INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1, 'Задание Канретада', 'C возвращением из мира смерти, герой. Было время, когда ты с гордостью $gстоял:стояла: среди своих собратьев, и меч твой был остер. Ныне же ты – лишь тень прошлого. Но встань передо мной, и я воскрешу легендарного рыцаря, которым ты некогда $gбыл:была:.$B$BЯ восполню твои силы, восстановлю оружие и подготовлю тебя к новым подвигам.', 'Поговорите с Канретадом, чтобы восстановить ваши таланты, оружие и средство передвижения.', '', NULL, NULL, NULL, 'Вспомнить свои таланты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2, 'Коготь гиппогрифа Острокогтя', 'Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы. Сенани Громовое Сердце на заставе Расщепленного Дерева несомненно пожелает увидеть этот трофей – доказательство ваших деяний.', 'Принесите коготь гиппогрифа Острокогтя Сенани Громовое Сердце на заставу Расщепленного Дерева в Ясеневом лесу.', 'Очень впечатляет, $N... коготь Острокогтя непросто добыть! Тебе везет в охоте!$B$BОстрый Удар давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщепленного Древа. Несомненно, скоро разойдется весть, что именно ты прикончил чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!', 'Да, могучий $C, я почувствовала твое приближение. Уверена, тебе есть что еще рассказать мне о твоей охоте.', NULL, NULL, 'Коготь гиппогрифа Острокогтя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5, 'Урчащий живот Трясунчика', 'Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за нее хорошо заплачу.$B$BУстрой мне пир, и не пожалеешь.$B$BГоворят, что шеф-повар Груаль в таверне \"Алый ворон\" делает превосходные темные пирожки с крабами...', 'Поговорите с шеф-поваром Груалем.', 'Значит, тебе нужны пирожки с крабами? Что ж, могу испечь...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6, 'Награда за голову Гаррика Тихокрада', 'Гаррик Тихокрад – головорез, который уже много недель не дает покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесешь мне голову этого негодяя – получишь награду!$B$BНо будь $gосторожен:осторожна:, $N. Гаррик собрал разбойничью шайку. До него непросто будет добраться.', 'Убейте Гаррика Тихокрада и принесите его голову заместителю судьи Виллему в Аббатство Североземья.', 'Ха! Ты его прикончил! Ты оказал большую услугу Элвину и заслуживаешь хорошей награды!', 'Ты нашел шайку Гаррика? Неужто мы, наконец, избавились от этого бандита?', NULL, NULL, 'Голова Гаррика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7, 'Нападение на лагерь кобольдов', 'Первое твое задание, $N, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.', 'Уничтожьте 8 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.', 'Славная работа. Эти кобольды – воры и трусы, но когда их много, они становятся опасны. А людям Штормграда лишняя угроза не нужна.$B$BПримите мою благодарность за хорошую работу.', 'Как прошла охота, $N? Ты обнаружил и уничтожил этих вредителей?', NULL, NULL, 'Кобольд-вредитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8, 'Выгодная сделка', 'Эй, $gприятель:подруга:! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! $B$BУ меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-ее-там. Неважно, какая у нее там фамилия! $B$BДа и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и $gсам:сама: сможешь там отдохнуть, если захочешь. По крайней мере, ты $gдолжен:должна: туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.', 'Доставьте ненадписанное письмо Ренни – хозяйке таверны в Тирисфальских лесах.', 'Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает... $B$BЧто? Слишком фальшивлю? Не купился?$B$BНу так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда! $B$BВозвращайся, когда будет что потратить... бродяга. $B$BИ вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости.', 'А? Что? Что это? $B$BОтрекшиеся... на аппетит они явно не жалуются. Располагайтесь как дома... да, дайте покой своим усталым косточкам. Меня зовут Ренни, если что-то понадобится – я к вашим услугам.', NULL, NULL, 'Ненадписанное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9, 'Поля смерти', 'Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех. Только не меня! Однако угодья захватили големы – дозорные полей.$B$BЕсли вы готовы поработать, я попросил бы вас пойти и убить 20 таких големов. Возвращайтесь за оплатой, когда все будет сделано. Когда расправитесь с теми, что обитают на моем поле, зачистите поля и моих соседей тоже.', 'Убейте 20 дозорных полей по просьбе фермера Сальдена.', 'Отличная работа, дружище. Вы полностью отработали свою плату. Кто знает, может быть, Западный Край снова расцветет.', 'А, я вижу, вы вернулись! Надеюсь, вы упорно работали над тем, чтобы очистить наши угодья от дозорных полей. Двадцати еще не набралось?', NULL, NULL, 'Дозорный полей убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10, 'Спасение Холстомера', 'Ох, это ужасно! Я послал моего лучшего помощника, младшего геодезиста Холстомера в пустыню, на юго-восток отсюда. Именно там располагается Зияющая бездна. Вот, а теперь он пропал, и в последнем докладе шла речь о странных насекомых. Неужели они наводнили уже два основных района пустыни?$B$BПрошу тебя, доберись до Зияющей бездны и поищи там Холстомера! Его... или хотя бы оборудование. Боюсь, больше от бедняги ничего и не осталось.', 'Узнайте, что стало с младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск.', 'Юный Холстомер был хорошим гоблином. Будем надеяться, что его кончина не напрасна, и собранные перед смертью сведения не пропали даром.$B$BПохоже, от этих жуков надо ждать неприятностей. Они слишком хитры, но все исследования указывают на то, что эти твари находятся под влиянием третьей стороны! Коли так, беда грозит не только Прибамбасску, но и всей пустыне!', 'Ну, что тебе удалось узнать? Похоже, ты только что из боя... Жив ли Холстомер?', NULL, NULL, 'Обозревательное устройство Холстомера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11, 'Награда за гноллов из стаи Речной Лапы', 'На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов.$B$BАрмия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов.', 'Принесите 8 раскрашенных поручей гноллов в казармы заместителю судьи Рейнеру.', 'О, вижу, ты слов на ветер не бросаешь! Прими нашу благодарность, $N.', 'Приветствую, $N. Ну, как идет война с гноллами?', NULL, NULL, 'Раскрашенные поручи гнолла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12, 'Народное ополчение', 'У народного ополчения есть лишь одна цель: защитить земли Западного края и вернуть в них мир. К сожалению, приходится это делать путем кровопролития.$B$BОдин из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику. У меня есть сообщения, что звероловов Братства замечали около рудника Янго к северо-западу отсюда, а также неподалеку от фермы Мольсена и тыквенной фермы Хмуроброва. Если ты хочешь присоединиться к ополчению, убей 15 звероловов и 15 контрабандистов из Братства Справедливости, а затем возвращайся ко мне.', 'Убейте 15 звероловов и 15 контрабандистов из Братства Справедливости и вернитесь к Гриану Камнегриву.', 'Отличная работа, $N. Мой разведчик был свидетелем твои доблестных деяний. Пока что с тобой очень приятно иметь дело.', 'Быть может, я недостаточно ясно выразился? Прошу прощения. Чтобы доказать, что ты достоин вступить в ряды народного ополчения и служить Свету, ты должен убить 15 звероловов и 15 контрабандистов из Братства Справедливости и вернуться ко мне, когда это будет сделано.', NULL, NULL, 'Зверолов из Братства Справедливости убито', 'Контрабандист из Братства Справедливости убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13, 'Народное ополчение', 'Шайка злобных погромщиков из Братства Справедливости разбойничает близ прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, $N, и пусть весь Западный край узнает о силе Света.$B$BЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты $gубил:убила: 15 погромщиков и 15 мошенников из Братства Справедливости.', 'Убейте 15 погромщиков и 15 мошенников из Братства Справедливости и вернитесь к Гриану Камнегриву на Сторожевой холм.', 'Ваша значимость для народного ополчения была подкреплена вашими смелыми действиями.', 'Нет времени на разговоры, $N. Погромщики из братства Справедливости лишают жителей Западного края мира и процветания, которого они заслуживают. Удостоверься, что ты убил как минимум 15 погромщиков и 15 мошенников. Это послужит остальным ясным намеком на то, что разбою здесь места нет.', NULL, NULL, 'Погромщик из Братства Справедливости убито', 'Мошенник из Братства Справедливости убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14, 'Народное ополчение', 'Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого Братства грабят и разоряют деревни вплоть до южной границы Западного края. Мы считаем, что они скрываются в холмах Разбойничьих Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения.', 'Убейте 15 разбойников, 5 налетчиков и 5 кастетчиков из Братства Справедливости. Вернитесь к Гриану Камнегриву на Сторожевой холм.', 'Я покинул разоренные земли Лордерона, вернувшись на свою родину... и застал ее в столь же ужасном состоянии. Но для Западного Края еще есть надежда. Проявленная тобой доблесть доказала, что ты с честью служишь нашему делу. С огромной гордостью я принимаю тебя в ряды народного ополчения. Да воссияет над тобой Свет!', NULL, NULL, NULL, 'Проходимец из Братства Справедливости убито', 'Ищейка из Братства Справедливости убито', 'Кастетник из Братства Справедливости убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (15, 'Разведка в руднике Горного эха', '$N, мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали. Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда.$B$BОтправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много... Убей-ка десяток, посмотри, сколько еще осталось, и доложи мне.', 'Уничтожьте 8 кобольдов-рабочих и вернитесь к маршалу Макбрайду. ', 'Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведет. Вот, это твоя награда. Когда будешь готов, приходи ко мне. Буду рад, если ты согласишься предпринять еще одну вылазку…', 'Ты был в руднике? Готов доложить об успехах?', NULL, NULL, 'Кобольд-рабочий убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (16, 'Жажда Джерарда', '', '', 'Благодарю, $N! Решишь еще со мной поторговаться – заходи.', NULL, NULL, NULL, 'Освежающая ключевая вода', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (17, 'В Ульдаман за реактивом', 'Мне рассказали о недавно открытом грибе-малиновике. Этот гриб растет целыми скоплениями на раскопках Ульдамана. Его можно отыскать в старых туннелях и глубинных, неизведанных зонах. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься.$B$BОтыщи эти грибы и принеси мне дюжину. Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнешь.$B$BЕсли выполнишь мое поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!', 'Принесите 12 грибов-малиновиков Гхаку Целителю в Телcамар.', 'Молодец, $N, ты снова показал, на что способен! Эти грибы мне очень пригодятся для исследований!$B$BА теперь, как я и обещал, можешь насладиться вкусом одного из моих восстановительных составов из личных запасов...$B$BЕсли ты тоже увлекаешься алхимией, мы можем вдобавок поговорить и о других делах. В любом случае, благодарю за помощь!', 'Ты принес грибы-малиновики, которые нужны мне для работы? Нет грибов – нет награды!', NULL, NULL, 'Гриб-малиновик', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (18, 'Братство воров', 'Тут возле Североземья недавно новая воровская шайка завелась. Зовут себя Братством Справедливости. Видели их за рекой, на востоке.$B$BНе знаю, что у них на уме, но наверняка ничего хорошего! Принеси мне их банданы, и в награду получишь оружие.', 'Принесите 8 красных холщовых бандан заместителю судьи Виллему к Аббатству Североземья.', 'Ага, вижу, ты вернулся не с пустыми руками. Армия Штормграда ценит твою помощь.', 'Ну, добыл мне банданы?', NULL, NULL, 'Красная холщовая бандана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (19, 'Тарил\'зун', 'Вестники и отступники из клана Черной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи. Их предводитель – орк по имени Тарил\'зун. Он уже натворил достаточно дел. Принеси мне его голову!', 'Принесите маршалу Маррису в Красногорье голову Тарил\'зуна. ', 'Тарил\'зун был жестоким и коварным орком. Ты молодчина – я знаю, справиться с ним было нелегко. Вот твоя награда, $N.', 'Орки Черной горы по-прежнему не дают нам покоя. Избавь нас хотя бы от Тарил\'зуна!', NULL, NULL, 'Голова Тарил\'зуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (20, 'Угроза Черной горы', 'К нам явились орки из клана Черной горы из Пылающих степей и захватили крепость Каменной Стражи. Они грабят области к северу от Озер, и жители тех земель бежали в город, набились в него, словно сельди в бочку.$B$BПомоги Приозерью избавиться от этой угрозы. Перебей орков и принеси в доказательство десять иззубренных топоров.$B$BХотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья. Если встретишь их – убивай без колебаний.', 'Принесите маршалу Маррису в Приозерье 10 иссеченных в бою топоров. ', 'Что ж, чем меньше орков, тем лучше. Большое тебе спасибо.', 'Ты уже охотился на орков, $N? Если так, покажи мне...', NULL, NULL, 'Иссеченный в бою топор', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (21, 'Схватка у рудника Горного эха', 'Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку. Возвращайся на рудник и помоги очистить его от кобольдов. $B$BВремя дорого, $N. Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье.', 'Уничтожьте 8 кобольдов-рудокопов и вернитесь к маршалу Макбрайду. ', 'Ты снова заслужил мою похвалу и благодарность армии Штормграда. В руднике еще достаточно кобольдов, но я отправлю других новобранцев бороться с ними. Для тебя имеются другие поручения.', 'Я знаю, это поганая работа, $N, но ее необходимо выполнить ради безопасности Североземья. Ты готов предоставить отчет?', NULL, NULL, 'Кобольд-рудокоп убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (22, 'Рецепт пирожка из печени жутеклыка', 'Лук очищен. Чеснок раздавлен. Розмарин измельчен. Основа выпечена. Укроп нарезан. Соус вымешан до гладкости. Все, что мне еще нужно для моего знаменитого пирога – это 8 кусков печени кровоклыка!', 'Принесите Сальме Сальден 8 кусков печени кровоклыка, чтобы она могла испечь пирог.', 'Замечательные куски, $N! Большое тебе спасибо! Мы с фермером Сальденом устроим сегодня настоящий праздник. А это – для тебя, за труды. У тебя ведь не было мысли, что $C вроде тебя останется без угощения, а?', 'Все, что мне еще нужно для моего знаменитого пирога – это восемь кусков печени жутеклыка!', NULL, NULL, 'Печень кровоклыка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (23, 'Лапа Топтыжня', 'Вот лапа могучего медведя Топтыжня – ваш трофей этого этапа охоты. На лапе есть маленький знак – месяц. Смысл этого знака покрыт тайной.$B$BЭту лапу надо отнести Сенани Громовое Сердце на заставу Расщепленного Дерева, чтобы доказать, что вы одолели могучую тварь, тем самым завершив этот этап охоты.', 'Принесите лапу Топтыжня Сенани Громовое Сердце на заставу Расщепленного Дерева в Ясеневом лесу.', 'О, лапа Топтыжня! Твоя навыки меня впечатлили, $C. Говорят, он многих убил. Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу. Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях. Убить такую тварь – истинное испытание воли и решимости.$B$BТвои предки гордились бы тобой!', 'Ах – $N – я только что подумала о тебе! Ну, как прошла охота?', NULL, NULL, 'Лапа Топтыжня (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24, 'Голова Тенумбры', 'Некогда стремительный Тенумбра лежит у ваших ног. Вы победили. Голова убитого ночного саблезуба – достойный трофей этой схватки в ходе охоты. Сенани Громовое Сердце на заставе Расщепленного Дерева захочет увидеть ваш трофей и наградить вас за этот этап охоты.', 'Принесите голову Тенумбры Сенани Громовое Сердце на заставу Расщепленного Дерева в Ясеневом лесу.', 'Победа в Ашенвальской охоте! Отлично! Голова Тенумбры, вне всякого сомнения, – достойный трофей столь впечатляющей схватки.$B$BДикий нрав Тенумбры был хорошо известен на заставе. Из-за этого чудовища любое путешествие от Зорамского взморья на запад, особенно пешком, было рискованным. Благодаря тебе этой угрозы больше не существует.', 'Еще раз привествую тебя, $N! Ты пришел показать мне свои охотничьи трофеи?', NULL, NULL, 'Голова Тенумбры (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (25, 'Остановка у Каменного Когтя', 'Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя?$B$BСообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на все, что только подойдет поближе... то есть, на все, что на дороге. Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса.$B$BНу, $gготов:готова: принести пользу?', 'Истребите 12 злобных элементалей воды на озере Мистраль, что к востоку от Туннеля Когтя и к юго-западу от заставы Расщепленного Дерева.Исследуйте беседку на озере Мистраль, из которой открывается вид на соседний форт Альянса. Вернитесь к Мастоку Райльшипу на заставу Расщепленного Дерева в Ясеневом лесу.', 'Да я слышал, как что-то пролетело по озеру подобно пыльной буре Степей. По звуку мы сможем найти пригодный раблюдательный пункт, чтобы присматривать за нашими друзьями из Альянса. Да, только если будем сидеть тихо...$B$BПохоже, от тебя тут больше толку не будет – сообщение между здешними местами и Каменным Когтем налажено. Возьми вот это – заслужил.', NULL, NULL, NULL, 'Злобный элементаль воды убито', 'Исследовать локацию', 'Исследуйте беседку на озере Мистраль, из которой открывается вид на соседний форт Альянса.', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (26, 'Необходимый урок', '$N, Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь $gзнаменитым защитником:знаменитой защитницей: природы.$B$BПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.', 'Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.', 'Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.$B$BТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.$B$BГотовься – время испытания пришло.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (27, 'Необходимый урок', '$N, Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь $gзнаменитым защитником:знаменитой защитницей: природы.$B$BПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.', 'Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.', 'Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.$B$BТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.$B$BГотовься – время испытания пришло.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (28, 'Испытание озера', 'Вот твое первое испытание – исследуй глубины озера Элуны и найди безделушку святилища. Она быстро разрушается, так что не медля отнеси ее к святилищу Ремула. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны.$B$BНа все испытание тебе дается ограниченное количество времени, и возможно, тебе придется соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха.$B$BУдачи тебе, $N.', 'Найдите безделушку святилища в озере Элуны и отнесите ее в святилище Ремула на северо-западе Лунной поляны. Оказавшись там, воспользуйтесь безделушкой.Потом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание.', 'Что же, сдается мне, еще один друид успешно прошел Испытание Озера! Хвалю тебя, мой юный друг.$B$BКак я уже сказала, мое имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту.', 'Для завершения Испытания озера тебе нужно использовать безделушку святилища в пределах этого места. До тех пор твое испытание считается незавершенным, и ты рискуешь провалить его.', NULL, NULL, 'Пройдите испытания Озера.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (29, 'Испытание озера', 'Вот твое первое испытание – исследуй глубины озера Элуны и найди безделушку святилища. Она быстро разрушается, так что не медля отнеси ее к святилищу Ремула. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны.$B$BНа все испытание тебе дается ограниченное количество времени, и возможно, тебе придется соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха.$B$BУдачи тебе, $N.', 'Найдите безделушку святилища в озере Элуны и отнесите ее в святилище Ремула на северо-западе Лунной поляны. Оказавшись там, воспользуйтесь безделушкой.Потом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание.', 'Что же, сдается мне, еще один друид успешно прошел Испытание Озера! Хвалю тебя, мой юный друг.$B$BКак я уже сказала, мое имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту.', 'Для завершения Испытания озера тебе нужно использовать безделушку святилища в пределах этого места. До тех пор твое испытание считается незавершенным, и ты рискуешь провалить его.', NULL, NULL, 'Пройдите испытания Озера.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (30, 'Испытание Морского Льва', 'Вот твое второе испытание – тебе понадобятся две половинки подвески морского льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика.$B$BПоговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звезд.', 'Найдите половинку подвески ловкости водяного облика и половинку подвески выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.Сложите из половинок подвеску морского льва. Для этого вам надо находиться рядом со святилищем Ремула.Отнесите собранную подвеску Дендриту Блеску Звезд в деревню Ночная Гавань, что на Лунной поляне.', 'Ты прошел испытание Морского Льва, $N. Прими мои поздравления.$B$BКаждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва.$B$BЗапомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик.', 'Ты уже собрал подвеску, $N? Дай посмотреть. Если тебе нужна помощь, чтобы соединить половинки, обратись к местным жителям. Так ты не только узнаешь то, что тебе надо, но и познакомишься с этой чудесной, благословенной поляной.', NULL, NULL, 'Подвеска Морского Льва', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (31, 'Водный облик', 'Ты $gзавершил:завершила: обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Тюраку Руническому Тотему в Громовой Утес. Покажи ему свою подвеску и докажи, что ты $gготов:готова: усвоить его уроки. Он завершит твое обучение, благодаря которому ты станешь $gединым:единой: с водой.$B$BДоброго тебе пути, юный друид. Мы еще встретимся.', 'Возвращайтесь в Громовой Утес и покажите Тюраку Руническому Тотему подвеску Морского Льва.', 'Великолепно, $N. Твои предки могут гордиться твоими успехами! Ты готов прининять водный облик, и я с радостью научу тебя этому.$B$BПрими также эту вещицу в знак признания твоих успехов в двух испытаниях. Надеюсь, тебе будет приятно присоединить ее к своему снаряжению защитника Природы и хранителя равновесия.', 'До меня дошли слухи о твоем триумфальном возвращении в Громовой Утес, но я все равно хочу увидеть доказательства того, что ты усвоил уроки Лунной поляны, прежде чем стану учить тебя принимать водный облик.$B$BЕсть ли у тебя подвеска Морского Льва?', NULL, NULL, 'Подвеска Морского Льва (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (32, 'Появление силитидов', 'Вот твой отчет. Прошу тебя, отнеси его кому-нибудь, сведущему в такого рода вопросах.$B$BЯ слышал про ученого-тролля по имени Зилзибин Барабанный Бой. Он посвятил много времени изучению форм жизни, встречающихся лишь в Азероте; он и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к нему. Нам любая помощь не помешает.$B$BЕго дом находится во втором ряду Волока в Оргриммаре.', 'Отнесите отчет Зилзибину Барабанному Бою в Оргриммар.', 'Что до твоего отчета... да, я уже встречался с этими тварями. Рудознатец правильно поступил, отправив это письмо и тебя ко мне.$B$BЭти существа мигом пожрут всю пустыню Танарис; они представляют собой одну из величайших опасностей, с которой только можно столкнуться. Знакомься, $N – это силитиды. Так зовутся странные насекомые, которые служат величайшему злу, грозящему и Орде, и Альянсу.$B$BЖаль, что нам не хватило ума понять это раньше.', 'Прости, мы не знакомы... Но судя по всему, тебе приходилось слышать обо мне. Чем могу помочь? Ты мне что-то принес?', NULL, NULL, 'Отчет о наблюдении за насекомыми (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (33, 'Волки на границе', 'Видимо, эта волчья болезнь не пройдет сама собой. Каждый день количество зараженных волков все возрастает. Мне больно думать об уничтожении детей природы, но мы должны убить этих заболевших молодых волков прежде, чем начнется эпидемия.$B$BУбей зараженных молодых волков в долине и принеси мне их шкуры в доказательство того, что дело сделано.', 'Принесите 8 шкур зараженных волков Игану Меховщику к Аббатству Североземья.', 'Ну, ты на славу постарался! Прямо не терпится поджарить волчатинки...$B$BУ меня есть кое-что интересное для тебя – выбирай!', 'Эй, $N! Я уж проголодался... Ты принес волчатину?', NULL, NULL, 'Шкура зараженного волка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (34, 'Незваный гость', 'Мой сад снова разграблен и вытоптан. И я знаю, кто это сделал! Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом.$B$BТеперь мне долго не удастся посадить нарциссы. Они загублены! И во всем виноват мерзкий кабан. Положи конец этому паразиту! Принеси мне его клык, и я с удовольствием вознагражу тебя. Говорят, он пасется в полях на юго-западе от Приозерья, но порой заходит и сюда, в мой сад.', 'Убейте Грубобрюха. Принесите Марти Джанроз клык вепря.', 'Наконец-то моему саду ничего не грозит! Спасибо тебе, $N, ты оказал мне большую услугу. Теперь мой сад расцветет с небывалой пышностью!', 'Грубобрюх все еще бесчинствует или ты уже избавил Приозерье от этого паразита?', NULL, NULL, 'Клык кабана Грубобрюха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (35, 'Новые заботы', 'Если ты думаешь, что слухи о мурлоках могут оказаться правдой, отправляйся к восточному мосту Элвиннского леса и поговори со стражником Томасом. Он уже неделю несет стражу у моста и должен знать, что там происходит на самом деле.$B$BПринеси мне его отчет.', 'Поговорите со стражником Томасом. ', 'Да, это правда: мурлоки поселились в реках и на их берегах в западной части леса. Мы не знаем, почему они пришли сюда, но их следует остерегаться: они агрессивны и довольно умны.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (36, 'Похлебка Западного края', 'Никогда я не думала, что наступит день, когда я покину ферму. Но поля кишат разбойниками, и для нас теперь тут слишком опасно. Как только фермер Хмуробров починит повозку, мы отправимся в путь.$B$BМожет быть, ты окажешь мне услугу? Я напишу рецепт похлебки Западного края, а ты отнесешь его Сальме Сальден вон на ту ферму – она сразу за развилкой дороги.', 'Отнесите Сальме Сальден рецепт похлебки Западного края. ', 'Эта Верна всегда была такой милой девушкой. Нам будет ее не хватать здесь, в Западном Крае, но, только между нами, в душе она – городская жительница, и Штормград – местечко как раз для нее. Ладно, хватит сплетничать! Начнем же готовить похлебку Западного Края!', 'Я буду очень скучать по Верне Хмуробров... Скажи-ка, ты не встретил ее по пути сюда?', NULL, NULL, 'Рецепт Верны: похлебка Западного края (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (37, 'Пропавшие стражи', 'Несколько дней назад мы отправили на обследование берегов реки двух наших стражей, Рольфа и Малакаи; ни один из них до сих пор не вернулся. Чтобы составить полный отчет, мне нужно выяснить, что с ними случилось.$B$BОтправляйся на север вдоль реки и разыщи стражей... или хотя бы их останки.', 'Отправляйтесь на север по реке и отыщите следы пропавших стражников – Рольфа и Малакаи.', 'Хотя на трупе мало что осталось, рядом с ним оказался медальон с надписью \"Камень пехотинца Малакаи\".', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (38, 'Похлебка Западного края', 'Помоги мне сварить похлебку Западного края! Мне нужны для нее следующие ингредиенты:$B$B3 куска жилистого мяса стервятника$B3 рыла жутеклыка$B3 глаза мурлока$B3 окры', 'Принесите Сальме Сальден 3 куска жилистого мяса стервятника, 3 рыла кровоклыка, 3 глаза мурлока и 3 окры.', 'Окра отлично загустит бульон! А теперь мы просто добавим жилистого мяса стервятника, несколько глаз мурлока и эти вкуснейшие рыла жутеклыка. И вот все готово! За оказанную помощь, $N, я предлагаю тебе отведать первую порцию похлебки Западного Края.', 'Возвращайся ко мне, когда соберешь 3 куска жилистого мяса стервятника, 3 рыла жутеклыка, 3 глаза мурлока и 3 окры.', NULL, NULL, 'Жилистое мясо стервятника', 'Глаз мурлока', 'Рыло кровоклыка', 'Окра');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (39, 'Донесение Томаса', 'Нужно сообщить маршалу Дугхану о смерти Малакаи и Рольфа. Наши войска на востоке Элвиннского леса не смогут справиться с мурлоками.$B$BЯ знаю, лишних солдат у нас нет, но, может, Дугхан пришлет хоть какую-то помощь...', 'Доставьте донесение в Златоземье маршалу Дугхану. ', 'Да, вести невеселые... Людей у нас и так немного, а теперь, когда мурлоки прикончили Рольфа и Малакаи, будет и вовсе несладко.$B$BЕсли положение не изменится к лучшему, боюсь, к концу недели бои будут идти уже в Златоземье...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (40, 'Водяная нечисть', '$N, в Элвиннском лесу появилась новая напасть. Мурлоки поднялись вверх по рекам в восточной части леса, они распугивают рыбу и нападают на мирных жителей.$B$BЯ предупреждал маршала Дугхана, но его больше беспокоит нашествие гноллов и бандитов. Мурлоков он вообще не принимает в расчет. $B$BЯ прошу тебя, $N, поговори с Дугханом и постарайся убедить его послать отряд на восток!', 'Реми Повторюх просит вас найти в Златоземье маршала Дугхана и поговорить с ним.', 'Да, верно, я говорил с Реми. Поверь, я очень высоко ценю его как торговца, но все отчеты о появлении мурлоков на востоке крайне недостоверны.$B$BЯ понимаю твою тревогу, но пока не будут получены надежные сведения о мурлоках, никаких войск на восток я посылать не стану.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (45, 'Судьба Рольфа', 'При осмотре местности были обнаружены запутанные следы, ведущие на восток вдоль берега Озера Каменных Столбов. В отдалении видно поселение мурлоков.$B$BВозможно, именно здесь и окончил свой путь Рольф...', 'Обыщите поселение мурлоков и найдите Рольфа – или подтверждение его смерти.', 'На шее трупа вы находите медальон с надписью \"Пехотинец Рольф Хартфорд\".', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (46, 'Награда за мурлоков', 'Армия Штормграда назначила награду за мурлоков – скрытней и добытчиков. Убей их и принеси мне их плавники: армия хорошо за это заплатит.$B$BМурлоки построили селение на Озере Каменных Столбов – это к северу отсюда; еще одно селение расположено на юге – там, где русло реки разделяется надвое.', 'Принесите 8 плавников мурлоков к восточному мосту Элвиннского леса и отдайте их стражнику Томасу.', 'Что у нас тут? Плавники? Отлично! Маршал Дугхан обеспокоен мурлоками, поселившимися на востоке леса. Он будет рад узнать, что ситуация под контролем.$B$BТвоя помощь в этом деле была просто неоценимой.', 'Ну что, $N, как идет охота?', NULL, NULL, 'Рваный плавник мурлока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (47, 'Золотая пыль', 'Кобольды в этих местах иногда носят с собой Золотую пыль. Достань мне этой пыли, и я дам за нее лучшую цену в городе! Лучшую цену в городе!$B$BКобольдов можно найти на юге, на руднике Подземных глубин, или на северо-востоке, рядом с Яшмовой шахтой.', 'Принесите 10 порций Золотой пыли в Златоземье Реми Повторюху. Золотую пыль можно добыть у кобольдов в Элвиннском лесу.', 'Благодарю за пыль, $N. Вот твои деньги... А вот и маленький подарочек от моих друзей. Возможно, он тебе пригодится... Да, пригодится.', 'Эй! Ну как, есть Золотая пыль... пыль?', NULL, NULL, 'Золотая пыль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (48, 'Янтарное сладкое', 'Где-то в южных краях, там, где вьется лоза$BЕсть колодец с водой, что чиста как слеза.$BБьет священной воды одинокий ручей,$BБудь же другом, скорей, отправляйся за ней!', 'Принесите Мрачнобуху Громовару воду святого источника. ', 'И-ик! Хо-хо!', 'И-ик! Хо-хо! Хочешь выступление на бис?$B$BГде-то в южных краях, там, где вьется лоза$BЕсть колодец с водой, что чиста как слеза.$BБьет священной воды одинокий ручей,$BБудь же другом, скорей, отправляйся за ней!', NULL, NULL, 'Вода святого источника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (49, 'Янтарное сладкое', 'Как прекрасна янтарная россыпь зерна!$BСловно жаром костра пропиталась она.$BЧтобы вышел наш пенный напиток хорош,$BТы ячмень мне добудь, кукурузу и рожь.', 'Принесите Мрачнобуху Громовару мешок ячменя, мешок ржи и мешок кукурузы.', 'И-ик! Хо-хо!', 'На бис? Легко!$B$BКак прекрасна янтарная россыпь зерна!$BСловно жаром костра пропиталась она.$BЧтобы вышел наш пенный напиток хорош,$BТы ячмень мне добудь, кукурузу и рожь.', NULL, NULL, 'Мешок ячменя', 'Мешок кукурузы', 'Мешок ржи', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (50, 'Янтарное сладкое', 'Прочь дремота и лень! Встану я поутру,$BЗамешаю зерно и в сусло разотру,$BСплавить куб перегонный – и будет добро!$BТолько истинных свойств подойдет серебро.', 'Принесите Мрачнобуху Громовару истинное серебро.', 'И-ик! Хо-хо!', 'Спеть на бис?С удовольствием, друг! Прочь дремота и лень! Встану я поутру,$BЗамешаю зерно и в сусло разотру,$BСплавить куб перегонный - и будет добро!$BТолько истинных свойств подойдет серебро.', NULL, NULL, 'Слиток истинного серебра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (51, 'Янтарное сладкое', 'Хочешь, друг мой, на брагу взглянуть? - так и быть!$BНам осталось лишь только ее процедить.$BВетвь смоковницы даст нам немного угля,$BБудет хмельный напиток светлей янтаря!', 'Принесите Мрачнобуху Громовару ветку смоковницы. ', 'И-ик! Хо-хо!', 'Повторить? Для тебя – что угодно!$B$BХочешь, друг мой, на брагу взглянуть? - так и быть!$BНам осталось лишь только ее процедить.$BВетвь смоковницы даст нам немного угля,$BБудет хмельный напиток светлей янтаря!', NULL, NULL, 'Ветка смоковницы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (52, 'Защита границы', 'Приветствую, $N. Чем дальше от Златоземья, тем агрессивнее становятся дикие звери: на Лесопилку Восточной долины постоянно нападают волки и медведи.$B$BХочешь нам помочь?', 'Убейте 8 лесных хищников и 5 молодых лесных медведей. Затем вернитесь к стражнику Томасу у восточного моста Элвиннского леса.', 'Я так тебе благодарен, $N!.. Похоже, в этом лесу поселилось что-то, что гонит зверей прямо на нас.$B$BЧто бы там ни было, хотел бы я, чтобы оно не покидало леса...', 'Надеюсь, волки и медведи уже перебиты?', NULL, NULL, 'Лесной хищник убито', 'Молодой лесной медведь убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (53, 'Янтарное сладкое', 'Вот медовая брага готова вполне,$BСловно солнце играет в ее глубине!$BМы в дубовый бочонок ее разольем,$BА потом насладимся напитком вдвоем!', 'Принесите Мрачнобуху Громовару вязанку обуглившихся дубовых поленьев.', 'Углем отфильтровано, вызрело в бочке,$BВосторг, упоение в каждом глоточке.$BПоднимем же тост за тебя, за меня$BИ за сладкий напиток цвета янтаря!', 'Конечно, ради тебя я спою еще раз!$B$BВот медовая брага готова вполне,$BСловно солнце играет в ее глубине!$BМы в дубовый бочонок ее разольем,$BА потом насладимся напитком вдвоем!', NULL, NULL, 'Вязанка обуглившихся дубовых поленьев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (54, 'Донесение в Златоземье', '$N, ты – $c, чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса.$B$BЕсли ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье. Златоземье находится на южном тракте, за пограничными воротами.', 'Отнесите документы маршала Макбрайда маршалу Дугхану в Златоземье. ', 'Что же, тут говорится, что ты был назначен полномочным представителем маршалов Штормграда. Прими мои поздравления.$B$BИ удачи тебе... Охранять Элвинн – это непростая работа. Да еще когда большая часть армии занимается непонятно чем по приказу какого-то аристократишки!$B$BВ наши мрачные времена политика – дело темное...', 'У тебя сообщение от маршала Макбрайда? Североземье по сравнению с Элвиннским лесом – мирный сад, но мне любопытно, о чем пишет Макбрайд.$B$BДайте-ка мне бумаги...', NULL, NULL, 'Документы маршала Макбрайда (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (55, 'Морбент Скверн', 'Морбент Скверн прячется в своем доме на вершине холма на востоке, рядом с кладбищем Вороньего холма. Пора положить конец его бесчинствам в наших землях…$B$BПримени против него Проклятье Морбента, оно обратит в прах всю его защитную магию.$B$BУбей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, $gгерой:героиня: Сумеречного леса.', 'Примените Погибель Морбента против Морбента Скверна, убейте его и верните Погибель Морбента в лагерь Свена.', 'Морбент Скверн убит. Темные всадники по-прежнему топчут наши земли, но все же мы одержали победу, хотя и неполную. Я надеялся на это вопреки всему.$B$BТы совершил невозможное, и легенды о тебе будут ходить во всему Сумеречному лесу.$B$BСтупай, $N. Быть может, судьба вновь приведет тебя ко мне...', 'Неужели Морбент Скверн повержен?!', NULL, NULL, 'Убейте Морбента Скверна', 'Погибель Морбента (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (56, 'Ночной Дозор', 'Я – командир Ночного дозора, и мой долг – охранять покой жителей Темнолесья. Солдаты Штормграда оставили свои посты, предоставив нас самим себе.$B$BЕсли ты $gготов:готова: на подвиги, помоги нам! Отправляйся в Застывшие сады на юге от Темнолесья и убей 8 скелетов-воинов и 8 магов-скелетов. Мы должны дать отпор нежити!', 'Убейте 8 скелетов-воинов и 6 магов-скелетов по просьбе командира Алтеи Чернодрев.', 'Великолепно, $N. За верную службу народу Темнолесья тебе полагается награда.', NULL, NULL, NULL, 'Скелет-воин убито', 'Маг-скелет убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (57, 'Ночной Дозор', '$N, я получила сведения о появлении нежити в наших лесах! Если ты не боишься, отправляйся на кладбище Вороньего холма и убей 15 скелетов-губителей и 15 ужасных скелетов. Также говорят, что скелеты появились и к югу от Темнолесья, на Безмятежном кладбище. Мы должны изгнать нежить из Сумеречного леса!', 'Убейте 15 скелетов-губителей и 15 ужасных скелетов по просьбе командира Алтеи Чернодрев.', 'Народ Темнолесья благодарит тебя, $N. Ты доказал свою преданность Ночному дозору.', NULL, NULL, NULL, 'Скелет-губитель убито', 'Ужасный скелет убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (58, 'Ночной Дозор', 'Обстановка на Вороньем холме не улучшилась. Безопасность Темнолесья – в твоих руках, $N. У нас не хватает стражей для обеспечения безопасности города. Придется тебе снова отправиться на Вороний холм и уничтожить 20 распространителей чумы в восточном мавзолее.', 'Убейте 20 распространителей чумы в восточном мавзолее Вороньего холма по просьбе командира Алтеи Чернодрев.', 'Я благодарю тебя, $N, от лица народа Темнолесья и от себя, как главы Ночного дозора, за храбрость и преданность общему делу. Да озарит Свет твой путь!', NULL, NULL, NULL, 'Распространитель чумы убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (59, 'Броня из кожи и ткани', 'Твои хитроумие и доблесть должны быть вознаграждены. Я приготовил для тебя знак: он пригодится для какой-нибудь части доспехов. Отнеси его Саре Тимберлейн на Лесопилку Восточной долины: она изготовит для тебя броню, или что там тебе будет нужно. Мне хотелось бы надеяться, что новые доспехи помогут тебе, $N, в защите Элвиннского леса от врагов.$B$BЛесозаготовки находятся к востоку от сторожевого поста Томаса.', 'Отдайте Саре Тимберлейн знак брони Штормграда.', 'Ага, вот и знак! Благодарю. Можешь выбрать любой доспех, какой тебе нужен.$B$BЖелаю удачи, $C! Надеюсь, новый доспех тебе пригодится.', 'Армия Штормграда поручила мне снабжение солдат одеждой и доспехами.$B$BЕсли ты дашь мне знак брони, я буду рада помочь тебе.', NULL, NULL, 'Знак брони Штормграда (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (60, 'Свечи кобольдов', 'Приветствую тебя, $gдобрый путник:прекрасная госпожа:! Не найдется ли у тебя свободной минутки?$B$BМы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи. Воск нужен, понимаешь? Я вот и думаю: может, ты мне поможешь?$B$BСвечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке... Может, прогуляешься туда и раздобудешь для меня свечи?', 'Принесите 8 больших свечей в Златоземье Вильяму Песту. ', 'Ну что, пришлось попотеть? Спасибо за свечи, $N! А вот и твоя награда...', 'Ну как, ты уже раздобыл свечи?', NULL, NULL, 'Большая свеча', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (61, 'Посылка в Штормград', 'В Штормграде мой брат Морган ждет посылки со свечами. У меня нет времени съездить туда самому, но если ты окажешь нам эту услугу, Морган хорошо тебе заплатит.$B$BВот, я тут упаковал свечи. А Моргана найти несложно, он работает в Торговом квартале Штормграда, в аптеке Песта.', 'Доставьте посылку Вильяма Моргану Песту в Торговый квартал Штормграда.', 'Вот плата за услугу... Кстати, можешь тут пока осмотреться: уверен, у нас наверняка найдется какое-нибудь зелье или безделушка, которые тебе пригодятся...', 'О, да это посылка от моего братца! Вот это здорово! Определенно, сегодня мой счастливый день!', NULL, NULL, 'Посылка Вильяма (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (62, 'Рудник Подземных глубин', 'Рудник в Североземье – не единственная головная боль. До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды.$B$BНужно исследовать рудник и подтвердить эти известия или опровергнуть их. Я буду ждать отчета. Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур.', 'Исследуйте рудник Подземных глубин и вернитесь в Златоземье с докладом для маршала Дугхана.', 'Скверные вести. И что дальше? Может, драконы?! Похоже, придется усилить охрану рудника. Спасибо тебе, $N. И подожди, не уходи... возможно, у меня найдется для тебя еще одно задание.', NULL, NULL, NULL, 'Исследовать локацию', 'Проведите разведку рудника Подземных глубин.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (63, 'Зов воды', 'На побережье Серебряного Бора, к западу от Гробницы, находится святилище, оскверненное чумой. Духи перестали разговаривать с нашим народом, и тебе предстоит победить воплощение воды и очистить купель.$B$BВозьми браслеты элементалей и остатки зелья Брин и помести их в жаровню. Этот ритуал позволит призвать чистого духа, с которым можно будет поговорить.$B$BПринеси мне доказательство того, что мое задание выполнено, и в награду я дам тебе тотем.', 'Одолейте оскверненное воплощение воды и поместите в жаровню Вечного источника в Серебряном бору его браслеты и оставшиеся капли чистейшей воды.', 'Вы помещаете браслеты в жаровню и выливаете в огонь оставшиеся капли зелья Брин. Пламя потрескивает, а вы начинаете проговаривать простые слова, которым вас обучила Ислен...', 'Жаровня все еще отражает окружающий свет, и, подойдя поближе, вы видите, что пламя тихонько колеблется.$B$BПохоже, эти места не так сильно затронула порча, и в целом, если не считать недостающих компонентов, жаровня готова к ритуалу призыва очищенного воплощения воды.', NULL, NULL, 'Браслеты оскверненного воплощения', 'Оставшиеся капли чистейшей воды (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (64, 'Забытая вещь', 'Это было ужасно! Верна разбудила меня, когда услышала гвалт в поле. Поля были полны хулиганья. Мы бежали в спешке, и я забыл взять с собой карманные часы. Папаша Верны подарил мне эти часы в день нашей с ней свадьбы, и мне прямо нехорошо от мысли, что ими могли завладеть те воры. Я оставил часы в доме, в платяном шкафу. Ищи тыквенную ферму к западу отсюда – ты ее не пропустишь. Если вернешь мне мои часы, я буду очень признателен!', 'Верните фермеру Хмуроброву его карманные часы, которые находятся в платяном шкафу в его доме на тыквенной ферме на западе.', 'Мои часы! Благодарю тебя, любезный господин!$B$BМы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности.', 'Боюсь, тебе так и не удалось достать мои часы?', NULL, NULL, 'Карманные часы Хмуроброва', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (65, 'Братство Справедливости', 'Группа негодяев, ответственных за то, что честные люди покидают Западный край, зовет себя Братством Справедливости. Мне нужно, чтобы ты $gпроник:проникла: в эту бандитскую шайку. Нам нужно узнать, кто ее главарь, и где они прячутся. В городе Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан.$B$BОтправляйся в Приозерье, что в Красногорье, к востоку от Элвиннского леса, и все разузнай.', 'Поговорите с Вилли в Приозерье по просьбе Гриана Камнегрива. ', 'Так значит, тебя послал Камнегрив? Что ж, я перед ним в долгу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (66, 'Легенда о Сталване', 'Вчера ночью меня охватил беспричинный ужас. Я почувствовала, что моя внучка Алисса оказалась в страшной опасности. Я разложила карты... и со стола на меня взглянула Смерть.$B$BПогрузившись в длительный и тяжкий транс, я сумела разгадать эту те$Nю тайну. Мне открылось имя: Сталван.$B$BОтыщи клерка в городской Ратуше и постарайся побольше разузнать об этом Сталване. Я опасаюсь за всех нас.', 'Найдите клерка Далтри в ратуше Темнолесья. ', 'А, так тебя послала мадам Ева...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (67, 'Легенда о Сталване', 'Сталван, значит? Дай-ка погляжу в журнал.$B$BСталван... Сталван... Ну-ка... А, вот он! У меня есть запись о некоем господине Сталване Мистмантле. Последний адрес – Лунореченская школа. Но это было так давно!$B$BОкажи любезность, дай знать, если выяснишь что-либо об этом типе. Записи должны содержаться в порядке.', 'Отправьтесь в Лунореченскую школу и сообщите все сведения о Сталване клерку Далтри.', 'Старый сундук со скрипом открывается...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (68, 'Легенда о Сталване', 'Вы находите в старом сундуке пыльное неотосланное письмо.', 'Отнесите пыльное неотосланное письмо клерку Далтри. ', 'Занятно. Значит, этот тип все же побывал в Луноречье. Странно, что письмо так и не доставили. Тем не менее я обновлю записи в журнале.', 'А, я тебя помню. Это ты спрашивал насчет Сталвана. Удалось его отыскать?', NULL, NULL, 'Пыльное неотосланное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (69, 'Легенда о Сталване', 'Боже мой! Сразу и не заметил. В журнале, точно под первым адресом Сталвана, написан еще один адрес, частично вычеркнутый. Похоже, он направлялся в таверну \"Гордость льва\" в Златоземье. Можешь поискать сведения там, $N.', 'Отправляйтесь в таверну \"Гордость льва\" и спросите, не слышал ли кто о Сталване.', 'Сталван? Знакомое имя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (70, 'Легенда о Сталване', 'Имя Сталван мне знакомо. А, вспомнил.$B$BМного лет назад ненастной ночью в трактир явился гонец, искавший убежища от непогоды. Около полуночи этот человек, бледный от страха, сбежал вниз по лестнице в пижаме и исчез.$B$BВторопях он оставил письма в сундуке на втором этаже. За ними он так и не вернулся. Осталось одно, от этого Сталвана. Адресовано оно в район каналов Штормграда. Можешь прочитать.', 'Возьмите недоставленное письмо Сталвана из сундука и доставьте его в район каналов Штормграда.', 'А ты не робкого десятка, раз решился доставить это.', 'Что это у тебя? Дай-ка посмотреть...', NULL, NULL, 'Недоставленное письмо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (71, 'Доклад для Томаса', 'Теперь, когда вы нашли оба медальона, отнесите их к мосту и отдайте стражнику Томасу: он должен узнать о смерти обоих стражей.', 'Отдайте стражнику Томасу у восточного моста Элвиннского леса медальоны стражей Рольфа и Малакаи.', 'Увы, $N, мои худшие опасения подтвердились. Мурлоки – это угроза, с которой придется считаться...', 'Приветствую, $N. Тебе удалось узнать, что случилось с Рольфом и Малакаи?', NULL, NULL, 'Медальоны Рольфа и Малакаи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (72, 'Легенда о Сталване', 'Мой отец был сторожем в этом поместье задолго до меня. Ему-то и пришлось вытирать кровь после того убийства. Но это к делу не относится.$B$BПоследние деньги треста Кременника давно иссякли. А теперь и последние семейные ценности отправляются прямиком на аукцион. Проклятые сборщики налогов!.. Пожалуй, если ты хочешь узнать побольше, можешь порыться в этом барахле. Кто знает, что тебе попадется.', 'Найдите улики в пожитках управляющего Фольсома. ', 'Вы медленно снимаете крышку с ящика...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (74, 'Легенда о Сталване', 'Внутри ящика вы находите много разных вещей: пыльные фамильные ценности, портрет, несколько охотничьих трофеев и старые книги. Уже на самом дне, под глиняной вазой, вам попадается страница, вырванная из дневника.', 'Отнесите страницу из дневника маршалу Хаггарду. ', 'Я едва разбираю буквы, но почерк напоминает мне о... Да, я видел что-то подобное до того, как мое зрение окончательно испортилось.', 'Что это у тебя? Не вижу. Зрение стало совсем никудышное. Дай-ка страницу сюда.', NULL, NULL, 'Вырванная из дневника страница (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (75, 'Легенда о Сталване', 'Когда я только приехал сюда, в сундуке на втором этаже лежала кипа пергаментов. Как-то раз я их просмотрел, но потом зрение стало не то, и я махнул на них рукой.$B$BОкажи любезность слепому старику, поищи в сундуке наверху что-нибудь, что сможет помочь тебе разузнать о Сталване. Мне кажется, там была выцветшая страница с интересными записями. Принеси ее мне, и я помогу тебе по мере сил.', 'Найдите в сундуке на втором этаже выцветшую страницу с записями. ', 'Это она!', 'Ну что, нашел страницу, о которой я говорил?', NULL, NULL, 'Выцветшая страница с записями', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (76, 'Яшмовая шахта', 'Благодаря тебе мы знаем, что рудник Подземных глубин заполонили кобольды. Но нам нужен разведчик, чтобы выяснить, что творится в Яшмовой шахте.$B$BОтправляйся туда и доложи мне, если обнаружишь кобольдов. Иди на восток по дороге, пока не доберешься до Башни Азоры, оттуда поверни на север, и у подножия гор отыщешь шахту.', 'Обследуйте Яш$Nю шахту и вернитесь с докладом в Златоземье к маршалу Дугхану.', 'Кобольды в Яшмовой шахте? Так это правда? Проклятье! Дела идут все хуже и хуже!$B$BКонечно, я благодарен тебе за информацию, , но лучше бы мы ошибались...', 'Приветствую тебя, $N. Какие новости? Что удалось обнаружить в Яшмовой шахте?', NULL, NULL, 'Исследовать локацию', 'Проведите разведку в Яшмовой шахте.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (77, 'Грязное дело', 'Я понял, про какую тару говорил Дран Дрофферс, у меня такая есть. Я помогу тебе разлить \"Медовую зыбь\" по бутылкам, чтобы этот грубиян, отец Мальтона, остался доволен. Но, разумеется, не бесплатно – взамен я хочу две бутылки \"Зыби\" для себя. Бутылки можно найти в ящиках на заброшенной базе Орды у Осклизлой скалы.$B$BДостать их будет нелегко, потому что в руинах кишмя кишат слизнюки и пиявки, и, говорят, у них там есть какой-то предводитель, что-то вроде верховного слизнюка. Но другого способа нет – придется тебе идти на базу и искать полные бутылки.', 'Найдите заброшенную базу Орды на Осклизлой скале и заберите из ящиков 10 бутылок \"Медовой зыби из Внутренних земель\".', 'Отличная работа, $N. Я очень рад, что напиток не испортился – нет ничего хуже на вкус, чем негодная медовуха.$B$BПогоди минутку, магии нужно время, чтобы подействовать на этот ценный груз. Хотя, на самом деле, никакой магии тут нет – я всего лишь перелью эту \"Медовую Зыбь\" в новые бутылки, и тогда этот напиток превратится в величайшее сокровище!$B$BНу вот, готово!', 'Я так понимаю, что ты принес мне бутылки с напитком, да?', NULL, NULL, '\"Медовая зыбь из Внутренних земель\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (78, 'Легенда о Сталване', 'Я знаю, кто мог бы тебе помочь. Когда я служил в страже Штормграда, мы порой пропускали по стаканчику в темнолесской таверне \"Алый ворон\". Ее хозяин Смиттс всегда был знатоком преданий. Покажи ему эту страницу, посмотрим, что он скажет.', 'Отнесите выцветшую страницу с записями хозяину таверны Смиттсу в Темнолесье, что в Сумеречном лесу.', 'Клянусь Светом! Я узнаю этот почерк!', 'Тебя послал маршал Хаггард? Что ж ты молчишь?$B$BЭх, старина Хаггард. Бедняга скоро совсем ослепнет. Впрочем, давай, покажи, что там у тебя.', NULL, NULL, 'Выцветшая страница с записями (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (79, 'Легенда о Сталване', 'Я много лет следил за легендами, ходящими об этом Сталване. Когда пару лет назад нескольких заезжих аристократов нашли мертвыми, мы с Хаггардом решили расследовать это дело. Я отыскал несколько заляпанных грязью страниц, но мы так и не нашли связи между ними и этим лесным сумасшедшим. Найденные тобой улики подтверждают его вину. Немедленно отнеси эту страницу командиру Чернодрев и расскажи ей о добытых сведениях!', 'Отнесите грязную страницу командиру Альтее Чернодрев.', 'Надо же, ты оказался настоящим сыщиком, $C).', 'Надеюсь, ты ко мне не по пустякам пришел, $C. Но, во имя Света, говори быстрее. Для меня превыше всего безопасность Темнолесья, и терять время впустую я не намерена.', NULL, NULL, 'Испачканные страницы записей (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (80, 'Легенда о Сталване', 'Я давно присматриваюсь к этому Сталвану. Но если эта страница написана той же самой рукой, то его вина несомненно доказана.$B$BЗа долгие годы службы клерк Далтри стал настоящим экспертом по различению почерков. Покажи ему эту страницу, проверь, совпадает ли почерк с росписью в журнале.', 'Покажите запятнанную кровью страницу записей клерку Далтри.', 'Несомненно! Почерк на этой странице совпадает с подписью в журнале.', 'И снова ты здесь, $N. Что на этот раз?', NULL, NULL, 'Страница записей, запятнанная кровью (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (81, 'Груз медовухи', 'Я позаботился о том, чтобы ничего не пропало – ни медовуха из бочонка, ни лишние бутылки. Не то чтобы я так уж тепло относился к Драну, но нет ничего хуже, чем когда пропадает выпивка! Вот, держи.$B$BДоставь этот бочонок Драну Дрофферсу в его забегаловку в Оргриммаре. Да, и пожалуйста, не забудь передать привет Мальтону. Скажи, что если он соскучится по отличной выпивке и великолепным собутыльникам, то мы будем в восторге от его визита.', 'Доставьте бочонок в Оргриммар Драну Дрофферсу. ', 'Ну-ка, ну-ка, надо еще посмотреть, что там в этом бочонке!$B$BДа, похоже, все цело. Ну, вот твоя плата за доставку. Я выручу впятеро больше, когда продам ее у себя в таверне! Хы-хы!$B$BНу, а эти лишние бутылки \"Медовой зыби\" из Внутренних земель прибережем для особых случаев. Надо попробовать смешать ее с шампанским. Назовем это... медованским!', 'Если ты не собираешься ничего покупать и у тебя нет ничего с собой, значит, ты впустую отнимаешь у меня время! Где моя медовуха?', NULL, NULL, 'Груз медовухи для Драна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (82, 'Исследование Ядовитого улья', 'Все эти сообщения о жуках... нам известно, что они опустошают пруды в Ядовитом улье. А НЕИЗВЕСТНО нам... все остальное.$B$BДля начала надо узнать, кто наш враг! Ступай в Ядовитый улей и добудь части тел проклятущих насекомых Сентипаар. Отнеси их алхимику Пестычинсу, пусть повозится. Если уж он возьмется за работу, скоро мы обо всем узнаем!', 'Принесите 5 частей тел насекомых Сентипаар из Ядовитого улья алхимику Пестычинсу в Прибамбасск.', 'Неплохая работа – я немедленно примусь за анализ этих частей! Сразу скажу одно – таких насекомых я еще не видел. Такое впечатление, что ими управляет какая-то чуждая сила.$B$BНемедленно поговори с Рудознатцем; ситуация серьезная, ему без сомнений понадобится твоя помощь! Не знаю точно, но скорее всего речь снова пойдет о насекомых пустыни Танарис!', 'Ты ведь младший геодезист, да? Говори скорее, ситуация серьезная! Ты принес мне части тел насекомых, обещанные Рудознатцем?!', NULL, NULL, 'Части тел насекомых Сентипаар', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (83, 'Красный лен', 'В Североземье Братство Справедливости носит маски из холстины; в Элвиннском лесу они предпочитают лен, который мог бы принести мне гораздо большую пользу... и прибыль.$B$BПринеси мне красные льняные банданы, а я сделаю из них кое-что полезное для тебя.$B$BЛагеря Братства разбросаны по всему Элвиннскому лесу.', 'Принесите 6 красных льняных бандан на лесопилку Восточной долины и отдайте их Саре Тимберлейн.', 'Отличные повязки, даром что ткань грубовата...$B$BВот, держи!', 'Послушай, $N, у меня лен кончается. Может, выручишь меня?', NULL, NULL, 'Красная льняная бандана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (84, 'Назад к Билли', 'Вот, держи. Отдай этот пирог Билли, да не забудь сказать, что я желаю ему подавиться!', 'Отнесите пирог со свининой на Виноградники Маклура и отдайте его Билли.', 'М-м, вкуснятина! Пирог что надо!$B$BПохоже, ко мне возвращается память...', 'О-ох... Помираю с голоду... Эй, $N, не угостишь пирожком?', NULL, NULL, 'Пирог со свининой (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (85, 'Потерянное ожерелье', 'Я потеряла ожерелье. Сдается мне, его стащил этот беспризорник Билли Маклур! Вечно он шастает по виноградникам, как крыса какая-то! Если решишь его искать, то сходи на виноградники, это к востоку отсюда.$B$BПожалуйста, разыщи мое ожерелье, порадуй старуху-вдову!', 'Поговорите с Билли Маклуром.', 'Чего-чего она там потеряла? Какое такое ожерелье? Не брал я его, даже в глаза не видел, и вообще я не вор какой-нибудь!$B$BМожет, я и знаю, кто мог это сделать... Вот только вспоминать на голодный желудок сложно, в голове мутится.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (86, 'Пирог для Билли', 'Может, если бы я получил пирог, то смог бы вспомнить, у кого сейчас это твое ожерелье. Кстати... Говорят, у тетушки Бернис получаются отличные пироги со свининой. $B$BЯ вот что думаю: принеси ей кабаньего мяса – около ферм кабанов ошивается видимо-невидимо – и попроси испечь для тебя пирог.', 'Принесите 4 куска кабаньего мяса на ферму Стоунфилд и отдайте тетушке Бернис.', 'Хоть мясо и жестковато, его можно потушить на медленном огне и приготовить отличную начинку для пирога!', 'Что? Я еще должна кормить пирогами мальчишку, который стащил мое ожерелье?! С другой стороны, если подумать, пирог – не такая большая цена за то, чтобы вернуть ожерелье назад.$B$BЛадно уж... Кабанье мясо у тебя есть?', NULL, NULL, 'Кусок кабанины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (87, 'Фикс', 'Я играл около рудника Подземных глубин и, похоже, уронил... М-м... В смысле, я там видел ожерелье этой самой дамы. Представления не имею, как оно туда попало; я тут ни при чем!$B$BВ общем, короче, я видел, как здоровенный кобольд с золотыми зубами схватил ожерелье и скрылся в руднике. Если отыщешь этого кобольда, найдешь и ожерелье, точно тебе говорю!', 'Верните ожерелье тетушке Бернис на ферму Стоунфилдов. ', 'Мое ожерелье! Оно нашлось! О, дорогуша, спасибо, спасибо!$B$BВот, держи. Это принадлежало моему мужу; \"счастливая вещица\" – он всегда так говорил. Если бы только он взял это с собой в последний поход!..', 'О, $N? Привет, привет... Ну что, нашлось мое ожерелье?', NULL, NULL, 'Ожерелье Бернис', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (88, 'Принцесса должна умереть!', 'У семейства Бреквеллов имеется свинья. Не простая, а призовая, по кличке – ты только представь себе! – Принцесса. И эта громадная гора сала то и дело пробирается на мой огород! Чтобы пожирать мои овощи!$B$BТак вот, прежде чем эта скотина доберется до полей... словом, Принцесса должна умереть! Принеси мне ее ошейник в доказательство того, что это свершилось, а взамен получишь кое-что полезное.$B$BПринцессу держат на тыквенной ферме Бреквеллов: это к востоку от фермы Маклуров. Разберись с ней прежде, чем она проголодается и вернется сюда!', 'Убейте Принцессу, заберите ее ошейник и отнесите на ферму мамаше Стоунфилд.', 'Счастье-то какое! Эта хавронья была такой громадной, что в один присест сожрала бы весь наш урожай! Я так тебе благодарна, $N!$B$BВзгляни: что-нибудь из этого тебе, надеюсь, подойдет?', 'Ну как? Надеюсь, Принцесса уже мертва?', NULL, NULL, 'Латунный ошейник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (89, 'Мост Безмолвия', 'Из-за последнего нашествия орков нам пришлось переплавить весь металл на пули, мечи и доспехи. Мы посылали в Штормград за новыми поставками, но отряд гноллов Красногорья разграбил обоз и сбежал в холмы за Приозерьем.$B$BНам не хватает материалов на ремонт моста. Если ты принесешь мне 5 железных пик и 5 железных клепок, $N, я прикажу тебя наградить.$B$BЗа дело!', 'Принесите 5 железных пик и 5 железных клепок штейгеру Ослоу в Приозерье.', 'Отличная работа, $N. Мы можем продолжить восстановление моста. Еще немного, и закончим.', 'Мост сам собой не строится! Где железные пики и железные клепки?', NULL, NULL, 'Железная пика', 'Железная клепка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (90, 'Котлеты из волчатины', 'Мое коронное блюдо – котлеты из волчатины! Разумеется, я могу тебе их пожарить. Но для этого мне понадобятся кое-какие продукты. Принеси 10 постных волчьих боков и немного штормградских приправ. В лесу полно волков, и добыть мясо будет несложно. Что до приправы, то ее можно купить у Фелисии Гамп в цветочном магазине в районе каналов Штормграда.', 'Принесите 10 постных волчьих боков и штормградские приправы шеф-повару Груалю в Темнолесье.', 'Отличная работа, $N! Наслаждайся вкуснятиной – приправленной котлетой из волчатины!', 'Ты принес 10 постных волчьих боков? А травяную приправу от Фелисии из Штормграда?', NULL, NULL, 'Постный волчий бок', 'Травяные приправы Штормграда', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (91, 'Закон Соломона', 'В восточных предгорьях нашего края обосновался враг Штормграда. С помощью тайной магии этот негодяй по имени Моргант сеет ужас и страдания в нашем городе и окрестностях.$B$BОн прибрал под свою руку гноллов из стаи Темношкуров, и они исполняют его повеления. Согласно закону Приозерья, пособничество врагу королевства карается смертью.$B$BГноллов следует уничтожить!$B$BПринеси мне 10 подвесок Темношкуров и получишь награду.', 'Принесите 10 подвесок Темношкуров помощнику судьи Конаху в ратушу Приозерья.', 'Суд Озер благодарит тебя за помощь правосудию, $N. Помогая претворить в жизнь законы Королевства, ты способствуешь установлению справедливости в наших землях.', 'Принеси мне 10 подвесок Темношкуров и получишь награду.', NULL, NULL, 'Подвеска Темношкуров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (92, 'Гуляш по-красногорски', 'Я бы с радостью сделала для тебя гуляш по-красногорски, но есть небольшое затруднение. Во время недавнего вторжения орков мне пришлось кормить целый отряд солдат Штормграда, и все кладовые опустели... Хотя если ты снабдишь меня всеми необходимыми продуктами, я уж расстараюсь!$B$BПринеси мне пять кусков жесткого мяса кондора, пять рыл больших кровоклыков и пять порций хрустящего паучьего мяса.', 'Принесите Бреанне пять кусков жесткого мяса кондора, пять рыл большого кровоклыка и пять порций хрустящего паучьего мяса.', 'Молодец, $N. И какие отличные куски! А вот и мое коронное блюдо – гуляш по-красногорски.', 'Мне все еще нужны пять кусков жесткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса.', NULL, NULL, 'Рыло большого кровоклыка', 'Жесткое мясо кондора', 'Хрустящее паучье мясо', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (93, 'Темные пирожки с крабами', 'Открою тебе тайну: темные пирожки с \"крабами\" делаются из паучьих лапок! Понимаю, эта новость может быть для тебя неприятной, но пирожки получаются вкусные и ароматные – отличная закуска! Принеси мне липкие паучьи лапки, и я испеку для тебя пирожочки.$B$BГоворят, что лучшие лапки у ядовитых кругопрядов. Они плетут паутины на севере, между холмами и рекой.', 'Добудьте 6 липких паучьих лапок и принесите их шеф-повару Груалю в Темнолесье.', 'О, отличные лапки! Дай-ка я замариную их особым составом, – не подсматривай! – потом хорошенько подрумяню на сковородке…$B$BИ хотя темные пирожки с крабами – мое коронное блюдо и рецептом я делиться не готов, вот тебе рецепт блюда не хуже.', 'Привет тебе, $N. Ну как, удалось добыть липкие паучьи лапки?', NULL, NULL, 'Липкая паучья лапка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (94, 'Недремлющее Око', 'Мой соперник Моргант – волшебник, наделенный великой силой, но лишенный сердечной доброты. Он обосновался в башне Илгалара, что в Красногорье. Я нашел способ следить за ним при помощи Ока Азоры.$B$BОднако Око не дает возможности проникнуть в его мысли. Для такого дела мне потребуется помощь.$B$BЕсли ты согласишься помогать мне, возьми амулет Азоры и отнеси его к башне Илгалара. Амулет нужно положить под статую льва рядом с башней.$B$BЕсли это будет сделано, то с помощью силы Азоры я смогу проникнуть в замыслы Морганта.', 'Отнесите амулет Азоры к статуе льва, стоящей рядом с башней Илгалара в Красногорье.', 'Вы кладете амулет Азоры в углубление, и он словно бы врастает в камень. Вы слышите голос Теокрита:$B$BПрими мою благодарность, юный $N. Отныне ты сможешь говорить со мной посредством этого амулета. После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание.', 'Статуя льва уже не одно десят$Nие несет свою одинокую стражу у печально знаменитой башни Илгалара.$B$BУ подножия статуи есть углубление, куда можно вложить драгоценный камень или амулет...', NULL, NULL, 'Амулет Азоры (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (95, 'Месть Свена', 'Раньше я работал на одной из ферм на юго-востоке... а потом темные всадники спустились с перевала Мертвого Ветра и перебили всю мою семью, пока я был в отлучке!$B$BВернувшись, я увидел неподалеку от амбара неясную фигуру человека, который что-то закапывал. Он успел сбежать от меня, а задерживаться я не мог, потому что преследовал темных всадников. Так я и не узнал, что там спрятано.$B$BЕсли ты можешь выяснить, что закопал в землю этот незнакомец, я буду очень признателен. Поищи возле старого пня, рядом с амбаром.', 'Выясните, что зарыто за старым пнем на ферме, где работал Свен. ', 'Вы находите кучу торопливо накиданной земли. Похоже, кто-то хотел что-то спрятать... а времени у него не хватало.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (96, 'Зов воды', 'Возьми осколок. Возьми его и даруй жизнь.$B$BДаруй жизнь и пойми. Пойми, что вода – это жизнь... А порча – конец жизни.$B$BОберегай и даруй жизнь силой воды.', 'Отнесите Осколок Воды Заклинательнице Воды Ислен к Лестнице Прилива, что в Степях.', 'А вот и доказательство твоих свершений, как я и просила.$B$BЯ рада, что могу первой поздравить тебя с успехом и вручить тебе этот... Тотем воды.$B$BПусть он служит тебе верой и правдой. Удачи!$B$BСледующее испытание ожидает тебя нескоро, поэтому учись хорошенько. Чистая вода не только вдыхает новую жизнь в раненых, но может также оказывать и другие эффекты. Когда найдешь время, поговори с наставником шаманов. Может быть, у него найдутся для тебя новые заклинания.', 'Ты вернулся. Отлично!$B$BКак путешествие в Серебряный бор? Много времени заняло?$B$BМне трудно понять, достиг ли ты успеха, ведь большая часть этих земель затронута порчей. Она затмевает все доброе, что есть в них. Впрочем, порой маленькая победа оказывается не менее важной, чем большая. Очищение воды здорово поможет и тебе, и другим шаманам.', NULL, NULL, 'Осколок Воды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (97, 'Легенда о Сталване', '$N, немедленно сообщи командиру Чернодрев, что почерки совпадают! Ее подозрения подтвердились!', 'Сообщите новости командиру Альтее Чернодрев. ', 'Я так и знала! Отличная работа, $N!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (98, 'Легенда о Сталване', 'Сталван Мистмантл вел порочную жизнь. От его руки погибли многие невинные люди. Несомненно, он виновен в бесчисленных преступлениях, а теперь угрожает и нашему Темнолесью. Лишь Свету известно, что за гнусные злодеяния он готовит. Ступай в его дом к северу от города, $C, и покончи со Сталваном раз и навсегда.$B$BПриведя мой приговор в исполнение, отправляйся к мадам Еве и покажи ей его фамильное кольцо. В конце концов именно ее предчувствие позволило нам раскрыть это темное преступление. Благодаря ей в Темнолесье стало безопаснее.', 'Убейте Сталвана Мистмантла и принесите мадам Эве его фамильное кольцо.', 'Знаю, $N, Сталван мертв. Я ощутила волну надежды, пробежавшую по оскверненному лесу. Сумеречный лес раз и навсегда освободился от кровожадной твари. Мою радость омрачает лишь мысль о тех, кто пал жертвой этого чудовища. А ты отважен и хитер, $C.', 'Да, $N?', NULL, NULL, 'Фамильное кольцо Мисмантла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (99, 'Безрассудство Аругала', 'По мере того, как растет мое понимание магии Аругала, растет и мое презрение к этому злосчастному глупцу. Я уже почти закончил исследование его так называемого \"лекарственного зелья\". $B$BУ меня будет полная информация, когда я узнаю, какие чары служат причиной странностей, происходящих в деревне Погребальных Костров. Днем живущие там крестьяне выглядят по-человечески. Но когда солнце заходит, деревенский люд превращается в воргенов Лунной Ярости. $B$BМне нужно извлечь энергию из заколдованных кандалов, надетых на крестьян Аругалом. Принеси мне 6 заколдованных кандалов из деревни Погребальных Костров, $N.', 'Принесите 6 кандалов из деревни Погребальных Костров Далару Ткачу Рассвета в Гробницу.', 'Твоя настойчивость весьма похвальна. С помощью информации, которую ты помог мне собрать, Аругал падет, и вся его безрассудная магия развеется. Браво, $N.', 'Тебе удалось собрать для меня кандалы из деревни Погребальных Костров, $N?', NULL, NULL, 'Кандалы из деревни Погребальных Костров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (100, 'Зов воды', 'Отзвучали последние слова заклятья, и вас ослепляет вспышка света. Звуки капель, падающих на пламя, стихают, и вас переполняет радость: ведь оскверненные духи вокруг вас уничтожены.', 'Поговорите с Низшим воплощением воды на Берегу Северного прилива, что в Серебряном бору.', 'Спасибо тебе. Спасибо шаманам.$B$BПорча отступает, но жизнь продолжает увядать. Пусть шаманы охраняют жизнь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (101, 'Тотем кары', 'По лесу расползается тление и порча, $N, и все мы вынуждены позаботиться о самозащите. Ветер несет мне вести о великой опасности, поджидающей тебя в ближайшем будущем.$B$BЕсли ты желаешь оградить себя от нее, $gблагородный:благородная: $C, принеси мне 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда. Тогда я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя.', 'Принесите 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда мадам Еве в Темнолесье.', 'Ты поступил мудро, $N. Этот тотем Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами. Если тебе будет что-то угрожать, возьми тотем в руку – и его магическая аура защитит тебя. Не теряй мужества, прекрасный $C. Тебе оно понадобится, ибо я чувствую – грядет немало кровопролитных сражений.', 'Принеси мне 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда, и я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя.', NULL, NULL, 'Клык вурдалака', 'Фиал паучьего яда', 'Палец скелета', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (102, 'Патрулирование Западного Края', 'Штормград отвернулся от нас. Злобный ветер несчастий носится по равнинам Западного Края. Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь. Мы, бывшие фермеры, намерены постоять за себя.$B$BТвое задание, если ты за него возьмешься, будет состоять в том, чтобы патрулировать луга Западного Края. Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мертвых копей. Принеси мне 8 лап гноллов, и я вознагражу тебя за проявленное мужество.', 'Принесите капитану Данувину на Сторожевой холм 8 лап гноллов.', 'Хорошая работа, $N. Если на стороне народного ополчения будут такие смельчаки, как ты, Западный Край сможет когда-нибудь вновь стать процветающей житницей, какой был когда-то. Пожалуйста, прими эту награду в знак признательности за твои усилия.', 'Набрал ли ты уже 8 лап с тех вероломных гноллов?', NULL, NULL, 'Лапа гнолла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (103, 'Хранитель пламени', 'Ночь, когда погибла семья смотрителя маяка, была ужасной. Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вел нападавших. Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам – моя забота. Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи.$B$BПомогите мне поддержать огонь факела – принесите 5 фляг масла, собрав их с сельскохозяйственных големов.', 'Принесите капитану Грейсону на Маяк в Западном Крае 5 бурдюков с маслом.', 'Хвала тебе, смелый $C. Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел.$B$BМеня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы.', 'Огонь вскоре погаснет, если не будет масла, $N.', NULL, NULL, 'Бурдюк с маслом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (104, 'Опасность на побережье', 'Когда моя жизнь оборвалась на скалах, я и понятия не имел, что уготовано мне на том свете. Маяк той ночью не светил, поскольку Старый Мрачноглаз перепугал семью смотрителя, и они убежали. Потом они вернулись и вновь зажгли пламя, но Мрачноглаз заставил более слабых духом мурлоков атаковать маяк вместе с ним. Во второй раз семье смотрителя не повезло, и вся она погибла у меня на глазах.$B$BУбейте Старого Мрачноглаза, если увидите его на берегу, принесите мне одну из его чешуй, и я вознагражу вас.', 'Принесите чешую Старого Мрачноглаза капитану Грейсону к Маяку в Западном Крае.', 'Итак, это злобное чудовище, Мрачноглаз, мертво. Хорошая работа, $N. Вы своими руками прервали одну жизнь, но, возможно, тем самым спасли множество других. Великое море, само по себе исполненное угрозы, станет этой ночью чуточку безопаснее благодаря вашему героическому деянию.', 'Ну как, вам еще не удалось справиться с угрозой по имени Старый Мрачноглаз? Его видели носящимся вдоль береговой линии Западного Края.$B$BВозвращайтесь ко мне, когда злобная тварь будет мертва.', NULL, NULL, 'Чешуя Старого Мрачноглаза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (105, 'Увы тебе, Андорал', 'Увы, пришло время напасть на Андорал и изгнать оттуда лича!$B$BЗлобный Араж Призыватель обосновался в самом сердце руин. Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы. Без многочисленных помощников тебе нечего и думать одержать над ним верх.$B$BУбей Аража и принеси мне его кристалл-талисман!', 'Принесите осколок оберега Араджа верховному палачу Деррингтону в Бастион в Западных Чумных землях.', 'Свершилось! Араж... этот лич наконец-то пал!$B$BСегодня ты оказал огро$Nю услугу Орде. Храбрость и упорство – спутники подлинного героизма. Прошу тебя, прими это в залог нашей благодарности. Пусть все знают, что благодаря тебе Орда одержала победу!', 'Тебе было дано задание, $N. Ты принес мне кристалл лича в доказательство его выполнения?', NULL, NULL, 'Осколок оберега Араджа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (106, 'Юные влюбленные', 'За что мне это наказание? Мое сердце отдано Томми Джо Стоунфилду, я жить без него не могу, но наши родители – заклятые враги! Я не только встретиться – даже взглянуть на него не могу!$B$BПожалуйста, отнеси Томми Джо это письмо. Он обычно бывает у реки к западу от фермы Стоунфилдов, а сама ферма – тоже к западу отсюда...', 'Отдайте любовное послание Мэйбелл Томми Джо Стоунфилду.', 'Я больше не могу жить в разлуке с ней! Я должен увидеть ее!', 'Письмо? От Мэйбелл? О, моя радость, свет моей жизни!.. Давай скорее письмо!', NULL, NULL, 'Любовное послание Мейбелл (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (107, 'Записка для Вильяма', 'Бьюсь об заклад, у Вильяма Песта найдется зелье, которое поможет соединить наших юных влюбленных!$B$BВот, держи: отнесешь эту записку Вильяму. Найдешь его в Златоземье, в таверне \"Гордость льва\".', 'Отнесите записку бабули Стоунфилд Вильяму Песту. ', 'У меня просто сердце разрывается, как подумаю об этих бедных детках, Мэйбелл и Томми Джо. Ах, молодость... Весна... Любовь...$B$BДумаю, я смогу им чем-нибудь помочь. Погоди-ка, дай подумать...', 'Что тут у тебя? Записка от бабули Стоунфилд? Ах, Милдред... Сто лет ее не видел. И что же она пишет?', NULL, NULL, 'Записка бабули Стоунфилд (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (109, 'Доклад Гриану Камнегриву', 'Похоже, $C, тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву. Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.', 'Поговорите с Грианом Камнегривом. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.', 'А, так это мой друг тебя сюда отправил? С его стороны это большая любезность.$B$BЧто ж... Монархия Штормграда больше не поддерживает нас. Остается полагаться на ополчение. Если ты хочешь сражаться за свободу вместе с нами, я буду рад этому.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (110, 'Анализ частей насекомых', 'Мне понадобится время на изучение оборудования Холстомера... и на приведение в порядок его дел. Ох, печенкой чую, не последняя это потеря, проклятые жуки еще покажут нам, где раки зимуют!$B$BПоговори, пожалуйста, с алхимиком Пестычинсом, узнай, как проходят исследования частей насекомых. Если все готово, принести мне результаты.', 'Найдите в Прибамбасске алхимика Пестычинса и получите результаты анализа частей насекомых.', 'Да, результаты готовы. Они, мягко говоря, неприятные.$B$BК сожалению, наши подозрения подтвердились, и насекомых контролирует неведомая сила. И не только неведомая, но и злобная. Этих насекомых превратили в настоящих опустошителей. Я такого еще не видел!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (111, 'Разговор с бабулей', 'Прошу тебя, $N, поговори с моей бабулей. Если кто и может сделать так, чтобы мы с Мейбелл были вместе, так это она.$B$BБабуля сейчас дома – это к востоку отсюда...', 'Поговорите с бабулей Стоунфилд. ', 'Пока наши семьи враждуют, у Томми Джо и Мэйбелл вряд ли есть шансы; но, может, мы дадим им возможность хоть немного побыть вместе.$B$BХм... Что бы придумать...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (112, 'Хрустальный фукус', 'Да, я могу приготовить для Мейбелл напиток невидимости, чтобы она могла убежать с Виноградников Маклура к своему Томми Джо. Но для этого мне нужен хрустальный фукус.$B$BЭти водоросли растут в океане, и мурлокам иногда удается добыть их. Может, у тех, что живут на берегах Хрустального Озера, найдется нужный компонент. А озеро найти просто: нужно только пойти на восток от Златоземья.', 'Принесите Уильяму Песту в Златоземье 4 побега хрустального фукуса. ', 'Ага, вот и фукус! Отлично, просто отлично! А теперь погоди минутку: сейчас напиток будет готов.', 'Тебе удалось добыть хрустальный фукус? Уверен, Мэйбелл ждет не дождется встречи со своим драгоценным Томми Джо...', NULL, NULL, 'Ветка хрустального фукуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (113, 'Анализ частей насекомых', 'Старший геодезист Рудознатец должен немедленно увидеть мой отчет. Более того... его должны увидеть все, кто умеет читать. Серьезная опасность грозит не только Танарису и Прибамбасску, но если сидеть, сложа руки, то и всему южному Калимдору. Да что там, всему Азероту – эти твари не собираются останавливаться.$B$BПусть Рудознатец сделает копию моего отчета, распространи ее среди всех своих союзников. Пусть все узнают об этом!', 'Отнесите отчет старшему исследователю Рудознатцу в Прибамбасск. Получите копию отчета, как просил алхимик Пестычинс.', 'Спасибо за доставку отчета, младший геодезист $N; вот плата за верную службу Водной компании Прибамбасска.$B$BХотя я не слишком люблю делиться информацией задарма с теми, кто мог бы заплатить за нее звонкой монетой, но Пестычинса я знаю много лет. Если он советует рассказать о нашествии насекомых всем и каждому, да будет так. Подожди немного, и я сделаю копию.', 'Ну как, младший геодезист $N, старина Пестычинс подготовил отчет?', NULL, NULL, 'Отчет о наблюдении за насекомыми (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (114, 'Бегство', 'Отнеси этот напиток невидимости юной Мейбелл. Его действия хватит на то, чтобы девушка успела встретиться с Томми Джо.', 'Отнесите напиток невидимости Мэйбелл Маклюр. ', 'Мне так стыдно, что приходится обманывать свою семью... Но я не могу отказаться от Томми!$B$BБлагодарю тебя, $N. Как только подвернется случай, я выпью этот напиток и найду способ пробраться к моему любимому.$B$BА в дополнение к словам благодарности прими вот это.', 'Томми Джо прочел мое письмо? Что он сказал?', NULL, NULL, 'Напиток невидимости (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (115, 'Темная магия', 'Орки из клана Черной Горы позвали на помощь чародеев, а те принесли с собой источники темной силы – полуночные сферы. Чародеи наносят чувствительные удары по защитникам Красногорья, и мы должны как можно скорее лишить их столь мощного оружия.$B$BДобудь для меня полуночные сферы. Ты найдешь их у чародеев Черной Горы. Я придумаю, как избавиться от Сфер, чтобы мир стал лучше и чище!', 'Принесите 3 полуночных сферы маршалу Маррису в Приозерье.', 'Благодарю тебя, $N. Я немедленно прикажу уничтожить эту мерзость.', 'Как успехи с чародеями? Где полуночные сферы?', NULL, NULL, 'Полуночная сфера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (116, 'Сухие времена', 'У меня возникло небольшое затруднение, $N. Еще немного, и все бутылки опустеют, а поставок алкоголя давно не было. Проклятые орки.$B$BНе хочешь подзаработать?$B$BПринеси мне бочонок громоварского светлого от Мрачнобуха Громовара из Западного Края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу.', 'Принесите кабатчику Дэниэлсу из Приозерья бочонок громоварского светлого из Западного края, бочонок мерло из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья.', 'Отличная работа, $N! Я представляю, сколько дорог тебе пришлось исходить, чтобы принести мне такое количество первосортных напитков. Завсегдатаи трактира будут счастливы!$B$BМоя жена неплохая рукодельница. Прошу, прими плащ, сшитый ею, в знак моей признательности.', 'Принеси мне бочонок громоварского светлого от Мрачнобуха Громовара из Западного Края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу.', NULL, NULL, 'Бочонок громоварского', 'Бочонок \"Мерло\"', 'Бутылка самогона', 'Бурдюк со сладким ромом');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (117, 'Громоварское', 'Торопись давай, иди побыстрей,$BЧтоб нашего пойла отведать скорей.$BОно ближе к пиву – не спутаешь с кашей,$BНо нужен нам хмель, чтоб сварить пойло наше.', 'Принесите Мрачнобуху Громовару 5 шишек хмеля. ', 'Хмель, и ячмень, и дрожжи, и солод -$BОт вкуса кидает то в жар, то в холод.$BНе надо просить и не надо молить,$BВедь можно себе из бочонка налить!', 'Торопись, мой друг, и иди побыстрей,$BЧтоб нашего пойла отведать скорей.$BОно ближе к пиву – не спутаешь с кашей,$BНо нужен нам хмель, чтоб сварить пойло наше.', NULL, NULL, 'Шишки хмеля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (118, 'Цена подков', 'Я потратил так много железа на доспехи и оружие для стражников Штормграда, что теперь его не хватает даже на подковы для лошадей!$B$BОтнеси эту записку кузнецу Аргусу в Златоземье, я хочу попросить его прислать мне партию подков.', 'Отнесите записку Вернера кузнецу Аргусу в Златоземье, что в Элвиннском лесу.', 'Так старому Вернеру нужны подковы, да?!', 'Что такое? Говоришь, Вернер тебя послал? Давай сюда его письмо. И ГОВОРИ ГРОМЧЕ!', NULL, NULL, 'Записка Вернера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (119, 'Доставка подков', 'Ладно, так и быть, пошлю ему 50 подков…$B$BВот они, уже упакованы, осталось только доставить! Передай Вернеру, что с ним приятно иметь дело. Пусть не забудет прочитать записку, прикрепленную к ящику!', 'Вернитесь к Вернеру Осгуду в Приозерье, что в Красногорье. Отдайте ему ящик с подковами.', 'Спасибо, ты здорово мне помог.$B$BЧто это? Аргус приложил к ящику записку... Что?! Аргус хочет ПЛАТЫ? Пф!$B$BЛадно, $N, спасибо за помощь.', 'О, да ты вернулся! Удалось достать подковы?', NULL, NULL, 'Ящик с подковами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (120, 'Посланец в Штормград', 'Тяжелые настали времена, $C. Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять. Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану. И поскорее возвращайся с вестями – неважно, добрыми или злыми.$B$BСпеши!', 'Мировой судья Соломон просит вас отнести отчет генералу Маркусу Джонатану в Штормград.', 'Вольно, $C.$B$BЧиновник Соломон – благородный человек. Его слова много для меня значат. Я поговорю с королем и объясню ему ситуацию. Заверьте доброго судью, что он получит подержку армии Штормграда. Я вышлю подкрепление, как только получу приказ Его Величества.', 'С чем пришел?', NULL, NULL, 'Состояние дел в Приозерье (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (121, 'Гонец в Штормград', 'Пока я жду ответа от короля, хочу, чтобы ты $gотнес:отнесла: это письмо мировому судье Соломону. $B$B$gСвободен:Свободна:, $C!', 'Отнесите ответ генерала Маркуса Джонатана мировому судье Соломону в Приозерье.', 'Благодарю тебя, $C. В знак признательности Озер и Штормграда прими эти деньги.$B$BХотя, признаться, смысл этого письма туманен. Что-то неладно в нашем королевстве. Боюсь, это не конец, а начало войны.', 'Новости от генерала? Когда прибудет подкрепление?', NULL, NULL, 'Ответ генерала (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (122, 'Брюшная чешуя', 'В обмен на подковы Аргус из Златоземья просит брюшную чешую черных дракончиков. Если ты добудешь мне 6 лоскутов чешуи, я смогу расплатиться с Аргусом... И для тебя что-нибудь сделаю.$B$BЧерных дракончиков можно отыскать к югу от Приозерья, но им не сидится на одном месте. Проще всего высматривать их, направляясь по другим делам, и охотиться по случаю.', 'Добудьте 6 лоскутов чешуи с брюха черных дракончиков и отнесите их Вернеру Осгуду в Красногорье.', 'Спасибо! Теперь я смогу расплатиться с Аргусом...', 'Если я не отдам чешую жадине Аргусу, он пошлет за ней кого-нибудь другого. Ты уже добыл материал?', NULL, NULL, 'Чешуя с брюха черного дракончика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (123, 'Вымогатель', 'На этом листке – расписание поставок золота из рудников в Элвиннском лесу. Поставки расписаны по дням и часам, а в качестве получателя указан некий \"Вымогатель\".$B$BСудя по всему, Вымогатель обосновался неподалеку от тыквенного поля Бреквеллов в восточной части Элвиннского леса.$B$BПохоже, это важные сведения. Было бы неплохо сообщить их маршалу Дугхану: он сейчас в Златоземье.', 'Пойдите в Златоземье к маршалу Дугхану и отдайте ему расписание Вымогателя.', 'Хм... Я слышал об этом \"Вымогателе\", вот только не знаю, на кого он работает. Должен тебя поблагодарить: расписание поможет нам разгадать эту тайну...', 'Что?! Да никто из наших в Элвиннских шахтах уже несколько месяцев не работает!$B$BДай-ка сюда эту бумажку...', NULL, NULL, 'Расписание Вымогателя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (124, 'Лай гноллов', 'Будто нам одних орков мало! А теперь вдоль хребта рядом с моими стойлами шастают громилы и мистики гноллов и при случае воруют лошадей…$B$BЕсли ты сможешь избавить меня от этих проходимцев, мы с лошадьми будем весьма признательны.', 'Убейте 10 громил из стаи Красногорья и 8 мистиков из стаи Красногорья. Вернитесь к Вернеру Осгуду.', 'Благодарю тебя за помощь, $N!', 'Лошади по-прежнему нервничают, а по ночам все еще доносится проклятый волчий вой. Прошу тебя, $N, сделай что-нибудь с этими гноллами!', NULL, NULL, 'Громила из стаи Красногорья убито', 'Мистик из стаи Красногорья убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (125, 'Утраченные инструменты', 'Мне не помешала бы помощь, $N. Наш город в осаде, и достать припасы и оборудование все труднее. Мои инструменты везли из Златоземья в фургоне, но мост был уничтожен. Мы перегрузили их в лодку, но тут орки пробили ее снарядом из катапульты! И вот невезенье, ящик опустился на самое дно озера.$B$BДостань его, $N, и я щедро вознагражу тебя.', 'Достаньте ящик с инструментами штейгера Ослоу со дна озера Безмолвия.', 'Отличная работа, $N! Я уж и не надеялся вновь увидеть свои инструменты.', 'Удалось вытащить инструменты?', NULL, NULL, 'Ящик инструментов Ослоу', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (126, 'Вой в холмах', '$N, гноллы по-прежнему здесь. Я слышу, как они завывают, охотясь в холмах над Приозерьем. И один из них воет громче других – это Изувой, их вождь.$B$BСтоит его прикончить, и вся стая разбежится! Убей его и принеси в доказательство отрубленную лапу.$B$BСоблюдай осторожность,  этот гнолл заслуженно возглавляет целую стаю. Он совсем не прост...', 'Принесите лапу Изувоя Вернеру Осгуду в Приозерье. ', 'И снова благодарю тебя за помощь. Штормград еле-еле справляется с орками, у них не хватает солдат, чтобы защищать Красногорье от напастей вроде гноллов.', 'Изувой – опасное существо, $N. Если ты еще не готов сразиться с ним, я тебя понимаю.', NULL, NULL, 'Лапа Изувоя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (127, 'Продажа рыбы', 'Озеро Безмолвия славится пятнистой рыбой-луной. На нее всегда есть спрос... А мой запас подходит к концу!$B$BПринеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты $gсам:сама: не умеешь удить, то... Попытайся отнять рыбу у мурлоков!', 'Принесите 10 тушек пятнистой рыбы-луны портовому начальнику Барену в Приозерье.', 'Иметь с тобой дело – одно удовольствие, дружище!', 'Ну как, где моя рыба-луна?', NULL, NULL, 'Пятнистая рыба-луна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (128, 'Награда за головы орков Черной горы', 'Мы должны уничтожить клан Черной Горы. Враг вторгся в наши земли. Эти горы по праву принадлежат королю Штормграда. До нас дошли сведения, что главы всех видов войск клана называются воителями. Их можно отыскать в северном лагере, к западу от дороги, ведущей в Пылающие степи.$B$BМировой судья Соломон распорядился перебить этих гнусных тварей. Убей 15 воителей из клана Черной Горы и возвращайся ко мне.', 'Убейте 15 воителей из клана Черной горы.', 'Вижу, ты доблестно сражался с кланом Черной Горы, $C. Ты оказал нашему городу неоценимую услугу.', NULL, NULL, NULL, 'Воитель из клана Черной горы убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (129, 'Бесплатный обед', 'Можешь оказать мне услугу? Я приготовила обед для стражника Паркера, но он ушел на дежурство... Он-то может постоять за себя, но простой горожанке вроде меня не стоит соваться в те края.$B$BЕсли ты отнесешь ему обед, я бесплатно тебя накормлю! Паркер патрулирует участок дороги, ведущей в Сумеречный лес.', 'Отнесите обед стражнику Паркеру. Он патрулирует дорогу, ведущую в Темнолесье.', 'Спасибо, вкусно и сытно покушать я люблю. Хранить Приозерье от нападений орков и гноллов нелегко!', 'Дарси прислала мне обед, да? У нее доброе сердце. Что ж... Пора подкрепиться!', NULL, NULL, 'Обед Паркера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (130, 'Визит к травнице', 'Если ты все равно идешь к Дарси, не отнесешь ли ей от меня цветы? Букетик можно приобрести у травницы в Приозерье, в западной части города.$B$BТолько когда будешь покупать цветы… не говори травнице Марти, от кого они и кому...', 'Поговорите с травницей Красногорья Марти Джайнроз. ', 'Тебе нужен букет цветов? Ты вроде бы у нас недавно... уже нашел даму сердца?$B$BПонимаю, мне не следует совать нос не в свое дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (131, 'Доставка нарциссов', 'Вот и букет. Я выбрала для тебя нарциссы. Мои любимые цветы!', 'Отнесите Дарси букет нарциссов.', 'Какая прелесть! Надо поскорее поставить их в воду!$B$BНо... это любимые цветы Марти. Неужели Паркер послал тебя за букетом к этой ревнивой мегере? Ты ведь не сказал, для кого они? Иначе не удивлюсь, если она их отравила.$B$BНет-нет, ты ни в чем не виноват. Большое спасибо! А вот и твой обед.', 'И снова здравствуй, $N. Понравился ли Паркеру обед?', NULL, NULL, 'Букет нарциссов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (132, 'Братство Справедливости', 'То, о чем я хочу тебе рассказать, может стоить мне жизни. Бандиты из Братства Справедливости замышляют что-то крупномасштабное. Последнее, что я слышал, – что они действуют заодно со всякими гноллами, кобольдами и даже гоблинами.$B$BОтнеси эту записку Камнегриву. В ней разъясняется все, что я знаю на эту тему.', 'Отнесите записку Вилли Гриану Камнегриву в Западный Край.', 'Эх!.. Надо было сгноить этого мошенника, когда у меня был шанс. Но эта информация действительно очень важна. Хорошая работа.', 'Приятно видеть вас снова, $N. Так что там Вилли собирался рассказать?', NULL, NULL, 'Записка Вилли (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (133, 'Фигурка вурдалака', 'Я живу вдали от города, никто меня не защищает, и даже странно, как это меня до сих пор не сожрали вурдалаки и мертвяки! Только вчера несколько костеглодов ломились ко мне в дом!..$B$BЯ хочу сделать особую фигурку – что-то вроде пугала для этой нежити. Для этого мне понадобится несколько ребер вурдалаков. Их можно добыть, убивая плотоядов, костеглодов, мозгоедов, гнилую нежить и распространителей чумы.$B$BПринеси мне ребра, и я дам тебе несколько монет.', 'Добудьте 7 ребер вурдалаков и принесите их в хижину Аберкромби. ', 'О, спасибо. Это наверняка сработает!', 'Кажется, я слышу за домом шаги вурдалаков – надо поскорее сделать фигурку! Ты принес мне ребра вурдалаков?', NULL, NULL, 'Ребро вурдалака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (134, 'Нападение огров', 'Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров! Я сбежал, бросив свой ящик с ценными инструментами и травами.$B$BПрогнав меня, они вернулись к своему кургану в южной части Сумеречного леса. Думаю, они оставили мой ящик неподалеку от кургана.$B$BПрошу тебя, $N, верни мне ящик, без него я как без рук.', 'Вернуть ящик Аберкромби владельцу.', 'Хвала Нек... то есть ТЕБЕ, $N! Ты более чем заслуживаешь награды.$B$BАга! Как я счастлив! Впереди много радостных ночей!', 'Ты принес мой ящик? Коли так, пожалуйста... Быстро дай его сюда!', NULL, NULL, 'Ящик Аберкромби', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (135, 'Братство Справедливости', 'Интересно, что имел в виду Вилли, когда упомянул о Каменщиках. Оговорился или проговорился? Могут ли разбойники из Братства Справедливости быть связаны с Каменщиками? Только один человек должен знать наверняка: Матиас Шоу, глава ШРУ. Покажи ему записку Вилли и посмотри, сможет ли он пролить свет на эту тайну. Если тебе не сразу удастся найти Шоу, поищи в казармах в старом городе.', 'Отнесите записку Вилли Матиасу Шоу в Штормград. ', 'Это дело может оказаться сложнее, чем полагает Камнегрив.', 'Какое у тебя ко мне дело? Я очень занятой человек...', NULL, NULL, 'Записка Вилли (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (136, 'Спрятанное сокровище капитана Сандерса', 'Если ты читаешь это – значится, старина капитан Сандерс уже покоится на дне. Так что мое сокровище теперь может стать твоим, главное – следуй подсказкам.$B$BСначала найди мой сундучок. Его, должно быть, уже наполовину песком занесло, а находится он на западном побережье Западного Края рядом с обломками корабля. Обломков-то там много, но ржавый якорь на берегу – только один. Найди этот якорь, и ты найдешь мой сундучок. Загляни внутрь за следующей подсказкой.', 'Найдите сундучок капитана Сандерса и поищите в нем следующую подсказку. ', 'Сундучок медленно, со скрипом, открывается. Кажется, ничего в нем нет, кроме песка и воды. Постойте-ка! Проворно выползает маленький крабик, а в клешнях у него – следующая подсказка!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (138, 'Спрятанное сокровище капитана Сандерса', 'Ключ к поиску сокровища таков: \"Отличная работа, приятель! Теперь тебе идти на восток. На восток в холмы, на восток к дороге. Ищи на обочине дороги развалины старого очага. Там найдешь старую бочку, в которой и будет следующий ключ\".', 'Найдите старую бочку рядом с разрушенным очагом и поищите в ней следующий ключ.', 'Отличная работа, охотник за сокровищами!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (139, 'Спрятанное сокровище капитана Сандерса', 'Обыскивая бочку, вы обнаруживаете еще один кусок пергамента. На нем написано: \"А теперь от этой бочки поверни к северу. Прямо, как ворон летит, иди, пока не наткнешься на пустой кувшин рядом с одинокой ветряной мельницей на прибрежных утесах. Осмотри кувшин внимательно – может, и найдешь то, что ищешь\".', 'Найдите следующую подсказку в пустом кувшине, найденном рядом с ветряной мельницей.', 'Ты на пути к главному призу, искатель сокровищ!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (140, 'Спрятанное сокровище капитана Сандерса', 'Конечно же, глубоко внутри старого кувшина лежит еще одна подсказка к поиску сокровища Сандера. Чернила кое-где расплылись, а бумага отдает виски, но кое-что вам удалось разобрать: \"Раз уж ты нашел мой старый кувшин из-под виски, значит, ты близко подобрался к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберешься до воды – не останавливайся! Плыви, пока не найдешь остров, где и находится мой сундук с сокровищем!', 'Установите местонахождение сундука капитана Сандерса и откройте его.', 'Петли на крышке старого сундука заржавели, но поддаются. Вы с усилием открываете сундук и забираете сокровище.$B$BПоздравляем!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (141, 'Братство Справедливости', 'Гильдию каменщиков возглавлял человек по имени Эдвин ван Клиф. Именно он занимался восстановлением Штормграда после разорения его орками во время Первой войны. Должно быть, ван Клиф и его люди остались недовольны тем, как с ними обошелся король, когда восстановление города было завершено. Это могло бы объяснить пару вещей.$B$BЯ тут расписал все более подробно для вашего начальства в Западном Крае. Сразу же отправляйтесь туда и передайте ему документ!', 'Передайте документ, написанный Шоу, Гриану Камнегриву в Западный Край.', 'Эдвин ван Клиф... Мне хорошо известно это имя. Обидно думать, что этот трудолюбивый и талантливый человек мог превратиться в такого мерзавца. Мне понадобятся дополнительные доказательства, чтобы я поверил в это.', 'Пролил ли Мастер Шоу какой-то свет на происходящее?', NULL, NULL, 'Донесение Шоу (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (142, 'Братство Справедливости', 'Нам нужно выяснить местонахождение убежища Братства Справедливости. $N, мой разведчик сообщает, что на дороге между Луноречьем, прииском на Золотом Берегу и рудником Янго видели вестника из Братства Справедливости. Я прошу тебя поймать его. Если он окажет сопротивление, убей его и принеси мне все, что найдешь при нем.', 'Выследите вестника из Братства Справедливости в Западном крае и принесите отнятое у него сообщение Гриану Камнегриву.', 'Вот явное доказательство того, что ими верховодит ван Клиф. Теперь все, что нам нужно узнать, – это где прячутся бандиты братства.$B$BНам тут немного повезло, пока вас не было. Мы поймали вора, пытавшегося украсть повозку Сальдена. Он пообещал навести нас на убежище бандитов в обмен на жизнь. Я прошу вас защитить его, чтобы предатель братства мог указать, где находится убежище. Возвращайтесь ко мне, когда выясните местонахождение убежища.', '$N, удалось ли вам найти какую-то информацию? Вы определили местоположение посланника?', NULL, NULL, 'Таинственное послание', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (143, 'Гонец в Западный Край', 'Что-то странное происходит в армии Штормграда, подкрепления все нет и нет. К сожалению, мы не можем позволить себе ждать. Нельзя же сидеть сложа руки и не пытаться позвать соседей на помощь, пока доблестные воины Приозерья погибают один за другим. Говорят, в Западном крае создано народное ополчение.$B$BОтнеси мою просьбу о помощи его предводителю, Гриану Камнегриву. Может быть, его люди помогут нам продержаться до подхода королевских отрядов.', 'Отнесите просьбу о помощи Гриану Камнегриву в Западный Край.', 'Добрый вестник, ты хорошо послужил своему господину.', 'Привет тебе, $C. Какое дело привело тебя к народному ополчению?', NULL, NULL, 'Обращение Соломона к Западному Краю (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (144, 'Гонец в Западный Край', 'Меня очень огорчило письмо мирового судьи Соломона. К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас. Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы.$B$BОтнеси мой ответ в Красногорье, $C, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов.', 'Вернитесь к чиновнику Соломону с ответом Гриана Камнегрива.', 'Что сказать, вести недобрые. Я и не подозревал, что у Камнегрива трудности, схожие с нашими. Что же отвлекает армию Штормграда от защиты ее собственных земель? Впрочем, зря я об этом говорю вслух.$B$BВот, вестник. Прими эти монеты в знак благодарности за верную службу городу. Быть может, скоро ты мне снова понадобишься.', 'Скоро ли ждать прибытия народного ополчения? Добрые ли вести ты несешь от лорда Камнегрива?', NULL, NULL, 'Ответ Камнегрива Соломону (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (145, 'Гонец в Темнолесье', 'И снова мне нужна твоя помощь. Я написал письмо лорду Чернодреву, прося его прислать нам на помощь обученных бойцов Ночного дозора на защиту Приозерья. Надо как можно скорее доставить мое послание. Действуй осторожно. Лорд Чернодрев – мэр города Темнолесья, расположенного в сердце Сумеречного леса. Не сходи с дороги.', 'Отнесите письмо лорду Чернодреву в Темнолесье. ', 'Благодарю за проделанный путь. Вести и верно важные.', 'Похоже, ты прибыл издалека, $C. Что привело тебя в Темнолесье?', NULL, NULL, 'Обращение Соломона к Темнолесью (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (146, 'Гонец в Темнолесье', 'Не знай я мирового судью Соломона лично, решил бы, что он сошел с ума. Послать в Приозерье Ночной дозор, потому что Штормград отказал в помощи? Мы и создали его, когда земли наводнила нечистая магия, а Штормград бросил нас на произвол судьбы. Если я пошлю в Приозерье Ночной дозор, то наш город падет, едва лишь дозор доберется  до края леса.$B$BОтнеси мой ответ своему господину в Приозерье.', 'Вернитесь к мировому судье Соломону с ответом лорда Элло Чернодрева.', 'Во имя Света! Армия Штормграда отступила из Западного Края. И Дозор не сможет защищать Темнолесье? Здесь таится предательство. Как же так?$B$BО, я забыл отблагодарить тебя за услуги, $C. Прими вот эту плату. А теперь извини меня. Что-то творится в Штормграде, и я должен докопаться до сути.', 'Рад снова видеть тебя, посланник. Могу ли я сообщить маршалу, что Ночная стража уже в пути?', NULL, NULL, 'Ответ Элло Чернодрева Соломону (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (147, 'Охота на человека', 'Если Вымогатель забирает золото с наших рудников, значит, он обворовывает королевство! Он должен предстать перед судом – а мне понадобится то кольцо, которое упоминалось в записке. Возможно, оно поможет нам узнать, на кого работает этот Вымогатель...$B$BЗдесь написано, что Вымогатель скрывается на тыквенном поле Бреквеллов. Попробуй поискать его там.', 'Найдите и убейте Вымогателя, а затем принесите его кольцо маршалу Дугхану.', 'Так тебе удалось его найти? Отлично, $N, просто прекрасно! Больше он ничего не будет \"вымогать\" на Элвиннских шахтах!$B$BА это кольцо... О, очень интересно! Это кольцо древнего братства Каменщиков Штормграда. С чего бы это мелкому воришке носить кольцо гильдии? И как вышло, что Братство Справедливости добывает золото на наших рудниках?$B$BНепростые вопросы, верно? Надеюсь, когда-нибудь мы узнаем ответ.', 'Тебе удалось разыскать Вымогателя? И на кого же он работает?', NULL, NULL, 'Кольцо Вымогателя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (148, 'Припасы из Темнолесья', 'Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели.$B$BНе $gмог:могла: бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Ее можно приобрести у мадам Евы, которая живет на центральной площади города.', 'Поговорите с мадам Евой.', 'А, так тебе нужна нить из призрачных волос? Боюсь, мои запасы иссякли, но я могу сделать еще... Если ты принесешь мне призрачные волосы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (149, 'Прядь призрачных волос', 'На старой ферме, в холмах к югу от Темнолесья, живет несчастное привидение по имени Слепая Мэри.$B$BВозьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити.$B$BБудь $gосторожен:осторожна:, рядом с домом бродит множество темных тварей.', 'Отнесите Слепой Мэри призрачный гребень.', 'Что это? Гребень? Какая прелесть! И он спокойно скользит по моим волосам, хотя они давно сбились в ужасный слипшийся колтун.$B$BАх, мне бы в зеркало посмотреться...', '*Всхлипывает.* Пожалуйста, не смотри на меня! Я вырвала глаза собственными руками, но все равно чувствую твой взгляд!$B$BЯ уродина! Уродина! Прошу тебя, отвернись!', NULL, NULL, 'Призрачный гребень (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (150, 'Мурлоки-браконьеры', 'Мурлоки начинают нас беспокоить. Все больше мурлокских рыбаков селится вдоль побережья Озера Безмолвия и вовсю ловит рыбу! Надо изгнать их, пока они не опустошили все озеро!$B$BУбей побольше мурлоков! Принеси мне восемь их плавников, и я найду, чем тебе отплатить...', 'Принесите 8 плавников мурлоков портовому начальнику Барену в Приозерье.', 'Молодец, $N. Надеюсь, тебе не слишком солоно пришлось.$B$BСтранно, что они ушли так далеко от моря. Хотелось бы знать, отчего они сбежали...', 'Принес плавники? Торопись, надо скорее изгнать мурлоков из нашего озера!', NULL, NULL, 'Плавник мурлока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (151, 'Бедная старая Савраска', 'Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений... Я ее покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге. Я была бы вам очень благодарна, $gсэр:леди:, если бы вы могли принести ей несколько горстей овса с окрестных полей.$B$BУверена, что вы найдете овес на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях. К юго-западу отсюда расположено несколько фермерских хозяйств.', 'Принесите 8 горстей овса Верне Хмуробров.', 'Огромное тебе спасибо, $N! Бедная старая Савраска будет просто счастлива!', 'Старая Савраска уже валится с ног. Не добыл ли ты овса для нее?', NULL, NULL, 'Горсть овса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (152, 'Зачистка побережья', 'Ты, должно быть, $gвидел:видела: все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово. Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности. На сегодняшний день мурлоки являются большой проблемой...$B$BРазберись с ними – убей 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков, – и награда будет ждать тебя.', 'Убейте 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков-мурлоков и вернитесь к капитану Грейсону на Маяк в Западном Крае.', 'Хорошая работа, $N. У тебя отличные боевые навыки! Благодаря тебе побережье Западного Края стало более безопасным местом.', 'Убей 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков-мурлоков, – и награда будет ждать тебя.', NULL, NULL, 'Мурлок-береговик убито', 'Мурлок-воин убито', 'Мурлок-волнолов убито', 'Мурлок-оракул убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (153, 'Красные кожаные банданы', 'В Братстве Справедливости идет постоянная кипучая деятельность. Я уже долго слежу за их передвижениями. Между прочим, я заметил, что многих бандитов можно опознать по красным кожаным банданам.$B$BПринеси мне 15 таких бандан, а я позабочусь о вознаграждении.', 'Принесите разведчику Галиану на Сторожевой холм 15 красных кожаных бандан.', 'Хорошая работа, $N. Пожалуйста, примите один из этих предметов в качестве оплаты за ваши труды.', 'Принесите мне 15 красных кожаных бандан, и я вам хорошо заплачу.', NULL, NULL, 'Красная кожаная бандана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (154, 'Гребень для Евы', 'НЕТ!!!$B$BУбери его, убери от меня этот гребень!$B$BЯ чудовище, меня больше никто не назовет прекрасной!', 'Верните гребень для призрачных волос мадам Еве в Темнолесье.', 'Ну, из этого выйдет целая катушка нити из призрачных волос, да еще и останется несколько прядей. Прими эти монеты в уплату за лишние пряди.', 'Чувствую, ты уже видел Слепую Мэри. Гребень все еще у тебя?..', NULL, NULL, 'Гребень для призрачных волос (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (155, 'Братство Справедливости', 'Так Камнегрив считает, что $gтакой слабый:такая слабая: $r сможет меня защитить? А ведь придется. Возьми-ка с собой пару-тройку друзей.$B$BТы же знаешь, что делать, да? Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости. Держись ко мне поближе. Бандиты из Братства охотятся за моей головой. Если нас увидят вместе, они попытаются меня убить.$B$BДай мне знать, когда ты и друзья, которых ты соберешь, будут готовы идти.', 'Сопроводите предателя к тайному убежищу Братства Справедливости. Когда он покажет, где прячутся ван Клиф и его люди, вернитесь к Гриану Камнегриву.', 'Великолепно, сэр $N! Теперь, когда мы знаем, где прячется ван Клиф, – он наш!', NULL, NULL, NULL, 'Проводите предателя Братства Справедливости к убежищу ван Клифа.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (156, 'Сбор цветков гнили', 'Если ты принесешь мне несколько цветков гнили, я сделаю для тебя сок зомби.$B$BЦветки гнили растут в самых странных местах. Например, в черепах ужасных скелетов и скелетов-губителей... хотя я лично туда не заглядывал!$B$BКладбище Вороньего холма кишмя кишит этими скелетами. Заодно ты и нас от них избавишь. Темнолесье будет тебе весьма признательно.', 'Соберите 8 цветков гнили и отнесите их хозяину таверны Смиттсу.', 'Отлично, ты сумел добыть цветки гнили. А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов.$B$BНочной дозор охраняет покой Темнолесья, и им нелегко приходится. Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех.', 'Привет. Ну как, принес цветки гнили?', NULL, NULL, 'Цветок гнили', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (157, 'Доставка ниток', 'Вот тебе нитки, $N. Им можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы.', 'Принесите нить из призрачных волос в хижину на севере от кладбища Вороньего холма и отдайте ее Аберкромби.', 'Великолепно! Она прекрасно подойдет…$B$BВот, дражайший $N, прими это в уплату за благороднейший поступок.', 'Я должен обвязать нитью из призрачных волос двери и окна, чтобы не пускать в дом чуждых призраков. Ты принес ее?', NULL, NULL, 'Прядь призрачных волос (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (158, 'Сок зомби', 'Мне нужна бутылка особого напитка – сока зомби. У хозяина темнолесской таверны \"Алый ворон\" Смиттса наверняка найдется лишняя бутылочка.$B$BТоропись, $N. Ночи стоят холодные, и мне не терпится снова наполнить жилы огнем.', 'Поговорите с хозяином таверны Смиттсом.', 'Значит, тебе нужен сок зомби? Хм... это довольно крепкий напиток, обычно его у меня не заказывают.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (159, 'Доставка сока', 'А вот и сок зомби…$B$BБудь с ним $gосторожен:осторожна:. Он такой крепкий, что мертвого поднимет!', 'Отнесите сок зомби в хижину Аберкромби.', 'Тысяча благодарностей, $N. Твоя глу... то есть твоя доброта согрела сердце старика!$B$BВот, друг, прими это в знак моей благодарности.', 'Сок зомби согреет меня долгими холодными ночами. Ты принес его?', NULL, NULL, 'Бутылка сока зомби (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (160, 'Записка для мэра', 'Отнеси эту записку Элло Чернодреву, мэру Темнолесья.$B$BМы с ним старые друзья... И когда он прочитает это и узнает, что ты для меня $gсделал:сделала:... не сомневаюсь, он будет счастлив не меньше меня! Ха-ха-ха!!!', 'Отнесите письмо Аберкромби Элло Чернодреву, мэру Темнолесья. ', '*Элло рассматривает письмо...*$B$BЧто это за язык? Похоже, какой-то древний... Не могу его прочитать.', 'Аберкромби?.. Я не знаю такого человека. Так говоришь, этот Аберкромби написал мне письмо?$B$BЧто ж, давай его сюда...', NULL, NULL, 'Письмо к Элло (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (161, 'Прямая и черная угроза', 'Если мои подозрения верны, то это взрывчатый порошок. Его следует показать специалистам, чтобы выяснить, с чем именно мы имеем дело. Ашлана Камнехмыла направили в полк, охраняющий Дун Модр и мост Тандола. Путь предстоит нелегкий и опасный, $N.$B$BПройди через врата Альгаза, по дороге, ведущей через Болотину, и отыщи Камнехмыла в Дун Модре. Советую не сходить с дороги и не задерживаться.', 'По просьбе главного инженера Плотиннера отнесите странно пахнущий порошок Ашлану Камнехмылу, специалисту по взрывчатым веществам. Он ждет вас в Дун Модре, что в Болотине.', 'Да, старина Плотина не зря беспокоится.', 'Что ты там бубнишь, сынок? В ушах звенит, аж жуть. Ух ты, что это ты мне принес?', NULL, NULL, 'Странно пахнущий порошок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (162, 'Появление силитидов', 'Прошу тебя, отнеси этот отчет кому-нибудь, сведущему в такого рода вопросах.$B$BЯ слышал про одну ночную эльфийку по имени Грацина Сила Духа. Она посвятила много времени изучению форм жизни, встречающихся лишь в Азероте; она и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к ней. Нам любая помощь не помешает.$B$BГоворят, она сейчас в храме Луны в Дарнасе.', 'Отнесите отчет о наблюдении за насекомыми Грацине Силе Духа в Дарнас. ', 'Что до твоего отчета... мы, ночные эльфы, знаем, о каком ужасе идет речь. Рудознатец правильно поступил, отправив свой отчет и тебя ко мне.$B$BЭти существа мигом пожрут всю пустыню Танарис; они представляют собой одну из величайших опасностей, с которой только можно столкнуться. Знакомься, $N – это силитиды. Так зовутся странные насекомые, которые служат величайшему злу, грозящему и Орде, и Альянсу.$B$BЖаль, что нам не хватило ума понять это раньше.', 'Да пребудут с тобой мир и покой, незнакомец. Зачем ты искал меня?', NULL, NULL, 'Отчет о наблюдении за насекомыми (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (163, 'Вороний холм', 'Что-то неладно на Вороньем холме, $N. Калор клянется, что он заметил кого-то – или что-то – в одном из домов. Две ночи подряд он видел крадущиеся тени, а на третью – свет в одном из окон.$B$BЕсли тебя и в самом деле беспокоит безопасность Темнолесья, выясни, что за чудовище скрывается на Вороньем холме.', 'Выясните, кто поселился на Вороньем холме.', 'Нет! Прошу, не убивай меня! Это всего лишь я... Трясунчик! Они повсюду... Мне не скрыться! Чудовища на Вороньем холме? Н-н-нет... не может быть. Всего лишь безвредный Трясунчик.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (164, 'Припасы для Свена', 'Ты знаешь Свена? Вот кто настоящий служитель Света! Он и его последователи стоят лагерем в северо-западной части Сумеречного леса.$B$BУвы, их так мало, что некого отправить за припасами в город. Не поможешь ли ты ему?', 'Отнесите Свену припасы. ', 'Припасы нам очень пригодятся. Семья Кэрвинов не оставляет нас без помощи. Вот, прими награду за труды.', 'С первого взгляда ты кажешься опытным бойцом, $C. Хочешь пополнить наши ряды?', NULL, NULL, 'Припасы для Свена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (165, 'Отшельник', 'Одно время в город частенько приходил старик и покупал припасы, но в последнее время я его не видела. Он живет в хижине рядом с кладбищем Вороньего холма, если я верно запомнила. Не навестишь ли ты его? Вдруг с ним что-то случилось?', 'Навестите старика в хижине рядом с кладбищем Вороньего холма.', 'Илана Карвин? Хе-хе, да, разумеется, Карвин. $B$BНет, со мной все в порядке, но мне трудновато ходить в город. Дороги нынче опасные, а я не молодею. Может, ты окажешь старику пару услуг?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (166, 'Братство Справедливости', 'Осталось одно, последнее задание. Эдвин ван Клиф должен умереть. Хотя меня печалит сам факт вынесения человеку смертного приговора, для всего народа Западного Края будет гораздо лучше, если ван Клиф упокоится навечно. Принесите мне голову этого негодяя, когда с ним будет покончено.', 'Убейте Эдвина ван Клифа и принесите его голову Гриану Камнегриву.', '$N, вы проявили удивительную храбрость. Народное ополчение благодарит вас за службу народу Западного Края. Смерть ван Клифа станет началом конца для Братства Справедливости. Надеюсь, недалек тот прекрасный день, когда мир вновь снизойдет на эту честную землю.$B$BЧесть имею, сэр!', 'Как продвигается ваша охота на Эдвина ван Клифа?', NULL, NULL, 'Голова ван Клифа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (167, 'О, брат мой...', 'Мы находились в обширных шахтах Западного Края, скрытых глубоко под землями Луноречья. Понятия не имею, откуда явились эти мерзкие вороватые вонючки. Так или иначе – туннель обрушился на нас. Мне удалось выбраться, но остальные... о них я ничего не знаю.$B$BВдруг тебе повезет больше, чем мне? Я ищу своего брата. Он всегда носил значок Лиги исследователей. Если ты не найдешь брата, постарайся найти хотя бы его значок.', 'Принесите значок Лиги исследователей, принадлежавший штейгеру Чертополоху в Штормград.', 'Мои подозрения оправдались. Бедный мой брат... Что ж, благодарю. Определенность лучше загадок, даже если она лишает надежды.', 'Нет ли у тебя каких-либо известий о моем брате? Можно ли еще надеяться, ведь столько времени прошло?', NULL, NULL, 'Амулет Крапивца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (168, 'Сбор воспоминаний', 'Многие из моих друзей погибли в тот роковой день, когда обрушился штрек. Если тебя как-нибудь занесет в ту шахту в Луноречье, пожалуйста, постарайся добыть что-то, что поможет их опознать. А если найдешь их карточки Союза шахтеров, принеси их мне, я отправлю их семьям погибших.', 'Добудьте 4 карточки Союза шахтеров и верните их Вилдеру Крапивцу в Штормград.', 'Спасибо тебе, $N. Твоя помощь в посмертном успокоении жертв этой чудовищной трагедии была неоценимой. Их семьи будут тебе признательны.', 'Принеси мне карточки Союза шахтеров, которые принадлежали моим друзьям...', NULL, NULL, 'Карточка Союза шахтеров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (169, 'Разыскивается: Гат\'Илзогг', 'Розыск! Гат\'Илзогг, один из вожаков Черной горы, разыскивается за нападение на крепость Каменной Стражи и набеги на окрестности Приозерья. $B$BГат\'Илзогг крайне опасен. По последним сведениям, он находится в недавно захваченной крепости и замышляет новые преступления против королевства. Нашествие орков должно быть остановлено любой ценой. Храбрец, доставивший голову Гат\'Илзогга мировому судье Соломону, будет щедро вознагражден.', 'Убейте Гат\'Илзогга и принесите его голову мировому судье Соломону в Приозерье.', 'Великолепная работа, $N! Гат\'Илзогг вел своих громил в бой, и они убивали ни в чем не повинных людей. Мы отомстили ему. Это первый шаг на пути возвращения крепости королевству Штормграда!', 'Что это, $C?', NULL, NULL, 'Голова Гат\'Илзогга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (170, 'Новая угроза', 'Надеюсь, ты $gоказался:оказалась: здесь не случайно, $C. Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес.$B$BЯ слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались. Говорят, их полно в горах на юго-востоке и возле замерзшего озера.$B$BТак ведь и это еще не все! Недавно они напали на наш лагерь на западе и разгромили его!$B$BНам и так воинов не хватает, а тут еще эти гады... Послушай, $gприятель:подруга:, может, ты нам поможешь? Боюсь, иначе нам троггов не одолеть...', 'Убейте 6 троггов из племени Каменной Челюсти и 6 сильных троггов из племени Каменной Челюсти.', 'Если повсюду происходит то же, что и здесь, у нас, то, клянусь бородой Магни, нас ждет большая беда! Остается надеяться, что король и Совет придумают, что делать с этими проклятыми троггами, иначе нам конец.', 'Упорные твари эти трогги, правда ведь?', NULL, NULL, 'Трогг из племени Каменной Челюсти убито', 'Сильный трогг из племени Каменной Челюсти убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (171, 'Опекун Альянса', 'Ты $gбыл:была: очень $gдобр:добра: ко мне, $N. Я и представить не мог, что Детская неделя пройдет так весело. Спасибо. Я не хочу печалится из-за собственной судьбы – предки всегда говорили мне, что я должен быть выше всех несчастий. Знаешь, когда я вырасту, я хочу стать героем... как ты.$B$BКак ни жаль, мне пора домой. Давай вернемся, и я расскажу нашей попечительнице, что ты лучше всех!', 'Отведите своего подопечного в приют Штормграда, вернув детскую свистульку попечительнице сирот Найтингейл в Храмовый квартал.', '', NULL, NULL, NULL, 'Свисток ребенка-сироты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (172, 'Детская неделя', 'Можешь ли ты помочь нам позаботиться о сиротах? $gБлагословен будь, друг:Благословенна будь, дева: помощь твоя во время Детской недели неоценима.$B$BВозьми этот свисток. Ты сможешь использовать его только во время Детской недели. Свистни в него – и сможешь поговорить с ребенком, о котором будешь заботиться. Свистни еще раз – ребенок уйдет.$B$BВсе очень просто, $N: используй свисток и заботься о ребенке. Любой сирота будет рад встрече с тобой.', 'Продудите в орочью детскую свистульку. Присматривайте за сиротой в течение всей Детской недели.', 'Заг-заг! Меня зовут Грент. Ты теперь мой опекун, да? Ты ищешь приключений, совсем как мои мама с папой! Наша попечительница говорит, что они с честью погибли в бою! Я так рад с тобой познакомиться!$B$BА мы теперь будем все делать вместе? Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь все равно как старший брат. Вот здорово!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (173, 'Воргены в лесу', 'На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом. Благодаря нашим усилиям народ Темнолесья живет в безопасности.$B$BТы считаешь, что $gдостоин:достойна: вступить в наши ряды?$B$BКогда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Кэрвина. Если ты хочешь показать, на что $gспособен:способна:, то слова тебе не помощники.$B$BВыступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду.', 'Калор из Темнолесья просит вас убить 6 тенеткачей Ночной Погибели.', 'Твои успехи впечатляют, $N. Похоже, ты на многое способен. Пожалуй, твоим талантам следует найти более достойное применение.$B$BВпрочем, вот что интересно... Воргены появились словно из ниоткуда. Но, с другой стороны, в наши границы вторглось такое количество странных существ, что это не самая большая проблема.', '$N, как успехи на охоте?', NULL, NULL, 'Маг теней из стаи Ночной Погибели убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (174, 'Взгляни на звезды', 'Один мой друг, гном по имени Ког, обещал мне помочь создать устройство, которое позволит изучать звезды. Уверен, что есть и иные объяснения творящемуся в лесу, чем магическое вмешательство.$B$BПринеси мне бронзовую трубку, изготовленную искусным инженером. Согласно чертежам Кога, это шаг номер один.', 'Принесите Виктору Призм\'Антрасу бронзовую трубку. ', 'Великолепно, $N! Первый шаг мы сделали успешно!', 'Тебе удалось отыскать искусного инженера и сделать бронзовую трубку?', NULL, NULL, 'Бронзовая труба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (175, 'Взгляни на звезды', 'Согласно чертежам Кога, мне нужно отыскать способ отражать свет. Помнится, есть у нас одна особа по имени Мэри, которая вечно таскает с собой зеркальце. Может быть, ты отыщешь ее и она одолжит нам свою отражающую поверхность? Кажется, она когда-то жила в южной части Сумеречного леса.', 'Найдите Мэри и уговорите ее пожертвовать зеркало для проекта Виктора.', 'Все верно, у меня некогда было зеркальце.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (176, 'Разыскивается: \"Дробитель\"', 'Разыскивается: Дробитель$B$BВ юго-западной части Элвиннского леса поселился могучий гнолл по прозванию Дробитель. Несмотря на все усилия, поймать его так и не удалось.$B$BАрмия Штормграда назначила за этого гнолла щедрую награду. Чтобы получить ее, необходимо представить маршалу Дугхану доказательства смерти Дробителя.', 'Убейте Дробителя и принесите маршалу Дугхану большой коготь гнолла', 'Ха! Отличная работа! А я уже было думал, что никому не под силу совладать с этим чудовищем!$B$BВот твоя награда, $N, а с ней прими и мою благодарность: этот гнолл у нас уже вот где сидел!', 'О да, этот Дробитель мне и моим людям немало крови попортил... Ты можешь о нем что-нибудь сообщить?', NULL, NULL, 'Коготь большого гнолла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (177, 'Взгляни на звезды', 'Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье. После этого я зашвырнула стекляшку за амбар. Одно время там бродил Невменяемый Вурдалак. Может быть, он утащил мое зеркальце. Говорят, что теперь эта тварь живет на Безмятежном кладбище.', 'Заберите зеркало Слепой Мэри у Невменяемого Вурдалака и отдайте его Виктору в Темнолесье.', 'Шедеврально! Это непременно сработает. Я глубоко признателен!', 'Я показал Когу наш прибор для изучения звезд, и он его одобрил. Ты не добыл отражающее устройство?', NULL, NULL, 'Зеркальце Мэри', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (178, 'Поручение Теокрита', '*До вас доносится голос...*$B$BНе пугайся. Я Теокрит, верховный маг башни Азоры в Элвиннском лесу. При помощи этой подвески гноллы из стаи Темношкуров общаются со своим повелителем Моргантом.$B$BЯ потратил много времени на то, чтобы тоже научиться вещать через эти подвески. Если ты слышишь мое сообщение, значит, заклинание сработало.$B$BПринеси мне эту подвеску, и я щедро вознагражу тебя.', 'Принесите выцветшую подвеску Темношкуров верховному магу Теокриту в Башню Азоры, что в Элвиннском лесу.', 'Благодарю тебя, $N. Я передал это сообщение через подвески Темношкуров несколько недель назад и полагал, что заклинание не сработало. Оказывается, в конечном итоге оно достигло по меньшей мере некоторых из них.$B$BХочется верить, что рано или поздно я научусь посылать таким образом боевые заклинания и обездвиживать тех гноллов, которые носят эти подвески.$B$BК сожалению, до этого еще очень далеко.', 'Говоришь, ты слышал мой голос из подвески? Хм-м-м... Дай-ка ее мне, надо ее как следует изучить.', NULL, NULL, 'Выцветшая подвеска Темношкуров (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (179, 'Дворфские экипировщики', 'Ну-ка, ну-ка, что тут у нас?.. Холодновато в наших краях, верно? Готов спорить, у тебя все время мерзнут руки. Ну, угадал?$B$BЯ скажу, что тебе нужно: пара хороших теплых перчаток. Ну да, душа у меня добрая, так что замерзнуть я тебе не дам. Только вот есть одно условие.$B$BПринеси мне волчьего мяса – и мы, считай, в расчете. Справедливо, как думаешь? Мне – мясо, а уж я-то позабочусь о том, чтобы у тебя пальцы больше не мерзли. Ну, что скажешь?', 'Принесите Стену Крепкоруку 8 кусков жесткого волчьего мяса.', 'О! Прекрасно! Волчье мясо – это то, что надо!.. Не беспокойся, $N, свою часть сделки я выполню честно. Вот, посмотри, что из этого тебе подойдет.', 'Что, потрепали тебя волки? Да уж, когти и клыки – это тебе не шуточки!', NULL, NULL, 'Жесткое волчье мясо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (180, 'Разыскивается: лейтенант Фангор', 'Разыскивается: лейтенант Фангор$B$BГлава гнолльской стаи Темношкуров, соратник Морганта, врага Города и Королевства. По приказу чиновника Соломона подлый предатель Штормграда приговаривается к смерти. Тот, кто приведет приговор в исполнение, должен в доказательство принести лапу Фангора мировому судье Соломону.', 'Убейте лейтенанта Фангора и принесите его лапу мировому судье Соломону в Приозерье.', 'Значит, злобный лейтенант Фангор мертв? Прекрасно. Ты удивительно храбрый $C. Городской совет Приозерья благодарит тебя за помощь.', 'Какие новости ты несешь Суду?', NULL, NULL, 'Лапа Фангора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (181, 'Взгляни на звезды', 'Для завершения работы не хватает только одного предмета. Согласно чертежам Кога, нам нужна линза. Единственную подходящую линзу в наших краях будет нелегко достать.$B$BВ кургане на юге Сумеречного леса живет огр по имени Ззарк\'Вул. Если сможешь, принеси мне его монокль, и я использую его вместо линзы!', 'Отыщите Ззарк\'Вула в кургане на юге Сумеречного леса и принесите его монокль Виктору в Темнолесье.', 'Наконец-то! Устройство для изучения звезд готово! Спасибо тебе, $N. Я могу продолжить исследования...', 'Тебе удалось уговорить Ззарк\'Вула одолжить нам свой монокль для эксперимента?', NULL, NULL, 'Монокль огров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (182, 'Пещера троллей', 'Нас с моим братом Сениром отправили в Дун Морог, чтобы разведать, действительно ли там объявились тролли, и насколько серьезна эта угроза. Совету хватает хлопот с троггами, лишние проблемы им ни к чему.$B$BНасколько я видел, тролли не слишком хорошо закрепились в Холодной долине; в основном они живут в южной пещере. Как по мне, тут и армия не нужна: несколько крепких бойцов вполне управятся.$B$BМожет, и ты решишь поучаствовать в этом деле? Не за так, конечно: у меня есть что тебе предложить.', 'Убейте 10 троллей-подростков из племени Мерзлогривов по просьбе Грелина Белоборода.', 'Проклятые тролли! Да не озарит их Извечный Свет!$B$B*Шумно дышит; немного успокаивается.*$B$BЭти негодяи ввалились ко мне ночью и украли мои записи! У меня хватило ума не доверять этому негодному подмастерь...', 'Насколько я знаю, эти тролли происходят из клана Снежной Гривы. Боюсь, о них я не знаю больше ничего, что могло бы тебе пригодиться, Элрибар.', NULL, NULL, 'Молодой тролль из племени Мерзлогривов убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (183, 'Охотник на вепрей', 'Нет ничего лучше охоты на диких вепрей, верно?$B$BПравда, здесь, в Холодной долине, их расплодилось столько, что весь интерес пропадает. Их и загонять не надо – они злые, как демоны, и сами бросаются прямо на охотника. Я бы даже сказал, что этих злобных свиней так много, что и охотиться-то стало опасно...$B$BКороче говоря, я буду благодарен, если ты поможешь мне прикончить хотя бы нескольких кабанов.', 'Убейте 8 малых скальных вепрей по просьбе Талина Остроглаза. ', 'Отлично, просто отлично! Теперь я могу спокойно отдох... М-м... Заняться охотой. Благодарю за помощь, $N.', 'Как идет охота?', NULL, NULL, 'Малый скальный вепрь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (184, 'Документ Хмуроброва', 'Это закладная на ферму Хмуроброва в Западном Крае. Она подписана Теодором Хмуробровом и его женой, Верной Хмуробров. На обороте документа торопливо нацарапаны слова:$B$B\"Мы нажали на Хмуроброва и получили от него нужную бумагу. Если тебе захочется заполучить один из участков, она тебе пригодится.$B$BС Хмуробровами проблем не предвидится: я видел, как они покидают Западный Край, у них как раз телега сломалась.\"$B$BНаверное, Хмуробровы были бы рады получить этот документ назад...', 'Доставьте фермеру Хмуроброву документ на ферму. ', 'Ты представить не можешь, $N как мы тебе благодарны! Конечно, сейчас в этих краях приличным людям не место, но, может, времена переменятся, и тогда нам нужно будет предъявить эту бумагу на право владения землей.$B$BКонечно, многого я предложить не могу, но возьми хотя бы вот это...', 'У тебя бумага на мою ферму? Вот это да! Вот это здорово! Несколько дней назад ее украли какие-то мерзавцы... Я думал, назад мне ее уже не получить.$B$BПожалуйста, отдай мне эту бумагу. Конечно, мы сейчас уезжаем из Западного Края и вернемся не скоро, но наступят времена, когда она нам очень пригодится...', NULL, NULL, 'Документ Хмуроброва (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (185, 'Охота на тигров', 'Когда я была маленькой девочкой, отец научил меня искусству охоты на тигров.$B$BМолодых зверей гораздо проще выслеживать и убивать. Поэтому начнем с простого. Молодые тигры часто забредают к лагерю экспедиции.$B$BПостарайся выследить и убить несколько зверей.', 'Ажек Руак из экспедиции Эрнестуэя попросила вас убить 10 молодых тигров Тернистой долины.', 'Неплохо, $N. Пора тебе двигаться дальше.', 'Пока ты не научишься справляться с молодыми тиграми, о дальнейших уроках и речи быть не может.', NULL, NULL, 'Молодой тигр Тернистой долины убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (186, 'Охота на тигров', 'А ты учишься, $C. Посмотрим, как ты справишься со взрослыми кошками. На сей раз тебе предстоит убить 10 тигров Тернистой долины.', 'Ажек Руак из экспедиции Эрнестуэя попросила вас убить 10 тигров Тернистой долины.', 'Впечатляюще, $C. Ты делаешь успехи.', 'Если ты жаждешь великих свершений, докажи сначала, что способен на малые. Убей 10 тигров Тернистой долины и возвращайся.', NULL, NULL, 'Тигр Тернистой долины убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (187, 'Охота на тигров', 'Поднимем ставки. Докажи, что сможешь убить 10 старых тигров Тернистой долины. Справишься – и я признаю, что ты $gготов:готова: к последнему испытанию, после которого я объявлю тебя великим охотником на тигров в присутствии мастера Эрнестуэя.$B$BСтарые тигры Тернистой долины неуловимы для врага и безжалостны в схватке.', 'Ажек Руак из экспедиции Эрнестуэя попросила вас убить 10 старых тигров Тернистой долины.', 'Очень, очень неплохо. Думаю, ты почти готов.', 'Прежде чем перейти к последнему заданию и претендовать на звание великого охотника, убей 10 старых тигров Тернистой долины.', NULL, NULL, 'Старый тигр Тернистой долины убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (188, 'Охота на тигров', 'Вот твое последнее испытание. Мы уже много недель выслеживаем эту хитрую тигрицу, прозванную Син\'Далл. Интересно, сможешь ли ты сделать то, что не удавалось ни $gодному:одной: $r – выследить и убить Син\'Далл. Принеси мне ее лапу в доказательство своего подвига.$B$BДаже выследить ее – непростая задача.', 'Ажек Руак из экспедиции Эрнестуэя просит вас убить Син\'Далл и принеси ее лапу.', 'Впечатляюще, должна сказать! Ты великий Охотник на тигров, $N!', 'Как идет охота на Син\'Далл?', NULL, NULL, 'Лапа Син\'Далл', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (189, 'Уши троллей Кровавого Скальпа', 'Проклятые тролли! Они постоянно убивают наших агентов! Я потерял в стычках с ними лучших своих бойцов. Цена операции все растет и растет! Как я объясню это барону Ревилгазу?$B$BНужно действовать решительно... Думай, Кебок... Тебя назначили на эту должность не за безделье... Придумал! Тебя... $N зовут, правда? Ты ведь мне поможешь? А уж я заплачу!$B$BПредлагаю сделку... ты принесешь мне уши пятнадцати троллей из племени Кровавого Скальпа, а я дам тебе денег.', 'Добудьте 15 ушей троллей из племени Кровавого Скальпа и принесите их Кебоку в Пиратскую Бухту.', 'Отлично, отлично. Это временно решит проблему…$B$B*Он принимается бормотать себе что-то под нос насчет огромных издержек…*$B$BЧто? Ты все еще здесь? Награда? А, да... Разумеется, бери... этого должно с лихвой хватить.', 'Ну как, надеюсь, успешно? Проклятые тролли кишмя кишат! Грязные твари.$B$BКстати, мое предложение и на твоих друзей распространяется! Тебе не помешает помощь!', NULL, NULL, 'Ухо тролля из племени Кровавого Скальпа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (190, 'Охота на пантер', 'Если ты хочешь отправиться на охоту вместе с нами под предводительством Хеминга младшего, докажи, что умеешь выслеживать пантер. Не бойся, начнем с простого. Для примера убей 10 молодых пантер.$B$BВыследить их - только полдела...', 'Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил вас убить 10 молодых пантер.', 'Доброе начало, $N!', NULL, NULL, NULL, 'Молодая пантера убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (191, 'Охота на пантер', 'А теперь задача потруднее. Если ты хочешь доказать, что $gдостоин:достойна: общаться с настоящими охотниками, убей 10 пантер.$B$BС этими ребятами не так легко справиться, они посильнее молодых зверей, с которыми тебе приходилось сталкиваться прежде.', 'Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил вас убить 10 пантер.', 'Великолепно, $N!', 'Иди, убей 10 пантер! Покажи, на что способен.', NULL, NULL, 'Пантера убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (192, 'Охота на пантер', 'Усложняем задание. Настоящий охотник сможет одолеть даже тенебрюхих пантер, самых опасных в Тернистой долине. Докажи, что сможешь прикончить 10 таких тварей.$B$BЕсли тебе покажется, что их трудно выслеживать, попробуй для начала убить одну...', 'Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил вас убить 10 тенебрюхих пантер.', 'Молодец, $N!', NULL, NULL, NULL, 'Тенебрюхая пантера убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (193, 'Охота на пантер', 'Тебе почти удалось доказать, что ты $gвеликий охотник:великая охотница: на пантер. И все же остается одна пантера по имени Баг\'тира.$B$BДобудь ее клык, и мое уважение тебе обеспечено!', 'Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил принести ему клык Баг\'тиры.', 'Итак, великая Баг\'тира мертва! Браво, $N. Ты и правда могучий $C!', 'Баг\'тира – хитрый зверь. Как идет охота?', NULL, NULL, 'Клык Баг\'тиры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (194, 'Охота на ящеров', 'Значит, ты считаешь себя $gпревосходным охотником:превосходной охотницей:? Проверим. Ступай в джунгли и подстрели 10 ящеров Тернистой долины. Посмотрим, как ты справишься с крупной дичью.$B$BИ нет, я не скажу, где их искать! Первая половина испытания – поиски зверя.', 'Хеминг Эрнестуэй младший просит вас убить 10 ящеров Тернистой долины.', 'Неплохо, старина!', 'Мне не доводилось встречать охотников, которые добывали дичь, попусту ошиваясь у костра – конечно, не считая моего отца. Ты собираешься подстрелить этих ящеров или будешь ждать, когда они умрут от старости?', NULL, NULL, 'Ящер Тернистой долины убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (195, 'Охота на ящеров', 'А теперь я задам тебе задачку, посмотрим, придется ли она тебе по вкусу. Отправляйся в джунгли и добудь 10 ящеров-кнутохвостов. Увидим, хватит ли тебе пороху!', 'Хеминг Эрнестуэй младший попросил вас убить 10 ящеров-кнутохвостов.', 'Именно так и появляются трофеи над камином! Неплохая охота, $N!', NULL, NULL, NULL, 'Ящер-кнутохвост убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (196, 'Охота на ящеров', 'Посмотрим, как ты справишься со следующим испытанием. Здесь живут хитрые ящеры, мы зовем их тропическими ловцами. Их гораздо труднее выследить и убить, чем другие виды, с которыми тебе пришлось столкнуться. Убей 10 тропических ловцов, и я соглашусь, что из тебя еще выйдет $gнастоящий охотник:настоящая охотница:.', 'Хеминг Эрнестуэй младший попросил вас убить 10 тропических ловцов. ', 'Хо-хо!!! У нас есть настоящий убийца ящеров! Неплохо, старина!', 'Ба! Что ты здесь делаешь? Настоящий охотник никогда не сдается, пока в поле зрения есть дичь. Не думаю, что тропические ловцы сами прибегут сюда и бросятся в костер. Глупый мальчик.', NULL, NULL, 'Хищник джунглей убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (197, 'Охота на ящеров', 'Ну, раз ты ходишь в джунгли как к себе домой, дай-ка я расскажу тебе о свирепом ящере, которого даже мне не удалось убить. Ажек называет этого хитрого ящера Тетис.$B$BЕсли ты хочешь показать подлинное мастерство, убей Тетис и принеси мне его коготь. Этот подвиг не удался еще ни одному охотнику!', 'Хеминг Эрнестуэй младший попросил вас убить Тетис, хитрого, опасного ящера Тернистой долины.', 'Великий $N, убийца ящеров!$B$BНеплохо звучит, а?', 'Как идет охота на Тетис? Я так понимаю, ее следы вели к нашему лагерю?', NULL, NULL, 'Коготь Тетис', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (198, 'Припасы для рядового Торсена', 'Хммм. У меня и правда есть для тебя дело. Лейтенант Дорен и его последователи там, на севере, регулярно получают от нас поставки еды и оборудования.$B$BПришло время доставить очередную партию, а, учитывая нападения троллей, никто не хочет за это браться. Лагерь Дорена располагается на северо-западе от дороги у входа в Тернистую долину из Сумеречного леса. Отнеси эту посылку рядовому Торсену, а если его нет в лагере, значит, он дежурит на юге от него. Он займется этими припасами.$B$BУчти, если ты провалишь задание, придется тебе возместить мои затраты.', 'Доставьте различные припасы гоблинов рядовому Торсену. ', 'Эти мины помогут нам защититься от этого зверя, Курцена, и его людей. Спасибо за доставку. Если тебе нужна работа, может быть, я смогу помочь тебе. И тебе не придется иметь дело с гоблинами, а?', 'Да? Что тебе нужно? А, припасы гоблинов. Странно, что их доставил $C, обычно они сами этим занимаются. Не важно... Ты ведь их не касался? Славно, славно... Мы бы не хотели, чтобы с нашими минами что-нибудь случилось, о нет.', NULL, NULL, 'Различные припасы гоблинов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (199, 'Прямая и черная угроза', 'Вы берете образец странно пахнущего порошка.', 'Вернитесь к главному инженеру Плотиннеру и покажите ему найденную улику.', 'Это тревожная находка, мягко говоря!', 'Ну как, нашел улики?', NULL, NULL, 'Странно пахнущий порошок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (200, 'Букмекер Ирод', 'Если Курцену известна тайна Торсена, значит, в наши ряды затесался шпион. Необходимо выяснить, откуда просочилась информация!$B$BСвязным Торсена в лагере Курцена был букмекер Ирод. Ирод работает снабженцем у Курцена, и знает все о его лагере. Если удастся добыть его записи, быть может, мы узнаем, как накрыли Торсена.$B$BКогда мы служили в войсках Курцена, кабинет букмекера располагался на верхнем этаже единственного двухэтажного дома в лагере. Скорее всего, его записи по-прежнему там.', 'Найдите записи букмекера Ирода. ', 'Вы находите записи букмекера Герода.$B$BСреди них: список поставок в лагерь, запросы от полковника Курцена и различные письма.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (201, 'Поиск лагеря', 'Мне сообщили о группе охотников, разбивших лагерь вверх по реке от рудника Торговой Компании возле озера Назферити. Я бы не придал этому значения, но говорят, будто один из тамошних охотников - сам Хеминг Эрнестуэй младший. Мне не верится, но у него настолько высокие связи, если ты понимаешь о чем я, что лучше заранее обезопасить себя.$B$BПочему бы тебе не заглянуть в этот лагерь и не разузнать, что они замышляют?', 'Найдите лагерь охотников и сообщите о его местонахождении Кразеку из Пиратской Бухты.', 'Хмм, значит у меня были точные сведения, как обычно. Любопытно. Кажется, они не представляют для нас опасности, но, быть может, им нужны наши превосходные товары. Хммм...', NULL, NULL, NULL, 'Исследовать локацию', 'Отыщите лагерь охотников', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (202, 'Полковник Курцен', 'И снова ты $gпоказал:показала: нам, на что $gспособен:способна:. Кажется, талантов у тебя не меньше, чем у самого Курцена! Это может спасти нас, горстку повстанцев... если ты сможешь выступить против Курцена и одержать над ним верх!$B$BОн управляет своими людьми из глубин Схрона. Ступай в эту пещеру, пробейся сквозь ряды ее защитников, и одолей Курцена и его ближайших приспешников.$B$BПрощай, $N. Ты – наша последняя надежда.', 'Убейте 6 гвардейцев и 4 заместителей Курцена и принесите голову Курцена лейтенанту Дорену в Лагерь повстанцев.', 'Я не смел верить вестям, но ты несешь нам доказательство того, что... Курцен и его главные сторонники повержены. Ты спас нас всех!$B$BДжунгли полны различных угроз, но никто не мог сравниться с жестоким и умным Курценом. Теперь, когда его нет, мы можем вздохнуть спокойнее.', 'Смею ли я надеяться, что Курцен и его защитники мертвы, $N?', NULL, NULL, 'Гвардеец Курцена убито', 'Помощник Курцена убито', 'Голова Курцена', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (203, 'Второе восстание', 'Мы решительно проигрываем полковнику Курцену. Он не только блестящий тактик – его войска превосходят нас в численности в десять раз! Чтобы выжить, нам придется прибегнуть к его же подлой тактике.$B$BПроберись в лагерь на востоке и убей как можно больше его бойцов. И скройся до прибытия подкрепления.', 'Убейте 15 партизан Курцена.Вернитесь к сержанту Йохве в Лагерь повстанцев.', 'Отлично. Потеря опытных бойцов вынудит его ослабит натиск на наш лагерь.$B$BА ты не боишься быть на нашей стороне, зная, какие силы выступают против нас??', 'Надеюсь, охота оказалась успешной, $N. Нам не продержаться без твоей помощи.', NULL, NULL, 'Партизан Курцена убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (204, 'Дурное лекарство', 'Чтобы получить шанс выстоять против Курцена, нам необходимо лишить его лекарей. Он собрал немало целителей, которые лечат его войска зельями из джунглей и травят наших бойцов экстрактами ядовитого папоротника.$B$BНам и самим нужны эти составы. Обыщи поселок Курцена – лекарства находятся у его целителей и партизанов, а экстракты скорее всего хранятся в одном из ящиков с припасами.', 'Принесите сержанту Йохве из Лагеря повстанцев 7 порций зелья из джунглей и 1 порцию экстракта ядовитого папоротника.', 'Молодец, $N. Эти лекарства помогут нам выжить и сохранить боеспособность. А при помощи экстракта мы создадим собственные снадобья.', 'Я жду – не дождусь зелий и экстракта, $N.', NULL, NULL, 'Зелье из джунглей', 'Экстракт ядовитого папоротника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (205, 'Тролльское колдовство', 'Пока я изучаю принесенные тобой прорисовки, собери для меня принадлежности злой магии троллей. Тебе придется проникнуть в земли племени Дробителей Черепов, второго племени на далеком юге, и добыть фетиши у их знахарей и мистиков.', 'Принесите 4 фетиша троллей из племени Дробителей Черепов брату Нимезу в лагерь Повстанцев.', 'Спасибо. Я изучу эти фетиши и пойму, они ли причина того, что Курцен обратился ко злу.', 'Ты принес фетиши, $N? Должно быть, именно в них заключается секрет падения Курцена... Мне нужно это узнать!', NULL, NULL, 'Фетиш Дробителей Черепов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (206, 'Май\'Зот', 'Хотя Курцен и мертв, зло, соблазнившее его, живет! Вот что мне удалось выяснить: огрский маг – Май\'Зот – живет в огрском кургане в восточных горах Тернистой долины. Говорят, что он пользуется магией, овладевающей разумом, и я не сомневаюсь, что Май\'Зот виноват в падении Курцена.$B$BПока он жив, зло будет расползаться, и может даже появиться второй Курцен.$B$BУбей его и принеси мне его Око разума, артефакт, позволяющий ему творить темные дела.', 'Принесите Око разума брату Нимезу в лагерь Повстанцев. ', 'Ага! Тебе удалось убить его! На стороне добра действуют великие силы, $N! Да не ослабеет твоя рука!$B$BЯ исследую Око Разума и попытаюсь придумать, как пользоваться им во благо. Если это невозможно... его следует уничтожить.', 'Да пребудет с тобой мое благословение. Сила Май\'Зота сравнима лишь с чернотой его души.', NULL, NULL, 'Око разума', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (207, 'Тайна Курцена', 'Когда-то полковник Курцен был великим и благородным человеком – я хочу выяснить, что заставило его свернуть с пути истинного! Должно быть, он находится под воздействием магии троллей. Надо изучить древние легенды, чтобы убедиться в этом.$B$BВ руинах тролльских городов в Тернистой долине спрятаны 4 таблички. Мне необходимо их добыть и прочесть! Перерисуй с них все отметки и принеси рисунки мне.$B$BПервая табличка находится в Руинах Бал\'лал, вторая – на Коварном рифе, а третья и четвертая – в Руинах Зул\'Кунды.', 'Найдите 4 таблички, перерисуйте их и принесите их брату Нимезу.', 'Спасибо, $N. Я изучу твои рисунки и попытаюсь выяснить, есть ли связь между троллями и злом, одолевшим полковника Курцена.', '$N! У тебя есть прорисовки тролльских табличек? Я должен раскрыть их тайны!', NULL, NULL, 'Первое предание троллей', 'Второе предание троллей', 'Третье предание троллей', 'Четвертое предание троллей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (208, 'Охотник на крупную дичь', '$N, ты $gдостоин:достойна: занять место среди нас. И на полях битвы в Лордероне, и в глубоких джунглях, мне редко приходилось видеть столь умелое обращение с оружием.$B$BТебе удалось убить свирепую Син\'Далл, неуловимую Баг\'тиру и коварную Тетис. Осталось одно – добыть голову короля Бангалаша. Давненько я точу зуб на этого белого тигра и оказался здесь именно ради него. Убей короля Бангалаша, и мы признаем, что тебе нет равных в искусстве охоты.', 'Хеминг Эрнестуэй младший попросил вас принести ему голову короля Бангалаша, огромного белого тигра.', 'Отлично сработано! Здорово! Поздравляю, $N, ты преуспел там, где другие потерпели поражение.$B$BВидеть тебя в рядах нашего охотничьего отряда – это честь для меня. Отныне никто не усомнится в твоем искусстве охотника и следопыта.$B$BУра тебе! Ура!', 'Вижу, ты вернулся, старина. Мне не раз приходилось заползать в лагерь и зализывать раны после столкновения с королем Бангалашем. Побудь здесь.', NULL, NULL, 'Голова Бангалаша', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (209, 'Клыки троллей', 'Убивать тигров и добывать их клыки на экспорт в южные моря – трудно и дорого. К счастью, мы придумали способ обрабатывать простые рого-подобные предметы и изготавливать неотличимые подделки.$B$BЛучше всего, как ни смешно, подходят клыки троллей из племени Дробителей Черепов.$B$BШ-ш-ш, спокойно, чем меньше знает покупатель, тем крепче он спит, верно? Принеси мне побольше таких клыков, чтобы мы могли подготовить ежемесячную поставку!', 'Добудьте 18 клыков троллей из племени Дробителей Черепов и принесите их Кебоку в Пиратскую бухту.', 'А, хорошо, хорошо! Хотя ты мог бы получше счистить... Ну, неважно, неважно что. Спасибо, $N, благодаря тебе у нас возрастет производительность и доходы! Хорошо, хорошо, а теперь перейдем к следующему делу...', 'Сильные, заразы, а? Ну, как успехи? Не хочу показаться нетерпеливым, но это мне покою не дает. Так как?', NULL, NULL, 'Клык тролля из племени Дробителей Черепов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (210, 'Горшок Кразека', 'Готовка по большей части лежит на мне. И она доставляла мне много хлопот, пока я не купил механический горшок у одного гоблина в Пиратской Бухте. Это чудо какое-то! Он сэкономил мне много часов... Пока не сломался!$B$BМожет, ты отнесешь его назад к продавцу, в ремонт? Продавца зовут Кразек.', 'Отнесите разбитый горшок Кразека гоблину Кразеку. ', 'А, вижу, разбитый горшок Кразека! Отличное устройство, но иногда выходят из строя пружины или шестерни. Посмотрим, что случилось с этой штукой…$B$BАга! Заржавел паровой агрегат, полетел сальник, а у надувателя отломились зубья. Странно, как тут умудрялись хотя бы варить репу!$B$BМогу ли я это починить? Разумеется!$B$BНо не за бесплатно. Бесплатный бывает только сыр в мышеловке...', 'Привет! Ты что-то мне принес?', NULL, NULL, 'Разбитый горшок Кразека (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (211, 'Увы тебе, Андорал', 'Увы, пришло время напасть на Андорал и изгнать оттуда лича!$B$BЗлобный Араж Призыватель обосновался в самом сердце руин. Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы. Без многочисленных помощников тебе нечего и думать одержать над ним верх.$B$BУбей Аража и принеси мне его кристалл-талисман!', 'Принесите осколок оберега Араджа командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра в Западных Чумных землях.', 'Свершилось! Араж... этот лич наконец-то пал!$B$BСегодня ты оказал огро$Nю услугу Альянсу. Храбрость и упорство – спутники подлинного героизма. Прошу тебя, прими это в знак нашей благодарности. Пусть все знают, что благодаря тебе Альянс одержал победу!', 'Тебе было дано задание, $N. Ты принес мне кристалллича в доказательство его выполнения?', NULL, NULL, 'Осколок оберега Араджа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (212, 'Холодный обед', 'Одно из моих коронных блюд – мороженый василиск под соусом винегрет из лайма. Проблема лишь в том, что... Это мясо не подлежит хранению, а ведь я должен приготовить это блюдо сегодня вечером – на день рождения одного благородного господина! Если сможете, принесите мне охлажденный окорок только что убитого ледоглазого василиска, а я организую специально для вас царскую трапезу!$B$BЛедоглазые василиски обитают в дюнах на северо-западе Тернистой долины, так что путь вам предстоит неблизкий. И не задерживайтесь по дороге!', 'Убейте ледоглазого василиска и принесите его охлажденный окорок Ангусу Штерну в \"Синий Отшельник\".', 'О, вот это окорочок! Большое, просто огромное спасибо!$B$BА теперь попрошу меня простить, мне нужно быстренько нарубить мясо, замариновать его и сервировать для банкета.', '$N! Вы добыли окорок? Я должен уже начать его готовить, а не то весь банкет пойдет насмарку!', NULL, NULL, 'Охлажденный окорок василиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (213, 'Недружественное поглощение', 'Он слишком далеко зашел! Мало того, что этот Гелриз теснит управляющих, назначенных торговыми олигархами, теперь он попытался обвести вокруг пальца знаменитейшего пирата!$B$BРевилгаз заявил, что не потерпит такого, и велел любым способом решить проблему.$B$BЛюбым способом? Я выбираю кражу. Геологов Торговой Компании, работающих рядом с озером Назферити, заинтересовали странные синие кристаллы, найденные в руднике. Принеси мне образцы этих камней, и меня не волнует, что тебе придется сделать с геологами для выполнения задания.', 'Добудьте 8 упавших кристаллов и принесите их Кебоку в Пиратскую Бухту.', 'Любопытно. Огранка кристаллов говорит только о том, что они собираются пользоваться ими в качестве горючего или катализатора. Большего сказать я не могу. Образцы необходимо показать старшему химику Хихиканту.', 'Мне нужны эти камни, $N. Любой ценой! Подробности мне не нужны, только результат, ни больше, ни меньше.', NULL, NULL, 'Упавший кристалл', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (214, 'Красные шелковые банданы', 'Не секрет, что красные банданы являются отличительным знаком бандитов из Братства Справедливости. Но мы узнали, что материал, из которого они изготовлены, указывает на ранг члена Братства.$B$BЯ рассказываю тебе об этом, потому что прошу тебя устранить как можно больше бандитов высокого ранга. Обладающих наивысшим рангом, без сомнения, можно найти в тайном убежище ван Клифа. Когда справишься с заданием, принеси мне 10 красных шелковых бандан в доказательство их смерти – и получишь награду. Желаю удачи, $N.', 'Принесите 10 красных шелковых бандан разведчице Риэле к башне на Сторожевом холме.', 'Отличная работа $N! От имени народного ополчения я благодарю вас за ваши усилия. Вскоре с помощью таких смельчаков, как вы, мы вернем эту землю ее народу.', 'Избавили ли вы нашу землю от бандитов из Братства Справедливости? Если да, предъявите в качестве доказательства 10 красных шелковых бандан.', NULL, NULL, 'Красная шелковая бандана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (215, 'Тайны джунглей', 'Спасибо, что $gспас:спасла: меня, $N. Понимаю, как это выглядит... но позволь мне объяснить.$B$BЛейтенант Дорен поручил мне снова завербоваться к Курцену, чтобы следить за его солдатами и предоставлять столь необходимые сведения повстанцам. Ты $gвидел:видела:, чем обернулась для меня попытка проникнуть в лагерь Курцена. Я думал, что это - мой шанс... Еще раз спасибо за спасение.$B$BЭто была тайная миссия, никому о ней не говори. Но лейтенант Дорен может все объяснить.', 'Поговорите с лейтенантом Дореном в Лагере повстанцев.', 'Да, Торсен сказал тебе правду. Только помалкивай об этом. Одно время мы, повстанцы, были слепо преданы полковнику Курцену. Но сейчас он перешел на сторону зла, и наша верность обратилась в ненависть. Если кто-нибудь узнает, что рядовой Торсен имел дело с людьми Курцена, однажды утром мы можем найти его с перерезанным горлом.$B$BНасколько мне известно, о задании Торсена знала только сержант Йохва и я. И кто-то еще. Предатель.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (216, 'Между молотом и Колючим Мехом', 'Фурболги из племени Колючего Меха мешают нашему продвижению! Деревня Колючего Меха, что лежит на востоке, преграждает нам путь к заставе Расщепленного Дерева. Это на дороге, что идет в обход деревни Астранаар. Если мы не будем ее контролировать, Альянс получит дополнительный путь для вторжения.$B$B$N, мы должны заткнуть эту дыру!$B$BИди в деревню Колючего Меха да устрой фурболгам прореживание. Выполнишь задачу – получишь награду, но важнее будет то, что ты выполнишь свой долг перед Ордой!', 'Убейте 8 мстителей из племени Колючего Меха и 8 шаманов из племени Колючего Меха. Большинство из них находятся к востоку от Зорамского взморья в деревне Колючего Меха. Выполнив задачу, возвращайтесь к Карангу Амаккару в форт Зорам\'гар, что в Ясеневом лесу.', 'Отлично, $C, отлично! Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что еще одна дорога расчищена от сил Альянса. Теперь завоевание Ясеневого леса Ордой пойдет полным ходом!$B$BТы заслужил свою награду, герой! Честь и слава тебе!', NULL, NULL, NULL, 'Мститель из племени Колючего Меха убито', 'Шаман из племени Колючего Меха убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (217, 'Защита королевских земель', '$N, наши разведчики обнаружили предводителя троггов. Похоже, этих тварей привел к озеру Лок Модан их вождь по имени Громаг. Его хорошо охраняют. Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят.$B$BЕсли ты $gуверен:уверена: в своих силах, $N, можешь возглавить операцию по ликвидации Громага и его громил. Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю.', 'Убейте предводителя троггов Громага и его охранников, Скрежетуна и Буяна. Сообщите об этом капитану Ругельфассу, ожидающему вас в южной сторожевой башне.', 'Превосходно, $Nт! Ты вернул надежду Лок Модану. Громаг мертв, и у нас появилась надежда изгнать троггов из наших земель.', 'Громаг и его охранники, Скрежетун и Буян, все еще живы. Задание не выполнено, покуда все трое живы. Все дворфы рассчитывают на тебя, $N.', NULL, NULL, 'Громаг убито', 'Костеглод убито', 'Буян убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (218, 'Украденные записи', 'Мои записи! Они уволокли в свою мерзкую пещеру мои записи! Здоровенный громила, весь разрисованный с головы до ног... Жаль, я не смог разглядеть его получше!$B$BПослушай, тебе ведь уже приходилось иметь дело с троллями? Может, ты сумеешь вернуть мои драгоценные записи?..', 'Убейте Грик\'нира Холодного и верните Грелину его записи.', 'Великолепно, $N! Словами не передать, как я благодарен! Мои записи, наконец-то!.. Да к тому же, похоже, троллей Холодной долины удалось-таки обуздать, так что больше беспокоиться не о чем.$B$BКстати, послушай: я скоро закончу свое донесение – так, может, ты поработаешь курьером и доставишь его моему братцу Сениру?', 'А, $N! Ну, как дела?', NULL, NULL, 'Записи Грелина Белоборода', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (219, 'Пропавший без вести', 'Наконец-то, сторонники Альянса!$B$BПомогите... Пожалуйста...$B$BПоследнее, что я помню – как орки окружили наш отряд. Меня ударили по затылку, и в глазах потемнело. А теперь я пленник в этой пещере. Спасите меня, я тяжело ранен.$B$BМне понадобится помощь, чтобы добраться до города... Пожалуйста... Вы моя последняя надежда...', 'Проводите капрала Кишана до Красногорья.', 'Ты отлично послужил Королевству, $C. Благодарю тебя за помощь капралу Кеешану. Одному ему не удалось бы сбежать от орков Черной Горы. Подобная храбрость заслуживает великой награды.', 'Да?', NULL, NULL, 'Проводите капрала Кишана до Красногорья.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (220, 'Зов воды', 'Прежде чем дать тебе в награду следующий тотем, Ислен поручит тебе еще одно задание. Для этого понадобится фиал с водой, который я дал тебе.$B$BСтупай, поговори с ней. Мы еще встретимся.', 'Отнесите фиал с чистейшей водой Ислен Заклинательнице Воды к Лестнице Прилива, что в Степях.', 'А, фиал с водой, созданной и благословленной Брин и добытой тобой, ни больше ни меньше.$B$BЖидкость в этом фиале необходима для создания сапты, но годится и для других целей.$B$BПри помощи этой сапты ты сможешь разглядеть водных духов в святилище в Серебряном бору, к югу от Подгорода. Что же до оставшихся капель... о них я расскажу тебе потом.$B$BНе боишься долгого пути, $N?', 'И снова здравствуй, $N. Выглядишь ты неплохо.$B$BЧто привело тебя ко мне?', NULL, NULL, 'Фиал с чистейшей водой (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (221, 'Воргены в лесу', 'Может, ты $gзаметил:заметила: крупных воргенов, бродящих по лесу в компании тенеткачей? Судя по всему, большую часть воргенских сил и составляют эти самые вестники Тьмы.$B$BСтранствуя по лесу, я узнал, что они захватили и Гниющий сад на юго-западе от города. Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться.$B$BБудь $gосторожен:осторожна:.', 'Убейте 12 вестников Тьмы из стаи Ночной Погибели. ', 'Ты достойно выступил против вестников Тьмы, $N. Но, похоже, ряды их нескончаемы. На место убитых становятся все новые и новые воргены.$B$BЧто за злая сила притягивает их сюда? Зачем они явились терзать наш несчастный город... $B$BЯ возлагаю надежду на мастера Кэрвина. Не сомневаюсь, он разберется с этой проблемой.', 'Уже вернулся, $N? Надеюсь, ты не собираешься отказываться от задания?', NULL, NULL, 'Вестник Тьмы из стаи Ночной Погибели убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (222, 'Воргены в лесу', 'Твои прежние достижения наводят меня на мысль, что ты можешь схватиться с сильнейшими из воргенов, наводнивших наши леса.$B$BСамими опасными из всех оказались Ярые Клыки и нечистые воргены. Они живут рядом с пещерами и в руднике на юге.$B$BЗарево их костров видно издалека.', 'Калор просит вас убить 8 Ярых Клыков из стаи Ночной Погибели и 8 нечистых воргенов из стаи Ночной Погибели.', 'Честно говоря, $N, я не верил, что ты справишься с этой задачей, но ты воистину могучий $C. Более того, если ты хочешь официально присоединиться к борьбе мастера Кэрвина, я с радостью напишу тебе рекомендательное письмо.', NULL, NULL, NULL, 'Ярый Клык Ночной Погибели убито', 'Нечистый ворген из стаи Ночной Погибели убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (223, 'Воргены в лесу', 'Вот, $N. Отнеси это письмо мастеру Кэрвину.$B$B<Он отдает вам поблекший пергамент.>$B$BЕсли к нам потянутся такие, как ты, в отряде будет больше людей, чем в Ночном дозоре! Быть может, тогда мы завершим работу, которую сейчас делаем с большим трудом.', 'Отнесите записку Калора Джонатану Карвину.', 'Прости за холодный прием, $N, ты ведь понимаешь, что я очень занятой человек. Вижу, ты произвел впечатление на Калора. Уверяю тебя, это нелегко. Так или иначе, он рекомендует принять тебя в наши ряды.$B$BВокруг полно ненадежных людей, а нам нужна помощь тех, на кого можно положиться. Мы бьемся против демонов, нежити и их пособников. Не теряй бдительности, осторожности и не доверяй никому, кто не хочет нам помочь.$B$BДа озарит тебя Свет!', 'Да, что тебе нужно? Быстрее, у меня полно неотложных дел.', NULL, NULL, 'Записка Калора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (224, 'Защита королевских земель', 'Мы должны защитить озеро Лок, $N! Множество королевских солдат проливает кровь в далеких землях, а наш родной край в опасности. Трогги полезли изо всех щелей! Нашествие троггов грозит безопасности Стальгорна. Пора истребить мерзких мутантов!$B$BНам нужна твоя помощь, $gотважный искатель приключений:отважная искательница приключений:. Ступай и устрани нависшую над нами угрозу. Убей 10 троггов из племени Камнедробов и 10 разведчиков из племени Камнедробов и возвращайся.', 'Горный пехотинец Кремневик просит вас убить 10 троггов из племени Камнедробов и 10 разведчиков из племени Камнедробов.', 'Молодчина, $N! Ты проявил немалое мужество на поле боя. Побольше таких, как ты, и мы победим троггов. Ты славно послужил королю Магни.$B$BЕсли тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером. Капитан дал ему непростое задание. Уверен, ему понадобится помощь. Поговори с Булыжным Карьером, он сейчас в башне.', 'Лок Модан в осаде, $N! Все сторонники Альянса, способные держать оружие, должны нам помочь. Ты уже убил 10 тТитанов из племени Камнедробов и 10 разведчиков из племени Камнедробов?', NULL, NULL, 'Трогг из племени Камнедробов убито', 'Разведчик из племени Камнедробов убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (225, 'Заброшенная могила', 'Надпись на древнем могильном камне гласит:$B$BМОРГАН ЛАДИМОР$B$B*При внимательном рассмотрении вы замечаете, что могилу недавно раскапывали, и большая часть земли насыпана заново...*', 'Поговорите с Широй Фон-Инди в Темнолесье.', 'Морган Ладимор?$B$BА-а-а, да, разумеется. У него долгая и печальная история. Я знал его до того, как он ушел на войну, но с тех пор ни разу не видел. Он был добрым и благородным человеком, но окончил свою жизнь плохо.$B$BПодожди-ка, я дам тебе вещь, которая поведает его историю лучше, чем я...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (226, 'Волки идут по пятам', 'Нас со Свеном ждут трудные времена, учитывая, что на востоке поселился Некромант. Мы здесь совсем одни, приходится самим добывать себе еду. Такое впечатление, что всякий раз, как я возвращаюсь в лагерь, неся добычу, за мной увязывываются лютые волки. Что и говорить, жить здесь опасно!$B$BНо если ты избавишь нас хотя бы от части волков, нам станет полегче. Они живут на севере и на востоке отсюда, возле реки.', 'Убейте 12 голодных лютых волков и 8 бешеных лютых волков. Вернитесь к Ларсу в лагерь Свена на западной границе Сумеречного леса.', 'О, хорошо. Ты здорово проредил волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном.$B$BВот, возьми в награду взрывпакеты. Их делают в городе, и Свену недавно выделили целую партию.', 'Охота еще не закончена?..', NULL, NULL, 'Голодный лютый волк убито', 'Бешеный волк убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (227, 'Морган Ладимор', '*Он роется на полках и вытаскивает книгу в кожаном переплете.*$B$BЕсли хочешь узнать побольше, спроси Альтею, она занималась... проблемами... возникшими с ним в последнее время.', 'Поговорите с командиром Альтеей Чернодрев в Темнолесье.', 'Морган Ладимор? Никогда о нем не слышала...$B$BА, ты о Мор\'Ладиме! Ты не знаешь его историю?$B$BЧто ж, я объясню тебе вкратце. По Сумеречному лесу бродит неупокоенный мертвец, зовущий себя Мор\'Ладимом. Судя по всему, это восставшее из могилы тело Моргана Ладимора, о котором ты, кажется, уже слышал. Он доставил нам массу неприятностей – начиная от нападения на патрульных и заканчивая убийствами простых людей.$B$B*Она смеривает вас взглядом.*$B$BКажется, ты смог бы помочь ему упокоиться с миром.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (228, 'Мор\'Ладим', 'Разведчики сообщают, что Мор\'Ладим бродит по кладбищу. Мы похоронили его за домом на холме, знаешь, где это?$B$BБольше я тебе ничем помочь не могу... Разве что пожелать удачи.', 'Убейте Мор\'Ладима и отнесите его череп командиру Альтее Чернодрев в Темнолесье.', 'Ты убил его? Это великий подвиг, $N! Прими благодарность от имени народа Темнолесья и Ночного дозора.$B$BАх, да... Осталось еще одно дело...', 'Я не буду винить тебя, если тебе не удастся справиться с ним, $N. Мор\'Ладим отнял жизни у сильнейших из наших воинов.', NULL, NULL, 'Череп Мор\'Ладима', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (229, 'Выжившая дочь', 'Надо было предупредить тебя раньше…$B$BКак бы тебе сказать…$B$BМорган думал, что у него погибла вся семья, но его дочь, Сара Ладимор, жива и служит в Ночном дозоре. Ее всегда беспокоили... обстоятельства... связанные с гибелью ее отца. Быть может, ты сообщишь ей о случившемся.', 'Поговорите с Сарой Ладимор в Темнолесье.', 'Да? Мой отец…$B$B*Она опускает глаза.*$B$BЖаль... что я не могу ничего для него сделать... Ах, если бы я поговорила с ним до того, как...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (230, 'Лагерь Свена', 'Порывшись в груде земли, вы находите небольшую книгу, перепачканную грязью.$B$BЗаглавие не указано, зато в ней содержатся сведения, необходимые Свену.', 'Принесите Свену книгу, найденную на ферме Свена. ', '*Свен прочитывает несколько страниц и захлопывает книгу.*$B$BЭтот таинственный незнакомец – свидетель смерти моей семьи! У меня столько вопросов к этому человеку... Узнать бы, кто он!', 'Что ты нашел?! Пожалуйста, дай посмотреть...', NULL, NULL, 'Книга с фермы Свена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (231, 'Дочерняя любовь', 'Возьми это кольцо и отнеси на его могилу. Может быть... может быть, он поймет, что я жива и никто не винит его в случившемся.$B$B*Со слезами на глазах она снимает кольцо с правой руки и отдает вам.*$B$BИ... спасибо, $N.', 'Отнесите кольцо Сары Ладимор на могилу Моргана Ладимора. ', '*В шорохе ветра слышится призрачный голос...*$B$BЧто это?.. Сара? Неужели она жива? Камень с сердца…$B$B$N. Возьми мой меч, Принцип. Моя душа упокоилась, и он более мне не нужен. Он был выкован во имя добра, а я оказался не достоин владеть им. Быть может, ты сможешь нести Свет вместо меня.$B$BЛиз, любовь моя...', 'Оставь меня в покое...', NULL, NULL, 'Кольцо Сары (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (232, 'Посылка для аптекаря Зинг', 'Королевскому фармацевтическому обществу нужна твоя помощь. Слушай внимательно, поскольку, если мой план удастся, мы оба окажемся в выгодном положении.$B$BСогласна, аптекарь Чанн... немного тронутый... но его исследования приносят свои плоды, если попадают в руки к умному человеку. К счастью, я как раз из таких. Отнеси этот заказ Алессандро Лусе, хозяину \"Тысячи мелочей Синей Луны\", он даст тебе набор для полевых испытаний. Принеси его мне, и я расскажу тебе подробнее о задании.', 'Отнесите заказ на товары Алессандро Луке в Подгород. ', 'А, так Зинг нужен набор для полевых испытаний? Жаль, что она не решилась осчастливить меня своим визитом.$B$BЛадно, сейчас я подготовлю набор.', 'Да, чем могу помочь? Ты здесь по приказу Королевского фармацевтического общества или же просто поговорить пришел?', NULL, NULL, 'Заказ на товары Зинг (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (233, 'Почта Холодной долины', 'Не думаю, что ты горишь желанием мне помочь, $gпарень:красотка:, но у меня тут целая куча писем, а времени на доставку нет.$B$BЭто все для Талина Остроглаза. Его лагерь – у замерзшего озера, к западу отсюда.$B$BНу что, может, доставишь ему почту?', 'Доставьте письма Талину Остроглазу в Холодную долину.', 'Благодарю тебя, я уже давно ждал этих писем...$B$BКонечно, они не все для меня. Вот это, скажем, для Грелина Белоборода. Он тут неподалеку живет, может, зайдешь к нему?', 'А? Что? Для меня что-то есть?', NULL, NULL, 'Пачка писем (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (234, 'Почта Холодной долины', 'Если мне память не изменяет, лагерь Грелина находится дальше по дороге, на юго-восток отсюда. Не сомневаюсь, он будет рад этому посланию.', 'Доставьте письмо Грелину Белобороду в Холодную долину. ', 'Здорово! Я уже давно не получал весточки из Стальгорна.', 'Могу ли я тебе чем-нибудь помочь?', NULL, NULL, 'Письмо Грелину Белобороду (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (235, 'Большая охота', 'Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!$B$BОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – застава Расщепленного Дерева и застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громовое Сердце находится на заставе Расщепленного Дерева, к северу от Степей. Она ждет желающих принять участие в большой охоте!', 'Поговорите с Сенани Громовое Сердце на заставе Расщепленного Дерева в Ясеневом лесу.', 'Добро пожаловать на новое пограничье, $N. Ясеневый лес – край неограниченных возможностей, где юному $C вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.$B$BКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (236, 'Горючее для разрушителей', '$N! Ты как раз вовремя. Хотя эта битва закончилась, мы должны подготовиться к новым сражениям. Отправляйся в Огненную котловину, который находится в на юго-востоке Озера Ледяных Оков, и принеси оттуда несколько неугасимых угольков.$B$BСмешав их с обычным углем, мы получим топливо для наших разрушителей и осадных машин.$B$BКстати, если по пути тебе встретятся солдаты Орды – не стесняйся, убей их и забери угольки. Нельзя допустить, чтобы в следующей битве преимущество оказалось на их стороне.', 'Осадный кузнец Крепкохват из Крепости Ледяных Оков попросил вас собрать 10 неугасимых угольков с тел воинов Орды в Огненной котловине.', 'Превосходно! Теперь огонь войны никогда не угаснет.', 'Итак, тебе удалось достать угли? Или злые ордынцы отшлепали тебя по пути к Котлу?', NULL, NULL, 'Неугасимый уголек', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (237, 'Защита королевских земель', 'Горный пехотинец Кремневик превозносит тебя до небес, $R. Поэтому я хочу доверить тебе очень важное задание. Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны.$B$BОтправляйся в южные холмы и убей 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов. Это поможет нам выиграть время. Когда выполнишь задание, возвращайся.', 'Горный пехотинец Булыжный Карьер просит вас убить 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов.', 'Ты прекрасно справился с заданием, $R! Сам король может гордиться тобой.$B$BК сожалению, обещанное подкрепление так и не подошло. Фронт обагрен кровью воинов Альянса. Вести о потерях наполняют горечью мое сердце... Так пусть же эти жертвы будут не напрасны! Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу.$B$BПоговори с горным пехотинцем Стеноломом, он даст тебе новое задание. Ты нужен нам как никогда.', 'Мы должны выиграть время, $C. Тебе приказано убить 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов. Не ослабляй натиск на врага, пока не подойдет подкрепление. Сейчас не время сидеть сложа руки.', NULL, NULL, 'Головолом из племени Камнедробов убито', 'Ясновидец из племени Камнедробов убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (238, 'Посылка для аптекаря Зинг', 'Я подготовил набор, $N. Не сомневаюсь, аптекарю Зинг не терпится его получить. Отнеси посылку как можно скорее и сообщи ей, что я запишу стоимость набора на счет Общества. Кроме того, передай ей мой пламенный привет.$B$BНу же, не стой как истукан. Простым курьерам не ведом отдых, а?', 'Отнесите набор для проведения полевых испытаний аптекарю Зинг в Подгород.', 'Хорошо – приятно работать с теми, кто старается не тратить мое время попусту.$B$BКогда я закончу с набором, ты сможешь двинуться в путь. Набор пригодится для сбора необходимых данных.$B$BЯ попытаюсь закончить побыстрее. А пока ждешь, можешь обдумать, что возьмешь с собой в пустыню.$B$BДа, именно в пустыню.', 'Похоже, Луса такой же надоедливый, как и ты. Впрочем, неважно. Давай сюда набор. Мне нужно немного с ним поработать, чтобы знать, какие компоненты искать.$B$BТы ведь принес его?', NULL, NULL, 'Набор для полевых исследований (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (239, 'Гарнизон у Западного ручья просит помощи!', 'Гарнизон западной границы докладывает об усилении активности гноллов и грабителей. Они просят, чтобы мы прислали подкрепление из Штормграда... Но у нас не хватает людей!$B$BТвоя помощь не была бы лишней. Поговори с заместителем судьи Рейнером: он сейчас находится в гарнизоне у Западного ручья. Рейнер скажет тебе, что делать.$B$BГарнизон расположен к западу отсюда: иди по дороге, а потом, когда перейдешь через речушку по мосту, сверни направо.', 'Отправляйтесь в Гарнизон у Западного ручья и поговорите с заместителем судьи Рейнером.', 'Тебя что, маршал Дугхан сюда послал? Ну... Ты, конечно, не солдат, но маршалу я доверяю.$B$BУ нас тут сложилась, скажем так, напряженная ситуация. Надеюсь, ты сумеешь нам помочь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (240, 'Возвращение к Трясунчику', 'А вот и пирожки с \"крабами\" а-ля Груал!', 'Отнесите Трясунчику темные пирожки с крабами. ', 'Ага! Спасибо, $N. Как раз то, что нужно.$B$BА вот и твоя плата за услугу!', '$N, ты уже здесь! А где моя еда?!', NULL, NULL, 'Темные пирожки с крабами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (243, 'Поход в пустыню', 'Ты отправишься в пустыню Танарис изучать состав тканей василисков, скорпидов и гиен. Добудь образцы тканей и проверь их при помощи этого набора; подозреваю, что не все окажутся удачными. Мне нужно по восемь образцов каждого вида.$B$BКроме того, у гоблинов Прибамбасска есть источники энергии, необходимые для работы измененного набора. Поговори с главным инженером Чепухастером и добудь у него источник энергии.$B$BБез образцов ткани можешь не возвращаться.', 'Поговорите с главным инженером Чепухастером из Прибамбасска насчет источника энергии для набора для полевых испытаний.', 'А, наши источники энергии 4711-ФТЗ! Обычно мы пользуемся ими для электрификации колодцев, но БЛАГОДАРЯ ПРОКЛЯТЫМ КОЧЕВНИКАМ энергии у нас в избытке.$B$BНе вопрос, я могу добыть тебе источник энергии, для каких бы гнусных научных целей он тебе ни понадобился. А, думаешь, я ни о чем не догадался? Как бы не так. Но это тебе дорого обойдется, $R. В Прибамбасске ничто не достается даром.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (244, 'Вторжение гноллов', 'Привет тебе, $C. Мне приказано охранять этот участок дороги. Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов.$B$BВ Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону. Уверен, он заплатит тебе за принесенные вести.$B$BФелдон обычно обходит территорию к югу от моста по дороге в Приозерье.', 'Поговорите с заместителем судьи Фелдоном. Его можно найти у моста западнее Приозерья, что в Красногорье.', 'К Элвиннскому лесу подбираются гноллы Красногорья? Похоже, скоро они доберутся и до наших земель. И тогда не только Приозерье окажется в осаде!$B$BВозьми плату за вести, хоть они и скверные. И время сейчас неподходящее, ведь мы ничего не сможем противопоставить новой угрозе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (245, 'Восьминогая угроза', 'Привет тебе, $C. Наверное, ты $gвидел:видела: пауков на западной границе? Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья.$B$BМне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться. Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов.$B$BМой тебе совет: остерегайся их яда.', 'Убейте 15 карликовых ядовитых кругопрядов и доложите об этом дозорному Додсу в Сумеречном лесу.', 'А! Ты вернулся. И на первый взгляд – в целости и сохранности. Разумеется, $N, Ночной дозор весьма тебе признателен. Я обещал вознаградить тебя, и обещание свое выполняю. Держи.', NULL, NULL, NULL, 'Карликовый ядовитый кругопряд убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (246, 'Подсчет врагов', 'У нас нет лишних людей, но с гноллами, о которых ты говоришь, надо что-то делать.$B$BПоищи их в южной части Красногорья. Убей, кого сможешь, и сообщи мне об их общем числе и степени угрозы, которую они представляют для города. Гноллы стоят лагерем вдоль южной дороги.$B$BСделай это ради армии Штормграда, $N, и получишь награду.', 'Убейте 10 полукровок из Красногорья и 6 браконьеров из Красногорья и сообщите об этом заместителю судьи Фелдону в Приозерье.', '*Заместитель судьи Фелдон слушает ваш отчет.*$B$BЗначит, там собралось немало гноллов, и, судя по всему, они весьма сильны. Должно быть, тебе нелегко было собрать эти сведения.$B$BЧто ж, $N, мы благодарим тебя за помощь.$B$BЕсли ты еще не беседовал с маршалом Маррисом и мировым судьей Соломоном, непременно обратись к ним. Дела у нас идут все хуже; не сомневаюсь, эти двое найдут тебе работу.', 'Прости, $N, но у меня сейчас совсем нет времени. Если тебе не о чем сообщить, мне лучше вернуться к делам.', NULL, NULL, 'Полукровка из стаи Красногорья убито', 'Браконьер из стаи Красногорья убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (247, 'Завершение охоты', '', '', '$N, ты убил всех трех чудовищ охоты в Ясеневом лесу. Ты предоставил мне несомненные доказательства их гибели, так что сомнений в твоих силе и упорстве у меня нет. В твоих жилах течет кровь охотников, и да будет тебе хвала по делам!Прошу, прими эту безделицу в знак благодарности за твои деяния, совершенные тобой ныне в Ясеневом лесу во славу Орды. Да будут духи предков милостивы к тебе!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (248, 'Пронизывающий взор', 'Я наблюдал за башней Илгалара и понял, что Моргант враждует с орками крепости Каменной Стражи. Не знаю, что за этим кроется, но ты можешь помочь мне приоткрыть завесу тайны.$B$BВозьми еще один амулет Азоры и отнеси его на вершину уцелевшей башни рядом с крепостью.$B$BОтыщи подходящее место для амулета и спрячь его там. Для этой цели прекрасно подойдет сундук или кувшин.', 'Поднимитесь на уцелевшую башню рядом с крепостью Каменной Стражи в Красногорье.Отыщите подходящее место и спрячьте там амулет Азоры.', 'Это подходящий сосуд для амулета Азоры. Он позволит Теокриту проникнуть в помыслы обитателей крепости Каменной Стражи.', 'Когда-то в этом кувшине был какой-то смрадный напиток, но теперь пустой сосуд лежит, забытый, на паре бочек.', NULL, NULL, 'Амулет Азоры (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (249, 'Моргант', 'Ценой долгих усилий я раскрыл планы Морганта.$B$BОн ищет Косу Элуны... и быть может, уже отыскал ее! Коли так, то скоро Красногорье, а следом и все королевство Штормграда почувствует его те$Nю мощь.$B$BЯ не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты $gдолжен:должна: войти в башню Илгалара и бросить ему вызов.$B$BОдолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет.', 'Победите Морганта.Принесите его подвеску Тени Теокриту в башню Азоры в Элвиннском лесу.', 'Ты сделал великое дело, $N. Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности.$B$BСмиренно прошу принять эту награду. Я пожелал бы тебе мира, выпади нам жить в мирные времена.$B$BВместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях.', 'Торопись, $N, пока не сбылись мои опасения и темное влияние Морганта не расползлось по всей стране.', NULL, NULL, 'Подвеска Тени', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (250, 'Прямая и черная угроза', 'Хвала небесам, что хоть кого-то волнует наша дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра! Не сомневаюсь, следующей целью Черного Железа станет именно Дамба. Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора.$B$BПотому-то ты мне и $gнужен:нужна:, $N. Я заметил саперов из клана Черного железа неподалеку от восточной части дамбы. Разведай обстановку и возвращайся с уликами.', 'Осмотрите область вокруг восточной части Дамбы и отыщите для главного инженера Плотиннера улику, указывающую на замыслы дворфов Черного Железа.', 'В подозрительной бочке содержится странно пахнущий порошок.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (251, 'Перевод записки Аберкромби', 'Отнесите записку Шире Фон-Инди. Он знает множество языков и не чужд древним искусствам – если кто и может перевести это послание, то это он.', 'Отнесите письмо, адресованное Элло, Шире Фон-Инди. ', '*Шира принимается за перевод записки...*', 'Значит, это записка от отшельника Аберкромби? Я с ним не знаком, но если он живет на кладбище, то мозг у него – трухлявый, как старый пень!', NULL, NULL, 'Письмо к Элло (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (252, 'Перевод для Элло', 'О небо! Если то, о чем сказано в этой записке – правда, то Аберкромби сделал нечто... невообразимое.$B$BОтнеси-ка переведенную записку Элло.$B$BИ поторопись, поскольку я боюсь, что это чудовище уже ковыляет к городу...', 'Отнесите переведенное письмо лорду Элло Чернодреву. ', '*Элло читает письмо... и бледнеет на глазах. Затем он поднимает на вас взгляд.*$B$BХотя ты помогал Аберкромби по доброте душевной, именно ты обрек наш город на гибель.$B$B*Элло погружается в раздумья...*', 'А, так записку перевели? Дай-ка взглянуть...', NULL, NULL, 'Переведенное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (253, 'Невеста Бальзамировщика', 'Бальзамировщиком в наших краях давно пугают детей. Когда-то он был добрым алхимиком, но смерть любимой жены Элизы лишила его рассудка. Чтобы вернуть ее к жизни, он прибег к темной магии и даже вложил в грудь мертвой супруги собственное сердце.$B$BЭто оживило Элизу... но ее сразило проклятие – она возжелала человеческой плоти, и Бальзамировщику пришлось закопать ее обратно.$B$BВсе его могущество заключено в сердце. Отыщи могилу Элизы, извлеки из нее сердце и принеси его мне, пока оно бьется. Если тебе удастся выполнить это, то сила Бальзамировщика иссякнет.', 'Отыщите могилу Элизы. Извлеките из нее сердце Бальзамировщика и вернитесь к Элло Чернодреву.', 'Получилось! Магия этого сердца защитит нас от зла Бальзамировщика и послужит могущественным талисманом Темнолесью.$B$BТы совершил подвиг во имя нашего народа, $N. Мы тебя не забудем.', 'Тебе удалось найти могилу Элизы? А достать сердце Бальзамировщика?', NULL, NULL, 'Сердце Бальзамировщика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (254, 'Копание земли', '', '', 'Вы копаете землю... и наконец находите остатки гроба.Вы слышите скрежет когтей по крышке и лязганье гнилых зубов…Решитесь ли вы открыть гроб и достать сердце Бальзамировщика?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (255, 'Наемники', 'Пройдет два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да еще два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и Дамба - Дамба! - тоже в опасности.$B$BПохоже, у меня нет выбора. Придется искать наемников.$B$BКак насчет тебя? На первый взгляд ты подходишь, $C. На северном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?', 'Мировой судья Тупонос просит вас убить 4 огров из клана Мо\'грош, 4 громил из клана Мо\'грош и 4 головорезов из клана Мо\'грош.', 'Прекрасные новости! Я и народ Телcамара глубоко признательны тебе. Ведь если нам удастся разобраться с ограми, мы сможем заняться троггами.', NULL, NULL, NULL, 'Огр из клана Мо\'Грош убито', 'Громила из клана Мо\'Грош убито', 'Головорез из клана Мо\'Грош убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (256, 'Разыскивается: Чок\'сул', 'По приказу мирового судьи Телcамара:$B$BЧок-сул, обвиняемый в организации нападений на город Телcамар, Каменную плотину и раскопки, приговаривается к смерти любым из возможных способов.$B$BВознаграждение получит тот, кто предоставит судье доказательства смерти Чок-сула.$B$BВ последний раз обвиняемого видели в лагере огров в северо-восточной части озера Лок Модан.', 'Убейте Чок\'сула и принесите его голову мировому судье Тупоносу в Телcамар.', 'Ой! Что это? И зачем ты притащил ее…$B$BБоги!.. Это она? Ну, разрази меня гром, неужели это голова проклятого огра? Вот это улов! Что ж, награда и благодарность от имени всего народа Телcамара достаются тебе по праву!', 'Да? Чем я могу вам помочь?', NULL, NULL, 'Голова Чок\'сула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (257, 'Похвальба охотника', 'Думаешь тягаться с Дэрилом Смелым? Не советую! Разумеется, отговаривать тебя я не буду. Вот испытание, которое тебе явно не по силам. Не огорчайся, если ничего не выйдет.$B$BНеподалеку от озера Лок Модан свила гнезда стая канюков. Почему бы не подстрелить несколько тварей? Знаешь что, если ты справишься с моим заданием за пятнадцать минут, я отдам тебе свой лук или ружье.$B$B*Он с презрением осматривает вас.*$B$BВсе равно тебе нечего терять.', 'Убейте 6 горных канюков и вернитесь к Дэрилу Юному в Приют странников. На выполнение задания отводится 15 минут.', 'Что? Получилось?!$B$BПослушай добрый совет, Валератврус, пусть успех не кружит тебе голову. Я хочу сказать, любой безусый паренек с луком справился бы с такими... небольшими существами. Надеюсь, тебе не слишком нравится убивать канюков, м-м-м? Не хотелось бы, чтобы они стали исчезающим видом.$B$BЧто ж, э-э-э... Пусть не говорят, что Дерил Смелый не держит свое слово.', 'Не вышло? Не расстраивайся, бедненький $N…$B$BНе всем же быть такими, как я.', NULL, NULL, 'Горный канюк убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (258, 'Вызов охотнику', '$N $gБатькович:Батьковна:, да? Вижу, ты лопаешься от гордости за выполненное задание, а? Я же говорил, что это легко.$B$BА вот попробуй поохотиться на кабанов. Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее. На сей раз даю тебе двенадцать минут.$B$BНе расстраивайся, если ничего не выйдет. Я тебе рубаху с собственного плеча отдам, если ты справишься!$B$BЯ не рассказывал, как получил свой знаменитый шрам? Нет? Это было два года назад...', 'Убейте 5 старых горных вепрей и вернитесь к Дэрилу Юному в Приют странников. На выполнение задания отводится 12 минут.', 'Похоже, тебе несладко пришлось. Видно, кабаны задали тебе изрядную трепку, да? Не беспокойся, я никому не расскажу о твоем поражении. Тебе и без досужих болтунов тяжело.$B$BО! Ты умудрился убить кабанов? Я... что ж... хочу сказать, ничего удивительного! Любой ребенок смог бы... Обещание?$B$BКакое еще обещание?', 'Вполне простительно пожалеть себя, если тебе утер нос кто-то столь же юный, как я. Не расстраивайся, $N...$B$BКстати, это у тебя имя такое или кличка?', NULL, NULL, 'Старый горный вепрь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (261, 'По пути Алого ордена', 'Буду откровенен. Мы ведем войну с нечистью. Это зло, уничтожающее наш народ и оскверняющее нашу землю. Нежить нужно остановить, пока это возможно, иначе весь мир погрузится во мрак. Мы поклялись сражаться до последней капли крови, не щадя ни жизни, ни души.$B$BТы с нами? Тогда яви свое мужество и докажи свою доблесть: убей опустошителей-отрекшихся, бродящих по Пустошам на юге, в Долине костей.$B$BСделай это, и братство Алого ордена примет тебя.', 'Убейте 30 опустошителей-отрекшихся и вернитесь к брату Антону на Высоте Найджела.', 'Тебе удалось доказать свою решимость. Братство Алого ордена благодарит тебя.$B$BЕсли тебя не страшит то, что ради правого дела приходится убивать, причем часто и много, тогда тебе с нами по пути.', 'С каждым днем Плеть становится все сильнее и многочисленнее. Если ты действительно хочешь остановить ее, докажи это делом!', NULL, NULL, 'Нежить-опустошитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (262, 'Таинственный незнакомец', 'Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья!$B$BПрошу тебя, $N, помоги мне. Ты не раз $gтворил:творила: настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны!$B$BЯ рассказал тебе все, что мог, но возьми эту книгу, обнаруженную на ферме. Может быть, кто-то в городе опознает ее, и мы выясним имя владельца?', 'Отнесите книгу, обнаруженную на ферме Свена, в Темнолесье и покажите ее горожанам.', 'Хмм... Кто-то совсем недавно держал эту книгу в руках. Этот человек одержим жаждой мести. Но увы, следы на ней, по крайней мере следы первого владельца, едва различимы.$B$BЯ могу сказать одно: он не из Темнолесья.', 'Если у тебя есть что-нибудь из вещей того незнакомца, которого ты разыскиваешь, покажи это мне. Может быть, я смогу понять, кто ее владелец.', NULL, NULL, 'Книга с фермы Свена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (263, 'Защита королевских земель', 'Горные пехотинцы уверяют, что ты $gсилен и отважен:сильна и отважна:, $N. Нам $gнужен:нужна: $r вроде тебя. Мы никак не можем справиться с троггами. Всех бойцов отозвали на фронт, и мы остались без защиты. Но раз среди нас $gпоявился закаленный:появилась закаленная: в боях $C, то может быть, нам удастся выстоять.$B$BУбей 10 шаманов из племени Камнедробов и 10 костегрызов из племени Камнедробов. Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов.', 'Горный пехотинец Стенолом просит вас убить 10 шаманов из племени Камнедробов и 10 костегрызов из племени Камнедробов.', 'Я сразу понял, $N, что Стальгорн будет тобой гордиться. Ты славно послужил королю Магни. Теперь, доказав, что ты верный защитник Королевства, можешь поговорить с капитаном. Может быть, он посвятит тебя в наши более насущные проблемы.$B$BХвала тебе, $Nиэль.', 'Уже вернулся? На всякий случай повторяю: я просил убить 10 шаманов из племени Камнедробов и 10 костегрызов из племени Камнедробов, $N. В атаку, Гроза тТитанов!', NULL, NULL, 'Шаман из племени Камнедробов убито', 'Костегрыз из племени Камнедробов убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (264, 'Покуда смерть не разлучит нас', 'Гад такой! Бросил меня ради своего клятого похода! Понимаете ли, \"Свет превыше всего, ибо он единственная наша защита от нежити!\"$B$BА как же дети?! А я?! Много ночей я терпеливо ждала его... я всегда была второй после его чертового долга!$B$BИ посмотрите, $N, теперь на плоды борьбы за \"справедливость\"! Он мертв, а на меня обрушилось все то, чему он пытался помешать!$B$BВозьмите этот хлам и положите на его могилу в Гробнице. Мне не нужен больше этот мусор... и он сам тоже!', 'Положите подвеску Кларисы на могилу Юрива в Серебряном бору. ', 'Вы кладете дешевую безделушку на могилу, и драгоценный камень в ней заметно тускнеет.$B$BКогда вы поднимаетесь, чтобы уйти, вы смотрите на подвеску – она лежит, тусклая и мертвая, в руках вырезанного на надгробной плите изображения. Ваши мысли прерывает порыв холодного ветра, пронесшегося по Гробнице. На мгновение все вокруг вас замирает.', 'Каменная плита холодна на ощупь. Могила была осквернена: вокруг валяется мусор, барельеф на плите исцарапан, из него выбиты куски, надгробье зарастает травой.$B$BНикому нет дела до погребенного здесь, особенно если это жертва поветрия.', NULL, NULL, 'Подвеска Кларисы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (265, 'Продолжение поисков незнакомца', 'Вот твоя книга, $N, желаю удачи в расследовании. Если ты расспросишь других горожан, они могут рассказать тебе что-нибудь ценное.$B$BЯ же скажу одно: хотя автор этой книги не из нашего города, тетрадь для нее он купил здесь.', 'Поговорите с горожанами о таинственном незнакомце. ', 'Ах, да. Я продал эту тетрадь одному сомнительному типу. Он не представился, но явно нервничал, дергался, то и дело оглядывался через плечо. $B$BНадеюсь, что смог тебе помочь...', 'Иногда я продаю чистые тетради ученым и магам, а также тем, что хочет вести дневник.$B$BЯ помню всех покупателей за последние несколько месяцев...', NULL, NULL, 'Книга с фермы Свена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (266, 'Расспросы в таверне', 'Вот твоя книга, желаю удачи в расследовании.$B$BСоветую заглянуть в таверну. Если человек, о котором ты говоришь, останавливался у нас в городе, скорее всего его кто-то видел.', 'Найдите в таверне улики, связанные с таинственным незнакомцем.', 'Ах да, эту книгу я помню. Ее владелец снимал комнату на несколько дней и вечерами засиживался в баре, все писал.$B$BГород он покинул в спешке, бормоча под нос, что его преследует... что-то. В последний раз я видел его на дороге, ведущей на запад. Кажется, он собирался искать новое укрытие.$B$BПервое, что ему встретится на западе, – это Вороний холм...', 'Хотя \"Алый Ворон\" процветает не так, как раньше, путники гостят здесь и в наши дни.$B$BЕсли ты опишешь того, кого ищешь, может быть, я его вспомню.', NULL, NULL, 'Книга с фермы Свена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (267, 'Троггская угроза', '$C, не знаю, $gслышал:слышала: ли ты о новой угрозе, нависшей над землями дворфов. Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов. Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов.$B$BИ все же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан. Принеси в доказательство своих свершений 8 каменных зубов троггов.', 'Принесите 8 каменных зубов троггов капитану Ругельфассу.', 'Отличная работа, Чазм. Ты оказал всем дворфам великую услугу, защищая наши земли. Сам король Магни Бронзобород может гордиться тобой!', 'Ты принес мне 8 каменных зубов тТитанов? Если нет, тебе есть чем заняться, $N.', NULL, NULL, 'Каменный зуб трогга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (268, 'Возвращение к Свену', 'Я лишь наполовину успел закончить книгу, найденную тобой. Мне пришлось оставить ее на ферме Свена во время поспешного бегства…$B$BВот. Отнеси Свену все мои записи. Здесь подробно рассказывается о случившемся на ферме.$B$BХотя единственным моим сокровищем в последние несколько недель были только эти записи, я охотно расстанусь с ними, лишь бы не вставать на пути Свена!', 'Отнесите Свену законченные записи Трясунчика. ', 'Записи многое проясняют. Теперь мне ясно, что следует искать темных всадников! Я встречал их в Сумеречном лесу и видел, как они говорят с чародеем Морбентом Скверном у Покинутой усадьбы.', 'Тебе удалось выяснить, что это за незнакомец?', NULL, NULL, 'Законченный дневник Трясунчика (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (269, 'В поисках мудрости', 'Отправляйся в Штормград и поговори с епископом Фартингом в соборе Света. Отдай ему записи Трясунчика и сообщи, что собираешься бросить вызов Морбенту Скверну.$B$BХоть Штормград и бросил Темнолесье на произвол судьбы, Фартинг – добрая душа и мудрый человек. Он поможет тебе спасти нас.$B$BТебя ждет много опасностей... Однако поспеши, $N. С каждым часом в Сумеречном лесу сгущается тьма.', 'Отдайте законченные записи Трясунчика епископу Фартингу в Штормграде.', '*Епископ изучает записи...*$B$BЗло нашло лазейку в и без того обложенный со всех сторон Сумеречный лес. Хвала Свету, что отыскался герой вроде тебя.$B$BНо прежде чем смело двинуться навстречу испытаниям, тебе следует хорошо подготовиться... Некромант Морбент Скверн всегда был необычайно силен, а чтобы стать неуязвимым, наложил на себя могучие чары. Тебе не одолеть его без оружия, способного пробиться сквозь эти преграды.', 'Отдохни пока, брат. Я вижу, у тебя позади долгий путь, и на тебя возложена тяжкая ноша. Скажи, что за тень пала на тебя?', NULL, NULL, 'Законченный дневник Трясунчика (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (270, 'Обреченный флот', 'Много лет назад Третья флотилия Кул-Тираса затонула у берегов Болотины, огромной топи к северу от дворфийского королевства Стальгорна. Одно из судов было нагружено светлой сталью.$B$BЭтот металл представляет для нас большую ценность, поскольку изготовленное из него оружие и доспехи разят врагов силой святой истины. Если вы собираетесь противостоять Морбенту Скверну, вам именно такое оружие и понадобится.$B$BОтправляйтесь в Гавань Менетилов и переговорите с моим коллегой-дворфом по имени Глорин Стальной Лоб. Если утерянный груз еще можно найти – он сообразит, где нужно искать.', 'Отправляйтесь в Гавань Менетилов в Болотине и поговорите с дворфом по имени Глорин Стальной Лоб.', 'Светлая сталь – и впрямь драгоценный металл, но все говорит за то, что задание у тебя не из легких. Ты проделал длинный путь, братишка. Если тебе сильно повезет, ты можешь найти то, что ищешь.$B$BА если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (271, 'Месть Вайрины', 'Не хочешь отплатить Его Смелости? Вынуждена признать, что Дэрил в самом деле многое умеет.$B$BГод назад весь Приют странников охотился на огромного медведя, но ни одному смельчаку не посчастливилось его одолеть. Тогда Дэрил решил выступить против зверя сам. Разумеется, он ничего не добился, да еще и получил этот уродливый шрам над глазом.$B$BУбей медведя, и не сомневаюсь, что даже Дэрил ненадолго лишится дара речи.$B$BСтарину Черношкура можно отыскать в логове в холмах над Телcамаром.', 'Убейте Старину Черношкура и принесите его голову Дэрилу Юному в Приюте странников.', 'Э... что это? Судя по всему, медвежья голова.$B$B*Он невольно проводит пальцем по старому шраму.*$B$BЧто ж, интересная добыча. Не тот ли самый медведь...$B$B*Он умолкает и начинает заметно дрожать.*$B$BО, скорее убери ее! Убери отсюда эту страшную штуку!', 'А, $N! Уже вернулся? Опять охотился? Не огорчайся, если тебя постигнет неудача. Неудачи заставляют нас работать над собой!$B$BВ любом случае тебе повезет больше, чем некоторым...', NULL, NULL, 'Голова Старины Черношкура', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (272, 'Испытание Морского Льва', 'Вот твое второе испытание – тебе понадобятся две половинки подвески морского льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика.$B$BПоговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звезд.', 'Найдите половинку подвески ловкости водяного облика и половинку подвески выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.Сложите из половинок подвеску морского льва. Для этого вам надо находиться рядом со святилищем Ремула.Отнесите собранную подвеску Дендриту Блеску Звезд в деревню Ночная Гавань, что на Лунной поляне.', 'Ты прошел испытание Морского Льва, $N. Прими мои поздравления.$B$BКаждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва.$B$BЗапомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик.', 'Ты уже собрал подвеску, $N? Дай посмотреть. Если тебе нужна помощь, чтобы соединить половинки, обратись к местным жителям. Так ты не только узнаешь то, что тебе надо, но и познакомишься с этой чудесной, благословенной поляной.', NULL, NULL, 'Подвеска Морского Льва', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (273, 'Снабжение экспедиции', 'Еще не поздно, ты можешь поискать Хальдара. Вряд ли он ушел далеко; Миран и Сайан – крепкие ребята, но под грузом бочек ходят не слишком быстро.$B$BОни пошли к раскопу обычной дорогой – на юг от города, вдоль берега озера.$B$BНайти их будет несложно, если они еще не добрались до места назначения.', 'Поговорите с Хальдаром. ', 'Хм, жалкой засаде Черного Железа не помешать мне доставить товар!$B$BНо Сайан... Никогда бы не подумал, что он сторонник этих предателей. Я с ним почти год работаю... должно быть, что-то упустил.$B$BЛадно, подумаю об этом позже.', NULL, NULL, NULL, 'Исследовать локацию', 'Найдите Хальдара, Мирана и Сайана.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (274, 'Прямая и черная угроза', 'Это не простой взрывчатый порошок. Только взгляни на эти крошечные серебристые кристаллы. А характерный запах! Ясно, как день – это сефорий. Сам по себе он безобиден, но, намокнув, может взорвать весь Стальгорн!$B$BХимическую реакцию можно нейтрализовать, смешав четыре компонента: паучий яд, толченый кристалл Могроша, слезу кроколиска и нейтрализующий коллоид. Расскажи об этом Плотиннеру, пока не поздно!', 'Ашлан Камнехмыл велел вам вернуться к главному инженеру Плотиннеру в Лок Модан и поделиться с ним открытием.', 'Нейтрализующий коллоид? Для сефория? О небо!', 'Что ты принес от Аслана?', NULL, NULL, 'Нейтрализующий коллоид (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (275, 'Нарывы на теле земли', 'Болотину лихорадит, и я не знаю почему. Трясинные ползуны набирают силу. Это болезненные, гнойные нарывы на теле земли! И чтобы исцелить ее, нужно загнать трясинных ползунов обратно в болота, откуда они вылезли.$B$BПолзуны водятся у водоемов в Болотине.', 'Убейте 8 трясинных ползунов и вернитесь к Ретилю Стражу Природы в Болотину.', 'Скоро раны на теле земли затянутся, и лихорадка спадет. Я благодарю тебя и вручаю небольшой подарок...', 'Я слышу стон земли Болотины. Трясинные ползуны все еще оскверняют ее своим присутствием. Возвращайся, когда выполнишь мое поручение.', NULL, NULL, 'Трясинный ползун убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (276, 'Вытоптанные луга', 'Многие годы гноллы из стаи Мохошкуров мирно жили в Болотине, но теперь их поголовье увеличилось. Они вытаптывают наши прекрасные луга и вырубают лес на дрова!$B$BЧтобы спасти природу нашего края, придется истребить часть гноллов.$B$BУбей 15 гноллов из стаи Мохошкуров и 10 полукровок из стаи Мохошкуров. Они водятся на юге, возле дворфийских Врат Альгаза. Когда справишься с заданием, вернись ко мне.', 'Убейте 15 гноллов  из стаи Мохошкуров и 10 полукровок из стаи Мохошкуров. Вернитесь к Ретилю Стражу Природы в Болотину.', 'Теперь наши земли спасены! Признаться, раньше я с недоверием относился к вашему брату... но твой подвиг, $С, заставил меня задуматься. Спасибо тебе!', 'Ты еще не выполнил мое задание, $C.', NULL, NULL, 'Гнолл из стаи Мохошкуров убито', 'Полукровка из стаи Мохошкуров убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (277, 'Запрет на огонь', 'Гноллы из стаи Мохошкуров вырубают деревья Болотины и жгут древесину, греясь у костров. Я этого не потерплю!$B$BОтбери у гноллов их кремни, которыми они высекают огонь. Кремни есть у всего клана, кроме мелких гноллов и полукровок из стаи Мохошкуров.', 'Принесите Ретилю Стражу Природы 9 необработанных кремней.', 'Спасибо. Я раскрошу их в порошок и выброшу в море, и их уже никогда не используют для того, чтобы жечь живую древесную плоть.', 'Ты принес эти проклятые камни для высекания огня?', NULL, NULL, 'Необработанный кремень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (278, 'Прямая и черная угроза', 'Немедленно принимайся за сбор материалов для нейтрализации взрывчатки, $N. Паучий яд ты найдешь у пауков у озера Лок Модан. Слезу кроколиска можно отыскать там же. А вот заполучить кристалл Могроша будет нелегко. Такие кристаллы добывают огры, живущие к северо-востоку отсюда, но и у огров они водятся нечасто.$B$BМы должны разминировать творение Черного Железа! Как только соберешь все материалы, сразу же возвращайся, и я подготовлю состав.', 'Принесите паучий яд, мо\'грошский кристалл и слезу кроколиска главному инженеру Плотиннеру.', 'Наконец-то, $N!', 'Ты принес все необходимое? Торопись!', NULL, NULL, 'Паучий яд', 'Мо\'грошский кристалл', 'Слеза кроколиска', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (279, 'Угроза из глубин', 'Мурлоки поднимаются из глубин океана и строят поселения на берегу. Они нападают на наших рыбаков и торговцев, и этому нужно положить конец.$B$BОдин из вожаков, Жрун, повадился со своими родичами из племени Синежабрых устраивать засады на дороге. А после каждого нападения они возвращаются в свои хибары, откуда их уже не достать. Мы хорошо заплатим тому, кто сможет обеспечить безопасность наших торговых путей.$B$BЖрун промышляет в речной бухте к северу отсюда. Найди его, убей гада и всю его свору. И принеси мне его голову.', 'Убейте 12 мурлоков из племени Синежабрых.Прикончите Жруна и принесите его голову Карлу Борану в Гавань Менетилов.', 'Отлично, $N!$B$BВот твои деньги, ты честно их заработал, выполнив все обязательства.', 'Наши купцы смогут почувствовать себя в безопасности, только когда мы избавимся от Жруна и его сородичей.', NULL, NULL, 'Мурлок из племени Синежабрых убито', 'Голова Жруна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (280, 'Прямая и черная угроза', 'Я только сегодня видел мятежников из клана Черного Железа, которые тащили к дамбе большую бочку. И рядом со мной не было ни одного горного пехотинца, поэтому никто их не остановил! Боюсь, они заложили сефорий у основания дамбы, и она того и гляди взлетит на воздух! Дай-ка я смешаю все компоненты. Вот, у меня получилась нейтрализующая смесь.$B$BСкорее, возьми смесь и залей ее в бочку, пока не поздно. Торопись!', 'Проплывите по реке к основанию дамбы, отыщите бочку с порохом и влейте в нее нейтрализующую смесь, чтобы предотвратить взрыв.', 'Вы вливаете нейтрализующую смесь, и из бочки доносится слабое шипение.', 'Крышка бочки медленно отвинчивается.', NULL, NULL, 'Нейтрализующая смесь (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (281, 'Украденные товары', 'Не так давно мурлоки напали на торговый корабль \"Слепая принцесса\". Корабль удалось спасти, но эти подлые твари растащили почти весь груз, в том числе и одну очень ценную вещь, статуэтку Теренаса Менетила. Ее надо вернуть во что бы то ни стало.$B$BОбыщи поселение мурлоков на побережье. Ищи сундуки, ящики, бочки – все, что может быть связано с украденным грузом. Найди статуэтку Менетила и верни ее мне.', 'Обыщите сундуки, бочки и ящики в поселениях мурлоков на побережье.', 'Сундук отсырел, он весь исцарапан – это явно следы от когтей. Вы открываете сундук. Внутри – размокшая гнилая солома. Можно предположить, что здесь спрятана некая ценная вещь, требующая бережного обращения. Вы разгребаете солому...$B$B...и находите несколько бутылок из красного стекла.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (282, 'Наблюдения Сенира', 'Я собирался послать своего ученика к брату Сениру с отчетом, но парень он не слишком надежный, а мне нужен кто-то, на кого действительно можно положиться. Ну, то есть, конечно, если ты не будешь возражать.$B$BХм-м. Чтобы добраться до Караноса, тебе придется пройти по тоннелю. $B$BПеред тем как зайти в тоннель, заскочи к горному пехотинцу Талосу и поговори с ним – в тоннеле полным-полно троггов.$B$BСначала тебе нужно вернуться по дороге к Старой Наковальне, а потом направиться на восток. Рядом с тоннелем Талос и стоит – найти его будет несложно.', 'Поговорите с горным пехотинцем Талосом.', 'Хм. Ну что ж, если Белобород послал тебя в Дун Морог по важному делу, то не мне тебя останавливать, верно?$B$BС другой стороны, пару советов-то я могу тебе дать...', 'Приветствую! Я тебе вот что скажу, $N: ты в тоннеле Дун Морога будь поосторожнее, там полно тТитанов, так что дорога небезопасна.$B$BЯ тебе даже больше скажу: если у тебя нет неотложных дел в Дун Мороге, оставайся-ка лучше в Старой Наковальне, пока в тоннеле не станет поспокойнее.', NULL, NULL, 'Донесение Грелина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (283, 'Прямая и черная угроза', 'Бочка негромко шипит.', 'Кажется, нейтрализующая смесь сработала. Вернитесь к главному инженеру Плотиннеру – принесите ему добрые вести.', 'Огромное спасибо, $N! Ты спас Каменную дамбу. Без твоей помощи террористы Черного Железа непременно разрушили бы это знаменитое сооружение. Королевство и Альянс гордятся тобой, отважный $C!$B$BДамба снова в безопасности... по крайней мере, пока...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (284, 'Поиски продолжаются', 'Вы обыскиваете все поселение мурлоков в этом районе, но статуэтки Менетила здесь нет.$B$BМожет быть, стоит проверить ближайшие несколько жилищ к северу и северо-востоку отсюда?', 'Найдите статуэтку Менетила.', 'Эту бочку, похоже, никто не трогал. Вы открываете ее...$B$BЗапах валит вас с ног. Сыр слегка заплесневел, но он вполне съедобен!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (285, 'Поиски в поселениях мурлоков', 'Вы обыскиваете еще несколько жилищ мурлоков. Вот досада – опять ничего!$B$B...Но вы уверены, что все получится.$B$BСтатуэтка Менетила наверняка где-то здесь, в одном из жилищ к северу.', 'Продолжите поиски статуэтки Менетила в поселении мурлоков.', 'Бочка наполовину утоплена в грязи и мокрой траве...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (286, 'Возвращение статуэтки', 'Вы достаете бочку из грязи, открываете ее и видите серебряную статуэтку, укрытую соломой. Фигурка изображает юного длинноволосого паладина с воздетым над головою молотом.$B$BЭто, должно быть, и есть статуэтка Менетилова! Теперь вам надо вернуть ее Карлу Борану в Гавань Менетилов.', 'Верните статуэтку Менетила Карлу Борану. Его можно найти в Гавани Менетилов, что в Болотине.', 'Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз. Ты сослужил нам хорошую службу и получишь обещанную награду.$B$BРадостно сознавать, что в этом мире еще есть надежные люди, на которых можно положиться, и особенно – в такое тяжелое и неспокойное время.', 'Ты принес статуэтку?', NULL, NULL, 'Статуэтка Менетила (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (287, 'Форт Мерзлогривов', 'Я не успеваю с донесением, и твоя помощь, $N, мне бы пригодилась. Я сумел узнать, где засели тролли, но их там было столько, что я побоялся лезть туда.$B$BВот что мне нужно... Спустись в пещеру, порыскай там, прибей пару-другую троллей и возвращайся ко мне.$B$BОтправляйся из Караноса по северной дороге. Когда перейдешь через мост, следуй на запад по замерзшей реке, пока не доберешься до Заледеневшего озера. На западном берегу обнаружишь Поселок Пивоваров. Форт Мерзлогривов находится к юго-западу от него.', 'Обследуйте форт Мерзлогривов и убейте 5 охотников за головами из племени Мерзлогривов по просьбе Сенира Белоборода из Караноса.', 'А, Кольянщик! Я так и думал, что тебе будет несложно найти это место, ведь мои указания были предельно четки...$B$BДай-ка мне закончить донесение.$B$B*Он приносит бумагу и что-то быстро на ней пишет.*$B$BВот! Ха-ха, теперь это совсем забавно... Думаю, Кольянщик, ты не откажешься помочь мне еще разок?', NULL, NULL, NULL, 'Охотник за головами из племени Мерзлогривов убито', 'Исследовать локацию', 'Полностью исследуйте форт Мерзлогривов.', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (288, 'Третья флотилия', 'Когда-то я был первым помощником на \"Владычице\", линейном корабле Третьей флотилии Кул-Тираса. Обреченной флотилии... Во время последнего плавания на нас напали красные драконы. А ими правили орки!$B$BУ нас не было ни единого шанса спастись от драконьего огня, и все корабли были сожжены и потоплены у побережья. Я один уцелел в этом кошмаре.$B$BОх, как же раскалывается голова! Погоди, сейчас я выпью чего-нибудь, немного приду в себя и продолжу.', 'Купите первому помощнику Фитсиммонсу кружку медовухи.', 'Вот! И голова не болит, и язык развязался. Спасибо, приятель!', 'Трубы горят, сил нет! Добрый господин, не купишь бедному забулдыге чего-нибудь горячительного? Умираю!', NULL, NULL, 'Кружка дворфийской медовухи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (289, 'Проклятая команда', 'Приободрившись, Фитсиммонс продолжает рассказывать...>$B$BЯ единственный уцелевший из всех матросов злополучной Третьей флотилии Кул-Тираса, погибшей у северного побережья. И хотя я последний из команды, чье сердце бьется и кто еще дышит, я не единственный, кто еще бродит по земле! На одном из наших кораблей хранилось великое, ужасное сокровище, и его потусторонняя зловещая сила держит души моих собратьев и не дает им покинуть гниющие остовы кораблей.$B$BЕсли ты сможешь их освободить, тогда, может быть, они избавятся от проклятия.', 'Убейте 13 проклятых матросов, 5 проклятых стражей бухты и первого помощника Снеллига. Принесите табакерку Снеллига первому помощнику Фитсиммонсу в Гавань Менетилов.', 'Багодарю тебя, $N. И прими благодарность моих несчастных собратьев.', 'Мне снятся кошмары, в которых я слышу, как наяву, стоны моих обреченных собратьев! Заклинаю тебя, добрый сэр, освободи их от этого ужаса. Пусть их стоны и вопли умолкнут навечно.', NULL, NULL, 'Проклятый матрос убито', 'Проклятый страж бухты убито', 'Табакерка Снеллига', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (290, 'Очищение', 'Чтобы избавиться от проклятия и освободить моих верных товарищей, нужно найти и очистить эту... проклятую штуковину... спрятанную на моем корабле! Не знаю, что это такое, знаю только, что эта штука хранится в корабельном сейфе, а ключ от сейфа – у капитана Халиндора.$B$BСтарина капитан снится мне до сих пор. Я знаю, он сейчас на \"Отважном\" – нашем несчастном корабле. Постарайся добыть ключ от сейфа, открой его и возьми эту вещь.$B$BПотом отнеси ее в город и отдай жрецу Глорину Стальному Лбу.', 'Возьмите ключ от сейфа на \"Отважном\" у капитана Халиндора.Откройте сейф на \"Отважном\".', 'Ключ насквозь проржавел, но замок открылся без труда.', 'Сейф заперт надежно.', NULL, NULL, 'Ключ от сейфа на \"Отважном\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (291, 'Донесения', 'Замечательно! Отнеси мое донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием. Ты найдешь его в Стальгорне, в палате, где король Магни вершит суд.$B$BЧто? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы.$B$BКстати, будь $gдобр:добра:, не говори о том, как ты мне $gпомогал:помогала:. Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица.', 'Отнесите донесение Сенира сенатору Бэрину Краснокамню в Стальгорн. ', '*Он быстро просматривает донесение.*$B$BПо приказу КОРОЛЯ!? Магни совсем спятил! И еще этот проклятый Белобород... Значит, взял дела в свои руки? Сенат этому не обрадуется, вовсе не обрадуется.$B$BЧто, ты еще здесь? Иди отсюда, пока я охрану не вызвал!', 'Хм... похоже, мои охранники потеряли хватку и пропускают ко мне кого попало. Ладно, что тебе надо? Говори быстрее.', NULL, NULL, 'Донесение Сенира (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (292, 'Око Палета', 'Внутри сундука лежит темный шар, источающий зловещее свечение. Это и есть то сокровище, о котором говорил Фитсиммонс: проклятое Око Палета.$B$BОтнесите проклятое Око Палета дворфийскому жрецу Глорину Стальному Лбу в Гавань Менетилов. Попросите его снять проклятие с Ока.', 'Отнесите проклятое Око Палета Глорину Стальному Лбу. Его можно найти в Гавани Менетилов, что в Болотине.', 'Око Палета? Поразительно! Хмм... с ним явно что-то не так. Говоришь, ты нашел его среди обломков судна? Это многое объясняет! Но как же Око попало на корабль Третьей флотилии?..$B$BНеудивительно, что этот Фитсиммонс так перепугался. Проклятое Око Палета кого угодно выбьет из колеи.', 'Тебя послал этот пропойца Фитсиммонс? Так скажи ему, что эль у меня закончился! Нечего ему разорять мои запасы.', NULL, NULL, 'Проклятое око Палета (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (293, 'Проклятое Око', 'Я не могу снять проклятие с Ока Палета. Это людское творение, и поэтому тебе следует направиться в Штормград. Найди того, кто сумеет тебе помочь. Обратись к архиепископу Бенедикту. Он главный в Соборе Света Штормграда, и сможет дать тебе наставления.$B$BНадеюсь, у тебя все получится.', 'Отнесите Око Палета архиепископу Бенедикту. Его можно найти в Соборе Света в Штормграде.', 'Это Око Палета. Определенно, оно видело много скорбей и печалей... может быть, стало свидетелем некоей ужасной, поистине ужасной трагедии.$B$BСейчас я очищу его, ибо Очи созданы для того, чтобы сиять ярким светом, и их сила становится опасной, если они запятнаны порчей.', 'Что это у тебя? Какой-то запачканный шар...', NULL, NULL, 'Проклятое око Палета (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (294, 'Месть Ормера', 'Придется признать, что положение отчаянное. Когда мы раскопали эти кости, ящеры немедленно атаковали нас. Многие из братьев были разорваны на месте, а мы с Меррин и бедолагой геологом оказались в ловушке здесь, наверху.$B$BПомоги очистить Болотину от ящеров, $N. Крапчатые ящеры и крапчатые крикуны водятся к западу от этого утеса. Убей по 10 тварей каждого вида.$B$BЭто будет началом моей мести.', 'Убейте 10 крапчатых ящеров и 10 крапчатых крикунов. ', 'Я понимаю, что убийство – грязная и опасная работа, $N. Но если бы я не поклялся остаться рядом с геологом и Меррин, я бы и сам отправился с тобой.', 'Убей 10 крапчатых ящеров и 10 крапчатых крикунов, Рейнон. Мои погибшие товарищи не заслужили своей горькой участи. Пора свести счеты.', NULL, NULL, 'Крапчатый ящер убито', 'Крапчатый крикун убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (295, 'Месть Ормера', 'Пора нанести им сокрушительный удар. Внизу бродят стаи крапчатых смертехватов и крапчатых острозубов. Убей по 10 гадов каждого вида!', 'Убейте 10 крапчатых смертехватов и 10 крапчатых острозубов. Вернитесь к Ормеру Сталеплету на раскоп Вельгара.', '$N, ты не представляешь, как ты мне помог!', 'Крапчатые смертехваты и крапчатые острозубы должны заплатить за все, что они с нами сделали. Ты уже убил по десятку этих мерзавцев?', NULL, NULL, 'Крапчатый смертехват убито', 'Крапчатый острозуб убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (296, 'Месть Ормера', 'Пока тебя не было, я заметил, что среди этих тварей есть один выдающийся экземпляр. Он крупнее остальных и отличается особой свирепостью. Могу поклясться, что он – их вожак, это он привел их сюда и подначил разорить шахту.$B$BСослужи мне последнюю службу, $N. Зарлозуба надо предать правосудию. А если принять во внимание тяжесть его преступлений, правосудие здесь может быть только одно: смерть на месте! Убей его и в доказательство принеси мне один из его когтей.', 'Убейте Зарлозуба и принесите Ормеру Сталеплету один из когтей чудовища.', 'Спасибо, $N. Мы не забудем того, что ты сделал для нас. Сколько ни в чем не повинных дворфов полегло в этой злосчастной шахте – а ведь они просто трудились на своих местах. Но ты отомстил за наших безвинно погибших братьев, и теперь ящеры дважды подумают, прежде чем нападать на владения короля Магни.', 'Зарлозуб мертв? Ты отомстил за смерть наших братьев?', NULL, NULL, 'Коготь Зарлозуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (297, 'Сбор идолов', 'Незадолго до появления в раскопе троггов мы обнаружили множество странных резных идолов. Изучить их мы не успели, потому что вскоре после этого трогги вытеснили нас из развалин! А идолы оказывают на этих тварей странное воздействие – превращают их в берсерков!$B$BОтбей 8 идолов у троггов и принеси мне – я хочу их изучить. Идолов ты найдешь у троггов – а их в раскопе более чем достаточно.', 'Принесите Магмару Рудоколу 8 резных каменных идолов. ', 'Ты добыл их! Хвалю, Талао!$B$BИ хотя там полно троггов-берсерков, ты, кажется, не сильно пострадал. Я буду с интересом следить за твоей судьбой... Ты подаешь надежды.', 'И где же идолы? Надо хорошенько изучить их и сообщить о результатах в Стальгорн!', NULL, NULL, 'Резной каменный идол', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (298, 'Отчет о ходе раскопок', 'Мне нужно отправить в Телcамар отчет о ходе работ и запрос на получение нового груза пороха! Вот мой отчет. Отнеси его Джерну Шлеморогу, он наш представитель в Телcамаре.$B$BЗадание не сложное, но достаточно важное.', 'Отнесите отчет о ходе работ Джерну Шлеморогу в Телcамар.', 'Ха! У Железняка проблемы с троггами. Интересно, порох ему нужен для продолжения раскопок или для войны с этими тварями...$B$BТак или иначе, он будет потрачен не зря!$B$BНо вот что странно, несколько недель назад я послал ему немало пороха. Интересно, куда он делся.', 'О, отчет о ходе работ на раскопе? Превосходно!', NULL, NULL, 'Отчет о достижениях Железняка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (299, 'Тайны прошлого', 'Перед самым вторжением я обнаружил скрижаль с письменами, именуемую скрижалью Гоаз. Несколько кусков отломилось, и в четырех местах текст обрывается. Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\".$B$BБоюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты $gмолод и полон:молода и полна: сил.$B$BОбыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру. Ищи среди древних артефактов или там, где почва разрыхлена. Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!', 'Обыщите раскопки и найдите четыре недостающих фрагмента скрижали: Адос, Модр, Голм и Неру. Принесите их геологу Вельгару.', 'Итак, скрижаль Гоаз восстановлена! Ты хорошо потрудился, $N. Будем надеяться, теперь я сумею расшифровать письмена $Nв. Я уже разбираю новые слова! Э... тут написано: \"Древние боги... томятся в цепях под землей\". Похоже, грядут грандиозные перемены.', 'Ты нашел недостающие фрагменты, $N? Адос, Модр, Голм и Неру...', NULL, NULL, 'Фрагмент Адос', 'Фрагмент Модр', 'Фрагмент Голм', 'Фрагмент Неру');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (301, 'Отчет в Стальгорн', 'Мы не можем выдать Сталекруту новую партию взрывчатого порошка без одобрения Стальгорна. Тебе придется отнести его отчет в штаб-квартиру Лиги исследователей.$B$BВот он. Отдай его геологу Грозовой Вершине, да не забудь сразу отскочить в сторону. Грозовая Вершина – горячая голова. Его совсем не порадуют новости о медленном продвижении работ.$B$BГрозовую Вершину можно найти в Зале исследователей.', 'Отнесите отчет Сталекрута о ходе работ геологу Грозовой Вершине.', 'Проклятый Железняк! Я послал ему целый воз пороха еще неделю назад, но он не потрудился упомянуть об этом в отчете.$B$BТак... куда делся порох?!?', 'Представители моего клана терпеть не могут, когда нас беспокоят по пустякам, $C. Надеюсь, твои вести стоят моего драгоценного внимания.', NULL, NULL, 'Отчет о достижениях Железняка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (302, 'Порох для Сталекрута', 'Если Сталекруту нужен порох, то, именем короля Магни, он его получит! Я уже отправил вестника в Телcамар с соответствующим приказом Джерну Шлеморогу. Он подготовит груз пороха и прочих припасов для Сталекрута.$B$BИ еще одно: я хочу, чтобы ты лично $gпроследил:проследила: за доставкой груза. Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба.', 'Поговорите с Джерном Шлеморогом в Телcамаре, что в Лок Модане.', 'Что? Грозовая Вершина хочет, чтобы ты лично проследил за доставкой груза к Железняку?$B$BЯ... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли. Вы чуть-чуть разминулись, я отправил их совсем недавно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (303, 'Война с Черным Железом', 'Война свирепствует повсюду: и в наших краях, и в чужих землях тоже. Пока наши могучие воины не щадят своих жизней, сражаясь во имя Альянса вдали от дома, на наших собственных землях бесчинствуют дворфы Черного Железа. Они разрушили один из мостов Тандола, потом пал и Дун Модр.$B$BТебе нужно собрать добровольцев и сдержать натиск врагов. Если сумеешь убить 10 дворфов Черного Железа, 5 проходчиков, 5 саботажников и 5 подрывников, тогда, может быть, мы и продержимся до подхода подкрепления.$B$BИ поторопись! У нас мало времени.', 'Убейте 10 дворфов, 5 проходчиков, 5 диверсантов и 5 подрывников из клана Черного Железа.', 'Ты все сделал как надо, $C. Ты доказал свою доблесть и преданность королю Магни, за что тебе честь и хвала! Боевой дух Черного Железа подорван, и у нас появилась возможность выгнать их с нашей земли навсегда... если этот треклятый резерв все-таки подойдет...', '$N не смог связаться с резервным отрядом. Нам нужно внести смятение в ряды неприятеля, $C. Возвращайся в лагерь Черного Железа и исполни свой долг перед королем Магни!', NULL, NULL, 'Дворф из клана Черного Железа убито', 'Проходчик из клана Черного Железа убито', 'Диверсант из клана Черного Железа убито', 'Подрывник из клана Черного Железа убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (304, 'Мрачное поручение', 'Сколько наших полегло в битве при Дун Модре! Мой родной брат погиб, когда обрушился западный мост Тандола. Да, дворфы Черного Железа - те еще бестии. Чертово племя, шайка головорезов. Рогго сумел разузнать, что их предводитель в Болотине - некий чернокнижник по имени Балгарас Нечистый. Трус и мерзавец, каких поискать. Посылает на битву своих солдат, а сам прячется у себя в лагере на Зловещем холме, к юго-востоку отсюда.$B$BРазыщи этого подлого слизняка, убей его, принеси мне его ухо, и получишь награду, $C.', 'Убейте Балгараса Нечистого и принесите его ухо Длиннокосу Мрачному в Дун Модр.', 'Ну, вот и все. Балгарас Нечистый мертв. И хотя смерть мерзавца не воскресит наших безвинно погибших братьев, тем, кто уцелел, будет гораздо спокойнее. Теперь, когда Балгараса нет, мы без труда справимся с Черным Железом. Хотя надо поторопиться. Истребить этих гадов под корень, пока у них не появился новый предводитель!$B$BТы сослужил нам добрую службу, $C.', 'Ты нашел Балгараса, $C? Сколько раз мы пытались его разыскать, но все тщетно.', NULL, NULL, 'Ухо Балгараса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (305, 'Пропавшие ученые', 'Ты, должно быть, тот самый разведчик, которого мне обещал Длиннокос? Знаешь... как-то мне неспокойно на сердце.$B$BМоя благоверная, Меррин, работает в изыскательской группе на раскопе Вельгара. Писала мне каждую неделю, весь прошлый месяц. А теперь вдруг пропала. Уже две недели ни слуху, ни духу. Наверняка что-то случилось!$B$BДлиннокос обещал, что, если я вскорости не получу никаких известий, он пришлет мне разведчика, который проверит, что стало с экспедицией. Как я понимаю, ты и есть этот разведчик, $N. Разыщи Меррин на раскопе к востоку отсюда!', 'Таррел Камнепряд просит отыскать Меррин Камнепряд на раскопках.', 'Слава богам, ты нас нашел!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (306, 'Пропавшие ученые', 'Это было ужасно! Мы обнаружили несколько очень редких артефактов. Пока мы занимались раскопками, нам все чаще и чаще начали попадаться огромные кости.$B$BВсе случилось внезапно. На нас напали крапчатые ящеры, их было значительно больше, чем нас. Почти все наши погибли в неравной схватке.$B$BОстались только мы трое. Ормер – он такой храбрый, настоящий герой, – спас меня и геолога, он прикрывал нас, пока мы бежали в укрытие. А теперь мы в ловушке, и вся наша работа пропала!$B$BВот, отнеси эту записку моему дорогому Таррелу. Я ему все написала подробно. Он разберется.', 'Отнесите записку от Меррин Таррелу Камнепряду. Его можно найти в Гавани Менетилов, что в Болотине.', 'Какая ужасная новость! Это счастье, что уцелели хотя бы трое. Когда же закончится эта череда злоключений?! Когда же наконец подданные короля Магни забудут, что значит жить в постоянном страхе?!', 'Ты сумел разыскать Меррин? Она просила мне что-нибудь передать?', NULL, NULL, 'Письмо Меррин (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (307, 'Грязные лапы', 'Рудник у Серебряного ручейка давно выработан. Лига рудокопов превратила его в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на дворфийские инструменты!$B$BРано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в шахту не спустились воины и не разнесли все к демонам. Задача твоя не из простых – помощники тебе не помешают.$B$BОборудование находится в ящиках лиги Рудокопов, разбросанных по всему руднику.', 'Принесите из рудника у Серебряного ручейка 4 ящика оборудования горному пехотинцу Грозовой Вершине.', 'Там много кобольдов? Жду не дождусь приказа очистить от них рудник. Как подумаю, что они там хозяйничают, аж киплю весь!', 'Ну как, принес инструменты?', NULL, NULL, 'Инструменты шахтеров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (308, 'Отвлечь Ярвена', '', '', 'Это мне? Ты мой спаситель, $N!', NULL, NULL, NULL, 'Громовой эль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (309, 'Охрана груза', 'Что ж, в путь, $N?$B$BДля начала надо доставить Железняку порох. Вес немалый, а здесь небезопасно – кто знает, что еще замышляют дворфы Черного Железа.$B$BС тобой мне будет куда спокойнее.', 'Убедитесь, что Миран и его груз добрались до раскопа, и сообщите об этом геологу Сталекруту.', 'О, слава Свету, вот мой порох. Но новости и верно тревожные. Только подумать, что находятся сторонники Черного Железа, способные снабдить их первосортными материалами для выполнения гнусных замыслов.$B$BНо над этим пусть поломает голову кто-нибудь другой и не сегодня. А я найду этому пороху отличное применение.', 'Где мой порох, $N? Он мне все нужнее и нужнее.', NULL, NULL, 'Проводите Мирана до раскопа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (310, 'Злейшие соперники', 'Не могу не признать, эти Громовары делают славные напитки. Но они должны понять, что не только у них это хорошо получается! Может, ты поможешь преподать им урок...$B$BВот, возьми-ка этот бочонок жгучего пива Ячменоваров. Проберись в подвал \"Громоварки\" в Караносе и подмени один бочонок их громового эля. И посмотрим, не скажут ли их заказчики, что мое пиво лучше, чем Громоваров!$B$BЕсли бочонки охраняются, тебе придется отвлечь стражу...', 'Замените один бочонок эля Громоваров бочонком жгучего пива Ячменоваров в подвале \"Громоварки\" в Караносе.', 'Вы быстро ставите бочонок жгучего пива Ячменоваров, что дала вам Марлетта, среди бочек громового эля.', 'Дата на бочонке показывает, что скоро его откроют.', NULL, NULL, 'Жгучее пиво Ячменоваров (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (311, 'Возвращение к Марлетте', 'Подсунув бочонок жгучего пива Марлетты в подвал в подвал \"Громоварки\" в Караносе, вы хватаете бочонок громового эля в качестве доказательства...', 'Принесите бочонок громового эля Марлетте Ячменовар в Поселок Пивоваров.', 'Неплохо, $N! Тебе, небось, нелегко было проскользнуть мимо их охраны?$B$BДа все равно – прими мою благодарность, и если когда-нибудь тебе понадобится крепкое пивко с огоньком, вспомни Ячменевцев!', 'Ну что, подмена удалась?', NULL, NULL, 'Бочонок Громового эля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (312, 'Ограбление тайника Тундры Макгранна', 'У меня был месячный запас вяленой солонины на зиму. Я запер его в ларь, чтобы медведи не добрались. Но пока я охотился на оленей, этот изверг, Старый Ледобород, уволок мой мясной ларь! Но он не смог взломать ториевый замок. Но я же с голоду помру, если не верну свое мясо!$B$BТы вроде посильнее меня будешь. Может, сумеешь вернуть мой запас? Нога моя совсем плоха – мне не суметь быстро забраться в пещеру и утащить оттуда ларь.', 'Добудьте из пещеры Старого Ледоборода вяленое мясо из краденого ларя Тундры Макгранна.', 'Какая же ты добрая душа, $N! Благодаря твоей отваге я не подохну с голоду, когда начнутся зимние бури.', 'Тебе удалось заглянуть в мой мясной ларь, $N?', NULL, NULL, 'Вяленое мясо МакГранна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (313, 'Серая берлога', 'Управлять осадным орудием не каждому по плечу. Тут нужна железная хватка и стальные нервы! К счастью, у меня есть и то, и другое! А у тебя? Кишка-то не тонка? Хочешь покаказать мне, на что ты $gспособен:способна:?$B$BЛадно... Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее. Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса? Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!', 'Принесите 8 грив вендиго пилоту Камнекожцу.', 'О, эти гривы мне очень пригодятся! Ты крепкий орешек, $C, бьюсь об заклад, я о тебе еще услышу!', 'Эй, $N! Ну что, побывал в Серой берлоге? Эти вендиго – злющие тварюги.', NULL, NULL, 'Грива вендиго', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (314, 'Защита стада', 'Мы услышали шум среди ночи. Поутру не досчитались в отаре двух баранов. Эта подлая тварь Вагаш покушается на наше единственное добро! Поскольку большая часть армии короля Магни сражается в дальних краях за дело Альянса, некому приструнить этого Вагаша.$B$BМожет, тебе достанет отваги найти эту тварь и прикончить? Принеси мне его клык, и я тебя награжу. Вагаш рыщет как раз вон над тем выгоном, но предупреждаю: это смертельно опасная тварюга.', 'Убейте Вагаша и принесите его клык Рудре Янтарлен на Бараний выгон.', 'Отлично! Верон будет так рад этой доброй вести! Убить Вагаша – дело непростое. Сдается мне, настанет день – и ты будешь сражаться вместе с воинами короля Магни на передовой Альянса!', 'Вагаш по-прежнему режет наше стадо! Пожалуйста, помоги убить эту мерзкую тварь!', NULL, NULL, 'Клык Вагаша', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (315, 'Всем портерам портер', 'Я тут по делу, а дело мое – создать самый лучший портер! Я знаю, я смогу – пивоварение у меня в крови. Просто надо составить правильный рецепт...$B$BТролльское племя Мерзлогривов высоко в восточных холмах выращивает одну травку, звездолист называется. Они используют ее в странных ритуалах своего племени. Нам, дворфам, она не особо нужна, но у нее неповторимый вкус... И я хочу поэкспериментировать с ней при варении пива!$B$BДобудь мне немного звездолиста – его можно \"отнять\" у ясновидцев племени Мерзлогривов или стянуть из тролльских корзинок с травами.', 'Принесите 6 порций звездолиста Регольду Ячменовару из Поселка Пивоваров.', 'Великолепно! Прямо не терпится испробовать эту травку в одном из моих рецептов. Думаю, вот в этом она особенно хорошо пойдет...', 'Ты добыл звездолист? Я уже приготовился сварить партию портера и хочу попробовать бросить в сусло эту травку.', NULL, NULL, 'Звездолист', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (317, 'Заготовка продовольствия', 'Я веду подготовку к выполнению боевого задания Осадной бригады. Дело будет долгим, и мне нужно укомплектовать мой паровик провизией на месяц. Так что пока Сталежар работает с моим танком, не отправишься ли ты на охоту?$B$BМне нужен мех, чтобы сделать кровать, и кабанина для еды. Кабаны – на мясо, медведи – на мех... Этих животных можно найти в снежных полях к югу от Серого логова.', 'Принесите 4 куска кабанины и 2 толстых медвежьих шкуры пилоту Брюхинсу в Поселок Сталежара.', 'Клянусь бородой Магни, ты славно поохотился! Спасибо тебе, $N.', 'Подготовка идет отлично. Как охота?', NULL, NULL, 'Кусок кабанины', 'Толстая медвежья шкура', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (318, '\"Вечное сияние\"', 'Регольд Ячменовар не боится экспериментировать со своим варевом. Продукт эксперимента порой хорош на вкус, а порой нет, а иногда... самого крепкого дворфа уложит в стельку.$B$BРедгольд живет в Поселке Пивоваров, к западу от Караноса, и один из его напитков, \"Вечное сияние\", – как раз то, что мне надо. Он согреет меня в пути.$B$BИ... этот благословенный напиток горит так, что я могу залить его в топку паровика – и будет такой силовой импульс! Эта тактическая уловка помогала мне выбираться из многих переделок.', 'Возьмите бочонок \"Вечного сияния\" у Регольда Ячменовара в Поселке Пивоваров.', 'Толступузу нужно \"Вечное сияние\"? Ну, ладно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (319, 'Услуга за \"Вечное сияние\"', 'У меня есть бочонок \"Вечного сияния\", но... не $gмог:могла: бы ты оказать мне услугу? Поселку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко...$B$BМы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты $gвзял:взяла: это зверье на себя, у нас было бы больше времени на ремесло и пивоварение.', 'Убейте 6 медведей-ледолапов, 8 старых скальных вепрей и 8 снежных леопардов. Вернитесь к Регольду Ячменовару в Поселок Пивоваров.', 'Спасибо тебе, $N. Славно будет заняться ремеслом без этого рыка да хрюканья за околицей!', 'Ну, расправился со зверьем?', NULL, NULL, 'Медведь-ледолап убито', 'Старый скальный вепрь убито', 'Снежный леопард убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (320, 'Возвращение к Толстопузу', 'Вот твоя бочка \"Вечного сияния\", $N. И спасибо тебе за охоту.', 'Отдайте бочонок \"Вечного сияния\" пилоту Толстопузу в Поселке Сталежара.', 'Ух ты! Пожалуй, открою-ка я его прямо сейчас да попробую...', 'Ну, привез \"Вечное сияние\"?', NULL, NULL, 'Бочонок \"Вечного Сияния\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (321, 'Светлосталь', 'Эти обломки погибших кораблей – останки Кул-Тирасской Третьей флотилии, сожженной и потопленной красными драконами во время последней Великой войны.$B$BФлотилия вышла из Лордерона, и с ней шел эльфийский боевой корабль – \"Орлик\". Он вез груз светлостали и присоединился к Третьей флотилии, ища покровительства и защиты. По иронии судьбы, он был потоплен теми же драконами, от которых пытался спастись...$B$BЛадно, краткий исторический экскурс будем считать завершенным. \"Орлик\" затонул к югу от Гавани Менетилов. Если найдешь светлосталь, принеси ее мне.', 'Найдите груз с затонувшего корабля \"Орлик\" в Болотине.', 'Сундук весь размок, его обшивка сломана. На стенках внутри и снаружи видны глубокие следы когтей... как будто в нем шарились мурлоки и унесли все сокровища.$B$BНо в самом дальнем углу завалялся один-единственный слиток светлостали. К несчастью, этого мало. Для того чтобы выковать достойное оружие, вам нужно больше.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (322, 'Достойное оружие', 'В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали. Зовут его Гриманд Элмор.$B$BМеталл, который ты $gнашел:нашла:, я упакую в сундук. Отнеси его Гриманду и расскажи ему свою историю. Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!', 'Отнесите сундук со слитками светлостали Гриманду Элмору в Штормград.', 'Да, занятный рассказ. И светлосталь! Я уже много лет не работал с этим материалом. Для меня это будет великая честь. А когда все закончится, ты непременно зайди ко мне и расскажи о своей битве с некромантом.$B$BНо не будем опережать события. Первым делом -оружие, которым ты сокрушишь Морбента Скверна...', 'Ты пришел по какому-то делу, $C?', NULL, NULL, 'Ящик со слитками светлостали (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (323, 'Доказательство силы', 'Морбент Скверн – могущественный некромант и союзник темных всадников. Я не могу послать тебя на битву с ним, не испытав прежде твою силу.$B$BХрабрость твою я не подвергаю сомнению, но если ты в самом деле хочешь выступить против некроманта, сразись сначала с его приспешниками.', 'Убейте 15 скелетов-налетчиков, 3 скелетов-лекарей и 3 скелетов-хранителей и вернитесь к Свену.', 'Без сомнения, в бою тебе нет равных, $N. Благодаря твоей решимости мы сможем положить конец деяниям Морбента Скверна!', 'Не опускай оружия,$N. Главное – не отчаиваться. Отчаяние – первейшее оружие сил зла.', NULL, NULL, 'Скелет-налетчик убито', 'Скелет-лекарь убито', 'Скелет-хранитель убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (324, 'Утерянные слитки', 'Вы забрали слиток светлостали из отсыревшего сундука, но похоже, что остальные слитки растащили мурлоки. Найдите мурлоков-налетчиков у остова \"Орлика\" и отберите у них светлосталь.', 'Соберите 5 слитков светлостали и вернитесь к Глорину Стальному Лбу в Болотину.', 'Ага, вот и материал! Ну что, пора бы пустить его в дело, а?', 'Ты уже собрал достаточно светлостали?', NULL, NULL, 'Слиток светлостали', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (325, 'Вооружен и особо опасен', 'Вот оружие против твоего врага. $N, иди и сражайся. Удачи тебе, возвращайся со славой!', 'Принесите Проклятье Морбента Свену в Сумеречный лес.', 'О, это именно то, что сразит Морбента Скверна! Отлично!$B$BГотовься. Скверн теперь – не жилец.', 'Привет, $N. Вроде недавно виделись, но с тех пор в тебе что-то решительно изменилось!', NULL, NULL, 'Погибель Морбента (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (328, 'Спрятанный ключ', 'Хотя в записях нет ни слова о рядовом Торсене, в кожаном переплете одной из книг Ирода обнаруживается маленький латунный ключ.$B$BПовнимательнее изучив записи, вы находите упоминания \"надежного сейфа\". Этот сейф спрятан внутри Схрона, системы пещер позади поселка Курцена.$B$BЕсли найти его, быть может, удастся разрешить загадку обнаружения Торсена.', 'Откройте сейф букмекера Ирода маленьким латунным ключом. ', 'Открыв сейф, вы понимаете, что именно здесь Герод хранил самые ценные монеты и прочие вещи.', 'Сейф окован бронзой. Выглядит он очень прочным и очень тяжелым.', NULL, NULL, 'Маленький латунный ключ (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (329, 'Шпион найден!', 'Среди ценностей в сундуке оказывается грязная, торопливо написанная записка. Это сведения о рядовом Торсене – где он патрулирует, с кем он говорит и как проводит время среди повстанцев. Записка подписана лишь одной буквой – М.$B$BЯсно одно, ее автор очень близко знаком с Торсеном, а это значит, что предатель – среди повстанцев.', 'Отнесите грязную записку лейтенанту Дорену в Лагерь повстанцев. ', 'Спасибо, $N. Эта записка позволит нам вычислить и уничтожить предателя!', 'Тебе удалось выяснить, кому была известна тайна Торсена? Среди нас есть предатель?', NULL, NULL, 'Грязная записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (330, 'Расписание дежурств', 'Принесенная тобой записка подписана просто \"-М\".. Не пойму, что это значит.$B$BНо... в записке также говорится, что этот человек дежурил вместе с Торсеном на прошлой неделе. Значит, он и есть предатель!$B$BИди к капралу Сетману. Он занимается составлением расписания и скажет, кто дежурил с Торсеном.', 'Поговорите с капралом Сетманом.', 'А, да, я могу узнать. Посмотрим... на прошлой неделе…$B$B... Да, с Торсеном дежурил рядовой Мерль. Всю прошлую неделю у них совпадало расписание дежурств.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (331, 'Доклад Дорену', 'Не просил ли лейтенант Дорен доложить ему о собранной информации по дежурствам?', 'Поговорите с лейтенантом Дореном в Лагере повстанцев.', 'Мне больно слышать, что нас предал Мерль. Он был храбрым солдатом, и мне казалось, что верным. С другой стороны, хорошо, что мы его нашли – с таким шпионом в наших рядах... мы недолго продержались бы против полковника Курцена.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (332, 'Реклама винного магазина', 'Если тебя интересует вино, так лучшее вино в Штормграде продает семейство Галлина! Это недалеко – в Торговом квартале, неподалеку от городских каналов.$B$BВозьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого \"Пино нуар\". Не пожалеешь!', 'Отправляйтесь на винокурню Галлины и принесите Сюзетте Галлине талон на вино, чтобы получить бутылку вина бесплатно.', 'Вы знакомы с Ренато? В таком случае – только для вас, мсье... Бутылка нашего особого \"Пино нуар\"! Такого вы не попробуете больше нигде во всем Азероте!', 'Приветствую и добро пожаловать, мсье! Не желаете ли отведать наших знаменитых вин?', NULL, NULL, 'Талон на вино (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (333, 'Харлан нуждается в помощи', 'Кажется, мы уже встречались. Наверное, насчет покупки брони и походной одежды. Кстати, ожидается суровая зима...$B$BА сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду. Мне нужна еще одна партия от нашего поставщика.$B$BЕсли ты отнесешь это послание Реме Шнайдер в ателье \"Канал\", моя признательность будет весьма велика.', 'Отправляйтесь в магазин одежды в районе каналов и принесите Реме Шнайдер заказ на ткани от Харлана Багли.', 'Говорят, бизнес Харлана пошел в гору. Хорошие новости, хотя… хотелось бы мне знать, для чего вдруг понадобилось столько брони. Неужели где-то поблизости скоро случится война? Благородные господа ничего не говорят нам об этом!$B$BНу что ж, спасибо тебе за помощь. Вот твоя плата, и я надеюсь, что с заказом Харлана все хорошо.', 'Вы принесли весточку от мистера Бэгли?', NULL, NULL, 'Заказ на ткани (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (334, 'Посылка для Турмана', 'Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, $C вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать…$B$BПрошу вас, $N! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в квартале магов, и стоит она прямо рядом с башней магов.', 'Отправляйтесь в суконную лавку Ларсона в Квартал Магов Штормграда, и передайте Турману Шнайдеру его набор для шитья.', 'Ох, блин покровный! А я так надеялся, что забытые инструменты помогут мне увильнуть от работы. А теперь все-таки придется помочь Ларсону с шитьем...$B$BНу, ладно: делу – время, потехе – час...', 'Вы хотите купить одежду?', NULL, NULL, 'Набор для шитья Турмана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (335, 'Благородный напиток', 'Лорд Вишлок наделал немалого переполоху среди Благородных домов. Он прознал о наших делах и теперь собирается добиться полного расследования. У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь.$B$BЕсть один цветочек под названием \"слеза Тиллоа\", он растет в садах Сталвана поблизости от Темнолесья. Еще мне понадобится мускусный корень, который можно найти только у подножия Каменной плотины в Болотине.', 'Принесите Зардету Черному Когтю слезу Тиллоа из Темнолесья и мускусный корень из Болотины.', 'Отлично! Это ровно то, что нужно!', 'Вишлок скоро наберет достаточно сил, чтобы доставить нам кучу неприятностей. Ты уже раздобыл слезу Тиллоа и мускусный корень?', NULL, NULL, 'Слеза Тиллоа', 'Мускусный корень', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (336, 'Благородный напиток', 'У лорда Вишлока, как у всех людей, есть свои маленькие слабости. Например, он совсем не дурак выпить. Удивительное лицемерие! Старый ханжа целыми днями сражается с заведениями вроде нашего, а ночи напролет проводит наверху, да еще и не платит по счету. Ну, посмотрим, как ему понравится придуманный мной специально для него напиток: портер \"Черный Коготь\"! С ног сбивает – точно тебе говорю, $N!$B$BОтнеси ему это пойло и посмотри, придется ли оно лорду по вкусу. Старый хмырь наверняка шатается вокруг Зала просителей.', 'Отнесите портер \"Черный коготь\" лорду Вишлоку в Зал просителей.', 'Спасибо за чудесный портер! Вот, возьми пару монет. А теперь иди прочь и не мешай мне дегустировать!', 'Ты что, не видишь, как я занят? Я готовлю речь! Я значу очень много для будущего этой державы!$B$BО, а что это у тебя? Похоже на освежающий напиток...', NULL, NULL, 'Портер \"Черный Коготь\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (337, 'Старый учебник истории', 'Хотя обложка книги исцарапана и заляпана грязью, на корешке все еще можно прочитать заглавие – \"История Штормграда\". Открыв ее, вы видите на первой странице печать библиотеки Штормграда.$B$BПохоже, кто-то взял почитать эту книгу, да так и не вернул...', 'Вернуть книгу \"История Штормграда\" в библиотеку Штормграда.', 'О небо! Этой книги не видели на полках со времен восстановления Штормграда. Конечно, ее придется реставрировать, она в плохом состоянии, но я с радостью помещу ее в нашу коллекцию редких книг.$B$BБлагодарю вас, господин. Прошу, примите плату за возвращение книги!', 'О-о-о! Что это у вас за книга? Можно взглянуть?', NULL, NULL, 'Старый учебник истории (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (338, 'Зеленые холмы Тернистой долины', 'Господин Эрнестуэй так расстроится, когда узнает об этом!$B$BОн доверил мне рукопись романа \"Зеленые холмы Тернистой долины\". Все шло хорошо, но по лагерю пронесся сильный порыв ветра и разметал страницы!$B$BБольшую часть мне удалось собрать, но многие страницы унесло в джунгли. Найди все страницы, и мы снова соберем четыре главы.$B$BЯ сам все разложу! Когда соберешь все четыре главы, возвращайся.', 'Соберите все недостающие страницы романа \"Зеленые холмы Тернистой долины\". Когда у вас на руках окажутся все четыре главы, верните их Барнилу.', 'Ты избавил меня от многих хлопот, $N. Не знаю, как и благодарить тебя. Вскоре книги господина Эрнестуэя появятся в библиотеках по всему свету!', 'Тебе удалось собрать все главы, $N?', NULL, NULL, 'Зеленые холмы Тернистой долины: глава I', 'Зеленые холмы Тернистой долины: глава II', 'Зеленые холмы Тернистой долины: глава III', 'Зеленые холмы Тернистой долины: глава IV');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (339, 'Глава I', 'Первая глава была необычайно интересной. Мастер Эрнестуэй предваряет рассказ знакомством со своими товарищами по охоте, в том числе и со мной! $B$BНо речь не об этом. Посмотрим, каких страниц не хватает. Кажется, страницы 1, 4, 6 и 8 все еще в джунглях!', 'Принесите 1, 4, 6 и 8 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю первую главу.', 'Наконец-то! Глава I собрана!', 'Тебе не удалось найти страницы 1, 4, 6 и 8? Именно их не хватает, чтобы собрать воедино главу I.', NULL, NULL, 'Зеленые холмы Тернистой долины: стр. 1', 'Зеленые холмы Тернистой долины: стр. 4', 'Зеленые холмы Тернистой долины: стр. 6', 'Зеленые холмы Тернистой долины: стр. 8');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (340, 'Глава II', 'Вторая глава представляла собой сплошные увлекательные рассказы про охоту на пантер и тигров. Так и хочется самому себе наподдать за то, что упустил страницы!$B$BМне удалось собрать почти все, кроме 10, 11, 14 и 16.', 'Принесите 10, 11, 14 и 16 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю вторую главу.', 'Вторая глава полностью собрана! Молодец!', 'Нам по-прежнему не хватает 10, 11, 14 и 16 страниц второй главы, $N.', NULL, NULL, 'Зеленые холмы Тернистой долины: стр. 10', 'Зеленые холмы Тернистой долины: стр. 11', 'Зеленые холмы Тернистой долины: стр. 14', 'Зеленые холмы Тернистой долины: стр. 16');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (341, 'Глава III', 'Глава III была моей любимой. В ней рассказывается о том, как сэр Эрлгедин и леди Руак впервые подстрелили зверя из дворфийского ружья. А какое захватывающее у нее окончание! $B$BПохоже, нам недостает страниц 18, 20, 21 и 24. Они должны быть где-то неподалеку...', 'Принесите 18, 20, 21 и 24 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю третью главу.', 'Уф! Отличная работа, $N. Теперь у нас есть вся глава III!', 'Ну как, где страницы 18, 20, 21 и 24? Стоит их найти, и третья глава будет собрана.', NULL, NULL, 'Зеленые холмы Тернистой долины: стр. 18', 'Зеленые холмы Тернистой долины: стр. 20', 'Зеленые холмы Тернистой долины: стр. 21', 'Зеленые холмы Тернистой долины: стр. 24');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (342, 'Глава IV', 'А, Глава IV, захватывающий финал! И как она закончилась! $B$BНам не хватает всего лишь трех страниц этой главы. А именно – 25, 26 и 27. Стоит найти их – и последняя глава готова.', 'Принесите 25, 26 и 27 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю четвертую главу.', 'Великолепно! Глава IV готова!', 'Нам не хватает всего лишь трех страниц главы I$N. Ты принес страницы 25, 26 и 27?', NULL, NULL, 'Зеленые холмы Тернистой долины: стр. 25', 'Зеленые холмы Тернистой долины: стр. 26', 'Зеленые холмы Тернистой долины: стр. 27', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (343, 'Кстати, о стойкости духа', 'Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, \"Как закалялось железо\". Копия этой книги должна быть в Королевской библиотеке Крепости Штормграда. Не могли бы вы заказать ее для меня? Да осенит вас благодать Света!$B$BКоролевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесет для вас книгу.', 'Отправляйтесь в Королевскую библиотеку Крепости Штормграда и поговорите с Милтоном Снопом. Он даст вам книгу по металлургии, которая интересует брата Кристофа.', 'Металлургия? Да, конечно, у нас много книг по данной отрасли знаний, и мы будем рады помочь брату Кристофу в подготовке лекции! Какая же книга его интересует?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (344, 'Брат Пакстон', '\"Как закалялось железо\"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провел в горах Каз Модана, добывая руду. Отличный парень!$B$BНо о чем это я? Ах, да... \"Как закалялось железо\"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с нее копию для своей коллекции.$B$BУж сколько тому месяцев минуло... Интересно, почему он ее задерживает.', 'Поговорите с братом Пакстоном из Аббатства Североземья.', 'Коллега Шиф потерял свою книгу? Мда, неловко вышло... Книга действительно у меня, но я не закончил ее переписывать, так что мне пока что нужен оригинал!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (345, 'Запас чернил', 'Я как раз собирался закончить свою работу над копией \"Как закалялось железо\", но...$B$BЯ пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут. Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я еще не успел закончить работу... и сделать еще чернил я не могу!$B$BДля изготовления чернил мне нужна ретбанская руда из Красногорья. Старшина Ослоу из Приозерья - мой верный поставщик...', 'Поговорите со штейгером Ослоу из Приозерья и расспросите его о ретбанской руде.', 'Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков. Если тебе сдалась ретбанская руда, добудь ее сам!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (346, 'Возвращение к Кристофу', 'Я закончил перепись и могу вернуть оригинал \"Как закалялось железо\". Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку.', 'Вернитесь к брату Кристофу на Соборную площадь. Отдайте ему книгу \"Как закалялось железо\".', 'Это она! Спасибо, $N! Да пребудет над тобой вечный сияющий Свет!', 'Тебе удалось найти книгу?', NULL, NULL, 'Книга \"Как закалялось железо\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (347, 'Ретбанская руда', 'Ретбанская руда получила свое название по имени первооткрывателя, Барта Ретбана. Выплавленный металл мягче железа, но руда имеет приятный темный цвет, и многие переписчики используют ее для изготовления чернил. Добыть руду можно в пещерах Ретбана к северу отсюда.$B$BК сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе еще вот что... Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду.$B$BТак что если тебе нужна руда... ты знаешь, как добыть ее.', 'Добудьте 5 кусков ретбанской руды и принесите их брату Пакстону в библиотеку Североземского аббатства.', 'О, благодарю! Я наконец-то смогу приготовить чернила и закончить свою работу над копией \"Как закалялось железо\"!$B$BБлагодарю тебя, $N!', 'Как там моя ретбанская руда?', NULL, NULL, 'Ретбанская руда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (348, 'Лихорадка Тернистой долины', 'Плохо... Мне... т-т-ак п-п-лохо.$B$BЯ п-подцепил... лихорадку Тернистой д-долины... Это смертельный вирус…$B$BЕдинственное лекарство... съесть сердце М-м-м-мок-ка Д-дикаря... неуловимой... белой гориллы…$B$BИщи знахаря Унбагва в с-с-скрытой пещере на южном мысу...$B$BПоспеши... я... умираю...', 'Найдите знахаря Унбагва и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.', '...сила возвращается..$B$BГде я? В Пиратской бухте? Ох! Мне снился странный сон…$B$B...слабость не полностью прошла...', '...мама?$B$B…так холодно…$B$B...отправляюсь в Круговерть Пустоты... Об-бними меня, мама...', NULL, NULL, 'Сердце Мокка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (349, 'Лихорадка Тернистой долины', 'temp text 02 - description', 'Temp text 02 - log.', 'Знахарь Унбагва любить клык горилла! Моя будет говорить с духи. Пусть придет Мокк Дикарь.$B$BТвоя защищать знахарь Унбагва от других горилл-зверей, или никакой Мокк не быть!', 'Знахарь Унбагва знать что есть Мокк Дикарь. Да, да!$B$BМоя говорить с духами, и он приходи.$B$BНо другие гориллы-звери тоже любят, когда духи говорят. Охрани знахаря Унбагва, и моя позвать его.$B$BЗнахарь Унбагва кое-что хотеть сначала. Твоя принеси 10 клыков гориллы, и моя начинать говорить с духи!', NULL, NULL, 'Клык гориллы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (350, 'Помощь старого друга', 'Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара...$B$BТеперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твое свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара. Ему, в сущности, наплевать на закон.$B$BТебе понадобится помощь. Я, увы, оказать ее не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале.', 'Поговорите с Иллингом Триасом в Штормграде. ', 'Опять Шоу?! Совести у него нет!..$B$BБратство Справедливости, говорите? Да вы просто мешок с хорошими новостями! Скажите еще, что Смертокрыл воскрес и напал на город...$B$BНу, ладно, выкладывайте все по порядку. И не пропускайте ни единой детали. Я хочу знать все.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (351, 'Найди КПХ-17:TN!', 'Вы находите какой-то странный яйцевидный металлический предмет. Повозившись с кнопками, вы пробуждаете яйцо, и оно превращается в гномский робот! Изнутри доносится голос.$B$B\"Меня зовут Карлс, и мой автономный робот потерялся! За его находку полагается награда! Прошу, отнесите этот маяк к роботу. Я уже вычислил координаты. Он сломался возле Зияющей бездны в Танарисе.\"', 'Отнесите аварийный маяк к автономному роботу Карлса.', 'Вы помещаете яйцо... аварийный маяк... внутрь цыпленка... робота.$B$BИзнутри робота доносится жужжание и скрип – он пытается встреть. Когда робот оживает, изнутри доносится голос Карлса:$B$B\"По крайней мере, КПХ-17:TN работает, но нуждается в серьезном ремонте! Он слишком тяжелый, чтобы унести отсюда... впрочем, у меня есть идея. Не хотите присмотреть за ним?\"', 'Похоже, вы нашли обломки... механического цыпленка? Из яйца снова доносится голос:$B$B\"Да, отличная работа! Это в самом деле мой автономный робот, хотя судя по сенсорам, он нуждается в хорошей починке перед перелетом в Пиратскую бухту. Для начала поместите маяк внутрь аппарата. А остальное он сделает сам!\"', NULL, NULL, 'Аварийный маяк КПХ-17/TN (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (353, 'Посылка для Грозовой Вершины', 'Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утонченными вкусами. Неудивительно, что Грингер Грозовая Вершина, горный пехотинец из Стальгорна, обратился ко мне, когда ему понадобилось оружие.$B$BЗаказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если ты собираешься на север, не возьмешься ли доставить груз?$B$BПо моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане.', 'Доставьте посылку горному пехотинцу Грозовой Вершине в Лок Модан.', 'Ага! Так Гриманд все-таки закончил мой топор! Мне уже не терпится опробовать его на троггах и кобольдах!$B$BБлагодарю, $N. Эта посылка проделала такой долгий путь... Вот, примите это в благодарность за ваши услуги.', 'Вы прибыли прямиком из Штормграда? Я слышал, что в человечьих землях обострилась ситуация с орками и грабителями. Там сейчас можно неплохо подзаработать – правда, $C?', NULL, NULL, 'Посылка для Грозовой Вершины (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (354, 'Смерти в семье', 'Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... еще до чумы.$B$BКогда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными...$B$BИз-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!$B$BСослужи Отрекшимся службу – убей Агамондов, ставших жертвами чумы, и принеси мне их останки.', 'Принесите останки Грегора, останки Ниссы и останки Турмана Колману Фартингу в Брилл.', 'Месть сладка, не правда ли? Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их? Надеюсь, что да. Надеюсь, они почувствовали страх, прежде чем упокоились навсегда.$B$BКонечно, глупо на это надеяться, но тем не менее.', 'Ты принес останки Агамондов? Эти проклятые твари уничтожены?', NULL, NULL, 'Останки Грегора', 'Останки Ниссы', 'Останки Турмана', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (355, 'Разговор с Севреном', 'Ты $gпринес:принесла: мне останки Агамондов и $gутолил:утолила: мою жажду мести. Но мельницы этой проклятой семейки все еще представляют собой угрозу не только для меня, но и для всех Отрекшихся.$B$BЯ рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично.', 'Поговорите с мировым судьей Севреном в Брилле. ', 'Коулман хорошо отзывался о тебе, Вёрлвинд, и рассказал о твоем успешном походе на мельницы Агамондов.$B$BОтрекшимся еще раз нужна твоя помощь...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (356, 'Патруль в арьергарде', 'Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них.$B$BНаш успех на Бастионе зависит от битвы на один фронт: мы не можем допустить атаки с тыла и уж конечно не можем лишить наших защитников линии поставки припасов.$B$BПомоги Бастиону. Отправляйся на восток и убей любого приспешника Плети, которого встретишь. Особое внимание обрати на ферму Балнира на востоке – там настоящее гнездо Плети.', 'Убейте 8 кровоточащих ужасов и 8 странствующих духов, а потом доложите о своих успехах Линнее, ожидающей вас в своем лагере.', 'Очень хорошо. Благодаря вашим усилиям Плеть еще долго не осмелится сунуться сюда. Я отправлю лестный отзыв моему начальнику, исполнителю Зуганду.', 'Ну что, как прошел обход?', NULL, NULL, 'Кровоточащий ужас убито', 'Странствующий дух убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (357, 'Личность лича', 'На острове посреди озера Ясноводного, что к северу отсюда, обитает лич. Сам он – свободный Отрекшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится.$B$BНо раз он Отрекшийся, он понадобится Королеве. А если он еще и специалист в некромантии, то его умения нам... весьма пригодятся.$B$BЧтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний. Прокрадись в его лагерь, достань ее, и принеси мне.', 'Принесите книгу лича Бетору Ледострелу в Подгород. ', 'Прекрасно, $N. Я изучу эту книгу и узнаю многое об этом личе. Ты сослужил королеве добрую службу.$B$B*Бетор открывает книгу и внимательно смотрит на ее сияющие страницы…*$B$BНевероятно! Добытая тобой книга принадлежит не кому иному, как Гюнтеру Чародею!$B$BГюнтер и при жизни был искусным некромантом. До нашествия Плети мы были добрыми товарищами и братьями по оружию. Судя по книге, после смерти он достиг еще большего могущества.$B$BЕго искусство могло бы нам очень пригодиться.', '$N, ты принес книгу?', NULL, NULL, 'Книга заклинаний лича', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (358, 'Грабители могил', 'Братские могилы к юго-востоку от фермы Гаррена были вырыты, чтобы справиться с... внушительным количеством смертей в Тирисфале после прихода Чумы.$B$BТела в этих могилах еще не превратились в нежить, но теперь Плеть подослала гноллов-Гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Это недопустимо!$B$BУ тебя будет два задания: перебить гноллов-Гнилошкуров возле братских могил и фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь.', 'Убивайте грабителей могил и полукровок из стаи Гнилошкуров.Принесите мировому судье Севрену 8 образцов бальзамирующей лимфы.', 'Отличная работа, Герей! Если силы Плети решили, что могут направлять этих мертвецов на нас, то они жестоко ошиблись. Что же касается жидкости, которую ты собрал с рабов Гнилошкуров, ее изучат наши аптекари. Возможно, они откроют какой-то секрет, который поможет нам в войне.$B$BСловом, ты отлично справился. Но война продолжается, и у тебя будет еще много шансов проявить себя перед Отрекшимися.', 'Ты сделал то, о чем я просил? Убил этих псов и забрал у них лимфу?', NULL, NULL, 'Грабитель могил из стаи Гнилошкуров убито', 'Полукровка из стаи Гнилошкуров убито', 'Бальзамирующая лимфа', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (359, 'Обязанности Отрекшихся', 'Мне нужен свежий отчет с восточной базы наших стражей смерти.$B$BЯ хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь еще одну крепость.$B$BИди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у нее есть вся нужная мне информация.', 'Поговорите со стражем смерти Линнеей', 'Севрену нужен отчет? Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них все же проникает время от времени.$B$BПлеть видели к востоку от нашей базы, возле Усадьбы Балнира.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (360, 'Возвращение к мировому судье', 'Теперь возвращайся к мировому судье Севрену с той информацией, что я дала вам. Он очень ждет ее, так что поспеши.$B$BА если встретишь по пути приспешников Плети – немедленно убей их! Нечего им шастать по нашим землям.', 'Вернитесь к мировому судье Севрену в Брилл.', 'Неприятно слышать, что Плеть просачивается через Бастион. Король-лич и его слуги не собираются сдаваться.$B$BНо и мы не уступим. Мы не позволим ему захватить нас снова!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (361, 'Недоставленное письмо', 'Это письмо, написанное Турманом, старшим сыном Грегора Агамонда. Оно адресовано Иветте Фартинг, но, похоже, так до нее и не добралось...', 'Найдите Иветту Фартинг и вручите ей письмо от Турмана Агамонда.', 'О... мой бедный Тармен! Я ведь просила его уйти с этих мельниц со мной и моим отцом, но его преданность семье оказалась сильнее... Так я и знала! Я знала, что Брэнд желает ему зла! Будь прокляты эти Чума и Плеть!$B$B*Лицо Иветты смягчается.*$B$BНо стенания – удел слабых. Я Отрекшаяся, у меня есть свои цели, и любовь не входит в их число. Спасибо за то, что принесли мне письмо от некогда любимого человека, теперь я хотя бы знаю, что с ним сталось.$B$BНо та жизнь для меня окончена. Навсегда.', 'Да?', NULL, NULL, 'Письмо Турмана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (362, 'Мельницы с привидениями', 'Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно. Турман был высоким и учтивым, а его младший брат – слабым и острым на язык.$B$BКогда мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых. На дороге, ведущей к мельницам Агамондов, до сих пор можно услышать его безумное бормотание.$B$BЯ собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина. Найди его, уничтожь и принеси мне его кости.', 'Убейте Девлина Агамонда и принесите его останки Колману Фартингу в Брилл.', 'Спасибо. Кости Девлина станут отличным украшением для моего плаща.$B$BЕсли что-то может согреть мое холодное сердце, то это мысль о том, что Агамондов больше нет. Они предали меня и мою семью, когда пришла Чума – а теперь я клянусь, что растопчу их кости ногами!', 'Ты нашел Девлина?', NULL, NULL, 'Останки Девлина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (363, 'Резкое пробуждение', 'Ты вовремя $gпришел:пришла: в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. $B$BМеня зовут Мордо, я смотритель склепа Могильника. А ты больше не $gраб:рабыня: Короля-лича. $B$BПоговори с жрецом Тени Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать.$B$BЧтобы выбраться из склепа, поднимайся наверх по ступенькам. Затем следуй вниз по дороге, пока не найдешь часовню.', 'Поговорите с жрецом Тьмы Сарвисом.', 'А, еще один живой мертвец! Должно быть, это настоящий шок – очнуться в склепе, в котором тебя встречает лишь холод... и Мордо. $B$BЯ все это читаю по твоему лицу. Позволь мне объяснить тебе наше... эээ... положение. $B$BНас освободила из-под контроля Короля-лича наша новая предводительница, леди Сильвана. Темная Госпожа руководит нами в войне против ненавистной армии Плети и цепляющихся за эту землю людей, преследующих нас, словно ищейки.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (364, 'Безмозглые твари', 'Мы, Отрекшиеся, ведем войну против армии Плети, ведомой Королем-личом: против поднятых некромантией войск нежити, против злобных зверей севера и истерзанных призраков. $B$BСеверную часть деревни оккупировали безмозглые твари Плети, их нужно уничтожить. Сокруши их, не давая пощады, пусть они и были прежде нашими братьями и сестрами. Падшие – всего лишь рабы Короля-лича.', 'Жрец Тени Сарвис хочет, чтобы вы убили 5 безмозглых зомби и 5 презренных вурдалаков.', 'Жаль, что нельзя привлечь Плеть на нашу сторону, ее несметные полчища пришлись бы как нельзя кстати в предстоящих битвах. $B$BНо так как договориться с ними нельзя, нам остается лишь уничтожить их.', 'В этой новой жизни ты далеко не продвинешься, если не в состоянии убить даже самых слабеньких зомби, $N. И не возвращайся, пока не сможешь доложить об успешном выполнении.', NULL, NULL, 'Безмозглый зомби убито', 'Презренный вурдалак убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (365, 'Поля горя', 'Кто это тут? $gНовенький:Новенькая:, да еще и $C? Если хочешь проявить себя перед Темной Госпожой, придется следовать обычаям Отрекшихся.$B$BК западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв.$B$BКак наберешь десяток, отнеси их аптекарю Юхану в Брилл.', 'Украдите 10 тыкв с западной фермы, к северу от Могильника. Потом отнесите эти тыквы аптекарю Юхану в Брилл.', 'Ты хорошо справился с заданием, $C, и тем самым доказал, что достоин примкнуть к армии Темной Госпожи.', 'Страж смерти Симмер сказал мне, что ты принесешь очень нужные реагенты. Ты уже собрал десять тыкв, $N?', NULL, NULL, 'Тирисфальская тыква', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (366, 'Книга Гюнтера', 'Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана.$B$BМы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамена Короля-лича. Я рад, что он остался свободным.$B$BМы должны привлечь его на свою сторону. Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича. Надеюсь, что, убедившись в этом, он станет одним из нас.', 'Верните Гюнтеру книгу заклинаний. Его можно найти на острове, в приюте Гюнтера.', 'Моя книга?! Так это ты украл ее!$B$BНо... что это за новые чары на ней... Бетор? Он в Лордероне?$B$BЕсли он все еще \"жив\", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича...', 'Твои хозяева глупцы! Незачем было подсылать тебя. Я никогда не стану рабом Плети!', NULL, NULL, 'Книга заклинаний Гюнтера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (367, 'Новая чума', 'Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Темная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса.$B$BВ своих изысканиях я обнаружил, что для этого потребуется кровь животных. Принеси мне 5 склянок крови пса тьмы, чтобы я мог провести эксперимент.', 'Принесите аптекарю Юхану 5 склянок крови псов тьмы. ', 'Ты хорошо справился, $N Благодарю тебя за старание.', 'Ты уже добыл 5 склянок крови псов тьмы, $N? Время не ждет!', NULL, NULL, 'Кровь пса тьмы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (368, 'Новая чума', 'Пока ты $gсобирал:собирала: для меня образцы, я провел исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее.$B$BМне потребуется 5 чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу.', 'Принесите аптекарю Юхану из Брилла 5 чешуек мурлоков из племени Злобного Плавника из Тирисфальских лесов.', 'Отличная чешуя, $N. Именно то, что мне нужно для микстуры.', '$N, тебе удалось собрать для меня 5 чешуек мурлоков из племени Злобного Плавника?', NULL, NULL, 'Чешуя мурлока из племени Злобного Плавника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (369, 'Новая чума', 'Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней. Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов.$B$BПринесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент. Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах.', 'Принесите аптекарю Юхану из Брилла 4 образца яда злобного ночного кругопряда.', 'Да, этот яд великолепно подойдет, $N! Я уже добавил все остальное в мой состав и вскипятил его. Наконец-то я испытаю эту смертельно опасную смесь!', 'Вы уже нашли яд злобного ночного кругопряда, $N? Это последний компонент, необходимый мне для испытания моего нового состава.', NULL, NULL, 'Яд злобного ночного кругопряда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (370, 'Война с Алым орденом', 'В документах вершителя Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми.$B$BУбей Перрина, трех ревнителей и трех миссионеров, а потом доложи мне о своем успехе.', 'Убейте капитана Перрина, 3 ревнителей и 3 миссионеров из Алого ордена по просьбе вершителя Зуганда.', 'Темная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, $C.', NULL, NULL, NULL, 'Капитан Перрин убито', 'Ревнитель из Алого ордена убито', 'Миссионер из Алого ордена убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (371, 'Война с Алым орденом', 'У нас до сих пор война, а Алый орден набирает силу. В отчете вершителя Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ фермы Балнира.$B$BУбей Вакона и 5 келейников из Алого ордена – это должно нанести ордену сокрушающий удар!', 'Убейте капитана Вакона и пятерых келейников из Алого ордена по заданию вершителя Зуганда.', 'Смерть капитана Вакона значительно замедлит продвижение Алого ордена по Тирисфалю. Но есть и другие угрозы.', NULL, NULL, NULL, 'Капитан Вакон убито', 'Келейник Алого ордена убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (372, 'Война с Алым орденом', 'Алый орден совершает набеги из своей разрушенной башни в северном Тирисфале, за могилой Фаола. Согласно нашей информации, отвечает за эти набеги жестокий капитан Мелраш.$B$BЯ даю вам особенное и очень важное задание – убить Мелраша и двух его телохранителей во имя Темной Госпожи.', 'По просьбе палача Зуганда убейте капитана Мелраша и двух его телохранителей.', 'Вы отлично справились, $C. Чем больше на стороне Отрекшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса. У меня хорошие предчувствия на ваш счет.', NULL, NULL, NULL, 'Капитан Мелраш убито', 'Телохранитель из Алого ордена убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (373, 'Неотправленное письмо', 'Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо. Адрес таков: \"Баросу Алекстону, главному архитектору Штормграда, в ратушу на Соборной площади\".$B$BКажется, оно написано совсем недавно, и печать еще свежая…', 'Доставьте письмо городскому архитектору Баросу Алекстону в Штормград.', 'Эдвин ван Клиф, говорите? Я бы скорее ждал письма от своей покойной бабушки... Так это вы его убили? Извините, конечно, но я сильно удивлен. В молодые годы он был просто непревзойденным бойцом. Ну, дайте-ка взглянуть, что он мне там написал после стольких лет...$B$B*Барос рассматривает письмо.*$B$BЭх, Эдвин… годы не изменили тебя ни на каплю. Все такой же идеалист и романтик. Представляете, $N, ему было все равно, кому мстить. Месть попросту поглотила его. Но, кажется, я его понимаю…', 'Да? Я могу вам чем-нибудь помочь?', NULL, NULL, 'Неотосланное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (374, 'Доказательство верности', 'Вершитель Зуганд сказал, что тебе уже приходилось убивать бойцов Алого ордена. Тирисфальские леса так и кишат ими.$B$BВариматрас, подручный Темной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стерто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден.$B$BПомоги нам истребить их, $C. Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Темной Госпоже.', 'Принесите 10 алых перстней стражу смерти Берджесу в Брилл.', 'Вариматрас будет гордиться тобой. Ты отлично служишь своим лидерам, $C.', 'Ты собрал 10 Алых перстней, $C?', NULL, NULL, 'Перстень Алого ордена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (375, 'Смертельный холод', 'Так холодно... Чума нежити расползается по моим венам, как клубок ледяных змеев, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.$B$BТеперь мои руки дрожат от холода. Если ты принесешь мне 5 шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, $N, чтобы я могла и дальше служить нашему делу.', 'Принесите 5 шкурок сумеречницы и грубую нить Гретхен Дедмар в Брилл.', 'Спасибо за заботу, $N. Надеюсь, когда-нибудь слух о твоей храбрости дойдет и до Сильваны...', 'Ты нашел для меня шкурки сумеречницы и грубую нить, $N?', NULL, NULL, 'Шкурка сумеречницы', 'Грубая нить', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (376, 'Проклятые', 'В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться. $B$BПохоже, и ты будешь $gзаписан:записана: к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесешь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно.', 'Ученице Элрет нужно 6 лап падальщика и 6 крыльев сумеречницы.', 'Спасибо, $N. Держи этот доспех. $B$BНадеюсь, тебе он послужит лучше, чем тому бедолаге, что носил его последним…', 'Постарайся остаться невредимым, пока я не найду для тебя каких-нибудь доспехов.', NULL, NULL, 'Лапа падальщика', 'Крыло сумеречницы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (377, 'Преступление и наказание', 'Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева.$B$BВард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью. И все же Штормград объявил Варда своим пленником.$B$BУбей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу.', 'Принесите советнику Миллстайпу руку Декстрена Варда. ', 'Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества? Чем меньше швали, тем лучше, я так считаю. Хвала тебе, друг мой! Ты не только утешил семьи покойных, ты преподал наглядный урок продажным бюрократам из Благородных домов. Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании.', 'Пока выродки вроде Декстрена Варда живут на этом свете, в мире нет места справедливости. Возвращайся, когда исполнишь приговор лорда Чернодрева. Тем самым мы утешим семьи покойных и – более того – преподадим урок Благородным домам.', NULL, NULL, 'Рука Декстрена Варда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (378, 'Успокоить Гневливого', 'Ты $gдоказал:доказала: свою преданность королю Магни, $C. И ты, так же как я, ненавидишь мерзавцев Черного Железа всем сердцем.$B$BЯ бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длиннокосом. Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола. А это значит, что Кам виноват в гибели брата Длиннокоса.$B$BПока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его, $N. Ради Грима! Принеси мне его голову!', 'Принесите голову Кама Гневливого Мотли Гармасону в Дун Модр.', 'Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть? Хорошо. С этими негодяями из клана Черного Железа только так и надо. Отлично потрудился, $C. Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемым войнами. Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан. Брат Длиннокоса отомщен.', 'Я не могу допустить, чтобы идиотская бюрократия людей мешала правосудию дворфов, $N. Существуют неопровержимые доказательства, что за диверсией на мосту Тандола стоял Кам Гневливый. Из-за этого предателя погибли наши собратья. Если людям достаточно и того, чтобы Гневливый сгнил в тюрьме, это их дело... но я не смогу спать спокойно, пока мерзавец не будет убит.', NULL, NULL, 'Голова Гневливого', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (379, 'Утолить жажду', 'Тебе нужен источник силы. Могу помочь. Что я хочу взамен? Пить! Принеси мне пять бурдюков с водой Скитальцев Пустыни, и я дам тебе 4711-FTZ.$B$BЗнаешь, где взять эти меха? Попробуй попросить их у кочевников Скитальцев Пустыни! Потом расскажешь, что из этого вышло.', 'Найдите 5 бурдюков с водой Скитальцев Пустыни главному инженеру Чепухастеру в Прибамбасск.', 'Отлично, вот тебе источник энергии. Честно говоря, он создан совсем не для исследовательского набора вроде этого, поэтому у тебя будет не так уж много времени, а потом все данные кирдыкнутся!$B$BКак только соберешь, все, что нужно, принеси эту штуковину мне, чтобы я отключил ее как надо. У тебя не больше двух часов на все про все.$B$BЕсли ты не успеешь, я, конечно, продам тебе еще один источник энергии. Ключевое слово – продам!', 'Ну как, кочевники поделились с тобой водой?', NULL, NULL, 'Бурдюк с водой Скитальцев Пустыни', 'Исследовать локацию', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (380, 'Паучья низина', 'Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета Альянса. $B$BК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. $B$BОтправляйся туда – может быть, ты сможешь чем-то помочь нам, $N.', 'Палач Аррен хочет, чтобы вы убили 8 молодых ночных кругопрядов и 5 ночных кругопрядов.', 'Ну что же, для начала неплохо. Очистка всей территории займет несколько недель или даже месяцев. А после этого, нам придется пойти туда с факелами, чтобы сжечь паутину. $B$BТы отлично справился, $N, я уверен, что подыщу для тебя еще какую-нибудь работенку.', NULL, NULL, NULL, 'Молодой ночной кругопряд убито', 'Ночной кругопряд убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (381, 'Алый орден', 'Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. $B$BМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! $B$BБудь $gосторожен:осторожна:, нечестивое рвение делает их опасными противниками.', 'Принесите вершителю Аррену 12 алых поручей, сняв их с новообращенных и посвященных из Алого ордена.', 'Если б только они послушались доводов разума, а, $N? Может быть, мы могли бы уговорить их все серьезно обсудить... Как же! $B$BИдиоты, ослепленные Светом...', 'Они просто идиоты... копающие себе могилы.', NULL, NULL, 'Поручи Алого ордена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (382, 'Красный гонец', 'В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из их монастыря к Могильнику. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! $B$BА ты, $N, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.', 'Убейте гонца Мевена Коргала в лагере Алого ордена, а потом передайте перехваченные известия палачу Аррену.', 'Хмм... Ну-ка, посмотрим, что ты там нашел... $B$B<Аррен пробегает глазами документы, принесенные вами.: $B$BНовости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы... \"Продолжайте организацию лагеря около разрушенного города...\" Ничего такого, о чем мы не знали бы... А это еще что? Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать.', 'Как продвигается выполнение задания, $N?', NULL, NULL, 'Бумаги Алого ордена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (383, 'Важные разведданные', 'Вот это нужно отнести моему начальнику, вершителю Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно $gпомог:помогла: нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдется более серьезная работа. $B$BИди по дороге из Могильника на север. Вскоре после того, как дойдешь до Тирисфаля, наткнешься на перекресток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье \"Остывший очаг\".', 'Отнесите бумаги Алого ордена вершителю Зуганду в Брилл.', 'О, прекрасно! Ты отлично потрудился, добывая эту информацию, $N. Хмм... Имена офицеров в Тирисфальских лесах…$B$BПредставь, какой удар мы можем нанести по боевому духу этих фанатиков, если убъем всех их лидеров одним стремительным ударом.', 'Да? Что тебе нужно?', NULL, NULL, 'Бумаги Алого ордена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (384, 'Кабаньи ребрышки в пиве', 'Завсегдатаи моей таверны больше всего любят кабаньи ребрышки в пиве! Беда в том, что местный охотник, который снабжал меня кабанятиной, теперь завербован в королевскую армию, чтобы помочь Альянсу.$B$BМожет, ты мне поможешь? Если принесешь мне шесть ребер скального вепря и \"Болтливое пиво\" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых ребрышек в пиве, не говоря уж о дармовой порции! Вся соль – в пиве!', 'Принесите 6 ребер скального вепря и кружку \"Болтливого пива\" Рагнару Громовару в Караносе.', 'Сварено пиво, разлито по кружкам,$BЭй, не деритесь, друзья и подружки!$BКаждому выделим по половине$BВкуснейшей порции ребрышек в пиве!', 'Мне нужно шесть ребер скального вепря и кружка \"Болтливого пива\", $N.', NULL, NULL, 'Ребро скального вепря', 'Болтливое пиво', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (385, 'Охота на кроколисков', 'Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков. Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса.$B$BМы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок. Но если хочешь отправиться на охоту, я не стану тебя отговаривать. Это действительно незабываемо.$B$BЯ и сам в свое время...', 'Принесите Мареку Железносерду в Приют Странников 5 кусков мяса кроколиска и 6 шкур кроколиска.', 'Ты отлично поохотился, $N. За хорошую работу и платят хорошо!', 'Я не рассказывал, как кроколиск едва не откусил мне руку? Жуткая тварь была, зубы – как лезвия. Но мне повезло... Я заткнул ему пасть ножом. Этот нож я до сих пор храню...', NULL, NULL, 'Мясо кроколиска', 'Шкура кроколиска', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (386, 'Что происходит?', 'Таргорр Ужасный служил под началом Гат\'Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью. По его прихоти отважных бойцов Королевства подвергали страшным пыткам. Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни. Но происходит что-то странное. Один из знатных людей запретил его казнить. Уверен, дело нечисто.$B$BПоложи конец Таргорру Ужасному, $N. Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства.', 'Принесите голову Таргорра Ужасного стражнику Бертону в Приозерье.', 'Наконец-то Таргорр Ужасный получил по заслугам. Я рад, что злодей угодил в лапы Смерти. Молодец, $N. Иной раз подлинное правосудие можно отыскать лишь за стенами залов суда, вдали от замутненного взора политиканов.', 'Ты уже побывал в тюрьме? Боюсь, что если предательство позволяет так долго сохранять жизнь Таргорру Ужасному, оно же может дать ему свободу. Он приговорен к смертной казни, $N, и не должен стать пешкой в руках интриганов.', NULL, NULL, 'Голова Таргорра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (387, 'Подавление бунта', 'Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда.$B$BНаказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдет в норму.', 'Тюремщик Телвотер просит вас убить в тюрьме 10 узников, 8 каторжников и 8 мятежников из Братства Справедливости.', '$N, ты отлично проявил себя в тюрьме. Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработал, и я тебе очень благодарен.', 'Тюрьма по-прежнему под контролем бунтовщиков! Этим крысам из Братства Справедливости нужно показать, что это им даром не пройдет! Возвращайся и задай им жару!', NULL, NULL, 'Узник из Братства Справедливости убито', 'Каторжник из Братства Справедливости убито', 'Мятежник из Братства Справедливости убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (388, 'Цвет крови', 'Кровь моя стынет в жилах от ужасного горя... Мой внук Мак… он был такой чудесный мальчик. Всего 14 лет. Когда армия ушла на фронт, он счел, что должен защитить город. Он был охранником в тюрьмe, куда прибыла партия заключенных из Братства Справедливости. Мак наказал некоторых заключенных за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды. За это он получил нож в спину.$B$BЯ хочу мести. Принесите мне 10 этих проклятых шерстяных бандан. Они цвета крови...', 'Принесите Никове Раскол 10 красных шерстяных бандан.', 'Значит, из-за этих жалких тряпиц они убили моего Мака... Ужасная, нелепая смерть!..$B$BУвы, мне не дано изменить прошлое. Но я благодарна вам, $N, за то что вам удалось воздать по заслугам убийцам моего внука.', 'Я вижу, вы вернулись, $C. Вы уже собрали 10 красных шерстяных бандан, принадлежавших этому отродью, Братству Справедливости?', NULL, NULL, 'Красная шерстяная бандана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (389, 'Базиль Тредд', 'ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны.$B$BКогда мы закончили работу, вельможи отказались платить нам за нее. Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии. Он поднял мятеж и покинул город, поклявшись отомстить.$B$BЕго лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме.', 'Поговорите с надзирателем Телвотером в тюрьме. ', 'Чего, во имя Света, тебе надо? Не видишь, тут и без тебя проблем хватает?$B$BБазиль Тредд?! Какое тебе дело до этого мерзавца? Или ты – из его поганых кровавых соратничков? Не будь у меня тут все камеры заняты, я бы тебя точно засунул в одну из них!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (391, 'Бунтовщики в тюрьме', 'Скажу тебе сразу, $N: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно.$B$BЧто от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову. А если ты на их стороне и не вернешься вовремя, то будешь долго, долго гнить заживо…', 'Убейте Базиля Тредда и принесите его голову Телвотеру в тюрьму Штормграда. ', 'Без Тредда бунтовщики станут куда более управляемыми. Посмотрим...$B$BДолжен сказать, я уже через полчаса решил, что больше тебя не увижу… но, надо признать, я в тебе ошибся.$B$BДумаю, тебе не удалось из него ничего вытянуть... А вот я знаю пару вещей насчет деятельности Тредда, которые тебя могут заинтересовать.', 'Или ты мне принесешь голову Тредда, или я тебе, $N, твою собственную оторву, ясно?', NULL, NULL, 'Голова Базиля Тредда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (392, 'Таинственный посетитель', 'Во время первого года заключения Тредда никто его не навещал. Мне казалось, что братство отказалось от него, поскольку он стал бесполезен.$B$BНо пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип. У меня возникли подозрения, но все его документы были в полном порядке.$B$BСогласно документам, звали его Мелик; вот его описание. Не думаю, что он еще когда-нибудь придет к Тредду.', 'Отнесите запечатанное описание посетителя Тредда Баросу Алекстону в Штормград.', 'Мелик? Нет, это имя мне незнакомо и даже ни на какие мысли не наводит. Это может быть кто угодно! Бывший каменщик, один из членов Братства Справедливости... Хотя если он тесно связан с ними, как предполагает Телуотер, кто-нибудь может опознать его. Мне нужно подумать.', 'Да, $N? Что вы нашли?', NULL, NULL, 'Запечатанное описание посетителя Тредда (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (393, 'Тень прошлого', 'Знаете ли, $N, мне так ничего и не пришло в голову. Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться. Матиас Шоу из ШРУ – его можно найти в казармах Старого города. Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки.$B$BЕсли кто-то и знает, о ком речь, то только он.', 'Отнесите запечатанное описание посетителя Тредда Матиасу Шоу в Штормград. ', 'Что это? Да, думаю, что знаю этого человека, но его зовут вовсе не Мелик. Наемные убийцы носят много масок, зовутся множеством имен и забывают их, как только они становятся не нужны. Этот человек также известен под именем Марзон; вероятно, это его очередной псевдоним.$B$BВ общем, он – наемный убийца, и я о нем довольно много знаю.$B$BМарзон сейчас работает на Грегора Лесковара – человека с репутацией, дурной даже для коррумпированного лорда Штормграда.', 'Приветствую. По какому делу вы ко мне явились, $C?', NULL, NULL, 'Запечатанное описание посетителя Тредда (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (394, 'Голова чудовища', 'Найди Шоу в Старом городе. Дай ему знать, что с Лесковаром покончено, а тебе все известно о заговоре лордов против города. Я думаю, он будет рад, что среди горожан Штормграда есть еще герои.$B$BДумаю, он отправит тебя на встречу с принцем или другим лордом. Не позволяй им запудрить себе мозги, $N. Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны.', 'Поговорите с Матиасом Шоу в Штормграде.', 'Значит, мертв? Ты скор на расправу, $N. Не хотел бы я стать твоим врагом.$B$B*Смеется и кладет руку вам на плечо.*$B$BНе прими за осуждение, $N. Я же глава наемных убийц, как я могу осуждать тебя за чистое убийство? По правде сказать, ты оказал людям Штормграда огро$Nю услугу, и я благодарю тебя за это.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (395, 'Гибель братства', 'Ах, да... Пока тебя не было, приходил Алекстон, хотел с тобой поговорить. Должно быть, это касалось Братства Справедливости.$B$B$N, позволь дать тебе совет: на твоем месте я бы по первой просьбе рассказал обо всем произошедшем в подробностях. Но при этом упомяни, что Лесковара сразила именно твоя рука. Можешь мне верить – я на таких вещах собаку съел.$B$BА что касается Триаса... ну, не говори о нем. Никогда. Если сможешь.', 'Поговорите с Баросом Алекстоном в Штормграде. ', 'Приятно тебя видеть снова, $N. Мне довелось услышать о недавней кончине лорда Грегора Лесковара.$B$BЗначит, твоя миссия оказалась успешной. Я щедро награжу тебя за спасение и меня, и многих прочих от мести ван Клифа.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (396, 'Аудиенция у короля', 'Я приготовил доклад для короля. Надеюсь, ты сумеешь преподнести его величеству все в лучшем виде. Не переживай так, король обязательно оценит твое благородное служение народу Штормграда и достойно наградит тебя.$B$BСрок твоей аудиенции близок, так что поторопись, чтобы не опоздать в Крепость Штормграда.', 'Доставьте доклад Бароса Алекстона о Братстве Справедливости королю Вариану Ринну в крепость Штормграда.', '$N, я щедро награжу вас за службу Штормграду. Если ван Клиф преуспел в своих махинациях, то у нас еще будет немало трудностей. Этого мы должны избежать.$B$BВозьмите этот жетон в знак королевской благосклонности, $C. Сожалею, что король не смог вручить его вам лично, но он сейчас занят на дипломатических переговорах и еще не освободился.', '$N, верно? Барос Алекстон уже предупредил о вашем прибытии. Должен признаться, мне будет интересно вас выслушать.', NULL, NULL, 'Доклад об уничтожении Братства Справедливости (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (397, 'За достойную службу', 'Я слышал, что Лорд Вишлок в восторге от напитка.$B$B$N, ты нам здорово $gпомог:помогла:. Теперь чернокнижники Штормграда смогут заниматься своим делом без помех. За свою службу ты получишь достойный подарок. Поговори с Згги, моим слугой.', 'Поговорите с Згги, слугой Зардета Черного Когтя, чтобы получить награду.', 'Хозяин дал подарок для $N. Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (398, 'Разыскивается: Червеглаз', 'Разыскивается: Червеглаз!$B$BУжасное даже по меркам гноллов чудовище – Червеглаз – приговорен к смерти за его преступления против Отрекшихся. Этот гнусный злодей воровал трупы для армии Короля-лича. Червеглаза видели близ фермы Гаррена, к северу от Брилла.$B$BГород Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить вершителю Зуганду его лапу.$B$BМилосердие – удел слабых.', 'Убейте Червеглаза и отнесите палачу Зуганду в Брилл его лапу.', 'Наконец-то Червеглаз получил по заслугам. Пусть твой поступок запомнится всем, кто захочет навредить нашему народу! Благодарю тебя от имени всего города Брилла, Урога.', 'Да?', NULL, NULL, 'Лапа Червеглаза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (399, 'Скромные дары прошлого', 'С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность. Говорят, нельзя вернуться в прошлое – и это верно. Дважды верно, если говорить обо мне – ведь мой родной дом был разграблен ворами и сожжен.$B$BЯ спросил у отца о судьбе некоторых моих вещей, например, о моем первом компасе. Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме.$B$BУсадьба Алекстона расположена к западу от Сторожевого холма. Может быть, ты найдешь мой компас?', 'Обыщите дом Бароса Алекстона в Западном Крае, найдите компас и вернитесь на Соборную площадь Штормграда.', 'Благодарю вас, $N! Совершенно бесполезная вещь, не считая воспоминаний... Нет слов, как я благодарен за то, что принесли мне этот предмет; вам, конечно, трудно понять цену памяти о Западном Крае. Возьмите это в знак моей признательности...', '$N! Вы нашли компас?', NULL, NULL, 'Простой компас', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (400, 'Инструменты для Сталежара', 'Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам! Но своего инструмента он не жалеет. Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые!$B$BМы только что выполнили его очередной заказ. Если ты его доставишь, я уверен, мастер заплатит тебе за труды.$B$BТы сможешь найти Сталежара к северо-востоку от Караноса. Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работенка подвернется.', 'Доставьте инструменты Белдину Сталежару.', 'У тебя мои инструменты? Отлично, парень, отлично! Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца. Славно, что ты принес мне эти инструменты, $N.$B$BВот, возьми эти деньги; спасибо!', 'Хм? Мал ты еще для водителя осадной машины. Ну да ладно... Тебе что-нибудь починить надо?$B$BВозьми номерок и жди своей очереди. Я сейчас работаю над парой машин, и времени на еще одну работу у меня не будет как минимум пару дней.$B$BИли ты тут по другому вопросу?', NULL, NULL, 'Инструменты Сталежара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (401, 'Ожидание перевода', 'Я почти закончил работу над переводом записки. Она будет готова через несколько минут.', 'Подождите немного и снова поговорите с Широй Фон-Инди.', 'Ну вот. Готово…$B$B*Вокруг воцаряется душная тишина, словно на лес опустился темный тяжелый полог...*', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (403, 'Охраняемый бочонок Громоваров', '', '', 'Этот бочонок эля охраняет Ярвен Громовар. Пока он в подвале, до бочек не добраться.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (404, 'Грязная работа', 'Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста.$B$BОтправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти.', 'Принесите 7 гнилых когтей стражу смерти Диллинжеру в Брилл.', 'Отличная работа. Жаль, я не видел, как ты расправляешься с этими гнусными тварями!', 'Ты выполнил задание, которое я тебе дал? Принес мне гнилые когти?', NULL, NULL, 'Гнилой коготь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (405, 'Блудный лич', 'Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, $N, как раз подходишь для этого.$B$BОтнеси эти приказы Бетору, а он расскажет, в чем состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдет о вербовке заблудшего лича. Это очень опасное дело.$B$BПриготовься как следует, $C. Не подведи нас.$B$BБетора можно найти в квартале Магов Подгорода.', 'Отнесите приказы Севрена Бетору Ледострелу в Подгород.', 'А, так тебя прислал мировой судья Севрен. Тогда да, дело у нас с тобой очень важное.$B$BУверен, Севрен выбрал того, кто справится с моим заданием, но… ладно, посмотрим.', 'Здравствуй. Либо ты не знаешь, кто я, либо у тебя ко мне очень срочное дело.$B$BПотому что иначе ты не посмел бы меня беспокоить…', NULL, NULL, 'Приказы Севрена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (407, 'Поля горя', 'Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития.$B$BЧуть-чуть смекалки, и простая тыква превратится в шпиона Темной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом.$B$BВот недавно мы поймали еще одного ревнителя из Алого ордена, сейчас он сидит в погребе таверны \"Петля висельника\". Иди, отнеси ему эту тыкву.', 'Отнесите отравленную тыкву пленному ревнителю из Алого ордена, которого держат в погребе таверны \"Петля висельника\".', 'Благословенный Свет! Наконец-то еда! Сладенькая тыквочка...', 'Прочь, нечестивое созданье! Свет, защити меня! Алый орден избавит Азерот от таких...$B$BОй... Это что, еда для меня? Я умираю с голода...', NULL, NULL, 'Отравленная тыква (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (408, 'Семейный склеп', 'Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас.$B$BТы не $gдолжен:должна: допустить этого. Отправляйся в склеп Агамондов и убей их неупокоенных предков.$B$BА заодно принеси мне череп капитана Даргола.', 'Убейте 8 стенающих предков и 8 гниющих предков.Убейте капитана Даргола и принесите его череп мировому судье Севрену в Брилл.', 'Твои действия нанесли Плети ощутимый удар! И твоя победа не будет забыта ни Отрекшимися, ни врагами.$B$BПродолжай бороться вместе с нами, $N, и когда-нибудь мы изгоним Короля-лича из Азерота!', 'Мы не можем позволить себе прохлаждаться, $N. С каждым часом кольцо Плети вокруг Тирисфальских лесов сжимается все сильнее.', NULL, NULL, 'Стенающая прародительница убито', 'Гниющий предок убито', 'Череп Даргола', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (409, 'Доказательство преданности', 'Ты говоришь, что $gнеподвластен:неподвластна: воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают. Но прежде чем я поверю тебе,ты $gдолжен:должна: доказать то, что являешься врагом Плети.$B$BНа южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара.$B$BВозьми из этого ящика манящую свечу, зажги ее на алтаре, и Лилит пробудится. Убей ее, и я поверю, что ты – враг Короля-лича.', 'Возьмите манящую свечу.Вызовите Лилит Нефару и убейте ее.Вернитесь на остров к Гюнтеру.', 'Невероятно! Ты убил Лилит Нефару и тем самым доказал, что являешься врагом Плети!$B$BЯ думал, что я – единственный из нежити, обладающий свободой воли, но теперь вижу, что есть и другие, кто не поддался влиянию Короля-лича.', NULL, NULL, NULL, 'Лилит Нефара убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (410, 'Спящая тень', '', '', 'Вы ставите на стол Манящую свечу и зажигаете ее...', NULL, NULL, NULL, 'Манящая свеча', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (411, 'Возвращение блудного лича', 'Отнеси этот самоцвет Пустоты моему старому товарищу Бетору. С его помощью мы сможем общаться, а мне очень многое надо ему сказать.', 'Отнесите самоцвет Пустоты Бетору Ледострелу в Подгород. ', 'Ты убедил его присоединиться к нам! Это огромная радость для всех Отрекшихся, $N. Я доложу об этом Темной Госпоже.', 'Ты вернул книгу Гюнтеру? Что он сказал?', NULL, NULL, 'Самоцвет Хаоса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (412, 'Операция \"Перенаправление\"', 'При дальнейшем анализе гномреганской ситуации оказалось, что нам не только не удалось извести троггов, но мы случайно превратили большую часть представителей нашей расы в ужасающих, безмозглых, злобных лепрогномов!$B$BМы с Оззи намерены направить в обратную сторону ужасный эффект лепры при помощи нашего последнего изобретения – атомарного перенаправлятора. Эта машина почти закончена, но нам чрезвычайно нужны зубцы рестабилизации и гиромеханические шестерни. Добудь их у лепрогномов, которые обитают около Гномрегана, и принеси нам!', 'Принесите Раззлу Шустрецу в Караносе 8 зубцов рестабилизации и 8 гиромеханических шестерней.', 'Эти гиромеханические шестерни и зубцы рестабилизации прекрасно подходят к чертежу Оззи для устройства Перенаправления. Как только я залью гидросмазку во внутренние клапаны сгорания, подкручу кривохраповик и повышу вязкость электрогуммигеля, раса гномов будет возрождена.', 'Перенаправлятор будет закончен и введен в эксплуатацию, как только у нас будет достаточно зубцов рестабилизации и гиромеханических шестерней.', NULL, NULL, 'Зубец рестабилизации', 'Гиромеханическая шестерня', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (413, 'Мерцающий портер', 'Хотелось бы мне, чтобы мой братец Велларт попробовал свежего \"Мерцающего портера\". Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан.$B$BМожет, он и не такой пивовар, как остальные Ячменовары, но свое пиво он любит, и я знаю, что это тоже ему понравится.$B$BНе отнесешь ему вот этот бочонок \"Мерцающего портера\"?', 'Отнесите бочонок \"Мерцающего портера\" горному пехотинцу Ячменовару.', '*Горный пехотинец Ячменовар пробует \"Мерцающий портер\"...*$B$BОх-х. Аж искры из глаз! Кажется, я даже в темноте видеть могу!', 'Привет, $C! Что за дело привело тебя сюда?$B$BНадеюсь, что-нибудь стоящее. Я уже много дней не дрался хорошенько, да и этот бочонок эля уже почти пуст...', NULL, NULL, 'Бочка \"Мерцающего портера\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (414, 'Портер для Кэдрелла', 'Я бы и еще отхлебнул \"Мерцающего портера\" с пивоварни моего братца – забористое же пойло! Но я хочу, чтобы мой приятель-пехотинец попробовал его. Зовут парня Кэдрелл, и он обычно патрулирует дорогу через Телcамар в озере Лок Модан.$B$BЧтобы добраться до Телcамара, иди на юго-восток через туннель, затем на развилке возьми на северо-восток. И по той дороге иди прямо до Телcамара.$B$BОтдай горному пехотинцу Кэдреллу этот бочонок \"Мерцающего портера\", и посмотрим, что он скажет!', 'Отнести бочонок \"Мерцающего портера\" горному пехотинцу Кэдреллу в Лок Модан.', 'Ну-с, попробуем...$B$BКлянусь бородой Магни! Аж голова кругом пошла! И в теле легкость необыкновенная.$B$BСейчас полечу, как птичка!', 'Привет, $C, добро пожаловать в Телcамар!', NULL, NULL, 'Бочонок \"Мерцающего портера\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (415, 'Новое пиво Регольда', 'Регольд Ячменовар, что живет в Поселке Пивоваров, спрашивал про тебя.$B$BОн хочет поговорить с тобой про свое новое пиво... Сказал вроде, что ты ему $gпомог:помогла:. Можешь самолично вернуться в Поселок Пивоваров и спросить, что ему надо.$B$BМожет, тебя дармовая выпивка ждет...', 'Поговорите с Регольдом Ячменоваром.', '$N! Помнишь тот звездолист, что ты принес мне? Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно!$B$BВот, попробуй и скажи, как пошло...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (416, 'Ловля крыс', 'К западу отсюда началось настоящее нашествие. Эти крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю!$B$BИх необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду.$B$BКобольды-туннельщиков поселились к западу от Телcамара вдоль горных склонов.', 'Принесите 12 ушей кобольдов-туннельщиков горному пехотинцу Кэдреллу в Телcамар.', 'Фу! Когда я просил принести уши, я не подозревал, что они так дурно пахнут!$B$BПрими награду, $N. Молодчина.', 'Приветствую тебя, $N! Как идет ловля крыс?', NULL, NULL, 'Ухо туннельщика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (417, 'Месть пилота', 'Хилдельв пишет в своем журнале, что подвергся нападению Паршивого Когтя, \"огромного медведя-ледолапа\". Он отогнал тварь, но та успела страшно изранить его.$B$BСудя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его.$B$BВ журнале Хилдельв записал свое последнее пожелание:$B$B\"Отомстить Паршивому Когтю.\"', 'Убейте Паршивого Когтя.Принесите его коготь и журнал Хилдельва пилоту Большеногу.', 'Злая весть. Хилдельв был хорошим другом. Жаль, что не довелось мне с тобой пойти на этого Паршивого Когтя!$B$BСпасибо тебе, $N. Пилоты Осадной бригады Стальгорна тебя не забудут.', 'Привет, $N. Есть у тебя весточка от моего друга Хилдельва?', NULL, NULL, 'Грязный коготь', 'Записи Хилдельва (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (418, 'Телcамарские кровяные колбаски', 'Едоки в Телcамаре не переводятся – еще бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками... Но ты ведь их еще не $gпробовал:пробовала:? Нет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение.$B$BМне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты. Добудь все это, а уж Видра сготовит все в лучшем виде!', 'Принесите Видре Жаркий Очаг в Телcамар 3 куска медвежатины, 3 связки кишок кабана и 3 порции паучьей лимфы.', 'Поверь, со стороны готовка выглядит куда сложнее, чем на деле, но...$B$BХоть я и не встречала никого, кому бы захотелось научиться делать колбаски, но на всякий случай рецептик я тебе все же дам. Бери! Ешь, пока рот свеж!', 'Я давно собираюсь начать готовить; где же все компоненты?', NULL, NULL, 'Кишки вепря', 'Медвежатина', 'Паучья лимфа', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (419, 'Пропавший пилот', 'Мой друг и напарник, пилот осадной машины Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его танк на крутой холм и он сломался!$B$BХилдельв, по-прежнему уверенный, что руда в тех горах есть, оставил меня охранять наши танки, а сам пошел дальше пешком.$B$BПрошло уже несколько дней, а я слышал ночью какой-то звериный вой в холмах. Мори – парень-кремень, но мне тревожно.$B$BПрошу тебя, $N, найди его.', 'Найдите пилота Хилдельва.', 'Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками. В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва. Труп одет во все еще превосходно сохранившийся ж$N бригадира.$B$BЭта мрачная сцена показывает, где встретил свой конец пилот Осадной машины.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (420, 'Наблюдения Сенира', 'Трогги, поселившиеся в тоннелях, крайне враждебны: они без раздумий нападают на любого, кто только осмелится туда сунуться. С другой стороны, что-то мне подсказывает, что у тебя хватит сил и умения, чтобы с ними справиться.$B$BЕсли тебе хочется побеседовать с Сениром, то его можно отыскать в Караносе.$B$BА добраться туда и вовсе просто: пройдешь весь тоннель насквозь, а дальше шагай себе по дороге до самого до города Караноса.', 'Доставьте донесение Грелина Сениру Белобороду в Караносе.', 'А что это у нас тут такое? О, донесение от моего братца! Хм-м...$B$BГоворил я ему, нечего поминать королевское имя всуе, да только станет он меня слушать! С другой стороны, кое-кому в Совете не мешает попортить кровь. Ха!$B$BКак бы то ни было, думаю, мне нужно и свое донесение отправить в Стальгорн. Как-то запоздал я с этим делом. Все этот проклятый холод!$B$BСлушай, если тебе это интересно, у меня скоро может найтись для тебя кое-какая работенка...', 'О, приветствую! Как дела? Не хочешь пропустить стаканчик? В такой холод только этим и спасаешься.', NULL, NULL, 'Донесение Грелина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (421, 'Проявить себя', 'Леди Сильвана поручила Вариматрасу завоевать земли людей и дворфов к югу. $B$BНо этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Темного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора. $B$BМне нужен кто-то, искушенный в воинском деле, чтобы разрубить узел, завязанный Аругалом. Убейте 5 белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу. Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом.', 'Далар Ткач Рассвета из Гробницы хочет, чтобы вы убили 5 белоголовов Лунной Ярости.', 'Вы сослужили мне хорошую службу, $C. Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала.', 'Если хотите достойно проявить себя, вы должны убить 5 белоголовов Лунной Ярости. Выполните это, и я позабочусь о том, чтобы ваши умения были востребованы в более серьезных заданиях.', NULL, NULL, 'Белоголов Лунной Ярости убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (422, 'Безрассудство Аругала', 'Для меня загадка, каким образом Аругал вообще был принят в Кирин-Тор. Его знания касательно применения заклинаний были просто мыльным пузырем. $B$BСейчас важно точно выяснить, какую магию применил Аругал, чтобы я мог использовать ее против него и обеспечить владычество Темной Госпожи в Серебряном бору. $B$BВначале Аругал останавливался на пшеничной ферме, что к северу от моста. Один из стражей смерти сообщил о том, что видел какие-то книги с заклинаниями, но не сумел их заполучить. Добудьте для меня ту из этих книг, которая называется \"Зелье Аругала\".', 'Раздобудьте книгу \"Зелье Аругала\" и принесите ее Далару Ткачу Рассвета в Гробницу.', 'Да, это именно та книга, которую я искал, $C. Если ваша приверженность делу Темной Госпожи не ослабела, вас ждет неплохое будущее среди Отрекшихся.', 'Чтобы понять, с чем мы имеем дело, $C, мне нужно внимательно изучить книгу \"Зелье Аругала\". Принесите его мне, или мне придется поискать себе достойного слугу', NULL, NULL, '\"Зелье Аругала\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (423, 'Безрассудство Аругала', 'Изучив деятельность Аругала я понял, что  мои наихудшие подозрения верны. Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин-Тор в самый трудный час. Идиоты! $B$BДля усиления своей никудышной магии Аругал использовал заколдованные предметы. В первую очередь я должен изучить эти предметы. Отправляйтесь в путь и убивайте обжор Лунной Ярости и темных духов Лунной Ярости, пока не наберете достаточного для моих исследований количества их заколдованных наручей. Эти злобные создания обитают к северу и к востоку отсюда.', 'Принесите Далару Ткачу Рассвета в Гробницу 6 наручей обжор Лунной Ярости и 3 наруча чернозлобов Лунной Ярости.', 'Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала. Вероятно, мне следовало поручить вам добыть больше наручей. $B$BТем не менее, вы отменно проявили себя, собирая эти, $C.', 'Мне понадобятся 6 наручей прожорней и 3 наруча темных духов, чтобы я мог полностью разобраться с ситуацией и определиться с окончательным решением по Аругалу. А теперь – за дело. Убивайте прожорней Лунной Ярости и чернозлобов Лунной Ярости, пока не наберете всего, что мне нужно.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (424, 'Безрассудство Аругала', 'Мне потребуется больше времени на раскрытие темных тайн чар Аругала,чем я думал. $B$BНо тем временем мне нужно, чтобы вы помогли разрешить одну небольшую проблему, которую обнаружили наши разведчики. Похоже, Аругал распространил свою магию на Серебряный рудник, находящийся в холмах к юго-востоку отсюда. $B$BЭтот рудник стал бы ценным ресурсом для Вариматраса. $B$BЯ хочу, чтобы вы снесли голову с плеч пораженному скверной старшине рудника Мрачнону Белесому. После его смерти рудник будет нашим.', 'Убейте Мрачнона Белесого и принесите его голову Далару Ткачу Рассвета в Гробницу.', 'Великолепно. Рудник обеспечит нас отменными ресурсами для наших сил по мере нашего продвижения по Серебряному бору и далее по Азероту.', 'Убит ли Мрачнон Белесый? Вариматрасу вряд ли понравится, если мы проигнорируем его повеление.', NULL, NULL, 'Голова Мрачнона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (425, 'Ивар Нечистый', 'Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком. Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый. $B$BНам удалось уйти от Ивара, но он успел как следует приложить Квинна. Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги. $B$BУбейте Ивара, чтобы Квинн мог спокойно поправляться. Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность.', 'Убейте Ивара Нечистого и принесите его голову Ран Йорик на делянку Ивара.', 'О, спасибо. Я очень благодарна вам, $N. $B$BЯ упомяну ваше имя в отчете, который направлю своему вышестоящему начальству.', 'Убит ли Ивар Нечистый? Если вы не готовы сделать это для меня и моего брата, убейте его ради Отрекшихся.', NULL, NULL, 'Голова Ивара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (426, 'Нападение на мельницы', 'Плеть пытается основать базу на мельницах Агамондов. Если им это удастся, они продолжат свои нападения в Тирисфале.$B$BПоступил приказ уничтожить всю Плеть на мельницах.$B$BОтправляйся туда и собери зазубренные ребра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей.$B$BЧтобы добраться до мельниц, иди по дороге на запад. После того как перейдешь мост, поверни на север, и скоро увидишь ветряные мельницы.', 'Соберите 5 зазубренных ребер и 3 почерневших черепа для стража смерти Диллинджера в Брилле.', 'Твои старания не прошли даром, $N! Я не буду благодарить тебя за исполнение долга, но стражи смерти Тирисфаля навсегда запомнят твое имя!', 'Наш бой с Плетью продолжается, $N! Выполни свой долг и вышвырни эту мерзкую безмозглую нежить обратно в Чумные земли!', NULL, NULL, 'Зазубренное ребро', 'Почерневший череп', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (427, 'Война с Алым орденом', 'Документы, которые прислал вершитель Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах.$B$BНо у стражей смерти есть заботы и поважнее: армия Короля-лича растет с каждой ночью. Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом.$B$BДокажи мне, что $gспособен:способна: служить Темной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей 10 воинов из Алого ордена.', 'Убейте 10 воинов из Алого ордена по просьбе вершителя Зуганда.', 'Замечательно, $C. Ваши боевые умения не вызывают сомнений.', NULL, NULL, NULL, 'Воин Алого ордена убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (428, 'Пропавшие стражи смерти', 'Пару недель назад двое наших стражей смерти – Ран и Квинн Йорик, ушли на разведывательное задание в северный Серебряный бор. С тех пор от них не было никаких известий. $B$BОни могли стать жертвами Плети, но даже если это так, мне нужно подтверждение. Найдите этих стражей смерти. $B$BИх первой целью была разведка на полях в северной части Серебряного бора. Начните свои поиски там.', 'Найдите стражей смерти Квинна Йорика и Ран Йорик. ', 'Вы нашли нас! Еще чуть-чуть – и было бы уже поздно...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (429, 'Звериные сердца', 'Мой брат Квинн был тяжело ранен вурдалаком, Иваром Нечистым, и я не знаю, сможет ли он как следует поправиться без помощи магии. Хотя я сама и не фармацевт, но знаю, что наши аптекари могут изготавливать исцеляющие зелья из обесцвеченных сердец воргов. $B$BСобери такие сердца и отнеси их аптекарю Ренферрелу к Гробнице, на юг отсюда. А потом возвращайся ко мне с зельем. $B$BМножество воргов водится между этим местом и садом Мальдена к востоку отсюда.', 'Соберите 6 обесцвеченных сердец ворга и принесите их аптекарю Ренферрелу в Гробницу.', '*Ренферрел берет у вас сердца.*$B$BМеня тревожит известие о том, что наши стражи смерти потерпели неудачу в своей миссии. $B$BБудем надеяться, что таких неудач будет немного. $B$BЯ сейчас дам зелье, но вот вам рецепт – если стражам смерти понадобится дальнейшая помощь, быть может, вы сами сможете им ее оказать.', 'У меня мало времени, $C: Темная Госпожа возложила на меня тяжелую задачу.', NULL, NULL, 'Обесцвеченное сердце ворга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (430, 'Назад к Квинну', 'Вот зелье, которое должно помочь Квинну Йорику поправиться. $B$BА теперь, простите, мне нужно продолжить одно очень важное дело...', 'Отнесите зелье Квинна Квинну Йорику на делянку Ивара, к северу от Гробницы.', '$gКвинн выпивает зелье.>$B$BДа, я чувствую его действие. Вскоре я снова смогу передвигаться. $B$BВы оказали мне большую услугу, $N.', 'Моя сестра сказала, что вы поможете нам. Это правда?', NULL, NULL, 'Зелье Квинна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (431, 'Манящие свечи', '', '', 'Вы берете одну свечу и кладете ее в сумку.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (432, 'Проклятые трогги!', 'Эти проклятые Светом трогги перевернули все мое рабочее место! Ты только глянь, еще одну бочку пороха разворотили!$B$BОх, прямо руки чешутся спуститься к ним да головы поотрывать! Всех бы поубивал!$B$BНо здоровье не позволяет, да еще это потрясение и злость... Они ничего мне не оставили!$B$BЯ бы сам их перебил, да рука уже не так тверда! Иди в карьер и перебей грязных тварей! Я заплачу! Ты только задай им шороху, перебей их!', 'Убейте по просьбе штейгера Камнелоба 6 головоломов из племени Каменной Челюсти в карьере Гол\'Болар.', 'Ох, на душе полегчало...$B$BНо я не успокоюсь, пока все трогги не будут уничтожены! Все до единого!', 'Гр-р-р… Как я зол!', NULL, NULL, 'Головолом из племени Каменной Челюсти убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (433, 'Слуга народа', 'Будучи членом Сената и Лиги исследователей, я взял на себя заботу об искоренении троггской заразы, наводнившей наши земли.$B$BОни ни за что ни про что разнесли карьер Гол\'Болар. Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и выгоняя горняков из шахт. У нас нет выбора, кроме как истребить их как можно больше, отстроиться заново и вернуться к работе.$B$BЕсли вы поможете мне разобраться с троггами, я с радостью возмещу вам затраты времени.', 'Убейте 10 костегрызов из племени Каменной Челюсти по просьбе сенатора Мера Каменная Реликвия из карьера Гол\'Болар.', 'Это только начало. Надеюсь, мы сможем воспользоваться преимуществом, и выделим небольшой контингент горных пехотинцев для защиты этого района. Тогда мы сможем начать восстановление инфраструктуры и вернуть горняков к работе.$B$BСпасибо тебе за помощь, $N.', 'Если мы сможем изгнать тТитанов из карьера Гол\'Болар, это будет первый шаг на долгом пути к избавлению от этой заразы.', NULL, NULL, 'Костегрыз из племени Каменной Челюсти убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (434, 'Нападение!', 'Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Охрана пропустит его без особых проблем.$B$BПока ты $gсобирал:собирала: для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов.$B$BЛесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения стражи! После этого поговори с Триасом.', 'Спрячьтесь в саду и подслушайте разговор лорда Грегора Лесковара и Марзона Бесшумного Клинка. После этого убейте обоих и возвращайтесь к Иллингу Триасу в Штормград.', 'Сделано? Отлично. $N, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу. С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса.$B$BПостарайтесь ни во что не вляпаться.', NULL, NULL, NULL, 'Лорд Грегор Лесковар убито', 'Марзон Бесшумный Клинок убито', 'Подслушайте разговор Лесковара и Марзона', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (435, 'Сопровождая Эрланда', 'Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери. Должно быть, они невероятно голодны, раз смогли счесть меня пищей. $B$BЯ должен доложиться своей коллеге, стражу смерти Ран Йорик. Но чтобы добраться до Ран, мне нужна помощь против этих волков.$B$BПожалуйста, проводите меня! Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья...', 'Проводите Эрланда, защищая его от волков, к Ран Йорик.', 'Спасибо за помощь, $N. Я боялась, что Эрланда погубили опасности Серебряного бора. Но я вижу, что благодаря вашей помощи этого не произошло.', NULL, NULL, NULL, 'Проводите Эрланда к Ран Йорик.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (436, 'Раскопки Сталекрута', 'Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера. В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов!$B$BСталекрут – надежный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать.$B$BОтправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу. Он ведет отчетность по раскопкам и сможет объяснить, чем вызвана задержка.$B$BЧтобы отыскать раскопки, обогни озеро с юга и направляйся на восток.', 'Обратитесь к исследователю Удару Топора.', 'Значит, Джерн хочет узнать, чем вызвана задержка?$B$BЖелезняк как раз пишет подробный отчет о своих последних достижениях, но я буду краток.$B$BДело в троггах!!!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (437, 'Мертвое поле', 'Первые отчеты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мертвом поле. Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство. $B$BМы хотим уничтожить Плеть Ночи. $B$BОтправляйтесь на Мертвое поле и атакуйте Гнилошкуров. Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и ее. $B$BСущность банши обратится в прах. Принесите мне этот прах в доказательство ее смерти.', 'Убивайте гноллов из стаи Гнилошкуров на Мертвом поле. Когда появится банши Плеть Ночи, убейте ее. Сущность банши принесите верховному палачу Хадрику в Гробницу.', 'Я слышал о вашем успешном набеге на гноллов-гнилошкуров, $N, а эта сущность является доказательством смерти банши Плеть ночи. $B$BСегодня Король-лич потерял еще одного прислужника. Вы становитесь еще более ценным союзником в глазах Отрекшихся.', 'Вы уже уничтожили Плеть Ночи, $N? От этого зависит наш успех в борьбе против Гнилошкуров!', NULL, NULL, 'Сущность Плети ночи', 'Исследовать локацию', 'Войти на Мертвое поле', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (438, 'Старая переправа', '$N, мы обнаружили еще одно место, где угнездилась Плеть: это старая переправа. Переправа находится к востоку от Гробницы, и ее патрулируют многочисленные гноллы-гнилошкуры и различная нежить. $B$BПолагаю, Плеть захватила это место неспроста. Отправляйся к старой переправе и выясни, в чем там дело.', 'Отправляйтесь к старой переправе. Поищите причину присутствия там сил Плети.', 'В лодке находится куча спеленутых мертвых тел. А если смотреть на восток через озеро Лордамер, то напротив видна пристань на острове Фенриса. $B$BДолжно быть, разгадку этой тайны стоит искать на острове.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (439, 'Необычная находка', 'Из кучи трупов торчит обнаженная рука. Это рука женщины – тронутая чумой, но относительно свежая. $B$BНа пальце надето кольцо. Вы снимаете кольцо и, осмотрев его, обнаруживаете гравировку: $B$B\"Делии\".', 'Принесите кольцо Делии верховному палачу Хадрику в Гробницу.', 'Говорите, это кольцо было надето на палец недавно погибшей женщины? $B$BВидимо, тело было поднято из общей могилы в Тирисфале, не иначе. Должно быть, гноллы-гнилошкуры таскают эти трупы на остров Фенриса!', '$N, вы вернулись. Я полагаю, ваше расследование дало результаты?', NULL, NULL, 'Кольцо Делии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (440, 'Кольцо с гравировкой', 'Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьей Севреном в Брилле. У него должны быть записи о недавних смертях и, если повезет, он сможет выяснить, кто такая Делия. $B$BНо я бы на это не рассчитывал. Тот, кто подарил ей кольцо, вероятно, уже мертв. Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии.', 'Отнесите кольцо Делии мировому судье Севрену в Брилл. ', 'Некая Делия жила в Брилле не так давно. Она была похоронена в общей могиле, но, если верить вашим словам, ее тело, должно быть, похитили гноллы из стаи Гнилошкуров и утащили в Серебряный бор. $B$BСтая Гнилошкуров, как и вся Плеть, должна быть уничтожена. Я верю, что ты предпримешь к этому надлежащие шаги.', 'Здравствуйте, $N. Что привело вас обратно в Брилл?', NULL, NULL, 'Кольцо Делии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (441, 'Роли, который живет в Подгороде', 'У Делии был муж по имени Роли, проживающий ныне в Подгороде. Если кольцо действительно принадлежало Делии, которая жила здесь, в Брилле, то Роли узнает его. $B$BНайти Роли вы можете в Торговом квартале Подгорода.', 'Отнесите Роли кольцо Делии.', 'Да, это вещица моей жены. Ее постигла та же участь, что и всех, кому не удалось пережить эти суровые времена. Меня не трогает ее смерть, как не трогает и ваш рассказ о похищении ее тела. $B$BПодобные чувства давно остыли во мне. Но желание все еще клокочет в моем мертвом сердце, $N. $B$BЖелание отомстить.', 'Мы знакомы?', NULL, NULL, 'Кольцо Делии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (442, 'Атака на остров Фенриса', 'А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса. $B$BТы снова $gдолжен:должна: добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова!$B$BЯ посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача, $N. Ты $gдолжен:должна: выйти $gпобедителем:победительницей:!', 'Принесите верховному палачу Хадрику в Гробницу голову Тула Когтя Ворона.', 'Смерть Тула Когтя Ворона – значимое событие, $N. Ренферрел рассказывает, что потоки энергии, которые вы высвободили при уничтожении Тула, ощущались аж до Гробницы. $B$BТвои действия получили большой резонанс у Отрекшихся. Твоя ценность в наших глазах растет.', 'Силам Плети нельзя позволить оставаться в Серебряном бору, $N. Возвращайся ко мне с доказательством смерти Тула.', NULL, NULL, 'Голова Тула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (443, 'Лимфа Гнилошкуров', 'Прежде чем мы совершим нападение на остров Фенриса, мы должны понять, кто стоит за Гнилошкурами. Наши аптекари считают, что их особенности связаны со странной жидкостью, текущей по их жилам. $B$BОтправляйся на остров Фенриса, к востоку от старой переправы, и собери лимфу гноллов-гнилошкуров, которых вы там встретите. Образцы нужны аптекарю Ренферрелу, который стоит неподалеку от Гробницы.', 'Принесите 8 бутылок лимфы Гнилошкуров аптекарю Ренферрелу рядом с Гробницей.', 'Отлично. Эта лимфа поможет нам понять природу гноллов-гнилошкуров, а также сможет показать нам, в чем их слабость... $B$B...если она у них есть...', 'Вы собрали лимфу Гнилошкуров, $N?', NULL, NULL, 'Лимфа Гнилошкуров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (444, 'Происхождение Гнилошкуров', 'Я выпарил лимфу, которую ты $gпринес:принесла: мне, и разложил ее на основные компоненты. Мои выводы еще не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией. $B$BПока я продолжу ее изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород. Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров.$B$BИди же. Бетора ты найдешь в Квартале Магов Подгорода.', 'Отнесите образец лимфы Бетору Ледострелу в Подгород.', 'Эта субстанция наполнена могучими заклинаниями, с некоторыми из которых я не сталкивался вот уже долгое время... $B$BСекундочку – мне придется воспользоваться проясняющим заклинанием...', 'Мои исследования требуют серьезной концентрации. Так что, надеюсь, ваш визит не праздный.', NULL, NULL, 'Образец лимфы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (445, 'Доставка в Серебряный бор', 'Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и $gсам понял:сама поняла:.$B$BЯ состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Темная Госпожа.$B$BОтнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору. Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад.', 'Отнесите находки аптекаря Юхана аптекарю Ренферрелу в Серебряном бору.', 'А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований! Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и с Тирисфальских лесов. Кстати, надо бы поскорей отправить те образцы в Некрополь...$B$BАх, простите, $N. Задержитесь в Серебряном бору чуть подольше, такой $C, как вы, всегда нам пригодится.', 'Что у вас за дело ко мне, $C?', NULL, NULL, 'Находки Юхана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (446, 'Тул Коготь Ворона', 'Эта лимфа была создана моим давним коллегой, Тулом Когтем Ворона. До великой войны он был молодым и многообещающим магом, но когда вошел в силу Король-лич, Тул предал своих братьев и перешел на сторону Плети. $B$BЯ и не думал, что он все еще жив, и уж тем более – что он возглавляет набеги Гнилошкуров на нас! $B$BЯ знаю многие из его заклинаний и могу помочь сварить зелье для того, чтобы им противостоять. Отнеси этот свиток обратно к аптекарю Ренферрелу. Там содержатся заклятья, необходимые для изготовления зелья.', 'Отнесите свиток Бетора аптекарю Ренферрелу в Серебряный бор, в Гробницу.', 'Этот свиток весь пронизан могущественной магией. Я никогда не использовал таких сил в зельях... это будет сильнодействующая микстура, и она должна сослужить тебе хорошую службу, если ты решишься атаковать Тула в его крепости на острове Фенриса.', 'Приветствую вас, $N. Что сказал Бетор?', NULL, NULL, 'Свиток Бетора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (447, 'Рецептура смерти', 'Силы Артаса неисчислимы. Но с Новой чумой мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми. $B$BМои исследования показали, что паучья кровь в соединении с токсином, извлеченном из сердца бешеного медведя, дает смертельно опасный эликсир. Собери необходимые субстанции с пауков из Струящейся Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору. Принеси реагенты в Подгород мастеру-аптекарю Фаранеллу из Королевского фармацевтического общества.', 'Соберите 6 сердец медведя и 6 образцов Летящей крови и принесите их мастеру-аптекарю Фаранеллу в Подгород.', 'Аптекарь Ренферрел правильно сделал, что послал вас ко мне, $N. Эти образцы действительно будут весьма полезны. Я немедленно начну изучить их отравляющие и инфицирующие свойства.', 'Приветствую вас, $C. Какое дело у вас к Королевскому фармацевтическому обществу?', NULL, NULL, 'Сердце медведя', 'Летящая кровь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (448, 'Доложиться Хадрику', 'Прежде чем вы нападете на остров Фенриса, доложитесь верховному палачу Хадрику. У него может быть дополнительная информация о том, что вам понадобится.', 'Доложитесь верховному палачу Хадрику в Гробнице. ', 'Если то, что говорит Бетор, – правда, то Тул Коготь Ворона представляет собой силу, с которой нужно разобраться, причем разобраться срочно. $B$BВ качестве помощи можете подобрать себе что-нибудь из нашего здешнего арсенала...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (449, 'Отчет стражей смерти', 'Хотя раны Квинна заживают, я хотела бы доставить наш отчет верховному вершителю Хадрику как можно скорее. В нем содержится информация, которая жизненно важна для захвата Серебряного бора Отрекшимися.', 'Отнесите отчет стражей смерти верховному палачу Хадрику в Гробницу. ', 'Я не ожидал ни такого количества Плети, с каким мы столкнулись в Серебряном бору, ни проблем, которые возникли перед стражами смерти в ходе разведывательной операции. $B$BВаша помощь нашим стражам смерти просто неоценима, $N. Вы заслуживаете похвалы.', 'Удалось ли вам прояснить судьбу стражей смерти?', NULL, NULL, 'Донесение стражей смерти (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (450, 'Рецептура смерти', 'Вы можете еще послужить Королевскому фармацевтическому обществу, $N. $B$BКогда Аругал навел на лес свою никче$Nю магию, он наложил проклятие на одного из наших самых многообещающих сотрудников, аптекаря Берарда. Ставший безвольным слугой Аругала, теперь Берард для нас бесполезен. Но его находки могут быть ценными. Он изучал древнюю чуму, давным-давно погубившую всякую жизнь в озере Лордамер. $B$BРаздобудьте записи Берарда из его кабинета в таверне деревни Погребальных Костров и принесите аптекарю Ренферрелу.', 'Найдите в деревне Погребальных Костров записи Берарда и отнесите их в Гробницу аптекарю Ренферрелу.', 'Записи аптекаря Берарда! В смелости вам не откажешь, $N. Теперь давайте посмотрим, чем занимался Берард прежде, чем сошел с ума...', 'Вижу, $N, вы снова здесь.', NULL, NULL, 'Записи Берарда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (451, 'Рецептура смерти', 'Согласно записям Берарда, мох озерных тихоходов и озерных ползунов может оказаться полезным для решения нашей задачи по изготовлению новой отравы. Эти твари обитают на островах на озере Лордамер на востоке. $B$BОн также упоминает об очень редкой субстанции – твердой опухоли, обнаруженной им у мурлока из племени Злобного Плавника. Очевидно, эта опухоль столь редка, что Берарду удалось раздобыть лишь одну. $B$BСоберите образцы моха, а также редкую твердую опухоль и отнесите их мастеру-аптекарю Фаранеллу в Подгород.', 'Принесите 6 образцов мха озерного ползуна, 6 образцов мха озерного тихохода и твердую опухоль мастеру-аптекарю Фаранеллу в Подгород.', 'Потеря Берарда – серьезный удар для Королевского фармацевтического общества. Но благодаря вашим стараниям и усердным исследованиям аптекаря Ренферрела разработки Берарда по-прежнему будут полезны делу Темной Госпожи. $B$BМы находимся на пороге чего-то великого $N. Если бы вы не были столь искусны в военном деле, я пригласил бы вас вступить в члены нашего Общества.', 'Что вновь привело вас в Подгород, $N?', NULL, NULL, 'Мох озерного тихохода', 'Мох озерного ползуна', 'Твердая опухоль', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (452, 'Засада в деревне', 'Вы очень вовремя добрались сюда, $N! $B$BСовет деревни Погребальных Костров вернется в любой момент. Аругалу же есть чем заняться в крепости. Он использует совет как марионеток, чтобы держать лишенных разума и воли приспешников в деревне под своим полным контролем. Но я уверена, что без руководства совета деревни Погребальных Костров сыновья Аругала взбунтовались бы против своего хозяина. $B$BЯ не могу справиться со всем в этим в одиночку. Мне нужна ваша помощь. Вместе мы сможем погубить совет, на благо леди Сильваны.', 'Помогите стражу смерти Фарлии уничтожить совет деревни Погребальных Костров.', 'Вы бились достойно настоящего последователя Темной Госпожи, Жрендед. Теперь, когда члены Совета мертвы, может быть, мы сможем восстановить контроль над этой деревней раз и навсегда и выбить Аругала из крепости Темного Клыка. Честь имею!', NULL, NULL, NULL, 'Помогите Фаэрлее уничтожить совет деревни Погребальных Костров.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (453, 'Поиски таинственного незнакомца', 'Удачи, $N. Надеюсь, ты найдешь этого парня, причем живым.$B$BСбежав за пределы Темнолесья, он мог пасть жертвой диких зверей.', 'Отыщите незнакомца. Его приметы:Он родом не из Темнолесья.Он – нервный тип.Он сбежал из Темнолесья и двинулся на запад.', '*Трясунчик вздыхает...*$B$BДа, автор этой книги – я. Сумел-таки отыскать меня?$B$BНо если ты прочитаешь мои записи, то узнаешь только половину истории!', 'Кто ты?! Оставь меня в покое!', NULL, NULL, 'Книга с фермы Свена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (454, 'После засады', 'До этого... случая мы все время таскали туда-сюда бочки с порохом. Теперь придется поделить работу: Миран понесет часть бочек, а я присмотрю за остальными.$B$BМне не хочется отпускать Мирана одного. Когда он соберется в путь, проводи, пожалуйста, его.', 'Поговорите с Мираном. ', 'Добрый день, $C.$B$BТы проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Черного Железа.$B$BЯ почти готов, осталось только кое-что проверить. Когда ты соберешься в путь, скажи мне об этом.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (455, 'Альгазская битва', 'Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине.$B$BПопытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов.$B$BНайти Менетилов несложно: пройдешь через Дун Альгаз, потом – по дороге на север, а на развилке свернешь на запад.$B$BМы очень надеемся на тебя, $N. Не подведи нас.', 'Пройдите через Дун Альгаз.Убейте 8 разведчиков из клана Драконьей Пасти и 6 рубак из клана Драконьей Пасти.Об исполнении доложите Валстагу Сталезубу в Гавани Менетилов.', 'Да, нехорошие новости!$B$BКак я понимаю, орки Драконьей Пасти всерьез вознамерились двинуться на Альгаз. Обычно они сидят у себя на холмах и никуда не суются. Что их сподвигло идти на Альгаз? Для меня это загадка...$B$BСпасибо, $N. Может быть, нам понадобится твоя помощь, когда мы пойдем разбираться с орками.', NULL, NULL, NULL, 'Разведчик из клана Драконьей Пасти убито', 'Рубака из клана Драконьей Пасти убито', 'Исследовать локацию', 'Проникнуть в Дун Альгаз.');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (456, 'Природное равновесие', 'Мои приветствия, $N. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. $B$BВесенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают.$B$BК несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. $gЮный:Юная:c: $C, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.', 'Убейте 4 молодых ночных саблезубов и 4 молодых щетинистых вепрей и вернитесь к опекуну Илталайну.', 'Ты хорошо исполнил свой долг, $N.', 'Дел еще немало, $N. Возвращайся ко мне, как только сократишь поголовье ночных саблезубов и щетинистых вепрей.', NULL, NULL, 'Молодой ночной саблезуб убито', 'Молодой щетинистый вепрь убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (457, 'Природное равновесие', 'Сокращение численности молодых особей, обитающих в Тенистой долине – это неплохо для начала, $N, однако нужно выполнить еще некоторую работу.$B$BЛесные ресурсы истощатся слишком быстро, если не решить эту проблему. Охота на диких зверей – это зло, необходимое для блага всех тех, кто обитает в этих землях. Отправляйся в лес и убивай облезлых ночных саблезубов и щетинистых вепрей ради равновесия.', 'Опекун Илталайн хочет, чтобы вы убили 5 облезлых ночных саблезубов и 5 щетинистых вепрей.', 'Твои дела доказывают твою преданность природе, Веткасакуры. Поверь, $С, несмотря на твою юность уже заметно, что тебя ждет блестящее будущее.', 'Твоя работа еще не завершена, $N. Возвращайся ко мне после того, как убьешь 8 облезлых ночных саблезубов и 8 щетинистых вепрей.', NULL, NULL, 'Облезлый ночной саблезуб убито', 'Щетинистый вепрь убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (458, 'Защитница леса', 'Какая отрада, что ты здесь, $C. Шепот лесных духов донес до моего слуха странные вести.$B$BТаинственная защитница леса, Тариндрелла, вернулась в Тенистую долину. Много лет эту дриаду не видели в лесах Калимдора. Что-то определенно не так, если она вновь появилась в этих землях. $B$BНайди Тариндреллу и узнай, что привело ее в наши рощи. Кто-то из Стражей сообщил о том, что ее видели к юго-западу от Альдрассила.', 'Найдите дриаду по имени Тариндрелла.', 'Я вижу, тебе удалось найти меня, юный $r! Друид Мелитар мудро поступил, отправив тебя сюда.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (459, 'Защитница леса', 'Непонятное зло затаилось в лесу Тельдрассила. Взгляни на холмы, где некогда обитали мирные фурболги. Они покинули свои дома и объединились в племя Кривой Сосны.$B$BЛишь порча, вызванная зловещим мхом Скверны, могла быть причиной подобного изменения. Грелли и греллиды кишат в округе, представляя собой угрозу для жителей Тенистой долины. $B$BНапади на этих бесов, $N, и узнай, действительно ли они подпали под чары зловещего мха Скверны.', 'Соберите 8 порций мха Скверны и принесите их Тариндрелле.', 'Твое служение обитателям Тенистой долины достойно награды, $N.$B$BОднако мои опасения подтвердились. Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь.$B$BДруид, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру. Он, как и мы, печется о благополучии леса.', 'Помоги мне подтвердить или опровергнуть мои подозрения, $N. Принеси мне 8 кусочков мха Скверны.', NULL, NULL, 'Мох Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (460, 'В целости и сохранности', 'На вид ты не похож на гнилошкура. Это хорошо. А то я уже потерял надежду... $B$BМеня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула. Он использовал свою магию для \"защиты\" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти. А после создания этих проклятых гнилошкурых гноллов Туле обезглавил меня... и отдал гноллам мою голову в качестве игрушки! $B$BПожалуйста, воссоедини меня с телом. Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле.', 'Отнесите голову Аларика на его могилу.', 'Спасибо, $N. Я опасался, что гноллы изуродовали мое тело. Приятно узнать, что это не так.', 'Видно, что эта могила была выкопана в спешке.', NULL, NULL, 'Говорящая голова (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (461, 'Замаскированный тайник', 'Я знаю об одной тайной нише в крепости, где хранится дорогой сердцу Тула и его давних коллег предмет. В ней также лежит нечто, что вы можете счесть полезным для себя. Возьмите меня туда! $B$BУглубление в стене находится в юго-западной башне крепости, позади пыльной полки. $B$BВозьмите мое тело, а сапоги оставьте здесь. Они мне все равно не по ноге...', 'Отнесите Аларика к замаскированной нише.', 'Вот мы и на месте, здесь открыто. Оставьте меня здесь. Лучшие дни моей жизни я провел в этой крепости, и мысль об упокоении в этих стенах умиротворяет меня. $B$BХорошенько закройте нишу – я не хочу, чтобы эти гнилошкуры нашли меня. $B$BАх, да, и возьмите вот это. Вы это заслужили.', 'Вот это место! Поднесите меня поближе...', NULL, NULL, 'Останки Аларика (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (463, 'Страж Природы', 'Ты ведь $gслышал:слышала: рассказы о Зеленом Страже? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим.$B$BОн живет на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями.$B$BОставь-ка свои денежки мне – покойникам они все равно не нужны. Да и Зеленый Дядя может обломать зуб об твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?', 'Найдите Зеленого Стража. ', 'Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты пришел с добрым умыслом... Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль.$B$BА теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (464, 'Боевые знамена', 'К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен. Драконы припомнили им все, гнали бывших хозяев аж до до самого Грим Батола. Затем орки скрылись в горах к востоку от раскопа Вельгара.$B$BОтсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила.$B$BНапади на этот лагерь, внеси панику в ряды орков. В доказательство содеянного принеси мне боевые знамена клана.', 'Принесите 8 боевых знамен клана Драконьей Пасти капитану Крепкому Кулаку.', 'Отличная работа, $N. Ныне клан Драконьей Пасти уж не тот, что в былые времена, когда оркам служили драконы. Но все равно они опасные противники.$B$BКланом Драконьей Пасти руководит Нек\'рош, сын Некросса – бывшего главы клана. Некросс владел могущественными заклинаниями, с помощью которых он управлял красными драконами. Но когда его силы иссякли... ну, ты уже знаешь эту историю.$B$BНекросс погиб, а его сын поклялся отомстить драконам, убившим его отца.', 'Ну что, ты показал оркам, почем фунт лиха?', NULL, NULL, 'Боевое знамя клана Драконьей Пасти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (465, 'Гамбит Нек\'роша', 'Пока ты $gсражался:сражалась: с кланом Драконьей Пасти, мы получили сведения об их планах.$B$BНек\'рош строит катапульты и планирует взять Менетил в осаду! А у нас тем временем вовсю идет битва при Дун Альгаз, и подкрепления ждать неоткуда!$B$BУничтожь катапульты, прошу тебя. Они стоят в лагере Драконьей Пасти.$B$BВозьми вот этот трут. Пробейся к катапультам и подожги их.$B$BПосле этого найди и убей Нек\'роша. Этот паршивец уже свое отжил...', 'Уничтожьте катапульты Драконьей Пасти.', 'Вы подносите трут к катапульте и высекаете искру...$B$BПламя охватывает катапульту и мигом перекидывается на другие!', 'Вот одна из катапульт. Поджигаем?', NULL, NULL, 'Дворфийский трут (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (466, 'Поиски огневита', 'Я слышал о редком виде руды – огневите. Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза. Огневит очень неустойчив – чуть что, сразу взрывается. Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек!$B$BРаздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах.$B$BАх да, чтобы добыть руду, тебе нужны познания в горном деле. Если у тебя нет необходимых знаний, то... отправь в шахту кого-нибудь из знакомых рудокопов!', 'Принесите 6 партий огневитовой руды пилоту Камнекожицу в Дун Морог.', 'Как раз столько, сколько нужно для экспериментов! Молодец, $N, я в тебя верил! Тут же отправлю материал на изучение. Надеюсь, что мой доброволец хотя бы до первых результатов доживет!', 'Где руда, $N?!', NULL, NULL, 'Огневитовая руда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (467, 'Найдите Камнекожца', 'Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин! И он всегда рад найти новый способ повысить огневую мощь своих орудий.$B$BДо него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет ее. И если тебе уже не терпится взяться за это дело, то найди Камнекожица в поселке Сталежара в Дун Мороге и спроси, чего он хочет.', 'Поговорите с пилотом Камнекожицем. ', 'Привет, $N. Ты тут по моему делу, да? Приятно видеть, как молодой $R рвется на поиски приключений!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (468, 'Отчитайтесь перед горным пехотинцем Рокхаром', 'Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину!$B$BЕсли желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз. Это к северу отсюда, по дороге за сторожевой башней.', 'Поговорите с горным пехотинцем Рокхаром.', '$C ни больше, ни меньше! Желаешь отправиться с нами в разведку? Отлично!$B$BНадеюсь, у тебя есть все необходимое снаряжение, потому что эта \"разведка\" может обернуться и кое-чем похуже...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (469, 'Ежедневная доставка', 'Привет тебе, $gстранник:путешественница:!$B$BНе лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок!$B$BНу а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана.$B$BЯ бы и сам отнес их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза.', 'Отнесите стопку кроколисковых шкур кожевнику Джеймсу Халлорану в Гавань Менетилов.', 'Хмм, да это же от Эйнара, да? Не вижу его уж который день, а шкуры присылает исправно. Опять поцапался со своей благоверной, к бабке не ходи!$B$BНадо бы подослать жену к Сиде – поговорить, чтобы та не выживала мужа из дому...', 'Не интересуется ли добрый $C сапогами из кроколисковой кожи? Могу предложить отличные выделанные шкуры!', NULL, NULL, 'Стопка кроколисковых шкур (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (470, 'Прожорливый слизнюк', 'Каждую неделю я хожу к Гробнице Железноборода, и в этот раз все было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась...$B$BЯ бросила в одного из них сумку, но он взял и засосал ее! Мне едва хватило времени, чтобы сбежать.$B$BА в сумке-то мои вещи!$B$BЯ даже не знаю, какой из этих гадов ее сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что $gсогласился:согласилась: помочь!', 'Отнимите сумку Сиды у неизвестного слизнюка возле гробницы Железноборода и верните ее хозяйке в Гавань Менетилов.', 'Спасибо большущее, $N! Я-то боялась, что ее больше не вернуть!$B$B*Она вытряхивает из склизкой сумки содержимое и собирает мелочь в кучку.*$B$BХм, чего-то я здесь самого нужного и не вижу... посмотри, может, тебе что-нибудь отсюда пригодится.', 'Где же моя сумочка?', NULL, NULL, 'Сумка Сиды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (471, 'Тяжкая судьба помощника', 'Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков. Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных.$B$BЛекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит!$B$BЕсли у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником. Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков.', 'Принесите 6 шкур гигантских кроколисков Джеймсу Халлорану в Гавань Менетилов.', 'Хмм... не думаю, что ты захочешь наняться ко мне в помощники, так ведь?$B$BХе-хе-хе! Да шучу я. Староват ты для этого, да и заметно, что у тебя на роду совсем другое написано. Благодарю тебя за помощь. Шкуры отменные – как раз подойдут мне для работы!', 'Помощник мне – как сын родной! Трудно же ему придется в жизни, одноногому...$B$BА, это ты, $N? Как твоя охота?', NULL, NULL, 'Шкура гигантского кроколиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (472, 'Падение Дун Модра', 'Дворфы Черного Железа захватили Дун Модр!$B$BЯ тяжело ранен, $C. Почти все мои однополчане погибли! Подонки из клана Черного Железа набросились на нас, не успели мы оправиться после взрыва.$B$BНаш командир, Длиннокос, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание...$B$BОчнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длиннокос тоже спасся! Иди в Дун Модр и отыщи его, $r!', 'Отыщите Грима Длиннокоса возле Дун Модра.', 'Какие новости из Менетила принес нам добрый $C? Так-так-так, значит, тебя зовут $N. Приятно познакомиться.$B$BЧто ж, весть добрая. Слава Свету, что молодой Харло выжил. Ранение у него было очень тяжелое, и нам пришлось отправить его в город на единственном уцелевшем скакуне.$B$BОднако в целом ситуация безнадежная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (473, 'Доклад капитану Крепкому Кулаку', '$N. Орки из клана Драконьей Пасти совсем озверели. Им уже мало одного Альгаза. Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков. Он сейчас в крепости, в зале Войны.', 'Найдите капитана Крепкого Кулака и поговорите с ним. ', '$N. Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе. Ты – достойный $R. Нам такие нужны.$B$BИ у меня уже есть для тебя поручение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (474, 'Убить Нек\'роша', 'Катапульты сожжены. Теперь найди и убей вождя Нек\'роша.', 'Убейте вождя Нек\'роша.Принесите голову Нек\'роша капитану Крепкому Кулаку.', 'Чистая работа, $N. Ты нанес сокрушительный удар оркам из клана Драконьей Пасти. Они еще не скоро оправятся от него. К тому же их катапульты больше не угрожают Гавани Менетилов.$B$BТы – достойный $R, а Стальгорн не забывает о героях! Вот твоя награда.', 'Ты уже убил Нек\'роша?', NULL, NULL, 'Голова Некроша', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (475, 'Ветер тревоги', 'Ветер тревоги веет над лесом.$B$BГэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен\'этиль. Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе.$B$BНо вести от Гэроласа что-то задерживаются, и я начинаю волноваться. Отправляйся на восток в Деревню Звездного Ветра – мне нужен отчет Гэроласа, дабы я был спокоен, узнав, что мои братья и сестры спят спокойно.', 'Найдите Гароласа Талветрена в Деревне Звездного Ветра.', 'Хвала лесным духам, ты здесь! Я знал, что Атридас забеспокоится и пришлет помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (476, 'Порча Кривой Сосны', 'Племя Кривой Сосны поражено порчей!$B$BЭти некогда мирные фурболги обратились против покровителей леса. Они подстерегли меня в засаде, когда я выходил из обители Бен\'этиль и разграбили Деревню Звездного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны.$B$BЯ слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придется сделать тебе, $gюный:юная: $C. Остается только надеяться, что безумные фурболги Кривой Сосны еще не уничтожили Бен\'этиль!', 'Вернитесь к Атридасу Медвежьей Шкуре в Доланаар. ', 'Клянусь звездами! Воистину тревожные вести!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (477, 'Пересечение границ', 'Как вы, должно быть, знаете, в деревне Янтарная Мельница окопалась враждебная группа людей. Она держится там в основном за счет поддержки, которую они получают от волшебников Даларана. $B$BЯ не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной Мельницы, показывает, что она имеет немаленькое значение. $B$BОни отправляют повозкой из Хилсбрада сундуки. Многое из привезенного складируется в небольшом лагере к северу от деревни Погребальных Костров. Раздобудьте содержимое одного такого сундука и принесите мне.', 'Раздобудьте содержимое одного из сундуков даларанских волшебников. Деревня Погребальных Костров находится на юге.', '*С любопытством открыв крышку ящика, вы находите в нем множество тщательно упакованных предметов. На самом верху лежит связка пожелтевших от времени карт, на которых, судя по всему, изображено Серебряный бор и другие области западного Лордерона. $B$BПод картами обнаруживается подвеска таинственно-волшебного вида.*', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (478, 'Карты и руны', '*Вы быстро вытаскиваете подвеску из сундука и кладете крышку на место.*', 'Отнесите странную подвеску жрецу Тьмы Алистеру в Гробницу.', 'Карты и эта... эта подвеска? Интересно. $B$BОчевидно, что волшебники Даларана почему-то интересуются Янтарной мельницей, но их цель по-прежнему остается неизвестной. $B$BМожет быть, Далар сможет выяснить, что они там ищут.', 'Узнали что-нибудь полезное, $N?', NULL, NULL, 'Исписанная рунами подвеска (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (479, 'Расследование в Янтарной Мельнице', 'Далар пытается выяснить, каков источник магической силы этих волшебников. А пока что нам нужно замедлить их прогресс любым путем... $B$BМаги, окудники и заступники, несомненно, носят такие подвески. Добудьте их. $B$BЧтобы добраться до Янтарной Мельницы, идите на юг по главной дороге, а на развилке сверните на восток.', 'Добудьте 8 подвесок Даларана и отнесите  жрецу Тьмы Алистеру в Гробницу.', 'Далар выяснил, что несмотря на замедление, процесс плетения чар зашел уже далеко. $B$BНекий очень могущественный волшебник направляет магическую энергию. Его нужно как можно скорее остановить.', 'Надо торопиться, нельзя дать их планам претвориться в жизнь – или мы можем перестать владеть Серебряным бором.', NULL, NULL, 'Подвеска Даларана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (480, 'Ткач', 'Верховный маг огромной силы отвечает за реактивацию энергетического узла. Они уже далеко зашли, так что единственный способ их остановить – это убить его. Это будет тяжело – безусловно, его защищают многочисленные маги и охранники. $B$BВам надо пойти и разобраться с ним, быстро. Когда он будет мертв, принесите мне его посох. Идите немедленно.', 'Убейте даларанского верховного мага, заберите его посох и отнесите жрецу Тьмы Алистеру в Гробницу.', 'Магия волшебников рассеивается, и энергетические узлы вновь засыпают. Ваши усилия оказались плодотворными, $N, и мы сумели нанести нашим врагам и могучим волшебникам Даларана серьезный удар. $B$BОднако нужно не терять бдительности – ведь источник энергии находится совсем близко... Нужно разрабатывать планы на будущее.', 'Быстрее, время на исходе, $N!', NULL, NULL, 'Посох Атэрика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (481, 'Анализ Далара', 'Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников.', 'Отнесите подвеску рунической надписи Далару Ткачу Рассвета в Гробницу.', 'Интересно – похоже, новые махинации Кирин Тора. Это могущественный артефакт. Такие часто использовали могучие волшебники Кирин Тора для передачи магической энергии. $B$BТо, что они так много таких вещиц доставляют в Янтарную Мельницу, указывает на то, что затевается что-то серьезное. $B$BПосмотрим, сумею ли я проникнуть сквозь защиту и поточнее разузнать об их намерениях.', 'Слушаю вас, $C. Что это?', NULL, NULL, 'Исписанная рунами подвеска (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (482, 'Планы Даларана', 'Конечно! Как же я мог забыть?$B$BЯнтарная Мельница была одним из мест, отмеченных магами Кирин-Тора, и примечательна тем, что на территории деревни находится спящий энергетический узел. Волшебники, должно быть, планируют реактивировать узел и использовать его энергию для какой-то более серьезной цели. $B$BМы не можем позволить этому случиться... $B$BЧтобы активировать энергии этого места, понадобится много сил, и мы можем осложнить им задачу, стащив у волшебников подвески. $B$BПередайте эту информацию Алистеру, он спланирует дальнейшие действия.', 'Поговорите с жрецом Тьмы Алистером в Гробнице. ', 'Вы принесли тревожные вести, $N. Если Далар прав – а у меня нет оснований думать иначе – мы должны действовать быстро. $B$BМне нужно выработать совместно с ним план нашей атаки. А тем временем нужно замедлить их прогресс.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (483, 'Реликвии Пробуждения', 'Захватчиков Кривой Сосны видели в обители Бен\'этиль на западе, они крушили там все подряд.$B$BСпящие друиды никогда не смогут выйти из Изумрудного Cна – они даже не понимают, в какую западню угодили, – если мы только им не поможем. Тонкий ритуал спячки нельзя нарушить без реликвий Пробуждения.$B$BОтправляйся в обитель и найди талисман Когтя Ворона, Черное перо, Небесный сапфир и руну Размещения. Друиды хранят их в священных ларцах. Принеси их мне, и я подготовлю ритуал пробуждения.', 'Добудьте реликвии Пробуждения и принесите их Атридасу Медвежьей Шкуре в Доланаар.', 'Тебе удалось это сделать, юный $С! Славно! И как раз вовремя.', '$N, похищенные друиды-вороны навеки останутся в ловушке Изумрудного Сна, если мы не сумеем добыть реликвии Пробуждения из обители Бен\'этиль, что на западе отсюда.$B$BЧем дольше мы медлим, тем неизбежнее их рок.', NULL, NULL, 'Талисман Когтя Ворона', 'Черное перо', 'Небесный сапфир', 'Руна размещения');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (484, 'Шкуры молодых кроколисков', 'Ты, наверное, $Gслышал:слышала; обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему континенту!$B$BУже $gвстречался:встречалась: с Эйнаром? Он – один из охотников, приносящих мне шкуры.$B$BВ последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков.$B$BУчитывая обстоятельства, я готов заплатить высшую цену за стопку шкур. Молодые кроколиски водятся на болотах прямо за городом.', 'Принесите 4 шкуры молодых кроколисков Джеймсу Халлорану в Гавань Менетилов. ', 'Отлично, превосходно! Прекрасные шкуры, $N! Надо немедленно замочить их... но перед этим я хотел бы попросить тебя еще об одной услуге. Думаю, ты справишься.', '$N, я ведь тебя посылал за шкурами? Где же они?', NULL, NULL, 'Шкура молодого кроколиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (485, 'Найти КПХ-9:HL!', 'Вы обнаружили странный металлический предмет яйцевидной формы. Когда вы нажали на какую-то кнопку, яйцо вдруг ожило, открылось и превратилось в непонятный механизм, который проскрежетал механическим голосом:$B$B\"Меня зовут Карлс Пропеллерз, и мой автономный робот поврежден. Просьба найти робота, вставить в него этот маяк, а потом вернуть мне за вознаграждение\".$B$B\"Я вычислил координаты робота – он попал в аварию в устье реки близ Осклизлой скалы\".', 'Отнесите аварийный маяк к автономному роботу Карлса. Робот находится во Внутренних землях, в устье реки близ Осклизлой скалы.', 'Вы помещаете яйцевидный аварийный маяк в механического цыпленка.$B$BС гудением и жужжанием робот поднимается на ноги, после чего из его механических внутренностей слышится голос Карлса:$B$B\"Что ж, по крайней мере, OOX-09:HL работает, но ему требуется капитальный ремонт! Он тяжелый, и нести его ты не сможешь, но вообще у меня есть одна мысль... Не хочешь ли присмотреть за ним еще немного?\"', 'Больше всего это похоже на обломки... механического цыпленка. Изнутри яйца снова раздается голосок: \"Да, отличная работа! Это мой автономный робот. Сенсоры показывают, что без подзарядки он не заведется и не долетит в Пиратскую бухту на починку... Иди вперед и положи маяк в робота – дальше он сам все сделает!\"', NULL, NULL, 'Аварийный маяк OOX-09/HL (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (486, 'Урсал Изверг', 'Настало время спасти друидов-воронов. Если сейчас мы потерпим неудачу, $N, их сон станет вечным.$B$BЯ подготовлю реликвии Пробуждения и совершу обряд. Но чтобы у меня все получилось, тварь, виновная в их злоключениях, должна быть уничтожена. Только тогда ритуал может быть выполнен.$B$BЭто Урсал Изверг разрушил дело наших братьев, и именно он должен теперь заплатить за свои злодеяния ради их освобождения. Отправляйся в Лагерь у Кривой Сосны на юго-западе и убей его.', 'Убейте Урсала Изверга и возвращайтесь к Атридасу Медвежьей Шкуре в Доланаар.', '$N, ты проявил себя как весьма достойный и способный $C. ночной эльф, следующий путем чести столь же неустанно, как ты, обязательно обретет великую славу в этом мире.$B$BДа будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия.', NULL, NULL, NULL, 'Урсал Изверг убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (487, 'Дорога в Дарнас', 'Дорогу в Дарнас нужно охранять. Путники, направляющиеся из Доланаара в Дарнас, рассказывают о варварских нападениях пораженных порчей фурболгов из племени Кривой Сосны.$B$BКаждый день из Дарнаса и в Дарнас поступают грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам.$B$BВозьмись же за оружие во имя священного леса, $C. Их логово находится где-то под этим наблюдательным пунктом. Убей 6 душителей из племени Кривой Сосны и возвращайся ко мне.', 'Убейте 6 душителей из племени Кривой Сосны и найдите часового Амару Ночную Странницу возле Доланаара.', 'Ты славно послужил доброму народу Доланаара и Дарнасса, отважный $С. От имени всех часовых Тельдрассила воздаю тебе хвалу.', 'На дороге все еще неспокойно, $C. Ступай же и убей 6 душителей из Кривой Сосны, а потом возвращайся ко мне.', NULL, NULL, 'Душитель из племени Кривой Сосны убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (488, 'Просьба Зенна', 'Вижу, ты работенку ищешь? Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце $gнаивному юнцу:наивной девчушке:... вроде тебя.$B$BВидишь ли, $N, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесешь.$B$BМне часто бывают нужны определенные... реагенты. Принеси 3 клыка ночного саблезуба, 3 пера островной совы и 3 мотка паутины чащобного тенетника.$B$BИ пусть это все останется между нами, $r.', 'Принесите Зенну Грязному Копыту, стоящему недалеко от Доланаара, 3 клыка ночного саблезуба, 3 пера островной совы и 3 мотка паутины чащобного тенетника.', 'Ха-ха! Хорошая работенка!$B$BКто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать $R? Я даже мечтать об этом не мог! Но раз уж так вышло... Наш милый мир полон неожиданностей.$B$BОбманули дурака на четыре кулака!', 'Ну что, $N, не запыхался? А я все думал, когда же ты принесешь то, что мне нужно…', NULL, NULL, 'Клык ночного саблезуба', 'Перо островной совы', 'Паутина чащобного тенетника', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (489, 'Искупление вины', 'Совет Леса узнал, что ты $gпомог:помогла: Зенну Грязному Копыту! Этот сатир – враг леса! И ты, как $r, $gдолжен бы:должна бы: понимать, что оскверняешь лес, убивая созданий Природы!$B$BТы $gдолжен:должна: искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу! $B$BПреподай Грязному Копыту урок – и заслужишь прощение. Есть такие скверношишки – это семена, падающие с деревьев. Они испускают зеленый дым.$B$BСкорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое.', 'Соберите 3 скверношишки и отдайте их Зенну Грязному Копыту близ Доланаара. ', 'Ну что ты за лапочка! Я знал, что ты мне еще пригодишься!', 'Ой, $N, ты мне что-то принес? Видать, что-то вкусненькое?', NULL, NULL, 'Скверношишка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (491, 'Жезл для Бетора', 'Туле как-то рассказывал мне, что давным-давно он вместе с двумя товарищами создал магический жезл, сплетя его из трех принадлежащих им ученических жезлов. Он был символом их дружбы, и, хотя Тул презрел ее, с жезлом он расстаться не мог и не желал отдавать его другим. Поэтому он выкрал жезл и спрятал его в крепости Фенриса.$B$BЗдесь. Отнесите жезл Бетору Ледострелу, одному из прежних друзей Тула. Я уверен, он будет рад его получить.', 'Отнесите Сплетенный жезл Бетору Ледострелу в Квартал Магов Подгорода.', '... Что это?! У Туле был наш Сплетенный жезл? Я думал, он пропал, когда наша дружба пошла прахом, и Туле примкнул к Королю-личу! $B$BДолжно быть, он не обращался к силе жезла, потому что если бы он сделал это, я бы почувствовал. И хорошо, что Тул не использовал жезл... $B$BЭто удивительная находка. Я признателен за нее, $N, и вознагражу тебя.', '$N, ты сразил Тула Когтя Ворона?', NULL, NULL, 'Сплетенный жезл (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (492, 'Новая чума', 'Один из стражей смерти сообщил, что недавно был захвачен еще один дворф-горный пехотинец. Обычно стражи смерти сажают пленных в погреб таверны \"Петля Висельника\", где им оказывается \"достойный прием\".$B$BПочему бы тебе не пойти и не угостить пленника специальным напитком, который я приготовил? В нем есть небольшая примесь того, что Темная Госпожа готовит для всего Азерота.', 'Отнесите особый напиток Юхана пленному горному пехотинцу. ', 'Ах, наконец-то питье! Хоть это и не \"Болтливое пиво\", но я рад хоть чем-то промочить горло.', 'Будь у меня моя верная винтовка, вы были бы уже мертвы, $C! Погодите, скоро мне на помощь приедет бригада паровых танков!', NULL, NULL, 'Особый напиток Юхана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (493, 'Путешествие в предгорья Хилсбрада', 'Темная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало новую чуму. Мы упорно трудимся и добились значительного прогресса. Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества. $B$BПоэтому я прошу тебя доставить мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада. Путь туда неблизкий. $B$BНаправляйся на юг и держись поближе к дорогам. Строго следуй дорожным указателям!', 'Отнесите находки аптекаря Ренферрела аптекарю Лидону в город Мельница Таррен в предгорьях Хилсбрада.', 'А, отлично. Я в высшей степени уважаю аптекаря Ренферрела. Сгораю от нетерпения начать изучение его работы.', 'У вас ко мне какое-то дело?', NULL, NULL, 'Находки Ренферрела (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (494, 'Время нанести удар', 'Молчи и слушай, $C.$B$BМеня направили сюда для наблюдением за городом Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что стражница смерти Леш передала следующие слова:$B$B\"Крик ворона на западе манит.\"$B$BСтупай по дороге на восток и обращай внимание на знаки. Торопись! Отправляйся в Мельницу Таррен со всей возможной скоростью!', 'Отправляйтесь в Мельницу Таррен и доставьте послание стража смерти Леш верховной вершительнице Дарталии.', 'Крик ворона на западе манит?$B$BОтличные новости! Пора напасть на Хилсбрад. Мы сможем воплотить наш план уничтожения жизни. Вариматрас будет доволен.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (495, 'Корона Воли', 'Муг\'тола и его отряд огров отправили в долину Альтерака за короной воли для леди Сильваны. К сожалению, вместо того чтобы принести ее королеве, этот идиот решил ее примерить... наверное, огры не могут устоять перед блестящими побрякушками.$B$BЕго необдуманный поступок привел к неприятным последствиям. Корона воли позволила Муг\'толу воспротивиться заклинанию подчинения, наложенному на него леди Сильваной.$B$BТемная Госпожа хочет, чтобы это стало уроком для остальных. Отправляйся в Мельницу Таррен в Хилсбраде и поговори с лейтенантом Мелизарой.', 'Поговорите с Мелизарой в Мельнице Таррен в предгорьях Хилсбрада. ', 'Тебя прислала Шарлиндра? Ну хорошо. Вскоре ты поймешь, что я не терплю пустой болтовни.$B$BМуг\'тол – наглец, и с ним мы разберемся быстро, тщательно и безжалостно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (496, 'Эликсир Страдания', 'Еще один мерзкий день в Мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение, $N.$B$BЧем скорее мы заразим здешних людей, тем лучше. Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило.$B$BЕсли ты хочешь принести пользу, добудь для меня следующее: 10 языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с Мельницей Таррен.', 'Аптекарь Лидон из Мельницы Таррен попросил принести ему 10 языков серых медведей и немного лимфы паука-охотника.', 'Отличные компоненты. Что ж, $N, ты умудрился внести хоть немного радости в мой тоскливый день. Благодарю тебя.', 'Я вижу, ты вернулся. Надеюсь, тебе удалось собрать нужные мне вещества. Еще один день без единой смерти совсем в тоску меня вгонит.', NULL, NULL, 'Язык серого медведя', 'Лимфа паука-охотника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (498, 'Спасение', 'Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат.$B$BМы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать.$B$BДарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог\'тара, освободи их.', 'Освободите Друлла и Тог\'тара по поручению Круска из Мельницы Таррен. ', 'Значит, люди собирались поработить наших воинов? Мы еще им покажем!$B$BПохоже, они захватили Гол\'дира, нашего вождя, и держат его в другом месте. Его тоже необходимо отыскать и спасти. Впрочем, пока неизвестно, где он…$B$BКогда у нас появится хоть какая-то зацепка, я немедленно скажу об этом тебе, $N.', 'Торопись, $C. Мне страшно подумать, что люди могут сделать с Друллом и Тог\'таром.', NULL, NULL, 'Освободите Друлла', 'Освободите Тог\'тара', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (499, 'Эликсир Страдания', 'Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания.$B$BВот, готово! Ах, ничто не доставляет столько радости в этих проклятых холмах, как принесение страдания в мир.$B$BПосмотрим, достигнут ли желанный эффект.$B$BДай попробовать моему помощнику Ампи то, что Темная Госпожа готовит людям и созданиям Плети.', 'Дайте Ампи эликсир Страдания.', 'Квак!', 'Ква!', NULL, NULL, 'Эликсир страдания (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (500, 'Награда Раздробленного Хребта', 'Огры из клана Раздробленного Хребта раскопали курган в Альтеракских горах, неподалеку от разрушенного города. Разведчики доносят, что они и сами руины захватили.$B$BМы не дадим им там вольготно расположиться; если они решат, что хорошо устроились, то следующим шагом спустятся с холмов и окажутся прямо рядом с нами!$B$BСтупай на север, в Альтеракские горы и убей побольше огров. Принеси мне грязные кости, которые они таскают с собой, и получишь неплохую награду.', 'Соберите 9 грязных бабок у огров из клана Раздробленного Хребта в Альтеракских горах. Принесите их маршалу Редпату в Южнобережье.', 'Отлично, $N. Должно быть, тебе пришлось зарубить целые полчища, чтобы набрать столько бабок.$B$BТеперь они к нам не сунутся. По крайней мере, некоторое время.', 'Ну как, $N, ты охотишься на огров? Удалось собрать из бабки?', NULL, NULL, 'Грязные кости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (501, 'Эликсир боли', 'О, $N... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит! Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесет в мир заслуженную смерть!$B$BНо как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Темной Госпожи. Помоги мне! В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти. Принеси мне немного крови, и мы повеселимся.', 'Принесите 10 сосудов крови горного льва аптекарю Лидону из Мельницы Таррен.', 'Отличная работа, $N.', 'Я помню тебя, $N. Ты собирался помочь мне составить последний эликсир. Мне нужна кровь горного льва, и я внесу новую толику страдания в жизнь обитателей Хилсбрада.', NULL, NULL, 'Кровь горного льва', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (502, 'Эликсир боли', 'Ах, ничто так не радует, как запах свежей крови в предгорьях!$B$BСмешаем капелюшку этого и щепотку того, и пойдет веселье! Из этой крови я сделаю эликсир Боли. Если мои вычисления верны, то этот состав порадует леди Сильвану. Надо его испытать.$B$BОтнеси этот эликсир на самую северную ферму Хилсбрадских полей, что на юго-западе. Посмотрим, как мое \"угощение\" понравится собачке фермера Рея, Стэнли.', 'Напоите Стэнли эликсиром Боли.', 'Вы наливаете немного эликсира в ладонь и протягиваете ее Стэнли.', 'Ав?', NULL, NULL, 'Эликсир боли (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (503, 'Гол\'дир', 'Судя по добытым тобой документам, Гол\'дира держат на большой базе Синдиката, расположенной на севере, вероятно, в Альтеракских горах. Он уж очень давно томится там в плену, пора освободить его.', 'Освободите Гол\'дира и возвращайтесь к Круску в Мельницу Таррен.', 'Спасибо, $N. По приказу Вождя я вел экспедицию из Дуротара, но, как видишь, наши планы несколько нарушились. Меня держали в плену в этом городе, заставляя работать – таскать тяжести и копать…$B$BВпрочем, неважно, что мне пришлось вынести. Куда важнее сведения, которые тебе необходимо доставить тем, кто сейчас возглавляет нашу группу.', 'Дай мне ключ, $C, и я сам отомкну замок.', NULL, NULL, 'Ржавый железный ключ', 'Исследовать локацию', 'Найти, где держат в плену Гол\'дира.', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (504, 'Наемники клана Раздробленного Хребта', 'Ты уже $gпомерился:померилась: силой с ограми Раздробленного Хребта, а теперь я хочу нанести им настоящий удар…$B$BСтупай в руины Альтерака и отыщи там наемников из клана Раздробленного Хребта. Убей побольше этих тварей – только так им можно показать, что лучше держаться подальше от земель Альянса.', 'Убейте 10 наемников из клана Раздробленного Хребта и возвращайтесь к маршалу Редпату в Южнобережье.', 'Очень хорошо. Вот награда.$B$BКстати, охотясь на огров ты видел город Альтерак. Как он выглядит? Боюсь, что скверно. Огры не славятся своей чистоплотностью.$B$BК счастью, благодаря твоим усилиям они будут держаться подальше от Южнобережья.', NULL, NULL, NULL, 'Солдат-наемник из клана Раздробленного Хребта убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (505, 'Убийцы из Синдиката', 'Меня недавно назначили чиновником в Южнобережье. Моего предшественника убили, и виновников так и не нашли. Впрочем, расследование показало, что скорее всего их нанял Синдикат – группа воров под командованием злодеев-дворян, бывшей знати павшего королевства Альтерак.$B$BЛагеря Синдиката расположены на возвышенности Соферы и на Кинжале Коррана, на севере и на западе от захваченной Ордой Мельницы Таррен. Убей всех союзников Синдиката, которых встретишь в этих лагерях.', 'Убейте 12 преступников и 8 воров Синдиката и возвращайтесь к мировому судье Генри Малебу в Южнобережье.', 'Спасибо, $N. Хотя, быть может, они все еще шныряют неподалеку, будем надеяться, что некоторые из убитых воров и бандитов принимали участие в убийстве прежнего чиновника. Но даже если и нет, Синдикат – позор этой земли и человеческой расы.$B$BСмерть этих бандитов и воров – добрая весть для всего Южнобережья.', NULL, NULL, NULL, 'Преступник из Синдиката убито', 'Вор из Синдиката убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (506, 'Наследие Блэкмура', 'День или два назад ко мне пришел главарь этого Синдиката. Его звали Алиден Перенольд, и он нарек себя лордом этих земель. Он поверил мне свои планы о порабощении орков, выступивших против него, как и планировал его отец и учитель, ненавистный Блэкмур.$B$BКуда важнее то, что он привел с собой свою любовницу, девочку-тростинку по имени Элиза. У нее на шее висело ожерелье, который жаждет заполучить вождь.$B$BСтупай, мне пора уходить, когда я закончу свои дела в лагере.', 'Отнесите собранные Гол\'диром сведения Круску в Мельницу Таррен. ', 'Надо же, какие наглецы эти люди! Мы покажем им, что орки не сдаются!$B$BОтныне это будет нашей целью наравне с тем украшением, которое стремится заполучить наш Вождь. Похоже, одной цели без другой не достичь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (507, 'Лорд Алиден Перенольд', 'Очевидно, что Перенольда необходимо убить, избавив мир от его гнусной сущности. Его поместье расположено к северу отсюда, на берегах озера Лордамер. Твой долг, $N, добыть медальон для Вождя и вернуться сюда.', 'Убейте лорда Алидена Перенольда и допросите его любовницу Элизу насчет ожерелья Тареты.', 'Нет, прошу вас, не убивайте меня! Я не хотела причинять зло вашему народу, он взял меня против воли! Пожалуйста... Пощадите меня!', 'Ч-что вам нужно?', NULL, NULL, 'Лорд Алиден Перенольд убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (508, 'Подарок Тареты', 'Ожерелье? Конечно же, можешь его забрать... Да, забирай! Мне не нужны воспоминания о нем... Просто оставь меня в покое...', 'Верните ожерелье Тареты Круску в деревню Мельница Таррен, что в Предгорьях Хилсбрада.', 'Странно, что вождь пошел на такие затраты ради этой мелочи. Я не всегда понимаю его мотивы, но я последую за ним, каковы бы ни были его приказы. Ты отлично поработал, $N, и я не сомневаюсь, что вождь будет рад услышать о твоем успехе.', 'А, вот и ты, $N. Сопутствовала ли тебе удача?', NULL, NULL, 'Ожерелье Тареты (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (509, 'Эликсир агонии', 'Новый день, новый эликсир. Если бы я тут командовал, я бы позволил Плети и жалким людишкам сцепиться между собой. Им и так нравится убивать друг друга.$B$BУвы, Темная Госпожа хочет ускорить процесс, так почему бы не скрасить унылые дни распространением смерти и болезней по стране.$B$BВот мой план: иди-ка ты во владение Нетандера на юге от Мельницы Таррен и на востоке от реки и Южнобережья. Принеси мне 6 цветков грязного рыла для нового эликсира.', 'Принесите 6 цветков грязного рыла аптекарю Лидону из Мельницы Таррен.', 'А, отвратительная вонь цветков Грязного Рыла. Хоть для чего-то эти грязные гноллы годятся.', 'Как дела во Владении Нетандера?', NULL, NULL, 'Цветок Грязного Рыла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (510, 'Зловещие планы', 'Среди документов вы находите список необходимых припасов. В их число входят самые простые вещи (еда, оружие, одежда) и несколько необычные (маски, масло, яд).$B$BВпрочем, более всего привлекает внимание срочность запроса – согласно документу, доставить все необходимое следует как можно скорее, чтобы \"выполнить важную миссию, нацеленную против Южнобережья\".', 'Отнесите зловещие планы мировому судье Южнобережья Малебу.', '*Малеб изучает документы.*$B$BДурные вести, $N. Судя по сведениям, содержащимся в этих документах, и последним действиям Синдиката, эта банда головорезов объявила войну Южнобережью.', '$N, вид у тебя обеспокоенный. Ты хочешь о чем-то рассказать?', NULL, NULL, 'Зловещие планы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (511, 'Зашифрованное письмо', 'Одно из писем на столе зашифровано.', 'Отнесите зашифрованное письмо хранителю мудрости Диббсу в Южнобережье.', 'Что это? Минуточку... Дай-ка взглянуть поближе.$B$B...$B$BХм, никогда не встречался с таким шифром, но, признаться, в этой области я не очень сведущ.', 'Да, господин? У тебя какое-то дело ко мне?', NULL, NULL, 'Хитро зашифрованное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (512, 'Благородные смерти', 'Боюсь, что главари Синдиката жаждут гибели Южнобережья. Мы должны нанести удар первыми, пока они не успели воплотить свои планы.$B$BОтправляйся в руины Странбрада, в северной части Альтеракских гор. Мы полагаем, что именно там находится штаб-квартира Синдиката.$B$BНам известно, что эту шайку головорезов возглавляет бывшая знать Альтерака. Дворяне скрываются среди прочих посланников Синдиката, но отличить их можно по перстням-печаткам. Разумеется, прежде необходимо их убить.$B$BПринеси мне эти перстни.', 'Принесите 7 альтеракских перстней-печаток мировому судье Малебу в Южнобережье.', 'Лишившись знатных предводителей, Синдикат утратит волю к действию, превратившись в обычную банду разбойников.$B$BТы хорошо послужил Альянсу, $N.', 'Как охота на сторонников Синдиката? Где их перстни?', NULL, NULL, 'Альтеракский перстень-печатка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (513, 'Эликсир агонии', 'Я уже решил, что еще один день пройдет без капли радости, но тут ты $gпринес:принесла: мне цветки Грязного Рыла.$B$BДля начала я приготовлю из них отличную смесь. Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода. Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнется!$B$BВот возьми этот состав Грязного Рыла и немедленно отнеси его аптекарю Фаранеллу.', 'Отнесите смесь из цветков Грязного Рыла опытному аптекарю Фаранеллу в Подгород.', 'Тебя послал аптекарь Лидон? Что ж ты сразу не сказал!$B$BНевзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников.$B$BОн прислал состав Грязного Рыла, какой умница! Я знаю, что замышляет наш друг из Хилсбрада. И мне нравится ход его мысли. Темная Госпожа порадуется наступлению новой чумы.', 'Видишь, я занят, $C? Темная Госпожа велит вывести новую чуму, пока нас не одолела Плеть со стороны Нордскола. С юга же нас теснят люди, поэтому время сейчас – главная ценность. Надеюсь, ты не по пустякам меня тревожишь!', NULL, NULL, 'Смесь из цветков Грязного Рыла (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (514, 'Письмо Грозовой Вершине', 'У меня есть коллега из Стальгорна, который может расшифровать это письмо. Ступай в библиотеку в Зале исследователей Стальгорна и поговори с геологом Грозовой Вершиной. Скажи ему, что тебя прислал я и покажи письмо. Если кто и может прочитать это во всех землях к северу от пика Черной горы, то это он.', 'Отнесите хитро зашифрованное письмо геологу Грозовой Вершине в Стальгорн. ', 'А, шифровка! Да, тут я спец. Дай-ка взглянуть...', 'Тебя прислал Диббс из Южнобережья? Как поживает старый книжный червь?', NULL, NULL, 'Хитро зашифрованное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (515, 'Эликсир агонии', 'Состав Грязного Рыла? Гениально! Почему мне не пришло это в голову?$B$BПожалуй, я добавлю свой коллоид разложения в эту хитрую смесь.$B$BЧтобы активировать отраву в смеси, Лидону понадобится крепкое зелье тролльей крови, немного чешуи наги из клана Пронзающего Гребня и глаза мурлоков из племени Рваного Плавника с южного берега Хилсбрада. Когда ты принесешь ему все составляющие, он мигом все сделает. Ох, как мне не терпится узнать о результатах его эксперимента!', 'Отнесите микстуру грязного рыла, крепкое зелье тролльей крови, 5 чешуек наг из клана Пронзающего Гребня и 5 глаз мурлоков из племени Рваного Плавника аптекарю Лидону в Мельницу Таррен.', 'У меня даже голова закружилась от возбуждения! Какой эксперимент! Ты мне очень помог, $N. Мы будем сеять болезнь и смерть по всем этим землям!', 'Я рад, что ты вернулся, $N. Я уж совсем заскучал. Ни единого развлечения, сижу, травлю и заражаю Ампи, а потом воскрешаю ее. И так целый день.$B$BКак прошло путешествие в Подгород? Тебе удалось зарубить по дороге человечка-другого?', NULL, NULL, 'Микстура из цветков Грязного Рыла (Прилагается)', 'Крепкое зелье тролльей крови', 'Чешуя наги Пронзающего Гребня', 'Глаз мурлока из клана Рваный Плавник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (516, 'Погибель Берена', 'Я получил сообщение, что группа нежити спряталась и готовит атаку против нас. Вооруженные этой информацией, мы можем повернуть все другой стороной и напасть первыми, подавив их планы в самом зародыше. $B$BК сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена. Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками. $B$BЯ полагаюсь на твою изобретательность. Отыщи их и нанеси им сокрушительный удар.', 'Найдите Погибель Берена, убейте 6 чернорабочих Когтя Ворона и 6 стражей Когтя Ворона, а затем вернитесь в Гробницу к жрецу Тьмы Алистеру.', 'Если наши разведчики и агенты продолжат предоставлять столь же ценную информацию, как эта, мы в мгновение ока очистим наши земли от армии Плети Короля-лича.', NULL, NULL, NULL, 'Чернорабочий Когтя Ворона убито', 'Страж Когтя Ворона убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (517, 'Эликсир агонии', 'Пришло время испытать новый эликсир. Но зачем же тратить хорошую, очень заразную болезнь на простых лягушек и собак? Давай устроим настоящее веселье во имя леди Сильваны.$B$BСтупай в Дун Гарок. Знаешь, это казармы, где вечно шныряют эти дворфишки. Укради у них бочонок \"Землекопского портера\". Получив его, я устрою веселую вечеринку!', 'Принесите бочонок \"Землекопского крепкого\" аптекарю Лидону из Мельницы Таррен.', 'Наконец-то! Теперь мы готовы действовать!', 'Иногда я впадаю в такую тоску в этом городишке, что открываю кувшин формальдегида и наслаждаюсь ароматом. Ампи начинает нервничать.$B$BНу что, удалось добыть бочку у дворфов? Честное слово, если я буду пялиться на этот эликсир целый день и ни на ком его не опробую, я закричу!', NULL, NULL, 'Бочонок \"Землекопского портера\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (518, 'Корона Воли', 'Муг\'тол и огры Раздробленного Хребта захватили руины Альтерака. Наказать их всерьез будет нелегко, если не проредить сначала ряды огров.$B$BА уж потом мы продолжим.$B$BЯсно? Отлично. Выполняй.', 'Убейте 10 извергов из клана Раздробленного Хребта по поручению Мелизары из Мельницы Таррен.', 'Снег стал алым от крови огров, но мы не должны останавливаться, пока не втопчем дух и тело огров Раздробленного Хребта в грязь и снег.', 'Я вижу, что задание все еще не выполнено, $N. Сообщить ли мне Шарлиндре о твоей непригодности?', NULL, NULL, 'Изверг из клана Раздробленного Хребта убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (519, 'Корона Воли', 'Тарг, Навозер и Гломмус – лейтенанты Муг\'Тола. Они верны ему, хотя кто там разберет, что вынуждает огров быть верными.$B$BПринеси мне их головы, $N, и нам останется отрубить башку Муг\'Толу вместе с короной.', 'Убейте Тарга, Навозера и Гломмуса и принесите их головы Мелизаре из Мельницы Таррен.', '...а я-то думала, что для начала огры зверски воняют.$B$BКогда ты принесешь мне голову Муг\'Тола, я прикажу отнести ее вместе с этими на пики Альтерака. Неплохой памятник тем, кто идет против воли Темной Госпожи.', 'Мне нужны их головы, а не оправдания.', NULL, NULL, 'Голова Тарга', 'Голова Навозера', 'Голова Гломмуса', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (520, 'Корона Воли', 'Лейтенанты Муг\'Тола мертвы, и нам остается только убить его самого и забрать корону Воли. Нет сомнений, ему не захочется с ней расставаться. Скорее всего, он ждет тебя, учитывая... уменьшение числа его товарищей.$B$BОтыщи Муг\'Тола и принеси мне его голову вместе с короной. Положим конец сопротивлению Раздробленного Хребта.', 'Убейте Муг\'Тола и принесите его голову и корону воли Мелизаре в Мельницу Таррен.', 'Ты с честью выполнил свой долг, $N. Голова Муг\'Тола украсит высочайшую вершину среди руин Альтерака, и стражи смерти сотрут с лица земли остатки клана Раздробленного Хребта.', 'Три головы у меня есть, а четвертой пока не видать. Это будет или голова Муг\'Тола, или твоя. Уж поверь мне на слово.', NULL, NULL, 'Голова Муг\'тола', 'Корона воли', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (521, 'Корона Воли', 'Остается отнести корону Воли Шарлиндре в Подгород. Она уж передаст ее леди Сильване. Но даже не думай воспользоваться ей в личных целях, $N. Пусть тебе послужит уроком судьба Муг\'Тола.', 'Отнесите корону Воли Шарлиндре из Подгорода. ', 'Так значит, этой реликвией воспользовался огр, чтобы не исполнять волю Темной Госпожи…$B$BСтранно, когда в такой небольшой вещи заключается великая сила. Которая попала в такие неуклюжие руки. Молодец, $N. Я отнесу корону леди Сильване и доложу ей о твоих подвигах.', 'Да? О чем ты хочешь доложить?', NULL, NULL, 'Корона воли (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (522, 'Контракт убийцы', 'Это контракт на убийство мирового судьи Генри Малеба. Он был опечатан красным воском с характерным оттиском кольца.', 'Отнесите контракт убийцы мировому судье Малебу в Южнобережье.', '*Малеб изучает контракт.*$B$BТеперь мне понятна подоплека последнего нападения на Южнобережье. Наверное, Синдикат хочет добраться до меня, как и до моего предшественника!', 'Я смотрю, ты тяжело дышишь! Есть, о чем доложить?', NULL, NULL, 'Контракт убийцы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (523, 'Смерть барона', 'Добытый тобой контракт был подписан бароном Вардусом, дворянином из бывшего королевства Альтерака, прославившегося холодным сердцем и необычайной жестокостью. Неудивительно, что за этим стоял барон.$B$BОтыщи его. Отыщи и сверши над ним суд. Должно быть, он прячется в одном из убежищ Синдиката – руинах Странбрада или долине на севере оттуда.', 'Принесите голову барона Вардуса мировому судье Малебу в Южнобережье. ', 'Спасибо, $N. У меня на душе полегчало, когда ты вышиб дух из этого злодея!', 'Пусть барон Вардус не надеется, что Южнобережье возволит ему безнаказанно подсылать к нам своих головорезов. Мне нужна его голова!', NULL, NULL, 'Голова барона Вардуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (524, 'Эликсир агонии', 'За соседней дверью стражи смерти держат нескольких заложников-фермеров. Верховный палач Дарталия подозревает, что среди них скрывается один из военных-стратегов. Очевидно, его нашли мертвым в Чумных землях. Дарталия всегда заботится обо мне и решила передать пленников мне в руки.$B$BПора устроить этим фермерам вечеринку. Ох, повеселимся!$B$BПоставь гниющий бочонок на ковер у них в комнате. Чумной напиток для всех!', 'Поставьте гниющий бочонок на ковер для плененных фермеров. ', 'Вы ставите гниющий бочонок на пыльный ковер.', 'От ковра идет гнилостный запах.', NULL, NULL, 'Испорченный бочонок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (525, 'Все больше тайн', 'Я расшифровал письмо, но не знаю, что с ним дальше делать. Вы нашли его у воров в предгорьях Альтерака? Очень странно...$B$BНадо доставить это письмо мировому судье Южнобережья. Хотя письмо и зашифровано, это ближайший город к горам Альтерака, и если назревает какая-то опасность, то они должны об этом узнать.', 'Доставьте расшифрованное письмо мировому судье Южнобережья Малебу. ', '*Малеб читает письмо.*$B$BЭто расшифровка письма, найденного вами в лагере Синдиката? Оно написано не вором, и даже не альтеракским аристократом.$B$BПохоже, у Синдиката есть связи с другими силами, и мне страшно подумать, что это за силы могут быть.', '$N. Вы шли через предгорья и по горам? Какие вы принесли вести?', NULL, NULL, 'Расшифрованное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (526, 'Слитки светлостали', 'Ты $gнашел:нашла: только один слиток светлостали – этого не хватит, чтобы выковать что-нибудь стоящее.$B$BВернись и поищи еще слитки. Думается, их растащили мурлоки, разграбившие корабль.', 'Найдите 5 слитков светлостали и вернитесь к Глорину Стальному Лбу в Болотину.', '', NULL, NULL, NULL, 'Слиток светлостали', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (527, 'Битва за Хилсбрад', 'Когда говоришь со мной, стой по стойке \"смирно\", $C.$B$BЯ нахожусь под прямым командованием Вариматраса. Наша задача – сдерживать распространение людей, покуда аптекари работают над составом новой чумы.$B$BПо нашим сведениям город Хилсбрад очень уязвим. Твое первое задание – прервать снабжение едой и прочим.$B$BОтправляйся на запад. Устрой налет на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца.', 'Убейте 6 хилсбрадских батраков, 6 хилсбрадских фермеров, фермеров Рея и Гетца и возвращайтесь к Дарталии в Мельницу Таррен.', 'Вольно, $C. Вижу, ты вернулся из боя. Мне доложили, что ты хорошо показал себя в Хилсбраде.', NULL, NULL, NULL, 'Хилсбрадский фермер убито', 'Хилсбрадский батрак убито', 'Фермер Рей убито', 'Фермер Гетц убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (528, 'Битва за Хилсбрад', 'Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно.$B$BНаши стражи смерти докладывают о крестьянах южного Хилсбрада, бегущих в поля. Эти глупцы надеются укрыться в садах, избежав гибели.$B$BПокажи им, как они заблуждаются, $N. Возвращайся в Хилсбрадские поля и отыщи там трусливых крестьян. Рази их направо и налево во имя Темной Госпожи.$B$B<Свободен:Свободна:!', 'Убейте 15 хилсбрадских крестьян и вернитесь к Дарталии в Мельницу Таррен.', 'Смерть все крепче сжимает костлявую руку на горле Хилсбрада. Битва идет хорошо.', NULL, NULL, NULL, 'Хилсбрадский крестьянин убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (529, 'Битва за Хилсбрад', 'Люди Хилсбрада оказывают нам неожиданное сопротивление. Кажется, проблема в кузнеце, снабжающем горожан оружием. Необходимо прервать цепь снабжения.$B$BУбей кузнеца Верринтана вместе с учениками и возвращайся с партией железа. Нам оно пригодится, когда мы одержим победу над Хилсбрадом и нападем на Южнобережье.', 'Убейте кузнеца Верринтана и 4 хилсбрадских учеников кузнеца.Принесите партию железа Дарталии в Мельницу Таррен.', 'Задание выполнено, $C. И, надо сказать, выполнено на славу.', 'Удалось ли тебе выполнить приказ, $C? Мертв ли кузнец Веррингтан и его подмастерья? И где партия железа?', NULL, NULL, 'Кузнец Верринтан убито', 'Хилсбрадский ученик кузнеца убито', 'Партия железа', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (530, 'Месть мужа', 'Когда-то Валдред был моим лучшим другом, а потом убил мою жену. Горевать я уже не способен, но до сих пор жажду мести. Если ты убьешь Валдреда и принесешь мне его проклятые руки, я тебя награжу.$B$BПо последним слухам, он был у Стены Седогрива в южном Серебряном бору. Небось, пытается сбежать в королевство Гильнеас.', 'Убейте Валдреда Морая.Принесите его руки Роли Андреану в Подгород.', 'А, хорошо. Этими руками была убита моя жена, Делия. С тех пор я думал только о мести, и вот ты стал моим оружием.$B$BВозьми кольцо, которое вернул мне ранее. Делия так давно умерла, что я не нуждаюсь в этой безделушке. Лучше я оставлю себе эти руки в память о предательстве друга.', 'Где его руки, $N?', NULL, NULL, 'Руки Валдреда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (531, 'Месть Вайрины', 'Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично!$B$BСкорее убери ее отсюда! Никому здесь не нужны твои страхолюдные трофеи!', 'Принесите голову Старины Черношкура Вайрине Быстрый Ветер в Приют странников.', 'Спасибо, что помог мне выполнить мой маленький план. Я много месяцев жаждала проучить этого надутого самовлюбленного мальчишку, а теперь нам это удалось! Вот, возьми, ты это заслужил.', 'Молодец, $N! Мы его хорошенько проучили! Дай мне голову, я сама ей займусь.', NULL, NULL, 'Голова Старины Черношкура (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (532, 'Битва за Хилсбрад', 'В Хилсбраде царит паника. Думаю, он скоро падет. Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки.$B$BНевзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия. Мы должны уничтожить их главу, чиновника Бернсайда, и весь городской совет. Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации.', 'Убейте мирового судью Бернсайда, и 4 членов совета Хилсбрада. Уничтожьте хилсбрадское официальное объявление. Украдите регистрационную книгу Хилсбрада. Затем вернитесь к Дарталии в Мельницу Таррен.', 'Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, $C.', 'Какие вести ты несешь?', NULL, NULL, 'Мировой судья Бернсайд убито', 'Член совета Хилсбрада убито', 'Хилсбрадское официальное объявление уничтожено', 'Регистрационная книга Хилсбрада');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (533, 'Шпионская работа', 'Наконец-то до нас дошли сведения о местопребывании Гол\'дира. Люди постоянно меняли места его заключения, но мы смогли сузить область поиска до большого лагеря Синдиката на севере отсюда.$B$BСтупай туда, $N, и заполучи все доступные сведения.', 'Добудьте сведения о местонахождении Гол\'дира для Круска из Мельницы Таррен.', 'Наконец-то мы знаем, где держат Гол\'дира. В лагере неподалеку отсюда. Будем надеяться, что на сей раз они не успеют подготовиться как прошлый раз, когда нас застали в расплох.', 'Ну как, удалось что-нибудь узнать? Боюсь, надежды для Гол\'дира все меньше и меньше...', NULL, NULL, 'Послание Синдиката', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (535, 'Валлик', 'Гр-рр... Раненый, умирающий, но не опускающий оружия.$B$BНе сомневаюсь, ты все равно убьешь меня, но если ты принесешь мне немного южнобережского портера – вы ведь такое тоже пьете? – я расскажу тебе то, что ты хочешь знать.', 'Принесите кружку южнобережского портера Валлику в лагерь Синдиката.', 'Принимая во внимание мою неминуемую смерть – думаю, могу с уверенностью сказать, что это самый вкусный напиток в моей жизни... Вот, возьми – когда я помру, мне это все равно не понадобится. $B$BНу, слушай!', 'Так что, ты принес мне чего-нибудь выпить или пришел просто покончить со мной?', NULL, NULL, 'Южнобережский портер', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (536, 'На побережье', 'Меня перевели в Южнобережье из городской стражи Штормграда. Непонятно, как тут вообще люди живут... А как воняет со стороны пристани и днем и ночью!$B$BДа еще старый Редпат на мою голову... Он хочет, чтобы я занялся мурлоками. Ха!$B$BЯ едва могу заставить себя подойти к этим рыбам-переросткам на Западном побережье. Если ты разберешься с ними вместо меня, я буду очень признателен.', 'Убейте 10 волноловов из племени Порванного Плавника и 10 оракулов из племени Порванного Плавника по поручению лейтенанта Фаррена Оринеля из Южнобережья.', 'Надеюсь, этого хватит, чтобы убедить Крассена, что я – ха! – выполняю его приказы и избавляю Южнобережье от страшной и ужасной угрозы, жутких мурлоков! Нет ничего страшнее ярости рыбы-переростка!', NULL, NULL, NULL, 'Волнолов из племени Рваного Плавника убито', 'Оракул из племени Рваного Плавника убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (537, 'Темный совет', 'Это письмо от существа, называющего себя Нагазом, членом сообщества Недремлющего Аргуса. Не знаю, что это за Аргус, но если он в союзе с Синдикатом, то представляет собой угрозу.$B$BОтыщи Нагаза и упомянутых в письме темных магов Недремлющего Аргуса. Найди их и убей.$B$BИщи их в Высокогорье, на севере от Странбрада, где позиции Синдиката сильнее всего.$B$BЕсли повезет, ты найдешь там послов Недремлющего Аргуса.', 'Убейте 4 темных магов Недремлющего Аргуса.Принесите голову Нагаза мировому судье Южнобережья Малебу.', 'Молодец, $N. Не хотелось бы, чтобы Недремлющий Аргус присоединился к Синдикату.$B$BХотя тебе и удалось убить их главаря в этих землях, ясно, что Нагаз был чьим-то слугой. Похоже, Недремлющий Аргус пустил корни по всему нашему континенту.$B$BИли по всему миру.', 'Удалось ли найти послов Недремлющего Аргуса?', NULL, NULL, 'Темный маг Недремлющего Аргуса убито', 'Голова Нагаза', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (538, 'Южнобережье', 'Доброго дня вам, $N. Если вы не против долгого путешествия, то у меня для вас найдется задание, которое поможет пополнить библиотеку Штормграда.$B$BВместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека. Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний! Мы должны восстановить все, что можем.$B$BЮжнобережье – ближайший к руинам Альтерака город. Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом. Он направит вас к руинам, может быть, там вы сумеете найти книги...', 'Поговорите с Хранителем мудрости Диббсом в Южнобережье.', 'Да, конечно, я помню Милтона. Такой типичный книжный червь, будь он здоров...$B$BИ он совершенно прав. Руины Альтерака по-прежнему полны драгоценных документов, которые находятся под угрозой исчезновения!$B$BТеперь-то в Альтераке обитают огры, а их совершенно не волнуют памятники культуры...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (539, 'Битва за Хилсбрад', 'Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса. Более того, львиную долю руды, идущей на вооружение Альянса, добывают именно там.$B$BХотя мы нанесли решительный удар по городу Хилсбраду, Альянс изо всех сил защищает свой рудник.$B$BРудник расположен на юге от Хилсбрада. Ступай туда и убей штейгера, человека по имени Бондс. Убей и его горняков. Альянс надолго запомнит этот урок.', 'Убейте штейгера Бондса и 10 хилсбрадских шахтеров и доложите о проделанной работе Дарталии в Мельнице Таррен.', 'Темная Госпожа будет рада услышать, что у нее появился новый рудник, который поможет вооружить ее бойцов.', NULL, NULL, NULL, 'Штейгер Бондс убито', 'Хилсбрадский шахтер убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (540, 'Сохранение знаний', 'Мерзкие огры поселились в руинах Альтерака, и мне дурно при мысли, что они делают с драгоценными книгами из библиотеки. Спаси все, что можно!$B$BСтупай в руины Альтерака и поищи там фолианты, украденные ограми. Собери все, что сможешь и принеси мне. Больше всего меня интересует одна книга – \"Рука Гри\'лека\". В ней содержится древняя мудрость троллей, о которой я жажду узнать, а последняя копия этой книги находилась именно в руинах Альтерака.', 'Найдите 5 фолиантов и потертую кожаную книгу, называемую \"Рука Гри\'лека\", и принесите их хранителю мудрости Диббсу в Южнобережье.', 'А, вот они! Великолепно! Я немедленно примусь за изучение \"Руки Гри\'лека\".', 'Жаль, что я сам не могу поискать в руинах, но боюсь, старые кости не выдержат пути вверх по горам. А у тебя как идут поиски знаний, $N?', NULL, NULL, 'Найденный фолиант', 'Потертая кожаная книга', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (541, 'Битва за Хилсбрад', 'Дворфы пришли на помощь людям? Проклятые мелкие твари!$B$BЧто ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев. Мы отлично знаем, где скрывается их цитадель в этих краях.$B$BОни построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовется Дун Гарок. Последняя цель этой битвы – осадить Дун Гарок, $C. Глава дворфов, капитан Железная Гора, должен умереть.', 'Отправляйтесь в Дун Гарок и убейте 8 горных пехотинцев, 4 стрелков, 2 жрецов и капитана Железную Гору. После возвращайтесь к Дарталии в Мельницу Таррен.', 'Твои подвиги на поле битвы достойны высочайшей хвалы.', 'Дун Гарок тебе не по зубам, а? А я-то думала, ты доказал свою доблесть в Хилсбраде.$B$BЕсли ты не в силах выполнить это задание, я найду другого, кто достигнет цели. Что до тебя, не сомневаюсь, Темной Госпоже не помешают новые гробокопатели в Тирисфальских лесах.', NULL, NULL, 'Горный пехотинец Дун Гарока убито', 'Ружейник из Дун Гарока убито', 'Жрец Дун Гарока убито', 'Капитан Железная Гора убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (542, 'Возвращение к Милтону', 'Мне понадобится время на изучение \"Руки Гри\'лека\", хотя я не сомневаюсь, что Милтону не терпится вернуть книги в коллекцию Штормграда.$B$BВот книги, добытые тобой в руинах Альтерака. Они уже упакованы и каталогизированы. Отнеси их Милтону Снопу в Штормград, он несомненно будет тебе признателен.', 'Отнесите фолианты Альтерака Милтону Снопу в Штормград.', 'О небо! Глазам своим не верю! Неужели они пережили падение Альтерака? И всех этих огров!$B$BСпасибо, $N. Огромное спасибо! Вы помогли нам сохранить человеческие знания, и прибавили великолепия Королевской библиотеке Штормграда.', '$N, вы вернулись! Как ваша миссия в Альтераке? Вы что-нибудь принесли?', NULL, NULL, 'Фолианты Альтерака (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (543, 'Тиара Перенольда', 'Тиара Перенольда – старая семейная реликвия одного из древнейших семейств Альтерака, входившего в правящие круги до падения королевства. Говорят, что ее изготовили мастера Стальгорна, украсив лучшими изумрудами.$B$BКогда Альтерак пал, тиара была утеряна, хотя поговаривали, что огрский маг Грел\'борг Скряга нашел ее и теперь пытается разыскать на руинах Альтерака другие сокровища.$B$BМы надеемся, что вы отыщете тиару.', 'Доставьте тиару Перенольда Ремингтону Риджвеллу в Штормград. ', 'О, чудесно. Конечно, тиару нужно почистить, но вы, $N, прямо-таки превзошли сами себя. Я велю привести тиару в порядок и немедленно помещу ее в нашу сокровищницу.$B$BПримите мою благодарность за пополнение коллекции семейных реликвий.', 'Приветствую, $N! Постарайтесь не наступить мне на отвороты брюк, костюмчик только что от портного.', NULL, NULL, 'Тиара Перенольда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (544, 'Взлом тюрьмы', 'Я прибыл в Мельницу Таррен с исследовательскими целями, а пришлось разрешать кризис. Видишь ли, четверо Отрекшихся несколько месяцев назад бежали из Подгорода. Они предали своих братьев, но что еще хуже... они украли кое-что у Темной Госпожи.$B$BЭти воры вломились в надежное хранилище и похитили четыре артефакта, необходимых нашим аптекарям для исследований. Сильвана жаждет вернуть эти артефакты.$B$BВоры бежали из Подгорода в Даларан, и волшебники спрятали их в Лордамерских выселках.', 'Найдите предателей и отберите у них артефакты, а потом возвращайтесь к волхву Сиянию Бездны в Мельницу Таррен.', 'Ты оказал Отрекшимся огро$Nю услугу, $N. Нам очень не хватало этих артефактов.$B$BХорошо, что Кеган и другие предатели получили по заслугам.', 'Удалось ли найти воров? И что куда важнее, вернуть похищенное?', NULL, NULL, 'Клинообразный Кровавый камень', 'Шаровидный кровавый камень', 'Осколок Кровавого камня', 'Овальный Кровавый камень');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (545, 'Даларанские патрули', 'Волшебники Даларана создали вокруг сердца своего города огромный магический купол. Некоторые говорят, что он призван защитить город от опасностей, которыми полнятся наши дни, другие же уверяют, будто волшебники захотели работать и строить планы в тишине и покое.$B$BМне лично наплевать, зачем соорудили этот купол. Меня интересуют развалины на окраинах города, где могут быть спрятаны ценные магические предметы.$B$BК сожалению, все окрестности патрулируют волшебники и порабощенные ими элементали.$B$BИтак, напади на них и возвращайся, когда существенно сократишь их число.', 'Убейте 6 даларанских призывателей и 12 порабощенных элементалей. Затем возвращайтесь к волхву Сиянию Бездны в Мельницу Таррен.', 'Замечательно. Теперь в руинах можно спокойно поискать артефакты, если быть осторожным.$B$BСпасибо, $N.', NULL, NULL, NULL, 'Даларанский призыватель убито', 'Порабощенный элементаль убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (546, 'Сувениры смерти', 'Я слышал, что Дарталия призвала тебя в строй, чтобы выступить против людей Хилсбрада. Как я завидую…$B$BПока ты там развлекаешься – убиваешь людей, грабишь города, запугиваешь невинных – я торчу здесь, на страже Мельницы Таррен.$B$BМожет, ты смилостивишься над старым стражем смерти? Видишь, я собираю коллекцию человеческих черепов, а тебе предстоит убить немало смертных. Набери в ходе битвы 30 черепов, принеси мне, и я тебе хорошо заплачу.', 'Страж смерти Самса из Мельницы Таррен попросил принести 30 человеческих черепов из Хилсбрада.', 'Превосходные черепа! И какие красивые! Вот тебе обещанная плата, $N!', 'Итак, $N возвращается? Сколько людей ты убил сегодня? Надеюсь, не одну сотню!$B$BТы несешь мне черепа?', NULL, NULL, 'Человеческий череп из Хилсбрада', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (547, 'Меч Гумберта', 'Верховный палач Дарталия послала меня наблюдать за Дун Гароком издалека. Я разбил лагерь подальше от дворфов. Но пришло утро, мне нужно было вскипятить воду, и я пошел за дровами.$B$BВернувшись, я обнаружил, что мои вещи пропали.$B$BОчевидно, ко мне заглянули дворфийские разведчики из Дун Гарока и украли их. Мне нужен мой меч! Если ты сможешь вернуть его, я буду очень признателен. Там так много дворфов... будет нелегко понять, кто же из них вор.', 'Найдите меч стража смерти Гумберта в Дун Гароке и верните его владельцу в Мельнице Таррен.', 'Ты нашел его!$B$BАх, как приятно чувствовать в руке знакомую рукоять. Премного благодарен!', 'Тебе удалось добыть мой меч, $N? Если верховный палач Дарталия узнает о моей небрежности, она прикажет меня повесить вниз головой!', NULL, NULL, 'Меч Гумберта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (549, 'Разыскиваются: сторонники Синдиката', 'По приказу леди Сильваны все члены организации, именуемой Синдикат, приговариваются к смертной казни. Всех пленных казнят. В настоящий момент организация собирает силы в руинах крепости Дарнхольд на юго-востоке от Мельницы Таррен.$B$BВсем, предоставившим доказательства своих подвигов верховной вершительнице Дарталии, будет дарована щедрая награда.', 'Убейте 10 разбойников и 10 сторожей из Синдиката и возвращайтесь за наградой к верховной вершительнице Дарталии в Мельницу Таррен.', 'Великолепно, $C. Такими темпами мы мигом очистим эти земли от синдикатской швали.', NULL, NULL, NULL, 'Разбойник из Синдиката убито', 'Сторож из Синдиката убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (550, 'Битва за Хилсбрад', 'Поскольку ты $gпроявил:проявила: немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.$B$BОтнеси мое письмо Брагору Кровопалу в Подгород. Можешь гордиться собой, $C.', 'Отнесите запечатанное рекомендательное письмо Дарталии Брагору Кровопалу в Подгород.', 'Так это ты знаменитый $C, нанесший сокрушительный удар по силам Альянса в Предгорьях Хилсбрада? Вести о твоих славных подвигах дошли до Подгорода.$B$BЕсли ты и впредь будешь проявлять подобный героизм, то тебя ожидает великое будущее в рядах бойцов Темной Госпожи.$B$BХотя наша главная проблема – наступление с севера Плети Короля-лича, человеческий вопрос тоже не решен и мешает строить планы битвы. Однако ты сумел доказать, что люди могут пасть. И они падут.', 'Что же заставило $C покинуть поле битвы и прийти в Подгород?', NULL, NULL, 'Запечатанное рекомендательное письмо Дарталии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (551, 'Заколдованный пергамент', 'На этот пергамент наложено заклинание, из-за чего надписи на нем невозможно расшифровать. Вы можете разобрать только одно слово вверху страницы: $B$B$BНагаз$B$B', 'Отнесите заколдованный пергамент Хранителю мудрости Диббсу в Южнобережье, что в Предгорьях Хилсбрада.', 'Опять зашифрованные записки? $B$BХотел бы я уметь разгадывать шифры, чтобы разобрать все странные фрагменты записей, что доходят к нам из Альтерака. Но боюсь, мне не хватает знаний.', 'Ого... Ты хочешь что-то мне показать? Надеюсь, какое-нибудь легендарное сокровище, найденное высоко в горах?..', NULL, NULL, 'Заколдованный пергамент (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (552, 'Месть Гелькулара', 'Мастер Гелькулар почти превратился в Короля Мертвых, когда его ритуальное логово в холмах обнаружила разъяренная толпа людей и зверски убила его. Хуже того, они похоронили моего учителя на кладбище Южнобережья.$B$BНемыслимое неуважение к великому волшебнику. Я его ученик, и хочу отомстить ненавистному городу.$B$BПервым делом нам понадобится жезл Гелькулара. Его ритуальное логово захватили йети. Жезл несомненно находится у одного из них.', 'Отберите у йети жезл Гелькулара и отнесите его новобранцу Тайванду в Мельницу Таррен.', 'Ты нашел его! Великолепно, $N!', 'Удалось ли тебе вернуть жезл Гелькулара? Там так много йети, что найти его будет нелегко. И все же без него не обойтись.', NULL, NULL, 'Жезл Гелькулара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (553, 'Месть Гелькулара', 'Вот, возьми Гелькуларов жезл. Он тебе понадобится.$B$BГелькулар создал для своего заклятья 3 церемониальных погребальных костра. Пламя Азеля и пламя Вераза находятся в Пещерах предгорий. Пламя Узеля находится в пещере выше по склону, в северной части гор.$B$BГелькуларов жезл необходимо зарядить в каждом из этих костров. Завершив ритуал, вонзи жезл в гробницу Гелькулара в Южнобережье, надежно охраняемом человеческом городе на юге. Мы отомстим!', 'Зарядите Гелькуларов жезл силой пламени Азеля, пламени Вераза и пламени Узеля.Вонзите заряженный жезл в гробницу Гелькулара в Южнобережье.', 'Из-под земли доносится глухой грохот.', 'От гробницы Гелькулара исходит духовная энергия.', NULL, NULL, 'Сила пламени Азеля получена', 'Сила пламени Вераза получена', 'Сила пламени Узеля получена', 'Гелькуларов жезл (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (554, 'Расшифровщик Грозовая Вершина', 'Геолог Грозовая Вершина – мастер дешифрования и декодирования. Если ты отнесешь найденный пергамент ему, то при удачном стечении обстоятельств он сможет его прочитать. В настоящий момент Грозовая Вершина работает в штаб-квартире геологов в Стальгорне.$B$BЕсли увидишь его, сообщи о нашем разговоре – в последнее время я много работы на него свалил.', 'Отнесите заколдованный пергамент геологу Грозовой Вершине в Стальгорн.', 'Мудрое решение. Все равно я не верю, что у других ученых хватит умения, чтобы перевести этот свиток. А если он окажется интересным, не бойся – я непременно пошлю за тобой.', 'Опять мне мешают?$B$BА, на этот пергамент наложено очень тонкое, сложное заклинание. Разумеется, я смогу его распутать, но на это потребуется время. А время – деньги.$B$BМожет быть, мне просто купить его у тебя?', NULL, NULL, 'Заколдованный пергамент (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (555, 'Нежный черепаховый суп', 'Ты скоро поймешь, что в Южнобережье готовят лучше, чем во всех землях к северу от Штормграда!$B$BСкажем, возьмем мой секретный рецепт черепахового супа. Иногда ко мне захаживают из самого Темнолесья, чтобы насладиться миской-другой. Правда, в последнее время мне не хватает ингредиентов. Я бы сам пошел к озеру Лордамер у Даларана и поохотился на тамошних хрустогрызов, но это слишком опасно. Если ты принесешь мне черепашьего мяса, я мигом сварю супчик.', 'Принесите 10 кусков черепашьего мяса шеф-повару Джессену в Южнобережье. ', 'Все будут в восторге – здесь снова подают нежный черепаховый суп шеф-повара Джессена!', 'Ну как, удалось найти нужные продукты? Да, скажу тебе, бывали времена поспокойнее. Ах, если бы не было войн...', NULL, NULL, 'Черепашье мясо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (556, 'Каменные талисманы', 'Волшебники Даларана славятся своей связью с элементалями, могущественными созданиями из других измерений, которыми они управляют при помощи магических талисманов. Волхв Сиянье Бездны хотел бы изучить эти талисманы.$B$BСтупай на земли даларанских волшебников на западе от Хилсбрада и собери несколько талисманов.$B$BТакие талисманы носят многие жители Даларана, но я советую поискать их в выселках. Это гораздо безопаснее.', 'Отнесите 10 истертых каменных талисманов хранителю Бел\'варилу из Мельницы Таррен.', 'Отличные талисманы. Хотя, кажется, из них немного выдохлась магия, оно и к лучшему. Пусть для начала наш колдун поэкспериментирует на менее активных образцах.$B$BСпасибо, $N.', 'Где истертые каменные талисманы, $N? Колдун хочет раскрыть их тайны.', NULL, NULL, 'Истертый каменный талисман', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (557, 'Сковывающие браслеты', 'Пока что колдун изучает каменные талисманы, но вскоре ему понадобится и другая часть – браслеты, связующие Стихии. Элементали носят их на запястье, что заставляет их выполнять волю мага.$B$BУбей побольше духов в руинах Даларана и собери с них браслеты Земли, и колдун будет доволен.', 'Принесите 4 браслета земли хранителю Бел\'варилу из Мельницы Таррен.', 'Тебе удалось их найти. Надеюсь, элементали, с которых сняты эти браслеты не очень сопротивлялись?$B$BХм... После смерти у меня атрофировалось не только сердце, но и чувство юмора заодно.$B$BЧто ж, спасибо, $N. Служа колдуну, служишь и Темной Госпоже, да.', 'Здравствуй, $N. Элементали – непростые противники, но я не сомневаюсь, что ты справишься. Ты несешь мне их браслеты?', NULL, NULL, 'Браслеты Земли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (558, 'Автограф Джайны', 'Говорят, что леди Джайна Праудмур из Терамора – одна из величайших героинь Альянса. Когда я вырасту, я тоже хочу стать героем Альянса!$B$BТы $gзнаком:знакома: с Джайной? Окажи мне услугу! Возьми у нее автограф! Я не знаю, как ее попросить, у нее нет времени для таких, как я... другое дело ты! Ты $gтакой же искатель:такая же искательница: приключений, как и она! Готов поспорить, что тебе получить у нее автограф – раз плюнуть!$B$BПожалуйста!', 'Отправляйтесь в Терамор и постарайтесь получить автограф Джайны Праудмур для своего подопечного.', '', NULL, NULL, NULL, 'Автограф Джайны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (559, 'Доказательство Фаррена', 'Ты не поверишь, Редпата не устроили все убитые нами – не скромничай, ты тоже $gприложил:приложила: к этому руку. Теперь он хочет от меня доказательств их смерти. Чтобы я отрубил холодные склизские мурлочьи головы и принес пред его очи!', 'Соберите 10 голов мурлоков на Западном побережье по просьбе лейтенанта Фаррена Оринеля из Южнобережья.', 'Ох, во имя Света! С них же течет на землю какая-то дрянь.$B$BЯ к ним не притронусь! Рыбу еще можно терпеть, но если у нее вырастают ноги и она ходит взад-вперед... Я рыбы уже несколько недель не ел, и поверь мне, в Южнобережье это означает жизнь впроголодь.', 'Ты несешь мне головы, $N?', NULL, NULL, 'Голова мурлока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (560, 'Доказательство Фаррена', 'Знаешь, мне даже прикасаться к этим головам не хочется... Раз уж они у тебя, отнеси их Редпату от моего имени, а?', 'Отнесите мешок с головами мурлоков маршалу Редпату в Южнобережье.', 'Так ты мальчик на посылках у Фаррена?$B$BЕсли ты помог ему добыть эти головы, большое тебе спасибо. Южнобережье нуждается в защитниках.', 'Приветствую тебя. Ты хочешь предложить свою помощь в поддержании порядка в Южнобережье?', NULL, NULL, 'Мешок с головами мурлоков (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (561, 'Доказательство Фаррена', 'Пожалуйста, сообщи лейтенанту Оринелю, что я хотел бы, чтобы он занялся нагами, заселившими Восточное побережье. Когда он добьется результатов, пусть лично доложит о них мне.', 'Поговорите с лейтенантом Фарреном Оринелем из Южнобережья. ', 'Наги, значит. Похоже, Крассен получил те же сведения, что и я... Ха! Он не сможет возвыситься благодаря мне. Позволь объяснить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (562, 'Эй, Штормград!', 'Мой бывший наставник из городской стражи Штормграда послал мне сообщение, что верховное командование Альянса обеспокоено появлением наг. По слухам, тот, кто хорошо проявит себя в этой области, получит повышение – или, по крайней мере, новое назначение.$B$BЕсть одна проблема... я не могу справиться с нагами. Разумеется, прекратить пьяную драку или скрутить воинственного вора я могу, но наги мне не по зубам. Помоги мне, $N!', 'Убейте 10 береговых охотников и 10 сирен из клана Пронзающего Гребня по просьбе лейтенанта Фаррена Оринеля из Южнобережья.', 'Разобравшись с нагами в Южнобережье, я могу не сомневаться в новом назначении. Я вернусь обратно в Штормград... И больше не увижу этот забытый Светом порт.', 'Я уже и письмо написал майору Самуэльсону в Крепость Ветров. Теперь мне нужен результат.', NULL, NULL, 'Береговой охотник из клана Пронзающего Гребня убито', 'Сирена из клана Пронзающего Гребня убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (563, 'Новое назначение', 'Мне будет легко добиться, чтобы мое донесение прочитали. Новый капитан стражи, майор Самуэльсон, был моим учителем еще в Штормграде. Ему не составит труда перевести меня обратно в столицу. Но придется попросить тебя отнести мое донесение ему... Главное, чтобы старина Редпат ничего не узнал.', 'Отнесите донесение Фаррена майору Самуэльсону в Крепость Штормграда.', 'Что такое? А... Значит, мой внимательный ученик занялся проблемой наг Южнобережья. Спасибо, что принес это мне, я непременно приму это во внимание, пересматривая назначения в следующем месяце.', 'Приветствую тебя. Чем могу тебе помочь я, городской стражник Штормграда?', NULL, NULL, 'Донесение Фаррена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (564, 'Серьезная угроза', 'Ничто не злит меня так, как потеря отличных коней. И поверь, эти назойливые мертвяки, синдикатские бандюги и прочие ни на что не годные негодяи лишили нас множества лошадок.$B$BНо я готов поклясться могилой моего прадедушки, что главный враг коней – горные львы Альтерака. Вечно осложняют мою жизнь!$B$BТы считаешь себя героем? Тогда пойди разберись с ними!', 'Убейте 8 горных львов и 10 крупных горных львов по поручению Даррена Малвея из Южнобережья.', 'Отличные новости! Надо было сразу же найти нормального героя войны, чтобы он разобрался со зверюгами. Твой папка гордился бы тобой, $N.', NULL, NULL, NULL, 'Горный лев убито', 'Крупный горный лев убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (565, 'Плащ из меха йети', 'Я, великий Бартоло, сделаю для тебя знаменитый во всем Альянсе, да и во всем мире, плащ из меха йети!$B$BОбыщи весь белый свет, и нигде прекрасней нет! Что, что я слышу, $gмаленький:маленькая:$r? \"Бартоло, твои плащи лучше всех!\" Да, да! Мне не раз это говорили.$B$BБартоло нужен рулон шерсти, плащ жителя холмов от искусного кожевника, тонкая нить и мех йети, конечно! Принеси мне все составляющие, и ты станешь $gсчастливым обладателем:счастливой обладательницей: одного из моих плащей!', 'Принесите Бартоло Джинсетти из Южнобережья рулон шерсти, плащ жителя холмов, тонкую нить и 10 клоков меха йети.', 'Пришло время для колдовской работы Бартоло! Мне не нужен ни посох волшебника, ни жезл мага. Ведь я, великий Бартоло, творю чудеса при помощи простой иглы и нити!', 'Итак, ты вернулся к великому Бартоло. Быть может, все материалы для плаща из меха йети собраны? Или просто хочешь постоять рядом со знаменитостью?', NULL, NULL, 'Рулон шерсти', 'Тонкая нить', 'Плащ жителя холмов', 'Мех йети');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (566, 'Разыскивается: Барон Вардус', 'По приказу верховной вершительницы Дарталии, человек по имени барон Вардус разыскивается по обвинению в многочисленных преступлениях против Отрекшихся. Вардус является высокопоставленным членом преступной организации Синдикат.$B$BВ последний раз его видели на высокогорье Альтеракских гор, к северу от Мельницы Таррен.$B$BОн приговаривается к смертной казни. Для получения награды необходимо предоставить доказательства его гибели верховной вершительнице Дарталии.', 'Убейте барона Вардуса и принесите его голову верховной вершительнице Дарталии в Мельницу Таррен.', 'Ты отлично работаешь, $N. Барон Вардус мертв, и число главарей Синдиката стало меньше. Недолго им осталось лютовать.', 'А, $N. Ты не за наградой за голову барона Вардуса?', NULL, NULL, 'Голова барона Вардуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (567, 'Вооружены и очень опасны!', 'Внимание: вооружены и очень опасны!$B$BСледующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:$B$BКлерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма.$B$BГорожанин Вилкс. Разыскивается за убийство аптекаря Эли.$B$BШахтер Хакетт. Разыскивается за убийство стража смерти Фрая.$B$BФермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода.$B$BВсе перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти.', 'Верховная вершительница Дарталия из Мельницы Таррен назначила награду за убийство клерка Горация Белоконя, гражданина Уилкса, шахтера Хакетта и фермерши Калабы.', 'Да ты неплохой охотник за головами, $C.', NULL, NULL, NULL, 'Клерк Гораций Белоконь убито', 'Горожанин Вилкс убито', 'Шахтер Хакетт убито', 'Фермерша Калаба убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (568, 'Защита Гром\'гола', 'Тром\'ка, $C!$B$BТы на удивление вовремя $gоказался:оказалась: в Гром\'голе. Как командир лагеря вождя, я обязан защищать всех сторонников Орды в этих джунглях. Наша цель – обеспечить бесперебойное снабжение Каменора, а некоторые обитатели здешних мест нам мешают.$B$BЯ поручаю тебе сократить численность ящеров рядом с Гром\'голом. Добившись заметных успехов, возвращайся, и я дам тебе новое задание.', 'Командир Агро\'гош из лагеря Гром\'гол поручил вам убить 15 ящеров-кнутохвостов.', 'Ты исполнил свой долг с честью, $C.', NULL, NULL, NULL, 'Ящер-кнутохвост убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (569, 'Защита Гром\'гола', 'Отправляясь в джунгли, мы не собирались воевать с местными племенами. Главное – снабжение Каменора. Увы, возник ряд сложностей. Местные огры заняли руины Мизджа на юго-востоке от Гром\'гола. Невзирая на многочисленные предупреждения, они продолжают нападать на наши караваны.$B$BЯ приказываю тебе разобраться с этими упертыми ограми.$B$BОтправляйся в развалины и попытайся выбить их оттуда. По крайней мере, преподай им хороший урок.', 'Командир Агро\'гош из лагеря Гром\'гол поручил вам убить 10 огров-громил и 5 огров-знахарей.', 'Отлично. Ты с честью послужил вождю.', 'Как дела с ограми руин Мизжа, $C?', NULL, NULL, 'Громила из клана Мош\'Огг убито', 'Знахарь из клана Мош\'Огг убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (570, 'Чары Мок\'тардина', 'Орда должна узнать о силе магии джунглей и подчинить ее себе. Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями. Я сделаю для тебя особую вещь, $gотважный:отважная:c: $C.$B$BПринеси мне когти тенебрюхих пантер и клык тигрицы. Учти, что клык должен быть безупречно ровным.$B$BЭти твари разгуливают по всем джунглям, но тебе не придется далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке.', 'Предсказатель Мок\'тардин из лагеря Гром\'гол попросил вас принести ему 8 когтей тенебрюхих пантер и безупречный тигриный клык.', 'Ты превосходно знаешь джунгли, $N. Отличная добыча! Я возблагодарю духов за то, что они пожертвовали таких зверей на благо Орды.', 'Добрые ли вести ты несешь?', NULL, NULL, 'Коготь тенебрюхой пантеры', 'Безупречный тигриный клык', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (571, 'Чары Мок\'тардина', 'Следующий компонент будет нелегко найти.$B$BЧтобы связать перья, когти и чистый клык, мне понадобится волшебный шнурок. Нам подойдет лишь сухожилие старой гориллы.$B$BЕго можно добыть только у старых горилл из Мглистой долины. Они кормятся к востоку от Пиратской Бухты.$B$BТолько сухожилие должно быть в идеальном состоянии. Быть может, тебе понадобится убить нескольких зверей, чтобы понять, что именно мне нужно, но результат того стоит.', 'Принесите сухожилие старой гориллы предсказателю Мок\'тардину в лагерь Гром\'гола.', 'Превосходное сухожилие, $N. Твои усилия скоро окупятся.', 'Была ли удача на твоей стороне, $N? Удалось ли тебе добыть сухожилие старой гориллы?', NULL, NULL, 'Сухожилие старой гориллы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (572, 'Чары Мок\'тардина', 'То, что тебе удалось добыть у зверей из семейства кошачьих – лишь первое, что требуется для создания могущественного зачарованного предмета. Меж тем украшения джунглей, усиленные при помощи моих ритуалов, неплохо послужат тебе в деле помощи Орде и вождю.$B$BТеперь же собери для меня перья тропических ловцов. Эти твари как правило прикрепляют перья на лапы. На юге от Гром\'гола, недалеко от большой арены, есть такое племя ящеров.', 'Принесите 10 перьев тропических ловцов предсказателю Мок\'тардину в лагерь Гром\'гол.', 'Великолепно. Я немедленно их подготовлю.', 'Сопутствовал ли тебе успех в охоте?', NULL, NULL, 'Перо тропического ловца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (573, 'Чары Мок\'тардина', 'Остается лишь одно составляющее, и я смогу наложить чары на колье.$B$BК югу отсюда, близко от западного побережья, высоко над утесами, располагается Святой источник. Он вызывает множество конфликтов среди религиозных ученых. Все расы Азерота утверждают, что воды освящены именно для их народа.$B$BВот мое последнее поручение: принеси мне воду Святого источника. Соблюдай осторожность. Сейчас его окрестности захватили наги. С ними тоже следует разобраться.', 'Предсказатель Мок\'тардин из лагеря Гром\'гол попросил вас принести ему воду из святого источника. Кроме того, он поручил вам убить 10 наг-исследователей.', 'Ты принес мне воду Святого источника, и я могу наложить чары на церемониальное колье.$B$BНоси его с гордостью, во имя Вождя и мощи Орды.', 'Я готов к зачаровыванию. Ты выполнил мое поручение?', NULL, NULL, 'Нага-исследователь убито', 'Вода святого источника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (574, 'Особые войска', 'После удара по обычным партизанам Курцена тебе придется вступить в схватку с его особыми отрядами. Они либо выбираются в лес и убивают наших солдат, либо отсиживаются позади поселка Курцена, в пещере, называемой Схрон.$B$BЯ знакома со многими воинами Курцена, и все они отличаются прекрасной подготовкой, верностью и жестокостью. Задание непростое, $N.$B$BЕсли ты сможешь их одолеть, доложи об этом лейтенанту Дорену, моему командиру. Он захочет услышать об этом из первых уст.', 'Убейте 10 коммандос и 6 охотников за головами Курцена.Доложите об этом лейтенанту Дорену из Лагеря повстанцев.', '$N. Сержант Йохва поверила в твои способности, а я поверил ей. Мы и надеяться не могли на подобный удар по силам Курцена. Я боялся, что мы, повстанцы, совсем одни, и не сможем справиться с гениальным полковником.$B$BБыть может, теперь у нас есть надежда.', 'Сержант Йохва говорит, что ты силен и отважен, $C. Докладывай!', NULL, NULL, 'Диверсант Курцена убито', 'Охотник за головами Курцена убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (575, 'Спрос и предложение', '\"Лучший мастер-кожевник Южных морей и старого и нового мира.\" Вот как меня называют! Меня! Дриззлика! Лучшим коже... Кхе-кхе. Короче.$B$BМои товары славятся по всему свету как наилучшие по мнению всех экспертов!$B$BЯ только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину его любимых превосходных сапог. Не скрою, это самая популярная модель.$B$BЧтобы приступить к раскройке, мне нужны шкуры кроколисков. Их можно добыть у реки в северной части Тернистой долины.', 'Принесите 2 большие шкуры речного кроколиска Дриззлику из Пиратской Бухты.', 'Эти шкуры отлично подойдут. Качество не слишком важно, учитывая, что они идут на внутреннюю отделку сапог, главное, чтобы носить было удобно.$B$BЕсли шкуры жестковаты, я вымочу их в тигриной крови. Вот они, секреты мастерства, да?', 'У меня все готово, не хватает только шкур. Одно тебе скажу, не надо заставлять Ридлвокса ждать.$B$BНе стоит расстраивать главного изобретателя Союза ремонтников.', NULL, NULL, 'Большая шкура речного кроколиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (576, 'Смотри в оба', 'Стой! Кто идет?$B$BАррр, кому я нужен без волшебного глаза. Мало того, что я лишился зрения в бою! Но тогда мне свезло, и один волшебник зачаровал для меня особый стеклянный глаз, и я снова мог видеть.$B$BА вчера на меня по дороге накинулись пираты Кровавого Паруса и отобрали у меня глаз! Кажется, эти типы чувствуют себя в Пиратской Бухте как дома.$B$BНе поможешь старому морскому волку вернуть зрение?', 'Диззи Одноглазый из Пиратской Бухты попросил вас отобрать его глаз у пиратов Кровавого Паруса.', 'Лопни моя селезенка! Разрази меня гром! Ты нашел мой прекрасный глаз! Проверим, годится ли он по-прежнему.$B$BХо! Я вижу, вижу!!!', 'Эгей, приятель! Может, я и не вижу ничего, но чую я тебя аж с другой стороны порта.$B$BГлаз бы мне не помешал. Капитан меня протащит под килем, если узнает, что моя гляделка в руках грязных пиратов Кровавого Паруса.$B$BКому нужен слепой впередсмотрящий? Я буквально жил на марсовой площадке... а теперь мне в лучшем случае поручат драить палубу.', NULL, NULL, 'Глаз Диззи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (577, 'Добыча шкур', 'Что ж, я раскроил основу сапог, получается превосходно, но на подбой шкур не хватит.$B$B\"Что же делать, Дриззлик?\" – спросишь ты. К счастью, ты говоришь со мной, и я скажу тебе, как мы поступим!$B$BПодбой все равно никто не видит, поэтому мы используем более толстую и дешевую шкуру кроков с озера Назферити.', 'Отнесите 5 шкур кроколисков-хрустогрызов Дриззлику в Пиратскую Бухту.', 'Мои сапоги не хуже колбасы, $N. Выглядят отлично, на вкус прекрасны. Я говорю, что внутри сверхкачественное мясо и приправы, и вы едите их с удовольствием.$B$BТак куда приятнее – и вкуснее – если не заглядывать внутрь.', 'Превосходные сапоги Дриззлика – отличная работа, стопроцентная кожа морских кроколисков. Лучше не бывает!$B$BОписания заманчивей не придумаешь, верно?$B$BРазве что ты принес мне шкуры?', NULL, NULL, 'Шкура кроколиска-хрустогрыза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (578, 'Камень приливов', 'Если правду говорят о гоблине-маге и элементалях воды, живущих на острове, значит я могу заполучить Камень Приливов!$B$BНайди этот остров... И выясни, что происходит. И если ты хочешь узнать подробнее о Камне Приливов, отнеси эту записку в библиотеку Штормграда, они найдут тебе книгу, в которой я впервые прочитал эту легенду.$B$BНеужели Газбан в самом деле нашел Камень?..', 'По поручению барона Ревилгаза из Пиратской Бухты найдите остров, населенный духами Воды.', 'Значит, легенды не лгут! Немыслимо!$B$BТеперь надо отыскать способ одолеть проклятье Камня Приливов, если мы хотим найти его. Проклятья – дело магов. Значит, надо обратиться к одному из них.', NULL, NULL, NULL, 'Исследовать локацию', 'Найдите остров духов Воды', 'Библиотечный свиток', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (579, 'Библиотека Штормграда', '', '', 'Какая книга вас интересует, $N?', NULL, NULL, NULL, 'Библиотечный свиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (580, 'Потерянный грог Алкача Виски', 'На подходе к Отвесным скалам, как раз в тот момент, когда старые добрые Внутренние земли показались на горизонте, нас настигла жуткая буря. Мы думали – все, нам каюк, море нас проглотит.$B$BНо старый Алкач знает, что такое жидкая храбрость! У кэпа был ящик портвейна \"Пупелливербос\", который мы взяли трофеем у одного пирата по пути в Штормград.$B$BВ общем, когда с Внутренних земель налетел шторм, я налег на грог. И тут шхуну захлестнула большая волна и смыла бутылки за борт. Кэп всыплет мне по первое число, если ты не поможешь их найти.', 'Алкач Виски из Пиратской Бухты попросил вас принести ему потерянные бутылки портвейна \"Пупелливербос\".', 'Лопни моя селезенка! Ты нашел грог кэпа!$B$BЯ по гроб жизни тебе обязан, друг.$B$BПохоже, снаружи разыгрался шторм. Пока он не пройдет, я согрею нутро грогом из одной из этих славных бутылочек...', 'Разрази меня гром! У меня почти кончилась выпивка! Кэп собирается поднять якоря, а старый Слим засохнет, как пустыня Танарис. А уж когда кэп узнает, что пропал его портвейн... лучше сразу за борт!', NULL, NULL, 'Портвейн \"Пупелливербос\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (581, 'Поиски Йеннику', 'Нас постиг злой рок. И коснулось это младшего сына моего вождя. Как у нас и заведено, мы отдали его на воспитание племени Гурубаши в Зул\'Гурубе, но после того, как племя Черного Копья последовало за орком Траллом, бедняга Йеннику оказался потерян для нас. Меня прислали в Тернистую долину из далекого Оргриммара на поиски сына вождя.$B$BЯ думаю, он в руках племени Кровавого Скальпа.$B$BЕсли ты хочешь помочь мне, напади на них. Они живут к северу отсюда. Собери их клыки и принеси мне.', 'Принесите 9 клыков троллей из племени Кровавого Скальпа Нимбойе в лагерь Гром\'гол.', 'Отличные клыки, $N. Значит, у тебя хватило сил на сражение с племенем Кровавого Скальпа.$B$BИ это очень хорошо, потому что охота далеко не закончена.', 'Охотник. Докажи мне, что воины Кровавого Скальпа пали от твоей руки.$B$BГде твои трофеи?', NULL, NULL, 'Клык тролля из племени Кровавого Скальпа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (582, 'Охота за головами', 'Мы должны узнать, мертв ли Йеннику.$B$BУбей как можно больше охотников за головами из племени Кровавого Скальпа и забери у них сушеные головы. Набери как можно больше голов, и я осмотрю их, чтобы убедиться, что среди них нет головы Йеннику.$B$BЕсли племя Кровавого Скальпа убило Йеннику, да падет 600-летнее проклятье на душу их предводителя, Ган\'зулаха!$B$BСтупай, $N. Охотников за головами можно найти в Руинах Зуулдая и Зул\'Кунды, в северной части побережья.', 'Принесите Нимбойе из лагеря Гром\'гол 20 сушеных голов. ', 'Спасибо, $N. Я осмотрю эти головы и узнаю, пал ли бедняга Йеннику под ударом топора охотника за головами.', '$N. Я боюсь за сына нашего вождя. Ты принес мне головы? Я хочу их осмотреть.', NULL, NULL, 'Сушеная голова', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (583, 'Добро пожаловать в джунгли', 'Добро пожаловать в Тернистую долину!$B$BБыть может, ты не знаешь об этом, но этот дворф – сын единственного и неповторимого Хеминга Эрнестуэя, прославленного героя Альянса и великого охотника на крупную дичь. Подобно отцу, он не слишком жалует гостей, но на твою долю выпало немало приключений, $C.$B$BСтупай, поговори с ним. Яблочко от яблоньки, как говорится, далеко не падает... наверное, он сможет научить тебя охотиться.', 'Поговорите с Хемингом Эрнестуэем-младшим.', 'Приятно познакомиться, $N. Давно в наши края не забредал $C. Я здесь с одной-единственной целью – поймать крупного и хитрого зверя. Раз ты, так сказать, личность героическая, может, захочешь принять участие в охоте? Впрочем, сначала покажи, на что способен.$B$BЯ научу тебя охотиться на ящеров. Ажек – на тигров. А сэр Эрлгедин – мастер выслеживать пантер.$B$BПокажи нам свое искусство, и сможешь принять участие в большой охоте.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (584, 'Головы племени Кровавого Скальпа', 'Я не нашел Йеннику среди голов, хвала Великому Змею за это. Но мы не сильно продвинулись в наших поисках.$B$BНеобходимо выяснить правду, и, боюсь, она известна лишь вождю племени Кровавого Скальпа и его знахарю. Они враги племени Черного Копья, и просто так говорить не будут, поэтому мы должны вырвать правду из их мертвых губ!$B$BПринеси мне головы Ган\'зула и Неззилока Зловещего и помести их в этот котел.$B$BЭти тролли живут в глубине руин Зул\'Кунды. Принеси их головы... а уж говорить мы их заставим.', 'Принесите головы Ган\'зулы и Неззилока и положите их в бурлящий котел в лагере Гром\'гол.', 'Вы кладете в котел головы Ган\'зулаха и Неззилока...', 'Зеленый отвар в котле бурлит.', NULL, NULL, 'Голова Ган\'зулаха', 'Голова Неззилока', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (585, 'Разговор с Неззилоком', '<Голова Неззилока начинает говорить.>$B$BЭто правда. Я знаю, куда увели дитя племени Черного Копья. Ты $gодолел:одолела: меня и $gсвязал:связала: мой дух, но я все равно не буду говорить даром!$B$BПлемя Кровавого Скальпа враждует с племенем Дробителей Черепов. Чтобы добиться от меня ответа, укради 3 трофейных черепа у племени Дробителей Черепов и положи их к нам, чтобы мой дух обрел рабов в Пустоте. Один череп возьми в Балиа\'ма, другой – в Зиата\'джаи, а последний – в Зул\'Мамве.', 'Принесите в лагерь Гром\'гол трофей из Балиа\'ма, трофей из Зиата\'джаи и трофей из Зул\'Мамве и положите их в бурлящий котел.', 'Да. Ты сослужил мне добрую службу. Когда мой дух освободится, я войду в Пустоту и обрету трех отличных слуг!$B$BТы – гордость своего клана, $R, и умилостивил меня.', 'Я жду черепов...', NULL, NULL, 'Трофей из Балиа\'ма', 'Трофей из Зиата\'джаи', 'Трофей из Зул\'Мамве', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (586, 'Разговор с Ган\'зулахом', '<Голова Ган\'зулаха начинает говорить.>$B$BБудь ты $gпроклят:проклята:! И будь прокляты твои предки!!!$B$BЛишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что:$B$BОтправляйся в сердце владений Дробителей Черепов на востоке. Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому. Ха! Принеси мне его разбитую броню, если сможешь!$B$BДа оторвет он у тебя руки и ноги и бросит медленно гнить. Да станешь ты добычей падальщиков!', 'Убейте 8 охотников, 6 охотников за головами и 4 берсерков из племени Дробителей Черепов.Принесите разбитые доспехи Ана\'тека к бурлящему котлу в лагере Гром\'гол.', 'Мне не хочется верить тебе, но увы, ты несомненно выполнил мое задание. Теперь, когда Анатек пал, гнев мой поостыл.$B$BТвоя сила приведет тебя к великим свершениям, $N. Но однажды... Мы встретимся в Пустоте, и снова померяемся силой.$B$BЯ буду ждать тебя.', 'Хотя моя собственная плоть постепенно облезает с черепа, я чую твой страх.$B$BХа! Ты никогда не справишься с моим заданием...', NULL, NULL, 'Охотник из племени Дробителей Черепов убито', 'Охотник за головами из племени Дробителей Черепов убито', 'Берсерк из племени Дробителей Черепов убито', 'Поврежденный доспех Анатека');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (587, 'Понюшка табака', 'Ах, жизнь моряцкая! Не скажу, что она хороша, но это моя жизнь.$B$BПришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку. Вредные привычки, но что за пират без пороков, а?$B$BТолько представь, как я был разочарован, узнав, что местный травник распродал весь товар. Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса.$B$BГотов поспорить, что $gбесстрашный:бесстрашная: $C вроде тебя сможет убедить их поделиться товаром, а?', 'См. Понюшка табака. Диг из Пиратской Бухты попросил принести ему 15 понюшек табаку.', 'Отличная работа, $N! И я даже в море отплыть не успел! Не знаю даже, как тебя благодарить.', 'Ну как, удалось найти товары, дружище?', NULL, NULL, 'Понюшка табака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (588, 'Судьба Йеннику', '<Неззилок говорит.>$B$BТы $gсумел:сумела: угодить и мне, и вождю, и я скажу тебе то, что ты хочешь знать…$B$BЮный Йеннику навеки потерян для своего клана.$B$BЕго забрал к себе знахарь Занзил Отверженный. Теперь Занзил полностью подчинил себе его тело и душу, и лишь сильнейшая магия может освободить его.$B$BТы такой магией не владеешь, $C.$B$BБыть может, племя Черного Копья, ваши союзники, могло бы подарить надежду на спасение Йеннику. Но лично я сомневаюсь.', 'Поговорите с Кин\'вилаем. ', 'Занзил Отверженный??$B$BЕсли Йеннику и правда попал в руки этого тролля, могущественного и злого знахаря, то надежды почти нет. Почти. Не больше букашечки.$B$BНо малая надежда лучше, чем совсем никакой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (589, 'Поющие кристаллы', 'Легенды повествуют о драгоценном камне, сокрытом в самом сердце Тернистой долины. Мы зовем его Оком разума, и он хранит в себе великую мощь. Если добыть этот камень, быть может, удастся вернуть Йеннику из тьмы.$B$BЯ попрошу духов джунглей помочь нам в поисках Ока разума. Тем временем отправляйся в рудник Хрустальной шахты на юго-востоке отсюда и добудь пульсирующие синие осколки из железозубых василисков. Осколки встречаются очень редко, но без их магии мы не сможем подчинить себе Око разума.', 'Принесите 3 пульсирующих синих осколка Кин\'вилаю в лагерь Гром\'гол.', 'Молодец, $N. Эти осколки правильной формы, и я уже слышу их голос.$B$BПока тебя не было, я говорил с духами джунглей. Теперь я знаю, где находится Око Разума…$B$B...И кто его охраняет.', 'Ты принес осколки, $N? Без них нам не обойтись, даже когда удастся заполучить Око Разума.', NULL, NULL, 'Пульсирующий синий осколок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (590, 'Выгодная сделка', 'Что?$B$BЧТО?!$B$BДенег хочешь? Не должен я тебе никаких денег. $B$BПисьмо? Какое письмо? Может, еще и подеремся? Ну, $gприятель:подружка:, давай! Вот еще, деньги я должен...', 'Одержите победу в схватке с Кальвином Монтеччи в Могильнике.', 'Невероятно! Какое мастерство! $B$BА я-то думал, ты будешь легкой добычей, $N. Да, хорошенько ты меня отделал. $B$BВот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать.', NULL, NULL, NULL, 'Победите Кальвина Монтеччи.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (591, 'Око разума', 'Око Разума находится у огра-мага на востоке отсюда, в глубине холма Мош\'Огг. Этого мага зовут Май\'Зот, и я помню его с тех пор, как племя Черного Копья обитало в Тернистой долине. Он жесток и силен.$B$BА если у него есть Око Разума, тем могущественней его магия.$B$BВступи с бой с Май\'Зотом и отними у него Око Разума. Задание опасное, но лишь так мы можем надеяться спасти Йеннику.', 'Отнесите око разума Кинвилаю в лагерь Гром\'гол. ', 'Тебе удалось добыть Око? Твою силу должно воспевать в легендах, $N!$B$BКроме того, добывая око ты одолел Май\'Зота и отправил его в Пустоту. Вот почему духи молчали о нем.$B$BХорошо, что он покинул мир плоти и крови, но боюсь, что теперь, в царстве духов он снова захватит власть.$B$BВпрочем, об этом будем беспокоиться в другой раз. А теперь я проведу ритуал, чтобы приспособить Око Разума для наших нужд...', 'Приветствую тебя, $N. Духи поют хвалу твоей храбрости, но о победе над Май\'Зотом они молчат.$B$BНесешь ли ты мне Око?', NULL, NULL, 'Око разума', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (592, 'Спасение Йеннику', 'Я превратил Око Разума в самоцвет Души. Он послужит двоякой цели: оглуши при его помощи Йеннику, а затем помести самоцвет ему на голову, чтобы поймать его душу.$B$BПотом отнеси камень Нимбойе.$B$BЙеннику живет у Занзила Отверженного, в руинах Абораза на Хрустальном взморье далекого мыса Тернистой долины.', 'Отнесите Нимбойе наполненный самоцвет Души. ', 'Победа! Ты освободил Йеннику от воли Занзила и выполнил задание, которое я считал безнадежным.$B$BНаше племя будет воспевать твое имя, Харо, и мы на каменных плитах напишем повесть о тебе, чтобы она никогда не забылась.', '$N. Кин\'вилай сказал, что послал тебя за Йеннику.$B$BЭто правда? Тебе удалось поймать его душу?', NULL, NULL, 'Наполненный самоцвет Души', 'Камень души', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (593, 'Наполнение самоцвета Души', '', '', 'Вы прикасаетесь к его лбу самоцветом Души. Он вздрагивает, когда волшебный предмет всасывает его разум, оставляя лишь тело, бездушную оболочку.', NULL, NULL, NULL, 'Камень души', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (594, 'Послание в бутылке', 'Записка написана красивым почерком. В ней значится:$B$BЛюбому, кто может мне помочь.$B$BПрошу тебя, не оставь меня в нужде. Великий Небогрив держит меня в плену на острове в Южных морях.$B$BПо ночам я смотрю на чужие звезды, полускрытые листвой деревьев, но в самую хорошую погоду на северо-западе я вижу Южное взморье и большие корабли на юго-западе.$B$BМолю тебя, мой будущий спаситель, помоги мне.', 'Отыщите автора послания в бутылке.', 'Ты явился, чтобы освободить меня?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (595, 'Пираты Кровавого Паруса', 'Ты не прочь подзаработать, а, $gприятель:подружка:? Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Разбойникам Черноводья, но не гнать же тебя в шею!$B$BМы только что бросили якорь в Пиратской Бухте, и уже прослышали, что наши соперники – гнусные, подлые пираты Кровавого Паруса – пустили корни в южной части Тернистой долины.$B$BВсе мои ребята слишком увлеклись грогом и девками! А мне нужен разведчик.$B$BОсмотри залив на севере от Пиратской Бухты рядом с Гибельным берегом и расскажи мне, что там творится.', 'Первый помощник Кразз попросил вас осмотреть залив на севере от Пиратской Бухты.', 'На крышке бочки лежит карта, на которой торопливо нацарапана пара слов, и несколько монет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (596, 'Ожерелье кровавых костей', 'Меня послали в Гром\'гол на помощь Нимбойе, но... У меня здесь свои дела.$B$BПлемя Кровавого Скальпа – наш заклятый враг. Трофеи, собранные с врагов, дают власть над ними. Ты можешь помочь нашему племени, открыв охоту на врага.$B$BПлемя Кровавого Скальпа живет на севере отсюда. Убей побольше троллей из этого племени и забери у них ожерелья кровавых костей. Собери как можно больше, и я награжу тебя.', 'Принесите Кин\'вилаю 25 ожерелий кровавых костей в лагерь Гром\'гол.', 'А, замечательно. Я сварю их, высосу из них силу и сотру в порошок, и дух наших врагов ослабеет!$B$BВот, $N. Возьми это в знак благодарности.', 'Когда-нибудь племя Черного Копья сокрушит Кровавый Скальп! Ты принес мне ожерелья наших врагов?', NULL, NULL, 'Ожерелье Кровавых костей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (597, 'Пираты Кровавого Паруса', 'На карте Пиратской Бухты нарисован красный крестик именно там, где вы стоите.$B$BНиже имеется подпись:$B$B\"Разбейте здесь лагерь и сидите тихо. Не нападайте, пока не получите сигнал с южного командного поста. Если заметите кого постороннего, сразу убивайте.\"', 'Отнесите находку первому помощнику Краззу в Пиратскую Бухту.', 'Конечно, я помню тебя, $C. Вижу, ты уже вернулся из разведки...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (598, 'Ожерелье расколотых костей', 'Раз ты $gпринес:принесла: трофеи от племени Кровавого Скальпа, у меня есть для тебя другое задание. На юго-востоке живет племя Дробителей Черепов, и мы воевали с ними много лет. Хотя племя Черного Копья давно не живет в Тернистой долине, мы не забыли раздоров с Дробителями Черепов.$B$BТак что начни на них охоту. Собери побольше ожерельев расколотых костей и принеси их мне. Помоги нам, и заслужишь признательность племени Черного Копья.', 'Принесите 25 ожерелий расколотых костей Кин\'вилаю в лагерь Гром\'гол.', 'Велика твоя сила, раз тебе удалось заполучить эти ожерелья, $N. Клан Дробителей Черепов пал под твоими ударами, как молодые ростки под тяжелыми шагами василиска!$B$BХвала твоим деяниям.', 'Клан Дробителей Черепов проклянет день, когда они выступили против нас! Ты справился с моим заданием?', NULL, NULL, 'Ожерелье расколотых костей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (599, 'Пираты Кровавого Паруса', 'Лопни моя селезенка! Значит, пираты Кровавого Паруса собираются напасть на Пиратскую Бухту? Вот наглость-то! Этот город испокон века был в руках Пиратов Черноводья!$B$BЗначит, дела обстоят хуже, чем я думал. Немедленно расскажи об этом командиру флота Морскому Рогу! Этот старый морской волк шатается где-то по городу...', 'Сообщите о запланированном нападении Кровавого Паруса командиру флота Морскому Рогу.', 'Пираты Кровавого Паруса собираются напасть на Пиратскую бухту? С тем же успехом они могут сразу сброситься с Отвесных скал. И все же ты оказал моему флоту большую услугу, передав мне эти сведения. Прими благодарность Разбойников Черноводья.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (600, 'Рудник Торговой Компании', 'Торговая Компания ведет операции в Тернистой долине, которые не дают трудолюбивым гоблинам вроде меня честно зарабатывать деньги! Пожалуйста, помоги мне!$B$BТорговая Компания обосновалась возле  Хрустальной шахты к северу отсюда. Внутрь они проникнуть не могут из-за злобных василисков, но все равно умудряются добывать Поющие кристаллы в ближайших холмах.$B$BОтбери у них эти кристаллы, показав тем самым, что джунгли им не принадлежат.$B$BИ.. э... принеси в доказательство сами кристаллы!', 'Принесите Шиззи Пуззыриксу из Пиратской Бухты 10 синих Поющих кристаллов.', 'Отлично! Чудесно! Я за них много выручу!!!$B$BТорговая Компания сунулась не в те джунгли, а? Нам всем станет лучше, если они уберутся отсюда, верно?$B$BСпасибо, $N. Ты сделал доброе дело.', 'Ты принес мне кристаллы?? Они мне нужны!!!$B$BТо есть... Мне нужно знать, что гнусную Торговую Компанию вскоре вытеснят из Тернистой долины. Потому что, э-э-э, нам, честным предпринимателям, надо зарабатывать на хлеб насущный!', NULL, NULL, 'Синий поющий кристалл', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (601, 'Элементали воды', 'Элементалей воды, несомненно, призвал Газбан, гоблин-волшебник, который нашел Камень Приливов, если верить слухам. Мы знаем, что на владельца камня накладывается проклятие, которое то стирает его из реальности, то возвращает обратно в наш мир...$B$BБыть может, нам удастся снять проклятье. Один даларанский маг может исследовать следы магии на браслетах элементалей. Отправляйся на остров и принеси несколько штук.', 'Принесите барону Ревилгазу в Пиратскую Бухту 6 браслетов элементалей воды.', 'Я не могу определить навскидку, какие из этих браслетов подойдут, но хотя бы один должен сгодиться. Отнеси их в Даларан, пусть на них посмотрит маг.$B$BНе могу же я, в самом деле, уехать из Пиратской бухты ради какого-то старого мага?$B$BНе то, чтобы я беспокоился, что кто-то попытается занять мое место и стать новым бароном. Никто не посмеет встать на пути у Ревилгаза.', 'Как дела, $N?', NULL, NULL, 'Браслеты элементаля воды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (602, 'Магический анализ', 'Насколько я знаю, магам Даларана удалось восстановить свой разрушенный город и перенести его в небо над Нордсколом, оставив позади гигантский кратер. Но некоторые маги остались здесь, и один из них обязательно найдет время посмотреть на браслеты. Насколько я знаю магов, они не устоят перед возможностью разгадать запутанную магическую головоломку.$B$BВозьми сумку с браслетами элементалей воды и узнай, не прольют ли они свет на проклятие Камня. Лучше всего обратиться к верховному магу Ансарему Руноплету. Я уже имел с ним дело, и его знания велики.', 'Отнесите браслеты элементалей воды верховному магу Ансарему Руноплету в Даларан.', 'Камень Приливов? Очень интересно. Быть может, вас это удивит – несколько лет назад я написал книгу, посвященную легендам империи Гурубаши. Я знаю об этом камне довольно много.$B$BПо крайней мере, на одном из этих браслетов я вижу остатки магии, которые явно поддаются анализу.$B$BПосмотрим...', 'Простите, но сейчас я очень занят.', NULL, NULL, 'Сумка с браслетами элементалей воды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (603, 'Ключ Ансарема', 'Маг, который владеет Камнем, может умножить его силу при помощи некой точки фокуса... вроде алтаря. Чтобы не допустить этого, необходим предмет равной силы.$B$BКак ни странно, я знаю одну очень подходящую вещь: древний кинжал, еще одну из тролльских реликвий. Только есть... небольшая проблема.$B$BЯ нашел этот кинжал, странствуя по Тернистой долине, и отдал его своей своевольной дочери, которая сбежала в Пиратскую Бухту и стала пираткой.', 'Поговорите с Кателиной в Пиратской Бухте.', 'Мой кинжал? Ты издеваешься?$B$BТы хочешь услышать, как я превратилась из лучшего бойца на ножах в Пиратской бухте в посмешище для всех пиратов?$B$BЯ проиграла схватку с одним из пиратов Кровавого Паруса – они редкие мерзавцы! – и он забрал мой кинжал в качестве трофея.$B$BОдним острым языком славу бойца не поддержишь...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (604, 'Пираты Кровавого Паруса', 'Кразз высоко ценит твою преданность Разбойникам Черноводья. Я доверяю тебе задание, очень важное для нашего флота.$B$BПроникни на так называемый южный командный пост, который пираты Кровавого Паруса основали на Диком взморье. Разграбь весь лагерь и принеси мне их карты и записи приказов. Так мы выясним, что замышляют эти ублюдки.', 'Командир флота Морской Рог из Пиратской Бухты попросил вас убить 10 сорвиголов из шайки Кровавого Паруса и принести ему карты и приказы Кровавого Паруса.', 'Отлично, $N. Теперь, когда их планы нам известны, это лишь вопрос времени.$B$BПодумать только, эти глупцы бросили якорь недалеко от мыса.', 'Эгей, $N. Какие вести ты несешь из южного лагеря Кровавого Паруса?', NULL, NULL, 'Сорвиголова из шайки Кровавого Паруса убито', 'Карты пиратов Кровавого паруса', 'Приказы пиратов Кровавого паруса', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (605, 'Осколки Поющих кристаллов', 'Поющие кристаллы добывают только в Тернистой долине, и некоторые покупатели готовы немало за них отсыпать. Кому их толкнуть, мне ясно, но проклятая Торговая Компания не дает собирать кристаллы честным предпринимателям вроде меня.$B$BЯ хочу тебя нанять.$B$BВасилиски Тернистой долины питаются этими кристаллами. Благодаря им у них прочная шкура, и иногда из нее можно добыть качественные кристаллы.$B$BГодится шкура любого василиска, но на северном побережье, южнее Зул\'Кунды, они не такие свирепые.', 'Принесите Шиззи Пуззыриксу 10 осколков Поющих кристаллов.', 'Ага! Отличные осколки, $N. То, что надо!$B$BВот твоя доля, и... с тобой приятно иметь дело.', 'Удалось добыть осколки? Процент с выручки получишь!', NULL, NULL, 'Осколок поющего кристалла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (606, 'Напугать Трусишку', 'Вот кого я терпеть не могу, так это тех, кто не отдает карточные долги! Мне задолжали несколько партнеров по игре. Не поможешь собрать с них мзду?$B$BВо-первых, есть Филипп \"Трусишка\", который вечно торчит у причала. Он проиграл мне кругленькую сумму на прошлой неделе, и я хочу ее получить! Только для этого надо его хорошенько припугнуть.$B$BСтупай, поохоться на старых горилл из Мглистой долины. Набери из них потрохов и отнеси Трусишке. Только не говори, что они обезьяньи, пусть в штаны со страху наложит!', 'См. «Напугать Трусишку». Отнесите 5 потрохов горилл из Мглистой долины Филиппу \"Трусишке\"  в Пиратскую Бухту.', 'Ох! Откуда у вас это? Нет, не говорите. Я не хочу знать!$B$BКто вас прислал? Морской волк?', 'Эй, мне не нравится, как вы на меня смотрите, сударь.', NULL, NULL, 'Потроха гориллы из Мглистой долины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (607, 'Возвращение к Маккинли', 'Вот, возьмите этот кошель и отнесите его Морскому Волку. И передайте, что я собирался ему заплатить! Клянусь!!!$B$BЯ всего лишь немного перебрал и заблудился по пути, и... знаете, как бывает. Он поймет – не нужно применять силу!', 'Отнесите плату Трусишки \"Морскому волку\" Маккинли. ', 'Хе-хе, отличная работа! И как, сильно Трусишка перетрусил, когда ты показал ему потроха?$B$BХа! Я читаю его как раскрытую книгу! Играя с ним в карты, нельзя не выиграть!$B$BСпасибо за помощь, $N. Пришел твой черед получить плату...', 'Ладно, $N. Где долг Трусишки?', NULL, NULL, 'Плата Трусишки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (608, 'Пираты Кровавого Паруса', 'Ну и наглец этот Фираллон! Он бы и озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот!$B$BПираты Кровавого Паруса поплатятся за свою беспечность. Теперь мы знаем все их планы и нападем первыми.$B$BХотя зачем посылать целый флот, если хватит отряда отважных искателей приключений? $N, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров. Весь флот отправится на дно следом за ними...', 'Командир флота Морской Рог из Пиратской Бухты попросил вас убить капитана Штиллеца, капитана Кильвателя и командира флота Фираллона.', 'Ах, что за великий день для Разбойников Черноводья! Трижды ура тебе, $N!', NULL, NULL, NULL, 'Капитан Штиллец убито', 'Капитан Кильватель убито', 'Командир флота Фираллон убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (609, 'Должники вуду', 'Список сокращается, но должники все еще остались.$B$BДалее идут Моури \"Деревянная Нога\" Вилкинс, Джон-Джон Ворон и Чаки \"Недотепа\".$B$BЭти паршивые собаки просрочили платежи на много месяцев, я-то думал, они поэтому из города сбежали! Потом, правда, мне сказали, что их прокляли и заколдовали, и они бродят по развалинам в джунглях. Но меня их судьба не волнует – мне бы свое вернуть!$B$BИх видели на северо-востоке отсюда, в руинах Абораза и руинах Жубуваля. Отыщи их и забери у них мои вещи.', 'Принесите деревянную ногу Моури, золотую подзорную трубу Джон-Джона и огромное кольцо Чаки \"Морскому волку\" Маккинли в Пиратскую Бухту.', 'Отлично! За это я выручу кругленькую сумму, особенно за то, что спрятано внутри ноги Моури! Спасибо, $N!$B$BНадеюсь, эти трое усвоили урок: никогда не ставь на кон то, что не можешь отдать.$B$BМожет быть, они поняли это слишком поздно... Но надо было думать, с кем садишься играть.', 'Ну что, нашел этих трех зараз? Забрал у них ценности?', NULL, NULL, 'Деревянная нога Моури', 'Золотая подзорная труба Джон-Джона', 'Огромное кольцо Чаки', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (610, '\"Красавчик\" Дункан', 'Так тебя прислал мой ОТЕЦ? Я думала, старик давно махнул на меня рукой.$B$BЭто он виноват, что я сбежала. С чего он взял, что я только и мечтаю о скучной жизни среди заплесневелых книг и седых, горбатых и надутых магов!$B$BЕсли тебе нужен мой кинжал, можешь отобрать его у \"Красавчика\" Дункана, одного из пиратов Кровавого Паруса. Я думаю, что почуствовав металл между лопаток, Дункан охотно расстанется с кинжалом.', 'Отберите кинжал Кателины у \"Красавчика\" Дункана. ', 'Тебе удалось одолеть Дункана? Значит, ты не совсем салага, как кажется с первого взгляда.$B$BПожалуй, это означает и то, что мне не стоит в ближайшее время вызывать тебя на бой!', 'Ты знаешь, что меня раньше никто не побеждал? Да, бывало, ранили, без этого ни одна поножовщина не обходится, но он долбанул меня по голове, я и отключилась. Пришла в себя – а кинжала нет.$B$BПо моему прозвищу легко понять, что без кинжала мне не жизнь, и мне нужен именно этот кинжал.', NULL, NULL, 'Кинжал Кателины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (611, 'Проклятье приливов', 'Значит, ты ищешь какой-то алтарь? Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты $gспрашивал:спрашивала:. Посмотри там.$B$BТы $gвернул:вернула: мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!', 'Уничтожьте Алтарь Приливов при помощи меча Кателины, убейте Газбана и принесите Камень Приливов и меч Кателины барону Ревилгазу.', 'Поразительно! Камень Приливов! Он займет достойное место в моей коллекции древних артефактов троллей. Видишь, создается впечатление, что это и есть окаменевший прилив? Великолепно!', 'Тебе удалось добыть для меня Камень Приливов, $N? Я уже приготовил для него место и купил красивую подставку.', NULL, NULL, 'Камень приливов', 'Кинжал Кателины (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (613, 'Вскрыть ногу Моури', 'Проклятье! Этот Моури поставил на свою ногу замок, и я не могу ее открыть! Его сокровища внутри, и именно их он мне должен!$B$BМне необходим ключ, чтобы вскрыть этот замок. Мори нередко играл в кости с ограми Мош\'Огг у них на холме на северо-востоке. Он успел рассказать мне, что ему пришлось спасаться бегством после прошлой игры, потому что больно много выиграл. Может быть, его ключ у огров.$B$BНо если так, придется убить целую толпу, чтобы его отыскать...', 'Принесите \"Морскому Волку\" Маккинли из Пиратской Бухты ключ Моури.', 'Ты нашел его! Тысяча благодарностей. Ты мне так помог!$B$BВот, возьми – ты заработал это сполна!', 'Эгей, $N! Нашел ключ Моури?', NULL, NULL, 'Ключ Моури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (614, 'Сундук капитана', 'Когда-то у меня был корабль, на котором я плавал до самого Кабестана в Калимдоре, и репутация у меня была безупречная.$B$BПока…$B$BПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую Бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!$B$BГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.', 'Верните Гекельберри Смоттсу из Пиратской Бухты его сундук.', '', NULL, NULL, NULL, 'Сундук Смоттса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (615, 'Капитанская сабля', 'После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его \"Месть Шмотта\", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова надавали мне по шее. \"Месть Шмотта\" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.$B$BУ другого великана, Неголаша, моя сабля.$B$BСразись с Неголашем и принеси мне мою саблю!$B$BМожешь поговорить со Салагой, поваром с \"Мести Шмотта\", который выжил в последней битве. Он поможет тебе найти великана.', 'Поговорите с Салагой.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (616, 'Остров духов', 'Барон Ревилгаз велел мне не упускать слухов о странных событиях и местах в округе Пиратской Бухты и всей Тернистой долины. Обычно я не придаю большого значения историям про призраков и прочую чушь, но моряки в таверне говорили об острове элементалей недалеко от побережья. Мол, там духи Воды и сумасшедший призрак гоблина.$B$BЕсли тебе встретится Ревилгаз, перескажешь ему эту историю?', 'Поговорите с бароном Ревилгазом в Пиратской Бухте. ', 'Интересно. Кажется, я недавно читал книгу, в которой говорилось о чем-то в этом духе…$B$BА, разумеется, легенды троллей. Если Кразек говорит правду, то вскоре к моей коллекции древних артефактов и реликвий добавится Камень Приливов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (617, 'Вязанка акириса', 'Ищешь работу, $N? Если ты не боишься трудностей, могу тебе предложить одно дельце.$B$BУ меня есть дружбан, Гроу, который зашибает бешеные деньги, продавая то, что наги называют стеблями акириса. Это очень ценная морская водоросль. Он за нее отлично платит.$B$BПритащи мне 10 стеблей этой травки, и мы сторгуемся. Наги живут на берегу к северу отсюда.', 'Принесите каперу Блоудсу из Пиратской Бухты 10 свертков со стеблями акириса.', 'Молодец, $N. Не так уж трудно было добыть 10 стеблей акириса, а? Я вполне сочувствую нагам, но каждый как-то должен зарабатывать на жизнь.', 'Если ты не по делу, вали отсюда, $N.', NULL, NULL, 'Стебли акириса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (618, 'Бой с Неголашем', 'Неголаш – великан-обжора.$B$BКогда они уничтожили мой корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!$B$BЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!', 'Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Шмотта.Убейте Неголаша и отнесите абордажную саблю Шмотта хозяину в Тернистую долину.', '', NULL, NULL, NULL, 'Абордажная сабля Смоттса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (619, 'Приманка для Неголаша', '', '', 'Вы нагружаете лодку едой и выпивкой...', NULL, NULL, NULL, 'Жареное крылышко канюка', 'Экзотическое вино', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (620, 'Кушак с монограммой', 'Вдоль каймы кушака вышита монограмма \"ГС\".', 'Верните кушак с монограммой владельцу.', '', NULL, NULL, NULL, 'Кушак с монограммой (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (621, 'Тайна Занзила', 'Занзил Отверженный и его приспешники живут в руинах Жубуваля и Абораза, на северо-востоке от Пиратской бухты. Его изгнали из племени. Почему? Ну...$B$BЗанзил научился подчинять себе разум других, и его страшатся собственные командиры. Он заставляет своих приспешников принимать смесь из тропических растений, которые подавляют их волю и укрепляют тела.$B$BЭта смесь пригодилась бы и другим, желающим подчинить себе других.$B$BПринеси мне образцы этой смеси, я найду им применение.', 'Принесите Шиззи Пуззыриксу из Пиратской Бухты 12 образцов смеси Занзила.', 'А, отлично! Вот твоя плата.$B$BИ еще немного сверх... за молчание.', 'Ты принес мне образцы смеси Занзила?', NULL, NULL, 'Смесь Занзила', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (622, 'Возвращение к капралу Калебу', 'Пока тебя не было, я починил твой горшок и даже приделал к нему свисток. Больше того, смотри! На дне появился новый нож, который запросто рубит кости!$B$BДа-да, теперь этот горшок – настоящая радость повара! Не сомневаюсь, владелец будет доволен.', 'Отнесите целый горшок Крейвела капралу Калебу в Лагерь повстанцев.', 'Готово! Чудесно, я могу готовить обед! Большое спасибо, $N.$B$BНадеюсь, в Пиратской бухте с тобой ничего не случилось. Там всякое бывает... Говорят, иногда гоблины утаскивают пьяных моряков на галеры, приковывают цепями и увозят неизвестно куда...', 'Привет, $N. Добрался до Пиратской бухты без приключений? Починил ли гоблин Кразек мой горшок??', NULL, NULL, 'Целый горшок Кразека (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (623, 'Вязанка акириса', '$N, раз уж ты здесь, я тебе вот что скажу. Пока тебя не было, я получил послание от Гроу. Его очень порадовала последняя поставка, и клиент немедленно захотел получить еще акириса.$B$BЯ собираюсь в Терамор не раньше, чем через неделю, но если ты не против двинуть в путь прямо сейчас, почему бы тебе не отвезти товар?$B$BХочешь поприключаться? Ты знаешь, где находятся Пылевые топи? Только будь $gосторожен:осторожна:, в Тераморе может быть опасно.', 'Принесите сверток со стеблями акириса каперу Грою в Терамор.', 'Что?! Мне некогда с тобой трепаться, $C. Если ты собираешься попусту тратить мое время, лучше сразу убирайся.$B$BЧто? Тебя прислал Блоудс, да?$B$B*Капер Грой внимательно рассматривает сверток.*$B$BНеплохо, неплохо. Еще один сверток – и клиент будет счастлив.$B$BДумаю, следующий вопрос будет про деньги, а? Ну разумеется!$B$BВот, бери монеты и совет в придачу: убирайся-ка подобру-поздорову.', 'А?', NULL, NULL, 'Сверток со стеблями акириса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (624, 'Загадка Кортелло', 'Есть мост, изукрашен резьбою, красивый на нем узор$BК востоку от Мертвого Ветра и к югу от Красногорья$BПод ним тебя ждет подсказка ль, улика ль – как назовешь.$BИ будет на Болоте Печали лежать, пока не найдешь.', 'Разгадай загадку! ', 'Намокший пергамент дает вам новую подсказку...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (625, 'Загадка Кортелло', 'Калимдор далекий ждет тебя давно,$BГде надеждам к сроку сбыться не дано.$BТы в Степях почуешь вкус пыли на губах,$BНу а в топях пылевых – лишь печаль и страх.$BНо на юго-запад путь тебя манит,$BМрак пещеры тайну для тебя хранит.', 'Разгадай загадку!', 'Вы находите заплесневелый свиток.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (626, 'Загадка Кортелло', 'Спеши же в славный Лордерон! Давно тебя он ждет.$BТам с мором, гибелью и тьмой сражается народ. $BПусть не страшит тебя война и битвы шум и гам – $BЗато задание свое исполнить сможешь там. $BВот берег Внутренних земель, где шумный водопад, $BТам, под водами его, тебя ждет дивный клад!', 'Разгадай загадку! ', 'Вы открываете сундук и обнаруживаете...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (627, 'Просьба Кразека', 'В Теснине Сухоусов - далеко на севере, в нагорье Арати - есть пещера. Там добывают редкие полезные ископаемые – кровавые камни. Да, они там не лучшего качества, но даже самые плохие кровавые камни высоко ценятся... теми, кто знает что с ними делать.$B$BЯ – знаю.$B$BЯ починю твой разбитый горшок, но пока я работаю над ним, принеси мне образцы кровавого камня. Если ты принесешь их достаточно, я награжу тебя.$B$BАх, да, если ты не умеешь добывать полезные ископаемые... попроси кого-нибудь помочь тебе!', 'Принесите 4 партии бедной кровавой руды Кразеку в Пиратскую Бухту.', 'А, великолепно! Ты оказал мне большую услугу.$B$BВот твоя плата...', 'Привет, $N. Удалось добыть кровавые камни?', NULL, NULL, 'Бедная кровавая руда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (628, 'Эксельзиор', 'Подбой готов, осталось сделать верхний слой. На него идут только наилучшие шкуры взрослых кроколисков. Они крепче и представляют собой лучшую основу для узоров, которыми славится линия превосходных сапог.$B$BХотя найти эту ценную шкуру нелегко, мне подходит лишь шкура старого солоноводного кроколиска. Эти твари выходят лишь на защиту молоди, поэтому может понадобиться убить несколько молодых зверей, чтобы выманить нужного.', 'Принесите Дриззлику из Пиратской Бухты шкуру старого солоноводного кроколиска.', 'Здорово! Благодаря твоей помощи я выполню этот заказ и отправлю его директору Ридлвоксу на следующем корабле в Нижнюю шахту. Быстрее, чем обещал!$B$BЯ сделал лишнюю пару, возьми ее за работу. Все за счет Дриззлика.$B$BИ помни, если нужны тебе сапоги, к Дриззлику ты поскорей прибеги!', 'Я где-то читал, что солоноводные кроколиски постепенно вымирают... это повредит моему делу, а?$B$BВпрочем, надеюсь, ты добыл мне шкуру старого солоноводного кроколиска!', NULL, NULL, 'Шкура старого кроколиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (629, 'Коварный риф', 'Давным-давно вода затопила древний город троллей рядом с Гибельным берегом, что на северо-западе. Мы зовем это место Коварным рифом, потому что в развалинах поселились мурлоки, которые нападают на всех, кто осмелится приблизиться.$B$BСреди руин есть древняя табличка, повествующая о древнем герое троллей, Гри\'леке. Это сказание священно в племени Черного Копья, и хотя сама табличка слишком велика и ее не унесешь, я хочу получить хотя бы осколок, чтобы поместить его в святилище в нашем новом городе, Оргриммаре.', 'Принесите осколок таблички Кин\'вилаю в лагерь Гром\'гол. ', 'Хорошо. Когда я вернусь в Оргриммар, этот осколок будет помещен в священное место. Он будет напоминать нам о силе и чести Гри\'лека.$B$BСпасибо, $N. Твои деяния говорят о крепнущей дружбе с племенем Черного Копья.', 'Я жду, когда ты принесешь мне осколок таблички, $N.', NULL, NULL, 'Обломок таблички', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (630, 'Послание в бутылке', '$N, ты и те, кого ты сможешь позвать мне на помощь – моя последняя надежда. Меня держит в плену великий Король Мукла. Он повелевает зверями на этом острове, и они держат меня здесь помимо моей воли на этой цепи. Если ты сможешь убить моего мучителя и отыскать ключ к кандалам, я буду навеки у тебя в долгу.$B$BЯ часто слышу шаги Короля Муклы на юго-восточной стороне острова. Соблюдай осторожность, справиться с ним нелегко.', 'Убейте Короля Муклу, возвращайтесь с ключом к принцессе Пубе и освободите ее.', 'Ты спас меня от великого бесчестья, $N. Будь это в моей власти, я приняла бы тебя в свое племя. Пока же я могу лишь вручить тебе этот залог моей благодарности за проявленное мужество и благородство.', 'Хвала предкам, кто-то пришел мне на помощь. Ты несешь мне ключ, а вместе с ним и свободу?', NULL, NULL, 'Ключ от кандалов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (631, 'Мост Тандола', 'Я помню, как горы содрогнулись от ужаснейшего взрыва. Не слабо рвануло, скажу я тебе!$B$BНа мосту Тандола погибли лучшие из наших солдат. Длинная Коса говорит, что дворфы Черного Железа еще заплатят нам за все до конца этой войны.$B$BНо сейчас у нас отчаянное положение, подкрепления все нет и нет. Длинная Коса отправил Ржавого Засова на разведку к восточному мосту – посмотреть, можно ли защитить мост теми силами, которые сейчас у нас есть.$B$BПрошло уже несколько дней. Мы не можем отправить солдат на поиски – Дун Модр осажден...$B$BБыть может, ты согласишься поискать нашего разведчика?', 'Найдите Ржавого Засова для Рага Гармасона.', 'Вы натыкаетесь на труп дворфа. На шлеме отчетливо видна надпись: \"Эбенезер Ржавый Засов\".', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (632, 'Мост Тандола', 'Кажется, бедняга Ржавый Засов попал в засаду дворфов Черного Железа. Возле его остывшего тела лежит клочок пергамента.$B$BРасскажите Рагу Гармасону о случившемся и передайте ему пергамент.', 'Принесите печальное известие Рагу Гармасону в Дун Модр в Болотину и отдайте ему пергамент, найденный возле трупа Ржавого Засова.', 'Какой ужас... Бедный, бедный Эбенезер.', 'Есть новости о Ржавом Засове, $N?', NULL, NULL, 'Приказы Кама Гневливого (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (633, 'Мост Тандола', 'Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня $gопечалил:опечалила:, $N.$B$BНо его жертва будет не напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с нагорьем Арати.$B$BЕсли ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай все возможное, чтобы спасти мост Тандола, и возвращайся ко мне.$B$BТы – наша единственная надежда.', 'Уничтожьте взрывчатку.', 'Мост спасен! Ты помог не только мне и королю Магни, но и всему народу Каз Модана!$B$BТеперь нужно продержаться до прибытия подкрепления...', 'Умоляю, избавься от проклятой взрывчатки, пока не поздно!', NULL, NULL, 'Взрывчатка уничтожена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (634, 'Просьба о помощи', 'Я попрошу тебя о еще одном одолжении, $C. Мы ожидаем подкрепление из Стальгорна. Рогго принес сведения о лагере воинов Альянса к северу отсюда. Они расположились на нагорье Арати, возле Опорного пункта.$B$BОтправься туда и отыщи капитана Ниалс. Спроси у капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола.', 'Найдите капитана Ниалс в Опорном пункте на нагорье Арати.', 'Передай мои соболезнования Длинной Косе и его солдатам. Я искренне опечален вестью о трагедии на мосту Тандола и падении Дун Модра...$B$BНо знайте, что и Стромгард пал! Именно поэтому мы сейчас стоим у Опорного пункта. Впереди – битва за наш великий город.$B$BДолг и честь не позволяют мне покинуть нагорье до тех пор, пока над Стромгардом не взовьется гордое знамя нашего короля! Придется Длинной Косе обходиться своими силами...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (635, 'Горный кристалл', 'Осколок пульсирует у вас в руках…$B$BВам кажется, что он молит о чем-то, пытается передать послание того, кто нуждается в вашей помощи.$B$BВам является видение – в северных горах Арати из земли торчит сияющий кристалл.$B$BВас так и тянет к этому месту.', 'Найдите кристалл из видения.', 'Кристалл пульсирует, будто в него заключена живая сила.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (636, 'Legends of the Earth $gNYI:', 'В книге изложена история принцессы элементалей Мизраэль и ее заточения глубоко под нагорьем Арати. Эти камни, кристаллы Мизраэль, являются окном в темницу принцессы.$B$BВероятно, тот, кто отважится отыскать эти кристаллы, сможет поговорить с ней...', 'Найдите кристаллы Мизраэль.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (637, 'Письмо Салли Балу', 'Промокший и потрепанный конверт разваливается в руках, и в ладонях остается письмо на нескольких страницах. Каждая буковка выведена с удивительной аккуратностью.$B$BПисьмо адресовано некой миссис Саре Баллу из Стальгорна. Оно начинается: \"Дорогая Сара...\"', 'Отнесите письмо Салли Баллу Саре Баллу.', 'Неужели ты видел моего Салли подо льдом? Прошу, скажи, что это не так!$B$BДай-ка я прочитаю, что он написал...', 'Похоже, на твою долю выпало немало странствий и нелегких битв, $C. Да, лихие настали времена. Что нового творится в мире?', NULL, NULL, 'Письмо Салли Балу (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (638, 'Троллебой', 'Торас Троллебой мертв, а Стромгард разрушен. Вол\'джин велел мне приложить все усилия, чтобы вырвать легендарный меч Трол\'калар из рук людей. Тогда мы сможем воспользоваться им в грядущих битвах с троллями Зул\'Гуруба.$B$BЗенгу, один из наших опытных охотников, отправился в Павший Молот в северо-восточной части нагорья Арати, чтобы проследить за этим.', 'Отправляйтесь в Павший Молот и поговорите с Зенгу. ', 'Как дела, $C? Вол\'джин дал нам непростое задание, и если ты хочешь предложить свою помощь, мы с радостью ее примем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (639, 'Печать Cтрома', 'В древние времена тролли воевали с Араторской империей и нашим самым могучим противником, лордом Игнеусом Стромским по прозвищу Троллебой. Он бросался в бой с мечом Трол\'каларом в руке – \"убийцей троллей\", на их древнем наречии.$B$BНо теперь сыновья Троллебоя ослабели, а цитадель их разрушена.$B$BМеч защищен несколькими печатями, которые были распределены между выжившими защитниками Стромгарда, и мы должны их отыскать.$B$BПервую из печатей захватил Синдикат, должно быть, она находится у одного из их людей в Стромгарде.', 'Добудьте печать Строма для Зенгу в Павшем Молоте. ', 'Отлично, дружище. Это хорошее начало для сбора всех печатей, которые нам понадобятся, чтобы извлечь Трол\'калар из могилы Троллебоя.', 'Вы еще не выяснили местонахождение первой печати? Скорее всего, она находится у кого-то из посланников Синдиката в Стромгарде.', NULL, NULL, 'Печать Строма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (640, 'Сломанная печать', 'Могила Тораса Троллебоя защищена тремя печатями, первую из которых тебе уже удалось раздобыть у Синдиката. Остальные две достать будет сложнее, поскольку ими владеет гораздо более сильное ополчение Стромгарда.$B$BПечать Торадина была разделена на одиннадцать частей сыном Тораса Галеном, а потом он распределил эти фрагменты между стромгардскими защитниками Собери фрагменты и принеси их Тор\'гану, троллю-шаману, – он сможет восстановить целостность печати.', 'Добудьте у защитников Стромгарда 5 фрагментов печати, принесите их Тор\'гану в Павший Молот.', 'А, так вам нужно воссоздать печать! Это будет не слишком сложно... все фрагменты на месте, а магическую структуру будет легко преобразовать.$B$BПожалуй, вам бы лучше закрыть глаза.', 'Тром\'ка, $C. Зенгу сообщил, что вам нужна моя помощь.', NULL, NULL, 'Фрагмент печати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (641, 'Печать Торадина', 'Восстановление прошло без сучка и задоринки. Теперь печать можно использовать, чтобы отпереть могилу Троллебоя. Верните печать Зенгу. Несомненно, у него найдутся еще для вас задания.', 'Принесите восстановленную печать Торадина Зенгу в Павший Молот.', 'Мы на полпути к тому, чтобы извлечь Трол\'калар из могилы Троллебоя. Мы не вполне уверены в том, где находится третья печать, поскольку владеющие ею, похоже, много передвигаются по нагорью Арати. Но я верю, что вам удастся ее отыскать.', '$N! У вас есть вторая печать?', NULL, NULL, 'Печать Торадина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (642, 'Пойманная принцесса', 'Меня зовут Мизраэль. Я принцесса духов земли, и мои пленители – гиганты – поймали меня в ловушку глубоко под нагорьем Арати. С миром на поверхности я могу говорить только при помощи этих кристаллов.$B$BПожалуйста, помоги мне. У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в теснине Сухоусов, к востоку отсюда. Чтобы объединить их силу, нужно отобрать у кобольдов крупицы мощи Мизраэль.$B$BПрошу тебя, $N, помоги мне!', 'Соберите 12 крупиц мощи Мизраэль и принесите их к радужным осколкам в Теснине Сухоусов.', 'Ах, тебе удалось активировать те кристаллы. Я уже чувствую, что начинаю приходить в себя!$B$BНо, увы, до свободы еще далеко...', 'Эта группа кристаллов выглядит очень похожей на кристаллы Мизраэли. Однако они не излучают такое же чувство надежности и безопасности.', NULL, NULL, 'Мощь Мизраэль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (643, 'Печать Аратора', 'Хотя принц едва ли может похвастаться властью над Стромгардом, не говоря уж обо всем нагорье Арати, тем не менее он разъезжает с остатками своей кавалерии по всей области. Я не могу сказать, зачем он это делает, но кто поймет, как мыслят эти люди?$B$BКакова бы ни была причина, более важно то, что он отдал одну из своих печатей лейтенанту Храброзову, командиру кавалерии. Найдите его и принесите мне эту печать.', 'Добудьте печать Аратора и принесите ее Зенгу в Павший Молот.', 'Потеря командира кавалерийского отряда станет серьезным ударом для стромгардских защитников. К тому же – что еще лучше – это значит, что нам осталось найти лишь одну печать, чтобы заполучить себе Трол\'калар.', 'Храброзова будет нелегко выследить, $N. Верхом он может перемещаться очень быстро. Тем не менее эта печать нам необходима.', NULL, NULL, 'Печать Аратора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (644, 'Печать Троллебоя', 'Последняя из печатей, необходимых, чтобы отпереть могилу Тораса Троллебоя, хранится у его сына. Он обитает в Стромгарде, в часовне, в том районе, что контролируется ополчением. У принца Галена хорошая охрана, да и сам он боец не промах, так что это задание может оказаться наиболее сложным.', 'Убейте принца Галена Троллебоя и принесите печать Троллебоя Зенгу в Павший Молот.', 'Удачный денек, $C. Кровь рода Троллебоев больше не будет беспокоить мой народ, и печати, необходимые для извлечения Трол\'калара, теперь у нас в руках. Скоро, очень скоро мы ударим по ненавистным троллям Зул\'Гуруба.', 'Вы вернулись, $N. Прерван ли род Игнеуса Троллебоя?', NULL, NULL, 'Печать Троллебоя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (645, 'Трол\'калар', 'Что это? Когда четыре печати оказались вместе, они соединились, образовав единую печать. Нет сомнений, что она сможет разбить охранные заклинания, наложенные на могилу Троллебоя.$B$BОстанки Троллебоя захоронены в святилище позади часовни в Стромгарде. Принесите же Трол\'калар.', 'Достаньте Трол\'калар из могилы Троллебоя в Стромгарде.', 'При совмещении линий на верхней стороне могилы Троллебоя с сияющими линиями печати Игнеуса вспышка света поглощает печать, и легендарный меч Трол\'калар освобождается из каменных объятий.', 'Углубления в камне на верхней стороне надгробия Троллебоя совпадают с сияющими линиями печати Игнеуса...', NULL, NULL, 'Печать Игнеуса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (646, 'Трол\'калар', 'Медленно угасает свет. Меч Трол\'калар, упрятанный в каменные ножны, освобожден.', 'Отнесите меч Трол\'калар Зенгу в Павший Молот. ', 'Поколениями силы Штрома и Аратора истребляли троллей. Теперь их величайшее оружие – в наших руках. Больше мы не будем топтаться на месте во влажных лесах Зул\'Гуруба.$B$BВы оказали нам серьезную помощь, $N, и тролли Черного Копья в долгу перед вами.$B$BЯ позабочусь о том, чтобы меч был доставлен Нимбойе в Гром\'гол.', '$N! Вам удалось забрать меч?', NULL, NULL, 'Убранный в ножны Трол\'калар (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (647, 'Самогон Маккрила', 'Ох, и хлебнул я вчера самогона! Узнай Длиннокос, что я отрубился на посту, он оторвал бы мне голову.$B$BБашка раскалывается, жуть. И в ушах гремит, будто осадные машины вокруг грохочут.$B$BОй-ой, а времени сколько! Я обещал мастеру-пивовару Бочкопузу из Южнобережья вернуть должок своим самогоном.$B$BА осталось до истечения срока действия долга всего 15 минут! Отнеси ему самогон, будь другом! И поскорее!', 'Отнесите самогон Маккрила мастеру-пивовару Бочкопузу в Южнобережье. ', 'Ах, ничто не греет так, как глоток самогона Туманника Маккрила! А я-то думал, что этот паразит опять просрочит платеж. Спасибо, дружище! Огромное тебе спасибо!', 'Что хорошего скажешь, $C?', NULL, NULL, 'Самогон Маккрила (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (648, 'Спасти КПХ-17:TN!', 'Из динамика снова слышится искаженный помехами голос гнома:$B$B\"Мне необходимо перегнать КПХ-17:TN в просторное и безопасное место, чтобы провести длительную процедуру наладки. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, к Пещерам Времени! Это самое подходящее место, и там достаточно просторно, чтобы подготовить аппарат к новому полету.$B$BПроводите робота в порт, а затем сообщите об этом мне. Я живу в Пиратской Бухте, меня зовут Карлс Пропеллерз. Конец связи!\"', 'Сопроводите КПХ-17:TN в безопасное место, затем сообщите об этом Карлсу Пропеллерзу в Пиратской Бухте.', 'А, так это вы великий спаситель КПХ-17:TN! У меня просто слов нет, настолько я вам благодарен! Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок!$B$BПрошу вас, выбирайте любую из этих готовых моделей. Еще раз спасибо вам, $N! Мы с моими роботами – ваши должники!', NULL, NULL, NULL, 'Проводить КПХ-17/TN в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (649, 'За медовухой', 'Хочу я поручить тебе одно дельце. Если ты любишь добрую медовуху, как и я, оно тебе понравится. Медовуха!$B$BЭто напиток, балда!$B$BНа заброшенной заставе Орды хранится запас \"Медовой зыби\" Внутренних земель. Такого славного пойла нынче больше не делают! Один из этих балбесов, дружков Мальтона, знает туда дорогу. Сходи к нему, принеси бочонок медовухи и еще пару бутылок мне лично. Поговори с Мальтоном, он тебе все расскажет.', 'Поговорите с Мальтоном Дрофферсом в Оргриммаре. ', 'А, это насчет медовухи, которая нужна папаше? Он собирается торговать ею в таверне. За настоящую \"Медовую зыбь\" можно выручить много денег... Я знаю того, кто может ее добыть. Он живет во Внутренних землях. Но вот какая штука: он того... эльф он. Высший.$B$BНо ты не бойся, он хороший высший эльф, он не из Альянса. То есть он хороший, как выпьет. А это дело он любит. Очень любит.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (650, 'За медовухой', 'Отправляйся к эльфу по имени Гилверадин Ловчий Солнца. Он так разбирается в винах, что умеет по запаху определить не только сорт вина, но и какого оно урожая! Он может прислать медовуху. Шесть бутылок на продажу, две отцу... а может, и больше – он не откажется! В общем, забери медовуху и возвращайся сюда.$B$BГилверадин живет неподалеку от пристанища высших эльфов во Внутренних землях. С эльфами этими лучше не связываться, уж поверь мне!', 'Поговорите с Гилверадином Ловчим Солнца во Внутренних землях.', 'А, ты знаешь Мальтона? Он мой старинный собутыльник! Понимаешь, я нашел средство, преодолевающее все искусственные границы и условности. Это – выпивка! Если бы разумные существа выпивали, вместо того чтобы воевать, мир сделался бы куда лучше и чище.$B$BВпрочем, боюсь, ты здесь не затем, чтобы слушать лекции о благословенных свойствах алкоголя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (651, 'Связывающие камни', 'Четыре связывающих камня разбросаны по нагорью Арати. Эти камни пригвоздили меня к земле.$B$BЧтобы оковы исчезли, нужно снять замок с самого мощного из них – с Внутреннего связывающего камня. А чтобы это сделать, придется собрать ключи с остальных трех камней.$B$BЭти камни охраняют стражи, но если у тебя хватит ума – или удачи, – тебе удастся найти возможность их нейтрализовать.', 'Добудьте огненный ключ, резной ключ и громовой ключ с западного связывающего камня, восточного связывающего камня и внешнего связывающего камня.Отнесите ключи к внутреннему связывающему камню.', '<Голос Мизраэли доносится из камня.>$B$BТы смог это сделать! Ты открыл замки! Я чувствую, как спадают мои оковы, и свобода все ближе.$B$BТы мой благородный спаситель, $C $N!', 'Перед вами внутренний связывающий камень. Это самый мощный из связывающих камней, и нужно открыть его, чтобы открылись замки остальных камней.', NULL, NULL, 'Огненный ключ', 'Резной ключ', 'Громовой ключ', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (652, 'Разбить краеугольный камень', 'Открыв замки связывающих камней, ты $gосвободил:освободила: меня от большей части моих оков, но кое-что еще удерживает меня. Это ключ-камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук.$B$BВы должны заполучить у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и использовать его для открытия ключ-камня.$B$B$N, вы так много сделали, чтобы мне помочь... Еще немножко... и моя благодарность потрясет все земные устои!', 'Найдите и убейте Фозрука. Принесите Жезл Порядка к краеугольному камню на нагорье Арати.', 'Вы вставляете жезл в ключ-камень. Земля под вами начинает дрожать...', 'Ключ-камень заряжен сильнейшей геомантической энергией.', NULL, NULL, 'Жезл Порядка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (653, 'Союзники Мизраэль', '$gГоворит Мизраэль.>$B$BСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.$B$BНо в должный час я пойду против гигантов, и они еще пожалеют о том, что отняли у меня свободу!$B$BТы $gблагородный союзник:благородная союзница:, $N. Через некоторое время мне вновь понадобится твоя помощь. Когда я буду готова, нужно, чтобы ты $gпризвал:призвала: меня на поверхность.$B$BПоговори с Герриком Костохватом. Он обитает в Стальгорне, в Заброшенном гроте. Он знает, как меня можно призвать.', 'Поговорите с Герриком Костохватом в Заброшенном гроте в Стальгорне.', 'Госпожа сказала мне о вашем приходе, $C. Приветствую вас в моем обиталище – ведь вы, как и я, служите высшей цели.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (654, 'Полевые испытания в Танарисе', 'После подключения источника энергии набор для полевых испытаний начинает светиться и вибрировать. Похоже, он работает как надо.$B$BЯ позабочусь о доставке.$B$BВсе необходимые образцы ты можешь найти в пустыне Танарис.$B$BСобрав их, доложи о выполнении главному инженеру Чепухастеру.', 'Добудьте приемлемые образцы тканей 8 василисков, 8 гиен и 8 скорпионов. Отнесите набор для проведения испытаний главному инженеру Чепухастеру в Прибамбасск до окончания действия источника энергии.', 'Ну ладно, на удаление источника энергии мне понадобится пара секунд. После этого можешь делать все, что захочешь, не боясь потерять данные.', 'Ну что, все образцы успел собрать? Если не все, то помни, как только энергия закончится, все результаты пропадут и придется начать все с начала.$B$BЭй, не жди от меня сочувствия; я думаю только об интересах Водной компании Прибамбасска, а если мне придется продавать источники энергии до возобновления поставок с ледяных ключей Дун Морога, то да будет так!', NULL, NULL, 'Непроверенный препарат тканей василиска', 'Непроверенный препарат тканей гиены', 'Непроверенный препарат тканей скорпида', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (655, 'Павший Молот', 'Воспоминания по-прежнему ярки, как будто все было вчера... Так много лет без надежды, прикованный к этой проклятой дыре деревом и сталью. И вот наконец появился вождь: Молот Рока блещет полуночными доспехами, высоко вздымает боевой молот...$B$BКак же это подло, как непереносимо, что удар труса мог сразить нашего величайшего героя. Враг наскочил сзади и пронзил его копьем... Я упал на колени. Какая могла быть надежда? Какая еще может быть надежда...', 'Поговорите с Тор\'ганом в Павшем Молоте.', 'А, вы говорите о Гор\'муле. Да, судя по вашим словам, похоже, он так и не оправился от смерти Молота Рока.$B$BГор\'муль был пленником здесь, когда Тралл и Оргрим вели битву за освобождение лагеря, но когда затряслясь земля и наши братья сбежали, его оставили там. Лишенный малейшего проблеска надежды, он скитался, затерянный, в одиночестве, пока мы не вернулись сюда, чтобы вновь поселиться в Павшем Молоте.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (656, 'Призыв принцессы', 'Вы должны нанести поражение Мизраэль прежде, чем она обретет полную силу. Если вы этого не сделаете, то, как только она наберет достаточно сил, она кинется на своих пленителей! Есть такие, кто считает, что может ее контролировать, но если ее можно контролировать, с чего было гигантам с самого начала заковывать ее в цепи?$B$BПотрясающая логика, да?$B$BЧтобы сразить Мизраэль, призовите ее у ее кристаллов, где вы в первый раз говорили с ней. Нанесите ей поражение и заберите ее мистические оковы, а потом подсоедините их к кристаллам Мизраэль.$B$BСделайте так – и она вновь будет поймана в ловушку.', 'Отправляйтесь к кристаллам Мизраэль, призовите принцессу и победите ее.Заберите ее мистические оковы и присоедините их к кристаллам.', 'Когда мистические оковы охватят кристаллы, из подземных глубин раздается нечеловеческий вой, переходящий в рык.$B$BКристаллы Мизраэли больше не излучают тепла и чувства безопасности, как это было раньше. Теперь они пульсируют неприкрытой угрозой... как если бы существо внизу, под ними, исходило злобой, направленной на поверхность.', 'Кристаллы Мизраэли сейчас подозрительно спокойны.', NULL, NULL, 'Мистические оковы', 'Свиток Мизраэль', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (657, 'Новая чума зарождается?', '<Кви начинает просматривать папку.>$B$BЭто в самом деле интересно! Похоже, аптекарь Йорель проводил здесь, на ферме Го\'Шека, какие-то смертельно опасные эксперименты. Я не знаю точно, какое это имеет отношение к Хилсбраду, но Фину не понравится, если мы проигнорируем такое дело.$B$BМы тут столкнулись с орками в ваше отсутствие, и теперь я не настолько хорошо себя чувствую, чтобы отправиться на помощь к Кинелори. Но если ты не против, проводи ее к ферме, где она собирается выкрасть результаты исследований, которые Йорель так и не отослал пока в Мельницу Таррен.', 'Поговорите с Кинелори на Ферме Го\'Шека, что на нагорье Арати. ', 'Если это успокоит Фина, я уничтожу каждого из Отрекшихся поодиночке. Он столько сделал для нас с тех пор, как началась чума. Мы и не надеялись, что когда-нибудь у нас снова будут друзья или семья.$B$BКогда будете готовы, дайте мне знать. Мы тотчас же двинемся в путь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (658, 'Новая чума зарождается?', 'Так тебя Фин послал узнать, как мы тут? Неудивительно – он слишком много беспокоится.$B$BМы уже много дней наблюдаем за этой фермой, и Кин уверяет, что недавно видела гонца, выходящего из вон того маленького домика с южной стороны.$B$BОна любительница поболтать, но я всегда доверяю ее ощущениям, когда мы бываем в опасных местах.$B$BА ты часом не следопыт, а? Мы думаем, что гонец может относить записки в городок Мельница Таррен. Если бы мы могли заполучить эти документы, это пролило бы свет на события в Хилсбраде.', 'Найдите Отрекшегося-курьера и принесите обнаруженную у него запечатанную папку Кви близ фермы Го\'Шека.', 'Отлично!$B$BПосмотрим, о чем тут идет речь...', 'Мы признательны вам за помощь в поисках гонца, $N.$B$BПока вас не было, Кин увидела аптекаря, выходящего из того же дома к югу отсюда. Я уверена, что они замышляют что-то дурное – но мне нужны доказательства, чтобы не натворить чего-нибудь по неосторожности.$B$BА вам удача улыбнулась?', NULL, NULL, 'Запечатанная папка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (659, 'Новая чума зарождается?', 'Приветствую, $N, приятно познакомиться. Я руковожу группой смельчаков, расследующих странные происшествия в этом районе.$B$BМоим родственникам в Хилсбраде недавно пришлось избавиться от своей собаки Стэнли, потому что животное таинственным образом выросло до невообразимых размеров и стало кидаться на каждого встречного.$B$BЯ уверен, что тут замешана нежить, и мы ищем доказательства.$B$BДве моих спутницы, Кви и Кинелори, отправились к ферме Го\'Шека, что находится на нагорье Арати, и давно не подавали о себе вестей. Найдешь их? А то я начинаю беспокоиться.', 'Найдите Кви и Кинелори у фермы Го\'Шека на нагорье Арати.', 'Постарайся быть как можно незаметнее, путник.$B$BОркам не слишком нравится, когда за ними шпионят, а их тут больше, чем видно невооруженным глазом.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (660, 'Новая чума зарождается?', 'Ладно, $N. Если вы готовы, то и я тоже.$B$BПопробуем?', 'Защищайте Кинелори, пока она не вернется к Кви. ', 'Вы оказали нам огро$Nю услугу, $N. Благодарю вас.$B$BНадеюсь, Кин не доставила вам слишком мног хлопот. Она очень дружелюбна, но может быть и смертельно опасной, если вы ее враг.', 'Время для болтовни закончилось. Защитите Кинелори, если вам небезразлична судьба народа Хилсбрада.', NULL, NULL, 'Защитите Кинелори.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (661, 'Новая чума зарождается?', 'После ночной гулянки в таверне Кинелори выглядела похуже, чем сейчас. Видно, вы неплохо ее защищали.$B$BТо, что она принесла с фермы, должно как минимум дать Фину представление о том, что происходит здесь, в Арати. Для того чтобы удоствоериться, что после вашей атаки не последует ответного удара, мы здесь ненадолго задержимся. Вы не откажетесь отправиться обратно в Южнобережье и поговорить с Фином?', 'Найдите Фина Оделика в Южнобережье, что в Предгорье Хилсбрада.', 'Итак, эти две баламутки в конечном счете – в полном порядке? Ха-ха, рад слышать. Благодарю вас за вести об их местонахождении и состоянии – меня в высшей степени радует, что они еще живы; обе они – мои близкие подруги и незаменимые спутницы в путешествиях.$B$BНо... более важна моя благодарность за вашу помощь. Вот, примите это вместе с благодарностью от всей нашей группы.$B$BЕсли посчастливится, мы выясним, что затевают Отрекшиеся, и положим конец их замыслам.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (662, 'Поиски на глубине', 'О\'Брин повел корабли в бухту. Мы были уверены, что именно здесь будет найдено сокровище. \"Вестник\" причалил нормально, но когда \"Девичья Блажь\" и \"Дух Серебряного бора\" приблизились к берегу, вода начала быстро понижаться. Страннейшая вещь, я такого в жизни не видал!$B$BТе два корабля налетели на что-то... нечто вроде храма в рифе. Оба быстро затонули – это была настоящая трагедия.$B$BНужно найти судовые журналы и карты обоих кораблей, прежде чем мы отчалим. Мы не можем оставить эту информацию доступной для любопытных глаз!', 'Первый помощник Нилзликс хочет, чтобы вы достали карты и судовые журналы кораблей \"Девичья Блажь\" и \"Дух Серебряного бора\".', 'Известие о том, что теперь эти сведения в безопасности, немного успокоит наше начальство в Пиратской бухте. Хорошая работа, $N.', 'Как успехи в поиске и спасении документов, $N? Нам и правда очень нужно забрать судовые журналы и карты с \"Девичьей Блажи\" и \"Духа Серебряного бора\".$B$BЕсли имеющиеся там сведения попадут в руки врагов, командир флота Морской Рок нас по палубе размажет.$B$BЭто если нам вообще удастся отсюда выбраться...', NULL, NULL, 'Карты \"Девичьей Блажи\"', 'Судовой журнал \"Девичьей Блажи\"', 'Карты \"Духа Серебряного бора\"', 'Судовой журнал \"Духа Серебряного бора\"');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (663, 'Эй, там!', 'Ой, кого видит Лоло! Это ж крошка-$R! Лоло всегда начеку!$B$BДобро пожаловать в бухту Фальдира. Капитан О\'Брин сказал, что мы задержимся тут лишь на несколько часов. Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую Бухту.$B$BНо Лоло думает, мы тут надолго засели. Из нашей эскадры мы потеряли два корабля. Беднягу \"Дух Серебряного бора\" и несчастную \"Девичью Блажь\". На дне морском они теперь!$B$BЛоло думает, вам бы переговорить с капитаном О\'Брином, если вы тут и дальше слоняться собираетесь.', 'Поговорите с капитаном О\'Брином в бухте Фальдира, что на нагорье Арати.', 'Хей, дружище.$B$BНу и жуть же была. Морской Рог отнимет у меня корабль, если проведает, что тут произошло.$B$BОдна из этих хитрых профессорских штучек указала на то, что поблизости от этой бухты лежит давно утерянный клад. Я привел \"Вестник\" к берегу, чтобы причалить, и сигнализировал \"Духу Серебряного бора\" и \"Девичьей Блажи\", чтобы они сделали то же самое.$B$BА потом вдруг море загрохотало. Вода понизилась, и оба корабля разбились, врезавшись в риф.$B$BНо это был не просто риф. Что-то было там, внизу...$B$BПомогите моей команде, и получите неплохое вознаграждение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (664, 'Затонувшие печали', 'Ох, жизнь – ужасная штука. Я должен бы покоиться в водяной могиле, а не сидеть здесь у огня, наслаждаясь свежим воздухом.$B$BКоманда не жалела сил, чтобы спасти мою прекрасную \"Девичью Блажь\". Да упокоятся ребята в мире, благословенны их сердца.$B$BО\'Брину удалось выбраться на берег, а нам не повезло. Море просто опрокинулось на нас, клянусь вам.$B$BВот мы плывем – и вот следующая волна обрушивается на нас. А эти твари! Они убили всех, кто выжил. Подлое нагово отродье. Я вырубился и пришел в себя уже здесь.$B$BЯ жажду их мерзкой холодной крови!', 'Капитан Стальные Нервы из бухты Фальдира хочет, чтобы вы убили 10 налетчиков и 3 колдуний из клана Пронзающего Гребня.', 'Славно потрудились, $N.$B$BЭти твари получили по заслугам. Хотя ничто не вернет мне мой корабль и мою команду, смерть этих наг дает хоть какое-то утешение.', NULL, NULL, NULL, 'Налетчик из клана Пронзающего Гребня убито', 'Колдунья из клана Пронзающего Гребня убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (665, 'Утонувшее сокровище', 'Теперь, когда мы настоящие полноценные разбойники Черноводья, мы должны помочь мистеру О\'Брину разыскать пропавшее эльфийское сокровище.$B$BПочти невозможно найти драгоценные камни в море без посторонней помощи. Доктор сконструировал специальные очки, которые должны помочь. Ему нужно зарядить эти очки энергией, извлеченной из заколдованного камня в пещере, расположенной выше по холму.$B$BНо эта пещера проклята! Когда мы подошли к ней, на нас напали. Защитите меня, и я смогу вытянуть энергию из камня и направить ее в очки.', 'Проводите профессора Физзлторпа в пещеру и обратно. ', 'Теперь очки работают превосходно! Отличная работа. $N.', 'Некогда болтать! Нужно зарядить очки энергией камня!', NULL, NULL, 'Защитите профессора Физзлторпа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (666, 'Утонувшее сокровище', 'Сокровища так долго лежали на дне морском, что покрылись известковым налетом, превратившись в большой камень. Но сила, влитая в эти очки, позволит вам легко определить их местонахождение.$B$BМаленькая гномская хитрость делает большие дела!$B$BВозьмите эти очки Ловца сокровищ, $N, посмотрите, может, вам удастся собрать какие-то из утерянных сокровищ для капитана О\'Брина.$B$BЯ бы и сам поплыл туда, но... эм... ну, у меня есть серьезные научные задачи, требующие срочного решения на надежной, сухой земле... да... вот.', 'См. Затонувшее сокровище. Доктор Драксельмер в бухте Фальдира хочет, чтобы вы собрали 10 эльфийских самоцветов и вернули ему очки Ловца сокровищ, когда закончите.', 'Великолепно, $N! Капитан будет очень доволен! Погодите, вот еще весть долетит до флотовладельца Морского Рога!..', 'Ну, и как работают очки? Все функционирует как надо? Можно подрегулировать, если есть необходимость.$B$BАх да, эти очки понадобятся мне, когда вы закончите. Я уверен, что капитан О\'Брин найдет им потом самое разнообразное применение.', NULL, NULL, 'Эльфийский самоцвет', 'Очки Ловца сокровищ (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (667, 'Смерть со дна морского', 'Это плохо. Похоже, клан Пронзающего Гребня готовится к нападению.$B$BНаги известны своей жестокостью в бою. Они не остановятся, пока я не умру.$B$BНе то чтобы я ценил свою жизнь выше, чем жизни членов команды, но вы должны помочь защитить меня. Я единственный, кто знает морские пути, – команда просто не сможет вернуться в Пиратскую Бухту без меня.$B$BНаги придут с моря. Мне нужно, чтобы вы оставались здесь, со мной, чтобы отразить их атаку. Займите место у пушки и оттесните их.$B$BГотовы, $N?', 'Защитите Мураша О\'Брина во время атаки наг.', 'Мы пережили их атаку!$B$BБез вас, $N, нам бы это не удалось. Мы отчалим, как только поднимется прилив. Если бы вы не были столь многообещающей героической личностью, я предложил бы вам место в своей команде. Но, конечно, вас ждет рыбка покрупнее.$B$BНесмотря на то, что вы всего лишь $r..', NULL, NULL, NULL, 'Защитите Мураша О\'Брина.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (668, 'Утонувшее сокровище', 'Не будем заставлять капитана О\'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь!$B$BА через несколько недель сотрудничества с этими пиратами мы с профессором поняли, что на нашем здоровье самым пагубным образом может сказаться, если нас застанут придерживающими их сокровища.$B$BВот, $N, отнесите все О\'Брину.', 'Отнесите эльфийские самоцветы капитану О\'Брину в бухту Фальдира, что на нагорье Арати.', 'Так, значит, коротышки в конце концов оказались полезными? Я знал, что мы этих мальчиков-с-пальчик не напрасно взяли с собой!', 'Эй, $C. Что привело вас на мостик?', NULL, NULL, 'Эльфийские самоцветы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (669, 'Утонувшее сокровище', 'Командир флота Морской Рог захочет сразу же услышать о нашей находке.$B$BНо, как видите, мы пока не в том положении, чтобы сняться отсюда. Не только прилив очень низок, но еще и эти проклятые твари, которым мы помешали, бдительно следят за нашими передвижениями.$B$BВы оказали бы большую услугу Пиратам Черноводья, если бы смогли сообщить флотовладельцу Морскому Рогу в Пиратскую Бухту, что мы отыскали сокровища и работаем над тем, чтобы достать еще. А этот образчик отвезите ему в качестве доказательства.', 'Доставьте образец эльфийского самоцвета командиру флота Морскому Рогу в Пиратскую Бухту, что в Тернистой долине.', 'А, узнаю старого доброго Мураша О\'Брина! Я знал, что это подходящий капитан для такого задания!', 'Что привело вас в Пиратскую бухту, $C?', NULL, NULL, 'Образец эльфийского самоцвета (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (670, 'Утонувшее сокровище', 'Слушайте, $N, у вас лицо искателя приключений. Мой флот застрял в Пиратской Бухте, пока мы не загрузимся.$B$BТам, да и не только там, творятся темные делишки, а мне нужно доставить кое-какую секретную корреспонденцию Мурашу О\'Брину, пришвартовавшемуся к побережью Арати.$B$BМогу ли я доверить вам доставку этого сообщения в целости и сохранности и надеяться на вашу готовность хранить это задание в секрете?', 'Отвезите письмо Морского Рога Мурашу О\'Брину в Бухту Фальдира, что на нагорье Арати.', 'Спасибо, что проделали такой долгий и опасный путь. Благодарю вас от имени разбойников Черноводья.', 'Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!', NULL, NULL, 'Запечатанное письмо Морского Рога (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (671, 'Зловещая магия', 'Я почувствовал что-то странное в воздухе... ощущение, будоражащее мою кровь. У меня возникли подозрения. Я твердо решил найти источник беспокойства и обнаружил на западе, у Северного поместья, остаточные следы призыва демона. Когда я приблизился, кровь буквально вскипела, и ярость разгорелась во мне.$B$BНа земле я заметил амулет из кровавого камня, какими пользуются, вызывая демона. Однако магическая сила найденного мной камня была уже полностью исчерпана. Мне нужен для изучения другой образец, но я не рискую возвращаться в поместье. Можете ли вы принести мне оттуда несколько амулетов?', 'Принесите Тор\'гану в Павший Молот 10 амулетов из кровавого камня. ', 'Выявление истинных намерений Синдиката отнимет у меня некоторое время, но их очевидное сотрудничество с темными демоническими силами меня беспокоит. Я расскажу вам, когда разузнаю.', 'Однажды проклятая кровь по-прежнему течет в моих жилах, $N. Если кто-то... что-то... призывает демонов... его надо остановить.', NULL, NULL, 'Амулет Кровавого камня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (672, 'Вызов духов', 'Мы пытались успокоить его, развеселить, рассказывать ему истории о нашем огромном городе Оргриммаре в Калимдоре, но его ничто не трогало.$B$BИстории о нашем молодом вожде, Тралле, который носит доспехи и молот Оргрима... но, быть может... Может быть! Демонстрация нашей новообретенной шаманской магии могла бы дать ему луч надежды. Попробовать стоит!$B$BМы могли бы сделать для него маленькую вещицу, да... Принесите мне несколько глаз раптора, и я посмотрю, что можно сделать.', 'Соберите 10 глаз нагорных ящеров с нагорных долгоногов и твердозубов и принесите их Тор\'гану в Павший Молот.', 'Отлично. Духи ящеров, от которых взяты эти глаза, предоставят носящему этот амулет свою силу.', 'Я создам амулет, который частично наделит Гор\'муля силой ящеров. Может быть, это пробудит в нем огонь жизни...', NULL, NULL, 'Глаз ящера нагорья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (673, 'Зловещая магия', 'У меня нет сомнений, что в стенах Стромгарда засел могущественный чернокнижник. Время от времени, используя обладающую магической энергией реликвию, этот чернокнижник призывал в больших количествах ужасных демонов. Мы должны отнять у него этот источник энергии.$B$BНайдите чернокнижника и убейте его. Принесите мне магический объект, который найдете при нем, чем бы он ни оказался. Я предприму шаги по разрушению реликвии и прослежу, чтобы ее мощь больше не использовалась для осквернения этой земли.', 'Добудьте сферу кровавого камня у чернокнижницы Марез Клобук и принесите ее Тор\'гану в Павший Молот.', 'Мои бессонные ночи наконец сменятся спокойным сном, когда я разрушу эту сферу. Спасибо вам, $N. Это леденящее напоминание о той ужасной власти, которую демоны имели над орками, прежде чем Адский Крик освободил их от проклятья.', 'Кровь моя пылает... все сильнее. Чернокнижника нужно остановить.', NULL, NULL, 'Оскверненная сфера Кровавого камня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (674, 'Вызов духов', 'Вот, отнесите этот амулет Гор\'мулю и посмотрите, пробудит ли сила ящера в нем тот боевой огонь, который некогда пылал в его крови.', 'Отдайте амулет из когтя ящера Гор\'мулю. Его можно найти в Павшем Молоте, что на нагорье Арати.', 'Что это? Отполированный кусок кости... Что мне пользы от полированной косточки? Разве безделушка способна вернуть Орде ее былую славу?', 'Какая может быть надежда, если рукой труса может быть убит сильнейший из сильных? Какая надежда, ответьте мне!', NULL, NULL, 'Амулет из когтя ящера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (675, 'Вызов духов', '*Гор\'муль бросает амулет на землю.*$B$BВас Тор\'ган послал, да? Тьфу... Никак не могу понять, почему он жалеет меня. В сострадании мне было отказано, когда мне не позволили умереть вместе с моим вождем во время боя. Жестокий удар судьбы настиг меня...', 'Поговорите с Тор\'ганом в Павшем Молоте, что на нагорье Арати.', 'Вижу, что не сработало. Тем не мение я чувствую, что демонстрация силы шаманов может помочь Гор\'мулю вернуть веру в себя. Сила амулета была недостаточно велика, чтобы показать ему нашу новообретенную мощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (676, 'Да падет молот', 'Слабаки... Все они слабаки. А ты, $C, куда смотришь? Думаешь, $gособенный:особенная:? Проверим?$B$BНа форт Павший Молот напали враги. Если не помочь нашим, им не устоять.$B$BВпрочем, не спеши. Прежде надо испытать твое искусство. На северо-востоке от Стромгарда в Арати есть курган, который заселил огрский клан Тяжелого Кулака. Когда одолеешь тамошних огров и мародеров, доложи об этом Драму Желчному в Павшем Молоте.', 'Убейте 8 огров и 10 головорезов из клана Тяжелого Кулака, затем найдите Драма Желчного в Павшем Молоте на нагорье Арати.', 'Значит, ты думаешь, что тебе хватит сил помочь Павшему Молоту? Да будет так.$B$BСальный послал тебя в огрский курган или в надежде, что ты там погибнешь, или полагая, что сможешь помочь нам. Так или иначе, ты здесь, а мне нужны солдаты. Натиск на наш форт не ослабевает.$B$BЕсли ты собираешься остаться в Павшем Молоте, то отдохни, а потом приходи ко мне. Чего-чего, а сражений на твою долю хватит.', 'У меня нет времени топор наточить, не говоря уж о том, чтобы покинуть форт и заняться теми тварями, которые убивают моих братьев.$B$BПохоже, опыта тебе не хватает даже для обычного рубаки, не говоря уж о полноценном $C. Что тебе нужно, Чебуратино?', NULL, NULL, 'Огр из клана Тяжелого Кулака убито', 'Головорез из клана Тяжелого Кулака убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (677, 'К оружию!', 'Тролли из племени Сухокожих и огры из клана Тяжелого Кулака с нагорья Арати стакнулись, чтобы выжить нас с этой земли, но мы не собираемся уступать ни им, ни кому угодно другому. Мы убьем их и покажем, что и мы здесь – у себя дома.$B$BТролли позорно бежали от нас; огры сожрали бы нас и спали бы на наших шкурах, если бы мы им позволили, – этим тварям не должно жить.$B$BМы начнем атаковать племя Сухокожих к югу отсюда. Убивай их пачками и возвращайся только тогда, когда их поселения будут залиты кровью.', 'Убейте 10 метателей топоров, 10 охотников за головами и 8 знахарей из племени Сухокожих, а затем возвращайтесь к Драму Желчному на заставу Павшего Молота.', 'Я вижу боевые отметины на твоих доспехах, и пот струится по твоему лбу. Неплохо, в самом деле неплохо.', 'Если ты еще не выполнил мое задание – может быть, ты просто трус в душе и неумеха в бою.', NULL, NULL, 'Метатель топоров из племени Сухокожих убито', 'Охотник за головами из племени Сухокожих убито', 'Знахарь из племени Сухокожих убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (678, 'К оружию!', 'Твоя сила очевидна, $N. Теперь посмотрим, как ты справишься с настоящим врагом.$B$BУ клана Тяжелого Кулака есть логово к юго-западу отсюда по направлению к дворфийскому мосту, и, если я не ошибаюсь, их молотобойцы и маги должны стать для тебя более серьезным испытанием – по крайней мере, для нас они таковым являются по сию пору.$B$BУбей столько огров, сколько сможешь, и возвращайся ко мне во плоти, если добьешься успеха, или в виде призрака, если потерпишь неудачу. В любом случае я воздам хвалу твоей стойкости в бою.', 'Убейте 10 громил и 4 магов из клана Тяжелого Кулака, затем возвращайтесь к Драму Желчному на заставу Павшего Молота.', 'Ты не слабее кодо, а твоя готовность к битве достойна восхищения.', NULL, NULL, NULL, 'Громила из клана Тяжелого Кулака убито', 'Волхв из клана Тяжелого Кулака убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (679, 'К оружию!', 'Зверю вот-вот отрубят голову... и все же для решающего удара требуется огромная сила, $N. Уверен, именно ты можешь помочь нам нанести этот последний мощный удар. Руководящие этими атаками устроили свое логово прямо в руинах Стромгарда – вот яркий пример человеческой слабости...$B$BНайди и убей вождей клана Тяжелого Кулака и их прислужников-шаманов, пытающихся выжить нас с этих земель.', 'Убейте 7 шаманов и 3 вождей из клана Тяжелого Кулака и возвращайтесь к Драму Желчному на заставу Павшего Молота.', 'Твой народ может гордиться тобой, $N. Угроза сильно уменьшилась, и я уверен, что мы начнем процветать здесь, на этом нагорье.', NULL, NULL, NULL, 'Шаман из клана Тяжелого Кулака убито', 'Вождь клана Тяжелого Кулака убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (680, 'Настоящая угроза', 'Ты отлично служишь моему мужу, $C, но он не знает, почему Павший Молот подвергается атакам.$B$BОр\'Калар – пешка в руках Муг\'тола в Стромгарде – яро ненавидит моего мужа и ничего так не желает, как его смерти – за то, что тот нанес ему поражение много лет назад.$B$BМои авгуры сообщают, что Ор\'Калар устроил для мужа ловушку, поэтому я скрыла от него, что огр объявился в этих землях.$B$BМой муж ринется сломя голову, если узнает о местонахождении огра, а я хотела бы попросить твоей помощи в убийстве этой твари.', 'Убейте Ор\'Калара и принесите его голову Корин Желчной на заставу Павшего Молота.', 'Вы оказали мне огро$Nю услугу, $N. Знайте, что жизнь моего мужа и безопасность Павшего Молота еще на некоторое время защищены благодаря вашим деяниям. Пожалуйста, примите это в качестве награды за вашу смелость.', 'Возле Башни Аратора – вот где вы найдете Ор\'Калара. С его смертью прекратятся атаки на Павший Молот, и жизнь моего мужа будет вне опасности.$B$BЯ вижу по вашим глазам, что вы считаете меня слабой – и даже бесчестной – из-за моего молчания. Однажды вы узнаете, что значит любить – как люблю я. Может быть, тогда вы поймете, что есть и другой вид силы и чести.$B$BА тем временем, выполните мою просьбу и убейте Ор\'Калара.', NULL, NULL, 'Голова Ор\'Калара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (681, 'Северное поместье', 'Мы ведем войну за Стромгард и терпим в ней поражение. Мы делим наш некогда великий город с ограми и Синдикатом, каждая группировка бьется с другой, и конца этому не видно.$B$BНо наши силы иссякают, в то время как силы наших врагов – растут.$B$BНам нужна помощь из Южнобережья, но есть проблемы с доставкой припасов, поскольку Синдикат контролирует территорию между нами.$B$BИди на базу Синдиката в Северном поместье и перебей там всех. Тогда, может быть, давление на наши транспортные пути ослабеет, и доставлять припасы станет проще.', 'Убейте 10 проходимцев и 6 наемников из Синдиката.Затем вернитесь к капитану Ниалс в Опорном пункте.', 'Очень хорошо, $N. Со смертью этих членов Синдиката нам должно стать полегче получать припасы из Южнобережья.$B$BБыть может, у нас еще есть надежда.', NULL, NULL, NULL, 'Проходимец из Синдиката убито', 'Наемник из Синдиката убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (682, 'Знаки Стромгарда', 'Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.$B$BМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!$B$BОтправляйся в район Стромгарда, контролируемый Синдикатом, и отбери у их бойцов наши знаки.', 'Принесите 7 знаков Стромгарда капитану Ниалс в Опорный пункт. ', 'Спасибо вам, $N. Мы известим семьи этих погибших солдат о том, что они пали в бою.$B$BЭто будут печальные вести, и все же это лучше знать о судьбе любимых людей, чем томиться неизвестностью.', 'Вы нашли знаки Стромгарда, $N? В Синдикате должны понять, что они не могут наживаться на смерти наших воинов.', NULL, NULL, 'Знак Стромгарда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (683, 'Просьба Сары Балу', '$N, у меня есть к вам маленькая просьба.$B$BВозьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода. Это небольшой труд для $gтакого:такой:, как ты, $gславного героя:славной девы:.$B$BМне в моем горе сейчас трудно будет предстать перед королем. Ты понимаешь меня.', 'Отнесите прошение Сары Баллу королю Магни Бронзобороду в Стальгорн.', 'Подожите минутку, я прочту письмо...', 'Значит, вы – $N-$C? Я наслышан о вашей доблестной службе Альянсу.$B$BЧто за дело привело вас ко мне ныне?', NULL, NULL, 'Просьба Сары Балу (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (684, 'Разыскивается: Марез Клобук', 'Назначена награда за голову Марез Клобук, высокопоставленной советницы и агента Синдиката. В последний раз ее видели на контролируемой Синдикатом территории Стромгарда.$B$BНаграду можно будет получить у капитана Ниалс.$B$BПредупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. Вооружена и очень опасна!', 'Принесите капитану Ниалс в Опорный пункт голову Марез.', 'Вы справились с Марез Клобук? Отличная работа, $N. В самом деле отличная!$B$BМарез была серьезной угрозой стромгардским защитникам, и ходят слухи, что она служила посредницей между Синдикатом и какими-то другими, темными силами. Мы рады узнать, что она больше не будет строить козни против нас.', 'Приветствую, $C. Вы хотите мне о чем-то сообщить?', NULL, NULL, 'Голова Марез', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (685, 'Разыскивается: Отто и лорд Соколиный Шлем', 'Ополчение Стромгарда уведомляет о назначении награды за головы лорда Соколиного Шлема и его телохранителя Отто. Соколиный Шлем руководит деятельностью Синдиката на нагорье Арати, и его смерть внесла бы большую сумятицу.$B$BЕго телохранитель Отто, хотя и не является стратегической целью, представляет собой опасного противника, на счету которого – смерть десятков наших воинов.$B$BНаграды за их головы можно получить у капитана Ниалс.', 'Принесите головы Отто и лорда Соколиного Шлема капитану Ниалс в Опорный пункт.', 'Лорд Соколиный Шлем и Отто? Отлично!$B$BВот ваша награда, $N. Я с радостью выплачиваю ее.', 'Приветствую, докладывайте.', NULL, NULL, 'Голова Отто', 'Голова лорда Соколиного Шлема', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (686, 'Королевские почести', 'Вряд ли добрые дворфские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа. Гибель ее мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе.$B$BМне не под силу вернуть ее супруга из Круговерти Пустоты, но я могу хотя бы почтить его память.$B$BЯ намерен заказать главному каменотесу Стальгорна Мраморщику памятник в честь Салли Баллу.$B$BОтправляйтесь к нему сейчас же и передайте мои слова, $C. Вы будете моим вестником.', 'Поговорите с главным каменотесом Мраморщиком.', 'Значит, вас послал лично король Магни Бронзобород?$B$BПодумать только! Стало быть, дело важное!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (687, 'Тельдарин Заблудший', 'Тельдарин Заблудший некогда был членом нашего ордена Сумеречного Молота. Однако он сошел с ума и отверг наше учение. Перед побегом он украл cвиток Мизраэль! Мы не смогли поймать его, но ходят слухи, что он совсем спятил и прячется в Бесплодных землях.$B$BЧтобы переманить на нашу сторону Госпожу, необходимо найти свиток. А для этого – найти Тельдарина.', 'Найдите Тельдарина Заблудшего.', 'Привет. Привет, привет, привет, привет, привет, ПРИВЕТ!$B$BПрости... Нет, не прощай! Не груби мне!$B$BО нет, это бред сумасшедшего.$B$BНо иногда мое единственное утешение – в безумии.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (688, 'Союзники Мизраэль', '$gГоворит Мизраэль.>$B$BСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.$B$BНо в должный час я пойду против гигантов, и они еще пожалеют о том, что отняли у меня свободу!$B$BТы $gблагородный союзник:благородная союзница:, $N. Через некоторое время мне вновь понадобится твоя помощь. Когда я буду готова, нужно, чтобы ты $gпризвал:призвала: меня на поверхность.$B$BПоговори с Заруком в Павшем Молоте. Он знает, как меня можно призвать.', 'Поговорите с Заруком в Павшем Молоте, что на нагорье Арати.', 'Добро пожаловать, $C. Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть ее на поверхность, нам нужно многое обсудить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (689, 'Королевские почести', 'Значит, наш добрый король решил построить памятник в честь солдата по имени Салли Баллу? И вы говорите, что бедный парень погиб на мосту Тандола?$B$BДа будет когда-нибудь мир в Азероте?$B$BКак бы то ни было, любое поручение нашего государя – дело первостепенной важности. Чтобы возвести действительно впечатляющий памятник на века, мне нужен самый лучший камень. Отправляйся на Холм Дарроу в Хилсбрад и привези мне альтеракского гранита.', 'Принесите главному каменотесу Стальгорна Мраморщику 5 кусков альтеракского гранита.', 'Замечательно! Лучше, чем я представить мог!$B$BА воображение у меня, между прочим...', '$N, $N, $N! Говорите же, привезли ли вы мне достаточно альтеракского гранита, чтобы начать творить шедевр в честь Салли Баллу?', NULL, NULL, 'Альтеракский гранит', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (690, 'Просьба Малина', 'Приветствую тебя, $N. Ты $gпохож на искателя:похожа на искательницу: приключений, а у меня как раз есть задание, требующее склонности к авантюрам.$B$BВерховный маг Трелан, мой первый наставник, не так давно бежал из Стромгарда, что на нагорье Арати, и просил меня помочь ему вернуть несколько предметов, которые он там оставил.$B$BГород был осажден, и Трелан попытался защитить башню Аратора, но потерпел неудачу. У меня на нагорье есть агенты, но они просили дополнительной помощи. Ты не против мне помочь?', 'Найдите Скуэрто в Опорном пункте на нагорье Арати. ', 'Так вас, значится, Малин прислал? А мне без разницы, пусть хоть сам Мурадин восстанет из мертвых и умчит вас отсюда на драконе... Я занят! Если вам что-нибудь нужно, обратитесь к Кретьену.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (691, 'На вес золота', 'Верховный маг Малин послал нас со Скуэрто собирать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда вы здесь, думаю, моя проблема решена.$B$BВот что мне нужно: клыки троллей из клана Сухокожих, лекарские сумки клана Сухокожих и нож темного охотника.$B$BНе могли бы вы добыть это все для меня? Племя Сухокожих обитает к юго-востоку от Арати.', 'Найдите 10 клыков троллей из племени Сухокожих, 4 лекарских сумки племени Сухокожих и нож темного охотника и принесите их ученику Крайтену в Опорном пункте.', 'Невероятно! Теперь я понимаю, почему Малин попросил вас присоединиться к нам – вы отлично потрудились!$B$BТакими темпами мы со Скуэрто очень скоро двинемся обратно в Штормград!$B$BЯ уверен, что мой спутник-дворф вернулся с разведки из Крепости Тяжелого Кулака; пообщайтесь с ним, когда будет время.$B$BПо нему заметно, что он затеял с ограми потасовку. Впрочем, не говорите ему об этом: он очень чувствителен к критике его навыков разведчика.', 'Что-нибудь вам уже удалось, $N?$B$B*Кретьен в процессе чтения делает какие-то пометки в своем журнале.*$B$BЕсли мои исследования верны, клыки можно собирать с любых троллей из племени Сухокожих. Лекарские сумки должны быть у знахарей Сухокожих, а особые ножи даются самым лучшим темным охотникам племени, когда они проходят ритуал посвящения. Невозможно заранее сказать, у какого из темных охотников есть такой нож, пока не сразишься с ним.', NULL, NULL, 'Клык тролля из племени Сухокожих', 'Лекарская сумка племени Сухокожих', 'Нож темного охотника', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (692, 'Утраченные фрагменты', 'Свиток Мизраэль... Свиток Мизраэль?! Нет, уверяю тебя, не стоит даже думать о нем! Его магия может вытащить Мизраэль на поверхность, и если ты это сделаешь, нам грозит беда!$B$BИли... может быть, уже слишком поздно. Может быть, она уже свободна. Может быть, она уже собирается с силами, прежде чем обрушиться на нас. Если так, свиток тебе НЕПРЕМЕННО ПОНАДОБИТСЯ!$B$B...как ужасно, что он уничтожен. Спятившие элементали похитили его и разорвали на клочки, а теперь дерутся за них.$B$BНо если бы тебе удалось собрать эти фрагменты, может быть, мы смогли бы восстановить свиток...', 'Принесите рваный, мятый и обожженный фрагменты свитка Тельдарину Заблудшему.', 'А, вы их нашли! Отличная работа, $N! Это, может, единственный наш шанс противостоять злу, которое несет Мизраэль!$B$BДайте-ка я найду мой степлер – посмотрим, смогу ли я соединить эти клочки...', 'Вы нашли фрагменты?! Вам непременно понадобится Свиток Мизраэли, если вы хотите вновь пленить ее, пока еще не стало слишком поздно!', NULL, NULL, 'Рваный фрагмент свитка', 'Мятый фрагмент свитка', 'Обожженный фрагмент свитка', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (693, 'Оружие получше кулаков', 'Здорово, $N.$B$BЯ выяснил, где оказалась первая вещь Трелана: Коргреш держит ее в зале Тяжелого Кулака. И судя по тому, как он кидался в своих потоками льда, чтобы заставить их держать строй, он, должно быть, уже близко подошел к пониманию того, как использовать мощь жезла на полную катушку.$B$BЧтобы добраться до зала Тяжелого Кулака, нужно идти на юг отсюда, а затем на восток от моста Тандола. Найди этого огра и отбери у него жезл.$B$BА за время твоего отсутствия я соображу, что нам делать со Стромгардом.', 'Найдите заклинательный жезл Трелана и верните его Скуэрто в Опорный пункт.', 'Блестяще, $N. Один предмет найден, и, по моему списку, осталось еще три. Все они находятся в Стромгарде.$B$BПередохните и восстановите силы – следующий этап моего плана потребует немного больше времени и усилий. Возвращайтесь ко мне, плотно покушав и отдохнув.', 'Наша цель – жезл, $N. Пока сосредоточьтесь на этой задаче.', NULL, NULL, 'Заклинательный жезл Трелана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (694, 'Оборона Трелана', 'Все отдохнули?$B$BВот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде. Необходимо активировать защитные возможности башни, если ты хочешь иметь хоть малейший шанс выстоять против них. Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман из клана Тяжелого Кулака. Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти.$B$BДобудь один из самоцветов и принеси его Кретьену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи.', 'Найдите лазурный агат и принесите его ученику Крайтену в Опорный пункт.', 'Вы меня просто поражаете, $N. Снова отличная работа.$B$BМинутку, я применю подходящее заклинание, чтобы заколдовать самоцвет, и все будет готово.', 'Привет еще раз, $N. Вы еще не нашли лазурный агат?', NULL, NULL, 'Лазурный агат', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (695, 'Чары ученика', 'Вот, $N. Самоцвет нужно только прижать к одному из пьедесталов у основания башни, чтобы активировать ее защитные силы. Используйте его, когда будете готовы войти в башню и искать остальные принадлежащие Трелану предметы.$B$BУдачи вам. Я буду ждать вашего возвращения в лагере. Ах да, перед уходом поговорите со Скуэрто: он расскажет вам обо всем, что нужно.', 'Поговорите со Скуэрто в Опорном пункте, что на нагорье Арати.', 'Хорошо, хорошо.$B$BЕсли нас ничего больше не держит, может быть, начнем?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (696, 'Атака на башню', 'Вот что тебе нужно найти: талисман Трелана, сферу Трелана да угольный агат Трелана.$B$BВсе эти три предмета должны быть в сундуках в башне, и ты спокойненько откроешь эти сундуки; главное – берегись огров.$B$BЗащитники башни не будут ими заниматься; придется тебе свое оружие держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их – ясное дело, они решат задать тебе взбучку.$B$BБудь $gосторожен:осторожна: – и удачи!', 'Найдите талисман, сферу и угольный агат Трелана и принесите их Скуэрто в Опорный пункт.', 'Никого лучше Малин и найти не мог в помощь нам, $N. Потрясающая работа!$B$BОн будет рад увидеть, каким ошеломляющим успехом увенчалась наша миссия.', 'Тебе все удастся сделать, и я уверен, Малин будет более чем доволен тобой.', NULL, NULL, 'Талисман Трелана', 'Сфера Трелана', 'Угольный агат Трелана', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (697, 'Просьба Малина', 'Отвезите это письмо обратно в Штормград и скажите Малину, что мы с Кретьеном скоро будем дома. Он хорошо вознаградит вас за помощь нам, $N, в этом-то я не сомневаюсь.$B$BДоброго пути!', 'Отвезите запечатанное письмо верховному магу Малину в Квартал Магов Штормграда.', '<Верховный маг Малин вскрывает письмо, и глаза его расширяются.>$B$BСветом клянусь, вам удалось! Трелан будет очень доволен. Я уверен, Кретьен и Скуэрто так же, как и я, радуются своему предстоящему возвращению в Штормград.$B$BБлагодарю вас, $N. Пожалуйста, примите это как помощь в ваших странствиях.', 'Слушаю вас... Ваше лицо мне смутно знакомо. Прошу прощения, мы раньше нигде не встречались? У меня столько дел, что я просто теряюсь.', NULL, NULL, 'Запечатанное письмо верховному магу Малину (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (698, 'Нехватка ресурсов', 'Я стараюсь добыть припасы для нашего поста на побережье, к востоку отсюда. Ток\'Кар делает, что может, но после несения караульной службы и приготовления пищи для солдат, времени у него остается немного.$B$BОни любят мясо острозубов, но у меня до сих пор не было возможности отправить им новую партию. Ты не $gмог:могла: бы помочь?$B$BМолодые острозубые кроколиски не так вкусны, как взрослые особи, так что дай им еще год-другой подрасти.', 'Принесите Ток\'Кару в Болотах Печали 8 сырых боков острозубых кроколисков.', 'Прекрасно! Свежее мясо к ужину! Спасибо, $N. $B$BНынешний вечерок будет куда приятнее прошлого – мы наедимся досыта. $B$BПускай Дар – орк на морду ужасный, зато добрый внутри.', 'Лок\'тар, $C. Путешествие через болота легким не назовешь. Ты действительно отважен, раз решился на это.', NULL, NULL, 'Сырой бок острозубого кроколиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (699, 'Нехватка ресурсов', 'Мурлоки на побережье представляют опасность, поэтому нас послали сюда отразить эту угрозу Каменору или, если силы врага окажутся слишком велики, поднять тревогу. Отдыхать нам особо некогда, и мы не откажемся от твоей помощи. $B$BИз когтей острозубого крепкохвата выходит неплохое оружие, если выделать их должным образом. Раздобудь немного для нас, и ты получишь оружие нашей работы в благодарность за свежее мясо и хорошую компанию.', 'Принесите 6 когтей острозубого крепкохвата Ток\'Кару на Болота Печали.', 'Рад видеть тебя живым и здоровым, $N.$B$BЭти когти нам весьма пригодятся, ведь чем больше оружия у нас будет в момент атаки, тем лучше.$B$BНачну работу над твоим экземпляром как можно скорее, много времени это не займет, я уже наловчился его изготавливать.', 'Добрая медовуха, костер, армия орков и запас оружия – это то, что надо! Я не жалею, что нас послали сюда охранять Каменор, но было бы неплохо однажды сделать здесь хороший бункер или хотя бы поставить башню.', NULL, NULL, 'Коготь острозубого крепкохвата', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (700, 'Королевские почести', 'Ах, какой прекрасный камень доставляют из Лордерона! Как жаль, что этот край лежит в разрухе.$B$BНо памятник получился весьма хорош! Думаю, король будет очень им доволен.$B$BТеперь же, будьте добры, пошлите государю весть, что памятник выполнен, как он и просил.', 'Доставьте известие королю Магни Бронзобороду. ', 'Гранит – такая малость по сравнению с жизнью достойного дворфа. Но ни один дворф в этом мире не вечен.$B$BБудем надеяться, что этот мемориал станет напоминанием будущим поколениям великого Азерота. Мы никогда не забудем, что за них отдали жизнь отважные солдаты вроде Салли Баллу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (701, 'Коварство ящера', 'При наличии дополнительных компонентов я смогу изготовить предмет, который наделит Гор\'муля коварством ящера! Когда сила ящера проникнет в Гор\'муля, он узнает о нашем новом могуществе, и спящий в его душе воин снова пробудится!$B$BДля того чтобы создать предмет и соответствующее заклинание, мне потребуются сердца ящеров.', 'Добудьте для Тор\'гана 12 сердец ящера, вырвав их у плотоглотов нагорья.', 'Да, эти отлично подойдут. Я перенесу силу и дух ящеров в эту сферу. Она наделит Гор\'муля огненной силой и разумом ящеров.', 'Я все приготовил, теперь мне нужны лишь сердца ящера.', NULL, NULL, 'Сердце ящера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (702, 'Коварство ящера', 'Возьмите эту сферу и используйте ее энергию, чтобы дух ящера вселился в Гор\'муля. Уверен, это взбодрит его дух и откроет новые горизонты жизни. Когда он вернется в нормальное состояние, мы сможем разъяснить ему, в каком положении находится нынче Орда, и тогда в наших непрекращающихся войнах мы сможем получить поддержку великого воина.', 'Отдайте сферу Тор\'гана Гор\'мулю. Его можно найти в Павшем Молоте, что на нагорье Арати.', 'По крайней мере, на сей раз – что-то интересное. Оно излучает странную силу...', 'Вы опять вернулись? Только мне не хватало снова этой жалости Тор\'гана.$B$BЧто вы принесли мне на этот раз? Может, цветную ниточку? Или, может, веревку, чтобы я мог покончить со своим жалким существованием?..', NULL, NULL, 'Сфера Тор\'гана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (703, 'Жареные крылышки канюка', 'О, жареные крылышки канюка, я их просто обожаю! Такие нежные, сочные, с густым соусом, ммм... Стоит только почуять запах – просто слюнки текут! $B$BЯ прекрасно их готовлю – пальчики оближешь, как раз собирался сварганить их сегодня на ужин, но... У меня есть все, кроме основного ингредиента – крылышек! Добудешь мне крылышек – может, поделюсь рецептом!', 'Принесите 4 крылышка канюка Ригглфаззу.', 'О, я примусь за готовку прямо сейчас! $B$BА вот тебе и рецепт, вдруг тоже придет настроение покулинарничать.', 'Привет, $N! Ну что, что там с моими крылышками?', NULL, NULL, 'Крыло канюка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (704, 'Судьба Эгмонда', 'Последний рапорт от Эгмонда был весьма тревожен, возможно, бедняги уже нет в живых! Он сообщил, что его землекопы обнаружили некие \"древние погребальные урны\" на раскопках близ Ульдамана. Боюсь, эта находка привлекла внимание троггов, так же как и идолы, найденные мною здесь. $B$BМне нужно получить эти урны для исследований. Отправляйся к раскопкам Ульдамана, собери урны и возвращайся ко мне', 'Принесите 4 резные каменные урны геологу Сталекруту в Лок Модан. ', 'Отличная работа! Упорный труд и толика удачи помогут нам выяснить, как связаны трогги с этими древними артефактами. $B$BСегодня ты оказал геологам неоценимую помощь, $N! Твои усилия не будут забыты. Как и бедняга Эгмонд, вечная ему память...', 'Ты нашел эти урны, $N? Надо разобраться, как они связаны с троггами!', NULL, NULL, 'Резная каменная урна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (705, 'В поисках жемчуга', 'Бесплодные земли – неприятное местечко, кишащее коварными хищниками и стервятниками. Жуткое, жуткое местечко, особенно для маленького гоблина. Чтобы выжить, приходится постоянно изворачиваться. $B$BУ меня есть секрет изготовления световых бомб. Я использую их, чтобы отпугивать хищников. Сейчас у меня заканчивается запас ингредиентов, а именно: порошок синего жемчуга. Добудь мне его, и вознаграждение не заставит себя ждать. $B$BНадеюсь, обувь у тебя прочная? Синий жемчуг можно найти в раковинах моллюсков на Коварном рифе. $B$BДа-да, том самом Коварном рифе в Тернистой долине!', 'Принесите 9 синих жемчужин Ригглфаззу в Бесплодные земли. ', 'Отличный жемчуг! Теперь надо смолоть его в порошок, смешать тут кое с чем... $B$BНу, берегитесь стервятники! Я припас для вас бомбы!', 'Ты принес мне жемчужины? У меня почти вышел запас световых бомб.', NULL, NULL, 'Синяя жемчужина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (706, 'Чары яркого пламени', 'В бытность мою учеником Феранора Железной Лапы, я перенял у него технику усиления оружия с помощью наложения огненных чар. Слыхал, Феранор нынче работает в кузне при охотничьем отряде в Лордероне. $B$BНе буду пока забивать тебе голову подробностями, скажу только, что для наведения чар требуется очень редкий ингредиент – кровь из еще бьющегося сердца детеныша черного дракона. Мне надо занять себя чем-то в ожидании распоряжений из Стальгорна, так что если принесешь мне сердце, я продемонстрирую тебе свое умение. Драконов найдешь в долине Летлор.', 'Принесите сердце черного дракона Сигруну Рудотесу. ', 'О, это прекрасно подойдет! Сейчас я немного поработаю над твоим оружием. И оно будет разить без пощады!', 'Как охота, $C?', NULL, NULL, 'Сердце черного дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (707, 'Вы нужны Сталекруту!', '$N. Я получил отчет геолога Сталекрута о ходе раскопок в Лок Модане. Ему нужен курьер для осуществления контроля за другими нашими земляными работами.$B$BБольше ничего сказать не могу, но если желаешь ноги поразмять, отправляйся к Сталекруту.', 'Поговорите с геологом Сталекрутом на раскопках Сталекрута близ озера Лок.', 'Значит, тебя послал Грозовая Вершина, да? Хорошо.$B$BУ меня есть для тебя важное поручение...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (708, 'Черный ящик', 'Поверхность этого металлического черного ящика изъедена ржавчиной, как будто его погружали в кислоту – похоже, он долго пролежал в желудке гигантского кондора. $B$BНа днище ящика выбит какой-то символ и надпись под ним: \"Орудие #19 – Осадная бригада Стальгорна\".', 'Отнесите заржавевший черный ящик в оружейную Стальгорна.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (709, 'Лекарство от судьбы', 'О небеса милосердные! Сама судьба стучится в двери! Помяните мое слово! Рок! Фатум! $B$BНет, я не могу более ничего сказать... Не могу поминать их имен, чтобы они не услышали меня! Но если нам удастся хотя бы узнать о них больше... Может, мы сможем противостоять им! $B$BМожет быть... $B$BИди в Ульдаман – проклятье, я все же произнес это! Найди табличку...табличку Рьюнэха. Да, найди ее! Не заставляй меня повторять! $B$BОна там, в глубине, в древнем сундуке, более древнем, чем любая доселе найденная работа дворфов.', 'Принесите табличку Рьюн\'эха Тельдарину Заблудшему. ', 'О, судьба милосердна к нам! Благодарю тебя! Возможно, нам удастся спастись!', 'Ты нашел табличку? В ней должен содержаться ключ к нашему спасению!', NULL, NULL, 'Табличка Рьюн\'эха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (710, 'Изучение стихий: Камень', 'Здесь, в Бесплодных землях, мне пришлось приостановить работу над моим последним изобретением – оковами Стихий. $B$BКогда они будут закончены, то позволят вызывать еще более мощных элементалей и управлять ими.Чтобы продолжить работу, мне нужны маленькие осколки камня, чтобы опробовать на них некоторые новые заклинания и механизмы. $B$BМаленькие осколки камня, которые можно собрать с младших каменных элементалей, как раз подойдут. Они водятся к западу отсюда, сбегай-ка туда быстренько.', 'Соберите 10 маленьких осколков камня и принесите Лотвилю Вериатусу в Бесплодные земли.', 'О, вот это пойдет! Спасибо, $N!.. Хмм... На выходе получается ощутимо больше песка, чем я предполагал. Надо бы изменить коэффициент трения. Хотя, нет! Величина трения будет пренебрежимо мала, если использовать масло льда! $B$B*Чуть слышно бормоча себе под нос, Лотвил опирается подбородком на сплетенные пальцы и погружается в раздумья...*', 'Так, вот сюда будет в самый раз... Слушай, подержи-ка вот здесь эту штуку! Ага, вот так, только выровняй по нормали. О чем бишь я... Ах, да! Камни, мне нужны маленькие осколки камней... Удобный полигон и материалы для исследования – все, что нужно ученому...', NULL, NULL, 'Маленький осколок камня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (711, 'Изучение стихий: Камень', '$N, ты уже $gпроявил:проявила: себя более $gспособным:способной:, чем все мои ученики вместе взятые. $B$BТеперь мне потребуется сила твоих мускулов. У каменных элементалей при должной осторожности можно найти большие каменные глыбы. Они достаточно велики и тверды, чтобы отколоть от них куски, удобные для исследования. Ты найдешь их у подножия гор к западу или юго-востоку отсюда. $B$BМожешь не торопиться, я пока займусь исследованием более мелких кусочков, которые ты $gпринес:принесла: мне.', 'Принесите 3 больших куска камня Лотвилю Вериатусу в Бесплодные земли. ', '$N, я просто диву даюсь! Я думал, что только полудюжине тауренов под силу донести столько камней!', 'Ты чрезвычайно порадовал меня, $N. Как я и предполагал, мелкие камни разрушились в ходе иследования. Если этот эксперимент будет вполовину столь удачен, как я предполагаю, то те элементали, которых я вызывал прежде, в сравнение не будут идти с теми, которыми я смогу повелевать!', NULL, NULL, 'Большой кусок камня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (712, 'Изучение стихий: Камень', '$N, мне нужно, чтобы ты $gпринес:принесла: мне еще кое-что – браслеты каменных элементалей. Полагаю, с помощью этих браслетов можно оценить прочность моих кандалов. $B$BВ магическом кристалле я видел нескольких каменных элементалей к юго-западу отсюда. Недалеко от них я заметил еще и нескольких огров. $B$BПринеси-ка мне 5 браслетов, чтобы было с запасом. Мой Серво славится умением путать все реагенты и результаты исследований.', 'Принесите 5 браслетов камня Лотвилю Вериатусу в Бесплодные земли.', '$N, а ты никогда не задумывался о карьере лаборанта? Нет? Честное слово, я не представляю, как смогу тут управиться, когда ты уйдешь. У меня прежде никогда не было ученика, сочетающего в себе острый ум, любознательность и физическую силу!', 'Большие камни, которые ты принес мне, просто чудесны, $N! Люсьен доставит те, что останутся от экспериментов, в Каранос. Они мне еще пригодятся. $B$BНапример, устрою себе из них уютное маленькое убежище, когда начну, наконец, практические исследования в рамках междисциплинарного подхода к взрывчатым веществам широкого спектра действия... $B$B*Голос Лотвила стихает по мере того, как ученый вновь погружается в свои эксперименты*', NULL, NULL, 'Браслеты Камня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (713, 'Охлаждение горячих голов', 'Послушай, я расскажу тебе о масле льда – это лучшее средство для того, чтобы уберечь мотор или механизмы от перегрева. $B$BЕго охлаждающая способность просто потрясает, а его долговечность в качестве смазочного материала просто не имеет равных. И это еще не все: оно позволяет сохранять чары на магических предметах. $B$BМне нужен сосуд этого масла, чтобы усилить магический потенциал кандалов моей работы и сделать их достаточно мощными, чтобы вызванный нами дух не прикончил нас на месте.$B$BБрокин, мой друг-гоблин, научит тебя, как изготовить масло. Ты найдешь его в Альтераке.', 'Найдите масло льда и принесите его Лотвилю Вериатусу в Бесплодные земли.', 'Великолепно! Оно послужит прекрасным охлаждающим компонентом для браслетов! И если эти чары падут раньше, чем через сто лет, клянусь, я просто отпишу все мое имущество Серво! $B$BВсе маги лиги будут изумлены, когда я закончу работу, $N! Потерпи, и ты увидишь!', 'Ты принес масло? Мне оно так нужно!', NULL, NULL, 'Масло льда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (714, 'Гиро...чего?', '$N, ты $gсправился:справилась: со своей работой выше всяких похвал.$B$B<Мысли Лотвиля явно витают где-то в его экспериментах.>$B$BБудешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростертыми...$B$BОп-ля! Лови-лови, скорей! Да, спасибо.$B$BА сейчас мне нужна всего лишь одна малость. Довольно маленькая штуковина, но очень важная: гирохронатом.$B$BЕсли сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент.', 'Принесите гирохронатом Лотвилю Вериатусу в Бесплодные земли. ', 'ОГО! <Лотвил хватает гирохронатом>$B$BОтлично! Мы почти у цели! Нет, в самом деле! Это же мой самый приоритетный проект! Дай-ка я засуну эту штуку в положенное ей место, и ты увидишь плоды моих – наших! – трудов! Сейчас, надо только немного подождать... пару секунд... или минут... или часов... Ладно, разберемся.', 'Да-да, одну секундочку... <Лотвил продолжает ковыряться в каком-то хитроумном приспособлении>', NULL, NULL, 'Гирохронатом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (715, 'Жидкий камень', 'Полагаю, все задачи, поставленные перед тобой Лотвилем, вскоре покажутся тебе очень простыми по сравнению с тем, что ждет впереди. С другой стороны, ты $gдоказал:доказала: свою приверженность наукам, которые так чтит Лотвиль. Не поможешь ли ты, в таком случае, и мне? $B$BМне необходимо лечебное зелье и зелье невидимости. Похоже, и то, и другое может мне вскоре понадобиться, если Лотвиль продолжит в том же духе. $B$BВзамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвиля. Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях.', 'Принесите слабое зелье невидимости и лечебное зелье Люсьену Подай-Ключ в Бесплодные земли.', 'УРА! $B$BТо есть, я хотел сказать, спасибо, $N! Это мне понадобится для путешествия по Бесплодным землям.', 'Лотвил уже почти закончил. А как твои успехи?', NULL, NULL, 'Лечебное зелье', 'Слабое зелье невидимости', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (716, 'Камень – лучшая одежка!', 'Я знаю, каким скупым бывает Лотвиль, $N, поэтому хочу сам вознаградить тебя за труды. Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение... $B$BЯ собрал все неиспользованные камни, которые ты $gпринес:принесла: и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся. Разумеется, они будут магическими. $B$BНо мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу.', 'Принесите украшенные узором бронзовые наручи Люсьену Подай-Ключ в Бесплодные земли.', 'А вот и твои браслеты, $N. Ну-ка, примерь!', 'Лучше бы тебе не тянуть, $N.$B$BС Лотвилом никогда не знаешь, что случится в следующий миг.', NULL, NULL, 'Украшенные узором бронзовые наручи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (717, 'Дрожь земли', 'Сейчас уже очевидно, что мы не можем быть уверены, что Чернохлыст и Гематус заключены в Летлоре надежно. Там обосновались черные драконы, кроме того, этим ограм удалось завладеть знаком земли – а это значит, что требуются куда более серьезные меры. $B$BДраконье узилище заперто тремя рунными камнями, которые можно заполучить только с помощью знака земли. Камни нужны, чтобы сломать печать на узилище. $B$BСломай печать и сделай так, чтобы драконы упокоились навек.', 'С помощью знака земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. Поместите рунные камни на печать земли и освободите драконов Чернохлыста и Гематуса. Убейте драконов и принесите Гареку наручники Чернохлыста, цепи Гематуса и знак земли.', 'Кирин Тор больше не будет беспокоиться по поводу грозных пленников Летлора. Я сообщу об этом своему господину. Красус, несомненно, будет доволен.', 'Мощная магия держит драконов под замком, и все же мы должны устранить даже малейшую возможность того, что они снова вырвутся на свободу!', NULL, NULL, 'Наручники Чернохлыста', 'Цепи Гематуса', 'Знак земли (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (718, 'Миражи', 'В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами. Местные огры из лагеря Кош набросились на них, как стервятники на падаль. Хотя воняют огры не лучше... чем падаль, я имею в виду. $B$BВ общем, они растащили все наши обозы с оружием и прочим скарбом и... Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды... $B$BНе $gмог:могла: ли бы ты нам помочь?', 'Верните ящик с припасами Сигруну Рудотесу. ', 'О, благодарю тебя, $N! Мы тут, надо сказать, уж было песок есть подумывали. $B$BНу да это дело прошлое. Сегодня будем пировать, как короли!', 'Да, пустыня не лучшее место для похудания... $B$BЭй, что это у тебя?', NULL, NULL, 'Ящик с припасами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (719, 'Дворф и его инструменты', 'Будь $gосторожен:осторожна:, $N! Повсюду шныряют дворфы Черного Железа – видимо, из клана Тенегорн. $B$BОни только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа. Я едва ноги унес.$B$BРаскоп прямо к северу отсюда. Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку.$B$BКак думаешь – сумеешь помочь? Наверняка кто-нибудь из этих гадов Черного Железа спер мою кирку!', 'Найдите счастливую кирку Ржанца и верните ее геологу Ржанцу к югу от карьера Тяжелоступа.', 'Ты спас меня, $C. Рад, что нашелся кто-то, способный преподать Кузне Теней урок.', 'Не знаю, зачем эти дворфы Кузни Теней тут рыщут, но у них определенно есть какая-то цель...', NULL, NULL, 'Счастливая кирка Ржанца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (720, 'Предвестник надежды', '<Куском мела на карте нацарапаны слова.>\"Рейдол, они уводят меня в Ульдаман. Пришли помощь!$B-Тяжелоступ\"', 'Найдите геолога Ржанца и сообщите, что Грез Тяжелоступ жив.', 'Тяжелоступ жив?! Какое счастье!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (721, 'Предвестник надежды', '$N, ты сможешь разыскать его? Ты разыщешь Тяжелоступа? $B$BПроклятые дворфы из Тенегорна схватили его, чтобы выпытать, что он знает о раскопках поселения $Nв. Если это случится, весь Стальгорн будет в большой опасности! $B$BДворфы Черного Железа уже давно разыскивают способы сотворения могущественных големов. Конечно, такова была цель и Тяжелоступа, но это только для того, чтобы остановить Черное Железо!$B$BВозможно, они сохранят ему жизнь, пока не вытянут из него все секреты. Поспеши, быть может, его еще удастся спасти!', 'Найдите Греза Тяжелоступа в Ульдамане. ', 'О, я так ослабел... *кашляет* Подойди ко мне, $C?$B$Тебя прислал Рейдол? Клянусь Мурадином, парень вовсе не так туп, как кажется.*кашляет*', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (722, 'Амулет тайн', 'Тебе не занимать смелости, раз ты $gявился:явилась: за мной в Ульдаман, $C.$B$BЕсли в самом деле хочешь помочь старику Тяжелоступу... *кашляет*... Найди мне мой амулет. $B$BЭто Чернотень... Его забрал Магреган Чернотень. Он здесь, в развалинах, я знаю... Этот амулет приведет их... *кашляет* прямо к свиткам, если их не остановить... Все в твоих руках, $N! Пожалуйста... верни амулет. $B$BЕсли свитки попадут к ним в лапы, Черное Железо сможет создавать еще более мощных големов. Я знаю, я это нутром чую!', 'Найдите амулет Тяжелоступа и верните его ему в Ульдаман.', 'Ха!*кхе, кхе* $B$BЯ знал, что ты справишься! *сморкается* Отличная работа, $N.*кашляет*', 'Клан Кузни Теней очень опасен! Будь осторожен!*кашляет* Ты должен найти амулет.', NULL, NULL, 'Амулет Тяжелоступа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (723, 'Клятва верности', '$gТяжелоступ едва дышит и, собрав последние силы, произносит слова.: $B$BНайди Рейдола, $N! Передай ему мой амулет... $gкашляет: Он знает, что делать. $gкашляет: Он знает, я искал истоки происхождения нашего народа, $gкашляет: знает и то, что целью моей жизни было остановить клан Кузни Теней. Нельзя позволить, чтобы они нашли свитки... $gкашляет:', 'Отнесите амулет Тяжелоступа геологу Ржанцу в Бесплодные земли.', 'Амулет Тяжелоступа! Если раньше в моем сердце еще теплилась надежда, что он жив, то теперь ничто не снимет с моей души этот камень. Этот амулет – дело всей его жизни. Нельзя допустить, чтобы его смерть была напрасной!', 'Сегодня дурной день. Однако в Бесплодных землях каждый день убивает надежду.', NULL, NULL, 'Амулет Тяжелоступа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (724, 'Клятва верности', 'К кому же обратиться за советом... $B$BИсторик Карник! Конечно! $B$BОн сейчас в Стальгорне – он точно сможет помочь! Он искал потерянные артефакты вместе с Тяжелоступом в Ульдамане. $B$BПолагаю, в Тенегорне прознали, что эти двое располагают тайными сведениями. $B$BСообщи Карнику о том, как погиб Тяжелоступ, и передай ему амулет – а он расскажет, что делать дальше.', 'Отнесите амулет Тяжелоступа историку Карнику в Стальгорне.', 'О, а вот это совсем другой разговор! Возможно, ты еще не осознал всей серьезности происходящего, ведь так? $B$BМы оплачем Тяжелоступа позже. $B$BСейчас я объясню тебе, почему этот амулет так важен.', 'Так-так... Еще один путник, которому что-то нужно от дворфов... $B$BСтупай своей дорогой добрый господин у меня нет времени на праздную болтовню!', NULL, NULL, 'Амулет Тяжелоступа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (725, 'Слухи об угрозе', '$N, беги, найди советника Белграма как можно скорее. Расскажи ему, что $gвидел:видела:, и спроси, что нам делать дальше. Отдашь ему эту записку, я изложил в ней все как можно подробней. $B$BА я пока побеседую с духом Тяжелоступа. Возможно, ему известно нечто, что сможет помочь нам пресечь безумные действия Тенегорнских прихвостней в Бесплодных землях. Теперь нам остается только молиться.', 'Найдите советника Белграма и отдайте ему записку. ', 'А, весточка от историка Карника. Прекрасно. $B$BДля него у меня всегда найдется минутка.$B$B*Советник Белграм разворачивает записку и погружается в чтение.*', 'Слушаю тебя, $C.', NULL, NULL, 'Запечатанная записка советнику Белграму (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (726, 'Слухи об угрозе', '<Когда советник Белграм дочитывает письмо до конца, его глаза в ужасе расширяются>$B$BЭто дурные вести... $B$BПожалуйста, вернись к историку Карнику и извести его именем короля, что он должен действовать быстро и рассудительно. Он должен остановить Тенегорн в Бесплодных землях.', 'Поговорите с историком Карником. ', 'Ты действуешь по этому делу с поспешностью, которая сделала бы честь и королю, $N! $B$BХорошо. Я знаю, что делать с Кузней Теней. $B$BИх силы в Ульдамане будут рассеяны, если мы поразим их в самое сердце – ударим по крепости Ангор.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (727, 'В Стальгорн за книгой Йагина', 'Эта табличка говорит о многом. И все же этого недостаточно! $B$BЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! $B$BОтправляйся к Геррику Костохвату. Ты найдешь его в лавке в Стальгорне, в Заброшенном гроте. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.', 'Отнесите печать Молота Геррику Костохвату в Заброшенный грот в Стальгорн.', 'О, рад видеть тебя брат.', 'Приветствую! Добро пожаловать в мою лавку, только не трогайте что попало! $B$BЗнание может быть смертельно опасным!', NULL, NULL, 'Печать Молота (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (728, 'В Подгород за книгой Йагина', 'Эта табличка говорит о многом. И все же этого недостаточно! $B$BЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу, и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! $B$BОтправляйся к хранителю Бел\'дугуру в Лордерон. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.', 'Отнесите печать Молота хранителю Бел\'дугуру в Подгород.', 'Будь осторожен, $C. Многие на этом свете сомневаются в праведности наших дел. И многие из них сделали бы все возможное, чтобы уничтожить нас! $B$BТы должен всегда сохранять бдительность, осторожность и терпение...', 'Ага, кто это у нас тут? Жаждущий знаний $C! Пришел взглянуть на мою коллекцию? Милости прошу! $B$BНо помни: во многом знании много печали, и преумножащий знания преумножает скорбь...', NULL, NULL, 'Печать Молота (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (729, 'Рассеянный геолог', 'Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера. В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера.$B$BНо геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего.$B$BМы обнаружили признаки некогда крупного поселения. Из-под земли выскочили ужасные големы и заполонили весь раскоп. Но Сомнамбулер, казалось, так ничего и не заметил. Я побежала обратно в Аубердин за помощью.$B$BПрошу тебя, отправляйся на юг и посмотри, все ли в порядке с геологом!', 'Отправляйтесь на юг, найдите геолога Сомнамбулера и узнайте, как у него дела.', 'Это ты, Холли? Мне нужна помощь, надо подолбить этот камень. Передай-ка мне мою щетку для камня – мне кажется, я тут что-то вижу.$B$BОй, да ты не Холли! Вряд ли ты видел мою щетку для камня...$B$BА, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашел. Куда же делась Холли?$B$BТак много нужно сделать! И где ж эта таинственная окаменелость... и моя щетка... и Холли...$B$BИ ты кто будешь... правда, это неважно, если ты хочешь помочь.$B$BДай знать, когда сможешь начать поиски.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (730, 'Неприятности на Темных берегах?', 'Приятно видеть! $C, $gинтересующийся:интересующаяся великими археологическими чудесами нашего мира!$B$BЧасто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать. Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора.$B$BМеня очень беспокоит судьба группы, которую я отправил на Темные берега. От них уже несколько недель ни слова.$B$BОтправляйся в Аубердин и узнай, где они предположительно могут находиться.', 'Отправьтесь в Аубердин и найдите следы дворфской изыскательской группы.', 'Как же здорово, что главный археолог Седой Ус прислал вас...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (731, 'Рассеянный геолог', 'Итак, Холли... А, да, верно, ты же не Холли. А где Холли?$B$BАй, ладно, это к делу не относится. Мы должны найти эту щетку для камня... то есть я имею в виду таинственную окаменелость! Мы должны найти эту окаменелость. Лига исследователей в Дарнасе захочет узнать, чем я тут занимаюсь.$B$BДай мне знать, когда будешь $gготов:готова:, и начнем поиски этой щетки... ну, то есть окаменелости! Мы найдем какой-нибудь документ, чтобы в Лиге остались довольны.$B$BТак что, $gготов:готова:?', 'Защищайте геолога Сомнамбулера, пока он ищет таинственную окаменелость, а затем вернитесь к археологу Холли в Аубердин.', 'Слава звездам, геолог Сомнамбулер в безопасности! Я же говорила тебе, какой он рассеянный. Не могу поверить, что он твердо хочет остаться там, где рядом повсюду рыщут жуткие твари!', NULL, NULL, NULL, 'Защитите геолога Сомнамбулера.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (732, 'Дрожь земли', 'Сигрун сказал, что ты $gоказал:оказала: ему неоценимую помощь. Возможно, мне она тоже понадобится. Меня прислал сюда мой господин, Красус из Кирин-Тора, чтобы прекратить беспорядки в низине Летлор. $B$BЯ не имею права разглашать поставленные передо мной задачи, но можешь не сомневаться – они имеют самое первостепенное значение.$B$BШайка бродячих огров, которых видели близ лагеря Бофф, украла предмет, именуемый знаком Земли. Мне необходимо вернуть этот предмет. Принеси его мне, и я расскажу тебе больше.', 'Принесите знак земли Гареку.', 'Ты принес знак, $N, – это очень хорошая весть! Знак Земли был создан дворфами Черного Железа из Крепости Ангор, чтобы заключить в узилище двух беспощадных драконов-помощников Смертокрыла – близнецов Бича Тьмы и Гематуса.', 'Шайка бродячих огров кочует от лагеря к лагерю в Бесплодных землях. Пустынный ветер заметает их следы, и их перемещения крайне сложно отследить. Слыхал, их видели недавно близ лагеря Бофф. Попробуй поискать там.', NULL, NULL, 'Знак земли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (733, 'Помогите кто чем может!', 'Да, туго нам придется, если мы не сможем раздобыть материалов для возведения простейших укреплений и других нужд. Заметил я, что у огров в этих землях полно металлолома. Возможно, легенды об осадных машинах, применявшихся в Бесплодных землях, не так уж далеки от истины...$B$BВ общем, геолог очень беспокоится за состояние нашего маленького лагеря, так что надо приниматься за работу как можно скорее. $B$BГлавный лагерь огров расположен рядом с Гротом Гнилобрюхих, к западу отсюда. Учти – расстояние приличное!', 'Принесите 7 кусков металлолома Сигруну. ', 'Спасибо, $N! Думаю, это поможет нам дотянуть до распоряжения из Стальгорна или Лиги Исследователей.$B$BЭх, добыть бы теперь соли для закалки оружия...', 'Ну, мы тут состряпали кое-какое укрепления из подручных материалов, но... Как видишь, наскребли негусто. Удалось добыть что-нибудь?', NULL, NULL, 'Металлолом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (734, 'Сложная задача', 'Пекрасно, прекрасно... $B$B<Лотвиль на секунду отрывает взгляд от кандалов.>$B$BСбегай-ка к Люсьену, $N. Мне нужна шестеренка №5. Принеси ее мне.', 'Поговорите с Люсьеном Подай-Ключ в Бесплодных землях.', 'Зубец #5, значит? Да, добром это не кончится...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (735, 'Звезда, Рука и Сердце', 'Книга Йагина, да? Вы хотите написать в ней новую главу о нас? Ну да, не мне спрашивать.$B$BЯ помогу вам – у меня как раз есть дополнительный экземпляр. Мы ведь должны друг другу помогать, не так ли? Только так мы добьемся успеха.$B$BМне нужны три предмета силы. Принесите их мне – и получите книгу.$B$BНазваний преметов я вам не скажу – нас могут подслушивать. Но я их вам напишу.', 'Доставьте предметы, перечисленные в записке Костохвата, Геррику Костохвату в Стальгорн.', 'На вас можно положиться, $C. Воистину, вам предстоит вписать новую главу в книгу нашего ордена, и я уверен, что это будут славные страницы.', 'Вы принесли то, о чем я вас просил?', NULL, NULL, 'Звезда Ксиль\'и', 'Рука Дагуна', 'Сердце Наследия', 'Записка Костохвата');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (736, 'Звезда, Рука и Сердце', 'Тебе нужна книга Йагина? Планируешь собрать свое стадо? Ну, разумеется... и я с удовольствием помогу тебе, $gбрат:сестра:.$B$BВзамен я также попрошу тебя о помощи.$B$BМне нужны три предмета силы. Принеси их – и книга будет твоей.$B$BНазвать вслух эти предметы я не могу, но запишу их.$B$BДобудь мне все, что я укажу в списке. Если справишься с этим, значит, ты действительно $gдостоин:достойна: начать новую главу в истории нашего ордена.', 'Прочитайте записку Бел\'дугура. Принесите перечисленные в записке предметы Бел\'дугуру в  Подгород.', 'Поразительно! Ты обладаешь или великим искусством, или удачей, иначе тебе не удалось бы добыть эти реликвии. Так или иначе, ты очень помог нам.', 'Как продвигаются дела, $C?', NULL, NULL, 'Звезда Ксиль\'и', 'Рука Дагуна', 'Сердце Наследия', 'Записка Белдугура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (737, 'Запретное знание', 'У меня есть для тебя книга, $N. Думаю, не стоит говорить, что с ней нужно обращаться очень бережно. И непременно держать подальше от рук врагов. $B$BВ этой книге содержится много секретов...$B$BОпасных секретов!', 'Отнесите книгу Йагина Тельдарину.', 'Вот она! О, проблеск надежды! $B$BБыть может, твои труды принесли нам спасение, $N! Тебе нужно поставить памятник! Воздвигнуть святилище! Славить твое имя в сказаниях, пока у детей твоих детей не родятся правнуки! $B$BЕсли только... Если только ОНИ еще не вырвались на свободу. Потому что если это случится, можешь забыть о детях. $B$BЕсли ОНИ вырвались на свободу, мы все пойдем на корм червям.', 'Ну вот и ты! Где пропадал? Принес книгу?', NULL, NULL, 'Книга Йагина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (738, 'Найти Эгмонда', 'Геолог Эгмонд вел раскопки в Бесплодных землях, на юго-западе. Я говорю \"вел\", потому что, к несчастью, от него нет вестей уже не одну неделю. Его нужно найти. $B$BВ последний раз его видели на самом южном раскопе Бесплодных земель – он расположен за Крепостью Ангор. Думаю, стоит начать поиски там.', 'Найдите Эгмонда. ', 'Должно быть, этот скелет принадлежит Эгмонду. Его кости изломаны и выбелены солнцем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (739, 'Мурдалок', 'Следы Эгмонда уводят на запад. Судя по кровавым следам на камнях и песке, дворф полз на коленях. $B$BИ здесь он умер. $B$BПод правой рукой мертвеца еле виднеется слово, нацарапанное на куске песчаника. $B$B\"Мурдалок,\" – гласит надпись.', 'Уничтожьте убийцу Эгмонда, Мурдалока. Убейте 12 костегрызов из племени Каменного Свода. Сообщите геологу Сталекруту в Лок Модане обо всем, что произошло.', 'Это горькая весть, $N! Он был силен и славно управлялся с молотом. Не сомневаюсь, прежде чем он пал от лап троггов, он уничтожил не одну мерзкую тварь.', NULL, NULL, NULL, 'Мурдалок убито', 'Костегрыз из племени Каменного Свода убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (741, 'Рассеянный геолог', 'Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнас? Мне не хотелось бы уезжать с Темных берегов без него.$B$BВот, $N, отвезите эту таинственную окаменелость главному археологу Седоусу в Дарнас.', 'Отвезите таинственную окаменелость главному археологу Седоусу в Дарнас. ', 'Ух ты! Только геолог Сомнамбулер мог сделать такое открытие!', 'Чем могу помочь, $R?', NULL, NULL, 'Таинственная окаменелость (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (742, 'Большая охота', 'Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!$B$BОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – застава Расщепленного Дерева и застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громовое Сердце находится на заставе Расщепленного Дерева, к северу от Степей. Она ждет желающих принять участие в большой охоте!', 'Поговорите с Сенани Громовое Сердце на заставе Расщепленного Дерева в Ясеневом лесу.', 'Добро пожаловать на новое пограничье, Топблэйд. Ясеневый лес – край неограниченных возможностей, где юному $C) вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.$B$BКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (743, 'Соседство со стаей Неистовства Ветра', 'Спасибо, что $gвыбрал:выбрала: время поговорить со мной, $N. Я Руул, воин и учитель.$B$BПришло время пройти испытания и покинуть Мулгор.$B$BЕсли ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги.$B$BЭти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе.', 'Принесите 8 когтей гарпий из стаи Ярости Ветра Руулу Орлиному Когтю в деревню Кровавого Копыта.', 'Молодец, $N. Похоже, ты готов двинуться дальше. Попутного тебе ветра!', 'Гарпии из клана Ярость Ветра – наши смертельные враги. Их ярость в битве сравнится лишь с их жаждой сырой плоти.', NULL, NULL, 'Коготь гарпии из клана Неистовства Ветра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (744, 'Подготовка к церемонии', '$N, вскоре мой брат предстанет перед вождем Кровавым Копытом, и мне выпала большая честь сделать для него головной убор.$B$BМне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски. Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом?$B$BПерья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утеса. Мне нужно всего-то 6 лазурных и 6 бронзовых перьев, чтобы закончить работу.', 'Добудьте 6 лазурных перьев и 6 бронзовых перьев, и принесите их Эйану Орлиному Когтю в Громовой утес.', 'Спасибо за помощь, $N.$B$BМое участие в церемонии в честь моего брата почти закончено. От меня требуется только подарить ему этот убор и быть свидетелем.', 'Этот головной убор станет замечательным подарком моему брату!', NULL, NULL, 'Лазурное перо', 'Бронзовое перо', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (745, 'Недобрые соседи', '$N, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.$B$BГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.$B$BСловами их не остановить.', 'Убейте 10 дубильщиков, 8 шкуродеров и 5 браконьеров из стаи Бледногривов и возвращайтесь к Бейну Кровавому Копыту в деревню Кровавого Копыта.', 'Хорошо, что ты отнесся к моему заданию со всей серьезностью, $N. Очень важно уважать землю и ее обитателей. Жизнь и смерть – это вечный цикл... Необходимость. Одно не может существовать без другого. Обдумай это хорошенько и никогда не забывай.', NULL, NULL, NULL, 'Дубильщик из стаи Бледногривов убито', 'Шкуродер из стаи Бледногривов убито', 'Браконьер из стаи Бледногривов убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (746, 'Дворфийские делишки', 'К северо-западу отсюда дворфы готовятся к раскопкам. Они думают, что тайны скрыты глубоко в земле, и это правда, но у нее надо учиться, а не осквернять бесконечными ямами.$B$BСобери инструменты дворфов, уничтожь их и принеси мне.$B$BЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.', 'Соберите 5 кирок геолога.Сломайте их в кузнице. Отнесите 5 сломанных инструментов Бейну Кровавому Копыту в деревню Кровавого Копыта.', 'Спасибо, $N. Звери Мулгора успокоятся. И, если будет на то воля духов, дворфы познают, что бурение земли – не лучший путь к обретению знаний.', 'Привет, $N. Ты принес сломанные инструменты? Дворфийские раскопки разъяряют мулгорских кодо. Пора положить конец осквернению нашей земли!', NULL, NULL, 'Сломанные инструменты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (747, 'Охота начинается', 'Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утес. Но прежде чем это случится, тебе придется доказать моему отцу, вождю Соколиному Ветру, что ты $Gдостоин:достойна; этой чести. $B$BНа плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты $gспособен:способна:, – поохоться на равнинных долгоногов и принеси мяса в деревню.', 'Принесите 7 перьев равнинных долгоногов и 7 кусков мяса равнинных долгоногов Груллу Соколиному Ветру в Лагерь Нараче.', 'Таурены Нараче благодарят тебя, $N. Я уверен, ты достигнешь больших высот.', 'Добыча пищи и перьев для племени – первый шаг на пути к завоеванию расположения вождя.', NULL, NULL, 'Мясо долгонога', 'Перо долгонога', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (748, 'Отравленная вода', 'Гоблины и их прислужники отравили наши священные колодцы! Это недопустимо.$B$BДля очищения колодцев придется создать тотемы, а ты пойдешь с ними к колодцам и проведешь очищающие ритуалы.$B$BНачнем мы с колодца Заиндевевшего Копыта. Земля сама поможет нам. Принеси мне лапы волков прерий и когти взрослых долгоногов. Эти звери живут на юго-западе.', 'Принесите 6 лап волков прерий и 4 когтя равнинного долгонога Муллу Громовому Рогу в деревню Кровавого Копыта.', 'Молодец, $N. Я вплету силу принесенных тобой вещей в тотем Очищения.', 'Ты несешь лапы и когти, $N?', NULL, NULL, 'Лапа волка прерий', 'Коготь долгонога', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (749, 'Разграбленный караван', 'Несколько дней назад мы наткнулись на охраняемый караван Торговой Компании, следовавший вдоль северного берега озера Каменного Быка. В предыдущей битве мы потеряли двоих, поэтому на сей раз мы напали без промедления и уничтожили караван.$B$BМы бросили их ящики с припасами, полагая, что наши факелы уничтожат все ценное, но учитывая, что возле сожженных телег видели мародеров Торговой Компании, похоже, мы ошиблись.$B$BБыть может, ты сходишь к каравану и посмотришь, что в ящиках?', 'Морин Ловец Облаков попросил вас изучить содержимое ящиков с припасами в разграбленном караване.', 'Все стороны ящика опечатаны знаками рудникового отдела Торговой компании. Сбоку прикреплены пометки, что содержимое должно быть обработано на одном из центральных заводов компании.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (750, 'Охота продолжается', 'Любой искушенный в охоте таурен понимает, что ее смысл не заключается в убийстве любой подвернувшейся добычи. Живущие на равнине звери обеспечивают нас всем необходимым для выживания. Ты произведешь впечатление на старейшин, если принесешь им несколько шкур горных пум – они у нас очень высоко ценятся! $B$BНашим детям нужна одежда, да и шатры пора подлатать.', 'Принесите 10 шкур горных пум Груллу Соколиному Ветру. ', 'Таурены из Нараче благодарят тебя за твои дары, $N. Твое охотничье искусство будет высоко цениться в Громовом Утесе.', 'Если ты сможешь добыть шкуры, я замолвлю о тебе словечко перед отцом, вождем Соколиным Ветром.', NULL, NULL, 'Шкура горной пумы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (751, 'Разграбленный караван', 'Приоткрыв крышку, вы видите плотно упакованную руду и минералы – новое свидетельство деятельности Торговой Компании в Мулгоре. Поверх руды и минералов лежит пачка бумаг.$B$BСо стороны восточных предгорий доносятся звуки работы и к небу поднимается дым от больших костров.', 'Отнесите бумаги Торговой Компании Морину Ловцу Облаков, которого можно найти неподалеку от Деревни Кровавого Копыта.', 'Похоже, Торговая компания в самом деле замыслила лишить нас всех природных ресурсов. Хорошо знать это наверняка, пожалуй, пришло время действовать.', 'Привет тебе, $N. Удалось что-нибудь вызнать о планах Торговой компании и ее деятельности на нашей родине?$B$BЕсли они хотят творить в наших землях то же, что и в других, мы быстро с этим покончим.', NULL, NULL, 'Бумаги Торговой Компании (Прилагается)', 'Исследовать локацию', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (752, 'Скромная просьба', 'Все члены племени живут вместе в мире и гармонии. $B$BМы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой. $B$BМоя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты ее, пока я занимаюсь делами племени?', 'Поищите матушку вождя Соколиный Ветер у источника к юго-востоку от Лагеря Нараче.', 'Ты проделал такой путь, чтобы помочь старушке? Да, похоже ты чтишь традиции нашего народа.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (753, 'Скромная просьба', 'В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я еще могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. $B$BДумаю, ты $gдостойный:достойная:c: $C. Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. $B$BПомни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин.', 'Наберите кувшин воды из колодца.Отнесите кувшин вождю Соколиному Ветру в Лагерь Нараче, который находится к северо-западу от источника.', 'Ты принес мне этот кувшин по просьбе Великой матери Соколиный Ветер. $B$BТвоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придет день, когда мы будем гордиться тобой в Громовом Утесе.', 'Ты вернулся с равнины, как я понимаю? Есть ли вести от Великой матери Соколиный Ветер?', NULL, NULL, 'Кувшин воды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (754, 'Очищение колодца Заиндевевшего Копыта', 'Я создал тотем для очищения Колодца Заиндевевшего Копыта. Отнеси его к колодцу и произведи ритуал очищения. Колодец находится на юго-востоке, и его охраняют мерзкие гоблины!$B$BЗадание непростое, но кому-то придется это сделать, иначе мы не сможем набирать там воду.$B$BУдачи тебе, $N.', 'Очистите колодец Заиндевевшего Копыта с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.', 'До меня только что дошли вести о твоем деянии – звери уже спешат к колодцу на водопой.$B$BТы оказал большую услугу нашему краю, $N. И всему народу тауренов.', 'Не мешкай, $N. Мы должны очистить колодец Заиндевевшего Копыта от скверны!', NULL, NULL, 'Очистите Колодец Заиндевевшего Копыта.', 'Тотем очищения колодца Заиндевевшего Копыта', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (755, 'Обряды Матери-Земли', 'Твоя готовность выполнить скро$Nю просьбу таурена из Нараче и твое желание обрести новые знания весьма похвальны, $N. Не сомневаюсь, придет день, и тебя, $C, назовут $gодним:одной: из величайших. $B$BНо сначала ты $gдолжен:должна: пройти три обряда Матери-Земли. $B$BПервым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер. $B$BОбиталище провидца сокрыто в холмах к югу от Лагеря Нараче.', 'Отправьтесь к провидцу Серой Пасти, который живет к югу от Лагеря Нараче.', 'Тебя прислал вождь Соколиный Ветер? Обряды Матери-Земли гораздо сложнее, чем кажутся на первый взгляд...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (756, 'Тотем Громового Рога', 'Для создания Тотема очищения колодца Громового Рога тебе понадобятся когти хищников мулгорских равнин. Придется тебе убить несколько охотников прерий и пум плоскогорья, живущих на востоке и на западе, и принести мне их когти.', 'Принесите 6 когтей охотников прерий и 6 когтей пум плоскогорья Муллу Громовому Рогу.', 'Спасибо, $N. Чтобы создать следующий очищающий тотем, тебе придется постичь, в чем разница между убийством ради пропитания и бессмысленной жестокостью.$B$BГоблинам же не дано понять разницу между захватом земли и жизнью в гармонии с ней.', 'Ну как, ты добыл когти, как я велел? С каждым часом Колодец Громового Рога загрязняется все больше!', NULL, NULL, 'Когти охотника прерий', 'Когти пумы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (757, 'Обряд Силы', 'Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утеса.$B$BСначала ты $gдолжен:должна: пройти обряд Силы. Чтобы выдержать это испытание, ты $gдолжен:должна: доказать свою храбрость, убивая врагов племени. $B$BВоины племени Дыбогривов из Ежевичной лощины вторгаются в земли нашего племени. Они нападают на наших охотников и грабят деревню по ночам. $B$BПокажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства.', 'Убивайте дыбогривов в Ежевичной лощине и принесите 8 их поясов вождю Соколиному Ветру в Лагерь Нараче.', 'Ты прошел первый из обрядов Матери-Земли. Племя гордится тобой!', 'Ты прошел обряд Силы, $N? Покажи мне доказательства твоей доблести, проявленной в войне против нашего врага – клана Вздыбленной Щетины.', NULL, NULL, 'Пояс племени Дыбогривов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (758, 'Очищение колодца Громового Рога', 'Тотем готов, $N. Остается лишь провести ритуал очищения.$B$BСтупай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью Тотема очищения колодца Громового Рога. После этого возвращайся ко мне.$B$BИ да пребудут с тобой духи.', 'Очистите колодец Громового Рога на севере от деревни с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.', 'Предки клана Громового Рога явились ко мне во сне и восхваляли тебя за очищение их колодца.$B$BОни просили передать тебе это в знак признательности…', NULL, NULL, NULL, 'Очистите колодец Громового Рога.', 'Тотем очищения колодца Громового Рога', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (759, 'Тотем Буйногривых', 'Тебе осталось очистить лишь один колодец, названный в честь племени Буйногривых. Для этого тебе понадобятся зубы лютого хищника, могучего волка прерий. Ступай на север, убей его и возвращайся.$B$BМогучие волки прерий водятся неподалеку от славного города Громового Утеса.', 'Отнесите 8 зубов могучего волка прерий Муллу Громовому Рогу в Деревню Кровавого Копыта.', 'Замечательно, $N. Увы, нашей земле приходится приносить в жертву своих детей, и я исполняюсь печали и гордости.', '$N. Несешь ли ты зубы волков?', NULL, NULL, 'Зуб могучего волка прерий', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (760, 'Очищение колодца Буйногривых', 'Духи говорят о твоих успехах в деле очищения колодцев племен Заиндевевшего Копыта и Громового Рога, $gюный:юная:c: $C. Тотем Буйногривых готов, и ты можешь приступить к выполнению задания.$B$BКолодец Буйногривых расположен на севере от Громового Утеса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой!', 'Очистите колодец Буйногривых с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.', 'Ты справился! Наши колодцы снова чисты, а земля исцелена. Деревня Кровавого Копыта признательна тебе, $N.$B$BПусть ветер шепчет о твоих подвигах сотни лет, а воды Мулгора остаются чистыми навек.', 'Последний колодец все еще отравлен, $N. Не мешкай!', NULL, NULL, 'Очистите колодец Буйногривых.', 'Тотем очищения колодца Буйногривых', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (761, 'Охота на перепелятников', 'Перепелятники – хитрые птицы. Их нелегко найти и убить. Связка перьев перепелятника – все равно что медаль для охотника, говорящая о его уме и решимости.$B$BЕсли ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников. $B$BПринеси мне их перья, и прославь свой клан этой победой.$B$BПерепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта.', 'Принесите 8 трофейных перьев перепелятника Харкену Тотему Ветра в Деревне Кровавого Копыта.', 'Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты показал, на что способен. Хорошо, что ты живешь у нас в деревне.', 'Ну как, нашел перепелятников? А где их перья?', NULL, NULL, 'Трофейное перо перепелятника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (762, 'Посланник зла', 'Посол Инфернус был отправлен в Крепость Ангор самим Рагнаросом, чтобы надзирать за поисками потерянных артефактов Тенегорна в Ульдамане. $B$BНам и без того было непросто, а теперь я даже боюсь предположить, сколько артефактов они смогут найти и использовать против Стальгорна! $B$BЗадача проста, $N! Возвращайся в Бесплодные земли и уничтожь посла Инфернуса. Как только ты выполнишь это задание, возвращайся к советнику Белграму с доказательством своего успеха. $B$BТеперь все в твоих руках!', 'Убейте посла Инфернуса в Крепости Ангор и принесите доказательство его смерти советнику Белграму в Стальгорн.', '$N, твоя преданность Стальгорну и народу дворфов не будет забыта. Благодарю тебя за помощь. $B$BЯ извещу историка Карника о твоих успехах письмом и отправлю рабочих в Бесплодные земли, чтобы они возобновили работы на раскопках как можно скорее. Еще раз благодарю тебя. $B$BПрежде чем ты уйдешь, выполни еще одну просьбу от имени короля Бронзоборода.', 'Время дорого, $N! Рагнарос не будет ждать, когда мы подготовимся.', NULL, NULL, 'Наруч посла Инфернуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (763, 'Обряды Матери-Земли', 'Чтобы продолжить прохождение обрядов Матери-Земли, ты $gдолжен:должна: выдержать еще два испытания. Тебе бы не помешало поднабраться опыта, $N.$B$BОтправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. $B$BОтнеси этот тотем Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.$B$BСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!', 'Отнесите тотем Соколиного Ветра Бейну Кровавому Копыту в Деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.', 'О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты $R особой породы!', 'Что привело тебя в мою деревню, $C?', NULL, NULL, 'Тотем Ястребиного Ветра (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (764, 'Торговая Компания', 'Теперь понятно, почему в Мулгоре появилось много сотрудников и оборудования Торговой Компании. Эти гоблины... Компания слишком быстро растет, не жди добра. Как говорят, гоблинам палец в рот не клади.$B$BМаленькие жадины. К несчастью для их деловых операций, таурены не согласны терпеть их присутствие в своих землях. Ступай в их рудник на северо-востоке от разграбленного каравана и преподай им урок.', 'Убейте 14 рабочих Торговой Компании и 6 бригадиров Торговой Компании по поручению Морина Ловца Облаков из Деревни Кровавого Копыта.', 'Думаю, такой намек невозможно не понять, а? Торговая компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые.', NULL, NULL, NULL, 'Рабочий Торговой Компании убито', 'Бригадир Торговой Компании убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (765, 'Бригадир Шумовик', 'Согласно документам, которые ты $gотыскал:отыскала: в караване, Торговая Компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить.$B$BМне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы. Его зовут бригадир Шумовик, он сейчас в руднике Торговой Компании на востоке от разграбленного каравана. Принеси мне его планшет, посмотрим, нет ли в нем чего полезного.', 'Убейте бригадира Шумовика и принесите его планшет Морину Ловцу Облаков в Деревню Кровавого Копыта.', 'Ярость немного отступила при вести о гибели злодея Шумовика. Я пороюсь в его личных вещах, посмотрю, нет ли там дополнительных сведений о ближайших планах Торговой компании. Спасибо за помощь, $N.', 'Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая компания во имя прибыли.', NULL, NULL, 'Планшет Шумовика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (766, 'Маззранач', 'Дедушка рассказывал мне истории о столкновениях с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах.$B$BИ вот ирония судьбы – он встретился мне во время странствий по равнинам и здорово укусил меня за плечо. Мой дед ничуть не преувеличил, описывая это жуткое создание. Теперь мне нужны редкие части животных, чтобы вылечить воспаленную рану: сердце койота, бедро пумы, чешуя равнинного долгонога и потроха перепелятника.$B$BТоропись, время не ждет.', 'Принесите сердце койота, бедренную кость пумы плоскогорья, чешую долгонога и потроха перепелятника Мауру Заклинателю Дождя в деревню Кровавого Копыта.', 'А, спасибо. Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня. Я обязан тебе жизнью.$B$BНо пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть…$B$BБудь осторожен во время своих странствий.', 'Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…$B$BТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.', NULL, NULL, 'Сердце волка прерий', 'Бедренная кость пумы плоскогорья', 'Чешуя долгонога', 'Потроха перепелятника');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (767, 'Обряд прозрения', 'Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утеса.$B$BНаш народ твердо усвоил, что кормящая нас земля – священна. Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождем деревни, Зарельманом Две Луны.', 'Поговорите с Зарельманом Две Луны в Деревне Кровавого Копыта.', 'Я предчувствовал, что ты придешь ко мне, $С. Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (768, 'Добывание шкур', 'Привет тебе, $gюноша:девица:. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесешь ты честь своему клану!$B$BЯ работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утеса.$B$BЕсли принесешь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью.', 'Принесите 12 кусков тонкой кожи Верену Долгоногу в Громовой Утес.', 'Ах, какая кожа! Из нее выйдут отличные товары.$B$BВот, $N. Возьми в знак благодарности...', 'Добро пожаловать еще раз! Поохотился? У тебя есть для меня кожа?', NULL, NULL, 'Тонкая кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (769, 'Сумка из шкуры кодо', 'Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем. Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы.$B$BИ тогда я поделюсь с тобой своими знаниями.', 'Принесите 4 куска легкой кожи и 4 мотка грубой нити Верену Высокому Страннику в Громовой Утес.', 'Добро. Спасибо, Мизерия. Мое сердце распирает от гордости, когда я вижу молодежь, взыскующую мастерства в кожевничестве!', 'Принесла мои припасы, $N?', NULL, NULL, 'Тонкая кожа', 'Грубая нить', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (770, 'Поцарапанный демоном плащ', 'На потрепанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом.$B$BМожет быть, следует рассказать кому-нибудь в Деревне Кровавого Копыта о кончине Призрачного Воя...', 'Отыщите кого-нибудь, кто слышал о Призрачном Вое. ', 'Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты вырос в моих глазах, юный $С. Оказывается, ты превосходный охотник!$B$BПозволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь мое оружие.$B$BПусть оно не знает промаха и дарует тебе славу.$B$BБудем надеяться, что дух Призрачного Воя упокоился с миром.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (771, 'Обряд прозрения', 'Чтобы пройти обряд Прозрения, тебе придется собрать некоторые реагенты для создания воды Провидцев.$B$BМне понадобятся камни, которых полно вокруг источников Мулгора. Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли.$B$BВ этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение. Следуй за ним, и оно приведет тебя к следующему этапу священного обряда.', 'Принесите 2 камня, лежащих у источника, и 2 янтарных семени Зарельману Две Луны в Деревню Кровавого Копыта.', 'Вижу, ты научился собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев.', 'Когда ты принесешь мне довольно камней и янтарного семени, я сделаю для тебя воду Провидцев.', NULL, NULL, 'Камень у источника', 'Янтарное семя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (772, 'Обряд прозрения', 'Я вручаю тебе воду Провидцев.$B$BВыпей ее перед костром племени. Когда священные воды вольются в тебя, из огня навстречу тебе шагнет видение.$B$BПосле этого следуй за ним навстречу своей судьбе...', 'Выпейте воду Провидцев перед костром племени в Деревне Кровавого Копыта и следуйте за видением.', 'Не бойся, $N. Ты успешно прошел Обряд прозрения.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (773, 'Обряд мудрости', 'Чтобы завоевать признание старейшин Громового Утеса, тебе следует пройти Обряд мудрости.$B$BТы уже $gпрошел:прошла: Обряд прозрения, и духи Красных скал благословят тебя силой предков. Лишь те, кто испили воды Провидцев, могут обрести это благословение.$B$BСтупай на восток от Громового Утеса, к Красным скалам, и отыщи там дух предков.', 'Отправляйтесь в Красные Скалы на востоке от Громового Утеса и поговорите с духом предков.', 'Ты приложил много стараний, чтобы пройти обряды Матери-Земли, $N.$B$BМы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утес. Итак, я передаю тебе почетную обязанность хранить его от бед.$B$BТы прошел Обряд мудрости, юный $C. Отныне ты можешь с гордостью войти в Громовой Утес.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (775, 'Путешествие в Громовой Утес', 'Отныне тебя будут почитать в стенах нашего великого города. $gПрошедший:Прошедшая: обряды Матери-Земли заслуживает такой чести.$B$BВыполни последнее задание, отыщи благородного вождя Кэрна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.', 'Поговорите с Кэрном Кровавым Копытом в Громовом Утесе.', 'Привет тебе, юный $С. Вижу, тебе удалось отыскать дорогу ко мне.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (776, 'Обряды Матери-Земли', 'Ты $gпрошел:прошла: обряды Матери-Земли и $gзаслужил:заслужила: достойное место среди жителей Громового Утеса.$B$BЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.$B$BМы охотники, $N. Внизу, в Мулгоре, есть могучий кодо по имени Арра\'чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра\'чеи.', 'Кэрн Кровавое Копыто из Громового Утеса попросил принести ему рог Арра\'чеи.', 'Отлично! Добрая охота.$B$BЯ пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо.$B$BТы оказал своему народу услугу.', 'Ты уже выследил Арра\'чею?', NULL, NULL, 'Рог Арра\'чеи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (777, 'Сложная задача', 'Ну, теперь за дело! $B$BЯ буду здесь...в укрытии. $B$BЕсли хочешь, можешь присоединиться.', 'Принесите шестеренку №5 Лотвилю Вериатусу. ', 'Ага, прекрасно! Отойди-ка в сторонку и наблюдай, как вершится история! *Лотвил вновь погружается в работу.*', '*Не отрывая взгляд от кандалов, Лотвил нетерпеливо протягивает руку.* $B$BНу? Давай сюда зубец!', NULL, NULL, 'Зубец #5 (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (778, 'Сложная задача', 'Ха! Сделано! $B$BЛюсьен, Серво, время пришло! $B$BТы $gготов:готова: стать $gсвидетелем:свидетельницей: запуска в эксплуатацию совершенной смеси алхимии, инженерной науки и древних тайн, $N? $B$BСейчас я призову могущественного элементаля. Это величайший день для всех нас!', 'Победите стража Фам\'ретора и верните оковы стихий Лотвилю Вериатусу.', 'Спасибо, $N! Ну и денек! $B$BНе думал я, что так получится. Хорошо, что с помощью магии мне удалось загнать тварь туда, откуда она появилась...$B$BВот, это миллионная доля моей благодарности...', 'Да... Не совсем тот результат, на который я рассчитывал... Не вернешь ли ты теперь мне оковы?', NULL, NULL, 'Оковы стихий Лотвиля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (779, 'Печать земли', '', '', 'Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась.', NULL, NULL, NULL, 'Алмазный рунический камень', 'Опаловый рунический камень', 'Аметистовый рунический камень', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (780, 'Боевые вепри', 'Боевые вепри из Ежевичной лощины, что к востоку отсюда, вторгаются в охотничьи угодья нашего племени. Их натаскивают свинобразы из племени Дыбогривов, наши заклятые враги. $B$BПойди и покажи гнусным тварям, кто хозяин в этих землях! Мы сварим из их боков и рыл славную похлебку для наших детишек!', 'Принесите 8 боков и 8 рыл боевых вепрей Груллу Соколиному Ветру.', 'Прекрасно! Мы сварим отличную похлебку, а для проклятых дыбогривов потеря нескольких боевых вепрей послужит уроком.', 'То, что боевые вепри творят в наших землях, уже переходит всякие границы. Сумел ли ты приструнить этих зверей? А бока и рыла принес?', NULL, NULL, 'Рыло боевого вепря', 'Бок боевого вепря', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (782, 'Разорванные союзы', 'От союзника Орды времен Второй войны, дракона Смертокрыла мы знаем, что два его лейтенанта, Чернохлыст и Гематус, были заточены в долине Летлор. Чтобы отстоять честь Орды и не допустить предательства, мы должны заставить замолчать наших растленных бывших союзников! $B$BМы наняли То\'груна и его шайку огров-наемников, чтобы они помогли нам получить знак земли – ключ, необходимый, чтобы открыть драконье узилище. Но То\'грун предал нас, забрав знак себе. Отправляйся в лагерь Бофф и отбери знак!', 'Убейте главаря То\'груна и принесите знак земли Горну в Каргат. ', 'Теперь, когда от То\'груна остался лишь голый скелет, обглоданный стервятниками и выбеленный солнцем и ветром, огры, лишенные главаря, рассеются по пустыне. Так малая победа принесла с собой великую! $B$BЗнак Земли снова у нас, и мы сможем отомкнуть узилище черных драконов в долине Летлор. Мы спасем их от уготованного им вечного заключения, хотя и свершим их судьбу!', 'Предательство То\'груна... Неудивительно, что огры больше не в Орде. Более всего на свете я желаю их смерти и возвращения знака Земли! $B$BЕсли ты еще не расправился с их шайкой, поспеши в лагерь Бофф. Он расположен к юго-востоку от Каргата.', NULL, NULL, 'Знак земли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (783, 'Внутренняя угроза', 'Надеюсь, ты $gготов:готова: к подвигам, $C, поскольку для тебя есть дело здесь, в Североземье.$B$BИ я имею в виду не мирные сельские заботы.$B$BСтража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится. И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких.$B$BЕсли ты $gготов:готова: откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он здесь, в аббатстве у меня за спиной.', 'Поговорите с маршалом Макбрайдом. ', 'Отлично. Еще один доброволец. В эти дни у нас много таких, как ты.$B$BНадеюсь, нам хватит бойцов.$B$BЗемлям людей угрожают внешние враги, потому большая часть наших сил направлена к рубежам. И из-за этого бандитские шайки вольготно чувствуют себя в наших землях.$B$BНам приходится воевать на много фронтов... Готовьтся к долгой войне, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (784, 'Бей предателей!', 'Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда.$B$BВторжение людей удалось отбить, крепость Тирагард пала. Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность! Эти люди совершенно не чтут договоров!$B$BПокажи свою доблесть, $N. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей.', 'Убейте 10 моряков Кул-Тираса, 8 стражей бухты Кул-Тираса и лейтенанта Бенедикта и возвращайтесь к Га\'Току на Колючий Холм.', 'Твоя отвага скоро станет известна всем, $C! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара.', 'Ты слышал приказ, $N. Речь идет о безопасности Дуротара! Выполняй свою задачу – либо уходи с позором.$B$BПокажи свою доблесть, выбей людей из крепости Тирагард!', NULL, NULL, 'Моряк Кул-Тираса убито', 'Страж бухты Кул-Тираса убито', 'Лейтенант Бенедикт убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (785, 'Стратегический союз', 'Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани.$B$BТролли из племени Черного Копья оказались бесценными союзниками для всего орочьего рода. И мы, из верности и чести, заключили с ними договор о взаимной обороне.$B$BИ вот вождь приказал удостовериться, что нашим друзьям в деревне Сен\'джин ничто не угрожает. Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы.$B$BРазыщи Лара и спроси, не нужна ли ему помощь.', 'Разыщите Лара Ночного Клыка на западной окраине деревни Сен\'джин.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (786, 'Предотвращение агрессии племени Колкар', 'Говори потише, $C! Кентавры из племени Колкар совсем близко, вон там, к западу от Утеса Колкара.$B$BПрошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!$B$BНельзя допустить, чтобы они это сделали! Достаточно ли ты $gхрабр:храбра:, чтобы напасть на Утес Колкар и уничтожить их планы?$B$BЯ заметил, что они хранятся у трех лидеров кентавров.', 'Лар Ночной Клык из деревни Сен\'джин хочет, чтобы вы уничтожили 3 плана нападения, которые хранятся в лагере кентавров, что на Утесе Колкар.', 'Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть. Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь.$B$BА кровопролитий в эти смутные времена и без того хватает.$B$BТы хорошо послужил своему народу, $C.', 'Кентавры постоянно изводят Орду своими набегами. Они намерены взять нашу родину в осаду! Этого нельзя допустить!', NULL, NULL, 'План нападения на долину Испытаний уничтожен', 'План нападения на деревню Сен\'джин уничтожен', 'План нападения на Оргриммар уничтожен', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (787, 'Новая Орда', 'Тром\'ка, $C! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов.$B$BОрда уже не такая, как раньше. Некогда я оставил ее: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся.$B$BГорнек скажет тебе, что делать дальше.', 'Зайти в Логово к Горнеку. ', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (788, 'Кабаньи клыки', 'Вот тебе первое поручение, чтобы ты $gнабрался:набралась: опыта и $gпоказал:показала: себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему.$B$BПожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда.', 'Убейте 8 пятнистых вепрей и вернитесь в Логово к Горнеку. ', 'Ну что ж, $N, неплохо. Но не задирай носа: грядут бои с куда более серьезными врагами.$B$BОднако ты показал себя достойным бойцом. В следующем испытании тебе придется встретиться с более опасным противником, так что дополнительная защита не помешает.', 'Не рано ли ты вернулся, а, $N? Надеюсь, ты не будешь уверять, будто выполнил все, что тебе было поручено?', NULL, NULL, 'Пятнистый вепрь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (789, 'Жала скорпидов', 'Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков. К северо-западу отсюда водится множество этих членистоногих. Принеси мне восемь их хвостов, чтобы доказать свою воинскую доблесть.$B$BИз яда жал скорпионов можно изготовить противоядие. Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя...$B$BНо тебе-то оно не понадобится, а?', 'Добудьте 8 хвостов рабочих скорпидов и принесите их в Логово Горнеку.', 'Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним! В бою победа или поражение зависят от многого.$B$BНу что ж, $N! Я научил тебя всему, чему мог. Ты оказался хорошим учеником. Я буду с интересом следить за твоей карьерой.', 'У скорпиона панцирь прочный, но не настолько, чтобы сильный воин не сумел его пробить. Пусть рука твоя будет тверда, и душа не знает сомнений – тогда скорпионы окажутся легкой добычей!', NULL, NULL, 'Хвост рабочего скорпида', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (790, 'Саркот', '$C! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу.$B$BА вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда...', 'Убейте Саркота и принесите его коготь Хана\'зуа. ', 'Да, убить его мне не удалось, но ранил я его серьезно. Пожалуй, мне есть чем гордиться. И это единственное, что утешает меня перед смертью. Как подумаю, как мало я сделал в жизни, такая злость берет!', 'Ох... Отец мой говаривал, что толку из меня не выйдет, и вот лежу я под деревом, помираю и думаю: прав был папаня…$B$BНо я хочу умереть, зная, что последний из моих врагов тоже мертв!', NULL, NULL, 'Уродливый коготь Саркота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (791, 'Больше сумок – больше добычи!', 'Старость сделала меня бесполезным в бою. Теперь я служу Орде иным путем.$B$BЯ сижу здесь, на вышине, и смотрю, не появятся ли враги. Но по мере того, как наши силы растут, мне все реже и реже приходится трубить в сигнальный рог.$B$BА чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину.$B$BЯ могу сделать тебе сумку для пожитков. Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров.', 'Принесите 8 лоскутов холста Фурлу Хмурому Лбу, стоящему на сторожевой башне рядом с Колючим Холмом.', 'Отлично, $N! Такая сумка пригодится любому хорошему бойцу.$B$BЯ отдаю честь твоей силе и решимости умереть во имя Орды!', 'Когда мы заселяли эти земли, я гордо сражался плечом к плечу с вождем. Все мое тело покрыто шрамами.$B$BЯ отстаивал честь Орды своим боевым топором в день победы над Архимондом, когда по необходимости был заключен нечестивый союз с людьми и эльфами.$B$BНо моя должность стража открыла мне новый взгляд на вещи.', NULL, NULL, 'Лоскуты холста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (792, 'Злобные фамильяры', 'Что ж, $C, надеюсь, у нас ты многому научишься.$B$BМеня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не все ладно!$B$BВ долине Испытаний обосновался клан Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос.$B$BИтак, вот твое первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне.', 'Убейте 8 злобных фамильяров и вернитесь к Зурите Востроглазой, которая ждет вас у Логова.', 'Молодец, $N!$B$BДа, злобные фамильяры для злодеев из Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предрекает великие события!', NULL, NULL, NULL, 'Злобный фамилиар убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (793, 'Разорванные союзы', 'Печать земли удерживают три рунных камня, сокрытые в долине Летлор. Один спрятан в алмазном столпе, другой – в опаловом, третий – в аметистовом. С помощью знака земли ты сможешь извлечь рунные камни и разрушить печать земли. $B$BНо будь $gосторожен:осторожна:, $N, Чернохлыст и Гематус очень опасны. Ты $gдолжен:должна: убить их и принести мне их наручники. $B$BДолина расположена к востоку от Бесплодных земель. Не теряй бдительности – в низине множество драконов!', 'С помощью знака земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. Поместите рунные камни на печать земли и освободите драконов Чернохлыста и Гематуса. Убейте драконов и принесите Горну наручники Чернохлыста, цепи Гематуса и знак земли.', 'Черные драконы вступают в союз с отступниками – орками Черной Горы. И тех, и других должно вернуть в лоно Орды или уничтожить. Теперь, когда мы покончили с Гематусом и Чернохлыстом, мы можем обратить взор на запад, на пик Черной Горы.', 'Немногие создания сравнятся по мощи и хитрости с драконами, и немногие драконы сравнятся по свирепости с Чернохлыстом и Гематусом.', NULL, NULL, 'Наручники Чернохлыста', 'Цепи Гематуса', 'Знак земли (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (794, 'Медальон клана Пылающего Клинка', 'С помощью ворожбы я узнала, что в глубине грота Пылающего Клинка находится мощный магический предмет. Его стерегут звери и черная магия.$B$BЭтот предмет – медальон клана Пылающего Клинка. Твоя очередная задача – найти его и отнять у ковена.$B$BНо берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамилиары, с которыми тебе уже доводилось встречаться!$B$BСтупай, $N. Грот находится к северо-западу отсюда.', 'Принесите медальон клана Пылающего Клинка Зурите Востроглазой, стоящей у Логова.', 'Он у тебя! Молодец!$B$BТеперь у нас есть возможность вытеснить приспешников Пылающего Клинка из долины Испытаний. Но, боюсь, этот грот – не единственный их оплот в наших землях.$B$BТак что эта встреча с ними была не последней.', 'Ну что, $N, задание выполнено? Удалось ли тебе раздобыть медальон Пылающего Клинка?', NULL, NULL, 'Медальон клана Пылающего Клинка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (795, 'Печать земли', '', '', 'Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась.', NULL, NULL, NULL, 'Алмазный рунический камень', 'Опаловый рунический камень', 'Аметистовый рунический камень', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (804, 'Саркот', 'То, что ты $gсделал:сделала: ради меня, заставило меня воспрянуть духом. Я еще повоюю!$B$BНо пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, $N, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь.', 'Расскажите Горнеку о том, что Хана\'зуа в беде.', 'Судя по твоему описанию, этим скорпионом был не кто иной, как Саркот! Неудивительно, что Хана\'зуа с ним не справился. Не тревожься о нем, помощь уже в пути.$B$BОднако, нужно сказать, я тебя зауважал. Неужели тебе действительно удалось одолеть Саркота? Это немалый подвиг, $N, тебе есть чем гордиться. А твоя готовность сражаться по просьбе незнакомца тем более делает тебе честь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (805, 'Деревня Сен\'джин', 'Твои испытания в борьбе с кланом Пылающего Клинка подошли к концу... по крайней мере тут, в нашей долине. Но я прошу тебя отнести известие о том, что ты теперь знаешь.$B$BСтупай в тролльскую деревню Сен\'джин, отыщи там мастера Гадрина. Отправляйся на восток, на развилке поверни направо.$B$BРасскажи Гадрину о чернокнижниках из клана Пылающего Клинка и о том, что они уже проникли в долину Испытаний. Узнай, не видно ли их в Сен\'джине.$B$BСтупай, $N, и не медли в пути! Боюсь, появление клана Пылающего Клинка в долине – это только первая ласточка...', 'Поговорите с мастером Гадрином в деревне Сен\'джин. ', 'Хм... Как это все не вовремя! Нет, у нас в Сен\'джине Пылающего Клинка пока не видно, однако на побережье, на островах Эхо, обосновалось иное зло.$B$BОрки – друзья троллей Черного Копья. Верные друзья. Мы хотели бы помочь оркам, но... сейчас нам самим нужна помощь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (806, 'Сгущаются черные тучи', 'Нельзя допустить, чтобы Пылающий Клинок закрепился в Дуротаре! Нужно уничтожить этих чернокнижников, прежде чем распространяемое ими зло расползется по нашей земле!$B$BЯ провел расследование и выяснил, что один из чернокнижников из клана Пылающего Клинка, гоблин по имени Пшикс Черношквал, обосновался на Громовом хребте к северо-западу отсюда. Там он и его приспешники сеют хаос!$B$BНайди Пшикса, убей его и принеси мне его коготь в в качестве доказательства.', 'Принесите коготь Пшикса Оргнилу Душегрызу из Колючего Холма.', 'Ага! Ты его убил!$B$BТвой клан может гордиться тобой, $N. Благодаря тебе в Дуротаре стало одним приспешником зла меньше.', 'Ну что, $N, удалось тебе найти Пшикса? Он и ему подобные должны быть изгнаны из наших земель!', NULL, NULL, 'Коготь Пшикса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (808, 'Череп Миншины', 'Я слышу голос моего брата, Миншины. Он взывает ко мне из снов.$B$BЕго захватил в плен Залазан, чернокнижник с островов Эха на востоке. И теперь Миншина мертв.$B$BНо смерть не принесла ему свободы! Залазан заточил дух Миншины внутри его собственного черепа. В снах я вижу его рядом с другими черепами, в магическом кругу на самом большом из островов Эха. Пока его душа находится в этом месте, она обречена на вечные страдания.$B$BПрошу тебя, $N, отыщи этот круг и похить череп Миншины. Принеси его мне.$B$BОсвободи его!', 'Украдите череп Миншины из магического круга на островах Эха.Принесите его мастеру Гадрину в деревне Сен\'джин.', 'Спасибо, $N! Тебе удалось спасти Миншину! Дух моего брата избавлен от рабства!', 'Ну что, $N, череп моего брата у тебя? Он наконец свободен?', NULL, NULL, 'Череп Миншины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (809, 'Ак\'Зелот', 'Со времен последней великой войны, когда Пылающий Легион потерпел поражение,  я ищу источники демонической порчи, что воздействует на общество орков. И принесенный тобой ошейник подтверждает мои опасения!$B$BОн принадлежит Пылающему Клинку, культу, объединенному вокруг предмета, который наделен демонической силой. Этот предмет называется демоново семя, и находится он в Степях, на вершине Багрового Тумана. Его необходимо уничтожить!$B$BОтправляйся на Дальнюю заставу на границе Степей, к западу, и поговори с моим помощником, Ак\'Зелотом. Он скажет тебе, что делать дальше.', 'Поговорите с Ак\'Зелотом в Степях.', 'Вот как? Нииру хочет, чтобы Демоново семя было уничтожено? Странно…$B$BЧто ж, хорошо. Если такова его воля, я расскажу тебе, как уничтожить семя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (812, 'Нужда в исцелении', 'А, $N... Ты как нельзя вовремя! Надеюсь на твое проворство.$B$BЯ сражался с несколькими ядохвостами, и один из них смог меня ужалить. Я чувствую, как слабею с каждой секундой... Боюсь, мне осталось не больше часа. Мне срочно нужна твоя помощь!$B$BКоргхан из Оргриммара умеет изготовлять противоядие. Найди его... Быстрее, $N! Долго мне не протянуть. Ищи его в расселине Теней.', 'Найдите в Оргриммаре Кор\'гхана и добудьте сыворотку от яда ядохвоста. Принесите сыворотку Ринагу на северо-западной границе Дуротара.', 'Ты спас мне жизнь, $N! Спасибо тебе. $B$BПрошу тебя, возьми эту вещь. Денег за нее не выручишь, но, надеюсь, она пригодится тебе в странствиях. Судя по тому, что ты говоришь, мне она пригодится нескоро. Кор\'гхан подвергнет меня еще множеству своих ритуалов, пока я не сумею показать, на что способен. Снова охотиться на вепрей, собирать хвосты скорпидов... *вздыхает*', 'Я даже рад, что не могу сейчас вернуться в Сен\'джин. Все смеялись бы над моей слабостью и глупостью!', NULL, NULL, 'Сыворотка от яда ядохвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (813, 'Поиски противоядия', 'Ядохвосты – одни из опаснейших скорпидов в Дуротаре! Со стороны Ринага было очень глупо охотиться на них, не имея при себе противоядия. Впрочем, сейчас его вразумлять уже поздно.$B$BПринеси мне несколько ядовитых желез ядохвоста от любых ядохвостов, каких найдешь у входа в Оргриммар, и я сделаю ему противоядие.$B$BТоропись, $N! Одному из наших нужна твоя помощь!', 'Принесите 4 ядовитых железы ядохвоста Кор\'гхану в Оргриммаре.', 'Вот противоядие, $N. Отнеси его поскорее Ринагу, да смотри, осторожнее!', 'Не забывай, если ты на какую-то тварь охотишься, первым делом надо как следует изучить ее повадки! Это может спасти тебе жизнь.', NULL, NULL, 'Ядовитая железа ядохвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (815, 'Хорошенький омлет', 'Ба! А я и позабыл, что надо готовить завтрак.$B$BСлушай, $N, сбегай-ка, раздобудь мне по-быстрому несколько яиц кнутохвостов, как минимум три штуки.$B$BИмей в виду, кровопалые кнутохвосты – твари свирепые и вполне могут убить, защищая свою кладку. Иногда они зарывают яйца слишком глубоко, чтобы их можно было беспрепятственно раздобыть, но если ты отправишься на острова Эха, к юго-востоку от деревни Сен\'джин, там эти яйца лежат повсюду.', 'Принесите 3 яйца кнутохвостов повару Торке в Колючий Холм.', 'Ну, может, ты и слабак но уж ловкости и проворства тебе не занимать, $N!$B$BНа вот, возьми за труды и проваливай. Мне готовить надо!', 'Завтрак, обед, ужин! Какая, в сущности, разница? Все равно кто-то должен готовить еду, и этот кто-то – я!', NULL, NULL, 'Яйцо кнутохвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (816, 'Пропавший, но не забытый', 'Прошу тебя, $N, может, хоть ты сумеешь мне помочь? Мой сын, Крон, несколько дней тому назад отправился на охоту и до сих пор не вернулся! Он ушел на запад, в Степи, охотиться на кроколисков у реки Строптивой. Я опасаюсь худшего…$B$BКрон могуч, но гордость и упрямство всегда доводили его до беды. Я попросила его не охотиться на кроколисков, потому что они злобны и коварны! А он рассвирепел и хлопнул дверью.$B$BЕсли не сумеешь отыскать его – узнай хотя бы, что с ним случилось... даже если тебе придется заглянуть в брюхо каждому кроколиску на берегах Строптивой!', 'Принесите известие о судьбе, постигшей Крона, Майше Тор\'крен в усадьбу к северо-западу от Колючего Холма.', 'Ох, сыночек... милый мой сыночек…$B$BЧто ж, я не знала судьбы своего сына и потому терзалась понапрасну. Теперь же я хоть смогу его оплакать…$B$BСпасибо тебе, $N. Прошу тебя, возьми этот плащ. Я-то собиралась подарить его Крону, когда он вернется с добычей... А теперь, зная, что он погиб, я даже не смогу смотреть на него.', 'Я молюсь, чтобы Крон вернулся ко мне, но, боюсь, я уже знаю, что с ним случилось…', NULL, NULL, 'Амулет Крона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (817, 'Полезная добыча', '$N, у нас в большом ходу шкуры дуротарского тигра. Чего только из них не делают! И одеяла, и доспехи, и шатры. Вот почему мы охотимся на этих животных, но не истребляем их.$B$BВ общем, пришла пора в очередной раз сократить поголовье. Наши потребности растут, и запасов не хватает. Мне нужны новые шкуры.$B$BПринеси мне 4 шкуры дуротарских тигров, и получишь награду. Эти кошки водятся на островах к югу отсюда.', 'Принесите 4 шкуры дуротарских тигров Вель\'рину Клыку в деревне Сен\'джин.', 'Молодец, $N! Благодаря твоей помощи наш народ не останется без доспехов и не будет страдать от холода, когда наступит зима. $B$BСпасибо тебе.', 'Как сейчас помню свою первую охоту на тигров! Я решил поохотиться на самом большом из островов Эхо. Я затаился в тени и ждал почти целый день.$B$BМои мускулы были напряжены, и я был готов выстрелить в любую секунду! Как же я торжествовал, когда мой первый тигр был повержен!', NULL, NULL, 'Мех дуротарского тигра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (818, 'Растворитель', 'Да, глаза меня порой подводят, но все же пока я вижу достаточно отчетливо. И все чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда. И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков.$B$BЧто? Ты $gдостоин:достойна:? Ну да, конечно... Это ты так думаешь.$B$BМне нужны кое-какие компоненты. Сумеешь ли ты их добыть?$B$BМне нужны невредимые глаза макрур и слизь крабов, их ты можешь собрать с любых макрур и крабов в Дуротаре. Вот принеси мне их, потом поговорим.', 'Принесите 4 невредимых глаза макрур и 8 фиалов со слизью крабов мастеру Ворналу в деревне Сен\'джин.', 'Отличная работа, $N! Ты молодец!', 'Вот-вот, сила и воля по-настоящему проявляются только со временем. Потеряешь терпение, дашь слабину – тут-то и вылезет твоя подлинная натура!', NULL, NULL, 'Невредимый глаз Макруры', 'Слизь краба', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (819, 'Пустой бочонок Чэня', 'Маленькая табличка на торце одной из бочек гласит:$B$B\"Чэнь Буйный Портер – $B$BДа будет ваш дух горяч, а кружка – полной.\"', 'Отыщите кого-нибудь, кто знает о пустом бочонке Чэня. ', 'Ну, я…$B$BЭто был один из бочонков Чэня Буйного Портера. Давным-давно он путешествовал вместе с Рексаром. Я не видел его и не слышал о нем с незапамятных времен. Спасибо, что ты принес мне этот бочонок, $N.', 'Да?', NULL, NULL, 'Пустой бочонок Чэня (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (821, 'Пустой бочонок Чэня', 'Хочешь попробовать напиток, придуманный Чэнем? Ах, до чего же хорош буйный портер! Чэнь передал рецепт моему наставнику, ну а он – мне. Только для него понадобится несколько компонентов. Но он того стоит!$B$BПринеси мне 5 клыков равнинного льва, 5 почек долгонога и 1 рог рокочущей ящерицы. Из них выйдет прекрасный портер.$B$BВсе эти составляющие нетрудно отыскать в Степях.', 'Принесите 5 клыков равнинного льва, 5 почек долгонога и 1 рог рокочущей ящерицы пивовару Дрону в Кабестан.', 'Ха-ха... Вот уж не думал, что снова сварю этот напиток!$B$BПрямо ностальгия охватила. Сразу вспомнилось, как я наварил троггского пойла. Спасибо, $N. От воспоминаний даже на душе посветлело.', 'Как идут поиски?', NULL, NULL, 'Клык равнинного льва', 'Почка долгонога', 'Рог рокочущей ящерицы', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (822, 'Пустой бочонок Чэня', 'Отличный напиток – буйный портер, а? $B$BЯ научился у Чэня еще одному рецепту. Хочешь узнать? Много времени он не отнимает, а в жизни пригодится. $B$BПринеси мне 5 грозовых желез любых грозошкуров, 1 слюнную железу грозового змея от больших грозовых змеев и печень кодо от любого из кодо Степей.$B$BВставляет – не то слово. Это эль трогга, о котором я уже говорил.', 'Принесите 5 грозовых желез, 1 слюнную железу грозового змея и 1 печень кодо пивовару Дрону в Кабестан.', 'Ха-ха! Я знал, что ты не откажешься от этого напитка. Приходи, я еще тебе сварю. Главное – приноси все необходимое.', 'Ну как, трудишься, ищешь все составляющие, $N?', NULL, NULL, 'Грозовая железа', 'Слюнная железа Грозового змея', 'Печень кодо', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (823, 'Явиться к Оргнилу', 'У нас, в деревне Сен\'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе. Однако принесенные тобой вести об Пылающем Клинке сулят неприятности всем.$B$BВ Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок. Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты $gузнал:узнала: в долине Испытаний. Ему нужно это знать.$B$BКолючий Холм находится к северу отсюда.', 'Поговорите с Оргнилом Душегрызом на Колючем Холме.', 'Да? Тебе есть, о чем доложить? Ну так рассказывай, чего ты ждешь?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (824, 'Дже\'неу из Служителей Земли', 'Служители Земли – сообщество шаманов, посвятивших себя изучению и охране Стихий. Они забыли о безумных древних богах, древних легендах и преданиях больше, чем большинство ученых вообще знало.$B$BПовезло тебе, что я знаю кое-кого из Служителей Земли тут, в Ясеневом лесу. Иди в форт Зорам\'гар на Зорамское взморье и покажи Дже\'неу Санкри свою находку. Если кто и поймет, что это за шар, так это он.', 'Отнесите оскверненную водяную сферу Дже\'неу Санкри в форт Зорам\'гар в Ясеневом лесу.', 'Этот шар... волнует он меня. Многие из наиболее могучих элементалей черпают силу и энергию при помощи таких устройств. Найти такую штуку неповрежденной – одно дело, а вот настолько оскверненной – совсем другое.$B$BЯ прослежу, чтобы этот шар как следует изучили Служители Земли. Возможно, мы сумеем положить конец такому осквернению стихий. Прошу – прими это в награду за то, что принес нам этот шар для изучения.', 'А, привет. Я много времени трачу на изучение воды – вернее, всех Стихий – так много, что порой не замечаю никого вокруг.$B$BВ чем тебе помочь разобраться?', NULL, NULL, 'Оскверненная водяная сфера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (825, 'Обломки кораблекрушения', 'Один из моих лучших разведчиков принес сообщение, что обломки кораблей Праудмура все еще плавают около побережья Дуротара, к востоку от крепости Тирагард.$B$BНи для кого не секрет, что люди, будучи в союзе с этими маленькими уродцами, гномами, неплохо овладели механикой. Нам нужно знать все о нашем предполагаемом противнике! К тому же, эти знания пригодятся и нашему народу.$B$BСплавай к обломкам, $N, и добудь мне инструменты Альянса.', 'Га\'Ток с Колючего Холма просит вас принести ему 3 комплекта инструментов гномов, найти которые можно в обломках кораблей у побережья.', 'Ты успешно выполнил поручение, $C. Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном.$B$BМолодец!', 'Когда мы узнаем, как люди управляют своей странной техникой, у нас будет куда больше шансов победить их в грядущих битвах.$B$BС новыми знаниями Орда станет сильнее!', NULL, NULL, 'Инструменты гномов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (826, 'Залазан', 'Знахарь Залазан живет на островах Эха на востоке. Эти острова мы когда-то называли родиной…$B$BА теперь он оттуда посылает троллей на материк, досаждая нашему народу и переманивая на свою сторону все новых приспешников.$B$BЕго нужно остановить!$B$BУничтожь Залазана и его слуг – бывших троллей из племени Черного Копья, ныне потерянных для нас! Принеси мне его голову – и я буду знать, что владычеству зла пришел конец.', 'Убейте Залазана, убейте 8 троллей-вудуистов и 8 проклятых троллей.Принесите голову Залазана Гадрину.', 'Залазана больше нет, наше племя снова может спать спокойно!$B$BСпасибо, $N. Племя Черного Копья многим тебе обязано. Если тебя мучает какой-нибудь недуг, обратись к моему помощнику, Бом\'бею, который находится позади меня. Он силен в магии вуду…', 'Ну что, $N, Залазан побежден?', NULL, NULL, 'Проклятый тролль убито', 'Тролль-вудуист убито', 'Голова Залазана', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (827, 'Скала Черепа', '$N! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками.$B$BЯ подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников.$B$BСтупай к скале Черепа и отбери у фанатиков, которых там найдешь, их ошейники. Принеси их мне, и я раскрою их тайну!', 'Отберите у фанатиков из Скалы Черепа обжигающие ошейники.Принесите их в лагерь Маргозу.', 'Отлично! В этих ошейниках и таится секрет Пылающего Клинка. И я его раскрою!', 'Ну что, $N, удалось тебе проникнуть в Скалу Черепа? Принес обжигающие ошейники?', NULL, NULL, 'Обжигающий ошейник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (828, 'Маргоз', 'Один из наших шаманов, Маргоз, многое знает о клане Пылающего Клинка. Как-то он рассказывал о пещере, которая называется скала Черепа, в горах у самого Оргриммара. Там окопалась большая шайка сектантов из клана Пылающего Клинка.$B$BПрежде чем отправиться к скале Черепа, поговори с Маргозом. Он мудр, и к его советам стоит прислушиваться.$B$BТы найдешь его на северо-востоке, между побережьем и Сухой лощиной.$B$BСледуй его советам, $N, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!', 'Поговорите с Маргозом. ', 'Здравствуй, $N. До меня дошли слухи о твоем появлении и о твоих подвигах в Дуротаре.$B$BТы – многообещающий $C.$B$BНе сворачивай с этого пути, и великое будущее будет ждать тебя!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (829, 'Ниру Огненный Клинок', 'Принесенные тобой обжигающие ошейники – это мощные инструменты демонов. И распознать их происхождение мне, как шаману, не под силу. Нужно, чтобы на них взглянул чернокнижник.$B$BОтнеси один обжигающий ошейник Нииру Огненному Клинку. Он искусный чернокнижник, но утверждает, что использует свою силу лишь затем, чтобы вредить демонам, а еще говорит, что его оккультные исследования идут на пользу Орде. Правда это или нет, а его помощь нам еще может понадобиться в борьбе с последователями демонов в Дуротаре.$B$BНииру можно найти в Оргриммаре, в Расселине Теней.', 'Отнесите один обжигающий ошейник Нииру Огненному Клинку в Оргриммаре.', 'О! Откуда у тебя это? Тебя прислал ко мне славный Маргоз из Колючего Холма, верно?$B$BНу-ка, дай взглянуть...', 'Мое почтение, $C. Чем могу я помочь тебе, брат?', NULL, NULL, 'Обжигающий ошейник (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (830, 'Приказы адмирала', 'Вы открываете потрепанный и выгоревший конверт и обнаруживаете документ официального вида. На нем – печать адмирала Праудмура.$B$BПохоже, это что-то важное. Может быть, Га\'току, командиру Колючего Холма, эта информация пригодится...', 'Отнесите приказы адмирала Праудмура Га\'току на Колючий Холм. ', 'Ничего хорошего это не предвещает... Очень хорошо, что ты принес это мне.', 'У тебя озабоченный вид, $C. Что у тебя там?', NULL, NULL, 'Приказы адмирала Праудмура (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (831, 'Приказы адмирала', 'Людям верить нельзя. Мы сражались плечом к плечу с ними, но в глубине души знали, что рано или поздно они нас предадут.$B$BАдмирал Праудмур был убит, но этого оказалось недостаточно, чтобы остановить предательство. Этот подлый человечишка успел как следует продумать и изложить свои планы на бумаге, прежде чем встретил заслуженную смерть.$B$BПохоже, что его владычество не закончится даже со смертью Бенедикта. Кто знает, когда следующая волна людей Праудмура обрушится на наши берега?$B$BЭти приказы нужно немедленно доставить в Оргриммар, Вол\'джину! Ты найдешь его в зале приемов Тралла.', 'Доставьте приказы адмирала Праудмура Вол\'джину в зал приемов Тралла в Оргриммаре.', 'О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости.$B$BТы достойно послужил Орде, $C.$B$BА теперь извини, мне нужно немедленно поговорить об этом с Траллом!', 'Ты что, не видишь? Я занят. Ну, докладывай. Но если дело не срочное...', NULL, NULL, 'Приказы адмирала Праудмура (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (832, 'Пылающие тени', '<Слова из амулета плавно перетекают в ваш разум.> $B$BГазз\'уз! $B$BГазз\'уз, докладывай! $B$BО том, что ты нашел в Скале Черепа, уже стало известно. Готовься к нападению!$B$BГовори, Газз\'уз! Говори, или я позабочусь о том, чтобы о твоем присутствии стало известно Нииру Огненному Клинку, а уж он-то тебя не пощадит!$B$BС Нииру тебе лучше не связываться...$B$BГазз\'уз, ты меня слышишь?', 'Отнесите этот амулет Ниру Огненному Клинку в Оргриммар. ', '*Нииру разглядывает Око Пылающей Тени.*$B$BЛюбопытно. Так ты говоришь, голос упоминал мое имя? Я, конечно, известен как непримиримый враг противников нашего вождя, но все же странно, что голос назвал именно меня. Тем более странно, что название секты, у членов которой ты нашел этот амулет, так похоже на мою фамилию.$B$BНадо изучить эту подвеску. Изучить и поразмыслить над тем, что значит это сообщение. $B$BСпасибо, $N, что сообщил мне об этом. Ты оказал своему народу серьезную услугу.', 'Ты хочешь рассказать мне о чем-то важном, по глазам вижу!', NULL, NULL, 'Око Пылающей Тени (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (833, 'Священное погребение', 'Лишь самых доблестных тауренов хоронят в Красных cкалах, на нашем священном кладбище. Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утес, и тем, кто отдал свои жизни на благо племени и вождей. $B$BПохоже, теперь на эту священную землю пала тень. Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их. $B$BПротив них поможет только сила, $N.', 'Сказитель Тотем Дождя попросил вас убить 8 злоумышленников из племени Дыбогривов в Красных cкалах.', 'Молодец. Ты проучил племя Дыбогривов. Теперь они дважды подумают, прежде чем осквернять святые для нас места.', NULL, NULL, NULL, 'Злоумышленник из племени Дыбогривов убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (834, 'Ветра пустыни', 'Я – Резлак, один из ребят Газлоу. Шеф послал меня на помощь оркам в Дуротаре. Все бы хорошо, если бы не проблемы с караванами. Точнее, с охраной караванов. Как ты думаешь, можно ли работать, когда караваны все время грабят?$B$BПоследний караван – они мне клялись, что он-то уж точно дойдет! – перехватили гарпии Пыльного Ветра в... как же его... Каньоне Колючего Ветра!$B$BА мне этот груз позарез нужен, я без него как без рук! Ступай по большому каньону на юг, там будет расселина, идущая с запада на восток...', 'Добудьте 5 мешков припасов и верните их Резлаку близ Оргриммара. ', 'О, то что надо! Наши припасы! Замечательно. Я смогу снова взяться за работу, как только найду кого-нибудь, кто донесет мне эти мешки.', 'Не пойми меня неправильно, я мастер своего дела, но ведь это же просто смешно! Что мне тут делать, песочные замки строить?', NULL, NULL, 'Мешок припасов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (835, 'Обеспечение безопасного сообщения', 'Газлоу мне как-то сказал: \"Резлак, запомни одну вещь: если хочешь, чтобы что-то было сделано хорошо, сделай это сам\".$B$BМы не можем и дальше терять караваны. Я вынужден взять дело в собственные руки. Сухая лощина находится в восточной части Каньона Колючего Ветра. Если перебить всех тамошних гарпий, дороги станут безопасными.$B$BРазумеется, Газлоу учил меня и другому: \"За соответствующую плату тебе сделают что угодно\". Ну что, $N, возьмешься?', 'Убейте 12 дикарок из стаи Пыльного Ветра и 8 грозовых ведьм из стаи Пыльного Ветра, обитающих возле Сухой лощины, по просьбе Резлака.', 'Ну все, теперь нашим караванам больше ничто не угрожает! Наконец-то я вздохну свободно. Твоя помощь пришлась как нельзя вовремя: со следующим караваном мне должны прислать партию занятных безделушек!$B$BТы, $N, свое дело знаешь. Обратись к моему шефу в Кабестане. У него наверняка найдется для тебя работенка.$B$BАх да, не беспокойся, разумеется, я тебе заплачу за труды!', 'Даже не верится, что такое мог говорить мой шеф, $N, а ведь он мужик соображающий. \"Не бойся рисковать, когда надо\", – вот что он говорил.$B$BВедь гарпии так и будут нападать на нас и на караваны, пока мы что-нибудь с этим не сделаем, верно?', NULL, NULL, 'Дикарка из стаи Пыльного Ветра убито', 'Грозовая ведьма из стаи Пыльного Ветра убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (836, 'Спасти КПХ-9:HL!', 'Из робота снова раздается голос гнома:$B$B\"Нужно вывести OOX-09:HL на открытое и безопасное место, чтобы он мог взять нужный разбег и взлететь. У него есть система маскировки, но она, похоже, повреждена, поэтому вам придется проводить цыпленка до... ну, скажем, к большим скалам, которые загораживают обзор! Местность там тихая и открытая, так что разбежаться он сумеет\".$B$B\"Пожалуйста, проводите робота на берег, а потом загляните ко мне в Пиратскую Бухту. Карлс Пропеллерз, конец связи\".', 'Сопроводите OOX-09:HL в безопасное место, а потом доложитесь Карлсу Пропеллерзу в Пиратской Бухте.', 'О, да ты просто спас моего робота OOX-09:HL! Я прям даже не знаю, как тебя благодарить! Моих автономных роботов еще совершенствовать и совершенствовать, но ты избавил меня от многих лишних часов работы, а также от расходов!$B$BПожалуйста, выбери себе что-нибудь в награду. Спасибо тебе еще раз, $N, я и мои роботы навеки у тебя в долгу.', NULL, NULL, NULL, 'Проводить OOX-09/HL в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (837, 'Вторжение', 'Когда мы поселились здесь, свинобразы Иглогривых владели большей частью этих земель и оказались сущей напастью! Большую их часть нам мало-помалу удалось вытеснить, но в некоторых районах они окопались прочно.$B$BНо с нас уже довольно! Мы не можем больше терпеть присутствие Иглогривых в наших землях. Их лагеря – к западу отсюда. Они часто прячутся в зарослях колючек. Сегодня мы вытесним их из Дуротара – а завтра, глядишь, и из всего Калимдора!', 'Убейте 4 свинобразов из племени Иглогривых, 4 разведчиков из племени Иглогривых, 4 пылемутов из племени Иглогривых и 4 боевых стражей из племени Иглогривых по просьбе Га\'Тока из Колючего Холма.', 'Я расскажу всем, что Иглогривы прогнаны со своих обжитых мест, и что их жилища надо сжечь. Теперь, когда племя Иглогривых изгнано из Дуротара, границы нашей новой родины станут значительно безопаснее.', 'Они, конечно, отчасти разумны и даже обладают зачатками общественного устройства, и все же меня не перестает удивлять тот факт, что иглогривы смогли захватить такие большие территории в Калимдоре. Быть может, они более хитры, чем мне кажется…', NULL, NULL, 'Свинобраз из племени Иглогривых убито', 'Разведчик племени Иглогривых убито', 'Пылемут из племени Иглогривых убито', 'Боевой страж племени Иглогривых убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (838, 'Некроситет', 'На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью Плети. В ее недрах наши враги спокойно проводят исследования, делаясь все сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти.$B$BАптекарь Дитерс многое знает о Некроситете и придумал, как достать ключ. Ты $gзарекомендовал:зарекомендовала: себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с аптекарем.', 'Поговорите с аптекарем Дитерсом из Бастиона, что в Западных Чумных землях. ', 'Да, $C. Верховный палач упоминал, что тебе можно доверить тайну ключа. В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ, позволяющий отомкнуть двери в любой момент.$B$BДело, как всегда, будет непростым. Но судя по всему, тебя такими словами не напугать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (840, 'Новобранец Орды', 'Хм, $gслабаком:слабенькой: тебя не назовешь…$B$BПослушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс.$B$BПередай Каргалу это письмо о найме – возможно, он его подпишет.', 'Ступайте из Колючего Холма в Степи по западной дороге. Перейдите через мост.Остановитесь у орочьей заставы за мостом.Отдайте Каргалу Боевому Шраму ваше письмо о найме.', 'А, так тебя Такрин прислал? Он отличный разведчик, не знаю даже, что бы я без него делал…$B$BПисьмо-то я подпишу, но на самом деле воины нам нужны не здесь, а в Перекрестке.', 'Чего тебе надо, молокосос? Если ты новобранец, давай сюда письмо, а иначе проваливай.', NULL, NULL, 'Письмо о найме (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (841, 'Еще один источник энергии?', 'Дай-ка я угадаю – ты не $gуспел:успела: осуществить свой страшный замысел, губительный для мироздания. Нет, еще лучше... Ты $gуронил:уронила: его в песок! Короче, в любом случае я могу продать тебе еще один источник энергии. Только на сей раз он обойдется в десять, да, ДЕСЯТЬ, бурдюков с водой Скитальцев Пустыни!$B$BВремена настали тяжелые, а источники энергии не растут на деревьях! Хм, а что, если росли бы? Может, нам сконструировать дерево источников энергии...', 'Принесите 10 бурдюков с водой Скитальцев Пустыни главному инженеру Чепухастеру в Прибамбасск в обмен на еще один источник энергии.', 'Ладно, вот еще один источник энергии. Очень советую применить его по назначению, если не хочешь добыть для меня еще десять мехов воды.', 'И где мои десять мехов воды?', NULL, NULL, 'Бурдюк с водой Скитальцев Пустыни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (842, 'Рекрутский набор Перекрестка', 'Отнеси это подписанное письмо о найме в Перекресток.$B$BТам всем заправляет – Сергра Черный Шип, лопни ее шкура! Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое. Тралл уверен, что она замечательная, но мне что-то так не кажется.$B$BТак что разбирайся $gсам, парень:сама: детка:...', 'Ступайте по западной дороге от форпоста Каргала.На развилке поверните налево и ступайте на юг.Найдите Сергру Черный Шип у перекрестка дорог в Перекрестке.', 'Ладно, $N. Не хочешь есть свой хлеб в Орде даром? Что ж, дел у нас предостаточно. Просто слушай внимательно и делай, что тебе скажут.$B$BИмей в виду, я по глазам вижу, что у тебя на уме. Наглости я не спущу! Тралл самолично заявил, что в Орде женщины во всем будут наравне с вами, мужиками. Только попробуй проявить ко мне неуважение – узнаешь, почем фунт лиха!', 'Ну-с, и кто у нас тут? Неужели Каргал снизошел до того, чтобы прислать мне очередного рекрута?', NULL, NULL, 'Подписанное письмо о найме (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (843, 'Ответный удар Ганна', 'Ныне я брожу по дорогам родного края в одиночестве.$B$BДворфы Бейл Модана не чтят моих границ. Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы. Земли, некогда приютившие и питавшие мое племя, захвачены вредоносными дворфами.$B$BВсе попытки решить дело миром провалились. Пришло время для решительных действий.$B$BВыгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря.', 'Ганн Каменное Копье попросил вас убить 15 бейл\'данских землечерпов и 5 бейл\'данских старшин.Принесите Ганну Каменному Копью записи Хазгорма.', 'Хазгорм заслужил свою судьбу. Мне нисколько его не жаль. Он явился в наши края незванным.$B$BБыть может, его смерть послужит предостережением тем, кто пытается нарушить наш покой.$B$BДай-ка я изучу записи этого дворфа...', 'С появлением в Бейл Модане дворфов многие ни в чем не повинные таурены лишились жизни или покинули родину предков. Я должен вернуть свои земли!', NULL, NULL, 'Бейл\'данский землечерп убито', 'Бейл\'данский старшина убито', 'Записи Хазгорма', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (844, 'Равнинные долгоноги', 'Первое задание будет совсем простым.$B$BРавнинные долгоноги, живущие к востоку отсюда, разоряют наши продовольственные склады – просто сил уже нет!$B$BПеребей несколько долгоногов и принеси мне их клювы.', 'Принесите 7 клювов долгоногов Сергре Черный Шип в Перекресток. ', 'Хорошо, $N. Долгоногов перебили, и нам будет проще доставлять продовольствие. Надеюсь, и ты кое-чему научился, потому что следующая дичь не такая смирная, как долгоноги...', 'Принес клювы долгоногов?', NULL, NULL, 'Клюв долгонога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (845, 'Жевры', 'Хотя жевры – не самые страшные звери в Степях, они посильнее равнинных долгоногов. Не беспокойся, в свое время тебе и покрупнее дичь достанется, но пока тебе еще надо малость поточить зубки. $B$BПоохоться на жевр на севере и на юге и собери их копыта. Принеси их мне, и, быть может, в следующий раз мы дадим тебе задание посерьезнее.', 'Убивайте жевр-бегунов, пока не наберете 4 пары копыт жевры для Сергры Черный Шип в Перекрестке.', 'Неплохо, $N. У жевр сильные ноги. Одного меткого удара достаточно, чтобы отшвырнуть таурена в сторону!$B$BПохоже, в тебе тоже силы хватает. Ну что, готов пройти настоящее испытание?', 'Сколько жевр тебе удалось убить?', NULL, NULL, 'Копыта жевры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (846, 'Месть Ганна', 'Очевидно, что шахтеры не могут обойтись без взрывчатки и шумных землеройных машин. Мы думаем, что скоро туда направят нового старшину.$B$BПусть проклятые дворфы отведают собственного угощения. Согласно схемам, если смешать нитроглицерин с древесной сердцевиной и натриевой селитрой, получится взрывной заряд. Все компоненты есть у ружейников, солдат и офицеров из Крепости.$B$BСобери все необходимое и принеси мне. Я создам заряд, который дворфы не скоро забудут!', 'Ганн Каменное Копье попросил вас принести ему 6 сосудов с нитроглицерином, 6 пучков древесной сердцевины и 6 образцов натриевой селитры.', 'Вижу, ты зря времени не терял, $C.$B$BОчень скоро дворфов ожидает неприятный сюрприз!', 'Вижу, ты вернулся, $N.$B$BХотя смерть Хазгорма и замедлила уничтожение холмов моих предков, полностью остановить разрушение не удалось.$B$BКрепость в Бейл Модане – угроза для нас всех. Она была построена для защиты раскопа, а теперь представляет собой грозную военную силу.$B$BЕсли ты принесешь мне все необходимое, я готов сделать заряд, после взрыва которого дворфы-торопыги передумают лезть в Степи.', NULL, NULL, 'Нитроглицерин', 'Древесная сердцевина', 'Натриевая селитра', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (847, 'Коварство ящера', 'Эта... эта сила... Это и есть мощь шаманов, которую Тор\'Ган пытался мне показать? Должен сказать, весьма интересно. Скажите Тор\'Гану, что он меня убедил... на данный момент. Я выслушаю то, что он хочет мне сказать.', 'Поговорите с Тор\'ганом в Павшем Молоте, что на нагорье Арати.', 'Когда чары спадут, я поговорю с Гор\'мулем. Благодарю вас за помощь в возвращении Гор\'муля к жизни. Я не сомневаюсь, что и он очень благодарен вам.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (848, 'Споры грибов', 'Оазисы Степей скрывают немало тайн. В их водах разлита энергия жизни, питающая и укрепляющая растения и животных.$B$BИ меняющая их.$B$BНеподалеку от этих оазисов растут грибы, чьи споры мы, аптекари Лордерона, используем при создании снадобий.$B$BПринеси мне эти споры – и благодарность наша будет велика.', 'Принесите аптекарю Хелбриму в Перекресток 4 порции спор грибов. ', 'Ах, да. Прекрасный материал. Действенный.$B$BЯ из Отрекшихся, а мы исполняем свои обещания. Вот твое вознаграждение, $N.', 'И где же споры? Мне надо сварить определенное зелье для коллеги из Громового Утеса, для этого и требуются споры...', NULL, NULL, 'Споры грибов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (849, 'Месть Ганна', 'Изучив схемы Хазгорма, можно без труда создать взрывчатку.$B$BНу вот, готово. $B$BА теперь, $N, я дам тебе особое задание. Возьми взрывчатку и подорви ветролет в Бейл Модане.$B$BЭта машина не просто играет ключевую роль в снабжении раскопок, она служит и для военных целей. И что еще важнее – она воплощение мощи дворфов и оскорбление памяти моего племени.$B$BВыполни это задание, и я буду гордиться тобой! Ну и награду ты тоже получишь.', 'Уничтожьте ветролет в Бейл Модане и возвращайтесь к Ганну Каменному Копью.', 'Отличная работа, $N. В Громовом Утесе тебя будут чтить как защитника священных земель тауренов и поборника исчезнувшего племени.', NULL, NULL, NULL, 'Уничтожьте бейлмоданский ветролет', 'Взрывающаяся шашка Ганна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (850, 'Главари племени Колкар', 'Сотни лет кентавры вставали на пути тауренов. В последнее время клан Колкар начал всерьез грозить безопасности Степей. Раньше им мешала побеждать их собственная неорганизованность, но недавно среди них появились новые вожди. Они создали из своих сородичей войско.$B$BЧтобы сохранить наши земли, мы должны убить вождей кентавров.$B$BПринеси мне голову Барака Кодобоя. Он живет в лагере неподалеку от Забытых прудов на севере.$B$BКогда одержишь над ним верх, возвращайся.', 'Принесите Регтару Вратам Смерти, живущему на западе от Перекрестка, голову Барака.', 'Молодец, $N. Кентавры – примитивные и грубые создания, но некоторым из них была дарована мудрость и умение вести в бой. Они-то опаснее прочих.$B$BБарак таким и был. Хорошо, что он мертв.', 'Привет, $N. Принес голову Барака?', NULL, NULL, 'Голова Кодобоя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (851, 'Верог Дервиш', 'Кентавр Верог Дервиш бродит по Пустошам, и найти его будет нелегко. Живет же он в командном шатре кентавров, в Застывшем оазисе на юго-востоке. Быть может, удастся заманить его туда.$B$BОтправляйся в Застывший оазис и напади на кентавров рядом с командным шатром. Это опасно, но если убить достаточно кентавров, кто-нибудь поднимет тревогу и явится Верог.$B$BПринеси мне его голову, и я помещу ее рядом с головой Барака Кодобоя.', 'Принесите Регтару Вратам Смерти, живущему на западе от Перекрестка, голову Верога.', 'Замечательно. Видно, ты взбаламутил кентавров – стражи заметили необычную активность неподалеку от Застывшего оазиса. Наверное, это твоя работа.$B$BМожешь гордиться своим подвигом, $N. Ты необыкновенно отважен.', 'Удалось найти Верога, $N?', NULL, NULL, 'Голова Верога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (852, 'Хэзрул Кровавая Отметина', 'Хэзрул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жесток и хитер. Одолев его, ты нанесешь серьезный урон всем Колкар, а значит, они станут меньше угрожать нам.$B$BИтак, убей его. Принеси мне его голову, как $gпринес:принесла: головы Барака и Верога.$B$BОн управляет своим народом из Цветущего оазиса на юге.', 'Принесите голову Хэзрула Регтару Врата Смерти, живущему к западу от Перекрестка.', 'Хвала тебе, $N. Хотя кентаврам не хватает дисциплины, чтобы обрушить свою ярость на врагов, как орки, они все равно свирепые противники. Одержав над ними верх, ты доказал свою доблесть.', 'Так Хэрзул повержен?', NULL, NULL, 'Голова Хэзрула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (853, 'Аптекарь Зама', 'Я сделал эмульсию из принесенных тобой спор, и теперь мне нужно доставить ее моей коллеге, аптекарю Заме. Если ты отнесешь ей мою посылку, она предложит тебе на выбор что-нибудь из своего запаса алхимических товаров.$B$BОна живет в Прудах Видений, пещере, расположенной ниже обиталища шаманов Громового Утеса. Путь к этой пещере хорошо скрыт, но начинается он на Вершине духов.$B$BПоспеши. Эмульсия хранится не очень долго, потому надо вскрыть и использовать ее до того, как она испортится.', 'Отнесите топленые споры аптекарю Заме в Громовой Утес за отведенное время.', 'А, споры, которые Хелбрим собрал в Степях. Он заручился твоей помощью при сборе? Хорошо.$B$BЭмульсия не успела испортиться, видать, ты время зря не тратил. Молодец, $C.', 'Ты несешь мне посылочку от аптекаря Хелбрима?', NULL, NULL, 'Топленые споры (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (854, 'Путешествие в Перекресток', 'Я знал, что ты придешь, $gюный:юная:c: $C. Хотя, пожалуй, ты уже не так $gюн:юна:.$B$BДумаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения. $B$BСтупай в Перекресток. Наша судьба тесно связана с судьбой орков, а им нужна помощь. Иди по дороге на восток, а потом сверни на север, к Перекрестку. Отыщи Тхорка в стенах города, ибо с ним пребывает благословение Матери-Земли.', 'Поговорите с Тхорком на Перекрестке в Степях. ', 'Я рад, что нам на помощь прибыли союзники из самого Громового Утеса. Добро пожаловать!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (855, 'Наручи кентавров', 'Клан Колкар угрожает завоеваниям Орды в Степях. Мы должны сократить численность их войск. В связи с этим у меня есть для тебя задание.$B$BОтправляйся в земли Колкар, перебей их воинов и принеси мне их наручи. Возвращайся с трофеями, и Орда тебя наградит.', 'Принесите Регтару Вратам Смерти, живущему к западу от Перекрестка, 15 наручей кентавров.', 'Неплохо. Уверен, тебе удалось вселить страх в выживших кентавров. Если Колкар не полные идиоты, теперь они успокоятся и прекратят наступление.$B$BК сожалению, вряд ли им на это хватит ума. Что весьма плохо.$B$BПлохо для них, разумеется.', 'Как идет охота, $N?', NULL, NULL, 'Наручи кентавров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (857, 'Слеза Лун', 'Она была у меня в руках! В этих самых руках! И я хочу вернуть ее! Она моя!$B$BЕе откопали эти грязные землечерпы... как же  прекрасна она была!.. Ее назвали слеза Лун. Первое серьезное открытие в Бейл Модане.$B$BОна должна достаться мне! Мне, говорю!$B$BГенерал Двукосса позавидовал силе, которую она мне давала, и запер ее в Крепости. Сказал, что эта вещь проклята. Дурак!$B$BЕе хотели заполучить и другие, мне пришлось их остановить. А этот мерзавец Двукосса прогнал меня.$B$BА я хочу ее вернуть. Она моя!', 'Фриглай Изгнанник попросил вас вернуть ему слезу Лун.', 'Наконец-то сила снова со мной! Со мной, говорю!', 'Где слеза Лун? Она мне нужна! Нужна, говорю!', NULL, NULL, 'Слеза Лун', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (858, 'Зажигание', 'Тебя случайно не Пароклапан прислал? У меня проблемы. Я запрыгнул внутрь, не подумав, что для запуска крошшера нужен ключ. Один из операторов спросил меня, все ли в порядке, и я впал в панику! Вместо того чтобы сказать, что я потерял ключ, я заявил, что крошшер неисправен.$B$BНадо поскорее выбираться отсюда! Поднимись в комнату управления на вышке, у бригадира должен быть ключ.$B$BВыручи меня!', 'Добыв ключ зажигания, отнесите его Визлкранку. ', 'Ага, похоже, ключ подходит. Ну-ка, знаю ли я, как управлять этой штуковиной…$B$BХм... Управление вращением... Этот рычаг отвечает за скорость и равновесие... Управление манипулятором. Ну и ну! Поверить не могу, что Торговая Компания создала устройство, которое настолько лучше нашего. Надо доставить этот резак в Кабестан!', 'Скорее, надо выбираться отсюда, пока никто ничего не заподозрил!', NULL, NULL, 'Ключ зажигания', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (860, 'Сергра Черный Шип', 'Ежели хочешь вступить на путь охотника, то тогда тебе надо идти в Степи. Тамошние твари упрямы и яростны. Охотясь там, ты многому научишься, и дух твой окрепнет.$B$BПоговори с Сергрой Черный Шип. Она будет первой твоей наставницей в Степях.$B$BСергра сейчас в Перекрестке. Чтобы туда добраться, иди на восток от Деревни Кровавого Копыта прямиком в Степи, затем на развилке сверни на север. И по дороге держи ухо востро – Степи весьма опасны для неопытных и беспечных.', 'Поговорите с Сергрой Черный Шип в Перекрестке в Степях.', 'Хочешь охотиться в Степях?$B$BГлаза у тебя горячие и молодые. Они еще не окосели от выслеживания добычи на тутошних пыльных равнинах.$B$BНо ты не бойся. Мы закалим твое тело и дух! И растолкуем, что охота – не просто выслеживание и добыча.$B$BГотовься. Твой путь начинается прямо сейчас.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (861, 'Путь охотника', 'Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий…$B$BСтранствий и охоты. Ведь охота – первая доблесть таурена.$B$BЕсли ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги. Он живет в Громовом Утесе, на вершине Охотников.$B$BЧтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья. Эти звери сильны и хитры – подходящая добыча для $gмолодого:молодой $c, $gизбравшего:избравшей: путь охотника.', 'Принесите 4 когтя хищника плоскогорья Мелору Каменному Копыту в Громовой Утес.', 'Скорн Белое Облако – мудрый таурен. Он посвятил охоте много лет, и хотя уже слаб телом, дух его по-прежнему бодр. Мы высоко чтим его.$B$BЕсли тебя и правда прислал Скорн, то он разглядел в тебе будущего охотника. Добыть же эти когти было непросто, я знаю.$B$BБыть может, тебе пора вступить на избранный путь.', 'Приветствую. Вижу, ты хочешь о чем-то рассказать. У тебя ко мне какое-то дело?', NULL, NULL, 'Коготь хищника плоскогорья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (862, 'Похлебка из пещерной крысы', 'Должно быть, $c вроде тебя в Степях голодно. Я вот постоянно хочу есть.$B$BЗнаешь, приготовлю-ка я тебе отличную похлебку. Для этого мне понадобится несколько пещерных крыс.$B$BПохоже, эти грязные дворфы в Бейл Модане увлечены празднованием. Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс.$B$BТебе не стать закаленным бойцом, пока не набьешь руку на крысах! Ха-ха!', 'Принесите 8 пещерных крыс Грубу на востоке от Перекрестка.', 'Обычно я не ем этих грызунов, пока они такие... такие... свежие. Им надо полежать несколько недель, чтобы мяско стало с душком. Но ты, похоже, голоден.$B$BДай-ка я сварю тебе похлебку из пещерных крыс. Ну вот, готово.$B$BКушай на здоровье!', 'Ну что, достаточно пещерных крыс притащил?', NULL, NULL, 'Пещерная крыса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (863, 'Бегство', 'Полагаю, я буду учиться по ходу дела... Вряд ли это так сложно. Тут пара кнопок, там рычаг-другой. Ну что, поехали?', 'Охраняйте Зигзага и похищенный гоблинский крошшер по пути к Пароклапану в Кабестан.', 'Надеюсь, нам удастся найти что-нибудь ценное в этом поломанном образце резака... Время на исходе! Я отправлю спасательную экспедицию на помощь к Визлкранку.$B$BА, вот тебе за труды.', NULL, NULL, NULL, 'Помогите Визлкранку выбраться из раскопа Торговой Компании.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (864, 'Возвращение к аптекарю Зинг', 'Ну вот, источник энергии извлечен, и твои данные сохранились. Что ж, счастливого пути и все такое. Надеюсь, зловещий научный эксперимент удался.$B$B*Гоблин отворачивается от вас и погружается в дела Водной компании Прибамбасска. Вы кладете запечатанный набор для испытаний в надежное место и готовитесь отбыть в Подгород. Вас и запечатанный набор ждет аптекарь Зинг.*', 'Отнесите запечатанный набор для полевых испытаний аптекарю Зинг в Подгород.', 'Я немедленно займусь анализом данных. Быть может, безумие Чанна обернется моей гениальностью.$B$BЧто до тебя... Ты мне полезен, а я хорошо обращаюсь с полезными существами. Прими эту вещь, эти монетки, а в придачу к ним – мою благодарность.$B$BЗаглядывай время от времени – думаю, что мы еще поработаем вместе.', 'Добро пожаловать домой. Разумеется, в том случае, если ты несешь мне запечатанный набор для полевых испытаний. Если нет – я притворюсь, что не заметила твоей полной некомпетентности и не буду обрушивать на тебя свой гнев. Потому что ты пойдешь и сделаешь, что велено!', NULL, NULL, 'Запечатанный набор для полевых испытаний (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (865, 'Рога ящера', 'Ящеры Степей умнее, чем прочие. Мне кажется, весь ум в рогах! Если так, эти рога можно стереть в порошок и сделать из них \"умный напиток\". Я мог бы продавать его за баснословные деньги!!!$B$BТы можешь мне помочь. Принеси мне целые рога яркочешуйчатых смертехватов. Они живут в южной части Степей и на севере, рядом с границей Ясеневого леса.', 'Соберите 5 невредимых рогов ящера с яркочешуйчатых смертехватов и отнесите их Мебоку Миззриксу в Кабестан.', 'Здорово, тебе удалось их добыть! Остается стереть рога в порошок, смешать с вином и...', 'Ты принес рога, $N? Я собираюсь сколотить состояние на этих тварях!', NULL, NULL, 'Невредимый рог ящера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (866, 'Образцы корней', 'Таких трав, как в Степях, нет нигде. Свойства у них по большей части те же, но вода оазисов оказывает на них особое влияние, и они все же отличаются от подобных им, хоть и не сильно.$B$BЯ хочу выяснить, в чем же состоит разница... и нельзя ли ей воспользоваться!$B$BЕсли ты владеешь искусством травничества, собери для меня образцы корней растений Степей, и я сравню их с травами из других регионов.', 'Принесите Мебоку Миззриксу из Кабестана 8 образцов корней.', 'Да-да, замечательно! Из этих корней я выращу травы и смогу изучить их. Надеюсь отыскать в них новые свойства. Скрытые ценные свойства...$B$BИ не беспокойся – ты узнаешь об этом первым. Потому что в таком случае мне понадобится много корней!', 'Привет, $N. Принес образцы корней?', NULL, NULL, 'Образец корня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (867, 'Гарпии-налетчики', 'Нет сил терпеть нападения на наши караваны со съестными припасами. Пора сократить число проклятых гарпий, перерезав горло десятку-другому.$B$BЯ пробрался к их гнездам и выяснил, кто есть кто. Начать надо с низов, а потом постепенно пробиваться наверх.$B$BДля начала займись гарпиями и разбойницами из стаи Зачарованного Крыла, поселившимися на северо-западе, и принеси мне 8 когтей Зачарованного Крыла. Будет уже неплохо...', 'Соберите 8 когтей Зачарованного Крыла.Принесите их Дарсоку Точному Ножу на Перекресток.', 'Прекрасные когти. Чудные. Отличная работа, $N. Надеюсь, в ближайшем будущем мне снова доведется полюбоваться на твою работу.', 'Ну как, много ли гарпий удалось убить? Режь их, круши и бери трофеи. Мне нужно 8 когтей Зачарованного Крыла.', NULL, NULL, 'Коготь Зачарованного Крыла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (868, 'Охота за яйцами', 'Эй, $N. Меня отправили в Перекресток присматривать за этими землями и сообщать начальству в Оргриммаре, что тут творится.$B$BВ частности, мне велено наблюдать за насекомовидными тварями на юге в Полях Великанов. Нам о них почти ничего не известно, а я хотел бы узнать о них побольше. Кажется, они умнее обычных животных.$B$BВозьми вспарывающий коготь и принеси несколько яиц этих тварей из их курганов, но будь осторожнее: они нападут на тебя, если заметят, что ты творишь.', 'Принесите 12 яиц силитидов и вспарывающий коготь Коррану в Перекресток.', 'Порадовал ты меня, $N. Молодец.$B$BВот твоя награда...', 'Осторожно, яйца хрупкие. Разбитые мне не нужны.', NULL, NULL, 'Яйцо силитида', 'Вспарывающий коготь (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (869, 'Ящеры-воры', 'Недавно из сторожевой башни был похищен груз серебра. Он предназначался в уплату стражам Перекрестка, и его необходимо вернуть.$B$BСамое странное... одного из воров мы поймали с поличным. И... это оказался ящер! Немыслимо!$B$BНе знаю, зачем ящерам серебро. Мне все равно: главное, чтобы у нас не воровали. Пусть сдохнут!$B$BОтправляйся на охоту в Степи. Принеси мне их головы!', 'Принесите 12 голов ящеров Газрогу в Перекресток.', 'Тебе удалось избавить нас от ящеров!$B$BСпасибо, $N. Ты – достойный $C.', 'Принес головы, $N?', NULL, NULL, 'Голова ящера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (870, 'Забытые пруды', 'Давным-давно Степи были цветущим садом, полным жизни. Но этих земель коснулась карающая десница войны и катаклизма, обратив их в высохшую пустыню. Это наполняет мое сердце грустью, но так уж получилось.$B$BВпрочем, в последние годы в Степях образовалось несколько новых оазисов, а в них появилась жизнь. Мы, друиды, чувствуем, что из глубины к поверхности рвется какая-то сила.$B$BМы должны обнаружить ее источник. Отправляйся к Забытым прудам, к северо-западу от Перекрестка. Отыщи в воде источник силы и возвращайся сюда.', 'Отыщите источник силы и доложите о нем Тонге Руническому Тотему.', 'Там есть расселина, из которой выходят пузырьки газа? Странно. Может быть, это и есть ответ на наши вопросы, но уверенности нет. $B$BВпрочем, хоть какая-то зацепка. Спасибо, что нашел ее.', 'Ты побывал у Забытых прудов, Варабэй? Удалось что-нибудь выяснить?', NULL, NULL, 'Исследовать локацию', 'Исследуйте воды Забытых прудов.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (871, 'Прекратить набеги', 'Все свинобразы – наши враги, $N. Просто одни из них причиняют нам больше неприятностей, чем другие.$B$BКлан Иглогривых в последнее время нередко нападает на наши караваны из Дуротара, и терпеть это нет больше сил. Мои разведчики ищут главарей, но тем временем чем больший урон мы нанесем эти свиньям, тем лучше.$B$BСтупай на северо-восток, по направлению к Дуротару. Ты легко отыщешь их логова среди огромных колючих побегов, исходящих из земли. Отыщи их и убей, кого сможешь.', 'Убейте 8 водоискателей, 8 терноплетов и 3 охотников племени Иглогривых и возвращайтесь к Тхорку с Перекрестка.', 'Отличная работа, $N. Мерзавцы-иглоривы наконец-то научатся считаться с мощью Орды.', NULL, NULL, NULL, 'Водоискатель из племени Иглогривых убито', 'Терноплет из племени Иглогривых убито', 'Охотник из племени Иглогривых убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (872, 'Конец бесчинствам', 'Один из разведчиков своими глазами видел нападение на караван из Дуротара, $N. Естественно, виноваты свинобразы из племени Иглогривых. Возглавляет нападения Криниг Грознорыл. Его видели на северо-востоке отсюда, южнее дороги на Дуротар. Пока Криниг жив, покоя не будет.$B$BНо чтобы окончательно прекратить разбой, надо как следует унизить мерзких иглогривов. Убей Кринига Грознорыла и его приспешников и принеси мне его клык.', 'Убейте 8 геомантов и 8 защитников из племени Иглогривых и Кринига Грознорыла и возвращайтесь к Тхорку из Перекрестка.', 'Молодец, $N. Криниг мертв, и число нападений на караваны сократится.$B$BТвой народ должен гордиться тобой.', 'Отрежь голову их вожаку, и воцарится хаос. Хорошенько усвой этот урок. Он пригодится тебе в будущем.$B$BЭти свиньи будут метаться без цели, и мы захватим все Степи.', NULL, NULL, 'Геомант племени Иглогривых убито', 'Защитник племени Иглогривых убито', 'Клык Кринига Грознорыла', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (873, 'Иша Авак', 'Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость. Народ побережья страшится его, ибо он поглотил многих из их числа.$B$BНо я не боюсь его. Я благодарна провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник.$B$BЕсли ты $gготов:готова:, плыви на поиски Иши Авака, Рока Глубин.$B$BЕго дух содержится в сердце, и услышав, как оно бьется, можно узнать многое о своей судьбе.', 'Принесите сердце Иши Авака Марен Небесной Провидице. ', 'Теперь вы с Иши Аваком едины, $N. Его дух живет в тебе. Он таится в твоих глазах…$B$BГлазах, которые однажды научатся видеть.', 'Не бойся вод, $R.', NULL, NULL, 'Сердце Иши Авака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (874, 'Марен Небесная Провидица', 'Ты $gпоохотился:поохотилась: на многих зверей Степей. Дух твой тверд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его.$B$BИ даже море.$B$BНайди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя.$B$BИщи ее с осторожностью, потому что побережье Степей захвачено людьми.', 'Поговорите с Марен Небесной Провидицей.', 'Тебя прислал мой брат? Должно быть, ты произвел на него впечатление. А если тебя зауважал Джорн, то и я буду уважать.$B$BЖелаешь ли ты сделать следующий шаг на пути охотника?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (875, 'Лейтенанты гарпий', 'Ха-ха-ха, $N. Еще захотелось? Отлично, приятно слышать.$B$BНа сей раз я хочу, чтобы ты $gубил:убила: несколько лейтенантов гарпий в Сухих холмах. Лейтенантами бывают только душегубки из стаи Зачарованного Крыла. Их можно отличить от других по характерным кольцам. Неприятные твари, да еще и приспешников их там полно. Убей шестерых и нанеси мощный удар по этому бабьему царству.$B$BИ пусть подыхают долго и мучительно. Это научит их не связываться с Ордой.', 'Соберите 6 колец лейтенантов гарпий с душегубок из стаи Зачарованного Крыла и возвращайся к Дарсоку Быстрому Ножу.', 'Прекрасная работа, дружище. Думаю, ты достигнешь высокого положения в Орде.', 'Ты уже принес 6 колец лейтенантов гарпий? Пора свершить над ними суд и положить конец их нападениям на Орду.', NULL, NULL, 'Кольцо лейтенанта гарпий', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (876, 'Серена Кровавое Перо', 'Ты так хорошо $gсправился:справилась: с лейтенантами и приспешниками, что я хочу дать тебе еще одно поручение.$B$BСерена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар. Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры.$B$BПерережь ей горло и принеси мне ее голову. Я хочу прибить ее на переднюю телегу следующего каравана... Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас.', 'Убейте Серену Кровавое Перо и принесите ее голову Дарсоку Точному Ножу на Перекресток.', 'ХА! Молодец, $N! Отличная работа... Я не был уверен, что ты справишься с заданием, но, оказывается, ты головорез, каких поискать. Еще раз спасибо за избавление от нашествия гарпий. Вот награда, используй ее с умом.', 'Ты ничего не получишь, пока я не увижу голову Серены.', NULL, NULL, 'Голова Серены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (877, 'Застывший оазис', 'Быть может, и в других оазисах Степей есть расселины вроде той, что тебе удалось обнаружить в Забытых прудах? Коли так, скорее всего именно эти расселины – источник жизни оазисов.$B$BНадо проверить.$B$BВот, возьми эти семена. Сейчас они мертвые и бесплодные. Отнеси их в Застывший оазис на юго-востоке. Если там есть расселина, помести в нее семена... и понаблюдай.', 'Внимательно осмотрите Застывший оазис и возвращайтесь к Тонге Рунному Тотему в Перекресток.', 'Удивительное открытие! Я дал тебе иссохшие, мертвые семена. Значит, то, что таится в этих оазисах, создает жизнь из ничего!$B$BНеобходимо исследовать это явление повнимательнее...', NULL, NULL, NULL, 'Проверьте мертвые семена', 'Сушеные семена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (878, 'Воюющие племена', 'Отомсти моим врагам. *фыркает* Помоги Кривозубу и Иглогривым, ослабив племя Дыбогривов. Оба племени духовно связаны с землей и ее мощью. *фыркает* Она дарует нам силу, необходимую для всего... и прежде всего – для войны.$B$BЕсли ты в самом деле хочешь узнать, кто причинил Тхорку и Орде так много страданий, помоги Кривозубу! Напади на духовных вождей Дыбогривов на севере; подорви их мощь, чтобы Иглогривые одолели своих соперников и покорили Степи.', 'Убейте 6 водоискателей, 12 терноплетов и 12 геомантов из племени Дыбогривов и возвращайтесь к Кривозубу в Лагерь Таурахо в Степях.', 'Да-да... Меня должна переполнять радость, *фыркает* ведь племя Дыбогривов испытало ту же боль, что и мой народ, $R. Но нет, радости нет места. *фыркает*$B$BТы помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него. Его забыли, оставили гнить в клетке!$B$BЯ помогал им даже из-за решетки, но никто не пришел мне на помощь!', 'Орда получит сведения *фыркает*, только когда ты убьешь мудрецов племени Дыбогривов, $R. *фыркает* Ни минутой раньше! Кривозуб не дурак.', NULL, NULL, 'Водоискатель из племени Дыбогривов убито', 'Терноплет из племени Дыбогривов убито', 'Геомант из племени Дыбогривов убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (879, 'Предатель в наших рядах', 'Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, $r. *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрестке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает*$B$BИмена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, $r, как они убили меня.', 'Убейте Нака, Куза и Лока Оркобоя и принесите их черепа Кривозубу в Лагерь Таурахо в Степях.', 'Дело сделано. Кривозуб считает, уж лучше так. *фыркает* Надо было убедиться *фыркает*, что я мертв, а не бросать меня здесь, во всеми забытой клетке.$B$BТебе осталось лишь одно дело, $R.', 'И как идет охота, $R? *фыркает* Торк полагает, что знает, кто возглавляет набеги на его народ, *фыркает* но он поймет, как ошибался.$B$BМоя смерть неотвратима, но тебе удалось нанести серьезный урон моим врагам, и Кривозуб ни о чем не жалеет. *фыркает*', NULL, NULL, 'Череп Каза', 'Череп Нака', 'Череп Лока', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (880, 'Измененные существа', 'Ты рассказываешь невероятные вещи, $N. Источник свойств этих оазисов явно сторонний. Или, быть может, вообще потустороннй.$B$BЯ хочу узнать, какое влияние расселины оказывают на зверей, приходящий на водопой.$B$BУбей несколько оазисных хрустогрызов в Цветущем и Застывшем оазисах. Принеси мне их панцири, и я их пристально изучу.', 'Принесите 8 измененных панцирей зубастых черепах Тонге Руническому Тотему в Перекресток.', 'Спасибо, $N. Изучая обитателей различных мест, узнаешь немало о самих местах. Посмотрим, о чем нам поведают панцири.$B$BПрошу тебя, прими благодарность за помощь... Быть может, эти монеты тебе не помешают. Мне они уже не нужны.', 'Как идет сбор панцирей? Много набрал?', NULL, NULL, 'Измененный панцирь хрустогрыза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (881, 'Ичияки', 'Ичияки, Белый Туман на языке тауренов, король кошачьих саванны. Он подкрадывается к жертвам так незаметно, что его уподобили белому туману, стелящемуся над землей. Убивает он одним ударом – жертва не успевает ни испугаться, ни ощутить боли.$B$BТаурены говорят, что он воплощает собой милосердие и смерть.$B$BТы узнаешь это на своем опыте, потому что я отправляю тебя охотиться на Ичияки. Его логово располагается на северо-востоке от Перекрестка, среди костей огромного кодо.$B$BСтупай. Добравшись до логова, протруби в этот рог. Протруби в рог, и он явится на зов.', 'Принесите шкуру Ичияки Сергре Черный Шип на Перекресток.', 'Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой. Он научит тебя обретать силу в хитрости, а честь в милосердии.$B$BПеред тобой долгий путь, $C. Хочется верить, что ты далеко пойдешь.', 'Тебя ожидает великий кот, $N.', NULL, NULL, 'Шкура Ичияки', 'Рог Ичияки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (882, 'Ишамухал', 'Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия. Охота – его страсть. Он убивает потому, что сам убийца по природе.$B$BИменно о его природе тебе и предстоит узнать многое, $N, ибо твой путь теперь поведет тебя по когтистым следам Ишамухала.$B$BНачинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мертвому дереву на северо-западе от Кабестана. Ишамухал почует тушу и явится на ее запах.$B$BБудь $gготов:готова: к его появлению.', 'Принесите клык Ишамухала Джорну Искателю Неба в Лагерь Таурахо.', 'Клык – всего лишь символ, но символ очень важных вещей.$B$BТеперь в тебе есть сила Ишамухала, $N. Пользуйся ей, но соблюдай умеренность. Отныне это твоя ноша.$B$BИ это великая честь.', 'Удалось ли тебе одолеть Ишамухала, $N?', NULL, NULL, 'Клык Ишамухала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (883, 'Лакота\'мани', 'Копыто Лакота\'мани – символ силы великого кодо.', 'Принесите копыто Лакота\'мани Джорну в Лагерь Таурахо.', 'Лакота\'мани на нашем языке означает \"Землекрушитель\", ибо шаги его громоподобны. Теперь он пребывает с тобой, к тебе перешло все его мужество. Отныне ты не побоишься встретиться с любой опасностью.$B$BВерь в себя, $N. Верь в себя, Землекрушитель.', 'Мопедгоша, я вижу в твоих глазах сияние новой силы! Скажи, ты встретился с великим Лакота\'мани?', NULL, NULL, 'Копыто Лакота\'мани (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (884, 'Оватанка', 'При касании от хвоста Оватанки летят искры.', 'Принесите хвостовой зубец Оватанки Джорну Искателю Неба в Лагерь Таурахо.', 'Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о ее стремительности не стоит судить по размеру. Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой.$B$BНыне ее неутомимость передалась тебе, $N. Теперь ты не отстал бы от Оватанки.', '$N, я вижу в твоих глазах сияние новой силы! Тебе удалось встретиться с могучей Оватанкой?', NULL, NULL, 'Хвостовой зубец Оватанки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (885, 'Ваште Пауни', 'Пера Ваште Пауни больно касаться.', 'Отнесите перо Ваште Пауни Джорну Заклинателю Небес в Лагерь Таурахо.', 'Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок.$B$BНо смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое... Или оба сразу.$B$BБоль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой. Внутренние терзания же – следствие сожалений.$B$BВпрочем, я вижу, что ты справился с этими искушениями и познал, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу.$B$BТы многое познал, $N.', 'Я вижу, ты исполнен решимости, $N. Решимости, порожденной страданием…$B$BТебя тяготит гибель Ваште Пауни?', NULL, NULL, 'Перо Ваште Пауни (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (886, 'Оазисы Степей', 'Друиды Громового Утеса ощущают странную силу, просачивающуюся в Степи к, востоку от Мулгора.$B$BМы отправили найти источник этой силы Тонгу Рунического Тотема, но, похоже, ему нужна помощь.$B$BОтправляйся в Степи и поговори с Тонгой. Он будет в Перекрестке. Иди туда по дороге на восток от Деревни Кровавого Копыта. Как попадешь в Степи, сверни на развилке на север. И продолжай идти, пока не упрешься в Перекресток.$B$BС дороги не сходи, $N, ибо Степи – край суровый.', 'Поговорите с Тонгой Руническим Тотемом на Перекрестке в Степях.', 'Мои собратья в Громовом Утесе мудро поступили, прислав тебя сюда, юный $С. Ибо тайну Степей мне в одиночку не раскрыть.$B$BБудем надеяться, что с твоей помощью мы найдем ответ на наш вопрос.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (887, 'Флибустьеры Южных морей', 'Жаль, что вице-адмиралу Греззлику не удалось добиться безопасности в наших водах для торговых кораблей. В торговый флот вложено столько денег, что я просто зверею, когда пираты как нечего делать нападают на мои корабли и похищают товары! $B$BГоворят, что флибустьеры Южных морей разбили лагерь к югу отсюда. Они мне как бельмо на глазу, и если ими не хочет заняться Греззлик, может быть, ты поможешь избавиться от них?', 'Убейте 12 грабителей Южных морей и 6 канониров Южных морей по просьбе Газлоу из Кабестана.', 'Молодец, малыш. Побольше таких подвигов, и у меня станет одной проблемой меньше. Хочется верить, что они решат перенести свой лагерь.$B$BОстается одно – вернуть украденные товары!', 'Мне даже думать тошно о том, сколько я денег потерял из-за проклятых пиратов. А теперь они еще и лагерь у меня под носом разбили? Это уже наглость. Надо что-то с этим делать.', NULL, NULL, 'Грабитель из братства Южных Морей убито', 'Канонир из братства Южных Морей убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (888, 'Украденное добро', 'Хоть я и хотел бы вернуть все товары, думаю, это невозможно. Но некоторые из них мне очень нужны!$B$BКак видишь, моя обсерватория почти готова, но ей не хватает двух малых линз. Первая из них прибыла с караваном из Дуротара, но вторую везли на корабле, который ограбили пираты. Кроме того, до меня так и не дошла партия сапог от Дриззлика из Пиратской Бухты!$B$BСтупай в пиратский лагерь и поищи их.', 'Верните Газлоу из Кабестана посылку с сапогами и линзу от телескопа.', 'Я так рад, что вернул свое добро! Спасибо за помощь, $N. Знаешь, мне пригодились бы помощники вроде тебя. Если понадобится работа, не забывай, что Газлоу неплохо платит!', 'Ну что, удалось найти мои вещи?', NULL, NULL, 'Партия сапог', 'Линза от телескопа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (889, 'Дух ветра', '', '', 'Хорошо. Да ведет тебя дух Агамаггана, $R. Возвращайся, если захочешь вновь соприкоснуться с магией Агамаггана.', NULL, NULL, NULL, 'Кровавые осколки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (890, 'Пропавший груз', 'Я уже сто лет жду последнего заказа из Пиратской Бухты! Наверняка его перехватили флибустьеры, но на всякий случай сходи в порт и спроси у Головокружилкинса, вдруг товары без моего ведома отнесли на склад?$B$BВот, отнеси мою учетную книжку Головокружилкинсу, пусть сверит со своими записями.', 'Отнесите учетную книжку Газлоу управляющему пристанью Головокружилкинсу. ', 'А, так тебя прислал Газлоу? Минутку, дай-ка я загляну в свои записи, надо убедиться, что я не отправил товар Газлоу куда-то не туда.$B$BНебось, он ждет поставку сапог от Дриззлика...', 'Хочешь отправить товар со следующим кораблем, $N?', NULL, NULL, 'Гроссбух Газлоу (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (891, 'Пушки крепости Северной Стражи', 'Вот и еще один мой корабль захватили рьяные людишки из крепости Северной стражи!$B$BПора разобраться с этими мерзавцами. Их паранойя перешла все мыслимые границы. Эти безрассудные любители спускать курок стреляют во все, что движется.$B$BОтправляйся на юг вдоль Торгового побережья, найди их крепость и брось вызов их силе. Принести в доказательство собственных подвигов медали их солдат. И во имя моего флота, убей капитана Гордостанную и ее рьяных канониров!', 'Капитан Тало\'тас Сияющий поручил вам собрать 10 тераморских медалей и убить капитана Гордостанную, канонира Вессана и канонира Смайта.', 'Ах, какая жалость, праведные пушки Альянса умолкли. Ты получишь награду за помощь, $N.$B$BКак бы теперь выручить тела наших погибших...', 'Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.', NULL, NULL, 'Капитан Гордостанная убито', 'Канонир Вессан убито', 'Канонир Смайт убито', 'Медаль Терамора');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (892, 'Пропавший груз', 'У меня в записях все в порядке, $N. Ступай к Газлоу и скажи, что ему не повезло. Не удивлюсь, если его товары прибрали к рукам пираты. $B$BЯ ничем не могу ему помочь. А, да... Скажи, что у меня есть для него кое-что из Нижней шахты, пусть приходит и забирает.', 'Верните Газлоу из Кабестана его регистр.', 'Вот непруха... Наверняка это корсары... Дыбоволос тут ни при чем, я уверен, он не стал бы так меня обманывать. В конце концов, он получает деньги за доставку.$B$BПохоже, мне придется вернуть себе кое-какие товары. Что скажешь?', 'Ну и что сказал Дыбоволос?', NULL, NULL, 'Гроссбух Газлоу (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (893, 'Предпочитаемое оружие', 'Хотя говорят, что у свинобразов племени Иглогривых за Полями Великанов нет искусных кузнецов, они научились делать серьезное оружие. Мне хотелось бы получить несколько образцов, чтобы изучить их технику работы.$B$BЕсли ты стремишься к подвигам во славу Орды, добудь для меня их оружие. Мне понадобятся кинжал, жезл и щит. Этого вполне хватит!', 'Принесите ст$N Иглогривых, обгоревший жезл Иглогривых и боевой щит Иглогривых Таттернаку Стальному Горну в Лагерь Таурахо в Степях.', 'Прекрасные, прекрасные образцы.$B$BСвинобразы куда более умелый народ, чем мне казалось.$B$BВот, возьми это и убирайся. Мне надо получше изучить это оружие. Похоже, мы недооценивали врага, а такие ошибки недопустимы.', 'У меня тоже есть сомнения насчет того, что жалкие иглогривые могли научиться кузнечному делу, но я выполняю приказы вождя, и потому стараюсь узнать побольше о племени Иглогривых.$B$BУ меня бывали задания и попротивней, но я с радостью выполняю их, чтобы служить народу орков.', NULL, NULL, 'Стилет Иглогривых', 'Обгоревший жезл Иглогривых', 'Боевой щит Иглогривых', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (894, 'Самофланж', 'Торговая Компания устроила к северу отсюда, в юго-западной части Нефтяного болота, небольшой исследовательский центр. Я не очень хорошо представляю, чем они занимаются, но до меня дошли сведения, что они проводят эксперименты со штукой под названием \"самофланж\".$B$BЧто еще за самофланж? Как бы то ни было, я хочу исследовать его, а значит, мне надо его заполучить.$B$BМне удалось достать копию их руководства пользователя. Почитай его, там наверняка написано, как вытащить самофланж из терминала.', 'Получите доступ к терминалу в исследовательском центре Торговой Компании.', 'На панели управления в беспорядке разбросаны кнопки, рычаги и мигающие лампочки. Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны 1-3 открыты. В нижнем правом углу панели управления имеется небольшая замочная скважина.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (895, 'Разыскивается: Барон Дольноберег', 'РОЗЫСК! $B$BРазыскивается барон Дольноберег, капитан \"Безрассудной\".$B$BКапитан Дольноберег из Гилнеаса водит корабли корсаров Южного моря. Он разыскивается по обвинению в пиратских нападениях. Предоставленные останки должны быть пригодны для опознания!$B$B- Газлоу.', 'Принесите Газлоу в Кабестан голову барона Дольноберега. ', 'А! Вот какое у тебя дело. Знаешь, я однажды видел \"Безрассудную\" в открытом море. Впечатляющий корабль. Или судно? Эти моряки так придираются к словам!$B$BВ общем, она так скользила по водной глади, что дух захватывало. Я рад, что ее проклятый капитан перестанет тревожить мои корабли.', 'Что происходит? Чем могу служить? Отправить груз, или, может быть, инженер понадобился?', NULL, NULL, 'Голова Барона Дольноберега', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (896, 'Удача шахтера', 'Хозяин причала в таком оживленном порту, как Кабестан, держит руку на пульсе происходящего. Я в курсе всего товарообмена между нашим городом и Пиратской бухтой.$B$BПоследние слухи касаются Каменного карьера, принадлежащего Торговой Компании, что на северо-востоке от Нефтяного болота. Один из шахтеров нашел изумруд размером с твой кулак. Я знаю несколько покупателей на такой товар и готов поделиться с тобой комиссией.', 'Заберите изумруд \"Кошачий глаз\" у одного из надзирателей или головорезов Торговой Компании и отдайте его управляющему пристанью Головокружилкинсу в Кабестане.', 'Только посмотри, какой он огромный, $N! Теперь мы разбогатеем! Ну-ка, судя по расценкам на драгоценные камни, я могу прикинуть твою долю... Пятьдесят процентов, будь спок!$B$BПосчитаем... Да, примерно так. С тобой приятно иметь дело, $N.', 'Если бы мы знали, кто именно нашел этот изумруд, дело выеденного яйца не стоило бы...', NULL, NULL, 'Изумруд \"Кошачий Глаз\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (897, 'Жнец', 'Это странное, похожее на насекомое существо выглядит так, будто попало в Степи случайно.', 'Принесите голову Жнеца Джорну Заклинателю Небес. ', 'Не могу ничего сказать о природе этого зверя, ведь духа его и след простыл. Но ты верно говоришь, он не из Степей. Боюсь, наш народ ожидают испытания…$B$BА пока готовься к худшему. Будем надеяться, что со временем мы разгадаем тайну этого существа.', 'Тебя что-то тревожит, $N. Как твои уроки в Степях? Что тебя так обеспокоило?', NULL, NULL, 'Голова жнеца (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (898, 'Свобода!', 'Наконец-то! Кто-то пришел мне на помощь!$B$BПоверить не могу, что тебе удалось пройти мимо стражей. Фанатики из Терамора совсем спятили. Они потопили наш корабль и меня, единственного выжившего, взяли в плен. Меня назвали врагом и угрозой безопасности Альянса.$B$BЯ! Угроза великому и могучему Альянсу? Я был матросом на грузовом судне, возившем самогон из Кабестана в Пиратскую Бухту.$B$BДовольно болтать. Ты ведь поможешь мне вернуться в Кабестан? Скажи, когда решишь тронуться в путь, и мы совершим побег.', 'Проводите Гилтареса Огненный Цветок к капитану Сияющему в Кабестан.', 'Подумать только, мы полагали, что Огненный Цветок давно погиб!$B$BТы заслужил уважение всех Тало\'данских каперов, $N.', 'Да?', NULL, NULL, 'Проводите Гилтареса Огненный Цветок в Кабестан.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (899, 'Огонь ненависти', 'Быть может, тебе знакома мука неопределенности, а может, и нет. Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть. Быть может, мне стоило идти не на север к Перекрестку, а в Таурахо.$B$BТы, $C, $gмог:могла: бы мне помочь.$B$BУбей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах.', 'Принесите Манкрику с Перекрестка 60 клыков свинобразов из племени Дыбогривов.', 'Воин, ты отнесся к моему заданию серьезно, спасибо тебе за это.$B$BХотя жажда мести не утолена, я могу хотя бы улыбаться при мысли о том, что и иглогривы испытали ту же боль, что и я.', 'Иглогривы за все заплатят, $N. Клянусь.', NULL, NULL, 'Клык свинобраза из племени Дыбогривов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (900, 'Самофланж', 'В настоящий момент открыты три контрольных клапана. Суда по надписям на панели управления, их надо закрыть, прежде чем выключать прибор.', 'Закройте топливный распределительный клапан, перепускной клапан и главный клапан управления, а потом снова попытайтесь воспользоваться панелью управления.', 'Лампочки, относящиеся к трем управляющим клапанам, медленно гаснут. Зеленый огонек становится желтым, и теперь можно повернуть рычажок, выключающий прибор. Клапаны закрыты, и терминал можно отключить.', 'Судя по мигающим лампочкам на панели управления, основные клапаны не закрыты.', NULL, NULL, 'Перекройте главный клапан управления', 'Перекройте топливный распределительный клапан', 'Перекройте перепускной клапан', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (901, 'Самофланж', 'Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала. Все бы хорошо, но чтобы отпереть терминал, нужен ключ.', 'Возьмите у ремонтника Угрелова ключ от терминала и отоприте им панель управления.', 'Повернув ключ в замке, вы открываете панель управления. В верхней части терминала гаснет красная лампочка. Теперь он полностью обесточен.', 'Лампочки на панели потухли, стрелки всех приборов на нуле, все бездействует.', NULL, NULL, 'Ключ от терминала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (902, 'Самофланж', 'Под панелью управления оказывается мешанина проводов, ламп и прочих загадочных механических объектов – кажется, большая часть там вообще не нужна. Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж. Одного усилия хватает, чтобы вытащить его из паза.', 'Отнесите самофланж Пароклапану в Кабестан.', 'Это... Э... Любопытно... Да. Я пошлю его в Союз ремонтников Нижней шахты. Не сомневаюсь, что эту штуку исследуют и поймут, для чего она нужна.$B$BВпрочем, сначала надо самому посмотреть что к чему...', 'А, вот и ты, $N! Принес самофланж?', NULL, NULL, 'Самофланж (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (903, 'Хищники Степей', 'Пришло время поохотиться на тех, кто может постоять за себя. Хищники саванны, живущие в Степях – сильные звери. Сильные, могучие, хитрые и опасные. Их можно найти в высокой траве на юго-западе от Перекрестка.$B$BСоблюдай осторожность, иначе можешь неожиданно превратиться из охотника в дичь.', 'Принесите 7 когтей хищников саванны Сергре Черный Шип на Перекресток.', 'А, вижу, ты времени даром не терял, а прятался в траве, выслеживая хищников. Как ты думаешь, пришло ли время встретиться лицом к лицу с сильнейшим из них?', 'Как успехи на охоте? Удалось найти хищников?', NULL, NULL, 'Когти хищника саванны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (905, 'Разъяренные смертехваты', 'Что ж, $N, теперь твоя задача усложняется. Сначала тебе надо победить свою добычу, а потом отыскать ее логово.$B$BЯ предлагаю поохотиться на яркочешуйчатых ящеров, живущих на юге. Убей их и забери перья. Отнеси перья в их гнезда на юго-западе от Застывшего оазиса. Покажи их сородичам, что ты не боишься!', 'Поохотьтесь на яркочешуйчатых ящеров и соберите с них перья. Отнесите перья в 3 гнезда когтедеров. Возвращайтесь к Сергре Черный Шип в Перекресток.', 'Значит, ты побывал возле гнезд и поместил в них перья? На это требуется немало мужества.$B$BТы чувствуешь, что стал сильнее, $N? Выглядишь ты куда крепче, чем в тот миг, когда явился сюда в первый раз. Думаю, Степи сыграли в этом свою роль.', NULL, NULL, NULL, 'Посетите синее гнездо ящера', 'Посетите желтое гнездо ящера', 'Посетите красное гнездо ящера', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (906, 'Предатель в наших рядах', 'Отнеси голову Лока Тхорку на Перекресток, $r. *фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах. Но я не сомневаюсь, что он наградит тебя за совершенный подвиг. *фыркает*$B$BПока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай.', 'Отнесите череп Лока Тхорку на Перекресток.', 'Тебе удалось найти главаря племени Иглогривых и собственноручно убить его, $N? Поразительно.$B$BУ меня нет слов, но это не значит, что я не благодарен тебе. Жители Перекрестка должны уважать твою силу.$B$BДолжен признать, я считал, что возглавляет налеты на наши обозы другой свинобраз. Еще раз спасибо, $N.', 'Да, что такое?', NULL, NULL, 'Череп Лока (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (907, 'Разъяренные рокочущие ящерицы', 'Пришло время выступить против рокочущих ящериц. Они столь огромны, что земля дрожит под их шагами. Сражаясь с ними, соблюдай осторожность: один неверный шаг – и они стопчут тебя.$B$BЯщерицы живут в южной части Степей. Их называют грозорылами, грозошкурами и громоголовами. Возвращайся ко мне с победой.', 'Отнесите 3 порции крови рокочущей ящерицы Джорну Искателю Неба в Лагерь Таурахо.', 'Я рад, что ты принес доказательство своего торжества. И особенно здорово, что у тебя все кости остались целы.', 'Тебе удалось одолеть рокочущих ящериц, $N?', NULL, NULL, 'Кровь рокочущей ящерицы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (908, 'Среди руин', 'Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины. Их присутствие приведет лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда.$B$B$N, ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!', 'Принесите глубинный сердечник Дже\'неу Санкри в форт Зорам\'гар в Ясеневый лес.', '', NULL, NULL, NULL, 'Глубинный сердечник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (909, 'Барон Акванис', 'Сраженный элементаль воды оставил после себя странную сферу. Вы предполагаете, что этот предмет каким-то образо подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость. Сама сфера вроде бы не поддается никаким физическим воздействиям.$B$BЕсли кто и сможет понять, что это за штука, то это Дже\'неу Санкри из Служителей Земли. Он находится в форте Орды Зорам\'гар в Ясеневом лесу.', 'Принесите странную водяную сферу Дже\'неу Санкри в форт Зорам\'гар в Ясеневом лесу.', '', NULL, NULL, NULL, 'Странная водяная сфера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (910, 'В порту', 'Я слышал, что между Кабестаном и Пиратской Бухтой плавают огромные корабли! Вот бы мне поплавать по океану и принять участие в морских боях. Может быть, когда я вырасту, я стану великим моряком Орды! Да!$B$BПожалуйста, своди меня в Кабестан, посмотреть на порт. Обещаю, я не свалюсь в воду и буду хорошо себя вести – мне бы посмотреть на корабли и вдохнуть запах соленой морской воды! Да!', 'Отведите своего подопечного в порт Кабестана в Степях.', '', NULL, NULL, NULL, 'Исследовать локацию', 'Сходить в порт Кабестана в Степях', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (911, 'Врата пограничья', 'Говорят, что Ясеневый лес – это новое пограничье, а врата к нему – Застава Мор\'шан. Здорово быть первооткрывателем, добывать все необходимое из первозданного леса! Говорят, что именно там будут греметь битвы между Ордой и Альянсом. Вот бы мне попасть туда!$B$BОтведи меня к заставе Мор\'шан, посмотреть на новое пограничье! Я хочу посмотреть, как Орда выгонит оттуда вонючих ночных эльфов!', 'Отведите своего подопечного к Заставе Мор\'шан в северной части Степей на границе с Ясеневым лесом.', '', NULL, NULL, NULL, 'Исследовать локацию', 'Ступайте на Заставу Мор\'шан в Степи.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (913, 'Крик грозового змея', 'Грозовой змей – лютый зверь, $N. И все же ты уже $gготов:готова: бросить ему вызов. Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты.$B$BВыполни мое задание, и твое обучение подойдет к концу.', 'Отыщите и убейте грозового змея. Принесите его крылья Джорну Заклинателю Небес в Лагерь Таурахо.', 'Тебе есть чем гордиться, ведь ты одолел всех врагов, явив силу, мужество и честь.$B$BНе останавливайся, следуй дальше по своему пути, $N. Более того, жизнь настоящего охотника – постоянная борьба. Ступай же с высоко поднятой головой по избранному тобой пути.$B$BПора.', 'Задание выполнено? Тебе удалось убить грозового змея?', NULL, NULL, 'Крылья Грозового змея', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (914, 'Повелители Змей', 'Друиды Клыка в Пещерах Стенаний поражены порчей. Когда-то они были частью ордена, давшего обет исцелить Степи, но теперь хотят перекроить эти земли в соответствии со своими извращенными представлениями о порядке.$B$BУ друидов Клыка четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах. Убей предводителей друидов, принеси мне их камни, и в Степях снова воцарится мир.$B$BИди, $N, и разыщи их укрытия в Пещерах Стенаний.', 'Принесите камни Кобрана, Анакондры, Пифаса и Серпентиса Наре Буйногривой, на Громовой Утес.', 'Ты сделал это, $N. Ты убил друидов Клыка, теперь мои сны свободны от их присутствия. Ты спас Степи, и я благодарю тебя от своего имени, от имени друидов Громового Утеса и от имени этой земли.', 'Меня преследуют воспоминания о моих кошмарах, $N. Удалось ли тебе убить отступников и завладеть их кристаллами?', NULL, NULL, 'Самоцвет Кобрана', 'Самоцвет Анакондры', 'Самоцвет Питонаса', 'Самоцвет Серпентиса');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (915, 'Женщинам – цветы, детям – ...', 'Мороженое! Пожалуйста-пожалуйста-пожалуйста, добудь для меня немного мороженого!!! Я больше всего люблю клубничное, а самое лучше клубничное мороженое делает Тигуль! Это мое самое любимое мороженое на свете!$B$BЯ пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе! Пожалуйста! Пожалуйста-препожалуйста! Преогромное пожалуйста!!!!', 'Купите своему подопечному клубничное мороженое. Кажется, мальчик предпочитает мороженое Тигуля.', '', NULL, NULL, NULL, 'Клубничное мороженое Тигуля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (916, 'Яд чащобного паука', 'Я пришел в Тенистую долину, чтобы наблюдать за чащобными тенетниками, обитающими в Паучьем логове. Они – родичи более мелких разновидностей пауков. Полагаю, что Древо Жизни оказало на них сильное воздействие... Я хотел бы получить несколько вещей, чтобы изучить их и подтвердить свои догадки.$B$BДля начала мне понадобится немного их яда. Добудь ядовитые железы у пауков-тенетников в Паучьем логове и вокруг него, к северу отсюда. После этого я смогу изучить эти образцы и понять, есть ли у этого яда сходство с ядом их более мелких сородичей.', 'Принесите 10 ядовитых желез чащобных тенетников Гилшалану Буйному Ветру, стоящему у Альдрассила.', 'Благодарю тебя, $N. Когда я вернусь в Дарнасс, я первым же делом сравню образцы яда из этих желез с ядами других пауков. Полагаю, что некоторые свойства яда связаны с ростом нового Древа Жизни.', 'Тебе удалось собрать ядовитые железы, $N?', NULL, NULL, 'Ядовитая железа чащобного тенетника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (917, 'Яйцо чащобного паука', 'Теперь, когда у меня есть паучий яд, мне хотелось бы получить для изучения живой образец. Не волнуйся, я не могу просить тебя поймать гигантского паука живьем. Да и мне самому вряд ли удалось бы справиться с таким \"образцом\"!$B$BНо если ты принесешь яйцо, из которого еще не вылупился паучок, то получить образец будет куда легче, не говоря уж о том, чтобы содержать.$B$BВ глубинах Паучьего логова должно быть гнездо. Прошу тебя, найди его, возьми оттуда яйцо паука и принеси мне.', 'Принесите яйцо чащобного тенетника Гилшалану, стоящему у Альдрассила.', 'О, отлично. Я отправлю яйцо и яд в Дарнасс, а потом и сам вернусь туда, когда мои изыскания здесь будут завершены. Я многого ожидаю от этих образцов, $N. Твоя помощь оказалась поистине бесценной.', 'Тебе удалось проникнуть в Паучье логово, $N? А найти паучье яйцо?', NULL, NULL, 'Яйцо чащобного паука', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (918, 'Саженцы древесника', 'Древесники Тельдрассила – духи Природы. Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе.$B$BПотому меня очень тревожит, что древесники становятся такими озлобленными.$B$BМне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников. Не $gмог:могла: бы ты собрать для меня этих саженцев вокруг озера Аль\'Амет?', 'Принесите 8 саженцев древесников Деналану к озеру Аль\'Амет.', 'Ты их добыл. Славно!$B$BЯ посажу их в специально подготовленную почву. Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных. Может, позже ты еще увидишь результаты!', 'Ты добыл саженцы? Мне не терпится посадить их.', NULL, NULL, 'Саженец древесника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (919, 'Ростки древесника', 'Вокруг вод озера Аль\'Амет прорастают маленькие древесники. Боюсь, им уже не помочь, нам придется выдернуть их из земли прежде, чем они станут слишком большими и начнут приносить беды.$B$BКогда будешь бродить вокруг озера, выдергивай каждый росток древесника, что попадется тебе по дороге. Помоги очистить нашу землю!', 'Принесите 12 ростков древесника Деналану к озеру Аль\'Амет..', 'Как много! Они распространяются с ужасающей скоростью. Надеюсь, мне удастся разгадать, что же за порча поразила их.$B$BБлагодарю за помощь, $N. Этот край благодаря твоим усилиям стал чище.', 'Добро пожаловать, $N. Нашел ли ты ростки у озера?', NULL, NULL, 'Побег древесника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (920, 'Зов Тенарона', 'Ты $N, не так ли? До меня доходили слухи, что тебя искал Тенарон. Ты отыщешь его в самой верхней комнате на вершине Альдрассила.$B$BХоть мы и живем долго, не стоит заставлять Тенарона ждать.', 'Поговорите с Тенароном Хваткой Бури. Он ждет вас на вершине Альдрассила в Тенистой долине.', 'А, $N. Я думал, что ты быстрее откликнешься на мой призыв. У меня есть важное задание, которое я хочу поручить тебе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (921, 'Венец Земли', 'Пришло время тебе отправиться на поиски своей судьбы, $N. Но чтобы подготовиться к встрече с миром за пределами наших зачарованных лесов, тебе нужно больше узнать о нашей недавней истории.$B$BМногое изменилось для нашего народа со времен битвы за гору Хиджал. Нордрассил ныне – лишь бледная тень того, чем он некогда был, его сила ушла на то, чтобы одолеть Архимонда и отбросить прочь Пылающий Легион...$B$BТебе нужно исполнить важное поручение. Принеси мне воды из лунного колодца к северу от Альдрассила.', 'Наполните хрустальный фиал и отнесите его Тенарону Хватке Бури, обитающему на вершине Альдрассила.', 'Тебе уже довелось услышать первую часть истории о последствиях битвы за гору Хиджал, однако еще многое нужно рассказать, и выполнение задания, данного мной тебе, будет продолжаться на протяжении всего твоего путешествия через Тельдрассил в Дарнасс.', 'Лунные колодцы содержат воду Источника Вечности, древнего источника магии, который навлек на наш мир так много ужасов.$B$BДруиды пользуются свойствами колодцев, а Стражи чтят их как святилища Элуны, но использовать магию колодцев запрещено всем.', NULL, NULL, 'Наполненный хрустальный фиал', 'Исследовать локацию', 'Хрустальный фиал', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (922, 'Релиан Зеленый Костер', '$N, не $gмог бы ты:могла бы ты: доставить один из тех ростков, что ты $gпринес:принесла: мне, моему другу, Релиану Зеленому Костру? Он друид из Дарнаса. Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками. У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом.$B$BБлагодарю тебя, $N. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов.$B$BРелиана обычно можно найти на какой-нибудь из дорожек Анклава Кенария в Дарнасе, он любит там гулять.', 'Принесите росток древесника Релиану Зеленому Костру в Дарнас. ', 'А, росток древесника? Я хотел попытаться сам вырастить древесника, чтобы помочь Деналану в его изысканиях.$B$BК сожалению, я выяснил, что множество древесников поражено порчей, и ростки таких существ также наследуют ее от родителей. И не в моих силах это исправить.$B$BУ Деналана великий талант работать со всем, что растет. Если кто и найдет исцеление для будущих древесников, то это он. Возможно, он - наша последняя надежда.', 'Привет тебе...$B$BЧем могу помочь?', NULL, NULL, 'Саженец древесника (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (923, 'Опухоли', 'Древесники становятся все более злобными. Мы пытаемся найти источник этой беды, но пока... чтобы уберечь Тельдрассил, нам приходится уничтожать древесников, которым уже не поможешь. Те, что бродят вокруг Родникового озера на севере, поражены порчей сильнее всего. Их надо уничтожить!$B$BУничтожь всех древесников, которых там найдешь, и собери растущие на них мшистые опухоли. Принеси их мне, чтобы я мог их сжечь.', 'Принесите 5 мшистых опухолей Релиану Зеленому Костру в Дарнас.', 'Хорошая работа! Эти опухоли – симптом болезни древесников. Они наполнены ядом, от которого мы должны очистить наши новые земли.$B$BЯ уничтожу эти опухоли. Благодарю тебя, $N.', 'Ты был у Родникового озера, $N? Удалось поохотиться там на древесников?', NULL, NULL, 'Мшистая опухоль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (924, 'Демоново семя', 'Демоново семя – страшное оружие Пылающего Легиона. Оно хранится в пещере на Вершине Багрового Тумана, над демоническим алтарем Огня.$B$BЯ подготовил силовые камни, которые разорвут связь Семени с Легионом.$B$BВозьми камень со стола и возложи его на алтарь Огня на Вершине Багрового Тумана. Отправляйся на запад, а на развилке сверни на север. Вершина окажется по левую руку от тебя. Безопаснее всего подниматься по северному склону. $B$BТоропись: сила камня постепенно иссякает.', 'Возьмите треснувший камень силы, возложите его на алтарь Огня до окончания его действия и возвращайтесь к Ак\'Зелоту.', 'Твоя цель достигнута. Тебе удалось уничтожить Демоново семя, как велел Нииру. Но это еще не конец…$B$BПосле уничтожения Демонова семени по всему астралу пошли волны небывалой силы. Их почувствовала не только я. Об этом узнают те, чью игрушку мы сломали…$B$BВпрочем, невзирая на грядущие испытания, я хочу вручить тебе кое-что. Нииру велел дать это в уплату и поблагодарить тебя.$B$BИтак, я благодарю тебя.', NULL, NULL, NULL, 'Уничтожьте Демоново семя.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (925, 'Отпечаток копыта Кэрна', 'Говорят, что Кэрн Кровавое Копыто – один из величайших героев Орды. Когда я вырасту, я тоже хочу стать героем Орды!$B$BТы $gзнаком:знакома: с Кэрном? Окажи мне услугу! Возьми у него отпечаток копыта! Я не знаю, как его попросить, у него нет времени на таких, как я... другое дело ты! Ты $gтакой же искатель:такая же искательница: приключений, как и он! Готов поспорить, что тебе получить у него отпечаток копыта – раз плюнуть!$B$BПожалуйста!', 'Отправляйтесь в Громовой Утес и постарайтесь получить отпечаток копыта Кэрна Кровавого Копыта для своего подопечного.', '', NULL, NULL, NULL, 'Отпечаток копыта Кэрна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (926, 'Треснувший камень силы', '', '', 'Эти камни исполнены магической энергии, но в каждом из них есть умышленный изъян. Они не слишком стабильные, и если взять их со стола, они быстро поглотят сами себя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (927, 'Сердце, поросшее мхом', 'Сердце Черномшеца Злосмрадного поросло темным маслянистым мхом. Понять, что это сердце, можно лишь по тому, что оно медленно и ритмично пульсирует... Даже сейчас. $B$BВозможно, это заинтересует Деналана.', 'Принесите поросшее мхом сердце Деналану к озеру Аль\'Амет.', '...Это еще что такое? Сердце древесника? Оно все поросло вонючим мхом!$B$BХорошо, что ты принес его мне, $N. Я исследую это сердце и, если удача повернется ко мне лицом, выясню, что это за мох на нем.', 'О, $N! Ты что-то мне принес?', NULL, NULL, 'Сердце, поросшее мхом (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (928, 'Венец Земли', 'Я мог бы поведать тебе еще многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждет тебя. Я перелил воду из фиала, принесенного тобой, в этот сосуд, чтобы ты $gотнес:отнесла: его Коритрасу.$B$BТы найдешь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернет на запад, следуй по пути, мощенному булыжниками.$B$BИ советую тебе не сходить с дороги, $N, – в последнее время в лесу появились опасные существа.', 'Отнесите частично наполненный сосуд Коритрасу Лунному Гневу в Доланаар.', 'А, понятно. Тебя послал Тенарон. Ну что ж, похоже, нам о многом нужно поговорить, многое сделать – но времени мало.$B$BДумаю, лучше не медлить и приступить к делу сейчас же.', 'Привет тебе, $C. Чем обязан удовольствию встречи с тобой?', NULL, NULL, 'Наполовину полный сосуд (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (929, 'Венец Земли', 'Сначала позволь поведать тебе, какая стоит перед тобой задача. Друиды Дарнаса пользуются водой из лунных колодцев Тельдрассила, и временами их колодцы надо пополнять. При помощи этих специально изготовленных фиалов ты сможешь набирать воду из лунных колодцев.$B$BОтнеси этот сосуд к лунному колодцу у деревни Звездного Ветра на востоке и набери из него немного воды, а затем возвращайся ко мне. Когда ты выполнишь это задание, я продолжу свой рассказ с момента, на котором его прервал Тенарон...', 'Наполните нефритовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар.', 'После битвы за гору Хиджал мы не знали, что делать дальше. Нордрассил дымился, опаленный огнем, и наше бессмертие – сама сущность нашего бытия! – было утрачено. $B$BИменно в эту пору испытаний Предатель вырвался из заточения и исчез Шан\'до Ярость Бури. Настали темные времена.', 'С возвращением, $N. Исполнил ли ты поручение?', NULL, NULL, 'Наполненный нефритовый фиал', 'Исследовать локацию', 'Нефритовый фиал', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (930, 'Светящийся плод', 'Под ветками этого светящегося растения висит большой круглый плод.$B$BВы уверены, что Деналану захочется его изучить.', 'Принесите светящийся плод Деналану к озеру Аль\'Амет. ', 'Ты нашел его на Тельдрассиле? Как интересно... Такой необычный плод. Может, семена занесло издалека? Может, даже из Азерота! И что-то в нем есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила.$B$BСпасибо тебе, $N. Теперь извини, мне нужно попристальнее его поизучать...', 'Похоже, ты что-то хочешь мне рассказать, $N? Ты что-то знаешь о древесниках?', NULL, NULL, 'Светящийся фрукт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (931, 'Мерцающий росток', 'Росток этого дерева мерцает в сумраке леса, распространяя вокруг себя изменчивое, пульсирующее свечение.$B$BНаверное. Деналана интересует именно такой образец.', 'Принесите мерцающий росток Деналану к озеру Аль\'Амет.', 'Где ты это нашел? Я не видел таких растений с тех пор, как жил на Болоте Печали. А это было много десят$Nий назад! Удивительно, как он попал в Тельдрассил. Да еще вырос до такой величины!$B$BСпасибо тебе, $N. Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком...', 'Ты что-то мне принес?', NULL, NULL, 'Мерцающий росток (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (932, 'Извращенная ненависть', 'Должен предупредить тебя, $N, что это должно остаться только между нами. Сатиры и так уже причиняют нам немало неприятностей, а этот уж слишком близко к нашему дому рыщет.$B$BЕго зовут лорд Меленас. Он живет по соседству, в Пещере Бесов, где собрал шайку греллей-воинов. Его сердце чернее ночи, а замыслы – омерзительны.$B$BНайди его в пещере, прямо к северу отсюда, и принеси мне его голову!', 'Убейте лорда Меленаса и принесите его голову Таллонкаю Гибкому Корню в Доланаар.', 'Теперь, когда лорд Меленас упокоился навек, я могу заняться и другими делами. Прими мою благодарность, $N.', 'Ты еще не убил лорда Меленаса? Необходимо убрать его быстро и тихо, $N. Его существование – угроза всем нам.', NULL, NULL, 'Голова Меленаса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (933, 'Венец Земли', 'К юго-востоку от входа в Дарнас, на берегу Арлитириэнских прудов есть еще один лунный колодец. Стражам трудно наблюдать за этими местами из-за все учащающихся нападений и все большей злобности фурболгов из племени Кривой Сосны. $B$BБудь начеку во время поисков колодца и держи оружие наготове.', 'Наполните турмалиновый фиал и вернитесь к Коритрасу Лунному Гневу в Доланаар.', 'Шан\'до Ярость Бури так и не вернулся, и новостей про него до сих пор не поступало. Друиды были в смятении. После пропажи Малфуриона верховный друид Фэндрал Олений Шлем взял на себя руководство друидами, убедив Круг Древних на Темных Берегах, что нашему народу пора снова заполучить былую мощь и бессмертие.$B$BС одобрения Круга Олений Шлем и самые могучие друиды вырастили Тельдрассил, новое Древо Жизни.', 'Поначалу на донесения об обезумевших фурболгах не обращали внимания. Кто бы мог подумать, что эти миролюбивые людомедведи могут впасть в бешенство? Сколько еще бед должно свалиться на наши головы?', NULL, NULL, 'Наполненный турмалиновый фиал', 'Исследовать локацию', 'Турмалиновый фиал', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (934, 'Венец Земли', 'Но не все было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила.$B$BНо пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-востоку от Врат Дарнаса. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне.', 'Наполните аметистовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар.', '', NULL, NULL, NULL, 'Фиал благословенной воды', 'Исследовать локацию', 'Аметистовый фиал', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (935, 'Венец Земли', 'Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном. Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников.$B$BМогу только надеяться, что верховный друид быстро найдет то, что ищет. Я наполню все принесенные тобой фиалы, чтобы ты $gдоставил:доставила: их в Дарнас.$B$BОтнеси их к Фэндралу Оленьему Шлему, ты найдешь его в роще друидов.', 'Отнесите наполненный сосуд верховному друиду Фэндралу Оленьему Шлему в Дарнас.', 'О, да, это та вода, о которой я просил. Тенарон и Коритрас улучили минутку передать ее... хотя гонца, может, и не самого надежного выбрали... хм-м.$B$BОднако теперь я могу вернуться к работе. Бремя бед Тельдрассила тяжким гнетом лежит на моих плечах. Но скоро я избавлюсь от этого ярма.$B$BВот, возьми. Может, тебе пригодится.', 'Я не звал тебя, так что не понимаю, зачем ты пришел отвлекать меня разговорами.$B$BЧто бы там ни было, пожалуйста, побыстрее.', NULL, NULL, 'Наполненный сосуд (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (936, 'Помощь верховному друиду Руническому Тотему', 'Извини, $C, можно тебя на минутку?$B$BКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.$B$BЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.', 'Поговорите с верховным друидом Хамуулом Руническим Тотемом на Уступе Древних Громового Утеса.', 'Привет тебе, $C! Рад, что ты хочешь помочь нам в наших исследованиях. Дел у нас много, и я оказал бы тебе дурную услугу, если бы не предупредил, что работа опасная. Надеюсь, тебя это не отпугнет... Впрочем, судя по твоему виду, тебе не впервой встречаться с опасностями.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (937, 'Зачарованная поляна', 'Меня отправили сюда с небольшим отрядом Часовых для защиты древа-оракула от гарпий, что устроили себе гнезда по всей поляне. Мы стараемся потихоньку вытеснить их отсюда.$B$BКогда древо-оракул попыталось послать гонца в Дарнас, на него напала стая гарпий и растерзала.$B$BЕсли ты считаешь, что это задание тебе по плечу, иди к их гнездовью и принеси их пояса в доказательство своего подвига.', 'Соберите 6 поясов Кровавых перьев и принесите из часовому Арании Проблеску Солнца на Поляну Оракула.', 'Ты столького достиг за такое короткое время! Это очень впечатляет, $N. Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе... но я понимаю, что тебя ждут великие дела.$B$BЯ заметила, что Древо-оракул только что сбросило кусок коры. Несомненно, оно хочет, чтобы ты выполнил какое-то поручение для него. Поговори с ним.', 'Их безжалостные когти и острые клювы могут оказаться для тебя трудным испытанием, $N, но я верю, что ты с честью выдержишь его.', NULL, NULL, 'Пояс Кровавых перьев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (938, 'Туманна', 'Мех самки саблезуба имеет характерный серый цвет, сливающийся с фоном окружающего леса. Вы видите, что она сильно пострадала: глубокие рваные раны видны на ее спине и брюхе.$B$BОна смотрит на вас, и в ее голубых глазах читается глубокая мудрость. Похоже, она хочет следовать за вами.', 'Проводите Туманну к Стражу Арании Проблеску Солнца к лунному колодцу близ Древа-оракула.', 'О, благодарю тебя, $N! Я так боялась, что уж больше не увижу мою Туманну, скорбела всем сердцем о ее гибели, о том, что навек разлучилась с моей верной спутницей... Я в неоплатном долгу перед тобой! Прими мою вечную благодарность.', NULL, NULL, NULL, 'Проводите Туманну к Стражу Арании Проблеску Солнца.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (939, 'Флейта Ксаварика', 'Вы рассматриваете простую деревянную флейту, которую подобрали, сразив Ксаварика.$B$BУзловатое дерево кажется твердым, но когда вы вертите ее в руках, все спирали и полоски на флейте вдруг начинают вращаться и двигаться. Вас внезапно охватывает нехорошее ощущение...$B$BВы встряхиваетесь, уверенные, что это просто игра воображения.$B$BНо, возможно, у других сатиров найдется разгадка тайны вашей находки. Отнесите ее друиду Эридане Грусти Ветра, которая живет в южной части Оскверненного леса.', 'Принесите флейту Ксаварика и 5 образцов уз Скверны нефритового огня Эридане Грусти Ветра в южную часть Оскверненного леса.', 'Я чувствую страдания Дерев, $N...$B$BДержать в руках эти предметы почти невыносимо...', 'Что такое, $C? У тебя встревоженный вид.', NULL, NULL, 'Флейта Ксаварика (Прилагается)', 'Узы скверны Нефритового Пламени', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (940, 'Тельдрассил', 'Шум леса донес до меня весть о твоих подвигах, $N. Когда я ощутила, что гарпии покинули свои гнездовья, великий покой распространился по лесу и его обитатели снова ощутили себя в безопасности. Я боялась посылать очередное сообщение верховному друиду, но теперь я знаю, что ты доставишь его ему в целости и сохранности.$B$BПередай ему письмо и знай, что лес будет охранять тебя по дороге в каменные джунгли.', 'Передайте отчет древа-оракула верховному друиду Фэндралу Оленьему Шлему в Дарнас.', 'Я-то думал, почему Древо-оракул так долго не связывается со мной... Сдается мне, что как только мы решаем одну проблему, немедленно возникает другая, еще более сложная.$B$BБоюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернем себе бессмертие. $B$BТем не менее, ты славно справился с заданием Древа-оракула, и за усердие тебе положена награда.', 'Хм-м... В тебе силен дух леса, $C. Что у тебя за дело к верховному друиду кальдораев?', NULL, NULL, 'Исписанная кора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (941, 'Сердце-семя', 'Я удалил этот смрадный мох с сердца, но оно все еще остается запятнанным...$B$BПопытайся посадить его в мою кадку. Она наполнена плодородной землей, которая может очистить и исцелить это сердце.', 'Посадите запятнанное сердце в кадку Деналана. ', 'Вы сажаете сердце в кадку, и оно быстро в нее зарывается!$B$BЧерез несколько секунд оно снова выкапывается из земли – уже очищенное. Оно тихонько пульсирует... и вам хочется взять его в руки.', 'Кадка полна земли, специально подготовленной Деналаном.', NULL, NULL, 'Запятнанное сердце (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (942, 'Рассеянный геолог', '\"Эта окаменелость поразительно похожа на другую, которую я однажды видел в Стальгорне. Геолог по имени Бутылопуз приносил ее на ежегодную конференцию Лиги Исследователей. Он был уверен, что в этой окаменелости скрыта мощь, которую можно каким-то образом высвободить.$B$BПоследнее, что я слышал, что Бутылопуз обосновался в таверне \"Большая вода\" и ждет, чтобы его сопроводили к раскопу Вельгара. Найдите его и покажите ему окаменелость, найденную Сомнамбулером. Может быть, он сумеет раскрыть секреты прошлого.', 'Отвезите таинственную окаменелость археологу Бутылопузу в Гавань Менетилов.', 'О боги! Так вы говорите, эта вещь происходит из далеких земель Калимдора?$B$BПоразительно! Просто поразительно!', 'Что это там у вас, дружище?', NULL, NULL, 'Таинственная окаменелость (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (943, 'Рассеянный геолог', 'Геолог Вельгар, который сейчас находится на раскопе в Болотине, держит окаменелость у себя. Когда я обнаружил камень Релу, то был уверен, что это ключ к тайне окаменелости.$B$BПока я шел по дороге к Вельгару, на меня напали ящеры, и реликвия пропала. Не знаю, какая из крапчатых тварей проглотила ее, но если вам удастся ее вернуть, я смогу высвободить силу этих артефактов.$B$BПринесите мне и камень Релу, и окаменелость, хранящуюся у Вельгара.', 'Археолог Бутылопуз в Гавани Менетилов хочет, чтобы вы принесли ему камень Релу и окаменелость Бутылопуза.', 'Великолепно, $N!$B$BТеперь посмотрим, смогу ли я использовать камень, чтобы распознать силы, скрытые в окаменелостях.', 'При помощи камня Релу я смогу раскрыть тайны моей окаменелости, а также и окаменелости Сомнамбулера с Темного Берега, $N.', NULL, NULL, 'Камень Релу', 'Окаменелость Бутылопуза', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (944, 'Меч Властителя', 'Очень странно, что наги появились здесь, на Темных берегах. Но еще страннее – клан Сумеречного Молота. Они поклоняются старым, очень старым богам этой земли. Богам, давным-давно низвергнутым.$B$BМеч Властителя, что к югу отсюда, – место, где пал один из этих древних богов.$B$BПойди туда и поищи других культистов Сумеречного Молота.$B$BВозьми этот фиал виденья. Используй его для создания гадальной чаши, когда разведаешь все у Меча Властителя. Посредством этой чаши поговори со мной.', 'Соберите информацию, а затем используйте фиал виденья для создания гадальной чаши. С помощью чаши поговорите с Ону.', 'Так ты обнаружил клан Сумеречного Молота у Меча Властителя?$B$BПлохо.$B$BДревний бог, пронзенный мечом, давно мертв, но это не значит, что исчезли и остатки его могущества.$B$BДолжно быть, клан Сумеречного Молота пытается найти его силу.', 'Меч Властителя, $N.$B$BОтправляйся туда, а потом снова свяжись со мной.', NULL, NULL, 'Исследовать локацию', 'Отправляйтесь в Меч Властителя.', 'Фиал виденья', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (945, 'Спасение Терилун', 'Помогите!$B$BЯ бродила у Меча Властителя, как вдруг меня окружили эти жуткие сектанты. Счастье, что я умею отлично прятаться!!!$B$BМожете помочь мне отсюда выбраться? И еще, мне нужно будет сообщить моей сестре Тересиль, что я в порядке. Она в Ясеневом лесу, к югу отсюда, у святилища Эссины.', 'Помогите Терилун спастись, а потом сообщите Тересиль, что ее сестра в безопасности. Тересиль можно найти у Святилища Эссины в Ясеневом лесу.', 'Моя сестра была – где? Тирелин любит бродить по всяким местам, но все-таки! Это же очень далеко, да и Меч Властителя – вовсе не безопасное место...$B$BНу, спасибо вам, Чебо. С вашей стороны было очень любезно сообщить мне, что с ней все в порядке.', NULL, NULL, NULL, 'Помогите Терилун спастись из Меча Властителя.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (947, 'Пещерные грибы', 'Я тут составляю одно зелье, для которого нужны редкие грибы, растущие в одной-единственной пещере. Пещера эта находится за водопадом Скалистый, к востоку и чуть севернее в горах.$B$BЯ бы и сам туда пошел, но в Роще Древних мне порекомендовали держаться подальше от того места. Наши почтенные союзники чувствуют, что в этой пещере таится какое-то незнакомое зло.$B$BПрошу вас, $N, соберите для меня эти грибы. А в процессе заодно приглядитесь: может быть, вы сможете подтвердить опасения Дерев.', 'Принесите 5 ножек струпника и 1 мертвянку Баритасу Лунному Сумраку в Аубердин.', 'Большое вам спасибо, $N. Это отличные экземпляры!$B$BКстати, когда вы были у водопада Скалистый, заметили ли что-нибудь, что могло подтвердить опасения Дерев?$B$BДерева мудры, но я надеялся, что на сей раз они ошибаются.', 'Вы еще не собрали грибов для меня, $N? В пещеру ходили?', NULL, NULL, 'Ножка струпника', 'Мертвянка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (948, 'Ону', 'Ону, древо мудрости из Рощи Древних, знает о вашем путешествии к Скалистому водопаду и хочет поговорить с вами. Роща расположена к югу отсюда, у подножья гор.$B$BДрева терпеливы и мудры, $N. Но если Ону ищет вашего совета касательно того, что вы видели у водопадов, то, боюсь, дело срочное.', 'Поговорите с Ону в Роще Древних.', 'Злорфи. Ты здесь.$B$BХорошо.$B$BНам есть... что обсудить. Тебе и мне.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (949, 'Лагерь Сумеречного Молота', 'Что замышляет клан Сумеречного Молота у Меча Властителя, неизвестно. Но наверняка что-то недоброе$B$BОбыщите их лагерь у Меча Властителя... Ищите то, что может помочь нам понять их намерения.$B$BВедь мы должны узнать об их целях раньше, чем они выработают план действий.', 'Найдите подсказку в лагере клана Сумеречного Молота, расположенном у Меча Властителя.', 'Книга написана от руки на древнем языке и прекрасно иллюстрирована.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (950, 'Возвращение к Ону', 'Вглядываясь в сумеречный фолиант, можно сойти с ума. Буквы начинают плыть и плясать перед глазами даже после мельком брошенного взгляда, и некогда прекрасный орнамент принимает гротескные формы.$B$BВырвать одну страницу с безумными каракулями – вот и все, что вам удается сделать, пока вы не потеряли сознание.', 'Принесите Ону лист с безумными письменами. ', 'Неизученная первобытная магия окружает этот пергамент с письменами. Я чувствую, что над ним потрудились древние силы.$B$BБудем надеяться, мы сумеем раскрыть цель деятельности клана Сумеречного Молота на Темном Берегу.', '$N. Ты вернулся.', NULL, NULL, 'Безумные каракули (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (951, 'Реликвии Матистры', 'Пергамент, который ты $gобнаружил:обнаружила: близ Меча Властителя, – страница древнего текста... написанная эльфами! Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев.$B$BНаправляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии. Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов.', 'Принесите Ону в Рощу Древних 6 реликвий Матистры. ', 'Благодарю тебя. Эти реликвии относятся к поре расцвета Матистры. Этот некогда могучий оплот эльфов давно разрушен, но остатки магии еще попадаются в руинах. Будем надеяться, что нам удастся раскрыть тайны этого места раньше, чем это сделают наши враги.$B$BБудь настороже, $N.', '$N. Ну что, удалось ли тебе что-то раскопать в руинах Матистры?', NULL, NULL, 'Реликвия Матистры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (952, 'Роща Древних', 'Если уж у тебя нашлось время передать письмо для древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Темные берега, прямо к югу от Аубердина.$B$BТы наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, древу мудрости. Он ждет от меня вести, точно так же, как я ждал вести с Поляны Оракула.', 'Доставьте письмо Фэндрала Ону в Рощу Древних на Темные берега к югу от Аубердина.', 'А. Спасибо, Каззакс. Тем не менее, это странно. Верховный друид всегда так торопится. Лес знает, что всему свое время. Шан\'до Ярость Бури это понимал.', 'А. $C. Чем может тебе помочь Ону?', NULL, NULL, 'Послание Фэндрала (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (953, 'Падение Амет\'Арана', 'К востоку отсюда находятся руины Амет\'Арана. Сейчас их населяют неупокоенные духи высокорожденных, некогда живших в его стенах, но когда-то Амет\'Аран был местом, где слуги Азшары свободно практиковались в своей могучей магии.$B$BМеня послали исследовать эти руины, и я наткнулась на две большие таблички, на которых была неразборчиво начертана история Амет\'Арана и его падения. Пока я пыталась прочесть руны, на меня напали призраки, и я сбежала.$B$BПожалуйста, если можете, отправляйтесь в руины и расшифруйте таблички вместо меня.', 'Изучите таблички, рассказывающие об Амет\'Аране и его падении, а затем возвращайтесь к часовому Тише Лунный Клинок, находящейся на Темных берегах.', 'У нас очень немного записей, относящихся ко времени Войны Древних, а особенно – к периоду разрушения Источника Вечности. Что неудивительно, если вспомнить о том, какие ужасные события и катаклизмы тогда происходили.$B$BСпасибо вам, $N. С вашей помощью моя работа здесь окончена, и я смогу представить Кругу Древних полный доклад.', 'Когда вы изучите таблички и узнаете о падении Амет\'Арана, я пойду с этой информацией в Аубердин и сообщу Кругу Древних.', NULL, NULL, 'Прочтите \"Песнь об Амет\'Аране\"', 'Прочтите \"Падение Амет\'Арана\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (954, 'Башал\'Аран', 'Руины Башал\'Арана, расположенные к востоку отсюда, населены демоническими служителями зла. Злые духи и сатиры, обосновавшиеся там, питаются магическими энергиями Башал\'Арана, и силы их растут от постоянной подпитки энергией.$B$BНо при этом я заметил, что к одному святилищу они не приближаются. На западной стороне руин, на вершине небольшого утеса, распространяется странное синее свечение... Там и должно быть объяснение нежеланию демонов приближаться к этому месту.$B$BЯ хотел бы, чтобы вы его исследовали.', 'Найдите источник странного синего свечения в руинах Башал\'Арана.', 'Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезный $r? На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение...$B$BНо, прошу вас, пусть мой грубый язык не заставит вас уйти. Очень уж много лет, а то и десят$Nий, прошло с тех пор, как у меня была приличная компания.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (955, 'Башал\'Аран', 'Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения. Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук.$B$BХотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты $gпомог:помогла: мне найти то, что держит меня здесь. Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на ее след.', 'Соберите 8 серег греллей для Астериона в Башал\'Аране.', 'И правда... Грелли Башал\'Арана не владеют тем, что я ищу... Однако недавно они были в контакте с этим. Недавно... Я имею в виду по меркам твоего времени, не моего. Для меня \"недавно\" простирается глубоко в прошлое, почти что в другую эру...', 'Когда я получу серьги, я применю заклинание, чтобы обнаружить местонахождение связывающей меня печати. Веками я мечтал о свободе, которую принесло бы мне разрушение печати... Быть может, эти века таким грузом лежат на моем разуме, что я уже никогда не приду в себя...', NULL, NULL, 'Серьга грелля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (956, 'Башал\'Аран', 'Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, подозреваю, я знаю, в чем дело. Несомнено эта печать находится во владении сатира, предводительствующего ими.$B$BЯ убежден, что моя догадка верна, $N. Она наверняка у одного из сатиров. Если ты сможешь ее добыть, то ты почти откроешь дверь моей темницы. Мне не сдержать слез...', 'Добудьте древнюю печать из лунного камня и принесите ее Астериону в Башал\'Аран.', 'Мне трудно поверить, что вещь, которую я сейчас держу в руках, так долго держала меня самого... Не будем тратить времени,$N. Когда печать будет уничтожена, я снова вольно смогу бродить по лесам.', 'Столпы этого святилища для меня – тюремная решетка, $N. У меня нет сил их разрушить, и нет такой магии, чтобы сокрушить их...$B$BБольше тысячи лет я смотрю на них и думаю: если я переживу этот камень, буду ли я свободен? Или меня держит незримая решетка?', NULL, NULL, 'Древняя печать из лунного камня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (957, 'Башал\'Аран', 'Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорожденных. В Амет\'Аране – точно таких же руинах к югу отсюда – до сих пор горит древнее синее пламя. В этом огне печать может быть уничтожена.$B$BБудь осторожнее в тех руинах, $N...', 'Уничтожьте древнюю печать из лунного камня у древнего пламени в Амет\'Аране, затем вернитесь к Астериону в Башал\'Аран.', 'Я свободен, $N! Я могу собственными глазами видеть, какие изменения произошли с нашим миром... Я узнаю только отдельные фрагменты. Подумать только, что когда я в последний раз гулял на свободе, еще существовал Источник и высокорожденные держали совет с Азшарой, нашей любимой королевой.$B$BЯ чувствую, что мой тюремщик, мой бывший хозяин, Атрикус, еще жив... Мое осознание безнадежности вскоре сменится мыслями о мести.', 'По правде говоря, $N, я боюсь... Боюсь, что твой приход – и все это – лишь плод моего воспаленного воображения. Можешь ли ты понять, какая это мука? Я... Пожалуйста, ступай скорее.', NULL, NULL, 'Уничтожьте печать у древнего пламени', 'Древняя печать из лунного камня', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (958, 'Инструменты высокорожденных', '$C. Вот задание, которое я вам поручаю.$B$BВидели ли вы руины Амет\'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда. Когда-то Амет\'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершенному их жалкими подражателями.$B$BМне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления. Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить.', 'Добудьте 7 реликвий высокорожденных для Тандриса Ветропряда в Аубердине.', 'Хотя это, безусловно, лишь игра моего воображения, я чувствую себя так, будто бы ощущаю в этих реликвиях ядовитое дыхание магии высокорожденных. Я их уничтожу, чтобы давно уснувшее зло больше никогда не пробудилось.', 'Если бы инструменты их гибели были разрушены во время катаклизма, уничтожевшего наш мир... Тем не менее мы должны сделать все возможное, чтобы ужасы нашего прошлого не повторились в будущем.', NULL, NULL, 'Реликвия высокорожденных', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (959, 'Неприятности в порту', 'Ой! $B$BКак видишь, у меня сегодня приключилась неприятность! Утром из Пиратской Бухты пришла поставка. И какая! Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало. В конце концов все рухнуло на землю.$B$BНе успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна 99-летней выдержки и бросился наутек. Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок.$B$BМожет, тебе хватит пороху, чтобы найти его?', 'Оператор крана Биггльфузз из Кабестана попросил вас отнять бутылку портвейна 99-летней выдержки у Безумного Магглиша, который прячется в Пещерах Стенаний.', 'Великолепно! И ведь меня едва не уволили! Теперь надо поскорее отнести подарок Газлоу.$B$BCпасибо, $N. Отличная работа!', 'Портовый начальник не дает мне покоя с тех пор, как Безумный Магглиш скрылся с этой бутылкой. Судя по всему, портвейн предназначался в подарок $N самим бароном Ревилгазом. $B$BЕсли у тебя довольно смелости и терпения для поисков Безумного Магглиша и похищенного портвейна, я щедро награжу тебя.', NULL, NULL, 'Портвейн 99-летней выдержки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (960, 'Размышление Ону', '', '', 'Я размышляю над твоим заданием, $N. Размышляю над причинами присутствия здесь клана Сумеречного Молота и нагов.Когда будешь готов, используй фиал виденья для создания гадальной чаши. Затем свяжись со мной с ее помощью.Если ты потерял свой фиал виденья, то у меня есть еще.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (961, 'Размышление Ону', '', '', 'Обнаружение культистов клана Сумеречного Молота беспокоит меня. Я должен поразмыслить об их намерениях...Когда у тебя будет больше информации, поговори со мной посредством гадальной чаши. Если тебе для создания чаши нужен фиал виденья, то... у меня есть еще.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (962, 'Змеецвет', 'Королевское фармацевтическое общество из великого Подгорода Лордерона направило меня сюда с очень необычной целью, $N. Возможно, ты сумеешь помочь мне, а, стало быть, и Темной Госпоже в трудах на благо Отрекшихся.$B$BНе так давно я изучала редкий образец флоры под названием змеецвет. Я уверена, что в большом количестве это растение таит в себе великие возможности.$B$BУвы, змеецвет можно найти только в самых темных закоулках Пещер Стенаний, опасной системе подземелий в Степях.', 'Аптекарь Зама из Громового Утеса просит вас принести ей 10 змеецветов. ', 'Ах, замечательные экземпляры! Вы хорошо поработали, $N.', 'Мне очень надеюсь, что вам удастся добыть достаточно змеецвета в Пещерах Стенаний. Я многих туда посылала, но никто не вернулся.', NULL, NULL, 'Змеецвет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (963, 'Во имя вечной любви', 'После битв за Источник Вечности я узнал, что Амет\'Аран разрушен, жители его погибли – в том числе и моя возлюбленная Анайя.$B$BЯ никогда не думал, что и через тысячи лет воспоминания об Анайе будут тревожить мои сны. Бродя в помрачении рассудка по лесам на Темном Берегу, я очутился в руинах Амет\'Арана... где и увидел неупокоенный дух моей любимой.$B$BЕе нужно освободить, но у меня просто рука не поднимается. Нужно уничтожить ее призрак.', 'Освободите дух Анайи Вестницы Зари и принесите ее подвеску Кириллиану Белому Когтю в Аубердин.', 'Благодарю тебя, $N. Может быть, было бы лучше... если бы я сам это сделал. Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную.$B$BПожалуйста, оставь меня наедине с моим горем...', 'С неизбывной печалью в сердце я последовал за Шан\'до Яростью Бури в долгий сон, и взял свою боль с собой в сны, и спал на протяжении тысячелетий.', NULL, NULL, 'Подвеска Анайи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (964, 'Фрагменты скелетов', 'Чтобы отомкнуть двери Некроситета необходим костяной ключ. Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой.$B$BНо не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи.', 'Принесите 15 фрагментов скелетов аптекарю Дитерсу в Бастион в Западных Чумных землях.', 'Отличные образцы! Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придется рано или поздно пройти.$B$BТеперь придется отыскать подходящую форму для отливки. Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей. Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает.', 'Убивай больше и чаще, $C. Нам понадобится солидный запас фрагментов скелетов для создания внешнего слоя ключа. Его же не зря называли Костяным ключом.', NULL, NULL, 'Фрагменты скелетов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (965, 'Башня Алталакса', 'Привет тебе, $gюный:юная:$r. Меня зовут Элисса Звездный Ветер, и моя задача – защищать Аубердин от всякого вреда.$B$BС этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда.$B$BНо он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью. Я была бы тебе очень благодарна, если бы ты $gсмог:смогла: найти его и удостовериться, что с ним все в порядке.', 'Найдите Балтула Удар Тени возле башни Алталакса на Темных берегах.', 'Тебя прислала Элисса? Это хорошо. У меня есть для нее тревожные вести, но не было возможности передать их ей.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (966, 'Башня Алталакса', 'Группа чернокнижников обосновалась вокруг и внутри башни. Я хотел было вернуться в Аубердин и доложить Элиссе раньше, но побоялся, что могу что-то пропустить, пока буду отсутствовать.$B$BДелгрен подозревал, что подобная компания может собираться у башни, но не знал, зачем.$B$BНесколько обрывков свитков пергамента, которые носят с собой чернокнижники, попали в мои руки, но мне нужно знать больше, чтобы разгадать эту головоломку. Однако я предостерегаю вас от попытки вторгнуться в саму башню: чернокнижники, засевшие там, гораздо сильнее!', 'Соберите 4 свитка истрепанного пергамента для Балтула Удара Тени возле башни Алталакса.', 'Большое спасибо, $N. Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников...$B$BХмм... Клан Темной Нити... Никогда раньше не слышал о такой группе. Пока у нас нет никаких сведений об их истории, практически невозможно сказать, в чем могут заключаться их планы.$B$BБольше нельзя тянуть. Нужно немедленно предупредить Делгрена.', 'Нашли ли вы у них еще свитки? Я смогу составить более целостное представление об этом культе, если вы сможете их найти.', NULL, NULL, 'Истрепанный пергамент', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (967, 'Башня Алталакса', 'Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от сил демонов и нежити. Он многое поведал мне о божественном Свете и воинском искусстве.$B$BДелгрен должен немедленно узнать о деятельности клана.$B$BТы найдешь его далеко на юге отсюда, на заставе Мейстры в Ясеневом лесу. Поторопись – я боюсь, что угроза клана Темной Нити растет с каждым часом.', 'Доставьте письмо Балтула Делгрену Очистителю в Ясеневый лес. ', 'Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простого посланца, не так ли? Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадет мне в руки. Посмотрим, что он там пишет...$B$BДа, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их.$B$BВначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников.', 'У вас ко мне какое-то дело, $C?', NULL, NULL, 'Письмо Делгрену (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (968, '\"Подземные Силы\"', 'Хотя книга ужасно истрепана и исцарапана, ее название на обложке все же можно разобрать:$B$B\"Подземные Силы\".$B$BВ книге перечисляются непроизносимые имена со зловещими титулами, способами почитания и предпочтительными способами жертвоприношения... И среди этих жертвоприношений числятся живые разумные создания.$B$BНа внутренней стороне обложки написано: \"Руны и Жребии Костохвата, Заброшенный грот, Стальгорн. Владелец: Геррик Костохват\".$B$BЕсли Костохват торгует подобными книгами, может быть, он выкупит и эту?', 'Принесите книгу \"Подземные Силы\" Геррику Костохвату в Заброшенный грот в Стальгорне.', 'А, экземпляр \"Подземных сил\". Интересный текст, да уж. А кое-кто найдет его и полезным тоже...$B$BНо эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице!$B$BХм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его друг? Да, должно быть, так. У вас в глазах такой же огонь горит!$B$BНу, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?', 'Приветствую, сударь.$B$BМогу ли я заинтересовать вас каким-то из моих фолиантов?', NULL, NULL, 'Книга \"Подземные Силы\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (969, 'Да пребудет с тобой удача!', 'Ах, одного взгляда на тебя достаточно, чтобы сказать: ты захочешь себе счастливый оберег. Мау\'ари всегда все знает! $B$BНа юг пойди - найдешь ущелье, а в нем гигантов, сделанных из кусков льда. Кристаллы можно отобрать у гигантов, но можешь собирать их и $gсам:сама: в ущелье. Эти кристаллы имеют отличную отражающую способность. $B$BПринеси мне 4 кристалла великанов Ледяного Молота, и счастливый оберег станет твоим.', 'Соберите 4 кристалла великанов Ледяного Молота для знахарки Мау\'ари из Круговзора.', 'О да… сейчас я сделаю для тебя этот оберег. Погоди-ка!', 'Принеси мне кристаллы – и я расскажу больше тебе!', NULL, NULL, 'Кристаллы великанов Ледяного Молота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (970, 'Башня Алталакса', 'Письмо Балтула приводит меня в ужас. Этот клан Темной Нити – сущее бельмо у меня на глазу, и его надо устранить! Мне приходилось иметь дело с мерзавцами из Темной Нити к северо-востоку отсюда в Ордиль-Аране. У одного из них есть самоцвет Души, в котором, как я думаю, заключается секрет силы клана.$B$BПринеси его мне, а уж я сумею разгадать его тайну.', 'Добудьте светящийся самоцвет Души и вернитесь к Делгрену Очистителю на заставу Мейстры.', 'Хмм, этот самоцвет Души наполнен какой-то темной магией. Давай-ка посмотрим, что в нем таится...', 'Ну, как, удалось добыть самоцвет души?', NULL, NULL, 'Светящийся самоцвет души', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (971, 'Знание в пучине', 'Насколько вам известно, я собираю знания. Древние знания. Могучие знания. Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят.$B$BХодят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине Ясеневого леса. Некогда там жили эльфы, но они давно уже мертвы. Эльфы эти обладали великим знанием, до того как их город превратился в руины.$B$BНайдите манускрипт в Непроглядной Пучине Сделайте это, и я не забуду вашей услуги. Даже после... скончания дней.', 'Принесите манускрипт Лоргалиса Геррику Костохвату в Заброшенный грот в Стальгорне.', 'Вы нашли манускрипт! Что за радостный день! Мы сделаем с него копии и распространим, и древнее знание Лоргалиса станет достоянием наших братьев и сестер!$B$BВы даже не понимаете, какую услугу нам оказали, $N. Но я надеюсь, что этот дар покажет вам всю глубину нашей признательности нашим союзникам.', 'Долог путь до Ясеневого леса, и задача ваша нелегка. Но если вы доставите мне манускрипт, $N... Велика будет ваша награда.', NULL, NULL, 'Манускрипт Лоргалиса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (972, 'Сапта воды', '', '', 'Возьми сапту воды и отыщи оскверненную заводь в Серебряном бору. Я возлагаю на тебя большие надежды, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (973, 'Башня Алталакса', 'Илкруд Магтрулл. Да, я знаю о нем. Это могучий орочий чернокнижник, который поселился в Святилище Огненной Расщелины, месте великого зла на юго-западе Ясеневого леса.$B$BДоныне он был не более чем досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться.', 'Принесите фолиант Илкруда Магтрулла Делгрену Очистителю на заставу Мейстры.', 'Сегодня ты сделал большое дело, $N. Гордись – ты сразил могущественного чернокнижника.$B$BА теперь посмотрим, что сказано в записях Илкруда.', 'У тебя немного ошарашенный вид, $N. С тобой ничего не случилось?', NULL, NULL, 'Фолиант Илкруда Магтрулла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (974, 'Найти источник', 'Эти горячие источники всегда были для меня загадкой! Откуда берется жар? $B$BЕсли учесть, что источники расположены совсем недалеко от Вулкана Огненного Венца, можно предположить, что их подогревает вулкан. Я разработал термометр, чтобы измерять температуру вулкана, и теперь хочу выяснить, в какой точке она наиболее высока. Термометр дает результаты по шкале Кракленгейта. $B$BВот, держи, отправляйся на хребет и выясни, где там точка с самой высокой температурой!', 'Выясните, где находится точка самой высокой температуры на Вулкане Огненного Венца, по просьбе Кракла из Кратера Ун\'Горо. Для измерения температуры щелкните по термометру правой кнопкой мыши. Проверяйте все жаркие точки, пока не будет обнаружена точка с самой высокой температурой.', 'Да, корреляция температур вулкана и горячих источников очевидна. Конечно, надо бы еще раз проверить правильность уравнений, однако создается впечатление, что расстояние и температура... Хмм...', 'Я бы и сам пошел, но уж больно боюсь элементалей Огня!', NULL, NULL, 'Найдите самую горячую точку Вулкана Огненного Венца', 'Термометр Кракла (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (975, 'Сокровище Мау\'ари', 'А теперь, прежде чем я дам тебе этот вот оберег, объясню, как им пользоваться. $B$BЕсли он у тебя с собой, окажется, что определенные предметы будут в добыче с тех созданий, с которыми ты бой вести будешь. А если нет, то и предметов не найдешь. Понятно? $B$BТы узнаешь их по имени – они называются э\'ко. Если найдешь такие – приноси Мау\'ари, она поможет тебе найти им применение. $B$BПостой-ка тут, пока я твой оберег доделаю.', 'Еще раз поговорите со знахаркой Мау\'ари через минуту, чтобы получить талисман на удачу.', 'Вот и готово, $N. Помни, ты должен носить его с собой. Почему бы тебе не отправиться обратно на природу из города и не посмотреть, что ты там обнаружишь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (976, 'Поставка для Аубердина', 'Делгрен попросил меня доставить письма и припасы часовому Звездный Ветер в Аубердин, но мне очень не хочется ехать в одиночку. В лесу опасные враги, а я не хочу, чтобы эти припасы и информация попали не в те руки.$B$BЕсли ты с остальными согласитесь охранять меня, то я смогу уехать прямо сейчас. Под вашей защитой я точно доставлю все это в Аубердин.', 'Поговорите с Делгреном Очистителем на заставе Мейстры после того, как проводите Фиро через Ясеневый лес.', 'Ты сегодня славно поработал, $C. То, что мы отослали в Аубердин, срочно необходимо для отражения темной угрозы, наводнившей лес.$B$BПрими это вместе с моей сердечной благодарностью.', NULL, NULL, NULL, 'Защитите Фиро Железнорука.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (977, 'Йети где-то рядом…', 'Теперь, когда мне есть чем прикрыть механические движущиеся части, мне нужна только одна вещь. Ну, точнее, две. Два рога! $B$BСамые большие рога – у патриархов и матриархов клана, так что, естественно, именно их-то я и хочу. Эта разновидность йети обитает в пещере к юго-востоку отсюда. Их там очень много, ты без труда их отыщешь. $B$BПомни, я хочу самые красивые рога – пожалуйста, не приноси ни побитых, ни сломанных!', 'Добудьте 2 безупречных рога Йети для Уми Смехотреп из Круговзора.', 'Просто не могу дождаться, чтобы скорее показать своим друзьям! Погоди секунду, пока я прикреплю рога… $B$BКласс!', 'Я уже почти закончила прикреплять мех, $N. Пожалуйста, поскорее принеси мне рога, что я просила!', NULL, NULL, 'Нетронутый рог йети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (978, 'Осененные луной дикие совухи', 'Перья диких совухов из Внутренних земель, кажется, содержат следы магии. Эти силы… непохоже, что создания способны их контролировать, больше похоже на то, что магия просто является частью их сущности. $B$BЗа время моих исследований я слыхал, что большая популяция диких совухов населяет заснеженные земли Зимних Ключей. Вдруг у этих существ есть те же свойства? Пожалуйста, $N, помоги мне найти ответ. Отправляйся в Зимние Ключи, собери выпавшие перья и возвращайся с ними ко мне.', 'Соберите в Зимних Ключах 10 осененных луной перьев и принесите их Эреласу Янтарному Небу в деревню Рут\'теран.', 'Теперь я могу сравнить перья между собой… Посмотрим-ка…', 'И откуда только берется эта магия? Думаю, что мы на правильном пути к отысканию ответа, $N.', NULL, NULL, 'Осененное луной перо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (979, 'В поисках Раншаллы', 'Да-да, на эти перья, похоже, наложены точно такие же чары, как и те, что я прежде заметил… Поскольку я совершенно не уверен в том, что именно мы нашли, я очень хочу, чтобы ты $gпродолжил:продолжила: поиск ответов, $N. $B$BМоя коллега недавно отправилась в Зимние Ключи изучать там диких совухов в их естественной среде обитания. Может, ты нагонишь ее и выяснишь, что ей удалось узнать?', 'Найдите Раншаллу в восточной части Зимних Ключей. +75 ед. репутации с Дарнас', 'Привет! Вас прислал Эрелас?? Здорово, я как раз собиралась отправиться в пещеры, и я отнюдь не возражаю против компании.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (980, 'Новые источники', 'Слыхал я, что существуют и другие горячие источники – в местечке Зимние Ключи, далеко к северу отсюда. И вот в чем загвоздка – в тех местах нет никаких вулканов! Очень любопытно... $B$BЧто ж, тут можно сделать лишь одно – отправиться в Зимние Ключи и поговорить с моей тамошней приятельницей. Ее зовут Донова Снегонора, она живет прямо рядом с источниками. $B$BНу, счастливой дороги! Еще раз спасибо за помощь с термометром.', 'Отправьтесь в Зимние Ключи и побеседуйте с Доновой Снегонорой.', 'Здравствуй, $N! Да, Кракл был совершенно прав...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (981, 'Башня Алталакса', 'За всю проделанную вами работу вы заслужили хорошую награду. Возвращайтесь к Делгрену и скажите ему, что Атрикус Нарассин лежит, сраженный вашей рукой, а клан Темной Нити сокрушен, и остатки его рассеяны.', 'Поговорите с Делгреном Очистителем на Заставе Мейстры.', 'Я знал, что вы возьметесь за это задание, $N.$B$BЯ чувствую, вас ждут великие дела и что вам суждено исцелить многие недуги, что терзают наши земли. Примите мое благословение, $N, и этот дар.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (982, 'Безбрежное море, глубокий океан', 'У побережья Темных берегов, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\". Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина. Теперь корабли лежат на дне океана, став добычей мурлоков$B$BОба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в сейфах. Я хотел бы, чтобы вы добыли их для нас; это много значило бы для членов команды.', 'Добудьте сейф \"Серебряной Зари\" и сейф \"Туманной Пелены\" для Горбольда Стальной Руки в Аубердине. Оба предмета можно найти в останках потерпевших крушение кораблей к северу от деревни.', 'Вы оказали нам огро$Nю услугу, юноша. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход.$B$BЧто же касается вас, прошу вас принять это. Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости.', 'Капитаны тех кораблей были славными ночными эльфами, и они заслужили лучшую участь, чем та, что им выпала. Может быть, внимание, проявленное к их личным ценностям, – наилучший способ позволить их душам обрести покой.', NULL, NULL, 'Сейф Серебряной Зари', 'Сейф Туманной Пелены', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (983, 'Жужжалка 827', 'Слушай! Помоги мне с моим последним изобретением, Жужжалкой. С ее помощью можно общаться на расстоянии!$B$BМожет быть, ты уже $gвидел:видела: их – такие ящики с рычагами. С ними одна проблема – за ними нужен постоянный уход.$B$BУ каждой из них есть своя проблема, но я нашел хитрое решение. Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины. Сейчас неисправна Жужжалка 827. Она находится чуть южнее Аубердина, совсем рядом с ним. Чтобы ее починить, нужно 6 ножек краба. Я заплачу...', 'Добудьте 6 ножек крабов и поместите их в Жужжалку 827. ', 'Когда вы кладете ножки крабов в приемник машины, то слышите, как шестерни начинают их перемалывать. По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли свое место. Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины.$B$B\"Алло! Уфф... Алло! Ты ее починил! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить еще одну машинку?\"', 'Жужжалка 827 хранит зловещее молчание. Единственный мигающий индикатор показывает, что в приемник нужно поместить 6 ножек крабов.', NULL, NULL, 'Ножка краба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (984, 'Насколько велика угроза?', 'Некоторые из моих собратьев спаслись от порабощенных порчей фурболгов в Тельдрассиле, а я пообещал остановить злодеяния, пока кровь не полилась рекой... или не произошло чего-то еще хуже.$B$BЯ уже вижу признаки присутствия скверны на Темных берегах, но она еще не так распространилась. Я думаю, было бы логично продолжить исследования фурболгов. Может быть, ты найдешь один из их лагерей, а затем вернешься ко мне, если увидишь следы порчи?', 'Найдите оскверненный лагерь фурболгов на Темных берегах и вернитесь к Терентису в Аубердин.', 'Это и вправду ужасные новости, $N.$B$BПоскольку фурболги находятся так близко к Аубердину, нам придется приготовиться к неизбежному.$B$BСпасибо вам, $N.', NULL, NULL, NULL, 'Исследовать локацию', 'Найдите оскверненный лагерь фурболгов.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (985, 'Насколько велика угроза?', 'Вы уже поднаторели в разведке на вражеских территориях, $N. Но способны ли вы не только следить за врагами, но и биться с ними?$B$BНе все искатели приключений предпочитают честную битву лицом к лицу искусству скрытности и уклонения.$B$BЕсли вы считаете, что готовы к сражению, то наибольшую угрозу нашему народу представляют сейчас фурболги в лагере к югу от Аубердина. Вы найдете там фурболгов Чернолесья. Убейте 8 землепроходцев и 5 заклинателей ветра, а потом возвращайтесь сюда, ко мне.', 'Убейте 8 землепроходцев и 5 заклинателей ветра из племени Чернолесья, а затем вернитесь к Терентису в Аубердин.', 'Смойте кровь с ваших доспехов, $N, и не мучайтесь из-за содеянного. Вместо этого вознесите благодарность судьбе. Вы уменьшили угрозу нашему народу здесь, в Аубердине, даже если весь Темный Берег пока еще находится в опасности из-за Мха Скверны.', NULL, NULL, NULL, 'Землепроходец из племени Чернолесья убито', 'Заклинатель ветра из племени Чернолесья убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (986, 'Пропавший хозяин', '$N, твое мастерство уже один раз сослужило мне хорошую службу в сложной ситуации. Могу ли я вновь возложить на тебя задачу помочь Лютому Когтю и его хозяину Волкору? Я могу сделать волшебный плащ, который позволит тебе беспрепятственно ходить вблизи враждебных существ Темных берегов, пока ты будешь искать Волкора.$B$BДля изготовления плаща, чтобы хватило материала, мне нужно 5 прекрасных шкур лунопарда, снятых со взрослых самцов или матриархов. Этих кошек можно найти около Петляющей реки, к югу отсюда, или еще дальше на юг, близ Ясеневого леса.', 'Найдите 5 прекрасных шкур лунопарда и принесите их Терентису в Аубердин.', 'Эти шкуры отлично подойдут, $N. Я немедленно приступаю к работе над плащом.$B$BДайте мне немного времени, а затем возвращайтесь.$B$BДа, еще кое-что: после того как вы задействуете чары, наложенные на плащ, вы будете ограничены в своем взаимодействии с другими лицами. Если сможете, ограничьтесь только разговорами. Все, что сверх этого, может развеять чары.', 'В здравом уме я не позволю вам идти искать Волкора, пока не сошью для вас тот плащ.', NULL, NULL, 'Прекрасные шкуры лунопарда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (990, 'Путь в Ясеневый лес', '$N, моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу. Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни.$B$BОтправляйся отсюда на юг и держись дороги – ты легко найдешь путь, если будешь держаться этого направления.', 'Найдите в Ясеневом лесу Раэну Волкопас. ', 'А, $С с Темного Берега. Хорошо, что Селарин прислала тебя так быстро, $N. Прости, что тебе пришлось так спешить. Но с твоей помощью мы, возможно, сможем исправить положение.$B$BЯ бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (991, 'Раэна – санитар Ясеневого леса', '$N, один мой старый друг тоже помогает часовым здесь, в Ясеневом лесу, но он еще не вернулся.$B$BОн думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником. $B$BПрежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла.$B$BОн также говорил, что камень может находиться в святилище на озере Фалатим у подножия западных гор. Камень хранился там до того, как святилище было разрушено. $B$BНайди моего друга, $N, пожалуйста.', 'Найдите в Ясеневом лесу Терониса. ', 'Покрытое ранами тело Терониса лежит на острове. По какой-то непонятной причине мурлоки бросили его здесь.$B$BГлубокие резаные раны явно оставлены оружием и когтями мурлоков.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (992, 'Исследование воды', 'У нас, в Водной компании Прибамбасска, образовалась вакансия на должность младшего геодезиста на временную работу. Интересуешься?$B$BКочевники захватили все наши колодцы, приходится искать альтернативные источники воды! В пустыне есть вода, надо только ее отыскать!$B$BВозьми это устройство для поиска воды и принеси мне пробу из пруда возле Заставы Скорбных Песков. Правда, это место на виду у троллей. Когда закончишь, принеси мне включенное устройство!', 'Воспользуйтесь нетронутым устройством для поиска воды возле пруда на Заставе Скорбных Песков. Забрав пробу, отнесите устройство старшему геодезисту Рудознатцу в Прибамбасск.', 'Что такое? На тебя напали какие-то мерзкие ползучие твари? Ох, плохо это для Водной компании Прибамбасска, ох плохо…$B$BНадо было раньше тебя предупредить насчет этих кошмарных насекомых, которые, кажется, выпивают всю воду в пустыне. Сначала я не придал им значения. Нам хватает проблем и с кочевниками, и мы решили, что это тоже их происки. Теперь мы знаем правду!', 'Рад тебя видеть, младший геодезист $N! Ты уже выполнил задание?', NULL, NULL, 'Включенное устройство для поиска воды', 'Нетронутое устройство для поиска воды', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (993, 'Пропавший хозяин', 'Плащ готов, $N. Пришло время найти Волкора. Я могу только надеяться, что мы успеем.$B$BМагия, скрытая в плаще, если ее пробудить, продержится недолго: может быть, минут пять. $gСам:Сама: решай, когда использовать: я бы предложил подождать, пока не найдешь Лютого Когтя.$B$BЕсли то, что он сказал мне – правда, ты найдешь его хозяина в пещере к югу отсюда. Лютый Коготь будет ждать тебя у дороги. Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину.', 'Найдите Волкора на Темных берегах и отдайте ему зачарованный плащ лунопарда.', 'Чудесно! Терентис прислал мне помощь!$B$BО, посмотри-ка, еще и плащ... *кашляет* Ох... Больно. Спасибо, $N.$B$BФурболги ранили меня, прежде чем я сумел от них улизнуть. Дай мне еще минутку, и я буду в состоянии разговаривать дальше.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (994, 'Спасение с помощью силы', 'Ладно, $N, силой так силой. Давайте убираться отсюда, как только вы будете готовы. Мы пробьемся к дороге – Лютый Коготь должен все еще ждать. А там мы уже сможем разделиться.$B$BТерентис сразу же захочет услышать ваш рассказ, поэтому вы направитесь в Аубердин, когда мы отсюда выберемся.', 'Защищайте Волкора, пока не доберетесь до дороги, а затем поговорите с Терентисом в Аубердине.', '$N! Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Темном Берегу и за его пределами.', NULL, NULL, NULL, 'Защищайте Волкора, пока не доберетесь до дороги.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (995, 'Спасение с помощью скрытности', 'Ну, ладно... Если вы уверены, попробуем выскользнуть отсюда. Мы уйдем, как только вы будете готовы.$B$BНе забудьте после бегства отсюда вернуться к Терентису в Аубердин. А я туда отправлюсь сам по себе, потому что, вероятно, буду двигаться быстрее вас.', 'Совершите побег из пещеры фурболгов и встретьтесь в Аубердине с Терентисом.', '$N! Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Темном Берегу и за его пределами.', NULL, NULL, NULL, 'Помогите Волкору сбежать из пещеры.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (996, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (997, 'Земля Деналана', 'Так ты идешь на юг? К озеру Аль\'Амет? Если да, то не выполнишь ли ты одну мою просьбу...$B$BМой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты. Ему нужна редкая земля из Дарнаса, но ее доставили в Доланаар с опозданием – только что.$B$BНе $gмог бы:могла бы: ты отнести ему эту землю?', 'Отнесите горсть редкой земли Деналану к озеру Аль\'Амет. ', 'Наконец-то! Я уже давно жду эту редкую землю. Надеюсь, она еще свежая...$B$BСпасибо тебе за доставку, $N. Ты – $R, не жалеющий времени на благие дела!', 'Ты что-то мне принес?', NULL, NULL, 'Горсть редкой земли (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (998, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (999, 'Когда сны превращаются в кошмары', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1000, 'Новое пограничье', 'Внимание, герои!$B$BКруг Кенария ищет отважных, которые помогут исследовать обширное новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках!$B$BВсе заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утеса.', 'Обратитесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утеса по поводу помощи Кругу Кенария в исследовании границ Калимдора.', 'Здравствуй, $C.$B$BЯ рад, что героям, подобным тебе, небезразлична судьба природы. Слава о твоих великих деяниях летела впереди тебя, и тебе здесь рады. Узрев тебя, я исполнился уверенности, что Круг Кенария обретет нужную ему помощь.$B$BНаши связи с Кругом Кенария Лунной поляны превыше расовых и политических предрассудков. Помни это, трудясь во славу Круга, и будет тебе благо.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1001, 'Жужжалка 411', 'Тоненький голосок пробивается откуда-то из глубины машины.$B$B\"Бацбах у аппарата! Следующая Жужжалка находится к северу от Аубердина, прямо на берегу.$B$BИтак, номер той Жужжалки – 411, и для ее починки нужно три глаза крепкозуба. Эти твари водятся недалеко от берега! Крепкозубы Темных берегов... *И-ик!* Извини...$B$BКак и в прошлый раз, когда поместишь в Жужжалку то, что нужно, она выдаст тебе награду. *И-ик!* Что? Не, со мной все в порядке!\"', 'Добудьте 3 глаза крепкозуба с крепкозубов Темных берегов, которые водятся в море неподалеку от Жужжалки 411.', 'Жужжалка оживает вскоре после того, как вы помещаете в нее глаза крепкозуба. После коротких помех вы слышите знакомый голосок.$B$B\"Вино из крабов лучше всего...\"*И-ик!*$B$B\"Что? О, ты уже ее починил! Ух, какой ты бысшшштрый. Так шшшо, согласишшшься почшшшинить ешшше одну?\"$B$BВы уверены, что слышите, как жидкость льется в емкость, а затем – звучные глотки.', 'Приемник машины открыт и, кажется, ждет, когда в него поместят 3 глаза крепкозуба.', NULL, NULL, 'Глаз крепкозуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1002, 'Жужжалка 323', '\"Жужжалка\" издает треск статических помех, и вы слышите голос Бацбаха.$B$B\"Шшшледуюшшшая жужшшшалка – номер 323. Она к шшшеверу от Аубердина, но... а хде жшшше эль? Шшшо? О, она шшштоит на дороге, так шшшо ты легко ее найдешшшь около мосшшшт\".$B$BБацбах что-то неразборчиво бормочет, а потом вы слышите отчетливый звук глотка.$B$B\"В эту нужшшшно положшшшить клыки лунопардов... шшшесть\".', 'Добудьте 6 клыков лунопарда и поместите их в \"Жужжалку 323\". ', 'Неожидано Жужжалка начинает работать, и вы отчетливо слышите, как клыки перемалываются внутри машины в муку.$B$B\"Так шшшо, ты это шшшделал! Отлишшшные новосшшшти... И шшшо жшшше... ты не уходишшшь? А! Можшшшет, хочешшшь ешшше поработать?\"', 'Хотя вы еще не поместили внутрь Жужжалки клыки лунопардов, вам кажется, что оттуда раздаются звуки статических разрядов и невнятное гномье бормотание. Может быть, кто-то уже успел починить машину?', NULL, NULL, 'Клык лунопарда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1003, 'Жужжалка 525', 'Сквозь булькающий шум и звуки капающей жидкости, исходящие от машины, вы слышите неверный голос Бацбаха.$B$B\"Шшшледуюшший далеко на юг по доррроге. Найти должно быть нетрудно... шшшразу рядом на обочшшине... возле огражшшдения. Думаю, я шшпрятал его в каких-то кусшшштах... Кусшшшты... Хи-хи... Да, Жужжшшалка 525 снимет сшшшедые шшшкальпы с этттих сшшшедых колючешшшшерстныхх медведей. Божшшшежшшш мой, шшшто за пойло. Гнусшшшные... Хи-хи-хи...\"$B$BВы слышите звуки жадных глотков, и машина выключается. Затем, совершенно неожиданно, вновь оживает.$B$B\"Четыре!\"', 'Соберите 4 седых скальпа с седых колючешерстных медведей к югу от Аубердина и положите их в Жужжалку 525.', 'Так ты шшшшо, положшшил шшшкальпы внутрь? Хорошшшо... Шо? Агга, я шшшоображшшаю, шшшо могу разшшшговаривать шшш тобой и безшшш материалов в машшшине. Но я пррравду грил, когда шшшказшшшал, шшшо они шшшломались!$B$BШшшмотри, кроме шшшредшшштв коммунимакации эти жужжшшшалки ешшше варят и дишшштиллируют отличшшшное питье. Просшшшти зшшша обман, но Ночшшшные эльфы не одобряют торррговли моими напитками в сшшшвоих городах. Я оставлю нечшшшто осшшшобенное в этом яшшшике, шшшобы показать мою благодарносшшшть за твои усшшшилия. Насшшшлаждайся!', 'Вы слышите пение, раздающееся из Жужжалки 525.$B$B\"Хотя изшшш крабов сладкое винннцо, из млатозшшшуба эль хоть куда, и сшшшамогонка лунная вкусна, но нет ничшшего лучше пива медвежшшшьего, и сшшшкоро будет оно у меня!\"$B$BЗаслонка открыта и ждет добытых вами 4 седых скальпов, а песенка звучит снова и снова.', NULL, NULL, 'Седой скальп', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1004, 'Новое пограничье', 'Внимание, герои!$B$BКруг Кенария ищет отважных, которые помогут исследовать обширное новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках!$B$BВсе заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утеса.', 'Обратитесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утеса по поводу помощи Кругу Кенария в исследовании границ Калимдора.', 'Здравствуй, $C!$B$BПриятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается.$B$BНаша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, – и добьешься успеха.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1005, 'Шныряющие за стеной', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1006, 'Что скрывается за стеной', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1007, 'Древняя статуэтка', 'Я хотел бы дать тебе поручение, $N.$B$BЯ на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги, выныривая из воды и вцепляясь в меня когтями! Я убежал, унеся с собой все, что смог, и чего хватило лишь вот на этот жалкий лагерь.$B$BНо когда я добрался до берега и побежал... я потерял одну дорогую мне вещь.$B$BПрошу тебя, $N, найди место засады – это на побережье к северу – и отыщи древнюю статуэтку. Именно из-за нее я отважился подвергнуть себя опасностям Зорамского взморья.', 'Принесите древнюю статуэтку Талену в его лагерь близ Зорамского взморья. ', 'Ты ее нашел! Спасибо тебе, $N!$B$BДревний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них.', 'Ты снашел статуэтку, $N?', NULL, NULL, 'Древняя статуэтка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1008, 'Зорамское взморье', 'По нашему северо-западному побережью, известному как Зорамское взморье, расползается зло.$B$BТам покоятся руины злосчастного города Зорам, разрушенного при Расколе и поглощенного морем. Для ночных эльфов он был утрачен на много веков. Утрачен и почти забыт.$B$BТеперь туда вернулись наги, и мы не знаем, почему. Но причина не так важна – мы должны перебить этих тварей и загнать их обратно в глубины!$B$BВозвращайся, когда выполнишь поручение.', 'Принесите 20 голов наг из клана Зловещего Хвоста Шиндрелл Огненный Всполох в Астранаар.', 'Отлично, $N. Твои деяния против наг на Зорамском взморье достойны похвалы.$B$BЯ знаю, что задание выполнить было нелегко, ибо сила и коварство наг прекрасно известны ночным эльфам. Мы это знаем, ибо у нас одна история.$B$BНо эту историю я вспоминать не желаю.', 'Мы не можем допустить, чтобы наги наводнили наше побережье, $N. Жизненно важно, чтобы ты отправился на Зорамское взморье, дабы довершить свое дело.', NULL, NULL, 'Голова наги из клана Зловещего Хвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1009, 'Руузель', 'Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не найти ключа к этому древнему замку.$B$BЭтим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его.$B$BДолгие годы кольцо считалось утраченным, пока наги недавно не нашли его.$B$BИх предводительница, Руузель, живет на острове на северной окраине Зорама. Прошу тебя, $N, добудь мне это кольцо!', 'Принесите кольцо Зорама Талену на Зорамское взморье. ', 'Ты добыл кольцо! Спасибо тебе, $N. Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты делал сегодня.', 'Говорят, что кольцо Зорама является ключом к любому замку в этом городе. Ты добыл его, $N?', NULL, NULL, 'Кольцо Зорама', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1010, 'Батранов волос', 'Есть одна травка, что росла некогда в древних руинах Убежища Батрана на севере. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души.$B$BВ этой деревне болеет ребенок, и сдается мне, что это болезнь не телесная. Не сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос? Мне он может понадобиться, чтобы вылечить ребенка.$B$BУбежище Батрана лежит к северу от заставы Мейстры и прямо к югу от границы с Темными берегами.', 'Принесите 5 стеблей Батранова волоса Орендилу Широколисту в Ясеневый лес.', 'Ах, ты принес эту травку! Теперь я сварю лекарство для ребенка, и будем молиться, чтобы отвар подействовал.$B$BИ... В Убежище Батрана – Отрекшиеся? Очень тревожная весть. Поистине, очень тревожная...', 'Ты добыл Батранов волос, $N? Ребенок слабеет с каждым часом...', NULL, NULL, 'Батранов волос', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1011, 'Чума Отрекшихся', 'Отрекшиеся, нежить из Орды, проникли в Ясеневый лес, и рыщут среди развалин и курганов. Мы уверены, что их цель – распространить чуму по землям ночных эльфов. Мы должны убедиться в этом!$B$BОтрекшиеся разбили лагерь к югу отсюда, рядом с обителью Дор\'Данил, где они готовят яды и заразу и разливают их по бутылкам. Проложи себе путь в этот лагерь и укради бутыль с заразой. Принеси ее сюда. Я исследую ее и узнаю, для чего она.', 'Принесите бутыль заразы Кайнету Штилю в Лесную Песнь.', 'Очень хорошо, $N. Теперь, когда я проанализирую содержимое бутыли, станут понятны цели Отрекшихся!', 'Ты нашел лагерь $N? добыл бутыль заразы?', NULL, NULL, 'Бутыль заразы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1012, 'Безумные друиды', 'Когда я боролся с ядами Отрекшихся, мне было видение. Я узрел друидов из обители Дор\'Данил, они были отравлены... убиты нежитью! Теперь они стали блуждающими духами, разлученными с телами и обезумевшими от этого.$B$BЧтобы души этих друидов обрели покой, ты $gдолжен:должна: войти в обитель Дор\'Данил и уничтожить ее некогда могучих предводителей – Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.$B$BСделай это и возвращайся ко мне.', 'Убейте друидов: Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца, затем возвращайтесь к Кайнету Штилю в Лесную Песнь.', 'Я ощутил, как утихает боль обители Дор-Даниль, и понял, что ты выполнил свою задачу.$B$BТяжелое дело выпало тебе, Кулер, ибо духи, которых ты уничтожил, всего лишь жертвы злобы Отрекшихся. Но с их погибелью, будем надеяться, и другие безумные духи обретут покой.', 'Страдания друидов Дор-Даниля все еще тревожат мои сны, $N. Ты должен уничтожить их предводителей!', NULL, NULL, 'Таниэль Темный Лес убито', 'Этиль Зов Луны убито', 'Маворис Проблеск Солнца убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1013, 'Книга Ура', '$N, в крепости Темного Клыка хранится книга – книга Ура, я хочу видеть ее в своей коллекции. Ур был великим магом Даларана до того, как оказался в рядах Плети, и его труды по иным мирам представляют большой интерес... для некоторых Отрекшихся.$B$BОтправляйся в крепость Темного Клыка и найди книгу. Принеси мне ее, и я сообщу о твоих заслугах Темной Госпоже.', 'Принесите книгу Ура хранителю Бел\'дугуру в Район Фармацевтов в Подгород.', 'Прекрасно. Эта книга будет прекрасным дополнением моей коллекции трудов Ура. Знания его были велики, однако ограниченность его сознания не давало ему обрести настоящую силу. Именно поэтому он не смог противостоять Плети. $B$BМы, Отрекшиеся, не можем позволить себе роскошь быть слабыми – ведь тогда нам не выжить... $B$BИ уж тем более не обрести власть.', 'Ты нашел книгу, $N?', NULL, NULL, 'Книга Ура', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1014, 'Смерть Аругалу!', 'Аругал по-прежнему сидит в крепости Темного Клыка. Мы не можем считать Серебряный бор стратегическим оплотом Темной Госпожи до тех пор, пока Аругал жив. $B$BЯ позабочусь о том, чтобы искоренить его магию, $N. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам. $B$BОтправляйтесь в крепость Темного Клыка и положите конец скверным деяниям Аругала раз и навсегда. И принесите мне голову этого злодея!', 'Убейте Аругала и принесите его голову Далару Ткачу Рассвета в Гробницу.', 'Наконец-то Серебряный бор избавлен от злодеяний Аругала. Вы сослужили огро$Nю службу Темной Госпоже, $N. Ваша стойкость будет вознаграждена.', 'Со смертью Аругала мы сможем укрепить власть Темной Госпожи в Лордероне.', NULL, NULL, 'Голова Аругала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1015, 'Новое пограничье', 'Внимание, герои!$B$BКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!$B$BВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнасе!', 'Поговорите с верховным друидом Фэндралом Оленьим Шлемом из дарнасского анклава Кенария относительно призыва Круга Кенария к изучению окраин Калимдора.', 'С чего вы решили, что я собираюсь тратить время на таких, как вы, $C? Хотя погодите...Дайте мне разобраться с моими повседневными обязанностями, и тогда, может быть, у меня для вас найдется пара минут. Нет, ну разумеется, благо Дарнасса, да что там – Тельдрассила! – это такая ерунда по сравнению с вашим желанием получить новую побрякушку...$B$BЭти недоумки из Лунной поляны, с их призывом на помощь, тратят мое время – не представляю, как выдержу все это?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1016, 'Браслеты элементалей', 'Бозьми этот божественный свиток – он поможет определить создателя этих элементалей. Но тебе понадобится кое-что взять у этих духов для фокусировки магии свитка – их браслеты прекрасно подойдут.$B$BХватит нескольких неповрежденных браслетов с этих существ. Другие для наших целей бесполезны, но зато у торговцев за них можно кое-что выручить, если пожелаешь продать. Как только ты добудешь неповрежденные браслеты, попытайся использовать свиток. Возвращайся ко мне с результатами, и мы продолжим.', 'Соберите 5 неповрежденных браслетов элементалей, а затем задействуйте на них божественный свиток. После отнесите разгаданный свиток Стражу Велене Звездный Всполох в Приют Серебряного Ветра.', 'Хорошая работа, $N, это даст нам информацию, необходимую для того, чтобы раскрыть преступника. Ты не против помочь нам схватить мага, который наполнил наши пруды порчеными элементалями? У меня сердце сжимается при виде оскверненного Ясеневого леса и других мест, и я просто сгораю от нетерпения схватить волшебника, который так старается еще сильнее навредить этому краю. Мы заставим его за все ответить.', 'Поскольку тебе придется разрушить браслеты, чтобы убить элементалей, наверное трудно будет найти те самые, в которых содержится информация, которая нужна для гадального свитка. Ты можешь выменять нужные тебе браслеты у кого-нибудь другого, но, может, у тебя есть уже разгаданный свиток?', NULL, NULL, 'Божественный свиток исполнения', 'Божественный свиток обещания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1017, 'Маг-призыватель', 'Есть только один маг из нежити в Степях, способный наслать порчу на стольких элементалей воды. И он единственный, кому хватит дури попытаться это сделать. Сарилус Грязнорожденный, наверное, сидит на вершине Вершины Багрового Тумана, да смеется надо мной. $B$B$N, тебе придется проникнуть на вражескую территорию и уничтожить этого мерзавца. Мне надоела его бестолковость, и надо показать ему, что бывает с теми, кто донимает часовых. $B$BУничтожь его и принеси мне его голову. Но соблюдай осторожность, Орда может подкараулить тебя.', 'Убейте Сарилуса Грязнорожденного и принесите его голову часовому Велене Звездный Всполох в Приют Серебряного Ветра.', 'Теперь эта мерзкая ухмылка навсегда стерта с его лица. Славное, воистину славное дело, $N. Возьми – это Свет Элуны, испей его, когда будет казаться, что всему конец, и смерть неминуема. Он спасет тебя по воле Богини.', 'Дело сделано? Сарилус Грязнорожденный мертв?', NULL, NULL, 'Голова Сарилуса Грязнорожденного', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1018, 'Новое пограничье', 'Внимание, герои!$B$BКруг Кенария ищет отважных, которые помогут исследовать обширное новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках!$B$BВсе заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утеса.', 'Обратитесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утеса по поводу помощи Кругу Кенария в исследовании границ Калимдора.', 'Здравствуй, $C!$B$BПриятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается.$B$BНаша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, – и добьешься успеха.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1019, 'Новое пограничье', 'Внимание, герои!$B$BКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!$B$BВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнасе!', 'Поговорите с верховным друидом Фэндралом Оленьим Шлемом из дарнасского анклава Кенария относительно призыва Круга Кенария к изучению окраин Калимдора.', 'С чего ты решил, что я буду утруждать себя беседой с таким, как ты, $C? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идет с важностью поиска этой пустяковины для твоей коллекции!$B$BСначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я еще и это сносить должен?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1020, 'Лекарство Орендила', '$N, я изготовил лекарство, которое, надеюсь, поможет больному ребенку. Отнеси его в Астранаар отцу ребенка, Пельтуру Белой Луне.$B$BЧтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток.', 'Принесите лекарство Орендила Пельтуру Белой Луне в Астранаар.', 'Это от Орендила?$B$BОн славен знанием трав и лекарским искусством. Это лекарство вселяет в меня надежду, которой прежде у меня почти не было...', 'Прошу прощения, но у меня нет времени на разговоры. Мое дитя, моя Релара смертельно больна!', NULL, NULL, 'Лекарство Орендила (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1021, 'Сатиры коварны! Дриады в опасности!', 'Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сестры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло!$B$B$N, ты $gдолжен:должна: найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски.', 'Найдите Анилию в Ксавиане, что в Ясеневом лесу. ', 'Судя по зияющей в боку ране, Анилия на грани смерти.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1022, 'Воющая долина', 'Хотя мы затратили много средств и сил на то, чтобы вытеснить остатки демонов из Оскверненного леса на север, успехи наши невелики. Нам удалось не допустить большую часть демонов в Ясеневый лес.$B$BНа севере, у границы Оскверненного леса, разрушенное святилище Мел\'Тандрис захватили загадочные волколюди. Из-за их пронзительных воплей это место называют теперь Воющей Долиной. Фолиант Мел\'Тандрис, что хранится в святилище может пролить свет на появление там волколюдей.', 'Отправляйтесь в Воющую Долину, изучите фолиант Мел\'Тандрис, затем возвращайтесь к часовому Мелирии Ледяной Тени в Лесную Песнь.', 'Фолиант Мел\'Тандрис действует странным образом. События, которые он записывает, события, которые он показывает... Никто тольком не понимает, почему он делает то, что делает.$B$BТем не менее, понятно, что предмет, который получила жрица Звездная Песня – эта коса Элуны – требует дальнейшего исследования.', NULL, NULL, NULL, 'Изучите фолиант Мел\'Тандрис', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1023, 'Раэна – санитар Ясеневого леса', 'Осматривая вещи Терониса, вы находите дневник, который все еще в неплохом состоянии.$B$BВы берете дневник и оставляете труп Терониса. $B$BОстается только найти камень, который искал Теронис. Раэна говорила, что он где-то здесь. Возможно, его забрали мурлоки...', 'Найдите светящийся самоцвет и вернитесь к Раэне Волкопас в Астранаар с дневником Терониса.', 'This is terrible, $N. Teronis is dead?!$B$BThe time for mourning will come, but for now we must focus our efforts. I shall send some of the Sentinels to recover Teronis\' body as soon as possible.$B$BYou have Teronis\' journal and the gem he was seeking. Do you think you\'re capable of completing his task? I would rest much better knowing his death was not in vain.', NULL, NULL, NULL, 'Светящийся самоцвет', 'Записи Терониса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1024, 'Раэна – санитар Ясеневого леса', 'Тебе придется провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла. Я бы начала поиск от лунного колодца к востоку от озера Ирис. Когда будешь $gготов:готова:, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя.$B$BДриада Шаэл\'дрин будет тебе лучшим, чем я, проводником. Найди ее.$B$BВозьми с собой этот самоцвет – он может понадобиться Шаэл\'дрин, если она решит помочь тебе восстановить жезл.', 'Найдите Шаэл\'дрин у лунного колодца на северо-востоке.', 'О, так тебя послала Раэна? Тогда это и правда серьезное дело. Чем я могу тебе помочь?', 'Здравствуй. Как поживаешь?', NULL, NULL, 'Светящийся самоцвет (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1025, 'Лучшая защита – нападение', 'Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе еще одно поручение, прежде чем ты отправишься к Лунному колодцу.$B$BНа дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращенный разум питается страхом, а кровожадность утоляется кровью невинных жертв.$B$BПомоги часовым защитить эти края, отплати этим чудовищам их же монетой.$B$BДумаю, их лагерь находится к югу от дороги... будь $gосторожен:осторожна:.', 'Убейте 1 дозорного, 2 ведмедей, 10 тотемистов и 12 воинов из племени Гиблой Чащи, а затем вернитесь к Раэне Волкопас в Астранаар.', 'Славная работа, $N. Спасибо тебе.', NULL, NULL, NULL, 'Дозорный из племени Гиблой Чащи убито', 'Ведмедь из племени Гиблой Чащи убито', 'Тотемист из племени Гиблой Чащи убито', 'Воин из племени Гиблой Чащи убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1026, 'Раэна – санитар Ясеневого леса', 'Хотелось бы мне, чтобы у тебя были более хорошие новости.$B$BРаэна права, я знаю о творении Дартола и древнях этих краев – или знала прежде. Они теперь все осквернены, их природа искажена.$B$BЕсли твоя цель – найти еще один фрагмент жезла, то тебе придется найти ключ, чтобы отпереть сундук, в котором он лежит.$B$BДеревянный ключ – на одном из древней к северо-востоку отсюда, близ Оскверненного леса. Как только добудешь его, ищи небольшую лощинку к западу от дороги близ границы Оскверненного леса... Сундук должен быть спрятан где-то там.', 'Найдите деревянный ключ и обломок жезла Дартола прежде, чем вернуться к Шаэл\'дрин у Лунного колодца.', 'Я рада твоему возвращению, $N.', 'Меня беспокоит то, что древни подверглись порче. Хотелось бы мне побольше сделать для них.', NULL, NULL, 'Железная ось', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1027, 'Раэна – санитар Ясеневого леса', 'Последний фрагмент жезла был отдан на хранение друидам Дор\'Данила. Я понятия не имею, где они его спрятали. Сожалею, что больше ничем не могу тебе помочь.$B$BМогу только сказать, что тебе следует идти по дороге, что ведет в Степи. Друиды скрывались к востоку от этой дороги, но они тебе уже не помогут – недавно их перебили... мне не очень хочется об этом думать.$B$BКогда найдешь последний фрагмент, принеси его мне, и я помогу тебе воссоздать жезл.', 'Найдите последний фрагмент жезла Дартола и вернитесь к Шаэл\'дрин у Лунного колодца.', 'Ты нашел последний фрагмент? Тебе очень повезло... И Раэне тоже.$B$BКак понимаю, нам надо попытаться собрать его, да?', 'Ты нашел последний фрагмент жезла, $N?', NULL, NULL, 'Железное навершие', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1028, 'Раэна – санитар Ясеневого леса', 'Вот собранный жезл, $N. Восстановить его было просто... Труднее будет найти святилище, в котором жезл можно будет наполнить силой.$B$BНо при твоих целеустремленности и усердии, после всех твоих достижений тебе не слишком трудно будет его найти.$B$BСтупай на юго-восток – там очень мало торных дорог, так что будь осторожнее – и посматривай на север. Святилище скрыто в горах, что окружают эту долину.$B$BКак только ты окажешься там, положи жезл в святилище... а остальное сделает магия. Хе-хе.', 'Найдите потаенное святилище и снова наполните чарами жезл Дартола.', 'Когда свечение угасает, вы видите в купели святилища заново наполненный чарами жезл.', 'Вы ощущаете ненавязчивую, но мощную силу в святилище и окружающих деревьях.$B$BВы кладете жезл в святилище, и вас окутывает тихий звон, а святилище начинает светиться...', NULL, NULL, 'Воссозданный жезл (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1029, 'Раэна – санитар Ясеневого леса', 'Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверен, она знает, куда тебе направиться дальше. $B$BУдачи, $N.', 'Вернитесь к Раэне Волкопас в Астранаар.', 'Ты собрал жезл, который отправил тебя искать Теронис? Это приятно слышать.$B$BТеронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1030, 'Раэна – санитар Ясеневого леса', 'Увы, не могу сказать, что у него было на уме.$B$BЕсли он сказал правду о силе жезла, то тогда ты сможешь принимать тот или иной образ. Какой – не знаю.$B$BМожет, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным фурболгам, но даже не затронутые порчей существа убили бы его, не будь он осторожен. Дартол, превращенный при помощи жезла, должен был бы поговорить с фурболгом, не подпавшим под порчу Мха Скверны.$B$BНа мой взгляд, надо начать поиски к юго-востоку от озера Мистраль.', 'Найдите не затронутого порчей фурболга и поговорите с ним при помощи жезла преображения Дартола.', 'Да-да... ты мой сородич, но ты здоровый. Пока еще чистый.$B$BНе знаю, как уж тебе удалось избежать тех злодеяний, что ночные эльфы обрушили на наш народ, но я рад, что больше я не одинок.$B$BНынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами. Это они с нами такое сделали... Они виноваты в том, что меня изгнали из племени.$B$BПо ночам я по-прежнему вижу костры в темноте.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1031, 'Ветвь Кенария', 'Анилия кладет руки вам на плечи и привлекает вас к себе. Задыхаясь, она показывает на находящуюся на севере арку, затем глаза ее закрываются, и из последних сил она шепчет: \"Он забрал ее... Гелтарис...\" И в душе вы понимаете, что Анилия умирает, жаждая, чтобы Ветвь Кенария была возвращена дриадам.', 'Убейте Гелтариса и верните Ветвь Кенария Иллиане в Лесную Песнь.', 'Анилия умерла? Нет, этого не может быть! Кажется, только вчера мы вместе бегали и играли в лесах!$B$BСчастливые дни теперь миновали...', 'Ты нашел их? Что сказала Анилия? Где она?', NULL, NULL, 'Ветвь Кенария', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1032, 'Убийство сатиров!', 'Поверить не могу – Анилии нет! Как часто мы вместе резвились в лесах... Я почти ощущаю... печаль. $B$BЯ знаю, от чего мне станет лучше. Пожалуйста, убей сатиров, что отняли у меня Анилию! Принеси мне их рога в доказательство своего деяния, и я буду навек тебе благодарна.', 'Принесите 16 рогов сатиров Иллиане в Лесную Песнь. ', 'Спасибо тебе, добрый $R. Душа моей сестры возрадуется твоим деяниям.', 'Пожалуйста, помоги мне отомстить за смерть Анилии.', NULL, NULL, 'Рога сатира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1033, 'Слеза Элуны', 'Я надеялся, что лекарство Орендила спасет Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие еще он попытается применить лекарства, если первое не поможет.$B$BСлеза Элуны – это такой камень, который можно найти только в одном месте – на острове в озере Ирис к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, $N, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!', 'Принесите Слезу Элуны Пельтуру в Астранаар.', '', NULL, NULL, NULL, 'Слеза Элуны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1034, 'Руины Звездной Пыли', 'Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже ее мучить, хвала богине. Но... лихорадка все еще сжигает ее.$B$BОрендил рассказал мне о морозной пыли, которую находят среди руин Звездной Пыли. Может, она усмирит лихорадку Релары. Собери немного этой пыли, прошу тебя, и принеси ее мне.$B$BРуины Звездной Пыли находятся на юге, $N. Да ускорит твой шаг Элуна!', 'Принесите 5 горстей звездной пыли Пельтуру в Астранаар.', '', NULL, NULL, NULL, 'Горсть звездной пыли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1035, 'Зеркало Небес', 'Лихорадка Релары прошла, но она еще очень слаба. Я не верю, что только время вернет ей былую силу. Мне кажется, тут нужна мощь лунного камня.$B$BМы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники.$B$BИх предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты $gдолжен:должна: отнять лунные камни у Оракула.$B$BИ, боюсь, для этого тебе придется его убить.', 'Отнимите лунный камень Упавшего Неба у Чащобного Оракула и принесите его Пельтуру в Астранаар.', 'О, $N, ты спас мою дочь! Я знаю, что сила лунного камня вернет моей дочери силы!$B$BМне никогда не отблагодарить тебя за все, что ты для меня сделал, но... пожалуйста, возьми вот это. После Релары это самое дорогое, что есть у меня.', 'Ты сразился с Чащобным Оракулом, $N? Если так, до дай мне, пожалуйста, лунный камень. Релара при последнем издыхании!', NULL, NULL, 'Лунный камень Упавшего Неба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1036, 'Суши весла, сухопутная крыса', '$N... Да, я слышал про тебя. Говорят, что ты не друг Пиратской Бухте – как и мы, пираты Кровавого Паруса. Командир флота Фираллон ищет здоровых и крепких воинов, чтобы послать их на особое задание.$B$BЗвучит заманчиво? Тогда отправляйся на \"Кровавую завесу\" и поговори с ним. Он в одной из кают. Корабль на стоянке на Диком берегу к востоку отсюда, рядом с \"Буруном\" и \"Госпожой Удачей\".', 'Поговорите с командиром флота Фираллоном на борту \"Кровавой завесы\" на побережье Тернистой долины.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1037, 'Велинда Песнь Звезд', 'Велинда Песнь Звезд была моей предшественницей здесь, в Ясеневом лесу. Поначалу казалось, что она держдит под контролем ситуацию в Оскверненном лесу, но понемногу ее усилия стали сходить на нет. И однажды она просто исчезла.$B$BМеня послали сюда продолжить ее труды. Но боюсь, я ничего не знаю об этой жрице. Возможно, Тин\'тель Танец Клинка, одна из командиров часовых, знает подробности ее исчезновения, о которых не знаю я.$B$BНаверняка она поймёт значение такой информации.', 'Поговорите с Тин\'тель Танцем Клинка на террасе Воинов в Дарнасе.', 'Велинда Песнь Звезд? То, что эта жрица пропала некоторое время назад, известно всем. Что касается событий, окружавших ее исчезновение... Чтобы поделиться такой информацией, мне нужна веская причина.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1038, 'Эффекты Велинды', 'Значит, это ты вычитал в фолианте Мел\'Тандрис? Думаю, ничего страшного не будет, если ты осмотришь ее вещи. Этот ключ позволит тебе отпереть сундук, в котором она держала свои пожитки в казарме часовых. Она вела дневник, и если что-то можно узнать, то только из него.$B$BДолжна тебе сказать, что часовые считают, что у нее была причина уйти, и ждут ее возвращения в любой момент. Эта жрица многими своими делами заслужила наше доверие.', 'Поищите в сундуке Велинды ее дневник, затем принесите его вместе с ключом Тинтэль Танцующий Клинок в Дарнас.', 'Похоже, что исчезновение Велинды – не столь безобидное дело, как казалось поначалу. Но я все равно не могу поверить, что она плохо кончила. Может, нам лучше будет найти ее?$B$B$N, раз уж ты проявил живой интерес к этому делу, то я была бы рада заручиться твоей поддержкой.', 'Что удалось найти?', NULL, NULL, 'Записи Велинды', 'Ключ Велинды (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1039, 'Порт в Степях', 'Кабестан – единственный порт в Степях. Скорее всего, Велинда нашла там торговое судно, которое шло в бухту Черноводья в Азероте. Мы ограничили сделки с гоблинами, которые руководят портом, но смотритель пристани наверняка знает, какие пассажиры взошли на борт, а какие сошли на берег.$B$BСледуй по дороге на юго-восток через Ясеневый лес, и попадешь в Степи. Смотри по сторонам, $N, эти края патрулируют солдаты Орды. Но в порту ты будешь в безопасности.', 'Поговорите с управляющим пристанью Головокружилкинсом в Кабестане, что в Степях.', '$R? Должен сказать, твоих сородичей тут у нас нечасто увидишь. Кого-то ищешь, да? Минуточку, сейчас гляну в своих учетных списках.$B$BЧерез порт проходит куча народу, так что подожди минутку, сделай милость.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1040, 'Дорога до Пиратской Бухты', 'А, наконец-то, нашел. Надо было сразу сказать, что она проезжала здесь давно. Посмотрим.$B$BВелинда. Оплатила проезд до Пиратской Бухты на \"Черной Скопе\". Никаких дополнительных пометок нет – значит, она благополучно добралась до места назначения. $B$BБольше ничем я помочь не могу, хотя она спрашивала, какие средства передвижения есть по ту сторону моря, и я упомянул Раззгота, водящего караваны из Пиратской Бухты. Быть может, Велинда отправилась с ним. $B$BНу все, давай, иди. Не весь же день с тобой болтать.', 'Плывите в Пиратскую Бухту и поговорите с караванщиком Раззготом.', 'Да? Не похоже, чтобы ты хотел отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратился.$B$BЯ угадал?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1041, 'Путь каравана', 'Оказывается, я ошибался насчет тебя, а я это не часто признаю.$B$BОказывается, я помню эту Велинду. Не каждый день жрица ночных эльфов желает отправиться в путь со старым грязным – но превосходным для транспортировки товаров – караваном вроде моего.$B$BПо пути на север мы разделились, и она направилась в Темнолесье. Тамошний клерк ведет записи. Может, он знает что полезное.$B$BОсторожнее в джунглях, они даже в лучшие времена – опасное место.', 'Поговорите с клерком Далтри из Темнолесья.', 'В последние годы случилось много странного, и я стараюсь вести записи про всех чужаков. Никогда не узнаешь, что пригодится... Хотя когда эти записи оказываются нужны, добра не жди... Нет, про вашу Велинду я не хочу сказать ничего дурного.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1042, 'Семья Карвин', 'Нет, у меня не сохранилось записей о пребывании Велинды Песни Звезд в Темнолесье... Хотя, прошу прощения за прямоту, не могу представить, чтобы жрица ночных эльфов снимала комнату в таверне, если ты понимаешь, о чем я.$B$BА вот о волко-людях я слышал, и не раз. Только недавно Калор явился в город, неся целую связку их голов. Он работает на Карвинов, которые охотятся на демонов и прочих чудовищ. Поговори с Джонатаном, главой их дома.', 'Поговорите с Джонатаном Карвином в Темнолесье.', 'Темные настали времена. Каждая ветвь в лесу нашептывает дурные вести, зло таится под каждым камнем.$B$BИ в такую пору незнакомец приходит в мой дом и задает вопросы про воргенов... Прощения за свои подозрения я просить не буду, зато потребую ответить на них.$B$BИ получу ответ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1043, 'Коса Элуны', 'Кажется, ты говоришь правду... Я не до конца понимаю твои мотивы, но если ты $gготов:готова: избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться. Важен результат.$B$BВоргены захватили рудник на юге. Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника.$B$BСтупай по своим делам, но если найдешь что-нибудь важное, расскажи об этом мне. Мы готовы принять любую помощь в нашей войне с силами зла.', 'Отыщите признаки местонахождения Косы Элуны и вернитесь к Джонатану Карвину в Темнолесье.', 'Интересные вещи ты рассказываешь, $N. Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить ее раз и навсегда, мы делаем все, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу.$B$BЯ уже велел Калору уделить этому первоочередное внимание.', NULL, NULL, NULL, 'Найдите доказательство присутствия Косы Элуны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1044, 'Полученные ответы', 'Мы разберемся с воргенами, не беспокойся. Искореним зло, которое твоя подруга невольно принесла в наши леса. Мы не в обиде на нее. Странные вещи творятся в наши времена, $N, и тьма не ведает пощады.$B$BНе буду тебя задерживать. Уверен, многие захотят узнать о том, что ты $gобнаружил:обнаружила: в рудниках Сумеречного леса.', 'Вернитесь к Тин\'тель Танцу Клинка в Дарнас.', 'Так вот какова судьба Велинды? Верховная жрица огорчится, услышав об этом – они очень дружили до исчезновения Велинды. И все же Коса Элуны несомненно была дарована Велинде нашей богиней, и очень плохо, что этот священный предмет попал в недобрые руки.$B$BВпрочем, это отдельный разговор. Я премного благодарна тебе за твои достижения.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1045, 'Раэна – санитар Ясеневого леса', 'Ночные эльфы стары, как время, но их надменность разрушает их собственный мир. А теперь еще и наши жизни. Но это уже никак не получится контролировать...$B$BЯ много в чем могу обвинять эльфов, но мы все равно отвечаем за свои деяния. Даже не подвергнувшись порче, мы способны творить великое зло.$B$BРэн Кровавый Клык – такое зло. Жаждущий мощи, алчный... порча только сделала его сильнее. Меня сжигает ненависть к эльфам, но я не хочу зла их детям, так что сами должны обуздать своих.', 'Убейте Рэна Кровавого Клыка, 4 кровозубых стражей и принесите череп Рэна Кролгу у озера Мистраль.', 'Хорошая работа.$B$BЛес все еще осквернен, но мы по крайней мере знаем, что сделали хоть немного для того, чтобы вернуть его прежнюю красоту. Если пожелаешь снова вернуться ко мне, я буду рад обществу сородича.$B$BУдачи тебе. Возможно, наши племена снова встретятся в не столь жестокие времена.', 'Ты еще не убил Рэна?$B$BДаже ночные эльфы не заслуживают его злобы. Его ненависть пылает даже ярче моей, но он уже не владеет собственным разумом. Он – угроза для всех исконных обитателей этого леса.', NULL, NULL, 'Рэн Кровавый Клык убито', 'Кровозубый страж убито', 'Череп Рэна Кровавого Клыка', 'Жезл Преображения Дартола');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1046, 'Раэна – санитар Ясеневого леса', 'Возвращайся в свое племя и поведай им о нашей победе.$B$BПокажи им свой трофей и насладись славой...', 'Принесите череп Рэна Кровавого Клыка Раэне Волкопас в Астранаар.', 'Значит, вот он – череп самого лютого фурболга в Ясеневом лесу?$B$BЯ более чем довольна твоими способностями, $N. Не знаю даже, как часовым отблагодарить тебя. Надеюсь, в будущем мы снова сможем положиться на тебя, чтобы помочь нашему народу.$B$BЯ положу этот череп и жезл Дартола на почетное место, чтобы все их увидели. $B$BТеронис гордился бы тобой. Еще раз спасибо тебе.', 'Часовые здесь, в Ясеневом лесу, делают что могут, но лишь благодаря таким $Cs как ты, мы не сдаем своих позиций.', NULL, NULL, 'Череп Рэна Кровавого Клыка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1047, 'Новое пограничье', 'Внимание, герои!$B$BКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!$B$BВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнасе!', 'Поговорите с верховным друидом Фэндралом Оленьим Шлемом из дарнасского анклава Кенария относительно призыва Круга Кенария к изучению окраин Калимдора.', 'С чего ты решил, что я буду утруждать себя беседой с таким, как ты, $C? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идет с важностью поиска этой пустяковины для твоей коллекции!$B$BСначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я еще и это сносить должен?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1048, 'В монастырь Алого ордена', '', '', 'Ты сослужил Темной Госпоже отличную службу, $C. Это задание было не из легких.$B$BЯ не забуду о твоей преданности Отрекшимся и стойкости в битве.', NULL, NULL, NULL, 'Верховный инквизитор Вайтмейн убито', 'Командор Алого ордена Могрейн убито', 'Ирод убито', 'Псарь Локси убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1049, '\"Компендиум павших\"', 'Намерения Служителей Земли относительно наших пораженных болезнью братьев чисты. Но кому ведомы замыслы тех, кто нашептывает всякое Совету старейшин?$B$BУ Отрекшихся, с которым мы ныне в союзе, вся история полна лжи. Слишком мы поторопились с союзом. Возможно, Кэрн прислушается к предупреждениям из Оргриммара.$B$BВ недрах монастыря Алого ордена находится \"Компендиум павших\", который стерегут безумные фанатики-люди. В том, что они творят, сквозит безумие, однако их исследования могут оказаться для нас полезными.', 'Добудьте \"Компендиум павших\" из монастыря в Тирисфальских лесах и возвращайтесь к Ведуну Искателю Истины в Громовой Утес.', '\"Компендиум павших\"! А я уж начал было сомневаться в том, что он вообще существует!$B$BТы сослужил добрую службу тауренам Громового Утеса, $N. Твоя преданность не будет забыта.', 'Кэрн – отважный и благородный вождь, и я доверил бы ему свою жизнь. Но есть и те, кому я в нынешние времена нипочем бы не доверился.$B$BКак только смогу собрать все возможные сведения, я сумею дать вождю небезосновательный совет.$B$BТебе удалось добраться до Тирисфальских лесов? Удалось проникнуть в Монастырь Алого ордена? \"Компендиум павших\" – лишь кусочек сложной мозаики...', NULL, NULL, '\"Компендиум павших\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1050, '\"Мифология Титанов\"', 'Будущее неотвратимо! Мы стремимся к нему подобно тому, как дождевые капли стремятся к Великому морю.$B$BНо, изучая прошедшее, мы узнаем, что ждет нас в грядущем, и готовимся к встрече с неведомым.$B$BПрежде чем великие беды обрушились на Лордерон, в Тирисфальских лесах находился оплот знаний. Ходят слухи, что в библиотеке старого монастыря хранится книга под названием \"Мифология $Nв\".$B$BПринеси ее мне – и, возможно, вместе мы сможем заглянуть в тайны прошлого!', 'Добудьте \"Мифологию Титанов\" из монастыря и принесите ее библиотекарю Мае Белокожке в Стальгорн.', 'Ты спас священный текст!$B$BТвое путешествие было долгим, а уж добыть такую книгу было несомненно трудно. Но дворфы Стальгорна от твоего успеха получат огро$Nю выгоду.$B$BСпасибо тебе, $N, от лица всей Лиги Исследователей.', 'Этот монастырь был духовной школой паладинов. Некогда он был цитаделью Света, а теперь попал в руки безумных фанатиков Алого ордена.$B$BОни считают, что у них благородная цель – очистить землю от нежити. Но безумие запятнало их деяния, и ныне они враги всем.$B$BПринеси мне \"Мифологию Титанов\", чтобы я могла изучить эту книгу. Я буду хранить ее здесь, в Стальгорне.$B$BОскверненные стены монастыря – не место для такого исторического сокровища.', NULL, NULL, '\"Мифология Титанов\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1051, 'Месть Воррела', 'Моя воля свободна, и все же я не могу более служить Темной Госпоже. Я чувствую, что время, отпущенное мне в Азероте, подходит к концу. Жизненные силы покидают меня.$B$BДознаватель Вишас всему виной! Он пытал меня много недель! Мало того, он отобрал у меня обручальное кольцо и нацепил его на палец своей жене! Чудовище!$B$BЯ жажду мести!$B$BЭтот глупец похвалялся своей прекрасной женой Нэнси, что живет у озера Лордамер. Я хочу, чтобы ты $gотыскал:отыскала: девку и $gвытряс:вытрясла: из нее душу вместе с моим кольцом! Верни кольцо моей жене Монике, она живет в Мельнице Таррен.$B$BИсполни мою последнюю волю.', 'Верните обручальное кольцо Воррела Сенгутца Монике Сенгутц в Мельнице Таррен.', 'Воррел был мне добрым супругом... $B$BПроклятые смертные! $B$BНикогда нам более не быть вместе. По крайней мере, я найду утешение в свершенной тобой мести. Благодарю тебя. $B$BА теберь оставь меня наедине с моим горем.', 'Что тебе нужно, странник?', NULL, NULL, 'Обручальное кольцо Воррела', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1052, 'По пути Алого ордена', 'Мы, рыцари Алого ордена, заявляем свои права на укрепления от Дольного Очага до Тирисфальских лесов. Мы гордимся нашей борьбой за чистоту Лордерона!$B$BВы подтвердили свою репутацию, сражаясь против нежити в Пустошах. Но настоящая угроза исходит из Лордерона.$B$BОтправляйся в Восточные королевства, в город Южнобережье. Отнеси письмо с моими рекомендациями и печатью рыцарю Райли Благочестивому. Он проводит тебя в монастырь Алого ордена.', 'Отнесите рекомендательное письмо брата Антона Ролею Благочестивому в Южнобережье.', 'Брат Антон по-прежнему проповедует идеи Алого ордена? О-ох...', 'Кто идет? Что вам от меня надо?', NULL, NULL, 'Рекомендательное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1053, 'Во имя Света!', 'Я всегда служил Алому ордену, гордился им и почитал служение за честь. Мне было чем гордиться, ведь мы спасали Азерот от нежити.$B$BНо после некоторого времени, проведенного в монастыре Тирисфальских лесов, я понял, что не ведал об истинных намерениях высшей иерархии ордена. Каждого, кто не принадлежит к ордену, они почитают грешниками. Невинных мужчин и женщин подвергают пыткам, полагая их нечистыми.$B$BВо имя Света, Алый орден должен быть сокрушен. И вам, $N, по силам остановить это чудовище.', 'Убейте Верховного инквизитора Вайтмейн, командира Могрейна из Алого ордена, воителя Ирода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Ролею Благочестивому в Южнобережье.', 'Хотя путь Света не приемлет убийств и кровопролитий, но в подобных случаях кровавая жертва служит благу королевства и всего мира.$B$BВаши деяния в монастыре помогли спасти множество невинных жизней. $N, я восхищаюсь вашей решительностью.', NULL, NULL, NULL, 'Верховный инквизитор Вайтмейн убито', 'Командор Алого ордена Могрейн убито', 'Ирод убито', 'Псарь Локси убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1054, 'Устранение угрозы', 'Прямо к северу от Астранаара живут фурболги Колючего Меха. Мои разведчики доносят, что в последние несколько месяцев они чрезвычайно умножились числом. Если они слишком расплодятся, то могут набраться наглости напасть на Астранаар!$B$BУбей их, сколько сможешь, главное – принеси мне череп их предводителя в знак того, что их усилия напрасны...пока. $B$BЯ останусь в Астранааре и буду ждать вестей от тебя. Да пребудет с тобой Элуна.', 'Принесите череп Дала Жилотяга Раэне Волкопас в Астранаар.', 'Славная работа, $N.$B$BЭти фурболги постоянно угрожают нам. По счастью, теперь они некоторое время будут сидеть тихо.', 'Из-за этой фурболгской заразы дни славы Ясеневого леса остались далеко в прошлом.', NULL, NULL, 'Череп Дала Жилотяга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1055, 'Раэна – санитар Ясеневого леса', 'Воссозданный жезл у вас в руках. Шаэл\'дрин захочет услышать о ваших успехах.', 'Вернитесь к Шаэл\'дрин у лунного колодца.', 'У тебя получилось, $N! Великолепно!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1056, 'Путешествие к Пику Каменного Когтя', 'Лесные духи говорят мне, что ты $gотважен и легок на подъем:отважна и легка на подъем:.$B$BНа юге, неподалеку от озера Мистраль, находится туннель, именуемый Туннель Когтя. Через этот туннель ты попадешь в место, называемое Утес Ветрорезов, в Когтистых горах. Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберешься до Пика Каменного Когтя.$B$BТам ждет хранитель Албагорм. Выслушай его просьбу, $r.$B$BПутешествие будет опасным.', 'Отправляйтесь к хранителю Албагорму на Пик Каменного Когтя.', 'Наконец-то! Вижу, Фальдреас прислушался к духам лесов...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1057, 'Возвращение Горелой Долины', 'Несомненно, будучи защитником лесных духов, можешь догадаться, почему я так встревожен.$B$BЧтобы достигнуть этого пика, тебе пришлось пройти через горы, и, конечно же, от глаз твоих не ускользнуло искажение, постигшее эту землю. Алчность привела к уничтожению священных холмов.$B$BОбугленная долина на юге сожжена механической армией жадных промышленников. Хуже того, клан Смертельной Ярости, вторгшийся на эти земли, отказывается пропустить нас – а ведь мы могли бы начать восстановление тех краев!$B$BИзгони прочь злобных гарпий, $N!', 'Хранитель Албагорм с Пика Каменного Когтя просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости.', 'Теперь, когда клан Смертельной Ярости понес большие потери, вероятно, и начнется истинная работа по восстановлению этих земель...', NULL, NULL, NULL, 'Гарпия из стаи Кровавой Ярости убито', 'Душительница из стаи Кровавой Ярости убито', 'Душегубка из стаи Кровавой Ярости убито', 'Бродяжница из стаи Кровавой Ярости убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1058, 'Лесная магия Джин\'Зила', 'Я в восхищении!$B$BТри маленьких клетки для трех маленьких эльфов. Ну-с, что бы нам сделать с нашими дорогими друзьями-древолюбами? Что ж, дадим им попробовать... как бы это они сказали... лесной магии!$B$BМне нужна добрая порция слизи Каменного Когтя. Принеси мне несколько сумеречных усиков этих ужасных кошек. И конечно же, потребуется множество глаз бегового оленя – глаз всегда не хватает! Да, и еще, последнее, чуть не забыл: драгоценную чешуйку волшебного дракончика.$B$BЖиво в Каменный Коготь, $N, чтобы я мог сварить немножко лесной магии!', 'Знахарь Джин\'Зил из Малака\'джина требует принести 5 порций слизи Каменного когтя, 5 сумеречных усиков, 30 глаз бегового оленя и чешуйку волшебного дракончика.', 'О, как счастливы будут эти маленькие лесные нимфы! Мы заставим их почувствовать себя как дома при помощи этого особого отвара!', 'Взгляни на наших маленьких друзей-эльфов! Заперты в клетках и не могут побродить по лесу!$B$BТебе удалось раздобыть для меня немного слизи? А как насчет усиков сумеречного бегуна? А разве у тебя еще нет чешуйки волшебного дракончика?$B$BА глаза? Мне нужно так много глаз! Невозможно составить доброе магическое лесное варево без хорошей порции глаз!', NULL, NULL, 'Слизь Каменного Когтя', 'Сумеречный Ус', 'Глаз бегового оленя', 'Чешуя волшебного дракончика');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1059, 'Возвращение Обугленной долины', 'Мы одержали победу над кланом Смертельной Ярости. Но они скоро соберут силы и вернутся, если не предпринять решительные действия. $B$BДалеко на юге Пустошей находится земля, известная как Тысяча Игл. Если идти на запад Тысячи Игл до тех пор, пока не достигнешь границ густого леса Фералас, то встретишь друида по имени Фалфиндер Хранитель Дорог.$B$BЭтот сильный и мудрый друид способен призвать великих лесных духов, которые помогут в восстановлении Обугленной долины.$B$BПоведай ему о нашей беде! Отправляйся на его поиски немедленно!', 'Отправляйтесь к Фалфиндеру Хранителю Дорог, живущему на границе Тысячи Игл и Фераласа.', 'Хранитель Албагорм поступил мудро, прислав тебя со срочным известием.$B$BБудем надеяться, что мы успеем призвать помощь, и что эта помощь из великого леса прибудет в Обугленную долину не слишком поздно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1060, 'Письмо Джин\'Зилу', 'Ты $gсделал:сделала: мне много добра, $N. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что еще.$B$BГарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин\'Зилу.$B$BОн будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место.', 'Отнесите письмо Дарсока Джин\'Зилу в пещеру Малака\'джин в Когтистых горах.', 'А, письмо от Дарсока. Давно от него не было вестей.$B$BЗначит, последняя из Кровавых Перьев мертва? Отличные вести. Я хорошо помню, как мой друг Рохан пошел убивать ее старшую сестру с этим психом из Мок\'Натала. Да, тогда я был молод, как ты сейчас.', 'На вид ты темная личность. Ты хочешь мне что-то показать?', NULL, NULL, 'Письмо Джин\'Зилу (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1061, 'Духи Каменного Когтя', 'Духи Когтистых гор разгневаны: гоблины и их приспешники разоряют и выжигают земли. Земля возопила, и те, кто способен слышать – услышали.$B$BВ Когтистые горы отправилась Сирит Камнеломм, многообещающий шаман Орды. Она сообщает, что гоблины вырубили много леса, и просит о помощи.$B$BОтправляйся в Когтистые горы, найди там Сирит. Чтобы туда добраться, ступай от Перекрестка в Степях по дороге на запад. Сирит стоит лагерем близ Долины Высокого леса.', 'Поговорите с Сирит Камнелом на границе Когтистых гор и Степей.', 'А, $C! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1062, 'Вторжение гоблинов', 'Торговая Компания, которой управляют гоблины, вторглась в Когтистые горы. Они валят деревья, выжигают большие участки леса. Духи этих земель вне себя от боли и ярости. Мы должны остановить Торговую Компанию!$B$BОтправляйсся на северо-запад, за Долину Высокого леса, к Утесу Ветрорезов. Ты найдешь гоблинов и их прислужников за работой - покажи же им, что Орда не позволит разорять Когтистые горы. Поговори с ними на том языке, который они лучше всего понимают...$B$BНа языке беспощадной силы!', 'Убейте 15 лесорубов Торговой Компании, затем вернитесь к Сирет Камнелом на границу Каменного Когтя и Степей.', 'Это подлинно отважное деяние, $N.$B$BВероятно, в конце концов нам понадобится мудрость тауренских старейшин, чтобы успокоить духов Каменного Когтя, но...$B$BПервый шаг в верном направлении сделан – Торговая Компания лишилась работников.', NULL, NULL, NULL, 'Лесоруб Торговой Компании убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1063, 'Мудрая старуха', 'Чтобы узнать, как окончательно успокоить духов Когтистых гор, нам нужно посоветоваться со старейшинами тауренов.$B$BЯ мало знаю о том, кто предводительствует тауренами, но одно имя мне известно: Магата. Я слышала, что она очень стара и много знает. Если кто из тауренов и может оказать нам помощь касательно духов, то это она.$B$BМагата живет в главном городе тауренов Громовом Утесе, на Вершине Старейшин – это северо-восточная вершина города. Поговори с Магатой и расскажи ей о том, что творится в Когтистых горах.', 'Поковорите с Магатой в Громовом Утесе.', 'Я приветствую тебя. Ты ищешь совета?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1064, 'Помощь Отрекшихся', 'Таурены в сродстве с этой землей, и мне больно слышать о том, что творится в Когтистых горах. Но я боюсь, что для исцеления этой земли нам прежде придется справиться с той заразой, что терзает нас самих.$B$BРазве не удача, что Отрекшиеся теперь с нами? Они много знают о заразных болезнях. Я уверена, что они смогут помочь нам и тем укрепят доверие между нашими народами.$B$BПоговори с аптекарем Замой. Она – ученая и представитель Отрекшихся. Ты найдешь ее у Прудов Видений под Уступом Духов.', 'Поговорите с аптекаршей Замой у Прудов Видений в Громовом Утесе.', 'Магата прислала о тебе весточку, $N. Хотя сердце мое уже и не бьется, оно все же разрывается от горя по духам Каменного Когтя.$B$BОтрекшиеся готовы помочь всем, чем только можно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1065, 'Путешествие в Мельницу Таррен', 'Нам придется прибегнуть к чрезвычайным мерам, чтобы избавить Когтистые горы от Торговой компании. Но только без кровопролития.$B$BУ одного моего коллеги может найтись то, что нам как раз для этого случая и нужно. Его зовут Лидон, он живет в городе Мельница Таррен в предгорьях Хилсбрада, в далеком краю Лордерон.$B$BЧтобы добраться до Хилсбрада, отправляйся на дирижабле в нашу столицу, Подгород. Оттуда иди на север в Тирисфальские леса, что к юго-западу от Серебряного бора, а затем на юг, в Хилсбрад.$B$BНайди Лидона и передай ему эту записку. Там написано, что нам от него нужно.', 'Принесите записку Замы аптекарю Лидону в Мельницу Таррен.', 'Записка от Замы? Наверняка ее сильно прижало, раз пишет в такую даль. Посмотрим...$B$BЗамечательно! Я знаю, что ей надо!', 'Ага, вы доставили мне новых подопытных?', NULL, NULL, 'Записка Замы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1066, 'Невинная кровь', 'Я создам яд, который остудит пыл Торговой компании. Они станут слабыми и покорными. Это же решит проблемы Орды в Когтистых горах, да?$B$BНо для создания отравы мне понадобится кровь невинных, а ее нелегко найти.$B$BК счастью, Синдикат, группа грабителей, насчитывает в своих рядах несколько темных магов... а они собирают кровь невинных для своих нечистых целей.$B$BТемных магов Синдиката можно найти в крепости Дарнхольд на юго-востоке.', 'Принесите 5 фиалов крови невинных аптекарю Лидону в Мельницу Таррен.', 'Очень хорошо! Надеюсь, Синдикат не причинил тебе особых проблем?$B$BКак я и говорил, кровь невинных не так уж легко добыть. Нам повезло, что трудную часть работы взяли на себя маги Синдиката.$B$BА теперь подожди, я создам мой состав...', 'Тебе удалось найти темных магов Синдиката и принести кровь невинных?', NULL, NULL, 'Фиал крови невинных', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1067, 'Возвращение в Громовой Утес', 'Вот отрава. Если воспользоваться ей против Торговой Компании, результаты должны оказаться весьма благоприятными – возможно, удастся добиться даже распростанения новой заразы. Мне не терпится испытать свою работу в деле!$B$BВпрочем, прежде отнеси ее аптекарю Заме. Она должна придумать наиболее эффективный способ использования отравы.', 'Отнесите отраву Лидона аптекарю Заме в Громовой Утес.', 'Отрава от аптекаря Лидона? Замечательно. Если я знаю Лидона, она очень хорошо подействует на Торговую Компанию...', 'Ты вернулся, $N. Аптекарь Лидон пришел к нам на подмогу?', NULL, NULL, 'Отрава Лидона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1068, 'Механические измельчители', 'Есть связь между духовной магией шаманов и природной магией друидов. Именно поэтому мы, шаманы, можем слышать мольбы духов Каменного Когтя. Я могу разобрать не все, что они шепчут, однако одно послание - одно видение -было четким...$B$BВ этом видении я узрела на Утесе Ветрорезов, на северо-западе Долины Высокого леса, две человекоподобные машины, которые валили деревья с невероятной скоростью. Этих металлических тварей нужно остановить!$B$BВ явленном мне видении я заметила, что машины эти отмечены странными символами:$B$BXT:4 и XT:9.', 'Уничтожьте шреддеры XT:4 и XT:9, затем вернитесь к Сирит Камнелом на границу Когтистых гор и Степей.', 'Уничтожение машинXT:4 и XT:9 успокоило многих духов Каменного Когтя, $N. Будем надеяться, что после потери этих машин Торговая Компания покинет эти горы.$B$BИбо если этого не произойдет, то бедствия, постигшие эти земли, могут оказаться бледной тенью того, что ждет нас впереди.', 'Духи деревьев плачут по своим погибшим собратьям, $N. Тебе нужно уничтожить шреддеры XT:4 и XT:9, иначе, я боюсь, Каменный Коготь никогда не оправится от этого ужаса.', NULL, NULL, 'XT:4 убито', 'XT:9 убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1069, 'Яйца мохового паука', 'В Пиратской бухте фантастический спрос на омлеты из паучьих яиц! Проблема в том... что яиц в Бухте нет.$B$BЯ чую прибыль!$B$BНа Утесе Ветрорезов и в Сиширском каньоне, в Когтистых горах на северо-западе, живут моховые пауки. Принеси мне их яйца, и я неплохо заплачу!$B$BНа Утесе Ветрорезов паучьи кладки можно найти под оставшимися деревьями.$B$BВ Сиширском каньоне... хм, если у тебя слабый желудок, можешь собирать яйца только на Утесе Ветрорезов...', 'Принесите Мебоку Миззриксу из Кабестана 15 яиц мохового паука.', 'Ты принес мне яйца! Спасибо!$B$BЯ пошлю их Дыбоволосу, и он переправит мой товар в Пиратскую бухту!$B$BВот твоя доля, $N. Без тебя мне бы не справиться.', 'Принес яйца, $N? Я уже заключил договор о транспортировке с управляющим пристанью Головокружилкинсом.', NULL, NULL, 'Кокон мохового паука', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1070, 'На страже в Когтистых горах', 'Привет тебе, $N.$B$BСудя по виду, ты много путешествуешь. Тебе приходилось бывать в Когтистых горах? Эта земля опустошена Торговой Компанией и прочими врагами ночных эльфов. $B$BНедавно часовой Волкопас послала туда мою подругу Келу Копье Тени, чтобы она узнала, что происходит в тех землях, однако до сих пор от нее нет вестей. Я еще беспокоюсь и потому, что Альянс отправил вместе с ней гнома-мага... это, несомненно, повод для тревоги.$B$BМожет быть, ты найдешь ее и пошлешь весточку мне?', 'Найдите Келу Копье Тени, которая наблюдает за долиной, выходящей к Утесу Ветрорезов в Когтистых горах.', 'А, так ты здесь по просьбе Тары из Ясеневого леса... я так скучаю по ней, по моей родине, по друзьям. Должно быть, ей хорошо среди часовых, раз прочие дела передает путникам. Я горжусь за нее.$B$BРада познакомиться с тобой, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1071, 'Отсрочка для гнома', 'Понимаешь ли, $N, я состою в Просвещенной Ассамблее Чародейства, Алхимии и Технических Наук, и моя цель... нет, мой ДОЛГ! – показать ночным эльфам, что единение магии, реактивов и механизмов поможет спасти их леса.$B$BОднако это тяжелая война, а гоблины, похоже, плодятся, словно кролики. У меня даже нет времени воплотить в жизнь свои новые изобретения!$B$BМне нужно время для планирования и организации. Но для этого мне потребуется твоя помощь – сдерживать натиск гоблинов у Утеса Ветрорезов к востоку отсюда...', 'Убейте 10 лесорубов и 10 лесозаготовителей Торговой Компании и вернитесь к Гаксиму Ржавошиппи в Каменный Коготь.', 'Спасибо тебе за помощь, $N. Да и вернуться тебе удалось как раз вовремя.$B$BКажется, я выработал идеальный план... взрывчатка. Нет, это не сам план, это его часть.$B$BПонимаешь ли, я использую сильные взрывчатые вещества – не волнуйся, они далеко не так опасны, как считается – для того, чтобы припугнуть гоблинов. Я смогу как следует нагнать на них страху, разместив в ключевых местах на границах горной местности заряды, однако в ближайшие несколько дней мне может не хватить материалов...', 'Ну и как продвигаются дела, $N?', NULL, NULL, 'Лесоруб Торговой Компании убито', 'Лесозаготовитель Торговой Компании убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1072, 'Старый коллега', 'Устройство, о котором я думаю – моя самая продвинутая версия на сегодняшний день. Но мне нужно особое зелье, чтобы это устройство заработало. Я думаю, нам нужно добыть хороший состав, поскольку эта миссия может стать для тебя последней.$B$BА для этого нам нужно мощное взрывчатое вещество: нитромирглицероний.$B$BЕдинственный, кто может создать НГ-5, это мой старый приятель – Ломак Демонтирс. Поищи его в Городе Механиков.$B$BЕсли уговоришь его сделать для нас немного НГ-5, то я начну работать над размещением своих устройств.', 'Поговорите с Ломаком Демонтирсом в Стальгорне. ', 'А-а-а... Тебя послал Гаксим, вот как? А откуда мне знать, что ты не врешь? Ась? Ась?..', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1073, 'Неумение + реактивы = потеха!', 'Ха-ха-ха!.. Тебе нужен нитромирглицероний, чтобы остановить гоблинов, уничтожающих лес?!$B$BМне все равно, знаешь ты Гаксима или нет... я дам тебе этот состав, чтобы посмотреть, как кого-нибудь разнесет на мелкие кусочки: или тебя, или гоблинов.$B$BНо есть проблемка: у меня кончились химикалии.$B$BНо вот что я тебе скажу: принесешь мне нужные зелья, и я прямо сразу же смешаю для тебя составчик.$B$BПо крайней мере, ты докажешь, что кое-что понимаешь в алхимии, прежде, чем я передам тебе образец своего величайшего творения.', 'Принесите 4 крохотных флакона с зельем маны и 2 слабых эликсира стойкости Ломаку Демонтирсу в Стальгорн.', 'Вот это подойдет.$B$BНе знай я тебя, я бы сказал, что ты кое-что понимаешь в алхимии... Ладненько, ладненько... в мире есть не только мечи и колдовство, верно?', 'Я не могу сделать нитромирглицероний без этих зелий... они жизненно важны для его создания.', NULL, NULL, 'Крохотный флакон с зельем маны', 'Слабый эликсир стойкости', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1074, 'Неумение + реактивы = потеха!', 'Ну вот тебе, держи. Тока поосторожней... это летучая смесь.$B$BЕсли Гаксим тебе и вправду друг, передай ему от меня привет. А если нет – взлетишь на воздух, вот будет тебе потеха.', 'Отнесите нитромирглицероний Гаксиму Ржавошиппи в Каменный Коготь.', 'Дело сделано, и сделано отлично, $N.$B$BНГ-5 незаменимый компонент для поджига повозок с динамитом.$B$BЧто? Да, динамит... целыми повозками. Это идеальный отвлекающий маневр, я тебе скажу... подожди и увидишь.', 'А, славно, славно, с возвращением.', NULL, NULL, 'NG-5 (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1075, 'Свиток от Маурена', 'Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, еще не объяснил этого?$B$BНу так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошел почти без твоего участия. Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвется НГ-5.$B$BНо мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен. Ты сможешь отыскать его там в квартале магов. Он человек, так что будь $gвнимателен:внимательна:, не ошибись.', 'Найдите в Штормграде Коллина Маурена.', 'Да, вот то заклинание, которое тебе нужно – оно позволит производить взрывы на расстоянии... хмм.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1076, 'Демоны в Западном Крае', 'А, кажется, я понял. Заклинание послания... полагаю, именно этого эффекта он хочет добиться. $B$BМне нужно создать свиток с запечатленным на нем заклинанием. Для этого мне нужен прах Пыледемона.$B$BПока я собираю остальные компоненты, почему бы тебе не отправиться в Западный Край и не найти там одно из этих мерзких существ? Они опасны, но я уверен, что ты со всем справишься, если желаешь участвовать в одном из экспериментов Гаксима.$B$BКогда ты вернешься, я буду здесь.', 'Принесите прах Пыледемона Коллину Маурену в Штормград. ', 'Подожди несколько секунд, и нужный тебе свиток будет готов.', 'Привет, $N. Тебе удалось найти нужный мне компонент?', NULL, NULL, 'Прах пыледемона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1077, 'Особая посылка для Гаксима', 'Вот, $N. Это то, что нужно.$B$BКогда в следующий раз увидишь Гаксима, передай ему от меня привет. Хотелось бы мне узнать, как закончится эта история.$B$BВсего тебе хорошего.', 'Отнесите свиток с посланием Гаксиму Ржавошиппи в Каменный Коготь.', 'Великолепно, $N! Славная работа.$B$BЭто заклинание вместе с НГ-5 даст идеальную дистанционную взрывчатку.$B$BУ нас получится прекрасный отвлекающий маневр, и ты прокрадешься и сопрешь документы и инженерные планы Торговой компании.$B$BТогда они не смогут вырубать леса так быстро.', 'Хо-хо, ты уже обратно? У тебя оно есть? Заклинание, в смысле?', NULL, NULL, 'Свиток с посланием (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1078, 'Поиск для Маурена', 'Путешественники постоянно спрашивают меня о Когтистых горах. Похоже, все ищут там приключений, причем самых разных: кому-то нужны виверны, кому-то – элементали, а у кого-то дела с Торговой Компанией.$B$BВ Обугленной долине, прячущейся среди пиков Когтистых гор, некогда обитали особые виды василисков: их чешуя, размолотая в порошок, была прекрасным реактивом для некоторых заклинаний, созданных мною. $B$BЕсли эти василиски еще живут там, мне надо заполучить хотя бы несколько чешуек.$B$BЕсли не очень торопишься, удели на это немного времени, я хорошо заплачу тебе.', 'Принесите 8 кристаллических чешуй Коллину Маурену в Штормград.', 'Великолепно, $N. Спасибо тебе огромное.$B$BМожет быть, и я когда-нибудь смогу помочь тебе.', 'И еще раз привет тебе, $N.$B$BТебе удалось побывать в той долине в Каменном Когте и добыть чешую?', NULL, NULL, 'Кристаллические чешуи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1079, 'Секретная операция – Альфа', 'Так вот, $N, смотри и слушай внимательно. Все устройства доделаны и готовы к использованию.$B$BВозьми эти листы – здесь все объясняется про детонаторы, взрывчатку и про то, как их разместить.$B$BПомни, успех твоей миссии не зависит от того, сколько разрушений ты сможешь причинить. План \"Альфа\" увенчается успехом в том случае, если ты принесешь технические чертежи Торговой Компании, находящиеся на лесопилке к югу от Скалистого Озера.', 'Добудьте технические чертежи Торговой Компании с лесопилки на Утесе Ветрорезов.', 'Просто великолепно! Это сильный удар по Торговой компании.$B$BМы сможем узнать уязвимые места их машин, а также использовать их разработки для наших собственных целей. Поистине, это великий день.', 'Тебе удалось раздобыть чертежи, $N?', NULL, NULL, 'Чертежи механизмов Торговой Компании', 'Сума для тайных операций', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1080, 'Секретная операция – Бета', 'План Бета – почти то же, что и план Альфа. $N.$B$BМы проводим отвлекающий маневр, а потом похищаем их драгоценные письма.$B$BГлавное – получить письма... помни это.$B$BНа листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами...', 'Добудьте документы Торговой Компании из Рудника Ветрорезов у восточного края Утеса Ветрорезов.', 'Великолепно, $N! Каэла и часовые будут счастливы. При твоих умениях да моих творениях нас никто и ничто не остановит!', 'Ну и как дела, $N?', NULL, NULL, 'Письма Торговой Компании', 'Сума для тайных операций', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1081, 'Приглашение от Тиранды', '$N, я уверена, что Тиранда Шелест Ветра лично хотела бы поблагодарить тебя за участие в этой миссии.$B$BМожет быть, это и незаметно с первого взгляда, но деяния, совершенные с твоей помощью, способны помочь нам закрепиться в Когтистых горах.$B$BЕсли хочешь и далее помогать нам в борьбе, отправляйся на встречу с Тирандой в храм Луны в Дарнасе.', 'Найдите в Дарнасе Тиранду Шелест Ветра.', 'Приветствую тебя, $N. Мне доводилось и прежде слышать твое имя, и я рада видеть, что, не взирая на твою молодость, ты уже избрал свой путь.$B$BТы окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1082, 'Новости для часового Тенисил', '$N, твоя помощь здесь оказалась поистине бесценной.$B$BЧасовые Ясеневого леса вознаградят тебя, если ты уведомишь их, что я и Гаксим живы. Скажи им, что мы трудимся над тем, чтобы остановить Торговую Компанию и исцелить эти земли.$B$BНайди в Астранааре Тару Тенисил, она обрадуется твоему возвращению и хорошим новостям.', 'Вернитесь к часовому Тенисил в Ясеневый лес.', 'Благодарю тебя, $N. Ты сослужил Стражам хорошую службу.$B$BЯ рада узнать, что Каэла... и даже Гаксим живы и здоровы.$B$BТы заслуживаешь нашего уважения.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1083, 'Разъяренные духи', 'Не могу сказать точно, что Торговая компания сделала с долиной, однако ясно, что обитающие там существа взяли над ними верх.$B$BПредставители Торговой компании подожгли лес, они использовали свои убийственные изобретения для того, чтобы как можно сильнее опустошить долину.$B$BНо в невежестве своем они также освободили нечто иное: пылающих духов, элементалей огня, камня и ярости.$B$BИ этой земле никогда не узреть улыбку Элуны, пока эти существа бродят на свободе.$B$BПринеси мне их дымящиеся угли, дабы доказать, что тебе удалось сократить число разъяренных духов.', 'Принесите 8 тлеющих углей от любых элементалей огня из Обугленной долины Келе Копье Тени в Когтистые горы.', 'Останки нашего врага... твоя сила сослужила нам добрую службу, $N. Благодарю тебя.', 'При первом взгляде на Горелую Долину на глаза мне навернулись слезы, $N.', NULL, NULL, 'Тлеющие угли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1084, 'Раны Дерев', 'Мне кажется очевидным, что защитники долины – древни – вели какие-то дела с Торговой компанией, прежде чем их оттеснили прочь. К несчастью, даже эти некогда великие охранители ныне впали в нечестие.$B$BГаксим полагает, что их падение каким-то образом связано с оружием, которое гоблины использовали во время отступления.$B$BЯ сказала ему, что возьму образец из тела раненого древня и отдам на изучение, чтобы понять, правда ли это.$B$BПринеси мне немного шрапнели, чтобы гном мог дать мне ответ...', 'Принесите образец ржавой шрапнели Келе Копье Тени в Каменный Коготь.', 'Спасибо, $N.$B$BЭтого должно быть более чем достаточно, чтобы Гаксим выяснил, каким образом скверна пала на древней. Я немедленно передам ему этот образец.', 'По-моему, Гаксим найдет шрапнели применение вне зависимости от того, как Торговая компания использовала ее в прошлом.', NULL, NULL, 'Ржавая шрапнель', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1085, 'На страже в Когтистых горах', 'Положение здесь, в Каменном Когте, явно не способствует совместной работе ночного эльфа и гнома.$B$BТорговая Компания опустошила эти земли, и большая часть моего времени уходит на то, чтобы положить предел уничтожению.$B$BНе суди Гаксима преждевременно; он понимает, что нам с ним необходимо трудиться вместе.$B$BЕсли ты хочешь помочь нам, то для начала поговори с Гаксимом.$B$BИзвини, что пока не могу отослать тебя обратно к Таре с хорошими новостямиI. Может быть, вскоре...', 'Поговорите с Гаксимом в Когтистых горах. ', 'Предательская... предательская и опасная, вот какова эта земля.$B$BНо я тут для того, чтобы показать ночным эльфам, что ежели призвать на помощь старое доброе инженерное дело и чуточку магии, то так будет вернее.$B$BВидишь ли, если убрать магию совсем, то ночным эльфам это никак не поможет – они без нее не могут. И мир без нее не может. А вот если подкрепить магию инженерным делом да алхимией, то так оно будет правильнее. Возможностей просто масса.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1086, 'Аэропорт ветролетов', 'Отрава готова. Остается только ее доставить адресату. И это придется сделать тебе, $N.$B$BУ Торговой Компании есть средства доставки сообщений и легкого груза от штаб-квартиры до Когтистых гор. Скорее всего, это маленький аэропорт, подходящий не для дирижабля, а для ветролета. Обыщи все области Когтистых гор, находящиеся под контролем Торговой Компании, и найди этот аэропорт, если он существует. Как найдешь, помести туда отраву.$B$BПоложишь – беги оттуда.', 'Отнесите распылитель ядовитого тумана в аэропорт Торговой Компании и вернуться к аптекарю Заме.', 'Ты нашел аэропорт? Молодец, $N! Отличный сюрприз ждал гобинов! Будем надеяться, что яд доберется до их штаб-квартиры.$B$BТы оказал своему народу неоценимую услугу, и пусть тебя не мучает совесть из-за отравления Торговой Компании. Они еще не того заслуживают.$B$BИ вот какой мудрости союзникам Отрекшихся стоит поучиться:$B$BНе бойся темных дорог... если они ведут к победе.', NULL, NULL, NULL, 'Установите распылитель ядовитого тумана.', 'Распылитель ядовитого тумана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1087, 'Наследие Кенария', 'Ты и представить себе не можешь, как я ненавижу эти омерзительные земли! Отродья Кенария и кальдорайские друиды, обитающие на этом пике, используют свою жалкую силу, чтобы подавить поток магии, даже так далеко на юг от их гнусного обиталища... их драгоценных лесов.$B$BЯ так хочу вернуться в Джеденар и купаться в потоках магии, но мой господин не позволяет мне вернуться, пока моя работа здесь не будет завершена.$B$BНе сомневаюсь, что ты любишь ночных эльфов и их союзников не больше, чем я. Помоги мне, и мы оба внакладе не останемся.', 'Убейте 4 сыновей Кенария, 4 дочерей Кенария и 4 кенарийских ботаников по поручению Брайлин Огненной Длани из Приюта у Солнечного Камня.', 'Я уже это чувствую... да... прекрасная мощь... струящийся поток. Как же глупы кальдораи, что отвергают дары этого мира, не дают магии свободно, словно песня, струиться по жилам.$B$BКак же скучна и бесцветна жизнь без этого огненного потока!', NULL, NULL, NULL, 'Сын Кенария убито', 'Дочь Кенария убито', 'Кенарийский ботаник убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1088, 'Ордан', 'Они думали, что могут остановить течение магии. Но они ошиблись. Они думали, что смогут спрятать Ордана – но я заполучу его голову!$B$BМагия дает мне способность видеть истину. Да... вот он где. Скрещение путей... На вершине великого древа в Ясеневом лесу. Название... Приют в Ночных Лесах. Один из старших сыновей лесного бога. Они унесли его прочь с этого пика прежде, чем я смогла найти его, однако его время на исходе.$B$BПринеси мне его голову, и я поделюсь с тобой могуществом.', 'Принесите голову Ордана Брайлин Огненной Длани к Приюту у Солнечного Камня.', 'Некогда, давным-давно, я знала Хорданиуса. Он был горд, как и все его сородичи, и ставил себя даже над высокорожденными.$B$BОднако теперь ему трудно так же высоко держать голову, не так ли, $N?$B$BЯ обещала тебе награду, и ты ее получишь. Слушай меня!', 'Когда мой повелитель отправил меня на Пик Каменного Когтя, мне казалось, что нужно будет лишь погубить ночных эльфов, которые ползают по руинам нашего древнего храма Азшары, оскверняя святость этого места... но Хорданиус ускользнул от меня.', NULL, NULL, 'Голова Ордана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1089, 'Логово', 'На Пике Каменного Когтя друиды построили Логово Когтя, где хранят множество могущественных предметов.$B$BОни продумали сложный план, чтобы не дать этим предметам попасть в чужие руки.$B$BК счастью, мне удалось... вытянуть некоторые подробности из одного из них.$B$BВ маленьком светильнике у входа в логово ты найдешь спрятанный там ключ Хранителя Врат – с его помощью ты сможешь открыть тайники, расположенные вокруг логова. А предметы из этих тайников помогут тебе открыть сокровищницу, размещенную в одном из центральных помещений.', 'Отправляйтесь к пещере на Пике Каменного Когтя. При помощи Ключа Хранителя Врат добудьте предметы, спрятанные друидами. Используйте эти предметы для того, чтобы открыть сокровищницу Логова Когтя.', 'Когда три ключа вошли каждый в свое отверстие, посреди мерцающего сияния появились несколько предметов.', 'Три замочных скважины вырезаны в камне.', NULL, NULL, 'Ключ Спящих', 'Ключ-коготь', 'Могильный ключ', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1090, 'Приказы Геренцо', 'Знаешь, когда-то я был второй по важности персоной во всем этом деле. Все изменилось, когда главным стал Геренцо. Уволил моего начальника Зиза Физзикса, а меня послал работать в копях. Но Зиз велел мне оставаться здесь и собирать сведения. Его новое начальство хорошо заплатит нам, если мы узнаем, что планирует Геренцо.$B$BВ любом случае, я точно знаю, что Геренцо приказал добыть как можно больше этой золотисто-зеленой руды. Я могу раздобыть образец, а ты передашь его Зизу. Но пока я этим занимаюсь, следи, не покажется ли стража.', 'Возьмите образец загадочной руды у Пузника после того, как он ее добудет.', 'Спасибо, $N. Тут выдалось несколько опасных моментов, да и мы, наверное, были не слишком-то внимательны.$B$BНо важно то, что у нас теперь есть образец руды, и мы должны как можно скорее доставить его Зизу.', NULL, NULL, NULL, 'Охраняйте Пузника, пока он добывает таинственную руду', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1091, 'Новости для Каэлы', '$N,отнеси эти письма Каэле. Уверен, что она захочет это узнать. По крайней мере, часовые точно захотят.$B$BИ обязательно расскажи ей о наших успехах и о том, что мы не добились бы ничего без чуточки магии.', 'Отнесите документы Торговой Компании Келе Копье Тени в Когтистые горы.', 'Это действительно интересно, $N.$B$BВы с Гаксимом все сделали правильно. Благодарю.', 'Да, $N? Какое у тебя ко мне дело?', NULL, NULL, 'Письма Торговой Компании (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1092, 'Приказы Геренцо', 'Полагаю, мне тоже нужно убираться отсюда. Не пройдет много времени, как слухи о том, что произошло здесь, распространятся достаточно высоко, и вряд ли меня в следующий раз встретят там с добром да лаской.$B$BМне нужно выбраться наружу и встретиться с Зизом. Надеюсь, он мне подыщет новую работенку!!!$B$BЯ попытаюсь тут слегка подчистить за собой, но тебе придется доставить образец руды Зизу немедля. Он говорил мне, что разбил свой лагерь где-то за западном склоне Утеса Ветрорезов. Удачи!', 'Доставьте Неопознанную Руду Зизу Физзиксу в Когтистые горы.', 'А, я так и знал, что правильно сделал, когда сказал Пузнику остаться. Я уверен, что инженеры в Нижней шахте захотят на это взглянуть.$B$BКонечно, я собираюсь прихранить кусочек для себя, но если они чего-то не узнают, то это им и не повредит, верно?', 'Что это? Я могу помочь тебе?', NULL, NULL, 'Неопознанная руда (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1093, 'Супер-дровосек 6000', 'Ну, Торговая Компания и наломала дров! О чем они только думали? Гоблинская компания нанимает гнома!$B$BК счастью для меня, Пароклапан всегда может узнать гения с первого взгляда. Он нанял меня сразу же, как меня выгнали оттуда!$B$BМне сказали, что компания строит какие-то огромные лесорубные машины, и Клапан хочет, чтобы я украл для него чертежи. К несчастью, Геренцо – вот ведь злобный гном! – хочет меня убить... может быть, ты вместо меня украдешь чертежи? Они должны быть у кого-то из операторов компании.', 'Добудьте чертежи \"Супер-дровосека 6000\" для Зиза Физзикса с Когтистых гор.', 'Эй, это то, что я думаю? Отлично!$B$BНу-с, посмотрим... и как мне понимать эту ерунду?.. и чем только думают эти гномы? Удивительно, что они хотя бы колесо сумели соорудить, не говоря уж об этих их обожаемых ветролетах.', 'Тебе удалось добыть чертежи? Я хочу порадовать нового начальника. Надеюсь, как только он убедится в моей верности – ну, насколько его вообще можно убедить... гоблинский гонор, и все такое... – он найдет достойное применение моему гениальному уму.', NULL, NULL, 'Чертежи \"Супер-дровосек 6000\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1094, 'Дальнейшие указания', 'В этом конверте – все сведения, которые я смог собрать до того, как меня выпнули за дверь... Внутренние документы Торговой Компании, кое-какие руководства, технические бумажки... О, и, конечно, чертежи \"Супер-потрошителя 6000\".$B$BПаровой Клапан обосновался в Кабестане в Степях. Тебе не доставит труда разыскать его, это такой мелкий зеленый тип.', 'Доставьте запечатанный конверт Пароклапану в Кабестан, что в Степях.', 'Физзик, да? Не то, чтоб я ему верил, но, кажется, это правильные сведения. Что б я ни отдал, лишь бы Торговая Компания убралась подальше!$B$BХотя они притащили с собой кое-какие хорошие машины... не буду отрицать, что от их изобретений есть польза, когда эти изобретения применяем мы, а не кто-то другой...', 'Эй, привет! Чем могу быть полезен?', NULL, NULL, 'Запечатанный конверт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1095, 'Дальнейшие указания', 'В Нижней шахте было много разговоров про этого гнома, нанятого Торговой Компанией. Торговые олигархи не одобряют, что Раздунк связался с Геренцо.$B$BРидлвокс велел мне позаботиться об этой проблеме, и я не сомневаюсь, что это указание от одного из олигархов. Разумеется, директор мне об этом не говорил. Скажем так, у меня такое подозрение.$B$BКак бы то ни было, Геренцо необходимо устранить, и Физзику придется хорошо поработать.', 'Отнесите Зизу Физзиксу в Когтистых горах новые приказы.', 'Убрать Геренцо? Я только за!$B$BГномы вообще неприятный народ, но, судя по всему, этот Геренцо хуже других. Он был одним из главных инженеров Гномрегана и работал над тайным проектом – каким именно, нам так и не удалось узнать, хоть мы и пытались пробраться в Дун Морог. В докладах говорилось, что этот тайный проект буквально взорвался им в лицо.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1096, 'Геренцо Терминатрикс', 'Один раз я встречал Геренцо и, скажу тебе, видок у него отвратнее некуда. Такое впечатление, что его плоть гниет и отпадает, части его тела заменены металлическими деталями и механизмами.$B$BК северо-востоку отсюда, высоко над Скалистым озером, вблизи водяного колеса находится пункт, откуда Геренцо наблюдает за всей местностью. Я не смог бы найти дорогу наверх, не говоря уж о том, чтобы справиться с Геренцо... Но тебе, кажется, это вполне под силу.$B$BЕсли ты убьешь его по моей просьбе, то получишь щедрое вознаграждение!', 'Принесите механическую руку Геренцо Терминатрикса Зиззу Физзиксу в Когтистые горы.', 'Взгляни на эту штуковину... только гном мог с такой управляться. Не понимаю только, зачем отрезать руку и заменять ее этой штукой, если можно просто сохранить обе руки и приделать третью!$B$BГномы, я тебе скажу...$B$BГеренцо, по крайней мере, если и не мертв, то неисправен. Надеюсь, этого доказательства будет достаточно, и Пароклапан даст мне назначение в одну из мастерских Союза ремонтников в Прибамбасске или, может быть, даже в Нижней шахте.', 'Паровой Клапан потребует какое-нибудь доказательство того, что Геренцо мертв. Полагаю, его механическая рука вполне сгодится.', NULL, NULL, 'Механическая рука Геренцо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1097, 'Просьба Элмора', 'Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза. Думаю, он хочет отправить посылку домой, на север.$B$BТы мне кажешься $gопытным путешественником:опытной путешественницей:... Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами.$B$BГриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов. Это в северо-восточной части города.', 'Поговорите с Гримандом Элмором в Штормграде. ', 'Ты поможешь мне с доставкой? Замечательно!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1098, 'Пропавшие стражи смерти', 'Готовясь к нападению на крепость Темного Клыка, мы отправили на разведку двух стражей смерти. Они не возвращаются вот уже много дней, но без их отчета нам не организовать успешного нападения!$B$BИтак, вот твое задание, $N. Отправляйся в крепость Темного Клыка на юге и найди стражей смерти Адаманта и Винсента. Найди их и помоги им, если сможешь.$B$BЭто очень опасное и важное задание, $N. Не подведи нас.', 'Найдите стражей смерти Адаманта и Винсента.', 'Перед вами лежит израненное тело Винсента.$B$BСтраж смерти Адамант написал отчет Хадреку... Но что бы ни хотел добавить к его словам Винсент, он унес это с собой в могилу.$B$BВ мертвой руке зажата небольшая безделушка...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1099, 'Гоблины победили!', '', '', '', NULL, NULL, NULL, 'Билет на бега для гоблинов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1100, 'Дневник Хмурня', 'Вы медленно открываете потрепанный дневник Хенрига Хмурня...', 'Прочитайте дневник Хенрига Хмурня. ', 'Говорите, что нашли этот дневник у мертвого дворфа? Дайте мне на минутку, хочу взглянуть...', 'Вас что-то беспокоит... Случилась какая-то неприятность?', NULL, NULL, 'Дневник Хмурня (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1101, 'Хозяйка Лабиринтов', 'Бедный Гералат! И этот дворф... Хмурень. Каким он был храбрецом!$B$BНельзя, чтобы их усилия пропали даром. Эта карга... Чарлга Остробок... нужно ее убить.$B$BРазумеется, поход в лабиринты Иглошкурых будет опасным, а за помощью в Дарнас посылать некогда. Так что тебе, $N, придется собрать отряд самостоятельно.$B$BПринеси мне медальон Чарлги Остробок в доказательство ее смерти.', 'Принесите медальон Чарлги Остробок Фалфиндеру Хранителю Путей в Таланааре.', 'Наконец-то старая карга умерла. Это отличная новость, $N!$B$BВ наше опасное время всегда приятно встретить такого храбреца, как ты.$B$BТеперь, когда прислужники Остробок мертвы, мы сможем продолжить наши исследования той области. Возможно, теперь мы сможем узнать, почему место упокоения Агамаггана подверглось такому осквернению.$B$BОднако, боюсь, здесь не обошлось без предательства...', 'Пока Чарлга Остробок собирает свои силы в Лабиринтах Иглошкурых, эти земли будут в огромной опасности.', NULL, NULL, 'Медальон Чарлги Остробок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1102, 'Отмщение грядет!', 'Кэрн – благородный вождь, объединивший наш народ здесь, в Громовом Утесе.$B$BНо я не могу так легко простить тех, кто изгнал нас с земель наших предков. Мой народ много десят$Nий прожил в южных Степях. Те края для нас священны. Но нас изгнали многочисленные враги.$B$BМесть ждет старую ведьму Чарлгу Острый Бок, которая повелевает нечестивым воинством в Лабиринтах Иглошкурых.$B$BПринеси мне сердце этой ведьмы, $N, и я смогу спокойно умереть.', 'Принесите сердце Чарлги Остробок Ольду Каменному Копью в Громовой Утес.', 'Теперь мерзкое племя Иглошкурых на себе испытает страдания моего народа! Пусть это будет им уроком.$B$BИзгнание целого народа из священной земли – этот грех заслуживает самой жестокой кары!$B$BБлагодарю тебя, $N, за то, что откликнулся на мою просьбу.', 'Как только я узнаю, что грязные твари Лабиринтов Иглошкурых изгнаны из их мерзкого логова, я упокоюсь с миром, зная, что месть свершилась.$B$BТы изгнал этих игрогривов из Лабиринтов? И подтвердишь свою весть, показав мне сердце этой ведьмы?', NULL, NULL, 'Сердце Чарлги Остробок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1103, 'Зов воды', 'Привет, $gбратан:сеструха:! Ты тута, чтобы очистить воду и доказать Ислен, что не лыком $gшит:шита:?$B$BЯ тока что прикончил оскверненного духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню.$B$BА эт што? А-а-а. Тьев понимает, бывает непруха. Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух.$B$BПринеси мне сапту воды от Ислен, покажи, что $gготов:готова: к новому заходу, а я уж приготовлю тебе, че нужно.', 'Принесите Тьеву Мордуну, который находится в Серебряном бору, сапту воды, если вам не удалось поговорить с низшим воплощением воды.', 'А-а-а, ты, типа, готов…;$B$BТогда я сую эти шмотки в жаровню, а ты уж побалакай с духом.$B$BИ не парься, увидишь ты свой призрачный мир с этой саптой... Старый Тьев не дурак, знает, как работает колдунство сапты.$B$BДавай, двигаем в святилище, побалакаем в духами вместе, братан.', 'Притащил сапту, братан? $B$BЯ видел еще одного типа, который обломался, победив оскверненного духа воды: он типа слишком долго тянул и слишком быстро, на его вкус, вывалился из призрачного мира. Не хочу, чтобы это еще с кем случилось. Подожду-ка я тута, вдруг кому нужно помочь будет.', NULL, NULL, 'Сапта воды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1104, 'Яд Соляных равнин', 'Я нарисовал уже столько чертежей нового болида! И все их надо непременно воплотить в реальность!!!$B$BЯ разрабатываю новое топливо, которое будет гореть жарко-прежарко! Пока что у меня не получается, но, кажется, я знаю, что мне может помочь...$B$BУ скорпидов с Мерцающей равнины совершенно особый яд, в нем чрезвычайно много солей. Он уникален! Как раз он-то мне и нужен.$B$BПринеси мне их яда и поверь: тогда наши болиды просто взлетят!', 'Принесите 6 порций соленого яда скорпида Пшиксу Медноштифу на Мерцающую равнину.', 'Отлично! Этот яд как раз подойдет! Спасибо, $N!$B$BТеперь надо его вскипятить, добавить скиппер-отомер и нега-катализатор и... Черт! Где мои записи?!', 'Привет-привет! Ну, где же яд?', NULL, NULL, 'Соленый яд скорпида', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1105, 'Крепкие панцири', 'Мой брат составляет новое топливо для болида. Он в этом деле просто гений! Правда, боюсь, его новое гениальное топливо разъест всю машину...$B$BПоэтому я хочу укрепить топливные баки.$B$BЗдесь, на равнинах, живут черепахи с очень прочными панцирями. Из них-то я и хочу сделать это покрытие – оно должно выдержать топливо моего брата.$B$BНу как, не желаешь ли взяться за эту работу и принести мне несколько панцирей?', 'Принесите 9 крепких черепашьих панцирей Виззлу Медноштифу на Мерцающую равнину.', 'Панцири! Спасибо, $N!$B$BОго, да они еще тверже, чем я думал! Вот примусь с ними работать – так, поди, целый ящик инструментов погну!', 'Мой брат разрабатывает новое топливо, и это меня немного беспокоит... Мне нужно как можно быстрее сделать новый топливный бак!$B$B$N, тебе удалось добыть черепашьи панцири?', NULL, NULL, 'Крепкий панцирь черепахи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1106, 'Мартек Изгой', 'Я разрабатываю новый двигатель, с которым мой болид помчится быстрее ветра! Помчится так, что даже сможет взлететь! Осталось мне сделать поршни, которые выдержат очень, очень высокое давление. Все мои испытания провалились потому, что я не смог сделать достаточно крепких поршней!$B$BНо есть тот, кто может мне помочь.$B$BЕго зовут Мартек Изгой. Он отличный кузнец и знает о металлах больше других. Вот, отвези ему это письмо, я знаю, он поможет мне!$B$BПравда, живет он далеко – в Азероте, в Бесплодных землях, в  одном лагере с гоблином!$B$BНайди его!', 'Отнесите письмо Пшикса Мартеку Изгою в Бесплодные земли.', 'Тебя прислал Пшикс? Это все меняет! Разумеется, я помогу тебе. Пшикс и его брат – одни из немногих, кто не желает мне смерти.$B$BЗначит, Пшикс хочет сделать поршни, да? Да такие сильные, чтобы выдержали все, что он задумал, а зная Пшикса, могу точно сказать, что его новый болид – это вулкан на колесах!', 'Что ж, вы нашли меня. Поздравляю.$B$BВы насчет топора, который я сделал для Гат\'Илзогга? Или пришли защитить честь герцогини Пемей?$B$BА хотя какая разница... Если вы пришли драться со мной, то давайте скорее с этим покончим.', NULL, NULL, 'Письмо Пшикса Медноштифа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1107, 'Средство против трения', 'Наш болид – это самая быстрая машина на равнинах! Она такая быстрая, что... я боюсь, что от трения ее разнесет на куски.$B$BЧтобы этого не произошло, мне нужен материал для покрытия движущихся частей машины. Он должен быть твердым, но не хрупким, и выдерживать соляную коррозию, иначе на Мерцающей равнине он долго не протянет.$B$BСлышали когда-нибудь про Коварный риф, $N? Это у побережья Тернистой долины. Там обитает племя мурлоков под названием Соляная Чешуя, и их хвостовые плавники как нельзя лучше подойдут для моего материала.', 'Принесите 10 соленых хвостовых плавников Виззлу Медноштифту на Мерцающую равнину.', 'Спасибо, $N! Осталось размолоть их, добавить кое-какие ингредиенты, и все будет готово. Тогда, по крайней мере, болид не пострадает от своей собственной скорости.$B$BЕще бы он от какого-нибудь препятствия не пострадал...', 'Эй, где там мои плавники? Если не защитить машину от ее же собственной скорости, долго она тут не протянет!', NULL, NULL, 'Соленый хвостовой плавник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1108, 'Индарилий', 'Я здесь не только потому, что хочу держаться ото всех подальше. В Бесплодных землях очень много металла, $N, но добыть его сумеет не всякий.$B$BЭтот металл называется индарилий, и говорят, что он обладает удивительной сопротивляемостью к температуре и механическим воздействиям. Как раз то, что нужно Пшиксу для его машины.$B$BНо я должен все проверить. Принесите мне немного индарилия, а я исследую его свойства.$B$BНастоящая индарилиевая руда залегает глубоко в шахтах Ульдамана, но трогги из племени Каменного Свода иногда тоже носят с собой обломки индарилия. Принесите их мне.', 'Принесите 10 пластин индарилия Мартеку Изгою в Бесплодные земли.', 'Да, то, что нужно. Положу их в горн и посмотрю, что будет.', 'Ну как, $N, удалось добыть немного индарилия? Я тут уже свой горн раскочегарил, можно начинать плавить.', NULL, NULL, 'Индарилиевая пластина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1109, 'Груды гуано', 'Как видишь, $N, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты.$B$BПоскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами. Работы полно, а времени в обрез!$B$BХоть ты и $C, но, судя по всему, немало $gстранствовал:странствовала:. Не поможешь мне?$B$BНам очень нужно редкое вещество. Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых. Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу...', 'Принесите 1 кучку гуано летучей мыши Лабиринтов мастеру-аптекарю Фаранеллу в Подгород.', 'Превосходно! Этого нам и не хватало, $N.', 'Вижу, ты вернулся. Удалось добыть гуано летучих мышей?', NULL, NULL, 'Гуано летучей мыши Лабиринтов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1110, 'Обломки болидов', 'Хе-хе, да тут такие гонки бывают, как же без происшествий! Вы только оглянитесь – все Мерцающие равнины просто усыпаны обломками разбитых болидов.$B$BИ за все эти детали гномы и гоблины могут хорошенько заплатить. Они вечно ищут, какую бы еще рухлядь привинтить на свои тачки.$B$BСтупайте и принесите мне побольше деталей, а я вам хорошенько заплачу.', 'Принестие 30 деталей болида Кравелу Углебороду на Мерцающую равнину.', 'Ого, вы только посмотрите! Кое-что хорошее в этой горе металлолома еще есть. Наверняка я смогу продать это за кругленькую сумму.$B$BА... это что, оторванное ухо? Ой! Не хотел бы я быть на месте того пилота.$B$BСпасибо, $N. Вот ваша плата. И еще бесплатный совет...$B$BДелайте вид, что вы круче всех – и тогда вам всегда удастся нагреть руки на чужой беде.', '$N, вы уже были на равнинах? Нашли какие-нибудь детали, которые я просил?', NULL, NULL, 'Обломки болидов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1111, 'Управляющий пристанью Головокружилкинс', 'Моя работа – выполнять запросы покупателей, а гномы заказали у меня набор деталей. Эти детали еще неделю назад прибыли в Кабестан, но я все никак туда не выберусь.$B$BМожет, ты туда смотаешься? Вот, надо будет найти управляющего пристанью Головокружилкинcа и отдать ему этот заказ.$B$BЕсли выполнишь мое поручение, я смогу доверить тебе и другие поручения.$B$BРазумеется, твой труд будет достойно вознагражден.', 'Отнесите заказ на детали Крейвела управляющему пристанью Головокружилкинcу в Кабестан, что в Степях.', 'Ах, да! Детали для Крейвела. Хорошо, что за ними пришли! Этот хлам валяется тут уже давно, я даже начал бояться, что он проржавеет!', 'Следующий! Так, ты отправитель или получатель?', NULL, NULL, 'Заказ на детали Крейвела (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1112, 'Детали для Крейвела', 'Вот посылка для Крейвела, $N. И когда отнесете, скажите ему... что если ему нужны еще особые заказы, то придется заплатить по всем счетам!', 'Отнесите Кравелу Углебороду его детали на Мерцающую равнину, что в Тысяче Игл.', 'Ура, детали! Надо отнести их гномам. Но сначала...$B$BВынем оттуда кое-что...', 'Вы уже забрали части из Кабестана?', NULL, NULL, 'Детали Крейвела (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1113, 'Сердца Доблести', 'Зачем мне редкий вид гуано, спросишь ты. Отвечаю. Я хочу выяснить в ходе эксперимента, какое воздействие окажут друг на друга два диаметрально противоположных химических вещества, особенно если оба смешать с токсичным реагентом, чтобы результаты были... погаже.$B$BВ северо-восточной части Тирисфальских лесов располагается монастырь Алого ордена. В его стенах и за их пределами живут ненормальные последователи Алого ордена. Кого из них ты убьешь, меня не волнует, у всех могут быть нужные мне сердца.', 'Мастер-аптекарь Фаранелл из Подгорода просит принести ему 20 сердец Доблести.', 'Сколько же на тебе кровищи, $N! Я вижу, ты неплохо потрудился!', 'Ты уже вернулся из Монастыря Алого ордена? Для этого восхитительного эксперимента мне понадобится много сердец!$B$BНе сомневаюсь, Вариматрас и Темная Госпожа будут рады, избавившись от алого сброда.', NULL, NULL, 'Сердце доблести', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1114, 'Заказ гномов', 'Ну вот, у меня есть все, что нужно. Осталось только отнести эти детали Пшиксу Медноштифу. Он уже давно их ждет – полагаю, он даже не заметит отсутствие одной маленькой детальки. Не стоит даже упоминать, что я ее забрал.$B$BЭта деталька совсем маленькая и ненужная.$B$BПравда-правда.', 'Отнесите хрупкие детали машины Пшиксу Медноштифу на Мерцающую равнину.', 'Вот они! Мои гидромеханизмы и усилительные болты! То, что нужно. Большое спасибо!', 'Принес мне что-нибудь? Здорово! Ну-ка, посмотрим...', NULL, NULL, 'Хрупкие детали машины (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1115, 'Сплетник', 'Ну вот, гномам услугу оказали, пора и гоблинам помочь!$B$BГоворят, что гоблинского пилота, Назза Парового Котла, раньше звали не так. Интересно, почему он сменил имя? Наверное, это секрет, и, скорее всего, он дорожит этим секретом.$B$BЕсли кто и знает правду, то только Кразек из Пиратской Бухты, на южном мысу Тернистой долины. Поговорите с Кразеком и разузнайте у него про нашего пилота-гоблина.$B$BЕсли вам удастся добыть у него ценную информацию, то мы все сможем извлечь из нее прибыль.', 'Поговорите с Кразеком в Пиратской Бухте, что в Тернистой долине. ', 'Хотите узнать про Назза Парового Котла? Вроде это гонщик с Мерцающей равнины?$B$BДа, я могу кое-что разузнать про него, но это будет нелегко. И не сразу.$B$BИ не за бесплатно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1116, 'Сонная пыль в болоте', 'Вытащить информацию из Назза – дело непростое, $N. Очень непростое. Но, раз уж вы ради этого приехали аж с Мерцающей равнины, то... не хотите ли попутешествовать еще немного?$B$BСобрали бы для меня кое-что, пока я буду связываться со своими источниками, а?$B$BХм... Что бы вам такое поручить? А, вот: сонная пыль с дракончиков из Болота Печали. Да, сонная пыль – это именно то, что мне нужно.$B$BПринесите мне ее, $N, а я взамен поделюсь с вами необходимой информацией.', 'Принесите 10 щепоток сонной пыли Кразеку в Пиратскую Бухту. Сонную пыль можно собрать с дракончиков на Болоте Печали.', 'Вот это да! Вы нашли сонную пыль!$B$BНу, и как там, на болотах? Говорят, горячей еды днем с огнем не сыщешь!', 'Уже вернулись? И сонная пыль у вас есть?', NULL, NULL, 'Щепотка сонной пыли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1117, 'Сплетни для Крейвела', 'Мне пришлось кое-кому оказать услугу, кое-кому подарить бутылку редкого эльфийского вина, а кое-что даже разузнать самостоятельно! Однако я добыл вам всю необходимую информацию.$B$BВот, я написал тут несколько интересных фактов касательно Назза Парового Молота. Делайте с ними что хотите, а для меня эта информация слишком опасна.$B$BИ не говорите никому, откуда вы ее достали!', 'Отнесите письмо с гоблинскими сплетнями Кравелу Углебороду на Мерцающую равнину, что в Тысяче Игл.', 'Так-так! Интересно... Очень интересно. Хех, возможно, мне придется поздороваться с гоблинским пилотом при следующей встрече.$B$BЭта информация многого стоит, $N. Думаю, Назз согласится раскошелиться за то, чтобы его секрет не стал достоянием общественности.', 'Нашли что-нибудь на Назза Парового Молота? Есть у него какой-нибудь секрет?', NULL, NULL, 'Гоблинские сплетни (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1118, 'Назад в Пиратскую Бухту', '$N, ты – $gхороший:хорошая:c: $C, ты сможешь выполнить это задание и не болтать о нем налево-направо.$B$BЯ разрабатываю новый план. Он довольно рискованный, но если все получится, то мы озолотимся! А ты как раз отлично сможешь мне помочь.$B$BДля начала тебе надо вернуться в Пиратскую Бухту. Прости, $gдорогой:дорогая: $N. Я знаю, что ты уже $gбыл:была: там по моему поручению, но в этот раз тебе надо будет поговорить с Шиззи Пуззыриксом.$B$BОтдай ему это письмо, а если он попросит помочь, то не откажи ему. Поверь, оно того стоит.', 'Отнесите план Крейвела Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.', 'Понятно. Крейвел придумал очень хитрую схему. Он очень умен – в этом ему не откажешь.$B$BЗначит, вам нужно что-то для поднятия духа, так? Что-то сильнодействующее...$B$BДумаю, можно использовать смеси, которыми Занзил кормит своих зомби...', 'Здрасьте-здрасьте. Что такой благородный $C делает в Пиратской бухте?', NULL, NULL, 'План Крейвела (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1119, 'Смесь Занзила и \"Дурацкое Крепкое\"', 'Я понял, как смешать смесь Занзила с пивом, чтобы получилось убойное пойло – \"Дурацкое крепкое\"! Наверное, это именно то, что нужно Крейвелу. Отнесите ему, пусть попробует. Расскажете потом, как все прошло!$B$BКстати, $N, эту брагу надо употребить как можно скорее – смесь Занзила оказывает на пивную закваску не очень хороший эффект, так что оно очень скоро выдохнется.', 'Отнесите \"Дурацкое Крепкое\" Крейвелу на Мерцающую равнину, что в Тысяче Игл.', 'Отлично! Гранк здорово помог нам! Обязательно отблагодарю его при встрече.$B$BИ вам спасибо, $N. Вы сделали большое дело, и оба мы заработаем на этом огромные деньги.', 'Привет, $N. Кранк Шипучка согласился нам помочь?', NULL, NULL, '\"Дурацкое Крепкое\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1120, 'Напоить гномов', 'Надо напоить \"Дурацким Крепким\" одну из команд на пит-стопах.Хочешь посмотреть, как оно подействует на гномов? Тогда возьми эль и передай его начальнику гномского гаража.$B$BИ поторопись – эта бурда быстро выдыхается.', 'Отнесите \"Дурацкое Крепкое\" начальнику гномского гаража в поселок Виражи на Миражах, что в Тысяче Игл.', 'Крепкое пиво? Как мило! Спасибо большое!$B$BПеред гонкой, конечно, пить не стоит, но... Самую чуточку ребятам не повредит. Да и не такое уж оно крепкое, так ведь?', 'Привет! Есть что-нибудь для меня?', NULL, NULL, '\"Дурацкое Крепкое\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1121, 'Напоить гоблинов', 'Надо напоить \"Дурацким Крепким\" одну из команд на пит-стопах.Хочешь посмотреть, как оно подействует на гоблинов? Тогда возьми эль и передай его начальнику гномского гаража.$B$BИ поторопись – эта бурда быстро выдыхается.', 'Отнесите \"Дурацкое Крепкое\" начальнику гномского гаража в поселок Виражи на Миражах, что в Тысяче Игл.', 'Что это? Ах, выпивка?$B$BНу что ж, стаканчик-другой никогда не повредит...', 'На что уставился?', NULL, NULL, '\"Дурацкое Крепкое\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1122, 'Возвращение к Пуззыриксу', '\"Дурацкое Крепкое\" отлично сработало! Я сделал ставку на следующую гонку и... надеюсь, команда, которую вы напоили, не забыла поставить на своей машине номер.$B$BУ меня еще одно задание для вас: отнесите эту записку обратно Шиззи Пуззыриксу в Пиратскую Бухту. Наверняка он захочет узнать, что эксперимент удался.$B$BНадо будет заказать у него еще этой выпивки для следующих гонок!', 'Отнесите отчет о \"Дурацком Крепком\" Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.', 'Здесь сказано, что задумка с \"Дурацким Крепким\" удалась. Отличная новость!$B$BЕсли вам вдруг потребуется еще, дайте знать, и я отправлю вас добыть еще смеси Занзила.', 'Здравствуйте, $N. Ну, как там сработала моя выпивка? Забористая штука, да?', NULL, NULL, 'Отчет о \"Дурацком Крепком\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1123, 'Рабин Сатурна', 'Мажордом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса... и еще дальше, к западу от Ун\'Горо. Найди его в Ночной Гавани, главном поселении Лунной поляны.$B$BПоскольку твои труды будут на благо всем нам, советую тебе вести себя осторожно. Между Дарнасом и Лунной поляной трения. Не думай о различиях между нашими народами, а лучше обратись к мудрости предков. Удачи тебе, $N.', 'Поговорите с Рабином Сатурной в селении Ночная Гавань на Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от крепости Древобрюхов.', 'Я Рабин Сатурна. От лица хранителя Ремула и всех обитателей сего священного места привествую тебя.$B$BЯ ценю твою заинтересованность и горячую готовность помочь Кругу Кенария. Таурены не раз показывали стойкую приверженность принципам Кенария, и благодаря им Орда может пользоваться безопасностью Лунной поляны. Ведь благо Азерота – наша общая цель.$B$BЗдесь ты среди друзей, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1124, 'Пустошь', 'К западу от Кратера Ун\'Горо, за северо-западным гребнем, лежит суровый пустынный край – Силитус. Немногие помнят, что там в древности развернулась война между ночными эльфами и злобной, чужеродной силой. Зло было повержено и заключено в оковы, но мы подозреваем, что сейчас некие силы хотят пробудить этот... невыразимый ужас.$B$BНайди Лайо Звездный Всполох, одного из наших разведчиков в Силитусе. Ищи его на Погосте Отважных, последнем приюте павших в этих пустынных краях. Передай ему это письмо, и он доверится тебе.', 'Поговорите с Лайо Зведным Всполохом близ кладбища Погост Отважных в Силитусе и покажите ему письмо Рабина.', 'Так тебя послал Рабин? Что же, чувствуй себя как дома... если хоть кто-то может назвать домом этот богами забытый край.$B$BВо времена великих бед меня еще не было среди живых, но в этих краях есть места, которые наяву рисуют жуткую картину позабытого прошлого. С твоей помощью Круг Кенария, может быть, покончит с угрозой, которая, как мы думали, исчезла много поколений назад.', 'Эти земли не прощают беспечности, $C. Что привело тебя в пустоши Силитуса?', NULL, NULL, 'Письмо Рабина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1125, 'Духи Южного Ветра', 'На юго-западе находится очень грустное место – деревня Южного Ветра. Именно с нее мы и начнем, $N.$B$BСудя по всему, некогда она была базой ночных эльфов для военных действий в Силитусе. Ее давным-давно захватили силитиды. Страшно представить, что там творилось в момент захвата...$B$BПо руинам бесцельно бродят духи павших друидов и стражниц. Исследуй эти края и освободи страдающие души, как подобает.', 'Освободите в деревне Южного Ветра души 8 истерзанных друидов и 8 истерзанных часовых и вернитесь к Лайо Звездному Всполоху на кладбище Силитуса, Погост Отважных.', 'Я подозревал, что немалую роль в гибели деревни сыграл огромный улей в башне неподалеку. Похоже, проделанная тобой работа подтверждает мои подозрения; улей представляет опасность для всей нашей деятельности.$B$BБлагодарю тебя за милость, оказанную душам павших. Я знаю, как нелегко это сделать. И все же я хочу вновь воззвать к тебе о помощи...', 'Ни одно существо не должно мучиться, как неупокоенные души, неважно, Альянсу оно служило или Орде. Это доброе дело – освободить несчастных призраков, $N.', NULL, NULL, 'Истерзанный друид убито', 'Истерзанный часовой убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1126, 'Улей в башне', 'Пора заняться ульем в деревне Южного Ветра, и мне кажется, я знаю, как это лучше сделать. Я знаю по опыту, что ульи силитидов очень чувствительны к окружающей среде; этим объясняется их нападения при звуках призрачного воя.$B$BСредоточие силы силитидов – башня, та самая, вокруг которой вьются осы. Ступай к этой башне и пробуди весь улей. Доложи обо всем, что удастся узнать, но соблюдай осторожность! Если попадется что-нибудь полезное, неси сюда.', 'Осмотрите башню деревни Южного Ветра и отыщите способ разворошить улей. Принесите все необычное, что попадется при выполнении задания Лайо Звездному Всполоху на кладбище Силитуса, Погост Отважных.', 'Что за... Что это?$B$BОно имеет форму... ящика? А дрянью-то как заросло... Стой, здесь видна часть того, что внутри. Неужели под всей этой гадостью скрывается книга?$B$BКажется, тебе удалось найти кое-что интересное, $N… по крайней мере, хочется на это надеяться. Может быть, это дневник или журнал, оставшийся с древних времен, лежавший в целости и сохранности под покровом хитиновой скорлупы.$B$BКажется, я знаю способ выяснить, что это.', 'Ну как, получилось? По крайней мере ты цел. Удалось что-нибудь отыскать?', NULL, NULL, 'Покрытый коркой щит силитида', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1127, '\"Дурацкое Крепкое\"', 'Говорите, вам нужно \"Дурацкое Крепкое\", да? Хотите снова отправиться на гонки?$B$BНу ладно, принесите мне еще смеси Занзила, и я наварю вам еще.', 'Принесите 12 порций смеси Занзила Шиззи Пуззыриксу в Пиратскую Бухту.', '', NULL, NULL, NULL, 'Смесь Занзила', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1130, 'Весть от Мелора', '$N, Мелор Каменное Копыто узнал о ваших подвигах и наметил для вас путь.$B$BЕсли вы хотите пройти его, отправляйтесь в Громовой Утес и поговорите с Мелором. Его можно найти на вершине Охотников.', 'Поговорите с Мелором Каменным Копытом в Громовом Утесе.', 'Итак, вы пришли, $N... Значит, вы готовы к путешествию через дальние земли?$B$BРаз так, юный $C, то слушайте...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1131, 'Сталезуб', 'Иногда мы охотимся ради еды. Иногда – ради чести. А иногда мы охотимся для того, чтобы усвоить уроки Матери-Земли.$B$BНо охота, на которую я хочу отправить вас, не имеет с этими вещами ничего общего. Вам нужно будет убить существо, не подчиняющееся божественной воле Матери-Земли.$B$BГиена по кличке Сталезуб бродит по Тысяче Игл, к югу от Степей. К этой зверюге прибиваются другие гиены, и вместе они держат всех остальных более мирных животных в страхе.$B$BНайдите Сталезуба, $N. Найдите и убейте его.', 'Принесите ребро Сталезуба Мелору Каменному Копыту в Громовой Утес.', 'Убив Сталезуба, вы избавили Тысячу Игл от страшной напасти.$B$BИ это, $N, ваш урок на сегодня.', 'Вы убили злобного Сталезуба, $N?', NULL, NULL, 'Ребро Сталезуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1133, 'Путешествие в Астранаар', '', '', '$N, вы здесь, чтобы предложить свою помощь Альянсу? Война уже добралась до этих мест, хотя Ясеневый лес все так же хранит свою красоту.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1134, 'Величавые виверны Каменного Когтя', 'Между нами и Ордой война не объявлена, однако мир между нами очень хрупок. Мы часто обнаруживаем, что среди нас тайно действуют их агенты. $B$BОб одной такой операции мы узнали из скрытых источников в Тераморе. Эти источники утверждают, что орки собирают яд величавых виверн поблизости от Мутного Озера в Когтистых горах, на юге. А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса!$B$BЕсли это правда, мы обязаны остановить их, $N. Мы должны лишить их источника яда.', 'Принесите 12 ядовитых желез славнокрыла Шиндрелл Огненный Всполох в Астранаар.', 'Благодарю тебя, $N. Мне не хотелось отправлять тебя убивать этих созданий, которые, возможно, не по своей воле помогали нашим врагам, однако это был мой долг.$B$BБыть может, друг мой, твое сердце оплакивает славнокрылов, которых тебе пришлось убить, однако пусть тебе принесет утешение то, что твои союзники больше не будут погибать от яда славнокрылов.', 'Тебе удалось добыть ядовитые железы славнокрыла, $N? Мы не можем позволить оркам использовать яд этих тварей против нас!', NULL, NULL, 'Ядовитая железа величавой виверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1135, 'Яд из Скального гнездовья', 'Как ты уже знаешь, орки часто приручают виверн в качестве ездовых животных. Но мало кто слышал о том, что яд виверны порой может быть ценнее самого животного. Так что, если желаете немного поохотиться, то у меня есть для вас работа.$B$BВ Тысяче Игл – это к западу отсюда – есть место под названием Скальное гнездовье. Там живут виверны, яд которых очень силен и чрезвычайно высоко ценится.', 'Принесите из Скального гнездовья 10 ядовитых желез для Фиоры Длинноушки в Терамор.', 'О-о-о, некоторые чуть ли не лопаются от яда, $N! Такие обычно собирают с очень юных виверн или с плодовитых самок. Наверное, нелегко вам пришлось в Скальном гнездовье!', 'Нашли Скальное гнездовье, $N? Как вас встретили тамошние виверны?', NULL, NULL, 'Ядовитая железа виверны Скального гнездовья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1136, 'Ледочрев', '$N, настало время тебе отправиться в далекие земли. Ты $gготов:готова: к этому путешествию. $B$BТебе поручается убить Ледочрева – йети, живущего в Альтеракских горах. Он отлично маскируется, его белая шкура сливается со снегами его горного обиталища. Увидеть его можно лишь изредка. $B$BНо я расскажу тебе, как приманить такое существо, как этот йети. Вот, возьми этот свиток: на нем я написал, как привлечь Ледочрева. $B$BА теперь ступай, $N. Путь предстоит долгий, впереди тебя ждут испытания. Задание будет выполнено, когда ты вернешься ко мне с гривой Ледочрева.', 'Принесите гриву Ледочрева Мелору Каменному Копыту в Громовой Утес.', 'Для того, чтобы найти и сразить Леочрева, нужно обладать силой и смекалкой, $N. Оба эти качества у тебя есть. $B$BТвой путь привел тебя в долины Тысячи Игл и в высокие горы Альтерака. Однажды он проведет тебя по всем странам матери-земли – ведь именно таков путь охотника.', 'Был ли ты в Альтеракских горах, $N? Ты встретился лицом к лицу с неуловимым йети Ледочревом?', NULL, NULL, 'Грива Ледочрева', 'Свиток из шкуры кодо', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1137, 'Новости для Пшикса', 'Индарилий обладает невероятной сопротивляемостью нагреву! Наверняка он подойдет для поршней Пшикса. Но ему потребуется настоящая индарилиевая руда, а не эти пластинки...$B$BЭту руду нужно добывать в глубине Ульдамана, на северной границе Бесплодных земель, – там ее навалом.$B$BПередавайте Пшиксу Медноштифту привет и скажите ему все, о чем я поведал вам.$B$BСчастливого пути, $N. Думаю, мы с вами еще увидимся: как только Пшикс прознает про индарилий, он как пить дать отправит вас в Ульдаман.', 'Поговорите с Пшиксом Медноштифтом на Мерцающей равнине, что в Тысяче Игл.', '$N, ты вернулся! Ты нашел Мартека? Вы с ним поговорили? Что он сказал? Он поможет?$B$BГовори-говори-говори!!!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1138, 'Дары моря', 'Мне нравятся крабы. Крабы – это деликатесные дары моря! Их можно печь, жарить на гриле, варить, делать из них бульон. Еще их можно жарить на сковороде, во фритюре и просто жарить. Есть крабовый салат, крабовый суп, краб тушеный, краб перченый, краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый десерт. Вот и... ну, и все.$B$BЯ здесь сейчас рыбу ужу, потому охотиться на сочных крабов мне некогда. Можешь извлечь кусочки отличного мяса из рифовых крабов и покрытых илом крабов. Их можно печь, жарить на гриле, варить...', 'Соберите 6 кусочков отличного крабьего мяса для Груббера Блумпа в Аубердине.', 'Да-а-а, эти кусочки отличного крабьего мяса – как раз то, что мне нужно. Спасибо, $N! Вот, это я обнаружил как-то, когда рыбачил, и мне оно без надобности. Может быть, ты сможешь как-то это использовать? В деликатесные блюда из крабов это уж точно не положишь.$B$BЯ ведь уже рассказывал тебе о крабах, правда?', '...краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый сюрприз. Вот и... ну, и все.', NULL, NULL, 'Кусочки отличного крабьего мяса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1139, 'Утерянные таблички Воли', 'Мы смогли сдержать клан Тенегорн, отрезав их силы от пика Черной Стали, но задание Тяжелоступа еще не выполнено. Его смерть не должна быть напрасной. Он мечтал найти табличку воли: камень, на котором высекли магические письмена сами титаны, чтобы вдохнуть жизнь в созданных ими существ, – по крайней мере, так гласят легенды. $B$BМы должны заполучить табличку воли прежде, чем до нее доберется клан Тенегорн. $B$BВозвращайся в Ульдаман, найди табличку и принеси ее мне незамедлительно.', 'Найдите табличку воли и принесите ее советнику Белграму в Стальгорн.', '*При виде таблички советник Белграм изумленно качает головой*$B$B$N, это поразительно! Я прослежу, чтобы табличка была доставлена королевским магам как можно скорее. Они непременно пожелают проверить, что в легендах истина, а что ложь. Ты помог нашему народу более, чем я смел надеяться!', 'Мы должны выполнить завет Тяжелоступа, $N! Я столь многим обязан ему. $B$BТвоя экспедиция в Ульдаман служет не только этой цели, но и благу всего рода дворфов! Если табличка попадет в руки Черного Железа, кто знает, какую армию големов они смогут создать!', NULL, NULL, 'Табличка воли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1140, 'Башня Алталакса', 'Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. $B$BИз каракулей Илкруда можно понять, что у Атрикуса еще оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса.$B$BПоосторожнее там, $N, от вида кровавых храмов сатиров содрогнется даже $gтакой закаленный:такая закаленная:c: $C, как ты.', 'Освободите заточенные души высокорожденных на Ночной поляне и Сатирнааре, затем вернитесь к Делгрену Очистителю на заставу Мейстры.', 'Возможно, мы слишком долго терпели сатиров в этом лесу. Я поговорю с Элиссой насчет этого, когда в другой раз поеду в Аубердин.$B$BТем не менее, раз самоцветы души уничтожены, сила Атрикуса сильно уменьшится. Мы должны воспользоваться этой возможностью и уничтожить его и его культ.', NULL, NULL, NULL, 'Освободите душу высокорожденного на Ночной поляне', 'Освободите душу высокорожденного в Сатирнааре', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1141, 'Семья и рыболовная удочка', 'Мне нравится рыбачить. Семья Блумп славится своими рыбаками. Меня зовут Груббер Блумп. Я рыбак.$B$BЕсть одна рыбка, которую я хотел бы поймать в этих водах – местная разновидность окуня. Я раньше ходил на окуня на лодке, но с тех пор как побережье оккупировали эти противные мурлоки, ни одна лодка в море не выходит. Боюсь, они и окуней всех съедят.$B$BСлушай, хочешь помочь мне наловить окуней? Я б тебе от чистого сердца подарил фамильную удочку семьи Блумп! Это очень хорошая удочка!', 'Поймайте 6 морских окуней с Темных берегов для Груббера Блумпа в Аубердине.', 'Какие отличные окуни, $N! Большое спасибо за помощь!$B$BТы как минимум такой же хороший рыбак, как моя драгоценная родственница Граун Блумп. У нее, правда, растет борода и от нее несет чем-то странным, но это для нее не причина перестать рыбачить. Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп.', 'Из окуней с Темного Берега можно приготовить множество вкусных блюд. Окуни хороши на вкус, но ловить их, я думаю, еще приятнее.$B$BТы еще не наловил окуней Темного Берега?', NULL, NULL, 'Окунь с Темных берегов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1142, 'Последнее желание', 'Мне недолго осталось жить... о, я так слаб...$B$BХмурен... храбрый дворф, он отправился... предупредить Фалфиндера...$B$BНо прежде, чем я умру... $B$BПожалуйста, верни моей жене ее подвеску... ее украл один из этих негодяев...$B$BПодвеска связывает нас... это очень важно... Пожалуйста, верни подвеску моей Трешале... в Дарнас... $B$BИ расскажи ей... о моей смерти.', 'Найдите подвеску Трешалы и верните ее Трешале Бурый Ручей в Дарнас.', 'О нет! $B$BНе может быть! О, я не верю! О, жестокий мир! $B$BМне предстоит весь век нести в сердце горе... Я не позволю делу Гералата погибнуть вместе с ним! $B$BБлагодарю тебя за то, что ты проделал этот опасный путь, $N. Но теперь оставь меня. $B$BЯ оплачу мужа в одиночестве...', 'Что привело тебя ко мне, $R?', NULL, NULL, 'Подвеска Трешалы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1143, 'Башня Алталакса', 'Понятно. Ну если то, о чем вы говорите, – правда, то сейчас самое время нанести удар. Я уверен, что Атрикус обосновался на самом верху башни. Однако будьте осторожны, его окружает множество сильных колдунов, гораздо более опасных, чем те, с кем вы встречались ранее.', 'Убейте Атрикуса Нарассина и принесите его голову Балтулу Удару Тени у башни Алталакса.', 'Я надеюсь, что после смерти Атрикуса демонические силы в этом районе отступят. Я не сомневаюсь, что они перегруппируются и вернутся, но тогда мы будем еще лучше подготовлены, чтобы встретить эту угрозу лицом к лицу.', 'Атрикус Нарассин – древний и могущественный чернокнижник. Может быть, нам стоило бы подождать, пока сам Делгрен не придет на помощь, но он, очевидно, очень сильно верит в вас, раз уж послал вас в одиночку.', NULL, NULL, 'Голова Атрикуса Нарассина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1144, 'Импортер Вилликс', 'Наконец-то, помощь пришла!$B$BТы не представляешь, как долго я уже здесь торчу! Уже и не помню, когда последний раз высовывал нос наружу.$B$BВидишь ли, я предприниматель. Как говорится, всегда ищу выгоду. Вот, прослышал, что Мебок Миззрикс дает хорошую цену за растущий здесь корень синелиста. Ну я и подумал, что на этом можно заработать неплохие денежки. Как видишь, я немножко ошибся!$B$BВытащи меня отсюда, я тебе хорошо заплачу!', 'Проводите импортера Вилликса до выхода из Лабиринтов Иглошкурых.', 'Уф... спасибо, дружище! А вот и обещанная награда – за мной не заржавеет!', NULL, NULL, NULL, 'Помогите Импортеру Вилликсу сбежать из Лабиринтов Иглошкурых.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1145, 'Рой растет', 'Многие путешественники, приходившие в Перекресток, помогали мне собирать яйца на Полях Великанов, а потом рассказывали, какие страшные твари там живут. Мне хватило этих рассказов, чтобы убедиться в том, что мой хозяин недооценил этих насекомых, и что на самом деле они гораздо опаснее.$B$BМне нужен кто-то, кто отправится в Оргриммар и встретится там с Белгромом Каменной Булавой. Это очень серьезное дело, которое можно поручить только ответственному посыльному.$B$BБелгрома почти всегда можно найти у цехового дома воинов.', 'Отнесите запечатанную записку Коррана Белгрому Каменной Булаве в Оргриммар.', 'А, записка от Коррана. Он служит уже давно и очень преданно. Я как раз собирался узнать, как у него дела в Перекрестке.', 'Я завидую вам, $C. Похоже, вы давно не бывали в Оргриммаре...$B$BЯ бы и сам отправился в путешествие, во славу Вождя, но Траллу я нужен здесь. Однако он очень мудрый правитель, и я верю ему. Я готов оставаться здесь столько, сколько буду ему нужен.', NULL, NULL, 'Запечатанная записка Коррана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1146, 'Рой растет', 'Значит, Корран пришел к похожему заключению относительно этих насекомых: они представляют собой гораздо большую угрозу, чем мы думали.$B$BНесколько дней назад из Тысячи Игл ко мне вернулся полумертвый охотник. Его с отрядом отправили на Мерцающую равнину, чтобы выгнать оттуда бригаду дворфов-археологов, но во время боя на месте раскопок появились эти насекомые и чуть было не положили весь отряд.$B$BГлавным у них был Моктар Крин, и сейчас они разбили лагерь на границе Мерцающей равнины. Отнесите ему это письмо.', 'Доставьте запечатанное письмо Белгрома Моктару Крину в Тысячу Игл.', 'Не обращайте внимания на это грохочущее эхо. Это всего лишь гонка гномов и гоблинов на Равнинах – они носятся на кошмарных машинах, созданных по всем правилам так называемой \"науки\". Однако в Тысяче Игл есть куда более серьезные опасности, одна из которых недавно унесла жизни большей части моего отряда.$B$BНо мы останемся здесь до тех пор, пока не получим известие от Белгрома из Оргриммара. До этого мы будем держать позицию и стоять на страже.', 'Нас привела на Мерцающую равнину война. А что привело вас сюда, $N?', NULL, NULL, 'Запечатанная записка Белгрома (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1147, 'Рой растет', 'Хмм. Значит, Белгром считает этих монстров опасными и хочет, чтобы их загнали в те глубины, из которых они некогда выползли.$B$BЕму, значит, недостаточно того, что мы убили всех дворфов из Лиги исследователей – надо посылать полумертвый отряд в новый бой! Сами мы не справимся, по крайней мере в таком состоянии. Карьер находится к югу отсюда, и дворфов там, скорее всего, больше нет. Не хочешь ли помочь нам своим клинком или посохом?', 'Убейте 5 силитидов-искателей, 5 силитидов-трутней и 5 силитидов-захватчиков, а потом вернитесь к Моктару Крину в Тысячу Игл.', 'Ха! Эта лимфа, которой ты покрыт с ног до головы, только красит тебя, $N! Хотя воняешь ты так, что аж глаза режет... Не подходи слишком близко к кодом, а то они сбегут или набросятся на тебя.$B$BДумаю, мои товарищи согласятся принять этот запах за убедительное доказательство того, что ты помог нам справиться с этими мерзкими насекомыми. Спасибо, $N.', 'Куча народу приезжает на Мерцающие равнины, чтобы посмотреть гонки. Думаю, мы найдем достаточно искателей приключений для того, чтобы избавиться от этих насекомых. А до тех пор мой отряд не сможет покинуть этот пост.', NULL, NULL, 'Силитид-искатель убито', 'Силитид-трутень убито', 'Силитид-захватчик убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1148, 'Части роя', 'Вы тщательно осматриваете панцирь. Повращав его в руках, вы видите, что полоски хитинового покрытия переплетены совершенно неповторимым образом, что делает панцирь невероятно прочным. Вы никогда в жизни не видели ничего подобного. Вы осматриваете останки дальше и понимаете, что эти существа очень сильны и высокоразвиты.$B$BЕще раз взглянув на эти останки, вы думаете, что Коррану было бы интересно обследовать этих существ поподробнее. Это помогло бы ему понять, кто они и откуда взялись.', 'Добудьте 1 сердце, 5 шпор и 3 целых силитидских панциря для Коррана из Перекрестка.', 'О, так вы недавно виделись с Моктаром? Он всегда заботился обо мне. Жаль слышать, что он тратит свое время на то, чтобы присматривать за своей группой, вместо того чтобы самому участвовать в бою... Но, думаю, ему нравится убивать членов Лиги Исследователей.$B$BХорошо, что вы принесли мне эти образцы, $N. Мы собрали и другие яйца насекомых на Полях Великанов, так что теперь у меня есть хороший материал для изучения. Скоро я смогу узнать, что это за насекомые и чего они хотят.', 'Ага, давненько ты ко мне не заглядывал, $N. Чем я могу тебе помочь? Похоже, на тебе еще не обсохла кровь врагов? Это хорошо. Хорошо и для вас, и для Орды, потому что чем больше битв вы пройдете, тем сильнее станете.', NULL, NULL, 'Сердце силитида', 'Шпора силитида', 'Целый силитидский панцирь', 'Раздробленный силитидский панцирь');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1149, 'Испытание веры', 'Итак, ты $gнашел:нашла: меня – или, возможно, тебя привела сама судьба? Это неважно. Теперь ты здесь, и перед тобой лежит новый путь.$B$BЛичность складывается из многих из многих граней: души, тела и разума. Некоторые из этих аспектов определяются культурными традициями, о наличии других мы можем только догадываться. Если согласишься, я испытаю некоторые присущие тебе качества.$B$BЕсли ты пройдешь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты.$B$BПервое испытание – это испытание веры.', 'Если ваша вера сильна, прыгните с досок над Тысячью Игл.', 'Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой. Ты поверил в себя, хотя и не был уверен, что выживешь. Твой разум открыт, и твой дух готов встретить все, что ждет впереди.$B$BЕсли желаешь, можешь приступить к следующему испытанию.', 'Вера. Она куда важнее, чем считают многие.$B$BИногда не важно, во что ты веришь, главное – верить.', NULL, NULL, 'Исследовать локацию', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1150, 'Испытание выносливости', 'Хорошо, что ты не теряешь смелости несмотря ни на что. Твоя вера крепка, и теперь настало время испытать твою силу.$B$BСначала тебе надо пройти испытание выносливости. Отправляйся в Логово Легкоперых - оно к западу от Заставы Вольного Ветра. Проберись в самую глубину логова и уничтожь там все запасы еды. К тому времени местные гарпии будут в ярости, и если ты останешься в живых, с тобой пр$Nит сразиться их предводительница - Гренка Кровавый Визг. Убей ее и принеси мне ее коготь, чтобы пройти это испытание.', 'Принесите коготь Гренки Дорну Вольному Ловчему в Тысячу Игл.', 'Гренка была очень сильна даже для такого $R как ты. Сегодня ты можешь по праву гордиться собой.$B$BВо время испытания веры ты показал силу своего духа, а сегодня подтвердил, что физически ты готов к битве. Гарпии Легкого Пера мертвы, и теперь настало время нового испытания.', 'Чтобы пройти все назначенные испытания, ты должен подготовиться морально, духовно и физически.$B$BМы слишком часто рвемся вперед неподготовленными. Я считаю своим долгом подготовить всех новичков, которые приходят ко мне, вне зависимости от их племени. Они должны знать, с чем им предстоит столкнуться за порогом родного дома.', NULL, NULL, 'Коготь Гренки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1151, 'Испытание силы', 'Во времена Древних богов элементалей можно было встретить повсюду. Они поклонялись Древним богам, а боги своей силой поддерживали связь духов с этим миром. Когда же Древние боги были изгнаны, элементали тоже покинули этот мир и теперь являются сюда только по зову могущественных магов.$B$BНо есть и исключения. Некоторые духи были достаточно сильны для того, чтобы остаться в этом мире, и одного из них зовут Рок\'Алим.$B$BДля того чтобы испытать свою силу, найди в Тысяче Игл Рок\'Алима и убей его.', 'Принесите фрагменты Рок\'Алима Дорну Вольному Ловчему в Тысячу Игл.', 'Испытание силы пройдено. Вы показали свою силу и храбрость и теперь готовы к последнему испытанию, после которого эти ритуалы завершатся.', 'Племена кентавров зовут Рок\'Алима Крушителем – из-за грохота, который издают его кулаки, которые он обрушивает на тех, кто достаточно смел или глуп для того, чтобы оказаться у него на пути.', NULL, NULL, 'Фрагменты Рок\'Алима', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1152, 'Испытание знаний', 'Твои испытания почти закончились, но проверку знаний проводить буду не я. Тебе придется посетить другие места и усвоить там новые уроки.$B$BЕсли ты $gготов:готова:, найди Брауга Тусклый Дух – это очень мудрый шаман. Внимательно выслушай его и выполни все, что он скажет, $N.$B$BБрауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес. И будь $gосторожен:осторожна:, $N, ночные эльфы могут помешать тебе.', 'Найдите Брауга Тусклый Дух возле входа в Туннель Когтя в Когтистых горах.', 'Гоблины терзают землю, ночные эльфы унижают младшие расы, а дни и ночи тем временем становятся все холоднее и холоднее. Отрекшиеся и орки – не единственные, кого нужно винить за конфликты, возникшие на землях Калимдора и Лордерона. Многие разумные расы причинили миру немало боли. Дорн знает об этом, и он отправил вас ко мне, потому что вы тоже способны это понять.$B$BСейчас вы стоите перед Браугом.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1153, 'Образец новой руды', '$C, раньше вы часто помогали мне в разных делах. Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью. По закону чести, я должен рассказать вождю обо всем, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи.$B$BНедавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл. Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать. А он мне очень нужен для исследования!', 'Отберите неочищенный образец руды у землекопа или геодезиста из племени Камнерылов и принесите его Таттернаку Стальному Горну в Лагерь Таурахо в Степях.', 'Хороший образец, $N. Очень хороший.$B$BВы замечательно справились с заданием, и эти путешественники больше не смогут задирать передо мной нос.$B$BЯ немедленно начну работать с ней, и если руда окажется достаточно прочной, я изготовлю из нее оружие и отправлю вождю, чтобы он посмотрел на наши успехи.$B$BЯ не забуду вашей помощи, $C.', 'Потом я встретился с путешественниками снова – с теми самыми, что не продали мне образец руды. Я плюнул в них за то, что они не стали помогать вождю.$B$BПусть они умрут в бою как трусы, а не как благородные воины, вставшие на сторону Орды.', NULL, NULL, 'Неочищенный образец руды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1154, 'Испытание знаний', 'Ты $gпрошел:прошла: испытание Дорна и хочешь пройти следующее? Что ж, хорошо. Но все предыдущие испытания были детскими играми. Физическую силу испытать легко – то ли дело сила разума!$B$BЛадно, объясню попроще: найди книгу, которую я назову, изучи ее и ответь на мой вопрос по ее содержимому.$B$BТы спросишь, что за книга? Она называется \"Наследие Аспектов\". Ее можно найти в глубине обители Дор\'Данил, это в южном Ясеневом лесу. Книгу охраняют мертвые друиды и их убийцы.', 'Найдите книгу \"Наследие Аспектов\" и вернитесь к Браугу Тусклому Духу ко входу в Туннель Когтя.', 'Это та самая книга, о которой я говорил. Полагаю, тебе известен ответ на мой вопрос – если только ты не поленился изучить книгу.$B$BКак только будешь готов, обратись ко мне, и я задам тебе вопрос.', 'Принеси мне книгу, когда прочитаешь ее. До этого я не буду задавать тебе вопросов.', NULL, NULL, 'Наследие Аспектов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1159, 'Испытание знаний', 'Отличная работа, $N. Ты $gпрошел:прошла: первую часть испытания знаний, но еще один вопрос остался без ответа. Правда, задавать его буду не я.$B$BПоговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей. Он до сих пор стремится к просвещению, но уже по-другому.$B$BОн даст тебе задание, и только потом задаст вопрос – но до сих пор ты $gсправлялся:справлялась: хорошо, и, я уверен, трудностей у тебя не возникнет.', 'Найдите Парквела Финталласа в Подгороде.', 'Тебя прислал Брауг? Невероятно.$B$B*Парквел критически осматривает вас.*$B$BСправился в Дор\'Даниле, прошел испытание веры и совладал с могущественным элементалем? Ха! Да ты, наверное, наслушался разговоров в таверне и теперь нагло врешь мне! Думаешь, что сможешь пройти мое испытание? Ну что ж, хорошо... $C.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1160, 'Испытание знаний', 'Я скажу тебе, что искать, и даже задам вопрос, но не потому, что тебе хочется проявить себя. Знания гораздо важнее силы. Даже если кто-то силой превосходит тебя, твои знания о мире могут оказаться куда полезнее.$B$BОтправляйся в монастырь на севере Тирисфальских лесов. В их библиотеке есть книга под названием \"Истоки угрозы нежити\" – по ней ныне обезумевшие паладины учатся истреблять моих собратьев.$B$BПринесите ее мне.', 'Найдите книгу \"Истоки угрозы нежити\" и отнесите ее Парквелу Финталласу в Подгород.', 'Это та самая книга, которую я велел тебе найти.$B$B*Парквел нежно проводит рукой по обложке, разглядывая ее.*$B$BЗначит, ты хочешь, чтобы я задал тебе вопрос, чтобы ты мог доказать, что твой дух так же силен, как и тело? Если ты хорошо изучил книгу, то я задам тебе вопрос, и с испытаниями будет покончено.', 'Надеюсь, ты доставил Алому ордену достаточно неприятностей перед тем, как украсть книгу.$B$BМое отношение к ним отнюдь не беспочвенно. Возможно, когда-то его участники и почитали Свет, но теперь они стремятся лишь уничтожить всех, кто не принадлежит к их религии. Они считают, что вся нежить – Отрекшиеся и все остальные – должна быть уничтожена, а тех, кто путешествует в земли нежити, они считают либо безумцами, либо рабами сильной магии. Идиоты. Идиоты и глупцы, все до единого.', NULL, NULL, '\"Истоки угрозы нежити\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1164, 'Ограбить воров', 'Воровка! Свинья! Кената все еще жива, ее семья живет и процветает, а я страдаю. Вот уж действительно Отрекшаяся!$B$BВсю мою семью забрала чума. Все наше имение тоже разорили во время войны. И теперь она и ее мерзкие дети имели наглость похитить у меня последние ценные вещи.$B$BСами вещи мне уже не нужны. Теперь я жажду мести!$B$BУбей этих проходимцев! Ступай в усадьбу Дабири в Арати, на северо-востоке от Опорного пункта.', 'Принесите головы Кенаты, Фардела и Марселя Дабири Генви Кэллоу в Подгород.', 'Ты стоишь передо мной, словно посланник Мести, и я склоняюсь в знак признательности.$B$BЖирная корова мертва, и я, зная, что ее потомки не будут топтать землю Азерота, могу потратить силы на что-нибудь более разумное. Надеюсь, прикончив их, ты ограбил усадьбу?', 'Убей их и принеси мне головы!', NULL, NULL, 'Голова Кенаты', 'Голова Марселя', 'Голова Фардела', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1166, 'Заботы властителя Мок\'Морокка', 'Твоя кланяться властитель Мок\'Морокк!$B$BРексар назначить меня правителем клана Каменного Молота!$B$BМоя хороший вождь! Моя бережет свой клан!$B$BБольшие драконы пр$Nать и жечь наш старый дом. Моя – умный огр! Моя найти здесь новый дом для свой клан. $B$BБросать старый дом так быстро, что забыть моя вещи. $gМаленький:Маленькая:$r, ты идти и приносить моя вещи. Идти на юг и приносить мой вкусный грог, мой табак и мой сейф. Я благодарить твоя, когда твоя сделать это. Твоя искать в Обители Пламени и в руинах Деревни Каменного Молота. Они быть там, моя уверен.', 'Принесите Мок\'Морокку его грог, табак и сейф в Гиблотопь.', 'Хороший $R. Моя скучать по этим вещам. Моя теперь дружить с твоя.', 'Моя хотеть свой грог. И свой табак. Где мой сейф? Твоя идти и приносить все властителю Мок\'Морокку. Моя слишком занят, моя управлять ограми.', NULL, NULL, 'Понюшка Мок\'Морокка', 'Грог Мок\'Морокка', 'Сейф Мок\'Морокка', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1167, 'Башня Алталакса', 'Прежде чем встретиться с Атрикусом, разумно было бы тебе посоветоваться с Балтулом. Не сомневаюсь, что он неусыпно следил за башней и может знать о недавних событиях.', 'Поговорите с Балтулом Ударом Тени возле башни Алталакса.', 'А, приятно снова свидеться, $N! Тут такие странные вещи творились, так что хорошо, что ты снова тут появился!$B$BОчень странные вещи, $N. Все казалось как обычно – ну, насколько тут вообще все может быть обычно – и вдруг на верхнем этаже башни как полыхнет! Потом начались вопли. Вопли раскалывали воздух, а в землю порой били молнии. Что все это может значить?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1168, 'Армия Черного дракона', 'Мок\'Морокк получил власть от Рексара. Но он больше любил власть, чем огров.$B$BЧерные драконы убили много огров. Убили жену Тхарга. Мок\'Моррокк велел нам бежать. Заставил прийти сюда.$B$BОгры должны биться. Ограм плохо бегать. Мок\'Морокк думает только о Мок\'Морокке.$B$BМой дом в руинах Деревни Каменного Молота. Мне нравится там на юге. Здесь не наш дом.$B$BПомоги ограм победить войско черного дракона. Мы хотим отомстить. Мы хотим домой.', 'Тхарг из деревни Гиблотопь хочет, чтобы вы уничтожили 10 огнегривых разведчиков, 10 огнегривых пеплохвостов и 5 огнегривых чешуйчатых губителей.', 'Ты убил многих из войска Черного дракона. Ты – отважный $R! Тхарг счастлив!', NULL, NULL, NULL, 'Огнегривый разведчик убито', 'Огнегривый пеплохвост убито', 'Огнегривый чешуйчатый губитель убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1169, 'Корни угрозы', 'Пока этот трусливый глупец Мок\'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает у него власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас.$B$BПочему ты так озадаченно смотришь на меня, $N? $gДумал:Думала:, я буду говорить как неотесанный чурбан только потому, что я – огр?$B$BНо к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла.', 'Принесите Драз\'Зилбу в деревню Гиблотопь 7 огненных языков и 7 пылающих сердец.', 'Рискованное было дельце, добывать все эти сердца и языки, а? Теперь я проникну в глубины тайн, чтобы выяснить, откуда на наш прежний дом свалилась такая напасть.', 'Теперь я смогу узнать, что за тварь напустила на нас свои отродья. Возможно, зная больше о захватчике, мы сможем понять, как уничтожить его раз и навсегда и поднять деревню Каменного Молота из руин.$B$BКонечно, заставить Мок\'Морокка оторвать свой толстый зад от земли, – уже само по себе героический поступок...', NULL, NULL, 'Огненный язык', 'Пылающее сердце', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1170, 'Выводок Ониксии', 'Деревня Каменный Молот была захвачена выводком Ониксии. Но почему дочь великого дракона Смертокрыла вторглась в наши земли? Вот что тревожнее всего!$B$BНеужели только для того, чтобы уничтожить небольшое поселение огров?$B$BПредупреди Мок\'Морокка. Нельзя сидеть сложа руки!', 'Поговорите с властителем Мок\'Морокком в Деревне Гиблотопь.', 'Почему ты говорить с моя про драконы? Моя не любить драконы. Моя не хотеть здесь никакие драконы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1171, 'Выводок Ониксии', 'Твоя уходить. Твоя идти и сказать Драз\'Зилбу, мы оставаться здесь. Здесь нет никакой черный дракон.', 'Поговорите с Драз\'Зилбом в Деревне Гиблотопь. ', 'Жалкий трус!$B$BМок\'Морокк выказывал силу, пока нашим вождем был Рексар. Но после его ухода Мок\'Морокк начал сам стремиться к власти. Он предпочитал требовать, вместо того чтобы руководить. Он не заботится о своих подданых, а наоборот хочет, чтобы мы заботились о нем.$B$BС этим надо что-то делать!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1172, 'Выводок Ониксии', 'Потомки Ониксии распространились по всей Земле Драконов. Нельзя допустить, чтобы и остальные ее отродья вылупились на свет!$B$BПоспеши в Драконьи топи на юге Пылевых топей. Наверняка она устроила там свое логово. Найди яйца злой драконихи и уничтожь их!$B$BМы никогда не вернем себе деревню Каменного Молота, если вокруг будут продолжать плодиться драконы.$B$BА что касается Мок\'Морокка... касательно этого червя у меня есть особые планы.', 'Драз\'Зилб из Деревни Гиблотопь хочет, чтобы вы уничтожили 5 яиц Ониксии.', 'Прекрасно! Теперь Ониксия не скоро отложит очередную кладку.$B$BБлагодарю тебя, $N, от имени моего народа.$B$BЯ уже о многом просил тебя, но, может, ты окажешь последнюю услугу клану Каменного Молота.$B$BМок\'Морокк не достоин править нами. Тхарг стал бы отличным вождем, но он стар и изранен. Изгони силой из этих мест Мок\'Морокка. Только тогда мы сможем избрать нового вождя, который отведет нас на родину, в южные земли.', 'Тебе надо поспешать в Землю Драконов, $N. Пока Драконья топь завалена яйцами Ониксии, они всегда будут превосходить нас числом. Поторопись же.$B$BУничтожь ее яйца! Не дай драконьей заразе расползаться по нашим землям!', NULL, NULL, 'Уничтожено яиц Ониксии', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1173, 'Вызов властителю Мок\'Морокку', 'Ты осмеливаешься вызвать на поединок властителя Мок\'Морокка?$B$BХа!$B$BМеня хочет сокрушить $gжалкий:жалкая: $r!$B$BПриготовишься к трепке – скажи мне.', 'Победите Мок\'Морокка и сообщите об этом Драз\'Зилбу в Деревне Гиблотопь.', 'Эта трусливая туша, Мок\'Морокк, сбежал как испуганный младенец при виде розги. Ты оказал нам огро$Nю услугу, $N.$B$BТеперь мой народ может выбрать себе нового лидера, того, кто поможет восстановить наши жилища и защитить их.', NULL, NULL, NULL, 'Изгнать владыку Мок\'Морокка из Деревни Гиблотопь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1175, 'Помехи на трассе', 'После того как гоблинский болид \"Красный Гром\" столкнулся с василиском, Кронкрайдер нанял меня присматривать за трассой. Не знаю, что жрут местные животные, но они вырастают просто огромными, и нужно постоянно отпугивать их, чтобы они не забредали на трек во время гонки.$B$BЗнаете, что? Если желаете немного заработать, ступайте и избавьте нас от нескольких василисков.', 'Убейте 10 просоленных василисков, 10 просоленных хрусталисков и 6 просоленных взорней, после чего вернитесь к начальнику трассы Зерину на Мерцающую равнину.', 'Надеюсь, вы не убивали василисков прямо на трассе? Здесь тела разлагаются очень долго, а лопатой их убирать замучаешься.', 'Убирать обломки с места аварии – тяжкий труд, а уж когда тебе мешают всякие твари, работа становится просто невыносимой.', NULL, NULL, 'Просоленный василиск убито', 'Просоленный хрусталиск убито', 'Просоленный взорень убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1176, 'Уменьшение веса', 'На гонках имеет значение абсолютно все! Будь то малейшее изменение мощности, небольшое ослабление колец натяжения или уменьшение веса болида – любую мелочь надо принимать в расчет.$B$BМы используем в своих болидах кости стервятников – они очень крепкие и легкие. К тому же их очень легко найти. Уж чего-чего – а стервятников на Мерцающих равнинах хватает.$B$BПринеси мне немного костей, и я хорошо заплачу тебе.', 'Добудьте 10 полых костей стервятника для Поззика с Мерцающей равнины.', 'Отлично! Моя команда сейчас же начнет работу! Спасибо, $N.', 'Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.', NULL, NULL, 'Полая кость стервятника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1177, 'Моя голодный!', 'Моя – большой огр. $B$BМоя голодный.$B$BТвоя идти ловить рыба. Твоя принести Дробу еда.$B$BТвоя кормить Дроб, или Дроб есть твоя.', 'Принесите дробильщику Грязноногу, живущему на севере Пылевых топей, 8 голов мурлоков из клана Болотного Плавника.', 'Моя любить рыбья голова!$B$BМоя пока твоя не есть.', 'Дать мне еды или я есть твоя.', NULL, NULL, 'Голова мурлока из клана Болотного Плавника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1178, 'Гоблинская поддержка', 'Наша гоночная команда – это гордость всей расы гоблинов! Вы удивитесь, узнав, что за личности в той или иной мере покровительствуют нашей команде.$B$BЗнаете Газлоу? Он собирает для нас детали по всему миру, а однажды даже разработал для нас новые костюмы!$B$BНесколько недель назад он пообещал прислать новый топливный регулятор, но посылка пока не пришла. Странно, обычно Газлоу держит свое слово... Может, вы не прочь съездить в Кабестан и спросить у него? Я бы не настаивал, но эти гномы нас догоняют!', 'Поговорите с Газлоу в Кабестане, что в Степях.', 'Вас прислал Поззик? Когда-то ведь он был одним из самых уважаемых механиков в Нижней шахте, но потом уволился и занялся гонками.$B$BПервое, что он сделал, придя в команду, – разработал две новых модели двигателей. Дела Союза ремонтников могут пострадать без Поззика, но ему уже нет до этого дела... Гонки для него все!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1179, 'Братья Медноштиф', 'Вы когда-нибудь слышали о Мерцающей равнине? Это огромное соляное плато в Калимдоре, южнее каньона Тысяча Игл. Это отличное место для гонок, потому что поверхность там совершенно... ну... равнинная!$B$BТам живет парочка гномов – мои друзья, они строят новый болид, и говорят, он жуть какой быстрый! Настолько быстрый, что их пилоты то и дело разбиваются и калечатся...$B$BОни заказали у меня несколько защитных шлемов, но у меня дела, и я не могу их отвезти.$B$BМожет быть, вы мне поможете?', 'Принесите ящик с защитными шлемами Виззлу Медноштифу на Мерцающую равнину, что в Тысяче Игл.', 'Ага! Длиннобородый прислал с вами наши шлемы! Ур-р-а-а-а!!!$B$BОсталось уговорить пилота сесть в наш болид...', 'Смотри куда прешь! Эй, эй, эй! Тут все хрупкое и важное, не вздумай ничего портить, а то мы не выиграем гонку!', NULL, NULL, 'Ящик с защитными шлемами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1180, 'Гоблинская поддержка', 'Вернемся к делу. Я обещал Поззику привезти новый топливный регулятор, но так и не получил его. Ревилгаз из Пиратской Бухты сказал, что выслал его, но, похоже, он куда-то улетучился.$B$BКоли так, ничего не попишешь, но по меньшей мере мы можем выяснить, отправляли его или нет.$B$BПоговори с управляющим пристанью Подгребаем по ту сторону моря, пусть заглянет в свои журналы.', 'Поговорите с управляющим пристанью Подгребаем в Пиратской Бухте, что в Тернистой долине.', 'Поставки в Кабестан? Дай-ка я загляну в записи…$B$BНет, последний груз, отправленный в Кабестан, если не считать оборудования и припасов, – это сапоги от Дриззлика. Никаких запчастей для гонок.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1181, 'Гоблинская поддержка', 'Боюсь, тут я помочь уже не в силах, $N. Если ты хочешь узнать подробности, поговори с самим бароном. Никто не знает дела Ревилгаза лучше самого Ревилгаза.$B$BОн сейчас на верхнем этаже таверны на другой стороне залива.', 'Поговорите с бароном Ревилгазом в Пиратской Бухте.', 'А, разумеется, я понимаю, о чем ты. Нет, помочь не могу. Мои наемники должны были добыть чертежи топливного регулятора, но вернулись с пустыми руками.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1182, 'Гоблинская поддержка', 'Видишь ли, резаки Торговой Компании возле озера Назферити (в северной части Тернистой долины) оборудовали новой моделью топливного регулятора. Я подумал, что Поззик мог бы воспользоваться им, узнай мы, как он устроен. К сожалению, Коззл, тамошний штейгер, оказался несколько умнее, чем я полагал.$B$BМожет быть, тебе больше повезет, и удастся получить чертежи. Я знаю, что он хранит их в доме, но скорее всего под замком.', 'Принесите чертежи топливного регулятора барону Ревилгазу из Пиратской Бухты.', 'А теперь, дай-ка я срисую чертежи для личного пользования, а эти отвези Поззику. Не хотелось бы, чтобы он подумал, будто один из спонсоров оставил его без поддержки.', 'Мне не хочется это признавать, но гномская команда очень сильная. Нашим ребятам надо дать пинка, чтобы шевелились.', NULL, NULL, 'Чертежи топливного регулятора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1183, 'Гоблинская поддержка', 'Все должно быть готово. Передай Поззику мои наилучшие пожелания и скажи, что если ему что понадобится, стоит только попросить. Буду ждать вестей о его новых рекордах!', 'Отнесите чертежи топливного регулятора Поззику на Мерцающую равнину.', 'Я надеялся, что он прибудет в готовом виде, зато теперь у нас есть уникальная возможность усовершенствовать конструкцию на этапе сборки. Спасибо, $N. Я нарисую план улучшенного регулятора, сделаю его и установлю.', '$N! Удалось ли отыскать топливный регулятор?', NULL, NULL, 'Чертежи топливного регулятора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1184, 'Части роя', 'Вернитесь к Белгрому в Оргриммар и скажите, что Моктар в Тысяче Игл сделает все, что от него требуется. А еще скажите, что я постоянно учусь и набираюсь знаний. Он будет рад это услышать.', 'Вернитесь к Белгрому Каменной Булаве в Оргриммар. ', 'Я очень ценю ваши усилия, $C. Вождю будет приятно услышать о том, как вы стараетесь для нас.$B$BО, разумеется, я назову ему ваше имя! Он часто говорит со мной и высоко ценит мое мнение.$B$BА теперь ступайте, у меня еще много дел. И если вдруг вы встретитесь с Корраном, и он расскажет вам что-нибудь еще об этих существах – сразу возвращайтесь ко мне. К этой угрозе нельзя относиться легкомысленно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1185, 'А под хитином было...', '', '', 'О, опять ты! В смысле, это ты – а ты, то есть, $N! Да, это ты!Слушай-ка!Та штука, что ты нашел в Силитусе, оказалась книгой. Дневник, написанный на очень древнем диалекте того, что теперь называется дарнассийским. Это займет некоторое время, но я намерен как следует в нем разобраться. Мне показалось, что тебе следует знать, что твоя находка оказалась просто бесценной для Круга.Мать-медведица в восхищении, и все такое!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1186, 'Восемнадцатый пилот', 'Мне сейчас нужно приспособить этот новый регулятор топлива на один из наших болидов, но если вы хотите еще немного помочь нашей команде, поговорите с Раззериком. Это наш пилот, – гм, наш восемнадцатый пилот, если точнее, – и он тоже любит вносить в болид всяческие усовершенствования.$B$BОн, правда, малость двинутый, так что не удивляйтесь, если что.', 'Поговорите с Раззериком на Мерцающей равнине, что в Тысяче Игл.', 'Это ведь вы помогали Поззику, правда? Когда-то я тоже бегал по пит-лейну и выполнял мелкие поручения механиков.$B$BА теперь – взгляните на меня! Я – лучший пилот команды гоблинов!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1187, 'Доработка Раззерика', 'Поззик – отличный механик, это я знаю, но он боится просто прибавить мощности и вырваться вперед! А вот я не боюсь.$B$BПосле того как он закончит работать с болидом, я внесу кое-какие изменения от себя: немного ослаблю ограничители, сниму кое-какие детальки с корпуса и добавлю побольше топлива!$B$BЯ заказал сефориевый ускоритель у Шрива. Он работает в Гизмориуме, в Прибамбасске, но дирижабль, на котором летел мой ускоритель, разбился в Пылевых топях! А мне он нужен, как воздух!', 'Найдите сефориевый ускоритель для Раззерика на Мерцающей равнине.', 'Ты только глянь на эту красотищу! Пятнадцать фунтов чистой сефориевой силы! Как только я прицеплю это к своему болиду, он понесется так, что я обгоню гномов на два круга!', 'И как мне показаться на треке, если у меня нет никакого ускорителя? Это ж ерунда какая-то!', NULL, NULL, 'Сефориевый ускоритель', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1188, 'Безопасность превыше всего', 'Постойте-ка, что это? Шрив оставил включенным режим безопасности. Но это же ограничит мощность, которую я смогу выжать из этого ускорителя! Говорил же я ему, чтобы отключил! Плохо, плохо.$B$BВам придется отнести это в Гизмориум Прибамбасска и заставить Шрива все отключить!', 'Отнесите сефориевый ускоритель Шриву в Прибамбасск, что в Танарисе.', 'Только Раззерик мог по одному взгляду определить, что я поставил сюда предохранитель. Этот ускоритель почти полностью состоит из взрывчатого сефория. Я модифицировал его так, что его мощность будет увеличиваться по мере использования, но Раззерик ведь не успокоится, пока не взорвется вместе со своим драндулетом!', 'Знаете, в Гизмориуме есть все для починки любых механизмов! Чем могу помочь?', NULL, NULL, 'Сефориевый ускоритель (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1189, 'Безопасность превыше всего', 'Вот, я сделал то, что просил Раззерик. Но скажите ему, чтобы он действовал как можно осторожнее: если он допустит хотя бы малейшую ошибку, болид не покатится вперед, а превратится в кучку пепла на треке.$B$BА нам бы совсем не хотелось искать потом девятнадцатого по счету пилота!', 'Верните модифицированный сефориевый ускоритель Раззерику на Мерцающую равнину, что в Тысяче Игл.', 'Так-то лучше! Вот бы увидеть рожи гномов, когда я стартую на этой малышке!$B$BЖалко, что я буду так занят установлением нового рекорда трассы!', 'Ты представляешь, Поззик подсунул мне в болид ведро с песком! Как я могу выжать максимальную скорость, если у меня под сиденьем целое ведро песка?', NULL, NULL, 'Модифицированный сефориевый ускоритель (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1190, 'Только вперед', 'Братья Медноштиф изобрели новый материал для изготовления машин – это единственное разумное объяснение. Их машины ездят быстрее прежнего, но их внешний вид и все остальные параметры ничуть не изменились.$B$BМы точно знаем, что Риззл Медноштиф никогда не расстается с чертежами своего изобретения.$B$BЯ скажу Замеку, чтобы устроил диверсию, – тогда ты сможешь выкрасть планы.', 'Дождитесь, пока Замек устроит диверсию, украдите чертежи Риззла и отнестие их Поззику на Мерцающую равнину, что в Тысяче Игл.', 'Свиток испещрен торопливыми пометками и рисунками, касающимися переработки какого-то сырья.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1191, 'Помеха Замека', '', '', 'Поехали!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1192, 'Индарилиевая руда', '', '', 'Замечательно! Моя команда немедленно начнет работу с необходимыми деталями для следующей гонки!', NULL, NULL, NULL, 'Индарилиевая руда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1193, 'Сломанная западня', '', '', 'Ториевое устройство беспрепятственно встает на место, создавая канал, в который нужно влить масло льда. Как только последние капли масла падают в канал, западня готова к работе.$B$BИ горе неосторожному огру, который подойдет слишком близко!', NULL, NULL, NULL, 'Ториевое устройство', 'Масло льда', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1194, 'Чертежи Риззла', 'В чертежах Риззла описывается процесс переработки индарилиевой руды. Из его каракулей можно понять, что эта руда добывается в недрах Ульдамана в Бесплодных землях.$B$BОстальные записи посвящены теплопроводным свойствам индарилия.$B$BПачка бумаг придавлена каким-то камнем – скорее всего, это и есть необработанная индарилиевая руда.', 'Отнесите образец индарилиевой руды Поззику на Мерцающую равнину, что в Тысяче Игл.', 'Индарилий? Интересно... Если он действительно способен выдерживать такой жар, то мне понятно, почему гоблины так отличились на последней гонке.$B$BБольшое спасибо за этот образец, он мне очень пригодится. Я проведу с ним кое-какие испытания, но для настоящего дела мне потребуется гораздо больше.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1195, 'Священное пламя', 'Кентавры племени Галак в Тысяче Игл хранят один предмет, сохранившийся еще со времен сотворения кентавров.$B$BНам бы хотелось его получить, но для этого нужен фиал воды из одного из лунных колодцев ночных эльфов.$B$BЧтобы набрать воды, тебе надо сначала добыть один из фиалов дриад, что живут близ Приюта в Ночных Лесах в сердце Ясеневого леса. Лунный колодец есть у западного берега реки Фалфаррен, к югу от главной дороги, у которой ты сможешь наполнить фиал.', 'Принесите наполненный гравированный фиал Зангену Каменному Копыту в Громовой Утес.', 'Хорошо. Это как раз то, что просил Рау. Ты можешь отнести ему фиал? Тебе понравится в Иглах, честное слово!', 'Как только у нас будет наполненный фиал, мы отправим его моему помощнику, Рау, в Тысячу Игл. Он-то и просил фиал этой воды, так что ему лучше знать, что с ней делать.', NULL, NULL, 'Наполненный гравированный фиал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1196, 'Священное пламя', 'Отнеси наполненный фиал Рау Скальному Бегуну на Заставу Вольного Ветра на юго-востоке Тысячи Игл. Туда ты можешь добраться на Великом подъемнике, что возле южного обрыва Степей.$B$BНе удивлюсь, если ты и в дальнейшем будешь нам помогать.', 'Доставьте наполненный гравированный фиал Рау Скальному Бегуну на Заставу Вольного Ветра.', 'Хм, да, этот фиал очень пригодится для наших целей. Поскольку дриады и кентавры происходят от одного корня, вода лунных колодцев поможет нам пробить брешь в стене неугасимого огня, что окружает реликвию кентавров.', 'Хм, неужто тебя послал Занген?', NULL, NULL, 'Наполненный гравированный фиал (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1197, 'Священное пламя', 'Водой, которую ты $gпринес:принесла:, можно будет затушить пламя, охраняющее реликвию кентавров. Однако оно погаснет лишь ненадолго, так что тебе придется поспешить.$B$BУтес Треснувшего Копыта – крепость кентавров – находится к северу отсюда. Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утеса.$B$BБудь $gосторожен:осторожна: – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность.', 'Принесите раздвоенное копыто Рау Скальному Бегуну на Заставу Вольного Ветра.', 'От этого копыта исходит странная энергия... Не сомневаюсь, что при его изучении мы узнаем много нового о кентаврах.$B$BБлагодарю вас, $N. Я немедленно приступлю к разгадке тайны, которую вы принесли мне.', 'Жду не дождусь, когда смогу получить это раздвоенное копыто. Вы уже добыли его?', NULL, NULL, 'Раздвоенное копыто', 'Наполненный гравированный фиал', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1198, 'В поисках Талрида', 'В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса.$B$BЯ должен собрать как можно больше сведений для Серебряного Рассвета, чтобы мы могли понять, где и когда нужна наша помощь.$B$BУже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Страж Талрид из ордена Серебряного Рассвета до сих пор не вернулся.$B$BДругие мои разведчики заняты насущными делами.$B$BПомоги мне найти Талрида, $N.', 'Найдите стража Талрида из ордена Серебряного Рассвета в Непроглядной Пучине.', 'Хорошо, что Рассветный дозорный Шедласс прислал вас. В этом испоганенном месте и правда затевается коварный план.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1199, 'Наступление сумерек', 'Черпая силу из старинных обрядов, посвященных Древним Богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.$B$BМы думаем, что Сумеречный Молот в союзе с нагами, и теперь они накапливают силы в Непроглядной Пучине на побережье Ясеневого леса.$B$BЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.$B$BОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.', 'Принесите 10 подвесок сумерек стражу Менадосу из ордена Серебряного Рассвета в Дарнас.', 'Нет сомнений – в тебе течет отважная и благородная кровь, $N. Серебряный Рассвет благодарит тебя за содействие силам добра.', 'В Непроглядной Пучине некогда был древний храм ночных эльфов. Одно время там находился самый мощный лунный колодец. Кто знает, какое зло ныне клубится там, когда храм в руках Сумеречного Молота?$B$BУдалось ли тебе проредить их ряды?', NULL, NULL, 'Подвеска сумерек', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1200, 'Жестокость Черных Глубин', 'Силы оставили меня. Мне необходима твоя помощь!$B$BВ давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный Лунный колодец.$B$BАку\'май, слуга Древнего бога, поднялся из глубин.$B$BСектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку\'май невинные жертвы.$B$BУбей Келриса и принеси его голову Сельгорму в Дарнас, $N.', 'Принесите голову повелителя сумрака Келриса Рассветному дозорному Селгорму в Дарнас.', '', NULL, NULL, NULL, 'Голова Келриса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1201, 'Тераморские шпионы', 'Орда с Альянсом сейчас находятся в состоянии шаткого перемирия. Тайные операции предпринимаются обеими сторонами, и наша обязанность – убедиться, что Орда выйдет из них победителем!$B$BСейчас у нас есть шанс это сделать.$B$BАгенты Альянса заняли позицию к востоку от Деревни Гиблотопь. Они следят за деревней и докладывают о наших действиях в районе Терамора. Мы не станем этого терпеть.$B$BТвоя задача – выследить этих шпионов и убить их. Этим мы ясно дадим понять их начальству, что не допустим шпионить у себя под носом.', 'Убейте 9 тераморских шпионов, потом вернитесь к Назиру Кровавому Копью в деревню Гиблотопь.', 'Отличная работа. Их шпионы хитроумны, но недостаточно, чтобы спастить от всевидящих глаз Орды.', 'Ты нашел шпионов, $N?', NULL, NULL, 'Тераморский секретный агент убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1202, 'Доки Терамора', '$N? Мы посылали двоих разведчиков украсть бумаги с корабля в одном из тераморских доков. Они добыли их, но были обнаружены, и им пришлось выбросить добычу в море.$B$BОдному из них удалось сбежать, но поднять документы со дна он не смог. Теперь я поручаю эту задачу тебе.$B$BБумаги лежат в сундучке, на дне моря возле тераморских доков. Найди их, $N, и принеси мне.', 'Принесите документы капитана Назиру Кровавому Копью в Деревню Гиблотопь.', 'Браво, $N. Это было нелегко, но документы, которые ты добыл – весьма ценны.', 'Ты нашел документы, $N? Информация содержащаяся в них, жизненно важна для Альянса, а значит необходима разведке Орды.', NULL, NULL, 'Бумаги капитана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1203, 'Ярлу нужен клинок', 'Мне предстоит жестокая рубка. С кем, я тебе сказать не могу, но вот то, что мне для этого просто необходим добрый клинок, это к гадалке не ходи. Некоторые называют его меч, а я зову пляшущий клинок.$B$BПоможешь мне, а? Эти рыболюди, мурлоки или как их там... ну те, что живут к северу отсюда на побережье. Среди них есть один, они зовут его Костяная Чешуя, так вот он носит неплохой клинок. Он-то мне и нужен!$B$BГлавное, поторопись, то что я собираюсь рубить, ждать не станет...', 'Принесите меч Костяной чешуи Ярлу \"Болотному Глазу\" в сторожку \"Болотный огонек\".', 'Это хороший клинок... Он хорошо танцует, – стал быть, это – хороший танцующий клинок! Спасибо-спасибо-спасибо!!! Таак. Теперь я его испробую...$B$BПозже. Я испробую его позже. Но все равно спасибо тебе!', 'Ты достал мне клинок?', NULL, NULL, 'Меч Костяной Чешуи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1204, 'Суп из глинистой черепахи с крабами', 'Я тут работаю над новым блюдом, оно будет называться \"Суп из глинистой черепахи с крабами\". Мне все еще не хватает основных ингредиентов, но я не уверен, что перенесу еще одну прогулку по Пылевым топям. $N, ты не окажешь мне услугу? Прежде всего, мне нужны языки глинистых черепах. Они водятся на побережье, в основном вокруг залива.$B$BНо мне не всякие языки сгодятся – я слышал, что у некоторых из этих черепах языки раздвоены. $B$BВот они-то и обладают тем непередаваемым вкусом, которым я хочу порадовать своих клиентов.', 'Принесите 8 раздвоенных языков глинистых черепах Моргану Штерну в Терамор.', 'Отлично! Благодарю тебя, $N!$B$BТеперь надо подумать, как именно приготовить эти языки, чтобы наилучшим образом подчеркнуть их изысканный вкус.$B$BНаконец-то у меня есть блюдо, достойное завсегдатаев \"Печального отшельника\" в Штормграде.', 'Ну как? Удалось добыть необходимые мне языки?', NULL, NULL, 'Раздвоенный язык глинистой черепахи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1205, 'Волокун', 'Волокун – старый кроколиск из Пылевых топей. Ему давно уже пора сдохнуть.$B$BСкрипя старыми костями он волочет свою огро$Nю тушу по болоту. Хотя он все еще движется с силой и скоростью молодого животного, его неугасимый пламенный дух уже износил свое дряхлое тело.$B$BТы $gдолжен:должна: освободить его от этой боли, $N. Дай ему покой.', 'Принесите зуб кроколиска Волокуна Мелору в Громовой Утес.', 'Отлично, $N. Я уверен – это было нелегкое испытание, но я рад, что мучения кроколиска наконец-то прекратились.', 'Ты добыл зуб Зыбуна, $N? Удалось ли тебе прекратить страдания этого существа?', NULL, NULL, 'Зуб Волокуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1206, 'Ярлу нужны глаза', 'Глазной сок очень вкусный, жаль только что большинство живых существ имеет всего по два глаза.$B$BНо вот у пауков их уже больше, гораздо больше. А сок из глаз пауков Мглистой пещеры обладает особенным мягким вкусом. Целехонькие паучьи глазки... прям уже чую их на языке.$B$BЭти пауки водятся к пещере к западу отсюда. Вот как ты думаешь, это пауки были названы по своей пещере или наоборот?', 'Принесите 20 целых глаз пауков Мглистой пещеры Ярлу \"Болотному Глазу\" в сторожку \"Болотный Огонек\".', 'Ты принес вкусные глазки... Паучьи глаза чисты как слеза. $B$BИх едят, а они глядят…$B$BВот те, что глядят, съешь последними, а то на болотах-то другой компании и нет.$B$BПривет, глазки мои маленькие, привеет! На вкус лучше курочки, с солью, с приправками...$B$BМмм...', 'Ну и где мои глаза?', NULL, NULL, 'Целый глаз паука Мглистой пещеры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1218, 'Лягушачьи лапки', 'Обожаю готовить! Аппетитные болотные блюда, жареные лягушачьи лапки и все в этом роде...$B$BТолько вот лапки у меня закончились. А в поместье лягушек как раз полно. Причем огромных. Может, принесешь мне их лапок? Ничего сложного, правда. Просто хорошенько дай лягушке по голове и неси мне лапки.$B$BА я их тут потушу, поперчу и с тобой поделюсь.$B$BЛюбишь лягушачьи лапки?', 'Принесите 10 лапок болотных лягушек Ярлу \"Болотному Глазу\" с Пылевых топей.', 'Ага, вот и специи. Вот теперь жабятина вполне готова.', 'Специи. Без них жизнь была бы совсем пресной, как думаешь?', NULL, NULL, 'Лапка болотной лягушки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1219, 'Орочье донесение', 'Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. $B$BДонесение написано на орочьем... И по виду важное...', 'Доставьте донесение шпиона лейтенанту Адену в Терамор.', 'Хм... Я не силен в орочьем, но это похоже... на отчет шпиона!', 'Вы что-то хотите мне сообщить?', NULL, NULL, 'Донесение шпиона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1220, 'Капитан Ваймс', 'Капитан Ваймс должен увидеть найденное тобой орочье донесение, $N. Он знает орочий язык, лучше чем кто либо из нас, и он должен быть осведомлен о том, что вблизи Терамора рыщут шпионы Орды.$B$BТы найдешь капитана в казармах в северо-восточной части острова Терамор.', 'Принесите шпионское донесение капитану Гаррану Ваймсу.', 'Донесение орочьего шпиона! Как тебе удалось его раздобыть? Впрочем, неважно, – давай-ка посмотрим, о чем там говорится...', 'У тебя что-то есть для меня?', NULL, NULL, 'Донесение шпиона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1221, 'Корни Синелиста', 'Корень синелиста – признанный деликатес в любом уголке мира! Но растет он только здесь, в Степях, глубоко под землей в Лабиринтах Иглошкурых.$B$BК тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землей. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!$B$BЗадачка, конечно, непростая, но если принесешь мне корней, я хорошо заплачу.', 'Возьмите ящик с дырками.Возьмите палочку-погонялочку для шмыгуносов.Возьмите справочник по шмыгуносам. В Лабиринтах Иглошкурых выпустите шмыгуноса и воспользуйтесь стеком, чтобы он начал искать корни. Принесите 6 корней синелиста, стек и ящик с дырками Мебоку Миззриксу в Кабестан.', 'Прекрасно! О, я загоню их перекупщикам за очень хорошую цену! $B$BСпасибо за работу, $N. Ты вполне надежный поставщик!', 'Ну что, принес корни, $N?', NULL, NULL, 'Корень синелиста', 'Ящик с отверстиями', 'Справочник владельца Шмыгуноса', 'Палочка-погонялочка для шмыгуносов');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1222, 'Побег Вонючки', 'Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!$B$BНе могу отбиться от тутошнего зверья, а ты, $gпарень:подруга:, как раз мне в этом и поможешь.$B$BПовар Морган Штерн составляет рецепт нового блюда, и он послал меня сюда на поиски листьев болотного боба. Он, похоже, думает, что они вкусные.$B$BКак бы то ни было, пока я искал эти самые листья... меня окружили! Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать эти бобы!', 'Сопроводите \"Вонючку\" Игнаца, затем пообщайтесь с Морганом Штерном в Тераморе.', 'Мистер Игнац не так давно приносил листья болотного боба, и он расказал мне, что вы помогли ему выбраться из весьма затруднительной ситуации.$B$BБлагодарю вас, $N. Я попрошу своего дядю принять вас по-королевски, когда вы в следующий раз окажетесь в \"Синем отшельнике\", в Штормграде.', NULL, NULL, NULL, 'Помогите Вонючке найти листья болотного боба.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1238, 'Потерянный рапорт', 'Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. $B$BЭто донесение шпиона, который провел многие недели в Тераморе.$B$BРасшифровав его, мы выяснили, что это донесение должно быть доставлено командиру орков-разведчиков в Деревню Гиблотопь.', 'Отнесите донесение шпиона Назиру Кровавому Копью в Деревню Гиблотопь.', 'Отлично, $N. Наш агент Марг Ночной Соглядатай был отправлен на разведку в Терамор.$B$BЭто его последний рапорт и, видимо, уже окончательно последний – судя по твоим словам, я боюсь, Марг навсегда остался в болотах...', 'У тебя что-то есть для меня?', NULL, NULL, 'Донесение шпиона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1239, 'Отрубленная Голова', 'Стоило копнуть чуть глубже, и из земли показалась отрубленная голова орка. На его лице застыл оскал, а в темных глазах – вызов.', 'Принесите голову строптивого орка Назиру Кровавому Копью в Деревню Гиблотопь.', 'Это голова Марга Ночного Соглядатая! Этого-то я и боялся. Посмотри на эту рану у него на шее, – как думаешь, это какое-то оружие, или он пал от клыков и когтей какого-то зверя? $B$BМы должны выяснить это, $N. Выяснить, не является ли его смерть делом рук Альянса.', 'У тебя для меня еще что-то есть, $N?', NULL, NULL, 'Голова строптивого орка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1240, 'Тролль-знахарь', 'Мы должны выяснить обстоятельства смерти Марга! И единственный способ это сделать, $N, – воспользоваться магией троллей. $B$BОтнеси голову Марга Кин\'вилаю в лагерь Гром\'гол в Тернистой долине.$B$BКин\'вилай – самый могущественный из знахарей племени Черного Копья, если кто-то и сможет вызвать дух Ночного Соглядатая – то это он.', 'Принесите голову строптивого орка Кин\'вилаю в лагерь Гром\'гол в Тернистой долине.', 'Да, теперь я вижу. Дух Марга застрял в нашем мире, потому что его задание не было завершено.$B$BНу что ж, давай поговорим с этим сердитым орком...', 'Рядом с тобой вьется очень сердитый дух, брат. Что привело тебя к Кин\'вилаю?', NULL, NULL, 'Голова строптивого орка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1241, 'Пропавший дипломат', 'Некоторое время назад один из наших дипломатов был отправлен в Терамор для встречи с Джайной Праудмур. Он не вернулся.$B$BЯ подозреваю, что к этому приложило руку Братство Справедливости, но уверенности у меня пока что нет. Пока что нам удается скрывать факт исчезновения дипломата, но так продолжаться не может.$B$BАгенты королевской службы рыщут по городам, но я хочу задействовать и свои связи.$B$BНа аллее Героев ты найдешь моего старого друга, его зовут Йорген. Передай ему эту записку и во всем его слушайся.', 'Найдите Йоргена в Штормграде.', 'Хм-м... *Йорген смотрит на вас, прищурившись.*$B$BХорошо. Придется вам помочь, хоть и не очень-то хочется. Долг есть долг.$B$BИ запомните одну простую вещь: вы знаете куда больше, чем уместно в вашем случае. Храните наши маленькие секреты и не болтайте по тавернам о том, что обнаружите. Ясно вам?', 'Хм-м, ну, надеюсь, у вас есть действительно достойный повод оторвать меня от рыбалки. Я не подаю нищим и не покупаю ничего у разносчиков...', NULL, NULL, 'Письмо Йоргену (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1242, 'Пропавший дипломат', 'Возьмите записку для Иллинга Триаса. Ничего ему не рассказывайте, просто ведите себя вежливо и дождитесь ответа; не волнуйтесь, Триас ответит.$B$BЕще раз напоминаю вам, $N: дело серьезное, так что держите рот на замке.$B$BТриаса вы найдете в его магазине в Торговом квартале; магазин называется \"Сыры Триаса\". Удачи!', 'Доставьте запечатанную записку Йоргена Иллингу Триасу в Штормград.', 'Извините, письмо мне? О... не так уж часто мне приходится получать что-то, кроме ящиков и бочонков, я ведь занят делом. Ну, давайте посмотрим, что там.$B$B*Открывая письмо, Эллинг смотрит на вас.*$B$B$N, вы выглядите возбужденно, с вами все в порядке?', 'Здравствуйте, $N. Могу ли я чем-нибудь вам помочь? Не хотите ли отведать \"Чеддер Триаса\"? Или кусочек \"Дарнассийского блю\"?', NULL, NULL, 'Запечатанная записка Эллингу (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1243, 'Пропавший дипломат', 'Йорген, ах ты старый мерзавец... Ну и что со всем этим делать?$B$BЛадно, я разберусь... Да чтоб ему в Круговерть Пустоты угодить раньше времени!$B$BНу что, $N, займемся делом? Я задействую все свои контакты, но тебе придется побегать.$B$BОтправляйся в поселение Темнолесье, которое находится в Сумеречном лесу, и найди там дозорного Бакуса; он обычно патрулирует северную дорогу за городской стеной. Просто скажи ему, что Братство Справедливости опять зашевелилось, а ты присматриваешь за ним по моей просьбе – и он тебе поможет, чем сможет.', 'Отнесите запечатанное письмо дозорному Бакусу в Сумеречный лес.', 'Вас послал Триас, да? Другое дело...$B$BМожете гонять чудовищ, сколько вам заблагорассудится. Уверен, что для вас это не составит особого труда, какой бы ужас ни вылез на вас из сумерек...$B$BТак чего же желает мой дорогой друг в этот пасмурный день?', 'По этим лесам путешествовать небезопасно, $N. Будьте осторожны, и если приметите опасность – немедленно обращайтесь к Смотрящим. Не пытайтесь разобраться самостоятельно. Иначе помощь может прийти слишком поздно...$B$BВпрочем, мы оба знаем, что вы плюнете на мои предупреждения и будете сражаться со всем, что выползет из сумерек, верно? Я знаю таких, как вы – настоящих приключенцев...', NULL, NULL, 'Запечатанная записка дозорному Бакусу (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1244, 'Пропавший дипломат', 'Опять Братство?! Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой.$B$BКстати, сейчас я вспомнил, что последнюю пару недель их агенты так и кишат вокруг участка Эддла. Это подозрительно – должно быть, назревает какая-то крупная заварушка.$B$BНе хочешь поискать там и выяснить, в чем дело?$B$BФерма находится к югу от дороги из Западного края как раз на входе в Сумеречный лес.', 'Найдите декларацию Братства Справедливости и верните ее дозорному Бакусу в Сумеречном лесу.', 'Вы вернулись, не вляпавшись ни в какие неприятности. Это само по себе достижение, не правда ли?$B$BНу, покажите, что принесли? Да, очень похоже на официальные документы Братства Справедливости. Но это может быть и подделкой, которую вам подсунули, чтобы одурачить и сбить со следа.', 'Будьте осторожнее, $N. Хоть вас и прислал сюда Триас, но это не значит, что все чудовища из чащоб будут к вам благосклонны. Особенно учитывая, что ваше расследование связано с Братством Справедливости.', NULL, NULL, 'Декларация Братства Справедливости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1245, 'Пропавший дипломат', 'О-ох, для обычной попытки ввести в заблуждение это слишком сложно. Отнесите этот документ Триасу, пусть поразмыслит над ним. И никому больше об этом не говорите. Кажется, это дело ни мне, ни ему не по плечу. Ну, посмотрим...$B$BИ, пожалуйста, $N, никому не говорите, что я вам помог. Если мое начальство поймет, что я о чем-то узнал и не поделился с ними, они могут меня запросто повесить.', 'Отнесите декларацию Братства Справедливости Иллингу Триасу в Штормград.', 'Да-а... весьма интересно. Йорген и Делавей молодцы, что навели меня на это.$B$BКажется, Братство Справедливости всерьез взялось за воплощение своих планов. Хм, а это что? \"Кулак\"? Знакомое имя...', 'Ой, да вы вернулись, и целиком, а не кусками в посылке! Разумеется, вы не за сыром явились, так давайте сразу перейдем к делу! Помог ли вам Бакус, или в Сумеречном лесу вы ничего не нашли?', NULL, NULL, 'Декларация Братства Справедливости (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1246, 'Пропавший дипломат', 'Вот что я об этом думаю... Дашель... Какой-то Дашель... Как его фамилия? Кулак! Дашель Каменный Кулак! В некоторых кругах его зовут просто Кулак, наверняка потому, что он не дурак подраться...$B$BЕго можно найти в Старом городе, прямо в центре. Поговорите с ним. Если понадобится, используйте меч или любой подручный тяжелый предмет, чтобы урезонить его, и не сомневайтесь. Если он так завязан в заговоре, как можно заключить по этим бумагам, то не расстанется с информацией по доброй воле...', 'Поговорите с Дашелем Каменным Кулаком в Штормграде.', 'Что?!$B$BМои дела тебя не касаются, ясно? Проваливай, нечего тебе здесь вынюхивать!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1247, 'Пропавший дипломат', 'Ну... м-м... да... Я кое-что знаю о встрече на участке Эддла. Она произошла несколько недель назад. Меня туда не приглашали, мое участие закончилось с провалом плана А, будь прокляты эти чертовы искатели приключений...$B$BПарень, с которым связан план Б, пришел из Менетила. Его зовут Пронырой. Это все, что мне удалось узнать из запасного плана.', 'Поговорите с Иллингом Триасом в Штормграде. ', 'О, $N, приятно видеть вас в живых. Значит, с Дашелем все прошло хорошо?$B$BЯ тут еще раз перечитал их планы, и хотя в тексте не упоминается имя дипломата, которого они преследовали, речь идет о плане Б, который вступил в действие после провала первой попытки захватить его.$B$BЭтот Проныра, о котором упомянул Дашель, кажется, не имеет другого имени – непонятно, кто он; но нам хотя бы известно, что он из Менетила.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1248, 'Пропавший дипломат', 'Один из моих знакомых переехал в Болотину, в портовый город Менетил. Думаю, что он поможет вам, если вы передадите ему привет и скажете, что работаете на меня. Зовут его Михаил; перед отъездом он говорил, что хочет стать барменом.$B$BПоговорите с ним, найдите этого Проныру и попробуйте разузнать еще что-нибудь насчет похищенного дипломата. Мы должны узнать, где его держат или хотя бы имя похищенного. Увы, в декларации ничего не говорится о том, что похитители собираются сделать с пленником после захвата.', 'Поговорите с Михаилом в Болотине.', 'Привет-привет, дорогой $N. Рады вас видеть. Не желаете ли эля? Или баранины?$B$BСкажите, чего бы вам хотелось, и я постараюсь выполнить все ваши пожелания. Меня зовут Михаил, я буду рад услужить вам.$B$BЭ? Что это? Триас? Прошу вас, говорите потише. Моим посетителям не обязательно слышать, о чем мы с вами говорим.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1249, 'Пропавший дипломат', 'Значит, вас послал Эллинг? О, это повод десятикратно умножить мое гостеприимство! Просите всего, чего пожелаете, постараюсь выполнить любую вашу просьбу!$B$BХм-м, Проныра, говорите? Не скажу, что мне знакомо это имя, но постараюсь что-нибудь разведать...$B$B$N, не оборачивайтесь прямо сейчас, но вон тот господин около двери слишком внимательно смотрит на нас и прислушивается к нашему разговору. На вашем месте я бы попробовал изловить его прежде, чем он уйдет отсюда.', 'Перехватите Яна Тапоке до его ухода и вернитесь к Михаилу.', 'Поймали его, да? Отлично! Знаете, а ведь это и есть тот самый Проныра! Я и сам удивился.$B$BДа, не думал я, что буду так скучать по всяким тайным расследованиям и азартным погоням. Верно говорят: сколько волка ни корми... Только не обмолвитесь про это Эллингу – он наверняка потащит меня обратно в Штормград, узнав, что я затосковал по былым денькам.$B$BХорошо, что мне удалось оказать вам хотя бы небольшую услугу во время вашего пребывания в Менетиле. Если еще что-нибудь понадобится, просто попросите.', NULL, NULL, NULL, 'Победите Яна Тапоке.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1250, 'Пропавший дипломат', 'Братство Справедливости не столько мне платит, чтобы за них умирать. Они похитили короля. Да, настоящего короля Штормграда, а не какого-то там дипломата. Он направлялся в Терамор, чтобы побеседовать с Джайной Праудмур, это большая тайна и дело тоже нешуточное. Но тут встряло Братство, у них был свой осведомитель.$B$BВ мои задачи входило только взять их человека на борт королевского корабля, когда он стоял у пристани. Парня звали Хендел, клянусь, это все, что я знаю!', 'Поговорите с Михаилом в Болотине.', 'КОРОЛЬ?! В смысле... король? Настоящий король? Вы шутите? Вы же не имеете в виду, что вы разыскиваете похитителей короля?! Я даже не в курсе, что он пропал. Теперь ясно, почему сейчас в Штормграде всем заправляет его сын.$B$BЯ прямо сейчас напишу Эллингу. Он должен знать, что вы встали на след.$B$BМне и в голову не приходило, что Джан может предать наш Штормград за деньги, пусть и немалые. Даже у вора должна быть честь!$B$BТеперь главное – найти этого Хендела – думаю, тут я могу помочь...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1251, 'Черный щит', 'Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остатках камина – только это и осталось от таверны \"Последний привал\".$B$BЩит можно снять.', 'Прнинесите почерневший железный щит Крогу в Деревню Гиблотопь.', 'Люди всегда отличались странными вкусами в области украшательства. Но на кой вешать над камином простой металлический щит? Может, его повесили туда те, кто спалил таверну?$B$BПредупреждение? Угроза?', 'Что это у тебя там, $N? Вещественное доказательство с руин \"Последнего привала\"?', NULL, NULL, 'Вороненый железный щит (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1252, 'Лейтенант Павал Рит', 'Солнечный зайчик блеснул в глаза из-под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$B$BПод якорем выбито имя владельца: \"Лейтенант Павал Рит\".', 'Принесите бляху Рита капитану Гаррану Ваймсу в Терамор.', 'День, когда мне приносят бляхи погибших стражей, светлым не назовешь. $B$BИногда они гибнут в битве, и мне приходится сообщать об их участи семье и близким... Иногда мы так и не знаем, что с ними сталось. А иногда знаем, и это еще хуже...', 'Ну как успехи с этой таверной? Удалось что-нибудь найти?', NULL, NULL, 'Бляха Рита (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1253, 'Черный щит', 'Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остатках камина – только это и осталось от таверны \"Последний привал\".$B$BЩит можно снять.', 'Принесите почерневший железный щит капитану Гаррану Ваймсу в Терамор.', 'Хмм... Я в устройстве оружия и доспехов не разбираюсь, я ими пользуюсь. $B$BЩит как щит, разве что огнем опалило.', 'Ты выяснил, что произошло с этой таверной?', NULL, NULL, 'Вороненый железный щит (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1258, '…с крабами', 'Еще один компонент моего нового рецепта – клешни гигантского краба. К сожалению, те которые водятся в Пылевых топях, – грязнокрабы, не годятся... Зато те, что живут на Болоте Печали, – в самый раз!$B$BОболочка клешни – важный элемент украшения блюда, поэтому они мне нужны целые и непоцарапанные. К сожалению, у краба всего две клешни, а то и одна, а мне для моих кулинарных экспериментов их нужно гораздо больше. Так что насчет небольшой прогулки, $N?', 'Принесите 12 безупречных крабьих клешней Моргану Штерну в Терамор.', 'Прекрасные экземпляры, $N. На самих клешнях ни царапинки, а мясо как и положено, розовое и нежное. У вас несомненный талант к этому делу! Не задумывались о карьере шеф-повара?', 'Я придумал чудесное блюдо из языков илистых черепах. Надеюсь, ваша охота прошла удачно?', NULL, NULL, 'Нетронутая крабья клешня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1259, 'Лейтенант Павал Рит', 'Лейтенант Павал Рит? Не припоминаю такого имени. Лучше всего вам будет поговорить с адъютантом Тезораном. У него хранятся все записи о тераморских стражниках – от их имен до предпочитаемого вооружения.$B$BУж он-то расскажет вам об этом Павале Рите.', 'Поговорите о Рите с адъютантом Тезораном в Тераморе.', 'Здравствуй, $N. Так тебе нужна информация об одном из нас? Как его бишь, Рит?$B$BСейчас проверю по своим записям.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1260, 'Морган Штерн', 'Я составляю новое меню для ресторана. Сельская кухня с болотным душком. Думаю, посетителям \"Синего отшельника\" понравится!$B$BЯ послал своего племянника Моргана в Терамор, город на краю Пылевых топей. Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи.$B$BДолог путь до Терамора, и для меня тяжеловат. Но я думаю, что $gтакой молодой:такая молодая: $C с радостью ухватится за возможность совершить подобное путешествие.', 'Поговорите с Морганом Штерном в Тераморе.', 'А! Так вас послал мой дядя?$B$BНу что ж, я тут собирал для него рецепты и добился определенных успехов, но мне нужна помощь. $B$BНадеюсь, вы не боитесь ноги промочить?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1261, 'Марг говорит', 'Ах ты, проклятый грязнокраб! Ты меня не достанешь! Ой, да я ж покойник! Видать, он все-таки достал меня.$B$BА как же моя миссия?! Ты, $N, $gдолжен:должна: закончить ее. Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора. На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить.$B$BТой ночью я пробрался в лагерь и украл эту подвеску. Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня!$B$B$N, ты $gдолжен:должна: найти эту тварь и вернуть подвеску.', 'Принесите изукрашенную Подвеску Назиру в Деревню Гиблотопь.', 'Эта подвеска была на солдате Штормграда??$B$BБлагодарю тебя, $N, за то, что раскрыл загадку смерти Марга. Но эта подвеска... Это новая загадка. И, возможно, она несет угрозу и Орде и Альянсу.', 'Ты выяснил, что случилось с Маргом?', NULL, NULL, 'Изукрашенная подвеска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1262, 'Сообщение для Зора', 'Странно, что украденная Маргом была у простого солдата. Возможно ее владелец маскировался, или, что вероятнее, солдаты сами ее стащили. $B$BЧто бы там ни было, эта подвеска принадлежала лицу благородного происхождения, и мы должны найти ее хозяина, если хотим разрешить эту загадку.$B$BОтнеси эту подвеску Зору Одинокое Дерево в Оргриммар. Он хорошо разбирается в интригах Альянса и, возможно, он в курсе, если эта подвеска известна в Штормграде.', 'Отнесите изукрашенную подвеску Зору Одинокому Дереву в Оргриммар.', 'Эта подвеска сделана удивительно тнокой и искусной работы, $N. Орку такое не нужно, но многие люди головы бы не пожалели за такую драгоценность.$B$BЯ изучу эту подвеску повнимательнее. Будем надеяться что в свое время мы все про нее узнаем.', 'Ты шел сюда аж из Деревни Гиблотопь, что в Пыльной трясине? Как там поживает Назир, как его дела?', NULL, NULL, 'Изукрашенная подвеска (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1263, 'Сожженная Таверна', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1264, 'Пропавший дипломат', 'В начале каждого месяца стражи бухты Кул-Тираса получают жалованье и отправляются прочь из Терамора в отпуск. Многие из них приходят сюда - выпить, гульнуть, пообщаться с женщинами. Одна из таких компаний регулярно приходит в эту таверну. Мне кажется, что и этот Хендел был среди них.$B$BКомандир Самаул из Терамора может вам помочь в поисках Хендела, если тот до сих пор там. Самаул всецело верен леди Джайне, но если вы упомянете при нем имя Эллинга, то его помощь может оказаться весьма... сдержанной.', 'Найдите командира Самаула в Пылевых топях.', 'Рад встрече, $N. Я – командир Самаул, состою на службе в гвардии леди Джайны Праудмур в Тераморе.$B$BХотя я немного занят, вы можете задавать мне любые вопросы, которые вас интересуют. Не сочтите за повод для обиды, но я попрошу вас высказаться по возможности лаконично.$B$BНадеюсь, что вы проявите должную осторожность, если соберетесь за пределы города. Там, снаружи – огры, орки и мурлоки, а в южной части болота обитают черные драконы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1265, 'Пропавший дипломат', 'Хендел? Да, я его знаю, но почему вас интересуют мои солдаты?$B$BЭллинг отправил вас разыскать его? Звучит как-то странно. Эллинг не послал бы вас ко мне, если бы все было в порядке. Вы можете хранить свои секреты сколько угодно, только имейте в виду: мой долг – охранять эти земли. Если ваша деятельность может нарушить порядок, лучше сообщите заранее.$B$BДумаю, что Хендела вы найдете в первой по счету от Терамора башне. Будьте осторожны.', 'Обыщите сторожевой пост, чтобы найти следы рядового Хендела.', 'Человека, известного вам как Хендел, здесь нет. Все остальное, что можно узнать от леди Праудмур, я думаю, вы уже знаете. Она просила меня найти вас и оказать вам помощь в расследовании. Если вы готовы принять мои услуги, я сообщу вам, где можно найти рядового Хендела. Вдвоем мы сможем предать его в руки правосудия.', 'Да, $N?', NULL, NULL, 'Исследовать локацию', 'Обследовать сторожевой пост', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1266, 'Пропавший дипломат', 'Рядовой Хендел находится к западу отсюда, в составе гвардии, охраняющей тераморских разведчиков во время отдыха. Они пытаются выяснить местоположение деревни Гиблотопь, базы Орды, а заодно и приглядывают за нашими границами.$B$BВы найдете его без труда, просто поищите в палатках у дороги.$B$BУ меня есть и другие дела, но я догоню вас так быстро, как смогу. При необходимости вы сможете найти меня в башне леди Праудмур.', 'Найдите рядового Хендела в Пылевых топях.', 'Добрый день. Это опасное место для горожанина. Если вы цените свою жизнь, не стоит находиться здесь слишком долго.$B$BЗадавайте вопросы быстро, попробую вам помочь. Только смотрите по сторонам, не покажутся ли огры. По слухам, поблизости база Орды. Разведчики пытаются найти ее, но это дело небыстрое. Мы еще не добились успеха.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1267, 'Пропавший дипломат', '', 'Поговорите с леди Джайной Праудмур в Пылевых топях.', 'Сначала позвольте вас, $N, поблагодарить за все, что вы уже сделали. Вы оказали неоценимую услугу моим людям и всем обитателям Штормграда. Жаль, что наше знакомство не состоялось при более благоприятных обстоятельствах.$B$BНадеюсь, вы понимаете, что я не имею возможности публично выразить вам свою признательность, но знайте, что она поистине безгранична...$B$BВо время следующего визита в Терамор разыщите меня и я сделаю для вас все, что смогу.$B$B$N, позвольте еще раз поблагодарить вас.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1268, 'Подозрительные следы копыт', 'Цепочка следов уходит от все еще дымящегося остова таверны \"Последний привал\". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.', 'Доложите о подозрительных следах возле таверны \"Последний привал\" Крогу из деревни Гиблотопь.', 'Следы копыт... Это может быть иглогрив, или даже кентавр. То, что они пришли в Степи, что-то да значит, и, сдается мне, они вполне способны сжечь таверну.$B$BК тому же кто бы это ни был, они не только сожгли здание, жена и детеныш владельца были убиты. Плохо дело... $B$BЛадно, я пошлю Кагоро посмотреть куда ведут следы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1269, 'Лейтенант Павал Рит', 'Солнечный зайчик блеснул в глаза из под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$B$BПод якорем выбито имя владельца: \"Лейтенант Павал Рит\".', 'Принесите бляху Рита Крогу в деревню Гиблотопь. ', 'Я знаю этого человека, Павала Рита. Жалкий даже по меркам собственного племени. Покинул своих товарищей и теперь скрывается в лесу. $B$BЯ послал Огрона выследить его. Некоторые подозревают, что он крал припасы. Я видел что Огрон направляется на юго-восток.', 'Удалось найти хоть какие-то намеки на то. Что случилось в таверне \"Последний привал\"?', NULL, NULL, 'Бляха Рита (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1270, 'Побег Вонючки', 'Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!$B$BНе могу отбиться от тутошнего зверья, а ты, $gпарень:подруга:, как раз мне в этом и поможешь. Гоблину из Кабестана по кличке Мебок Миззрикс нужны листья болотного боба для зелья или еще какой надобности, – меня это, честно говоря, не колышет: он неплохо платит, а я неплохо знаю болота, потому и впрягся.$B$BВот только не успел я еще найти эти листья, как меня уже окружили. Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать для Мебока эти листья.', 'Сопроводите \"Вонючку\" Игнаца, затем пообщайтесь с Мебоком Миззриксом в Кабестане.', 'Вонючка недавно приносил тут мне травки, и он расказал, что ты помог ему выпутаться из мерзкой ситуации. Хорошая работа! Друг Вонючки и мой друг.$B$BПеред тем как вернуться обратно на болота, он просил передать тебе это, если мы вдруг увидимся.', NULL, NULL, NULL, 'Помогите Вонючке найти листья болотного боба.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1271, 'Праздник в \"Печальном отшельнике\"', '', '', 'Мой племянник сказал, что ты помог ему с его поисками в Пыльной трясине, а заодно и вытащил его компаньона из неслабой передряги. Мы, Штерны, держимся друг дружки и не забываем наших друзей!Так что мой руки, $N, сегодня пируем в твою честь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1272, 'Найти Рита', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1273, 'Допрос Рита', 'Это было непросто, но я все-таки нашел этот Рит. Неплохо он прятаться... Для человек. $B$BОгрон боится, что человек свихнуться, – слишком много времени на болоте, Твоя идти с Огрон и спрашивать человека все, что хотеть.', 'Пойдите с Огроном и поговорите с Ритом, потом вернитесь к Крогу в Деревню Гиблотопь.', 'Пфф. Это хорошо, что Рит больше не будет прятаться на болоте, но это плохо, что люди такие хрупкие существа, что могут помереть от одной маленькой стрелы.$B$BСдается мне, что мы зашли в тупик и нужно поискать разгадку где-нибудь еще.', NULL, NULL, NULL, 'Вместе с Огроном допросите Рита.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1274, 'Пропавший дипломат', 'Простите, $gсэр:мадам:. Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства.$B$BЕсли вы без лишнего шума проберетесь в Крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь. Прошу вас, храните это в тайне, ибо все это дело большой важности.', 'Найдите епископа Делавея в Крепости Штормграда. ', 'Здравствуйте, $N. Я – епископ Делавей.$B$BДайте-ка, я угадаю, почему вы здесь! Наверняка потому, что откликнулись на просьбу юного Томаса, который предложил вам оказать мне услугу. Он всегда стремится помочь мне.$B$BБоюсь, я еще не успел все сформулировать, так что простите мне некоторую невнятность изложения... И, прошу вас, храните все это в тайне.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1275, 'Исследование порчи', 'Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?$B$BЯ боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить еще одну расу злобных монстров.$B$BЯ хотел бы изучить ствол мозга сатиров и нагов, чтобы понять, на что обрекают себя эльфы крови. И сатиров, и нагов вы найдете в Непроглядной Пучине, на побережье Ясеневого леса.$B$BПуть неблизкий, $N.', 'Гершал Шепот Ночи в Аубердине хочет, чтобы вы принесли ему 8 оскверненных стволов мозга.', '', NULL, NULL, NULL, 'Оскверненный ствол мозга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1276, 'Черный щит', 'А, вспомнил! Мозарн – знаменитый кузнец из Громового Утеса. Я же помню, что слышал это имя прежде!$B$BЕсли мне не изменяет память, Служители Земли наградили меня оружием его работы, хорошее было оружие.$B$BВозможно, он расскажет тебе больше о щите, вышедшем из его рук.$B$BЯ не уверен, что эта информация важна, но, поскольку мы так и не знаем ничего о Рите, пренебрегать ей было бы неразумно.', 'Покажите потемневший железный щит Мозарну из Громового Утеса.', 'Да, ты прав Это моя работа.$B$BПравда, боюсь, что это все, что я могу тебе рассказать о нем, $N. Из моих рук вышло столько щитов и прочего оружия, что вряд ли я смог бы запомнить их все.', 'Привет, $C. Я могу чем-то помочь?', NULL, NULL, 'Вороненый железный щит (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1281, 'Песня Джима', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1282, 'Зовут его Улыбка Джим', 'Вот хоть тресни – жаль мне старину Джима! Он ведь не всегда был таким. Держал таверну на болотах... отличное было местечко.$B$BСлушай, я не очень-то хочу все это вспоминать. Если тебе так нужно, поговори с капитаном Ваймсом. Он живет на верхнем этаже цитадели, где большие казармы, к востоку от башни леди Джайны.', 'Поговорите с капитаном Гарраном Ваймсом на верхнем этаже цитадели.', 'Настоящее его имя – Джеймс Хьяль. Он открыл таверну на краю Степей, хотел сделать уютное местечко для отдыха путешественников. $B$BМожет, он слишком многого хотел, но некоторое время дела в таверне шли хорошо. Потом мы потеряли контроль за дорогами через болота, и здесь стали шататься огры, а Джеймс был слишком упрям, он не захотел бросить свое детище ради безопасности. Теперь таверна \"Последний привал\" сгорела до основания. Мы пытались разобраться, но особых успехов не достигли, поэтому твою помощь примем с благодарностью. Если хочешь помочь – посмотри, вдруг что найдешь на развалинах.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1284, 'Подозрительные следы копыт', 'Цепочка следов уходит от все еще дымящегося остова таверны \"Последний привал\". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.', 'Доложите о подозрительных следах возле таверны \"Последний привал\" капитану Гаррану Ваймсу из Терамора.', 'Следы копыт, говоришь? В последнее время в этих краях зашевелились кентавры. Наши разведчики во время вылазки в Степи заметили несколько их лагерей и поселений.$B$BЯ пошлю одного из наших охотников, Фальграна Гастила, посмотреть, куда ведут эти следы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1285, 'Солдаты Даэлина', 'Реддон... Редпат... А! Вот он! Лейтененат Павал Рит.$B$BВсупил в ряды тераморской стражи вместе с остальными новобранцами, которые пришли из-за моря вместе с леди Праудмур. Зачислен в морские пехотинцы Кул-Тираса в возрасте шестнадцати лет. Отличная служба, поощрения...$B$BЧислится пропавшим без вести.', 'Вернитесь с информацией о Рите к капитану Гаррану Ваймсу в Терамор.', 'Пропал без вести? В переводе с языка Тезорана, это значит – предатель.$B$BНе сомневаюсь, что это один из тех глупцов, слепо преданных адмиралу Даэлину и готовых ради него предать собственную страну. Забавно, правда? Дезертиры обвиняют нас в предательстве дела Альянса.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1286, 'Дезертиры', 'Удержаться на болотах было нелегко. Но все же мы возвели несколько оборонительных сторожевых башен в округе.$B$BПо последним донесениям разведчиков, группа дезертиров обосновалась в Разрушенной башне к юго-востоку от таверны. $B$BЗа главного у них, кажется, Балос Хакен. Посмотрим, получится ли вытянуть у него какие-нибудь сведения.$B$BНо будь с ним осторожнее, $N, он тертый вояка.', 'Расспросите о Рите Балоса Хакена и его дезертиров в Пылевых топях.', 'Тебя Ваймс прислал? Вечно он спихивает на других всю грязную работу...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1287, 'Дезертиры', 'Рит? Этот трус?$B$BМы вышвырнули его из лагеря, потому что он настаивал на налете на деревню огров Гиблотопь, чтобы пограбить их запасы. Нас не так много, чтобы рассчитывать справиться с этими безмозглыми тварями. $B$BОн настолько часто зарывался, что мы решили, что с нас хватит, и прогнали его.$B$BВот, я помог тебе, почему бы теперь тебе не забыть о нашей встрече?', 'Поговорите с капитаном Гарраном Ваймсом в Тераморе.', 'Я пошлю лейтенанта Келдвелла поговорить с дезертирами из Разрушенной башни. Вдобавок, я попрошу его поискать Рита. Болота не так уж велики и непроходимы, так что я уверен, он его отыщет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1288, 'Донесение Ваймса', 'Хорошая работа, $N. Для любителя просто отличная. $B$BЛеди Праудмур просила, чтобы я держал ее в курсе, но я некоторое время не имел возможности с ней пообщаться.$B$BЯ собирался отправить ей рапорт позже, – но мне кажется уместным вместо этого послать к ней тебя. Ты куда лучше меня ответишь на все ее вопросы.', 'Отнесите донесение Ваймса леди Джайне Праудмур в Терамор.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1289, 'Зад', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1301, 'Джеймс Хьяль', 'Перед тем, как перебраться сюда, в \"Синий Отшельник\", я обучался, у одного из лучших поваров которых я когда-либо встречал. Его звали Джеймс Хьяль, и все чего я добился в этой жизни, это только благодаря ему.$B$BИнтересно, как-то он там сейчас? Они вместе со своим братом Винсентом работали в таверне, в Гавани Менетилов, но я давно о нем ничего не слышал.$B$BЕсли вдруг ненароком встретишь его, кланяйся от меня.', 'Поговорите с Винсентом Хьялом в Гавани Менетилов. ', 'Джеймс? Так он еще когда уехал отсюда. $B$BВолна патриотизма накрыла, наверное. Можно понять. Многие после всего этого безумия, творящегося в Лордероне, последовали за море за Джайной Праудмур.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1302, 'Джеймс Хьяль', 'Мой брат Джеймс ушел за море с леди Праудмур. Последнее, что я слышал, былото, что по окончании боев он там открыл таверну. Но, где бы он не находился, я уверен, что дела у него идут хорошо. Он ведь, знаете ли, великолепный повар.$B$BЯ некоторое время не имел о нем известий - видать, с гостиницей было много хлопот - но я уверен, что клерк в Тераморе сможет указать вам, где искать моего брата. Клерка вы найдете на верхнем этаже крепости в центре города, как же ее... А! Цитадель, вот как она называется.', 'Поговорите с клерком Лендри в Цитадели в Тераморе. ', 'Джеймс Хьяль, Джеймс Хьяль... Что-то знакомое...$B$BА, точно! Случай с \"Последним привалом\". Если ты хоть что-то об этом знаешь, то пойди и расскажи капитану Ваймсу. Он ведет расследование.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1318, 'Неоконченное дело Гордоков', 'Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а? Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спер его у одного из королей!$B$BА вещица-то была ценная: латная рукавица Мощи Гордока! И в старых байках говорится, что воротить ее сможет только настоящий король Гордок. А еще говорится, что паскудный эльф до сих пор шляется где-то тут. Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!', 'Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.По словам Давигрома, в \"старых байках\" говорится, что Тортелдрин – \"страшный эльф\", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.', '', NULL, NULL, NULL, 'Латная рукавица Мощи Гордока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1319, 'Черный щит', 'Увы, но я не смогу помочь тебе, $N. Впрочем, я знаю, кто сможет. Каз Дваждыдвац – один из лучших наших кузнецов. Его можно найти на кузне.$B$BПокажи ему щит и послушай, что он скажет.', 'Покажите потемневший железный Щит Казу Дваждыдвацу из Терамора.', 'Хмм... Интересная железяка. Это точно не моя работа, и я не знаю ни одного кузнеца по эту сторону моря, из чьих рук она могла бы выйти.', 'На что взглянуть?', NULL, NULL, 'Вороненый железный щит (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1320, 'Черный щит', 'Чуть было не просмотрел... Кожаный ремень на тыльной стороне щита сгорел, но, сдается мне, он был приспособлен под крупную руку. Скорее всего, тауренскую.$B$BВот, в общем, и все, что я могу тебе сказать. Передай капитану Ваймсу, что я сожалею, но больше ничем не могу ему помочь.', 'Поговорите с капитаном Гарраном Ваймсом в Тераморе.', 'Узнать удалось немного, но и это сгодится. Будем надеяться, что вскоре прояснятся остальные части этой головоломки, и мы сможем увидеть полную картину произошедшего.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1321, 'Черный щит', 'Хмм... Я не вижу в этом щите ничего необычного. Нужно попросить До\'гола, нашего кузнеца, взглянуть на него. Может быть, До\'гол сможет рассказать нам больше, хотя я бы не надеялся на это...', 'Покажите потемневший железный щит До\'голу из Деревни Гиблотопь.', 'Хороший щит. Крепкий, тяжелый, хороший... Но До\'голу он не нужен. Догол делает щиты, а не покупает их, $N.$B$BТеперь понятно?', 'Что это у тебя тут, $C?', NULL, NULL, 'Вороненый железный щит (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1322, 'Черный щит', 'Хм... А на ободе щита, оказывается, что-то написано, но прочитать трудно, все обгорело.$B$BЧтобы отчистить надпись, мне нужна кислота – подойдет яд пауков Мглистой пещеры. Эти пауки водятся в старых копях – Мглистой пещере к северо-западу от деревни. Принеси немного их ядовитых желез, и я почищу щит.', 'Добудьте 5 ядовитых желез Паука Черного Тумана для До\'гола из Деревни Гиблотопь.', 'Я не люблю слишком больших пауков – их не раздавишь.$B$BСпасибо, $N. Теперь я вскрою железы и залью их содержимым щит…', 'Ты добыл яд этих пауков?', NULL, NULL, 'Железа с едким ядом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1323, 'Черный щит', 'Сдается мне, что с кислотой я переборщил. Теперь осторожно потрем щит…$B$BХмм. Прочесть сложновато, но, похоже, тут написано имя: Мозарн. Никогда о таком не слышал. Надо спросить Крога, он знаком с кучей народу.', 'Поговорите с Крогом в Деревне Гиблотопь.', 'Мозарн? Звучит знакомо... Но поручиться не могу. Может быть вспомню попозже.$B$BСкорее всего, это имя не имеет значения. Щит мог попасть туда откуда угодно и с какой угодно целью.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1324, 'Пропавший дипломат', 'Что?! Ты приходишь сюда, обвиняешь меня в пособничестве Братству Справедливости и ожидаешь, что я буду стоять столбом и позволю себя убить? Меня, между прочим, давно насчет тебя предупреждали...', 'Победите рядового Хендела в Пылевых топях.', 'Уверяю вас, что мы все огорчены текущими событиями, но просим позволить забрать его назад в Терамор, чтобы задать несколько вопросов. Это поможет в поисках короля.$B$BЛеди Праудмур отблагодарит вас за помощь. Обратитесь к ней при первой возможности.', NULL, NULL, NULL, 'Победить рядового Хендела.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1338, 'Заказ Грозовой Вершины', 'Есть один дворф-бронник, чья работа меня глубоко восхищает. Его зовут Фьюрен Длиннобород, и такого искусника еще поискать. Мне нужен новый щит, и я хотел бы сделать заказ у него!$B$BПроблема в том... что он живет далеко на юге, в Квартале Дворфов в Штормграде. В человеческих землях! Представления не имею, зачем он поселился так далеко от Стальгорна. Должно быть, люди платят немалую мзду, лишь бы удержать его у себя!$B$BЕсли ты любишь путешествовать и не прочь подзаработать, может, передашь мой заказ Фьюрену?', 'Отнесите заказ Грозовой Вершины Фьюрену Длиннобороду в Штормград.', 'А, заказ от дворфа Грозовой Вершины. Это гордый клан, славный крепкими, сильными дворфами. И их богатством.$B$BБольшое спасибо, $N. Я сегодня же вечером займусь щитом для горного пехотинца Грозовой Вершины.', 'Письмо из дворфийских земель? Интересно, кто это пишет мне из такой дали…$B$BПозволь взглянуть на заказ.', NULL, NULL, 'Требование Грозовой Вершины (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1339, 'Задание Грозовой Вершины', 'Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие. Сможет ли $r вроде тебя справиться с его поручением?$B$BЕсли ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне.', 'Поговорите с горным пехотинцем Грозовой Вершиной. ', 'Верно. У меня есть одно дельце, но самому мне недосуг – не могу покинуть пост. Путь неблизкий, придется поработать ногами.$B$BЗато отличная возможность поискать приключений!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1358, 'Образец для Хелбрима', 'Мой коллега из Калимдора, аптекарь Хелбрим, исследует воздействие лордеронских ядов на тамошних зверей. Он наверняка хотел бы иметь препарат из волчьего сердца, что мне прислал Ренферрел. $B$BХелбрим обосновался в Степях, в деревне под названием Перекресток. Чтобы до него добраться, вам нужно будет на дирижабле добраться до орочьей столицы Оргриммара, а потом пешком проследовать на юг, в Дуротар. Направляйтесь на запад, в Степи, и вскоре дойдете до Перекрестка.', 'Принесите образец сердца волка аптекарю Хелбриму в Степи.', 'А, очень хорошо. Если первые результаты верны, токсические свойства этих сердец могут серьезно продвинуть нас в наших представлениях о ядах. $B$BЭто долгожданная посылка, $N. Ваша награда за нее – совершенно заслуженная.', 'У вас есть для меня посылочка?', NULL, NULL, 'Образец сердца волка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1359, 'Посылка для Зинг', 'Волчьи сердца, которые вы собрали, обладают качеством, невиданным доселе в подобных образцах. Это сила яда, которая должна быть смертельной даже для тех самых волков, в груди которых бьются эти сердца! $B$BЭто просто невероятно, и мы должны продолжить исследование. Я сохранил несколько полученных препаратов. Отнесите их моей коллеге, аптекарю Зинг. Ее можно найти в главном представительстве нашего Общества в Подгороде.', 'Отнесите образцы сердца волка аптекарю Зинг в Подгород.', 'Ах да, препараты сердец, о которых говорил Ренферрел. Я хочу поскорее начать экспериментировать с ними... Обнаружение новых форм ядов всгда вызывает живейший интерес в Королевском фармацевтическом обществе.', 'Вы мне что-то принесли?', NULL, NULL, 'Образцы сердца волка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1360, 'Возвращенные сокровища', 'Я неплохо зарабатывал горнорабочим на ульдаманском раскопе в Бесплодных землях, пока не появились эти клятые трогги. Я едва сумел спасти свою шкуру, но в суматохе потерял самое дорогое, что у меня было. Уверен, что трогги не добрались до моего сокровища, поскольку оно в сундуке, но сундук-то в самой их гуще.$B$BЕсли ты принесешь его мне, то не поскуплюсь ни на деньги, ни на хвалу! Сундучок с моим именем находится в конце Северного зала. Вот туда тебе и надо попасть.', 'Достаньте сокровище Крома Крепкорука из сундука в северном зале Ульдамана и принесите ему в Стальгорн.', 'Ах, я снова счастлив! Спасибо тебе огромное.$B$BМожет, кому из дворфов дороже всего блеск металла, а кому – сверкание драгоценных камней, но Крепкорук без своей драгоценной пивной кружки вряд ли может считаться Крепкоруком!', 'Ну, тебе удалось надавать этим троггам и добраться до моего сундука?', NULL, NULL, 'Сокровище Крома Крепкорука', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1361, 'Регтар Врата Смерти', 'Регтар Врата Смерти, воин Орды, набирает агентов для похода в земли Пустошей. Любой желающий может поговорить с ним и попробовать записаться в отряд. Найти Регтара можно в Степях, в одном из укрытий к западу от Перекрестка.$B$BНе следует забывать, что в Пустошах не затихают битвы, поэтому без оружия там нечего делать.', 'Поговорите с Регтаром Врата Смерти в Степях.', 'Да, я набираю добровольцев. Тех, кто готов отправиться в Пустоши и сражаться с кентаврами. Я изложу ситуацию вкратце, чтобы ты скорее мог приступить к выполнению задания.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1362, 'Кентавры Пустошей', 'Кентавры из клана Колкар изначально жили в Пустошах, но теперь они все чаще появляются в Степях. Это известный факт, и Орда послала своих агентов разбираться с ними.$B$BОднако же пока клан Колкар силен в Пустошах, эти кентавры всегда будут для нас угрозой. Думаю, пора от них избавиться. Главное – безопасность!$B$BПоговори с Фелгуром Бью-Двоих: ты его найдешь на Заставе Скитающихся Духов в Пустошах. Его отправили туда для сбора информации о кентаврах. Думаю, он лучше всех знает, как справиться с кланом Колкар.', 'Найдите на Заставе Скитающихся Духов в Пустошах Фелгура Бью-Двоих и поговорите с ним.', 'Тебя Регтар сюда прислал? Значит, ты и будешь решать проблему кентавров? Что ж, хорошо.$B$BНадеюсь, ты успел отдохнуть. Не знаю уж, удастся нам разобраться с этими тварями, или нет, но за то, что это будет долгая и тяжкая драка, могу ручаться.$B$BПрисядь и послушай меня...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1363, 'Задание Мазена', 'Я слежу за тем, чтобы все фолианты и свитки в библиотеке Академии Тайных Наук и Искусств постоянно находились под присмотром. Кто знает, сколько глупостей может натворить непосвященный, заполучив тайные трактаты по магии?$B$BНапример, на прошлой неделе мой помощник Деллис допустил одну оплошность... Он неплохой работник и хорошо ориентируется в пределах библиотеки, но совершенно теряется, стоит ему выйти за ворота Штормграда... Пожалуйста, помогите Деллису разобраться с его затруднением.', 'Поговорите с послушником Деллисом в Штормграде. ', 'Да не виноват я! Клянусь, не виноват!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1364, 'Задание Мазена', 'Указания мастера Мазена были совсем простыми: доставить важное сочинение дозорному Махару Ба в Крепость Стражей Пустоты.$B$BНо мне раньше не доводилось бывать в Выжженных землях! Путешествие было просто ужасным...$B$BНеподалеку от Болота Печали я свернул куда-то не туда и оказался окружен жуткими тварями, похожими на растения. Они напали на меня, и я сбежал. Представьте себе, при этом я потерял сочинение! Думаю, его забрала одна из этих тварей.$B$BНе могу ли я попросить вас найти документ и доставить его Махару Ба?', 'Верните \"Рассуждения Кадгара о пространственной сходимости\" и доставьте сочинение дозорному Махару Ба в Крепость Стражей Пустоты.', 'Какое счастье!$B$BДо сего момента я считал, что мой запрос на \"Рассуждения Кадгара о пространственной сходимости\", который я отправлял в Академию Тайных Наук и Искусств, был отклонен мастером Мазеном.$B$BОн, должно быть, просто потонул в запросах, поскольку последнее время происходит множество странных событий.$B$BТеперь прошу меня простить – мне пора приступить к исследованиям. Понимаете, сама возможность прикоснуться к творению величайшего Кадгара повергает меня в трепет...', 'Что привело вас в Крепость Стражей Пустоты, $C?', NULL, NULL, 'Рассуждения Кадгара о пространственной сходимости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1365, 'Вождь Дез\'хеп', 'Племя Колкар – не единственные кентавры в Пустошах. На этих пустынных равнинах поселилось множество племен, ведущих друг с другом бесконечную войну. Наше счастье, что они дерутся между собой: кентавры сильны и яростны в битве, и, если бы они объединились, нам тяжело было бы выстоять против них.$B$BМы должны покончить с ними прежде, чем они объединятся.$B$BТвое первое задание – расколоть племя Колкар. Для этого нужно убить их предводителя Дез\'хепа.$B$BДеревня клана Колкар находится к северо-востоку отсюда. Иди, и да пребудет с тобой удача.', 'Принесите Фелгуру Бью-Двоих голову вождя Дез\'хепа. ', 'Отлично. Быстрый и точный удар по клану Колкар стал весьма эффектной демонстрацией силы, а сила – это именно то, что кентавры понимают лучше всего.$B$BСмерть вождя клана Колкар не только расколет клан, но и станет предостережением для всех прочих кентавров.', 'Ну что, $N, удалось тебе одолеть Дез\'хепа?', NULL, NULL, 'Голова вождя Дез\'хепа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1366, 'Награда за кентавров', 'Тебе удалось устрашить кентавров; теперь пришло время пустить им кровь. Странствуя по Пустоши, охоться на кентавров. Их клан меня не волнует: просто убей их и принеси мне уши. Пригоршни ушей!$B$BЧем меньше кентавров, тем слабее их решимость: пусть навсегда расстанутся с мыслью завоевать эти земли!$B$BДоброй охоты, $N.', 'Принесите в Пустоши 15 ушей кентавров и отдайте Фелгуру Бью-Двоих.', 'Теперь-то кентавры навсегда запомнят твое имя! Уверен, они уважают и страшатся тебя. Уверен, благодаря тебе они не забудут и того знамени, под которым ты вступал в бой.$B$BЗнамя Орды!', 'Как идет добыча ушей, $N? Много нарезал?', NULL, NULL, 'Ухо кентавра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1367, 'Союз с племенем Маграм', 'Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племен, и так найдем способ одолеть всех остальных.$B$BЕсли ты решишь заключить союз с племенем Маграм, уничтожь их кровных врагов – племя Гелкис. Так ты завоюешь уважение племени Маграм. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Варугом. Ты найдешь его на окраине деревни Маграм в юго-восточной части Пустошей.', 'Заслужите дружественное отношение племени Маграм, а затем поговорите с Варугом.', 'Кентавры племени Гелкис кричат от ужаса, заслышав твое имя, $N. Они страшатся и ненавидят тебя. Ненавидят так же, как племя Маграм!$B$BМожет, ты и не слабее нас. Может, ты даже достоин того, чтобы мы с тобой говорили. Посмотрим...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1368, 'Союз с племенем Гелкис', 'Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племен, и так найдем способ одолеть всех остальных.$B$BЕсли ты решишь заключить союз с племенем Гелкис, уничтожь их кровных врагов – племя Маграм. Так ты завоюешь уважение племени Гелкис. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Утой Мудрой. Ты найдешь ее на окраине деревни Гелкис в юго-западной части Пустошей.', 'Заслужите дружественное отношение племени Гелкис, а затем поговорите с Утой Мудрой.', 'Земля говорит со мной; земля говорит, что ты убил многих из племени Маграм. Это хорошо.$B$BЕсли хочешь быть другом племени Гелкис, слушай. Я буду говорить с тобой. У меня есть для тебя дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1369, 'Россыпи Слез', 'Племя Гелкис считает, что нас защищает матерь кентавров Терадрас. Они глупы. Кентавров никто не защищает. Маграм не нужна защита! Мы сильнее всех!$B$BПусть племя Гелкис поймет, насколько они глупы. Отправляйся в их деревню, прямиком к пещере. В этой пещере они хранят кристаллы – слезы Терадрас. Уничтожь эти кристаллы! Принеси мне их осколки!', 'Для поддержания отношений с племенем Маграм принесите 3 кристалла Россыпи Слез Варугу в деревню Маграм.', 'Ага! Вот они, Слезы! Теперь племя Гелкис поймет, что Терадрас не защитит их. Она не станет плакать, когда мы сокрушим их! Маграм будут править здесь!$B$BТы хорошо сделал, выбрав нашу сторону, $N. Мы – самые сильные.', 'Если ты нам не враг, то сделаешь то, о чем я прошу!', NULL, NULL, 'Россыпи Слез', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1370, 'Похищение припасов', 'Когда мы не воюем, то охотимся, чтобы добыть мяса. Мясо дает нам силу. Сытый воюет лучше голодного. Сытый сильнее. Сытый победит.$B$BПлемя Маграм поступает так же. Они запасают мясо, чтобы воевать дольше. Если нападешь на их деревню на востоке и заберешь их припасы, Маграм станут слабыми.', 'Принесите 6 мешков недосушенного мяса в деревню Гелкис и отдайте Уте Мудрой.', 'Хорошо. Я слышу, как урчит в брюхе у голодных Маграм! Слышу это даже здесь!$B$BЯ отдам это мясо племени Гелкис. Мы будем воевать много дней без отдыха.$B$BТо, что ты сделал, хорошо для племени Гелкис.', 'Когда докажешь, что верен клану Гелкис, возвращайся. Будем говорить.', NULL, NULL, 'Недосушенное мясо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1371, 'Игрушка для Варуга', 'Давным-давно один маленький гном пришел в Пустоши со своей тележной, запряженной лошадью и нагруженной множеством странных вещей. Занятных вещей. Некоторые горели разноцветным огнем. Некоторые двигались, не будучи при этом живыми. Я убил этого маленького гнома, но перед этим... он заставил меня посмеяться.$B$BЯ оставил себе одну вещицу с его тележки – ту, которая понравилась мне больше всего. Это был деревянный человек, который махал на меня руками, пока я не ударил его, да так, что тот сломался.$B$BЯ хочу нового деревянного человека! Доставай его, где хочешь, но принеси мне!', 'Для поддержания отношений с племенем Маграм принесите усовершенствованный манекен-мишень Варугу в деревню Маграм.', 'Да! Именно такой человек у меня и был! Он снова будет двигаться. Снова будет веселить меня!', 'Если ты нам не враг, то сделаешь то, о чем я прошу!', NULL, NULL, 'Усовершенствованный манекен-мишень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1372, 'Правда и только правда', 'По приказу Вариматраса нашу экспедицию направили на изучение нижнего Азерота.$B$BОтправившись на разведку, я заметил лазутчика, подобравшегося к Приюту Бродяги. Не успел я скрутить его, как некоторые наши орочьи... братья... захватили его и уволокли в Каменор, крепость на Болоте Печали.$B$BЯ хочу... помочь... нашим братьям-оркам. Они не заметили наш лагерь, но я все равно собираюсь оказать им услугу.$B$BФаустин поможет тебе сделать... сыворотку правды для нашего друга в Каменоре.', 'Поговорите с аптекарем Фаустином в Приюте Бродяги. ', 'Зредус как раз перед твоим приходом рассказал мне об этом любопытном маленьком лазутчике.$B$BЭто и правда проблема. Нам вовсе не нужен нахал, вынюхивающий, что да как.$B$BУверен, орки Каменора с интересом выслушают его. Поскольку они, хм, наши союзники, мы должны помочь им добыть информацию от этого человека.$B$BПомоги мне, $N, – и мы доставим в Каменор сыворотку правды.$B$BЗа Орду!$B$BЭ-э... я правильно выразился?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1373, 'Онгеку', 'Тебе еще предстоит свершить многое. Война племен Гелкис и Маграм тебя не затронет: в это время ты будешь далеко отсюда.$B$BЗемля раскрывает множество тайн тем, кто умеет слушать ее; и одна из них – тайна красного кристалла, который называют дренетистом. Это камень нездешнего происхождения; он из тех земель, где горы парят в небе, где правят демоны...$B$BПринеси мне осколок дренетиста: о, с ним сила моей магии возрастет во много раз!.. Осколок можно отыскать на Болоте Печали: его хранит один из Заблудших, Онгеку.', 'Для поддержания отношений с племенем Гелкис принесите осколок дренетиста Уте Мудрой в деревню Гелкис.', 'О да, это и есть тот осколок, о котором шептала мне земля... Я ощущаю его магическую силу – ту силу, которую я направлю против врагов племени Гелкис.$B$BТебе удалось исполнить еще одно наше задание, $N. Возможно, со временем племя Гелкис сможет по праву считать тебя другом.', 'Докажи, что ты – подлинный друг племени Гелкис, $N.', NULL, NULL, 'Осколок дренетиста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1374, 'Вождь Джен', 'Земля говорит со мной. Земля знает, что племя Маграм утратило былую силу. Пришло время покончить с их вождем!$B$BПринеси мне голову Джена, вождя племени Маграм!', 'Принесите голову вождя Джена Уте Мудрой в деревню Гелкис.', 'Вождь Джехн был силен, но глуп. Он полагал, что наделен великой силой, но забыл, что магия Земли могущественнее любого смертного. Лишившись вождя, племя Маграм впадет в ничтожество, и племя Гелкис восторжествует!', 'Докажи, что ты – подлинный друг племени Гелкис, $N.', NULL, NULL, 'Голова вождя Джена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1375, 'Вождь Шак', 'Ты помогаешь племени Маграм. Это хорошо. Ты мне нравишься. А теперь пойди и убей вождя племени Гелкис! Вождь Шак – мне нужна его голова! Я хочу видеть его голову, я буду смотреть на нее и смеяться!', 'Для поддержания отношений с племенем Маграм принесите голову вождя Шака Варугу в деревню Маграм.', 'Вождь Шак мертв! Я насажу его голову на пику, чтобы любоваться ею каждый день! Пусть мертвые глаза Шака видят мощь племени Маграм!', 'Делай то, что нужно племени Маграм, и я помогу тебе.', NULL, NULL, 'Голова вождя Шака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1380, 'Вождь Храта', 'Ты $gпомог:помогла: нам справиться с племенем Маграм, $N; теперь помоги нам одолеть племя Мародин! Убей их предводителя! Убей Храту!$B$BЧтобы вызвать его на бой, ты $gдолжен:должна: протрубить в боевой рог племени Мародин; а рог этот ты найдешь, поднявшись на высокий утес в Долине Копий.$B$BТолько запомни: чтобы протрубить в рог, тебе нужно разыскать мундштук, а это нелегко, потому что найти такие мундштуки можно только у кентавров, пользующихся особым доверием племени...$B$BО чем это я? Ах, да: когда ты протрубишь в рог, кентавры явятся на бой, и тебе придется убивать их, пока не доберешься до самого Храты.$B$BА у вождя Храты есть фрагмент... некоего ключа. Принеси его мне...', 'Для поддержания отношений с племенем Гелкис принесите фрагмент Ключа Мародина Уте Мудрой в деревню Гелкис.', 'Он мертв! Вождь Храта мертв! Теперь племя Мародин падет! И когда этой землей станет править племя Гелкис – клянусь, мы не забудем тебя, $N. Духи земли будут вечно славить твое имя!', 'Надеюсь, вождь Храта мертв? А фрагмент ключа – он у тебя?', NULL, NULL, 'Фрагмент ключа Мародина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1381, 'Вождь Храта', 'Вождь племени Гелкис мертв; пришел черед племени Мародин! Убей их вождя, Храту!$B$BЕго не так просто отыскать, нет... Чтобы вызвать его на бой, ты $gдолжен:должна: протрубить в боевой рог клана Мародин; а рог этот ты найдешь, поднявшись на высокий утес в Долине Копий. Только запомни: чтобы протрубить в рог, тебе нужно убить кентавра из племени Мародин и забрать у него мундштук.И вот когда ты протрубишь в рог, кентавры явятся на бой, и тебе придется убивать их, пока не доберешься до самого Храты. А у Храты есть фрагмент ключа. Он нужен мне, этот фрагмент. Принеси его. Принеси мне.', 'Для поддержания отношений с племенем Маграм принесите фрагмент Ключа Мародина Варугу в деревню Маграм.', 'Вождь Храта мертв! Теперь Маграм – сильнейшее из племен! Мы сокрушим всех! Мы будем править в Пустошах!$B$BМы не забудем тебя, $N, и в тот час, когда сотни будут гибнуть под нашими копытами, мы пощадим тебя.', 'Сделай, что я говорю. Докажи, что ты – достойный союзник племени Маграм!', NULL, NULL, 'Фрагмент ключа Мародина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1382, 'Странный союз', 'На наше счастье, племена кентавров постоянно враждуют. Если бы они объединились, никто не сумел бы их остановить. Да, нам сильно повезло – и мы должны обратить это везение себе на пользу.$B$BПлемя Гелкис ведет жестокую войну с племенем Маграм. Если мы атакуем поселение Маграм, то, возможно, сумеем заключить союз с племенем Гелкис.$B$BВ юго-западной части Пустошей, неподалеку от лагерей племени Гелкис, ты сможешь найти Уту Мудрую. Возможно, поговорив с ней, ты сумеешь заключить союз...', 'Заслужите дружественное отношение племени Гелкис, а затем поговорите с Утой Мудрой.', 'В племени Гелкис говорят о тебе. Твои руки в крови проклятых Маграм. Это хорошо.$B$BЯ буду говорить с тобой. Скажи, что ты можешь сделать для племени Гелкис – и что племя может сделать для тебя.', 'Прочь! Кентавры племени Гелкис не желают видеть тебя! Уходи!$B$BИди, убей Маграм, много Маграм – тогда будем говорить.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1383, 'Правда и только правда', 'Я знаю подходящую сыворотку. Она обойдется с правдой именно так, как с ней следует обходиться.$B$BЧтобы сделать ее, мне понадобится несколько сердец пантер тени из болота. Кроме того, мне нужен мох хозяина болота, обитающего неподалеку. Не сомневаюсь, что ты сумеешь уговорить его поделиться с тобой.$B$BИ последнее, что необходимо мне для составления сыворотки, это кровь мечтательного дракончика, вроде тех, что живут рядом с пещерой Итара в болоте.$B$BА теперь иди!', 'Принесите аптекарю Фаустину в Приют Бродяги 5 сердец пантер тени, мох хозяина болота и немного крови зеленого дракончика.', 'Великолепно, $N! И как раз вовремя. Судя по тому, что говорит Зредус, лазутчик оправился от ран и готов к допросу.$B$BПогоди, сейчас я приготовлю отра... то есть сыворотку правды.', 'Лазутчик в Каменоре несомненно... расколется... после того, как напьется моей сыворотки. Ха-ха!$B$BОднако компоненты достать сложно. Пантеры Тени часто встречаются на Болоте, но собрать достаточно сердец – непростая задача. А хозяин болота может быть очень несговорчивым.$B$BДа и достать опухоль странника глубин – та еще задачка, но зато с ней можно провести такую реакцию, что мало не покажется.', NULL, NULL, 'Сердце пантеры Тени', 'Мох хозяина болота', 'Кровь зеленого дракончика', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1384, 'Набег на племя Колкар', 'Кентавры из племени Колкар полагают, что сильны в магии. Они ничего не понимают в магии! Они не распознают ее, даже если их носом в магию ткнуть!..$B$BКто-то должен доказать им, что в отношении магии они просто дети неразумные. Думаю, этим кем-то будешь ты. Отправляйся в деревню Колкар, что на северо-восток отсюда. Отними у кентавров их обереги и принеси их мне. Я брошу их в огонь, и это согреет мне сердце.', 'Для поддержания отношений с племенем Гелкис принесите 10 грубых оберегов Уте Мудрой в деревню Гелкис.', 'Ты сделал доброе дело для племени Гелкис. Клан Колкар слаб: он обречен и сгинет. Их жалкая магия не поможет им. Ты показал им это – и страх сделает их еще слабее!$B$BВ этих землях слабаки долго не живут.', 'Где обереги? Они у тебя? Теперь-то эти кентавры поняли, как они слабы?', NULL, NULL, 'Грубый оберег', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1385, 'Политика силы', 'Пустоши – земля, пожираемая огнем войны. Кентавры враждуют между собой; мы страшимся того, что победившее племя пойдет войной на наши крепости и разрушит их. Мы не можем этого допустить.$B$BМы должны научиться побеждать кентавров, а для этого нам придется заключить союз с одним из их племен. Племя Маграм издревле враждует с племенем Гелкис. Если ты начнешь войну с племенем Гелкис, возможно, племя Маграм задумается о том, что неплохо бы иметь такого воина на своей стороне.$B$BЗавоюй расположение племени Маграм, а затем отправляйся в деревню племени в юго-восточной части Пустошей и поговори с Варугом.', 'Заслужите дружественное отношение племени Маграм, а затем поговорите с Варугом.', 'Многие из племени Гелкис пали от твоей руки. Мне это нравится. Может, ты сумеешь сделать что-то еще, что мне понравится. Может, ты сумеешь стать другом племени Маграм.', 'Уходи прочь, не то Маграм сокрушат тебя! Хочешь стать нашим другом – убивай кентавров племени Гелкис!', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1386, 'Нападение на племя Колкар', 'Клан Колкар полагает, что он силен; мы смеемся над ними – и убиваем их со смехом! Ты тоже их убиваешь. Покажи, что умеешь убивать их не хуже, чем мы. Клан Колкар должен умереть. Иди на север. Убей их. Убей их всех!', 'Для поддержания отношений с племенем Маграм вы должны убить 12 кентавров из племени Колкар, 12 разведчиков из племени Колкар и 6 извергов из племени Колкар, а затем вернуться к Варугу в деревню Маграм.', 'Теперь клан Колкар страшится тебя. Скажи, ты смеялся, когда убивал их? Когда убиваешь, надо смеяться: тогда враги увидят, что они слабы.', NULL, NULL, NULL, 'Кентавр из племени Колкар убито', 'Разведчик из племени Колкар убито', 'Изверг из племени Колкар убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1387, 'Награда за кентавров', 'Раса кентавров состоит из множества кланов. У каждого из них – свой вождь и свои законы, но есть одна черта, которая объединяет их всех: жестокость.$B$BЕсли мы хотим обрести мир, нам следует изгнать кентавров из этих земель. Тебе предстоит исполнить это нелегкое задание.$B$BВ своих странствиях по Пустоши ты будешь убивать кентавров и собирать их уши. Чем больше ушей, тем лучше. Принеси их мне.$B$BЕсли, $N, ты исполнишь это во славу и во имя Альянса, мы будем на шаг ближе к завершению этой войны.', 'Принесите в город Высота Найджела 15 ушей кентавров и отдайте их капралу Мелкису.', 'Ах, уши... Уши! Что ж, прекрасно.$B$BБесспорно, услуги, оказанные тобой Альянсу, весьма велики, $N. Поверь, та кровь, что была пролита тобой в Пустошах, поможет спасти множество жизней.', 'Тебе есть что сообщить, $N?', NULL, NULL, 'Ухо кентавра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1388, 'Правда и только правда', 'Все прошло точно по плану. Теперь отнеси эту сыворотку правды стражу смерти Зредусу, и он покажет, как ею... Правильно воспользоваться.$B$BХа-ха!', 'Отдайте сыворотку правды Фаустина стражу смерти Зредусу в Приюте Бродяги.', 'Я знал, что старина Фаустин что-нибудь придумает! Ты ему очень помог, я даже не сомневаюсь.$B$BА теперь к делу, верно?', 'Не сомневаюсь, что ты очень помог нашему дорогому другу, аптекарю Фаустину.', NULL, NULL, 'Сыворотка правды Фаустина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1389, 'Кристаллы дренетиста', 'Заблудшие, живущие в Болотном пристанище, на вид ничем от нас не отличаются, но на самом деле это чудовища... лишившиеся рассудка в пути до Азерота. Когда-то они были нашими братьями. Теперь они живут в Болотном пристанище, к востоку отсюда, захватывая и убивая любого, кто попадется под руку.$B$BСейчас они украли одну из наших святынь – кристаллы дренетиста.$B$BУ нас не хватает сил ворваться в Святилище и вернуть себе нашу реликвию, но без нее... мы тоже вскоре утратим свой путь.', 'Принесите 6 кристаллов дренетиста Магтуру в Убежище в Болоте Печали.', 'Благодарю тебя, $N. Мы перед тобой в долгу.', 'Ну, и где кристаллы?', NULL, NULL, 'Кристалл дренетиста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1391, 'Правда и только правда', 'Мы должны действовать тайно. В конце концов ты же не можешь войти и заставить этого олуха выпить состав Фаустина?$B$BНо от выпивки ни один человек не откажется. Я возьму сыворотку Фаустина и замешаю ее в эль. Сомнений нет, бедняга без колебаний выпьет предложенную бурду.$B$BСпеши в Каменор на Болото Печали, $N. И никому не рассказывай о нашем задании...', 'Отнесите бражку Зредуса секретному агенту Марксену в Каменор.', 'Ты принес мне попить? Как мило с твоей стороны. Мне не давали даже губы смочить вот уже несколько дней. Позволь мне утолить жажду, и я расскажу обо всем, что узнал...', 'Прошу, смилуйся надо мной! У меня есть сведения, которые не касаются Альянса. Хотя я не сторонник Орды, вы столкнулись с предательством, которое я хочу разоблачить!', NULL, NULL, 'Бражка Зредуса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1392, 'Нобору Дубина', 'Нобору много месяцев не давал житья дренеям Прибежища, и его дубина стала символом жестокости, которую они претерпели от рук Заблудших.', 'Принесите дубину Нобору главе Убежища на Болото Печали.', 'Ты добыл оружие ужасного Нобору? Так значит он мертв? $B$BЭто праздник для всего Убежища! Нобору и его банда, многие годы терроризировали нас, бродя по болотам и убивая любого дренея, который попадался на пути. Он ставил под угрозу само наше выживание, но нам не хватало сил, справиться с ним самостоятельно. $B$BТы оказал нам большую услугу, $N.', 'Приветствую. И добро пожаловать в Убежище!', NULL, NULL, 'Деревянная рапира Нобору (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1393, 'Побег Галена', 'Помогите! Эти твари хотят меня съесть!$B$BЕсли ты поможешь мне выбраться отсюда, то получишь великое сокровище! Оно лежит в моем лагере, в болотах к северу от Каменора, но только я знаю, как открыть сейф, в котором оно находится.$B$BЕсли ты поможешь мне, я научу тебя, как открыть этот сейф.', 'Выведите Галена из опасного места, затем найдите его лагерь на Болоте Печали и откройте его сейф.', 'Замочная скважина этого сейфа залита черной смолой. Открыть его невозможно.$B$BНо Гален рассказал вам о секретном замке на днище сейфа... $B$B... Быстро осмотрев сейф, вы находите задвижку. Задвижка отодвинута, и сейф открывается.', NULL, NULL, NULL, 'Выведите Галена из Болотного пристанища.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1394, 'Финальное испытание', 'Ты хорошо $gсправился:справилась:, $N. Ты $gпрошел:прошла: все мои испытания и те, что были до этого. Возвращайся к Дорну в Тысячу Игл. Он непременно заметит перемены, произошедшие с твоим телом, разумом и духом, и поймет, что твои усилия достойны награды.$B$BВсегда храни в себе ту гармонию, которой ты $gдостиг:достигла: в этих испытаниях, $N, и тогда в будущем Дорн сможет испытать тебя еще раз.', 'Поговорите с Дорном Вольным Ловчим в Тысяче Игл. ', 'А, $N. Давненько ты не заглядывал в мой дом. Кажется, прошло уже много лун с тех пор, как ты сделал первый шаг на своем пути.$B$BА теперь ты вернулся намного сильнее, чем раньше... И намного мудрее. Это хорошо. И тебе полагается достойная награда за все испытания.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1395, 'Поставки для Стражей Пустоты', 'Этот ящик с камнями силы нужно доставить в Крепость Стражей Пустоты, в Выжженные земли. Их сила будет сохраняться не так-то долго, так что мы не можем отправить их следующим караваном. $B$BТебе следует отнести их как можно скорее.$B$BОтдай их интенданту Лунгерцу в Крепости Стражей Пустоты. Чтобы достичь крепости, тебе следует направиться на восток через Первал Мертвого Ветра, затем далее через Болото Печали, потом свернуть на юг через Выжженные земли.$B$BОднако осторожнее, $N. Твой путь проляжет через опасные земли, но цель должна быть достигнута.', 'Отнесите ящик камней силы интенданту Лунгерцу, прежде чем камни утратят силу.', 'О, камни силы! Маги будут рады увидеть их!$B$BБольшое спасибо, $N. Я знаю, что твой путь из Темнолесья был нелегок.', 'Приветствую! Не обращай внимания на всю эту суматоху, это обычное дело в Крепости Стражей Пустоты.$B$BУ тебя что-то для меня есть?', NULL, NULL, 'Ящик с силовыми камнями (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1396, 'Атака тварей', 'Мой караван направлялся к восточному побережью, но до места так и не добрался. Заблудшие атаковали нас, перебив стражу и уничтожив припасы.$B$BВыжить удалось только мне. Я обещал сохранить оставшиеся товары, но вокруг полно чудовищ. Прошу тебя, помоги мне защитить мой лагерь!', 'Убейте 8 молодых острозубых кроколисков, 10 ткачей скорби и 10 болотных ягуаров и потом вернитесь к дозорному Биггсу на Болоте Печали.', 'Судя по звукам, твари убрались. Благодарю тебя, $N. Теперь-то, надеюсь, они не вернутся!', 'Болотные твари наседают, $N! Ты должен спасти лагерь!', NULL, NULL, 'Молодой острозубый кроколиск убито', 'Ткач скорби убито', 'Болотный ягуар убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1398, 'Плавник', 'Я – твой должник,$N, В твоей груди бьется великодушное сердце. А теперь – смею ли еще раз попросить тебя о помощи?$B$BЧтобы добраться до Стражей Пустоты, я должен починить эту повозку, а для этого мне необходимо дерево. Сухое, прямое дерево, а те не рыхлые и скрюченные кусты, которые растут на болотах.$B$BОтправляйся на восточное побережье, поищи там плавник хорошо просушенный солнцем и принеси его мне.', 'Принести 8 кусков сухого плавника дозорному Биггсу на Болоте Печали.', 'Дерево легкое, но крепкое. Спасибо, $N, это подойдет.', 'Ты нашел хоть немного плавника, $N?', NULL, NULL, 'Сухой плавник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1418, 'Ника Алый Шрам', 'Бесплодные земли суровы. Они примыкают к территории Альянса возле озера Лок Модан, потому сообщение между Каменором и форпостом Каргата часто оказывается перерезанным. $N, у тебя есть шанс проявить себя. Отправляйся в Бесплодные земли и поговори с Никой Алый Шрам, главой разведчиков Каргатского форпоста, а затем принеси мне ее доклад.', 'Поговорите с Никой Алый Шрам.', 'Хелгруму нужен доклад, а? Я посылала гонца в Каменор около трех дней назад. Он что, не добрался? Если в Каменоре нет моего донесения, сдается мне, гонец сгинул. Будем надеяться, что следующий, кого я пошлю, будет лучше подготовлен, ну или более удачлив.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1419, 'Койоты-воры', 'Ну и как тебе Бесплодные земли, $C? Жара, пылища, стаи всяких тварей? У тебя есть шанс прочувствовать все прелести этих земель еще лучше.$B$BСкальные койоты – наглые твари. Наглые настолько, что пробираются в Каргат и воруют наши припасы. Помоги нам избавиться от них!$B$BПринеси мне их челюсти, если ты соберешь достаточно много, я поверю, что ты и вправду знаешь Бесплодные земли.', 'Принесите 30 челюстей койотов Нике Алый Шрам в Каргат.', 'Впечатляющий набор челюстей, $N. Теперь-то эти койоты поостерегутся подбираться к нашим припасам.$B$BОтлично! Койоты из Бесплодных земель – не такая уж легкая добыча. Теперь я уверена – ты сможешь тут выжить.', 'Ты принес челюсти?', NULL, NULL, 'Челюсть койота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1420, 'Донесение Хелгруму', 'Я написала новое донесение для Хелгрума из Каменора, отнеси его ему. $B$BИ если ты считаешь себя гонцом – не сбейся с пути и не попадись врагам!', 'Отнесите донесение Ники Хелгруму Быстроногому в Каменор.', 'Благодарю тебя, $N. Из донесения Ники я понял, что Альянс озабочен собственными проблемами, и, может статься, что кое-какие враги у нас общие.', 'Ты вернулся! Донесение при тебе?', NULL, NULL, 'Донесение Ники (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1421, 'Пропавший караван', 'Я был оглушен во время атаки Заблудших, но, прежде чем потерять сознание, я видел, как одну из наших повозок угоняли к Болотному пристанищу, поселению Заблудших на севере.$B$BВ этой повозке находился сундук с наиболее ценными реагентами, предназначающимися для магов Крепости Стражей Пустоты. $N, найди сундук, добудь эти реактивы и верни их мне.', 'Найдите похищенный из каравана сундук в Болотном пристанище, добудьте реагенты магов и принесите их дозорному Биггсу.', 'Браво! С этими реактивами волшебники Крепости Стражей Пустоты смогут продолжить работу. Я не знаю, чем они там занимаются, знаю только, что это связано с Темным порталом в Бесплодных землях и напрямую касается безопасности всего Альянса.', 'Ты достал реактивы, $N?', NULL, NULL, 'Реагенты волшебника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1422, 'Угроза с моря', 'Пока я буду работть над твоим оружием, почему бы тебе не поговорить с Катором? Он, говорил, что ему нужна помощь с патрулированием побережья, и тебе бы лучше поддерживать боевую форму, а не напиваться с теми недоделками, что торчат в нашем лагере.', 'Поговорите с Катором на Болоте Печали.', 'Помолчи немного, $C. Даже сквозь глухой рокот моря все еще слышно отвратительное бульканье, заменяющее рыболюдям речь', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1423, 'Потерянные припасы', 'Этот бочонок мал, зато прочен. Его швы заплиты желтым пахучим воском, а на торце выдавлены слова:$B$BИНТЕНДАНТ ЛУНГЕРЦ$B$BКРЕПОСТЬ СТРАЖЕЙ ПУСТОТЫ', 'Принесите потерянные припасы интенданту Лунгерцу. ', 'Благодарю тебя, $N. На пути из Темнолесья теряется так много провизии, Как хорошо, что кое-что удается вернуть.', 'У тебя что-то есть для меня?', NULL, NULL, 'Потерянные припасы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1424, 'Озеро Слез', 'Вождь послал нас разузнать, что творится в храме Атал\'Хаккар.$B$BАтал\'ай – племя темных заклинателей, известных тем, что используют запретную магию. Можешь себе представить, как мы были поражены, когда узнали что храм затоплен.$B$BТеперь его сторожат зеленые драконы, которые утверждают, что они защитники Азерота.$B$BМы должны выяснить, что произошло. Исследуй окрестности озера Слез и собери артефакты Атал\'ай. С их помощью я смогу собрать всю картину воедино.', 'Соберите 5 артефактов Атал\'ай для Фелзерула из Каменора.', 'Твое усердие в происках артефактов Аталаи достойно похвалы, $C.', 'Никто не знает, что темные обряды творились в Храме Атал\'Хаккара. Но мы знаем, что там применялись мощные чары.$B$BИ мы должны выяснить все, что сможем, об этой магии. Возможно, заклинания Атал\'ай будут полезны и Орде.$B$BКак только ты принесешь достаточно артефактов Атал\'ай в окрестностях озера Слез, мы поймем, что замышляли тролли и что именно привело к такому исходу.', NULL, NULL, 'Артефакт Атал\'ай', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1425, 'Доставка груза', 'Пока я чиню эту повозку, $N, выполни для меня еще одно, последнее задание. $B$BЯ собрал наиболее важные припасы, уцелевшие после набегов огров. Доставь их в крепость Стражей Пустоты. Она выстроена в холмах, на севере Выжженных земель, для наблюдения за Темным порталом.$B$BДобраться туда можно по восточной дороге. Когда она разветвится, сверни на юг к Выжженным землям, а потом налево на следующей развилке. Не сходи с дороги,$N, и не теряй бдительности', 'Доставьте груз в Крепость Стражей Пустоты интенданту Лунгерцу.', 'Что? Груз из каравана Биггса? Мы думали, он пропал вместе с караваном.$B$BСпасибо, $N. Надеюсь там кристаллы Азоры, этот реактив, нам крайне необходим, а наш запас подходит к концу.', 'У тебя ко мне какое-то дело?', NULL, NULL, 'Партия товара Стражей Пустоты (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1426, 'Угроза с моря', 'Мне не нравится ни море, ни твари, что лезут из его глубин. Море могущественно, но слепо, бесчувственно и жестоко. С какой радостью я истреблял бы этих рыболюдей сотнями, будь у меня возможность. Но мне принесет и некоторую радость зрелище их гибели от рук тех, кто выполняет волю Орды.$B$BОт твоих рук, $C. Скольких ты сможешь убить? Хочешь ли рискнуть и сразиться с сильнейшими из них?', 'Убейте 10 болотных мурлоков, 10 болотных чернильщиков и 10 болотных трупоедов, затем вернитесь к Котору в Болото Печали.', 'Море безбрежно и безжалостно, но ты запятнал его кровью его собственных порождений. Рыболюди знают, что такое боль. Их тупость заставит их сплотить ряды после того разгрома, который ты им учинил, и это хорошо.$B$BПусть из булькающие крики заглушают шум моря по ночам. А я буду улыбаться каждый раз как услышу, что кто-то из них замолк. $B$BВозвращайся ко мне, если вдруг захочется поубивать еще рыболюдей. Я с удовольствием тебя вознагражу за это.', 'Я терпелив. Терпелив и вечен как старая замшелая каменюга с Дренора. Рыболюди больше не протревожат наших границ, по крайней мере, пока я жив. Будь у меня армия, я бы очистил этот мир, как и прочие миры, от этих тварей. Мне противно даже говорить о них.', NULL, NULL, 'Болотный мурлок убито', 'Болотный чернильщик убито', 'Болотный трупоед убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1427, 'Угроза с моря', 'Прежде чем пойти отдохнуть, пообщайся с Ток\'Каром. Пока тебя не было, он, наверняка, закончил работу над обещанным тебе оружием. Было бы неплохо, если бы ты опробовал его на рыболюдях, когда созреешь...уж доставь мне удовольствие.', 'Поговорите с Ток\'Каром в Болоте Печали.', 'О! $N, ты вернулся! Хорошо. Я как раз закончил партию оружия против мурлоков. За свежее мясо кусак и за то, что заставил Катара улыбаться, выбери себе одно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1428, 'Продолжающаяся угроза', 'Мне приятно видеть, что ненависть, которую ты испытываешь к рыболюдям, все растет, как и моя.$B$BНайди их на побережье, а потом когда битва будет закончена, возвращайся, и мы решим, как вознаградить тебя за усердие.', 'Убейте 10 болотных чернильщиков, 10 болотных трупоедов и 10 болотных оракулов, затем вернитесь к Котору в Болоте Печали.', 'Отлично, $C. Но мне мало этой крови. Пусть все рыболюди исчезнут с лица земли.', 'Только когда море и все его порождения, особенно эти отвратительные рыболюди упокоятся, я буду счастлив...', NULL, NULL, 'Болотный чернильщик убито', 'Болотный трупоед убито', 'Болотный оракул убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1429, 'Изгнанник Атал\'ай', 'Пока ты $gсражалась:сражался: с опасностями озера Слез, один из моих разведчиков вернулся со свитком из сушеного мяса с кровавыми письменами. Мне кажется это официальный приговор жрецу племени Атал\'ай. Этот жрец был приговорен племенем к участи худшей, чем смерть, – он был изгнан на север во Внутренние земли, жить среди троллей племени Сухокожих. Я соберу эти артефакты, а тебе предстоит найти изгнанника и выяснить их назначение. После этого возвращайся ко мне.', 'Принесите сверток с артефактами Атал\'ай к изгнаннику Атал\'ай во Внутренние земли.', 'Ты принес мне артефакты призыва Атал\'ай? Я вижу, Джаммал\'ан Пророк ведет своих последователей из Чертога Крови навстречу выбранному ими року. Интересно, вернулся ли Хаккар в свой храм? Встретили ли они свою судьбу?', 'Для того чтобы прийти сюда, нужна большая смелость. Ну или большая глупость...', NULL, NULL, 'Сверток с артефактами Атал\'ай (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1430, 'Свежее мясо', 'Среди моих покупателей крайне высок спрос на сочное крабье мясо, особенно мясо чудовищного краба. $B$BЕсли ты планируешь направиться на побережье, то можешь еще и с выгодой прогуляться туда, если ты принесешь мне несколько крабьих ног, чтобы я переправил их в Оргриммар. $B$BПобережье находится к востоку отсюда, а крабы там просто кишат, что на берегу, что под водой.', 'Принесите 10 ног чудовищного краба Дару на Болото Печали.', 'О! Замечательно, я жду не дождусь, когда попробую крабье мясо, должным образом приготовленное на открытом огне. Возьми с собой в дорогу малую толику, вкус просто несравненный!', 'У меня тут бочонок вина ожидает твоего возвращения, $N, по мне товар прежде надо на вкус попробовать, а потом уж отсылать заказчику.', NULL, NULL, 'Нога чудовищного краба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1431, 'Отношения с Альянсом', 'Слушай внимательно, $C. Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное.$B$BМы – народ гордый, и война с людьми истощила даже терпение Тралла. Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего. В то же время он тонкий дипломат. Он умеет обращаться с людьми.$B$BЕсли тебе это интересно, поговори с Кельдраном. Его лачуга стоит у западного входа в город.', 'Поговорите с Кельдрином в Оргриммаре.', 'Патанни, $C! Меня зовут Кельдран, я изучаю магию... и другие тайные искусства.$B$BДело, по поводу которого ты здесь, требует большей тонкости, чем те, которыми тебе приходилось заниматься раньше. Однако это не значит, что ты не можешь нам помочь.$B$BПожалуйста, устраивайся поудобнее. Я расскажу тебе, зачем вождю понадобилась моя... и твоя помощь.$B$BВсе начинается со впечатления, $N. Какой себя видит Орда. Какими видят нас наши союзники. И, главное, какими нас видят наши враги.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1432, 'Отношения с Альянсом', 'Альянс все расширяет свои владения в Калимдоре. Из-за этого может сложиться впечатление, что Орда вступает в союз с Пылающим Легионом. Вождь не может этого допустить. И я, с его благословения, буду отвечать за их изгнание.$B$BУ меня есть свои агенты в Пустошах, на Заставе Скитающихся Духов – это к северу от большого Кладбища кодо. Ступай на юг от Обугленной долины в Когтистых горах, и увидишь заставу. Когда прибудешь туда, разыщи Такату Стального Клинка.', 'Поговорите с Такатой Стальным Клинком в Пустошах. ', 'Приветствую, $C! У тебя есть вести из Оргриммара? Это хорошо.$B$BВ здешних краях все провоняло демонами – сильнее, чем кентавровым навозом. Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться.$B$BПолучается, что мы вроде как помогаем кентаврам. Это мне не по нутру, но все это на благо Орды, так что я выполняю свой долг перед вождем, даже если ради этого приходится поддерживать чернокнижников.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1433, 'Отношения с Альянсом', 'Чернокнижники из клана Пылающего Клинка преданы злу до мозга костей. Души их осквернены, и единственный способ их остановить – это уничтожить.$B$BКельдрин отправил со мной Морина, потому что он знает многое о Пылающем Клинке и разбирается в уловках чернокнижников.$B$BОн борется с Клинком, а на мою долю остаются прочие козни демонов тут, в Пустошах.$B$BПоговори с Морином, он посвятит тебя в свои планы.', 'Поговорите с Морином Костоломом в Пустошах. ', 'Ах, да! Нам всегда пригодится помощь тех, кто предан вождю.$B$BМеня зовут Майрин. Я здесь по просьбе Кельдрина и нашего юного вождя, Тралла. Мальчику нужна помощь в борьбе против врагов, угрожающих его власти.$B$BПодойди-ка поближе, $C. Я изложу тебе свои планы касательно ликвидации этого гнойного нарыва, Пылающего Клинка.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1434, 'Опоганенные сатиры', 'Влияние демонов возникает не на пустом месте. Нужен какой-то изъян, который позволяет злу войти в тебя.$B$BМожет быть, слабость духа, или излишнее стремление к власти, или жажда мести... Когда мы поддаемся боли, то позволяем злу взять над нами верх – такому злу, как сатиры.$B$BОни связаны с Пылающим Клинком, и Тралл хочет, чтобы их перебили. Разыщи их на северо-востоке и возвращайся ко мне, когда сумеешь их изгнать.', 'Убейте 7 разбойников из племени Ярой Ненависти, 7 скверноподданных племени Ярой Ненависти, 7 предателей из племени Ярой Ненависти и 7 адских сатиров из племени Ярой Ненависти и вернитесь к Такате Стальному Клинку в Пустоши.', 'Молодец, $C! В тебе есть доблесть и преданность делу.$B$BКогда мы покончим с нашими делами в Пустошах, вождь непременно узнает о том, что ты помогал нам выполнять его волю.$B$BБлагодарю тебя!', 'Спутник-таурен предупредил меня, что сатиры – не совсем то, чем кажутся. Он считает, что зло в них исказило их истинную природу. Но сам я такого не видел.$B$BЯ вижу только, как они безжалостно убивают слабых и оскверняют души тех, кто обращается к темным силам.$B$BИ я буду уничтожать их, пока вождь не поручит мне другое дело. Жалости к ним я не испытываю.', NULL, NULL, 'Разбойник из племени Ярой Ненависти убито', 'Скверноподданный племени Ярой Ненависти убито', 'Предатель из племени Ярой Ненависти убито', 'Призыватель огня из племени Ярой Ненависти убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1435, 'Сжигание душ', 'Этих жалких тварей лучше всего предать смерти. Но, когда имеешь дело с теми, кто присягнул тьме, недостаточно просто убивать.$B$BВозьми этот самоцвет. Приведи его в действие, когда один из негодяев из клана Пылающего Клинка будет близок к смерти. Заклятие вытянет оскверненный дух из жертвы, и у тебя в руках окажется одушевленный самоцвет.$B$BПринеси мне эти одушевленные самоцветы, я с ними разберусь.$B$BСтупай же, и постарайся избегнуть смерти!', 'Верните пылающий самоцвет и 15 усиленных пылающих самоцветов Морину Костолому в Пустошах.', 'А, ты вернулся с победой! Это хорошо. Давай сюда самоцветы, я их спрячу в надежное место…$B$BУ меня больше нет для тебя поручений, $C. Отдохнешь – поговори с Такатой. Возможно, у него найдется для тебя дело – а может, он попросит тебя вернуться в Оргриммар и сообщить Кельдрану, как идут дела у нас в Пустошах.', 'Я пытался сделать заклятие как можно более простым. Вытянуть душу твоей жертвы из умирающего тела должно быть детской игрой. Но не рассчитывай, что магия самоцвета сама убьет твоего врага. Активировать камень нужно только тогда, когда враг уже умирает, иначе ничего не получится.', NULL, NULL, 'Пылающий самоцвет (Прилагается)', 'Одушевленный самоцвет', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1436, 'Отношения с Альянсом', 'Дела идут на лад, $N. Быть может, если мы продолжим одерживать победы над демонами и их приспешниками, вождь разрешит нам вернуться домой еще до начала следующего сезона.$B$BВозвращайся к Кельдрану и расскажи, чего нам удалось добиться. Уверен, он вознаградит тебя за труды. Он будет горд, узнав, что вождь ценит его усилия.', 'Поговорите с Кельдрином в Оргриммаре.', 'Тебе удалось добиться успеха, да еще какого, $С! Спасибо тебе.$B$BБлагодарю тебя за труды, за потраченное время и за то, что ты с пониманием отнесся к моей просьбе. Тралл стремится к миру между Ордой и Альянсом и потому заботится, чтобы мы выглядели достойно в глазах противника. Не следует провоцировать новые конфликты.$B$BЯ твой должник!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1437, 'Расследование Валарриэля', 'Приветствую тебя, $N. Я – Валарриэль. Я прибыл сюда, чтобы установить местопребывание двух пропавших торговцев из почтенной дарнасской семьи – дома Малем. Глава дома опасается самого худшего; я обязан выяснить все, что могу, о его пропавших детях. Правда, поиски Тираниса и Далинды я еще не начал, но надеюсь, что не задержусь здесь надолго.$B$BПоследнее, что мне довелось слышать о них – то, что несколько недель назад они миновали Когтистые горы.$B$BЕсли найдешь их повозку, прошу тебя, немедленно дай мне знать.', 'Отправляйтесь в Пустоши и попытайтесь отыскать повозку Тираниса и Далинды Малем.', 'Судя по виду повозки, она подверглась воздействию как грубой силы, так и чар. Похоже, битва была короткой, и у одной из сторон не было никаких шансов – не было даже возможности отразить удар. Ни трупов, ни следов крови нигде не видно.$B$BКто бы ни напал на торговцев, действовал он весьма умело...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1438, 'Расследование Валарриэля', 'Постарайся разыскать Далинду и Тираниса. Начни поиски с той самой крепости, о которой ты $gговорил:говорила:, а я пока что свяжусь с Дарнасом и изложу ситуацию. Что бы ты ни $gобнаружил:обнаружила:, немедленно дай мне знать.$B$BЯ хотел еще кое-что сказать тебе, $N. Дело в том, что мое начальство весьма обеспокоено действиями Тираниса и причинами, которые заставили его отправиться сюда. Чрезвычайно важно найти Далинду и доставить ее домой. Целой и невредимой, по возможности. А вот Тираниса следовало бы сначала... проверить.', 'Найдите в Пустошах Далинду Малем.', 'Благодарение Элуне, хоть кто-то пришел на помощь! Прошу тебя, $C, помоги мне. Орки Пылающего Клинка схватили меня и моего брата Тираниса и притащили сюда. Мне кажется, они собираются принести меня в жертву своим хозяевам-демонам!..$B$BЯ знала, что наше путешествие в Пустоши – это ошибка, но Тиранис так настаивал... в последнее время он особенно увлекся потаенными знаниями, хотя многим это не нравилось. Он решил отправиться в эти края именно после того, как узнал, что здесь появляются демоны...$B$BБоюсь, с ним случилось что-то скверное... очень скверное!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1439, 'Поиски Тираниса', 'Орки перебили нашу охрану и слуг, а потом приволокли нас сюда. Ты представить себе не можешь, что с ними сделали! Я думала, нас тоже прикончат на месте – но, как выяснилось, у орков были на нас другие планы.$B$BТиранис пытался поговорить с ними. Наверное, он думал, что его знания тайных искусств произведут на орков впечатление. Не знаю уж, почему.$B$BПрошу тебя, помоги! Я не могу уйти, пока не узнаю, что случилось с моим братом. Найди его – или хотя бы узнай о его судьбе. Умоляю!..', 'Разыщите в Пустоши Тираниса Малема.', 'Это ужасно!.. Но, полагаю, у тебя не было другого выхода. Если бы не ты, его все равно убили бы... Наверное, я должна поблагодарить тебя. Прости, если это звучит не слишком искренне: думаю, ты понимаешь, почему.$B$BТеперь, когда я знаю, какая судьба постигла моего несчастного брата, думаю, пора бежать отсюда. Если ты еще не передумал, я с радостью воспользуюсь твоей помощью и покину это страшное место.$B$BКогда будешь готов, скажи мне: мы тут же отправимся в путь.', 'Боюсь, Тиранис попытается узнать тайны Пылающего Клинка и стать одним из них, если, конечно, они это позволят. Его всегда восхищала та власть, которую дает магия – и никогда он не думал о цене этой власти...$B$BНе знаю, как мне вернуться к семье, когда душа Тираниса подвергается такой опасности... Наш народ считает преступлением даже изучение подобной магии, а уж если Тиранис преобразится в одно из тех существ, с которыми му ведем войну...', NULL, NULL, 'Подвеска Тираниса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1440, 'Возвращение к Валарриэлю', 'Итак, время пришло?.. Ценю твои усилия и благодарю тебя за все, что ты $gсделал:сдалала: для меня и моей семьи. Что ж, если ты $gготов:готова:, то и мне тут больше нечего делать. Отправимся в путь по первому твоему слову.', 'Выведите Далинду Малем из Крепости Громового Топора, а затем вернитесь в Пустоши к Валлариелю Истребителю Демонов.', 'Благодарю тебя, $N. Далинда благополучно добралась до Высоты Найджела и чувствует себя гораздо лучше, чем я смел надеяться. Я даже не надеялся на столь благополучный исход! То, что ей удалось добраться сюда своими силами – добрый знак. Надеюсь, с тобой тоже все в порядке?..$B$BМне жаль, что Тиранис не вернулся; однако все, что с ним произошло, было плодом его собственных решений. Далинде придется с этим смириться – и, к тому же, разбираться с последствиями его действий, когда она вернется в Дарнасс.', NULL, NULL, NULL, 'Спасите Далинду Малем.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1442, 'Поиск самоцвета Кора', 'День добрый, $N. Чем могу помочь $gидущему:идущей: путем Света?$B$BАх да, кузнец Стилвелл... давно не виделись. Я хорошо его помню, хотя давно о нем не слышал.$B$BОн никогда не казался мне злодеем, поэтому остается думать, что его стремление получить самоцвет Кора благородно.$B$BЕсли вам и правда нужен самоцвет, то придется направиться на северо-запад Ясеневого леса. Там, среди древних развалин, вы обнаружите Непроглядную Пучину. В их недрах таятся наги, и они до сих пор используют такие самоцветы. Не ходите туда в одиночку, $C.', 'Принесите самоцвет Кора Тандрису Ветропряду на Темных берегах.', 'Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой.$B$BПусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале.$B$BЯ надеюсь, вы понимаете, что делаете, $C, ибо в руках у вас не игрушка.', 'Я с трудом поверил бы в чистые намерения того, кто ищет самоцвет Кора, не будь это искатель святого пути. Но таким, как вы, я доверяю даже больше, чем собственным сородичам. И я не стану судить о вашем ордене по деяниям ваших падших собратьев.', NULL, NULL, 'Оскверненный самоцвет Кора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1444, 'Возвращение к Фел\'зерулу', 'Джаммал\'ан Пророк приговорил меня к изгнанию из храма Атал\'Хаккар. Некогда я считал верховного жреца достойным главой храма.$B$BЕго непоколебимая вера в свое пророчество может привести к гибели Атал\'ай, если уже не привела.$B$BНо стоило мне высказать мои сомнения, я был заклеймен как еретик и изгнан из храма.$B$BПринесенные тобой артефакты безопасны... Но если Джаммал\'ан нашел нужный для ритуала призыва фетиш, то всему миру угрожает смертельная опасность.', 'Вернитесь в Каменор к Фел\'зерулу.', 'Мы же виделись совсем недавно, $C. Надеюсь, твое путешествие было удачным. Что тебе поведал изгнанник-Атал\'ай во внутренних землях ?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1445, 'Храм Атал\'Хаккар', 'Так он говорил о пророчестве Джаммал\'ана?$B$BДуховный вождь Атал\'ай верит, что когда однажды, Хаккар вернется в Азерот из Пустоты, он дарует племени бессмертие.$B$BПо мне дураком надо быть, чтобы раньше срока вызывать светопреставление.$B$BНо ты говоришь, этот изгой упоминал о зачарованных амулетах? А вот это уже напрямую меня касается. Если среди них окажется ключ к ритуалу Атал\'ай, который и привел ко всей этой заварухе, мы должны понять его тайную силу.$B$BОтправляйся в Храм и добудь амулеты!', 'Соберите 20 фетишей Хаккара и принесите их Фел\'зерулу в Каменор. ', 'Отважный $C, ты доказал, что являешься одним из лучших воинов Орды.$B$BТеперь-то мы разберемся с этими амулетами!', 'Если фетиши Атал\'ай способны призвать Хаккара и исполнить пророчество Джаммал\'ана, мы должны заполучить их. Орда должна познать их силу!', NULL, NULL, 'Фетиш Хаккара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1446, 'Джаммал\'ан Пророк', 'Мои товарищи из клана Сухокожих не любят, когда чужаки приходят к ним домой.$B$BЯ? А у меня и дома-то нет. Я жил в племени Атал\'ай на Болоте Печали, но был изгнан оттуда.$B$BУ нашего духовного лидера по имени Джаммал\'ан, было, как он сам говорил, \"видение\". Он решил, что если призвать бога Хаккара, то он дарует Атал\'ай бессмертие.$B$BЯ настоятельно рекомендовал ему проявить осторожность, потому это это \"видение\" могло быть всего лишь манипуляцией, обманом!$B$BЯ хочу отомстить за свое изгнание. Принесите мне голову Джаммал\'ана. Может быть, тогда мой народ освободится!', 'Принесите изгнаннику Атал\'ай из Внутренних земель голову Джаммал\'ана.', 'Джаммал\'ан безоговорочно верил своим бредовым видениям, и именно из-за них мой народ постигла такая страшная судьба.$B$BСпасибо, $N, что отомстил за мое изгнание. Я глубоко скорблю по своему народу. У меня нет дома, в который я мог бы вернуться.', 'Теперь, когда Джаммал\'ана нет, у меня появилась возможность вернуться к своему народу.$B$BС таким духовным лидером, как Джаммал\'ан, племя Атал\'ай было обречено.', NULL, NULL, 'Голова Джаммал\'ана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1447, 'Пропавший дипломат', 'В Штормград приходили многие твои коллеги, $C, были среди них умные, были и круглые дураки, но подобных тебе нет, не было и не надо... $B$BЧего ты от меня хочешь?', 'Победите Дашеля Каменного Кулака в Штормграде. ', 'У тебя явно была причина прийти ко мне. Так в чем дело?', 'Я вовсе не хотел тебя оскорбить, $C. Мы же друзья? Никаких проблем?', NULL, NULL, 'Победить Дашеля Каменного Кулака.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1448, 'В поисках Храма', 'Когда-то я был так же молод и полон сил, как ты, $C.$B$BТеперь я стар и не могу больше странствовать по миру. О, сколько я всего повидал!$B$BНо была одна загадка, которая до сих пор волнует меня. Во время моего последнего путешествия Лига исследователей направила меня на поиски храма Атал\'Хаккар. Говорили, что он расположен где-то на болоте Печали.$B$BПоскольку я уже был стар и немощен, то облетел эти земли на грифоне, но ничего не нашел.$B$BНе поможешь старому дворфу? Может быть, тебе повезет больше?', 'Найдите храм Атал\'Хаккар и сообщите о его местонахождении Брохану Бочкопузу из Штормграда.', 'Храм Атал\'Хаккара скрыт в глубинах озера Слез? И охраняется зелеными драконами?$B$BЭто чудесное открытие, $C! Очевидно, что-то ужасное случилось с этим храмом...', 'Я путешествовал по всему миру, от джунглей Азерота до снежных вершин Каз Модана.$B$BРаньше я никогда не попросил бы о помощи, но мои старые кости ноют и не позволяют пуститься в путь.$B$BЕдинственное, что позволит мне умереть со спокойной душой – знание о том, что я все же выполнил последнее задание Лиги Исследователей.$B$BЕсли вы поможете мне в поисках Храма Атал\'Хаккара, то я буду вечно признателен вам, $C!$B$BИсследуйте Болото Печали и возвращайтесь с рассказом о своих находках!', NULL, NULL, 'Исследовать локацию', 'Найдите храм Атал\'Хаккар.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1449, 'Во Внутренние земли', 'Как я уже говорил, я пытался обнаружить храм, осматривая окрестности с высоты. Строго говоря, я был не один...$B$BЯ нанял грифона в небезызвестном питомнике в Заоблачном Пике во Внутренних землях. Птицей управлял один из лучших пилотов, но в воздухе он выпал из седла и свалился в болото...$B$BМоя старая дырявая память не сохранила его имени, но хозяин питомника должен понять, о ком идет речь.$B$BОтправляйся туда и найди Фалстада Громового Молота.$B$BХорошо бы узнать, что случилось с тем пилотом...', 'Поговорите с верховным таном Фалстадом Громовым Молотом в Заоблачном Пике, что во Внутренних землях.', 'Чего тебе, $gпарень:девчонка:? Не видишь – и без тебя забот хватает? Чем болтаться тут без толку, лучше займись делом, $R.$B$BЧто-что случилось... Тролли лезут из всех щелей, вот что! Ну говори уже, с чем пришел.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1450, 'Укротитель грифонов Разящий Коготь', 'Так, значит, ты $gтот парень:та девчонка:, $gкоторогокоторую: наняли эти старые развалины из Лиги исследователей?$B$BТак, слушай меня, $C. Я понятия не имею, кто у них там развлекался, летая над Азеротом! Я что, похож на Разящего Когтя? Похож?$B$BЕсли тебя интересуют грифоны, так поговори с укротителем! Если я увижу тебя без дела, то завалю по уши настоящей работой.$B$BДавай-давай, топай отсюда.', 'Поговорите с укротителем грифонов Разящим Когтем в питомнике на Заоблачном пике.', 'Да, конечно, я прекрасно помню о том, как послал одного из пилотов отвезти Брохана Бочкопуза.$B$BЛиге Исследователей всегда найдется место в моем сердце. Мой отец участвовал в экспедиции первой исследовательской команды, обнаружившей Ульдаман.$B$BС Броханом я отправил своего лучшего пилота по имени Рапсод Землекоп.$B$BАх, что за наездник это был! Ну, до поры...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1451, 'Рапсод Землекоп', 'Рапсод всегда любил поддать лишнего. Не поймите меня неправильно: мы, дворфы этого питомника, все любим порой принять на грудь пинту-другую доброго эля.$B$BНо старина Землекоп любил это дело больше, чем грифоны любят летать – порой ужас что получалось. Никто не умел летать так, как Рапсод...$B$BАвария с этим вашим приятелем Броханом была только первым звоночком. После этого Землекоп покатился под горку, пришлось его уволить.$B$BГоворят, он открыл пивнушку к югу отсюда...', 'Найдите Рапсода Землекопа во Внутренних землях. ', 'И-ик!$B$BЯ ж прям на вас смотрю, чего это вас так мотыляет из стороны в сторону? У меня аж морская болезнь начинается, ха-ха!$B$BИ-ик!$B$BО! Чувствуете, дорогуша? Земля так и ходит ходуном. Надо выпить!$B$BИк-к!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1452, 'Калимдорский коктейль', 'Ик!$B$BВас послал этот старый пень Брохан? Как вспомню ту историю, так... И-ик!$B$BЧтобы рассказать, что там со мной случилось над этим болотом, понадобится выпить капельку для храбрости. Полный ужас, вы не поверите! Ик!$B$BВот что я скажу – притащите-ка мне индри... гринди... эн-гре-де-ен-ты для калимдорского коктейля, и вы обо всем услышите!$B$BЗначится, что нужно мне... Потроха руха из Танариса, печень гроддока, печень сталемеха из Фераласа... Да.$B$BКалимдорский коктейль развяжет мне язык!', 'Принесите Рапсоду Землекопу 3 куска потрохов руха, 3 печени гроддока и 3 печени сталемеха.', 'Как я погляжу, у вас этих потрошков полные карманы! И какая беда принесла вас из Калимдора-то?$B$BСейчас подождите, я сделаю вытяжку, и тогда уж расскажу все, что вы пожелаете.$B$BИк!$B$BМеня дрожь пробирает, когда вспоминаю это клятое болото.$B$BИк!$B$BСейчас, сейчас, почти готово дело...', 'Пробовали болтливое пиво? Один из моих любимых сортов, надо сказать... Ик!$B$BНо если вы хотите, чтобы я вспомнил все детали того... ик... душераздирающего полета, потребуется что-то покрепче, и-ик, да...$B$BМне так представляется, что потрошка и печенки вы мне не торопитесь нести?$B$BИк!', NULL, NULL, 'Потроха руха', 'Печень сталемеха', 'Печень гроддока', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1453, 'Дела Поисковой корпорации в Пустошах', 'Надо сделать одну работу в Пустошах, $N. Это жуткое место, опоганенное кентаврами и прочими грязными тварями. Но если ты ищешь честную работенку на неделю, то отправляйся туда, найди Крелдига Унгора и скажи, что это я тебя прислал.$B$BТы найдешь его на Высоте Найджела – он прячется в укромном лагере в горах северных Пустошей. Держись к востоку от выхода из Когтистых гор. Будь начеку, иначе можешь проскочить мимо лагеря.', 'Поговорите с Крелдигом Унгором на Высоте Найджела в Пустошах.', 'Рад видеть, что у Горной корпорации нет недостатка ни в работе, ни в искателях приключений, готовых прийти на помощь.$B$BЯ – Крелдиг, $N. Это хорошо, что ты взялся помочь Горной корпорации. В эти дни все что-то ищут – кто фамильные драгоценности потерял, кто магический предмет, кто любимых. Да мало ли что. Но если за дело берется Горная корпорация, то по сходной цене она найдет все что угодно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1454, 'Пожитки Карнитола', 'Мое первое задание касается мага Карнитола – это какой-то тип из благородных, живет в Штормграде. Говорит, на его корабль напали морские великаны, и было это все у северо-западного берега Пустошей. Вместе со слугами этот тип попытался вытащить на берег один из самых ценных сундуков, но когда великаны набросились на них толпой, почел за благо телепортировать себя и своих слуг куда подальше, а сундук, натурально, бросил.$B$BТак вот, Карнитол хочет, чтобы мы нашли его сундук со всем содержимым и доставили ему в Штормград.', 'Найдите в Пустошах сундук Карнитола.', 'Похоже, сундук вовсе не пострадал от морской воды...$B$BОднако он взломан. Если тут и были магические охранные ловушки, то они явно успели сработать: края сундука обожжены.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1455, 'Пожитки Карнитола', 'Любопытно, кто – или что – все же открыло этот сундук?.. Судя по длинным глубоким царапинам на боках и крышке, это был не человек и не великан... Непохоже также, чтобы отметины оставил меч или кинжал.$B$BКроме всего прочего, сундук пуст. Абсолютно и непоправимо пуст.$B$BДелать нечего: остается только закрыть сундук и уйти. Крелдиг будет крайне разочарован.', 'Поговорите с Крелдигом Унгором на Высоте Найджела в Пустошах.', 'Ну-с, $N, с возвращением на Высоту Найджела. Расскажи-ка, что тебе удалось обнаружить...$B$BКак?! Ничего?.. Ну, дорогуша, из ничего и не выйдет ничего: боюсь, за пустой сундук никто платить не станет.$B$BРасскажи-ка мне побольше об этих самых отметинах... царапинах, которые ты заметил.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1456, 'Пожитки Карнитола', 'Любопытно, очень любопытно...$B$BЧто ж, может, для нас еще не все потеряно.$B$BЕсли идти по тому же берегу на север, в сторону острова Раназьяр, там будут развалины построек ночных эльфов. Понятное дело, развалины эти теперь под водой; к тому же, там поселились наги из клана Скользящего Плавника. Сдается мне, эти наги замешаны в истории с сундуком.$B$BЕсли разведчики нагов решились зайти так далеко на юг, значит, по всей видимости, они очень сильны. Так что пожитки Карнитола, как мне кажется, надо поискать у сильнейших среди нагов: приливных охотников или морских ведьм.', 'Найдите сумку для книг, принадлежащую Карнитолу, и отнесите ее в Пустоши Крелдигу Унгору.', 'Просто роскошно, $N! Тебе удалось найти пожитки Карнитола!$B$BОт этих проклятущих нагов вечно одни проблемы. Я бы предпочел с Ордой воевать, чем с ними связываться, честно тебе говорю. Поверь, ты оказал Горной корпорации огро$Nю услугу!', 'Не знаю уж, кем там был этот Ниджел, но что в его лагере я провел самую паршивую ночь в своей жизни, это точно, уж можешь мне поверить, $N.', NULL, NULL, 'Сумка для книг Карнитола', 'Эликсир восстановления пловца', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1457, 'Пожитки Карнитола', 'Послушай, доставь-ка вещички Карнитола Ройттену в Стальгорн: он тебе неплохо заплатит.$B$BТолько ты с ним поосторожнее, не то ты ему понравишься сверх всякой меры и он решит тебя взять к нам, как это называется, на полную ставку!$B$BНет, я ничего не говорю, $N; ты молодчина!$B$BТолько будь поосторожнее на обратном пути и поторапливайся: Карнитол – не самый терпеливый тип... зато платит от души!', 'Отнесите сумку для книг, принадлежащую Карнитолу, в Стальгорн, и отдайте ее Ройттену Камнемолоту.', 'Ах да, Карнитол... Точно, было у него такое дело в Пустошах. Великолепно!$B$BИтак, сундук уничтожен, но все его содержимое тут, да? Что ж, поверим ему на слово, поверим... Тут какое дело? Если ко мне возникнут какие-то претензии, я всегда могу послать жалобщиков куда подальше. Они же от нас чего хотят? – правильно, чтобы мы нашли их вещи. Мы и находим, а уж сохранность и внешний вид находок – это второй вопрос.$B$BПрекрасная работа, $N! Давай-ка посмотрим, что ты на этом заработал...', 'Слушай, $N, дела идут полным ходом, деньги крутятся, так что мне не до болтовни. Оно, конечно, если у тебя что-то есть к Горной корпорации, тогда отойдем, поговорим, а если нет, то лучше пудри мозги кому-нибудь из моих подчиненных – они тебе ответят на все вопросы, только оставь меня в покое!', NULL, NULL, 'Сумка для книг Карнитола (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1458, 'Реагенты для Поисковой корпорации', 'Одна из моих задач здесь – сбор реагентов для Скрытного Кудесника, гномского мага из Караноса. Ройттен-то, небось, думает, что это – раз плюнуть, коли уж мы все равно тут торчим, а дело не из простых, да и рук не хватает...$B$BПервые несколько реагентов добыть не так уж сложно, а я готов заплатить неплохие деньги тому, кто мне поможет.$B$BМне нужны рога и когти сатиров Ярой Ненависти: они тут недалеко обитают, на востоке. Ты мне их сначала принеси, а потом мы займемся остальным списком.', 'Принесите 10 когтей и 10 рогов сатиров племени Ярой Ненависти в Пустоши Крелдигу Унгору.', 'Отлично, $N, отлично! Не то чтобы я был уверен в качестве этой дряни, но ежели этому Скрытному типу нужны были какие-то особые рога и когти, надо было мне об этом раньше сказать, а теперь уж пусть забирает, что дают, я так себе думаю.$B$BНу что, посмотрим, что там дальше по списку?', 'Отвратные они твари, эти сатиры, точно? Поговаривают, что они как-то связаны с ночными эльфами, но мне в это как-то не слишком верится.$B$BСдается мне, эти слухи пошли из-за того, что один эльф несколько лет назад втянул их в войну. После этой войны весь мир поменялся. Опаснее стал, да и страшнее тоже...', NULL, NULL, 'Коготь Ярой Ненависти', 'Рог Ярой Ненависти', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1459, 'Реагенты для Поисковой корпорации', 'А следующее по списку Скрытного Кудесника у нас... Погоди-ка... А, да, вот оно.$B$BНу, не то чтобы это было большой редкостью, но тут наш дорогой друг сподобился дать подобные разъяснения. Ему понадобился яд скорпиона и шкура кодо. А вот тут вот, меленькими буковками, видишь? – тут написано, что яд-то может быть от любого скорпиона, а шкура ему нужна непременно со старого кодо, но ни в коем случае не с умирающего или дряхлого.$B$BОх уж эти мне маги... вечно у них какие-то заскоки.', 'Принесите 7 фиалов скорпионьего яда и 3 шкуры старого кодо в Пустоши Крелдигу Унгору.', 'Твоя помощь просто неоценима, $N Благодаря тебе я проведу в этих проклятущих Пустошах вдвое меньше времени. Еще немного, и можно будет отправиться в Стальгорн: отдых мне не помешает...$B$BКогда мы покончим с этим списком и я вернусь домой, непременно загляни ко мне: я тебе поставлю пару пинт доброго эля!$B$BА пока-что давай займемся остальными реактивами, договорились?', 'Ты уж извини, что я тебе не сказал, где искать скорпионов и кодо. Я здешние места не особо знаю, да и времени у меня не было все тут обследовать...', NULL, NULL, 'Яд скорпиона', 'Шкура старого кодо', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1462, 'Сапта земли', '', 'Попросите у провидицы Воронье Перо еще одну сапту земли. ', 'Возьми это и помни – этот предмет священный.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1463, 'Сапта земли', '', 'Поговорите с Канагой заклинателем земли, чтобы получить еще один сапту земли.', 'Я даю тебе ее со спокойной душой. Твоя доблесть мне известна. Однако же впредь будь поосторожнее!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1464, 'Сапта огня', '', 'Поговорите с Телфом Джоламом, чтобы получить еще одну сапту огня. ', 'Пусть огонь неугасимо пылает в твоем сердце, Лигазул!$B$BСтихии ждут тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1465, 'Расследование Валарриэля', 'При осмотре повозки удается найти подвеску, а также следы, ведущие на юг – туда, где над фортом поднимается легкий дымок, заставляющий думать не о пожаре и горящих домах, а об очаге или костре, на котором готовится пища. Должно быть, если Малемы еще живы, их увели в том направлении.$B$BВаларриэль непременно должен увидеть подвеску – и об этих признаах жизни на юге ему тоже нужно рассказать...', 'Принесите подвеску Малемов Валарриелю Истребителю Демонов на Высоте Найджела в Пустошах.', 'Я в ярости! Подумать только, какой провал!..$B$BИ ведь этих двоих предупреждали, что здесь крайне опасно. А теперь они оба пропали... И хорошо, если живы.$B$BГоворишь, ты видел следы, ведущие к ближнему форту?.. Что ж, возможно, у нас все еще есть шанс...$B$BМестные жители говорят, что в этой крепости обосновались орки Пылающего Клинка – те, что служат демонам. Я вовсе не хочу сказать, что вся Орда придерживается подобных верований – но это сейчас неважно, а важно то, что эти орки непременно убьют тебя, если увидят, что ты пытаешься что-то разведать неподалеку от их форта.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1466, 'Реагенты для Поисковой корпорации', 'Это последнее в списке. Врать не буду, задание не из приятных; к тому же оно наверняка займет у тебя больше времени, чем предыдущие.$B$BНу ладно, хватит болтать. Вот гляди: Скрытный Кудесник тут пишет, что ему нужны мозги любых пожирателей маны или охотников на магов... крылья Пустоты ему еще нужны, от любой Девы, Сестры или Колдуньи Пустоты... и еще... кровь Тюремщика Судеб ему еще нужна, от лорда или капитана – не важно.$B$BПростенькое такое заданьице, точно? Слушай, я тебе вот что скажу: если ты откажешься, я пойму.', 'Принесите 10 мозгов гончих Скверны, 10 крыльев Пустоты и 10 фиалов крови тюремщика судеб в Пустоши Крелдигу Унгору.', 'Честно говоря, не думал, что тебе это удастся. Ты – это что-то, $N! Надо же, и демонов покромсал для чокнутого мага, и живым вернулся! Вот это класс!$B$BКак вернусь в Стальгорн, лично расскажу о тебе старине Ройттену!', 'Я даже и представить себе не мог, что все эти демонические твари обитают тут, в Пустошах. Мне все как-то казалось, что после ухода эльфов тут кентавры живут...$B$BИнтересно, как здесь эти твари оказались и чего им тут надо?', NULL, NULL, 'Мозг гончей Скверны', 'Крыло Пустоты', 'Кровь тюремщика судеб', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1467, 'Реагенты для Поисковой корпорации', 'Хочешь плату получить? Так за этим тебе придется вернуться в Стальгорн и потолковать со стариной Ройттеном. Думаю, он будет рад отделаться, наконец, от коробки Кудесника. Отдашь ему вот это, и получишь свою награду. $B$BДа ты не беспокойся: когда я вернусь, то всяко замолвлю за тебя словечко. Мне тоже не больно-то хочется торчать в этих самых Пустошах.', 'Доставьте коробку Скрытного Кудесника в Стальгорн Ройттену Камнемолоту.', 'О, а вот и посылка для Скрытного Кудесника, прямиком из Пустошей! Прекрасно! Ценю твою работу, $С: к тому же, тебе удалось уложиться в срок. Приятно было с тобой работать.$B$BВот тут твоя плата. И пусть все знают, что Горная корпорация всегда оплачивает услуги своих работников по высшему разряду!', 'Рад тебя видеть, $N. Бизнес процветает, Молоты звенят по наковальням, меха раздувают огонь, а моя жена готовит мне пирог на десерт... Жизнь прекрасна, не так ли?', NULL, NULL, 'Коробка Кудесника (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1468, 'Детская неделя', 'Можешь ли ты помочь нам позаботиться о сиротах? $gБлагословен будь, друг:Благословенна будь, дева: помощь твоя во время Детской недели неоценима.$B$BВозьми этот свисток. Ты сможешь использовать его только во время Детской недели. Свистни в него – и сможешь поговорить с ребенком, о котором будешь заботиться. Свистни еще раз – ребенок уйдет.$B$BВсе очень просто, $N: используй свисток и заботься о ребенке. Любой сирота будет рад встрече с тобой.', 'Продудите в детскую свистульку. Присматривайте за сиротой в течение всей Детской недели.', 'Э... ну, привет. Меня зовут Рандис, ты будешь за мной присматривать, да? А ты – искатель приключений? Мама и папа тоже были такими. Значит, ты меня поймешь!$B$BДавай играть! Воспитатели мне сказали, что ты мне будешь вроде старшего брата. Это здорово! Если бы у меня были настоящие братишки и сестренки...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1469, 'Рапсодия о болоте', 'Перед тем как лететь, я выпил полный бочонок портера. Ик!$B$BЧто это был за полет! Я несся по воздуху, а Брохан болтался за моей спиной, но храма мы не видели. Ик!$B$BИ не нашли бы мы его никогда, если бы я не нагрузился так, что сверзился из седла. Упал в воду, пошел прямо на дно. А тут, откуда ни возьмись, целое стадо отвратительных троллей! Конечно, я постарался убраться оттуда как можно быстрее. Еле выбрался, однако прихватил с собой вот этот сувенир. Держите, отнесете его Брохану и расскажете, что храм этот его – там, под водой. Ик!', 'Отнесите фрагмент таблички Атал\'ай Брохану Бочкопузу в Штормград. ', 'Рапсод Землекоп! Точно! Как я мог забыть такое имя?$B$BТак он все это время знал о том, что храм затонул? Что ж, это точно сэкономит вам время.$B$BНо предмет, сделанный Атал\'ай... Вот это находка!', 'Наконец-то вы вернулись, $N! Давненько мы не виделись, я было подумал, что вы забыли о моем поручении...$B$BВы нашли этого хитроумного всадника? Он что-нибудь сказал?', NULL, NULL, 'Фрагмент таблички Атал\'ай (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1470, 'Приоткрывая завесу', '', '', 'Хотя ты еще не прошел испытаний и находишься в самом начале ученичества, ты доказал, что силы у тебя достаточно, чтобы суметь призвать беса и подчинить его своей воле. Пусть тебя не обманывают его небольшие размеры. Физической силы ему не хватает, зато хватит магического могущества и разума, чтобы хорошо служить тебе.$B$BСлушай меня внимательно, $N, потому что повторять я не буду, и тогда придется все осваивать самостоятельно.', 'Твои силы пока малы, но мне кажется, что ты уже начинаешь ощущать скрытые возможности. $B$BДаже мертвый может почувствовать себя живым, когда эта сила циркулирует в нас.', NULL, NULL, 'Череп гремучего скелета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1471, 'Связывание', 'Ты наверняка уже $gвидел:видела: круг призыва. Только в его пределы ты можешь вызвать демона Бездны.$B$BПри помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии.$B$BПодчиненный демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва. Ты сможешь пользоваться им, когда захочешь.', 'При помощи рун призыва вызовите и подчините себе демона Бездны, а потом верните руны призыва Карендину Халгару в Квартале магов Подгорода.', 'Великолепная работа, $N. Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны.$B$BТы сможешь обратить силу, которую недавно испытал на себе, против своих врагов.', 'Надеюсь, ты преуспеешь в своих начинаниях, $N. Впрочем, если тебе не удастся задуманное, мое недовольство покажется тебе сущим пустяком.', NULL, NULL, 'Призванный демон Бездны убито', 'Руны Призыва (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1472, 'Пожиратель Душ', 'Сайаады – пожиратели душ, разбивающие сердца и вводящие в искушение. Существа, исполненные зла и изощренной хитрости.$B$BСказания из уст что праведников, что грешников говорят одно: их женщин называют суккубами, а мужчин – инкубами.$B$BПросто так их в наш мир не выманишь. Сайаад не сможет устоять перед сердцами добрых и любящих смертных. Когда он явится в Азерот, можно побороть его и подчинить себе.$B$BСтупай в храм и поговори с моим помощником Годриком Фарсаном. Он поможет тебе подобрать приманку.', 'Поговорите с Годриком Фарсаном в Храме Проклятых. ', 'Тебя прислал Карендин? Говоришь, ты $N?$B$BНе думай, что я просто беспомощный слепец. Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1473, 'Создание Бездны', 'Похоже, ты $gготов:готова: призвать демона Бездны.$B$BЭти твари появляются из Круговерти Пустоты, лежащей за пределами мира. Если ты не сможешь подчинить себе вызванного демона, он разорвет тебя на части.$B$BПервого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре.$B$BК сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями.', 'Найдите гримуар Эгалина и отнесите его Карендину Халгару в Храм Проклятых.', 'А, великолепно. Вероятно, Перрин не догадывался, какие знания скрывает в себе этот фолиант.$B$BМы больше не допустим хищения книги. Смотри: вот схема заклинания, объясняющая, как следует направлять энергию.', 'Эгалин был моим учителем. Он повелевал вызванным им демоном Бездны без малейших затруднений.$B$BКогда пришел мой черед подчинить себе эту тварь, я был слишком самоуверенным. Не обманывайся своим мнимым могуществом, $N, с этой тварью ни на секунду нельзя терять бдительности.', NULL, NULL, 'Гримуар Эгалина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1474, 'Связывание', 'При помощи этих сердец наложи заклинание на круг призыва, чтобы открыть дверь в наш мир для суккуба. Твои силы возросли, и они понадобятся тебе, чтобы одолеть демоницу.$B$BОстерегайся ее чар, $N, даже сила воли может не защитить от них. Если ты победишь, суккуб вернется в Бездну, а я научу тебя заклинанию, которое позволит тебе вызывать ее в любой момент.', 'При помощи чистых сердец призовите и подчините суккуба, а потом верните чистые сердца Карендину Халгару в Квартале магов Подгорода.', 'И снова ты справился с заданием. Давно мне не встречались чернокнижники с такими задатками. Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям.$B$BА теперь я хочу научить тебя заклинанию призва личного суккуба.', 'Суккуб – один из самых опасных обитателей Бездны, поскольку быстро подчиняет себе слабых духом.$B$BНикогда не забывай об этом.', NULL, NULL, 'Призванный суккуб убито', 'Чистые сердца (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1475, 'В храм Атал\'Хаккар', 'Храм Атал\'Хаккар посвящен древнему божеству Хаккару Свежевателю Душ. Храм охраняет злобное племя троллей Атал\'ай, и он, если верить слухам, неприступен.$B$BТеперь, когда он затонул, добывать в нем артефакты стало еще сложнее. Но это именно то, о чем я тебя прошу, $N.$B$BПомоги мне собрать целые таблички Атал\'ай. Принеси их мне, и я вернусь в Лигу исследователей героем. Вместе мы добьемся успеха!', 'Соберите 10 табличек Атал\'ай для Брохана Бочкопуза из Штормграда.', 'Таблички Атал\'ай! Благодарю, $N!$B$BКогда я доставлю их в Лигу Исследователей, наши имена войдут в историю. Вы помогли старому дворфу выполнить его последнее задание, и я бесконечно признателен вам за это!', 'Поскольку для меня наступили не лучшие времена, я обращаюсь к вам, $N. Если б только мои старые кости позволяли мне преодолеть Болото Печали и добраться до затопленного храма, я бы непременно сражался рядом с вами!$B$BВ былые времена гордость не позволила бы мне просить вас о помощи, но ныне я слишком стар, чтобы справиться сам. Прошу, помогите мне! Я хочу уйти в отставку, выполнив последнее поручение Лиги Исследователей.', NULL, NULL, 'Табличка Атал\'ай', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1476, 'Чистые сердца', 'Чтобы поймать суккуба, нужно чистое сердце. Но разве остались среди смертных непорочные сердца?$B$BПосле долгих поисков и расспросов мне удалось найти только двоих.$B$BПервый из них – Далин Искусник. Он посвятил свою жизнь заботе о лордеронских беженцах, которых отказалась принять родня в Стене Седогрива.$B$BВторая – Корма Виллард. Она верна своей утраченной привязанности и бродит по Болотине в поисках подруги.$B$BПринеси их сердца Карендину. Но сначала я покажу тебе твои жертвы.', 'Принесите сердца Далина Искусника и Кормы Виллард Карендину Халгару в Храм Проклятых.', 'А с виду доброе сердце ничем не отличается от любого другого, да?$B$BМожет быть, мы просто... по-другому смотрим на мир. Но эти сердца прекрасно подойдут. Не сомневаюсь, их чистота привлечет суккуба.', 'Я приятно удивлен тем, как быстро ты справляешься с заданиями, $N. Принеси мне сердца, и я преисполнюсь еще большего уважения.', NULL, NULL, 'Сердце Далина', 'Сердце Кормы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1477, 'Важные поставки', 'Наши маги проводят исследования в крепости Стражей Пустоты, в Выжженных землях – исследования, жизненно важные для понимания Темного портала. Они почти постоянно требуют поставок, однако доставлять что бы то ни было в крепость крайне сложно.$B$BМы просим твоей помощи в обеспечении прибытия поставок в крепость Стражей Пустоты. Сдай рапорт начальнику стражи Соригелу в Темнолесье и сделай то, о чем он попросит. Но это задание приведет тебя во враждебные земли, $N. Приготовься к любым опасностям.', 'Поговорите с начальником стражи Соригелом в Темнолесье, что в Сумеречном лесу.', 'Тебя послал Андромах? Очень хорошо. У меня для тебя важное задание...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1478, 'Призыв Халгара', 'А, $N! Я только что получил новости от Карендина Халгара – он хочет поговорить с вами насчет дальнейшего обучения.$B$BМожете гордиться собой! Не каждый день мастер Халгар решает самолично проинструктировать юного чернокнижника.$B$BЕго можно найти в Квартале Магов Подгорода, возле Храма Проклятых.', 'Поговорите с Карендином Халгаром в Подгороде. ', 'Хорошо, я вижу, Агерон нашел вас, $N. Давайте не будем тратить время на болтовню и церемонии, а сразу же перейдем к вашему обучению. Вам еще очень много надо узнать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1479, 'Купина Вечности', 'Я слышал, что ночные эльфы устроили банк прямо внутри дерева, которое похоже на медведя! Круто! Ночные эльфы очень милые, а как они любят природу! Но медведи – это совсем здорово!$B$BСводи меня посмотреть на древо-медведя в Дарнас! Пожалуйста! Мы можем доплыть туда на корабле, много времени это не займет. Пожалуйста, пожалуйста, пожалуйста!', 'Отведите сироту к банку Дарнаса. Банк находится в дупле дерева, которое называется Купина Вечности.', '', NULL, NULL, NULL, 'Исследовать локацию', 'Ступайте в банк Дарнаса, известный также как Купина Вечности.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1480, 'Осквернитель душ', 'Рваная шкура пахнет гнилью, и она на удивление мягкая и гибкая для такого сухого и хрупкого на вид материала.$B$BЕсли ее развернуть, на ней видны красные письмена на непонятном наречии. А внизу – очень отчетливый отдельный символ, должно быть, подпись.$B$BМожет быть, Морин сумеет объяснить, что это такое?', 'Отнесите рваную шкуру демона Морину Костолому в Пустоши.', 'Да, $N, это действительно чужой язык, и весьма древний. Он отчасти напоминает эредан, но отличия несомненны. Если не ошибаюсь, это нечто вроде договора... Да, вот этот символ – подпись демона: лорд Азреток.', 'Чернокнижники Пылающего Клинка начинают понимать, насколько они бессильны. Их магия не внушает ничего, кроме презрения.$B$BВсей своей силой они обязаны тем, кому служат, а вовсе не истинному знанию и пониманию законов магии.', NULL, NULL, 'Рваная шкура демона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1481, 'Осквернитель душ', 'Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты.$B$BОднако если он действительно так могуществен, мне понадобятся предметы, собранные со смертельно опасных тварей...$B$BПрежде всего мне придется снять заклятия, которые защищают его от соглядатаев. Для этого нужен скальп сатира, но не первого попавшегося, а тенелова племени Ярой Ненависти.$B$BИщи их в древних развалинах на северо-востоке Пустошей.', 'Принесите скальп тенелова Морину Костолому в Пустошах.', 'Что, $С, тенеловы тебя не убили? Неплохо, очень неплохо.$B$BДа, этот скальп мне подходит. Пока тебя не было, мне удалось собрать остальные необходимые реагенты.$B$BЯ почти готов. Мне необходима только точка приложения заклинания – тот предмет, в котором мы увидим повелителя демонов и место, где он находится.', 'Смотри, $C, принеси именно тот скальп, что надо! Мы оба погибнем, если используем неправильные реагенты. Повелитель демонов наверняка защищен заклинаниями, которые убивают непрошеных соглядатаев!$B$BДовольно с меня былых мучений.', NULL, NULL, 'Скальп тенелова', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1482, 'Осквернитель душ', 'Кристалл оракула нам подойдет. Их делают наги для своих оракулов.$B$BК северо-западу отсюда, на побережье, есть обширный коралловый риф, где поселились наги. Там можно найти и оракулов. Но Скользящий Плавник смертельно опасен и встретит тебя отнюдь не с распростертыми объятиями. Так что смотри, осторожнее, и постарайся убраться оттуда побыстрее.$B$BА когда вернешься, мы попробуем отыскать этого лорда Азретока.', 'Принесите кристалл оракула Морину Костолому в Пустоши.', 'Драгоценный кристалл оракула! Безупречный... великолепный…$B$BЧто ж, начнем немедленно. Нам следует отыскать этого повелителя демонов.$B$BОтступи на шаг, $C, и давай посмотрим, как выглядит Азреток и где его искать.', 'Мне нужен кристалл оракула, $C. Если мы найдем и уничтожим этого лорда Азретока, вождь будет весьма признателен нам обоим. Так что давай работать вместе, чтобы быстрее управиться с этим делом и добиться расположения вождя.', NULL, NULL, 'Кристалл оракула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1483, 'Зиз Физзикс', 'Торговая Компания переманила лучшие гоблинские умы, но порой у нас появляется возможность вернуть свое. $B$BНекоторое время назад подразделение Торговой Компании в Когтистых горах приняло на работу Геренцо Терминатрикса – гнома! Это так ошарашило другого инженера, Зиза Физзикса, что он умолял меня найти ему новую работу в Союзе ремонтников. Я дал ему несколько заданий, но ему может понадобиться помощь.$B$BНе навестишь его? Он живет у западного края Утеса Ветрорезов.', 'Поговорите с Зизом Физзиксом на Утесе Ветрорезов, что в Когтистых горах.', 'Я думал, что начальство Торговой Компании – настоящие тираны, но потом я познакомился с Пароклапаном, он хуже их всех!$B$BХа! И все же это лучше, чем сидеть без работы... Или, хуже того, работать с этим Геренцо. Если ты хочешь мне помочь, дело для тебя найдется.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1484, 'Осквернитель душ', 'Это существо куда опаснее, чем мне казалось! Неудивительно, что Таката сомневается, что мне удастся его одолеть. Он будет оскорблен, если не сообщить ему о том, что случилось.$B$BПоговори с мечником, скажи, что хочешь убить демона, если он разрешит, но особо не настаивай. Пусть думает, будто это его собственная идея.', 'Поговорите с Такатой Стальным Клинком в Пустошах. ', 'Да, я видел, что только что произошло между Майрином и повелителем демонов! Похоже, это существо, даже в видении, обладает куда большим могуществом, чем мой соратник-чернокнижник. Сумеет ли он одолеть этого монстра? Лучше бы я занялся этим сам... Но вождю я нужен здесь. Я опозорю свой клан, если оставлю свои здешние обязанности и отправлюсь добывать себе славу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1485, 'Злобные фамильяры', '', '', 'Во время обучения ты научишься вызывать самых разных существ. Все они по-своему полезны, даже если на первый взгляд это не очевидно.$B$BПусть малый рост беса тебя не смущает. Ты уже знаешь, как опасны они бывают.', 'Важно уметь контролировать существ, которых ты будешь призывать с помощью магии. Интересующихся ремеслом чернокнижников и так мало, поэтому я не позволю тебе рисковать жизнью прежде, чем увижу, что ты к этому готов.', NULL, NULL, 'Голова злобного фамилиара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1486, 'Шкуры загадочных существ', 'Пока Наралекс погружался в свои кошмары все глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные.$B$BЭти искаженные существа наделены странными, потусторонними силами. В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре. Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее.$B$BЕсли эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искаженных шкур.', 'Принесите 20 искаженных шкур Налпаку в Пещерах Стенаний.', 'Твои услуги не останутся незамеченными. Протеже.$B$BСпасибо тебе за твою неоценимую помощь.', 'Я весьма заинтересован в том, чтобы исследовать шкуры этих тварей, наводнивших Пещеры Стенаний. Как успехи, $C?', NULL, NULL, 'Искаженная шкура', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1487, 'Искоренение Скверны', 'Цели у Наралекса были самые благие.$B$BНаш лидер стремился впасть в Изумрудный Сон, и вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так.$B$BМечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры.$B$BВ то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей.$B$BОтправляйся туда, $N. и уничтожь порченое семя.', 'Убейте для Эбру 7 загадочных опустошителей, 7 загадочных гадюк, 7 загадочных шаркунов и 7 загадочных страхозубов.', 'Как послушник Наралекса я не могу не отметить твоей храбрости. Твоя помощь – это всего лишь первый шаг в очищении Степей от порчи.$B$BБлагодарю тебя, и да пребудет тобой удача.', NULL, NULL, NULL, 'Загадочный опустошитель убито', 'Загадочная гадюка убито', 'Загадочный шаркун убито', 'Загадочный страхозуб убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1488, 'Осквернитель душ', 'Я ничего не знаю об этом владыке Азретоке, однако согласен с Морином: его следует остановить, особенно если он пытается подчинить себе клан Пылающего Клинка.$B$BТвое стремление служить вождю уже не требует доказательств, и я готов доверить тебе собрать отряд, чтобы убить Азретока и его слугу чернокнижника.$B$BКогда подготовишься, отправляйся на юг, а покончишь с ними – возвращайся ко мне.', 'Убейте лорда Азретока и Джуккара Грим\'рода и вернитесь к Такате Стальному Клинку в Пустоши.', 'Эта победа очень важна для нас, $N. Все мы радуемся вашему успеху. Теперь я думаю, что наше будущее не так беспросветно, как мне казалось.$B$BДемоны будут повержены, Пылающий Клинок потерпит крах, и в один прекрасный день у нас снова будет свой дом!', 'Слава Орде! Смерть врагам!$B$B$N, демоны Пустошей сейчас сделались опаснее, чем когда бы то ни было. Моя надежда вернуться к вождю тает: этих злобных тварей становится все больше и больше!$B$BАх, если бы нам приходилось иметь дело с одними только кентаврами!', NULL, NULL, 'Лорд Азреток убито', 'Джугкар Грим\'род убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1489, 'Хамуул Рунический Тотем', 'На раковинах, что ты мне принес, присутствует порча, которой я никогда раньше не видел. Я уверен, что причины ее возникновения кроются в воде оазиса, и я уже предчувствую, чем это грозит этим землям.$B$BИсточник этой порчи в Пещерах Стенаний, но прежде чем отправиться туда, поговори с Хамуулом Руническим Тотемом, старшим друидом. Я послал ему весточку о том, что творится в Степях. Он мудр и сможет дать тебе дельный совет.$B$BНайдешь его в Громовом Утесе, на Вершине Старейшин.', 'Поговорите с Хамуулом Руническим Тотемом.', 'Приветствую тебя, $N, добро пожаловать. И лучше бы тебе собрать всю волю в кулак, потому что дело, порученное тебе, будет крайне нелегким.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1490, 'Нара Буйногривая', 'Я вошел в сновидения и увидел там орден друидов, обитающих в Пещерах Стенаний. Когда-то их цели были благородными. Но теперь они отклонились от первоначального пути и стали слугами порчи просачивающейся из Степей.$B$BЯ уже стар, и мои силы не бесконечны. Я не мог дольше оставаться в сновидениях, хотя и хотел узнать больше об этих друидах. Но Нара молода и сильна духом, и она осталась там, когда я вынужден был уйти.$B$BПоговори с ней, $N, ты найдешь ее в дальней палатке.', 'Поговорите с Нарой Буйногривой.', 'Все верно, я знаю о друидах из Пещер Стенаний. Я видела их исковерканные, покрытые чешуей лица. Я знаю об их злодеяниях, и самое главное, мне известны их планы.$B$BТы должен остановить их, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1491, 'Умный напиток', 'Ладно, рога ящеров не подошли. Ничего страшного, с первого раза никому не удается разбогатеть. Кроме того, мне удалось придумать кое-что получше! $B$BСуществует вещество, именуемое воющей субстанцией, и мне кажется, именно из-за него в Степях такие странные растения и животные. Принеси мне немного субстанции, и я попробую добавить ее в напиток!$B$BНасколько я знаю, это вещество накапливается в эктоплазматических существах в Пещерах Стенаний на западе. Убей несколько существ из пещер и собери из них субстанцию.', 'Принесите 6 порций воющей субстанции Мебоку Миззриксу в Кабестан.', 'Здорово, ты принес ее! Не терпится опробовать напиток. Я знаю, он принесет мне много денег!$B$BСпасибо, Слантер. Вот тебе деньги, и, разбогатев, я пришлю тебе еще, клянусь!', 'Где моя воющая субстанция?', NULL, NULL, 'Воющая субстанция', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1492, 'Управляющий пристанью Головокружилкинс', 'Мне нужно послать ящик зелий, реагентов и прочего своим партнерам из Старого Света. У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл.$B$BНе $gмог:могла: бы ты отнести ящик управляющему пристанью Головокружилкинcу? А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья.', 'Отнесите надежный ящик управляющему пристанью Головокружилкинcу в Кабестан.', 'Небольшой ящик. Да, пожалуй, для него найдется место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно. Надо только записать его в мой регистр.$B$BНу вот, все готово. Пока, $C.', 'Желаешь отплыть на ближайшем корабле или послать товар на ту сторону света?', NULL, NULL, 'Надежный ящик (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1498, 'Путь защиты', 'Одна из основных задач воина... защита. Мы – щит Орды, заслоняющий собой наших более слабых братьев. Если ты хочешь вступить в наши ряды, докажи мне, что не струсишь.$B$BСтупай в Дуротар, на Громовой хребет, где живут бурешкуры и рокочущие ящерицы. Поохоться на них, докажи, что ты сильнее их! Выстой против них и принеси мне в доказательство побольше оплавленных чешуек.$B$BКак только принесешь, я возьмусь тебя учить.', 'Принесите 5 оплавленных чешуек Уззеку на Дальнюю заставу в Степях.', 'А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкий парень. А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости.$B$BУчись хорошенько, $N. Вскоре тебе предстоит новый урок.', 'Ну как, принес чешуйки? Если ты не можешь выстоять против рокочущих ящериц, я не буду тебя учить.', NULL, NULL, 'Оплавленная чешуя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1499, 'Злобные фамильяры', 'Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамильярами.$B$BДумаю, тебе не помешает набраться опыта, помогая Зурите. Не забудь ей сказать, что ты $gпомогал:помогала: разобраться с бесами – возможно, у нее найдется для тебя награда.', 'Поговорите с Зуритой Востроглазой.', 'Молодец, $N!$B$BДа, злобные фамильяры для воинов Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предсказывает тебе великие дела!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1500, 'Пробуждение Наралекса', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1501, 'Создание Бездны', 'Чернокнижников осталось так мало... Мы многим рискуем, но наш риск оправдан! Если ты хочешь принести пользу Орде и вождю, пора тебе научиться новому заклинанию призыва.$B$BДля начала добудь табличку Верги. Чернокнижники из клана Пылающего Клинка похитили ее и хранят у себя в логове, под скалой Черепа к востоку от города. После этого я покажу тебе руны, необходимые для призыва демона Бездны.', 'Добудьте табличку Верги для Ган\'рула Кровавого Глаза в Оргриммаре.', 'Молодец. Надеюсь, во время твоего визита в логово чернокнижники из клана Пылающего Клинка сильно пострадали?$B$BОни причинили немало вреда вождю, да и нам, чернокнижникам, тоже.', 'Ну что, $N, табличка Верги у тебя? Пока ты ее не добудешь, я с тобой и разговаривать не стану!', NULL, NULL, 'Табличка Верги', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1502, 'Тун\'грим Огневзор', 'Воину пристало владеть хорошим оружием. Самое лучшее оружие делает орк по имени Тун\'грим Огневзор. Это отшельник, который живет на вершине холма к востоку от Перекрестка.$B$BЕсли тебе нужно оружие, воин, отправляйся к Тун\'гриму. Чтобы добраться до его жилища, дойди до Перекрестка и сверни на восток, в сторону холмов. Он разбил лагерь на самой вершине.', 'Поговорите с Тун\'гримом Огневзором из Степей.', 'Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу. Например, тебе что-то от меня нужно.$B$BИ раз ты добрался до моего жилища, то я могу предположить, что именно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1503, 'Стальные слитки', 'Я дам тебе оружие, $N, но прежде помоги мне. Несколько дней назад с северо-запада на меня напало племя Иглогривых. Биться со мной они побоялись, но зная, какое у меня плохое зрение, одни отвлекли меня своим пофыркиванием, а другие ограбили мой лагерь! Трусы!$B$BОни украли железный сундук, в котором лежали стальные слитки. Если ты сможешь вернуть их, я дам тебе нужное оружие.$B$BНайди мой сундук в одном из лагерей иглогривов и принеси мне стальные слитки.', 'Принесите стальные слитки Тун\'гриму Огневзору из Степей.', 'Вот они! И все мои слиточки на месте, что и неудивительно. Откуда иглогривым знать, что делать с такой отличной сталью.$B$BСпасибо, $N. Вот твоя награда. Пусть она служит тебе верой и правдой.', 'Ты принес мне стальные слитки?', NULL, NULL, 'Стальные слитки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1504, 'Оковы', 'Посмотри на табличку Верги. Изображенные на ней знаки понадобятся тебе для призыва. Отнеси это в круг в шатре Ниру Огненного Клинка на другом конце пещеры. Там ты сможешь вызвать демона Бездны.$B$BТебе нужно будет одолеть его любыми физическими и магическими средствами. А после этого возвращайся ко мне со знаками призыва, и я покажу тебе, как подчинить это существо своей воле.', 'Используя знаки призыва, призовите и подчините своей воле демона Бездны. Верните знаки призыва Ган\'рулу Кровавому Глазу в Оргриммаре.', 'Молодец, $N! Я покажу тебе, как вызывать демона Бездны, подобного тому, которого тебе только что пришлось одолеть.$B$BЗнай, мы на тебя очень рассчитываем, и пока что ты оправдываешь все наши надежды!$B$BОднако пусть успех не кружит тебе голову. Впереди куда более сложные задачи!', 'Демон Бездны – создание могущественное! Я помню, как боролся с ним, когда был в твоем возрасте, $N. С годами мой демон стал меньше сопротивляться – но подозреваю, он просто надеется, что я утрачу бдительность.$B$BНе забывай этого, $N!', NULL, NULL, 'Призванный демон Бездны убито', 'Знаки Призыва (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1505, 'Ветеран Уззек', 'Орда чтит своих воинов, потому что никто не сомневается в их силе. Но истинному величию чуждо самодовольство. Никогда не упускай случая поучиться новому.$B$BОтыщи Уззека. Он прошел через много сражений и теперь обучает молодых воинов боевым приемам. Он живет к югу от Форпоста, орочьего гарнизона на границе Степей и Дуротара.', 'Поговорите с Уззеком в Форпосте в Степях.', 'Привет, юноша. Ты учиться пришел?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1506, 'Призыв от Ган\'рула', 'Эй, ты! Ты ведь $N, верно?$B$BНадеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул. Ты найдешь его среди старших чернокнижников в расселине Теней.$B$BНасколько я знаю Ган\'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое.', 'Найдите Ган\'рула Кровавого Глаза в Оргриммаре и поговорите с ним.', 'Ага, хорошо. Я опасался, что Офек не сумеет с тобой связаться.$B$BТебе пора продолжить свое обучение на чернокнижника. Все прочие дела пока отложи.$B$BНадеюсь, с этим проблем не будет?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1507, 'Пожиратель Душ', 'Пора тебе научиться новому колдовству. Ты научишься вызывать сайаада, чьи чары порабощают разум. Это существо способно зачаровывать и подчинять себе слабых духом. Но не бойся! Я уверен, тебя ему не одолеть.$B$BЧтобы приманить сайаада, нужен предмет, в котором воплощена искренняя любовь и преданность. Тебе нужно найти такую вещь.$B$BГде? Ну, потолкуй с Казулом. Чего не знает этот старый чернокнижник, того и знать не стоит.', 'Поговорите с Казулом в расселине Теней.', 'Хм... $N. Ты еще новичок, но я чую в тебе большие способности.$B$BУ тебя врожденный дар к чернокнижию, $N. Такими вещами не разбрасываются.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1508, 'Слепой Казул', 'Раз Ган\'рул отправил тебя ко мне, ты, должно быть, хочешь вызвать суккуба, женщину-сайаад, и ищешь приманку... Ну, если ты $gготов:готова: довериться слепому поводырю, $N, то слушай. Среди утесов Оргриммара, к западу от башни ветрокрылов, живет Занкайя. Она ждет, когда к ней вернется близкий друг. Ступай к ней.', 'Поговорите с Занкайей в Оргриммаре.', 'У тебя есть весточка от Дограна? Он должен был вернуться уже несколько дней тому назад, а о нем до сих пор ни слуху, ни духу...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1509, 'Вести о Догране', 'Моего супруга, Дограна, не так давно отправили служить в Перекресток. Это было повышение по службе, он так гордился…$B$BМне, конечно, было грустно, но ему я этого не показывала. Грустно и тревожно. Степи – не Оргриммар, это опасное место, и я боялась худшего…$B$BОн должен был вернуться неделю назад, а от него до сих пор нет никаких вестей!$B$BМожет, ты сходишь в Перекресток, разузнаешь о нем? Он служил вместе с Газрогом, и Газрог, наверное, до сих пор там...', 'Поговорите с Газрогом в Перекрестке.', 'Занкайя? Жена Дограна, да?$B$BСлышать-то я о нем слышал, но это не те новости, которые стоит ей передавать.$B$BДа нет, не убили его. Но он ранен и сейчас в плену у иглогривов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1510, 'Вести о Догране', 'Он был в Лагере Таурахо, где мы пытались извести иглогривов. Он повел нескольких рубак на одно из их стойбищ, и там его тяжело ранили. Остальные вернулись и попытались его выручить. Но он был в плохом состоянии, раны загноились, и ребята побоялись его трогать.$B$BОни отправили сюда послание, просили троллей из Малака\'джина у Когтистых гор прислать целительное зелье. Мы послали за зельем, но гонец пока не вернулся.', 'Поговорите с Кен\'зиглой в Малака\'джине. ', 'Орк? Надеюсь, ты не за тем, другим? А то он добрался не очень... благополучно. Общение с гоблинами не довело его до добра.$B$BОн успел сказать, что приехал за целительным зельем, но больше ничего вразумительного.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1511, 'Зелье Кен\'зиглы', 'Я так и думал, что за зельем явится кто-нибудь еще!$B$BВот оно, $N, бери. Имей в виду, сразу все ему не давай, пусть выпьет половину! Этого ему хватит, чтобы передвигаться. А иначе он истечет кровью. На следующее утро пусть выпьет вторую половину.$B$BОтнеси это Логмару в Лагерь Таурахо. Судя по тому, что сказал мне первый гонец, Логмар знает, где Догран.', 'Отнесите зелье Кен\'зиглы рубаке Логмару в Лагерь Таурахо.', 'О, как нельзя более кстати! А то Догран уже умирает там, в плену.$B$BЭто нужно доставить ему немедленно. Но большинство моих рубак сейчас на задании...', 'Да, чего тебе?', NULL, NULL, 'Зелье Кен\'зиглы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1512, 'Дар любви', 'Занкайя молода и красива. Зачем ей калека? Несправедливо это будет.$B$BОставь меня, $N. Спасибо тебе. Я предпочел бы умереть в славной битве, а не влачить это жалкое существование.$B$BИ прошу тебя, не говори об этом моей супруге... Не хочу, чтобы она чувствовала себя виноватой.', 'Отнесите подвеску, испачканную грязью, Ган\'рулу Кровавому Глазу в Оргриммар.', 'Ну, если ты говоришь, что этого достаточно, я тебе верю, $N. Дай-ка я ее оботру... Да, вот такая, блестящая и чистенькая, она будет куда соблазнительней для суккуба.', 'А, вот и ты! Ну что, готов встретиться с суккубом?', NULL, NULL, 'Подвеска, испачканная грязью (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1513, 'Оковы', 'Отнеси это к кругу призыва в шатре Ниру, $N. Вызови гнусного суккуба и покажи ему, кто здесь хозяин. Я верю в силу твоей магии. Но все же будь осторожнее: гордость и самоуверенность погубили немало многообещающих чернокнижников.$B$BКогда подчинишь суккуба, верни подвеску мне. Нужно будет сообщить Занкайе о случившемся.', 'Призовите и подчините суккуба с помощью подвески Дограна. Верните подвеску Ган\'рулу Кровавому Глазу в Оргриммаре.', 'Получилось! Впрочем, я ничего другого и не ждал, ведь ты – мой лучший ученик.$B$BТеперь я с радостью покажу тебе, как вызывать усмиренного суккуба. Ступай, тебе многому нужно научиться. Я рассчитываю, что к нашей следующей встрече ты уже по-настоящему подчинишь своего суккуба.$B$BС печальной историей Дограна и Занкайи разберутся те, кто постарше тебя. Но ты ее не забывай: она послужит хорошей защитой от хитростей темного демона, который явился к тебе сегодня.', 'Когда я вижу суккуба, мое сердце поет... Но в то же время я буквально чувствую, как моя душа иссыхает, утекает, как песок между пальцев.$B$BБудь осторожнее!', NULL, NULL, 'Призванный суккуб убито', 'Подвеска Дограна (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1514, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1515, 'Догран в плену', 'Ну, раз уж ты здесь и хочешь завершить свое дело, останавливать тебя я не буду. Но своих воинов я с тобой отпустить не cмогу, ступай в одиночку.$B$BДограна держат в лагере иглогривов, к северу отсюда. Ищи две хижины, стоящие рядом. Иглогривы его стерегут – если, конечно, его еще не убили, или он не умер от ран.$B$BУдачи тебе!', 'Отнесите зелье Кен\'зиглы Дограну в Степях.', 'Тьфу, гадость…$B$BОднако сил у меня прибавляется. Пожалуй, я теперь смогу уковылять отсюда... Однако похоже, что ногу мне придется отнять. И руку тоже.', 'Ууф-ф...', NULL, NULL, 'Зелье Кен\'зиглы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1516, 'Зов Земли', 'Что ж, $C, пора! Ты $gнабрался:набралась: сил, твой дух стоек, как сама Земля. А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости.$B$BСтихия земли будет управлять твоей судьбой, станет частью тебя. $gГотов:Готова: ли ты? Тебе придется предстать перед самой Землей. И тогда ты увидишь многое, что ведомо лишь шаманам.$B$BРазыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твое будущее.', 'Принесите Канаге заклинателю земли 2 копыта ловцов Скверны.', 'Великолепно! Твой успех доказывает: ты действительно готов.$B$BСреди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твое терпение. Земля защитит тебя, если ты будешь относиться к ней с должным почтением. Но и Земля, как все прочие стихии, может быть своенравной.$B$BТеперь я сделаю для тебя сапту. Прими ее – и постигнешь свой путь!', 'Терпение – вот величайшая добродетель! Все на земле меняется: горы превращаются в пустыни, реки становятся ущельями. И лишь сама Земля остается неизменной. Она не любит нетерпеливых.$B$BТеперь Земля зовет тебя: приближается время решительной схватки! Когда ты достигнешь успеха и вернешься ко мне, ты будешь куда ближе к целостности.$B$BДругие будут завидовать твоей мудрости и ненавидеть тебя за свое невежество.', NULL, NULL, 'Копыто ловца Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1517, 'Зов Земли', 'Сапта – это напиток, который связывает душу со стихией. Сама магия растворена в нем. И сильные духом благодаря ему способны зреть стихии, которых никто более не видит. Твой дух будет связан со стихией сапты. Лишь немногие избранные шаманы знают рецепт этого напитка.$B$BЗапомни: сапту можно пить лишь в священном месте, и нигде более!$B$BОтыщи Священный Камень к юго-западу отсюда. Он находится в конце Потайной тропы. Выпей там сапту, а дальше... увидишь!', 'Найдите Священный Камень и выпейте рядом с ним сапту Земли.', 'Ах... $N... Земля ликует от того, что ты пришел сюда. $B$BТеперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твое терпение, и весь мир – основа твоей сущности. $B$BДля прохождения этого обряда довольно было смиренно предстать перед землей. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1518, 'Зов Земли', 'Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались. Он создаст тотем для тебя, и этот камушек будет сердцем тотема. Он невелик, но со временем ты поймешь, что размер не имеет значения. Иногда малое оказывается долговечнее большого.$B$BБудь $gтерпелив:терпелива:, $N. Оставайся $gсильным:сильной:. И ищи мудрости. В конце концов ты станешь единым целым с Землей – чти же ее, и она будет чтить тебя.', 'Отнесите необработанный кварц Канаге заклинателю земли в долину Испытаний.', 'Великолепно!$B$BТотем, который я создам для тебя, – не просто символ нового статуса. Он обладает тайными возможностями. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретешь, тем больше способностей земли станет тебе доступно.$B$BНаставники скажут тебе, когда ты будешь готов к новым знаниям.$B$BА пока возьми этот тотем Земли.', 'Вот ты и встал на первый из четырех путей, которые в конце концов приведут тебя к твоему предназначению!$B$BЕсли у тебя с собой тот камушек, что дала тебе Земля, ты получишь от меня обещанный тотем.$B$BА если нет – убирайся до тех пор, пока не обретешь путь!', NULL, NULL, 'Грубый кварц (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1519, 'Зов Земли', 'Время настало, $gюный:юная: c: $C. Тело твое возмужало, а дух закалился, как сама земля. Я вижу, ты $gобрел:обрела: мудрость.$B$BЗемля ведет и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придется пройти испытания. Если ты $gготов:готова:, твоему взору откроется то, о чем известно лишь нашему народу. $B$BНайди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах. Возвращайся ко мне, когда соберешь достаточно мази для изготовления зелья.', 'Принесите 2 порции ритуальной мази провидице Воронье Перо в Лагерь Нараче.', 'Отлично, $N. Ты вернулась – а значит, готова к следующему шагу. $B$BСтихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твое терпение. Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя ее законам, ты приумножишь мудрость. Никогда не забывай тайны, которые она разделит с тобой. $B$BТеперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути.', 'Земле не занимать терпения, она будет ждать, покуда ты не будешь готова, ибо она знает, что с течением времени все разрушается и возрождается вновь. Это круговорот бытия. Горы превращаются в пустыни, реки становятся каньонами. Земля – самая упрямая и самая мудрая из стихий.$B$BТы должна прежде всего научиться терпению и выносливости. Земля призывает тебя, потому что знает – ты готова. Если ты преуспеешь, то родишься заново и навсегда распрощаешься со своим невежеством.', NULL, NULL, 'Ритуальное зелье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1520, 'Зов Земли', 'Сапта – это напиток, призванный объединить твой дух со стихиями. Сотворенное с помощью магии зелье позволит тем, чье сознание открыто, видить стихии так, как их никто не видел ранее. Твой дух будет навеки связан со стихией, для которой был создан сапта – и лишь немногим из нашего племени известен секрет его изготовления. $B$BСапта должна быть выпита в только в священном месте и более нигде. $B$BНайди шаманское святилище к востоку отсюда и выпей сапту там.', 'Найдите Дольмен Кодо и выпейте сапту земли.', 'Ах... $N... Земля ликует от того, что ты пришел сюда. $B$BТеперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твое терпение, и весь мир – основа твоей сущности. $B$BДля прохождения этого обряда довольно было смиренно предстать перед землей. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1521, 'Зов Земли', 'Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой. Она создаст для тебя тотем, и этот камень станет его сердцем. Тебе может показаться, что он мал, но со временем ты поймешь, что размер не имеет значения. Иногда малое оказывается долговечнее большого.$B$BБудь $gтерпелив:терпелива:, $N. Оставайся $gсильным:сильной:. И ищи мудрости. Так угодно земле. В конце концов ты станешь единым целым с землей – чти же ее, и она будет чтить тебя.', 'Отнесите грубый кварц провидице Воронье Перо в Лагерь Нараче.', 'Прекрасно! $B$BТотем, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретешь, тем больше способностей земли станет тебе доступно.$B$BНаставники в Калимдоре скажут тебе, когда ты будешь готов к новым знаниям.$B$BА пока возьми этот тотем Земли...', 'Приветствую тебя, $N. Ты бы не вернулся ко мне, если бы не выполнил задания. Позволь мне первой поздравить тебя с выбором первой дороги – первой из четырех, которым отныне ты будешь следовать во всех своих путешествиях. $B$BЕсли у тебя есть камень, который дала тебе земля, я отдам тебе обещанный тотем. Если же нет, мне жаль тебя. Посвятившему себя служению стихиям должно иметь гордость.', NULL, NULL, 'Грубый кварц (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1522, 'Зов Огня', 'Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Краналом.$B$BКранал живет к северу от Перекрестка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, $gготов:готова: к этому.$B$BНайти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесет.', 'Найдите в Степях Кранала Фисса.', 'Что, тебя Сеарн прислал, да?$B$BНу, на Сеарна положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня.$B$BДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Однако, имей терпение, $N. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1523, 'Зов Огня', 'Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание, $N! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты $gготов:готова: платить за это.$B$BОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если промахнешься, можешь очутиться в землях ночных эльфов!', 'Найдите в Степях Кранала Фисса.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1524, 'Зов Огня', 'У тебя достаточно сил, чтобы управлять тотемом огня, но это еще не значит, что ты $gготов:готова: к этому.$B$BВдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране. Отыщи путь на вершину, и найдешь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени.$B$BОтнеси ему этот факел – это знак, что ты пытаешься приручить огонь. Верни мне этот факел зажженным от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотем огня.', 'Отнесите факел Дремлющего Пламени Телфу Джуламу в Дуротаре.', 'А, $N, я ошибся! Прошу прощения. Я не знал, что у тебя с собой этот факел. Очень рад познакомиться.$B$BСюда забредает немало путешественников, которые ищут клады или охотятся на невиданных зверей, и мне приходится прогонять их из этого святилища, которое кажется пустым. Но мы-то с тобой знаем истину, не так ли, $N?$B$BЭто святилище скрывает от несведущих великую тайну. Для нас эта тайна священна!', 'Привет тебе, $N! Ты находишься в святилище Дремлющего Пламени. Только те, кто достаточно сведущ в шаманском искусстве, способны постичь тайны этого места и силу, которую оно содержит. Мне жаль отсылать тебя ни с чем после того, как тебе пришлось проделать весь этот путь – ведь он отнюдь не безопасен! – однако я – хранитель святилища, и не могу позволить бродить здесь кому попало.', NULL, NULL, 'Факел Дремлющего Пламени (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1525, 'Зов Огня', 'Но ты ведь здесь не затем, чтобы выслушивать лекции по истории, верно? Тебе нужно неугасимое пламя и тотем огня!$B$BПервый шаг – это создать сапту, чтобы связать тебя со стихией огня.$B$BЯ могу изготовить тебе сапту, но для этого нужны две вещи. Во-первых – огненная смола, распространенное вещество, которое обычно носят при себе заклинатели из племени Иглогривых в восточных Степях.$B$BА вот второй компонент добыть куда сложнее: это мешочек с реактивами, какие носят чернокнижники из клана Пылающего Клинка. Их можно отыскать в пещере над ущельями к северо-востоку от Колючего Холма.', 'Принесите 1 порцию огненной смолы и 1 мешочек с реагентами Телфу Джуламу в Дуротаре.', 'Это как раз то, что надо, $N.$B$BОгонь – это не просто хаос и разрушение. Запомни это хорошенько! Огонь – это еще и жизнь, и творение! Все в мире взаимосвязано подобным же образом. Противоборствующие силы противостоят друг другу, но при этом не могут существовать поодиночке. Они взаимно уничтожаются, но придают друг другу смысл. Помни об этом!$B$BОдновременное использование различных видов магии говорит не только о подлинном искусстве, но и о большой мудрости.', 'У меня достаточно ингредиентов, чтобы изготовить сапту огня, если ты только раздобудешь мешочек с реактивами и немного огненной смолы. Фанатики из клана Пылающего Клинка носят при себе большую часть необходимых компонентов, так что разыскивать что-то еще обычно не приходится.$B$BСапты всегда изготовляются из ингредиентов, тесно связанных с соответствующими стихиями. Нашу задачу упрощает то, что чернокнижники всегда имеют дело с огнем.', NULL, NULL, 'Огненная смола', 'Мешочек с реагентами', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1526, 'Зов Огня', 'Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени! Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление. Оно не нападет на тебя, пока ты не будешь $gготов:готова: к этому, однако оно поймет, что ты его видишь.$B$BПостарайся поразить его как можно быстрее, $N, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберет! Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел.', 'Сразитесь с низшим воплощением огня и поместите светящийся уголек в жаровню в святилище Неугасимого Пламени.', 'Когда вы бросаете уголек в жаровню, в чаше вспыхивает жаркое белое пламя. Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьется пламя. $B$BВы опускаете факел в чашу, и он мгновенно вспыхивает.', 'Жаровня высотой примерно в треть вашего роста выглядит вполне обычной, если не считать того, что она покрыта письменами. Металл блестит, как новенький, чаша вверху жаровни прохладная на ощупь...', NULL, NULL, 'Факел Дремлющего Пламени (Прилагается)', 'Тлеющий уголь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1527, 'Зов Огня', 'Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Дуротар. Вас охватывает восторг. Пламя факела рвется и трепещет на ветру.$B$BИ вот вы начинаете спускаться обратно по тропе, ведущей в Степи, возвращаясь к Краналу Фиссу.', 'Принесите факел Неугасимого Пламени Краналу Фиссу в Степи.', 'Твой дух пылает ярче любого факела, $N! Тебе есть чем гордиться.$B$BНе сходи с избранного пути, и стихии будут повиноваться тебе, а наши собратья станут искать у тебя советов и наставлений. Позволь мне первым поздравить тебя и вручить тебе новый тотем...', 'Да, $N? Что у тебя там?', NULL, NULL, 'Факел Вечного Пламени (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1528, 'Зов Воды', 'Вода – твое будущее, дружище. Вижу, ты уже $gпокорил:покорила: огонь и, кажись, $gготов:готова: поговорить с Ислен.$B$BИслен живет на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнешься – ищи нехилую акулу! Ислен – великая повелительница духов, и она научит тебя сути воды... если ты $gготов:готова:.$B$BТы ее запростяк найдешь, только на юг слишком далеко не заходи: Ислен живет рядом с Кабестаном.', 'Отыщите в Степях Ислену Заклинательницу Воды.', 'Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.$B$BПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1529, 'Зов Воды', 'Много воды утекло со времени последнего испытания. Ты $gпроявил:проявила: немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.$B$BОтыщи Ислен Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $N.', 'Отыщите в Степях Ислену Заклинательницу Воды.', 'Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.$B$BПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1530, 'Зов Воды', 'Первым делом ты $gдолжен:должна: понять, что вода означает возрождение. $B$BВода течет, разрушает и очищает все сущее. Ты увидишь, что вода – великий целитель, но только чистая вода.$B$BПознав, что оскверненная вода разрушает все кругом, ты поймешь и то, как вода важна для мироздания.$B$BЕсли же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На ее дом постоянно нападают иглогривы.', 'Отыщите Брин на Хребте Черных Шипов в Южных степях.', 'Да?$B$BМ-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредет в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты? У всех нас свои причины действовать так или иначе. У меня другой вопрос – что заставило простого $r отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие?$B$BГотова поспорить, что мы оба знаем ответ на этот вопрос.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1531, 'Зов Воздуха', 'Ты делаешь успехи, дружище. Я верю, что ты $gдостоин:достойна: тотема воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл. Отнесись к ней с уважением, и она расскажет, как получить тотем.$B$BИди на юг, через Степи, а когда попадешь в Тысячу Игл, сверни на восток. Пратт прячется в пещере вместе со своим парнем. Ха-ха! Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится.', 'Найдите Пратту Заклинательницу Туч в Тысяче Игл.', 'Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотем. Возвращайся, когда будешь готов продолжить обучение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1532, 'Зов Воздуха', 'Все ветра Калимдора спешат к тебе навстречу, и скоро ты займешь достойное место среди наших самых выдающихся $gбратьев:сестер:. Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждет великое будущее.$B$BДух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своем пути.$B$BОтправляйся на самый юг Степей, в Тысячу Игл. Там, на востоке, ты найдешь Пратту Заклинательницу Туч, и она продолжит твое обучение.', 'Найдите Пратту Заклинательницу Туч в Тысяче Игл.', 'Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотем. Возвращайся, когда будешь готов продолжить обучение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1534, 'Зов Воды', 'Возьми этот бурдюк и ступай в густой лес, который ночные эльфы зовут Ясеневым. Он находится далеко на севере от Степей.$B$BДобравшись до леса, отправляйся в его западную часть. Возле гряды, отделяющей Когтистые горы от Ясеневого леса, за озером Мистраль, располагается священное место, руины Звездной Пыли. В центре озера, на островке, есть маленький фонтан. Прежде чем возвращаться к Ислен, принеси мне воду из этого источника.', 'Наполните пустой синий бурдюк для воды в руинах Звездной Пыли и отнесите воду Брин из Степей.', 'Чудесно. Теперь у меня есть все три пробы воды, и я могу наполнить фиал чистейшей водой, которую только способно найти живое существо. Она понадобится тебе на следующем этапе.$B$BЯ рада, что среди избравших наш путь есть такие, как ты, $N. Все шаманы гордятся тобой, и я надеюсь вскоре услышать о твоих подвигах.', 'Ты уже несешь мне воду, $N? Говорят, что руины охраняют огромные порождения природы, которые не жалуют гостей, но, вероятно, это всего лишь легенды, призванные отпугивать врагов ночных эльфов.$B$BИ все же соблюдай осторожность.', NULL, NULL, 'Полный синий бурдюк для воды', 'Пустой синий бурдюк для воды', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1535, 'Зов Воды', 'Чтобы обрести понимание и получить от меня сапту, тебе предстоит отыскать чистейшую воду. Принося мне образцы, обращай внимание на окружающий мир – какие существа зависят от этой воды и охраняют ее. Как она влияет на леса и пустыни. Ты увидишь, как влага, дающая жизнь сущему, вынуждает различных существ отнимать эту жизнь у других.$B$BНачнем с малого: ниже моего домика есть пруд с драгоценной влагой.', 'Наполните пустой коричневый бурдюк для воды в источнике ниже хижины Брин и отнесите ей воду.', 'Я предполагала, что если ты возьмешься набирать воду, кровопролития не избежать. Жаль, что иглогривы не понимают, что все живые существа связаны между собой, а жадность лишь усиливает боль и страдания их собственного народа. О, сколь многого они достигли бы, забыв о спорах и объединившись.$B$BДа, для них это плохо, но для других обитателей Степей – скорее хорошо.', 'Я готова дать тебе следующее задание. Ты уже наполнил бурдюк?$B$BЯ знаю, как ревниво иглогривы относятся к водопоям. Ведь даже малый источник для них – настоящее сокровище. Они устраивают пир, если Степи осчастливит хоть небольшой дождь. Вода для них священна, ведь здесь ее очень мало. Ясно?', NULL, NULL, 'Полный коричневый бурдюк для воды', 'Пустой коричневый бурдюк для воды', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1536, 'Зов Воды', 'Давным-давно мы с несколькими спутниками отправились в предгорья Хилсбрада. Нам пришлось отбиваться от навязчивых людей, поселившихся в тех краях, и в итоге мы оказались в городке, захваченном Отрекшимися, – Мельнице Таррен.$B$BИ удивительное дело – в центре города обнаружился маленький источник свежей родниковой воды. Не думаю, что пораженные чумой жители города осознают его ценность – это малый луч света в царстве тьмы.$B$BНабери воду из этого источника в этот бурдюк и принеси мне.', 'Наполните пустой красный бурдюк для воды в Мельнице Таррен и отнесите воду Брин в Степи.', 'Хорошо, $N. Ты изо всех сил стараешься выполнить порученные тебе задания и добиваешься успеха.$B$BЕще одна проба воды, и я смогу создать реактив, необходимый для сапты. Ислен будет довольна.', 'Источник, оставшийся чистым в центре такого города, напомнил мне о сказках, услышанных в детстве. Даже во времена великой боли и скорби остается место надежде, пусть самой малой. Тралл – последняя надежда орков. Он выжил, пройдя сквозь суровые испытания, и вывел наш народ из тьмы собственной силой и решимостью.$B$BНе думаю, чтобы на долю хотя бы одного орка выпало столько страданий, но в то же время ни одному орку не была дарована такая сила.', NULL, NULL, 'Полный красный бурдюк для воды', 'Пустой красный бурдюк для воды', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1558, 'Каменная плотина', 'В Стальгорне живут все дворфы и гномы. Рядом есть местечко, которое зовется озером Лок Модан, и именно там дворфы отгрохали ЗДОРОВЕННУЮ дамбу. Говорят, это одна из самых больших построек в мире. Во как!$B$BПожалуйста, своди меня к озеру Лок Модан, посмотреть на дамбу! Как она называется? Кажется, Каминная дамба? Нет, камин – это что-то не то. В общем, она большая. И на огромный водопад хочется посмотреть. Обещаю, я не буду к нему наклоняться!', 'Отведите сироту к Каменной плотине у озера Лок Модан. Пусть постоит в центре дамбы и полюбуется огромным водопадом.', 'Ух ты! Она еще БОЛЬШЕ, чем я думал! Я собственного голоса не слышу из-за грохота воды! Эй, а вода там не закончится? Ой, а что будет, если дамба рухнет! Вот это было бы страшно!$B$BСпасибо, что показал мне дамбу. Мне понравилось. Я же говорил, что буду хорошо себя вести!', NULL, NULL, NULL, 'Исследовать локацию', 'Ступайте на вершину Каменной плотины возле озера Лок Модан.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1559, 'Секрет изготовления световой бомбы', '', '', 'Так ты у нас инженер, да? Ну что ж, за то, что нашел для меня жемчужины, вот тебе секрет изготовления световых бомб. Ты с ними только уж поосторожней, как бы самому не ослепнуть!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1560, 'Задание Туги', 'Я заблудился!$B$BМоя жена, Торта, отправила меня за обедом, но я не туда свернул.$B$BОтведи меня обратно к Торте! Она ждет меня на юге от Порта Картеля.', 'Сопроводите Тугу к его жене, Торте.', 'Он что, сам не смог найти дорогу? Как обычно.$B$BДа, видно тебе надо дать что-нибудь за труды...', 'Где Тоога?', NULL, NULL, 'Отвести Тугу к Торте.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1578, 'Помощь фронту', 'Горная пехота озера Лок Модан без передышки сражается с троггами! Им нужен постоянный подвоз новых доспехов и оружия, иначе с троггами не справиться.$B$BМой коллега Торвальд как раз и поехал туда – за тем чтобы у солдат было доброе снаряжение. Так что если ты сможешь изготовить несколько медных топоров и плетеных поясов и доставить их Торвальду, он был бы очень благодарен. Он даже может поделиться с тобой своими знаниями.$B$BТорвальда ты найдешь в южной сторожевой башне озера Лок Модан.', 'Отнесите 6 медных топоров и 6 медных плетеных поясов Торвальду в южную сторожевую башню озера Лок Модан.', 'Ох, прости! Я и не понял, что ты пришел помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут!$B$BВот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся.', 'У меня нет времени на болтовню. Говори, какое у тебя ко мне дело?', NULL, NULL, 'Медный топор', 'Медный плетеный пояс', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1579, 'Суперразъемы', 'Я прибыл в Аубердин в поисках тишины и покоя. Я хочу заниматься своими изобретениями там, где царит покой, потому что после ночных попоек мне совсем не нравится гомон Стальгорна!$B$BТак что я отправился на корабле в Аубердин... и по дороге слегка перебрал. Я уронил за борт мой ящик с суперразъемами!$B$BТочно не знаю, где я их потерял, но если ты попытаешься выловить их в океане, может, тебе повезет...', 'Принесите Бацбаху Кривошипу в Аубердин 8 суперразъемов.', 'Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты самый везучий $R на Калимдоре!', 'Нашел мои суперразъемы, $N? Без этих суперразъемов я не могу приспособить шатуны!', NULL, NULL, 'Суперразъем', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1580, 'Электропеллеры', 'Мы знаем, что тебе везет, но... насколько сильно везет, $N?$B$BОднажды ночью я бродил по дорогам Темных берегов. Я искал речку или озеро, пригодные для испытания моей самодвижущейся и взрывающейся подсадной утки и, думаю, был слегка пьян... поскольку потерял сознание и пришел в себя в Аубердине спустя несколько часов. Мои волосы были опалены, а сумка с электропеллерами исчезла! Должно быть, я уронил ее в воду!$B$BМне нужны эти электропеллеры! Может быть, тебе удастся выловить их из какого-нибудь водоема на Темных берегах?..', 'Принесите 12 электропеллеров Бацбаху Кривошипу в Аубердин.', '', NULL, NULL, NULL, 'Электропеллер', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1581, 'Эликсиры для клана Режущего Листа', 'Наша лавочка трав и алхимических снадобий процветает, но мой муж проводит столько времени за изготовлением эликсиров, что почти забыл про личную жизнь!$B$BТы нам не поможешь?$B$BЕсли ты привезешь мне партию уже готовых эликсиров, я охотно куплю их у тебя. У меня есть некоторые редкие травы, которые могут оказаться полезными для тебя.', 'Доставьте 6 эликсиров львиной силы и 2 слабых эликсира защиты Сирел Остролист в Доланаар.', 'Прекрасные снадобья! Ты проявил исключительную щепетильность, $N что очень важно для алхимика!$B$BВот твои травы, я только-только их собрала. Пусть они тебе пригодятся!', 'Ну, привет тебе, $N. Привез эликсиров на продажу?', NULL, NULL, 'Эликсир львиной силы', 'Слабый эликсир защиты', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1582, 'Ж$N лунного сияния', 'У нас, жителей Дарнаса, в особенности у ремесленников, работы невпроворот. Молодым искателям приключений неймется испытать себя во всякой глухомани, так что нам постоянно нужен подвоз материалов.$B$BЕсли ты поможешь мне выполнить заказ на кожаные изделия, я, может, научу тебя более совершенной технике работы с кожей.', 'Принесите 1 пару тисненых кожаных перчаток, 5 пар тисненых кожаных сапог и 5 тисненых кожаных плащей Лотериас в Дарнас.', 'Да, славные изделия. У тебя искусные руки и острый глаз. Из тебя может получиться неплохой кожевник.$B$BСлушай, $N. Давай-ка я покажу тебе выкройку ж$Nа Лунного сияния.', 'Приветствую, $N.', NULL, NULL, 'Тисненые кожаные перчатки', 'Тисненые кожаные сапоги', 'Тисненый кожаный плащ', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1598, 'Украденная книга', '', '', 'Замечательно... Мне никогда не удавалось добраться до этой книги, его держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг.$B$BЛадно, ты отлично потрудился, и я уверена, что ты сумеешь справиться со своим собственным бесом. Пора показать тебе, как его вызывать!', 'Было бы слишком опасно самой пытаться украсть эту книгу из аббатства. Какая удача, что этот простофиля сделал всю грязную работу за меня!', NULL, NULL, 'Силы Бездны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1599, 'В начале славных дел', '', '', 'Прекрасно, прекрасно! В самом деле, $N, неплохая работа. Возможно, те, кто тебя рекомендовал, и не ошиблись...$B$BВпрочем, это не мне решать. Поживем – увидим. Будем надеяться, что первый же вызванный бес не вырвет тебе сердце и не сожрет внутренности – думаю, подобное могло бы серьезно повредить твоей карьере. Пока у меня есть основания полагать, что в качестве чернокнижника ты сумеешь прожить хотя бы несколько месяцев.$B$BКстати, $N, хотел тебе дать тебе совет по поводу бесов. Запомни, размер – еще не главное: даже самый глупый таурен знает, что бесы наделены весьма сильной магией.', 'Обереги из перьев наделены своего рода магической силой. Было бы интересно провести соответствующие исследования... Да уж, троллям удалось меня удивить.', NULL, NULL, 'Оберег из перьев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1618, 'Экипирование Красногорья', 'Не только мы, дворфы, сражаемся денно и нощно – люди, наши союзники, тоже не прохлаждаются!$B$BНа Красногорье время от времени устраивают налеты орки Черной Горы, а снаряжения туда всегда мало поставляется. Если ты им поможешь, то местный кузнец Вернер Осгуд наверняка научит тебя паре хитростей.', 'По просьбе Тормуса Подземной Кузни отнесите 4 рунных медных пояса и 4 тяжелых медных кувалды Вернеру Осгуду в Красногорье.', 'Спасибо, $N. Это чрезвычайно мне поможет. Орки Черной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск.$B$BТо, что ты принес, даст мне хоть небольшую передышку. И у меня будет время кое-чему тебя научить...', 'Надеюсь, ты принес добрые вести из Стальгорна? Я уже не знаю, что мне делать!', NULL, NULL, 'Рунический медный пояс', 'Тяжелая медная кувалда', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1638, 'Обучение воина', 'Ты в самом деле неплохой воин, $N, но лет тебе мало, и еще многому придется научиться.$B$BПоговори с Гарри Берлгардом – обычно он сидит в \"Свинье и свистке\", в старом городе Штормграда. Гарри опытный боец и неплохой учитель. Он покажет тебе несколько приемов, глядишь, и подольше проживешь.', 'Поговорите с Гарри Берлгардом в Штормграде.', 'О-хо! Выпей со мной, парень. С первого взгляда ты кажешься крепким, посмотрим, что с тобой сделает несколько кружек крепкого пива!!!$B$BИли... А, да ты поучиться хочешь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1639, 'Бартлби Пьянь', 'Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься.$B$BВидишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку.$B$BХа, если ты $gзнаком:знакома: с ним, то догадаешься, что так просто он ее не отдаст.', 'Поговорите с Бартлби.', 'Эй, красавчик! Что таким как ты делать в \"Свинье и свистке\"? Осторожнее, неровен час, ноготь сломаешь...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1640, 'Побить Бартлби', 'Что ты хочешь? Да ты $gспятил:спятила:!$B$BЭту кружку ты получишь только через мой труп...', 'Побейте Бартлби и снова поговорите с ним.', 'А ты крепче, чем кажешься с первого взгляда.', 'Эту кружку ты получишь только через мой труп...', NULL, NULL, 'Побить Бартлби', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1641, 'Фолиант Божественности', '', '', 'Здесь, в Штормграде, я – наставник паладинов. Я – тот, кто ведет их стезей добродетели к Истинному Свету, дабы они защищали Азерот от нашествия нежити и иных бедствий.И для тебя пришло время сделать первый шаг на пути праведности. Если ты решишься принять этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, чего от тебя ожидают. Постигнув мудрость, заключенную в этой книге, ты откроешь в себе новые, удивительные способности.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1642, 'Фолиант Божественности', 'Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы. Стремление к божественности для нас не означает стремления стать божеством – мы стремимся к добру во всех деяниях наших.$B$BХотя в эти тяжелые времена мы призваны сокрушать зло, тебе всегда следует помнить: лишь помогая другим, ты выделяешься среди других обитателей Азерота. Сочувствие, терпение, отвага – все эти достоинства значат для паладина не меньше, чем сила в сражении.$B$BУсвой же это и помни всегда.', 'Поговорите с Даторианом Раллом в Штормграде.', 'И снова рад приветствовать тебя, $N. Как идет изучение Фолианта Божественности?$B$BПомни: тебе предстоит пройти испытание. Каждого из нас ждет множество свершений – как в городе, так и в иных землях. Всегда есть люди, нуждающиеся в помощи, сострадании и понимании; всегда есть враждебные твари, которых необходимо уничтожать во благо людей.$B$BДокажи, что ты можешь помогать своим ближним – в особенности тем, кому меньше повезло в жизни. Тем самым ты докажешь, что твои помыслы чисты и что ты воистину служишь Свету.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1643, 'Фолиант Божественности', 'Итак, $N, твоя задача – найти в Штормграде того, кто нуждается в помощи. Того, кто чист сердцем и помыслами. Возможно, это тот, кто сам помогает другим. Возможно – тот, кто нуждается в наставнике. Как бы то ни было, намерения того, кого ты ищешь, будут благородны, и он во всем будет полагаться на тебя.$B$BТы возвратишься ко мне, когда исполнишь это задание, и мы поговорим о твоем пути – а равно и о том, что значит быть паладином Света.', 'Обыщите Торговый квартал и найдите Стефани Тернер.', 'О, привет, милашка. Что, все ищешь приключений? Я так рада, что у тебя все в порядке!$B$BЯ? А что я? Ну, с учетом обстоятельств, у меня тоже дела идут неплохо...$B$BПравда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать? Но ничего, мы справимся. Под \"нами\" я имею в виду себя и своего мужа, конечно. Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1644, 'Фолиант Божественности', 'Да будут благословенны эти несчастные! Многие из них потеряли родных во время набегов нежити...$B$BМой муж Джон помогает мне доставать ткань, чтобы я могла шить сироткам одежду, но увы, на это у меня не хватает времени, ведь их нужно сначала накормить и дать им кров.$B$BЧто? Правда? Ты хочешь мне помочь? Благодарение Вечному Свету! Благодарю тебя, $N!$B$BЕсли бы у меня был лен на одежки малышам, их жизнь стала бы хоть немного легче...', 'Принесите 10 отрезов льна в Штормград и отдайте Стефани Тернер.', 'Ах, $N, благодарю, благодарю тебя!$B$BДетишки так рады будут, да и у меня будет побольше времени на них. Надеюсь, теперь Джон сможет возвратиться поскорее.$B$BПрими мою искреннюю признательность, $N. Я всегда верила, что в сердцах людей есть место милосердию. Да пребудет с тобой Извечный Свет.', 'Надеюсь, моему Джону в Стальгорне повезет. Он терпеть не может дальние поездки – ведь ему приходится оставлять меня одну с детьми, – но знает, что это необходимо. У Джона такое доброе сердце...$B$BИногда нам бывает и полегче, но этот год поистине выдался самым тяжелым на моей памяти. Возможно, это знак того, что в мире что-то меняется, кто знает?..', NULL, NULL, 'Льняной материал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1645, 'Фолиант Божественности', '', '', 'Приятно встретить тебя, $N. Я направляю паладинов на путь высших добродетелей, когда они посвящают себя Свету и защите Азерота от Плети и прочих бед.Пришла пора сделать первый шаг по пути истинных добродетелей. Если ты принимаешь этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, что тебя ждет. Если ты это поймешь и окажешься способным учеником, то откроешь путь к великим возможностям.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1646, 'Фолиант Божественности', 'Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы. Стремление к божественности для нас не означает стремления стать божеством – мы стремимся к добру во всех деяниях наших.$B$BХотя в эти тяжелые времена мы призваны сокрушать зло, тебе всегда следует помнить: лишь помогая другим, ты выделяешься среди других обитателей Азерота. Сочувствие, терпение, отвага – все эти достоинства значат для паладина не меньше, чем сила в сражении.$B$BУсвой же это и помни всегда.', 'Поговорите с Тизой Кузнебой в Стальгорне. ', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1647, 'Фолиант Божественности', 'Твоя задача, $N, найти в Стальгорне кого-нибудь, кто нуждается в помощи. Того, кто чист душой и помыслами. Может быть, того, кто сам помогает другим. Того, кто нуждается в совете. Кто бы то ни был, у него должны быть благородные стремления и он должен полагаться на твою доброту.$B$BСделай это и по выполнении возвращайся ко мне. Тогда мы еще поговорим о твоем пути и о том, что значит быть паладином Света. Я останусь в храме до твоего возвращения. Мое наставничество нужно и другим паладинам.', 'Найдите во внешнем кольце Стальгорна Джона Тернера.', 'СИРОТСКИЙ ПРИЮТ ШТОРМ... о, простите, я вовсе не хотел кричать на вас, сударь,$B$BМеня зовут Джон Тернер. Как поживаете?$B$BРад, искренне рад слышать, что у вас все хорошо. А у меня был трудный день, я тоскую по жене, но такова цена, которую приходится платить, чтобы накормить голодные рты и одеть нагих.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1648, 'Фолиант Божественности', 'Мы с женой держим в Штормграде сиротский приют, по большей части для детей, потерявших родителей во время нападений Плети в последние десять лет. Я приезжаю в Стальгорн примерно раз в месяц и занимаюсь сбором средств у здешних горожан, а также прошу помощи у различных организаций.$B$BНынешняя поездка была мучительно медленной и не слишком продуктивной.$B$BЕсли бы мне удалось добыть еще немного льняной ткани для одежды, я бы смог, наконец, отправить посылку домой.', 'Принесите 10 отрезов льняной ткани Джону Тернеру в Стальгорн.', '', NULL, NULL, NULL, 'Льняной материал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1649, 'Фолиант Доблести', 'Отвага и сопутствующие ей достоинства подобны драгоценным металлам. Нужно беречь их, когда находишь, ибо цена их велика, но также необходимо копить и приумножать их. Тогда они образуют крепчайший сплав, зачастую выдерживающий даже самые сильные удары.$B$BТвои сила, вера и храбрость должны быть испытаны. Тебе надлежит научиться хранить веру в любых обстоятельствах и понять, что с помощью сил Света ты сможешь преодолеть те препятствия, которые не по силам другим.', 'Поговорите с Даторианом Раллом в Штормграде.', 'Ты просишь испытать твою отвагу? Прекрасно!$B$BДля тебя в городе и в окрестностях найдется немало заданий. Нам как раз нужен кто-нибудь с твоими способностями.$B$BЭто испытание не будет легким, $N! Оно, как и многое в нашей профессии, может привести к гибели. Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли паладин служить правому делу.$B$BЧувствуешь ли ты в себе готовность к испытанию?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1650, 'Фолиант Доблести', 'Отлично! Отсутствие сомнений говорит о твоей готовности к испытаниям. Да будет так!$B$BВ самом конце Долгого Берега стоит небольшой домик с окнами на океан. Там живет чета Стивеллов. Джордан – великолепный кузнец, и сейчас он собирается в Стальгорн, чтобы навестить дворфов. Но его жена Дафна остается дома одна, без защиты...$B$BДонесения говорят, что Братство Справедливости захватило почти весь край. Дафне может понадобиться защита от злодеев. Отправляйся туда.', 'Найдите Дафну Стилвелл в Западном Крае.', 'Здравствуй, $N. Я полагаю, что со всем этим оружием в руках ты хочешь либо захватить мои земли, либо Церковь наконец-то послала мне защитника на время поездки Джордана.$B$BПозволь представиться: я – Дафна Стилвелл. Очень приятно!$B$BТвое прибытие очень кстати: с восхода солнца я уже прикончила с полдюжины этих мерзавцев. До этого они не особо торопились, но сейчас они наверняка заметили тебя, а значит, будут здесь с минуты на минуту...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1651, 'Фолиант Доблести', 'Бьюсь об заклад, они скоро вернутся – так что приготовься.$B$BВ доме есть пистолет, я возьму его и при необходимости помогу тебе, но лучше рассчитывай только на свои силы.$B$BНе знаю, сколько их будет, но уверена, что больше, чем в прошлый раз.$B$BМоли Свет благословить тебя, потому что… Слышишь? Они идут!$B$BУкроемся за домом!', 'Защитите Дафну Стилвелл от нападения Братства Справедливости. Проследите, чтобы ни ее, ни ваша душа в случае смерти не покинули свои тела, иначе испытание не будет засчитано.После победы поговорите с Дафной Стилвелл.', '$N, мы победили! Благодарю тебя за помощь. Это было просто великолепно! Я и не думала, что паладин может справиться с таким количеством врагов зараз.$B$BТвоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня...', 'Укроемся в доме!', NULL, NULL, 'Защитите Дафну Стилвелл.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1652, 'Фолиант Доблести', 'Прошу, возвращайся к Даториану и передай ему, что теперь со мной все в порядке – благодаря тебе и Церкви.$B$BОн пошлет весть в Стальгорн, чтобы мой Джордан не волновался за меня.$B$BОх, как я соскучилась по своему мужу! Жду не дождусь его возвращения...', 'Поговорите с Даторианом Раллом в Штормграде.', 'Вот мы и встретились снова. Я вижу, что дух твой бодр. Дом четы Стивеллов теперь в безопасности, а из твоего рассказа ясно, что ему теперь еще долго ничего не будет угрожать. Отлично!$B$BДафна и Джордан немало помогли Церкви. Отправить тебя на их защиту – весьма скромная ответная услуга.$B$BТы получишь награду за проявленную отвагу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1653, 'Испытание доблести', 'Вообще я не сомневаюсь, что Джордан захочет лично отблагодарить тебя, и раз уж мне надо сообщить ему, что его жена в безопасности, то, думаю, лучше всего тебя посланником и отправить.$B$BДжордан был паладином Света, до того как приверженность отцовскому ремеслу увлекла его на другой путь, – а потому он хорошо знает наш образ жизни и считается одним из самых надежных наших приверженцев.$B$BОн должен еще быть в Стальгорне – он любит работать днем за воротами, там где с гор тянет холодным воздухом.', 'Поговорите с Джорданом Стилвеллом в Стальгорне.', 'Добрый день, $N. Вижу, ты служишь Свету?$B$BЧто это? Тебя послал Даториан?! Моя жена, как она? Я так и знал – стоит уехать, сразу беды нагрянут. Скажи мне, она... о, хвала Свету. Я так счастлив, что она в безопасности. Это Братство Справедливости было опасным еще до нынешних своих налетов, но теперь уж королевские советники не смогут этой угрозы отрицать.$B$BЧто еще велел передать Даториан?$B$BИменно ты и назначен был оберегать мою жену? Тогда еще раз прими мою благодарность, $N. Не могу придумать лучшего испытания доблести, чем это.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1654, 'Испытание доблести', 'Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар. Пойми меня правильно, все будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода.$B$BЯ скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света. Но тебе придется добыть необходимые для ковки предметы. Я уже набросал список, так что остается только, чтобы некто отважный и искусный принес их мне. Что скажешь, $C?', 'Возьмите список Джордана, добудьте немного древесины белокаменного дуба, партию очищенной руды Бэйлора, кузнечный молот Джордана и самоцвет Кора и отдайте их Джордану Стилвеллу в Стальгорне.', 'Великолепно! Ты добыл все необходимое.$B$BТеперь я легко изготовлю для тебя великолепное оружие! Я и так собирался когда-нибудь его выковать, просто не было возможности достать все необходимое. Спасибо тебе, $N.$B$BКак же приятно снова держать в руке молот моих отцов... и самоцвет Кора – я и не думал, что когда-нибудь увижу его собственными глазами!', 'Предметы эти нелегко добыть, но, смею тебя заверить, оружие, которое я для тебя сделаю, сторицей окупит твои труды.$B$BЭто будет лучшая моя работа и лишь малая награда за все, что ты сделал для меня.', NULL, NULL, 'Древесина белокаменного дуба', 'Партия очищенной руды Джордана', 'Дробящий молот Джордана', 'Очищенный самоцвет Кора');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1655, 'Партия руды Балора', 'Ох, и $gиспугал ты меня, парень:испугала ты меня: дамочка;! Не видишь, что я в размышлениях?$B$BЭто что еще? Поставка Джордану... Стальгорн. А, да, я понял, о чем речь. Мо\'грошские огры ограбили меня, и нет у меня руды для старого друга. Караван шел сюда из Болотины и попал в засаду. Охранник, что уцелел, помер пару дней назад – целитель не поспел вовремя.$B$BЕсли хочешь найти эту партию руды, то придется тебе двинуться на северо-восток, за озеро Лок. Она где-то там.', 'Доставьте партию руды для Джордана Балору Крепкоруку к озеру Лок Модан.', 'Ну-ну, надо же! Знал бы я, что ты и правда прямо туда и пойдешь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести. Но ведь ты тут не за тем, чтобы за меня работу делать, верно?$B$BА сделка есть сделка. Джордан хотел получить свою руду, и он ее получит.$B$BПередай ему приветик от меня, и доброй тебе дороги, $C.', 'Ну, что, удалось? Огры получили от тебя по полной, да?', NULL, NULL, 'Партия руды Джордана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1656, 'Незаконченное задание', '$N, умоляю, помоги мне! У меня еще есть дело здесь, на плато - я прохожу обряд Силы, - а мой отец требует, чтобы я срочно доставила эти меха в таверну в деревне Кровавого Копыта! $B$BКак же мне выполнить сразу обе задачи - завершить ритуал и отнести меха?! Не отнесешь ли ты их вместо меня?$B$BТаверна - такое милое и уютное местечко, там есть все, чего может пожелать притомившийся путник. Даю слово, тебе понравится!', 'Отнесите сверток мехов хозяину таверны Кауту в деревню Кровавого Копыта.', 'О, а вот и мои меха! Благодарю вас.$B$BВы доставили их даже быстрее, чем я ожидал. Они послужат отличными одеялами для моих постояльцев.$B$BПрошу вас, гостите в таверне, сколько пожелаете. Наши двери всегда открыты, и мы рады каждому. Не стоит недооценивать значение полноценного отдыха - особенно если впереди дальняя дорога.', 'Приветствую! Чем Каут может вам помочь?$B$BПуть сюда от самого плато неблизок: кто-то всю дорогу думает об уставших мышцах и стертых ногах, а кто-то наслаждается великолепными пейзажами... А вы что скажете?', NULL, NULL, 'Сверток мехов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1657, 'Чем пахнет в Южнобережье', 'Сделайте ваш праздник Тыквовина незабываемым... насолив нашим врагам на Южнобережье!$B$BВозьмите специально собранную бомбу-вонючку – она наполнена невероятно зловонным веществом, запах которого не вынесет ни одно тупое животное, включая людей. Вам нужно будет бросить ее в самый центр Южнобережья, так что готовьтесь к драке с Альянсом!$B$BА когда сделаете этот шаг к нашему освобождению, возвращайтесь ко мне!', 'Бросьте три бомбы-вонючки Отрекшихся в центр Южнобережья в Хилсбраде и вернитесь к призывательнице тьмы Янке на фестиваль Плетеного человека в Тирисфальских лесах.', 'Ах, превосходно! Надеюсь, Альянс задохнется от нешего подарка – так же, как мы задыхались от рабских оков Плети!$B$BВы отлично отметили этот Тыквовин, Усамыч, с чем я вас и поздравляю! И в качестве вознаграждения позвольте разделить с вами вот это вкусности. Надеюсь, оно вам понравится!', 'Вы доставили наш \"подарочек\" жителям Южнобережья?$B$B*Янка Зовущая Тьму злобно хихикает.*', NULL, NULL, 'Бросьте бомбу-вонючку в Южнобережье', 'Забытая бомба-вонючка Отрекшихся', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1658, 'Сорвать праздник Плетеного человека', 'Мне нужны храбрецы, готовые отправиться в Тирисфальские леса на фестиваль Плетеного человека. Не скрою, это очень опасно. Стража на фестивале будет особенно бдительна и свирепа. И все же надо выяснить, велик ли в этом году фестиваль, и сколько бед Отрекшиеся причинят нам во время Тыквовина.$B$BЕсли тебе хватит пороху, ступай в Тирисфаль и разведай, что да как. Я прослежу, чтобы тебе хорошо заплатили за принесенную информацию.', 'Отыщите место проведения фестиваля Плетеного человека в Тирисфальских лугах и возвращайтесь в Южнобережье к сержанту Хартману.', '', NULL, NULL, NULL, 'Исследовать локацию', 'Разведайте, что происходит на фестивале Плетеного человека.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1661, 'Фолиант благородства', 'Приветствую тебя, $N! Я несказанно рад тому, что могу называть тебя $gБратом:Сестрой:: твое посвящение – радость для всех нас.$B$BПришло время вручить тебе великий дар. Но знай: сейчас я даю его тебе, не требуя ничего взамен; но потом настанет час, когда всем паладинам придется немало потрудиться для того, чтобы получить его.$B$BПриходи в любое время – я отдам тебе твой подарок.', 'Поговорите с Даторианом Раллом в Штормграде. ', 'Поздравляю! Да пребудет с тобой Свет!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1665, 'Кружка Бартлби', 'Ладно, бери мою кружку. Стой! Дай-ка я хотя бы допью... Ну вот. Бери.', 'Отнесите кружку Бартлби Берлгарду.', 'А вот и кружка! Да уж, он не хотел с ней расставаться, но ты умеешь настоять на своем. Молодец.$B$BПриступим к обучению...', 'Я наблюдал за твоей дракой с Бартлби. Неплохо! Удалось отобрать кружку?', NULL, NULL, 'Кружка Бартлби (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1666, 'Маршал Хаггард', 'Ты $gосвоил:освоила: несколько новых приемов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард.$B$BОн живет в своем поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины. Он ушел в отставку, но за время службы собрал недурную коллекцию оружия.$B$BСкажи, что тебя прислал я, и если повезет, он поделится лишним оружием.', 'Поговорите с маршалом Хаггардом.', 'Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так подкрался, что я принял тебя за гнолла!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1667, 'Джек Мертвозуб', 'Тебя ведь прислал Берлгард? Да, у меня есть запасное оружие, но сначала я хочу дать тебе задание…$B$BНекоторое время назад меня обманул злодей из Братства Справедливости, Джек Мертвозуб. Он пришел в темноте, одетый в гербовую накидку Штормграда, и я принял его за маршала Дугана. Джек сказал, что ему нужен мой старый знак маршала, и я, не раздумывая, отдал его... а потом он захохотал и сбежал, прежде, чем я успел его схватить!$B$BВерни мне мой знак! Джек Мертвозуб наверняка прячет его в лагере на юге.', 'Добыть знак маршала Хаггарда из лагеря Джека Мертвозуба и вернуться к маршалу Хаггарду.', 'Ура, мой знак у тебя! Я боялся, что лишился его навсегда, а шваль из Братства Справедливости получила возможность изображать из себя представителей власти. Тебе же удалось предотвратить невиданный разгул преступности.$B$BВот мое оружие, которое лежит без дела с тех времен, как я был маршалом. Я его регулярно чистил его, и оно в отличной форме, выбирай!', 'Мой знак у тебя? Страшно подумать, какие преступления может совершить Джек с его помощью.', NULL, NULL, 'Знак маршала Хаггарда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1678, 'Веджрек', 'Хорошему воину пристало быть стойким. Я научу тебя новым приемам, но прежде докажи, что сможешь справиться с серьезными противниками.$B$BВеджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов. Он живет в хижине в предгорьях, чуть южнее Форта Мерзлогривов.$B$BПринеси мне голову Веджрека, и я поверю, что ты не лыком $gшит:шита:.', 'Принесите голову Веджрека Марену Грозовой Вершине в Стальгорн.', '', NULL, NULL, NULL, 'Голова Веджрека', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1679, 'Марен Грозовая Вершина', 'Привет тебе, воин! Ты $gнаделен:наделена: многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдешь.$B$BМарен в Оружейной, в Палатах войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним.', 'Поговорите с Мареном Грозовой Вершиной.', 'А, $N. Я слышал твое имя от воинов Дун Морога. Надеюсь, ты не все время проводишь в пивных?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1680, 'Тормус Подземная Кузня', 'Ты уже $gосвоил:освоила: несколько приемов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скует тебе оружие по вкусу.$B$BТормус живет здесь, в Стальгорне, в Великой Кузне.', 'Поговорите с Тормусом Подземной Кузней.', 'Тебя прислал Марен? Да, я могу сковать тебе превосходное оружие... Но услуга за услугу.$B$BНе бойся. Конечно, задание будет опасным, ты можешь погибнуть, но разве не к этому стремятся все воины?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1681, 'Мастерская Сталекрута', 'У моего наставника, Стурги Сталекрута, была мастерская на юге от озера Хельмова ложа в восточной части Дун Морога. Он был лучшим учителем кузнечного дела.$B$BНо однажды ученики принесли ему странную руду. Мастер Сталекрут назвал ее мрачной рудой и с радостью с ней работал, но увы, вскоре на них напал отряд дворфов Черного Железа. Они поубивали всех!$B$BСтупай в мастерскую Сталекрута, $N, и отомсти за смерть моего учителя. И принеси мне груз мрачной руды.', 'Принесите мрачную руду Тормусу Подземной Кузне в Стальгорн.', 'Ты нашел ее! Молодец!$B$BНадеюсь, что в ходе поисков ты убил целую толпу дворфов Черного Железа. Боюсь, нам придется столкнуться с ними не только в мастерской Сталекрута.$B$BВпрочем, спасибо за руду, $N. Я с радостью поработаю с ней и исследую ее свойства.', 'Тебе удалось пробраться в поселок Сталекрута? А мрачная руда у тебя?', NULL, NULL, 'Мрачная руда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1682, 'Оружие из серой стали', '', '', 'Вот тебе оружие, только что с наковальни. На него пошла добытая тобой мрачная руда!Что же, $N, выбирай!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1683, 'Ворлус Подлое Копыто', 'Прежде чем браться за твое обучение, я хочу испытать твою храбрость.$B$BСатир Ворлус Подлое Копыто обнаружил один из наших лунных колодцев, тот, что на юго-востоке от обители Бен\'этиль. Он плещется в его светлых водах, оскверняя их своим присутствием.$B$BОтыщи Ворлуса и убей его. В доказательство принеси мне его рог, и я возьмусь учить тебя.$B$BОтыскать дорогу к колодцу очень трудно, но тот, кто ищет, тот всегда найдет.', 'Принесите рог Ворлуса Эланарии из Дарнаса.', '', NULL, NULL, NULL, 'Рог Ворлуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1684, 'Эланария', 'Приветствую тебя, воин. Ты растешь над собой, но профессия воина не так проста, как кажется. Тебе нужен хороший учитель.$B$BВ Дарнасе, на террасе Воинов, живет Эланария. Поучись у нее.', 'Поговорите с Эланарией.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1685, 'Приглашение Гакина', 'И вот так всегда. Я разыскивал тебя весь день, но так и не смог найти; а сейчас, когда я вовсе этого не ожидал, ты появляешься как из-под земли.$B$BЯ уже и так слишком много времени потратил на твои поиски, так что буду краток. Наставник Гакин призывает тебя для дополнительных занятий – и, думаю, тебе стоит поторопиться.$B$BТы найдешь его в подвале таверны \"Забитый ягненок\". К слову сказать, не стоит много болтать об этом месте...', 'Обратитесь к Гакину Темнопряду в квартал магов Штормграда.', 'Наконец-то ты здесь. Мне следовало послать за тобой кого-нибудь более расторопного, чем Ремен.$B$BНу, неважно.$B$BКогда у тебя было последнее занятие? Слишком давно, слишком... А ты знаешь, что у плохо обученного чернокнижника мало шансов сохранить голову на плечах?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1686, 'Тень Элуры', 'Ты многому $gнаучился:научилась:, $N. Пора создать для тебя настоящее оружие. Оружие воина.$B$BТебе придется отправиться за ним на Темные берега.$B$BДавным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой.$B$BДля начала тебе придется одержать верх над стражем элунита, тенью Элуры. Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза. Победи ее, забери у нее медальон и собери со дна ящики с элунитом.', 'Принесите 8 партий элунитовой руды и медальон Элуры Эланарии из Дарнаса.', '', NULL, NULL, NULL, 'Элунитовая руда', 'Медальон Элуры', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1687, 'Маяк с привидениями', 'Попечительницы сирот рассказывают нам сказки на ночь. Иногда даже про привидений. Это особенно КРУТО! Мне запомнилась история про призрак, живущий в маяке Западного Края. Говорят, он был капитаном пиратского корабля, но корабль захватили другие пираты. Правда, интересно?$B$BОтведи меня к этому маяку! Я хочу посмотреть на призрак капитана! Обещаю не отходить от тебя ни на шаг!', 'Отведите сироту к маяку на побережье Западного Края.', 'Надо же, настоящий призрак! Потрясающе – мне не терпится рассказать ребятам из приюта. Капитан Грейсон... И выглядел точно как пират! Когда я вырасту, я тоже стану пиратом-призраком!$B$BСпасибо, что сводил меня в Западный Край, я знаю, что вокруг полно всякой жути. Надеюсь, я не очень усложнил тебе жизнь. Ты просто чудо!', NULL, NULL, NULL, 'Исследовать локацию', 'Отправляйтесь к маяку Западного Края.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1688, 'Сурена Каледон', 'У меня была ученица по имени Сурена Каледон. Помню, она стояла как раз там, где сейчас стоишь ты… Просила меня научить ее искусству чернокнижия, а у самой даже капли таланта к этому не было. Хм, зато она была молода и довольно миловидна. Если бы я видел тогда, что это за вероломная дрянь!$B$BРаспутная девка сбежала с одним из членов Братства Справедливости по имени Эрлан Драджмур. Об этой потере я нисколько не сожалею, однако колье кровавого камня, которое я подарил ей, мне все еще нужно.$B$BЕе жизнь для меня больше ничего не значит. Ты найдешь девку на тыквенной ферме Бреквеллов. Верни мне мое имущество!', 'Верните колье Кровавого камня Гакину Темной Вязи в Штормград.', 'Сурена была талантлива, но не настолько, чтобы овладеть чарами самостоятельно. Печально видеть, как погибают молодые и талантливые, но иногда без этого нельзя.$B$BНадеюсь, усилия, вложенные в тебя, прахом не пойдут...', 'Старики и мудрецы тоже подвластны чарам молодости и красоты, $N. Это совет, который стоит запомнить на всю оставшуюся жизнь.', NULL, NULL, 'Колье Сурены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1689, 'Оковы', 'Вернув мое колье и обманув Сурену, ты $gдоказал:доказала:, что не уступаешь ей в таланте.$B$BПоэтому я уверен, что тебе не помешает обучение. Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше.$B$BЯ научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоем распоряжении. Используй магию колье в кругу призыва.', 'С помощью колье кровавого камня призовите и подчините демона Бездны, затем верните колье кровавого камня Гакину Темнопряду.', 'Тебе удалось даже больше, чем я ожидал, $N. На это я и надеялся. Теперь ты можешь научиться управлять покоренным тобой демоном. Он станет твоим помощником в предстоящих испытаниях. Сейчас мне нечему больше учить тебя, но я уверен, что мы с тобой, $N, еще увидимся...', 'Я не могу показать тебе, как управлять демоном Бездны, пока ты не подчинишь его своей воле.', NULL, NULL, 'Призванный демон Бездны убито', 'Колье кровавого камня (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1690, 'Расправа над Скитальцами Пустыни', 'Эй, ты! Пора оказать услугу Водной компании Прибамбасска.$B$BКочевники Скитальцев Пустыни захватили почти все колодцы пустыни Танарис! Без них у нас мигом закончится вода. Если ты хочешь заслужить нашу признательность, расправься с этими варварами!$B$BСтупай на восток и прикончи 10 бандитов и 10 воров из шайки Скитальцев Пустыни, а на обратном пути доложись мне. Никому не миновать расправы... или как там говорится... А, неважно, иди себе!', 'Убейте 10 бандитов и 10 воров из шайки Скитальцев Пустыни на востоке от Прибамбасска и возвращайтесь к главному инженеру Чепухастеру.', 'Ну, вот это называется эффективность! Ты помог нам сократить число кочевников, и мы начинаем подумывать о том, чтобы отбить наши колодцы.$B$BВодная компания Прибамбасска благодарит тебя за помощь, но мы еще не разобрались с этими проклятыми кочевниками. Слушай внимательно – вот что нам понадобится теперь...', NULL, NULL, NULL, 'Бандит из шайки Скитальцев Пустыни убито', 'Вор из шайки Скитальцев Пустыни убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1691, 'Еще одна расправа над Скитальцами Пустыни', 'Теперь тебе придется схватиться с кочевниками посильнее. Ты неплохо $gпоработал:поработала:, но если отбивать у этих гадов наши колодцы, лучше бы противников было поменьше!$B$BНа сей раз выступи против разбойников, убийц и темных магов. Их можно найти на востоке и юго-востоке отсюда.$B$BНе буду тебе лгать – справиться с ними нелегко. Зато в случае успеха мы очень скоро сможем вернуть себе принадлежащее нам по праву!', 'Убейте 10 темных магов, 8 разбойников и 6 убийц из шайки Скитальцев Пустыни по поручению главного инженера Чепухастера из Прибамбасска.', 'Первоклассная работа, $N… первоклассная! Число кочевников сократилось настолько, что мы можем бросить им вызов!$B$BТы уже поговорил с оператором крана Тормозиллером? Он предлагает награду за меха с водой, которые могли тебе попасться во время битвы с кочевниками!', 'Ну что, удалось одолеть кочевников, о которых я говорил? Все планы Водной компании Прибамбасска зависят от твоего успеха! Не подведи нас...', NULL, NULL, 'Разбойник из шайки Скитальцев Пустыни убито', 'Убийца из шайки Скитальцев Пустыни убито', 'Темный маг из шайки Скитальцев Пустыни убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1692, 'Кузнец Матиль', 'Я сложила собранный тобой элунит в сундук. Отнеси его кузнецу Матилю, мы сделаем из него элунитовое оружие.$B$BМатиль на юге отсюда, на другой стороне этого здания.', 'Отнесите сундук элунита кузнецу Матилю.', 'А, элунитовая руда. Работать с этим металлом – одно удовольствие, ведь он благословлен самой богиней Элуной. Выковать элунитовое оружие – великая честь.$B$BПодожди, я сейчас примусь за работу...', 'Привет тебе, юный воин. Чем могу тебе служить?', NULL, NULL, 'Сундук Элунита (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1693, 'Оружие из элунита', '', '', 'Это оружие я выковал из принесенного тобой элунита. Можешь взять себе любое.Большое спасибо. Работать с элунитом – не только удовольствие, но и великая честь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1698, 'Йорус Ячменовар', 'Йорус Ячменовар бросил вызов всем воинам Альянса. Он ждет в таверне Приозерья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание.', 'Поговорите с Йорусом Ячменоваром. ', 'Ха! Значит, до тебя дошли вести о моем вызове, а?$B$BЧто ж, садись и слушай. Пей и наслаждайся... Может быть, это твоя последняя выпивка в этой жизни.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1699, 'Ретбанский вызов', 'Я называю мое испытание Ретбанским вызовом. Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько \"но\"…$B$BВернуться тебе придется в течение часа.$B$BТам полно красногорских гноллов.$B$BПеред тем, как тронуться в путь, тебе придется глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменевец!$B$BЧто скажешь? Пещеры Ретбана находятся в холмах на севере от Приозерья. Ты $gготов:готова: принять Ретбанский вызов?', 'Войдите в пещеры Ретбана, доберитесь до первой развилки и вернитесь к Йорусу Ячменовару за отведенное время.Вы не должны умирать и освобождать свой дух.', 'Ты справился! Молодец! Трижды ура$N!', 'Ты теряешь время, $N. На твоем месте я бы поторопился.', NULL, NULL, 'Исследовать локацию', 'Войдите в пещеры Ретбана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1700, 'Гриманд Элмор', 'Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Гриманду Элмору. Он живет здесь, в Квартале Дворфов, в оружейном магазине. Он гордится своим искусством и совсем не обрадуется моему открытию...', 'Отнесите записки Фьюрена Гриманду Элмору.', 'Это написал Фьюрен? Как он смел! Да я его всему сам научил! Яйца курицу не учат! Нахал!$B$BХм-м-м... Но в этих записях что-то есть... Надо попробовать...', 'Приветствую, добро пожаловать. Чем могу помочь?', NULL, NULL, 'Записки Фьюрена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1701, 'Закаленный доспех', 'Ну вот, я дал тебе отличный щит, но это еще не все. Я знаю секрет изготовления очень прочного доспеха. Это нелегко, и мне потребуются редкие материалы, но если тебе не лень за ними поохотиться, доспех получится несравненный.$B$BЧто скажешь? Если ты не боишься трудностей, я выдам тебе список необходимых материалов и где их искать.', 'Соберите все необходимые материалы для Фьюрена Длинноборода и отнесите их в Штормград.', 'Тебе удалось добыть все необходимое? Вот это да! Я опасался, что химеры слопают тебя с потрохами!$B$BЧто ж, займемся доспехами...', 'Как охота на падальщиков? Удалось добыть нужные материалы?', NULL, NULL, 'Опаленный паучий клык', 'Обугленный рог', 'Гальванизированный рог', 'Сосуд флогистона');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1702, 'Щитник', 'Да, приняв Ретбанский вызов, ты $gпоказал:показала:, на что $gспособен:способна:. Я свое слово держу. Ты получишь обещанную награду…$B$BТолько она в Штормграде.$B$BПоговори с моим другом, Фьюреном Длиннобородом. Он живет в Квартале дворфов. Его щиты славятся во всей округе, а мне он должен услугу.$B$BВот, отнеси Фьюрену этот боченок жгучего пива Ячменевца и попроси взамен щит. Он плохого не даст.', 'Отнесите бочонок жгучего пива Фьюрену Длиннобороду.', 'А, жгучее пиво Ячменевца. Отличный напиток! Значит, ты от Йоруса, а?$B$BКонечно я дам тебе щит, да еще какой! Такого нигде не найти, честное слово!', 'Привет! Меня мучает жажда, а тебя?', NULL, NULL, 'Бочонок жгучего пива (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1703, 'Матиль', 'Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Матилю. Он живет довольно далеко, в Дарнасе, но несомненно будет рад, если я поделюсь с ним своими открытиями.', 'Отнесите Матилю записки Фьюрена.', '', NULL, NULL, NULL, 'Записки Фьюрена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1704, 'Клацморт Гайкокрут', 'Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Клацморту Гайкокруту. Он живет в Стальгорне, и когда услышит о моем открытии... Он бороду себе выдернет от восторга!', 'Отнесите записки Фьюрена Клацморту Гайкокруту.', 'Ну и ну! Поразительные записи мне прислали! Больше того... Они ошеломляющие и невероятные, я едва на ногах стою от восторга!$B$BФьюрен совершил прорыв в кузнечном деле! Да-да, самый настоящий прорыв! Мне не терпится испробовать новую технологию!', 'Добрый день, или утро, или вечер. Какая разница! Ты ко мне по делу?', NULL, NULL, 'Записки Фьюрена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1705, 'Пылающая кровь', 'Может, этот Фьюрен и совершил открытие, но мне надо проверить, так ли это. Попробую-ка я сделать такие доспехи. Если ты поможешь добыть все материалы, можешь забрать доспех себе.$B$BМне понадобится горящая кровь и горящий камень.$B$BЕдинственное место, где можно добыть эти материалы – Сумеречный лес. Горящая кровь есть у воргенов из стаи Ночной Погибели из пещеры Роланда, а горящий камень хранит у себя их главарь, Кишкодер.$B$BИ не мешкай, во имя Света.', 'Принесите 20 сосудов горящей крови и 1 горящий камень Гриманду Элмору из Штормграда.', 'Недурно! А теперь, прошу прощения, мне тоже надо поработать...', 'Ну как, удалось добыть горящую кровь и камень? Без них доспехов не сделаешь.', NULL, NULL, 'Пылающая кровь', 'Горящий камень', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1706, 'Доспехи Гриманда', '', '', 'Глазам своим не верю! Технология Фьюрена оказалась удачной, и этот доспех способен выдержать серьезную нагрузку.Держи, $N. И огромное тебе спасибо. Если бы ты не принес мне все необходимые материалы, я бы так и не поверил в открытие Фьюрина.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1707, 'Награда за воду', 'Привет тебе, $N. Меня зовут Живец, и у меня есть для тебя важная работа! Ура!$B$BЯ опытный оператор крана, и ничто не порадует меня так, как бурдюки с водой Скитальцев Пустыни, которые могут попасться тебе в пустыне, у кочевников. Все равно это наша вода – мерзкие кочевники ее украли! Водная компания Прибамбасска предлагает в награду полевой набор за каждые пять бурдюков. А главное, ты поможешь Прибамбасску!', 'Принесите 5 бурдюков Скитальцев Пустыни оператору крана Тормозиллеру в Прибамбасск.', 'Великолепно! Чем больше мехов с водой нам удастся добыть, тем ниже вероятность катастрофы! Можешь таскать их сотнями, и за каждые пять будешь получать все ту же награду.', 'Ты принес все пять бурдюков? Если да, то лечебный набор Водной компании Прибамбасска, модель 103-ХВ, твой!', NULL, NULL, 'Бурдюк с водой Скитальцев Пустыни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1708, 'Железный коралл', 'Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах. Раз ты $gпомог:помогла: Фьюрену, а он мне, я разрешу тебе забрать их себе!$B$BЧтобы довести работу до конца, мне необходим особый коралл, выжженный. Он растет лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине.$B$BПринеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, $N, у меня руки чешутся, так хочется взяться за дело.', 'Принесите 20 партий выжженного коралла Клацморту Гайкокруту в Стальгорн.', 'Вот, то что нужно! Молодец! А теперь дай-ка я их расплавлю и расплющу. Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет!$B$BНу-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!', 'Привет-привет, $N! Ты несешь мне выжженные кораллы? Мне не терпится взяться за работу!', NULL, NULL, 'Тлеющий коралл', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1709, 'Творение Клацморта', '', '', 'Вот твои доспехи, $N. Идея Фьюрена отлично сработала. Идеально! Чудесно, если правду сказать!По этой броне можно осадные орудия прокатить, и она сохранит форму!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1710, 'Высохшая скорлупа', 'Мой коллега, Фьюрен Долгобород, совершил многообещающее открытие. Я хотел бы испытать его на новых доспехах, мне кажется, результат превзойдет все ожидания.$B$BНе поможешь? Если ты принесешь мне все необходимые материалы, я и для тебя сделаю такие доспехи.$B$BМне понадобится высохшая на солнце скорлупа яиц виверн Скального Гнездовья из Тысячи Игл. Скорлупу можно найти под их гнездами. Как наберешь достаточно, возвращайся.', 'Принесите 20 кусков высохшей на солнце скорлупы Матилю из Дарнаса.', '', NULL, NULL, NULL, 'Высохшая на солнце скорлупа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1711, 'Доспехи Матиля', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1712, 'Циклониан', 'Я давно наблюдаю за этими местами, в надежде дожить до падения великого Циклониана. Увы, мне до сих пор не встретился герой, готовый схватиться с повелителем ветра.$B$BМожет быть, этим героем окажешься ты?$B$BДокажи, что ты великий воин – собери все предметы, необходимые для призыва Циклониана. Тогда, быть может, тебе удастся одолеть его и завладеть сердцем Вихря.$B$BЕсли это свершится, я вложу силу сердца в оружие и вручу его тебе.$B$BВот список нужных компонентов.', 'Принесите Бат\'ра Стражу Ветра все предметы из его списка.', 'Ты сумел собрать все необходимое для заклинания призыва, доказав тем самым свою силу и ловкость. Но следующий шаг будет гораздо опаснее.$B$BБудем надеяться, что сила тебя не покинет.', 'Ты уже все собрал, $N? Принеси все компоненты, иначе я не поверю, что тебе хватит сил одолеть Циклониана.', NULL, NULL, 'Корень жизни', 'Клык тролля из племени Кровавого Скальпа', 'Субстанция Изгнанников', 'Пергамент Бат-ра');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1713, 'Призыв', 'Я готов провести ритуал призыва Циклониана. Потом тебе предстоит победить его и забрать у него из груди сердце Вихря. После этого я создам оружие, которое вберет в себя силу Циклониана.$B$B$N, $gготов:готова: ли ты выступить против повелителя ветра?', 'Принесите сердце Вихря Бат\'ра Стражу Ветра.', 'Ты справился! Циклониан повержен, а у тебя в руках сердце Вихря!', '$N, мне нужно сердце Вихря!', NULL, NULL, 'Сердце Вихря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1714, 'Субстанция Изгнанников', '', '', 'Обереги медленно опускаются на дно котла…$B$BИз глубины поднимается большой пузырь воздуха, лопается и…$B$B... на поверхности оказывается оплавленный камень.', NULL, NULL, NULL, 'Громовой оберег', 'Пылающий оберег', 'Оберег Гребня', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1715, 'Таверна \"Забитый ягненок\"', 'Хмм. В прежние времена все чернокнижники Каз Модан обучались под присмотром мастеров Гномрегана, но теперь, когда все мы вынуждены ютиться в этой крысиной норе под названием Стальгорн и Магни решил не спускать с нас глаз, нам приходится отсылать наших новичков на обучение в Штормград.$B$BПо счастью, Гакин не растяпа, так что ты все равно узнаешь все, что тебе надо, но я просто киплю!$B$BКороче, ты найдешь Гакина в подвале \"Забитого ягненка\" в Штормграде.', 'Обратитесь к Гакину Темнопряду из Квартала Магов Штормграда.', 'Так тебя послал Зловещая Отвертка? Нет, пора бы уже этим стальгорнским растяпам как-то разобраться с ситуацией. Штормград не резиновый, и наставников тут сколько есть, и не больше. Если сюда повалит народ, то рано или поздно мы привлечем к себе внимание.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1716, 'Пожиратель Душ', 'Сайаады – пожиратели душ, подавляющие волю и вводящие в искушение. Порождение чистого зла. В легкомысленных историях этих демонов называют суккубами, если речь о женщинах, и инкубами, если это мужчины. Примани демона символом любви, победи его – и он будет тебе служить. Но найти подходящий символ непросто. Поговори с Такаром Провидцем. Ты найдешь его в калимдорских Степях возле лагеря Таурахо.', '', '$N, как вы добрались? Вы проделали долгий путь, чтобы поговорить со мной. Но не бойтесь: я знаю, зачем Гакин прислал вас. Это было мудро с его стороны, потому что я могу вам помочь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1717, 'Приглашение Гакина', '$N! Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать.$B$BТы давненько уже не $gпроходил:проходила: очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать.', 'Обратитесь к Гакину Темнопряду из Квартала Магов Штормграда.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1718, 'Островитянин', 'Ты становишься недурным воином, $N. Пришло время помериться силой с братьями по оружию.$B$BНедалеко от побережья Степей, к югу от Кабестана, есть остров. Он называется Островом Битв. Это место встречи воинов.$B$BМесто встречи и дружеских схваток.$B$BПоговори со старшим воином острова, Кланноком Маклеодом. Если он сочтет тебя достойным дальнейшего обучения, то поможет тебе сделать очередной шаг на пути воина.$B$BДо Острова Битв можно добраться по песчаной отмели вдоль Торгового побережья.', 'Поговорите с Кланноком Маклеодом.', 'Привет тебе, воин. Хорошо, что тебе удалось добраться до Острова Битв. Надеюсь, он тебе нравится...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1719, 'Побоище', 'Если ты хочешь учиться у меня, тебе придется пройти испытание: Побоище. Через него проходят все молодые воины, вообразившие себя великими. А величие надо доказывать.$B$BДля начала пройди сквозь ту толпу и встань на решетку. Это будет знак Пруттику Плоскоголову, что ты готов. Он сразу пришлет тебе соперника.$B$BКогда ты одолеешь всех, он позовет Большого Вилла. Убей его и вернись ко мне за отведенное время.', 'Убейте Большого Вилла и поговорите с Кланноком Маклеодом на Острове Битв.', 'Молодец, $N. Ты прошел испытание Побоищем!$B$BТы могучий воин, и учить тебя – великая честь...', 'Ты уже прошел испытание?', NULL, NULL, 'Большой Вилл убито', 'Исследовать локацию', 'Встать на решетку, чтобы начать Побоище', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1738, 'Сердцедрево', 'Готовясь к твоему приходу, я на скорую руку оглядел весь мир, проник взглядом сквозь пелену времени и нашел то, что тебе нужно.$B$BВо время Войны Древних двое влюбленных вместе пали в битве. Там, где перестали биться их сердца, выросло дерево, известное как сердцедрево – символ их бессмертной любви.$B$BЭтого должно быть достаточно, чтобы привлечь суккуба. Руины Ордиль\'Арана, где растет сердцедрево, находятся в северо-западной части Ясеневого леса.', 'Раздобудьте в Ясеневом лесу сердцедрево и принесите его Гакину Темнопряду в Квартал магов Штормграда.', 'Да, сердцедрево нам подойдет. Дай-ка я немного обработаю древесину...$B$BТакар – настоящий кладезь премудростей; с таким не пропадешь, правда? Если б я только мог убедить его вернуться к цивилизации...', 'Как проходят поиски, $N?', NULL, NULL, 'Сердцедрево', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1739, 'Оковы', 'С помощью сердцевины сердцедрева ты сможешь открыть портал и призвать суккуба в круг призыва. Круг находится в подвале.$B$BНе забывай об осторожности, $N, суккубы подчиняли себе и самых стойких заклинателей.$B$BПосле того как вызовешь демона и вернешь его обратно в Бездну, возвращайся ко мне и я научу тебя, как обращаться с суккубом.', 'Призовите и подчините суккуба, используя сердцевину сердцедрева, затем верните сердцевину сердцедрева Гакину Темнопряду. Он будет ждать вас в \"Забитом ягненке\".', 'Неплохо, $N, неплохо... Я не ошибся, когда решил обучать тебя. Твои успехи меня не разочаровывают.$B$BПора научить тебя обращению с только что подчиненным суккубом. Только не забывай про осторожность!', 'Иногда я удивляюсь, как же Сурена, которая не была суккубом, ухитрилась так заморочить мне голову? Эх... Может быть, дело и не только в ней...', NULL, NULL, 'Призванный суккуб убито', 'Сердцевина сердцедрева (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1740, 'Шар Соран\'рука', 'Когда демоны Легиона попадают в немилость, их души заключают в сферы и раздают магам и чернокнижникам.$B$BМногих из них носили на Азероте их слуги. Даже расколотые на части, эти сферы хранят в себе силу демонов, заключенных внутри. Шар Соран\'рука был расколот надвое. Одну из частей раздробили на еще более мелкие фрагменты послушники Сумеречного Молота в Непроглядной Пучине. А другая, большая часть, досталась волшебнику из крепости Темного Клыка. Найди их, и я смогу воссоздать этот шар.', 'Соберите 3 фрагмента Соран\'рука и 1 большой фрагмент Соран\'рука и принесите их Доану Кархану в Степи.', 'Да... Этот шар не так уж сильно раскололи, и передо мной почти все осколки. Воссоздать их, сделав Соран\'рука единым целым, несложно.$B$BЯ посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона. Ты оказал мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору.', 'Мне понадобилось много лет, чтобы собрать все части сферы Заргейна, но она служит мне верой и правдой, как будет служить тебе шар Соран\'рука', NULL, NULL, 'Фрагмент Соран\'рука', 'Большой фрагмент Соран\'рука', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1758, 'Фолиант заговора', 'Простой круг призыва не поможет тебе вызвать на бой охотника скверны.$B$BЯ и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника скверны без посторонней помощи.$B$BС этим тебе поможет Крому Крепкоруку. Теперь он – главный чернокнижник, и целыми днями он сидит в библиотеке Стальгорна, оберегая древние тексты.', 'Поговорите с Кромом Крепкоруком в Стальгорне.', 'Фолиант Заговора? Хм-м... Знакомое название. Я его никогда не видел – а уж поверьте, я помню все прочитанные книги.$B$BХм…$B$BА, да! Я видел ссылки на этот фолиант в библиотечных каталогах.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1778, 'Фолиант Божественности', 'Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, $C.', 'Поговорите с Тизой Кузнебой в Стальгорне.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1779, 'Фолиант Божественности', 'Я хочу, чтобы ты $gвзял:взяла: это, $N. Это называется знак Жизни.$B$BТы $gпоказал:показала: свое милосердие и терпение, а теперь я хочу, чтобы ты $gпроявил:проявила: себя не только как воин, но и как $gцелитель:целительница:.$B$BМой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Черного Железа. Он едва ноги унес – сейчас лечит свои раны у одного из наших жрецов.$B$BВозьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет.', 'Возьмите знак жизни и поговорите с Майридоном Кузнебоем в Стальгорне. ', '*кашляет*$B$BДоброго тебе здравия, $C. Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона. Так что сила твоего знака Жизни пока мне не нужна.$B$BЗначит, моя женушка тебя послала потолковать со мной, да? Славно, славно. У меня найдется времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1780, 'Фолиант Божественности', 'Я сегодня же отнесу это детям. Ты можешь не тревожиться, $C. Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения $gдоказал:доказала:, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается.$B$BДоброго пути!', 'Поговорите с Даторианом Раллом в Штормграде.', 'Ты уже здесь, $N? Однако, странствия заняли у тебя не так много времени, как я полагал. И что же тебе удалось свершить за время, проведенное вдали от Храма? Может быть, тебе довелось сражаться за справедливость? Или удалось постичь смысл милосердия? Или помочь кому-либо из нуждающихся жителей Азерота? Расскажи мне все...$B$BЧто ж, $N, это производит впечатление. Поверь, это поистине поступки того, кто следует путем Света и ставит благо других выше своего собственного.$B$BРано или поздно такое самопожертвование всегда вознаграждается.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1781, 'Фолиант Божественности', 'Прими этот знак жизни, $N.$B$BТебе удалось обрести милосердие и терпение: пришло время узнать, хватит ли у тебя сил, чтобы воспользоваться одним из величайших даров Света. $B$BМой друг Газин недавно вернулся из Элвиннского леса с острова Героев, где он едва не расстался с жизнью после стычки с магами из Братства Справедливости. Сейчас он у алтаря: надеюсь, служителям удастся исцелить его раны.$B$BВозьми этот знак и поговори с Газином. Если сумеешь помочь ему, мы продолжим нашу беседу. Да пребудет с тобой извечный Свет!', 'Отнесите знак Жизни Газину Тенорму в Штормград.', '*кашляет*$B$BЯ рад встрече с тобой, $r. Не обращай внимания на мои раны: добрые служители Света смогут обо всем позаботиться. Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока.$B$BЗначит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно. Я тебе расскажу, что случилось со мной и моим другом Хензом. Если нам повезет и тебе хватит сил и умения, ты еще сможешь всех нас спасти...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1782, 'Доспехи Фьюрена', '', '', 'Вот твои доспехи, $N. Они выдержат любой удар, не будь я Фьюрен Длиннобород!И спасибо большое. Я многому научился, работая с принесенными тобой материалами. Думаю, в один прекрасный день я совершу новое открытие!А результаты этого я отправлю другим кузнецам Альянса.Я скажу им, что ты мне очень помог, может быть, они тоже решат отблагодарить тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1783, 'Фолиант Божественности', 'Мы выслеживали дворфов Черного Железа, что окопались к югу от озера Хельмово Ложе. Мы знали, что они затевают недоброе, потому мы с Нармом решили подобраться поближе, чтобы посмотреть, как их капитан раздает приказы своим воинам.$B$BМы с Нармом воспользовались случаем и пристукнули нескольких, но они оказались крепче, чем мы думали, и набросились на нас толпой. Нарм велел мне бежать за помощью, и вот я здесь.$B$BНарму нужна помощь. И я не успокоюсь, пока он ее не получит.$B$BТы ведь поможешь ему, $N?', 'Возьмите знак Жизни и воскресите Нарма Фолка в Дун Мороге.', 'Не знаю, как мне отблагодарить тебя, брат!$B$BВидать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни.$B$BДа, это правда, я пал в бою с дворфами Черного Железа, пытаясь получить одну из их бумаг. Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появился. То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1784, 'Фолиант Божественности', 'Прежде чем я пал в бою, мы с Майридоном почти одолели одного из соглядатаев из клана Черного Железа возле того небольшого домика. Мы видели, как их капитан раздавал им бумаги с приказами, и хотели убить его и забрать эти бумаги.$B$BКое-кто в совете Стальгорна до сих пор не верит в присутствие дворфов Черного Железа в Дун Морог. Захватив одну из этих бумаг, мы не только получим доказательства их вылазок, но и поймем, что они затевают.$B$BДобудь один из приказов и отнеси Майридону, $N.', 'Добудьте приказ клана Черного Железа у дворфов из клана Черного Железа возле Хельмова Ложа и вернитесь к Майридону Кузнебою в Стальгорн.', '', NULL, NULL, NULL, 'Послание дворфов Черного Железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1785, 'Фолиант Божественности', 'Вижу, моя женушка прямо пышет гордостью. Я бы на твоем месте поскакал прямо к ней. Сдается, она хочет перекинуться с тобой парой слов.$B$BДа хранит тебя Свет, $gславный:славная:c: $C. Я буду искать тебя на поле боя против Плети и клана Черного Железа, когда придет пора.', 'Поговорите с Тизой Кузнебой в Стальгорне.', 'Сегодня ты оказал большую услугу Стальгорну, $N. Я горда, что ты среди нас, и если ты готов, я хотела бы благословить тебя этим свитком. Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни.$B$BЯ научу тебя возрождать к жизни твоих соратников. Используй это умение мудро, Хорнфел, и прими благодарность от меня, моего мужа и всего Стальгорна.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1786, 'Фолиант Божественности', 'Мы с Хензом добрались до острова Героев – он находится посреди озера Каменных Столбов, в северо-восточной части Элвиннского леса. Мы слышали, что Братство Справедливости проникло в наши земли, и должны предоставить доказательства этого вторжения королевским советникам.$B$BМы засекли двоих из этих подонков, когда они просматривали кое-какие документы, и напали на них. Увы, магов было больше, и нас заставили отступить.$B$BХенз прикрывал меня, и мне удалось бежать... проклятый глупец, отвагу проявить решил!..$B$BИ вот он там так и остался. Хенз, я имею в виду. Может, ты сумеешь помочь, $N?', 'Возьмите знак Жизни, пойдите в Элвиннский лес и воскресите Хенза Фолка.', 'Прими мою благодарность, брат.$B$BВ твоих руках я вижу знак Жизни – тебя послал Даториан или Газин.$B$BМы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи. Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побежден...$B$BНо тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, $N, можешь мне поверить. Это свидетельство крепости твоей веры...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1787, 'Фолиант Божественности', 'У нас еще будет время поговорить о знаке. Сейчас важнее заполучить те бумаги, которые мы видели у Братства Справедливости. Если бумаги будут у нас, мы сможем доказать, что Братство проникло в Элвиннский лес – а может, и узнать что-нибудь о его планах.$B$BУвы, $N, навряд ли я сейчас могу считаться воином. Сможешь ли ты пойти в бой в одиночку? Сумеешь ли ты добыть то, что нам так необходимо?$B$BЕсли это тебе удастся, отнеси бумаги Газину и сообщи ему, что со мной все хорошо.', 'Найдите волшебников из Братства Справедливости в Элвиннском лесу, заберите у них бумаги и отнесите их Газину Тенорму в Штормград.', 'Великолепно! Тебе удалось спасти Хенза и выполнить задание. Теперь я знаю: воистину, Свет озаряет твой путь, $N!', 'А, это ты, $N? С Хензом все в порядке? Тебе удалось добиться успеха?$B$BЯ вижу, острову Героев не страшно никакое братство, пока в твоих руках оружие, а с нами пребывает сила Света. Однако решение за королем и его советниками...', NULL, NULL, 'Документ Братства Справедливости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1788, 'Фолиант Божественности', 'После того как Даториан ознакомится с этими бумагами, я передам их королевским советникам; однако прежде тебе стоит поговорить с Даторианом. Думаю, он тоже хотел бы поблагодарить тебя.$B$BТвоя помощь поистине неоценима, $N. Надеюсь, это не последняя наша встреча. Я горжусь нашей дружбой.', 'Поговорите с Даторианом Раллом в Штормграде.', 'Что ж, $N, полагаю, ты можешь гордиться своими свершениями.$B$BСкажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделен знак Жизни. Если в твоих силах призвать исцеляющую силу Света, ты достоин того, чтобы принять величайший дар паладинов, – дар воскрешения.$B$BТы сможешь возвращать к жизни павших спутников так же, как вернул к жизни Хенза.$B$BГорний Свет озарил тебя, $N, открой же ему душу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1789, 'Знак Жизни', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1790, 'Знак Жизни', '', '', 'Поспеши, $N! Слишком много жизней зависит от твоего успеха или неудачи.Если ты не сумеешь помочь Газину и Хензу, возвращайся: я дам тебе новый знак Жизни.Не думай, что я помогаю тебе просто так, нет: тебе, как и всякому другому паладину, нужно доказать, что ты достоин своего звания. Постоянные неудачи – не лучшая рекомендация...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1791, 'Страж Ветра', 'Что ж, ты $gосвоил:освоила: стойку берсерка, теперь нужно подобрать тебе оружие.$B$BПоговори с Бат\'ра Ветростражем, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями. Он опытный оружейник и могучий шаман.$B$BЕсли ты захочешь встретиться с Бат\'ра, отправляйся к реке, что течет вдоль восточного края Мельницы Таррен. Иди вдоль нее на север – Бат\'ра разбил лагерь рядом с руинами на берегу реки.', 'Поговорите с Бат\'ра Стражем Ветра.', 'Тебе пришлось проделать долгий путь, юный воин. Как у тебя горят глаза! Тебе ведь нужно мощное оружие?$B$BЯ помогу тебе... в обмен на твою помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1792, 'Оружие вихря', '', '', 'У меня есть сердце Вихря, и я могу подобрать ему вместилище по твоему выбору.Возьми любое оружие, и знай, что его сила – сила Циклониана.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1793, 'Фолиант Доблести', '', '', 'Теперь доказано, что ты – приверженец сил Света, $N, но времена наступают все более опасные, и поэтому важно знать, какая сила скрывается в твоем сердце. Когда демоны, драконы или какое другое зло ступят на нашу землю, тогда и подвергнется испытанию твой дух. Достанет ли у тебя сил?Храбрость в любой ситуации – такая же неотъемлемая часть сущности паладина, как Свет, доспех и оружие. Необходимость защищать слабых и не терять веры – вот еще два урока, которые ты должен усвоить, пока проходишь обучение в Соборе Света.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1794, 'Фолиант Отваги', '', 'Что же, теперь нет сомнений, что благодать Света пребывает с тобой, $N, но чем опаснее времена, тем важнее знать, какую силу скрывает плоть. Когда на твои земли ступят демоны, драконы или иное зло, твоя доблесть подвергнется испытанию. Достанет ли тебе сил?Не бывает паладина без отваги в любой ситуации, как не бывает паладина без Света, доспеха и оружия. Защищай слабых, не теряй веры – вот два урока, которые тебе следует усвоить во время обучения в Соборе Света.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1795, 'Оковы', 'Если ты $gготов:готова:, давай приступим. Начну с объяснений.$B$BСначала мы создадим основной круг призыва. После этого мои послушники создадут больший круг при помощи жезлов направления.$B$BЗатем ты прочтешь заклинание из фолианта Заговора, и на зов явится охотник скверны. Будь $gосторожен:осторожна:, $N. Охотник скверны - сильный враг, не теряй головы.', 'Призовите и одолейте охотника скверны при помощи фолианта заговора и верните фолиант Страхаду Фарсану из Кабестана.', 'Впечатляюще, $N. Когда я сражался с охотником скверны, то едва выжил. Предчувствую, что ты станешь одним из сильнейших чернокнижников нашей эры.', 'Каждый чернокнижник должен иметь в своем распоряжении охотника скверны. Хотя их сложно приручить, обретенное могущество стоит затраченных усилий.', NULL, NULL, 'Призванный охотник Скверны убито', 'Фолиант заговора (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1796, 'Материалы для зачарованного золотого кровавого одеяния', 'Первым делом я помогу тебе создать одеяние. Ты принесешь мне несколько необходимых составляющих, а уж работать над ними будем вместе. В итоге, если ты справишься, разумеется, ты получишь первый из многих предметов, которые одарят тебя могуществом и помогут в борьбе против сил Тьмы.$B$BДля начала тебе нужны одеяния тайны. Их может сшить портной или их можно купить... еще лучше сделать их самому, но это сложно. Короче, для начала принеси мне эти одеяния.', 'Принесите одеяния Тайны Менаре Расщепительнице Бездны в Степи.', 'То, что нужно,$N.$B$BВ основе всех волшебных предметов должна лежать вещь высокого качества. Чем больше усилий и искусства вложить в предмет, тем легче напитать его магией. Редкие и дорогие составляющие также лучше держат магию. Не жалей об утрате этого одеяния: когда мы закончим, оно станет куда лучше.', 'Как идут поиски одеяния, $N? Удалось создать его самостоятельно? Когда делаешь что-то сам, куда приятнее наполнять этот предмет магией. Получаешь большее удовлетворение. Но я пойму, если ты предпочтешь более легкий путь – заказать одеяние. Подобная... целеустремленность тоже хороша.', NULL, NULL, 'Одеяния тайны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1798, 'На поиски Страхада', 'Пришло время научить тебя вызывать охотника скверны, $N. Здесь у меня нет ни реагентов, ни предметов, необходимых для обучения, так что придется тебе найти другого учителя – Страхада Фарсана.$B$BОн проживает в гоблинском порту Кабестане. Я извещу его о том, что ты появишься.', 'Поговорите со Страхадом Фарсаном в Степях.', '$N? Ах да, конечно. Наше новое чудо. Но, боюсь, настоящее чудо вряд ли успеет стать легендой при жизни.$B$BВпрочем, неважно – ты здесь для того, чтобы пройти обучение, а не слушать, как я шучу сам с собой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1799, 'Части шара Орахила', 'Отлично, приступим.$B$BПервым делом ступай внутрь и поговори с моими послушниками. Тебе предстоит избрать свой путь – они объяснят подробнее.$B$BПотом придется отправиться в Пустоши и отыскать сферу Подземного огня у одного из чернокнижников Поля Маннорок. Именно эту сферу необходимо очистить при помощи мага по имени Табета в южной части Пылевых топей. Она поможет тебе ради меня.$B$BИ не возвращайся, пока не выполнишь оба задания.', 'Поговорите с послушниками Менары в башне над Кабестаном и изберите свой путь.После этого принесите Табете в Пылевые топи сферу Подземного огня.', 'А, так тебя послала Менара. Ну, хорошо... Располагайся, чувствуй себя как дома. Впрочем, ты, должно быть, спешишь? Быть может, ищешь утраченную силу? Может, я ошибаюсь, и скверна все же коснулась тебя.', 'Ты явно не маг, и я не уверена, что тебе можно доверять. Я ощущаю в тебе колдовскую силу, но кажется, тебя не затронула скверна, столь легко берущая верх над вашим братом.$B$BДа, $C… $C пришел просить меня о помощи.$B$BИтак, что тебе нужно, Свояк?', NULL, NULL, 'Сфера подземного огня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1800, 'Тронный зал Лордерона', 'Если мы хорошо себя ведем, то попечительницы сирот рассказывают нам на ночь сказки про славные сражения и про мирные времена. В одной из легенд говорилось о том, как пал Лордерон и как злобный Артас отнял жизнь у собственного отца, чтобы захватить трон.$B$BБесчестный человек! Когда я вырасту и стану великим воином Орды, мной будет править лишь закон чести, а не зло!$B$BПокажи мне его тронный зал! Он находится как раз перед входом в Подгород.', 'Отведите своего подопечного в старый тронный зал Лордерона, который находится как раз у входа в Подгород.', '', NULL, NULL, NULL, 'Исследовать локацию', 'Отправляйтесь в тронный зал Лордерона, который находится у входа в Подгород.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1801, 'Фолиант заговора', 'Простой круг призыва не поможет тебе вызвать на бой охотника Скверны.$B$BЯ и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника Скверны без посторонней помощи.$B$BС этим тебе поможет Йорах Аннисон. Он работает в Подгороде картографом, но все равно знает о древних текстах куда больше моего.', 'Поговорите с Джорахом Аннисоном в Подгороде.', 'Картография! Картинки, далекие от реальности. Они мне не нужны. $B$BКниги – повествование, описание! В них и только в них следует искать правду. Я обменял бы все свои карты на одну книгу о возвышении некромантии или сагу о торжестве Темной Госпожи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1802, 'Фолиант заговора', 'Он был утрачен, но есть кое-какие соображения насчет того, где он может находиться сейчас.$B$BС него сделали только одну копию и отнеслись к ней совершенно по-варварски: большая часть книги была вырвана из переплета. Ходят слухи, что она каким-то образом попала в руки одного кентавра из Тысячи Игл.$B$BОстальное было утрачено в прибрежных краях к западу от Южнобережья, откуда книгу должны были переправить морем в Гавань Менетилов. Судно так и не прибыло.$B$BА за мои сведения я попрошу одно: когда найдешь книгу, дай мне заглянуть в нее хотя бы одним глазком.', 'Добудьте заплесневелый фолиант и потрепанный манускрипт для Крома Крепкорука из Стальгорна.', 'С ума сойти! Теперь я один из немногих, что сумел хоть мельком заглянуть в нее.$B$BНе терпится повнимательнее изучить этот текст. Какой великий день, $N! Позволь мне еще раз заглянуть в нее прежде, чем уйдешь. Уверен, что Страхад охотно пришлет мне копию.', 'Так слухи оказались верны, $N?', NULL, NULL, 'Заплесневелый фолиант', 'Потрепанный манускрипт', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1803, 'Фолиант заговора', 'А! Вижу, наши вкусы сходятся. Поиски фолианта заговора – достойное занятие. Знаешь ли ты, что он некогда хранился в стенах Лордерона? Правда, эти варвары поглумились над ним, вырвали больше половины страниц. Кто мог совершить такую мерзость?$B$BИтак, половина потеряна, хотя говорят, будто она попала в руки кентавров из Тысячи Игл.$B$BОстальную часть должны были перевезти в Стальгорн, но она потерялась при перевозке где-то на берегу моря к западу от Южнобережья.', 'Отыщите заплесневелый фолиант и потрепанный манускрипт для Йораха Аннисона из Подгорода.', 'Так-так-так! Что это у нас?$B$BНевероятно, $N. Я был уверен, что это невозможно, но вот я держу в руках фолиант Заговора.$B$BПозволь мне полистать его, пока ты не ушел.', 'Может быть, фолиант Заговора и упоминался в сказках, но даже в самых невероятных историях есть доля правды.', NULL, NULL, 'Заплесневелый фолиант', 'Потрепанный манускрипт', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1804, 'Фолиант заговора', 'Как же не хочется его выпускать из рук! Но ты его $gнашел:нашла: и, конечно же, свершишь при его помощи куда более важные дела. Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию.$B$BПока тебя не было, он прислал для тебя письмо. Он пишет, что для призыва духов необходимо достать три жезла направления.$B$BОн-то не знает, где их искать, но зато я знаю! Последний раз их использовали орки клана Драконьей Пасти в Болотине. Я бы поискал у их заклинателей!', 'Принесите восстановленный фолиант и три жезла направления Страхаду Фарсану в Кабестан.', 'Отлично! Фолиант Заговора и три практически нетронутых жезла направления.$B$BЗабавно выходит. Давно молодые чернокнижники не приручали охотников Скверны.', 'Давно не видел тебя здесь. Ты нашел фолиант и жезлы?', NULL, NULL, 'Восстановленный фолиант (Прилагается)', 'Жезл направления', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1805, 'Фолиант заговора', 'Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет. Выбор здесь небогат – большинство книг посвящено географии, и я все до дыр зачитал. Надеюсь, Страхад пришлет мне копию.$B$BКстати, он прислал весточку, пока тебя не было. Чтобы выполнить очередную задачу, тебе понадобится три жезла направления.$B$BВ благодарность за то, что ты $gдал:дала: мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине.', 'Принесите восстановленный фолиант и три жезла направления Страхаду Фарсану в Кабестан.', 'Отлично! Фолиант Заговора и три практически нетронутых жезла направления.$B$BЗабавно выходит. Давно молодые чернокнижники не приручали охотников Скверны.', 'Да, $N? Чем я могу тебе помочь?', NULL, NULL, 'Восстановленный фолиант (Прилагается)', 'Жезл направления', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1806, 'Испытание доблести', 'Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займет.$B$BКогда все будет закончено, ты будешь гораздо лучше $gподготовлен:подготовлена: к защите дела Света, уж за это я ручаюсь.$B$BНе утаю, $N, я даже немного завидую твоим деяниям. Но осознание того, что я по-своему помогу тебе, и немало помогу, все же радует меня.', 'Подождите, пока Джордан Стилвелл не закончит изготовление оружия.', 'Вот оно, $N. Оружие, достойное защитника Света вроде тебя. Я дал ему имя в честь великого дворфского паладина, моего друга. Его звали Вериган... Бош Вериган. Прошу, прими его в благодарность от меня и моей жены. Мы очень обязаны тебе. Мир станет лучше, если по земле ходят такие, как ты!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1818, 'Разговор с Диллинджером', 'Мне сказали, что у стража смерти Диллинджера есть работа для таких, как ты. Если ты хочешь доказать свою ценность Темной Госпоже, немедленно отправляйся к нему.$B$BСтраж смерти Диллинджер стоит на посту в западном конце Брилла, рядом с кладбищем.', 'Поговорите со стражем смерти Диллинджером в Брилле.', 'Ты хочешь получить задание? Отлично. У меня есть одно. Довольно важное. Заодно и свою силу нам покажешь... И решимость защищать дело Отрекшихся.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1819, 'Улаг Колун', 'Когда Тирисфальские леса наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению. Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич.$B$BМы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его.$B$BДля этого его придется убить.$B$BВоспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы.$B$BСними их и... будь $gготов:готова:!', 'Убейте Улага Колуна и поговорите со стражем смерти Диллинджером.', 'Молодец, $N. Улаг был серьезным сторонником Плети. Тебе удалось доказать стражам смерти и через них Темной Госпоже, что ты опытный и умелый воин и заслуживаешь дальнейшего обучения.', NULL, NULL, NULL, 'Улаг Колун убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1820, 'Разговор с Колманом', 'Тебе удалось услужить Темной Госпоже, пришло время услужить одному из ее подданных.$B$BКолману Фартингу нужен воин, который сможет отомстить врагам Отрекшихся.$B$BКоулман сидит в таверне \"Петля висельника\", в восточной части Брилла.', 'Поговорите с Колманом Фартингом.', 'Да, это правда. Мне нужна помощь закаленного воина. Средств у меня немного, зато ты послужишь не только мне, но и делу Отрекшихся. Так что если ты справишься, наградой будет почет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1821, 'Наследие Агамондов', 'При жизни я служил семье Агамондов, и именно из-за них и умер! Поделом им, они стали теперь безмозглыми прислужниками Короля-лича.$B$BМне же хочется лишить их остатков чести. Ступай в Семейную усыпальницу Агамондов и принеси их фамильное оружие: меч, топор, кинжал и палицу.$B$BСклеп находится на севере, позади мельниц Агамондов. Его стерегут бойцы Плети и сами неупокоенные хозяева.', 'Принесите Колману Фартингу фамильный топор Агамондов, фамильный меч Агамондов, фамильную палицу Агамондов, фамильный кинжал Агамондов.', 'А! Вот оно! Итак, проклятые земли Агамондов лишены остатков чести и памяти. Отныне семьи воистину не существует!', 'Тебе удалось принести фамильное оружие?', NULL, NULL, 'Фамильный топор Агамондов', 'Фамильный кинжал Агамондов', 'Фамильная палица Агамондов', 'Фамильный меч Агамондов');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1822, 'Фамильное оружие', '', '', 'Я оставлю принесенное тобой оружие на память о понесенных потерях. Впрочем, ты можешь выбрать наиболее полюбившуюся тебе вещь и оставить ее себе.Да послужит она тебе лучше, чем прежним проклятым владельцами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1823, 'Разговор с Ругой', 'Ты уже опытный воин, и имя твое на слуху у многих. Может быть, ты хочешь пройти испытание Руги Тотема Ярости? Коли так, отправляйся в Лагерь Таурахо, в Степи.$B$BОн ждет всех воинов, что готовы принять его вызов.', 'Поговорите с Ругой Тотемом Ярости.', 'Ты хочешь пройти испытание, $N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1824, 'Испытание на Полях Великанов', 'Чтобы пройти это испытание, тебе придется отправиться на юг, к Полям Великанов. Там ты встретишь полчища ползучих существ, похожих на насекомых. Они явились в Степи незванными, и мне они совсем не нравятся.$B$BПринеси их усики. Главное, чтобы они все еще дергались, поэтому тебе придется поторопиться. Добудь мне усики за отведенное время, и я сочту, что испытание пройдено.', 'Принесите 5 дергающихся усиков Руге Тотему Ярости в Лагерь Таурахо.', 'Отличная работа, $N! Ты прошел испытание на Полях Великанов, сделав тем самым еще один шаг по тропе воина.', 'Ну как, усики у тебя? Коли так, давай их скорее сюда, а то они скоро перестанут дергаться...', NULL, NULL, 'Дергающийся усик', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1825, 'Разговор с Тун\'гримом', 'Слухи о твоих доблестных подвигах во славу Орды дошли до знаменитого орочьего кузнеца, Тун\'грима Огневзора. Он хотел бы сделать для тебя доспехи, но тебе надо как можно скорее с ним встретиться.$B$BТун\'грим живет на востоке от Перекрестка, что в Степях.', 'Поговорите с Тун\'гримом Огневзором из Степей.', 'Да, ты пришел. Отлично, нам с тобой многое придется обсудить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1838, 'Доспехи Жестокости', 'Я наслышан о твоей силе и доблести и хочу сделать для тебя броню, которая охранит тебя в бесчисленных сражениях.$B$BВпрочем, создание такой брони – само по себе подвиг. Мне понадобится твоя помощь, а также помощь других кузнецов Орды.$B$BВозьми этот список. Я составлял его не одну ночь, напряженно вглядываясь в пергамент почти незрячими глазами. Принеси мне все перечисленное, и я создам тебе первую часть доспеха.', 'Принесите Тун\'гриму Огневзору 15 закопченных железных слитков, 10 мер толченого азурита, 10 железных слитков и сосуд флогистона.', 'Ты принес все, что я просил. Теперь дело за мной...', 'Ты все предметы из списка принес?', NULL, NULL, 'Закопченый железный слиток', 'Толченый азурит', 'Железный слиток', 'Сосуд флогистона');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1839, 'Ула\'елек и рукавицы Жестокости', 'Кузнец-тролль по имени Ула\'елек готов выковать для тебя рукавицы жестокости. Он живет в Дуротаре, в деревне Сен\'джин, вместе со своими собратьями из племени Черного Копья, и с нетерпением ждет твоего прихода.', 'Поговорите с Ула\'елеком из Дуротара.', 'Привет тебе, $N. Старый Тунгрим предупредил меня о твоем приходе, но умолчи он, я не удивился бы твоему появлению.$B$BДухи следят за каждым твоим шагом, юный воин, и они говорят, что от твоей руки пало немало врагов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1840, 'Орм Каменное Копыто и шлем Жестокости', 'Искусство Орма Каменного Копыта пользуется заслуженным уважением. Он и сделает тебе шлем Жестокости.$B$BЕго можно найти в Громовом Утесе, рядом с прудом и центральным тотемом города.', 'Обратитесь к Орму Каменному Копыту из Громового Утеса.', 'Привет тебе, воин. Я Орм. Тунгрим сказал, что тебе нужен шлем. Это правда?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1841, 'Велора Нители и набедренники Жестокости', 'Говорят, что при жизни Велора Нители была одним из лучших кузнецов Лордерона. Кажется, она и после смерти не лишилась таланта. Поговори с Велорой, она сделает тебе набедренники Жестокости.$B$BВелора трудится в Подгороде Лордерона, в торговом квартале.', 'Поговорите с Велорой Нители из Подгорода.', 'Тебе нужны набедренники? Отлично!$B$BХм... Тогда кто из нас будет их делать?$B$BШутка. Смешно? Я вот не понимаю... Чувство юмора я утратила одновременно с обонянием. Примерно в те времена, как перестала дышать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1842, 'Копыта сатиров', 'Я могу сделать для тебя пару рукавиц Жестокости, напитав их магической силой. Но прежде тебе придется добыть эту самую силу.$B$BВ северо-восточной части Ясеневого леса живут сатиры. Их привлекла туда сила леса. Они питаются его первозданной чистотой, искажая и оскверняя ее. Сатиров, вобравших в себя особенно много магии Ясеневого леса можно отличить от других по разбухшим, нераздвоенным копытам.$B$BВ этих копытах содержится великая сила. Они понадобятся мне для создания рукавиц.', 'Принесите 7 целых копыт сатиров Ула\'елеку в Дуротар, в деревню Сен\'джин.', 'Ага, вот и они! Сатиры похитили силу Ясеневого леса, а их сила вольется в мое творение...', 'Копыта уже у тебя? Помни, они полны сильнейшей магии.', NULL, NULL, 'Нераздвоенное копыто сатира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1843, 'Рукавицы Жестокости', '', '', 'Спасибо, $N. Эти рукавицы – мое величайшее достижение. Возьми их. Ты окажешь мне честь, если пойдешь в них в бой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1844, 'Рог химеры', 'Я сделаю тебе шлем, но прежде докажи, что $gдостоин:достойна: его.$B$BВ северо-западной части Когтистых гор лежит Обугленная долина. Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все существа живущие там исполнены боли и отчаяния.$B$BТуда тебе и придется отправитсья, $N.$B$BСтупай в Обугленную долину и найди там химеру-матриарха. Избавь ее от страданий. Принеси в доказательство ее гибели гальванизированный рог, и я сделаю тебе шлем.', 'Принести Орму Каменному Копыту из Громового Утеса гальванизированный рог.', 'Что же, задание выполнено, $N. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты заслужил шлем...', 'Ну и где рог? Ты избавил матриарха от страданий?', NULL, NULL, 'Гальванизированный рог', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1845, 'Шлем Жестокости', '', '', 'Возьми этот шлем.Тебя привели ко мне великие свершения, и если Матери-земле будет угодно... тебе предстоит немало подвигов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1846, 'Берцовые кости', 'Чтобы создать набедренники жестокости, мне понадобятся прочные берцовые кости. У орков из клана Драконьей Пасти крепкие ноги. Они-то мне и нужны.$B$BНо только самые прочные. Непременно проверь их, прежде чем счесть подходящими. Если ты сможешь сломать их голыми руками, значит, они не достаточно прочные.', 'Принесите 8 крепких берцовых костей Драконьей Пасти Велоре Нители в Подгород.', 'Молодец! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались?$B$BОпять я пошутила. Ты не смеешься.$B$BЧто-то у меня не так с чувством юмора...', 'Я жду, когда ты принесешь берцовые кости. Из них выйдет отличная основа для набедренников.', NULL, NULL, 'Прочная берцовая кость Драконьей Пасти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1847, 'Набедренники Жестокости', '', '', 'Вот твои набедренники, $N. Ну как, подходят? Или надо что-то менять? Мне хочется угодить заказчику! По крайней мере всегда хотелось.Теперь ремесло утратило прежнюю прелесть. Но все лучше, чем быть безмозглым рабом Плети!Наверное.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1848, 'Хауберк жестокости', '', '', 'Тебе несомненно пришлось пролить немало крови, чтобы справиться с моим заданием, $N. Вот плод твоих трудов.Носи с удовольствием. Как-нибудь заходи, расскажешь, как он тебе пригодился в бою.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1858, 'Изувеченная Длань', 'Загляни в сумку Тазана и принеси мне то, что найдешь внутри. Замок там непростой, так что постарайся раздобыть ключ.$B$BНа трупе Тазана ключа не было? Значит, он его кому-то отдал... Ах, ну да, конечно. У него был помощник, Гамон. Он пьяница, так что ищи его в тавернах. Возможно, тебе удастся потихоньку утащить у него ключ.', 'Украдите ключ Тазана, откройте сумку Тазана и отнесите содержимое сумки Терзоку в расселину Теней в Оргриммаре.', 'Так-так, интересно... Что ж, $N, ты полностью оправдал мое доверие. Отныне можешь считать себя членом клана Изувеченной Длани. И возьми это. Думаю, он тебе очень пригодится в будущем.', 'Не ужасно ли это: держать в руках то, что тебе нужно, и не иметь возможности его достать?', NULL, NULL, 'Дневник Тазана', 'Сумка Тазана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1859, 'Терзок', 'Говори тише, $N! Ну да, я знаю твое имя. Мне сказали, чтобы я ждал одного орка, и дали описание твоей внешности.$B$BСудя по тому, что о тебе рассказывают, ты неплохо держишься в открытом бою, но можешь прибегнуть и к хитрости, верно?$B$BВ общем, сходи в Оргриммар, поговори с Терзоком. У него есть для тебя предложение.', 'Поговорите с Терзоком в расселине Теней в Оргриммаре.', 'А, это ты! Очень хорошо, что Каплак сумел тебя перехватить.$B$BНам нужно поговорить кое о чем, не в последнюю очередь – о твоем будущем в Раздробленной Руке.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1860, 'Поговорите с Джиннией', 'У нас, магов, есть одна задача, которая жизненно важня для безопасности Штормграда и Элвиннского леса.$B$BПодробности ты можешь узнать у Джиннии Пушки. Она работает в Башне магов, в районе магов в Штормграде. Не мешкай.', 'Поговорите с Джиннией Пушкой в Штормграде.', 'Тебя послали мне на подмогу, $N? Хорошо. Приятно видеть, что молодые маги рады внести свой вклад в общее дело…$B$BКакое дело, спросишь ты? Вырастешь – узнаешь. Обязательно узнаешь... со временем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1861, 'Зеркальное озеро', 'Этот мир пал жертвой магических войн, в результате которых нарушилось течение магической энергии. Мы попытались просчитать дальнейшие последствия, и многие из нас опасаются худшего!$B$BНо об этом мы поговорим позже. Для начала надо собрать все доступные сведения.$B$BВозьми этот сосуд, отправляйся к подножию водопада у Зеркального озера, что на юго-западе от Врат Штормграда, и принеси мне пробу тамошней воды. Я хочу исследовать ее на предмет заражения тлетворной магией.', 'Отнесите пробу воды из Зеркального озера Джиннии Пушке из Штормграда.', 'Спасибо, $N. Я исследую магические свойства этой воды. Будем надеяться, что их не окажется, а то, неровен час, окажется, что магия повлияла на всех, кто пил много воды из Зеркального озера.$B$BВозьми эту сферу или этот посох в знак моей благодарности за услугу. Пускай они служат тебе верой и правдой.', 'Ты принесла мне пробу, $N? Магические потоки Штормграда и Элвиннского леса ощутимо изменились, и я должна знать, что проникает в нашу воду.', NULL, NULL, 'Проба воды Зеркального озера', 'Фляга Джиннии', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1878, 'Награда за воду', '', '', 'Великолепно! Чем больше мехов с водой нам удастся добыть, тем ниже вероятность катастрофы! Можешь таскать их сотнями, и за каждые пять будешь получать все ту же награду.', NULL, NULL, NULL, 'Бурдюк с водой Скитальцев Пустыни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1879, 'Поговорите с Бинк', '$N! Бинк, моя коллега-гном из Стальгорна, прислала мне весточку. У нее возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты $gготов:готова: ей помочь, $N?$B$BЕсли да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна.', 'Поговорите с Бинк из Стальгорна.', 'О, я вижу в тебе неплохие задатки, да-да! Но чтобы стать хорошим магом, одних задатков мало. А не сликшом хороший маг – плохой маг. А из-за плохих магов и возникают все проблемы!$B$BОй, кажется, я немного забегаю вперед. Начнем сначала!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1880, 'Маг-тастический гизмонитор', 'Мы, маги, не просто щелкаем пальчиками и создаем забавные искорки! Мы контролируем поток магической энергии, основной ткани мироздания! Для этого требуется осторожность и решимость. И знания... Невероятно много знаний!$B$BОдно из моих устройств, маг-тастический гизмонитор, позволяет собирать и хранить множество знаний! Но увы, он утрачен! Когда мы бежали из Гномрегана, я оставила его в сундуке в одном из домишек за пределами города. Теперь там кишмя кишат лепрогномы!$B$BПрошу тебя, $N, верни мне гизмонитор!\"', 'Верните Бинк маг-тастический гизмонитор.', 'О, радость! Создавая гизмонитор, я и не догадывалась, в какую зависимость от него попаду! Теперь я могу возобновить свои исследования.$B$BСпасибо, Рискем! Вот, смотри. Это мой первый набор магических инструментов. Они не так блестят, как новые, зато проверены временем. Выбирай любой из них – все они могут тебе пригодиться.', 'Тебе удалось найти мой гизмонитор? Нужно найти его, пока источник питания не разрядился!', NULL, NULL, 'Маг-тастический гизмонитор', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1881, 'Разговор с Анастасией', 'У Анастасии Хартвелл есть задание, которое тебе как раз по плечу. Поговори с ней. Она живет в квартале магов в Подгороде. Готовься выполнить первое задание для магов Отрекшихся.', 'Поговорите с Анастасией Хартвелл.', 'Привет тебе, $N. Ты правильно поступил, откликнувшись на мой зов, но еще правильнее будет меня выслушать...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1882, 'Ферма Балнира', 'Чумные земли – гнусное место, творение Короля-лича. Он отравил землю, осквернил и убил все живое. Хотя в убийственной силе чумы есть что-то привлекательное, мы, маги Отрекшихся, считаем ее неуправляемой и недопустимой.$B$BДля начала надо понять, проникла ли она в Тирисфаль. Отправляйся на ферму Балнира в восточной части Тирисфаля. В саду растут цветы – львиный зев. Собери их и возвращайся.', 'Принесите львиный зев Бальнира Анастасии Хартвелл в Магический Квартал Подгорода.', 'Отличные цветы. Я отправлю их на изучение нашим аптекарям. Пусть поищут в них скверну Проклятых земель.$B$BМолодец, $N. Я предлагаю тебе выбрать награду – сферу или посох. И то, и другое может тебе здорово пригодиться.', 'Ну и где львиный зев? Этот цветок вбирает в себя магическую энергию, поэтому изучение этих растений поблизости от Чумных земель даст нам возможность понять, добралась ли чума нежити до Тирисфальских лесов.', NULL, NULL, 'Львиный зев Бальнира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1883, 'Разговор с Ун\'Тувой', 'Ун\'Тува, маг деревни Сен\'джин, обнаружил изменения в потоках магической энергии Дуротара и просит тебя о помощи. Поговори с ним и сделай все, что сможешь.$B$BПриди к нему на помощь, и со временем тебе откроются великие тайны.', 'Поговорите с Ун\'Тувой.', 'Привет тебе, $N. Хвала тебе, ибо ты ответил на мой зов о помощи. Будем надеяться, что ты справишься с заданием...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1884, 'Груды джуджу', 'Оказывается, нормальное течение магической энергии в Дуротаре нарушил чернокнижник Залазан с островов Эха. Для этого он разместил оскверненные фетиши, груды джуджу, среди домов центрального острова Эха.$B$BИз-за этого болеет здешнее зверье, а чернокнижники и пришельцы из преисподней, таящиеся во тьме, набираются силы.$B$BНеобходимо уничтожить эти груды джуджу, $N, прежде чем наши земли изменятся до неузнаваемости.', 'Уничтожьте 4 груды джуджу и вернитесь к Ун\'Туве из деревни Сен\'джин.', 'Я чувствую, что груды джуджу уничтожены. При удаче все труды Залазана пойдут н$Nку и в Дуротаре восстановится нормальное течение магической энергии.$B$BТвой подвиг во имя Орды достоин всяческой хвалы!', 'Торопись, $N. Уничтожь проклятые груды джуджу!', NULL, NULL, 'Уничтожено груд джуджу', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1885, 'Меннит Каркад', '$N? Вот уж не ожидал тебя увидеть после того, как тобой заинтересовался сам Каркад. Ничего нельзя сказать наперед...$B$BВ любом случае, тебе лучше встретиться с ним, и поскорее. Лучше тебе не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него.', 'Поговорите с Меннитом Каркадом в Квартале Разбойников Подгорода.', 'Хм. Несомненно, вы пришли сюда по первому моему зову, так? Не ожидал ничего иного от перспективного стража смерти.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1886, 'Стражи смерти', 'Чтобы вступить в ряды стражей смерти, элитной охраны лорда Вариматраса, тебе придется сперва доказать свои способности.$B$BНе буду лгать: это задание может окончиться твоей гибелью.$B$BМне нужна помощь в нескольких вопросах. Во-первых, принеси мне личные вещи Астора Хадрена – это вестник, путешествующий между Серебряным бором и Подгородом. Как ты это сделаешь - тебе решать.$B$BПока что это все, что тебе следует знать. Справишься - узнаешь больше.', 'Принесите рекомендательное письмо Астора Менниту Каркаду в Квартал Разбойников Подгорода.', 'Неплохо, $N. Первая часть испытания пройдена. Надеюсь, Андрон ничего не узнал о твоих действиях, и ты сможешь убедить его, что ты и есть тот вестник, которого он ждет.', 'Пришел доложить об успехе?', NULL, NULL, 'Рекомендательное письмо Астора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1898, 'Стражи смерти', 'Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умен, чтобы заподозрить неладное.$B$BЛорд Вариматрас подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства.$B$BПоговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалеку от Района Фармацевтов.', 'Поговорите с Андроном Гантом в Подгороде.', 'Ах да, я ждал тебя. Полагаю, наши общие знакомые довольны переданными сведениями?$B$BБоюсь, тебя спрашивать без толку, вряд ли тебя обременяют лишними знаниями. К чему доверять гонцу слишком много тайн?', 'Добрый день. Чем могу помочь?', NULL, NULL, 'Рекомендательное письмо Астора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1899, 'Стражи смерти', 'Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочел бы иметь дело с тобой.', 'Отнесите гроссбух Андрона Менниту Каркаду в Квартал Разбойников Подгорода.', 'Ну и ну, я и не рассчитывал вытянуть столько информации из Андрона. Дай-ка я изучу этот гроссбух повнимательнее и дам тебе следующее задание.', 'Как твои успехи?', NULL, NULL, 'Гроссбух Андрона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1918, 'Оскверненная стихия', 'Из убитого элементаля выпала ярко светящаяся сфера воды. Содержимое шара в лучшем случае отвратительно. Можно с уверенностью сказать, что то, что заразило воды озера Мистраль, находится в этой сфере.$B$BТак сразу и не скажешь, кого может заинтересовать эта находка – возможно, подскажет тот, кто послал вас к этому озеру, а именно Масток Райльшип с заставы Расщепленного Дерева.', 'Отнесите оскверненную водяную сферу Мастоку Райльшипу на заставу Расщепленного Дерева в Ясеневый лес.', 'Ты нашел какой-то грязный шар с водой и решил принести его мне? Я кто, по-твоему – представитель Служителей Земли или что? $B$BВообще-то, у меня появилась кое-какая идея... может, тебе и правда понадобится помощь Служителей Земли. В смысле, если это поможет разрешить ситуацию на озере, то я к твоим услугам.$B$BТы знаешь, кто такие Служители Земли, $N?', 'Да, в чем дело?', NULL, NULL, 'Оскверненная водяная сфера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1919, 'Задание Джиннии', 'Ты набираешься знаний и опыта, $gюный:юная: $N. Ты $gготов:готова: приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?$B$BЕсли да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда. У нее есть для тебя задание, которое впервые приоткроет окно в невидимый мир.', 'Поговорите с Джиннией Пушкой в Штормграде.', '$N, у меня есть для тебя задание. Да-да, прямо здесь, в квартале магов. Слушай внимательно, не будем терять время даром.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1920, 'Печальный отшельник', 'Сообщают о беспорядках в таверне \"Синий отшельник\", что в квартале магов. Там бродят странные невидимые существа, чувствую там образовался провал Маны.$B$BОтправляйся туда и поймай этих тварей. Чтобы они стали видимыми, воспользуйся заклятьем Проявления, одолей их и посади в шкатулки-духоловки. Как только наберешь достаточно этих тварей, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием.', 'Возьмите свиток заклятия Проявления и ящик с шкатулками-духоловками за спиной у Джиннии Пушки. Принесите 3 заполненных шкатулки-духоловки Джиннии в Башню магов.', 'Ну ты молодец! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир.$B$BТы приносишь сообществу магов все больше пользы, $N.', 'Тебе удалось поймать этих тварей, $N? Их необходимо изучить, чтобы выяснить, почему они появились в городе.', NULL, NULL, 'Заполненная шкатулка-духоловка', 'Ящик со шкатулками-духоловками', 'Свиток заклятия Проявления', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1921, 'Сбор материалов', 'За верную службу своим собратьям-магам тебе полагается одеяние волшебника. Его вполне может сшить Уинн Ларсон, если ты принесешь ей все необходимое.$B$BСамо одеяние шьется из льна, который легко найти, но кроме него понадобятся заряженные самоцветы Расселины, а их добывают исключительно в Руднике у Серебряного ручейка у озера Лок Модан. Горняки дворфов не смогли забрать их, и они лежат в ящиках по всему руднику.$B$BНабери льна, добудь самоцветы и принеси их Уинн Ларсон в суконную лавку Ларсона в район магов.', 'Отнесите 10 кусков льна и 6 заряженных самоцветов Расселины Уинн Ларсон в Штормград.', 'Да, превосходный лен. Из него выйдет отличная ряса. А после того, как я разошью ее самоцветами, получится настоящее одеяние для мага!', 'Привет, $N. Джинния предупредила меня о твоем появлении. Что ты мне несешь?', NULL, NULL, 'Льняной материал', 'Заряженный самоцвет Расселины', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1938, 'Трактат Ура по темной магии', 'Давным-давно в этой башне жили три мага, и один из них поддался искушению и занялся темными искусствами. Его уговаривали отказаться от черной магии, но тщетно. И он был изгнан.$B$BНовое пристанище изгнанного мага – башня Илгалара в Красногорье. Он унес с собой ценную книгу – Трактат Ура по темной магии.$B$BМы, маги Штормграда, хотим вернуть себе эту книгу. Отправляйся в башню Илгалара, найди этот фолиант в библиотеке и принеси мне.', 'Принесите Трактат Ура по темной магии верховному колдуну Андромату из Штормграда.', 'Я опасался, что Моргант спрятал книгу где-то еще или же нашел способ открыть ее и прочесть.$B$BХорошо, что он не успел, и что все печати, наложенные на этот трактат, сохранились в целости.', 'Тебе удалось добыть книгу? Ее тайны не для глаз непосвященных, и если слишком углубиться в нее, можно обречь себя на гибель.', NULL, NULL, 'Трактат Ура по темной магии', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1939, 'Верховный колдун Андромат', 'С тобой хочет поговорить верховный колдун Андромат. Он находится на верхнем этаже Башни магов, в квартале магов Штормграда.$B$BОбязательно поговори с ним, ведь Андромат – один из самых могущественных магов за пределами Даларана. Его совет стоит десяти других.', 'Поговорите с верховным колдуном Андроматом.', 'Привет тебе, $N. Рад тебя видеть. Надеюсь, у тебя найдется время выслушать старика...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1940, 'Безупречная паутина', 'Пожалуй, следует наградить тебя за безупречную службу. Пора тебе обзавестить одеянием, которое пристало носить магу твоего уровня. Если тебе удастся собрать все необходимые материалы, одеяние у тебя будет.$B$BСтупай в Сумеречный лес и убей побольше пауков, падальщиков-отшельников. Набери их паутины, только учти, годится лишь самая лучшая. Набрав достаточно паутины, отнеси ее Уинн Ларсон, которой принадлежит магазин \"Суконная лавка Ларсона\" в Квартале Магов. Она сошьет тебе одеяние.', 'Принесите 8 кусков безупречной паутины Уинн Ларсон в Штормград.', 'Неплохая паутина. Я немедленно примусь за работу!', 'Ах, да. Маги из Башни магов предупредили меня о твоем приходе. Ты несешь мне нужную паутину?', NULL, NULL, 'Нетронутая паутина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1941, 'Одеяние из ткани маны', '', '', 'Вот твое одеяние. Один из моих шедевров! Носи на здоровье, а если тебя спросят, кто шил... Посоветуй им обратиться в суконную лавку Ларсона!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1942, 'Одеяние волшебного плетения', '', '', 'Твое одеяние готово! Отличный шелк тебе достался... Ты уж прости, одеяние получилось довольно короткое, часть шелка я себе оставила.Шучу, шучу. Оно тебе идеально подойдет, причем будет уместно смотреться как в бою, так и на торжественном обеде. Наслаждайся!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1943, 'Разговор с Дейно', 'Магу Дейно нужна твоя помощь, $N. Она живет в Оргриммаре, в пристанище Темнотерна.', 'Поговорите с Дейно.', 'Хорошо, что ты здесь. Я хочу дать тебе довольно сложное задание. Оно жизненно важно для всего сообщества магов. Помоги мне, и маги отплатят тебе сторицей.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1944, 'Воды Ксавиана', 'В восточной части Ясеневого леса раскинулся прославенный город Ксавиан. Ученые всех народов слышали легенды о хранимом в нем древнем знании. Говорят, что воды Ксавиана содержат немало магической энергии.$B$BМне нужна проба воды из Ксавиана.$B$BВозьми этот сосуд и ступай туда. Набери воды у подножия самого большого водопада и возвращайся ко мне. Соблюдай осторожность – руины древнего города заполонили сатиры, им не нравится, когда в их дела встревают маги.', 'Принесите пробу воды из Ксавиана Дейно в Оргриммар.', 'А, отлично. Надеюсь, сатиры Ксавиана тебе не слишком сильно помешали?$B$BСпасибо, $N. Я немедленно займусь изучением пробы воды из Ксавиана.', 'Хорошо, что сосуд уцелел. А вода в нем есть? Мне не терпится изучить ее свойства.', NULL, NULL, 'Проба воды из Ксавиана', 'Фляга Дейно', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1945, 'Смеющиеся сестры', 'За верную службу тебе полагается новое одеяние, если ты принесешь все необходимые материалы.$B$BТебе придется вернуться в Ясеневый лес за локонами волос cмеющихся сестер – дриад, бродящих возле Приюта в Ночных Лесах.$B$BДобыв их волосы, отнеси их Кил\'хале, троллю-портному с Перекрестка, что в Степях. Он-то и сошьет тебе одеяние.', 'Принесите 12 волос cмеющихся сестер Кил\'хале с Перекрестка.', 'А, из этих волос выйдет отличное одеяние. Жаль, что приходится убивать Смеющихся сестер ради добычи волос, впрочем, добровольно они их все равно не отдали бы.$B$BЖаль, но не очень.', 'Привет тебе, $N. Дейно предупредила меня о твоем появлении. Она сказала, что ты принесешь волосы Смеющихся сестер. Это правда?', NULL, NULL, 'Волосы смеющейся сестрички', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1946, 'Одеяние из кружева Пустоты', '', '', 'Вот твое пустокружево. Оно прочное и удобное и хранит в себе магию волос Смеющейся сестрички.Наслаждайся. Если понравится, не забудь упомянуть об этом в разговоре с Дейно. Вот уж с кем бы не хотелось ссориться...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1947, 'Путь в болото', 'Пришло время заслужить магический жезл. Для начала поговори с отшельницей из Пылевых топей, человеком по имени Табета. Она живет в хижине в глубине болота, на западе от Терамора.$B$BЕе познания велики, и она сможет дать тебе добрый совет. Хижина Табеты находится чуть севернее руин Деревни Каменного Молота.', 'Поговорите с Табетой.', 'Тихо! Не беспокой меня, сейчас очень ответственный момент!$B$BМинуточку...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1948, 'Волшебные предметы', 'Создать жезл мага не так-то просто. Приходится искать редкие компоненты, да и собирать его надо так, чтобы он вмещал побольше магической энергии. Собери все необходимое и принеси мне.$B$BЯ составила список компонентов и заодно указала, где их искать. Четко следуй моим указаниям, в противном случае при создании жезла может случиться большая неприятность!', 'Принесите 1 нефрит и шипастый жезл Молний Табете в Пылевые топи.', 'Ага! Тебе удалось найти нефрит и сделать шипастый жезл! Молодец!$B$BУ тебя что, из ушей дым идет? Наверное, ты подошел слишком близко, когда молния била в заготовки. Такое случается. Не расстраивайся, получить удар молнии – хорошая примета!', 'Здравствуй, $N. Ты все компоненты принес?', NULL, NULL, 'Нефрит', 'Заряженный молнией жезл', 'Инструкции Табиты', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1949, 'Великие тайны', 'Для создания жезла мне нужно прочитать некоторые разделы одной книги. Называется она \"Ритуалы Силы\", а написал ее волхв Тирт.$B$BУ меня ее нет, да и ни в одной библиотеке ее не сыскать. Поэтому придется тебе найти Тирта и взять ее у него.$B$BУдачи. Когда-то он был великим магом и ученым, но теперь большую часть времени проводит на гоночном поле на Мерцающей равнине, пьет и играет в азартные игры.', 'Поговорите с волхвом Тиртом на Мерцающей равнине.', 'Что? Говори громче! У меня не такой острый слух, как бывало.$B$BНадеюсь, ты несешь мне кружку свежего эля или верные сведениями о следующей гонке! Если нет, проваливай... А то у меня наготове жезл превращения!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1950, 'Волшебное слово', 'Я помогу тебе с книгой, но сначала окажи мне услугу!$B$BНужная тебе книга заодно и магический сейф. Он открывается особой фразой, и ее-то я и забыл! Обычно мне напоминает помощник, но он куда-то запропал.$B$BЕсли тебе нужна книга, найди моего помощника! Поспрашивай у зрителей, вдруг кто-то его видел. Притащи его сюда или выбей из него волшебные слова!', 'Узнайте волшебные слова, отпирающие сейф Тирта и вернитесь к Тирту.', 'Ах да, припоминаю…$B$BЯ и правда наложил на Джонсона проклятье. Не помню, зачем я это сделал, но так ему и надо, маленькому нахалу!', 'Чего ты ждешь? Мне нужны волшебные слова!', NULL, NULL, 'Обнаружить секретную фразу', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1951, 'Обряды власти', 'Хм... Оказывается, книги-то у меня и нет! Видишь ли, мне пришлось отдать последнюю копию \"Обрядов власти\" за игорные долги какому-то жрецу...$B$BОдному из Алого ордена. Наверное, он унес ее в монастырь в Тирисфальские леса!$B$BЕсли тебе так нужна книга, придется сходить за ней в монастырь. Прости за доставленные неудобства. Я в последнее время сам не свой...', 'Принесите книгу \"Обряды власти\" Табете в Пылевых топях.', 'Вот она! То что нужно для последнего обряда создания жезла! Надеюсь, поиски были не слишком сложными?', 'Приветствую, $N. У тебя ли книга \"Обряды силы\"?', NULL, NULL, 'Обряды силы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1952, 'Магический жезл', 'Пойду, займусь созданием жезлов.', 'Поговорите с Табетой по завершении ритуала.', 'Ну вот, жезлы готовы. Выбирай любой!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1953, 'Возвращение на болота', 'Пришло время поговорить с Табетой... отшельницей из Пылевых топей. Она научит тебя создавать могущественные магические инструмены.$B$BХижина Табеты находится в глубинах Пылевых топей, западнее Терамора.', 'Поговорите с Табетой.', 'Ах, да. Тебе нужна сфера или жезл? Ну, хорошо. Я помогу тебе.$B$BВпрочем, знай. Это очень опасно и может привести к твоей гибели.$B$BИли моей гибели. В общем, кому-то умереть придется…$B$BБудем надеяться, что не нам, а?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1954, 'Сфера подземного огня', 'Первым делом тебе нужно заполучить сферу силы. У чернокнижников из клана Пылающего Клинка очень подходящие сферы... Жаль, что в каждой из них заключен демон! Но это поправимо, и очень даже.$B$BОтправляйся в Пустоши и отбери сферу подземного огня у призывателя из клана Пылающего Клинка. Призыватели живут на поле Маннорок.$B$BКак получишь сферу, возвращайся.', 'Принесите сферу Подземного огня Табете из Пылевых топей.', 'Ага, недурная сфера. Не в том смысле недурная, как охлажденная вода с соком в жаркий день.$B$BБолее того, она вовсе НЕ недурная, если посмотреть повнимательнее. Да не вода, сфера!$B$BСосредоточься, $N! Иначе с этим заданием не справиться!', 'Сфера Подземного огня у тебя?', NULL, NULL, 'Сфера подземного огня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1955, 'Поединок с демоном', 'У нас есть сфера призывателя, остается изгнать из нее демона.С этим я легко справлюсь.$B$BТебе придется куда труднее. Как только демон изойдет из сферы, убей его.$B$BГлавное – не медлить. Если ты провозишься слишком долго, он вернется в сферу и нам придется начать сначала!$B$BГотовься к схватке, $N. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелегким.', 'Убейте демона сферы, а потом поговорите с Табетой.', 'Великолепно, $N. Тебе удалось преподать этому демону урок, который он надолго запомнит.$B$BТеперь он трижды подумает, прежде чем вновь сунуться в наш мир. Однако если это произойдет, единственной целью демона будет найти того дерзкого смертного, что одолел его когда-то. Скорее всего, он вернется с приятелями. Огромными, жуткими приятелями, жаждущими твоей крови $B$BНу что, $N, тебе уже страшно?', NULL, NULL, NULL, 'Демон сферы убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1956, 'Сила Ульдамана', 'Демон уничтожен, остается завладеть источником энергии. К сожалению, самые лучшие источники энергии – старые, и заполучить их нелегко. Судьба любит над нами подшутить, а?$B$BИтак, тебе придется отправиться в Ульдаман и победить тамошнего обсидианового часового. Он большой и сильный, а уж какой у него источник энергии!$B$BУдачи тебе, $N. Ну, а если она от тебя отвернется... приятно было познакомиться.', 'Добудьте обсидиановый источник силы и принесите его Табете в Пылевые топи.', '', NULL, NULL, NULL, 'Обсидиановый источник силы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1957, 'Волнолов маны', 'Мы почти закончили, осталось самое опасное.$B$BНужно вдохнуть силу в пустую сферу призывателя. Для этого придется обуздать энергию провала Маны. Я произнесу заклинание, оно временно создаст нужный нам провал, из которого хлынут твари, волноловы маны. Тебе придется одолеть их, и тогда я смогу собрать воедино их силу.$B$BТвоя задача – убить достаточно волноловов маны, пока провал открыт, а я уж соберу всю энергию в твою сферу.', 'Убейте 12 волноловов маны за отведенное время.', 'Надо же, ты справился! Я в тебе не сомневалась! Ну ладно, чуть-чуть сомневалась, даже не чуть-чуть... Но не так уж сильно.$B$BЧестно.', NULL, NULL, NULL, 'Волнолов маны убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1958, 'Небесная сила', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1959, 'Задание Анастасии', 'Маги Подгорода заметили в городе выплеск магической энергии и обратились к чародеям Орды с просьбой выяснить, что же происходит.$B$BПодробности тебе расскажет Анастасия Хартвелл. Поговори с ней, она живет в Квартале Магов Подгорода.', 'Поговорите с Анастасией Хартвелл. ', 'Это правда. В нашем городе произошел выплеск магической энергии. Мы не поняли, что именно произошло, и даже к добру это или к худу. Не хватает информации…$B$BЧто подводит нас к разговору о задании.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1960, 'Лавка алхимика', 'В лавке алхимика Алжернона, что в Районе Фармацевтов, происходит что-то странное. Там бродят странные невидимые существа, сотканные из магической энергии.$B$BВозьми у меня за спиной шкатулки-духоловки и свиток с нужным заклинанием. Воспользуйся свитком в лавке, подчини этих существ и загони их в шкатулки. Как только наберешь достаточно, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием.', 'Возьмите свиток заклятия Проявления и ящик с шкатулками-духоловками за спиной у Анастасии Хартвелл. Принесите 3 заполненных шкатулки-духоловки, ящик со шкатулками духоловками и заклинание Проявления Анастасии в Подгород.', 'Отлично, $N. Лучшие умы Подгорода займутся изучением невидимых тварей. Мы выясним, откуда они взялись в нашем городе.$B$BЕсли дело в возникновении провала Маны, потребуется определить, случайно он возник или нет. Если не случайно,а в результате действий враждебных сил, нам придется готовиться к появлению более серьезных противников.', 'Ну, в чем же там дело, $N? Тебе удалось поймать невидимых тварей?', NULL, NULL, 'Заполненная шкатулка-духоловка', 'Ящик со шкатулками-духоловками', 'Свиток заклятия Проявления', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1961, 'Сбор материалов', 'Тебе пора обзавестись первым облачением мага, $N. Одеяние – знак твоего особого положения, свидетельство твоего достоинства.$B$BДля создания нужного одеяния тебе понадобятся самоцветы маны от даларанских магов из Серебряного бора. Они верят примерно в то же, во что и мы, поэтому убивать их нехорошо, но раз они не могут противостоять нам, значит жизни они не заслуживают.$B$BОтнеси камни и несколько кусков льна Джозефу Грегориану в суконную лавку Квартала Магов.', 'Принесите 10 кусков льна и 6 даларанских самоцветов маны Джозефу Грегориану.', 'Отличный материал. Оценить качество самоцветов я не могу, но вскоре мы узнаем, подходят ли они для создания одеяний из чароткани...', 'Анастасия предупредила меня о твоем приходе. Я готов сшить тебе одеяние. Где же лен и самоцветы?', NULL, NULL, 'Льняной материал', 'Самоцвет маны Даралана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1962, 'Одеяние из огненной чароткани', '', '', 'Вот твое новое одеяние, $N. Носи на здоровье.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1963, 'Изувеченная Длань', 'Вождь слишком хитрит и осторожничает. Он не хочет пускать в ход всю мощь Орды. Изувеченная Длань вернет Орде былую гордость!$B$BМы тайно копим силы и исподтишка наносим удары неосторожным врагам. Докажи свою доблесть, выполни мое задание!$B$BТролль по имени Тазан торгует с пиратами близ Кабестана. У него есть нужные мне сведения. Убей его и принеси мне его сумку.', 'Убейте Тазана и принесите его сумку Терзоку в расселину Теней в Оргриммаре.', 'Хм. Я, конечно, рад слышать, что Тазана больше нет в живых, однако от запертой сумки проку мало. Нам нужно то, что внутри!$B$BВот и второе задание для того, кто стремится вступить в клан Изувеченной Длани!', 'Только глупец может подумать, будто открытый удар топором опаснее кинжала в спину!', NULL, NULL, 'Сумка Тазана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1978, 'Стражи смерти', 'Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства.$B$BЛорд Вариматрас будет доволен, и раз именно ты $gсовершил:совершила: это открытие – тебе и сообщать о нем.$B$BАх да, как я мог забыть?$B$BДобро пожаловать в ряды стражей смерти.', 'Отнесите гроссбух Андрона Вариматрасу в Зал Темной Госпожи в Подгороде.', 'Хм, любопытно. Стражи смерти превосходно справились со своими обязанностями.$B$BСудя по всему, ты ждешь благодарности за свои подвиги. Скоро это станет для тебя привычным делом, $N. Стражам смерти не помешают талантливые новички.', 'Да?', NULL, NULL, 'Гроссбух Андрона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1998, 'Фенвик Татрос', 'Лорд Вариматрас сообщил мне о грозящей Отрекшимся опасности, с которой следует немедленно разобраться. Во всем виноват Фенвик Татрос, предводитель нежити, поселившейся в Серебряном бору.$B$BЯ немедленно вспомнил о тебе, $N, и сразу понял, кому следует доверить это задание. Ты не $gобделен:обделена: талантами и выполнишь поручение безукоризненно.$B$BПо последним сведениям от стражей смерти, Татроса видели неподалеку от разрушенной пристани озера Лордамер.', 'Убейте Фенвика Татроса и принесите его голову Менниту Каркаду в Квартал Разбойников Подгорода.', 'Прекрасно, $N. Ты оказался достойным помощником, а посему настало время продолжить твое обучение темным искусствам.', 'Я целиком положился на тебя. Выполни распоряжение лорда Вариматраса.', NULL, NULL, 'Голова Фенвика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (1999, 'Предметы торговли', 'Маги братства Кирин-Тора в Янтарной Мельнице хранят важные документы, касающиеся положения дел в Даларане. Эти сведения удалось вытянуть из одного пленника. Лорд Вариматрас поручил стражам смерти добыть эти документы.$B$BЧесть выполнить это задание выпала тебе, $N. Для задания понадобится кое-какое снаряжение и умение вскрывать замки. Поговори с Эстеллой Джендри, она поставляет нам обмундирование. Попроси у нее набор инструментов, перед тем как отправляться в путь.', 'Отыщите отчет о состоянии Даларана и отдайте его Менниту Каркаду в Квартале Разбойников Подгорода.', 'Прекрасно, $N. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал.$B$BВижу, я был прав, положившись на тебя. Поверь, мальчик мой, ты далеко пойдешь.', 'Удалось отыскать документы, $N?', NULL, NULL, 'Отчет о состоянии Даларана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2000, 'Рокар Тень Клинка', 'Слишком много ты бездельничаешь, $N. Пора тебе научиться чему-нибудь новому. Сегодня ночью пятерых из наших нашли мертвыми в расщелине в Оргриммаре, и почти никаких следов. У нас есть враги, которые действуют против нас нашими же методами.$B$BТебе пора научиться вскрывать замки.$B$BУвы, мои руки не очень подходят для этого ремесла. Отыщи Рокара, он живет в холмах возле Дуротара. Он уже стар, но, думаю, все еще не потерял форму.', 'Поговорите с Рокаром Тенью Клинка в Дуротаре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2038, 'Пропавшее снаряжение Бинглза', 'Мало того, что они вторглись в наши края, эти трогги атаковали меня с ближайшего острова и украли мои инструменты и особую взрывчатку – сорвиголовку Покрышкинса. Без вертолета и взрывчатки движению не обойтись!$B$BВерни мне инструменты и отыщи сорвиголовку, $N. За Гномреган!', 'Найдите и верните Бинглзу гаечный ключ Бинглза, отвертку Бинглза, молот Бинглза и сорвиголовку Бинглза.', 'Ты оказал движению огромнуюю услугу, $N. Скоро трогги и лепрогномы узнают, что такое воздушная атака!', '$N! Где мои вещи?!', NULL, NULL, 'Гаечный ключ Бинглза', 'Отвертка Бинглза', 'Молот Бинглза', 'Сорвиголовка Бинглза');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2039, 'Найти Бинглза', 'Мы потеряли связь с Бинглзом! Он был отправлен в разведывательный полет над Гномреганом, и уже неделю от него нет никаких известий. Я знаю только то, что он отправился в разведку и потерпел крушение.$B$BПоследний раз его видели над озером Лок. Возможно, ты сможешь выяснить, что с ним, $N.', 'Найдите Бинглза Покрышкинса в Лок Модане.', 'Значит, Гноарн сомневается во мне как в разведчике? Интересно, почему...$B$BЛадно, не берите в голову, мне нужна ваша помощь! Нет! Ваша помощь нужна нашему общему делу!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2040, 'Битва под землей', 'Гномреган захватили трогги! Ситуация крайне тяжелая, но, быть может, вы cможете помочь, $N.$B$BГлубоко под землей, в Мертвых копях, находится действующий гоблинский крошшер. Найдите его и принесите его источник питания. С его помощью мы сможем обеспечить наши автогиробуроройки достаточной энергией, чтобы пробиться через каменные границы Гномрегана и открыть дорогу армии гномов!', 'Принесите Шони Молшунье в Штормград зубчатый спрек-механизм гномов из Мертвых копей.', 'Хорошая работа, $N. Благодаря вам день освобождения Гномрегана приблизился еще на шаг!', 'Вы нашли зубчатый спрек-механизм гномов, $N?', NULL, NULL, 'Зубчатый спрек-механизм гномов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2041, 'Разговор с Шони', 'Возможно... Возможно, вы поможете нам в битве за Гномреган.$B$BВ Штормграде вы найдете командира нашей подземной штурмовой группы, Шони Молшунью. Шони нужна помощь в сооружении автогиробуророек.$B$BВы найдете ее среди дворфов в Штормграде.$B$BУдачи, $N.', 'Поговорите с Шони Молшуньей в Квартале Дворфов в Штормграде.', 'Вы с известиями от центрального командования?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2078, 'Месть Гиромачта', 'Эй, сухопутное создание, нужно, чтоб ты $gнашел:нашла: моего первого помощника.$B$BБерешь этот ключ, вставляешь ему в башку и ведешь сюда, чтобы он опять служил своему кэпу.$B$BЭтим мурлокам и их главарю не шибко понравится, когда ими займется мой первый помощник!', 'Найдите первого помощника Гелхака, Бешенатора 4100, и отведите его к Гелхаку.', 'Да-а-а... А ты, оказывается, больше, чем желторотая собачья акула, крыса ты сухопутная.$B$BКэп тебя, может, даже пустит палубу драить, если так и дальше пойдет...', 'И где есть мой первый помощник, $N? Пойдешь на корм акулам, если не поторопишься!', NULL, NULL, 'Первый помощник Гелхака', 'Ключ Штурмана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2098, 'Помощь Гиромачту', 'Жизнь пирата нелегка, сухопутное ты создание. Это не только грабежи да пьянки! Увы, мой корабль затонул совсем рядом с берегом из-за этих мерзких жесткозубов.$B$BПервое, что мне нужно, – это чтоб мой первый помощник был в рабочем состоянии!$B$BКогда меня вынесло на берег, ключ от моего первого помощника сломался от удара о скалы, и его части растащили обитающие на Темных берегах звери. Краем глаза я заметил разъяренных крабов, свирепых лесных долгоходов и мурлоков, обшаривающих останки корабля...', 'Отыщите три фрагмента ключа и отнесите их Гелхаку Гиромачту.', 'Ах ты ж, акула собачья! Тебе удалось все найти! Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждет!$B$BА кстати, ты не видел моего первого помощника?', 'Эй, сухопутник, еще не нашелся мой сломанный ключ?', NULL, NULL, 'Верхняя часть ключа Гелхака', 'Средняя часть ключа Гелхака', 'Нижняя часть ключа Гелхака', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2118, 'Зачумленные земли', 'Болезнь расползается по Темным берегам, захватывая сознания и тела всех, до кого добирается.$B$BНа медведей-осотников она подействовала особенно жестоко. Некогда благородные звери стали инструментами разрушения, бешеными и неистовыми. Возможно, у меня есть средство от этой напасти.$B$BОтнеси в лес эту ловушку и положи ее на землю. Любой бешеный колючешерстный медведь, попавший в нее, станет на короткий период времени послушным. В таком состоянии он будет следовать за тобой. Приведи его сюда, $N.', 'Поймайте бешеного колючешерстного медведя отведите его Тарнариуну.Если вам не удастся поймать зверя и вы потеряете ловушку, вернитесь к Тарнариуну Целителю Деревьев и попросите у него еще одну.', 'Наша работа только начинается, $N. Вы готовы к следующему заданию?', 'Вы привели ко мне больного зверя, $N?$B$BЕсли вам не удалось захлопнуть ловушку, не беспокойтесь – надежда Тарнариуна живет вечно. Если вам нужна еще одна ловушка, отмените ваше задание и вновь обратитесь ко мне.', NULL, NULL, 'Поймано бешеных колючешерстных медведей', 'Надежда Тарнариуна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2138, 'Избавление от заразы', 'Как я и боялся, целительное средство не действует.$B$BМеня очень печалит, что я вынужден приговаривать к смерти создания природы, но больных колючешерстных медведей придется истребить.$B$BВозвращайтесь в лес и уничтожьте 20 бешеных колючешерстных медведей, $N. Скорее всего, это не остановит зло, но хотя бы ненадолго замедлит наступление заразы на наш лес и его обитателей.', 'Очистите лес от 20 бешеных колючешерстных медведей и возвращайтесь к Тарнариуну Исцелителю Деревьев на Темный Берег.', 'Вы сослужили большую службу Аубердину, $N, но ваша работа на этом не закончена.$B$BОтдохните, а затем возвращайтесь ко мне.$B$B...И, $N, укрепитесь духом и разумом для дальнейшего кровопролития.', NULL, NULL, NULL, 'Бешеный колючешерстный медведь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2139, 'Надежда Тарнариуна', 'За выживание нашего народа и безопасность наших земель мы платим высокую цену, $N.$B$BВы пролили кровь слуг природы; вы сразили множество больных зверей. Народ Аубердина в долгу перед вами, поскольку боль истерзанного леса немного утихла – пусть и ненадолго.$B$BУ меня есть для вас последнее задание, но предупреждаю: вам снова придется убивать. Надеюсь, это последний раз, когда мне приходится побуждать вас к этому, $N. В пещере к северо-востоку отсюда, близ Башал\'Арана, живет мать-медведица. Убейте ее.', 'Найдите и убейте мать-медведицу.', 'Вы с честью и мужеством сражались на благо Аубердина, $N. В наших измученных войной землях смерть и отчаяние стали нормой. Многие уже не пытаются встретить лицом к лицу испытания в нашем новом доме, их выбор – либо скрываться в своих жилищах, либо бежать в более укрепленные и безопасные земли Альянса.$B$BСпасибо вам, $N. Может быть, вскоре мы с вами будем плечом к плечу биться против другого врага.', NULL, NULL, NULL, 'Мать-медведица убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2158, 'Отдых и покой', 'Каждому путнику рано или поздно нужно отдохнуть и восстановить силы – а для этого нет места лучше, чем таверна \"Гордость льва\".$B$BТам всем заправляет мой лучший друг Фарли. Скажи ему, что ты от меня – может, он даже скидки тебе даст на еду и выпивку.$B$BНайти \"Гордость льва\" несложно: нужно просто идти по дороге на юг. Не бойся, с пути не собьешься!', 'Побеседуйте с Фарли, хозяином \"Гордости льва\". ', 'Наш девиз – покой и отдых для всех усталых и продрогших! Прошу, садись у огня, отдохни с дороги.$B$BХочешь – отведай, чем у нас кормят, да и выпить чего-нибудь тебе не помешает...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2159, 'Посылка в Доланаар', 'Привет тебе, $gюный:юная:c: $C. Не окажешь ли ты мне услугу? У меня тут сверток с травами, который надо доставить в Доланаар. Но я еще не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться.$B$BНе отнесешь ли ты посылку? Ее надо доставить Кельдамиру – хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда.', 'Отнесите посылку хозяину таверны Кельдамиру в Доланааре.', 'Ах да, травы из Тенистой долины! Жаль, что Портанниус сам не смог ее доставить – нам с ним много что надо обсудить. Но я все равно рад получить эту посылку и познакомиться с тобой.$B$BПокуда ты здесь – чувствуй себя как дома. Герои должны быть крепки телом и духом, так что если выпадает возможность отдохнуть и подлечиться, надо ей пользоваться! Забота о теле и духе только приблизит тебя к победе!$B$BТак что располагайся поудобнее...', 'Чем я могу тебе помочь, юноша? Желаешь отдохнуть на постоялом дворе? Или тебе нужен камень возвращения?', NULL, NULL, 'Посылка в Доланаар (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2160, 'Припасы для Таннока', 'Похоже, тебе не впервой путешествовать, и трудности в дороге тебя не пугают. Что ж, раз уж ты все равно собираешься в путь, может, заодно прихватишь и посылочку в Каранос? Ее нужно отдать хозяину таверны.$B$BТы ведь не можешь не заглянуть в таверну. После всего, что тебя ожидает в пути – а ожидает тебя много чего, уж можешь мне поверить, – ты наверняка захочешь отдохнуть и перевести дух.$B$BТак вот, я тебя и прошу – передай кое-что помощнику хозяина; его зовут Таннок Молот Стужи. Я сам в одиночку до Караноса не доберусь, а патруля горных пехотинцев еще ждать и ждать...', 'Отнесите ящик с припасами хозяину таверны Танноку Молоту Стужи в Караносе.', 'О, гляди-ка, Ручник Ржавозубчик все-таки прислал припасы! Я уж начинал беспокоиться: с тех пор, как тут поселились трогги, из Старой Наковальни вести почти и не доходят.$B$BЯ тебе очень благодарен, $N, просто словами не передать, как. Ты тут располагайся, будь как дома, дорога-то была не из легких!', 'А, привет-привет! Заходи, садись у огня: тут и согреешься, и доброго эля выпьешь, с дороги-то...', NULL, NULL, 'Ящик с припасами для постоялого двора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2161, 'Ноша батрака', 'Извини... Ты не $gмог:могла: бы мне помочь?$B$BУ меня тут тяжеленная сумка с припасами. Я шел по дороге, на меня нападали и скорпиды, и пауки, и еще более страшные твари! Я нес припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать. Но оказалось, что припасы им не нужны! И вот мне придется тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут...$B$BНе $gмог:могла: бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – $gгерой:героиня:! Ты, небось, ничего не боишься...$B$BОтнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!', 'Отнесите сумку Укора хозяину таверны Гроску в Колючий Холм.', 'А-а, это припасы, которые Укор понес в долину Испытаний! Что, не пригодились? Ну да, конечно, они любят морить голодом молодых героев вроде тебя. Говорят, будто это закаляет дух!$B$BСпасибо, что принес припасы обратно. Пусть пока полежат на полочке... Погоди, не уходи, дай я тебя сначала чем-нибудь угощу!$B$BИ не забудь отдохнуть у нас на постоялом дворе. Конечно, ты отважен и готов горы свернуть, но если не отдохнешь, силенок не будет, а это не пойдет на пользу ни тебе, ни Орде!', 'Добро пожаловать в Колючий Холм!', NULL, NULL, 'Сумка Укора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2178, 'Спокойная жизнь долгоногов', 'Чувствуешь этот восхитительный аромат? Это мой секретный рецепт, $N – свежесваренная похлебка из долгонога. Настоящий деликатес!$B$BНе хочешь узнать рецепт?$B$BНо прежде, чем я тебя научу готовить это блюдо, докажи мне, что умеешь управляться с долгоногами.$B$BНет, я вовсе не жду, что ты пойдешь, приручишь одного и приедешь ко мне на нем верхом! Но если ты убьешь несколько птиц и принесешь мне их сочного мяса, это, пожалуй, убедило бы меня показать тебе, как готовится похлебка из долгонога.', 'Принесите 5 кусков мяса долгонога Аландариан Песне Ночи в Аубердин.', 'Фантастика! Попробуйте сами и скажите, что вы думаете об этом, $N!', 'Мой горшок пуст, а я проголодалась! Что ж вы так долго?', NULL, NULL, 'Мясо долгонога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2198, 'Рассыпавшееся ожерелье', 'Вы нашли потускневшее ожерелье, хотя даже то, что оно потускнело, не может исказить искусную, даже отчасти магическую работу создателя. Ожерелье было разрушено, поскольку в собранном виде в нем явно не хватает трех драгоценных камней. На обратной стороне ожерелья – почти стершаяся печать Стальгорна. Ниже печати – выгравированы три небольших буквы: \"ТдК\".$B$BЕсли вы хотите восстановить ожерелье, вы будете должны узнать о его происхождении. Возможно печать и эти буквы, помогут вам в этом.', 'Найдите создателя ожерелья, чтобы узнать, чего оно стоит.', 'Да, я – тот ювелир, который создал это ожерелье. Но больше ты из меня ничего клещами не вытянешь. За все надо платить, приятель, и информация не исключение. Если ты хочешь, чтобы я тебе помог, придется сначала помочь мне.', 'Ты ошибся гномом, приятель! Меня там и близко не было. Ты ничего не докажешь!$B$BПодожди, а тебе вообще, чего надо??? Что за... Где ты это взял?', NULL, NULL, 'Рассыпавшееся ожерелье (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2199, 'Мудрость за деньги', 'Я прославленный в нашем Стальгорне ювелир! Ну, был прославленным... У меня сейчас трудные времена, и все из-за козней конкурента! Дурная репутация в нашем ремесле приводит к финансовому краху. И в результате мое доброе, но недавно опороченное имя теперь медного гроша не стоит.$B$BЯ хочу, чтобы ты $gпринес:принесла: мне пять серебряных слитков, чтобы я сумел закончить заказ – первый за целую вечность!$B$BЕсли ты принесешь мне серебряные слитки, я отвечу на твои вопросы по поводу ожерелья.', 'Принесите пять серебряных слитков Талвашу дель Кисселю в Стальгорн.', 'Для меня теперь нет дороже друга, и плевать, что скажут другие... шучу, шучу! Правда, спасибо тебе огромное!$B$BИтак, ожерелье, которое теперь у тебя, – одно из лучших моих творений, но в нем не хватает трех драгоценных камней, что помогали удерживать в нем магическую силу. Некоторое время назад я сделал его для одного паладина. Он по личному побуждению отправился в поход, дабы выжечь \"злую скверну\" с раскопа в Бесплодных землях, в месте, называемом Ульдаман.$B$BВ общем... этот паладин погиб в Ульдамане, и это стало началом моих горестей.', 'Ты принес мне пять серебряных слитков, как я просил? Я поделюсь с тобой моей печальной повестью об ожерелье, коим ты ныне владеешь... Но только после того, как я получу слитки! Неужели ты не поможешь бедному гному?', NULL, NULL, 'Серебряный слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2200, 'Назад в Ульдаман', 'Мой конкурент распустил слухи, что мое ожерелье проклято и что оно-то и сгубило паладина. Нечего и говорить, что покупателей на проклятые ювелирные изделия больше не нашлось.$B$B$N, я предлагаю тебе сделку – найди драгоценные камни, и я восстановлю ожерелье, а ты расскажешь всем, что на моих изделиях НЕТ никакого проклятия!$B$BПопытайся найти разгадку гибели паладина в Ульдамане – может, его тело все еще там, ведь он последний владел этим ожерельем! Когда ты найдешь камни, воспользуйся вот этим – так ты сможешь связаться со мной в Стальгорне.', 'Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья.', 'В дневнике говорится, что после больших усилий паладин выяснил, где находятся все три камня:$B$BРубин спрятан дворфами Кузни Теней на огражденной завалами территории во время сражения с троггами за контроль над Ульдаманом.$B$BТопаз трогги спрятали в вазе, под боком у несколько неожиданных поселенцев Ульдамана – дворфов Альянса!$B$BНаконец, сапфир забрал себе старейшина троггов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2201, 'Время собирать камни', 'Дневник паладина дает, скорее всего, единственную подсказку, о том, где искать камни из ожерелья. Если верить записям паладина, то придется иметь дело с дворфами Стальгорна и троггами, борющимися за контроль над раскопками в Ульдамане.$B$BВооружившись этим знанием, отнесись к поискам этих камней серьезно. Когда ты найдешь камни, сообщи об этом Талвашу через фиал Видения и следуй полученным от него инструкциям.', 'Найдите рубин, сапфир, и топаз, которые спрятаны в разных местах Ульдамана. Когда найдете, свяжитесь с Талвашем дель Кисселем, используя фиал Видения, который он предоставил.Из дневника вы узнали следующее:*Рубин укрыт в забаррикадированном Тенегорне.*Топаз спрятан в урне в одной из областей, занятых троггами, недалеко от расположения дворфов Альянса.*Сапфир присвоил себе Гримлок, лидер троггов.', 'Ух ты! Да это и вправду три потерянных камня. Отличная работа! Но, к сожалению, это еще не все.$B$BНет, я не пытаюсь тебя надуть, поверь мне, $C. Дело в особенностях создания магической бижутерии - настоящей магической бижутерии от Талваша де Кисселя! Для того чтобы создать подобную вещь, нужен большой запас магической энергии, которой в этом ожерелье уже не осталось.', 'Образ Талваша появляется на поверхности воды в чаше.$B$B\"Ого! Да ты еще жив! Удалось ли тебе найти камни? Я так надеюсь, что тебе удастся спасти мою репутацию. Умоляю тебя, скажи, что ты не терял времени даром и вызываешь меня не для того, чтобы просто поболтать. Подобные сеансы стоят недешево, а я сейчас весьма стеснен в средствах.\"', NULL, NULL, 'Рубин рассыпавшегося ожерелья', 'Сапфир рассыпавшегося ожерелья', 'Топаз рассыпавшегося ожерелья', 'Окровавленный дневник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2202, 'В Ульдаман за реактивом', 'Мне рассказали о недавно открытом грибе-малиновике. Этот гриб растет целыми скоплениями на раскопках Ульдамана. Его можно отыскать в старых туннелях и самых глубоких местах, не потревоженных исследователями. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься.$B$BОтыщи эти грибы и принеси мне дюжину. Только учти: одно неосторожное движение, и они выпустят облако ядовитых спор.$B$BВыполнишь мое поручение – я сделаю для тебя один из моих знаменитых восстановительных эликсиров!', 'Принести 12 грибов-малиновиков Джаркалу Замшелому Клыку в Каргат.', 'Молодец, $N, ты снова показал, на что способен! Эти грибы очень пригодятся для моих исследований!$B$BА теперь, как я и обещал, можешь насладиться вкусом одного из самых действенных восстановительных составов из моих личных запасов...$B$BЕсли ты тоже увлекаешься алхимией, мы можем вдобавок поговорить о других делах. В любом случае, благодарю за помощь!', 'Ты принес грибы-малиновики для моих алхимических исследований? Нет грибов – нет награды!', NULL, NULL, 'Гриб-малиновик', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2203, 'Пробежка по Бесплодным землям-2', 'Ты $gоказал:оказала: мне неоценимую помощь, $C. Надо бы в награду дать тебе рецепт эликсира, который ты $gпробовал:пробовала:... Но прежде я дам тебе еще одно опасное задание. Вот моя просьба.$B$BВ этом сейфе находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опаленного дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне.$B$BДобудь мне кровь дракона, и я отдам тебе рецепт.', 'Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Джаркалу Замшелому Клыку в Каргат.', 'Между нами, алхимиками, говоря, ты просто герой! Вот, возьми этот рецепт. Пусть он принесет тебе успех и богатство, как и мне!', 'Ты уже наполнил сосуды кровью опаленных драконов-стражей? Знаю, задание опасное... но в случае успеха тебя ждет рецепт восстановительного эликсира. Игра стоит свеч, мой друг... игра стоит свеч...', NULL, NULL, 'Сосуд драконьей крови', 'Сейф с волшебными сосудами', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2204, 'Восстановление ожерелье', 'Тебе понадобится немного \"магической силы\" для ожерелья, и Ульдаман – лучшее место, чтобы ее раздобыть. Там бегает множество магических созданий. Поймай самое крупное и злобное, вынь из него источник магической силы и принеси его мне. Я уверен, что смогу вплавить его в ожерелье.$B$BБез источника силы, ожерелье починить невозможно. Возвращайся ко мне в Стальгорн, когда раздобудешь что-нибудь подходящее и мы быстро наладим для тебя эту вещь.', 'Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу дель Кисселю в Стальгорн.', 'Отлично! – Я рад видеть и тебя и этот источник силы в целости и сохранности. Теперь, когда драгоценные камни возвращены на сове место, восстановить само ожерелье, займет не больше минуты... Как только я это сделаю, оно станет твоим!$B$BВолнуешься, да? просто дрожишь от нетерпения? Тааак, на чем я в прошлый раз сосредотачивал фокус заклинания...', 'Ты не останавливался даже чтобы привести себя в порядок после Ульдамана, так ведь? Пришел прямо сюда благоухая подземельными ароматами. Что ж будем надеяться, что все эти жертвы были принесены не напрасно.$B$BУдалось тебе добыть источник силы для ожерелья?', NULL, NULL, 'Источник Силы рассыпавшегося ожерелья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2205, 'Выход на ШРУ', 'Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам. Ты выглядишь так, что Матиас может принять тебя за $gторговца:торговку: сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником. Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена.$B$BК делу! Доставь этот пакет Матиасу: возможно, у него тоже найдется для тебя пара заданий.$B$BНе задерживайся!', 'Доставьте пакет от Керина Сильвиуса мастеру Матиасу Шоу в казармы Штормграда.', 'Итак, тебе удалось меня отыскать. Глядя на тебя, я бы сказал, что для тебя это было серьезным испытанием как физических сил, так и умственных способностей.$B$BНу что, попросить Рензика показать тебе, где здесь постоялый двор, или ты сразу приступишь к работе?', 'Чем могу служить, $C?', NULL, NULL, 'Посылка для Матиаса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2206, 'Держи-хватай!', 'Наши полевые агенты сообщают о серьезной активности Братства Справедливости к югу от Златоземья. В этих донесениях указывается, что Братство захватило лагерь Джерода и теперь использует его как перевалочный пункт для переправки больших партий контрабанды из Красногорья в Западный край.$B$B$N, тебе нужно пробраться в доки и добыть расписание поставок. Скорее всего, портовой начальник носит его при себе.$B$B...и кстати, $N, если тебя обнаружат – ты ничего не знаешь о ШРУ...', 'Найдите портового начальника из Братства Справедливости и добудьте расписание поставок для мастера Матиаса Шоу.', 'Я потрясен... Потрясен, что Керин наконец-то нашла новобранца, из которого действительно может выйти толк. Возьмите этот клинок, $N. Придет день, когда ШРУ вновь призовет вас на службу. Совершенствуйте свое мастерство, пусть глаза ваши будут всегда открыты, а клинок – наточен.$B$BВы не заметите нас, но почувствуете, когда мы будем рядом...', 'С каждой минутой, что вы ошиваетесь тут, в казармах, ваша жизнь становится короче на 60 секунд.', NULL, NULL, 'Расписание поставок Братства Справедливости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2218, 'Путь к спасению', 'Еще одна заблудшая душа, стало быть, ищет наставничества? Полагаю, ты хочешь найти смысл жизни – смысл твоей жизни. Я тысячу раз видел, как другие герои искали работу.$B$BЧто же, сегодня тебе повезло. У Хограла найдется лекарство для твоего недуга.$B$BВот что ты сделаешь: иди по этой дороге до Стальгорна и там зайди в Заброшенный грот. Как окажешься там, найди воровскую гильдию и переговори с Хальфданом Чернобородом. Он укажет тебе путь к спасению.', 'Поговорите с Хальфданом Чернобородом в Стальгорне. ', 'Стало быть, ты считаешь себя настоящим мерзавцем? Достойным оказаться среди немногих избранных ребят Черной Бороды – стать офицером Тайного Круга?$B$BТолько настоящий прохвост так высоко себя ценит!$B$BТаких мы и ищем! Добро пожаловать, $N!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2238, 'Простая уловка', 'Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит.$B$BУ Тайного Круга есть свои жизненные ценности, $N. И эти ценности – драгоценности. Просекаешь?$B$BТеперь сдается нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берем свою долю, – ты улавливаешь нить?$B$BНам надо, чтобы ты $gпереговорил:переговорила: с Онином Макмолотом в Гномрегане и $gвернулся:вернулась: с ответом. Этот хитрый дворф спрятался среди прокаженных. Так что поосторожнее.', 'Найдите Онина Макмолота в Гномрегане.', 'Тсссс! Тише, балда. Нас подслушивают.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2239, 'Донесение Онина', 'Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день.$B$BМои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол\'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться.$B$BВсе в этом донесении, $r. Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг.', 'Доставьте донесение Онина Хальфдану в Стальгорн.', 'Большой крюк? Клянусь собственной бородой!$B$BТы постарался на славу, $N. Возьми вот этот кинжал и ступай. Круг призовет тебя снова, когда будет готов третий шаг.$B$BЧто такое третий шаг? Да тот, что идет после второго, а именно – хороший пинок тебе под зад.$B$BХочешь?', 'Ну, как тебе запашок лепрогнома? Чего ухмыляешься?$B$BНу, какие вести от Онина?', NULL, NULL, 'Донесение Онина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2240, 'Потайной чертог', 'Теперь вернемся к насущным задачам.$B$BТебе предстоит исследовать чертог Хаз\'мула. Проблема в том, что он находится за огромной, запертой дверью! К счастью, я знаю, как ее открыть.$B$BЯ записал все в своем дневнике, здесь на столе. Моя группа и я заперты здесь... Так что ты, $N, $gдолжен:должна: найти для нас чертог Хаз\'мула!$B$BПрочитай мой дневник и отправляйся в чертог. Потом поговори с геологом Грозовой Вершиной в Стальгорне.', 'Прочитайте журнал Балеога, исследуйте, потайной чертог и потом доложите об увиденном геологу Грозовой Вершине.', 'Вы видели чертог Хаз\'Мула? Потрясающе! Бейлог был уверен, что он существовал, но я, честно говоря, сомневался.$B$BСпасибо, $N. Теперь то, что вы обнаружили сподвигнет наших лидеров приложить все усилия к тому, чтобы отвоевать Ульдаман. А когда это место снова вернется под руку Стальгорна, все тайны Чертога Хаз\'Мула будут нашими!', NULL, NULL, NULL, 'Исследовать локацию', 'Исследуйте потайной чертог', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2241, 'Катись, яблочко...', 'Говорят, что я обезумел от любви.$B$BДа, я все время думаю о Сиарне. Да, мой дом полон рисунков и картин, с которых на меня смотрит Сиарна. Да, я часто целыми днями крошки в рот не беру, не сплю, не пью, а все плачу о нашей несбывшейся любви. Что в этом плохого?$B$BИ вот теперь она отказывается меня видеть. МЕНЯ! Я пытался письма ей писать, так она не желает ни с кем разговаривать, если только это не разбойник.$B$BНе отнесешь ли ты ей от меня этот цветок? И не забудь сказать ей, что он от Джаннока.', 'Отнесите розу Джаннока Сиарне в Дарнас.', 'Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать! Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться...$B$BНе хочешь ли подрядиться на одно дельце, $C?', 'Какая прелесть! Ты принес цветочки на собственную могилу!', NULL, NULL, 'Роза Джаннока (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2242, 'Зов судьбы', 'Нам кажется, что одно существо могло бы помочь нам понять, что происходит с лесами Тельдрассила. Увы, уговорить это существо может оказаться опасным делом.$B$BЭто сатир. Он скрывается на ветви на опушке Поляны Оракула. Пока всех, кто подходил к этому сатиру – с угрозами или добрым словом, – постигала мрачная судьба. Может, надо подкрасться к нему незаметно, $N?$B$BУзнай, что у Сетира Древнего в сумках, и возвращайся ко мне.', 'Найдите Сетира Древнего и принесите все, что сумеете найти, Сиарне.', 'Дурные вести, $N. Похоже, что зараза, охватившая леса и реки Темного Берега, начинает расползаться и по нашему дому.$B$BТы сослужил добрую службу, но больше ты уже ничем не поможешь. Прими этот клинок в награду за службу Тельдрассилу.', 'Ну так что там у Сефира Древнего обнаружилось, $N?', NULL, NULL, 'Записи Сетира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2258, 'Пробежка по Бесплодным землям', '$N, я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реагенты, которые можно отыскать в Бесплодных землях.$B$BВот что мне нужно: 5 вторых желудков канюка, 10 клыков скального койота и 5 осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не $gлюбитель:любительница: сражений, можешь попросить о помощи друзей.$B$BЯ неплохо заплачу, если ты принесешь мне все необходимое.$B$BЧто скажешь?', 'Принесите 5 вторых желудков канюка, 10 клыков скального койота и 5 осколков каменных элементалей Джаркалу Смешанному Лишайнику в Каргат.', 'Молодец, $N. Этого мне должно хватить на некоторое время. Вот обещанная плата.$B$BЕсли ты не против получить новое задание, то вот – мне нужны еще кое-какие реактивы. Некоторые из них можно найти только в глубинах ульдаманского раскопа. Добыть их нелегко, но и плата за помощь будет немалая.$B$BМожет быть, кое-что получше блестящих монет!', 'Ты принес все необходимое? Пока не принесешь, платить не буду.', NULL, NULL, 'Второй желудок канюка', 'Клык скального койота', 'Осколок каменного элементаля', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2259, 'Эрион Шепот Тени', 'Не бойся, $N, я не стану посылать тебя к Сиарне. Эрион требует твоего присутствия в Анклаве Кенария. Не медли!', 'Встретьтесь в Дарнасе с Эрионом Шепотом Тени.', 'Пора идти дальше, $R, – мир ждет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2260, 'Директива Эриона', 'Весть о ваших деяниях получила широкую огласку, $N. Настолько далеко, что даже разведка Штормграда желает лично побеседовать с вами.$B$BДорога не беспошлинная и небезопасная, но возможность стажироваться в ШРУ – это вам не жук чихнул!$B$BВас ждет целый новый мир, $N. Отправляйтесь в Старый город Штормграда и поговорите с Рензиком Ножом в штаб-квартире ШРУ.', 'Отправляйтесь в Штормград и посоветуйтесь с Рензиком Ножом.', 'Вы откликнулись на призыв ШРУ, $N, и проделали долгий путь от дальних берегов, чтобы вступить в наши ряды. Однако вам многому предстоит научиться.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2278, 'Платиновые диски', 'Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения. Когда ты касаешься их, у тебя покалывает пальцы, и перед тобой возникает Каменный Страж.$B$B\"Приветствую тебя! Я – хранитель знаний. Создание земельников было подробно описано и сохранено на Дисках Норганнона.\"$B$BТы раскрыл сокровищницу никому прежде неизвестных знаний!', 'Поговорите с каменным Стражем и запомните все, что он передаст вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона.', 'Прослушав инструкции каменного Стража, ты снова получаешь доступ к Дискам Норганнона, теперь уже зная историю создания земельников, троггов и дворфов. Слабый, краткий гул доносится из глубины дисков. Каменный страж говорит: $B$B\"Теперь Диски синтезировались. Дотронься до них еще раз, чтобы получить личную копию.\"', 'Голос каменного стража, кажется, проникает прямо в твою душу:$B$B\"Ты должен сначала дождаться распознания данных Дисков Норганонна; как только ты выполнишь это требование, тебе будет разрешено получить портативную версию сохраненных данных. Пожалуйста убедись, что ты полностью исследовал информацию в пределах этого хранилища.\"', NULL, NULL, 'Выслушайте каменного Стража', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2279, 'Платиновые диски', 'Ты прикасаешься к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул, и твой мешок вдруг становится тяжелее. Внутри ты обнаруживаешь миниатюрную копию Дисков.$B$BНесомненно, для увлекающихся историей Азерота, это – неслыханная ценность. Лига исследователей из Стальгорна как раз из таких. Возможно, они найдут применение этим дискам.', 'Отнесите миниатюрную копию дисков Норганнона в Лигу исследователей в Стальгорне.', 'Что это у вас там... ох мать моя... Откуда вы это взяли?$B$BНет, правда?$B$BВы кому-нибудь еще об этом расказывали?$B$BПРАВДА?!$B$BМой дорогой $C, Вы, возможно, только что совершили открытие года в области археологии! Богов ради! Кого я пытаюсь надуть, открытие столетия! Если эти диски – то, о чем я думаю, то они будут тем ключом, который мы так долго искали! Теперь мы сможем раз и навсегда доказать магическое происхождение дворфов!', 'Да, могу я вам чем-нибудь помочь? Я, вообще-то занят, в настоящий момент, делом, которое представляет немалую важность для всей Лиги. Но я весь внимание.', NULL, NULL, 'Миниатюрные платиновые диски (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2280, 'Платиновые диски', 'Вы прикасаетесь к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул, и ваш мешок вдруг становится тяжелее. Внутри вы обнаруживаете миниатюрную копию дисков.$B$BНесомненно, для увлекающихся историей Азерота это – неслыханная ценность. Мудрецы из Громового Утеса – как раз из таких. Возможно, они найдут применение этим дискам.', 'Отнесите миниатюрную копию дисков Норганнона кому-то из мудрецов с Громового Утеса.', 'Что это у нас тут?$B$BНевероятно, мой юный друг! На этих дисках записаны древние и давно утерянные тайны. Ты поступил мудро, принеся их мне.', 'Мой юный друг, я видел, как ты решительно направляешься к моей палатке. То дело, ради которого ты ищешь моего совета, имеет значение для всей Орды? Или ты хочешь, чтобы перед тобой открылась вся мудрость вселенной?', NULL, NULL, 'Миниатюрные платиновые диски (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2281, 'Встречи в Красногорье', 'Посылать тебя в бой равноценно убийству. Рензику не нужны лишние покойники. Но тебе, $N, бояться нечего: для тебя найдется не такое опасное дело.$B$BОтправляйся в Красногорье и поговори там с Люцием – этот тип связан с ШРУ. Он постоянно отирается у пристани в Приозерье вместе с остальными бездельниками.', 'Пойдите к Приозерью в Красногорье и поговорите с Люцием.', 'Что, $N, не слишком-то у тебя ловкие пальчики, верно? Ну, да не беспокойся: я и не из таких делал отличных разбойников!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2282, 'Лесопилка Альтера', 'Я долгие годы обучал молодых воров. В конце концов не всякому плуту от рождения достается ловкость и проворство, как у старого Люция.$B$BРядом с дорогой стоит лесопилка Альтера. Я оставил там сундук, а в нем – кое-что важное. Принеси его мне! Возвращайся с добычей, и получишь Воровской сертификат.', 'Откройте сундук Люция, достаньте руну воровства и вернитесь к Люцию в Приозерье.', 'Сумел открыть, да? Неплохая работа, $N.$B$BТеперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта.', 'Я забыл предупредить тебя насчет орков?$B$BГоворят, в последнее время они все время толкутся вокруг мельницы.', NULL, NULL, 'Воровская руна', 'Отмычки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2283, 'Пропавшее ожерелье', 'У нас есть для тебя работа – если у тебя, конечно, хватит пороху за нее взяться!$B$BВ глубине Бесплодных земель есть раскопки Ульдамана. Говорят, недавно там откинул копыта какой-то идиот-паладин. При нем было очень ценное ожерелье с тремя самоцветами: рубином, сапфиром и топазом.$B$BКороче, нам нужно это ожерелье, и мы готовы за него заплатить – чистым серебром! Если оно попорченное – ничего, как-нибудь починим.', 'Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу.', 'О-о, добыча! Отсюда чую, оно здесь... Дай-ка взглянуть…$B$BЭй, что это ты нам подсовываешь? Тут же камней не хватает. Ты что думал, мы не заметим? Даже Мальтон увидел бы, что камней нету!$B$BНу, может, это и не ты их спер... Но ведь ожерелье без них ничего не стоит! Не-ет, твоя работа еще не окончена!', 'Ну что, оно у тебя, это ожерелье? Если его у тебя нет, не получишь ни гроша!', NULL, NULL, 'Рассыпавшееся ожерелье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2284, 'Пропавшее ожерелье, этап 2', 'Эти камни наверняка остались где-то в Ульдамане! Это так же верно, как то, что Мальтон – балбес. Вернись и разыщи их!$B$BКак я уже говорил, если то, что нам рассказывали, правда, в нем были рубин, сапфир и топаз. Найди их и вставь обратно в ожерелье.$B$BГде они? А кто ж их знает? Может, тебе повезет отыскать труп того паладина. Может, они до сих пор при нем – если его, конечно, не обчистили.', 'Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана.', 'Похоже, вам-таки удалось отыскать останки паладина, о которых говорил Дран. Обыскав их, вы находите дневник паладина. Дневник в плохом состоянии, большая часть страниц перепачкана запекшейся кровью. Но и оставшийся текст – сплошная галиматья. Похоже, это язык людей.$B$BПридется вам найти кого-то, кто сможет это перевести.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2298, 'Королевская облава', 'И вот собрались мы уже разрабатывать фазу III, когда вломились несколько болванов Магни, стали нести какую-то чушь насчет воровства и что они арестуют некоторых членов Тайного Круга.$B$BДа только поди возьми старика Черную Бороду! Разборка пошла нешуточная, и каким-то образом всплыло твое имя!$B$BХочешь совет? Бери первого грифона из Стальгорна и дуй в Штормград. Иди в Старый город и там переговори с моим старым приятелем Рензиком Ножом.', 'Отправляйтесь в Штормград и найдите Рензика Ножа.', 'Всегда рад видеть в наших рядах ребят Хальфдана!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2299, 'К Хальфдану!', 'Где тебя носило, $N? Хальфдан всюду тебя искал. Мы уж подумали, что король забил тебя в кандалы.$B$BДуй в Стальгорн как можно быстрее и поговори с Хальфданом!', 'Отправляйтесь в Стальгорн и поговорите с Хальфданом Чернобородом.', 'Говори тише, $N, стража может услышать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2300, 'ШРУ', 'Слушай, рыбка, тебя тут Рензик искал.$B$BНа твоем месте я не заставлял бы его ждать – все-таки он правая рука Матиаса...', 'Отправляйтесь в Штормград и разыщите Рензика Ножа.', 'Как насчет того, чтобы приступить к работе? Или хочешь сначала вздремнуть?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2318, 'Трудности перевода', 'Зайдя в окончательный тупик, ты приходишь к выводу, что тебе нужна книга, написанная на понятном тебе языке. Перевести ее, к сожалению, может далеко не каждый. Ближайший к тебе такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях. Начать, пожалуй, стоит оттуда.', 'Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях.', 'Могучий $C, я знаю зачем Вы здесь, в Бесплодных землях. Я знаю, что Вам нужны мои умения по части языков. Вы – в поисках частей того ожерелья, которое вы нашли в Ульдамане.$B$BУдивлены? Не стоит – знать такие вещи – моя работа. Вместо этого давайте обсудим, что Вы сделаете для того, чтобы перевести дневник. Доверяйте мне – я – единственный, кто может перевести его.$B$BТак что позвольте мне сделать вам лучшее предложение, чем может Дран Дрофферз и можете без помех продолжать переговоры с ними. Заинтригованы?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2338, 'Трудности перевода', 'Скупщикам Дрофферсу и Сыновьям не хватит умения, чтобы восстановить чары на ожерелье, а вот я могу это сделать. Только дай мне изучить его, чтобы я научился делать подобные. Одолжи мне его на время, а я переведу для тебя дневник. Пока будешь искать камни, я как раз успею изучить ожерелье. $B$BЭто выгодно нам обоим. Ну, что скажешь?', 'Одолжите ожерелье Джаркалу. Взамен он переведет дневник.', 'Благодарю тебя, секрет ожерелий разгадать несложно, если иметь достаточно времени, чтобы изучить всего одно из них. $B$BА теперь погоди еще минутку, я произнесу заклинание, чтобы быстро перевести дневник с человеческого языка на понятный тебе. Я тролль слова, спроси кого хочешь в Орде, и тебе скажут: Джаркалу Замшелому Клыку можно доверять! Ну-с, приступим...', 'Молодец, умненький $C, чуешь свою выгоду! Так мы оба получим то, что нам нужно, а скупщики Дрофферс и Сыновья будут думать, что и они получили свое.', NULL, NULL, 'Непереведенные записи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2339, 'Найти самоцветы и источник энергии', 'Вот и перевод, ты можешь $gсам:сама: прочесть его. Там говорится, что рубин спрятан дворфами, топаз спрятали трогги, а сапфир прикарманил трогг по имени Гримлок. $B$BПослушай-ка, тебе потребуется источник энергии, чтобы ожерелье вновь заработало. Дран Дрофферс об этом даже не подозревает. Чтобы найти такой источник, отправляйся в Ульдаман, спустись в самую глубину и убей самую сильную тварь, которую сможешь найти. $B$BУверен, у нее ты и найдешь источник энергии!', 'Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане. Из дневника следует... * Рубин спрятан на огражденной завалами территории Тенегорна. *Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса.*Сапфир забрал Гримлок, старейшина троггов.', 'Отлично, $C! Скоро мы пожнем плоды наших трудов. Я закончил работу над ожерельем и уверен, что теперь смогу создать такое же. $B$BНо сначала я использую специальное заклинание, чтобы быстро исследовать эти самоцветы, прежде чем ты унесешь их и ожерелье в Оргриммар. Это займет всего пару минут.', 'Путешествие в Ульдаман в твоих интересах – тебе нужны самоцветы и источник энергии, чтобы вернуть ожерелью волшебную силу. $B$BТы доставишь камни головорезам в Оргриммар, а я сохраню источник энергии, поскольку именно он заставит ожерелье снова работать...', NULL, NULL, 'Рубин рассыпавшегося ожерелья', 'Сапфир рассыпавшегося ожерелья', 'Топаз рассыпавшегося ожерелья', 'Источник Силы рассыпавшегося ожерелья');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2340, 'Принести самоцветы', 'Ожерелье будет работать, только если самоцветы будут в сродстве с металлом оправы. Этот источник энергии поможет вернуть ожерелью магическую силу... Надеюсь. $B$BЯ с удовольствием предоставлю тебе камни, подходящие к ожерелью, если окажется, что источник энергии действительно работает. $B$BОтправляйся в Оргриммар и выполни, что $gобещал:обещала: скупщикам Дрофферсу и Сыновьям. Никому не сообщай о наших договоренностях, и, возможно, к твоему возвращению я приготовлю сюрприз.', 'Доставьте ожерелье и драгоценности Драну Дрофферсу в Оргриммар.', 'Ну, все в порядке. Я могу оставить себе и мешок? Спасибо, премного благодарен.$B$BИ все же лучший трофей – это ожерелье! Не строй такую кислую мину, оно было бы тебе не к лицу! $B$BСделка есть сделка, поэтому вот твоя награда за принесенные трофеи. Что ж, с этим покончено, можешь заглядывать иногда, если понадобится работа. А пока будь любезен, покинь помещение!', 'Смотри-ка, кто пришел, кто потратил свое драгоценное время, чтобы заглянуть к Драну Дрофферсу! Будем надеяться, твой визит не станет пустой тратой времени для меня. Пока не получу, что просил, платить не буду, имей это в виду. И можешь не сомневаться – перепроверю все, что ты принес дважды и трижды!', NULL, NULL, 'Ожерелье и драгоценности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2341, 'Пропавшее ожерелье, этап 3', 'Полдела сделано. Дран и Мальтон Дрофферсы уже ссорятся из-за новой добычи. Теперь нужно сходить в Бесплодные земли – возможно, у Джаркала Замшелого Клыка из Каргата найдется для вас особая награда...', 'Навестите Джаркала Замшелого Клыка в Каргате.', 'Источник силы, полученный от тебя, превзошел все мои ожидания! Мне удалось сделать два ожерелья – тебе и мне, – и в нем осталось достаточно энергии, чтобы сделать как минимум еще три! Я на этом неплохо наживусь, а семейка Дрофферсов ничего и не узнает!$B$BВот, держи. Я тебе очень благодарен... а это знак моей благодарности!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2342, 'Возвращенные сокровища', 'Гарреттам не пристало мести загоны для летучих мышей такой метлой! Мерзкая работенка позволила мне заработать немного денег, и я хочу истратить их на улучшение своего положения.$B$BФамильное \"оружие\" Гарреттов заперто в нашем сундуке в Южном зале Ульдамана. Там наша семья трудилась долгие годы. Без него я застряну тут навеки – в буквальном смысле – и буду мести за проклятыми летучими мышами до скончания веков.$B$BПринеси мне наше сокровище! Помоги вернуть то, что положено мне по праву рождения!', 'Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана.', 'Наконец-то – метла, достойная Гарретта. Не зря я потратил на тебя деньги!$B$BВы слышите меня, летучие мыши? Теперь у меня есть истинное оружие семьи Гарреттов! Трепещите, проклятые пискуны!', 'Уборке нет конца... летучие мыши смеются надо мной и моей метлой. Скажи, ты ведь принесешь мне фамильное сокровище? Я готов отдать тебе все мое серебро – неужели этого недостаточно?!', NULL, NULL, 'Фамильное сокровище Гарретта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2358, 'Рога Нез\'ры', 'Много лет назад рога Незры были похищены из поместья Черного Ворона. Я искал их по всем морям и континентам и только теперь выяснил, что они все время находились у этих ничтожных тварей.$B$BУбей всех орков из клана Черной горы, которые встретятся тебе на пути, забери у них рога Незры и возвращайся ко мне в Приозерье.$B$BОкажи мне эту услугу, и заслужишь благодарность всех Черных Воронов.', 'Верните рога Незры Арантиру в Приозерье.', '', NULL, NULL, NULL, 'Рога Нез\'ры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2359, 'Башня Клейвена', 'Я за этой башней уже не первую неделю наблюдаю, $N. Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи.$B$BКто такие? Мы можем только гадать. Одно я тебе скажу: это не люди.$B$BКак бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет. А ключ от сундука – у того зомби с шипами.$B$BДобудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесешь Матиасу.', 'Добудьте ключ от башни Братства Справедливости, проберитесь в башню и выясните, каково содержимое сундука из Сумеречного леса. Отнесите найденные вещи Матиасу Шоу в Штормград. Почитайте дневник Кирнен, чтобы больше узнать о башне.', 'Это объясняет присутствие мертвяков из Братства Справедливости, которых вы с Кеарнен видели рядом с башней. Это может объяснить и вовлеченность Торговой Компании в дела Братства Справедливости и эти странные поставки из Сумеречного леса.$B$BКак явствует из этой книги, тролли Занзила в Тернистой долине нашли возможность поднимать мертвых с помощью зелий... выражаясь точнее – ядов.$B$BВы бесполезны для ШРУ, если у вас нет четкого представления о ядах, $N, особенно когда рецепт того, как поднимать нежить, почти у нас в руках.', 'Есть какие-то новости от посланницы Кеарнен?', NULL, NULL, 'Дневник Клейвена Мортвейка', 'Ключ от башни Братства Справедливости', 'Дневник Кеарнен', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2360, 'Матиас и Братство Справедливости', 'Произошло то, чего я ожидал, $N. Разведотдел ШРУ сообщает, что Братство Справедливости что-то затевает в Западном крае.$B$BСкладывается впечатление, что Братство захватило покинутую сторожевую башню Альянса к юго-востоку от Сторожевого холма и использует ее как базу для ввоза контрабанды из Красногорья.$B$BОтправляйся в Западный край и свяжись с агентом Кирнен для подробного доклада. Она там прячется, неподалеку от башни.$B$B... и кстати, $N, если тебя раскроют – ты ничего не знаешь о ШРУ...', 'Найдите посланницу Кеарнен в Западном Крае и поговорите с ней.', 'Наконец-то Матиас прислал еще одного агента мне в помощь. Ну, надеюсь, он готов к вороху неприятных новостей.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2361, 'Восстановление ожерелье', '', '', 'Я с великой радостью вручаю тебе это ожерелье, могучий $C. Ты оказал мне неоценимую услугу, и я благодарен тебе за это. Носи же его с гордостью и не забывай при этом все время упоминать о том, кто сделал его для тебя!Да, если еще добавишь, что на ожерелье нет проклятия, это будет великолепно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2378, 'Поиски Изувеченной Длани', 'Ты много $gсделал:сделала: для стражей смерти, но пришло время двигаться дальше. У тебя талант к искусству обмана и скрытности, но этот талант еще следует развить.$B$BУ стражей смерти есть союзники в Изувеченной Длани. Поищи среди них тех, кто готов помочь нам. Для начала поговори с Шентулом в Оргриммаре.', 'Отправляйтесь в Оргриммар и поговорите с Шентулом в Расселине Теней.', 'Так вот кого могучие союзники прислали Шентулу... Не впечатляет…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2379, 'Зандо\'зан', 'Одной твоей решимости еще недостаточно, чтобы преодолеть препятствия, которые ждут впереди.$B$BПоговори с Зандо\'заном, чтобы начать учиться на агента Изувеченной Длани.$B$BЛишь овладев навыками незаметности и коварства, ты сможешь сделать следующий шаг.', 'Поговорите с Зандо\'заном в расселине Теней.', 'Быть может, Зандо\'зан ошибся. Зандо\'зан просит прощения.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2380, 'В Оргриммар!', 'Ты, конечно, далеко еще не специалист по скрытности и всяким уловкам, однако же тебе есть куда расти. По крайней мере, начальство явно обратило на тебя внимание: сам великий Шентул запомнил твое имя!$B$BСтупай на север – эта дорога ведет в Оргриммар. Отыщи там в расселине Теней Шентула и поговори с ним.', 'Поговорите с Шентулом в расселине Теней в Оргриммаре.', 'Очень важно, чтобы Изувеченная Длань сохраняла бдительность перед лицом перемен, которые Тралл намеревается ввести в Орде. Числом тут не возьмешь – для нас главное незаметность и разнообразные уловки!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2381, 'Грабь награбленное', 'Не хочу тебя пугать, $N, но последние пять воров, которым я поручил похитить сокровище Южного моря, не вернулись. Потом их нашли... Частично.$B$BВ южной части побережья пришвартован пиратский корабль, \"Стрела прилива\". В трюме у него хранится то самое сокровище. На второй палубе устроен пиратский притон, в котором они натаскивают своих воров.$B$BПроникни на этот корабль, похить сокровище и принеси его мне. Если тебе надо поднатореть в воровском искусстве, можешь заглянуть в притон, но соблюдай осторожность!', '', 'Немыслимо! Невероятно! Поразительно! Да ты талант, $N. Или же ты самый везучий парень на свете!$B$BВот твоя доля. Думаю, ты найдешь ей лучшее применение, чем я.', 'Что ж, по крайней мере, ты пока цел. А сокровище нашел?', NULL, NULL, 'Сокровище Южного моря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2382, 'Реникс из Кабестана', 'Зандо\'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо\'зан слишком много болтает.$B$B$N! У Зандо\'зана есть поручение для тебя! $N $gдолжен:должна: отправиться в Кабестан, к востоку от Перекрестка, и поговорить с Рениксом Презренным. Ступай!', 'Поговорите с Рениксом Презренным в Кабестане, что в Степях.', 'Как, опять? Предыдущие пятеро, кого прислал ко мне этот чокнутый тролль, пошли на корм акулам. Ну что ж, будем надеяться, что тебе повезет…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2383, 'Записка на пергаменте', 'А, $N! Тебе тут пергамент прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить. Он обычно сидит в тени у входа в Логово.', 'Прочтите пергамент и поговорите с Франгом в долине Испытаний.', 'А-а, да, это я тебе написал... Я слышал, что ты скоро тут появишься, $N. Рад, что тебе удалось добраться сюда невредимым – будем надеяться, что ты переживешь и грядущие испытания. Наберешься сил – приходи ко мне. Я сделаю все, чтобы из тебя получился настоящий воин.$B$BУдачи, $N! Возвращайся, когда будешь готов.', 'Что у тебя там? Пергамент? Ты что, грамотный?', NULL, NULL, 'Записка на пергаменте (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2398, 'Потерянные дворфы', 'Раскопки в Ульдамане не всегда были захвачены троггами. Изначально мы, дворфы Стальгорна, вели здесь работы, но потом... Потом появились эти твари. Они прибыли столь быстро и в таком количестве, что дворфы не смогли ничего поделать.$B$BЧестно говоря,  их нападение было настолько внезапным, что многие наши люди могли не успеть вырваться из осады. Боюсь, они по сей день остаются в ловушке в тылу врага.$B$BМой друг Бейлог руководил небольшим отрядом дворфов в глубине раскопа прямо перед нападением троггов. Если он и его ребята живы, то я хочу, чтобы ты $gнашел:нашла: их.', 'Найдите Бейлога в Ульдамане.', 'Ты как раз вовремя! Я уже боялся, что проспорю Олафу!$B$BОн бился об заклад, что его борода достанет до колен, прежде чем мы увидим живое лицо, $C.$B$BИ вот, ты здесь, а бороде Олафа еще до колен осталась пара дюймов.$B$BСпасибо, $N! Я обязательно поделюсь с тобой выигрышем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2399, 'Росток папоротника', '', '', 'Папоротник, который Деналан посадил у себя в саду, проклюнулся и вырос. Ростки так и просят, чтобы их скорее собрали...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2418, 'Силовые камни', 'Есть у меня зуб на этих дворфов Тенегорна! Пару лет назад они пригласили меня в Крепость Ангор, чтобы я исследовал для них два образца прелюбопытнейших камней, привезенных с ульдаманского раскопа. Я провел исследования, и вообрази, что это было? Энергия! Каждый камень был мощнейшим источником энергии в сжатом, потенцированном виде – нужно только знать, как правильно высвободить ее! Чего только не найдешь в Ульдамане... $B$BВ общем, как только я рассказал об этом дворфам, они вышвырнули меня из крепости и направились в Ульдаман за чудесными камнями. $B$BМне бы такие, знаешь ли, тоже пригодились. Принеси мне несколько обоих видов, и я щедро вознагражу тебя.', 'Принесите 8 дентриевых силовых камней и 8 энелиевых силовых камней Ригглфаззу в Бесплодные земли.', 'Прекрасно, ты принес их! Ты самый благонадежный $R, которого мне приходилось встречать! $B$BНемедленно опробую эти камни на моих последних механизмах! Нутром чую, с этими камнями можно создать вечный двигатель!', 'Ну, что там с камнями? Мне нужен источник питания для моей механической мышки...', NULL, NULL, 'Дентриевый камень силы', 'Камень могущества Ан\'Аллеума', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2438, 'Изумрудный ловец снов', 'Некогда Гэролас Талветрен, страж друидов обители Бен\'этиль, подарил мне изумрудного ловца снов. Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит.$B$BУвы, мне не удалось забрать его из моего шкафчика в деревне Звездного Ветра... Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там.$B$BМожет, тебе удастся добыть моего ловца снов, $C?', 'Принесите изумрудного ловца снов Таллонкаю Гибкому Корню в Доланаар.', 'Мой изумрудный ловец снов очень много для меня значит. Такие подарки лишь немногим дарят. Прими мою благодарность за его возвращение, $N.', 'Прошу, быстрее. Могу лишь надеяться, что фурболги не повредили моего ловца снов.$B$BТы еще не добыл его, $N?', NULL, NULL, 'Изумрудный Ловец снов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2439, 'Платиновые диски', 'Это невероятная находка. Согласно этим дискам, Древние Титаны, или Создатели, имеют отношение к нашему чудесному возникновению! Нам нужно уделить как можно больше времени их изучению.$B$BА вас, $gгероический:героическая:c: $C, прошу принять этот сертификат и отнести его Дините Каменной Мантии в хранилище. По нему вы получите то, что, на мой взгляд, будет достойной наградой за такую находку!$B$BКогда будете готовы, возвращайтесь ко мне – у Лиги исследователей еще много работы для вас!', 'Отнесите наградной сертификат Дините Каменной Мантии в хранилище Стальгорна.', 'Ах, сертификат Лиги Исследователей... и весьма ценный, смею заметить.$B$BЛига Исследователей дает мне полномочия предложить вам выбрать себе награду прямо из хранилища. Награда ваша, так что выбирайте – либо пять наилучших целебных зелий, либо пять сильных зелий маны.', 'Добро пожаловать в хранилище Стальгорна, $N. Чем могу помочь?', NULL, NULL, 'Наградной сертификат (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2440, 'Платиновые диски', 'Я сосредоточу свои усилия на исследовании этих дисков, и со временем они раскроют мне свою тайну.$B$BА тебя $N, я награжу за то, что ты $gобратил:обратила: на них мое внимание. Отнеси этот сертификат Бене Заиндевевшее Копыто, наставнице алхимиков в Громовом Утесе. Она даст тебе один интересный предмет, который наверняка тебе понравится, а еще она даст тебе на выбор зелий из моих личных запасов.$B$BВозвращайся поскорее, ибо я чувствую, что мы стоим на пороге великого открытия.', 'Отнесите наградной сертификат Бене Заиндевевшее Копыто в Громовой Утес.', 'Что же, $N, ты, видать, угодил ведуну Искателю Истины, принеся ему ту штуку. Так что вдобавок ты получишь в награду зелья из его личного хранилища. Можешь выбрать или 5 наилучших целебных зелий, либо 5 сильных зелий маны.', 'Привет тебе, $C! Ты пришел сюда учиться алхимии или за чем-то еще?', NULL, NULL, 'Наградной сертификат (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2458, 'Надежное прикрытие', 'Торговая Компания... Доводилось тебе слышать про такую?$B$BМы в течение года пытались внедрить агента в их ряды. Это было непросто, но мы преуспели.$B$BНедавно мы получили сведения, что Торговая Компания затевает что-то крупное. Ступай к башне Торговой Компании, которая стоит к северу от Нефтяного болота, и свяжись с нашим тайным агентом, надсмотрщиком Физзулом.$B$BКогда найдешь башню, используй это сигнальное ружье, потом подойди к Физзулу и покажи ему приветствие Изувеченной Длани.', 'Отыщите башню Торговой компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.Возле башни выстрелите из сигнального ружья ДВА раза, потом подойдите к надсмотрщику Физзулу и продемонстрируйте приветствие Изувеченной Длани (команда :честь).Все нужно делать строго по порядку – Физзул убивает всех, кто кажется ему подозрительным.', 'Приятно видеть в здешних местах еще одного агента Изувеченной Длани! Вот только боюсь, как бы твоих вспышек не заметил кто-то лишний.$B$BВ следующий раз, как тебе нужно будет со мной поговорить, дважды свистни в этот свисток, и я пойму, что это свои.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2459, 'Фероситас Пожиратель Снов', 'Изумруд... Он пропал! Мой ловец снов поврежден!$B$BК северу от деревни Звездный Ветер засела шайка мистиков из племени Кривой Сосны. Я слышал, что их вожак, Фероситас Пожиратель Снов, носил ожерелье, которое светится зеленым в ночи. Теперь, глядя на своего ловца снов, я уверен, что это он украл мой изумруд... Он не понимает, что его сила для него бесполезна.$B$BНайди этот пропавший драгоценный камень, $N. И раз уж ты здесь, истреби заодно и этих зловредных мистиков.', 'Таллонкай Гибкий Корень из Доланаара хочет, чтобы вы убили 7 мистиков из племени Кривой Сосны и нашли пропавший самоцвет.', 'Теперь я восстановлю своего ловца снов! Спасибо тебе, $N.', 'Пусть Фероситас и эти мистики Кривой Сосны вернут то, что принадлежит мне! Прошу тебя, отними у них изумруд, чтобы я мог восстановить своего ловца снов.', NULL, NULL, 'Мистик из племени Кривой Сосны убито', 'Самоцвет Таллонкая', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2460, 'Приветствие Изувеченной Длани', 'Теперь, когда ты – разбойник Изувеченной Длани, тебе следует обучиться особому приветствию. Это знак, по которому мы опознаем своих.$B$BСмотри и повторяй за мной.', 'Повторите приветствие Изувеченной Длани вслед за Шентулом.', 'Молодец, $N! Теперь мы можем продолжать.', 'Повтори!', NULL, NULL, 'Приветствие Изувеченной Длани выполнено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2478, 'Миссия: выполнима, но с трудом', 'Тебе придется украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне еще пригодится.$B$BНе забудь: яд ослабил всех в этой башне. Покажи, на что ты $gспособен:способна:, неси хаос и разрушение в стены башни. Убей всех – жалости тут нет места!$B$BКогда внутри останутся лишь кровавые ошметки, возьми сейф Галливикса и укради из него запас смеси Занзила. Отнеси голову Галливикса и смесь Шентулу в Оргриммар.', 'Украдите ключ от башни у штейгера Силиксиза, убейте двух мертвяков-мутантов Торговой Компании, двух патрульных Торговой Компании и двух смотрителей Торговой Компании.Ликвидируйте старшего мастера Галливикса, взломайте замок на его сейфе и украдите запас измененной смеси Занзила. Отнесите запас смеси и голову Галливикса Шентулу в Оргриммар и получите следующие указания.', 'Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену, $N. Да, работа агента Изувеченной Длани опасна.$B$BНо ты отлично справился с заданием, $C. Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам.', 'Докладывай, $N.', NULL, NULL, 'Мутировавший мертвяк из Торговой компании убито', 'Наблюдатель Торговой Компании убито', 'Патрульный Торговой Компании убито', 'Голова Галливикса');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2479, 'Помощь Хинотта', 'Отнеси образчик этой смеси Сержу Хинотту в Мельницу Таррен.$B$BЕсли кто сможет тебя исцелить, так это Серж. Он тебя обучит всему, что связано с ядами, – если, конечно, выживешь.', 'Отправляйтесь в Мельницу Таррен в предгорьях Хилсбрада и доставьте образчик смеси Занзила Сержу Хинотту.Сядьте на дирижабль, идущий до Подгорода, и летите вдоль дороги на юг, через Серебряный бор в сторону Хилсбрада. Следите за знаками.', 'О, $C, какой ты бледненький! А чем это от тебя так мерзко благоухает? Я должен выяснить!', 'Это что такое???', NULL, NULL, 'Образец видоизмененной смеси Занзила (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2480, 'Помощь Хинотта', 'Никогда не видел таких отличных результатов действия яда! Занзил, говоришь? Не слыхал о таком... Однако пора уже приступать к созданию состава.$B$BИтак, я должен вылечить тебя и научить пользоваться этим ядом?$B$BДай мне пару минут на изучение токсина, $N.', 'Дождитесь, пока Серж Хинотт доделает лекарство.', 'Лекарство готово! Выпей это противоядие, и наступление безумия остановится. Впрочем, с запахом ничего не поделаешь.', NULL, NULL, NULL, 'Лекарство готово', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2498, 'Возвращение к Деналану', 'Я только что получил известие, что Деналан с озера Аль\'Амет узнал, что могло послужить причиной возникновения опухоли, поражающей древесников. Пожалуйста, поговори с ним и скажи, что тебя прислал я.$B$BТоропись, $N, ему нужна наша помощь.', 'Релиан Зеленый Костер хочет, чтобы вы поговорили с Деналаном у озера Аль\'Амет.', 'Ах, так, значит, Релиан послал тебя мне в помощь. Хорошо, что ты так скоро пришел.$B$BЯ обнаружил нечто чрезвычайно тревожное!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2499, 'Дубохмур', 'В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль\'Амет – дом родной.$B$BЯ не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражен опухолью, какой я в жизни не видывал... Она просто гигантская!$B$B$N, ты и так уже достаточно $gпомог:помогла: мне в моих трудах, но я попрошу тебя еще об одной услуге. Найди Дубохмура и сними эту опухоль. Избавь мою землю от источника порчи!', 'Деналан с озера Аль\'Амет хочет, чтобы вы сняли гигантскую опухоль с Дубохмура.', 'Я так и знал, что ты сумеешь избавить озеро от этой чудовищной твари.$B$BПечальная история – Дубохмур некогда был великим вождем своих сородичей... но порча поражает всех подряд – и подлых, и благородных.$B$BВеличина этой опухоли в дрожь бросает, но я обязан исследовать ее, чтобы понять, какая зараза терзает древесников.$B$BПрими мою благодарность, $N.', 'Тебе удалось найти Дубохмура, $C?', NULL, NULL, 'Гигантская опухоль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2500, 'Пробежка по Бесплодным землям', '$C, я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реагенты, которые можно отыскать в Бесплодных землях.$B$BВот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не $gлюбитель:любительница: сражений, можешь попросить о помощи друзей.$B$BЯ неплохо заплачу, если ты принесешь мне все необходимое.$B$BЧто скажешь?', 'Добудьте в Бесплодных землях реагенты для Гхака Целителя и отнесите их ему в Телcамар.', 'Молодец, $N. Этого мне должно хватить на некоторое время. Вот обещанная плата.$B$BЕсли ты не против получить новое задание, мне нужны еще кое-какие реактивы. Некоторые из них можно найти только на ульдаманском раскопе. Добыть их нелегко, но и плата за помощь будет немалая.$B$BМожет быть, кое-что получше блестящих монет!', 'Ты принес все необходимое? Пока не принесешь, платить не буду.', NULL, NULL, 'Второй желудок канюка', 'Клык скального койота', 'Осколок каменного элементаля', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2501, 'Пробежка по Бесплодным землям-2', 'Ты не раз меня $gвыручал:выручала:, $N. Я хотел бы дать тебе в награду рецепт зелья, которое ты уже $gпробовал:пробовала:, но взамен попрошу выполнить опасное поручение.$B$BВ этом сейфе находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опаленного дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне.$B$BДобудь мне кровь дракона, и я отдам тебе рецепт.', 'Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Гхаку Целителю в Телcамар.', 'Между нами, алхимиками, говоря, ты просто герой! Вот, возьми этот рецепт. Пусть он принесет тебе успех и богатство, как и мне!', 'Ты уже наполнил сосуды кровью опаленных драконов-стражей? Знаю, задание опасное... но в случае успеха тебя ждет рецепт восстановительного эликсира. Игра стоит свеч, мой друг... игра стоит свеч...', NULL, NULL, 'Сосуд драконьей крови', 'Сейф с волшебными сосудами', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2518, 'Слезы Луны', 'Некогда леди Сатра была дорога Элуне. Эта изящная и чистая душой паучиха ткала серебряные свои нити под светом луны, ловя в свои сети вечерний туман. Его серебристые капли обладали великой целительной силой, их хранили в этом храме.$B$BНо недавно Сатру постигло безумие. Теперь и ее потомство под угрозой.$B$BНайди леди Сатру, $N, и положи конец ее страданиям. Она обитает у северных границ Тельдрассила, близ Родникового озера. Возьми ее серебристые паутинные железы и принеси их мне.', 'Жрица А\'моора из дарнасского храма Луны хочет, чтобы вы принесли ей серебряные паутинные железы леди Сатры.', 'Лес оплакивает леди Сатру, но это надо было сделать.$B$BБлагодарю тебя, $N.', 'В великой печали даю я тебе это поручение, но у нас нет надежды исцелить леди Сатру.$B$BМы надеемся, что если принести серебряные паутинные железы в жертву Элуне, то она благословит Сатру, и та возродится с покоем в душе.', NULL, NULL, 'Серебристые паутинные железы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2519, 'Храм Луны', 'Одному некогда великому существу из нашего леса нужна помощь, $r. $B$BЭто трудное дело, но его надо сделать.$B$BПожалуйста, разыщи нашу жрицу А\'мууру, она все тебе объяснит. Ищи ее к юго-востоку отсюда, в Храме Луны.', 'Сестра Аквинна хочет, чтобы вы поговорили со жрицей А\'муурой из Храма Луны.', 'Стало быть, тебя прислала сестра Аквинна?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2520, 'Жертвоприношение Сатры', 'Теперь ты $gдолжен:должна: закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны. Пусть великая паучиха обретет покой.$B$BВнутри этого храма ты найдешь центральный фонтан. Там ты оставишь жертвоприношение. Святые воды смоют порчу, что повергла Сатру в безумие.$B$BКогда закончишь дело, возвращайся ко мне.', 'Жрица А\'муура просит вас положить серебристые паутинные железы леди Сатры у фонтана в храме и затем вернуться к ней.', 'Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновленным духом.$B$BДа примет Элуна ту жертву, что ты принес ей.', NULL, NULL, NULL, 'Совершите жертвоприношение у источника', 'Жертвоприношение Сатры', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2521, 'Служба для Кум\'иша', '$gраса:, может ли твой ничтожный мозг понять уникальность безупречной сферы из дренетиста? Некоторые дренеи тратили всю свою жизнь на поиски одного-единственного кристалла – и все лишь для того, чтобы встретиться с ужасной судьбой, не достигнув своей цели.$B$BИ вот ты стоишь перед Кум\'ишей, знаешь, что требуется Кум\'ише. Ты все еще желаешь помочь? Отлично, $r... Если ты в какой-нибудь момент своего путешествия через эти земли найдешь безупречную сферу из дренетиста, верни ее мне и я вознагражу тебя так, как тебе не грезилось в самых безумных мечтаниях.', 'Если в своем путешествии по Выжженным землям вы найдете безупречную сферу из дренетиста, отнесите ее Кум\'ише Коллекционеру. Будьте внимательны – этот камень – один из самых редких кристаллов во всем Азероте. Любое существо в этих землях может владеть безупречной сферой из дренетиста. Вы будете вознаграждены за каждую безупречную сферу из дренетиста, которую доставите Кум-ише.', 'Не обманывают ли меня глаза? Невозможно! Откуда... Каким образом...$B$BБыть может, теперь откроется разлом и мы сможем вернуться на родину.', 'Я посвятил свою жизнь поискам безупречной сферы из дренейского аметиста. Всю жизнь, $C!', NULL, NULL, 'Безупречная сфера из дренетиста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2522, 'Попытки Кум\'иша', 'Хотя заклинание портала ни к чему не привело, я по-прежнему надеюсь, что моя следующая попытка будет успешной.$B$BНадежда дренеев столь же сильна, как твоя жадность до безделушек, $r. Возвращайся в те проклятые земли и найди еще одну безупречную сферу из дренетиста.$B$BНу конечно же, брать или не брать на себя эту задачу – выбираешь только ты *усмешка*.', 'Найдите безупречную сферу из дренетиста и верните ее Кум\'ише Коллекционеру.', 'Просто поразительно. Я сомневался, что тебе удастся найти еще одну сферу, но вот она – пульсирует у меня в ладонях.$B$BОтлично сделано, $N!$B$BЕсли найдешь еще – а я верю, что это возможно – то принеси мне, и я вознагражу тебя.', 'Удалось ли тебе найти еще одну безупречную сферу из дренетиста?', NULL, NULL, 'Безупречная сфера из дренетиста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2523, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2541, 'Спящий друид', 'Шаман племени Кривой Сосны, который живет в этих местах, нашел способ разлучать дух спящего друида с физическим телом. Этот фурболг оживил мое тело и заставил его нападать на любого, кто пытается обследовать обитель Бен\'этиль. Теперь мне не выйти из Изумрудного Сна, и я не могу прекратить это!$B$BПомоги мне! У шамана Кривой Сосны есть при себе странный оберег, который он использует во время ритуала, и я хотел бы исследовать его. Прошу тебя, $N, принеси его мне!', 'Принесите шаманский оберег вуду Обену Яростному Когтю в обитель Бен\'этиль.', 'Прими мою благодарность, $N.$B$BКакая странная вещица... Я чувствую злую ауру, которую она излучает. Очень мощное заклятие...', 'Если бы я смог осмотреть этот оберег, я смог бы понять суть чар. Удалось тебе его найти?', NULL, NULL, 'Шаманский оберег вуду', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2561, 'Друид-медведь', 'Изучив этот оберег, $N, я понял, что надо сделать. Пожалуйста, возьми его и сделай, как я прошу.$B$BТебе придется собраться с духом и проникнуть в самые глухие закоулки обители Бен\'этиль. Там ты найдешь мое лишенное души тело... Хотя я и скорблю о том, что мне сейчас придется поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны.$B$BЧтобы я мог сбежать от них, ты должен уничтожить мое физическое тело. Как только это будет сделано, обрати на мой труп силу амулета вуду. После этого возвращайся ко мне.', 'Обен Яростный Коготь просит, чтобы вы уничтожили его лишенное души тело, а затем воспользовались оберегом вуду.', 'Наконец-то я свободен от власти племени Кривой Сосны! Спасибо тебе, $N.$B$BОтныне мой дух обретет вечный покой в объятиях Изумрудного Сна.$B$BВозможно, однажды мы снова встретимся, юный $C. Но пока прими эту награду в знак моей благодарности.', '$N, будь осторожен с моим телом: на него наложены могучие чары.', NULL, NULL, 'Освободите душу Обена Яростного Когтя.', 'Оберег вуду', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2581, 'Челюсти гиены-хохотуна', 'Хорошо известно, что челюсти гиены невероятно сильны, но чтобы они были способны прокусить три дюйма ториевой стали? Невозможно, невероятно, и тем не менее я видел это своими глазами.$B$BОтправляйся в Выжженные земли и принеси мне три челюсти гиены-ухмыльника. А пока ищешь гиен, высматривай также кабанов и скорпоков: для дополнения к изначальной эссенции требуется также два обожженных легких вепря и одна клешня скорпока.', 'Принесите три челюсти гиены, два обожженных легких вепря и клешню скорпока магу крови Дразиалу.', 'Как самочувствие, $N? Ты излучаешь ауру гиены-ухмыльника – силу, с которой никто из смертных не сравнится!$B$BК несчастью, из принесенных тобой компонентов я смогу сделать эссенции только на одну таблетку. Если тебе понадобится еще одна таблетка, мне нужно будет больше компонентов.', 'Отвратительно пахнешь, $N. Что серные поля – такое милое место для прогулки? И где мои компоненты?', NULL, NULL, 'Челюсть голодного хохотуна', 'Обожженные легкие вепря', 'Клешня скорпока', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2582, 'Ярость веков', 'О, $N, добро пожаловать, давно не виделись. Похоже, тебе понравился эффект крепкого, действенного зелья, извлеченного из гиены-ухмыльника. Однако осторожнее: если непосредственным эффектом является титанический прилив сил, то долгосрочный эффект, сказывающийся на твоем духе и рассудке, может быть опасным. $B$BКстати говоря, тебе нужно еще зелья? Тогда принеси мне еще три челюсти гиены, два обожженных легких вепря и одну клешню скорпока.', 'Принесите три челюсти гиены, два обожженных легких вепря и клешню скорпока магу крови Дразиалу.', 'Вот, возьми! И помни, что использовать это зелье надо расчетливо. Если понадобится еще, приходи ко мне после того, как израсходуешь порцию, которую я тебе только что выдал.', 'Тебе удалось добыть органы этих тварей?', NULL, NULL, 'Челюсть голодного хохотуна', 'Обожженные легкие вепря', 'Клешня скорпока', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2583, 'Жизненная сила вепря', 'В этих опаленных землях водятся два вида кабанов: углегривый кабан и зловепрь.$B$BСудя по всему, стойкость этих тварей такова, что делает их почти неуязвимыми, поскольку другие животные считают, что вепрей слишком трудно убить, следовательно, на них не стоит даже тратить усилий.$B$BНам нужно провести дальнейшие исследования, $N. Если ты принесешь мне три обожженных легких вепря, две клешни скорпока и мозг василиска, я создам отличный эликсир на основе вытяжки из этого материала. И первым делом проверю на тебе!', 'Принесите три обожженных легких вепря, две клешни скорпока и мозг василиска магу крови Дразиалу.', 'Дух вепря озаряет твое существование, $N! Может быть, ты веришь, что тебе дарована неуязвимость, как и этим тварям?', 'Так где органы, $N!?', NULL, NULL, 'Обожженные легкие вепря', 'Клешня скорпока', 'Мозг василиска', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2584, 'Дух вепря', 'Когда я впервые выдал тебе этот эликсир, $N, я уже понимал, что одна-две порции не удовлетворят твой аппетит. Даже сейчас я вижу в твоих глазах этот голод. Сей состав имеет одно побочное свойство – он дает привыкание, которому, похоже, не может сопротивляться даже самая сильная воля.$B$BЧто ж, пусть так! Если тебе требуется еще порция смеси с легочной вытяжкой, отправляйся обратно в пустоши и принеси мне три обожженных легких вепря, две клешни скорпока и мозг василиска.', 'Принесите три обожженных легких вепря, две клешни скорпока и мозг василиска магу крови Дразиалу.', 'Хочу предупредить тебя, $N, не пытайся смешивать созданные мною составы. Химические свойства состава, недавно принятого тобою, всегда возобладают над предшествующими заклинаниями; таким образом, эффект другого зелья будет сведен на нет.', 'Так где органы, $N!?', NULL, NULL, 'Обожженные легкие вепря', 'Клешня скорпока', 'Мозг василиска', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2585, 'Решительный удар', 'Тебе приходилось видеть их сражение, $N? Я имею в виду скорпоков. Видеть грациозность и ловкость, с которой они движутся? Решительность, с которой они наносят удары?$B$BЕсли бы мы только могли выделить эту ловкость и заключить ее в оболочку, мы были бы богаты вне всякого... я хочу сказать... это было бы благо для всего научного соообщества. $B$BПомоги мне, $N, и я выделю для тебя порцию настойки.$B$BДля того чтобы создать стабильное вещество, мне потребуется три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря.', 'Принесите три клешни скорпока, две порции потрохов стервятника и обожженное легкое вепря магу крови Дразиалу.', 'Потрясающе. Анализ этой эссенции был самым сложным. $B$BВозьми щепотку этой солевой вытяжки и положи ее под язык. Ты испытаешь легкое чувство эйфории, после которого наступит состояние невероятной ловкости и быстроты.', 'Так где органы, $N!?', NULL, NULL, 'Клешня скорпока', 'Потроха стервятника', 'Обожженные легкие вепря', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2586, 'Скорпоковая соль', 'Ты $gжив:жива:! Это поистине хорошая новость! Полагаю, тебе нужно еще скорпоковой настойки?$B$BОтлично, $N, тогда снова ступай в пустоши и не возвращайся, пока не заполучишь три клешни скорпока, две порции потрохов стервятника и обожженное легкое вепря.', 'Принесите три клешни скорпока, две порции потрохов стервятника и обожженное легкое вепря магу крови Дразиалу.', 'Отличная работа, $N. Вот одна мера настойки для тебя, а оставшиеся девять будут использованы для моих исследований. $B$BВ любой момент, когда тебе понадобится скорпоковая настойка, возвращайся ко мне, и мы заключим сделку.', 'Так где органы, $N!?', NULL, NULL, 'Клешня скорпока', 'Потроха стервятника', 'Обожженные легкие вепря', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2601, 'Укус василиска', 'Эти пустоши кишат василисками Красного камня, $N. Эти василиски отлично приспособились к местным условиям, их тут больше, чем любых других диких животных. $B$BЯ наблюдала издали, как они охотятся и ведут свою повседневную жизнь – мыслительный процесс у этих тварей, похоже, куда более сложный, чем у некоторых из тех существ, которых мы называем разумными.$B$BЯ должна изучить их мозги!$B$BРаздобудь для меня десять их мозгов, $N. Однако для опытов мне понадобятся еще потроха двух стервятников, которые дадут основу для раствора.', 'Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре.', 'Замечательно, $N! Предлагаю тебе отведать на вкус внутреннюю суть василисков красного камня.$B$BЕсли этот состав тебе понравится, всегда можно сделать еще... за определенную плату.', 'Удалось ли тебе добыть нужные органы?', NULL, NULL, 'Мозг василиска', 'Потроха стервятника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2602, 'Непогрешимый разум', 'Твое сосредоточение ушло так скоро? Нужно провести еще больше исследований!$B$BАх да, $N, цена остается прежней. Отправляйся в Выжженные земли и возвращайся ко мне с десятью мозгами тварей Красного Камня и потрохами двух стервятников.', 'Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре.', 'Да, да, $N, дай мне минутку, и нужные тебе составы будут готовы к употреблению.$B$BВот, возьми... и помни, $N, что нельзя даже пытаться употреблятьь эти экспериментальные составы слишком часто. Результат будет катастрофическим.', 'Удалось ли тебе добыть нужные органы?', NULL, NULL, 'Мозг василиска', 'Потроха стервятника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2603, 'Стойкость стервятника', 'В этих опаленных землях смерть воистину крылата, $r.Я много раз наблюдала, как черные убийцы и костеглоды пируют на телах павших исследователей – иногда пожирая наиболее отвратительные и разложившиеся останки трупов. Удивительно все же, как их внутренние органы справляются с заразой, царящей в этих землях?$B$BПомоги мне в моих исследованиях, $N! Мне нужны потроха! Понадобятся также две челюсти гиены в качестве основы для состава.$B$BТвои усилия будут вознаграждены вдвойне.', 'Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре.', 'Превосходно! Я немедленно приступаю к работе. Возможно, удастся найти лекарство от множества недугов, существующих в этом мире!$B$BАх да, твоя награда – конечно, если тебе опять понадобится зелье, возвращайся ко мне, я дам тебе новое поручение.', 'Не трать зря мое время, $N. Нам нечего обсуждать, пока ты не принесешь то, что мне требуется.', NULL, NULL, 'Потроха стервятника', 'Челюсть голодного хохотуна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2604, 'Духовное превосходство', 'Я вижу, внутреннее пламя угасло. Как по-твоему, длилась ли эта духовная эйфория хотя бы час?$B$BЕсли ты желаешь получить еще зелья из потрошков, то изволь снабдить меня сырьем! Отправляйся обратно, $N. И не возвращайся, пока не наберешь десять мер потрохов и две челюсти.', 'Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре.', 'Возможно, когда-нибудь я смогу выделить активные компоненты этой эссенции и получить куда более эффективный результат. К несчастью, пока тебе придется довольствоваться тем, что я в состоянии сделать на настоящий момент. Если понадобится еще зелье из потрошков, возвращайся ко мне.', 'Не трать зря мое время, $N. Нам нечего обсуждать, пока ты не принесешь то, что мне требуется.', NULL, NULL, 'Потроха стервятника', 'Челюсть голодного хохотуна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2605, 'Жаждущий гоблин', 'Слышь, у меня возникла мысль. Я слышал о странных тварях, собирателях росы, живущих на юго-западе... Говорят, они хранят воду в особых железах.$B$BМне кажется, что из этих желез я бы сделал напиток, который утолил бы мою жажду! Ты не поможешь мне, $N?$B$BПоищи кактусовый сад, $N, именно там пасутся собиратели росы.', 'Добудьте насыщенную влагой железу и принесите ее Синю Гогельмогелю в Прибамбасск.', 'Чудесно! Дай мне железу – я хочу выпить ее!', 'Прошу, скажи мне, что ты нашел собирателей росы!', NULL, NULL, 'Насыщенная влагой железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2606, 'Хороший вкус', 'Фу! Ну и гадость! Да, идея была неудачная…$B$BСтой, что такое? О, знаю, ты считаешь, что не стоит отказываться от этой штуки. Ладно.$B$BЭээ... У меня есть идея! Гениально! Отнеси эту росу моей подруге Поливалке – она отличный повар. Скажи, что мы тут задумали, пусть придумает, как улучшить вкус.$B$BЯ хочу сказать, что такая дрянь по крайней мере, должна пробирать до мозга костей... А пока ей до мозга далеко...', 'Поговорите с Поливалкой в Прибамбасске по поручению Синя Гогельмогеля.', 'Синь отличный парень, не пойми меня превратно – только немного... эксцентричный, что ли.$B$BИ разумеется, ему опять нужна моя помощь.', 'Значит, старый Синь опять за свое? Из чего сделан этот состав?', NULL, NULL, 'Кактусовая роса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2607, 'Прикосновение Занзила', 'Похоже, что информации у вас даже больше, чем я ожидал. Как-то странно все оборачивается, $N.$B$BЛекарство? Хм-м... Спуститесь в подвал и поговорите с Доком Миксиль-Пиксилем – он, вероятно, сможет помочь.', 'Поговорите с Доком Миксиль-Пиксилем в подвале казарм.', 'Как раз вовремя! Просто положите сыр на стол и проваливайте. Осборн заплатит вам на выходе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2608, 'Прикосновение Занзила', 'Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите еще хуже. Вы, $gсударь:сударыня:, будете предсмертной отрыжкой самой смерти.$B$BХа! Слышал, Нетронь? Запиши-ка это!$B$B*Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые... раз пятьдесят или около того... Ложитесь, и приступим к лечению, $N!', 'Лягте на землю (действие :lay) для осмотра Доком Миксиль-Пиксилем – он не сможет подобрать лекарство, пока не найдет причину болезни.', 'Позвольте, я минутку посовещаюсь со своими коллегами, $N. Доктор Монтгомери, мистер Ноарм, все на консилиум!', NULL, NULL, NULL, 'Позвольте врачу поставить диагноз.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2609, 'Прикосновение Занзила', 'Однозначно, $N. У вас чтотит.$B$BК счастью, от чтотита у меня есть средство.$B$BИ вот что мне понадобится для его изготовления: букетик простых полевых цветов, одна освинцованная колба, одна бронзовая трубка и последнее – но немаловажное! – нитка светлого зеленовато-желтого шелка. Старушка Эмма оставила для меня катушку таких ниток в \"Тончайшей пряже\". Эту лавку можно найти, если идти вдоль каналов.$B$BА теперь поспешите, $N, и постарайтесь ни к кому не прикасаться, пока вас не вылечат. Кстати, доктор Монтгомери сказал, что вам нужно душ принять... это его слова, не мои!', 'Принесите Доку Миксиль-Пиксилю один букетик простых полевых цветов, одну освинцованную колбу, одну бронзовую трубку и одну катушку светлого зеленовато-желтого шелка. Чтотит, знаете ли, сам собой не проходит.', 'Что я делаю? А на что похоже то, что я делаю? Я продумываю, как вылечить ваш чтотит! И нечего так возмущенно на меня смотреть, $N! Еще несколько секунд... Готово! Побрызгайте на себя этим лечебным средством с... эээ... необыкновенным запахом – и вы в полном порядке!', 'Если хотите вылечить свой чтотит, придется приложить побольше усилий, $N. Где компоненты исцеляющего средства?', NULL, NULL, 'Скромные полевые цветы', 'Освинцованная колба', 'Бронзовая труба', 'Катушка светло-оливковых шелковых ниток');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2621, 'Опозоренный', 'Сожалею. Это все, что у меня есть. Одно неверное решение, приведшее к массе плохих последствий. Если бы я только дождался тех приказов! Может быть, там было бы сказано подробно обо всех ужасах, ожидающих нас в этих проклятых землях? Может быть, нам дали бы другое задание или выслали бы подкрепление? Но в конечном итоге, это моя вина. Все это – моя вина. $B$BИ вот я стою здесь, ожидая приказов. Я должен знать. Я должен знать, каковы эти приказы. $B$BКомандир-посланник Руаг находится в Каменоре. Найди его и узнай, что стало с приказами.', 'Поговорите с командиром разведотряда Руагом в Каменоре, что в Болоте Печали.', 'Хватка Тралла... Эта история все еще свежа в моей памяти.$B$B*Командир Руаг качает головой.*$B$BУжасная вещь – то, что случилось с этим подразделением. Орда потеряла немало своих лучших солдат, когда этот батальон был уничтожен.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2622, 'Пропавшие приказы', 'Приказы? Зачем тебе понадобились эти приказы?$B$BЧто ты подразумеваешь, $N? Конечно, я передал эти приказы! Солдаты, с которыми я их послал, попали в засаду и были безжалостно забиты до смерти мурлоками. Выжил только один – если это называется выжить. Он едва может говорить, не может ходить, его приходится кормить через трубку. Если хочешь знать, что случилось с приказами, поговори с Бенгором. Я знаю, он где-то неподалеку... и вот еще что, $N, следи, куда суешь свой нос – его ведь и откусить могут.', 'Поговорите с Бенгором в Каменоре, что в Болоте Печали.', 'Болот... ный... гово... говорун...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2623, 'Болотный говорун', 'Приказы были отданы командиром-посланником. Мы приняли... приняли приказы. На пути в Выжженные земли – засада.$B$BМурлоки... много мурлоков... Одного звали Болотный Говорун. Вырвал приказы у меня из рук, ударил копьем мне в голову. Восток... пещера...$B$B*Бенгор теряет сознание.*', 'Заберите приказы вождя и верните их павшему герою Орды.', 'Это хуже, чем я ожидал. Девятнадцать моихх соратников были бы избавлены от мучений, которым они подвергаются. Если бы я только действовал не столь неразумно!$B$BПомоги им, $N! Я бессилен что-либо сделать.', 'Ожидаю приказов.', NULL, NULL, 'Приказы военного вождя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2641, 'Маленький секрет Поливалки', 'Когда я была маленькая, у нас в семье готовила моя сестра. Это было ужасно! Половину ее творений я даже в рот взять не могла... пока не отыскала свой \"маленький секрет\"! Добавь его в любую еду и... получится вкуснятина!$B$BЧто за секрет, спросишь ты. Это гриб, называемый фиалковый траган. Если хочешь помочь мне превратить эту дрянь во что-то съедобное, отправляйся во Внутренние земли и поищи там маленькое озерцо.$B$BИ не забывай, фиалковый траган растет только под водой.', 'Найдите фиалковый траган и вернитесь к Поливалке в Прибамбасск.', 'Ага, вот и он!$B$BОтлично выглядит, хоть сейчас... Ха-ха, шучу!', 'Фиалковый траган можно найти только в озере, под водой. Надеюсь, ты умеешь задерживать дыхание!', NULL, NULL, 'Фиалковый траган', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2661, 'Посылка для Синя', 'Вот фиалковый порошок, $N. Отнеси его Синю и скажи ему, что он мой должник!', 'Отнесите фиалковый порошок Синю Гогельмогелю в Прибамбасск.', 'Фиалковый порошок, значит? Дай-ка попробую – хуже все равно не будет, это ясно!', 'А, вот и ты, $N. Что ты мне принес?', NULL, NULL, 'Фиалковый порошок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2662, 'Эликсир Ноггенфоггера', 'А теперь вмешаем этот порошок в росу.$B$BЗаходи через пару минут... когда я доведу до совершенства великолепный эликсир Гогельмогеля!', 'Синь Гогельмогель хочет поговорить с вами после завершения работы над эликсиром.', 'Попробуй! Невероятно вкусно!!!$B$BЯ знал, что у меня все получится... Еще раз спасибо за помощь, $N, только встань в сторонке! Ты не даешь прохода будущим покупателям. Я заработаю миллионы на неподражаемом эликсире Гогельмогеля, миллионы!$B$BЧто такое? Поливалка говорит, что я ее должник? Ох, такая шутница эта Поливалка!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2681, 'Камни, что связывают нас', 'Одних лишь твоих сил не хватит, чтобы одолеть Разелиха и его приспешников.$B$BСобери подходящую группу искателей приключений и освободи моих подчиненных от вечных мук! Тебе нужно разбить восемнадцать камней.$B$BСражайся отважно и умри с честью, $N.', 'Освободите девять слуг Разелиха, трех слуг Севины, трех слуг Аллистария и трех слуг Грола. Когда ваша задача будет выполнена, возвращайтесь к павшему герою. Вы должны оставаться поблизости от камней, иначе процесс не будет завершен.', 'Тебе это удалось, $N! Несчастные, истерзанные души наконец-то обретут покой.$B$BНо наша работа еще не завершена, $N. Нам еще многое нужно обсудить и еще больше сделать.', 'Это нелегкая задача, $N. Не сдавайся!', NULL, NULL, 'Освобождено слуг Разелиха', 'Освобождено слуг Гролла', 'Освобождено слуг Аллистария', 'Освобождено слуг Севины');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2701, 'Герои древних времен', 'Пожалуйста, забери отсюда реликвию древности. Мы больше ни на что не можем использовать ее.$B$BМожет быть, она послужит тебе в борьбе против Легиона.', 'Откройте шкатулку и возьмите награду.', 'Искристый блеск на какое-то время ослепляет вас.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2702, 'Герои древних времен', 'Твои благородство и героизм – высокая честь для меня, $N.$B$BИ для тебя – не менее высокая...', 'Поговорите с капралом Тундом Треснувшим Копытом.', 'Поистине, ты оказываешь честь нам всем. Одних лишь благодарностей будет недостаточно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2721, 'Кирит', 'Как только завершается одна часть твоих приключений, $N, начинается другая.$B$BОдин из моих подчиненных пропал без вести – затерялся где-то в Выжженных землях. Я, конечно же, говорю о лейтенанте Кирите. $B$BКак я упоминал ранее, мы оба были в плену у Аллистария и подвергались мучениям, но увы несчастному Кириту – его сила воли оказалась недостаточно велика. Из своей клетки я слышал происходящее: крики боли разносились по пещерным залам. С тех пор Кирита и след простыл.', 'Узнайте, что стало с лейтенантом Киритом.', 'Требор? Тебя послал Требор?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2741, 'Супер Яйц-О-Матик', '', '', 'Вы кладете в машину яйцо гиппогрифа. Раздается несколько гудков и странный механический шум.$B$BПохоже, яйцеметр взвесил, измерил и упаковал ваше яйцо. Вот это называется быстрое обслуживание!', NULL, NULL, NULL, 'Яйцо гиппогрифа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2742, 'Рин\'джи в ловушке', 'Эй, $r!$B$BРин\'джи потерял топор, и его схватили! Пожалуйста, помоги Рин\'джи сбежать. Я знаю, что не $gкаждый:каждая $r любит троллей, но я тебя очень прошу! Мне надо выйти отсюда!$B$BУ меня кое-что есть, и очень хорошее, если поможешь мне, я тебе это подарю...$B$BРин\'джи спрятал свой секрет у Отвесных скал.', 'Выведите Рин\'джи из Сторожки Кель\'Данил, а потом найдите то, что он спрятал в Отвесных скалах, на востоке.', 'Эта табличка, наверное, и есть тот самый \"секрет\", о котором говорил Рин\'джи.$B$BОна покрыта странными письменами, которые вам совершенно не знакомы.', NULL, NULL, NULL, 'Проводить Рин\'джи в безопасное место.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2743, 'Покров Тьмы', 'Не будем тратить слов, $r; мое время здесь ограничено.$B$BТебе следует уничтожить троицу силы, связанную с повелителем демонов Разелихом. Это деяние не настолько просто, как задача по освобождению проклятой души.$B$B<Кирит ухмыляется.>$B$BВидишь ли, каждый из прислужников Разелиха носит на шее треть амулета, при помощи которого был создан Разелих. Тот же самый амулет понадобится тебе для призвания сего архидемона.$B$BВозвращайся к Требору и поведай ему, что требуется для призвания Разелиха. Он подскажет тебе, что делать дальше.', 'Вернитесь к павшему герою Орды со своими находками.', 'Повелитель демонов проявляет хитрость почти столь же расчетливую, как и его жестокость, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2744, 'Охотник на демонов', 'Эта троица находится под покровительством Разелиха.$B$BВ обмен на их службу Разелих даровал каждому из них почти безграничную власть над Выжженными землями. Кусочки амулета связаны с жизненной силой их владельцев и дают им бессмертие. Пока они остаются в Выжженных землях, их нельзя убить и их жизнь продлится до конца мира.$B$BНо есть некто, способный оказать тебе помощь в дальнейшем, $N. Отправляйся в Азшару и найди там охотника на демонов, Лорамуса Многонога. Поиск следует вести на островах.', 'Поговорите в Азшаре с Лорамусом Многоногом. ', 'Я помогу тебе. Однако мне кажется, что ты не совсем понимаешь, против чего сражаешься.', 'Что ты здесь делаешь?', NULL, NULL, 'Поговорите с Лорамусом.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2745, 'Проникновение в крепость', 'Хм-м, интересная история, причем не из тех, на которые можно наплевать. Да, помочь-то я вам могу, но то, что вам нужно будет сделать, это свершить правосудие... частично незаконным путем, если уж вы хотите довести дело до конца.$B$BС Лесковаром и Марзоном нужно разобраться – и быстро. Как думаете, вы на это способны?$B$BРешать вам. Если да, то поскорее отправляйтесь в крепость и найдите там моего старинного друга – гнома по имени Тирион. Он уже пару недель как наблюдает за Лесковаром. Он сможет помочь вам покончить с этим делом.', 'Поговорите с Тирионом в крепости Штормграда. ', 'Какого?! Не подкрадывайтесь ко мне вот так! И говорите тише! На кой вы, спрашивается, во имя Теней, так ко мне подкрадываетесь? Не видите, что ли – я занят, безмозглое вы создание!$B$BЧто вы имеете в виду, спрашивая, что я делаю? Жду открытия следующего Темного портала, а вы что подумали? Выкладывайте, с чем пришли, и валите отсюда... пока стражники не заметили, что мы тут вдвоем в кустах прячемся. Мне нужно блюсти репутацию.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2746, 'Все по порядку', 'Триас хочет поторопить события, так? Ладно, мы это сделаем, но сейчас я не готов. И, кстати, сложную часть я беру на себя, а ручки пачкать будете вы, это понятно? Отлично.$B$BЗначит, мне нужно, чтобы вы мне кое-что принесли, чтобы я смог воплотить в жизнь свой план. У меня есть мысль об отличной маскировке, при помощи которой этот робот-шпион пройдет мимо стражников.$B$BПринесите мне немного шелка и пару яблок. Где достать шелк – думайте сами, а вот подходящие яблоки есть у Клары в ее маленьком хозяйстве сразу за городской чертой.', 'Принесите Тириону в Штормград 3 отреза шелка и 2 свежих яблока Клары.', 'Это отлично подойдет, $N. Прекрасная работа.$B$BВся остальная амуниция у меня в сумке... Слава Свету, у меня есть приятель-портной, сшивший мне шелковую сумку. А то мне бы уже некуда было рассовывать свои вещи.$B$BПрежде чем мой робот-шпион отправится куда надо, давайте обговорим детали, чтобы вы знали, что вам нужно будет делать.', 'Я наблюдаю за Лесковаром вот уже две недели. Триас никогда ему не доверял, но мы и не подозревали, что он втянут во что-то, связанное с Братством Справедливости. Мы отслеживали то, что могло связывать его с Сумеречным Молотом. В любом случае, он становится более опасным, чем допустимо для этого города, и тут-то мы и вступаем в дело.$B$BПринесите мне указанные предметы, и мы сможем осуществить мой план.', NULL, NULL, 'Шелковый материал', 'Свежее яблоко Клары', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2747, 'Необычное яйцо', '', '', 'Значит, ты смог добыть такое яйцо – поразительно!$B$BСегодня ты совершил настоящий подвиг!', NULL, NULL, NULL, 'Необыкновенное яйцо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2748, 'Хорошее яйцо', '', '', 'Очень хорошо, $N. Скоро я пошлю это яйцо в Дарнасс, надеюсь, из него вскоре вылупится гиппогриф!$B$BПрими это в знак моей благодарности.', NULL, NULL, NULL, 'Нормальное яйцо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2749, 'Обычное яйцо', '', '', 'Значит, ты нашел обычное яйцо? Пожалуйста, дай его мне... Будем надеяться на лучшее.$B$BПрими эту награду, это все, что у меня есть. Если снова окажешься в Фераласе, помни, что я всегда готова купить найденные тобой яйца.', NULL, NULL, NULL, 'Обычное яйцо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2750, 'Плохое яйцо', '', '', 'Боюсь, я тебя не порадую. Это яйцо уже не спасти. Я могу забрать его у тебя и поступить с ним, как должно.$B$BНе огорчайся, всех нам все равно не спасти. Если ты снова окажешься в Фераласе, попробуй еще раз. Принеси еще одно яйцо для Супер Яйц-О-Матика!', NULL, NULL, NULL, 'Испорченное яйцо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2751, 'Варварские доспехи', 'Двадцать поколений Омошей держали в руках этот молот, $N! Сколько тонн металла мы перековали! Но, увы, на мне наш род завершится. У меня нет потомства.$B$BЯ не могу допустить, чтобы тайные чертежи и приемы Омошей умерли вместе со мной!$B$BДокажи Орокку, что ты годишься в кузнецы, $N. Принеси ему 2 украшенных узором бронзовых наруча, 2 бронзовых длинных меча и 2 острых когтя. Принеси их Орокку, и мы продолжим обучение.', 'Принесите 2 украшенных узором бронзовых наруча, 2 бронзовых длинных меча и 2 острых когтя Орокку Омошу в Оргриммар.', '', NULL, NULL, NULL, 'Украшенные узором бронзовые наручи', 'Бронзовый длинный меч', 'Острый коготь', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2752, 'За железными наплечниками', 'У тебя внимательные глаза, $N. Ты вбираешь мудрость Омошей, точно губка!$B$BТри урока дам я тебе.$B$BВернись к наковальне и сделай для Орокка 4 бронзовых боевых топора и 4 бронзовых боевых молота. Лишь тогда узнаешь ты, как изготовить железное оплечье!', 'Принесите Орокку Омошу в Оргриммар 4 бронзовых боевых топора и 4 бронзовых боевых молота.', 'Орокк гордится тобой, $N. Вот, читай, как изготовить железное оплечье!', 'Продемонстрируй мне свое усердие, $R!', NULL, NULL, 'Бронзовый боевой топор', 'Бронзовый боевой молот', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2753, 'Тяжелая поступь', 'Орокк научит тебя еще двум вещам, $N. Да, я знаю, тебе тяжело, но надо продолжать – во имя Омошей!$B$BПринеси 4 зеленых железных шлема, 4 пары зеленых железных наручей и 2 пары зеленых железных поножей – и я научу тебя тому, что будет страшить твоих врагов!', 'Принесите 4 зеленых железных шлема, 4 пары зеленых железных наручей и 2 пары зеленых железных поножей Орокку Омошу в Оргриммар.', 'Ты напоминаешь Орокку его деда, Горокка Омоша! Вот, читай, учись делать железные сапоги.', 'Их черепа будут трещать под твоими сапогами!', NULL, NULL, 'Зеленый железный шлем', 'Зеленые железные наручи', 'Зеленые железные поножи', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2754, 'Рога безумия', 'Это последнее, чему научит тебя Орокк, $N. Но прежде принеси Орокку 2 прочных железных кувалды, 2 пары посеребренных бронзовых сапог и две пары посеребренных бронзовых рукавиц.$B$BТы узнаешь, как приятно видеть страх в глазах врагов при одном твоем появлении!', 'Принесите Орокку Омошу в Оргриммар 2 прочных железных кувалды, 2 пары посеребренных бронзовых сапог и 2 пары посеребренных бронзовых рукавиц.', 'Потрясающе, $N! Теперь ты знаешь все секреты Омошей!', 'Ну-ка, $N, покажи железу, кто тут главный!', NULL, NULL, 'Прочная железная кувалда', 'Посеребренные бронзовые сапоги', 'Посеребренные бронзовые рукавицы', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2755, 'Радости Омоша', 'Нет, $N, Орокк не плачет. Это сажа в глаз попала.$B$B*Орокк утирает слезу.*$B$BОстался последний секрет семьи Омошей, которому научит тебя Орокк.$B$BВыучи танец радости Омошей, и научишься ковать железный кулак!', 'Научитесь танцу Радости Омошей.', '*Орокк шумно отдувается.*$B$BДавненько Орокк не плясал танец Радости Омошей! Ну, $N, смотри и учись!', NULL, NULL, NULL, 'Выучите танец радости Омошей.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2756, 'Старые обычаи', 'В былые легендарные времена Атурк сокрушил бы черепа своих врагов и истер кости в мелкий порошок! Но эти дни давно миновали, $r. Вождь требует мира между кланами, и старых врагов мы теперь даже пальцем тронуть не смеем.$B$BДаже не верится! Но такова воля Тралла.$B$BНу, довольно жалоб! Ты здесь, чтобы учиться – и ты будешь учиться! Принеси 4 стальные кирасы и 4 стальных латных шлема, и узнаешь вкус войны!', 'Принесите 4 стальные кирасы и 4 стальных латных шлема Атурку Наковальне в Оргриммар.', '', NULL, NULL, NULL, 'Стальная кираса', 'Стальной латный шлем', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2757, 'Вперед, в Пиратскую Бухту!', 'Слышь, будешь болтаться здесь – так ничему и не научишься!$B$BВот я знаю мужика, который знает мужика, который ошивается возле кузницы в Пиратской Бухте. Покажи ему этот значок, и он тебе про мифрил все расскажет!$B$BЧего-чего? Оставь это грудным младенцам, $N, тебе пора двигаться дальше!$B$BЕсли тебя это интересует, его звать Макгеван.', 'Поговорите с Макгеваном в Пиратской Бухте.', 'Клянусь задницей Черного Копыта! Наконец хоть кто-то достойный Ордена мифрила!', 'Экий редкий зверь к нам пожаловал! Ну-ка, покажи свой значок...', NULL, NULL, 'Мифриловый знак отличия (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2758, 'Происхождение кузнечного искусства', 'Когда я был примерно в твоем возрасте, дворф по имени Гальван взял меня под свою опеку и обучил меня способам ковки доспехов. Перед своим отъездом в Пиратскую Бухту он заставил меня пообещать, что я буду до конца дней своих обучать всех, у кого будет желание и решимость овладеть кузнечным ремеслом. Так я и поступил.$B$BИтак, теперь настало твое время чему-нибудь научиться. Сделай мне шесть пар золотых чешуйчатых наручей – и узнаешь, откуда есть пошло кузнечное дело, $N.', 'Принесите 6 пар золотых чешуйчатых наручей Хэнку Молоту в Штормград.', 'Отлично, $N! Слушай и впитывай.$B$BМастерство кузнеца никогда не исходит отсюда! *Хэнк указывает на молот.*$B$BМастерство кузнеца никогда не исходит и отсюда! *Хэнк указывает на наковальню.*$B$BТолько отсюда происходит мастерство кузнеца! *Хэнк указывает себе на сердце.*$B$BТеперь ты знаешь, каково происхождение кузнечного искусства.', 'Может быть, ты станешь одним из наследников Гальвана!', NULL, NULL, 'Золотые чешуйчатые наручи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2759, 'В поисках Гальвана', 'Хотя Гальван покинул Пиратскую Бухту много лет назад, члены ордена по-прежнему остаются в городе, надеясь однажды найти кого-нибудь, достойного внимания мастера.$B$BВозьми этот знак и отдай его Макгевану в Пиратской бухте.$B$BЕсли ты действительно с этим справишься, он поймет, что ты $gдостоин:достойна:. Я в тебя верю, $N!', 'Поговорите с Макгеваном в Пиратской Бухте.', 'Клянусь гривой Черного Копыта – наконец-то появился хоть кто-то, достойный Ордена мифрила!', 'Редкая ты, должно быть, птица, дружище. Дай-ка мне глянуть на этот знак...', NULL, NULL, 'Мифриловый знак отличия (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2760, 'Орден Мифрила', 'Большинство наших новобранцев так и не добрались до Пиратской Бухты, $N. Блеска эмблемы оказывается достаточно, чтобы пробудить алчность даже в самых стойких кузнецах. Дураки, эмблема эта – капля в море по сравнению со стоимостью предметов, которые ты увидишь!$B$BНайди Гальвана Древнего и покажи ему эту булавку. Он живет далеко на севере, междук Зул-Гурубом и холмом Мош\'Огг.', 'Поговорите с Гальваном Древним в Тернистой долине.', 'А, прошло много лет, с тех пор, как я в последний раз видел достойных принятия в Орден мифрила. Начнем же!', 'Приветствую! Подойди ближе; покажи Гальвану, что у тебя.', NULL, NULL, 'Мифриловая подвеска (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2761, 'Плавим, не плавим, плавим, не плавим…', 'Многие кузнецы считают, что горное дело и кузнечное ремесло – две разные вещи; но что за кузнец без металла? Как же, это невозможно! Опытный кузнец должен быть и опытным горняком.$B$BПокажи Гальвану, на что ты $gспособен:способна:, $N. Принеси мне сорок слитков железа и сорок слитков мифрила. За это Гальван научит тебя создавать изысканные мифриловые штаны!', 'Принесите сорок мифриловых слитков и сорок железных слитков Гальвану Древнему из Тернистой долины.', 'Твои работы безупречны! Ты начинаешь понимать основы минералогии Гальвана! Возьми это и научись всему, чему сможешь.', 'Когда хорошо поработаешь, мышцы ноют и тело ломит!', NULL, NULL, 'Железный слиток', 'Мифриловый слиток', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2762, 'Обманное серебро', 'Говорят, что истинное серебро прочнее мифрила. Гальван не будет спорить с такой оценкой, но вопреки названию, истинное серебро далеко от истины! Мифрил куда благороднее! ХА! И тем не менее, на сей раз тебе придется найти это обманное серебро.$B$BПринеси мне сорок мифриловых слитков и пять слитков истинного серебра. Взамен я научу тебя искусству изготовления изысканных мифриловых перчаток, и что куда важнее, ты узнаешь, что истинному серебру веры нет.', 'Принесите сорок мифриловых слитков и пять слитков истинного серебра Гальвану Древнему из Тернистой долины.', 'Нелегко с ним справиться, а? Я об истинном серебре. Гальван потратил не меньше десяти лет в горах Альтерака, прежде чем усвоил этот урок. Возьми это и научись, чему сможешь!', 'Когда хорошо поработаешь, мышцы ноют и тело ломит!', NULL, NULL, 'Мифриловый слиток', 'Слиток истинного серебра', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2763, 'Могущество камней', 'Для нашего ремесла очень важно научиться добывать дракоценные камни. Немногие камни драгоценнее цитрина. Он во много раз усиливает ту магию, которую мы вкладываем в наши творения.$B$BНа сей раз мы усилим сорок слитков мифрила четырьмя цитринами. В результате ты получишь лучшее представление о магической гемологии и научишься создавать изысканные мифриловые наплечники.', 'Принесите сорок мифриловых слитков и 4 цитрина Гальвану Древнему из Тернистой долины.', 'Да, от такой красоты взгляда не оторвешь, $N. Цитрин – великолепный камень.$B$BА теперь смотри внимательно, вот чему можно научиться!', 'Когда хорошо поработаешь, мышцы ноют и тело ломит!', NULL, NULL, 'Мифриловый слиток', 'Цитрин', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2764, 'Лучший ученик Гальвана', 'Если ты $gготов:готова: покинуть Гальвана, отправляйся в Прибамбасск.$B$BТам живет мой лучший ученик, Трентон Молот Света. Он научит тебя обращению с изысканным мифрилом. Впрочем, можешь остаться здесь и поучиться еще!$B$BАх да, Прибамбасск находится в Танарисе!', 'Поговорите с Трентоном Молотом Света. Его можно найти в Прибамбасске, что в Танарисе.', 'Тебя прислал Гальван Древний?$B$B*Трентон кланяется*$B$BЭто большая честь – познакомиться с еще одним из его учеников!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2765, 'Кузнец-умелец!', 'Я с первого взгляда понял, что ты станешь $gодним из моих лучших учеников:одной из моих лучших учениц:! Ты без колебаний $gотдал:отдала: Макгевану вещь, наделенную силой, лишь бы только встретиться со мной. Подобная слепая вера и преданность искусству должна быть вознаграждена.$B$BТы $gстал:стала: настоящим экспертом в кузнечном деле. Насладись же наградой!', 'Получите награду у Гальвана Древнего!', 'Что ж, ты в самом деле заслужил украшение, наделенное большей силой, чем то, которым пришлось пожертвовать на пути сюда. Пользуйся на здоровье, $N.', NULL, NULL, NULL, 'Вы победитель', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2766, 'Найти ККX-22:FE!', 'Перед вами странный металлический предмет яйцевидной формы. Вы понажимали на кнопочки – и внезапно яйцо ожило и раскрылось. Очевидно, это какой-то гномский приборчик! Из механического яйца раздается искаженный разрядами голос:$B$B\"Меня зовут Карлс Пропеллерз. Мой автономный робот попал в аварию! Обнаруживший его получит награду! Прошу вас, доставьте этот маячок к роботу!$B$BЯ вычислил координаты робота – он находится в пещере рядом с Долиной Свирепого Утеса!\"', 'Отнесите аварийный маяк к автономному роботу Карлса, в пещеру рядом с Долиной Свирепого Утеса.', 'Вы помещаете яйцо... то есть аварийный маяк... внутрь цыпленка... то есть автономного робота.$B$BВнутри робота слышится гудение и жужжание. Он пытается подняться на ноги. После того как робот оживает, снова слышится голос Карлса, но на этот раз изнутри робота:$B$B\"Ну что ж, по крайней мере, OOX-22:FE работает. Однако он нуждается в серьезном ремонте! Нести его вы не сможете, он слишком тяжелый... О! У меня идея! Не согласитесь ли вы его проводить?\"', 'Вы обнаружили какие-то обломки... робота-цыпленка? Металлическое яйцо снова оживает:$B$B\"Да-да, отлично! Это действительно мой автономный робот. Однако, если верить моим сенсорам, ему потребуется мощный толчок, чтобы он мог долететь до Пиратской бухты для починки. Давайте, поместите маяк внутрь аппарата – дальнейшее маяк сделает сам!\"', NULL, NULL, 'Аварийный маяк OOX-22/FE (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2767, 'Спасти ККX-22:FE!', 'Из динамика снова слышится искаженный разрядами голос гнома:$B$B\"Мне необходимо перегнать ККX-22:FE в просторное и безопасное место, чтобы начать длительную процедуру подготовки к взлету. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, на большую дорогу! Это самое подходящее место, и там достаточно просторно, чтобы аппарату было где развернуться.$B$BПроводите робота в порт, а затем сообщите об этом мне. Я живу в Пиратской Бухте, меня зовут Карлс Пропеллерз. Конец связи!\"', 'Проводите ККX-22:FE в безопасное место, затем сообщите об этом Карлсу Пропеллерзу в Пиратской Бухте.', 'О, спаситель! Вы доставили на место OOX-22:FE! У меня просто слов нет, настолько я вам благодарен! Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок!$B$BПрошу вас, выбирайте любую из этих готовых моделей. Еще раз спасибо вам, $N! Мы с моими роботами – ваши должники!', NULL, NULL, NULL, 'Проводить ККX-22/FE в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2768, 'Изыскательский жезл', 'Сержант Блай обокрал меня! Он сказал, что он только одолжит, но он украл мой драгоценный изыскательский жезл!!! Без этого жезла как я буду знать, где бурить новые скважины под воду??$B$BНайди Блая и принеси мне мой жезл! Я слышал, что он вынудил его компашку низкопробных авантюристов идти за сокровищами в Зул\'Фаррак, – город, расположенный на западе. Держу пари, там ты его и найдешь.$B$BНадеюсь, что он уже повстречался с троллями, потому что если тебе придется драться с ним за мой жезл, то схватка выйдет нешуточная.', 'Принесите изыскательский жезл главному инженеру Чепухастеру в Прибамбасск.', 'Ты сделал это, $N. Пришлось ли тебе убить Блая? Надеюсь, ты задал ему и его прихвостням хорошую трепку!', 'Ты нашел Блая? Ты принес мой изыскательский стержень?', NULL, NULL, 'Изыскательский жезл', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2769, 'Братья Медноштиф', 'Вы еще не встречались с братьями Медноштиф? Они на Мерцающей равнине в Калимдоре гоняют на своем болиде наперегонки с гоблинами. Обычно они выигрывают, что неудивительно: гоблинские машины взрываются так часто, что едва дотягивают до финишной черты!$B$BНо братья Медноштиф все равно постоянно ищут новые способы сделать свою машину еще более скоростной, и Виззл сказал мне, что ему нужен очень редкий компонент для очередных экспериментов.$B$BПохоже, ему надо с этим помочь. Спросите его на этот счет.', 'Поговорите с Виззлом Медноштифом на Мерцающей равнине.', 'Так ты хочешь мне помочь? Отлично!$B$BМне для эксперимента нужна одна штука, и отважный $C вроде тебя добудет ее без труда!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2770, 'Газ\'рилла', 'В пустыне Танарис есть город троллей – Зул\'Фаррак, в глубине которого находится священный бассейн. Из этого бассейна тролли призывают огромное чудовище, Газ\'риллу! Злобная энергия пронизывает это чудовище насквозь, до самых кончиков его чешуи. И именно эту энергию я хочу использовать в своей машине!$B$BПринеси мне наэлектризованную чешую Газ\'риллы.$B$BНо только помни, что тролли держат способ призывания этого монстра в тайне, и просто так они с ней не расстанутся.', 'Принесите искрящую чешую Газ\'риллы Виззлу Медноштифу на Мерцающую равнину.', 'Ого, да это же чешуя! Спасибо, $N. Сейчас же начну работать с ней.$B$BТак значит, ты видел Газ\'риллу? Эта тварь и правда такая большая, как про нее говорят?', 'Вы принесли чешую? Мне не терпится извлечь из нее максимум пользы!', NULL, NULL, 'Искрящая чешуя Газ\'риллы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2771, 'Голова на плечах', 'Похоже, таков был замысел учителя. Меня он научил делать одни предметы, а тебя другие.$B$BУчитель мудр, $N! Мы обучим друг друга!$B$BНаучи меня делать мифриловые капюшоны и изысканные мифриловые наплечники, а я покажу тебе, как куется изысканный мифриловый шлем.', 'Принесите два мифриловых капюшона и изысканный мифриловый наплечник Трентону Молоту Света.', 'Великолепно! Даже я говорю, что это отличный результат. Смотри и учись, $N!', 'Ты сделал все необходимые предметы, $N?', NULL, NULL, 'Мифриловый капюшон', 'Изысканный мифриловый наплечник', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2772, 'Мир у твоих ног', 'На прошлогодних соревнованиях по кузнечному делу все зрители видели, как трусливый пес из Торговой Компании подставил мне подножку. Им и невдомек, как я умудрился выиграть соревнования: правильно, благодаря изысканным мифриловым сапогам!$B$BНа соревнованиях этого года мне понадобятся изысканные мифриловые штаны, потому что в конкурсе участвует крошшер Торговой Компании! Научи меня делать штаны, а я научу тебя делать сапоги!', 'Принесите две пары тяжелых мифриловых сапог и изысканные мифриловые штаны Трентону Молоту Света.', 'Мир будет у твоих ног, $N! Пусть все падут ниц перед твоим величием!', 'Ты сделал все необходимые предметы, $N?', NULL, NULL, 'Тяжелые мифриловые сапоги', 'Изысканные мифриловые штаны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2773, 'Мифриловый парень', 'В этих краях меня зовут Мифриловым Парнем. Я продаю изысканный мифрил искателям приключений со всего света.$B$B<Трентон переходит на шепот.>$B$BИм и невдомек, что я не умею делать изысканные мифриловые перчатки. Ш-ш-ш! Пусть это останется между нами.$B$BНаучи меня делать такие перчатки, а я взамен покажу тебе последнее, чему обучил меня Гальван: изысканную мифриловую кирасу.', 'Принесите две тяжелых мифриловых кирасы и изысканные мифриловые перчатки Трентону Молоту Света.', 'Спасибо за науку, $N. Скоро в твоих руках окажется король изысканного мифрилового доспеха.$B$BСмотри!!!', 'Ты все вещи сделал, $N?', NULL, NULL, 'Тяжелая мифриловая кираса', 'Изысканные мифриловые перчатки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2781, 'Разыскивается: Калиф Жало Скорпида', 'РАЗЫСКИВАЕТСЯ: Калиф Жало Скорпида!$B$BВодная компания Прибамбасска предлагает награду за голову Калифа Жало Скорпида, главы Скитальцев Пустыни. Он обвиняется в:$B$B1. Убийстве сотрудников Водной компании Прибамбасска!$B2. Похищении ресурсов Водной компании Прибамбасска!$B3. Захвате собственности Водной компании Прибамбасска!$B$BПринесите доказательство гибели Калифа Жало Скорпида главному инженеру Чепухастеру и получите награду!', 'Принесите голову Калифа Жало Скорпида главному инженеру Чепухастеру в Прибамбасск.', 'Наконец-то – правосудие свершилось! Ты нанес суровый удар подлым кочевникам! Жало Скорпида мертв, может быть, это отпугнет этих надоед от колодцев Прибамбасска!$B$BОт лица Водной компании Прибамбасска я вручаю тебе эту награду. Ты оказал нам большую услугу.', 'Да, $C, я официальный представитель Водной компании Прибамбасска. Чем могу быть полезен?', NULL, NULL, 'Голова Калифа Жало Скорпида', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2782, 'Секрет Рин\'джи', 'Табличка покрыта письменами троллей из племени Сухокожих. Да, секрет Рин\'джи и впрямь оказался очень загадочным.$B$BВозможно, эта табличка представляет собой немалую ценность, хотя может быть и с точностью до наоборот. Тролль из племени Сухокожих в беде мог пообещать что угодно, лишь бы его спасли...', 'Отнесите табличку Оран Змеиные Кольца в Квартал Магов Подгорода. Оран – известная ученая, изучающая троллей из племени Сухокожих, и она наверняка сумеет прочесть надписи на табличке.', 'Хм, какая необычная табличка... Где вы ее взяли, $N?', 'Хм, и что же это?', NULL, NULL, 'Секрет Рин\'джи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2783, 'Незначительные разногласия', 'Мы сражаемся не с тем врагом, $N.$B$BИстинная сила этих земель продолжает наращивать свою мощь и численность, пока мы ссоримся с орками из-за клочка выжженной земли. $B$BНеужели мы продолжим воевать в этих землях против Орды лишь для того, чтобы в один ужасный день пасть от руки Пылающего Легиона? Тогда все наши усилия будут тщетны.$B$BНадо отбросить прочь мелкие разногласия, $N, и поговорить с павшим героем Орды. Он знает правду о Выжженных землях.', 'Поговорите с павшим героем Орды на границе Выжженных земель и болот.', 'Альянс желает помочь?$B$BЯ не думал, что этот день когда-либо наступит вновь. День, когда Альянс будет сражаться плечом к плечу с Ордой против общего врага.$B$BДа будет так... мы объединимся.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2784, 'Попавший в немилость', 'Выслушай мою историю, $r.', 'Послушайте, как павший герой Орды рассказывает свою историю.', 'Будучи духом, я бессилен что-либо сделать. Помоги мне, $N. Дай мне возможность снова обрести свою честь.', 'Послушай, что я скажу.', NULL, NULL, 'Печальная история', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2801, 'Печальная история', 'Прежде чем мы продолжим, тебе следует услышать мою историю.', 'Послушайте, как павший герой Орды рассказывает свою историю.', 'Настало время действовать, $N.', 'Послушай, что я скажу, $N.', NULL, NULL, 'Горестная повесть', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2821, 'Знак качества', 'У меня принцип простой: если что делаешь, делай как можно лучше – и никаких компромиссов! А тот, кто станет говорить, будто качество не имеет значения, того гляди, продаст тебе недвижимость в Дун Мороге с видом на море!$B$BИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их в Долине Свирепого Утеса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?', 'Принесите 10 толстых шкур йети Пратту Макгруббену в Крепость Оперенной Луны.', 'Ну что, видишь, каковы эти шкуры? Надо тебе сказать, что после специальной обработки они делаются прочнее железа! Немногие про это знают, а вот я, с помощью своих особых дубильных составов, смогу делать из них вещи несравненного качества! Ну да, и все это – благодаря тебе.$B$BПожалуйста, Коэн, выбирай себе любое из моих готовых изделий.', 'Принеси десять толстых шкур йети – и получишь любое из моих изделий! А мои вещи на редкость добротные, это все знают!$B$BЕсли не знаешь, где отыскать йети, я тебе подскажу. Ищи у Забытого берега, близ Долины Свирепого Утеса.', NULL, NULL, 'Толстая шкура йети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2822, 'Знак качества', 'Я горжусь своим мастерством. Мои вещи сразу видно! А тот, кто станет говорить, будто качество не имеет значения, пожалуй, захочет убедить тебя и в том, будто земля не хранит тайн!$B$BИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их к западу отсюда, в Долине Свирепого Утеса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?', 'Принесите 10 толстых шкур йети Джангору Быстрому Страннику в Лагерь Мохаче.', 'О, отлично! Надо тебе сказать, что эти шкуры после специальной обработки делаются прочнее железа! Правда, подобрать состав для дубления не так-то просто, но все равно, я уверен, что мои вещи, изготовленные из них, будут еще лучше прежнего.$B$BЧто до тебя, $N, – ты воистину бесценный помощник! Пожалуйста, выбирай себе любое из моих готовых изделий.', 'Ну что, удалось тебе добыть десять толстых шкур йети? Мои кожаные изделия не знают себе равных, и ты получишь в уплату одно из них, только принеси шкуры.$B$BЕсли не знаешь, где отыскать йети, я тебе подскажу. Ищи к западу отсюда, у Забытого берега, близ Долины Свирепого Утеса.', NULL, NULL, 'Толстая шкура йети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2841, 'Техновойны', 'О-о, гномьи технологии! Еще пару лет назад они использовались в основном в анекдотах. Да уж, времена изменились! Теперь они выстроили такую машину, которая лучше, чем все наши крошшеры вместе взятые! Мне нужны ее чертежи, $N!$B$BУвы, эти бумаги хранятся в сейфе Анжинера Термоштепселя. А что хуже всего – код от сейфа известен только самому Термоштепселю!$B$BДелай что хочешь, $N, но добудь этот код, открой сейф и достань оттуда эти чертежи!', 'Добудьте в Гномрегане чертежи боевой машины и код от сейфа Термоштепселя в Гномрегане и принесите их Ноггу в Оргриммар.', 'Да, $N, я знал, что у тебя все получится! А вот Совик все сомневался…$B$B*Ногг прочищает горло.*$B$BНу, теперь, когда чертежи у нас в руках, разобраться в этих гномьих нововведениях – всего лишь вопрос времени. Эти изобретения очень пригодятся нам, гоблинам, для новых моделей резаков!', 'Не вижу чертежей! Они спрятаны у тебя под одеждой или ты вернулся с пустыми руками и только понапрасну меня раздражаешь?', NULL, NULL, 'Чертежи буровой установки', 'Код от сейфа Термоштепселя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2842, 'Главный инженер Скути', 'Как только Керноби сообщил нам о новой гномьей машине, мы со Скути принялись строить \"Транстелепорт-6000\" – лучший способ добраться до Гномрегана.$B$BОн уже готов, $N. Если хочешь его испытать, ступай в Пиратскую Бухту и поговори со Скути у Гнезда Крыльев Ветра. Из Кабестана туда можно добраться на лодке.$B$BНет, разумеется, ты можешь попробовать добраться до Гномрегана через горы Дун Морог, кишащие дворфами!', 'Поговорите со Скути в Пиратской Бухте.', 'Ну, разве она не красавица? Вершина гоблинских транспортных технологий! И десяти раз не взрывалась!$B$BТы не бойся, $N. Больше она не взорвется, я там все отладил. Ну, а если тебе не повезет, ты хотя бы умрешь быстро и безболезненно!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2843, 'Поехалиии!', 'Пока импульсный повторитель у тебя с собой, стоит только ступить на площадку, и перенесешься в Гномреган.$B$BМожет быть, ощущения будут необычные, но ни одно из них не останется навсегда... Теперь.$B$BЧуть не забыл самое главное – как вернуться назад. Когда ты решишь уносить ноги, поднимись на площадку транстелепорта в Гномрегане!$B$BА теперь я настрою импульсный повторитель на твой рост и вес.', 'Дождитесь, пока Скути настроит гоблинский импульсный повторитель. ', 'Готово! Когда соберешься с духом, просто ступи на площадку.', NULL, NULL, NULL, 'Гоблинский импульсный повторитель', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2844, 'Великан-опекун', 'Нет от меня никакого толку, $N! Я должен был стеречь мою маленькую подружку, Шаю, а она взяла и убежала! Я даже не знаю, как это вышло: в последний раз, как я ее видел, мы шли через развалины к северу отсюда.$B$BВсе было хорошо, а потом я поворачиваюсь, а ее нет!$B$BИ теперь я даже и не знаю, чего мне делать-то. Что мне делать, $N? Я так переживаю!$B$BСлушай, а может, ты сходишь ее поищешь? У тебя-то ноги куда резвее моих!', 'Найдите потерявшуюся ночную эльфийку.', 'Ой, как хорошо, что ты меня нашел! По правде говоря, я немножко заблудилась... Но тут очень красиво, правда?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2845, 'Шая-бродяжница', 'Не поможешь ли ты мне отыскать моего друга, Камнедробителя? Он должен был следить за мной... Но со мной иногда случается, что я ухожу, куда глаза глядят. Вокруг столько интересного, я увлекаюсь, забываю обо всем на свете, и…$B$BНо есть одна вещь, которая обязательно привлекает мое внимание.$B$BВ этом сундучке хранится колокольчик. Он мне очень дорог. Мне ужасно нравится его звон. Так что, если я вдруг куда-нибудь уйду, позвони в колокольчик, и я тотчас прибегу обратно!', 'Достаньте из сундучка колокольчик Шаи.Проводите Шаю Листогон в лагерь Камнедробителя.', 'Шо? Так говоришь, этот колокольчик помогает найти Шай, когда она убежала? Вот это да!$B$BНу, $N, раз я стольким тебе обязан, на, держи!', 'Ох, я так из-за тебя переволновался! Спасибо большое, $N, что привел Шай домой!', NULL, NULL, 'Колокольчик Шаи', 'Проводить Шаю Листогон в лагерь Камнедробителя.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2846, 'Тиара Глубин', 'Давным-давно у меня была прекрасная драгоценность – Тиара Глубин. Это была не просто красивая безделушка, она была наделена великой силой, предназначенной для тех, кто умел с ней обращаться.$B$BКогда слух о моей тиаре достиг ушей гидроманта Велраты, она решила заполучить ее и послала своих подручных выкрасть ее у меня!$B$BЯ хочу вернуть то, что принадлежит мне. Отправляйся в Зул\'Фаррак, город троллей в пустыне Танарис, найди там Велрату и забери у нее мою тиару. Возвращайся ко мне и заслужишь мою вечную благодарность.', 'Принесите Тиару Глубин Табете в Пылевых топях. ', 'Чудно! Ты нашел ее! И, что ее важнее, Велрата ее лишилась! Благодарю тебя, $N. И... Если я прежде высказывалась несколько резко, не бери в голову. К тем, кто не пытается меня обокрасть, я отношусь гораздо дружелюбнее.', 'Ты принес тиару, $N? Велрата поняла, что значит переходить мне дорогу?', NULL, NULL, 'Тиара глубин', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2847, 'Доспехи из дикой кожи', '$N, ты уже $gопытный кожевник:опытная кожевница:. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используется загадочная и непостоянная сила дикого винограда, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах.$B$BЯ научу тебя делать эти доспехи, но для этого тебе придется потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси ее, потом обсудим дальнейшее.', 'Принесите 10 кусков плотной кожи Пратту Макгруббену в Крепость Оперенной Луны.', '', NULL, NULL, NULL, 'Плотная кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2848, 'Наплечники из дикой кожи', 'Наплечники из дикой кожи обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все доспехи из дикой кожи, они прошиты дикой лозой, что придает им мощные, но непостоянные магические свойства.$B$BДля изготовления изделия по этой выкройке мне потребуется шесть накладок из толстой кожи и дикая лоза. Для тебя это не слишком сложное задание.', 'Принесите 6 накладок из толстой кожи и дикую лозу Пратту Макгруббену в крепость Оперенной Луны.', 'Да, $N, это хорошие, надежные наборы для усиления брони. Если я чего требую не только от себя, но и от своих подмастерьев, так это высокого качества!$B$BТы неплохо потрудился, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.', 'Ну что, принес ли ты шесть наборов для усиления брони их толстой кожи и дикий виноград, как я просил?$B$BИзготовление брони из толстой кожи – дело непростое и трудоемкое, но это помогает набить руку перед тем, как взяться за более сложные вещи, например, дикарские кожаные доспехи.$B$BТак что если я заставляю тебя всем этим заниматься, то не просто так...', NULL, NULL, 'Накладки из толстой кожи', 'Дикая лоза', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2849, 'Ж$N из дикой кожи', 'Ж$N – основа любых доспехов из дикой кожи. Основа ж$Nа переплетена дикой лозой, что дает максимальную защиту торса и позволяет использовать мощную магию растения.$B$BДля изготовления предмета по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикая лоза. Добыть все это непросто, но, думаю, ты справишься.', 'Принесите 2 черепашьих чешуйчатых кирасы, 2 пары черепашьих чешуйчатых перчаток и дикую лозу Пратту Макгруббену в крепость Оперенной Луны.', 'Да, $N, неплохие вещицы! За одно умение и старание, вложенное в них, можно получить несколько лишних серебряных монет.$B$BНу что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные ж$Nы!', 'Ну что, где те черепашьи чешуйчатые кирасы и перчатки, что я велел принести? И не забудь про дикий виноград!$B$BЕще работая с простейшими выкройками, мы понимаем, что сложное и простое строится по одним и тем же принципам. Таким образом, изготовление черепашьих чешуйчатых кирас подготавливает тебя к созданию дикарского кожаного ж$Nа.$B$BЧто до перчаток... ну, перчатки пригодятся мне самому! Не забывай, ты работаешь на меня!', NULL, NULL, 'Черепашья чешуйчатая кираса', 'Черепашьи чешуйчатые перчатки', 'Дикая лоза', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2850, 'Шлем из дикой кожи', 'Шлем из дикой кожи обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех доспехах из дикой кожи, в основу шлема вплетена дикая лоза, наделяющая его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!$B$BНо для изготовления изделия по этой выкройке мне понадобятся 2 ночных мундира, 2 ночных головных повязки и дикая лоза. Принеси это все, и выкройка твоя!', 'Принесите 2 ночных мундира, 2 ночных головных повязки и дикую лозу Пратту Макгруббену в крепость Оперенной Луны.', 'Да, это Ночное снаряжение – именно то, что я просил тебя принести, $N. Впрочем, от кожевника твоего уровня я другого и не ждал.$B$BТы достоин уметь изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь ее с пользой.', 'Мне нужны эти мундиры и головные повязки, а также дикий виноград, прежде чем я поделюсь с тобой секретом дикарского кожаного шлема!$B$BЛюбому искателю приключений необходима защита для головы, будь это простейшая головная повязка или глухой шлем. Ну и, разумеется, принцип изготовления шлемов всегда один и тот же, какими бы финтифлюшками ты его ни украшал.', NULL, NULL, 'Ночной мундир', 'Ночная головная повязка', 'Дикая лоза', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2851, 'Сапоги из дикой кожи', 'Тебе известно уже немало, $N. Однако многое еще остается постичь. Теперь ты узнаешь о сапогах из дикой кожи – ведь без обуви не обходится ни один доспех.$B$BНоге в них удобно и приятно, и дальний путь в них не так тяжел. Мягкая же подошва позволяет при необходимости ступать беззвучно.$B$BДля изготовления их по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И две дикие лозы – запомни, две, а не одна! Добудешь все это – тогда продолжим.', 'Принесите 2 пары ночных штанов, 2 пары ночных сапог и 2 диких лозы Пратту Макгруббену в крепость Оперенной Луны.', '', NULL, NULL, NULL, 'Ночные штаны', 'Ночные сапоги', 'Дикая лоза', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2852, 'Поножи из дикой кожи', 'Ну, $N, теперь, когда с простыми предметами покончено, мы можем перейти к более сложным вещам. Поножи из дикой кожи – одна из наиболее прочных и надежных разновидностей кожаного доспеха. Они отлично защищают и живот, и ноги, и прочие важные части тела. А поскольку в них вшита еще и дикая лоза, дающая дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи.$B$BДля изготовления изделия по этой выкройке мне понадобятся два черепашьих чешуйчатых шлема, две пары черепашьих чешуйчатых наручей, и две дикие лозы.', 'Принесите два черепашьих чешуйчатых шлема, две пары черепашьих чешуйчатых наручей и две дикие лозы Пратту Макгруббену в крепость Оперенной Луны.', '', NULL, NULL, NULL, 'Черепаший чешуйчатый шлем', 'Черепашьи чешуйчатые наручи', 'Дикая лоза', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2853, 'Мастер школы Дикаря', 'Что ж, $N, ты – образец прилежания. Остался только один предмет доспехов из дикой кожи, который ты не умеешь изготовлять. Я не стану заставлять тебя трудиться, чтобы ее получить: ты и так сполна $gрасплатился:расплатилась: за все. Однако же сам я тебе его дать не могу. Ты получишь награду от моего наставника, того, кто посвятил в тайны нашего ремесла меня самого. $B$BОтнеси эту записку Телонису. Он обучает кожевников в Дарнасе. Покажи ему записку, и пусть он приветствует тебя как $gравного:равную:, подобно мне самому.', 'Отдайте письмо Пратта Телонису, главному кожевнику Дарнаса.', 'А, ты от Пратта! Он, конечно, человек, но временами напоминает мне нас, ночных эльфов. Он действительно гениальный кожевенник! И если он тебя так расхваливает, это говорит в твою пользу.$B$BНасколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твое обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!', 'Приветствую, $R... Судя по твоему внешнему виду, ты – кожевник, как и я. Ты пришел, чтобы учиться, или у тебя ко мне другое дело?', NULL, NULL, 'Письмо Пратта (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2854, 'Доспехи из дикой кожи', '$N, ты уже $gопытный кожевник:опытная кожевница:. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это доспехи из дикой кожи. В них используется загадочная и непостоянная сила дикой лозы, которую можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах.$B$BЯ научу тебя делать эти доспехи, но для этого тебе придется потрудиться. Для начала мне нужно просто десять кусков толстой кожи. Принеси ее, потом обсудим дальнейшее.', 'Принесите 10 кусков плотной кожи Джангору Быстрому Страннику в Лагерь Мохаче.', 'Ну что ж, $N, я рад, что ты теперь мой ученик. Ты поступил разумно, избрав ремесло кожевника: когда ты научишься изготовлять дикарские кожаные доспехи, у тебя отбою не будет от тех, кто одевается в кожу.$B$BНу, за работу! С чего мы начнем?', 'Чтобы не было недоразумений: пока ты овладеваешь искусством изготовления дикарских кожаных доспехов, ты считаешься моим учеником. Дикий виноград – растение мощное, но непостоянное, и потому оно придает изготовленной тобой прочной броне дополнительную прочность, которая, однако, проявляется время от времени. Однако все эти знания дались мне не даром!$B$BПервоначальная плата за обучение составляет десять кусков плотной кожи.$B$BНу, а когда ты их добудешь, мы поговорим о работе, которую тебе следует выполнить.', NULL, NULL, 'Плотная кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2855, 'Наплечники из дикой кожи', 'Наплечники из дикой кожи обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все доспехи из дикой кожи, они прошиты дикой лозой, что придает им мощные, но непостоянные магические свойства.$B$BДля изготовления изделия по этой выкройке мне потребуется шесть накладок из толстой кожи и дикая лоза. Для тебя это не слишком сложное задание.', 'Принесите 6 накладок из толстой кожи и дикую лозу Джангору Быстрому Страннику в лагерь Мохаче.', 'Да, $N, это хорошие, надежные доспехи. Если я чего требую не только от себя, но и от своих учеников, так это высокого качества!$B$BТы неплохо потрудился, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.', 'Ну что, принес ли ты шесть наборов для усиления брони из толстой кожи и дикий виноград, как я просил?$B$BИзготовление комплектов для усиления брони – дело непростое и трудоемкое, но это помогает набить руку перед тем, как взяться за более сложные вещи, например, дикарские кожаные доспехи.$B$BКаждый урок имеет свою цель, Шкек. И к любому заданию следует относиться ответственно.', NULL, NULL, 'Накладки из толстой кожи', 'Дикая лоза', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2856, 'Ж$N из дикой кожи', 'Ж$N – основа любых доспехов из дикой кожи. Основа ж$Nа переплетена дикой лозой, что дает максимальную защиту торса и позволяет использовать мощную магию растения.$B$BДля изготовления предмета по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикая лоза. Добыть все это непросто, но, думаю, ты справишься.', 'Принесите 2 черепашьих чешуйчатых кирасы, 2 пары черепашьих чешуйчатых перчаток и дикую лозу Джангору Быстрому Страннику в лагерь Мохаче.', 'Да, $N, неплохие вещицы! Судя по умению и старанию, с какими они изготовлены, ты всерьез относишься к своему ремеслу.$B$BНу что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные ж$Nы!', 'Ну что, где те черепашьи чешуйчатые кирасы и перчатки, что я велел принести? И не забудь про дикий виноград!$B$BЕще работая с простейшими выкройками, мы понимаем, что сложное и простое строится по одним и тем же принципам. Таким образом, изготовление черепашьих чешуйчатых кирас подготавливает тебя к созданию дикарского кожаного ж$Nа.$B$BЧем дальше ты продвигаешься, тем больше твое ремесло становится сродни искусству!', NULL, NULL, 'Черепашья чешуйчатая кираса', 'Черепашьи чешуйчатые перчатки', 'Дикая лоза', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2857, 'Шлем из дикой кожи', 'Шлем из дикой кожи обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех доспехах из дикой кожи, в основу шлема вплетена дикая лоза, наделяющая его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!$B$BНо для изготовления изделия по этой выкройке мне понадобятся 2 ночных мундира, 2 ночных головных повязки и дикая лоза. Принеси это все, и выкройка твоя!', 'Принесите 2 ночных мундира, 2 ночных головных повязки и дикую лозу Джангору Быстрому Страннику в лагерь Мохаче.', 'Да, это Ночное снаряжение – именно то, что я просил тебя принести, $N. Впрочем, от кожевника твоего уровня я другого и не ждал.$B$BТы достоин того, чтобы изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь ее с пользой.', 'Мне нужны эти мундиры и головные повязки, а также дикий виноград, прежде чем я поделюсь с тобой секретом буйного кожаного шлема!$B$BЛюбому искателю приключений необходима защита для головы, будь это простейшая головная повязка или глухой шлем. Ну и, разумеется, принцип изготовления шлемов всегда один и тот же, какими бы финтифлюшками ты его ни украшал.', NULL, NULL, 'Ночной мундир', 'Ночная головная повязка', 'Дикая лоза', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2858, 'Сапоги из дикой кожи', 'Тебе известно уже немало, $N. Однако многое еще остается постичь. Теперь ты узнаешь о сапогах из дикой кожи – ведь без обуви не обходится ни один доспех.$B$BНоге в них удобно и приятно, и дальний путь в них не так тяжел. Мягкая же подошва позволяет при необходимости ступать беззвучно.$B$BДля изготовления их по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И две дикие лозы – запомни, две, а не одна! Добудешь все это – тогда продолжим.', 'Принесите 2 пары ночных штанов, 2 пары ночных сапог и 2 диких лозы Джангору Быстрому Страннику в лагерь Мохаче.', 'И снова ты выполняешь непростой заказ с искусством опытного профессионала! Ты заслужил эту выкройку, равно как и мою благодарность.', 'Прежде чем ты получишь выкройку, $N, тебе следует выполнить мой заказ! Что, у тебя все готово?$B$BС самой первой модели сапог, которую мы изучаем, мы постигаем общий принцип изготовления сапог. В качественной обуви должен соблюдаться тонкий баланс между удобством и функциональностью. В хорошей обуви ее хозяин, не уставая, пройдет расстояние вдвое большее, чем то, от которого владелец дешевой обувки свалится с ног.', NULL, NULL, 'Ночные штаны', 'Ночные сапоги', 'Дикая лоза', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2859, 'Поножи из дикой кожи', 'Ну, $N, теперь, когда с простыми предметами покончено, мы можем перейти к более сложным вещам. Поножи из дикой кожи – одна из наиболее прочных и надежных разновидностей кожаного доспеха. Они отлично защищают и живот, и ноги, и прочие важные части тела. А поскольку в них вшита еще и дикая лоза, дающая дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи.$B$BДля изготовления изделия по этой выкройке мне понадобятся два черепашьих чешуйчатых шлема, две пары черепашьих чешуйчатых наручей, и две дикие лозы.', 'Принесите два черепашьих чешуйчатых шлема, две пары черепашьих чешуйчатых наручей и две дикие лозы Джангору Быстрому Страннику в лагерь Мохаче.', 'Ну что, мой приказ снова выполнен отлично. Может, в один прекрасный день уже я явлюсь к тебе, как ученик к учителю, а, Бубен?$B$BВот выкройка поножей, а с ней и моя благодарность. Пусти полученные знания в дело, и пусть твои изделия будут достойны твоих способностей!', 'Ну что, готовы ли черепашьи чешуйчатые наручи и шлемы? И не забудь, теперь мне нужно два экземпляра дикого винограда!$B$BТеперь ты начинаешь осознавать, какое могущество заложено в дикарских кожаных доспехах. Умение изготовлять такие универсальные доспехи для кожевника почти что бесценно! Единственное ограничение – это наличие нужных ресурсов. А качество готового доспеха границ не имеет!', NULL, NULL, 'Черепаший чешуйчатый шлем', 'Черепашьи чешуйчатые наручи', 'Дикая лоза', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2860, 'Мастер школы Дикаря', 'Что ж, $N, теперь ты знаешь все, чему я мог тебя научить. Однако остался еще один предмет из дикой кожи, выкройки которого у тебя нет. Я не стану заставлять тебя трудиться, чтобы ее получить: ты и так сполна $gрасплатился:расплатилась: за все. Однако же отдать тебе его сам я не могу.$B$BТы получишь награду от моей наставницы, той, которая посвятила в тайны нашего ремесла меня самого. Отнеси эту записку Уне. Она обучает кожевников в Громовом Утесе. Покажи ей записку, и пусть она приветствует тебя как $gравного:равную:, подобно мне самому.', 'Отдайте письмо Джангора Уне, главному кожевнику Громового Утеса.', 'А, ты от Джангора! Приятно видеть, что у одного из моих лучших учеников теперь свои ученики…$B$BДжангор – очень талантливый и добросовестный кожевенник. И если он тебя так расхваливает, это говорит в твою пользу.$B$BНасколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твое обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!', 'Приветствую, $R... Судя по твоему внешнему виду, ты – кожевник, как и я. Ты пришел, чтобы учиться, или у тебя ко мне другое дело?', NULL, NULL, 'Письмо Джангора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2861, 'Миссия Табеты', 'Ходят слухи, что у Табеты, мага, живущего в Пылевых топях, серьезный зуб на одну песчаную троллиху из Зул\'Фаррака. Если ты поговоришь с Табетой, она, конечно, расскажет тебя больше.$B$BИ захвати с собой друзей, $N. Если она пошлет тебя в Зул\'Фаррак, а, скорее всего, так и будет, то лучше тебе там в одиночку не появляться.$B$BТы найдешь дом Табеты к западу от Терамора и к северу от руин Каменного Молота.', 'Поговорите с Табетой в Пылевых топях.', 'Да. Верно. У меня большой зуб на эту троллиху. И не один.$B$BХочешь помочь мне?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2862, 'Война с племенем Древолапов', 'О, эти гноллы... Сказать, что они отравляют нам жизнь – значит ничего не сказать! Мы здесь постоянно живем под угрозой нападения! Я не знаю, всегда ли они жили в Фераласе, или пришли сюда откуда-то еще, но если мы не будем противостоять им достаточно решительно, нам здесь не жить.$B$BА в последнее время гноллы совершенно озверели! Нам необходима твоя помощь, чтобы сократить их численность. Принеси мне десяток их грив, и я щедро вознагражу тебя за труды.$B$BСтупай!', 'Принесите 10 грив гноллов-древолапов Хадокену Быстрому Страннику в Лагере Мохаче.', 'Неплохое начало, $N! Таких воинов, как ты, еще поискать!$B$BЯ ведь давал такое задание не только тебе. И до тебя немало бойцов сражались с гноллами, и в былые времена наших усилий хватало, чтобы заставить их отступить. Однако в последнее время они упорно прут на север, в наши земли. Гноллы бьются так отчаянно... как будто им некуда отступать!$B$BОднако у меня есть один план. Возможно, он позволит раз и навсегда покончить с этой войной...', 'Мы отражаем их нападения, а они все лезут и лезут! Их явно что-то гонит... Или, может быть, кто-то? А, $N, ты уже вернулся? Ну что, гривы при тебе?', NULL, NULL, 'Грива гнолла-древолапа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2863, 'Истребление вожаков', 'План состоит в том, чтобы одним махом истребить всех предводителей гноллов. Если нам удастся это сделать, в рядах гноллов воцарится хаос. А возможно, до этих блохастых тварей даже дойдет, что с нами лучше не связываться!$B$BТебе, $N, я поручаю истребить пятерых вожаков гноллов. Только сделать это нужно в течение часа, иначе весь план пойдет н$Nку!', 'Убейте в течение часа 5 вожаков стаи Древолапов и вернитесь к Хадокену Быстрому Страннику.', 'Тебе удалось выполнить мою просьбу. Молодец, $N! Вот, прими эту небольшую награду за свои труды.$B$BТеперь, когда число гноллов сократилось, и их вожаки перебиты, эти твари дважды подумают, прежде чем решатся снова напасть на лагерь! Однако проблемы это не решает...$B$BГноллы не могли так озвереть безо всякой причины! И я хочу выяснить, в чем дело, прежде, чем они пришли в себя.', NULL, NULL, NULL, 'Вожак стаи Древолапов убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2864, 'Тран\'рек', 'У моего кузена Тран\'река сейчас большие проблемы. Он обещал мне партию панцирей скарабея еще неделю назад, но так и не поставил. Он мой кузен, так что я не хотел бы посылать кого-то в Прибамбасск выколачивать из него свои деньги или груз.$B$BМожешь поговорить с ним за меня? Скажи ему, что он должен доставить мне этот груз – иначе придется отвечать, как и всем остальным... $B$BПрибамбасск находится на севере пустыни Танарис в Калимдоре.', 'Поговорите с Тран\'реком в Прибамбасске.', 'Привет!$B$BТак ты общался с моим кузеном Кразеком? Ну и как он там? Надеюсь, что в Бухте контрабандистов к нему хорошо относятся…$B$BПанцири скарабея, говоришь? Дай мне рассказать тебе одну историю.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2865, 'Панцири скарабеев', 'У скарабеев Танариса очень твердый панцирь, достаточно твердый, чтобы использовать их как строительный материал много для чего. Очень много!$B$BЭти панцири, настолько полезная вещь, что ради них скарабеев извели практически под корень.$B$BЯ знаю, где они еще водятся, и я поделюсь с тобой, если ты пообещаешь принести мне их панцири, обещаешь?$B$BТак вот. Колония скарабеев находится в Зул\'Фарраке. Видимо до троллей еще не дошло, насколько полезны их панцири.$B$BТак что все твои! Отправляйся в Зул\'Фаррак и принеси мне целых панцирей скарабеев.', 'Принести 5 целых панцирей скарабея Тран\'реку в Прибамбасск.', 'Урра! Ты достал их!$B$BСпасибо, $N, ты мне просто жизнь спас!', 'Принес? Мой кузен в Пиратской бухте очень ждет этих панцирей. А он не любит ждать!', NULL, NULL, 'Нерасколотый панцирь скарабея', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2866, 'Руины Соларсаля', 'К югу от нас находятся руины Соларсаля. Это развалины очень древнего города. Мы уже обследовали руины, но пока не нашли там ничего примечательного и оставили их в покое.$B$BОднако не так давно в этих развалинах поселились наги из клана Гребня Ненависти, причем в угрожающих количествах. Поначалу мы решили, что они готовят нападение. Возможно, они его действительно готовят, но нам кажется, что там происходит что-то еще.$B$BСтупай туда, осмотри развалины и обрати внимание на все, что покажется подозрительным. Удачи, $N!', 'Обследуйте руины Соларсаля на предмет присутствия наг.', 'Внимательно изучив беседку, вы обнаруживаете следующее. $B$BВо-первых, беседка явно новая, и не похожа на окружающие руины. Во-вторых, столбы беседки исписаны мелкими значками. Значки повторяются, но что это за письмена и что они означают, вам непонятно. Ну и, в-третьих, камень беседки – теплый на ощупь.$B$BДа, все это, несомненно, подозрительно!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2867, 'Возвращение в Крепость Оперенной Луны', 'Теперь, когда вы обнаружили странную беседку в глубине руин Соларсаля, настало время вернуться в Крепость Оперенной Луны и доложить генералу Шандрисе Оперенной Луне о своем открытии.', 'Вернитесь в Крепость Оперенной Луны к Шандрисе Оперенной Луне и доложите о находке.', 'С возвращением, $N! Обнаруженная тобой беседка действительно весьма... подозрительна. Очевидно, что даже если наги и не замышляют нападения, их присутствие не сулит нам ничего хорошего. Ну, как бы то ни было, вот твоя заслуженная награда.$B$BСудя по всему, Крепость Оперенной Луны отчаянно нуждается в помощи для борьбы с нагами из клана Гребня Ненависти. Я бы хотела дать тебе еще одно поручение, если ты не против...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2869, 'Борьба с Гребнем Ненависти', 'На данный момент самое разумное – рассчитывать на то, что наги в любом случае попытаются захватить остров. И нам нужно предотвратить эту угрозу, пока не стало поздно.$B$BПринеси мне десять штук чешуи Гребня Ненависти. Как их добыть – думаю, ясно? У тебя будет случай поохотиться на наг, и количество их воинов на острове Сардор уменьшится. И то, и другое нам на пользу!', 'Принесите 10 штук чешуи наг из клана Гребня Ненависти Латроникусу Лунному Копью в Крепость Оперенной Луны.', 'Да-да, эта чешуя вполне годится. Думаю, мы отправим ее Пратту. Может быть, он сумеет изготовить из нее что-нибудь полезное.$B$BА для тебя у меня есть еще одно задание. Но сначала вот твоя награда за труды. Твоя служба генералу и всей Крепости Оперенной Луны очень ценна перед лицом грозящей нам опасности.', 'Если ты здесь затем, чтобы отчитаться о выполнении задания, $N, то отлично: где мои десять штук чешуи? А если ты просто так, поболтать, то мне сейчас не до этого.$B$BЗнай, мы, ночные эльфы – народ мирный! Мы стремимся лишь к поддержанию мира и гармонии. Однако это не значит, что мы не готовы защищать свои интересы. Это мой долг перед генералом Лунное Перо, и перед всей крепостью!', NULL, NULL, 'Чешуя наги из клана Гребня Ненависти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2870, 'Борьба с лордом Шалзару', '$N, мы получили новые донесения разведчиков, и теперь неплохо представляем себе, как устроено войско наг. Высшее командование состоит из особ королевской крови. Именно они-то всем и заправляют.$B$BНам стало известно имя одного из самых жестоких нагов, лорда Шалзару. Разведка докладывает, что во время недавних раскопок, которые наги проводили в пещере к югу от основных руин на острове Ужаса, он лично обнаружил некую загадочную реликвию.$B$BЕго необходимо остановить. Убей его, и принеси мне этот предмет, чтобы мы могли его изучить.', 'Убейте лорда Шалзару и принесите обнаруженную им таинственную реликвию Латроникусу Лунному Копью в Крепость Оперенной Луны.', 'Отлично, $N! Гибель лорда Шалзару повергнет наг в смятение – надолго, если не навсегда. Так что теперь они представляют значительно меньшую угрозу, чем прежде, и все это – благодаря тебе!$B$BВот тебе новая награда из сокровищницы замка. Эта награда заслужена тобой – вся, вплоть до последней монеты! Добро пожаловать в Крепость Оперенной Луны в любое время, друг мой.$B$BДа, $N, и прежде, чем ты уйдешь... еще одна просьба...', 'Смерть лорда Шалзару заставит их отложить выполнение своих планов на несколько недель, если не на несколько месяцев. Кроме того, обнаруженная им реликвия весьма любопытна…$B$BНу что, $N, удалось тебе выполнить задание?', NULL, NULL, 'Таинственная реликвия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2871, 'Доставка реликвии', 'Не возьмешься ли ты доставить эту реликвию моей жене Вестии? Я был бы тебе очень признателен. Она не только почтенная жрица, но и одна из наиболее сведущих ученых. Я лично не пойму, что это за штука, хоть меня озолоти. Но уж если моя жена в ней не разберется, значит, не разберется никто.$B$BОна вон там, неподалеку. Занимается, небось. Спасибо, $N!', 'Доставьте таинственную реликвию Вестии Лунное Копье в Крепость Оперенной Луны.', 'Интересно... Так говоришь, это вещь из руин Соларсаля? Ну да, Латро прав: мне следовало на это взглянуть... Такое впечатление, что эта вещь – не оттуда. С другой стороны, на работу наг это тоже не похоже. Далеко не столь чуждое…$B$BМне потребуется некоторое время на то, чтобы с ней разобраться. А когда я завершу свои исследования, возможно, ты мне снова пригодишься – если ты, конечно, окажешься в это время поблизости.$B$BНа, возьми это – у нас таких вещиц много, а тебе она, думаю, пригодится!', 'Да, чем могу помочь? Постой-постой, это ты – тот самый $C, который помогает генералу Лунное Перо и моему Латро разобраться с нагами? Я – Вестия, жена Латро... то есть Латроникуса. Очень рада познакомиться!$B$BНо прошу прощения – ведь ты, конечно, здесь по делу? Ты мне что-то принес?', NULL, NULL, 'Таинственная реликвия (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2872, 'Долг Столи', 'Мой давний приятель Столи должен мне особую бутылку рома. Он держит бар в Порту Картеля в Танарисе, и клялся, что ром у него крепче, чем во всей Пиратской Бухте. Он даже заявил, что удвоит свой долг мне, если я попробую его напиток и не соглашусь с ним!$B$BДумаю, он потом пожалел о своих словах, потому и не шлет мне ром. Но я ничего не забываю, поэтому поговори с ним вместо меня...', 'Поговорите со Столи из Порта Картеля.', 'А, ты уже поговорил с МакКинли!$B$BОн ошибается! Я вовсе не боюсь угостить его Картельским ромом…$B$BПросто рома у меня нет!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2873, 'Посылка Столи', 'Я должен старине Маккинли из Пиратской Бухты немного рома. Проблема в том, что ром у меня закончился! Капитан Куэрго украл последнюю партию и прячет в стенах огороженного пиратского поселения на юге.$B$BЕсли ты отыщешь мою партию рома, я смогу доказать Маккинли, что калимдорская выпивка в сто раз лучше пойла из Пиратской Бухты!', 'Отыщите партию товара Столи и возвратите ее хозяину в Порт Картеля.', 'Здорово, спасибо за помощь! Теперь я наконец-то выиграю пари у МакКинли.', 'Ну что, $N? Удалось тебе отыскать партию рома?', NULL, NULL, 'Посылка Столи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2874, 'Ром для Маккинли', 'Еще раз спасибо за помощь, $N. Вот тебе бутылка картельского рома. Отнеси ее Маккинли, пора развеять его заблуждения относительно рома из Пиратской Бухты.', 'Отнесите бутылку Столи \"Морскому волку\" МакКинли в Пиратскую Бухту.', 'Попробуем…$B$BПрямо не верится! Ужасный напиток! Потрясающий!$B$BПожалуй, придется простить Столи долг. Он не обманул меня насчет Картельского рома. Эта штука густая как соус и жжет как лава!', 'Ну что, Столи раскошелился?', NULL, NULL, 'Бутылка Столи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2875, 'Разыскивается: Андре Огнебородый', 'Злобный пират Андре Огнебородый разыскивается за преступления против Картеля Хитрая Шестеренка и Прибамбасска.$B$BСогласно указу правящего совета, все лица, прочитавшие данный документ, уполномочены применять любые меры при задержании Андре и его пособников.$B$BСогласно следующему указу, если Андре скончается или по иным причинам не сможет предстать перед судом, его может представлять его голова. Предоставление упомянутой головы начальнику отдела безопасности Чепухастеру повлечет за собой заключение весьма выгодного и ответственного контракта.', 'Принесите голову Андре Огнебородого начальнику отдела безопасности Чепухастеру в Порт Картеля.', 'А, голова Андре. Значит, суд над ним все-таки состоялся!$B$BБольшое спасибо, $N. А теперь распишись тут, и я займусь оплатой твоих услуг.$B$BИ не беспокойся из-за надписи мелким шрифтом. Ничего страшного там нет, и... Не думаю, что найдется такое маленькое увеличительное стекло, все равно ее не прочитаешь.', 'Вид у тебя ошеломленный. Ты что, наши юридические документы почитал?', NULL, NULL, 'Голова Огнебородого', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2876, 'Расписание кораблей', 'В свитке приводится список рейсов между Портом Картеля и Пиратской Бухтой. Там перечислены все прошлые и будущие грузы с указанием названий кораблей, везущих их. Напротив некоторых стоит большой крестик, напротив других заметки \"ОТЛИЧНАЯ ДОБЫЧА\" и \"СИЛЬНАЯ ОХРАНА\".$B$BКое-кто из Порта Картеля очень заинтересуется этим документом.', 'Сообщите о корабельном расписании руководству Порта Картеля.', 'Ох, похоже это список рейсов, причем здесь указаны дни и часы отбытия и прибытия! Если эти сведения попали в руки капитана пиратского корабля, у нас будут большие неприятности!$B$BТы их у пирата нашел? Дурные вести…$B$BСпасибо, $N. Я рад, что ты нашел этот документ и отправил пирата кормить рыб!', 'Я смотрю, ты тяжело дышишь! У тебя какие-то новости?', NULL, NULL, 'Корабельное расписание (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2877, 'Зачистка Осклизлой скалы', 'Мы, клан Громового Молота, помним прошлое куда лучше, чем наши собраться из Стальгорна. Если хочешь, чтобы к тебе тут хорошо относились, не бойся грязной работы!$B$BОрда забросила одну из своих баз во Внутренних землях, она находится на Осклизлой скале. Сейчас эту базу заполонили слизнюки и пиявки, у нас были на нее планы, но пока там кишат эти твари, мы не можем занять эту позицию.$B$BВот тебе, собственно, и работка! Отправляйся туда и убей по 10 зеленых слякочей и нефритовых слизнюков, а потом доложи мне, как все прошло. Вперед!', 'Убейте 10 зеленых слякочей и 10 нефритовых слизнюков, после чего доложитесь Фраггару Громовой Мантии, который ждет вас на Заоблачном пике.', 'Нет, подумать только, как вы здорово помогли Громовому Молоту! Вы отлично работаете, а мы это ценим.$B$BВаша маленькая зачистка куда важнее, чем может показаться на первый взгляд. Осталось еще истребить слизнюков и пиявок, и тогда мы сможем распространить свое влияние еще дальше. Новые друзья на Заоблочном Пике – это, конечно, хорошо, но, как говорится, не дружбой единой, так что вот вам еще кое-что, вдобавок.', NULL, NULL, NULL, 'Зеленый слякоч убито', 'Нефритовый слизнюк убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2878, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет некоторым количетсвом кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2879, 'Посох равноденствия', 'Это, должно быть, посох Равноденствия! Этот посох, на самом деле, является ключом, которым некогда отмыкали Монолит Равноденствия в Руинах Яростного Ветра, на материке к западу от Сонных Ветвей.$B$BОтыщите четыре огня, которые все еще пылают среди руин: Самха, Имбел, Бильтан и Лахасса. Добудьте их суть, встаньте перед Монолитом и зарядите посох их силой. Если это действительно посох Равноденствия, вы сумеете отпереть Монолит и достать из него священный артефакт.', 'Зарядите посох Трояса и отыщите Монолит Равноденствия.', 'Заряженный посох буквально вырывается из рук. Невероятная мощь отдается дрожью во всем теле.$B$BВы касаетесь холодной поверхности Монолита…$B$BОтворяется небольшая дверка, за ней виднеется артефакт.$B$BВсе пространство вокруг Монолита Равноденствия озаряется светом.', 'Монолит Равноденствия безмолвно высится среди руин. Что же может быть внутри него?', NULL, NULL, 'Посох Равноденствия', 'Посох Трояса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2880, 'Ожерелья троллей', 'Я скажу прямо, $r – мы НЕ принадлежим к Альянсу! Клан Громового Молота – это независимая организация, и мы относимся хорошо только к тем, кто заслужил это своими делами, а не пустой высокопарной болтовней!$B$BЕсли вы хотите, чтобы вас тут уважали, – докажите, что вы достойны! В холмах Внутренних земель поселились мерзкие тролли, которые иногда носят племенные ожерелья. Принесите мне пять таких ожерелий, и тогда я, возможно, поверю, что с вами можно иметь дело.', 'Принесите 5 тролльих ожерелий Фраггару Громовой Мантии на Заоблачный пик.', 'Вот, о чем я и говорил! Эти ожерелья доказывают, что вы не боитесь черной работы, а клан Громового Молота это ценит.$B$BПродолжайте в том же духе, и заслужите наше уважение.', 'Мне нужно пять ожерелий, которые носят эти тролли. Если непонятно, то поясню, что проще всего снять ожерелье с мертвого тролля.$B$BДокажите, что вы друг Громового Молота.', NULL, NULL, 'Племенное троллье ожерелье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2881, 'Ожерелья троллей', '', '', 'Чем больше ожерелий, тем меньше троллей во Внутренних Землях! Вы молодец, $N. Так держать!', NULL, NULL, NULL, 'Племенное троллье ожерелье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2882, 'Золото Куэрго', 'На карте изображена южная часть берега, а ниже имеется элегантная подпись…$B$B$BЮжней Шестеренки,$BНа юге от дома$BНайдешь ты флаг, мачту и кости – знакомо?$BКопай прямо там, если смелости хватит –$BЗа все тебе злато Куэрго отплатит. $BПоищешь ты ключ и конечно найдешь,$BНо прежде немало крови прольешь.', 'Найдите золото Куэрго!', 'Вас ждут скрытые сокровища капитана Куэрго!', 'Сундук заперт!', NULL, NULL, 'Ключ Куэрго', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2902, 'Разведка планов Древолапов', 'Гноллы, конечно, умом не блещут, но в последнее время в их деятельности прослеживаются признаки тщательного планирования. Если бы удалось добыть эти планы, возможно, нам было бы проще понять, отчего они так зашевелились в последнее время.$B$BПрошу тебя, вернись в лагеря Древолапов и попытайся найти что-нибудь похожее на боевые планы. Наверняка у них есть что-то в этом духе: в последнее время они действуют чересчур согласованно. Отыщи эти планы, и возвращайся ко мне.', 'Найдите гноллские боевые планы в гноллских лагерях к югу от Лагеря Мохаче.', 'Да, это те самые планы, которые просил отыскать Хадокен Быстрый Странник. Множество стрелок, очевидно, обозначают передвижения войск, однако большая часть этих стрелок направлена не на север, к Лагерю Мохаче, а на юг.$B$BВ углу карты нарисовано нечто вроде крупного насекомого, окруженного разнообразными значками. Судя по всему, гноллов действительно донимают какие-то насекомые...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2903, 'Планы битвы', 'Теперь, когда планы гноллов добыты, вам остается только вернуться с ними в Лагерь Мохаче к Хадокену Быстрому Страннику. Быть может, он или еще кто-нибудь сумеет разобраться, что замышляют гноллы?', 'Отнесите планы битвы Древолапов Хадокену Быстрому Страннику в Лагерь Мохаче.', 'О, это именно то, что нам нужно! Я, правда, не мастак разбирать всякие каракули, однако я на своем веку повидал достаточно планов битв, чтобы понять, что творится у гноллов. Похоже, сейчас они ведут войну на два фронта. Один противник – это мы... но, судя по всему, основные их силы брошены на юг.$B$BТут все не так просто! Возможно, пора выяснить, с кем же они воюют.', 'С возвращением, $N. Ну что, удалось тебе обнаружить какие-нибудь планы?', NULL, NULL, 'План битвы Древолапов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2904, 'Катавасия', '<Керноби стонет> Э-э... Что случилось?$B$BПоследнее, что я помню, это как меня похитили дворфы Черного Железа, избили до полусмерти и бросили сюда, к этим омерзительным троггам.$B$BВытащи меня отсюда, $N!$B$BСделаем так: выведи меня к выходу; если нам удастся выбраться живыми, пойдешь в Пиратскую Бухту и скажешь Скути, что я был в Кабестане и предупредил Оловеня, что дворфы Черного Железа тоже как-то связаны с работой над супер-роботом.$B$BИдем!', 'Отведите Керноби к Часовому ходу. Затем отправляйтесь с донесением к Скути в Пиратскую Бухту.', 'Ты достоин награды за то, что вернул Керноби целым и невредимым, $N. Если твой дальнейший путь ведет в Гномреган, вот это поможет тебе расправиться с никчемным предателем, Анжинером Термоштепселем.', NULL, NULL, NULL, 'Спасение Керноби', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2922, 'Промыть мозг Техботу', 'Когда пал наш родной город Гномреган, с Техботом, видимо от расстройства, приключилось короткое замыкание. Бедный мой маленький друг! Он так помогал мне и моим коллегам! В него встроена куча полезных прибамбасов на все случаи жизни, объем памяти просто огромен, но все это теперь совершенно бесполезно – его мозг из позитронного стал негатронным! Все заложенные в него программы теперь работают наоборот. Мой бедный сумасшедший робот теперь бродит по Гномрегану.$B$BМожет, тебе удастся изловить его и извлечь его ядро памяти. Тогда я смогу разобраться в причинах поломки и, возможно, устраню ее.', 'Принесите ядро памяти Техбота мехмастеру Замыкальцу в Стальгорн.', 'О, какое счастье! Спасибо, $N! Я немедленно начну разбираться с поломкой! $B$BБедный мой Техбот! Потерпи, я тебя вылечу. $B$BТак, куда же я засунул свой гидропневмогайковерт...', 'Ну как, нашел Техбота?', NULL, NULL, 'Ядро памяти техбота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2923, 'Мехмастер Замыкалец', 'Мехмастер Замыкалец крайне опечален судьбой своего творения – Техбота. Помнится, Техбот был когда-то для гномов весьма полезным инструментом, однако теперь Большая Искра говорит, что он сломан.$B$BОчень жаль. Но быть может, его еще возможно починить.$B$BПоговори об этом с Мехмастером Замыкальцем в Городе Механиков в Стальгорне. Он будет рад любой помощи.', 'Поговорите с механомастером Большой Искрой. ', 'Да, это правда. Мой Техбот совсем вышел из строя! Ты сможешь мне помочь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2924, 'Базовый элемент', 'Базовый элемент – практически универсальная деталь, широко используемая механиками и кузнецами Гномрегана. Однако в спешке покидая город, никто из нас не догадался прихватить с собой эти детали. Мне просто необходимо пополнить мои запасы!$B$BПожалуйста, отправляйся в Гномреган и добудь мне побольше этих бесценных артефактов. Ты найдешь их в подземельях нашего города – обычно они хранятся в контейнерах-экстраполяторах.$B$BУмоляю тебя, поторопись!', 'Принесите 12 базовых элементов Клацморту Гайкокруту в Стальгорн.', 'Прекрасно! Теперь я могу продолжить свои эксперименты! $B$BНе знаю как благодарить тебя, $N! Ты спас будущее гномьей науки!', 'Ну как, нашел механизмы?', NULL, NULL, 'Базовый элемент', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2925, 'Базовые элементы Клацморта', 'Мой друг, гном Клацморт Гайкокрут из Стальгорна, прислал мне письмо, в котором сообщает, что ему необходима помощь. Ему нужно отправиться в Гномреган, некогда величайший город гномов, который был осквернен, и теперь его населяют лишь безумные гномы и их жуткие изобретения.$B$BЯ не могу покинуть Дарнас, но душа моя болит за друга. Если ты сможешь помочь ему вместо меня, благодарности моей не будет предела.$B$BТы найдешь Клацморта в Городе Механиков в Стальгорне.', 'Поговорите с Клацмортом Гайкокрутом в Стальгорне. ', 'Да! Да! Мне очень нужна помощь в Гномрегане! И $C вроде тебя как раз подойдет!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2926, 'Новая формула', 'С самого дня нашего бегства из города Гноарн только о том и думает, как выставить троггов из Гномрегана и очистить город от заражения.$B$BУ нас с Раззлом есть некоторые идеи на этот счет, однако похоже, что воплотить их в жизнь сможет только настоящий безумец. Мы еще не знаем, сработает ли наш замысел – надо все как следует проверить! Для этого нам потребуются радиоактивные осадки, оставляемые облученными троггами в Гномрегане. Это зеленая светящаяся субстанция. Наполни ею эту склянку и принеси мне!', 'Соберите радиоактивный осадок, оставляемый облученными захватчиками и облученными погромщиками в пустую освинцованную склянку для проб. Принесите наполненную склянку Оззи Триггервольту в Каранос.', 'Прекрасно! Теперь пришла пора опробовать нашу новую формулу. Если этот метод сработает, я не только смогу вылечить этого несчастного лепрогнома, но и вернуть свою утраченную шевелюру! Ну-ка, отойди в сторонку!', 'Разве не понятно?! Мы пытаемся спасти целый народ! Нам необходимо изучить радиоактивный осадок! Ради будущего всех гномов!', NULL, NULL, 'Наполненная освинцованная склянка для проб', 'Пустая освинцованная склянка для проб', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2927, 'На другой день', 'Вы ведь не думаете, что я всегда был лысым? Нет, $gсударь:сударыня:! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане. До тех пор я был единственным кудрявым гномом во всем Азероте.$B$B*Гноарн потрясает в воздухе кулаком.*$B$BБудь прокляты эти проклятые грязные трогги, будь они все прокляты!!!$B$BМожет, еще не поздно, $N. Мы еще можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе. Они со своим партнером Раззлом как раз пытаются решить эту проблему.', 'Поговорите с Оззи Триггервольтом в Караносе, что в Дун Мороге.', 'Я думал, что утрата волос нашим выдающимся главой убьет его, так нет, выжил!$B$BЯ стоял рядом с ним, когда тот схватил дозу. И эти замечательные коричневые локоны посыпались на пол прядями! Клочьями! Ужас произошедшего только усилился, когда у Гроана крыша поехала! Да! Гроан, не веря глазам своим, коснулся лысой головы, и во взгляде его загорелась месть, $N! И тогда он обрушился на троггов!$B$B*Оззи ежится.*', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2928, 'Сооружение автогиробуророек', 'Это ужасно, $N. У нас, видно, не хватит запчастей, чтобы собрать всю партию автогиробуророек, которую пора отправить в Дун Морог.$B$BЧто нам точно нужно – так это детали, $N. И для добычи этих деталей не найти места лучше, чем Гномреган! Я слышала, что роботы и механизмы, оставшиеся там, бродят по городу как овцы на вольном пастбище.$B$BЯ хочу от вас, чтобы вы отправились в Гномреган и распотрошили этих роботов на запчасти. Двух дюжин деталей должно хватить.', 'Принесите Шони в Штормград 24 горсти механических внутренностей роботов.', 'Это отлично подойдёт, $N. Считайте, что одна автогиробуроройка отремонтирована. Осталось еще 398.', 'Если бы речь шла о гонках, вы бы уже проиграли.', NULL, NULL, 'Механические внутренности робота (24)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2929, 'Великое предательство', 'Я доверял Термоштепселю, $r. Никогда я не думал, что он предаст меня и весь гномий род. И ради чего? Ради власти? Богатства? Все это он и так со временем получил бы. Теперь мы лишились родного дома, а этот безумец остался там править. Король без королевства...$B$BМы вернем Гномреган, $N. Мы не остановимся, пока город снова не станет нашим! Если ты хочешь присоединиться к нашей борьбе, выполни совсем простое поручение – убей предателя. Уничтожь Анжинера Термоштепселя.', 'Отправляйтесь в Гномреган и убейте Анжинера Термоштепселя. Вернитесь к главному механику Меггакруту.', 'Я рад, что последнее, что он видел в своей жизни, была твоя стопа, попирающая его преступную голову, $R! Теперь, когда Термоштепсель мертв, наши планы по возвращению Гномрегана на шаг приблизились к осуществлению!', NULL, NULL, NULL, 'Анжинер Термоштепсель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2930, 'Спасение данных', 'Когда мы бежали из Гномрегана, то оставили там столько данных! Жизненно важных данных!$B$BМне нужны данные с радужной перфокарты чрезвычайно секретного терминала матричного перфографа 3005-D, что находится в глубинах Гномрегана. Тебе нужно добраться до терминала, но сначала надо получить допуск... а для этого надо добраться до терминалов низшего уровня защиты – моделей -A, -B и -C. А для ЭТОГО тебе понадобятся перфокарты допуска, начиная с белой... а все перфокарты остались в городе.$B$BЭто же катастрофа! Ты можешь помочь нам?', 'Принесите радужную перфокарту главному механику Чугунотрубзу в Стальгорн.', 'У вас получилось! Вы нашли призматическую перфокарту и восстановили утраченные данные! Жизненно, критически, безмерно важные данные, без которых мы просто не смогли бы жить!$B$BВашу услугу гномы запомнят надолго, $N.', 'Вы принесли призматическую перфокарту?', NULL, NULL, 'Радужная перфокарта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2931, 'Поручение Чугонотрубза', 'Стальгорнский главный механик Чугунотрубз ищет искателей приключений! Он собирает отряд для проникновения в Гномреган с целью возвращения данных чрезвычайной важности и секретности.$B$BХотя Чугунотрубз и не состоит в Просвещенной ассамблее чарологии, алхимии и инженерных наук, подобно мне, но он гном толковый, и если он считает это дело важным, то, по моим подсчетам, оно с вероятностью 84 процента важное!$B$BШансы хорошие!', 'Поговорите с главным механиком Чугунотрубзом в Стальгорне.', 'Я готовлю миссию в Гномреган для возвращения важных данных. Если вы пришли помочь, то слушайте!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2932, 'Предупреждение', 'Когда-то тролли из племени Сухокожих были на стороне Орды, но потом они предали Тралла... и это не должно сойти им с рук!$B$BВот, возьми мою пику и отправляйся во Внутренние земли, это далеко на севере. Сначала найди Мельницу Таррен – поселение наших союзников, Отрекшихся, а оттуда иди на северо-восток.$B$BВо Внутренних землях убей 20 троллей из племени Сухокожих, насади их черепа на мою пику и воткни ее в землю в одной из их деревенек – Хири\'вата или Зун\'вата.$B$BПусть видят, что за свои действия надо отвечать!', 'Соберите черепа троллей из племени Сухокожих и насадите их на пику Нимбойи, после чего установите пику с тролльими черепами в центре одной из их деревень во Внутренних землях и возвращайтесь к Нимбойе в Тернистую долину.', 'До меня дошли вести о ваших подвигах. Это жестокий поступок, но почетный. Надеюсь, тролли Сухокожих внимут нашему предупреждению.', NULL, NULL, NULL, 'Оставить предупреждение', 'Пика Нимбойи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2933, 'Бутыли с ядом', 'В этих бутылках содержится очень сильный зеленый яд.$B$BСудя по количеству бутылок в деревне, тролли из племени Сухокожих очень дорожат им. Возможно, аптекарь в Мельнице Таррен тоже заинтересуется этим ядом.', 'Принесите бутылку яда аптекарю в Мельницу Таррен.', 'О, что это? Похоже на яд... яд какого-то паукообразного, да? Где же вы его взяли?', 'Приветствую, милый $C! За весь этот длинный день у меня не было ни одного удачного эксперимента. Надеюсь услышать от вас хорошие новости.', NULL, NULL, 'Флакон с ядом (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2934, 'Неповрежденная ядовитая железа', 'Мне нужен свежий образец того яда, что вы приносили мне. Пауки, с которых он был собран, водятся во Внутренних землях – охотьтесь на них, пока вам не удастся добыть неповрежденную ядовитую железу, а потом принесите ее мне. Больше всего пауков живет в тролльем городе Шадра\'Алоре.$B$BИ не задерживайтесь, $N – ядовитая железа нужна мне предельно свежей.', 'Принесите неповрежденную ядовитую железу аптекарю Лидону в Мельницу Таррен.', 'О, замечательно! Яд свежий и, я уверен, чрезвычайно смертоносный! Спасибо!', 'Ну как, удалось добыть неповрежденную ядовитую железу, $N? Мне не терпится начать эксперименты с этим ядом, и у меня есть для этого целый выводок маленьких миленьких животных!', NULL, NULL, 'Неповрежденная ядовитая железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2935, 'Разговор с мастером Гадрином', 'Яд этих пауков не так силен, как тот, что вы приносили раньше. Наверное, тот яд был от другого паука.$B$BМне нужен свежий образец того яда, а чтобы узнать, откуда он, нужно поговорить с троллем, который много знает о племени Сухокожих – это мастер Гадрин в деревне Сен\'джин. Отправляйтесь в Дуротар и поговорите с ним. Он вполне может знать, откуда тролли племени Сухокожих берут этот яд.', 'Поговорите с мастером Гадрином в деревне Сен\'джин.', 'А, так вам нужен свежий яд пауков Сухокожих? Ну что ж, присядьте... вам не понравится то, что я сейчас скажу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2936, 'Паучья богиня', 'Тролли из племени Сухокожих поклоняются паучьей богине, и самый сильный яд берут у нее. Так что если тебе нужен этот яд, нужно будет призвать ее.$B$BДля этого требуется знать ее истинное имя – оно начертано на табличке в тролльском городе Зул\'Фарраке, что в Танарисе. Табличка находится у гробницы, которую охраняет Тека Мученик.$B$BСразись с Текой и прочитай на табличке имя паучьей богини, а потом возвращайся ко мне.', 'Прочитайте надписи на табличке Теки, узнайте имя паучьей богини, которой поклоняются тролли из племени Сухокожих, а потом возвращайтесь к мастеру Гадрину.', 'Элорта но Шадра... Произносите это имя лишь шепотом, потому что один его звук повергает духов в смятение.$B$BЯ напишу его на бумаге и сотворю для вас заклинание призыва.', NULL, NULL, NULL, 'Узнать имя паучьей богини', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2937, 'Призыв Шадры', 'Возьмите этот пергамент и прочитайте написанное на нем заклинание около алтаря Шадра\'Алора – это в самом сердце владений клана Сухокожих. Это заклинание призовет Шадру – паучью богиню.', 'Убейте Шадру у алтаря Шадра\'Алора и принесите ее яд аптекарю Лидону в Мельницу Таррен.', 'Лучше и быть не могло!', 'Достали яд?', NULL, NULL, 'Яд Шадры', 'Пергамент Гадрина', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2938, 'Яд в Подгород', 'Этот яд, который вы нашли у троллей Сухокожих, просто поразителен! Одной капли хватило, чтобы убить две дюжины кроликов. Ну, конечно, эти кролики были такие маленькие, что все уместились у меня на ладони, так что и организмы их особо не могли сопротивляться токсину... Но, тем не менее, яд просто убойный!$B$BЯ хотел бы отправить образец моему коллеге, аптекарю Фаранеллу в Подгород. Наверняка он захочет испытать его самостоятельно.', 'Отнесите сверток опытному аптекарю Фаранеллу в Подгород.', 'Очень хорошо. Лидон говорил, что яд в этом свертке – самый смертоносный из тех, что ему встречались, и теперь он в срочном порядке ищет способ его применения.$B$BНадеюсь, применений ему найдется немало.$B$BСпасибо, $N. Вы оказали Королевскому Фармацевтическому Обществу неоценимую услугу.', 'Мне сказали, что вы скоро будете, $N. Принесли мне письмо?', NULL, NULL, 'Сверток Фаранелла (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2939, 'В поисках знаний', 'Руины Фераласа могут быть очень опасны, но зато они способны немало рассказать нам о том, что здесь произошло.$B$BВот, к примеру, несколько дней тому назад, копаясь в развалинах к югу отсюда, я обнаружил одну вещицу. На вид – обычный посох, но меня не покидает ощущение, что посох этот не простой. Мы с Ангелас уже давно корпим над книгами, но так ничего о нем и не узнали.$B$BУ меня есть коллега в Дарнасе, которая, возможно, сумеет сообщить нам что-нибудь полезное. $N, быть может, вы сходите к ней и попросите нам помочь?', 'Поговорите с Дарин Добрый Ветер в деревне Рут\'теран. ', 'А, так ты от Трояса Лунного Бриза?$B$B*Бормочет себе под нос* Вот вечно он меня донимает: ему все время кажется, что он обнаружил что-то чрезвычайно важное…$B$BПослушай, $N, я буду говорить откровенно. Троясу каждый раз кажется, будто он нашел в этих развалинах невесть какую диковинку. На самом же деле все, что там было ценного, давно уже растащили огры либо гарпии.$B$BТы, конечно, можешь порыться в библиотеке, но не думаю, что ты сумеешь найти что-то, что тебе пригодится.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2940, '\"Фералас: История\"', 'Книга выглядит так, как будто ее не открывали годами. Переплет потерт и запылен, страницы пожелтели... Тем не менее, проглядев ее, вы убеждаетесь, что это именно то, что нужно было Троясу.$B$BВы берете книгу, но соображаете, что неплохо было бы спросить разрешения прежде, чем ее уносить.', 'Попросите Дарин Добрый Ветер одолжить вам книгу.', 'Ты хочешь взять \"Историю Фераласа\"?$B$BДай подумать…$B$BХорошо, я разрешу тебе позаимствовать эту книгу, $N, если ты сначала окажешь мне одну услугу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2941, 'В обмен на книгу', 'Я в свое время занималась самыми разными предметами, а вот сейчас меня очень интересуют хрустогрызы, которые обитают на побережье Внутренних земель. Мне особенно хочется посмотреть на одного из них: гигантскую черепаху, которую зовут Гаммерита. Я бы отправилась туда сама, но не могу отвлекаться от своих исследований. Добудь мне хотя бы изображение, ладно?$B$BОтнеси это письмо Кургль Поскакушке, которая живет в Танарисе. Она изобрела для меня машинку, которая может делать картинки. Кажется, Гурдл называет это \"снимками\"...', 'Отнесите письмо Кургль Поскакушке в Танарис.', 'А, ты один из студентов Дарин? Она очень сведущий историк, $N. Тебе повезло, что ты занимаешься под ее руководством.$B$BНу, давай я покажу тебе свой супер-хвататель. Он тебе понравится!', 'Письмо – мне?', NULL, NULL, 'Короткая записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2942, 'Завтрашний камень', 'Как только артефакт извлечен из Монолита, вы ощущаете, что энергия посоха Равноденствия идет на убыль.', 'Верните искрящийся камень и посох Равноденствия Троясу Лунному Бризу в Крепость Оперенной Луны.', 'Я с самого вашего ухода не отрывался от книги, $N. Так вот: добытый вами камень называется Завтрашний камень. Для чего он нужен, я пока точно не знаю, однако понятно, что пустяковую вещь так прятать не стали бы.$B$BЯ буду продолжать свои исследования. Надеюсь, что я и в будущем смогу на вас рассчитывать, $N. Спасибо вам за все!', 'Я рад, что вы вернулись, $N! Ну что, удалось вам что-нибудь найти?', NULL, NULL, 'Искрящийся камень', 'Посох Равноденствия (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2943, 'Возвращение к Троясу', 'Вот книга, $N. Пожалуйста, обращайся с ней бережно!$B$BНу, ступай. Наверно, Трояс тебя уже заждался.', 'Доставьте книгу Троясу Лунному Бризу в Крепость Оперенной Луны.', 'Книга у вас! Чудесно!', 'А, Ишт! Ну что, вы побывали в Дарнассе?', NULL, NULL, '\"История Фераласа\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2944, 'Супер-щёлк FX', 'Ты $gпервый:первая:, кто увидит мое новое изобретение – \"Супер-щёлк FX\"! Тебе нужно только навести его на предмет, который ты хочешь запечатлеть, и нажать на кнопку!$B$BКак там звать ту черепашку из Внутренних земель, которую ты ищешь? Гаммерита? На вот, бери и снимай. Я уверена, что Дарин будет в восторге от снимка.$B$BУдачно пощёлкать!', 'Сделайте снимок Гаммериты с помощью \"Супер-щёлк FX\" и вернитесь к Дарин Добрый Ветер в деревне Рут\'теран.', 'О да! Изобретение Гурдл оправдало все мои ожидания!$B$BТы только не зазнавайся, $N, но имей в виду, что я тобой довольна.$B$BТак, где же я оставила эту книгу...', 'А, $N, вот наконец и ты! У тебя с собой прибор, который изготовила для меня Гурдл? Отлично!', NULL, NULL, 'Снимок Гаммериты', 'Супер-щёлк FX (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2945, 'Кольцо, покрытое грязью', 'С тела одного из дворфов Черного Железа вы сняли предмет, напоминающий кольцо. Сложно сказать, что это за кольцо, поскольку оно покрыто толстым слоем окаменевшей грязи. Носить его едва ли возможно. Однако вы уверены, что под слоем грязи скрывается драгоценный металл, а может, еще и самоцвет.$B$BПожалуй, стоит попытаться отчистить всю эту грязь.', 'Придумайте, как отчистить кольцо, покрытое грязью.', 'Вы опускаете кольцо и три монеты в Чистер 5200.$B$BМашина с яростным гудением принимается за работу, скрипя и вибрируя. Сложно представить, что происходит внутри...$B$BНаконец Чистер 5200 замирает и окошко премника со звоном открывается. В нем лежит маленькая аккуратно завернутая коробка с красным бантиком. Похоже, Чистер 5200 также предоставляет подарочную упаковку!', 'Перед вами гномий механизм, к которому прикреплена табличка с названием \"Чистер 5200\". Судя по инструкции под табличкой, эта машина начищает предметы до зеркального блеска, устраняя все виды загрязнений. Машина снабжена щелью для монет, в которую требуется опустить три серебряный монеты, после того как предмет, нуждающийся в очистке, помещен внутрь. $B$BПохоже, стоит опробовать это приспособление на вашем кольце.', NULL, NULL, 'Покрытое грязью кольцо (Прилагается)', 'Требуется денег: 3', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2946, 'Посмотрим, что будет дальше', 'Мы хотим, чтобы вы доставили диски, обнаруженные вами, к запечатанным воротам Ульдума. Мы... мы не знаем, что с вами там может случиться.$B$BДа, мы знаем, что звучит рискованно. Но может ведь и ничего не случиться? Может, вам придется что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойтесь экспериментировать и будьте готовы ко всему.$B$BКогда справитесь с заданием, возвращайтесь в Стальгорн. Нам будет что проанализировать!', 'Принесите миниатюрные платиновые диски к воротам Ульдума в Танарисе и проверить, имеют ли диски отношение к воротам.', 'Когда вы прикасаетесь к постаменту, ульдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража.$B$B\"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание\".', 'Какой знакомый постамент. Возможно, он тут неспроста...', NULL, NULL, 'Миниатюрные платиновые диски (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2947, 'Возвращение кольца', 'Открыв коробку, вы видите именно то, что и предполагали – сияющее кольцо! Вы чувствуете исходящие от него волны магической силы.$B$BНа внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Стальгорна, а рядом с ним выгравированы инициалы: \"ТдК\". Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!', 'Вы можеть оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца.', 'Кольцо, говорите? Ну конечно, это я его сделал! $B$BДо падения Гномрегана у меня была там небольшая мастерская. Видимо, кольцо осталось там, когда пришлось очень быстро давать деру. Довольно простое кольцо – я сделал таких несколько. $B$BГоворите, сняли с дворфа Черного Железа? Занятно, занятно – дело пахнет весьма запутанной интригой... Возможно, следует дать знать властям; такие вещи не для нашего брата... $B$BЧто касается кольца...', 'Эй-эй! Кто тут ломится? Я уважаемый предприниматель! Нечего устраивать истерики, наверняка курьер с деньгами просто задержался в пути... А, прошу прощения, я принял вас за моего арендодателя! $B$BВы пришли к лучшему ювелиру Стальгорна, который НИКОГДА не создает проклятых предметов! $B$BТак что вам угодно?', NULL, NULL, 'Сверкающее золотое кольцо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2948, 'Гномское усовершенствование', 'Слушайте $N, конечно, это ваше кольцо... но я вам лучшее сделаю! Дизайн, как я уже сказал, уж очень прост. Теперь я уже намного искуснее, и всего за каких-то тридцать серебряников я вам из него шедевр сделаю! Ну, чуть побольше тридцати, честно говоря...$B$BСейчас я в затруднении, все мои запасы материалов иссякли. Если вы принесете мне слиток серебра и моховой агат, то я нанесу на кольцо решетчатый узор из серебра и агата, и оно станет гораздо более стильным!$B$BПоверьте мне!', 'Принесите сверкающее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Талвашу дель Кисселю в Стальгорн.', 'Ах, именно то, что нужно! Когда нибудь, когда я выберусь из этой ямы, в которую так незаслуженно попал, я сделаю для вас, для ВСЕХ лучшие украшения во всем Азероте! А пока благодарю вас за хлопоты. Обычно я прошу в десять раз больше, чем я взял с вас за кольцо такого качества...$B$BКстати, о кольцах – вот ваша обновка!', 'Вы принесли нужные материалы? Я бы не стал просить, если бы удача не покинула меня...', NULL, NULL, 'Сверкающее золотое кольцо (Прилагается)', 'Серебряный слиток', 'Моховой агат', 'Требуется денег: 30');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2949, 'Возвращение кольца', 'Открыв коробку, появившуюся в окошке Чистера 5200, вы видите сияющее кольцо! Надев кольцо на палец, вы чувствуете исходящие от него волны магической силы.$B$BНа внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Оргриммара, а рядом с ним выгравированы три буквы: \"НОГ\" – это явно начало имени, но даже после чистки прочесть его целиком невозможно. Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!', 'Вы можеть оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца.', 'Кольцо из Гномрегана? Очень любопытно... Нет, его сделал не я. $B$BГномреганская штучка – н-да, неплохо для горстки болванов. Подумать только, эти ходячие недоразумения вдруг научились делать машины лучше нас... $B$BЧто, кольцо было у дворфа Черного Железа? Еще интереснее... Возможно, гномы сперли и подправили чертежи их жутких големов – я бы этому совсем не удивился. Значит, теперь дворфы жаждут мести. Очень любопытно... $B$BЧто же о кольце...', 'Ничего, уж мы найдем управу на этих мерзких маленьких гномов. Я даже не сомневаюсь, что это они сперли у нас эту машину! Проклятые создания... А? Чего изволите?', NULL, NULL, 'Сверкающее золотое кольцо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2950, 'Переделка кольца', 'Нет-нет-нет, я не собираюсь утверждать, что это моя работа! Обычно я такого не делаю. Но твое сообщение насчет дворфов Черного Железа чрезвычайно полезно. Так и быть, я переделаю для тебя это кольцо, и оно станет куда лучше, чем мог предполагать его создатель. Наверно, это был какой-нибудь гном...$B$BПринеси мне слиток серебра, моховой агат и тридцать серебряных монет – за труды. Я украшу кольцо серебряной решеткой, вправлю в него агат, и это значительно усилит его магические свойства. Интересует?', 'Принесите сверкающее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Ноггу в Огргиммар.', 'Вот оно, твое кольцо, лучше прежнего. Еще раз спасибо за сведения об этих дворфах Черного Железа. Это объясняет, откуда вдруг у гномов взялись гоблинские идеи...', 'Ну что, есть у тебя нужные материалы? Без того, о чем я просил, я это кольцо улучшить не смогу!', NULL, NULL, 'Сверкающее золотое кольцо (Прилагается)', 'Серебряный слиток', 'Моховой агат', 'Требуется денег: 30');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2951, 'Чистер 5200!', 'Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений.Небольшая табличка, прикрепленная к устройству, гласит: \"Чистер 5200\".$B$BВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.', 'Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.', 'Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.', 'Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.', NULL, NULL, 'Покрытый грязью предмет', 'Требуется денег: 3', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2952, 'Чистер 5200!', '', '', 'С проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приемника открывается, и вы видите в нем аккуратно завернутую коробочку. Видимо, машина выдает очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги... Что ж, посмотрим...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2953, 'Работа для Чистера', '', '', 'Чистер 5200 с яростным гудением принимается за работу. Въевшаяся грязь растворяется под воздействием гномьих чистящих средств. $B$BНаконец Чистер 5200 перестает вибрировать. Окошко премника со звоном открывается – в нем лежит аккуратно завернутая коробка.', NULL, NULL, NULL, 'Покрытый грязью предмет', 'Требуется денег: 3', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2954, 'Каменный Страж', 'Приветствую. Я охраняю вход. Если в вашем наборе дисков нет Ульдумских пластин, вы не сможете посетить комплекс Ульдум.\"$B$BДолжно быть, появление Каменного Стража Норганнона и есть та реакция, на которую рассчитывали те, кто послал вас в пустыню Танарис с платиновыми дисками. Прежде чем продолжить путь, вам предстоит узнать историю Каменного Стража.', 'Узнайте назначение Каменного Стража Норганнона, затем коснитесь пьедестала Ульдума в пустыне Танарис.', 'В голосе Каменного Стража звучит сила и власть:$B$B\"Когда ты коснешья пьедестала, диски вернутся к тебе. Получив же Ульдумские пластины и воссоединив их с имеющимися дисками, ты сможешь войти в Ульдум.\"', 'Чтобы продолжить, следует узнать назначение Каменного Стража...', NULL, NULL, 'Узнайте назначение Каменного Стража Норганнона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2962, 'Сильное зеленое свечение', 'Этого образца не только недостаточно для опытов, он еще и загрязнен.$B$BНам нужно более сильное зеленое свечение. Для наших целей эти трогги явно недостаточно облучены. Вам придется отправиться в Гномреган и принести некоторое количество радиоактивных образцов прямо с носителей. Я говорю об облученных слизнюках, шнырюках и ужасниках. Будьте начеку: образцы хранить очень трудно. Возможно, придется сделать несколько попыток, пока вы не принесете достаточное количество образцов.', 'Отправляйтесь в Гномреган и принесите высокорадиоактивные образцы. Внимание: отходы нестабильны и довольно быстро разрушаются.Верните Оззи тяжелую освинцованную склянку для проб, когда задача будет выполнена.', '*Оззи рассматривает вас.* Впечатляюще, у вас не отвалилась ни одна конечность! Ну-с, посмотрим, на что сгодится эта проба!', 'Хм, вы не светитесь. Хороший знак.', NULL, NULL, 'Высокомощные радиоактивные осадки', 'Тяжелая освинцованная склянка для проб (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2963, 'Ульдумские чудеса', 'И снова примите мои поздравления, $N! Ваша ульдаманская находка привела всю Лигу исследователей в такое возбуждение! Лига пыталась разгадать тайны найденных вами миниатюрных платиновых дисков. Ваше неожиданное прибытие сюда, в Зал, дает мне возможность сказать вам, что мы, похоже, наткнулись на нечто великое!$B$BИсторик Карник нашел важные сведения по поводу истинного происхождения Долины Стражей в пустыне Танарис. Он хочет поговорить с вами как можно скорее!', 'Поговорите с историком Карником в Зале Исследователей в Стальгорне.', 'Я счастлив, что вы не оставляете интереса к исследованиям, $N! Ваши прирожденные талант и отвага помогут нам приоткрыть завесу таких тайн, что мы и надеяться не смели!$B$BДиски Норганнона из Ульдамана служили хранилищем обширных знаний. Вы, так сказать, только чуть копнули. У Создателей, как говорят, в Азероте имелись и другие хранилища. Это подводит нас к проблеме Ульдума...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2964, 'Новое задание', 'Что сказать, $N… мы зашли в тупик. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьезное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймем тебя и отправим за пластинами.$B$BОб этом необходимо сообщить старшему исследователю; он без сомнения пожелает лично поблагодарить тебя за помощь Лиге.', 'Поговорите со старшим исследователем Магелласом в Стальгорне.', 'Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска. Мы зашли настолько далеко благодаря тебе, $N, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум!$B$BПозволь вручить тебе заслуженный гонорар и небольшую премию. Заглядывай к нам время от времени... Ульдум ждет тебя!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2965, 'Ульдумские чудеса', 'Ах, $N, как удачно, что ты снова $gпришел:пришла: ко мне! Твоя ульдаманская находка вызвала ожесточенные споры среди мудрецов. Я сам только что спорил с друидом, Нарой Буйногривой, когда меня вдруг осенило – ее недавние приключения могут быть весьма важны в смысле определения следующего нашего шага в разгадке этой тайны!$B$BЯ бы хотел, чтобы ты $gпоговорил:поговорила: с ней о ее путешествии в Долину Стражей в пустыне Танарис. Она ждет теба на Вершине Старейшин.', 'Поговорите с Нарой Буйногривой на Вершине Старейшин Громового Утеса.', 'В глубине пустыни Танарис есть место, называемое Долиной Стражей. Эти диски, что ты нашел... в переводе иероглифической надписи на них упоминается место под названием Ульдум. Многие считают, что это миф.$B$BНо я-то знаю, что Ульдум существует. Я была там. Ну... хотя бы рядом постояла.$B$BНо вот в чем загадка, $N – мы думаем, что есть связь между этими дисками и Ульдумом, потому мы хотим, чтобы ты отправился туда.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2966, 'Посмотрим, что будет дальше', 'Мы с Ведуном Искателем Истины хотели бы, чтобы ты $gдоставил:доставила: эти миниатюрные диски к запечатанным воротам Ульдума. Мы... мы не знаем, что может после этого случиться.$B$BДа, мы понимаем, это может показаться рискованным. Но может ведь и ничего не случиться? Может, тебе придется что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойся испытать их и будь $gготов:готова: ко всему.$B$BУзнай, что получится, и возвращайся ко мне. Нам есть много о чем поговорить.', 'Принесите миниатюрные платиновые диски к воротам Ульдума в Танарисе и проверьте, имеют ли диски отношение к воротам.', 'Когда вы прикасаетесь к постаменту, улдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража.$B$B\"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание\".', 'Какой знакомый постамент торчит из горячего песка. Возможно, он тут неспроста...', NULL, NULL, 'Миниатюрные платиновые диски (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2967, 'Возвращение в Громовой Утес', 'Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски.$B$BОбретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Громовой Утес к Наре Буйногривой, сообщить ей о совершенных открытиях.', 'Поговорите с Нарой Буйногривой в Громовом Утесе.', 'Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке.$B$BЕсли нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Не знаю, радоваться такой возможности или ужасаться.$B$BБыть может, нам придется пожертвовать всем ради сохранения глубинных тайн земли, грозящих нам всем великими опасностями, хм, в тайне.', 'Добро пожаловать, $N. Ну как, пригодились диски?', NULL, NULL, 'Миниатюрные платиновые диски (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2968, 'Новое задание', 'Что сказать, $N… мы оказались в тупиковой ситуации. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьезное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймем тебя и отправим за пластинами.$B$BОб этом необходимо сообщить Ведуну Искателю Истины; он без сомнения пожелает лично поблагодарить тебя за услышанный зов.', 'Поговорите с Ведуном Искателем Истины в Громовом Утесе. ', 'Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска. Мы зашли настолько далеко благодаря тебе, $N, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум!$B$BПозволь вручить тебе заслуженный гонорар и немного сверхурочных. Должно покрыть все непредвиденные расходы. Заглядывай к нам время от времени... Ульдум ждет тебя, юноша!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2969, 'Свободу всем живым существам!', 'Гнусные таурены из племени Зловещего Тотема ловят лесных дракончиков, $N! Мы с Джер\'кай понятия не имеем, что они собираются с ними делать, но явно ничего хорошего!$B$BУ нас просто не хватит сил, чтобы прорваться в лагерь и освободить пленных дракончиков, но, может быть, с твоей помощью...$B$BЕсли ты согласишься помочь, и у тебя есть надежные товарищи, отопри клетку вот этим ключом и выпусти бедных зверушек на волю! Только постарайся, чтобы все сумели улететь живыми... Конечно, я тоже буду с тобой! А Джер\'кай останется здесь.', 'Освободите летучих хамелеонов из вольера в лагере Зловещего Тотема с помощью ключа от бамбуковой клетки. Необходимо, чтобы Киндел Лунная Пряжа и как минимум 6 хамелеонов остались живы.У вас в запасе 6 минут. После этого Киндел решит, что пора отступать, и задание останется невыполненным.', 'Слава Элуне! $N, ты настоящий подарок судьбы! Нам с Джер\'Кай в одиночку никогда бы не удалось спасти бедных дракончиков.$B$BПожалуйста, поговори теперь с Джер\'Кай. А мне нужно приготовиться к мести! Если дракончики на свободе, это еще не значит, что таурены не наловят новых! Так что мы с Джер\'Кай собираемся перейти в наступление.', NULL, NULL, NULL, 'Спасите от плена как минимум 6 летучих хамелеонов', 'Ключ от бамбуковой клетки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2970, 'Небольшое возмездие', 'Как тебе уже говорила Киндел, мы с ней собираемся напасть на тауренов из племени Зловещего Тотема. Мы без труда уложим несколько тауренов, не подвергаясь опасности сами, но мы были бы очень рады, если бы и ты $gприсоединился:присоединилась: к нам.$B$BТот лагерь, что внизу, тебе известен, но дальше на восток есть еще несколько. Постарайся причинить тауренам максимальный ущерб. Ну, а после того, как они отведают стрел Киндел и твоего собственного оружия, мы можем встретиться здесь снова.', 'Убейте 12 натуралистов, 10 налетчиков из племени и 6 шаманов из племени Зловещего Тотема, а затем вернитесь к Джер\'кай Лунной Пряже в Фераласе.', 'Да, $N, Кайдел была права насчет тебя: у тебя талант к этому делу! Ты – куда более опытный искатель приключений, чем мы обе. Спасибо, что ты с нами!$B$BЭтот клан Зловещего Тотема куда опаснее остальных тауренов. Подозреваю, что их боятся даже собственные сородичи! $B$BВпрочем, об этом потом.', 'Кайдел нужно время, чтобы подготовиться, но у нас с тобой и так счет идет на десятки! Клан Зловещего Тотема обнаружил наше присутствие, и теперь они закопошились, как гадюки!$B$BОни сделают все, что в их силах, чтобы избавиться от нас. Так что смотри, осторожнее! Теперь, когда ты с нами, они будут охотиться и на тебя.', NULL, NULL, 'Натуралист из племени Зловещего Тотема убито', 'Налетчик из племени Зловещего Тотема убито', 'Шаман из племени Зловещего Тотема убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2972, 'Небольшое возмездие', 'Здесь, в глуши, у нас с Киндел нет особых возможностей тебя вознаградить. Но разумеется, без награды мы тебя не отпустим! Вот, возьми мой перстень с печаткой. Если когда-нибудь окажешься в ветвях Тельдрассила, зайди в храм в центре Дарнаса. Там ты найдешь нашу верховную жрицу, Тиранду Шелест Ветра. Кольцо будет для нее знаком, что с нами все в порядке, и что тебе можно доверять.$B$BМы обе благодарим тебя, $N!', 'Отнесите перстень-печатку Джер\'кай верховной жрице Тиранде Шелест Ветра в Дарнас.', 'Прекрасная история, $N! Мы очень рады, что ты помог не только драконьему племени, но и одной из наших жриц. Джер\'Кай поступила правильно, прислав тебя к нам. Я позабочусь о том, чтобы вернуть ей ее кольцо – в Фералас в ближайшее время отправятся наши разведчики. Пусть заодно разведают и это...$B$BСпасибо тебе еще раз. Чувствуй себя у нас, как дома!', 'Привет тебе, дитя мое! Мы рады видеть в нашем храме столь закаленных искателей приключений. Если у тебя есть время, быть может, ты поделишься парочкой историй с менее опытными странниками? Многим из них наверняка пойдет на пользу твоя мудрость.$B$BОх, прости меня! Как это неучтиво с моей стороны! Ведь ты пришел в наш храм за помощью, а я пристаю к тебе с пустяками... Прости меня, пожалуйста. Чем могут тебе помочь служители Света?', NULL, NULL, 'Перстень-печатка Джер\'кай (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2973, 'Новый сверкающий плащ', 'Приятно познакомиться, $C. Мы с товарищами прибыли сюда, в Фералас, по заданию из Оргриммара.$B$BМоя супруга, Коррин, очень любит новые наряды. Я хочу пошить ей новый плащ из прозрачных крылышек лесных дракончиков. Не согласишься ли ты мне помочь? Те летучие хамелеоны с роскошными крыльями, что мне нужны, водятся к западу от Лагеря Мохаче.', 'Принесите 10 радужных крыльев летучих хамелеонов Кригу Головорубу в Лагерь Мохаче.', 'Отлично, $C! Да, это то, что надо. Этого вполне хватит на плащ для Коррин, а может, и останется! Спасибо тебе.$B$BНу что, надеюсь, охота была не очень опасной? А то ведь Фералас ошибок не прощает.$B$BСпасибо еще раз, $C!', 'Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, $C! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов. $B$BКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!', NULL, NULL, 'Радужное крыло летучего хамелеона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2974, 'Зловещее открытие', 'Как? Таурены, здесь, в этих краях? Да ты шутишь! И как они выглядели?$B$BПлемя Зловещего Тотема! Тебе повстречались именно они. Белгром, один из наших старших, очень ими интересуется... Даже награду за них назначил!$B$BВозвращайся туда, $C! Возвращайся, и принеси мне их рога – чем больше, тем лучше! С племенем Зловещего Тотема шутки плохи, и недооценивать их не стоит. Ступай и перебей их, сколько сможешь. Пусть реки Фераласа побагровеют от их темной крови!', 'Принесите 20 рогов тауренов из племени Зловещего Тотема Кригу Головорубу в лагерь Мохаче.', 'Отличные рога, $C! Молодец! Я заберу их у тебя и сообщу о твоих деяниях Белгрому, как только вернусь в Оргриммар. Ты помог мне уже дважды, и я тебя запомню. Быть может, когда-нибудь и я тебе помогу! Удачи.', 'Клан Зловещего Тотема – злой клан, $C. Я серьезно. Если тебе удалось обнаружить их гнездо, самое лучшее – нанести упреждающий удар, прежде, чем они попытаются захватить наши владения и сравнять с землей наши деревни.', NULL, NULL, 'Рог таурена из племени Зловещего Тотема', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2975, 'Огры Фераласа', 'Присутствие огров из клана Гордунни не может оставаться незамеченным. Оглядись вокруг, $N! Само их существование уродует эту землю. Необходимо оттеснить их назад, пока они не продвинулись еще дальше в Фералас.$B$BСтупай на север вдоль реки, и увидишь их заставу. Задай им жару, $N! Пусть видят, что им тут не рады.', 'Убейте 10 огров из клана Гордунни, 10 огров-магов из клана Гордунни и 5 громил из клана Гордунни по просьбе Роки Орхан из Лагеря Мохаче.', 'Отлично, $N! Еще немного, и эта земля исцелится. Мы не сдадимся!', NULL, NULL, NULL, 'Огр из клана Гордунни убито', 'Огр-маг из клана Гордунни убито', 'Громила из клана Гордунни убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2976, 'Зловещее открытие', 'Чего еще?$B$BАх, я говорил о награде? Ну что ж, поделом мне – пора бы и научиться держать язык за зубами…$B$BНу, в конце концов, это ты $gсделал:сделала: всю работу, тебе и награда полагается. Забирай рога. Я велю упаковать их в ящик. Отыщи на Аллее Чести Белгрома Каменную Булаву. Он расспросит тебя о том, что ты $gвидел:видела:, и выдаст заслуженную награду.$B$BПока, $C! Еще раз спасибо за все.', 'Отнесите ящик с рогами тауренов из племени Зловещего Тотема Белгрому Каменной Булаве в Оргриммар.', 'Клан Зловещего Тотема?! Интересно... Так говоришь, ты наткнулся на них во время охоты в Фераласе? В самом деле?$B$BТвои новости очень важны для нас, $C. Расскажи все как было, а я пока отсчитаю твою награду.$B$BДа, и пока ты не ушел: имей в виду, я тебе очень признателен за эту информацию.', 'Поживей, $C! У меня сегодня еще много дел.', NULL, NULL, 'Ящик с рогами тауренов из племени Зловещего Тотема (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2977, 'Возвращение в Стальгорн', 'Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски.$B$BОбретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Стальгорн и сообщить Лиге исследователей о совершенных открытиях.', 'Поговорите с историком Карником из Стальгорна.', 'Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке.$B$BЕсли нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Только представь – у нас появится возможность исследовать место, где трудились Создатели, не роясь в земле!$B$BХотя землю рыть тоже неплохо... вполне...', 'Добро пожаловать, $N. Ну как, пригодились диски или дело ничем не закончилось?', NULL, NULL, 'Миниатюрные платиновые диски (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2978, 'Свиток Гордунни', 'Вы берете в руки запачканный свиток и обнаруживаете, что на нем изображена какая-то встреча или церемония. Рока Орхан наверняка заинтересуется этим свитком и тем, что он означает для Гордунни...', 'Отнести свиток Гордунни Роке Орхан в Лагерь Мохаче.', 'Этот свиток... Ты нашел его в Поселении Гордунни?', 'Что это?', NULL, NULL, 'Свиток Гордунни (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2979, 'Темный обряд', '$N, похоже, они готовят какой-то темный обряд! Насколько я понимаю, проводить его будут маги-лорды из клана Гордунни.$B$BОтыщи одного из таких магов-лордов, и добудь у него магическую сферу.$B$BВ такой сфере сокрыта великая мощь, и она поможет нам больше узнать об этом обряде и о магии, которой владеют Гордунни.', 'Добудьте сферу Гордунни по просьбе Роки Орхан из Лагеря Мохаче.', 'Эта сфера поможет нам получить информацию о Гордунни... И мы используем эту информацию, чтобы разгромить их!', 'Нам нужно понять, почему Гордунни здесь, $N.', NULL, NULL, 'Сфера Гордунни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2980, 'Огры Фераласа', 'Теперь, когда ты $gпоказал:показала: себя настоящим бойцом, я надеюсь, тебе хватит мужества выполнить и следующее задание.$B$BОтправляйся в Высокогорные дебри, к юго-западу отсюда. Это земля, которая некогда принадлежала ночным эльфам. Там увидишь заброшенные и разрушенные здания. Когда увидишь среди руин засохшие деревья и оскверненную почву, знай: там и живут Гордунни. Прогони их прочь!$B$BЭти огры куда опаснее тех, с которыми тебе, $N, доводилось сталкиваться прежде. Так что будь осторожнее!', 'Убейте 10 шаманов из клана Гордунни, 10 чернокнижников из клана Гордунни и 5 извергов из клана Гордунни по просьбе Роки Орхан из Лагеря Мохаче.', 'Да, $N, ты воистину надежный и верный союзник!', NULL, NULL, NULL, 'Шаман из клана Гордунни убито', 'Чернокнижник из клана Гордунни убито', 'Изверг из клана Гордунни убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2981, 'Опасность в Фераласе', 'Что, $C, хочешь показать себя? Фералас для этого самое подходящее место! Главная сила там – племя огров, именуемое Гордунни, и их становится все больше и больше. Их надо остановить, пока они не вытеснили из Фераласа нас!$B$BВ Лагере Мохаче в Фераласе живет моя знакомая воительница по имени Рока Орхан. Ступай к ней. Она подробнее расскажет тебе о создавшемся положении.', 'Поговорите с Рокой Орхан в Лагере Мохаче.', 'А, тебя прислал Белгром! Ты как нельзя более вовремя, $R.$B$BЯ расскажу, что у нас тут творится, а ты уж решай, по зубам ли тебе это... Хотя если тебя прислал Белгром, значит, сомневаться в твоей доблести не приходится.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2982, 'Высокогорные дебри', 'Места там опасные, и все же мы с Троясом исследовали руины в лесах Фераласа.$B$BНо в последнее время Трояс ходил в Высокогорные дебри в одиночку. Я серьезно за него беспокоюсь! Эти земли захвачены ограми из клана Гордунни, а они не дают спуску тем, кто забредает на их территорию!$B$BЯ надеялась, что вы, может быть, согласитесь побывать в развалинах на юго-востоке и перебить часть огров? Тогда эти места станут не такими опасными. Я вам буду очень признательна!', 'Убейте 8 чернокнижников из клана Гордунни, 8 шаманов из клана Гордунни и 8 громил из клана Гордунни по просьбе Ангелас Лунный Бриз.', 'О, как я вам благодарна!$B$BТолько, пожалуйста, Троясу об этом ни слова!', NULL, NULL, NULL, 'Чернокнижник из клана Гордунни убито', 'Шаман из клана Гордунни убито', 'Громила из клана Гордунни убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2983, 'Зов Огня', 'Много времени прошло с тех пор, как ты $gпрошел:прошла: последнее испытание, $N. Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу! Стихия огня – твоя, если только ты $gготов:готова: заплатить за это знание.$B$BОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!', 'Найдите в Степях Кранала Фисса.', 'Что, тебя Сварт прислал, да?$B$BНу, на Сварта положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня.$B$BДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение, Сонноекопыто. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2984, 'Зов Огня', 'Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание, $N! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты $gготов:готова: платить за это.$B$BОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если промахнешься, можешь очутиться в землях ночных эльфов!', 'Найдите в Степях Кранала Фисса.', 'Что, тебя Нарм прислал, да?$B$BНу, на Нарма положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня.$B$BДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение, $N. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2985, 'Зов Воды', 'Похоже, ты $gготов:готова: к новому испытанию, $N. Ты $gпроявил:проявила: немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.$B$BОтыщи Ислену Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $N.', 'Отыщите в Степях Ислену Заклинательницу Воды.', 'Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.$B$BПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2986, 'Зов Воды', 'Много воды утекло со времени последнего испытания. Ты $gпроявил:проявила: немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.$B$BОтыщи Ислену Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $N.', 'Отыщите в Степях Ислену Заклинательницу Воды.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2987, 'Кобальт Гордунни', 'Я только что прибыл сюда, в Фералас. Я слышал, что у огров из клана Гордунни, обитающих в здешних чащобах, попадаются интересные минералы. Неизвестно, к чему они им, но уж, разумеется, по доброй воле они ими делиться не собираются! Наоборот, норовят спрятать, чтобы бизнесменам вроде меня труднее было до них добраться.$B$BЕсли вы согласитесь помочь, то вот вам моя лопатка. Ступайте в Поселение Гордунни к северу отсюда и накопайте мне образцов кобальта Гордунни. Ищите: где блеснет синим, там и ройте!', 'Добудьте 12 образцов кобальта Гордунни для Орвина Гиззмика из Лагеря Мохаче.', 'Отлично! Захвачу это с собой, когда снова отправлюсь в путь. Я наверняка сумею найти кого-то, кто выложит за эти образцы кругленькую сумму!$B$BБлагодарю вас, $N. Вот, возьмите за труды.', 'Ну что, вперед, за работу!$B$BА мне надо много где побывать, много кого повидать... Время – деньги!', NULL, NULL, 'Кобальт Гордунни', 'Лопата Орвина (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2988, 'Тролльи клетки', 'Пропал сын нашего самого лучшего грифона! Наследник Быстрокрыла, Остроклюв, пропал несколько дней назад, когда охотился вместе с родителями. Я думаю, его похитили тролли!$B$BПомогите нам! Остроклюва могут держать в клетке в одной из двух деревенек Сухокожих.', 'Проверьте клетки в двух деревнях Сухокожих и возвращайтесь к дрессировщику грифонов Разящему Когтю.', 'Остроклюва в деревнях нет? Хм... это плохо. От этого грифона должно было произойти их следующее поколение, и если он погибнет, то наш флот понесет огромные потери...', NULL, NULL, NULL, 'Проверьте первую клетку', 'Проверьте вторую клетку', 'Проверьте третью клетку', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2989, 'Алтарь Зула', 'У троллей из племени Сухокожих Остроклюва нет... Значит, его забрали тролли из племени Порочной Ветви. Поищи детеныша грифона у алтаря Зула – это на западной границе территории этого племени.', 'Осмотрите вершину Алтаря Зула и возвращайтесь к укротителю грифонов Разящему Когтю.', 'Остроклюва там не было? Это плохая, но и хорошая новость...$B$BХорошо, что его не было на алтаре Зула – там тролли из клана Порочной Ветви совершают свои жертвоприношения.$B$BСпасибо за помощь, но, боюсь, вам предстоит еще одна, более тяжелая работа.', 'Скорее, $N! Племя Порочной Ветви держит у себя Остроклюва, нужно немедленно освободить его!', NULL, NULL, 'Исследовать локацию', 'Осмотреть алтарь Зула', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2990, 'Тадиус Мрачная Тень', 'Отнеси это перо Тадиусу Мрачной Тени, прорицателю. Он давно ушел из Заоблачного Пика в поисках темных знаний, но в душе он все еще с нами, с кланом Громового Молота!$B$BВозможно, он поможет нам разыскать Остроклюва.$B$BЭто перо нашли в гнезде, где был детеныш грифона, и если ты отдашь его Тадиусу, то он сможет при помощи своего прорицания узнать, где находится сам Остроклюв.$B$BУдачи, $N. Тадиуса можно найти в Выжженных землях, в башне магов в крепости Стражей Пустоты.', 'Принесите перо Остроклюва Тадиусу Мрачной Тени в Выжженные земли.', 'Ах, да. Это перо грифона, но не обычного, а великого, способного на великие дела... Если, конечно, он доживет до зрелого возраста.$B$BХотите найти его? Что ж, тогда слушайте, храбрый $С.', '$N, вы пришли с подарком?', NULL, NULL, 'Перо Остроклюва (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2991, 'Медальон Некрума', 'Я найду вам вашего грифона, но вначале вы должны кое-что сделать для меня. В Зул\'Фарраке живет тролль по имени Некрум Кишкожуй, и мне очень-очень нужен его медальон, для изучения. Принесите мне тот медальон, а я найду вам Остроклюва.$B$BЗул\'Фаррак лежит за океаном, на западе, в пустыне Танарис.', 'Принесите медальон Некрума Тадиусу Мрачной Тени в Выжженные земли.', 'А, медальон Некрума. Говорят, он дарует троллям удивительное долголетие, но за определенную цену. Надеюсь, мне удастся заполучить силу этого медальона и избежать его... побочных эффектов.$B$BВы оказали мне огромную услугу, $N. Мне осталось лишь выполнить свою часть соглашения.', 'Вы достали медальон Некрума, $N? В нем сокрыта сила, которую мне не терпится изучить.', NULL, NULL, 'Медальон Некрума', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2992, 'Прорицание', 'Посторонитесь-ка, мне нужно место, чтобы выполнить ритуал прорицания. Я установлю связь между этим пером и его владельцем, а потом попытаюсь найти и самого Остроклюва.$B$BЕсли все пойдет по плану, то должно получиться, а если нет... Вы, на всякий случай, закройте глаза.', 'Дождитесь, пока Мрачная Тень не закончит ритуал прорицания.', 'Ритуал прошел успешно. Я видел Остроклюва и могу сказать, где его найти.', NULL, NULL, NULL, 'Дождаться, пока Мрачная Тень закончит', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2993, 'Назад во Внутренние земли', 'Остроклюва держат в клетке, на самом верху Джинта\'Алора, что во Внутренних землях. Ключ от его клетки находится у коварной жрицы племени Порочной Ветви Ведьмисы.$B$BНу вот, я закончил. Желаю удачи, $N.', 'Поговорите с укротителем грифонов Разящим Когтем.', 'Вы поговорили с Мрачной Тенью? Что он сказал?$B$BЧто? Остроклюв у троллей Порочной Ветви? Это немыслимо! Мы непременно должны его спасти!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2994, 'Спасение Остроклюва', 'Мы должны спасти Остроклюва!$B$BПробейся в верхнюю часть Джинта\'Алора, отбери ключ у коварной жрицы Ведьмисы, а потом найди и освободи Остроклюва!', 'Пробейтесь в верхнюю часть Джинта\'Алора, убейте коварную жрицу Ведьмису, возьмите у нее ключ от клетки и освободите Остроклюва.', 'Быстроветр и Острокоготь минуту назад вернулись вместе со своим детенышем, и теперь от него не отходят. Ох, как гляну на них, аж слеза прошибает...$B$BЯ даже не знаю, чем мы можем отблагодарить вас, $N. Грифоны Заоблачного Пика и их всадники навсегда запомнят ваше имя.', NULL, NULL, NULL, 'Откройте клетку Остроклюва', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2995, 'Линии связи', 'Сторожка Кель\'Данил – центр сообщения высших эльфов Внутренних земель. Их посланники пытаются установить отношения с другими расами и делятся с ними сведениями о троллях из племени Сухокожих, обитающих в южной части Внутренних земель. Все документы, связанные с этим, хранятся в сторожке.$B$BМы не хотим, чтобы Высокодолье заключало союзы с другими народами, $N.$B$BУничтожь документы Высокодолья. Есть мнение, что рукописи не горят… у тебя есть шанс проверить, так ли это.', 'Оран Змеиные Кольца из Подгорода просит вас отправиться во Внутренние земли и сжечь отчет Высокодолья, заметки Высокодолья и записи Высокодолья.', 'Великолепно. Пока эльфы будут восстанавливать утраченную информацию, мы сможем еще навсегда отрезать их от остального мира…', NULL, NULL, NULL, 'Сожгите записи Высокодолья', 'Сожгите заметки Высокодолья', 'Сожгите отчет Высокодолья', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2996, 'В поисках Страхада', 'Я многому тебя научил, теперь тебе нужен новый наставник. Он живет в Кабестане, его зовут Страхад. Он человек, но он отнюдь не слаб. Он невелик ростом, но силен! Ты уже можешь вызывать более могущественных существ, и он научит тебя этому. Ступай к нему. Он живет в Кабестане, над портом, рядом с башней.', 'Поговорите в Кабестане со Страхадом Фарсаном.', 'A busy day in Ratchet, isn\'t it? How I enjoy watching the toil of a port city. So much mystery, so much adventure... so much ignorance.$B$BIs that hatred I see in your eyes, $N? Good, we will put that to good use.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2997, 'Фолиант Божественности', 'Привет, $N. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, посети Стальгорн и поговори с одной из самых почитаемых наших сестер – Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от тебя.$B$BТы можешь найти ее на верхнем этаже Зала Тайн, что в Палатах Магии. Удачи тебе, $N.', 'Поговорите с Тизой Кузнебой в Стальгорне.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2998, 'Фолиант Божественности', 'Приветствую тебя, $gбрат мой:сестра моя:. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе. Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать.$B$BНа твоем месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдется на это время. Ищи его в Соборе Света: там он проводит большую часть времени.', 'Поговорите с Даторианом Раллом в Штормграде.', 'Как красив Штормград, не правда ли?..$B$BТвой визит в это время более чем уместен, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (2999, 'Фолиант Божественности', 'Привет, $N. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, поднимись наверх и поговори с одной из наших самых почитаемых сестер – Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что от тебя ожидается.', 'Поговорите с Тизой Кузнебой в Стальгорне.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3000, 'Фолиант Божественности', 'Привет, $N. Я знаю, что ты рук не покладаешь, помогая жителям Азерота, но когда тебе выпадет свободная минутка, вернись в Стальгорн и поговори с Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые дворфские паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от всех нас.$B$BYТы можешь найти ее на верхнем этаже Зала Тайн, что в Палатах Магии.', 'Поговорите с Тизой Кузнебой в Стальгорне.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3001, 'В поисках Страхада', 'Я многому тебя научил, и теперь тебе нужен новый наставник. Он живет в Кабестане, его зовут Страхад. Это человек, но отнюдь не слабый. Также у нас нет причин смотреть на него как на потенциального врага... по крайней мере, пока что. Он обладает силой и заслуживает уважения. Я чувствую в тебе готовность призывать более могущественных существ, и он может обучить тебя этому.', 'Поговорите со Страхадом Фарсаном в Кабестане.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3002, 'Сфера Гордунни', 'Я, конечно, хорошо знаю своих врагов, и все же я – только воительница, $N. Я даже приблизительно не представляю, на что способна эта сфера.$B$BНо я знаю одного мага в Оргриммаре, который сможет рассказать нам о ней больше. Отнеси сферу к нему!', 'Отнести сферу Гордунни Утель\'наю в Пристанище Темнотерна в Оргриммаре.', 'Да, $N, занятная вещица…$B$BЭтот шар весьма могуществен, но и очень опасен!', 'Что это у тебя, $R?', NULL, NULL, 'Сфера Гордунни (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3022, 'Не кантовать!', '$N, я вижу, как ты $gпредан:предана: сему достойному делу. Да, конечно, ты можешь мне помочь!$B$BОтнеси этот ящик с яйцами Эреласу Янтарному Небу. Он друид, и заботится об этих яйцах, помогает вылупиться маленьким гиппогрифам и обучает их. Его можно найти в Тельдрассиле, в маленькой деревушке Рут\'теран на юге.', 'Отнесите тщательно упакованный ящик Эреласу Янтарному Небу в деревню Рут\'теран.', 'Спасибо за помощь, $N. Если бы не мы, гиппогрифы уже вымерли бы. Впрочем, тебе случалось бывать в Фераласе, и ты знаешь не понаслышке, как опустошили землю Гордунни.$B$BЧто ж, ты видишь, как я занят. Можешь идти.$B$BЕще раз спасибо, $N.', 'Еще одна посылочка от Гургл?', NULL, NULL, 'Бережно упакованный ящик (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3042, 'Троллье месиво', 'Тролли племени Песчаной Бури в Зул\'Фарраке делают состав для закалки из песчаника, и я бы не отказался заполучить себе немного этого состава. Он весьма ценится мастерами, так что если ты принесешь мне достаточно, то и вознаграждение будет щедрым.$B$BЗул\'Фаррак находится к северо-западу от Прибамбасска. Удачи!', 'Принесите 20 фиалов с Тролльим месивом.', 'Отлично! Так много и все отборные! Этот запас я буду расходовать долго…$B$BБлагодарю тебя, $N. Прими это в качестве оплаты.', 'Принес?', NULL, NULL, 'Троллье месиво', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3062, 'Темное сердце', 'Эдана Коготь Ненависти – королева гарпий из стаи Студеных Ключей, что обитают в руинах к западу отсюда. Эдана – это воплощенное зло. Я слышал, что сердце у нее каменное. Она не ведает иных чувств, кроме ненависти, которую питает ко всему живому. Сразись с Эданой и принеси мне ее темное сердце!$B$BЯ слышал, что гарпии носят при себе рог. Если затрубить в него у камней Когтя Ненависти, в северной части руин, появится царица.$B$BПредставь, как она удивится, когда обнаружит, что это был зов не ее сородичей, но самой смерти!', 'Принесите темное сердце Эданы Коготь Ненависти Тало Терновому Копыту.', 'Ну, вот теперь я точно знаю, что Эдана мертва! А это сердце я оставлю себе на память о твоем подвиге, $N. Спасибо тебе!', 'Ненависть, которую распространяет вокруг себя Эдана, необходимо остановить!', NULL, NULL, 'Темное сердце Эданы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3063, 'Месть стае Студеных Ключей', 'В свое время я был закаленным охотником. Не было на свете такого зверя, которого я бы боялся. До тех пор, пока…$B$BЯ был один в лесу, точил свой клинок после жаркой битвы, и тут на меня напали из засады! Меня окружили гарпии, я еле сумел добраться до безопасного места.$B$BЯ еще и теперь как наяву слышу их вопли...$B$BИ с тех пор я уже никогда не мог стать прежним. В душе у меня кипит ненависть – все эти годы я жажду сквитаться с ними!$B$BГарпии из стаи Студеных Ключей водятся к западу отсюда. Отомсти за меня, $N.', 'Убейте 4 гарпий, 4 разбойниц, 4 призывательниц ветра и 4 убийц из стаи Студеных Ключей по просьбе Тало Тернового Копыта.', 'Спасибо тебе, $N. Ты возвращаешь покой душе старого таурена.', NULL, NULL, NULL, 'Гарпия из стаи Студеных Ключей убито', 'Разбойница из стаи Студеных Ключей убито', 'Душегубка из стаи Студеных Ключей убито', 'Призывательница ветров из стаи Студеных Ключей убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3065, 'Простая табличка', 'А, $N! Тебе тут пергамент прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить. Он обычно сидит в тени у входа в Логово.', 'Прочтите простую табличку и поговорите с Франгом в долине Испытаний.', 'Наша долина – подходящее место, чтобы упражняться в воинских навыках. Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готов продолжать обучение – возвращайся ко мне. Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!', 'А, еще один $R в наших рядах! Ты мне подходишь.$B$BС топором тебе пока не управиться, но копье тоже сгодится.$B$BДобро пожаловать в долину Испытаний!', NULL, NULL, 'Простая табличка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3082, 'Каменная табличка', 'А, $N! Тебе тут табличку прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Джен\'шан, наставницы охотников. Она хочет с тобой поговорить.', 'Поговорите с Джен\'шан в долине Испытаний. ', 'Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники. Не забывай об этом, а Джен\'шан не забудет о тебе.$B$BДжен\'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают. И тебя ждет большое будущее – помни это!$B$BБудет надо – приходи к Джен\'шан. Она тебя научит всему, чему сможет, когда ты будешь готов.', 'Джен\'шан видит перед собой могучего охотника! Духи довольны.$B$BТропа охотника – один из древнейших путей этого мира. Орда обратилась к нам, когда пыталась выжить на Азероте. Ее воины попросили обучить их, открыть им наши тайны. Да, они уже были сильны: среди них были и грозные шаманы, и отважные воины. Но путь охотника еще не был их путем...', NULL, NULL, 'Каменная табличка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3083, 'Табличка с письменами', 'А, $N! Тебе тут табличку прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить.', 'Прочтите табличку с письменами и поговорите с Руагом в долине Испытаний.', '', NULL, NULL, NULL, 'Табличка с письменами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3084, 'Руническая табличка', 'А, $N! Тебе тут табличку прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить.', 'Поговорите с Шикрик в долине Испытаний.', 'Ты, вероятно, уже знаешь, что могущество нам дают стихии. Огонь, земля, вода и воздух – вот наши орудия.$B$BНаша сила исходит от духов предков. Мы должны вести наш народ. Для городов и деревень, где мы бываем, мы должны стать тем же, чем стал Тралл для всей Орды. У нас будут просить совета и защиты. Но чтобы этого добиться, тебе потребуется немало трудов. Когда ты почувствуешь, что у тебя накопилось достаточно сил, приходи ко мне, и я научу тебя всему, чему смогу.', 'А, $N! Рада видеть тебя здесь. У меня немало дел, и учеников хватает, но каждый раз, как ко мне является кто-то из твоего племени, я чувствую, что круг замкнулся: ведь когда-то я сама училась у одного из ваших шаманов!', NULL, NULL, 'Руническая табличка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3085, 'Освященная табличка', 'А, $N! Тебе тут табличку прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Кен\'джая, наставника жрецов. Он хочет с тобой поговорить.', 'Прочтите освященную табличку и поговорите с Кен\'джаем у Логова в долине Испытаний.', 'Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе все лучше и лучше... В какой-то момент тебе поможет старый Кен\'джай! Приходи потолковать с мной, когда будешь готов. И если духи согласятся, мы научим тебя кое-чему еще... но только если они согласятся!$B$BНу, ступай, потолкуй со другими здешними жителями. И про меня не забывай.', 'А-а, ты здесь! Хорошо-хорошо! Духи предупреждали меня, что скоро ты явишься повидаться с Кен\'джаем. Я рад приветствовать тебя в долине Испытаний. Это место недолго будет тебе домом, но постарайся научиться здесь всему, чему можно.', NULL, NULL, 'Освященная табличка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3086, 'Табличка с тайными знаками', 'А, $N! Тебе тут табличку прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Май\'ах, наставницы магов. Она хочет с тобой поговорить.', 'Прочтите табличку с тайными знаками и поговорите с Май\'ах у входа в Логово в долине Испытаний.', 'Да, $N, скоро ты станешь очень могущественным! И все это узнают... некоторые – на собственной шкуре!$B$BНо берегись! Бойся не орков, не эльфов и не дворфов. Бояться надо тех, кого не увидишь простым глазом. Магия могуча. И иногда заставляет творить то, чего не хочется. А иногда заставляет считать себя сильнее, чем ты есть. Будь терпеливее. Будь умнее.$B$BКогда решишь, что готов учиться, возвращайся к Май\'ах. Она тебя всему научит, не беспокойся!', 'Ага, $N, ты уже нравишься Май\'ах! Неплохо, неплохо. Уважай Май\'ах, и Май\'ах будет уважать тебя. Ну, хватит про это. Ты здесь, чтобы учиться магии, а не слушать болтовню Май\'ах.$B$BЧему Май\'ах тебя не сможет научить, так это одному: как остановить демонов.', NULL, NULL, 'Табличка с тайными знаками (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3087, 'Пергамент с письменами', 'А, $N! Тебе тут пергамент прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Джен\'шан, наставницы охотников. Она хочет с тобой поговорить.', 'Прочтите пергамент с письменами и поговорите с Джен\'шан в долине Испытаний.', 'Когда мы закончим беседу, поговори с остальными обитателями долины. Они будут просить тебя что-нибудь сделать для них – и каждое такое задание будет для тебя проверкой на прочность.$B$BНаберешься мудрости и опыта – приходи к Джен\'шан, она научит тебя новым приемам и навыкам. Возвращайся к Джен\'шан как можно чаще.', 'А, вот и ты! Хорошо. Дженшан тебя ждала.$B$BМногие думают, что путь охотника прост, но Джен\'шан тебе скажет: это неправда. На то, чтобы совладать со зверями Дуротара и других земель, нужно не меньше искусства, чем на то, чтобы плести чары или говорить с предками.$B$BБыть может, стрелять из лука или ружья не так опасно, как применять заклинания, но твоим врагам от этого будет не легче.', NULL, NULL, 'Пергамент с письменами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3088, 'Исписанный пергамент', 'А, $N! Тебе тут пергамент прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить.', 'Прочтите исписанный пергамент и поговорите с Руагом в долине Испытаний.', 'Клан Изувеченной Длани просил меня позаботиться о тебе. Они хотят, чтобы я обучил тебя и сообщал тебе о том, что им нужно. Даже если ты пока не стремишься им помогать – хотя это было бы глупо с твоей стороны, – я обучу тебя всему, чему смогу... за умеренную плату. Возвращайся ко мне, когда решишь, что готов, и мы посмотрим, чему можно тебя научить.', 'Тс-с, тише! Не доверяю я этому Нартоку. С тем, кто норовит забиться в пещеру глубже меня, лучше не связываться.$B$BНадеюсь, тебе без труда удалось меня отыскать?', NULL, NULL, 'Исписанный пергамент (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3089, 'Рунический пергамент', 'А, $N! Тебе тут пергамент прислали, пока тебя не было.$B$BПрочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить.', 'Прочтите рунический пергамент и поговорите с Шикрик в долине Испытаний.', 'Ты станешь тем, через кого говорят предки. Сила стихий будет в твоей власти – достаточно лишь будет протянуть руку. Внести смятение в ряды врагов будет проще простого, а исцелять союзников станет так же просто, как дышать. Помни об этом, когда встретишься с новыми испытаниями. Возвращайся ко мне, если понадобится. Я буду учить тебя новым заклинаниям и наставлю на верный путь, когда ты будешь готов.', 'А, пришел наконец-то! А я уж думать начала, долго ли мне тебя еще ждать. Я отправила пергамент довольно давно, но не была уверена, что его тебе доставили.$B$BНу ладно, довольно болтать. Ты здесь потому, что был избран стать духовным наставником нашего народа.', NULL, NULL, 'Рунический пергамент (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3090, 'Гниющий пергамент', 'А, $N! Тебе тут пергамент прислали, пока тебя не было.$B$BЯ лично стараюсь не иметь дела с чернокнижниками, однако ты его все-таки прочитай, когда время будет. Это, кажется, от твоего нового наставника, Нартока. Он хочет с тобой поговорить.', 'Прочтите гниющий пергамент и поговорите с Нартоком в Логове в долине Испытаний.', 'Теперь и ты в наших рядах! Но не обманывайся, $N. Да, ты имеешь доступ к могуществу, которому многие завидуют, но это не означает, что к тебе будут относиться с почтением. Тралл пускает нас в Оргриммар, ведь мы его сородичи – а иначе мы стали бы такими же жалкими, как люди, что держали его в рабстве. И все же будь осторожен. Да, в твоих руках могущество, но если будешь глуп, – погибнешь.$B$BПонадобятся новые заклинания – приходи ко мне.', 'Ага, вот и ты... тебя никто не заметил по дороге? Это хорошо.$B$BНаш мир полон глупцов, $N. Даже у великого Тралла есть свои недостатки. Он отказывается от могущества, которое необходимо, чтобы полностью подчинить эти земли! Мы ведь уже не марионетки порождений Пустоты. Мы сами себе господа. Мы горды и могущественны!', NULL, NULL, 'Гниющий пергамент (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3091, 'Простая записка', 'Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника воинов Харутта. На твоем месте я бы прочитал ее поскорее.', 'Прочтите простую записку и поговорите с Харуттом Громовым Рогом в Лагере Нараче.', 'Каждый из нас играет свою роль в племени. Каждый из нас должен проходить одни и те же обряды. Никогда не позволяй гордыне ослепить тебя и заставить думать иначе.$B$BЯ тут обучаю новых воинов, желающих снискать славы в битве и последовать по пути своих предков. Возвращайся ко мне, когда будешь готов, и я научу тебя всему, что умею. Иди, и да пребудет с тобой благословение племени, $N!', 'А, вот наконец-то и ты, $C. Я не солгал тебе в записке, $N. Мы тоже таурены особой породы, не как шаманы и друиды нашего племени. Мы не менее важны. Мы те, кто защищает границы, охотится на кентавров и воюет.', NULL, NULL, 'Простая записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3092, 'Нацарапанная записка', 'Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника охотников Ланко. На твоем месте я бы прочитал ее поскорее.', 'Прочтите нацарапанную записку и поговорите с Ланко Дальнострелом на Плато Красного Облака.', '', NULL, NULL, NULL, 'Нацарапанная записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3093, 'Руническая записка', 'Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставницы шаманов Милы. На твоем месте я бы прочитал ее поскорее.', 'Прочтите руническую записку и поговорите с Милой Рассветной Странницей в Лагере Нараче.', 'Мы еще не раз встретимся с тобой, и каждый раз ты будешь уходить от меня чуть более сильной... чуть более подготовленной. Твой дух будет пылать подобно Неугасимому пламени.$B$BА теперь ступай, Сновавайп, испытай себя! Возвращайся, если тебе понадобится моя помощь.', 'И вот ты пришла ко мне, быстрее, чем вода падает с неба. Мне приятна твоя поспешность. Она говорит о том, что ты понимаешь, как важен наш разговор и твое присутствие здесь. Я понимаю стихии и говорю с духами нашего народа, не стремясь при этом выбиться в лидеры. Я смогу научить тебя тому же.', NULL, NULL, 'Руническая записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3094, 'Зеленая записка', 'Привет, $N! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника друидов Гарта. На твоем месте я бы прочитал ее поскорее.', 'Прочтите зеленую записку и поговорите с Гартом Вестником Туманов в Лагере Нараче.', 'Хоть у нас и ночных эльфов есть что-то общее, не стоит ждать от них хорошего отношения. Гордыня ослепляет их, но это не твоя забота. Сосредоточь свой разум на уроках Матери-Земли, а я научу тебя тому, что знаю, когда ты будешь готов. $B$BПриходи ко мне почаще, Шаэлрит. Ты узнаешь, что Мать-Земля дарует величайшие способности тем, кто полностью посвящает себя ее учению.', 'Вот и ты! Очень хорошо. Духи предков по всему Мулгору вдруг стали беспокойны, и никто не может понять, что послужило этому причиной. Отныне ты всегда должен будешь прислушиваться к духам природы и становиться их воплощение. Помни это.', NULL, NULL, 'Зеленая записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3095, 'Простой свиток', 'А, вот и ты! Пока ты $gразбирался:разбиралась: с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника воинов Даннала. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', 'Прочитайте простой свиток и поговорите с Данналом Штерном в Могильнике.', 'Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь. Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты был достойным бойцом. $B$BА теперь иди и проверь свои боевые навыки. Многое ты поймешь сам со временем, а кое-что я и вовсе не вправе поведать тебе. Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом.', 'Итак, ты прибыл. Хорошо. Я слышал, что еще нескольким удалось избежать \"смерти\" и они направляются сюда. Возможно, подобная живучесть пригодится им и в будущем. $B$BБлагодари Сильвану за свою свободу... свободу тела и духа. Хотя тебя по-прежнему мучают чума и ее последствия, ты можешь теперь передвигаться свободно – на вид ты в полном порядке.', NULL, NULL, 'Простой свиток (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3096, 'Зашифрованный свиток', 'А, вот и ты! Пока ты $gразбирался:разбиралась: с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', 'Прочитайте зашифрованный свиток и поговорите с Давидом Триасом в Могильнике.', 'Большую часть времени я провожу здесь, в таверне, присматриваясь к новым лицам и новым возможностям. Не суй свой нос, куда не следует, а я сделаю все возможное, чтобы научить тебя кой-чему. Возвращайся ко мне, когда захочешь – посмотрим, будешь ли ты готов выучить пару новых трюков.', 'Значит, тебе все же удалось!.. Отлично, с течением времени нам требуется все больше разбойников. Тенеохотники, возможно, захотят отыскать тебя, когда решат, что настал нужный момент, так что не пропадай и не делай ничего такого, о чем мог бы потом пожалеть. Им нужны способные агенты... а не жалкие карманники и дураки.', NULL, NULL, 'Зашифрованный свиток (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3097, 'Священный свиток', 'А, вот и ты! Пока ты $gразбирался:разбиралась: с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', 'Прочитайте священный свиток и поговорите с темным священником Дьюстеном в церкви Могильника.', 'Есть лишь одно, что ты должен знать: мы выжили благодаря лишь силе воли. В нас есть вера, отличающая нас от других, и с помощью нашей силы мы сможем в корне изменить весь Азерот. Слабые придут, чтобы положиться на тебя. Прокаженные будут звать тебя Господином. А невежественный будет просить тебя об обучении. Моя обязанность – обеспечить тебя необходимыми инструментами, чтобы, когда придет время, ты был готов. По мере накопления опыта навещай меня. Я научу тебя большему, когда настанет время.', 'Итак, меж огня, чумы, беспорядков и еще худших бед, еще один \"верный\" стучит в мою дверь. Что ж, позволь поприветствовать тебя, $C. И дай мне минутку, чтобы я объяснил тебе пару вещей, прежде чем ты решишь, что пора отправляться на поиски того, что притягивает тебя: Священный Свет позабыл о тебе, духи твоих предков – всего лишь сказки, а создания Пустоты не желают тебя. $B$BТы понимаешь, о чем я?', NULL, NULL, 'Священный свиток (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3098, 'Свиток, покрытый письменами', 'А, вот и ты! Пока ты $gразбирался:разбиралась: с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', 'Прочитайте свиток, покрытый письменами, и поговорите с Изабеллой в церкви Могильника.', 'You must return to me often if you are to become powerful enough to destroy those who would oppose us. The rules of magic still apply to you, $N. You will still find corruption follows you like hungry wolves in the night. You will find its caress is not unlike an addiction, an old lover still wanting to be by your side. But these things can be staved off. These things will only control you if you allow them to.$B$BGo now, return to me when you\'ve grown more powerful.', NULL, NULL, NULL, 'Покрытый письменами свиток (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3099, 'Нечистый свиток', 'А, вот и ты! Пока ты $gразбирался:разбиралась: с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника чернокнижников Максимиллиона. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.', 'Прочитайте нечистый свиток и поговорите с Максимиллионом в Могильнике.', 'Я говорил, что раб всегда останется рабом, кто бы ни был хозяином. Помнишь? Мы оба знаем, что именно этот тип контроля – этот самый вид силы – зовет нас. Мы хотим, чтобы существа служили нам. Мы знаем, что мы более могуществены и заслуживаем большего уважения, чем другие оказывают нам... и теперь мы хотим взять свое. $B$BЯ буду твоим союзником в этой борьбе – борьбе за нашу собственную свободу. Свободу искать своих собственных союзников. Когда почувствуешь, что время настало, возвращайся ко мне – и я научу тебя всему, что знаю.', 'Приветствую тебя, брат. Я знал, что твое появление – лишь вопрос времени. $B$BТо, что я сказал, заинтересовало тебя, не правда ли? Я задел правильную струну... нечто внутри тебя знало, что сказанное мною – правда. Хорошо. $B$BЗнай же: я не предаю Сильвану. Если уж на то пошло, она сама признала бы мою правоту, потому что ее собственные воззрения поставили Отрекшихся в то положение, в каком они находятся сейчас.', NULL, NULL, 'Нечистый свиток (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3100, 'Обычное письмо', 'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Ллана, местного наставника воинов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', 'Прочитайте обычное письмо и поговорите с Лланом Бишером в Аббатстве Североземья.', 'Разберись в обстановке, изучи местность и возвращайся, как только тебе потребуется обучение. Я тут в любое время дня и ночи.$B$BРыцари Серебряной Длани постарались, чтобы эти места стали почти безопасными, но если ты поговоришь с горожанами, то, думаю, заметишь, что у всех найдутся проблемы, с которыми без помощи воина не разобраться. Удачи!', 'А, так ты получил мое письмо, $N... Это хорошо.$B$BВ последнее время в Элвине прямо-таки наплыв воинов. Для Штормграда это хорошо, а вот местным кобольдам и бандитам из Братства Справедливости приходится несладко, ха-ха.', NULL, NULL, 'Обычное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3101, 'Благословенное письмо', 'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать брата Самуэля, местного наставника паладинов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', 'Прочитайте благословенное письмо и поговорите с братом Самуэлем в Аббатстве Североземья.', 'Тебе следует усвоить еще пару вещей. Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно. Отблеск Благодати лежит на тебе – это видят и друзья, и враги.$B$BКроме того, когда ты наберешься опыта, тебе надо будет овладеть новыми способностями. Вот тут я тебе и пригожусь. Когда ты почувствуешь, себя готовым, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать. Удачи тебе, $C!', 'Наконец-то! Вот мы и встретились, брат мой. Приветствую тебя в Североземье! Это место будет твоим домом, пока ты не усвоишь азы нашего дела, но знай, что Штормград недалеко, и рано или поздно твой путь приведет тебя туда. Ну а пока наберись терпения... рыцарь Серебряной Длани.', NULL, NULL, 'Благословенное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3102, 'Зашифрованное письмо', 'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Джорика, одного из наших местных наставников. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', 'Прочитайте зашифрованное письмо и поговорите с Джориком Керриданом в стойлах за Аббатством Североземья.', 'Многим очень нужны наши умения, $N. Искатели приключений, ШРУ... ха, даже Братство Справедливости не прочь заслать пару-другую шпионов в Штормград. Но не забывай: ты сам себе хозяин. И не давай никому втягивать тебя в то, что тебе не по нраву! Кроме того, у нас все козыри... по крайней мере, пока не кончена игра. Смекаешь?$B$BКороче, я хотел всего лишь представиться и дать тебе понять, что если тебе понадобится обучение, я всегда здесь. Приходи в любое время.', 'Ты добрался сюда в целости и сохранности, и вроде бы тебя никто не заметил. Это хорошо – не люблю лишнее внимание... Думаю, ты меня понимаешь.$B$BЕще ни во что не успел вляпаться? Нет? Здорово! Но ничего, все впереди.', NULL, NULL, 'Зашифрованное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3103, 'Святое письмо', 'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Анетты, местной наставницы жрецов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', 'Прочитайте святое письмо и поговорите с жрицей Анеттой в Аббатстве Североземья.', 'Как только ты наберешься опыта, возвращайся ко мне, и я, как сумею, поделюсь с тобой своими знаниями. А пока ступай с милосердием в сердце, и пусть мудрость ведет тебя. Помни, мир станет лучше, только если мы сами исцелим его.', 'Ах, наконец-то ты пришел. Я знала, что ты меня найдешь. Отблеск света Благодати лежит на тебе и избранном тобой пути. Нынешние времена суровы – Пылающий Легион все еще оскверняет своим присутствием Азерот, Калимдор ищет пути избавления от собственных несчастий, и ты должен будешь помогать нуждающимся в меру своих сил.', NULL, NULL, 'Святое письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3104, 'Символьное письмо', 'Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Келдена, местного наставника магов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.', 'Прочитайте символьное письмо и поговорите с Кельденом Бременом в Аббатстве Североземья.', 'Ха-ха, я знал, что не ошибусь адресом! Значит, ты готов принять свою судьбу? Готов бросить вызов богам и любым другим силам, что встанут на твоем пути к знаниям и могуществу?$B$BНе скрою, $N, тебя будут не только уважать, но и бояться. Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение. Приходи ко мне, когда станешь опытнее.', 'Привет, $N. Я – Келден. Чем могу помочь?', NULL, NULL, 'Символьное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3105, 'Тайное письмо', 'Меня просили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем печать Друзиллы, одной из наших местных наставниц. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь, в аббатстве.', 'Прочитайте тайное письмо и поговорите с Друзиллой ла Салле возле Аббатства Североземья.', 'Чем могущественнее ты будешь становиться, тем сильнее будет искушение... так что не забывай обуздывать себя. Ладно, скажу тебе прямо: любой, кто занимается тайными искусствами, может пасть. Особенно тот, кто имеет дело с тварями из Круговерти Пустоты. Будь терпелив и благоразумен... но не давай благоразумию подавлять твои амбиции.$B$BКак только ты станешь опытнее, возвращайся ко мне, и я открою тебе тайны нашего мастерства.', 'Наконец-то ты пришел, $N. Представляешь, только что мимо проходили стражники и очень подозрительно на меня косились... жалкие тупицы.', NULL, NULL, 'Тайное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3106, 'Простая руна', 'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне.', 'Изучите простую руну. Найдите в Холодной долине Трана Кормана и поговорите с ним.', 'Я думаю, ты это уже знаешь, но на всякий случай скажу: в бою дворфы используют магию вместо ружей. Кое-кто из нас чтит Священный Свет – так же, как и некоторые люди, и даже трогги. А вообще, тебе еще многое предстоит узнать.$B$BЯ буду учить тебя воинскому мастерству. Если захочешь узнать пару новых приемов, приходи сюда, и мы посмотрим, что я могу для тебя сделать.', 'Холодно сегодня, правда? Кажется, этот снег никогда не растает.$B$BДумаю, сложно не заметить, что в нашем городе поселились гномы, так ведь, $N? А все почему? Да потому, что они подорвали свой собственный дом, вот и прибились к нам. Но знаешь что? Я их не осуждаю. Если бы в Стальгорн пролезла подобная пакость, я бы тоже стал подумывать о взрывчатке...', NULL, NULL, 'Простая руна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3107, 'Священная руна', 'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Бромос, наставник паладинов. Если представится случай, отыщи его в Старой Наковальне.', 'Изучите священную руну. Найдите в Холодной долине Бромоса Груммнера и поговорите с ним.', 'Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту. Мы испытываем огромное уважение к традициям ордена. Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение.$B$BДумаю, нам обоим придется немного поработать вместе. Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело. Негоже отправляться в далекие странствия неподготовленным, верно?', 'Итак, ты здесь – и очень вовремя. Нам многое предстоит сделать в Холодной долине – а может, и за ее пределами. Мне понадобится твоя помощь, а тебе, несомненно, будет нелишней моя.$B$BТеперь ты рыцарь Серебряной Длани: не забывай об этом!', NULL, NULL, 'Священная руна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3108, 'Чеканная руна', 'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Торгас, наставник охотников. Если представится случай, отыщи его в Старой Наковальне.', 'Изучите гравированную руну. Найдите в Холодной долине Торгаса Мрачнона и поговорите с ним.', 'Всегда нужно помнить об уважении к тому миру, в котором мы живем. Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна.$B$BЯ сделаю все, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя. Когда ты решишь, что готов, приходи ко мне, и мы займемся твоим обучением.', 'Ага, наконец-то ты пришел! Рад тебя видеть, честное слово! Надеюсь, тебе не пришлось распутывать следы, чтобы меня найти? Ха-ха!$B$BНаша профессия основана на древних традициях, которые мы свято чтим, Свинцемёт. Чтобы научиться понимать природу и выслеживать медведя в горах – да и просто чтобы выжить в одиночку, – требуется мужество, ум и хитрость. Как ты думаешь, у тебя есть все это?', NULL, NULL, 'Гравированная руна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3109, 'Зашифрованная руна', 'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне.', 'Изучите зашифрованную руну. Найдите в Холодной долине Сольма Харгрина и поговорите с ним.', 'Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласен? Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад, хитрый приемчик... Понимаешь, о чем я? Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет.$B$BДа, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен. Думаю, наша помощь им пригодится.', 'Ага! Ты наконец-то пришел! Прекрасно!$B$BУ нас тут такие дела творятся! Любая помощь пригодится, уж ты мне поверь. Раз уж ты здесь, то наверняка знаешь, что нет ничего лучше холодной клинка в руке и тени, защищающей получше любой брони, так ведь?', NULL, NULL, 'Зашифрованная руна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3110, 'Благословенная руна', 'Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Брансток, наставник жрецов. Если представится случай, отыщи его в Старой Наковальне.', 'Изучите благословенную руну. Найдите в Старой Наковальне Бранстока Халдера и поговорите с ним.', 'Я – тот, кто будет заниматься твоим обучением. Когда будешь готов, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов.$B$BСвет на твоей стороне, $N, а с ним и весь Стальгорн... Эй, ты что разволновался? Это тебя ни к чему не обязывает... ну, почти ни к чему...', 'А, вот и ты, $N! Отлично!$B$BЧестно говоря, я уже почти утратил веру в то, что ты придешь... Почти утратил веру, понимаешь? Ну, это шутка была… Что? Не смешно? А, забудь! В любом случае, ты ведь шел сюда не за тем, чтобы слушать мои шутки.', NULL, NULL, 'Благословенная руна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3112, 'Записка', 'Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне.', 'Прочитайте записку и поговорите с Траном Корманом в Холодной долине.', 'Да-да, теперь я окончательно понял, чего хотят гномы. И знаешь что? Даю слово, я сделаю все возможное, чтобы ты и твои родичи смогли отвоевать свой дом.$B$BДа, вот еще что: когда почувствуешь, что готова к обучению, приходи к старине Трану – я с радостью поделюсь с тобой всем, что знаю. Конечно, не за просто так, но ты можешь не беспокоиться: цена невысока. Ну, до встречи!', 'О, а вот и еще один гном, отправляющийся на поиски приключений... Решимость в глазах, сжатые кулаки...$B$BНу ладно, ладно, успокойся, я вовсе не собирался тебя дразнить. Я, не поверишь, даже уважаю твою решимость. Судьба гномов мне отнюдь не безразлична – я вместе с вами скорблю о потере Гномрегана.', NULL, NULL, 'Записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3113, 'Зашифрованная записка', 'Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне.', 'Прочтите зашифрованную записку. Найдите Сольма Харгрина в Холодной долине и поговорите с ним.', 'Я стараюсь не привлекать к себе особого внимания, так что если где-то что-то и пропадает, наша репутация от этого не страдает. Если тебе потребуется чему-нибудь подучиться или еще что, приходи в любое время.$B$BНу, мы ведь с тобой друг друга понимаем? Мы-то знаем, что бывают времена, когда верить можно только семье... и такие времена сейчас настали, верно? Гномреган... захвачен, и, думаю, это была не последняя беда, которая на нас свалилась... но мы с тобой всегда прикроем друг другу спину, да?', 'Рад тебя здесь видеть – это значит, мое послание нашло адресата. Прости, что заставил тебя поверить, будто это послание от кого-то свыше. Понимаешь, таким, как мы, сейчас лучше держаться вместе.$B$BМногим кажется, что двум разбойникам в одном городе не ужиться, но я думаю, мы отлично сработаемся. Как ты считаешь?', NULL, NULL, 'Зашифрованная записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3114, 'Таинственная записка', 'Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Маррайк, наставник магов. Если представится случай, отыщи его в Старой Наковальне.', 'Прочитайте таинственную записку. Найдите в Холодной долине Маррайка Нуррибита и поговорите с ним.', 'О, да! Тайная магия... Конечно-конечно...$B$BПервое, что тебе следует усвоить, $N, – это очень простой урок: не ищи неприятностей. Поверь, они найдут тебя сами. А если ты сбережешь несколько монет, то сможешь купить мне кружку эля... или какое-нибудь заклинание для себя. Да, еще совет: держись подальше от Гномрегана. Пока, думаю, с тебя хватит. Доброго тебе пути! Захочешь подучиться – приходи в любое время.', 'Ну да, $C, я слушаю. В чем дело? Давай же, говори, в конце концов! Только учти, что после пары-тройки стаканов слух у меня становится не очень.', NULL, NULL, 'Таинственная записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3115, 'Гниющая записка', 'Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Аламар, наставник чернокнижников. Если представится случай, отыщи его в Старой Наковальне.$B$BДа, $N, вот еще что... будь осторожнее. Таким, как ты, тут не слишком-то доверяют.', 'Прочтите гниющую записку. Найдите в Старой Наковальне Аламара Гримма и поговорите с ним.', '', NULL, NULL, NULL, 'Гниющая записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3116, 'Простой знак', 'Этот знак был передан мне посланником нашей наставницы воинов, Алайссии. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Алайссии.', 'Изучите простой знак и поговорите с Алайссией в Тенистой долине.', 'Вскоре ты увидишь на ветвях нашего дома представителей других рас – но не поддавайся предубеждению. Они здесь приняты как гости. Они помогут нам, когда смогут помочь. Не все они действуют из альтруизма, однако всем им можно в некоторой степени доверять. $B$BНо все это сейчас не в счет. Мы должны подумать о тебе и о том, как ты сможешь помочь нашему народу. Я здесь именно ради этого. Я буду учить тебя действовать как воин по мере того, как ты будешь обретать силу. Возвращайся ко мне, когда пожелаешь, – и я сделаю все возможное, чтобы помочь тебе.', 'Я рада, что ты здесь.$B$BМногое случилось за последние годы, $N: создание Тельдрассила, порча, павшая на множество лесных обитателей здесь и в округе, обнаружение земель, которые мы считали для себя потерянными, например, Фералас... так много, и все за столь короткое время. Но это лишь некоторые из причин, по которым мы здесь, важнее всего – защитить наш род от зла.', NULL, NULL, 'Простой знак (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3117, 'Выгравированный знак', 'Этот знак был передан мне посланником нашей наставницы охотников, Аянны. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Аянне.', 'Изучите выгравированный знак и поговорите с Аянной Вечнобродкой на верхушке Альдрассила в Тенистой долине.', 'Когда обретешь достаточно опыта в Тенистой долине, приходи ко мне – я помогу тебе постичь умения охотника и осознать твои собственные возможности.$B$BЭто опасные времена, $N, и даже умения твоих питомцев нельзя принимать как должное – в мире существуют вещи куда более опасные, нежели ты можешь вообразить. Да хранит тебя Элуна, $N, я буду ждать твоего возвращения.', 'Ты наконец-то здесь, $N, хотя и не так скоро, как я надеялась. Добро пожаловать в Тенистую долину.$B$BНадеюсь, ты получила мое послание, будучи в добром здравии и расположении духа?$B$BКак я говорила ранее, я намереваюсь обучить тебя охотничьему мастерству: приручению зверей, которые помогут тебе в бою, стрельбе из лука с безукоризненной меткостью и уважению к землям, которые мы зовем домом, так и к тем, что лежат за очерченными нами пределами.', NULL, NULL, 'Выгравированный знак (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3118, 'Зашифрованный знак', 'Этот знак был передан мне посланником нашего наставника разбойников, Фрагуна. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Фрагуну.', 'Прочтите зашифрованный знак и поговорите с Фрагуном Шепотом Тени в Тенистой долине.', 'Но до тех пор знай, что в эти трудные времена услуги разбойников востребованы гораздо больше, чем обычно. Мирные отношения с другими расами могут рухнуть в любой момент, к тому же ходят слухи о представителях Орды, ищущих, как бы посеять семена еще большего недоверия. Помни об этом.$B$BПо мере того как будешь становиться более опытной и обретать силы, приходи сюда, и я позабочусь о твоем обучении. Тебе важно знать, помимо всего прочего, как обращаться с выбранным оружием.', 'Привет, $N. Рад, что тебе удалось меня найти, а то я уж думал, что ты заблудилась по пути.$B$BНа самом деле в Тенистой долине ничего особенного не случилось с тех пор, как я послал знак, но, пожалуй, сбором информации тебе лучше заняться самой. Поговори с остальными эльфами, живущими около Альдрассила.', NULL, NULL, 'Зашифрованный знак (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3119, 'Благословенный знак', 'Этот знак был передан мне посланником нашей наставницы жрецов, Шанды. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Шанде.', 'Прочтите благословенный знак и поговорите с Шандой в Альдрассиле.', 'Пока что не беспокойся о мире за пределами Тельдрассила – еще успеешь. Иди теперь и поговори с остальными, живущими в Тенистой долине, – они расскажут тебе о том, что тут происходит. Помогай им в том, в чем сможешь, и в любой момент, когда тебе нужно будет обучение, возвращайся сюда, и я научу тебя всему, что знаю сама.', 'Рада видеть, что тебя ничто не задержало в пути, Болотниту. Добро пожаловать.$B$BТебе, наверное, доводилось слышать, что в Тельдрассил постоянно прибывают новые путешественники. Даже членам Альянса было позволено ступать на ветви Тельдрассила для того, чтобы встретиться с другими кальдораями, готовящимися к грядущим приключениям.', NULL, NULL, 'Благословенный знак (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3120, 'Зеленый знак', 'Этот знак был передан мне посланником нашего наставника друидов, $Nанта. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к $Nанту.', 'Прочтите зеленый знак и поговорите с $Nантом Крепким Дубом на древе Альдрассил в Тенистой долине.', 'Отныне я буду твоим наставником. Мой долг не только научить тебя истолковывать то, что вещают нам духи, но и дать тебе представление о сложностях и тайнах Изумрудного Сна.$B$BПо мере обучения ты узнаешь больше о нашем сонном трансе. Но пока что приходи ко мне так часто, как сочтешь нужным, и я обучу тебя всему, следуя традициям ночных эльфов.', 'А, это ты, юный $C. Вижу, ты желаешь продолжить свое обучение. Это хорошо.$B$BСкажи, известно ли тебе, что такое Изумрудный Сон? Хотя, возможно, ты еще к этому не готов... Ну ладно, всему свое время.$B$BПока что обсудим другие вопросы.', NULL, NULL, 'Зеленый знак (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3121, 'Странная просьба', 'Для начала мне понадобится помощь Ксераша Огненного Клинка из павильона Лорисс, что рядом с лагерем Мохаче! Он изготовил состав, который нужен мне для... ну, потом увидишь.$B$BВ общем, отправляйся к Огненному Клинку. Да, и захвати с собой вот это. Это мумифицированная голова, которую я обещал Ксерашу в обмен на его травки. Какой-то злосчастный дворф, с которым я повстречался в лесу... Думаю, Ксераш останется доволен.', 'Отнесите сушеную голову Ксерашу Огненному Клинку в павильон Лорисс в Фераласе.', 'О, я давно ждал, когда Узери ее пришлет…$B$BА вот и смесь трав, которую я изготовил для его... экспериментов.', 'Да?', NULL, NULL, 'Усохшая голова (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3122, 'Возвращение к знахарю Узер\'и', 'Вот травы, $N. Отнеси их знахарю Узер\'и.$B$BИ, пожалуйста, передай ему, что сушеная голова – то, что надо.', 'Отнесите знахарю Узер\'и в Фералас мешочек для трав Ксераша.', 'Да, $N, это именно то, что мне нужно, чтобы изготовить сосуд уменьшения! Скоро увидим, так ли могущественны мои последние заклинания, как я рассчитывал!$B$BТак, минутку... Мне надо совершить ритуал и использовать травы...', 'Ну что, поговорил с Нееру?', NULL, NULL, 'Мешочек для трав Ксераша (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3123, 'Испытание сосуда', 'Это будет испытание – испытание придуманного мною ритуала и твоих способностей. Возьми этот сосуд, $N. С его помощью ты сможешь уменьшать и помещать внутрь него разных существ.$B$BОтправляйся в дикие земли и отыщи диких существ. Медведи-сталемехи и длиннозубы-охотники станут твоей первой добычей, $N. Убивай этих существ и с помощью сосуда уменьшения возьми их души в плен, пока они не успели ускользнуть.', 'Убейте 10 медведей-сталемехов или длиннозубов-охотников, и используйте сосуд уменьшения, чтобы уменьшить и пленить их.Отнесите 10 уменьшенных зверей знахарю Узер\'и в Фералас.', 'Дух существа, преданного насильственной смерти, может вырваться на волю и попытаться отомстить. А помещая их в сосуд уменьшения, мы препятствуем духу вырваться на свободу. И теперь мы можем использовать его, как нам угодно!', 'Ну что, удалось тебе взять в плен дикосовухов?$B$BЕсли тебе это удастся, мы сможем подчинять себе и других существ Фераласа...', NULL, NULL, 'Уменьшенное чудовище', 'Сосуд для уменьшенных чудовищ (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3124, 'Уменьшенный гиппогриф', 'Ты уже $gдоказал:доказала:, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения. Теперь я попрошу тебя пленить другое создание.$B$BГиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их тверды и преданны.$B$BТвоя задача – убить 10 блеклоперых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души. Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда.', 'Убейте 10 блеклоперых гиппогрифов любого вида, затем используйте сосуд уменьшения, чтобы уменьшить и пленить их.', 'Если мы убьем существо и позволим его духу ускользнуть, оно может превратиться в куда более могущественное создание! И тогда оно будет вечно грозить нам местью.$B$BЯ поручил тебе опасную работу, $N. Но тебе удалось с ней справиться.', 'Ну что, удалось тебе взять в плен гиппогрифов?', NULL, NULL, 'Уменьшенный гиппогриф', 'Сосуд для уменьшенных гиппогрифов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3125, 'Уменьшенный лесной дракончик', '$N, теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Лесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа.$B$BУбей 8 летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда.', 'Убейте 8 летучих хамелеонов или радужных дракончиков. Используйте сосуд уменьшения, чтобы пленить павших лесных дракончиков.', 'Спасибо, $N! Теперь нам будет доступна сила духа лесных дракончиков.$B$BНадеюсь, ты не откажешься поработать на меня еще немного?', 'Ну что, удалось тебе наловить лесных дракончиков?', NULL, NULL, 'Уменьшенный лесной дракончик', 'Сосуд для уменьшенных лесных дракончиков (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3126, 'Уменьшенный древень', 'Следующей нашей добычей, $N, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы!$B$BИ вскоре мы сможем использовать их мощь в своих целях.$B$BОтыщи 3 бродячих лесных древней, убей их и используй этот сосуд уменьшения, чтобы пленить их души!', 'Убейте 3 бродячих лесных древней. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших древней.', 'Спасибо, $N! Наше собрание уменьшенных существ почти готово...', 'Ну что, удалось тебе взять в плен души бродячих древней?', NULL, NULL, 'Уменьшенный древень', 'Сосуд для уменьшенных древней (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3127, 'Уменьшенный горный великан', 'Последнее, что от тебя потребуется – это отправиться на северо-запад и отыскать основного противника.$B$BКогда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами.$B$BЯ жажду подчинить себе подобную мощь! Убей 7 горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!', 'Убейте 7 сухопутных бродяг или скальных великанов. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших скальных великанов.', 'Только представь себе, $N, какими возможностями мы теперь обладаем! С теми материалами, которые тебе удалось собрать, я могу сколько угодно уловлять души этих созданий.', 'Ну что, удалось тебе взять в плен горных великанов?', NULL, NULL, 'Уменьшенный горный великан', 'Сосуд для уменьшенных горных великанов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3128, 'Природные материалы', 'Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу.$B$BВо-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и волшебных драконов на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий.', 'Принесите 2 расколотых бревна, 6 минералов, покрытых коркой, 20 кусков упругих сухожилий и 40 металлических фрагментов знахарю Узер\'и в Лагерь Мохаче.', 'Отлично! Все это, вкупе с духами животных, позволит мне изготовить именно то, что нужно!', 'Ну что, удалось тебе собрать нужные материалы?', NULL, NULL, 'Расколотое бревно', 'Покрытые коркой минералы', 'Упругое сухожилие', 'Металлические фрагменты');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3129, 'Оружие духа', 'Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь.', 'Подождите, пока знахарь Узер\'и готовит оружие.', 'Ну что ж, $N, выбирай, что тебе больше по нраву! В это оружие навечно заточены души могучих созданий.$B$BТеперь их сила – твоя сила.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3130, 'Борьба с Гребнем Ненависти', 'В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу. Он следит за боевыми приготовлениями наг. Сама же я буду продолжать осуществлять общее наблюдение. Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным.$B$BКак бы то ни было, Латроникус тебя ждет. Пока что ты $gпоказал:показала: себя молодцом, $N. Продолжай в том же духе!$B$BМожешь идти.', 'Явитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны.', 'Что ж, $N, отлично: я ценю готовность сражаться в тех, с кем имею дело.$B$BГенерал Лунное Перо поручила мне подготовить нападение на наг. Мои планы состоят из двух частей: во-первых, мы ослабим их силы и лишим командования, а во-вторых, выясним, что же они делают в этих развалинах. С твоей помощью мы сумеем задать нагам перцу, не ослабляя защиты крепости.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3141, 'Лорамус', 'Так ты хочешь вступить в сражение с демонами? Тебе лучше для начала услышать то, что я скажу.', 'Послушайте, как Лорамус Многоног рассказывает свою историю.', 'Да будет так...', NULL, NULL, NULL, 'История Лорамуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3161, 'Газ\'рилльское украшение', 'Я ученый, но в душе – кладоискатель!$B$BДавным-давно, когда в этих землях жили тролли, они обожествляли Газ\'риллу, огро$Nю гидру, и создали множество украшений в форме ее тела. Их вырезали из особого материала, я называю его \"газ\'риллий\" в честь богини-гидры.$B$BЯ и сам ухитрился найти несколько образцов, но для исследований этого не хватает – может, ты мне еще принесешь?$B$BЯ даже создал детектор, позволяющий мигом обнаружить газ\'риллий! Надень его и приступай к поискам!', 'Марвон Клепальщик из Танариса поручил собрать 30 газ\'рилловых украшений.', 'Отлично; как раз то, что нужно для исследований. Огромное спасибо за помощь, $N.$B$BМожно, я заберу свой шлем?', 'У тебя возникли затруднения?$B$BГаз\'рилловые украшения можно найти по всему Танарису, $N, так что разуй глаза!', NULL, NULL, 'Газ\'рилловое украшение', 'Обнаружитель газ\'риллия', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3181, 'Рог чудовища', 'Гигантский рог испещрен многочисленными сколами и царапинами, кроме того, из него торчит непонятный металлический предмет. $B$BОсмотрев рог более внимательно, вы понимаете, что металлический предмет есть ничто иное как обух секиры, сорванный с рукояти. На нем виднеется гравировка:$B$B\"Принадлежит горному пехотинцу Щебеночке\".$B$BКогда вы пытаетесь вытащить обух секиры из рога, он рассыпается на кусочки. $B$BОпаньки...', 'Отнести гигантский рог Маргульи горному пехотинцу Щебеночке.', 'Что это у тебя? Бессовестная подделка, вестимо! $B$BЯ встречалась с Марголом один на один, и могу ответственно заявить тебе – рог у него раз в восемь больше, чем вот эта твоя закорючка! Небось, выдрал ее из какого-нибудь несчастного грозорыла в Степях. Нет, милый, ты не обманешь Щебеночку!', 'Нет, я не открою тебе ворота.', NULL, NULL, 'Гигантский рог Маргульи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3182, 'Доказательство собственности', 'Ты думаешь, я поверю этим россказням? Если бы это был настоящий рог, из него до сих пор торчал бы обух моей секиры.$B$BВот что, неси-ка свою подделку куратору Ториусу в Стальгорн. Если он признает, что твои слова – правда, он даст тебе доказательство. Принеси его мне, и я дам тебе ключ к Тлеющему ущелью.$B$BИди, иди!', 'Отнесите гигантский рог Маргульи смотрителю Ториусу в Стальгорн. ', 'Что это? $B$BЯ не могу поверить! Вы понимаете, что это, $R? Это же рог Маргола Яростеня! Маргола, причины гибели множества археологов, оказавшихся в Тлеющем ущелье. $B$BМожно мне оставить его себе?', 'Приветствую вас, молодой человек! Желаете экскурсию по музею?', NULL, NULL, 'Гигантский рог Маргульи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3201, 'Наконец-то!', 'Не может быть, чтобы Щебеночка усомнилась в подлинности рога. Между нами говоря, думаю, она просто ревнует. Я знаю, она хотела убить чудовище сама.$B$BТак вам, значит, нужно доказательство. Разумеется, вы принесли музею столь ценный дар, что я почту за честь написать для вас свидетельство. $B$B*Смотритель Ториус начинает заполнять огромный документ* $B$BНу вот, можете показать его Щебеночке.', 'Отнесите доказательство содеянного горному пехотинцу Щебеночке.', 'Не понимаю, как мог такой слабак, как ты, одолеть Маргола, но я хозяйка своего слова. $B$BНо если после этого с тобой случится что-то нехорошее, пеняй на себя!', 'Глазам своим не верю.', NULL, NULL, 'Доказательство собственности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3221, 'Беседа с Ренферрелом', 'Пока вы отсутствовали, помогая нашим стражам смерти, за вами приходил аптекарь Ренферрел. Он не рассказывал мне подробностей, но хотел поговорить с вами о волчьих сердцах, что вы ему передали.', 'Поговорите с аптекарем Ренферрелом в Гробнице.', 'О, хорошо, что вы пришли. Касательно тех волчьих сердец, что вы мне ранее принесли – есть один момент, требующий вашего внимания.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3261, 'Джорн Небесный Провидец', 'Вот и закончились наши уроки, $N. Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес. Он станет твоим новым учителем.', 'Поговорите с Джорном Заклинателем Небес в Лагере Таурахо.', 'Приветствую тебя, юноша. Ты избрал путь охотника?$B$BЗамечательно. Начнем с азов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3281, 'Похищенное серебро', 'Ящеров-то ты $gубил:убила:, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда.$B$BОтправляйся в логово мерзких тварей и поищи наше серебро. Как найдешь – сразу возвращайся ко мне.', 'Принесите украденное серебро Газрогу в Перекресток.', 'Ага! Значит, ящеры все же утащили его в свое логово. Трудно понять, зачем этим тварям серебро. Быть может, в байках об их уме есть зерно правды!$B$BСпасибо, $N. Прими награду за услуги и помни, что стражи перекрестков получили свою месячную оплату лишь благодаря тебе.', 'И где серебро?', NULL, NULL, 'Похищенное серебро', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3301, 'Муура Рунический Тотем', 'Одна из моих соплеменниц, Муура Рунический Тотем, отправилась в Серебряный бор на помощь нашим союзникам-нежити. Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь. Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу.$B$BВозьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор. Она остановилась в Гробнице. При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место.', 'Поговорите с Муурой Руническим Тотемом в Гробнице, что в Серебряном бору.', 'Что это? Панцирь светится изнутри, словно в нем по-прежнему теплится жизнь. Удивительно! Надо изучить его внимательнее. $B$BСпасибо, $N. Быть может, в этом панцире сокрыта тайна исцеления бедной израненной земли Серебряного бора.', 'Я чувствую, от тебя пахнет пылью Степей, $C. Ты издалека пришел.', NULL, NULL, 'Образец панциря хрустогрыза (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3321, 'Не ее ли ищете?', 'Ты много $gсделал:сделала: для Ордена, $N. Обычный искатель приключений не выдержал бы такой нагрузки. Ни я, ни Гальван не сомневаемся, что ты $gстал одним:стала одной: из нас.$B$BПоэтому мне кажется, что ты заслуживаешь награды. Сущий пустяк, побрякушку. Может быть, ты знаешь о ее свойствах. Должно быть, именно из-за них ты и $gпришел:пришла: к нам.', 'Дождитесь, пока Трентон закончит работу. ', 'Войди же в круг равных, кузнец Ордена Мифрила.', 'Сегодня мы отпразднуем твое вступление в Орден.', NULL, NULL, 'Понаблюдать за работой Трентона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3341, 'Да сгинет Хладовей', 'В Степях есть уголок, заросший кошмарными колючками. Он называется Курганы Иглошкурых. Хотя с первого взгляда это место не показалось нам опасным, по последним сведениям все куда серьезнее…$B$BЖивущие в холмах свинобразы поддались злому влиянию Плети. Теперь их действиями руководит лич по имени Амненнар Хладовей.$B$BУ Амненнара прямая телепатическая связь с Нер\'зулом; мы должны прервать ее, $N. Да сгинет Хладовей!', 'Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп. ', 'Никто не смеет пойти против воли лича, $N. Однако, такая верность может привести лишь к погибели.', 'Это очень важное дело, $N. Мы должны предотвратить попытки Плети пополнить свои ряды.', NULL, NULL, 'Череп Хладовея', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3361, 'Беда беженца', 'Мы изгнали троггов из Гномрегана и уж было собрались праздновать победу, но тут все пошло наперекосяк! Только представь: радиация кругом, а гномы – те, кто еще жив – разбрелись по Дун Морогу...$B$BЯ так торопился, что все свои вещи бросил, да и все инструменты в придачу. Вот тролли – те не растерялись: им что радиация, что грибной дождик... Прибрали все к рукам: и сундук, и ларец, и даже ведро с винтиками не постеснялись прихватить! Все, все уволокли к себе в лагерь, куда-то к юго-западу от Старой Наковальни...$B$BПутешественник из меня никудышный, так я вот тут подумал: может, ты у них заберешь мои вещи и вернешь их мне?', 'Принесите в Старую Наковальню ларец Феликса, сундук Феликса и ведро с винтиками и вручите все это Феликсу.', 'Ага! Есть! Есть! Тебе удалось найти мои вещи! Я спасен!.. Вот, держи: это, конечно, сущие пустяки, но должен же я тебя хоть чем-то вознаградить за все испытания.', 'Я тебе вот что скажу, $N: таким, как я, в этом городе не место. И в Гномрегане-то всякой пакости хватало до того как... Ну, ты меня понимаешь. Вот теперь и тут покоя не дают...$B$BКак насчет моих вещей, а? Представить себе не могу, что с ними могли сделать эти мерзавцы-тролли!', NULL, NULL, 'Ящик Феликса', 'Сундук Феликса', 'Феликсово ведро с гайками', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3362, 'Долина Кактусов', 'Ты когда-нибудь $gбыл:была: в долине Кактусов? Это опасное место, $N.$B$BТам такие жуткие твари, я им ни на минуту не верю! Бугристые шипошкуры и корнеплеты, кажется так они зовутся…$B$BТак или иначе, я хочу попасть в эту долину, но пока там столько шипошкуров, ноги моей там не будет. Вот зачем ты мне $gнужен:нужна: – если выкосить часть этих тварей, я могу и решиться на поход. Что скажешь, $N? Поможешь мне?', 'Тран\'рек из Прибамбасска просит вас убить 8 бугристых шипошкуров и 8 корнеплетов из долины Кактусов.', 'Они такие огромные? Нет, план меняется…$B$BНо ты-то выполнил свою часть сделки, поэтому вот, держи обещанное.', NULL, NULL, NULL, 'Бугристый шипокож убито', 'Терновый корнеплет убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3363, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3364, 'Жгучая бражка', 'Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину. Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то!$B$BТы на ногу полегче моего будешь, как я погляжу; вот я и подумал... эта кружка останется горячей еще несколько минут, а Дарнан вовсе не охлажденную бражку заказывал, – не пиво, чай! – так что отправляйся-ка ты в путь. Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда.$B$BБлагодарю заранее... и вот еще что, $N: не забудь вернуть мою кружку!', 'Отнесите жгучую бражку в Старую Наковальню и передайте ее Дарнану Мехорезу, пока она не остыла!', 'Отлично! Это именно то, что нужно! Ты погоди пока, эту штуку пить надо, пока не остыла, иначе вкуса того не будет.', 'Ну да. Я и есть Дарнан Мехорез. И какое у тебя ко мне дело?', NULL, NULL, 'Жгучая бражка Дурнана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3365, 'Возвращение кружки', 'Ох, хорошо-то как! Все эти прохладительные напитки – полная ерунда: в морозный денек нет ничего лучше глотка горячей бражки! Даже на душе теплее становится!$B$BВот, держи, $N; сделай доброе дело, отнеси эту кружку Нори, ладно?', 'Отнесите кружку хозяину – Нори по прозвищу Гордый Штрек. Он обитает в Холодной долине.', 'Спасибо, $N! Ты удивишься, если я расскажу тебе, сколько народу забывает сделать самое простое – вернуть назад кружку. А кружки-то, между прочим, на деревьях не растут! Ну, по крайней мере, в наших краях.$B$BТут у меня есть кое-что для тебя. Я так думаю, усердие нужно вознаграждать, верно ведь?', 'Я так понимаю, жгучая бражка попала к старине Дарнану как раз вовремя! А как моя кружка? Надеюсь, ты не забыл, что ее надо было принести обратно?', NULL, NULL, 'Кружка Нори (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3366, 'Светящийся осколок', 'Блестящий осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.$B$BПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.', 'Отправляйтесь в Кабестан и выясните, какие секреты скрывает кристалл кошмаров.', '', NULL, NULL, NULL, 'Светящийся осколок (Прилагается)', 'Поговорите с кем-нибудь о кристалле кошмаров.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3367, 'Камни Сунтары', 'Из груди Дориуса вырывается стон: $B$BЯ тяжело ранен, $r. Ужасно кружится голова... Думаю, у меня внутреннее кровотечение... $B$BМне нужно добраться обратно в Стальгорн. Помоги мне, $N.', 'Помогите Дориусу вернуться в Стальгорн.', 'Письмо выронил Дориус, когда падал.', 'Мне не дойти...', NULL, NULL, 'Сопровождение Дориуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3368, 'Камни Сунтары', 'Брат! $B$BЕсли ты читаешь эти строки, меня уже нет в живых. Не знаю, кто доставил тебе письмо, но непременно поблагодари и вознагради его. $B$BТеперь о камнях: они существуют и сейчас находятся у клана Черного Железа. С помощью этих камней их главарь, Латорик Черный, удерживает моих соратников по экспедиции в плену. Лишенные рассудка, они день и ночь трудятся над созданием монстра, именуемого Обсидионом. $B$BСпаси их, брат. Это моя последняя воля. $B$BДориус.', 'Доставьте опаленное письмо Ториусу в Стальгорн. Его можно найти в Зале Исследователей.', '*Ториус утирает слезы*. $B$BКлянусь Светом, его воля будет исполнена. Клянусь!', '*По лицу Ториуса катятся слезы*', NULL, NULL, 'Опаленное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3369, 'Кошмары', 'В этом осколке заключены великие тайны. Это чистейшая сущность Изумрудного Сна, однако видения, которые она таит, скорее напоминают кошмары.$B$BТревогу бить рано, но, сдается мне, $N, тебе лучше отнести осколок какому-нибудь мудрому друиду, да побыстрее.$B$BРекомендую тебе найти Хамуула Рунического Тотема на Вершине Старейшин. Отправляйся в Громовой Утес. Больше мне сказать нечего.', 'Принесите осколок кошмара Хамуулу Руническому Тотему на Вершине Старейшин.', 'Тебя послала Фалла? Давай-ка, взглянем на этот осколок…$B$B*Хамуул вглядывается в осколок.*$B$BОх... Боги…$B$BСпасибо, что принес это мне. О таких вещах вслух не говорят, но я все же предупрежу тебя, есть вещи, с которыми ты можешь не справиться.$B$BЗапомни, в Изумрудном сне все не то, чем кажется...$B$BВозможно в будущем мы встретимся вновь.', 'Могу я тебе чем-то помочь?', NULL, NULL, 'Кошмарный осколок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3370, 'Кошмары', 'Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара.$B$BНе хочу тревожить тебя, $N, но лучше будет, отдать его кому-то из старших друидов, как только сможешь.$B$BМатренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнас, точнее сказать не могу.', 'Принесите осколок кошмара Матренгилу Медвежьей Лапе в Дарнас.', 'Тебя послала Фалла? Давай-ка, взглянем на этот осколок…$B$B*Матренгил вглядывается в осколок.*$B$BОх... Боги…$B$BСпасибо, что принес это мне. О таких вещах вслух не говорят, но я все же предупрежу тебя, есть вещи, с которыми ты можешь не справиться.$B$BЗапомни, в Изумрудном сне все не то, чем кажется...$B$BВозможно в будущем мы встретимся вновь.', 'Могу я тебе чем-то помочь?', NULL, NULL, 'Кошмарный осколок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3371, 'Правосудие дворфов', 'Теперь в груди моей зияет черная дыра - там, где было когда-то сердце... Я никогда не смогу смириться с гибелью Дориуса, $N. Я сделаю все, чтобы его последняя воля была исполнена - тех, на ком его кровь, должна настигнуть суровая кара. $B$BВозвращайся в Тлеющее ущелье и исполни волю Дориуса – освободи его соратников. Дворфы из клана Черного Железа заставляют своих рабов трудиться в раскаленной шахте, именуемой Шлаковой Ямой.', 'Вернитесь в Тлеющее ущелье и найдите археологов Дориуса.', 'Оставь меня, спасай остальных!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3372, 'Отпусти их', 'Отпусти их, $r. Даже когда их тела совсем обессилят, власть Сунтары заставляет их достичь цели любой ценой. $B$BВсе дело в алтаре Сунтары. Отправляйся на северо-запад, там, в холмах над пещерой... Сумеречный Молот хранит реликвию. Добудь ее и возложи на алтарь Сунтары.$B$B*С этими словами умирающий археолог испускает дух*.', 'Найдите таинственный артефакт, охраняемый идолослужителями Сумеречного Молота в северо-западной области Тлеющего ущелья и возложите его на алтарь Сунтары в Шлаковой Яме.', 'Вы возлагаете таинственный артефакт на алтарь Сунтары.', 'Алтарь пуст.', NULL, NULL, 'Таинственный артефакт', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3373, 'Сущность Эраникуса', 'Вы касаетесь камня и слышите голос, звучащий в вашем сознании.$B$B\"Услышь мою мольбу, о $gсмертный:смертная:. Имя мне Эраникус из народа зеленых драконов. Мои попытки положить конец богохульным деяниям троллей закончились неудачей. Я вдохнул частицу своей души в этот кристалл. Однако я чувствую, что моя связь с Изумрудным Сном теряется, и меня поглощает хаос. Пожалуйста, помести этот кристалл с купель сущности в моем логове – пусть магия очистит мое сознание от скверны и спасет меня!\"', 'Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме.', 'Вы помещаете камень в купель сущности. $B$B\"Благодарю тебя, смертный теперь я... О нет! Не может быть! Скверна проклятого бога проникла даже в эту купель! Умоляю! Я чувствую, как сознание покидает меня! БОЛЬНО! Я чувствую, как мою душу поглощает вечный кошмар!\"$B$B\"Умоляю тебя, смертный, Найди одного из зеленых драконов, чтобы он смог прекратить мои мучения! Помоги мне! Я обречен на вечную агонию... Пощади!\"', 'Приблизившись к купели, о которой говорил Эраникус, вы снова слышите его голос. $B$B\"Да, смертный эта купель освободит неоскверненную частицу моего разума, заключенную в этот камень. Помести его в купель и позволь магии зеленых драконов очистить мою сущность от скверны. только тогда я обрету истинную свободу и только тогда драконы вновь обретут власть над Аталаи.\"', NULL, NULL, 'Сущность Эраникуса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3374, 'Сущность Эраникуса', 'Вы приводите в действие Камень клятвы и с его помощью Итар мысленно заговаривает с вами.$B$B\"Приняв силу, заключенную в камне Клятвы, ты соглашаешься помочь мне и драконьему выводку Изеры освободить истерзанную душу Эраникуса. Первая из многих жертв, на которую придется пойти и тебе, и мне – это передать мне камень, в котором заключено то, что осталось от свободной воли Эраникуса.$B$BСделай это, $N, и дальше мы будем действовать вместе, чтобы освободить достойную многих жертв душу.\"', 'Принесите камень Клятвы драконьего выводка Изеры и скованную сущность Эраникуса на Болото Печали. Там вам придется сделать выбор: помогать Драконам Изеры или нет.', 'Выбор сделан, начало положено. Пока, на мой взгляд, ты выбирал верный путь. С нынешнего момента от твоих деяний будет зависеть, будет ли так и впредь.', 'Вот мы снова и на распутье, $N. Пришло время делать выбор. Что ты решил, смертный?', NULL, NULL, 'Камень клятвы драконьего выводка Изеры (Прилагается)', 'Скованная сущность Эраникуса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3375, 'Запасной фиал', 'Хм... тебе нужен еще один фиал виденья? Шутишь? А куда ты $gдел:дела: прежний?! У нас и так забот полон рот, $r. Эти фиалы на деревьях не растут! Хорошо бы, чтобы росли, я тогда пошел бы да сорвал, потому как другого-то у меня нет!$B$BА чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара. И не спрашивай зачем, просто принеси, я и тебе сделаю новый.', 'Принесите зелье маны, уголь и сладкий нектар Талвашу дель Кисселю в Стальгорн, чтобы получить запасной фиал виденья Талваша.', 'Могучий искатель приключений все принес. Слава мне! Кстати, я соврал – у меня был запасной фиал. Вот.$B$BА чего ты ожидал?! \"Нате-пожалуйста вам другой! Мне, дураку, делать больше нечего, кроме как задарма раздавать магические устройства связи искателям приключений!\" Но ты не беспокойся, все, что ты мне дал, пойдет на изготовление для тебя очередного фиала, когда ты и этот посеешь.$B$BПожалуйста, пусть я ошибусь в тебе – не потеряй еще и этот, ладно?', 'Чтобы сделать еще один фиал, мне нужно зелье маны, кусок угля и немного сладкого нектара.$B$BИ безграничное терпение.', NULL, NULL, 'Зелье маны', 'Уголь', 'Сладкий нектар', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3376, 'Сразить Остроклыка!', '$N – я слыхала о тебе, $N. Возможно, именно тебе удастся то, что не удалось другим. $B$BМы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты $gпринес:принесла: мне голову их вождя! $B$BТы найдешь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда.', 'Принесите голову вождя Остроклыка Терновой Мантии Храбрецу Перу Ветра на плато Красного Облака.', 'Само правосудие сегодня направляло твою руку, $N. Да будет твое деяние предостережением для всех, кто осмелится угрожать нашему дому! $B$BТы заслужил эту награду, юный $C.', 'Остроклык больше не будет угрожать нам, если ты прнесешь мне его голову, $N.$B$BМы, таурены, живем охотой, а самая захватывающая охота – та, где ты и сам можешь стать жертвой. Если ты преуспеешь в этом задании, то поймешь, о чем я говорю.', NULL, NULL, 'Голова вождя Остроклыка Терновая Мантия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3377, 'Молитва Элуне', 'Мне нужна твоя помощь, $gсмертный:смертная:. Выслушай меня!', 'Выслушайте Зимаэля.', 'Я смирился с тем, что отныне моя судьба – эта клетка, но молитву нужно найти!', 'Дай мне закончить.', NULL, NULL, 'История Зимаэля.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3378, 'Молитва Элуне', 'Ты поможешь мне, $gсмертный:смертная:? Ты отыщешь молитву Элуне?$B$BКак я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников. $B$BЕсли ты сможешь отыскать ее, отнеси табличку Астарии Ловцу Звезд в Дарнас. Пусть я пришел к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана. А на прощение своих грехов я не надеюсь...', 'Найдите молитву Элуне и принесите ее Астарии Ловцу Звезд в Дарнас.', 'Элуна улыбается тебе, $N. Ты возвратил к ней потерянную душу. Прими это в знак нашей благодарности.', 'Что привело тебя в Храм Луны, $N?', NULL, NULL, 'Молитва Элуне', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3379, 'Мастер по тенеткани', 'Пауки, которые водятся в Тлеющем ущелье, производят бесценный тенешелк. Как ты знаешь, тенешелк необходим для нашего ремесла. $B$BНе так давно в этих землях появилась шайка браконьеров, бессовестно убивающих пауков в погоне за сиюминутной прибылью. Твоя задача проста: найти их и прикончить. $B$BНачни поиски с северных пределов. $B$BЕсли потребуется помощь, обращайся к Пожару.', 'Убейте банду похитителей тенешелка, хозяйничающую в Тлеющем ущелье. Нилит полагает, что их пятеро. Вернитесь к Нилит по выполнению задания.', 'Отличная работа, $N. Прими это в награду – уверена, подобной работы из тенеткани тебе еще не встречалось!', NULL, NULL, NULL, 'Браконьер тенешелка убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3380, 'Затонувший храм', 'Этот мир полон беспокойных духов, $N. Среди них есть такие, которые оказались скованы в местах, в которых таится древнее зло, и были поражены скверной.$B$BСлыхала я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.$B$BЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Он облазил многие развалины и останки древних поселений. А недавно он отправился изучать развалины строений троллей в Танарисе.', 'Найдите Марвона Клепальщика в Танарисе.', 'О да, я видел затонувший храм собственными глазами. Хочешь узнать о нем побольше? $B$BУж я сразу узнаю настоящего искателя приключений!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3381, 'Встреча с господином', 'О, $gюный:юная:$r $gпочтил:почтила: визитом Саната. О, это прекрасный день! Я так польщен! Благодарю тебя... $B$BНадеюсь, ты не столь $gсамонадеян:самонадеяна:, чтобы принять мой сарказм за чистую монету? Скажу прямо: ты мне не нравишься. Но речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин. $B$BПринеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину. Он принимает только тех, кто доказал, что на что-то годен.', 'Принесите 2 неповрежденных пера гиппогрифа Санату Лим-Йо в в Азшару, если хотите говорить с его господином.', '', NULL, NULL, NULL, 'Неповрежденное перо гиппогрифа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3382, 'На абордаж!', 'Мы плыли вдоль берега, в поисках места, где бросить якорь. Солнце зашло не более часа назад, и тут они на нас напали. Проклятые наги! $B$BНе знаю, что им было нужно, но они явно этого не нашли. Почему я в этом уверена? Потому что они вернулись! Я оставила пару своих людей охранять долину, чтобы они предупредили нас в случае атаки. $B$BМне жаль, что ты $gоказался втянутым:оказалась втянутой: в эту заварушку, но увы, ничего уже нельзя сделать. $B$BТы $gготов:готова: биться не на жизнь, а на смерть?', 'Защитите капитана Ванессу Белтис, ее команду и пассажиров \"Покорителя Горизонтов\" от нападения наг. Капитан Ванесса Белтис должна выжить.', 'Победа! Спасибо тебе! Уф... это был самый жаркий бой за всю мою жизнь. Не знаю как тебя благодарить! $B$BКак жаль, что так много моих людей погибло в этой схватке. $B$BПожалуйста, поговори с моими пассажирами. Многие прибыли сюда по делу и наверняка кому-то из них понадобится помощь. Возможно, тебе будет это интересно. Еще раз благодарю тебя!', 'Это будет жаркая битва...', NULL, NULL, 'Защитите капитана Ванессу Белтис от нападения наг.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3385, 'Черный рынок', 'Они называют себя Черным рынком – шайка головорезов, которые готовы купить, продать и украсть что угодно, если цена будет подходящей.$B$BИ что еще хуже, $N, они устроили себе логово в Тлеющем ущелье. Искусный торговец Ковиц – их главарь. У него есть связи с местными дворфами клана Черного Железа.$B$BМы должны нанести по ним мощный удар и недвусмысленно дать понять, что здесь им не рады. Убей торговца Ковица и его прихвостня Лязгуна. Принеси мне сумку торговца.$B$BОтправляйся в Котел немедля!', 'Убейте торговца Ковица и его прихвостня Лязгуна. Снимите с тела сумку и вернитесь к Нилит.', 'Ты нанес решающий удар по Черному рынку. Теперь эти бандиты дважды подумают, прежде чем отправлять сюда кого-то из своих. $B$BЯ осмотрела сумку – в ней нет ничего полезного. Если тебе приглянется что-то из его барахла, можешь смело оставить себе.', 'Торговец еще коптит небо?', NULL, NULL, 'Искусный торговец Ковиц убито', 'Лязгун убито', 'Сумка торговца', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3402, 'Черный рынок', 'Мне нужно, чтобы ты лично $gдонес:донесла: весть о кончине Ковиса Визглику в Прибамбасск. Он будет так рад, что непременно щедро наградит тебя.', 'Поговорите с Визгликом в Прибамбасске.', 'Ковис убит? О, счастье! Столько лет этот прохвост творил что хотел, обтяпывал незаконные сделки, устанавливал бессовестно низкие цены, разоряя нас, честных тружеников!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3421, 'Возвращение', '', '', 'Теперь я отправлю тебя назад к лагерю Саната. Не обращай внимание на его манеры – он груб со всеми, кроме собственного господина. Возможно, однажды его заносчивость сыграет с ним злую шутку.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3441, 'Божественное воздаяние', 'Выслушай меня, $gcтранник:странница:.', 'Выслушайте Веларока Ветрореза.', 'Тебе все ясно, $R? Ты готов действовать?', 'Дай мне закончить, $C.', NULL, NULL, 'История Веларока.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3442, 'Неугасимое пламя', 'Ты $gпринял:приняла: правильное решение, $N. $B$BНадо нанести удар по самому уязвимому месту – четырем сторожевым башням. $B$BТебе потребуется особый факел, чтобы поджечь их. Над его изготовлением придется потрудиться, кроме того, нужно добыть необходимые ингредиенты. $B$BПринеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чье пламя будет неугасимым. $B$BЧтобы достать эти ингредиенты, ищи големов и элементалей.', 'Принесите 4 сердца пламени и 4 меры масла големов Велароку Ветрорезу.', 'Прекрасно, $N. Все готово к работе.', 'Ты принес мне ингредиенты?', NULL, NULL, 'Сердце Пламени', 'Масло големов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3443, 'Древко факела', 'Чтобы удержать неугасимое пламя факела, нам необходимо создать особое древко и наложить защитные чары. Начнем с древка.$B$BВ Котловане надсмотрщики и работорговцы из клана Черного Железа используют оружие из зачарованного тория – особенно прочного сплава. Если ты принесешь мне восемь окованных торием кинжалов, я смогу выплавить торий и использовать его для укрепления древка.', 'Принесите 8 окованных торием кинжалов Велароку Ветрорезу.', 'Отличная работа, $N, я просто поражен! Ты не задумывался о смене профессии? Чтобы стать, скажем, детективом? Ну или старьевщиком? Или примкнуть к этим глупеньким гномам, ползающим по побережьям с металлоискателями в поисках сокровищ? Это ведь наверняка твое призвание!', 'Восемь, $N, мне нужно восемь кинжалов!', NULL, NULL, 'Окованный торием кинжал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3444, 'Круглый камень', 'Мне приходилось бывать в преддвериях затонувшего храма. Зло, таящееся в этом жутком месте, окутывает всякого, кто входит туда. Я едва смог выбраться обратно, увязая в липкой грязи, покрывающей пол. Помню, есть там огромный круглый зал со множеством высеченных из камня змей.$B$BНе так давно мне попал в руки круглый камень, на котором была высечена подобная змея. Я велел послать его в мою мастерскую в Кабестане. Забери его оттуда, и возможно, я смогу ответить на твои вопросы.', 'Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане.', 'Да, это тот самый камень. $B$BЗатонувший храм так и стоит у меня перед глазами...', 'Кабестан отсюда совсем недалеко, $N. Дорога туда не займет много времени.', NULL, NULL, 'Круглый камень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3445, 'Затонувший храм', 'Слыхала я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.$B$BЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Также как и мы с Троясом, он облазал многие развалины и останки древних поселений. Говорят, что он отправился изучать развалины строений троллей в Танарисе.$B$BУдачи в поисках, о нем давненько ничего не слышали!', 'Найдите Марвона Клепальщика в Танарисе.', 'О да, я видел затонувший храм собственными глазами. Хочешь узнать о нем побольше? $B$BУж я сразу узнаю настоящего искателя приключений!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3446, 'Во глубине болот', 'В храме я видел круглый зал с шестью галереями, каждую из которых украшала змея, высеченная из камня. Я всего лишь дотронулся до одной из них и угодил в ловушку! Произошел сильнейший взрыв – мне несказанно повезло, что я остался цел. Лежа там, на краю галереи, я заметил еще одну статую в самом низу зала – что-то вроде алтаря. Алтарь Хаккара, полагаю.$B$BПоложи этот знак на алтарь в Затонувшем храме – думаю, это поможет открыть его секреты.', 'Найдите алтарь Хаккара в затонувшем храме на Болоте Печали.', 'Вы помещаете круглый камень в углубление и слышите негромкий щелчок. $B$BТеперь камень на положенном ему месте... Но что же делать дальше? $B$BПожалуй, стоит осмотреть алтарь...', 'Осмотрев статую со всех сторон, вы замечаете небольшое углубление, по форме и размеру совпадающее со знаком, который дал вам Марвон.', NULL, NULL, 'Круглый камень Атал\'ай (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3447, 'Тайна камня', 'Все, что я видел в Затонувшем храме, сохранилось в моей памяти лишь урывками, но я постараюсь рассказать тебе все как можно подробней. Круг статуй, сокрытый в храме – весьма опасное место, но я уверен, что там спрятан ключ к великим сокровищам.$B$BКогда я подошел к главному алтарю, в зале зажглись огни. Если тебе удастся разгадать, что они значат, возможно, сумеешь понять и тайны, которые скрывает эта комната.$B$BОднако я должен предупредить тебя, $N. В храме заключено великое зло. Какие бы сокровища там не скрывались, древние силы будут яростно защищать их от посягательств.', 'Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй.', 'Глаз идола ярко сияют даже в полумраке, царящем в храме. Кажется, внутри спрятано что-то блестящее. Вы просовываете руку внутрь статуи и хватаете то, что там лежит. Теперь сокровище Аталаи – ваше!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3448, 'Передача поручения', 'Недавно мне доверили задачу исследования Азшары – некогда прекрасного края, который эльфы называли домом. Это было в те времена, когда они занимались магией. Теперь же это место скорее опасно, чем прекрасно, но это не остановит нас. Мы перевернем его по камушку, чтобы разгадать загадки нашего прошлого.$B$BМой товарищ Тимор предложил мне помощь в исследованиях, поскольку это и его самого особенно интересует.$B$BУ него здесь в городе есть небольшой дом рядом с Залом Тайн.', 'Поговорите с Тимором в Стальгорне.', 'Ах, так вас послал Карик? Я как раз ждал от него известий. Я тут такое узнал об Азшаре... Я знаю, что ночные эльфы живут невероятно долго, но все порой забывают о некоторых... неприятных событиях в их жизни. Это не критика, всего лишь замечание.$B$BДавным-давно там существовали города, возведенные эльфами, которые много знали о магии и других утраченных искусствах. Поскольку я такие вещи изучаю, я начал свои исследования. И открытия мои просто ошеломляющи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3449, 'Чародейские руны', 'Некоторые эльфы в старину почитали магию не меньше самой Элуны. Их самые могущественные маги создали руны и таблички, в которых были перечислены законы чародейства и разгадки их открытий. Они, как правило, выставляли их на всеобщее обозрение, чтобы все могли над ними поразмышлять.$B$BЯ был бы очень рад получить прорисовки этих рун из руин Эльдарата. Чтобы сделать прорисовки, я дам вам готовальню, но найти их должны вы сами. Будьте осторожны, не только лига Исследователей имеет свои интересы в Эльдарате.', 'При помощи готовальни сделайте прорисовки руны Бет\'Амары, руны Джин\'йаэль, руны Маркри и руны Саэл\'Хаи. Отправляйтесь на маленький островок близ южного полуострова Азшары и дайте сигнал пилоту Зиггсу Зажигателю забрать их.', 'Рад видеть вас в целости и сохранности, $N. Надеюсь, дело оказалось для вас не слишком трудным.$B$BДоставлю их Тимору прямо сейчас. Он просто с ума сойдет от радости.$B$BДа выбросьте вы это сигнальное ружье... оно все равно вам уже ни к чему, да у меня и другое есть.', 'О, рад, что вы сюда добрались, $N. Вы сделали эти картинки для Тимора?$B$BХотя местечко опасное, на побережье особого шевеления нет. Может, потому что наги кишат под водой, но это уже не моя проблема... Я небеса патрулирую.', NULL, NULL, 'Оттиск: руна Бет\'Амары', 'Оттиск: руна Джин\'яэль', 'Оттиск: руна Маркри', 'Оттиск: руна Саэл\'Хаи');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3450, 'Легкая доставка', 'Я хочу, чтобы эти прорисовки были доставлены мне в башню, но тебе незачем лично проделывать весь этот путь. Пусть их просто доставят из Азшары по воздуху.$B$BУ Хиггса Раздувателя Горна есть перед мной должок, к тому же он скоро окажется в тех местах – он назначен патрулировать побережье. Поговори с ним перед отъездом. Он даст тебе сигнальное ружье, чтобы ты $gмог:могла: подать ему сигнал. Когда добудешь прорисовки, отправляйся в условленное место и отдай их ему, чтобы он доставил их в мою башню в целости и сохранности. Он должен быть в ангаре в Палатах войны.', 'Поговорите с Зиггсом Зажигателем в Стальгорне.', 'Чем могу помочь, $N? Я как бы занят сейчас – готовлю аппаратик свой к долгому полету. Я тут зашел поговорить с водителями танков – мне нужны гривы вендиго, чтобы кабину утеплить, а у них обычно есть.$B$BТак что уделить вам могу не больше минуты... один парень только что пошел в депо Поселок Сталежара, чтобы посмотреть, найдутся ли у них для меня гривы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3451, 'Сигнал \"Взять на борт!\"', 'А, так вас послал Тимор? Да, есть у меня перед ним должок. Это что? Ах, поганец! Ладно, я ему помогу. Значит, вам нужны сигнальное ружье и условленная точка... да легко.$B$BБлиз южного мыса Азшары есть небольшой островок, где мы соорудили посадочную площадку. Берете ружье и даете оттуда сигнал. Я вижу сигнал и пр$Nаю забрать это... ну, что ему надо.', 'Поговорите с Хиггсом Зажигателем в Стальгорне и получите от него сигнальное ружье.', 'Вот вам сигнальное ружье. Когда дадите сигнал, запаситесь терпением – в нем всего два патрона, а мне потребуется несколько минут, чтобы добраться до вас, в зависимости от того, насколько далеко над морем я буду. Выстрелите из ружья – и полюбуйтесь на море.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3452, 'Защита пламени', 'Работа над факелом близится к завершению. Не хватет лишь одного компонента. $B$BВ горах к северо-западу отсюда есть большой лагерь Сумеречного Молота. Говорят, они носят при себе некие символы и идолов в дань уважения своему богу. Полагаю, в этих символах и идолах заключены чары достаточной силы для создания магической брони. Принеси мне знак Рагнароса, и я попытаюсь извлечь из него его магическую силу, чтобы создать защитные чары для факела.', 'Найдите знак Рагнароса и принесите его Велароку Ветрорезу.', 'Символ источает злые чары – именно они и требуются для завершения работы над факелом.', 'Факел воздаяния не будет работать без источника магической энергии.', NULL, NULL, 'Знак Рагнароса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3453, 'Факел воздаяния', 'Мне нужно несколько минут, чтобы сложить вместе все части и наложить чары.', 'Подождите, пока Веларок Ветрорез закончит факел воздаяния.', 'Есть еще одно, последнее задание, которое ты должен выполнить.', NULL, NULL, NULL, 'Создание факела', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3454, 'Факел воздаяния', 'Факел готов и отныне связан со своим владельцем. Возьми его, $N.', 'Возьмите факел воздаяния.', 'Вы хватаете факел обеими руками и ощущаете исходящие от него волны гнева и ненависти.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3461, 'Возвращение к Тимору', 'Тимор не оставил мне ничего, чтобы вам заплатить, потому предлагаю вам обсудить награду лично с ним, когда вернетесь в Стальгорн. Я уверен, что он до сих пор у себя в Палатах Магии. Постучитесь и потребуйте щедрой платы, потому как местечко-то не для пикника... это уж точно.$B$BВсе же благодарю вас, что вы ему помогли, и желаю удачи.$B$BОй, готовальня мне ни к чему. Почему бы вам просто не отдать ее лично Тимору, когда вы с ним встретитесь?', 'Принесите Тимору его готовальню назад в Стальгорн.', 'Отлично! Я так рад это слышать.$B$BКак мне не терпится вернуться в мою башню и поработать над прорисовками... Я так завидую вам! Побывать в Азшаре... думаю, это мечта всех изучающих чародейские науки.$B$BЛадно, хотя мы и не говорили о награде, поскольку вы работаете на лигу Исследователей, но вы ее заслуживаете.', 'Вы вернулись! Замечательно. А готовальню мою принесли?', NULL, NULL, 'Набор для рисования (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3462, 'Оруженосец Малтрейк', 'Поговори с моим посыльным, оруженосцем Малтрейком. Он объяснит тебе, как использовать факел.', 'Поговорите с оруженосцем Малтрейком.', 'Ты готов нанести удар?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3463, 'Задай им жару!', 'Слушай меня внимательно, $N. Четыре башни нельзя разрушить, но если поджечь их с помощью факела воздаяния, пламя не угаснет очень долго - и это пламя нельзя будет унять никакими силами. $B$BПока башни горят, ни один страж или караульный не сможет подняться на них - а значит, первая линия обороны противника фактически будет прорвана. $B$BТы $gдолжен:должна: пробраться в башни и поджечь их с помощью факела воздаяния. И берегись патрульных Черного Железа!', 'Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния.', 'Отлично! С тобой можно идти в разведку, $N!', 'Ты потерял дорогу, $N?', NULL, NULL, 'Западная башня подожжена', 'Южная башня подожжена', 'Восточная башня подожжена', 'Северная башня подожжена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3481, 'Безделушки...', 'Похоже, сундук заперт.', 'Открыть сундук.', 'Замок открывается, как только вы прикасаетесь к нему. Любопытно, сколько же может быть внутри сокровищ? Есть только один способ узнать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3482, '', 'Версия задания с черным ящиком для Орды.', 'Отнесите ящик Крейвелу.', '', NULL, NULL, NULL, 'Щербатая черная коробка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3483, 'Сигнал \"Взять на борт!\"', '', '', 'Еще одно сигнальное ружье, да? Это можно.И не забудьте – южная оконечность Азшары. Этот крохотный островок переделан в посадочную площадку. Вы ее не пропустите, если окажетесь в нужном месте.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3501, 'Счет идет на большие числа', 'Быть может, ты никогда не найдешь безупречную сферу из дренетиста, однако во время скитаний по этим землям тебе, несомненно, удастся обнаружить различные несовершенные фрагменты дренетиста.$B$BХотя сомнительно, что Кум\'иша сможет использовать эти несовершенные фрагменты для возвращения домой, эти осколки могут сослужить иную, весьма полезную службу для дренеев.$B$BПринеси любой несовершенный фрагмент дренетиста, который найдешь, и я вознагражу тебя.', 'Принесите Кум\'ише несовершенные фрагменты дренетиста и получите награду за каждый из них.', 'Ты разочаровываешь меня, $R. Такой большой, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих!', 'Повезло ли тебе в поисках?', NULL, NULL, 'Несовершенный фрагмент дренетиста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3502, 'Дренейский хлам...', 'Ну-с, узрев проявление этой ненасытной жадности, я не могу сдержать отвращение.$B$BИ тем не менее я не намерен долго задерживаться на твоем пристрастии к материальным благам.$B$BЗа каждый несовершенный фрагмент дренейского аметиста, который ты принесешь, я вознагражу тебя каким-нибудь хламом. Моя груда хлама будет уменьшаться, а твоя – расти. На Дреноре такая ситуация называлась \"все в выигрыше\".', 'Принесите Кум\'ише несовершенные фрагменты дренетиста. У любого вида монстров в Выжженных землях могут быть эти фрагменты.', 'Ты разочаровываешь меня, $R. Такой большой, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих.$B$BЗнакомые слова? А как же – я повторяю их тысячу раз на дню.$B$BО, как мне отвратителен этот мир!', 'Ну? Дренейский аметист? Помнишь?$B$B*Кум-иша сжимает кулак и стучит тебя по голове.*$B$BЕсть кто-нибудь дома?', NULL, NULL, 'Несовершенный фрагмент дренетиста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3503, 'Встреча с господином', '', '', 'Да, уж не вернуть тех дней, когда я мог требовать с желающих видеть моего господина все, что заблагорассудится. Теперь-то я отправляю к нему любой сброд – только попроси! Как меня это бесит! Но приказы не обсуждаются. Я могу потешить себя лишь глумясь над твоей безвкусной одеждой и жалким выражением лица. Впрочем, мне и это уже наскучило! И необходимость трепаться тут с тобой меня бесит! Будешь телепортироваться к господину или нет?!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3504, 'Предательница', 'Предательница и воровка! Других слов для нее у меня нет!$B$BНаверное, я сделал большую ошибку, $N. Я доверился эльфу крови.$B$BОна уверяла, будто в Азшаре хранятся несметные сокровища... могущественные артефакты... Все, что нужно, – это отправить с ней нескольких воинов для охраны, и она меня щедро вознаградит. Ну, и кто остался в дураках? Она их всех перебила!$B$BЯ жажду мести, $N. Но посылать туда других воинов я уже не могу. Найди Аг\'тора в Храбростане, к северу от лагеря Халдарр. Он тебе скажет, что делать дальше.', 'Отнесите запечатанное письмо Аг\'тору Кровопалу в Азшару.', 'Мы уже многих посылали против нее и ее приспешников, но они слишком сильны! Никто из посланных не вернулся. Наверное, некоторые погибли, но большинство, подозреваю, просто сбежали. Трусы!$B$BОднако теперь, когда прибыло подкрепление, у нас снова появилась надежда. Быть может, мы все-таки сумеем с ней разобраться.$B$BНу так что, ты с нами?', 'А-а, Белгром наконец-то прислал кого-то стороннего, не из своих солдат?$B$BРаньше в этом лагере было двенадцать воинов, $N, но теперь они все мертвы! Эта магичка, Римтори, погубила всех! Белгрома она обвела вокруг пальца... собственно, она его соблазнила. Не мое это дело, но, между нами говоря, стерва она изрядная. Потому я и продолжаю помогать Белгрому. На его месте я бы, наверное, сделал то же самое.', NULL, NULL, 'Запечатанное письмо Аг\'тору (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3505, 'Предательница', 'Так я и думал.$B$BМы начнем наступать на ее приспешников от южных утесов северного полуострова Азшары. Убивайте их, не зная пощады – пусть знают, кого предали!$B$BНасчет ее самой пока не тревожьтесь – она проводит большую часть времени, рыская по Азшаре вместе со своими телохранителями. После того как перебьете ее работников, стоит отыскать ее личный лагерь. Нужно сначала разведать, откуда можно на нее напасть. Может быть, стоит как-нибудь выманить ее из лагеря...', 'Убейте 10 эльфов крови-землемеров и 10 эльфов крови-геодезистов, потом разыщите лагерь волхва Римтори. В лагере найдите что-нибудь важное для мага, из-за чего она могла бы ринуться в бой.', 'Вы начинаете листать страницы и обнаруживаете, что одна из них заложена узкой ленточкой черного шелка.$B$BВы пытаетесь разобрать непонятные слова и видите на одной из страниц схему. Присмотревшись, вы понимаете, что кристаллы, круг и некоторые другие компоненты, лежащие на земле, расположены так же, как на рисунке.', 'Заглавие этой книги написано золотом по черной кожаной обложке: \"кальдорайский фолиант Призыва\". Открыв книгу, вы обнаружили, что она древняя, но превосходно сохранилась.$B$BТекст, по-видимому, на каком-то древнем языке... кальдорайском, наверное?$B$BИнстинкт подсказывает вам, что, когда вы покончите с местью, сюда стоит вернуться снова.', NULL, NULL, 'Эльф крови - землемер убито', 'Эльф крови - геодезист убито', 'Исследовать локацию', 'Найдите лагерь волхва Римтори.');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3506, 'Предательница', 'Вы поразмыслили еще немного, и вам на ум пришло сразу несколько идей, одна из которых заставила улыбнуться: возможно, если вы уничтожите кристаллы, подлая эльфийка, погубившая стольких орков, достаточно разозлится?$B$BВы продолжаете разбирать текст и рисунки и понимаете, что один из кристаллов связан с создателем круга – прочие же связаны с куда более жуткими тварями.$B$BВы закрываете книгу и начинаете прикидывать, какой из кристаллов следует уничтожить.', 'Уничтожьте кристалл средоточия чар, связанный с волхвом Римтори, затем убейте ее. Отнесите голову Римтори Аг\'тору Кроволапу в Азшаре.', 'Ага!!! Невероятно!$B$BТебе это удалось! То-то Белгром обрадуется! Наконец-то души десятков наших воинов упокоятся в мире. Спасибо тебе, $N.', 'Ну что, $N, много тебе удалось перебить этих эльфов-предателей?$B$BЯ надеюсь, что именно у тебя хватит сил поставить эту мерзавку на колени! За все, что она натворила, она заслуживает самой мучительной смерти!', NULL, NULL, 'Голова волхва Римтори', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3507, 'Предательница', 'Вернись в Оргриммар к Белгрому. Он захочет увидеть ее голову своими глазами! Мы там тоже скоро будем.$B$BУдачный у нас денек! Спасибо за помощь, $N.', 'Поговорите с Белгромом Каменной Булавой в Оргриммаре.', 'Ха-ха-ха! Вот и ты, жалкая девчонка! Я плюю на твои останки!$B$BСпасибо, $N. Я благодарю тебя от всей души! Это воистину великий день!$B$BБудь это в моей власти, я наградил бы тебя целым королевством! Но, может быть, ты согласишься на это?$B$B*Белгром смотрит на голову мага, который предал его.*$B$BХа-ха! Глупая эльфийка! Вот что с тобой стало! В парусиновом мешке, голова отдельно, тело отдельно! Не надо было предавать Белгрома!', 'Да, $C, я тебя помню. Я просил тебя отправиться в Азшару и уничтожить ту негодяйку, которая предала меня! Кажется, будто это было много лун тому назад... Только не говори мне, что Аг\'тор и остальные тоже мертвы!', NULL, NULL, 'Голова волхва Римтори (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3508, 'Минуя охрану', 'Тебе свойственна безрассудная храбрость, $N. Это ценное качество твоего рода – слепо кидаться в битву, почти не имея шансов на успех. Я помогу тебе, хотя бы только ради того, чтобы увидеть смерть приспешников Разелиха. $B$BОднако для того, чтобы пробиться через охранные чары, окружающие их, требуется время, равно как и использование редких артефактов.$B$BНе нарушай тишину, я должен исполнить ритуал просветления. Сведения, которые я получу, помогут мне отковать оружие великой мощи.', 'Подождите, пока Лорамус завершит заклинание просветления.', 'Необходимо отыскать имя зверя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3509, 'Имя Зверя', 'Существует лишь один способ причинить вред повелителю демонов и его приспешникам. Следует выковать оружие силы, несущее его истинное имя.$B$BКогда такое оружие будет выковано, демон и все, кем он повелевает, станут уязвимы. $B$BВ Азшаре обитает меньшее божество: лорд Арккорос. Тебе следует найти его. Однако осторожнее: его слуги не остановятся ни перед чем, чтобы убить тебя, если обнаружат.$B$BНесомненно, за такие сведения придется заплатить.', 'Поговорите в Азшаре с лордом Арккоросом. Начните поиски у кромки воды, чтобы найти храм Арккоран.', 'Повелитель демонов?$B$B*Лорд Арккорос смеется.*$B$BБыть может, кое-кто сможет помочь тебе этими сведениями; но сначала ты должен помочь кое-кому.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3510, 'Имя Зверя', 'Она убивает моих детей. Она называет себя повелительницей океанов. Фальшивая богиня, и ничего более. Сокруши ее и принеси мне все ее головы.$B$BЗа это ты получишь то имя, которое тебе нужно, и кое-что еще, не менее важное.$B$BОна бродит вокруг гнезда... Она зовется Хетайра.$B$B*Лорд Арккорос указывает на юго-запад.*$B$BИди!', 'Убейте Хетайру и принесите окровавленную голову Хетайры, разбитую голову Хетайры и покрытую синяками голову Хетайры лорду Арккоросу.', 'Наконец-то хоть кто-то достойный мудрости Арккороса!', '*Лорд Арккорос склоняется, чтобы лучше видеть тебя.*$B$BГде они?', NULL, NULL, 'Разбитая голова Хетайры', 'Окровавленная голова Хетайры', 'Покрытая синяками голова Хетайры', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3511, 'Имя Зверя', 'Как и обещал, я открою тебе имя Повелителя демонов Разелиха Осквернителя. Однако сначала я должен приготовить кое-что необычайно важное для твоего путешествия.$B$BДля создания оружия, которое ты ищешь, необходим состав для закалки. Подожди немного, я выжму кровь из этих голов.$B$B*Лорд Арккорос сжимает головы между своими гигантскими ладонями, выдавливая из них кровь.*$B$BДоставь этот состав для закалки Лорамусу вместе с именем зверя: Рах\'лих.', 'Отнесите состав для закалки Лорамусу Многоногу.', 'Этот состав содержит протравку, необходимую нас для отковки оружия. Это еще один шаг к созданию сего оружия.', 'С возвращением! Я рад видеть тебя, $R. Тебе удалось узнать подлинное имя?', NULL, NULL, 'Кровь Хетайры (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3512, 'Судя по словам Эраникуса...', '$N, нашим первым шагом будет разработка способа связаться с Эраникусом через этот камень. Он сейчас находится на зыбкой грани между сном и смертью, в сетях кошмаров. Хотя принесенная тобою сущность сильно поражена порчей, все еще есть шанс, что мы дотянемся до Эраникуса.$B$BТебе придется отправиться далеко на север и к востоку от Зимних ключей разыскать нашего смертного союзника, Умбранса Ищущего Духов. Он умеет говорить с мертвыми. Хотя Эраникус и не вполне мертв, этот человек все же сможет нам помочь.', 'Отправляйтесь в восточную часть Зимних Ключей и поговорите с Умбрансом Ищущим Духов.', 'Хорошо, что Итар послал тебя ко мне. Хотя Эраникус и не мертв в общем смысле этого слова, я смогу поговорить с ним. Но прямо сейчас я не могу помочь тебе...$B$BЯ с удовольствием это сделаю, но сначала мне самому нужна помощь того, кто, в отличие от меня, не скован старческой немощью. Мой наиболее ценный гадальный инструмент был у меня украден, и, пока я не заполучу его обратно, я бессилен помочь Эраникусу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3513, 'Свиток с рунами', 'Свиток официального вида перевязан серебристой лентой. Несомненно, кому-то он был бы весьма интересен, но кому?$B$BНа севере, рядом с границей Ясеневого леса, есть застава, и если в свитке идет речь о ночных эльфах, именно туда его и надо отнести.', 'Отнесите свиток с рунами в северную сторожевую башню Степей.', 'Та-ак... И где ты это нашел?', 'Что это?', NULL, NULL, 'Свиток с рунами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3514, 'Мощь Орды', 'Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Логова Когтя на Пике Каменного Когтя.$B$BОна уже не встретится с гонцом, у которого ты нашел этот свиток, хе-хе, но так просто им это не пройдет. Орда не потерпит такого нахальства.$B$BСтупай в Логово Когтя, $N. Убей Ринтариэль и покажи это всем. Возьми с собой флаг Орды и установи его в Логове Когтя у всех на виду. В другой раз они трижды подумают, прежде чем снова соваться в наши земли.', 'Убейте предводительницу Логова Когтя, Ринтариэль Хранительницу Ключей.', 'Да ты силен! Это большое дело – лишить Логово Когтя Ринтариэль. Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса. Они подумают дважды, чем прежде чем снова соваться к нам.$B$BСпасибо.', NULL, NULL, NULL, 'Ринтариэль Хранительница Ключей убито', 'Флаг Кадрака', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3517, 'Тайненькое знаньице', 'Ты знаешь, $N, я, в общем, неплохо устроилась в Азшаре. У наказания Белгрома, обрушившегося на мою голову, есть свои положительные стороны. $B$BЯ тут полазала по окрестностям и обнаружила просто уйму ценностей, валяющихся без дела. $B$BЕсли интересно, могу рассказать подробнее и даже поделюсь прибылью, если поможешь мне добыть кое-что. $B$BВ руинах Эльдарата к востоку отсюда сокрыты четыре таблички. Каждая из них носит имя мага высокорожденных. Принеси мне их, и мы поговорим о дальнейшем сотрудничестве.', 'Найдите таблички Бет\'Амары, Джин\'яэль, Маркри и Саэль\'Хай и принесите их Джедиге в Азшару.', 'Отлично, $N, ты принес все таблички, и они в хорошем состоянии. Мы получим за них хорошую цену. $B$BНу, не будем тратить время зря. Пора обменять таблички на денежки!', 'У меня есть знакомые, которые готовы отвалить за таблички неплохой куш. Я скажу тебе, кому нужно их доставить. Только без дураков, получишь свою долю после того, как принесешь мне расписку от клиента. $B$BПоторапливайся, время не ждет! А не то найду еще кого-нибудь в помощники!', NULL, NULL, 'Табличка Бет\'Амары', 'Табличка Джин\'яэль', 'Табличка Маркри', 'Табличка Саэль\'Хай');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3518, 'Доставка Магате', 'Первую табличку нужно отнести таурену по имени Магата. Ты найдешь ее среди старейшин Громового Утеса. Она самая ярая сторонница заключения союза тауренов с Отрекшимися, ибо считает, что именно таурены и их обычаи могут помочь Отрекшимся вновь найти путь к обретению человеческой природы. $B$BОтнеси ей табличку Бет\'Амары. Тауренка считает, что может найти в табличке способ, как помочь Отрекшимся... ну да, по крайней мере она в это верит.', 'Отнесите табличку Бет\'Амары Магате в Громовой Утес.', 'О, наконец-то! Табличка Бет\'Амары! А я уж гадала, неужели орк не сдержала обещания, или, чего доброго, бедняжка нашла кончину в Азшаре. Я рада, что ей удалось. $B$BБет\'Амара был одним из самых могущественных алхимиков высокорожденных. Говорят, что он единственный овладел искусством трансмутации металлов.', 'Приветствую тебя, $N. Чем я могу помочь тебе? Говори быстрее, у меня много дел.', NULL, NULL, 'Табличка Бет\'Амары (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3519, 'Друг в беде', 'Ох... меня сильно покусала паучиха по имени Гитьис Зловещая, когда я обследовал паучиную пещеру. Похоже, я серьезно отравлен. Помоги мне!$B$BПожалуйста, дай знать Дирании Серебряному Сиянию. Она сможет помочь мне.$B$BСпеши... Как голова кружится…', 'Поговорите с Диранией Серебряным Сиянием в Тенистой долине.', 'Ох, какая беда, а я-то думала, что это сегодня Иверрона не видно... Предупреждала же я его насчет пауков!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3520, 'Духи крикунов', 'Мне нужны духи дольных крикунов из Фераласа. Они родственники старого-престарого бога и напрямую связаны с ним.$B$BВозьми ежевичный посох и ступай в Фералас. Отыщи в южной и центральной части дольных крикунов и одержи над ними верх. Потом помаши моим посохом над их телами. Таким образом ты выманишь их души. Коснись каждой из душ и собери их сущности.$B$BПринеси мне посох и собранные сущности, и я расскажу тебе о том старом боге.', 'Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе\'кинье в Порт Картеля.', 'Молодец, $N. Пожалуй, пришло время рассказать тебе правду…$B$BУ троллей существует пророчество о возвращении на землю убитого бога, Хаккара Свежевателя Душ. Некоторые говорят, что пришествие Хаккара принесет троллям радость и славу, другие же ждут лишь конца всего сущего.$B$BЯ не верю в этот миф, но не сомневаюсь, что сущность Хаккара таит в себе великую силу, которая не должна попасть в руки недостойных...', 'Ты несешь мне сущность дольных крикунов, $N?', NULL, NULL, 'Поймано душ крикунов', 'Колючка Йе\'кинья (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3521, 'Противоядие для Иверрона', 'Мы могли бы помочь Иверрону: я знаю противоядие, которое нейтрализует действие яда. Но для него мне нужны некоторые ингредиенты.$B$BМне понадобятся гиацинтовые грибы. Их можно найти под деревьями или добыть у греллей к югу отсюда – похоже, они им по вкусу. Еще мне нужны лунные лилии, что растут только вокруг прудов.$B$BПоследний ингредиент добыть сложнее всего. Это лимфа тех самых чащобных тенетников, что отравили Иверрона.', 'Соберите 7 гиацинтовых грибов, 4 лунные лилии и 1 порцию лимфы чащобного тенетника и принесите Дирании Серебряное Сияние в Тенистую долину.', 'Хвала Элуне – ты так быстро собрал все ингредиенты!$B$BПодожди минутку, сейчас я приготовлю противоядие.', 'Пожалуйста, принеси мне все эти ингредиенты, $N. Иверрону нужна наша помощь!', NULL, NULL, 'Гиацинтовый гриб', 'Лунная лилия', 'Лимфа чащобного тенетника', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3522, 'Противоядие для Иверрона', 'Противоядие готово, $N. Пожалуйста, проследи, чтобы Иверрон его выпил.$B$BИ запомни – это важно: противоядие будет обладать своими целебными свойствами в течение пяти минут. Необходимо доставить его до истечения этого времени.$B$BПоторопись, во имя Элуны!', 'Отнесите противоядие Иверрону, прежде чем оно потеряет свои целебные свойства. Иверрона можно найти около пещеры, что к северу отсюда.', 'Что это, $N?$B$BЯ знал, что Дирания поможет мне!$B$B*Иверрон выпивает противоядие.*$B$BЯ все время попадаю в переделки, а Дирания постоянно меня из них вытаскивает.$B$BМне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя. Что ж, надеюсь, ты расчистил мне дорогу через этот лес, полный мерзостных чащобных тенетников...', 'О... $N, какое счастье, что ты вернулся...', NULL, NULL, 'Противоядие для Иверрона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3523, 'Плеть в холмах', 'Благодарю, что $gспас:спасла: меня! Имя мне Белнистраз. Не хотелось бы закончить жизнь столь бесславно – быть сожранным одной из омерзительных тварей Плети. Да-да, ты не $gослышался:ослышалась:, Плеть вступила в союз с местными свинобразами.$B$BПослушай... вместо того, чтобы бежать, спасая собственную жизнь, я бы предпочел вступить с врагом в бой, чтобы защитить невинных. Не желаешь ли ты мне помочь? Это опасно, но ты явно не из тех, кто пасует перед трудностями.', 'Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам.', 'Весьма похвально, $N. Я знал, что из тех, кто захочет взяться за это непростое и опасное дело. Не скрою, нам предстоит тяжелая работа. Но мы должны приложить все усилия и справиться с ней. $B$BПослушай, я введу тебя в курс дела...', 'Я далек от политики. Мне нет дела до того, связан ли ты с Ордой или Альянсом. Все, чего я хочу – уничтожить прямую и неотвратимую угрозу всем расам этого мира. $B$BЕсли ты хочешь стать героем для всех народов, отдай мне Камень клятвы, который получил от меня в знак своего согласия. Я... не из здешних мест; у нас принято скреплять договоренности Камнем клятвы.', NULL, NULL, 'Камень Клятвы Белнистраза (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3524, 'Останки на берегу', 'Громадные морские твари выбрасываются на пески Темных берегов и лежат там, пока не умирают. В последнее время останки этих тварей выносит на берег все чаще и чаще. Меня послали сюда из Храма Луны для расследования ситуации, но наличие мурлоков у береговой линии затрудняет мою задачу.$B$BОдни такие останки лежат на юге от Аубердина, совсем рядом, но вокруг очень много злобных мурлоков из племени Серой Мглы. Можешь сходить туда и принести мне для изучения кости этой твари?', 'Соберите кости морской твари, выброшенной на берег к югу от Аубердина, и принесите их Гвеннид Блай\'Леггонд в Аубердин.', 'Я надеюсь, что мурлоки не слишком досаждали вам, пока вы собирали для нас эти кости! Я непременно следующим же гиппогрифом доставлю их в Дарнасс. Храм Луны снабдил меня некоторыми средствами, которыми я могла бы расплачиваться за помощь; пожалуйста, примите немного денег вместе с нашей благодарностью.$B$BВаш успех побуждает меня предложить вам возможность и дальше оказывать помощь Храму Луны, если вы заинтересованы в этом...', 'Эти морские твари только недавно стали приплывать на отмели Темного Берега в таких тревожно больших количествах. Не могу сказать точно, но думаю, что это своего рода дурное предзнаменование. Извлечение образцов костей такой твари, что лежит к югу отсюда, поможет нам в Дарнассе оценить ситуацию!', NULL, NULL, 'Кости морской твари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3525, 'Уничтожить идола', 'Рядом с входом ты увидишь идола – свинобразы используют его как жертвенный очаг. Эти твари на самом деле пожирают своих пленников из Степей. Я должен разбить идола, чтобы они более никогда не могли его использовать, но мне потребуется твоя помощь. Сопроводи меня к идолу. Там я проведу ритуал, но при этом я даже не смогу говорить с тобой, не говоря уж о том, чтобы самому защитить себя. Тебе придется держать оборону, пока я буду проводить ритуал. Если меня убьют раньше, чем я закончу, это будет означать крах всех наших планов.$B$BТы $gготов:готова:?', 'Сопроводите Белнистраза к идолу свинобразов в Курганах Иглошкурых. Защищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.', 'Белнистраз исчезает, оставив на месте себя пылающее зарево. Вы видите в пламени очертания огромного крылатого красного дракона. Рокочущий голос Белнистраза наполняет ваше сознание.$B$B\"Я всегда верил в вашу смелость, смертные. Благодаря тебе кровавым делам, вершимым здесь этими тварями, пришел конец. Моя вера в мужественность смертных созданий сегодня укрепилась. Прими эту награду – она достойна героя.\"', NULL, NULL, NULL, 'Защищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3526, 'Гоблинское инженерное дело', 'Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!$B$BПрочитай этот учебник, $N. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.', 'Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.', 'Что же, $N, ты нашел подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (повторяю: ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела.$B$BДержи ушки на макушке, $N, тогда чему-нибудь научишься.', 'Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?', NULL, NULL, 'Справочник по инженерным дисциплинам (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3527, 'Пророчество Мошару', 'Древнее пророчество Мошару повествует о том, как взять в плен сущность бога Хаккара. Пророчество записали на двух табличках и отнесли в тролльский город Зул\'Фаррак, что к западу от Прибамбасска.$B$BПринеси мне таблички Мошару!$B$BПервая табличка находится у давно умершего тролля Теки Мученика. Говорят, что его истязатели превратились в скарабеев и до сих пор ползают по его святилищу.$B$BВторая табличка – у гидроманта Велраты, рядом со священным озером Газ\'риллы.$B$BДобудешь таблички – сразу приходи.', 'Принесите первую и вторую таблички Мошару Йе\'кинье в Танарис.', 'О, замечательно. Я соединю эти таблички и раскрою их секреты.$B$BЯ давно твой должник, $N. И, боюсь, мой долг будет только расти.', 'Ты несешь мне таблички пророчества $N?$B$BЯ хочу изучить их и понять, как сковать сущность Хаккара!', NULL, NULL, 'Первая табличка Мошару', 'Вторая табличка Мошару', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3528, 'Бог Хаккар', 'Пришло время брать в плен сущность аватары Хаккара.$B$BОтнеси яйцо Хаккара в святилище Падшего бога в Затонувшем храме Азерота. Призови силу яйца и разбуди мертвого бога.$B$BОн пошлет против тебя своих прислужников. Одолей их и нацеди из них крови. Угаси при помощи этой крови вечный огонь, в котором заключен дух Хаккара. Когда пламя погаснет, в мир войдет аватара Хаккара.$B$BПобеди его и помести его сущность в яйцо Хаккара.', 'Отнесите заполненное яйцо Хаккара Йе\'кинье в Танарис.', 'Значит, сущность Хаккара заключена в яйцо! Смотри, как в Яйце пульсирует жизнь! Неужели мифы о Хаккаре правда?$B$BНе может быть, ведь в таком случае Хаккар может возродиться. Я буду хранить это яйцо как зеницу ока, чтобы оно не попало в недобрые руки.$B$BНаша совместная работа подошла к концу, $N. Ты прикоснулся к легенде, быть может, твои подвиги однажды изменят облик нашего мира.', 'Тебе удалось победить аватару Хаккара, $N? Заряжено ли это яйцо его сущностью?', NULL, NULL, 'Заполненное яйцо Хаккара', 'Яйцо Хаккара', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3541, 'Доставка Джес\'римону', 'В Оргриммаре есть у меня скупщик краденого. У него притон в Волоке. Этого скользкого типа нелегко найти, если не знать точно где искать. Запомни: искать следует в одном из самых высоких зданий. $B$BТолько сделай мне одолжение, не ори на весь Калимдор, где он и чем занимается – это было бы... весьма неприятно для нас обоих. $B$BОн готов заплатить очень хорошую цену за табличку Джин\'яэль. Не знаю, зачем уж она ему сдалась, но $gвидел:видела: бы ты, как у него загорелись глаза, когда я упомянула, что знаю, где ее найти!', 'Отнесите табличку Джин\'яэль Джес\'римону в Оргриммар.', 'Ага, Джедига прислала мне посылку... Великолепно, я ждал ее. $B$BДа, Джедига славная бабенка! Свирепая как волчица... что может быть лучше? $B$BКак я погляжу, табличка в целости и сохранности. А что это значит, $N? Значит, посыльный получит на магарыч!', 'Ну, что тебе нужно, тля? У меня на сегодня уйма дел, и ты в их число не входишь. Впрочем, если будешь путаться под ногами, найдется и на тебя минутка!', NULL, NULL, 'Табличка Джин\'яэль (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3542, 'Доставка Андрону Ганту', 'Теперь ты отправишься к Андрону Ганту. Он обретается в Подгороде, недалеко от Района Фармацевтов. $B$BЭтот был более многословен, когда я спросила, зачем ему нужна табличка. Маги Подгорода хотят изучить некоторые тайные заклинания высокорожденных. Они считают, что табличка им в этом поможет. Маркри был очень талантлив в чарах призыва различных существ, особенно элементалей. $B$BОтнеси ему табличку Маркри и возвращайся за своей долей.', 'Отнесите табличку Маркри Андрону Ганту в Подгород.', 'Вот, возьми пару монет... *ик*... купи себе новую броню... или шляпу. $B$BНичего не жаль для хороших посыльных!', 'Ого... *ик* вот так сюрприз! *ик* Да у меня гости! *ик* Чем, так сказать, могу?.. *ик*', NULL, NULL, 'Табличка Маркри (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3561, 'Доставка верховному магу Ксилему', 'Последнюю табличку надлежит доставить весьма опасному человеку, $N. Можешь не сомневаться, я доверяю ему куда меньше,чем кому-либо из тех, к кому я тебя отправляла. $B$BВерховный маг Ксилем живет в башне в холмах, возвышающихся над Азшарой. Он человек, однако он не похож на людей, которых мне приходилось встречать... или убивать. Он необычайно властен. Я не смею спросить его, что он собирается делать с табличкой. $B$BОн сказал мне, что страж его, Санат, поможет мне попасть в его башню, когда я буду готова предстать перед ним. Ищи Саната на севере.', 'Отнесите табличку Саэль\'Хай верховному магу Ксилему в Азшару.', 'О, табличка Саэль\'Хай... как давно я мечтал изучить ее! $B$BБлагодарю тебя, $N. Скажи Джедиге, что я доволен работой. Орк заслужила свою награду.', 'Чем ты явился ко мне, $N?', NULL, NULL, 'Табличка Саэль\'Хай (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3562, 'Плата Магаты Джедиге', 'Отнеси это послание Джедиге. Скажи ей, что я заплачу ей лично, когда она придет ко мне.$B$BСтупай скорее, $N. Скажи своей госпоже, что награда ожидает ее.', 'Отнесите записку Магаты Джедиге в Азшару.', 'А, отлично. Она поступила вполне разумно. По крайней мене по отношению к тебе. Я побаивалась, что она сделает с тобой что-нибудь неприятное, чтобы наказать меня за высокомерие. Она любит, чтобы к ней являлись лично, а не отправляли мальчиков на побегушках. Похоже, она действительно обрадовалась табличке. $B$BЧто ж, посмотрим.', 'Что сказала Магата? Старая карга наверняка выбрала словечко покрепче...', NULL, NULL, 'Записка Магаты (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3563, 'Плата Джес\'римона Джедиге', 'Отнеси это послание Джедиге. Скажи ей, что я доволен ее работой.$B$BСкажи, чтобы скорее возвращалась в Оргриммар – Джес\'римон достойно наградит ее. $B$BПередай ей это, и, возможно, впредь я буду давать тебе поручения, $N.', 'Доставьте записку Джес\'римона Джедиге в Азшару.', 'Судя по этому письму, Джесримон весьма доволен нашей работой... $B$BЗнал бы он как я довольна работой, которую он мне дает... Ну, теперь у меня есть еще одна причина задержаться в Азшаре. $B$BВот, забирай свою долю.', 'Ты говорил с Джес\'римоном? $B$BСреди троллей он реальный кабан, однако за работу платит хорошо и аккуратно. $B$BЕсли сможешь выдержать его манеры, непременно заработаешь хороший барыш на выполнении его поручений.', NULL, NULL, 'Записка Джес\'римона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3564, 'Плата Андрона Джедиге', 'Вот *ик!* держи *ик!* Это для Джедиги. И ты это, *ик* заходи, если что!', 'Доставьте записку Андрона Джедиге в Азшару.', 'Отлично... ого, это еще что! $B$BХа-ха! Что ты сказал ему, когда отдавал табличку, $N? Он заплатил нам едва ли не дважды сверх уговоренного! Нет, я конечно, не жалуюсь... Ты сказал ему, что я изменила условия сделки? Или этот пьянчуга опять шары залил и не соображал, что делает? $B$BНу, уже неважно. Вот, держи свою долю – с премией!', 'Ну что, ты говорил с Андроном? Он редко покидает Подгород, так что не думаю, что его будет сложно найти.', NULL, NULL, 'Записка Андрона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3565, 'Плата Ксилема Джедиге', 'Что еще? Ах да, оплата. Конечно. $B$BВот, возьми и выметайся. Уверен, Джедига ждет не дождется твоего возвращения.', 'Доставь записку Ксилема Джедиге в Азшару.', 'Что, в самом деле не случилось ничего неприятного? И он отдал тебе деньги не торгуясь? Ушам не верю... Я, честно признаться, ожидала какого-то подвоха. Похоже, с ним все же можно иметь дело. $B$BВот, держи свою награду. Спасибо за помощь.', 'Ну, что сказал тебе $N? Ничего с тобой не сделал? Не пытался заманить тебя к себе в услужение?', NULL, NULL, 'Записка Ксилема (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3566, 'Восстань, Обсидион!', 'Это... была... ловушка... $B$BПрости... меня... $B$BТы $gдолжен:должна: убить предателя... Отомсти ему за нас... За Ториуса...', 'Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн.', '*Ториус бледнеет.*$B$BЭтого не может быть... Мой единокровный брат! Неужели он мог это сделать?! $B$B*Лицо Ториуса искажает ярость*$B$BОн предал меня, он предал Стальгорн! Видимо, влияние Древних Богов еще сильно в этих землях.Боюсь, если даже мой брат – некогда благородный и уважаемый человек – так легко поддался воле Рагнароса, никто их нас не может чувствовать себя в безопасности!', 'Я не верю! Ты можешь доказать, что это не ложь?', NULL, NULL, 'Голова Латорика Черного', 'Сердце Обсидиона', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3567, 'Умный в гору не пойдет...', '', '', 'Хочешь посмотреть, какой вид открывается во-он оттуда, с тех Двух Колоссов? Могу тебя туда отправить, $R.Только подумай заранее, как потом будешь спускаться. Это путешествие в один конец!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3568, 'Разносчик порчи', 'Видишь этого несчастного таурена? Она недавно побывала в Азшаре. Среди руин Эльдарата она была ранена в бою с нагами.$B$BОтбившись от них, она решила отдохнуть на берегу и попила водички из приливной заводи. Теперь ее тошнит... помимо всего прочего.$B$BМне нужно выяснить, что она пила. Возьми этот ящик, в нем несколько помеченных фиалов. Наполни их из разных заводей и возвращайся.', 'Наполните все 4 пустых фиала из приливных заводей в руинах Эльдарата и возвращайтесь к химику Карабосу.', 'Чудесно. Ты успел вернуться до ее гибели. Славно, славно.$B$BЗначит, пора приступать.$B$BЯ некоторое время изучал симптомы ее болезни, и теперь дело совсем плохо. Удивительно, как она на ногах держится. Ее уже три или четыре раза вырвало... запах просто чудесный.$B$BДай-ка я состряпаю что-нибудь для нашей... подруги.', 'Ты ведь догадываешься, к чему все идет, $N? Ей не выжить... видно с первого взгляда. Лучшее, что она может сделать, – это помочь нам отыскать лекарство от чумы. Быть может, в воде, которую она пила, мы найдем намеки на то, как можно получить рецепт? Если все равно помирать, почему бы не сделать перед смертью доброе дело для своего народа? Ты согласен?', NULL, NULL, 'Наполненный фиал номер 1', 'Наполненный фиал номер 2', 'Наполненный фиал номер 3', 'Наполненный фиал номер 4');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3569, 'Разносчик порчи', 'Отнеси эликсир Терсе – вдруг он ей поможет? Пока она не выпьет его, точно не скажешь.', 'Дайте эликсир Карабоса Терсе Песне Ветра в Подгороде.', 'Химик Карабос – само гостеприимство... даже не по себе стало. Но если он говорит, что есть шанс излечиться, выбора нет. Искать другие лекарства нет времени. Ни жрецы, ни шаманы не смогли мне помочь.$B$BБудем надеяться, что Мать-земля сохранит мою душу.', 'Я пришла в Подгород, потому что слышала, что алхимики давно работают над созданием лекарств, которые могут исцелить их собственную болезнь. Я надеялась, что они и мне помогут.$B$BХотя я чувствую себя не в своей тарелке, выбора нет – боль раздирает меня изнутри, и мне срочно нужна помощь.', NULL, NULL, 'Эликсир Дуремара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3570, 'Разносчик порчи', '', '', 'Я и не думал, что эликсир сработает так быстро. Спасибо, $N. Займусь-ка работой над остальными образцами. Уверен, вскоре леди Сильвана и Отрекшиеся будут их активно использовать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3601, 'Оскорбленный Ким\'джаель', 'Ким\'джаель оскорблен до глубины души! Знаешь, что на самом деле Ким\'джаель значит для эльфов крови, $N? Я для них всего лишь букашка! Маленькое безвредное создание, на которое можно и наступить – не жалко! $B$BОни наняли меня, чтобы я обшарил для них место, где, как они сказали, спрятано сокровище. Ну ты понимаешь, при слове \"сокровище\" я утратил бдительность и купился на их посулы! Конечно же, они предали меня и даже пытались прикончить! $B$BНикогда нельзя верить мерзким эльфам крови! $B$BМне удалось уйти живым, но у негодяев осталось все мое снаряжение! Пожалуйста, забери его у них!', 'Обыщите Талассийское поселение и найдите компас, прицел, плюшевого цыпленка и центробежный растягиватель Ким\'джаеля. Верните все это Ким\'джаелю в Азшару.', 'Ха! Так им и надо! $B$BВот это круто! Теперь-то они знают, что значит предавать своих партнеров! Особенно гоблинов! $B$BНу, теперь о твоей награде... я же сказал, значит, заплачу. $B$BВот, держи... может, пригодится.', 'Мерзкие эльфы крови! Да-да, если бы я был таким же большим и сильным, как ты, уж я бы научил их хорошим манерам. Я поскольку я может и сильный, но легкий, я лучше заплачу тебе, чтобы ты сделал это за меня.', NULL, NULL, 'Компас Ким\'джаеля', 'Прицел Ким\'джаеля', 'Плюшевый цыпленок Ким\'джаеля', 'Центробежный растягиватель Ким\'джаеля');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3602, 'Азшарит', 'Древние скальные великаны из южных регионов Азшары для поддержания существования поглощают камни и каменные образования. Продуктом переработки такой \"пищи\" являются чрезвычайно податливые, но при этом необычайно прочные кристаллы, известные как азшарит. $B$BНа южной гряде находятся целые залежи азшарита, однако его почти никому не удавалось добыть из-за чрезвычайной жестокости великанов.$B$BТебе следует отправиться на юг и раздобыть азшарита столько, чтобы его хватило для создания оружия. Мои гончие скверны помогут в розыске кристаллов.', 'Найдите в южной Азшаре двадцать кристаллов азшарита. Вы можете использовать Гончих Скверны, которые помогут вам \"вынюхивать\" местонахождение хорошо сокрытых залежей. Когда задача будет завершена, возвращайтесь к Лорамусу Многоногу.', 'Твои задачи в Азшаре завершены. Теперь я должен подготовить все необходимое для следующего шага твоего пути.', 'Зло не спит, и глуп тот, кто думает иначе. Отдохнешь после смерти. Принеси же мне кристаллы.', NULL, NULL, 'Кристаллизированный азшарит', 'Набор для вызова ищейки Скверны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3621, 'Создание отравы Скверны', 'Оружие готово к отковке. Тебе следует отнести закаленный азшарит к тому, кто может обуздать энергию скверны.$B$BВ Тернистой долине живет такой кузнец. Гальван Древний, глава Ордена Мифрила, создаст оружие по твоему заказу. Ты можешь найти его становище между Зул\'Гурубом и холмом Мош\'Огг.$B$BПусть решительность и вера помогут тебе пройти это испытание. А если ты погибнешь, знай, что твой Бог тебе улыбается.', 'Отнести груз Гальвану Древнему в Тернистую долину.', 'Могу лишь вообразить, через что тебе пришлось пройти, чтобы раздобыть эти материалы. Немногим удавалось вернуться живыми из Азшары, не говоря уж о том, чтобы встретиться лицом к лицу с полубогами и демонами.', 'Вот как, Лорамус? Прошло много лет с тех пор, как я в последний раз слышал это имя.', NULL, NULL, 'Партия товара Гальвану (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3625, 'Зачарованное азшаритовое оружие, отравленное Скверной', '$N, для создания оружия необходимо время.$B$BВдобавок, ты можешь использовать силу оружия Проклятия Скверны лишь раз в три минуты. Длительность действия, ослабляющего Разелиха Осквернителя и его приспешников, может быть различной. Именно поэтому следует высвобождать силу Проклятия Скверны лишь в нужный момент!$B$BТеперь дай мне время на создания оружия для тебя, $N.', 'Подождите, пока Гальван закончит отковывать оружие.', '*Гальван вытирает пот со лба..*$B$BНикогда еще не существовало более подходящего оружия для убиения демона, $N.', 'Если вмешиваться в процесс, то оружие может получиться с изъяном. Терпение, $N.', NULL, NULL, 'Оружие выковано.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3626, 'Возвращение в Выжженные земли', 'Час возмездия близок, $N. Тебе следует вернуться в Выжженные земли вместе с твоим новообретенным оружием и поговорить с павшим героем Орды о том, как достичь твоей главной цели.', 'Вернитесь к Павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.', 'Похоже, сражения закалили тебя, $N. Но достаточно ли в тебе силы и решимости, чтобы противостоять Разелиху и его приспешникам?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3627, 'Воссоединить расколотый амулет', 'Чтобы добраться до Осквернителя, тебе следует сначала уничтожить троицу силы и собрать осколки амулета. Когда у тебя в руках будут все три осколка, возвращайся ко мне, и я скажу, что делать дальше.$B$BИди, $N! В Выжженные земли! Севина, Аллистарий и Грол должны погибнуть!', 'Убейте Грола Разрушителя, леди Севину и верховного мага Аллистария. С их трупов заберите Амулет Грола, Амулет Севины и Амулет Аллистария.Помните о том, что нужно использовать зачарованное азшаритовое оружие, отравленное Скверной, чтобы ослабить троицу! Их нельзя убить иначе – но используйте оружие разумно...', 'Амулет Разелиха Осквернителя наконец-то собран воедино. Но Разелих чует, что цепь его власти порвана. Он знает, что ты собираешься убить его...', 'Три должны образовать один, один должен осветить путь.', NULL, NULL, 'Амулет Аллистария', 'Амулет Грола', 'Амулет Севины', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3628, 'Ты – Рах\'лих, демон!', 'Логово Разелиха находится на вершине самой высокой горы Выжженных земель. Единственный способ достигнуть логова – это использовать телепортирующие руны поблизости от горы. Пока у тебя есть этот амулет, ты свободно можешь переместиться в логово. А достигнув логова, призови зверя. Ключ к этому – твой амулет, $N. Используй его на Алтаре Осквернителя.$B$BЕсли одолеешь Осквернителя, принеси его рог. Он станет символом надежды для всех, кто увидит его – доказательством того, что в этом раздираемом войнами мире еще есть герои!', 'Уничтожьте Разелиха Осквернителя и вернитесь к павшему герою Орды с отрубленным рогом Осквернителя. Вам также понадобится вернуть оберег Осквернителя, чтобы павший герой мог уничтожить его, дабы оберег не попал к тому, кто использует его во зло.', 'Сегодняшний день останется в памяти навеки. Демонический повелитель Выжженных земель наконец-то пал!', 'Больше нечего бояться.', NULL, NULL, 'Отрубленный рог Осквернителя', 'Оберег Осквернителя (Прилагается)', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3629, 'Гоблинское инженерное дело', 'В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер.$B$B$N, почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого.', 'Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.', 'Что же, Немёртвое, ты разумно поступаешь, прося у меня наставничества! Любой дурак может стать экспертом в азах инженерного дела – что прекрасно видно на примере гномов и их радиоактивного Гномрегана. Для овладения гоблинским инженерным делом требуется крепкая соображаловка и твердая (повторяю – ТВЕРДАЯ) рука.$B$BДержи ушки на макушке, Немёртвое, может, что и усвоишь.', 'Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?', NULL, NULL, 'Справочник по инженерным дисциплинам (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3630, 'Гномское инженерное дело', 'В инженерном деле есть две дисциплины: гномская и гоблинская. Гномское инженерное дело пока что зарекомендовало себя лучшим из двух. В нем речь идет о конструировании чудесных штучек и приспособлений, которые украшают жизнь!$B$B$N, почитай этот справочник. Если ты захочешь больше узнать о гномском инженерном деле, то отнеси его мехмастеру Замыкальцу в Стальгорн. Помни – выбор твой не подлежит пересмотру, и изучить другую дисциплину ты не сможешь, так что удостоверься в своем выборе, прежде чем выполнять его задание!', 'Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.', 'А, молодой инженер, заинтересованный в освоении единственно верной школы инженерного дела! Что ж, дружище, прости мне мою мелодраматичность. Пока ситуация наша остается тяжелой, день всегда кажется светлее, когда встречаешь собрата по ремеслу, откликнувшегося на трубный призыв истинного инженерного дела!', 'Да-да, чем могу служить? Времени у меня теперь более чем достаточно; ведь все, что я делаю – это стою здесь, пока наш любимый город охвачен смертельным радиоактивным облаком.', NULL, NULL, 'Справочник по инженерным дисциплинам (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3631, 'Призывание коня Скверны', 'Хммм. Я сказал бы, что ты еще $gне готов:не готова:, но тут не мне решать. Страад думает иначе, а решает он... пока.$B$BОн хочет с тобой говорить, причем срочно. Он пока все еще в Степях над Кабестаном, в своей маленькой башне со своими учениками.$B$BДолго не тяни.', 'Поговорите в Кабестане со Страхадом Фарсаном.', 'Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны.$B$BМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3632, 'Гномское инженерное дело', 'На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Гномская намного сильнее! Она занимается конструированием чудесных штучек и устройств, которые делают лучше нашу жизнь!$B$B$N, прочти эту инструкцию. Если желаешь узнать побольше о гномском инженерном деле, отнеси этот справочник мехмастеру Замыкальцу – он здесь, в Стальгорне. Помни: если выберешь гномское инженерное дело, то это с концами, другим направлением заниматься не сможешь, так что подумай хорошенько, прежде чем выполнить его поручение!', 'Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.', 'А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!', 'Да-да, какие ваши запросы я могу удовлетворить ныне? Воистину, времени у меня много, ибо я только и делаю, что ошиваюсь здесь, когда наш возлюбленный город лежит, окутанный смертоносным радиоактивным облаком!', NULL, NULL, 'Справочник по инженерным дисциплинам (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3633, 'Гоблинское инженерное дело', 'Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!$B$BПрочитай этот учебник, $N. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.', 'Если вы хотите узнать о гоблинском инженерном деле, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск, что в Танарисе.', 'Что же, $N, ты нашел подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (ключевое слово – ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела.$B$BДержи ушки на макушке, $N, и чему-нибудь научишься.', 'Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?', NULL, NULL, 'Справочник по инженерным дисциплинам (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3634, 'Гномское инженерное дело', 'На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.$B$B$N, прочти эту инструкцию. Если ты желаешь узнать побольше о гномском инженерном деле, отнеси этот справочник мехмастеру Замыкальцу в Стальгорн. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься другим направлением, так что подумай хорошенько, прежде чем выполнить поручение Замыкальца!', 'Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.', 'А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!', 'Да-да, какие ваши запросы я могу удовлетворить ныне? Воистину, времени у меня много, ибо я только и делаю, что ошиваюсь здесь, когда наш возлюбленный город лежит, окутанный смертоносным радиоактивным облаком!', NULL, NULL, 'Справочник по инженерным дисциплинам (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3635, 'Гномское инженерное дело', 'На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.$B$B$N, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую Бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько прежде, чем выполнить поручение Карлса!', 'Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту.', 'Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решетку.$B$BМы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.', 'Эй, ты! Если собираешься жаловаться, что мой автономный робот пробил стену твоего дома, можешь сразу обращаться к адвокату. Или ты по другому поводу?', NULL, NULL, 'Справочник по инженерным дисциплинам (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3636, 'Нести свет', 'Плеть постоянно досаждает силам Альянса. Думаю, $N, ты знаешь об этом не хуже меня. В последнее время нам удалось сделать пару интересных находок.$B$BВ Степях есть жуткие заросли терновника, называемые Курганы Иглошкурых. Сначала казалось, что там обитают только иглогривы, но теперь выясняется, что в этих зарослях гнездятся самые разнообразные чудовища. Управляет ими лич по имени Амненнар Хладовей.$B$BВо имя Света, $N! Изгони зло с холмов Иглошкурых!', 'Убейте Амненнара Хладовея в Курганах Иглошкурых.', 'Спасибо, $N. Теперь Плеть подумает дважды, прежде чем выпускать на нас своих гадов.$B$BДа хранит тебя Свет!', NULL, NULL, NULL, 'Амненнар Хладовей убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3637, 'Гномское инженерное дело', 'На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.$B$B$N, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую Бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько прежде, чем выполнить поручение Карлса!', 'Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту.', 'Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решетку.$B$BМы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.', 'Если собираешься жаловаться, что мой автономный робот врезался в стену твоего дома, можешь сразу обращаться к адвокату. Или ты по другому поводу?', NULL, NULL, 'Справочник по инженерным дисциплинам (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3638, '', '', '', 'Добро пожаловать в клуб, $N Скоро ты получишь доступ к наиболее передовым разработкам во всем Азероте.$B$BТеперь, когда ты решил посвятить себя этому искусству, пора познакомиться с гоблинским инженерным делом. С этого мгновения мы будем помогать тебе разрабатывать план предельного раскрытия талантов гоблинского инженера!', 'Если ты подписал документ и готов отдать его мне, тогда вот что я скажу. Предупреждаю в последний раз – это б$N в один конец. Если ты готов – добро пожаловать в наши ряды!', NULL, NULL, 'Подписанный залог Никса', 'Залог секретности Никса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3639, 'Покажи свою работу', 'Блеск в твоих глазах выдает тебя с головой – ты любишь взрывать! Ты опытный инженер, тут вопросов нет, $N. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гоблинскоориентированную технику для будущих трудов. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек твердого динамита и пять взрывоопасных овец – и смотри $gсам:сама: не подорвись!$B$BСдай мне эти предметы, и я признаю тебя истинным гоблином-инженером!', 'Принесите 20 больших железных бомб, 20 шашек плотного динамита и 5 взрывоопасных овец Никсу Шепружину в Прибамбасск.', 'Вот твой первый членский б$N гильдии гоблинов-инженеров!$B$BБ$N оплачивается вперед за четырнадцать дней. Через две недели срок действия истечет. Когда это произойдет, то для продления заплати очередную пошлину любому наставнику гоблинской инженерного дела. Без б$Nа твое членство будет временно приостановлено, и ты не будешь иметь доступа к новым чертежам.$B$BЭто никак не повлияет на уже обретенные знания: если уж стал гоблинским инженером, то это навсегда.', 'Как только я получу на рассмотрение твои инженерные изделия, я выдам тебе настоящий членский б$N гильдии гномов-инженеров! Пока он будет действителен, ты будешь иметь неограниченный допуск к любому наставнику по гоблинскому инженерному делу в мире.', NULL, NULL, 'Большая железная бомба', 'Твердый динамит', 'Взрывоопасная овца', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3640, 'Договор о неразглашении', '', '', 'Добро пожаловать в клуб, $N! Скоро вы получите доступ к наиболее передовым разработкам во всем Азероте.$B$BТеперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!', 'Если вы подписали документ и готовы отдать его мне, тогда вот что я вам скажу.$B$BТайны, которые я вам доверю, настолько важны, что подписание Договора о неразглашении просто жизненно необходимо. Я сам такой подписывал, как и мои брат и сестра. Вы попадете в очень приятную компанию, инженер Август!', NULL, NULL, 'Подписанный залог Большой Искры', 'Залог секретности Большой искры', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3641, 'Покажи свою работу', 'Если ты $gготов:готова: приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась: по адресу! Ты опытный инженер, тут вопросов нет, $N. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и я признаю тебя истинным гномов-инженером.', 'Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени мехмастеру Замыкальцу в Стальгорн.', 'Вот ваш первый ччленский б$N гильдии гномов-инженеров!$B$BБ$N оплачивается вперед за четырнадцать дней. Через две недели срок действия истечет. Когда это произойдет, вы заплатите очередную пошлину любому наставнику гномской инженери и получите продление. Без б$Nа ваше членство будет временно приостановлено, и вы не будете иметь доступа к новым чертежам.$B$BЭто никак не повлияет на уже обретенные вами знания: если уж стал гномским инженером, то это навсегда.', 'Как только я получу на рассмотрение ваши искусные инженерные изделия, я выдам вам настоящий членский б$N гильдии гномов-инженеров! Пока он будет действителен, вы будете иметь неограниченный допуск к любому наставнику по гномскому инженерному делу в мире.', NULL, NULL, 'Мифриловая труба', 'Точный прицел', 'Усовершенствованный манекен-мишень', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3642, 'Договор о неразглашении', 'Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у тебя в руках, об этом написано.$B$BНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займешься гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.$B$BЕсли ты по-прежнему хочешь заняться гномским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько.', 'Если вы согласны заниматься гномским инженерным делом, щелкните ПКМ по Договору о неразглашении и еще раз обратитесь к Карлсу Пропеллерзу в Пиратской Бухте.', 'Добро пожаловать в клуб, $N! Скоро вы получите доступ к наиболее передовым разработкам во всем Азероте.$B$BТеперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!', 'Если ты подписал документ и готов отдать его мне, тогда вот что я скажу.$B$BХотя я не согласен с политикой Гномрегана – и особенно этого глупца, мехмастера Замыкальца – с политической точки зрения, документ о неразглашении превыше всего! Ты должен избрать свой путь и следовать им всю свою жизнь.', NULL, NULL, 'Подписанный залог Карлса', 'Залог секретности Карлса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3643, 'Покажи свою работу', 'Если ты $gготов:готова: приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась: по адресу! Ты опытный инженер, тут вопросов нет, $N. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и я признаю тебя истинным гномов-инженером.', 'Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени Карлсу Пропеллерзу в Пиратскую Бухту.', 'Вот твой первый членский б$N гильдии гномов-инженеров!$B$BБ$N оплачивается вперед за четырнадцать дней. Через две недели срок действия истечет. Когда это произойдет, то для продления заплати очередную пошлину любому наставнику гномского инженерного дела. Без б$Nа твое членство будет временно приостановлено, и ты не будешь иметь доступа к новым чертежам.$B$BЭто никак не повлияет на уже обретенные знания: если уж стал гномским инженером, то это навсегда.', 'Как только я получу на рассмотрение твои инженерные изделия, я выдам тебе настоящий членский б$N гильдии гномов-инженеров! Пока он будет действителен, ты будешь иметь неограниченный допуск к любому наставнику по гномскому инженерному делу в мире.', NULL, NULL, 'Мифриловая труба', 'Точный прицел', 'Усовершенствованный манекен-мишень', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3644, 'Продление членского б$Nа', '', '', 'Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский б$N за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский б$N. Это даст тебе доступ к гоблинским чертежам соотвествующих наставников.$B$BБ$N будет действителен две недели, по истечении которых придется снова заплатить.', NULL, NULL, NULL, 'Требуется денег: 2', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3645, 'Продление членского б$Nа', '', '', 'Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский б$N за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский б$N. Это даст тебе доступ к гномским чертежам соотвествующих наставников.$B$BБ$N будет действителен две недели, по истечении которых придется снова заплатить.', NULL, NULL, NULL, 'Требуется денег: 2', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3646, 'Продление членского б$Nа', '', '', 'Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский б$N за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский б$N. Это даст тебе доступ к гоблинским чертежам соответствующих наставников.$B$BБ$N будет действителен две недели, по истечении которых придется снова заплатить! Если ты хочешь иметь доступ к чертежам, не просрочивай платежи.', NULL, NULL, NULL, 'Требуется денег: 2', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3647, 'Продление членского б$Nа', '', '', 'Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский б$N за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский б$N. Это даст тебе доступ к гномским чертежам соотвествующих наставников.$B$BБ$N будет действителен две недели, по истечении которых придется снова заплатить.', NULL, NULL, NULL, 'Требуется денег: 2', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3661, 'Любимцы Элуны?', 'Дикие совухи – очень непредсказуемые существа, $N. Они могут быть мягкими и пушистыми, но если что-то дорогое для них окажется под угрозой, в них проснется настоящий зверь!$B$BГоворят, что этих животных создала сама Элуна, и я хочу узнать, правда это, или нет.$B$BМного диких совухов обитает во Внутренних землях – целые популяции примитивных, злобных существ. Не хочешь отправиться туда и принести мне их перьев?', 'Собрерите во Внутренних землях 15 перьев диких совухов и отнесите их Эреласу Янтарному Небу в деревню Рут\'теран.', 'Спасибо за перья, $N.$B$BЧто вам удалось узнать о дикосовухах?$B$BВозможно, эти перья помогут узнать больше и сказать, являются ли они кровожадными монстрами или просто одичавшими питомцами. Надеюсь, когда-нибудь я узнаю правду.$B$BЯ продолжу свои исследования, а вы, пожалуйста, по истечении некоторого времени зайдите ко мне снова.', 'Старайтесь избегать их, $N. Дикосовухи могут счесть вас за врага.', NULL, NULL, 'Перо дикого совуха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3681, 'Фолиант Божественности', 'Я вынужден прервать твое путешествие, $r. Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения.$B$BЕсли бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов.$B$BНайди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света.', 'Разыщите в Штормграде Даториана Ралла и поговорите с ним.', 'Добро пожаловать в Собор Света, $C.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3701, 'Дымящиеся руины Тауриссана', 'Отправляйтесь в дымящиеся руины Тауриссана в Пылающих степях и соберите как можно больше информации.$B$BГоворят, все руины просто усыпаны таинственными реликвиями. Возможно, вам надо начать поиски здесь, $N. Опасайтесь таурисанских стражей-убийц, что стерегут руины, охраняя все тайны, какие там могут быть.', 'Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону.', 'Ох ты! Эта информация многое объясняет касательно Тауриссана.$B$BНо предстоит узнать еще больше!', NULL, NULL, NULL, 'Информация получена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3702, 'Дымящиеся руины Тауриссана', 'Не желаете ли услышать краткий обзор истории дворфов Черного Железа?', 'Узнайте от королевского историка Аркессона историю Тауриссана.', 'Продолжим?', 'Позвольте мне закончить рассказ об истории Тауриссана.', NULL, NULL, 'Выслушайте историю о Тауриссане.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3721, 'Собственный ККХ', '', '', 'Тебе удалось выручить всех трех моих роботов серии ООХ! Ты сделал все, что требовалось и даже больше, поэтому я хочу особым образом отблагодарить тебя за помощь. Это миниатюрная версия того же робота, с которым ты провел так много времени и полюбил, ООХ!Обычно я никому не дарю такие опасные устройства, но ты оказал мне неоценимую помощь. Кроме того у этой тварюшки отключены боевые механизмы и устройство самонаведения.А в остальном это полноценный ООХ!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3741, 'Ожерелье Хилари', 'Моя подруга Хилари потеряла ожелелье, и мы никак не можем отыскать его. Мы весь день сидели на одном и том же месте, удили рыбу, и уже все кругом обыскали. Наверное, оно упало в воду. Родители не разрешают нам плавать в озере... Мама говорит, что под водой водятся чудовища, но вы ведь их не боитесь, правда?$B$BПожалуйста, достаньте нам ожерелье.', 'Найдите ожерелье Хилари и верните его Хилари в Приозерье.', 'Спасибо, что достали мне ожерелье, господин $C... Вы очень добры! Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?', 'Привет. Я очень переживаю из-за пропажи ожерелья. Ведь его мне папа привез! Кстати, он говорит, что в озере водятся чудовища. Вы уже их победили?', NULL, NULL, 'Ожерелье Хилари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3761, 'Почва Ун\'Горо', 'Говорят, что почва из Кратера Ун\'Горо наделена мощными магическими свойствами. Кругу Кенария нужно много этой почвы для исследований. Ступай в страшные окрестности Ун\'Горо и добудь земли побольше.$B$BЭта богатая почва порой лежит большими грудами, а иногда ее находят у некоторых тварей. Относи землю к Геду – ищи кучки земли и таурена, раздающего команды. Он не злой, просто постарайся его не слишком донимать.', 'Принесите 20 образцов земли из Кратера Ун\'Горо Геду на Вершину Старейшин Громового Утеса.', 'Ладно, рядовой $N, и не пытайся помогать мне сваливать эту землю в кучу! Если бы Великие духи этого хотели, то прямо тут и устроили бы чудо, что, не так?!$B$BВерховный друид Рунический Тотем опять хочет с тобой говорить, но чтобы выполнить его очередное поручение, тебе нужно разбираться в травничестве на уровне подмастерья. Но если ты еще не доучился, он все равно тебе дельце подберет.', 'Вольно, рядовой. Если ты собираешься выгрузить землю из Ун\'Горо – то жди команды! Если нет – кругом и марш отсюда!', NULL, NULL, 'Почва Ун\'Горо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3762, 'Помощь верховному друиду Руническому Тотему', 'Извини, $C, можно тебя на минутку?$B$BКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.$B$BЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.', 'Поговорите с верховным друидом Хамуулом Руническим Тотемом на Уступе Древних Громового Утеса.', 'Привет тебе, $C. Я рад, что ты хочешь помочь нам в наших исследованиях. Сделать предстоит многое, и я дурно поступил бы, если бы сказал, что труды наши не сулят опасности. Надеюсь, это тебя не отпугнет... но, судя по твоему виду, тебе и прежде приходилось сталкиваться с опасностями.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3763, 'Помощь верховному друиду Оленьему Шлему', 'Простите, $C, не уделите ли вы мне крупицу вашего времени?$B$BДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит ни кто иной, как сам верховный друид Фэндрал Олений Шлем.$B$BПрошу вас, если вам интересно, поговорите с лим лично в анклаве Кенария в Дарнассе.', 'Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.', 'Что же, $C... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.$B$BИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3764, 'Почва Ун\'Горо', 'Говорят, что почва из Кратера Ун\'Горо наделена мощными магическими свойствами. Я хочу знать, насколько эти слухи преувеличены. Ступай в заросший кратер Ун\'Горо и добудь хороших образцов земли для наших исследований.$B$BТебе может показаться, что это дело не достойно тебя, но такое поведение не завоюет тебе приязни ни с моей стороны, ни со стороны Круга Кенария. Принеси образцы земли Дженалю, который наверняка сидит без дела вон за тем деревом – ищи кучки земли, и найдешь его. Снабжением занимается он, не я.', 'Принесите 20 образцов земли из кратера Ун\'Горо Дженалю в дарнасский анклав Кенария.', 'Наконец-то ты сможешь избавиться от своего драгоценного груза, благородный $C. Тяжкая, наверное, ноша... не легче ноши созерцателя, вроде меня... Вот гонорар за работу, назначенный самим верховным дуидом.$B$BВерховный друид Олений Шлем опять хочет видеть тебя, $N, но ты получишь помощь при выполнении следующего его задания, если только будешь разбираться в травознании не хуже подмастерья. Но если даже ты и вовсе не травник, ты все равно можешь помочь Кругу!', 'А, опять эта грязь. Верховный друид требует с каждого искателя приключений по двадцать кучек – двадцать кучек ему и будет. И пусть те, кто строит нам козни, топает по обочине!', NULL, NULL, 'Почва Ун\'Горо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3765, 'Проблема за морем', 'Штормград – невероятно суматошный город.$B$BЯ прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам.$B$BМой брат Гершала на Темных берегах нуждается в помощи. Он обитает в приморском городке Аубердине.$B$BЭто путешествие будет долгим и насыщенным. Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, $C.', 'Отправляйтесь в Аубердин к Гершалу Шепоту Ночи.', 'О, вас прислал мой брат Аргос? Должно быть, вы устали от долгого пути. Но нам очень о многом нужно поговорить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3781, 'Изучение рассветницы', 'При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун\'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен разгадать его тайну.$B$BОтнеси это вниз, Матренгилу, и он даст тебе семена, чтобы ты $gмог:могла: начать работу. Если все израсходуешь, тебе придется купить у него еще семян.', 'Отнесите расписку верховного друида в получении семян Матренгилу Медвежьей Лапе в дарнасский анклав Кенария.', 'Да, расписка на двадцать пакетиков семян. Если все изведешь, еще достанем. Хотя производить семена Тарлендриса в большом количестве – дело, увы, недешевое. Потому Круг Кенария и просит помощи в частичном возмещении стоимости.$B$BТе, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды.', 'Да пребудут с тобой мир и спокойствие. Как понимаю, ты с поручением от самого верховного друида?', NULL, NULL, 'Расписка в получении семян (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3782, 'Изучение рассветницы', 'При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун\'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен раскрыть его тайну для Круга.$B$BОтнеси эту расписку моей дочери Башане Рунический Тотем, и она даст тебе семена, чтобы ты $gмог:могла: начать работу. Если все израсходуешь, тебе придется купить у нее еще семян.', 'Отнесите расписку в получении семян Башане Рунический Тотем в Громовой Утес.', 'Да, расписка на двадцать пакетиков семян. Если все израсходуешь, у меня есть еще на продажу. $B$BУвы, $N, производить семена Тарлендриса в большом количестве дорого. Потому Круг Кенария и просит помощи в частичном возмещении стоимости.$B$BТе, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды.', 'Да пребудет мир с тобой, друг. Как понимаю, ты здесь по делу от самого верховного друида?', NULL, NULL, 'Расписка в получении семян (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3783, 'Йети где-то рядом…', 'У моих друзей всегда замечательные идеи. Я никогда не думала, что смогу сравниться с ними… до сегодняшнего дня! У меня созрел потрясающий план! Если обещаешь никому не говорить, я расскажу тебе его по секрету… $B$BЯ хочу сделать механического йети! Мои друзья с ума сойдут, когда увидят, что я смогла смастерить!$B$BДля начала мне понадобится толстый мех йети с холмов Ледополоха. Ты мне поможешь? Йети водятся к юго-востоку отсюда.', 'Соберите 10 толстых кусков меха йети для Уми Смехотреп из Круговзора.', 'Это отличные меха, $N. Это чудесное начало воплощения моего плана!', 'Мне так много нужно всего собрать, чтобы начать! Пожалуйста, принеси мне эти меха как можно скорее!', NULL, NULL, 'Толстый мех йети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3784, 'Помощь верховному друиду Руническому Тотему', 'Извини, $C, можно тебя на минутку?$B$BКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.$B$BЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.', 'Поговорите с верховным друидом Хамуулом Руническим Тотемом на Уступе Древних Громового Утеса.', 'Приветствую, $C! Я рад, что тебя заинтересовало наше исследование. Дел очень много, и я обманул бы тебя, сказав, что речь идет о безопасном задании. Надеюсь, тебя так просто не напугать... По твоему виду можно предположить, что тебе приходилось сталкиваться с опасностями.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3785, 'Изучение рассветницы', 'Это сума вечного цветения для семян Тарлендриса. Еще тебе понадобится почва из Кратера Ун\'Горо как удобрение для семян. Когда достанешь все, что надо, просто используй суму, она позаботится обо всем.$B$BКогда у тебя будет достаточно рассветницы, принеси ее мне сюда, в анклав. И не тревожь верховного друида: он эльф занятой, не стоит всякий раз отрывать его от дела!', 'При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций земли Ун\'Горо попытайтесь прорастить рассветницу.Принесите 10 рассветниц Матренгилу Медвежьей Лапе в Дарнас.', 'Очень хорошо, $N, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария. $B$BНам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить.', 'Ну что, $N, удалось вырастить рассветницу для архиважных исследований верховного друида? Его труды во благо Круга Кенария чрезвычайно важны, и твоя помощь будет весьма кстати!', NULL, NULL, 'Рассветница', 'Сума вечного цветения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3786, 'Изучение рассветницы', 'Вот сума вечного цветения для семян Тарлендриса. Еще тебе понадобится почва из Кратера Ун\'Горо как удобрение для семян. Когда достанешь все, что надо, просто используй суму, а уж она сама позаботится обо всем.$B$BКогда у тебя будет достаточно рассветницы, принеси ее мне сюда на Вершину Старейшин. И не утруждай верховного друида – он очень занят исследованиями, да и других забот у него полон рот.', 'При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций земли Ун\'Горо попытайтесь прорастить рассветницу.Принесите 10 рассветниц Башане Рунический Тотем в Громовой Утес.', 'Очень хорошо, $N, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария. $B$BНам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить.', 'Добро пожаловать $N. Ты вырастил рассветницы для наиважнейших исследований верховного друида? С каждым днем таинственные свойства Кратера Ун\'Горо становятся все понятнее благодаря помощи таких, как ты!', NULL, NULL, 'Рассветница', 'Сума вечного цветения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3787, 'Кинтис Пламень', 'Простите, $gдруг мой:уважаемая госпожа:...$B$BМой коллега хотел бы поговорить с вами касательно проводимых вами совместно с Кругом Кенария исследований. Он друид, зовут его Квинтис Ночной Костер, и живет он в Крепости Оперенной Луны в Фераласе. Он хотел бы посоветоваться с вами насчет рассветницы... и он очень хотел бы, чтобы этот разговор не дошел до ушей верховного друида.$B$BЕсли вы заинтересовались, поговорите с Кинтисом; не сомневайтесь, он расскажет вам все подробно.', 'Поговорите с друидом по имени Квинтис Ночной Костер в Крепости Оперенной Луны.', 'Благодарю вас за ваш визит, усталый путник! Позвольте представиться: я – Квинтис Ночной Костер, друид и скромный слуга Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперенная Луна и Протекторат – вы, может быть, о нас слыхали) и я хотели бы поговорить с вами о той работе, которую вы проводите для Фэндрала Оленьего Шлема в Дарнассе.$B$BПрежде чем мы пойдем дальше, я хотел бы попросить вас, чтобы этот разговор остался строго между нами. Если вы с этим согласны, мы можем продолжать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3788, 'Просьба друида', 'Простите, друг мой…$B$BОдин мой коллега хотел бы побеседовать с вами об исследованиях, которые вы ведете в сотрудничестве с Кругом Кенария. Это друид по имени Квинтис Ночной Костер. Он проживает здесь же, в Крепости Оперенной Луны. Он хотел бы поговорить с вами насчет рассветницы... а главное, очень просит вас, чтобы эта беседа не дошла до ушей верховного друида.$B$BЕсли вас это интересует, поговорите с ним, и вам все станет ясно.', 'Поговорите с друидом по имени Квинтис Ночной Костер в Крепости Оперенной Луны.', 'Благодарю вас, что явились ко мне, усталый путник! Позвольте представиться. Я – Квинтис Ночной Костер, друид и смиренный служитель Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперенная Луна и Протекторат – быть может, вы о нас слышали), и я хотел поговорить с вами о работе, которую вы ведете в Дарнассе по поручению Фэндрала Оленьего Шлема.$B$BНо прежде, чем мы продолжим наш разговор, я хотел бы вас попросить, чтобы эта беседа осталась между нами. Если вы не против, то мы можем перейти к делу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3789, 'Помощь верховному друиду Оленьему Шлему', 'Простите, $C, не уделите ли вы мне крупицу вашего времени?$B$BДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит ни кто иной, как сам верховный друид Фэндрал Олений Шлем.$B$BПрошу вас, если вам интересно, поговорите с лим лично в анклаве Кенария в Дарнассе.', 'Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.', 'Что же, $C... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.$B$BИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3790, 'Помощь верховному друиду Оленьему Шлему', 'Простите, $C, не уделите ли вы мне крупицу вашего времени?$B$BДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит ни кто иной, как сам верховный друид Фэндрал Олений Шлем.$B$BПрошу вас, если вам интересно, поговорите с лим лично в анклаве Кенария в Дарнассе.', 'Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.', 'Что же, $C... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.$B$BИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3791, 'Тайна рассветницы', '$N, я буду с вами откровенен. Меня интересует – точнее, тревожит вопрос, почему верховный друид в Дарнасе пользуется именем и возможностями Круга Кенария для того, чтобы добывать огромное количество рассветницы. Я – исследователь, и специализируюсь на проклятиях. И я слышал, что рассветница в соответствующих условиях приобретает те же свойства, что и прочие травы, используемые в примитивных проклятиях.$B$BЯ хотел бы узнать об этом подробнее. И мне нужна ваша помощь. Принесите мне десять рассветниц, и я буду у вас в долгу!', 'Принесите 10 рассветниц друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.', 'Какое... какое странное ощущение вызывают у меня эти растения! Во имя Элуны, что же затеял Олений Шлем?$B$BНу, как бы то ни было, спасибо вам за помощь. Вот кое-что... ну, понимаете, за труды. Мои исследования, несомненно, затянутся, и мне потребуется еще немало такой травы. Раз уж я этим занялся, пожалуй, стоит проверить, пригодна ли рассветница для использования в алхимии. И тем не менее мне не по себе от этих растений...', 'Мне нужно десять рассветниц – этого должно хватить как минимум для первоначальных исследований. Конечно, поначалу немалое количество материала будет потрачено на тупиковые эксперименты, но такова уж природа научного исследования!', NULL, NULL, 'Рассветница', 'Сума вечного цветения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3792, 'Рассветница для Крепости Оперенной Луны', '', '', 'Спасибо, $N. Я их пока припрячу. У меня, конечно, нет таких значительных средств, как у Оленьего Шлема, однако я все же способен вознаградить вас за труды! Тем более, кто знает, что может случиться, если Олений Шлем будет получать все больше рассветницы... Тут что-то нечисто, помяните мои слова!$B$BНе забывайте, что от лишней рассветницы я никогда не откажусь. Приносите по пять штук за раз, и я их возьму.', NULL, NULL, NULL, 'Рассветница', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3801, 'Наследие Черного Железа', 'Привет тебе, $N. Я Франклорн Искусник. Да, тот самый Франклорн Искусник, который придумал, как тесать камень. За долгие странствия по терзаемому войнами миру тебе несомненно случалось проходить сквозь мои творения или стоять на них.$B$BДолжно быть, тебе интересно, откуда я здесь и что мне от тебя нужно. Логичные вопросы.$B$BРазумеется, мне нужна твоя помощь. В обмен на нее я дарую тебе ключ, открывающий путь в глубины моего проклятого города.', 'Чтобы получить ключ от города, поговорите с Франклорном Искусником у гробницы Искусника на Черной горе.', 'Жадность ли привела тебя сюда или слепая верность, от твоего предприятия будет благо нам всем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3802, 'Наследие Черного Железа', 'Финий Темнострой находится за Кольцом Закона в Зале Ремесла. Убей ничтожную тварь и забери Железного Друга.$B$BОтнеси Железного Друга в святилище Тауриссана и помести молот в предначертанное ему место: в руки статуи, воздвигнутой в мою честь.$B$BПосле этого откроется тайное отделение, в котором я спрятал главный ключ. А главное, Железный Друг навеки останется в моих руках. Если они предпримут попытку забрать его, то статуя и молот рассыплются и исчезнут вовек.', 'Убейте Финия Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника.', 'Молот легко встает на место, в руку массивного монумента Черного Железа. У основания статуи открывается тайное отделение. Внутри оказывается...', 'Статуя зловеще нависает над вами.', NULL, NULL, 'Железный Друг', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3803, 'Рассветница для Дарнаса', '', '', 'Великолепно! Верховный друид, несомненно, обрадуется этой рассветнице. Правда, должен признать... даже находиться рядом с ней с ней не особо приятно. Представляю, как тяжело верховному друиду все время возиться с этой травой!$B$BА это для тебя, $N. Круг Кенария благодарит тебя за безотказную помощь.', NULL, NULL, NULL, 'Рассветница', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3804, 'Рассветница для Громового Утеса', '', '', 'Великолепно – эта рассветница несомненно поможет нам в будущем! Мы знаем, что и ночные эльфы проводят подобные исследования трав, хотя непонятно, для чего будут они использовать результаты – если, конечно, что-нибудь найдут. Верховный друид считает, что рассветница будет нам нужна до тех пор, пока мы на узнаем тайну этого растения.$B$BА это для тебя, $N. Круг Кенария благодарит тебя за неустанную помощь.', NULL, NULL, NULL, 'Рассветница', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3821, 'Скала Молота Ужаса', 'Несколько недель назад Ша\'ни была отправлена в Пылающие степи, чтобы исследовать странные ритуалы огров клана Огненного Чрева – что-то эти огры оживились в последнее время. $B$BКлинозуб сообщил мне, что от ее группы с тех пор не было вестей, и что главное сейчас – заняться неотложными делами. Представляешь?! А речь, между прочим, о моей жене! $B$BЯ не вправе оставить свой пост, но я должен знать, что случилось с Ша\'ни! Отправляйся в Пылающие степи и найди ее!', 'Отправляйтесь в Пылающие степи и выясните, что сталось с Ша\'ни Гордый Клык.', 'Бедный мой Талтрак... $B$BА мы ведь хотели уехать во Внутренние земли вместе с родителями, когда закончим службу. Теперь этим мечтам не суждено сбыться!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3822, 'Кром\'Грул', 'Они захватили весь мой взвод, $N. И всех, кроме меня, убили.$B$BИх главарь, Кром\'Грул, оставил меня для совершения какого-то обряда.$B$BМеня приковали к этому алтарю и жестоко пытали. Через час мучений мое физическое тело умерло. Тогда эта тварь вырвала у меня из носа обручальное кольцо и напялила на свой палец. В жизни не встречала подобного варварства!$B$BНайди Кром\'Грула и убей его! Отнеси мое кольцо Талтраку.$B$BИ, $N, скажи ему, что мы снова встретимся... в следующей жизни.', 'Заберите ноздревое кольцо Ша\'ни у Кром\'Грула и верните его Тал\'траку из Каргата. Обыщите различные пещеры и рудники скалы Молота Ужаса.', '*Талтрак опускается на пол.*$B$BМы собирались уехать во Внутренние земли. Она рассказывала? Это было ее последнее задание.$B$B*Талтрак плачет.*$B$BОно мне не нужно, $N. Оставь его себе или выброси, мне все равно! Теперь кольцо ничего для меня не значит. Без нее оно ничто...', 'Тебе удалось найти Ша\'ни? С ней все в порядке?', NULL, NULL, 'Ноздревое кольцо Ша\'ни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3823, 'Угасание Огненного Чрева', 'Мы должны нанести удар первыми!$B$BБуду краток.$B$BОгры из клана Огненного Чрева – союзники орков из клана Черной Горы в Пылающих степях. Рука об руку они охраняют богатую полезными ископаемыми скалу Молота Ужаса и линиии снабжения.$B$BОставь свой след в истории, $N. Смети их охрану и возвращайся ко мне.$B$B<Орелиус хватается за воздух, будто кого-то душит.>$B$BЯ тебя прибью, Винки!', 'Убейте 15 огров-магов, 7 огров и 7 громил из клана Огненного Чрева.', 'Потрясающе, солдат! Оркам и ограм понадобится несколько минут или даже часов, чтобы оправиться от удара!', NULL, NULL, NULL, 'Огр-маг из клана Огненного Чрева убито', 'Огр из клана Огненного Чрева убито', 'Громила из клана Огненного Чрева убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3824, 'Гор\'теш Жестокий', 'Говорю же, они колеблются! Пора нанести решительный удар.$B$BМы должны убить жестокого вождя, Гор\'теша. И что еще важнее, мне нужна его голова для третьей фазы операции против огров Огненного Чрева.$B$BИ помни, солдат, Гор\'теш правит не из скалы Молота Ужаса, но из строения орков Черной Горы на западе от нее.$B$BИтак, приказы тебе даны ясные. Найди Гор\'теша и отруби ему башку. Потом возвращайся ко мне.$B$BЗАТКНИСЬ, Винки!', 'Завладейте головой Гор\'теша.', 'Только посмотрите на нее. Какая мерзость! Когда остатки огров Огненного Чрева увидят этот жирный чайник на вершине собственной скалы, начнется паника!$B$B*Орелиус хохочет.*', 'О радость, о счастье! Ты несешь его голову?', NULL, NULL, 'Отрубленная голова Гор\'теша', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3825, 'Голова огра на палочке = вечеринка', 'Осталось только одно задание, солдат.$B$BЯ позволил себе вольность – нанизал голову Гор\'теша на пику. Тебе остается отнести ее на вершину скалы Молота Ужаса и воткнуть в землю. Стоит только сделать это, как трусливые огры бросятся куда глаза глядят! Когда ты повеселишься от души, возвращайся ко мне, и я награжу тебя за проделанную работу.$B$B*Кажется, Орелиус теряет связь с реальностью.*', 'Отнесите голову Гор\'теша на вершину скалы Молота Ужаса. Поищите кучу рыхлой земли и воткните в нее пику.', 'Отличная работа, солдат! Поразительная! Ах, я получу медаль за храбрость, то есть, я хочу сказать, ты получишь недурную награду!', 'Ну как? Ты зарисовал повальное бегство огров?', NULL, NULL, 'Голова Гор\'теша установлена', 'Отрубленная голова Гор\'теша', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3841, 'Бездомный сиротка', 'О, $N, привет! Я так рада видеть тебя снова! Как твое путешествие в Дарнас?$B$BА у нас тут приятные новости! Пока тебя не было, мы сумели многого добиться. Мы даже спасли целую кладку яиц! К сожалению, самка погибла прежде, чем мы подоспели…$B$BСлушай, хочешь себе такого дракончика? Детеныши скоро должны вылупиться, и им понадобится $gхороший папа:хорошая мама:. Ну, что скажешь?$B$BЕсли тебя это действительно интересует, возьми одно из яиц и ступай к Квентину, который находится на Мерцающей равнине, возле гоночной трассы. Он тебе скажет, что делать дальше.', 'Поговорите с Квентином в Тысяче Игл. ', 'О, яйцо летучего хамелеона! И вот-вот должно проклюнуться, если я не ошибаюсь. Удивительно, как тебе удалось его добыть, да еще в таком хорошем состоянии? В Фераласе в наше время эти животные почти не делают кладок... Насколько я понимаю, в тамошних лесах развелась уйма браконьеров, которые охотятся на этих прекрасных созданий и убивают их. Какая жалость, не правда ли?$B$BНо откуда у тебя это яйцо?', 'А, $C, привет!$B$BТы не думай, я тут не ради гонок... хотя зрелище, конечно, занимательное.$B$BЯ прибыл сюда, в Тысячу Игл, чтобы выяснить, можно ли спасти эти земли. Для меня это своего рода личный подвиг: добиться, чтобы эта пустыня вновь расцвела и зазеленела! Может быть, мне все же удастся обнаружить неподалеку источники воды...$B$BТы ведь не мог не заметить, какой резкий переход наблюдается между Фераласом и Тысячей Игл? Тут наверняка не обошлось без магии...', NULL, NULL, 'Непроклюнувшееся яйцо летучего хамелеона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3842, 'Инкубатор', 'Кинда и Джер\'ка? Занятно... Жаль, что летучие хамелеоны не смогут оценить все, что эти девушки для них делают. Очень, очень способные девочки…$B$BТак значит, они дали тебе это яйцо в подарок? Что ж, теперь оно твое и ты за него отвечаешь. Оно, похоже, вот-вот проклюнется, но нужно еще позаботиться о том, чтобы детеныш вылупился здоровым.$B$BДля заклинания, которое будет защищать яйцо, мне требуется только два эликсира стойкости. Остальные компоненты у меня уже есть.', 'Принесите 2 эликсира стойкости Квентину в Тысячу Игл.', 'Великолепно! Это то, что надо. Сейчас, я смешаю все компоненты, и мы поглядим, как будет себя чувствовать детеныш...', 'Чем дольше я здесь нахожусь, тем сильнее мне хочется поучаствовать в этих гонках, $N. Просто крышу сносит…$B$BНу что, удалось тебе добыть эликсиры? Как только я смогу поручиться за здоровье детеныша, я верну яйцо тебе, и оно останется у тебя, пока не проклюнется.$B$BСообщи мне, как добудешь их.', NULL, NULL, 'Эликсир стойкости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3843, 'Новый член семьи', 'Великолепный экземпляр, $N! Если это создание благополучно вылупится на свет, у тебя будет прекрасный, здоровый питомец!$B$BНо если ты рассчитываешь оставить его себе, я бы посоветовал сделать еще одну вещь. Отправляйся на Заоблачный пик во Внутренних землях, и поговори там с дворфом по имени Агнар Зверопас. Он большой специалист по дрессировке животных, и объяснит тебе, что нужно делать дальше.$B$BТолько ступай скорее, $N, яйцо хрупкое и без должного ухода долго не протянет!', 'Отнесите хрупкое яйцо летучего хамелеона во Внутренние земли и поговорите с Агнаром Зверопасом. У вас есть на это всего 1 час. В противном случае детеныш в яйце умрет.', 'Так-так-так... Таких мелких я даже и не видел. Лесной дракончик, если не ошибаюсь... точнее, летучий хамелеон. Отлично, отлично!$B$BНу, чтобы этот малыш благополучно выжил и вырос крепким и здоровым, нужно раздобыть для него еды! Хорошо, что ты вовремя до меня добрался!', 'Привет, $N! Чем могу пригодиться?', NULL, NULL, 'Хрупкое яйцо летучего хамелеона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3844, 'Тайна, покрытая мраком', 'На берегу вы видите разбитый плот. Если учесть, что пруд очень мал, непонятно, как мог оказаться в нем плот, да еще такой побитый непогодой. Хотя, более пристальный взгляд на деревья дает возможность предположить, что уровень воды здесь не постоянный... $B$BВозможно, если приглядеться повнимательней, можно отыскать ключ к загадке...', 'Осмотритесь и попытайтесь выяснить, кому мог бы принадлежать разбитый плот.', 'На дне пруда виднеется какой-то сверток.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3845, 'Тайна, покрытая мраком', 'Вы вытаскиваете сумку на берег, в надежде, что ее содержимое укажет вам на то, откуда она могла взяться и кому бы могла принадлежать. $B$BВсе же немногие путники забредают в Укрытие Маршалла...', 'Изучите найденное в сумке и верните владельцу.', 'О, а вот это, похоже, и в самом деле мне знакомо!', 'Приветствую! Простите, а мы не встречались раньше? Ваше лицо выглядит знакомым...', NULL, NULL, 'Большой компас', 'Свернутая пергаментная карта', 'Ключ Львиной Головы', 'Небольшая сумка');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3861, 'Куд-кудаааа!', '\"... Кудах... кудах... Куд-кудааааа!$B$BКудах...кудах-тах-тах... \"$B$BКурица смотрит на вас и начинает что-то царапать на земле лапой. Вам кажется, что это какое-то слово,но вы не уверены, какое именно. Может... С-А-Л-Ь-Д-Е-А-Н? Прежде чем вы успеваете спросить, курица уходит по своим делам.', 'Найдите немного цыплячьего корма и вернитесь к вашей курочке-подружке. Когда найдете курицу, покажите, как вы рады ее видеть (эмоция \":рад\"), а потом накормите специальным цыплячьим кормом.', '\"Куд-кудааа!!!\"$B$BКурица начинает жадно клевать корм, который вы рассыпали перед ней.$B$BЧерез несколько мгновений она испуганно оглядывается по сторонам. Начинает скрести лапой и суетиться. Она что, яйца снести хочет? Вы думаете, что надо бы заглянуть под нее.', 'Курица смотрит на вас темным холодным и голодным взглядом и ждет.$B$B\"Куд-кудаааа!$B$BКудах...кудах-тах-тах.\"', NULL, NULL, 'Цыплячий корм', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3881, 'Спасение экспедиции', 'Не знаю, какими судьбами ты $gоказался:оказалась: здесь, но ты для нас $gжеланный:желанная: $gгость:гостья:! Меня зовут Виллиден Маршал, я здесь с самостоятельной исследовательской экспедицией. Последняя и самая важная наша кампания столкнулась с многочисленными трудностями. Пожалуй, наиболее существенным нашим просчетом было то, что мы недооценили опасность, которую несет в себе дикая природа Кратера Ун\'Горо. $B$BНам пришлось в спешке покинуть наши базовые лагеря в северо-восточной и юго-западной областях кратера, побросав жизненно-важные припасы. Ты выглядишь весьма внушительно – не поможешь ли нам вернуть их?', 'Принесите ящик с провизией и исследовательское оборудование Виллидену Маршаллу в Кратер Ун\'Горо.', 'О, ты привез нам и нашу провизию, и наши инструменты! Ты не просто спас экспедицию, ты спас нам жизнь! Теперь-то мы сможем здесь продержаться! Не знаю, как благодарить тебя! $B$BХоть мы тут небогаты, без награды ты не останешься. Знай, $N, в экспедиции Маршала у тебя есть друзья, готовые помочь в любую минуту!', 'Если мы вообще хотим выжить в этом жутком месте, нам нужна провизия. А спасение хоть каких-то из наших исследовательских инструментов было бы просто манной небесной!', NULL, NULL, 'Ящик с провизией', 'Исследовательское оборудование', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3882, 'Игра в кости', 'Думаешь, раз в экспедиции Маршалла я ответственный за раскопки, то мне страшно нравится копаться в земле? Нет, я, конечно, мог бы придумать более паршивое занятие, но сейчас что-то ничего не приходит в голову.$B$BМы должны были вести раскопки в местечке под названием Путь Ужаса – неплохое название, не находишь? Искать, значит, там дохлых стегодонов и деметродонов... А их там, между прочим, и живых полным полно! Вил и Хол, видишь ли, хотят изучать это гиблое место, поэтому мы должны исправно поставлять им кости динозавров. Между нами говоря, живые для этих целей сгодились бы не хуже!', 'Принесите 8 костей динозавра Искру Пустокопу в Кратер Ун\'Горо.', 'Прекрасно, отличные кости, ну просто прелесть, что за кости!$B$BСПАСИБО, ЧТО ВЫРЫЛ ДЛЯ НАС ЭТИ ДРЕВНЕЙШИЕ КОСТИ И НЕ ОХОТИЛСЯ НА ЖИВОТНЫХ, ЧТО МОГЛО БЫ НАНЕСТИ НЕПОПРАВИМЫЙ УЩЕРБ ОКРУЖАЮЩЕЙ СРЕДЕ! $B$BТихо, тихо, не спорь со мной, мне совершенно неинтересно, где ты на самом деле их взял, так что давай замнем этот вопрос за ясностью. Вот, возьми это в награду и держи рот на замке, хорошо?', 'Можешь думать обо мне что хочешь, но эти лабораторные крысы даже не поймут, принадлежат ли принесенные им кости древним динозаврам или тем, которые пытались сожрать нас вместе с палатками прошлой ночью! Выбраться бы отсюда живым...', NULL, NULL, 'Кость динозавра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3883, 'Экология чужих', 'То, что мы потерпели неудачу, еще не значит, что исследования надо прекратить! Мы изучали насекомых Гориши в южной части кратера, прежде чем были вынуждены ретироваться сюда. Их присутствие чуждо для экологии Ун\'Горо, и мы должны разобраться почему. $B$BВ их ульях должны быть инкубаторы для личинок. Эти места можно определить по свисающим гроздьям личинок. Возьми образец стены улья рядом с инкубатором вот в этот фиал и принеси его мне на исследование. Но будь $gосторожен:осторожна:!', 'Воспользуйтесь фиалом для образцов, чтобы взять образец материала со стены улья из одного из инкубаторов Гориши в Кратере Ун\'Горо. Ищите в ульях комнаты со свисающими гроздьями личинок. Принесите образец материала стены улья Холании Маршалл в Кратер Ун\'Горо.', 'О, прекрасно, ты очень помог мне. Хотелось бы мне дать тебе большую награду, но жизнь на лоне дикой природы накладывает свои ограничения. Однако могу заверить, без твоей помощи наши исследования были бы невозможны.', 'Ты принес мне образец для исследования, $N?', NULL, NULL, 'Образец материала со стены Улья', 'Неиспользованный фиал для образцов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3884, 'Дневник Вилидена', 'Вы обнаружили изорванный дневник. Кое-какие страницы еще можно прочесть, в том числе и форзац, на котором значится имя Виллидена Маршалла. Если верить написанному в дневнике, Виллидена можно найти где-то на севере кратера, куда он и его товарищи были вынуждены бежать от диких зверей, напавших на их главную стоянку.', 'Верните дневник Виллидену Маршаллу, который находится где-то в Кратере Ун\'Горо.', 'Вы только взгляните на это! Мой дневник! Я думал, он утерян навсегда, как в все, что нам пришлось бросить в базовом лагере. Спасибо, что вернул мне его!', 'Приветствую! Мы с коллегами рады видеть собрата по разуму после стольких недель общения с диким зверьем! Что привело тебя в Кратер Ун\'Горо?', NULL, NULL, 'Изорванный дневник (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3901, 'Игрушки-погремушки', 'Ты уже $gпродемонстрировал:продемонстрировала: свой потенциал в обычных обстоятельствах, $N, а теперь давай посмотрим, как ты будешь действовать под давлением. $B$BСкелеты-костетрясы – еще одни безмозглые приспешники Короля-лича – более серьезные враги, чем зомби, с которыми ты $gсталкивался:сталкивалась: до этого. Я попрошу тебя уменьшить их количество и проявить себя среди Отрекшихся. Не мешкай! Когда все будет сделано – возвращайся ко мне.', 'Убейте 8 скелетов-костетрясов, а затем вернитесь к жрецу Тени Сарвису в Могильник.', 'Отличная работа, $N. Ты показал, что достоин свободы, которая была тебе дана. Многие будут ненавидеть тебя за то, кем ты стал, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрекшихся. $B$BВот, возьми это и ступай своей дорогой. Тебя ждут великие дела, $C.', NULL, NULL, NULL, 'Скелет-костетряс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3902, 'Поиски старой одежды', 'Эй, ты! Если ищешь, что бы такого сделать полезного, слушай сюда! $B$BНам нужны свеженькие рекруты, только что из могилы, которых можно направить в Могильник, чтобы они поискали там что-нибудь стоящее из экипировки. Скорее всего, там будут груды ящиков. Мы надеемся, что вскоре поднимутся новые рекруты, а поскольку нам вовсе не надо, чтобы они слонялись тут голыми, надо бы поскорее чем-нибудь поживиться! $B$BА теперь за работу, несчастный ты мешок с костями! Я не собираюсь платить тем, кто еле двигается.', 'Обыщите Могильник и его окрестности и найдите 6 ящиков с добычей и передайте их стражу смерти Салтену.', 'Отличная работа, $N, я так и думал, что ты не совсем бесполезное существо. А это тебе – одна из лучших вещичек среди тех, что мы собрали.', 'Тебе удалось найти что-нибудь стоящее? Нет ничего постыдного в повторном использовании выброшенных вещей. Никто не станет ничего давать нам – мы, Отрекшиеся, сами себя обеспечим!', NULL, NULL, 'Ящики с добычей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3903, 'Милли Осворт', 'Ты $gпоказал:показала: себя $gнадежным:надежной:c: $C, $N. Да и тяжелой работы не боишься, не правда ли?$B$BУ меня есть подруга, Милли Осворт. У нее какие-то проблемы. Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь.', 'Поговорите с Милли Осворт.', 'О, заместитель судьи Виллем просил тебя поговорить со мной? Он отважный человек и всегда готов помочь, но дела не дают ему покинуть Аббатство Североземья, да к тому же, боюсь, нынешняя моя проблема ему не по плечу.$B$BВозможно, ты мне поможешь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3904, 'Урожай Милли', 'Шайка бандитов, это Братство Справедливости, проникла на виноградники Североземья во время сбора урожая! Я сообщила об этом стражникам, и они заверили меня, что разберутся с этим делом, но... я боюсь за виноград! Если мой урожай не украдут грабители, так наши стражники потопчут!$B$BПрошу тебя, помоги мне! Я собрала большую часть винограда в корзины, но оставила их в виноградниках на юго-востоке.$B$BПринеси мне мой виноград, пожалуйста!', 'Принесите 8 корзин с виноградом Милли Осворт в Аббатство Североземья.', 'Ох, спасибо тебе, $N! Ты спас мой урожай! И, надеюсь, ты показал этим бандитам, что тут им хозяйничать не позволят!$B$BМожет, стражи нам тут нынче и не достает, но зато у нас есть такие герои, как ты!!!', 'Ты принес мой виноград, $N?', NULL, NULL, 'Урожай Милли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3905, 'Уведомление о поставке винограда', 'Теперь, когда мой урожай спасен, отнеси это уведомление о поставке винограда брату Нилзу. Он ведает съестными припасами в Североземье, и я уверена, что он обрадуется, узнав, что у него будет свежий виноград.$B$BБрата Нилза ты найдешь в аббатстве, в звоннице – он там любит... дегустировать вино.', 'Отнесите уведомление о поставке винограда брату Нилзу в Аббатство Североземья.', 'Так, что у нас тут...$B$BХвала Свету! Виноград Милли спасен! Когда она сказала мне, что эти бандиты разнесли ее виноградники, я чуть не впал в уныние, но моя вера в Свет не дрогнула!$B$BИ благодаря твоей отваге теперь у нас есть виноград для вина! Да хранит тебя Свет, $N!', 'Сдается мне, ты в хорошем настроении! Сядь, отдохни тут немножко. Хочешь вина?', NULL, NULL, 'Уведомление о поставке винограда (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3906, 'Дисгармония пламени', 'Старейшины говорят, духи стихий в последнее время неспокойны. Дворфы Черного Железа вызвали в наш мир злобного духа, и теперь он угрожает вечной засухой нашим землям. Мы должны найти причину беспокойства духов. $B$BОтправляйся к Черной горе, через пропасть Пламени, прямо в карьер. Найди там владыку огня – Подчинителя Пирона – и положи конец его злодеяниям!', 'Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду.', 'Не может быть... Не может быть! Уничтожение Пирона лишь приоткрыло завесу над истинным положением вещей. В глубинах Черной горы скрываются еще более коварные силы.', 'Духи стихий все еще пребывают в беспокойстве, $N.', NULL, NULL, 'Подчинитель Пирон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3907, 'Дисгармония пламени', 'Я чувствую скверну в воздухе, $N! Источник ее скрывается в глубинах Черной горы. $B$BИмя его в стонах земли и ветра: лорд Опалитель... Но это еще не все: кто-то или что-то повелевает им. Сам он – лишь инструмент в более могущественных руках. $B$BНайди его и выясни, где скрывается его повелитель. Возвращайся ко мне, когда все разузнаешь.', 'Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию.', '<Громосерд хватает табличку Каринья.> $B$BРагнарос... здесь... $B$BСтарейшины были правы, страшась зла, исходящего от Черной горы. Могущественный служитель Древних богов! В НАШЕМ МИРЕ! Мы должны оценить наши позиции здесь, в Каргате. Нужно решить, стоит ли остаться и драться или бежать в страхе перед новым Расколом. $B$BЛучше больше не приближайся к Черной горе, $N. В ее глубинах кроется куда более великое зло, чем все, что встречалось тебе раньше.', 'Вскоре пламя поглотит эти земли. Торопись, $N!', NULL, NULL, 'Лорд Опалитель убито', 'Табличка Каринья', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3908, 'Тайна, покрытая мраком', 'Видишь ли, я совершенно не представляю, как здесь оказался – просто тайна, покрытая мраком! Мне кажется, я вообще ничего не помню...$B$BЭти вещи все же кажутся мне знакомыми... $B$BМой меч. Я должен был как-то укрепить его, но совершенно не помню зачем? Мне жаль, что не могу сказать тебе больше, но я и в самом деле ничего не помню. $B$BВ любом случае, я знаю куда это отнести – к Донове Снегоноре в Зимние Ключи. Она может закалить меч в местных горячих источниках.', 'Отнесите меч Линкена Донове Снегоноре.', 'Ну конечно, я могу закалить меч. А пока я работаю, расскажи мне, что так задержало Линкена. Обычно он не забывает о важных вещах.', 'Ого! Неужели Линкен наконец-то собрался прислать мне свой меч?', NULL, NULL, 'Тренировочный меч Линкена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3909, 'Эликсир Видере', 'Что такое? Линкен ЗАБЫЛ ВСЕ? $B$BЯсно, потеря памяти... $B$BВот его меч. Он не закончен. Я знаю, кто может закончить его, но... поговорить с ним – непростая задача. $B$BОднако я знаю, кто сможет тебе помочь. Не буду сейчас вдаваться в подробности, скажу только, что тебе необходимо любым способом заполучить эликсир Видере. Единственный, кто может помочь тебе в этом – Греган Пивоплюй. Его нелегко отыскать, но говорят, что недавно его видели в лесах Фераласа.', 'Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре.', 'Мне нужна одна склянка эликсира, чтобы проверить, правильный ли это состав... Да, это он.', 'Уже вернулся?', NULL, NULL, 'Эликсир Видере', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3911, 'Последняя Стихия', 'У меня есть работа для тех, кто не боится заглянуть в глубины, $N. $B$BКлан Черного Железа научился создавать чрезвычайно мощных големов. $B$BИсходя из отчетов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. $B$BПодумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без нее можешь не возвращаться! Награда будет сопоставима с затраченными усилиями.', 'Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей.', '', NULL, NULL, NULL, 'Суть Стихий', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3912, 'Встречаемся на кладбище', 'Этот эликсир позволит тебе говорить с существами, которые обычно незримы. $B$BВозьми эликсир Видере и меч Линкена и отправляйся на кладбище на окраине Прибамбасска в Танарисе. Будешь на месте, выпей эликсир. Результат может показаться тебе неожиданным, но не впадай в панику. $B$BВ том обличье, которое ты примешь, отправляйся на север, в горы. Тот, кто тебе нужен, скрывается в скалистых ущельях. Его имя Гаэриан. $B$BПомни, ты сможешь поговорить с ним только переменив облик...', 'Отправляйтесь на кладбище на окраине Прибамбасска и выпейте там эликсир Видере. Далее, следуя инструкциям Доновы, найдите Гаэриана.', 'Давненько никто не говорил со мной...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3913, 'Замогильная история', 'Когда вернешься на кладбище, $N, увидишь там могильный камень, стоящий особняком. Под ним скрываются многие секреты! $B$BОтодвинь его, и тайны откроются тебе!', 'Воскресните, найдите могильный камень, о котором говорил Гаэриан.', 'Камень отодвинут в сторону, под ним находится небольшое углубление. Положив в него меч Линкена, вы понимаете, что меч идеально ложится туда.', 'Похоже, это тот самый камень, о котором говорил Гаэриан.', NULL, NULL, 'Закаленный меч Линкена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3914, 'Меч Линкена', 'Вокруг меча вспыхивает ослепительно яркое пламя. После того как оно угасло, вы можете снова взять меч. Он изменился!', 'Доставьте превосходный меч Линкена Линкену в Кратер Ун\'Горо.', 'Мой меч, он закончен! $B$BВспомнить бы еще, на что он мне сдался... $B$BДай-ка я пока заплачу тебе за работу.', 'О! Твое лицо мне знакомо! Постой, я угадаю!', NULL, NULL, 'Превосходный меч Линкена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3921, 'Венаки Бенике', 'Мне кажется, я сломал самофланж. Это плохо, потому что я успел рассказать о нем нескольким коллегам из Нижней шахты, и они очень заинтригованы. Надо починить его!$B$BОтнеси сломанный самофланж Венаки Бенике, которая живет к югу от заставы Мор\'шан, лагеря Орды между Степями и Ясеневым лесом. Она очень умная и любопытная. Покажи ей самофланж, и я не сомневаюсь, что она не упустит возможности починить его.', 'Отнесите сломанный самофланж Венаки Бенике.', 'Что это? Самофланж, говоришь? Что такое самофланж??$B$BА... Посмотри, как он вибрирует, когда берешь его в руки. А внутри жужжат сложные шестеренки. Ух ты! Мне хочется починить его и узнать, зачем он тебе?', 'Я очень занята, $C. Если ты пришел не по важному делу, иди своей дорогой...', NULL, NULL, 'Сломанный самофланж (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3922, 'Металлические заготовки', 'Я готова заняться самофланжем, но для этого мне понадобятся запчасти. У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для работы понадобится целая куча.$B$BПроще всего их достать у Нефтяного болота на востоке. Торговая Компания обычно хранит их в ведрах с инструментами. Ступай туда и поищи эти штуковины, а набрав достаточно, возвращайся.', 'Принесите 15 металлических заготовок для деталей Венаки Бенике в Степи.', 'О, ты принес их! Теперь я могу приступить к работе...', 'Несешь заготовки, $N? Я все посматриваю на самофланж, и мне не терпится им заняться.', NULL, NULL, 'Металлическая заготовка для детали', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3923, 'Рилли Грязегоб', 'Увы, у меня ничего не вышло. Я добавила в самофланж несколько новых индикаторов, чтобы проверить его структурную целостность, и согласно им, структурная целостность на нуле. Я могу добавить пару циферблатов и рычаг-другой, но... Думаю, станет только хуже.$B$BОтнеси самофланж Рилли Грязегобу. Он работал на Торговую Компанию, и уж если Рилли не сможет починить эту штуку, то пиши пропало.$B$BОн работает в механической мастерской Ногга в Оргриммаре, в Аллее Чести.', 'Отнесите разбитый и сломанный самофланж Рилли Грязегобу в Оргриммар.', 'Что это? Надо же, самофланж. Откуда он у тебя? Неужели ты рыскал по владениям Торговой Компании в Степях?$B$BИнтересно, это говорит о смелости или о глупости?', 'Осторожно! Голову береги! Не стой под стрелой!', NULL, NULL, 'Разбитый и сломанный самофланж (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3924, 'Руководство по самофланжу', 'Думаю, я смогу починить самофланж, но для этого мне понадобится руководство пользователя. В Торговой Компании у меня был соперник, начальник Медноклин. Он ревностно хранил тайны самофланжа и лишь частицы знания доверял самым надежным своим сторонникам. Я не входил в число избранных...$B$BНачальник Медноклин работает в северо-восточной части Степей, на Каменном карьере.', 'Отнесите руководство по самофланжу Рилли Грязегобу в Оргриммар.', 'Ты принес руководство! Мне не терпится узнать, как починить самофланж! Я говорил с Пароклапаном из Кабестана, и он просил поблагодарить тебя за услуги и вознаградить за них.$B$BЯ тоже весьма признателен, и если починю-таки эту штуку, сразу тебе сообщу...', 'Где руководство?', NULL, NULL, 'Руководство по самофланжу', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3941, 'Помощь гномов', 'Думай, голова! Думай, шапку подарю... Я помню, что явился сюда с какой-то очень серьезной целью. Но совсем не помню с какой!$B$BЕсть идея, $N! Вон там, в пещерах живет гномесса по имени Джей Ди, я помню, она была очень добра ко мне, когда я впервые оказался здесь. Может, она сможет что-то рассказать. $B$BСпроси ее! Только осторожней, она все время возится с этими ужасными светящимися кристаллами, которых полно в этом кратере. Не знаю, зачем уж он ей нужны...', 'Найдите Джей Ди Колли в Укрытии Маршалла.', 'Стой на месте, не шевелись... Я испытываю новую комбинацию кристаллов...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3942, 'Память Линкена', 'О, Линкен? Да, смешной парень... Когда он впервые оказался здесь, бормотал всякую ерунду. Наверное, кто-то как следует двинул бедняге по голове! $B$BОднако кое-что из той чепухи, которую он нес, крепко засело у меня в памяти. Помню, он говорил, что делает какой-то тотем, и что ему необходимо поговорить с какой-то Эриданой Грустью Ветра... кажется, в месте, называемом Оскверненный лес. Думаю, если хочешь узнать больше, тебе следует отпрявиться прямиком к этой Эридане.', 'Найдите Эридану Грусть Ветра на юге Оскверненного леса.', 'Приветствую тебя, $C. Могу ли я чем-то помочь тебе?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3961, 'Приключения Линкена', 'Лично я полагаю, что Линкен явился сюда, чтобы избавить нас от Яропламеня... Он кажется простым парнем, однако он совсем не интересуется моими экспериментами и механизмами, как большинство гномов. Должно быть, в глубине души он истинный воин. $B$BОтдай тотем ему. Возможно, это поможет ему вспомнить, зачем он пришел сюда.', 'Отнесите серебряный тотем Аквамонтоса Линкену в Укрытие Маршалла.', 'Джей Ди вообще хоть чем-нибудь помогла тебе?', 'О, привет, $N!', NULL, NULL, 'Серебряный тотем Аквамонтоса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3962, 'Один в поле не воин', '$N, я наконец-то вспомнил... Я пришел сюда, чтобы сразиться с Яропламенем! Это и есть цель моего путешествия! $B$BНо я больше не герой... потому что герой стоит передо мной. Теперь ты $gдолжен:должна: закончить начатое. $B$BЯропламень стережет артефакт, именуемый Золотым пламенем. В нем кроется сила более мощная, чем что-либо мне известное, поэтому этот артефакт не должен попасть в дурные руки.$B$BИ мой тебе совет – не ходи $gодин:одна:. Один в поле не воин.', 'Отправляйтесь к Вулкану Огненного Венца, к югу от Укрытия Маршалла. Найдите Яропламеня и разрушьте его защитную ауру с помощью тотема. Когда дух будет сражен, заберите из пещеры Золотое пламя.', 'Спасибо, $N. $B$BТеперь Золотое пламя будет возвращено на мою родину, где мы сможем защитить его от посягающих на него негодяев. $B$BЕсли бы не ты, я до сих пор не помнил бы, кто я такой и зачем пришел! Я хочу отблагодарить тебя! $B$BБери все что нравится!', 'Яропламень почти неуязвим благодаря защитной ауре, создаваемой Золотым пламенем. Только тебе под силу разрушить ауру с помощью серебряного тотема Аквамонтоса.', NULL, NULL, 'Яропламень убито', 'Золотое пламя', 'Серебряный тотем Аквамонтоса (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3981, 'Командир Гор\'шак', 'Бедняга Гаргал... Он даже не успел ничего понять как – бац! – стрела вонзилась прямо ему в башку... Он и прежде гением не был, а теперь уж... $B$B*Гэлмав скорбно морщится.* $B$BКогда мы вытащили стрелу, заметили записку, прикрученную к древку. В ней не было ничего, кроме грубо нацарапанной картинки, изображающей, видимо, орка за решеткой, и подписи командира Гор\'шака. $B$BЕсли он еще жив и находится в Глубинах, ты $gдолжен:должна: отыскать его. $B$BЛовушка? Проклятье, какая еще ловушка, что ты несешь?! Отправляйся немедленно!', 'Найдите командира Гор\'шака в Глубинах Черной горы. Судя по рисунку в записке, искать следует в темнице где-то вроде того.', 'У нас мало времени. Слушай внимательно, $R. Сведения, которые я сообщу тебе, совершенно секретны и не подлежат разглашению.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (3982, 'Что происходит?', 'Меня прислал сюда Тралл, и я нахожусь под его покровительством. Неужели ты думаешь, что эти фигляры смогли бы меня поймать? Я разведчик, и я им поддался специально, чтобы собрать информацию.$B$B*Гор\'шак понижает голос.*$B$BИмператор Тауриссан похитил принцессу Стальгорна. Она сейчас здесь, в этом городе! Надо думать, когда старый Магни об этом узнал, его чуть удар не хватил.$B$B*Гор\'шак смеется.*$B$BТихо! Слышишь? Это стражники! ЗАЩИЩАЙСЯ!', 'Защитите Горшака.', 'На этот раз все обошлось. Но теперь они поднимут тревогу... и пришлют за тобой еще стражников.', 'Защищайся, придурок!', NULL, NULL, 'Вступите в схватку со стражниками и останьтесь в живых.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4001, 'Что происходит?', 'Пока что мне не удалось толком поговорить с Караном из темницы напротив. Однако я все-таки смог убедить его в том, что я – то есть мы – не обидим его и не сделаем ему ничего плохого.$B$BПоговори с ним и попробуй узнать о принцессе и ее похитителях. Всю информацию, которую удастся собрать, передай вождю.$B$BТралл не хочет, чтобы с принцессой что-то случилось. У него даже есть план, как вернуть ее в целости и сохранности в Стальгорн, и Карану все это уже известно... Иди!', 'Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар.Вы вспоминаете слова Гор\'шака о том, что Карана держат в темнице напротив.', 'Сейчас у Орды есть шанс изменить политическую ситуацию в нашем мире, истерзанном войной. Причем изменить радикально. Раз и навсегда. Слушай внимательно, $N.$B$BПостарайся, чтобы все получилось. Провал в этом деле смерти подобен.', 'Что привело тебя в это мрачное место?', NULL, NULL, 'Информация, полученная от Карана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4002, 'Восточные королевства', 'Принесенные тобой сведения чрезвычайно ценны, $N.$B$BЯ – вождь, и мой долг – действовать на благо Орды, так, чтобы грядущие поколения не были обречены на безнадежное прозябание!$B$BИ вот нам выпала возможность определить судьбу будущих союзов. Выступив на помощь дворфам, мы значительно укрепим свои взаимоотношения с Восточными королевствами. Вот почему твой долг – вернуться с победой!$B$B<Готов:Готова: ли ты?', 'Поговорите с Траллом.', 'Все, $N. Отныне пути назад нет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4003, 'Спасение принцессы', 'Этот удар, нанесенный дворфам Черного Железа, способен потрясти их королевство до основания.$B$BПринцесса находится под контролем императора Тауриссана. Чтобы ее освободить, необходимо убить императора. Имей в виду, твоя задача вдвойне опасна: пока принцесса находится во власти императора, она нападет на тебя, не раздумывая.$B$BНи в коем случае не причиняй ей вреда!!!', 'Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия.', 'Что ты наделал!', NULL, NULL, NULL, 'Император Дагран Тауриссан убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4004, 'Спасенная принцесса', 'Ты $gубил:убила: моего мужа, $r! Мой ребенок родится на свет без отца!$B$B*Принцесса Мойра указывает на вас.*$B$BИстинно говорю тебе, это дитя станет следующим королем Стальгорна. И тогда берегись! Этим преступным деянием ты $gнавлек:навлекла: на себя проклятие. Возмездие настигнет тебя и твой род. Всех вас будут травить до скончания дней!$B$B*Вы уверены, что принцесса Мойра до сих пор пребывает под действием чар Тауриссана.*$B$BОставь меня, $r. Поторопись к своему нанимателю. Наверняка он с нетерпением ждет вестей об исполнении его гнусных замыслов.', 'Вернитесь к Траллу в крепость Громмаш, что в Оргриммаре.', '*Тралл поражен вашим рассказом. Он явно не ожидал ничего подобного.*$B$BСтало быть, надо ждать новой угрозы. Магни уже немолод, кто знает, сколько ему осталось. А если Магни не станет, дорога к трону Стальгорна будет открыта для еще не рожденного отпрыска Черного Железа.$B$BТы исполнил мое поручение и получишь награду.$B$BА теперь оставь меня, $N! Мне надо посовещаться с Сильваной и Кэрном.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4005, 'Аквамонтос', 'Возьми этот мешок с припасами и отнеси в Танарис. Отправляйся в Бухту Сорванных Парусов и найди круг камней. $B$BВстав в этот круг, прочти заклинание из книги Аквора и вызови единственное создание, способное превратить собранные тобой предметы в тотем, с помощью которого можно сразить Яропламеня! $B$BАквамонтос не любит, когда его будят, но помни, ты $gдолжен:должна: быть внутри круга, когда будешь читать заклинание!', 'Отнесите книгу Аквора, серебристые когти и сердце Железнолесья в Танарис. Воспользуйтесь книгой для призыва Аквамонтоса. По получении тотема, отнести его Джей Ди Колли в Укрытие Маршалла.', 'Яропламень, говоришь...$B$BДа, я знаю, этот могучий элементаль обитает в опаленном центре кратера. Мы все стараемся держаться от этого места подальше – никому не удавалось проникнуть сквозь ауру этого создания. Многие смельчаки нашли свою смерть в расщелинах сердца кратера.', 'Так ты вернулся... Хмм... Дай-ка мне взглянуть...', NULL, NULL, 'Серебряный тотем Аквамонтоса', 'Припасы Эриданы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4021, 'Контратака!', 'Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости. Я получил сообщение, что отряд клана Колкар оставил свой дом в Пустошах и прибыл в Степи, движимый местью. Более того, они прямо сейчас подбираются к нам с запада!$B$BВыступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям. Убивай их, пока не появится их вождь, предводитель Кром\'зар. Одолей его и принеси в доказательство кусок его знамени.$B$BНе подведи меня, $N.', 'Принесите кусок знамени Кром\'зара Регтару Вратам Смерти. Его можно найти на западе от Перекрестка.', 'Получилось! Ты победил клан Колкар!$B$BЯ непременно сообщу Траллу о твоих подвигах, $N.$B$BМожешь гордиться собой, ты – достойный сын Орды.', 'Где знамя?', NULL, NULL, 'Кусок знамени Кром\'зара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4022, 'Вкус пламени', 'Стая знает о твоей работе в Тлеющем ущелье.$B$BПокажи ее, $r. Шкуру, $gкретин безмозглый:кретинка безмозглая:.', 'Покажите Цирусу Раскаивателю сброшенную кожу черного дракона, полученную от Веларока Ветрореза.', '*Цирус изучает шкуру.*$B$BНу что ж, тебе удалось доказать, что ты хоть на что-то пригоден, смертный.', '*Глаза Цируса вспыхивают, как две пылающих сферы.*', NULL, NULL, 'Сброшенная кожа черного дракона', 'Доказательство представлено', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4023, 'Вкус пламени', 'Ты ищешь Стаю? Принеси мне доказательства того, что ты $gдостоин:достойна: этого знания, $gсмертный:смертная:.', 'Покажите Цирусу Раскаивателю доказательство своих деяний.Возникает чувство, что Цирус заранее сомневается в ваших качествах.', '*Цирус изучает шкуру.*$B$BНу что ж, тебе удалось доказать, что ты хоть на что-то пригоден, смертный.', '*Глаза Цируса вспыхивают, как две пылающих сферы.*', NULL, NULL, 'Сброшенная кожа черного дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4024, 'Вкус пламени', 'Я хочу попробовать обжигающие языки пламени огненной горы. Чтобы сквозь меня текла лава Черной горы. Я жажду этого обжигающего тепла.$B$BБейл\'Гар живет в глубинах Черной горы. Он воплощение пламени, порождение огня Рагнароса.Убей Бейл\'Гара и возьми из его дымящихся останков частицу его внутреннего огня.$B$BЧтобы взять, не обжигаясь, этот огонь, воспользуйся драконьей шкурой.$B$BДобейся успеха, и награда будет велика.', 'Отправьтесь в глубины Черной горы и убейте Бейл\'Гара.Известно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл\'Гара его огненную сущность.Отнесите сущность Цирусу Раскаивателю.', '*Цирус выхватывает сущность Огня у вас из рук.*$B$BДА!$B$BБери награду и убирайся. Долой с глаз моих!', 'Пал ли от твоей руки великан?', NULL, NULL, 'Пойманная сущность огня', 'Измененная сброшенная шкура черного дракона', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4041, 'Эликсир Видере', '', '', 'Ну что, удалось тебе обойти старого Миблона, а?', NULL, NULL, NULL, 'Корень вечерника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4061, 'Восстание машин', 'Впервые мы увидели эти машины, когда начали набеги в Тлеющее ущелье. Потом выяснилось, что их привозят из Пылающих степей, вероятно, из глубин Черной горы. Нам нужна твоя помощь, $N. $B$BДля выполнения первого задания отправляйся в Пылающие степи и извлеки осколки элементалей из каменных машин и малых каменных созданий, которых там найдешь. Когда соберешь достаточно, возвращайся ко мне, и я попробую разобраться, откуда они происходят.', 'Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании. Теодора упоминала, что осколки можно найти у элементалей и големов.', '*Теодора раскладывает перед собой осколки и рассматривает их в огро$Nю лупу.* $B$BПрелюбопытно... На каждом из этих осколков выгравированы... инициалы.', 'Отнесись к этому заданию со всей серьезностью, $N!', NULL, NULL, 'Треснувший осколок элементаля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4062, 'Восстание машин', 'ГЛА. $B$BЭти инициалы выгравированы на осколках элементалей. Под ними выгравирована надпись, видимо, указующая на ранг машины. Механизмы, уничтоженные тобой в Пылающих степях, имели четвертый ранг. Полагаю, это один их низших рангов. $B$BВозьми этот образец осколка и отнеси его Лотвилю Вериатусу в лагерь на востоке. Он ученый, весьма признанный в сферах изучения cтихий. Возможно, он поможет нам советом.', 'Отнесите образец осколка элементаля Лотвилю Вериатусу. Теодора упоминала, что его лагерь находится на востоке.', '*Лотвил неожиданно бледнеет* $B$BЯ узнаю эти знаки...', 'Что это у тебя, $R?', NULL, NULL, 'Образец осколка элементаля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4063, 'Восстание машин', 'Неужели это Аргелмах? Не может быть! Он же мертв уже много лет! Почему я так в этом уверен? Да потому что это я убил его! $B$BЭтот презренный дворф имел маниакальную страсть к извращению моих изобретений – над которыми я, к слову, корпел годами! – и использованию их для своих мерзких делишек. Надо же, самые мерзкие создания всегда самые живучие! $B$BЕсли это и правда работа Аргелмаха, то он должен быть уничтожен. И мне потребуются образцы его последних творений. Если у меня будут образцы, возможно, я смогу придумать, как подавить восстание. Видимо, Аргелмах теперь в глубинах Черной горы под охраной своих творений.', 'Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилю. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии.', 'Что это?! Голова... Она не из плоти и крови! Это какое-то создание из черного железа! Аргелмах был ЕЩЕ ОДНОЙ машиной! Полагаю, в таком случае нам рано праздновать победу – на его место вскоре придет другой!', 'Так это и в самом деле был он? Так он жив?', NULL, NULL, 'Голова Аргелмаха', 'Невредимое ядро элементаля', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4081, 'УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа', 'По приказу полководца Клинозуба, командира каргатского экспедиционного отряда: $B$BВсе силы генерала Кузни Гнева в Глубинах Черной горы должны быть истреблены. $B$BКлан Кузни Гнева – беспощадные убийцы, ответственные за уничтожение 109-ого подразделения каргатского экспедиционного отряда. Необходимо сохранять бдительность. $B$BТот, кто сможет разбить передовые войска генерала Кузни Гнева в Глубинах Черной горы, будет представлен к награде.', 'Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! По приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания.', 'Небось, после такого Кузня Гнева в штаны наложил! Теперь проходи, проходи, солдат. У меня еще масса дел!$B$BСмотри внимательно на объявления, для тебя может найтись еще работенка.', NULL, NULL, NULL, 'Охранник из клана Ярости Горна убито', 'Надсмотрщик из клана Ярости Горна убито', 'Пехотинец из клана Ярости Горна убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4082, 'УНИЧТОЖИТЬ НА МЕСТЕ: Высокопоставленные чины Черного Железа', 'Приказ полководца Клинозуба, командира Каргатского экспедиционного корпуса: $B$BГлава разведывательного подразделения Каргатского экспедиционного корпуса, гроссмейстер Лекслорт вернулся с рапортом о месторасположении высокопоставленных чинов Черного Железа. В центре города, за закрытыми воротами они обучают своих солдат уничтожать наших собратьев. Отправляйся в Глубины Черной горы и уничтожь их! $B$BВ случае успешного выполнения задания будешь $gпредставлен:представлена: к награде.', 'Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! По приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания.', 'Не сомневаюсь, генерал Кузня Гнева теперь... в гневе. Возвращайся ко мне, когда получишь третью награду, и мы приступим к операции \"Смерть Кузне Гнева\". Пока не буду вдаваться в детали, но могу заверить наперед, что точно кто-нибудь умрет!', NULL, NULL, NULL, 'Медик из клана Ярости Горна убито', 'Солдат из клана Ярости Горна убито', 'Офицер из клана Ярости Горна убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4083, 'Призрачный кубок', '', '', 'Призрачный кубок парит в воздухе, медленно поднимаясь и опускаясь... как будто следуя ритмам биения умирающего сердца.', NULL, NULL, NULL, 'Звездный рубин', 'Золотой слиток', 'Слиток истинного серебра', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4084, 'Серебряное сердце', 'Я не знаю, о ком ты говоришь, $N. $B$BНо если твой друг искал меня, я знаю, что ему было нужно. $B$BВ сердце Кратера Ун\'Горо скрывается зло в чистейшей его форме – это элементаль, именуемый Яропламень. Он защищен аурой, разрушить которую не под силам никому... $B$BНикому, кроме обладателя еще большей силы. Я научу тебя, как справиться с этой задачей, $N. $B$BСначала сделай, что я попрошу. Собери и принеси мне 11 серебристых когтей и 1 сердце Железнолесья – ты найдешь их у созданий Оскверненного леса.', 'Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра из Оскверненного леса.', 'Прекрасно, $N. Вижу, ты всегда готов помогать друзьям.', 'Я расскажу тебе о том, как сразить Яропламень, но прежде принеси мне то, что чем я просила тебя.', NULL, NULL, 'Серебристые когти', 'Сердце Железнолесья', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4101, 'Очищение Оскверненного леса', 'Растения дают жизнь Оскверненному лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!$B$BК северу отсюда лежат пещеры Железнолесья. Тамошние криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя, принеси мне их застывший сок – его называют кровавым янтарем, – чтобы я могла изучить его в надежде спасти другие формы здешней жизни.', 'Принесите 15 кровавых янтарей Аратандис Серебряному Небу в Оскверненный лес.', 'Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Оскверненный лес. Ты доказал мне, что готов сделать все для Круга Кенария. Теперь я доверяю тебе.$B$BМожет показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства. Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов, которые я смогу сделать.$B$BПришла пора исцелить Оскверненный лес, $N.', 'Оскверненный лес страдает, $N – а вместе с ним и я! Я должна быть уверена во всем – если мои знания попадут в злые руки, это обернется бедой для всего Оскверненного леса.$B$BПринеси мне кровавый янтарь с убитых Криводревов-элементалей, и я поверю, что ты искренне помогаешь мне в поисках средства борьбы с порчей.', NULL, NULL, 'Кровавый янтарь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4102, 'Очищение Оскверненного леса', 'Растения дают жизнь Оскверненному лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!$B$BК северу отсюда лежат пещеры Железнолесья. Тамошние криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя, принеси мне их застывший сок – его называют кровавым янтарем, – чтобы я могла изучить его в надежде спасти другие формы здешней жизни.', 'Принесите 15 кровавых янтарей Майбессе Речному Ветру в Оскверненный лес.', 'Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Оскверненный лес. Ты доказал мне, что готов сделать все для Круга Кенария. Теперь я доверяю тебе.$B$BМожет показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства. Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов. которые я смогу сделать.$B$BПришла пора исцелить Оскверненный лес, $N.', 'Оскверненный лес страдает, $N – а вместе с ним и я! Я должна быть уверена во всем – если мои знания попадут не в те руки, это обернется бедой для всего Оскверненного леса.$B$BПринеси мне кровавый янтарь с убитых Криводревов-элементалей, и я поверю, что ты искренне помогаешь мне в поисках средства борьбы с порчей.', NULL, NULL, 'Кровавый янтарь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4103, 'Лекарство из охотничьих трофеев', '', '', 'Очень хорошо, вот тебе кенарийский бальзам. Ищи в Оскверненном лесу пораженные растения, $N! Когда найдешь, исцеляй их при помощи моего целебного бальзама.', NULL, NULL, NULL, 'Оскверненный осколок души', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4104, 'Лекарство из минералов', '', '', 'Что же, прекрасно! Вот тебе кенарийский бальзам. Если при разработках жил металлов в Оскверненном лесу найдешь еще порченого купороса, не забудь принести его мне! Чем больше найдешь, тем больше бальзама я смогу сделать.', NULL, NULL, NULL, 'Затронутый порчей купорос', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4105, 'Лекарство из оскверненных трав', '', '', 'Отличная работа, $N – все это после очищения пойдет на исцеление Оскверненного леса. Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес. Исцеление этого края от порчи не терпит отлагательств!', NULL, NULL, NULL, 'Зародыш Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4106, 'Лекарство из оскверненных шкур', '', '', 'То что нужно! Вот, бери этот бальзам для исцеления растений и лечи им Оскверненный лес от порчи! Мы не должны сдаваться, $N!', NULL, NULL, NULL, 'Клочок порченой шкуры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4107, 'Лекарство из распыленных предметов', '', '', 'Вот тебе кенарийский бальзам, и за него я прошу только одну порцию малой субстанции Пустоты, $N. Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала. Если тебе понадобится еще бальзам, ищи меня тут!', NULL, NULL, NULL, 'Простая субстанция Хаоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4108, 'Лекарство из охотничьих трофеев', '', '', 'Очень хорошо, Вот тебе кенарийский бальзам. Ищи в Оскверненном лесу пораженные растения, $N! Когда найдешь, исцеляй их при помощи моего целебного бальзама.', NULL, NULL, NULL, 'Оскверненный осколок души', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4109, 'Лекарство из минералов', '', '', 'Что же, прекрасно! Вот тебе кенарийский бальзам. Если при разработках жил металлов в Оскверненном лесу найдешь еще порченого купороса, не забудь принести его мне! Чем больше найдешь, тем больше бальзама я смогу сделать.', NULL, NULL, NULL, 'Затронутый порчей купорос', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4110, 'Лекарство из оскверненных трав', '', '', 'Отличная работа, $N – все это после очищения пойдет на исцеление Оскверненного леса. Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес. Исцеление этого края от порчи не терпит отлагательств!', NULL, NULL, NULL, 'Зародыш Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4111, 'Лекарство из оскверненных шкур', '', '', 'То что нужно! Вот, бери этот бальзам для исцеления растений и лечи им Оскверненный лес от порчи! Мы не должны сдаваться, $N!', NULL, NULL, NULL, 'Клочок порченой шкуры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4112, 'Лекарство из распыленных предметов', '', '', 'Вот тебе кенарийский бальзам, и за него я прошу только одну порцию простой субстанции Пустоты, Хафф. Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала. Если тебе понадобится еще бальзам, ищи меня тут!', NULL, NULL, NULL, 'Простая субстанция Хаоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4113, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4114, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4115, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4116, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4117, 'Оскверненный кнутокорень', '', '', 'Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4118, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4119, 'Оскверненный ночной дракон', '', '', 'Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4120, 'Сила порчи', 'Я – охотник, и всегда стремлюсь превзойти силой своих противников. Запомни, $N: всегда можно обратить ситуацию в свою пользу, если хорошо знаешь врага.$B$BК северу от Ясеневого леса есть место, называемое Оскверненный лес. Тамошние звери запятнаны веществом, которое именуется скверной. Медведи и волки от него совершенно взбесились, но в то же время скверна сделала их сильнее обычного.$B$BСтупай, $N. Отправляйся в Оскверненный лес, чтобы встретиться с этими тварями лицом к лицу.', 'Убейте 12 гризли злобных когтей и 12 опустошителей-сквернолапов в Оскверненном лесу по просьбе Тало Тернового Копыта из лагеря Мохаче.', 'Судя по твоему описанию, эти твари отличаются безоглядной свирепостью…$B$BОставайся начеку, $N. Тебе стоит как можно больше узнать о порче. Врага нужно знать в лицо!', NULL, NULL, NULL, 'Гризли злобных когтей убито', 'Опустошитель-сквернолап убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4121, 'Опасное положение', 'Ты в самом деле надеешься добраться до точки встречи, держа меня в плену? Ты и правда рассчитываешь, ворвавшись в крепость Черной горы и похитив главную ценность клана, удрать $gнезамеченным:незамеченной:?$B$BДа тебя в порошок сотрут!', 'Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью.Лекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму.Также отдайте Лекслорту ториевые оковы.', 'Твой подвиг не пропадет втуне. Ты заслужил эту награду. Теперь Вождь поведает тебе о последнем задании.', 'Давай сюда этого предателя, $N.', NULL, NULL, 'Ториевые оковы', 'Доставка пленника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4122, 'Грарк Лоркруб', 'Я шел за ним через Тлеющее ущелье, через горы и Пылающие степи. Предателя поймали на месте преступления, когда тот передавал оркам Черной горы сверхсекретную информацию о деятельности нашего отряда. Я говорю о Грарке Лоркрубе. $B$BОн теперь в Пылающих степях, под их надежной охраной – по крайней мере, он сам так думает. $B$BВозьми эти оковы, $N. Найди Грарка, надень на него эти оковы и доставь сюда. Награда будет достойной.', 'Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. По обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника.', 'Разве ты не понимаешь, какую силу можно обрести, присоединившись к армии Черной горы?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4123, 'Сердце горы', 'Сколько лет я ищу этот камень! Он называется \"сердце горы\". Размером как раз с твой кулак. Дворфы Черного Железа прячут его в своих тайных подвалах. Я пытался его купить, предлагал им хорошую цену, но они не продают!$B$BПридется забрать его силой, другого способа я не вижу.$B$BТебе надо пробиться на нижний ярус Глубин Черной горы, взломать потайной сейф и забрать сердце. Для того чтобы добраться до тайника, тебе придется сразиться с тамошним стражником. Его зовут Хватка Смерти, и он появится только тогда, когда ты вскроешь все сундуки и сейфы!$B$BУдачи.', 'См. Сердце горы. Принесите сердце горы Максворту Суперблеску в Пылающие степи.', 'Ты добыл Сердце! Великолепно! Оно даже прекраснее, чем мне представлялось!$B$BПрошу тебя, $N, прими это в уплату за свои труды!', 'Ты принес сердце горы? Для меня его ценность поистине безгранична.', NULL, NULL, 'Сердце горы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4124, 'Пропавший курьер', 'Моему соратнику, Гинро Пылающему Очагу, нужна помощь. Он ищет курьера и пакеты, которые тот вез. Курьер пропал примерно неделю назад; наши собственные поиски результата не дали. Мы зашли в тупик. Пришлось объявить курьера пропавшим без вести.$B$BЕсли у тебя есть свободное время, пожалуйста, поговори с Гинро. Он должен быть где-то здесь. Возможно, он у себя.', 'Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.', 'Ты от Латро, я так понимаю? Я думаю, что дело глухо, но готов принять любую помощь. Должен признаться... я буду рад, когда вопрос решится хоть как-то. Я каждое утро выезжаю в лес разыскивать следы Раскала, и каждый вечер возвращаюсь домой с пустыми руками!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4125, 'Пропавший курьер', 'Прошла примерно неделя с тех пор, как Раскал, курьер, отправился в Таланаар. Фералас он знает, как свои пять пальцев – он был здесь с нами с самого начала, с тех пор, как генерал Оперенная Луна привела сюда экспедиционный корпус. Я знаю, что он собирался взять весельную лодку и проплыть вдоль побережья Фераласа, чтобы миновать лагерь Орды.$B$BЕго лодки я так и не обнаружил – но, возможно, тебе это удастся. Может быть, она спрятана либо потонула. А между тем именно лодка может помочь выяснить, где Раскал. Если найдешь что-нибудь, дай мне знать.', 'Отыщите лодку курьера, которая должна находиться где-то на побережье Фераласа.', 'Вы обнаружили затонувшую лодку. Сквозь мутноватую воду видны дыры, зияющие в левом борту. Кажется, будто лодка буквально ободрана до своего деревянного остова. Такое впечатление, что лодку пытались перекусить пополам. На правом борту нарисован небольшой герб Крепости Оперенной Луны.$B$BВ иле, скопившемся на дне лодки, блеснул металл...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4126, 'Харли Чернопых', 'Подонки Черного Железа под предводительством гнусного Харли Чернопыха украли рецепт нашего лучшего громоварского светлого! Подлые твари! Они не достойны такого прекрасного напитка!$B$B$N, у меня есть для тебя работа. Отправляйся в Глубины Черной горы в Пылающих степях, уничтожь все бочонки с громоварским светлым, какие сумеешь найти, и забери у мерзавцев наш рецепт!$B$BПереверни все Глубины, но найди этот рецепт!', 'Найдите украденный рецепт громоварского и верните его Рагнару Громовару в Каранос.', 'Рецепт у тебя! Ты молодец! Надеюсь, ты задал жару этим подонкам и Харли Чернопыху? Так им и надо, мерзавцам!$B$BНаше семейство перед тобой в неоплатном долгу, $N. Ты настоящий герой!', 'Ты нашел рецепт, $N? Меня передергивает от одной мысли о том, что эти наглецы будут пить наш фамильный напиток!', NULL, NULL, 'Украденный рецепт громоварского', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4127, 'Разбитая лодка', 'Копаясь в иле, вы нащупываете рукоятку ножа. Похоже, тот, кто плыл на лодке, его потерял. Рядом валяются обломки самой лодки…$B$BВы берете нож с собой: Гинро Пылающий Очаг из Крепости Оперенной Луны велел вам принести ему все, что может помочь разгадать тайну. Однако вас не покидает ощущение, что вы тут не одни...', 'Вернитесь в Крепость Оперенной Луны и покажите Гинро Пылающему Очагу выброшенный нож, который вы нашли.', 'Интересно... Похоже, это нож Раскала. Так говоришь, он валялся на дне, рядом с обломками его лодки? Ну, может быть, этой находки и недостаточно, чтобы делать какие-то выводы. Но у нас есть один необычный способ узнать побольше…$B$BДоводилось ли тебе слышать о сверхзнании?', 'А, $N! С возвращением. Надеюсь, тебе удалось узнать что-нибудь о судьбе Раскала? Даже если его судьба трагична...', NULL, NULL, 'Выброшенный нож (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4128, 'Рагнар Громовар', 'Здравствуй, $N. Ходят слухи, что кто-то украл у Рагнара Громовара его драгоценный эль. Бедолага рвет и мечет! Ему нужен отважный и дерзкий наемник, который возьмется за это дело. Рагнар готов хорошо заплатить.$B$BЕсли тебе интересно, переговори с ним. Он сейчас в своей \"Громоварке\" в Караносе. Это в Дун Морог.', 'Переговорите с Рагнаром Громоваром.', 'Да, ты прав, я не просто рассержен. Я в бешенстве! Меня обокрали! Эти скоты сперли наш старый фамильный рецепт! Да как они только посмели?! Я и раньше-то их ненавидел... этих поганых дворфов из клана Черного Железа! А теперь... ох, как я зол!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4129, 'Тайна ножа', 'У нас в крепости живет друид, Квинтис Ночной Костер, который умеет... много всего. В частности, он владеет сверхзнанием – способностью узнавать на ощупь историю предмета. Не спрашивай, как он это делает – я в этом не разбираюсь, и разбираться не хочу. Я знаю только две вещи: во-первых, я видел, как это работает, а во-вторых, этот друид у меня в долгу.$B$BКороче, тащи этот ножик к Квинту, в его жилище на дереве, и передай, что должок, который за ним числится, будет уплачен, если он разберется с этой штукой.', 'Отнесите выброшенный нож к друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.', 'Спасибо, $N.$B$BКонечно, сверхзнание точным искусством не назовешь, с какой стороны ни взгляни, но все же в былые времена я не раз с его помощью разбирался в ситуациях, которые все прочие сочли безнадежными. Думаю, на этот раз оно поможет нам хотя бы отчасти понять, что произошло с Раскалом.$B$BВремени это много не займет, но легким и приятным это дело не назовешь. Так что будь готов прийти мне на помощь.', 'Ты от Гинро, да? Ох, нелегкая это работа... впрочем, долг платежом красен. А они еще издеваются, говорят, мол, не везет в карты – повезет в любви... Впрочем, мне везет скорее в постижении тайн природы.$B$BНет, конечно, я это сделаю. Возможно, это именно то, чего нам недостает, чтобы узнать о судьбе Раскала. Давай сюда нож, и возьмемся за дело.', NULL, NULL, 'Выброшенный нож (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4130, 'Сверхзнание', 'Извини, меня до сих пор немного пошатывает. Как бы то ни было, я увидел несколько полезных вещей.$B$BРаскал вытащил два больших кожаных заплечных мешка из своей лодки и направился прочь от воды. Однако потом вернулся к лодке. Вижу скальпы гноллов... он наткнулся на гноллов – кажется, это тот клан, который называют Древолапами. Он чем-то очень озабочен, даже вроде бы напуган. Раскал настолько поглощен своими мыслями, что не замечает, как у него за спиной материализуются элементали воды. И... и все. Больше я ничего не увидел.$B$BИзвини, $N. Мне необходимо отдохнуть. Расскажи Гину о том, что я видел. Ему следует это знать...', 'Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.', 'Спасибо, что рассказал мне о видениях Кинта, $N. Так и быть, в следующий раз, как мы с ним сядем за карты, постараюсь быть к нему подобрее.$B$BНу, в бою Раскал никому не уступит, и гноллы – не те, кто может его обеспокоить, тем более, напугать. Но, может быть, эти новые сведения тебе все же пригодятся?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4131, 'Гноллы из стаи Древолапов', 'Возможно, Раскала сцапали наши \"друзья\" из клана Древолапов, но что-то мне подсказывает, что дело было не так. И все равно начать лучше всего с их лагерей.$B$BКонечно, хотелось бы иметь более отчетливые сведения, но пока что у нас нет ничего, кроме смутного указания на лагеря гноллов. Я знаю, что гноллы хранят у себя награбленное и дерутся из-за добычи. Возможно, они просто наткнулись на заплечные мешки, которые упоминал Кинт. Прежде я не рисковал соваться к гноллам, но теперь, когда у нас есть сведения, полученные от Кинта, попробовать стоит.', 'Обыщите лагеря Древолапов в южном Фераласе в поисках вещей курьера либо самого курьера.', 'На ближайшем дереве висят два больших кожаных мешка. На обоих виднеется метка Крепости Оперенной Луны...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4132, 'Операция:смерть Кузне Гнева', 'Ты $gпроделал:проделала: отличную работу, $N! Теперь пришло время для последнего задания. $B$BГенерал Кузня Гнева, ответственный за атаки Черного Железа на 109-ое подразделение Каргатского экспедиционного корпуса и масовые убийства наших солдат, должен понести наказание. $B$BЭто непростое задание, но в случае успеха труды окупятся сторицей.', 'Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания.', 'Наконец-то! Возмездие настигло негодяя! Ты отлично сражался, $N! Носи этот медальон как символ твоих заслуг перед Ордой и Каргатским экспедиционным корпусом.', NULL, NULL, NULL, 'Генерал Кузня Гнева убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4133, 'Вивиана Лягроб', 'Тенемагу Вивиан Лягроб нужна твоя помощь. Она сейчас в Бесплодных землях, на сторожевой заставе Каргат. Там недавно прошел слух о небезызвестном напитке, сваренном дворфами Черного Железа в Глубинах Черной горы, – вот она и отправилась проверить.$B$BПоговори с Вивиан. Она тебя ждет.', 'Переговорите с тенемагом Вивиан Лаграв в Каргате.', 'Спасибо, что ты пришел, $N. Это место не лишено своеобразного сурового очарования, но ему не хватает утонченности Района Фармацевтов.$B$BВпрочем, я позвала тебя не для того, чтобы вести светские беседы. Давай сразу к делу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4134, 'Украденный рецепт громоварского', 'Ходят слухи, что Харли Чернопых из клана Черного Железа украл рецепт эля. Говорят, этот эль, громоварское светлое, придает великую силу и храбрость тому, кто его употребит. Нам хотелось бы изучить состав этого напитка. Может быть, мы найдем и другое применение его удивительным свойствам... подходящее для целей Отрекшихся.$B$BОтправляйся в Глубины Черной горы, найди Харли, забери у него рецепт громоварского светлого и принеси его мне.$B$BВозможно, тебе придется выманить Харли из укрытия. Для этого пригрози ему уничтожением его драгоценного эля.', 'Принесите рецепт громоварского светлого Вивиан Лягроб в Каргат.', 'Вот и славно. Я отошлю рецепт в Район Фармацевтов. Его там изучат, и со временем мы раскроем его секреты. И, возможно, придет такой день, когда дворфы Альянса с удивлением обнаружат, что волшебные свойства их тайного напитка против них же и обернулись!$B$BПо-моему, это будет забавно. Видимо, смерть как-то странно влияет на чувство юмора... ты не находишь?', 'Ты добыл рецепт, $N?', NULL, NULL, 'Украденный рецепт громоварского', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4135, 'Гудящая Бездна', 'В рюкзаках находится два предмета: во-первых, посылка, адресованная в Таланаар, а во-вторых – записка, адресованная неизвестно кому.$B$BВ записке, набросанной торопливым почерком, говорится об обнаружении коварных насекомоподобных существ к югу от лагерей гноллов, в лесах, известных как \"Гудящая Бездна\". Автор сообщает, что намерен лично проникнуть туда, поскольку речь может идти о серьезной опасности, грозящей всему Фераласу. Записка подписана \"Раскал из Оперенной Луны\".$B$BПохоже, вам наконец-то удалось выяснить, куда делся Раскал...', 'Продолжайте поиски Раскала (или его останков) в Гудящей Бездне. Согласно записке, Гудящая Бездна находится к югу от лагерей стаи Древолапов.', 'Вам удалось обнаружить огромный кокон непонятного происхождения. Сам кокон мягкий и слизистый, но изнутри в разных местах выпирает что-то твердое. Размеры кокона позволяют предположить, что внутри может находиться гуманоид среднего роста... и сквозь стенки кокона действительно просвечивают очертания фигуры гуманоида!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4136, 'Риббли Крутипроб', 'Мой братец Риббли всегда только и делал, что тянул денежки из семьи и тратил их на какие-то поганые махинации.$B$BПохоже, последний его проект оказался поганее прочих, потому что барон Ревилгаз из Пиратской Бухты назначил награду за голову бедняжки Риббли. Ты даже не представляешь, как возрадовались все Крутипробы! Наш малыш Риббли наконец хоть чего-то да стоит!$B$BНо сейчас он скрывается в Глубинах Черной горы. Найди его и приведи ко мне!$B$BА если он не пойдет добром... ну что ж, не пойдет – и не надо... тогда принеси мне его голову.', 'Принесите голову Риббли Юке Крутипроб в Пылающие степи.', 'Ага! Ты нашел его! И... как я понимаю, мой маленький братец не пожелал возвращаться в семью. Очень жаль. Посмотрела бы я на его рожу, когда он услышал о том, что мы собираемся сдать его Ревилгазу.$B$BСпасибо, $N. Ты даже не представляешь, как порадовал все наше семейство. И Риббли сейчас такой тихий и славный... он никогда таким не был.', 'Ты привел Риббли? Хотя меня больше интересует не столько он сам, сколько его голова.', NULL, NULL, 'Голова Риббли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4141, 'Муиджин и Ларион', 'Видишь Лариона вон там? Это ОН виноват, что мы застряли здесь! $B$BЯ говорил ему, что мы идем не туда, но разве он меня слушал? И представляешь, после этого он еще и не желает со мной разговаривать! Ну, пока он не передумает, я позабавлюсь! $B$BТы $gзаметил:заметила: здесь таких странных созданий, похожих на цветы? На самом деле это довольно умные зверушки. Думаю, их можно надрессировать на всякие фокусы. $B$BВ первую очередь, мне нужны образцы для изучения. Сможешь принести мне несколько?', 'Соберите 15 кровоцветов и принесите их Муиджину.', 'Надеюсь, они не доставили тебе забот, $N? Крайне дикие создания! $B$BОднажды я попытался перепрыгнуть через один такой цветочек, так он напал на меня! Растения не должны так себя вести...', 'Ну, Ларион, ты сам нарвался...', NULL, NULL, 'Кровоцвет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4142, 'Визит к Грегану', 'Не знаю, что и сказать тебе, $N. У этих растений, видимо, имеются зачатки разума. $B$BВпрочем, я не специалист. Однако знаю, к кому обратиться за действительно профессиональным мнением. $B$BОтправляйся в Фералас и найди там моего приятеля по имени Греган Пивоплюй. Он на таких вещах собаку съел. $B$BУверен, Греган сможет дать нам действительно дельный совет. Думаю, искать его лучше где-нибудь в лесу – парень никак не городской житель.', 'Отнесите кровоцвет Грегану Пивоплюю в Фералас.', 'Кровоцвет, говоришь? Хмм... В общем, сначала расскажи мне, что собираешься делать, а уж потом я скажу тебе, смогу ли помочь.', 'Я живу здесь, в лесу... Очень, знаешь ли, спокойно и благостно. $B$BПо крайней мере я сам так думал. Теперь ко мне шастает столько гостей, сколько я не видал в худшие дни в Стальгорне! Просто проходной двор какой-то!', NULL, NULL, 'Кровоцвет (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4143, 'Туман зла', 'Честно говоря, $N, мне никогда прежде не доводилось видеть подобных растений. Возможно, имеет смысл наведаться в этот кратер... $B$BВ любом случае, думаю, что знаю, что именно ищет Майджин. Ему нужен туман Атал\'ай. Это жуткая субстанция, которую весьма сложно собрать, однако именно этот туман необходим ему, чтобы управлять маленькими монстрами. $B$BТебе нужно найти храм Атал\'Хаккар на болоте Печали. Туман Атал\'ай можно собрать с обитающих там глубинных скрытней, мракочервей и слизнюков. Удачи тебе, $N!', 'Соберите 5 образцов тумана Аталаи и принесите их Муиджину в Кратер Ун\'Горо. ', 'Признаю, мне очень боязно прикасаться с этой штуке, $N! Но раз Греган утверждает, что она работает, надо попробовать.', 'Ларион все еще не разговаривает со мной! Надо же, надулся, как мышь на крупу.', NULL, NULL, 'Туман Атал\'ай', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4144, 'Побеги кровоцвета', '', '', 'Ну, приступим, $N! Уж это привлечет внимание Лариона, будь уверен!', NULL, NULL, NULL, 'Побег кровоцвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4145, 'Ларион и Муиджин', 'Видишь там Майджина? Это ОН виноват, что мы потерялись! $B$BЯ знал дорогу, но он настоял на том, чтобы пойти \"коротким путем\" и вот! Мы застряли в этой дыре! $B$BЧто еще хуже, он теперь взялся натравливать на меня этим проклятых паразитов – кровоцветы! Я так зол, что не собираюсь говорить с ним. А эти паразиты – просто последняя капля! $B$BДумаю, в первую очередь мы перекроем ему снабжение! Пойди-ка, поохоться на кровоцветы, а потом возвращайся ко мне.', 'Уничтожьте 5 кровоцветов-хлестунов, 5 кровоцветов-крепкозубов, 5 кровоцветов-живодеров и 5 кровоцветов-звероловов по просьбе Лариона из Укрытия Маршалла.', 'Спасибо за помощь, $N, однако боюсь, у меня плохие новости...', NULL, NULL, NULL, 'Кровоцвет-хлыстун убито', 'Кровоцвет-зверолов убито', 'Кровоцвет-живодер убито', 'Кровоцвет-крепкозуб убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4146, 'Питание для шокера', 'Тебе повезло, $N! Я тут работал над кой-какими собственными изобретениями, пока Марвон в отъезде. И вот моя последняя разработка – антижучиный шокер ближнего действия! Его надо совсем чуть-чуть поправить, и можно смело использовать против кровоцветов-паразитов. С удовольствием подарю тебе одну из моих тестовых моделей, однако для нее необходимо питание – туман Атал\'ай. Его можно собрать в храме Атал\'Хаккар с обитающих там трясинных скрытней, мракочервей и слизнюков.', 'Доставьте незаряженный шокер и 5 образцов тумана Аталаи Лариону в Укрытие Маршалла.', 'Так Марвона там не было? И что же ты оттуда принес?', 'Эти твари меня достали, $N! Просто достали!', NULL, NULL, 'Разряженный громобой (Прилагается)', 'Туман Атал\'ай', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4147, 'Мастерская Марвона', 'Мне удалось проследить за Муиджином – он и впрямь выращивает эти проклятые растения! $B$BДумаю, единственным решением будет... Нет, говорить с ним бесполезно, надо готовиться к ответному удару! $B$BНам потребуется помощь моего друга Марвона, у него мастерская в Кабестане.', 'Отправьтесь к Марвону Клепальщику в его мастерскую в Кабестане.', 'Марвона здесь давно нет, $N. Он отправился в Танарис, изучать развалины древних поселений троллей. $B$BА зачем он был тебе нужен?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4148, 'Разряд кровоцвета', '', '', 'Похоже, это устройство прекрасно сработает, $N. Помни, как только заметишь где-нибудь этих паразитов, немедленно используй шокер!', NULL, NULL, NULL, 'Побег кровоцвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4161, 'Калдорайский рецепт', 'Давным-давно ночные эльфы назывались кальдораями, \"детьми звезд\". Изучение прошлого – важный шаг на пути $c, $N, так что слушай внимательно все, что я расскажу тебе.$B$BКальдораи всегда гордились тем, что живут в гармонии с природой. Это означает, что мы берем у природы только то, что нам необходимо, и воздаем ей сторицей. Это равновесие позволяло нам вершить многое, $N.$B$BСтупай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне.', 'Принесите 7 маленьких паучьих лапок Заррину в Доланаар.', 'Всегда помни то, что я ныне показал тебе, $N. Ты – часть того равновесия, которое ночные эльфы стремятся поддерживать даже в тревожные времена.', 'Помни о равновесии, $N. Желаю тебе открыть в себе понимание и любовь к живым лесам.', NULL, NULL, 'Небольшая паучья лапка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4181, 'Гоблинское инженерное дело', 'В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул гоблинское инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер.$B$B$N, почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого.', 'Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.', 'Что же, $N, ты разумно поступаешь, прося у меня наставничества! Любой дурак может стать экспертом в азах инженерного дела – что прекрасно видно на примере гномов и их радиоактивного Гномрегана. Для овладения гоблинским инженерным делом требуется крепкая соображаловка и твердая (повторяю – ТВЕРДАЯ) рука.$B$BДержи ушки на макушке, $N, может, что и усвоишь.', 'Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?', NULL, NULL, 'Справочник по инженерным дисциплинам (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4182, 'Драконья угроза', 'Жизнь в Пылающих степях никогда не бывает спокойной.$B$BТолько посмотри вокруг! Мы не знаем, что случилось с этими строениями, но до большого взрыва все это было частью Красногорья.$B$BНо довольно скулить! У нас есть более насущная проблема. Может быть, ты $gзаметил:заметила: драконов под этим хребтом. Необходимо вынудить их отступить. Убей как можно больше и возвращайся. Если ты добьешься успеха, я дам тебе другое задание.', 'Убейте 15 детенышей черного дракона, 10 черных драконидов, 4 черных драконид и 1 черного дракона.', 'Добрая охота, $N. Ну, раз ты можешь справиться с драконами и их прихвостнями, пора поговорить о более насущных проблемах.', NULL, NULL, NULL, 'Детеныш черного дракона убито', 'Черный драконоид убито', 'Черный дракон убито', 'Черная драконида убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4183, 'Подлинные хозяева', 'Мы всегда думали, что орки Черной Горы такие жестокие от природы. Оказывается, дело обстоит иначе.$B$BДа, их и правда ведет в бой жажда крови и любовь к сражениям, но руководят ими черные драконы. Мы подозреваем, что именно они возбуждают в них ярость и злобу.$B$BОтнеси это письмо мировому судье Соломону. Он скажет, что делать.$B$B*Хелендис протягивает вам запечатанное письмо.*', 'Отправьтесь в Приозерье, что в Красногорье, и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону.', '*Мировой судья Соломон распечатывает письмо от Хелендиса и начинает читать.*', 'Приветствую тебя, $N. Мы уже встречались? Твое лицо кажется мне знакомым.', NULL, NULL, 'Письмо Хелендиса Речного Мыса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4184, 'Подлинные хозяева', 'Дурные вести, $N. Нетрудно прийти в отчаяние, узнав, что твои смертельные враги – всего лишь пешки куда более страшного противника. Приозерью не пережить натиска орков Черной Горы и черных драконов. Если падет Приозерье, следующим будет Темнолесье, а что потом? Златоземье? Сам Штормград?$B$BНемедленно отнеси это сообщение королю Вариану Ринну в Штормград! Если мы и этим не добьемся от столицы помощи, то не добьемся никакими силами, и все пропало.', 'Передайте обращение Соломона королю Вариану Ринну.Король Ринн пребывает в Крепости Штормграда.', 'Драконы? Быть того не может!', 'Что привело тебя в Крепость Штормграда?', NULL, NULL, 'Обращение Соломона к королю Ринну (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4185, 'Подлинные хозяева', 'Грустную картину нарисовал Соломон. Тем не менее, мы не можем позволить себе посылать наши и без того скудные войска на помощь Приозерью, основываясь только на догадках. Мне понадобится доказательство правоты его заявлений, прежде чем я смогу предпринять какие-то действия.$B$BПоговорите с леди Престор, $N. Она женщина ученая и много чего знает о драконах и драконидах. Возможно, она сможет пролить какой-то свет на эту ситуацию.', 'Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор.', '*Болвар подпирает рукой подбородок, как бы глубоко задумавшись.*$B$BВ то время как я уважаю позицию леди Престор, я уверен, что для этой дилеммы есть решение, которое могло бы развеять все наши тревоги.', '*Болвар пристально смотрит на вас.*', NULL, NULL, 'Совет от госпожи Престор', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4186, 'Подлинные хозяева', 'Я намерен наделить тебя полномочиями представителя, действующего от имени Штормграда, $N.$B$BВозвращайся к мировому судье Соломону в Приозерье и передай ему этот указ.', 'Отнесите указ Ринна мировому судье Соломону в Приозерье.', 'Ну, полагаю, могло быть и хуже...$B$B*Мировой судья изучает вас взглядом.*$B$BПохоже, что судьба Озер ложится теперь на ваши плечи.$B$B*Вы замечаете, что мировой судья часто-часто моргает. Кажется, он плачет.*', 'Есть какие-то новости от лорда Болвара?', NULL, NULL, 'Указ Ринна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4201, 'Приворотное зелье', 'О, терзания и муки неразделенной любви! Мои чары не действуют на возлюбленного. Рядовой Камнеузл отвергает меня! Это невыносимо!$B$BТы $gдолжен:должна: мне помочь! Мы, суккубы, хорошо разбираемся в любовных делах, и я могу приготовить волшебное зелье, которое разрушит железную стену вокруг непреклонного сердца Каменного Узла. Для того чтобы сварить это зелье, мне нужна трава кровь Грома, серебряные слитки скальных великанов Азшары и вода из источников Голакка в Кратере Ун\'Горо. Воду можешь набрать в этот сосуд.$B$BПрошу тебя, $N, помоги моей бедной истерзанной душе обрести радость и счастье!', 'Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы.', 'Ты все принес! Теперь я смогу приготовить волшебный напиток, и Каменный Узел воспылает ко мне любовью!$B$BСпасибо, Тыж. Ты – истинный рыцарь любви!', 'Ты принес все, что нужно? Боль в моем сердце растет с каждым днем!', NULL, NULL, 'Кровь Грома', 'Огромный серебряный слиток', 'Наполненный сосуд Нагмары', 'Сосуд Нагмары');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4221, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4222, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4223, 'Подлинные хозяева', '*Мировой судья вздыхает.*$B$BВозвращайся в Пылающие степи, $N. Как представитель Штормграда ты $gдолжен:должна: предстать перед маршалом Максвеллом. Удачи.', 'Поговорите с маршалом Максвеллом в Пылающих степях.', '<Маршал Максвелл смеется.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4224, 'Подлинные хозяева', 'Что? Думаешь, ты $gпервый:первая:? Сколько же еще мы должны потерять солдат прежде, чем Штормград начнет шевелиться?$B$BМы собрали целую кучу разведданных касательно угрозы со стороны клана Черной горы до того, как потеряли нашего командира, маршала Виндзора. С ним пропала и вся наша бесценная прнформация.$B$BНам просто необходимы эти документы. Поговори с Джоном-Оборванцем, $N. Он был при Виндзоре, когда на них налетел рейд клана Черной горы. Последний раз его видели в пещере к северую отсюда.', 'Поговорите с Джоном-Оборванцем.', 'Я мог бы тебя предупредить, но разве это интересно?', 'Ты уже поговорил с Джоном?', NULL, NULL, 'История Джона-Оборванца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4241, 'Маршал Винздор', 'Значит, этот жалкий трус говорит, что Виндзор жив?$B$BГотовься, тебе предстоит отправиться на его поиски. Если Виндзор жив, спаси его. Если мертв – принеси мне доказательства его гибели.$B$B*Максвелл смеется.*$B$BТебе, наверное, надоело это слышать?', 'Отправляйтесь на Черную гору на северо-западе и войдите в Глубины Черной горы. Узнайте, что сталось с маршалом Виндзором.Кажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу.', 'Где он! Я убью его!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4242, 'Утраченная надежда', 'Болвар – жалкий дурак. Я собирал все его драгоценные \"доказательства\" только для того, чтобы засунуть их ему же в глотку.$B$BНедоумок! Слепой идиот! Доказательство стоит в двух шагах от него, а он ушами хлопает.$B$BЧто касается собранных мною сведений – вся информация утрачена, причем безвозвратно.$B$BЕсли я все-таки найду Железогубитель и выберусь из этого лабиринта, я первым делом отправлюсь в Штормград и вломлю ему молотом промеж глаз, этому подлому змею.$B$BОставь меня, $N.', 'Сообщите маршалу Максвеллу плохие новости. Его можно найти на Дозоре Моргана, что в Пылающих степях.', 'Вполне очевидно, что он повредился рассудком.$B$B*Максвелл скорбно склоняет голову.*$B$BПечально, когда благородный и доблестный воин превращается в невменяемого идиота. Как я понимаю, мы зашли в тупик...$B$BНо ты хорошо потрудился, $N. И получишь награду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4243, 'В поисках Чи-Та 3', 'Увы, что-то случилось с одним из моих величайших изобретений. Ты ведь $gвидел:видела: моих механических белок? Так вот, чтобы подобраться поближе к обезьянам, обитающим в кратере Ун\'Горо, я создала механическую обезьяну, которая должна была смешаться со стаей. Я назвала ее Чи-Та 3. Ее глаза были сделаны из магических кристаллов, так что я могла видеть все, что видит она. Она успела добраться до Пещеры лишайников – это логово обезьян к востоку отсюда – и там я потеряла с ней контакт. Последним, что я видела, был вожак стаи, который подбежал поздороваться с ней. $B$BТы поможешь мне разыскать ее?', 'Найдите Чи-Та 3 в Кратере Ун\'Горо.', 'Осмотрев Чи-Та 3, вы обнаруживаете две глубоких вмятины в творении инженерного искусства Карны. Одна вмятина украшает плечо робота, другая зияет на голове. $B$BПохоже, энергии в машине не осталось.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4244, 'В поисках Чи-Та 3', 'Внимательно осмотрев робота, вы замечаете отодвигающуюся панель, над которой значится: \"Заменить мифриловую обшивку, затем выключить и включить питание\". $B$B\"Сомнительно, что такую серьезную поломку можно устранить так легко... $B$BНе попробуешь – не узнаешь.', 'Найдите мифриловую обшивку и вернитесь к Чи-Та 3 в Кратер Ун\'Горо. ', 'Вы снова отдвигаете панель на спине Чи-Та 3 и осторожно вынимаете обгоревшую мифриловую обшивку, заменяя ее новой. Если действительно считать, что это и была основная причина поломки, то осталось лишь включить питание.', 'Панель, в которую необходимо вставить мифриловую обшивку, все еще закрыта. Чи-Та 3 лежит неподвижно.', NULL, NULL, 'Мифриловая обшивка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4245, 'В поисках Чи-Та 3', 'Установив тумблер в положение \"выкл.\", вы оглядываетесь, чтобы удостовериться, что все готово к тому, чтобы доставить Чи-Та 3 назад к Карне Сомнамбулер. Убедившись, что горилл поблизости нет, вы собираетесь включить робота. $B$BЭто ваш последний шанс. Вы уверены, что хотите сделать именно это?', 'Доставьте Чи-Та 3 назад Карне Сомнамбулер в Кратер Ун\'Горо.', 'Ах, тебе удалось, какое счастье! Спасибо, $N! $B$BО, моя бедняжечка! Как тебе досталось! Ничего, я починю тебя, будешь как новенькая! $B$BЕще раз благодарю тебя, $N, твоя помощь неоценима.', NULL, NULL, NULL, 'Защищать Чи-Та 3, пока она не будет доставлена Карне Сомнамбулер.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4261, 'Древний дух', 'Оскверненный лес был некогда местом мирным и безмятежным... Пока сюда не пришел Легион. Эти инферналы, разрушения, хаос...$B$BЧереп Гул\'дана сделал так, что ничто не смогло уберечься от порчи. $B$BДаже сейчас, будучи духом, я ощущаю себя в ловушке, ощущаю страдания этого края. Помоги мне найти путь домой. Прошу тебя, $N, пообещай, что ты уведешь древний дух отсюда, туда, где я, наконец, обрету покой.$B$BКак только я освобожусь, найди Кайнета Штиля, друда, что живет в Лесной Песне, к востоку отсюда.', 'Сопроводите Арая в безопасное место, затем поговорите с Кайнетом Штилем в Лесной Песне на востоке Ясеневого леса.', 'Да, $N. Оскверненный лес пережил много горестей. Спасибо тебе за все.$B$BОднажды мы очистим Оскверненный лес от скверны, и каждое доброе дело приближает этот миг.', NULL, NULL, NULL, 'Сопроводите Арая в безопасное место.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4262, 'Подчинитель Пирон', 'Последние пять магов, которые отправились на разведку к Черной горе вернулись довольно хрустящими и с перманентной завивкой – или хуже того.$B$B*Джалинда берет с земли щепотку пепла и пускает по ветру.*$B$BА больше всего неприятностей нам причиняет один тип, подчинитель Пирон. Необходимо остановить этого элементаля, чтобы наша экспедиция могла пробраться в глубины Черной горы.$B$BОн охраняет вход в каменоломни Черной горы.', 'Убейте подчинителя Пирона.Кажется, Джалинда говорила, что Пирон охраняет каменоломню. Может, поискать его там?', 'Опалитель? О, небо…', NULL, NULL, NULL, 'Подчинитель Пирон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4263, 'Опалитель!', 'Ты $gуверен:уверена:, что Пирон сказал перед смертью \"Опалитель\"?$B$B*Джалинда судорожно сглатывает.*$B$BВедь лорд Опалитель – прислужник Рагнароса! О небо, небо... Что же нам делать?$B$BКак ты думаешь, справишься с еще одним заданием? Мне больше некого послать, $N!$B$BНам никогда не одолеть врагов, если Опалитель будет и дальше воскрешать Пирона из пепла.$B$BТебе придется отыскать и уничтожить лорда Опалителя!', 'Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!', 'О небо! Ты уверен, что Опалитель сказал перед смертью \"Рагнарос\"?*Джалинда протягивает вам что-то и морщит лоб в раздумье.*', NULL, NULL, NULL, 'Лорд Опалитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4264, 'Измятая записка', 'Лист помят и испачкан, и текст почти не читается, но вам все-таки удалось разобрать несколько фраз:$B$B\"...по иронии судьбы...$B$B...упадок распавшегося Альянса...$B$B...если бы не усердие генерала Кузни Гнева, мы никогда не сумели бы найти ключ к шифру...$B$B...Аргелмах почти завершил расшифровку записок Виндзора.$B$BНаш владыка восстанет из бездны и сокрушит всех, кто остался...$B$BИмператор Дагран Тауриссан\".', 'Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива.', '*Маршал Виндзор читает записку.*', '*Маршал Виндзор заметил смятый листок у вас в руке.*$B$BЧто это там у тебя, $N?', NULL, NULL, 'Измятая записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4265, 'Освобожденный из улья', 'Когда вы прикасаетесь к кокону, он немного раскрывается, и вы видите внутри ночного эльфа, который, как ни странно, все еще жив, и даже, кажется, цел и невредим, только в глубоком обмороке. Когда вы вытаскиваете его из кокона, он шевелится и приходит в себя.$B$B\"Слава Элуне! Я спасен! Спасибо тебе, друг. Я... Меня зовут Раскал. Эти жуки парализовали меня, и очнулся я уже в коконе. Тебя из крепости прислали, да?\"$B$BПохоже, вы нашли пропавшего курьера...', 'Освободите Раскала из улья Зукк\'аш.Вернитесь к Гинро Пылающему Очагу в Крепости Оперенной Луны и сообщите ему, что Раскал жив и здоров.', 'С возвращением, $N! Раскал не так давно явился ко мне и сообщил обо всем, что произошло.$B$BЯ... да что там, вся наша крепость не знает, как тебя благодарить за твои подвиги. Раскал погиб бы, если бы не твоя своевременная помощь. А ведь ты помогаешь нам не ради платы, как какой-нибудь наемник! Ты – подлинный герой. Знай, что отныне Гинро Пылающий Очаг – твой друг до скончания веков!', NULL, NULL, NULL, 'Освободите Раскала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4266, 'Благодарность за отвагу', '$N, генерал Шандриса Оперенная Луна хотела бы поговорить с тобой лично. Несомненно, она хочет поблагодарить тебя за все, что ты $gсделал:сделала: для крепости, но, насколько я знаю, она также хотела бы поговорить с тобой о тех насекомоподобных тварях, которых вы с Раскалом видели в южном Фераласе. Сообщения об этих насекомых, которых именуют Зукк\'аш, звучат... скажем так: устрашающе.$B$BГенерал Оперенная Луна ждет тебя в главном здании.', 'Поговорите с Шандрисой Оперенной Луной в Крепости Оперенной Луны.', '$N, я от души благодарю тебя за всю оказанную тобой помощь. Твоя отвага перед лицом превосходящих сил противника достойна награды в тысячу раз большей. Тем не менее, я надеюсь, что ты примешь в дар от всей крепости хотя бы это.$B$BА теперь, если можно... я хотела бы попросить тебя еще об одной услуге. Сейчас, когда здесь, в Фераласе, обнаружен улей Цуккаш, думаю, это задание следует поручить именно тебе...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4267, 'Возвышение силитидов', 'Я доверяю тебе копию отчета Раскала о вторжении в юго-восточный Фералас. Полный доклад будет отправлен на хранение в Дарнас, а эту копию отнеси, пожалуйста, представителю Протектората. Ее зовут Грацина Сила Духа; это жрица, которая живет в храме Луны в Дарнасе. Она обладает обширными познаниями о подобных существах, так что, если она ознакомится с этим докладом, это пойдет на пользу всем нам.$B$BМожешь идти, $N. Удачи тебе, и да хранит нас Элуна!', 'Отнесите донесение Раскала Грацине Силе Духа в Дарнасе.', 'Нам, ночным эльфам, немало известно об ужасах, описанных в этом докладе. Сандрис поступила мудро, отправив ко мне доклад – и тебя с ним.$B$BЭти твари стремительно заполонят весь Фералас. Можно сказать, что это одна из самых страшных опасностей, какие нам когда-либо грозили! Насекомые, с которыми столкнулись вы с курьером, называются силитидами. Они – всего лишь орудие одной из величайших угроз, с какими встречались как Альянс, так и Орда.$B$BМолюсь, чтобы у нас хватило решимости разгромить их прежде, чем они уничтожат нас!', 'Добро пожаловать в наш благословенный храм! Я узнала о твоем приходе из предсказания. Тот доклад, что просила тебя отнести Шандрисе Оперенной Луне, у тебя с собой?', NULL, NULL, 'Донесение Раскала (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4281, 'Посылка в Таланаар', 'Сверток, который вы нашли в лагере гноллов-древолапов, следовало доставить в небольшой путевой лагерь Таланаар на юго-востоке Фераласа. Неизвестно, какая судьба постигла курьера, однако сверток так и остался недоставленным!$B$BОсмотрев пакет, вы видите на нем имя \"Хранитель дорог Фалфиндер\". Возможно, это имя адресата?', 'Отнесите недоставленную посылку Хранителю дорог Фалфиндеру в Таланаар.', 'Слава Элуне! Наконец-то пришла посылка из Крепости Оперенной Луны!$B$BНо раз ее принес ты, значит, с нашим курьером, Раскалом, что-то случилось? Надеюсь, что все уладится... Насколько я знаю, в последнее время гноллы из клана Древолапов очень боятся чего-то, что происходит на юге. Может быть, Раскал заблудился в глуши? Будь осторожнее.$B$BНу, как бы то ни было, спасибо тебе еще раз. А вот и плата за доставку!', 'Добро пожаловать в Таланаар, $C. Тебе нужна какая-нибудь помощь?', NULL, NULL, 'Недоставленная посылка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4282, 'Проблеск надежды', '<Маршал Виндзор возбужденно потрясает запиской.>$B$BТы понимаешь, что это значит, $N?$B$BМожет быть, еще не все потеряно! Насколько я понял, информацией завладели два дворфа Черного Железа – генерал Кузня Гнева и повелитель големов Аргелмах. Однако есть у меня подозрение, что они ее не отдадут, даже если мы их очень вежливо попросим.$B$BНадеюсь, ты $gготов:готова: сражаться.$B$BРазыщи этих двоих негодяев! Убей их обоих и верни мне утерянную информацию.', 'Верните маршалу Виндзору утерянную информацию.Маршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева.', '*Маршал Виндзор выхватывает у вас из рук таблички.*$B$BУходим!', 'Уже очень скоро все это закончится.', NULL, NULL, 'Утерянная информация маршала Виндзора', 'Утерянная информация маршала Виндзора', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4283, 'ПЯТЬДЕСЯТ! АГА!', 'Открою тебе тайну, солдат. Подойди-ка поближе.$B$BЯ ЕДИНСТВЕННЫЙ, КТО ЕЩЕ НЕ СПЯТИЛ!$B$BПосмотри на остальных. Ты веришь, что они ненормальные? А так оно и есть! ПСИХИ! СУМАСШЕДШИЕ!$B$B*Орелиус понижает голос.*$B$BНо пусть это останется между нами – тобой, мной и моим приятелем, капитаном Винки.$B$B*Орелиус хватается за воздух и будто прижимает кого-то к себе.*$B$BВ общееем... помимо ушей огров, я собираю их содатские медальоны. Сегодня на повестке дня орки. Пятьдесят штук. ИДИ!$B$B*Орелиус трубит в рог.*$B$BЗАТКНИСЬ!', 'Найдите 50 медальонов Черной горы.', 'Ты справился! И вот твоя награда: ПОЧЕШИ МНЕ ЖИВОТИК! ДАВАЙ! ЧЕШИ!', '*Орелиус говорит в довольно большое отрезанное ухо огра.*$B$BПылающие степи – центру. Центр, прием.', NULL, NULL, 'Медальон Черной горы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4284, 'Кристаллы силы', 'Уверена, ты $gвидел:видела: их, $N. Они повсюду! $B$BТы не понимаешь, о чем я? О кристаллах, конечно! Большинство их просто игнорирует, но я чувствую, что в них заключена какая-то сила. Я уже давно провожу с ними эксперименты, но пока, видимо, так же далека от разгадки, как и в первые дни исследований... Впрочем, я не теряю надежды! $B$BСейчас у меня почти вышел запас кристаллов. Не поможешь ли мне его восполнить?', 'Соберите по 7 кристаллов силы каждого цвета: красных, синих, желтых и зеленых. Принесите их Джей Ди Колли в Укрытие Маршалла.', 'Теперь я продолжу эксперименты. Спасибо, $N!', 'Я чувствую, что близка к разгадке, $N!', NULL, NULL, 'Красный кристалл силы', 'Желтый кристалл силы', 'Зеленый кристалл силы', 'Синий кристалл силы');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4285, 'Северный пилон', 'Что бы это могло быть? Я все время думаю об этой загадке! $B$BЭти слухи о хрустальных пилонах просто сводят меня с ума! Можешь считать меня наивной дурочкой, но я верю почти всему, что мне рассказывают. $B$BВ общем, слыхала я, что один из пилонов находится совсем неподалеку отсюда – где-то на севере. Пожалуйста, разыщи его, $N! Я уверена, пилоны существуют!', 'Отыщите Северный хрустальный пилон в Кратере Ун\'Горо.', 'Я знаю, что все эти рассказы – правда, $N.', NULL, NULL, NULL, 'Отыскать и исследовать Северный хрустальный пилон.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4286, 'Хороший товар', 'Капитан Винки уверяет, что дворфы Черного Железа в глубинах Черной Скалы загребли все лучшее добро. Верно, Винки?$B$B*Орелиус, как может, изображает пирата.*$B$BВот видишь? Иди туда и принеси мне образцы их добра.$B$BТряхни стариной и отправляйся вглубь!', 'Добудьте 20 поясных сумок дворфов Черного Железа.', '*Орелиус роется в груде поясных сумок.*$B$BВЕЛИКОЛЕПНО!$B$B*Орелиус сует нос в кучу и принюхивается.*$B$BВОСХИТИТЕЛЬНО! Только посмотри на это добро!$B$BВозьми одну себе, здесь их полно.', 'Не беспокой меня, Эст. Нам с Винкей надо кое с кем встретиться.', NULL, NULL, 'Поясная сумка дворфов Черного Железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4287, 'Восточный пилон', 'За время моего пребывания здесь, до меня не раз доходили странные слухи о таинственных хрустальных пилонах, сокрытых в кратере. Полагаю, они довольно велики. $B$BНе могу отделаться от мысли, что в этих слухах есть доля истины, и эти пилоны как-то связаны с обнаруженными нами кристаллами... $B$BУдовлетвори мое любопытство, поищи пилон в восточной области кратера.', 'Отыщите Восточный хрустальный пилон в Кратере Ун\'Горо.', 'Ун\'Горо такое странное место, $N! Входишь – и будто оказываешься в другом мире!', NULL, NULL, NULL, 'Найти и исследовать Восточный хрустальный пилон', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4288, 'Западный пилон', 'Мои опыты пока не принесли никаких положительных результатов, $N. Теперь я возлагаю надежды лишь на то, что ты сможешь найти один из пилонов, о существовании которых я слыхала. $B$BВозможно, если смешать определенные цвета... Впрочем, я тороплю события. Необходимо сначала найти его. $B$BИсследуй западную область кратера, $N, говорят, пилон находится именно там.', 'Отыщите Западный хрустальный пилон.', 'В стенах кратера много ниш и пещер. Попробуй обыскать извилистые тропинки в тех местах, если больше ничего не можешь придумать.', NULL, NULL, NULL, 'Найти и исследовать Западный хрустальный пилон', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4289, 'Обезьяны Ун\'Горо', 'В этом кратере встречается множество странных зверей – они похожи на тех, что водятся на моей родине, но выглядят более... породистыми. Я не могу объяснить это, но мне кажется, это место – средоточие силы Матери-Природы. Я воздаю ей хвалу всякий раз, как встречаю одно из ее прекрасных созданий в этом кратере. $B$BЕсли ты тоже хочешь достигнуть просветления, отправляйся на север. Там ты найдешь огромных обезьян, помериться силами с которыми сочтет за честь самый искусный воин. Принеси мне их шкуры, докажи свою силу!', 'Принесите 2 шкуры Ун\'Горской гориллы, 2 шкуры Ун\'Горского топтуна и 2 шкуры Ун\'Горского рокотуна землепроходцу Торве к входу в Кратер Ун\'Горо.', 'Значит, тебе хватило сил одолеть обезьян Ун\'Горо. Это славно. Конечно, это не такая сложная задача, как сражение с Лар\'корви, и все же немалая победа. $B$BМое племя обрадуется шкурам, из них получатся прекрасные одежды! Ты помог мне и показал себя достойным. $B$BПрежде чем ты отправишься далее, воздадим хвалу Матери-Земле и поблагодарим духов обезьян, убитых тобой – они должны знать, что их смерть была не напрасна!', 'Что, неужели сдался, $N? $B$BНе падай духом. Выследить и сразить обезьяну Ун\'Горо – не простая задача, даже для великого охотника.', NULL, NULL, 'Шкура ун\'горской гориллы', 'Шкура ун\'горского топотуна', 'Шкура ун\'горского рокотуна', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4290, 'Добыча Лар\'корви', 'Однажды мой брат имел неосторожность отрезать кусок мяса от добычи Лар\'корви, когда того не было рядом. Однако оказалось, что Лар\'корви наблюдал за моим братом из укрытия. Он преследовал моего брата долгие недели, разрушая все на своем пути. Наконец, брат мой в страхе решил покинуть кратер. $B$BНо Лар\'корви настиг его недалеко от этого места и убил его. $B$BЕсли хочешь привлечь к себе внимание Лар\'корви, найди его свежеубитую добычу и отрежь от нее кусок мяса. $B$BЗатем возвращайся ко мне.', 'Найдите последнюю добычу Лар\'корви, украдите кусок трупа жесткозуба и вернитесь к землепроходцу Торве в Кратер Ун\'Горо.', 'Этот кусок послужит хорошей приманкой, $N. Похоже, удача в охоте сопутствует Лар\'корви. Однако странно, где он смог найти жесткозуба в этих краях... $B$BЯ сохраню это для тебя до тех пор, пока ты не будешь готов встретиться с чудовищем. Не волнуйся за меня – полагаю, ты уже успел так разозлить Лар\'корви, что он не станет убивать меня раньше, чем вкусит твоей плоти.', 'Не относись к этому заданию легкомысленно, $N. Если ты и вправду желаешь встретиться с чудовищем, ты должен быть очень осторожен и рассудителен. Необходима немалая сила и сноровка, чтобы победить Лар\'корви.', NULL, NULL, 'Часть трупа жесткозуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4291, 'Запах Лар\'корви', 'Я удивлен, что Лар\'корви не вышел к тебе, $N! И все же у меня есть задумка, как выманить его. $B$BПоскольку Лар\'корви – доминирующий самец в своей стае, он может выбирать любую самку. А выбирает он многих! Ты найдешь много кладок равазавров к западу отсюда. Подберись к ним поближе и спровоцируй самок атаковать тебя. В их головах находятся железы, источающие жуткий запах – так эти твари оповещают своих самцов о готовности к размножению. Принеси мне две такие железы.', 'Принесите 2 феромонные железы равазавра землепроходцу Торве в преддверие Кратера Ун\'Горо.', 'Это отличные образцы, $N. С их помощью мы сможем выманить Лар\'корви. Мне не терпится узнать, чем закончится твой бой с чудовищем. Это огромная тварь с зубами, подобными булатным клинкам. Ты посмотришь в его глаза и познаешь, каков взгляд смерти.', 'Будь осторожен$N. Когда подберешься близко к яйцам, самки ринутся защищать их. Они могут быть не менее опасны, чем сам Лар\'корви, если почувствуют угрозу своему потомству. Но если тебе удастся добыть железы, мы точно сможем выманить Лар\'корви из его логова.', NULL, NULL, 'Половая железа равазавра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4292, 'Приманка для Лар\'корви', 'Это самая сложная часть нашего плана. К северу отсюда есть узкая тропинка, ведущая в горы. Именно там я в последний раз видел Лар\'корви. Ты легко узнаешь это место – там повсюду разбросаны дочиста обглоданные кости крупных животных, имевших неосторожность подойти слишком близко к логову Лар\'корви. Положишь там принесенное с собой мясо. Затем полей мясо вот этим составом. Если это не выманит к тебе Лар\'корви, то я не знаю, чем еще его можно заманить.', 'С помощью предметов из мешочка Торвы выманите Лар\'корви и сразите его. Принесите голову Лар\'корви землепроходцу Торве ко входу в Кратер Ун\'Горо.', 'Хвала Матери-Земле! Ты справился!Ты показал себя великим, $N. Твой дух силен. Твоей храбрости нет равных. А сила твоя укрепилась. Я склоняюсь пред твоим мастерством. $B$BТолько самым великим из моих предков были под силу подобные свершения.', 'Не дай своему страху побороть тебя, $N! Страх – великий предатель, с ним нужно бороться. $B$BВозьми это мясо и потри его железой самки чудовища. И тогда сама смерть предстанет перед тобой.', NULL, NULL, 'Голова Лар\'корви', 'Мешочек Торвы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4293, 'Проба слизи...', 'Оскверненный лес находится далеко на севере от Степей – даже дальше, чем Ясеневый лес. Вокруг тамошних заводей, благословленных касанием Скверны, полно слизнюков. Плеть наводнила эти земли инферналами и прочими демонами. Судя по всему, в это время слизнюки и полезли из-под земли.$B$BСобери образцы слизнюков Оскверненного леса – мы проверим их при помощи моего оборудования и создадим контрольную группу, чтобы сопоставить ее с другими принесенными тобой образцами.', 'Возьмите на пробу образцы слизи из Оскверненного леса. Воспользуйтесь тестовым оборудованием химика Барабоса в Подгороде, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему.', 'Великолепно. Эти пробы прекрасно подойдут. Благодарю за помощь.$B$BСобрав все образцы слизи, мы сможем двинуться дальше. Я начинаю подозревать, что леди Сильвана не зря заинтересовалась этими существами. Более того, сама того не зная, она, похоже, оказалась на грани великого открытия. Эти пробы очень интересны. А как они прореагировали с моими препаратами... хм, да, нам есть над чем поработать.', 'Мне нужно не меньше пяти проб слизи для контрольной группы. Продолжай собирать образцы слизи, пока не предоставишь мне все необходимое. Так велела леди Сильвана...', NULL, NULL, 'Проба порчи из Оскверненного леса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4294, '...и образцы слизнюков', 'Тебе приходилось слышать о Кратере Ун\'Горо? Он расположен рядом с пустыней Танарис. Великолепное место: тамошние буйные заросли буквально кишат жизнью! А какие там растения…$B$BИменно туда тебе и следует отправиться. До меня дошли слухи, что в этих местах сохранилась практически девственная природа. Исследователи лишь недавно добрались до них, и далеко не все тайны еще раскрыты.$B$BЯ хочу, чтобы ты $gпринес:принесла: мне образцы живущих там слизнюков. Если слухи правдивы и их не тронула порча, я смогу узнать, откуда появились эти существа.', 'Возьмите на пробу образцы слизи из Кратера Ун\'Горо. Воспользуйтесь тестовым оборудованием химика Барабоса в Катакомбах, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему.', 'Удивительно! Кратер Ун\'Горо таит куда больше секретов, чем я думал. Интересно, какие еще открытия нас ждут?$B$BПоразительно... Изумительно чистые образцы. Хм, что бы это значило? Похоже, по природе они относятся скорее к стихиям... но непростым. Они напоминают мне... о Древних богах. Мы находили их следы по всему Азероту – вдруг и эти существа каким-то образом связаны с ними?$B$BНадо продолжать исследования.', 'Да, $N? Как успехи?', NULL, NULL, 'Чистая проба из Ун\'Горо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4295, 'Эль для Каменного Узла', '', '', 'Это что? Ага! Пахнет элем Черного Железа! Пусть я пьян и мало что соображаю, но скажу тебе, добрый сэр: ты настоящий друг!', NULL, NULL, NULL, 'Кружка эля Черного Железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4296, 'Табличка Семерых', 'Я прибыл в Пылающие степи из-за легенд о Семерых. Это были дворфы, прославленные знаниями и силой, а значит – и богатством.$B$BИменно к богатству я и стремлюсь!$B$BУзнай мы побольше про Семерых, могли бы оба разбогатеть. Говорят, что в руинах Тауриссана есть табличка Семерых, содержащая знания древних дворфов. Найди ее, перепиши текст и принеси мне. И мы оба узнаем ее тайны!', 'Перепишите текст с таблички Семерых.', 'А, ты нашел табличку! И как хорошо переписан текст! Ты точно $C, а не переписчик?$B$BВот, возьми, $N. Это обещанные деньги.', 'Удалось переписать мудрость Семерых? Раскрыла ли табличка их тайны?', NULL, NULL, 'Переписанный с таблички текст', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4297, 'Покормить малыша', 'Летучие хамелеоны всеядны: это значит, что они питаются как животной, так и растительной пищей. Твое яйцо вот-вот проклюнется, и мы должны быть к этому готовы. Лучшая еда для этих малявок – это мясо, свежее, сочное мясо! Хочешь – верь, хочешь – нет. Почему – я так и не выяснил, но, кажется, это имеет какое-то отношение к замыслу Элуны относительно эльфов. Возможно, они должны были быть защитниками... не знаю.$B$BЯйцо я пока покараулю, а ты сходи и добудь мне свеженьких окороков среброгривых бродяг. Ими-то мы и покормим малыша, когда он вылупится.', 'Принесите 5 окороков среброгривого бродяги Агнару Зверопасу во Внутренних землях.', 'Да, это мясо вполне годится. А тем временем, если я не ошибаюсь, твой дракончик начинает вылупляться! Ну, как тебе это? В смысле, каково быть папой? Груз ответственности не давит пока?', 'Ну что, $N, добыл ли ты мясо? А то твой дракончик вот-вот вылупится. И если он не поест как следует, едва появившись на свет, он и недели не проживет, а это будет жаль.$B$BПо правде говоря, $N, мне вообще жаль отдавать тебе это яйцо. Так не заставляй меня жалеть об этом еще больше!', NULL, NULL, 'Окорок среброгривого бродяги', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4298, 'У вас появился малыш!', 'Ух ты, да он уже вылупляется!', 'Поговорите с Агнаром Зверопасом во Внутренних землях.', 'Вот, бери яйцо... Тебе лучше держать его при себе, чтобы вылупившийся детеныш сразу привязался к тебе. Тогда он будет считать тебя своим папочкой.$B$BНу все, $N, поздравляю! У тебя теперь все равно что собственный ребенок!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4300, 'Костяные клинки', 'Да, если так подумать, то, пожалуй, для тебя есть работенка. Джес\'римону пригодится твоя помощь.$B$BВ Кратере Ун\'Горо водятся ящеры – с когтями острыми, как бритва. У большинства ящеров когти черные, как смерть, но у некоторых ящеров они белые. У Раздробленной Руки имеются... клиенты, которые очень ценят оружие, изготовленное из таких когтей. Принеси побольше белых когтей, и Джес\'римон заплатит тебе по совести. А если сделаешь это быстро, то получишь кое-что сверху.', 'Принесите 8 белых когтей равазавра Джес\'римону в Оргриммаре.', 'Да, это то, что надо! Спасибо, $N. И тебе удалось уложиться в срок... это замечательно.$B$BБыть может, мы сумеем изготовить из этих когтей оружие и для тебя. Что скажешь?', 'Клиенты недовольны, $N. Где же обещанные когти?', NULL, NULL, 'Белый коготь равазавра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4301, 'Могучая Уча', 'Пока ты $gисследовал:исследовала: Ун\'Горо, я встретил и других созданий, охота на которых доставит удовольствие такому мастеру как ты. Одно из них – огромная обезьяна, я видел ее в стае других обезьян к северу отсюда. Ты уже $gбывал:бывала: в этой пещере раньше, однако не могу ручаться, что выйдешь из этой схватки $gживым:живой:, если действительно возьмешься за это задание. $B$BЯ назвал эту обезьяну Уча, она одна из самых могучих детей Матери-Природы. Убей ее, и я буду отстаивать твое право называть себя $gвеликим охотником:великой охотницей:.', 'Принесите шкуру Учи землепроходцу Торве ко входу в Кратер Ун\'Горо.', 'Отлично, $N! Я доволен. Сегодня ты совершил великое деяние. $B$BУча была одной из самых огромных обезьян, виденных мною за всю жизнь. То, что ты смог сразить ее, говорит о твоей собственной силе и храбрости. $B$BПрими это в знак моего уважения. Ты заслужил это.', 'Уча... Это был великолепный зверь. Она была огромной и рыжей, а зубы ее были подобны кинжалам. Ее руки толщиной спорили со стволами деревьев, а двигалась она так быстро, что ей позавидовал бы и горный лев! Тебе повезло встретить столь мощное создание для испытания своей храбрости – многим поколениям в моем племени не посчастливилось повстречать ничего подобного.', NULL, NULL, 'Шкура Учи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4321, 'Давай-ка разберемся', 'То, что ты $gрассказал:рассказала: мне о пилонах, весьма интересно... $B$BДай мне минутку, мне нужно сделать некоторые расчеты... Зайди ко мне через пару минут, я смогу дать ответ на твой вопрос.', 'Поговорите с Джей Ди Колли через пару минут.', 'Так вот, $N! Все это очень интересно... Надюсь, мои диаграммы верны! Я собрала все сведения в эту книгу и отдам ее тебе. $B$BПолагаю, теперь я могу ответить на все твои вопросы о кристаллах, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4322, 'Побег!', 'Пора выбираться отсюда, $N. Помоги мне забрать мои вещи со склада и освободить моих друзей. Если у нас все получится и нам удастся отсюда сбежать, отправляйся в Дозор Моргана и расскажи обо всем маршалу Максвеллу. Он тебе скажет, что делать дальше.', 'Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции.', 'Поразительно, $N. Просто невероятно. Виндзор был здесь буквально перед твоим приходом. Ворвался, как ураган, весь такой разгоряченный и буйный. Его притязания поистине грандиозны, но он заявляет, что у него есть на то основания. Сейчас он направляется в Штормград и собирается бросить вызов Болвару и... госпоже Престор.', NULL, NULL, NULL, 'Побег!', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4324, 'Юка Крутипроб', 'Риббли, мой младший братец, всю жизнь был никчемным придурком и позором для всей семьи, но в итоге оказалось, что он тоже чего-то да стоит и может пригодиться. Но понимаешь, какое дело... чтобы приставить его к работе, нам понадобится твоя помощь.$B$BМоя сестра Юка искала его почти месяц, и в итоге ей удалось узнать, что он прячется в Пылающих степях. Ей нужен наемник, и она обратилась ко мне за помощью.$B$BНе хочешь взяться за это дело? Если берешься, тогда тебе надо переговорить с сестрой. Ты найдешь ее в Пламенеющем Стяге, в пещере к северо-западу от скалы Молота Ужаса.', 'Переговорите с Юкой Крутипроб в Пылающих степях.', 'Да, я ищу брата. Его надо найти и вернуть.$B$BПриведи его ко мне. А если он будет сопротивляться... тогда принеси мне хотя бы его голову.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4341, 'Каран Могучий Молот', 'Тебе приходилось бывать в дымящихся руинах Тауриссана? А тебе не попадался этот жалкий бездельник Каран Могучий Молот? Это дворф, который был должен охранять мою девочку!$B$B<Король всхлипывает.>$B$BИ теперь она пропала, $N!$B$BМои воины обшарили всю Степь. Им удалось узнать только то, что моя дочка может быть в Глубинах. Может, она уже погибла!$B$BА Харан, видимо, сидит там в плену... найди его! Я хочу получить ответ!', 'Пойдите в Глубины Черной горы и найдите Карана Могучего Молота.Король упомянул, что Каран сидит там в плену – может, стоит поискать темницу.', 'Прошу, позволь мне объясниться!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4342, 'Рассказ Карана', 'Пожалуйста, выслушай меня, а потом будешь судить!', 'Выслушайте рассказ Карана Могучего Молота.', 'Как ты сам понимаешь, я ничего не мог сделать.', 'Дай мне закончить рассказ.', NULL, NULL, 'Рассказ Карана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4343, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4361, 'Недобрые вести', 'Расскажи обо всем королю Магни, $N. Он знает, что делать.', 'Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду.', '*Король Магни в ярости бьет кулаком по столу.*', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4362, 'Судьба королевства', 'Похоже, и моя судьба, и судьба королевства Стальгорн ныне в руках моего старинного врага Даграна Тауриссана.$B$BВозможно, вы моя последняя надежда, $N. Вы должны спасти мою драгоценную дочь Мойру!$B$BЕсть только один путь наверняка разрушить лежащее на Мойре заклятие Тауриссана – убить его.$B$BНо умоляю, $N, не причиняйте ей вреда! Помните, она под властью Тауриссана! Все, что она будет делать или говорить, – результат злого заклятия Тауриссана!', 'Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана.', '*Принцесса оплакивает гибель императора Даграна Тауриссана.*$B$BЗа что???', NULL, NULL, NULL, 'Император Дагран Тауриссан убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4363, 'Королевский сюрприз', 'Тауриссан был великим и доблестным дворфом. Ты $gразрушил:разрушила: мою жизнь и жизнь моего будущего ребенка!$B$B<Вы уверены, что принцесса до сих пор пребывает под действием чар императора.>$B$BВозвращайся в Стальгорн и скажи моему отцу, что наследником королевства будет дворф из клана Черного Железа.$B$BНравится это ему или нет, но именно так все и будет!', 'Вернитесь в Стальгорн и переговорите с королем Магни Бронзобородом.', '*Король Магни Бронзобород явно расстроен.*$B$BСдается мне, даже в смерти Тауриссан победил.$B$BБольше я не нуждаюсь в твоих услугах, Тыж. Но прежде чем ты покинешь нас, выбери себе награду из королевских сокровищниц.$B$B*Король садится на трон и погружается в раздумья.*', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4381, 'Кристалл восстановления', '', '', 'Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. $B$BТеперь полученное сочетание – ваше.', NULL, NULL, NULL, 'Желтый кристалл силы', 'Зеленый кристалл силы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4382, 'Кристалл силы духа', '', '', 'Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. $B$BТеперь полученное сочетание – ваше.', NULL, NULL, NULL, 'Зеленый кристалл силы', 'Синий кристалл силы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4383, 'Кристалл-хранитель', '', '', 'Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. $B$BТеперь полученное сочетание – ваше.', NULL, NULL, NULL, 'Красный кристалл силы', 'Зеленый кристалл силы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4384, 'Хрустальный удар', '', '', 'Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. $B$BТеперь полученное сочетание – ваше.', NULL, NULL, NULL, 'Красный кристалл силы', 'Синий кристалл силы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4385, 'Хрустальный заряд', '', '', 'Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. $B$BТеперь полученное сочетание – ваше.', NULL, NULL, NULL, 'Красный кристалл силы', 'Желтый кристалл силы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4386, 'Хрустальная спираль', '', '', 'Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. $B$BТеперь полученное сочетание – ваше.', NULL, NULL, NULL, 'Синий кристалл силы', 'Желтый кристалл силы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4401, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4402, 'Кактусовый десерт Галгара', 'Ну и жарища у нас в долине!$B$B*Галгар утирает пот со лба.*$B$BБыли бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт! Ничто не освежает лучше этого восхитительного лакомства.$B$BЗнаешь что, $N? Принеси-ка мне шесть плодов кактуса, и я изготовлю тебе несколько порций кактусового десерта. Они тебе пригодятся в путешествиях. Плоды кактуса можно собрать со здешних кактусов.', 'Принесите Галгару 6 плодов кактуса. Не забудьте, их можно найти возле кактусов.', 'Замечательно, $N! А вот и твой кактусовый десерт, как было обещано. И еще кое-что в придачу...', 'Ну что, собрал плоды?', NULL, NULL, 'Плод кактуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4403, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4421, 'Порча нефритового огня', 'Мало кто отваживается искать здесь приключений... Порча, поразившая Оскверненный лес, расползается, поражая все без разбору.$B$BЯ, состоя в Изумрудном Круге, ищу способ исцелить эти земли, но есть те, кто радуется ее мучениям.$B$BЯ говорю о сатирах из племени Нефритового Пламени, что живут к северо-западу отсюда, в руинах Констелласа. Ими предводительствует особенно жестокий сатир по имени Ксаватрас. Они продолжают поражать заразой любое живое существо, которое попадается им на пути.$B$BМы должны защитить этот край – ведь некогда он был нашим. Срази Ксаватраса и уничтожь его приспешников.', 'Убейте 11 скверноподданных, 9 тенеловов, 9 разбойников из племени Нефритового Пламени и Ксаватраса. Возвращайтесь к Эридане Грусти Ветра в Оскверненный лес по выполнении задания.', 'Избавление Оскверненного леса от Ксаватраса – только первый шаг на долгом пути. Придется долго трудиться, чтобы залечить раны этой земли.$B$BЯ чувствую, что за всем этим стоит нечто большее, чем какие-то сатиры, но правду мы узнаем только со временем...', NULL, NULL, NULL, 'Скверноподданный из племени Нефритового Пламени убито', 'Тенелов из племени Нефритового Пламени убито', 'Разбойник из племени Нефритового Пламени убито', 'Ксаватрас убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4441, 'Древа в узах скверны', 'Флейта, найденная тобой, вырезана из древесины сторожевого древа, верного союзника ночных эльфов.$B$BСатиры поражают порчей все, на что наталкиваются, в том числе и древа, для которых Оскверненный лес был домом родным. Из-за скверны духи древ попали в узы и теперь терзаются, не в силах освободиться. Эти узы скверны, что ты $gнашел:нашла:, наверняка с этим связаны.$B$BМы должны попытаться очистить эту флейту от скверны, $N. Принеси мне благословенной воды из дарнасского храма Луны.', 'Отправляйтесь в Дарнас и наберите в фиал Эриданы благословенной воды из храма Луны. Возвращайтесь к Эридане с полным фиалом.', 'Спасибо тебе, $N. Будем же молиться, чтобы нам удалось исцелить нанесенные раны...', 'Будем надеяться, что сия вода освободит духи Древ и подарит им мир.', NULL, NULL, 'Фиал благословенной воды', 'Фиал Эриданы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4442, 'Очищение явлено!', 'При помощи сей воды Элуны я попытаюсь смыть скверну с этой флейты. Мы должны покончить со страданиями...$B$BДа направит мою руку Элуна и да укрепит она мое сердце.$B$BПодожди немного – потом поговорим.', 'Через мгновение заговорите с Эриданой.', 'При помощи этой благословенной воды я сумела разорвать связь между флейтой и духами Дерев. Но я все же уверена, что если ты заиграешь на этой флейте в священном месте, то ты мог бы призвать духи Дерев.$B$BВозможно, тебе следует попытаться сделать это в руинах в южной части Железнолесья. Некогда там обитало много оскверненных древней, и, возможно, они и до сих пор там находятся, пусть и в обличье духов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4443, 'Оскверненный кнутокорень', '', '', 'Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
