INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4446, 'Оскверненный кнутокорень', '', '', 'Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4447, 'Оскверненный ночной дракон', '', '', 'Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4448, 'Оскверненный ночной дракон', '', '', 'Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4449, 'Попался!', 'Эй! Эй, ты, там! Иди скорей сюда! $B$BПомоги мне! Я спасался бегством от дворфов Черного Железа и попытался спрятаться от них здесь. Проклятые геологи со своей проклятой магией! Они увидели, что я здесь прячусь, и заперли меня здесь! Проучи, проучи этих проклятых геологов! И... это... добудь мне несколько лоскутков шелка... так... вдруг пригодится...', 'Убейте 8 геологов из клана Черного Железа и принесите 15 отрезов шелка тому, кто заперт в отхожем месте в Тлеющем ущелье.', 'О, какое облегчение! Как я рад, $N! Тебе удалось отомстить проклятым геологам? Их наглость не знала границ, однако. Не знаю как благодарить тебя! Ты это... погоди минутку, мне тут надо закончить некоторые дела...', 'Я тут уже целый день торчу! Достань мне шелку... э-э... в смысле... геологов! Пусть узнают, что такой мой... в смысле... твой гнев!', NULL, NULL, 'Геолог из клана Черного Железа убито', 'Шелковый материал', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4450, 'Учетная книга из Танариса', 'Ты знаешь, мне это кое-что напоминает.$B$BНе хочешь закончить за меня одну работенку, за которую я взялся в Танарисе? Это пара пустяков...$B$BКринкель Сталлинн из Прибамбасска искал какие-то вещи – некоторые здесь, в Тлеющем ущелье, а некоторые в других местах. Может, глянешь на список? Ты наверняка сможешь что-нибудь найти.$B$BЕсли тебе это интересно, я просуну его учетную книгу под дверь. Отнесешь ее ему вместе с разыскиваемыми вещами, когда соберешь их все.', 'Возьмите учетную книгу Кринкеля Сталлера и найдите все перечисленные в ней вещи. Затем отнесите их и книгу Кринкелю Сталлеру в Танарис.', 'Ого, да ты смог выполнить эту работу! Прекрасно. Полагаю, теперь ты попросишь меня выковать для тебя что-нибудь. $B$BУ меня есть превосходное оружие и доспехи. Благодарю тебя, $C! $B$BДумаю, ты заслужил... хммм... что-нибудь полезное.', 'Да-да? Чем я могу помочь тебе, $C? Я ужасно занят, у меня полно капризных клиентов, которым вынь да положь немедленно их заказ.Так что давай пошустрей со своими делами. Не хочу показаться грубым, но у меня совершенно нет времени на пустую болтовню!', NULL, NULL, 'Учетная книга Сталлина', 'Часть прочной хрустальной ноги', 'Задержанная посылка', 'Сбалансированная шпага Сталлина');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4451, 'Ключ к свободе', 'Маленький медный ключик выглядит совершенно непритязательно. Единственное, что выдает его значимость, – надпись, выгравированная на бородке: $B$B\"Служебные помещения Черного Железа – изготовление дубликатов строжайше запрещено\".$B$BУ вас нет ни малейшего представления, что это за ключ и куда ведет открываемая им дверь.', 'Найдите дверь в Тлеющем ущелье, к которой подходит ключ от дома Грязнули.', 'Вот те на! Чтоб мне провалиться! Ты нашел ключ! Я знал, что проклятые дворфы Черного Железа спрятали его, после того как заперли меня в этой дыре! О, благодарю тебя, $N! Скорее открой дверь и выпусти старика Локида на свободу!', '*кашель* Кто там? Не видите что ли, занято!', NULL, NULL, 'Ключ от уборной Грязнули (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4461, 'Оскверненный кнутокорень', '', '', 'Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4462, 'Оскверненный ночной дракон', '', '', 'Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4463, 'Манускрипт Размышления', '', '', 'Забирай свою безделушку, неразумная тварь. Оставь меня в покое!', NULL, NULL, NULL, 'Черный алмаз', 'Черная кровь замученных', 'Зелье из потрошков', 'Манускрипт размышления');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4464, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4465, 'Оскверненный песнецвет', '', '', 'Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4466, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и исцеляется.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4467, 'Оскверненный ветроцвет', '', '', 'Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и исцеляется.', NULL, NULL, NULL, 'Кенарийский бальзам исцеления растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4481, 'Манускрипт Здоровья', '', '', 'Это вызов его памяти... Смертный оканчивает работу всей его жизни.$B$BЗабирай свою безделушку и убирайся!', NULL, NULL, NULL, 'Черный алмаз', 'Коктейль \"Легкое дыхание\"', 'Манускрипт здоровья', 'Ночное дыхание дракона');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4482, 'Манускрипт Упорства', '', '', '', NULL, NULL, NULL, 'Черный алмаз', 'Манускрипт упорства', 'Кристалл-хранитель', 'Глаз Каджала');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4483, 'Манускрипт Устойчивости', '', '', 'Прочие манускрипты рассеяны по свету. По таким уголкам, куда ты не осмелишься войти. Которых бы лучше и не было.$B$BЯ выпью из этих составляющих силу. А ты получишь то, что останется...', NULL, NULL, NULL, 'Черный алмаз', 'Хрустальная спираль', 'Пылающая сущность', 'Манускрипт Устойчивости');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4484, 'Манускрипт Ненасытности', '', '', 'Голова болит... Сила бескрайних пределов вселенной... Ахххх!$B$B*Матредис кривится от боли.*$B$BБери, что тебе нужно, и уходи!', NULL, NULL, NULL, 'Черный алмаз', 'Манускрипт ненасытности', 'Драчливый корнеплод', 'Кристалл силы духа');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4485, 'Фолиант благородства', 'Приветствую, $N. Я вижу, твоя решимость по-прежнему сильна, как и твоя вера.$B$BДумаю, настало время тебе поговорить с Даторианом Раллом в Штормграде. Ты $gдолжен:должна: получить еще несколько уроков, и я чувствую, ты к ним $gготов:готова:.$B$BНайди Даториана в Соборе Света – и пожалуйста, $N, отнесись к его урокам серьезно. Ты $gдобился:добилась: своего положения благодаря скромности и упорному труду, так не разочаруй нас – не становись $gвысокомерным:высокомерной:.$B$BУдачи тебе.', 'Поговорите с Даторианом Раллом в Штормграде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4486, 'Фолиант благородства', 'Ну-ка, ну-ка, поглядите на могучего паладина во всей красе!$B$BПрошу прощения, $N, я не в обиду... Просто иногда немного завидую твоим достижениям. Тиза говорит, что в этом – моя слабость, и я обещал ей, что искореню этот недостаток. Но пока не преуспел, $gсам:сама: понимаешь.$B$BНо вот почему я хотел с тобой поговорить: Даториан Ралл из Штормграда сообщил, что хочет встретиться с тобой в Соборе Света, когда ты будешь к этому $gготов:готова:. Звучало веско. Звучало так, как будто что-то эдакое происходит.', 'Поговорите с Даторианом Раллом в Штормграде.', 'А, вижу, ты вернулся в храм, Лордхаарт. Это хорошо. Многое случилось за последнее время, и я попрошу тебя о помощи, если ты докажешь, что способен справиться с моими поручениями.$B$BКругом множество предателей. Мне нужна будет твоя помощь, чтобы остановить их.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4487, 'Призывание коня Скверны', 'Ага, хорошо, что ты здесь. Я посылал $gсуккуба:инфернала: за тобой, но, похоже, ты $gуспел:успела: добраться сюда раньше, чем они добрались до тебя. Ладно.$B$BТут недавно пошли разговоры о твоем растущем могуществе – и это очень хорошо для тебя, а для других, наверное, не очень. Короче, я думаю, что ты уже достаточно $gзарекомендовал:зарекомендовала: себя и потому заслуживаешь...хе-хе... подарочка.$B$BВ Степях над Кабестаном ты найдешь человека по имени Страхад. Уверен, вы уже встречались.', 'Поговорите в Кабестане со Страхадом Фарсаном.', 'Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны.$B$BМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4488, 'Призывание коня Скверны', 'О, $N, ты $gпочтил:почтила: нас своим присутствием. Какая честь!$B$BНадеюсь, ты не думаешь, что мы будем тебя облизывать с ног до головы. Может, ты и быстро набираешь могущество, но ты все еще дитя малое в том, что касается истинного знания и мудрости. Если не поостережешься, тебя охватит одержимость, и воля твоя ослабеет.$B$BНо ближе к делу – Страхад желает говорить с тобой. Он по-прежнему живет в башне над Кабестаном в Степях. Советую не тянуть канитель.', 'Поговорите в Кабестане со Страхадом Фарсаном.', 'Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны.$B$BМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4489, 'Призывание коня Скверны', 'А, $r! Иди сюда!$B$BТебя ведь зовут $N, не так ли?$B$BЯ так и думал. Короче: твоя мощь растет, и это было замечено. Теперь пора наградить тебя за старания.$B$BИди в Степи. Там, над Кременником, ищи Страхада Фарсана – может, помнишь его? У него есть для тебя кое-что. Это много времени не займет.', 'Поговорите в Кабестане со Страхадом Фарсаном.', 'Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны.$B$BМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4490, 'Призывание коня Скверны', 'Я бы наградил тебя за терпение да усердие. Но, знаешь ли, в будущем призывание коня Скверны будет куда труднее. Придется заслужить награду... и это будет непросто.$B$BПока же получи способность призывать эту тварь и пользуйся ей по своему усмотрению.', 'Поговорите в Кабестане со Страхадом Фарсаном, чтобы получить способность призывать коня Скверны.', 'Удачи, $N. Надеюсь встретиться с тобой в будущем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4491, 'Дружеская помощь', 'Уф... Как здесь жарко! $B$BЯ тут прогуливался по окрестностям, как вдруг накатила эта жуткая жара. Похоже, у меня тепловой удар. $B$BПомоги мне добраться до моей подруги Мучи в Укрытие Маршалла. Думаю, я сумею дойти, если кто-то будет вести меня. $B$BЕсли я вдруг потеряю сознание, просто плесни мне в лицо воды из фляги Мучи. Думаю, этого будет достаточно...', 'Отведите Ринго к Муче Кусора в Укрытие Маршалла. Если Ринго потеряет сознание, плесните на него воды из фляги Спрэггл, чтобы привести его в чувство.', 'Да, Ринго совсем плох, $N, но я рада, что он вернулся в целости и сохранности... $B$BСпасибо, что разыскал его!', 'О, я так волновалась за Ринго!', NULL, NULL, 'Доставить Ринго к Муче Кусора в Укрытие Маршалла.', 'Фляга Мучи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4492, 'Потерялся!', 'Помоги мне, $N! Мой друг Ринго отправился сегодня исследовать вулкан к югу отсюда, и его что-то долго нет! Я очень беспокоюсь. $B$BТы сможешь найти его? Вот, возьми с собой эту флягу, думаю она ему пригодится!', 'Найдите Ринго на Вулкане Огненного Венца.', 'О, я так рад, что ты нашел меня!', 'Кто... Кто здесь?', NULL, NULL, 'Фляга Мучи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4493, 'Нашествие силитидов', 'Такое впечатление, что намерения, более того, смысл самого существования силитидов состоит в том, чтобы сожрать все, что отлично от них. Они ведут себя очень целеустремленно и именно поэтому представляют серьезную опасность для всего Азерота.$B$BВсе, что мы видели до сих пор, – это только цветочки! Подозреваю, что их основные силы сосредоточены в глубине Калимдора, в Кратере Ун\'Горо. Ступай в Прибамбасск в пустыне Танарис и поговори с алхимиком Пестычинсом. Расскажи ему о моей гипотезе. Он наверняка поможет нам бороться с силитидами.', 'Поговорите с алхимиком Пестычинсом в Прибамбасске.', 'Как понимаю, тебя прислала Грацина? Твой опыт в истреблении этих тварей воистину бесценен – пока я еще не видел никого, кто осмелился бы потягаться с ними. Что же до идеи Грацины насчет того, что их гнездо – Кратер Ун\'Горо... может быть, оно и так. Ун\'Горо – это таинственные и опасные джунгли к западу отсюда. Может быть, мы действительно подошли на шаг ближе к разрешению загадки силитидов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4494, 'Нашествие силитидов', 'Такое впечатление, что намерения, более того, смысл самого существования силитидов состоит в том, чтобы сожрать все, что отлично от них. Они ведут себя очень целеустремленно и именно поэтому представляют серьезную опасность для всего Азерота.$B$BВсе, что мы видели до сих пор, – это только цветочки! Подозреваю, что их основные силы сосредоточены в глубине Калимдора, в Кратере Ун\'Горо. Ступай в Прибамбасск в пустыне Танарис и поговори с алхимиком Пестычинсом. Расскажи ему о моей гипотезе. Он наверняка поможет нам бороться с силитидами.', 'Поговорите с алхимиком Пестычинсом в Прибамбасске.', 'Да, я так понимаю, тебя Зилзибин прислал? Твой опыт воистину бесценен: до тебя я не встречал никого, кому доводилось сражаться с этими тварями. Что касается идеи Зиба насчет Кратера Ун\'Горо... Может быть, он и прав. Ун\'Горо – это таинственные и опасные джунгли к западу отсюда. Может быть, мы действительно подошли на шаг ближе к разрешению загадки силитидов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4495, 'Добрый друг', 'Мой друг по имени Иверрон обычно навещает меня в одно и то же время каждый день. Странно, что сегодня он вообще не пришел – он задерживается уже на несколько часов.$B$BПризнаться, $N, я несколько волнуюсь. Иверрон проводит много времени возле пещеры к северу отсюда, и я знаю, насколько там опасно – это ведь логово пауков!$B$BПослушай, если ты вдруг направляешься в ту сторону, то не поищешь ли Иверрона?', 'Найдите Иверрона возле пещеры на севере.', 'Я рад, что тебе удалось найти меня, $N. Как ты узнал, что я тут?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4496, 'Путаница в джунглях', 'Исследования показали, что силитиды подобны пчелам – стоит убить королеву улья, и остальные без нее пропадут. Я создам приманку, которая позволит тебе выманить королеву. Выманив ее, сразись с ней.$B$BВпрочем, для начала нам понадобятся некоторые реагенты. Отправляйся на запад, в ульи силитидов в Кратере Ун\'Горо и принеси ароматическую железу одного из мерзких жуков. Кроме того мне понадобятся образцы почвы из кратера.', 'Принесите ароматическую железу Гориши и 5 образцов почвы из Кратера Ун\'Горо алхимику Пестычинсу в Прибамбасск.', 'А, вот и ароматическая железа. Похоже, мембрана цела – великолепно. И почва тоже подойдет. Я кое-чего добавлю, и сделаю из этого прекрасную приманку.$B$BПодожди минутку, и все будет готово. После этого можно будет сделать следующий шаг и остановить силитидов, пока они не захватили Прибамбасск... и весь остальной Калимдор.', 'Найти подходящую ароматическую железу может оказаться непросто – она должна быть в идеальном состоянии, чему совсем не способствует способ добычи. Что же до почвы, ее-то должно быть совсем нетрудно отыскать.$B$BКороче, ты принес мне все необходимое?', NULL, NULL, 'Ароматическая железа Гориши', 'Почва Ун\'Горо', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4501, 'Осторожно, злой терродактиль', 'Требуется: опытный боец для устранения угрозы со стороны терродактилей, населяющих Кратер Ун\'Горо. Популяция этих тварей растет, они уже представляют серьезную угрозу забредшим в кратер путникам. $B$BНеобходимо уменьшить популяцию, убив 10 терродактилей. $B$BВыполнивших задание просьба обращаться за наградой к Муче Кусора.', 'Убейте 10 терродактилей, затем поговорите со Мучей Кусора в Укрытии Маршалла.', 'Я просто в шоке от жутедактилей! Спасибо тебе, $N! Теперь я хотя бы смогу спокойно высунуть нос из Укрытия Маршалла!', 'Ты знаешь, я как-то не особо беспокоилась по поводу того, что эти твари вдруг стаои плодиться, как кролики. Пока однажды не увидела надпись на большом камне. $B$BОПАСАЙСЯ ЖУТЕДАКТИЛЕЙ!$B$BКто мог такое написать? Это уж слишком... слишком жутко, чтобы не замечать!', NULL, NULL, 'Бесноватый терродактиль убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4502, 'Вулканическая активность', 'Я многому научилась у Марвона Клепальщика. Но он уже так давно уехал, что я подумываю начать собственные эксперименты.$B$BЯ недавно читала о Кратере Ун\'Горо и странной вулканической деятельности в его центре. Мне думается, что многое можно было бы узнать, если бы мне удалось заполучить для исследований немного пепла из тамошних элементалей.$B$BТы не против добыть немного пепла для меня, раз уж все равно туда направляешься?', 'Добудьте 9 образцов пепла Ун\'Горо из элементалей огня, что водятся вокруг вулкана в Кратере Ун\'Горо, и доставьте их Лив Быстрочин в Кабестан.', 'Эти образцы как нельзя лучше сгодятся для моих исследований! Спасибо, $N! Обещаю – тебе я расскажу о моих открытиях в первую очередь!', 'Это правда, что вулкан в Ун\'Горо активен? Уверена, что многе смогу узнать по вулканическому пеплу, $N.', NULL, NULL, 'Пепел Ун\'Горо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4503, 'Крылолет Шиззла', 'Я работаю над вертолетом! $B$BИ вот, застрял здесь и не могу выбраться! С удовольствием тормознул бы грифона или ветрокрыла, чтобы подбросили меня до Прибамбасска, да только ужасно боюсь этих тварей! $B$BТы мне не поможешь? Мне осталось сделать только крылья, и я думаю, что чешуя терродактиля или деметродона была бы идеальным материалом. Однако маленькому гоблину не под силу справиться со столь грозными хищниками! А ты на вид весьма $gкрут:крута:! Может, попытаешься добыть мне чешуек?', 'Принесите 8 чешуй перепончатого деметродона и 8 чешуй перепончатого терродактиля Шиззлу в Укрытие Маршалла.', 'Да, эта чешуя подходит просто превосходно! С помощью этих чешуек мне уж точно удастся поднять мое творение в воздух! $B$BБлагодарю тебя!', 'Как вы лодку назовете, так она и поплывет! Нужно хорошее имя моему летательному аппарату! Я назову его... Крылолет!', NULL, NULL, 'Чешуя перепончатого деметродона', 'Чешуя перепончатого терродактиля', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4504, 'Суперлипучка', 'Я всегда искал способ быстро заработать. Если ты поможешь воплотить мою последню идею, я поделюсь с тобой доходами. Что ты на это скажешь?$B$BТак я и думал!$B$BСтупай к смоляным ямам в северной части Кратера Ун\'Горо и принеси мне смолы. Но не просто смолы, а смолы из зверей, живущих вокруг этих ям. Обычная смола недостаточно липкая.$B$BВ растениеподобных существах присутствует хлорофилл, и смола, смешанная с ним, делается сверхлипкой.', 'Отнесите 12 образцов сверхлипкой смолы Тран\'реку в Прибамбасск.', 'Да, да, та самая смола…$B$BЭй, минуточку, руки мои, руки... Я не могу их разлепить…$B$BМожет быть, это не такая уж хорошая идея. Впрочем, стоп! Растворитель суперлипкой смолы! Вот что разойдется за полдня!', 'Тран\'рек гений, прочь сомненья – этот суперклей с руками оторвут!', NULL, NULL, 'Сверхлипкая смола', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4505, 'Источник порчи', 'Говорят, будто я слишком жестока... Но ведь это только потому, что я жажду добыть для Орды преимущество перед Альянсом любым способом.$B$BСейчас меня прежде всего интересует лунный колодец в руинах Констелласа, к югу отсюда, который охраняют сатиры из племени Нефритового Пламени. Этот лунный колодец, некогда символ возрождения этих несносных ночных эльфов, ныне осквернен, и порождает все больше сатиров.$B$BУ меня есть одна мысль, $N, и мне хотелось бы получить пробу воды оттуда... для моей любимой кошечки.', 'Принесите образец оскверненной воды из лунного колодца сатиров из племени Нефритового Пламени Винне Хеззард на заставу Отравленной Крови.', 'Очень хорошо.Нам надо найти способ использовать эту порчу против наших врагов...', 'Это чрезвычайно важно. Ступай не медля!', NULL, NULL, 'Наполненный флакон', 'Прочный флакон', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4506, 'Зараженные саблезубы', 'Эта оскверненная вода может помочь нам, $N. От одной ее капли мои котятки выросли вдвое и даже стали сильнее... кое в чем. Эти кошечки могут оказаться полезными...$B$BВот, $N. Возьми эту кошачью переноску и выпусти котеночка, что сидит внутри возле лунного колодца, что в руинах Констелласа. Хе-хе... результаты тебе наверняка понравятся!$B$BПотом принеси кошечку ко мне обратно, а я уж возмещу тебе затраты времени.', 'Отнесите котенка Винны к оскверненному лунному колодцу, выпустите его, затем снова принесите Винне.Как только вернетесь к Винне, щелкните мышкой по котенку, чтобы выпустить его.', 'Отлично!$B$BОтрекшиеся не побрезгуют никакими средствами, чтобы сокрушить Альянс! И эта оскверненная вода весьма поможет нам в наших будущих трудах...', 'И не говори мне, что тебе не удалось туда попасть! Иди!', NULL, NULL, 'Верните оскверненную кошку Винне Хеззард.', 'Клетка котенка Винны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4507, 'Пешка берет королеву', 'Вот и приманка. Внутри улья должен быть какой-то кристалл. Мы думаем, что силитиды пользуются им для вещания по всему улью. Где он? Я бы поискал в инкубаторах.$B$BЕсли положить приманку на этот кристалл, непременно явится королева. Но предупреждаю, без охраны она не ходит. Убей ее и вынь из нее мозг. Как ни гадко это звучит, его необходимо изучить. Удачи, $N!', 'Призовите и сразите матку улья Гориши.Принесите мозг матки Гориши алхимику Пестычинсу в Прибамбасск.', 'Поразительно! Сегодня мы одержали победу. Впрочем, нам понадобится время, чтобы разобраться с полученными материалами. Не волнуйся, все пойдет в дело.$B$BЧто до силитидов, я искренне сомневаюсь, что мы сумели остановить их нашествие. К сожалению, это было бы слишком легко.', 'Нам не обойтись без мозга королевы. Судя по всему, силитиды находятся под контролем чуждой злой силы. Мне страшно думать, кто может управлять такой злобной тварью, как силитид, $N.', NULL, NULL, 'Мозг королевы Гориши', 'Приманка для королевы Гориши', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4508, 'Затишье перед бурей', 'Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты.$B$BОтнеси мой последний отчет Грацине Силе Духа, в Дарнас; она ведь по-прежнему в [раме Луны? У нее много друзей среди важных шишек Альянса, $N; если удастся привлечь их внимание, быть может мы и выживем.', 'Отнесите отчет Пестычинса о ситуации в Ун\'Горо Грацине Силе Духа в Дарнас.', 'Хотя я очень благодарна тебе, не знаю, выйдет ли из этого толк. Альянс видит лишь опасность, исходящую от Орды, а ведь даже наши вожди здесь, в Дарнассе, не понимают, в чем именно она состоит. Глупцы вроде Фэндрала Оленьего Шлема уверяют, что силитиды не могут грозить нам как тогда, в далеком прошлом. Он невежда – и невежа!$B$BТы видел опасность своими глазами. Мы должны одолеть силитидов!', 'Они глупцы, $N! Бессмысленная ненависть к Орде затмила им разум. Они не видят дальше своего носа – не верят в опасность, грозящую всем нам. Не знаю, как еще можно доказать им реальность нашествия силитидов. Может, бросить прямо в ульи?$B$BПрости, ты, наверное, несешь какие-то вести?', NULL, NULL, 'Отчет Пестычинса о ситуации в Ун\'Горо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4509, 'Затишье перед бурей', 'Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что-либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты.$B$BОтнеси мой последний отчет Зилзибину Барабанному Бою, в Оргриммар; он ведь по-прежнему там? У него много друзей среди важных шишек Орды; если удастся привлечь их внимание, быть может мы и выживем.', 'Отнесите отчет Пестычинса о ситуации в Ун\'Горо Зилзибину Барабанному Бою в Оргриммар.', 'Хотя я очень благодарна тебе, не знаю, выйдет ли из этого толк. Орда видит лишь опасность, исходящую от Альянса. Если бы удалось доложить о случившемся лично Траллу, он непременно принял бы меры, но его окружают дурные советчики. Они готовы гоняться за собственным хвостом, надеясь застать Альянс врасплох!$B$BТы видел опасность своими глазами. Мы должны одолеть силитидов!', 'Они глупцы, $N! Бессмысленная ненависть к Альянсу затмила им разум. Они не видят дальше своего носа – не верят в опасность, грозящую всему миру. Не знаю, как еще можно доказать им реальность нашествия силитидов. Может, бросить прямо в ульи?$B$BПрости, ты, наверное, несешь какие-то вести?', NULL, NULL, 'Отчет Пестычинса о ситуации в Ун\'Горо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4510, 'Затишье перед бурей', '$N, твоя помощь просто неоценима. Придет время, и, думается, я снова буду вынуждена обратиться к тебе за содействием в борьбе против силитидов. Мы должны осмыслить все, что узнали в Ун\'Горо. Опасаюсь, что мои предположения по поводу того, что силитиды родом из Ун\'Горо, неверны... и где-то их гораздо больше.$B$BОтнеси эту бумагу Идриане в банк. Она выдаст тебе кое-что из моего хранилища в знак моей признательности. Благодарю тебя за помощь, $gотважный:отважная:c: $C.', 'Отнесите банковскую расписку Идриане в банк Дарнаса.', 'Эта расписка дает мне право выдавать вам предметы из хранилища Грацины Силы Духа в нашем банке. Похоже, она весьма вам благодарна!', 'Элуне\'адоре, $C. Чем могу помочь?', NULL, NULL, 'Банковская расписка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4511, 'Затишье перед бурей', 'Спасибо тебе, $N. Без тебя у нас бы ничего не вышло. Несомненно, вскоре придет время, когда я снова попрошу твоей помощи в борьбе с силитидами. Придется пересмотреть то, что известно нам по Ун\'Горо. Боюсь, мое предположение, что силитиды происходят из Ун\'Горо, оказалось ложным. Где-то есть другое гнездо, куда более крупное.$B$BОтнеси эту записку Карусу в банк. Он выдаст тебе кое-что, что может считаться знаком моей благодарности. Спасибо за помощь, $gмогучий:могучая:c: $C!', 'Отнесите банковскую расписку Карусу в банк Оргриммара.', 'Согласно этой расписке, мне следует выдать вам некий предмет из хранилища Зилзибина Барабанного Боя. Кажется, вас можно поздравить!', 'Заг-заг! Чем могу служить, $C?', NULL, NULL, 'Банковская расписка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4512, 'Долгий путь слизнюка', 'Но больше всего я изучал слизнюков. Я понимаю, что звучит нелепо, но их же почти не осталось!$B$BНе так давно я помогал одной даме из Менетила искать ее сумку – так слизнюки эту сумку сожрали. Я видел, что члены Королевского фармацевтического общества Подгорода собирают образцы этих тварей. Я хочу понять, почему! Откуда они их берут?$B$BЯ слышал, что они водятся в Оскверненном лесу. Мне нужны экземпляры этих слизнюков для продолжения исследований. Я дам вам банки, а вы возьмете образцы мертвых существ.', 'Принесите 6 флаконов с образцами нечистых слизнюков и 6 флаконов с образцами проклятых слизнюков Ларису Обалдую в Стальгорн.', 'Блестящий результат, $N! Вы умудрились подойти достаточно близко, взять образцы этих гнилостных тварей и ничуть не пострадать! Благодарю вас. О, это как раз то, что надо. Немедленно примусь за эксперименты.$B$BЕсли я прав, я стану одним из величайших ученых Лиги Исследователей!$B$BЭто покажет всем дворфам, что они правильно поступили, пустив нас, гномов, в Стальгорн после гномреганской катастрофы.', 'Некоторые мои эксперименты дают просто невероятные результаты. Думаю, еще немного, и я смогу понять природу этих тварей и выяснить, какую роль они сыграли в происхождении жизни в Азероте... если, конечно, они вообще имеют отоношение к Азероту.$B$BОдна из величайших моих теорий – не слишком популярных – гласит, что слизнюки и слизь не связаны собственно с происхождением нашей планеты. Они, скорее, ее выделения.$B$BНо я не могу ни доказать ее, ни опровергнуть, пока не получу побольше образцов.', NULL, NULL, 'Флакон с образцом проклятого слизнюка', 'Флакон с образцом нечистого слизнюка', 'Упаковка пустых коробочек для слизней', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4513, 'Долгий путь слизнюка', 'Мне, похоже, понадобятся еще образцы, $N. Но – как бы это сказать – они должны быть чистыми. Да знаю, знаю. \"Что значит \"чистые\", Ларис?\" Я не уверен. Я знаю только, что вот эти – осквернены... прямо как Оскверненный лес. Потому так важно понять. Эти слизнюки словно бы приспосабливаются к условиям места, в котором находятся. Мне нужны образцы, которые не заражены. Но где их взять? Где?!$B$B$N, возьмите эти банки на случай, если вам попадутся чистые экземпляры.', 'Принесите 10 флаконов c образцами чистых слизнюков Ларису Обалдую в Стальгорн.Если будет трудно их найти, возможно, стоит попытаться добиться от Лариса подсказки.', 'Так вы их нашли? $N, вы – сущее сокровище! Ваши преданность и помощь просто неоценимы, я даже не знаю, чем вас отблагодарить!$B$BПожалуйста, примите это за ваши труды. Мне надо кое над чем поработать, но я уверен, что, когда вы вернетесь, мне снова понадобится ваша помощь.$B$BБлагодарю вас! От всего сердца благодарю!', 'Как много нужно обдумать. Но что это значит? И как это влияет на жизнь народов Азерота?', NULL, NULL, 'Флакон с образцом чистого слизнюка', 'Сумка с пустыми флаконами для слизи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4521, 'Одичавшие стражи', 'Зимние Ключи расположены как раз за Древобрюхами на северо-востоке Оскверненного леса. Приходилось там бывать?$B$BЯ слышал, что эти края заселены существами, которых называют дикими совухами. Эти животные, как известно, охраняли тайны ночных эльфов.$B$BМы должны выяснить, какие тайны хранятся в Зимних Ключах.$B$BЯ слышал что лохматые совухи водятся к югу от этой дороги, а те, которых называют бешеными совухами, населяют центр Зимних Ключей. Убей их и расчисть дорогу.', 'Убейте для Трулла Баловня Судьбы 15 бешеных совухов и 15 лохматых совухов.', 'Отличные новости, $N. Теперь, когда эти твари не стоят у нас на пути, мы можем проникнуть в Зимние Ключи. Ты готов?', NULL, NULL, NULL, 'Бешеный совух убито', 'Лохматый совух убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4542, 'Письмо на Заставу Вольного Ветра', 'Кентавры стали все чаще нападать на эти земли, и об этом нужно срочно доложить на заставу Вольного Ветра! Отправляйся туда, найди дозорного утесов Долгорога и отдай ему это письмо. Форт находится к юго-востоку отсюда.$B$BНо будь осторожнее: неподалеку есть поселение племени Зловещего Тотема, и его представители в последнее время ведут себя беспокойно.', 'Отнесите срочное послание дозорному утесов Долгорогу на Заставу Вольного Ветра.', 'Опять плохие новости! Эти кентавры зашли слишком далеко! Они напали на один из моих караванов и убили всех погонщиков! Это неслыханно, они должны за это заплатить!', 'Что вы хотели, $C? Срочное послание? Для меня?', NULL, NULL, 'Срочное послание (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4561, 'Образцы на пробу из кратера Ун\'Горо', '', '', 'Вы берете чашку Петри с пробой слизи. Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое. В конце концов вы должны найти пробу, которая устроит химика Барабоса.', NULL, NULL, NULL, 'Образец слизи из Кратера Ун\'Горо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4581, 'Кайнет Штиль', 'Друид Кайнет Штиль прислал мне весточку. Он хотел бы получить отчет обо всем, что творится у нас на побережье и в лесах вокруг Астранаара. Он опасается, что по Ясеневому лесу расползается порча... Может, он и прав.$B$BВот, отнеси ему мой отчет. Ты найдешь его в святилище Лесной Песни, в лесах Ночной Песни к востоку отсюда.', 'Отнесите записку Шиндрелл Кайнету Штилю в Лесную Песнь.', 'А, отчет Шиндрелл! Премного благодарен, $N. Шиндрелл – отличный часовой, она отважна и умна. Надо прочесть это донесение и попытаться понять, что за нечисть расползается по Ясеневому лесу.', 'Ты что-то мне принес?', NULL, NULL, 'Записка Шиндрелл (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4601, 'Чистер 5200!', 'Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений.Небольшая табличка, прикрепленная к устройству, гласит: \"Чистер 5200\".$B$BВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.', 'Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.', 'Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.', 'Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.', NULL, NULL, 'Покрытый грязью предмет', 'Требуется денег: 3', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4602, 'Чистер 5200!', 'Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений.Небольшая табличка, прикрепленная к устройству, гласит: \"Чистер 5200\".$B$BВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.', 'Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.', 'Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.', 'Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.', NULL, NULL, 'Покрытый грязью предмет', 'Требуется денег: 3', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4603, 'Работа для Чистера', '', '', 'Чистер 5200 с яростным гудением принимается за работу. Въевшаяся грязь растворяется под воздействием гномьих чистящих средств. $B$BНаконец Чистер 5200 перестает вибрировать. Окошко премника со звоном открывается – в нем лежит аккуратно завернутая коробка.', NULL, NULL, NULL, 'Покрытый грязью предмет', 'Требуется денег: 3', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4604, 'Работа для Чистера', '', '', 'Чистер 5200 с яростным гудением принимается за работу. Въевшаяся грязь растворяется под воздействием гномьих чистящих средств. $B$BНаконец Чистер 5200 перестает вибрировать. Окошко премника со звоном открывается – в нем лежит аккуратно завернутая коробка.', NULL, NULL, NULL, 'Покрытый грязью предмет', 'Требуется денег: 3', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4605, 'Чистер 5200!', '', '', 'С проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приемника открывается, и вы видите в нем аккуратно завернутую коробочку. Видимо, машина выдает очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги... Что ж, посмотрим...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4606, 'Чистер 5200!', '', '', 'С проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приемника открывается, и вы видите в нем аккуратно завернутую коробочку. Видимо, машина выдает очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги... Что ж, посмотрим...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4621, 'Стой, Адмирал!', 'Слышь, ты, морской волк... Нам, пиратам Кровавого Паруса, жить да поживать бы, когда бы не Пиратская Бухта. Ух, мы порезвились бы вдоволь! А если б ты $gпырнул:пырнула: ножом командира флота Морского Рога,чихали бы мы тогда на его посудины! Если б ты $gпырнул:пырнула: ножом барона Ревилгаза, мы б и их закона не боялись.$B$BВ общем, коль хочешь стать у нас почетным адмиралом – да, АДМИРАЛОМ, я не шучу, прирежь обоих, и все дела. Иди, $gпарень:девица:, возвращайся, когда дело будет сделано.', 'Убейте командира флота Морского Рога и барона Ревилгаза из Пиратской Бухты, а потом возвращайтесь к командиру флота Фираллону на борту \"Кровавой завесы\" неподалеку от побережья Тернистой долины.', '', NULL, NULL, NULL, 'Барон Ревилгаз убито', 'Командир флота Морской Рог убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4641, 'Твое место в мире', 'Ну вот, $N, ты и $gстал взрослым... достаточно взрослым:стала взрослой... достаточно взрослой:, чтобы сражаться во имя Орды и во славу вождя.$B$B*Калтунк меряет вас взглядом.*$B$BДа, ты вполне годишься!$B$BРазумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного.$B$B*Калтунк хохочет.*$B$BОтправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, $gюный:юная:c: $C. Горнека ты найдешь в Логове, на западе.', 'Поговорите с Горнеком. Вы помните, как Калтунк отметил на карте его местонахождение и упомянул, что Горнек живет в Логове, здании, расположенном на западе.', 'Очередной рекрут Калтунка?$B$BВидно, плохи наши дела, если у нас нет никого получше. Ну, ничего. К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравый воитель Орды!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4642, 'Слияние', 'В этом сосуде находится слизнюк, созданный из пробы, которую ты $gпринес:принесла: из Оскверненного леса. Отнеси его к кратеру Ун\'Горо и отыщи чистого слизнюка. Подберись поближе, выпусти наш экземпляр и посмотри, что они сделают друг с другом.$B$BПо завершении эксперимента принеси мне пробу того, что останется. Я буду ждать тебя здесь, в Районе Фармацевтов.', 'Принесите образец перемешанной слизи химику Барабосу в Подгород.', 'О, великолепно, $N. Великолепно.$B$BНу и дела. Кто бы подумал, что они будут взаимодействовать таким образом... Придется посвятить побольше времени изучению феноменов окружающей среды, которые вызывают в этих тварях подобные изменения.$B$BА теперь я вернусь к своим исследованиям. Быть может, вскоре свидимся. Пока же – всего наилучшего.', 'Как идет эксперимент, $N? Я вернусь к изучению принесенных тобой проб, поскольку начинаю понимать, почему ими так заинтересовалась леди Сильвана. Если они в самом деле часть Древних богов, то кто знает, какую пользу они могли бы принести нам...', NULL, NULL, 'Образец перемешанной слизи', 'Упакованная едкая слизь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4661, 'Проба – образцы из Оскверненного леса', '', '', 'Вы берете чашку Петри с пробой слизи. Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое. В конце концов вы должны найти пробу, которая устроит химика Барабоса.', NULL, NULL, NULL, 'Образец слизи из Оскверненного леса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4681, 'Останки на берегу', 'Та тварь на берегу – не единственная на Темном Берегу. Вдоль побережья их еще много, да и в воде тоже. Я хотела бы, чтобы вы исследовали другие известные нам останки. Мне сообщили, что они находятся в воде, непосредственно к западу от Аубердина, возле затонувшего судна. Возвращайтесь ко мне с тем, что вам удастся найти полезного для нас.$B$BКстати, в ваших странствиях вы можете найти и другие подобные останки. Если вы обнаружите что-то, обязательно принесите нам для дальнейших исследований!', 'Извлеките останки морской черепахи из скелета морской черепахи, лежащего в воде к западу от Аубердина, а затем поговорите с Гвеннид Блай\'Леггонд в Аубердине.', 'Вы чрезвычайно помогли мне сегодня; теперь у нас есть серьезные шансы узнать, почему эти твари выбрасываются на отмели Темного Берега. Мысль о том, что они бегут сюда из прибрежных вод Тельдрассила, очень беспокоит меня. Если вы наткнетесь на другие останки в ваших странствиях, пожалуйста, дайте мне знать. Наши исследования здесь пока на начальной стадии.$B$BОт имени Храма Луны примите, пожалуйста, это в качестве благодарности за ваши труды. Благодарю вас, $N!', 'Когда вы исследуете останки твари, лежащие в воде к западу отсюда, я, наверное, смогу представить надлежащий отчет в храм Луны в Дарнассе. Возможно, тогда мы приблизимся к пониманию того, почему эти несчастные создания выбирают такую смерть, выбрасываясь на отмели на Темных берегах.', NULL, NULL, 'Останки морской черепахи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4701, 'Устранение опасности', 'Тебе несомненно приходилось видеть воргов, которыми командуют орки Черной Горы.$B$BВот что интересно – сколько мы их ни убиваем, их не делается меньше. Разведчики доносят, что воргов растят и обучают на пике Черной Горы, в столице орков этого клана. Отправляйся туда и поищи источник опасности. Отыщи... и уничтожь.$B$BУдачи, $N. Да хранит тебя Кенарий...', 'Отправьтесь на пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами.', 'Не думай о том, страдала ли она, Август. Этого зверя осквернило касание темной магии. Ты оказал Альянсу огромную услугу и получишь за нее награду.', NULL, NULL, NULL, 'Халикон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4721, 'Одичавшие стражи', 'Гонцы вернулись из Зимних Ключей с сообщением о том, что в его южной части есть группа небольших пещер. У них сложилось впечатление, что этот район обжили дикие совухи. Если они охраняют что-то важное, то, я думаю, именно там мы это и найдем.$B$BС этими дикими совухами тебе будет справиться намного сложнее, чем в предыдущий раз, $N. Эти создания, похоже, ввергает в безумие та самая вещь, которую они столь яростно защищают.', 'Убейте для Трулла Баловня Судьбы из Оскверненного леса 10 яростных совухов в Зимних Ключах.', 'Вот что я уважаю – так это хорошую работу, $N. Теперь мы можем дальше действовать в Зимних Ключах.', NULL, NULL, NULL, 'Яростный совух убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4722, 'Останки морской черепахи', 'Вы наткнулись на останки морской черепахи, некоторое время назад выбросившейся на Темные берега. Плоть ее уже объели мурлоки, обосновавшиеся неподалеку от останков. Вы можете набрать достаточное количество образцов, которые пригодятся Гвеннид Блай\'Леггонд.', 'Отнесите останки морской черепахи Гвеннид Блай\'Леггонд в Аубердин.', 'Еще одна находка, которую нам надо изучить. Хорошая работа, $N! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете.', 'Здравствуйте, $N, вы хотите рассказать еще что-то о тварях, выбросившихся на берег?', NULL, NULL, 'Останки морской черепахи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4723, 'Останки морской твари', 'Останки гигантского крепкозуба – намного больших размеров, чем можно было бы ожидать на Темных берегах, – лежат у побережья Туманного предела. Как это существо очутилось здесь, неизвестно; мурлоки, объедающие тушу, кажутся слишком слабыми и неспособными даже толпой притащить ее сюда.$B$BВ то время как некоторая часть костей уже начисто обглодана, останков еще достаточно, чтобы набрать образцов для Гвеннид Блай\'Леггонд.', 'Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.', 'Еще одна находка, которую нам надо изучить. Хорошая работа, $N! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете.', 'Может, когда-нибудь мы изыщем средство, чтобы несчастные твари больше не заканчивали впустую свою жизнь на отмелях Темного Берега. А до тех пор мы должны продолжать наши исследования.$B$BПриветствую, $N! С какими вы вестями?', NULL, NULL, 'Кости морской твари (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4724, 'Праматерь стаи', 'Ходят слухи, что ворги, управляемые орками Черной Горы, – создания сверхъестественных сил. Говорят также, что это не настоящие ворги, а потомство пса-демона, подаренное оркам властителем преисподней. $B$BПравда куда более проста, но не менее ужасна. Ворги Черной Горы – потомство Халикон, огромной праматери воргов. Каков из себя ее самец? Вряд ли кто из видевших его выжил, чтобы поведать об этом. $B$BНужно нанести удар по самому сердцу логова воргов. Уничтожь Халикон. И прошу тебя, не забывай об осторожности!', 'Убейте Халикон, праматерь стаи воргов Кровавого Топора.', 'Бешеные щенки? Гизрул Поработитель? И ты стоишь передо мной живехонький и рассказываешь об этом?! Глазам не верю! Ты заслужил свою награду!', NULL, NULL, NULL, 'Халикон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4725, 'Останки морской черепахи', 'Еще одни останки морской черепахи лежат прямо на берегу. К панцирю прикреплена упряжь. Скорее всего, черепаху выгнали на берег неизвестные нам твари; она не выбросилась на берег сама, хотя другие останки и наводят на эту мысль. Теперь останками черепахи завладели мурлоки племени Серой Мглы, питающиеся мертвечиной.$B$BОбследуя упряжь, вы обнаруживаете ящик со странными пометками. Может быть, Гвеннид Блай\'Леггонд сможет что-то понять?', 'Отнесите ящик со странными пометками Гвеннид Блай\'Леггонд в Аубердин.', 'Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Темного Берега.$B$BЯ отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и еще раз спасибо за вашу помощь.', 'Приятно вновь увидеть вас, $N. Мы прилагаем большие усилия, чтобы узнать, почему же огромные морские существа выбрасываются на пески Темного Берега, но на каждый найденный ответ возникает два новых вопроса.$B$BВы пришли, чтобы снова оказать нам помощь в расследовании?', NULL, NULL, 'Ящик со странной пометкой (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4726, 'Сущность детеныша дракона', 'Я уже несколько недель изучаю драконов в Пылающих степях, и кажется, наконец-то наметился определенный прорыв! Я создала устройство – Драко-инкарцинатор 900. Оно может поймать сущность детеныша дракона!$B$BПо крайней мере, я на это рассчитываю.$B$BВозьми это устройство и испытай его на детеныше дракона в Пылающих степях. Пока он будет под воздействием инкарцинатора, одолей его и выпусти из него сущность.$B$BЕсли это сработает, будет замечательно! И принеси мне образцы на изучение!', 'Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.', 'Сработало! Ты добыл сущность драконов! Молодец!$B$BОна мне очень пригодится в ходе экспериментов. Я надеюсь, что однажды придумаю способ ловить живых драконов или хотя бы добывать их яйца. Если ты придумаешь, как это сделать, то мне позавидуют все, кто занимается изучением драконов!$B$BЗаказчик тоже будет доволен. А такого, как он, лучше не огорчать...', 'Удалось получить сущность детенышей? Мне не терпится изучить ее.$B$BКроме того, моего заказчика лучше не разочаровывать.', NULL, NULL, 'Сущность детеныша дракона', 'Драко-инкарцинатор 900 (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4727, 'Останки морской черепахи', 'Скелет морской черепахи лежит на песчаной отмели на севере Темных берегов. Мурлоки племени Серой Мглы либо не нашли ее тушу, либо по каким-то причинам не рискнули приблизиться к ней. В любом случае, от черепахи осталось достаточно, чтобы взять образцы для Гвеннид Блай\'Леггонд, проводящей расследование по поручению Храма Луны.', 'Отнесите останки морской черепахи Гвеннид Блай\'Леггонд в Аубердин.', 'Интересно, что мурлоков там не было. Мы будем иметь это в виду, когда начнем изучать эти останки! Благодарю вас за ваши труды, $N; Храм Луны уполномочил меня передать вам эти деньги в качестве компенсации за потраченное время.', 'Приветствую снова, $N! Вы нашли еще каких-то выбросившихся на берег тварей, о которых следовало бы узнать Храму Луны?', NULL, NULL, 'Останки морской черепахи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4728, 'Останки морской твари', 'Растерзанные останки того, что на вид кажется похожим на гигантское морское млекопитающее, лежат на берегу. Около них валяется тачка и различные инструменты, как будто кто-то раньше уже пытался изучать останки. Хотя мурлоки основательно растащили скелет, останков достаточно, чтобы найти подходящий образец костей для Гвеннид Блай\'Леггонд в Аубердине.', 'Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.', 'О, я уверена, вы обнаружили останки твари, которые уже изучались Лигой Исследователей. Они работают здесь, на Темном Берегу, и упоминали, что изучали одну из выбросившихся на берег тварей, пока их не прогнали мурлоки. Похоже, вам удалось добиться успеха там, где и мы, и они потерпели фиаско. Пожалуйста, примите эту скро$Nю плату от имени Храма Луны.', 'Приветствую вас снова, $N! Что привело вас обратно в Аубердин? Может быть, вы хотите доложить о новой находке?', NULL, NULL, 'Кости морской твари (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4729, 'Редкие звери Киблера', 'Должно быть, тебе интересно, что я здесь делаю? Взгляни на клетки! Разве не ясно?$B$BЯ очень люблю животных, но по роду занятий я торговец. Я разыскиваю и приручаю редких зверей, чтобы богатые и знаменитые клиенты могли сделать их своими питомцами.$B$BТеперь ты, наверное, хочешь спросить: \"Чем тебе помочь, Киблер?\" Отвечаю: возьми эту клетку и поймай несколько щенков-воргов. За это я приручу одного из них и отдам тебе!', 'Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру.', 'Ты вовремя их принес,$N. Подрасти они еще немного, и их не удалось бы приручить! Дай мне пару минут, и одного из них можешь забирать.', '*Киблер яростно спорит с Опусом.*', NULL, NULL, 'Щенок ворга в клетке', 'Пустая клетка для щенка ворга', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4730, 'Останки морской твари', 'Полуразложившиеся тело твари, похожей на огромное морское млекопитающее, лежит на берегу. Группа мурлоков, более сильных, чем обитающие ближе к Аубердину, обосновалась вокруг погибшего создания. Останков достаточно, чтобы отобрать образцы костей, которые можно отнести Гвеннид Блай\'Леггонд.', 'Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.', 'Кости, которые вы принесли, принадлежат мирным морским млекопитающим, обитающим в водах, окружающих корни Тельдрассила. Им, насколько известно, никогда не было свойственно выбрасываться на берег, как это делают крепкозубы. Хотела бы я знать, почему они так ведут себя. Что ж, может быть, изучение их останков принесет свои плоды, и мы что-то узнаем.$B$BИ снова спасибо вам за помощь. Пожалуйста, примите это вознаграждение от имени Храма Луны.', 'Снова приветствую вас, $N! Хотите сообщить об очередной находке?', NULL, NULL, 'Кости морской твари (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4731, 'Останки морской черепахи', 'Еще одни останки морской черепахи лежат у береговой линии. На панцире есть упряжь, которая еще частично держится. Возможно, несчастная тварь не сама выбросилась на берег (что кажется наиболее вероятным по отношению к другим погибшим тварям), а была пригнана к береговой линии неизвестными существами. Могучие мурлоки племени Серой Мглы сделали остов этой твари своим жилищем.$B$BОбследуя упряжь, вы обнаруживаете ящик со странными пометками. Возможно, Гвеннид Блай\'Леггонд сумеет что-то разобрать?', 'Отнесите ящик со странными пометками Гвеннид Блай\'Леггонд в Аубердин.', 'Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Темного Берега.$B$BЯ отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и еще раз спасибо за вашу помощь.', 'Я вновь приветствую вас, $N! Работа, которую вы проделали для Храма Луны, просто великолепна. Порадуете нас снова плодами своих трудов?', NULL, NULL, 'Ящик со странной пометкой (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4732, 'Останки морской черепахи', 'Вы обнаружили тело морской черепахи, выбросившейся на Темный Берег некоторое время назад. Оно почти дочиста объедено мурлоками клана Серой Мглы – теми самыми, что поселились вокруг останков. Однако, похоже, несколько подходящих образцов для Гвеннид Блай\'Леггонд вы сможете отобрать.', 'Отнесите останки морской черепахи Гвеннид Блай\'Леггонд в Аубердин.', 'Так вы нашли и других выбросившихся на берег тварей, $N? Морские черепахи обычно резвились в водах у подножья Нордрассила – до его гибели. Однако с рождением Тельдрассила этих созданий становится все меньше и меньше. Некоторые, как мы уже знаем, оканчивают свою жизнь здесь – непонятно почему.$B$BБыть может, ваша помощь поможет нам раскрыть эту тайну. Пожалуйста, примите эти деньги за образцы, предоставленные нам для исследований.', 'Я вновь приветствую вас, $N! Вам удалось обнаружить еще что-то, интересное Храму Луны?', NULL, NULL, 'Останки морской черепахи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4733, 'Останки морской твари', 'Останки животного, похожего на гигантского крепкозуба, лежат, вынесенные на отмель в скалистой Сумрачной Излучине. Этот крепкозуб в несколько раз больше любого из тех, что обитают в здешних водах. Откуда бы это создание ни приплыло, вряд ли оно родом с Темных берегов.$B$BХотя туша животного уже потеряла целостность, останков достаточно, чтобы найти подходящие образцы для Гвеннид Блай\'Леггонд.', 'Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.', 'Размеры крепкозуба, о котором вы рассказываете, просто ошеломляют. Даже самые старые крепкозубы в этих водах – и то в несколько раз меньше. В то время как крупные крепкозубы, как известно, обитают близ Тельдрассила, их количество постоянно уменьшается. Интересно, связано ли как-то это с выбрасывающимися на берег тварями?$B$BМы продолжим анализ костей, которые вы нам принесли, а это вам вознаграждение от имени Храма Луны. Благодарю вас, $N.', 'Хвала Элуне – я рада нашей встрече, дорогой $N. Расследование Храмом Луны феномена выброшенных на берег созданий продолжается. Быть может, вы хотите предложить нам еще что-то интересное?', NULL, NULL, 'Кости морской твари (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4734, 'Заморозка яйца', '$N, я работаю над созданием нового устройства, яйцехладоскопа! Оно предназначено для того, чтобы направить сгусток холода на яйцо дракона... и заморозить его! Можешь испытать эту штуку?$B$BГоворят, что на пике Черной горы у драконов есть питомник, в котором полно яиц. Подходящее место для испытаний! Заморозь яйцо и расскажи, сработал прибор или нет.$B$BНе беспокойся. Замороженные драконьи яйца совершенно безобидны. А вот остальных надо опасаться!', 'Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье на Пике Черной Горы.', 'Сработало? Великолепно! Я так и знала!$B$BПока тебя не было, я создала новую модель яйцехладоскопа. С куда большим радиусом действия.$B$BВозьми его, вдруг случайно забредешь на пик Черной горы.', 'Ну как, испытал яйцехладоскоп?', NULL, NULL, 'Прототип яйцехладоскопа (Прилагается)', 'Испытать модель яйцехладоскопа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4735, 'Сбор яиц', '$N, я, наконец, готова исследовать настоящие яйца драконов! Возьми это устройство-коллекционер. Он предназначен для захвата драконьего яйца и подготовки его к транспортировке. Возвращайся в Гнездовье и собери при помощи этой штуки несколько яиц.$B$BНе забудь, первым делом их надо заморозить, иначе из них могут вылупиться драконы, не успеешь собрать!$B$BКак только наберешь достаточно яиц, неси их мне!', 'Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.', 'Ух ты! Яйца! Значит, устройство-коллекционер сработало! Я гений!$B$BСпасибо, $N. Мой заказчик очень порадуется яйцам...', 'Ты несешь мне яйца, $N? Мой заказчик прослышал, что ты занимаешься их сбором, и очень хочет их получить!', NULL, NULL, 'Коллекционное яйцо дракона', 'Устройство-коллекционер (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4736, 'Поиски Менары Расщепительницы Бездны', 'А, привет, $N. Твое обучение идет неплохо. Настолько неплохо, что, я думаю, пришло время вознаградить тебя за прилежание – и за то, что сила магии все еще не поработила тебя.$B$BЕсли тебя заинтересовали мои слова, поговори с Менарой Расщепительницей Бездны из Кабестана. В настоящий момент она живет в башне Страхада Фарсана, построенной на утесе над городом.$B$BОна не очень доброжелательно настроена, поэтому похвалы от нее не жди. Но если ты будешь стараться, твои усилия не пропадут втуне.', 'Поговорите с Менарой Расщепительницей Бездны в Степях.', 'А, тебя прислал Остротерн. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4737, 'Поиски Менары Расщепительницы Бездны', 'Ха! Я вижу, ты стремишься к могуществу. Не сомневаюсь, рано или поздно ты падешь жертвой соблазна и жажды магии.$B$BПфа! Ты $gглуп:глупа:! Время покажет, что я был прав, – ничто другое, одно лишь время…$B$BНо мне кажется, что не все согласны с Зевростом. Менара готова создать предметы, которые помогут тебе обрести могущество и обуздать собственную силу. Если хочешь, ступай в Кабестан. Она живет в башне над городом.', 'Поговорите с Менарой Расщепительницей Бездны в Степях.', 'А, тебя прислал Зеврост. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4738, 'Поиски Менары Расщепительницы Бездны', 'Пойми одно, $N: я считаю, что ты не $gготов:готова: к такой ответственности. Я уверена, что вовлекать новичков в создание любых предметов силы, тем более, непроверенных, недопустимо.$B$BНо решать не мне, а сильным мира сего, которые хотят наделить тебя такими дарами.$B$BЕсли ты хочешь узнать побольше, советую поговорить с Менарой Расщепительницей Бездны из Кабестана. Обычно ее можно найти в башне над портом.', 'Поговорите с Менарой Расщепительницей Бездны в Степях.', 'А, тебя прислала Демизетта. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4739, 'Поиски Менары Расщепительницы Бездны', '$C! Да, ты!$B$BВижу, ты не полностью $gэкипирован:экипирована:, хотя уверенности и $gподнабрался:поднабралась:. Да-да, теперь я это понимаю.$B$BМенара Расщепительница Бездны научит тебя нескольким вещам. Она немало времени посвящает обучению молодежи тайным искусствам. Тем, кто проходит ее испытания, она даже дает дары.$B$BЕсли хочешь поучиться, ступай в город Кабестан в Степях. Она живет над городом в башне Страхада.', 'Поговорите с Менарой Расщепительницей Бездны в Степях.', 'А, тебя прислал Каэл. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4740, 'Разыскивается: Глубомрак!', 'Внимание!$B$BНазначена награда за голову мурлока, именуемого \"Глубомрак\". Эта злобная тварь повинна в смерти как минимум одного часового и подозревается в потоплении как минимум двух грузовых судов в прибрежных водах Темного Берега!$B$BГлубомрака в последний раз видели в поселении мурлоков к югу от Аубердина, и, судя по всему, он охраняет хижины своих сородичей. Награда за голову Глубомрака ждет смельчака у часового Глинды Нал\'Шии в Аубердине.$B$BСовет Аубердина', 'Найдите и убейте мурлока, известного как Глубомрак. Предполагается, что это существо охраняет и защищает хижины мурлоков в поселении к югу от Аубердина, у воды.О смерти Глубомрака доложите часовому Глинде Нал\'Шии в Аубердине.', 'Что ж, похоже, вы здесь не только затем, чтобы просто узнать! Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее.$B$BСегодня вы послужили для наших жителей орудием справедливости, $N. И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящего героя народа Аубердина.', NULL, NULL, NULL, 'Глубомрак убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4741, 'Одичавшие стражи', 'В северных областях Зимних Ключей дикие совухи совсем озверели. Необходимо положить этому конец!$B$BОтправляйся на охоту, а заодно исследуешь местность, где они обитают.$B$BМеста там дикие, но ты справишься. Возвращайся, когда убъешь 13 диких совухов.', 'По заданию Трулла Баловня Судьбы из Оскверненного леса убейте 13 осененных луной совухов.', 'Сдается мне, тебе нравится эта работенка. Думаю, мы стараемся не напрасно.', 'Только не говори мне, что струсил, отправляйся!', NULL, NULL, 'Осененный луной совух убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4742, 'Печать Вознесения', 'Видишь, в этой печати есть три простых углубления. В них надо вставить три камня власти; после этого властитель Змейталак, владыка нижней крепости, должен будет закалить печать в пламени черных драконов.$B$BНайди эти камни! И помни, $gсмертный:смертная:: шансы, что у кого-то из трех генералов нижней крепости будет при себе нужный нам камень, невелики. Не отступайся! Ищи, будь $gвнимателен:внимательна: и не теряй решимости!', 'Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваэлану вместе с простой печатью Вознесения.Камни могут быть у трех генералов: у воеводы Вуна из клана Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора.', '*Образ Ваелана на миг расплывается мутным пятном.*$B$B*Камни, которые вы принесли, исчезли.*$B$BТеперь все готово к тому, чтобы печать вознесения обрела свою силу. Пора приступать к завершающему этапу.', 'Мужество и терпение – залог успеха, смертный!', NULL, NULL, 'Самоцвет Черной Вершины', 'Самоцвет Тлеющего Терновника', 'Самоцвет Кровавого Топора', 'Простая печать вознесения');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4743, 'Печать Вознесения', 'Очень немногие черные драконы из верхней крепости способны закалить печать в пламени своего дыхания. Змейталак – один из них, но его волю сломить невозможно.$B$BТебе надо добраться до Драконьих топей в Пылевых топях. Там ты найдешь древнего дракона, известного под именем Огнебор. Ты $gдолжен:должна: сломить его волю, $N. И когда он ослабнет, тебе нужно будет воспользоваться этой сферой. Но помни, $gсмертный:смертная:: его разум силен, и ты сможешь удерживать его под контролем не более нескольких секунд. За эти секунды тебе нужно успеть закалить печать.', 'Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.Как только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати Вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку.', 'Стой спокойно. Я наложу последнее защитное заклинание.$B$B*Глаза Ваелана превращаются в два огненных шара.*$B$BТеперь печать Вознесения обрела свою полную силу...$B$BЯ вложил в артефакт очень мощные защитные чары. В минуту предельного отчаяния, когда тебе покажется, что все потеряно, призови силу красных драконов и используй ее для защиты.', 'Не теряй времени, смертный. Нефариан уже завершает последние приготовления. Если мы не остановим его сейчас, он обрушит на мир свою злобу.', NULL, NULL, 'Закаленная печать Вознесения', 'Подарок Ваэлана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4761, 'Тандрис Ветропряд', 'При разведке в лагере фурболгов вы обнаружили информацию, которую нужно довести до сведения Тандриса Ветропряда. Он любезно согласился исполнять обязанности старейшины в Аубердине, мудростью своей направляя повседневную жизнь деревни. Прошу вас поделиться с ним вашими находками в деле фурболгов.$B$BЯ уверен, что у него есть свои идеи по поводу источника наведенной на них порчи. Может быть, вы сможете вместе с ним выработать план восстановления природного равновесия!', 'Поговорите с Тандрисом Ветропрядом в Аубердине.', 'Рад нашей встрече, $C. Ваше расследование ситуации с фурболгами как нельзя кстати. Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведенной на сами леса. Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4762, 'Река Скалистая', 'Воды реки Скалистой исполнились злобы и порчи. Река впадает в Туманный предел, и я боюсь, что скоро беда затронет и Аубердин. Я подозреваю, что в загрязнении повинны фурболги Чернолесья, живущие в верховьях реки, но я также полагаю, что они не являются подлинной причиной этой порчи.$B$BВозьмите эту пробирку и отправляйтесь к устью реки, что к северу отсюда. Идите вверх по реке до первого водопада и там возьмите пробу воды. Ориентиром вам послужит высокий мост через реку. Когда возьмете пробу, вернитесь ко мне в Аубердин.', 'Отправляйтесь на север от Аубердина, к первому водопаду вверх по реке Скалистой, и там возьмите пробу.С пробой воды Скалистой реки возвращайтесь в Аубердин к Тандрису Ветропряду.', 'Я не удивлен тем, насколько сильно отравлена эта вода, но поглядите, какой мерзостной она становится! Похоже, что нужно действовать как можно скорее, да,$N? К востоку от нас находится Оскверненный лес; это и есть настоящий источник порчи, я в прошлом такой уже видел. Заранее могу сказать, что ваша проба подтвердит это. Наверное, мы могли бы найти средство для исцеления, но нам понадобится помощь, даже чтобы попытаться это сделать. Когда придет время, я надеюсь,$N, вы сможете нам ее предоставить.', 'Загрязнение реки Скалистой – лишь первое проявление тревожной тенденции здесь, на Темных берегах. Проба, которую вы добудете, поможет нам составить план... как я начинаю подозревать, план атаки.', NULL, NULL, 'Проба воды Скалистой реки', 'Пустая пробирка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4763, 'Порабощенные фурболги Чернолесья', 'Мы узнали, что источником порчи, наведенной на фурболгов, являются сатиры. Они держат своих жертв в повиновении с помощью талисманов, через которые направляют магию. Если для фурболгов еще есть шансы на спасение, мы должны выманить сатиров-поработителей и отнять у них талисманы!$B$BНаполни эту чашу из нашего лунного колодца и стащи образцы пищи фурболгов из их северного лагеря. Смешай все и поставь чашу возле большого костра у реки; любой фурболг, поевший из этой чаши, на некоторое время очистится, что привлечет внимание сатира... которого нужно убить!', 'Наполните пустую чашу очищения из лунного колодца Аубердина.Соберите образцы фруктов, орехов и зерна в расположенных на севере лагерях фурболгов.Смешайте все в чаше и поместите ее возле ближайшего к реке Скалистой большого костра в северном лагере, вызвав таким образом сатира.Снимите с него талисман порчи и принесите его Тандрису Ветропряду в Аубердин.', 'Мы только начали войну за освобождение наших лесов от порабощающих сил Скверны, но сегодняшняя битва выиграна! $N, народ Аубердина в огромном и почти неоплатном долгу перед вами. Прошу вас принять это вместе с нашей благодарностью. То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков.', 'Талисман Скверны – это жуткое приспособление, которое служит для нарушения природного баланса. Когда вы найдете этот предмет среди того, чем сатир мучает фурболгов, и принесете его мне для уничтожения, можно будет считать, что мы одержали великую победу!', NULL, NULL, 'Талисман порчи', 'Пустая чаша очищения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4764, 'Пряжка Роковой оснастки', 'Высоко в горах, на пике Черной горы, есть чертог, который некогда звался Залом Сокровищ. Именно там дворфы Черного Железа хранили свои реликвии, трофеи и предметы искусства.$B$BЭто было давно. Говорят, что зал обрушился, и теперь используется... менее достойно. Но я думаю, что там остались дворфийские реликвии.$B$BОдна из них – пряжка Роковой оснастки. Ее поверхность так плотно инкрустирована редкими самоцветами, что любой дворф начинает плакать от одного ее вида.$B$BИменно эта пряжка и станет твоей целью, $N.', 'Принесите пряжку роковой оснастки Майре Светлое Крыло в Пылающие степи.', 'Ты нашел ее! Значит, слухи оказались правдой!$B$BСпасибо, $N. Мой клиент, граф Ремингтон Риджвелл, с радостью поместит ее в свою коллекцию.', 'Ты принес пряжку, $N? Мой клиент готов хорошо за нее заплатить.', NULL, NULL, 'Пряжка Роковой оснастки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4765, 'Доставить Риджвеллу', 'Я упаковала пряжку Роковой оснастки в ящик для отправки в Штормград. $N, ты мне очень $gпомог:помогла:, но я хочу попросить еще об одной услуге.$B$BДоставь этот ящик графу Ремингтону Риджвеллу. Он в Крепости Ветров. Не сомневаюсь, он обрадуется.', 'Отнесите ящик Риджвелла Ремингтону Риджвеллу в Крепость Штормграда.', 'А, так это ты! Спасибо, $N. И... если ты еще не знаешь об этом... благодарность дома Риджвеллов стоит королевской.', 'Мне доложили о прибытии вестника. Вестника с даром с пика Черной горы.$B$BЭто ты?', NULL, NULL, 'Ящик Риджвелла (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4766, 'Майра Светлое Крыло', 'Мой агент, Майра, отправилась в Пылающие степи, чтобы обыскать развалины города Тауриссана. В разрушенном обиталище дворфов из клана Черного Железа таится множество ценных вещей... которые украсят наш семейный музей.$B$BМайара говорит, что кое-что нашла, но ей нужна помощь. Правда, это находится не в Тауриссане. Вместо этого требуется устроить вылазку на пик Черной горы.$B$BПодробности мне неизвестны, но если тебя заинтересовало мое предложение, поговори с Майрой в Пылающих степях.', 'Поговорите с Майрой Светлое Крыло на Дозоре Моргана в Пылающих степях.', 'Ты из Штормграда? Чудесно – я знаю об одном предмете искусства, который Ремингтон любой ценой захочет заполучить в свой музей. Но это будет нелегко.$B$BТут-то ты и понадобишься.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4767, 'Ветрокрыл', 'Мне велели набрать новых виверн, чтобы выдрессировать их и использовать в качестве ездовых животных. Их поголовье постоянно растет, и я надеюсь, что когда-нибудь сам смогу стать всадником на ветрокрыле. Однако виверны пользуются большим спросом, и нам их постоянно не хватает. Может быть, вы, $N, сможете мне помочь?$B$BЯ хочу попросить вас отправиться в Скальное гнездовье и набрать с кладок виверн немного яиц. Отсюда ступайте на северо-запад, держитесь поближе к стене каньона – и увидите дорогу, ведущую наверх. Но будьте очень осторожны: виверны не любят чужаков, а уж за свои кладки они будут готовы разорвать кого угодно.', 'Соберите в Скальном гнездовье 10 яиц виверн и отнесите их Элу на Заставу Вольного Ветра.', 'Отлично! Детеныши из этих яиц помогут мне осуществить задуманное! Возьмите это в знак моей признательности, пусть вам всегда везет на любой охоте, $C.', '$N, вы набрали для меня яиц виверн? Мне не терпится начать дрессировку моих новых ветрокрылов!', NULL, NULL, 'Яйцо виверны Скального гнездовья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4768, 'Табличка Темнокамня', 'Табличка Темного Камня – это записки покойного дворфа Урхельда Темного Камня. Он был величайшим алхимиком древности, но современники считали его сумасшедшим и не придавали значения его изысканиям.$B$BИзвестно, что он записал результаты своих трудов. Вырезал их на табличках. И у меня есть основания предполагать, что одна из этих табличек хранится в Пике Черной горы, в зале, который когда-то назывался залом Удачи. Как его называют сейчас, я не знаю, ибо многие уходили в Черную Скалу, но немногие вернулись назад.$B$BЕсли тебя не пугают опасности Пика Черной горы, принеси мне табличку, и я щедро тебя награжу.', 'Принесите табличку Темного Камня тенемагу Вивиан Лаграв в Каргат.', 'Превосходно. Для того чтобы разобраться со всеми формулами, мне потребуется не один день, но я уверена, что результат будет стоить затраченного труда.$B$BСпасибо, $N. Ты оказал нам поистине неоценимую услугу.', 'Тебе удалось разыскать табличку, $N? Мне не терпится приступить к изучению ее секретов.', NULL, NULL, 'Табличка Темного Камня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4769, 'Вивиан Лягроб и табличка Темнокамня', 'Вивиан Лягроб прислала мне весть из Каргата, что в Бесплодных землях. Она выяснила, что в Пике Черной горы хранится один древний текст, который может помочь нам в изысканиях. Однако это всего лишь догадка, требующая подтверждения. Нужно, чтобы кто-то добыл этот текст из Пика. Но сразу скажу: это будет непросто.$B$BЕсли возьмешься за эту работу, обратись к Вивиан в Каргат.', 'Переговорите с темным магом Вивианой Лягроб.', 'Верно. У меня есть основания предполагать, что в Пике Черной горы хранится табличка, на которой записаны древние алхимические рецептуры. Я рада, что ты обратился ко мне, ибо мне нужна помощь. Я должна получить эту табличку.$B$BСадись и устраивайся поудобнее, я сейчас объясню, что к чему.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4770, 'Путь домой', 'Пожалуйста, $C, помогите мне! Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица! Я пришел сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился.$B$BМне срочно нужно вернуться на заставу Белого Плеса! Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвет!$B$BЗастава прямо к востоку отсюда... пожалуйста, проводите меня туда!', 'Выведите Паоку Ходячую Гору из Скального гнездовья, а потом поговорите с Мотегой Огненной Гривой на заставе Белого Плеса.', 'Что?! Да если б я знал, что Паока Ходячая Гора полезет в Скальное гнездовье, я бы цепями приковал его к тотему! Его отец был против того, чтобы он ехал со мной в Тысячу Игл. Мы собирались изучать различных животных, населяющих эти прекрасные земли.$B$BЯ очень признателен вам за то, что вы помогли Паоке. Надеюсь, это покроет все ваши затраты.', NULL, NULL, NULL, 'Выведите Паоку из Скального гнездовья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4771, 'Рассветный гамбит', 'Я поместила рассветный гамбит в ящик, в котором были драконьи яйца. Ты $gдолжен:должна: отнести его в самую глубину Некроситета.$B$BВектус, маг из нежити, руководит группой студентов Плети. Доставь рассветный гамбит в комнату, которую они называют смотровой. Если все пойдет как надо, устройство уничтожит всю нежить, находящуюся в этот момент в комнате.$B$BПосле этого уничтожить Вектуса будет проще пареной репы. Так ведь?', 'Отнесите \"Рассветный гамбит\" в демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк.', 'Какое счастье! Вектус уничтожен! А \"Рассветный гамбит\", он сработал? $B$BВ самом деле? Ну... я, в общем-то, не сильно и надеялась... В общем, я рада, что ты справился, $N. $B$BСеребряный Рассвет, да и весь Азерот у тебя в долгу.', NULL, NULL, NULL, 'Вектус убито', 'Отнесите \"Рассветный гамбит\"', 'Рассветный гамбит', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4781, 'Материалы для зачарованного золотого кровавого одеяния', 'Следующее задание не сложнее первого, но тебе все равно потребуется помощь.$B$BДля вышивки мне нужна золотая нить, но ее не так просто найти, и мало кто знает, как ее делать. К счастью, этот секрет ведом одному из тех, кто верен нашему делу и старается помогать тем, кто стремится пополнить наши ряды.$B$BОтнеси золотой слиток Зиску Ладноскрою в Пиратскую Бухту. Он отличный портной и с радостью спрядет для тебя нить. Золотые слитки могут изготавливать опытные горняки. Обратись к ним.', 'Отнесите слиток золота Зиску Ладноскрою в Тернистую долину.', 'Великолепно. Я рад, что ты сумел так быстро заручиться помощью горняка. Или ты сам справился? Так или иначе, молодчина. Нить из этого слитка выйдет превосходная.$B$BНа ее изготовление понадобится время, поэтому возвращайся немного позже – честно говоря, я послал слиток одной принцессе, запертой в башне, которая только и делает, что прядет золотые нити... нет, честно. Я не шучу... ладно, шучу.', 'Да-да, золотые слитки. Принеси мне слиток, и тогда поговорим про нить. А пока я советую сосредоточиться на обучении. Самые суровые испытания еще впереди. Поверь, сколько ты ни занимайся, сколько ни копи силу, ее все равно будет не хватать.', NULL, NULL, 'Золотой слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4782, 'Материалы для зачарованного золотого кровавого одеяния', 'Возвращайся к Менаре и скажи ей, что работа предстоит долгая, но я постараюсь ради нее... и ради тебя. Передай ей, что пока ты собираешь остальные материалы, я закончу делать нить. Тогда ты придешь и заберешь ее.$B$BУдачи, $N. Ах, да, передай привет Страхаду, раз уж будешь рядом. Старый болван... как его угораздило построить башню рядом с Кабестаном?', 'Возвращайтесь к Менаре Расщепительнице Бездны в Степи.', 'Отлично, вот и ты, Эверек. А где же нитка?$B$BА, ясно. Понятно. Гоблин и его брат ни разу нас не подводили – думаю, вполне понятно, что он не смог сделать ее сразу. Да будет так... Тем временем мы займемся другими материалами.$B$BТы готов?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4783, 'Материалы для зачарованного золотого кровавого одеяния', 'Следующие материалы можно найти в Пустошах, далеко на западе от Степей, за Когтистыми горами.$B$BТам все еще царит хаос со времен Раскола. Это место, где предстоит серьезное испытание твоей силе и хитрости – там бродят омерзительные твари и приспешники Пылающего Легиона.$B$BПринеси мне кровь сатиров племени Ярой Ненависти, что обитают на северо-востоке, и простой камень Преисподней от младших инферналов Поля Маннорок.$B$BИ то, и другое понадобится для создания одеяния.', 'Принесите 10 фиалов крови сатира племени Ярой Ненависти и 1 простой камень Преисподней в Степи, Менаре Расщепительнице Бездны.', 'Великолепно, $N. Отличные материалы. Я пока подготовлю их, а тебе дам другое задание: принести два оставшихся ингредиента. Готов?', 'Пустоши – опасное место: наги, гиганты, сатиры, Пылающий Легион... И вдобавок ко всему еще и воинственные кентавры.$B$BЯ уже говорил, что это подвергнет испытанию не только твою силу и ловкость, но и терпение. Не теряй бдительности, $N.', NULL, NULL, 'Фиал крови сатир племени Ярой Ненависти', 'Камень младшего инфернала', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4784, 'Материалы для зачарованного золотого кровавого одеяния', 'Осталось отыскать три составляющих, $N, и твое одеяние будет готово.$B$BВо-первых, нить из чистого золота, которую делает Зиск. Отправляйся к нему в Пиратскую Бухту и принеси нить.$B$BВо-вторых, нужны тлеющие угли элементалей огня с нагорья Арати. Если я правильно помню, духов можно найти в западной части нагорья, рядом со стеной Торадина.$B$BИ, наконец, мне нужен осколок души, созданный тобой.$B$BСобрав все составляющие, возвращайся в башню, и я закончу работу над одеянием.', 'Принесите Менаре Расщепительнице Бездны в Степи нить из чистого золота, 2 тлеющих угля и осколок души.', 'Великолепно, $N! Все материалы у меня есть, можно приступать.$B$BДумаю, ты будешь доволен.', 'Осталось недолго, $N, честное слово. Одеяние неплохо послужит тебе и даст преимущество над противниками.', NULL, NULL, 'Нить из чистого золота', 'Тлеющий уголь', 'Осколок души', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4785, 'Нить из чистого золота', '', '', 'Вот, бери. И пожалуйста, передай от нас привет Менаре.Мы ждем от тебя великих свершений. Быть может, когда Легион падет на колени, прозвучит твое имя и хвала твоей силе. Жду не дождусь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4786, 'Завершенное одеяние', 'А теперь я завершу работу над одеянием. Это займет немного времени. Не уходи далеко.', 'Дождитесь, пока Менара Расщепительница Бездны закончит работу над вашим одеянием, и еще раз поговорите с ней.', 'Готово. Прими это одеяние и носи его с честью.$B$BТы хорошо поработал, и я предвижу, что тебя ждут великие дела. Помни: чтобы справиться с искушением скверны, которое подстерегает каждого, ступившего на путь магии, понадобится сильная воля и немалая стойкость. Пока ты не лишился воли, тебя ждут великие успехи.', NULL, NULL, NULL, 'Дождитесь, пока Менара Расщепительница Бездны закончит работу над избранным предметом.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4787, 'Древнее яйцо', 'В пророчестве Мошару говорится о древнем яйце. Это реликвия тех времен, когда тролли правили громадными империями, и в нем заключена сила, которая сможет сдержать сущность Хаккара. Пожалуй, это единственный способ избавить наш мир от зла.$B$BПринеси мне древнее яйцо, $N. Говорят, оно спрятано в Джинта\'Алоре, что во Внутренних землях, в пещере за амфитеатром в верхней части города.', 'Принесите древнее яйцо Йе\'кинье в Танарис.', 'А, ты добыл яйцо! Низкий тебе поклон, $N. Твоя сила и храбрость будут воспеты в веках.', 'Ты несешь древнее яйцо? Я чувствую, как просыпаются великие силы. Боюсь, время у нас на исходе.', NULL, NULL, 'Древнее яйцо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4788, 'Последние таблички', 'Пока я изучаю третью и четвертую таблички Мошару, отыщи пятую и шестую! Это будет нелегко, потому что они в руках троллей из клана Тлеющего Терновника на пике Черной горы. Этот пик – огненная гора между Пылающими степями и Тлеющим ущельем.$B$BУдачи, $N. Она тебе понадобится.', 'Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе.', 'Невероятно! Ты их нашел! Ты настоящий герой, $N!$B$BИ это очень удачно, потому что судя по предыдущим табличкам... без героя нам не обойдтись. Грядет такое...', 'Ты уже добрался до Черной Скалы? Пятая и шестая таблички у тебя?', NULL, NULL, 'Пятая табличка Мошару', 'Шестая табличка Мошару', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4801, 'Э\'ко ледопардов', '', '', 'Да, $N, Мау\'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау\'ари на себе или на своих союзниках.', NULL, NULL, NULL, 'Э\'ко ледопардов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4802, 'Э\'ко фурболгов племени Зимней Спячки', '', '', 'Да, $N, Мау\'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау\'ари на себе или на своих союзниках.', NULL, NULL, NULL, 'Э\'ко фурболгов племени Зимней Спячки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4803, 'Э\'ко щербозубов', '', '', 'Да, $N, Мау\'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау\'ари на себе или на своих союзниках.', NULL, NULL, NULL, 'Э\'ко щербозубов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4804, 'Э\'ко хладнокрылов', '', '', 'Да, $N, Мау\'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау\'ари на себе или на своих союзниках.', NULL, NULL, NULL, 'Э\'ко хладнокрылов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4805, 'Э\'ко йети', '', '', 'Да, $N, Мау\'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау\'ари на себе или на своих союзниках.', NULL, NULL, NULL, 'Э\'ко йети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4806, 'Э\'ко великанов', '', '', 'Да, $N, Мау\'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау\'ари на себе или на своих союзниках.', NULL, NULL, NULL, 'Э\'ко великанов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4807, 'Э\'ко диких совухов', '', '', 'Да, $N, Мау\'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау\'ари на себе или на своих союзниках.', NULL, NULL, NULL, 'Э\'ко диких совухов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4808, 'Фелнок Сталлист', 'Мне придется попросить тебя еще об одной услуге.$B$BВ результате исследования добытых тобой сущностей, я поняла, как можно заморозить яйца драконов и сохранить их! Мне нужно испытать собственную теорию, но первым делом понадобятся кое-какие приспособления. Мой коллега, Фелнок Сталлист, умеет их делать.$B$BОтнеси это письмо Фелноку и объясни ему, что мне нужно. Фелнок живет в городе Круговзоре, в Зимних Ключах.', 'Отнесите письмо Тинки Фелноку Сталлисту в Круговзор, что в Зимних Ключах.', 'Это не одеяло! Что это? Письмо от Тинки? И что она пишет?..$B$BА, она занимается исследованиями в Пылающих степях. В этом есть смысл – драконов там полно. Смотри-ка, ей нужны кое-какие детали для создания одного устройства. Вот зачем я ей понадобился, а?', 'Как здесь холодно! Надеюсь, ты принес мне одеяло!', NULL, NULL, 'Письмо Тинки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4809, 'Рога хладнокрылов', 'У меня есть почти все, что нужно Тинки, не хватает только одного важного компонента – рогов хладнокрылов. Рога этих химер – великолепный источник стужи, но годятся только безупречные рога без единой трещинки! Чтобы выполнить заказ Тинки мне нужно несколько таких рогов.$B$BДобудь их, и я соберу посылку для Тинки.', 'Добудьте 8 безупречных рогов хладнокрыла.', 'Отличные рога. Прямо средоточие холода! Дай-ка я надену перчатки и упакую их вместе с остальным заказом Тинки...', 'Ты несешь мне рога стылодыхов, $N?', NULL, NULL, 'Безупречный рог хладнокрыла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4810, 'Возвращение к Тинки', 'Ну вот, все готово и запаковано! Доброго пути, не забудь передать Тинки, что она мой должник!', 'Отнесите ящик Фелнока Тинки Кипеллер в Пылающие степи. Ее можно найти возле Пламенеющего Стяга.', 'Принес! Ура! Я немедленно примусь за работу! Огромное спасибо, $N!$B$BТы очень мне помог, может быть я снова прибегну к твоей помощи...', '$N! Ты поговорил с Фелноком? Ты принес, то что я просила?', NULL, NULL, 'Ящик Фелнока (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4811, 'Красный кристалл', 'К востоку отсюда становится все больше враждебно настроенных лунных совухов. Когда-то их считали милыми и спокойными, почти мистическими созданиями. В то время как кое-кто продолжает почитать их, тревога о безопасности Аубердина вынуждает меня смотреть на вещи более реалистично.$B$BЯ получила сообщения, что лунных совухов привлекает большой красный кристалл, находящийся в горной гряде на востоке Темного Берега. Никто не только не знает, что это за кристалл, но есть ли он на самом деле. Я хочу, чтобы вы установили его местонахождение и доложили мне о том, что обнаружите.', 'Направляйтесь на восток от Аубердина и поищите большой красный кристалл в горной гряде на востоке Темных берегов. Вернитесь с докладом к часовому Глинде Нал\'Шие в Аубердин.', 'Так значит, кристалл существует, $N? Как интересно... В любом случае, вы хорошо справились с заданием; отличная работа!$B$BА какова же природа этого кристалла? Это лишь один вопрос в целом море вопросов... На ум мне приходит и другой: почему лунных совухов тянет к кристаллу? Он безвреден, или же таит в себе зло?$B$BУ меня еще много вопросов, но нам придется пристально изучить кристалл, чтобы добиться хоть каких-то ответов.', NULL, NULL, NULL, 'Исследовать локацию', 'Найти большой красный кристалл на восточном хребте Темных берегов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4812, 'Пока струится вода...', 'Возьмите эту пустую колбу и наполните ее водой из лунного колодца в Аубердине. Ее могучая магия должна помочь нам разгадать структуру кристалла. Чтобы это сделать, просто облейте кристалл, а остальное должно произойти само собой.$B$BХотя я не думаю, чтобы вам что-то угрожало, я все же попрошу вас быть осторожнее. За горами на востоке находится Оскверненный лес, и если этот кристалл как-то связан с тем местом (как я подозреваю), он может оказаться очень опасным.', 'Наполните пустую колбу для воды в лунном колодце Аубердина, а затем исследуйте красный кристалл, находящийся в горной гряде на востоке Темного Берега.', 'Вы снова добрались до таинственного кристалла. Откупорив флакон с водой лунного колодца, вы аккуратно выливаете его содержимое на верхушку кристалла. Пока вода струится по его граням, вы видете, как непроглядная поверхность кристалла становится прозрачной...', 'На фоне лесного пейзажа Темного Берега кристалл выглядит совершенно чужеродным. Вам кажется, что откуда-то изнутри кристалла до вас доносится чуть слышное жужжание.', NULL, NULL, 'Колба для воды из лунного колодца', 'Пустая колба для воды', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4813, 'Скрытые фрагменты', 'С помощью воды Лунного колодца выяснилось, что в кристалле заключено несколько мелких фрагментов костей, а также половина челюсти. Кажется, челюсть принадлежала гуманоиду, но точно нельзя сказать, не разбив кристалл, – а это даже для самой мощной магии может оказаться почти непосильной задачей.$B$BЗадание выполнено, и все, что вам остается, – это вернуться в Аубердин и доложить обо всем часовому Глинде Нал\'Шие.', 'Доложите о результатах ваших изысканий часовому Глинде Нал\'Шие в Аубердине.', 'Да, похоже, что, хотя мы и знаем теперь о кристалле больше, в результате возникло множество новых вопросов.$B$BЯ пойду с добытой вами информацией в совет Аубердина. Может быть, они подскажут, что делать дальше с этим кристаллом. Если вообще есть о чем говорить – пока что угроза слишком далеко на востоке, чтобы принимаеть ее всерьез.$B$BЧто же касается вас, возьмите это. Считайте это наградой за хорошо проделанную работу, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4821, 'Странное яйцо', 'Ходят слухи, что здесь, в Тысяче Игл, появилось яйцо какого-то странного существа. Но те, кто видел его, не смогли подойти достаточно близко и рассмотреть яйцо поподробнее. Его охраняют змеи, да так, словно это яйцо – их собственное!$B$BЯ хочу, чтобы вы нашли его и принесли мне для изучения. Говорят, что оно находится в логове змеев, но вообще-то таких гнезд несколько, они разбросаны вдоль стен каньона к югу и северо-востоку от заставы.', 'Принесите странное яйцо Хагару Грозовому Копыту на Заставу Вольного Ветра.', 'Наконец-то я получил это таинственное яйцо... Дайте-ка взглянуть на него... Что... что это?!', 'Мне нужно узнать побольше об этом таинственном яйце. Кто знает, что может из него вылупиться...', NULL, NULL, 'Странное яйцо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4822, 'Женщинам – цветы, детям – ...', 'Мороженое! Пожалуйста-пожалуйста-пожалуйста, добудь для меня немного мороженого!!! Я больше всего люблю клубничное, а самое лучше клубничное мороженое делает Тигуль! Это мое самое любимое мороженое на свете!$B$BЯ пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе! Пожалуйста! Пожалуйста-препожалуйста! Преогромное пожалуйста!!!!', 'Купите своему подопечному клубничное мороженое. Кажется, мальчик предпочитает мороженое Тигуля.', '', NULL, NULL, NULL, 'Клубничное мороженое Тигуля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4841, 'Упокоение кентавров', '$N, я поручаю вам охоту на этих кентавров. Отомстите им за нас как следует – вырежьте весь их лагерь к северу от Заставы Вольного Ветра. Пусть рука ваша будет тверда!', 'Убейте 12 разведчиков, 10 пастухов и 6 ветроловок из племени Галак, после чего вернитесь к дозорному утесов Долгорогу на Заставу Вольного Ветра.', 'Примите это в благодарность от меня, $N.', 'Роггин, вы убили слишком мало кентавров! Продолжайте охоту, а уж я в долгу не останусь.', NULL, NULL, 'Разведчик из племени Галак убито', 'Пастух из племени Галак убито', 'Ветроловка из племени Галак убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4842, 'Выяснение причин', 'По правде говоря, хотя в Зимних Ключах вулканов нет, я думаю, для возникновения этих горячих источников есть не менее опасные причины…$B$BВпрочем, наверное, ты $gсам:сама: захочешь все увидеть. Тебе нужно будет пересечь все Зимние Ключи, до самого юга этого края. Там, где воздух станет плотным и удушливым, а небо потемнеет, ты как раз и найдешь то, что я считаю причиной возникновения горячих ключей.$B$BСходи взглянуть. Я уверена, ты вернешься с кучей вопросов.', 'Последуйте указаниям Доновы Снегоноры, а затем вернитесь к ней.', 'Да, демоны добрались до Теснины Зловещего Шепота. Я уверена, мы наблюдаем следы их присутствия. И я собираюсь и дальше наблюдать на горячими ключами, чтобы узнать о них больше.$B$BЯ немного подожду, чтобы ты набрался сил, а потом снова привлеку тебя к исследованию Теснины Зловещего Шепота.', 'У воды в ключах очень странные свойства… я по-прежнему не очень понимаю, что все это значит…', NULL, NULL, 'Исследовать локацию', 'Отыщите Теснину Зловещего Шепота.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4861, 'Взбесившиеся дикие совухи', 'Эй, послушай, $gпаренек:девчушка:! Меня какие-то кровожадные дикие совухи гнали всю дорогу из моего лагеря! Подозреваю, я слишком близко подобрался к разгадке того, что же они там охраняют. $B$BЯ еле ноги унес оттуда. Боюсь, мой коллега оказался менее везучим. Ты как, не против того, чтобы бросить вызов диким совухам и отправиться в мой лагерь? Мне очень нужны мои припасы, а также я хотел бы вернуть амулет, который извлек вчера во время раскопок.', 'Найдите разоренный лагерь Джерона Гранильщика и его припасы на юге Зимних Ключей.', 'Среди разрушенных пожитков в лагере находится и сильно потрепанный ящик.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4862, 'Товар на любителя', 'Верь – не верь, но есть народ, который готов отлично заплатить за необычную зверушку, причем чем она злее, тем лучше!$B$BЯ послал на пик Черной горы Блестяшку, чтобы собрать паучьи яйца, но она уже несколько недель не возвращается. Может, ты придешь ей на выручку?$B$BВот что, $N. Ступай-ка туда и принеси мне паучьи яйца. Я тебе не только хорошо заплачу, но еще и приручу для тебя одного паучка!', 'Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука.Судя по всему, яйца надо искать недалеко от пауков.', 'Какой урожай! Что за яйца! Они принесут мне несколько хорошеньких золотых монеток.$B$BКак и обещано, вот тебе зверушка. Смотри, чтобы она тебя не цапнула!', 'У тебя в сумке лежат паучьи яйца или ты так, поболтать, зашел?', NULL, NULL, 'Яйцо скального паука', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4863, 'Взбесившиеся дикие совухи', 'Вы озираетесь, но видите ничего такого, чтобы могло понадобиться Джерону. Однако, заметно, что найденный вами ящик был вскрыт силой, как будто тут побывали дикие совухи...$B$BВзглянув на восток, вы замечаете покинутый фургон. Стоит посмотреть не осталось ли там каких-то вещей Джерона.', 'Найдите опрокинутый фургон Джерона Гранильщика.', 'Подойдя к фургону, вы думаете о том, что едва ли внутри осталось что-то полезное для Джерона. Однако, приглядевшись, вы замечаете в снегу возле фургона пару ящиков, которые выглядят неповрежденными.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4864, 'Взбесившиеся дикие совухи', 'Изучив содержимое ящика, вы решаете, что Джарону могут пригодиться лежащие там инструменты. Однако среди них нет и следа амулета.$B$BПохоже, дикие совухи обитают к северу и к востоку отсюда, и вы решаете, что ваш следующий шаг – встретить этих существ лицом к лицу и забрать у них амулет.', 'Подберите припасы Джерона из снега, и найдите дикого совуха, похитившего амулет, о котором говорил Джерон.Принесите припасы и ожерелье миних перьев Джерону Гранильщику в его дом в Зимних Ключах.', 'Ну, примерно это я и ожидал услышать, парень. Я уж было думал, что свихнувшиеся звери раздраконили все мои пожитки… $B$BНо тебе удалось найти мои инструменты и, что еще важнее, амулет! Интересно, почему дикие совухи так яростно его защищали… В любом случае, я теперь дважды подумаю, прежде чем сунуться к ним опять!', 'Привет… Расскажи-ка, какие новости?', NULL, NULL, 'Припасы Джерона', 'Амулет Синего пера', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4865, 'Змеиная дикость', 'Если бы я не видел это собственными глазами, то ни за что бы не поверил! Месть обрушилась на Тысячу Игл!$B$B*Хагар утирает лоб.*$B$B$N, надо действовать быстро! Скорее, иди и поговори с Мотегой Огненной Гривой, он на заставе Белого Плеса, это к северо-западу отсюда, прямо возле дороги. Он подскажет нам, что делать!', 'Расскажите о найденном Мотеге Огненной Гриве на Заставе Белого Плеса, что в Тысяче Игл.', 'Отмщение! Значит, легенда об Арикаре не врет! Да, эту проблему следует разрешить немедленно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4866, 'Материнское молоко', 'Должно быть, это один из сильнейших ядов на свете!$B$BВо время одной из вылазок на пик Черной горы я слышал, как орки говорят о его смертоносности. Они называют его \"материнское молоко\" в честь Дымной Паутины, огромной паучихи, поселившейся в одной из пещер Лабиринта.$B$BИ вот что мне нужно от тебя: образец молока из твоих собственных вен. Ядовитая железа не подойдет! Поэтому дай ей отравить себя, а потом возвращайся!$B$BА я тебя... подою!$B$B<Потирает руки в нетерпении.:', 'Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд.', 'Из этого выйдет потрясный эль!$B$BА ты что думал? Что я сделаю яд или что-то такое?$B$BНу, дети пошли...', '*Джон-Оборванец щипает вас.*', NULL, NULL, 'Вас подоили', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4867, 'Аррок Смертный Вопль', 'Ар-рх! Трудно говорить!$B$BВозьми эту записку! Принеси мне мой амулет!', 'Прочитайте записку Вароша. Принесите Варошу его амулет.', 'Я уже чувствую, как ко мне возвращаются силы! И проклятие Аррока уже не разрушает мой разум.$B$BСпасибо, $N! Я не люблю быть кому-то обязанным, но должен признать: ты мне очень помог.$B$BЖелаю удачи в походе на Пик Черной горы. Это безрассудство, если ты думаешь, что сможешь дойти до вершины, хотя твоя смелость поистине не знает границ.', 'А, вот и ты! Ты принес мой амулет?', NULL, NULL, 'Амулет Вароша', 'Свиток Вароша', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4881, 'Убийственный заговор', 'Таурен по имени Канати Серое Облако собрался разбить в Тысяче Игл охотничий лагерь. Мы должны убить его и опустошить лагерь, уничтожив всех его сторонников. Собираемся на маленькой заставе к юго-западу от Великого подъемника.', 'Предупредите Канати Серое Облако на заставе Белого Плеса, что на него готовится покушение.', 'Они хотят меня убить? Пусть приходят, я покажу им, как дерутся таурены!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4882, 'Умение хранить секреты', 'Вы не можете понять, важна ли ваша находка – ожерелье, упавшее с шеи недавно убитого дикого совуха. Оно источает яркий пульсирующий свет.$B$BМожет быть, Трулл Баловень Судьбы сможет что-то рассказать – похоже, он очень много знает о диких совухах. Возможно, стоит его расспросить об этом ожерелье?', 'Отнесите ожерелье синих перьев Труллу Баловню Судьбы на заставу Отравленной Крови.', 'Важная находка?', 'Хотите еще о чем-то сообщить?', NULL, NULL, 'Ожерелье Синих перьев (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4883, 'Умение хранить секреты', 'Хотя я располагаю некоторыми сведениями о совухах, с которыми ты $gборолся:боролась: в Зимних Ключах, однако об их магии мне ничего не известно. Но я знаю кое-кого, кто с удовольствем изучит это ожерелье и скорее всего сумеет рассказать тебе о его свойствах.$B$BНара Буйногривая из Громового Утеса настоящий эксперт в подобных вещах, тебе стоит поговорить с ней. Удачи, $N!', 'Отнесите ожерелье синих перьев Наре Буйногривой.', 'Полагаю, у энергии этого ожерелья лишь один источник, $N.$B$B*Нара закрывает глаза и замолкает на мгновение.*$B$BДикосовухи, обманутые и испуганные существа, не всегда были такими. Они были созданы для того чтобы служить ночным эльфам. Богиня ночных эльфов Элуна сотворила их, чтобы охранять священные места.$B$BКонечно, это кажется неважным, однако я призываю тебя взглянуть глубже.$B$BВ свое время ты поймешь. Спасибо, что принес мне это ожерелье, $N.', 'Чем я могу помочь тебе, $N?', NULL, NULL, 'Ожерелье Синих перьев (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4901, 'Стражи алтаря', 'На самой вершине гребня находится, как я полагаю, алтарь богини Элуны. Насколько я знаю, нам нужно зажечь пять факелов – в каждой пещере, и тогда мы получим доступ к алтарю.$B$BЯ расшифровала заклинания, вырезанных на камне в древних руинах Кел\'Терила, которые, как я думаю, являются ключом к активации алтаря. Помогите мне зажечь факелы, пока я буду читать заклинание.$B$BЕсли у нас все получится, вы сможете доложить Эреласу о результатах!', 'Защитите Раншаллу, пока она пытается активировать алтарь Элуны. Сообщите о ваших находках Эреласу Янтарному Небу в деревне Рут\'теран.', 'Вы виделись с Раншаллой?', NULL, NULL, NULL, 'Раскройте секрет алтаря Элуны.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4902, 'Питомцы Элуны', 'Это поразительно!$B$BМне всегда было интересно, какова же истина… Что ж, вы просто обязаны поделиться этими сведениями! Сразу же отправляйтесь к верховному друиду Фэндралу Оленьему Шлему – вы найдете его в Дарнасе, в Круге Кенария. Расскажите ему подробно о случившемся – так же, как рассказали мне. Я уверен, что ему будет очень интересно!$B$BЭто важная информация, $N!', 'Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.', 'Не ходите вокруг да около, рассказывайте, с чем пришли.$B$BАх, вот как? Хмм… Ясно.$B$BСпасибо, что сразу пришли с этим ко мне; докладывать все на самый верх – самое правильное… Но… Да. Друиды Круга Кенария знают о дикосовухах уже довольно давно. О том, что они – питомцы Элуны и были избраны охранять наиболее священные места.$B$BВ общем, хоть это для нас и не новость, я, безусловно, признателен вам за ваши усилия. Вот, возьмите это – думаю, это подходящая награда за ваши труды.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4903, 'Приказ полководца', 'По приказу полководца Клинозуба следующие жители Пика Черной горы подлежат уничтожению: $B$BОсобо опасный преступник вождь Омокк. $B$BЖестокий и беспощадный тролль воевода Вун.$B$BПовелитель Змейталак, десятник в малом городе.$B$BТакже необходимо доставить в штаб все найденные при них документы. $B$BУспех – слава и награда.$B$BПоражение – позор и забвенье.', 'Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат.', '*Зеленые щеки полководца на минуту покрываются мертвенной бледностью.*', '*Полководец Клинозуб берет под козырек*.', NULL, NULL, 'Властитель Змейталак убито', 'Вождь Омокк убито', 'Воевода Вун убито', 'Важные бумаги Черной горы');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4904, 'Долгожданная свобода', 'Арнак хотел жениться на мне, и поэтому похитил меня, когда я отвергла его предложение. Мой брат пытался остановить его, но Арнак оказался сильнее. Он... он убил моего брата и привел меня сюда. Мой бедный брат...$B$B$N, не могли бы вы вывести меня с Пика Темного Облака? Я хочу назад, к Талье! Она, наверное, с ума сходит от беспокойства.', 'Выведите Лакоту Песню Ветра с Пика Темного Облака, а потом поговорите с Талией Янтарной Шкурой на Заставе Вольного Ветра.', 'Спасибо, $N. В глубине души я всегда верила, что она найдет способ вернуться ко мне. Она рассказала мне о вашей храбрости и о том, как вы помогли ей сбежать. Эти вещи принадлежали ее брату. Уверена, она бы сама непременно отдала их вам.', NULL, NULL, NULL, 'Выведите Лакоту Песню Ветра с Пика Темного Облака.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4906, 'Снова порча!', 'Другой лагерь сатиров угрожает северной части Оскверненного леса. Тамошними сатирами предводительствует жестокий Ксаварик. Эти подлые предатели и обманщики радуются, поражая порчей тварей Оскверненного леса.$B$BКсаватрас и его приспешники – только часть большого плана по созданию оскверненного лунного колодца. А затем всем этим воспользуется Ксаварик.$B$BТеперь, когда Ксаватрас уже не мешается у нас под ногами, заверши это дело, $N. Отправляйся на север и срази Ксаварика.', 'Эридана Грусть Ветра из Оскверненного леса просит вас убить 8 призывателей Пламени, 8 предателей и 8 плутов из племени Нефритового Пламени, а также Ксаварика. По выполнении задания возвращайтесь к Эридане.', 'Спасибо за все, что ты сделал, $N. Да защитит тебя Элуна, и да направит она твой путь.', NULL, NULL, NULL, 'Призыватель огня из племени Нефритового Пламени убито', 'Предатель из племени Нефритового Пламени убито', 'Плут из племени Нефритового Пламени убито', 'Ксаварик убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4907, 'Тинки Кипеллер', 'Привет, $N. Помнишь Тинки Кипеллер? Она-то тебя помнит! Она послала мне весточку, чтобы я передал тебе при случае. Ей снова нужна твоя помощь. Кажется, это опять связано с изучением драконов.$B$BСтупай в Пылающие степи, в Пламенеющий Стяг, и поговори с ней.', 'Поговорите с Тинки Кипеллер. Ее можно найти возле Пламенеющего Стяга в Пылающих степях.', 'Фелнок не ошибся! Мне снова нужна твоя помощь, и на сей раз... задание будет опасным.$B$BТы готов?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4921, 'Пропавшая без вести', 'Мы бились в маленьком лагере тауренов и разделились в бою – на нее наседали разом трое дыбогривов. Силы были неравны. Я отвлек на себя очень многих и увидел, что набежали новые враги и одолевают ее. Впав в ярость, я бросился на врагов, но они с легкостью одержали надо мной верх.$B$BЯ пришел в себя и увидел, что таурен-друид ухаживает за мной, – он набрел на меня на Золотом пути.$B$BПрошу тебя, $C, узнай что-нибудь о моей жене.', 'Отыщите жену Манкрика и возвращайтесь к нему в Перекресток.', 'Понятно. Спасибо, $C.', NULL, NULL, NULL, 'Найдите жену Манкрика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4941, 'Мудрость Эйтригга', 'Ренд жив? $B$BБыть того не может! Я думал, он погиб несколько десятков лет назад. $B$BТебе нужно обратиться за советом к Эйтриггу, $N! Никто не знает о Черной горе больше него, и если то, что написано здесь, правда, Эйтриггу стоит об этом знать. Никому нельзя отказывать в праве на месть. $B$BКогда поговоришь с Эйтриггом, ступай к вождю за указаниями.', 'Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу. В последний раз Эйтригг был в в зале приемов Тралла.', '*Тралл, похоже, весьма встревожен услышанным.*', 'Зачем явился? Я занят!', NULL, NULL, 'Совет с Эйтриггом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4961, 'Очищение шара Орахила', 'А, сфера призывателя – так вот откуда исходит искажение. Если ты хочешь ей пользоваться, придется изгнать из нее демона. С этим я легко справлюсь.$B$BТебе придется куда труднее. Как только демон выйдет из сферы, убей его.$B$BИ спеши. Если ты будешь возиться слишком долго, он вернется в сферу, и нам придется начать сначала!$B$BПодготовься к схватке, $N. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелегким.', 'Убейте демона сферы, а потом поговорите с Табетой.', 'Великолепно, $N. Тебе удалось преподать этому демону урок, который он надолго запомнит. Могущества и умения тебе не занимать. Полагаю, пришло время вернуться к Менаре с очищенным шаром и найти ему доброе применение.$B$BУдачи, $C. Быть может, наши пути еще пересекутся.', NULL, NULL, NULL, 'Демон сферы убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4962, 'Осколок гончей Скверны', 'Итак, ты $gвыбрал:выбрала: гончую скверны. Отлично.$B$BВозьми этот рубин, он позволит подчинить ее душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он все сделает за тебя.$B$BСоветую отправиться в Пустоши и попробовать подчинить одну из тамошних гончих скверны. Они отлично подойдут.$B$BКогда добьешься успеха, отнеси плененного духа и рубин Менаре.', 'Возьмите рубин Сквернолова и поймайте в него одну из гончих скверны в Пустошах. Добившись успеха, отнесите плененный дух Гончей Скверны и рубин Сквернолова Менаре Расщепительнице Бездны из Степей.', 'А, дух гончей скверны. Молодец, $N;.$B$BКогда у меня будет и дух, и очищенная сфера, я смогу слить их воедино, но не раньше.', 'Да, $N? Ты сделал выбор? Инфернал или гончая скверны?$B$BЧасто чернокнижники предпочитают усиливать сильные стороны, а не развивать слабые. Порой лучше научиться чему-то одному, чем стать разносторонним заклинателем.', NULL, NULL, 'Рубин Сквернолова (Прилагается)', 'Плененный дух Гончей Скверны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4963, 'Осколок инфернала', 'Итак, ты $gвыбрал:выбрала: инфернала. Отлично.$B$BВозьми этот изумруд, он позволит подчинить его душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он все сделает за тебя.$B$BСоветую отправиться в Пустоши и попробовать подчинить одного из инферналов. Они отлично подойдут.$B$BКогда добьешься успеха, отнеси плененного духа и изумруд Менаре.', 'Возьмите Пылающий изумруд и поймайте в него одного из инферналов в Пустошах. Добившись успеха, отнесите плененный дух инфернала и пылающий изумруд Менаре Расщепительнице Бездны из Степей.', '', NULL, NULL, NULL, 'Пылающий изумруд (Прилагается)', 'Плененный дух инфернала', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4964, 'Завершение шара Дар\'орахила', 'Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять свое мнение.', 'Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар\'орахила, и еще раз поговорите с ней.', 'Готово. А теперь скажи, что ты предпочитаешь,: посох, который займет обе руки, или шар, который позволит тебе пользоваться кинжалом или мечом.$B$BСражение с огненным големом – суровое испытание. Нет сомнений, что этот предмет славно послужит тебе в будущем. Прилежно изучай тайные искусства, $N. Я буду ждать вестей о твоих подвигах.', NULL, NULL, NULL, 'Дождитесь, пока Менара Расщепительница Бездны закончит работу над избранным предметом.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4965, 'Знание шара Орахила', 'Так-так-так… приятно видеть, как ты набираешься могущества, $N. Мне кажется, ты $gготов:готова: поговорить с Менарой Расщепительницей Бездны в Степях. Если вы раньше не встречались, то, поверь мне, другого такого специалиста по созданию предметов – особенно сфер, в которые можно заключить демона – не найти.$B$BИнтересно? Тогда поищи ее. Она живет в башне Страхада над Кабестаном.', 'Поговорите с Менарой Расщепительницей Бездны в Степях.', 'А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.$B$BПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.$B$BИтак, думаешь, ты готов, $N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4966, 'Защитить Канати Серое Облако', 'Кентавров намного больше, чем я думал, $N. Пожалуйста, помогите мне отбиться от них.', 'Защитите Канати Серое Облако от нападения кентавров.', 'Спасибо за помощь, $N. Без тебя я бы ни за что не справился.', NULL, NULL, NULL, 'Защитить Канати Серое Облако', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4967, 'Знание шара Орахила', 'Ты так и не $gпоумнел:поумнела: и по-прежнему стремишься в западню. Да, говорю я дерзко. Я смотрю на тебя и смеюсь. Ты жалкий червь!$B$BНо мое мнение не имеет значения. Главное, что думают те, кто желает иметь с тобой дело! И в данном случае наделенные силой полагают, что ты заслуживаешь большего.$B$BЕсли ты к чему-то стремишься, поговори с Менарой Расщепительницей Бездны в башне над Кабестаном. Кажется, ты с ней уже $gвстречался:встречалась:.', 'Поговорите с Менарой Расщепительницей Бездны в Степях.', 'А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.$B$BПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.$B$BИтак, думаешь, ты готов, Назран?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4968, 'Знание шара Орахила', 'Хм-м... Тебе удалось добиться немалого... Поразительно. Я думала, что ты давно $gсошел:сошла: с ума, $gраздираемый:раздираемая: скверной магией, просочившейся в твою душу. Тогда, пожалуй, двинемся дальше?$B$BЕсли ты хочешь испытать свое искусство, отыщи Менару Расщепительницу Бездны в башне Страхада над Кабестаном. Она поможет тебе сделать следующий шаг.', 'Поговорите с Менарой Расщепительницей Бездны в Степях.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4969, 'Знание шара Орахила', 'Ха-ха! Ты растешь над собой, $gюный:юная:c: $C.$B$BСо временем инферналы и повелители ужаса склонятся перед тобой!$B$BПока же тебе приходится полагаться на оружие, скованное руками смертных.$B$BПохоже, ты $gготов:готова: создать еще одно. Если хочешь, с тобой может поговорить Менара Расщепительница Бездны! Она живет неподалеку от башни Страхада над портовым городом Кабестан. Отправляйся туда, как решишь, что время уже пришло.', 'Поговорите с Менарой Расщепительницей Бездны в Степях.', 'А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.$B$BПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.$B$BИтак, думаешь, ты готов, $N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4970, 'Накормить ледопардов', 'Если хочешь достойно проявить себя, начни с простого, но очень важного дела. $B$BДобудь в окрестностях мясо химер и медведей-щербозубов. Принеси его мне, чтобы я мог кормить им ледопардов, которых я дрессирую.', 'Соберите 5 кусков мяса медведей-щербозубов и 5 кусков мяса стылодыхов для Риверна Холодного Ветра в Зимних Ключах.', 'Спасибо за помощь, $N. Мое мнение о тебе со временем становится все лучше.', 'Дисциплина и твердая решимость – вот чего ты должен достичь. Я могу поручать тебе простейшее задание несколько раз, и каждый раз все должно быть сделано как можно лучше.', NULL, NULL, 'Мясо медведя-щербозуба', 'Мясо хладнокрылой химеры', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4971, 'Вопрос времени', 'Кто-то вмешался в ход времени в Андорале! Скорее всего, это дело рук Плети. Я могу попытаться сохранить неизменным ход времени здесь и исправить повреждения, но мне не должны мешать. В этом ты мне и поможешь.$B$BВ Андорале поселились временные паразиты, падальщики, питающиеся обрывками потока времени. Их можно обнаружить только по синему сиянию. Они очень мешают мне. Пожалуйста, $N, искорени этих паразитов, воспользовавшись временным переместителем.', 'Воспользуйтесь временным переместителем рядом с одним из амбаров Андорала и найдите временных паразитов.Убейте 10 временных паразитов и верните временной переместитель Хроми в Андоральскую таверну в Западных Чумных землях.', 'Мне стало много легче исправлять ход времени. Спасибо, $N. Хотя тебе непросто понять все опасности нарушения естественного хода событий, я рада, что ты осознаешь важность противостояния Плети, а я почти уверена, что это дело ее рук.$B$BПочему бы не вознаградить тебя за помощь, смертный. Тебя ждут величайшие подвиги, и одна безделушка не заставит тебя свернуть с избранного пути. Хотя нам с драконами не помешает твоя помощь и в дальнейшем...', 'Там, где кто-то вмешивается в ход времени, непременно появляются временные паразиты. Я чувствую, что их немало, и они мне очень мешают.$B$BЕсли ты искоренишь хотя бы часть, мне будет гораздо проще разрешить сложившуюся ситуацию. Я почувствую, когда ты справишься с моим заданием.', NULL, NULL, 'Временной паразит убито', 'Временный переместитель (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4972, 'Отсчет времени', 'Мне нужно отправить тебя в мир за пределами этой комнаты, $N. Сейчас все объясню.$B$BВидишь, как эта комната отличается от остального Андорала? Мои драконы существуют во многих пластах реальности и времени. Чтобы исправить ущерб, нанесенный Андоралу, я действую из другого временного пласта, чтобы не загрязнить его сверх меры. Для продолжения работ мне необходимы особые устройства, оставшиеся со времен прихода чумы. Они находятся в сейфах в руинах некогда гордого города.', 'Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.', 'Вот, как раз то, что нужно, $N. Спасибо.$B$BПозволь вознаградить тебя. Быть может, ты не понимаешь, зачем тебе такое устройство. И даже для чего оно; довольно знать, что в будущем этот предмет тебе очень пригодится. А сохранишь ты его до тех времен или нет... дело твое, дружок.', 'Временные устройства, которые я ищу, очень просты. По большей части это просто часы, и их стрелки остановились в тот миг, когда в Андорале вспыхнула чума.$B$BВремя нескончамо, а часы, которые ты мне принесешь так и будут стоять... пока мы не справимся с временной аномалией.', NULL, NULL, 'Часы Андорала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4973, 'Отсчет времени', 'Если ты $gготов:готова: еще раз оказать мне помощь, я попрошу тебя принести еще пять часов из руин Андорала. Это очень поможет мне на равных бороться со злобной силой, пытающейся изменить ход времени.$B$BВзамен часов ты получишь еще один дар, который, мне кажется, здорово пригодится тебе в будущем.', 'Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.', 'И снова я благодарю тебя за помощь. Прими этот дар. Сейчас тебе невдомек, для чего он, но, быть может, ты еще узнаешь его истинную ценность. Можно сказать, что я предвижу это, $N.', 'Часы Андорала, как и те, на башне, остановились в три часа. Именно в это время чума распространилась по всему городу, лишая жизни несчастных жителей.$B$BКак ни печалимся мы о событиях того дня, они уже вошли в историю, без них не было бы сегодняшнего дня, такого, каким видите его вы, смертные. Бронзовые драконы должны хранить линию времени!', NULL, NULL, 'Часы Андорала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4974, 'За Орду!', 'Ренд осмеливается делать подобные заявления, потому что он пользуется поддержкой черных драконов.$B$BТы, $N, проникнешь в Залы Вознесения, найдешь там \"вождя\" Ренда Чернорука и уничтожишь его – ВО ИМЯ ОРДЫ!!!$B$B*Тралл ударяет кулаком по своему трону.*$B$BВ следующий раз, как я увижу тебя в своих покоях, ты торжествующе поднимешь ввысь его отрубленную голову и вручишь ее своему вождю. Выполни это – и станешь одним из героев Орды!', 'Отправляйтесь в Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар.', 'Тебе удалось нанести силам Черной горы сокрушительный удар, $N! Теперь, когда их вождь убит, воинство Черной горы снова ввергнуто в хаос.$B$BНаградой за твой героизм будет процветание народа Калимдора!', '*Тралл фыркает.*', NULL, NULL, 'Голова Ренда Чернорука', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4975, 'Завершение шара Дар\'орахила', 'Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять свое мнение.', 'Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар\'орахила, и еще раз поговорите с ней.', '', NULL, NULL, NULL, 'Дождитесь, пока Менара Расщепительница Бездны закончит работу над избранным предметом.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4976, 'Возвращение к Менаре', 'Теперь, когда демон изгнан, ты можешь отнести шар Менаре в Кабестан, $N. Передай ей от меня привет, да и $gсам:сама: не робей. Надеюсь, что тебе удастся противостоять искушениям порчи, которые, несомненно, будут подстерегать тебя на избранном пути.$B$BЖелаю удачи.', 'Отнесите очищенную сферу инфернала Менаре Расщепительнице Бездны в Степи.', 'Отлично, $N. Подходящая сфера.$B$BОсталось одно – решить, какого демона следует заключить в нее. Решишь – считай, новый предмет силы у тебя в кармане.', 'Как идут поиски Табеты и сферы?$B$BКогда дело доходит до магических сил, без нее не обойтись. Не сомневаюсь, она с радостью согласилась бы помочь тебе, отыщи ты ее.', NULL, NULL, 'Очищенная сфера подземного огня (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4981, 'Агент Блестяшка', 'Никогда нельзя верить гоблинам! Рано или поздно все приходят к этому выводу, $N. $B$BЕе зовут Блестяшка, она была одним из лучших наших агентов. Потом оказалось, что стерва вела двойную игру – работала на какого-то типа по имени Киблер, нелегально торгующего экзотическими животными в Пылающих степях, и использовала средства Орды для финансирования своих махинаций! $B$BОна должна быть доставлена ко мне живой. $B$BПоследний раз ее видели у Пика Черной горы. $B$BИ смотри, чтобы она не заговорила тебе зубы!', 'Отправьтесь к пику Черной горы и выясните, что сталось с Блестяшкой.', 'Я не буду лгать тебе, $R. Мне были нужны деньги! Киблер хорошо платит – куда больше, чем в Каргатском экспедиционном корпусе в лучшие его годы. $B$BНо можешь не сомневаться, я верна присяге! Думаешь, зачем я здесь? Чтобы таскать этому придурку-гоблину яйца экзотических зверушек или еще для каких глупостей? Нужно быть очень крупным идиотом, чтобы явиться в пик Черной горы отлавливать зверье! Не думаю, что на свете много таких сумасшедших. $B$B*Блестяшка заливисто хохочет.*$B$BВот что я тебе скажу, такие просто не должны размножаться, да-да!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4982, 'Вещи Блестяшки', 'По ночам, когда городская стража не особенно ревностно исполняет свои обязанности, я незаметно брожу по улицам и беру на заметку все, что может иметь хоть какую-то ценность для стратегических планов К.Э.К. Все подмечаю и все записываю.$B$BНо вчера ночью случился прокол. В темноте я запнулась о натянутую веревку, и включился сигнал тревоги. Пришлось срочно прятать все оборудование для разведки и мчаться в укрытие. И что самое ужасное, сейчас мне уже не удастся забрать свои вещи из тайника. В городе ввели усиленный режим патрулирования! Вся информация утрачена.$B$BРазыщи мои вещи, верни их мне, и я тихо-мирно вернусь в К.Э.К.', 'Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья.', 'Ой, молодчина! Когда я передам Лекслорту эти планы, он позабудет обо всех страшных угрозах в мой адрес и уж точно не станет спускать с меня шкуру.$B$B$N, ты мой герой!', 'Ну, как успехи?', NULL, NULL, 'Вещи Блестяшки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4983, 'По данным разведки', 'Передай этот рапорт Лекслорту. Теперь я верну себе доброе имя, потому что мое донесение, безусловно, сослужит хорошую службу К.Э.К. и даст им значительное стратегическое преимущество в борьбе с этими орками.$B$BПойти с тобой, говоришь? У меня много работы, недосуг мне носиться туда-сюда. Беги, донесение надо доставить как можно скорее!', 'Передайте донесение Блестяшки гроссмейстеру Лекслорту в Каргат.', 'Все-таки надо отдать ей должное;, хитрая бестия снова сумела выкрутиться! Ее донесение содержит бесценную информацию, которая очень поможет в наших делах с орками Черной Горы.$B$BРазумеется, ты не останешься без награды. Всякий труд должен быть оплачен.', 'Где эта гоблинша?!', NULL, NULL, 'По данным разведки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4984, 'Страдания природы', 'Хотя бороться с Плетью в одиночку бесполезно, я все равно прибыл в эти земли, чтобы лечить израненную природу. Чума поражает зверей и травы, не ведая пощады. Прошу, продолжи мое дело.$B$BНесчастных животных не спасти, остается прекратить их страдания. Ступай, отыщи больных волков и прикончи их. Прошу тебя, $N, избавь их от мучений – и мне тоже станет полегче.', 'Убейте 8 больных волков и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.', 'Я... Чую, что души убитых волков обрели покой. Мы с ними благодарны тебе за милосердие.$B$BНо в этом проклятом месте страдают не только волки. Мне вновь придется просить тебя о помощи.', 'Пораженных чумой волков необходимо истребить. Эта болезнь неизлечима. Я пытался справиться с ней, пока сам не пал ее жертвой.', NULL, NULL, 'Больной волк убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4985, 'Страдания природы', 'На востоке отсюда, рядом с границей Восточных Чумных земель, некогда жили гордые и могучие гризли.Чума затронула и их. Теперь они бродят по округе, страдая от застывающих мышц и гниющей плоти и меха.$B$BПрошу тебя, избавь их от страданий. Единственное исцеление для них – быстрая смерть. Ты можешь даровать ее.', 'Убейте 8 болезненных гризли и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.', '\"Я чувствую, что гризли упокоились с миром. Вот... вот моя последняя просьба. Я записал ее.. на этой ветви, чувствуя, что дни мои сочтены.$B$BЯ не ошибся, мне и верно приходит конец. Еще раз спасибо, брат... все живые существа этой проклятой земли обрели покой... теперь мой черед.\"$B$BС этими словами друид испускает тяжелый вздох, сменяющийся предсмертным хрипом. На полу остается лишь безжизненное тело.', 'Я слышу твою поступь, $N. Зрение мое уже помутнилось, но я чувствую все, что вокруг. Ты избавил несчастных гризли от страданий?', NULL, NULL, 'Болезненный гризли убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4986, 'Покрытая письменами дубовая ветвь', 'В безжизненной руке друида-таурена – удивительно живая дубовая ветвь. Внимательно осмотрев ее, вы видите вырезанные на ней друидические символы.$B$BСхватившись за ветвь, вы замечаете, что она слишком теплая для простой ветви. У вас в подсознании возникает образ древа Тельдрассила, точнее, самого Дарнаса. Более того, в голове так и вертятся слова \"Круг Кенария\". Кажется, в ветку вложили знания, куда ее лучше отнести.', 'Судя по магии, вложенной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Дарнасе. Попросите о помощи одного из тамошних друидов.', 'Это... Это странно. Тот друид – друид-таурен, надо же – передал тебе ценнейшие сведения о чуме Плети. Удивительно, зачем таурену понадобилось добровольно передавать подобные сведения $C. Надеюсь, ты говоришь правду. Не сомневайся, мы воспользуемся этими данными. Значит, таурены не так далеко отпали от Кенария, как полагает Фэндрал...$B$BКхе-кхе, да. Прими это в знак признательности Круга Кенария.', 'Приветствую тебя от имени Круга Кенария, $C. Что за дела привели тебя к нам?', NULL, NULL, 'Покрытая письменами дубовая ветвь (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (4987, 'Покрытая письменами дубовая ветвь', 'В безжизненной руке друида-таурена – удивительно живая дубовая ветвь. Внимательно осмотрев ее, вы видите вырезанные на ней друидические символы.$B$BСхватившись за ветвь, вы замечаете, что она слишком теплая для простой ветви. У вас в подсознании возникает образ Громового Утеса в Мулгоре, точнее, Вершины Старейшин. Более того, в голове так и вертятся слова \"Круг Кенария\". Кажется, в ветку вложили знания, куда ее лучше отнести.', 'Судя по магии, записанной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Громовом Утесе. Попросите о помощи одного из тамошних друидов.', 'Значит, это от Малгриса? Мы слышали, что он хотел избавить существ из Чумных земель от страдания, но столь плачевного итога мы не ждали... Печально. Малгрис... был моим другом. Я скорблю о его гибели.$B$BНо благодаря тебе его труды не пропали даром. В этой ветви заключено множество знаний о наступлении чумы на наши земли. Мы пристально изучим ее. А что до тебя, то возьми это. Мы хотели бы отблагодарить тебя.', 'Приветствую тебя от имени Круга Кенария, $C. Что за дела привели тебя к нам?', NULL, NULL, 'Покрытая письменами дубовая ветвь (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5001, 'Вещи Блестяшки', 'Обычно я стараюсь не связываться с такими, как ты, $r, но, похоже, сейчас я застряла между троллем и горным завалом. Видишь ли, я выполняю важное задание для Орды. Однако та информация, которую мне удалось раздобыть, касается также и благополучия Альянса. Поверь мне, я не питаю симпатий к Альянсу, но угроза Черной горы – это гораздо серьезнее, чем какая-то там толпа грязных орков.$B$BПомоги мне найти мои вещи, а я передам тебе сведения, которые могут оказаться полезными для твоих сородичей.$B$BНу что, по рукам?', 'Найдите вещи Блестяшки и верните их владелице. Удачи!', 'Ой, спасибо! И где ж они были?!', 'Ну, как успехи?', NULL, NULL, 'Вещи Блестяшки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5002, 'Донесение Максвелла', 'Я – честная гоблинша и хозяйка своего слова, $r. А теперь слушай внимательно...$B$BЭтих орков используют в основном в качестве вьючных животных или пушечного мяса для черных драконов!$B$BИх предводитель не кто иной, как Нефариан, сын Смертокрыла. Также мне удалось узнать, где именно в крепости засели приспешники Нефариана.$B$BОтнеси эту карту маршалу Максвеллу в Пылающие степи. Я там отметила все места, где найти этих извергов.', 'Передайте маршалу Максвеллу информацию Блестяшки.', 'Что ж, это лишь подтверждает уже известную нам информацию. Тем не менее здесь есть интересные сведения, которые нам пригодятся.$B$BОтметки на карте – это хорошее подспорье. Так мы быстрее разберемся с угрозой Черной горы.', '$N! Сколько лет, сколько зим!', NULL, NULL, 'Информация Блестяшки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5021, 'Лучше поздно, чем никогда', '\"Доставьте посылку... Доставьте ее, пока я не очутилась в ловушке!\"$B$BПо всему дому разносятся причитания напуганной женщины. Привидение скорчилось в углу на втором этаже. Кажется, она не понимает, что вокруг, да и вас едва замечает.$B$B\"Ты хочешь доставить мою посылку? Прошу тебя, сделай это, пока хуже не стало. Я собиралась уехать отсюда. Должно быть, там все еще стоит мой конь... или я опоздала?\"', 'Судя по сбивчивым объяснениям призрачной женщины, она хочет доставить посылку. Бедняга уверяет, что посылка лежала там, где стоял ее конь. Где именно это было, женщина не сказала.', 'В сарае на полу лежит посылка. Вы могли бы пройти мимо, но она бросается в глаза среди развалин. Быть может, именно о ней говорила Джанис Фелстоун...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5022, 'Лучше поздно, чем никогда', 'Вы берете посылку, стирая с нее слой пыли и грязи. Она адресована Эмме Фелстоун из Штормграда; посылка должна была быть доставлена четыре года назад.$B$BХотя вы не уверены, что Эмма Фелстоун жива, всем известно, что в Штормграде существует реестр жителей города. Справки можно наводить у королевских представителей Переписи Штормграда.', 'Выясните у королевских представителей Переписи Штормграда местонахождение Эммы Фелстоун. Офицера-переписчика можно найти в Ратуше.', 'Говорите, посылка для Эммы Фелстоун? И четыре года назад она жила в Штормграде? Посмотрим…$B$BСудя по всему, четыре города назад в городе и верно жила некая Эмма Фелстоун. Скорее всего жила. Я ориентируюсь по переписи, имевшей место пять лет назад, но никаких записей о том, что она уехала, нет. Но это не значит, что Эмма все еще здесь.$B$BМинуточку... уж не старушке ли Эмме адресована эта посылка?', 'Добро пожаловать в отдел переписи Штормграда. Если вы хотите навести справки о жителях города, то пришли по адресу.', NULL, NULL, 'Посылка Дженис (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5023, 'Лучше поздно, чем никогда', 'Вы берете посылку, стирая с нее слой пыли и грязи. Она адресована Иеремии Фелстоуну из Лордерона; посылка была подготовлена к отправке четыре года назад.$B$BХотя вы не уверены, что Иеремия Фелстоун жив, всем известно, что в Подгороде, прежде именовавшемся Лордероном, существует реестр жителей города. Справки можно наводить у королевских инспекторов Переписи Подгорода.', 'Поговорите с королевскими инспекторами Подгорода и наведите справки о Иеремии Фелстоуне. Офицера-переписчика можно найти рядом с пунктом регистрации гильдий и гербовых накидок.', 'Посылка для Иеремии Фелстоуна... В Лордерон... Пожалуй, я смогу помочь.$B$BДо наступления чумы Иеремия Фелстоун жил в городе. Бывший Иеремия Фелстоун – многие представители нежити изменили фамилии, чтобы избавиться от прошлого. Так произошло и в этом случае. Иеремения Фелстоун стал Иеремией Пэйсоном.$B$BМинуточку... разве это не он продает тараканов?', 'Тебе требуется помощь переписчика Подгорода или ты просто хочешь узнать, не умер ли твой давний знакомый? Ко мне с такими вопросами часто обращаются.', NULL, NULL, 'Посылка Дженис (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5041, 'Снабжение Перекрестка', 'Нападение на караваны лишает нас необходимых припасов.$B$BТебе хватило храбрости выступить против племени Иглогривых, и я вновь попрошу тебя о том же, но на сей раз посматривай, нет ли где украденных у нас припасов? Может быть, они в лагерях этих тварей, и иглогривы жиреют на чужом добре?$B$BНарод Перекрестка будет у тебя в неоплатном долгу.', 'Найдите и верните Тхорку из Степей ящики с припасами из Перекрестка.', 'Ха-ха! Спасибо, $N! Ты нам очень помог. Ты неизменно спасаешь народ Перекрестка и Орды. Если я могу что-нибудь для тебя сделать, обращайся.', 'Как идут поиски припасов? Надеюсь, иглогривов-то ты легко одолеешь?', NULL, NULL, 'Ящики с припасами для Перекрестка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5042, 'Сила Агамаггана', '', '', 'Ах, если бы Кривозуб мог видеть, как ты наказал предавших его! *фыркает*$B$BБлагодарю тебя, ведь, собирая эти осколки, ты убил еще нескольких иглогривов Дыбогривов. Продолжай в том же духе, и я вновь буду помогать тебе. *фыркает*', NULL, NULL, NULL, 'Кровавые осколки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5043, 'Ловкость Агамаггана', '', '', 'Да будет верной твоя цель и метким оружие, $R.$B$BДух Агамаггана пребывает с тобой. *фыркает* Возвращайся, если захочешь. Кривозуб снова благословит тебя, если будет на то воля великого кабаньего бога. *фыркает*', NULL, NULL, NULL, 'Кровавые осколки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5044, 'Мудрость Агамаггана', '', '', 'Теперь враги будут трепетать от одного твоего вида, $R. *фыркает*$B$BПоведай Кривозубу о своих битвах, когда мы встретимся в следующий раз – в этой жизни или в следующей. *фыркает*', NULL, NULL, NULL, 'Кровавые осколки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5045, 'Высокий дух', '', '', 'Наши величайшие воины и величайшие шаманы *фыркает* позавидовали бы твоей силе воли, $R.$B$BТеперь, зная, что иглогривам не остановить тебя, ты нанесешь еще больший урон племени Вздыбленной Щетины. *фыркает*', NULL, NULL, NULL, 'Кровавые осколки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5046, 'Иглошкура', '', '', 'В бой, $R!', NULL, NULL, NULL, 'Кровавые осколки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5047, 'Пип Шустрикс, к вашим услугам!', 'Разыщи Малифоя Черномолота в Круговзоре, $C. Скажи ему, что с Пипом все в порядке и что костюмчик исправно работает.$B$BИ передай ему вот что...$B$B*Пип вручает вам ярко светящийся кусок мяса.*$B$BЯ его вырезал из внутренностей одной зверюги во время своих вынужденных каникул.$B$BГотов поспорить, Малифой очень подробно тебе растолкует, что можно сделать с мясом этого чудища!$B$BКстати, ты знаешь, где Круговзор? Это в Зимних Ключах.', 'Переговорите с Малифоем Черномолотом в Круговзоре.', 'Он жив? Костюм цел? А что это там у тебя?', 'Да?', NULL, NULL, 'Светящийся кусок мяса животного (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5048, 'Добросердечная Эмма', 'Это злобная старушенция и к тому же, весьма вероятно, уже с катушек съехала... Но записи указывают, что старушка Эмма как раз вполне может являться той самой Эммой Фелстоун.$B$BВозможно, вы видели старушку Эмму бредущей по городу – она разговаривает сама с собой, иногда неся совершенно невнятный вздор. Но она никому и ничему не мешает, так что горожане, в большинстве своем, оставили ее в покое.$B$BОбдумав все, я бы сказал, что старушка Эмма и в самом деле – Эмма Фелстоун. Можете сами спросить у нее, не Фелстоун ли ее фамилия.', 'Найдите в Штормграде старушку Эмму и узнайте, действительно ли она – Эмма Фелстоун. Если да, то, может, ей понравится та посылочка, что собрала для нее Джанис Фелстоун.', 'Мое имя и в самом деле Эмма Фелстоун – но меня впервые так называют за много лет. Кто... кто вы?$B$BВы говорите, что знали... мою сестру?! Она до сих пор жива? Да что это я – конечно же, нет. Когда чума охватила Лордерон, я ожидала самого худшего. Так много моих родственников погибло... или еще хуже того. И вот я здесь, сумасшедшая старушка Эмма, одна-одинешенька. Кто же вы – разоритель могил или что? Ищете следующую жертву?$B$BЧто... у вас посылка для меня от сестры?', 'Я поросила бы вас не топтать мою лужайку, но, как видите, у меня ее нет.', NULL, NULL, 'Посылка Дженис (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5049, 'Грусть Иеремии', 'Мне удалось выяснить, что тот, кого ты ищешь, – он же получатель посылки – это Иеремия Пейсон, продавец тараканов в Подгороде.$B$BМне всегда казалось, что для торговли тараканами нужны особые личные качества. Не сомневаюсь, тебя ждут великие дела, $C. Ступай, меняй мир к лучшему. Впрочем, позволь и мне поучаствовать в столь великих событиях и приоткрыть завесу тайны: он находится недалеко от банка, в стороне от одной из дорожек.', 'Найдите в Подгороде Иеремию Пейсона и выясните, в самом ли деле он Иеремия Фелстоун. Если да, передайте ему посылку от Джанис Фелстоун.', 'Я не пользовался этим именем много лет... Да, некогда, до того прекрасного момента, когда я влился в ряды нежити, меня так звали.$B$BТак ты знал мою сестру... или, точнее, недавно говорил с моей сестрой?$B$BОна умерла.$B$BЧетыре года назад.$B$BЗнаешь, не будь у меня такие хрупкие кости, я бы с радостью тебя пнул. Глумишься над чужим горем?$B$BЧто... у тебя посылка от моей сестры?!', 'Всякий раз, как кто-то наступает на таракана, я плачу. Не доводи меня до слез.', NULL, NULL, 'Посылка Дженис (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5050, 'Оберег удачи', 'Кажется, я была неправа насчет тебя и должна извиниться. Сестра прислала мне ряд личных вещей, в том числе – ха-ха – документы на ферму Фелстоун. Я погожу предъявлять на нее права.$B$BЕсли призрак моей сестры не может упокоиться и привязан к ферме... может быть, ты вернешь ей это? Это половина талисмана; вторую носил ее муж.$B$BМожет быть, она обретет покой, если узнает, что я получила посылку?', 'Отнесите половинку талисмана Джанис Фелстоун в Западные Чумные земли.', 'Вы отдаете половинку талисмана призраку. Джанис выжидающе смотрит на вас.$B$B\"Милый, а где твоя половина талисмана? Нам не быть вместе, не собрав его воедино. Милый... Ты меня видишь?\"', 'Джон, милый... Это ты? Мне так холодно...', NULL, NULL, 'Половинка талисмана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5051, 'Вторая половина', 'Несчастный призрак продолжает причитать:$B$B\"Мне холодно, Джон. Принеси мне свой оберег, и мы снова будем вместе! Скорее, Джон, пока чума не превратила нас в жутких тварей! Я не вижу тебя, Джон... Но знаю, ты рядом. Я чувствую.\"$B$BБыть может, если найти вторую половину оберега и собрать его воедино, душа Джанис Фелстоун обретет покой.', 'Отыщите вторую половину оберега Удачи на ферме Фелстоун в Западных Чумных землях и соберите его.Отдайте оберег Удачи Джанис Фелстоун.', 'Вы отдаете целый оберег Удачи призраку Джанис Фелстоун. Взяв его в руки, она моментально преображается. Призрачный облик слегка мерцает, а девушка устремляет на вас ясный, хоть и грустный, взор.$B$B\"Ты освободил меня... Мне больше не нужен этот оберег. Возьми его, быть может он принесет тебе не меньшее утешение, чем мне.\"', 'Джон, не давайся в руки вурдалаков... Не отдавай им меня... Гнусные вурдалаки, оберег защитит нас.', NULL, NULL, 'Оберег удачи', 'Половинка талисмана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5052, 'Кровавые осколки Агамаггана', 'Кровь повлияла не только на шипы $gфыркает:, но и на другие аспекты земли: среди прочих минералов попадаются кроваво-красные камни. Племя Дыбогривов выкапывает эти осколки и носит с собой как тотемы $gфыркает:, и они дают им силы в бою и помогают творить заклинания. $gфыркает:$B$BСекреты их магии мне известны.$B$BПринеси Кривозубу один кровавый осколок, и ты все поймешь. Принеси Кривозубу много осколков, и он благословит тебя. Сильна магия иглогривов, ведь это магия самого Агамаггана! $gфыркает:', 'Принесите кровавый осколок Кривозубу в Лагерь Таурахо в Степи.Соберите побольше кровавых осколков, и он одарит вас силой, дарованной ему Агамагганом.', 'Да, ты понимаешь. *фыркает* Мои слова для тебя – не пустой звук, $R. Быть может, Кривозуб и заключен в клетку, но что клетка для силы Агамаггана! *фыркает*$B$BКасание осколка, какое забытое ощущение, $R. $B$BЗнаешь, каково это – чувствовать себя отрезанным от силы?$B$BНо об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба. Теперь они падут от твоей руки. *фыркает*', 'Наши племена селятся в тех областях Степей, где растут колючки, *фыркает* потому что это священные места. И первейшее из них – это земли Иглошкурых. Тело Агамаггана составляет все эти земли, но особенно хранимы холмы, потому что вход в них сделан из его огромной пасти! *фыркает* Она поглощает всех неверных и выплевывает их тела, когда он хорошенько прожует их! *фыркает*$B$BАгамагган оставил свое тело, чтобы защитить нас, и щедро делится своим духом, чтобы мы защищали его. *фыркает*', NULL, NULL, 'Кровавые осколки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5054, 'Урсиус из щербозубов', 'В заснеженных горах Зимних Ключей, на северо-западе, умелый охотник идет по следу своей добычи… Я говорю о медведе-щербозубе Урсиусе – звере ловком и умном.$B$BЯ посылаю тебя в бой против него. Он бродит по холмам к северо-западу от Круговзора. Найди его и начни охоту на него – раньше, чем он поймет твои намерения.$B$BВсе, кто шли на Урсиуса, вскоре понимали, что они добыча, а отнюдь не охотники. Так что будь начеку.', 'По просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах убейте Урсиуса.', 'Задание было непростым, но тебе сопутствовал успех. Только не думай так сразу, что тебе удалось произвести на меня впечатление, $N.', NULL, NULL, NULL, 'Урсиус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5055, 'Хладнокрылая Брумеран', 'Умная и ловкая Брумеран тихо скользит по заснеженным просторам южных окраин Зимних Ключей. Но пусть тебя не обманывает ее грация – она отнюдь не безопасна. Все, кто встает у нее на пути, расплачиваются за это – частенько своими собственными жизнями.$B$BНайди Брумеран среди хладнокрылых химер. Срази ее, а затем возвращайся ко мне.', 'Убейте Брумеран по просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах.', 'Да. Ты вернулся. Теперь я верю, что охота – твое призвание. Ты встретился с самой свирепой из тварей и вернулся превзойдя мои ожидания.$B$BТеперь ты готов к моему последнему испытанию.', 'Брумеран ждет тебя, $N.', NULL, NULL, 'Брумеран убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5056, 'Ши-Ротам', 'На севере Зимних Ключей, в районе, который называют Уступ ледопардов, обитают огромные кошки. Их предводительница известна под именем Ши-Ротам. Если тебе удастся сразить матриарха ледопардов, ты завоюешь уважение в глазах своих сородичей.$B$BОтправляйся обратно в глушь. Придя на место, добудь священного мяса ледопардов. Найди камень Ши-Ротам и помести мясо на него. Мясо растерзанных подданных заставит их предводительницу Ши-Ротам явиться в гневе.$B$BБудь $gготов:готова: встретиться с ней лицом к лицу и сразить ее.', 'Убейте Ши-Ротам для Шторма Призрачное Копыто.', 'Ты доказал как свою силу, так и решимость. Еще много испытаний ждет тебя впереди. Я показал тебе все, что мог.', NULL, NULL, NULL, 'Ши-Ротам убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5057, 'Прежние свершения', 'Еще раньше, чем вы пришли ко мне поговорить, $N, я слышал о ваших деяниях… что у вас есть непреодолимое желание проявить себя, что вы $C с отменными способностями, и теперь я знаю, что все это было правдой.$B$BТе, кто добивается таких успехов, заслуживают признания. Отнесите этот знак в Громовой Утес моему другу Мелору Каменному Копыту. Уверен, что он вспомнит и вас, и ваши подвиги. Расскажите ему о своих недавних достижениях. И никогда не забывайте о том, что свершили сегодня.', 'Отнесите Знак Шторма Призрачное Копыто Мелору Каменное Копыто в Громовой Утес.', 'Мы учимся благодаря жизненным испытаниям, $N. Я уверен, что в результате ты стал лишь сильнее и мудрее. Ты сильно повзрослел с того момента, когда мы общались впервые.$B$BПрими это в память о тех сложных заданиях, с которыми ты справился, и знай, что ты навсегда завоевал мое уважение и восхищение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5058, 'Дневник миссис Далсон', '', '', 'В дневнике с пожелтевшими от времени страницами открыта последняя запись:\"Гарольд превратился в нежить, и я не знаю, что теперь будет. Я из последних сил утащила его в единственное место, которое можно надежно запереть. Я держу ключ при себе, будем надеяться, что моя уловка сработает...Надеюсь, я смогу выбраться отсюда, но для этого нужны деньги. Все наши вещи в шкафу... и, кажется, Гарольд держал ключ от него при себе.Пора мне отдохнуть, я смертельно устала.\"', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5059, 'Под замком', '', '', 'Вы отпираете дверь ключом, обнаруженным на скелете миссис Далсон. Наружу выскакивает кровожадный вурдалак, который сидел в заперти неизвестно сколько лет.$B$BСудя по леденящему кровь воплю, бывшего фермера Далсона уже не спасти.', NULL, NULL, NULL, 'Ключ от уборной Далсонов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5060, 'Под замком', '', '', 'Ключ, взятый из останков фермера Далсона, идеально подходит к замку. Двери шкафа распахиваются. Внутри оказывается несколько уцелевших предметов, которые кажутся весьма ценными.', NULL, NULL, NULL, 'Ключ от шкафа Далсонов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5061, 'Водный облик', 'Ты $gзавершил:завершила: обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнас. Покажи ему свою подвеску и докажи, что ты $gготов:готова: усвоить его уроки. Он завершит твое обучение, благодаря которому ты станешь $gединым:единой: с водой.$B$BДоброго пути, $gюный друид:дева-друид:. Мы еще встретимся.', 'Вернитесь в Дарнас и покажите Матренгилу Медвежьей Лапе свою подвеску Морского Льва.', 'Великолепно, $N. Ты готов принимать водный облик, и я с радостью научу тебя.$B$BА также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это. Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия.', 'Весть о твоем возвращении в Дарнасс опередила тебя, хотя я хочу увидеть доказательства того, что ты усвоил уроки Лунной поляны прежде, чем стану учить тебя принимать водный облик.$B$BЕсть ли у тебя подвеска Морского Льва?', NULL, NULL, 'Подвеска Морского Льва (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5062, 'Священное пламя', 'Арикара очень опасна,  и мы должны как можно быстрее разделаться с ней. Для того чтобы привлечь это чудовище, тебе нужно будет разжечь священный огонь жизни.$B$BСобери немного редкой огненной агавы и отнеси ее Магате Зловещий Тотем. Она живет в Громовом Утесе, на Вершине Старейшин. Магата – очень могущественная шаманка, владеющая тайной приготовления зачарованного порошка из огненной агавы.$B$BОгненную агаву можно собрать на Кипящем озере, это к востоку отсюда.', 'Соберите 10 листов огненной агавы и поговорите с Магатой Зловещий Тотем на Вершине Старейшин в Громовом Утесе.', 'Прекрасно, вы собрали достаточно огненной агавы. Эта редкая трава растет лишь в Тысяче Игл, и она поможет мне разбудить священное пламя жизни.$B$B*Магата начинает зачаровывать огненную агаву.*', 'Значит, Мотега Огненная Грива сообщает об Арикаре... Хм, это дурные вести.$B$B*Магата оглядывается вокруг.*$B$BАрикара – это смертоносная тварь, рожденная лишь для того, чтобы мстить тем, кто совершает злодеяния.$B$B*Магата улыбается.*', NULL, NULL, 'Огненная агава', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5063, 'Шапка ученого из Алого ордена', 'Головного убора лучше этого тебе, быть может, и не придется увидеть. Из безупречной звериной шкуры наши опытные мастера изготовят потрясающую шляпу, о какой может только мечтать любой иллюзионист!$B$BПятьдесят золотых и предметы по списку – и твою голову украсит шапка ученого из Алого ордена:$B$B– безупречная звериная шкура$B$B– потертый шовный материал поганища$B$B– чародейские кристаллы$B$B– зачарованная алая нить$B$BИ УЗРИШЬ ТЫ ЧУДО!', 'Для изготовления шапки ученого из Алого ордена вам нужно принести Малифою Черномолоту 1 безупречную звериную шкуру, 5 кусков потертого шовного материала поганища, 8 чародейских кристаллов, 5 зачарованных алых нитей. Вы также должны будете уплатить 50 золотых монет за изготовление головного убора.', '', NULL, NULL, NULL, 'Нетронутая звериная шкура', 'Истлевшая шовная нить поганища', 'Чародейный кристалл', 'Зачарованная алая нить');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5064, 'Наблюдение за Зловещим Тотемом', '$N, мы благодарны тебе за помощь, и поэтому я доверю тебе еще одно важное задание. Племя Зловещего Тотема явно что-то замышляет: недавно мы видели, как в их поселение приходили какие-то странные путники. Потом нам удалось узнать, что важные записи они хранят в трех разных сундуках пика Темного Облака.$B$BЕсли тебе удастся достать эти документы, я щедро тебя вознагражу.', 'Найдите и заберите три тайные записки на Пике Темного Облака.', 'Великий тотем духов! Какие ужасные новости! Я немедленно начну готовиться, кто знает, что нас ждет...$B$BВот, $N, как я и обещал, это награда за вашу храбрость и услугу.', 'Тебе удалось выяснить, что задумало племя Зловещего Тотема?', NULL, NULL, 'Тайная записка №1', 'Тайная записка №2', 'Тайная записка №3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5065, 'Утраченные таблички Мошару', 'Тот тролль обманул тебя. В тех двух табличках шла речь о пленении сущности Хаккара, но легенда этим не исчерпывается. Я долго изучал этот вопрос, и обнаружил, что табличек Мошару шесть, а не две! Шесть!$B$BИ боюсь, нас не порадует то, что в них записано.$B$BНайди третью и четвертую таблички. Они находятся в Восточных Чумных землях, у троллей из племени Моходеров. Найди их и принеси мне.', 'Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис.', 'Ты нашел их! Отлично!$B$BСпасибо, $N. Я изучу эти тексты и расшифрую их значение.$B$BДля тебя же у меня есть еще одно задание...', 'Ты принес мне таблички? Боюсь, в них написано о великой опасности, грозящей нашему миру.', NULL, NULL, 'Третья табличка Мошару', 'Четвертая табличка Мошару', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5066, 'Призыв к оружию: Чумные земли!', 'Слушайте, слушайте все! Я обращаюсь к героям, и да услышат они мою речь!$B$BВКороль Штормграда призывает к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Стало известно, что над Чумными землями вновь сгущаются тучи!$B$BГерои королевства! Ищите командира Ашлама Отважного Кулака! Его гарнизон вы найдете в лагере Промозглого Ветра на севере Альтеракских гор!', 'Найдите командира Ашлама Отважного Кулака в лагере Промозглого Ветра на севере Альтеракских гор.', 'Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5067, 'Поножи тайны', 'В то время как изготовление такого предмета еще никому не удавалось, считается, что это все же возможно – при правильном стечении обстоятельств.$B$BЕсли искатель тайных знаний желает наделить поножи могучей силой, вот что должно быть найдено:$B$B– безупречная звериная шкура$B$B– потертый шовный материал поганища$B$B– арканитовые слитки.$B$B– бальзамировочный состав Снегошепота$B$BИ УЗРИШЬ ТЫ ЧУДО!', 'Для изготовления поножей тайны вам нужно принести Малифою Черномолоту 1 безупречную звериную шкуру, 5 кусков потертого шовного материала поганища, 5 арканитовых слитков и 5 порций бальзамировочного состава Снегошепота. Вам придется также заплатить 50 золотых за изготовление этого предмета.', '', NULL, NULL, NULL, 'Нетронутая звериная шкура', 'Истлевшая шовная нить поганища', 'Арканитовый слиток', 'Бальзамировочный состав Ледяного Шепота');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5068, 'Кираса кровавой жажды', 'Говорят, что кираса кровавой жажды была создана лишь один раз, и изготовлена она была для легендарной убийцы Гароны. Суждено ли еще одному подобному доспеху увидеть свет? Сомнительно...$B$BИ все же! Наши мастера могут воспроизвести этот доспех, если дать им необходимые компоненты:$B$B– безупречную звериную шкуру.$B$B– потертый шовный материал мясника.$B$B– арканитовые слитки.$B$B– шкуру тени.$B$BИ УЗРИШЬ ТЫ ЧУДО!', 'Для изготовления кирасы кровавой жажды вам нужно принести Малифою Черномолоту 1 безупречную звериную шкуру, 10 кусков потертого шовного материала поганища, 5 арканитовых слитков и 5 шкур тени.Вы также должны будете уплатить 50 золотых за изготовление доспеха.', 'Я уж думал, что не доживу до этого дня.$B$BДостижение такого масштаба может превзойти лишь награда за него.', 'До тех пор, пока не соберешь все необходимое, ты лишь попусту тратишь мое время.', NULL, NULL, 'Нетронутая звериная шкура', 'Истлевшая шовная нить поганища', 'Арканитовый слиток', 'Шкура тени');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5081, 'Миссия Максвелла', 'Эти сведения заполняют последние пробелы в наших данных о пике Черной Горы.$B$BМы должны напасть со всей решительностью, $N.$B$BПервым делом нужно убить их воеводу, Вуна. Без его боевых планов орки Черной Горы будут ввергнуты в хаос.$B$BСледом должен умереть вождь огров, Омокк. Трусливые огры Черной Горы окажутся беспомощны.$B$BИ, наконец, повелитель всей цитадели зла: Змейталак. Когда он умрет, командование будет обезглавлено.', 'Отправляйтесь на пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака.', 'Отличная работа, $N. По меньшей мере нам удалось выиграть время – а на счету каждая минута.', NULL, NULL, NULL, 'Воевода Вун убито', 'Вождь Омокк убито', 'Властитель Змейталак убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5082, 'Угроза со стороны Зимней Спячки', 'Сюда в Зимние Ключи я пришла, чтобы изучать Источники Ледяного Пламени. Я заметила, что у воды здесь какие-то… странные свойства. Мне пока не удалось определить источник этих свойств, да и, по правде говоря, в последнее время у меня возникли кое-какие сложности, из-за фурболгов племени Зимней Спячки.$B$BИх, кажется, тянет к источникам – так же, как и меня. Они яростно защищают воду и не подпускают меня близко к двум большим ключам к северу отсюда.$B$BЯ хотела бы продолжить свои изыскания. Ты не поможешь мне?', 'По просьбе Доновы Снегоноры из Зимних Ключей убейте 8 землепроходцев, 8 дозорных и 8 тотемистов из племени Зимней Спячки.', 'Огромное спасибо, $N! Теперь я могу вернуться к работе.$B$BНашел что-нибудь интересное в поселении Зимней Спячки?', 'Буду очень признательна за помощь!', NULL, NULL, 'Землепроходец из племени Зимней Спячки убито', 'Дозорный из племени Зимней Спячки убито', 'Тотемист из племени Зимней Спячки убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5083, 'Огненный эликсир Зимнего Сна', 'Тот сосуд, что вы нашли у фурболга племени Зимней Спячки, пуст, но внутри осталось несколько капель странной зеленой жидкости. Он почти сияет.$B$BОбнаружили ли вы нечто важное?$B$BВозможно, Донова Снегонора могла бы что-то вам разъяснить, поскольку она уже довольно давно живет у горячих ключей.', 'Принесите Донове Снегоноре пустую флягу из-под огненной воды.', 'Это было у фурболга из племени Зимней Спячки?', 'Что это у тебя?', NULL, NULL, 'Пустая фляга из-под огненной воды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5084, 'Поддавшиеся порче', 'Зеленая жидкость… немного напоминает мне жижу, которую я видела, когда пробиралась через Оскверненный лес. И я видела несколько гонцов племени Зимней Спячки, входящих во владения Древобрюхов… Возможно, это имеет отношение к той склянке, что вы нашли, $N.$B$BСразу за Крепостью Древобрюхов, в Оскверненном лесу, живет большая группа фурболгов. Они зовутся племенем Мертвого Леса, и давно попали под власть скверны. Да, фурболги этого племени совершенно безумны. Может, сходишь и поищешь свидетельства того, что между племенами Зимней Спячки и Мертвого Леса есть какое-то сообщение?', 'Исследуйте поселение фурболгов из племени Мертвого Леса в северной части Оскверненного леса в поисках ключа к разгадке.', 'В котле кипит гнилостная, отвратительно пахнущая субстанция…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5085, 'Таинственная слизь', 'Зеленая субстанция внутри котла кажется точно такой же, какую вы обнаружили в сосуде. Это странное слизистое вещество может оказаться таким же полным скверны, как и фурболги, что его изготовили…$B$BЕсли фурболги племени Зимней Спячки его используют, значит ли это, что вскоре они окажутся в таком же состоянии, как и племя Мертвого леса?$B$BЛучше всего сообщить об этих находках Донове, прихватив и образец жидкости из котла.', 'Вернитесь к Донове и сообщите ей о своих находках.', 'Ты очень находчив, $N. Так ты полагаешь, что фурболги племени Зимней Спячки побывали в лагере Мертвого Леса?', 'Надеюсь, вы что-нибудь нашли, $N. Фурболги племени Зимней Спячки становятся все агрессивнее!', NULL, NULL, 'Сосуд с таинственной вязкой жидкостью (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5086, 'Ядовитый Ужас', 'Я изучила образцы, с которыми вы вернулись, и хотя точно пока ничего сказать не могу, я думаю, что в них есть следы ядовитых компонентов. Однако, единственный способ узнать наверняка – это найти что-то для сравнения.$B$BЯ думаю, что фурболги Мертвого Леса могут собирать эти компоненты с других зараженных скверной существ в Оскверненном лесу: в частности, с элементалей, населяющих Железнолесье, которых называют ядовитым ужасом.$B$BСобери для меня несколько образцов для сравнения, но будь $gосторожен:осторожна: – там очень опасно!', 'Соберите 3 капли ядовитого ужаса и принесите их Донове Снегоноре в Зимние Ключи.', 'Мне нужно сравнить с этими образцами то вещество, что ты нашел в котле – тогда, я уверена, мы узнаем больше.', 'Я думаю, мы начинаем понимать, что тут происходит, $N.', NULL, NULL, 'Капля ядовитого ужаса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5087, 'Гонцы Зимней Спячки', 'Очень интересно, $N…$B$BЕсли эту ядовитую субстанцию смешать с водой из горячих ключей, она потеряет свою токсичность, и остается лишь способность временно воздействовать на тех, кто такую смесь употребляет. Наверное, из-за этого племя Зимней Спячки и защищает источники столь яростно: они необходимы фурболгам для очистки огненной воды.$B$BМы должны положить этому конец: прекратить контакты между племенами Зимней Спячки и Мертвого Леса. Группа гонцов курсирует между поселением Зимней Спячки и Оскверненным лесом. Найди их, убей и забери то, что у них будет с собой.', 'Найдите гонцов из племени Зимней Спячки и не позвольте им донести их груз до их деревни.', '*Донова изучает содержимое ящика.*$B$BИнтересно, делает ли употребление этой субстанции фурболгов более агрессивными? На вид они кажутся намного крупнее…', 'Посмотрим, что случится, когда фурболги племени Зимней Спячки не получат своей огненной воды!', NULL, NULL, 'Ящик Зимней Спячки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5088, 'Арикара', 'Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл. Сделать это нужно на Пике Темного Облака, на отдельной скале, где находится местное кладбище.$B$BЯ зачаровала порошок так, чтобы он привлек Арикару, $N.$B$BБоюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище. Поспешите, $C, вы можете не успеть!', 'Убейте Арикару и в качестве доказательства принесите ее останки вместе с воспламеняющим порошком Мотеге Огненной Гриве на заставу Белого Плеса.', 'Ерунда какая-то. Зачем Арикаре охотиться за Кэрном Кровавым Копытом? Но Магата не может ошибаться, она наша самая могущественная шаманка.$B$B*Мотега качает головой.*$B$BВ любом случае, вы очень помогли Орде, и деяние ваше не останется незамеченным. Пожалуйста, выберите себе любую награду.', 'Вы убили смертоносную змею Арикару, $N?', NULL, NULL, 'Воспламеняющий порошок (Прилагается)', 'Змеиная шкура Арикары', 'Зажгите священный огонь жизни.', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5089, 'Приказ генерала Драккисата', 'Вы обыскали труп убитого драконида и обнаружили записку, содержание которой показалось вам важным: письмо от его непосредственного начальника, генерала Драккисата, в котором упоминается некий протокол.$B$BВнутренний голос подсказывает, что это письмо следует показать маршалу Максвеллу.', 'Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи.', 'Мда... теперь все усложняется...', 'С чем пожаловал, $N?', NULL, NULL, 'Приказ генерала Драккисата (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5090, 'Призыв к оружию: Чумные земли!', 'Слушайте, слушайте все! Я обращаюсь к героям, и да услышат они мою речь!$B$BВКороль Штормграда призывает к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Стало известно, что над Чумными землями вновь сгущаются тучи!$B$BГерои королевства! Ищите командира Ашлама Отважного Кулака! Его гарнизон вы найдете в лагере Промозглого Ветра на севере Альтеракских гор!', 'Найдите командира Ашлама Отважного Кулака в лагере Промозглого Ветра на севере Альтеракских гор.', 'Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5091, 'Призыв к оружию: Чумные земли!', 'Слушайте, слушайте все! Я обращаюсь к героям, и да услышат они мою речь!$B$BВКороль Штормграда призывает к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Стало известно, что над Чумными землями вновь сгущаются тучи!$B$BГерои королевства! Ищите командира Ашлама Отважного Кулака! Его гарнизон вы найдете в лагере Промозглого Ветра на севере Альтеракских гор!', 'Найдите командира Ашлама Отважного Кулака в лагере Промозглого Ветра на севере Альтеракских гор.', 'Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5092, 'Зачистка территории', 'Поскольку западная и северная дороги, ведущие в Андорал, хорошо укреплены, я подумываю о нападении с востока, как наименее защищенной стороны. Плеть рассчитывает на защиту нежити, наводнившей холм Печали.$B$BПервым заданием будет зачистка холма Печали. Убей побольше скелетов и вурдалаков; по выполнении задания возвращайся ко мне!', 'Убейте 10 скелетов-свежевателей и 10 слюнявых вурдалаков на холме Печали.Вернитесь к командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра в Западных Чумных землях.', 'Задание выполнено, $N! Отлично, отлично!$B$BПозволь наградить тебя за труды звонкой монетой из казны Штормграда. Советую потратить награду на подготовку к следующей битве... Ведь тебе придется войти в руины Андорала.$B$BГотовься! Будь бдителен!', NULL, NULL, NULL, 'Скелет-живодер убито', 'Слюнявый вурдалак убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5093, 'Призыв к оружию: Чумные земли!', 'Внимайте моим словам, о герои! Орда призывает к решительным действиям!$B$BВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.$B$BХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лугов!', 'Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лесов и Подгорода.', 'Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5094, 'Призыв к оружию: Чумные земли!', 'Внимайте моим словам, о герои! Орда призывает к решительным действиям!$B$BВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.$B$BХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лугов!', 'Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лесов и Подгорода.', 'Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5095, 'Призыв к оружию: Чумные земли!', 'Внимайте моим словам, о герои! Орда призывает к решительным действиям!$B$BВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.$B$BХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лугов!', 'Найдите верховного палача Деррингтона. Его базовый лагерь расположен в Бастионе к востоку от Тирисфальских лесов и Подгорода.', 'Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5096, 'Вылазка в стан Алого ордена', 'Прежде чем заняться Андоралом, мы должны разобраться с Алым орденом, обосновавшемся в Дольном Очаге. Его приспешники разбили лагерь между полем Джанис и Слезами Далсона, так что мы оказались между двух огней – нам противостоят разом и Плеть, и Алый орден.$B$BМне кажется, надо их стравить между собой. Вот что я хочу тебе поручить: уничтожь командный шатер. Сожги его при помощи пламени в бутылке - вот, возьми в этом ящике. Сделав это, воткни посреди лагеря знамя Плети. При удаче, нас оставят в покое и займутся Плетью.', 'Отправляйтесь в лагерь Алого ордена между полем Джанис и Слезами Далсона и уничтожьте командный шатер.Разместите в лагере знамя Плети и возвращайтесь к верховному палачу Деррингтону в Бастион, в Западные Чумные земли.', 'Отличная работа, $N. Благодаря налету на Алый орден мы выиграли время. Я послал разведчика наблюдать за лагерем, чтобы убедиться, что прибывшее подкрепленея поддастся на провокацию.$B$BЕсли натиск ордена ослабеет, мы сможем рискнуть и устроить вылазку в Андорал. Это очень важно. Я бы хотел, чтобы этим тоже занялся ты – в конце концов, у тебя такой большой опыт.', 'Налет на позиции Алого ордена даст нам время, необходимое для нападения на Андорал. Надеюсь, ты добился успеха?$B$BКоли так, мы должны действовать стремительно и тайно. Если Плеть и Алый орден не поддадутся на провокацию, нам против них не выстоять.', NULL, NULL, 'Унитожить командный шатер и установить знамя Плети в лагере.', 'Знамя Плети', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5097, 'Сторожевые башни', 'Мы можем поменить будущие цели для наших войск при помощи магического устройства, сигнального факела. Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками.$B$BТвоя цель – ворваться в Андорал и установить силнальные факелы на всех четырех башнях. Устанавливать факелы надо в дверных проемах; они сами собой отметят всю башню. В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну.', 'Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен.Отметив все четыре башни, следует вернуть сигнальный факел командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра в Западных Чумных землях.', 'Жрецы говорят, что со всех четырех башен идут четкие сигналы! Боюсь сглазить, но по-моему, ты только что выполнил очередную операцию без сучка, без задоринки! Отлично, $N!$B$BБашни помечены, и все готово к началу атаки. Пришло время сразиться с Плетью!', NULL, NULL, NULL, 'Первая башня отмечена', 'Вторая башня отмечена', 'Третья башня отмечена', 'Четвертая башня отмечена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5098, 'Сторожевые башни', 'Мы можем пометить будущие цели для наших войск при помощи магического устройства, сигнального факела. Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками.$B$BТвоя цель – ворваться в Андорал и установить сигнальные факелы на всех четырех башнях. Устанавливать факелы надо в дверных проемах; они сами отметят всю башню. В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну.', 'Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен.Отметив все четыре башни, следует вернуть сигнальный факел верховному палачу Деррингтону в Бастион в Западных Чумных землях.', 'Чернокнижники говорят, что со всех четырех башен идут четкие сигналы! Ты выполнил мои приказы с точностью, достойной закаленного бойца. Орда не забудет твоей верной службы!$B$BБашни помечены, и все готово к началу атаки. Пришло время сразиться с Плетью!', NULL, NULL, NULL, 'Первая башня отмечена', 'Вторая башня отмечена', 'Третья башня отмечена', 'Четвертая башня отмечена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5101, 'Великое тестовое задание... Судьбы!', 'Ха! Что, думаешь, это тестовое задание? А здесь, между прочим, даже написано, кого надо убить!$B$BДаже не $Nся, что легко отделаешься!$B$BУбей 10 овец (1933) и без их трупов даже не показывайся!', 'Убейте 6 овец для Бенни и бегите со всех ног!Насчет ног я пошутил.', '', NULL, NULL, NULL, 'Овца убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5102, 'Кончина генерала Драккисата', 'Мы бьемся против этих тварей на двух фронтах – из столицы, Штормграда, мы бьем их в спину, а здесь, в Пылающих степях, мы стоим у самого их порога. Не теряй бдительности, $N. Никто не избегнет нашего гнева, как никто из наших не избегнул их гнева, который обрушился на наши дома и семьи.$B$BОтыщи этого генерала Драккисата и убей его!$B$BЗадание непростое, но и награда будет велика.', 'Отправьтесь на пик Черной горы и устраните генерала Драккисата.', 'Следующий удар мы несомненно нанесем по драконьим лордам. Молодец, храбрый солдат Альянса! Отличная работа.', NULL, NULL, NULL, 'Генерал Драккисат убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5103, 'Смерть в огне', 'От человека остался только обугленный скелет. Похоже, он умер буквально на расстоянии вытянутой руки от того, что пытался схватить, – неопалимых латных рукавиц.$B$BМожет, вам стоит забрать рукавицы и попробовать выбраться из огня?', 'Наверняка в этом мире есть кто-то, кто знает, что делать с этими рукавицами.', 'Что это за...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5121, 'Верховный вождь племени Зимней Спячки', 'Хотя нам по-прежнему известно очень мало о том, зачем фурболги используют эту странную субстанцию, я думаю, что лучше всего положить конец всему этому, пока ситуация не вышла из-под контроля.$B$BФурболги племени Зимней Спячки демонстрируют ненормальный уровень агрессии, и эта перемена в их поведении заставляет меня думать, что они, должно быть, выполняют приказ своего вождя. Скорее всего, мы не можем исправить тот вред, что уже нанесен, но я думаю, если их вождь будет убит, хуже они уж точно не станут.$B$BТебе нужно идти на восток, в деревню Зимней Спячки.', 'По просьбе Доновы Снегоноры из Зимних Ключей убейте верховного вождя племени Зимней Спячки.', 'Большое тебе спасибо, $N. Я надеюсь, что смогу вернуться к своим исследованиям, не опасаясь нападения из засады. Пожалуйста, прими это от меня в качестве награды.', NULL, NULL, NULL, 'Верховный вождь племени Зимней Спячки убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5122, 'Медальон веры', '', '', 'Ты принес медальон! Теперь я смогу наконец покинуть священные стены и исполнить свой долг! $B$BЯ должен убить чудовище, из-за которых скверна поразила меня и многих моих братьев и сестер! Имя его – барон Ривендер.', NULL, NULL, NULL, 'Медальон веры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5123, 'Последний фрагмент мозаики', 'Записи, которые вы нашли у верховного вождя, кажутся обширными, но просмотрев пару страниц, вы понимаете, что не можете прочитать написанное. Все заметки написаны так коряво, что вы сомневаетесь, что кто-либо сможет что-то понять в них.$B$BНо, может быть, Донова сможет?..', 'Отнесите неразборчиво исписанный журнал Донове Снегоноре в Зимние Ключи.', 'Что бы это значило? Ничего не могу разобрать…', 'Что это у тебя, $N?', NULL, NULL, 'Неразборчиво исписанный журнал (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5124, 'Огненные латные рукавицы', 'Клянусь бородой Тауриссана! $B$BОткуда они у тебя?$B$BИ, что еще важнее, сможешь ли ты с ними расстаться? Само собой, я заплатил бы за столь благородный жест. $B$BВот что я тебе скажу, $N. Если отдашь мне эти неопалимые рукавицы, я научу тебя, как сделать себе пару хороших рукавиц. Все, что тебе нужно сделать – собрать для меня необходимое, чтобы я мог предложить тебе точный рецепт. $B$BДоговорились??$B$BВот список того, что мне нужно. С тебя – рукавицы, а я пока займусь незачарованным торием.', 'Принесите Малифою Черномолоту 6 зачарованных ториевых слитков, 2 сущности огня и 4 звездных рубина. Вам также нужно будет расстаться с неопалимыми латными рукавицами.', 'Как я и обещал, $N, вот ваш рецепт! Я также добавлю кое-что от себя за ваши труды и самоотдачу. А то просто девать некуда!..', 'Время – деньги, $N. И того, и другого мне всегда не хватает.', NULL, NULL, 'Неопалимые латные рукавицы', 'Зачарованный ториевый слиток', 'Субстанция Огня', 'Звездный рубин');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5125, 'Слова Аурия', '', '', 'Я умираю, $N… но душа моя обрела спасение. Я так многим обязан тебе... Прошу, прими это... И продолжай биться за правое дело, храбрый $C!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5126, 'История Лоракса', 'Сатир расхаживает туда-сюда и разговаривает сам с собой. Решитесь ли вы задать ему вопрос?', 'Поговорите с Лораксом. Выслушайте то, что он вам расскажет.', '*Лоракс смеется.*', NULL, NULL, NULL, 'Выслушайте историю Лоракса.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5127, 'Демонова кузня', 'Лоракс заключает сделки, да, но он не имеет дел с никчемными смертными.$B$BС тобой, однако, я сделку заключу... возьми эту пику, она усилена мощной энергией скверны. Когда найдешь Горалука Разбитую Наковальню, убей его и проткни этой пикой его остывающее сердце. Он продал свою душу, и она будет моей. Верни мне пику, а также кирасу, которую похитил этот вор, и я научу тебя тому, чему хотел научиться он.', 'Отправляйтесь на пик Черной горы и найдите Горалука Разбитую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей.Кроме того, вам нужно найти заготовку рунической кирасы.Отнесите пику и кирасу Лораксу в Зимних Ключах.', 'Ты не нарушил договора. Душу я забрал. Награду я отдам.', 'Не поддайся соблазну…', NULL, NULL, 'Окрашенная душой пика', 'Заготовка рунической кирасы', 'Окровавленная пика', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5128, 'Слова верховного вождя', 'Племя Зимней Спячки больше не представляет для меня угрозы, но если тебе по-прежнему хочется выяснить, что побудило фурболгов готовить и использовать эту странную огненную воду, думаю, вам стоит поискать Келека Стража Неба. $B$BОн принадлежит к группе, известной как Изумрудный Круг – это группа друидов, посвятивших себя работе над исцелением Оскверненного леса от порчи. $B$BКелек много работал с фурболгами – может быть, он сможет больше меня рассказать об этих записях. $B$BИ еще раз спасибо тебе, $N.', 'Отнесите неразборчиво исписанный журнал Келеку Стражу Неба в южную часть Оскверненного леса.', 'Да, если дадите мне немного времени, я, может быть, смогу перевести для вас то, что тут написано. $B$B*Келек пролистывает страницы.*$B$BКогда я смогу внимательно все просмотреть, я вам сообщу.$B$BСпасибо, что поделились этим со мной, $N. О фурболгах из племени Зимней Спячки нет почти никаких сведений.', 'Изумрудный Круг благорасположен ко всем, $C. Чем я могу вам помочь?', NULL, NULL, 'Неразборчиво исписанный журнал (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5141, 'Кожевничество: чешуя дракона', 'Кожевничество школы Дракона – непростое ремесло, однако весьма прибыльное. Я научу тебя изготовлять отличные кольчужные доспехи, но при одном условии. $B$BВыбрав этот путь, ты откажешься от изучения школ традиций предков и силы стихий. На пути к вершине мастерства ты $gдолжен:должна: выбрать лишь одну из трех. Кроме того, я должен взглянуть на лучшие твои работы – в том числе на доспехи скорпида. И наконец, докажи мне, что ты $gспособен:способна: добыть основу нашего ремесла – чешую дракона.', 'Принесите 2 прочные кирасы из панциря скорпида, 2 пары прочных перчаток из панциря скорпида и 10 потертых чешуек дракона Питеру Галену в Азшару. По выполнении этого задания вы получите возможность обучения кожевничеству школы чешуи драконов. Если вы выполните это задание, вы не сможете изучать кожевничество школы традиций предков и школы стихий.', 'Ты принял важное решение. Уверяю тебя, ты не пожалеешь о том, что выбрал школу чешуи драконов – это очень выгодное ремесло. $B$BЧтобы получить новые знания, просто побеседуй со мной, и я расскажу все, что тебе нужно.', 'Если ты готов принять это решение и из трех школ выбрать школу чешуи драконов, то я возьму тебя в ученики. Принеси мне то, что я просил, и мы начнем обучение.', NULL, NULL, 'Прочная кираса из панциря скорпида', 'Прочные перчатки из панциря скорпида', 'Потертая драконья чешуя', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5142, 'Малышка Памела', 'Многие погибли во время битвы при Дарроушире... и многие, избежавшие смерти, позавидовали мертвым.$B$BКогда битва началась, я спрятала мою племянницу Памелу и теперь не знаю, жива ли она. Я всего лишь странствующий дух, но мое сердце жаждет знать, все ли у нее хорошо.$B$BПожалуйста, $gдобрый:добрая:c: $C, не поищешь ли ты мою племянницу в Дарроушире? Это к востоку отсюда, за пустошью Гаррона.', 'Найдите Памелу Редпат в Дарроушире.', 'Привет, я Памела. А ты кто?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5143, 'Кожевничество: традиции предков', 'Чтобы постичь школу традиций предков, следует обрести понимание подлинной сути дикой природы. Я знаю, что ты уже владеешь искусством изготовления доспехов из дикой кожи, и хочу завершить твое обучение.$B$BЗнай, $C: избрав этот путь, ты отказываешься от изучения школ чешуи драконов и стихий, изучать можно только одну из них. А теперь принеси мне свои лучшие доспехи из дикой кожи. С них мы и начнем твое обучение.', 'Принесите ж$N и шлем из дикой кожи Кариссии Лунной Охотнице из Фераласа.Выполнив это задание, вы станете кожевником школы традиций предков.Также вы лишитесь возможности изучать кожевничество школы чешуи драконов и школы стихий; убедитесь, что избрали именно этот путь, прежде чем выполнять задание.', 'Ты пожертвовал лучшее, что у тебя было, и вскоре природа отплатит тебе сторицей. Когда мы завершим твое обучение, силы природы покорятся тебе.$B$BВ будущем, чтобы улучшить свое мастерство, просто обратись ко мне, и я сообщу тебе все, что ты захочешь знать.', 'Силы природы надлежит умиротворить прежде, чем пытаться использовать их в кожевенном деле. Принеси ко мне свою жертву этим силам, и я позабочусь о том, чтобы тебя услышали!', NULL, NULL, 'Жилет из дикой кожи', 'Шлем из дикой кожи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5144, 'Кожевничество: сила стихий', 'Я мастер кожевничества школы Стихии, и если ты хочешь открыть разум великим силам, я поделюсь с тобой всем, что знаю. $B$BНо знай, $C: выбирая этот путь, ты никогда уже не сможешь обучиться кожевничеству школы Дракона и школы традиций предков, ибо из трех школ должно выбрать одну. Кроме того, мне требуется доказательство того, что ты в гармонии со всеми стихиями. Принеси мне чистейшие субстанции огня, воды, земли и ветра.', 'Принесите Саре Дубильщице 2 сердца огня, 2 сферы воды, 2 ядра земли и 2 дыхания ветра. Выполнение этого задания позволит вам изучать кожевничество школы силы стихий. Кроме того, вы откажетесь от изучения кожевничества школ чешуи дракона и традиций предков. Нужно быть уверенным, что выбрана верная школа, прежде чем выполнять задание.', '', NULL, NULL, NULL, 'Сердце огня', 'Магическая сфера воды', 'Ядро земли', 'Дыхание ветра');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5145, 'Кожевничество: чешуя дракона', 'Кожевничество школы Дракона – непростое ремесло, однако весьма прибыльное. Я научу тебя изготовлять отличные кольчужные доспехи, но при одном условии. $B$BВыбрав этот путь, ты откажешься от изучения школ традиций предков и силы стихий. На пути к вершине мастерства ты $gдолжен:должна: выбрать лишь одну из трех. Кроме того, я должен взглянуть на лучшие твои работы – в том числе на доспехи скорпида. И наконец, докажи мне, что ты $gспособен:способна: добыть основу нашего ремесла – чешую дракона.', 'Принесите 2 прочные кирасы из панциря скорпида, 2 пары прочных перчаток из панциря скорпида и 10 потертых чешуек дракона Торкафу Оку Дракона в Бесплодные земли. По выполнении этого задания вы получите возможность обучения кожевничеству школы чешуи драконов. Если вы выполните это задание, вы не сможете изучать кожевничество школы традиций предков и школы стихий.', 'Ты принял важное решение. Уверяю тебя, ты не пожалеешь о том, что выбрал школу чешуи драконов – это очень выгодное ремесло. $B$BЧтобы получить новые знания, просто побеседуй со мной, и я расскажу все, что тебе нужно.', 'Если ты готов принять это решение и из трех школ выбрать школу чешуи драконов, то я возьму тебя в ученики. Принеси мне то, что я просил, и мы начнем обучение.', NULL, NULL, 'Прочная кираса из панциря скорпида', 'Прочные перчатки из панциря скорпида', 'Потертая драконья чешуя', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5146, 'Кожевничество: сила стихий', 'Я мастер кожевничества школы Стихии, и если ты хочешь открыть разум великим силам, я поделюсь с тобой всем, что знаю. $B$BНо знай, $C: выбирая этот путь, ты никогда уже не сможешь обучиться кожевничеству школы Дракона и школы традиций предков, ибо из трех школ должно выбрать одну. Кроме того, мне требуется доказательство того, что ты в гармонии со всеми стихиями. Принеси мне чистейшие субстанции огня, воды, земли и ветра.', 'Принесите Бру$N Заиндевевшему Копыту на нагорье Арати 2 сердца огня, 2 сферы воды, 2 ядра земли и 2 дыхания ветра. Выполнение этого задания позволит вам изучать кожевничество школы силы стихий. Кроме того, вы откажетесь от изучения кожевничества школ чешуи дракона и традиций предков. Нужно быть уверенным, что выбрана верная школа, прежде чем выполнять задание.', 'Ты бросил жребий, и Стихии приняли тебя. Когда я закончу твое обучение, ты овладеешь искусством изготовления наилучших кожаных доспехов.$B$BЧтобы учиться этому искусству и дальше, приходи ко мне, и я разделю с тобой те знания, которые ты захочешь со мной разделить.', 'Изготовление этого типа кожаных доспехов требует терпения и самоотдачи. Когда решаешься связать свою судьбу со Стихиями, спиной к ним уже не повернешься. Принеси мне доказательства того, что ты на что-то годен, – и мы начнем.', NULL, NULL, 'Сердце огня', 'Магическая сфера воды', 'Ядро земли', 'Дыхание ветра');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5147, 'Разыскивается: Арнак Зловещий Тотем', 'Разыскивается: Арнак Зловещий Тотем.$B$BАрнак приговорен к смертной казни по многочисленным обвинениям в убийствах и похищениях. Достойная награда ждет того, кто найдет преступника и приведет приговор в исполнение.$B$BПоследний раз Арнака видели на утесе близ пика Темного Облака. Принесите доказательство его смерти дозорному утесов Долгорогу на заставу Вольного Ветра и получите свою награду.', 'Убейте Арнака Зловещего Тотема и принесите доказательство дозорному утесов Долгорогу на заставу Вольного Ветра.', 'Ха! Что ж, отличные новости! А я уж думал, его никогда не накажут.$B$BДержи награду, $N... И большое спасибо. Признаться, меня приводили в ярость сообщения о его бесчинствах!', 'Есть новости об этом убийце, Арнаке Зловещем Тотеме?', NULL, NULL, 'Копыто Арнака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5148, 'Кожевничество: традиции предков', 'Чтобы постичь школу традиций предков, следует обрести понимание подлинной сути дикой природы. Я знаю, что ты уже владеешь искусством изготовления доспехов из дикой кожи, и хочу завершить твое обучение.$B$BЗнай, $C: избрав этот путь, ты отказываешься от изучения школ чешуи драконов и стихий, изучать можно только одну из них. А теперь принеси мне свои лучшие доспехи из дикой кожи. С них мы и начнем твое обучение.', 'Принесите ж$N и шлем из дикой кожи Кариссии Лунной Охотнице из Фераласа.Выполнив это задание, вы станете кожевником школы традиций предков.Также вы лишитесь возможности изучать кожевничество школы чешуи драконов и школы стихий; убедитесь, что избрали именно этот путь, прежде чем выполнять задание.', 'Ты принес богатые жертвы, и Природа вскоре позволит подчинить себя. Закончив обучение, ты сможешь делать истинные воплощения силы Природы.$B$BКогда решишь поучиться, поговори со мной, и я оделю тебя знаниями, к которым ты будешь готов.', 'Прежде чем научиться подчинять Природу себе, вливая ее силу в кожаные доспехи, тебе следует получше узнать ее. Принеси жертву этой силе, и услышат тебя.', NULL, NULL, 'Жилет из дикой кожи', 'Шлем из дикой кожи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5149, 'Кукла Памелы', 'Тетушка Марлен сказала мне, что я должна остаться дома, пока папа на войне. Мой папа – самый смелый в мире!$B$BНо я здесь уже так долго, а он все не приходит за мной. Иногда сюда приходят злые люди и шепчут. Я так хочу, чтобы папа прогнал их, но его все нет и нет...$B$BА иногда, когда стемнеет, мне так хочется поиграть с моей куклой, но ее тоже нет, она осталась в городе.$B$BПринесешь мне мою куклу?', 'Найдите куклу Памелы.', 'Ты нашел мою куклу! Ура!', 'Ты нашел мою куклу?', NULL, NULL, 'Кукла Памелы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5150, 'Даданга проголодалась!', '', '', 'Даданга с видимым удовольствием принюхивается к побегам. $B$BВ благодарность за лакомство она подталкивает к вам носом маленький коричневый сверток.', NULL, NULL, NULL, 'Побег кровоцвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5151, 'Механизм гипервместимости', 'На наш караван напали кентавры, и выжить удалось только мне! А самый лучший мой механизм висел на шее могучей пантеры-охранницы! Даже кентавры дрожали, увидев эту зверюгу!$B$BВот ключ от ее клетки. Они забрали все, а ключ оставили. Убей пантеру, принеси мне мой гипервместитель, а я хорошо заплачу за него.$B$BТо, что осталось от нашего каравана, находится к северу отсюда.', 'Убейте зверя и принесите механизм гипервместимости и ключ от клетки пантеры Визло Фингалету.', 'Мой гипервместитель! Ну все, теперь с места не сойду, пока не разберусь, зачем же эта штука нужна...', 'Нашелся мой гипервместитель?', NULL, NULL, 'Ключ от клетки пантеры (Прилагается)', 'Механизм гипервместимости', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5152, 'Тетушка Марлен', 'О, я так одинока! Где моя семья? Тетушка Марлен велела мне ждать здесь, ушла и не вернулась. А ты случайно не $gвидел:видела: моего папу?$B$BМожет, тетушка Марлен знает, где он. Она живет рядом с Андоралом, у нее домик на самом юге. Вроде бы он на холме... да, она говорила, что на холме.$B$BПожалуйста, $N! Мы же с тобой теперь друзья? Поговори с моей тетушкой!', 'Поговорите с Марлен в южной части руин Андорала.', 'Ты видел Памелу? Она жива? О, нет! Бедная моя девочка! Она была так мала, так весела и шаловлива...$B$BОна ведь не знает, что стало с ее отцом? С моим братом Джозефом?$B$BОна едва ли сможет это понять... А даже если бы и могла, я не в силах сказать ей об этом.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5153, 'Странный историк', 'Увы, Джозефу не дано воссоединиться с дочерью. Его душа была искажена Плетью, он сам стал чудовищем. Как жестока судьба!$B$BИ все же судьбу можно изменить.$B$BОтправляйся к его монументу и обыщи окрестные могилы. Тела самого Джозефа там нет, однако где-то под монументом лежит его обручальное кольцо. Отнеси кольцо Хроми. Это странная гномесса... с весьма странными способностями.$B$BХроми живет в развалинах таверны в северо-западной части Андорала.', 'Принесите Хроми обручальное кольцо Джозефа.', 'Что это, обручальное кольцо? Дай-ка взглянуть...$B$BКогда-то оно принадлежало великому человеку, однако с ним связано великое зло...$B$BТы хочешь помочь ему? Поздновато собрался, а впрочем... возможно, мы сможем изменить прошлое!', 'Ты очень вовремя. Часом не из будущего явился?', NULL, NULL, 'Обручальное кольцо Джозефа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5154, 'Анналы Дарроушира', 'Чтобы спасти Джозефа Редпата, придется обратиться к его прошлому. Надо прочитать, что говорится о нем в анналах Дарроушира – книге, хранящейся в ратуше Андорала.$B$BПринеси мне книгу. Мы узнаем о судьбе Джозефа и, если повезет сможем... изменить ее.', 'Принесите Анналы Дарроушира Хроми в Андорал. ', 'Прекрасно, ты нашел ее! Что в ней говорится? Там упоминается Джозеф Редпат? Если да, то мы сможем спасти его!$B$BО... В Анналах Дарроушира говорится, что во время битвы Джозеф Редпат пал жертвой порчи и примкнул к войскам Плети, предав защитников Дарроушира!$B$BЧто за горькая судьба! Думаю, мы должны приложить все усилия, чтобы изменить ее.', 'Ты нашел книгу, $N?', NULL, NULL, 'Анналы Дарроушира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5155, 'Силы Джеденара', 'Если уж мне придется положиться на тебя в этом деле, то прежде заслужи доверие.$B$BЯ должна точно знать, что ты – враг Совета Теней, тех, кто в ответе за великие злодеяния здесь и за границами леса.$B$BОтправляйся в чащу Оскверненного леса. На западе ты увидишь тропинку в Джеденар. Именно там Совет строит свои козни вместе с Пылающим Легионом.$B$BПроникни в недра одной из населенных ими оскверненных Обителей и перебей их. Потом вернись ко мне. Тогда я увижу, что ты искренне нам помогаешь.', 'Отправляйтесь в Джеденар и убейте 4 джеденарских гончих, 4 джеденарских стражей, 6 джеденарских адептов и 6 джеденарских сектантов, затем возвращайтесь к Грете Замшелое Копыто в Оскверненный лес.', 'Хорошо, $N! Теперь, когда они уменишились числом, мы усилим натиск.$B$BНу, попробовал их мощь? И как тебе? Они оказались так же сильны, как ты предполагал? Или сильнее? Или, может, они тебе вообще не противники? Разве это не здорово?$B$BМы сможем обсудить подробности твоих подвигов чуть позже. Сейчас у нас другие дела есть.', NULL, NULL, NULL, 'Джеденарская гончая убито', 'Джеденарский страж убито', 'Джеденарский адепт убито', 'Джеденарский сектант убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5156, 'Проверка на порчу', 'На севере отсюда, если идти по восточной дороге, лежит так называемая долина Рваных Ран. Это то место, где во время последнией великой войны призывали инферналов. Там до сих пор поганят землю кратеры – да и сами големы.$B$BЯ хочу узнать две вещи. Во-первых, шляются ли там до сих пор эти энтропийные духи? И второе – до сих ли пор заполнены эти кратеры поганой вонючей водой, что скапливалась в них долгие годы? Поможешь ли ты мне это узнать, $N? Но будь $gосторожен:осторожна: – инферналы уничтожают все на своем пути.', 'Найдите и уничтожьте 2 энтропических зверей и 2 энтропических ужасов при обследовании долины Рваных Ран. После проверьте, по-прежнему ли заполнены кратеры оскверненной водой. Затем возвращайтесь к Таруну Красному Перу в Оскверненный лес.', 'Хорошо, что тебе удалось остаться в живых, $N. Плохо, что вода еще там. Я надеялся найти хоть один чистый источник воды в Оскверненном лесу. Похоже, тут я потерпел неудачу. Будь у нас такой источник, куда проще было бы исцелять землю.$B$BПридется заняться спасением тех лесных существ, что еще можно спасти, по ходу дела истребляя тех, в которых порча зашла так далеко, что они сами стали угрозой и для себя, и для всех, кто оказался в этом некогда великом лесу.', NULL, NULL, NULL, 'Энтропический зверь убито', 'Энтропический ужас убито', 'Исследовать локацию', 'Исследуйте кратеры долины Рваных Ран.');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5157, 'Собрать оскверненную воду', 'Глубоко в недрах Джеденара лежит Оплот Теней – главный оплот порчи и зла.$B$BСовет Теней окружил свое логово защитными заклятьями, заключенными в жаровнях. Если уж мне выпала задача узнать побольше о нашем враге путем магического наблюдения, то тогда мне надо будет, чтобы кто-то потушил эти жаровни. Тогда я смогу тайно понаблюдать за Советом и выяснить, кто его возглавляет.$B$BЕсли сможешь – возьми эту флягу и наполни ее водой из лунного колодца в центре Джеденара. Потом вернись ко мне.', 'Возьмите пустую флягу и наполните ее водой из лунного колодца, что находится в центре Джеденара. Возвращайтесь к Грете Замшелое Копыто в Оскверненный лес.', 'Это то, что надо, $N.$B$BТеперь нам остается только очистить воду и залить ей жаровни. Это будет нетрудно – придеться только совершить небольшое пуешествие.$B$BНадеюсь, это мы провернем быстро.', 'Как только у нас будет вода из Лунного колодца, мы ее очистим и при помощи ее погасим эти жаровни защиты в Оплоте Теней. Это даст мне достаточно времени, чтобы заглянуть в еще более глубокие чертоги и понять, кто же на самом деле возглавляет этот... культ.$B$BМолю Мать-Землю о помощи!', NULL, NULL, 'Оскверненная вода Лунного колодца', 'Пустая фляжка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5158, 'В поисках духовной помощи', 'Отнеси эту оскверненную воду в Степи, $N. К югу от Кабестана на побережье скрытно живет моя старая приятельница, шаманка по имени Ислена Заклинательница Воды. Она может нам помочь. Ее узы с духами воды всегда были крепки. Веди себя благородно – и этого будет достаточно, чтобы убедить ее и духов воды помочь нам в нашем деле.$B$BИщи ее в маленьком лагере прямо у кромки воды. А на пиратов, $N, внимания не обращай... это все мелочи жизни, тебе они не угроза.', 'Отнесите порченую воду из Лунного колодца Ислен Заклинателю Воды в Степи.', 'А, так тебе надо очистить воду из этого Луннного колодца. Благородное дело – остановить порчу, пожирающуюу Оскверненный лес, но не от меня зависит, очистится ли вода. Я спрошу духов воды – это им решать, справедливо ли ваше дело.$B$BПодожди минутку, и я передам им твою просьбу. Надеюсь, они проникнутся к тебе сочувствием, как и я.', 'Чую, ты не простой путешественник, что ищет дорогу в Кабестан. Заходи, садись, отдохни у нас в лагере. Отдохнешь – тогда и поговорим.', NULL, NULL, 'Оскверненная вода Лунного колодца (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5159, 'Чистая вода возвращается в Оскверненный лес', 'Благодари духов, $N. Это они, а не я, помогли тебе.$B$BНыне я отдаю тебе эту очищенную воду. Передай Грете мой поклон и мои наилучшие пожелания. Она нащупала нечто более важное, чем сумели многие из нас... я уверена, что она вскоре все узнает.$B$BС Советом Теней шутки плохи, $N. Запомни это.$B$BТеперь ступай. Бери воду и возвращайся к Грете.', 'Отнесите очищенную воду из лунного колодца Грете Замшелое Копыто в Оскверненный лес.', 'Этой воды для наших целей хватит с избытком.$B$BРада слышать, что Ислен смогла нам помочь. Ее связь с водными духами была всегда прочной. К тому же, она мудра, и духи редко не одобряют ее цели. То, что оба они благословили наше дело, дает мне надежду, что мы идем верным путем.', 'Вижу, ты вернулся, $N. Это хорошо. Ты нашел Ислен в Степях? Или нам придется искать другой путь к нашей цели?', NULL, NULL, 'Очищенная вода из Лунного колодца (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5160, 'Матрона-защитница', 'Тебе придется отправиться в Калимдор, $r. Наша стая сейчас поселилась на холодных просторах Зимних Ключей. Когда доберешься туда, отправляйся в пещеры Маз-Торил.$B$BНа ледяном полу в пещерах ты найдешь письмена из кобальтовых рун. Сожми в руке пластинку моей чешуи, встань на руну – и перенесешься к Хале, нашей матроне-защитнице.$B$BОтдай ей пластинку моей чешуи. Хале посмотрит в нее, как в магический кристалл, и увидит все, что я видел и чувствовал в этом проклятом месте.', 'Дойдите до Зимних Ключей и найдите Хале. Отдайте ей пластину чешуи Ауби.', 'Аспекты настойчиво утверждают, что нам не следует вмешиваться в дела смертных. Но иногда все-таки надо вмешаться – особенно когда кто-то из наших сородичей пренебрегает указами старших.', 'Рада видеть тебя, $N.', NULL, NULL, 'Чешуя Ауби (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5161, 'Гнев синих драконов', 'Мы понимаем, что пытается сделать проклятое порождение Смертокрыла, и мы знаем, что этого нельзя допустить.$B$BНо из-за Черной горы, которая защищает Нефариана, вмешательство стало для нас невероятно трудным.$B$BИ все же мы можем дать силу тебе, смертному существу, если ты решишься на это.$B$BЛежащий перед тобой путь полон опасностей. Примешь ли ты нашу помощь, решать тебе. Обдумай это и поговорим еще раз, когда ты примешь решение', 'Если у вас есть желание продолжить, поговорите снова с Хале', 'Да будет так…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5162, 'Гнев синих драконов', 'Тайные силы контролирую я, и ради тайных сил пошлю я тебя к твоему следующему деянию.$B$BКогда будешь $gготов:готова:, начнется твое путешествие. В Чумные земли лежит твой путь, и с Джезибой надлежит тебе говорить.$B$BЭто смертный, мудрый, как древние предки, и терпеливый, как сама недвижная земля. Ты найдешь его в Андорале.', 'Поговорите с Джезибой в Чумных землях. Он обитает в Андорале.', 'Я Джезиба, многим известный как Скульптор. Правда ваяю я не статуи, а героев.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5163, 'Йети где-то рядом…', 'Все готово, $N!$B$BИтак, я уже сообщила по почте моим друзьям, что у меня для них сюрприз. И тут на сцену выходишь ты!$B$BЯ дам тебе моего механического йети, а тебе нужно будет удивить их, нанеся визит каждому, включив йети и послав его по направлению к ним.$B$BКогда покажешь мое изделие Легакки в Круговзоре, Поливалке в Прибамбасске и Квикксилю в Укрытии Маршалла, возвращайся и расскажи мне, как все было!$B$BИ моего йети тоже, пожалуйста, приведи обратно.', 'Возьмите механического йети Уми и напугайте им ее друзей:- Легакки в Круговзоре (Зимние Ключи), - Поливалку в Прибамбасске (Танарис), - Квикксиля в Укрытии Маршалла (Кратер Ун\'Горо)Когда проделаете все это, принесите механического йети обратно Уми.', 'Ха! Они теперь дважды подумают, прежде чем снова высмеивать мои идеи!$B$BСпасибо за помощь, $N. Без тебя мне не удалось бы так развлечься!', 'Жду, не дождусь, так хочется услышать, как реагировали мои друзья!$B$BТакого они никак не могли ожидать!', NULL, NULL, 'Напугайте Легакки', 'Напугайте Поливалку', 'Напугайте Квикксиля', 'Механический йети Уми (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5164, 'Перечень Заблудших', 'Хале не могла отыскать лучшего орудия справедливости. Прочти перечень Заблудших и обрети просветление.$B$BЕсли ты выстоишь... Если ты сделаешь то, о чем тебя просят и выживешь... Из тебя выйдет герой.', 'Прочитайте перечень Заблудших.', 'Книга состоит по большей части из сотен страниц, исписанных словами и символами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5165, 'Погасить Пламя Защиты', 'Теперь тебе надо вернуться в Джеденар. Эти жаровни скорее всего расставлены в Оплоте Теней. Загаси их пламя, и защита, возведенная Советом, хотя бы на некоторое время падет. Я буду ждать этого мгновения. Когда оно настанет, я загляну в недра оплота и попытаюсь узнать, кто стоит во главе всего этого. Тогда – и только тогда – мы попытаемся атаковать их напрямую.', 'При помощи очищенной воды из лунного колодца загасите пламя в четырех жаровнях защиты внутри Оплота Теней в Оскверненном лесу. Затем возвращайтесь к Грете Замшелое Копыто в Изумрудное святилище.', 'Я сумела увидеть тебя при помощи своих заклинаний, как только погасли жаровни. Славная работа, $N.$B$BИ я успела кое-что узнать прежде, чем чернокнижники Совета Теней восстановили свои заклинания. Надеюсь, этого будет достаточно.$B$BТеперь отдыхай. Я сейчас расскажу тебе, что я узнала.', NULL, NULL, NULL, 'Погасите жаровню Боли', 'Погасите жаровню Злобы', 'Погасите жаровню Страдания', 'Погасите жаровню Ненависти');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5166, 'Кираса Всецветных драконов', 'По иронии судьбы, на изготовление мощной кирасы, призванной защитить от нападения всецветных драконов, идут их собственные шкуры.$B$BНа безупречную шкуру всецветного дракона нашивают их же чешую. В настоящий момент этих тварей не существует, и хочется верить, что и не будет.$B$BПоследний компонент, который труднее всего достать – это кровь героев.$B$BИ наконец, из этих компонентов Скульптор создает подлинный шедевр.', 'Джезиба \"Скульптор\" может сковать кирасу Всецветных драконов, если вы принесете ему следующее:1 всецветный панцирь.10 сверкающих всецветных чешуек.10 порций крови героев.10 истлевших шовных нитей поганища.', 'Неужели ты не понимаешь? Сам путь и был целью. Неужели тебя не тревожат шрамы? И боль забыта?$B$BВыстояв в испытании, ты сделался сильнее. Гораздо сильнее. И кираса – лишь внешнее проявление внутренней мощи.', 'Ты сделал правильный выбор, $C.', NULL, NULL, 'Всецветный панцирь', 'Сверкающая многоцветная чешуя', 'Кровь героев', 'Истлевшая шовная нить поганища');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5167, 'Ножные латы всецветного воина', 'На изготовление этих поножей идут взрослых всецветных драконов. Переливчатую чешую закрепляют на проволочной основе и зачаровывают, окропляя кровью героев. В конце следует обтянуть поножи изнутри шкурой тени.', 'Джезиба \'Скульптор\' может сковать ножные латы Всецветного воина, если вы принесете ему следующее:1 всецветный панцирь.10 сверкающих всецветных чешуек.10 порций крови героев.5 шкур тени.', 'Когда ты войдешь в их чертоги, они почуют запах павших братьев. Пусть страх станет твоим оружием!', 'Свет не видывал таких поножей!', NULL, NULL, 'Всецветный панцирь', 'Сверкающая многоцветная чешуя', 'Кровь героев', 'Шкура тени');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5168, 'Герои Дарроушира', 'Герои Дарроушира навсегда поселились в моем сердцу, а эта книга, анналы Дарроушира, рассказывает об их жизни.$B$BЗдесь рассказывается о паладине Дейвиле Яркосвете и о том, как Алый орден забрал его манускрипт в ратушу Дольного Очага.$B$BЗдесь также говорится о моем брате, капитане Редпате. После его предательства, его щит раскололся и развалился на куски, и теперь лежит в самом неожиданном месте – рядом с амбаром в пустоши Гаррона.$B$BСобери эти реликвии, $N.', 'Принесите книгу Дейвила и щит Редпата Карлину Редпату.', 'Это книга и щит!$B$BОни тесно связаны с историей Дарроушира, и я уверен – эта история еще не закончена.', 'Ты собрал реликвее, $N?', NULL, NULL, 'Манускрипт Дейвила', 'Щит Редпата', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5181, 'Негодяи Дарроушира', 'В Анналах Дарроушира упоминается о самых мерзких воинах, бившихся в том сражении. Там рассказывается о том, как Альянс разбил силы лорда Хоргуса Опустошителя. Тело его было брошено в озеро к северо-западу от Перекрестка Корина, и череп его поныне там. $B$B$Nук Черный так и не был побежден, но его легендарный меч был сломан и потерян. Он лежит на дне ущелья к западу от Перекрестка Корина.$B$BПринеси мне эти предметы, $N. Не знаю почему, но твоя судьба связана с ними.', 'Принесите череп Хоргуса и сломанный меч $Nука Карлину Редпату в часовню Последней Надежды.', 'Ты нашел их! Прекрасно, $N! В этих предметах заключена великая сила, и однажды ты сможешь овладеть ею.$B$BОднако они навевают на меня печальные воспоминания о потерянных близких и о предательстве...', 'Ты принес мне череп и меч, $N?', NULL, NULL, 'Череп Хоргуса', 'Сломанный меч Мардука', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5201, 'Вторжение племени Зимней Спячки', 'Мое присутствие здесь мало кто замечает, $N. Однако, существует одна неприятность, укроненившаяся в Зимних Ключах: это фурболги из племени Зимней Спячки.$B$BХотя лично я никогда не атаковал фурболгов, они выглядят безумными и боятся всего, что им встречается на пути. Я видел, как они убивали бесчисленное количество существ, чья вина состояла лишь в том, что они оказались не в то время и не в том месте.$B$BМне все это уже поперек горла – пожалуйста, помоги мне нанести им ответный удар. Убивай фурболгов и не подпускай их к Уступу ледопардов.', 'По заданию Риверна Холодного Ветра убейте 5 шаманов и 5 ведмедей из клана Зимней Спячки.', 'Меня невероятно радует, что хотя бы на короткое время мы можем забыть о вторжении фурболгов племени Зимней Спячки.$B$BЯ начинаю замечать вашу настойчивость, $N.', NULL, NULL, NULL, 'Шаман из племени Зимней Спячки убито', 'Ведмедь из племени Зимней Спячки убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5202, 'Странный красный ключ', 'Маленький красный ключ сделан из какого-то материала, похожего на кость. Он тяжел, но на вид кажется хрупким. Зачем прислужнику Совета Теней этот предмет? Возможно, этот странный ключ открывает какой-то замок в Джеденаре?', 'Обыщите Джеденар и найдите замок, который открывается странным красным ключом.', 'Ключ! Ты его нашел! Пожалуйста, дай его мне, и я, наконец, освобожусь!', 'Смогу ли я хоть когда-нибудь вырваться из этой клетки?$B$BРано или поздно они принесут меня в жертву своим демонам. Чудовища!', NULL, NULL, 'Кроваво-красный ключ (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5203, 'Спасение из Джеденара', 'Но, как бы мне это ни было тяжко, в первую очередь мне нужно сделать вот что: найти меч Трея, именуемый Светлая Сталь и сбежать из Оплота Теней, чтобы рассказать моим командирам, что здесь творится. Ты поможешь мне, $N?$B$BНаше снаряжение тут неподалеку, а ты уже $gпоказал:показала:, что сумеешь выбраться наверх.$B$BКогда мы выберемся отсюда, я направлюсь в Дарнас, если ты сможешь найти мою подругу Джессир на границе с Ясеневым лесом. Она должна была встретить нас у лагеря Изумрудного Круга неподалеку отсюда.$B$BЧто скажешь, $N? Поможешь мне еще раз?', 'Сопроводите Арко\'нарин туда, где лежат меч Светлая Сталь и снаряжение Арко\'нарин, и защитите ее при побеге из Оплота Теней. Потом разыщите Джессиру Лунную Радугу в Оскверненном лесу и расскажите ей, что случилось с ее друзьями.', 'Так это ты помог Арко спастись? Как я рада увидеть тебя! Она не так давно проходила мимо этих мест в Дарнасс. Она несла Светлую Сталь и у нее не было даже времени поговорить с друидами, чтобы те ее исцелили. Говорила, что дело слишком спешное.$B$BНо все же она рассказала мне о твоей встрече с духом Трея. Какая страшная судьба для рыцаря Серебряной Длани! Она, конечно, не подает виду, но я знаю, что ее душа разрывается от потери одного из ближайших друзей...', NULL, NULL, NULL, 'Защитите Арко\'нарин при побеге из Оплота Теней.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5204, 'Воздаяние Света', 'Она делает вид, что с ней все в порядке. Ей хочется, чтобы я думала, будто она сама сумеет справиться с горем, но я же не слепая. Смерть Трея и его крики под пытками, которым его подвергали, долго мучили ее, и мы ничем не могли ей помочь. Но мы все же можем дать ей хоть немного покоя!$B$B$N, вернись в Оплот Теней, убей мучителя Трея и найди его останки. Почему бы нам самим не покончить с этим, пока Арконарин оплакивает своего друга?', 'Вернитесь в Джеденар и убейте суккуба Ракайю, затем отыщите останки Трея Светогорна.', 'Вы как можно осторожнее собираете останки паладина, сознавая, что его хотя бы его дух свободен от мучений, которым его подвергали.', 'Вы осматриваете тело. Вне всякого сомнения, это был рыцарь Серебряной Длани, Трей Легкий Горн. На мгновение вы вспоминаете об Арконарин и задумываетесь – нет ли в вашей жизни того, кто значил бы для вас столько же, как этот человек для недавно спасенной вами из Оплота Теней ночной эльфийки?$B$BСобравшись с мыслями, вы понимаете, что вы не понесете останки паладина к Джессир, пока не убьете его мучителя.', NULL, NULL, 'Ракайа убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5206, 'Мародеры Дарроушира', 'Хроми утверждает, что собранные тобой реликвии могут служить реагентами для мощных чар. Однако требуется еще один ингредиент: черепа воинов Плети, участвовавших в битве при Дарроушире.$B$BВозьми этот кристалл и отправляйся за черепами лучших воителей Плети. Кристалл заколдован: он резонирует, если поднести его к черепу воителя, участвовавшего в битве.$B$BИди, $N. Ты найдешь воителей Плети на Ядовитой поляне к северу отсюда и в Грибной долине на западе.', 'Принесите 5 резонирующих черепов и загадочный кристалл Карлину Редпату в Восточные Чумные земли.', 'Отлично, у нас есть черепа!$B$BХоть я и не совсем понимаю, зачем именно они нужны, я чувствую исходящую от них силу и то, что они связаны с моей родной деревней, Дарроушир.', 'Ты принес черепа? Хроми говорит, они необходимы для заклятия, а заклятие поможет нам спасти Дарроушир.', NULL, NULL, 'Резонирующий череп', 'Загадочный кристалл (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5210, 'Брат Карлин', 'С помощью магии я дополнила анналы Дарроушира – теперь они содержат сведения и о том, что случилось после битвы. И там говорится, что еще один из рода Редпатов пережил предательство Джозефа. Его имя Карлин, он сейчас в восточных пределах Чумных земель, в часовне Последней Надежды.$B$BОтправляйся к нему и передай ему книгу.', 'Отнесите дополненные анналы Дарроушира Карлину Редпату в Восточные Чумные земли.', 'Что это за книга? Анналы Дарроушира? О, там был мой дом... пока не пришла Плеть! Зачем ты принес мне эту книгу?$B$BЧто это? Смотри, на последних страницах рассказывается о том, что случилось уже после битвы! Здесь говорится и обо мне, и о моем брате Джозефе... Неужели это правда?$B$BЯ должен знать!', 'Ты пришел с запада? Что там происходит? Я знаю, что Андорал пал, но добралось ли воинство Плети до Тирисфаля?', NULL, NULL, 'Дополненные анналы Дарроушира (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5211, 'Защитники Дарроушира', 'Многие защищавшие Дарроушир пали в битве. И многие из них восстали из мертвых, примкнув к Плети! Ты $gдолжен:должна: отыскать эти несчастные души и избывить их от страданий.$B$BКаннибалы-вурдалаки, бормощущие вурдалаки, болезненные живодеры – многие из них были добрыми жителями Дарроушира. Уничтожив их тела, ты освободишь их души.$B$BТы найдешь их в Проклятом лесу, Перекрестке Корина и прочих опорных пунктах Плети в Восточных Чумных землях.', 'Освободите 15 дарроуширских духов и возвращайтесь к Карлину Редпату.', 'Рад слышать, что истерзанные души моих сородичей с твоей помощью обрели свободу. Ты пролил бальзам на мои раны – теперь я знаю, что хоть кто-то из моих павших сородичей освободился от ига Плети.', 'Несчастные защитники Дарроушира взывают ко мне в моих снах, $N. Освободи их!', NULL, NULL, 'Освободите дарроуширских духов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5212, 'Плоть не лжет', 'Аптекари Отрекшихся не единственные в этом мире, кто искушен в науках.$B$BЯ уже много лет изучаю эту заразу, $r. Ранее я полагала, что активность чумы со временем уменьшается, однако то, что наблюдается в Чумных землях, поражает воображение.$B$BЗдесь вирус со временем становится все более активным!$B$BЯ должна продолжать исследования! Вирус наиболее активен в певые дни после заражения, поэтому мне нужны образцы тканей, пораженных совсем недавно. Отправляйся в Стратхольм и снабди меня препаратами для исследований, $N.', 'Принесите 10 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, сойдут ткани любой твари из Стратхольма.', 'В химическом составе вируса приизошли какие-то изменения. Я должна продолжать исследования.', 'Некоторые считают, что у меня параноя, а я вот отвечу: \"Бди! Вирус не дремлет!\"', NULL, NULL, 'Образец чумной плоти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5213, 'Вирус чумы', 'Тебе предстоит углубиться еще дальше в кварталы Стратхольма, $N. B$BЗа первыми воротами ты увидишь зиккураты. Известно, что твари Плети черпают из этих сооружений великую силу. Обыщи зиккураты и расскажи мне обо всем, что там увидишь.', 'Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк.', 'Потрясающе! Теперь я должна как следует изучить эти данные – это может потребовать нескольких месяцев. Серебряный Рассвет приносит тебе огро$Nю благодарность, $N.$B$BТебе будет дарована печать Рассвета или руна Рассвета на твой выбор. И то, и другое можно использовать вместо Жетона Серебряного Рассвета для сбора знаков различия Плети. Если потеряешь, обращайся ко мне за заменой.', 'Мы на пороге открытия! Скоро мы узнаем, на чем основана устойчивость вируса чумы.', NULL, NULL, 'Сведения о Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5214, 'Великий Эзра Гримм', 'То, что произошло с Эзрой, поистине ужасно! Город осаждала нежить, но Эзра не хотел бросать свою лавку превосходного табака. Последнее, что он сказал мне: \"Я не уйду, пока не сожгу все до последнего листочка, чтобы ничего не осталось врагу!\"$B$BЯ тоже знаю толк в хорошем табаке, но не готов расстаться с жизнью ради каких-то сушеных листьев, пусть и наивысшего качества. Хотя... может там и вправду что-то уцелело?$B$BЧто скажешь, $N? Не поищешь табачку для старины Дымка?', 'Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней коробку отличного табака Эзры Гримма и принесите ее Дымку ЛаРу.', 'О, мои милые папироски, как я по вам скучал...', 'Я сам не справлюсь, $N! Помоги старику...', NULL, NULL, 'Отличный табак Гримма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5215, 'Котлы Плети', 'В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и еще четыре – на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети.$B$BКел\'Тузад слишком силен, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, верховная жрица Макдонелл, поможет тебе выполнить задание; она продолжит инструктаж.', 'Поговорите с верховной жрицей Макдонелл на Берегу Промозглого Ветра в Западных Чумных землях.', 'Да осияет тебя Свет в наши темные времена, $C. Я рада, что смогу помочь тебе в борьбе с планами Плети.$B$BНаша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети. Для этого придется взять пробы из всех котлов в Западных Чумных землях.$B$BГотовься к славной битве против жестокой Плети!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5216, 'Цель: поле Джанис', 'Из четырех котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать.$B$BОтправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества.', 'Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.', 'Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает. И все же, кажется, отныне вы сможете открывать панель доступа без ключа. Изнутри доносится гнусный запах. В котле бурлит смесь неизвестных веществ.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', NULL, NULL, 'Ключ к котлу на поле Джанис', 'Пустая бутылка с поля Джанис (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5217, 'Возвращение в Лагерь Промозглого Ветра', 'Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить.$B$BЗаполучив яд, пора возвращаться к верховной жрице Макдонелл в лагерь Промозглого Ветра.', 'Принесите полную бутылку с поля Джанис верховной жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.', 'Молодец, $N! Алхимик Арбингтон мигом проведет анализ этой дряни и составит противодействующее вещество. Надо будет внести его в котел и постараться, чтобы побольше испарений попало в воздух. Кто знает, может удастся ослабить Плеть.$B$BЭто будет нелегко – придется постоянно устраивать набеги на котлы и добавлять в них необходимые реагенты. И все же у нас есть шанс получить в решающей битве преимущество перед Плетью!', 'Добро пожаловать в Лагерь Промозглого Ветра, $N. Наслаждайся ощущением безопасности. Как дела с котлами?', NULL, NULL, 'Полная бутылка с поля Джанис (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5218, 'Котел поля Джанис', '', '', 'Добавив в котел все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров. Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь.', NULL, NULL, NULL, 'Чародейский ускоритель', 'Костяной катализатор', 'Руническая ткань', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5219, 'Цель: Слезы Далсона', 'Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слезы Далсона. Но сегодня не время лить слезы, $C. Мы должны нанести удар по котлу и получить к нему доступ!$B$BОтправляйся в Слезы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлят свои яды.', 'Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.', 'Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает. Вы получили постоянный доступ у котлу. По переплетенным трубкам течет гнусная тягучая жижа.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', NULL, NULL, 'Ключ к котлу на поле Слез Далсона', 'Пустая бутылка с поля Слез Далсона (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5220, 'Возвращение в Лагерь Промозглого Ветра', 'Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить.$B$BЗаполучив яд, пора возвращаться к верховной жрице Макдонелл в лагерь Промозглого Ветра.', 'Принесите полную бутылку с поля Слез Далсона верховной жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.', 'А, мне будет чем заняться. Молодец, $N!$B$BИтак, следующий шаг ясен. Мы должны составить список компонентов, которые будет необходимо смешать с зельем чумы, чтобы добиться от него обратного действия.$B$BДля этого придется поместить эти составляющие непосредственно в котел. Аптекарь Арбингтон знает гораздо больше чем я, поэтому в ближайшее время поговори с ним.', 'Мы знаем, что в каждом из котлов замешаны составляющие, распространяющие заразу. Также нам известно, что нужно для составления противоядий для каждого из котлов. Какие компоненты нужны для котла с поля Слез Далсона не определить без образца зелья. Действуй.', NULL, NULL, 'Полная бутылка с поля Слез Далсона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5221, 'Котел Слез Далсона', '', '', 'Добавив в котел все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров. Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь.', NULL, NULL, NULL, 'Чародейский ускоритель', 'Соматический усилитель', 'Руническая ткань', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5222, 'Цель: Удел Страданий', 'Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остается еще два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!$B$BНа сей раз твоя цель – котел Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла.$B$BДоброй охоты, $N!', 'Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.', 'Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз. Внутри бурлит омерзительно пахнующая жидкость.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', NULL, NULL, 'Ключ к котлу Удела Страданий', 'Пустая бутылка с Призрачной фермы (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5223, 'Возвращение в лагерь Промозглого Ветра', 'Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке.$B$BЗаполучив яд, пора возвращаться верховной жрице Макдонелл в Лагерь Промозглого Ветра.', 'Принесите полную бутылку с Призрачной фермы верховной жрице Макдонелл в Лагерь Промозглого Ветра, в Западные Чумные земли.', 'Еще одно задание выполнено без сучка, без задоринки! Итак, у нас есть доступ вот уже к трем котлам! Если бы не страшная некромантская власть Кел\'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их!$B$BАлхимик Арбингтон вскоре сообщит, что требуется добавить в этот котел – и другие, подвластные нам – чтобы справиться с чумой нежити. Итак, настало время добраться до последнего из западных котлов!', 'Как только мы исследуем образец из котла Удела Страданий, у нас появится третий способ нанести сокрушительный урон Плети, подобрав правильное противодействующее вещество!', NULL, NULL, 'Полная бутылка с Призрачной фермы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5224, 'Котел Удела Страданий', '', '', 'Добавив в котел все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров. Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь.', NULL, NULL, NULL, 'Чародейский ускоритель', 'Соматический усилитель', 'Руническая ткань', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5225, 'Цель: пустошь Гаррона', 'Последний оставшийся котел находится на ферме, которая теперь зовется пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, $N.$B$BПустошь Гаррона находится далеко на востоке от Бастиона, близко от границы Восточных Чумных земель. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни ее из котла и принеси мне. Да укроет тебя тьма своим крылом, $C.', 'Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с путоши Гаррона.', 'Коснувшись панели доступа у основания, ключ Хранителя котла Душегнева исчезает. Раздается негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', NULL, NULL, 'Ключ к котлу на пустоши Гаррона', 'Пустая бутылка с пустоши Гаррона (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5226, 'Возвращение в лагерь Промозглого Ветра', 'Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку.$B$BЗаполучив яд, пора возвращаться к верховной жрице Макдонелл из лагеря Промозглого Ветра.', 'Отнесите полную бутылку с пустоши Гаррона высшей жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.', 'Поздравляю, $N, тебе удалось обеспечить нам доступ к последнему из котлов! Аптекарь Арбингтон вскоре составит список компонентов, которые необходимо добавить в него.$B$BЧто до тебя, я не сомневаюсь, что командир Отважный Кулак пожелает лично поблагодарить тебя за помощь. Без тебя наша борьба с Плетью была обречена. Спасибо, ты настоящий герой.', 'На пустоши Гаррона находится последний котел на западе, к которому у нас еще нет доступа. Получив образцы зелья чумы из этого котла, мы сможем внести необходимые компоненты в четыре сосуда! Плети придется нелегко, когда мы доберемся до всех четырех котлов, даже сила Кел\'Тузада ее не спасет.', NULL, NULL, 'Полная бутылка с пустоши Гаррона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5227, 'Котел пустоши Гаррона', '', '', 'Добавив в котел все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров. Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь.', NULL, NULL, NULL, 'Чародейский ускоритель', 'Эктоплазматический резонатор', 'Руническая ткань', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5228, 'Котлы Плети', 'В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и еще четыре – на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети.$B$BКел\'Тузад слишком силен, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, жрица Тьмы Вандис, поможет тебе выполнить задание; она продолжит инструктаж.', 'Поговорите со жрицей Тьмы Вандис в Бастионе, что в Западных Чумных землях.', 'Да благословит тебя Тьма, брат $R. Я помогу тебе организовать нападение на котлы Плети.$B$BНаша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети. Для этого придется взять пробы из всех котлов в Западных Чумных землях.$B$BТебя ждет героическая схватка с Плетью!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5229, 'Цель: поле Джанис', 'Из четырех котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать.$B$BОтправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества.', 'Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.', 'Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает. И все же, кажется, отныне вы сможете открывать панель доступа без ключа. Изнутри доносится гнусный запах. В котле бурлит смесь неизвестных веществ.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис с вершины Холодного Ветра не составляет труда.', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', NULL, NULL, 'Ключ к котлу на поле Джанис', 'Пустая бутылка с поля Джанис (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5230, 'Возвращение в Бастион', 'Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить.$B$BПора возвращаться к жрице Тьмы Вандис в Бастион.', 'Принесите полную бутылку с поля Джанис жрице Тьмы Вандис в Бастион, что в Западных Чумных землях.', 'Молодец, $N! Аптекарь Дитерс мигом проведет анализ этой дряни и составит противодействующее вещество. Надо будет внести его в котел и постараться, чтобы побольше испарений попало в воздух. Кто знает, может удастся ослабить Плеть.$B$BЭто будет нелегко – придется постоянно устраивать набеги на котлы и добавлять в них необходимые реагенты. И все же у нас есть шанс получить в решающей битве преимущество перед Плетью!', 'Добро пожаловать в Бастион, $N. Наслаждайся ощущением безопасности. Как дела с котлами?', NULL, NULL, 'Полная бутылка с поля Джанис (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5231, 'Цель: Слезы Далсона', 'Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слезы Далсона. Но сегодня не время лить слезы, $C. Мы должны нанести удар по котлу и получить к нему доступ!$B$BОтправляйся в Слезы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз, и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлит свое варево.', 'Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.', 'Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает. Вы получили постоянный доступ у котлу. По переплетенным трубкам течет гнусная тягучая жижа.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', NULL, NULL, 'Ключ к котлу на поле Слез Далсона', 'Пустая бутылка с поля Слез Далсона (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5232, 'Возвращение в Бастион', 'Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить.$B$BПора возвращаться к жрице Тьмы Вандис в Бастион.', 'Отнесите полную бутылку с поля Слез Далсона жрице Тьмы Вандис в Бастион в Западных Чумных землях.', 'А, мне будет чем заняться. Молодец, $N!$B$BИтак, следующий шаг ясен. Мы должны составить список компонентов, которые будет необходимо смешать с зельем чумы, чтобы добиться от него обратного действия.$B$BДля этого придется поместить эти составляющие непосредственно в котел. Аптекарь Дитерс знает гораздо больше чем я, поэтому в ближайшее время поговори с ним.', 'Мы знаем, что в каждом из котлов замешаны составляющие, распространяющие заразу. Также нам известно, что нужно для составления противоядий для каждого из котлов. Какие компоненты нужны для котла с поля Слез Далсона не определить без образца зелья. Действуй.', NULL, NULL, 'Полная бутылка с поля Слез Далсона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5233, 'Цель: Удел Страданий', 'Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остается еще два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!$B$BНа сей раз твоя цель – котел Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее.И вновь тебе придется убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла.$B$BДоброй охоты, $N!', 'Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.', 'Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз. Внутри бурлит омерзительно пахнующая жидкость.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', NULL, NULL, 'Ключ к котлу Удела Страданий', 'Пустая бутылка с Призрачной фермы (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5234, 'Возвращение в Бастион', 'Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке.$B$BПора возвращаться к жрице Тьмы Вандис в Бастион.', 'Принесите полную бутылку с Призрачной фермы жрице Тьмы Вандис в Бастион, что в Западных Чумных землях.', 'Еще одно задание выполнено без сучка, без задоринки! Итак, у нас есть доступ вот уже к трем котлам! Если бы не страшная некромантская власть Кел\'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их!$B$BАптекарь Дитерс вскоре сообщит, что требуется добавить в этот котел – и другие, подвластные нам – чтобы справиться с чумой нежити. Итак, настало время добраться до последнего из западных котлов!', 'Как только мы исследуем образец из котла Удела Страданий, у нас появится третий способ нанести сокрушительный урон Плети, подобрав правильное противодействующее вещество!', NULL, NULL, 'Полная бутылка с Призрачной фермы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5235, 'Цель: пустошь Гаррона', 'Последний оставшийся котел находится на ферме, которая теперь зовется пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, $N.$B$BПустошь Гаррона находится далеко на востоке от Бастиона, близко к границам Восточных Чумных земель. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни ее из котла и принеси мне. Да укроет тебя тьма своим крылом, $C.', 'Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с путоши Гаррона.', 'Коснувшись панели доступа у основания, ключ хранителя котла Душегнева исчезает. Раздается негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тьмы Вандис из Бастиона не составляет труда.', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', NULL, NULL, 'Ключ к котлу на пустоши Гаррона', 'Пустая бутылка с пустоши Гаррона (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5236, 'Возвращение в Бастион', 'Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку.$B$BПора возвращаться к жрице Тьмы Вандис в Бастион.', 'Отнесите полную бутылку с пустоши Гаррона жрице Тьмы Вандис в Бастион в Западных Чумных землях.', 'Поздравляю, $N, тебе удалось обеспечить нам доступ к последнему из котлов! Аптекарь Дитерс вскоре составит список компонентов, которые необходимо добавить в него.$B$BЧто до тебя, я не сомневаюсь, что верховный палач Деррингтон пожелает лично поблагодарить тебя за помощь. Без тебя наша борьба с Плетью была обречена. Спасибо, могучий $C.', 'На пустоши Гаррона находится последний котел на западе, к которому у нас еще нет доступа. Получив образцы зелья чумы из этого котла, мы сможем внести необходимые компоненты в четыре сосуда! Плети придется нелегко, даже сила Кел\'Тузада ее не спасет.', NULL, NULL, 'Полная бутылка с пустоши Гаррона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5237, 'Задание выполнено!', '', '', 'Успешная диверсия против всех котлов – огромная победа!*Командир откашливается и оглушительно орет.*Слушайте, слушайте все! За верную и преданную службу королевству Штормграда и Альянсу, за выполнение долга и даже более того – перед лицом невероятной опасности, отметим – я вручаю $N награду и передаю ему нашу вечную благодарность. Он – истинный герой Альянса. Ура!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5238, 'Задание выполнено!', '', '', 'Успешная диверсия против всех котлов – огромная победа!*Верховный палач откашливается и оглушительно орет.*Слушайте, слушайте все! За верную и преданную службу Отрекшимся и Орде, за выполнение долга и даже более того – перед лицом невероятной опасности, отметим – я вручаю $N награду и передаю ему нашу вечную благодарность. Он – истинный герой Орды. Ура!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5241, 'Дядюшка Карлин', 'Ты знаешь, иногда по ночам мне слышится плач дядюшки Карлина – как будто бы плач доносится откуда-то издалека, с востока.$B$BА вдруг он плачет обо мне... $N, пожалуйста, разыщи моего дядюшку и скажи ему, что со мной все в порядке.$B$BСкажи, что я здесь, жду его и очень скучаю по сказкам, которые он рассказывал мне на ночь... особенно той, про кроликов и черничное варенье. Она была такая забавная!', 'Найдите Карлина Редпата.', 'Ты видел Памелу? Она жива?$B$BПогибла?! Бедная моя девочка! За что твой дух осужден скитаться в этом жестоком мире... Почемы тебя не стало во цвете лет, а я все еще копчу небо! Как бы я хотел вместо тебя отдать жизнь и призраком бродить по руинам Дарроушира!$B$BСудьбу не изменить... Спасибо тебе, $N. Теперь мой долг – месть, я осознаю это ясно как никогда.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5242, 'Окончательный удар', 'Увы, я вижу только один путь покончить с угрозой Оскверненному лесу – прямую атаку. Других путей в Оплот Теней нет, телепортировать тебя внутрь я тоже не могу. Единственный путь – прямой путь в бездну... и я также знаю, кого тебе следует искать в этой бездне. Его зовут Скверн\'дан... Владыка теней Скверн\'дан. Его власть там, внизу, смертоносна... Он – голова змеи. Убей его и двух его суккубов-прислужниц, и вернись ко мне. Это Скверн\'дан заключил союз с Легионом. Его надо остановить!', 'Убейте Моору и Салию и принесите голову владыки теней Скверн\'дана Грете Замшелое Копыто в Оскверненный лес.', 'Хвала Матери-Земле, $N! Хвала тебе! Воистину, великий день!$B$BСовет Теней вряд ли сможет снова обрести ту власть которой обладал до того, как ты нанес удар по их иерархии. Великое дело ты ныне свершил!', 'Теперь, без Фел-дана, Совет Теней потеряет цель и будет беспомощен. Они перегрызутся между собой за власть и сокровища – плату за будущие планы. А мы воспользуемся этим времением и вырежем и их, и их рабов-демонов.', NULL, NULL, 'Моора убито', 'Салия убито', 'Голова Владыки теней Скверн\'дана', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5243, 'Святая вода', 'Я склонен рассматривать свое бытие в форме нежити как род болезни, $r. Болезни, которая требует лечения. Впрочем, для Серебряного Рассвета это не болезнь, а истинное благословение. Действительно, нет лучше орудия против язычников Плети, чем нежить.$B$BКоллеги чтят меня за мои деяния, однако почести ничего не значат для меня.$B$BЕсли ты хочешь содействовать делу Серебряного Рассвета, у меня есть для тебя работа.$B$BОтправляйся в Стратхольм и пополни наши запасы святой воды. Искать ее следует в брошенных ящиках с припасами.', 'Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Барталомею Чтимому, как только воды будет достаточно.', 'Отлично, $R. Ты доказал, что терпим к ближнему и непримирим в борьбе против приспешников Кел\'Тузада.', 'Учти, далеко не все ящики припасов в разрушенном городе остались в целости и сохранности. Воины Плети боятся святой воды, однако она не является препятствием для диких зверей.', NULL, NULL, 'Святая вода Стратхольма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5244, 'Руины Кел\'Терила', 'История Кел\'Терила – это история проклятой расы, прикованной к месту, где был совершен неудавшийся ритуал…$B$BВысокорожденные, которых вы найдете там, когда-то похитили священный артефакт, будучи уверенными, что смогут вытянуть его мощь, перелить ее в себя и стать еще более могущественными. Из-за их действий реликвия взорвалась, а куски ее ушли под лед озера...$B$BЕсли хотите узнать больше, поговорите с Джероном Гранильщиком. Он был там недавно и сможет рассказать вам обо всем.', 'Поговорите с Джероном Гранильщиком в деревне Звездопада.', 'Ну, конечно, я могу подробно рассказать про Кел\'Терил. Имей в виду, я не историк – но могу рассказать тебе о том, что я сам там видел…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5245, 'Беспокойные духи Кел\'Терила', 'Несчастные существа эти духи высокорожденных, что и говорить. Они все еще ищут части самой вещи, которая навсегда привязала их к Кел\'Терилу, эту похищенную у них реликвию.$B$BЕсли тебе это интересно, можешь взять мою кирку и отправляться на юг к озеру, чтобы попытаться достать части этого артефакта изо льда.$B$BЯ не могу сказать что именно ты найдешь, но Аврора Зов Небес наверняка сможет; она живет около башни Северного Перевала в северной части Восточных Чумных земель.', 'Используйте кирку Джерона, чтобы добыть фрагменты реликвии высокорожденных, Принесите их Авроре Зов Небес в Восточные Чумные земли.', 'Прошлое Высоких Эльфов не лучшая тема для беседы, $N. Мне до сих пор больно думать об этом... И самое главное, уже невозможно ничего исправить.', 'Что привело тебя сюда?', NULL, NULL, 'Первый фрагмент реликвии', 'Второй фрагмент реликвии', 'Третий фрагмент реликвии', 'Четвертый фрагмент реликвии');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5246, 'Фрагменты прошлого', 'Я не понимала… Простите мои жестокие слова, $C.$B$BЯ не хочу вспоминать об ошибках своих предков, но если ваша просьба искренна, я помогу.$B$B*Аврора изучает фрагменты.*$B$BЯ уверена, что это – Кристалл Зин-Малора, артефакт, содержащий в себе могучие силы тайной магии. Возможно, его использовали и во благо, но из-за злых намерений тех, кто его похитил, кристалл раскололся.$B$BОтправляйтесь в Храм Зин-Малор в Азшаре – я могу лишь надеяться, что книга все еще там.', 'Найдите Священные письмена высокорожденных в Храме Зин-Малор, в Азшаре и принесите их Авроре Зов Небес к Башне Северного перевалa, в Восточных Чумных землях.', 'Этих страниц долгие годы никто не касался…', 'Лишь по страницам священных записей я разберу, смогу ли помочь вам или нет…', NULL, NULL, 'Священные письмена высокорожденных', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5247, 'Фрагменты прошлого', 'Я смогу помочь тебе, если воссоздание артефакта действительно является твоим желанием.$B$BЧтобы воссоединить фрагменты, мне потребуются вещи, обладающие сильными магическими свойствами. Слитки зачарованного тория и пять кристаллов восстановления… Также тебе нужно будет набрать воды из... необычного источника... Найди Зловещий пруд на Пути Элдрета в Забытом Городе, что в Фераласе, и наполни этот фиал.$B$BПока тебя не будет, я попытаюсь извлечь из этих страниц знание, как восполнить урон, нанесенный реликвии.', 'Принесите зачарованный слиток тория, 5 кристаллов восстановления и фиал пугающей воды Авроре Зов Небес к башне Северного Перевала, в Восточных Чумных землях.', 'Используя эти компоненты, я сумею снова соединить эти фрагменты… надеюсь, получится именно то, чем эта реликвия когда-то являлась.', 'Реликвия должна быть в руках только того, кто заслуживает абсолютного доверия. Она не должна быть вновь похищена…', NULL, NULL, 'Зачарованный ториевый слиток', 'Кристалл восстановления', 'Фиал пугающей воды', 'Пустой фиал для воды');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5248, 'Измученный воспоминаниями о прошлом', '$N, Я скорблю о том, что раса эльфов была разрушена, подобно этому кристаллу. Я не знаю, соберутся ли когда-нибудь эти осколки воедино, и все же то, что я могу помочь тебе, уменьшает мою скорбь.$B$BМы не должны забывать о прошлом, $N...$B$BПожалуйста верни кристалл Зин-Малора к озеру Кел\'Терил. Найди там духа высокорожденного, который, так же как и я, сожалеет о допущенных ошибках и скажи ему, что мы стремимся все исправить.', 'Отнесите кристалл Зин-Малора к озеру Кел\'Терил в Зимних Ключах и найдите духа высокорожденного, который согласится с вами поговорить.', 'Оссстаааввь меняяяя...', 'Прррроооокляааат.. Навееечноооо...', NULL, NULL, 'Кристалл Зин-Малора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5249, 'В Зимние Ключи!', 'В Зимних Ключах, к северу отсюда, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.$B$BРабота здесь отнимает все мое время, так что у меня давно уже не было возможности самой добраться до Зимних Ключей. Но вам-то ничто не мешает!$B$BКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в деревне Звездопада и очень много знает о тех местах.', 'Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.', 'Друг Иви Росистой Листвы? Приятно познакомиться, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5250, 'Звездопад', 'В Зимних Ключах, к северу от Оскверненного леса, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.$B$BЯ так занята своими исследованиями здесь, что у меня давно уже не было возможности самой добраться до Зимних ключей. Но у вас-то нет никаких причин для отказа от путешествия туда и изучения руин.$B$BКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в Звездопаде и очень много знает о том районе.$B$BСкажите ему, что вы $gмой ученик:моя ученица:.', 'Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.', 'Ученик Дарин Доброго Ветра? Приятно познакомиться с вами, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5251, 'Архивариус', 'Впадать в крайности всегда опасно, $N. Взять, к примеру, Алый орден. Неужели такой слепой фанатизм способен привести к чему-то хорошему? Скольких невинных убили они во имя Света.$B$BЭто просто святотатство!$B$BВот что, один из этих негодяев мне особенно интересен – это архивариус Галфорд из Стратхольма. Этот человек отвечает за самые ценные документы ордена. Уничтожь его и сожги его архивы! Если справишься с этим, получишь достойную награду.', 'Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алого ордена.', 'Отличная работа, $N! Ты уничтожил разведданные, собираемые Алым орденом годами! Алые будут в ярости...', NULL, NULL, NULL, 'Архивариус Галфорд убито', 'Архив сожжен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5252, 'Раскаявшийся высокорожденный', 'Кри… кристалл…$B$BЗдешние высокорожденные находятся в плену их жалкого сущессствования…$B$BЯ полон горрречи, но я понимаю, в чем моя ошибка. И хотя изменить прошлое нееевозможно, теперь я обрел покой, зная, что тебе удалосссь добыть кристалл Зин-Малора...$B$BТы $gдолжен:должна: вернуть крисссталл...$B$BОн должен быть воззвращен.', 'Поговорите с Вундом Ночным Охотником в деревне Звездопада и узнайте у него, куда нужно поместить кристалл Зин-Малора.', 'Это… это то, что я думаю?', 'Прошло довольно много времени после твоего ухода, $N. Как прошло путешествие?', NULL, NULL, 'Кристалл Зин-Малора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5253, 'Кристалл Зин-Малора', 'Впечатляюще, $N. $B$BКристалл Зин-Малора никогда не вернется в храм, лежащий в руинах. Но я полагаю, что твои усилия уничтожить зло минувших лет не должно пойти прахом.$B$BНайди верховного друида Фэндрала Оленьего Шлема в Дарнасе, $N, и отдай ему кристалл. Он должен находится в руках тех, кто не злоупотребит его мощью. К тому же только самые сильные маги смогут управиться с артефактом такой мощи.', 'Доставьте Кристалл Зин-Малора верховному друиду Фэндралу Оленьему Шлему в Дарнас.', 'Я слышал о кристалле Зин-Малора. Его обладатель получает практически неограниченную магическую мощь, но только если он достоин этого. Я впечатлен – вы не только умудрились добыть кристалл, вы еще и достаточно мудры, чтобы не пытаться его использовать самостоятельно.$B$BСпасибо, что принесли его мне, Драккард. Мы сохраним его, и пусть духи, охранявшие кристалл все это время, наконец-то обретут покой.', 'Да, $R?', NULL, NULL, 'Кристалл Зин-Малора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5261, 'Иган Меховщик', 'Иган Меховщик ищет охотника на зараженных волков. Это добрая новость, поскольку в последнее время в Долине Североземья появилось слишком много больных животных.$B$BЕсли тебе это интересно, то поговори с Иганом. Он за углом аббатства, если свернуть налево.', 'Поговорите с Иганом Меховщиком.', 'Что? Ищу ли я охотников на волков? Ну да, так и есть. А ты, наверное, ищешь работу?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5262, 'Ошеломляющая истина', 'В воздухе еще вихрится пыль, а вы пытаетесь собраться с мыслями и осознать произошедшее. И все же весь ужас вашего положения все же не укладывается в голове.$B$BВерховный рыцарь оказался демоном! И не просто демоном, а братом самого Вариматраса, верховного правителя Подгорода.$B$BВы бережно укладываете голову повелителя ужаса в суму. Разумеется, никто не поверит рассказанному вами без вещественных доказательств.$B$BНадо сообщить герцогу Николасу Зверенхоффу как можно скорее!', 'Отнесите голову Балназзара герцогу Николасу Зверенхоффу в Восточные Чумные земли.', 'Неужели все это время Алым Маршем правил демон! Все это время они служили злу, сами не подозревая об этом!', 'С чем пожаловал, $N?', NULL, NULL, 'Голова Балназзара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5263, 'Быстрее, выше, сильнее', 'Ты $gпроявил:проявила: прирожденную склонность к разрушению и умеешь следовать приказам. Эти похвальные качества весьма редко сочетаются. Полагаю, ты можешь стать совершенным орудием высшего промысла.$B$B*Зверенхофф сжимает кулаки*$B$BКел\'Тузад усадил своего мальчика на побегушках править в Стратхольме. Докажи мне свою верность и доблесть. Уничтожь барона Ривендера и принеси мне его голову.', 'Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу.', 'Давно мне не приходилось объявлять о новых героях. Ты ты будешь первым, кого лорд Максвелл удостоит аудиенции за много лет.', 'На руках барона кровь стольких людей, скольких ты не видел в своей жизни.', NULL, NULL, 'Голова барона Ривендера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5264, 'Лорд Максвелл Тиросс', 'Тебе оказана большая честь, $N.$B$BЛорд Максвелл хочет наградить тебя за твои заслуги перед Серебряным Рассветом!$B$BПоверь мне, это большая честь – Максвелл уже много лет не удостаивал никого аудиенции.', 'Поговорите с лордом Максвеллом Тироссом. Вы найдете его внутри храма.', 'Ты для нас очень ценный союзник, $N, и ты получишь достойную награду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5265, 'Серебряный Оплот', 'Серебряный Оплот уже много лет закрыт и запечатан. Много лет не находилось достойных войти в него и прикоснуться к силе Серебряного Рассвета – до сегодняшнего дня.$B$BСеребряный Оплот распахнул врата перед тобой, $N.', 'Откройте Серебряный Оплот и получите награду.', 'Ух ты...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5281, 'Мятущиеся души', 'Многие погибли во время битвы при Стратхольме. Многие предпочли расстаться с жизнью, бросившись в пламя пожара, чем повергнуться порче и примкнуть к Плети.$B$BТеперь они скитаются по улицам Стратхольма в обличье бесплотных призраков.$B$BМы должны помочь им, $N.$B$BУ меня есть помощник по имени Эган, он спец по призракам и духам. Найди его. Он, вероятно, сейчас в Восточных Чумных землях близ Стратхольма, проверяет свои изобретения.', 'Найдите Эгана. В последний раз его видели недалеко от Стратхольма.', 'Неужели Ален нашел кого-то, у кого будет довольно храбрости помочь мне?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5282, 'Мятущиеся души', 'Только безграничная ненависть к Плети поддерживает во мне силы и желание жить. Но я не фанатик. Не такой, как этот сброд из Алого ордена – они скорее убьют невинную нежить, чем удостоят хоть каплей сочувствия.$B$BВозьми мой излучатель. С его помощью ты сможешь освободить истерзанные души, обреченные на скитания в Стратхольме.$B$BСтреляй в призраков, бродящих по улицам. Освободи их!', 'Стреляйте в фантомных и призрачных горожан на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.Освободите 15 неупокоенных душ и возвращайтесь к Эгану.', '*Эган утирает скупую слезу*$B$BВидел ли ты мою матушку, $N? Она обрела свободу?$B$BТы просто образец благородства. Прими эту скромную награду за труды...', NULL, NULL, NULL, 'Освобождено душ', 'Самострел Эгана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5283, 'Искусство школы Брони', 'Ты $gпринял:приняла: верное решение.$B$BМы со стариной Железнусом друг друга не перевариваем. Этот кустарь косорукий знает, кто тут настоящий мастер.$B$BВеликие войны не выигрываются без хорошего доспеха. Когда дойдет до дела, никакой меч не спасет.$B$BИ никак иначе, так что возьмемся-ка за работу. Тебе нужно только показать мне, что у тебя есть природный талант к делу. Потом я выкую из тебя настоящего бронника и как следует отшлифую. Знаешь, как делать мифрил изысканным, а?', 'Изготовьте и отдайте Грумнусу 4 изысканных мифриловых шлема, 2 пары изысканных мифриловых сапог и 1 изысканную мифриловую кирасу.', 'Самое оно, $N. Теперь уж нельзя останавливаться. Нет, еще не поздно перейти на отковку шпилек, э-э-э, в оружейники податься.$B$BНо я уверен, что ты сделал верный выбор.', 'Ах, нет ничего краше доброго кузнечного загара. Сразу видно, у кого славный загар, по белым полосам от передника.', NULL, NULL, 'Изысканный мифриловый шлем', 'Изысканные мифриловые сапоги', 'Изысканная мифриловая кираса', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5284, 'Путь оружейника', 'Если станешь кузнецом, то к тебе очень часто будут обращаться за снаряжением всякие там герои и искатели приключений. Хотя порой работы невпроворот, спина ноет и дышать нечем, плата покрывает все с лихвой.$B$BДа, вот еще, $N, у кузнецов всегда водится золотишко!$B$BЕсли хочешь стать $gодним:одной: из нас, тебе придется доказать, что ты сможешь заработать для меня пару звонких монет – то есть показать, что ты $gусвоил:усвоила: все, чтобы стать специалистом по изготовлению оружия высшего качества. Приступай к работе!', 'Сделайте и отдайте Железнусу 4 палаша из лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 большие черные палицы.', 'Как раз вовремя! Заказчики уже ждут.$B$BДавай сюда свои изделия да слушай внимательнее. Сейчас ты делаешь первый шаг в карьере оружейника.', '*Железнус деловито складывает золотые монеты в аккуратные столбики.*', NULL, NULL, 'Палаш из лунной стали', 'Массивный железный топор', 'Тяжелый мифриловый топор', 'Большая черная палица');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5301, 'Искусство изготовления брони', 'Моя работа приносит мне подлинное удовлетворение! Когда я вижу гордого воина Орды, защищенного моими доспехами, я понимаю, зачем родился на свет. Это как наваждение, $N, я без этого просто жить не могу.$B$BКонечно, этому я тебя научить не смогу – я могу только указать тебе путь. Ведь кузнечное ремесло, как и любая жизненная стезя, – это путешествие.$B$BЕсли ты хочешь стать $gодним:одной: из избранных, я, конечно, готов тебя учить. Но сначала тебе нужно выполнить мое задание.', 'Чтобы присоединиться к школе брони, изготовьте и отдайте Окотосу 4 изысканных мифриловых шлема, 2 пары изысканных мифриловых сапог и 1 изысканную мифриловую кирасу.', 'Это последний шаг перед тем, как ты начнешь свою новую карьеру в школе Брони, $N. Если ты колеблешься, сейчас твой последний шанс отступить. А иначе готовься к жизни, полной славы!', 'Я буду ковать сталь, пока мое дыхание не иссякнет.', NULL, NULL, 'Изысканный мифриловый шлем', 'Изысканные мифриловые сапоги', 'Изысканная мифриловая кираса', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5302, 'Путь оружейника', 'В один прекрасный день я создам легендарный молот. Молот, достойный вождя!$B$BЭто труд всей моей жизни, $N. Мое главное и единственное увлечение. Я вижу, что ты можешь стать $gодним:одной: из нас – оружейником! И я помогу тебе в этом, если хочешь.$B$BТебе нужно только выполнить простое задание. При твоем мастерстве оно и впрямь несложное.', 'Изготовьте и отдайте Боргошу 4 палаша из лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 больших черных палицы.', 'Это последний шаг перед тем, как ты начнешь свою новую карьеру оружейника, $N. Если ты колеблешься, сейчас твой последний шанс отступить. А иначе готовься к жизни, полной познания!', 'Во славу Орды!', NULL, NULL, 'Палаш из лунной стали', 'Массивный железный топор', 'Тяжелый мифриловый топор', 'Большая черная палица');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5305, 'Секрет безмятежности', 'В казематах бастиона Алого ордена таится секрет Безмятежности. Молотобоец из Багрового легиона охраняет эту тайну. Срази его и принеси мне его фартук. За это я наделю тебя знанием о том, как изготовить зачарованный боевой молот!', 'Отправляйтесь в Стратхольм и убейте молотобойца из Багрового легиона. Возьмите его фартук и возвращайтесь к Лилит.', '', NULL, NULL, NULL, 'Фартук молотобойца из Багрового легиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5306, 'Змеекамень Пленяющей Духов', 'Пусть ее красота не обманывает тебя, $C. Темная охотница Вош\'гаджин безумна и смертельно опасна. $B$B<Килрам указывает на шрам у себя на лице.>b$BДа, это ее рук дело – \"удар любви\", как она выразилась. $B$BНаконец настал момент для отмщения. $B$BВош\'гаджин ты найдешь на пике Черной горы. Убей ее и принеси мне ее змеекамень. Сделай это, и я научу тебя секретам изготовления клинка рассвета.', 'Отправляйтесь на Пик Черной горы, убейте Те$Nю охотницу Вос\'гаджин. Заберите у нее змеекамень и принесите Килраму.', 'Ты уверен. что тебе нужна именно эта школа? Помни, что это закроет для тебя возможность вступить в школу Меча или Молота.', 'Легенда гласит, что если хотя бы раз применить змеекамень Вос\'гаджин, лезвие топора останется острым на тысячу лет!', NULL, NULL, 'Змеекамень Вос\'гаджин', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5307, 'Порча', 'Если я краток, на то есть причины. Чертежи для создания великого меча, Порчи, были похищены Черной стражей: элитным отрядом скелетов барона Ривендера. $B$BДа, именно, Ривендера из Стратхольма.. $B$BОружейник Черной стражи хранит теперь эти чертежи как зеницу ока.$B$BУбей его и принеси доказательство его смерти, и в благодарность я научу тебя всему, что нужно для изготовления пылающей рапиры!', 'Найдите в Стратхольме оружейника Черной Стражи и уничтожьте его. Возьмите его Знак Черной Стражи и принесите Сирилу Плетебою.', '', NULL, NULL, NULL, 'Знак отличия Черной Стражи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5321, 'Спящий пробудился', 'Я шел к Заставе Мейстры, чтобы встретиться с Лиладрис Лунная Река, но решил остановиться здесь и немного вздремнуть. С тех пор как я очнулся от Изумрудного Сна, я все время такой сонный...$B$B*зевает*$B$BНе откажетесь проводить меня? Я так понимаю, Застава Мейстры находится к югу отсюда, в Ясеневом лесу, у дороги. Путь может быть опасен; я надеюсь, у вас есть друзья, которые смогут составить нам компанию.$B$BДа, и вот еще что: я могу заснуть по дороге, так что если вам нужно будет меня разбудить, сделайте это с помощью моего рога. Он в этом сундуке.', 'Сопроводите Керлониана Вечный Сумрак к Лиладрис Лунной Реке на Заставу Мейстры в Ясеневом лесу.', 'О, я так рада, что Керлониан смог сюда добраться. И я уверена, что найду его спящим где-нибудь поблизости, ведь так?$B$BСпасибо вам за то, что показали ему дорогу, $N.', 'Прибыл ли Керлониан?', NULL, NULL, 'Рог Пробуждения', 'Сопроводите Керлониана Вечный Сумрак на Заставу Мейстры.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5341, 'Сокровище Баровых', 'В Некроситете находятся сокровища семейства Баровых. Я, Алексий Баров, один из двух оставшихся наследников нашего дома. Второй – мой брат, Велдон.$B$BЭтот жалкий трус бежал во время войны и по-прежнему длит свое никчемное существование в человеческом обличье.$B$BСейчас он ищет документы, чтобы унаследовать все состояние. Доберись до этих документов раньше моего брата, и я озолочу тебя!', 'Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову.', 'Отличная работа, $R. Теперь главное – подтвердить мое право наследования...', 'Кланяйся, $R. В конце концов, я дворянин, а ты – деревенщина без гроша за душой.', NULL, NULL, 'Документы на Брилл', 'Документы на Каэр Дарроу', 'Документы на Южнобережье', 'Документы на Мельницу Таррен');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5342, 'Последний из Баровых', 'Естественно, пока мой брат жив, могут возникать вопросы о порядке наследования. Я не допущу этого.$B$BПолагаю, ты, шваль, не побоишься замарать руки убийством.$B$BЗадание простое, надеюсь, ты справишься; если хочешь получить награду.$B$BВелдон сидит под крылышком у Альянса в лагере Промозглого Ветра на востоке. Убей его и принеси мне голову.$B$B<Алексий зевает.>$B$BДавай-давай, иди.', 'Отправляйтесь в лагерь Промозглого Ветра – на земли Альянса – и убейте Велдона Барова. Отнесите его голову Алексию Барову.Соблюдайте осторожность – скорее всего, Велдона охраняет мразь из Альянса.', 'Чудесно! Теперь лишь в моих руках мощь и все сокровища дома Баровых.$B$B*Алекси швыряет в вас большим мешком.*$B$BСдачу оставь себе, животное.', 'Обеспечишь мне получение наследства, получишь свою долю.', NULL, NULL, 'Голова Велдона Барова', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5343, 'Сокровище Баровых', 'Милый братец Алексий. И зачем я, глупец, пощадил его? Я смотрел в лицо врага, нежити, и оставил его в живых.$B$B<Велдон сплевывает.>$B$BОн хочет отобрать МОЕ наследние. Не бывать тому!$B$BНайди документы на мои владения, прежде чем эта мерзость дотянется до них своими костлявыми ручками, и получишь большую награду. Документы находятся в руинах Некроситета. Спеши!', 'Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Вэлдону Барову.', 'Я хочу дать тебе еще одно задание, $R.', 'Позаботься о моей будущем, а я позабочусь о твоем.', NULL, NULL, 'Документы на Брилл', 'Документы на Каэр Дарроу', 'Документы на Южнобережье', 'Документы на Мельницу Таррен');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5344, 'Последний из Баровых', 'Документы у меня в руках, осталось только одно. Алексия придется убить. Когда он умрет, я смогу вздохнуть спокойно, не ожидая гибели от руки наемного убийцы.$B$BЗадание простое. Алексий находится под покровительством Орды – в Бастионе.$B$BНет, я не требую, чтобы ты прямо $gвзял и убил:взяла и убила: его, мне голова нужна! А как ты ее получишь... твое дело. Подобные размышления ниже моего аристократического достоинства.', 'Отправляйтесь в Бастион – на земли Орды – и убейте Алексия Барова. Отнесите его голову Вэлдону Барову.Соблюдайте осторожность – скорее всего, Алексия охраняет ордынская мразь.', 'О радость, о счастье! Наконец-то черная овца в стаде семьи Баровых мертва, и я получил наследство!$B$BВозьми деньги и убирайся, деревенщина.', 'Ты хочешь денег, да?', NULL, NULL, 'Голова Алексия Барова', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5361, 'Семейное древо', 'Мой брат, Натака, находится на Заставе Скитающихся Духов в Пустошах. Я хотел бы попросить вас... не доставите ли ему этот отчет? С тех пор, как я писал ему последний раз, прошел целый год, и вот сейчас кентавры опять что-то затевают. Мой брат должен узнать обо всем.$B$BВам нужно будет отправиться в Каменный Коготь – это горы к северу от Перекрестка, а потом свернуть на запад, в Обугленную долину. Пустоши находятся южнее долины. Следуйте по дороге на юг, и скоро увидите Заставу Скитающихся Духов.', 'Доставьте отчет дозорного утесов Долгорога Натаке Длинному Рогу на Заставу Скитающихся Духов в Пустоши.', 'Не знаю, как вы связаны с моим братом, но, вижу, он вам доверяет, $C.$B$BЯ – Натака Длинный Рог, и я приветствую вас на Заставе Скитающихся Духов! Воин нам здесь точно не помешает. Поговорите с другими, наверняка у них найдется работа для вас.', 'Что у вас за новости, $C? Ах, неужели это письмо от моего брата? Ну что ж, давайте его сюда!', NULL, NULL, 'Отчет дозорного утесов Долгорога (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5381, 'Рука Ируксоса', 'В руки клана Пылающего Клинка попала демоническая шкатулка, в которой хранится могущественный артефакт – рука Ируксоса. Орки из клана Пылающего Клинка используют ее, чтобы открывать демонические порталы на поле Маннорок. Мы должны остановить нашествие демонов, захлестывающее наш мир, $N!$B$BРасколи красный кристалл в крепости Громового Топора этой киркой демонов: так ты сможешь добыть демоническую шкатулку.', 'Добудьте в крепости Громового Топора демоническую шкатулку, а затем принесите ее и кирку демонов Тайге Мудрой Гриве в деревню Ночных Охотников.', 'О, Демоническая шкатулка... Наконец-то я увидел ее. Послушай, $C, дай-ка ее мне, и я ее открою... и покажу тебе Руку Ируксоса.', 'Эй, $N, а где Демоническая шкатулка?', NULL, NULL, 'Демоническая шкатулка', 'Кирка демона (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5382, 'Доктор Теолен Крастинов – Мясник', 'Крастинов виновен в тысячах смертей. Справедливость должна восторжествовать – пусть он вкусит собственного блюда.$B$BНайди его и заставь испытать мучения его бессчетных жертв. Когда он умрет, сожги наши останки. Пусть обратятся в пепел, $N.', 'Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.', 'Душа моя исцелена, $N. Ты оказал нам с мужем огро$Nю услугу, но это еще не все.', 'Мясника должно остановить!', NULL, NULL, 'Доктор Теолен Крастинов убито', 'Останки Евы Саркофф сожжены', 'Останки Люсьена Саркоффа сожжены', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5383, 'Мешок ужасов Крастинова', 'Вы открываете мешок. Внутри – различные инструменты пытки. Ваше внимание привлекает странный предмет – сосуд крови, все еще теплый.$B$BПожалуй, Саркофф могла бы заинтересоваться вашей находкой.', 'Отнесите мешок ужасов Еве Саркофф в Каэр Дарроу.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5384, 'Киртонос Глашатай', 'Вот она, $N.$B$B*Ева указывает на сосуд в мешке.*$B$BКровь невинных. Чистейшая кровь, умилостивление хозяина Крастинова.$B$BПри помощи этой крови можно вызвать Киртоноса, и именно она поможет его уничтожить.$B$BОтнести эту кровь на балкон, помести в жаровню. Киртонос явится на зов – он не сможет устоять. Когда он явится, обрушь на него ярость и гнев тысяч невинно убиенных.$B$BЕсли ты добьешься успеха, мы на славу отблагодарим тебя.', 'Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.Сражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф.', 'Киртонос мертв, и страшная глава истории Некроситета подошла к концу. Но твои деяния не окончены. Многие узнали о твоих подвигах. Возьми это, $N. Это часть нашей сущности. При ее помощи ты сможешь связаться с другими павшими душами Каэр Дарроу.', 'Соблюдай осторожность, Киртонос – опытный боец.', NULL, NULL, 'Киртонос Глашатай убито', 'Невинная кровь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5385, 'Останки Трея Светогорна', 'Вы осторожно поднимаете мешок и собираетесь возвращаться к Джессире Лунной Радуге на границу Ясеневого леса и Оскверненного леса. Вы надеетесь, что паладин будет с почестями погребен, когда его останки будут доставлены его друзьям.', 'Принесите останки Трея Светогорна Джессире Лунной Радуге в Оскверненный лес.', 'Тебе удалось! Хвала Элуне и всем силам, что ты почитаешь, $N! Сегодня ты совершил деяние благое и почетное. Я уверена, что Арконарин возрадуется, узнав, что ты не только спас ее, но так же убил тварь, которая истязала одного из лучших ее друзей.$B$BЯ бы хотела сделать для тебя больше, но прошу тебя – прими эту скромную награду.', 'Как дела в Джеденаре, $N?', NULL, NULL, 'Останки Трея Светогорна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5386, 'Дорога рыбка к обеду', 'Давненько на заставе Скитающихся Духов не наслаждались запахом жареной рыбки... Тролли, живущие в деревне Ночных Охотников – отличные рыбаки, вот только из-за разбушевавшихся в наших краях кентавров мне никак не выкроить времени, чтобы добраться до них.$B$BПослушай-ка, окажи мне услугу: отправляйся в деревню Ночных Охотников. Разыщи там Джинар\'Зиллена, потолкуй с ним и принеси мне рыбок-кровобрюхов: я их просто обожаю! На юг отсюда идет дорога: она приведет тебя аккурат в деревню троллей.', 'Отправляйтесь в деревню Ночных Охотников и поговорите с Джинар\'Зилленом, а затем принесите Натаке Длинному Рогу 2 рыбы-кровобрюха.', 'Ты просто спас меня, $N! А эти кровобрюхи так хороши, что хоть сырыми их ешь.$B$B*Натака сглатывает слюну.*$B$BНу, давай, давай скорее, выбери один из этих предметов в уплату за рыбу!..', 'У меня копыта подергиваются и слюни текут от нетерпения, как подумаю о жареном кровобрюхе... Ты ведь принес мне кровобрюха, верно?', NULL, NULL, 'Рыба-кровобрюх', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5401, 'Жетон Серебряного Рассвета', '', '', 'Все, кто сражаются со злом во имя Серебряного Рассвета, должны получить наш амулет. Он даст тебе право получать награды у наших интендантов.Пока ты носишь его на шее, ты сможешь собирать камни Плети с убитой нежити; да-да, иногда они носят такие знаки различия. Собирай их и приноси мне. За каждый набор ты получишь по знаку доблести Серебряного Рассвета – так мы благодарим наших героев.Ступай навстречу судьбе – вступай в битву со злом!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5402, 'Камни приспешников плети', '', 'Камни Плети приспешников – знаки различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово \"слабый\" – относительное понятие. Не стоит недооценивать Плеть. От имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.', 'Поздравляю, $N – и с радостью вручаю тебе знак доблести Серебряного Рассвета!$B$BЭти знаки служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережем для самых преданных наших сторонников. Во-вторых – их можно отдавать нашим интендантам вместе с деньгами и получать ценные предметы, которые изготовляют в нашем ордене.$B$BТак или иначе, ты их заслужил сполна. Молодец!', NULL, NULL, NULL, 'Камень приспешника Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5403, 'Камни захватчиков Плети', '', 'Камни Плети приспешников – знаки различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.В настоящий момент Серебряный Рассвет предлагает по знаку доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.', 'Поздравляю, $N – и с радостью вручаю тебе знак доблести Серебряного Рассвета!$B$BКаждый выданный знак доблести приближает час победы над Плетью! Все больше героев вступают в бой с Плетью на ее землях, и Серебряный Рассвет несомненно будет в первых рядах той армии, что решится положить конец бесчинством прихвостней Повелителя Тьмы. Надеюсь, твоей доблести хватит и до того дня!', NULL, NULL, NULL, 'Камень захватчика Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5404, 'Камни осквернителей Плети', '', 'Камень Плети Осквернителя – знак различия предводителей Плети. Он есть у каждого обладающего властью в Плети. Убийство этих проклятых тварей служит благу Серебряного Рассвета... да и вообще всеобщему благу!От имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, $N – с этими тварями шутки плохи.', 'Поздравляю, $N – и с радостью вручаю тебе знак доблести Серебряного Рассвета!$B$BТе, кто удостаивается этих знаков – подлинные борцы за добро. Мы благодарны всем, кто выступает против Плети, но убийство одного из ее главарей – настоящий подвиг и тяжелейший удар по нашему противнику!$B$BЗа Рассвет, брат мой!', NULL, NULL, NULL, 'Камень осквернителя Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5405, 'Жетон Серебряного Рассвета', '', '', 'Все, кто сражаются со злом во имя Серебряного Рассвета, должны получить наш амулет. Он даст тебе право получать награды у наших интендантов.Пока ты носишь его на шее, ты сможешь собирать камни Плети с убитой нежити; да-да, иногда они носят такие знаки различия. Собирай их и приноси мне. За каждый набор ты получишь по знаку доблести Серебряного Рассвета – так мы благодарим наших героев.Ступай навстречу судьбе – вступай в битву со злом!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5406, 'Камни осквернителей Плети', '', 'Камень Плети Осквернителя – знак различия предводителей Плети. Он есть у каждого обладающего властью в Плети. Убийство этих проклятых тварей служит благу Серебряного Рассвета... да и вообще всеобщему благу!От имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, Херин – с этими тварями шутки плохи.', 'Поздравляю, $N– и с радостью вручаю тебе знак доблести Серебряного Рассвета!$B$BТе, кто удостаивается этих знаков – подлинные борцы за добро. Мы благодарны всем, кто выступает против Плети, но убийство одного из ее главарей – настоящий подвиг и тяжелейший удар по нашему противнику!$B$BЗа Рассвет, брат мой!', NULL, NULL, NULL, 'Камень осквернителя Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5407, 'Камни захватчиков Плети', '', 'Камни Плети приспешников – знаки различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.В настоящий момент Серебряный Рассвет предлагает по знаку доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.', 'Поздравляю, $N– и с радостью вручаю тебе знак доблести Серебряного Рассвета!$B$BКаждый выданный знак доблести приближает час победы над Плетью!Все больше героев вступают в бой с Плетью на ее землях, и Серебряный Рассвет несомненно будет в первых рядах той армии, что решится положить конец бесчинством прихвостней Повелителя Тьмы. Надеюсь, твоей доблести хватит и до того дня!', NULL, NULL, NULL, 'Камень захватчика Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5408, 'Камни приспешников плети', '', 'Камни Плети приспешников – знаки различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово \"слабый\" – относительное понятие. Не стоит недооценивать Плеть. От имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.', 'Поздравляю, $N – и с радостью вручаю тебе знак доблести Серебряного Рассвета!$B$BЭти знаки служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережем для самых преданных наших сторонников. Во-вторых – их можно отдавать нашим интендантам вместе с деньгами и получать ценные предметы, которые изготовляют в нашем ордене.$B$BТак или иначе, ты их заслужил сполна. Молодец!', NULL, NULL, NULL, 'Камень приспешника Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5421, 'Рыбка в ведерке', '', '', 'Ах, дружочек, нет ничего лучше хорошо сделанной работы, особенно когда делаешь ее не ты... Верно ведь?', NULL, NULL, NULL, 'Моллюск', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5441, 'Ленивые батраки', 'Проклятые батраки! Им велено валить лес, но они все время пытаются отлынивать. Мне нужен кто-то, кто их приструнит. Ты, $r, мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум! Управишься – не забудь вернуть дубинку.$B$BПроклятые лентяи...', 'Проучите ленивых батраков дубинкой старшины. Разбудите 5 батраков, потом верните дубинку штейгеру Тазз\'рилу в долине Испытаний.', 'Отлично, отлично! В следующий раз будут знать, как дрыхнуть на работе! Спасибо за помощь!', 'Негодяи, бездельники…$B$BЧто? Где моя дубинка? Ну что, удалось тебе всыпать этим лентяям?', NULL, NULL, 'Разбужено батраков', 'Дубинка штейгера (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5461, 'Рас Ледяной Шепот – человек', 'Нежить боится жизни не меньше, чем живые – смерти. Ступившие на путь не-жизни нередко уничтожают все свидетельства прежнего бытия.$B$BК сожалению, для создания артефакта, способного превратить Раса Ледяного Шепота в смертного, мы должны отыскать какой-то предмет, сохранившийся со времени его настоящей жизни.$B$BОтправляйся в разрушенный город Стромгард, родину Ледяного Шепота, и найди такой предмет. Удачи тебе, $N.', 'Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу Воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье $Nуку.', 'Честно говоря, я сомневался, что эта вещь вообще существует. Перед нами открывается удивительная возможность – главное, ее не пропустить.$B$BГотовься, $N, ведь то, о чем я тебя попрошу, низведет тебя в самые глубины Преисподней.', 'Да, книгу Воспоминаний нелегко найти, $N.', NULL, NULL, 'Книга Воспоминаний', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5462, 'Рас Ледяной Шепот – гибель', 'Оскверненной душе можно противопоставить особые памятные предметы.$B$BГоворят, будто Ледяной Шепот встал под знамена Короля-лича в Стратхольме. Он добровольно лишил себя жизни с целью влиться в ряды нежити.$B$BИменно в тех землях следует искать память о его человеческом облике.$B$BВ часовне Последней Надежды ты найдешь Леонида Барталомея Чтимого, некогда бывшего рабом Плети, освобожденного королевой банши, но отдавшего свою верность Серебряному Рассвету. Быть может, он знает больше, чем я. В путь!', 'Отправляйтесь в часовню Светлых надежд в Восточных Чумных землях и найдите Леонида Бартоломея Чтимого. Покажите ему книгу Воспоминаний и расскажите обо всем, о чем удалось узнать.', '*Леонид проглядывает книгу.*$B$BТы заставляешь меня вспоминать события, о которых хотелось забыть навек.', 'Не задавай вопросов, если не хочешь узнать ответы.', NULL, NULL, 'Книга Воспоминаний (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5463, 'Дар Менетила', 'Рас Ледяной Шепот некогда тоже был человеком. Я собственными глазами видел, как он вручил свою бессмертную душу Королю-личу. Он приставил к своему горлу кинжал и с улыбкой перерезал себе глотку от уха до уха. Его мертвое тело упало в центр пентаграммы. Король-лич бросил взгляд на мертвого мага, и в ту же секунду Рас Ледяной Шепот восстал в обличье Короля-лича.$B$B<Леонид опускает глаза на мгновенье и снова продолжает рассказ>$B$BДа, $r, я помню. У того, что ты ищешь, есть имя – Дар Менетила: это земля, благословленная Королем-личом – священное место Плети.', 'Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу Воспоминаний на оскверненную землю.', 'Вы кладете книгу на оскверненную землю.', 'От Дара Менетила веет могильным холодом.', NULL, NULL, 'Книга Воспоминаний (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5464, 'Дар Менетила', 'Души падших цепляются за любое олицетворение их прежное жизни и превращают любой значимый для них предмет в Книгу Души. Вы поднимаете предмет и прячете в сумку.', 'Отнесите Книгу Души Леониду Бартоломею в Восточные Чумные земли.', 'Как эта душа цепляется за книгу, также она будет цепляться и за человеческое обличье Раса Ледяного Шепота.', '*Леонид вздрагивает*', NULL, NULL, 'Книга Души (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5465, 'Книга Души', 'Отнеси книгу $Nуку, $N, он расскажет тебе, что делать дальше.', 'Возвращайтесь к мировому судье $Nуку в Каэр Дарроу. Покажите ему книгу души.', 'Признаться, я ожидал вновь увидеть тебя в обличье несчастного призрака.', 'Неужели тебе удалось сделать невозможное?', NULL, NULL, 'Книга Души (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5466, 'Рас Ледяной Шепот – лич', 'Осталось одно задание, $N – бросить вызов личу Расу Ледяному Шепоту.$B$BВоспользуйся против него силой Книги – не знай пощады! Терпи удары, которые обрушит на тебя злобная тварь. Не бойся боли!$B$BКогда ритуал будет завершен, Рас снова станет смертным. Именно в этот момент его необходимо убить. Срази злодея и забери его голову.', 'Отыщите в Некроситете Раса Ледяного Шепота. Найдя его, воспользуйтесь книгой души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Ледяного Шепота. Отнесите голову мировому судье $Nуку.', 'Десять тысяч душ возопили единым гласом! Ты нанес смертельный удар Плети и ее хозяевам.', 'На твоих плечах покоится бремя тысяч неупокоенных душ, $N.', NULL, NULL, 'Человеческая голова Раса Ледяного Шепота', 'Книга Души', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5481, 'Задание Толстяка', 'Хозяину надо растения. У нас большие руки, цветы рвать никак. Ты нам помогать, мы тебя не трогать. Нам надо мракоцвет, он растет тут и у дороги.$B$BТы соберешь – отнеси хозяину Холланду на кладбище в Брилл.', 'Соберите 3 ветки мракоцвета для младшего аптекаря Холланда на кладбище Брилла.', 'Что это? Мракоцвет?! Зачем он мне сдался?! Эта тупая гора мяса собирает ромашки и привлекает – сколько, Темная Госпожа знает, – к этому делу таких простаков, как ты! Без обид.$B$BЛадно, главное, что ты здесь. Я не собираюсь тратить свое время на то, чтобы объяснить этому поганищу элементарные вещи. Так что, может, ты соберешь для меня этот проклятый погибельник?', 'Где это никчемное поганище? Ты принес мне то, что мне нужно? Если нет, то иди и не возвращайся, пока не соберешь достаточно цветков!', NULL, NULL, 'Мракоцвет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5482, 'Погибельник', 'Теперь ты понимаешь, в каком затруднительном положении я нахожусь, $N? Это нечто все еще ходит там и собирает не те растения. Я непременно отблагодарю тебя, если ты соберешь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу.$B$BНасколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла. Поторопись – и будь $gосторожен:осторожна: – в тех местах полно гноллов.', 'Соберите 10 веток погибельника для младшего аптекаря Холланда.', 'А, мой погибельник! Превосходно!$B$B<Младший аптекарь Холланд жадно потирает ладони.>$B$BОн мне очень пригодится. Ты оказал мне, ой, то есть Темной Госпоже, большую услугу, Герей. Как я и обещал, вот твоя награда.', 'Я полагаю, ты уже собрал достаточно погибельника?', NULL, NULL, 'Погибельник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5501, 'Собиратель костей', 'Мы тут на золотой жиле сидим, на золотой жиле! Знаешь, что это? Кости кодо!.. Кости кодо изменят мир раз и навсегда! У меня масса клиентов, которые делают из этих костей мебель, музыкальные инструменты – даже взрывчатый порошок, чтоб тебе знать!$B$BСюда приходит караван, забирает у меня кости, а потом караванщики продают их в деревне Ночных Охотников. И неплохая выручка, да, очень неплохая... Если пойдешь на юг отсюда, то доберешься прямиком до Кладбища кодо. Принеси мне десяток костей, а я дам тебе кое-что взамен. Ну что, идет?', 'Принесите 10 костей с Кладбища кодо в хижину Кормека и отдайте Биббли Скобкофузу.', 'Ох, вот они, мои косточки, мои драгоценные!..$B$BЯ стану самым богатым гоблином в мире, я прославлюсь, мое лицо не будет сходить с обложек \"Каравана истории\", и тогда они все еще увидят, кто я такой! Да-да, особенно тот зеленый сморчок, который вечно твердил: \"Ничего достойного в жизни совершить не сможешь ты!\"', 'Ну, где они, мои косточки, где же они? Караван вот-вот придет. Всего десять костей – и это будет мой звездный час, клянусь чем угодно! Вот увидишь!', NULL, NULL, 'Кость кодо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5502, 'Опекун Орды', 'Ты $gбыл:была: очень $gдобр:добра: ко мне, $N. Я и представить не мог, что Детская неделя пройдет так весело. Спасибо. Я не хочу печалиться из-за собственной судьбы – предки всегда говорили мне, что я должен быть выше всех несчастий. Знаешь, когда я вырасту, я хочу стать героем... как ты.$B$BКак ни жаль, мне пора домой. Давай вернемся, и я расскажу нашей попечительнице, что ты лучше всех!', 'Отведите своего подопечного в приют Оргриммара, вернув вернув орочью детскую свистульку попечительнице сирот Найтингейл в Храмовый квартал.', '', NULL, NULL, NULL, 'Свисток орка-сироты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5503, 'Жетон Серебряного Рассвета', '', '', 'Все, кто сражаются со злом во имя Серебряного Рассвета, должны получить наш амулет. Он даст тебе право получать награды у наших интендантов.Пока при тебе амулет, ты можешь собирать камни Плети с убитой нежити – иногда они носят такие знаки различия. Собирай их и приноси мне. За каждый из них ты получишь по знаку доблести Серебряного Рассвета – так мы благодарим наших героев.Ступай на встречу судьбе – вступай в битву со злом!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5504, 'Оплечья Рассвета', 'Тебе причитается награда за верную службу Серебряному Рассвету, $N. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых ценных наших предметов – оплечье защиты от магии.$B$BЕсли прикрепить его к доспехам, твое сопротивление силам одного из пяти направлений магии возрастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.', 'Принесите 10 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион.', 'Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока наше отношение к тебе не изменится, ты сможешь купить эти мантии у любого интенданта Серебряного Рассвета.$B$BЗа Рассвет, брат мой!', 'А, благородный $C! Ты принес мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.', NULL, NULL, 'Знак доблести Серебряного Рассвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5505, 'Ключ от Некроситета', '', '', 'Ну, вот, готово, $N – это ключ от Некроситета. Я не сомеваюсь, что он позволит тебе проникнуть в пределы школы. Впрочем, есть лишь один способ узнать наверняка. И не теряй времени даром.Удачи тебе, герой. Да рассеют твои победы мрак!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5507, 'Оплечья Рассвета', 'Тебе причитается награда за верную службу Серебряному Рассвету, $N. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых ценных наших предметов – оплечье защиты от магии.$B$BЕсли прикрепить его к доспехам, твое сопротивление силам одного из пяти направлений магии возрастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.', 'Принесите 10 знаков доблести Серебряного Рассвета интенданту Искре Света из лагеря Промозглого Ветра.', 'Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить эти мантии у любого интенданта Серебряного Рассвета.$B$BЗа Рассвет, брат мой!', 'А, благородный $C! Ты принес мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.', NULL, NULL, 'Знак доблести Серебряного Рассвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5508, 'Камни осквернителей Плети', '', '', 'Поздравляю, $N! С гордостью вручаю тебе знак доблести Серебряного Рассвета.$B$BТолько настоящие герои и воины добра получают его. Мы ценим любые деяния, направленные против подлой Плети, но убийство одного из их лидеров заслуживает особого почтения!$B$BВо имя Рассвета, брат!', NULL, NULL, NULL, 'Камень осквернителя Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5509, 'Камни захватчиков Плети', '', '', 'Поздравляю, $N – и с радостью вручаю тебе знак доблести Серебряного Рассвета!$B$BКаждый выданный знак доблести означает, что вероятность победы Плети делается все ниже. Все больше героев вступают в бой с Плетью на ее землях, и Серебряный Рассвет несомненно будет в первых рядах той армии, что решится положить конец бесчинством прихвостней Повелителя Тьмы. Надеюсь, твоей доблести хватит и до того дня!', NULL, NULL, NULL, 'Камень захватчика Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5510, 'Камни приспешников плети', '', '', 'Поздравляю, $N– и с радостью вручаю тебе знак доблести Серебряного Рассвета!$B$BОни служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережем для самых преданных наших сторонников. Во-вторых – ими можно расплачиваться с нашими интендантам, также как и деньгами, и получать ценные предметы, которые изготовляют в нашем ордене.$B$BТак или иначе, ты их заслужил. Молодец!', NULL, NULL, NULL, 'Камень приспешника Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5511, 'Ключ от Некроситета', '', '', 'Ну, вот, готово, $N - это ключ от Некроситета. Я не сомеваюсь, что он позволит тебе проникнуть в пределы школы. Впрочем, есть лишь один способ узнать наверняка. И не теряй времени даром.Удачи тебе. Да рассеют твои победы мрак!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5513, 'Оплечья Рассвета', 'Тебе причитается награда за верную службу Серебряному Рассвету, $N. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых ценных наших предметов – оплечье защиты от магии.$B$BЕсли прикрепить его к доспехам, твое сопротивление силам одного из пяти направлений магии возрастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.', 'Принесите 10 знаков доблести Серебряного Рассвета интенданту Затвор в Часовню Последней Надежды в Восточные Чумные земли.', 'Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета.$B$BЗа Рассвет, брат мой!', 'А, благородный $C! Ты принес мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.', NULL, NULL, 'Знак доблести Серебряного Рассвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5514, 'Форма денег стоит', 'Тебе нужно поговорить с гоблином по имени Кринкель Сталлер. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдется недешево. Мы просим тебя не скупиться и заплатить ему.$B$BЯ алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел.$B$BНу вот, опять я брякнул что-то не то. Ладно.$B$BТебя ждет Прибамбасск! Удачи!', 'Отнесите Кринкелю Сталлеру из Прибамбасска прочные фрагменты скелета и 15 золотых монет.', 'Дитерс сказал, что ты принесешь все необходимое, и так оно и оказалось! Сделка есть сделка. Дай-ка я сложу фрагменты скелетов в форму.$B$BДитерс их заранее закалил? Великолепно... В противном случае тебе пришлось бы тащиться обратно в Бастион.', 'Да, я знаю, кто ты и зачем пришел. Дитерс послал мне весточку. Сразу перейдем к делу?$B$BУ меня есть форма, в которой можно изготовить нужный тебе ключ, но она обойдется недешево – 15 золотых. Деньги вперед и не пытайся торговаться. Я сложу в форму фрагменты скелетов и покажу, как можно отлить его, не зная ничего о кузнечном деле... и все это бесплатно.$B$BПусть не говорят, что наемники за копейку удавятся!', NULL, NULL, 'Прочные фрагменты скелета (Прилагается)', 'Требуется денег: 15', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5515, 'Мешок ужасов Крастинова', 'Мы сбросили с себя тяжелое бремя, но твое задание все еще не исполнено, $N. Повелитель Крастинова, Киртонос, все еще жив.$B$BВпрочем, прежде чем бросить ему вызов, необходимо придумать, как его вызвать.$B$BГоворят, что кровь невинных от Крастинова к Киртоносу переправляет Джандис Барова.$B$BНайди ее в затопленных коридорах Некроситета и убей. Принеси все улики, которые только найдешь.', 'Найдите в Некроситете Джандис Барову и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф.', 'Мешок ужасов!', '*Эва то появляется, то исчезает.*', NULL, NULL, 'Мешок ужасов Крастинова', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5517, 'Многоцветная драгоценность Рассвета', '$gБрат:Сестра: $N – твоих деяний во славу Серебряного Рассвета не счесть. В знак признательности я готова продать тебе одно их наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!$B$BПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.', 'Принесите 25 знаков доблести Серебряного Рассвета интенданту Затвор в Часовню Последней Надежды в Восточные Чумные земли.', 'Что и говорить, твои подвиги весьма впечатляют, $N – прими же многоцветное оплечье Рассвета!$B$BПока в Серебряном Рассвете тебя превозносят, ты можешь покупать дополнительные многоцветные оплечья у любого из интендантов Рассвета.', 'Приветствую, могучий $C! Где же знаки доблести, о которых шла речь? Как только ты их принесешь, я сразу выдам тебе многоцветное оплечье Рассвета.', NULL, NULL, 'Знак доблести Серебряного Рассвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5518, 'Броня огров Гордока', 'Если вы собираетесь сразиться с королем этой помойки – а думаю, что без этого не обойтись, – тогда вам придется миновать капитана Давигрома. Конечно, можно его просто убить. Но возможно, вам стоит оставить его в живых.$B$BВы спросите – каким образом? Я сижу здесь уже довольно долго, и успел придумать, как можно изготовить личину огра, которая продержится достаточно долго, чтобы обмануть этих остолопов. Но, увы, больше чем на десять минут ее не хватит. Принесите мне все, что нужно, и я вам ее изготовлю. Торопиться-то мне все равно некуда...', 'Принесите 4 рулона рунической ткани, 8 кусков грубой кожи, 2 мотка рунической нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе.', 'Да, это подойдет. Вот тут подтянуть, тут подогнуть... Да-да, все должно пройти как по маслу!*Прикованный гоблин расплывается в широкой улыбке.*$B$BНу вот, все готово! Только не забывайте – это не самое долговечное изделие. У вас всего десять минут, после этого оно развалится, и все увидят, кто вы такой! Постарайтесь надеть его не раньше, чем приблизитесь к капитану, и помните: оно превратит в огра только вас, но не ваших спутников!', 'Из всего, что мне нужно, пожалуй, труднее всего добыть огрскую дубильную кислоту. Может быть, наверху найдется? Мне самому туда не дойти, с этим ядром на цепи не больно-то побегаешь.$B$BВ общем, принесите мне все, что нужно, и я изготовлю вам огрскую личину, которая заставит капитана Давигрома принять вас за одного из своих.', NULL, NULL, 'Рулон рунической ткани', 'Грубая кожа', 'Руническая нить', 'Огрская дубильная кислота');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5519, 'Броня огров Гордока', '', '', 'Вот, пожалуйста, $N: после того, как вы ее наденете, у вас в запасе будет десять минут. Удачи!$B$BДа, и если сумеете найти ключ, чтобы выпустить меня отсюда, непременно мне скажите, слышите?', NULL, NULL, NULL, 'Рулон рунической ткани', 'Грубая кожа', 'Руническая нить', 'Огрская дубильная кислота');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5521, 'Многоцветная драгоценность Рассвета', '$gБрат:Сестра: $N – твоих деяний во славу Серебряного Рассвета не счесть. В знак признательности я готова продать тебе одно их наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!$B$BПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.', 'Принесите 25 знаков доблести Серебряного Рассвета интенданту Искре Света из лагеря Промозглого Ветра.', '', NULL, NULL, NULL, 'Знак доблести Серебряного Рассвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5522, 'Леонид Барталомей', 'Я получила весть от своего господина Вектуса. На самом деле... не напрямую от него, но от некого Леонида Бартоломея. Я не знаю его, однако он видел моего господина – а никто не может видеть моего господина, если он сам этого не пожелает.$B$BЛеонид сказал мне, что Вектусу необходимы драконьи яйца. Доставь их ему в Часовню Последней Надежды в Восточные Чумные земли.$B$BАй! За что? Разве Вектус не доверяет мне? Не обращай внимания, я не тебе. Просто доставь яйца куда следует и сообщи Леониду, что я сделал все, как было приказано.', 'Принесите охлажденные яйца Леониду Бартоломею в Восточные Чумные земли.', 'Прекрасно, прекрасно. Тебе еще не известно, сколь великое зло кроется за теми, на кого ты работал но я открою тебе глаза на правду. Не бойся, я не служу им. Имя мне Леонид Бартоломей; братья мои из Серебряного Рассвета зовут меня Чтимым. $B$BОбманом я убедил Тинки отправить драконьи яйца мне. Нам несказанно повезло, что она попалась в эту ловушку, потому что если бы драконьи яйца были доставлены по назначению, в руках врага оказалась бы огромная сила.', 'Ага, ты ведь один из тех, кто устроил заварушку в Пике Черной горы? Принес то, о чем я просил?', NULL, NULL, 'Охлажденные яйца (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5524, 'Многоцветная драгоценность Рассвета', '$gБрат:Сестра: $N – твоих деяний во славу Серебряного Рассвета не счесть. В знак признательности я готова продать тебе одно их наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!$B$BПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.', 'Принесите 25 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион, что в Западных Чумных землях.', 'Что и говорить, твои подвиги весьма впечатляют, $N – прими же многоцветное оплечье Рассвета!$B$BПока в Серебряном Рассвете тебя превозносят, ты можешь покупать дополнительные многоцветные оплечья у любого из интендантов Рассвета.', 'Приветствую, могучая $C! Где же знаки доблести, о которых шла речь? Как только ты их принесешь, я сразу выдам тебе многоцветное оплечье Рассвета.', NULL, NULL, 'Знак доблести Серебряного Рассвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5525, 'Освободите Нотта!', '', '', 'Вы для меня – номер один во всем мире! Все остальные – после вас! Ох, большое вам спасибо, что освободили меня!$B$BЯ знал, я знал, что меня ждет более достойная участь, чем пойти на обед какому-нибудь огру!', NULL, NULL, NULL, 'Ключ от оков Гордока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5526, 'Осколки сквернита', 'Твои знания об Эльдре\'Таласе – Забытом Городе – в Фераласе теперь очень пригодятся, $N. Именно в восточной части этого разрушенного города властвует нечестивый Алззин Перевертень. Ступай же туда со всей поспешностью и посмотри в лицо ожидающей тебя опасности. $B$BПлод Изобилия, ныне оскверненный и ставший Сквернитом, должен находиться неподалеку от Алззина. Когда он упадет, собери столько субстанции Сквернита, сколько сможешь. Закрой его в реликварий и принеси мне.$B$BУдачи тебе, и быстроты Кенария.', 'Отыщите сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии чистоты, затем верните его Рабину Сатурне в Ночную Гавань на Лунной поляне.', 'Дело сделано, отважный $С, и Круг Кенария в долгу перед тобой. Хотя война еще далеко не окончена, мы выиграли великую битву с теми, кто хотел обрушить на нас молот рока.$B$BПрошу – прими это в знак нашей безмерной благодарности. Знай, $N, что для Круга Кенариуса ты навсегда останешься героем. Прими нашу благодарность.', 'Имея в своем распоряжении запечатанный реликварий Чистоты, мы сможем не только устранить угрозу порчи, но и подойти к изучению этого проклятия со всей ответственностью. Возможно, мы даже сумеем разработать новые средства борьбы с порчей, что постоянно угрожает Азероту.$B$BЯ знаю, что Мили не согласиась бы ни на что иное...', NULL, NULL, 'Запечатанный реликварий Чистоты', 'Реликварий Чистоты', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5527, 'Реликварий Чистоты', 'Первый шаг – найти вместилище, способное удержать чрезвычайно оскверненную субстанцию и оградить обладателя от ее влияния. Единственное известное мне приспособление, в котором, возможно держать такую дрянь, как Сквернит, – это реликварий Чистоты.$B$BВ сердце пустошей Силитуса находятся руины поселения Ночных эльфов, деревня Южного Ветра. Я знаю, что реликварий хранился там много лет назад. Если хочешь помочь нам достичь успеха, обыщи эти руины в надежде найти его.', 'Отправляйтесь в Силитус и найдите реликварий чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань на Лунной поляне.', 'Воистину, ты и правда находчив, как говорят. Кругу Кенария повезло, что ты на нашей стороне.$B$BТеперь, когда реликварий снова у нас в руках, на сердце у меня стало легче. Теперь мне значительно проще просить тебя не только повергнуть нечестивого демона, но и принести одну опасную вещь...', 'Реликварий Чистоты – удивительный предмет сам по себе. Их было сделано очень мало, и почти все они были утрачены за прошедшие века.$B$BНадо признать, я давно узнал о том, что деревне Южного Ветра хранится один из этих артефактов. Но после начала треволнений в Силитусе я решил, что эта тайна должна остаться тайной. Расспрашивать – лишь вызывать подозрения у наших врагов.$B$BУвы, спокойное время миновало, особенно учитывая нынешнюю ситуацию в Эльдре\'Таласе.', NULL, NULL, 'Реликварий Чистоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5528, 'Лучшее пойло Гордока', '', '', 'Ну, ты теперь у нас большая шишка, так попробуй задаром моего лучшего пойла! Оно и сил добавляет, и голову кружит! Пей, пей, начальник – попробуй, сам увидишь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5529, 'Зачумленные детеныши дракона', 'До Серебряного Рассвета дошли слухи о том, что Плеть создает собственную армию драконов! Мы должны этому помешать – с помощью драконов Плеть сможет беспрепятственно перемещаться по всему Азероту!$B$BИх некроманты выращивают проклятых драконов в Некроситете, посреди озера Дарроумир.$B$BОтправляйся в Некроситет и убей как можно больше драконьих детенышей, пока они не успели вырасти и превратиться в неуязвимых монстров!', 'Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды.', 'Отлично, $N! Они нескоро смогут вырастить новый выводок. $B$B...По крайней мере, я на это очень надеюсь...', NULL, NULL, NULL, 'Зачумленный детеныш дракона убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5531, 'Бетина Биггльцинк', 'Яйца, которые ты $gпринес:принесла: мне, должны были быть использованы Плетью для создания чудовищных проклятых драконов. Охлажденные яйца черных драконов были бы бесценны для их опытов – это несомненно позволило бы Плети достичь своей подлой цели гораздо быстрее.$B$BОтнеси яйца Бетине Биггльцинк – она сведуща в науках и алхимии. Она обеспечила нас оружием против Плети. С твоей помощью мы нанесем этим тварям решающий удар.', 'Принесите охлажденные яйца Бетине Биггльцинк.', 'Прекрасно, правильная упаковка – залог сохранности яиц при транспортировке. Да они отборные!$B$BОтложим их в надежное место для дальнейшего исследования, а пока займемся более важным делом.$B$BЯ разработала прибор, предназначенный для уничтожения нежити в Некроситете. Тамошние ученые сейчас работают над выведением нового вида драконов – нежити. Мы должны помешать им!$B$BПрибор я назвала \"Рассветным гамбитом\", потому что... в общем, я сама не совсем понимаю, как он работает.$B$BСможешь проверить?', 'Приветствую тебя, $N. Что ты принес мне, драконьи яйца? Посмотрим, посмотрим...', NULL, NULL, 'Охлажденные яйца (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5533, 'Некроситет', 'На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью плети. В ее недрах наши враги спокойно проводят исследования и делаются все сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти.$B$BАлхимик Арбингтон многое знает о Некроситете и придумал, как достать ключ. Ты $gзарекомендовал:зарекомендовала: себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с алхимиком.', 'Поговорите с алхимиком Арбингтоном с вершины Холодной Скалы, что в Западных Чумных землях.', 'Рад встрече, $C. В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ... который отомкнет входную дверь.$B$BПредставляю, какие кошмары таятся за ней, $N. Не понимаю, как герои вроде тебя решаются на такие подвиги...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5534, '\"Пропавшее\"оборудование Ким\'джаеля', 'Что?! Ты в своем уме?! Чем ты еще $gнедоволен:недовольна:?! $B$BТы хоть представляешь, сколько стоят эти гранаты? За них дают... ладно, не важно... Хочешь денег? Хорошо. Прежде докажи мне, что ты $gценный работник:ценная работница:.$B$BОтправляйся в руины Эльдарата и принеси мне некую руну, которую искали эльфы крови. Полагаю, она у наг.', 'Найдите некую руну, которую хранят наги в руинах Эльдарата и принесите ее Ким\'джаелю в Азшару.', 'Ха! Отлично! $B$BУж я выясню, что это за штука, зачем она нужна и зачем волхв Римтори – та кобыла, которая меня в это втянула – так хотела ее заполучить. Ха! Вонючие эльфы крови! Уж Ким\'джаель покажет вам, где раки зимуют! Он покажет вам, кто тут букашка! $B$BНу, ты молодчина, $N! Спасибо тебе... Чего говоришь, не булькает? Ну, держи свои презренные монеты и проваливай, мне и без тебя есть чем заняться.', 'Ну, $N? Где моя руна? Ты же хочешь денег? Так вот сначала поработай! $B$BНе то не получишь уговоренную сумму. Что, мы ни о чем не договаривались? А, ну прекрасно. Тогда советую поторопиться, а не то получишь сильно меньше, чем ожидаешь.', NULL, NULL, 'Некая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5535, 'Беспокойные духи', 'Давным-давно высокорожденные были самыми могущественными адептами тайной магии, когда либо существовавшими среди ночных эльфов. Порча, которая охватывает каждого, кто имеет дело с тайной магией, принесла много горя народу ночных эльфов и всему Азероту. $B$BЯ обещал Часовым, что буду освобождать встреченных мной духов от их смертных связей. Если поможешь мне в этом, я награжу тебя. $B$BДухи скитаются в святилище Песни Теней к северо-востоку отсюда.', 'Уничтожьте по 6 теней высокорожденных обоих полов и возвращайтесь к Ло\'хату в Азшару.', 'Отличная работа, $C. Благодарю тебя. Теперь духи обрели покой, а опасность, которую могла навлечь их жажда магии, миновала. $B$BДумаю, обе стороны конфликта, раздирающего ныне Азерот, поймут, что ты выше этого.', 'Как идут поиски духов высокорожденных, $N? $B$BАзерот видел много бедствий, однако эти духи являют собой одно из самых серьезных. Возможно, дело в их всепоглощающей тяге к тайной магии. Ты знаешь, что эта тяга ведет за собой Пылающий Легион... И ты знаешь, чем все это может закончиться.', NULL, NULL, 'Тень высокорожденной убито', 'Призрак высокорожденного убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5536, 'Земли, полные ненависти', 'Сатиры, искаженные и зловредные порождения ночных эльфов, ныне оскверняют священные земли, по которым некогда ступал Кенарий. Конечно, не в моих силах помочь эльфам справиться со всеми этими отвратительными созданиями, однако я поклялся Матери-Земле помочь эльфам избавиться от сатиров хотя бы здесь. $B$BНадеюсь, ты поможешь мне в этом деле. $B$BК северо-востоку отсюда ты найдешь клан Халдарр. Возвращайся ко мне, когда испытаешь свою силу.', 'Уничтожьте 6 сатиров, 2 плутов Халдарра и 2 скверноподданных из племени Халдарр и возвращайтесь к Ло\'хату к границе Ясеневого леса.', 'Отличная работа, $C. Вижу, ты не только силен, но и хитер. Битва с сатирами была испытанием твоей преданности Матери-Земле, даже если ты поклоняешься другим богам. Она пронизывает все сущее в нашем мире и за его пределами. Два ока ее, темное и светлое, всегда взирают на нас с небес. $B$BПрошу тебя, прими эту скро$Nю плату в знак моей признательности.', NULL, NULL, NULL, 'Сатир из племени Халдарр убито', 'Плут из племени Халдарр убито', 'Скверноподданный из племени Халдарр убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5537, 'Фрагменты скелетов', 'Чтобы отомкнуть двери Некроситета необходим костяной ключ. Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой.$B$BНо не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи.', 'Принесите 15 фрагментов скелетов алхимику Арбингтону в Берег Промозглого Ветра в Западных Чумных землях.', 'Отличные образцы! Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придется рано или поздно пройти.$B$BТеперь придется отыскать подходящую форму для отливки. Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей. Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает.', 'Как бы гнусно это ни звучало, для создания ключа нам нужен солидный запас фрагментов скелетов. Недаром его назвали Костяным ключом', NULL, NULL, 'Фрагменты скелетов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5538, 'Форма денег стоит', 'Тебе нужно поговорить с гоблином по имени Кринкель Сталлер. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдется недешево. Мы просим тебя не скупиться и заплатить ему.$B$BЯ алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел.$B$BНу вот, опять я брякнул что-то не то. Ладно.$B$BТебя ждет Прибамбасск! Удачи!', 'Отнесите Кринкелю Сталлеру из Прибамбасска прочные фрагменты скелета и 15 золотых монет.', 'Арбингтон сказал, что ты принесешь все необходимое, и так оно и оказалось! Сделка есть сделка. Дай-ка я сложу фрагменты скелетов в форму.$B$BАрбингтон их заранее закалил? Великолепно... В противном случае тебе пришлось бы тащиться обратно на Берег Промозглого Ветра.', 'Да, я знаю, кто ты и зачем пришел. Арбингтон послал мне весточку. Сразу перейдем к делу?$B$BУ меня есть форма, в которой можно изготовить нужный тебе ключ, но она обойдется недешево – 15 золотых. Деньги вперед и не пытайся торговаться. Я сложу в форму фрагменты скелетов и покажу, как можно отлить его, не зная ничего о кузнечном деле... и все это бесплатно.$B$BПусть не говорят, что наемники за копейку удавятся!', NULL, NULL, 'Прочные фрагменты скелета (Прилагается)', 'Требуется денег: 15', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5541, 'Боеприпасы для Громострела', 'Хегнар Громострел продает ружья у дороги в Старую Наковальню. Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны.$B$BНо... Последний ящик с боеприпасами, что я ему послал, пропал по дороге. Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго... и этот дурак бросил боеприпасы для Громострела!$B$B$N, $gне мог бы ты:не могла бы ты: найти их и вернуть Громострелу? Он их ждет, и наверняка у него боеприпасы уже на исходе.', 'Доставьте боеприпасы Хегнару Громострелу в Дун Мороге.', 'Вот радость-то, еще боеприпасы! Поставка старины Лослора, наконец, прибыла! Пусть и поздновато, но, как говаривал мой дедуля, лучше поздно, чем никогда!$B$BБольшое тебе спасибо, $N. Покупатели тут заждались!', 'Надеюсь, ты не за боеприпасами пришел, потому как они у меня почти закончились!', NULL, NULL, 'Боеприпасы Громострела', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5542, 'Псы-демоны', 'Если ты собираешься здесь оставаться, придется тебе поработать в уплату за проживание. У нас есть ряд докучающих обстоятельств, с которыми неплохо бы разобраться.$B$BНачни с чумных псов и их отродий.$B$BЯ не многим смогу тебе отплатить, но горячую пищу и приятную беседу гарантирую.', 'Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу.', 'Молодец, $N. Давай, отдохни. Поедим же и побеседуем о давно ушедших днях!', NULL, NULL, NULL, 'Карликовый чумной пес убито', 'Чумной пес убито', 'Бесноватый чумной пес убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5543, 'Окровавленные небеса', 'Горе тем, кто в глупости своей бродит по Чумным землям. В здешних лесах таится много опасностей – от Алого ордена, который убивает всех, кроме своих сторонников, до Плети, которая всегда рада пополнить свои ряды новой нежитью.$B$BДаже звери и птицы превратились в отвратительных хищных чудовищ. Я прошу тебя уничтожить тех, что нападают с небес – чумных нетопырей.', 'Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу.', 'Ты бесподобный образец порядочности, $R! Давненько я не чувствовал крови героев в своих венах. Подобная отвага внушает надежду!', NULL, NULL, NULL, 'Чумной нетопырь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5544, 'Мясо личинок-трупоедов', '$gраса:, у меня еда на исходе. Мне стыдно признаться, но угостить тебя нечем.$B$BНе поможешь старику? Единственные твари в этих краях, которых не поразила чума, это личинки-трупоеды. Они довольно гадкие, зато их мясо хранится много месяцев. Мне необходимо запасти несколько сотен фунтов на зиму!', 'Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите их мяса. Возвращайтесь к Тириону Фордрингу, когда насобираете 15 кусков мяса червей-трупоедов.', 'Да благословит тебя Свет, юноша.', 'Ты постепенно привыкнешь к вкусу, $R.', NULL, NULL, 'Кусок мяса червя-трупоеда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5545, 'Тридцать три несчастья', 'У меня большие неприятности. Приближается срок поставки древесины, а я не успеваю ее отправить. Самое обидное, что она уже заготовлена – но волки и медведи, расплодившиеся к северу отсюда, не дают моим работникам ее забрать$B$BЯ уже договорилась с заместителем судьи Рейнером насчет зверья, но мне нужен кто-нибудь, кто доставит сюда эти дрова. Если ты принесешь мне восемь вязанок, я все успею.', 'Принесите 8 вязанок дров Раэлен на Лесопилку Восточной долины.', 'Великолепно! Благодаря тебе я сумела выполнить заказ вовремя. Всякий труд должен быть оплачен, так что прошу тебя принять эту плату за беспокойство.$B$BСпасибо – и до свидания!', 'Послушай, $C, срок поставки мне никто продлять не будет. Мне позарез нужны эти дрова!', NULL, NULL, 'Вязанка дров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5561, 'Отлов кодо', 'Гоблин Биббли думает, что только он умеет делать деньги в Пустошах. Ха! Единственный караван, который осмеливается странствовать по этим землям, полностью зависит от меня. С тех самых пор, как я научился омолаживать кодо и управлять старыми и умирающими зверями при помощи моего энергетического инкапсулятора, мы трое – я, караванщик Корк и Риггер – создали что-то вроде компании.$B$BВот, держи инкапсулятор: он действует на древних, старых и умирающих кодо, превращая их в ручных и заставляя следовать за тобой. Как сумеешь приручить кодо, веди его ко мне.', 'Приведите пять прирученных кодо Смиду Заржавеню в Лагерь Заржавня. Не забудьте вернуть ему энергетический инкапсулятор.', '*Смид Заржавень начинает считать.*$B$BТри... Четыре... Ага, пять. Прекрасно! Я просил пять прирученных кодо – и получил ровно пять прирученных кодо! Я буду богат... Да, очень, очень богат! Хотелось бы мне видеть, какую кислую рожу скорчит Биббли, когда узнает об этом!', 'Караван скоро будет здесь. Надеюсь, ты привел новых прирученных кодо? Да? Да?', NULL, NULL, 'Приручено кодо', 'Энергетический инкапсулятор кодо (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5581, 'Порталы Легиона', 'Воззри: вот Рука Ируксоса. Поистине, ужасающее зрелище.$B$BЕсли ты намереваешься закрыть порталы демонов на Поле Маннорок, – а именно об этом я и хочу тебя попросить, – то она должна быть у тебя. Угроза со стороны демонов растет: мы должны закрыть их порталы, дабы демоническим существам более не было доступа в этот мир. Удачи тебе в этом нелегком деле, $N... и берегись стражей портала.', 'Уничтожьте 6 порталов на поле Маннорок, а затем вернитесь к Тайге Мудрой Гриве в деревню Ночных Охотников.', 'Ты воистину достоин величайших почестей, $N. Твоими трудами жизнь на всем Азероте станет гораздо спокойнее.', 'Удалось ли тебе закрыть порталы демонов на Поле Маннорок?', NULL, NULL, 'Порталы закрыты', 'Рука Ируксоса (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5582, 'Здоровая чешуя дракона', 'Это чешуйка была взята у пораженного проклятой чумой драконьего детеныша. Однако в отличие от других чешуек, изъязвленных и покрытых слизью, эта выглядит совершенно здоровой.$B$BЛюбопытное явление. Бетина Биггльцинк непременно захочет на это взглянуть.', 'Отнесите здоровую чешую дракона Бетине Биггльцинк в Часовню Последней Надежды в Восточные Чумные земли.', 'Очень интересно... Возможно, ч помощью этой чешуи мне удасться проникнуть в суть козней Плети. Благодарю тебя, $N. Впредь, если обнаружишь подобные чешуйки, непременно приноси их мне!', 'Ты что-то принес мне, $N?', NULL, NULL, 'Здоровая чешуя дракона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5601, 'Сестренка Памела', 'Во время войны я бежала в Лордерон – мне посчастливилось спастись до того, как полчища Плети прошли по моим родным местам и превратили их в зачумленные руины. Мне повезло, но судьба была не столь благосклонна к моей семье. Боюсь, все они погибли во время битвы при Дарроушире.$B$BДеревня Дарроушир была частью Восточных королевств, теперь это еще одни развалины в южных пределах Восточных Чумных земель. Не $gмог:могла: бы ты узнать, что сталось с моей семьей? Я так волнуюсь за них, особенно за мою сестренку Памелу.$B$BПожалуйста, отыщи ее!', 'Найдите Памелу Редпат в Дарроушире.', 'Где моя сестра Джессика? Она покинула меня так давно, когда я была еще совсем маленькой девочкой. Она так плакала, когда уходила... Не знаю, почему, может, разбила коленку?$B$BРаньше мы с Джессикой вместе играли, и танцевали, и собирали цветы... А иногда мы прятались за дверью и ждали, когда отец придет домой, чтобы выскочить и напугать его.$B$BЯ хочу, чтобы она вернулась! Может, если вернется она, то вернется и папа, и остальные, и мы снова будем вместе играть...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5621, 'Облачение Луны', 'Мне нужна твоя помощь, $N. Я должна оставаться здесь, чтобы обучать других, но ты $gмог бы:могла бы: помочь одной из наших раненых часовых к югу от Доланаара. Ее ранили, когда она патрулировала город, и ей нужна наша помощь. Ее зовут Шайя.$B$BКогда найдешь ее, исцели ее раны и укрепи ее тело заклятиями. По крайней мере, это защитит ее от бед на некоторое время. Когда выполнишь свой долг перед Элуной, возвращайся ко мне.', 'Найдите часовую Шайю и залечите ее раны \"Слабым исцелением\" 2-го уровня. Затем примените к ней \"Слово силы: Стойкость\" и вернитесь к Лорне Утренний Свет в Доланаар.', '', NULL, NULL, NULL, 'Исцелите часового Шайю и укрепите ее здоровье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5622, 'Во имя Элуны', '$N, тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет. Она расскажет тебе больше о пути Элуны, и с ее помощью ты получишь свое первое облачение, говорящее о твоем статусе $gжреца:жрицы: Элуны.$B$BБудь $gосторожен:осторожна:, и да хранит тебя в пути Элуна!', 'Поговорите в Тельдрассиле с Лорной Утренний Свет.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5623, 'Во имя Света', 'Приветствую тебя, $gюный жрец:юная жрица:. Пришло время узнать больше о нашей вере. После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту. Знания ее велики; к тому же она уже слышала о тебе и о твоем стремлении к Истинному Свету. Она готова поделиться с тобой своей мудростью.', 'Поговорите с жрицей Жозеттой в Элвиннском лесу.', 'Я рада видеть тебя здесь, $N. Нам нужно поговорить о твоем будущем и о пути Света...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5624, 'Облачение Света', 'Обычно я подвергаю всех последователей Света небольшому испытанию. Так я выясняю, достойны ли они своего первого облачения – символа того, что церковь их принимает и поддерживает.$B$BНо сейчас ситуация немного отличается. Один из жителей Златоземья видел раненого стража на берегу озера к востоку отсюда. Этого стража зовут Робертс. Найди его, исцели его раны, придай ему стойкости и вернись сюда. Если ты справишься, я сочту твое испытание завершенным.', 'Найдите стражника Робертса и залечите его раны \"Слабым исцелением\" 2-го уровня. Затем примените к нему \"Слово силы: Стойкость\" и вернитесь к жрице Жозетте в Златоземье.', 'Прекрасно, $N. Теперь город охраняет еще один страж. Приятно видеть, что ты учишься пользоваться своими способностями. Если захочешь узнать что-нибудь новое, возвращайся ко мне. А пока что прими это облачение. Если наденешь его, все будут знать, что ты принадлежишь к нашему ордену. Впрочем, можешь и не надевать, если не хочешь: для выполнения следующих заданий оно не нужно.', 'Возможно, тебе уже известно, что целительская магия необходима для выживания нашего народа, особенно в эти тяжелые и неспокойные времена. Особенно в ней нуждаются путешественники и воины – те, что сражаются мечом и магией со злом, пришедшим в наш мир.$B$BТебе не следует забывать, насколько важно это умение. В совокупности с заклинанием \"Слово силы: Стойкость\" целительская магия сделает твоих друзей могучими воинами, способными бестрепетно переносить удары врага.$B$BНе позволяй никому забыть о мощи твоей магии!', NULL, NULL, 'Исцелите стражника Робертса и укрепите его здоровье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5625, 'Облачение Света', 'Как правило, примерно в эту пору $gпослушники:послушницы: вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе. Но, честно говоря, сейчас у меня есть и более важные дела. Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф.$B$BИзлечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты $gпрошел:прошла: испытание. Справишься?', 'Надите горного пехотинца Дольфа и залечите его раны \"Слабым исцелением\" 2-го уровня. Затем примените к нему \"Слово силы: Стойкость\" и вернитесь к Максану Ковальне в Каранос.', 'Прекрасно, $N. В тебе есть Свет, и в этом нет сомнений.$B$BВот, прими это одеяние. Оно будет показывать всем, что ты жрец, – носи его, если желаешь.$B$BВ будущем тебе придется пройти через другие испытания. Старайся узнать побольше о своих способностях и возможностях. Испытай свою силу в одном-двух одиночных боях, а потом и в группе с другими путниками.$B$BНе страшись никого: твоей силе может позавидовать любой.', 'Ты нашел Дольфа, $N?$B$BНаверное, ты уже знаешь, что наша способность исцелять весьма полезна. Мы можем не только лечить раненых, но и помогать всем так называемым героям, которые пытаются прославить свое имя. При помощи \"Слова Силы: Стойкость\", что позволяет им выдерживать больше ударов, и нашей целительской магии мы все преодолеем!', NULL, NULL, 'Исцелите горного пехотинца Дольфа и укрепите его здоровье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5626, 'Во имя Света!', 'Эй! $N! У тебя есть свободная минутка?!$B$BТы давно уже следуешь пути Света, так ведь? Как насчет того, чтобы сходить к Максану Ковальне в Каранос? Он расскажет тебе побольше о твоей судьбе, а если ты окажешься $Gдостойным:достойной;, он тебе даст твои первые одеяния $gжреца:жрицы:.$B$BТеперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать.', 'Поговорите с Максаном Ковальней в Дун Мороге.', 'О, так тебя послал Брансток? Славно, славно! Он прав, уже пора бы сделать шажок побольше в сторону Света. Это закалит твой характер и укрепит твое тело… и дух.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5627, 'Звезды Элуны', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5628, 'Возвращение домой', 'Если не ошибаюсь, $N? Рад, что ты $gуделил:уделила: мне минутку внимания. Забраться так далеко от дома, да в такие юные годы, – мне по душе твое рвение! Если бы мне в молодые годы хватило духу постранствовать по миру...$B$BТут недавно тебя искала жрица из вашего ордена. Сказала, что тебе спешно надо вернуться в храм Луны в Дарнасе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоем месте не тянул.', 'Поговорите в Дарнасе со жрицей Алатеей.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5629, 'Возвращение домой', 'Еще раз приветствую тебя, $N. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени. Жрица Алатея прислала за тобой. Сдается, ты $gпривлек:привлекла: внимание наших старейшин, и они считают, что ты $gсозрел:созрела: для более великих дел. Отправляйся в дарнасский храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна.', 'Поговорите в Дарнасе со жрицей Алатеей.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5630, 'Возвращение домой', 'Ну здравствуй, $gдруг:подруга. Приятно видеть: что ты так далеко $gзабрался:забралась:! Без обид, но многие из ваших не слишком хорошо переносят тутошние холода. Славно, что ты $gслеплен:слеплена: из более крутого теста.$B$BНе так давно одна из ваших жриц искала тебя – говорила,  чтобы ты $gнашел:нашла: жрицу Алатею в храме Луны в Дарнасе. Должно быть, это важно так что возвращайся туда как можно скорее.', 'Поговорите в Дарнасе со жрицей Алатеей.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5631, 'Возвращение домой', 'Недавно в наших чертогах побывала одна жрица, и она искала вас, $gюный:юная: $r. Она сказала, что ее послали за вами и что вы должны вернуться в храм Луны в Дарнасе как можно скорее. По прибытии найдите жрицу – она расскажет вам больше.$B$BДа пребудет с вами Свет, $N.', 'Поговорите в Дарнасе со жрицей Алатеей.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5632, 'Возвращение домой', 'Да-да, конечно. Здравствуй, $N. Недавно тут побывала посланница нашего ордена. Она искала тебя. Она мельком упомянула, что в Дарнасе случилось что-то важное и что тебе следует как можно скорее вернуться в храм Луны. Сразу поговори там со жрицей Алатеей. Наверняка это касается твоих успехов.$B$BВ общем, возвращайся в Дарнас, как только сможешь.', 'Поговорите в Дарнасе со жрицей Алатеей.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5633, 'Возвращение домой', 'Добро пожаловать, $gдруг:подруга:. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом.$B$BПока ты тут $gстранствовал:странствовала: в наших краях, тебя разыскивала здесь жрица из вашего храма. Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны. Прости, большего не скажу, но мне показалось, что дело важное. Когда доберешься до Храма, поговори со жрицей Алатеей.', 'Поговорите в Дарнасе со жрицей Алатеей.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5634, 'Молитва отчаяния', '', 'Твои услуги, оказанные силам Света, неоценимы, а твои деяния – пример блистательной храбрости для всех, кто путешествует в землях, полных опасностей. Прошу, считай этот урок наградой за все, сделанное тобой.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5635, 'Молитва отчаяния', '$N, тобой заинтересовались наши высшие иерархи. Они желают твоего скорейшего возвращения в Собор Света Штормграда. Вероятно, они считают, что для тебя наступило время нового обучения. Когда доберешься до собора, обратись прямо к верховной жрице Лорене, она расскажет тебе об остальном. Удачи! Да хранит тебя Свет!', 'Поговорите с Верховной жрицей Лореной в Штормграде.', 'Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5636, 'Молитва отчаяния', 'Да благословит тебя Элуна, $r! Надеюсь, что Свет не покидает тебя.$B$BТебя недавно разыскивал один из наших жрецов. Он просил передать тебе, что в Соборе Света Штормграда тебя ожидает Верховная жрица Лорена. Не трать времени даром, твой народ нуждается в тебе.', 'Поговорите с Верховной жрицей Лореной в Штормграде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5637, 'Молитва отчаяния', '$N, тебе пора отправляться в Штормград. Верховная жрица Лорена ожидает тебя в Соборе Света, она хочет поговорить с тобой. Должно случиться что-то особенное, если тобой заинтересовалась сама Верховная жрица. Не знаю, к добру это или к худу. Думаю, что так или иначе все это окажется полезным для тебя.$B$BНе трать много времени, собирайся быстрее.', 'Поговорите с Верховной жрицей Лореной в Штормграде.', 'Дмитроярош, я рада тебя видеть! Нам есть о чем поговорить, но твое обучение важнее всего, ведь это – путь Света.$B$BЕсть знание, которым должны овладеть все прислужники Света. Чувствуешь ли ты в себе достаточно сил? Если да, то перейдем к обсуждению.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5638, 'Молитва отчаяния', 'Эй, $r! Тебя недавно искал один из ваших жрецов! Он просил тебе передать, что тебя очень ждут в Соборе Света. Еще сказал, что это очень важно, и мне кажется, что ему стоит верить. Он был настроен весьма благодушно, так что для тебя это хорошие новости. Тебе стоит поторопиться, чтобы не упустить этот шанс.$B$BДа хранит тебя Элуна, $r.', 'Поговорите с Верховной жрицей Лореной в Штормграде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5639, 'Молитва отчаяния', '$N! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки. Не мешкай. Ты найдешь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!', 'Поговорите с Верховной жрицей Лореной в Штормграде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5640, 'Молитва отчаяния', 'Благословенна будь Элуна, чей свет хранит тебя, $N!$B$BСейчас многие члены нашего ордена решили укрепить свои познания и веру в силу Элуны. Как я знаю, и в твоем ордене происходит то же самое.$B$BКогда закончишь свои дела в Дарнасе, отправляйся к вашей верховной жрице, дабы получить новые знания.', 'Поговорите с Верховной жрицей Лореной в Штормграде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5641, 'Бесстрашие', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5642, 'Страж Тьмы', 'В Оргриммаре происходит нечто важное, $N.$B$BОбычно посланцы, которые приезжают сюда за троллями-жрецами, держатся с ленцой. А на этот раз они, похоже, спешили! Не засиживайся в Громовом Утесе. Думаю, тебе стоит как можно скорее вернуться в Аллею Духов.', 'Поговорите с Ур\'кьо в Оргриммаре.', 'Тебя ждет один из самых важных обрядов инициации для жреца нашей веры, $N. Я вижу, что ты готова к нему, и потому сейчас объясню все подробнее.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5643, 'Страж Тьмы', 'Как и многие из наших жрецов, члены твоего племени проходят обряды инициации. Эти обряды часто наделяют жрецов особыми способностями, которые помогают им выжить. Я чувствую, что тебе пришло время пройти такой обряд. Возвращайся в Аллею Духов в Оргриммаре и поговори с Ур\'кьо. То, чему он тебя научит, может оказаться чрезвычайно важным в будущем.', 'Поговорите с Ур\'кьо в Оргриммаре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5644, 'Всепожирающая чума', 'Доброго тебе дня, $N. Вижу, ты многому $gнаучился:научилась:, и пришло время вернуться к Эльталисте. Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным.$B$BЯ не скажу, что тебя ждет – пусть для тебя это будет сюрпризом. Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки.$B$BОтправляйся в Подгород, поговори с Эльталисте, $N. Она ждет тебя в Квартале Воинов.', 'Поговорите с Эльталисте в Подгороде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5645, 'Бесстрашие', '$N, ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне. Торопитесь, $gмогучий мой друг:могучая моя госпожа:, ибо близится срок вашего очередного испытания. Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но мое место здесь. Но да пребудет с вами Свет в пути вашем. Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии.', 'Поговорите с верховным жрецом Роханом в Стальгорне.', 'Хорошо, что ты пришел, $N. Наша раса горда и могуча, и пришла пора научиться быть таким не только самому, но и вселять эти чувства в сердца других. готов ли ты, юноша?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5646, 'Всепожирающая чума', 'Эльталисте оказала моему народу большое доверие, посылая ко мне учеников, а теперь я сделаю то же для ее племени.$B$BВозвращайся в Подгород, $N. Твоя госпожа ждет тебя в Квартале Воинов, чтобы рассказать еще больше о твоем народе и его обычаях. Ступай, не медли.', 'Поговорите с Эльталисте в Подгороде.', 'Отлично, ты вернулся и даже не опоздал. Нам нужно обсудить кое-что важное, $N. Твоя сила растет, и надо подготовить тебя к грядущим испытаниям.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5647, 'Бесстрашие', 'Твоя раса так сильна, $N. Мы гордимся союзом с вами. С каждым закатом ты и твои сородичи не только все ближе к разгадке вашего истинного происхождения, но и обретаете все большую уверенность в том, что вы на верном пути во многом. Именно эта уверенность приносит вам победу.$B$BНедавно из Стальгорна пришла весть. Тебя просят вернуться и поговорить с верховным жрецом Роханом в Палатах Магии. Не стоит заставлять его ждать. Да направит твой путь Элуна.', 'Поговорите с верховным жрецом Роханом в Стальгорне.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5648, 'Одеяния духовности', 'Что ж, $N, вот ты и $gготов:готова: к своему первому испытанию. К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда. Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас. Ее зовут Корджа. Найди ее, исцели и дай ей благословение наших предков.$B$BСделай это – и я сочту, что ты $gподтвердил:подтвердила: свою готовность ступить на путь жреца.', 'Найдите рубаку Кор\'жу и залечите ее раны \"Слабым исцелением\" 2-го уровня. Затем примените к ней \"Слово силы: Стойкость\" и вернитесь к Тай\'джин в Колючий Холм.', 'Отлично! Так значит, Корджа жива и может снова защищать наш город от злокозненных людей? Я люблю вспоминать дни битв, когда подлинная сила проявлялась в бою. Тогда часто случалось, что мудрые губили тех, кто недооценивал их, полагаясь лишь на мощь мышц.$B$BЯ считаю, что ты молодец, $N. Вот, возьми это одеяние. Может быть, оно тебе пригодится. Может быть, тебе все равно, однако ты его заслужила, и я горжусь тем, что теперь могу звать тебя сестрой.', NULL, NULL, NULL, 'Исцелите рубаку Корджу и укрепите ее здоровье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5649, 'В пользу духовности', 'Понимаешь, наш народ присоединился к Орде, потому что они к нам добры. Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи еще живы. Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне.$B$BТы это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай\'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь $gготов:готова:.', 'Поговорите с Тай\'джин в Дуротаре.', 'Ах-ха... наконец-то твой путь привел тебя к Тай\'джин. Это хорошо.$B$BТеперь ты знаешь, что мы уже не то племя, что когда-то присоединилось к Орде. Мы стали гораздо сильнее. Мы обрели эту силу потому, что научились приспосабливаться – это мы переняли у Орды. Прежде мы побеждали врагов и забирали их силу, теперь же мы набираемся сил, а потом побеждаем врагов.$B$BВозможно, разница не столь заметна, но ты ее поймешь. Ты увидишь. Племя рассчитывает на то, что ты научишься видеть такие вещи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5650, 'Одеяния Тьмы', 'Мы черпаем силу из тьмы и теней, $N, но ваше дело – не только дело тьмы. Вы поняли, что большая заслуга есть и в изучении искусства лечения. Это мудрый выбор. Но прежде чем познать тьму, вы должны познать и свет, а для этого нужно пройти испытание.$B$BК северу от кладбища находится раненый страж смерти по имени Кел – он уже очень долго защищает нас от гноллов, и ему требуется лечение. Но для того чтобы он мог и дальше исполнять свой долг, вы должны также придать ему сил. Используйте для этого свои заклинания, а потом возвращайтесь ко мне.', 'Найдите стража смерти Кела и залечите его раны \"Слабым исцелением\" 2-го уровня. Затем примените к нему \"Слово силы: Стойкость\" и вернитесь к темному священнику Берилу в Брилл.', 'Вы с легкостью выдержали мое испытание. Это хорошо.$B$BСкоро вы будете готовы принять на себя еще большую ответственность, и этот путь приведет вас к более темным силам – таким, которыми не обладает ни один жрец другой расы.$B$BПримите это одеяние в знак вашего положения. Вы его заслужили. Если же вы не хотите его носить, что ж, тогда вы вольны поступить с ним так, как вам будет угодно. Я и другие и так никогда не забудем того положения, которого вы достигли в наших рядах.', 'Наши силы дают нам невероятные возможности, $N, однако скоро вы поймете, что наша способность исцелять раны и повышать наносимый врагам урон является одной из самых полезных и желанных. Не сомневайтесь в выбранном пути жреца – вы не раз убедитесь, что поступили правильно, избрав его. А вот если вы желаете применять магическую энергию для уничтожения врагов, то вам стоило бы лучше отправиться изучать тайную магию.', NULL, NULL, 'Исцелите стража смерти Кела и укрепите его здоровье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5651, 'Во славу Тьмы', 'Отрекшиеся извлекли много уроков из своего опыта и поняли такие вещи, о которых остальные только начинают догадываться. И несмотря на то что наш путь лежит во тьме, скоро ты поймешь, что очень много вещей зависит от нее – так же как и от света. Ты научишься использовать и то и другое... с должной осторожностью. Но никогда не забывай того, что нас создали в тлене и бросили гнить, как какие-нибудь отбросы. Тьма – это наш дом.$B$BКогда захочешь узнать больше, найди темного священника Берила в Брилле.', 'Поговорите с темным священником Берилом в Тирисфальских лесах.', 'Наконец-то вы прибыли! Чтобы пройти испытания, одной веры не достаточно. Нужно еще чувство долга и немного амбиций.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5652, 'Обессиливающий сглаз', '', '', 'Тебе стоит внимательно отнестись к этому уроку. \"Обессиливающий сглаз\" всегда пригодится в бою. Позднее я подвергну тебя испытаниям, чтобы дать тебе возможность показать себя и доказать свою полезность племени.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5654, 'Обессиливающий сглаз', 'Пора тебе встретиться с Ур\'кьо, $N. Ты найдешь его на аллее Духов, в городе орков. Ступай туда и поговори с ним. Пора тебе познать древнюю мудрость нашего народа. Пора вступить в круг и стать настоящим жрецом нашего племени.', 'Поговорите с Ур\'кьо в Оргриммаре.', 'А, ты здесь! Это хорошо. Теперь мы можем начать твое обучение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5655, 'Обессиливающий сглаз', 'Мне нужно было удостовериться, что ты не уйдешь слишком далеко от дома, $N. Меня послали за тобой потому, что Ур\'кьо, величайший из наших жрецов, желает поговорить с тобой. Ступай туда. Ступай в Аллею Духов в городе орков и поговори с Ур\'кьо. Он ждет тебя.', 'Поговорите с Ур\'кьо в Оргриммаре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5656, 'Обессиливающий сглаз', 'Мое нестареющее сердце всегда греет мысль о том, что по миру бродит множество жрецов всех культур. Хорошо знать, что на свете есть сила, не имеющая отношения к тайной магии и вполне доступная нам. Вот почему я сочту за честь указать тебе путь, $N.$B$BУркьо, ваш великий жрец в Оргриммаре, просит тебя прибыть к нему. Ты найдешь его на аллее Духов.', 'Поговорите с Ур\'кьо в Оргриммаре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5657, 'Обессиливающий сглаз', 'Домой! Возвращайся домой, $gюный:юная:$r!$B$BТвой духовный наставник Ур\'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути.$B$BСтупай в Аллею Духов в Оргриммаре, великом городе Орды! Ты найдешь его там.', 'Поговорите с Ур\'кьо в Оргриммаре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5658, 'Прикосновение слабости', '', '', 'А, юный жрец снова здесь. Я хочу преподать тебе урок, который ты не скоро забудешь. Готов ли ты?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5659, '$gNYI: Touch of Weakness', 'Ты $gобратился:обратилась: не туда, $N. Лучше поспеши в Квартал Воинов Подгорода. Эльталисте объявила, что все обучающиеся у нее жрецы и жрицы должны как можно скорее вернуться к ней. Она хочет, чтобы вы получили новые знания о своей силе и о том, как ей управлять.$B$BНе заставляй ее ждать: она не терпит отговорок и опозданий.', 'Поговорите с Эльталисте в Подгороде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5660, 'Прикосновение слабости', 'Далеко же ты $gзабрался:забралась:c:, $C. Тебя ждут в большом городе под землей. Твоя госпожа, Эльталисте, велит тебе вернуться. Как и в моем племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту. Лучше лети в Квартал Воинов на самом быстром дирижабле.', 'Поговорите с Эльталисте в Подгороде.', 'А, вот и еще один. Для меня время не имеет значения, но для тебя оно бежит быстро. Тебе следует многому научиться, и я хочу передать тебе побольше знаний. А пока покажи, на что способен. Выполни это условие, и награда будет велика.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5661, 'Прикосновение слабости', 'Ты всего лишь гость в деревне Кровавого Копыта, $N, а дом твой далеко. Меня послали сюда искать жрецов из моего племени. С ними хотят говорить вожди. Но и тебе я могу помочь.$B$BГоворят, что ваша главная жрица велит всем Отрекшимся прийти к ней – видно, ей есть что сказать.$B$BСтупай, поговори с Эльталисте в Квартале воинов этого вашего города, как его там...', 'Поговорите с Эльталисте в Подгороде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5662, 'Прикосновение слабости', 'Мое почтение тебе и твоему народу, $N. Обычно я учу лишь своих соплеменников. Тебе же передала знания Эльталисте из города, некогда звавшегося Лордероном.$B$BВозвращайся к ней, ведь только она может передать тебе способности, отличающие воинов вашей веры от других.$B$BСтупай в Квартал Воинов Подгорода и отыщи там свою госпожу.', 'Поговорите с Эльталисте в Подгороде.', 'А, вот и еще один. Для меня время не имеет значения, но для тебя оно бежит быстро. Тебе следует многому научиться, и я хочу передать тебе побольше знаний. А пока покажи, на что способен. Выполни это условие, и награда будет велика.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5663, 'Прикосновение слабости', 'Эльталисте послала вести всем своим жрецам. Нам велено отправить молодежь в Подгород на обучение. Если ты в самом деле считаешь себя $gодним:одной: из верных, возвращайся туда.$B$BЭльталисте живет в Квартале Воинов в глубинах Подгорода.', 'Поговорите с Эльталисте в Подгороде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5672, 'Благодать Элуны', '', '', 'Посвятив себя служению Элуне и нашему народу, ты достигла такого положения, которое не всякому из нас доступно. По традиции за великую твою преданность тебя полагается обучить более могучим способностям. Согласна ли ты?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5673, 'Благодать Элуны', 'Знай, что здесь ты можешь в любое время обратиться к любому наставнику, $N. Впрочем, есть знания, которые мы не можем тебе предоставить. Среди них – учение вашей богини Элуны. Верным своим приверженцам она дает особые способности, и, если я не ошибаюсь, тебе пора вернуться домой, в Храм Луны, и пройти испытание.$B$BТак что как сможешь – возвращайся и поговори со жрицей Алатеей.', 'Поговорите в Дарнасе со жрицей Алатеей.', 'Да благословит тебя Элуна за столь скорое возвращение. Это важный период в твоем обучении, и орден весьма серьезно к этому относится. Когда отдохнешь с дороги, дай мне знать. Тогда мы сможем поговорить о продолжении твоего обучения и о том, куда на сей раз приведет тебя твой путь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5674, 'Благодать Элуны', 'Настал славный день, $N. Ты $Gдостиг:достигла; возраста, когда наши $gжрецы:жрицы: изучают те способности, которые свойственны только ночным эльфам. Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела. Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны.', 'Поговорите в Дарнасе со жрицей Алатеей.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5675, 'Благодать Элуны', 'Не тяни время, $gдруг:подруга:. Пора тебе возвращаться домой в Дарнас. Жрица Алатея велит возвращаться на обучение. Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди. Алатея в своем письме говорит, что будет ждать тебя в храме Луны. Удачи.', 'Поговорите в Дарнасе со жрицей Алатеей.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5676, 'Волшебное искажение', '', '', 'Чтобы защититься от тайной магии, которая является нашим основным врагом, мы должны знать некоторые заклинания.Я научу тебя заклинаниям, которые помогут защитить себя и спутников от вредоносного воздействия тайной магии.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5677, 'Волшебное искажение', 'Мне бы хотелось показать тебе кое-какие из наших особых методик обучения, которые направят тебя по пути Света, но меня опередили. Тебе нужно вернуться в Штормград, $N... Прямо сейчас. Поверь мне, так будет лучше. Когда ты встретишься с Верховной жрицей Лореной из Собора Света, ты поймешь, о чем я говорю. Для вашей расы настало время подумать о будущем и выбрать свой собственный путь.', 'Поговорите с Верховной жрицей Лореной в Штормграде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5678, 'Волшебное искажение', 'Тебе пора возвращаться в Штормград. Старшие иерархи призывают тебя продолжить тренировки. Жаль, что мне пришлось разыскивать тебя, но я делаю это во имя союза между нашими расами.$B$BБуду говорить откровенно, тайная магия не внушает мне никакого доверия, хоть по благословлению богов, хоть без них...$B$BТы понимаешь, о чем я говорю? Вернись в Собор Света. Верховная жрица Лорена ждет тебя.', 'Поговорите с Верховной жрицей Лореной в Штормграде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5679, 'Всепожирающая чума', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5680, 'Страж Тьмы', '', '', 'Время обряда уже близко. Теперь я научу тебя заклинанию, которое очень пригодится тебе в битвах с врагами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5713, 'Каждый выстрел – в цель', 'Я направлялась в Аубердин с важным донесением, когда меня атаковал фурболг Марош и его следопыты. Во время атаки я получила отравление, так что еле держусь. Я могу изготовить противоядие, но это займет некоторое время.$B$BХотела попросить вас защитить меня, пока я не приму противоядие. Я подсоблю вам своим луком, как смогу.$B$BЕсли мы выживем, то смогу доставить донесение в Аубердин, а вас попрошу поговорить с Онейей на Заставе Мейстры и проинформировать ее о случившемся.', 'Защитите жизнь часового Айнаши, а потом поговорите с Ойнеей на Заставе Мейстры в Ясеневом лесу.', 'Вы принесли долгожданное известие, $С. Приятно слышать, что Айнаша жива и здорова благодаря вам. Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь.', NULL, NULL, NULL, 'Защитите жизнь Стража Айнаши', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5721, 'Битва при Дарроушире', 'Теперь, $N, тебе предстоит принять участие в битве при Дарроушире и спасти Джозефа Редпата.$B$BПоложи реликвии на городскую площадь Дарроушира, и духи его жителей восстанут из могил. Начнется битва, и ты $gдолжен:должна: сделать все возможное, чтобы Дейвил выжил в битве с Хоргусом, а Редпат должен подвергнуться порче и после этого быть убитым.$B$BВ этом случае дух Редпата будет спасен. Поговори с ним и возвращайся к его дочери Памеле.', 'Положите сверток с реликвиями на городскую площадь Дарроушира.Предотвратите смерть Дейвила Яркосвета от рук Хоргуса.Не допустите смерти капитана Редпата до появления Редпата Падшего. Убейте Редпата Падшего. Поговорите с духом Джозефа Редпата, когда он вновь появится на городской площади, затем отправляйтесь к Памеле и поговорите с ней.', 'Битва окончена! Мой папа сказал мне это! Он разогнал всех духов и возвращается домой! Я так счастлива! $B$BА еще он сказал, чтобы я радушно встретила тебя, так что я приготовила тебе чаю. Ты любишь с сахаром?', 'Там снаружи собрались злые духи. Они шепчут мне всякие ужасы...', NULL, NULL, 'Примите покаяние Редпата', 'Сверток с реликвиями', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5722, 'В поисках потерянного ранца', 'В Огненной пропасти Магату интересуют не только трогги. До нее дошли слухи, что один из ее слуг, некий Маур Зловещий Тотем, будучи в пропасти, нашел нечто особенное, но выбраться оттуда ему не удалось. Она хочет, чтобы кто-нибудь нашел тело Маура – если оно еще цело – и выяснил, что же он такое нашел, пытаясь вести переговоры с троггами.$B$BЕсли найдешь что-нибудь интересное, принеси это Магате, и она наверняка не поскупится на награду.$B$BДа, пропасть ищи в самых темных закоулках Оргриммара.', 'Обыщите Огненную пропасть в поисках тела Маура Зловещего Тотема и найдите все необычные предметы.', 'Тело выглядит так, будто Маура жестоко били дубинками или кулаками, но большая часть одежды и снаряжения на месте. Похоже, троггам не сильно были нужны его пожитки.$B$BВы начинаете осматривать тело в поисках любых предметов, которые могли бы заинтересовать Магату.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5723, 'Испытание силы врага', 'Назойливые твари, известные как трогги, вдруг полезли из заполненных лавой туннелей под Оргриммаром. Магата по своей доброте душевной хотела договориться с этими тварями, но они набросились на ее переговорщиков и перебили их. Но такого обращения с тауренами она допустить не может, так что теперь для нее эти твари – враги Орды.$B$BОна просит тебя разделаться с этими троггами, прежде чем они начнут угрожать Орде из-под земли. Найди Огненную пропасть и уничтожь их всех!', 'Найдите в Оргриммаре Огненную пропасть, убейте 8 троггов и 8 шаманов Огненной пропасти и возвращайтесь к Рахауро в Громовой Утес.', 'Я рад, что ты серьезно отнесся к просьбе Магаты. Спасибо тебе, $N. Теперь, когда троггов поубавилось, они уже не полезут так нагло на поверхность!$B$BМожет, в будущем мы сумеем узнать, откуда взялись эти твари, и что им надо.', NULL, NULL, NULL, 'Трогг Огненной пропасти убито', 'Шаман Огненной пропасти убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5724, 'Возвращение потерянной сумки', 'Под телом погибшего таурена вы находите сумку. Убитый до сих пор крепко держит ее – видимо, он пытался уберечь ее во время нападения троггов.$B$BВысвободив сумку из его крепкой хватки, вы закидываете ее себе на плечо и готовитесь возвращаться наружу из туннелей, чтобы отправиться к Рахауро в Громовой Утес.', 'Отнесите сумку Маура Зловещего Тотема Рахауро в Громовой Утес.', 'Прекрасно, $N. Благодарю тебя.$B$BМагата сказала мне, что если ты найдешь ее сородича, то я должен отдать тебе вот это. Прошу, прими в знак благодарности.', 'Удалось ли что-нибудь найти, $N? Хоть какой-нибудь намек на то, почему ее сородич погиб без нужды?', NULL, NULL, 'Сумка Зловещего Тотема (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5725, '', '', '', 'Молодец, $C. Ты оказал Темной Госпоже хорошую услугу. Ее подданным пригодятся твои упорство и честолюбие. Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Темной Госпоже свергнуть Короля-лича и освободить рабов Плети.', 'Меня ждет сотня дел, $C. Где книги?', NULL, NULL, 'Заклинания Тьмы', 'Магическая формула Пустоты', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5726, 'Тайные враги', 'Чего я не потерплю, $N, так это предательства среди своих. Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползется еще сильнее.$B$BНо ты, $gюный искатель приключений:юная искательница приключений:, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду... можешь обнаружить настоящего главу заговора!$B$BЕсли у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников из клана Пылающего Клинка лейтенантский знак отличия и принеси его мне.', 'Принесите лейтенантский знак отличия Траллу в Оргриммар.', 'Молодец, $N! Слава духам! Быть может, именно ты – тот, кому суждено избавить меня от самых серьезных моих опасений! Ну кто бы мог подумать, что столь юное существо, как ты, сумеет достойно защитить наше дело? Ты мне напоминаешь меня самого в молодости... Я позабочусь о том, чтобы тебя достойно вознаградили за труды – если мы оба переживем грядущую бурю.$B$BЛадно, сейчас не время рассыпаться в похвалах. То, что тебе уже удалось совершить, – пустяки в сравнении с тем, что еще предстоит... Но начало положено хорошее.', 'Ну что, $N, удалось тебе добыть знак отличия? Он необходим, чтобы внедриться в организацию, которая представляет собой самую серьезную угрозу Орде.$B$BТы еще узнаешь, насколько замысловатую сеть способны сплести как орки, так и люди, ведомые алчностью и жаждой власти. Тебе станут очевидны их козни и тайные помыслы. Ты обнаружишь, что вокруг тебя идет война, какая тебе и не снилась!', NULL, NULL, 'Лейтенантский знак отличия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5727, 'Тайные враги', 'Ну-ка, посмотрим, стоил ли принесенный тобой знак отличия таких усилий.$B$BВ городе живет чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель клана Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам еще нужен, мы можем использовать его, чтобы навредить нашим врагам.$B$BОтнеси ему этот знак отличия в Расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за $gодного:одну: из своих. А потом возвращайся ко мне.', 'Отнесите лейтенантский знак отличия Ниру Огненному Клинку. Убедите его в своей преданности клану Пылающего Клинка. Вернитесь к Траллу в Оргриммар.', 'Великолепно, $C! Просто великолепно!$B$BТвое сегодняшнее деяние – всего лишь первый шаг к куда более серьезным делам. Возможно, это поможет нам уничтожить Совет Теней раз и навсегда.$B$BПерескажи мне все, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь.', 'Ну что, $C? Поверил ли он нашему обману, или все хуже, чем я думал поначалу?$B$BЕсли ты докажешь Нииру свою полезность, нам будет куда проще проникнуть в Совет Теней. У Нииру наверняка предостаточно информации, которую можно будет использовать, чтобы извести под корень всех, кто хочет погубить наше дело.', NULL, NULL, 'Убедите Ниру в своей преданности клану Пылающего Клинка', 'Лейтенантский знак отличия', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5728, 'Тайные враги', 'Хм, предводители клана Огненного Клинка... Это серьезно. Если Ниру ими дорожит, значит, именно их и нужно ликвидировать. Этот сатир... Баззалан, и тот, второй, которого упоминал Ниру, – он кто, чернокнижник? – их следует убить.$B$BВозвращайся в Расселину Теней и проникни в Огненную Пропасть, $N. Разыщи этих предводителей клана Огненного Клинка и убей их. Но будь $gосторожен:осторожна:, чтобы Ниру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя $gодним из братьев:одной из сестер: по оружию.', 'Убейте Баззалана и Жергоша Призывателя Духов и вернитесь в Оргриммар к Траллу.', 'Я рад, что ты вернулся, $N. Преданные мне агенты уже сообщили, что в пещерах под Оргриммаром воцарился хаос – теперь, когда их предводители убиты. Мне даже докладывали, что Нииру более чем взбудоражен. Похоже, мы пробили брешь в его броне. Не могу не признать, что меня это радует... Пусть небольшая, но все же победа.', NULL, NULL, NULL, 'Баззалан убито', 'Жергош Призыватель Духов убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5729, 'Тайные враги', 'Думаю, теперь тебе следует попытаться войти в число приближенных Ниру. Если он действительно так взбудоражен, как мне доносят, мы убьем сразу двух зайцев. Во-первых, тебе, возможно, удастся разузнать побольше о Совете или, по крайней мере, о Пылающем Клинке, и, во-вторых, он, возможно, начнет доверять тебе настолько, что попросит ему помогать. Ему сейчас отчаянно не хватает помощников.$B$BВозвращайся в Расселину и поговори с ним, но не особо навязывайся.', 'Поговорите с Ниру Огненным Клинком в Оргриммаре.', 'Ну в чем дело?! Ах, это ты, $C... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всем виноват. Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами. Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5730, 'Тайные враги', 'Теперь ты $gодин:одна: из моих лейтенантов! Готовься, $C. Скоро я призову тебя.$B$BМожно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать. Я сделаю все, что смогу, чтобы свести к минимуму потери здесь, в Огненной Пропасти. А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы. Возвращайся ко мне как можно скорее.', 'Поговорите с Траллом в Оргриммаре.', 'Ясеневый лес? Хм. Впервые слышу о присутствии Совета или Пылающего Клинка в Ясеневом лесу. Я поручу своим агентам это проверить, $N. А ты молодец.$B$BПока отдыхай, занимайся другими делами. Скоро я призову тебя снова.$B$BЛок-тар Огар!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5741, 'Скипетр Света', 'Говорят, что клан Пылающего Клинка, обосновавшийся на востоке в крепости Громового Топора, заполучил скипетр Света, добыв его у наг. Легенда гласит, что этот скипетр обладает властью погружать целые города в пучины моря. Мы не можем позволить, чтобы такая сила оставалась в их руках.$B$BТвой долг – вырвать скипетр из недостойных рук! Сейчас он у ясновидца из клана Пылающего Клинка на одной из башен крепости Громового Топора.', 'Отыщите Скипетр Света и принесите его Азору Альдаморту в башню Этель-Ретор.', 'Неуловимый Скипетр Света!.. Добыв его, ты избавил мир от великой угрозы. Прекрасно, $C, просто прекрасно!..', 'Ты нашел Скипетр Света? Он у тебя?', NULL, NULL, 'Скипетр Света', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5742, 'Искупление', 'Ты славно $gпоработал, друг мой:поработала: подруга;. Отдохни, а я пока расскажу тебе мою историю до конца.', 'Выслушайте Тириона Фордринга.', 'Вернуть моего сына на путь истинный будет нелегко. Ты готов?', 'Прошу, друг мой, сядь и выслушай меня.', NULL, NULL, 'История Тириона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5761, 'Убить тварь', 'Главная задача, которую поручил мне наш великий вождь, – это извести тех тварей, которые повинны в том, что в великий город нашего владыки проникают демоны. Клан Пылающего Клинка – главная, но не единственная угроза. Есть еще и Огненный Клинок, клан, который обосновался в Огненной Пропасти и втайне смущает умы простых представителей Орды.$B$BЧтобы их остановить, нужно убить их предводителя, стража Скверны по имени Тарагаман Ненасытный.$B$BУбей его. Я уверен, Вождь будет рад получить его сердце...', 'Спуститесь в Огненную пропасть, убейте Тарагамана Ненасытного и принесите его сердце Ниру Огненному Клинку в Оргриммаре.', 'Ага! Тебе это удалось! Тралл, конечно, будет в восторге.$B$BЯ позабочусь о том, чтобы это сердце попало по назначению.$B$BНу, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоем успехе.$B$BСпасибо за помощь, $C.', 'Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!', NULL, NULL, 'Сердце Тарагамана Ненасытного', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5762, 'Хеминг Эрнестуэй-младший', 'У меня тут посылка для нового покупателя по имени Хеминг Эрнестуэй-младший. Посылка шла очень долго, и Хеминг давно уехал, не дождавшись ее. Говорят, что теперь он где-то в Тернистой долине, охотится там на зверей вместо отца. Перед отъездом он оставил мне немного денег, чтобы я переслал ему посылку.$B$BОн очень богатый дворф, а с такими полезно водить дружбу, правда? Так что... не желаете ли доставить Хемингу эту посылку?$B$BГоворят, он разбил лагерь в Тернистой долине, к северу от Гром\'гола.', 'Отнесите ящик Крейвела Хемингу Эрнестуэю младшему в Тернистую долину.', 'Отлично, посылочка от Углебрада! Спасибо, $N! В этом ящике находится специальное измерительное оборудование, – по крайней мере так сказал мой отец, – и в джунглях оно нам очень пригодится.$B$BВот ваша плата, и расскажите мне, как там поживает старина Углебрад? Наверняка опять замышляет какую-нибудь пакость?', 'Уж не пустынная ли это пыль у тебя на воротнике?$B$BХм... Если мой нос не врет, то это не пыль, а соль! Прямиком с Мерцающей равнины, да?', NULL, NULL, 'Сундук Крейвела (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5763, 'Охота в Тернистой долине', 'Давным-давно пришел в эти земли дворф. Звали его Хеминг, и он хотел поохотиться на крупного зверя. С ружьем он умел обращаться просто великолепно, и много дней мы охотились с ним вместе, забыв даже о вражде, разделявшей наши народы...$B$BКогда он уходил в Тернистую долину, я поклялся, что, когда бы он ни вернулся, я встречу его как дорогого гостя. Ныне он отправился охотиться в неведомые земли, но успел воспитать сына, достойного отцовской славы.$B$BОтнеси этот рог кодо в подарок Хемингу-младшему. Ты найдешь его в Тернистой долине, к северу от лагеря Гром\'гол.', 'Отнесите рог кодо, принадлежащий Руну, Хемингу Эрнестуэю младшему в Тернистую долину.', 'О, этот рог принадлежит таурену Руну Буйногривому! Отец часто рассказывал о том, как славно они вместе охотились в Пустошах. Значит, Рун приглашает меня на охоту, да?$B$BУ нас сейчас дел по горло, но я все равно благодарен тебе за добрую весть, $N. Возможно, следующая моя экспедиция будет в Пустоши, в земли кентавров.', 'Присядь и отдохни, $C. Скоро ты снова отправишься в джунгли...', NULL, NULL, 'Рог кодо, принадлежащий Руну (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5781, 'Символ ушедших дней', 'Чтобы помочь Телану вернуться на путь истинный, мы должны найти то, что напомнит ему о прошлом.$B$BОдин из таких предметов  – игрушка, которую я подарил ему на сем$Nие. Он очень дорожил этим маленьким боевым молотом, уменьшенной копией моего собственного оружия.$B$BКогда меня изгнали за предательство, его мать сказала сыну, что я погиб. Его отвели к моей пустой могиле в Крипте, и там он похоронил свой молот вместе со всеми воспоминаниями обо мне.$B$BПрошу тебя, отправляйся в Крипту и принеси молот Телана.', 'Отправляйтесь в Крипту – в самой южной части Восточных Чумных земель – и добудьте молот Телана. Отнесите его Тириону Фордрингу.', '*Тирион с трудом сдерживает слезы.*$B$BСама судьба свела нас вместе, $N. Да благословят тебя небеса за доброту.', 'Он должен быть спасен.', NULL, NULL, 'Молот Телана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5801, 'Кузня Пламенного хребта', 'Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу.$B$BНа западе от кратера Ун\'Горо располагается вулкан Огненного Венца – действующий вулкан. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава.$B$BВот и все, чем я могу тебе помочь. Как доделать ключ тебе подскажет Арбингтон.', 'Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину вулкана Огненного Венца в кратере Ун\'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.Отнесите недоделанную отмычку алхимику Арбингтону на берег Промозглого Ветра в Западные Чумные земли.', 'Недешево обошлась тебе эта отмычка, а? И все же работа над ней не закончена; пришло время завершающего этапа – а это самое сложное. Тебе придется выступить против того самого врага, что ждал нас в Андорале... Злобной твари, которая правит бал в стенах разрушенного города.$B$BЯ говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети.', 'Тебе удалось сделать заготовку отмычки? Мне жаль, что тебе пришлось покупать форму на свои деньги, но всем приходится вносить свой вклад в борьбу с Плетью. Отдай мне заготовку отмычки, и я скажу, чего не хватает для завершения работы над ней.$B$BЭто будет нелегко, но подготовка к нападению на Андорал не пропадет втуне. Вот увидишь.', NULL, NULL, 'Недоделанная отмычка', 'Форма для отливки отмычек', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5802, 'Кузня Пламенного хребта', 'Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу.$B$BНа западе от кратера Ун\'Горо располагается вулкан Огненного Венца – действующий вулкан. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава.$B$BВот и все, чем я могу тебе помочь. Как доделать ключ тебе подскажет Дитерс.', 'Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину вулкана Огненного Венца в кратере Ун\'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.Отнесите недоделанную отмычку аптекарю Дитерсу в Бастион, что в Западных Чумных землях.', 'Недешево обошлась тебе эта отмычка, а? И все же работа над ней не закончена; пришло время завершающего этапа – а это самое сложное. Тебе придется выступить против того самого врага, что ждал нас в Андорале... Злобной твари, которая правит бал в стенах разрушенного города.$B$BЯ говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети.', 'Тебе удалось сделать заготовку отмычки? Мне жаль, что тебе пришлось покупать форму на свои деньги, но всем приходится вносить свой вклад в борьбу с Плетью. Отдай мне заготовку отмычки, и я скажу, чего не хватает для завершения работы над ней.$B$BЭто будет нелегко, но подготовка к нападению на Андорал не пропадет втуне. Вот увидишь.', NULL, NULL, 'Недоделанная отмычка', 'Форма для отливки отмычек', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5803, 'Скарабей Аража', 'Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа.$B$BПроберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея!$B$BКлюч от Некроситета ждет тебя, $N!', 'Убейте Аража Призывателя отнесите его скарабея алхимику Арбингтону на Берег Промозглого Ветра, что в Западных Чумных землях.', 'А, вот она! Я... поражен твоей отвагой и хитростью. У меня в голове не укладывается, на что ты готов пойти ради победы над силами тьмы.$B$BПозволь и мне сыграть свою небольшую роль в твоем подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верзней части ключа. Его сила отомкнет двери Некроситета.$B$BНу вот, остался пустячок...', 'Ты сумел далеко зайти, $N – но только уничтожение физического облика Аража Призывателя даст нам возможность завершить работу над ключом. Добудь скарабея Араджа – любым из возможноых способов – и принеси мне, и я сделаю из него головку ключа.', NULL, NULL, 'Скарабей Аража', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5804, 'Скарабей Аража', 'Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа.$B$BПроберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея!$B$BКлюч от Некроситета ждет тебя, $N!', 'Убейте Аража Призывателя и отнесите его скарабея аптекарю Дитерсу в Бастион, что в Западных Чумных землях.', 'А, вот она! Я... поражен твоей отвагой и хитростью. У меня в голове не укладывается, на что ты готов пойти ради победы.$B$BПозволь и мне сыграть свою небольшую роль в твоем подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верзней части ключа. Его сила отомкнет двери Некроситета.$B$BМного времени это не займет...', 'Ты сумел далеко зайти, $N – но только уничтожение физического облика Аража Призывателя даст нам возможность завершить работу над ключом. Добудь скарабея Аража – мытьем или катаньем – и принеси мне, и я сделаю из него головку ключа.', NULL, NULL, 'Скарабей Аража', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5805, 'Привет!', 'Добро пожаловать в \"World of Warcraft\"!$B$BВ знак особой благодарности за приобретение коллекционного издания \"World of Warcraft\" примите этот подарочный сертификат и передайте Мериссе Стилвелл в Златоземье. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$B$BЕще раз благодарим вас и желаем приятного пребывания в \"World of Warcraft\"!', 'Передайте подарочный сертификат Златоземья Мериссе Стилвелл. ', '', NULL, NULL, NULL, 'Подарочный сертификат Златоземья (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5821, 'Наемный телохранитель', 'Обычно мы с Риггером проводим кодо мимо поселения кентавров из племени Колкар. Боевые барабаны кентавров слышно издалека, так что, едва заслышав их, мы останавливаемся, чтобы переждать опасность. Мертвый торговец, знаешь ли, плохой торговец!$B$BВот что я тебе скажу, $C: если ты будешь охранять нас по дороге мимо деревни Колкар, мы в долгу не останемся.$B$BРасстояние-то небольшое, да и делать почти ничего не придется – только проследить за тем, чтобы караван был цел. А награду ты получишь, не сомневайся, обращайся к Смиду Заржавеню, мы с ним обделываем кое-какие делишки. Он живет чуть дальше по дороге.', 'Охраняйте караван Гизлтона на пути мимо деревни кентавров из племени Колкар. О награде поговорите со Смидом в Лагере Заржавня.', 'Знаешь ли, мне не кажется такой уж хорошей идеей платить таким, как ты, за охрану каравана Гизлтона, $C. Будь я повыше ростом, взялся бы за работу по совместительству. Только представь: сижу это я на кодо в седле, а в руках у меня – самая большая в мире пушка, и я готов показать этим кентаврам, где нежить зимует... А?', NULL, NULL, NULL, 'Охраняйте караван Гизлтона на пути мимо деревни кентавров из племени Колкар', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5841, 'Привет!', 'Добро пожаловать в World of Warcraft!$B$BВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Йори Шлемолому в Караносе. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$B$BЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!', 'Принести Йори Шлемолому подарочный сертификат Караноса.', '', NULL, NULL, NULL, 'Подарочный сертификат Караноса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5842, 'Привет!', 'Добро пожаловать в World of Warcraft!$B$BВ качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Орентилу Шепоту Ветра в Доланааре. Вас ждет подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. $B$BЕще раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!', 'Отнесите подарочный серитификат Доланаара Орентилу Шепоту Ветра.', '', NULL, NULL, NULL, 'Подарочный сертификат Доланаара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5843, 'Привет!', 'Добро пожаловать в World of Warcraft!$B$BВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Магге в Колючем Холме. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$B$BЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!', 'Передайте подарочный сертификат Колючего Холма Магге в Колючем Холме.', '', NULL, NULL, NULL, 'Подарочный сертификат Колючего Холма (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5844, 'Привет!', 'Добро пожаловать в World of Warcraft!$B$BВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Ворну Небесному Провидцу в деревне Кровавого Копыта. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$B$BЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!', 'Отнесите подарочный сертификат деревни Кровавого Копыта Ворну Небесному Провидцу.', '', NULL, NULL, NULL, 'Подарочный сертификат деревни Кровавого копыта (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5845, 'Символ утраченной чести', 'Со смертью Утера орден Серебяной Длани утратил боевой дух.$B$BМой мальчик держался до последнего. Но, отступая в разоренную деревушку Северного дола, он принял окончательное решение.$B$BВыжил ли кто из ордена, подумал он, да и какая разница?$B$BС этой мыслью Телан бросил знамя Серебряной Длани и отрекся от всего, что прежде было ему дорого. Его честь осталась на обагренной кровью земле Северного дола.$B$BОтправляйся в Северный дол и принеси мне этот символ утраченной чести.', 'Отправляйтесь в Северный дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу.', 'Даже в столь плачевном состоянии оно так же прекрасно, как и в тот день, когда я принес присягу, глядя на него.$B$BВозможно, вместе с этим знаменем ты спас и мою душу.', 'Моя вера поможет тебе, $N. Свет не ведает пределов.', NULL, NULL, 'Символ утраченной чести', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5846, 'Символ семейной любви', 'Когда Телан был маленьким, мы нередко ездили в Каэр Дарроу. В последний раз художница по имени Ренфри изобразила всю нашу семью на берегу. Это лучшее мое воспоминание о Телане и Карандре. Именно тогда, стоя рядом с женой и держа на руках сына, я чувствовал глубокую связь с собственной семьей, которую мне не дано было почувствовать вновь.$B$BЕсли эта картина все еще существует, найди ее.$B$BОтправляйся на разоренный остров Каэр Дарроу и выясни, уцелел ли художник или картина.', 'Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину.', 'Как я могла забыть? Многие духи этого острова обречены хранить последние счастливые воспоминания перед трагической гибелью.$B$BПроклятье это коснулось и меня – я одна из немногих, кто помнит все…$B$BБыть может, именно эта вещь, которая тебя интересует, держит меня прикованной к этим руинам. Я расскажу тебе все, что знаю, в надежде, что это дарует мне свободу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5847, 'Привет!', 'Добро пожаловать в World of Warcraft!$B$BВ качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Клэр Вилловер в Брилле. Вас ждет подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. $B$BЕще раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!', 'Отнесите подарочный сертификат Брилла Клэр Вилловер.', '', NULL, NULL, NULL, 'Подарочный сертификат Брилла (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5848, 'Символ семейной любви', 'На стене мой мастерской... В казармах ордена... долгие годы висела картина.$B$BПосле суда над Тирионом я знала, что не смогу держать ее на виду. Я спрятала ее так, чтобы никто не нашел.$B$BОтправляйся в Стратхольм и проберись в то, что ныне зовется бастионом Алого ордена. Найди там картину с двумя лунами. Сними лишнюю краску и увидишь мой шедевр – \"Символ семейной любви\".$B$BДа направит Свет твою руку.', 'Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира.Отнесите картину Тириону Фордрингу.', '*При виде картины Тирион хватается за сердце.*$B$B*Он начинает всхлипывать.*', 'Картина. Где картина?', NULL, NULL, 'Символ семейной любви', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5861, 'Найти Миранду', 'Ты $gсделал:сделала:  все, о чем я тебя просил. Остался один, последний шаг на пути к спасению.$B$BОтнеси все собранные тобой предметы Телану. К сожалению, Телан и его рыцари Алого ордена нападут на тебя, едва завидев.$B$BЕсть только один способ доставить мое сообщение – приняв обличье врага.$B$BНа юге отсюда находится гробница Утера. Там живет моя старая добрая подруга, Миранда. Найди ее, покажи все собранные тобой предметы, и она тебе поможет.', 'Отправляйтесь к гробнице Утера, которая находится в южных Чумных землях. Покажите Миранде Колдунье подарок Тириона.', 'Я была самой доверенной советницей Тириона, когда он носил титул лорда $Nенхольдского. Я открыто отреклась от вердикта ордена Серебряной Длани и была изгнана за неповиновение.$B$BНа долю Тириона выпало много боли и разочарований. Готов ли ты исправить несправедливости, обрушившиеся на Фордрингов?', 'Я давно дожидалась этого дня.', NULL, NULL, 'Подарок Тириона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5862, 'Уловка против Алого ордена', 'Я, как говорится, иллюзионистка. Хотя я могу создать иллюзию, благодаря которой ты проберешься в Дольный Очаг, помни – сила моя не безгранична.$B$BЕсли ты забредешь слишком далеко, иллюзия рассеется. Заклинание требует от меня значительного количества сил и сосредоточения, и я не слишком долго смогу поддерживать его.$B$BКогда будешь $gготов:готова: – обращайся.', 'Поговорите с Мирандой, пусть она наложит на вас алую иллюзию. Отправляйтесь в Дольный Очаг, покуда она действует, и отнесите подарок Тириона верховному лорду Телану Фордрингу.Дольный Очаг на севере, а Телан должен быть внутри крепости $Nенхольд.', 'Что это, солдат?$B$BТаэлан открывает коробку и начинает рассматривать содержимое.*$B$BЭтого... Этого не может быть. Но все, что ты мне показала…$B$B*Таэлан опускается на колено, сердце у него колотится. На этот город того и гляди выплеснется ярость веков.*', 'Ты прибыла нам на помощь из Длани Тира?', NULL, NULL, 'Подарок Тириона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5863, 'Поселение Песчаного Молота', 'Совсем недавно в Танарисе появились огры-кочевники. Они захватили большой участок пустыни к югу отсюда и построили целую крепость. Племена поменьше бродят по пустыне, захватывая руины тролльских городов.$B$BПоселение Песчаного Молота должно пасть! Не позволим же ограм превратиться в страшную силу.$B$BИх главаря зовут Гор\'марок Опустошитель. Мне кажется, что если его устранить, это станет началом конца огров.', 'Анди Линн из Прибамбасска просит уничтожить поселение Песчаного Молота, убив 10 громил и 10 мародеров из клана Песчаного Молота и Гор\'марока Опустошителя.', 'Я так рада, что ты выполнил мою просьбу, $N! Спасибо за помощь!', NULL, NULL, NULL, 'Громила из клана Песчаного Молота убито', 'Головорез из клана Песчаного Молота убито', 'Гор\'марок Опустошитель убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5881, 'Смена караула', 'Орда не дает нам растерять силы, и это правильно! С самой Великой Войны мы здесь, в Калимдоре, живем неплохо.$B$BЯ прошу тебя оказать мне услугу: один парень по имени Гриш Выносливый Гонец охраняет Великий подъемник в западных пустошах. Передай ему это письмо: там говорится, что один из солдат запаса скоро придет ему на смену, чтобы он мог навестить свою семью. Гриш недавно просил об этом, и он будет рад услышать эти новости.', 'Маггран просит вас передать письмо Гришу Выносливому Гонцу у Великого подъемника в Степи.', 'Это хорошие новости; я слишком долго сижу здесь, охраняя этот кусок дерева. Теперь я смогу побыть со своими родными... Ура!', 'У тебя какие-то новости от землепряда Магграна?', NULL, NULL, 'Письмо Магграна о вызове подкрепления (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5882, 'Лекарство из охотничьих трофеев', '', '', 'Очень хорошо, вот тебе кенарийский бальзам. Ищи в Оскверненном лесу пораженные растения, Кеа! Когда найдешь, исцеляй их при помощи моего целебного бальзама.', NULL, NULL, NULL, 'Оскверненный осколок души', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5883, 'Лекарство из минералов', '', '', 'Что же, прекрасно! Вот тебе кенарийский бальзам. Если при разработках жил металлов в Оскверненном лесу найдешь еще порченого купороса, не забудь принести его мне! Чем больше найдешь, тем больше бальзама я смогу сделать.', NULL, NULL, NULL, 'Затронутый порчей купорос', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5884, 'Лекарство из оскверненных трав', '', '', 'Отличная работа, $N – все это после очищения пойдет на исцеление Оскверненного леса. Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес. Исцеление этого края от порчи не терпит отлагательств!', NULL, NULL, NULL, 'Зародыш Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5885, 'Лекарство из оскверненных шкур', '', '', 'То что нужно! Вот, бери этот бальзам для исцеления растений и лечи им Оскверненный лес от порчи! Мы не должны сдаваться, $N!', NULL, NULL, NULL, 'Клочок порченой шкуры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5886, 'Лекарство из распыленных предметов', '', '', 'Вот тебе кенарийский бальзам, и за него я прошу только одну порцию простой субстанции Пустоты, $N. Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала. Если тебе понадобится еще бальзам, ищи меня тут!', NULL, NULL, NULL, 'Простая субстанция Хаоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5887, 'Лекарство из охотничьих трофеев', '', '', 'Очень хорошо, вот тебе кенарийский бальзам. Ищи в Оскверненном лесу пораженные растения, $N! Когда найдешь, исцеляй их при помощи моего целебного бальзама.', NULL, NULL, NULL, 'Оскверненный осколок души', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5888, 'Лекарство из минералов', '', '', 'Что же, прекрасно! Вот тебе кенарийский бальзам. Если при разработках жил металлов в Оскверненном лесу найдешь еще порченого купороса, не забудь принести его мне! Чем больше найдешь, тем больше бальзама я смогу сделать.', NULL, NULL, NULL, 'Затронутый порчей купорос', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5889, 'Лекарство из оскверненных трав', '', '', 'Отличная работа, $N – все это после очищения пойдет на исцеление Оскверненного леса. Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес. Исцеление этого края от порчи не терпит отлагательств!', NULL, NULL, NULL, 'Зародыш Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5890, 'Лекарство из оскверненных шкур', '', '', 'То что нужно! Вот, бери этот бальзам для исцеления растений и лечи им Оскверненный лес от порчи! Мы не должны сдаваться, Бурн!', NULL, NULL, NULL, 'Клочок порченой шкуры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5891, 'Лекарство из распыленных предметов', '', '', 'Вот тебе кенарийский бальзам, и за него я прошу только одну порцию простой субстанции Пустоты, $N. Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала. Если тебе понадобится еще бальзам, ищи меня тут!', NULL, NULL, NULL, 'Простая субстанция Хаоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5892, 'Припасы Железного рудника', 'Пока не началась война, мы хранили припасы для Дун Болдара на Железном руднике. Когда у нас были войска, чтобы охранять рудник, трогги не были такой уж большой проблемой, но сейчас мы сражаемся с Ордой и не в силах его удерживать.$B$BТем не менее, припасы с Железного рудника нам очень нужны, $N. Отправляйся туда и добудь их.', 'Принесите 10 ящиков припасов Железного рудника интенданту Альянса в Дун Болдар.', 'Отлично! Уж я найду применение этому добру. Спасибо, $N!', 'Что, $N, удалось раздобыть припасы? Их вечно не хватает...', NULL, NULL, 'Припасы Железного рудника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5893, 'Припасы из рудника Ледяного Зуба', 'Рудник Ледяного Зуба, к северу отсюда, был идеальным местом для хранения припасов. Но сейчас, когда разгорелась война с кланом Грозовой Вершины, у нас не хватает солдат, чтобы его постоянно патрулировать и охранять. Так что рудник постоянно переходит из рук в руки, – то к Альянсу, то к местным подземным жителям...$B$BНо припасы нам по-прежнему нужны, $N! Ступай на рудник Ледяного Зуба и добудь их. Будь $gосторожен:осторожна: – в этом месте то и дело возникают стычки.', 'Доставьте 10 припасов Ледяного Зуба интенданту Орды в крепость Северного Волка.', 'А, вот они! Отличная работа, $N Припасы немного заплесневели – сказывается влажность воздуха в руднике – но все равно сгодятся.$B$BСпасибо тебе, Гонзага. Ты помог нашим войскам поддержать силы.', 'Ты вернулся с рудника Ледяного Зуба? А где припасы?', NULL, NULL, 'Припасы из рудника Ледяного Зуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5901, 'Чума на вашу лесопилку!', 'Ну все, теперь у меня есть партизанский план борьбы с Алым орденом! Для начала они расплатятся за свои деяния лесопилкой. Вот они у меня попрыгают! Посмотрим, будут ли они также лихо перестраивать все в городе под свои нужды, когда я перекрою им поступления стройматериалов. Поможешь мне, $N?$B$BВозьми эту банку и отправляйся в Проклятый лес, что в Восточных Чумных землях. Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!', 'Возьмите пустую банку для термитов и отправляйтесь к большим термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.', 'Замечательно, $N. Благодарю тебя.$B$BЕсли не сдрейфил, продолжим!', 'Ну как, нашел термитники, $N? Не сомневаюсь, такой умный $C справится с такой простенькой задачей!$B$BНаберем термитов и устроим диверсию на лесопилке!', NULL, NULL, 'Пустая банка для термитов (Прилагается)', 'Термиты Чумных земель', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5902, 'Чума на вашу лесопилку!', 'Теперь у нас просто прорва термитов. Я надежно запрятал их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдешь, если свернешь на запад с дороги, ведущей отсюда в город.$B$BКак будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик.$B$BГлавное открыть, а уж дальше термиты сами разберутся. А потом возвращайся ко мне – я придумаю, чем тебя порадовать.', 'Найдите подходящее место в центре лесопилки Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов из Чумных земель.', 'Как только бочонок оказывается открыт, водопад термитов обрушивается из-под крышки.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5903, 'Чума на вашу лесопилку!', 'Я долгое время пытался бороться с Алым орденом в открытую, но без толку. Теперь я подумываю прибегнуть к некоторым партизанским методам – если не можешь одержать победу, хотя бы отрави врагу существование!$B$BЕсли хочешь мне помочь, слушай мой план: я собираюсь подбросить им на лесопилку самых зловредных термитов из всех существующих.$B$BЭти твари водятся в Проклятом лесу недалеко от Стратхольма – их колония пережила чуму и переродилась в новый, еще более живучий вид. Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!', 'Возьмите пустую банку для термитов и отправляйтесь к большим термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Восточные Чумные земли.', 'Замечательно, $N. Благодарю тебя. Их так много... честное слово, мне даже жаль бедняг из Алого Марша! Впрочем, лесопилка-то все равно не их, они ее нагло присвоили, так ведь?', 'Ну как, нашел термитники, $N? Их полно в Проклятых землях.', NULL, NULL, 'Пустая банка для термитов (Прилагается)', 'Термиты Чумных земель', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5904, 'Чума на вашу лесопилку!', 'Теперь у нас просто прорва термитов. Я надежно запрятал их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдешь, если свернешь на запад с дороги, ведущей отсюда в город.$B$BКак будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик.$B$BГлавное открыть, а уж дальше термиты сами разберутся. Едва ли Алый Марш сможет впредь использовать лесопилку!', 'Найдите подходящее место в центре лесопилки Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов из Чумных земель.', 'Как только бочонок оказывается открыт, водопад термитов обрушивается из-под крышки.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5921, 'Лунная поляна', 'На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны. Теперь, когда ты $gвстал:встала: на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься на Лунную поляну. Пользуйся им, когда тебе нужно знание или уединение Лунной поляны.$B$BВот первый урок: отправляйся на Лунную поляну и поговори с Дендритом Блеском Звезд в Ночной Гавани о том пути, по которому ты ныне следуешь. Удачи тебе.', 'При помощи заклинания \"Телепортация: Лунная поляна\" перенеситесь на Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.', '\"Да будет так, отец Кенарий. Да будет так.\"$B$BДендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы.$B$B\"Первое обличье, которое тебе следует освоить, – это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота! И так отныне будет всегда.\"', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5922, 'Лунная поляна', 'На священной земле Лунной поляны рады всем друидам – и тауренам, и эльфам. Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погруженными в спячку друидами. Теперь, когда ты знаешь путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься на Лунную поляну. Пользуйся им всегда, когда тебе нужно знание или уединение Лунной поляны.$B$BВот первый урок – отправляйся на Лунную поляну и поговори с Дендритом Блеском Звезд в Ночной Гавани о том пути, которым ты ныне следуешь. Удачи тебе.', 'При помощи заклинания \"Телепортация: Лунная поляна\" перенеситесь на Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.', '\"Да будет так, отец Кенарий. Да будет так.\"$B$BДендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы.$B$B\"Первое обличье, которое тебе следует освоить, – это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота! И так отныне будет всегда.\"', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5923, 'Голос Природы', 'Не уделишь мне минутку внимания?..$B$BМне сообщили, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Матренгил – непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила.$B$BОн живет в анклаве Кенария в Дарнасе, на втором уровне дерева Фэндрала Оленьего Шлема.', 'Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнасе.', 'Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5924, 'Зов Природы', 'Не уделишь мне минутку внимания?..$B$BМне сообщили, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Матренгил – непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила.$B$BОн живет в анклаве Кенария в Дарнасе, на втором уровне дерева Фэндрала Оленьего Шлема.', 'Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнасе.', 'Я рад, что ты добралась сюда, мой юный друид. Пришло время тебе сделать большой шаг в огромный мир.$B$BКаждый из детей Кенария слышит внутри себя призыв служить природе. Животные и растения – наши друзья, а также и наша забота. Таков наш выбор – посвятить жизни сохранению равновесия во имя блага всего живого. Твой первый шаг в этот мир будет заключаться в изучении пути медведя, в изучении силы тела и силы сердца.$B$BПриготовься!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5925, 'Голос Природы', 'Не уделишь мне минутку внимания?..$B$BМне сообщили, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Матренгил – непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила.$B$BОн живет в анклаве Кенария в Дарнасе, на втором уровне дерева Фэндрала Оленьего Шлема.', 'Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнасе.', 'Я рад, что ты нашел сюда дорогу, юный друид. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5926, 'Голос Природы', 'Прости меня, друг мой…$B$BМне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься.$B$BТы найдешь его в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.', 'Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.', 'Я рад, что ты нашел сюда дорогу, мой юный друид. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов служения природе. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Твой первый шаг в этот мир станет шагом медведя – ты познаешь, что такое сила тела и духа.$B$BГотовься!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5927, 'Зов Природы', 'Прости меня, друг мой…$B$BМне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься.$B$BТы найдешь его в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.', 'Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5928, 'Зов Природы', 'Прости меня, друг мой…$B$BМне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься.$B$BТы найдешь его в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.', 'Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.', 'Я рад, что тебе удалось добраться сюда, мой юный друид. Пришла тебе пора сделать очередной большой шаг на своем славном пути!$B$BВ каждом из детей Кенария живет стремление служить природе. Животные и растения – не только наши подопечные, но и наши друзья. Мы посвящаем свою жизнь сохранению равновесия не только ради себя, но и ради них. И первым твоим шагом в этот мир природы будет изучение медведя. Благодаря ему ты обретешь силу тела и духа.$B$BГотовься же!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5929, 'Дух Великого Медведя', 'В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который дает начала понимания истинной природы медведя. Всем друидам в определенный момент требуется мудрость этого существа, и ты не исключение.$B$BОтправляйся же прямо сейчас к духу Великого Медведя и познай все, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты $gусвоил:усвоила: его уроки.', 'Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд на Ночную Гавань в Лунной поляне.', 'Дендрит делает еще один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается.$B$B\"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоем сила и осознанное стремление, хотя еще и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя.\"', 'Возвращайся только тогда, когда дух Великого Медведя отпустит тебя ко мне. Без его благословения твое обучение не может продолжаться.', NULL, NULL, 'Найдите духа Великого Медведя и усвойте все, что он расскажет вам о природе медведя.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5930, 'Дух Великого Медведя', 'В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который дает начала понимания истинной природы медведя. Всем друидам в определенный момент требуется мудрость этого существа, и ты не исключение.$B$BОтправляйся же прямо сейчас к духу Великого Медведя и познай все, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты $gусвоил:усвоила: его уроки.', 'Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань на Лунной поляне.', 'Дендрит делает еще один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается.$B$B\"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоем сила и осознанное стремление, хотя еще и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя.\"', 'Возвращайся только тогда, когда дух Великого Медведя отпустит тебя ко мне. Без его благословения твое обучение не может продолжаться.', NULL, NULL, 'Найдите духа Великого Медведя и усвойте все, что он расскажет вам о природе медведя.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5931, 'Возвращение в Дарнас', 'Пришла пора нашим дорогам разойтись, дитя мое, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Матренгил Медвежья Лапа живет в истинном равновесии с природой, хотя и обитает опасно близко к тому месту, где это равновесие пошатнулось. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия.$B$BСтупай же, дитя. Мы еще встретимся.', 'Вернитесь в Дарнас и поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария.', 'С возвращением, $N. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной.$B$BДух Великого Медведя был частью Азерота с самого его возникновения. Мы полагаемся на его мудрость и могущество в достижении наших целей. Теперь пришла пора тебе пройти первое свое испытание на этом пути. Слушай же...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5932, 'Возвращение в Громовой Утес', 'Пришла пора нашим дорогам разойтись, дитя мое, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Хотя таурены недавно вступили на путь Кенария, Тюрак Рунический Тотем живет в равновесии с природой. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия.$B$BСтупай же, дитя. Мы еще встретимся.', 'Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин.', 'С возвращением, $N. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной.$B$BДух Великого Медведя был частью Азерота с самого его возникновения. Мы, таурены, внимательно прислушиваемся к таким духам, и его цели ведут нас к процветанию. Теперь пришла пора тебе пройти первое свое испытание на этом пути. Слушай же...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5941, 'Возвращение к Хроми', 'Ты $gсобрал:собрала: многие реликвии, сохранившиеся со времен битвы при Дарроушире. Они взывают ко мне... умоляют изменить судьбу жителей Дарроушира.$B$BДа, звучит абсурдно, но Хроми, странный гном, живущий в Андорале, убеждает меня, что это возможно. Она говорит, ты можешь спасти Дарроушир! $B$BТы $gдолжен:должна: отнести эти реликвии ей, она ждет тебя в разрушенной таверне в Андорале.', 'Отнесите сумку с реликвиями Хроми в Андорал. ', 'Ага, вот они... Они послужат основой для мощного заклинания, которое сможет призвать духов Дарроушира.$B$BС помощью этих чар и толики удачи мы сможем спасти Джозефа Редпата!', 'Я говорила с твоим другом Карлином. Он очень хорошо о тебе отзывался. Он верит, что именно ты сможешь изменить судьбу его деревни.$B$BТы принес мне собранные тобой реликвии?', NULL, NULL, 'Сумка с мощами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5942, 'Спрятанные сокровища', 'Папа велел отдать тебе этот ключ. Он открывает сундук, который стоит во дворе за домом.$B$BА еще он просил поблагодарить тебя. Не знаю, правда, за что – может, он знает, что ты $gнашел:нашла: мою куклу?$B$BВот и ключ. Спасибо тебе, $N, ты $gхороший:хорошая:!', 'Откройте сундук Джозефа ключом Джозефа.', 'Ключ со скрипом поворачивается в замке...', 'Сундук стар и покрыт грязью.', NULL, NULL, 'Ключ Джозефа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5943, 'Караван Гизлтона', 'Вид-то у тебя надежный, $r. Подзаработать хочешь? Мы с Корком думали, что на этом караване срубим кучу денег – но оказалось, что новое предприятие сулит гораздо больше неприятностей и опасностей, чем мы полагали.$B$BТам, впереди, находится Поле Маннорок... Обычно демоны не обращают на нас внимания, но на этот раз что-то изрядно напугало кодо. Я хорошо заплачу тебе за охрану каравана. Если нам удастся миновать Поле Маннорок без проблем, ты сможешь получить награду у Смида: это наш деловой партнер в Лагере Заржавня.', 'Проводите караван Гизлтона через Поле Маннорок. О награде поговорите со Смидом: его можно найти в Лагере Заржавня.', 'Я не уверен, что стоит платить такие деньги за защиту каравана Гизлтона. В конце концов, Корк и Риггер зарабатывают не больше одного золотого в неделю. Главное, чтобы они мне платили за кодо, а остальное – не мое дело.', NULL, NULL, NULL, 'Проводите караван Гизлтона через Поле Маннорок.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5944, 'Во сне', 'Как же долго я был марионеткой верховного рыцаря. И что было проку сражаться с Алым орденом? Прошли десятки лет с мнимой смерти отца, но я жил лишь воспоминаниями о нем.$B$BМне снилось, что мы с отцом снова вместе. Он стоит рядом, с гордостью глядя, как меня принимают в орден. Мы бьемся с Плетью плечо к плечу, принося славу Альянсу и Лордерону.$B$BНе желаю больше жить во сне.$B$BОтведи меня к отцу.', 'Вывести Телана Фордринга из Дольного Очага.', 'Убийство моего сына не пройдет этим чудовищам даром. Пусть нас утешит мысль о возрождении Ордена.$B$BЯ встану во главе обновленного Ордена Серебряной Длани.$B$BВ знак своей признательности я могу отдать тебе лишь эти вещи, символы моего прошлого. Прими их, они служили мне верой и правдой долгие годы.$B$BДа встретимся мы в лучшие дни и вспомним давнее прошлое... трудные битвы... пробуждение от сна.', NULL, NULL, NULL, 'Искупление?', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5961, 'Защитник королевы банши', 'Приятно видеть, что в наши ряды вступают закаленные бойцы. С каждым днем нас становится все больше. Ты $gготов:готова: испытать собственную решимость, $C?$B$BПервый среди моих защитников – Натанос по прозвищу Гнилостень. Немногие могут превзойти его в преданности и доблести.$B$BОтыщи его в Восточных Чумных землях. Он живет в Поместье Маррисов и порой бродит по окружающим его пустошам, истребляя всякую мразь из воинств Плети и Альянса.', 'Поговорите с Натаносом Гнилостенем в Восточных Чумных землях. Он живет в Поместье Маррисов.', 'Темная Госпожа считает тебя достойным встретиться с ее защитником. Ты ведь прислан кормить моих псов, да? Иначе зачем ты меня тревожишь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (5981, 'Истребление великанов', 'Около четырех тысяч лет назад Тиранда Шелест Ветра спасла жизнь королевы ледопардов, вырвав ее из рук жестоких великанов. С тех самых пор ледопарды стали союзниками ночных эльфов. $B$BТе самые великаны, что когда-то представляли опасность для ледопардов, и поныне живут не очень далеко отсюда. Их называют кланом Ледяного Молота, и они обосновались в большой долине к югу отсюда.$B$BДокажите вашу лояльность – убейте этих великанов во имя королевы ледопардов, Ши-Ротам!', 'По просьбе Риверна Холодного Ветра убейте 4 великанов и 4 оберегателей ледяного молота.', 'Отлично, $N. Ваша решимость не осталась незамеченной.', NULL, NULL, NULL, 'Великан Ледяного Молота убито', 'Оберегатель Ледяного Молота убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6001, 'Тело и дух', 'Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха. Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, которой ты, как $gодин:одна: из друидов-медведей, должен овладеть.$B$BТы $Gзаслужил:заслужила; право пользоваться этой лунной пылью Кенария, $N... теперь покажи мне, что также $gзаслужил:заслужила: право обладать силами тела и духа, необходимыми друиду!', 'Посыпьте лунной пылью Кенария камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа.Затем поговорите с Матренгилом Медвежьей Лапой в Дарнасе.', 'Это твой первый большой шаг на пути к великим свершениям, $N. Я чую учение Духа Великого Медведя в тебе, и вижу, что ты перенял мощь Лунокогтя.$B$BБолее ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!', NULL, NULL, NULL, 'Поборите Лунокогтя, чтобы заслужить его силу духа и тела', 'Лунная пыль Кенария', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6002, 'Тело и дух', 'Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха. Лунные совухи – звери особые, в здешних краях они не живут. Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, который ты $gдолжен:должна: овладеть, как $gодин:одна: из друидов-медведей.$B$BТы $gзаслужил:заслужила: право пользоваться этой лунной пылью Кенария, $N... теперь покажи мне, что также $gзаслужил:заслужила: право обладать силой тела и духа, необходимыми друиду!', 'Посыпьте лунной пылью Кенария Камень Лунного совуха, что между Мулгором и Степями, чтобы вызвать Лунокогтя. Теперь вам надо побороть Лунокогтя, чтобы заслужить его силу духа и тела.Когда выполните это, поговорите с Тюраком Руническим Тотемом в Громовом Утесе.', 'Это твой первый большой шаг на пути к великим свершениям, $N. Я чую учение Духа Великого Медведя в тебе, и вижу, что ты перенял мощь Лунокогтя.$B$BБолее ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!', 'Пока ты не ответишь на вставший перед тобой вызов, ты не сумеешь полностью познать силу духа и тела. До тех пор я ничем не смогу тебе помочь.', NULL, NULL, 'Поборите Лунокогтя, чтобы заслужить его силу духа и тела', 'Лунная пыль Кенария', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6004, 'Неоконченное дело', 'У меня была разведывательная миссия – немного сократить число противников и оценить укрепления Дольного Очага. Некоторые сторонники Альянса считают, что этот город имеет не только историческое значение. Не мое дело решать, что важнее, но выполнять задание я не в силах, пока не отдохну.$B$BЕсли хочешь, я неплохо заплачу тебе за помощь. Начни на юге, возле лагеря Алого Ордена, у небольшого бастиона. Если ты окажешься достаточно $gсилен:сильна:, я попрошу тебя помочь мне выполнить основную часть задания.', 'Убейте 2 медиков, 2 охотников, 2 волхвов и 2 рыцарей из Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.', 'Молодец, $N. Как тебе удалось так быстро с ними разобраться? Спасибо. $B$BМне пока не встречался никто, кто одобрил бы Алый орден или его методы. Я верю в Свет, также как и все жители Штормграда, но эти фанатики наглядно доказали, что стремятся лишь убивать всех, кроме своих сторонников... даже ни в чем не повинных людей.', 'Как успехи? Враг оказался сильнее, чем ты думал? Надеюсь, что нет. Мое следующее задание потребует гораздо больше сил, чем это.', NULL, NULL, 'Медик Алого ордена убито', 'Охотник из Алого ордена убито', 'Маг Алого ордена убито', 'Рыцарь Алого ордена убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6021, 'Зельдарр Изгой', 'Кто бы мог подумать, после всех наших заключений в Чумных землях нам не хватало только воров! И не просто воров, а троллей!$B$BИ не просто воров-троллей, а мертвых воров-троллей!$B$BИх главарь – огромный мертвый тролль по имени Зельдарр Изгой. Они являются по ночам, крадут тела из ямы и тащат их в свое мерзкое логово. Оно зовется Крипта, это к западу отсюда.$B$BОтправляйся туда, $N, и разберись с Зельдарром. Я сыт по горло его проделками!', 'Принесите голову Зельдарра Управляющему Алену в Часовню Последней Надежды.', 'Поделом ему! Надеюсь, и остальным их его шайки тоже досталось!', 'Тебе удалось разыскать логово Зельдарра, $N? Ты нашел на него управу?', NULL, NULL, 'Голова Зельдарра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6022, 'Преднамеренное убийство', 'Будь $gготов:готова: на умышленное убийство, если хочешь со мной работать.$B$BДля начала покорми моих псов.$B$BВозьми эту ступку и пестик и отправляйся в Перекресток Корина. Там у тебя будет обширный выбор тварей Плети – убей тех, какие больше приглянутся. Из их свежих туш добудь живую гниль, растолки в ступке и дай отстояться, чтобы она сгустилась. Принесешь сгущенную гниль мне.$B$BИ слушай меня, недотепа, живая гниль – продукт скоропортящийся! Поэтому работать придется быстро.', 'Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее, чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль.', 'Прискорбно, прискорбно... Я-то надеялся скормить моим псам тебя...$B$B*Натанос вздыхает*$B$BЛадно, по-крайней мере им есть, что погрызть.', 'Что нюни распустил? Если эта работенка не по тебе, отправляйся обратно к Темной Госпоже и сообщи ей, как дурно я с тобой обошелся.$B$BПроваливай!', NULL, NULL, 'Сгущенная гниль', 'Ступка и пестик', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6023, 'Неоконченное дело', 'Подлинная суть моей миссии состояла в том, чтобы подорвать мощь внешних отрядов Алого ордена, а потом проникнуть внутрь Дольного Очага и оценить их основные силы. Я пока не в форме, но, может быть, могу снова попросить о помощи? Судя по собранным сведениям, за пределами города костяк сил ордена составляют двое: охотник Радли и кавалер Алого ордена Дарген. Убей их, и дело стронется с мертвой точки. Они должны быть неподалеку от прохода, рядом с городом.', 'Убейте охотника Радли и кавалериста Даргена и вернитесь к Кристе Чернотени в Западные Чумные земли.', 'Спасибо, $N. Я и не рассчитывала на такую помощь. Кажется, самый воздух этих земель лишает меня воли. Я очень устала, и чем дольше здесь нахожусь, тем мне хуже.$B$BНе представляю, как я проберусь в Дольный Очаг, чтобы выяснить размер армии Алого ордена.$B$BНо это другой разговор. Погоди, возьми это... в уплату. Спасибо еще раз.', 'Тебе уже удалось их найти, $N? Если мы избавимся от этих двоих, я смогу пробраться в Дольный Очаг, посмотреть, что к чему. Без твоей помощи мне не обойтись. Пожалуйста, найди мне Рэдли и Даргена.', NULL, NULL, 'Охотник Радли убито', 'Кавалер Алого ордена Дарген убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6024, 'Мольба Хамейи', 'Убей меня. Пока не поздно!$B$BМеня зовут Хамейя. Мы с собратьями путешествовали через Зул\'Машар и, видимо, съели что-то не то. Мы заражены!$B$BЯ слышу, как лич нашептывает мне, что я должен отправиться в Зул\'Машар и постараться распространить заразу. Я не могу противиться его словам, поэтому написал это послание прежде, чем разум окончательно оставит меня.$B$BЯ закопал сундук с сокровищами рядом повозкой, оставленной за этим склепом, но его можно открыть только моим ключом. Ключ у меня.$B$BЧтобы добыть сокровище, убей меня. Пока не поздно!', 'Убейте секретного агента Хамейю. С помощью ключа извлеките сокровище из кучи грязи за Криптой.', 'Сундук Хамейи открыт!', 'Сундук надежно заперт.', NULL, NULL, 'Ключ Хамейи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6025, 'Неоконченное дело', 'Что? Правда? Ты $gготов:готова: меня выслушать? Но ты и так очень много для меня $gсделал:сделала:, $N. Я не могу просить тебя отправиться в Дольный Очаг.$B$BТы серьезно? Дольный Очаг гораздо опаснее прохода... Я не смогу защитить тебя или даже рассказать, что тебя может ждать там.$B$BЕсли ты в самом деле хочешь мне помочь, то проникни в город и поднимись там на на какое-нибудь высокое место, чтобы осмотреть его с высоты. Оцени количество войск и доложи мне. Но будь $gосторожен:осторожна:...', 'Проберитесь в Дольный Очаг и найдите возвышенность, с которой открывается вид на весь город. Оцените силы Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.', 'Молодец, $N! Спасибо!$B$BЯ вернусь к Эллингу... точнее, в Штормград как только смогу. Возьми эту скро$Nю сумму, должна же я тебя отблагодарить. Твой народ может тобой гордиться, $N. Спасибо и удачи.', 'Это опасное задание, $N. Я завидую твоей храбрости.', NULL, NULL, 'Исследовать локацию', 'Осмотреть Дольный Очаг с высоты', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6026, 'Работу пополам', 'Серебряный Рассвет поручил старине Дымку кой-какую работенку. А я что, я токмо рад – денежка-то никогда не лишняя!$B$BОднако силы мои уже не те, и я бы, пожалуй, воспользовался твоей помощью, если ты тоже не прочь подзаработать. Я пойду в Проклятый лес и отмечу знаком строения, которые предстоит взорвать, а ты пока добудешь взрывчатки. Договорились? Жди меня на этом самом месте, как соберешь все необходимое. Ну, что скажешь?', 'Принесите 2 ториевых слитка, 1 золотой жезл, 8 высоковзрывчатых бомб и 8 нестабильных детонаторов Смоки Ля Рю.Для этого вам придется найти кузнеца и инженера.', 'Могу заплатить половину сейчас и половину по выполнению работы.', 'Верь старине Дымку, $R, дело стоящее. Серебряный Рассвет за копейку не удавится.', NULL, NULL, 'Ториевый слиток', 'Золотой жезл', 'Взрывоопасная бомба', 'Нестабильное пусковое устройство');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6027, 'Книга Древних', 'Послушай меня, $N: я вручаю тебе Самоцвет Змеи. Его нужно поместить на руку Статуи Змеи, что на острове Раназьяр: это небольшой островок к северо-западу отсюда. Когда сделаешь это, явится тот, кто хранит Книгу Древних. В книге можно найти вековые тайны нагов. Принеси мне эту книгу: вместе мы сумеем узнать многое о наших чешуйчатых врагах!', 'Отыщите Книгу Древних и принесите ее Азору Альдаморту в башню Этель-Ретор.', 'Утраченная Книга Древних! Я прослежу за тем, чтобы она была передана высокому совету. Сегодня ты свершил великое деяние; прими же благодарность за этот подвиг!', 'Ах, $N, как я рад тебя видеть! Ну как, есть при тебе Книга Древних?', NULL, NULL, 'Книга Древних', 'Самоцвет Змеи (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6028, 'Донесение из Круговзора', 'Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета по управлению Круговзором. Я должен доложить обстановку офицеру Чистосердой в Лагерь Промозглого Ветра, расположенный на южной окраине Западных Чумных земель.$B$BЕсли мне это удастся, это будет прекрасный повод представить тебя моей начальнице и, возможно, устроить тебе персональное задание', 'Доставьте донесение из Круговзора офицеру Чистосердой из ордена Серебряного Рассвета в Лагерь Промозглого Ветра в Западных Чумных землях.', 'Грегор крайне находчив. Он некоторое время имел дело с Картелем Хитрая Шестеренка, и стал экспертом по \"искусству\" переговоров с гоблинами. Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии. Если, так или иначе, она обеспечивает им повторные заказы...$B$BВо всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу. Примите это вместе с нашей благодарностью.', 'Приветствую, $C. От имени Серебряного Рассвета, я предлагаю вам безопасность и убежище, пока вы находитесь на территории Лагеря Промозглого Ветра. Так же я могла бы подыскать для вас подходящее дело...', NULL, NULL, 'Донесение из Круговзора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6029, 'Донесение из Круговзора', 'Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета в администрации Круговзора. Я должен доложить обстановку офицеру Гарушу в Бастион, расположенный на восточных окраинах Западных Чумных земель, к востоку от Тирисфальских лесов.$B$BЕсли я могу тебя об этом просить... это будет прекрасный повод представить тебя моему начальнику. И, возможно, он найдет тебе дело!', 'Доставьте донесение из Круговзора офицеру Гарушу из ордена Серебряного Рассвета в Бастион в Западных Чумных землях.', 'Грегор крайне находчив. Он некоторое время имел дело с Картелем Хитрая Шестеренка, и стал экспертом по \"искусству\" переговоров с гоблинами. Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии. Если, так или иначе, она обеспечивает им повторные заказы...$B$BВо всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу. Примите это вместе с нашей благодарностью.', 'Приветствую, $C. От имени Серебряного Рассвета, я предлагаю вам безопасность и убежище, пока вы находитесь на территории Бастиона. Я мог бы также предложить хорошую драку за стоящие того цели!', NULL, NULL, 'Донесение из Круговзора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6030, 'Герцог Николас Зверенхофф', 'Отшельник-медиум по имени Умбранс, обитающий в этих краях, обеспечил Серебряный Рассвет настоящим шедевром литературы... Это самое большое собрание слухов и сплетен, которое только было когда-либо издано.$B$BОдин из наиболее уважаемых лидеров Рассвета, герцог Николас Зверенхофф, является блестящим лингвистом. Ты не $gмог:могла: бы отнести ему эту книгу – не бесплатно, разумеется! Сейчас его можно найти в Часовне Последней Надежды, в восточной части Восточных Чумных земель.', 'Доставьте книгу \"Исследования речи духов\" Герцогу Николасу Зверенхоффу в Часовню Последней Надежды в Восточных Чумных землях.', 'Это... Вы принесли мне весьма особенную книгу. Я хотел бы сказать Вам, что \"особенная\" в этом случае означает \"уникальная и весьма познавательная\", но так ли это мы еще проверим.$B$BOoooooo? Кто это выдумал? $B$BХорошо, я узнал об этом Умбрансе, о котором говорил Грегор, и это ваша заслуга. Я приложу все усилия, чтобы расшифровать эту книгу. Что касается Вас... Серебряный Рассвет вам бесконечно благодарен. Возможно нам еще потребуются ваши услуги, пока вы здесь.', 'Да пребудет с вами Свет, в эти темные времена, $C. Что привело вас сюда, в этот последний оплот надежды среди тьмы и отчаяния?', NULL, NULL, 'Исследования речи духов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6031, 'Руническая ткань', 'Мы, Древобрюхи, самодостаточны. Мы не любим чужаков. Для нас такая жизнь хороша, но вот для торговли – нет.$B$BНедавно к нам в крепость Древобрюхов забрела редкая гостья – одна ночная эльфийка. У нее был плащ из рунической ткани. Руническая ткань у нас вещь редкая, но плащ был такой красивый, что мои сородичи пожелали, чтобы я нашил им побольше одежды из рунической ткани.$B$BТы принесешь мне рунической ткани? А за это я кое-что дам тебе.', 'Принесите 30 отрезов рунической ткани Мелиошу в крепость Древобрюхов.', 'А, принесла. Какая же красивая ткань!$B$BСпасибо тебе, $N. Ты настоящий друг. Пожалуйста, прими в благодарность.', 'Ты принесла руническую ткань? Мой народ сгорает от нетерпения получить одежду из рунической ткани!', NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6032, 'Священная ткань', 'Хотя Древобрюхам по нраву ощущение от рунической ткани, она для нас не священна. А вот луноткань – священна.$B$BПринеси мне немного этой священной ткани, и я научу тебя некоторым портняжным секретам.', 'Принесите 2 отреза луноткани Мелиошу в крепость Древобрюхов.', 'Очень хорошо! Эта ткань пойдет на одеяния, священные для нашего народа. Спасибо, $N. Теперь я буду обучать тебя.', 'Ты принесла луноткань, $N?', NULL, NULL, 'Луноткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6041, 'Дымок над водою', 'Пока ты $gзанимался:занималась: заготовкой припасов, мои люди отметили некоторые сооружения Плети, которые должны быть уничтожены.$B$BПлан действий таков: я дам тебе 10 брусков моего особого состава, ты отправишься в Проклятый лес и оставишь их в сооружениях Плети, помеченных знаком.$B$B*Дымок щелкает пальцами*$B$BБабах! Все очень просто!', 'Отправляйтесь в Проклятый лес, к северо-западу от Часовни Последней Надежды. Уничтожьте 8 сооружений Плети, отмеченных знаком взрыва, поместив особый состав Дымка внутрь сооружения. Дымок отметил зиккураты и бойни.Разместив бомбу внутри сооружения, немедленно выбирайтесь наружу и любуйтесь делом рук своих с безопасного расстояния. Ах да, вот еще что, особый состав Дымка – вещество весьма нестабильное.', 'Загар тебе очень идет. Я всегда говорил, игра с огнем весьма полезна для цвета лица!$B$B*Дымок хохочет во все горло*$B$BНу да ладно, вот обещанная награда. И кой-чего сверх обещанного, чтобы боль от ожогов не казалась столь жестокой!', NULL, NULL, NULL, 'Уничтожено сооружений Плети', 'Особый ингредиент Дымка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6042, 'Мелочи нежизни', 'С фермы и шагу нельзя ступить, чтобы не напороться на одну из этих проклятых летучих мышей! Я бы, знаешь ли, предпочел заниматься истреблением Плети, не отвлекаясь на всякую мелкую шушеру. Мое время слишком дорого, чтобы тратить его на охоту за мышами. А вот твое – нет.$B$BЧто ты там бормочешь? Обучение? Вот тебе обучение – пойди поучись ловле мышей! И не смей показываться мне на глаза, пока не перебьешь несколько десятков этих мерзких тварей.', 'Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостеню.', 'Вот можешь же, если захочешь! Главное, правильно подобрать аргументы.', 'Хватит ныть! Я мог бы заставить тебя собирать мышиный помет, но я сегодня добрый!$B$B*Натаноса явно осенила какая-то идея*$B$BЭй! А ну погоди! Куда побежал!', NULL, NULL, 'Пагубный нетопырь убито', 'Чудовищный чумной нетопырь убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6061, 'Приручение зверя', 'Для нас, тауренов, важно следовать традициям предков, сражаясь с могучими зверями. Одолевая их, мы вбираем в себя их дух, делаясь все ближе Матери-Земле.$B$BПриручив же зверя и сделав его своим помощником, мы делаем еще один шаг навстречу природе. В конце концов ты сможешь выбрать зверя себе по вкусу. Но сначала всему приходится учиться, и этому тоже. Для начала возьми этот хлыст приручения; ступай, приручи равнинного долгонога.', 'Приручите взрослого равнинного долгонога при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.', '', NULL, NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите взрослого равнинного долгонога.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6062, 'Приручение зверя', 'Умение подчинять природу своей воле – великое искусство. Ты $gохотник:охотница:, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу.$B$BОбрести власть над животным – дело не простое, тут требуется решимость.$B$BДля начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря. Они водятся поблизости от Колючего Холма. Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне.', 'Приручите лютого пятнистого вепря с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме.', 'Молодец, $N! Думаю, тебе уже можно поручить задачу посложнее...', 'Удачи тебе, юный охотник!', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите лютого пятнистого вепря.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6063, 'Приручение зверя', 'Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям. Ее следует почитать как нечто, без чего само твое существование было бы невозможным.$B$B$N, ты $gдолжен:должна: доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника.$B$BПервым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного тенетника. Приручи его и поупражняйся в своем охотничьем искусстве.', 'С помощью хлыста приручения приручите чащобного тенетника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.', 'Отлично, $N! Ты и правда быстро обучаешься.', 'Ты быстро обучаешься, $N. Однажды ты станешь великим охотником.', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите чащобного тенетника.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6064, 'Приручение зверя', 'Привет, $gпарень:подруга:! Стало быть, хочешь узнать, как завести себе питомца?$B$BЧто же, начнем. Когда доходит до охоты, нет ничего важнее снаряжения, но о моем новом шрапнельном самостреле мы поболтаем в другой раз. А пока займемся тем, что, так интересует тебя в данный момент – питомцем!$B$BТебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу. Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его.', 'Приручите большого скального вепря с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.', 'Знаю-знаю, тебе невтерпеж узнать, кого надо будет приручить следующим, да?', 'Тебе сначала надо попробовать приручить разных зверей – тогда ты сможешь понять, кто тебе больше по душе.', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите большого скального вепря.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6065, 'Путь охотника', 'Привет тебе, $gюный охотник:юная охотница:. Ты кажешься мне достаточно $gопытным:опытной:, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.', 'Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта, что в Мулгоре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
