INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6076, 'Путь охотника', 'Привет тебе, $gюный охотник:юная охотница:. Ты кажешься мне достаточно $gопытным:опытной:, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.', 'Поговорите с Грифом Диким Сердцем в Караносе, что в Дун Мороге.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6081, 'Обучение зверя', 'Теперь ты умеешь приручать зверей, но тебе еще осталось узнать, как их обучать.$B$BСтупай в Оргриммар. Там тебе нужно будет поговорить с одним из самых прославленных наших охотников, Ормаком Лютострелом. Он покажет тебе, как обучать своего нового питомца. Ты найдешь Ормака в Аллее Чести.$B$BУдачи, $N!', 'Поговорите с Ормаком Лютострелом в Оргриммаре.', 'А, молодой охотник! Да, я поделюсь с тобой навыками и знаниями, необходимыми для того, чтобы обучать и дрессировать питомца. Ты сможешь не только обучать своего питомца новым способностям, но также научишься кормить его и даже оживлять, если он погибнет в бою.$B$BА теперь ступай. Мы поговорим позднее.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6082, 'Приручение зверя', 'Последнее животное, которое тебе придется приручить, – это панцирный скорпид. Тебе придется частенько с ними сражаться. Но ты, будучи $Gохотником:охотницей;, $gдолжен:должна: уметь повелевать и такими существами.$B$BКогда ты вернешься, я обучу тебя всему, что потребуется, чтобы приручить животное по твоему выбору. Выбранный тобой зверь будет набираться опыта и становиться сильнее. А еще я покажу тебе, как призывать его и отпускать на волю, когда в нем не будет надобности.', 'Приручите панцирного скорпида с помощью хлыста приручения. Потренируйтесь, потом вернитесь к Тотару в Колючем Холме.', 'Теперь, Эч, ты знаешь все, чему я мог тебя обучить. Пора тебе воспользоваться полученными знаниями и выбрать себе собственного питомца.$B$BВот, Эч, я даю тебе способность приручать зверя, а также призывать и отсылать его по собственной воле. Можешь гордиться своим новым умением, ты заслужил эти знания!', 'Ну что, удалось тебе укротить панцирного скорпида?', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите панцирного скорпида', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6083, 'Приручение зверя', 'Разумеется, $N, питомец дает тебе большое преимущество в бою. Подчиняя себе живое существо, ты добавляешь его силу к своей. Он становится как бы продолжением тебя.$B$BСледующее задание потребует от тебя обратиться от земли к морю. Приливный краб, которого тебе нужно будет приручить, обитает в прибрежных водах, близ деревни Сен\'джин и островов Эха. Воспользуйся хлыстом приручения, чтобы усмирить зверя, а потом потренируй свои навыки.', 'Приручите приливного краба с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме.', 'Ты быстро учишься, $N! Молодец.', 'Тебе нужно тренироваться, чтобы набраться опыта в укрощении питомцев. Удалось ли тебе приручить приливного краба?', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите приливного краба', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6084, 'Приручение зверя', 'Эти скальные вепри такие здоровенные – может, тебе хочется кого поизящнее? Ладушки, у меня есть кое-кто на примете. К югу и востоку отсюда ты найдешь больших белых кошек, называемых снежными леопардами. Они чем-то напоминают элегантную винтовку – такие же красивые и такие же смертоносные. Они гораздо проворнее и быстрее укрощенного тобой вепря.$B$BНа, держи этот хлыст приручения. Посмотрим, придется ли тебе по душе снежный леопард.', 'Приручите снежного леопарда с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.', 'Когда я увижу, что ты достаточно подготовлен, я научу тебя приручать любого понравившегося тебя зверя.', 'Ну, как тебе снежный леопард, $N?', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите снежного леопарда', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6085, 'Приручение зверя', 'Возможно, тебе понравится животное, обладающее чем-то большим, чем просто грубая сила. Медведи-ледолапы – замечательные спутники для охотников-новичков, вроде тебя. Их можно найти к востоку от Караноса. Вот тебе хлыст приручения, попытайся приручить это животное и посмотри, как он тебе придется!$B$BКогда ты вернешься, я научу тебя, как приручать животных. Твой питомец будет вместе с тобой разделять опасности и получать опыт. Я также научу тебя призывать и отпускать животное по своему желанию.', 'Приручите медведя-ледолапа с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.', 'Отлично, $N. Теперь научу тебя приручать зверя, а также призывать и отпускать его по желанию.$B$BНайди себе славного верного питомца – и доброй охоты!', 'Ну, удалось приручить медведя-ледолапа?', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите медведя-ледолапа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6086, 'Обучение зверя', '$N, ты умеешь приручать зверей, но ведь надо еще научиться тренировать своего питомца.$B$BИди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специлистов в обучении зверей – Белией Громовой Гранит. Она покажет тебе, как обучать питомца. Так что отправляйся в путь, $gпарень:подруга:!$B$BБелия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка. Удачи, $N.', 'Поговорите в с Белией Громовой Гранит в Стальгорне.', 'Новенький? Вижу, быть тебе великим охотником.$B$BДа, я могу поделиться с тобой знаниями, необходимыми для обучения и управления питомцем. Ты сможешь не только обучить своего питомца новым способностям, но и научишься его кормить и даже воскрешать, если он погибнет в бою.$B$BПомни, лучший способ подружиться с питомцем – это обращаться с ним уважительно и хорошо за ним ухаживать. Тогда твой питомец будет безгранично предан тебе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6087, 'Приручение зверя', 'Твой дух полон огня, охотник, и ты с радостью встречаешь новые испытания.$B$BСледующее задание – приручить волка, известного как охотник прерий. Он быстр и бесстрашен, и чтобы сделать его своим спутником, тебе придется воспитать в себе эти качества.$B$BВо время боя ты поймешь, как вы будете сражаться бок о бок. Ведь вы с питомцем должны действовать очень слаженно, как единый организм.$B$BВот хлыст приручения, $N. Подчини себе охотника прерий, потренируйся.', 'Приручите охотника прерий при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.', 'Да... Мать-Земля полагает, что ты готов к следующему уроку.', 'Удалось найти охотника прерий?', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите охотника прерий.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6088, 'Приручение зверя', 'Последним твоим заданием станет приручение жителя неба. Перепелятник – непростой противник, но зато отличный союзник – атакует он внезапно и пугает врагов.$B$BПо воле Матери-Земли, по возвращении с победой, я наделю тебя искусством приручать любого зверя и делать его своим спутником; твоему питомцу придется встретиться с теми же испытаниями, что и тебе, и вместе с тобой набираться опыта. Я покажу тебе, как подзывать и отсылать его по собственной воле.', 'Приручите перепелятника при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.', '', NULL, NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите перепелятника.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6089, 'Обучение зверя', 'Теперь ты знаешь, как приручать питомца, но тебе надо научиться еще и обучать его.$B$BОтправляйся в Громовой Утес. Там тебе нужно будет поговорить с одним из наших самых уважаемых охотников, Хольтом Громовым Рогом. Если он сочтет тебя достойным знаний, то объяснит тебе, как обучать твоего нового питомца. $B$BХольт одолел многих могущественных и страшных зверей Азерота и сам повелевает сильными существами. Его связь с Матерью-Землей сильна, и он многому может научить. Удачи, $N.', 'Поговорите с Хольтом Громовым Рогом в Громовом Утесе.', 'А, юный охотник. Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца. Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падет в бою.$B$BСтупай, Мать-Земля еще сведет наши пути. Поговорим позже.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6101, 'Приручение зверя', 'Природа изменчива, но на нее вполне можно положиться, $N. Она предсказуема в том, что никогда не остается одной и той же, она всегда меняется. $B$BПоручения, которые я тебе дам, помогут тебе увидеть и оценить различных существ, которые впоследствии смогут стать твоими спутниками.$B$BВозьми этот хлыст приручения и приручи ночного саблезуба-охотника, которого ты найдешь к югу отсюда. Поупражняйся в своем охотничьем искусстве. Таким образом ты начнешь понимать сходства и различия творений природы.', 'С помощью хлыста приручения приручите ночного саблезуба-охотника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.', 'Вижу в тебе обязательность и понимание всего, чему я научил тебя, $N.', 'Постоянно поддерживать равновесие с природой – таков путь жизни каждого ночного эльфа.', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите ночного саблезуба-охотника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6102, 'Приручение зверя', 'Тебе удалось приручить двух детей земли, и теперь тебе предстоит подружиться с обитателем неба. При помощи этого хлыста приручи совиного крикуна, которого найдешь к западу отсюда. Испытай свое искусство, взяв в спутники эту могучую сову.$B$BКогда вернешься, я наделю тебя знаниями, которые понадобятся тебе для приручения любого животного, которого ты выберешь себе в спутники. Твой спутник встретит лицом к лицу те же опасности, что и ты, и вместе с тобой будет набираться опыта. Я также научу тебя, как призывать и отпускать по желанию твоего питомца.', 'С помощью хлыста приручите совиного крикуна. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.', 'Теперь ты знаешь все, чему я мог тебя обучить, $N. Могу ли дать тебе еще один совет? Хорошенько подумай прежде, чем выбрать первого питомца. Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса? Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе.$B$BЧто же, $N. Ныне я дам тебе умение приручать животное, а так же призывать и отпускать его, когда тебе будет нужно. Гордись своими новыми умениями – ты их честно заслужил.', 'Я горжусь твоими достижениями, $N. Справился ли ты с той задачей, что я тебе поручил?', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите совиного крикуна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6103, 'Обучение зверя', 'Теперь ты знаешь, как приручать питомца, но тебе надо научиться еще и обучать его.$B$BОтправляйся в Дарнас. Там тебе нужно будет поговорить с одной из наших самых уважаемых охотниц, Иокастой. Она объяснит тебе, как обучать твоего нового питомца, так что поторопись.$B$BХотя Иокаста и сурова, ей всегда приятно наблюдать за развитием способностей очередного охотника. Держись с ней почтительно, и она воздаст добром. Удачи, $N.', 'Поговорите с Иокастой в анклаве Кенария в Дарнасе.', 'Новоиспеченный охотник?. Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем. Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке.$B$BЗапомни, $N: всегда уважай равновесие и почитай природу. Теперь ступай. Попозже еще поговорим.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6121, 'Новый урок', 'Теперь, $N, ты $Gготов:готова; узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты $gусвоил:усвоила: этот важный урок, посему тебе придется испытать на себе силу действия яда в полной мере. Отправляйся на Лунную поляну и поговори с Дендритом Блеском Звезд – он ждет твоего прибытия, чтобы начать обучение.', 'Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.', 'Добро пожаловать, юный друид, рад видеть, что ты горишь желанием узнать о нейтрализации ядов.$B$BЕсли в прошлом большинство друидов проходили заранее установленные испытания, то для твоей работы такого не понадобится. В Аубердине вспышка отравления животных, и в тамошней деревне справиться с этим не могут. Поэтому представитель деревни просил помощи у Лунной поляны, и мы направляем тебя к ним. Это не учеба, а серьезное задание, имей в виду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6122, 'Основной источник', 'Водопад Скалистый на Темном Берегу – основной источник питьевой воды для всего региона, но теперь я подозреваю, что именно оттуда распространяется отрава, поражающей местную фауну – особенно оленей. Возьми эту пробирку, чтобы отобрать немного воды из устья пещеры. Осторожнее – в пещере у водопада ныне поселилась опасная нага.$B$BКак только наберешь воды, доставь ее Аландариан Песне Ночи в Аубердин. Именно она просила нашей помощи, и ты поможешь ей разобраться с этой заразой.', 'Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый. Доставьте наполненную колбу Аландариан Песне Ночи в Аубердин, на Темный Берег.', 'Клянусь Элуной, какая омерзительная вода! Немудрено, что оленей поразил недуг.$B$BЧто-то заражает воду, и она в свою очередь поражает все грунтовые воды Темного Берега. Больных оленей видели повсюду, не только у реки. Даже если эта вода и есть основной источник расползающейся болезни, тут замешано что-то еще.$B$BХочешь – верь, хочешь – не верь, но эта вода поможет нам найти исцеление. А пока я буду исследовать жидкость, мне понадобится кое-что еще, чтобы составить лекарство...', 'Это тебя прислал Круг Кенария Лунной поляны, да? Замечательно! Нам так не хватает рук для работы с бедными оленями, и мы рады любой помощи. $B$BТы принес пробу воды, о которой говорил мне Дендрит Блеск Звезд? Он сказал, что ты принесешь ее, чтобы мы могли тотчас же приступить к трудам по исцелению...', NULL, NULL, 'Колба, наполненная водой водопада Скалистый', 'Пустая колба для воды из Скалистого водопада', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6123, 'Создание лекарства', 'Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится земляной корень. Травники знают, где его искать, так что, если нам не повезло и вы не $gтравник:травница:, придется найти кого-то, кто сможет помочь.$B$BДля усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно. В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будьте осторожны.', 'Принесите 5 земляных корней и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.', 'Отлично, $N, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось.$B$BИзготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия. Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот!$B$BА теперь позвольте мне приступить к работе!', 'Вы собрали реагенты, необходимые для изготовления мази? Сами по себе олени не поправятся, так что нам лучше поспешить им на помощь!', NULL, NULL, 'Земляной корень', 'Лунный гриб', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6124, 'Исцеление больных', 'Мази, изготовленной из реактивов, которые ты $gпринес:принесла: мне, $N, хватит на десять доз. Пока я работаю здесь, в деревне, пытаясь изготовить побольше этой мази, я хотел бы, чтобы ты $gпомог:помогла: нам начать исцеление. По всем Темным берегам встречаются больные олени. Используй мазь для исцеления их недуга.$B$BЯ уверен, что Дендрит Звездная Вспышка с Лунной Поляны захочет поговорить с тобой, когда ты закончишь. Пожалуйста, передай благодарность жителей Аубердина Кругу Кенария... и позволь мне поблагодарить тебя лично за помощь!', 'Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темных берегах, – это должно их исцелить. По слухам, ареал обитания больных оленей – южнее реки Скалистой и севернее Аубердина, а далее – по всей области, вплоть до южных границ Темных берегов, где начинается Ясеневый лес.', 'Вы хорошо сделали, что позаботились о больных оленях Темных берегов; это невольные жертвы порчи и осквернения, расползающихся по всему краю. В Дарнассе есть те, кто признает наличие угрозы... и те, кто упорно игнорирует ее все усиливающиеся признаки. Я надеюсь, что вы, $N, – один из тех, кто не собирается надевать шоры и будет смотреть в лицо фактам.$B$BКак бы там ни было, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы.', NULL, NULL, NULL, 'Исцелено больных оленей', 'Мазь исцеления животных', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6125, 'Власть над ядом', 'Ты $Gпознал:познала;, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами.$B$BТебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнас, $N. Теперь, когда его $gученик усвоил данный ему:ученица усвоила данный ей: урок, он несомненно научит тебя новому могучему заклинанию.$B$BДо свидания, юный друид. Мы еще встретимся.', 'Вернитесь к Матренгилу Медвежьей Лапе в анклав Кенария в Дарнасе. ', 'С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинул нас, и, должен признаться, был изумлен, узнав о ситуации в Аубердине. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие.$B$BТы благородно поступил в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй ее во благо, $N... во благо.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6126, 'Новый урок', 'Теперь, $N, ты $Gготов:готова; узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты $gусвоил:усвоила: этот важный урок, посему тебе придется испытать на себе силу действия яда в полной мере. Отправляйся на Лунную поляну и поговори с Дендритом Блеском Звезд – он ждет твоего прибытия, чтобы начать обучение.', 'Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.', 'Привет тебе, мой юный друид, я рад, что ты жаждешь узнать, как изгонять из тела яд.$B$BВ старину друиды проходили заранее установленные испытания, но тебе этого делать не придется. В Перекрестке и Степях вспышка отравлений животных, и справиться с ней там никак не могут. Оттуда запросили помощи Лунной поляны, так что мы посылаем тебя. Это не учеба, а серьезное задание. Помни это.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6127, 'Основной источник', 'Вершина Багрового Тумана, что к северо-западу от Перекрестка – самый вероятный источник распространения этой отравы. На его вершине находятся озера воды, влияющие на перемены погоды. Подозреваю, что вода сейчас заражена демонопоклонниками из клана Пылающего Клинка.$B$BВозьми этот пробоотборник и набери воды из озера у самой вершины. Наполнив, доставь его Тонге Руническому Тотему в Перекресток. Именно он и просил нашей помощи, и ты будешь работать вместе с ним над искоренением этой заразы.', 'Используйте пустой пробоотборник Вершины Багрового Тумана для отбора воды из озера на вершине.Доставьте наполненный пробоотборник Вершины Багрового Тумана Тонге Руническому Тотему в Перекресток, что в Степях.', 'Клянусь предками, какая омерзительная вода! Немудрено, что газелей поразил недуг.$B$BЧто-то заражает воду, и она начинает разрушать экосистему северных Степей. Больных газелей видели повсюду к северу от тутошней дороги с востока на запад. Даже если эта вода и есть основной источник расползающейся болезни, тут замешано что-то еще.$B$BЭта вода, верь – не верь, поможет нам найти исцеление. А пока я буду исследовать эту воду, мне понадобится кое-что еще, чтобы составить лекарство...', 'Это тебя прислал Круг Кенария Лунной поляны, да? Большая удача для нас! Мы выбиваемся из сил, пытаясь восстановить равновесие среди больных газелей, что блуждают в северных Степях. Мы рады любой помощи. $B$BТы принес пробу воды, о которой говорил мне Дендрит Блеск Звезд? Он сказал, что ты принесешь воды, дабы мы могли приступить к трудам по исцелению тотчас же...', NULL, NULL, 'Наполненный пробоотборник Вершины Багрового Тумана', 'Пустой пробоотборник Вершины Багрового Тумана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6128, 'Сбор лекарственных ингредиентов', 'Основой целебной мази для газелей послужит вода. Для придания ей целебных свойств мне понадобится земляной корень. Травники знают, где его отыскать, так что если нам не повезло, и ты – не $gтравник:травница:, придется попросить кого-то о помощи. $B$BДля силы воздействия мне нужны рога кодо – осколки и куски не подойдут. Кодо живут в северной части Степей. Убей несколько зверюг, заодно и природное равновесие восстановится. Отпили у них рога и принеси мне.', 'Принесите 5 земляных корней и 5 рогов кодо Тонге Руническому Тотему в Перекресток, и он сделает целебную мазь.', 'Отлично, $N, ты принес так много составляющих, что должно хватить на несколько больших доз мази – по крайней мере, положим начало исцелению.$B$BИзготовление средств против ядов иногда бывает весьма сложным, ведь для нейтрализации каждого из них требуется отдельный антидот. Здорово было бы научиться в любой момент лечить отравления, не беспокоясь о конкретных составляющих противоядия!$B$BЛадно, пора браться за работу!', 'Ты собрал реагенты, необходимые для изготовления мази? Сами по себе газели не поправятся, так что нам лучше поспешить к ним на помощь!', NULL, NULL, 'Земляной корень', 'Рог кодо', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6129, 'Исцеление больных', 'Мне удалось сделать десять доз целебной мази. Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотел бы, чтобы ты $gпомог:помогла: нам лечить бедных животных. По всей северной части Степей бродят больные газели. Исцели их недуг при помощи этой мази.$B$BЯ уверен, что Дендрит Блеск Звезд на Лунной поляне захочет поговорить с тобой, когда ты закончишь. Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!', 'Нанесите мазь исцеления животных на 10 больных газелей, обитающих в северной части Степей, – это должно их вылечить. По слухам, больные газели живут севернее дороги, проходящей через Перекресток с востока на запад.', 'Вы хорошо сделали, что позаботились о больных газелях Степей; это невольные жертвы порчи и осквернения, расползающихся по всему краю. Вы, таурены, лучше прочих постигаете мудрость Кенария. И Вы, Укряшдру, как и мудрейшие из Громового Утеса, постигаете, что необходимость достичь равновесия превыше искусственных расовых границ. $B$BТак или иначе, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы.', NULL, NULL, NULL, 'Исцелено больных газелей', 'Мазь исцеления животных', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6130, 'Власть над ядом', 'Ты $Gпознал:познала;, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами.$B$BТебе следует вернуться к Тюраку Руническому Тотему в Громовой Утес, $N. Теперь, когда его $gученик усвоил данный ему:ученица усвоила данный ей: урок, он несомненно научит тебя новому могучему заклинанию.$B$BДо свидания, юный друид. Мы еще встретимся.', 'Вернитесь к Тюраку Руническому Тотему на Вершину Старейшин в Громовой Утес. ', 'С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинул нас, и, должен признаться, был изумлен, узнав о ситуации в Перекрестке. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие.$B$BТы благородно поступил в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй ее во благо, $N... во благо.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6131, 'Союзник Древобрюхов', 'Фурболги Древобрюхов – единственное фурболгское племя, не затронутое порчей. Однако, нынче многие расы без разбору убивают всех фурболгов подряд. И потому фурболгов Древобрюхов осталось так мало.$B$BХочешь заслужить доверие? Изгони из Оскверненного леса пораженных порчей фурболгов Мертвого Леса, и в один прекрасный день мы признаем тебя $gсоюзником:союзницей:. Ты найдешь первое племя Мертвого Леса – воинов, следопытов и садовников – к западу от меня.', 'Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 5 воинов 5 землепроходцев и 5 садовников из племени Мертвого Леса.', '', NULL, NULL, NULL, 'Воин из племени Мертвого Леса убито', 'Землепроходец из племени Мертвого Леса убито', 'Садовник из племени Мертвого Леса убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6132, 'Вытащи меня отсюда!', 'Вытащи меня отсюда!$B$BЯ отправилась к Долине Копий, чтобы поговорить с Мародинами. Мне казалось, с ними можно вести кое-какие дела... Но они не желают говорить со мной! Мне кажется, они... они хотят съесть меня!$B$BТолько вытащи меня отсюда – вот увидишь, мой брат Хормиц тебе кучу денег отвалит! А найти-то его несложно: он в нашем лагере, к востоку отсюда, там еще Кладбище кодо рядом.$B$BНам лучше поторопиться, $N: буквально пару минут назад я слышала, как два кентавра говорили, что нужно собрать дрова для готовки...', 'Проводите Мелиццу Жужжалит в лагерь у Кладбища кодо в Пустошах. Поговорите с Хормицем Жужжалитом.', 'Моя сестра Мелисса предупредила меня о твоем приходе. Хочу тебя поблагодарить за то, что вытащил ее из очередной беды. Правда, боюсь, она уже успела вязаться во что-то новое...', 'Тебе не встречалась моя сестра Мелисса? Вечно она где-то гуляет... До добра это не доведет!', NULL, NULL, 'Мелицца Жужжалит провождена в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6133, 'Охота на cледопытов', 'Высшие эльфы в Сторожке Кель\'Литиен присвоили себе кое-что, что принадлежит мне, $C. Это документ, описывающий мою смертную жизнь. $B$BНет, к тебе его содержимое не имеет никакого отношения – даже не вздумай сунуть туда нос! Твое дело маленькое – принеси мне документ!$B$BИ имей в виду, тупица, я хочу, чтобы эти негодяи пожалели, что наложили свои лапы на мою частную собственность! Нанеси им как можно больший ущерб!', 'Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель\'Таласа. Документ находится где-то в Сторожке Кель\'Литиен.Также убейте 8 следопытов, 8 разведчиц дорог и 8 лесников.', 'Надеюсь, тебе хватило ума не совать свой нос в реестр. С твоей стороны это было бы равносильно самоубийству.', 'Не заставляй меня ждать, $C!', NULL, NULL, 'Разведчица дорог убито', 'Следопыт убито', 'Лесник убито', 'Реестр Кель\'Таласа');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6134, 'Сбор эктоплазмы', 'На юго-востоке есть местность, именуемая Долиной Костей. Долину эту населяют призраки кентавров племени Маграм. Жутковато звучит, верно? Подумай, как это пугает Маграмов!.. Если бы нам удалось собрать энергию призраков – только представь, что за это дали бы кентавры!..$B$BВот, возьми эти призрачные магниты. Если поставишь такой магнит между двух скелетов, Мертвых Гигантов, то призраки потянутся к нему. Отойди подальше, уничтожь призраков и собери их эктоплазму: позже мы продадим ее Маграм.', 'Принесите 8 единиц эктоплазмы и ящик призрачных магнитов Хормицу Жужжалиту в Пустоши.', 'А вот и она!.. Похоже, ты и сам в эктоплазме перемазался. Склизкая штука, верно?$B$BЧто ж, $N, прими мою благодарность. Эта дрянь стоит целого состояния... Конечно, если удастся убедить кентавров ее купить!', 'Эй, $N, где моя эктоплазма?', NULL, NULL, 'Ящик с призрачным магнитом (Прилагается)', 'Эктоплазма', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6135, 'Проклятый Тенекрыл', 'Пока тебе удается с горем пополам выполнять мои поручения.$B$BПора бы заставить тебя сделать что-нибудь посложнее. Да, тупица, ты $gдозрел:дозрела: до настоящей работенки.$B$BВот что, выследи и убей Тенекрыла – это чудовищная летучая мышь-альбинос, которая хозяйничает в землях к северу отсюда. И принеси мне клок его белой шерсти – чтоб я знал, что ты не врешь!', 'Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостеню.Говорят, Тенекрыл рыщет в землях к северу от имения Марриса.', 'Неплохая работа, тупица. Посмотрим, что можно сварганить для тебя из этого меха...', 'Не советую соваться к твари в одиночку, $C.', NULL, NULL, 'Полоска меха Тенекрыла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6136, 'Огромный червь', 'За лагерем Серебряного Рассвета и часовней Последней Надежды, к западу от Северного Дола обитает огромный червь, Мерзкослиз.$B$BЯ потерял целые батальоны в попытках уничтожить его. Его размеры невообразимы! Чем больше он ест, тем больше растет...$B$BХотя я, в общем-то, мало волнуюсь по поводу того, сожрет ли тебя червь, должен признать, что предпочел бы, чтобы ты $gвышел победителем:вышла победительницей:. Учти, Мерзкослиз особенно охотно жрет тех, кто попытался напасть на него.', 'Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостеню по выполнению задания.', 'О, да ты делаешь успехи! Такими темпами скоро получишь повышение – от полного имбецила до недоумка.', 'Как же ты меня достал!', NULL, NULL, 'Мерзкослиз убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6141, 'Брат Антон', 'Антон, мой собрат по оружию, услышал вести о нашествии нежити в далеком Калимдоре, в тех землях, что называются Пустошами. Конечно же, он немедленно собрался в путь, чтобы покончить с этой угрозой!$B$BОн ищет отважных и решительных спутников – тех, у кого хватит храбрости сражаться с ним плечом к плечу. Если ты хранишь чистоту в своем сердце, разыщи брата Антона в городе, носящем имя Высоты Найджела, в Пустошах.', 'Поговорите с братом Антоном на Высоте Найджела, что в Пустошах.', 'Я получил вести о помощи, грядущей с востока. Не о тебе ли шла речь? Ты пришел сюда, дабы помочь Алым в нашем благородном походе?$B$BЕсли это так, то слушай...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6142, 'Наживка из моллюска', 'Судя по виду, $C, ты – $gзаядлый рыбак:заядлая рыбачка:! Обожаю ловить рыбу, всю жизнь этим занимаюсь. Можешь мне поверить, нет лучшей наживки, чем мясо мягкокожего моллюска: рыба просто не может против нее устоять, если ты понимаешь, о чем я.$B$BНа север отсюда, неподалеку от берега, есть потерпевший крушение корабль: так вот, вокруг него эти моллюски так и кишат! Принесешь мне 10 кусочков мяса моллюска – а взамен я тебе дам кое-что полезное...', 'Найдите 10 кусочков мяса мягкокожего моллюска и принесите Май\'Лахии в деревню Ночных Охотников.', 'Это просто великолепно!.. Когда я спросила у знахаря, как лечить головную боль, он мне ответил: Май\'Лахия, детка, попробуй половить рыбку в мутной воде; увидишь – тебе сразу полегчает!$B$BОх, как подумаю – мне и правда сразу легче становится!', 'Дождаться не могу, когда же отправлюсь на рыбалку. Я просто мечтаю о наживке из мяса моллюсков!.. Ты ведь принес мне 10 кусочков, как я просила?', NULL, NULL, 'Мясо мягкокожего моллюска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6143, 'Смерть земноводным!', 'Может, ты $gслышал:слышала:, может, нет... Мы с командой рыбачили неподалеку от острова Раназьяр, к северу от разбитого корабля на северном побережье. Мы всегда там рыбачили, сколько я себя помню – а теперь я ни о чем другом не могу думать, кроме как о мести за своих друзей...$B$BОднажды утром на нас напали наги. Они убили всех, кроме меня!..$B$BЯ не могу вынести бремени этой вины, $C, пойми меня: ты $gнужен:нужна: мне, чтобы расправиться с проклятыми нагами. Поверь, я хорошо вознагражу тебя. Ты ведь возьмешься за это дело?', 'Убейте 7 мирмидонов, 7 наг и 5 колдуний из клана Скользящего Плавника, а затем вернитесь в деревню Ночных Охотников и поговорите с Друлзегаром.', 'Ты говоришь, эти мерзкие твари мертвы? Да, месть сладка... Но в моем сердце по-прежнему пустота, которой ничто не заполнит. Я посвящу всю свою жизнь тому, чтобы извести нагов под корень – весь их род до последнего змееныша!..$B$BВот, дружище, держи свою награду, как я и обещал – хотя она ничтожно мала в сравнении с моей благодарностью...', NULL, NULL, NULL, 'Мирмидон из клана Скользящего Плавника убито', 'Нага из клана Скользящего Плавника убито', 'Колдунья из клана Скользящего Плавника убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6144, 'Приказ по армии', 'Мы получили приказ,$C. Сам Вариматас требует, чтобы я прислал ему наиболее способных солдат в Подгород для выполнения крайне сложной операции. $B$BУвы, самые достойные и способные давно погибли, а вместо них я располагаю кучкой жалких недоумков.$B$B*Натанос окидывает вас ледяным взглядом*$B$BПредстанешь перед Вариматасом в Подгороде. Смотри, не опозорь меня, $C!', 'Отправляйтесь в Подгород и поговорите с Брагором Кровопалом.', 'Верховный рыцарь восседает в Бастионе Алого ордена пока его войска хозяйничают в наших землях, сея скверну и разрушения.$B$BТемная Госпожа повелела мне разобраться с этим червяком раз и навсегда. Ты заставишь их расплатиться за свои деяния.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6145, 'Курьер из Багрового Легиона', 'Тело не может жить без головы, а голова без тела. Оборона сил Алого ордена в Стратхольме практически несокрушима. Однако мы можем обезглавить их армию.$B$BМои верные стражи смерти уже давно собирают сведения о деятельности Алого ордена за пределами Стратхольма. Каждый день им присылают инструкции из центрального штаба в Длани Тира. Мы должны перехватить их, $r! Убей курьера из Багрового легиона и забери бумагу. Отдашь ее Натаносу.', 'Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового легиона. Убейте его и заберите приказ верховного рыцаря.За дальнейшими указаниями обращайтесь к Натаносу Гнилостню.', '*Натанос хохочет и потирает руки*$B$BОтлично! Наконец-то! Наконец-то у меня есть возможность уничтожить Алого Оракула!', 'Если ты справишься с этой задачей, можешь считать, что почти заслужил мое уважение? $C.', NULL, NULL, 'Приказ верховного рыцаря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6146, 'Уловка Натаноса', 'Я тут немного подрихтовал приказ. Если наша маленькая уловка сработает, Алый Оракул на некоторое время окажется почти без защиты. Тут-то мы и нанесем удар!$B$BТеперь слушай внимательно, $C. Доставишь приказ лорду-рыцарю Валдермару.$B$BЧто значит как?! Лично в руки, тупица!$B$BДержи приказ и это гнилое яблоко – съешь его, когда войдешь в город. Оно... э-э... придаст тебе более приятный для человеческого глаза вид. Запомни, лично в руки лорду-рыцарю Валдермару!', 'Отправляйтесь в Длань Тира к юго-востоку от поместья Маррисов. Прибыв в город, откусите от гнилого яблока. Под личиной рыцаря Алого ордена доставьте приказ верховного рыцаря лорду-рыцарю Вальдермару.', 'Где тебя носило так долго? Я уж думал, тебя схватили твари Плети!', 'Не ныть, солдат! Приказы не обсуждаются!', NULL, NULL, 'Приказ верховного рыцаря', 'Сундук Натаноса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6147, 'Назад к Натаносу', 'Верховный рыцарь прислал очень странный приказ... Однако приказы не обсуждаются. Возвращайся в бастион Алого ордена и сообщи, что Оракул выдвигается немедленно.$B$BМы приложим все усилия, чтобы доставить его в Стратхольм в целости и сохранности.', 'Возвращайтесь к Натаносу Гнилостню и отчитайтесь о выполнении задания.', 'Болваны! Они ни о чем не догадались! Ну, готовься, $C. Настало время нанести решающий удар!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6148, 'Алый Оракул Деметрия', 'Деметрия – главный советник верховного рыцаря. Ее величают Оракулом за ее сверхъестественные способности. Она неоднократно оказывала помощь Алому ордену в боях с Плетью.$B$BПосмотрим, в самом ли деле ей открыто будущее... Уверен, она предвидела, что ее ждут неприятности. Вот ты их ей и обеспечишь!$B$BВыследи Оракула и убей ее. Полагаю, сейчас она на пути к Длани Тира. Не подведи меня, насекомое!', 'Алый орден сейчас в пути. Найдите оракула Деметрию и ее свиту на дороге от Длани Тира в Стратхольм. Убейте оракула и возвращайтесь к Натаносу Гнилостню.', 'От этого удара они нескоро оправятся! Отлично, $N! Ты заслужил мое доверие и эту награду!', 'Тебе удалось убить ее?', NULL, NULL, 'Деметрия убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6161, 'Сокровища Ракмора', 'Записи Ракмора рассказывают о том, как во время плаванья к Крепости Оперенной Луны его корабль был атакован морскими тварями. Чтобы не дать врагу завладеть его сокровищем, Ракмор спрятал сундук на острове Раназьяр.$B$BОткрыть сундук можно только двумя ключами, золотым и серебряным. Они были утрачены, но если разыскать и сундук, и оба ключа – кто знает, какие сокровища откроются счастливцу?', 'Найдите серебряный и золотой ключи Ракмора, а затем разыщите и отоприте сундук Ракмора.', 'Сундук открывается. Перед вами сокровище Ракмора!', 'Сундук надежно заперт...', NULL, NULL, 'Серебряный ключ Ракмора', 'Золотой ключ Ракмора', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6162, 'Последняя битва супруга', 'Мой супруг ради чести нашего клана отправился в Оскверненный лес, чтобы сразиться с Советом Теней и прочими мерзостными тварями!$B$BОн несколько раз избегал смерти. Потом я получила письмо от него, в котором он говорил, что некий друид попросил у него помощи против огромного пораженного порчей фурболга по имени Рор – и с тех пор я не слышала больше ни о муже, ни о друиде.$B$BЯ хочу, чтобы ты $gпринес:принесла: мне отрубленную когтистую лапу этого Рора, $N! Я жажду мести за мое вдовство! Эта тварь, как я знаю, засела где-то на юге, возле границы Ясеневого леса.', 'Убейте властителя Рора и принесите его коготь Дрека\'Сур на заставу Отравленной Крови в Оскверненном лесу.', 'Ты держишь слово – честь для меня познакомиться с тобой. Мой муж погиб в бою – он гордился бы тобой. Но я не смогла бы спокойно спать, если б не знала, что тварь, обрекшая меня на одиночество, заплатила за все!$B$BЕще раз спасибо тебе, $N.', 'Где коготь этой твари, $N? Он заплатит за свои преступления! Мне плевать, из-за порчи это или просто со злости, что он живет в таком поганом лесу! Никакому фурболгу не прощу зла, причиненного моей семье!', NULL, NULL, 'Коготь Властителя Рора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6163, 'Рамштайн', 'На этом самом месте я когда-то держал оборону Лордерона... Бесчисленное воинство Плети прошло волной по моей ферме, уничтожив все живое на своем пути.$B$BГрязь. Скверна. Я стал беспомощной и безвольной игрушкой в руках Плети, оказавшись в рядах нежити. Сознанием моим управляла воля Короля-лича. $B$BА потом она освободила меня... Я ждал, я надеялся и наконец обрел свободу.$B$BТеперь я хочу отомстить чудовищу, забравшему мою жизнь. Убей его!', 'Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира.', 'Надеюсь, ты заставил тварь умолять о пощаде?$B$B*Натанос всердцах плюет на землю*$B$BПовешу эту голову над камином.$B$BХорошая работа, Тихийгуставо. Ты заслужил мое уважение.$B$B*Натанос отдает честь*.', 'Когда Сильвана освободила меня, я гонялся за тварью, убившей меня, многие месяцы, но безрезультатно. Чудовище укрылось в Стратхольме...', NULL, NULL, 'Голова Рамштайна Ненасытного', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6164, 'Книга рецептов Августа', 'Пожалуй, я готов открыть лавку...$B$BО нет! Моя книга рецептов! Мне не обойтись без нее!$B$BКажется, я оставил ее где-то в городе... Да, видимо, в таверне, в которой останавливался!$B$BПринеси мне мою книгу, умоляю, принеси мне ее! А когда открою лавку, ты увидишь, что цены у меня просто БЕЗУМНЫЕ!', 'Найдите книгу рецептов Августа Помешанного в таверне в Долине Ужаса.', 'Вот она! Какое счастье!$B$BЭто безумно счастливый день, $N!', 'Ты нашел книгу? Лавка простаивает!', NULL, NULL, 'Книга рецептов Августа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6181, 'Срочное сообщение', 'Хотя мы не получаем серьезной помощи напрямую из Штормграда, у меня в городе есть знакомый, снабжающий нас доспехами. Зовут его Озрик Штранг. Его магазин, \"Ограниченная неуязвимость\", находится в Старом городе.$B$BНаши запасы доспехов заканчиваются, и я должен связаться с Озриком, чтобы попросить еще. Можете ли вы передать ему эту записку?$BБыстрее всего добраться до Штормграда можно с помощью Тора, нашего укротителя грифонов. Он находится прямо у подножия этого холма. Приходите к нему с моей запиской, а затем летите на грифоне в Штормград.', 'Отнесите записку Льюиса укротителю грифонов Тору.', 'Вам нужно доставить эту записку в Штормград? Это не проблема, вы можете взять одного из моих грифонов!', 'Такое ощущение, что вы сильно торопитесь. Что ж, если так, то вы пришли в правильное место!', NULL, NULL, 'Записка Льюиса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6182, 'Первый и последний', 'Натанос Маррис был первым и последним человеком-предводителем следопытов. Учеником Сильваны Ветрокрылой, ныне Королевы-банши Отрекшихся.$B$BМы думали, что Натанос погиб в бою много лет назад, при защите Лордерона. Хотя его тело не было обнаружено, считалось, что он не сумел выбраться из Восточных Чумных земель.$B$BМатиас Шоу изучил обстоятельства его исчезновения и у него может быть какая-то информация. Поговори с ним как можно скорее. Он обитает в старом городе, в казармах.', 'Поговорите с Матиасом Шоу в Старом Городе в Штормграде. Матиас находится в казармах.', 'После появления сообщений о необычной активности Отрекшихся в Восточных Чумных землях туда были посланы агенты ШРУ для расследования ситуации. Результаты этого расследования оказались весьма тревожными.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6183, 'Поминовение усопших', 'Пятеро моих лучших полевых агентов занимались делом Марриса. Вернулся только один, и тот через три дня умер во сне.$B$BТа скудная информация, которую удалось из него вытрясти, звучала несусветной чушью. Мы разобрали лишь два слова: \"Натанос\" и \"Гнилостень\".$B$BУ меня не хватает сотрудников, чтобы продолжить это расследование, и в \"Черном Вороне\" нам не помогут. Мы должны докопаться до сути, чтобы хотя бы принести какое-то утешение семьям погибших. Вы окажете нам помощь?', 'Еще раз поговорите с Матиасом Шоу, если хотите принять его задание.', '*Матиас кивает.*$B$BЯ и не сомневался, что Болвар пришлет мне честных и благородных людей – самых преданных солдат Альянса.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6184, 'Флинт Тенемор', 'Единственные сведения, которыми мы сейчас располагаем – это то, что Натаноса Марриса, возможно, убил этот тип по имени \"Гнилостень\". Мы допускаем, что тот же \"Гнилостень\" расправился и с моими агентами.$B$BФлинт Тенемор, еще один сотрудник ШРУ, находится в лагере на Берегу Промозглого Ветра в Западных Чумных землях. Найдите его. Он расскажет вам о текущей ситуации в Чумных землях и даст задание.$B$BУдачи вам, $N.', 'Отправляйтесь в Лагерь Промозглого Ветра в Западных Чумных землях и найдите Флинта Тенемора.', 'Ваше первое задание будет очень простым, $N. Уйти – и вернуться. Провести разведку...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6185, 'Чума на востоке', 'Говорю же, первое задание – разведывательное. Ничего особенного, $N. Отправляйся в Восточные Чумные земли и поищи там сведения про Гнилостеня.$B$BИ поглядывай, не найдешь ли ты наших пропавших оперативников. Мы вынуждены предположить, что они погибли, но коли так, должны быть... трупы.$B$B*Флинт сглатывает трудный комок.*$B$BВсе агенты ШРУ носят такие знаки.$B$B*Флинт показывает вам знаки отличия ШРУ.*$B$BПринеси мне все, какие только найдешь.', 'Поищите в Восточных Чумных землях сведения про некоего Гнилостеня и пропавших агентов ШРУ. Если удастся найти знаки отличия ШРУ, отнесите их Флинту Тенемору в Лагерь Промозглого Ветра.', 'Рутгер. Фредо. Турьен. Все... Мертвы…$B$B*Флинт сжимает в руках их регалии.*$B$BГде они были? Удалось ли тебе собрать сведения про этого мерзавца, Гнилостеня?', 'Ну... Как дела?', NULL, NULL, 'Знак отличия ШРУ (Рутгер)', 'Знак отличия ШРУ (Фредо)', 'Знак отличия ШРУ (Турьен)', 'Исследовать локацию');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6186, 'Пришествие Гнилостеня', '*Флинт бледнеет.*$B$BЭто дело рук На... Натаноса? Натанос и есть Гнилостень?$B$BНо почему? Он был... таким благородным, пользовался всеобщим уважением. Единственный человек, которого согласились обучать высшие эльфы. И теперь он безжалостный сторонник Отрекшихся?$B$BМне... жаль, что приходится просить об этом, $N, но об этих событиях должен узнать король Ринн. Я прошу тебя незамедлительно вернуться в Штормград с вестями.', 'Возвращайтесь в Штормград и сообщите королю Вариану Ринну о судьбе Натаноса Марриса.', 'Нет. Не может... НЕТ! Как? Агент Отрекшихся? ЗАЩИТНИК Королевы банши???$B$B*Верховный лорд Болвар Фордрагон бессильно опускает руки.*', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6187, 'Порядок должен быть восстановлен', 'Знаешь, сколько предводителей следопытов существует на этом свете? А сколько когда-либо существовало людей-предводителей следопытов?$B$BДостижения Натаноса необыкновенны. Он был тактическим гением, благодаря ему Альянс в течение десят$Nия одерживал победы.$B$BА теперь... теперь он защитник Отрекшихся.$B$BНет. Такого быть не должно. Порядок должен быть восстановлен.$B$BСобери армию, $N. Возвращайся в Чумные земли со своими воинами и уничтожь Гнилостеня.$B$BЖелаю удачи, $N. В этом бою она тебе точно понадобится.', 'Соберите войско и отправляйтесь в Восточные Чумные земли. Проведите полномасштабную атаку на Натаноса Гнилостеня и любых воинов Орды, которые могут попытаться его защитить.Будьте осторожны, потому что Орда всеми силами будет защищать бывшего предводителя следопытов.', 'Это трагедия. Я думаю... я уверен, что над нами висит проклятие, $N. Мы приговорены терять наших величайших воинов, благороднейших героев и даровитейших ученых.$B$BМы в долгу перед вами и, уверяю вас, $N, где бы сейчас ни был Натанос Маррис, он с улыбкой взирает на вас.', NULL, NULL, NULL, 'Натанос Гнилостень убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6221, 'Северные фурболги Мертвого Леса', 'Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.$B$BПлемя Мервтого Леса злобное, но это все действие скверны, поразившей их разум. Они не враждебны от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.$B$BПрошу тебя, $N, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.', 'Нафиэн просит вас убить 5 дозорного из племени Мертвого Леса, 5 мстителей и 5 шаманов из племени Мертвого Леса.', '', NULL, NULL, NULL, 'Дозорный из племени Мертвого Леса убито', 'Мститель из племени Мертвого Леса убито', 'Шаман из племени Мертвого Леса убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6241, 'Боевые действия в деревне Зимней Спячки', 'Клан Древобрюхов готов постоять за себя, $N. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. $B$BПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. $B$BЕсли бы вы могли сократить их число, это бы нам здорово помогло, $N.', 'Убейте 6 тотемистов, 6 дозорных и 6 землепроходцев из племени Зимней Спячки по просьбе Сальфы.', '', NULL, NULL, NULL, 'Тотемист из племени Зимней Спячки убито', 'Дозорный из племени Зимней Спячки убито', 'Землепроходец из племени Зимней Спячки убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6261, 'Дунгар Долгопив', '$N, я сложил в этот ящик все, о чем просил Льюис. Можете отвезти ему ящик?$B$BС Тором в Западном Крае вы уже общались – значит, сможете нанять грифона, чтобы туда вернуться. Наш укротитель грифонов – Дунгар Долгопив, он находится в Торговом квартале.$B$BПоговори с Дунгаром и доставь этот ящик Льюису как можно скорее. Мы не хотим, чтобы нашим воинам в Западном Крае пришлось сражаться без новых доспехов!', 'Отнесите ящик Озрика к укротителю грифонов Дунгару Долгопиву.', 'Нужно доставить сундук в Западный Край, да? А вы там бывали прежде? Если да, то никаких проблем, друг мой. У меня есть множество грифонов, обученных этому маршруту!', 'Да вы вспотели, сударь! Не стоило так много бегать на своих двоих. В следующий раз возьмите грифона!', NULL, NULL, 'Ящик Озрика (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6281, 'Продолжение пути в Штормград', 'За небольшую плату вы можете нанять грифона для полета в Штормград, чтобы доставить записку Льюиса Озрику. Более быстрого пути нет.$B$BЕсли для вас это приемлемо, поговорите со мной снова, когда будете готовы лететь. Я, конечно, возьму с вас немного денег, но поверьте, оно того стоит!', 'Оплатите укротителю грифонов Тору полет до Штормграда и принесите записку Льюиса Озрику Штрангу в магазинчик \"Ограниченная неуязвимость\", расположенный в районе Старого города.', 'А, записка от интенданта Льюиса! Я не удивлен, что ему понадобилась дополнительная экипировка. Сторожевой Холм далеко, и в Штормграде едва помнят о нем.$B$BЧто ж, спасибо вам, $N. Вот немного денег на покрытие ваших транспортных расходов.', 'Путешествовали, да? Видели что-нибудь интересненькое?', NULL, NULL, 'Записка Льюиса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6282, 'Угроза со стороны гарпий', 'Таурен горд тем, что защищает эти земли. Несомненно, ты понимаешь, почему я обеспокоен тем, что здесь, в Каменном Когте, обитает множество гарпий.$B$BКлан Смертельной Ярости – вот откуда берутся все новые и новые гарпии в Калимдоре. Они посягают на жизнь всех и каждого, не давая слабым даже уйти отсюда!$B$BМне нужна твоя помощь в уничтожении гарпий, $N!', 'Землепряд Маггран из Приюта у Солнечного Камня просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости.', 'Замечательные новости! Поведай мне вновь, как тебе удалось вселить ужас в холодные сердца злобных гарпий. Клан Смертельной Ярости понес серьезный урон!', 'Не дай Обугленной долине изнурить тебя, $N. В тех холмах обитает множество злых существ. Сохраняй силы, и ты одолеешь угрозу, нависшую над нашим народом. Иди же, и рази без колебаний – пусть наши дети никогда не изведают этого зла.', NULL, NULL, 'Гарпия из стаи Кровавой Ярости убито', 'Душительница из стаи Кровавой Ярости убито', 'Душегубка из стаи Кровавой Ярости убито', 'Бродяжница из стаи Кровавой Ярости убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6283, 'Предводительница стаи Кровавой Ярости', 'Уменьшить число гарпий из стаи Кровавой Ярости – этого недостаточно. Единственное, чем можно извести эту заразу – это убить их предводительницу, Потрошительницу!$B$BСредь этих мерзостных существ она почти королева. Убей ее, и гарпий станет меньше.$B$BВозвращайся в Обугленную долину, и ты найдешь ее у западных холмов. Ее не так-то легко уничтожить, но награда будет велика.', 'Маггран из Приюта у Солнечного Камня просит убить Потрошительницу из стаи Кровавой Ярости и принести ему ее останки в доказательство того, что она мертва.', 'Я уже чувствую, как гнев покидает меня. Что мне теперь делать? Знание о том, что зло бродило поблизости от моих земель, заставляло мои мысли течь быстро, пусть и безмолвно. Быть может, это и к лучшему... быть может, теперь я смогу обратить свои мысли в сторону добра, как и положено таурену.$B$BПрошу тебя, прими это в награду за твои труды.', 'Потрошительница из стаи Кровавой Ярости – ужасное существо! Ты, несомненно, найдешь ее у подножия западных холмов в Обугленной долине.$B$BБез нее гарпии будут бессильны... и мы уж точно сможем избавиться от них!', NULL, NULL, 'Останки потрошительницы из стаи Кровавой Ярости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6284, 'Арахнофобия', 'Предупреждение: дорога отсюда на запад, в Сиширский каньон, опасна.$B$BБесселет и ее восьминогие отпрыски превратили этот каньон в свое логово, заплетенное паутиной.$B$BМаггран Связующий Землю из Приюта у Солнечного Камня назначил награду за Бесселет. Убей ее и принеси доказательство ее смерти Магграну – получишь награду за устранение этой восьминогой угрозы.', 'Убейте Бесселет и принесите клык Бесселет Магграну в Приют у Солнечного Камня.', 'Добрая охота, $N! Бесселет издавна была угрозой для этих земель... и я не буду по ней тосковать. Возьми эту награду в знак того, что тебе удалось защитить наш лес.$B$B*Маггран потирает рану, нанесенную Бесселет.*$B$BБыть может, теперь больше народа будет приходить в Приют у Солнечного Камня, не боясь того, что крадется во мраке.', 'Бесселет – безжалостный хищник... Я опасаюсь за тех, кто путешествует по Паучему Тракту ночами. Именно тогда Бесселет и ее отродья охотятся на ничего не подозревающих путников. Я сам едва не стал жертвой ее полуметровых смертоносных клыков, но, к счастью, сумел отбиться и убежать. Я отдам что угодно за то, чтобы это чудовище было уничтожено.', NULL, NULL, 'Клык Бесселет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6285, 'Возвращение к Льюису', 'Укротителем грифонов в Западном Крае работает Тор. Если вы с ним уже знакомы, то можете на одном из моих грифонов к нему долететь.$B$BПолезная для вас информация: грифоны обучены так, что до столицы могут долететь всегда, а к укротителям, расположенным в других местах, полетят, только если вы там уже бывали.$B$BВы ведь уже были у Тора, так что просто поговорите со мной еще раз, когда будете готовы лететь в Западный Край. А там уже отнесете ящик Озрика интенданту Льюису.', 'Оплатите укротителю грифонов Дунгару Долгопиву полет до Сторожевого холма, а затем отнесите ящик Озрика Льюису.', 'Отлично, вы привезли доспехи! Мы распределим их между теми, кому они срочно необходимы.$B$BСпасибо вам, сэр $N. Вы нам очень помогли. А теперь, когда вы знакомы и с нашими грифонами, я надеюсь, вы будете часто пр$Nать к нам и предлагать свою помощь Сторожевому холму!', 'Вы уже вернулись из Штормграда? Озрик прислал доспехи?', NULL, NULL, 'Ящик Озрика (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6301, 'Цикл возрождения', 'Жадность промышленников и постоянная война опустошили земли Каменного Пика. Только благословение Матери-Земли может исцелить такие раны.$B$B$N, я хочу отправить тебя на поиски особого семени – семени Геи. Его можно найти только здесь, в Каменном Когте, к северу от Приюта у Солнечного Камня, у Мутного Озера, у самого края воды. $B$BКак только ты принесешь мне эти семена, я напитаю их шаманской силой, дабы ускорить их рост.', 'Таммра Перекати-поле из Приюта у Солнечного Камня просит вас собрать 10 семян Геи.', 'О, $N, так вот они – семена Геи! Смотри и увидишь, как благословение Матери-Земли даст этим крошечным семенам жизни возможность цвести и плодоносить.$B$B*Таммра начинает читать заклинание.*', 'Страшные разрушения, причиненные войной и теми, кто наживался на лесозаготовках, глубоко ранят мою душу. Чтобы начать цикл возрождения и оживить эти земли, мне нужны семена Геи. Есть ли они у тебя, $C?', NULL, NULL, 'Семя Геи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6321, 'Поставка оружия', 'Исполнитель Хадрик попросил меня заняться нашим арсеналом в Гробнице. По лесу рыщут силы Плети, а то и кое-что похуже, и он хочет, чтобы у наших стражей смерти было достаточно оружия, когда оно понадобится. $B$BЯ выяснил, что в целом у нас все в порядке, но нам нужно дополнительное оружие взамен потерянного в боях. $B$BВот заявка на поставку для торговца оружием Гордона Уиндема, находящегося в Подгороде. Отнесите этот заказ нашему дрессировщику летучих мышей, Каросу Раззоку, и поговорите с ним о полете в Подгород.', 'Отнесите заказ Подрига Каросу Раззоку.', 'А, заказ на поставки. Не сомневаюсь, вам нужно доставить его в Подгород. И как можно скорее, потому что в Гробнице нельзя допустить нехватку оружия.', 'Похоже, вы пришли по серьезному делу?', NULL, NULL, 'Заказ Подрига (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6322, 'Майкл Гарретт', 'Я сложил припасы для Гробницы в этот ящик. Если ты уже $gбывал:бывала: в Гробнице и $gзнаком:знакома: с тамошним дрессировщиком летучих мышей, то можешь туда лететь. $B$BПоговори с дрессировщиком летучих мышей здесь, в Подгороде – с Майклом Гарреттом. Он поможет тебе добраться до Гробницы.', 'Отправляйтесь к Майклу Гарретту с ящиком Гордона.', 'Этот ящик нужно доставить в Гробницу, что в Серебряном бору? Это легко: наши мыши ежедневно туда летают.', 'Если вам нужно преодолеть большое расстояние, удобнее всего сделать это на летучей мыши.', NULL, NULL, 'Ящик Гордона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6323, 'Полет в Подгород', 'Одна из моих летучих мышей может отвезти вас в Подгород, за небольшую плату. Приходите ко мне, когда будете готовы, чтобы мы могли организовать ваш полет. $B$BГордона Уиндема вы найдете в Торговом квартале Подгорода. Именно там и приземлится летучая мышь.', 'Оплатите у дрессировщика летучих мышей Кароса Раззока полет до Подгорода, а затем отнесите заказ Подрига Гордону Уиндему в Подгороде.', 'Заказ из Гробницы? Отлично. Для меня честь – услужить тем, кто служит Темной Госпоже.', 'Я держу оружие в отличном состоянии. Все почищено и готово к использованию.', NULL, NULL, 'Заказ Подрига (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6324, 'Обратно к Подригу', 'Дрессировщика летучих мышей в Гробнице зовут Карос Раззок. Если вы уже знакомы с ним, я могу предоставить вам одну из своих летучих мышей, чтобы вы к нему вернулись. $B$BВсе наши мыши всегда могут долететь до Подгорода, но, чтобы добраться до более отдаленных мест, пассажир должен сначала посетить эти места и познакомиться с тамошними дрессировщиками. $B$BС Каросом вы уже встречались в Гробнице, так что теперь можете летать туда на мышах. Вернитесь ко мне, когда будете готовы к полету.', 'Оплатите у дрессировщика летучих мышей Майкла Гарретта полет до Гробницы, а затем отдайте ящик Гордона стражу смерти Подригу в Гробнице.', 'Хорошая работа, $N. Это оружие позволит не застать врасплох наших стражей смерти. $B$BВы сослужили хорошую службу Темной Госпоже.', 'Вы вернулись, $N. Привезли наши припасы из Подгорода?', NULL, NULL, 'Ящик Гордона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6341, 'Изобилие Тельдрассила', 'Рыбаки деревни Рут\'теран живут очень хорошо: ведь рыба здесь очень крупная, и ее много. Я хотела бы сравнить здешнее изобилие с ситуацией в материковых водах.$B$BЯ собрала образцы рыбьих костей и чешуи, которые хотела бы отправить своему коллеге на Темные берега. Его зовут Лайрд, он торгует рыбой в Аубердине.$B$BИдите с моей коллекцией образцов к нашему укротителю гиппогрифов, Веспристу, и поговорите с ним насчет полета в Аубердин.', 'Отнесите коллекцию Нессы к Веспристу.', 'А, вы хотите доставить эту посылку в Аубердин? Отлично...', 'Чем могу помочь? Нужен транспорт?', NULL, NULL, 'Коллекция Нессы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6342, 'Полет в Аубердин', 'Из деревни Рут\'теран можно добраться в Аубердин двумя путями: на пароме и на гиппогрифе. Оба способа быстры и надежны, но если вы еще никогда не летали в Аубердин на гиппогрифе, я бы порекомендовал вам это сделать.$B$BМой вам добрый совет: говорите с дрессировщикам гиппогрифов в каждом городе, где они есть. Когда вы поговорите с дрессировщиком, то сможете летать в этот город из других мест.$B$BВозвращаю вам коллекцию Нессы. Поговорите со мной, когда будете готовы лететь в Аубердин и доставить коллекцию Лайрду.', 'Совершите полет в Аубердин на гиппогрифе укротителя Весприста и отнесите коллекцию Нессы Лайрду.', 'Посылка от Нессы? Спасибо, $N! Она говорила, что собирается прислать мне образцы рыбы, пойманной близ деревни Рут\'теран. Она думает, что эта рыба может серьезно отличаться от той, что ловится здесь...$B$BНичего себе! Эта челюсть чуть ли не вдвое больше, чем у таких же здешних рыб. А эта чешуя размером с кулак! Невероятно!', 'Вы прибыли из Тельдрассила? Скажите, как там ловится рыба?', NULL, NULL, 'Коллекция Нессы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6343, 'Возвращение к Нессе', 'Мне нужно отправить Нессе ответ. Ей будет очень интересно знать, насколько здешняя рыба отличается от той, что водится у берегов Тельдрассила. Мы можем лишь догадываться о причинах, но подозреваю, что так воздействует само Древо Жизни на окружающую его природу!$B$BПожалуйста, отнесите мой ответ Нессе. Если хотите лететь в Рут\'теран на гиппогрифе, поговорите с дрессировщиком гиппогрифов Кайлаис Лунному Перу. А если хотите добраться паромом, то он регулярно отходит от причала к северо-западу отсюда.', 'Принесите ответ Лайрда Нессе Песне Теней.', 'Все это очень интересно. Рыба здесь крупная, но я не думала, что разница между обитающими в материковых и здешних водах столь велика. Для этого должна быть причина...$B$BЧто ж, благодарю вас, $N. Я обсужу с земляками новости, что вы принесли. Может быть, когда-нибудь мы найдем причину этой странности. А пока будем ею пользоваться!', '$N, вы уже вернулись из Аубердина? Вы говорили с Лайрдом?', NULL, NULL, 'Ответ Лайрда (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6344, 'Несса Песнь Теней', 'Моя подруга, Несса Песнь Теней, торгует рыбой в деревне Рут\'теран. Ей нужно доставить посылку на Темный берег, и она ищет кого-нибудь, кто мог бы ей помочь.$B$BЕсли вы хотите помочь Нессе, то ступайте в деревню Рут\'теран через портал в Дарнасе. Портал находится к западу от Храмовых садов.', 'Поговорите с Нессой Песнь Теней.', 'Да, мне нужен курьер, который доставит посылку на Темный Берег. Вы мне поможете?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6361, 'Связка шкур', 'Я хочу переслать в Громовой Утес связку шкур степных зверей. Мой коллега, Ахану, занимается кожевенным делом и найдет им достойное применение.$B$BНе возьмешься доставить ему шкуры?$B$BДо Громового Утеса проще всего добраться на ветрокрыле. Отнеси шкуры укротителю ветрокрылов Девраку и поговори с ним насчет доставки в Громовой Утес.', 'Отнесите связку шкур Зарга укротителю ветрокрылов Девраку из Перекрестка.', 'Хочешь отвезти эти шкуры в Громовой Утес? Тогда ты обратился по адресу!', 'Тебе нужн ветрокрыл? Собираешься доставлять какие-то товары?', NULL, NULL, 'Связка шкур (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6362, 'Дорога до Громового Утеса', 'За небольшую плату ты можешь полететь в Громовой Утес на ветрокрыле. Быстрее не бывает!$B$BЕсли тебя устраивает цена – обращайся, когда решишь отправиться в путь.$B$BЕсли ты везешь эти шкуры Ахану, думаю, ты отыщешь его в оружейной Хевы, у основания башни ветрокрылов в Громовом Утесе. Именно там ты и приземлишься!', 'Оплатите перелет в Громовой Утес укротителю ветрокрылов Девраку и, оказавшись на месте, отнесите связку шкур Ахану.', 'А, новая связка шкур. Я немедленно ими займусь.$B$BСпасибо, брат. Ты оказал мне большую услугу. Возьми эти монеты, чтобы покрыть дорожные расходы и потраченное время.', 'Судя по пыли на одежде, ты только что из Степей. Тебя мой друг Джахан прислал?', NULL, NULL, 'Связка шкур (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6363, 'Укротитель ветрокрылов Тал', 'Я приготовил кое-какие кожаные изделия на продажу в Перекрестке. Не отнесешь их Джахану?$B$BЕсли ты уже $gпоговорил:поговорила: с укротителем ветрокрылов в Перекрестке, можешь полететь туда на виверне.$B$BОтнеси мои товары здешнему укротителю ветрокрылов Талу и поговори с ним насчет дороги до Перекрестка.', 'Отнесите кожаные вещи Ахану Талу из Громового Утеса. ', 'Тебе нужно в Перекресток? Нет проблем. Если ты там уже побывал и поговорила с Девраком, можешь лететь на одном из моих ветрокрылов.', 'Приветствую тебя, $C. Чем могу помочь?', NULL, NULL, 'Кожаные вещи Ахану (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6364, 'Возвращение к Джахану', 'Чтобы полететь в какой-нибудь город, следует сначала побывать в нем и поговорить с укротителем ветрокрылов. В Перекрестке ты уже $gпобывал:побывала:, поэтому за небольшую плату ветрокрыл может отнести тебя туда.$B$BОбращайся, когда решишь отправиться в путь. Оказавшись в Перекрестке, отнеси кожаные вещи Джахану Соколиному Крылу.', 'Оплатите перелет до Перекрестка у укротителя ветрокрылов Тала, а затем отнесите кожаные вещи Ахану Джахану Ястребиному Крылу.', 'Ахану прислал мне готовые изделия? Очень хорошо. В Перекресток забредает много охотников и искателей приключений, и дела у меня идут неплохо.$B$BСпасибо за помощь, $N. Я у тебя в долгу.', '$N, ты уже вернулся из Громового Утеса? Ахану получил мои шкуры?', NULL, NULL, 'Кожаные вещи Ахану (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6365, 'Мясные продукты в Оргриммар', 'Я хочу послать своей подруге несколько видов превосходных мясных продуктов. Ее зовут Гришка, она хозяйка таверны в Оргриммаре. Поможешь мне доставить мясо?$B$BДо Оргриммара проще всего добраться на ветрокрыле. Отнеси мясные продукты Девраку, укротителю ветрокрылов, и поговори с ним насчет доставки в Оргриммар.', 'Отнесите мясные продукты Зарга Девраку из Перекрестка.', 'Тебе нужно доставить мясо в Оргриммар? Нет проблем. За небольшую плату тебя отнесет туда мой ветрокрыл.', 'Хочешь куда-то добраться в мгновение ока? Тогда ты обратился по адресу!', NULL, NULL, 'Мясные продукты Зарга (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6381, 'Новая жизнь', 'Вот видишь, $C, хотя эта земля глубоко изранена, круговорот жизни – великая сила. Теперь мы должны внести свой вклад и помочь этой силе. Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине. Но берегись – там, в полумертвых землях, еще встречаются гарпии и злобные элементали огня.$B$B$N, возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы. Круговорот жизни должен продолжаться!', 'Посадите 10 семян Геи в земляные курганы Геи, а затем верните оставшиеся зачарованные семена Геи Таммре в Приют у Солнечного Камня.', 'Это великая победа, свершенная ради здешних земель. Со временем произойдут и другие перемены: Торговая компания уберется отсюда вместе со своими пилами и топорами, разгневанные духи огня успокоятся, а гарпии будут изгнаны с этих земель.$B$BТолько тогда, $N, в Каменном Когте настанет истинный мир.$B$BТы совершил благое дело, $C; возьми один из этих предметов в награду за вклад в создание новой жизни.', 'Семена, посаженные тобою, очень сильны, они сопротивляются порче и помогут создать основу для других видов жизни. Они будут расти и расти, сначала не давая распозаться порче и исцеляя израненную землю, а затем, в один прекрасный день, вновь покроют земли Каменного Котя густыми лесами.$B$BВсе ли семена Геи израсходованы на эти посадки?', NULL, NULL, 'Посажено семян Геи', 'Заколдованные семена Геи (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6382, 'Большая охота', 'Твоя сила производит впечатление, $C, а интерес к охоте дает надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьезнее.$B$BОрда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса. Если ты $gготов:готова: проявить себя в непознанных еще землях, обратись к Сенани Громовое Сердце на заставе Расщепленного Дерева. Она находится к северу от тропы из Степей.', 'Поговорите с Сенани Громовое Сердце на заставе Расщепленного Дерева в Ясеневом лесу.', 'Добро пожаловать на новое пограничье, $N. Ясеневый лес – край неограниченных возможностей, где юному $C) вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.$B$BКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6383, 'Большая охота', '', '', 'Великая охота в Ясеневом лесу заключается в убийстве трех легендарных тварей. Ты можешь выследить их и испытать свои умения против их хитрости и силы. И в этом испытании ты, надеюсь, поймешь что-то и о себе. Вот эти чудища – медведь Топтыжень, ночной саблезуб Тенумбра и гиппогриф Острокоготь.Эти твари могучи, и, возможно, тебе понадобится помощь. Ели тебе удастся их одолеть, принеси мне доказательства своих подвигов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6384, 'Дорога до Оргриммара', 'Всего лишь за несколько монет ветрокрыл отнесет тебя в Оргриммар. Оказавшись там, отнеси мясные продукты Зарга Гришке. Ее постоялый двор располагается на аллее Силы неподалеку от небесной башни, где тебя высадит мой ветрокрыл.$B$BПоговори со мной, когда решишь отправиться в путь.', 'Оплатите полет в Оргриммар укротителю ветрокрылов Девраку и, оказавшись в Оргриммаре, отнесите мясные продукты Зарга Гришке.', 'О, чудесно! Какое отличное мясо! Оно ведь от Зарга, да? Этот орк знает, как завоевать женское сердце…$B$BОх, мне не терпится его приготовить. Но не слишком много! Мясо вкуснее, когда его подают редко, верно?', 'Какой вкусный запах! Ты часом не сырое мясо несешь?', NULL, NULL, 'Мясные продукты Зарга (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6385, 'Укротитель ветрокрылов Дорас', 'Я написала Заргу письмо благодарности. Поможешь с доставкой? Если ты уже $gпоговорил:поговорила: с укротителем ветрокрылов в Перекрестке, то можешь полететь туда.$B$BИди с моим письмом к Дорасу, оргриммарскому укротителю ветрокрылов, и поговори с ним насчет полета до Перекрестка.', 'Отнесите письмо Гришки Дорасу из Оргриммара.', 'Тебе нужно доставить письмо в Перекресток? Да, мои виверны могут отнести тебя туда.', 'Тебе нужен ветрокрыл?', NULL, NULL, 'Письмо Гришки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6386, 'Возвращение на Перекресток', 'Мои виверны могут отвезти тебя в самые разные края – при условии, что ты $gсам:сама: там уже $gбыл:была: и $gговорил:говорила: с местным укротителем ветрокрылов.$B$BТебе уже доводилось бывать в Перекрестке, да и Деврака ты знаешь, так что, лети прямо к нему. Оказавшись в Перекрестке, ты сможешь передать Заргху письмо Гришки.$B$BКак будешь $gготов:готова:, скажи.', 'Оплатите перелет в Перекресток укротителю ветрокрылов Доресу и, оказавшись на месте, передайте письмо Гришки Заргху из Перекрестка.', 'Ха! Я так и знал, что ей понравится! Ничто так не нравится женщинам, как хороший сочный стейк!$B$BСпасибо, $N. Ты оказал мне неоценимую услугу. Вот тебе плата за труды – и не удивляйся, если я приглашу тебя на свадьбу!', 'Ты вернулся из Оргриммара? Гришак понравилось мясо?', NULL, NULL, 'Письмо Гришки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6387, 'Награды ученикам', 'Ко мне приходит немало молодых дворфов, мечтающих научиться горному делу. Что же нужнее всего шахтеру? Кирка!$B$BЯ составил список учеников, которые хорошо проявили себя на занятиях и заслужили почетную кирку. Отнеси этот список Голниру Твердопалу в Стальгорн. Он подготовит для меня эти кирки.$B$BПроще всего добраться до Стальгорна на грифоне, поэтому ступай с этим списком к нашему укротителю грифонов, Торгруму Боррелсону, и поговори с ним насчет полета в Стальгорн.', 'Отнесите список Брока Торгруму Боррелсону в Телcамаре.', 'Тебе нужно отвезти это в Стальгорн, да? За небольшую плату я позволю тебе оседлать одного из моих грифонов, и он отнесет тебя прямо в город. Что скажешь?', 'Надоел Телcамар? Решил слетать в другой город?', NULL, NULL, 'Список Брокка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6388, 'Грит Турден', 'Вот почетные кирки для учеников Брока. Если ты уже $gбывал:бывала: в Телcамаре, можешь полететь обратно на грифоне!$B$BОтнеси кирки нашему укротителю грифонов, Гриту Турдену, и поговори с ним насчет полета в Телcамар.', 'Отнесите почетные кирки Гриту Турдену в Стальгорне.', 'Значит, тебе нужно в Телcамар? Не вопрос. Если ты там уже бывал и беседовал с Торгрумом Боррелсоном, можешь полететь к нему на грифоне.', 'Похоже, ты собрался куда-то лететь. Хочешь нанять грифона?', NULL, NULL, 'Почетные кирки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6389, 'Чума на вашу лесопилку!', 'Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели.$B$BПримериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу.', 'Выпустите термитов с Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Западные Чумные земли.', 'Ха-ха, превосходно! Ты справился! Дух моего отца наконец сможет покоиться с миром, а уж я-то как доволен!$B$BСпасибо тебе! Проси что хочешь, чем смогу – помогу!', 'Тебе удалось, $N? Выпустил термитов? Нельзя допустить, чтобы в руках Алого ордена оказалась и лесопилки, и Дольный Очаг. Нет уж, пусть лучше останутся вовсе с пустыми руками. Они лишь умножают наши и без того многочисленные жертвы в последней войне. Нет им пощады!', NULL, NULL, 'Бочонок термитов Чумных земель (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6390, 'Чума на вашу лесопилку!', 'Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели.$B$BПримериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу.', 'Выпустите термитов Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.', 'Спасибо тебе, $N. У меня есть лишь эта монета... Но, думаю, ты получил удовольствие от самого процесса!', 'Тебе удалось, $N? Выпустил термитов?$B$BМои близкие лишились работы, а кое-кто и жизни, и я не желаю, чтобы вдобавок место, где прошло мое детство, досталось этим мнимым святошам!', NULL, NULL, 'Бочонок термитов Чумных земель (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6391, 'Полет в Стальгорн', 'Всего за несколько монет один из моих грифонов отнесет тебя в Стальгорн. Там ты сможешь отдать список Брока Голниру Твердопалу. Его можно найти в гильдии горняков Тайной Горы. Она находится неподалеку от Великой Кузни Стальгорна, и именно там тебя высадит мой грифон!$B$BКогда решишь отправиться в путь, обращайся ко мне.', 'Заплатите укротителю грифонов Торгруму Боррелсону, долетите на грифоне до Стальгорна и отдайте список Брока Голниру Твердопалу.', 'А, последний список лучших учеников Брока. Я уже подготовил почетные кирки, осталось выбить на них имена учеников...', 'Чем я могу вам помочь, господин?', NULL, NULL, 'Список Брокка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6392, 'Возвращение к Броку', 'За небольшую плату грифон отнесет тебя в Телcамар... если ты там уже $gбывал:бывала:. Грифоны могут летать только туда, где ты $gуспел:успела: побывать. Не упускай случая поговорить со всеми укротителями грифонов, и получишь возможность пр$Nеть к ним.$B$BТоргрума, дрессировщика грифонов Телcамара, ты уже $gвидел:видела:, поэтому можешь вернуться к нему. Оказавшись в Телcамаре, отнеси кирки Броку Камнекопу.$B$BКогда решишь тронуться в путь – обращайся ко мне.', 'Заплатите укротителю грифонов Гриту Турдену, долетите на грифоне до Телcамара и отдайте почетные кирки Броку Камнекопу.', 'А вот и кирки. Отлично! Я раздам их своим ученикам. Им, конечно, не терпится пустить их в ход в рудниках возле озера Лок Модан.$B$BБлагодарю за помощь, Чазм. Я у тебя в долгу. Возьми эти деньги, они должны покрыть стоимость перелета.', 'А, $N. Ты уже вернулся из Стальгорна?', NULL, NULL, 'Почетные кирки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6393, 'Война элементалей', 'Совет Приливов послал меня объявить войну элементалям огня здесь, в Каменном Когте. Нептулон Приливный Охотник, повелитель всех элементалей воды, лично заинтересован в том, чтобы узреть погибель всех наших огненных сородичей.$B$B$N, ты можешь помочь мне высоко подняться во мнении Совета путем уничтожения элементалей огня в Обугленной долине. После смерти от этих элементалей остаются огненные кристаллы. Отдай их мне, и ты получишь награду.', 'Принесите 10 Огненных кристаллов Цунаману в приют Солнечного Камня.', 'Духи воды внутри меня булькают от восторга. $N, я высоко ценю твой дар – славную победу, о которой я могу сообщить в Совет Приливов.', 'Совет Приливов проявляет нетерпение. Они желают положить конец войне, которая вот уже не одну эпоху идет во всех измерениях. Мои собратья жаждут услышать новости о грандиозной победе над ненавистными элементалями огня. Где же огненные кристаллы, что так нужны мне?', NULL, NULL, 'Огненный кристалл', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6394, 'Кирка Тазз\'рила', '$N, ты $gдобросовестный:добросовестная:$r. Можно доверить тебе еще одно дело?$B$BНе так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку. А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей! Не можешь ли ты сходить в грот Пылающего Клинка и раздобыть мою кирку?$B$BЯ ее оставил в зале с водопадами. Кирка моя заговоренная – она светится в темноте, так что найти ее будет нетрудно... только, боюсь, ее уже стерегут!', 'Принесите штейгеру Тазз\'рилу его кирку.', 'Она у тебя! Моя любимая кирка! Спасибо большое, $N! Ну, теперь главное – дождаться, когда мои батраки управятся с рубкой леса, – и можно снова искать минералы!', 'Ну что, $N, удалось тебе проникнуть в грот? А кирку мою нашел?', NULL, NULL, 'Кирка Тазз\'рила', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6395, 'Последнее желание Марлы', 'Моя подруга Марла Фиппс жила до чумы со своим мужем Самуэлем, но когда пришла чума, Самуэль погиб... и вступил в ряды Плети. $B$BМарла избежала чумы, но погибла от рук собственного мужа, лишившегося разума. Однако так велика была ее любовь, что последним желанием ее было, чтобы Самуэль был похоронен рядом с ней. $B$BСамуэль Фиппс обитает теперь у разоренного лагеря близ дороги на северо-восток от Могильника. Убей его и выполни желание Марлы: похорони Самуэля в ее могиле, в первом ряду нашего кладбища.', 'Отнесите останки Самуэля Фиппса на могилу Марлы, а затем вернитесь к ученице Элрет.', 'Ты, $N, совершил сегодня доброе дело. Хотя наша борьба против армии Плети продолжается, будем надеяться, что Марла и Самуэль упокоятся с миром.', NULL, NULL, NULL, 'Останки Самуэля погребены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6401, 'Кайя жива!', 'Передай Таммре Перекати-поле, тетушке Кайи, живущей в Приюте у Солнечного Камня, добрые новости – Кайя жива! Мы думали, что она погибла во время того жестокого нападения на нашу деревню. Иди по дороге на запад, и придешь в Приют у Солнечного Камня.', 'Передайте хорошие новости Таммре Перекати-поле, живущей в Приюте у Солнечного Камня.', 'Хвала духам, моя племянница Кайя жива! Это поистине добрая новость. Спасибо тебе, $N!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6402, 'Встреча в Штормграде', 'Вы с Виндзором должны встретиться у ворот Штормграда.$B$BВиндзор расскажет такое, что все королевство содрогнется!$B$BИ не ходи туда $gодин:одна:, $N. Собери целую армию! Позови своих земляков. К оружию!', 'Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии.', 'Пока мы не вступили в бой, собери армию. В конце концов, на дракона идем!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6403, 'Великий Маскарад', 'Вот это было приключение, друг мой. Я перед вами в огромном, неоплатном долгу. Может быть, когда все будет кончено...$B$BКак уже доподлинно установлено вами, Леди Престор – это Ониксия, отродье Смертокрыла, сестра-близнец владыки Черной горы Нефариана.$B$BСлишком долго держала она наше королевство под контролем. Даже сам Верховный лорд – марионетка в ее руках... Это колдовство будет разрушено.$B$BНе надо бойтесь, вместе мы победим!$B$BВы готовы?', 'Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!', '*Болвар держит в руках расколовшийся амулет.*$B$BМагия, содержавшаяся в нем, должна воскреснуть. Око дракона должно быть настроено.$B$BСамопожертвование Виндзора освободило наше королевство, но угроза, исходящая от Ониксии и ей подобных, никуда не делась.$B$BЭтот медальон удерживал в плену мои разум и тело. Он также давал мне доступ к собственному разуму Ониксии – к ее тайнам. Хотя эти воспоминания сейчас как будто в тумане, кое-что я помню.', 'Я... мне... я был бессилен.', NULL, NULL, 'Сопроводите Реджинальда Виндзора.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6421, 'Ущелье Камнепадов', 'Что-то не так здесь, в Каменном Когте. Чувствуешь ли ты непокой, витающий в воздухе, $N?$B$BК юго-востоку отсюда, в ущелье Камнепадов, есть пещера. Там кобольды отчаянно ищут редкие кристаллы резонита. Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере. Помимо того, неплохо бы тебе обследовать глубины этой пещеры.$B$BИди же, $gюный:юная:c: $C, мне очень важно знать, что за зло таится под этими горами.', 'Обследуйте глубины пещеры в ущелье Камнепадов и принесите 10 кристаллов резонита для исследования Мор\'рогалу в Приют у Солнечного Камня.', 'О да! Это оно – кристалл резонита несет следы земной магии. Должно быть, кобольды, докопавшись до глубин, обнаружили там земельника.$B$BЛегенда утверждает, что земельники – это существа, созданные титанами. Именно с их помощью создана земная твердь, по которой мы ступаем. Угроза велика, нельзя не обращать на нее внимания.$B$B*Мор\'рогал качает головой.*$B$BБыть может, я сумею наложить заклинание на эти куски руды, чтобы нарушить затею кобольдов.', 'Какие новости из Ущелья Камнепадов? Я вспомнил, что существует легенда, в которой говорится о резоните... Но не за что ухватиться. Быть может, узнав, что таится на дне пещеры, мы сможем пролить свет на их зловещие намерения.', NULL, NULL, 'Кристалл резонита', 'Исследовать локацию', 'Обследуйте пещеру в ущелье Камнепадов', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6441, 'Рога сатира', 'Привет! Я ехала через Ясеневый лес в Кабестан и решила остановиться здесь, на заставе Расщепленного Дерева. Я никогда не упущу выгодного дельца, а тут оказывается, что рога сатира нынче пользуются в Кабестане большим спросом.$B$BЯ тут поспрошала, и оказывается, что сатиры с Ночной поляны, из Сатирнаара и Ксавиана как раз носят такие рога, что мне надо. Мне эти сатиры не по зубам... но вот тебе – наверняка!$B$BСкажи, сколько возьмешь, добудь мне рога, и я оплачу тебе потраченное время.', 'Добудьте 16 рогов сатира для Пиксель на заставе Расщепленного Дерева.', 'Изумительные рога, $N! Спасибо за помощь!$B$BО, а это вам за труды...', 'Надеюсь, вы поторопитесь добыть мне эти рога, Седативщик. Я скоро возвращаюсь в Кабестан!', NULL, NULL, 'Рога сатира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6442, 'Наги на Зорамском взморье', 'Зло рыщет по побережью, $r.$B$BЗдесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощенный морем. Разрушенный и почти забытый.$B$BТеперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись.$B$BПринеси мне 20 их голов! Загони наг назад, в глубины моря!', 'Принесите 20 голов наг из клана Зловещего Хвоста Марукайе на Зорамское взморье.', 'Побольше бы нам таких, как ты, $N. Спасибо за помощь.', 'Наг все больше и больше, $N. Прошу, сделай это для меня.', NULL, NULL, 'Голова наги из клана Зловещего Хвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6461, 'Кровопийцы', 'Мы, тролли, тут, в Малака\'джине, живем с земли, да и живем хорошо. В Каменном Когте есть на что поохотиться. $B$BТолько вот повадились к нам в последнее время незваные гости... по ночам пауки на наши стоянки нападают, хотят украсть нашу добычу. $B$BЕсли поможешь нам поубивать этих злобных тварей, мы, тролли Малака\'джина, будем перед тобой в долгу. Тут, в Каменном Когте, пауки повсюду – ступай на север, и увидишь, о чем я толкую.', 'Ксен\'Зилла из Малака\'джина просит вас убить 10 моховых ползунов и 7 моховых ядоплюев.', 'О, вот и славненько! Ну хорошо, авось сегодня к нам на ужин меньше незваных гостей налезет.$B$BТысяча благодарностей, $N. Мы у тебя в долгу навечно.', NULL, NULL, NULL, 'Моховой ползун убито', 'Моховой ядоплюй убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6462, 'Оберег троллей', 'Мои сородичи шли сюда со священными тролльскими оберегами, но фурболги Колючего Меха напали на них и перебили прежде, чем они успели добраться до Зорам\'гара! Эти подлые фурболги!$B$BЯ горюю по убитым братьям и сестрам – но мы еще встретимся в загробной жизни. Но их тролльские обереги в нашем мире весьма ценятся. Меня бесит, что ими завладели фурболги!$B$B$N, ты $gдолжен:должна: вернуть эти обереги! Они находятся в сундуках в Крепости Колючего Меха, в пещере на окраине Деревни Колючего Меха, к северу от Астранаара.', 'Принесите 8 оберегов троллей Митсуве в форт Зорам\'гар.', 'Ты их нашел! О, благодарю тебя, $N! Ты представить себе не можешь, что ты сделал для меня. $B$BТролль без оберега что орк без боевых шрамов...$B$BПустое место, а не тролль.', 'Ты нашел обереги, $N? Моя кровь кипит от гнева, что эти священные обереги в руках фурболгов!', NULL, NULL, 'Оберег троллей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6481, 'Пробуждение земельника', 'Благодаря тебе, $C, мы узнали, что этой земле грозит великая опасность. Резонитовая емкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок. $B$BЯ изменил своей шаманской силой принесенные тобой кристаллы. Возьми кристалл резинита и разбей резонитовую емкость, где спит земельник.$B$BСразу после пробуждения Гоггерок будет ослаблен... Убей его, $N!', 'Откройте резонитовую емкость при помощи зачарованного кристалла резонита и затем убейте Гоггерока. Вернитесь к Мор\'рогалу с новостями и зачарованным кристаллом резонита.', 'Это хорошие новости, $С! Я опасался того, что земельник может сделать с Калимдором.$B$BУничтожение Гоггерока было задачей, достойной истинного героя. Но тебе удалось справиться с этим, и теперь и Каменный Коготь, и Калимдор перед тобой в долгу, благородный $С.$B$BПрими это как заслуженную и достойную награду.', 'Я боюсь, что если мы не избавимся от этой угрозы немедленно, весь Каменный Коготь падет. Мощь земельника несравнима ни с какой другой. По пробуждении Гоггерок будет ослаблен долгим сном, и тебе следует воспользоваться этим. Иди же, $N!', NULL, NULL, 'Гоггерок убито', 'Колдовской кристалл резонита (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6482, 'Свободу Руулу!', 'А? Ты кто?$B$B$N? Ты не фурболг. Они прокляты! Они подумали, что я медведь, и схватили меня, а теперь морят голодом! Я погибаю...$B$BПомоги мне сбежать, затем поговори с моей сестрой Ями на заставе Расщепленного Дерева к востоку отсюда.$B$B$N! Мне надо сбежать!', 'Сопроводите Руула, затем поговорите с Ями Снежное Копыто на заставе Расщепленного Дерева.', 'Ты нашел моего брата! Его схватили фурболги Колючего Меха? Какая страшная весть! Хотя многие фурболги существа благородные, эти – извращенные твари.$B$BСпасибо за спасение брата, $N. Страшно подумать, как они обходились с бедняжкой Руулом! Наверняка после таких испытаний он будет долго спать...', NULL, NULL, NULL, 'Выведите Руула за пределы владений Колючего Меха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6501, 'Око дракона', 'Фрагмент расколотого амулета – это все, что я могу вам предложить.$B$BВам придется найти еще одного дракона, который согласится помочь вам в изготовлении нового ключа. Как только вы добудете этот ключ, вам нужно будет отправиться в Драконьи топи в Пылевых топях. Там вы и найдете ее логово, $N.$B$BГде найти других драконов, готовых помочь? К сожалению, я не знаю... Говорят, что такие существуют. Некоторые из них могут даже жить среди нас в обличии людей, гномов или эльфов, например. Желаю вам удачи в поиске.', 'Найдите существ, способных вернуть силу фрагменту амулета Око Дракона. Все, что об этих существах известно – это то, что они есть.', 'Я должна была догадаться – часть плоти царицы черных драконов, Ониксии. Какая мерзость…', 'Я чувствую, что ты излучаешь недобрую ауру, $C. Что у тебя может быть с собой такого, что обладало бы такой аурой?', NULL, NULL, 'Фрагмент амулета Око Дракона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6502, 'Амулет Пламени дракона', 'Это – заколдованная драконья чешуя. Целая чешуйка открывает проход в драконье логово, а в сломанном виде она бесполезна.$B$BЕе можно починить, но для этого требуется кровь могучего черного дракона. Есть один такой... Его зовут генерал Драккисат, он возглавляет армию драконидов Нефариана. Тебе доводилось о нем слышать?$B$BВозвращайся с его кровью, $r, и я наложу чары на этот осколок. Тогда ты сможешь проникнуть в Логово Ониксии.', 'Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы.', 'Этот амулет поможет тебе достичь цели. Гнездо Ониксии ты найдешь в Пылевых топях. Пока амулет с тобой, ее стражи не смогут препятствовать тебе.$B$BСиние драконы желают тебе удачи, $N.', 'Река времени никогда не прекращает и не замедляет свой бег, $R. Моя жизнь бесконечна, но твоя – нет. Не теряй даром времени...', NULL, NULL, 'Кровь могучего черного дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6503, 'Вестницы Ясеневого леса', 'Мы получили донесение, что вестницы Ясеневого леса не так давно покинули Аванпост Среброкрылых и теперь шныряют в лесу у наших границ. Нам не надо, чтобы они разнюхивали что да как с нашей обороной!$B$BПроникни в лес к югу отсюда и к востоку от альянсовского Аванпоста Среброкрылых. Найди и перебей лазутчиц, а потом возвращайся.', 'Убейте 9 вестниц из Ясеневого леса, а затем вернитесь к Курай\'бину на заставу Расщепленного Дерева.', 'Очень хорошо, $N. Твое охотничье мастерство впечатляет...$B$BПотеря лазутчиц малость притупит нюх Альянса, а ежели им разведданных не хватит, то вряд ли они нападут.', 'Жду отчета о деле с лазутчицами, $N.', NULL, NULL, 'Вестница Ясеневого леса убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6504, 'Утраченные страницы', 'Этот крошшер я только что получила из Кабестана и как раз возвращалась на лесозаготовки Песни Войны, на свое рабочее место. Мне дали нструкцию к крошшеру, но по дороге назад у меня ее вырвало из рук порывом ветра. Все страницы разлетелись, и осталась у меня одна обложка.$B$BГде теперь эти страницы носит, одним предкам ведомо... Но как я резаком-то без них пользоваться буду? Не найдешь ли их для меня?', 'Найдите 12 пропавших страниц руководства по использованию резака и соберите их по порядку глав 1, 2 и 3. Верните страницы Гурде Печати Гнева близ заставы Расщепленного Дерева.', 'Не сильна я в чтении... Но теперь я могу вернуться к работе! Спасибо, $N!', 'Надеюсь, ты быстро найдешь эти страницы, $N! Мне очень надо скорее вернуться к работе!', NULL, NULL, 'Руководство пользователя крошшера - Глава 1', 'Руководство пользователя крошшера - Глава 2', 'Руководство пользователя крошшера - Глава 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6521, 'Нечестивый союз', 'Повелеваю тебе убить посланника Малкина – я не позволю ему выполнить волю Короля-лича. Он пишет, что ждет встречи где-то поблизости от Курганов Иглошкурых.$B$BЕго присутствие там многое объясняет. Сила тамошних иглогривов многократно увеличилась, и среди них отмечаются признаки чумы. Очевидно, они заключили с Малкином какое-то соглашение.$B$BНайди и убей Малкина, $N. Возвращайся ко мне, когда исполнишь мое повеление.', 'Принесите голову посла Малкина Брагору Кровопалу в Подгород.', 'Прекрасно. Ты хорошо поработал, $C. $B$BТеперь, после смерти Малкина, мы по крайней мере можем быть уверенными, что продвижение Плети будет остановлено. В благодарность за преданность прими этот дар.$B$BПока нам неизвестно, насколько прочные позиции заняла Плеть в Лабиринтах Иглошкурых, однако не сомневаюсь, что скоро нам удастся разузнать их замыслы.', 'Ты нашел посланника, $N? Надеюсь, он мертв? Мы не можем позволить Плети закрепиться в Калимдоре. Довольно и того, что они постоянно осаждают наши границы – не хватало еще отбиваться от них на двух фронтах! Единственное, что радует меня в принесенных тобой вестях, – что старая ведьма, похоже, не подверглась скверне. В глубине души она понимала, что Плеть может наделить ее огромной властью, и все же осознавала, что, заключи она союз с нежитью, Степи перестанут быть ее истинной вотчиной.', NULL, NULL, 'Голова посланника Малкина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6522, 'Нечестивый союз', 'Госпожа моя!$B$BНаше предложение вам прекрасно известно. Для вас это отличная возможность получить безграничную власть над Степями и окрестными землями. От вас нам требуется лишь небольшое содействие – дайте нам свободу действий в этих землях.$B$BМы убедительно просим вас рассмотреть это предложение. Мы обладаем великой силой и охотно поделимся ею с тем, кто достаточно мудр, чтобы примкнуть к нам. Я буду ждать вас у Курганов Иглошкурых.$B$BС наилучшими пожеланиями,$BПосланник Малкин.', 'Отнесите маленький свиток Брагору Кровопалу в Королевский квартал Подгорода.', 'Я узнаю знак на этом свитке, $N. Говоришь, нашел это у старухи, правящей в Лабиринтах Иглошкурых? Любопытно. $B$BПохоже, Плети мало одного континента. Посол Малкин – тот, кто написал письмо, – один из служителей Плети. Он был человеческим послом в Лордероне, прежде чем... все переменилось. $B$BЕсли Плеть в самом деле пытается закрепиться в Калимдоре, нам пора что-то предпринять.', 'С чем пожаловал, $N? Надеюсь, это действительно важное дело – я не люблю, когда мне докучают по пустякам.', NULL, NULL, 'Маленький свиток (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6523, 'Защита Кайи', 'Спасибо большое за спасение! Мы должны уходить побыстрее, прежде чем они обнаружат, что я на свободе. Я прошу сопроводить меня до Лагеря Апарахе. Оттуда я уже знаю, куда идти.$B$BМой отец, Макаба Плоское Копыто, наверное, уже отчаялся узнать, где я.', 'Проводите Кайю Плоское Копыто до Лагеря Апарахе, затем вернитесь к Макабе Плоскому Копыту, находящемуся поблизости от юго-восточного края Каменного Когтя.', 'Кайя жива! $N, я благодарю тебя за ее спасение!', NULL, NULL, NULL, 'Кайю проводили до Лагеря Апарахе.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6541, 'Донесение Кадраку', 'Ты когда-нибудь $gбывал:бывала: в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ.$B$BЕсли тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.', 'Доложитесь Кадраку в сторожевой башне в северных Степях.', 'Ясеневый лес – разделенный войной край, но наши недавние усилия увенчались успехом. Мы основали заставу не только на Зорамском взморье, но еще прямо к северу отсюда построили заставу Расщепленного Древа.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6542, 'Донесение Кадраку', 'Ты когда-нибудь $gбывал:бывала: в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ.$B$BЕсли тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.', 'Доложитесь Кадраку в сторожевой башне в северных Степях.', 'Ясеневый лес – разделенный войной край, но наши недавние усилия увенчались успехом. Мы основали не только заставу на Зорамском взморье, но и еще прямо к северу отсюда построили заставу Расщепленного Древа.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6543, 'Отчет клана Песни Войны', 'Недавно я отправил в Ясеневый лес нескольких разведчиков. Мне нужен гонец, чтобы доставить им приказы и вернуться с отчетом об их наблюдениях.$B$BПервый твой пункт – форт Зорам\'гар, что на западном побережье на Зорамском взморье. Там ты найдешь первого гонца. Так же тебе придется заглянуть на заставу Расщепленного Дерева, что на севере и к востоку по дороге близ Азшары. Там найдешь разведчика и сопровождающего.$B$BПередай каждому указания и забери у них новые донесения.', 'Распакуйте связку донесений. Доставьте отчеты клана Песни Войны разведчику, гонцу и всаднику из клана Песни Войны. Возьмите у них новые донесения для Кадрака и доставьте ему в северную сторожевую башню в Степях.', 'Вижу, на тебя можно положиться. Эти новые сведения чрезвычайно важны для осуществления планов по расширению нашего присуствия в Ясеневом лесу. Теперь мы можем разработать следующий шаг.', 'Торопись, $N. Они должны получить указания, это срочно.', NULL, NULL, 'Сведения разведчика из клана Песни Войны', 'Сведения гонца из клана Песни Войны', 'Сведения всадника из клана Песни Войны', 'Связка донесений');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6544, 'Налет Торека', 'Эй! $C! Иди-ка сюда!$B$BМы с ребятами хотим напасть на аванпост Среброкрылых на западе. Наша цель – их командир, Дариэль Лунное Пламя. Разведчики говорят, что форт здорово защищен, там полно часовых и воинов. Славная будет драка!$B$BХочешь помочь нам, $N, и разделить нашу славу? Если пойдешь с нами, то когда победим, сможешь доложить о наших успехах моему начальнику, Эртогу Лютоклыку. Ты найдешь его на заставе Расщепленного Дерева.$B$BЧто скажешь? Пойдешь с нами?', 'Сопровождайте Торека при нападении на аванпост Среброкрылых и в сражении с Дариэлем Лунным Пламенем, затем поговорите с Эртогом Лютоклыком на заставе Расщепленного Дерева.', 'Значит, Тореку дельце удалось! Хорошая работа, $N. Ночные эльфы – достойные враги. Худоваты на вид, но сильные да яростные! Видать, драка была красивая, посмотреть бы... $B$BНадеюсь, парочку шрамов-то ты заработал?', NULL, NULL, NULL, 'Займите Аванпост Среброкрылых.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6545, 'Сведения гонца из клана Песни Войны', '', '', 'Что же, в моих последних донесениях Кадраку все подробно описано. Возвращайся к нему как можно быстрее.', NULL, NULL, NULL, 'Отчет клана Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6546, 'Сведения всадника из клана Песни Войны', '', '', 'Доставь мое донесение Кадраку, $N. И побыстрее.', NULL, NULL, NULL, 'Отчет клана Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6547, 'Сведения разведчика из клана Песни Войны', '', '', 'Передай Кадраку, что мы тут успешно сдерживаем ночных эльфов. Все идет согласно плану.', NULL, NULL, NULL, 'Отчет клана Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6548, 'Отомсти за мою деревню', 'Племя Зловещего Тотема напало на мою деревню и убило почти всех ее жителей. Я сразил столько нападавших, сколько мог, но едва спас собственную жизнь.$B$B$N, всё, чего я желаю – это чтобы как можно больше этих негодяев умерло. Ты найдешь их к западу отсюда.', 'Убейте 8 бузотеров и 6 наемников из племени Зловещего Тотема, затем вернитесь к Макабе Плоскому Копыту, ожидающему вас на юго-восточной границе Когтистых гор.', '$N, я благодарю тебя... но я никогда не забуду того, что клан Зловещего Тотема сделал с моей деревней.', 'Тебе удалось их убить?', NULL, NULL, 'Бузотер из племени Зловещего Тотема убито', 'Наемник из племени Зловещего Тотема убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6561, 'Злодейство в Непроглядной Пучине', 'Силы оставили меня. Мне необходима твоя помощь!$B$BВ давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный лунный колодец.$B$BАку\'май, слуга Древнего бога, поднялся из глубин.$B$BСектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку\'май невинные жертвы.$B$BУбей Келриса и принеси его голову Башане в Громовой Утес, $N.', 'Принесите голову Повелителя сумрака Келриса Башане Рунический Тотем в Громовой Утес.', 'Келрису много раз удавалось ускользнуть от Серебряного Рассвета. $B$BЕго считали мертвым или пропавшим без вести.$B$BПоложив конец его власти, ты спас жизнь многих, $N. $B$BСлава Матери-Земле! Нет прощенья тем, кто приносит невинные жертвы Древнему Богу! $B$BТы совершил великий подвиг, $N. Келрис был порождением зла, он стремился повергнуть наш мир в хаос, поклоняясь Старым Богам. Благодарю тебя, $N.', 'Да пребудет с тобой милость Матери-Земли, $N. $B$BМы должны стремиться к гармонии и согласию во всем мире. Все происходит по воле Матери-Земли, и все мы – орудия в ее руках.', NULL, NULL, 'Голова Келриса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6562, 'Угроза из Глубин', 'Дже\'неу Санкри нужна помощь. Он в форте Зорам\'гар в Ясеневом лесу. Этот лес ночных эльфов находится к северу от Когтистых гор. Ты можешь добраться до него через Утес Ветрорезов или идя на север через Степи. Зорамское взморье лежит далеко на западе от леса. Будь $gосторожен:осторожна:, $N. Там обитают такие силы, от которых теплого приема не жди.', 'Поговорите с Дже\'неу Санкри в Ясеневом лесу.', 'Тебя послал Цунаман? Великолепно. Тогда нам есть что обсудить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6563, 'Сущность Аку\'май', 'В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы. Недавно было замечено, что эти кристаллы собирают наги. Пока не станет ясно, зачем им это, сдается мне, что надо наг этой возможности лишить. В кристаллах этих содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом.$B$BТы мне не поможешь, $N? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы.', 'Принесите 20 сапфиров Аку\'май Дже\'неу Санкри в Ясеневый лес.', 'Хорошая работа, $N. Это те самые кристаллы, о которых я говорил. Как интригующе...$B$BЯ чувствую в них силу. К ним тянутся духи воды. Для чего бы наги ни собирались их использовать... Ладно, хорошо, что они больше не в их руках.', 'Как поиски кристаллов, $N? Ты видел, как наги их собирают? Я молю своих предков, чтобы нам удалось понять, зачем им это.', NULL, NULL, 'Сапфир Аку\'май', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6564, 'Верность Древним богам', 'На смятом обрывке бумаги кое-как нацарапано:$B$B\"Да, вели всем жрицам приносить мне эти кристаллы. В них обитают могучие духи элементалей воды, и они весьма помогут нашим аквамантам в призывании духов.$B$BОвладев силой, заключенной в кристаллах, мы сумеем умилостивить Аку\'май. И однажды настанет день, когда мы накопим достаточно сил, чтобы вернуть Аку\'май к нам, и мир вернется в величайшую свою эпоху! Эпоху власти Древних богов!\"', 'Принесите отсыревшую записку Дже\'неу Санкри в Форт Зорам\'гар в Ясеневый лес.', 'Это и правда интересно. Я рад, что ты принес мне эту записку.$B$BТеперь мы знаем, как зовут причину наших бед... Лоргус Джетт!', 'Да, $N? В чем дело? Мне еще многое нужно узнать об этих кристаллах, что собирают наги.', NULL, NULL, 'Отсыревшая записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6565, 'Верность Древним богам', 'Мы не можем допустить, чтобы этот последователь Сумеречного Молота выполнил свой план. Клан Сумеречного Молота не понимает духов Природы. Они верят в Древних богов – богов хаоса и разрушения, побежденных давным-давно. Нельзя дать этому Лоргусу добиться своего! Ты $gдолжен:должна: оставновить его, $N. Мне самому этого не сделать – я слишком слаб.$B$BСтупай в Непроглядную Пучину, найди и убей его! А потом возвращайся в Зорам\'гар.', 'Убейте Лоргуса Джетта в Непроглядной Пучине и вернитесь к Дже\'неу Санкри в Ясеневый лес.', 'Прекрасно!!! Хвала тебе, $N. Может, мы и не окончательно разобрались с Сумеречным Молотом, но по крайней мере один их план по возвращению в могуществе своем Древних богов мы нарушили.$B$BКто знает, какие еще замыслы них на уме, но пока мы можем вздохнуть свободно.', 'Ты еще не нашел его, $N? Лоргуса надо остановить!', NULL, NULL, 'Лоргус Джетт убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6566, 'Что принес ветер', 'Рад видеть тебя снова, $N. Ветер принес вести из Восточного королевства.$B$BСадись и слушай.', 'Выслушайте Тралла.', 'Готов ли ты взять на себя эту задачу?', 'Терпение, $N. Слушай внимательно!', NULL, NULL, 'Выслушайте Тралла.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6567, 'Герой Орды', 'Рексар, один из самых преданных моих защитников, нашел путь в логово дракона. Однако он покинул Азерот, чтобы присоединиться к экспедиции в Запределье.$B$BОн оставил в деревне Ночных Охотников своего товарища Рокаро, который тоже знает этот путь. Отыщи его.', 'Найдите Рокаро в деревне Ночных Охотников в Пустошах.', 'В драконье логово можно проникнуть только одним способом.$B$BНу, разумеется, если ты не почетный член их клана.$B$BНо и тогда тебе пришлось бы пройти немало испытаний и получить ключ, заколдованный самим генералом Драккисатом.$B$BНо раз уж ты не черный дракон, все будет несколько сложнее.$B$B<Рексар ухмыляется.:', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6568, 'Мастерица обмана', 'Иллюзия и маскировка: вот два способа, которые помогут тебе обмануть черных драконов и добыть то, что ты ищешь.$B$BКонечно, я тоже мог бы преподать тебе некоторые уроки в искусстве обмана, но здесь тебе понадобится помощь мастера.$B$BЯ знаю, кто смог бы тебе помочь. Тебе нужно отправиться в Западные Чумные земли и разыскать там Миранду Колдунью: когда-то она была мастером иллюзий Лордерона. В прошлом Миранда не раз помогала нам; она поможет и тебе, если сочтет твои цели достойными.$B$BВот, отнеси ей это послание.', 'Доставьте письмо Рокаро Миранде Колдунье в Западные Чумные земли.', '<Миранда берет записку и через некоторое время улыбается.>$B$BКак он? Я про Рексара. Ой, к чему удивление? Письмо не просто так оставлено пустым. Ведь главное – это мысли и поступки того, кто его отправил. Да и, судя по обстоятельствам, Рексар не мог ничего написать. Представь, если бы тебя поймали или убили, и важная информация досталась бы врагу!$B$BНо все хорошо. Миранда поможет тебе, нежить. У меня должок перед вождем.$B$B<Миранда улыбается.>', 'Нечасто приходится видеть выходцев из Орды в этой части Лордерона. Ну, с чем же ты пришел к Миранде?', NULL, NULL, 'Письмо Рокаро (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6569, 'Иллюзии Ока', 'Значит, $r $gвозжелал:возжелала: войти в Черное Племя?$B$BСоздать необходимую тебе иллюзию - пара пустяков. Куда труднее собрать компоненты, необходимые для наложения этих чар. Раз Вождь поручил тебе такую миссию, Миранде остается повиноваться.$B$BОтправляйся в верхнюю часть крепости на пике Черной горы и убей столько черных драконидов, чтобы набить заплечные мешки их глазами.$B$BКогда наберешь достаточно, возвращайся к Миранде.', 'Отправляйтесь на пик Черной горы и добудьте 20 глаз черных драконоидов. По выполнении задания вернитесь к Миранде Колдунье.', 'Дай-ка Миранде посмотреть, $R.$B$BО, да, отличные глаза.$B$BТеперь Миранда сделает для тебя медальон, который создаст иллюзию, при помощи которой ты сможешь обмануть привратника Черного Племени.', 'Самое главное для создания любой иллюзии – глаза тех, кого мы хотим изобразить, $N.$B$B*Миранда указывает на мешок, до отказа набитый глазами. Надпись на нем гласит \"Алый орден\".*$B$B*Миранда хохочет.*', NULL, NULL, 'Глаз черного драконида', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6570, 'Огнебор', 'Благодаря этому медальону в пределах логова Огнебора ты будешь сохранять нужный облик.$B$BОгнебор – старый дракон, древний привратник Нефариана. На него возложена обязанность испытывать тех драконов, которые должны войти в элитную стражу Ониксии.$B$BОтправляйся в Драконьи топи в Пылевых топях и войди в его логово. Оказавшись внутри, надень амулет, и следуй за своей судьбой!', 'Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором.', 'Неужели у нас иссякли хорошие бойцы? Зачем Нефариан присылает мне детенышей? Тебе не пройти испытания, мелочь пузатая.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6571, 'Поставка для клана Песни Войны', 'Нам на лесозаготовках Песни Войны страшно не хватает кое-чего!$B$BУ Пиксель на заставе Расщепленного Дерева наш груз лезвий для пил. За ящиком топоров от управляющего пристанью Подгребая придется сгонять в Пиратскую Бухту. $B$BА получить груз масла и веревок будет еще труднее. Веревку стянули фурболги из племен Колючего Меха и Гиблой Чащи, а сатиры перехватили партию масла, и теперь изводят его на свои гадкие ритуалы на Ночной поляне, в Сатирнааре и Ксавиане!$B$BТы мне поможешь?', 'Соберите полностью поставку Песни Войны: лезвия для пил, веревку для бревен, масло и партию топоров Песни Войны для Локе Окарра на заставе Расщепленного Дерева.', 'Замечательно, $N! Ты избавил меня от больших забот!$B$BНо не думай, что я буду неблагодарен!', 'Надеюсь, ты с грузом? У меня будут большие неприятности, если я не доставлю все как можно скорее!', NULL, NULL, 'Пилы клана Песни Войны', 'Партия топоров клана Песни Войны', 'Масло клана Песни Войны', 'Погрузочная веревка');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6581, 'Пилы клана Песни Войны', '', '', 'Само совершенство – то, что надо! Ладно, вот груз.', NULL, NULL, NULL, 'Смертоносный мушкетон', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6582, 'Черепа: Провидец', 'Все мы дети Смертокрыла, ничтожество. И наша власть над младшими аспектами должна укрепиться.$B$BЕсли ты действительно $gдостоин:достойна: возвышения, то другие драконы должны дрожать от одних звуков твоего имени. Найди их вожаков и сокруши во имя нашего Отца!$B$BОтправляйся в Зимние ключи и найди там дракона по имени Провидец. Убей его и любого синего дракона, кто осмелится встать на твоем пути, и принеси мне его череп.', 'Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору.', 'Одно исссс нессскольких ссаданий иссполнено...', '*Огнебор шипит*', NULL, NULL, 'Череп Провидца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6583, 'Черепа: Сомнус', 'Наш отец сокрушил самих Аспектов, а наш долг – сеять хаос и страх среди их детей.$B$BТы $gдолжен:должна: показать свою боевую мощь бессонно грезящим. Я говорю о зеленых драконах.$B$BОтправляйся на Болото Печали и порази Сомнуса, избранного бойца зеленых драконов. Не сдерживай своей ненависти, раздави его, как червяка, и вернись ко мне с его черепом.', 'Убейте избранного бойца зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору.', 'Еще один мертв...', 'Не смей возвращаться, пока не омоешь рук в крови наших врагов и не упьешься их страданиями.', NULL, NULL, 'Череп Сомнуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6584, 'Черепа: Хроналис', 'Дозорные Времени, дети Ноздорму – Повелителя Вечноссссти...$B$BТрое из них охраняют Пещеры Времени, но только один из этих троих представляет интерес для черных драконов: Изменяющий время Хроналис, любимый отпрыск Нодзорму. Расправьсссся с ним так, чтобы даже песок в его часах рыдал от ужаса, и вернись ко мне с его черепом.', 'Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору.', 'Оссталссся только один... Самый ненависссстный...', 'Забавно, не правда ли, птенчик? Время как оно есссть...', NULL, NULL, 'Череп Хроналиса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6585, 'Черепа: Акстроз', 'Над горами Грим Батола отец наш бился против объединенных сил Аспектов. Но коварное предательство Алекстразы дало им возможность избежать его гнева.$B$BПосссзорное пятно на иссстории нашшшего рода.$B$BТеперь Грим Батол стерегут красные драконы. Их военачальник Акстроз должен быть убит, а его череп доставлен мне. Вперед, птенчик! За нашего Отца!', 'Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору.', 'Я сомневался, стоишь ли ты посвящения, птенчик. Но ты выказал немалое упорство, побеждая наших врагов и добывая честь нашему роду. Теперь я должен подготовить черепа для твоего возвышения.', 'Я вижу в тебе ссследы перемен, птенчик. Ты прошшел иссспытание, осстался один обряд.', NULL, NULL, 'Череп Акстроза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6601, 'Вознесение', 'Из черепов наших врагов сделан медальон. Ты его ссснаешшь, не правда ли? Ты несомненно $gвидел:видела: его на ваших старейшинах.$B$BВозьми его, птенчик, отнеси на Пик и отдай генералу Драккисату. Генерал наложит на него последнее заклятье, чтобы настроить амулет на тебя.$B$BТы будешь носить его как знак доблести, обозначающий твою принадлежность к одному из самых привилегированных слоев нашего общества, Защитникам Царицы Драконов.$B$BИди же!', 'Казалось бы, загадка разгадана. Вы знаете, что амулет Обмана Драконов, который сделала для вас Миранда Колдунья, не будет работать на пике Черной горы. Найдите Рокаро и расскажите о ваших затруднениях. Покажите ему амулет Угасающего Пламени Дракона. Будем надеяться, он знает что делать.', 'Пара медных грошей стоят больше чем вся эта драконья болтовня, $N. На твоем месте, я не придавал бы столько значения их словам, некоторое хвастовство присуще всему их роду.', '$N! Без паники!', NULL, NULL, 'Амулет угасающего пламени дракона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6602, 'Кровь могучего черного дракона', 'Как насчет того, чтобы нанести визит генералу? На этот раз - никаких иллюзий и прикрытий.$B$BЦеремония?.. Весьма изящное определение для той кровавой бойни, которой так любят услаждать себя черные драконы.$B$BВсе, чего недостает этому амулету - кровь генерала Драккисата. Весьма примитивная защита. Я расскажу тебе, как разрешить эту маленькую проблему.$B$BОтправляйся к пику Черной горы и прикончи Драккисата. Принеси мне его кровь, и я активирую ключ от Логова Ониксии.', 'Отправляйтесь к пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рокаро.', '<Рексар ухмыляется.>$B$BЭту победу будут помнить много лет, можешь мне поверить, $N. Амулет Пламени Дракона отркоет тебе путь в Логово Ониксии. Собирай своих союзников: я верю, ты принесешь Орде новую победу!', 'Драккисата не так легко победить, $N. Об этом могли бы свидетельствовать тысячи, павшие по его вине...', NULL, NULL, 'Кровь могучего черного дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6603, 'Сложности в Зимних ключах!', 'В Зимних ключах какая-то заваруха!$B$BЯ некоторое время жила в тех диких местах и в этих вещах разбираюсь... Я всегда с гордостью это говорю. По мне, так время, что я прожила в холмах, прямо-таки золотое времечко. Помогает развивать быстроту рефлексов, сохранять холодную голову и держать ухо востро...$B$BЧтобы так разбираться в ситуации в диких краях, как я, надо быть зрелым и иметь хорошие мозги.$B$BЛадно, о чем, бишь, я?$B$BА, да, заваруха. Найди Донову Снегонору у горячих источников, и она расскажет тебе побольше.', 'Найдите Донову Снегонору у горячего источника в Зимних ключах.', 'О, привет! Значит, Мегги рассказала тебе о моих трудностях?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6604, 'Взбесившиеся дикие совухи', 'Вы заметили заброшенный лагерь к югу отсюда? Такое впечатление, что дикие совухи сошли с ума и уничтожили все, до чего смогли дотянуться! $B$BЯ слыхал, что один из выживших после этой атаки сейчас приходит в себя в деревне Звездопада, к западу отсюда. Мне очень любопытно, что же там произошло... а вам нет?', 'Поговорите с Джероном Гранильщиком в деревне Звездопада.', 'Слушаю, чем могу быть полезен?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6605, 'Странная дамочка', 'Я только что вернулся из Оскверненного леса, $N. По пути я останавливался на заставе Отравленной Крови, и познакомился с одной очень странной дамочкой… Казалось, она зациклилась на одной вещи и, полагаю, я мог бы сказать, на чем именно, но думаю, лучше она сама тебе это объяснит. $B$BЕсли тебе интересно, отправляйся на заставу Отравленной Крови, в западной части Оскверненного леса и поищи Винну Хеззард.$B$BКто знает, может быть, ей нужна твоя помощь...', 'Поговорите с Винной Хезард в Оскверненном лесу.', 'О, $C. Вижу, еще есть надежда. Ты здесь, чтобы мне помочь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6606, 'Немного удачи', 'Немного удачи никому не помешает, так ведь? Иногда даже крошечного преимущества достаточно, чтобы обратить все в свою пользу...$B$BНедавно мне довелось познакомиться с одной довольно эксцентричной особой. Она сделала мне особый талисман на удачу... не бесплатно, разумеется. Но, поверь уж мне, он того стоит!$B$BМожет, тебе тоже такой нужен? Найди знахарку Мау\'ари в Кругозоре. Свой я тебе не отдам!', 'Поговорите со знахаркой Мау\'ари в Кругозоре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6607, 'Нат Пэгл, великий рыболов', 'Не скажу, что мне так уж нравится рыбачить. Последний раз мне этим приходилось заниматься 20, а то и 30 лет назад. $B$BЛюди занимаются своим делом по разным причинам.$B$BЯ не говорю, что ты $gдолжен:должна: убить на рыбалку 30 лет, или выловить всю рыбу в этом море, чтобы стать хорошим рыбаком. Я думаю, тебе просто надо собраться и решиться несколько часов просиживать зад на берегу, ничего не делая.$B$BВот что я тебе скажу, поймай мне несколько редких рыб из этого списка, и я взамен научу тебя кой-чему.', 'Поймайте для Ната Пэгла следующих рыб:Махи-махи с берега Туманных Тростников на Болоте Печали. Ударник Сартериса с побережья Сар\'Терис из Пустошей.Фералас-ахи из реки Вердантис из Фераласа.Синий плавник Гибельного берега из Тернистой долины.По выполнении вернитесь к Нату Пэглу.', 'Вот это, я понимаю, улов!$B$BПоди сюда, дай-ка я тебе покажу пару трюков.', 'Ну как, сегодня клев был?', NULL, NULL, 'Фералас-ахи', 'Махи-махи с Тростникового берега', 'Ударник Сартериса', 'Синий плавник Гибельного берега');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6608, 'Больше учить нечему', 'Лумак больше не может тебя учить, $N. Нечему больше учить тебя. Найди друга Лумака, Ната Пэгла. Он человек, не еда! Нат друг Лумака! Он тебя научит ловить рыбу лучше.$B$BНата можно найти в Пылевых топях, к югу от Тераморо... как его там. Он, наверное, удит рыбу. Иди!', 'Похоже, Лумак хочет сказать, что ему больше нечему вас учить. Возможно, стоит найти его друга Ната Пэгла – человека, который удит рыбу на островах к югу от Терамора. Кажется, Лумак имеет в виду именно это.', 'Так ты че, друг Лумака?$B$BРыбная ловля? Чего я о ней не знаю, того и знать не стоит!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6609, 'С меня больше нечего взять!', 'Я же дворф, $gпарень:подруга:, это ж без очков видать! Не мое дело рыбу ловить! Ты только глянь на меня! Я ж, считай, каменный!$B$BС меня больше нечего взять – все тебе отдал! Я тебя научил всему, что умел, балда!$B$BЕще не $gпонял:поняла:? А, да ладно. Есть у меня старый дружок в Калимдоре, который сможет тебе помочь. Его зовут Нат Пэгл, он хороший парень. Ищи его на островах к югу от Терамора. Ну, топай!', 'Отправляйтесь в Калимдор, в приморский город Терамор. Там к югу от города найдите остров. Нат Пэгл уже ждет.', 'У меня на островке всегда найдется место для гостей... Насколько помню...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6610, 'Мидии с сюрпризом', 'Тебе случалось слышать о мидиях с сюрпризом? Конечно же нет! Это мой последний кулинарный шедевр. Ах, от одной мысли слюнки текут.$B$BК сожалению, у меня кончились все припасы, и я не могу его сделать! Хочешь сделку? Принеси мне нужные продукты, а я поучу тебя готовить, и даже дам парочку омлетов с мидиями! $gСогласен:Согласна:?$B$BВот что мне нужно:', 'Могиль Быстроруб поручил принести ему следующее:10 гигантских яиц. Их можно отыскать у рухов Танариса или других крупных птиц.10 кусков острого мяса моллюсков. Разумеется, его добывают из раковин моллюсков!20 кусков альтеракского сыра. Из сыроварни!Собрав все составляющие, возвращайтесь к Диргу.', 'Вот ты полакомишься, $N. Смотри и учись!$B$B*Дирг начинает готовить мидии с сюрпризом.*', 'Мне скоро конец придет от голода! Быстрей, $N – а то мне придется залезть в собственную заначку.', NULL, NULL, 'Гигантское яйцо', 'Острое мясо моллюска', 'Альтеракский сыр', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6611, 'Ступай в Прибамбасск!', 'Как может Замджа научить тебя всему на свете? Ты знаешь все кулинарные заговоры Замджи и требуешь новых!$B$BЗамджа ничем помочь не может. Пусть $gтолстый:толстая:$r пойдет в Прибамбасск. Найдешь там мелкого гоблина по имени Могиль – вот он тебе и поможет, обжора.$B$BКогда станешь великим поваром – вернешься, научишь Замджу всему, что знаешь, а? Ну, ступай, ступай.', 'Отправляйтесь в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом.', '*Дирг выплевывает ошметки кожаной сандалии.*$B$BОх! Фу! Тьфу!*Дирг долго откашливается.*$B$BВ чем дело? Ты разве не знаешь, что в коже очень много белка и чрезвычайно мало углеводов? Ничего, узнаешь еще!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6612, 'Я знаю одного парня...', 'Судя по твоему половнику, ты знаешь, чего хочешь. Да вот научить мне тебя нечему.$B$BНо тебе свезло, я знаю одного парня. Он гоблин, и считается первым поваром Калимдора.$B$BДа, $gприятель:подруга:, придется тебе податься до Калимдора. Иди-ка в Прибамбасск и сыщи Могиля Быстроруба. Он тебя прямиком и направит.', 'Пойдите в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом насчет продвижения в поварской карьере.', '*Дирг выплевывает кожу.*$B$BТьфу...$B$B*Дирг громко кашляет.*$B$BНу? Известно ли тебе, что в коже чрезвычайно много белка и мало углеводов, $R?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6621, 'Король Гиблой Чащи', '$N, к юго-востоку от Астранаара живет еще одно племя фурболгов, Гиблая Чаща. Они не так многочисленны, как Колючий Мех, но их ярость в будущем может представлять угрозу. Продемонстрировав им силу, мы сможем эту угрозу ликвидировать.$B$BБери этот штандарт, иди в деревню Гиблой Чащи и поставь его на их тотемном кургане. Они попытаются уничтожить штандарт, но ты держись, пока не появится их вождь, Мургут. Он захочет отстоять честь племени. Принеси мне тотем, что будет на нем.$B$BСобирай друзей, $N. С этим делом $C-одиночка не справится.', 'Водрузите знамя Каранга на тотемном кургане Гиблой Чащи. Не дайте фурболгам уничтожить знамя. Одолейте вождя Мургута и принесите тотем Мургута Карангу Амаккару в Зорам\'гар.', 'Хорошая работа, $N. Бросив вызов Гиблой Чаще и победив их вождя, ты крепко вдолбил в их головы:$B$BС Ордой шутки плохи.$B$BТеперь это племя долго не осмелится досаждать нам.', 'Ты победил вождя Мургута, $N? принес его тотем Гиблой Чащи?', NULL, NULL, 'Тотем Мургута', 'Знамя Каранга (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6622, 'Очередь на медобслуживание', 'Добрый день, доктор. Вы должны будете пройти тест на оказание срочной медицинской помощи. Если тест будет пройден успешно, вы вольетесь в ряды наших лучших травматологов.$B$BА теперь внимание! Раненые, находящиеся в критическом состоянии, должны получить помощь первыми. После критически раненых следует перевязать тяжелых пациентов. Потом можно заняться и обычными ранеными. Для прохождения теста вам нужно спасти 15 пациентов. Если 6 пациентов умрут, так и не дождавшись перевязки, испытание будет провалено.$B$BДля этого теста вам будут предоставлены специальные бинты.$B$BУдачи, доктор.', 'Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.Помните о порядке оказания помощи! Находящиеся при смерти солдаты умрут быстрее, чем тяжелораненые. Легкораненые могут прожить дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.', 'Доктор $N, добро пожаловать в ряды травматологов Орды.', NULL, NULL, NULL, '15 пациентов спасено!', 'Очередные перевязочные бинты', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6623, 'Травматология', 'Доктор $N, я так понимаю? Рад новой встрече.$B$BУ меня для тебя замечательные новости. Доктор Грегори Виктор, главный травматолог Орды, предлагает тебе поработать у него в Павшем Молоте. Такой шанс выпадает раз в жизни! Лично я отдал бы все на свете за возможность поработать под руководством великого Грегори Виктора! Не упусти свою удачу!', 'Отправляйтесь в Павший Молот на нагорье Арати и поговорите с доктором Грегори Виктором о том, чтобы стать травматологом.', 'Отлично. Надевайте халат, работа не ждет!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6624, 'Очередь на медобслуживание', 'Здравствуйте, доктор. Вам сегодня предстоит пройти испытание на очередность оказания помощи раненым. Если вы успешно пройдете этот экзамен, вы будете приняты в ряды престижного сообщества травматологов Альянса.$B$BА теперь слушайте внимательно! Сначала необходимо оказать помощь смертельно раненым. После – тем, у кого тяжелые ранения. Последними идут обычные раненые. Вы должны оказать помощь 15 пациентам, чтобы пройти этот экзамен. Если 6 ваших пациентов после оказания им помощи скончаются, экзамен будет считаться проваленным.$B$BУдачи, доктор.', 'Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.Помните о порядке оказания помощи! Находящиеся при смерти солдаты умрут быстрее, чем тяжелораненые. Легкораненые могут прожить дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.', 'Доктор $N, Добро пожаловать в ряды травматологов Альянса!', NULL, NULL, NULL, '15 пациентов спасено!', 'Очередные перевязочные бинты', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6625, 'Травматологи Альянса', 'Полагаю, вы доктор $N. Приятно познакомиться.$B$BУ меня есть для вас замечательная новость! Густаф ван Склифф, главный врач-травматолог Альянса, делает вам личное предложение приехать к нему в Терамор. Такая возможность выпадает раз в жизни! Я бы все отдала за возможность учиться у великого доктора Густафа ван Склиффа! Не упустите возможности, доктор!', 'Отправляйтесь в Терамор в Пылевых топях и поговорите с доктором Густавом ван Склиффом насчет зачисления в травматологи Альянса.', 'Чудесно. Мойте руки, и сразу начнем!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6626, 'Воинство зла', 'Отрекшиеся не стремятся превратить смертных в себе подобных... насколько мне известно. Однако этот посланник, видимо, охотно превращает в нежить всех желающих. Я начинаю думать, что на самом деле он работает на Плеть.$B$BОднако сейчас меня больше беспокоит не он, а его последователи, число которых все возрастает. Я вижу,что каждые день из тьмы выползают все новые и новые его приспешники, пресмыкающиеся перед ним в жажде власти.$B$BЯ слишком слаба, чтобы справиться с ними, $N. Помоги мне.', 'Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице в Курганы Иглошкурых.', 'Спасибо, $N. Ты оказал мне неоценимую помощь! Я продолжу наблюдать за посланником и иглогривами. Если же ты ищешь более серьезных противников, собери соратников и отправляйся к пещере, напоминающей кабанью утробу. Не сомневаюсь, внутри скрываются создания, с которыми будет интересно помериться силами столь великому воителю.', 'Как охота, $N? Глядя на то, что творит это посланник в наших землях, я перестаю сомневаться, что Плеть представляет самую страшную угрозу нашему миру с самого его сотворения.', NULL, NULL, 'Боевой страж племени Иглошкурых убито', 'Терноплет из племени Иглошкурых убито', 'Сектантка из племени Мертвой Головы убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6627, 'Испытание знаний', 'Ты $gпринес:принесла: мне книгу, и я должен задать тебе вопрос. Ты $gготов:готова:?$B$BСпешить нам некуда, так что не торопись. Можешь ответить мне в любое время.', 'Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах.', 'Отличная работа, $C. Ты изучил книгу как следует и прошел еще одно наше испытание.', 'Жизнь полна вопросов, $C. Тебе никогда не удастся ответить на все, но если не будешь пренебрегать обучением, то сможешь слегка увеличить свои знания.', NULL, NULL, 'Дайте верный ответ на вопрос Брауга Тусклого Духа.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6628, 'Испытание знаний', 'Вот мы и встретились снова. Ты $gпроявил:проявила: недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос.$B$BКогда будешь $gготов:готова:, подойди и поговори со мной, но перед этим как следует подготовься. Спешить нам некуда.', 'Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде.', 'Отличная работа, $N. Я сомневался, что у тебя хватит терпения изучить этот текст, но ты дал верный ответ.', 'Я считаю, что для выживания в этом мире нужно помнить только одно правило: чем больше знаешь, тем больше видишь.$B$BУчись, наблюдай, и тогда разглядишь то, чего никто другой не увидит $R.', NULL, NULL, 'Правильно ответьте на вопрос Парквелла Финталласа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6629, 'Убить Грундига Темное Облако', 'Что ж, $N, с негодяями из племени Зловещего Тотема тебе удалось расправиться отлично. Но Грундиг Темное Облако и его личная банда громил куда хуже. Именно он возглавлял то жестокое нападение на мою деревню.$B$BЕсли осмелишься, то найдешь его на заставе Зловещего Тотема чуть дальше по дороге на запад. Убей его, и я буду вечно тебе признателен.', 'Убейте Грундига Темное Облако и 6 громил из племени Зловещего Тотема и вернитесь к Макабе Плоскому Копыту, который ждет на юго-восточной границе Когтистых гор.', 'Грундиг Темное Облако мертв! $N, за это деяние я буду вечно признателен тебе!', NULL, NULL, NULL, 'Грундиг Темное Облако убито', 'Громила из племени Зловещего Тотема убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6641, 'Ворша Хлестунья', 'Ворша Хлестунья... это омерзительная гидра, что рыщет в морях...$B$BОна нападает на нашу заставу почем зря, уничтожая все на своем пути.$B$BНо я готов драться, $N. Я готов уничтожить гидру и положить конец ее нападениям на Зорам\'гар.$B$BНаги почитают эту гадкую тварь и поддерживают в ее честь пламя на жаровне, что находится на острове у побережья. Думаю, если мы ее загасим, то разъяренная Ворша вылезет из моря.$B$BНам понадобится помощь, так что приведи крепких друзей.', 'Охраняйте Муглаша на его пути к жаровне. Помогите ему погасить жаровню, а затем защищайте его, ведя бой с нагами.Если вам все удастся, возвращайтесь в форт Зорам\'гар и сообщите гонцу клана Песни Войны о смерти Ворши Хлестуньи.', 'С тех пор, как я сюда прибыл, я пережил много нападений наг. Мне прямо легче на душе становится от мысли, что Ворша больше не будет разгуливать где ей вздумается.$B$BМы в большом долгу перед тобой, $N.', NULL, NULL, NULL, 'Победите Воршу Хлестунью.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6642, 'Покровительство братства, черное железо', '', '', 'Твой дар приняли и оценили. Ты заслужил добрую славу. Если братство удостоверится в твоей преданности, тебе дадут доступ к тайнам древних ремесел.', NULL, NULL, NULL, 'Руда черного железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6643, 'Покровительство братства, огненное ядро', '', '', 'Твой дар приняли и оценили. Ты действительно достоин доверия братьев. Думаю, рано или поздно ты получишь доступ к тайнам древних ремесел.', NULL, NULL, NULL, 'Огненное ядро', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6644, 'Покровительство братства, ядро лавы', '', '', 'Твой дар приняли и оценили. Теперь мы видим, что ты действительно ищешь дружбы с нами. Если ты заслужишь добрую славу в братстве, мы поделимся с тобой тайнами древних ремесел.', NULL, NULL, NULL, 'Ядро лавы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6645, 'Покровительство братства, кожа Недр', '', '', 'Твой дар приняли и оценили. Многие братья относятся к тебе с уважением. Если ты заслужишь почет в братстве, мы поделимся с тобой тайнами древних ремесел.', NULL, NULL, NULL, 'Кожа Недр', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6646, 'Покровительство братства, кровь горы', '', '', 'Твой дар приняли и оценили. Если заслужишь доверие братства, тебе дадут доступ к тайнам древних ремесел.', NULL, NULL, NULL, 'Кровь Горы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6661, 'Охота на крыс', 'Эй ты, стой, да? Зарра... За... Зарррработать хочешь? У нас тут большая проблема с крысами и не хватает умелых рук.$B$BЧто ты там болтаешь? Все, что от тебя требуется – взять эту флейту крысолова и сыграть подходящую мелодию. Они пойдут за тобой хоть на край света!$B$BНо это лишнее – ты просто поймай пяток и принеси, они нужны нам живыми.$B$BРрррр...', 'Поймайте 5 подземных крыс, используя Флейту крысолова, и принесите их Монти. Не забудьте вернуть флейту владельцу.', 'Ха, хорошо сделанная работенка, молодец! Моему братцу они нужны свеженькими, чтобы приготовить из них котлеты.', 'Аррр... Мы еще долго будем ждать?', NULL, NULL, 'Поймано крыс', 'Флейта крысолова (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6662, 'Братишка Нипси', 'Мой братишка Нипси занимается производством котлет из подземных крыс на том конце подземки. Надо, чтобы ты $gдоставил:доставила: этот ящик с крысами к нему, пока они не протухли. Так что давай, двигай!$B$BТы ведь $gездил:ездила: раньше на поезде, да? Это очень просто. Заходи, когда поезд прибудет – и наслаждайся поездкой. Главное, не высовывай руки-ноги, не то на всю жисть калекой останешься.', 'Отвезите Нипси в подземное депо Штормграда коробку таинственного мяса.', 'Бедняга Монти. После того, что случилось в Гномрегане, он сам на себя не похож. Этот парень океана в жизни не видал, а туда же – в пираты метит.$B$B*Нипси вздыхает.* Ну, по крайней мере, он обеспечивает непрерывные поставки этих дерганых тварей.', '*Нипси просовывает указательный палец в одно из отверстий для доступа воздуха, проделанных в коробке.*$B$BЖивенькие-здоровенькие... и как раз вовремя!', NULL, NULL, 'Коробка таинственного мяса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6681, 'Поместье, Черный Ворон', '$N,$B$BЧерный Ворон очень заинтересовался тобой, $gюный вор:юная воришка:. Мы наблюдали. Тебе не хватает ловкости, но это преходяще.$B$BЕсли ты хочешь стать $gучеником:ученицей: мастера Черного Ворона и членом Лиги убийц, стоит только принести печать Черного Ворона (приложенную к этому письму) в поместье Черный Ворон.$B$BПервым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость.$B$BС уважением,$B$B$Nрад.', 'Отнесите печать Черного Ворона $Nраду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.Не теряйте бдительности. Поиски поместья – проверка на ловкость.', 'Отлично, юный вор.$B$BВид у тебя немного побитый, но ничего особенного.$B$BТебя ждет долгий путь – долгий и исполненный наград. Ты готов принять свою судьбу, войдя в число мастеров Черного Ворона?$B$BПоговори со стражами снаружи дома. Они дадут тебе первое задание.', 'Ты знаешь Милтона?$B$B*Фахрад смеется.*', NULL, NULL, 'Ритуал Хитрости', 'Печать Черного Ворона (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6701, 'Эмблемы Синдиката', '', '', 'Эй, отличная работа! Если ты продолжишь в том же духе, может, прочие разбойники перестанут над тобой смеяться.', NULL, NULL, NULL, 'Эмблема Синдиката', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6721, 'Путь охотника', 'Привет тебе, $gюный охотник:юная охотница:. Ты кажешься мне достаточно $gопытным:опытной:, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.', 'Поговорите с Дазаларом в Доланааре, что в Тельдрассиле.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6722, 'Путь охотника', 'Привет тебе, $gюный охотник:юная охотница:. Ты кажешься мне достаточно $gопытным:опытной:, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.', 'Поговорите с Дазаларом в Доланааре, что в Тельдрассиле.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6741, 'Больше добычи!', '', '', 'Еще раз спасибо, $N. Орда гордится тобой...', NULL, NULL, NULL, 'Обломки брони', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6761, 'Новое пограничье', 'Я поручил своему заместителю, Матренгилу Медвежьей Лапе, разобраться с призывом о помощи с Лунной поляны. Так что по этому поводу говори с ним – НЕ со мной!$B$BИ позволь мне дать тебе один дружеский совет. Это я вывел нас всех из тьмы – я, а вовсе не Круг Кенария Лунной поляны, – когда наш народ потерял все. Тельдрассил дает нам новую жизнь! Они наверняка попытаются внушить тебе совсем другое, но только глупец поверит их пропаганде!$B$BТы же, вроде, не из таких. Или я ошибаюсь?', 'Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнасе.', 'Да, $C, спасибо, что пришел. Прошу прощения за это недоразумение... но взаимное недоверие между здешним верховным друидом и хранителем Ремулом с Лунной поляны прямо-таки дрожит в воздухе. Каждый подозревает другого в кляузничестве, а ведь проблема странной порчи Тельдрассила все еще не решена. Но взаимное недоверие от этого не стихает.$B$BКак бы то ни было, у нас есть долг перед Кругом Кенария... даже если его предводители не ладят друг с другом.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6762, 'Рабин Сатурна', 'Мажордом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса... и еще дальше, к западу от Ун\'Горо. Найди его в Ночной Гавани, главном поселении Лунной поляны.$B$BПоскольку твои труды будут на благо всем нам, советую тебе вести себя осторожно. Между Дарнасом и Лунной поляной трения... и как бы они не переросли со временем в нечто большее.', 'Поговорите с Рабином Сатурной в селении Ночная Гавань на Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от крепости Древобрюхов.', 'Я Рабин Сатурна. От лица хранителя Ремула и всех обитателей сего священного места приветствую тебя.$B$BЯ ценю твою заинтересованность и горячую готовность помочь Кругу Кенария. Также мне ведомо о недовольстве, с которым верховный друид Дарнасса отозвался о твоей помощи нам. Будь уверен, что все, что делается, – делается во благо, и что тебя не коснутся необдуманные выпады, целью коих ты можешь стать.$B$BЗдесь ты среди друзей, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6781, 'Больше обломков брони', '', '', 'Это неплохие образчики, $N. Я могу перековать их на новую экипировку для наших воинов.$B$BЕсли припасов у меня окажется достаточно, может, наши опытные воины смогут выйти на поле боя!', NULL, NULL, NULL, 'Обломки брони', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6801, 'Локолар Владыка Льда', '', '', 'Мы пролили достаточно вражеской крови. Я смешаю эту кровь с остальной... И как только жертва будет принесена, Владыка Льда покажет этим псам Грозовой Вершины всю силу ярости Северных Волков!', NULL, NULL, NULL, 'Кровь солдата из клана Грозовой Вершины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6804, 'Отравленная вода', 'Мы отправили отряд элементалей воды на разведку в восточные пределы Лордерона, пораженные чумой нежити. Теперь наши разведчики поражены скверной. Повелители Вод не могут допустить, чтобы проклятая чума угрожала нашему народу!$B$BВозьми этот фиал. В нем заключен один из аспектов Нептулона. Он исцелит пораженных скверной элементалей, уничтожив проникшую в их тела заразу. Однако этот процесс столь болезнен, что некоторые из них могут стать нестабильными.$B$BТебе придется убить колыхающихся волноплесков. Принеси мне их браслеты.', 'Исцелите отравленных элементалей в Восточных Чумных землях с помощью аспекта Нептулона. Принесите 12 браслетов колыхающихся волноплесков и аспект Нептулона герцогу Гидраксису в Азшару.', 'Ты отлично справился, $C. Оскверненные элементали воды были позором для всего нашего племени – ведь в основе элементалей воды лежит чистота, именно в ней коренится наша сила.', 'Принес браслеты?', NULL, NULL, 'Наручи обезумевших духов воды', 'Аспект Нептулона (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6805, 'Буря в пустыне', 'Мы, элементали воды, противостоим существам низших стихий. Если и в самом деле хочешь быть $gнашим союзником:нашей союзницей:, докажи это!$B$BДалеко на юге, в пустынных землях Силитуса, в скалистом уголке, именуемом долиной Кристаллов, кишат слуги воздуха и земли. Они защищают сокрытые там предметы силы от примитивных существ, смертных. Мне нет никакого дела до того, что они там стерегут, я хочу, чтобы ты $gперебил:перебила: их.$B$BОтправляйся в Долину Кристаллов в Силитус и уничтожь наших врагов.', 'Убейте 15 вихрей пыли и 15 пустынных грохотунов и возвращайтесь к герцогу Гидраксису в Азшару.', 'Ты доказал свою доблесть и полезность для нашего народа. Возможно, у меня будет для тебя и другая работа – работа, более достойная ценного союзника Повелителей Вод.', 'Трусость – это то, чему нет прощения, $C. Отправляйся в Силитус и докажи свою доблесть.', NULL, NULL, 'Вихрь пыли убито', 'Пустынный грохотун убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6821, 'Око Углевзора', 'Ты $gдоказал:доказала: мне, что $gспособен:способна: доблестно противостоять врагам и верно служить Повелителям Вод. Однако пока тебе приходилось выходить на бой с довольно слабыми противниками. Сможешь ди ты сразить более могущественного врага.$B$BСлушай мое повеление.$B$BНа вершине пика Черной горы орки изловили слугу огня, Пиростража Углевзора. Найди место, где они его держат, и перебей и стражу и пленника. Принеси мне его глаз – докажи свою преданность.', 'Принесите око Углевзора герцогу Гидраксису в Азшару.', 'Что ж, ты доказал, что у тебя довольно силы и хитрости для столь сложной задачи – ведь для того, чтобы противостоять тварям, скрывающимся в Черной горе, одной только силы недостаточно. $B$BТеперь я уверен, ты станешь для нас ценным союзником, $N...', 'Ты принес мне глаз, $C? Или у тебя не хватило духу и близко подойте к Пику Черной горы.', NULL, NULL, 'Око Углеглаза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6822, 'Огненные Недра', 'Пришло время испытать твои силы всерьез, $N. Ты $gготов:готова:?$B$BНа самом дне Глубин Черной горы скрывается путь к Огненным Недрам. Это оплот нашего врага, охраняемый самыми мощными служителями огня в нашем мире.$B$BОтправляйся в Огненные Недра, $N. Докажи мне, что у тебя хватит сил справиться с тем, что скрывается там.$B$BЕсли у тебя есть союзники, бери их с собой. Не стоит отправляться в Огненные Недра в одиночку.', 'Убейте 1 Повелителя огня, 1 лавового великана, 1 древнюю гончую Недр и 1 лавового волноплеска и возвращайтесь к герцогу Гидраксису в Азшару.', 'Тебе под силу подвиги, которые большинству кажутся невозможными. Ты вступил в схватку с тварями Огненных Недр и вышел из нее победителем. $B$BТы силен для столь маленького создания. $B$BВозможно, однажды Повелители Вод заключат союз с твоим племенем.', NULL, NULL, NULL, 'Огненный великан убито', 'Повелитель огня убито', 'Древняя гончая недр убито', 'Лавоменталь убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6823, 'Агент Гидраксиса', 'Если в самом деле хочешь быть $gнашим союзником:нашей союзницей:, докажи серьезность своих намерений в боях против наших врагов – слуг воздуха, земли и огня. Каждое нанесенное им поражение подорвет их позиции в этих землях и послужит доказательством твоей приверженности благу нашего народа.', 'Добейтесь уважительного отношеия к себе со стороны Гидраксианских Повелителей Вод, затем отправляйтесь к герцогу Гидраксису в Азшару.', 'Молва о твоих необыкновенных успехах в борьбе против наших врагов облетела всех Повелителей Вод. Некоторые из нас считали, что твое тело слишком маленькое и хрупкое, чтобы ты мог биться в наших рядах, однако теперь никто не сомневается в твоей силе. Ты завоевал наше уважение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6824, 'Руки врага', '$N, твоя помощь для нас неоценима, и мы с неохотой отправляем тебя на последнее задание – мы не хотим терять столь полезного союзника, однако работа есть работа.$B$BИмей в виду, если ты успешно выполнишь поставленную перед тобой задачу, это весьма существенно приблизит час нашей победы.$B$BМы хотим, чтобы ты $gуничтожил:уничтожила: нескольких капитанов в Огненных Недрах: Люцифрона, Сульфурона, Гееннаса и Шаззраха. Убей их и принеси их отрубленные руки.$B$BЭто потребует от тебя всех сил, но если ты преуспеешь, Повелителям огня будет нанесен ужасный удар.', 'Принесите руки Люцифрона, Сульфурона, Гееннаса и Шаззраха герцогу Гидраксису в Азшару.', 'Это их руки! Тебе действительно удалось уничтожить их! $B$B$N, твоим подвигам нет числа, но последнее твое деяние нескоро будет стерто из памяти Повелителей Вод. Твое имя станет легендой. $B$BВозвращайся ко мне, $N, у меня найдется для тебя работа.', 'Тебе удалось разбить капитанов Недр, $N? Ты принес мне их руки.', NULL, NULL, 'Рука Шаззраха', 'Рука Люцифрона', 'Рука Гееннаса', 'Рука Сульфурона');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6825, 'Небо зовет – флот Смуггла', '', '', 'Флот питается плотью своих врагов.$B$BСкоро мы двинемся в бой!', NULL, NULL, NULL, 'Плоть солдата из клана Грозовой Вершины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6826, 'Небо зовет – флот Мааши', '', '', 'Больше мяса! Чтобы мои виверны снова могли вступить в бой, нужно еще!', NULL, NULL, NULL, 'Плоть лейтенанта из клана Грозовой Вершины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6827, 'Воздух зовет – флот Маэстра', '', '', 'Что это?! Ты думаешь, меня устроит такое качество работы, а, $N? Ступай, солдат! Катись! Нужно больше мяса!', NULL, NULL, NULL, 'Плоть командора из клана Грозовой Вершины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6844, 'Умбер, архивариус', 'Здесь полно работы, но мне кажется, главное – отнести это в Круг, на анализ. Поверь мне, дела здесь не переводятся. Если внутри этого хитина находится дневник, то Круг сможет заглянуть в прошлое!$B$BОтнеси этот дневник архивариусу Круга в Ночную Гавань. Его зовут Умбер, он настоящий гений! Да, тронутый, не без того, но все равно гений! Умбер находил манускрипты в куда более плохом состоянии. Если эти записи можно восстановить, он это сделает.', 'Отнесите покрытый коркой предмет Умберу – архивариусу Круга Кенария – в деревню Ночная Гавань, что на Лунной поляне.', 'Жаба меня побери! Что это? Формой определенно напоминает книгу... Попытаюсь-ка я взломать оболочку.$B$BТебя прислал Лайо из Силитуса? До меня доходили только смутные слухи – не такие уж смутные, если хорошо подумать – об ужасах, творящихся в тех краях. Учитывая мою нелюбовь ко всему, что напоминает насекомых, все эти сплетни – хорошая причина остаться здесь, с моими книжечками!', 'Эй, привет! Хмм…$B$BНе скрою, друг мой... Пахнешь ты неважно. Можно сказать, воняешь. Нет-нет, ничего личного. Всего лишь маленький совет... В будущем, вернувшись из боя, освежись немного. Первое впечатление – это очень важно!$B$BВпрочем... Чем могу служить?', NULL, NULL, 'Покрытый коркой щит силитида (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6845, 'Раскрытие древних секретов', 'Короче, свяжись со мной как можно скорее... если, конечно, хочешь знать, что там внутри. Как только я это узнаю, с удовольствием поделюсь с тобой информацией – разумеется, если там действительно окажется книга.$B$BА пока я свяжусь с самой-большой-медведицей этого медвежьего угла, то есть Рабином. Он, несомненно, пожелает узнать, что за кашу ты тут $gзаварил:заварила:. Никогда не заставляй мать-медведицу ждать, $N... ну, если только тебе неймется искупаться в меду.$B$BТакое бывает, уж поверь мне.', 'Поговорите с Рабином Сатурной в деревне Ночная Гавань на Лунной поляне.', 'А, $N – я надеялся, что у тебя найдется для меня минутка. Рад видеть, что ты в добром здравии.$B$BЯ получил известие, что ты идешь с поля, и мне захотелось лично выразить тебе признательность Круга Кенария за помощь. Несомненно, в Силитусе еще много тайн, и то, что ты доставил Умберу, может оказаться наиболее интересным. Прошу тебя, прими это в знак нашей благодарности за помощь.$B$BСпасибо тебе, благородный $C.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6846, 'В атаку!', '', '', '', NULL, NULL, NULL, 'Приказы об атаке клана Грозовой Вершины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6847, 'Всевидящее око мастера Рисона', 'Для Синдиката ничего не значат войны, которые ведутся в этой долине, $C. Мы будем делать то, что делали всегда: подождем, пока из пепла не появится истинный вождь, свободный от всеобщего безумия, и не нанесет решающий удар.$B$BПравда, сейчас мы здесь не поэтому. Тролли из племени Ледяной Секиры похитили наше сокровище – всевидящее око.$B$BСпаси око, и мы всегда будем к твоим услугам, что бы ни случилось.$B$BВозвращайся, когда добудешь око, я тебя проверю.$B$B<Мастер Рисон оскаливает зубы в усмешке.:', 'Заберите всевидящее око мастера Рисона из пещер Ледяной Секиры и возвращайтесь к мастеру Рисону.Будьте осторожны: говорят, что на всевидящее око мастера Рисона наложено ужасное проклятие!', '', NULL, NULL, NULL, 'Всевидящее око мастера Рисона спасено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6848, 'Всевидящее око мастера Рисона', 'Для Синдиката ничего не значат войны, которые ведутся в этой долине, $C. Мы будем делать то, что делали всегда: подождем, пока из пепла не появится истинный вождь, свободный от всеобщего безумия, и не нанесет решающий удар.$B$BПравда, сейчас мы здесь не поэтому. Тролли из племени Ледяной Секиры похитили наше сокровище – всевидящее око.$B$BСпаси око, и мы всегда будем к твоим услугам, что бы ни случилось.$B$BВозвращайся, когда добудешь око, я тебя проверю.$B$B<Мастер Рисон оскаливает зубы в усмешке.:', 'Заберите всевидящее око мастера Рисона из пещер Ледяной Секиры и возвращайтесь к мастеру Рисону.Будьте осторожны: говорят, что на всевидящее око мастера Рисона наложено ужасное проклятие!', '', NULL, NULL, NULL, 'Всевидящее око мастера Рисона спасено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6861, 'Портативный крошшер Зинфиззлекса', 'Я хочу опробовать свой портативный крошшер не меньше тебя, $r, но для того, чтобы его сделать, мне нужны материалы – много материалов!$B$BСказать точнее, целая гора тория, мифрила и железа. Кроме того, по паровой пиле на каждый крошшер. Их можно достать на лесопилке.$B$BДо того, как меня поймали, я здесь все разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины.', 'Принесите мастеру-инженеру Спустипару$B$B*30 ториевых слитков$B$B*50 мифриловых слитков$B$B*75 железных слитков1 паровую пилу.', '', NULL, NULL, NULL, 'Ториевый слиток', 'Мифриловый слиток', 'Железный слиток (75)', 'Паровая пила');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6862, 'Портативный крошшер Зинфиззлекса', 'Я хочу опробовать свой портативный крошшер не меньше тебя, $r, но для того, чтобы его сделать, мне нужны материалы – много материалов!$B$BСказать точнее, целая гора тория, мифрила и железа. Кроме того, по паровой пиле на каждый резак. Их можно достать на лесопилке.$B$BДо того, как меня поймали, я здесь все разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины.', 'Принесите мастеру-инженеру Спустипару$B$B*30 ториевых слитков$B$B*50 мифриловых слитков$B$B*75 железных слитков1 паровую пилу.', '', NULL, NULL, NULL, 'Ториевый слиток', 'Мифриловый слиток', 'Железный слиток (75)', 'Паровая пила');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6881, 'Ивус Лесной Властелин', '', '', 'Отлично, $N. Сила этих чар пригодится для усиления уже имеющейся магии. Когда энергии наберется достаточно, я смогу ее сфокусировать и воззвать к Владыке Леса о помощи.', NULL, NULL, NULL, 'Кристалл Бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6901, 'В атаку!', '', '', '', NULL, NULL, NULL, 'Приказы об атаке клана Северного Волка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6921, 'Среди руин', 'Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины. Их присутствие приведет лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда.$B$B$N, ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!', 'Принесите глубинный сердечник Дже\'неу Санкри в форт Зорам\'гар в Ясеневый лес.', 'Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить.$B$BТы сегодня хорошо потрудился, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде помог, и имеешь право гордиться собой.', 'Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает там Сумеречный Молот.', NULL, NULL, 'Глубинный сердечник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6922, 'Барон Акванис', 'Сраженный элементаль воды оставил после себя странную сферу. Вы предполагаете, что этот предмет каким-то образо подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость. Сама сфера вроде бы не поддается никаким физическим воздействиям.$B$BЕсли кто и сможет понять, что это за штука, то это Дже\'неу Санкри из Служителей Земли. Он находится в форте Орды Зорам\'гар в Ясеневом лесу.', 'Принесите странную водяную сферу Дже\'неу Санкри в форт Зорам\'гар в Ясеневом лесу.', 'Ого... вот это находка, $N.$B$BГоворишь, ты добыл это из барона Акваниса в Непроглядной Пучине? Барон Акванис давно уже считается оскверненной силой Стихии, а этот шар даст понять, что именно повергло его в скверну. Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать.$B$BХорошо, что ты принес эту штуку мне. Прошу – прими это вместе с горячей благодарностью Служителей Земли.', 'О, привет еще раз, $N. Я, как всегда, взирал на морские волны и читал их письмена. Что привело тебя в форт?', NULL, NULL, 'Странная водяная сфера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6941, 'Небо зовет – флот Змейера', '', '', 'Скоро флот будет готов подняться в воздух! А пока – продолжай!', NULL, NULL, NULL, 'Жетон лейтенанта клана Северного Волка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6942, 'Небо зовет – флот Слидора', '', '', 'Продолжай свое дело, солдат! Грифоны Заоблачного пика готовы к вылету с минуты на минуту!', NULL, NULL, NULL, 'Жетон солдата из клана Северного Волка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6943, 'Небо зовет – флот Ромеона', '', '', 'Видишь? Посмотри на них, солдат! Вот они, кружат в воздухе! Скоро флот Ичмена нанесет удар в самое сердце долины! Грозовая Вершина будет править в небесах!', NULL, NULL, NULL, 'Жетон командора клана Северного Волка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6961, 'Здравствуй, Дедушка Зима!', 'Доброго тебе Зимнего Покрова! Не забудь поздороваться с Дедушкой Зимой! Если в этом году ты $gбыл примерным мальчиком:была примерной девочкой:, получишь в день праздника замечательные угощения. Не забудь сказать ему, что именно тебе хотелось бы получить в этом году!$B$BТакже не забудь приготовить угощение для тех, кто хорошо себя вел. У нас есть из чего выбрать. Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!', 'Поговорите с Дедушкой Зимой. Он находится неподалеку от торговца из Пастбищ Дымного Леса в Оргриммаре.', 'Хо-хо-хо! Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса! \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!$B$BВсе, кто хорошо себя вел в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Уррра!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6962, 'Угощение для Дедушки Зимы', 'Эй, не окажешь ли услугу Дедушке Зиме, хм, $gмальчуган:девчушка:?$B$BНет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением. Немного печенья и ледяного молока, чтобы запить, – и будет довольно. Ты ведь любишь дедушку и принесешь мне угощение?', 'Принесите 5 кусочков имбирного печенья и ледяное молоко Дедушке Зиме в Оргриммар.', 'Ну, спасибо! Угодил ты Дедушке Зиме, $N! Доброго тебе праздника Зимнего Покрова.$B$BА вот тебе кое-что... ну, за труды, понимаешь.', 'От всех этих разговоров об угощении у меня у самого аппетит разыгрался. М-м-м... Прянички с молочком...', NULL, NULL, 'Имбирное печенье', 'Ледяное молоко', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6963, 'Кража угощения Зимнего Покрова', 'Слушай... не хочется портить праздничное настроение, но Пастбищам Дымного Леса нужна помощь как раз от $gискателя:искательницы: приключений вроде тебя.$B$BМы потеряли важную партию угощения, что запасаем на праздник, а теперь еще пропал и агент Пастбищ Дымного Леса, которого мы отправили на поиски! Помоги, будь $gлюбезен:любезна:! Говорят, покраденное в последний раз видели в Альтеракских горах, туда наш посланец и отправился.$B$BПривези оттуда и его, и наши припасы в целости и сохранности!', 'Найдите агента Пастбищ Дымного Леса, пропавшего в снежных районах Альтеракских гор.', 'Т-т-ты м-м-меня с-слышишь! Слава б-б-богам!$B$BН-нет, я не с-с-снеговик. М-меня зовут Сакс, я раб-ботаю в Оргриммарском отделении Пастбищ Дымного Леса. М-м-м-меня отп-правили искать пропавший товар, и тут на меня нап-пала тварь, какой я никогда не видывал!$B$BБр-р, ну и холодрыга!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6964, 'Повод для праздника', 'Подарки, гости, угощение... чушь собачья!$B$BЭти гоблины искажают саму суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым ее укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!$B$BЕжели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте Сагорна Гривастого Странника. Уверен, он будет очень удивлен, что хоть кому-то история интереснее подарков.', 'Поговорите с Сагорном Гривастым Странником в Аллее Мудрости Оргриммара о празднике Зимнего Покрова.', 'Праздник Зимнего Покрова, говоришь? Увы, в прежние времена для нас, тауренов, он был куда важнее. А теперь, похоже, другие используют древние легенды, чтобы продать побольше сладостей и подарков.$B$BНеудивительно, что Фарманда это так огорчает. Он и остальные таурены держатся за наше прошлое, как за боевое знамя. Я лично считаю, что немного веселья никогда не помешает, но о происхождении праздника забывать нельзя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6981, 'Светящийся осколок', 'Блестящий осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.$B$BПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.', 'Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке.Затем отнесите осколок туда, куда вас направят.', 'О... мне никогда не приходилось видеть ничего подобного...', 'Приветствую тебя, $R. Я могу тебе чем-то помочь?', NULL, NULL, 'Светящийся осколок (Прилагается)', 'Поговорите с кем-нибудь в Кабестане о светящемся осколке.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6982, 'Припасы Ледяного Зуба', 'Рудник Ледяного Зуба – это хранилище Орды. Мой желудок не переваривает жратву, которой они кормят своих солдат, а их доспехи и оружие выглядят ужасно! Но... во времена, когда припасы столь важны, нам выбирать не приходится. $B$BОтправляйся в рудник Ледяного Зуба и принеси мне часть их припасов. Это поможет Альянсу поддержать свою боевую форму, а заодно лишить воинов Орды самого необходимого.$B$BРудник находится далеко на юге, в глубоком тылу Орды.', 'Принесите 10 ящиков с припасами Ледяного Зуба интенданту Альянса в Дун Болдар.', 'Сколько припасов! Отличная работа, $N. Я проверю содержимое ящиков и раздам его нашим воинам.', 'Удалось ли вам добраться до рудника Ледяного Зуба в тылу Орды, $N? Сумели ли вы стащить их припасы?', NULL, NULL, 'Припасы из рудника Ледяного Зуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6983, 'Прохладное чувство юмора', '$N, с-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства! Т-только ос-стор-р-рожно! Это он с-сделал из меня с-снеговика!$B$BВа-ва-вам понадобится помощь! Я в-видел, как он шляется тут в-в-вместе с другими йети. Он нав-верняка где-то п-поблизости! Отыщите мой груз, $N, отвезите его в Оргриммар, П-пастбищам Дымного Леса, и п-п-передайте им, что м-меня надо разморозить!', 'Отыщите украденные лакомства и верните их Каймарду Меднокнопу в Оргриммар. Лакомства должны быть у Омерзительного Гринча, который бродит где-то среди заснеженных вершин Альтеракских гор.', 'Вы нашли груз! Вы спасли наш праздник!$B$BБедный Сакс! Конечно же, мы немедленно отправим спасателей и придумаем, как его разморозить. Надеюсь, он успеет прийти в себя к празднику... Хотя, конечно же, потом ему придется отработать то время, которое он прогулял! Но в любом случае, если бы не вы, все пошло бы прахом!', 'Зарригар, без этих лакомств наш праздник Зимнего Покрова будет загублен на корню! Можете себе представить: все послушные детки останутся без знаменитых пирожков Гракку!', NULL, NULL, 'Украденные лакомства', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6984, '\"Пастбища Дымного Леса\" благодарны тебе!', 'Спасибо тебе от \"Пастбищ Дымного Леса\" за возвращение краденых сладостей, $N! И хотим мы тебе за это предложить особый подарок... От самого Дедушки Зимы!$B$BПоговори с Дедушкой Зимой, и он даст тебе подарок праздника Зимнего Покрова от нашего имени! От нашего села да к вашему столу – вкусная и здоровая пища от \"Пастбищ Дымного Леса\"... благодаря тебе, конечно же!', 'Поговорите с Дедушкой Зимой в Оргриммаре.', 'Хо-хо-хо! Добро пожаловать!$B$BГоблины мне сказали, что тебе нынче полагается специальный приз, и я рад отдать его. Вот он – и веселого тебе праздника Зимнего Покрова каждый год!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (6985, 'Припасы Железного рудника', 'Дворфы из клана Грозовой Вершины используют Железный рудник для хранения припасов. Сбегай на этот рудник и позаимствуй у дворфов их богатства. Это малость подрежет крылья клану Грозовой Вершины, а мы получим необходимые материалы.$B$BДействуй осторожно, $N. Железный рудник лежит в глубине территории Альянса, и за него постоянно идут бои.', 'Доставьте 10 ящиков припасов Железного рудника интенданту Орды в крепость Северного Волка.', 'Вот это я понимаю! Прекрасная работа, $N! Надеюсь, во время набега тебе удалось прирезать парочку дворфов во славу Северного Волка!', 'Ты уже вернулся с Железного рудника? А где припасы?', NULL, NULL, 'Припасы Железного рудника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7001, 'Пустые стойла', 'Набат войны зовет наших солдат к оружию! Мы должны восстановить боеспособность армии!$B$BЕсли в стойлах заведется зверье, то всадники на волках смогут снова отправиться в бой.$B$BВозьми этот намордник и найди следы северных волков, обитающих в ближайшем лесу. Когда отыщешь волка, используй намордник, чтобы его приручить. Прирученных зверей приводи ко мне, я поставлю их в стойла.$B$BКогда стойла будут полны, наши всадники снова смогут отправиться на фронт.', 'Найдите северного волка в Альтеракской долине. Подойдите к нему на достаточное расстояние, чтобы его \"приручить\", и используйте намордник клана Северного Волка. После приручения северный волк проследует за вами к смотрителю стойл из клана Северного Волка. Поговорите со смотрителем, чтобы получить награду за пойманных волков.', 'Я могу только надеяться, что те, кого я послал за шкурами баранов, будут столь же удачливы, $N.$B$BС такой скоростью мы заполним стойла за считанные часы!', 'Без твоей помощи наездники на волках из клана Северного Волка останутся без верховых животных. Ты оказываешь нам неоценимую услугу!', NULL, NULL, 'Приручите северного волка и приведите его к смотрителю стойл.', 'Наплечники клана Северного Волка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7002, 'Упряжь из бараньей кожи', '', '', 'Отлично, солдат. Я скажу тебе, когда будет достаточно.$B$BА пока продолжай работать!', NULL, NULL, NULL, 'Шкура альтеракского барана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7003, 'Уменьшение великанов', 'Нет, если я собираюсь здесь остаться, мне решительно необходимо что-то сделать с великанами! Они губят весь бизнес.$B$BЯ взял за основу разновидность гномского уменьшающего луча, но внес в конструкцию гоблинские усовершенствования! Дабы самому избежать различных неудобств – например, смерти, – я поручаю его испытание вам. Испробуйте его на любых великанах, каких найдете в Фераласе. После уменьшения вы обнаружите на месте великанов их маленькие копии – принесите их мне!', 'Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 15 миниатюрных великанов этих великанов Зорбину Дребезгуну в порт Забытого берега в Фераласе.', 'Архивеликолепно! Я крайне рад видеть, что вы не только вернулись живым, но и благополучно сохранили все ваши конечности! Нет-нет, разумеется, ультрасжиматель совершенно безопасен, как вы могли подумать!$B$BЯ ценю ваши усилия, $N. Вы – добрый друг всех гоблинов! Примите это в знак моей признательности!', 'Остатки миниатюризации – ценнейшая штука для инженера, скажу я вам! Ну, например, они помогают гарантировать, что уменьшитель не сделает чего-нибудь не того: например, не взорвется в руках при работе с ним.$B$BНет-нет, тот, что у вас, конечно же, не взорвется! Он абсолютно надежен!', NULL, NULL, 'Миниатюрный великан', 'Ультрасжиматель Зорбина', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7021, 'Здравствуй, Дедушка Зима!', 'Веселого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре! Все, кто хорошо себя вел в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождешься.$B$BИ $gсам:сама: не забудь купить подарки для тех, кто хорошо себя вел весь год. У нас богатейший выбор подарков на любой вкус! От нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!', 'Поговорите с Дедушкой Зимой. Он находится неподалеку от торговца из Пастбищ Дымного Леса в Оргриммаре.', 'Хо-хо-хо! Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса! \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!$B$BВсе, кто хорошо себя вел в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Уррра!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7022, 'Здравствуй, Дедушка Зима!', 'Доброго тебе Зимнего Покрова! Не забудь поздороваться с Дедушкой Зимой! Если в этом году ты $gбыл примерным мальчиком:была примерной девочкой:, получишь в день праздника замечательные угощения. Не забудь сказать ему, что именно тебе хотелось бы получить в этом году!$B$BТакже не забудь приготовить угощение для тех, кто хорошо себя вел. У нас есть из чего выбрать. Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!', 'Поговорите с Дедушкой Зимой – он находится неподалеку от торговца из Пастбищ Дымного Леса в Стальгорне.', 'Хо-хо-хо! Я Дедушка Зима, и от имени доброго народа Пастбищ Дымного Леса... \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса,\" – хотел бы пожелать всем замечательно провести праздник Зимнего Покрова.$B$BЕсли в этом году ты был примерным мальчиком, то, может быть, ты получишь лакомство от Пастбищ Дымного Леса в качестве угощения на праздник Зимнего Покрова. Хо-хо!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7023, 'Здравствуй, Дедушка Зима!', 'Доброго тебе Зимнего Покрова! Не забудь поздороваться с Дедушкой Зимой! Если в этом году ты $gбыл примерным мальчиком:была примерной девочкой:, получишь в день праздника замечательные угощения. Не забудь сказать ему, что именно тебе хотелось бы получить в этом году!$B$BТакже не забудь приготовить угощение для тех, кто хорошо себя вел. У нас есть из чего выбрать. Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища с Пастбищ Дымного Леса!', 'Поговорите с Дедушкой Зимой – он находится неподалеку от торговца из Пастбищ Дымного Леса в Стальгорне.', 'Хо-хо-хо! Я – Дедушка Зима, и от имени доброго народа пастбищ Дымного леса... \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из пастбищ Дымного леса,\" – хотел бы пожелать всем замечательно провести праздник Зимнего Покрова.$B$BЕсли в этом году ты был примерным мальчиком, то, может быть, ты получишь лакомство от Пастбищ Дымного Леса в качестве угощения на праздник Зимнего Покрова. Хо-хо!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7024, 'Здравствуй, Дедушка Зима!', 'Веселого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре! Все, кто хорошо себя вел в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождешься.$B$BИ $gсам:сама: не забудь купить подарки для тех, кто хорошо себя вел весь год. У нас богатейший выбор подарков на любой вкус! От нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!', 'Поговорите с Дедушкой Зимой. Он находится неподалеку от торговца из Пастбищ Дымного Леса в Оргриммаре.', 'Хо-хо-хо! Я Дедушка Зима, и я явился к вам благодаря добросердечию Пастбищ Дымного Леса! \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!$B$BВсе, кто хорошо себя вел в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Ур-р-ра!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7025, 'Угощение для Дедушки Зимы', 'Эй, не окажешь ли услугу Дедушке Зиме, хм, $gмальчуган:девчушка:?$B$BНет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением. Немного печенья и ледяного молока, чтобы запить, – и будет довольно. Ты ведь любишь дедушку и принесешь мне угощение?', 'Принесите 5 кусочков имбирного печенья и ледяное молоко Дедушке Зиме в Стальгорн.', 'Ну, ты и угодил Дедушке Зиме, $N! Доброго тебе праздника Зимнего Покрова.$B$BА вот тебе кое-что... ну, за труды, ты понимаешь.', 'От всех этих разговоров об угощении у меня самого аппетит разыгрался. Мммм... Прянички с молочком...', NULL, NULL, 'Имбирное печенье', 'Ледяное молоко', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7026, 'Упряжь ездовых баранов', '', '', 'Отлично, солдат. Я скажу тебе, когда будет достаточно.$B$BА пока продолжай работать!', NULL, NULL, NULL, 'Шкура cеверного волка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7027, 'Пустые стойла', 'Посмотри на эти стойла, $N! Они совершенно пустые! У бригады Грозовой Вершины нет скаковых баранов, а значит, нет и кавалерии.$B$BТы $gдолжен:должна: помочь нам, солдат! Возьми учебный ошейник и отправляйся в самую глушь этой долины. Найди альтеракских баранов, которые там бродят, и поймай их при помощи ошейника. Как поймаешь барана, возвращайся ко мне, я поставлю его в стойла.$B$BКогда баранов будет достаточно, я извещу командира всадников. В твоих силах возродить нашу кавалерию!', 'Найдите в Альтеракской долине альтеракского барана. Чтобы приручить барана, используйте учебный ошейник клана Грозовой Вершины. Для этого надо подойти в барану поближе. Пойманный баран проследует за вами к смотрителю стойл. Поговорите со смотрителем стойл, чтобы получить вознаграждение за пойманных баранов.', 'Стойла наполняется прямо на глазах. Так держать!', 'Без твоей помощи бараньи наездники на баранах из клана Грозовой Вершины останутся без верховых животных. Ты можешь оказать нам неоценимую услугу!', NULL, NULL, 'Баран пойман и возвращен', 'Учебный ошейник клана Грозовой Вершины', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7028, 'Хрустальные орнаменты', 'На западе, в глубинах Мародона, раскинулись хрустальные пещеры Террамока... Это очень древнее место, $C. А я хочу наложить лапу на часть тамошних древностей. За огромными дверями скрыты реликвии древних богов.$B$BЕсли ты отважишься бросить вызов злу, таящемуся в Мародоне, я щедро тебе заплачу. Собери там терадрические хрустальные орнаменты и принеси их мне.$B$BКак только я доберусь до этих орнаментов, я смогу их... изучить. Слишком долго дремали скрытые силы...', 'Соберите 15 терадрических хрустальных орнаментов для Ивы из Пустошей.', 'Ха-ха-ха! Я так и знала, что ты вернешься.$B$B*Ива бормочет себе под нос.*$B$B... Как легко убедить.$B$B… пойдет на что угодно за сходную цену. Хе-хе-хе...', 'Не задавай лишних вопросов!$B$BЗаказ есть заказ.', NULL, NULL, 'Терадрический хрустальный орнамент', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7029, 'Порча Злоязыкого', 'В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все, до чего может дотянуться. Из-за него умирают растения.$B$BВозьми этот фиал, $N, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.$B$BОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от порчи, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.', 'Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.Полейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в деревню Ночных Охотников.', 'Спасибо, что принес мне фиал. Я исследую остатки жидкости.$B$BХотя впереди много работы, зло, совершенное Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.', 'Если ты сумеешь исцелить растение, оно снова оживет. Мы должны делать все, что в наших силах, $N…', NULL, NULL, 'Исцелено растений гнусь-лозы', 'Наполненный лазурный фиал', 'Лазурный фиал с внутренним покрытием', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7041, 'Порча Злоязыкого', 'В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все кругом. Из-за него там больше не растут цветы.$B$BВозьми этот фиал, $N, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.$B$BОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от порчи, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.', 'Наполните лазурный фиал с внутренним покрытием в оранжевом пруду Мародона.Полейте гнусь-лозу из наполненного фиала, чтобы изгнать ядовитую лозу.Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела.', 'Спасибо, что принес мне фиал, $N. Я исследую остатки жидкости.$B$BХотя впереди много работы, зло, совершенное Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.', 'Если ты сумеешь исцелить растение, оно снова оживет. Мы должны делать все, что в наших силах, $N…', NULL, NULL, 'Исцелено растений гнусь-лозы', 'Наполненный лазурный фиал', 'Лазурный фиал с внутренним покрытием', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7042, 'Пропавшее угощение Зимнего Покрова', 'Слушай... не хочется портить праздничное настроение, но Пастбищам Дымного Леса нужна помощь как раз от $gискателя:искательницы: приключений вроде тебя.$B$BМы потеряли важную партию угощения, что запасаем на праздник, а теперь еще пропал и агент Пастбищ Дымного Леса, которого мы отправили на поиски! Помоги, будь $gлюбезен:любезна:! Говорят, покраденное в последний раз видели в Альтеракских горах, туда наш посланец и отправился.$B$BПривези оттуда и его, и наши припасы в целости и сохранности!', 'Найдите агента Пастбищ Дымного Леса, пропавшего в снежных районах Альтеракских гор.', 'В-в-вы м-м-меня с-с-слыш-шит-т-е! П-по г-г-гроб ж-жиз-зни б-б-б-лагодарен!$B$BЯ н-н-не с-с-нег-говик, я М-м-еш-ш-окс, я р-р-абот-т-аю на с-с-с-т-ттальгорнское от-т-деление П-п-астбищ Д-д-дымного л-леса... М-меня п-п-ослали на-найти п-пропавший груз, к-кок-гда на м-м-меня н-напала т-т-варь, каких я п-п-прежде и н-н-е в-видывал!$B$BКак же я з-з-з-ам-м-мерз-з-з...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7043, 'Прохладное чувство юмора', '$N, с-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства! Т-только ос-стор-р-рожно! Это он с-сделал из меня с-снеговика!$B$BВа-ва-вам понадобится помощь! Я в-видел, как он шляется тут в-в-вместе с другими йети. Он нав-верняка где-то п-поблизости! Отыщите мой груз, $N, отвезите его в Стальгорн, П-пастбищам Дымного леса, и п-п-передайте им, что м-меня надо разморозить!', 'Отыщите украденные лакомства и верните их Кардену Деньгозвону в Стальгорн. Лакомства должны быть у Омерзительного Гринча, который бродит где-то среди заснеженных вершин Альтеракских гор.', 'Вы нашли груз! Вы спасли наш праздник!$B$BБедный Сакс! Конечно же, мы немедленно отправим спасателей и придумаем, как его разморозить. Надеюсь, он успеет прийти в себя к празднику... Хотя, конечно же, потом ему придется отработать то время, которое он прогулял! Но в любом случае, если бы не вы, все пошло бы прахом!', '$N, без этих лакомств наш праздник Зимнего Покрова будет загублен на корню! Можете себе представить: все послушные детки останутся без знаменитых пирожков Гракку!', NULL, NULL, 'Украденные лакомства', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7044, 'Легенды Мародона', 'Повелитель сатиров, лорд Злоязыкий, сеет ужас по всем ходам-переходам этой пещеры, отравляя разум и чувства всех несчастных, оказавшихся внутри. Он живет за лиловыми кристаллами.$B$BКроме того, Злоязыкий создал живой символ собственного падения, Ноксиона, который живет за оранжевыми кристаллами. Эти двое похитили скипетр моего брата. Келебрас, мой брат... бессмысленно бродит по пещерам, снедаемый порчей.$B$BПомоги ему! Найди обломки скипетра и попробуй поговорить с моим братом.', 'Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса.Найдите способ поговорить с Келебрасом.', 'Теперь, когда мой жезл собран воедино, надеюсь, вскоре мы сумеем избавить Мародон от скверны.', 'Я очнулся от нескончамого кошмара...', NULL, NULL, 'Келебрийский бриллиант', 'Келебрийский жезл', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7045, '\"Пастбища Дымного Леса\" благодарны тебе!', 'Спасибо тебе от Пастбищ Дымного Леса за возвращение краденых сладостей, $N! И хотим мы тебе за это предложить особый подарок... От самого Дедушки Зимы!$B$BПоговори с Дедушкой Зимой, и он даст тебе подарок праздника Зимнего Покрова от нашего имени! От нашего села да к вашему столу, вкусная и здоровая пища от Пастбищ Дымного Леса... благодаря тебе, конечно же!', 'Поговорите с Дедушкой Зимой в Стальгорне.', 'Хо-хо-хо! Добро пожаловать!$B$BГоблины мне сказали, что тебе нынче полагается специальный приз, и я рад отдать его. Вот он – и веселого тебе праздника Зимнего Покрова каждый год!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7046, 'Скипетр Келебраса', 'Некогда скипетр был моей опорой и надежей. Он наделял меня властью над этими пещерами. Я надеялся умиротворить дух моего дяди... Теперь я передам это бремя тебе.$B$BДля того же, чтобы слить воедино обе половины скипетра, мне понадобится твоя помощь. Иди за мной и пока я буду призывать энергию, чтобы воссоединить жезл с бриллиантом, выполняй мои указания.$B$BВоссоздадим же совместными усилиями скипетр Келебраса!', 'Помогите Келебрасу Освобожденному воссоздать скипетр Келебраса.По завершении ритуала снова обратитесь к нему.', 'Прошу тебя, возьми этот скипетр и знай, что заключенная в нем сила должна служить лишь добру. Не останавливайся на достигнутом, иди дальше, вглубь пещер. Надеюсь, ты сумеешь отыскать останки моего дяди. Тебя подстерегает множество опасностей, $N.$B$BЕсли понадобится, можешь смело обращаться ко мне.', 'Если ты хочешь начать ритуал заново, останови его и снова обратись ко мне.', NULL, NULL, 'Создать скипетр Келебраса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7061, 'Пир Зимнего покрова', 'Вот, если тебе интересно узнать о празднике Зимнего Покрова побольше, прочти эту книгу. Я полагаю, что наше толкование легенды достаточно верное, и все же, как ученый, предпочитаю, чтобы вся информация была проверена.$B$BКогда дочитаешь, отнеси эту книгу в Громовой Утес Кэрну Кровавому Копыту. Ему наверняка приятно будет узнать, что кто-то еще интересуется преданиями нашего народа.', 'Прочитайте книгу \"Праздник Зимнего Покрова\". Отнесите книгу Кэрну Кровавому Копыту в Громовой Утес.', 'Предания и легенды, связанные с Зимним Покровом, с годами потускнели и забылись. Да, я знаю, что гоблины помогают возрождать этот праздник в своих собственных целях, но все же радует, что народ хоть как-то помнит о нем.$B$BТвое желание узнать еще больше о нем и о нашем прошлом весьма похвально, $C. Подобное стремление к мудрости можно лишь приветствовать.', 'Добро пожаловать в Мулгор и нашу скромную общину Громового Утеса, друг мой. Мне всегда были по нраву те, кому интересно наше королевство, его народ и его предания. Ты ведь поэтому здесь?', NULL, NULL, 'Пир Зимнего Покрова (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7062, 'Повод для праздника', 'Подарки, гости, угощение... чушь собачья!$B$BЭти гоблины искажают самую суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым ее укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!$B$BЕжели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте историка Карника из лиги Исследователей. Уверен, он будет очень удивлен, что кому-то история интереснее подарков.', 'Поговорите с историком Карником в лиге Исследователей в Стальгорне о празднике Зимнего Покрова.', 'Говорите, праздник Зимнего Покрова? Увы, в прежние времена для нас, дворфов, он имел гораздо более весомое значение. А теперь, похоже, другие используют легенду о Дедушке Зиме, чтобы продать побольше сладостей и подарков.$B$BНеудивительно, что Голли так огорчает эта перемена. Он и остальные дворфы держатся за наше прошлое, как за боевое знамя. Я лично считаю, что небольшой праздник никогда не помешает, но о его происхождении забывать нельзя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7063, 'Пир Зимнего покрова', 'Если вам интересно побольше узнать о празднике Зимнего Покрова, прочтите эту книгу. Хотя я и думаю, что наше толкование легенды вполне соответствующее, я все же ученый и буду рад, если мне удастся свести всю информацию воедино.$B$BКогда вы отправитесь к королю Магни Бронзобороду, отнесите ему эту книгу. Я точно знаю: ему приятно будет услышать, что кто-то еще интересуется старинными легендами.', 'Прочтите книгу \"Праздник Зимнего Покрова\", узнайте побольше о происхождении праздника. Закончив читать книгу, отнесите ее королю Магни Бронзобороду в Стальгорн.', 'Легенды и предания о Зимнем Покрове уже много лет подернуты дымкой забвения. Я понимаю, что гоблины возродили праздник ради собственных целей, но хорошо, что жители хотя бы так помнят о нем.$B$BВаше желание докопаться до истины и узнать о нашем прошлом – замечательное качество, юный $C. Меня радует ваша природная любознательность.', 'Добро пожаловать в королевство Стальгорн. Мне всегда по сердцу те, кто интересуется нашим королевством, его народом и его преданиями. Вы ведь ради этого явились ко мне?', NULL, NULL, 'Пир Зимнего Покрова (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7064, 'Яблочко от яблоньки...', 'В глубинах Мародона живет злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с Древними Богами. Когда-то, давным-давно, ее отыскал Зейтар, первый сын Кенария. Их... потомство зовется кентаврами. Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас. Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь.', 'Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от деревни Ночных Охотников в Пустошах.', 'Отличные новости, $N! Спасибо!$B$BЯ поговорю с Марандисом и спрошу его совета, как быть с останками Зейтара. Ну, по крайней мере, самая сложная часть задания выполнена.$B$BМне было предписано предложить эти предметы в награду тому, кто сумеет помочь нам. Выбери любой из них.', NULL, NULL, NULL, 'Принцесса Терадрас убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7065, 'Яблочко от яблоньки...', 'В глубинах Мародона живет злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с Древними Богами. Когда-то, давным-давно, ее отыскал Зейтар, первый сын Кенария. Их... потомство зовется кентаврами. Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас. Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь.', 'Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши.', 'Отличные новости, $N! Спасибо!$B$BХотя мне жаль, что ты не смог принести останки Зейтара, кто я, чтобы оспаривать волю первенца Кенария? Может быть, кентавры сумеют преодолеть собственную кровожадность – будем надеяться на лучшее.$B$BМне было предписано предложить эти предметы в награду тому, кто сумеет помочь нам. Выбери любой из них.', NULL, NULL, NULL, 'Принцесса Терадрас убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7066, 'Семя Жизни', 'Несчастные кентавры – мои дети – пропадут без отца.$B$BОглянись – это место исполнены надежды и того, чему учил мой отец, Кенарий. И все это произошло от меня! Я не могу лишить их своей поддержки... хоть они и обратились против меня.$B$BУ меня есть к тебе просьба – я хочу успокоить своего брата. Возьми это... первое семя жизни, родившейся из моих останков. Скажи ему, что я не погиб, а мой дух ныне пребывает здесь. Уверен, он меня поймет.', 'Найдите на Лунной поляне Ремула и отдайте ему семя жизни.', 'Итак, мой брат обрел покой? Я счастлив, что дожил до этого дня. Видя его гордость и гнев, я опасался, что он навеки потерян для нас... Но этот символ принесенной им жертвы доказывает, что он не погиб, но возродился для жизни вечной. Он занял свое место в природе, как и пристало ему.$B$BБлагодарю тебя, $N. Принеся мне дар от моего брата, ты посеял во мне надежду, которая, казалось, давно умерла. Я чувствую, что это семя еще принесет свой благой плод в этой истерзанной войнами земле.', 'От тебя несет скверной, как от большинства искателей приключений наших дней. Но ты отличаешься от остальных. О чем ты хочешь со мной поговорить? Я чую что-то знакомое, но не могу понять, что именно.$B$BПрошу тебя, скажи, почему ты хотел поговорить со мной?', NULL, NULL, 'Семя Жизни (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7067, 'Инструкции кентавра-парии', 'Хотя меня изгнали из племени как еретика, меня поддерживает вера. Только ей я и живу. Впрочем, мне не исполнить предначертанное без посторонней помощи... Причем помощи чужака, а не кентавра.$B$BКто-то должен войти в священные залы Мародона – гробницы, которую защищает мой народ, допуская внутрь лишь избранных.$B$BЕсли ты $gсогласен:согласна: помочь мне, стоит только кивнуть. Я отдам тебе свиток с инструкциями. Прочти его и обдумай мои слова.', 'Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей.', 'Вот он, вот амулет! Теперь мне предстоит долгое дело объединения племен. Спасибо.$B$BВот, возьми это за услуги. Надеюсь, мы еще встретимся в совсем другой обстановке.', 'Что ты решил, $N? Ты сможешь мне помочь? Ступишь ли ты на священную землю, чтобы помочь мне создать единый народ кентавров?!', NULL, NULL, 'Амулет Соединения', 'Инструкции кентавра-парии', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7068, 'Фрагменты осколка сумрака', 'Сильна магия в святом месте для кентавров, священном Мародоне. Племена кентавров Пустошей готовы биться за эти места до последней капли крови, но куда им! Мы свое возьмем!$B$BСтупай в ихний Мародон и найди там каменных тварей из осколков сумрака. Ты дашь Утель\'наю лиловые кристаллы, а уж он тебя не обидит!$B$BМеста там опасные, так что бери с собой друзей.', 'Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель\'наю в Оргриммар.', 'Ага, как раз то, что нужно для колдовства. Возьми одну из этих побрякушек и иди отсюда... У меня полно работы.', 'Ну как, нашел кристаллы? Ритуалы силы, могущественные заклятья... Одним словом, эти осколки очень и очень нужны всем знатокам тайных искусств.', NULL, NULL, 'Фрагмент осколка сумрака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7070, 'Фрагменты осколка сумрака', 'Я недавно начал испытания различных кристаллов и их магических свойств. Леди Праудмур позволила мне обратиться к путешественникам в Пустошах с просьбой отыскать там некое место, называющееся Мародон. В руинах храма поселились огромные каменные элементали, состоящие из лиловых кристаллов, которые я нарек осколками сумрака.$B$BЕсли ты решишь направиться в ту сторону и захватишь по пути несколько кристаллов, я буду очень признателен. Более того, я могу сделать тебе из них украшение.', 'Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей.', 'Отличные кристаллы, $N. На самом деле некоторые искатели приключений уже принесли мне образцы этих кристаллов, и из них я сделал эти украшение... Можешь выбрать любое из них. И еще раз спасибо. Чем больше образцов, тем лучше.', 'Ты уже побывал в Мараудоне? Понимаю, дело это опасное, но если ты достигнешь успеха, награда с лихвой окупит затраченные усилия.', NULL, NULL, 'Фрагмент осколка сумрака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7081, 'Кладбища Альтеракской долины', 'Кладбища в Альтеракской долине представляют собой очень большую ценность. И Орда, и Альянс свирепо дерутся за право обладать этими сакральными местами. $GГотов:Готова; ли ты вступить в эту схватку, $N?$B$BЯ хочу, чтобы ты $gзахватил:захватила: кладбище неприятеля. Найди кладбище с вымпелом Орды и вытащи из земли этот вымпел! Вот и все, задание выполнено.$B$BЕсли не сложно, можешь покараулить захваченное кладбище несколько минут, до прибытия наших войск.', 'Захватите кладбище, затем возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.', 'Отлично! Кладбища нам необходимы, чтобы удерживать контроль над Альтеракской долиной. Захватывая кладбища, ты помогаешь Альянсу отстоять свою независимость.$B$BА теперь ступай, $N. Возвращайся в бой, и если увидишь еще одно кладбище Орды... то ты знаешь, что надо делать!', '$N, ты еще не захватил кладбище. Возвращайся, когда задание будет выполнено!', NULL, NULL, 'Нападение на стойла совершено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7082, 'Кладбища долины Альтерака', 'Линия фронта в Альтеракской долине постоянно изменяется. Мы отступаем и снова отвоевываем территории в смертельной схватке с врагом. Особо яростные сражения идут за кладбища, $N.$B$BЯ приказываю тебе атаковать кладбище Альянса! Найди кладбище со знаменем Альянса в центре и вырви древко из земли!$B$BНа этом задание будет выполнено. Но тебе нужно будет подождать некоторое время, пока не придут наши войска.', 'Захватите кладбище, затем возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.', 'Отлично, $N! Если мы завладеем всеми кладбищами, духи врагов будут бесцельно слоняться по этим землям, не в силах помешать нам.', NULL, NULL, NULL, 'Нападение на стойла совершено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7101, 'Башни и бункеры', 'Башни и бункеры – основные защитные сооружения, так что все они должны быть нашими! Твое следующее задание – захват вражеского бункера.$B$BЗайди в бункер Альянса – над ним развевается их флаг. Внутри ты увидишь знамя. Сними его, и на его месте появится белое знамя Орды. Дело сделано!$B$BБольше ничего не нужно, но если ты немного подождешь и не дашь Альянсу отбить бункер обратно, то он самоуничтожится!', 'Захватите башню врага и возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.', 'Я слышала, задание успешно выполнено! Это хорошо...$B$BТеперь наши войска смогут безнаказанно продвинуться вперед и показать Альянсу, что ему не место в Альтеракской долине!', NULL, NULL, NULL, 'Башня захвачена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7102, 'Башни и бункеры', 'Башни и бункеры – основные защитные сооружения, так что у нас их должно быть как можно больше! Я приказываю тебе атаковать вражескую башню или бункер в Альтеракской долине.$B$BЗайди в бункер Орды – над ним развевается их флаг. Внутри ты увидишь вымпел. Сними его, и на его месте появится белое знамя Альянса. Дело сделано!$B$BНо на этом задание еще не закончено. Если ты продержишься рядом с башней некоторое время, чтобы ее не захватила Орда, то она разрушится!', 'Уничтожьте вымпел на вражеской башне или бункере и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.', 'Я получил отчет о том, что ты обезвредил вражеский вымпел. Отлично, $N! Теперь мы перенесем линию фронта на вражескую территорию.', NULL, NULL, NULL, 'Знамя уничтожено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7121, 'Интендант', '$N, интендант велел отправлять новых рекрутов к нему. Нам нужны припасы, которые хранятся в тайниках на рудниках Альтерака, так что, скорее всего, он отправит тебя за ними.$B$BСтупай по этой дороге на запад, там найдешь интенданта.', 'Поговорите с интендантом клана Грозовой Вершины.', 'Приятно видеть новых солдат, $N, но если повезет, ты скоро отправишься на задание и перестанешь быть новичком.$B$BПодойди ко мне через минутку, я дам тебе задание...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7122, 'Захват рудника', 'Рудники в Альтеракской долине – нечто большее, чем обычные сырьевые ресурсы. И клан Грозовой Вершины, и клан Северного Волка хранят на рудниках свои припасы. Одни – на Железном руднике, другие – на руднике Ледяного Зуба. Неплохо было бы захватить чужие припасы!$B$BЗахвати рудник и возращайся ко мне. Найди рудник, который никому не принадлежит, и убей того, кто там главный. После этого рудник перейдет к нам, и мы вышлем войска для его охраны.', 'Захватите рудник, который не принадлежит клану Грозовой Вершины, и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.', 'У тебя получилось! Прекрасная работа, $N! Теперь, когда рудник охраняют наши войска, добывать сырье и хранить припасы станет гораздо легче.', NULL, NULL, NULL, 'Рудник захвачен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7123, 'Разговор с интендантом', '$N, интендант клана Северного Волка набирает рекрутов для задания на рудниках Альтеракской долины. Поговори с ним, он расскажет тебе все подробно.$B$BСтупай в бункер по западной дороге, зайди в западный вход, там ты и найдешь интенданта.', 'Поговорите с интендантом клана Северного Волка.', 'Привет тебе, $N! Приятно видеть $C, который решил служить Орде. Обратись ко мне через минутку, я выдам тебе жизненно важное задание...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7124, 'Захват рудника', 'Битва, разгоревшаяся на землях Альтеракской долины, идет и за рудники – Железный и Ледяного Зуба. Они богаты сырьем, и к тому же их можно использовать для хранения припасов.$B$BПомоги нам, $N! Захвати один из этих рудников, во имя Орды! Отправляйся на рудник, который принадлежит нашим врагам, и убей того, кто там главный. Как только ты захватишь рудник, мы вышлем войска, чтобы взять его под охрану.', 'Захватите рудник и возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.', 'Ты захватил рудник! Мы вышлем туда охрану и сможем добывать сырье и хранить припасы.$B$BОтлично, $N. Ты оказал Орде неоценимую помощь в ведении боевых действий!', NULL, NULL, NULL, 'Рудник захвачен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7141, 'Битва за Альтерак', 'Лига исследователей уверена, что в Альтеракской долине есть артефакты, но клан Северного Волка не позволяет нам проводить здесь исследования. Не дадим Орде задушить наши благородные научные начинания! Уничтожь генерала клана Северного Волка, Дрек\'Тара. Без него орки ничего сделать не смогут.$B$BДрек\'Тара можно найти в крепости Северного Волка, на юге Альтеракской долины. Убей его и возвращайся.', 'Отправляйтесь в Альтеракскую долину, сразитесь с генералом Орды Дрек\'Таром и возвращайтесь к геологу Камнетерке в Альтеракские горы.', 'Прекрасная работа, $N! Орда не скоро оправится от смерти генерала, так что мы можем начинать наши исследования!', NULL, NULL, NULL, 'Нанесите поражение Дрек\'Тару', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7142, 'Битва за Альтерак', 'Дворфы из клана Грозовой Вершины вместе со своими союзниками вторглись в Альтеракскую долину, и мы должны выкинуть их отсюда! Если мы хотим выиграть битву за Альтерак наверняка, то нам нужно уничтожить их генерала, Ванндара Грозовую Вершину!$B$BЕго можно найти в Дун Болдаре, на севере Альтеракской долины.$B$BУбей его, $N, и возвращайся обратно ко мне.', 'Отправляйтесь в Альтеракскую долину и убейте генерала дворфов, Ванндара Грозовую Вершину. После этого возвращайтесь к Вогге Смертной Хватке в Альтеракские горы.', 'Отлично, $N! Зря Грозовая Вершина вторглась на эти земли. Себе дороже вышло!$B$BХа! Все, чего они добились – это смерти своего генерала!', 'Мы не потерпим дворфов на наших землях! Отправляйся к нашим врагам и убей их вождя, генерала Грозовую Вершину!', NULL, NULL, 'Убейте генерала Ванндара Грозовую Вершину', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7161, 'Испытательные земли', 'Приветствую, $C. Много времени прошло с тех пор, когда мы в последний раз внимали зову битвы. Трудно пробудить давно забытые чувства, но если они проснулись, обязательно прольется кровь. Ярость боя зовет нас...$B$BВ долине Альтерака все новички должны пройти боевое крещение.$B$BГлубоко в пещерах гноллов из стаи Дикой Лапы хранится знамя клана Северного Волка. Отправляйся туда и добудь его. Возвращайся ко мне вместе со знаменем, и получишь знак отличия новобранца.', 'Отправляйтесь в пещеры Дикой Лапы, расположенные на юго-востоке от основной базы в Альтеракской долине, и добудьте знамя клана Северного Волка. Отнесите знамя воеводе Лаггронду.', 'Это жгучее чувство означает, что твоя душа пробудилась и услышала зов битвы.$B$BТеперь ты – один из клана Северного Волка, $N. Поздравляю тебя.$B$BПостоянно носи с собой этот знак. По мере того как ты будешь продвигаться по службе в клане Северного Волка, я буду заменять его на другие, соответствующие более высокому званию.$B$BВозможно, однажды придет день, когда ты заслужишь полное уважение клана Северного Волка и получишь око командования.', 'Подъем! Подъем, $N! Это не сон! Ты и правда попал в самое пекло сражений!', NULL, NULL, 'Знамя клана Северного Волка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7162, 'Испытательные земли', 'Ты $gприбыл:прибыла: вовремя, $C. Эти дикари из клана Северного Волка ни в какую не желают сдаваться! Ничего, мы им покажем, на что способен клан Грозовой Вершины. Они склонятся перед нашей мощью!$B$BПеред тем, как отправиться в бой, ты $gдолжен:должна: вступить в ряды клана Грозовой Вершины.$B$BК юго-востоку от Дун Болдара находятся пещеры Ледяного Крыла. В их недрах хранится знамя клана Грозовой Вершины. Отправляйся туда и добудь его. Принеси знамя мне, и получишь отличительный знак новобранца.', 'Отправляйтесь в пещеры Ледяного Крыла в Альтеракской долине, на юго-западе от Дун Болдара, и добудьте знамя клана Грозовой Вершины. Отдайте знамя лейтенанту Хаггердину в Альтеракских горах.', 'Прими этот знак и носи его с честью, $N. Это символ твоего положения в Грозовой Вершине. Когда ты приобретешь уважение Грозовой Вершины, я выдам тебе другой знак.$B$BВозможно, в один прекрасный день ты станешь легендарным воителем и получишь Око Командования.', 'В этих землях следует опасаться гарпий, $C. Они не задумываясь вырвут тебе глотку.', NULL, NULL, 'Знамя клана Грозовой Вершины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7163, 'Награда найдет героя', '', '', 'Это знак особого расположения клана Северного Волка. Носи его с собой все время.$B$BИ вот что, $C... Придет время умирать – умри с честью!', NULL, NULL, NULL, 'Знак различия клана Северного Волка 1-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7164, 'Уважение клана', '', '', '<Воевода Лаггронд отдает салют.>$B$BСтупай, $N! Продолжай сражаться за клан Северного Волка! Мы должны выиграть эту войну! За Дрек\'Тара! За вождя!', NULL, NULL, NULL, 'Знак различия клана Северного Волка 2-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7165, 'Заслуженное почтение', '', '', '*Воевода Лаггронд рычит.*$B$BО твоих подвигах уже слагаются песни, солдат. Грозовая Вершина содрогается в страхе, слыша твое имя. Так держать!', NULL, NULL, NULL, 'Знак различия клана Северного Волка 3-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7166, 'Легендарные герои', '', '', 'Скоро ты окинешь бдительным оком все поля сражений! Ты примешь командование долиной Альтерака и всеми ее войсками!', NULL, NULL, NULL, 'Знак различия клана Северного Волка 4-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7167, 'Око Командования', '', '', 'Направь силу своего знака, и пусть враги услышат твой голос. Мощь Орды несокрушима!', NULL, NULL, NULL, 'Знак различия клана Северного Волка 5-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7168, 'Награда найдет героя', '', '', 'Пусть враги знают, что их поверг не простой солдат, а один из командиров Грозовой Вершины!', NULL, NULL, NULL, 'Знак отличия клана Грозовой Вершины 1-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7169, 'Уважение Стражи', '', '', 'Сам король наслышан о твоих подвигах на поле брани, $C. Продолжай с честью нести стражу Грозовой Вершины!', NULL, NULL, NULL, 'Знак отличия клана Грозовой Вершины 2-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7170, 'Заслуженное почтение', '', '', 'Когда мы встретились впервые, я не сомневался, что из тебя получится великая воительница. Носи свой знак с честью, солдат!', NULL, NULL, NULL, 'Знак отличия клана Грозовой Вершины 3-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7171, 'Легендарные герои', '', '', 'Без сомнения, ты сумеешь заслужить и Око Командования!', NULL, NULL, NULL, 'Знак отличия клана Грозовой Вершины 4-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7172, 'Око Командования', '', '', 'Ты поведешь нашу армию к победе, командир! Вот твое войско. Веди его в бой... Сокруши клан Северного Волка!', NULL, NULL, NULL, 'Знак отличия клана Грозовой Вершины 5-го ранга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7181, 'Легенда о Корраке', 'Вторжение клана Грозовой Вершины – это не единственная угроза в этих землях, солдат. Война в долине ведется на два фронта. Тролли-канибалы из племени Ледяной Секиры тоже представляют собой силу, с которой надо считаться.$B$BИх предводитель – Коррак Кровопуск – жестокая и коварная тварь.$B$BУбийство Коррака нанесло бы непоправимый удар племени Ледяной Секиры. Убей его и получи награду!', 'Согласно легенде, вождь могущественного племени Ледяной Секиры периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.Если Коррак появится, убейте его и возвращайтесь к воеводе Лаггронду.', '', NULL, NULL, NULL, 'Коррак Кровопуск убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7201, 'Последний элемент', 'У меня есть работа для тех, кто не боится заглянуть в глубины, $N. $B$BКлан Черного Железа научился создавать чрезвычайно мощных големов. $B$BИсходя из отчетов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. $B$BПодумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без нее можешь не возвращаться! Награда будет сопоставима с затраченными усилиями.', 'Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лягроб также бормотала что-то про элементалей.', 'Превосходно! Я немедля отправлю это с курьером в Подгород. $B$BЧто же до тебя, вот твоя плата, как я и обещала. Сдачу можешь оставить себе, грязное животное!', '*Потирает руки*$B$BНу, показывай скорее, что принес!', NULL, NULL, 'Суть Стихий', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7202, 'Коррак Кровопуск', 'Племя Ледяной Секиры, местные аборигены, имеют скверную привычку украшать свой стол блюдами из мяса наших солдат.$B$BНичего, мы им покажем, как с нами связываться!$B$BНам удалось добыть книгу, в которой записаны имена не только их знати, но и самого вождя, которое они тщательно скрывают! Его зовут Коррак Кровопуск.$B$BСмерть Коррака – это смерть всего племени Ледяной Секиры! Убей его и возвращайся.', 'Согласно легенде, вождь могущественного племени Ледяной Секиры периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.Если вам удастся найти Коррака, убейте его и возвращайтесь к лейтенанту Хаггердину в Альтеракские горы.', '', NULL, NULL, NULL, 'Коррак Кровопуск убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7221, 'Разговор с геологом Камнетеркой', 'А, $N, с докладом, да? Отлично.Клан Грозовой Вершины должен использовать всех, кто годится хоть на что-нибудь.$B$BПоговори с геологом Камнетеркой в Дун Болдаре. Она как раз набирает добровольцев для очень важного задания на вражеской территории. Ты найдешь ее в гарнизоне Дун Болдара, внизу.$B$BСмотри внимательно, когда будешь пробираться через Дун Болдар. Для $c, $gкоторый:которая:c: не чурается работы, здесь найдется много дел.', 'Поговорите с геологом Камнетеркой в гарнизоне Дун Болдара.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7222, 'Разговор с Воггой Смертобоем', '$C? Отлично! Мы рады видеть тебя в Альтераке, $N. Дворфы и их союзники вторглись в нашу долину, так что Орда приветствует каждого, кто решил вступить в праведный бой!$B$BПоговори с Воггой Смертобоем. Он как раз набирает агентов для важного задания в крепости Альянса в Альтеракской долине!$B$BВоггу можно найти в крепости Северного Волка.', 'Поговорите с Воггой в крепости Северного Волка.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7223, 'Обломки брони', 'В Альтеракской долине часто гремят сражения, и поставок из Стальгорна для нужд наших войск недостаточно.$B$BЕсли ты найдешь на поле боя обломки брони, приноси их мне, они нам пригодятся.', 'Принесите 20 обломков брони Мурготу Подземной Кузне в Дун Болдар.', 'Среди них попадаются весьма неплохие куски, $N. Я смогу сделать из них новую броню для наших войск.$B$BЕсли унас будет достаточно брони, то скоро новые войска смогут выйти на поле боя!', 'Удалось найти обломки, $N?', NULL, NULL, 'Обломки брони', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7224, 'Вражеский трофей', 'Если надешь на поле боя обломки вражеских доспехов, неси их мне. Из них выйдет отличная броня для наших собственных войск!', 'Принесите 20 обломков доспехов кузнецу Регзару в деревню Северного Волка.', 'Просто отлично. Я залатаю повреждения так, что никто и не отличит обломки вражеской брони от наших доспехов!$B$BСпасибо, $N. Хочешь, отполирую твои собственные доспехи?', 'Что, $N, попались обломки брони среди остальной добычи?', NULL, NULL, 'Обломки брони', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7241, 'Защита клана Северного Волка', 'Издалека доносится рокот барабанов войны, $C. Клан твоего вождя подвергается атакам презренных дворфов из клана Грозовой Вершины из Стальгорна. $B$BСудя по твоему виду, можно решить, что ты $gзакален в битвах и готов:закалена в битвах и готова: постоять за дело клана Северного Волка. $B$BА сейчас тебе предстоит сделать новый шаг к усовершенствованию твоего воинского мастерства. К северу от Мельницы Таррен, в Альтеракских горах, есть вход в Альтеракскую долину. Там тебе нужно отыскать воеводу Лаггронда.', 'Отправляйтесь в Альтеракскую долину, расположенную в Альтеракских горах. Найдите воеводу Лаггронда у входа в тоннель и поговорите с ним, чтобы начать свою военную карьеру в клане Северного Волка. Альтеракская долина находится к северу от Мельницы Таррен у подножия Альтеракских гор.', 'Чтобы стать солдатом Северного Волка, нужно сначала пройти испытания...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7261, 'Королевское право', 'Здесь, в Альтеракской долине, идут тяжелые бои. С одной стороны на нас наступают тролли-каннибалы из племени Секиры Зимы, с другой – дикари из клана Северного Волка. Во имя короля Магни Бронзоборода, все они должны быть уничтожены! Владение этими землями – неотъемлемое суверенное право королевства Стальгорн!$B$BК сожалению, солдаты не растут на деревьях. Доложись лейтенанту Мурпу рядом с Альтеракской долиной и с честью приступай к несению службы в Грозовой Вершине!', 'Отправляйтесь в Альтеракскую долину, к предгорьям Хилсбрада. Найдите лейтенанта Хаггердина рядом со входом в туннель и поговорите с ним.Во славу клана Бронзобородов!', 'За работу!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7281, 'Братская любовь', 'Ужасно... В сражении я столкнулся со своим братом, командором из клана Грозовой Вершины.$B$BИз всех четырех командоров клана Грозовой Вершины он самый опасный. Возможно, Королева-банши сможет возродить его после смерти, и тогда я докажу ему ошибочность его поступков...$B$BМой брат находится в глубине территории врага. Убей его и возвращайся ко мне. Я уверен, солдат, что у тебя хватит сил выполнить это задание.$B$BНо лучше не отправляйся в одиночку.', 'Отправляйтесь на территорию клана Грозовой Вершины и убейте командора Карла Филипса. После выполнения задания возвращайтесь к командору Луи Филипсу.', 'Твой героизм не останется незамеченным, Топблэйд.$B$BЕсли я хочу спасти брата, то нельзя терять ни минуты. Я должен немедленно обратиться к Сильване!', NULL, NULL, NULL, 'Командир Карл Филипс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7282, 'Братская любовь', 'Нужно избавить его от страданий, солдат! Воистину, он не ведает, что творит. Ужасная Королева-банши сделала его своей бездумной марионеткой.$B$BСтупай вперед, через поле брани, в глубину территории клана Северного Волка. Найди моего брата и уничтожь его. Его мучениям должен прийти конец.', 'Отправляйтесь на территорию клана Северного Волка и убейте командира Луи Филипса. После выполнения задания возвращайтесь к командиру Карлу Филипсу.', 'Надеюсь, ты не забыл сжечь тело?', NULL, NULL, NULL, 'Командир Луи Филипс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7301, 'Свергнутые властители небес', 'Мы взяли их в плен, $r. Мы захватили командиров звена. В небе разразилась яростная битва, но в итоге они все же уступили! К сожалению, во время контратаки против крепости Северного Волка были сбиты наши лучшие пилоты. Нужно выяснить, что с ними случилось. $B$BОбыщи западную смотровую башню и крепость Северного Волка. Там они были замечены в последний раз. Как можно тщательней осмотри эти районы.', 'Отправляйтесь в крепость Северного Волка и поищите командиров звена Слидора, Змейера и Ичмана. Вернитесь с отчетом к командиру Даффи.', 'Невероятно! Ты их освободил, да? Правда? Ну, по крайней мере, мы знаем теперь, где их держали.', NULL, NULL, NULL, 'Ичмен найден', 'Змейер найден', 'Слидор найден', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7302, 'Свергнутые властители небес', 'Наша воздушная поддержка в полном беспорядке, $N. Командиров звена сбили на вражеской территории. Ты $gдолжен:должна: узнать, что с ними стало, чтобы мы могли попытаться их спасти! $B$BГуса в последний раз видели над укрытием Ледяного Крыла. Боевую виверну Джезтора заметили у лесопилки Грозовой Вершины. Маэстр... кто-то видел, как этот безголовый идиот разбился возле северного оплота Дун Болдара. $B$BЭто вся информация, что у меня есть. За дело! Как следует прочеши указанные районы.', 'Выясните, что стало с командирами звена Гусом, Джезтором и Маэстром. Вернитесь с отчетом к командиру Мулфорту.', 'Отличная работа! Собранная тобой информация поистине бесценна.', NULL, NULL, NULL, 'Гус найден', 'Джезтор найден', 'Найдите Маэстра', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7321, 'Нежный черепаховый суп', 'Кто сказал, что нежить не понимает в кулинарии? Взять, к примеру, мой заветный рецепт нежного черепашьего супа. Да я знаю народ, что из мертвых бы восстал, только бы скушать тарелочку! Хе-хе...$B$BКстати, в последнее время мне ни тарелочки приготовить не удалось. Обычно я сам ходил на озеро Лордамер ловить хрустогрызов – у, грязные тварюги – но не могу сейчас бросить работу.$B$BЕсли ты добудешь мне немного черепашьего мяса, я научу тебя варить такой суп!', 'Принесите 10 кусков черепашьего мяса Кристофу Френчу на Мельницу Таррен.', 'Мой нежный черепаший супчик согреет тебя холодной ночью... Если, конечно, ты еще помнишь, что такое холод.', 'Повезло добыть ингредиенты? Надо сказать, нынче эти места просто кишат подонками из Альянса... По мне, они уже зашли слишком далеко...', NULL, NULL, 'Черепашье мясо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7341, 'Честная сделка', '', '', 'Отлично! Я – таурен слова, $R. Вот тебе твои стрелы.', NULL, NULL, NULL, 'Ториевые патроны (200)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7342, 'Стрелы – для неженок!', '', '', 'Добрая сделка, если я что-то в этом понимаю! Стрелы – твои.', NULL, NULL, NULL, 'Ториевые патроны (200)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7367, 'Обезвредить угрозу', 'Клан Северного Волка позволил заманить себя в совершенно идиотскую ловушку, $C. Надо быть более осмотрительным, действуя на территории врага.$B$BЕсли хочешь нанести им ощутимый удар, нужно уничтожить того, кто отвечает их за минные поля, – я говорю об эксперте по взрывчатым веществам. Пока он жив, минные поля существуют. Но если он будет мертв, поддерживать их станет некому.$B$BНе исключаю, что эксперта можно найти в башне рядом с гарнизоном Стылой Крови. Удачи тебе!', 'Найдите эксперта по взрывчатым веществам из клана Северного Волка и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Грозовой Вершины.', '', NULL, NULL, NULL, 'Эксперт по взрывчатке из клана Северного Волка убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7368, 'Обезвредить угрозу', 'Про противопехотные мины я знаю все. Именно я, а не кто-нибудь, отвечаю за мины на всей линии фронта.$B$BЕсли ты хочешь обезвредить все минные поля клана Грозовой Вершины, сначала надо убить их эксперта по взрывчатым веществам. Этот трусливый дворф скорее всего прячется в первой башне поля брани. Убей его, и минные поля будут обезврежены раз и навсегда.$B$BКак убьешь его, возвращайся ко мне. Добрые дела не должны оставаться без награды.', 'Найдите эксперта по взрывчатым веществам из клана Грозовой Вершины и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Северного Волка.', '', NULL, NULL, NULL, 'Эксперт по взрывчатке из клана Грозовой Вершины убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7383, 'Венец Земли', 'Но не все было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила.$B$BНо пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне.', 'Наполните аметистовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар.', 'Находиться в присуствии Древа-оракула... это все равно что увидеть воплощенную мудрость. Позволь мне продолжить...$B$BТельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена. Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности. Алекстраза также отказала Оленьему Шлему, а без ее благословения рост Тельдрассила стал непредсказуем, и в нем обнаружились изъяны...', 'Друиды, Древо-оракул и верховный друид тщательно наблюдали за ростом Тельдрассила. Но хотя мы и обрели новый дом, бессмертие к нам не вернулось.', NULL, NULL, 'Наполненный аметистовый фиал', 'Аметистовый фиал', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7385, 'Галлон крови', '', '', 'И вновь пролилась кровь наших врагов. Я смешаю ее с той, что уже собрана. Когда крови будет столько, сколько нам нужно, Владыка Льда покажет этим собакам с Грозовой Вершины, что значит ярость клана Северного Волка!', NULL, NULL, NULL, 'Кровь солдата из клана Грозовой Вершины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7386, 'Гроздь кристаллов', '', '', 'Отлично, $N. Сила этих чар пригодится для усиления уже имеющейся магии. Когда энергии наберется достаточно, я смогу ее сфокусировать и воззвать к Владыке Леса о помощи.', NULL, NULL, NULL, 'Кристалл Бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7429, 'Освободите Нотта!', '', '', 'Вы для меня – номер один во всем мире! Все остальные – после вас! Ох, большое вам спасибо, что освободили меня!$B$BЯ знал, я знал, что меня ждет более достойная участь, чем пойти на обед какому-нибудь огру!', NULL, NULL, NULL, 'Ключ от оков Гордока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7441, 'Пузиллин и старейшина Аж\'Тордин', 'Представь себе, $gчужестранец:чужестранка:: стоило мне зазеваться всего на секунду!.. я был очень занят: спасался от принца-отступника... – и меня тут же обворовали! Гнуснейший демон, бес Пузиллин, стащил мою книгу заклинаний, и ключ от некогда прекрасных чертогов Эльдре\'Таласа!$B$BКлюч мне теперь ни к чему: я обменял свое бессмертие на свободу, – но книга мне нужна позарез!$B$BОтыщи мне этого беса Пузиллина, и добудь у него книгу!$B$BИщи его в Квартале Криводревов Забытого Города.', 'Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж\'Тордина.Если добудете книгу, вернитесь к Аж\'Тордину в павильон Лорисс в Фераласе.', 'Тебе удалось ее найти! Будь проклят этот несчастный бесенок... Увы, имущества у меня, мягко говоря, немного. Придется тебе выбирать из того, что я могу предложить...', 'Я ни о чем не жалею, чужестранец. Королевы давно уже нет в живых. Труды Шен\'дралар осквернены безумием принца Тортелдрина. Я жажду лишь свободы... Освобождения...', NULL, NULL, 'Книга магических формул', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7461, 'Древнее безумие', 'Ну что, этого тебе достаточно? Надеюсь, ты не устрашишься вступить в бой?$B$BЭтому безумию пора положить конец! Время бессмертных давным-давно миновало. Уничтожь стражей, охраняющих столпы, и ликвидируй силовое поле. А потом убей Пламе\'тара. Это лишит принца большей части его силы, и тогда ты сможешь убить и его тоже. Помоги духам этого города упокоиться в мире!', 'Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией тюрьму Пламе\'тара. После того как столпы угаснут, силовое поле, удерживающее Пламе\'тара, рассеется.Войдите в тюрьму Пламе\'тара и уничтожьте злобного демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.Если задание будет выполнено успешно, вернитесь во двор, к древней Шен\'дралар.', 'Мы благодарим тебя, герой!', 'Будь осторожнее! Принц умеет заговаривать зубы...', NULL, NULL, 'Пламе\'тар убито', 'Принц Тортелдрин убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7462, 'Сокровище Шен\'драларов', 'В библиотеке, Читальне, ты найдешь древний сундук, спрятанный под лестницей. Можешь взять оттуда, что тебе понравится.', 'Вернитесь в Читальню и найдите сокровище Шен\'драларов. Получите свою награду!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7463, 'Магический напиток', 'А-а, $r, $gпосвятивший:посвятившая:r:себя магии! Удивительно. Я не видывал подобных тебе уже... сколько? Которое у нас тысячелетье на дворе? Да уже лет пятьсот!$B$BУ меня есть кое-что, что поможет утолить твою жажду, но сначала тебе придется выполнить одно мое поручение.$B$B<Лидрос хихикает.>$B$BВ Эльдре\'Таласе завелась аномалия. В восточном крыле поселился элементаль воды. Надо его... того... занести в каталог.$B$BСтупай в квартал Криводревов, и добудь мне частицу стихийной сущности Гидротвари. Принеси ее мне, а я тебя научу одной полезной штучке!', 'Отправляйтесь в квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.', 'Чудесно! Да, а ты кто такой? А, впрочем, неважно! Так что я должен был тебе дать? А-а, ну, ты вроде бы маг, так что тебе, возможно, пригодится вот это...', 'Да? Мы где-то встречались?', NULL, NULL, 'Сущность Гидротвари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7481, 'Эльфийские легенды', 'Несколько лет тому назад одинокий эльфийский мастер по имени Тельмий Сновидец бежал из своей разоренной родной земли, унеся с собой несколько древних эльфийских артефактов.$B$BПоиски пропавшего мастера привели нас из руин Кель\'Таласа через Пылающие степи и морские просторы в Фералас.$B$BМы подозреваем, что эльф искал убежища в залах Эльдре\'Таласа (ныне известного как Забытый Город).$B$BОтыщи его, $gстранник:странница:! Жив он или мертв, а знания, которые он унес с собой, отыскать необходимо!', 'Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в Лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать.', 'Какое горе! Какая трагедия! Так ты говоришь, все пропало? И никаких следов Кариэля?', NULL, NULL, NULL, 'Найдите Тельмия Сновидца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7482, 'Эльфийские легенды', 'Несколько лет тому назад одинокий эльфийский мастер по имени Тельмий Сновидец бежал из своей разоренной родной земли, унеся с собой несколько древних эльфийских артефактов.$B$BПоиски пропавшего мастера привели нас из руин Кель\'Таласа через Пылающие степи и морские просторы в Фералас.$B$BМы подозреваем, что эльф искал убежища в залах Эльдре\'Таласа (ныне известного как Забытый Город).$B$BОтыщи его, $gстранник:странница:! Жив он или мертв, а знания, которые он унес с собой, отыскать необходимо!', 'Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в крепость Оперенной Луны к исследовательнице Рунический Шип и сообщите ей все, что вам удалось узнать.', 'Какое горе! Какая трагедия! Так ты говоришь, все пропало? И никаких следов Кариэля?', NULL, NULL, NULL, 'Найдите Тельмия Сновидца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7483, 'Манускрипт Скорости', 'Мастер Сновидец потерял \"Манускрипт Скорости\" в восточном крыле. Этот манускрипт позволит тебе наложить на все свое снаряжение небольшое ускоряющее заклятие. Детские игрушки, на самом деле…$B$BТем не менее, если тебя это интересует, принеси мне манускрипт и кое-какие необходимые реагенты.$B$BХм... Насколько я помню, там требуется кровь героев, безупречный черный алмаз и большие сияющие осколки. Впрочем, я могу и ошибаться!$B$B*Лидрос пожимает плечами.*', 'Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Скорости\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 2 образца крови героев, чтобы получить магический камень стремительности.', '*Лидрос зевает.*$B$BНу, вот тебе твой магический камень стремительности, как и было обещано. Только не стремись извести его сразу!$B$B*Лидрос хихикает.*', 'Чего тебе? Я с каталогом работаю!', NULL, NULL, '\"Манускрипт Скорости\"', 'Нетронутый черный алмаз', 'Большой сверкающий осколок', 'Кровь героев');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7484, 'Манускрипт Средоточия', 'Этот манускрипт едва не вызвал интерес у одного из юных фамильяров хранителя мудрости! Бедняжка, ему было всего несколько недель от роду!$B$BТем из вас, кто интересуется магией, этот манускрипт может пригодиться!$B$BОн пропал где-то в этом крыле. Могу только предположить, что его прибрал к рукам один из духов высокорожденных.$B$BПринесите мне \"Манускрипт Средоточия\", несколько больших сияющих осколков, шкуру тени и безупречный черный алмаз, и я создам для вас магический камень.', 'Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Средоточия\", 1 безупречный черный алмаз, 4 больших сияющих осколка и 2 образца шкуры тени, чтобы получить магический камень сосредоточения.', 'Смотри, $R, не покалечься, когда будешь пускать его в ход!', 'Снова ты? Ну, а теперь-то тебе чего надо?', NULL, NULL, '\"Манускрипт Средоточия\"', 'Нетронутый черный алмаз', 'Большой сверкающий осколок', 'Шкура тени');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7485, 'Манускрипт Защиты', 'Потеряв этот манускрипт, он рыдал, как ребенок! Не пойми меня неправильно – мне и самому случалось плакать из-за книг, ведь нет большей утраты, чем утраченные знания, – но рыдать из-за этих почти бесполезных обрывков заклинаний? Абсурд! Мне даже подумалось, что принц, пожалуй, оказал ему услугу, отделив его плоть от костей.$B$BПринеси мне этот манускрипт вместе с безупречным черным алмазом, большими сверкающими осколками и истлевшей шовной нитью поганища, и я воссоздам этот магический знак!$B$BАх, да: в общем, ищи в северном крыле.', 'Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Защиты\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 1 потертый шовный материал поганища, чтобы получить магический камень защиты.', 'Да-да! Успокойся. Вот твой магический знак, как я и обещал.', 'Радуйся, что я такой терпеливый, а то бы я тебе...', NULL, NULL, '\"Манускрипт Защиты', 'Нетронутый черный алмаз', 'Большой сверкающий осколок', 'Истлевшая шовная нить поганища');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7486, 'Награда для героя', '$N, твои заслуги перед Повелителями Вод превосходят самые смелые ожидания. Мы не могли предположить, что обитатель этого мира может обладать подобной силой!$B$BНе знаю, как у твоего народа принято выражать благодарность, однако могу пообещать тебе щедрую награду.$B$BОтправляйся в южную часть острова и найди сундук, сокрытый в волнах. В том сундуке твоя награда.$B$BИди, $N. Забери свою награду.', 'Заберите свою награду из сундука Гидраксиса.', '*Голос Гидраксиса вторит рокоту прибоя* $B$BВыбирай, что тебе по душе, $N. Пусть мой дар защитит тебя от недругов Повелителей вод.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7487, 'Сродство с недрами', 'Земля испещрена трещинами и разломами – прямо у нас под ногами, $r. В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра в Черной горы, в самую вотчину Повелителя огня.$B$B<Удивлен:Удивлена:? Прискорбно... Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб...$B$BУверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться.$B$BСмотрю, у тебя глаза заблестели. Послушай, приобрести сродство с недрами не так сложно. Отправляйся в Глубины Черной горы и принеси мне осколок из Огненных Недр. Я сделаю так, что ты сможешь видеть портал.', 'Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе.', '', NULL, NULL, NULL, 'Осколок из Огненных Недр', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7488, 'Сеть Лефтендрис', 'Маг Лефтендрис, злокозненная эльфийка крови, чья жестокость уступает лишь ее извращенной приверженности к магии, бежала в Забытый Город! Она создала магическое устройство: сеть, улавливающую энергию этого места, – и мы опасаемся, что, если Летендрис не остановить, она нанесет непоправимый урон нашему миру!$B$BОстанови ее, $N. Отыщи ее и отними у нее эту сеть. Она, скорее всего, где-то неподалеку от сатиров в Квартале Криводревов Забытого Города. Принеси эту сеть мне, чтобы мы могли осторожно выпустить захваченную ею энергию на свободу...', 'Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе.', 'Тебе удалось добыть сеть! Молодец, $N! Лефтендрис, как и многие ей подобные эльфы, совершенно не задумывается о том, чем необузданное применение магии может грозить нашему миру. Они мнят себя владыками магии, не сознавая, что они всего лишь рабы своей собственной зависимости. Ее смерть печалит меня, но это было необходимо.$B$BСпасибо тебе, $N. Энергию, накопившуюся в сети, мы осторожно выпустим на свободу в глуши, а саму сеть я уничтожу, чтобы она не попала в руки еще какому-нибудь безумному магу.', 'Ну что, $N, сеть у тебя? Скопившуюся в ней магическую энергию необходимо рассредоточить!', NULL, NULL, 'Сеть Лефтендрис', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7489, 'Сеть Лефтендрис', 'Эльфийка крови Лефтендрис перешла все мыслимые границы! Она так жаждала все новой магической энергии, что бросила вызов своим собратьям и создала хитроумное устройство, сеть, предназначенную для того, чтобы всасывать отравленную магию Забытого Города. Она и теперь собирает эту энергию, намереваясь использовать ее против своих врагов!$B$BЛефтендрис необходимо остановить. Отыщи ее в Квартале Криводревов в Забытом Городе, повергни ее и принеси ее сеть мне, чтобы мы могли передать ее для изучения более здравомыслящим эльфам крови.', 'Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе.', 'Молодец, $N! Эта сеть содержит в себе большие запасы магической энергии Забытого Города, и я опасался, что, если этой магией овладеет столь безответственное существо, как Лефтендрис, последствия могут быть непредсказуемыми. Ее смерть меня, конечно, печалит, но я понимаю, что живой бы она с этой сетью не рассталась.$B$BСпасибо тебе, $N. Я отправлю эту сеть более трезвомыслящим специалистам по магии, чем Лефтендрис. Им такую мощь доверить можно...', 'Ну что, $N, сеть Лефтендрис у тебя?', NULL, NULL, 'Сеть Лефтендрис', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7490, 'Победа Орды', 'Тебе удалось совершить невозможное! Царица черных драконов лежит мертвой у твоих ног. Отруби ей голову и отнеси ее своему вождю.', 'Отнесите голову Ониксии Траллу в Оргриммар.', 'Это великая победа для Орды, $N. Тебе уже не раз случалось постоять за честь своего вождя. Пришла пора и вождю оказать тебе честь!', '*Когда Тралл видит громадную голову Ониксии, его всегдашнее самообладание на миг ему изменяет. Тралл уже готов схватиться за свой легендарный Молот Рока!*', NULL, NULL, 'Голова Ониксии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7491, 'На виду у всех', 'Властитель Рунтак ожидает тебя в Аллее Силы.$B$B<Тралл отдает вам честь.>$B$BНе заставляй его ждать, герой!', 'Найдите властителя Рунтака в Аллее Силы.', 'Выбери себе награду, и мы достойно отпразднуем твою победу!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7492, 'Лагерь Мохаче', 'Тало Терновое Копыто, тауренский старейшина, живущий в Фераласе, прислал просьбу о помощи. Подробностей он не сообщает, но говорит, что ему требуются агенты для тонкой... и опасной работы!$B$BПослужи Орде, $N. Отправляйся в Лагерь Мохаче в Фераласе и поговори с Тало.', 'Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе.', 'А, приятно видеть, что $C откликнулся на мой призыв! Мне нужна твоя помощь, $N. Но боюсь, что это дело заведет тебя на опасный путь…$B$BЭтот путь лежит в Забытый Город.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7493, 'Все еще только начинается!', '', '', 'Драконоубийца и опытный кожевник:опытная кожевница;? Ты не перестаешь изумлять меня, герой. Я сражен.Пожалуйста, прими как дар то, чему я собираюсь тебя научить. Это знание окажется бесценным для тебя, если ты намерен уничтожить последних черных драконов.Изготовь плащ из чешуи драконьей царицы. Он будет защищать тебя и твоих союзников от опаляющего дыхания владыки Черной горы... Нефариана.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7494, 'Крепость Оперенной Луны', '$N! Твоя помощь нужна в Фераласе!$B$BЛефтендрис, маг, объявленный вне закона, бежала в развалины древнего эльфийского города Эльдре\'Таласа, ныне именуемого Забытым Городом. Есть основания предполагать, что у нее с собой мощный магический артефакт, который необходимо вернуть.$B$BЛатроникус Лунное Копье ищет агентов, которые согласились бы отправиться в Забытый Город и отнять у Лефтендрис этот артефакт.$B$BПослужи Альянсу! Отправляйся к Латроникусу. Он находится в Крепости Оперенной Луны в Фераласе.', 'Поговорите с Латроникусом Лунным Копьем в Крепости Оперенной Луны в Фераласе.', 'Привет тебе, $N. Рад тебя видеть, но предпочел бы встретиться с тобой в более приятных обстоятельствах.$B$BСлушай внимательно, у меня для тебя жизненно важное задание...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7495, 'Славная победа Альянса', 'Вы совершили невозможное. Царица черных драконов лежит мертвой у ваших ног. Возьмите ее голову и передайте ее королю Вариану Ринну.', 'Отнесите голову Ониксии королю Вариану Ринну в Штормград.', 'Долгие годы я жил под ее дурманящим взором. Наконец-то правосудие свершилось, а честь Штормграда восстановлена! Сегодня мы празднуем великую победу!', 'Ох ты, клянусь бородой Утера!', NULL, NULL, 'Голова Ониксии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7496, 'Праздник добрых времен', '$N, найди майора Маттингли в Аллее Героев. Он будет тебя ждать...', 'Найдите майора Маттингли в Аллее Героев.', '$N, немногие были удостоены подобной церемонии. Прошу, выбери свою награду, и мы начнем праздник!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
