INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7505, 'Ледяной шок и вы', 'Том помечен печатью Читальни.', 'Верните книгу законным владельцам.', 'Отличная работа, $R. Если найдете еще какие-то книги, несите их нам, не раздумывая.$B$BСо временем мы подбираем все новые награды за возвращение пропавших экземпляров!', 'Вы ее нашли!', NULL, NULL, '\"Ледяной шок и вы\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7506, 'Изумрудный Сон', 'Том помечен печатью Читальни.', 'Верните книгу законным владельцам.', 'Отличная работа, $С. Если найдете еще какие-то книги, несите их нам, не раздумывая.$B$BСо временем мы подбираем все новые награды за возвращение пропавших экземпляров!', 'Вы ее нашли!', NULL, NULL, 'Изумрудный Сон (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7507, 'Nostro\'s Compendium', 'Вы обнаружили нечто очень важное. Эта книга не похожа ни на одну из тех, которые вам доводилось видеть раньше.$B$BТакое впечатление, как будто кому-то удалось испортить печать Читальни. Текст искажен и читается с трудом.', '', 'На черном рынке ты мог бы получить за эту книгу немало золота, $N! Тем более, что защитная печать теперь сломана, так что тайны драконоборчества доступны любому, кому хватит любопытства, чтобы овладеть знаниями, сокрытыми на священных страницах!$B$BВозможно, ты заслуживаешь ценной награды... Точнее, награды, которую придется добывать ценой громадных усилий!$B$B*Лидрос ухмыляется.*', 'О, одна из наших лучших компиляций! Я ее уже лет триста не мог отыскать...', NULL, NULL, 'Справочник Ностро по истреблению драконов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7508, 'Ковка Кель-Серрара', 'Если хотите взять на себя эту задачу, отнесите тусклый клинок Лидросу.', 'Отдайте тусклый и плоский эльфийский клинок сказителю Лидросу.', 'Если тебе удастся войти в логово драконицы, раскали клинок в ее огненном дыхании, а потом остуди в ее собственной крови. И тогда клинок будет навеки твоим.', 'Отлично! Ну-с, начнем...', NULL, NULL, 'Тупой плоский эльфийский клинок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7509, '', '', '', '*Лидрос бормочет нечто невнятное.*$B$BНу, $C, вот тебе клинок Кель-Серрар, как и было обещано.', 'Быть может, в один прекрасный день радужным клинком будет владеть другой...', NULL, NULL, 'Закаленный древний клинок', 'Неопалимый древний клинок', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7541, 'Служба Орде', '', '', 'Нашим ученым нужно время, чтобы изучить принесенную тобой подвеску. Но за то, что ты сделал для Орды, я хочу наградить тебя этим знаком.Спасибо, $N, твой поступок делает честь тебе и полезен нам.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7562, 'Мор\'зул Вестник Крови', 'Ты хорошо $gизучил:изучила: темные искусства и $gобрел:обрела: такую власть над существам из других миров, что... быть может, пришло время подчинить себе одного из знаменитых коней погибели.$B$BВызвать его в наш мир нелегко, для этого потребуется великая сила и большие затраты, но если ты хочешь владеть таким скакуном, поговори с Мор\'зулом Вестником Крови. Он разбил лагерь рядом с Алтарем Бурь в Пылающих степях.$B$BСтупай, $N. Задание рискованное, но такие чернокнижники как ты не страшатся опасностей.', 'Поговорите с Мор\'зулом Вестником Крови у Алтаря Бурь в Пылающих степях.', 'Привет тебе, $N, и добро пожаловать. Ты пришел сюда ради Алтаря Бурь? Может быть, ты хочешь овладеть его силой ради тайных целей…$B$BИли... просто хочешь поговорить со мной? Да, кажется именно так.$B$BТы хочешь обуздать коня погибели? Нелегкая цель. На это уйдет немало крови, пота и... золота, конечно. Впрочем, конь погибели Зорота стоит того, поэтому слушай...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7563, 'Ярость крови', 'Кони погибели живут в другом мире, на огненных равнинах Зорота, и чтобы подчинить себе одного из них, необходимы могущественные руны. Я могу начертать эти руны на пергаменте, но для этого нужны особые чернила.$B$BВ далеких Зимних Ключах живут зверосовы. Некогда они были чистыми существами, но демоническое влияние Теснины Зловещего Шепота лишило их разума, и они бродят по снегам в полном безумии.$B$BИз их крови я и сделаю чернила. Остается ее добыть.', 'Принесите 30 бутылок крови яростных зверей Мор\'зулу Вестнику Крови в Пылающие степи.', 'А, замечательно. Я переработаю эту кровь в чернила и сделаю обещанный тебе пергамент. Может, я немножко оставлю себе, говорят, вкус у нее необыкновенный...', 'Ты уже видел бешеных отродий, $N? Эти твари исполнены магии, и почти вся она сосредоточена у них в крови.', NULL, NULL, 'Кровь яростного зверя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7564, 'Дикоглаз', 'Мой слуга, Горзиеки, довольно опытный алхимик. Он сможет приготовить чернила, о которых шла речь. Я уже подготовил принесенную тобой кровь; отнеси ее Горзиеки, пусть приступает к работе.', 'Принесите ларец Крови Горзиеки Дикоглазу в Алтарь Бурь, что в Пылающих степях.', 'А, это кровь. Наверняка от мастера Морзула. Он ее обожает, и любит, когда она проливается. Я же предпочитаю, чтобы она текла по жилам маленького грызуна. Тогда она остается теплой... до употребления.$B$BВ этой крови заключена великая сила. Наверное, Морзул хочет создать еще один пергамент для призыва коня погибели! Ух, как интересно!$B$BКоли так, то проводить ритуал будешь ты и... тебе понадобится не только кровь.', 'Ты что-то принес? Уж не большого ли и сочного паука? Или таракана? Хоть бы живого... Мне так нравится, когда они еще шевелятся во рту...', NULL, NULL, 'Ларец Крови (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7581, 'Тюремные кандалы', 'Ты $gдолжден:должна: добыть у младших демонов кандалы для стражника ужаса.$B$BКровь сатира из племени Буйного Нрава, что живут в Забытом Городе, для этого сгодится. Свернувшаяся кровь скрепит осколки Хедерины и даст силу хрустальной темнице.', 'Отправляйтесь в Забытый Город, что в Фераласе и добудьте 15 порций крови сатиров из племени Исчадий Природы, что живут в Квартале Криводревов. Вернитесь к Дайо из Гниющего шрама по выполнении поручения.', 'Ах, просто замечательно! Эта кровь подавит магическое сопротивление стражника ужаса.', 'Подойдет только кровь сатиров из племени Исчадий Природы.', NULL, NULL, 'Кровь сатира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7582, 'Тюремная камера', 'Демоны Хедерины, что живут у подножия горы Хиджал, выделяют яды Скверны, которые вызревают и твердеют, образуя антимагические кристаллы. Они известны как слезы Хедерины.$B$BДаже чудовищная сила стражника ужаса не сможет разбить стены тюрьмы, сделанной из этого материала.$B$BОтправляйся в Теснину Зловещего Шепота в Зимних ключах, и добудь этих слез.', 'Отправляйтесь к Теснине Зловещего Шепота в Зимних ключах и добудьте 5 слез Хедерины у демонов Хедерины, что населяют эту теснину. Вернитесь к Дайо из Гниющего шрама по выполнении поручения.', '', NULL, NULL, NULL, 'Слезы Хедерины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7583, 'Подавление', 'Темница готова. Теперь самое трудное дело.$B$BТы $gдолжен:должна: найти и схватить командира стражников ужаса в Гниющем шраме при помощи этой хрустальной темницы.$B$BОсторожнее! Стражник ужаса -коварный и смертельный враг, он будет пытаться уничтожить тебя, как только ты начнешь обряд заточения. Он будет отчаянно отбиваться, пытаясь избежать плена.$B$BОн будет смотреть только на тебя, $N. Потому я рекомендую взять с собой друзей, которые не дадут ему погубить тебя!', 'Отправляйтесь в Гниющий шрам и и найдите командира стражников ужаса.При помощи светящегося кристалла заточения поймайте командира стражников ужаса. Будьте готовы к отчаянным атакам и сопротивлению, поскольку демон будет пытаться избежать заточения.Если вы добьетесь успеха, отнесите пленного стражника ужаса Дайо в Гниющий шрам.', 'Ты сделал все, как я просил. Теперь ты готов воспринять знание о том, как призывать и контролировать тварей.', 'Ну? Как?', NULL, NULL, 'Плененный страж ужаса', 'Светящийся кристалл Заточения (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7601, 'Что хочет Ниби', 'Если хочешь научиться у меня призывать инфернала-слугу, ты $gдолжен:должна: убить Крошиуса и добыть из его пылающих останков огненное ядро. Но это не так просто, как кажется. Крошиус чуть не дотла сгорел. Тебе придется снова воспламенить его тело и поднять его из праха. Но для этого тебе придется добыть другие ингредиенты из других демонических сущностей.$B$BМой бес по имени Бесенок покажет тебе дорогу.', 'Поговорите с Бесенком в Оскверненном лесу.', 'Ох, опять двадцать пять...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7602, 'Безупречная субстанция Скверны', 'Если ты намереваешлся воскресить Крошиуса, тебе понадобится пламя Скверны. Я могу зажечь его, но для этого потребуются кое-какие ингредиенты.$B$BТебе придется принести мне безупречной субстанции Скверны из трех краев нашего мира.$B$BПервый тип субстанции ты найдешь у сатиров из племени Легаши, что в Азшаре. Второй тип – у джеденарских легионеров, а третий можно добыть у стражей Скверны в Выжженных землях.$B$BПринеси мне по порции каждой субстанции, и я зажгу пламя скверны, что позволит тебе оживить Крошиуса.', 'Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест.Безупречной субстанцией в Азшаре владеют сатиры из племени Легаши. В Джеденаре она есть у джеженарских легионеров. Стражи Скверны в Выжженных землях владеют этой субстанцией в своих краях.Добудьте три типа безупречной субстанции Скверны и возвращайтесь к Бесенку в Оскверненный лес.', 'Одну минуточку, и я сотворю из всех трех субстанций пламя Скверны.', 'Ты только никому не говори, что Ниби дурак.', NULL, NULL, 'Безупречная субстанция Скверны (Азшара)', 'Безупречная субстанция Скверны (Джеденар)', 'Безупречная субстанция Скверны (Темный портал)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7603, 'Огненное ядро Крошиуса', 'Крошиус лежит грудой праха на северо-востоке отсюда, в долине Рваных Ран. Возьми этот пламень Скверны и воспламени его останки. Пламя оживит павшего инфернала.$B$BПосле этого он наверняка пришибет и тебя, и твоего приспешника.$B$BЕсли каким-то чудом тебе удастся уложить Крошиуса, возьми его огненное ядро и принеси Ниби.', 'Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождать, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.Принесите огненное ядро Крошиуса Ниби Всемогущему в Оскверненный лес.', 'Сделка есть сделка! Бери это и быстро записывай. У меня нет времени! На нас прет мое самое величайшее творение!', 'Ты заблудился, что ли?', NULL, NULL, 'Огненное ядро Крошиуса', 'Пламя Скверны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7604, 'Заключение договора', '$gНижеподписавшийся:Нижеподписавшаяся: со всей ответственностью заявляет, что сульфуронский слиток, переданный $gим:ею: братству Тория (ООО \"БТ\"), является подлинником. $gНижеподписавшийся:Нижеподписавшаяся: также подтверждает, что ООО \"БТ\" не несет никакой ответственности за любой вред, могущий последовать в результате неосторожного обращения с Сульфурасом, как то: использование Сульфураса в качестве материала для ковки; самостоятельные разработки; попытки воспроизведения; продажа и употребление в пищу.$B$BПодпись под договором автоматически означает согласие $gподписавшегося:подписавшейся: со всеми условиями, перечисленными в документе.$B$B_______________$B$BПодпись', 'Подпишите договор с представителем Братства Тория Локтосом Зловещим Торговцем, если вам нужен чертеж Сульфурона.', '', NULL, NULL, NULL, 'Контракт Братства Тория (Прилагается)', 'Сульфуронский слиток', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7621, 'Предупреждение', '', '', 'Жрец, ты стоишь на пороге серьезных испытаний, которым подвергнешься для проверки твоих способностей.Послушай, что я скажу тебе.Запомни, ты должен проходить испытания самостоятельно. Пусть твои союзники отойдут на безопасное расстояние и ждут, не вмешиваясь. Любое вмешательство может повлечь за собой самую строгую кару.Судьба привела сюда тебя и только тебя. Вступи в битву с честью. Да пребудет с тобой Свет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7622, 'Баланс Света и Тьмы', 'Тебе предстоит сделать то, что оказалось не под силу мне – спасти крестьян, погибших во время бегства из Стратхольма.$B$BОни выйдут на свет, и ты $gдолжен:должна: защитить их. Если ты не сможешь спасти слишком многих, мы продолжим влачить наше проклятое существование.$B$BЭто настоящее испытание для всех твоих способностей. Да поможет тебе Свет, $N.', 'Спасите жизни 50 крестьян прежде, чем 15 из них будут убиты. Поговорите с Эрис Тайнопламень по выполнении задания.Число погибших крестьян можно узнать, посмотрев на Колья Смерти.', 'Твоя смелость и упорства не имеют себе равных, жрец. Ты обрел право владеть расщепителем Нордрассила. Тебе осталось исполнить лишь одно: найти Око Тени. Найди его, даже если тебе придется обыскать весь мир.', NULL, NULL, NULL, 'Баланс Света и Тьмы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7623, 'Лорд Гиблопуст', 'Морзул говорит, что ты хочешь открыть портал в Зорот. Раз так, тебе не обойтись без зоротианской звездной пыли. А ее нелегко найти в Азероте!$B$BОна может быть лишь у одного существа – лорда Гиблопуста из Джеденара, сердца Совета Теней! Поговори с ним, вдруг он поделится звездной пылью.$B$BВпрочем, отправляясь в Джеденар, тебе необходимо принять злое обличье, чтобы добраться до Совета Теней. Значит, тебе нужны мои зелья Теней, а они недешевы...', 'Купите зелья Теней у Горзиеки в Алтаре Бурь, что Пылающих степях.Приняв зелья, пройдите через Джеденар в Оскверненном лесу и поговорите с лордом Гиблопустом, который находится в Оплоте Теней.', 'Мое терпение бесконечно, $C. Но это не значит, что я уделю тебе больше секунды времени...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7624, 'Улатек Предатель', 'Хочешь заслужить мою милость? Что ж, тогда убей, кого я укажу.$B$BМой слуга, Улатек, пресмыкается передо мной, а тем временем умышляет против меня вместе с лордом Хел\'нуратом из Зорота. Хел\'нурат хочет низвергнуть меня и захватить власть, а Улатек – его шпион...$B$BДокажи, что служишь мне, а не моим противникам. Вступи в бой с Улатеком в его собственном доме, Оплоте Теней на западе. Передай ему, что мне известна его тайна. Вот увидишь, он затрясется от страха. Принеси мне сердце предателя!', 'Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар.', 'Ах, великолепно! Полежав с недельку, оно обретет ни с чем не сравнимый вкус! Может быть, мне послать за головой Улатека и поставить себе на обеденный стол?..$B$BТы оказал мне услугу, $C, и я уже терпимей отношусь к тебе. Немного терпимей.', 'Я уже чувствую вкус сердца Улатека на губах. Как сладка плоть предателя...', NULL, NULL, 'Сердце предателя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7625, 'Зоротианская звездная пыль', 'Так ты $gявился:явилась: в поисках зоротианской звездной пыли? Ты хочешь открыть портал в Зорот, владения моего соперника Хелнурата? Уж не одного ли из его драгоценных коней погибели ты хочешь украсть?$B$BОтлично. У моего слуги, Ур\'Дана, есть большой запас зоротианской звездной пыли. Обращайся к нему... если денег хватит.', 'Купите зоротианскую звездную пыль у Ур\'Дана из Оплота Теней в Джеденаре, что в Оскверненном лесу. Отнесите ее Горзиеки Дикоглазу в Пылающие степи.', 'Вот она! Даже не верится! Должно быть, ты заключил большую сделку с Повелителем ужаса или заплатил огро$Nю сумму, или и то, и другое!$B$BМор\'зул скоро получит чернила и сделает для тебя пергамент с рунами. Ты откроешь портал в Зорот и украдешь одного из знаменитых коней погибели!', 'Ты уже побывал в Джеденаре? Удалось получить звездную пыль у лорда Гиблопуста?', NULL, NULL, 'Зоротианская звездная пыль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7626, 'Колокол Детмуры', 'Колокол Детмуры назвали в честь Детмуры Темноглазой. Это один из трех предметов, необходимых для создания круга Великого призыва. Сопряженный с Колесом и Свечой, он предоставит в твое распоряжение огромный запас магической энергии.$B$BМой слуга Горзиеки может создать такой колокол, но ему понадобится много эликсиров энергии Тьмы. Добудь их у алхимика и отнеси Горзиеки.', 'Отнесите 2 эликсира энергии Тьмы Горзиеки Дикоглазу в Пылающие степи..', 'Отлично! Надеюсь, достать эликсиры было не слишком сложно. Иногда алхимики очень ревниво относятся к своим творениям…$B$BЯ сделаю колокол и отдам его, когда ты будешь готов провести ритуал.', 'Ты несешь мне эликсиры, $N? Морзул говорит, что тебе нужен Колокол Детмуры, а на его создание нужно много темной силы!', NULL, NULL, 'Эликсир силы тьмы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7627, 'Колесо Черного Похода', 'Колесо Черного Похода содержит в себе и направляет черную силу, необходимую для создания круга Великого призыва. Горзиеки может создать это колесо, но ему понадобятся большие сверкающие осколки, которые получают зачаровыватели, и руда черного железа, которую может добыть опытный горняк.$B$BПринеси моему слуге все необходимое.', 'Отнесите 6 больших блестящих осколка и 25 кусков руды черного железа Дикоглазу в Пылающие степи.', 'Ага, вот они! Я слышал,что черное железо добывают лишь в глубинах Черной горы, да и осколки не даром тебе достались. Меня всегда поражает целеустремленность чернокнижников. Кабы все эти силы, да на поимку жуков, такой пир бы получился!$B$BПрости, отступил от темы. Я сделаю колесо и отдам его, когда ты будешь готов провести ритуал.', 'Колесо Черного Похода трудно сделать, и для него нужно много составляющих. Ты уже их собрал?', NULL, NULL, 'Большой сверкающий осколок', 'Руда черного железа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7628, 'Свеча Судного дня', 'Свеча Судного дня хранит в себе огонь, который опаляет всех, желающих прервать твой ритуал. Зажигая свечу при создании круга Великого призыва, ты сожжешь всех упрямых демонов!$B$BВпрочем, сдержать этот огонь довольно трудно, и для этого нужна чешуя черного дракона. Купи ее у мастера снятия шкур и принеси Горзиеки Дикоглазу.', 'Принесите 3 куска чешуи черного дракона Горзики Дикоглазу в Пылающие степи.', 'А, хорошо. При помощи чешуек я смогу обуздать пламя свечи. Теперь я возьмусь за работу, и отдам тебе свечу, когда ты будешь готов провести ритуал.', 'Ты несешь мне чешую дракона, $N? Я и браться не буду за изготовление свечи, пока не получу ее... а то весь лагерь может взлететь на воздух!', NULL, NULL, 'Чешуя черного дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7629, 'Доставка беса', 'Для подготовки пергамента Мор\'зула осталось сделать только одно – напитать бумагу зоротианской звездной пылью. И... боюсь, здесь этого не сделать. Мне не хватит оборудования!$B$BВпрочем, я знаю об одной лаборатории, где есть все необходимое. Она находится в Некроситете, на острове Каэр Дарроу, в Чумных землях.$B$BЯ туда отправиться не смогу, но у меня есть идея. Возьми эту бутылку. В ней сидит довольно умный бес. Выпусти его в алхимической лаборатории, и он напитает пергамент звездной пылью.', 'Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзики Дикоглазу.', 'Славно. Д\'живи создал пергамент. Как тебе Некроситет? Правда, там ужасно интересно? А какие там жуки... Говорят, вкуснейшие!$B$BСпасибо тебе, $N, спасибо, что вернул мой флакон. Он у меня давно... и не продается!', 'Ты уже побывал в Некроситете? Напитал ли бес пергамент звездной пылью?', NULL, NULL, 'Пергамент создан', 'Бес в кувшине (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7630, 'Арканит', 'Итак, колокол, колесо и свеча готовы. Осталось создать черный магнит. Он понадобится во время ритуала, поддерживать прочие объекты, на случай, если они подведут.$B$BДля создания магнита мне понадобится арканит. У тебя его нет? Коли так, поищи его у алхимика.$B$BПринеси мне арканит, и я создам черный магнит.', 'Принесите 1 арканитовый слиток Горзики в Пылающие степи.', 'Ты принес его! Отлично! Теперь я могу создать магнит. Когда ты начнешь ритуал создания круга Великого призыва, тебе понадобится магнит, чтобы уж точно довести его до конца!', 'И где арканит, $N? Как только ты его принесешь, я сделаю тебе черный магнит.', NULL, NULL, 'Арканитовый слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7631, 'Зоротианский конь погибели', 'Все готово. Пришло время провести ритуал создания круга Великого призыва и воспользоваться пергаментом с рунами, начертанными зоротианской звездной пылью... И отрыть портал в Зорот.$B$BВсе инструкции по проведению ритуала я записал в тот свиток. Изучи его внимательно, потому что следует делать все в точности так, как написано, или успеха не добиться.$B$BУдачи, $N. И да попадут души твоих врагов в твой мешочек осколков.', 'Прочтите инструкции Мор\'зула. Призовите зоротианского коня погибели, одолейте его и подчините его дух.', 'Дух ксоротианского коня погибели повержен. Хотя он в ярости, вы чувствуете, что душа его принадлежит вам…$B$BОна нашептывает темные слова, благодаря которым вы постигаете, как вызывать коня погибели.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7632, 'Древний лист', 'Кожица листа светится ярко-зеленым. Его поверхность очень морщиниста, на ней видны многочисленные прожилки и бороздки.$B$BЕсли задуматься, то этот лист – наверняка нечто очень древнее и могущественное.$B$BМожет, поискать, кому он принадлежит?', 'Найдите хозяина древнего окаменелого древесного листа. Удачи, $N, мир велик.', 'Еще бы мне не узнать собственный лист! Смотри-ка! В великолепном состоянии.$B$BОчень мило с твоей стороны вернуть его, $C.$B$BВозможно, ты сможешь сослужить нам службу, а мы – тебе.', '*Вартус кряхтит.*', NULL, NULL, 'Древний окаменелый древесный лист (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7633, 'Посвящение', '', '', 'Твоя преданность и искренность не остались незамечены, $C.Мы – Дерева, защитники этого некогда великого леса. Наши тела погибли 10 000 лет назад, когда Архимонд и Пылающий Легион прошли по горе Хиджал. Однако, души наши не погибли.Есть у нас несколько заданий для тебя. Если ты их выполнишь, тебе будут открыты тайны Дерев.Знай – если выполнишь их, просто возвращайся к этой скале, и мы ответим на твой зов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7634, 'Перетянутый жилами лист древня', 'Привествую тебя, $C. Я Хастат, древо мудрости. Я храню память тысячелетий.$B$BЕсли один из моих листьев свернуть надлежащим образом, он будет служить колчаном, подобных которым не было уже 10 000 лет. Если к этому колчану в пару получить еще и лук Древ, то силе их равных не будет.$B$BПринеси мне жил взрослого синего дракона, и получишь колчан.', 'Хастат Древний просит вас принести ему жилу взрослого синего дракона. По выполнении задания возвращайтесь к Хастату в Оскверненный лес.', 'Да защитят мои листья твои стрелы! Да не ведают они промаха! Да сгинут враги нашего мира!', 'С возвращением, юный $C.', NULL, NULL, 'Жила взрослого синего дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7635, 'Подходящая тетива', 'Вартус, конечно, предложил тебе посох для лука Дерев, но наложить чары на тетиву, без которой лук – не лук, могу только я.$B$BЭто простое дело, совсем плевое. Убей взрослого черного дракона и добудь из него жилу. Принеси мне эту жилу, и я зачарую ее так, что тетива для лука из нее будет, считай, вечной.', 'Стома Древний просит вас принести ему жилу взрослого черного дракона. Добыв жилу, возвращайтесь к Стоме в Оскверненный лес.', 'Это был самый мерзостный из драконов. Жила просто смердит злом.$B$BПодожди немного – я очищу ее и наложу соотвествующие чары.', 'Я уверен, что ты без труда найдешь и убьешь черного дракона, $N. Не отнимай у меня времени пустой болтовней.', NULL, NULL, 'Жила взрослого черного дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7636, 'Ветвь ходячего Древа', 'Тайные слуги Пылающего Легиона все еще строят козни в нашем мире, $C. Они оскверняют все, к чему прикасаются. Природа чахнет и стенает от их присутствия.$B$BТы $gдолжен:должна: выследить этих демонических разносчиков порчи, $N. Помни – ты $gдолжен:должна: лично разобраться с ними – иначе сбегут. Пока ты $gодин:одна:, они будут пытаться уничтожить тебя. Ты $gдолжен:должна: сразить их, обратить их надменность в ничтожество!$B$BЯ дам тебе кусок моей коры. Письмена на ней приведут тебя к нашим врагам. Принеси мне их головы.', 'Вы должны найти и уничтожить следующих четверых демонических разносчиков порчи:Симон Совратительницу.Клинфрана Безумного.Соленора Убийцу.Арториуса Судьбоносного.Уничтожьте этих тварей и возвращайтесь к Вартусу Древнему в Оскверненный лес с их головами.В поисках местонахождения этих демонов сверяйтесь с окаменевшей корой.Вы ОБЯЗАНЫ выполнить это задание в одиночку.', '', NULL, NULL, NULL, 'Голова Симоны', 'Голова Клинфрана', 'Голова Соленора', 'Голова Арториуса');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7637, 'Жертва необходима', 'Чтобы подготовиться к этому заданию, ты $gдолжен:должна: сначала показать умение жертвовать и умение судить... в первую очередь – жертвовать.$B$BДля выполнения задания ты $gдолжен:должна: получить курильницу экзорцизма у верховного жреца Рохана. Несмотря на то, что ее использование будет продиктовано благими намерениями и существенными причинами, за нее должна быть предложена соответственная компенсация.$B$BОтправляйся в Стальгорн и поговори с верховным жрецом. Если возьмешь с собой достаточно звонкой монеты, чтобы компенсировать ему потерю курильницы, ты проявишь должную готовность к жертвам.$B$BА теперь иди, $N, время терять нельзя.', 'Доберитесь до Стальгорна и получите курильницу экзорцизма у верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых.', 'Да пребудут на тебе все благословения, друг мой $C! Твой дар далеко превосходит наши нужды. Твоя жертва не только поможет восстановить утраченное, но также позволит нам помочь самым бедным жителям Стальгорна.$B$BА теперь дай-ка я удостоверюсь, что как следует подготовил эту курильницу для твоих будущих свершений.', 'Приветствую тебя, благородный паладин! Я наполнил свою верную курильницу свежайшими благовониями и трижды благословил ее специально для тебя. Твое пожертвование поможет нам здесь, в Стальгорне, не только изготовить новую курильницу, но также пополнить оскудевающие запасы пищи для наших нужд.', NULL, NULL, 'Требуется денег: 150', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7638, 'Лорд Грейсон Тенелом', 'Пришло твое время, $N, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени... твоего рыцарского коня.$B$BПоговори с лордом Грейсоном Тенеломом здесь, в Храмовом квартале Штормграда. Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня.$B$BЯ желаю тебе всего наилучшего в этом испытании. Во имя Света, $gмой благородный брат:моя благородная сестра:!', 'Поговорите с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда.', 'Я рад видеть тебя, $N. Я знаю, что ты желаешь раздобыть рыцарского коня, и вот наконец время пришло.$B$BТы, конечно, должен будешь пройти разнообразные испытания, но самое главное – это твоя решимость преодолеть множество препятствий, что встанут перед тобой. Это не учебные задачи – ты уже явно перерос их. Тебе придется вырвать своего будущего скакуна из лап того зла, борьбе с которым ты посвятил свою жизнь.$B$BРешай же, твое время пришло!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7639, 'Демонстрация истинного правосудия', 'Прими эту курильницу и будь $gблагословен:благословенна:. Я сам применял ее в нескольких обрядах экзорцизма, и она хорошо послужит тебе в грядущих тяжких испытаниях.$B$BНыне возвращайся к лорду Грейсону Тенелому в Штормград, $N. Он даст тебе поручение.', 'Принесите курильницу экзорцизма лорду Грейсону Тенелому в храмовый квартал Штормграда.', 'Да, это она. Не раз вам придется совершать этот обряд и не раз вам придется в ходе него жертвовать собой. Я рад, что вы готовы к этому. Жертвенность – важнейшая составляющая, без которой не выполнить долга паладина... но не мне говорить вам об этом.$B$BА теперь, $N, вам придется проявить истинное правосудие в ваших делах. И эта курильница послужит вашим сосудом для оказания помощи истерзанным духам утраченной нами земли.', 'С возвращением, $N. Вы принесли курильницу экзорцизма?', NULL, NULL, 'Курильница экзорцизма Рохана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7640, 'Изгнание призраков из Долины Ужаса', 'Я добавил в курильницу щепотку зараженной земли Долины Ужаса, что в Восточных Чумных землях. Ты $gдолжен:должна: будешь использовать курильницу для поиска мест, которые несут на себе признаки беспокойного поведения потусторонних сил. Ищи зеленое свечение, исходящее из-под земли – так физический мир проявляет себя, мучимый миром потусторонним, и используй курильницу для вызова из-под земли злых духов.$B$BКогда свершишь суд над призраками, я поставлю перед тобой новую задачу.', 'Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в храмовый квартал Штормграда.', 'Отличная работа, $N. Свершить суд Света над теми, кто обитает во тьме – задача, к выполнению которой мы должны подходить с рвением и усердием. Именно это ты и свершил благодаря своей жертве в Стальгорне и правосудию над духами Долины Ужаса.$B$BТвои следующие шаги вновь потребуют от тебя и жертвенности, и умения вершить правосудие: ведь тебе нужно будет вернуть дух рыцарского коня, который служит сейчас рыцарю смерти, известному как Темный Губитель.', 'Приятно вновь увидеться с тобой, $N. Завершена ли твоя работа в Долине Ужаса?', NULL, NULL, 'Дух долины Ужаса убито', 'Курильница экзорцизма (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7641, 'Работа Гриманда Элмора', 'Без особого чепрака рыцарский конь паладина ничем не отличается от обычного скакуна. Чепрак для твоего скакуна не только должен быть изготовлен из наилучших материалов, но в силу сопутствующих обстоятельств нужно, чтобы он еще был в достаточной мере настроен на призрачный мир.$B$BНо все по порядку, $N – сначала нужно изготовить чепрак. В Квартале Дворфов Штормграда проживает один из самых лучших современных мастеров – Гриманд Элмор. Он берет за свою работу недешево, но качество его работы – как раз то, что нам нужно. Поговори с ним.', 'Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда.', 'Привет-привет, паренек – лорд Победитель Тени известил меня заранее о том, что ты придешь со мной повидаться. Я с удовольствием сделаю чепрак, какой тебе нужен, но это будет нелегко, да и обойдется недешево. Я об этом говорю открыто и в первую очередь.$B$BНо, скажу я тебе – и Грейсон поддержит меня в этом утверждении – лучшего чепрака, чем изготовленный мной, ты во всем Азероте не найдешь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7642, 'Сбор необходимого', 'Для чепрака тебе понадобятся четыре вещи: руническая ткань для подкладки, арканитовые слитки для покрытия, цветки слезы Артаса для настройки на призрачный мир и святая вода из Стратхольма для духовного укрепления. На самом деле, вещей понадобится пять... если считать золото для меня. Эта плата – за весь мой труд, а также седло и стремена ручной работы.$B$BКогда наберешь все это, я смогу изготовить твой чепрак. А пока ты ищешь необходимое, я приступлю к работе.', 'Принесите Гриманду Элмору в Квартал дворфов Штормграда 40 отрезов рунической ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой из Стратхольма и 150 золотых монет.', 'Это... да, это именно то, что нужно. А ты весьма находчивый паладин, не так ли?$B$BЛадненько, давай-ка закончим с твоим чепраком!', 'А, это ты, $N. Я не смогу закончить изготовление чепрака без тех вещей, о которых я тебе говорил. Удалось ли тебе собрать все?', NULL, NULL, 'Святая вода Стратхольма', 'Слезы Артаса', 'Руническая ткань', 'Арканитовый слиток');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7643, 'Дух древнего коня', 'Твоему чепраку нужно особое благословение, а его можно получить только у подходящего духа. Такой дух обитает, например, в башне Забытого Города – это Дух древнего коня. Сейчас его удерживает в плену Тендрис Криводрев. Убей эту тварь, чтобы освободить духа, $N.$B$BТолько имей в виду, что просто освободить – недостаточно. Тебе нужно сначала умилостивить духа, чтобы получить его благословение. Для этого понадобится особый лошадиный корм. Ты найдешь его в Южнобережье, если поговоришь с Меридет Карлсон.', 'Купите лошадиный корм для духа древнего коня у Меридет Карлсон в Южнобережье.Убейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака.', 'Дух древнего коня обнюхал корм и чинно захрустел им. Насытившись, дух благосклонно позволил вам накинуть чепрак ему на спину.', 'Дух древнего коня внимательно взирает на вас – так, словно ждет чего-то.', NULL, NULL, 'Арканитовый чепрак (Прилагается)', 'Сытный манный лошадиный корм', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7644, 'Благословенный арканитовый чепрак', 'После того как чепрак наброшен на спину духу древнего коня, он начинает чуть заметно светиться. На миг кажется, будто все вокруг звенит от напряжения и магической мощи... а потом чепрак исчезает со спины коня. Теперь он в вашем заплечном мешке.$B$BОчевидно, чепрак получил благословение. Теперь, согласно наставлениям лорда Победителя Тени, вам следует вернуться с этим чепраком к нему в Штормград.', 'Вернитесь с благословенным арканитовым чепраком к лорду Грейсону Тенелому в храмовый квартал Штормграда.', 'Тебе пришлось немало постранствовать, друг мой! И вот наконец твой чепрак готов к последнему шагу, который тебе придется предпринять.$B$BЭтот чепрак пригодится тебе, чтобы седлать своего скакуна, когда труд искупления будет завершен. Однако до этого тебе снова придется вступить в тяжкую борьбу. Твой час близок!$B$BПеред этим нам нужно изготовить еще один, последний предмет. Надеюсь, твой пыл еще не иссяк?', '$N, ты вернулся! Ну что, удалось тебе справиться с Меридет Карлсон и Тендрисом Тенеломом? Честно говоря, даже и не знаю, кто из них опаснее...', NULL, NULL, 'Благословенный арканитовый чепрак (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7645, 'Сытный манный лошадиный корм', 'Серебряная Длань посчитала меня ЧОКНУТОЙ, когда я сказала, что могу сделать особый конский корм, который насытит призрачных лошадей. ВСЕ считали меня чокнутой! Пришло время отыграться!$B$BЯ сделаю, что тебе надо, ПАЛАДИН... ЗАЩИТНИК, тоже мне... Но обойдется это недешево. Мне понадобится сытное манное печенье, которое продают только в Серебряном Рассвете. Кроме того я требую – да, ТРЕБУЮ, золото в качестве компенсации за перенесенные страдания!$B$BПосмотрим, многим ли ты можешь пожертвовать, ПАЛАДИН.', 'Принесите 20 cытных манных печений – ключевых составляющих сытного манного лошадиного корма – Меридет Карлсон в Южнобережье в предгорьях Хилсбрада. Продается печенье только в Серебряном Рассвете.Кроме того, понадобится дать ей 50 золотых, чтобы успокоить ее ущемленное самолюбие.', 'ДА, КТО...стоп, ты и золото мне даешь? Лично ты не называл меня чокнутой – а они дразнили меня сдвинутой, слетевшей с катушек... И ты хочешь искупить зло, причиненное не тобой?$B$BЯ... я недооценила тебя, $N. Если тебе понадобится еще корм для коней, обращайся. Я сделаю его бесплатно. Спасибо... благородный паладин.$B$BНо деньги я себе оставлю – я не настолько чокнутая, чтобы отказаться от целого состояния.', 'Да, я доказала, что ты неправ? Все они ошибались! Я БЫЛА ПРАВА ВСЕ ЭТО ВРЕМЯ!!!', NULL, NULL, 'Сытное манное печенье', 'Требуется денег: 50', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7646, 'Магический кристалл', 'Теперь мы должны сконструировать магический кристалл – так начнется твой подвиг и освобождение плененного духа зловещего рыцарского коня. Собственно, кристалл уже почти готов. Катализатором для него послужила курильница, которую ты $gиспользовал:использовала:, изгоняя духов из долины Ужаса; осталось только сделать подходящую подставку для нашего прибора.$B$BДа, и еще нужны последние два компонента – азеротский алмаз и безупречный черный алмаз. Эти два камня станут маяком, пронзающим тьму!', 'Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Храмовый квартал Штормграда.', 'Отличные камни, $N. Последние фрагменты теперь установлены на свои места. Наконец-то, пришло твое время!$B$BВ глубине Главного склепа в Некроситете покоятся останки многих существ. Среди них есть кости и некогда благородного рыцарского коня. Призрачный дух скакуна теперь служит рыцарю смерти Темному Терзателю. Ты победишь Терзателя и свершишь правый суд над его несчастным конем. Только ты, $N, можешь даровать душе скакуна искупление и избавить ее от мук ужасного служения.', 'Ты продвинулся уже так далеко, $N. Твой последний акт жертвования мирскими вещами станет залогом одного из твоих величайших достижений. Я это чувствую всем своим существом!', NULL, NULL, 'Азеротский алмаз', 'Нетронутый черный алмаз', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7647, 'Суд и расплата', 'Возьми эту сумку – в ней собраны предметы, которые понадобятся тебе для выполнения задания.$B$BИспользуй магический кристалл в самом сердце подвала Великого оссуария для вызова проклятых духов, над которыми нужно свершить суд. Во время испытания рассчитывай силы – духи могут оказаться сильнее, чем ты думаешь. После гибели духов появится сам рыцарь смерти. Срази его и верни потерянную душу рыцарского коня. Только тогда, $N, ты сможешь принести ей избавление и возложить чепрак на твоего нового скакуна.$B$BЖелаю удачи!', 'Используйте магический кристалл в центре подвала Великого оссуария в Некроситете. Победите вызванных духов, а затем – рыцаря смерти Темного Терзателя, который появится после поражения духов.Верните падшему скакуну Темного Терзателя его спасенную душу и покройте его благословенным зачарованным чепраком.', 'Искорка жизни, давно покинувшей бедного зверя, сверкает в его глазах, когда ваша рука возвращает ему его спасенную душу. Вы покрываете спину скакуна чепраком и чувствуете всплеск святой силы – правосудие свершилось! Конь тыкается носом в вашу руку, как будто благодаря за избавление от груза ужасного прошлого. Вы чувствуете, что теперь у вас появился верный друг.', 'Дух зловещего рыцарского коня смотрит на вас тоскливым взором. В его мертвых глазах уже давно погас огонь надежды.', NULL, NULL, 'Спасенная душа рыцарского коня', 'Благословенный арканитовый чепрак', 'Сумка лорда Грейсона', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7648, 'Шедевр Гриманда', '*Гриманд утирает пот со лба, сияя от гордости.*$B$BГотово, $gдруг мой:моя леди:. Это одно из моих лучших изделий – не хуже, чем тот чепрак, что я собственноручно смастерил для лорда Победителя Тени, когда он отправлялся за своим конем. Благодарю тебя за доверие.$B$BНесомненно, и сам Грейсон захочет полюбоваться на мою работу. Покажи ему чепрак и передай мою искреннюю благодарность за его достойные дела.', 'Покажите арканитовый чепрак лорду Грейсону Тенелому в храмовом квартале Штормграда.', 'Великолепная работа! С возрастом мастерство Гриманда растет. А его изделия были одними из лучших еще в те времена, когда он делал чепрак для моего коня!$B$BЭтот чепрак слишком хорош для обычного скакуна, но нам предстоит иметь дело с необычным животным. Тебе предстоит оседлать паладинского коня, и поэтому для чепрака нужно получить особое благословение. Ступай.', 'А вы неплохо показали себя, $N. Как только чепрак будет готов, вы отправитесь на следующий подвиг.', NULL, NULL, 'Арканитовый чепрак (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7649, '\"Зачарованная ториевая броня\", том I', 'Том помечен печатью Читальни.', 'Верните книгу законным владельцам.', 'Молодец, мой мальчик!$B$B*Сказитель Лидрос выдирает из книги одну страницу.*$B$BВот, этот чертеж тебе наверняка пригодится!', 'Вы ее нашли!', NULL, NULL, 'Зачарованная ториевая броня (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7650, '\"Зачарованная ториевая броня\", том II', 'Том помечен печатью Читальни.', 'Верните книгу законным владельцам.', 'Молодец, мой мальчик!$B$B*Сказитель Лидрос выдирает из книги одну страницу.*$B$BВот, этот чертеж тебе наверняка пригодится!', 'Вы ее нашли!', NULL, NULL, 'Зачарованная ториевая броня (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7651, '\"Зачарованная ториевая броня\", том III', 'Том помечен печатью Читальни.', 'Верните книгу законным владельцам.', 'Молодец, мой мальчик!$B$B*Сказитель Лидрос выдирает из книги одну страницу.*$B$BВот, этот чертеж тебе наверняка пригодится!', 'Вы ее нашли!', NULL, NULL, 'Зачарованная ториевая броня (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7652, 'Выгодная сделка', '', '', 'Отлично, сударь у меня для вас деловое предложение. Я тут хочу продать несколько чертежей имперских латных доспехов, и мне необходим покупатель. В обмен я хочу получить слитки тория. Как вам мое предложение?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
