INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7665, 'Новый красный ящер', '', '', '', NULL, NULL, NULL, 'Свисток красного крапчатого ящера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7666, 'Возвращение в Великий оссуарий', '', '', 'Ты снова отправляешься в Некроситет, $N? Раз уж ты так дорого заплатил за использование кристального предсказателя, может быть, возьмешь с собой еще один? Он поможет тебе преодолеть опасности Великого оссуария.Бери, бери. Заслужил!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7667, 'Существенная помощь', '$N, у меня есть срочное дело, и надеюсь, ты сумеешь мне помочь. Разреши, я объясню.$B$BВ глубине Некроситета в Лордероне есть здание, которое называется Великий оссуарий. Мне нужно изготовить устройство, которое позволит развеять зловещие тени этого жуткого места. Но чтобы его завершить, мне нужны два алмаза, азеротский и безупречный черный. Найти их не так-то просто, я знаю, но самому мне их раздобыть не под силу.$B$BНе согласишься ли ты добыть для меня эти камни?', 'Принесите Сагорну Гребнестраннику в Аллею Мудрости в Оргриммаре азеротский алмаз и безупречный черный алмаз.', 'Твоя щедрость не знает границ, $N! Спасибо тебе.$B$BТеперь я смогу изготовить свой кристальный предсказатель, и даже не один. Новые алмазы понадобятся мне нескоро... Кстати, может быть, один из предсказателей тебе пригодится для чрезвычайно важного дела. Если его не выполнить, миру духов грозит катастрофа!', 'Мне так неудобно тебя просить – но для кристального предсказателя, того устройства, которое я надеюсь изготовить, требуются оба эти камня. Но, конечно, если у тебя ничего не получится, я тебя пойму...', NULL, NULL, 'Азеротский алмаз', 'Нетронутый черный алмаз', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7668, 'Угроза Темного Губителя', 'Рыцарь смерти Темный Терзатель, владычествует над Великим оссуарием в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.$B$BПриведи его в действие в Великом оссуарии, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, $N! Только его гибель способна исправить урон, нанесенный миру духов!', 'Используйте кристальный предсказатель в Великом оссуарии в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.Принесите голову Темного Терзателя Сагорну Гривастому Страннику на аллею Мудрости Оргриммара.', '', NULL, NULL, NULL, 'Голова Темного Терзателя', 'Гадальный кристалл', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7669, 'Возвращение в Великий оссуарий', '', '', 'Ты снова отправляешься в Некроситет, $N? Раз уж ты так дорого заплатил за использование кристального предсказателя, может быть, возьмешь с собой еще один? Он поможет тебе преодолеть опасности Главного склепа.Бери, бери. Заслужил!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7670, 'Лорд Грейсон Тенелом', '$N, пришла пора узнать, что потребуется от тебя, дабы получить предмет твоих давних мечтаний, а именно... боевого скакуна.$B$BПоговори с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда. Он не только наставит тебя в обращении с самым верным товарищем паладина, но и даст тебе задачу, прежде чем ты получишь своего скакуна.$B$BЖелаю тебе успешно пройти это испытание. Во имя Света, $gблагородный брат:благородная сестра:!', 'Поговорите с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда.', 'Рад видеть тебя, $N. Я знаю, что ты ждал от меня наставлений, как добыть себе скакуна, и теперь час настал.$B$BТебе, несомненно, придется подвергаться разным испытаниям, но самое важное – испытание твоей готовности идти вперед вопреки любым препятствиям, что станут у тебя на пути. Это не учебные упражнения – твоя стать уже не для простых учебных испытаний. Тебе придется спасти твоего будущего товарища из лап зла, с которым тебе предстоит сражаться всю жизнь.$B$BВнемли же, твой час пришел!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
