INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7681, 'Hunter test quest', 'Примените \"Кормление питомца\" к своему питомцу.', 'Покормите своего питомца и поговорите с персонажем, который выдал это задание.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7682, 'Hunter test quest2', 'Примените \"Кормление питомца\" к своему питомцу.', 'Покормите своего питомца и поговорите с персонажем, который выдал это задание.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7701, 'Разыскивается: надзиратель Мальториус', 'Именем его светлости надзирателя Скользорука должно убить агента Братства Тория надзирателя Мальториуса, командира подразделения Шлаковой Ямы войск Черного Железа в Котловане. Его голову должно принести в качестве доказательства. $B$BЗа наградой обращаться к дозорному капитану Лоло Долгобою.', 'Дворф из клана Черного Железа, вероломный надзиратель Мальториус, скрывается в глубине Шлаковой Ямы в Котле, что в Тлеющем ущелье. Убейте надзирателя Мальториуса и принесите его голову дозорному капитану Лоло Долгобою.', 'Не думал я, что еще раз увижу эту мерзкую рожу! *ик* Надо признать, выглядит он получше, после того как ты отрезал все лишнее. *ик* $B$BВот, держи свою награду.', 'Не видишь, я занят! Что *ик* у тебя *ик* там?', NULL, NULL, 'Голова надзирателя Мальториуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7702, 'Казнь через лишение сна', 'Чтобы подорвать силы Черного Железа в Шлаковой Яме, необходимо нанести удар по самому уязвимому месту. $B$BОткрою тебе секрет: дворфы, а особенно дворфы Черного Железа, крайне нуждаются в регулярном отдыхе. Хорошем отдыхе! $B$BТак вот скажи мне, как они смогут спать, если у них не будет подушек? Правильно! Никак. Поэтому надо прокрасться в Шлаковую Яму и стянуть все их подушки!', 'Найдите спальные кварталы дворфов Черного Железа в глубине Шлаковой Ямы, что в Котле. Украдите 20 подушек дворфов Черного Железа. По выполнении задания вернитесь к Эвонис Сажекурке.', 'Прекрасно! Сонные дворфы Черной Скалы будут вынуждены возвращаться в Глубины, чтобы немного поспать, и производительность труда в Шлаковой Яме упадет.', 'Пусть эти дурацкие очки тебя не обманут, $N! Я тут самая умная.', NULL, NULL, 'Подушка Черного Железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7703, 'Неоконченное дело Гордоков', 'Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а? Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спер его у одного из королей!$B$BА вещица-то была ценная: латная рукавица Мощи Гордока! И в старых байках говорится, что воротить ее сможет только настоящий король Гордок. А еще говорится, что паскудный эльф до сих пор шляется где-то тут. Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!', 'Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.По словам Давигрома, в \"старых байках\" говорится, что Тортелдрин – \"страшный эльф\", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.', 'Ух ты!!! Да ты и впрямь настоящий король! Я и не думал, что мне доведется своими глазами увидеть эту вещь!.. Только че-то она выглядит, как будто колдунства в ней не осталось... Может, тот паскудный эльф ее спортил? Да и плевал я на этого эльфа!$B$BСлышь, видишь эту метку на рукавице? Это старая-престарая метка, постарше всех королей Гордоков, говорят. Ну, нас, капитанов Гордоков, всех учат тому, как эту метку обновить, и вернуть рукавице силу!$B$BИ я сделаю это для тебя, король! Вот, бери рукавицу и правь вовеки!', 'А, начальник! Ну че, нашел рукавицу? Может, старые байки-то врут? Че-то как-то не верится, что паскудный эльф мог что-то спереть у короля Гордока!', NULL, NULL, 'Латная рукавица Мощи Гордока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7704, 'Размер имеет значение', 'Ну и ну... Вот так сюрприз! У горничной была огромная вышитая подушка, и вот теперь она в ваших руках. Эвонис Сажекурке непременно захочет заполучить ее. Посмотрим, что она сможет предложить взамен...', 'Отнесите подушку горничной Крепкие Тиски Эвонис Сажекурке в Тлеющее ущелье.', 'На такую удачу я даже и не рассчитывала! Магическая подушка горничной теперь моя! Можешь не сомневаться, ты получишь свою награду за труды, $N!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7721, 'Энергия для уменьшения', 'Если я поступлю вопреки доводам разума, и все же буду по-прежнему содержать инженерную  мастерскую на Забытом берегу, мне нужно будет как-то разобраться с этими зловредными элементалями. Чтоб им провалиться, этим необузданным стихиям!$B$BНо как повезло мне – а теперь и  тебе, $gмой уважаемый помощник:моя уважаемая помощница:! Ведь эти элементали представляют собой идеальный источник энергии для моего ультрасжимателя! Так что ликвидируй их, не стесняясь, только смотри, не выбрасывай ядра элементалей воды!', 'Соберите 10 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.', 'Супер-пупер-превосходнейше! Да, этих ядер мне хватит надолго... И мало того: теперь на побережье станет поменьше этих элементалей, и мне не придется по ночам рыдать в подушку оттого, что я выбрал для своей мастерской худшее место в мире!$B$BСпасибо вам, $N, за все ваши труды. Конечно, это создаст мне некоторые финансовые проблемы, но тем не менее я не могу не отблагодарить вас материально!', 'Я не стану докучать вам техническими подробностями и объяснениями, для чего мне эти ядра. Я лучше намекну, что, выполнив эту важную задачу, вы получите кругленькую сумму, и еще кое-что полезное в придачу. Ну что, где мои ядра?', NULL, NULL, 'Ядро элементаля воды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7722, 'Какой еще плавень?', 'Когда этот негодяй Мальториус покинул клан, он унес с собой кое-что поважнее безупречнейшего чародейского кристалла. Он украл рецепт огненного плавня! Полагаю, это была его возможность выслужиться у дворфов Черного Железа. $B$BВерни нам эти секретные документы, $N. Мальториус наверняка держит их при себе, там, в Шлаковой Яме.', 'Верните секретные документы по изготовлению огненного плавня, украденные надзирателем Мальториусом. Инспектор скорее всего находится в Шлаковой Яме в Котле. Документы верните мастеру-кузнецу Гориврату в Тлеющем ущелье.', 'Надеюсь, вместе с документами ты вытряс из него его подлую душонку! Рагнаросу ведомо, он этого заслужил! $B$BТеперь приступим к делу.', 'Тебе удалось вернуть документы?', NULL, NULL, 'Секретный рецепт: огненный плавень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7723, 'Отекшие пальцы', 'К несчастью, я уже не способен на столь меткие удары, как раньше, из-за проблем с пальцами. Виноват климат и низкое атмосферное давление – пальцы здесь отекают и становятся похожими на телcамарские кровяные колбаски... $B$BТак что придется тебе поработать за меня: вышиби дух из боевых големов, которых найдешь в ущелье.', 'По поручению Хансела Большерука убейте 20 тяжелых боевых големов, которых можно найти в землях, окружающих Котел в Тлеющем ущелье. По выполнении задания вернитесь к Ханселу.', 'Молодец, парень! Вот тебе подарок за труды.', NULL, NULL, NULL, 'Тяжелый боевой голем убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7724, 'Огненная угроза', 'Как только старый Хансел собирается отдохнуть, нелегкая подбрасывает ему еще работенки... $B$BВот, пожалуйста, теперь большие лавовые пауки добавили проблем! Скользорук говорит, его храбрецы чуть ли не из пушек от них отстреливались... $B$BКороче, чтобы зря не пугать детишек и наших доблестных вояк, надо бы найти на пауков управу. Уверен, ты справишься.', 'По указанию Хансела Большерука убейте 20 больших лавовых пауков в Тлеющем ущелье. Пауки водятся на вулканических плато и в озерах лавы в Тлеющем ущелье.когда убьете достаточно пауков, вернитесь к Ханселу.', '*Хансел чихает* $B$BПохоже, опять простыл... Проклятый холод!', NULL, NULL, NULL, 'Большой лавовый паук убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7725, 'Еще раз ослабим великанов', 'Я знаю, ты уже $gсобирал:собирала: для меня остатки миниатюризации... но, если тебе захочется снова поразвлечься, имей в виду: мне всегда нужны новые остатки!$B$BРазумеется, такого большого вознаграждения, как раньше, я больше предложить не смогу, но зато я всегда буду рад замолвить за тебя словечко перед своими друзьями-гоблинами.$B$BПоверь мне, $gпутник:путешественница:: гоблины к подобным отзывам прислушиваются чрезвычайно внимательно!', 'Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 10 миниатюрных великанов Зорбину Дребезгуну в порт Забытого берега в Фераласе.', 'Это просто фантастика, $N! Вы снова исполнили мою просьбу, и я вам за это чрезвычайно признателен.$B$BСпасибо вам большое!$B$BНаверное, вы привыкли рассчитывать на что-то большее, чем эта монета, но зато будьте уверены, что ваши деяния в помощь мировому гоблинству прогремят на весь картель Хитрая Шестеренка! Если вам захочется новых подвигов, пожалуйста, обращайтесь ко мне!', 'Ах, вот они, плоды исследований и разумной утилизации: мои сладенькие остаточки! Нет-нет, вы только не подумайте, будто я пробую их на вкус!$B$BЯ такого почти никогда не делаю.', NULL, NULL, 'Миниатюрный великан', 'Ультрасжиматель Зорбина', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7726, 'Новая энергия для уменьшения', 'О, ты не прочь снова поработать? Так героическое собирание кусков слизи, выпавших из тел элементалей, не утолило твоей жажды приключений? Ну, тогда ты, наверное, не огорчишься, если я снова дам тебе то же самое поручение?$B$BЛадно, шутки в сторону: мне нужны новые ядра элементалей воды. Но имей в виду: сейчас почти все мои средства уходят на обустройство мастерской, так что награда, возможно, будет не столь велика... Зато обещаю, что расскажу о тебе всем своим ближним и дальним знакомым! А у меня масса знакомых в картеле!', 'Соберите 6 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.', 'Высший класс, $N, просто высший класс! Конечно, деньги, которые вы получите – не самая крупная награда за подобную работу, зато можете быть уверены: мои коллеги из картеля Хитрая Шестеренка будут осведомлены о ваших подвигах!$B$BЕсли будете искать новую работу, дайте мне знать. Мне всегда нужны новые ядра элементалей, и тому подобное.', 'Ну что, удалось вам добыть то, о чем я просил?', NULL, NULL, 'Ядро элементаля воды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7727, 'Пламезавры? Ну и название...', 'Бедные мои ножки... У меня бурсит, $gмолодой человек:милочка:. Да, большие шишки всегда наживают себе шишки. Ну и как мне заниматься истреблением всяких тварей, если пальцы моих ног в таком плачевном состоянии?В общем, тут-то ты мне и поможешь! $B$BСкрендж и Гориврат хотят, чтобы я поубивал этих проклятых ящеров, чтобы расчистить путь для их исследовательских отрядов. Они, вишь ты, желают изучать озера лавы в Шлаковой Яме. А всякие пламезавры и прочие завры им, вишь ты, мешают. В общем, придется тебе направиться в Шлаковую Яму и слегка ускорить процесс вымирания этих монстров.', 'По поручению Хансела Большерука убейте 20 пламезавров, обитающих в озерах лавы в Шлаковой Яме - это часть Котла в Тлеющем ущелье. По выполнении задания вернитесь к Ханселу в Тлеющее ущелье.', 'Ох, болят мои ножки... $B$BЛадно, раз уж нет пемзы...', NULL, NULL, NULL, 'Пламезавр убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7728, 'УКРАДЕНО: фурма и подзорная труба наблюдателя', 'Внимание, украдены следующие предметы: $B$B*Фурма из черного железа – одна штука. $B$B*Подзорная труба наблюдателя – одна штука. $B$BПросьба вернуть за вознаграждение. $B$BБратство Тория точно знает, что эти предметы были украдены беспринципными и завистливыми дворфами из клана Черного Железа из Тлеющего ущелья. $B$BПодзорная труба была великолепным прибором для наблюдения, а фурма – просто незаменимый инструмент. $B$BНашедшему просьба вернуть указанные вещи Скренджу.', 'Найдите и верните фурму и подзорную трубу наблюдателя надсмотрщику Скренджу в Тлеющем ущелье. Единственная известная информация: вещи были украдены дворфами Черного Железа. Подзорная труба является бесценным прибором для наблюдения, а фурма – незаменимым кузнечным инструментом.', 'Ух ты! Тебе удалось! Вот, получай свою награду.', 'Хочешь награду, давай сюда мои вещи!', NULL, NULL, 'Фурма', 'Подзорная труба наблюдателя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7729, 'ВАКАНСИЯ: устранитель конкурентов', 'Надсмотрщику Скренджу требуется опытный кандидат на должность устранителя конкурентов в Тлеющем ущелье. Пол неважен. $B$BЕсли ты считаешь, что твоя квалификация достаточна для этой должности, отправляйся в Тлеющее ущелье и уничтожь надсмотрщиков и работорговцев из клана Черного Железа. $B$BВозвращайся к надсмотрщику Скренджу, когда твоя одежда пропитается кровью. $B$BТы поймешь, когда настанет момент, так что вопросов не задавай.', 'Убейте 15 надсмотрщиков и 15 поработителей из клана Черного Железа. По выполнении задания вернитесь к десятнику Скренджу в Тлеющее ущелье.', '15.9 фунтов кишок и крови на одну одежку! Да это почти рекорд! Поздравляю, $C!', NULL, NULL, NULL, 'Надсмотрщик из клана Черного Железа убито', 'Поработитель из клана Черного Железа убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7730, 'Вторжение улья Цуккаш', 'Судя по сведениям, полученным с помощью разведки, враги, теснящие гноллов с юга, – это раса насекомоподобных существ. Неизвестно, разумны ли они – но, откровенно говоря, это и неважно. Если гноллы их так боятся, что предпочитают переть на нас, значит, эти твари так же опасны, как гноллы, а может, и еще опаснее.$B$BПроникни в те места, где обитают эти насекомые, Зукк\'аш. Это место называется \"Гудящая Бездна\". Постарайся уменьшить их численность, и доложи мне о том, что увидишь. В доказательство своих свершений принеси мне их панцири!', 'Принесите 20 панцирей Зукк\'аш Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.', 'Молодец, $C! Конечно, отпугнуть этих насекомых тебе не удалось – их не проймешь ничем, кроме полномасштабной военной кампании. Однако с твоей помощью мы сумеем выиграть время, чтобы разработать должную стратегию.$B$BЯ велю изучить эти панцири – нам нужно узнать об этих тварях как можно больше, прежде чем бороться с тем, что оказалось куда более сложной задачей, нежели мы предполагали.', 'Ну что, $N, как охота? Ты здесь, чтобы доложить о своих успехах?', NULL, NULL, 'Панцирь Зукк\'аш', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7731, 'Жалохвост', 'Один из разведчиков, исследовавших Гудящую Бездну, доложил о виденном им гигантском насекомом – куда более крупном, чем все остальные замеченные им насекомые. Помимо необычных размеров, оно, по-видимому, окружено какой-то особой аурой, которой у прочих насекомых нет. Мы назвали его жалохвостом. $B$BНам хотелось бы изучить внутренности этой твари, чтобы понять, как лучше бороться с этой новой угрозой. Добудь ядовитые железы жалохвоста и принеси их мне!', 'Убейте жалохвоста в Гудящей Бездне и принести железы ядохлеста Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.', 'Впечатляет, $C... весьма впечатляет! Если жалохвост – действительно одна из самых опасных их тварей, со временем изучение этого существа окажется весьма ценным! Ну, а теперь моя задача – позаботиться, чтобы мы выстояли достаточно долго, чтобы суметь воспользоваться полученными знаниями!$B$BВот, $N, пожалуйста, прими эту монету. Весь лагерь благодарит тебя за отвагу!', 'Ну что, удалось тебе одолеть жалохвоста?', NULL, NULL, 'Железы жалохвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7732, 'Донесение об улье Зукк\'аш', 'Ты поступаешь весьма разумно, направляя свои усилия на борьбу с этими насекомыми, грозящими Лагерю Мохаче. Опасность далеко еще не миновала, и мне хотелось бы попросить тебя о еще одной услуге. Вот в этих бумагах изложены все сведения об улье Зукк\'аш, которые нам удалось раздобыть. Прошу тебя доставить их Зилзибину Барабанному Бою на Волок в Оргриммаре. Он специалист по подобным созданиям; надеюсь, добытые нами знания ему пригодятся.', 'Доставьте отчет о нашествии насекомых-Зукк\'аш на Лагерь Мохаче Зилзибину Барабанному Бою, который проживает на Волоке в Оргриммаре.', 'А-а, я давно ждал подобных вестей... Эти твари, с которыми тебе довелось столкнуться – древняя угроза, которую Орда предпочитает игнорировать. Хадокен поступил мудро, что отправил этот доклад – и тебя с ним, – ко мне.$B$BЦуккаш – это те самые создания, которых именуют силитидами. Многим кажется, будто это просто неразумные твари, но позволь тебя заверить: они значительно, значительно опаснее, чем любая угроза со стороны Альянса!$B$BИ мне бы очень пригодилась твоя помощь в том, чтобы подробнее узнать об этой напасти – если у тебя, конечно, хватит сил и желания мне помогать.', 'Приветствую! У тебя такой вид, словно ты торопишься по срочному делу. Я могу чем-нибудь помочь?', NULL, NULL, 'Отчет о нашествии насекомых-Зукк\'аш на Лагерь Мохаче (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7733, 'Борьба за качество', 'Я знаю, где можно добыть шкуры еще лучше этих – хотя в это и трудно поверить! На севере Фераласа – в глубине Пещеры Бешеного оврага, обитает другая стая йети. Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует!$B$BА я хорошо вознагражу тебя за десяток шкур таких йети. Принеси их мне, и мы договоримся.', 'Принесите 10 шкур йети из пещеры Бешеного оврага Пратту Макгруббену в Крепость Оперенной Луны в Фераласе.', 'Отлично, отлично! Они подойдут мне как нельзя лучше – я уже вижу, что после надлежащей обработки они сделаются гораздо прочнее.$B$BЕще раз спасибо за помощь, $N! Вот, пожалуйста: прими одно из моих последних изделий.', 'Если эти шкуры не уступают шкурам йети Дикого Утеса, они, должно быть, по прочности ничем не хуже тория!$B$BТы только представь себе!', NULL, NULL, 'Шкура йети из пещеры Бешеного оврага', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7734, 'Борьба за качество', 'Я знаю, где можно добыть шкуры еще лучше этих – хотя в это и трудно поверить! На севере Фераласа – в глубине Пещеры Бешеного оврага, обитает другая стая йети. Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует!$B$BА я хорошо вознагражу тебя за десяток шкур таких йети. Принеси их мне, и мы договоримся.', 'Принесите 10 шкур йети из пещеры Бешеного оврага Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе.', 'Отлично, отлично! Они подойдут мне как нельзя лучше – я уже вижу, что после надлежащей обработки они сделаются гораздо прочнее.$B$BЕще раз спасибо за помощь, $N! Вот, пожалуйста: прими одно из моих последних изделий.', 'Если эти шкуры не уступают шкурам йети Дикого Утеса, они, должно быть, по прочности ничем не хуже тория!$B$BТы только представь себе!', NULL, NULL, 'Шкура йети из пещеры Бешеного оврага', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7735, 'Безупречная шкура йети', 'Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети с Дикого утеса.$B$BВам известно, что Пратту Макгруббену из Крепости Оперенной Луны всегда нужны шкуры йети, а уж эта его тем более заинтересует!', 'Отнесите безупречную шкуру йети Пратту Макгруббену в Крепость Оперенной Луны в Фераласе.', 'Невероятно! Да это, можно сказать, царица всех шкур йети!$B$BДа уж, конечно, за такую шкуру я и заплачу по-царски! Обычно за одну-единственную шкуру я дорого не даю, но из этой шкуры я наверняка сумею изготовить нечто особенное. Спасибо, что принес ее мне, $N!', 'Что это, $N? У тебя есть для меня нечто особенное?', NULL, NULL, 'Нетронутая шкура йети (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7736, 'Пополнение запасов огненного плавня – королевская кровь', '', '', 'Плавень в кузне лишним не бывает, поверь моему слову...', NULL, NULL, NULL, 'Чешуя пламезавра', 'Королевская кровь', 'Уголь', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7737, 'Завоевать еще большую благосклонность', '', '', 'Так, давай сюда окалину!', NULL, NULL, NULL, 'Окалина черного железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7738, 'Безупречная шкура йети', 'Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети из Пещеры Бешеного оврага.$B$BВам известно, что Джангору Быстрому Страннику из Лагеря Мохаче всегда нужны шкуры йети, а уж эта его тем более заинтересует!', 'Отнесите безупречную шкуру йети Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе.', 'Невероятно! Это, пожалуй, лучший образчик шкуры йети, какой я когда-либо видел!$B$BДа уж, конечно, за такую шкуру следует заплатить по достоинству! Обычно за одну-единственную шкуру я дорого не даю, но из этой шкуры я наверняка сумею изготовить нечто особенное. Спасибо, что принес ее мне, $N!', 'Что это, $N? У тебя есть для меня нечто особенное?', NULL, NULL, 'Безупречная шкура йети (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7761, 'Приказ Чернорука', 'Недоумок,$B$BКак-то мне очень сомнительно, что ты сумеешь сдержать чужаков и не дать им проникнуть в убежище повелителя. В случае твоей смерти, – а подобный исход более чем вероятен, – у этой сферы есть свой собственный механизм защиты, который не даст чужакам перенестись напрямую в логово Крыла Тьмы.$B$BСферой сможет воспользоваться только тот, кто отмечен меткой Драккисата. К счастью, Драккисат, в отличие от некоторых \"интендантов\", далеко не дурак и хорошо разбирается в своем деле. Он самолично охраняет клеймо!$B$BС уважением, вождь Ренд Чернорук$B$BP.S. Уничтожь это письмо, идиот!', 'Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа.В письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить.', 'Раскаленное клеймо прожигает вам руку, но вы даже не морщитесь. Вы сильны и крепки духом!$B$BТеперь у вас есть метка Драккисата. Самое время устроить потеху и разнести этот замок ко всем чертям!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7781, 'Владыка Черной горы', 'Знакомое чувство ликования охватывает вас: победа!!! Перед вами лежит гигантская, покрытая боевыми шрамами голова Нефариана. Отнесите же ее своему королю!', 'Отнесите голову Нефариана королю Вариану Ринну в Штормград.', 'Вы понимаете значение этой победы, $N? Ваш подвиг войдет в историю Штормграда! Подобного успеха Альянс не знал многие годы!', 'Невероятно!', NULL, NULL, 'Голова Нефариана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7782, 'Владыка Черной горы', 'Отправляйтесь на Аллею Героев и поговорите с фельдмаршалом Стоунбриджем.', 'Поговорите с фельдмаршалом Стоунбриджем на Аллее Героев в Штормграде.', '*Фельдмаршал Афрасиаби кланяется вам.*$B$BВыбирайте награду, и пусть начнется празднество!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7783, 'Владыка Черной горы', 'Ты вновь испытываешь знакомое чувство – сладость победы! У твоих ног лежит массивная, покрытая боевыми шрамами голова Нефариана. Отнеси ее своему вождю, $gвоитель:воительница:!', 'Отнесите голову Нефариана Траллу в Оргриммар.', 'Ты снова принес Орде славу, $N! Сын Смертокрыла мертв. Силам зла будет над чем задуматься!', 'Жаль, что меня там не было, $N! Хотел бы я видеть морду этой твари, когда ты нанес ему смертельный удар!', NULL, NULL, 'Голова Нефариана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7784, 'Владыка Черной горы', 'Разыщи властителя Рунтака в Аллее Силы.', 'Поговорите с властителем Рунтаком в Аллее Силы в Оргриммаре.', 'Выбери себе награду, и я установлю голову этой твари так, чтобы ее могли видеть все!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7785, 'Сосуд Возрождения', 'Изучи Сосуд Возрождения, смертный. Из него возродится Искатель Ветра!', 'Изучите Сосуд Возрождения и вернитесь к верховному лорду Демитриану.', 'Пусть поход твой будет увенчается успехом. Да благословит тебя мой повелитель.', 'Освободишь ли ты его из астральной тюрьмы?', NULL, NULL, 'Сосуд возрождения (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7786, 'Громораан Искатель Ветра', 'Я рассказал тебе все, что знаю, $N. Именно тебе предстоит отыскать элементий и уничтожить воплощение Повелителя огня.$B$BЕсли ты справишься, с тобой пребудет благословение Громораана.', 'Чтобы освободить Громораана Искателя Ветра из тюрьмы, отнесите правый и левый наручник Ветроносца, 10 слитков элементия и сущность Повелителя огня верховному лорду Демитриану.', 'Даже во сне я не чаял увидеть этот день.$B$BЗри же, смертный.$B$BУЗРИ ТОГО, КТО СТАРШЕ СУЩЕГО!$B$BУЗРИ ТОГО, КТО СРАЖАЛСЯ С $NМ И БОГОМ!$B$BВОССТАНЬ, МОЙ ПОВЕЛИТЕЛЬ! ОТРИНЬ ОКОВЫ!', 'Пусть мир падет на колени, если нужно!', NULL, NULL, 'Элементиевый слиток', 'Сущность повелителя огня', 'Наручники Искателя Ветра', 'Наручники Искателя Ветра');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7787, 'Громовая ярость', 'Ты $gодолел:одолела: Искателя Ветра. Отнеси этой лживой предательской скотине, Демитриану, дремлющий клинок и заставь его воспользоваться предоставленными ему материалами и пробудить Громовую ярость.', 'Отдайте Дремлющий клинок Игривого Ветра верховному лорду Демитриану.', 'Прошу, не трогай меня! Возьми, что тебе нужно! Возьми клинок! Позволь Демитриану собирать осколки своей никчемной жизни.', '*Демитриан дрожит от страха.*', NULL, NULL, 'Дремлющий клинок Игривого Ветра (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7788, 'Долой захватчиков!', '$gЮный:Юная:c: $C! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$B$BОтправляйся в ущелье Песни Войны, чтобы оборонять заставу Среброкрылых! Отражай нападения ордынских захватчиков!$B$BНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $N, и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Ордой, получите почетный знак ущелья Песни Войны и вернитесь с ним к часовой Дальней Песне в рощу Среброкрылых.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7789, 'Громи захватчиков-Среброкрылых!', 'Чащобы Ясеневого леса падут перед мощью Орды, $r! Что бы ни делали часовые из армии Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как они смеют препятствовать нам пользоваться тем, что по праву наше?$B$BПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из армии Среброкрылых и заслужи почетный знак ущелья Песни Войны. Вернись ко мне с этим знаком, $N – и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
