INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7809, 'Пожертвование: магическая ткань', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Магическая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7810, 'Повелитель арены', 'Должно быть, стать мастером арены не так просто! Быть может, пират-распорядитель на арене Гурубаши, знает, в чем тут штука!', 'Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.', 'Арр, дорогуша! Одной безделушки недостаточно, чтобы стать мастером Арены! Пришло время проверить тебя на прочность.', NULL, NULL, NULL, 'Мастер Арены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7811, 'Пожертвование: руническая ткань', '', '', 'Невероятно! Мы немедля пустим ее в дело, будьте уверены. Еще раз спасибо за помощь! Без вас мы бы точно пропали.$B$BХотя вы уже и так много пожертвовали ткани, я и в будущем с удовольствием приму от вас любое количество рунной ткани. Просто свяжитесь со мной, и я лично постараюсь, чтобы ваши добрые дела не остались незамеченными!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7812, 'Больше рунической ткани', '', '', 'О, $N, если бы такие герои, как вы, не помогали нам, гномам, мы бы совсем погибли! Благодарю вас за непрестанные труды!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7813, 'Пожертвование: шерсть', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Шерсть', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7814, 'Пожертвование: шелк', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Шелковый материал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7815, 'Хрустогрызы, чувак!', 'Ты не смотри, что у них такие большие красивые глазки! Страшней морского хрустогрыза зверя нет! Только я удочку закину, как приплывают эти черепахи-переростки, жрут мне всю наживку и удилище пополам ломают!$B$BСделай мне и всей нашей деревеньке одолжение – поубивай их всех.$B$BВ смысле, хрустогрызов.', 'Убейте 10 морских хрустогрызов по поручению Катума Удильщика из деревни Сломанного Клыка во Внутренних землях.', 'Ооо! Вот спасибо, вот помог! На тебе удочку, надеюсь, поймаешь на нее воооот такую рыбину!', 'Как идет охота?', NULL, NULL, 'Морской хрустогрыз убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7816, 'Гаммерита!', 'Йоу! Тут живет всем черепахам черепаха – звать Гаммерита – предводительница всех морских хрустогрызов и просто наглая прожорливая рептилия, чтоб ей.$B$BОна сожрала мою лучшую блесну! Взяла и откусила прямо с удочки! С тех пор рыба совсем клевать перестала.$B$BНайди Гаммериту и вытащи у нее из брюха мою блесну!', 'Убейте Гаммериту и верните Катуму Удильщику из деревни Сломанного Клыка его лучшую блесну.Катум сказал, что Гаммерита ползает по берегу среди остальных черепах.', 'ЧУВАК!!! Ну и дела! Блесна есть, хрустогрызов нет, да я сейчас всю рыбу в море переловлю!', 'Нашел ее?', NULL, NULL, 'Лучшая блесна Катума', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7817, 'Пожертвование: магическая ткань', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Магическая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7818, 'Пожертвование: руническая ткань', '', '', 'Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7819, 'Больше рунической ткани', '', '', 'Спасибо, $N! Что бы мы делали без героев, неустанно пекущихся о благе Отрекшихся...', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7820, 'Пожертвование: шерсть', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Шерсть', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7821, 'Пожертвование: шелк', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Шелковый материал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7822, 'Пожертвование: магическая ткань', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Магическая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7823, 'Пожертвование: руническая ткань', '', '', 'Невероятно! Мы немедля пустим ее в дело, будь уверен. Еще раз спасибо за помощь! Без тебя нам бы туго пришлось.$B$BХотя ты уже и так много ткани нам подарил, я и в будущем с удовольствием приму от тебя любое количество рунной ткани. Просто обратись ко мне, и я лично позабочусь о том, чтобы твои добрые дела не остались незамеченными!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7824, 'Пожертвование: руническая ткань', '', '', 'Потрясающе! Эта ткань нам очень пригодится. Еще раз спасибо за помощь! Без тебя мы бы просто пропали.$B$BЕсли в будущем у тебя заведется еще лишняя рунная ткань, приноси и ее, пригодится. Уверяю тебя, твои добрые дела не пропадут втуне!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7825, 'Больше рунической ткани', '', '', 'О, $N, если бы такие герои, как ты, не помогали Громовому Утесу, страдания наши были бы нестерпимы! Благодарю тебя за непрестанные труды!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7826, 'Пожертвование: шерсть', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Шерсть', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7827, 'Пожертвование: шелк', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Шелковый материал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7828, 'Охота на бродяг', 'В диких лесах Внутренних земель погибло много храбрых троллей, $r. Одни из самых опасных животных там – среброгривые волки. Они прячутся в высокой траве и всегда нападают неожиданно.$B$BНельзя закрывать глаза на такую опасность!$B$BУменьшите поголовье среброгривов!', 'Убейте 5 среброгривых бродяг и 5 среброгривых ревунов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.Мархор сказал, что волки обитают в лесах Внутренних земель.', 'Прекрасная работа, $R. Благодарю вас от имени клана Сломанного Клыка.', NULL, NULL, NULL, 'Среброгривый бродяга убито', 'Среброгривый ревун убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7829, 'Охота на дикарей', 'Одни из самых мерзких существ во Внутренних землях – дикие совухи. Сколько храбрых воинов племени Сломанного Клыка они уже разорвали своими когтями и клювами...$B$BУбей всех диких совухов, которых встретишь, $r. Твоя помощь будет взвешена, измерена и по достоинству оценена.', 'Убейте 10 диких совухов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.Мархор сказал, что совухи обитают в лесах Внутренних земель.', 'Вы доказали, что вы – преданный союзник клана Сломанного Клыка, $N. Молодец.', NULL, NULL, NULL, 'Дикий совух убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7830, 'Отмщение за погибших', 'Мерзавцы из клана Громового Молота учат своих грифонов убивать троллей. Ужасно, конечно, но не беспокойся, мы этого так не оставим.$B$BПока что я прошу тебя уничтожить местных вожаков грифонов. Этих остроклювов зовут еще повелителями небес. $B$BУбей одного из них и принеси мне его перо.', 'Убейте остроклюва-повелителя небес и принесите его перо охотнику Мархору в деревню Сломанного Клыка.Мархор говорил, что остроклювы водятся во Внутренних землях.', '*Мархор изучает перо*$B$BИнтересно, сколько наших охотников сожрало это чудовище, прежде чем вы воздали ему по заслугам?', 'Остроклюв-повелитель небес – очень редкая порода грифонов, от которых происходит невероятно агрессивное потомство.', NULL, NULL, 'Перо остроклюва-повелителя небес', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7831, 'Пожертвование: магическая ткань', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Магическая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7832, 'Больше рунической ткани', '', '', 'Да, $N, что бы мы делали без таких героев, как ты, неустанно пекущихся о благе Оргриммара! Спасибо тебе!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
