INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7835, 'Пожертвование: магическая ткань', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Магическая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7836, 'Пожертвование: руническая ткань', '', '', 'Потрясающе! Эта ткань нам очень пригодится. Еще раз спасибо за помощь! Без тебя мы бы просто пропали.$B$BЕсли в будущем у тебя заведется еще лишняя рунная ткань, приноси и ее, пригодится. Уверяю тебя, твои добрые дела не пропадут втуне!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7837, 'Больше рунической ткани', '', '', 'Да, $N, что бы мы делали без таких героев, как ты, неустанно пекущихся о благе племени Черного Копья! Спасибо тебе!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7838, 'Великий повелитель арены', '', '', 'Много крови пролито тобою на песок ринга, и я с радостью нарекаю тебя Великим Повелителем Арены!', NULL, NULL, NULL, 'Мастер Арены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7839, 'Хулиганы из племени Порочной Ветви', 'Эти негодяи из племени Порочной Ветви напали на нашу деревню и украли мои инструменты! У меня, конечно, есть запасные, но тот набор, что они уволокли, был мне дорог как память. Когда я был еще мальчишкой, мне спас жизнь один гном, а потом он подарил мне тот набор.$B$BЯ очень хочу вернуть их, $N, я без них как без рук!$B$BМархор сказал, что мои инструменты видели в храмах Агол\'вата и Шаол\'вата, они оба на северо-востоке Внутренних земель.$B$BПожалуйста, верни мне инструменты!', 'Найдите потерянные инструменты кузнеца Углежога из деревни Сломанного Клыка во Внутренних землях.Углежог сказал, что инструменты могут быть в одном из храмов троллей из племени Порочной Ветви в северо-восточной части Внутренних земель. Также следует проверить на Осклизлой скале.', 'Мои инструменты! Вы их нашли! О, какое счастье! спасибо, $N!', 'Берегитесь троллей из клана Порочной Ветви, $N. Они очень жестоки и агрессивны.', NULL, NULL, 'Потерянные инструменты Углежога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7840, 'Лярд потерял свой обед', 'Лярд хотел устроить пикник в секретном месте, а потом пришли злые тролли из племени Порочной Ветви и побили Лярда большими палками. Лярд убежал в деревню, но потерял свой обед. Лярд голодный... Может, сходишь в секретное место и найдешь там мой обед? Лярд боится. Это на севере! Остров на севере, там секретное место!', 'Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях.Лярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из племени Порочной Ветви.', '*Лярд берет у вас огромный кусок мяса и начинает жадно его грызть*$B$BВот, как хорошо! Спасибо, мелкий.$B$BЛярд даст тебе в подарок эту специальную корзинку для пикника.', '*Лярд потирает огромный живот*$B$BЛярд хочет кушать...', NULL, NULL, 'Обед Лярда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7841, 'Послание для Громового Молота', 'Клан Громового Молота якшается с нашими врагами и заключает с ними союзы. В этот раз они спутались с высшими эльфами. Убей любого эльфа из Высокодолья, которого только встретишь – пусть их тела послужат предупреждением.$B$BС троллями шутки плохи!', 'Убейте 8 гонцов, 5 разведчиков, 5 стрелков и 2 следопытов Высокодолья по поручению Отхо Можи\'ко из деревни Сломанного Клыка.Высших эльфов из Высокодолья можно найти в Сторожке Кель\'Данил в северо-западной части Внутренних земель.', 'Хе, кажется, тролли Сломанного Клыка не ошиблись с выбором союзников! Вы молодец.', NULL, NULL, NULL, 'Разведчик высокодолья убито', 'Гонец высокодолья убито', 'Следопыт высокодолья убито', 'Стрелок высокодолья убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7842, 'Еще одно послание для Громового Молота', 'Говорят, что дворфы Громового Молота и их грифоны – друзья не разлей вода. Хоть это и не очень красиво, но нужно воспользоваться этим преимуществом. Сделаем им еще одно предупреждение.$B$BУбей всех грифонов, каких только встретишь во Внутренних землях, и принеси мне длинное элегантное перо – это должно подействовать.', 'Принесите длинное элегантное перо Отхо Можи\'ко из деревни Сломанного Клыка во Внутренних землях. Перо нужно собрать с местных грифонов, которых можно найти практически в любом месте Внутренних земель.', 'О, друга, хорошо-то как! Еще разок, и эти Громовые Молоты узнают, как связываться с троллями!', 'Наше последнее предупреждение непременно отпугнет их. Или очень сильно разозлит.', NULL, NULL, 'Длинное элегантное перо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7843, 'Последнее послание для Громового Молота', '*Отхо вручает вам длинное окровавленное копье, обернутое перьями грифона*$B$BВот, берите. Отнесите это на Заоблачный пик, в самый центр тамошнего поселения. Воткните копье у колодца, пусть эти дворфы знают, что с нами шутки плохи! А потом возвращайтесь ко мне. Надеюсь еще увидеть вас $gживым:живой:.', 'Доберитесь до Заоблачного Пика в западной части Внутренних земель и оставьте возле колодца в центре города последнее предупреждение для клана Громового Молота. После выполнения задания возвращайтесь к Отхо Можи\'ко в деревню Сломанного Клыка.Берегитесь дворфов из клана Громового Молота и других сторонников Альянса.', 'Жалко, меня там не было, вот бы посмотреть на их рожи! Как они там, друга? Сумки пакуют, бегут из города?$B$BУ тебя отлично все получилось, правда-правда. Отхо дарит тебе вот этот амулет.', NULL, NULL, NULL, 'Послание Громовому Молоту доставлено', 'Последнее послание клану Громового Молота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7844, 'Собратья-каннибалы', 'Во Внутренних землях живет три племени троллей, $N. На этом, собственно, сходство и заканчивается – мы все тролли и мы все живем здесь.$B$BПлемя Порочной Ветви, как следует из названия, самое отвратительное – тамошние каннибалы едят и троллей, и вообще всех, кто подвернется.$B$BЕсли бы Зул\'джин был здесь, он бы уничтожил все это отродье одним движением руки! Но Зул\'джина с нами нет, поэтому приходится справляться самим.$B$BВот тебе задание – пойти и перебить троллей из племени Порочной Ветви.', 'Убейте 6 охотников за скальпами и 2 ворожеев из племени Порочной Ветви по поручению Яо\'джин из деревни Сломанного Клыка.Яо\'джин сказала, что эти тролли живут близ храмов Шаол\'вата и Агол\'вата в северо-восточной части Внутренних земель.', 'Ты молодчина, $C. Сам Зул\'джин бы лучше не сделал!', 'Ворожеи и охотники за скальпами из племени Порочной Ветви живут на северо-востоке Внутренних земель.', NULL, NULL, 'Охотник за скальпами из племени Порочной Ветви убито', 'Ворожей из племени Порочной Ветви убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7845, 'Похищен старейшина Зазубренный Клык!', 'Однажды ночью племя Порочной Ветви совершило набег на нашу деревню, и похитило моего мужа. Наши разведчики узнали, что он еще жив и находится в плену на самом верху Джинта\'Алора. Они сказали, что недобрая жрица Ведьмиса хочет принести его в жертву их безликому кровавому богу Хаккару.$B$BПрошу тебя, $N, спаси его! Наша деревня не переживет такой тяжелой потери.', 'Спасите старейшину Зазубренного Клыка из Джинта\'Алора по поручению его жены из деревни Сломанного Клыка.Старейшину держат в плену на самом верху Джинта\'Алора – главного поселения троллей из племени Порочной Ветви, расположенного на юге Внутренних земель.', 'Действовать нужно быстро, $N. Стражи наверняка вас заметили.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7846, 'Отыскать ключ!', 'Ключ от моих кандалов у Хита\'йи Хранительницы, она в пещере поблизости. Но будь $gосторожен:осторожна:, там полно охраны!$B$BУбей Хранительницу и возьми у нее ключ, иначе мне отсюда не выйти.', 'Убейте хранительницу Хита\'йю и заберите у нее ключ от оков, после чего возвращайтесь к старейшине Зазубренному Клыку и освободите его.', 'Наконец-то, свобода! Спасибо, $N! Клан Сломанного Клыка непременно услышит о ваших подвигах.', 'Поспешите!', NULL, NULL, 'Ключ от кандалов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7847, 'Возвращение к старейшине Зазубренный Клык', 'Вернись к моей жене, старейшине Зазубренный Клык! Скажи ей, что со мной все хорошо, и что скоро я буду дома. Она непременно наградит тебя за это известие.', 'Возвращайтесь к старейшине Зазубренный Клык и сообщите ей, что ее муж спасен.', 'Вы оказали клану Сломанного Клыка неоценимую услугу, $N! Мы навечно в долгу перед вами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7848, 'Сродство с недрами', 'Земля испещрена трещинами и разломами – прямо у нас под ногами, $r. В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра в Черной горы, в самую вотчину Повелителя огня.$B$B<Удивлен:Удивлена:? Прискорбно... Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб...$B$BУверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться.$B$BСмотрю, у тебя глаза заблестели. Послушай, приобрести сродство с недрами не так сложно. Отправляйся в Глубины Черной горы и принеси мне осколок из Огненных Недр. Я сделаю так, что ты сможешь видеть портал.', 'Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе.', 'Теперь я могу открыть тебе дорогу в Огненные Недра. Ищи и обрящешь...', 'Только те, чья сущность в сродстве с Огненными Недрами, могут прийти через портал.', NULL, NULL, 'Осколок из Огненных Недр', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7849, 'Воссоединение останков', 'Как и у многих других жителей нашей деревни, мой близкий родственник погиб в лесу. Это был мой брат-близнец Малькор – он погиб в бою с троллями из племени Порочной Ветви, тогда же, когда пропал муж старейшины Зазубренный Клык.$B$BМоего брата быстро казнили, а его останки бросили на съедение слизнюкам и волкам.$B$BЖизнь его мы не уберегли, но душу спасти еще можно. Пожалуйста, принеси мне его останки, $N.', 'Принесите охотнику Мархору из деревни Сломанного Клыка во Внутренних землях кости и череп его брата-близнеца.Мархор сказал, что останки его брата бросили на съедение слизнюкам и волкам племени Порочной Ветви – все эти твари водятся неподалеку от вершины Джинта\'Алора: слизнюки в компостной яме, а волки – в логове.', 'Мой милый брат, как же мне тебя не хватает...$B$BСпасибо за помощь, $N. Вы настоящий герой.', 'Когда все его останки будут у меня, я отнесу из Яйо\'джину и подготовлю их к надлежащему погребению.', NULL, NULL, 'Череп охотника Мальхора', 'Кости охотника Мальхора', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7850, 'Темные сосуды', 'Тролли из племени Порочной Ветви проявляют в бою необычайную свирепость! Это все потому, что их околдовала недобрая коварная жрица Ведьмиса.$B$BВ поселении Джинта\'Алор можно найти очень много сосудов с порченой кровью, которые излучают те$Nю магию безликого кровавого бога и наделяют троллей из племени Порочной Ветви сверхъестественными силами, сводя их с ума.$B$BУкради эти сосуды и принеси их мне, чтобы я сняла порчу и ослабила хватку кровавого бога.', 'Принесите 5 сосудов с порченой кровью старейшине племени Сломанного Клыка во Внутренние земли. Сосуды с кровью находятся в поселении Джинта\'Алор.', 'Зло, которому подчинялись тролли из клана Порочной Ветви, на время ослабло. Однако нельзя терять бдительности, потому что даже если одна жрица погибнет, ее место вскоре займет другая.', 'Будьте осторожны в бою с троллями Порочной Ветви, $N. Их разум затуманен, и драться они будут до смерти.', NULL, NULL, 'Сосуд с порченой кровью', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7861, 'Разыскивается: коварная жрица Ведьмиса и ее прислужники', 'По приказу старейшины Зазубренный Клык разыскивается коварная жрица Ведьмиса и ее приспешники.$B$BТот, кто убьет Ведьмису и ее стражей Аман\'заси, получит отличную награду!', 'Убейте коварную жрицу Ведьмису и 5 стражей Аман\'заси из племени Порочной Ветви, после чего доложите старейшине племени Сломанного Клыка во Внутренних землях.Коварную жрицу Ведьмису и стражей Аман\'заси можно найти в верхней части Джинта\'Алора во Внутренних землях.', 'Это серьезный удар по клану Порочной Ветви. Вы получите достойную награду, $N.', NULL, NULL, NULL, 'Коварная жрица Ведьмиса убито', 'Страж Аман\'заси из племени Порочной Ветви убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7862, 'Требуется: капитан стражи в деревню Сломанного Клыка', 'Капитан стражи Малькор погиб, и теперь эта должность свободна. Если вы хотите стать капитаном стражи в деревне Сломанного Клыка, выполните эти задания и подайте заявление старейшине Зазубренный Клык.$B$BУничтожьте берсерков из племени Порочной Ветви.$B$BУничтожьте темных охотников из племени Порочной Ветви.$B$BУничтожьте кровопийц из племени Порочной Ветви.$B$BУничтожьте пожирателей душ из племени Порочной Ветви.', 'Убейте 5 берсерков, 3 темных охотника, 3 кровопийц и 2 пожирателей душ из племени Порочной Ветви.После выполнения задания вернитесь к старейшине Сломанному Клыку в деревню Сломанного Клыка.', 'Вы и правда отлично подходите для такой работы, $N. Примите это в знак признательности и благодарности за ваши старания. Через год я еще раз пересмотрю все кандидатуры.', NULL, NULL, NULL, 'Берсерк из племени Порочной Ветви убито', 'Темный охотник из племени Порочной Ветви убито', 'Кровопийца из племени Порочной Ветви убито', 'Пожиратель душ из племени Порочной Ветви убито');
