INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7868, 'Улучшенные припасы Всадников', '', '', 'Ты хорошо зарекомендовала себя, $N, тут сомнений нет! В награду возьми этот пакет! В нем паек и бинты, которые найдешь только в ущелье Песни Войны.Когда в ущелье тебя еще больше зауважают, тебе их тут даже продадут. Паек мы выдаем, если относимся к кому-то дружественно, а бинты – когда уважаем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7871, 'Долой захватчиков!', '$gЮный:Юная:$C! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$B$BОтправляйся в ущелье Песни Войны, чтобы оборонять заставу Среброкрылых! Отражай нападения ордынских захватчиков!$B$BНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $N, и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Ордой, получите почетный знак ущелья Песни Войны и вернитесь с ним к часовой Дальней Песне в рощу Среброкрылых.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7872, 'Долой захватчиков!', '$gЮный:Юная: $C! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$B$BОтправляйся в ущелье Песни Войны, чтобы оборонять заставу Среброкрылых! Отражай нападения ордынских захватчиков!$B$BНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $N, и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Ордой, получите почетный знак ущелья Песни Войны и вернитесь с ним к часовой Дальней Песне в рощу Среброкрылых.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7873, 'Долой захватчиков!', '$gЮный:Юная:c: $C! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$B$BОтправляйся в ущелье Песни Войны, чтобы оборонять заставу Среброкрылых! Отражай нападения ордынских захватчиков!$B$BНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $N, и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Ордой, получите почетный знак ущелья Песни Войны и вернитесь с ним к часовой Дальней Песне в рощу Среброкрылых.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7874, 'Громи захватчиков-Среброкрылых!', 'Чащобы Ясеневого леса падут перед мощью Орды, $r! Что бы ни делали часовые из армии Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как они смеют препятствовать нам пользоваться тем, что по праву наше?$B$BПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из армии Среброкрылых и заслужи почетный знак ущелья Песни Войны. Вернись ко мне с этим знаком, $N – и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7875, 'Громи захватчиков-Среброкрылых!', 'Чащобы Ясеневого леса падут перед мощью Орды, $r! Что бы ни делали часовые из армии Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как они смеют препятствовать нам пользоваться тем, что по праву наше?$B$BПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из армии Среброкрылых и заслужи почетный знак ущелья Песни Войны. Вернись ко мне с этим знаком, $N – и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7876, 'Громи захватчиков-Среброкрылых!', 'Чащобы Ясеневого леса падут перед мощью Орды, $r! Что бы ни делали часовые из армии Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как они смеют препятствовать нам пользоваться тем, что по праву наше?$B$BПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из армии Среброкрылых и заслужи почетный знак ущелья Песни Войны. Вернись ко мне с этим знаком, $N – и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7877, 'Сокровище Шен\'драларов', 'В библиотеке, Читальне, ты найдешь древний сундук, спрятанный под лестницей. Можешь взять оттуда, что тебе понравится.', 'Вернитесь в Читальню и найдите сокровище Шен\'драларов. Получите свою награду!', 'Вы открываете сундук и находите там...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7881, 'Тисненые кожаные сапоги', '', '', '', NULL, NULL, NULL, 'Тисненые кожаные сапоги', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7882, 'Кожаные куртки', '', '', 'Ага, это же мои доспехи! Великолепно. Из какой кожи сделаны, можно полюбопытствовать? Швы прочные, материал плотный... Загляденье! Ты – настоящий мастер, $N, прими мои комплименты! $B$BБлагодарю тебя от всей души. Держи обещанные купоны.', NULL, NULL, NULL, 'Утяжеленный кожаный доспех', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7883, 'Гном-гигант!', '', '', 'Вот это размерчик! Даже не знаю, найдет ли Эбби эдакого гнома - ну да ладно, в крайнем случае подошьем костюм.$B$BСпасибо тебе, $N. Вот обещанные купоны.', NULL, NULL, NULL, 'Варварская портупея', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7884, 'Мальчик-кроколиск и бородатый мурлок', '', '', 'Красота! Как раз мой размерчик. Надеюсь, мне не придется чистить клетку с кроколисками. Очень неприятные зверьки, правда?$B$BВот твои купоны, $N. Приятного отдыха на ярмарке!', NULL, NULL, NULL, 'Черепашьи чешуйчатые поножи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7885, 'Накладки на доспехи', '', '', 'Отлично! Эта броня вполне сгодится! Ты посмотри, опять дырка в шатре... сейчас твои комплекты в момент разлетятся на заплаты!$B$BСпасибо огромное, $N. Эти комплекты помогут значительно сократить наши расходы на ремонт. А вот и твои купоны – ты их заслужил!', NULL, NULL, NULL, 'Комплект грубой брони', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7889, 'Зернистое грузило', '', '', 'Вот это я понимаю! Не слишком тяжелые, но и вес чувствуется. Отлично подойдут для наращивания мышечной массы!$B$BТрижды спасибо, $N. А вот твой купон!', NULL, NULL, NULL, 'Зернистое грузило', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7890, 'Тяжелый точильный камень', '', '', 'Мои камушки! А какие тяжеленькие! Уже чувствую, как мышцы наполняются силой. Спасибо большое, $N!$B$BВот, возьми купоны – и смотри, не объедайся сладким! $C вроде тебя должен держать себя в хорошей боевой форме!', NULL, NULL, NULL, 'Тяжелый точильный камень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7891, 'Зеленые железные наручи', '', '', '', NULL, NULL, NULL, 'Зеленые железные наручи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7892, 'Большая черная палица', '', '', '', NULL, NULL, NULL, 'Большая черная палица', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7893, 'Ритуалы Силы', '', '', 'Благодарю тебя, $N. Эти камни нужны мне для ритуала, о котором я узнала из древней скрижали, найденной в глубоких джунглях Тернистой долины.$B$BТам говорится, что та, кто верно выполнит ритуал, станет обладательницей силы десяти тауренов!', NULL, NULL, NULL, 'Массивный шлифовальный камень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7894, 'Медный регулятор', '', '', 'Ага! Модуляторы! Супер!$B$BПока что я не могу тебе сказать, что мы возводим, но без модуляторов все просто развалится. Я твой должник, $N Прими от меня этот купон и сердечную благодарность!', NULL, NULL, NULL, 'Медный регулятор', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7895, 'Трещащий бронзовый механизм', '', '', 'Мои трещоточки! Прелестно! Как чудесно они жужжат и стрекочут! О, когда я оборудую свой балаганчик, он станет одним из чудес света, запомни мои слова!$B$BВот твои купончики, $N. Приятного отдыха на Ярмарке!', NULL, NULL, NULL, 'Трещащий бронзовый механизм', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7896, 'Зеленые фейерверки', '', '', '', NULL, NULL, NULL, 'Зеленый фейерверк (36)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7897, 'Автоматические ремонтные наборы', '', '', 'Благодарю! Пора приступать к ремонту.$B$BСколько же ночей мне придется провозиться, чтобы все прикрутить на место... Знаешь, иногда мне снова хочется стать охотником за головами, но... на ярмарке в сто раз лучше!$B$BВозьми купоны, Нагибайся, веселись и отдыхай на здоровье!', NULL, NULL, NULL, 'Автоматический ремонтный набор', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7898, 'Ториевое устройство', '', '', 'Премного благодарен, $N! Эбби как раз такие устройства и искал. Не знаю уж, зачем они ему, но Эбби ума не занимать, мозговитый гном. Мозговитый и даже немного не от мира сего...$B$BЭх, если бы он хоть разок отведал нежной человечины, какой бы тролль из него вышел!$B$BВот, Профессия. Сделка есть сделка, забирай купоны.', NULL, NULL, NULL, 'Ториевое устройство', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7899, 'Маленькие мохнатые лапки', '', '', 'Отличные экземпляры! Наделаем игрушек да сувениров – и у нас отбою не будет от посетителей!$B$BВот твой купон, $N. Ты его заслужил!', NULL, NULL, NULL, 'Маленькая мохнатая лапка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7900, 'Разорванные шкуры', '', '', 'Прекрасные шкуры, $N! Посажу за работу швей и художников. Сошьем, набьем, покрасим – и таких игрушек не будет больше ни у кого в Азероте!$B$BКакие такие купоны? Ай, забыл – вот, держи!', NULL, NULL, NULL, 'Разорванная шкура медведя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7901, 'Мягкие, пушистые хвосты', '', '', 'Вот молодчина, $N! Теперь посетители унесут с собой не только воспоминания о ярмарке, но и очень дорогостоящие сувениры! Потом они покажут \"Пышный хвост\" друзьям, и те захотят себе такой же, могу поспорить на что угодно.$B$BЛадно, что-то я заболтался. Вот твои купоны! Развлекайся и веселись... и не забудь рассказать о ярмарке всем друзьям и знакомым!', NULL, NULL, NULL, 'Мягкий пушистый хвост', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7902, 'Радужные перья', '', '', 'Ага, вот и мои перышки! Прелесть, не так ли? От такой красоты даже у мертвого разыграется воображение!$B$BТы мне так помог, $N. Лучшая награда для меня – улыбки на лицах посетителей, а тебе причитаются обещанные купоны!', NULL, NULL, NULL, 'Радужное перо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7903, 'Глаза злобных летучих мышей', '', '', 'Бесподобно! Целая горсть глаз! Надеюсь, тебе было страшно на них охотиться! Ага! Если уж такой бравый $C до сих пор дрожит от страха, что же будет с нашими несчастными посетителями?!$B$BВот, возьми эти купоны, $N, и спасибо тебе за услугу!', NULL, NULL, NULL, 'Глаз злобной летучей мыши', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7905, 'Ярмарка Новолуния', 'Скоро начнется Ярмарка Новолуния – время чудес и веселья!$B$BЕсли ты поторопишься, то сможешь обменять этот сертификат на бесплатные призовые купоны! Передай сертификат Гелвасу Углешлюзу в ярмарочном лагере.$B$BСейчас ярмарка стоит рядом со Златоземьем, в Элвиннском лесу. Не упусти свой шанс! Отправляйся прямо сегодня!', 'Передайте сертификат на призовой купон Гельвасу Угольному Шлюзу в лагерь ярмарки Новолуния.', 'Добро пожаловать на ярмарку Новолуния! Этот сертификат на ПЯТЬ, да, целых ПЯТЬ призовых купонов!$B$BКогда у вас будет их побольше, обратитесь ко мне, и я обменяю их на ценные призы. Чем больше вы получите купонов, тем больше выиграете призов. Вперед!', 'Да, $N, чем могу служить? У вас есть сертификат на призовой б$N?', NULL, NULL, 'Бесплатное поручительство (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7907, 'Карты Новолуния: Звери', 'Как только вы собираете вместе восемь карт из колоды Зверей, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите колоду Зверей на ярмарку Новолуния.', 'Итак, ты собрал колоду Зверей. Отныне ты всегда можешь рассчитывать на хорошее отношение к себе на нашей ярмарке. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты Зверей! Поздравляю!', NULL, NULL, 'Колода Зверей (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7908, 'Повелитель арены', 'Должно быть, стать мастером арены не так просто! Быть может, пират-распорядитель на арене Гурубаши, знает, в чем тут штука!', 'Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7926, 'Ярмарка Новолуния', 'Скоро начнется Ярмарка Новолуния – время чудес и веселья!$B$BЕсли ты поторопишься, то сможешь обменять этот сертификат на бесплатные призовые купоны! Передай свой сертификат Гелвасу Углешлюзу в ярмарочном лагере.$B$BСейчас ярмарка стоит рядом с Громовым Утесом, в Мулгоре. Не упусти свой шанс! Отправляйся прямо сегодня!', 'Передайте сертификат на призовой купон Гельвасу Угольному Шлюзу в лагерь ярмарки Новолуния.', 'Добро пожаловать на ярмарку Новолуния! Этот сертификат на ПЯТЬ, да, целых ПЯТЬ призовых купонов!$B$BКогда у вас будет их побольше, обратитесь ко мне, и я обменяю их на ценные призы. Чем больше вы получите купонов, тем больше выиграете призов. Вперед!', 'Да, $N, чем могу служить? У вас есть сертификат на призовой б$N?', NULL, NULL, 'Бесплатное поручительство (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7927, 'Карты Новолуния:Порталы', 'Как только вы собираете вместе восемь карт из колоды Порталов, девятая карта с такой же \"рубашкой\" появляется в колоде мистическим образом. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите карты Порталов на ярмарку Новолуния.', 'Итак, ты собрал колоду Порталов. Отныне между тобой и Ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты Порталов! Поздравляю!', NULL, NULL, 'Колода Порталов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7928, 'Колода карт Новолуния: Полководцы', 'Как только вы собираете вместе восемь карт из колоды воинов, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите колоду Полководцев на ярмарку Новолуния.', 'Итак, ты собрал колоду Полководцев. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты Полководцев! Поздравляю!', NULL, NULL, 'Колода Полководцев (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7929, 'Колода карт Новолуния: Элементали', 'Как только вы собираете вместе восемь карт из колоды Элементалей, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите колоду Элементалей на ярмарку Новолуния.', 'Итак, ты собрал колоду Элементалей. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты из колоды Элементалей! Поздравляю!', NULL, NULL, 'Колода элементалей (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7930, '5 купонов – цветок Новолуния', '', '', 'Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7931, '5 купонов – поощрительный приз Новолуния', '', '', 'Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7932, '12 купонов – малый приз Новолуния', '', '', '', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7933, '40 купонов – большой приз Новолуния', '', '', 'Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7934, '50 купонов – ящик Новолуния', '', '', 'Не зевай, забирай! Приз, достойный королевы! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7935, '10 купонов – прошлогодний окорок', '', '', '', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7936, '50 б$Nов – прошлогодний окорок', '', '', '', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7937, 'Ты найдешь свою удачу...', '\"Ты найдешь свою удачу в Восточной долине\".$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите Лесопилку Восточной долины в Элвиннском лесу. Возле стойл стоит копна сена... На этом видение обрывается.', 'Отыщите свою удачу на Лесопилке Восточной долины в Элвиннском лесу.', 'В копне сена был надежно спрятан небольшой сундучок. Видимо, в нем-то и скрывается ваша удача.', 'Судя по видению, вам нужна именно эта копна сена...', NULL, NULL, 'Предсказание Сейджа #23 (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7938, 'Ты найдешь свою удачу...', '\"Ты найдешь свою удачу в Мертвых копях\".$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите Мертвые копи возле разрушенной деревни Луноречье в Западном Крае. Запутанные ходы приводят вас к порталу, который ведет в самое сердце шахт. Вдруг перед порталом возникает странный сундук... На этом видение обрывается.', 'Отыскать свою удачу в Мертвых копях в Западном Крае.', 'В сундуке оказался еще один сундучок. Видимо, в нем-то и скрывается ваша удача.', 'Этот сундук очень похож на тот, что явился вам в видении.', NULL, NULL, 'Предсказание Сейджа #24 (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7939, 'Обмен: массивные шлифовальные камни', '', '$N, я от всей души благодарю тебя за помощь. Не представляешь, как ты мне помог.Знаешь что... если ты снова принесешь мне массивные шлифовальные камни, то я подкреплю свою благодарность купонами ярмарки!', 'Снова спасибо, $N. Вот твой подарок – купоны ярмарки Новолуния. Не забудь рассказать о ярмарке друзьям!', NULL, NULL, NULL, 'Массивный шлифовальный камень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7940, '1200 б$Nов – сфера Новолуния', '', '', 'Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния (1200)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7941, 'Еще накладки на доспехи', '', '', 'Держи б$Nы, $N. Удачно тебе повеселиться!', NULL, NULL, NULL, 'Комплект грубой брони', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7942, 'Обмен: ториевые устройства', '', '', 'Вот твои купоны, $N. Смотри, не трать их все в одном месте!', NULL, NULL, NULL, 'Ториевое устройство', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7943, 'Обмен: глаза летучих мышей', '', '', 'Спасибо тебе, $N. А вот и твои б$Nы!', NULL, NULL, NULL, 'Глаз злобной летучей мыши', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7944, 'Ты найдешь свою удачу...', '\"Ты найдешь свою удачу в Пещерах Стенаний.\"$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите пещеру, расположенную к юго-западу от Перекрестка в Степях. Запутанные ходы приводят вас к порталу, который ведет в самое сердце пещеры. Вдруг перед порталом возникает странный сундук. На этом видение обрывается.', 'Отыскать свою удачу в Пещерах Стенаний в Степях.', 'В сундуке оказался еще один сундучок. Видимо, в нем-то и скрывается ваша удача.', 'Этот сундук очень похож на тот, что явился вам в видении.', NULL, NULL, 'Предсказание Сейджа #25 (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7945, 'Ты найдешь свою удачу...', '\"Ты найдешь свою удачу возле утеса Бледногривов\".$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите утес Бледногривов в Мулгоре. Возле входа в пещеру стоит пень... На этом видение обрывается.', 'Отыскать свою удачу возле утеса Бледногривов в Мулгоре.', 'Из дупла в пне вы извлекли небольшой сундучок. Видимо, в нем-то и скрывается ваша удача.', 'Судя по видению, вам нужен именно этот пень...', NULL, NULL, 'Предсказание Сейджа #27 (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7946, 'Потомство Жабжаб', '', '', 'Спасибо, $N. А вот и обещанное яйцо! Детеныш еще не готов вылупиться, но, когда придет срок, у тебя появится прекрасный питомец!', NULL, NULL, NULL, 'Кружка эля Черного Железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7961, '', '', 'Соберите 10 несчастливых лапок кролика и вернитесь к Джону Лекрафту к кузнице на острове Дизайнера.', '', NULL, NULL, NULL, 'Кроличья лапка, приносящая неудачу', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (7981, '1200 б$Nов – амулет Новолуния', '', '', 'Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния (1200)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8041, 'Сила горы Мугамба', '', '', 'Привет тебе, $C. Я – Джин\'рок Разрушитель, тролль Мугамбы. В Зандаларе нет ни одного тролля, который не слышал бы о твоих подвигах. Твои упорство и сила воли нас восхищают.Носи этот талисман на шее, $C. Пусть сила Мугамбы наполнит тебя и поможет в сражениях с нашими общими врагами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8042, 'Сила горы Мугамба', '', '', 'Наши пути еще пересекутся, $C.', NULL, NULL, NULL, 'Сила Мугамбы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8043, 'Сила горы Мугамба', '', '', 'Используй обретенную мощь, чтобы сокрушить Гурубаши!', NULL, NULL, NULL, 'Сила Мугамбы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8044, 'Ярость Мугамбы', '', '', 'Тебе позавидовал бы сам Зул\'джин, $c. Иди в бой, не страшась, и всегда возвращайся с победой!', NULL, NULL, NULL, 'Сила Мугамбы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8045, 'Клеймо язычника', '', '', 'Знай, язычник: несчастье сплотило нас. Здесь, в Зандаларе, не понимают и не принимают твоей веры, но нам не чужда терпимость. Носи этот талисман в знак нашей дружбы, и пусть он послужит предостережением твоим врагам.Продолжай сражаться во славу нашего племени, и тогда я увеличу силу клейма.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8046, 'Клеймо язычника', '', '', 'Делай, что считаешь нужным, чтобы уничтожить наших врагов, $C. Даже если это означает служить Свету.$B$B*Джинрок морщится.*', NULL, NULL, NULL, 'Клеймо Язычника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8047, 'Клеймо язычника', '', '', 'Наши верования различаются, но я признаю, что твои намерения благородны. Истреби наших врагов, благородный $C.', NULL, NULL, NULL, 'Клеймо Язычника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8048, 'Печать героя', '', '', '', NULL, NULL, NULL, 'Клеймо Язычника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8049, 'Око Зулдазара', '', '', 'Прими этот талисман в знак нашей признательности, $c.С тех пор как ты связал свою жизнь с троллями Зандалара, Глаз Зулдазара исполнился великой силы. Возвращайся ко мне время от времени, чтобя я мог наполнить его энергией.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8050, 'Око Зулдазара', '', '', '', NULL, NULL, NULL, 'Око Зулдазара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8051, 'Око Зулдазара', '', '', '', NULL, NULL, NULL, 'Око Зулдазара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8052, 'Всевидящее Око Зулдазара', '', '', '', NULL, NULL, NULL, 'Око Зулдазара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8053, 'Знаки Силы: боевые наручи вольнодумца', 'Ты – $gязычник:язычница:, но мы не преследуем язычников в нашем племени. Мы уважаем тех, кто не боится гонений и без колебаний готов принять смерть за свою веру. Мы знаем, что ты $gготов:готова: умереть за свои убеждения, наши вольнодумцы тоже были такими.$B$BНам нужны знаки силы. Ступай в Зул\'Гуруб и уничтожь прислужников Хаккара. Возвращайся, когда найдешь то, что мне нужно. В обмен я отдам тебе одну из деталей доспехов зандаларских вольнодумцев.', 'Принесите Джин\'року Разрушителю изначальные наручники племени Хаккари. Требуется дружелюбное отношение племени Зандалар.Джин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.', 'Ты многое сделал для того, чтобы прославить наше племя. Теперь, когда твои руки обагрены кровью приспешников Хаккара, любой в Зандаларе назовет тебя другом.$B$BНоси с честью эти боевые наручи Вольнодумца. В них заключена настоящая сила.', 'Ты вернулся? Знаки Силы с тобой? Или ты просто отнимаешь у меня время?$B$BЯ надеюсь, что нет, язычник.', NULL, NULL, 'Изначальные наручники племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8054, 'Знаки силы: пояс вольнодумца', 'Твои верования для нас чужды, $gязычник:язычница:. Но племя Зандалар в свое время тоже называли еретиками. Это было еще во времена расцвета Гурубаши. Тогда язычники осмелились бросить вызов жрецам Хаккара. Их нещадно преследовали и уничтожали, словно диких зверей, но они до самого конца не отступили в своей борьбе против Кровавого бога. Мы понимаем, какую цену им пришлось заплатить, и чтим их мужество. Они были настоящими вольнодумцами. $B$BУничтожь приспешников Хаккара в Зул\'Гурубе и принеси мне знаки силы. В случае успеха тебя ждет награда.$B$BСтупай.', 'Принесите Джин\'року Разрушителю изначальную лацерну племени Хаккари. Требуется уважение племени Зандалар.Джин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.', 'Не зря тебя уважают в нашем племени. Ты сеешь смерть среди врагов, Зул\'Гуруб трепещет от одного твоего взгляда.$B$BВот он, пояс вольнодумца. Носи его с честью. На него наложено могучее заклятие, отныне пусть оно хранит тебя.', 'Знаки у тебя? Обагрила ли кровь врагов твои доспехи?', NULL, NULL, 'Изначальная лацерна племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8055, 'Знаки Силы: кираса вольнодумца', 'Боевое снаряжение – это символ могущества. Вольнодумцы же особенно гордятся своими доспехами. Они усиливают кирасы могущественными заклятиями, и даже если во время боя их вера пошатнется, то кирасы выдержат все что угодно.$B$BЕсли ты заслужишь уважение нашего племени, то получишь такую кирасу. Ступай в Зул\'Гуруб и принеси мне Знаки Силы. Вырви их у врага безо всякой пощады. Докажи, что ты заслуживаешь звания вольнодумца.', 'Принесите Джин\'року Разрушителю изначальную гербовую накидку племени Хаккари. Требуется почтение племени Зандалар.Джин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.', 'Тебе удалось сделать то, что до сих пор удавалось немногим. Теперь-то прислужники Хаккара знают, что значит настоящий вольнодумец! Оказывается, заслужить уважение племени могут даже еретики вроде тебя.$B$BПрими эту кирасу, вольнодумец. Пусть она поможет тебе сокрушить всех, кто встанет у тебя на пути!', 'Знаки Силы у тебя? Нам необходимы могучие заклятия, заключенные в них. Если ты добудешь эти знаки, то здорово поможешь племени.', NULL, NULL, 'Изначальная гербовая накидка Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8056, 'Знаки Силы: наручи авгура', 'Авгуры нашего племени очень гордятся своим даром предвидения. Это тебе не знахари, которые только и знают, что проклинать направо и налево! Нет, наши авгуры предсказывают будущее по костям и листьям. Тебе, как $gшаману:шаманке:, должно быть известно, на что способны авгуры. В Зандаларе их откровения очень ценятся.$B$BПокажи нам, чего ты стоишь, и принеси знаки силы из Зул\'Гуруба. Если тебе это удастся, я отдам тебе наручи, которыми наши авгуры очень дорожат.', 'Принесите Майвики из Зулдазара изначальные обручья племени Хаккари. Требуется дружелюбное отношение племени Зандалар.Майвики из Зулдазара живет на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальные обручья племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8057, 'Знаки Силы: наручи гаруспика', 'Гаруспики играют не последнюю роль в нашем племени; если ты достаточно $gмудр:мудра:, то обязательно прислушаешься к их предсказаниям. Они читают судьбу по внутренностям животных и приносят их в жертву духам, чтобы узнать божественную волю. Именно мудрость гаруспиков дала нам преимущество в войне с разрозненными племенами империи Гурубаши.$B$BДокажи нашему племени, чего ты стоишь. Принеси из Зул\'Гуруба знаки силы, и я отдам тебе наручи, от которых не отказался бы никто из гаруспиков Зандалара.', 'Принесите Майвики из Зулдазара изначальный браслет племени Хаккари. Требуется дружелюбное отношение племени Зандалар.Майвики из Зулдазара находится на острове Йоджамба, в Тернистой долине.', 'О да, я чувствую силу, исходящую от этих Знаков, $N. Ты заслужила право называться другом племени! И, конечно же, я помню про сделку... Вот твои наручи гаруспика!', 'Ты добыл Знаки Силы в Зул\'Гурубе? Эти наручи того стоят, $N, можешь мне поверить!', NULL, NULL, 'Изначальный браслет племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8058, 'Знаки Силы: боевые наручи воздаятеля', 'Месть – это сила. Именно она движет воздаятелями Зандалара. У племени много врагов, и воздаятели несут им возмездие. Ни одно преступление против нас не останется безнаказанным! Враги должны бояться нашей мести! Так было раньше и так будет всегда.$B$BСтань одним из наших воздаятелей! Найди знаки силы в Зул\'Гурубе. Сверши возмездие от имени нашего племени и уничтожь прислужников Хаккара. Ты будешь $gвознагражден:вознаграждена:.', 'Принесите Джин\'року Разрушителю изначальные обручья племени Хаккари. Требуется дружелюбное отношение племени Зандалар.Джин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.', 'Ты славно отомстил нашим врагам. Именно таков и должен быть зандаларский блюститель!$B$BВозьми эти наручи. Пусть они напитают силой твою месть. Знай, что с этой минуты в Зандаларе тебя считают другом.', 'Тебе удалось достать Знаки Силы? Свершилось ли возмездие во имя Зандалара?', NULL, NULL, 'Изначальные обручья племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8059, 'Знаки Силы: напульсники бесноватого', 'Чернокнижники ступают на опасную почву, заключая сделки с демонами, но наши бесноватые зашли еще дальше. С помощью древнего ритуала они позволяют демону захватить свое тело, а потом пытаются подчинить его своей воле и использовать его силу. Совершить такой подвиг удается не многим.$B$BЕсли хочешь приобщиться к знанию бесноватых, принеси мне знаки силы из Зул\'Гуруба.', 'Принесите Аль\'табиму Всевидящему изначальный браслет племени Хаккари. Требуется дружелюбное отношение племени Зандалар.Аль\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.', 'Превосходно сработано... Я чувствую, что Знаки Силы были вырваны у приспешников Хаккара ценою их ужасных мучений. Возьми эти напульсники. На них наложены могучие заклятия, заключающие в себе силу плененных демонов. Они послужат тебе в сражениях.', 'Тебе удалось добыть Знаки Силы? Сражаясь со злобными приспешниками Хаккара, ты не только доказываешь готовность постичь пути бесноватых, но подтверждаешь для нас свою важность.', NULL, NULL, 'Изначальный браслет племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8060, 'Знаки Силы: напульсники мастера иллюзий', 'Маги нашего племени – это творцы иллюзий. В свои чары они вплетают заклинания, одурманивающие врагов и сбивающие их с толку.$B$B<Аль\'табим злорадно хихикает.>$B$BНаблюдать за работой настоящего мастера иллюзий – истинное удовольствие. Ты можешь видеть, как враг уничтожает себя сам, все больше и больше погружаясь в безумие.$B$BЕсли хочешь узнать о мастерах иллюзий побольше, ступай в Зул\'Гуруб и принеси мне знаки силы. Взамен я отдам тебе напульсники, которые использовали наши мастера иллюзий, творя свои заклинания.', 'Принесите Аль\'табиму Всевидящему изначальные наручники племени Хаккари. Требуется дружелюбное отношение племени Зандалар.Аль\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.', 'Невероятно... Ты чувствуешь силу, которую они излучают? Во времена империи Гурубаши Знаками Силы иногда обменивались как монетами. Теперь мы в Зандаларе используем скрытые в них заклинания, чтобы предотвратить новое пришествие Кровавого бога Хаккара.$B$BТы славно потрудился, Эст, отныне можешь считать себя в Зандаларе другом. Прими эти напульсники мастера иллюзий.', 'О, Эст, ты уже вернулся? Тебе удалось достать Знаки Силы?', NULL, NULL, 'Изначальные наручники племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8061, 'Знаки Силы: напульсники исповедника', 'В Зандаларе принято одаривать силой тех, кто общается с богами и власть имущими. Наши жрецы не просто целители – они исповедники нашего племени. Зло приходит как снаружи – из Зул\'Гуруба, так и изнутри. Наши исповедники – наши судьи, которые оберегают нас от того зла, что поглотило Гурубаши.$B$BСтупай в Зул\'Гуруб и принеси знаки силы. Узнай, что значит быть исповедником, и охрани нас от зла.', 'Принесите Аль\'табиму Всевидящему изначальный браслет племени Хаккари. Требуется дружелюбное отношение племени Зандалар.Аль\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальный браслет племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8062, 'Знаки Силы: наручи хищника', 'В темные времена, наставшие после падения империи Гурубаши, зандаларские хищники использовали все свое мастерство, чтобы наше племя сумело выжить. И теперь они воплощают в себе самую сущность охоты. Отправляйся в Зул\'Гуруб и докажи, что ты $gдостоин:достойна: занять место среди хищников Зандалара. Принеси мне знаки силы из Зул\'Гуруба. Тогда ты сможешь еще на один шаг приблизиться к тому, чтобы стать $gодним:одной: из немногих хищников нашего племени.', 'Принесите Фальтиру Слепому изначальные наручники племени Хаккари. Требуется дружелюбное отношение племени Зандалар.Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.', 'Да... Мне не нужно зрение, чтобы почуять присутствие Знаков Силы. Даже самый последний тролль в племени благодарен тебе за то, что ты делаешь ради нас. Мы не только считаем тебя своим другом; мы считаем, что ты достоин носить наручи хищника, воплощающие в себе его сущность. Мы гордимся тобой, $N.', 'Ступай в Зул\'Гуруб и охоться на тех, кто владеет Знаками Силы, $N. Пусть они будут твоей добычей.', NULL, NULL, 'Изначальные наручники племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8063, 'Знаки Силы: наручи безумца', 'Безумцы Зандалара чем-то сродни разбойникам, но самое главное – они несут с собой хаос и разрушение. В те жестокие времена, когда наши племена были раздроблены, боевое безумие помогло нам выстоять против врага. Если бы не оно, мы бы не уцелели.$B$BПринеси мне знаки силы из Зул\'Гуруба, и одна из деталей доспехов безумцев станет твоей. Впусти боевое безумие в свою душу!', 'Принесите Фальтиру Слепому изначальные обручья племени Хаккари. Требуется дружелюбное отношение племени Зандалар.Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальные обручья племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8064, 'Знаки Силы: пояс гаруспика', 'Мы в Зандаларе не следуем путями друидов: мы не подстраиваемся под природу, но меняем ее согласно нашим желаниям. Тем не менее и среди нас есть те, кто близок к природе. Наши гаруспики всегда умели слушать и понимать ее. Чтобы понять дух животного, надо знать, что значит быть одним из них. В этом и заключается истинная сила природы.$B$BПринеси мне знаки силы из Зул\'Гуруба, докажи племени, что тебе можно доверять. Если ты сделаешь это, я отдам тебе пояс – из тех, что некогда принадлежали гаруспикам Зандалара.$B$BВ нем сокрыто могучее колдовство!', 'Принесите Майвики из Зулдазара изначальный кушак племени Хаккари. Майвики из Зулдазара находится на острове Йоджамба, в Тернистой долине. Требуется уважение племени Зандалар', 'Спасибо тебе, $N. Сила, сокрытая в этих предметах, сама по себе сокровище, с этим никто не возьмется спорить. Своими деяниями ты заслужила уважение всего племени. Возьми свою награду!', 'Удалось достать Знаки Силы? Как только я получу их, пояс гаруспика станет твоим.', NULL, NULL, 'Изначальный кушак племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8065, 'Знаки Силы: мундир гаруспика', 'Одежда гаруспиков, $N, – это символ их могущества. Например, мундир – это символ связи между гаруспиком и постигаемой им божественной мудростью. В мундир зашивают части тел животных, принесенных в жертву. Это напоминает гаруспику о связи с его дарами.$B$BДокажи племени, чего ты стоишь, и принеси Знаки Силы из Зул\'Гуруба. Сделай это, и мундир гаруспиков, хранящий их силу, станет твоим.', 'Принесите Майвики из Зулдазара изначальную гербовую накидку племени Хаккари.Майвики из Зулдазара находится на острове Йоджамба, в Тернистой долине.', 'Невероятно. Тебе удалось достать знаки силы, $N! То, что ты сделала для Зандалара, войдет в легенды. Племя восхищается твоими подвигами. Вот твой мундир, друид.', 'Тебе удалось достать Знаки Силы? Мундир гаруспика стоит твоих усилий.', NULL, NULL, 'Изначальная гербовая накидка Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8066, 'Знаки Силы: пояс хищника', 'Любой хищник знает, как подкрадываться к добыче, но самый ловкий умеет выбирать лучший момент для удара. Ты $gдолжен:должна: уметь и подкрадываться, и нападать, чтобы вернуться с добычей из Зул\'Гуруба.$B$BПринеси мне знаки силы. Я обрету могущество, заключенное в них, а ты получишь пояс зандаларского хищника – вещь, ради которой стоит потрудиться.', 'Принесите Фальтиру Слепому изначальную лацерну племени Хаккари. Требуется уважение племени Зандалар.Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.', 'Я загодя почуял твое присутствие, $N, хотя это было не так-то просто. Тебя выдали Знаки Силы. Чтобы почувствовать их, мне совсем не обязательно что-либо видеть. Их заклинания излучают изначальную магию, которая поможет нам побороть дьявольские планы Кровавого бога Хаккара.$B$BТы же прими нашу благодарность и награду. Носи с честью этот пояс хищника и знай, что племя уважает тебя.', 'Безумные приспешники Хаккара в Зул\'Гурубе владеют Знаками Силы, $N. Выследи их, напади и добудь эти Знаки. Докажи племени, что ты можешь считаться хищником Зандалара.', NULL, NULL, 'Изначальная лацерна племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8067, 'Знаки Силы: оплечье хищника', 'В Зандаларе одежда рассказывает о подвигах того, кто ее носит. При этом символы наших свершений не обязательно должны быть видимы глазом – излучаемая ими сила говорит сама за себя. Одежда хищников Зандалара обладает именно такими свойствами; более же всего они ценят свои оплечья. Они скрывают своего владельца от чужих взглядов, когда он желает остаться невидимым.$B$BВ Зул\'Гурубе тебя ждут знаки силы. Принеси их мне, и это оплечье станет твоим.', 'Принесите Фальтиру Слепому изначальную эгиду племени Хаккари. Требуется почтение племени Зандалар.Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальная эгида племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8068, 'Знаки Силы: оплечье мастера иллюзий', 'Магия – это бесформенная изначальная сила. Могучие маги управляют ее энергией в своих целях. Мы прибегаем к ней в своих заклятиях, но, чтобы создавать иллюзии, нужно особое могущество. Как можно победить врага, который существует только в твоем воображении? В Зандаларе знают цену подобной магии, и мастера иллюзий пользуются большим уважением в племени.$B$BПринеси из Зул\'Гуруба знаки силы, и ты заслужишь уважение племени, а также оплечье мастера иллюзий.', 'Принесите Аль\'табиму Всевидящему изначальную лацерну племени Хаккари. Требуется уважение племени Зандалар.Аль\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.', 'Отныне уважение племени тебе обеспечено! Благодаря тебе, $N, Зул\'Гуруб испытал на себе мощь Зандалара.$B$BПрими благословение племени и оплечье мастера иллюзий. Пусть оно служит тебе верой и правдой.', 'Как прошел твой набег на Зул\'Гуруб? Ты довел врагов до безумия, используя мастерство иллюзий? Впрочем, от чего бы они ни умерли, добытые Знаки Силы помогут нам предотвратить воцарение Хаккара.', NULL, NULL, 'Изначальная лацерна племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8069, 'Знаки Силы: одеяние мастера иллюзий', 'В нашем племени одежда – это символ могущества и власти. Она сшита из лучших материалов и усилена заклинаниями, которые дают нам мощь. Одежды мастеров иллюзий отражают самую сущность творимых ими заклятий. Легенды гласят, что одежды мастера иллюзий постоянно меняет свой вид.$B$BЯ могу дать тебе такое одежды, $N... но сначала покажи племени, на что ты $gспособен:способна:. Принеси мне из Зул\'Гуруба Знаки Силы!', 'Принесите Аль\'табиму Всевидящему изначальную рубашку племени Хаккари. Требуется почтение племени Зандалар.Аль\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.', 'Наконец-то нашелся $R, достойный носить одеяние мастера иллюзий! Твои деяния в Зул\'Гурубе снискали тебе славу в Зандаларе на вечные времена. Носи одеяние с честью, $N!', 'Удалось ли тебе достать Знаки Силы? Я знаю, это сделать непросто... Но у меня было видение, что именно чужеземец возглавит нас и поведет на борьбу с Хаккаром. Может быть, это именно ты?', NULL, NULL, 'Изначальная рубашка племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8070, 'Знаки Силы: пояс исповедника', 'После падения имеперии Гурубаши ужасное зло, разъедавшее племя изнутри, охватило и Зандалар. Нас спасли исповедники, которые защищали нас от нас же самих, не давая истреблять себе подобных. До сих пор исповедники охраняют наш дух и стоят на страже наших жизней.$B$BСтупай в Зул\'Гуруб и узри глубину падения Хаккара и Гурубаши. Вырви из их грязных лап знаки силы. В случае успеха тебя ожидает награда.', 'Принесите Аль\'табиму Всевидящему изначальный кушак племени Хаккари. Требуется уважение племени Зандалар.Аль\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальный кушак племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8071, 'Знаки Силы: оплечье исповедника', 'Исповедники Зандалара носят особые оплечья, по которым каждый из нас узнает пастырей племени. Эти оплечья усилены могучими заклятиями, которые помогают почувствовать угрозу, исходящую от врагов племени. Тебе, как $gжрецу:жрице:, они очень бы пригодились.$B$BЕсли ты отправишься в Зул\'Гуруб, сразишься с приспешниками Хаккара и принесешь мне нужные знаки силы, я отдам тебе оплечье, достойное лучших исповедников.', 'Принесите Аль\'табиму Всевидящему изначальную эгиду племени Хаккари. Требуется почтение племени Зандалар.Аль\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальная эгида племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8072, 'Знаки Силы: оплечье безумца', 'Одним из легендарных безумцев Зандалара был Кар\'вахал Безумный. Легенды гласят, что в боях с врагами племени он применял заклинание \"волна безумия\", наложенное на его оплечья. Врагов поражал ужас, и они видели только мелькание его двойных кинжалов. До сих пор оплечья безумцев – предмет их особой гордости.$B$BПринеси мне знаки силы из Зул\'Гуруба, и они достанутся тебе, чтобы вселять безумие и трепет в твоих врагов.', 'Принесите Фальтиру Слепому изначальный ремень племени Хаккари. Требуется уважение племени Зандалар.Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.', 'Сегодня мы можем праздновать победу благодаря тебе и тому безумию, которое ты вселил в сердца наших врагов. Племя Зандалара будет чтить тебя! Нет лучшего способа выразить нашу благодарность, чем отдать тебе эти оплечья безумцев Зандалара.', 'О, ты вернулся – с тобой ли Знаки Силы? Легенды о Карвахале Безумном говорят нам, что, как бы ни был силен враг, его можно одолеть. Хаос способен поставить на колени любого, и это одна из немногих закономерностей, присущих ему.', NULL, NULL, 'Изначальный ремень племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8073, 'Знаки Силы: мундир безумца', 'Мои глаза уже давно ничего не видят, но я от этого не страдаю. В нашем племени одежда – символ твоего статуса и могущества, поэтому самые могущественные предметы излучают невидимую глазами силу. Этот мундир зандаларского безумца – не исключение, он пронизан изначальной магией хаоса и безумия, присущих его владельцу.$B$BМне нужны знаки силы, которые находятся в Зул\'Гурубе. Принеси мне их, и я отдам тебе этот легендарный мундир, который... придется под стать любому сеятелю безумия.', 'Принесите Фальтиру Слепому изначальную эгиду племени Хаккари. Требуется почтение племени Зандалар.Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальная эгида племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8074, 'Знаки Силы: пояс авгура', 'Авгуры многое знают о стихиях, дружище, и используют свои знания во славу нашего племени. В темные времена, наступившие после падения империи Гурубаши, именно авгуры привели нас в тихую гавань Южных морей. Они же вернули нас обратно в долину, в самое сердце зла, свившее себе гнездо в Зул\'Гурубе.$B$BПринеси знаки силы из Зул\'Гуруба и докажи племени, чего ты стоишь. Взамен я дам тебе пояс, который служил нашим авгурам. Это не простой пояс, на нем лежит могучее заклинание.', 'Принесите Майвики из Зулдазара изначальный ремень племени Хаккари. Требуется уважение племени Зандалар.Майвики из Зулдазара находится на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальный ремень племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8075, 'Знаки Силы: хауберк авгура', 'Все авгуры Зандалара носят хауберки. Они сшиты из лучшего шелка и укреплены прочными кольчужными звеньями. Хауберк – не только символ причастности авгуров к божественному, но и знак их власти. Никто не смеет переходить дорогу тем, кто общается с духами.$B$BДокажи свою преданность племени и принеси мне знаки силы из Зул\'Гуруба. Если тебе удастся сделать это, я отдам тебе лучший из хауберков, который когда-либо носили наши авгуры!', 'Принесите Майвики из Зулдазара изначальную гербовую накидку племени Хаккари. Требуется почтение племени Зандалар.Майвики из Зулдазара находится на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальная гербовая накидка Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8076, 'Знаки Силы: оплечье бесноватого', 'Бесноватые стремятся полностью слиться с силой, а не просто использовать ее. Многие из бесноватых проиграли бой со своим демоном. Но когда враги наступали со всех сторон – особенно в Зул\'Гурубе, – победа стоила всех принесенных жертв. От того, сумеем ли мы сокрушить наших врагов, зависит наше существование, – этому нас научило падение империи Гурубаши.$B$BСтупай в Зул\'Гуруб и добудь необходимые нам знаки силы. Наградой тебе будет оплечье бесноватого.', 'Принесите Аль\'табиму Всевидящему изначальный кушак племени Хаккари. Требуется уважение племени Зандалар.Аль\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.', 'Молодец, $N. Знаки Силы из Зул\'Гуруба служат нам напоминанием о могуществе, которое было растрачено впустую. Империя Гурубаши была сильна, но пожрала сама себя изнутри. Игра, в которую играют бесноватые, очень похожа на то, что случилось с империей... Но добытая ими сила необходима для выживания племени.$B$BПрими это оплечье, наш славный союзник... оно сослужит тебе добрую службу.', 'Удалось добыть Знаки Силы в Зул\'Гурубе? Чтобы победить Хаккара, нам нужна колдовская мощь, заключенная в них. Помоги нам, и ты не останешься без награды.', NULL, NULL, 'Изначальный кушак племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8077, 'Знаки Силы: одеяние бесноватого', 'Одеяния, в которые мы облачаемся перед битвой, говорят о нашей силе. Одеяние бесноватого создано из рунической ткани, на которую наложено могучее заклятие. Один его вид вселяет страх в сердца врагов... Особенно его боятся демоны, зная, что рано или поздно бесноватый их одолеет и подчинит своей воле.$B$BПринеси мне знаки силы из Зул\'Гуруба. Это непросто сделать... но в случае успеха одеяние бесноватого станет твоим.', 'Принесите Аль\'табиму Всевидящему изначальную рубашку племени Хаккари. Требуется почтение племени Зандалар.Аль\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.', '', NULL, NULL, NULL, 'Изначальная рубашка племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8078, 'Знаки Силы: пояс воздаятеля', 'Зул\'Гуруб жаждет мести, но Хаккар не должен воцариться! Он подточил империю Гурубаши и разрушил ее, и этому преступлению не может быть оправдания. Из-за Хаккара тролли теперь – лишь тень былой славы.$B$BСтань нашим воздаятелем, уничтожь служителей зла. Зул\'Гуруб должен отведать мести Зандалара. Как доказательство совершенной мести, принеси мне знаки силы. Взамен ты получишь пояс воздаятеля. С ним ты обретешь настоящую мощь.$B$BСтупай.', 'Принесите Джин\'року Разрушителю изначальный ремень племени Хаккари. Требуется уважение племени Зандалар.Джин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.', 'Теперь ты знаешь путь, которым надлежит следовать блюстителю. Твои деяния принесли племени славу, а нашим врагам – смерть.$B$BПрими этот пояс блюстителя, и вместе с ним – нашу благодарность.', 'Ты принес Знаки Силы? Тебе удалось уничтожить врагов племени? Пусть Хаккар познает ярость наших блюстителей!', NULL, NULL, 'Изначальный ремень племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8079, 'Знаки Силы: кираса воздаятеля', 'Символ мощи воздаятеля – его кираса. Ее выковывают, используя могучие заклятия. Подобный доспех носят только те, кто заслужил почет и уважение племени. Кираса воздаятеля – символ возмездия Зандалара.$B$BСтать воздаятелем – значит нести возмездие. Добудь в Зул\'Гурубе знаки силы и принеси их нам. Мы должны вернуть заклинания, которые были у нас украдены. Пусть приспешники Хаккара заплатят за свои преступления кровью! Твоей наградой будет кираса воздаятеля.$B$BСтупай. Отомсти за нас.', 'Принесите Джин\'року Разрушителю изначальную рубашку племени Хаккари. Требуется почтение племени Зандалар.Джин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.', 'То, что ты совершил, внушает трепет. Племя не забывает своих героев, ведь благодаря тебе Зул\'Гуруб испытал всю силу отмщения Зандалара!$B$BТвои деяния станут примером для остальных, и они будут чтить тебя как само воплощение мести.', 'Ты вернулся с победой? Знаки Силы с тобой? Расскажи мне о совершенной мести!', NULL, NULL, 'Изначальная рубашка племени Хаккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8080, 'Ресурсы Низины Арати', 'Войну выигрывают солдаты, любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна, еще не начавшись!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо, и все можно добыть там.$B$BИ вот чего я хочу от вас, $N. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.', 'Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Маклир в Опорный пункт.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8101, 'Камешек Каджаро', '', '', 'Знаешь ли ты, что это, $R? Это – камешек с горы Каджаро в Южных морях. Там, где находится эта гора, постоянно происходят извержения вулканов, сама земля течет и меняется.Сила камня будет расти по мере того, как будет крепнуть твоя связь с троллями Зандалара. Используй его силу, чтобы стереть наших врагов с лица земли. В битве будь подобен вулкану: пусть никто не спасется от смертоносной мощи твоего гнева...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8102, 'Камешек Каджаро', '', '', 'Будь как огненная лава Каджаро, которую ничто не может остановить.', NULL, NULL, NULL, 'Камешек Каджаро', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8103, 'Камешек Каджаро', '', '', 'Продолжай истреблять троллей Зул\'Гуруба. Пусть Хаккар знает, что мир не склонится перед его жестокостью.', NULL, NULL, NULL, 'Камешек Каджаро', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8104, 'Самоцвет Каджаро', '', 'Дай мне свой талисман, $N. Я покажу тебе кое-что.', '<Аль\'табим раскалывает камень при помощи могучей, но незримой силы.>$B$BВидишь? В этом камне находятся могучие кристаллы, пропитанные невидимой энергией нашего мира. Расколов его, я позволил энергии выплеснуться. Используй его, чтобы сокрушить наших врагов.', NULL, NULL, NULL, 'Камешек Каджаро', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8105, 'Битва за Низину Арати', '$N, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов. Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки.$B$BСовершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найдите вражеское знамя и сорвите его с флагштока!$B$BКогда сумеете сделать это на четырех указанных базах, возвращайтесь ко мне.', 'Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.', '', NULL, NULL, NULL, 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на ферму совершено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8106, 'Ожерелье Кезанского порока', '', '', 'Прими этот талисман, $C. Используй его силу, чтобы уничтожить наших общих врагов.Знай, что он – частичка нашей истории. В свое время Кезан был частью огромной Зандаларской империи. К сожалению, гоблины выжили оттуда моих братьев и сестер...Теперь в Кезане находится столица гоблинов Нижняя шахта, а ведь в давние времена он славился своим величием! До сих пор Кезан считается нашей священной землей.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8107, 'Ожерелье Кезанского порока', '', '', 'Слейся с тьмой, $C. Проникни в мир теней. Позволь Кезанскому пороку напитать темные стороны твоего \"я\".', NULL, NULL, NULL, 'Ожерелье Кезанского порока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8108, 'Ожерелье Кезанского порока', '', '', '', NULL, NULL, NULL, 'Ожерелье Кезанского порока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8109, 'Ожерелье вечного Кезанского порока', '', '', 'Убей их и освежуй трупы. Пусть тени поглотят приспешников Хаккара! Страх твоих врагов придаст тебе силы, а ожерелье Кезанской порчи стократно умножит ее.', NULL, NULL, NULL, 'Ожерелье Кезанского порока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8110, 'Зачарованные водоросли Южных морей', '', '', 'Видишь эти водоросли, золотце? Они из Южных морей. Мы всего лишь добавили немного заклинаний и немного магии, чтобы они лучше служили своему владельцу.Ты ведь $С, так что для тебя это будет совсем просто. Оберни их вокруг шеи и подумай о птичках, белочках – в общем, о чем-нибудь для тебя приятном.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8111, 'Зачарованные водоросли Южных морей', '', '', 'Смотри, не скури его нечаянно! Ожерелье поможет тебе сражаться со злом.', NULL, NULL, NULL, 'Зачарованные водоросли Южных морей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8112, 'Зачарованные водоросли Южных морей', '', '', 'Тебе удалось показать троллям Зул\'Гуруба, что значит истинная сила!', NULL, NULL, NULL, 'Зачарованные водоросли Южных морей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8113, 'Безупречные зачарованные водоросли Южных морей', '', '', 'Славен твой путь, $N. Продолжай преследовать и безжалостно истреблять приспешников Хаккара.', NULL, NULL, NULL, 'Зачарованные водоросли Южных морей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8114, 'Контроль над четырьмя базами', '$N, ты бесстрашно $gворвался:ворвалась: в самое пекло сражения в Низине Арати и $gзаслужил:заслужила: на этом поле боя великие почести. Ты $gпоказал:показала: нам, чего стоит $C вроде тебя, и $gпоказал:показала нашим врагам: что мы не сдадимся перед их подлостью!$B$BПоскольку ты уже $gдоказал:доказала: нам свою ценность, у меня есть для тебя очень трудное задание. Я хочу, чтобы ты $gзанял и удержал:заняла и удержала: как минимум четыре базы в Низине Арати. Если вам удастся это сделать, мы не только сумеем собрать стратегически важные ресурсы – мы сможем показать Орде наше превосходство!$B$BИдите, $N, и да сопутствует вам удача.', 'Отправляйтесь в низину Арати, захватите и удержите контроль над четырьмя базами одновременно, затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.', 'Отличная работа, $N! Ко мне прибежал взволнованный разведчик и доложил о ваших действиях. Мы в Лиге Аратора остались очень довольны!$B$BВы быстро становитесь настоящим героем среди солдат Лиги, и сегодняшние ваши деяния подтверждают вашу безукоризненную репутацию.', NULL, NULL, NULL, 'Захватите и удержите контроль над четырьмя базами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8115, 'Контроль над пятью базами', '$N, битва за низину Арати - кровавое предприятие. Твоя помощь очень нужна Лиге Аратора и принимается с большой благодарностью.$B$BУ нас есть для тебя еще одно задание.$B$BЛига хочет нанести решительный, сильный удар по оккупирующим низину Арати Осквернителям. Мы хотим выбить их из всех стратегических точек поля боя!$B$BЭто будет нелегко, но если кто и в состоянии это сделать, то это ты.', 'Возьмите под контроль одновременно все 5 баз в низине Арати, а затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.', '', NULL, NULL, NULL, 'Возьмите под контроль одновременно все пять баз', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8116, 'Ожерелье видений Вудресса', '', '', 'У тебя есть много общего со старой Майвики, золотце. Мы оба – шаманы! Правда, Майвики больше занимается мистикой, а ты в основном выполняешь за других грязную работу. Зато мы оба знаем, что могут даровать великие духи.Я дам тебе этот шар, носи его на шее. Загляни в него, и увидишь деревню Вудресс в Южных морях. Пусть это укрепит твой дух!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8117, 'Ожерелье видений Вудресса', '', '', '', NULL, NULL, NULL, 'Ожерелье видений Вудресса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8118, 'Ожерелье видений Вудресса', '', '', '', NULL, NULL, NULL, 'Ожерелье видений Вудресса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8119, 'Незамутненное ожерелье видений Вудресса', '', '', '', NULL, NULL, NULL, 'Ожерелье видений Вудресса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8120, 'Битва за Низину Арати', 'Как вы, конечно, слышали, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей!$B$BОтправляйтесь в Низину Арати и нападите на рудник, лесопилку, кузницу и стойла. Спустите с флагштоков вражеские знамена, заявив о правах Орды на эти территории.$B$BИдите, $N. Доложите мне, когда выполните задание.', 'Захватите рудник, лесопилку, кузницу и стойла и возвращайтесь к повелительнице смерти Двайр в Павший Молот.', 'Разведчик Осквернителей пришел ко мне с рапортом о вашем успехе, $N. Неплохо сработано.$B$BКак вы вскоре поймете, чтобы выиграть битву в Низине Арати, мы должны все время быть начеку и пресекать любые попытки экспансии Альянса. Поступайте так – и тем самым обеспечите нам победу.', NULL, NULL, NULL, 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на стойла совершено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8121, 'Захват четырех баз', '$N, в то время как гремят бои за низину Арати, новости о твоих деяниях достигли моих ушей. Среди нас ты пользуешься большим уважением, и это дает мне уверенность в том, что ты выполнишь миссию, которую я собираюсь на тебя возложить.$B$BПришло время послать весточку Лиге Аратора. Мы должны дать им понять, что их позиции в низине Арати слабы, и потерять их очень легко. Мы должны показать им это, удерживая одновременно четыре стратегических точки в низине.$B$BДобейся успеха в этом, $N, и заслужишь еще большее уважение среди Осквернителей.', 'Удерживайте одновременно четыре базы в низине Арати, а затем возвращайтесь к повелительнице смерти Двайр в Павший Молот.', 'Хорошая работа, $N! Ваши последние деяния в Низине Арати дались вам нелегко, так что сопутствовавший вам успех достоин похвалы. Лига Аратора, должно быть, уже измотана недавними стычками в низине, зализывает свои раны и, будем надеяться, подумывает, стоит ли вести эту войну дальше.', NULL, NULL, NULL, 'Удерживайте одновременно четыре базы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8122, 'Занять пять баз', 'Непросто увидеть, когда мы так уже глубоко увязли в конфликте, но наши разведчики сообщают об ослаблении Лиги Аратора. Мы должны использовать это окно и нанести Лиге жестокий удар! Возвращайся в низину Арати и бросайся в бой против наших врагов. Проклинай их, убивай их и захвати все пять стратегических баз! Пусть их солдаты с воплями бегут с передовой и пусть рассказы о твоей жестокости срываются с их дрожащих губ.$B$BСделай это и одержи великую победу для Осквернителей.', 'Захватите и удерживайте все пять баз в низине Арати, затем возвращайтесь к повелительнице смерти Двайр в Павший Молот.', '', NULL, NULL, NULL, 'Захватите и удерживайте все пять баз', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8123, 'Перекрыть линии поставок Аратора', 'Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.$B$BТы, $N, можешь нам помочь. Отправляйся в низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захвати и удерживай под контролем те базы, которые сможешь, выиграй битву и возвращайся ко мне с ресурсами, которые тебе удастся добыть.', 'Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8141, 'Зандаларский талисман тени', '', '', 'Ты быстро растешь, юный $C. Пришло время принять тебя в Шера Алик. На нашем языке это название означает \"Рука смерти\". Тысячи лет мы были наемными убийцами Зандаларской империи. Слишком долго мы сидели сложа руки и смотрели, как Хаккар набирает силу. Настала пора сразиться с ним, но теперь за нами нет объединенных сил троллей. Только ты и подобные тебе могут помочь нам в борьбе с Кровавым богом и его приспешниками.Носи этот талисман, и пусть он поможет тебе в твоих странствиях.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8142, 'Зандаларский талисман тени', '', '', '', NULL, NULL, NULL, 'Зандаларский талисман тени', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8143, 'Зандаларский талисман тени', '', '', '', NULL, NULL, NULL, 'Зандаларский талисман тени', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8144, 'Зандаларский талисман власти над тенями', '', '', '', NULL, NULL, NULL, 'Зандаларский талисман тени', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8145, 'Нить Водоворота', '', '', 'В Зандаларе профессия охотника весьма уважаема. Наши лучшие охотники уплывают к самому краю Водоворота, чтобы доказать свою отвагу.Там, в сердце моря, они добывают водоросль, известную как \"нить Водоворота\". Из нее плетут талисманы, увеличивающие силу и меткость.Я дам тебе одну нить Водоворота. По мере того как будет расти твоя связь с Зандаларом, я буду вплетать новые нити в твой талисман.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8146, 'Нить Водоворота', '', '', 'Пусть они искупят свои деяния собственной кровью.', NULL, NULL, NULL, 'Ожерелье Водоворота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8147, 'Нить Водоворота', '', '', 'Теперь мне осталось добавить в твой талисман только одну нить, $c.', NULL, NULL, NULL, 'Ожерелье Водоворота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8148, 'Ярость Водоворота', '', '', 'Твой путь только начинается, юная $c. Возможно, когда-нибудь ты окажешься рядом с Водоворотом и сумеешь заглянуть в самое сердце мира.$B$BДа пребудет с тобой сила и пусть дух твой будет тверд!', NULL, NULL, NULL, 'Ожерелье Водоворота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8149, 'Почести герою', 'Во время Недели урожая в Азероте мы возносим хвалу героям, которые готовы жизнь отдать – а порой и отдают – за нас. Альянс славит множество героев, но нет повести печальнее на свете, чем повесть об Утере Светоносном.$B$BПомоги же нам воздать почести Утеру и отнеси эти подношения к его гробнице в Западных Чумных землях. Положи их к подножию его статуи и возвращайся ко мне. Я пробуду тут только до конца праздника, так что не трать времени и отнеси Утеру эти приношения.', 'Пойдите к гробнице Утера в Западных Чумных землях, положите подношения у подножия его статуи и вернутсья к Вагнеру Молотобойцу в Стальгорн до конца Недели урожая.', 'Он был героем из героев, этот Утер. Даже представить не могу, какую боль он испытал, когда Артас – его лучший ученик, которого Утер любил как сына, – предал человечество. И все же он попытался остановить Артаса, за что мы всегда будем его помнить как истинного паладина. Он дрался до конца, думая лишь о тех, кого надеялся спасти.$B$BСпасибо тебе, $N. Ты оказал почести великому герою, помянув его и принеся радость Неделе урожая.', 'Ты побывал у гробницы Утера и оставил там приношения?$B$BДля не столь опытного странника это довольно опасное предприятие. Безопаснее – относительно – идти севернее реки, что течет через Хилсбрад в Чумных землях. Она вытекает из озера, что находится рядом с Холмом Печали. Затем она сворачивает на запад через холмы, огибая гробницу... полную тварей Плети.', NULL, NULL, 'Положите подношение у гробницы Утера', 'Подношение Утера', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8150, 'Почести герою', 'Во время Недели урожая мы воздаем почести героям, которые готовы отдать, – а порой и отдают, – за нас жизнь. В Орде множество храбрецов и героев, но нет более яркого примера мужества и самопожертвования, чем Гром Адский Крик.$B$BПомоги же нам воздать почести Грому. Отнеси эти подношения к его памятнику в каньоне Гибели Демона в Ясеневом лесу. Положи их к ногам статуи и возвращайся ко мне. Я пробуду тут только до конца праздника, так что не теряй времени!', 'Отправляйтесь к памятнику Грому Зычногласому в Каньон Гибели Демона в Ясеневом лесу и положите подношения у подножия памятника. Вернитесь к Явниру Нашаку в Оргриммар до конца Недели урожая.', 'Полное имя Грома – \"Громмаш\", означает \"Сердце великана\". Воистину, ему потребовалось сердце великана, чтобы в одиночку выстоять против Маннорота! Верно сказал вождь, что проклятие орков началось с Грома, и Гром же с ним покончил! И воистину, самопожертвование – и, возможно, искупление – Грома было не напрасным.$B$BСпасибо тебе, $N. Ты почтил память великого героя, порадовав его дух и дух Недели урожая.', 'Ну что, ты уже побывал у памятника Грому?$B$BМесто, где стоит памятник, все еще осквернено присутствием Пылающего Легиона. Если ты недостаточно опытный искатель приключений, смотри в оба, когда окажешься там!', NULL, NULL, 'Положите подношение у памятника Грому', 'Подношения Грому', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8151, 'Талисман охотника', 'Огтинк из Азшары ищет опытных охотников вроде тебя. Огтинк – фурболг-охотник, отрекшийся от своего племени ради помощи Кругу Кенария. Он стремится наставлять собратьев по оружию и учить их соблюдению природного равновесия. Тебе не помешает поговорить с ним.$B$BОгтинг живет на скалах Азшары, на северо-востоке от руин Эльдарата.', 'Поговорите с Огтинком из Азшары.', 'Я более не охочусь, а учу других. Такая судьба.$B$BСоздай с моей помощью талисман охотника, состоящий из частиц убитой дичи. Талисман будет напоминать тебе о прошлых испытаниях и победах. Я оставлю его себе, а тебе дам кое-что другое.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8153, 'Рога и копыта', 'Беговые олени являются обладателями самых мощных рогов из всех известних нам животных. Олень использует рога для обороны, атаки и нередко убийства. Совершенной формы рога являются свидетельством силы духа животного. $B$BДобывший такие рога и сам обретает небывалую силу духа. $B$BПоохоться на мохноногих оленей и принеси мне лучшую пару их рогов.', 'Принесите пару великолепных рогов мохоногого оленя Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.', 'У тебя явно хорошее терпение и зоркий глаз, иначе тебе не удалось бы справиться с задачей. Я доволен.', 'Принес рога?', NULL, NULL, 'Великолепный рог бегового оленя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8154, 'Ресурсы Низины Арати', 'Войну выигрывают солдаты, любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна, еще не начавшись!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо, и все можно добыть там.$B$BИ вот чего я хочу от вас, $N. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.', 'Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Маклир в Опорный пункт.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8155, 'Ресурсы Низины Арати', 'Войну выигрывают солдаты, любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна, еще не начавшись!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо, и все можно добыть там.$B$BИ вот чего я хочу от вас, $N. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.', 'Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Маклир в Опорный пункт.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
