INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8160, 'Перекрыть линии поставок Аратора', 'Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.$B$BТы, $N, можешь нам помочь. Отправляйся в низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захвати и удерживай под контролем те базы, которые сможешь, выиграй битву и возвращайся ко мне с ресурсами, которые тебе удастся добыть.', 'Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
