INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8166, 'Битва за Низину Арати', '$N, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $B$BНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $B$BКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.', 'Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.', '', NULL, NULL, NULL, 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на ферму совершено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8167, 'Битва за Низину Арати', '$N, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов. Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки.$B$BСовершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найдите вражеское знамя и сорвите его с флагштока!$B$BКогда сумеете сделать это на четырех указанных базах, возвращайтесь ко мне.', 'Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.', '', NULL, NULL, NULL, 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на ферму совершено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8168, 'Битва за Низину Арати', '$N, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов. Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки.$B$BСовершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найдите вражеское знамя и сорвите его с флагштока!$B$BКогда сумеете сделать это на четырех указанных базах, возвращайтесь ко мне.', 'Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.', '', NULL, NULL, NULL, 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на ферму совершено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8169, 'Битва за Низину Арати', 'Как вы, конечно, слышали, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей!$B$BОтправляйтесь в Низину Арати и нападите на рудник, лесопилку, кузницу и стойла. Спустите с флагштоков вражеские знамена, заявив о правах Орды на эти территории.$B$BИдите, $N. Доложите мне, когда выполните задание.', 'Захватите рудник, лесопилку, кузницу и стойла и возвращайтесь к повелительнице смерти Двайр в Павший Молот.', '', NULL, NULL, NULL, 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на стойла совершено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8170, 'Битва за Низину Арати', 'Как ты, конечно, $gслышал:слышала:, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей!$B$BОтправляйся в Низину Арати и напади на рудник, лесопилку, кузницу и стойла. Сорви с флагштоков вражеские знамена, заявив о правах Орды на эти территории.$B$BИди, $N. Доложи мне, когда выполнишь задание.', 'Захватите рудник, лесопилку, кузницу и стойла и возвращайтесь к повелительнице смерти Двайр в Павший Молот.', '', NULL, NULL, NULL, 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на стойла совершено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8171, 'Битва за Низину Арати', 'Как вы, конечно, слышали, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей!$B$BОтправляйтесь в Низину Арати и нападите на рудник, лесопилку, кузницу и стойла. Спустите с флагштоков вражеские знамена, заявив о правах Орды на эти территории.$B$BИдите, $N. Доложите мне, когда выполните задание.', 'Захватите рудник, лесопилку, кузницу и стойла и возвращайтесь к повелительнице смерти Двайр в Павший Молот.', '', NULL, NULL, NULL, 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на стойла совершено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8181, 'Сопротивление Йекинье', 'Дурные вести, $N. Если верить табличкам Мошару, то подлинная сущность Хаккара, то есть само божество, может родиться из того самого яйца, в которое тебе удалось его заключить. Йе\'кинья обманул тебя, он хотел привести в мир Хаккара!$B$BСтупай к этому негодяю и потребуй, чтобы он вернул тебе яйцо. Остается молиться, чтобы можно было предотвратить возрождение Хаккара!', 'Поговорите с Йе\'киньей.', 'Значит, ты поговорил с этим старым дворфом Железным Башмаком и отыскал утраченные таблички Мошару? Ох, уж этот проспектор, сующий нос не в свое дело…$B$BНеважно. Мир уже не спасти. Хаккар возродился, и сила его растет с каждым часом... далеко-далеко, в глубинах древнего королевства Зул\'Гуруба! Он вернулся! И теперь затопит мир кровью и ужасом!$B$BСпасибо, $N. Ты помог ускорить возвращение Свежевателя Душ!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8182, 'Длань Растахана', 'Все наши самые жуткие страхи сбываются. В легендах говорилось о Свежевателе Душ, правившим миром древних троллей злом и жестокостью. Сила его была беспредельна. Если его не остановить, он снова воцарится в Азероте!$B$BТролли Зандалара могут остановить наступление тьмы. Они живут на острове Йоджамба, недалеко от побережья Тернистой долины, к западу от руин Зул\'Кунды. Поговори с их вождем, Молтором. будем надеяться, что он знает, как одолеть Хаккара.', 'Поговорите с Молтором из Тернистой долины.', 'Тебя прислал геолог, Железный Башмак? Он мудр, как и его сородичи, и в мудрости своей прислал тебя ко мне. Мы, зандаларские тролли, знаем, как одолеть Свежевателя Душ.$B$BПоговори с другими троллями, живущими на острове, прислушайся к их словам и готовься, $N, ибо твой дальнейший путь пропитан кровью.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8183, 'Сердце Хаккара', 'Сердце Хаккара пылает изнутри. Свежеватель Душ повержен, но ключ к его силе – все еще в его сердце.', 'Принесите сердце Хаккара Молтору на остров Йоджамба.', 'Сердце Хаккара!.. Со Свежевателем Душ покончено! Наш мир спасен!$B$BНевозможно переоценить то, что ты сделал для нас, $N. Ты – живая легенда нашего мира.', '$N, ты окружен темной аурой. Неужели и тебя настигло проклятие Свежевателя Душ?', NULL, NULL, 'Сердце Хаккара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8184, 'Явление Силы', '', '', 'Используй подарок с умом, $C. Не давай спуску приспешникам Хаккара!', NULL, NULL, NULL, 'Изначальный идол племени Хаккари', 'Исколотая кукла вуду', NULL, NULL);
