INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8192, 'Прикосновение анимиста', '', '', 'Используй подарок с умом, $С. Не давай спуску приспешникам Хаккара!', NULL, NULL, NULL, 'Изначальный идол племени Хаккари', 'Исколотая кукла вуду', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8193, 'Лучший рыболов', '', '', 'Скорее сдавай пойманную рыбу, если хочешь заслужить звание лучшего удильщика! Я торчу здесь уже много ЧАСОВ, и даже маковой росинки во рту не было! Давай сюда вкуснорыб!', NULL, NULL, NULL, 'Крапчатая вкуснорыба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8194, 'Начинающий рыболов', '', '', 'По рукам!', NULL, NULL, NULL, 'Крапчатая вкуснорыба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8195, 'Монеты племен Зулиан, Раззаши и Хаккари', '', '', 'Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, $N, прими его вместе с нашей благодарностью!', NULL, NULL, NULL, 'Зулианская монета', 'Монета Раззаши', 'Монета племени Хаккари', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8196, 'Экстракт манго', '', 'Манго, из которых можно изготовить могучий экстракт, растут на островах Южных морей. Одно-единственное манго придает и физические и душевные силы тому, кто его съест. Тебе когда-нибудь приходилось пробовать манго? Если нет, то ты много потерял!У нас есть запасы манго, и мы охотно обменяем плоды на Почетный знак Зандалара. Если ты не знаешь, где достать знаки, поговори с Винчаксой. Приступим к обмену?', 'Хорошая сделка, дружище, наслаждайся ароматом экзотических плодов Южных морей, и да пребудет с тобой благословение племени.', NULL, NULL, NULL, 'Почетный знак Зандалара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8201, 'Коллекция голов', 'Это правда. Хаккар теперь обитает в Зул\'Гурубе, питаясь силой наших богов. Порабощеные им жрецы направляют энергию самых священных божеств Свежевателю Душ, и скоро сильнее его в Азероте не будет существа. Его надо остановить!$B$BВозьми этот священный шнур. Нанижи на него головы верховных жрецов, по вине которых сила наших богов утекает к Хаккару.$B$BСделав это, возвращайся ко мне.', 'Соберите ожерелье из голов пятерых жрецов и вернитесь с ним к Экзалу на остров Йоджамба.', 'Вот это ожерелье! Тебе удалось остановить хищение силы наших богов и ослабить Хаккара!$B$BТы совершил настоящий подвиг, $N. Пусть головы этих презренных троллей продолжают умолять тебя о пощаде – даже после того, как в них остынет кровь.', 'Ты уже открутил жрецам головы, $N? Мы должны остановить Хаккара, пока он не набрался сил!', NULL, NULL, 'Коллекция голов племени Гурубаши', 'Священный шнур', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8221, 'Редкая рыба – рыба-ангел Кифэра', '', '', '*Жжж*$B$BОпознание рыбы-ангела Кифера завершено.$B$BВы можете получить награду.$B$B*Щелк-щелк**Бзззз*', NULL, NULL, NULL, 'Рыба-ангел Кифэра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8222, 'Светящаяся кровь скорпида', '', '', 'Чудесно, чудесно, $N! Спасибо тебе. Наварю краски и превращу вон ту кучу мусора в восхитительные сувениры!$B$BВот твои купоны – удачно отдохнуть!', NULL, NULL, NULL, 'Светящаяся кровь скорпида', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8223, 'Обмен: светящаяся кровь скорпида', '', '', 'Спасибо тебе, $N. А вот и твои купоны!', NULL, NULL, NULL, 'Светящаяся кровь скорпида', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8224, 'Редкая рыба – дезийская ставрида', '', '', '*Жжж*$B$BОпознание дезийской ставриды завершено.$B$BВы можете получить награду.$B$B*Щелк-щелк**Бзззз*', NULL, NULL, NULL, 'Дезийская ставрида', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8225, 'Редкая рыба – синий полосатик Браунелла', '', '', '*Жжж*$B$BОпознание синего полосатика Браунелла завершено.$B$BВы можете получить награду.$B$B*Щелк-щелк**Бзззз*', NULL, NULL, NULL, 'Синий полосатик Браунелла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8227, 'Измерительная лента Ната', 'Среди разбросанных рыболовных инструментов лежит свернутая шелковая измерительная лента. К ней прицеплена бирка с надписью:$B$B\"Нат Пэгл, Пылевые топи\".', 'Верните измерительную ленту Нату Пэглу. Найти Пэгла можно в Пылевых топях.', 'О, тебе удалось отыскать мою измерительную ленту? Она мне очень дорога! Именно ею я измерял самых больших рыб, которых мне удавалось поймать...$B$BНо ведь я потерял свою ленту в Зул\'Гурубе... Ты там был? Может быть, ты видел этого самого Газ\'ранку, о котором рассказывают басни?$B$BЧто ж... может быть, ты хочешь его поймать?', 'Привет, сынок. Хочешь порыбачить?', NULL, NULL, 'Измерительная лента Ната (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8228, 'Приглашение на рыбалку', '', '', 'В это воскресенье в Пиратской бухте будет рыболовецкое состязание! Если хочешь принять участие, вот, почитай правила!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8229, 'Приглашение на рыбалку', '', '', 'В это воскресенье в Пиратской бухте будет рыболовецколе состязание! А вот и правила!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8231, 'Охота на волношлепа', 'Волношлеп – земноводное, встречающееся только в Азшаре. Эти твари сильны и очень живучи. $B$BВ их твердой блестящей чешуе, как в зеркале, отражается мастерство охотника. $B$BВыследи и убей нескольких на побережье Азшары и принеси мне их чешую.', 'Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.', 'Волношлепы – не самые слабые противники, особенно если пытаться биться с ними в воде – их естественной среде обитания. Ты доказал что можешь справиться с очень опасной добычей.', 'Тебе удалось собрать ингредиенты?', NULL, NULL, 'Чешуя волношлепа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8232, 'Зеленый дракон', 'Ты отправляешься на опасную охоту. Убей зеленого дракона Морфаза и принеси мне его зуб. Морфаз обитает в храме Атал\'Хаккар. Вход в него ты найдешь на болоте Печали. $B$BНо помни, $gодному:одной: тебе его не осилить. У дракона много врагов – найди соратников и уничтожь его! $B$BМногие, очень многие не прочь добыть зуб этой твари. Принеси его мне, и я достойно награжу тебя.', 'Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.', 'Ты показал себя великим воителем, $N. Прими этот дар, я храню его с давних лет, когда сам был охотником.', 'Я вижу на твоем челе печать невзгод, $N. Тебе удалось убить дракона?', NULL, NULL, 'Зуб Морфаза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8233, 'Приглашение', 'Лорд Джорах Черный Ворон настоятельно приглашает вас к себе. Приглашение тайное, поэтому никаких подробностей.$B$BПоместье Черный Ворон находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд.', 'Поговорите с лордом Джорахом Черным Вороном в его поместье.', 'Добро пожаловать! Прошу вас, $N, присаживайтесь. Я хочу обсудить с вами одно простое дельце.$B$BВидите ли, недавно я лишился кое-чего очень ценного, и, прямо говоря, хочу вернуть его любой ценой. Это дело и для вас выгодное, да, очень выгодное.$B$BЧто скажете, $N? Вы же любите приключения?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8234, 'Запечатанная лазурная сумка', 'Начнем сначала. Я потерял небольшую сумку голубого цвета. В ней были мои личные вещи. $B$BНет нужды искать воров – они уже мертвы. Мне известно лишь, что эти дураки не сумели открыть сумку и продали ее какому-то шаману из племени Древобрюхов в Азшаре, выдав ее за священную реликвию. Очень умно. $B$BЯ хочу, чтобы ты $gотправился:отправилась: в Азшару и $gзаполучил:заполучила: у шамана мою сумку – хитростью или силой. Полагаю, что лучше все же хитростью. Сумку отнеси верховному магу Ксилему.', 'Добудьте запечатанную лазурную сумку у шамана из племени Древобрюхов в Азшаре. Затем отнесите сумку верховному магу Ксилему в Азшаре.', 'Вижу, у тебя сумка лорда Черного Ворона. Что ж ты сразу не сказал, сынок?', 'Мы знакомы?', NULL, NULL, 'Запечатанная лазурная сумка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8235, 'Зашифрованные фрагменты', 'Лорд Черный Ворон просил нас с тобой об услуге. Он желает снять заклятие с этой сумки. $B$BК сожалению, мои книги по снятию чар были захвачены и уничтожены дикарями. Каждый клочок, оставшийся от них, невероятно ценен для меня. $B$BЕсли ты сможешь принести мне зашифрованные фрагменты, я попробую восстановить хотя бы часть моих книг. Чтобы найти фрагменты, поохоться на обитающих в Азшаре зверей - они обычно подбирают все, что плохо лежит.', 'Принесите 10 зашифрованных фрагментов верховному магу Ксилему в Азшару.', 'Похоже, тебе удалось найти весьма ценные фрагменты. Не так уж ты и бесполезен, в конце концов.', 'Ты принес мне фрагменты? Я должен как можно скорее приступить к работе.', NULL, NULL, 'Зашифрованный фрагмент', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8236, 'Лазурный ключ', 'Мне потребуется время, чтобы расшифровать фрагменты и снять заклятие. Когда я закончу, то самолично доставлю сумку лорду Черному Ворону. $B$BОднако нам все еще нужен ключ. Говорят, что ключ присвоил зеленый дракон по имени Морфаз. Его логово находится в глубинах храма Атал\'Хаккар – вход в него ты найдешь на болоте Печали. $B$BСобери своих сподвижников и отправляйся к логову дракона. Лорд Черный Ворон ждет, когда ты принесешь ему ключ.', 'Принесите лазурный ключ лорду Черному Ворону.', 'Ключ! Я уже думал, что он потерян навеки! Прошу тебя, возьми что-то из зачарованной одежды из моих запасов. Она предназначена для особо искусных разбойников. Пусть все знают, что с тобой шутки плохи! $B$B*Джорах раскрывает сумку, и из нее вырывается золотое сияние. Джорах с изумлением смотрит внутрь...*', 'Верховный маг $N уже прислал мне сумку. Ты принес ключ?', NULL, NULL, 'Лазурный ключ', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8238, 'Монеты племен Гурубаши, Порочной Ветви и Сухокожих', '', '', 'Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, $N, прими его вместе с нашей благодарностью!', NULL, NULL, NULL, 'Монета племени Гурубаши', 'Монета племени Порочной Ветви', 'Монета племени Сухокожих', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8239, 'Монеты племен: Песчаная Буря, Дробители Черепов и Кровавый Скальп', '', '', 'Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, $N, прими его вместе с нашей благодарностью!', NULL, NULL, NULL, 'Монета Песчаной Бури', 'Монета клана Дробителей Черепов', 'Монета Кровавого Скальпа', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8240, 'Драгоценности для Занзы', 'Драгоценности племени Хаккари необходимо уничтожить. Это наше внутреннее дело, но оно настолько важное, что мы просим о помощи и чужеземцев.$B$BОтыщи в Зул\'Гурубе все драгоценности, которые сможешь, принеси на алтарь Занзы и уничтожь их. Если ты справишься с этим заданием, я дам тебе почетный знак нашего племени. Знай, что у нас этими знаками не разбрасываются!$B$BСтупай, и да пребудет с тобой благословение Занзы!', 'Найдите в Зул\'Гурубе драгоценности племени Хаккари и уничтожьте их на алтаре Занзы на острове Йоджамба. Затем поговорите с Винчаксой.', 'Отлично... Каждая драгоценность, которую удалось отнять у прислужников Кровавого бога – еще один шаг к тому, чтобы покончить с ними навечно. Ты оказал племени неоценимую услугу, и племя этого не забудет.$B$BПомни, что найденные драгоценности нужно уничтожить на Алтаре Занзы. За уничтожение каждой драгоценности ты получишь почетный знак племени! Для хранения почетных знаков тебе потребуется свободное место в сумках.', 'Уничтожь драгоценности на Алтаре Занзы! Сделай это, и Занза благословит тебя дважды!', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8241, 'Пополнение запасов огненного плавня - железо', '', '', 'Плавень в кузне лишним не бывает, поверь моему слову... Неси сколько можешь, пока не скажу – хватит.', NULL, NULL, NULL, 'Чешуя пламезавра', 'Железный слиток', 'Уголь', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8242, 'Пополнить запасы огненного плавня с помощью толстой кожи', '', '', 'Плавень в кузне лишним не бывает, поверь моему слову...', NULL, NULL, NULL, 'Чешуя пламезавра', 'Толстая кожа', 'Уголь', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8243, 'Напиток могущества Занзы', '', 'Теперь, когда племя тебе доверяет, ты можешь воспользоваться нашими зельями. Вот, смотри. Этот напиток несет на себе благословение Занзы, и любой искатель приключений будет счастлив обладать им.У меня в запасе три таких напитка, и я дам тебе один из них, но взамен мне нужен почетный знак Зандалара. Запомни: пока ты находишься под действием одного из напитков, ты не сможешь принять другой.Возвращайся, когда у тебя появится то, что нужно для обмена.', 'Все по-честному, приятель! Вот твой напиток – пусть он поможет в твоих странствиях!', NULL, NULL, NULL, 'Почетный знак Зандалара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8246, 'Перстни Зандалара', '', 'Для друзей нашего племени, $N, у меня есть особый подарок прямо из нашего дома в Южных морях... Перстни Зандалара! Они усиливают любые наплечники и влияют на силу нападения или заклинаний.В обмен на каждое кольцо мне нужно 15 почетных знаков Зандалара.', 'Все по-честному, приятель! Вот твой перстень – пусть он поможет в твоих странствиях!', NULL, NULL, NULL, 'Почетный знак Зандалара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8249, 'Принести лари', '', '', 'Да найдется место для этих ножей в чьем-нибудь сердце.$B$BВ буквальном смысле.', NULL, NULL, NULL, 'Тяжелый ларь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8250, 'Магическое искусство', 'Верховный маг Ксилем ищет кого-то... Не менее опытного, чем ты.$B$BЕсли хочешь, поговори с ним. Он живет в Азшаре, в башне на вершине утеса. Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо.$B$BСанат живет в лагере ниже башни своего хозяина. Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрешься в скалы.', 'Найдите Саната Лим-Йо и добейтесь, чтобы он доставил вас к верховному магу Ксилему.', '*Санат смотрит на вас с презрением.*$B$BВерховный маг Ксилем ждет тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8251, 'Волшебная пыль', 'Эльфы крови в Азшаре изобрели свой способ распылять магические предметы. Получаемая в результате сияющая пыль отличается от элементов, получаемых в результате обычного распыления.$B$BЯ отправил ученика купить этой пыли, но эльфы безжалостно убили его. Они должны заплатить за это! $B$BВремя мирных переговоров прошло, $N. Найди эльфов крови в скалах Азшары и примени к ним более... убедительные методы. Мне нужна эта пыль.', 'Принесите 10 горстей сияющей пыли верховному магу Ксилему.', '', NULL, NULL, NULL, 'Сияющая пыль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8252, 'Кораллы сирен', 'Оглянись вокруг. Развалины и все побережье кишат тварями Бича Злобы. Проклятые создания научились искать редкие вещества и предметы, встречающиеся в Азшаре. $B$BНапример, эти твари почему-то очень интересуются заколдованными кораллами – по совершенно не ясным мне причинам. Теперь этих кораллов в бухте почти не осталось, а они так нужны мне для исследований! Прошу тебя, отбери несколько кораллов у сирен из клана Бича Злобы и принеси их мне.', 'Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему.', '', NULL, NULL, NULL, 'Заколдованный коралл', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8253, 'Уничтожить Морфаза', 'В глубинах храма Атал\'Хаккар скрывается зеленой дракон по имени Морфаз. $B$BМного лет назад он напал на меня из засады и проглотил целиком сопровождавшего меня ученика. Мне не впервой терять ученика, однако имено этот, проглоченный, нес кристалл тайной магии небывалой мощи. $B$BВыбери достаточно сильных соратников и отправляйся в храм. Уничтожь Морфаза и принеси мне мой кристалл.', 'Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.', 'Невероятно! Кристалл увеличился, как будто все эти годы впитывал магию дракона. $B$BБольше мне не о чем тебя просить. С этим кристаллом я вновь могу творить тайные чары. Первое мое творение будет принадлежать тебе, $N. Выбирай...', 'Ты убил моего старого врага?', NULL, NULL, 'Кристалл тайной магии', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8254, 'Помощь Кенарию', 'Служителям богов пристало помогать попавшим в беду. Как именно – неважно, главное – во имя чего.$B$BКругу Кенария необходима помощь. Если ты хочешь протянуть им руку помощи, поговори с Огтинком. Он живет на вершинах скал на северо-востоке от руин Эльдарата в Азшаре.', 'Отыщи Огтинка в Азшаре.', 'Я очень рад твоему приходу. У меня словно камень с души свалился. Нам предстоит очень много дел.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8255, 'Охота на беговых оленей', 'Мохноногие олени, обитающие в Азшаре, – самые великолепные создания, когда-либо населявшие Оскверненный лес. Они наделены естественной невосприимчивостью ко всем болезням и ядам, поэтому порча не коснулась их. Мудрые животные предпочли покинуть зараженные земли. $B$BК прискорбию своему я должен просить тебя поохотиться на этих прекрасных созданий, поскольку их железы необходимы для изготовления целительного снадобья. Снадобья, которое вернет Оскверненному лесу его прежний облик.', 'Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.', 'Сама судьба привела тебя сюда, $N. Вера твоя не противоречит тому, что должно исполнить для создания снадобья. $B$BВидишь ли, Круг Кенария считает этих беговых оленей священными животными, убийство которых невозможно ни при каких обстоятельствах. Если бы им пришлось это сделать, это сильно подорвало бы их дух.', 'Ты вернулась. Надеюсь, удача улыбнулась тебе?', NULL, NULL, 'Железа здорового бегового оленя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8256, 'Лимфа нежити', 'Чтобы получить целительное снадобье, воспользуемся простым рецептом: смешаем одну часть яда с двумя благотворными субстанциями. Один целительный компонент у нас уже есть, теперь надо добыть яд. $B$BСамые могущественные твари нежити, такие как неупокоенные высокорожденные, скитающиеся по руинам Эльдарата, часто настолько сильно поражены порчей, что она принимает вполне осязаемую форму зеленой слизи. Среди живых эта субстанция известна как лимфа нежити. $B$BЭто очень мощный яд, поэтому потребуется лишь одна мера.', 'Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.', 'Да, не самое приятное зрелище... Но, как это не печально, эта мерзкая субстанция необходима для создания целебной мази. Спасибо, $N.', 'Нам нужна лимфа как можно скорее! Тебе удалось добыть ее?', NULL, NULL, 'Лимфа нежити', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8257, 'Кровь Морфаза', 'Теперь нам нужен последний целительный компонент. $B$BИзвестно, что зеленый дракон Морфаз наделен невосприимчивостью ко всем болезням и ядам. Это знание досталось дорогой ценой – не один друид погиб, пытаясь справиться с драконом. Уверен, его кровь послужит отличным компонентом для нашего снадобья.$B$BПосланник Круга Кенария заберет уже собранные тобой компоненты, пока ты будешь добывать последний. Собери соратников и отправляйся в логово зеленого дракона в затонувший храм Атал\'Хаккар. Принеси его кровь Грете Замшелое Копыто в Оскверненный лес.', 'Убейте Морфаза в затонувшем храме Атал\'Хаккар и принесите его кровь Грете Замшелое Копыто в Оскверненный лес. Вход в храм сокрыт на болоте Печали.', 'Не могу поверить... тебе действительно удалось справиться с драконом и добыть его кровь! Мы немедленно приготовим снадобье и начнем исцеление растений и животных Оскверненного леса. Это займет очень много времени, но теперь мы можем это сделать – и все благодаря тебе!', 'Ты добыл кровь Морфаза?', NULL, NULL, 'Кровь Морфаза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8258, 'Угроза Темного Губителя', 'Темный Терзатель, рыцарь смерти, владычествует над Великим оссуарием в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.$B$BПриведи его в действие в Великом оссуарии, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, $N! Только его гибель способна исправить урон, нанесенный миру духов!', 'Используйте кристальный предсказатель в Великом оссуарии в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.Принесите голову Темного Терзателя Сагорну Гривастому Страннику на аллею Мудрости Оргриммара.', '', NULL, NULL, NULL, 'Голова Темного Терзателя', 'Гадальный кристалл', NULL, NULL);
