INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8262, 'Улучшенный полевой комплект Лиги Аратора', '', '', 'Ты хорошо зарекомендовал себя, $N, тут сомнений нет! В награду возьми этот пакет! В нем паек и бинты, которые найдешь только в лощине Боевого Клича.Когда в лощине тебя еще больше зауважают, тебе их тут даже продадут. Паек мы выдаем, если относимся к кому-то дружественно, а бинты – когда уважаем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
