INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8271, 'Герой клана Грозовой Вершины', '', '', 'Как великий воитель Грозовой Вершины, можешь выбрать одну вещь из награб... из этих спасенных сокровищ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8272, 'Герой клана Северного Волка', '', '', 'Как ощущения, $N? Приятно видеть поверженных врагов в пыли у своих ног? Отличное чувство, правда?Прими награду за свои героические деяния, солдат.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8273, 'Благодарность Оран', '', '', 'Надо же, как интересно. Говоришь, ты нашел эту табличку на Отвесных скалах во Внутренних землях? Очень, очень любопытно. *Оран потирает руки и прячет табличку подальше.*Благодарю за труды. Темная Госпожа будет довольна этим открытием. Позволь тебя наградить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8275, 'Отвоевание Силитуса', 'Слушайте, герои Альянса! Мы слишком долго не обращали внимания на опасность, источник которой – силитиды. Им никто не противостоял, и мерзкие насекомые подготовились к масштабному вторжению.$B$BСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!$B$BВсе на защиту Азерота! Все, способные держать оружие, должны пройти инструктаж у призывательницы ветров Гордый Рог в крепости Кенария!', 'Поговорите с призывательницей ветров Гордый Рог в крепости Кенария.', 'Отлично, еще один доброволец готов выступить против силитидов. Добро пожаловать в крепость Кенария, $С. Я рад, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8276, 'Отвоевание Силитуса', 'Слушайте, герои Орды! Мы слишком долго не обращали внимания на серьезную угрозу. Дрожание земли рядом с ульями силитидов говорит о серьезном возрастании их числа в связи с готовящимся нападением.$B$BСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!$B$BВсе, способные держать оружие, должны обратиться к призывательнице ветров Гордый Рог в крепости Кенария! Смерть силитидам!', 'Поговорите с призывательницей ветров Гордый Рог в крепости Кенария.', 'Отлично, еще один доброволец готов выступить против силитидов. Добро пожаловать в крепость Кенария, $C. Я рад, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8277, 'Смертельный яд', 'Битисса Шаткобрус к твоим услугам! Мой кузен Ноггл зарабатывает на жизнь, продавая алхимикам из крепости Кенария редкие травы. Точее, зарабатывал. Из последней вылазки он вернулся отравленный страшным ядом.$B$BЯ сумела замедлить действие яда, но чтобы полностью нейтрализовать его, мне понадобятся образцы яда тех тварей, что ужалили его.$B$BНоггл вернулся с севера, поэтому я готова поспорить, что он пострадал от камнехвостых скорпидов или песчаных пауков-быстроногов. Принеси мне несколько жал и жвал, и я сделаю противоядие.', 'Принесите Битиссе Шаткобрус из крепости Кенария 8 жал камнехвостых скорпидов и 8 жвал песчаных пауков-быстроногов.', 'Скрести пальцы, дружище! Будем надеяться, что нам удастся спасти Ноггла!', 'Ты уже собрал для меня образцы? Мы теряем Ноггла!', NULL, NULL, 'Жало камнехвостого скорпида', 'Клык песчаного паука-быстронога', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8278, 'Последняя надежда Ноггла', 'Проклятье! Противоядие не сработало. Наверное, Ноггла укусила одна из тварей на далеком юге, они гораздо страшнее остальных.$B$BПридется попросить тебя отправиться за образцами, $N. В утешение могу сказать, что поскольку яд у них сильный, мне потребуется не так много образцов, как в прошлый раз. С другой стороны, на юге больше ядовитых тварей, поэтому придется убить по несколько существ разных видов.', 'Принесите Битиссе Шаткобрус из крепости Кенария 3 жала камнехвостых клешневиков, 3 жала камнехвостых живодеров и 3 клыка скальных пауков-скакунов.', 'Да! Похоже, сработало, Ноггл приходит в себя. Мы у тебя в долгу!', 'Это последний шанс спасти Ноггла! Спеши!', NULL, NULL, 'Жало камнехвостового живодера', 'Жало камнехвостого клешневика', 'Клык скального паука-скакуна', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8279, 'Сумеречный словарь', 'Сумеречный Молот не прощает тех, кто покидает его ряды. Они охотятся за мной, словно за диким зверем! Излишне говорить, что их враги – мои друзья!$B$BЧтобы расшифровать эту табличку, мне понадобится книга, которой пользуются их писцы при закодировании тайных посланий, Сумеречный словарь. Эта книга настолько важна, что три ее главы держат в разных местах! Главы находятся у особых офицеров, именуемых сумеречными хранителями. Ищи их в лагерях Сумеречного Молота.', 'Принесите три главы Сумеречного словаря отшельнику Ортеллу из Силитуса.', 'Ура! Вот они, все части книги! Приступим, $N.$B$BЗаменить каждое третье слово словами из второй главы... Потом заменить каждое второе слово словами из первой главы... Стоп, я что-то путаю?', 'Кто идет? А, это ты! Ты уже все главы словаря собрал?', NULL, NULL, 'Сумеречный словарь - Глава 1', 'Сумеречный словарь - Глава 2', 'Сумеречный словарь - Глава 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8280, 'Надежные поставки', 'Крепость Кенария имеет важнейшее стратегическое значение. Не сомневаюсь, что пока мы удерживаем его, силитидам нас не одолеть. Разумеется, если припасы будут поступать регулярно.$B$BПесчаные черви оказались даже большей помехой для наших караванов, чем сами силитиды. Например, сегодня утром землечерпы разграбили большой караван с рассветницей. Необходимо сократить число этих тварей, чтобы обеспечить бесперебойные поставки.', 'Убейте 15 землечерпов по поручению призывательницы ветров Гордый Рог.', 'Прими мою глубочайшую благодарность. Помогая крепости Кенария, ты проявил редкое мужество.', NULL, NULL, NULL, 'Землечерп убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8281, 'Обеспечение безопасности', 'Ты великолепно себя $gзарекомендовал:зарекомендовала:, $N. К сожалению, нашему снабжению по-прежнему грозит опасность. Землечерпов теперь нет, но их место несомненно займут их более крупные южные родственники – земляные сокрушители.$B$BЧтобы приструнить этих червяков, придется убить их побольше. Но мы не можем подвергать опасности наше снабжение.', 'Убейте 20 земляных сокрушителей по поручению призывательницы ветров Гордый Рог.', 'Великолепно! Ты оказался ценным союзником в подготовке к войне против силитидов.', NULL, NULL, NULL, 'Земляной сокрушитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8282, 'Потерянная сумка Ноггла', 'Где я? Где моя сумка? $gвздыхает: Наверное, я потерял ее, убегая от Смертехвата, огромного скорпида. Я мчался, не разбирая дороги, и забрел прямо в гнездо камнехвостых живодеров.$B$BВ моей сумке были ценнейшие реагенты. Без них мы с Битикс не сможем делать зелья для крепости Кенария. Я пока не в силах встать, но если ты сможешь вернуть мне реагенты, я тебе отплачу сторицей.$B$BНа Смертехвата я наткнулся в южных горах, за лагерем Бронзоборода.', 'Принесите сумку Ноггля из гор в южной части Силитуса и верните ее хозяину в крепость Кенария.', 'Да! Ты принес мне сумку. И все ценные реагенты вместе с ней! Я твой должник на долгие годы.', 'Ты еще не нашел мою сумку? С другой стороны, грех жаловаться, от яда-то меня излечили.', NULL, NULL, 'Сумка Ноггла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8283, 'РОЗЫСК: Смертехват, гроза пустыни', 'Согласно последним сведениям, ужасный скорпион, Смертехват, отступил в южные горы перед лицом нашествия силитидов. Эта тварь представляет большую угрозу патрулям и экспедициям южных регионов. Тех, кто поспособствует ее уничтожению, будет ждать неплохая награда. По вопросам получения награды обращаться к капитану Вишу Коцусу, на вершину сторожевой башни крепости Кенария.', 'Принесите хелицеры Смертехвата Вишу Коцусу, капитану стражи.', 'Замечательно! Смертехвата нет, и мы сможем спокойно подобраться к ульям силитидов по южным горам. Мы высоко ценим твою работу.', 'Доказательством гибели твари послужат ее хелицеры. Нет хелицер, нет и награды.', NULL, NULL, 'Хелицеры смертехвата', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8284, 'Сумеречная тайна', 'На северо-западе отсюда некогда благоденствовал лагерь служителей культа Сумеречного Молота. Теперь на месте лагеря остались лишь обломки древесины и ткани, среди которых бродят элементали.$B$BМне удалось добыть там несколько кусочков глиняной таблички, но их слишком мало, чтобы узнать что-нибудь ценное. Не сможешь ли ты добыть остальные фрагменты? Быть может, они прольют свет на деятельность Сумеречного Молота в Силитусе.', 'Геолог Ехидная из крепости Кенария просит вас собрать 8 фрагментов сумеречной таблички.', 'Так я и думала. Я могу перевести отдельные слова, но они лишены смысла. Сумеречный Молот часто пользуется особыми шифрами, чтобы скрыть значение своих текстов от чужих; нужно найти кого-ниудь, кто разбирается в таких вещах.', 'Разграбленный лагерь находится на северо-западе. Возвращайся, когда соберешь все фрагменты.', NULL, NULL, 'Фрагмент сумеречной таблички', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8285, 'Дезертир', 'Ходят слухи, что некто по имени Ортелл вышел из рядов Сумеречного Молота. Говорят, он прячется в горах на юге от деревни Южного Ветра и живет в полном уединении. Может быть, имеет смысл прибегнуть к его помощи в расшифровании таблички.$B$BВозьми восстановленную табличку и отнеси ее Ортеллу.', 'Отнесите восстановленную табличку отшельнику Ортеллу в Силитус.', 'Вижу, ты не понаслышке знаешь о моей бывшей организации. Должно быть, ты из крепости Кенария.$B$BТебе нужна информация для борьбы с Сумеречным Молотом? Подойди ближе, может быть, мы сможем помочь друг другу.', 'Ты! Как ты меня нашел? Кто ты? За тобой не следят? Говори!', NULL, NULL, 'Восстановленная Сумеречная табличка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8286, 'Что ждет нас завтра', 'Я уже почти очутился в объятьях смерти, и тут вмешался он. Лишь раз дохнул он на мое искалеченное тело, а затем оставалось лишь дождаться, пока пески времени исцелят мои раны.$B$B\"Навеки останешься ты, коли так нужно,\" – сказал он, и с этими словами сделал меня Стражем.$B$BТолько взгляни на пустыню. Вторая война неминуема. Найди тайное укрытие бронзовых драконов. Отправляйся в Пещеры Времени и узнай, не вернулся ли повелитель. Я должен знать наверняка, иначе не смогу действовать.', 'Отправляйтесь в Пещеры Времени в Танарисе и найдите Анахроноса, из рода Ноздорму.', 'Так и предначертано – восстал великий. Мое бдение подходит к концу...', 'Анахронос вернулся?', NULL, NULL, 'Исследовать локацию', 'Найдите драконов из рода Ноздорму.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8287, 'Ужасная цель', 'Ну вот... Ценная информация, скажу я тебе! Я видел, как силы Круга Кенария прибыли в Силитус. Они планируют выбить из наших краев Сумеречный Молот, верно? Это поспособствует воплощению их планов.$B$BОтнеси этот пергамент их главе, командору Мар\'алиту. Скоро Сумеречный Молот будет изгнан из этих земель и его жадные ручки до меня не дотянутся!', 'Отнесите переписанный с таблички расшифрованный текст командору Мар\'алиту.', 'Очень интересные сведения, $N. Они проливают свет на деятельность Сумеречного Молота в Силитусе и несомненно помогут бороться с этой сектой. Вот тебе награда за труды, $С.', 'Что ты мне принес, $N?', NULL, NULL, 'Переписанный с таблички расшифрованный текст (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8288, 'Кто будет избран?', 'Время у нас на исходе! Нам необходим герой! Выполнить мое задание под силу лишь целой армии, но только одному из целой толпы будущих героев суждено принять на себя тяжкую ношу ответственности – стать союзником Племени.$B$BВ логове повелителя Черной горы живет жестокий зверь, предводитель драконов Разящий Бич. Он охраняет Зал Раздора, перекрывая путь в покои Нефариана. Убей гнусную тварь и принеси мне ее голову. Это будет первым шагом на твоем пути.', 'Принесите голову предводителя драконов Разящего Бича Баристольфу из Зыбучих Песков в крепость Кенария в Силитусе.', 'Неужели ты станешь первым союзником бронзовых драконов за тысячу лет?', 'Твоя цель – завоевать благосклонность рода Ноздорму.', NULL, NULL, 'Голова предводителя драконидов Разящего Бича', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8290, 'Долой захватчиков!', '$gЮный:Юная:c: $C! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$B$BОтправляйся в ущелье Песни Войны, чтобы оборонять заставу Среброкрылых! Отражай нападения ордынских захватчиков!$B$BНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $N, и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Ордой, получите почетный знак ущелья Песни Войны и вернитесь с ним к часовой Дальней Песне в рощу Среброкрылых.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8291, 'Долой захватчиков!', '$gЮный:Юная:c: $C! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$B$BОтправляйся в ущелье Песни Войны, чтобы оборонять заставу Среброкрылых! Отражай нападения ордынских захватчиков!$B$BНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $N, и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Ордой, получите почетный знак ущелья Песни Войны и вернитесь с ним к часовой Дальней Песне в рощу Среброкрылых.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8294, 'Громи захватчиков-Среброкрылых!', 'Чащобы Ясеневого леса падут перед мощью Орды, $r! Что бы ни делали часовые из армии Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как они смеют препятствовать нам пользоваться тем, что по праву наше?$B$BПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из армии Среброкрылых и заслужи почетный знак ущелья Песни Войны. Вернись ко мне с этим знаком, $N – и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8295, 'Громи захватчиков-Среброкрылых!', 'Чащобы Ясеневого леса падут перед мощью Орды, $r! Что бы ни делали часовые из армии Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как они смеют препятствовать нам пользоваться тем, что по праву наше?$B$BПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из армии Среброкрылых и заслужи почетный знак ущелья Песни Войны. Вернись ко мне с этим знаком, $N – и получишь награду!', 'Войдите в ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8297, 'Ресурсы Низины Арати', 'Войну выигрывают солдаты, любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна, еще не начавшись!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо, и все можно добыть там.$B$BИ вот чего я хочу от вас, $N. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.', 'Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Маклир в Опорный пункт.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8299, 'Перекрыть линии поставок Аратора', 'Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.$B$BТы, $N, можешь нам помочь. Отправляйся в низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захвати и удерживай под контролем те базы, которые сможешь, выиграй битву и возвращайся ко мне с ресурсами, которые тебе удастся добыть.', 'Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8301, 'Путь праведника', 'Род Ноздорму инстинктивно не верит низшим расам. Хоть ты и $gсмог:смогла: доказать мне, что у тебя задатки настоящего героя, пришло время доказать это моему повелителю.$B$BУлей Аши, улей Зора и улей Регал кишат силитидами, которые грозят нашему существованию. Убей как можно больше проклятых тварей и принеси мне фрагменты их панцирей. Когда у тебя закончится место в заплечных мешках, возвращайся и я укреплю твою решимость.', 'Принесите Баристолфу 200 фрагментов силитидских панцирей.', 'Не думай, что ты один. Я дарую тебе способность привлекать других к себе на помощь. Подлинному защитнику своего народа не обойтись без помощи собратьев.', 'Недоверие к смертным расам коренится в далеком прошлом; но пусть тебе об этом расскажут сами драконы, когда придет время', NULL, NULL, 'Обломок силитидского панциря (200)', 'Агент Ноздорму', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8302, 'Рука праведника', 'Старательно выбирай своих представителей, $gсмертный:смертная:. Всякий раз, выполнив задание, ты сможешь выбрать себе нового представителя.$B$BА теперь, не теряя времени, скажу: мне по-прежнему нужны обломки силитидских панцирей. Что стоишь? Иди!', 'Принесите Баристолфу 200 фрагментов силитидских панцирей.', 'Молодец, герой. Тебе будет дарована возможность назначить еще одного агента Ноздорму.', 'Быть может, когда-нибудь ты возглавишь гарнизон крепости Кенария.', NULL, NULL, 'Обломок силитидского панциря (200)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8303, 'Анахронос', 'Время пришло, $N.$B$BЯ должен извиниться за то, что так долго держал все в тайне. Но кругом враги, они могут оказаться у нас прямо под носом. Прошу тебя, прими этот фолиант, читай его и учись. Я с радостью делюсь с тобой знаниями. Теперь же отыщи нашего повелителя.', 'Отыщите Анахроноса в Пещерах Времени в Танарисе.', 'Весь Калимдор надеется на тебя, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8304, 'Дражайшая Наталия', 'Моя милая Наталиа пропала.$B$BЧестно говоря, в последние недели перед исчезновением она довольно странно вела себя. Я несколько раз видел, как она говорила сама с собой. При этом Наталиа уверяла, что все в порядке и ей необходимо продолжать исследования.$B$BВ последний раз я видел ее, когда она направилась в лагерь Бронзоборода, на юг.$B$BУ меня слишком мало солдат, $N. Сходи в лагерь Бронзоборода и допроси дворфов.', 'Допросите обитателей лагеря Бронзоборода по поручению командора Мар\'алита из крепости Кенария. Этот лагерь находится южнее крепости Кенария.Собрав необходимые сведения, вернитесь к командору Мар\'алиту.', '*Командир Мар\'алит опускает голову в раздумье.*$B$BЖива она или мертва, я должен выполнить свой долг. И найти ее. Увы, я не имею права покинуть этот форт. Придешь ли ты мне на помощь, $N?', NULL, NULL, NULL, 'Франкал допрошен', 'Рутгар допрошен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8305, 'Давно забытые воспоминания', 'В пустыне неподалеку от Силитуса, рядом со священной стеной, есть хрустальная слеза. Эта слеза – символ великих потерь, понесенных во время войны Зыбучих песков. Отыщи эту слезу и загляни в ее глубины, дабы достичь просветления.', 'Отыщите в Силитусе хрустальную слезу и загляните в ее глубины.', 'Вы чувствуете, что кристалл исполнен великой скорби. Сила ее столь велика, что вам кажется, будто вы немедленно рухнете и умрете от тоски.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8306, 'В бездне безумия', 'Прошу тебя, $N, отправляйся в улей Регал и узнай, что сталось с моей возлюбленной Наталией. Это будет очень непросто. Прежде чем нырять в бездну безумия, вернись и поговори с дворфами. Быть может, они подскажут тебе, как разобраться с силитидами из улья.$B$BИ последнее, $N. Если она в самом деле безумна, как говорят... сделай, что должно.$B$B<Командор Мар\'алит отворачивается в сторону.:', 'Найдите возлюбленную командора Мар\'алита из крепости Кенария в Силитусе. По имеющим сведениям, госпожу Наталию Мар\'алит можно найти в улье Регал.Прежде чем отправляться в улей, не забудьте поговорить с дворфами из лагеря Бронзоборода. Они могут дать пару советов и подкинуть дополнительную работу.Следует помнить слова командора: \"Сделай, что должно...\"', '*Командир Мар\'алит хватается за сердце.*$B$BК\'Тун? ЧТО все это значит? Что еще за К\'Тун? Как мог этот демон превратить мою милую Наталию в описанного тобой монстра?', NULL, NULL, NULL, 'Судьба госпожи Наталии Мар\'алит', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8307, 'Блюдо из червей', 'Приспособиться к жизни в пустыне, мягко говоря, нелегко. Мне не хватает не только птиц и деревьев Аубердина, но и нормальной еды! Я делаю все, что моих силах, но выбор продуктов у нас невелик. Я изучаю местные травы, но их так мало…$B$BЗато я видела, как в лагерях Сумеречного Молота охотятся на песчаных червей. Но их мясо очень горькое, и я не представляю, как сделать его съедобным. Если ты окажешься в их лагере, смотри в оба. Как узнаешь что-нибудь – сообщи мне.', 'Поищите в лагере Сумеречного Молота на западе от крепости Кенария сведения о приготовлении мяса песчаных червей.', 'В книге содержится несколько обычных рецептов и пара очень оригинальных. Полистав ее, вы находите рецепт, в котором упоминается мясо песчаных червей.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8308, 'Потерянное письмо Бранна Бронзоборода', 'Всем заинтересованным лицам:$B$BЕсли вы читаете это письмо, значит, я мертв или скоро умру. Трудно сказать. Большая часть команды уже мертва.$B$BНашел сведения про титана. Страшная битва между ним и Древним богом. Самый настоящий Древний Бог. Нашел древний туннель в Ан\'Кираж. Иду по нему.$B$BОтнесите это письмо в мой старый лагерь. Покормите, напоите и приласкайте моих обезьянок.$B$B- Бранн Бронзобород, оперативный исследователь$B$BP.S. Остерегайся безумного ночного эльфа, поклоняющегося Древнему богу.', 'Отнесите письмо Бранна Бронзоборода в лагерь Бронзоборода в южной части Силитуса.', 'Что ж, многое прояснилось. Если ты доберешься до Ан\'Киража, посматривай, нет ли там старины Бранна. Боюсь, без своих обезьян он бессилен.', 'Мамочки.', NULL, NULL, 'Потерянное письмо Бранна Бронзоборода (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8309, 'Поиски рун', 'После нашего первого рейда в ульи и последовавшего безумия госпожи Мар\'алит, их этих трех ульев так и хлынули проклятые жуки! Мне кажется, их повышенная активность связана с письменами, покрывающими эти странные кристаллы.$B$BНам нужны оттиски с кристаллов из всех трех ульев. Заполучив их, мы можем попытаться понять причины этого безумия.$B$BВозьми копирующее устройство геолога и ступай в ульи, $N. Без оттисков из всех ульев даже не возвращайся.', 'Рутгар Знакописец из лагеря Бронзоборода в Силитусе просит отправиться в улья Аши, Зора и Регал и сделать оттиски со всех покрытых письменами кристаллов.Чтобы сделать приличные копии древних рун, можно воспользоваться копирующим устройством геолога. По выполнении задания вернуться к Рутгару Знакописцу.', 'Ничего я не понимаю в этих письменах. Первый раз такие вижу! Надеюсь, исследования Франкала помогут пролить на них свет.', 'Если в одном из ульев тебе попадется ненормальная ночная эльфийка, дай ей хорошего пинка от нашего имени.', NULL, NULL, 'Оттиск кристалла из Улья Аши', 'Оттиск кристалла из Улья Зора', 'Оттиск кристалла из Улья Регал', 'Копирующее устройство геолога (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8310, 'Расшифровка', 'Мне кажется, я изобрел эликсир, который поможет нам расшифровать письмена и язык силитидов и киражей! Что мне нужно? Хорошо, что ты $gспросил:спросила:! Мне нужны мозги! Точнее говоря, мозги всех видов силитидов, живущих в ульях. Принеси мне мозги, и работа Рутгара не пойдет насмарку.', 'Добудьте для Франкала Каменного Моста из лагеря Бронзоборода в Силитусе мозг силитидов из ульев Зора, Аши и Регал. По выполнении задания вернитесь к Франкалу.', 'Поразительно! Не уходи далеко, дитя. Может быть, мы поручим тебе еще задание-другое.', 'Поиграй с мартышками, дитя. У меня нет времени на глупости.', NULL, NULL, 'Мозг силитида из Улья Аши', 'Мозг силитида из Улья Зора', 'Мозг силитида из Улья Регал', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8311, 'Тыквовинские вкусности для Джеспера!', 'Хотел бы я пойти потыквовинничать, но не могу – приболел. Если ты вместо меня сходишь, я обменяю тебе сладости, что ты наберешь, на те, что у меня уже есть. Думаю, тебе они понравятся – они превратят тебя в разные смешные и страшные штуки!$B$BУ каждого из хозяев таверн в больших городах есть сладости, которые они раздают на Тыквовин. Поговори с ними и выполни их задания. А еще в Стальгорне живет гном по имени Талваш, и он тоже раздает сладости. Когда соберешь их все, принеси мне сюда!', 'Поговорите с хозяевами таверн в Штормграде, Стальгорне и Дарнасе, а также с Талвашом де Кисселем в Стальгорне. Выполните то, что они потребуют за предлагамые ими сладости.Вернитесь к Джесперу в сиротский приют Штормграда и принесите ему марципан из Дарнаса, леденец из Гномрегана, нугу из Штормграда и конфету из Стальгорна.', '', NULL, NULL, NULL, 'Нуга из Штормграда', 'Леденец Гномрегана', 'Конфета Стальгорна', 'Дарнасский марципан');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8312, 'Тыквовинские вкусности для Крохи!', 'Я бы так хотела отправиться за конфетами! Но не могу, потому что болею... Сходи вместо меня, а? А я с тобой потом поменяюсь: отдам те конфеты, что у меня уже есть, взамен тех, которые дадут тебе! Вот эта конфетка тебе наверняка понравится: она позволяет превращаться в разных существ, забавных и страшных!$B$BУ всех хозяев таверн в больших городах непременно есть конфеты, которые они дарят на Тыквовин – надо только поговорить с ними и сделать то, что они попросят. И троллиха по имени Кали Ремик в деревне Сен\'джин тоже раздает конфеты. Когда соберешь все конфеты, принеси их мне, ладно?', 'Поговорите с хозяевами таверн в Оргриммаре, Подгороде и Громовом Утесе и с Кали Ремик из деревни Сен\'джин. Выполните то, что они потребуют за предлагамые ими сладости.Вернитесь к Мальцу в сиротский приют Оргриммара и принесите ей марципан Громового Утеса, леденец племени Черного Копья, нугу из Оргриммара и конфету Подгорода.', 'Ух ты! Тебе удалось собрать их все! Ты настоящий герой!$B$BСпасибо большое. Вот, возьми эти тыквовинские конфеты – они ужасно вкусные!$B$BСчастливого Тыквовина, $N!', 'Что, много конфет тебе дали? Ужасно жаль, что я не могу пойти сама, но оттого, что ты мне помогаешь, мне чуточку легче...', NULL, NULL, 'Нуга из Оргриммара', 'Леденец племени Черного Копья', 'Конфета Подгорода', 'Марципан Громового Утеса');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8313, 'Наделение знаниями', 'Хотя вам вполне понятен рецепт по приготовлению мяса песчаного червя, в нем упоминаются незнакомые травы и специи. Быть может, Каландрата хорошо разбирается в растениях пустыни и сможет помочь вам.', 'Принесите вырванную страницу с рецептом Каландрате в таверну крепости Кенария.', 'Дай-ка взглянуть…$B$BКажется, все просто. У них есть свои названия для некоторых видов растений, но догадаться совсем просто. Дай, я покажу!', 'Ты освоил рецепт? Надеюсь, ты поделишься им с друзьями?', NULL, NULL, 'Вырванная страница с рецептом (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8314, 'Разгадка тайны', 'Мы на грани крупного прорыва, $N! Принесенные тобой оттиски позволили нам воссоздать письмена на хрустально призме. Очевидно, что для киражей и прочих непонятных сущностей они имеют большое значение и позволяют передавать силитидам сообщения.$B$BК несчастью, это все, что нам удалось понять. Необходимо прочитать послания, сокрытые в кристаллах.$B$BОтнеси покрытую письменами хрустальную призму геологу Ехидной в крепость Кенария. Может, она сумеет тебе помочь.', 'Рутгар Знакописец из лагеря Бронзоборода в Силитусе просит вас отнести покрытую письменами хрустальную призму геологу Ехидной в крепость Кенария.', 'Дворфы не смогли расшифровать письмена, потому что тут и расшифровывать нечего. Следовало просто правильно повернуть верхний слой призмы, так, чтобы он выровнялся с изображениями внутри кристалла. Тогда сообщение можно прочитать. Умно…$B$BВпрочем, хотя теперь мы можем перевести полученные данные, главное – понять их правильно. На поверхности призмы есть только одна подсказыка – если я правильно перевела оттиски – и если ей верить, то дело плохо.', 'Ну и ну! Что это, $N?', NULL, NULL, 'Покрытая письменами хрустальная призма (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8315, 'Зов', 'Здесь изображена встреча посланника киражей с тремя силитидами у костей большого дракона. Над рисунком я вижу надпись, судя по всему, какой-то шифр. Не исключено, что это ключевой момент призыва посланника.$B$BЯ создам копию, попробуй воспользоваться ей в пустыне у Костей Граккаронда. Если я права, вожди решат, что им посылают какие-то данные и явятся на зов. Убей их и сразись с посланником. Ключ к кристаллам у него...', 'Геолог Ехидная из крепости Кенария просит добыть открыватель кристаллов у киражского посланника.Вам следует отнести письмена зова к костям Граккаронда, на юг от крепости Кенария, и нарисовать их на песке. Если появится киражский посланник, убейте его и заберите открыватель кристаллов. При успехе вернитесь к геологу Ехидной.Для выполнения задания понадобится целая армия!', '20.000 лет истории у меня в руках!', 'Мы должны воспользоваться подходящей возможностью и нанести удар!', NULL, NULL, 'Открыватель Кристаллов', 'Письмена зова', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8316, 'Оружие войны', '', '', 'Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.Если это... пророчество сбудется…*Геолог Ехидная бледнеет.*Можно считать, что у нас нет будущего.Это оружие понадобится тебе на войне в пустыне.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8317, 'Помощь по кухне', 'Рецепт мне несомненно пригодится. Пора приниматься за работу, чтобы приготовить копченые пустынные клецки уже сегодня. Мне не помешала бы помощь, а уж я бы тебе отплатила сторицей.', 'Каландрате из крепости Кенария нужны 10 копченых пустынных клецок.', 'Отлично! Ты мой спаситель. Не думала, что сторонники Сумеречного Молота могут придумать такой хороший рецепт.', 'Как идут дела с клецками?', NULL, NULL, 'Копченые пустынные клецки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8318, 'Тайные послания', 'Некоторые из служителей культа Сумеречного Молота носят с собой листы бумаги, на которых нацарапана какая-то неразборчивая писанина. Принеси мне целую пачку таких писулек.$B$BЯ не могу понять, что означает эта ерунда, но дело не в том! При помощи этих бумажек происходят тайные переговоры их группировок. Чем больше текстов мы у них отнимем, тем сложнее им будет обмениваться сообщениями!', 'Принесите 10 зашифрованных сумеречных текстов Бору Буйногривому в крепость Кенария.', 'Великолепно! Уберу-ка я их подальше, они мне потом пригодятся.', 'Ты принес мне тексты?', NULL, NULL, 'Зашифрованный Сумеречный текст', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8319, 'Зашифрованные Сумеречные тексты', '', '', 'Отличная работа! Я замолвлю за тебя доброе слово.', NULL, NULL, NULL, 'Зашифрованный Сумеречный текст', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8320, 'Геолорды из культа Сумеречного Молота', 'Сумеречный Молот, безумная секта, поклоняющаяся богам смерти и разрушения, разбила лагеря по всему Силитусу и день и ночь проводит свои ритуалы. Планы ее стронников нам неизвестны, но они как-то связаны с пульсирующими красными кристаллами, разбросанными по всей пустыне.$B$BХотя, быть может, однажды нам удастся разгадать эту тайну, но сейчас главное – избавиться от угрозы. Ступай в их лагеря и найди там геолордов из культа Сумеречного Молота. Они командуют этими змеюками, поэтому нанести удар необходимо именно по ним!', 'Убейте 10 геолордов из культа Сумеречного Молота и вернитесь к Хууму Буйногривому в крепость Кенария.', 'Ты отлично справился с этим заданием, $N. Смерть геолордов из культа Сумеречного Молота – серьезный удар по силам культа. Будем надеяться, что мы сумели отсрочить выполнение их планов...', NULL, NULL, NULL, 'Сумеречный геолорд убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8321, 'Вайрал Подлый', 'Мы обнаружили еще одну базу Сумеречного Молота. Она зовется Сумеречная пещера и находится в северо-восточной части Силитуса. Их главарь, Вайрал Подлый, живет именно в этой пещере, и его-то тебе и предстоит победить. Одолев злодея, принеси мне его перстень-печатку.$B$BГоворят, что в Сумеречной пещере можно насмотреться таких ужасов, что век не забудешь.', 'Принесите перстень-печатку Вайрала Хууму Буйногривому в крепость Кенария.', 'Получилось! Вайрал мертв! Что ж, нападение Сумеречного Молота на Силитус обречено на провал. Их здесь еще немало осталось, но они нескоро оправятся от сегодняшнего удара.', 'Тебе удалось победить Вайрала Подлого? Где его перстень-печатка?', NULL, NULL, 'Перстень-печатка Вайрала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8322, 'Тухлые яйца', 'Люди Южнобережья любят эль, особенно тот, что подают в местной таверне. Думаю, тыквовинского хаоса им маловато – надо бы подпортить им недельный, а то и месячный запас выпивки!$B$BВозьмите вот эти тухлые яйца и подбросьте в главную бочку с пивом в таверне Южнобережья. Однако вашего присутствия там не потерпят, поэтому приготовьтесь защищаться!$B$BКак только угостите все Южнобережье этим незабываемым элем, возвращайтесь на наш фестиваль!', 'Бросьте тухлые яйца в главную бочку с пивом в таверне Южнобережья.', 'Пробившись в таверну, вы опускаете тухлые яйца в бочку. В воздухе разливается отвратительная вонь...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8323, 'Истинно верующие', 'Теперь, когда у меня есть Сумеречный словарь, мне остается попросить тебя о небольшой услуге.$B$BВ моей бывшей организации ежемесячно издаются тщательно закодированные сводки новостей.$B$BЕсли они получат новые сведения обо мне или решат перестать меня искать, об этом сообщат в \"Истинно верующем\".$B$BХотя меня, безусловно, интересует подобная информация, в этих сводках могут быть и другие полезные сведения. Принеси мне как можно больше зашифрованных текстов, добытых у сторонников Сумеречного Молота.', 'Принесите 10 зашифрованных Сумеречных текстов отшельнику Ортеллу.', 'Великолепно! Я как можно скорее займусь расшифровкой. Если мне попадется интересная информация, я найду способ связаться с тобой.', 'Тебе удалось найти зашифрованные тексты? Мне было бы интересно заглянуть в свеженький номер \"Истинно верующего\".', NULL, NULL, 'Зашифрованный Сумеречный текст', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8324, 'Не теряя веры', '', '', 'Великолепно! Если тебе снова попадутся зашифрованные тексты, сразу неси мне.', NULL, NULL, NULL, 'Зашифрованный Сумеречный текст', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8325, 'Очищение острова Солнечного Скитальца', 'Чем скорее ты начнешь свое обучение, $N, тем лучше будет для всех нас. Поскольку права на ошибку у нас нет, слушай внимательно.$B$BПламенеющие кристаллы - зеленые плавающие в воздухе объекты к западу от Солнечного Шпиля - используются на нашем острове как источники энергии для проведения магических экспериментов. Маназмеи издревле охраняли их, но во время вторжения Плети в Кель\'Талас наша магическая сила ослабла, и маназмеи вышли из повиновения.$B$BУ нас нет иного выбора, кроме как истреблять их ради очищения острова. Убей несколько маназмеев и возвращайся ко мне.', 'Убейте 8 маназмеев – они находятся у пламенеющих кристаллов, недалеко от башни и беседки Солнечного Шпиля.', 'Что же, ты успешно справился со своим первым заданием, прими мои поздравления. Твои успехи вселяют в меня уверенность, что ты пойдешь гораздо дальше, чем те молодые эльфы крови, что пропускают мимо ушей уроки наставников. Дальнейшие успехи будут вознаграждаться, и не только знаниями, но и кое-чем более ощутимым.$B$BОднако твоя работа здесь пока не закончена. Тебе еще многому предстоит научиться...', NULL, NULL, NULL, 'Маназмей убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8326, 'Вынужденные меры', 'Благодаря тебе мне удалось кое-что выяснить, но, честно говоря, открытие меня не порадовало. Необузданная мощь пламенеющих кристаллов нарушила природное равновесие острова гораздо сильнее, чем я думала. Так что придется прибегнуть к весьма жестким мерам, чтобы восстановить равновесие.$B$BНекоторые из местных животных, например рыси, попали под влияние кристаллов, и их придется истребить. Принеси мне их ошейники, $N, и я попробую восстановить нашу власть над рысями.', 'Соберите 8 ошейников с убитых рысей-прыголапов и детенышей прыголапов и возвращайтесь к магистру Эроне на острове Солнечного Скитальца.', 'Теперь башня и ее окрестности станут относительно безопасными, пусть и ненадолго. Ты хорошо потрудился, но если мы хотим здесь прочно обосноваться, необходимо взять под контроль весь остров. А для этого придется сталкиваться с куда более грозными противниками, чем обезумевшие маназмеи и рыси.$B$BВозьми мой подарок, $N, он тебе, несомненно, пригодится в дальнейшем.', 'Мне не доставляет никакого удовольствия просить тебя убивать этих животных. В прошлом мы жили в относительной гармонии с лесными существами, но настали другие времена. Главная задача син\'дорай – выжить. Помни об этом.', NULL, NULL, 'Ошейник рыси', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8327, 'Визит к Лантану Перилону', 'Ступай к моему помощнику, Лантану Перилону. Он скажет тебе, что делать дальше. Пока мы обуздываем мощь пламенеющих кристаллов, тебе придется заняться академией Фалтриена. Лантан подробно объяснит тебе все при встрече.$B$BИди на запад по этой тропе и скоро увидишь его.$B$BУдачи, $N, твои труды будут вознаграждены.', 'Поговорите с Лантаном Перилоном на острове Солнечного Скитальца – он стоит рядом с дорогой, отходящей на запад от Солнечного Шпиля.', '$N, магистр Эрона говорила мне, что ты скоро прибудешь. Видишь на западе высокое здание с резными шпилями, парящее в воздухе? Это – академия Фалтриена. Тебе предстоит отбить ее у одного из Презренных - эльфов крови, поддавшихся своим самым низменным страстям.$B$BНадеюсь, ты готов к битве. Это станет для тебя не просто уроком доблести, но и примером того, что с тобой случится, если ты забудешь о том, кто ты есть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8328, 'Обучение мага', 'По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных магов на острове Солнечного Скитальца тренирует Джулия Солнцесвет. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.$B$BДжулия, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.', 'Поговорите с наставницей магов Джулией Солнцесвет в Солнечном Шпиле на острове Солнечного Скитальца.', 'А, $N, видимо, ты из новых магов нашего острова, да? Что же, ты не ошиблась, заглянув ко мне. Если ты хочешь овладеть искусством магии, то я согласна делиться с тобой своими знаниями - покуда твоих денег и способностей будет хватать для продвижения в науке.$B$BНачнем же!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8330, 'Вещи Соланиана', 'Из-за беспорядков в Солнечном шпиле я не успел собрать свои вещи, которые оставил в разных местах по всему острову. Я не могу бросить свой пост у Солнечного Колодца, поэтому прошу тебя собрать их.$B$BМне нужен мой гадальный шар, дневник и свиток магии Плети. Возьми эту сумку и сложи в нее вещи. Принеси их мне, и я награжу тебя, а в придачу отдам сумку!', 'Верните Соланиану его гадальный шар, дневник и свиток магии Плети. Их можно найти на острове Солнечного Скитальца у пруда, у одного из пламенеющих кристаллов и у фонтана. Вернитесь с вещами к хранителю Колодца в Солнечный шпиль на острове Солнечного Скитальца.', 'Отлично! Я знал, что ты прекрасно справишься. Как только мы почувствуем себя в безопасности на этом острове, я сумею найти этим вещам хорошее применение.$B$BКак я и обещал, сумка теперь твоя. Думаю, это справедливая награда!', 'Тебе удалось найти мои вещи? Как только мы окончательно закрепимся на острове Солнечного Скитальца, они понадобятся мне для работы. А пока я должен следить за Солнечным Колодцем... точнее за тем, что от него осталось.', NULL, NULL, 'Гадальный шар Соланиана', 'Свиток магии Плети', 'Дневник Соланиана', 'Сумка острова Солнечного Скитальца');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8331, 'Аурель Золотой Лист', 'Мы надеялись, что Сумеречный Молот свернет свои операции в Силитусе... Увы, мы ошиблись. Благодаря постоянным нападением на лагеря сектантов нам удалось выяснить, что Молот контролирует еще более страшная сила, Совет Бездны. Для связи с культистами, этот совет пользуется ветровыми камнями, рассеянными по лагерям Молота. Пришло время выступить против Совета Бездны.$B$BПоговори с ремесленницей Аурель Золотой Лист, в восточной части крепости Кенария. Мы задумали одну хитрость, для которой необходимо ее искусство.', 'Поговорите с Аурель Золотой Лист в крепости Кенария.', 'Добрый день, $N. Говорят, ты собираешься выступить против Совета Бездны? Коли так, слушай внимательно...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8332, 'Герцоги Совета', 'Мы думаем, что при помощи ветрового камня можно устроить засаду на герцога Совета Бездны. Для этого придется связаться с Советом через этот камень и убедить всех, что ты – $gодин:одна: из командующих среднего ранга Сумеречного Молота.$B$BЧтобы эта хитрость удалась, необходим статусный медальон. Я могу создать его, но мне понадобится большой сверкающий осколок и талисманы храмовников Бездны.$B$BПринеси их мне, а остальное я сделаю сама.', 'Принесите Аурель Золотой Лист в крепость Кенария 1 большой сверкающий осколок и 3 талисмана бездны.', 'Очень хорошо. Я как раз начала работать над созданием медальона – дело за последними компонентами. Я закончу через несколько минут…$B$BНу вот. Медальон готов.$B$BЕго надо надеть перед тем, как активировать один из ветровых камней Сумеречного Молота. Кроме медальона тебе понадобится Сумеречное облачение, и Совет Бездны примет тебя за одного из своих прихвостней-культистов.', 'У тебя уже есть осколок и талисманы, $N? Без них мне не сделать станционный медальон.', NULL, NULL, 'Большой сверкающий осколок', 'Талисман Бездны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8333, 'Статусный медальон', '', '', 'Вот, $N. Еще один станционный медальон служителя Сумрачного Молота. Бери на здоровье. Удачи тебе в борьбе с Советом Бездны!', NULL, NULL, NULL, 'Большой сверкающий осколок', 'Талисман Бездны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8334, 'Агрессия', 'Прежде чем направить тебя в академию, я хочу, чтобы ты $gвыполнил:выполнила: одну задачу, требующую немедленного решения. Некогда древуны помогали нам возделывать наш прекрасный остров, но теперь они вышли из повиновения. Уничтожь их как можно скорее, но помни: они очень агрессивны. Именно из-за этого нам приходится истреблять некогда покорных нам слуг.$B$BМне неприятно просить тебя об этом, но выживание – не самое приятное дело. Горевать будем потом.', 'Убейте 7 древунов и 7 одичавших древунов, затем вернитесь к Лантану Перилону на острове Солнечного Скитальца.', 'Хотя гибель древунов не приносит мне радости, твой успех показал мне, что ты созрел для выполнения важнейшей задачи на острове Солнечного Скитальца. Выбери награду – для следующего задания тебе понадобится надежное оружие. От твоего успеха зависит дальнейшая судьба острова.', NULL, NULL, NULL, 'Древун убито', 'Одичавший древун убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8335, 'Фелендрен Изгой', 'В академии Фалтриена, что к юго-западу отсюда, обитает предатель нашего народа.$B$BЕго зовут Фелендрен. Он был изгнан из земель эльфов крови за то, что не слушал предостережений наставников и старейшин. Он изгой нашего общества, ибо живет он лишь для того, чтобы насыщать свою неутолимую жажду магии. Фелендрен не пожелал бороться со своим пагубным пристрастием и превратился в жалкое подобие мыслящего существа. Теперь он один из Презренных, которые угрожают нашему спокойствию!$B$BСрази его и тех духов, которых он сделал своими приспешниками!', 'Убейте 8 чародейских призраков, 2 нечистых чародейских призрака и Фелендрена Изгоя в академии Фалтриена. Принесите голову Фелендрена Лантану Перилону на остров Солнечного Скитальца.', 'Голова Фелендрена... ты достоин похвалы, $N. Ты преуспел там, где прочие, как и Фелендрен, потерпели крах. Возможно, ты и правда уже готов совершать подвиги во имя эльфов крови.$B$BТвой успех говорит о том, что ты способен преодолеть серьезные испытания, таящиеся в чащобах Лесов Вечной Песни... и поверь мне, они уже ждут тебя.', 'Помни: Фелендрен Изгой – всего лишь симптом куда большей беды. Его уничтожение решит лишь наши сегодняшние проблемы, но всем эльфам крови грозит та же участь, если мы не научимся обуздывать свою тягу к магии.', NULL, NULL, 'Чародейский призрак убито', 'Нечистый чародейский призрак убито', 'Голова Фелендрена', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8336, 'Пригоршня осколков', 'Очень жаль, что мы утратили контроль над многими существами этого острова. Некогда это был оплот спокойствия, трудов и исследований. Теперь мы только и делаем, что отбиваемся от нападений собственных созданий!$B$BВыполни для меня небольшое поручение и получишь волшебный дар. Принеси мне горсть магических осколков. Ты можешь найти их у существ, обладающих магическими способностями. В награду за это я наложу на тебя заклятие, которое поможет тебе в твоих приключениях.', 'Соберите 6 магических осколков, убивая любых существ, обладающих магическими способностями, а затем вернитесь к чародею Итанасу.', 'Замечательно! Как раз то, что нужно. Я много размышлял о проклятии, поразившем остров Солнечного Скитальца. Одно из возможных решений проблемы – собирать магические осколки и проводить эксперименты над ними. Не лучший путь, но другого я пока не вижу.$B$BКак бы то ни было, я продолжу свои исследования. Сейчас я наложу на тебя заклятие. Уверен, оно тебе поможет!', 'Некогда при помощи магии мы подчинили себе многих существ этого острова. Но когда Плеть уничтожила Солнечный Колодец, наша власть над ними ослабла. Магические осколки – все, что осталось от наших заклинаний, и мы надеемся создать из них новое устройство, чтобы вновь подчинить себе местную фауну.$B$BВозможно, они также помогут нам понять, что за проклятие поразило наш остров...', NULL, NULL, 'Магический осколок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8338, 'Оскверненный магический осколок', 'Вы нашли странный магический осколок, обыскав останки нечистого чародейского призрака. Осколок не похож на те, что вам уже попадались. Он темный и выглядит зловеще – прямо как тот дух, у которого вы его забрали. Один вид его на вашей ладони наполняет вас зловещими предчувствиями.$B$BЧародей Хелион возле беседки у Солнечного Шпиля на острове Солнечного Скитальца наверняка сможет найти ему применение.', 'Принесите оскверненный магический осколок чародею Хелиону, который стоит возле беседки у Солнечного Шпиля на острове Солнечного Скитальца.', 'Как интересно... Когда я говорю \"интересно\", это значит, что я крайне взволнован.$B$BВосстановление контроля над островом после разрушения Солнечного Колодца - задача чрезвычайно тяжелая. Подозреваю, что за всеми нашими бедами стоит одна и та же злая сила, и этот осколок поможет мне понять, что же на самом деле происходит.$B$BТы мудро поступил, принеся его мне, $N. Вот, возьми это в награду за предусмотрительность. Благодарю тебя.', 'Судя по всему, у тебя какое-то срочное дело. Чем я могу помочь?', NULL, NULL, 'Оскверненный магический осколок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8341, 'Лорды Совета', 'Чтобы вызвать лордов Совета Бездны, необходим больший ветровой камень. К тому же они согласны беседовать лишь с самыми высокопоставленными представителями Сумеречного Молота. Но... Я придумала, как поработать над твоей маскировкой и обмануть лордов Бездны!$B$BДля этого понадобится кольцо Власти, которое носят лишь вожди сектантов. Я готова создать такое кольцо, если ты принесешь мне большие сверкающие осколки и перстни Бездны.', 'Принесите Аурель Золотой Лист в крепость Кенария 5 больших сияющих осколков и 3 перстня бездны.', 'Спасибо. Минуточку, сейчас кольцо будет готово…$B$BВот, бери.$B$BНе забудь надеть это кольцо, станционный медальон и прочее облачение Сумеречного Молота, прежде чем активировать ветровой камень. Тогда Совет бездны примет тебя за одного из своих, и может быть, тебе удастся заманить одного из них в ловушку!', 'Ты принес мне околки и перстни, $N? Без них я не смогу создать кольцо Власти.', NULL, NULL, 'Большой сверкающий осколок', 'Перстень Бездны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8342, 'Кольцо Власти служителя культа Сумеречного Молота', '', '', 'А, вижу, твоя решимость не ослабела. Немногие решились бы схватиться с демоническим советом!$B$BВот кольцо, $N. Да пребудет воля твоя тверда, и да сопутствует тебе удача.', NULL, NULL, NULL, 'Перстень Бездны', 'Большой сверкающий осколок', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8343, 'Открытие Золотого Листа', '$N, Аурель придумала, как вызвать и одолеть правящую верхушку Совета Бездны! Это опасно, но ты $gзаслужил:заслужила: уважение всего Круга Кенария. Мы знаем, что ты – $gединственный:единственная:, кому по плечу такое задание.$B$BЖелаю удачи, $N. Когда решишь приняться за это задание, поговори с Аурель.', 'Поговорите с Аурель Золотой Лист в крепости Кенария.', 'Хуум говорит правду. Думаю, я знаю, как вызвать лорда Совета Бездны. Слушай внимательно...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8344, 'Windows to the Source', '', '', 'Отлично! Да, этих сущностей хватит для первого этапа моих исследований. У меня стойкое ощущение, что сущность оскверненного духа - это как раз то, что мы ищем... источник силы, о котором я говорил.$B$BМолодым чернокнижникам необходимо строго выполнять приказы старших. Как я и обещал, вот твоя награда за послушание и выполнение поручения - знание о том, как призывать и подчинять беса.$B$BПусть оно хорошо тебе послужит, Котячий.', 'Сущности духов помогут мне как источники силы в моих экспериментах. Чернокнижнику важно понять природу существа прежде, чем подчинять его своей воле. Демоны - самый мощный источник силы, и если они и правда скрываются на нашем острове, то это просто подарок судьбы.$B$BНу... для нас, чернокнижников.', NULL, NULL, 'Призрачная сущность', 'Оскверненная призрачная сущность', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8345, 'Святилище Дат\'Ремара', 'День за днем я стою здесь и смотрю на море. Глаза мои устремлены к горизонту, и люди говорят, что я живу лишь прошлым. Но я твердо убежден, что каждый, кто попадает на этот остров, обязан почтить память героев, пожертвовавших собой ради нашего народа.$B$BДат\'Ремар Солнечный Скиталец был нашим первым королем. Он привел нас сюда из Калимдора через бурный Водоворот.$B$BНайди его святилище на западе отсюда и не возвращайся, пока не прочтешь надпись, посвященную памяти короля.', 'Прочтите надпись на святилище Дат\'Ремара и вернитесь к хранителю Колодца Соланиану в Солнечный шпиль на острове Солнечного Скитальца.', 'Ах, $N, благодарю тебя за то, что ты посетил святилище Дат\'Ремара. Прежде всего следует похвалить тебя за чувство долга и почтительность – они послужат тебе не только здесь, но и повсюду на Азероте.$B$BЧто до странных ощущений – несомненно, это от порчи, поразившей остров Солнечного Скитальца. Мы обратим на это внимание; спасибо за предупреждение!', NULL, NULL, NULL, 'Надпись на святилище Дат\'Ремара прочитана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8346, 'Неутолимая жажда', 'На острове Солнечного Скитальца тебя ждет множество уроков, но один ты $gдолжен:должна: запомнить навсегда: обуздывай свою жажду магии, $N! Эта жажда неутолима! Тебе необходимо научиться контролировать расход энергии при помощи \"Волшебного потока\". Если ошибешься – станешь $gодним:одной: из Презренных... безнадежно зависимых от магии безумцев.$B$BНайди на острове маназмея и попрактикуй на нем заклинание \"Волшебного потока\". Научись обуздывать свою тягу к магии. Возвращайся, когда утолишь жажду.', 'Используйте вашу расовую способность \"Волшебный поток\" против маназмея, затем вернитесь к чародею Хелиону.', 'Сегодня ты славно потрудился, $N. Твоя тяга к учебе показывает мне, что ты одолеешь неутолимую жажду, которую приходится терпеть всем эльфам крови.$B$BОднако не зазнавайся. Стремись к новым знаниям и неустанно применяй их. Только усердие спасет нашу расу.$B$BВозьми этот подарок - он тебе пригодится. Теперь ступай и верни былую славу нашему народу!', NULL, NULL, NULL, 'Примените \"Маноотбор\" к существу', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8347, 'Помощь курьерам', 'Магистр Эрона желает, чтобы ты $gнаправился:направилась: в город Луносвет и $gпомог:помогла: нам восстановить его... Она начала питать к тебе особое доверие после того, как ты $gразрешил:разрешила: ситуацию в академии Фалтриена. Не разочаруй нас, $N.$B$BПо дороге на площадь Соколиных Крыльев, к югу отсюда, поговори с гонцом Аларион. Ты найдешь ее неподалеку от моста.$B$BКурьеры заботятся о перевозке грузов отсюда на континент и обратно, и ты $gмог:могла: бы оказать им существенную помощь в этом деле.', 'Поговорите с курьером Аларион у моста к югу от острова Солнечного Скитальца.', 'О, привет, $C! До меня дошел слух, что молодой и талантливый эльф, хорошо послуживший магистру Эроне, направляется сюда, чтобы помочь курьерам. Мы не откажемся от помощи, зная, что ты проявил себя так хорошо.$B$BНадеюсь, ты выполнишь для нас парочку поручений?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8348, 'Перстень герцогов', 'Хуум говорит, что ты $gпридумал:придумала:, как вызвать герцогов Бездны! Это большое достижение.$B$BЗнаешь, что бы еще хорошо сделать? Убить одного из них. Это произвело бы неизгладимое впечатление на их прихвостней, если ты понимаешь, о чем я. В доказательство собственного подвига принеси перстень герцога.', 'Принесите перстень бездны Бору Буйногривому из крепости Кенария.', 'Стоило тебе войти в крепость Кенария, и я сразу понял, что передо мной могучий $C. Так держать!', 'Как дела с герцогом Бездны? Трудно пришлось?', NULL, NULL, 'Перстень Бездны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8349, 'Бор Буйная Грива', 'Теперь у тебя есть медальон, и ты можешь вызвать герцога Бездны. Поговори с Бором Буйногривым. Он даст тебе задание.$B$BУдачи, $N. Если тебе снова понадобятся медальоны, возвращайся ко мне.', 'Поговорите с Бором Буйногривым из крепости Кенария.', 'Рад видеть тебя, $C! Значит, теперь у тебя есть медальон? Хорошо – он понадобится тебе для следующего задания...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8350, 'Доставка посылки', 'Гибель еще одного нашего курьера - истинная трагедия, но это неизбежные издержки нашего ремесла. Нужно как можно быстрее доставить этот сверток магистру Эроне на постоялый двор на Площади Соколиных Крыльев.$B$BНам недостает курьеров, и мне больше некому дать это поручение.$B$BНе скрою - путь на Площадь Соколиных Крыльев станет чрезвычайно опасен, как только ты покинешь пределы Рассветной улицы. Возьмешься за это дело, $N?', 'Доставьте посылку Эроны хозяйке таверны Деланиель на площадь Соколиных Крыльев в лесах Вечной Песни.', 'Благодарю за быструю доставку.$B$BИ пока ты здесь, чувствуй себя как дома. Если у тебя еще нет камня возвращения - возьми его. Он позволит тебе мгновенно перенестись в таверну - но не чаще одного раза в час. Если вдруг потеряшь свой камень возвращения - просто зайди в любую таверну, и хозяин охотно даст тебе другой камень.', 'Добро пожаловать в мою таверну, $C. Я вижу, ты что-то мне принес?', NULL, NULL, 'Сверток Эроны (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8351, 'Разговор с Бором', 'Теперь ты можешь замаскироваться под высокопоставленного представителя Сумрачного Совета, и с тобой хочет поговорить Бор Буйногривый. Ступай, поговори с ним и готовься к трудному заданию...', 'Поговорите с Бором Буйногривым из крепости Кенария.', 'Да, все верно, $N. У меня есть очень сложная задача...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8352, 'Скипетр Совета', 'Мы с Хуумом только что обсуждали тебя. Он говорит, что ты $gготов:готова: испытать себя и сразиться с лордом Бездны!$B$BДолжен предупредить, что это очень опасно. Возьми с собой подкрепление. И не пару друзей, а хороший боевой отряд. Если твои друзья стоят тебя, кто знает, может быть, удастся одолеть этого лорда!$B$BЕсли ты вдруг справишься – мне как всегда потребуются доказательства – то тебя ждет великая награда.', 'Принесите скипетр бездны Бору Буйногривому из крепости Кенария.', 'Ты... ты справился! Невероятно, $N! Вот! Возьми это. Это самый большой сундук, какой у нас только был, и я набил его нашей лучшей добычей.', 'Ну, как дела? Я бы с удовольствием бросил свой пост и схватился с одним из них!', NULL, NULL, 'Скипетр Бездны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8353, 'Курочка с мятой', 'А, тыквовинничаем для больных деток? Я сказал бы, ты малость $gстароват:старовата: конфетки выпрашивать...$B$BЧто же, за мое лакомство – стальгорнскую мятную конфетку – ты мне... поквохтаешь как курица! Да, курочка с мятой хорошо идет... ладно, может, курочке от этого и не так ХОРОШО... но конфетку не дам, пока не поквохтаешь!$B$BЛадно, $C, будешь квохтать или нет?! Пора отрабатывать лакомство!', 'Изобразите курицу для хозяина таверны Огневара.', 'Ха-ха-ха! Просто здорово, $N! Вот твое угощение.$B$BВеселого Тыквовина!', 'Я жду...', NULL, NULL, 'Изобразите курицу для хозяина таверны Огневара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8354, 'Курочка с мятой', 'А, ты у нас сегодня заместо детишек, да? Я сказал бы, ты малость $gстароват:старовата: конфетки выпрашивать...$B$BЧто же, за мое лакомство – мятную конфету Подгорода – ты... поквохчешь как курица! Да, курочки любят мятные конфетки... впрочем, им не обязательно их ЛЮБИТЬ... главное, что конфетку ты не получишь, пока не поквохчешь!$B$BНу что, $C, будешь квохтать или нет?! Пора отрабатывать лакомство!', 'Изобразите курицу для хозяина таверны Нормана и получите за это конфету Подгорода!', 'Ха-ха-ха! Просто здорово, $N! Вот твое угощение.$B$BВеселого Тыквовина!', 'Я жду...', NULL, NULL, 'Изобразите курицу для хозяина таверны Нормана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8355, 'Плата за леденец', 'А, тебе нужны сладости! Ха-ха!$B$BНу, хотя ты и доброе дело делаешь, собирая сладости для больных детишек, так просто я тебя не отпущу. Есть у меня вкусные гномреганские мармеладки, и я отдам их больным детишкам... если ты изобразишь мне паровоз! Ха, вот это будет штука! За мармеладку – целый паровоз!$B$BТу-ту, $C!', 'Изобразите паровозик для Талваша дель Кисселя.', 'У-у-у! Великолепно, $N! Вот твои сладости.$B$BСчастливого Тыквовина!', 'Ну, давай!', NULL, NULL, 'Изобразите паровозик перед Талвашем', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8356, 'Поиграй мускулами!', 'Какой у тебя... интересный костюмчик. Несмотря на то, что ты по доброте своей помогаешь заболевшему ребенку, мне все же придется попросить тебя сделать что-нибудь!$B$BНу-ка, ну-ка... ты выглядишь $gтаким сильным и мускулистым:такой сильной и мускулистой: в этом... наряде... посмотрим-ка на твои бицепсы! Да, давай, поиграй-ка мускулами, $gсилач:силачка:!$B$BПоиграешь мускулами – дам тебе вкуснейшей нуги. Это отличное тыквовинское угощение!', 'Поиграйте мышцами для хозяйки таверны Аллисон и получите от нее за это нугу из Штормграда.', 'Да ты и правда силач, ха-ха! Прекрасно, и спасибо за то, что так ценишь спорт. Вот твои сладости.$B$BСчастливого Тыквовина, $N!', 'Никаких сластей, пока не поиграешь бицепсами, $N...', NULL, NULL, 'Поиграйте мускулами перед хозяйкой таверны Эллисон', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8357, 'Танец за марципан', 'Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...$B$BДумается, нынче марципановая булочка потянет на... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусненькую марципышечку!', 'Потанцуйте для хозяйки таверны Салиенны, и за это вы получите дарнасский марципан!', 'Да тебе стоило бы в балет податься, Антрандир!$B$BВот твоя награда за чудесное развлечение. Веселого тебе тыквовина, и передай привет больным детишкам! Пусть быстрее поправляются.', 'Ты ведь умеешь танцевать, а? Ну, попытайся – правая нога вперед... затем назад... вперед...потряси ей...', NULL, NULL, 'Станцуйте для хозяйки таверны Салиенны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8358, 'Плата за мармеладки', 'А, тебе нужны сладости? Ну-ну!$B$BЗаруби себе на носу: ты, конечно, занимаешься благородным делом, собираешь сласти для больного ребенка, но без платы ты ничего не получишь! У меня как раз имеется сладкий-пресладкий леденец племени Черного Копья, больная девочка ему будет очень рада... но сначала изобрази-ка ты мне паровозик! То-то я посмеюсь! Посмотри, какой замечательный леденец – а всего-то и надо изобразить паровозик!$B$BНу-ка, $C! Чух-чух-чух-чух!', 'Изобразите паровозик перед Кали Ремик (команда /train) и получите в награду леденец племени Черного Копья!', 'Ту-ту-у! Ну, молодец, $N! Вот твоя конфета.$B$BСчастливого Тыквовина!', 'Ну, поехали...', NULL, NULL, 'Изобразите паровозик перед Ремик', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8359, 'Поиграй мускулами!', 'Ой, какой интересненький костюмчик! Нет, ты, конечно, $gхороший мальчик:хорошая девочка:, собираешь сладости для больного ребенка, но, боюсь, тебе все же придется выполнить для меня какое-нибудь задание, прежде чем ты получишь конфету.$B$BДай-ка подумать... У тебя такой накачанный вид в этом... костюмчике! Вот поиграй-ка мускулами!$B$BА я тебе за это дам вкусной оргриммарской нуги. Дети ее очень любят!', 'Поиграйте мускулами (команда /мускулы) перед хозяйкой таверны Гришкой.', 'О-о, да ты настоящий силач, ха-ха! Молодец, $N! Я ужасно повеселилась. Вот тебе твоя конфета.$B$BВеселого Тыквовина!', 'Не-ет, $N, сначала поиграй мускулами!', NULL, NULL, 'Поиграйте мускулами перед трактирщицей Гришкой', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8360, 'Танец за марципан', 'Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...$B$BДумается, нынче марципановая булочка потянет на... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусненькую марципышечку!', 'Потанцуйте для хозяйки таверны Палы, и за это вы получите марципан Громового Утеса!', 'Да тебе стоило бы в балет податься, Зулалар!$B$BВот твоя награда за чудесное развлечение. Веселого тебе тыквовина, и передай привет больным детишкам! Пусть быстрее поправляются.', 'Ты ведь умеешь танцевать, а? Ну, попытайся – правая нога вперед... затем назад... вперед...потряси ей...', NULL, NULL, 'Станцуйте для хозяйки таверны Палы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8361, 'Связь с Бездной', 'Мы видели, как сектанты проводят ритуалы и вызывают могущественных повелителей стихий. Мы не знаем, поклоняются ли им служители культа или используют как посредников при общении с еще более страшными силами. Ясно одно – они получают приказы от этих элементалей.$B$BОтыщи храмовника Бездны и задай ему хорошую трепку! Стоит лишить войска командира, и в их рядах начинается разброд и шатания. Принеси доказательство своего подвига.', 'Убейте храмовника бездны по поручению Бора Буйногривого из крепости Кенария, что в Силитусе, и принесите в доказательство талисман бездны.', 'Ха! У тебя получилось! Скоро мы одолеем Сумеречный Молот!', 'Тебе удалось выполнить мое поручение?', NULL, NULL, 'Талисман Бездны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8362, 'Талисманы Бездны', '', '', 'Молодец! Меньше храмовников – меньше забот.$B$BВот, возьми, $N. Надеюсь, это тебе пригодится.', NULL, NULL, NULL, 'Талисман Бездны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8363, 'Перстни Бездны', '', '', 'Великолепно, $N! Одолев герцогов, ты нанес серьезный удар Сумеречному Молоту. Вот обещанная награда. Это лучшее из найденного нами с Хуумом.', NULL, NULL, NULL, 'Перстень Бездны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8364, 'Скипетры Бездны', '', '', 'Я знал, что ты справишься, $N! Вот твоя награда.', NULL, NULL, NULL, 'Скипетр Бездны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8365, 'Пиратские шляпы', 'Так это тебя Картель послал к нам на помощь? Пожалуй, ты сойдешь. Слушай внимательно, $C. Ты ведь знаешь, что я законодатель мод Азерота? Короли и королевы, вожди и... как там Орда называет своих королев? Одним словом, все носят, что я укажу. И платят за это бешеные деньги, что особенно приятно.$B$BВ общем, поступим так. Отправляйся в Бухту Сорванных Парусов и раздобудь побольше пиратских шляп. Справишься?', 'Добудьте 20 шляп пиратов Южных Морей и отнесите их Отти Кутюри в Порт Картеля в Танарисе.', 'Ты просто душка, даже если провозился дольше, чем я привыкла. Остается почистить и украсить эти шляпы, и я заработаю кругленькую сумму! Я всегда считала, что за хорошую работу полагается вознаграждение. Вот, возьми. И советую потратить часть на хорошую ванну, солнышко.', 'У тебя на руках все двадцать шляп? Не верю, покажи. И все должны быть в безупречном состоянии!', NULL, NULL, 'Шляпа пирата Южных морей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8366, 'Покажи этим пиратам', 'Они требуют от меня невозможного!$B$BКартель Хитрая Шестеренка хочет, чтобы я преподал пиратам Южных Морей урок. Мне что, разорваться?! Я должен поддерживать здесь порядок.$B$BВ последнее время пираты забыли, что Картель платит им за защиту. Нужно показать им, что к чему.$B$BПираты поселились в Бухте Сорванных Парусов, неподалеку отсюда, на юге. Спасибо, $N. Я твой должник!', 'Начальник отдела безопасности Чепухастер из Порта Картеля в Танарисе просит убить 10 пиратов, 10 флибустьеров, 10 рабочих и 10 сорвиголов Южных морей.', '$N! Да ты просто герой!!!$B$BТеперь-то Картель от меня отстанет, ведь эта шваль получила по заслугам! Так, что бы дать тебе в награду? Пожалуй, немного денег, да еще выбери из этих вещей, что понравится.', 'Уже вернулся? Надеюсь, ты хорошенько проучил эту южноморскую шваль!', NULL, NULL, 'Пират из братства Южных Морей убито', 'Флибустьер из братства Южных Морей убито', 'Портовый рабочий из братства Южных Морей убито', 'Сорвиголова из братства Южных Морей убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8367, 'Великая честь', 'Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.$B$BСтупай же и сокруши противника на всех фронтах. За честь! За Орду!', 'Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.', 'На твою долю выпали непростые испытание, но ты не лишился мужества и сила тебя не покинула. Знаки победы – пустое. Не по ним судят о твоей доблести. Выше голову, $N. Сегодня тебе подобает смотреть на других свысока, ведь ты настоящий герой!', 'Земля в Низине Арати пропитана кровью, а эхо битвы все еще не смолкло в Альтераке. Не теряй попусту мое время, ступай на фронт!', NULL, NULL, 'Почетный знак ущелья Песни Войны', 'Почетный знак Низины Арати', 'Почетный знак Альтеракской долины', 'Почетный знак Ока Бури');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8368, 'Битва за ущелье Песни Войны', 'Битва со Среброкрылыми часовыми за ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.$B$BНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!', 'Принесите 3 почетных знака ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.', 'Великолепно! Ты показал, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.', 'Ты несешь вести из Ущелья Песни Войны?', NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8369, 'Вторжение в Альтеракскую долину', 'Слушай, $N. Что бы ни болтали про битву в Альтеракской долине, правда состоит в следующем: экспедиция клана Грозовой Вершины вторглась в земли клана Северного Волка. В тот день, когда мы позволим Альянсу безнаказанно нарушать наши границы, я повешу секиру на стену и примусь посыпать голову пеплом. Отправляйся и сотри в порошок наглых захватчиков!', 'Принесите 3 почетных знака Альтеракской долины ордынскому вестнику войны рядом со входом на поле боя.', 'Ты встал на защиту наших земель с невиданной храбостью! Я непременно расскажу командующим о твоих подвигах.', 'Что слышно из земель Северного Волка? Как идет битва в Альтеракской долине?', NULL, NULL, 'Почетный знак Альтеракской долины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8370, 'Завоевание Низины Арати', 'Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.$B$BВ низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, $N!', 'Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8371, 'В едином порыве', 'В войне против Орды решающей может оказаться любая битва, $gсынок:дочка:.$B$BПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот - любая проигранная битва может дать нашим врагам преимущество в другой.$B$BАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.', 'Принесите почетные знаки каждого поля боя бригадному генералу Альянса в любую столицу Альянса или в Шаттрат.', 'Да, ты не из тех, кто дает слабину! То, что тебе удалось постичь, не измерить никчемными медалями и наградами. Лишь те, кто тоже прошли сквозь огонь битвы, могут понять, что такое закалка истинного бойца.$B$BТы молодец, $C. Настоящий герой Альянса!', 'Какие вести из дальних стран?', NULL, NULL, 'Почетный знак Альтеракской долины', 'Почетный знак Низины Арати', 'Почетный знак ущелья Песни Войны', 'Почетный знак Ока Бури');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8372, 'Битва за ущелье Песни Войны', 'Среброкрылые часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес. Впрочем, желание сохранить этот лес объсняется не только их любовью к природе.$B$BЭтот лес представляет собой естественную преграду для наступления сил Орды. Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды.$B$BВнеси свой вклад в борьбу со всадниками из клана Песни Войны, $N! За Альянс!', 'Принесите 3 почетных знака ущелья Песни Войны бригадному генералу Альянса рядом со входом на поля боя.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8373, 'Сила сосен', 'Самое гнусное в Тыквовине – это бомбы-вонючки, которые Отрекшиеся бросают на Южнобережье. Кто бы мог подумать, что праздновение свободы требует такой вони?$B$BКогда наступит Тыквовин, убери при помощи этого очистителя любую из мерзких бомб, которые Орда может подкинуть к нам в деревню. Очиститель действует благодаря силе сосен.$B$BПрими участие в поддержании чистоты Южнобережья, и я дам тебе кое-какие тыквовинские вкусности, которым ты несомненно порадуешься. Договорились?', 'Уберите любую бомбу-вонючку Отрекшихся, брошенную в Южнобережье, при помощи очистителя бомб-вонючек. По выполнении задания возвращайтесь к сержанту Хартману.', 'А, воздух стал почище. Немного чище.$B$BСпасибо тебе, $N. Похоже, Южнобережье переживет очередной Тыквовин. Вот твое угощение, спасибо! Если у тебя закончатся конфеты, кажется, в Стальгорне есть гномесса по имени Катрина Мерцанна, которая продает их. Впрочем, кажется только во время Тыквовина.', 'Проклятые Отрекшиеся... Мало того, что они нежить, да еще они устраивают беспорядки в МОЕЙ деревне!', NULL, NULL, 'Убрать бомбу-вонючку, брошенную в Южнобережье!', 'Очиститель бомбы-вонючки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8374, 'Завоевание Низины Арати', 'Чтобы выиграть войну, мало быть быть умнее и хитрее противника. Зачастую победа достается тем, в чьих руках сосредоточены все ресурсы.$B$BРесурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми.$B$BЕсли победа будет за Альянсом, нашим солдатам достанется больше мечей и копий. Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!', 'Принесите 3 почетных знака Низины Арати бригадному генералу Альянса рядом со входом на поля боя.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8375, 'Помни Альтеракскую долину!', 'Не пойми меня превратно, $N. Орда совершенно справедливо считает долину Альтерака территорией клана Северного Волка.$B$BВидишь ли, экспедиция клана Грозовой Вершины прибыла в эти края как мирные исследователи. Они искали руду и древние реликвии, но нашли лишь смерть. Альянс не ожидал такой бессмысленной жестокости даже от клана Северного Волка.$B$BВечная память отважным дворфам, павшим от рук вероломных орков. Ступай, $C, внеси свой вклад в битву за Альтеракскую долину. За Альянс!', 'Принесите 3 почетных знака Альтеракской долины бригадному генералу Альянса рядом со входом на поле боя.', 'Ты исполнил свой долг, $N. Орда заплатит за свое вероломство!', 'Какие вести с фронта, $N?', NULL, NULL, 'Почетный знак Альтеракской долины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8376, 'Оружие войны', '', '', 'Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.Если это... пророчество сбудется…*Геолог Ехидная бледнеет.*Можно считать, что у нас нет будущего.Это оружие понадобится тебе на войне в пустыне.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
