INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8382, 'Оружие войны', '', '', 'Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.Если это... пророчество сбудется…*Геолог Ехидная бледнеет.*Можно считать, что у нас нет будущего.Это оружие понадобится тебе на войне в пустыне.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8383, 'Помни Альтеракскую долину!', '', 'Битва в Альтеракской долине идет, не утихая! Давно ли ты вступал в бой, $N?', 'Ты – гордость Альянса, $N. Если не сдаваться и не отступать, вскоре мы одержим победу над Ордой!', NULL, NULL, NULL, 'Почетный знак Альтеракской долины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8384, 'Завоевание Низины Арати', '', '', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8385, 'В едином порыве', '', '', 'Не зря о тебе так много говорят в последнее время, $N. Не будь в рядах Альянса таких, как ты, нам бы не выстоять против жестоких бойцов Орды.', NULL, NULL, NULL, 'Почетный знак Альтеракской долины', 'Почетный знак Низины Арати', 'Почетный знак ущелья Песни Войны', 'Почетный знак Ока Бури');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8386, 'Битва за ущелье Песни Войны', '', '', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8387, 'Вторжение в Альтеракскую долину', '', 'Битва за Альтерак продолжается! Возвращайся в Альтеракскую долину и выгони наглых захватчиков с исконных земель клана Северного Волка, $N!', 'Отличная работа, $N! Тебе есть, чем гордиться. Еще немного, и мы вышвырнем Альянс из Альтерака!', NULL, NULL, NULL, 'Почетный знак Альтеракской долины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8388, 'Великая честь', '', 'Многие храбрые воины стараются брать с тебя пример, бросаясь в бой против Альянса. Что нового тебе встретилось в странствиях?', 'Твоих подвигов во имя Орды не счесть. Приятно видеть, что твой дух по-прежнему крепок.', NULL, NULL, NULL, 'Почетный знак Альтеракской долины', 'Почетный знак Низины Арати', 'Почетный знак ущелья Песни Войны', 'Почетный знак Ока Бури');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8389, 'Битва за ущелье Песни Войны', '', 'Битва в Ущелье Песни Войны идет, не прекращаясь. Внеси свой вклад в изгнание часовых из клана Среброкрылых с наших земель!', 'Молодчина, $С! Благодаря тебе и таким как ты Орда вернет себе Ущелье Песни Войны!', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
