INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8392, 'Завоевание Низины Арати', '', 'У нас подходят к концу все припасы, $N. Нам не выстоять против Орды, если мы не захватим Низину Арати. Эта низина – настоящая кладовая природы. Ты уже внес свой вклад в борьбу за нее?', 'Отличная работа, $C! Благодаря тебе Альянс сумеет завоевать необходимые ресурсы.', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8393, 'Завоевание Низины Арати', 'Чтобы выиграть войну, мало быть быть умнее и хитрее противника. Зачастую победа достается тем, в чьих руках сосредоточены все ресурсы.$B$BРесурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми.$B$BЕсли победа будет за Альянсом, нашим солдатам достанется больше мечей и копий. Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!', 'Принесите 3 почетных знака Низины Арати бригадному генералу Альянса рядом со входом на поля боя.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
