INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8404, 'Битва за ущелье Песни Войны', '', 'Помни, что битва в Ущелье Песни Войны идет не только за деревья. На самом деле мы сражаемся за сохранение естественной границы между Ясеневым лесом и Степями. Что нового на фронте?', 'Отличная работа, $N. Благодаря тебе, граничный лес Ясеневого леса простоял еще день.', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
