INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8409, 'Поломанные бочки', 'Тухлые яйца успешно подброшены в бочку, и весь эль Южнобережья теперь безнадежно испорчен.$B$BОтправляйтесь назад, к Янке Зовущей Тьму, на фестиваль Плетеного человека на Тирисфальских лугах, и доложите о своем успехе.', 'Вернитесь к Янке Зовущей Тьму на фестиваль Плетеного человека на Тирисфальских лугах.', 'Ха-ха! Вот теперь-то вы продемонстрировали настоящий дух Тыквовина, вернее, дух ОТРЕКШИХСЯ!!!$B$B*Янка Зовущая Тьму смеется и потирает руки.*$B$BЗамечательно, что в Южнобережье теперь будут пить испорченный эль, а то и вовсе никакого. А вы – вот, угощайтесь. Надеюсь, вам все понравится!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8410, 'Покорение стихий', 'Бат\'ра Страж Ветра ищет шамана вроде тебя. Принеси ему по образцу каждой из стихий, чтобы доказать свое мастерство.$B$BБат\'ру можно отыскать на востоке от Мельницы Таррен. Иди вдоль реки на север до руин. Там-то Бат\'ра и разбил лагерь.', 'Соберите образцы воздуха, огня, земли и воды по поручению Бат\'ры Стража Ветра.', 'Отлично, дружище. Теперь поболтаем.', 'Что ты мне принес, $C?', NULL, NULL, 'Первородный воздух', 'Первородный огонь', 'Первородная земля', 'Первородная вода');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8411, 'Покорение Стихий', 'Добро пожаловать, $C. Расклад такой: ты несешь мне стихии и только потом я с тобой говорю.$B$BМне нужны от тебя Огонь, Воздух, Вода и Земля. Только потом я тебе буду доверять, дружище. Надо удостовериться, что ты не совсем дундук.', 'Принесите стихии Земли, Воздуха, Огня и Воды Бат\'ре Стражу Ветра.', '', NULL, NULL, NULL, 'Первородный воздух', 'Первородная земля', 'Первородный огонь', 'Первородная вода');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8412, 'Тотем духов', 'Духи стихий здешних мест меня невзлюбили.$B$BТы знаешь о тотемах больше других, а мне без защитного тотема духов не обойтись. Стихии у нас уже есть, теперь нужно что-то более близкое к природе, первобытное.$B$BВ Западных Чумных землях можно добыть когти медведей и глаза пауков. Падальщики едят и тех, и других, поэтому у них в желудках может быть и то, и другое.', 'Принесите части тотема Духа Бат\'ре Стражу Ветра.', 'Отлично, дружище! Попробуем...', 'Духи знают, что делают, а они пытаются убить меня! Надеюсь, ты несешь мне нужные части.', NULL, NULL, 'Воспаленный паучий глаз', 'Толстый черный коготь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8413, 'Вуду', 'Силы этого тотема духов не достаточно. Нам нужна магия вуду, чтобы сделать верную защиту.$B$BТролли из затонувшего храма делают перья, насыщенные магией вуду. Ступай туда и убей Гашера, Миджана, Золо, Хукку, Зул\'Лора и Лоро. Тогда нам хватит магии на настоящий тотем духов.', 'Принесите вудуистские перья Бат\'ре Стражу Ветра.', 'Пора этому троллю хорошенько вздремнуть! За мной присмотрит тотем духов.$B$BТебе понадобилось много времени, чтобы собрать все части. Ты хочешь что-нибудь за труды?', 'И где перья, дружище?', NULL, NULL, 'Янтарное перо вуду', 'Синее вудуистское перо', 'Зеленое вудуистское перо', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8414, 'Борьба со злом', 'Привет тебе, $C. Отрадно видеть рыцаря вроде тебя в сих безотрадных землях.$B$BМы рассчитваем на твою помощь в борьбе с беконечными полчищами нежити. Собери побольше камней Плети и отнеси их верховному жрецу Тель\'данису. Он охраняет гробницу Утера неподалеку отсюда.$B$BКамни Плети находят лишь те, кто получил Жетон Серебряного Рассвета. Если у тебя нет амулета, поговори с офицером Чистосердой.', 'Принесите 20 камней Плети приспешников верховному жрецу Тель\'данису в Западные Чумные земли.', 'Исцелять камень Плети от зла рискованно, ведь может явиться нежить со всех сторон света. Но ты предан делу Света, и я не боюсь за тебя, $N…', 'Какое зло ты принес мне?', NULL, NULL, 'Камень приспешника Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8415, 'Лагерь Промозглого Ветра', 'Командиру Ашламу Отважному Кулаку нужен паладин, не уступающий тебе честью и доблестью, $N. Командир живет в Лагере Промозглого Ветра в южной части Западных Чумных земель. Найди его и помоги делу Света!', 'Обратитесь к командиру Ашламу Отважному Кулаку в Лагерь Промозглого Ветра.', 'Отлично, $C! Посмотрим, из какого теста ты сделан.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8416, 'Бездействующие камни Плети', 'Камни очищены от зла, $N.$B$BЯ в курсе планов командира Ашлама, и ему понадобится всего лишь один бездействующий камень. Отнеси его, и да сгорит Плеть в праведном огне.', 'Отнесите бездействующий камень командиру Ашламу Неутомимому на Берег Промозглого Ветра.', 'Ты выполнил мой приказ без лишних слов, $N.$B$BПохоже, тебе можно верить. Пожалуй, я поделюсь с тобой своим планом.', 'Удалось ли Тельданису очистить камни Плети?', NULL, NULL, 'Бездействующий камень Плети (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8417, 'Неупокоенный дух', 'По Выжженным землям бродит неупокоенный дух одного из величайших героев Орды. Честь воина прочнее смертного тела, так что тебе не помешает поговорить с ним.', 'Поговорите с павшим героем Орды у входа в Выжженные земли.', 'Итак, ты хочешь избавить меня от боли. Жаль, что меня нельзя просто-напросто зарубить, но к сожалению, не все так просто...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8418, 'Создание камня силы', 'Теперь мы сможем создать оружие против нежити из бездействующих камней Плети. Задание непростое. Магией, способной вынудить зло обратиться против самого себя, владеют лишь тролли из затонувшего храма.$B$BВ храме есть тролли по имени Ранокол, Миджан, Золо, Хукку, Зул\'Лор и Лоро. Не стоит их жалеть... они давно пали и их души запятнаны злом.', 'Добудьте янтарные, синие и зеленые вудуистские перья у троллей из Затонувшего храма.', 'Великолепно. Я сказал бы, что удивлен, но я ни на минуту не сомневался, что ты не подведешь нас.$B$BМне выпала честь вручить тебе один из священных камней силы. Пользуйся им во благо.', 'Тебе удалось убить проклятых троллей?', NULL, NULL, 'Янтарное перо вуду', 'Синее вудуистское перо', 'Зеленое вудуистское перо', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8419, 'Просьба беса', 'С тобой хочет встретиться один бес из Оскверненного леса по имени Бесенок. Это довольно странно, поскольку он попросил тебя принести отрез ткани Скверны в залог доброй воли. Ты весьма $gмогущественный чернокнижник:могущественная чернокнижница: и наверняка знаешь, что ткань Скверны таскают с собой сатиры из Оскверненного леса.$B$BБесенок живет на севере от водопада Отравленной Крови. Говорят, в это время года там очень красиво.', 'Принесите отрез ткани Скверны Бесенку в Оскверненный лес.', 'Ой, спасибо, добренький $C!$B$B*Бесенок подносит ткань к лицу.*$B$BКак мне нравится ее касаться! Она так славно обжигает кожу и внушает злобные мысли...', 'Ты принес мне ткань Скверны?', NULL, NULL, 'Ткань Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8420, 'Пробирает!', 'Может, ты и не $gожидал:ожидала: услышать это от беса, но мне хочется завести питомца. Правда-правда. Это же нечестно – у Ниби есть я, а у меня нет никого!$B$BМне даже не надо живого питомца. Мне нужно что-нибудь, из чего я бы мог его себе сделать – например, ткань Скверны. У сатиров тут, в Оскверненном лесу, ткань Скверны-то имеется, так что просто убивай их, пока не найдешь ткань. Звучит не так уж и ужасно, правда?', 'Принесите отрез ткани Скверны Бесенку в Оскверненный лес.', 'Ого! Добрая ты. Особенно для чернокнижнцы!$B$B*Бесенок прижимает ткань к лицу.*$B$BКак же мне нравится это ощущение, как чудесно пощипывает кожу, и как зло волной проходит по всему нутру...', 'Где моя ткань Скверны?', NULL, NULL, 'Ткань Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8421, 'Бросовый материал', 'Теперь, когда у меня есть ткань Скверны, я могу начать изготовление собственного питомца.$B$BНо ему нужны глазки! Может, сумеешь оторвать кусочек гнилой древесины от железного дерева, и я вырежу из нее прелестные глазки? Деревья эти можно найти в Железнолесье.$B$BА еще мне понадобится немного экстракта Отравленной Крови, чтобы мой питомец приобрел демонический запах. Этот экстракт можно добыть из нечистых слизнюков, а они ошиваются прямо по соседству со мной и Ниби.', 'Принесите 10 кусков гнилой древесины и 4 порции экстракта Отравленной Крови Бесенку в Оскверненный лес.', 'Лучшего и не надо!', 'Ну, все принес?', NULL, NULL, 'Гнилая деревяшка', 'Экстракт Отравленной Крови', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8422, 'Тролли Пера', 'Мой питомец почти готов. Осталось набить его.$B$BТолько вудуистские перья с троллей затонувшего храма помогут делу. Их зовут Ранокол, Миджан, Золо, Хукку, Зул\'Лор и Лоро. Убей их. Перебей их всех! $B$BЭто непростое дело, $N, потому я заплачу тебе за услугу, дав тебе кое-что из барахла Ниби – ему это все равно, наверное, не нужно.', 'Принесите 6 вудуистских перьев троллей из затонувшего храма.', 'Отлично, теперь мой питомец закончен! $B$B*Бесенок быстро набивает куколку и с демонической горячностью обнимает ее.*$B$BОго, какой побочный эффект у этих вудуистских перьев...', 'Ты принес перья? Мою куколку надо набить!', NULL, NULL, 'Янтарное перо вуду', 'Синее вудуистское перо', 'Зеленое вудуистское перо', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8423, 'Воинское испытание', '*Герой окидывает тебя взглядом.*$B$BНет сомнений, ты $C. У меня для тебя есть почетная задача, но сначала необходимо испытать твою силу.$B$BГоворят, что Рексар проверял остроту своих клинков, убивая зловепря одним быстрым ударом. Теперь же я проверю твою силу, отправив тебя на охоту за зловепрями.', 'Убейте 7 зловепрей в Выжженных землях и вернитесь к павшему герою Орды. ', 'Мне не нужны доказательства твоих подвигов, $C. Достаточно того, что я вижу решимость в чертах твоего лица.', NULL, NULL, NULL, 'Зловепрь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8424, 'Война против Приверженцев Тени', 'Постоянное присутствие Приверженцев Тени в Выжженных землях причиняет мне сильную боль. Их темные ритуалы и заклинания вызывают мучения, каких я не ведал при жизни.$B$BЧерез тебя я могу передать мое собственное послание боли. Иди и неси мой гнев.', 'Убейте приверженцев тени в Выжженных землях и вернитесь к павшему герою Орды.', 'Тебе уже удалось умерить мою боль и тем самым почтить меня. Благодарю тебя, $C.', NULL, NULL, NULL, 'Адепт культа Приверженцев Тени убито', 'Сектант Культа Приверженцев Тени убито', 'Лиходей культа Приверженцев Тени убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8425, 'Вудуистские перья', 'Благодаря твоей чести я обрел частицу покоя. Неправильно было бы ничего не предложить взамен.$B$BПри жизни мое оружие и доспехи были великолепны, но теперь они для меня бесполезны. Быть может, тебе они послужат лучше.$B$BОтправляйся к затонувшему храму и уничтожь троллей-охранников Ранокола, Миджана, Золо, Хукку, Зул\'Лора и Лоро. У них хранятся магические перья, которые могут восстановить мое материальное тело на достаточно долгое время, чтобы я мог вручить тебе награду.', 'Принесите вудуистские перья павшему герою Орды, забрав их у троллей в Затонувшем храме.', 'Наконец-то я вновь могу почувствовать холодное прикосновение стали, пусть даже на несколько мгновений.', 'Ты уже назад – так быстро? Для тебя и меня время течет по-разному, быть может, для тебя это и вправду было долгое путешествие...', NULL, NULL, 'Янтарное перо вуду', 'Синее вудуистское перо', 'Зеленое вудуистское перо', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8426, 'Битва за ущелье Песни Войны', 'Битва со Среброкрылыми часовыми за ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.$B$BНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!', 'Принесите 3 почетных знака ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.', 'Великолепно! Ты показал, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.', 'Ты несешь вести из Ущелья Песни Войны?', NULL, NULL, 'Почетный знак ущелья Песни Войны', NULL, NULL, NULL);
