INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8440, 'Завоевание Низины Арати', '', 'Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!', 'Отличная работа, $N! Пока Низина Арати в наших руках, припасов нам хватит.', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8441, 'Завоевание Низины Арати', '', 'Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине сражения. Низина Арати должна отойти к нам!', 'Отличная работа, $N! Пока Низина Арати в наших руках, припасов нам хватит.', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
