INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8443, 'Завоевание Низины Арати', '', 'Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!', 'Отличная работа, $N! Пока Низина Арати в наших руках, припасов нам хватит.', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8446, 'Под покровом кошмара', 'Эта вещь так и сочится порчей.$B$BМожет быть, существует связь между ней и драконами, вылетающими из Сна. Кто-то должен разобраться, что делать с этой штукой. Может, тебе обратиться к друидам с Лунной поляны или из крепости Кенария?', 'Найдите того, кто сможет осознать значение поглощенного кошмарами предмета.Может быть, вам сможет помочь могущественный друид.', 'Я должен очистить этот предмет от скверны. Тогда, быть может, мне удастся понять, почему в последнее время я не могу проникнуть в Сон. Давай.', 'Да, $C?', NULL, NULL, 'Поглощенный кошмарами предмет (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8447, 'Пробуждение легенд', 'Воды озера Элуне\'ара смоют кошмары, поглотившие этот предмет. Это займет совсем немного времени. Подожди, $N.', 'Дождитесь, пока хранитель Ремул с Лунной поляны очистит поглощенный кошмарами предмет.', 'Возьми это кольцо, $N. Оно помогло Малфуриону, а теперь поможет тебе...', NULL, NULL, NULL, 'Пробуждение легенд.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8460, 'Союзник Древобрюхов', 'Фурболги Древобрюхов – единственное фурболгское племя, не затронутое порчей. Однако нынче многие расы без разбору убивают всех фурболгов подряд. И потому фурболгов Древобрюхов осталось так мало.$B$BХочешь заслужить доверие? Изгони из Оскверненного леса пораженных порчей фурболгов Мертвого Леса, и в один прекрасный день мы признаем тебя $gсоюзником:союзницей:. Ты найдешь первое племя Мертвого Леса – воинов, землепроходцев и садовников – к западу от меня.', 'Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу.', 'Мы сильно страдаем от того, что случилось в прошлом. Спасибо за все, что ты сделал для защиты Древобрюхов. И в знак начала нашей дружбы, прими этот скромный подарок.', 'Запомни, $N. Если хочешь заслужить наше доверие, прояви себя.', NULL, NULL, 'Воин из племени Мертвого Леса убито', 'Землепроходец из племени Мертвого Леса убито', 'Садовник из племени Мертвого Леса убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8461, 'Северные фурболги Мертвого Леса', 'Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.$B$BПлемя Мертвого Леса злобное, но это все действие скверны, поразившей их разум. Они враждебны не от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.$B$BПрошу тебя, $N, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.', 'Нафиэн просит вас убить 6 дозорных, 6 мстителей и 6 шаманов из племени Мертвого Леса. По выполнении возвращайтесь на север Оскверненного леса ко входу в крепость Древобрюхов.', 'Чую, что ты вернулся с победой. Победа... какое пустое слово, если подумать о том, что еще надо сделать. Как бы то ни было, ты доказал, что достоин нашего доверия.$B$BНе сразу фурболги Крепости Древобрюхов начнут относиться к тебе без враждебности в этой берлоге. Но твое упорство пробьет стену любой подозрительности, которую мои братья могут питать к тебе. Пока ты не предашь нас и не поднимешь на нас оружия, мы будем находить общий язык.', NULL, NULL, NULL, 'Дозорный из племени Мертвого Леса убито', 'Мститель из племени Мертвого Леса убито', 'Шаман из племени Мертвого Леса убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8462, 'Беседа с Нафиэном', 'Кто знает, может ты справишься с еще более страшной угрозой, что нынче нависла над нами, кланом Древобрюхов. Ты уже $gсумел:сумела: показать здесь свою доблесть...$B$BЕще один мой сородич стоит на страже у входа в Крепость Древобрюхов, по этой дороге дальше к северу. Его зовут Нафиэн. Он может показаться тебе злобной грязной тварью, но ты его не бойся. Он всего лишь ищет помощи против злых сил, что угрожают нашему дому.', 'Отправляйтесь на север по главной дороге в Оскверненном лесу и поговорите с фурболгом по имени Нафиэн. Он стоит на страже у входа в крепость Древобрюхов.', 'Ага... ветер принес мне весть о чужаке не из нашего племени, который ищет союза с фурболгами Крепости Древобрюхов. Добро пожаловать – но знай, мое племя не доверяет чужакам.$B$BВремена сейчас смутные, и мы можем доверять только тем, кто вместе с нами сражается с осквернителями наших краев... тем, кто доказал нам свою верность. А те, кому мы не доверяем, встретят откровенную враждебность, как только войдут в крепость.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8463, 'Нестабильные кристаллы маны', 'Шайка Презренных не так давно похитила из одного из наших волшебных святилищ запас нестабильных кристаллов маны. А эти кристаллы при неправильном обращении могут взрываться с такой силой, что ее хватит, чтобы проломить городскую стену!$B$BТак вот, $N, меня не волнует, если эти кристаллы взорвутся у них - пусть хоть все повзрываются, - но этот эпизод выставляет моих подчиненных не в лучшем свете!$B$BПринеси мне все оставшиеся похищенные кристаллы, сколько найдешь - возможно, они до сих пор в своей упаковке.', 'Верните 6 нестабильных кристаллов маны Аэльдону Озаренному Солнцем на площади Соколиных Крыльев.', 'Отличная работа, $N!', 'Ну что, удалось тебе отыскать похищенное?', NULL, NULL, 'Нестабильный кристалл маны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8464, 'Боевые действия в деревне Зимней Спячки', 'Клан Древобрюхов готов постоять за себя, $N. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. $B$BПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. $B$BЯ вынужден просить вас пробить брешь в их рядах для уменьшения угрозы для нас. Ищите их в деревне Зимней Спячки далеко на восток отсюда.', 'Убейте 8 шаманов, 8 дозорных и 8 ведмедей из племени Зимней Спячки по просьбе Сальфы. Он ждет у входа в Крепость Древобрюхов в Зимних Ключах.', 'Спасибо за то, что вы сделали, как ни печально все это. Примите это в качестве знака нашей благодарности. $B$BЯ бы очень просил вас не прекращать оказывать нам помощь, $N. У нас слишком мало союзников, которых мы можем призвать, и без вашей помощи опасность для моего племени была бы слишком велика, чтобы мы могли справиться с нею в одиночку.', NULL, NULL, NULL, 'Шаман из племени Зимней Спячки убито', 'Дозорный из племени Зимней Спячки убито', 'Ведмедь из племени Зимней Спячки убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8465, 'Разговор с Сальфой', 'Порча расползается не только от фурболгов Мертвого Леса с юга, но и с востока, от фурболгов из племени Зимней Спячки, что в Зимних Ключах. Если хочешь еще нам помочь, поговори с Сальфой по другую сторону берлоги, у входа в Зимние Ключи. Иди туда по левой тропке.$B$BОсторожнее – если мои тамошние сородичи сочтут, что ты – недобрый гость или ненавистный враг, они на тебя нападут. Иди так быстро, как можешь, чтобы избежать стычки. Убьешь кого из Древобрюхов, пусть даже защищаясь – вызовешь еще большую враждебность.', 'Пройдите через Крепость Древобрюхов и выйдите к Зимним Ключам. Поговорите с Сальфой, который стоит на страже у входа в Крепость Древобрюхов.', 'Привет тебе, $C – я тут и страж, и глашатай Древобрюхов в Зимних Ключах, и защитник моего племени.$B$BНаши сородичи из племени Зимней Спячки в этой холодной земле подпали под ту же власть порчи, что и фурболги Оскверненного леса. Если ты пришел помочь фурболгам из крепости Древобрюхов, то мы рады принять твое предложение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8466, 'Перья для Гразла', '', '', 'Хорошая работа, $N! Я уж постараюсь, чтобы мои сородичи узнали о твоих делах.$B$BНе забывай приносить мне все перья, что добудешь. Я возьму все, сколько принесешь.', NULL, NULL, NULL, 'Перо из головного убора Мертвого Леса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8467, 'Перья для Нафиэна', '', '', 'Хорошая работа, $N! Я уж постараюсь, чтобы мои сородичи узнали о твоих делах.$B$BНе забывай приносить мне все перья, что добудешь. Я возьму все, сколько принесешь.', NULL, NULL, NULL, 'Перо из головного убора Мертвого Леса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8468, 'Разыскивается: Таэлис Ненасытный', 'Город Луносвет назначает награду за голову Таэлиса Ненасытного, известного главаря Презренных. Он разыскивается за то, что неоднократно совершал преступления против жителей Луносвета, в том числе убил двух городских стражников.$B$BОтносительно награды обращайтесь к сержанту Ка\'рену.', 'Принесите голову Таэлиса сержанту Ка\'рену на площадь Соколиных Крыльев в лесах Вечной Песни.', 'Наконец-то этот негодяй, Таэлис, получил по заслугам! Молодец, $N. Теперь-то Презренные присмиреют хотя бы на время!', 'Ты хочешь мне что-то показать?', NULL, NULL, 'Голова Таэлиса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8469, 'Бусы для Сальфы', '', '', 'Ты снова доказал свою доблесть! Я позабочусь о том, чтобы о твоих деяниях узнало все наше племя.$B$BНе забывай приносить мне бусы Зимней Спячки. О каждом твоем успехе я расскажу своим сородичам.', NULL, NULL, NULL, 'Бусы духов Зимней Спячки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8470, 'Ритуальный тотем Мертвого Леса', 'Вы нашли один из ритуальных тотемов фурболгов клана Мертвого Леса. Сам тотем совершенно неописуемой конструкции, и от него исходит ощутимое чувство отчаяния. Если есть предмет, который мог бы стать олицетворением порчи, снедающей фурболгов Мертвого Леса – то вот он.$B$BОдин из фурболгов в крепости Древобрюхов мог бы найти применение этому предмету... конечно, если вы уже добились достаточного доверия от них, чтобы они снизошли до разговора с вами.', 'Отнесите ритуальный тотем Мертвого Леса в Крепость Древобрюхов и посмотрите, не пригодится ли этот предмет кому из тамошних фурболгов. Фурболги Крепости Древобрюхов не станут говорить с вами – разве что их отношение к вам нейтральное или лучше.', 'Тотем... похоже, один из мертволесских, но от него прямо несет разложением. В этом предмете явственно ощущается то, что обратило наших собратьев против нас.$B$BТы мудро поступил, принеся его нам, $N. Возможно, изучив его и проведя обряды, мы сможем узнать, что отравило разум наших сородичей. Благодарю тебя, друг, – прими эти дары в благодарность за твою находку.', 'Да, $C, чем могу тебе помочь? Ты ходишь среди нас беспечно, хотя это не слишком-то правильно. Я чую что-то... что-то тревожное...', NULL, NULL, 'Ритуальный тотем Мертвого Леса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8471, 'Ритуальный тотем Зимней Спячки', 'Вы нашли один из ритуальных тотемов Зимней Спячки. Сам тотем представляет собой неописуемую конструкцию, которая испускает почти осязаемые волны страха и отчаяния. Если такую вещь носят все фурболги, то понятно, что довело их до такого состояния.$B$BКто-нибудь из фурболгов логова Древобрюхов наверняка разберется с этой вещью... однако фурболги будут говорить только с теми, кому достаточно доверяют.', 'Отнесите ритуальный тотем Зимней Спячки в берлогу Древобрюхов и отдайте его фурболгу, который им заинтересуется. Никто из племени Древобрюхов не заговорит с вами, пока вы не завоюете себе среди них достойную репутацию.', 'Эта вещь... она имеет форму ритуального тотема Зимней Спячки, однако этот тотем был испорчен непостижимыми для меня силами. Так или иначе, в нем присутсвует именно та энергия, которая заставила племя Зимней Спячки обратиться против нас.$B$BС твоей стороны было очень мудро принести его нам, $N. Мы тщательно его изучим и, будем надеяться, найдем способ исцелить наших собратьев.$B$BМы благодарны тебе, и просим тебя принять это за твои услуги.', 'Охотник – ты пришел к нам с миром, но я вижу, что у тебя очень важная цель. Важная не только для фурболгов, но и для твоих соплеменников, $R. О чем ты хочешь нам поведать?', NULL, NULL, 'Ритуальный тотем Зимней Спячки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8472, 'Серьезная неполадка', 'Волшебные часовые, которых наши предки изготовили, чтобы охранять город, в последнее время пришли в полную негодность. Они уже не признают в нас своих хозяев и нападают, как только увидят!$B$BОни созданы много лет назад, но волшебные сердечники, на которых они работают, все еще вполне пригодны. Собери эти сердечники и принеси мне, чтобы я мог пустить их в дело. Часовые бродят по разрушенным кварталам Луносвета, на северо-западе.', 'Соберите 6 волшебных сердечников с волшебных часовых, которые бродят по руинам Луносвета, и принесите их магистру Джаронису на площадь Соколиных Крыльев в лесах Вечной Песни.', 'Молодец, $N! Теперь, когда наши волшебные святилища не работают в полную силу, эти энергетические сердечники очень сильно поспособствуют решению наших проблем.', 'Ну что, $N, удалось тебе собрать волшебные сердечники?', NULL, NULL, 'Волшебный сердечник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8473, 'Печальное задание', 'Трудные ныне времена, $N. Очень не хотелось нам сжигать леса вдоль границы Призрачных земель, но иначе никак не удавалось предотвратить распространение Плети.$B$BА вот теперь древни, которые в течение многих лет были нашими друзьями, пытаются восстановить леса вдоль Выжженной рощи.$B$BНам так и не удалось убедить наших бывших союзников прекратить эти попытки. Мне очень горько тебя об этом просить, $C, но тебе придется пустить в ход единственное оставшееся у нас средство – силу.', 'Убейте 10 высохших хранителей лесов в Выжженной роще. Вернитесь к Ларанне Речной Ветер в башне к северо-западу от Выжженной рощи в лесах Вечной Песни.', 'Значит, дело сделано... Будь прокляты эти времена, вынудившие нас пойти на крайние меры... и будь проклята Плеть!$B$BЗапомни, $N: мы должны защищать свои земли во что бы то ни стало! И мы победим!', 'Даже боюсь спрашивать, $N... задание выполнено?', NULL, NULL, 'Высохший хранитель лесов убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8474, 'Подвеска Старого Белоствола', 'На подвеске выгравированы инициалы: ЛРВ. Возможно, они помогут вам найти создателя подвески...', 'Отыщите того, кто мог изготовить подвеску Старого Белоствола. Возможно, он подскажет, что это за предмет?', 'О-о... эта подвеска... Я подарила ее Старому Белостволу, после того как его народ помог нам отстроить нашу деревню.$B$BБоюсь, это означает, что он...$B$B*Эльфийка откашливается и берет себя в руки.*$B$BСпасибо, что принес мне эту вещь, $N. Я хотела бы попросить тебя об одной услуге...', 'Ты хочешь мне что-то показать?', NULL, NULL, 'Подвеска Старого Белоствола (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8475, 'Тропа Мертвых', 'Полоса выжженной земли, которая тянется через леса Вечной Песни, как постоянное напоминание о том дне, когда Артас привел Плеть в наш возлюбленный город...$B$BЭто хуже, чем бельмо на глазу: даже теперь по ней в Луносвет приходят прислужники Плети из Призрачных земель.$B$BСтупай, $N, и помоги моим воинам убивать лишенную разума нежить, которая приходит Тропой Мертвых.', 'Убейте 8 чумных мародеров и вернитесь к следопыту Джеле на Тропе Мертвых в лесах Вечной Песни.', 'Разумеется, Плеть еще нескоро отступится от нас, но все же оборонять Тропу Мертвых необходимо, и мы благодарны за любую помощь!', NULL, NULL, NULL, 'Чумной мародер убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8476, 'Угроза Амани', 'Наши владения – это не обширные королевства людей или орков. То, что ты видишь перед собой, $N, – это, считай, и есть все земли, что принадлежат нам на Азероте.$B$BИ пока мы не сумеем добраться до Запределья, мы должны любой ценой защищать то немногое, что имеем.$B$BОднако у наших нецивилизованных соседей на юго-востоке, троллей из племени Амани, явно имеется свое мнение насчет того, кому принадлежат эти земли. Мы больше не можем терпеть их ежедневные набеги! Отправляйся в их поселения, Зеб\'Вату и Тор\'Вату, и научи их уму-разуму!', 'Убейте 5 аманийских берсерков и 5 аманийских метателей топоров по просьбе лейтенанта Вестницы Зари из обители Странников, что в лесах Вечной Песни.', 'Молодец, $N! Чем больше у нас будет таких, как ты, то тем быстрее мы вернем нашим землям прежнее великолепие.', NULL, NULL, NULL, 'Аманийский берсерк убито', 'Метатель топоров из племени Амани убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8477, 'Молот копьедела', 'Между троллями Амани и син\'дорай существует многовековая неприязнь и открытая вражда. Однако же это не мешает мне оценить работу коллеги-оружейника, $N.$B$BМне уже попадались изделия троллей Амани, и должна признаться, что это очень качественные вещи. Ходят слухи, что Отембе Создатель Копий владеет волшебным молотом, таким легким и хорошо уравновешенным, что он позволяет работать очень ловко и эффективно.$B$BЕсли ты принесешь мне этот инструмент, я сделаю тебе оружие.', 'Найдите в Тор\'Вате к юго-востоку от обители Странников копьедела Отембе и принесите его молот Аратель Кузне Солнца в обитель Странников, что в лесах Вечной Песни.', 'Да, $N, слухи не лгали! Этот молот - легкий, и в то же время мощный. Теперь я смогу завершить несколько начатых и не оконченных мною вещей! И, разумеется, первая же из них - твоя!', 'Ну что, $N, ты принес мне молот Отембе?', NULL, NULL, 'Молот Отембе', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8479, 'Зул\'Марош', 'Поди-ка поближе. Да не боись, не укусит тебя Вень\'яши!$B$BМы, тролли из племени Черного Копья – смертельные враги Амани, как и ваш народ. Их старшой, Зул\'Марош – очень злой тролль. Он отравил меня и оставил подыхать в этой клетке.$B$BСмерти я не боюсь, нет. Я смотрел смерти в глаза, и смеюсь над нею!$B$BНо я не смогу умереть спокойно. Пусть Зул\'Марош тоже умрет! Он там, за озером, в Зеб\'Вате. Я буду сопротивляться яду, пока ты не принесешь мне его башку!', 'Принесите Вень\'яши, пленному троллю в Тор\'Вате, голову вождя Зул\'Мароша. Вождя можно найти в Зеб\'Вате, за озером Элрендар.', 'О да! Наконец-то Зул\'Марош получил по заслугам! Он сжег деревню Вень\'яши. Я убил много Амани, прежде чем меня затолкали в эту клетку! Я спрятал кое-что в песке – это будет мой дар тебе.$B$BОх... яд расходится по жилам... Пора мне помирать...', 'Ну что, принес голову Зул\'Мароша?', NULL, NULL, 'Голова вождя Зул\'Мароша', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8480, 'Потерянное оружие', 'Презренные смелеют с каждым днем, $N! Они уже расхрабрились настолько, что захватили причал Солнечного Паруса!$B$BА что самое неприятное - когда нас атаковали, нам пришлось оставить там большую часть нашего оружия. Добудь же его, чтобы мы могли показать этим подонкам, кто здесь хозяин!', 'Принесите 8 комплектов оружия син\'дорай Велендрису Белому Рассвету в лесах Вечной Песни.', 'Отлично, $N! Зададим жару этим Презренным!', 'Ну что, тебе удалось собрать потерянное оружие?', NULL, NULL, 'Оружие син\'дорай', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8481, 'Корень всех зол', '$N, спасибо тебе за то, что $gнашел:нашла: способ вырвать корень зла из душ племени Зимней Спячки – уничтожить демона, овладевшего ими!$B$BОтнеси этот факел к входу в пещеру верховного вождя племени Зимней Спячки и поставь его там. Это заставит демона появиться. Вот тогда ты со своими союзниками нападешь на него! Только сущность погибшего демона поможет начать долгий процесс исцеления племени Зимней Спячки... и спасения Крепости Древобрюхов.', 'Установите факел призыва демона у входа в пещеру верховного вождя племени Зимней Спячки в деревне фурболгов Зимней Спячки. Сразите демона и добудьте сущность Зандивиуса для Горна Одноглаза из Крепости Древобрюхов.', '', NULL, NULL, NULL, 'Факел вызова демонов (Прилагается)', 'Сущность Зандивиуса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8482, 'Обличающие документы', 'В документах содержатся подробные карты стратегически важных объектов в лесах Вечной Песни. Прилагается также план волшебного святилища. Кроме того, присутствует множество заметок на неизвестном вам языке.$B$BПоскольку все эти документы вы нашли у дарнасского шпиона, пожалуй, стоит отнести их капитану стражи – Аэльдону Озаренному Солнцем.', 'Отнесите обличающие документы Аэльдону Озаренному Солнцем на площадь Соколиных Крыльев в лесах Вечной Песни.', 'Все это было у ночного эльфа? Точно? Язык-то явно дворфийский...$B$BНасколько я понимаю из письма, тот, кто его написал, не сам устроил аварию, но был прислан сюда, чтобы понаблюдать за ее результатами. Тут сказано, что наша работа опасна и безрассудна... но кто же это?$B$BНу разумеется! Тот посланец из Стальгорна! Глупо было доверяться тому, кто служит Альянсу.', 'Ты мне что-то принес? Дай-ка взглянуть...', NULL, NULL, 'Обличающие документы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8483, 'Дворфийский шпион', 'Слушай, $N. Ситуация очень деликатная. Мы вычислили шпиона, но убить его открыто не можем. Не можем мы и попытаться его схватить - слишком велик риск, что уйдет.$B$BПрошу тебя: пойди в Северное святилище, найди там геолога Стража Наковальни и убей его. Только тихо: мы не хотим, чтобы пошли разговоры, что мы допустили в свой город шпиона.$B$BПринеси мне в доказательство его голову. Пусть стальгорнцы знают, что к син\'дорай соваться опасно.', 'Принесите голову геолога Стража Наковальни Аэльдону Озаренному Солнцем на площадь Соколиных Крыльев в лесах Вечной Песни.', 'Ага, дело сделано! Отличная работа.$B$BПредводителю следопытов уже обо всем сообщили - поверь мне, дворфы дорого заплатят за предательство.$B$BСегодня ты оказал большую услугу своему народу, $N!', 'Ну что, удалось тебе разобраться с этим прохвостом?', NULL, NULL, 'Голова геолога Стража Наковальни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8484, 'Знак мира', 'Твои подвиги выше любых похвал, $N. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.$B$BПрошу – отнеси этот дар королю дворфов, что живет в железной горе – вроде бы вы зовете этот город Стальгорном. В былые времена он пытался заключить с нами союз от имени Альянса. Так что теперь достойно будет, чтобы ты $gзавершил:завершила: труды Альянса по установлению мира с нами.', 'Отнесите мирное приношение Древобрюхов королю Магни Бронзобороду в Стальгорн.', '', NULL, NULL, NULL, 'Мирное приношение Древобрюхов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8485, 'Знак мира', 'Твои подвиги выше любых похвал, $N. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.$B$BПрошу – отнеси этот дар вождю орков, что живет в Дуротаре. Кажется, вы называете его город Оргриммаром. В былые времена он пытался заключить с нами союз от имени Орды. Так что теперь достойно будет, чтобы ты $gзавершил:завершила: труды Орды по установлению мира с нами.', 'Отнесите мирное приношение Древобрюхов Траллу в Оргриммар.', '', NULL, NULL, NULL, 'Мирное приношение Древобрюхов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8486, 'Магическая нестабильность', 'Ну наконец-то этот олух Кайданис прислал хоть кого-то!$B$BЯ предупреждала о том, как опасно перегружать Западное святилище! И вот теперь один из энергетических конвертеров уничтожен, а из святилища лезут чародейские призраки!$B$BМне нужна твоя помощь, чтобы разобраться с этими существами, прежде чем мы отправим туда ремонтников. Времени в обрез!', 'Убейте 5 магических призраков и 5 волшебных охотников по просьбе хранительницы энергии Велании.', 'Спасибо, $N. Теперь, когда ситуация под контролем, можно отправить туда рабочих и все наладить. Надеюсь, там ничего серьезного...', NULL, NULL, NULL, 'Магический призрак убито', 'Волшебный охотник убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8487, 'Зараженная почва', 'Пока Артас и его армия Плети не проложили здесь свой гибельный путь к Луносвету, это было действующее волшебное святилище.$B$BА теперь от него не больше проку, чем от любой другой части Тропы Мертвых. Почва заражена, это место кишит нежитью, энергия силовых линий полностью искажена.$B$BИ теперь я хочу знать, $N, обратимо ли это искажение или нет. Собери образцы почвы, чтобы я могла изучить их. Возможно, со временем мы сумеем все исправить?', 'Соберите 8 проб зараженной земли для ученицы Мирведы в Восточном святилище, что в лесах Вечной Песни.', 'Отлично! Я обработаю эти образцы заклятием усиления, чтобы мне было удобнее исследовать порчу.', 'Ну что, $N, готовы ли образцы, которые я просила?', NULL, NULL, 'Проба зараженной земли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8488, 'Неожиданный результат', 'Что-то не так, $N. Я чувствую присутствие Плети! Готовься сражаться!', 'Защитите ученицу Мирведу от Плети, напавшей из засады.', 'Нет, $N, мои надежды тщетны... Сама природа этой почвы изменилась. Спасибо тебе за помощь. Напоследок окажи мне, пожалуйста, еще одну услугу.', NULL, NULL, NULL, 'Защитите ученицу Мирведу', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8489, 'Невредимый преобразователь', 'Кажется, перед вами один из чародейских преобразователей, о которых говорила хранительница энергии Велания. Огонь его не коснулся, так что он может ей пригодиться.', 'Принесите хранительнице энергии Велании невредимый чародейский преобразователь.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8490, 'Усиление обороны', 'Некогда древние рунические камни поддерживали защитный барьер вдоль границ лесов Вечной Песни. Многие из них были уничтожены во время нападения Артаса, а некоторые были похищены.$B$BИз трех оставшихся лишь один сохранил прежнюю мощь. Но возможно, тот рунический камень, что на востоке, тоже можно спасти.$B$BВот, возьми этот кристалл и влей его энергию в восточный рунический камень. Это займет не более минуты. Однако берегись: находящиеся поблизости твари Плети попытаются уничтожить камень. Этого нельзя допустить!', 'Установите заряженный кристалл рядом с восточным руническим камнем и в течение одной минуты обороняйте его от нежити. Затем верните кристалл хранителю рун Дериану в лесах Вечной Песни и получите награду.', 'Отлично! Значит, наша оборона от Плети продержится еще немного. Спасибо тебе за помощь, $N!', 'Ну что, $N, удалось ли тебе зарядить рунный камень?', NULL, NULL, 'Рунический камень заряжен', 'Заряженный кристалл (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8491, 'Добывание шкур', 'Прыголапы, которые водятся в здешних краях, славятся своими превосходными шкурами. Порой даже эти мошенники, ночные эльфы, забредают к нам, чтобы побраконьерствовать.$B$BИз-за стычек с троллями из племени Амани все наши припасы иссякли, и нашим следопытам не до охоты. Если ты согласишься помочь нам добыть шкуры прыголапов, я вознагражу тебя надежными доспехами. Прыголапов-охотников легко встретить в лесах к северу отсюда.', 'Принесите 6 шкур прыголапов Велану Светлому Тополю из деревни Легкий Ветерок, что в лесах Вечной Песни.', 'Отлично, $N! Вот, возьми в награду эту часть доспеха. Из доставленных тобою шкур я смогу сделать еще.', 'О, ты уже здесь! А где шкуры?', NULL, NULL, 'Шкура прыголапа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8492, 'Альянсу не хватает медных слитков!', 'Здорово, $C! На вид ты вполне $gпригоден:пригодна: к тому, чтобы принять участие в подготовке к войне! Нам пригодится любая помощь, так что наступил твой звездный час.$B$BЯ собираю медные слитки стопками по двадцать штук. Дело благое, да? Ты как, хочешь оказать помощь Альянсу?', 'Принесите 20 медных слитков сержанту Камнелобу в Палаты войны Стальгорна.', 'Похвально, солдат! Сейчас мы уложим эти слитки в штабель и используем их по назначению. Альянс будет гордиться тобой. $B$BЕсли раздобудешь еще стопку медных слитков, не раздумывай, неси мне.', 'Ну что, солдат, удалось собрать 20 медных слитков?', NULL, NULL, 'Медный слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8493, 'Альянсу все еще не хватает медных слитков!', 'Ты $gвернулся:вернулась:, $C? Превосходно! Для подготовки к войне в Ан\'Кираже все еще нужны медные слитки. Ты поможешь нам собрать их?', 'Принесите 20 медных слитков сержанту Каменлобу в Военный двор Стальгорна.', 'Прекрасная работа! Добыча и выплавка всей этой меди, должно быть, была тем еще развлечением. Если, конечно, ты не купил слитки на аукционе. В любом случае, главное – результат. Приложенные тобой усилия не останутся незамеченными, $С. Если раздобудешь еще слитки, без малейшего колебания неси их мне.', 'Ты уже вернулся, $C? Превосходно! Слитки, которые тебе удалось достать, сослужат нам добрую службу. Я могу сказать со всей ответственностью, что медь пойдет на изготовление паровых танков, а так же вертолетов и прочей военной техники.$B$BИ пусть эти штабеля меди не смущают твой взгляд, к сожалению, их пока недостаточно, чтобы подготовится к войне в Ан\'Кираже как следует. Но ведь мы еще можем рассчитывать на твою помощь?', NULL, NULL, 'Медный слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8494, 'Альянсу не хватает железных слитков!', 'Эгей, $gмистер:мисс.: Красивые Штанишки, ты прямо отрада для моих измученных глаз. Пока ты $gшатался:шаталась: по городам и весям в поисках приключений, у нас тут произошла прорва всего. К примеру, Альянс вот готовится к войне в Ан\'Кираже, и всем резко понадобились железные слитки... чертова прорва железных слитков. Можешь таскать их мне стопками по двадцать. Ну как, могу я на тебя рассчитывать, $C?', 'Принесите 20 железных слитков капралу Карнсу в Палаты войны Стальгорна.', 'Ну хорошо, $N, на этот раз тебе удалось вывернуться. Пожалуй, на будущее за тобой стоит приглядывать. Как ни тяжело это говорить, но спасибо тебе за помощь. Альянс тебя не забудет, и я тоже. А теперь дуй-ка отсюда и лучше помоги еще кому-нибудь в заготовках.', 'Если эти двадцать железных слитков у тебя с собой, даже не рассказывай мне, куда ты умудрился их запрятать.', NULL, NULL, 'Железный слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8495, 'Альянсу по-прежнему не хватает железных слитков!', 'Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, $C, а то я прямо таять начинаю. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул\'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.', 'Принесите 20 железных слитков капралу Карнсу на аэродром в Дун Морог.', 'Должно быть, в Пылающих Степях выпал снег. Вы только посмотрите, это же $N, да не просто так, а с подарком. Двадцать железных слитков! Именно то, что мне нужно. $B$BХочу сказать тебе со всей серьезностью, $N, Альянс перед тобой в долгу. А теперь давай, шлепай отсюда и помоги еще кому-нибудь в заготовках.', 'Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, $C, а то я буквально таю изнутри. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул\'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.', NULL, NULL, 'Железный слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8496, 'Запас бинтов', 'В последнее время мы понесли серьезные потери, и запас бинтов стремительно иссякает. Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордый Рог в крепость Кенария.', 'Принесите 30 плотных бинтов из рунической ткани, 30 плотных шелковых бинтов и 30 плотных бинтов из магической ткани призывательнице ветров Гордый Рог в крепость Кенария в Силитусе. Кроме того сдайте тыловую задачу X.', 'Ты как раз вовремя. Принесенные тобой перевязочные материалы спасут немало жизней. Мы благодарны тебе за труды. Вот твое следующее задание.', 'Что ты мне принес, $N?', NULL, NULL, 'Плотные бинты из рунической ткани', 'Плотные бинты из магической ткани', 'Плотные шелковые бинты', 'Краткий обзор задач перевозок X (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8497, 'Неприкосновенный запас', 'В крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания в пустыне и отнеси их Каландрате в крепость Кенария.', 'Принесите 4 сферы воды, 4 мощных противоядия и 4 копченые пустынные клецки Каландрате в таверну в крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу I.', 'Отлично! Нам очень нужны эти материалы. Спасибо.', 'Что ты мне принес, $N?', NULL, NULL, 'Магическая сфера воды', 'Мощное противоядие', 'Копченые пустынные клецки', 'Краткий обзор задач перевозок I (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8498, 'Боевые приказы Сумеречного Молота', 'Разведчики донесли, что от предводителей Сумеречного Молота поступили новые приказы. Их распространяют пророки под охраной солдат. Перехвати эти приказы и принеси их командору Мар\'алиту.', 'Добудьте боевые приказы Сумеречного Молота и отнесите их командору Мар\'алиту в крепость Кенария в Силитусе. Для завершения задания понадобится тактическая задача X.', 'Великолепно. Главное – опережать противника на ход. Благодаря полученным сведениям, нам известны намерения Сумеречного Молота.', 'Что ты мне принес, $N?', NULL, NULL, 'Боевые приказы Сумеречного Молота', 'Краткое изложение тактической задачи X (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8499, 'Альянсу не хватает ториевых слитков!', 'Крайне любезно с твоей стороны, что ты так беспокоишься о нуждах Альянса. Приготовления к войне идут полным ходом, и, помимо всего прочего, нам нужно очень много ториевых слитков. Именно за их сбор я и отвечаю. Торий необходим для изготовления различных военных машин, в основном паровых танков, которые планируется доставлять по воздуху в Силитус сразу же после сборки. За помощь в добыче ториевых слитков я была бы очень признательна, $C.', 'Принесите 20 ториевых слитков госпоже Двукоссе в Палаты войны Стальгорна.', 'О, спасибо тебе, $C! Огромное спасибо! Прибавилось еще двадцать, осталось собрать еще несчетное количество. Альянс пред тобой в долгу. Если раздобудешь еще двадцать слитков, обращайся ко мне.', 'Я надеюсь, тебе удалось собрать необходимое количество ториевых слитков?', NULL, NULL, 'Ториевый слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8500, 'Альянсу по-прежнему не хватает ториевых слитков!', 'Добро пожаловать снова, $N. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.', 'Принесите 20 ториевых слитков госпоже Двукоссе на аэродром в Дун Морог.', 'Отличная работа, $C! Я прослежу, чтобы ториевые слитки были хорошо упакованы и доставлены кузнецам и инженерам, которые изготавливают для нашей армии военную технику. Спасибо тебе еще раз. Если сможешь достать еще двадцать слитков, я приму их у тебя с благодарностью.', 'Добро пожаловать снова, Хэллпер. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.', NULL, NULL, 'Ториевый слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8501, 'Цель: острожалы из улья Аши', 'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут летающие острожалы из этого улья.$B$BВыполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 острожалов из улья Аши и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XII.', 'Отличная работа, $N. Твои подвиги в сражении при Улье Аши не прошли незамеченными.', 'О чем ты хочешь рассказать, $N?', NULL, NULL, 'Острожал из улья Аши убито', 'Изложение боевой задачи XII (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8502, 'Цель: рабочие из улья Аши', 'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут рабочие из этого улья.$B$BВыполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 рабочих из улья Аши и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу III.', 'Отличная работа, $N. Без рабочих силитидам придется нелегко. Кто будет восстанавливать их ульи?', 'Ты хочешь что-то сказать, $C?', NULL, NULL, 'Рабочий из улья Аши убито', 'Изложение боевой задачи III (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8503, 'Альянсу не хватает удавника!', 'Знаешь ли ты, $C, насколько широко и разнообразно применение удавника? Как, я тебе уже об этом рассказывал? Правда?.. Ну ладно. В любом случае, нам нужно много этой травы, и когда я говорю так, я имею в виду действительно МНОГО! Не следует ли тебе помочь нам, как ты считаешь? Я понимаю, это означает, что тебе придется остаться без всех этих чудесных штучек, которые можно приготовить из удавника... но ведь это ради благого дела!', 'Принесите 20 стеблей удавника рядовому Драксельмеру в Палаты войны Стальгорна.', 'Урра! Еще двадцатью меньше собирать. Отлично справляешься с работой! Пойду уберу травы, пока они не засохли. Времени так мало, а удавника так много!$B$BСпасибо еще раз, $С!', 'Это грязный поклеп! Я не брал отсюда ни одной травинки! Хотя соблазн очень велик... ведь это ж практически настоящая панацея от утилитарной бесполезности. *кашляет* Да, кстати, как там насчет удавника, который ты должен был принести мне?', NULL, NULL, 'Удавник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8504, 'Альянсу по-прежнему не хватает удавника!', 'Эй, ты там... Ой... Что это было? Ах, да, $N! $gЗашел:Зашла: поинтересоваться, не нужно ли мне еще удавника? О, тебе крупно повезло, потому что ответ на этот жизненно важный вопрос – конечно, ДА! Ну как, соберешь еще двадцать штук?', 'Принесите 20 стеблей удавника рядовому Драксельмеру на аэродром в Дун Морог.', 'О мой бог, сколько у тебя тут удавника! Давай-ка по-быстрому упакуем его в коробку, чтобы не испортился. Ты оказал мне... то есть, я хотел сказать, нам, Альянсу, угромную услугу! Я приложу все усилия, чтобы все узнали, что это великий $N внес неоценимый вклад в подготовку к киражской войне, пожертвовав столько удавника!', 'Эй, ты там... Ой... Что это было? Ах, да, $N! Зашел поинтересоваться, не нужно ли мне еще удавника? О, тебе крупно повезло, потому что ответ на этот жизненно важный вопрос – конечно, ДА! Ну как, соберешь еще двадцать штук?', NULL, NULL, 'Удавник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8505, 'Альянсу не хватает лилового лотоса!', '$С, цветы лилового лотоса где только не применяют. От имени Альянса я отвечаю за заготовку лотоса в количестве, достаточном для удовлетворения всех военных нужд.$B$BНо чтобы собирать цветы, мне нужны добровольцы. Справишься с этим заданием?', 'Принесите 20 цветков лилового лотоса мастеру Ночной Песне в Палаты войны Стальгорна.', 'Твой вклад очень ценен для всех нас, $С. Только объединив наши усилия, мы сможем отбросить армию безжалостных силитидов и одержать победу. Даже Орда занимается сбором лилового лотоса. Если снова наберешь этих цветов, возвращайся ко мне.', 'Тебе удалось собрать цветы лилового лотоса?', NULL, NULL, 'Лиловый лотос', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8506, 'Альянсу по-прежнему не хватает лилового лотоса!', 'Добро пожаловать обратно, $C. Наши запасы лилового лотоса растут, но нам все равно нужно еще. Займись сбором цветов, если можешь, я тебя очень прошу.', 'Принесите 20 цветков лилового лотоса мастеру Ночной Песне на аэродром в Дун Морог.', 'От имени Альянса с радостью принимаю твой дар, $N. Ты внес неоценимый вклад в создание снадобий, которые помогут нашим воинам на поле боя. Я благодарю тебя и прошу принести еще лилового лотоса, как только у тебя появится возможность.', 'Добро пожаловать обратно, $C. Наши запасы лилового лотоса растут, но нам все равно нужно еще. Если в твоих силах заняться сбором этих цветов, я прошу тебя это сделать.', NULL, NULL, 'Лиловый лотос', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8507, 'Рутинное задание', 'Приветствую тебя, $N. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.$B$BДружина Стальгорна под предводительством капитана Черной Наковальни расквартирована рядом с Ульем Зора.$B$BПоговори с капитаном и его лейтенантом, Джанелой Твердомолот, а потом возвращайся. Тем временем я подготовлю для тебя новое задание.$B$BАх да, сделай одолжение, держись подальше от легиона Оргриммара. Нам нелегко удерживать эти два войска от грызни, очень уж они друг друга не любят.', 'Поступите в распоряжение дружины Стальгорна возле улья Зора. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях от капитана Черной Наковальни, вернитесь к призывателю ветров Калдону в крепость Кенария в Силитусе.Внимание: исцеление или наложение благоприятных заклинаний на бойцов дружины Стальгорна переводит в режим PvP.', 'Отлично, $N. Я подготовила целую серию заданий, которые наилучшим образом распорядятся твоими навыками.$B$BЕсли ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!$B$BЕсли тебе понадобится новое задание, возвращайся к капитану Черной Наковальне.', 'Дружина капитана Черной Наковальни расквартирована рядом с Ульем Зора. Если ты не найдешь его, поговори с Джанелой Твердомолот.', NULL, NULL, 'Подписанные бумаги о полевых обязанностях', 'Неподписанные бумаги о полевых обязанностях', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8508, 'Бумаги о полевых обязанностях', '', 'Я так понимаю, мне надо подписать эти бумаги, парень?', 'Да, в наши дни эта небольшая заварушка сойдет за рутинные обязанности. Отнеси бумаги в крепость Кенария, уверен, они уж подготовят тебе работу поинтереснее.$B$BСтупай!', NULL, NULL, NULL, 'Готовые бумаги о полевых обязанностях', 'Подписанные бумаги о полевых обязанностях', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8509, 'Альянсу не хватает слез Артаса!', 'Я предпочитаю говорить быстро и по существу, $C. Альянсу нужно много слез Артаса для войны в Ан\'Кираже. Не спрашивай меня, зачем, я всего лишь выполняю приказ. Собери столько этих цветов, сколько унесешь, и сдай мне. Ну что, возьмешься за это задание?', 'Принесите 20 слез Артаса старшему сержанту Жермен в Палаты войны Стальгорна.', 'Неплохо сработано, $С. Должна сказать, я приятно удивлена. Ты никогда бы не поверил, сколько людей приходят, обещают помочь и не возвращаются. Одну секунду, сейчас я упакую травы в ящик и прикреплю к нему бирку с твоим именем, а потом сможем поговорить на тему того, нужны ли мне еще эти растения.', 'Что? Докладывай быстро и четко, $C! Тебе удалось собрать необходимое количество слез Артаса?', NULL, NULL, 'Слезы Артаса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8510, 'Альянсу снова нужны слезы Артаса', 'Так, похоже, слезы Артаса мне все еще нужны. Я предполагаю, что они растут там же, где и раньше. Чем быстрее мы закончим подготовку, тем быстрее начнем наступление на Ан\'Кираж.$B$BЯ могу вновь рассчитывать на твою помощь, $C?', 'Принесите 20 цветков слезы Артаса старшему сержанту Жермен на аэродром в Дун Морог.', 'Просто невероятно, $N! Альянс перед тобой в долгу. Мне нужно проследить, чтобы эти травы были упакованы и хранились надлежащим образом, пока кто-нибудь не изготовит из них что-нибудь полезное. Обращайся ко мне в любое время, особенно, если принесешь еще слез Артаса.', 'Так, похоже, слезы Артаса мне все еще нужны. Я предполагаю, что они растут там же, где и раньше. Чем быстрее мы закончим подготовку, тем быстрее начнем наступление на Ан\'Кираж.$B$BЯ могу вновь рассчитывать на твою помощь, $C?', NULL, NULL, 'Слезы Артаса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8511, 'Альянсу не хватает легкой кожи!', 'Наш клан Обдирщиков Камня испокон века знал толк в снятии шкур, $C. Как говорится, и с камня снимем шкуру. Потому-то Альянс и попросил нас взяться за заготовку тонкой кожи для войны в Ан\'Кираже. Я слежу, чтобы кожа была хорошо выдублена, уж не знаю, для чего она там понадобится. Но без помощи мне никак не обойтись.$B$BПока я здесь за всем надзираю, тебе придется прогуляться малость и добыть кож, а потом принести их мне. Ну что, $gпаренек:девушка:, возьмешься за дело?', 'Принесите 10 кусков легкой кожи Бонни Шлифовальщице в Палаты войны Стальгорна.', 'Я прямо скажу, Альянску крупно повезло, что у него есть такие искушенные специалисты по снятию шкур, как ты,$С. Уж я прослежу, чтобы ни одну кожу ненароком не попортили. Спасибо тебе – и не забудь, когда я пересчитаю кожу, справиться у меня, не требуется ли нам еще.', 'Ну, $C, где обещанная кожа?', NULL, NULL, 'Тонкая кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8512, 'Альянсу по-прежнему не хватает легкой кожи!', 'Рада снова тебя видеть, $N. Похоже, что мы еще не собрали достаточно кожи для наших воинских нужд. Если принесешь мне штук десять кож, это будет просто отлично.', 'Принесите 10 кусков легкой кожи Бонни Шлифовальщице на аэродром в Дун Морог.', 'Спасибо за столь щедрое пожертвование, $N. Пойду уложу кожи в стопку. Я думаю, их быстренько превратят в красивые доспехи, пустят на всякие заплатки, или для чего еще там нужна кожа. Возвращайся, как сможешь, и приноси еще – легкой кожи много не бывает.', 'Рада снова тебя видеть, $N. Похоже, что мы еще не собрали достаточно кожи для всяких воинских нужд. Если принесешь мне штук десять кож, это будет просто отлично.', NULL, NULL, 'Тонкая кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8513, 'Альянсу не хватает средней кожи!', 'Так точно, $gсэр:мэм:, я отвечаю за сбор всей средней кожи, необходимой для подготовки к войне с Ан\'Кираем. Если вы можете раздобыть среднюю кожу, неважно где, сдайте ее мне, пожалуйста. Я буду благодарен за любую помощь, если у вас найдется на нее время.', 'Принесите 10 кусков средней кожи рядовому Портеру в Палаты войны Стальгорна.', 'Вау! Похоже, вы и правда решили помочь. Большое спасибо за ваш вклад в общее дело. Пойду-ка я упакую и пересчитаю кожи. Нет, вы действительно знаете, чем скрасить день простого служаки.', 'Так точно, сэр, я помню вас. Вы принесли среднюю кожу?', NULL, NULL, 'Жесткая кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8514, 'Альянсу по-прежнему не хватает средней кожи!', 'Так точно, $gсэр:мэм:, к настоящему времени нам удалось собрать $2063w кусков средней кожи. Я знаю, что прошу слишком многого, но не могли бы вы снова оказать помощь? Если желаете, конечно. Мне необходимо выполнить установленную норму.', 'Принесите 10 средних кож рядовому Портеру на аэродром в Дун Морог.', 'Ничего себе, вот это кипа кожи, которую вы притащили, сэр! Я послежу, чтобы она попала точно по назначению, непременно. Если вы и дальше будете помогать нам, то мы выполним план гораздо раньше срока! $B$BСпасибо, $N!', 'Так точно, сэр, мы собрали много средней кожи, но все равно недостаточно. Заверяю вас, мы найдем этой коже самое наилучшее применение, ни один клочок не пропадет зря. Я знаю, что требую слишком многого, но если у вас еще сохранилось желание, помогите мне набрать установленную норму.', NULL, NULL, 'Жесткая кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8515, 'Альянсу не хватает плотной кожи!', 'О, будет так здорово! $C, приготовления к ан\'киражской войне идут вовсю, и так получилось, что я отвечаю за заготовку плотной кожи. Из нее мы сможем наделать тысячи разных вещей, но сначала надо ее достать – тоже тысячами. В буквальном смысле. И тут на сцену выходишь ты.$B$BТы ведь принесешь мне отличную увесистую кипу плотной кожи? Правда-правда?', 'Принесите 10 кусков толстой кожи Марте Остроигл в Палаты войны Стальгорна.', 'О, я знала, что ты справишься, $С, конечно же, я это знала! Я отправлю эту кожу по нужному адресу, как только смогу. Ага, а теперь давай-ка посмотрим. Похоже, в итоге все получается очень, очень миленько. Загляни ко мне еще разочек, я сейчас проверю, не нужно ли нам еще кожи. Если понадобится, то было бы так здорово, если бы ты смог достать для нас еще!', 'Это же обещанной кожей у тебя сумки набиты, $C? Не могу дождаться, когда же ты отдашь ее мне! Тогда все-все останутся нами довольны, правда?', NULL, NULL, 'Плотная кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8516, 'Альянсу по-прежнему не хватает плотной кожи!', 'Да-да, стопки все еще не очень высокие. $N, мы не выполняем норму – не хватает целых $2071w кусков плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли.$B$BТы ведь принесешь мне еще плотной кожи?', 'Принесите 10 плотных кож Марте Остроигл на аэродром Стальгорна.', 'У тебя снова все получилось! Просто невероятно, как ты умудряешься выбраться отсюда, собрать все, что нужно, а потом еще вернуться и сдать все мне. Когда люди узнают, сколько ты для нас сделал, они встанут в очередь за твоими автографами! $B$BБольшое-пребольшое спасибо за столь благородное и щедрое пожертвование плотной кожи, $N.', 'Да-да, стопки еще не очень высокие. Облизни, мы не выполняем норму – не хватает целых 80000 плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли. $B$BТы ведь принесешь мне еще плотной кожи?', NULL, NULL, 'Плотная кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8517, 'Альянсу не хватает льняных бинтов!', 'Война в Ан\'Кираже будет долгой и кровавой. Прибегнуть к помощи людей, подобных тебе, было для Альянса мудрым решением. Перед тем как сломя голову ринуться в военный конфликт, надо собрать достаточно припасов.$B$BМне поручили запасать льняные бинты, и я надеюсь, что ты мне поможешь. Это не так-то легко, но по крайней мере льняные бинты проще всего изготовить. Что скажешь, $C?', 'Принесите 20 льняных бинтов часовому Серебринке Небес в Палаты войны Стальгорна.', 'Многим солдатам ты, считай, сослужил добрую службу, $С. Я лично прослежу, чтобы твои усилия не остались незамеченными. Одну минуту, сейчас я упакую эти бинты, куда надо, и внесу их в реестр, а потом посмотрим, сколько нужно ли мне еще. $B$BДа осенит тебя своим светом Элуна, ночной эльф!', 'Двадцать льняных бинтов у тебя, $C?', NULL, NULL, 'Льняные бинты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8518, 'Альянсу по-прежнему не хватает льняных бинтов!', 'Меня всегда изумляет самоотверженность – ведь столь многие обычно гораздо более склонны к эгоизму. $C, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?', 'Принесите 20 льняных бинтов часовому Серебринке Небес на аэродром в Дун Морог.', 'Прими мою благодарность, $N. Пока некоторые пытаются нажиться на подготовке к войне, ты раз за разом доказываешь свою бескорыстную преданность делу Альянса, да что там, всего Азерота. $B$BДа пребудет с тобой благословение Элуны!', 'Меня всегда изумляет самоотверженность, ведь многие обычно более склонны к эгоизму. Друид, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?', NULL, NULL, 'Льняные бинты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8519, 'Пешка на Доске Вечности', 'Успокоившись и сосредоточив взгляд на кристалле, вы замечаете, что внутри что-то шевелится. Посмотрев поближе, вы осознаете, что перед вами предстало прошлое... давно забытое.', 'Узнайте о прошлом все, что можно. Потом поговорите с Анахроносом в Пещерах Времени в Танарисе.', 'После предательства Оленьего Шлема я собрал осколки скипетра Зыбучих песков и вернулся сюда. Я желал охранить скипетр от посягательств тех, кто был готов воспользоваться им во зло – так были созданы драконы.$B$BМне казалось, что если разделить части скипетра между четырьмя могущественными Аспектами, то взыскующие Хаос не смогут восстановить его. Я был глупцом. Проклятые драконы охотятся на меня по сей день.', NULL, NULL, NULL, 'Война Зыбучих песков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8520, 'Альянсу не хватает шелковых бинтов!', 'На горизонте маячит война в Ан\'Кираже, так что мы должны приложить все усилия, чтобы на поле боя солдаты ни в чем не нуждались. Именно этим мы и занимаемся. Я вот, например, отвечаю за заготовку шелковых бинтов.$B$BНе хочешь ли мне помочь малость?', 'Принесите 20 шелковых бинтов медсестре Стоунфилд в Палаты войны Стальгорна.', '$N, ты молодчина! Спасибо за бинты. Благодаря тебе мы еще на шаг приблизились к нашей общей цели. Сейчас пойду уберу бинты, а потом можем еще поболтать.', 'Приветик, $C, ну что, удалось раздобыть двадцать шелковых бинтов?', NULL, NULL, 'Шелковые бинты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8521, 'Альянсу по-прежнему не хватает шелковых бинтов!', 'Очень мило с твой стороны снова предложить мне помощь, $C. Мы пока собрали всего лишь $2082w шелковых бинтов, так что еще работать и работать.', 'Принесите 20 шелковых бинтов медсестре Стоунфилд на аэродром в Дун Морог.', 'Приятно иметь дело с бескорыстными ребятами вроде тебя, $N. Мы не забудем твой вклад в подготовку к войне. Именно от таких, как ты, и зависит, победим мы или проиграем. Я надеюсь, что наших усилий хватит для победы. $B$BЕще раз большое спасибо!', 'Очень мило с твоей стороны снова предложить мне помощь, $C. Мы уже собрали очень много шелковых бинтов, но это, к сожалению, далеко не конец. $N, можешь принести еще штук двадцать? Я была бы благодарна тебе от имени всего Альянса.', NULL, NULL, 'Шелковые бинты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8522, 'Альянсу не хватает бинтов из рунической ткани!', 'Считай ведение войны сколь угодно сомнительным занятием, $C, но военная машина уже завертелась. Оглянись на свою семью и друзей и спроси, чем ты можешь помочь им, – ведь все мы попадем в горнило битвы, и надо будет как-то выживать.$B$BИменно поэтому я запасаюсь бинтами из рунической ткани, кто бы их ни принес. Не хочешь ли внести посильный вклад в это дело?', 'Принесите 20 бинтов из рунической ткани хранителю Лунному Сумраку в Палаты войны Стальгорна.', 'Твоя настойчивость в выполнении этого задания выше всяких похвал, $С. Сейчас я уберу бинты на склад и вернусь. Я бы хотел побеседовать с тобой относительно возможности добыть еще бинтов из рунной ткани.', 'Проходит день за днем, а мы все продолжаем и продолжаем готовиться. Друид, тебе удалось достать бинты из рунной ткани?', NULL, NULL, 'Бинты из рунической ткани', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8523, 'Альянсу по-прежнему не хватает бинтов из рунической ткани!', 'Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, $C. Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край.$B$B$N, можешь принести мне еще бинтов из рунической ткани?', 'Принесите 20 бинтов из рунической ткани хранителю Лунному Сумраку на аэродром в Дун Морог.', 'Я рад что этот путь мы проделали вместе, $N. Работать с тобой – одно удовольствие. Хочу еще раз поблагодарить за бескорыстную помощь Альянсу тебя и всех, подобных тебе. Возращайся скорей, побеседуем еще.', 'Итак, мы слова вынуждены говорить о делах, не терпящих отлагательств, $C. Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край. $B$BЖестя, можешь принести мне еще бинтов из рунной ткани?', NULL, NULL, 'Бинты из рунической ткани', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8524, 'Альянсу не хватает радужного тунца!', 'Эй! Если бы я спросил тебя: \"Нужно ли солдатам на войне хорошо кушать?\" – ты бы, без сомнения, $gответил:ответила:: \"Да, конечно!\". И я абсолютно с тобой согласен! Рад, что мы сошлись во мнениях. Теперь, я думаю, ты не будешь спорить, что тебе осталось только отправиться на рыбалку, наловить радужного тунца, приготовить всю порцию и принести мне. М-м-м, я уже в предвкушении.', 'Принесите 20 тушек радужного тунца Гладню Гастроному в Палаты войны Стальгорна.', 'Два для Альянса, один мне, два для Альянса, один мне... Эгей, отличная работа, рыбак! Похоже, ты отличное приобретение для нашего клуба. А мне кажется, надо б раздобыть еще тунца. Почему бы тебе не прогуляться и не принести еще рыбки? У меня уже в животе урчит...', 'Готов поспорить, что ты вернешься с нужным количеством радужного тунца, $C!', NULL, NULL, 'Радужный тунец', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8525, 'Альянсу по-прежнему не хватает радужного тунца!', 'Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастроном, чтобы быть точным. Выходит, ты $gпришел:пришла:, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец? $gоблизывается:$B$BЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!', 'Принесите 20 тушек радужного тунца Гладню Гастроному на аэродром в Дун Морог.', 'Я сразу понял, что в тебе что-то такое есть, детка. Ты выглядишь, как человек, который знает, чего хочет. Да-да, с Глади Гастрогномом есть верное правило, – сделай мне приятно, и ты об этом не пожалеешь. $B$BХа-ха-ха! Ладно, сейчас пойду сложу рыбку и вернусь. Если хочешь, можешь пока приготовить еще двадцать штук.', 'Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастрогном, чтобы быть точным. Выходит, ты пришла, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец? *облизывается*$B$BЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!', NULL, NULL, 'Радужный тунец', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8526, 'Альянсу не хватает жареного мяса ящера!', 'Как делишки, $C? Я вижу, ты просто рвешься принять участие в заготовке провизии для ан\'киражской войны. Мой папочка решил, что ответственность за сбор чего-то там чему-то там меня научит. Как бы не так. Я мясо на дух не выношу.$B$BЛадно, если вдруг захочешь помочь, принеси побольше жареных ящеров. Несомненно, именно об этом мясе и будут мечтать все наши отважные солдаты.', 'Принесите 20 жареных ящеров Саре Грустносвист в Палаты войны Стальгорна.', 'Вот это да. Спасибо, что притащил сюда всю эту жженую плоть, $С. Минуточку, сейчас я его покидаю в кучу, – надеюсь, кто-нибудь о нем да позаботится. Если время найдется, может быть, еще принесешь?', 'Ну что, где там наши жареные ящеры?', NULL, NULL, 'Жареный ящер', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8527, 'Альянсу по-прежнему не хватает жареного мяса ящера!', 'О, снова здорово, $C. Я вижу, ты в восторге от всей этой беготни. Наверное, ты хочешь принести мне еще двадцать жареных ящеров? Отлично. Тогда пойди и принеси. Увидимся.', 'Принесите 20 жареных ящеров Саре Грустносвист на аэродром в Дун Морог.', 'Вау, ты просто бизнес-воротила. Один твой вид уже наводит на меня усталость. В любом случае, спасибо тебе от имени Альянса и все такое. Пойду позабочусь, чтобы всю эту дохлятину куда-нибудь прибрали. Думаю, ты можешь вернуться попозже, когда я проверю, сколько нам еще осталось собрать. Хотя, если честно, этим мясом уже провоняло здесь абсолютно все.', 'О, снова здорово, $C. Я вижу, ты в восторге от всей этой беготни. Наверное, хочешь принести мне еще двадцать жареных ящеров? Отлично. Так пойди и принеси. Увидимся.', NULL, NULL, 'Жареный ящер', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8528, 'Альянсу не хватает пятнистого желтохвоста!', 'Возможно, заготовка вареной рыбы выглядит не особенно героически, но не стоит преуменьшать значение нашей работы, $C.Солдаты – такие же люди, как и все, и они хотят есть. Именно поэтому мы должны обеспечить их провиантом, пока не началась война в Ан\'Кираже.$B$BЯ получила приказ заготавливать пятнистый желтохвост. Это отличный пищевой ресурс, он хорошо хранится, идет на изготовление различных блюд и совсем не пахнет, в отличие от другой морской рыбы. Ну что, поможешь мне в его заготовке?', 'Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке в Палаты войны Стальгорна.', 'Спасибо за быструю и своевременную помощь, $С. Теперь наши солдаты не будут испытывать недостатка в провианте. Подожди немного, я позабочусь о размещении рыбы на складе, и мы обсудим доставку еще одной порции, если ты не против.', 'Я уверена, что ты вернулся так быстро, потому что принес необходимое количество желтохвоста.', NULL, NULL, 'Рецепт пятнистого желтохвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8529, 'Альянсу по-прежнему не хватает пятнистого желтохвоста!', 'Если у тебя еще не пропало желание помогать нам, то нам все еще нужен желтохвост, $N. Я думаю, в прошлый раз ты $gприобрел:приобрела: достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?', 'Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке на аэродром в Дун Морог.', 'Сразу видно, что ты заботишься о нуждах Альянса, как о своих собственных, $N. Твои старания не останутся незамеченными, и награда обязательно найдет своего героя. Спасибо за отлично приготовленную рыбу. Теперь ее можно хранить долго и без особых проблем. Пойду-ка я запишу, сколько ты принес. Когда близится война, на счету должна быть каждая рыбина!', 'Если у тебя еще не пропало желание помогать нам, то нам опять нужен желтохвост, $N. Я думаю, в прошлый раз ты приобрел достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?', NULL, NULL, 'Рецепт пятнистого желтохвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8530, 'Альянсу не хватает опаленных вулканических камней!', '$C, мне нужна твоя помощь. Есть камни, которые можно достать в Огненных Недрах, – я имею в виду опаленные вулканические камни. Они нужны нам для подготовки к войне в Ан\'Кираже. Наши кузнецы и инженеры знают, как их использовать, так что мы получили на них заказ. Проберись в Огненные Недра и собери столько, сколько сможешь. Не сомневаюсь, что тебе удастся уговорить пойти с тобой штук тридцать девять близких приятелей.', 'Принесите 50 оплавленных вулканических камней командиру Мощному Молоту на аэродром в Дун Мороге.', '', NULL, NULL, NULL, 'Опаленный вулканический камень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8532, 'Орде не хватает медных слитков!', 'Я так рад, что ты $gрешил:решила: помочь нам. Не всякий бы согласился, так что я лучше еще раз уточню, правильно ли ты меня $gпонял:поняла:. Мне нужны медные слитки, а не просто медь. У нас недостаточно ни времени, ни людей, чтобы самим ее выплавлять, так что твои усилия не останутся незамеченными. Ну как, $C, справишься?', 'Принесите 20 медных слитков шахтеру Кромвелю в Аллею Духов Оргриммара.', 'Вот они, слитки, хорошо, что ты не стал полировать их. В блеске нет никакого смысла, они все равно пойдут на военные нужды. Пойду уложу их в штабели, и нужно позаботиться, чтобы они были пущены в дело. Если добудешь еще двадцать, обращайся прямо ко мне.', 'Я надеюсь, 20 медных слитков у тебя с собой, $C?', NULL, NULL, 'Медный слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8533, 'Орде по-прежнему не хватает медных слитков!', 'Уже $gвернулся:вернулась:? Из тебя быстро бы получился отличный рудокоп, $C. Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что ты кое-что можешь, вопрос – хочешь ли?', 'Принесите 20 медных слитков шахтеру Кромвелю в Дуротар.', 'Ты опять доказал, что ты многого стоишь, $C. Я чувствую, эта медь хорошо нам послужит, когда придет время. А теперь мне надо сложить ее в штабеля и подсчитать. Если у тебя не пропало желание, ты, вероятно, сможешь помочь нам, если принесешь еще медных слитков.', 'Уже вернулся? Из тебя быстро получился бы отличный рудокоп, $C. Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что кое-что ты можешь, но вот вопрос – хочешь ли.', NULL, NULL, 'Медный слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8534, 'Донесение разведчика из Улья Зора', 'Мы отправили наших лучших разведчиков к ульям силитидов. Азенель уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить от нее сведения.', 'Свяжитесь с кенарийской разведчицей Азенель в улье Зора и отнесите ее донесение призывательнице ветров Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VI.', 'Мы очень ценим твои усилия, $N. Я немедленно займусь этим донесением, а ты можешь переходить к следующему заданию.', 'Разведчик Азенель находится внутри Улья Зора. Спеши! Время не ждет.', NULL, NULL, 'Донесение разведчика из Улья Зора', 'Краткое изложение тактической задачи VI (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8535, 'Седой храмовник', 'Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан\'Кираже, мы не должны терять бдительность и давать волю внешним врагам.$B$BОтыщи способ вызвать и уничтожить седого храмовника и доложи о выполнении задания Бору Буйногривому.', 'Призовите и убейте седого храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу IV.', 'Отличная работа, $N. Вот следующее задание.', 'Ты уже выполнил задание?', NULL, NULL, 'Серый храмовник убито', 'Краткое изложение тактической задачи IV (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8536, 'Земляной храмовник', 'Сумеречный Молот и повелители стихий, которым поклоняются культисты, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан\'Кираже, мы не должны терять бдительность и давать волю внешним врагам.$B$BОтыщи способ вызвать и уничтожить земляного храмовника и доложи о выполнении задания Бору Буйногривому.', 'Призовите и убейте земляного храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу III.', 'Отличная работа, $N. Вот следующее задание.', 'Ты уже выполнил задание?', NULL, NULL, 'Земляной храмовник убито', 'Краткое изложение тактической задачи III (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8537, 'Багровый храмовник', 'Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан\'Кираже, мы не должны терять бдительность и давать волю внешним врагам.$B$BОтыщи способ вызвать и уничтожить багрового храмовника и доложи о выполнении задания Бору Буйногривому.', 'Призовите и убейте багрового храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу II.', 'Отличная работа, $N. Вот следующее задание.', 'Ты уже выполнил задание?', NULL, NULL, 'Багровый храмовник убито', 'Краткое изложение тактической задачи II (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8538, 'Четыре герцога', 'Связь между Сумеречным Молотом и Советом Бездны оказалась куда важнее, чем нам казалось вначале.$B$BМы не сомневаемся, что повелители Стихий, именуемые герцогами Бездны, управляют служителями культа Сумеречного Молота. Найди способ выманить в наш мир четырех герцогов Бездны и убей их!$B$BМы избрали тебя за прежние заслуги и не сомневаемся, что ты справишься.', 'Отыщите способ вызвать и убить герцога Пепла, герцога Глубин, герцога Ветров и герцога Осколков и доложите о выполнении задания командору Мар\'алиту в крепости Кенария. Для завершения задания принесите тактическую задачу V.', 'Сегодня ты сделала великое дело, $N. Тебе удалось избавить нас от злейших врагов. Хвала тебе за это!', 'Ты уже выполнила задание?', NULL, NULL, 'Огарцог убито', 'Герцог Глубин убито', 'Герцог Ветров убито', 'Герцог Осколков убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8539, 'Цель: сестры-убийцы из Улья Зора', 'Мы вызвали подкрепление для сражения у улья Зора. Твоя задача – убить как можно больше сестер-убийц. Выполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 сестер-убийц из улья Зора и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу V.', 'Отличная работа, $N. Ты очень ценный союзник.', 'Ты хочешь что-то сказать, $C?', NULL, NULL, 'Сестра-убийца из улья Зора убито', 'Изложение боевой задачи V (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8540, 'Сапоги для стражей', 'Верховому подразделению крепости Кенария не хватает изысканных мифриловых сапог. Принеси нам очередную партию и передай их капитану Вишу Коцусу из крепости Кенария.', 'Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II.', 'Отлично! Как раз то, что нужно. Спасибо.', 'Что ты мне принесла, $N?', NULL, NULL, 'Изысканные мифриловые сапоги', 'Краткий обзор задач перевозок II (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8541, 'Шлифовальные камни', 'У стражи крепости Кенария на исходе шлифовальные камни. Добудь их и отнеси капитану Вишу Коцусу в крепость Кенария.', 'Принесите 10 массивных шлифовальных камней, 10 твердых шлифовальных камней и 10 тяжелых точильных камней Вишу Коцусу, капитану стражи в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III.', 'Отлично! Нам очень нужны эти материалы. Спасибо.', 'Что ты мне принес, $N?', NULL, NULL, 'Массивный шлифовальный камень', 'Твердый шлифовальный камень', 'Тяжелый точильный камень', 'Краткий обзор задач перевозок III (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8542, 'Орде не хватает оловянных слитков!', 'Лок\'тар, $r, я уверен, ты в курсе, что мы собираемся воевать с киражскими тараканами. Вождь сказал, что сначала надо как следует подготовиться. Я б охотней точил мечи или подгонял броню, но мне доверили сбор оловянных слитков. Для меня это большая честь, да! Но без помощи мне не справиться.$B$BНадо, чтобы кто-то добывал эти самые слитки и приносил сюда. Нам нужно так много, что, боюсь, я и считать-то до стольких не умею.', 'Принесите 20 оловянных слитков рубаке Маугу в Аллею Духов Оргриммара.', 'Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, $C! От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси еще столько же.', 'Ну, сколько там у тебя оловянных слитков, $C? Думаю, после войны надо бы научиться считать, что ли...', NULL, NULL, 'Оловянный слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8543, 'Орде все еще нужны оловянные слитки!', 'Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я так нервничаю, что потихоньку начинаю выходить из себя. А твоя медлительность меня просто бесит!!! Не можешь притаскивать товар быстрее, что ли? Может, мне малость с тобой поразмяться, чтобы снять стресс...$B$BХар!!! Нет, не буду, пожалуй, а то кто тогда будет носить мне слитки?', 'Принесите 20 оловянных слитков рубаке Маугу в Дуротар.', 'Тром\'ка, $N! Своими делами ты оказываешь и мне, и Орде большую честь. Сейчас я позабочусь об этих слитках. А когда мы сделаем все, что нужно, то отправимся на войну и покажем этому ничтожному Альянсу, как надо давить тараканов! $B$BТак что ступай и принеси еще слитков!', 'Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я немного нервничаю, думаю, ты меня понимаешь, как солдат солдата, $C. Это будет победоносная война, когда начнется. Воины Орды преодолеют пески и с оружием в руках кинутся на киражских тараканов. В этот день все мы обретем великую славу! $B$BХар! Но сначала нужно собрать достаточное количество этих несчастных оловянных слитков. Забавно, что мы не можем начать грандиозную войну без этих маленьких штуковин, правда?', NULL, NULL, 'Оловянный слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8544, 'Наплеч Завоевателя', 'У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!', 'Принесите киражские наручники властности, 2 идола Ночи, 5 каменных и 5 глиняных скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', 'Я изготовил это наплечье, смертный, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.', 'Тебе удалось собрать все, что мне нужно?', NULL, NULL, 'Киражские наручники властности', 'Идол Ночи', 'Глиняный скарабей', 'Каменный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8545, 'Орде не хватает мифриловых слитков!', 'Война надвигается неотвратимо, и все, что нам остается, $C, – это как следует подготовиться к ней. В такие времена мы должны сплотиться и помогать друг другу. Как видишь, меня поставили ответственным за сбор мифриловых слитков, которые потом пойдут на нужды армии. Я стараюсь как могу, но этого пока недостаточно.$B$BСумеешь добыть мифрил на рудниках и переплавить его в слитки? Это бы нам очень пригодилось.', 'Принесите 20 мифриловых слитков старшему сержанту Ткелаху. Ткелах находится на аллее Духов Оргриммара.', 'Ну вот, очень неплохой зачин в нашей работе, $C. Теперь на складе лежит еще 20 новеньких слиточков, сейчас я внесу их в список. Когда на пороге война, на счету каждая крупинка мифрила! $B$BТы заглядывай, похоже, нам скоро еще понадобятся слитки.', 'Хорошо бы поскорее собрать все слитки и закончить подготовку к войне в Ан\'Кираже. Ты уже достал все, что мне нужно, дружище?', NULL, NULL, 'Мифриловый слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8546, 'Орде все еще не хватает мифриловых слитков!', '', 'Ага, приятно снова тебя видеть, дружище. Я помню, ты уже помог мне разок, а теперь снова нужна твоя помощь. Мы продолжаем собирать для войны мифриловые слитки. Из них получится отличное оружие, которым мы легко передавим всех этих киражских тараканов.Так что, если ты и правда нам друг, принеси еще мифриловых слитков. Пока мы не выполнили нашу квоту, я очень на тебя рассчитываю.', 'Отлично сработано, $N! Мы ближе к цели на целых двадцать слитков. Сейчас я прослежу, чтобы их отгрузили. Если раздобудешь еще двадцать, дружище, сразу же тащи их мне.', NULL, NULL, NULL, 'Мифриловый слиток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8547, 'Привет!', 'Добро пожаловать в мир World of Warcraft!$B$BВ знак особой благодарности за приобретение коллекционного издания вы получаете подарок! Передайте этот подарочный сертификат Марсилле Утренней Звезде на площади Соколиных Крыльев. Взамен вы получите маленького спутника, который будет сопровождать вас на пути к славе.$B$BЕще раз благодарим вас и желаем приятного времяпровождения в мире World of Warcraft!', 'Принесите подарочный сертификат площади Соколиных Крыльев Марсилле Утренней Звезде.', '', NULL, NULL, NULL, 'Подарочный сертификат площади Соколиных Крыльев (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8548, 'Броня добровольца', 'Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты, $N.$B$BНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.', 'Принесите 5 боевых, 3 тыловых и 7 тактических знаков Кенария Варгусу из крепости Кенария в Силитусе. Требуется дружелюбие со стороны Круга Кенария.', '', NULL, NULL, NULL, 'Кенарийский знак бойца', 'Кенарийский знак тыловика', 'Кенарийский знак тактика', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8549, 'Орде не хватает мироцвета!', 'Говорят, каждое поколение должно пройти испытание огнем. Боюсь, что ан\'киражская война станет для нас тем самым горном для закалки. Ничего, подготовимся как следует и покажем всем, из какого мы слеплены теста.$B$BНам нужен мироцвет, который пойдет на создание лекарственных снадобий, и я вызвалась быть ответственной за его сбор. Надеюсь, ты $gпришел:пришла: предложить мне свою помощь. Собери побольше мироцвета и принеси его мне.', 'Принесите 20 цветков мироцвета травнице Гордый Плюмаж в Аллею Духов Оргриммара.', 'Подготовка близится к концу, и скоро грянет война. Спасибо за помощь, $N. Мироцвет очень нужен нам, и твой вклад в общее дело не останется незамеченным. Если сможешь, возвращайся и помоги мне собрать еще мироцвета. А пока ступай, и пусть Мать-Земля хранит тебя.', 'Уже собрал мироцвет и вернулся, $C?', NULL, NULL, 'Мироцвет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8550, 'Орде все еще не хватает мироцвета!', '', 'Приветствую тебя еще раз, $N. Я рада, что ты решил снова помочь нам в этом бесконечном сборе мироцвета. Подготовка к войне идет полным ходом, поэтому эликсиры и снадобья нужны в огромных количествах.Собери столько же мироцвета, сколько и в прошлый раз, и благодарность моя не будет знать границ. Если вдруг собранный мироцвет у тебя уже с собой, то я приму его с радостью.', 'Спасибо, что продолжаешь помогать нам, $N. Твоя самоотдача делает честь тебе и твоим предкам. Пойду упакую травы, чтобы они не потеряли своей свежести к тому времени, когда они понадобятся. Продолжай трудиться на благо нашей победы, во имя Орды!', NULL, NULL, NULL, 'Мироцвет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8551, 'Сундук капитана', 'Когда-то у меня был корабль, на котором я плавал до самого Кабестана в Калимдоре, и репутация у меня была безупречная.$B$BПока…$B$BПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую Бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!$B$BГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.', 'Верните Гекельберри Смоттсу из Пиратской Бухты его сундук.', 'О, ты нашел его! О, радость, о счастье! Спасибо, $N. Ко мне вернулся мой сундук, и в душе разгорается прежний огонь.$B$BНо месть моя еще не свершилась...', 'Эгей, $N! Нашел Горлаша? Это был мой любимый сундук, к тому же в тайном отделении там лежат все мои сокровища!', NULL, NULL, 'Сундук Смоттса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8552, 'Кушак с монограммой', 'Вдоль каймы кушака вышита монограмма \"ГС\".', 'Верните кушак с монограммой владельцу.', 'Тебе удалось вернуть мой кушак? Тогда... ты, должно быть, убил морского великана! Урааа!$B$BКак я рад, что этот негодяй мертв – Мок\'раш был одним из трех великанов, которые уничтожили мои корабли и поубивали всю команду.$B$BИ так три раза подряд!$B$BТы достойный $С, $N.', 'Привет. У тебя ко мне какое-то дело?', NULL, NULL, 'Кушак с монограммой (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8553, 'Капитанская сабля', 'После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его \"Месть Шмотта\", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова надавали мне по шее. \"Месть Шмотта\" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.$B$BУ другого великана, Неголаша, моя сабля.$B$BСразись с Неголашем и принеси мне мою саблю!$B$BМожешь поговорить со Салагой, поваром с \"Мести Шмотта\", который выжил в последней битве. Он поможет тебе найти великана.', 'Поговорите с Салагой.', 'Привет-привет, $N. Капитан говорит, что ты пойдешь на Неголаша, а?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8554, 'Бой с Неголашем', 'Неголаш – великан-обжора.$B$BКогда они уничтожили мой корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!$B$BЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!', 'Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Смоттса.Убейте Неголаша и отнесите абордажную саблю Смоттса хозяину в Тернистую долину.', 'Ты отобрал у Неголаша мою саблю! Глазам своим не верю! Я чувствую, с момента нашей встречи ветер удачи переменился, теперь он попутный!$B$BСпасибо! Если я все же куплю себе новый корабль, а ты пожелаешь поплыть в море, приходи, гостем будешь.', 'Тебе удалось добыть мою саблю, $N?', NULL, NULL, 'Абордажная сабля Смоттса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8555, 'Создание драконов', '', '', 'Эраникус, Веластрас и Азурегос... Не сомневаюсь, тебе приходилось слышать об этих драконах, смертный. И они не случайно сыграли очень важную роль как наблюдатели нашего мира.К сожалению (и в этом виновата отчасти моя наивность), под воздействием то ли посланников Древних Богов, то ли предательства близких людей, все они пали. Благодаря чему мое недоверие к твоим собратьям только усилилось.Отыщи их... И готовься к худшему, $R.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8556, 'Перстень неумолимой силы', 'Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.$B$BКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.$B$BПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, $C.', 'Принесите киражское кольцо власти, 2 лучистых идола, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.', 'Я заменю камень в этом кольце. Увидишь, это сделает его эффективность куда более... приемлемой.', 'Ты принес мне кольцо и остальные материалы, $N?', NULL, NULL, 'Киражское кольцо власти', 'Лучистый идол', 'Бронзовый скарабей', 'Скарабей из слоновой кости');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8557, 'Пелерина неумолимой силы', 'Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $N. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.', 'Принесите киражскую воинскую пелерину, 2 ониксовых идола, 5 серебряных и 5 костяных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.', 'О да... Эта пелерина безукоризненна. $B$BВозьми ее, $N. Пусть она защитит тебя от нечистой магии кираи.', 'Ты принес мне материал на мантию?', NULL, NULL, 'Киражская воинская пелерина', 'Ониксовый идол', 'Костяной скарабей', 'Серебряный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8558, 'Серп неумолимой силы', 'Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...$B$BПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, $N, и я создам для тебя могучее оружие из лучших киражских материалов.', 'Принесите киражскую шипастую рукоять, 2 алебастровых идола, 5 хрустальных и 5 каменных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.', 'Ты славно потрудился, $C. Эта рукоять отлично сработана... Как в руке лежит! $B$BПрими это оружие, $N. Пусть оно поможет тебе сокрушить наших врагов!', 'Ты принес мне необходимые материалы, $N?', NULL, NULL, 'Киражская шипастая рукоять', 'Алебастровый идол', 'Хрустальный скарабей', 'Каменный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8559, 'Наголенники Завоевателя', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', 'Принесите киражские наручники властности, 2 идола Войны, 5 золотых скарабеев и 5 скарабеев из слоновой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники властности', 'Идол Войны', 'Скарабей из слоновой кости', 'Золотой скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8560, 'Набедренники Завоевателя', 'Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная:? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.', 'Принесите целую шкуру Оуро, 2 идола Смерти, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Целая шкура Оуро', 'Идол Смерти', 'Бронзовый скарабей', 'Скарабей из слоновой кости');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8561, 'Корона Завоевателя', 'Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан\'Киража будут служить нам.$B$BПринеси то, что мне нужно, $N. Взамен я отдам тебе головной убор, не имеющий равных по силе.', 'Принесите венец Век\'нилаша, 2 идола Солнца, 5 каменных и 5 хрустальных скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Венец Век\'нилаша', 'Идол Солнца', 'Хрустальный скарабей', 'Каменный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8562, 'Кираса Завоевателя', 'Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.', 'Принесите панцирь Древнего Бога, 2 идола Войны, 5 серебряных и 5 костяных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Панцирь Древнего Бога', 'Идол Войны', 'Серебряный скарабей', 'Костяной скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8563, 'Обучение чернокнижника', 'По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных чернокнижников на острове Солнечного Скитальца тренирует призыватель Тели\'Лариен. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.$B$BТели\'Лариен, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.', 'Поговорите с наставником чернокнижников – призывателем Тели\'Лариеном в Солнечном Шпиле на острове Солнечного Скитальца.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8564, 'Обучение жреца', 'По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных жрецов на острове Солнечного Скитальца тренирует сестра Арина. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.$B$BАрина, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.', 'Поговорите с наставницей жрецов сестрой Ариной в Солнечном Шпиле на острове Солнечного Скитальца.', 'Приветствую тебя, $N. Я – сестра Арина. Я предлагаю свои услуги тем, кто хочет постичь путь жреца. Многие считают, что жрецы не способны на убийство, но эльфы крови придерживаются других взглядов. Мы призваны исцелять плоть и дух, но мы и несем возмездие тем, кто преступает наши законы.$B$BЯ буду тебя обучать, но попрошу покрывать возможные расходы и уделять учебе все внимание. Если ты согласна, то начнем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8565, 'Былые победы в Арати', '', '', '', NULL, NULL, NULL, 'Ящик ресурсов из Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8566, 'Былые победы в Арати', '', '', '', NULL, NULL, NULL, 'Ящик ресурсов из Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8567, 'Былые победы в ущелье Песни Войны', '', '', '', NULL, NULL, NULL, 'Талисман заслуг Среброкрылых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8568, 'Былые победы в ущелье Песни Войны', '', '', '', NULL, NULL, NULL, 'zzDEPRECATED Warsong Mark of Honor', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8569, 'Былые сражения в ущелье Песни Войны', '', '', '', NULL, NULL, NULL, 'Лента жертвоприношения ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8570, 'Былые сражения в ущелье Песни Войны', '', '', '', NULL, NULL, NULL, 'Лента жертвоприношения ущелья Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8572, 'Броня ветерана', 'Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты, $N.$B$BНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.', 'Принесите 7 боевых, 4 тыловых и 4 тактических знаков Кенария Варгусу из крепости Кенария в Силитусе. Требуется уважение со стороны Круга Кенария.', '', NULL, NULL, NULL, 'Кенарийский знак бойца', 'Кенарийский знак тыловика', 'Кенарийский знак тактика', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8573, 'Броня защитника', 'Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты, $N.$B$BНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.', 'Принесите 15 боевых, 20 тыловых, 20 тактических знаков Кенария и 1 знак Кенария Варгусу из крепости Кенария в Силитусе. Требуется превознесение со стороны Круга Кенария.', 'Отличная работа, $N. Прошу тебя, прими это от лица Круга Кенария. Ты заслужила такую награду!', 'Мы заинтересованы в том, чтобы у ближайших наших сподвижников было хорошее снаряжение, $N.', NULL, NULL, 'Кенарийский знак бойца', 'Кенарийский знак тыловика', 'Кенарийский знак тактика', 'Драгоценность Кенария');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8574, 'Стойкая броня', 'Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий призывательницы ветров Гордый Рог, нужны не для красоты, $N.$B$BНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.', 'Принесите 15 боевых, 20 тыловых, 17 тактических знаков Кенария и 1 знак Ремула Варгусу из крепости Кенария в Силитусе. Требуется почтение со стороны Круга Кенария.', '', NULL, NULL, NULL, 'Кенарийский знак бойца', 'Кенарийский знак тыловика', 'Кенарийский знак тактика', 'Знак Ремула');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8575, 'Магическая книга Азурегоса', 'Из надписи на книге вы ни слова не понимаете. Вы даже не знаете, на каком языке сделана эта надпись!', 'Принесите магическую книгу Азурегоса Нарайну Причуденю в Танарис.', '*Нарайн жадно рассматривает письмена.*$B$BНевероятно, $С!Что это? Я по-драконьи ни бум-бум.', 'ОООХХХ! Эта штучка прямо-таки пульсирует магией! Это мне?', NULL, NULL, 'Магическая книга (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8576, 'Перевод книги', '', '', 'Первым делом, $N, нам надо узнать, что там Азурегос написал в своей книжке.Говорите, он сказал вам, будто он умеет делать арканитовые буйки, и что тут – чертежи? Странно, что он написал это на драконьем. Этот старый козел знает, что я не могу читать эту белиберду!Ежели мы хотим это сделать, то мне нужны мои гадальные очки, пятисотфунтовая курица и второй том \"Драконьего языка для чайников.\" Не обязательно в этом порядке.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8577, 'Тушеный Лис, БЛД', 'Если я хочу хоть что-то перевести, мне нужны мои гадальные очки. Увы, их давным-давно спер мой бывший лучший друг Тушеный Лис. Он разбил мое сердце на пять частей и оставил меня в горести.$B$BПри помощи моего верного хрустального шара я выяснил, где он находится – либо у Стены Седогрива в Серебряном бору или в каком-то мире за порталом Запределья, нынче разоренном Пылающим Легионом. Вы должны найти его след и отнять у него мои очки, $N!', 'Нарайн Причудень хочет, чтобы вы нашли его бывшего лучшего друга (БЛД) Тушеного Лиса, и отняли у него гадальные очки, которые БЛД украл у Причуденя.', 'Поверить не могу, что он меня нашел. Я был полностью уверен, что потерял его, когда был в Запределье. Я туда не вернусь, $R! Ни за какие коврижки! Я готов быть ему по четным лучшим другом и рабом по нечетным!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8578, 'Гадальные очки? Без проблем!', '* Из ящика доносится вздох облегчения.*$B$BТак вам нужны только его очки? Отлично! Никаких проблем... Подождите минуточку, и... Эй! Где... Епрст!$B$BВ общем, есть новость плохая и еще хуже. Плохая – я потерял очки. Еще хуже – я потерял их, когда в прошлом месяце разнюхивал обстановку в Огненных Недрах. Да, в Огненных Недрах... Думаю, что на этом наш разговор закончен! Пока!', 'Найдите гадальные очки Нарайна и отнесите их Нарайну Причуденю в Танарис.', 'Прекрасно! Теперь где взять 500-фунтовую курочку и второй том \"Драконьего языка для чайников???\" О, а вот вам кое-что за ваши тяжкие труды!', 'Что, Огненные Недра? Надеюсь, мои очки еще целы!', NULL, NULL, 'Гадальные очки Нарайна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8579, 'Поборники правого дела из числа смертных', '', 'Мы чуем наших порабощенных собратьев, томящихся в глубинах Ан\'Киража, но даже армия драконов не сможет спасти их, $R.К\'Тун наложил заклинание, которое не только держит их в плену, но поработит всех нас, если мы подойдем достаточно близко.Древний Бог предвидел наше появление и не оставил нам никакой надежды. Смешно даже думать, что смертное существо вроде тебя сможет чего-то добиться.', 'Я вижу, ты не обычная смертная, $N. Твои шансы победить Древнего Бога исчезающе малы, но они все равно больше, чем наши. В конце концов, если он ожидает у своих дверей драконов, то вряд ли готовится встретить кого-нибудь вроде тебя. $B$BТысячу лет назад Анахронос и Олений Шлем создали союз смертных и драконов, и смогли победить киражей. Можем заключить договор и мы. Если ты завоюешь доверие крыла Бронзовых драконов, мы тоже будем тебе доверять, и ты сможешь стать настоящим защитником правого дела.', NULL, NULL, NULL, 'Знаки различия киражского владыки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8580, 'Орде не хватает огнецвета!', 'Даров, $C. Как делишки, дружище? Орде тут для войны в Ан\'Кираже понадобилась прорва этого несчастного огнецвета. Даж интересно, они собираются запихнуть его во всякие взрывающиеся штуки или отдать Альянсу на топливо для танков? Спроси что-нибудь полегче, тут Пелекейки не в курсе, ага.$B$BНо кое-что Пелекейки знает... например, что ты сейчас пойдешь и принесешь ему этого несчастного огнецвета, ага, дружище?', 'Принесите 20 огнецветов нетопыриному наезднику Пелекейки в Аллею Духов Оргриммара.', 'Воин! Пелекейки просто счастлив. Сейчас он заберет эти цветочки и сложит их в коробку, чтоб не попортились. Уж Пелекейки присмотрит, чтоб их употребили на всякие военные штуки, а не на какую-нибудь дребедень. А если добудешь еще цветочков, сразу же тащи Пелекейки, ему это всяко понадобится.', 'Ты ведь не хочешь рассердить Пелекейки, ага, дружище? Ты хочешь, чтобы Пелекейки был счастлив. Поэтому щас пойдешь и принесешь ему целую охапку огнецвета, причем очень-очень быстро!', NULL, NULL, 'Огнецвет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8581, 'Орде все еще не хватает огнецвета!', '', 'Пелекейки знает, что ты хочешь помочь, ага. Принеси побольше огнецвета, и он будет счастлив. Пелекейки сделает из цветочков большие-большие бомбы и очень повеселится, когда они упадут на всяких жучков в Ан\'Кираже. Но для этого Пелекейки нужен огнецвет, ага, $C.Так что давай тащи его Пелекейки, и поживее. Приноси столько же, сколько и в прошлый раз, и Пелекейки будет доволен.', 'Ты случайно не шутишь, $C? Ты принес Пелекейки огнецвет так быстро? Сейчас-ка, дружище, Пелекейки его посчитает. Пелекейки так счастлив, он думает, что ты лучший собиратель огнецвета, ага. Скорей бы началась война с Ан\'Кираем, уж мы бы позажигали в Силитусе, так ведь, братище?', NULL, NULL, NULL, 'Огнецвет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8582, 'Орде не хватает лилового лотоса!', 'Лилового лотос, $C, является основной составляющей множества зелий, эликсиров и масел, которые необходимы для войны в Ан\'Кираже. Мы создадим бесчисленное количество самых разных снадобий. Я думаю, придется даже поэкспериментировать, чтобы исследовать все возможные способы его применения. Но для экспериментов необходимо иметь достаточно цветов в запасе.$B$BА вот это уже работа для тебя. Ступай и собери как можно больше цветков лилового лотоса. Возьмешься ради нас за это задание?', 'Принесите 20 цветков лилового лотоса аптекарю Жезель в Аллею Духов Оргриммара.', 'Твоя работа заслуживает одобрения, $C. Я должна рассортировать образцы и не забыть отметить, что это был твой вклад. Пока у меня не дойдут руки до этих цветов, нужно их правильно хранить. Как ты мог отметить, лотоса нужно гораздо больше, чем мы сейчас имеем. Далеко не уходи.', 'Ты так скоро возвратился $C? А где лиловый лотос? Поторопись, а то все мои труды пойдут насмарку.', NULL, NULL, 'Лиловый лотос', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8583, 'Орде все еще не хватает лилового лотоса!', '', 'Вынуждена констатировать тот факт, что мы все еще нуждаемся в цветах лилового лотоса, $C. Мои исследования направлены на изучение новых способов применения этого реагента, и очень много уходит на то, чтобы выработать методологию.Мне нужно, чтобы ты собрал как минимум еще двадцать образцов. Возвращайся, когда выполнишь это задание.', 'Безукоризненно точная работа, $N. Не могу не похвалить твое прилежание, а так же быстроту. Я лично присмотрю, чтобы ни один из этих цветков не пропал понапрасну. $B$BБольшое тебе спасибо. Если соберешь еще лилового лотоса, бегом неси ко мне.', NULL, NULL, NULL, 'Лиловый лотос', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8584, 'Никогда не расспрашивай меня о моем бизнесе!', 'Обо мне вам следует знать только одно - НИКОГДА не расспрашивайте меня о моем бизнесе! Я работаю с такими материями, в которых вы просто ничего не понимаете! Например: знаете ли вы, что такое психотронный мордарий? Конечно, не знаете! Именно поэтому я - мозговой центр, а вы - добывающий придаток.$B$BКак я уже сказал, если мы хотим, чтобы у нас все получилось, нам понадобится 500-фунтовая курица.$B$BСтупайте в Прибамбасск и поговорите с Диргом Быстрорубом - он скажет, где вам искать подходящий экземпляр.', 'Нарайн Причудень из Танариса хочет, чтобы вы поговорили с Могилем Быстрорубом из Прибамбасска.', '*Дирг чешет голову.*$B$B500-фунтовая курица? Таких не бывает! То есть, уже не бывает. Знавал я такую птицу... Черного бройлера-убийцу...$B$B*У Дирга дрожит голос.*$B$BНо его давно уже никто не видел, и эта птица теперь существует только в сказках. Однако, у меня есть идейка, от которой будет выгода нам обоим.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8585, 'Остров Ужаса!', 'Легенды гласят, что у химер Острова Ужаса, что в Фераласе, самое сочное и нежное на свете мясо! У этих химер есть главный химер, который, если его приготовить как надо, сойдет за 500-фунтовую курицу. Или не сойдет.$B$BСтупай на остров Ужаса и убей лорда Лакмерана. Принеси мне его тушу. Гном будет доволен. А вот чтобы я был доволен, достань мне немного вырезки химеры.$B$BСделай это – и будет тебе твоя 500-фунтовая курица и кое-что сверх того.', 'Принесите тушу Лакмерана и 20 кусков вырезки химер Могилю Быстрорубу в Танарис.', 'Посмотри только на мраморные прожилки в этой химерятинке! Блеск!$B$BТеперь вернемся к нашим цыплятам... Посмотрим... Чтобы составить рецепт мне нужно пару минут.', 'Хммммм... Химерятинка...', NULL, NULL, 'Труп Лакмерана', 'Вырезка химеры', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8586, 'Зажигательные отбивные Могиля из химерока', 'Рецепт готов! Теперь мне нужно от тебя немного ракетного топлива и глубокоскальной соли. Я займусь специями, а за счет мяса, что ты $gдобыл:добыла: покроем остальные расходы.$B$BКак принесешь мне то, что я просил, курица будет готова, и можешь нести ее Нарайну.', 'Дирг Быстроруб из Прибамбасска просит, чтобы вы принесли ему 20 порций гоблинского ракетного топлива и 20 порций глубокоскальной соли.', 'Готово! Представляю тебе величайшее мое творение: лягающиеся химеровые отбивные Дирга!', 'Поторопись. А то мясо протухнет.', NULL, NULL, 'Гоблинское ракетное топливо', 'Глубокоскальная соль', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8587, 'Возвращение к Нарайну', 'Я гоблин слова, $gпарень:подруга:. Вот твой 500 фунтовый цыпленок.$B$BНа кой гному 500-фунтовый цыпленок – понятия не имею...$B$B*Могиль ворчит себе под нос что-то неразборчивое.*$B$BМожет, он спать в нем будет... Грязные гномы...', 'Доставьте 500-фунтового цыпленка Нарайну Причуденю в Танарис.', '*Нарайн обеими руками рвет огромного цыпленка, зарывается носом во вкуснейшее блюдо Дирга.*$B$BМмммм... Невероятно! Никогда ничего вкуснее не едал!', 'Какой восхитительный запах!', NULL, NULL, '500-фунтовый цыпленок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8588, 'Орде не хватает толстой кожи!', 'Если уж мы собрались воевать, сначала надо подготовиться как следует, правда, дружище? Толстая кожа на войне – продукт первой необходимости. Она идет на все – начиная с заплаток на доспехи и заканчивая старыми добрыми ловушками.$B$BИменно поэтому ее надо собрать как можно больше. А вот это уже твоя работа, $C. Наточи поострее нож и добудь кож этак штук десять. Вот принесешь их, тогда и поговорим.', 'Принесите 10 кусков толстой кожи специалисту по снятию шкур Джамани на аллею Духов Оргриммара.', 'О, тебе удалось достать толстую кожу. У тебя острый нож, $C, кожи отлично выделаны! Пойду уберу их на склад. Нужно убедиться, что твой вклад не пропадет и послужит на благо Орде. Если удастся раздобыть еще, неси сюда.', 'Я тут не в игрушки играю, так что времени трепаться с тобой у меня нет, $C. Слишком много толстой кожи, с которой надо возиться. Возвращайся обратно, когда соберешь хотя бы десять кусков.', NULL, NULL, 'Толстая кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8589, 'Орде все еще не хватает толстой кожи!', '', 'Так точно, $C, мне все еще нужна толстая кожа. Запросы от генералов и интендантских служб кажутся бесконечными. Но это еще ничто по сравнению с тем, что требуют от нас хозяева дирижаблей!Мне придется, пожалуй, двойную норму сдать. Шекелман, пожалуйста, принеси побольше толстой кожи, и как можно скорее!', 'Ну ты даешь, дружище! Огромное тебе спасибо за эти кожи. Каждая из них хоть немного, но приближает нас к завершению военной подготовки. Пойду сдам кожи на склад, чтобы кожевники могли приступить к работе. $B$BБольшое тебе спасибо еще раз. Если раздобудешь следующую порцию кож, то ты знаешь, где меня найти.', NULL, NULL, NULL, 'Толстая кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8590, 'Орде не хватает плотной кожи!', 'Я рада, что ты $gрешил:решила: поговорить со мной, $C. Подготовка к войне в Ан\'Кираже идет полным ходом, так что нам с тобой нельзя сбавлять темп работы.$B$BЯ отвечаю за сбор плотной кожи, и ее нужно действительно много, поэтому без твоей помощи никак не справиться. Если ты мне поможешь, в моем лице тебе будет благодарна вся Орда.', 'Принесите 10 плотных кож сержанту Умале в Аллею Духов Оргриммара.', 'Ты хорошо постарался, $C. Эта кожа не будет истрачена зря – она пойдет на усиление наших дирижаблей и изготовление оружия и брони. Благодарю тебя от лица всей Орды. Если тебе в своих путешествиях удастся добыть еще плотной кожи, неси ее мне. И удачи тебе.', 'Что, $C, уже удалось достать плотную кожу?', NULL, NULL, 'Плотная кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8591, 'Орде все еще не хватает плотной кожи!', '', 'Как видишь, $C, я все еще продолжаю собирать плотную кожу. И я снова хочу просить тебя о помощи. Обещаю, Орда не забудет приложенных тобой усилий.Постарайся достать кожу как можно скорее, для нас очень важно поскорее закончить приготовления к войне!', 'Ты справился, я знала, что у тебя все выйдет! От имени всей Орды я снова благодарю тебя. Твой вклад не останется незамеченным. Если достанешь еще плотной кожи, приноси ее мне. $B$BЛок\'тар огар, $C!', NULL, NULL, NULL, 'Плотная кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8592, 'Тиара Оракула', 'Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан\'Киража будут служить нам.$B$BПринеси то, что мне нужно, $N. Взамен я отдам тебе головной убор, не имеющий равных по силе.', 'Принесите венец Век\'нилаша, 2 идола Мудреца, 5 серебряных и 5 костяных скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Венец Век\'нилаша', 'Идол Мудреца', 'Серебряный скарабей', 'Костяной скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8593, 'Брюки Оракула', 'Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная:? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.', 'Принесите целую шкуру Оуро, 2 идола Жизни, 5 золотых и 5 глиняных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Целая шкура Оуро', 'Идол Жизни', 'Золотой скарабей', 'Глиняный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8594, 'Оплечье Оракула', 'У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!', 'Принесите киражские наручники Командования, 2 идола Возрождения, 5 серебряных скарабеев и 5 скарабеев из слоновой кости Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', 'Я изготовил это наплечье, смертный, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.', 'Тебе удалось собрать все, что мне нужно?', NULL, NULL, 'Киражские наручники властности', 'Идол возрождения', 'Серебряный скарабей', 'Скарабей из слоновой кости');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8595, 'Поборники правого дела из числа смертных', '', '', 'Мы довольны твоей службой, $N. Наш договор остается в силе.', NULL, NULL, NULL, 'Знаки различия киражского владыки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8596, 'Обмотки Оракула', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', 'Принесите киражские наручники властности, 2 идола Смерти, 5 бронзовых и 5 золотых скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники властности', 'Идол Смерти', 'Бронзовый скарабей', 'Золотой скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8597, '\"Драконий язык для чайников\"', 'Я так и знал, что однажды эта книга мне пригодится! И я в своей мудрости и и предусмотрительности приготовил для нее укромное хранилище.$B$BНе беспокойтесь, это место никто и никогда не найдет! Только для того, чтобы туда добраться, мне понадобился гирокоптер. Увы, я потерпел крушение на берегу по дороге домой. Но именно в результате этого несчастного случая я обрел сверхгномские способности!$B$BНайдите мой разбитый гирокоптер на Последнем берегу и плывите оттуда к югу! Нужное место узнаете с первого взгляда!', 'Найдите книгу Нарайна Причуденя на острове в Южных морях.', 'Книга пропала! На куче земли лежит записка.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8598, 'вЫкУП', '*Текст записки оттиснут на пергаменте различными шрифтами.*$B$BТвоя драгоценная книга у нас, гном. Ежели хочешь снова ее увидеть, делай как сказано.$B$B*Дальше идет список инструкций на три страницы.*$B$BНеси деньги и приходи один!', 'Отнесите письмо с требованием выкупа Нарайну Причуденю в Танарис.', '*Нарайн багровеет.*$B$BПохитили... мою... книгу, книгокрады!!! Я покажу им, как попадаться под руку гному с паранормальным способностями!', 'Ну, в чем дело?', NULL, NULL, 'Письмо с требованием выкупа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8599, 'Любовная песнь для Нарайна', 'Нечасто у меня бывают гости. Говоря по чести, последний раз это было тогда, когда я спасла этого миленького, сладенького гномика из-под обломков разбитого ветролета.$B$B<Меридит смотрит вдаль, погрузившись в воспоминания.>$B$BТы его знаешь? Нарайн? Нарайн Причуддень? О, как бы я была благодарна, если бы кто-нибудь доставил ему письмо от меня. Я просто должна рассказать ему о своих чувствах! Я знаю, это любовь! Я точно знаю!$B$BНе можешь ли ты доставить это письмецо Нарайну? Я век буду благодарна тебе!', 'Отнесите любовное послание Меридит Нарайну Причуденю в Танарис.', 'Что!?$B$B*Нарайн начинает суетиться.*$B$BНу, хммм... От меня-то вы чего хотите??? Она же рыба! РЫБА, говорю вам! А я гном. У нас все равно ничего бы не вышло.', 'От вас рыбой несет!', NULL, NULL, 'Любовное послание Меридит (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8600, 'Орде не хватает грубой кожи!', 'Я понял, что подгонка ножа по руке важна даже больше, чем острота лезвия. И самый тупой клинок способен порезать, если приложить нужное усилие. Правильно, $C? Думаю, у нас не будет таких проблем, ведь наши ножи всегда хорошо заточены.$B$BНу, это не важно. У меня для тебя есть дело. Достань мне побольше грубой кожи. Она нужна, чтобы Орда как следует подготовилась к войне в Ан\'Кираже. Я не сомневаюсь, что ты отлично справишься, ага?', 'Принесите 10 кусков грубой кожи доктору Серратусу, который находится на аллее Духов в Оргриммаре.', 'Прекрасно, прекрасно, ты проделал неплохую работенку, хотя некоторые из этих кож по краям обрезаны не слишком ровно. Но, без сомнений, задание выполнено, и ты получишь обещанную награду. Если вдруг раздобудешь еще прочной кожи, то тащи ее мне поскорее.', 'Не может же быть, чтобы срезка десяти прочных кож отняла столько времени! Может, тебе стоит наточить охотничий нож? Или я ошибся, и кожи у тебя с собой?', NULL, NULL, 'Грубая кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8601, 'Орде все еще не хватает грубой кожи!', '', 'Война в Ан\'Кираже неотвратимо приближается, и приготовления идут полным ходом, $C. Мы не должны снижать темп подготовки. По крайней мере, я не хочу, чтобы это случилось по моей вине. Достань мне еще одну стопку прочной кожи. Я буду крайне признателен, если ты быстро разберешься с этой проблемой, Арт.', 'Тренировка, тренировка и еще раз тренировка. Хорошо заточенный нож и умение им пользоваться еще не раз сослужат тебе добрую службу, $N. Похоже, края этих кож стали ровнее, чем было вначале. Ты купил себе новый нож? $B$BВ любом случае, большое спасибо за потраченные силы. Твой вклад не останется незамеченным, уж будь уверен. Если вдруг сыщещь еще прочной кожи, приходи узнать, не нужна ли она мне.', NULL, NULL, NULL, 'Грубая кожа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8602, 'Наплечье Зовущего бурю', 'У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!', 'Принесите киражские наручники Господства, 2 идола Жизни, 5 золотых и 5 хрустальных скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники господства', 'Идол Жизни', 'Золотой скарабей', 'Хрустальный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8603, 'Одежды Оракула', 'Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.', 'Принесите чешую Древнего Бога, 2 идола Смерти, 5 каменных и 5 хрустальных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Чешуя Древнего Бога', 'Идол Смерти', 'Каменный скарабей', 'Хрустальный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8604, 'Орде не хватает шерстяных бинтов!', 'Приветствую, $C. Мне поручено собирать шерстяные бинты для подготовки к войне в Ан\'Кираже. К сожалению, на поле боя солдаты не могут рассчитывать, что лекари успеют добраться сразу до всех. Поэтому мы должны уделить как можно больше внимания оказанию первой помощи.$B$BЕсли у тебя есть время, помоги мне собрать шерстяные бинты. Принеси их сюда, а я позабочусь, чтобы тебе выдали положенное вознаграждение.', 'Принесите 20 шерстяных бинтов целителю клана Долгий Бег в Аллею Духов Оргриммара.', 'Прими мою благодарность, $C, и вместе с ней – благодарность всей Орды. Если тебе еще попадутся шерстяные бинты, неси их мне. А пока – да хранят тебя предки!', 'О, $C, тебе уже удалось раздобыть бинты? Так быстро?', NULL, NULL, 'Шерстяные бинты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8605, 'Орде все еще не хватает шерстяных бинтов!', '', 'Рад снова тебя видеть, $C. Мы продолжаем трудиться в поте лица, и мне опять нужна помощь в сборе шерстяных бинтов. Если ты нам поможешь, я буду крайне благодарен. В прошлых битвах из-за недостатка первой помощи погибло слишком много хороших солдат. Я никогда не прощу себе, если подобное случится еще раз.', 'Ты знаешь, что такое настоящее благородство, $N! Я прослежу, чтобы эти бинты попали в нужные руки. Прими мою благодарность и благодарность Орды.$B$BСтупай с миром и обязательно возвращайся, если у тебя будут лишние шерстяные бинты. Нам понадобится вся помощь, которая только возможна.', NULL, NULL, NULL, 'Шерстяные бинты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8606, 'Утка!', 'Меня посетила гениальная мысль! Вот что мы сделаем. Я насыплю в мешок камней, а вы осуществите сброс. Да, знаю, я должен доставить выкуп лично – я и доставлю, типа того.$B$B<Нарайн меряет вас взглядом.>$B$BСойдете. Берите этот тюрбан, одежду и мешок с камнями и направляйтесь к условленной точке сброса в Зимних ключах.$B$BВ этом специальном наборе все, что вам нужно. Когда они высунут нос, чтобы забрать выкуп, задайте им перцу! Будут знать, как наезжать на Нарайна!', 'Нарайн Причудень из Танариса хочет, чтобы вы отправились в Зимние кючи и сбросили мешок с золотом в условленной точке, указанной книгокрадами.', 'А вдруг мы недооценили этих книгокрадов?', NULL, NULL, NULL, 'На кого работает номер два?', 'Особый набор Нарайна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8607, 'Орде не хватает бинтов из магической ткани!', 'Ты действительно хочешь помочь мне в сборе материалов, за которые я отвечаю? Отлично! Бинты из магической ткани нужны мне любой ценой, я имею в виду, в буквальном смысле \"любой ценой\". Хорошо бы свежие, но это совершенно не обязательно. Когда добудешь их, $C, возвращайся ко мне, я прослежу, чтобы тебя соответственным образом наградили.', 'Принесите 20 бинтов из магической ткани госпоже Кэллоу на аллею Духов Оргриммара.', 'Удивительно, но все в порядке. Возможно, я недооценила твои способности, $C. Все возможно. К тому же, задание было несложное, а награда гораздо больше, чем следует. Впрочем, не бери в голову. Если хочешь в самом деле доказать, чего стоишь, ступай и принеси еще бинтов из магической ткани.', 'Пожалуйста, не подведи, это поставит меня в крайне неудобное положение. Возвращайся с бинтами из магической ткани как только сможешь.', NULL, NULL, 'Бинты из магической ткани', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8608, 'Орде опять не хватает бинтов из магической ткани!', '', 'Ты вернулся? Занятно. Как можно заметить, я все еще собираю материалы для так называемой ан\'киражской военной кампании. Это означает, что мне опять нужны волшебные бинты. С нетерпением жду твоего возвращения, $C.', 'Просто поразительно, $C, тебе опять все удалось! Ну, говорят, что у меня нюх на помощников. Хорошо, твой вклад не останется незамеченным и ты несоменно получишь социальные льготы соразмерно своим заслугам. А пока, я полагаю, тебе следует вернуться к сбору бинтов из магической ткани, если ты действительно хочешь доказать, чего стоишь.', NULL, NULL, NULL, 'Бинты из магической ткани', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8609, 'Орде не хватает бинтов из рунической ткани!', 'Альянс и Орда готовятся к войне в Ан\'Кираже, идя встречными курсами. Просто удивительно, что они собираются воевать не друг с другом, а с силитидами, какая бы сила ни стояла за ними. Не менее удивительно, что обе стороны вносят свой вклад в заготовку военных ресурсов в достаточном количестве.$B$BЯ отвечаю за сбор бинтов из рунической ткани, для оказания первой помощи. Но одна я точно не справлюсь. Помоги мне, $C, я буду очень признательна.', 'Принесите 20 бинтов из рунической ткани каменному стражу Глиняному Копыту в аллею Духов Оргриммара.', 'Орда в долгу перед тобой, $C. Спасибо тебе за то, что ты для нас сделала, мы сохраним твои поступки в своем сердце. Я должна складировать эти бинты и посчитать, насколько мы приблизились к выполнению цели. Если получится, добудь еще бинтов из рунной ткани и возвращайся ко мне.', 'Я думаю, война скоро начнется, $C. Хорошо, что ты нашел время позаботиться о наших общих нуждах. Тебе уже удалось достать бинты из рунной ткани?', NULL, NULL, 'Бинты из рунической ткани', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8610, 'Орде все еще не хватает бинтов из рунической ткани!', '', 'Близится время, когда мы очертя голову кинемся в бой и пройдем огнем и мечом по всему Ан\'Киражу, $C. Но сначала мы должны накопить силы и как следует подготовиться ко встрече с насекомыми, которые там засели, и их хозяевами.Раз уж ты пришел сюда, значит хочешь внести очередное пожертвование на нужды нашей армии? Мне нужны бинты из рунной ткани. Принеси мне их как можно скорее.', 'С твоей стороны это очень бескорыстный поступок, $N. Может быть, именно он спасет жизнь многим бойцам нашей армии в Ан\'Кираже. Орда в долгу перед тобой. Если сумеешь достать еще бинтов из рунной ткани, пожалуйста, неси их мне.', NULL, NULL, NULL, 'Бинты из рунической ткани', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8611, 'Орде не хватает постных стейков из волчатины!', 'Я здесь не просто так загораю, $C. Подготовка к войне – дело нешуточное! Если мы хотим передавить киражских тараканов, надо приложить массу усилий, в том числе к заготовке провианта.$B$BМеня назначили ответственным за засолку постных стейков из волчатины. Однако не могу же я разорваться на части – бегать за волками по лесам и обеспечивать хранение и учет мяса одновременно. Так что это тебе придется добыть волчатины и приготовить ее, как надо, а потом ты принесешь ее мне. Все понятно?', 'Принесите 20 постных стейков из волчатины кровавому стражу Сыросмолла на аллею Духов Оргриммара.', 'О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживет свежим. $B$BСпасибо за вклад в наше общее дело, $C. А пока – как насчет того, чтобы принести мне еще порцию стейков?', 'Что, уже наготовил волчатины, $C? Мне не важно, если они будут пережаренные или переперченные, главное, чтобы их можно было жевать и чтобы они оказались у меня побыстрее!', NULL, NULL, 'Постный стейк из волчатины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8612, 'Орде все еще не хватает постных стейков из волчатины!', '', '', '', NULL, NULL, NULL, 'Постный стейк из волчатины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8613, 'Орде не хватает пятнистого желтохвоста!', 'Отличный денек для рыбалки, ага, дружище? Эта ты правильно думаешь, мне б рыбка ого как пригодилась. Орде нужна чертова куча пятнистого желтохвоста. Говорят, мы будем его хавать, когда отправимся в Ан\'Кираж рубиться. Так я ответил, что всегда готов служить, ага. Тока мне, конечно, помощь понадобится. Ты как насчет помочь, $C?', 'Принесите 20 пятнистых желтохвостов Линдо Рыболову на аллею Духов Оргриммара.', 'О, вот эт\'дело. Отличный рыбец! Счас-ка я ее приберу, штоб не попортилась. Спасибо, што помог. Я так скажу, ты пока номер один по этому самому желтохвосту. Как наловишь и изготовишь еще штук двадцать, тащи сюда. Будь спок, уж я всем раззвоню о твоих подвигах!', 'Уже пришлепал обратно, $C? И как там насчет рыбки? Помнишь, что ее надо было вкусненько приготовить, ага? Травить наших солдат сырой рыбой не годится, особенно посередь пустыни.', NULL, NULL, 'Рецепт пятнистого желтохвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8614, 'Орде все еще не хватает пятнистого желтохвоста!', '', 'Как вишь, рыбка нам все еще нужна. И немало, ага. Бойцы должны хорошо лопать, штобы завалить всех киражских тараканов. Так что желтохвост – эт наше все. Налови его побольше, прожарь хорошенько и тащи сюда, а уж я и вся Орда скажем тебе спасибо.', 'Лучший улов сезона, $N! Отличная работенка. Вот эт\' я понимаю, никаких костей в рыбе. За такого желтохвоста всякий боец спасибо скажет. Наловишь еще, тащи сюда обзательно.', NULL, NULL, NULL, 'Рецепт пятнистого желтохвоста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8615, 'Орде не хватает печеного лосося!', 'Подготовка к войне в Ан\'Кираже – дело нешуточное, $C. Чтобы изготовить оружие, нужно железо, а чтобы крепко держать его в руках – провиант. Если ты не поешь пару дней, хватит ли у тебя сил поднять боевой топор, когда придет время для битвы?$B$BИменно поэтому сбор провизии не менее важен, чем все остальное. Я занимаюсь заготовками печеного лосося. Он хорошо хранится и обладает отличными питательными свойствами. Ну что, поможешь мне, $C?', 'Принесите 20 печеных лососей повару Острой Шпоре на аллею Духов Оргриммара.', 'Большое спасибо, что помог мне с заготовкой рыбы, $C. Очень многим нет никакого дела до подготовки к войне, их интересует только, как бы набить свои карманы. Они недостойны благорасположения Орды, в отличие от тебя. Пусть твое сердце исполнится гордости за свои бескорыстные деяния. $B$BПрими еще раз мою благодарность. Если найдешь время, чтобы еще раз помочь нам, буду очень признателен.', 'Ну как, удалось раздобыть рыбу, $C? Помни, что она должна быть хорошо приготовлена. К сожалению, сырая рыба мне без надобности.', NULL, NULL, 'Печеный лосось', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8616, 'Орде все еще не хватает печеного лосося!', '', 'В прошлый раз ты принес просто отличную запеченную рыбу, $C. Должен признать, я не удержался и взял немного себе. Как видишь, мы еще не собрали столько, сколько нужно. Я надеюсь, ты вернулся, потому что принес еще штук двадцать?', 'Трудно представить, сколько времени и сил ты потратил, чтобы помочь нам, $N. Знай, твои труды не пропадут впустую. Я благодарен тебе от имени всей Орды. Возвращайся, когда наготовишь следующую порцию рыбы.', NULL, NULL, NULL, 'Печеный лосось', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8619, 'Предок Утренний Туман', '', '', 'Приятно знать, что народ этих земель все еще отдает дань уважения старшим расам. Всего хорошего, $N. Прими этот знак...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8620, 'Единственный способ', 'Надо было раньше сообразить! Мой архивраг, Доктор Жло, взялся за старое! А теперь, благодаря вашему провалу в Зимних ключах, Доктор Жло уничтожил мою книгу! И как теперь вы будете спасать мир, герой?$B$BИз полученной мной записки я узнал, что \"Драконий язык для чайников: том II\" разорван на 8 частей и разбросан по ветру! Если вы как-нибудь умудритесь найти пропавшие главы, при помощи этого магического переплета сшейте их снова и возвращайтесь ко мне.', 'Найдите 8 утраченных глав из книги \"Драконий язык для чайников\" и соберите их при помощи магического книжного переплета. Принесите полную книгу \"Драконий язык для дураков: том II\" Нарайну Причудденю в Танарис.', 'Фантастика. Поверить не могу, что вы прошли через барьер! Вы, часом, не машина? Будь я на вашем месте – да горел бы этот мир синим огнем!$B$BСнимаю перед вами тюрбан, сэр. Что же, доброе дело не должно остаться без награды.', 'Я надеваю штаны точно так же, как и вы – по штанине на ногу. Только когда мои штаны на мне, я делаю арканитовые буйки. Арканитовые, детка!', NULL, NULL, 'Драконий язык для чайников, т. II', 'Магический книжный переплет', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8621, 'Прочные ботинки Зовущего бурю', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', 'Принесите киражские наручники Господства, 2 идола Мудреца, 5 бронзовых и 5 глиняных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники господства', 'Идол Мудреца', 'Бронзовый скарабей', 'Глиняный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8622, 'Хауберк Зовущего бурю', 'Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.', 'Принесите панцирь Древнего Бога, 2 идола мудреца, 5 серебряных и 5 костяных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Панцирь Древнего Бога', 'Идол Мудреца', 'Серебряный скарабей', 'Костяной скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8623, 'Диадема Зовущего бурю', 'Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан\'Киража будут служить нам.$B$BПринеси то, что мне нужно, $N. Взамен я отдам тебе головной убор, не имеющий равных по силе.', 'Принесите диадему Век\'лора, два идола Возрождения, пять каменных и пять хрустальных скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Диадема Век\'лора', 'Идол возрождения', 'Каменный скарабей', 'Хрустальный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8624, 'Поножи Зовущего Бурю', 'Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная:? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.', 'Принесите шкуру гигантского песчаного червя, два идола Борьбы, пять бронзовых скарабеев и пять скарабеев из слоновой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Шкура гигантского песчаного червя', 'Идол Борьбы', 'Скарабей из слоновой кости', 'Бронзовый скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8625, 'Наплечные пластины таинства', 'У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!', 'Принесите киражские наручники господства, 2 идола Смерти, 5 каменных и 5 бронзовых скарабеев Андоргос в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', 'Я изготовил это наплечье, смертный, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.', 'Тебе удалось собрать все, что мне нужно?', NULL, NULL, 'Киражские наручники господства', 'Идол Смерти', 'Каменный скарабей', 'Бронзовый скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8626, 'Прочные ботинки бойца', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', 'Принесите киражские наручники властности, 2 идола Жизни, 5 каменных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', 'Поздравляю, $N. Тебе удалось выполнить это задание. Теперь я вижу, что ты не простая смертная. Прими эту вещь, она поможет тебе сокрушить мерзких киражей.', 'Тебе удалось достать то, что я просил, $N?', NULL, NULL, 'Киражские наручники властности', 'Идол Жизни', 'Каменный скарабей', 'Костяной скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8627, 'Кираса Мстителя', 'Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.', 'Принесите кирасу Древнего Бога, 2 идола Мудреца, 5 серебряных и 5 костяных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Панцирь Древнего Бога', 'Идол Мудреца', 'Серебряный скарабей', 'Костяной скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8628, 'Корона Мстителя', 'Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан\'Киража будут служить нам.$B$BПринеси то, что мне нужно, $N. Взамен я отдам тебе головной убор, не имеющий равных по силе.', 'Принесите диадему Век\'лора, два идола Возрождения, пять каменных и пять хрустальных скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Диадема Век\'лора', 'Идол возрождения', 'Каменный скарабей', 'Хрустальный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8629, 'Набедренники Мстителя', 'Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная:? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.', 'Принесите шкуру гигантского песчаного червя, два идола Борьбы, пять бронзовых скарабеев и пять скарабеев из слоновой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Шкура гигантского песчаного червя', 'Идол Борьбы', 'Скарабей из слоновой кости', 'Бронзовый скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8630, 'Наплечье Мстителя', 'У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!', 'Принесите киражские наручники Господства, два идола Жизни, пять хрустальных и пять золотых скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники господства', 'Идол Жизни', 'Золотой скарабей', 'Хрустальный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8631, 'Поножи Таинства', 'Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная:? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.', 'Принесите целую шкуру Оуро, 2 идола Мудреца, 5 серебряных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Целая шкура Оуро', 'Идол Мудреца', 'Серебряный скарабей', 'Костяной скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8632, 'Венец Таинства', 'Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан\'Киража будут служить нам.$B$BПринеси то, что мне нужно, $N. Взамен я отдам тебе головной убор, не имеющий равных по силе.', 'Принесите венец Век\'нилаша, 2 идола Ночи, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Венец Век\'нилаша', 'Идол Ночи', 'Бронзовый скарабей', 'Скарабей из слоновой кости');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8633, 'Одеяния Таинства', 'Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.', 'Принесите чешую Древнего Бога, 2 идола Солнца, 5 золотых и 5 глиняных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Чешуя Древнего Бога', 'Идол Солнца', 'Золотой скарабей', 'Глиняный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8634, 'Сапоги Таинства', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', 'Принесите киражские наручники Господства, 2 идола Солнца, 5 серебряных и 5 хрустальных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники господства', 'Идол Солнца', 'Серебряный скарабей', 'Хрустальный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8635, 'Предок Камнещеп', '', '', 'Легенды растут из семени давних битв. Ты живешь в эпоху героев, юноша. Да укоренится твоя легенда и да принесет она обильный плод.Всего тебе наилучшего, $N. Прими от меня этот знак...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8636, 'Предок Скалогром', '', '', 'Плоть, материя жизни, смертна и рано или поздно обратится в прах. Дух же вечен. Всего наилучшего тебе, $N. Прими этот знак...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8637, 'Сапоги торговца смертью', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', 'Принесите киражские наручники властности, 2 идола Борьбы, 5 хрустальных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники властности', 'Идол Борьбы', 'Хрустальный скарабей', 'Костяной скарабей');
