INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8654, 'Предок Первокамень', '', '', 'Приятно знать, что народ этих земель все еще отдает дань уважения старшим расам. Всего хорошего, $N. Прими этот знак...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8655, 'Наголенники Мстителя', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', 'Принесите киражские наручники Господства, 2 идола Мудреца, 5 бронзовых и 5 глиняных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники господства', 'Идол Мудреца', 'Бронзовый скарабей', 'Глиняный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8656, 'Хауберк Бойца', 'Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.', 'Принесите панцирь Древнего Бога, 2 идола Жизни, 5 золотых и 5 глиняных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.', 'Я не ожидала, что ты сумеешь вернуться живой $N.$B$BТебе удалось исполнить то, что не под силу многим бессмертным. $B$BУбив К\'Туна, ты не только спасла Азерот, ты поколебала чаши космических весов, на которых лежат события, далеко превосходящие твое понимание. $B$BПрими этот доспех как символ великой славы и знак великого груза, который ты взвалила на себя своим поступком. $B$BБыть может, он поможет преодолеть тяготы пути, который отныне лежит перед тобой, богоборец.', 'К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.', NULL, NULL, 'Панцирь Древнего Бога', 'Идол Жизни', 'Золотой скарабей', 'Глиняный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8657, 'Диадема бойца', 'Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан\'Киража будут служить нам.$B$BПринеси то, что мне нужно, $N. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.', 'Принесите диадему Век\'лора, 2 идола Борьбы, 5 бронзовых скарабеев и 5 скарабеев из слоновой кожи Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', 'Тыбе удалось одержать победу! Императоры-близнецы прекратили шептаться в моей голове. $B$BПрими же от меня награду. Один вид этой вещи вселяет ужас в сердца киражей... Она напоминает им, что самые могучие их предводители погибли от руки смертных.', 'Ты принесла мне то, о чем я просил, $N?', NULL, NULL, 'Диадема Век\'лора', 'Идол Борьбы', 'Бронзовый скарабей', 'Скарабей из слоновой кости');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8658, 'Поножи Бойца', 'Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная:? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.', 'Принесите шкуру гигантского песчаного червя, 2 идола Солнца, 5 серебряных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', 'Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражей, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Кирая.', 'Ты принесла мне все, что необходимо, $N?', NULL, NULL, 'Шкура гигантского песчаного червя', 'Идол Солнца', 'Серебряный скарабей', 'Костяной скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8659, 'Наплечье Бойца', 'У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!', 'Принесите киражские наручники властности, 2 идола Войны, 5 хрустальных скарабеев и 5 скарабеев из слоновой кости Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздрому.', 'Я изготовил это наплечье, смертная, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.', 'Тебе удалось собрать все, что мне нужно?', NULL, NULL, 'Киражские наручники властности', 'Идол Войны', 'Хрустальный скарабей', 'Скарабей из слоновой кости');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8660, 'Обмотки призывателя рока', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', 'Принесите киражские наручники Господства, 2 идола Ночи, 5 глиняных скарабеев и 5 скарабеев из слоновой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники господства', 'Идол Ночи', 'Глиняный скарабей', 'Скарабей из слоновой кости');
