INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8664, 'Оплечье призывателя рока', 'У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!', 'Принесите киражские наручники Господства, 2 идола Мудреца, 5 бронзовых и 5 костяных скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники господства', 'Идол Мудреца', 'Бронзовый скарабей', 'Костяной скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8665, 'Сапоги сотворения', 'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.', 'Принесите киражские наручники Господства, 2 идола Возрождения, 5 каменных и 5 серебряных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники господства', 'Идол возрождения', 'Каменный скарабей', 'Серебряный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8666, 'Ж$N сотворения', 'Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.', 'Принесите чешую Древнего Бога, 2 идола Возрождения, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Чешуя Древнего Бога', 'Идол возрождения', 'Бронзовый скарабей', 'Скарабей из слоновой кости');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8667, 'Шлем сотворения', 'Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан\'Киража будут служить нам.$B$BПринеси то, что мне нужно, $N. Взамен я отдам тебе головной убор, не имеющий равных по силе.', 'Принесите Диадему Век\'лора, два идола Жизни, пять золотых и пять глиняных скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Диадема Век\'лора', 'Идол Жизни', 'Золотой скарабей', 'Глиняный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8668, 'Брюки сотворения', 'Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная:? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.', 'Принесите шкуру гигантского песчаного червя, 2 идола Войны, 5 каменных и 5 хрустальных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Шкура гигантского песчаного червя', 'Идол Войны', 'Каменный скарабей', 'Хрустальный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8669, 'Наплечные пластины сотворения', 'У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!', 'Принесите киражские наручники Господства, два идола Борьбы, пять золотых и пять каменных скарабеев Андоргосу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.', '', NULL, NULL, NULL, 'Киражские наручники господства', 'Идол Борьбы', 'Золотой скарабей', 'Костяной скарабей');
