INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8687, 'Цель: копатели из Улья Зора', 'Мы вызвали подкрепление для сражения у улья Зора. Твоя задача – убить как можно больше копателей. Выполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 копателей из улья Зора и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу VII.', 'Отличная работа, $N. Без копаталей силитидам придется нелегко. Кто будет восстанавливать строение улья? Думаю, ты хочешь получить новое задание.', 'Ты хочешь что-то сказать, $C?', NULL, NULL, 'Проходчик из улья Зора убито', 'Изложение боевой задачи VII (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8688, 'Предок Вестник Ветров', '', '', 'В небесах, в бессчетных созвездиях, записана разгадка всех наших земных тайн. Смогут ли мудрые – и удачливые – обратить взор к небесной тверди и узнать правду?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8689, 'Накидка Бесконечной мудрости', 'Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $N. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.', 'Принесите киражскую воинскую пелерину, 2 яшмовых идола, 5 золотых и 5 глиняных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.', 'О да... Эта пелерина безукоризненна. $B$BВозьми ее, $N. Пусть она защитит тебя от нечистой магии кираи.', 'Ты принесла мне материал на мантию?', NULL, NULL, 'Киражская воинская пелерина', 'Яшмовый идол', 'Золотой скарабей', 'Глиняный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8690, 'Плащ надвигающейся бури', 'Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $N. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.', 'Принесите киражскую царскую пелерину, 2 обсидиановых идола, 5 глиняных и 5 золотых скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.', '', NULL, NULL, NULL, 'Киражская монаршая пелерина', 'Обсидиановый идол', 'Глиняный скарабей', 'Золотой скарабей');
