INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8704, 'Перстень Незримого пути', 'Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.$B$BКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.$B$BПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, $C.', 'Принесите киражское церемониальное кольцо, 2 янтарных идола, 5 золотых и 5 глиняных скарабеев Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.', '', NULL, NULL, NULL, 'Киражское церемониальное кольцо', 'Янтарный идол', 'Золотой скарабей', 'Глиняный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8705, 'Чекан Беспредельной мудрости', 'Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...$B$BПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, $N, и я создам для тебя могучее оружие из лучших киражских материалов.', 'Принесите киражскую изысканную рукоять, 2 лучистых идола, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.', 'Ты славно потрудилась, $C. Эта рукоять отлично сработана... Как в руке лежит! $B$BПрими это оружие, $N. Пусть оно поможет тебе сокрушить наших врагов!', 'Ты принесла мне необходимые материалы, $N?', NULL, NULL, 'Киражская изысканная рукоять', 'Лучистый идол', 'Бронзовый скарабей', 'Скарабей из слоновой кости');
