INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8728, 'Хорошая новость и плохая новость', 'Что же, это оказалось дольше, чем я думал. Давай-ка посмотрим, что написано в этой книге.$B$B<Нарайн молча читает книгу, периодически что-то бормоча себе под нос.>$B$BХорошая новость – я на 99% уверен, что смогу сделать арканитовый буй, который будет работать согласно твоим требованиям. А вот это полностью зависит от плохих новостей.$B$BПлохие новости заключаются в том, что мне понадобится куча арканита, элементиевой руды и редких самоцветов.$B$BПринеси мне все, что надо, и я сделаю буй.', 'Нарайн Причуддень из Танариса хочет, чтобы вы принесли ему 20 арканитовых слитков, 10 кусков элементиевой руды, 10 азеротских бриллиантов и 10 синих сапфиров.', 'Уговор есть уговор. Надеюсь, вы знаете, во что лезете, $N. Это вам не жук чихнул – рыбку ловить!', 'Арканитовые буйки сами собой не делаются, $N. НЕТ, денег взаймы не дам.', NULL, NULL, 'Арканитовый слиток', 'Элементиевая руда', 'Азеротский алмаз', 'Синий сапфир');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8729, 'Гнев Нептулона', 'Я еще не говорил о плохой новости, нет? Ее зовут Каракула – 30 метров смерти и разрушения. Наверное, я забыл об этой мелочи.$B$BМое сверхпсихопсионическое ясновидение говорит мне, что лучше всего будет закинуть буек с берега Азшары, в залив Бурь.$B$BВысматривай водоворот, в котором скорее всего будет до кучи обломков кораблей.$B$BКстати, надеюсь, не в одиночку пойдешь?$B$BЕсли тебе каким-то чудесным образом повезет, отнеси обломок скипетра Анахроносу.', 'Забросьте арканитовый буй в водоворот в заливе Бурь Азшары.', 'Славно, $N. Скоро я сумею воссоздать скипетр Зыбучих Песков.', 'Время на исходе!', NULL, NULL, 'Осколки синего скипетра', 'Арканитовый буй', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8730, 'Порча Нефария', 'Надо же, герой! Тысячу лет назад мне поручили хранить осколок, и вот, в черный час он был отнят у меня... Но какая же трагедия без жестокости?$B$B<Валестраз слабо кашляет.>$B$BОс... осколок скипетра ныне у Нефария.$B$BВремя дорого, ибо Нефарий намерен уничтожить осколок. Поторопись!', 'Убейте Нефариана и добудьте осколок красного скипетра. Верните осколок красного скипетра Анахроносу в Пещеры Времени в Танарис. На выполнение задания у вас есть 5 часов.', 'Душа Веластраса ныне спокойна, герой. Все Аспекты следят за твоими успехами с великим интересом. Знай – у тебя могучие союзники.$B$BМне было приказано даровать тебе нечто, способное помочь тебе в твоей борьбе. Воспользуйся этим во благо...', 'И еще один наш герой пал жертвой отродья Смертокрыла. Когда же окончатся наши страданья...', NULL, NULL, 'Осколок красного скипетра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8731, 'Рутинное задание', 'Приветствую тебя, $N. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.$B$BЛегион Оргриммара под предводительством капитана Крушителя Черепов расквартирован рядом с Ульем Регал.$B$BПоговори с капитаном и принеси мне доказательство выполнения его указаний. Тем временем я подготовлю для тебя новое задание.$B$BАх да, сделай одолжение, держись подальше от дружины Стальгорна. Добровольцы Орды и Альянса постоянно грызутся друг с другом.', 'Поступите в распоряжение легиона Оргриммара возле улья Регал. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях, отнесите их призывателю ветров Калдону в крепость Кенария.Внимание: исцеление или наложение благоприятных заклинаний на бойцов легиона Оргриммара переводит в режим PvP.', 'Сразу видно, что Круг немного внимания уделяет писанине. Он подписал эти бумаги кровью силитидов!$B$BХорошо, $N. Я подготовил для тебя задания, которые наилучшим образом используют твои способности, $C.$B$BЕсли ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!', 'Ты выполнил задание, $N? Капитан Расколотый Череп – рядом с Ульем Регал.', NULL, NULL, 'Подписанные бумаги о полевых обязанностях', 'Неподписанные бумаги о полевых обязанностях', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8732, 'Бумаги о полевых обязанностях', '', 'Бумаги о полевых обязанностях? Что за чушь, $N?', 'В старые добрые дни в доказательство выполненного долга я пометил бы твой лоб кровью. Тралл же велит слушаться друидов.$B$BВозьми бумаги и отнеси их в крепость Кенария. Не сомневаюсь, они найдут для тебя подходящую работу.', NULL, NULL, NULL, 'Готовые бумаги о полевых обязанностях', 'Подписанные бумаги о полевых обязанностях', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8733, 'Эраникус, Тиран Сна', 'Это будет расплата, $gгерой:героиня:. Если я сегодня погибну, то паду я за правое дело. Верни осколок зеленого жезла. Освободи Эраникуса от порчи, которой поразили его Древние боги.$B$BОтправляйся в Дарнас. Прямо у стен города ты встретишь одного из моих агентов. Он даст ход нашим делам и оповестит Тиранду о наших планах так, чтобы не прознал Олений Шлем.$B$B<Малфурион вздыхает.>$B$BУтратить милость тысячелетий...', 'Отправляйтесь на континент Тельдрассил и найдите агента Малфуриона у стен Дарнаса.', 'Огонек молчит, только иногда тихо жужжит. Странно, но он способен ощаться с вами мысленно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8734, 'Тиранда и Ремул', 'Тиранда будет извещена, $gмертный:смертная:. Шан\'до Ярость Бури подготовил меня к неожиданностям.$B$BТеперь тебе надлежит отправиться на Лунную поляну и поговорить с хранителем Ремулом. Он даст тебе дальнейшие инструкции по поводу того, как вызвать Эраникуса.$B$BМы все желаем тебе великой удачи.', 'Отправляйтесь на Лунную поляну и поговорите с хранителем Ремулом.', 'Невозможно будет выманить Эраникуса из Сна, если он того не пожелает. Однако, его намерения заставят его прийти в наш мир. Он жаждет уничтожить живое проявление Малфуриона. Если мы добьемся успеха, это может погубить одного из самых могучих союзников Сна. Кошмар полностью поглотит все, что еще сохранилось, если Малфурион падет...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8735, 'Порча Кошмара', 'Тебе нужно оправиться к четырем порталам сна Азерота. Из каждого ты добудешь фрагмент порчи Кошмара. Дракониды, населяющие те места, не будут их отдавать. Возвращайся, когда добудешь все фрагменты.', 'Отправьтесь к четырем порталам Сна Азерота и добудьте фрагменты порчи Кошмара из каждого из них. Вернитесь к хранителю Ремулу на Лунную поляну по завершении задания.', 'Готова ли ты? Готов ли мир встретить то, что мы собираемся призвать? Я не знаю... У меня есть долг перед Малфурионом. Я связан долгом и честью...', '*Ремулос находится в глубокой задумчивости.*', NULL, NULL, 'Фрагмент порчи Кошмара', 'Фрагмент порчи Кошмара', 'Фрагмент порчи Кошмара', 'Фрагмент порчи Кошмара');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8736, 'Явление Кошмара', 'Мы должны усмирить Эраникуса. Мы не можем позволить ему уничтожить себя!$B$BТиранда уже идет нам на помощь. Мы должны отбить удары дракона и спасти Ночную гавань от неминуемого уничтожения.$B$BСтой на страже! Ты и твои союзники – наша единственная надежда.', 'Защитите Ночную гавань от Эраникуса. Не дайте погибнуть хранителю Ремулу. Не убивайте Эраникуса. Защищайте себя. Дождитесь Тиранды.', 'Он пришел в себя, $N. Ныне он возвращается в Сон, дабы исправить тот вред, что причинил. Эраникус станет могучим союзником Малфуриону и моему отцу.$B$BПрими эти доспехи, $N, они подарены мне самой Изерой. Они пригодятся тебе в сражении с киражами.', NULL, NULL, NULL, 'Избавление Эраникуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8737, 'Лазурный храмовник', 'Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан\'Кираже, мы не должны терять бдительность и давать волю внешним врагам.$B$BОтыщи способ вызвать и уничтожить лазурного храмовника и доложи о выполнении задания Бору Буйногривому.', 'Призовите и убейте лазурного храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу I.', 'Отличная работа, $N. Вот следующее задание.', 'Ты уже выполнил задание?', NULL, NULL, 'Лазурный храмовник убито', 'Краткое изложение тактической задачи I (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8738, 'Донесение разведчика из Улья Регал', 'Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Ландион уже несколько дней наблюдает за передвижениями этих насекомых. Найди его и забери у него письменный отчет. Нам необходимо как можно скорее получить собранные сведения.', 'Свяжитесь с разведчиком Кенария Ландионом в улье Регал и отнесите донесение разведчика из улья Регал призывательнице ветров Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VII.', 'Мы очень ценим твои усилия, $N. Я немедленно займусь этими донесениями, а ты можешь переходить к следующему заданию.', 'Разведчик Ландион находится внутри Улья Регал. Спеши, $N! Время не ждет.', NULL, NULL, 'Донесение разведчика из Улья Регал', 'Краткое изложение тактической задачи VII (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8739, 'Донесение разведчика из Улья Аши', 'Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Джалия уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить собранные сведения.', 'Свяжитесь с разведчиком Кенария Джалией в улье Аши и отнесите донесение разведчика призывательнице ветров Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VIII.', 'Мы очень ценим твои усилия, $N. Я немедленно займусь этим донесением, а ты можешь переходить к следующему заданию.', 'Разведчик Джалия находится внутри Улья Аши. Спеши, $N! Время не ждет.', NULL, NULL, 'Донесение разведчика из Улья Аши', 'Краткое изложение тактической задачи VIII (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8740, 'Сумеречные мародеры', 'В последнее время появились верховые отряды сторонников Сумеречного Молота. Они не суются в земли, охраняемые крепостью Кенария, а грабят небольшие караваны и отряды.$B$BНайди и убей сумеречных мародеров, а заодно и их лидера, воительницу по имени Морна. О выполнении задания доложи призывательнице ветров Гордый Рог.', 'Убейте сумеречного мародера Морну и двух сумеречных мародеров. Доложите о выполнении задания призывательнице ветров Гордый Рог. Кроме того, сдайте тактическую задачу IX.', 'Молодец, $N. Сумеречные мародеры причинили нам множество неприятностей. Мириться с ними было нельзя. Вот тебе следующее задание.', 'Ты уже выполнил задание?', NULL, NULL, 'Сумеречный мародер Морна убито', 'Сумеречный мародер убито', 'Краткое изложение тактической задачи IX (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8741, 'Возвращение победителя', 'Хранитель ждет твоего возвращения, $N. Отнеси этот осколок зеленого скипетра Анахроносу в Пещеры Времени.', 'Отнесите осколок зеленого скипетра Анахроносу в Пещеры Времени в Танарисе.', 'Твои деяния станут всем известны. Тебя будут славить в песнях от Оргриммара до дальних пределов Южных морей. Все узнают о поборнике Бронзовых драконов, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8742, 'Армия Калимдора', '', '', 'Миновала тысяча лет и, как и было предрешено, ныне предо мной стоит избранница судьбы. Та, кто поведет свой народ в новый век.Древний бог трепещет, $N. Да, он боится твоей веры. Ниспровергни пророчество К\'Туна.Он знает, что ты идешь, избранница – и с тобой идет вся мощь Калимдора. Скажи мне, когда будешь готова, и я отдам тебе скипетр Зыбучих Песков.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8743, 'Бей в гонг!', '', 'Гонг Скарабея зловеще нависает над тобой. Крепись духом, $N – как только гонг Скарабея загудит, врата Ан\'Киража откроются.Дряхлая пасть этого зверя может извергнуть только хаос и разрушение. Защити свой народ!', 'Из земли рядом с гонгом торчит особенный кристалл. Возможно, это подарок племени Ноздорму.', NULL, NULL, NULL, 'Скипетр Зыбучих Песков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8744, 'Тщательно завернутый подарок', '', '', 'Надпись на подарке гласит:Дорогому $N.Желаю счастливого праздника Зимнего Покрова.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8745, 'Сокровище Вневременного', '', 'Привет тебе, избранник. Я Джонатан, хранитель священного гонга и вечный страж Бронзовых драконов.Вневременной дал мне право даровать тебе один предмет на выбор из его клада вне времен. Да поможет он тебе в битве с К\'Туном.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8746, 'Метцен-северный олень', 'БЕДА! Похищен Метцен – северный олень!$B$BМетцен – один из восьми оленей Дедушки Зимы и собственность \"Пастбищ Дымного Леса\". Мы получили целых ДВА письма с требованием выкупа от двух шаек, каждая из которых утверждает, что олень у них. Праздники в разгаре, мы не можем бросить дела! Пожалуйста, найди Метцена и верни его нам!$B$BВозьми эти письма с требованием выкупа – может, найдешь в них подсказку. Когда найдешь, посыпь северного оленя вот этой пылью, и он освободится от любых пут!$B$BПрошу, поспеши!', 'Найдите Метцена – северного оленя, пользуясь подсказками из писем.Не забудьте взять мешочек с пылью северного оленя, чтобы осыпать Метцена этой пылью.Освободив Метцена, верните мешочек с пылью северного оленя Каймарду Меднокнопу в Оргриммаре.', 'Ур-ра! Получилось!$B$BМетцен буквально только что пр$Nел обратно в свои стойла! Да-да, конечно же, Метцен умеет летать. Пыль сработала отлично! Я так и знал! Ты буквально спас нас – и не только праздник Зимнего Покрова, но и сами \"Пастбища Дымного Леса\"! Спасибо тебе, Кусяй.$B$BПослушай... За свои труды ты заслуживаешь награды. Вот, держи. Это не просто приправа. Если когда-нибудь у тебя будет верховое животное, эта штука тебе пригодится. Счастливого Зимнего Покрова!', '$N! Ну что, помогли тебе эти записки? Метцен нашелся? Страшно подумать, что могли сделать с ним эти бессердечные головорезы... Но мы просто не могли выплатить такой запредельный выкуп!', NULL, NULL, 'Найдите и спасите Метцена – северного оленя', 'Прах с копыт северного оленя', 'Сумка Пастбищ Дымного Леса', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8747, 'Путь защитника', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
