INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8751, 'Защитник Калимдора', '', 'Никогда прежде мне не случалось видеть такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременной!Дай мне свой перстень, и я наложу на него еще одно заклятье.', 'Хвала тебе, Защитник Калимдора! Великая тебе хвала!', NULL, NULL, NULL, 'Перстень-печатка Бронзовых драконов', NULL, NULL, NULL);
