INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8761, 'Великий заклинатель', '', '', 'Хвала тебе, Великий заклинатель! Великая тебе хвала!', NULL, NULL, NULL, 'Перстень-печатка Бронзовых драконов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8762, 'Метцен-северный олень', 'БЕДА! Похищен Метцен-северный олень!$B$BМетцен – один из восьми оленей Дедушки Зимы и принадлежит Пастбищам Дымного Леса. Мы получили не одно, а ДВА письма с требованием выкупа от двух шаек, каждая из которых утверждает, что олень у них. Праздники в разгаре, мы не можем бросить дела! Пожалуйста, найди Метцена и верни его нам!$B$BВозьми эти письма с требованием выкупа, – может, найдешь в них подсказку, – а вот этой пылью посыпь северного оленя, и он освободится от любых пут!$B$BПрошу, поспеши!', 'Пользуясь подсказками из писем, найдите, где злоумышленники прячут Метцена-северного оленя.Не забудьте захватить мешочек с прахом с копыт северного оленя, чтобы освободить Метцена от пут.После освобождения оленя верните мешочек Вулморту Деньгозвону в Стальгорн.', 'Ты это сделал! Ура-а-а!$B$BМетцен совсем недавно пр$Nел обратно в свои стойла – да-да, Метцен умеет летать! Эта пыль сработала чудодейственно, я так и знал! Ты спас не только праздник Зимнего Покрова, но и Пастбища Дымного Леса! Спасибо тебе, $N.$B$BСлушай... за твои великие дела хочу дать тебе вот это. Это нечто ОСОБЕННОЕ – если ты заведешь себе верховое животное, эта штука тебе пригодится. Счастливого Зимнего Покрова!', '$N! Тех записок в сумке, что я тебе дал, оказалось достаточно для обнаружения Метцена? Страшно подумать, что могли сделать с ним эти бессердечные головорезы... Но мы просто не могли выплатить такой запредельный выкуп!', NULL, NULL, 'Найдите и спасите Метцена – северного оленя', 'Прах с копыт северного оленя', 'Сумка Пастбищ Дымного Леса', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8763, 'Герой дня', 'Слушай... Вообще-то тебе об этом знать не полагается, но, раз уж ты $gгерой:героиня: дня и все такое…$B$BВ это время года повсюду полно свежего остролиста, но он быстро вянет. У нас есть машинка, которая заготовляет остролист таким образом, что он не портится! Знаешь, почем его можно продать летом?$B$BЯ разрешу тебе воспользоваться сушилкой, но только если ты мастер-кулинар. От тебя потребуется некоторое количество глубокоскальной соли и два-три... ну, скажем, пять золотых. И ты получишь славную партию остролиста, которую можно хранить сколько угодно.', 'Принесите 1 порцию глубокоскальной соли и 5 золотых монет к любой сушилке для остролиста, чтобы получить 5 сушеных остролистов.', 'Машина при начале работы тихонько гудит и выпускает облачко пара. Вскоре она останавливается, и из нее выходит еще одна струйка пара. Дверца открывается, а за ней – партия сушеного остролиста!', 'На первый взгляд, сушилка для остролиста напоминает нечто вроде перегонного куба, но, если вглядеться повнимательнее, становится видно, что в основную конструкцию внесены типично гоблинские изменения. Тем не менее вы – достаточно опытный кулинар, чтобы разобраться, как работает эта машина.$B$BСвежий остролист в машину уже загружен – нужно только добавить глубокоскальной соли и пять золотых монет, и машинка заработает.', NULL, NULL, 'Глубокоскальная соль', 'Требуется денег: 5', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8764, 'Изменение пути – уже не защитник', '', '', '', NULL, NULL, NULL, 'Перстень-печатка Бронзовых драконов', 'Каменный скарабей', 'Золотой скарабей', 'Серебряный скарабей');
