INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8766, 'Изменение пути – уже не победитель', '', '', '', NULL, NULL, NULL, 'Перстень-печатка Бронзовых драконов', 'Костяной скарабей', 'Скарабей из слоновой кости', 'Каменный скарабей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8767, 'Слегка помятый подарок', '', '', 'Похоже, этот подарок несколько раз встряхнули. Ярлычок гласит:Самому любимому $r.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8768, 'Подарок в яркой упаковке', '', '', 'На нарядно упакованном подарке стоит ваше имя.Стойте, он шевельнулся или показалось?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8769, 'Тикающий подарок', '', '', 'Пожелание счастливого праздника Зимнего Покрова от друзей с пастбищ Дымного леса.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8770, 'Цель: защитники из Улья Аши', 'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут защитники из этого улья.$B$BВыполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 защитников из улья Аши и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу I.', 'Отличная работа, $N. Мы не забудем твоих усилий.', 'Ты хочешь что-то сказать, $C?', NULL, NULL, 'Защитник из улья Аши убито', 'Изложение боевой задачи I (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8771, 'Цель: песчаные ловцы из улья Аши', 'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут песчаные ловцы из этого улья.$B$BВыполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 песчаных ловцов из улья Аши и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу II.', 'Отличная работа, $N. Твои подвиги в сражении при Улье Аши не прошли незамеченными.', 'Ты хочешь что-то сказать, $C?', NULL, NULL, 'Песчаный ловец из улья Аши убито', 'Изложение боевой задачи II (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8772, 'Цель: стражи дорог из Улья Зора', 'Мы вызвали подкрепление для сражения у улья Зора. Твоя задача – убить как можно больше стражей дорог. Выполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 стражей дорог из улья Зора и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу VI.', 'Отличная работа, $N. Твои подвиги в сражении при Улье Зора не прошли незамеченными.', 'Ты хочешь что-то сказать, $C?', NULL, NULL, 'Страж дорог из улья Зора убито', 'Изложение боевой задачи VI (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8773, 'Цель: разрушители из Улья Зора', 'Мы вызвали подкрепление для сражения у улья Зора. Твоя задача – убить как можно больше разрушителей. Выполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 разрушителей из улья Зора и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи IV.', 'Я слышал немало добрых слов о твоем участии в нападении на Улей Зора. Продолжай в том же духе, и победа будет за нами.', 'Ты хочешь что-то сказать, $C?', NULL, NULL, 'Разоритель из улья Зора убито', 'Изложение боевой задачи IV (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8774, 'Цель: стерегущие из Улья Регал', 'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Регал. Твоей основной целью будут стерегущие из этого улья.$B$BВыполнив задание, отчитайся поговори с командором Мар\'алитом.', 'Убейте 30 стерегущих из улья Регал и доложите об этом командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи VIII.', 'Отличная работа, $N. Твои подвиги в сражении при Улье Регал не прошли незамеченными.', 'О чем ты хочешь рассказать, $N?', NULL, NULL, 'Душитель из улья Регал убито', 'Изложение боевой задачи VIII (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8775, 'Цель: огнеполохи из улья Регал', 'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Регал. Твоей основной целью будут злюки из этого улья.$B$BВыполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 огнеполохов из улья Регал и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу IX.', 'Отличная работа, $N. Твои подвиги в сражении при Улье Регал не прошли незамеченными.', 'О чем ты хочешь рассказать, $N?', NULL, NULL, 'Огнеполох из улья Регал убито', 'Изложение боевой задачи IX (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8776, 'Цель: поработители из улья Регал', 'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Регал. Твоей основной целью будут поработители из этого улья.$B$BВыполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 поработителей из улья Регал и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу X.', 'Отличная работа, $N. Твои подвиги в сражении при Улье Регал не прошли незамеченными.', 'О чем ты хочешь рассказать, $N?', NULL, NULL, 'Поработитель из улья Регал убито', 'Изложение боевой задачи X (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8777, 'Цель: землерои из Улья Регал', 'По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Регал. Твоей основной целью будут землерои из этого улья.$B$BВыполнив задание, поговори с командором Мар\'алитом.', 'Убейте 30 землероев из улья Регал и доложите о выполнении задания командору Мар\'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XI.', 'Отличная работа, $N. Твои подвиги в сражении при Улье Регал не прошли незамеченными.', 'О чем ты хочешь рассказать, $N?', NULL, NULL, 'Землеглот из улья Регал убито', 'Изложение боевой задачи XI (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8778, 'Взрывчатка для дружины Стальгорна', 'Стальгорнская дружина прислала необычный запрос – на весьма... э-э-э... неустойчивые вещества. Собери их и принеси господину Форсунчику из Стальгорнской дружины.', 'Принесите 6 бутылок воспламеняющей смеси, 5 бочонков гоблинского ракетного топлива и 10 порций концентрированного взрывчатого вещества чародею Форсунчику возле улья Зора в Силитусе. Кроме того, принесите тыловое задание IV.', 'Ах, да! Они очень пригодятся! Большое спасибо, $N!', 'Что ты мне принес, $N?', NULL, NULL, 'Воспламеняющая смесь', 'Гоблинское ракетное топливо', 'Концентрированное взрывчатое вещество', 'Краткий обзор задач перевозок IV (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8779, 'Материалы для гадания', 'Исследования геолога Ехидной имели огромное значение для нашей кампании в Силитусе. Недавно она запросила материалы для своего исследования.$B$BПожалуйста, собери все необходимое и отнеси ей. Пусть она продолжает работу.', 'Принесите 1 большой сияющий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Ехидной в крепость Кенария в Силитусе. Также принесите тыловое задание V.', 'О да... Ты мне очень помог! Достать эти материалы в пустыне невероятно сложно. Спасибо, $N.', 'Что ты мне принес, $N?', NULL, NULL, 'Большой сверкающий осколок', 'Большой светозарный осколок', 'Огромный изумруд', 'Краткий обзор задач перевозок V (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8780, 'Комплекты брони', 'У дружины Стальгорна на исходе запасы комплектов брони. Добудь партию таких комплектов и отнеси их Джанеле Твердомолот на заставу дружины Стальгорна, что рядом с Ульем Зора.', 'Принесите 8 комплектов грубой брони и 8 накладок из толстой кожи Джанеле Твердомолот на заставу дружины Стальгорна возле улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VII.', 'Спасибо, я передам их нашим ребятам.', 'Что ты мне принес, $N?', NULL, NULL, 'Комплект грубой брони', 'Накладки из толстой кожи', 'Краткий обзор задач перевозок VII (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8781, 'Нехватка оружия', 'Дружина Стальгорна оказалась чрезвычайно полезным союзником в наших битвах в Силитусе. К сожалению, по пути они растеряли много припасов и оборудования. Добудь партию оружия и доставь ее Джанеле Твердомолот к Улью Зора.', 'Принесите 2 палаша из лунной стали Джанеле Твердомолот на заставу дружины Стальгорна возле улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VI.', 'Отлично! Мне не придется выслушивать жалобы на тупые клинки. Спасибо, $N.', 'Что ты мне принес, $N?', NULL, NULL, 'Палаш из лунной стали', 'Краткий обзор задач перевозок VI (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8782, 'Поставки формы', 'У нас такой приток добровольцев, что не хватает формы. Принеси материалы для пошива формы и отдай их призывательнице ветров Гордый Рог.', 'Принесите 1 кусок луноткани, 2 рулона рунической ткани и 1 железношелковую паутину призывательнице ветров Гордый Рог в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII.', 'А, да, нам их очень не хватало. Спасибо за добрую службу, $N.', 'Что ты мне принес, $N?', NULL, NULL, 'Луноткань', 'Рулон рунической ткани', 'Железношелковая паутина', 'Краткий обзор задач перевозок VIII (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8783, 'Необычные материалы', 'Варгус, кузнец крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат. Добудь все необходимое и отнеси их Варгусу в крепость Кенария, чтобы он снабдил войска всем необходимым.', 'Принесите Варгусу из крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX.', 'Да-да. Превосходные материалы. Спасибо, $N.', 'Что ты мне принес, $N?', NULL, NULL, 'Зачарованный ториевый слиток', 'Зачарованная кожа', 'Краткий обзор задач перевозок IX (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8784, 'Секреты Кираи', 'Вам удалось обнаружить древний киражский артефакт! Возможно, один из драконов, стоящих в храме недалеко от входа, сможет найти применение этой реликвии.', 'Принесите древний киражский артефакт драконам, которые укрылись в храме, недалеко от входа.', 'Какая поразительная находка, $N. Просто изумительная! Определенно, она поможет нам проникнуть в извращенные умы наших врагов.', 'Ты весь светишься! Я знаю, что это значит...', NULL, NULL, 'Древний киражский артефакт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8785, 'Амулеты для легиона Оргриммара', 'Легион Оргриммара послал запрос на несколько необычные вещества. Учитывая, как хорошо они проявили себя в Силитусе, мы бы хотели как можно скорее выполнить их просьбу. Собери материалы и отнеси их троллихе по имени Шаи.', 'Принесите 6 мощных амулетов, 6 бутылей большого колдунства и 8 бутылок воспламеняющей смеси жрице Тьмы Шаи к улью Регал в Силитус. Кроме того, принесите тыловое задание IV.', 'Ах, да. То что нужно! Из этих веществ я сделаю особое зелье. Оно оч-чень не понравится силитидам!', 'Ты принес мне все материалы?', NULL, NULL, 'Воспламеняющая смесь', 'Настой большого колдунства', 'Мощный амулет', 'Краткий обзор задач перевозок IV (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8786, 'Нехватка оружия', 'Легион Оргриммара послал запрос на поставку оружия, а его нет на складе! Добудь необходимое снаряжение и отнеси его Мероку Долгому Шагу к Улью Регал.', 'Принесите 3 массивных железных топора Мероку Долгому Шагу в лагерь легиона Оргриммара рядом с ульем Регал. Кроме того, сдайте тыловую задачу VI.', 'Отличная работа. Нам очень не хватало оружия.', 'Что ты мне принесла, $N?', NULL, NULL, 'Массивный железный топор', 'Краткий обзор задач перевозок VI (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8787, 'Комплекты брони', 'В Силитус, к нам на подмогу, прибыли отважные добровольцы из легиона Оргриммара. По пути они растеряли свои запасы накладок на доспехи. Добудь партию таких комплектов и отнеси их Мероку Долгому Шагу, в лагерь легиона Оргриммара.', 'Принесите 8 комплектов грубой брони и 8 накладок из толстой кожи Мероку Долгому Шагу к улью Регал. Кроме того, сдайте тыловую задачу VII.', 'Отлично... Я раздам все комплекты солдатам. Легион Оргриммара благодарит тебя, $N!', 'Что ты мне принесла, $N?', NULL, NULL, 'Комплект грубой брони', 'Накладки из толстой кожи', 'Краткий обзор задач перевозок VII (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8788, 'Слегка помятый подарок', '', '', 'Похоже, этот подарок несколько раз встряхнули. Ярлычок гласит:Самому любимому $r .', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8789, 'Киражское императорское оружие', 'Мы не то чтобы просто сидели здесь на протяжении тысячелетий, $N.$B$BМы наблюдали за торжеством этих тварей, пока они пировали и истощали свои ресурсы. Мы слушали, как они строят схемы и планы по уничтожению нашего мира. Мы узнали о предателях в их рядах.$B$BУ них есть слабости, и теперь мы знаем, как их использовать.$B$BНайди и принеси мне их церемониальное оружие. В сочетании с предметами, созданными непостоянством их собственного бога, оно станет силой, с которой придется считаться любому.', 'Аригос в Храме Ан\'Киража создаст для вас усиленное элементием оружие, если вы принесете ему киражское имперское оружие и 3 куска элементиевой руды.', 'Это оружие, усиленное элементием, одинаково легко пронзит как обычного кираи, так и их бога.', 'Найди то, что мне нужно, и ты станешь чем-то большим, чем сумма составляющих твою личность элементов, защитник.', NULL, NULL, 'Киражское императорское оружие', 'Элементиевая руда', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8790, 'Киражские императорские регалии', 'Аригос предполагает, что элемент, рожденный в результате столкновения между Древними Богами и их прислужниками, в надлежащих условиях станет для них смертельным. Я имею в виду элементий, $gсмертный:смертная:.$B$BПринеси мне киражские императорские регалии и это вещество-яд, я и смогу создать оружие, обладающее великой силой.', 'Меритра из Сна в Храме Ан\'Киража может создать для вас усиленное элементием оружие, если вы принесете ей киражские имперские регалии и 3 куска элементиевой руды.', '', NULL, NULL, NULL, 'Киражские монаршие регалии', 'Элементиевая руда', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8791, 'Повергнутый Оссириан', 'Смертельная угроза больше не нависает над нами. Безжалостный Оссириан повержен!$B$BОб этой победе должны узнать все жители Калимдора. Отнесите голову Оссириана командору Мар\'алиту в крепость Кенария.', 'Принесите голову Оссириана Неуязвимого командору Мар\'алиту в крепость Кенария.', 'Выражаю тебе нашу наиглубочайшую благодарность. Ты оказала огромную услугу жителям Калимдора. Можешь выбрать один из этих амулетов, $N.', 'О, $N, ты уже вернулась! Целой и невредимой, могу добавить. Ну, какие новости из Ан\'Киража?', NULL, NULL, 'Голова Оссириана Неуязвимого (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8792, 'Орде нужна твоя помощь!', 'Приветствую, я рада, что ты $gрешил:решила: поговорить со мной. Если мы хотим достойно подготовиться к ан\'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не следует оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, $N!$B$BПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, $C? Примешь участие в этом жизненно важном деле?', 'Поговорите с вождем Горчуком на аллее Духов Оргриммара.', 'Тром\'ка, $C! Приятно видеть, что многие вроде тебя, Сокрушунг, решили помочь Орде в предстоящей ан\'киражской заварухе. Она будет грандиозной, не сомневайся. Пока наши усилия вселяют надежду, что мы одолеем силитидов и их злобных правителей, которые засели в Ан\'Кираже. $B$BРаз уж ты принял решение, можешь помогать запасать любые материалы, которые тебе будет проще раздобыть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8793, 'Орде нужна твоя помощь!', 'Приветствую! Хорошо, что ты $gрешил:решила: поговорить со мной. Если мы хотим достойно подготовиться к ан\'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не следует оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, $N!$B$BПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, $C? Примешь участие в этом жизненно важном деле?', 'Поговорите с вождем Горчуком на аллее Духов Оргриммара..', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8794, 'Орде нужна твоя помощь!', 'Приветствую! Хорошо, что ты $gрешил:решила: поговорить со мной. Если мы хотим достойно подготовиться к ан\'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не следует оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, $N!$B$BПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, $C? Примешь участие в этом жизненно важном деле?', 'Поговорите с вождем Горчуком на аллее Духов Оргриммара.', 'Тром\'ка, $C! Приятно видеть, что многие вроде тебя, $N, решили помочь Орде в предстоящей ан\'киражской заварухе. Она будет грандиозной, не сомневайся. Пока наши усилия вселяют надежду, что мы одолеем силитидов и их злобных правителей, которые засели в Ан\'Кираже. $B$BРаз уж ты принял решение, можешь помогать запасать любые материалы, которые тебе будет проще раздобыть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8795, 'Альянсу нужна твоя помощь!', 'Приветствую. Хорошо, что ты $gрешил:решила: поговорить со мной. В подготовке к войне в Ан\'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи простых граждан им не справиться, $N!$B$BЕсли хочешь поддержать Альянс, обратись с фельдмаршалу Снежной Лавине, который отвечает за сбор ресурсов. Что скажешь, $C? Примешь ли ты участие в этом жизненно важном деле?', 'Поговорите с фельдмаршалом Снежной Лавиной, который находится в Палатах войны Стальгорна.', 'Приветствую тебя и желаю удачи, юноша! Как хорошо, что в Альянсе есть люди вроде тебя, $N. Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан\'Кираже. Если мы объединим наши усилия, то наверняка сможем выковырять мерзких силитидов из их укрытия. $B$BНе стесняйся предложить свою помощь лицам, ответственным за сбор материалов, которые тебе легче раздобыть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8796, 'Альянсу нужна твоя помощь!', 'Приветствую. Хорошо, что ты $gрешил:решила: поговорить со мной. В подготовке к войне в Ан\'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи простых граждан им не справиться, $N!$B$BЕсли хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за сбор ресурсов. Что скажешь, $C? Примешь ли ты участие в этом жизненно важном деле?', 'Поговорите с фельдмаршалом Снежной Лавиной, который находится в Палатах войны Стальгорна.', 'Приветствую тебя и желаю удачи, юноша! Как хорошо, что в Альянсе есть люди вроде тебя, Оксиморон. Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан\'Кираже. Если мы объединим наши усилия, то наверняка сможем выковырять мерзких силитидов из их укрытия. $B$BНе стесняйся предложить свою помощь лицам, ответственным за сбор материалов, которые тебе легче раздобыть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8797, 'Альянсу нужна твоя помощь!', 'Приветствую. Хорошо, что ты $gрешил:решила: поговорить со мной. В подготовке к войне в Ан\'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи простых граждан им не справиться, $N!$B$BЕсли хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за сбор ресурсов. Что скажешь, $C? Примешь ли ты участие в этом жизненно важном деле?', 'Поговорите с фельдмаршалом Снежной Лавиной, который находится в Палатах войны Стальгорна.', 'Приветствую тебя и желаю удачи, юноша! Как хорошо, что в Альянсе есть люди вроде тебя, $N. Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан\'Кираже. Если мы объединим наши усилия, то наверняка сможем выковырять мерзких силитидов из их укрытия. $B$BНе стесняйся предложить свою помощь лицам, ответственным за сбор материалов, которые тебе легче раздобыть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8798, 'Твой собственный Йети', '', '', 'Ух ты! Да ты оказывается, тоже инженер! Раз ты помог мне разыграть моих друзей, я в ответ научу тебя, как создать своего собственного механического йети, чтобы ты смог продолжить забаву и напугать кого и когда захочешь. Главное, чтобы тебе удалось достать все необходимые компоненты.Ну так что, $N? Хочешь научиться делать механических йети?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8799, 'Герой дня', 'Слушай... Вообще-то тебе об этом знать не полагается, но, раз уж ты герой дня и все такое…$B$BВ это время года повсюду полно свежего остролиста, но он быстро вянет. У нас есть машинка, которая заготовляет остролист таким образом, что он не портится! Знаешь, почем его можно продать летом?$B$BЯ разрешу тебе воспользоваться сушилкой, но только если ты мастер-кулинар. От тебя потребуется некоторое количество глубокоскальной соли и два-три... ну, скажем, пять золотых. И ты получишь славную партию остролиста, которую можно хранить сколько угодно.', 'Принесите 1 порцию глубокоскальной соли и 5 золотых монет к сушилке для остролиста, чтобы получить 5 сушеных остролистов.', 'Машинка издала негромкий рокот, выпустила облачко пара – и работа пошла! Вскоре она остановилась, выпустив еще одно облачко пара. Открывается дверка – и вот вам сушеный остролист!', 'На первый взгляд сушилка для остролиста напоминает нечто вроде перегонного куба, но, если вглядеться повнимательнее, становится видно, что в основную конструкцию внесены типично гоблинские изменения. Тем не менее вы – достаточно опытный кулинар, чтобы разобраться, как работает эта машина.$B$BСвежий остролист в машину уже загружен – нужно только добавить глубокоскальной соли и пять золотых, и машинка заработает.', NULL, NULL, 'Глубокоскальная соль', 'Требуется денег: 5', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8800, 'Броня Кенария', 'Выполнив все задания, обратись к Варгусу, кузнецу. Покажи ему все заработанные знаки, и получишь награду, в зависимости от твоей преданности нашему делу.', 'Поговорите с Варгусом в крепости Кенария в Силитусе.', 'Тебя прислал Калдон? Хорошо, посмотрим, чем я могу тебе помочь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8801, 'Наследие К\'Туна', 'Стены Ан\'Киража содрогаются. Сила зла, более древняя, чем сам этот мир, уничтожена.$B$BПри одном взгляде на лежащие перед вами мерзкие останки стынет сердце. Даже после смерти К\'Тун распространяет вокруг себя ауру зла.$B$BВам удалось совершить невозможное.$B$BВы извлекаете глаз и осторожно укладываете его в сумку.$B$BНужно доставить глаз К\'Туна в соседнюю залу и отдать драконам.', 'Принесите Глаз К\'Туна Келестрасу в Храм Ан\'Кирая.', 'Теперь мы можем покинуть это место, Госпожа $N. Великое зло полностью уничтожено, и ваши странствия, которые войдут в легенды, близятся к своему завершению.', '*Келестрас преклоняет перед вами колени*$B$BГоспожа $N, вы разбили наши оковы.', NULL, NULL, 'Око К\'Туна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8802, 'Спаситель Калимдора', 'Пришла пора вернуться в Пещеры Времени, $gгосподин:госпожа: $N. Анахронос ожидает тебя. Отдай ему глаз К\'Туна – не сомневаюсь, он непременно захочет поместить его в коллекцию своего хозяина.', 'Принесите глаз К\'Туна Анахроносу в Пещеры Времени.', 'Повелитель оставил это для вас, защитник. В тайнике безвременья хранятся бесценные артифакты. Можете выбрать, что пожелаете.', 'Госпожа $N! Все закончилось...', NULL, NULL, 'Око К\'Туна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8803, 'Подарок в разноцветной упаковке', '', '', 'Надпись на подарке гласит:Дорогому $N.Надеюсь, это поможет тебе нести мир и радость зимних дней всему Азероту.Твой Дедушка Зима.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8804, 'Неприкосновенный запас', 'В крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания в пустыне и отнеси их Каландрате в крепость Кенария.', 'Принесите 4 сферы воды, 4 мощных противоядия и 4 копченые пустынные клецки Каландрате в таверну в крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу I.', 'Отлично! Нам очень нужны эти материалы. Спасибо.', 'Что ты мне принесла, $N?', NULL, NULL, 'Магическая сфера воды', 'Мощное противоядие', 'Копченые пустынные клецки', 'Краткий обзор задач перевозок I (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8805, 'Сапоги для стражей', 'Верховому подразделению крепости Кенария не хватает изысканных мифриловых сапог. Принеси нам очередную партию и передай их капитану Вишу Коцусу из крепости Кенария.', 'Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II.', 'Отлично! Как раз то, что нужно. Спасибо.', 'Что ты мне принес, $N?', NULL, NULL, 'Изысканные мифриловые сапоги', 'Краткий обзор задач перевозок II (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8806, 'Шлифовальные камни', 'У стражи крепости Кенария на исходе шлифовальные камни. Добудь их и отнеси капитану Вишу Коцусу в крепость Кенария.', 'Принесите 10 массивных шлифовальных камней, 10 твердых шлифовальных камней и 10 тяжелых точильных камней Вишу Коцусу, капитану стражи в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III.', 'Отлично! Нам очень нужны эти материалы. Спасибо.', 'Что ты мне принесла, $N?', NULL, NULL, 'Массивный шлифовальный камень', 'Твердый шлифовальный камень', 'Тяжелый точильный камень', 'Краткий обзор задач перевозок III (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8807, 'Материалы для гадания', 'Исследования геолога Ехидной имели огромное значение для нашей кампании в Силитусе. Недавно она запросила материалы для своего исследования.$B$BПожалуйста, собери все необходимое и отнеси ей. Пусть она продолжает работу.', 'Принесите 1 большой сияющий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Ехидной в крепость Кенария в Силитусе. Также принесите тыловое задание V.', 'О да... Ты мне очень помогла! Достать эти материалы в пустыне невероятно сложно. Спасибо, $N.', 'Что ты мне принесла, $N?', NULL, NULL, 'Большой сверкающий осколок', 'Большой светозарный осколок', 'Огромный изумруд', 'Краткий обзор задач перевозок V (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8808, 'Поставки формы', 'У нас такой приток добровольцев, что не хватает формы. Принеси материалы для пошива формы и отдай их призывательнице ветров Гордый Рог.', 'Принесите 1 кусок луноткани, 2 рулона рунической ткани и 1 железношелковую паутину призывательнице ветров Гордый Рог в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII.', 'А, да, нам их очень не хватало. Спасибо за добрую службу, $N.', 'Что ты мне принесла, $N?', NULL, NULL, 'Луноткань', 'Рулон рунической ткани', 'Железношелковая паутина', 'Краткий обзор задач перевозок VIII (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8809, 'Необычные материалы', 'Варгус, кузнец крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат. Добудь все необходимое и отнеси их Варгусу в крепость Кенария, чтобы он снабдил войска всем необходимым.', 'Принесите Варгусу из крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX.', 'Да-да. Превосходные материалы. Спасибо, $N.', 'Что ты мне принесла, $N?', NULL, NULL, 'Зачарованный ториевый слиток', 'Зачарованная кожа', 'Краткий обзор задач перевозок IX (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8810, 'Запас бинтов', 'В последнее время мы понесли серьезные потери, и запас бинтов стремительно иссякает. Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордый Рог в крепость Кенария.', 'Принесите 30 плотных бинтов из рунической ткани, 30 плотных шелковых бинтов и 30 плотных бинтов из магической ткани призывательнице ветров Гордый Рог в крепость Кенария в Силитусе. Кроме того сдайте тыловую задачу X.', 'Ты как раз вовремя. Принесенные тобой перевязочные материалы спасут немало жизней. Мы благодарны тебе за труды. Вот твое следующее задание.', 'Что ты мне принесла, $N?', NULL, NULL, 'Плотные бинты из рунической ткани', 'Плотные бинты из магической ткани', 'Плотные шелковые бинты', 'Краткий обзор задач перевозок X (Прилагается)');
