INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8827, 'Подарки Дедушки Зимы', 'Говорят, что Дедушка Зима – не без помощи Пастбищ Дымного Леса – сложил под елку в Стальгорне подарки для всех. Я бы с радостью сходил туда, но мне надо присматривать за PX-238 Чудовольтом Мороза.$B$BА ты непременно туда загляни. Не сомневаюсь, Дедушка Зима и для тебя подарочек припас.', 'Поговорите с Дедушкой Зимой. Он находится в Стальгорне, неподалеку от торговой зоны Пастбищ Дымного Леса.', 'О-хо! Добро пожаловать! Я знаю, зачем ты пришел – открыть свой подарочек на Зимний Покров.$B$BНу-ну, не бойся, Дедушка Зима не забыл про своего любимого $r $c. Загляни под елочку, подарок тебя ждет-дожидается.$B$BКстати, раз уж все дарят друг другу подарки, не хочешь осчастливить своих друзей превосходными продуктами Пастбищ Дымного леса?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8828, 'Подарки Дедушки Зимы', 'Говорят, что Дедушка Зима – не без помощи Пастбищ Дымного леса – сложил под елку в Оргриммаре подарки для всех. Я бы с радостью сходил туда, но мне надо присматривать за PX-238 Чудовольтом Мороза.$B$BА ты непременно туда загляни. Не сомневаюсь, Дедушка Зима и для тебя подарочек припас.', 'Поговорите с Дедушкой Зимой. Он находится в Оргриммаре, неподалеку от торговой зоны Пастбищ Дымного Леса.', 'О-хо! Добро пожаловать! Я знаю, зачем ты пришел – открыть свой подарочек на Зимний Покров.$B$BНу-ну, не бойся, Дедушка Зима не забыл про своего любимого $C-$C. Загляни под елочку, подарок тебя ждет-дожидается.$B$BКстати, раз уж все дарят друг другу подарки, не хочешь осчастливить своих друзей превосходными продуктами Пастбищ Дымного леса?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8829, 'Последняя хитрость', 'Сумеречный Молот действует путем обмана и тайных наветов. Хотя они действуют в нашем мире, их идеи рождаются за его пределами, куда мы прежде не могли добраться.$B$BМы пришли к заключению, что камни, которыми главари Сумеречного Молота пользуются для призывания своих повелителей, работают в обе стороны. Чтобы попытаться воспользоваться ими подобным образом, мы должны изготовить точнейшую копию одеяния посланника культа Сумеречного Молота.$B$BСобери все необходимые материалы и отнеси их Аурэль Золотой Лист, $N.', 'Принесите шкуру тени, 3 обтрепанных куска поганища и 1 одеяние сумеречного сектанта Аурель Золотой Лист в крепость Кенария в Силитусе. Кроме того сдайте тыловую задачу XI.', 'Да, думаю, собранных тобой материалов хватит. Я окрашу это одеяние в цвета, которые носят посланники Сумеречного Молота. Да поможет Элуна вновь обмануть наших врагов.$B$BНо не беспокойся, когда ты выполнишь свою роль в этой игре, то получишь достойную награду. Ты верная и достойная союзница, $N.', 'Что ты мне принесла, $N?', NULL, NULL, 'Шкура тени', 'Истлевшая шовная нить поганища', 'Одеяние сумеречного заклинателя', 'Краткий обзор задач перевозок XI (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8830, 'Один рекомендательный жетон', '', '', 'Отлично – твои подвиги записаны, и тебе воздастся по заслугам. Продолжай в том же духе, $C!$B$BЕсли ты хочешь сдать еще несколько жетонов, я с радостью их приму.', NULL, NULL, NULL, 'Рекомендательный жетон Альянса', NULL, NULL, NULL);
