INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8846, 'Пять жетонов в обмен на припасы', '', 'А, хочешь пополнить припасы! Понимаю... В это легко поверить, если хорошенько оглядеться по сторонам.Я готов и в дальнейшем снабжать тебя припасами, но в обмен на них попрошу соответствующее количество рекомендательных жетонов. В таком случае ты не заслужишь признательности нашего народа, но зато получишь большие шансы выжить в грядущих битвах.', 'Что ж, договорились; забирайте припасы. Если вам понадобится еще, скажите мне, и я подготовлю соответствующий приказ.$B$BУдачи в трудах, $N. Нам не победить, не организовав достойное снабжение. Но если каждый внесет свой вклад, победа будет не за горами!', NULL, NULL, NULL, 'Рекомендательный жетон Альянса', NULL, NULL, NULL);
