INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8856, 'Неприкосновенный запас', 'В крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания в пустыне и отнеси их Каландрате в крепость Кенария.', 'Принесите 4 сферы воды, 4 мощных противоядия и 4 печеных лосося Каландрате в таверну в крепости Кенария в Силитусе.', '', NULL, NULL, NULL, 'Магическая сфера воды', 'Мощное противоядие', 'Копченые пустынные клецки', 'Краткий обзор задач перевозок I (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8857, 'Тайны колосса – Аши', 'Мне нужны закаленные в бою искатели приключений, которые согласятся принести свежие образцы панциря павшего колосса Аши Карлсу в Пиратскую Бухту. Нет-нет, я не прошу подходить к телу этой твари. Возьми один из образцов у меня и поспеши. Тухлятина ему не годится!', 'Отнесите фрагмент панциря колосса Аши Карлсу Пропеллерзу в Пиратскую Бухту.', 'Ох, сколько же я наделаю цыплят из этого отличного панциря! Молодец, мальчик мой!', 'Да? Что тебе нужно?', NULL, NULL, 'Фрагмент панциря колосса Аши (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8858, 'Тайны колосса – Регал', 'Я бы с радостью сунул этот панцирь прямо в наглую рожу Скользкорука... Только вот мне не выбраться, я собираю образцы этого тараканища. И судя по его размерам, провожусь еще лет сто.$B$BОтнеси этот образец Скользкоруку, и побыстрее. Он платит МНОГО!$B$BА вот его адресок: лагерь Братства Тория – он в Тлеющем ущелье.', 'Отнесите фрагмент панциря колосса Регала надзирателю Скользоруку в Тлеющем ущелье.', 'Великолепно. Из этого хитина можно сделать необыкновенно мощный доспех. Вот обещанные богатства.', 'Хм...', NULL, NULL, 'Фрагмент панциря колосса Регала (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8859, 'Тайны колосса – Зора', 'Моих слуг едва не убили при попытке добыть эти образцы. Не медли ни минуты! Лорд Максвелл Тиросс с нетерпением ждет свежих образцов панцирей. Он надеется, что тайны Колосса помогут нам в войне с Плетью!$B$BТы еще тут?! Вперед, в часовню Последней Надежды! Да, ты получишь неплохую награду за труды...', 'Отнесите фрагмент панциря колосса Зоры лорду Максвеллу Тироссу в Часовню Последней Надежды в Восточных Чумных землях.', 'Отлично, и как раз вовремя! Молодец, парень.', 'Что-то ты тяжело ступаешь, дружище.', NULL, NULL, 'Фрагмент панциря колосса Зоры (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8860, 'Отмечаем Новый Год!', 'Штормград устраивает празднество в честь нового года! Целый день там можно пить задарма, а ночью будет фейерверк!$B$BЭто должно быть прекрасно... но в Пиратской бухте сегодня тоже праздник, и держу пари, там будет еще лучше!$B$BНу, как бы то ни было, хозяйке таверны Аллисон в Штормграде требуются припасы Пастбищ Дымного Леса, чтобы помочь накормить всех гуляк. Окажи мне услугу, доставь эту партию!$B$BСпасибо, $N! Аллисон держит таверну \"Позолоченная роза\" в Торговом квартале Штормграда.', 'Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Аллисон в Штормград.', '', NULL, NULL, NULL, 'Припасы Пастбищ Дымного Леса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8861, 'Отмечаем Новый Год!', 'Громовой Утес устраивает празднество в честь нового года! Целый день там можно пить задарма, а ночью будет фейерверк!$B$BЭто должно быть прекрасно... но в Пиратской бухте сегодня тоже праздник, и держу пари, там будет еще лучше!$B$BНу, как бы то ни было, хозяйке таверны Пале в Громовом Утесе требуются припасы Пастбищ Дымного Леса, чтобы помочь накормить всех гуляк. Окажи мне услугу, доставь эту партию!$B$BСпасибо, $N! Пала держит таверну возле моста, ведущего на вершину Охотников.', 'Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Пале в Громовой Утес.', 'О, отлично! Эти припасы помогут накормить всех моих сородичей, собравшихся сюда на праздник!$B$BСпасибо тебе, $N. Я у тебя в долгу. Прошу, возьми эти монеты... и последуй моему совету – пей сегодня от всей души и присоединяйся к праздничным танцам!', 'Добрый день, $C! Ты хочешь отпраздновать Новый Год у нас, в Громовом Утесе? Или просто дать отдых усталым копытам, прежде чем снова отправляться на охоту?', NULL, NULL, 'Припасы Пастбищ Дымного Леса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8862, 'Свеча Элуны', '', '', 'Что же, прекрасно – беру эти монеты наследия. Бери свечу Элуны с моим благословением. И полюбуйся праздничными фейерверками.$B$BДа будет веселым и радостным твой Лунный фестиваль, $N.$B$BИ если ты решишься встретиться с Оменом и его приспешниками, тебе весьма пригодится свеча Элуны...', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8863, 'Праздничные клецки', '', '', 'Замечательно! Наслаждайся клецками и прими мои поздравления. Хотя это всего лишь крохи благодарности по сравнению с той славой, которой ты покрыл себя, свершая великие деяния, мне кажется, что они тебе все равно понравятся.$B$BА если бы у тебя были еще монетки наследия, то у меня нашлось бы для тебя много интересных вещей.', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8864, 'Платья Лунного фестиваля', '', '', 'Отлично – беру эти монеты наследия. Бери платье и мое благословение. И полюбуйся, пожалуйста, праздничным фейерверком. $B$BТочно так же, как ты принес честь и славу своим старшим, ты оказал честь и мне, посетив меня. Спасибо тебе, и радостного Лунного фестиваля!', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8865, 'Костюмы Лунного фестиваля', '', '', 'Идет – я беру эти монеты наследия. Бери этот брючный костюм и мое благословение. И полюбуся, пожалуйста, праздничным фейерверком! $B$BЕсли у тебя найдется еще несколько монет наследия, обращайся ко мне. Я буду продавать разные вещи в течение всего Лунного фестиваля.', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8866, 'Предок Бронзобород', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8867, 'Лунный фейерверк', 'Каждый год друиды Лунной поляны празднуют торжество своего города над древним злом.$B$BМы вспоминаем о мудрости старейшин, наслаждаемся пирами и, разумеется, пускаем фейерверки!$B$BЗа небольшое пожертвование ты можешь приобрести разноцветные фейерверки у наших торговцев. Можешь воспользоваться здешними пусковыми установками.', 'Запустите 8 лунных фейерверков и 2 ракеты. Вернитесь к предвестнице Лунного фестиваля в любую столицу.', 'Молодец, $N.$B$BРаз вы так прониклись духом праздника, почему бы вам не отправиться в Лунную поляну?$B$BЕсли у вас есть время, там можно неплохо повеселиться. Полно еды, выпивки, баек у костра... И фейерверков!$B$BОткройте приглашение, стоя в большом круге лунного света, и перенесетесь в Лунную поляну.', 'Ну что, $N, нашли ракетометы?', NULL, NULL, 'Фейерверков запущено', 'Ракет запущено', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8868, 'Благословение Элуны', 'Эта тварь, Омен, был некогда героем нашего мира. Волк великой силы, любимец удачи, Омен сражался плечом к плечу с героями Войны Древних, пока не попал под власть демонический магии. Обратившись против своих союзников, он в ярости рыскал по Азероту, сея вокруг себя смерть и ужас.$B$BНаконец, побежденный здесь, на Лунной поляне, Омен ныне спит под илом озера Элуне\'ара. Но каждый год во время праздника он шевелится во сне... $B$BСобирай соратников, $N, пробуди и порази эту тварь, Омена. Заслужи благословение Элуны!', 'Призовите Омена, победите его и получите благословение Элуны. Вернитесь к Валадару Звездной Песне в Ночную Гавань.', 'Славное дело, $N. Победа над Оменом возвратила его дух в воды озера Элуны. Хотя сама тварь была благословлена Элуной и не может умереть, его гнев еще на год утихнет.$B$BТвоя победа стоит праздника, $N – да почтят все могущество Омена, воздадут хвалу тебе и твоим друзьям и восславят, покой, который был подарен тобой этому трагическому герою нашего прошлого.', 'Омен еще шевелится под илом озера Элуны, $N...', NULL, NULL, 'Получите благословение Элуны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8869, 'Секрет безмятежности', 'В казематах бастиона Алого ордена таится секрет Безмятежности. Молотобоец из Багрового легиона стережет его как зеницу ока. Срази его и принеси мне его фартук. За это я открою тебе секреты школы молота.$B$BНо запомни. Если ты выберешь это умение, школы меча и топора будут для тебя закрыты.', 'Отправляйтесь в Стратхольм и убейте молотобойца из Багрового легиона. Возьмите его фартук и возвращайтесь к Лилит.', '', NULL, NULL, NULL, 'Фартук молотобойца из Багрового легиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8870, 'Лунный фестиваль', 'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', 'Поговорите с предвестницей Лунного фестиваля в Палатах Магии Стальгорна. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', 'Добро пожаловать, $N. Ты пришел, чтобы праздновать вместе с нами?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8871, 'Лунный фестиваль', 'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', 'Поговорите с предвестницей Лунного фестиваля в парке Штормграда. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', 'Добро пожаловать, $N. Ты хочешь присоединиться к торжествам?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8872, 'Лунный фестиваль', 'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', 'Поговорите с предвестницей Лунного фестиваля в дарнасском анклаве Кенария. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8873, 'Лунный фестиваль', 'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', 'Поговорите с предвестницей Лунного фестиваля в Аллее Мудрости в Оргриммаре. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8874, 'Лунный фестиваль', 'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', 'Поговорите с предвестницей Лунного фестиваля у входа в Подгород. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8875, 'Лунный фестиваль', 'Время веселиться, $N! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.', 'Поговорите с предвестницей Лунного фестиваля на вершине Старейшин Громового Утеса. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8876, 'Маленькие ракеты', '', '', 'О, великолепно. Вот тебе инструкция, $N, и да благословит тебя Элуна.', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8877, 'Пусковая установка для фейерверков', '', '', 'Вот, $N. Это чертеж пусковой установки для фейерверков. Ставишь ее там, где хочешь повеселиться, и приглашай друзей на праздник!', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8878, 'Праздничные выкройки', '', '', 'Вот твои выкройки, $N. Изделия, которые ты сошьешь благодаря им, будут вне всякого сомнения прекрасны.', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8879, 'Большие ракеты', '', '', 'Отлично, беру. Вот твои инструкции, $N. Воспользуйся ими к вящей славе Элуны!', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8880, 'Сигнальные ракеты', '', '', 'Вот, Хамите. Бери эти чертежи и изучай их секреты. Желаю тебе удачи и надеюсь в будущем увидеть твои прекрасные творения.', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8881, 'Большие связки фейерверков', '', '', 'Спасибо, $N. Вот инструкция по изготовлению больших сигнальных ракет. И пусть твое изделие принесет радость и удачу всем, кто будет на них любоваться.', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8882, 'Пусковая установка для связок фейерверков', '', '', 'Вот твой чертеж. Рассмотри его как следует и изучи...$B$BУдачи, $N. И пусть твои праздники посоперничают с самим Лунным фестивалем!', NULL, NULL, NULL, 'Монета Наследия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8883, 'Валадар Звездная Песня', 'Раз у тебя есть приглашение на Лунный фестиваль, можешь отправляться на Лунную поляну! Там полно веселых гуляк, а в деревне Ночная Гавань Валадар Звездная Песня и его сестра Фариэль приглашают всех принять участие в празднике.$B$BОтправляйся на Лунную поляну через большой круг лунного света и поговори с Валадаром – узнай, какие призы могут перепасть тебе во время праздника!', 'Отправляйтесь на Лунную поляну при помощи приглашения на Лунный фестиваль. Прибыв на место, поговорите с Валадаром Звездной Песней в деревне Ночная Гавань.', '$N, добро пожаловать в Ночную Гавань, столицу Лунного фестиваля! Обычно наша деревня держится в стороне от основных событий Азерота, но во время этого праздника мы с радостью приглашаем всех к себе.$B$BНадеюсь, тебе у нас понравится, $N. Если решишь поучаствовать в конкурсах, обращайся ко мне или к моей сестре.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8884, 'Рыбьи головы, рыбьи головы...', 'Приветствую тебя, $C. Посмотри-ка вон туда, в сторону моря. Что ты видишь? Правильно, наш пляж... Наш Безмятежный берег. Но теперь на нем кишат гнусные твари, именуемые мурлоками!$B$BЭто оскорбление для всех нас!$B$BУ меня есть для тебя задание – если ты сочтешь, что оно тебе по плечу. Мне нужны их головы! Посмотрим; возможно, если нам удастся значительно сократить их численность, эти твари испугаются и вернутся обратно в свои темные глубины, откуда выползли!', 'Добудьте 8 голов мурлоков из племени Темной Чешуи. Принесите их Гатвелиону Солнечному Взору в лесах Вечной Песни на утес над Безмятежным берегом.', 'Молодец, $C, ты неплохо потрудился! Судя по запаху, тебе удалось добыть все, что я просил – а может, и более того. Эти головы нам еще пригодятся. На уху или еще куда-нибудь...$B$BУвы, но, боюсь, твои усилия результата не дали. Мурлоки и не думают отступать! Нам надо действовать более решительно!', 'Мы, следопыты из обители Странников, делаем все, чтобы исправить урон, нанесенный нашим прекрасным землям. И ради этого мы готовы на все!$B$BНу что, где головы мурлоков?', NULL, NULL, 'Голова мурлока из племени Темной Чешуи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8885, 'Кольцо Мррргла', 'Мурлоки из племени Темной Чешуи не испугались тебя! Но я, кажется, знаю, как им отомстить – и заодно заставить их собирать вещички!$B$BУ этих мурлоков есть главарь, который зовет себя Мррргл. Он бродит по Золотистому взморью, к югу от устья реки. Эта тварь некогда убила моего земляка и теперь нагло носит его кольцо!$B$BУбей Мррргла и принеси мне кольцо моего товарища. Уж тогда-то мы сумеем запугать этих чудищ!', 'Снимите кольцо Мррргла с трупа предводителя племени Темной Чешуи. Верните его Гатвелиону Солнечному Взору в лесах Вечной Песни на утесе над Безмятежным берегом.', 'Наконец-то! Правда, мурлоки так и не ушли, но все же приятно было видеть, как они забегали в панике, когда ты сразил их так называемого \"вождя\". Я благодарю тебя, а вместе со мной – и все син\'дорай Луносвета!$B$BПожалуйста, выбери одну из этих вещей в награду за оказанную тобой услугу!', 'Ты, $C, – оружие моей мести и победы! Ну что, кольцо у тебя с собой?', NULL, NULL, 'Кольцо Мррргла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8886, 'На помощь! Пираты!', 'Ох, $C, как хорошо, что ты здесь! Эти склизкие мурлоки захватили мой груз! Мало того, что все магические товары, которые я везла, разграблены Презренными, так теперь все остальное попало в лапы к мурлокам! Куда катится эта страна?!$B$BПоможешь вернуть мой груз? Нет, я не рассчитываю, что ты спасешь все, но буду благодарна хотя бы за часть груза! Уверена, во всем виноваты мурлоки из племени Темной Чешуи, которые живут в хижинах к юго-западу отсюда, на Золотистом взморье!', 'Отыщите 6 тюков из груза капитана Келисендры и верните их капитану Келисендре в укрепленный лагерь к востоку от причала Солнечного Паруса в лесах Вечной Песни.', 'Прекрасно! Ты спас меня от разорения и отомстил этим мерзким тварям!$B$BТеперь, если мне только удастся уговорить наших славных следопытов помочь мне с грузом, я наконец-то выберусь отсюда! Надо было вернуться сразу, как только Велендрис сумел отбить верфь.$B$BВот, возьми. Большего я себе позволить не могу, но должна же я хоть как-то вознаградить тебя за труды!', 'Я так рада, что ты мне помогаешь, $N! Я даже могу улыбаться, впервые за много дней. Но как подумаю, что эти чудища сделали с моим кораблем и что происходит с Кель\'Таласом...$B$BНу что, удалось тебе найти хотя бы часть груза?', NULL, NULL, 'Груз капитана Келисендры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8887, 'Утраченные карты капитана Келисендры', 'Интересно... У вас в руках водонепроницаемый кожаный футляр, внутри которого множество листов пергамента. Судя по обозначениям, это навигационные карты, подписанные капитаном Келисендрой.$B$BВы уже слышали о небольшом укрепленном лагере к востоку от причала Солнечного Паруса. Может быть, там вы найдете капитана?', 'Верните утраченные карты капитану Келисендре в укрепленный лагерь к востоку от причала Солнечного Паруса в лесах Вечной Песни.', 'Ох, $C, ты прелесть, просто прелесть! Я и понятия не имела, что эти гадкие мурлоки из племени Темной Чешуи украли еще и навигационные карты! А ведь без них я не смогла бы ходить по морю, даже если бы мы отвоевали причал и отремонтировали мой корабль!$B$BСпасибо тебе большое! Вот, возьми это золото в знак моей благодарности!', 'Здравствуй, $C! Ты не представляешь, как я рада тебя видеть. Я понимаю, что глупо торчать тут, раз уж причал захвачен Презренными. Велендрис и его следопыты поклялись защищать меня, при условии, что я уберусь отсюда, как только верну свой груз.$B$BА что это там у тебя? Выглядит смутно знакомым...', NULL, NULL, 'Утраченные карты капитана Келисендры (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8888, 'Ученица магистра', '$C, выслушай мою просьбу! Я решил закрыть свою школу – по причинам, в которые я сейчас вдаваться не могу. Несколько дней назад я отправил туда с этой целью одну из моих учениц, Лоралталис. И с тех пор о ней ни слуху, ни духу!$B$BПрошу тебя, сходи в шпиль Блеклых Сумерек, узнай, как она там, и все ли с ней в порядке. От обители Странников ступай по тропе на север, потом на развилке поверни направо.', 'Поговорите с ученицей Лоралталис возле шпиля Блеклых Сумерек, что в лесах Вечной Песни.', 'Магистр обо мне тревожится? Как это мило. Лучше бы он побеспокоился обо мне раньше, когда мы были еще в замке!$B$BНу, неважно. Пожалуйста, $C, выслушай меня внимательно. Мне придется попросить тебя об услуге.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8889, 'Отключить замок', 'Как тебе, должно быть, известно, магистр Блеклые Сумерки прислал меня сюда, чтобы отключить источники энергии, питающие замок. Их три, они находятся в разных местах внутри шпиля.$B$BУвы, я, похоже, опоздала: шпиль Блеклых Сумерек захватили странные магические создания. Мне не хватает опыта, чтобы выполнить эту задачу, но, думаю, $gтакой умелый:такая умелая:c: $C, как ты, с этим справится...', 'Отключите 3 источника энергии в шпиле Блеклых Сумерек. Потом верните деактивирующий самоцвет ученице Лоралталис.', 'Я так благодарна тебе за помощь! Однако печально слышать, что некоторые из моих товарищей поддались искушению...$B$BТеперь, когда источники энергии отключены, я, пожалуй, подожду здесь, пока все успокоится, а потом проберусь внутрь и заберу их останки...', 'Тебе удалось отключить источники энергии? Мне отсюда плохо видно...', NULL, NULL, 'Первый источник энергии отключен', 'Второй источник энергии отключен', 'Третий источник энергии отключен', 'Деактивирующий самоцвет (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8890, 'Весточка из замка', '$N, я хочу попросить тебя о последней услуге. Не согласишься ли ты вернуться в обитель Странников и рассказать магистру Блеклые Сумерки о том, что здесь произошло? Пусть знает, что со мной все в порядке, но имеет в виду, что некоторые из учеников стали Презренными!$B$BСпасибо тебе за помощь!', 'Вернитесь к магистру Блеклые Сумерки в обитель Странников, что в лесах Вечной Песни.', 'О нет! Значит, я опоздал... Это все моя вина.$B$BМои исследования альтернативных источников магии зашли слишком далеко, прежде чем я догадался положить этому конец. Если бы только я отправился туда сам... или если бы они вняли моим предупреждениям!$B$BИх судьба на моей совести, $C. Но все равно, я благодарю тебя за то, что ты помог истерзанным душам моих бывших учеников обрести покой. Меня отчасти утешает то, что они недолго пребывали в этом состоянии, которое для эльфа хуже смерти.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8891, 'Неоконченное исследование', 'Вы обнаружили тетрадь, похожую на журнал наблюдений, забытый магистром Блеклые Сумерки. Проглядев журнал, вы понимаете, что магистр проводил весьма рискованные эксперименты, пытаясь фильтровать потоки порченной магии. Возможно, это объясняет то, что произошло в замке. Магистр наверняка будет рад получить свой журнал обратно...', 'Верните журнал магистру Блеклые Сумерки в обитель Странников, что в лесах Вечной Песни.', 'Да, $N, вот оно, доказательство моего преступления! В этом журнале - описание всех моих неосторожных опытов.$B$BМеня предупреждали, но я не обращал внимания, я продолжал свои исследования, пока не стало поздно! Тогда я осознал свою ошибку и попытался ее исправить. Однако некоторые из моих учеников успели зайти слишком далеко. Я эвакуировал замок, чтобы изолировать их от порчи, но в спешке забыл отключить источники энергии...$B$BЯ сожгу этот журнал, чтобы никто более не пал жертвой подобного искушения! Я ведь всего лишь хотел помочь син\'дорай...', 'Что это? Какая знакомая тетрадка... О нет! Этот журнал... мои исследования... с них-то все и началось!', NULL, NULL, 'Журнал магистра Блеклые Сумерки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8892, 'Проблемы на причале Солнечного Паруса', 'Причал Солнечного Паруса захватили Презренные. Как только мы сумеем подвести туда подкрепление, мы покажем этим уродам, почем фунт лиха!$B$BА пока что ты, $N, можешь нам помочь: поучи их слегка уму-разуму. Сходи туда и покажи им, что с нами шутить опасно. Причал Солнечного Паруса находится к западу от деревни Легкий Ветерок.', 'Убейте 5 Презренных-лиходеев и 5 Презренных-бесчинников и вернитесь к следопыту Деголиену.', 'Пусть знают, что с нами лучше не связываться! Молодец, $N.', NULL, NULL, NULL, 'Презренный-лиходей убито', 'Презренный-бесчинник убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8893, 'Супер Яйц-О-Матик', '', '', 'Вы кладете в машину яйцо гиппогрифа. Раздается несколько гудков и странный механический шум.$B$BПохоже, яйцеметр взвесил, измерил и упаковал ваше яйцо. Вот это называется быстрое обслуживание!', NULL, NULL, NULL, 'Яйцо гиппогрифа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8894, 'Зачистка территории', 'Ужас, просто ужас! В замке творится неизвестно что, магистр и все его ученики разбежались, и не успели мы глазом моргнуть, как оказалось, что повсюду кишат эти магические твари! А Виллитену кто-нибудь что-нибудь сказал? Ни словечка!$B$BПослушай, $C, твой долг – помочь мне разогнать этих мерзких существ! Я не могу поддерживать порядок, пока вокруг бесчинствуют эти \"аномальные явления\"!', 'Убейте 6 мана-змеев и 6 эфирных призраков и вернитесь к смотрителю Виллитену в земли Блеклых Сумерек, что в лесах Вечной Песни.', 'Ну, думаю, этого должно быть достаточно? Спасибо за помощь, $C. Могу лишь надеяться, что этот беспорядок окончательно ликвидируют к тому времени, как в шпиль Блеклых Сумерек вернется магистр.$B$BНа вот, возьми эту мелочь. Это немного, но больше у меня при себе сейчас нет. Можешь перед уходом ликвидировать еще нескольких тварей, если тебя не затруднит.', 'Ну что, тебе удалось разобраться с ними? Сколько этих магических аномалий тебе удалось уложить? Что же я буду делать, если магистр Блеклые Сумерки вернется, а тут повсюду эти твари?', NULL, NULL, 'Мана-змей убито', 'Эфирный призрак убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8895, 'Послание в Северное святилище', 'Приятно видеть, что ты хоть на что-то $gспособен:способна:, $N. Ну, раз уж ты так стремишься себя показать, вот тебе новое задание.$B$BВот письмо хранителю энергии Кайданису, чародею, отвечающему за Северное святилище. Отправляйся на юго-запад от Площади Соколиных Крыльев, и найдешь его. Это очень важная персона, так что смотри, не досаждай ему пустой болтовней!', 'Доставьте непомеченное письмо хранителю энергии Кайданису в Северном святилище в лесах Вечной Песни.', 'Спасибо, $N. Я ждал этого письма.', 'Да, $C?', NULL, NULL, 'Непомеченное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8896, 'Дворфийский шпион', 'Так ты говоришь, что эти бумаги были у ночного эльфа? Язык-то, по большей части, дворфийский...$B$BПроспектор Страж Наковальни! Его прислали сюда из Стальгорна с дипломатической миссией! Мне следовало заподозрить, что он не случайно интересуется нашими волшебными святилищами! $N, отыщи этого дворфа в Северном святилище и разберись с ним. Да, и сделай это тихо!', 'Найдите и убейте геолога Стража Наковальни в Северном святилище, затем доложите о выполнении задания Аэльдону Озаренному Солнцем из Лесов Вечной Песни.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8897, 'Дорогая моя Колара!', 'Я должен нести стражу здесь, у ворот, но я не могу выбросить из головы мысли о моей милой Коларе. В лучшем случае я могу видеться с нею лишь по несколько часов... Да и что я собой представляю? Я получаю жалованье младшего офицера и со дня на день меня могут отправить на фронт.$B$BНе забудет ли она обо мне сразу же после расставания? В городе полно мужчин, и многие из них богаты.$B$BНо, как бы то ни было, я написал тут несколько слов... в общем, ничего особенного, но я буду признателен, если ты доставишь ей эту записку от меня.', 'Отнесите тщательно продуманную записку лейтенанта Хельдрика Коларе Дин, обитающей поблизости от банка в Штормграде.', 'Как это мило! Он впервые догадался мне написать. Ты думаешь, он это серьезно?$B$BКолара Нельдрик? По-моему, звучит неплохо. О, но я забегаю вперед. Спасибо тебе.', 'Привет, красавчик.Чем-нибудь могу тебе помочь?', NULL, NULL, 'Написанная со старанием записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8898, 'Дорогая моя Колара!', 'В последний раз, когда я был в Штормграде по делам банка, я встретил там девушку. Она похитила мое сердце. Я не могу не думать о ней! Я хотел бы послать ей это письмо – я переписывал его двенадцать раз.$B$BПочта сейчас так загружена, а я хотел бы точно знать, что письмо попадет к ней.$B$BЕсли ты направляешься туда, то не окажешь ли мне услугу?', 'Отнесите смятое письмо Коларе Дин, обитающей поблизости от банка в Штормграде.', 'Тормек? О да, я помню его. У него была такая красивая борода, и он все время в нее улыбался.$B$BАх, поверить не могу, что он меня не забыл!', 'Привет, красавчик.Чем-нибудь могу тебе помочь?', NULL, NULL, 'Смятое письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8899, 'Дорогая моя Колара!', 'Как описать ее красоту? Тысячи лет я учился выражать свои мысли словами, но ныне я нем. $B$BЭти смертные вводят в смущение разум и превращают нас в лепечущих чушь идиотов.$B$BЯ слишком долго смотрел на эти слова. Я больше не могу выжать из них ни капли смысла и убедительности. Нет, она должна получить это послание немедленно, или кто-нибудь другой привлечет ее внимание.', 'Отнесите безукоризненное письмо Коларе Дин, обитающей поблизости от банка в Штормграде.', 'Ничего подобного я прежде не получала. Как трогательно!', 'Привет, красавчик.Чем-нибудь могу тебе помочь?', NULL, NULL, 'Аккуратненькое письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8900, 'Дорогая моя Эления!', 'Она была такой грустной. Я понял это, едва взглянув на выражение ее лица. Я имею в виду, она казалась грустной – понимаешь? $B$BА после того, как я поговорил с ней, возникла взаимосвязь. Я не думал, что кто-то может понять меня, но она смогла.$B$BКогда я сказал остальным, они смеялись надо мной, и потому я больше никогда с ней не заговаривал. Но я скучаю по ней. Ты не можешь отнести ей от меня письмо? Я хочу быть уверен, что оно попадет к ней в руки.', 'Отнесите слегка помятую записку Элении Хайдон, обитающей поблизости от банка в Подгороде.', 'Вот не ожидала, что орк окажется таким красноречивым. Конечно же, до нынешних времен у нас не было возможности как следует их узнать. Спасибо за доставку письма!', 'О, и чему я обязана такой радостью?', NULL, NULL, 'Слегка помятая записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8901, 'Дорогая моя Эления!', 'Известно ли тебе, что такое любовь, $gюноша:девушка:? До недавнего времени, пока я не повстречал создание по имени Эления из Подгорода, это чувство было мне не знакомо. Таурены вообще редко обращают внимание на представителей других рас, тем более, если это кто-то из Отрекшихся. Но сейчас я днями и ночами думаю только о ней.$B$BТы не $gмог:могла: бы отнести ей это письмо? Я хочу, чтобы она приехала в Мулгор. Надеюсь, она согласится.', 'Отнесите написанное со старанием письмо Элении Хайдон, обитающей поблизости от банка в Подгороде.', 'Какие милые слова написал мне Темма! Но, хотя его слова меня тронули, я не могу всерьез рассматривать любовь таурена. Мы слишком разные по крови, разуму и духу.$B$BКак хорошо, что он не сделал мне это предложение лично. Мне было бы невыносимо разбивать ему сердце.', 'О, и чему я обязана такой радостью?', NULL, NULL, 'Написанное со старанием письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8902, 'Дорогая моя Эления!', 'Целую жизнь назад я был помолвлен с девушкой по имени Эления, подругой моего детства. Прошли годы с тех пор, как я в последний раз думал о ней, но в последнее время она постоянно занимает мои мысли. $B$BБыть может даже тогда, когда все ушло, в нашей жизни все-таки остается место для любви.$B$BЯ уверен, что она тоже изменилась. Ты не передашь ей от меня письмо? Я слишком волнуюсь, чтобы передать его лично.', 'Отнесите проникнутое любовью письмо Элении Хайдон, обитающей поблизости от банка в Подгороде.', '', NULL, NULL, NULL, 'Проникнутое любовью письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8903, 'Опасная любовь', 'И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.$B$BДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.$B$BОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.', 'Раздобудьте открытку штормградского стражника и отдайте ее Аристану Моттару в Штормграде.', 'Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить. За этим должны крыться какие-то причины.', 'Прав ли я был, когда беспокоился? Поражены ли стражи этой любовной лихорадкой?', NULL, NULL, 'Открытка штормградского стражника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8904, 'Опасная любовь', 'И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.$B$BДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.$B$BОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.', 'Возьмите заплесневелую открытку стража и отнесите ее Фенстаду Аргайлу в Подгороде.', 'Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить. За этим должны крыться какие-то причины.', 'Был ли я прав, когда волновался? Наши идиоты-стражи поддались этой заразе?', NULL, NULL, 'Заплесневелая открытка стража', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8905, 'Серьезное предложение', 'Рада встрече, $C. У меня найдется кое-что интересное для тебя.$B$BЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу.$B$BКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне изрядное количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.', 'Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручами Буйного Сердца Делиане в Стальгорне.', 'Великолепно! Так совершим обмен! Жалко расставаться с такими великолепными доспехами, но, боюсь, в ближайшее время они мне не понадобятся.$B$BЕсли ты согласишься выполнить для меня еще кое-какие поручения, то, может, я отдам и остальную часть комплекта.', 'Ты принес мне то, что я просила, $N?', NULL, NULL, 'Образец крови из Зимних Ключей', 'Наручи дикого сердца', 'Требуется денег: 20', NULL);
