INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8913, 'Серьезное предложение', 'Привет тебе, $C! Судя по тому, как ты держишься, тебе немало довелось повидать на белом свете. Но бьюсь об заклад, что таких доспехов, как эти, тебе видеть не доводилось!$B$BОкажи мне небольшую услугу, и я отдам их тебе в обмен на наручи попроще.$B$BМне нужен яд тварей, обитающих в Силитусе. Принеси мне этот яд и немного золотых монет, и я произведу обмен.', 'Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами Буйного Сердца Моквару в Оргриммар.', 'О, да... Мукс будет в восторге.$B$BЭти поручья – часть набора доспехов. Если ты согласишься помогать мне и дальше, то я, пожалуй, готов буду расстаться с остальным.', 'Ну что, $N, удалось тебе добыть то, что нужно?', NULL, NULL, 'Образец яда силитида', 'Наручи дикого сердца', 'Требуется денег: 20', NULL);
