INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8918, 'Серьезное предложение', 'Привет тебе, $C! Судя по тому, как ты держишься, тебе немало довелось повидать на белом свете. Но бьюсь об заклад, что таких доспехов, как эти, тебе видеть не доводилось!$B$BОкажи мне небольшую услугу, и я отдам их тебе в обмен на наручи попроще.$B$BМне нужен яд тварей, обитающих в Силитусе. Принеси мне этот яд и немного золотых монет, и я произведу обмен.', 'Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с поручьями Стихий Моквару в Оргриммар.', '', NULL, NULL, NULL, 'Образец яда силитида', 'Наручники Стихий', 'Требуется денег: 20', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8919, 'Серьезное предложение', 'Привет тебе, $C! Судя по тому, как ты держишься, тебе немало довелось повидать на белом свете. Но бьюсь об заклад, что таких доспехов, как эти, тебе видеть не доводилось!$B$BОкажи мне небольшую услугу, и я отдам их тебе в обмен на наручи попроще.$B$BМне нужен яд тварей, обитающих в Силитусе. Принеси мне этот яд и немного золотых монет, и я произведу обмен.', 'Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами Багрового Тумана Моквару в Оргриммар.', '', NULL, NULL, NULL, 'Образец яда силитида', 'Наручи Багрового Тумана', 'Требуется денег: 20', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8920, 'Серьезное предложение', 'Привет тебе, $C! Судя по тому, как ты держишься, тебе немало довелось повидать на белом свете. Но бьюсь об заклад, что таких доспехов, как эти, тебе видеть не доводилось!$B$BОкажи мне небольшую услугу, и я отдам их тебе в обмен на наручи попроще.$B$BМне нужен яд тварей, обитающих в Силитусе. Принеси мне этот яд и немного золотых монет, и я произведу обмен.', 'Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами Доблести Моквару в Оргриммар.', 'О, да... Мукс будет в восторге.$B$BЭти наручи – часть набора доспехов. Если ты согласишься помогать мне и дальше, то я, пожалуй, готов буду расстаться с остальным.', 'Ну что, $N, удалось тебе добыть то, что нужно?', NULL, NULL, 'Образец яда силитида', 'Наручи доблести', 'Требуется денег: 20', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8921, 'Эктоплазматический дистиллятор', 'А, тебе нужен мой последний проект… спектральный сканер иных измерений! К сожалению, мне не хватает средств и сотрудников.$B$BХочешь помочь? Великолепно! Первым делом нам придется добыть самую сущность смерти! Эктоплазматический дистиллятор будет нелегко построить, $N.$B$BМне понадобится арканитовый преобразователь, несколько великих вечных субстанций и масло каменного угря. Пригодится и вулканический пепел из прудов лавы в Пылающих степях – из него я сделаю фильтр.', 'Принести Муксу Маноскребу из Прибамбасска 1 сверхточный арканитовый преобразователь, 4 великих сущности вечности, 10 порций масла каменного угря, 25 горстей вулканического пепла и 40 золотых.', 'Вот, именно то, что и требовалось. И очень вовремя!$B$BДистиллятор вот-вот заработает! А тем временем прими это в уплату за работу.', 'Я понимаю, что материалы недешевые... Но клянусь, все они необходимы!', NULL, NULL, 'Сверхточный арканитовый преобразователь', 'Великая вечная субстанция', 'Масло каменного угря', 'Вулканический пепел');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8922, 'Сверхъестественное устройство', 'Я должна найти способ связаться с Антионом Хармоном... точнее, с его духом!$B$BЯ знаю одного инженера, который чрезвычайно интересуется сверхъестественным. Он говорит, будто бы может соорудить машину, которая позволит ему разговаривать с духами!$B$BТа кровь, что ты $gсобрал:собрала:, предназначается как раз ему. Поезжай в Прибамбасск и отдай ее ему в оплату услуг!', 'Отнесите запечатанный контейнер с кровью Муксу Маноскребу в Прибамбасск в Танарисе.', 'О, радость! У меня как раз запасы оскудели!$B$BГоворите, вас Делиана послала?', 'Вы что-то мне принесли?', NULL, NULL, 'Запечатанный ларчик с кровью (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8923, 'Сверхъестественное устройство', 'Ты все еще здесь? Да, храбрости тебе не занимать! Наверное, тебя заинтересовали те наручи, что я тебе дал. Да, у меня есть и другие детали такого доспеха, и ты их получишь, если будешь по-прежнему помогать мне.$B$BТот яд, что я собирал, предназначен для моего знакомого, Мукса Маноскреба. Это инженер, который увлекается всем сверхъестественным. Сейчас он пытается построить прибор, с помощью которого можно общаться с мертвыми! Я надеюсь с помощью этого прибора связаться с Антионом и получить от него совет.', 'Отнесите запечатанный ларчик с ядом Муксу Маноскребу в Прибамбасск.', 'Замечательно! Как раз вовремя. У меня яд почти закончился…$B$BТак ты говоришь, тебя Моквар прислал?', 'Ты хочешь со мной поговорить?', NULL, NULL, 'Запечатанный ларчик с ядом (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8924, 'В поисках эктоплазмы', 'Отличная конструкция, вот что я скажу! Впрочем, тебе придется попутешествовать, чтобы отыскать бестелесную нежить, без которой не обойтись.$B$BВидишь ли, разный климат оказывает разного рода воздействие на спектральную ткань мертвецов. Там понадобится эктоплазма от страдающих ночных эльфов Силитуса, духов высокорожденных из Зимних Ключей и призраков и банши из Восточных Чумных земель. Не забудь установить дистиллятор, прежде чем приступать к делу!', 'Воспользуйтесь эктоплазматическим дистиллятором рядом с бестелесной нежитью и соберите 12 образцов опаленной эктоплазмы в Силитусе, 12 образцов замороженной эктоплазмы в Зимних Ключах и 12 образцов стабильной эктоплазмы в Восточных Чумных землях. Принесите их вместе с эктоплазматическим дистиллятором Муксу Маноскребу в Прибамбасск.', 'Да, отличные образцы!$B$BСобрав всю иномирную энергию из этих субстанций, мы сможем связаться с теми душами, что еще не покинули этот мир!', 'Тебе удалось собрать эктоплазму, $R?', NULL, NULL, 'Опаленная эктоплазма', 'Замороженная эктоплазма', 'Стабильная эктоплазма', 'Дистиллятор эктоплазмы (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8925, 'Портативный источник энергии', 'Теперь нам понадобится стабильный и портативный источник энергии, который сможет поддерживать эктоплазму в активной форме. До меня дошли слухи о могущественном элементале по имени Повелитель магмы Бокк. Его сердце состоит из магмы, и это бесконечный источник тепла!$B$BГоворят, что его можно отыскать в Пылающих степях, на юге от Черной горы. Принеси мне магмовое ядро и мы обеспечим энергией спектральный сканер иных измерений!', 'Отыщите в Пылающих степях Повелителя магмы Бокка, добудьте его магмовое ядро и отнесите его Муксу Маноскребу в Прибамбасск.', 'Получилось! Теперь нам явно хватит энергии на спектральный сканер иных измерений!', 'Тебе удалось отыскать лорда магмы, $N?', NULL, NULL, 'Магмовое ядро', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8926, 'Справедливое вознаграждение', 'Ты $gсдержал:сдержала: слово и $gпринес:принесла: устройство Мукса. И уж если я хочу, чтобы ты и дальше $gзащищал:защишала: мою шкуру, то награда должна быть соотвествующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.', 'Принесите пояс дикого cердца и пару перчаток дикого cердца в Стальгорн Делиане.', 'Ты свою часть сделки выполнил, я выполню свою.$B$BНо помни: лучшее я придержу до завершения работы. Сладкое – на закуску.', 'Ну, готов к обмену?', NULL, NULL, 'Пояс дикого сердца', 'Перчатки дикого сердца', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8927, 'Справедливое вознаграждение', 'Ты $gоказался:оказалась: чрезвычайно надежным $gпомощником:помощницей:, $N! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!$B$BОбменяю-ка я твой пояс и повязки на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.', 'Принесите Моквару в Оргриммар пояс дикого cердца и перчатки дикого cердца.', 'Наш договор остается в силе. Не забывай, вскоре ты получишь куда более ценные вещи! Только освободи меня от этого проклятия, а уж я тебе отплачу сторицей!', 'Ну что, будем меняться?', NULL, NULL, 'Пояс дикого сердца', 'Перчатки дикого сердца', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8928, 'Сомнительный торговец', 'Сердечник снабдит наше устройство энергией, остается найти жезл, который будет должным образом направлять ее и при этом не расплавится.$B$BЗнавал я одного беса из Зимних Ключей, который продавал самые разные товары. У него был жезл Стихий, который бы идеально подошел. Так и пнул бы себя – что стоило купить?$B$BОн живет в пещере у входа в Теснину Зловещего Шепота. Прокрадись туда и отыщи его.$B$BИ не давай ему больше сорока золотых – такую цену он назвал мне!', 'Отыщите беса в пещере у входа в Теснину Зловещего Шепота в южной части Зимних Ключей, купите жезл Скверны Стихий и отнесите его Муксу Маноскребу в Прибамбасск.', 'Ты справился! Этот жезл идеально подойдет. А теперь соберем-ка мы все вместе...', 'Ну как, удалось найти беса в Теснине Зловещего Шепота?', NULL, NULL, 'Жезл скверны стихий', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8929, 'В поисках Антиона', 'Ну что ж, нам ничего не остается, как только опробовать гоблинское изобретение. Говорят, Антион пал под натиском легионов Стратхольма, когда пытался войти в его ворота. $B$BПопробуй воспользоваться этим изобретением там, возможно, тебе удасться узнать то, что знал Антион.', 'Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.', 'Тебя прислала Делиана? Я сделаю все, что ты просишь, но сначала окажи мне любезность.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8930, 'В поисках Антиона', 'Ну что ж, нам ничего не остается, как только опробовать гоблинское изобретение. Говорят, Антион пал под натиском легионов Стратхольма, когда пытался войти в его ворота. $B$BПопробуй воспользоваться этим изобретением там, возможно, с его помощью и в самом деле можно говорить с мертвыми.', 'Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.', 'Тебя прислал Моквар? Я сделаю все, что ты просишь, но сначала окажи мне любезность.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8931, 'Справедливое вознаграждение', 'Ты $gсдержал:сдержала: слово и $gпринес:принесла: устройство Мукса. И уж если я хочу, чтобы ты и дальше $gзащищал:защишала: мою шкуру, то награда должна быть соотвествующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.', 'Принесите пояс загонщика и пару перчаток загонщика в Стальгорн Делиане.', '', NULL, NULL, NULL, 'Пояс загонщика', 'Перчатки загонщика', NULL, NULL);
