INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8937, 'Справедливое вознаграждение', 'Ты $gсдержал:сдержала: слово и $gпринес:принесла: устройство Мукса. И уж если я хочу, чтобы ты и дальше $gзащищал:защишала: мою шкуру, то награда должна быть соответствующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.', 'Принесите пояс Доблести и пару рукавиц Доблести в Стальгорн Делиане.', 'Ты свою часть сделки выполнил, я выполню свою.$B$BНо помни: лучшее я придержу до завершения работы. Сладкое – на закуску.', 'Ну, готов к обмену?', NULL, NULL, 'Пояс доблести', 'Рукавицы доблести', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8938, 'Справедливое вознаграждение', 'Ты $gоказался:оказалась: чрезвычайно надежным $gпомощником:помощницей:, $N! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!$B$BОбменяю-ка я твой пояс и повязки на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.', 'Принесите Моквару в Оргриммар пояс загонщика и перчатки загонщика.', 'Наш договор остается в силе. Не забывай, вскоре ты получишь куда более ценные вещи! Только освободи меня от этого проклятия, а уж я тебе отплачу сторицей!', 'Ну что, будем меняться?', NULL, NULL, 'Пояс загонщика', 'Перчатки загонщика', NULL, NULL);
