INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8944, 'Справедливое вознаграждение', 'Ты $gоказался:оказалась: чрезвычайно надежным $gпомощником:помощницей:, $N! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!$B$BОбменяю-ка я твой пояс и рукавицы на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.', 'Принесите Моквару в Оргриммар пояс Доблести и рукавицы Доблести.', 'Наш договор остается в силе. Не забывай, вскоре ты получишь куда более ценные вещи! Только освободи меня от этого проклятия, а уж я тебе отплачу сторицей!', 'Ну что, будем меняться?', NULL, NULL, 'Пояс доблести', 'Рукавицы доблести', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8945, 'Просьба мертвеца', 'Я отвечу на все твои вопросы, $N. Но прежде исполни мою просьбу.$B$BЛюбимая жена моя была схвачена проклятым воинствои Рийвендера.$B$BКак же я не хотел, чтобы она следовала за дураками из Серебряного Рассвета, но теперь это все уже не важно. Прошу тебя, сделай то, что не удалось мне, – спаси Исиду из лап барона!', 'Отправляйтесь в Стратхольм и спасите Исиду Хармон от барона Ривендера.', 'Благодарю, за спасение! Не думал я, что мне удастся выжить. Прошу тебя, прими это в качестве миллионной доли моей благодарности. $B$BАнтион... о нет... не может быть!', NULL, NULL, NULL, 'Исида спасена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8946, 'Доказательство жизни', 'Нет судьбы горше, чем видеть, как твои близкие гибнут, пытаясь спасти тебя. Ты утвержаешь, что можешь говорить с мертвыми.$B$BОтнеси Антиону этот медальон как доказательство того, что я жива и здорова. Скажи ему, что ему не стоит цепляться за этот мир, обрекая себя на скитания в обличье бесплотного духа – мое бедное сердце этого не вынесет.$B$BПрощай, $N, я всегда буду у тебя в долгу.', 'Отнесите медальон Исиды Антиону Хармону в Восточные Чумные земли.', 'Да, это ее медальон – ты нашел ее! Теперь я могу покоиться с миром.$B$BЯ отвечу на все твои вопросы, $N. Но торопись, время мое на исходе.', 'Исида жива?', NULL, NULL, 'Медальон Исиды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8947, 'Странная просьба Антиона', 'Мы не сразу поняли важность медальона Вальтхалака, поэтому он был поделен наряду с остальными трофеями. Первый фрагмент получил дворф по имени Тельдрен. Я сам пытался отобрать у него этот фрагмент, но дворф избил меня до полусмерти. Тебе придется забрать фрагмент силой.$B$BГоворят, Тельдрен стал гдадиатором у дворфов Черного Железа. Имей в виду, это очень сильный противник.$B$BИ сначала собери для меня некоторые материалы – они тебе понадобятся.', 'Принести три слитка черного железа, 20 кусков зачарованной кожи, 3 куска луноткани и 4 обработанные грубые шкуры Антиону Хармону в Восточные Чумные земли.', 'Прекрасно, я превращу их во что-нибудь полезное.', 'Ты достал материалы, $N?', NULL, NULL, 'Слиток черного железа', 'Зачарованная кожа', 'Луноткань', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8948, 'Старый приятель Антиона', 'Тельдрен – не из тех, кто охотно вступает в честный поединок. Но я изготовил знамя его родовых цветов.$B$BЕсли еще наложить на него соответствующее заклятие, перед этим он не устоит.$B$BМой старый приятель по имени Фарлин знает такое заклятие. Умеет он... подзуживать. Ты найдешь его в библиотеке Забытого Города.', 'Отнесите незаконченное Знамя Вызова Фалрину Садовнику в библиотеку Забытого Города.', 'А, так ты от Антиона, говоришь? А я-то думал, он мертв... Впрочем, случалось мне на своем веку слышать и более странные вещи.$B$BНу что ж. Так чего ты от меня хочешь?', 'Ну, говори, чужестранец, не видишь что ли, я занят!', NULL, NULL, 'Незаконченное Знамя Вызова (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8949, 'Кровная месть Фарлина', 'Да, $C, мне действительно знакомы те чары, которые ты ищешь. Но я не из тех, что оказывают услуги даром, даже тем, кого прислал сюда мой старый приятель.$B$BЯ испытываю глубокую ненависть и презрение к нашим грубым соседям-ограм. И не только к ним: последователей Омокка я ненавижу не меньше, чем сторонников короля Гордока.$B$BУбивай их! И чем больше, тем лучше! Принеси мне в доказательство своего успеха ожерелья, которые огры носят на шее. Сделай это, тогда и поговорим о твоей просьбе.', 'Соберите 25 боевых ожерелий огров с огров Забытого Города или пика Черной горы и вернитесь в Читальню Забытого Города к Фалрину Садовнику.', 'Хм... Как ни странно, но даже это меня не утешило. Ведь мой брат погиб от рук этих тварей!$B$BЧто ж, так или иначе, а ты свою часть сделки выполнил. Поглядим, что я смогу сделать для тебя.', 'Ну что, $N, удалось ли тебе выполнить мою просьбу?', NULL, NULL, 'Боевые бусы огров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8950, 'Чары подстрекателя', 'Я без труда могу наложить на знамя чары, которые тебе нужны, $N. Но к несчастью, у меня нет необходимых материалов: такие заклинания очень мало кто спрашивает.$B$BМне потребуется сущность одного из призраков Элдрета, обитающих в этих залах, горсть черных рун из Некроситета и несколько больших сверкающих осколков. Принеси мне эти реагенты, и я создам для тебя нужные чары.', 'Принесите 1 сущность язвительного призрака, 4 черных руны и 8 больших сверкающих осколков Фалрину Садовнику в Забытом Городе.', 'Да, это отлично подойдет. И когда я закончу, ни одна сила в мире не помешает твоей жертве принять брошенный тобой вызов!', 'Ну что, $N, удалось тебе собрать все необходимые материалы?', NULL, NULL, 'Сущность язвительного призрака', 'Темная руна', 'Большой сверкающий осколок', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8951, 'Прощальные слова Антиона', 'В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!', 'Вернитесь в Стальгорн к Делиане с сапогами дикого cердца, килтом дикого cердца и наплечем дикого сердца.', 'Поверить не могу, что наша жизнь висит на волоске из-за какого-то дурацкого медальона! А ты уверен, что Антион упомянул Бодли?$B$BЛадно, ты свое дело сделал, так что давай закончим и с твоей наградой.', 'Ты вернулся, $N. Расскажи, что тебе довелось узнать. Но сначала поговорим о твоей награде.', NULL, NULL, 'Сапоги дикого сердца', 'Килт дикого сердца', 'Наплеч дикого сердца', 'Верхняя часть амулета Лорда Вальтхалака');
