INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8956, 'Прощальные слова Антиона', 'В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!', 'Принесите в Стальгорн Делиане сапоги Незаметности, штаны Незаметности и наплеч Незаметности.', 'Поверить не могу, что наша жизнь висит на волоске из-за какого-то дурацкого медальона! А ты уверен, что Антион упомянул Бодли?$B$BЛадно, ты свое дело сделал, так что давай закончим и с твоей наградой.', 'Ты вернулся, $N. Расскажи, что тебе довелось узнать. Но сначала поговорим о твоей награде.', NULL, NULL, 'Сапоги незаметности', 'Штаны незаметности', 'Наплеч незаметности', 'Верхняя часть амулета Лорда Вальтхалака');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8957, 'Прощальные слова Антиона', 'В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$B$BЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$B$BНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!', 'Отдайте Моквару в Оргриммаре сапоги Стихий, килт Стихий и наплечье Стихий.', '', NULL, NULL, NULL, 'Сапоги Стихий', 'Килт Стихий', 'Наплечье Стихий', 'Верхняя часть амулета Лорда Вальтхалака');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8958, 'Прощальные слова Антиона', 'В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!', 'Принесите в Стальгорн Делиане сандалии Багрового Тумана, поножи Багрового Тумана и оплечье Багрового Тумана.', '', NULL, NULL, NULL, 'Сандалии Багрового Тумана', 'Поножи Багрового Тумана', 'Оплечье Багрового Тумана', 'Верхняя часть амулета Лорда Вальтхалака');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8959, 'Прощальные слова Антиона', 'В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!', 'Принесите в Стальгорн Делиане сапоги Доблести, ножные латы Доблести и наплеч Доблести.', '', NULL, NULL, NULL, 'Сапоги доблести', 'Ножные латы доблести', 'Наплеч доблести', 'Верхняя часть амулета Лорда Вальтхалака');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8960, 'Злосчастная доля Бодли', 'Значит, нам нужно найти недостающие части и собрать медальон? Но разыскать Бодли будет непросто. Он отправился к Черной горе, хотел еще раз проникнуть в Пик Черной горы. И до сих пор не вернулся.$B$BБоюсь, как бы с ним не случилось беды. На всякий случай возьми с собой спектральный сканер иных измерений. Лучше заранее приготовиться к самому худшему...', 'Отыщите Бодли у Пика Черной горы с помощью спектрального сканера иных измерений.', 'Ты себе даже не представляешь, как я рад, что меня видят и слышатI Наконец я дождался кого-то, с кем можно поговорить!$B$BТы нам поможешь, $N? Мы сами не ведали, что творили, и совершили великое зло, а теперь должны все исправить. Если ты сказал правду и у тебя действительно есть верхняя часть амулета Лорда Вальтхалака, я могу подсказать, где найти две оставшиеся части. Тогда амулет вновь обретет свою целостность, и весь этот ужас закончится.$B$BДа, кстати, меня зовут Бодли. Будем знакомы!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8961, 'Три властелина огня', 'Для того чтобы вызвать Лорда Вальтхалака, первым делом нам нужно собрать амулет воедино. Одна часть у нас есть, еще двух не хватает. Для того чтобы собрать эти части, нам нужно добыть жаровню и особые угли, чтобы зажечь в ней огонь.$B$BТы, может быть, $gслышал:слышала: о трех властелинах огня. Это Лорд Огниус из Глубин Черной горы, Пиростраж Углевзор из Пика Черной горы и Огарцог из Силитуса. Убей их, возьми от каждого по одному углю и принеси их сюда вместе с жаровней Благословения, которую можно купить у приспешников Серебряного Рассвета, если ты пользуешься среди них уважением.', 'Добыть огневит Огниуса, око Углевзора и пепел Огарцога и принести их Бодли в Черную гору вместе с жаровней Благословения.', 'А тебе смелости не занимать, $C! Но сейчас не до комплиментов – времени мало. Не хватает еще нескольких важных компонентов, и их надо собрать как можно скорее.$B$BКогда почувствуешь, что готов, скажи мне, и я дам тебе следующее поручение.', 'А все наша глупость... Зачем мы взялись за эту проклятую работу?! Если бы мы не украли тогда по незнанию душу Лорда Вальтхалака, заключенную в амулете... если бы некоторые в нашей компании не разделили бы из жадности амулет между собой... Сейчас я жил бы себе поживал, да добра наживал! Пил бы свежее пиво, быть может, возился бы со своими детишками.$B$B$N, не допусти, чтобы постыдная алчность, погубившая нашу команду, стала проклятием и для тебя.', NULL, NULL, 'Огневит Опалителя', 'Уголь Углевзора', 'Уголек Огарра', 'Жаровня Благословения');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8962, 'Важная составляющая заклинания', '$C:, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего соратника.$B$BУ Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов. Мне нужно, чтобы ты $gзабрал:забрала: останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса.', 'Найдите останки друидов и принести их Бодли в Черную гору.', '', NULL, NULL, NULL, 'Останки друидов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8963, 'Важная составляющая заклинания', '$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моей павшей соратницы.$B$BИзалиен, наша жрица, выросла в Зимних Ключах в Деревне Звездного Ветра. Забери реликвию Деревни Звездного Ветра у великанов ледяного молота в теснине Ледяного Шепота в южной части Зимних Ключей.', 'Найдите реликвию Деревни Звездного Ветра и принести ее Бодли в Черную гору.', 'Ты хорошо потрудился, $N. Я помещу квинтэссенцию реликвии в жаровню.$B$BОсталось только проникнуть в святилище Элдретарр в восточной части Забытого Города, зажечь в жаровне огонь и вызвать дух Изалиен. Амулет Вальтхалака осквернил ее душу, так что Изалиен не упокоится с миром, пока у нее не отнимут эту проклятую вещь.', 'Я не ожидал, что ты так скоро вернешься, $C. Ты принес то, за чем я тебя посылал?', NULL, NULL, 'Реликвия Деревни Звездного Ветра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8964, 'Важная составляющая заклинания', '$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь. Но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет духов моих бывших соратников.$B$BДжариен и Сотос оставили нас и решили присоединиться к Алому ордену, свято уверовав в его путь. Они так стремились вступить в эту подлую организацию... но не прошли испытания на посвящении. Отправляйся в Длань Тира в Восточных Чумных землях и забери сверкающий меч фанатизма у тамошних преторов.', 'Добудьте сверкающий меч фанатизма и принесите его Бодли в Черную гору.', 'Отлично, $N. Я помещу квинтэссенцию меча в жаровню.$B$BОсталось только проникнуть к Кровавому трону в бастионе Алого ордена в Стратхольме, зажечь в жаровне огонь и вызвать духов Джариен и Сотоса. Даже не знаю, что с ними стало в посмертии… Знаю только, что амулет Вальтхалака исказил их души.', 'Я не ожидал, что ты так скоро вернешься, $C. Ты принес то, за чем я тебя посылал?', NULL, NULL, 'Сверкающий меч фанатизма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8965, 'Важная составляющая заклинания', '$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего товарища.$B$BКормок, огр-некромант, путешествовавший вместе с нами, обосновался впоследствии на южном побережье предгорий Хилсбрада и вызвал души изгнанных мертвецов, обитателей острова Очищения. Иди туда и добудь пепел душ Изгнанников.', 'Добыть пепел душ Изгнанников и принести его Бодли в Черную гору.', '', NULL, NULL, NULL, 'Пепел душ Изгнанников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8966, 'Левая часть амулета Лорда Вальтхалака', 'Мой товарищ Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пал жертвой разрушительных чар осколка духа Лорда, заключенного внутри. После того как мы выкрали книгу заклинаний Вальтхалака и амулет, мы попытались укрыться в верхних пределах Пика Черной горы. Но когда мы туда поднимались, Мор сорвался и упал.$B$BПотом мы узнали, что он не разбился, но его захватил и подверг страшным пыткам воевода Вун. Призрачные убийцы пробрались к нему и убили его на глазах у Вуна.', 'Вызвать дух Мора Серого Копыта с помощью жаровни Призыва, прикончить его и забрать недостающую часть амулета Лорда Вальтхалака. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Вальтхалака и жаровню Призыва.', '', NULL, NULL, NULL, 'Мор Серое Копыто убито', 'Левая часть амулета Лорда Вальтхалака', 'Жаровня Призыва (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8967, 'Левая часть амулета Лорда Вальтхалака', 'Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее поселение своего народа, известное теперь под названием Забытый Город. Насколько нам удалось узнать, она отправилась в Забытый Город как по личным причинам, так и за тем, чтобы вызнать секреты той части амулета лорда Вальтхалака, которую она забрала с собой.$B$BНо ее замыслам не суждено было сбыться. До нас дошли слухи, что у святилища Элдретарр Изалиен попала в засаду, которую устроил Алззин Перевертень.', 'С помощью жаровни Призыва вызвать дух Изалиен и убить ее. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.', 'Спасибо, $N. Твоими стараниями дух Изалиен наконец упокоился с миром. Быть может, теперь она обретет мир и покой в запредельных чертогах своей богини. А вот нам еще долго покой не грозит. Потому что придется как следует потрудиться, чтобы разрешить эту поганую ситуацию.$B$BК сожалению, мне неизвестно, где сейчас владелец правой части амулета. Но не бойся; при жизни я изучал прорицательское искусство и кое-что понимаю в гадании и ворожбе. У меня есть для тебя поручение. Если справишься с ним, мы сумеем узнать, где искать недостающую часть.', 'Ты так быстро исполнил мое поручение, $N? Тебе удалось спасти дух Изалиен и добыть левую часть амулета Лорда Вальтхалака?', NULL, NULL, 'Изалиен убито', 'Левая часть амулета Лорда Вальтхалака', 'Жаровня Призыва (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8968, 'Левая часть амулета Лорда Вальтхалака', 'Наши бывшие соратники, брат с сестрой Сотос и Джариен, решили присоединиться к Алому ордену. Они ушли и забрали с собой левую часть амулета лорда Вальтхалака. Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас ее надо вернуть.$B$BНасколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в бастионе Алого ордена, и верховный рыцарь собственноручно прикончил обоих.$B$BКак бы там ни было, нам нужна эта часть амулета, и мы... то есть ты $gдолжен:должна: будешь ее забрать.', 'Вызвать духов Джариен и Сотоса с помощью жаровни Призыва и убить их обоих. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.', 'Я рад, что души этих двоих наконец обрели покой, хотя, признаться, при жизни я их недолюбливал. Как бы там ни было, теперь у нас есть левая часть амулета, что, безусловно, не может не радовать!$B$BК сожалению, мне неизвестно, где сейчас владелец правой части амулета. Но не бойся; при жизни я изучал прорицательское искусство и кое-что понимаю в гадании и ворожбе. У меня есть для тебя поручение. Если справишься с ним, мы сумеем узнать, где искать недостающую часть.', 'Значит ли это, $C, что твоими стараниями души этих глупцов наконец упокоились с миром и ты забрал левую часть амулета Лорда Вальтхалака?', NULL, NULL, 'Джариен убито', 'Сотос убито', 'Левая часть амулета Лорда Вальтхалака', 'Жаровня Призыва (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8969, 'Левая часть амулета Лорда Вальтхалака', 'Теперь, когда у нас есть все, что нужно для ритуала призыва, осталось решить, кого именно вызвать.$B$BКормок был неплохим парнем, пока не занялся некромантией. Вот тогда нам всем стало по-настоящему жутко – и это при том, что отряд набирали уж явно не из боязливых юнцов и кисейных барышень. Никто не удивился, когда он забрал свою часть амулета и вернулся в свой новый дом в Некроситете.$B$BНо даже там он не укрылся от призрачных убийц. Они прикончили его на глазах у Раса Ледяного Шепота, его хозяина.', 'С помощью жаровни Призыва вызвать дух Кормока и убить его. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.', '', NULL, NULL, NULL, 'Кормок убито', 'Левая часть амулета Лорда Вальтхалака', 'Жаровня Призыва (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8970, 'Я вижу в твоем будущем остров Алькац...', 'Как я уже говорил, $C, при жизни я изучал ворожбу и гадание и даже подумывал о том, чтобы пойти в прорицатели или провидцы. Но это не самое прибыльное занятие. Во-первых, неблагодарное и опасное. А во-вторых, реагенты редки и недешевы. Однако я кое-чему научился, и моих знаний хватит, чтобы найти последнюю часть амулета, а вместе с нею – и дух моего павшего соратника.$B$BНо мне понадобится твоя помощь, $N. Отправляйся на остров Алькац у побережья Пылевых топей и собери кровавую ламинарию у наг из клана Страшаз, которые там обитают.', 'Собрать 20 порций кровавой ламинарии у наг из клана Страшаз и принести их Бодли в Черную гору.', 'Честно признаюсь, $N, я уже и не чаял увидеть тебя живым. Впрочем, сейчас у нас есть и другие заботы, помимо Алькаца.$B$BЛадно, мне надо сосредоточиться... прорицательство – это тебе не в носу ковыряться... А как ты думал? Щелкнешь пальцами раз-другой, и сразу получишь четкий и ясный ответ? Нет, $N, все не так просто.', 'Кровавая ламинария, $N, много кровавой ламинарии – чем больше, тем лучше. Она нужна мне для того, чтобы обострить мои провидческие способности. Думаю, один ты не справишься. Лучше возьми с собой пару-тройку друзей... эти наги Страшаза – поистине мерзкие твари!', NULL, NULL, 'Кровавая ламинария', 'Левая часть амулета Лорда Вальтхалака', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8977, 'Возвращение к Делиане', 'Приятно было поработать с тобой, $N! Вот, твой заказ готов.$B$BНадеюсь, мои изделия тебе пригодятся. И кстати, если ты не против, расскажи обо мне другим. Лишние заказчики мне совсем не помешают!', 'Принесите спектральный сканер иных измерений Делиане в Стальгорн.', 'Блестяще! Ты на славу постарался, $N. Хотя я гоблинским изделиям и не доверяю, но выбора у меня нет.', 'Уже вернулся?', NULL, NULL, 'Спектральный сканер иных измерений (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8978, 'Возвращение к Моквару', 'Приятно было поработать с тобой, $N! Вот, твой заказ готов.$B$BНадеюсь, мои изделия тебе пригодятся. И кстати, если ты не против, расскажи обо мне другим. Лишние заказчики мне совсем не помешают!', 'Принесите Моквару в Оргриммар спектральный сканер иных измерений.', 'Он у тебя! Ты молодец, $N. Я впечатлен. Отличная работа!', 'Ну что, ты принес мне прибор?', NULL, NULL, 'Спектральный сканер иных измерений (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8979, 'Подозрения Фенстада', 'Кажется, я понял причину странностей, происходящих в последнее время. Ты чувствуешь новый запах в воздухе, перебивающий даже вонь от каналов? Запах новых одеколонов и духов, только что вошедших в моду?$B$BНаш разум затуманен какой-то гнусной алхимией.$B$BЕсть только один способ убедиться – отнести флакон одеколона и духов аптекарю Зинг. Королевское фармацевтическое общество отыщет истину.$B$BЯ возмещу тебе цену покупки, когда ты вернешься.', 'Отнесите 1 флакон одеколона и 1 флакон духов аптекарю Зинг в Район Фармацевтов в Подгороде.', 'Понятно, еще одна навязчивая идея Фенстада. Он что думает, Королевскому фармацевтическому обществу нечем больше заняться, только проводить для него всякие мелкие расследования?$B$BНу что ж, еще раз я потешу его душу.', 'Чем могу служить?', NULL, NULL, 'Флакон одеколона', 'Флакон духов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8980, 'Мнение Зинг', 'Это неожиданно. Похоже, Фенстад в конце концов все-таки что-то нарыл. Я нашла следы веществ, используемых в зельях контроля над разумом.$B$BИзвестно, что такие вещества используются в некоторых духах, но некоторые из обнаруженных мною ингридиентов... Это серьезная алхимия, даже для того, кто наделен способностями участника Королевского фармацевтического общества.', 'Вернитесь к Фенстаду Аргайлу, ожидающему около банка в Подгороде.', 'Так я был прав! Не следует тратить время зря. Мы должны определить источник этих порочных ароматов.$B$BВот возмещение за купленные тобою духи и одеколон.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8981, 'Подношение даров', '', 'Ты здесь для того, чтобы поднести дар любви и уважения своему великому вождю?', 'Чудесно! Замечательно! Я добавлю это к куче других подарков.$B$BЯ не ждал, что их будет так много! Должно быть, вы поистине питаете любовь к своим вождям.$B$BПогоди, я добавлю еще один к общему счету...', NULL, NULL, NULL, 'Подарочный набор Орды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8982, 'Поиск источника', 'Мы должны узнать, кто поставщик. Я заметил у аптекаря Катрины в сумке флакон духов. Она сказала, что приобрела его у Нормана, хозяина таверны.', 'Поговорите с хозяином таверны Норманом в Подгороде.', 'О да, я лишь недавно получил партию духов и одеколона. Я не знаю, надолго ли они задержатся на полках – похоже, всем эти запахи нравятся. $B$BНо если хочешь спросить мое мнение, то я не знаю, что в этом такого.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8983, 'Поиск источника', 'Что-то не так с тем, чем я торгую? Ну, я никогда не видел, чтобы так много народа столь отчаянно чего-нибудь жаждало.$B$BЯ покупаю припасы у торговки по имени Мара Ренник. Она в городе недавно.$B$BОна упоминала, что хочет доставить кое-какие товары торговцу одеждой в Квартал Магов.', 'Поговорите с Марой Ренник в портновской лавке в Квартале Магов Подгорода.', 'Боюсь, я продала всю партию духов и одеколона Норману, хозяину таверны. Если они тебе нужны, поговори с ним – может быть, у него что-то еще осталось.$B$BНо не трать времени. Полагаю, ты сочтешь запах одеколона просто неотразимым.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8984, 'Источник обнаружен', 'Видишь ли, действия какого-то негодяя-аптекаря – не моя забота. Если он вредит нашему делу, то я буду первой, кто укажет тебе нужное направление поисков.$B$BЕсли он невиновен, то ему нечего скрывать, верно?$B$BЯ приобрела товары у аптекаря Стаффрона Лерента. Он работает в укромном уголке за поместьем Черный Ворон в предгорях Хилсбрада. Честно говоря, он показался мне несколько странным.', 'Найдите аптекаря Стаффрона Лерента в предгорьях Хилсбрада за поместьем Черный Ворон.', 'Да, я сделал эти благовония. Чудный запах, не так ли? Неотразимый.$B$BКогда воины Альянса и Орды равно будут сражены этой любовью, они не смогут остановить воздвижение Совета Тени.$B$BОни окажется ослабленными и неподготовленными. Беспокоясь за тех, кого любят, они потеряют бдительность.$B$BРешение было таким простым. Почему понадобилось столько времени, чтобы найти его? Слабое место любого – его сердце. И тебе уже не остановить неизбежное.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8985, 'Еще одна важная составляющая заклинания', '$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моей павшей соратницы.$B$BИзалиен, наша жрица, выросла в Зимних Ключах в Деревне Звездного Ветра. Забери реликвию Деревни Звездного Ветра у великанов ледяного молота в теснине Ледяного Шепота в южной части Зимних Ключей.', 'Найдите реликвию Деревни Звездного Ветра и принести ее Бодли в Черную гору.', '', NULL, NULL, NULL, 'Реликвия Деревни Звездного Ветра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8986, 'Еще одна важная составляющая заклинания', '$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего соратника.$B$BУ Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов. Мне нужно, чтобы ты $gзабрал:забрала: останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса.', 'Найдите останки друидов и принести их Бодли в Черную гору. ', 'Ты хорошо потрудился, $N. Я помещу квинтэссенцию этих останков в жаровню.$B$BОсталось только проникнуть в нижний предел Пика Черной горы, в чертог воеводы Вуна в Тазз\'Алаоре, зажечь в жаровне огонь и вызвать оскверненный дух Мора Серого Копыта. Его душа не упокоится с миром, пока у него не отнимут этот проклятый амулет.$B$BДа, кстати, у меня тут осталось немного кровавой ламинарии, которую ты мне привез с острова Алькац, и я наварил тебе зелий. Бери, бери. Штука полезная!', 'Я не ожидал, что ты так скоро вернешься, $C. Ты принес то, за чем я тебя посылал?', NULL, NULL, 'Останки друидов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8987, 'Еще одна важная составляющая заклинания', '$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь. Но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет духов моих бывших соратников.$B$BДжариен и Сотос оставили нас и решили присоединиться к Алому ордену, свято уверовав в его путь. Они так стремились вступить в эту подлую организацию... но не прошли испытания на посвящении. Отправляйся в Длань Тира в Восточные Чумные земли и забери сверкающий меч фанатизма у тамошних преторов.', 'Добудьте сверкающий меч фанатизма и принесите его Бодли в Черную гору.', '', NULL, NULL, NULL, 'Сверкающий меч фанатизма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8988, 'Еще одна важная составляющая заклинания', '$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего товарища.$B$BКормок, огр-некромант, путешествовавший вместе с нами, обосновался впоследствии на южном побережье предгорий Хилсбрада и вызвал души изгнанных мертвецов, обитателей острова Очищения. Иди туда и добудь пепел душ Изгнанников.', 'Добыть пепел душ Изгнанников и принести его Бодли в Черную гору.', 'Ты хорошо потрудилась, $N. Я помещу квинтэссенцию пепла в жаровню.$B$BОсталось только проникнуть в чертог Раса Ледяного Шепота в Некроситете, зажечь в жаровне огонь и вызвать Кормока. Амулет Вальтхалака исказил дух, так что Кормок не упокоится с миром, пока у него не отнимут эту проклятую вещь. Добром он ее не отдаст. Тебе придется действовать силой.$B$BДа, кстати, у меня тут осталось немного кровавой ламинарии, которую ты мне привезла с острова Алькац, и я наварил тебе зелий. Бери, бери. Штука полезная!', NULL, NULL, NULL, 'Пепел душ Изгнанников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8989, 'Правая часть амулета Лорда Вальтхалака', 'Мой товарищ Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пал жертвой разрушительных чар осколка духа Лорда, заключенного внутри. После того как мы выкрали книгу заклинаний Вальтхалака и амулет, мы попытались укрыться в верхних пределах Пика Черной горы. Но когда мы туда поднимались, Мор сорвался и упал.$B$BПотом мы узнали, что он не разбился, но его захватил и подверг страшным пыткам воевода Вун. Призрачные убийцы пробрались к нему и убили его на глазах у Вуна.', 'Вызвать дух Мора Серого Копыта с помощью жаровни Призыва, прикончить его и забрать недостающую часть амулета Лорда Вальтхалака. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.', 'Спасибо тебе за помощь, $N. Неприкаянный дух Мора наконец упокоился с миром, и теперь у нас есть восстановленный амулет! Но самое трудное испытание еще впереди.$B$BДля того чтобы правильно настроить жаровню и вызвать дух Лорда Вальтхалака, нам нужно собрать еще несколько компонентов для завершающего заклинания. Собери их все и принеси мне сюда.', 'У тебя получилось? Ты добыл правую часть амулета Лорда Вальтхалака, восстановил целостность амулета и сделал так, чтобы дух моего старого друга Мора Серого Копыта наконец упокоился с миром?', NULL, NULL, 'Мор Серое Копыто убито', 'Амулет Лорда Вальтхалака', 'Жаровня Призыва (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8990, 'Правая часть амулета Лорда Вальтхалака', 'Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее поселение своего народа, известное теперь под названием Забытый Город. Насколько нам удалось узнать, она отправилась в Забытый Город как по личным причинам, так и за тем, чтобы вызнать секреты той части амулета лорда Вальтхалака, которую она забрала с собой.$B$BНо ее замыслам не суждено было сбыться. До нас дошли слухи, что у святилища Элдретарр Изалиен попала в засаду, которую устроил Алззин Перевертень.', 'С помощью жаровни Призыва вызвать дух Изалиен и убить ее. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.', '', NULL, NULL, NULL, 'Изалиен убито', 'Амулет Лорда Вальтхалака', 'Жаровня Призыва (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8991, 'Правая часть амулета Лорда Вальтхалака', 'Наши бывшие соратники Сотос и Джариен некогда решили вступить в ряды Алого ордена. Уходя, они забрали с собой правую часть амулета лорда Вальтхалака. Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас ее надо вернуть.$B$BНасколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в бастионе Алого ордена, и верховный рыцарь собственноручно прикончил обоих.$B$BКак бы там ни было, нам нужна эта часть амулета, и мы... то есть ты... $gдолжен:должна: будешь ее забрать.', 'Вызвать духов Джариен и Сотоса с помощью жаровни Призыва и убить их обоих. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.', 'Я рад, что души этих двоих наконец обрели покой, хотя, признаться, при жизни я их недолюбливал. Как бы там ни было, теперь у нас есть восстановленный амулет! Но самое трудное испытание еще впереди.$B$BДля того чтобы правильно настроить жаровню и вызвать дух Лорда Вальтхалака, нам нужно собрать еще несколько компонентов для завершающего заклинания. Собери их все и принеси мне сюда.', 'Значит ли это, $C, что твоими стараниями души этих глупцов наконец упокоились с миром и ты забрал недостающую часть амулета Лорда Вальтхалака?', NULL, NULL, 'Джариен убито', 'Сотос убито', 'Амулет Лорда Вальтхалака', 'Жаровня Призыва (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8992, 'Правая часть амулета Лорда Вальтхалака', 'Теперь, когда у нас есть все, что нужно для ритуала призыва, осталось решить, кого именно вызвать.$B$BКормок был неплохим парнем, пока не занялся некромантией. Вот тогда нам всем стало по-настоящему жутко – и это при том, что отряд набирали уж явно не из боязливых юнцов и кисейных барышень. Никто не удивился, когда он забрал свою часть амулета и вернулся в свой новый дом в Некроситете.$B$BНо даже там он не укрылся от призрачных убийц. Они прикончили его на глазах у Раса Ледяного Шепота, его хозяина.', 'С помощью жаровни Призыва вызвать дух Кормока и убить его. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.', 'Отлично сработано, $N! Кормок был не таким уж плохим огром, во всяком случае при жизни. И я искренне надеюсь, что теперь он обрел покой. Итак, теперь у нас есть восстановленный амулет! Но самое трудное испытание еще впереди.$B$BДля того чтобы правильно настроить жаровню и вызвать дух Лорда Вальтхалака, нам нужно собрать еще несколько компонентов для завершающего заклинания. Собери их все и принеси мне сюда.', NULL, NULL, NULL, 'Кормок убито', 'Амулет Лорда Вальтхалака', 'Жаровня Призыва (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8993, 'Подношение даров', '', '', 'Чудесно! Замечательно! Я добавлю это к куче других подарков.$B$BЯ не ждал, что их будет так много! Должно быть, вы поистине питаете великую любовь к своим вождям.$B$BПогоди, я добавлю еще один к общему счету...', NULL, NULL, NULL, 'Подарочный набор Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8994, 'Последние приготовления', 'У нас почти все готово, $C. Осталось найти еще несколько компонентов, и тогда я смогу должным образом настроить жаровню и вызвать дух лорда Вальталака.$B$BДля начала я попрошу тебя отправиться в пик Черной горы и перебить тамошних орков. Они носят наручи из особого сплава металлов, один из которых как раз мне и нужен. Постарайся собрать их как можно больше, чтобы я смог извлечь необходимое количество металла. И еще мне понадобится настой великой силы. Без нее я не смогу завершить заклинание.$B$BИди, $N, удачи тебе!', 'Соберите 40 наручей Черной горы и добудьте настой великой силы. Отнесите все это Бодли в Черную гору.', 'Замечательно! Как раз то, что нужно! Я добуду металл из наручей и положу в жаровню последние компоненты. Когда все будет готово, ты сможешь вызвать дух Лорда Вальтхалака, и амулет наконец-то вернется к хозяину.$B$BТы прошел долгий путь, $N. Так не останавливайся теперь, когда до конца остается всего один шаг!', 'Мы через многое прошли вместе, $N, и я просто хотел сказать... как бы все ни обернулось, я очень тебе благодарен! Ты рисковал жизнью, чтобы помочь уцелевшим участникам нашей команды наемников. Мне кажется, что теперь ты тоже один из нас.', NULL, NULL, 'Боевые наручи Черной горы', 'Настой великой силы', 'Амулет Лорда Вальтхалака', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8995, 'Mea Culpa, Лорд Вальтхалак', 'Теперь все готово, $N.$B$BПри жизни Лорд Вальтхалак жил в чертоге, который теперь называется чертогом Зверя. Отправляйся туда, зажги огонь в жаровне Призыва и вызови дух владыки. При этом Вальтхалак вновь обретет тело, и тебе придется убить его еще раз. Но сначала тебе нужно сразиться со Зверем владыки, так что лучше иди не $gодин:одна:, а возьми себе в помощь верных друзей, ибо немногие возвращались из верхних пределов Пика Черной горы живыми.$B$BКогда убьешь Вальтхалака, используй амулет. Как только дух Лорда обретет целостность, он потребует вернуть ему амулет. И это его право!$B$BУдачи!', 'Вызвать Лорда Вальтхалака с помощью жаровни Призыва. Убить его и использовать амулет. Потом вернуть амулет духу Вальтхалака.', 'Твое счастье, смертный, что тебя не было среди тех подонков, которые украли мой амулет.$B$BТеперь я возьму то, что принадлежит мне по праву! Отдай мне амулет!', '$C, как ты посмел нарушить мой покой?!', NULL, NULL, 'Лорд Вальтхалак убито', 'Амулет Лорда Вальтхалака', 'Жаровня Призыва', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8996, 'Возвращение к Бодли', 'На сей раз я прощаю тебе твою дерзость, $C, потому что сегодня ты $gсовершил:совершила: благородный поступок: $gвернул:вернула: мне недостающие части моей украденной души. Быть может, тебе не хватает телесной мощи, $r, но ты $gкрепок духом, смел и отважен:крепка духом: смела и отважна;, в отличие от тех, кто украл мою душу!$B$BВозвращайся к ним, пока я не передумал и не прикончил тебя на месте. Иди к ним и скажи, что им ничего не грозит... до поры до времени.', 'Вернитесь к Бодли в Черную гору и отдайте ему жаровню Призыва.', 'Что, правда?! Он так и сказал?! Ушам не верю! Он действительно собирается отозвать призрачных убийц?! Хотя, как я понимаю, он намекнул, что в будущем намеревается разобраться с моими товарищами – с теми, кто еще жив.$B$BСегодня – великий день, $N! Ты сумел сделать то, что удавалось лишь считаным единицам, и хоть и отчасти, но все-таки освободил нас от прошлых грехов.$B$BСпасибо! Прими это в знак благодарности. Эту вещь можно использовать для призыва тех духов, с которыми ты уже имел дело, и некоторых других...', '$N, ты вернулся живым! Выходит, теперь ты один из нас.$B$B!Ну, давай же! Скорее рассказывай!', NULL, NULL, 'Жаровня Призыва', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8997, 'Круг замкнулся', 'Как это ни грустно, $gдружище:моя госпожа:, пришло время прощаться. Но если ты вдруг соберешься меня навестить, я всегда буду рад встрече с $gдругом:доброй подругой:. Приходи, когда хочешь. Может быть, даже в самое ближайшее время, пока ты еще не $gотправился:отправилась: в Пик Черной горы.$B$BЛадно, долгие проводы – лишние слезы. Иди, пока я действительно не прослезился. Возвращайся к Делиане в Стальгорн и расскажи ей обо всем, что случилось.', 'Поговорите с Делианой в Высоком троне в Стальгорне.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8998, 'Круг замкнулся', 'Как это ни грустно, $gдружище:моя госпожа:, пришло время прощаться. Но если ты вдруг соберешься меня навестить, я всегда буду рад встрече с $gдругом:доброй подругой:. Приходи когда хочешь. Может быть, даже в самое ближайшее время, пока ты еще не $gотправился:отправилась: в Пик Черной горы.$B$BЛадно, долгие проводы – лишние слезы. Иди, пока я действительно не прослезился. Возвращайся к Моквару в Оргриммар и расскажи ему обо всем, что случилось.', 'Поговорите с Мокваром в крепости Громмаш в Аллее Мудрости в Оргриммаре.', 'Рад, что с тобой ничего не случилось, $N. Кстати, ты выглядишь очень неплохо. Возмужал, заматерел... сразу видно, бывалый боец.$B$BНу, садись и рассказывай, где ты был и что видел.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (8999, 'Сладкое – на закуску', 'Замечательная история, $N! Спасибо тебе и сердечная благодарность всем, кто принимал участие. Может, сегодня ночью я хоть нормально посплю.$B$BВ награду хочу предложить несколько вещичек, что тебя, наверное, порадуют.', 'Отдайте Делиане клобук и жилет Буйного Сердца.', '', NULL, NULL, NULL, 'Клобук дикого сердца', 'Жилет дикого сердца', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9000, 'Сладкое – на закуску', 'Замечательная история, $N! Спасибо тебе и сердечная благодарность всем, кто принимал участие. Может, сегодня ночью я хоть нормально посплю.$B$BВ награду хочу предложить несколько вещичек, что тебя, наверное, порадуют.', 'Отдайте Делиане шапку и мундир загонщика.', '', NULL, NULL, NULL, 'Шапка загонщика', 'Мундир загонщика', NULL, NULL);
