INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9015, 'Вызов', 'Слушай внимательно, $N. Тебе нужно будет войти в Зал Правосудия в Глубинах Черной горы. Когда верховный судья Мрачнокамень вынесет тебе приговор, вонзи знамя в землю в знак открытого неповиновения.$B$BТелдрен не сможет сдержаться и примет вызов на бой, горя желанием драться. Убей его и забери то, что должно забрать, после чего передай эту вещь Антиону.', 'Войдите в Зал Правосудия в Глубинах Черной горы, выслушайте приговор верховного судьи Мрачнокамня и вонзите знамя Вызова в центр круга. Убейте Телдрена и его гладиаторов, после чего вернитесь к Антиону Хармону в Восточные Чумные земли с первой частью амулета Лорда Вальтхалака.', 'Ты добыл часть медальона, $N?', 'Ты вернулся, $N!', NULL, NULL, 'Команда Телдрена побеждена', 'Верхняя часть амулета Лорда Вальтхалака', 'Знамя Вызова', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9016, 'Прощальные слова Антиона', 'В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$B$BЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$B$BНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!', 'Отдайте Моквару в Оргриммаре сапоги дикого Сердца, килт дикого сердца и наплеч буйного сердца.', 'Это проклятие пало на нас из-за какого-то медальона! Да, видно, Лорда Вальтхалак – мужик злопамятный.$B$BНу что ж, попробуем отыскать оставшиеся части – надеюсь, нам это удастся до того, как меня постигнет безвременная кончина. Но все-таки давай сначала разберемся с твоей наградой.', 'А, $N, ты снова здесь! По глазам вижу, что тебе есть о чем мне рассказать. Но сначала давай разберемся с твоей наградой.', NULL, NULL, 'Сапоги дикого сердца', 'Килт дикого сердца', 'Наплеч дикого сердца', 'Верхняя часть амулета Лорда Вальтхалака');
