INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9021, 'Прощальные слова Антиона', 'В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$B$BЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$B$BНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!', 'Отдайте Моквару в Оргриммаре сандалии Багрового Тумана, поножи Багрового Тумана и оплечье Багрового Тумана.', '', NULL, NULL, NULL, 'Сандалии Багрового Тумана', 'Поножи Багрового Тумана', 'Оплечье Багрового Тумана', 'Верхняя часть амулета Лорда Вальтхалака');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9022, 'Прощальные слова Антиона', 'В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$B$BЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$B$BНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!', 'Отдайте Моквару в Оргриммаре сапоги Доблести, ножные латы Доблести и наплеч Доблести.', '', NULL, NULL, NULL, 'Сапоги доблести', 'Ножные латы доблести', 'Наплеч доблести', 'Верхняя часть амулета Лорда Вальтхалака');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9023, 'Идеальный яд', 'Мы с братом занимаемся составлением ядов для поместья Черный Ворон.$B$BЛорд Черный Ворон поручил мне исследование нового и очень эффективного яда, который производится из ядовитых желез обителей Зул\'Гуруба и руин Ан\'Киража.$B$BВ этих проклятых руинах живут две опасных твари, которые годятся для наших целей. Принеси мне ядовитые железы Куриннакс и Веноксиса, и заслужишь мою вечную признательность.', 'Дирк Громодрев из крепости Кенария попросил принести ему ядовитую железу Веноксиса и ядовитую железу Куриннакса.', 'Прими благодарность Черного Ворона! Выбирай!', 'Дельце не простое, $N. Без помощников тебе не обойтись.', NULL, NULL, 'Ядовитая железа Веноксиса', 'Ядовитая железа Куриннакса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9024, 'Подозрения Аристана', 'Я понял! Ты чувствуешь новый запах в воздухе? Запах новых одеколонов и духов, только что вошедших в моду? Наши стражи не стали бы так просто пренебрегать своими обязанностями.$B$BИменно так – разве что их разум затуманен какой-то гнусной алхимией.$B$BЕсть только один способ убедиться – отнеси флакон одеколона и духов Моргану Песту и расскажи ему о моих подозрениях. Я возмещу тебе затраты, когда ты вернешься.', 'Отнесите 1 флакон одеколона и 1 флакон духов Моргану Песту в Торговый квартал Штормграда.', 'Я понимаю тревогу Аристана, но мне кажется, он перестарался. Пусть молодые мужчины и женщины делают то, что им нравится. Я думаю, Аристан просто забыл, что такое быть молодым и влюбленным.$B$BНо лучше ему этого не говорить. У него странное чувство юмора.', 'Я чем-нибудь могу тебе помочь?', NULL, NULL, 'Флакон одеколона', 'Флакон духов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9025, 'Открытие Моргана', 'Ну-с, что я скажу... Похоже, Аристан в конце концов все-таки напал на какой-то след. Я нашел остатки веществ, используемых в любовных зельях и хитрых средствах контроля разума.$B$BИзвестно, что такие вещества используются в некоторых духах, но некоторые из обнаруженных мною ингредиентов... Пахнет занятно.', 'Вернитесь к Аристану Моттару, ожидающему около банка в Торговом квартале Штормграда.', 'Хотя я так и думал, что дело в этом, однако от того, что мои подозрения подтвердились, на душе спокойнее не стало. Мы должны тщательно продумать следующий шаг. $B$BВот возмещение за купленные тобою духи и одеколон.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9026, 'Поиск источника', 'Мы должны найти источник. Я видел гораздо больше народа, чем обычно, – в том числе и стражей – входящими в \"Позолоченную розу\" и выходящими оттуда. Поговори с Эллисон. Если она продает эти духи, она должна знать, откуда они взялись.', 'Поговорите с хозяйкой таверны \"Позолоченная роза\" Аллисон в Торговом квартале Штормграда.', 'О да, я лишь недавно получила партию духов и одеколона. Они очень хорошо расходятся, и я не знаю, надолго ли они задержатся на полках.$B$BНо если хочешь спросить мое мнение, то это как-то скучно, когда все пахнут одинаково. Да, запах хороший, но все же...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9027, 'Поиск источника', 'В этом одеколоне есть что-то интересное? Возможно. Никогда не видела, чтобы столько народа так страстно желали приобрести один и тот же товар.$B$BПослушай, если с этим что-то не так, я тоже хочу знать. Я купила всю партию у торговца по имени Эверт Соризам. Он в городе недавно.$B$BОн упоминал, что собирается доставить кое-какие товары в \"Тончайшую пряжу\".', 'Поговорите с Эвертом Соризамом в \"Тончайшей пряже\" у каналов Штормграда.', 'Да, конечно. Эти благовония в нынешнем сезоне расходятся моментом. Только за последний час у меня уже пять или шесть раз спрашивали о них.$B$BБоюсь, я продал всю партию этого товара. Если он тебе нужен, поговори с хозяйкой таверны Эллисон в \"Позолоченной Розе\".$B$BНо не трать времени. Полагаю, ты сочтешь запах одеколона просто неотразимым', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9028, 'Источник обнаружен', 'Что? Предательство? Нет, нет, заверяю тебя, мои намерения были совершенно безобидными.$B$BЧто плохого в том, чтобы слегка помочь тем, кто желает облегчить мучительный ритуал ухаживания? Пойми, это не преступление.$B$BИ чтобы доказать, что я ничего плохого не желал, я даже назову источник этих благовоний. $B$BИх поставлял мне Стаффрон Лерент, какой-то аптекарь. Я никогда не говорил с ним.$B$BГоблин-посредник сказал, что этот аптекарь работает где-то в предгорьях Хилсбрада, за тем загадочным поместьем Черный Ворон. Желаю тебе удачи в поисках.', 'Найдите аптекаря Стаффрона Лерента в предгорьях Хилсбрада за поместьем Черный Ворон.', 'Да, я сделал эти благовония. Чудный запах, не так ли? Неотразимый.$B$BКогда воины Альянса и Орды равно будут сражены этой любовью, они не смогут остановить воздвижение Совета Тени.$B$BОни окажется ослабленными и неподготовленными. Беспокоясь за тех, кого любят, они потеряют бдительность.$B$BРешение было таким простым. Почему понадобилось столько времени, чтобы найти его? Слабое место любого – его сердце. И тебе уже не остановить неизбежное.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9029, 'Бурлящий котел', '', '', 'Из котла разносится приятный запах.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9030, 'Прощальные слова Антиона', 'В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$B$BЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Делиане и скажи ей, что Бодли – ее единственная надежда найти оставшиеся части. $B$BНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!', 'Поговорите с Делианой из Стальгорна.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9032, 'Злосчастная доля Бодли', 'В медальоне заключена душа Вальтхалака? Неудивительно, что его охраняет столь мощное проклятие.$B$BНо разыскать Бодли будет непросто. Насколько я знаю, он собирался вернуться в Пик Черной горы, и с тех пор о нем больше никто не слышал.$B$BПопробуй найти его в Черной горе, хотя весьма вероятно, что Бодли уже нет в живых. Так что я бы тебе посоветовал взять с собой спектральный сканер иных измерений. Как ни горько мне говорить об этом, но лучше заранее приготовиться к самому худшему...', 'Отыщите Бодли у Пика Черной горы с помощью спектрального сканера иных измерений.', 'Ты себе даже не представляешь, как я рад, что меня видят и слышатI Наконец я дождался кого-то, с кем можно поговорить!$B$BТы нам поможешь, $N? Мы сами не ведали, что творили, и совершили великое зло, а теперь должны все исправить. Если ты сказал правду и у тебя действительно есть верхняя часть амулета Лорда Вальтхалака, я могу подсказать, где найти две оставшиеся его части. Тогда амулет вновь обретет свою целостность, и весь этот ужас закончится.$B$BДа, кстати, меня зовут Бодли. Будем знакомы!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9033, 'Отголоски войны', 'С последней войны прошло пять лет…$B$BПогибли десятки тысяч, и все ради чего? Нам так и не удалось избавиться от угрозы.$B$BТеперь же Король-лич вновь поднимает голову. Его правая рука, Кел\'Тузад, готовится напасть на наши земли.$B$BОн не пройдет! Докажи свою преданность нашему делу. Рискни своей жизнью ради победы над Плетью, а Серебряный Рассвет и Алый Марш прикроют тебя со спины.$B$BСтупай в Наксрамас и уничтожь воинство Плети...', 'Командор Элигор Вестник Рассвета из часовни Последней Надежды, что в Восточных Чумных землях просит убить 5 ходячих ужасов, 5 каменных горгулий, 8 капитанов рыцарей смерти и 3 ядовитых пауков-скакунов.', 'Что ж, отличная работа! Ты получишь награду за верную службу обитателям часовни Светлых надежд.', NULL, NULL, NULL, 'Капитан рыцарей смерти убито', 'Ядовитый паук-скакун убито', 'Живое чудовище убито', 'Каменная горгулья убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9034, 'Кираса неустрашимости', 'Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.', 'Корфакс из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать кирасу дредноута, если вы принесете ему 1 испоганенную кирасу, 25 обломков доспехов, 4 слитка арканита и 2 кристалла-источника.', '', NULL, NULL, NULL, 'Испоганенная кираса', 'Обломок доспехов', 'Арканитовый слиток', 'Кристалл-источник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9035, 'Засада на дороге', 'Эй! Помоги, пожалуйста!$B$BНа нас с товарищем напали Презренные! Они так алчут магии, что забрали буквально все, что нашли: и кристаллы маны, и жезлы, и книги заклинаний... ну, то есть все!$B$BМеледор погнался за ними, а мне пришлось остаться, чтобы приглядывать за тем, что они не сумели отнять. Догони его, посмотри, вдруг ты сумеешь ему помочь...', 'Поговорите с учеником Меледором в лесах Вечной Песни на дороге, ведущей из Луносвета на юг.', 'Все, сбежали. Видно, не понравился им мой огненный шар! Но вот вещи наши они побросали в реку...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9036, 'Ножные латы неустрашимости', 'Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.', 'Корфакс из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать ножные латы дредноута, если вы принесете ему следующее: 1 испоганенные ножные латы, 20 обломков доспехов, 4 слитка арканита и 3 обработанных грубых шкуры.', '', NULL, NULL, NULL, 'Испоганенные ножные латы', 'Обломок доспехов', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9037, 'Полный шлем неустрашимости', 'Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.', 'Корфакс из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать шлем дредноута, если вы принесете ему 1 испоганенный шлем, 15 обломков доспехов, 5 слитков арканита и 1 кристалл-источник.', 'Не забывай, пока мозг цел – есть шансы выжить. Носи этот шлем, не снимая!', 'Голова куда уязвимей остального тела.', NULL, NULL, 'Испоганенный полный шлем', 'Обломок доспехов', 'Арканитовый слиток', 'Кристалл-источник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9038, 'Наплечье неустрашимости', 'Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.', 'Корфакс из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать наплечье дредноута, если вы принесете ему следующее: 1 испоганенное наплечье, 12 обломков доспехов, 2 слитка арканита и 3 обработанных грубых шкуры.', 'Мне всегда казалось, что наплечники – самая броская часть доспеха. Надеюсь, ты со мной согласен.', 'Самое главное – оковка.', NULL, NULL, 'Испоганенное наплечье', 'Обломок доспехов', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9039, 'Башмаки неустрашимости', 'Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.', 'Корфакс из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать башмаки дредноута, если вы принесете ему следующее: 1 испоганенные башмаки, 12 обломков доспехов, 2 слитка арканита и 3 обработанных грубых шкуры.', 'Помню, как на прошлой войне Могрейн давил черепа нежити этими самыми башмаками!', 'Не стоит недооценивать хорошую обувь! Особенно если ее сделал Корфакс.', NULL, NULL, 'Испоганенные башмаки', 'Обломок доспехов', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9040, 'Рукавицы неустрашимости', 'Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.', 'Корфакс из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать рукавицы дредноута, если вы принесете ему следующее: 1 испоганенные рукавицы, 8 обломков доспехов, 1 слиток арканита и 5 обработанных грубых шкур.', 'Да сомкнутся твои пальцы на горле Кел\'Тузада.$B$B*Корфакс изображает, будто кого-то душит.*', 'В этих рукавицах пристало держать достойное оружие.', NULL, NULL, 'Испоганенные рукавицы', 'Обломок доспехов', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9041, 'Воинский пояс неустрашимости', 'Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.', 'Корфакс из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать боевой пояс дредноута, если вы принесете ему 1 испоганенный латный пояс, 8 обломков доспехов, 1 слиток арканита и 5 обработанных грубых шкур.', 'С его помощью можно удавить врага-другого. Или отправиться на гоблинскую дискотеку. Ты будешь звездой вечера!', 'Пояс – это не только модный аксессуар, но и важная часть доспеха.', NULL, NULL, 'Оскверненный воинский пояс', 'Обломок доспехов', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9042, 'Наручи неустрашимости', 'Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.', 'Корфакс из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать наручи дредноута, если вы принесете ему 1 испоганенные наручи, 6 обломков доспехов, 1 слиток арканита и 1 кристалл-источник.', 'Не забывай, что запястья – пятая по уязвимости часть тела! Защити свои запястья, а они уж охранят и локти. Может быть.', 'Запястье стоит на втором месте по уязвимости. Или на четвертом?', NULL, NULL, 'Оскверненные наручи', 'Обломок доспехов', 'Арканитовый слиток', 'Кристалл-источник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9043, 'Мундир Искупления', 'Убивая лордов Наксрамаса, ты найдешь остатки доспехов наших павших героев. Принеси их мне. Заодно захвати обломки лат, поврежденных в бою, и материалы, способные вдохнуть новую жизнь в оскверненные доспехи. Тогда я сделаю тебе очень неплохую броню.', 'Командор Элигор Вестник Рассвета из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать мундир искупления, если вы принесете ему следующее: 1 испоганенный мундир, 25 обломков доспехов, 4 слитка арканита и 3 обработанных грубых шкуры.', '', NULL, NULL, NULL, 'Оскверненный мундир', 'Обломок доспехов', 'Арканитовый слиток', 'Обработанная грубая шкура');
