INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9049, 'Ремень Искупления', 'Убивая лордов Наксрамаса, ты найдешь остатки доспехов наших павших героев. Принеси их мне. Заодно захвати обломки лат, поврежденных в бою, и материалы, способные вдохнуть новую жизнь в оскверненные доспехи. Тогда я сделаю тебе очень неплохую броню.', 'Командор Элигор Вестник Рассвета из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать ремень искупления, если вы принесете ему следующее: 1 испоганенный ремень, 8 обломков доспехов, 1 слиток арканита и 3 кристалла-источника.', 'Ремень послужит двум целям: 1) Защитит тебя в сражениях с Плетью и 2) Ты будешь выглядеть гораздо стройнее.', 'Пока ты не принесешь мне все материалы, я не смогу начать работу.', NULL, NULL, 'Испоганенный ремень', 'Обломок доспехов', 'Арканитовый слиток', 'Кристалл-источник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9050, 'Накулачники Искупления', 'Убивая лордов Наксрамаса, ты найдешь остатки доспехов наших павших героев. Принеси их мне. Заодно захвати обломки лат, поврежденных в бою, и материалы, способные вдохнуть новую жизнь в оскверненные доспехи. Тогда я сделаю тебе очень неплохую броню.', 'Командор Элигор Вестник Рассвета из часовни Последней Надежды, что в Восточных Чумных землях, готов сделать накулачники искупления, если вы принесете ему следующее: 1 испоганенные накулачники, 6 обломков доспехов, 1 слиток арканита и 2 обработанных грубых шкуры.', 'Очень выгодное занятие, делать эти запястья. Но не забывай, если постоянно мокнуть в них под дождем, они могут заржаветь!', 'Пока ты не принесешь мне все материалы, я не смогу начать работу.', NULL, NULL, 'Оскверненные накулачники', 'Обломок доспехов', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9051, 'Испытание яда', 'Яд, который ты $gпомог:помогла: мне создать, нужен мне для особых целей. Огромные дьявозавры, обитающие в кратере, мешают мне охотиться и даже угрожают моей жизни. Даже если бы у меня хватило сил, чтобы убить дьявозавра, это было бы бесполезно – на место убитого немедленно придет другой. $B$BВозьми эту отравленную колючку и загони ее глубоко в шкуру дьявозавра. Яд усмирит зверя, хоть я и не знаю, насколько быстро...', 'Уколите дьявозавра шипом дьявозавра. По выполнении задания вернитесь к землепроходцу Торве.', '', NULL, NULL, NULL, 'Уколите дьявозавра шипом.', 'Шип дьявозавра', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9052, 'Яд кровоцвета', 'Мне нужна твоя помощь в создании яда, с помощью которого я собираюсь усмирять огромных чудовищ, обитающих в кратере. Не бойся, яд не смертелен. Кроме того, острые глаза $C будут большим подспорьем при сборе ингредиентов. $B$BГрибы-кровошляпочники растут под побегами кровоцвета - их в кратере полным полно. Жала Гориши - это жала насекомых, которые водятся в районе Скользкого оврага в южной части кратера.', 'Соберите 8 кровошляпочников и 8 жал Гориши и вернитесь к Землепроходцу Торве в Кратер Ун\'Горо.', 'Наконец-то! $B$BТеперь я смешаю эти ингредиенты с почвой Ун\'Горо и сварю яд...', 'Тебе удалось собрать ингредиенты?', NULL, NULL, 'Жало Гориши', 'Кровошляпочник', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9053, 'Лучший ингредиент', 'Как я и опасался – яд слишком слаб для такого большого зверя. $B$BЧтобы создать более мощный яд, мне потребуются лучшие ингредиенты. Отправляйся на дно храма Атал\'Хаккар, раскрой секреты алтаря и заполучи от тамошнего стража гнилую лозу. Храм опасен, поэтому не ходи $gодин:одна:. $B$BВозвращайся ко мне, когда закончишь задание.', 'Возьмите гнилую лозу у стража на дне затонувшего храма и вернитесь к Землепроходцу Торве.', '', NULL, NULL, NULL, 'Гнилая лоза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9054, 'Мундир расхитителя гробниц', 'Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$B$BПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!', 'Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать мундир расхитителя гробниц, если вы принесете ему 1 испоганенный мундир, 25 обрывков кольчуги, 4 слитка арканита и 3 обработанных грубых шкуры.', 'Пусть тебя боятся, $N!', 'Ты все необходимое принесла?', NULL, NULL, 'Оскверненный мундир', 'Обрывки кольчуги', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9055, 'Набедренники расхитителя гробниц', 'Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$B$BПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!', 'Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать набедренники расхитителя гробниц, если вы принесете ему 1 испоганенные набедренники, 20 обрывков кольчуги, 3 слитка арканита и 5 обработанных грубых шкур.', 'Чем больше частей этой брони ты соберешь, тем сильнее изменишься. У тебя появится желание убивать. Может быть, даже жажда крови.$B$BСкажем так, я не готов взять на себя ответственность за то, что ты можешь натворить...', 'Ты все необходимое принес?', NULL, NULL, 'Оскверненные набедренники', 'Обрывки кольчуги', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9056, 'Головной убор расхитителя гробниц', 'Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$B$BПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!', 'Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать головной убор расхитителя гробниц, если вы принесете ему 1 испоганенный головной убор, 15 обрывков кольчуги, 4 слитка арканита и 2 кристалла-источника.', 'Тебя уже можно испугаться в темноте!', 'Ты все необходимое принес?', NULL, NULL, 'Испоганенный головной убор', 'Обрывки кольчуги', 'Арканитовый слиток', 'Кристалл-источник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9057, 'Наплеч расхитителя гробниц', 'Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$B$BПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!', 'Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать наплеч расхитителя гробниц, если вы принесете ему 1 испоганенный наплеч, 12 обрывков кольчуги, 2 слитка арканита и 3 обработанных грубых шкуры.', 'Я постарался сделать бармы побольше, позаметнее. Поверь мне, они тебе понравятся…', 'Ты все необходимое принес?', NULL, NULL, 'Испоганенный наплеч', 'Обрывки кольчуги', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9058, 'Сапоги расхитителя гробниц', 'Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$B$BПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!', 'Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать сапоги расхитителя гробниц, если вы принесете ему 1 испоганенные сапоги, 12 обрывков кольчуги, 1 слиток арканита и 3 кристалла-источника.', 'Сапоги готовы, $N! Носи их с удовольствием.', 'Ты все необходимое принес?', NULL, NULL, 'Испоганенные сапоги', 'Обрывки кольчуги', 'Арканитовый слиток', 'Кристалл-источник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9059, 'Боевые рукавицы Расхитителя гробниц', 'Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$B$BПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!', 'Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать боевые рукавицы расхитителя гробниц, если вы принесете ему 1 испоганенные боевые рукавицы, 8 обрывков кольчуги, 1 слиток арканита и 5 обработанных грубых шкур.', 'Да передастся тебе ярость и сила некрорахнида.', 'Ты все необходимое принес?', NULL, NULL, 'Оскверненные боевые рукавицы', 'Обрывки кольчуги', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9060, 'Ремень расхитителя гробниц', 'Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$B$BПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!', 'Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов сделать ремень расхитителя гробниц, если вы принесете ему 1 испоганенный ремень, 8 обрывков кольчуги, 1 слиток арканита и 3 кристалла-источника.', 'Такой ремень достоен королей! А получишь ее ты, $N.', 'Ты все необходимое принес?', NULL, NULL, 'Испоганенный ремень', 'Обрывки кольчуги', 'Арканитовый слиток', 'Кристалл-источник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9061, 'Накулачники расхитителя гробниц', 'Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$B$BПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!', 'Охотник Леопольд из часовни Последней Надежды в Восточных Чумных землях готов создать накулачники расхитителя гробниц, если вы принесете ему 1 испоганенные накулачники, 6 обрывков кольчуги, 1 слиток арканита и 2 обработанных грубых шкуры.', 'Накулачники готовы. Наслаждайся!', 'Ты все необходимое принес?', NULL, NULL, 'Оскверненные накулачники', 'Обрывки кольчуги', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9062, 'Промокшие страницы', 'Да уж, завидев кого-то, с кем им не справиться, проклятые Презренные разбегаются быстрее зайцев! Ладно, сейчас не о том речь. Нужно отыскать гримуар стихий моего наставника!$B$BЯ точно видел, как один из этих трусов швырнул его в реку, но вот где он теперь? Может, ты поможешь его отыскать? Я в долгу не останусь!', 'Отыщите в реке под мостом гримуар стихий Антеола по просьбе ученика Меледора.', 'Гримуар промок насквозь! Что же делать? Инструктор Антеол будет очень зол!$B$BСлушай, вот тебе деньги! И у меня есть идея.', 'Что, не нашелся? Ну, ищи дальше! Это очень важная книга, $C!', NULL, NULL, 'Гримуар стихий Антеола', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9063, 'Землепроходец Торва', 'Охотнику по имени Землепроходец Торва понадобилась помощь друида. Он сказал, что лишь у нас есть нужные навыки и должное уважение к природе.$B$BОт Кратера Ун\'Горо к пустыне Танарис ведет дорога. Торва стоит у самого входа в кратер.', 'Поговорите с Землепроходцем Торвой в Кратере Ун\'Горо.', 'Ради встречи со мной тебе пришлось проделать долгий путь, $С. Ты как раз вовремя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9064, 'Взять вину на себя', 'Ох, то-то Антеол разъярится, как узнает, что его книжка испорчена! Слушай, есть предложение. Не бойся, ты внакладе не останешься.$B$BОтнеси ему эту книжку. О том, что произошло, ни слова. А если спросит, как это вышло, просто скажи, что ты $gуронил:уронила: книжку в лужу. Тебе он не наставник, так что тебе за это ничего не будет.$B$BАнтеол читает свои лекции у пруда Тихого Шелеста, к юго-востоку от Луносвета. Ты ведь это сделаешь, ладно? Я в долгу не останусь!', 'Принесите гримуар стихий Антеола инструктору Антеолу у пруда Тихого Шелеста в лесах Вечной Песни.', 'Так ты говоришь, что эти два остолопа сулили тебе взятку за то, чтобы обмануть меня? Очень хорошо, что ты ко мне пришел, $N!', 'С какой целью ты прерываешь мою лекцию, $C?', NULL, NULL, 'Гримуар стихий Антеола (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9065, 'Задание Чоу (123)аа', 'Эй, ты! Убей пару кобольдов-вредителей.', 'Убедитесь, что вы уничтожили эту башню!', '', NULL, NULL, NULL, 'PattyMacks Dummy убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9066, 'Суровый урок', 'Надеюсь, что сегодня ты, $N, получишь ценный урок. Никогда не поручай кому-то другому лгать вместо тебя.$B$BА теперь возвращайся к моим бестолковым студентам и вразуми их с помощью этого жезла. Моя магия подсказывает мне, что ты найдешь их на дороге к западу отсюда, по ту сторону Тропы Мертвых.$B$BКогда выполнишь это, возвращайся ко мне. Я дам тебе небольшую награду за труды.', 'Накажите карающим жезлом Антеола двух его студентов, ученика Ралена и ученика Меледора. Верните жезл Антеолу у пруда Тихого Шелеста в лесах Вечной Песни.', 'Отличная работа, $N! Не волнуйся, они не останутся в этом облике навечно. Однако из числа моих учеников они исключены до тех пор, пока не докажут, что достойны у меня учиться.', 'Ну что, $N, выполнил ли ты то, о чем я просил?', NULL, NULL, 'Ученик Меледор наказан', 'Ученик Рален наказан', 'Карающий жезл Антеола (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9067, 'Бесконечный праздник', 'Обожаю вечеринки! Кель\'Талас будто создан для них.$B$BНо сейчас у меня возникла проблема, и мне нужна твоя помощь. Собери побольше припасов к праздничному столу.$B$BПринеси мне от винодела Благословение Солнца из таверны \"Луносвет\" бутылку его лучшего вина. У Залены Юной Зари в обители Странников возьми побольше восхитительной закуски из прыголапа. Еще, кстати, забери заказанные мной фейерверки у Халиса Рассветного Странника в деревне Легкий Ветерок!$B$BПоторопись!', 'Добудьте бутылку \"Благословения Солнца Гранд Резерв\", закуску из прыголапа и связку фейерверков и принесите все это лорду Салтерилу на виллу Салтерила, что в лесах Вечной Песни.', 'О, а ты, оказывается, весьма энергичный юноша!$B$BДа, это то, что надо. Ты, несомненно, заслуживаешь награды. И, наверное, что-нибудь сверх обещанной платы...$B$BДа-да, совсем забыл: вот тебе приглашение на вечеринку! Только в следующий раз, как будешь у меня, $C, прошу, переоденься во что-нибудь... более праздничное.', 'Это тебя я только что послал за припасами для праздника? Или это был не ты? Ну, в конце концов, не могу же я всех в лицо помнить! У меня ведь столько... интересных знакомых!$B$BТак чего тебе надо?', NULL, NULL, '\"Благословение Солнца Гранд Резерв\"', 'Закуска из прыголапа', 'Связка фейерверков', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9068, 'Мундир Землекрушителя', 'Прошу тебя, окажи мне честь и верни броню тех, кто пал, защищая эти земли.$B$BЗлые силы несомненно испоганили эти доспехи и используют их для собственных гнусных целей, однако их можно укрепить при помощи обрывков кольчуг и вновь пойти в них на войну.$B$BПринеси мне остатки брони павших и материалы для их очищения, и получишь взамен доспехи Землекрушителя.$B$BСтупай, поищи в Наксрамасе.', 'Римблат Землекрушитель из часовни Последней Надежды в Восточных Чумных землях готов создать мундир землекрушителя, если вы принесете ему 1 испоганенный мундир, 25 обрывков кольчуги, 4 слитка арканита и 3 обработанных грубых шкуры.', '', NULL, NULL, NULL, 'Оскверненный мундир', 'Обрывки кольчуги', 'Арканитовый слиток', 'Обработанная грубая шкура');
