INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9075, 'Накулачники Землекрушителя', 'Прошу тебя, окажи мне честь и верни броню тех, кто пал, защищая эти земли.$B$BЗлые силы несомненно испоганили эти доспехи и используют их для собственных гнусных целей, однако их можно укрепить при помощи обрывков кольчуг и вновь пойти в них на войну.$B$BПринеси мне остатки брони павших и материалы для их очищения, и получишь взамен доспехи Землекрушителя.$B$BСтупай, поищи в Наксрамасе.', 'Римблат Землекрушитель из часовни Последней Надежды в Восточных Чумных землях готов создать накулачники землекрушителя, если вы принесете ему следующее: 1 испоганенные накулачники, 6 обрывков кольчуги, 1 слиток арканита и 2 обработанных грубых шкуры.', '', NULL, NULL, NULL, 'Оскверненные накулачники', 'Обрывки кольчуги', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9076, 'Главарь Презренных', 'Презренные настолько упиваются своей нечистой магией, что, наверное, даже не осознали, что нам удалось вернуть себе большую часть оружия. Однако мы не можем рассчитывать, что они будут долго пребывать в растерянности. Сейчас самое время избавиться от их предводителя, Альдарона. Его видели на верхнем этаже здания у причала. Принеси мне его голову, и я вознагражу тебя по заслугам.', 'Принесите голову Альдарона Велендрису Белому Рассвету у причала Солнечного Паруса в лесах Вечной Песни.', 'Ага, тебе все-таки удалось его одолеть! Ну, конечно, вряд ли бы ты его поймал, если бы мои воины его не загнали...$B$BДа шучу я, шучу! Спасибо, $C. Ты еще завоюешь себе славу.', 'Ну так что, удалось тебе добыть его голову или нет? У меня нет лишнего времени, $N!', NULL, NULL, 'Голова Альдарона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9077, 'Кираса костяной косы', 'Если ты хочешь броню костяной косы, принеси мне все материалы.$B$BСтупай в Наксрамас, огромный парящий город смерти, и набери там испоганенных доспехов и обрывков кожи. Принеси их мне вместе с остальными материалами, и, считай, Костяная коса – твоя. Ах да, не забудь и мне отстегнуть за работу... Кости я тебе обеспечу.', 'Роган Убийца из часовни Последней Надежды в Восточных Чумных землях готов создать кирасу костяной косы, если вы принесете ему 1 испоганенную кирасу, 25 обрывков кожи, 2 слитка арканита и 6 обработанных грубых шкур.', '', NULL, NULL, NULL, 'Испоганенная кираса', 'Обрывок кожи', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9078, 'Ножные латы костяной косы', 'Если ты хочешь броню костяной косы, принеси мне все материалы.$B$BСтупай в Наксрамас, огромный парящий город смерти, и набери там испоганенных доспехов и обрывков кожи. Принеси их мне вместе с остальными материалами, и, считай, Костяная коса – твоя. Ах да, не забудь и мне отстегнуть за работу... Кости я тебе обеспечу.', 'Роган Убийца из часовни Последней Надежды в Восточных Чумных землях готов создать ножные латы костяной косы, если вы принесете ему 1 испоганенные ножные латы, 20 обрывков кожи, 1 слиток арканита, 8 обработанных грубых шкур и 100 золотых.', 'Осторожей носи мои доспехи. Не ровен час, порежешься...', '*Роган смеется.*$B$BДо меня только сейчас дошло, в чем тут штука!', NULL, NULL, 'Испоганенные ножные латы', 'Обрывок кожи', 'Арканитовый слиток', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9079, 'Полный шлем костяной косы', 'Если ты хочешь броню костяной косы, принеси мне все материалы.$B$BСтупай в Наксрамас, огромный парящий город смерти, и набери там испоганенных доспехов и обрывков кожи. Принеси их мне вместе с остальными материалами, и, считай, Костяная коса – твоя. Ах да, не забудь и мне отстегнуть за работу... Кости я тебе обеспечу.', 'Роган Убийца из Часовни Последней Надежды в Восточных Чумных землях готов создать шлем костяной косы, если вы принесете ему следующее: 1 испоганенный шлем, 15 обрывков кожи, 8 обработанных грубых шкур, 1 кристалл-источник и 75 золотых.', '', NULL, NULL, NULL, 'Испоганенный полный шлем', 'Обрывок кожи', 'Обработанная грубая шкура', 'Кристалл-источник');
