INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9085, 'Тени Рока', 'После разрушения защиты кругов призыва Плети, которые появляются в тех местах, где происходит нападение, тебе придется сразиться с послушниками, которые охраняют эти круги.$B$BЧестно говоря, это не живые существа, а тени, одни из самых устрашающих созданий Короля-лича. Их можно обнаружить с помощью некротических рун, которые они носят при себе, а затем уничтожить посредством магии или силой оружия.', 'Идите к кругу призыва и убейте Тень Рока, затем возвращайтесь к командиру Томасу Элерану в Часовню Последней Надежды в Восточные Чумные земли.', 'Превосходная работа, $N. Теперь, когда тени уничтожены, у нас остается надежда одолеть Короля-лича.', 'Повезло ли тебе, $N?', NULL, NULL, 'Тень Рока убито', NULL, NULL, NULL);
