INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9095, 'Одеяние ледяного огня', 'У меня был доступ ко многим личным вещам Медива. Меня больше всего интересовали манускрипты. Хотя в основном книги были, прямо скажем, полной чепухой, но и в этой мусорной кучи были свои изумруды. В одном из манускриптов описывалось создание брони, достойной верховного мага, брони ледяного огня.$B$B*Анджела указывает на собственную голову.*$B$BВсе знания теперь хранятся там, и я с радостью поделюсь ими с тобой, если ты снабдишь меня необходимыми материалами.', 'Верховный маг Анджела Досантос из часовни Последней Надежды в Восточных Чумных землях готова создать одеяние ледяного пламени, если вы принесете ей 1 испоганенное одеяние, 25 обрывков ткани, 4 куска луноткани и 2 кристалла-источника.', '', NULL, NULL, NULL, 'Оскверненное одеяние', 'Обрывок ткани', 'Луноткань', 'Кристалл-источник');
