INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9107, 'Сандалии Проклятого Сердца', 'Не буду тебе лгать, $gслизняк:тля:. Тьма облачения Проклятого Сердца может поглотить нас обоих, потому я и назначил такую высокую цену. Если уж умирать, то по крайней мере, на груде золота.$B$BМне наплевать, как сдохнешь ты, главное делай, как я скажу. Принесешь все, что велено – оба нагреем руки. Ну, или умрем; впрочем, я начинаю повторяться...', 'Матеус Заклинатель Гнева из часовни Последней Надежды готов создать сандалии проклятого сердца, если вы принесете ему 1 испоганенные сандалии, 12 обрывков ткани, 2 куска луноткани и 3 обработанных грубых шкуры.', 'Видишь? Осознаешь, какие силы тут задействованы? Очищение... Глупцы…$B$B*Матеус неодобрительно качает головой.*$B$BБери то, за чем пришел и проваливай.', 'Ха, возвращение блудного грызуна! Ну и как, несешь, что велено?', NULL, NULL, 'Оскверненные сандалии', 'Обрывок ткани', 'Луноткань', 'Обработанная грубая шкура');
