INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9118, 'Наручники веры', '*Отец Монтой делает какие-то странные пассы.*$B$BБлагослови тебя Свет, дитя мое, удалось ли тебе отыскать одежды павших? Бедные воины, лишившиеся жизни на поле битвы – у них отняли все, даже достоинство.$B$BПринеси мне оскверненные доспехи павших и все реагенты для их очищения, и ты познаешь, что такое истинная вера.', 'Отец Иниго Монтой из Часовни Последней Надежды готов создать наручники Веры, если вы принесете ему следующее: 1 испоганенные наручники, 6 обрывков ткани, поврежденных в бою, 1 кристалл-источник и 1 чародейский кристалл.', '', NULL, NULL, NULL, 'Испоганенные наручники', 'Обрывок ткани', 'Чародейный кристалл', 'Кристалл-источник');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9119, 'Авария в Западном святилище', 'Раз уж ты здесь, $N, я попрошу тебя об услуге. Сюда прибегал ученик хранительницы энергии Велании и просил помощи. Судя по всему, в Западном святилище произошла авария. А я был несколько занят нашим... весьма любезным... гостем, дворфом. Узнай, не сможешь ли ты ей помочь. Западное святилище - к юго-западу отсюда.', 'Поговорите с хранительницей энергии Веланией в Западном святилище в лесах Вечной Песни.', 'Оглядись вокруг. Нельзя сказать, что все в порядке!$B$BВ Западном святилище произошла серьезная авария. Нужно сделать все, чтобы ситуация не ухудшилась!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9120, 'Падение Кел\'Тузада', 'От повелителя Наксрамаса остался лишь этот талисман. Голос рассудка подсказывает, что следует уничтожить его, дабы Король Мертвых не смог более возродиться. К счастью, вы не привыкли слушаться внутреннего голоса.$B$BКое-кто из часовни Последней Надежды обещал недурно заплатить за этот талисман. Кому есть дело до возрождения Кел\'Тузада?', 'Отнесите талисман Кел\'Тузада в Часовню Последней Надежды в Восточных Чумных землях.', 'Я и помыслить не мог, что доживу до такого…$B$B*У отца Монтоя трясутся руки от возмущения.*$B$BДа, да, ты получишь награду. Да еще какую. А ну давай эту штуку сюда!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9121, 'Цитадель ужаса – Наксрамас', 'В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$B$BМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку тебе не хватает преданности делу Серебряного Рассвета, за чары придется немало заплатить. Ты можешь отказаться от задания и вернуться ко мне, как только тебя начнут почитать или превозносить. Тогда я сделаю тебе скидку.', 'Верховный маг Анджела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова наложить на вас заклинание чародейского покрова за 5 чародейских кристаллов, 2 кристалла-источника, 1 сферу Праведности и 60 золотых. Вы должны заслужить уважительное отношение Серебряного Рассвета.', '', NULL, NULL, NULL, 'Чародейный кристалл', 'Кристалл-источник', 'Сфера Праведности', 'Требуется денег: 60');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9122, 'Цитадель ужаса – Наксрамас', 'В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$B$BМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку ты весьма $gпредан:предана: делу Серебряного Рассвета, часть издержек мы возьмем на себя.', 'Верховный маг Анджела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова наложить на вас заклинание чародейского покрова за 2 чародейских кристалла, 1 кристалл-источник и 30 золотых. Вы должны заслужить почтительное отношение Серебряного Рассвета.', 'Ты почувствуешь легкий звон в ушах, $N. Это будет означать, что наш план сработал. В конечном итоге ты сможешь войти в Наксрамас через портал в Проклятых землях.', 'Никто их вошедших в Наксрамас, не вернулся назад.', NULL, NULL, 'Чародейный кристалл', 'Кристалл-источник', 'Требуется денег: 30', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9123, 'Цитадель ужаса – Наксрамас', 'В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$B$BМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку твоя преданность делу Серебряного Рассвета не подлежит сомнению, мы возьмем на себя все издержки.', 'Верховный маг Анджела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова бесплатно наложить на вас заклинание чародейского покрова. Сначала добейтесь того, чтобы вас превозносили в Серебряном Рассвете.', 'Ты почувствуешь легкий звон в ушах, $N. Это будет означать, что наш план сработал. В конечном итоге ты сможешь войти в Наксрамас через портал в Проклятых землях.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9124, 'Доспехи расхитителя гробниц на дороге не валяются...', 'Хочешь получить такую побрякушку?$B$B*Леопольд помахивает значком Алого ордена.*$B$BМне пригодилась бы твоя помощь в одном деле, $N. Я создаю броню расхитителей гробниц для глупцов, желающих сунуть нос в Наксрамас. У меня нет недостатка в материалах, за исключением конечностей и панцирей некрорахнидов. Принеси мне их, и получишь значок. Имей в виду, интенданты готовы отдать за эти побрякушки много интересного.', 'Принесите 30 конечностей и панцирей некрорахнидов Охотнику Леопольду в Часовню Последней Надежды в Восточные Чумные земли.', 'Отлично, $N. Имей в виду, я всегда готов купить еще.', 'Как охота?', NULL, NULL, 'Конечности и панцири некрорахнидов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9125, 'Конечности и панцири некрорахнидов', '', 'Хорошая работа, $N. Если сможешь принести мне еще конечностей и панцирей арахнидов-могильщиков, я всегда готов заплатить – еще одним знаком отличия.', 'Прекрасно, $N! Они мне очень пригодятся!', NULL, NULL, NULL, 'Конечности и панцири некрорахнидов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9126, 'Копи костяной косы', 'Для изготовления доспехов костяной косы, изобретенных доном Хулио, требуются обломки костей – чем больше, тем лучше. Хотя безумцы, регулярно отправляющиеся в Наксрамас, приносят мне довольно много, обломки костей Плети для меня никогда не лишние.$B$BНе желаешь ли помочь мне? Так ты изничтожишь подлых тварей плети и снабдишь меня материалом для доспехов.', 'Принесите 30 обломков костей Рогану Убийце в Часовню Последней Надежды в Восточные Чумные земли.', 'А ты быстр, $N! Быстр, как лисица...', 'Я могу указать тебе путь к зараженным местам, $C.', NULL, NULL, 'Обломки костей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9127, 'Обломки костей', '', '', 'Скоро, скоро я осуществлю свою мечту – устроюсь стриптизером в лучший кабак Прибамбасска на полную ставку! Продолжай работать, $N.', NULL, NULL, NULL, 'Обломки костей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9128, 'Уравнение стихий', 'Приветствую тебя, $gстранник:странница:! Не ищешь ли ты работу? Плачу знаками отличия – их можно обменять на разные магические предметы у интендантов.$B$BСлушай, что мне нужно: принеси мне как можно больше средоточий стихий – сколько сможешь унести. Чем больше, тем лучше!$B$BСредоточия стихий можно найти у элементалей всех форм и размеров.', 'Принесите 30 средоточий стихий верховному магу Анджеле Досантос в Часовню Последней Надежды в Восточные Чумные земли.', 'Отлично, $N! Вот твой знак, как я и обещала. Имей в виду, я всегда готова купить еще.', 'Я могу подсказать тебе, где искать, $N.', NULL, NULL, 'Средоточие стихий', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9129, 'Средоточие стихий', '', '', 'Отличная работа, $N!', NULL, NULL, NULL, 'Средоточие стихий', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9130, 'Товары из Луносвета', 'Привет новобранцам! У нас тут плохо со снабжением, но эльфы крови обещали нам материальную помощь. Это и будет твоим первым заданием.$B$BБери накладную и неси повелителю небес Солнечному Крылу. Он снабдит тебя дальнейшими инструкциями, как добраться до Луносвета.', 'Доставьте накладную интенданта Лимель повелителю небес Солнечному Крылу в Транквиллион.', 'Значит, Лимель просит тебя отправиться в Луносвет и доставить ее товар? Долетим во мгновение ока... за скро$Nю плату, естественно.', 'Да, что у тебя?', NULL, NULL, 'Накладная интенданта Лаймель (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9131, 'Броня неустрашимости', 'Ты когда-нибудь $gвидел:видела: доспехи неустрашимости, $C? Конечно нет, ты же еще совсем салага. Так вот, послушай знатока – он великолепен!$B$BТы, наверное, недоумеваешь, какое это к тебе может иметь отношение? Вот что, недотепа, мне нужны пластины черного железа – как можно больше.$B$BС их помощью я скрепляю части доспехов неустрашимости для наших славных воинов. Так что я хорошо заплачу.', 'Принесите 30 пластин черного железа Корфаксу в Часовню Последней Надежды в Восточные Чумные земли.', 'Маловато, но пока сойдет. Найдешь еще – приноси.', '*Корфакс злобно смотрит на вас*$B$BНу что тебе еще надо? Указать дорогу?', NULL, NULL, 'Лом черного железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9132, 'Лом черного железа', '', '', 'Что, и это все? Я же ясно сказал – мне нужно ЕЩЕ!', NULL, NULL, NULL, 'Лом черного железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9133, 'Полет в Луносвет', '$C, за весьма скро$Nю плату я могу быстро доставить тебя по воздуху на одном из этих великолепных животных! Смею тебя заверить, это куда безопаснее, чем идти пешком!$B$BДобравшись до Луносвета, найди Сатрена Лазурного Рассвета на базаре.$B$BКогда будешь $gготов:готова: покорить небеса, обращайся.', 'Оплатите полет в Луносвет и доставьте накладную от интенданта Лимель Сатрену Лазурному Рассвету в Луносвет.', 'Это еще что? И без того гнилые мозги Лимель окончательно у нее из ушей вытекли, что ли? Ей нужен весь этот товар?!$B$BУ вас есть помощник? Сами вы вряд ли справитесь.', 'Список довольно длинный. Дай-ка посмотреть.', NULL, NULL, 'Накладная интенданта Лаймель (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9134, 'Повелительница небес Полудымка', 'Непохоже, чтобы у тебя была повозка или вьючное животное, так что лучше дам тебе тот груз, который ты сможешь унести. Если ты уже $gговорил:говорила: с повелителем небес Солнечным Крылом в Транквиллионе, то тебе надо будет доставить вот этот ящичек интенданту Лимель как можно скорее, вернувшись назад по воздуху.$B$BДоставь этот товар на экспертизу повелительнице небес Полудымке к вратам Пастыря на входе в Луносвет.', 'Доставьте товар интенданта Лимель повелительнице небес Полудымке к вратам Пастыря, что ведут в Луносвет.', 'Возвращаешься в Транквиллион, в Призрачные земли? Доставлю с ветерком!', 'О, с виду – увесистый ящик! Ты хочешь погрузить его на одну из моих крылатых красоток?', NULL, NULL, 'Товары интенданта Лаймель (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9135, 'Возвращение к интенданту Лимель', 'Значит, все сходится. Сдается, эти Отрекшиеся готовы драться за нас до конца, и мы в долгу перед ними, хотя на лицо они ужасные и гнилые внутри.$B$BЛадно, к делу. Ты уже $gговорил:говорила: с повелителем небес Солнечным Крылом в Транквиллионе? Если так, то за небольшую плату ты легко и быстро вернешься назад.$B$BДай знать, как будешь $gготов:готова:.', 'Оплатите обратный полет в Транквиллион в Призрачных землях и доставьте товары интенданта Лимель интенданту Лимель в Транквиллион в Призрачных землях.', 'Ну ладно, раз уж он пообещал, что остальное прибудет отдельным грузом, то положусь на его слово. Хотя работаем вместе мы и недолго, но пока он всегда доставлял товар в срок.$B$BСпасибо, Котячий, ты делаешь честь син\'дорай! И вот тебе монетка за труды... все равно она только без толку карман тянет.', 'Чернокнижница, ты так скоро вернулась? Это те товары, за которыми я тебя посылала? Не похоже, чтобы тут было все, что я запрашивала!', NULL, NULL, 'Товары интенданта Лаймель (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9136, 'Дикая флора', 'Я изготавливаю особые доспехи для наших бравых солдат, входящих в Наксрамас – они называются доспехами сновидца. Обычно у меня нет недостатка в материалах, за исключением диких ростков.$B$BВозможно, ты подумаешь, что эта работа не серьезна, однако без диких ростков создание таких доспехов невозможно.$B$BИ я готова платить за эту работу знаками Рассвета или Марша!', 'Принесите 30 диких ростков Райн в Часовню Последней Надежды в Восточные Чумные земли.', 'Благодарю тебя, $N.$B$B*Райн кланяется*$B$BПомни, что ростки всегда нужны мне.', 'Я прекрасно разбираюсь в флоре нашего мира. Тебе нужен совет?', NULL, NULL, 'Дикий росток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9137, 'Дикие ростки', '', '', 'Спасибо, $N! Твоя помощь в борьбе с Плетью неоценима.', NULL, NULL, NULL, 'Дикий росток', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9138, 'Деревня Солнечной Короны', 'Мы тут в окружении, $C. Все окрестные селения захвачены Плетью!$B$BСпеши на северо-восток к деревне Солнечной Короны и сокруши нерубов – тварей Плети! Их трудно с кем-либо спутать – они похожи на пауков.$B$BНе трать времени... Кель\'Талас должен снова стать нашим!', 'Убейте 10 нерубов-стражей и возвращайтесь к чародею Вандрилу в Транкивиллион, что в Призрачных землях.', 'Невероятно! Но сколько же еще нужно сделать до того, как Плеть окончательно и бесповоротно будет изгнана из Кель\'Таласа!$B$BВот, прими эту плату. Это немного, но ты ее заслужил.', NULL, NULL, NULL, 'Неруб-страж убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9139, 'Деревня Золотистой Дымки', 'Кое в чем мы преуспели, но есть еще два поселения, которые надо отбить!$B$BСледующая наша цель – деревня Золотистой Дымки. Она находится к северо-западу отсюда, ее захватили призраки высших эльфов, что прежде обитали здесь. Я понимаю, что это ужасно, но их тактика почти та же, что и у Плети.$B$BИди и перебей этих призраков и духов, $C. Чтобы добраться туда, иди по западной дороге от Транквиллиона.', 'Уничтожьте 6 кель\'дорайских привидений и 4 кель\'дорайских призрака в деревне Золотистой Дымки, затем возвращайтесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.', 'Твой успех в деревне Золотистой Дымки еще на шаг приблизил нас к отвоеванию наших земель. Но не обольщайся, $C – битва далеко не закончена.$B$BВот, бери, это более чем заслуженная награда. Эта вещь может тебе пригодиться, когда ты пойдешь наводить порядок в деревне Ветрокрылых.', NULL, NULL, NULL, 'Кель\'дорайское привидение убито', 'Кель\'дорайский призрак убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9140, 'Деревня Ветрокрылых', '$N, тебе пришло время вступить в главную битву за поселения Призрачных земель. Деревня Ветрокрылых к юго-западу отсюда захвачена крупным и сильным ударным отрядом - тенями и горгульями. Ты выступишь на острие нашей атаки и ослабишь противника насколько возможно!$B$BМагистры соседнего святилища Солнца на сей раз сделали специальный запрос: они хотят, чтобы останки этих тварей Плети были доставлены им для изучения, дабы найти метод борьбы с ними.$B$BДоброй охоты!', 'Соберите 6 порций иллюзорного вещества и 4 обломка горгульи. Возвращайтесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.', 'Дело сделано, $N. Ты вырвал из когтей Плети целых три поселения! Теперь мы сможем собрать больше сил для противостояния тварям Плети на Тропе Мертвых и к югу от Смертхольма.$B$BВот – выбирай что хочешь. Надеюсь, ты никуда не уезжаешь? Ты нам тут еще очень пригодишься!', 'Ну, что, $C, деревня Ветрокрылых освобождена? Проклятые магистры из святилища Солнца уже просто плешь мне проели – не терпится им ручонками своими пощупать останки тех тварей Плети, что я просил тебя собрать.$B$BНо ты не переживай. Соберись и продолжай выполнять задание. А с магистрами я сам разберусь.', NULL, NULL, 'Иллюзорное вещество', 'Обломок окаменевшей горгульи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9141, 'Не все так просто', 'Хочешь получить задание? Не все так просто. Неужели ты думаешь, что я буду раздавать задания всякому явившемуся пред мои очи оборванцу, когда меня осаждают толпы желающих работать на фронте!$B$BХочешь получить задание – докажи, что ты его $gдостоин:достойна:! Принеси мне знак доблести, тогда и поговорим.$B$BИмей в виду, единственный способ поступить к нам на работу – обагрить руки кровью!', 'Принесите знак доблести Серебряного Рассвета командиру Метцу в Часовню Последней Надежды в Восточные Чумные земли.', 'Хорошо, слушай порядок действий: за каждый предъявленный знак доблести будешь получать задание. Выполнять строго по инструкции и отчитываться караванщику Камнетесу. Вопросы есть? Прекрасно, теперь марш отсюда.', '*Командир-посланник Метц жует сигару*$B$BВ чем дело? У меня нет времени!', NULL, NULL, 'Знак доблести Серебряного Рассвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9142, 'Задание мастера', '', 'Ты знаешь правила парень. Получишь задание, только когда предъявишь знак доблести.', 'Ну, сам напросился. Приказы не обсуждаются.', NULL, NULL, NULL, 'Знак доблести Серебряного Рассвета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9143, 'Неприятности в Зеб\'Соре', 'Лейтенант бросил нас в атаку на троллей, не разведав обстановку. Из-за его тупости нас чуть под корень не вырезали! Слышишь меня, Томатрен? Ты идиот!$B$BПоможешь нам, $C? Этим троллям надо как следует всыпать! Мне придется остаться здесь и присматривать за лейтенантом – у него, похоже, совсем крыша поехала.$B$BИди прямо на восток, на другую сторону озера, в Зеб\'Сору. Я жажду крови! Принеси мне уши троллей, я из них ожерелье сделаю!', 'Добудьте 6 ушей троллей из Зеб\'Соры и принесите их следопыту Валанне в Призрачные земли.', 'Спасибо тебе за помощь, $C! Спасибо. Теперь хоть можно сказать, что наш поход и наши потери не были напрасны.', 'Ну что, добыл уши троллей?$B$BЕсли бы к нам хотя бы изредка посылали помощь из Транквиллиона, у нас не было бы таких проблем. Хорошо, хоть ты оказался под рукой.', NULL, NULL, 'Ухо тролля из Зеб\'Соры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9144, 'Пропавший в Призрачных землях', 'Несколько дней назад моего племянника послали в Призрачные земли. Он ничего не говорил о своем задании, упомянул только, что оно секретное.$B$BОн до сих пор не вернулся. $N, я опасаюсь худшего! Возможно, черствым магистрам Луносвета и нет дела до пропавшего гонца, но для меня он как сын! Прошу тебя, $N, найди его, пожалуйста...', 'Идите по дороге, ведущей из деревни Легкий Ветерок на юг, и найдите курьера Рассветного Странника.', 'Пожалуйста, помоги... Я... мне нужно... в Транквиллион... Я должен... выполнить задание...$B$B<Эльф крови снова впадает в забытье, его глаза стекленеют.:', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9145, 'Спасти следопыта Валанну', '$C, я не могу сидеть сложа руки и ждать аудиенции у верховного палача или госпожи Златилен! Дело не терпит отлагательств!$B$BМы бились с троллями из племени Призрачной Сосны из Зеб\'Соры, что на северо-восточном берегу озера Элрендар. Но лейтенант неудачно провел атаку, и мы потеряли многих Странников. А потом он просто спятил! Следопыт Валанна послала меня сюда, а следопыта Салиссу – в анклав Странников за помощью.$B$BПрошу тебя, найди их, $C. Валанна тяжело ранена, а от лейтенанта толку никакого.', 'Найдите следопыта Валанну и лейтенанта Томатрена на берегу озера Эрлендар в Призрачных землях близ деревни Солнечной Короны.', 'Хорошо, что Летвалин жив и здоров. И хорошо, что ему хватило ума попросить у тебя помощи, вместо того чтобы сидеть и ждать.$B$BНадеюсь, следопыт Салисса добралась до анклава Странников.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9146, 'Донесение капитану Гелиосу', 'Я попрошу тебя еще об одной, последней услуге, $C. На случай, если следопыт Салисса не доберется до Анклава Странников на южной оконечности озера, ступай туда и приведи подмогу.$B$BСвяжись с капитаном Гелиосом и скажи ему, что здесь случилось. Он наверняка пришлет подмогу, как только сможет.', 'Поговорите с капитаном Гелиосом в Анклаве Странников на южном берегу озера Элрендар в Призрачных землях.', 'Воистину злые вести – я переоценил командирские способности Томатрена. Я тотчас отправлю отряд, чтобы они доставили его и Валанну сюда в целости и сохранности.$B$BУвы, мы так ничего и не знаем о следопыте Салиссе, так что я опасаюсь худшего.$B$BТы сегодня оказал огро$Nю услугу Странникам, $C. Прошу – прими этот маленький дар в знак нашей благодарности.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9147, 'Умирающий курьер', 'Ну, что без дела стоишь? Не видишь – мальцу нужна срочная помощь! Похоже, его тело пожирает чума. Еще немного – и даже такая мастерица-аптекарша, как я, уже ничем ему не поможет.$B$BЖивотные к югу от реки несут заразу в своей крови. Ступай-ка через мост и истреби больных животных. Принеси мне побольше образцов зараженной крови, и я сумею выделить сыворотку, способную спасти этого эльфа. Торопись!', 'Аптекарь Тедра из лесов Вечной Песни просит вас принести ей 4 образца зараженной крови животных из Призрачных земель.', 'Вовремя, $N! Я уж собралась было копать могилку нашему приятелю.$B$BПохоже, мое зелье действует - мальчик-то приходит в себя.$B$BЭй, похоже, он хочет что-то тебе сказать! Почему бы тебе не поговорить с ним?', 'Ну? Ты принес то, что я просила? Поспеши, иначе этот прекрасный юный эльф крови умрет!', NULL, NULL, 'Образец зараженной крови', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9148, 'Письмо в Транкивиллион', 'Нет сил... идти... я должен доставить письмо... от лорда-регента Терона... ужасное предостережение. Тебе придется доставить его вместо меня.$B$BОтнеси его чародею Вандрилу в Транквиллион. Этот город находится дальше к югу по этой дороге. Отправляйся туда... найди Вандрила...', 'Отнесите письмо из Луносвета чародею Вандрилу в Транквиллион, что в Призрачных землях.', 'Наконец-то! Мы ждали ответа от лорда-регента несколько недель! Посмотрим, что он пишет...$B$B<Вандрил начинает читать письмо.>$B$BЧто? Тьма? Он ощущает присутствие тьмы в Призрачных землях?! Будто я сам не вижу!$B$BИ этого ответа мы так долго дожидались?', 'Письмо при тебе?', NULL, NULL, 'Письмо из Луносвета (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9149, 'Чумной берег', 'Чтобы найти лекарство от этой болезни, нам нужно понять, как она влияет на различные существа - от самых сложных форм жизни до простейших. $B$BЯ прибыл сюда для исследования мурлоков, поскольку они, как и мы, сохраняют свободу воли даже после смерти. Что делает этих ничтожных ублюдков такими особенными? Мне надо это выяснить, $N!$B$BОтправляйся на северо-запад и принеси мне их хребты, чтобы я мог изучить накопление заразы в их костном мозге. Кто знает, что за секрет хранят их жалкие кости?', 'Принесите 6 хребтов чумных мурлоков аптекарю Рензитену в Транквиллион, что в Призрачных землях.', 'Блестяще! Эти хребты как нельзя лучше годятся для моих исследований! Когда я найду лекарство от чумы и слух обо мне пойдет по городам и весям, тогда уж я не позабуду упомянуть о тебе!$B$BА пока вот тебе награда. Они могут тебе понадобиться, если решишь вернуться на побережье.', 'Ты принес мне те образцы, что я просил, $N?', NULL, NULL, 'Хребет чумного мурлока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9150, 'Спасение прошлого', 'Прямо не верится! На юго-востоке от нас существует и действует настоящее магическое святилище – святилище Солнца! Все самые знаменитые магистры собрались туда ради этого!$B$BИ, конечно, все позабыли о святилище Луны. От него мало что осталось, и его сила породила странных тварей. $B$BНо я не дам добру пропасть. Отправляйся в святилище Луны и посмотри, нельзя ли собрать с тамошних тварей немного кристаллизованной субстанции?', 'Магистр Даренис хочет, чтобы вы отправились в святилище Луны к западу от Транквиллиона и добыли 8 кристализованных субстанций маны с волшебных пожирателей и маначервей, что населяют это место.', 'Это очень мощная субстанция. Я весьма доволен твоей работой.', 'Ты добыл субстанцию, $N?', NULL, NULL, 'Кристализованная субстанция маны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9151, 'Святилище Солнца', 'Ты $gдоказал:доказала: свою верность Транквиллиону, оказав содействие в борьбе против сил Плети. Из Луносвета прибыли несколько наших самых могучих магистров, чтобы перенести битву прямо на вражеский порог.$B$BОни восстановили чародейское святилище на юге и оттеснили Плеть из окрестностей. Они намерены нанести удар по Смертхольму, оплоту Дар\'Хана. Тебе следует присоединиться к ним, $N. Уверен, $gтакой закаленный:такая закаленная:c: $C, как ты, очень им пригодится.', 'Поговорите с магистром Идонисом в святилище Солнца в Призрачных землях.', 'Так ты от Дарениса? Очень хорошо, думаю, твоя помощь в сражении с силами Дар\'Хана нам пригодится.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9152, 'Припасы могильщика', 'И как прикажете мне обеспечивать военные поставки, когда я даже своих собственных получить не могу? Мне обещали конвой – а он так и не прибыл. Кроме того, одну повозку пришлось бросить на западе, когда на меня напала шайка вурдалаков!$B$BС твоей помощью я мог бы заново открыть дело. Отправляйся из города по западной дороге мимо кладбища. По другую сторону Тропы Мертвых дорога раздваивается. Холм, за которым должна быть моя повозка, как раз за развилкой.', 'Найдите припасы Ратиса Могильщика и верните их хозяину в Транквиллион, что в Призрачных землях.', 'Теперь, когда мои припасы при мне, я могу открыть свою лавочку. Уверен, что верховный палач будет весьма рад узнать, что можно начинать войну против Дар\'Хана и Плети.$B$BКонечно же, мы не забыли о вознаграждении. Вот, $C, деньги, о которых я говорил. Заходи, если понадобится купить что-нибудь.', 'Как только верну себе остаток припасов, смогу заняться делом. Войскам не уйти далеко, если они не смогут покупать то, что им нужно.$B$BЗона боевых действий – место прибыльное, не так ли, $C? Ну да ладно, удалось ли тебе пробиться к моей повозке через полчища этих вурдалаков?', NULL, NULL, 'Припасы Ратиса Могильщика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9153, 'Под тенью', 'Парящие некрополи Плети не щадят ни Орду, ни Альянс. Тень летающих крепостей пала на Танарис, Выжженные Земли, Зимние Ключи и Пылающие степи.$B$BТолько объединив усилия, мы сможем противостоять этой беде.$B$BНекрополи поддерживаются энергией магических кругов, которые размещены в различных точках захваченных регионов. Все магические круги охраняются полчищами нежити. Мы определили, что если уничтожить эти толпы нежити, то защита кругов будет снята.', 'Найдите по карте регион, атакуемый Плетью. Отправляйтесь туда и излейте свою ярость на некрополь, разгромив толпы Плети вокруг него. Доставьте 10 некротических рун Плети командиру Томасу Элерану в Часовню Последней Надежды в Восточные Чумные земли.', 'Умница, $N. Постепенно занимая новые позиции, мы сможем избавиться от угрозы со стороны возрожденной Плети.$B$BОтдохни и восстанови силы, но после этого тебе снова придется отправиться на фронт, иначе мы потеряем те земли, которые отбили сегодня. $B$BДабы помочь тебе в грядущих битвах, мы готовы отдать тебе некоторые из наших особых предметов в обмен на определенное количество некротических рун.', 'Потребуется какое-то время, чтобы избавиться от нависшей над нами угрозы. Как далеко тебе удалось продвинуться, $N?', NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9154, 'Часовня Последней Надежды', 'Захватчики Плети вернулись, и их теперь куда больше, чем когда-либо прежде. Серебряный Рассвет собирает всех, кто может носить оружие и желает пустить его в ход, для защиты наших земель.$B$BЕсли разделяешь эти убеждения, отнеси этот документ Хранителю свитков в Часовню Последней Надежды в Восточных Чумных землях.', 'Отнесите объявление о мобилизации Хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.', 'Серебряный Рассвет посылает призыв о помощи, и ты – среди тех, кто откликнулся на этот призыв. Нет времени, чтобы должным образом обучить тебя. Мы верим в твои способности и в то, что с твоей помощью мы сумеем отразить угрозу, исходящую от Плети.', 'Ты здесь ради того, чтобы вступить в наши ряды, не так ли?', NULL, NULL, 'Объявление о мобилизации (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9155, 'По Тропе Мертвых', 'Раз уж ты $Gзабрел:забрела; в такую даль, то $gдолжен:должна: знать о Тропе Мертвых. Даже теперь твари Плети бездумно следуют по выжженной полосе, что оставил за собой Артас по пути в Луносвет.$B$BПокажи, на что ты $gспособен:способна:, прореди ряды Плети на Тропе. Если отработаешь свой хлеб, я замолвлю за тебя доброе слово.', 'Убейте 10 восставших ненасытников и 10 уродливых каннибалов на Тропе Мертвых. Возвращайтесь к ловчему смерти Ратиэлю в Транквиллион за наградой.', 'Неплохо, $N. Вот, держи. Было бы славно, если бы таких как ты, было побольше в этих краях.', NULL, NULL, NULL, 'Восставший ненасытник убито', 'Уродливый каннибал убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9156, 'Разыскиваются: Гнилоступ и Лузран', 'Сим назначается щедрая награда за мерзостных поганищ, известных как Гнилоступ и Лузран! Эти отвратительные создания Дар\'Хана чрезвычайно опасны. Их видели близ Воющего и Кровоточащего зиккуратов. Тот, кто желает получить награду, должен предоставить головы этих поганищ ловчему смерти Ратиэлю в доказательство своей победы!', 'Найдите в Призрачных землях Гнилоступа и Лузрана. Принесите их головы ловчему смерти Ратиэлю в Транквиллион и получите награду.', 'Ага... Лузран и Гнилоступ! Ну, что невеселый нынче у вас видок, а? Хотя краше вы, как вижу, не стали.$B$BВозьми себе награду из этих вещей на выбор, $N. Ты ее заслужил.', 'У тебя есть что мне показать, $N?', NULL, NULL, 'Голова Гнилоступа', 'Голова Лузрана', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9157, 'Забытые обряды', 'Каждый год мы, обитатели деревни Солнечной Короны, принимали участие в обряде, который был предназначен для того, чтобы держать под контролем различные аспекты природы. Власть над стихией воды символизировалась призыванием и покорением элементаля по имени Аквантион. Но наши чары были подлым образом искажены, в результате этот поганец разорвал узы и сам поработил нас!$B$BВо время обряда мы носили медальоны в виде волны. Найди их на дне этого озера, они нужны нам, чтобы освободить души наших сородичей!', 'Принесите 8 медальонов Волны Геранису Белому Рассвету в Призрачные земли.', 'Теперь, когда у нас снова есть эти медальоны, мы призовем Аквантиона. Этот мятежный элементаль заплатит за нашу смерть. Мы будем отомщены!', 'Удалось ли тебе добыть медальоны, $N? Духи утонувших по-прежнему бродят вокруг озера!', NULL, NULL, 'Медальон волны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9158, 'Разносчики заразы', 'Ты $Gпроявил:проявила; мужество, отправившись сюда, в Призрачные земли, $N. Здесь у нас много работы и мало храбрецов, готовых за нее взяться.$B$BЕсли ты действительно $gготов:готова: нам помочь, я осмелюсь предложить тебе одно неблагодарное задание. Вся дикая природа здесь поражена заразой, и мы должны остановить ее распространение. Ступай охотиться на светлопалых рысей к востоку и югу отсюда и возвращайся, когда перебьешь достаточное их число.', 'Странница Седайна из Анклава Странников в Призрачных землях хочет, чтобы вы убили 10 светлопалых рысей.', 'Ты хорошо потрудился, $N. Очень важно, чтобы зараза не перекинулась на здоровых животных Вечной Песни. Если ты ищешь, что бы еще сделать, то у меня всегда найдется для тебя работа.', NULL, NULL, NULL, 'Светлопалая рысь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9159, 'Обуздание заразы', 'Ты $gпоказал:показала: себя достойным союзником, $N. Я прошу тебя продолжить труды и выследить еще некоторое количество зараженных животных. На сей раз придется иметь дело с более опасными тварями. А именно – с воронковыми пауками-прядильщиками к западу от Тропы Мертвых и мрачницами-вампирами к югу отсюда. Покончишь с делом – возвращайся ко мне.', 'Странница Седайна из анклава Странников, что в Призрачных землях, хочет, чтобы вы убили 8 воронковых пауков-прядильщиков и 10 мрачниц-вампиров.', 'Ты серьезно подошел к решению задачи, и потому я хотела бы достойно наградить тебя. Побольше бы нам таких отважных и решительных союзников, Ланцкнехт.', NULL, NULL, NULL, 'Мрачница-вампир убито', 'Воронковый паук-прядильщик убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9160, 'Обследование Ан\'дарота', '$C, у нас проблемы с группой ночных эльфов, недавно захвативших находящийся поблизости островок. Они устроили небольшой лагерь в Ан\'дароте, древнем узле линии магической силы, облюбованном еще высшими эльфами. Это к северо-западу отсюда. Туда ведет грунтовая дорога, что начинается сразу за Тропой Мертвых.$B$BПомоги нам – отправляйся туда, узнай, что они затевают, и перебей сколько сможешь этих надменных ночных эльфов.', 'Обследуйте район Ан\'дарота, убейте 12 часовых-шпионов и возвращайтесь к госпоже Златилен в Транквиллион, что в Призрачных землях.', 'Как жаль, что операция в Ан\'дароте не пролила свет на планы ночных эльфов! Однако меня заинтересовали эти предметы, похожие на магически выращенные деревья с наполненными силой шарами наверху! Возможно, нам следует более целенаправленно собирать информацию.$B$BВозьми эти деньги и эликсиры. Уверена, они тебе понадобятся очень скоро, особенно в наших делах с ночными эльфами.', NULL, NULL, NULL, 'Часовой-шпион убито', 'Исследовать локацию', 'Обследование Ан\'дарота', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9161, 'Тень предателя', 'Говорят, что Дар\'Хан Дратир восстал из мертвых, чтобы возглавить полчища Плети здесь, в Призрачных землях. Дар\'Хан давно уже связался с Плетью... но некогда, при жизни, он был эльфом... Большую часть своего времени он проводил в башне Утренней Звезды, к северо-западу отсюда. Он скрывался там долгими ночами, строя козни против собственного народа. $B$BОбыщи башню, $N, может, найдешь еще какую информацию. Возможно, он вел дневник или делал записи. Поищи, информация лишней не бывает.', 'Отправляйтесь к башне Утренней Звезды в Призрачных землях и найдите любую информацию о прошлом Дар\'Хана.', 'Перевернув несколько страниц этой древней книжицы, вы приходите к выводу, что некогда она принадлежала эльфу по имени Дар\'Хан Дратир.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9162, 'Hints of the Past', 'As you skim through the pages in the journal you\'re overcome by an unnerving sense of being watched.$B$BThe contents are unsettling.  Dar\'Khan\'s soul was one filled with hatred and contempt for his own people.  The extent of his machinations and plots are all documented in great detail.$B$BPerhaps there is something here that Vynna will find useful.', 'Return to Ranger Vynna at the Farstrider Enclave with Dar\'Khan\'s Journal.', 'This information is very valuable, $N.  We all knew about Dar\'Khan\'s plans to steal the power of the Sunwell for the Scourge, but much of the information found here is completely new to us.  Magister Kaendris at the Sanctum of the Sun will want to look at this. ', 'Поведай мне, $N, что тебе удалось найти?', NULL, NULL, 'Записи Дар\'Хана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9163, 'Вылазка на оккупированную территорию', 'Наиболее простой способ выведать планы ночных эльфов – отправить тебя на их остров с целью добыть любую доступную информацию.$B$BЯ хочу, чтобы ты $gнаправился:направилась: на запад по дороге из города на остров Шаландис, что прямо рядом с побережьем. Ступай туда и принеси мне все планы, которые найдешь на острове либо на корабле.', 'Выкрадите планы ночных эльфов относительно Ан\'дарота, Ан\'овина и магического наблюдения за син\'дорай, затем доставьте их госпоже Златилен в Транквиллион, что в Призрачных землях.', 'Очень тревожно! Из этих планов видно, что силы ночных эльфов сосредоточены не только в Ан\'дароте – это нам известно, – но и в Ан\'овине, более удаленном узле линии силы к юго-востоку отсюда.$B$BНа востоке есть еще третий узел, о котором здесь не упоминается, – Ан\'телас. У меня очень нехорошие предположения насчет всего этого, $C.', 'Как успехи по раскрытию планов ночных эльфов на острове Шаландис, $C?', NULL, NULL, 'Планы ночных эльфов: Ан\'дарот', 'Планы ночных эльфов: Ан\'овин', 'Планы ночных эльфов: магическое наблюдение за син\'дорай', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9164, 'Пленники Смертхольма', 'А, да. Одно их моих лучших изобретений. Этот напиток снимает большинство алхимически вызванных видов оцепенения.$B$BПобочные эффекты – головокружение, р$N и - в редких случаях – временная слепота. Но все лучше, чем то, что Плеть готовит для этих пленников в Смертхольме, скажу я тебе.$B$BУдачи и еще раз удачи, $gотважный:отважная:c: $C. Она тебе пригодится.', 'Возьмите приводящее в сознание зелье Рензитена с собой в Смертхольм и спасите ученика Варниса, аптекаря Инит и следопыта Ведорана. Возвращайтесь к чародейке Джанеде в святилище Солнца за наградой.', 'Замечательная работа, $N. Без твоей помощи эти несчастные утратили бы разум, и их душами завладела бы Плеть.', 'Что с пленниками Смертхольма? Ты туда еще не ходил?', NULL, NULL, 'Аптекарь Инит спасена', 'Ученик Варнис спасен', 'Следопыт Ведоран спасен', 'Приводящее в сознание зелье Рензитена (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9165, 'Подорожная', 'Если бы не помощь странников вроде тебя, наш караван никогда не добрался бы до пункта назначения! Твари Плети лезут из всех щелей!$B$B*Страж Дидье утирает лоб*$B$BТеперь надо дождаться здесь фельдмаршала Чамберса, чтобы он подписал тебе подорожную. Предъявишь ее командиру Метцу в Часовню Последней Надежды в Восточные Проклятые земли.$B$BИ вот что, $N, имей в виду, Метц из тех парней, которые любят орать, мол, прихлопну как муху да кишки по деревьям развешу... Только в отличие от большинства подобных крикунов, именно так он и сделает.', 'Доставьте подписанную подорожную командиру Метцу в Часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Подорожная подписана', 'Подорожная (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9166, 'Донесение в Ан\'телас', 'Отправляйся на восток. На южном склоне пика Солнечного Пастбища, к северо-востоку от святилища Солнца, находится Ан\'телас. Именно туда следует доставить обнаруженные нами планы ночных эльфов.$B$BМагистр Силастор постоянно проводит там исследования узлов линий силы для потенциального их использования в битве с Плетью. Пусть глянет на эти планы и прольет свет на замыслы ночных эльфов.', 'Передайте планы ночных эльфов магистру Силастору из Ан\'теласа в Призрачных землях.', 'Это ужасно! Ночные эльфы! Они создали здесь свой лунный кристалл с какой-то нечестивой целью, но я ускользнул от них и собрал отряд разведчиков и заклинателей из соседнего святилища Солнца. Мы перебили большинство их, и сейчас отряд выслеживает и истребляет оставшихся!$B$BЯ рад, что ты сейчас здесь, у меня для защиты осталась только пара разведчиков! Тут небезопасно!$B$BПодожди минуточку, я просмотрю эти планы и пойму, что затевают ночные эльфы.', 'О, хвала Солнцу!', NULL, NULL, 'Планы ночных эльфов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9167, 'Гибель предателя', 'Все, что мы сделалив Призрачных землях, призвано вернуть то, что принадлежит нам по праву. Плеть слишком долго держала в своих когтях эти земли.$B$BПришло время расплаты, $N. Благодаря тебе и нашим новым союзникам, Отрекшимся, час отмщения близок.$B$BТот, кто хочет похитить мощь Солнечного Колодца, должен сгинуть! Ступай в Смертхольм, оплот Плети к югу от Тропы Мертвых. Принеси мне голову Дар\'Хана, и твои деяния не будут забыты!', 'Убейте Дар\'Хана Дратира в Смертхольме и принесите его голову магистру Кендрису в святилище Солнца в Призрачных землях.', 'Сегодня ты нанес сокрушительный удар по господству Плети в этих краях.$B$BТеперь, когда гнусный предатель мертв, мы вернем себе наши земли, и величие наше будет восстановлено!', 'Ну, дело сделано? Дар\'Хан убит?', NULL, NULL, 'Голова Дар\'Хана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9168, 'Сердце Смертхольма', 'Глубоко в недрах Смертхольма наши враги пытаются создать более сильных и смертоносных призрачных солдат. Эти гнусные твари – совершенные инструменты, созданные самим Дар\'Ханом и закаленные черной магией Смертхольма.$B$BОтправляйся в башню Проклятых Смертхольма и уничтожь их, $N. Мы не можем позволить армии нашего врага усиливаться в то время, как мы с трудом удерживаем плацдарм в Призрачных землях.', 'Уничтожьте 8 очей Дар\'Хана и доложите об этом магистру Идонису в святилище Солнца в Призрачных землях.', '', NULL, NULL, NULL, 'Око Дар\'Хана убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9169, 'Ан\'овин: отключение', 'Эти лунные кристаллы – наблюдательные устройства, и следят они за нами! Я понимаю, что из Ан\'дарота до кристаллов дотянуться не смогут, чего не могу сказать про Ан\'овин, что лежит прямо к югу отсюда.$B$BИз схем, которые теперь есть в моем распоряжении, я узнал основные принципы действия лунных кристаллов; достаточно просто отключить их. Отправляйся в Ан\'овин, добудь сферу управления у одного из ночных эльфов и с ее помощью отключи лунный кристалл, чтобы не дать осуществиться их планам!$B$BТоропись, $C!', 'Добудьте сферу управления кристаллом и с ее помощью отключите лунный кристалл ночных эльфов в Ан\'овине. Затем возвращайтесь к магистру Силастору в Ан\'телас в Призрачных землях.', 'Какое облегчение, $C! Знай, что если бы ты не отключил эти следящие шары, мы оказались бы в еще более тяжелом положении, чем сейчас! Подумай только - кругом враги, и один из них способен следить за каждым нашим шагом!$B$BНо теперь нам не надо об этом беспокоиться - и все благодаря тебе! Вот, возьми, я хочу вознаградить тебя за труды, а у меня тут как раз образовалось несколько вещиц, которые мне уже больше не понадобятся.$B$BЕще раз спасибо тебе, !', NULL, NULL, NULL, 'Лунный кристалл ночных эльфов отключен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9170, 'Приспешники Дар\'Хана', 'Этот подлый предатель, Дар\'Хан, обрел великую власть, встав на сторону Плети. Его приспешники командуют огромной армией нежити, что противостоит нашим тающим силам.$B$BМасофет Черный, Джурион Обманщик, Боргот Кровопускатель и Мирдоран Мерзостный. Запомни эти имена крепко, ибо в Призрачных землях эти полководцы Плети уступают только самому Дар\'Хану. Срази их, и их безмозглое воинство будет повергнуто в хаос.', 'Магистр Идонис хочет, чтобы вы отправились в Смертхольм и сразили Масофета Черного, Джуриона Обманщика, Боргота Кровопускателя и Мирдорана Мерзостного. Выполнив поручение, отчитайтесь перед магистром Идонисом в святилище Солнца Призрачных земель.', 'Армии Дар\'Хана скоро будут разгромлены. Плеть не выстоит против объединенной мощи син\'дорай и Отрекшихся.', 'Удалось ли тебе разрушить командную структуру Плети, Дезенджел? Приспешники Дар\'Хана мертвы?', NULL, NULL, 'Мирдоран Мерзостный убито', 'Боргот Кровопускатель убито', 'Джурион Обманщик убито', 'Масофет Черный убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9171, 'Хрустящий деликатес', 'Это невыносимо! Мне тут совершенно не из чего готовить! Госпожа пригласила меня из Луносвета – ей нужны утонченные блюда, соответствующие ее положению. А что, нет? И вот я здесь, но тут нечего есть! Ты $gдолжен:должна: пойти и принести свежей дичи, чтобы я хоть что-нибудь смог приготовить.$B$BГоспожа Златилен любит покушать что-нибудь хрустящее. К юго-западу отсюда, по ту сторону Тропы Мертвых, полно воронковых пауков-прядильщиков. Да, они противные, я знаю, но именно они нам и нужны.', 'Добудьте 5 хрустящих паучьих лапок и принесите их главному шеф-повару Плеснеру в Транквиллион, что в Призрачных землях.', 'Отлично, то что надо! Нет, не рассказывай мне про этих ползучих тварей, слушать не желаю! Я обращу свою магию на эти ножки, и они станут замечательно вкусными. Немножко специй, немножко травок-приправок и, конечно, щепоточку чар, и вот вам блюдо, достойное королевы! Или, в нашем случае, благородной дамы.$B$BТы сослужил мне хорошую службу, $C. Вот тебе в награду рецепт и кусочек на пробу.', 'Я даже отсюда слышу, как у дамы бурчит в животе! Надеюсь, ты принес то, что я просил?', NULL, NULL, 'Хрустящая паучья лапка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9172, 'Доклад магистру Кендрису', 'Магистры святилища Солнца далеко продвинулись в анализе слабостей Плети при помощи Отрекшихся. Магистр Кендрис знает, что делать с этой информацией.$B$BСвятилище Солнца находится к юго-западу отсюда. Торопись, $N. Дар\'Хан – коварный враг, он следит за каждым нашим шагом!', 'Принесите дневник Дар\'Хана магистру Кендрису в святилище Солнца, что в Призрачных землях.', 'Эта книжица... быть того не может! Это почерк самого Дар\'Хана. В ней должна быть информация, которая раскроет нам слабости нашего противника.$B$BХорошо, что ты пришел с ней к нам, $N. Странники проявили великую мудрость, передав эти записи нам. А вот этот доспех в грядущем пригодится тебе на службе нашему общему делу.', 'Ты хочешь говорить со мной?', NULL, NULL, 'Записи Дар\'Хана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9173, 'Захват шпилей Ветрокрылых', '$C, я желаю, чтобы ты $gзахватил:захватила: шпили Ветрокрылых!$B$BЭто высокая честь. Шпили Ветрокрылых – родина леди Сильваны Ветрокрылой, повелительницы Отрекшихся и бывшей главнокомандующей следопытов. Однако ныне они захвачены безмозглыми полчищами Плети.$B$BЧтобы добраться туда, ступай по южной дороге до развилки. Возьми направо, пересеки Тропу Мертвых и иди на юго-запад. Ты обязательно увидишь ее.', 'Убейте 8 послушников из Смертхольма и 10 павших следопытов, затем возвращайтесь к верховному вершителю Маврену в Транквиллион, что в Призрачных землях.', 'Уверен, что леди Сильвана будет довольна, узнав о наших успехах здесь.$B$BВозьми эту монету за труды.', NULL, NULL, NULL, 'Послушник из Смертхольма убито', 'Павший следопыт убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9174, 'Победа над Аквантионом', 'Этот злобный элементаль сгубил много жизней в тот роковой день, когда восстал против нас. Чтобы нарушить наш обряд, он призвал подлых мурлоков. Более того, ему удалось исказить наши чары и обратить их против нас.$B$BПокажи ему всю силу нашей неутоленной мести! Возьми эти медальоны и возложи их на алтарь Укрощения Приливов на дне озера. Аквантион тут же ответит на твой вызов!$B$BНо берегись, $r! Поскольку наша магия более не властна над ним, гнев его будет неукротим! Срази Аквантиона, дабы мы обрели покой!', 'Геранис Белый Рассвет хочет, чтобы вы нырнули на дно озера к востоку от деревни Солнечной Короны и возложили связку медальонов на алтарь укрощения волн. Призовите и сразите элементаля по имени Аквантион, затем возвращайтесь к Геранису.', 'Ты отомстил за нашу гибель и освободил наши души от власти Аквантиона. Наконец-то мы обретем покой.', 'Аквантион убит?', NULL, NULL, 'Аквантион убито', 'Сверток с медальонами (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9175, 'Ожерелье Госпожи', 'Ожерелье мерцает, это настоящий шедевр ювелирного искусства, который светится даже во мраке, окутывающем Призрачные земли. Судя по надписи и месту, где вы его нашли, это наверняка принадлежит самой леди Сильване Ветрокрылой!$B$BНаверное, лучше всего будет отнести эту вещь верховному вершителю Маврену в Транквиллион. Похоже, он самый высокопоставленный Отрекшийся в здешних местах и наверняка знает, что с этой вещью делать.', 'Отнесите ожерелье госпожи верховному вершителю Маврену в Транквиллион, что в Призрачных землях.', 'Говоришь, ты нашел это на одной из тварей Плети в шпилях Ветрокрылых и что на ней есть надпись? Дай-ка посмотреть!$B$BВот, возьми монету за хорошую работу.', 'Что там у вас, $N?', NULL, NULL, 'Ожерелье Госпожи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9176, 'Зиккураты-близнецы', 'Судя по этому дневнику, Дар\'Хан пообещал Плети два мощных эльфийских артефакта: камень света и камень пламени. Они наполнены магический силой Солнечного Колодца и настроены так, чтобы Плеть не могла овладеть ими.$B$BЭти кристаллы предполагалось перенести туда, где ныне стоят Воющий и Кровоточащий зиккураты, прямо в центр Тропы Мертвых. Если они и доныне там, нам нужно вернуть их. Их сила очень понадобится нам в борьбе с врагом.', 'Отправьтесь к Кровоточащему зиккурату и Воющему зиккурату и добудьте оттуда камень света и камень пламени. После этого возвращайтесь к магистру Кендрису в святилище Солнца.', 'Слухи были верны! Камень света и камень пламени и правда существуют! Мы сделаем из них оружие, которое обратим против Дар\'Хана.$B$BВоспользуйся им, когда наступит срок, и сила Солнечного Колодца, заключенная в них, поразит предателя той самой силой, которую он хотел похитить у нас!', 'Тебе удалось добыть кристаллы?', NULL, NULL, 'Камень пламени', 'Камень Света', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9177, 'Путь в Подгород', 'Невероятно! Похоже, это подарок леди Сильване Ветрокрылой от ее сестры Аллерии!$B$BТебе необходимо тотчас же доставить эту вещь ей в Подгород! Двор госпожи находится в Королевском квартале.$B$BЧтобы попасть туда, воспользуйся сферой транслокации во внутреннем святилище дворца Ярости Солнца в городе Луносвет, который перенесет тебя в Подгород. Как только окажешься там, спустись на подъемнике в сам город. Чтобы попасть в Королевский квартал, воспользуйся своими картами.', 'Отнесите Леди Сильване Ветрокрылой ожерелье Госпожи в Королевский Квартал Подгорода.', '<Сильвана выхватывает у вас ожерелье.>$B$BБыть того не может! Столько лет прошло... я думала, оно навсегда пропало...$B$B<После долгого задумчивого молчания леди приходит в себя и берет себя в руки.>$B$BТы думал, это меня обрадует? Думаешь, я вспоминаю те времена, когда не была владычицей Отрекшихся? Оно ничего для меня не значит, как, впрочем, и для тебя. И Аллерия Ветрокрылая давно мертва и позабыта!$B$B<Она роняет амулет на землю.>$B$BТеперь можешь удалиться, $C.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9178, 'Задание мастера – массивное грузило', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд BS-091:$B$B120 массивных грузил.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 120 массивных грузил и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера – массивное грузило (Прилагается)', 'Массивное грузило (120)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9179, 'Задание мастера: имперский латный нагрудник', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд BS-428:$B$B3 имперских латных нагрудника.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 3 имперских латных нагрудника и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера: имперский латный нагрудник (Прилагается)', 'Имперский латный нагрудник', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9180, 'Путь в Подгород', 'Невероятно! Похоже, это подарок леди Сильване Ветрокрылой от ее сестры Аллерии!$B$BТебе необходимо тотчас же доставить эту вещь ей в Подгород! Двор госпожи находится в Королевском квартале.$B$BЧтобы попасть туда, воспользуйся сферой транслокации во внутреннем святилище дворца Ярости Солнца в городе Луносвет, который перенесет тебя в Подгород. Как только окажешься там, спустись на подъемнике в сам город. Чтобы попасть в Королевский квартал, воспользуйся своими картами.', 'Отнесите Леди Сильване Ветрокрылой ожерелье Госпожи в Королевский Квартал Подгорода.', '<Сильвана выхватывает у вас ожерелье.>$B$BБыть того не может! Столько лет прошло... я думала, оно навсегда пропало...$B$B<После долгого задумчивого молчания леди приходит в себя и берет себя в руки.>$B$BТы думал, это меня обрадует? Думаешь, я вспоминаю те времена, когда не была владычицей Отрекшихся? Оно ничего для меня не значит, как, впрочем, и для тебя. И Аллерия Ветрокрылая давно мертва и позабыта!$B$B<Она роняет амулет на землю.>$B$BТеперь можешь удалиться, $C.', 'Представься.$B$BЧто это у тебя? Это ожерелье кажется мне знакомым... Дай его мне!', NULL, NULL, 'Ожерелье Госпожи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9181, 'Задание мастера: вулканический молот', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд BS-697:$B$B3 вулканических молота.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 3 вулканических молота и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера: вулканический молот (Прилагается)', 'Вулканический молот', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9182, 'Задание мастера: огромный ториевый боевой топор', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд BS-6020:$B$B3 огромных ториевых боевых топора.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 3 огромных ториевых боевых топора и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера: огромный ториевый боевой топор (Прилагается)', 'Огромный ториевый боевой топор', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9183, 'Задание мастера: светозарный венец', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд BS-80:$B$B3 светозарных венца.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 3 светозарных венца и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера: светозарный венец (Прилагается)', 'Светозарный венец', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9184, 'Задание мастера: гибельная кожаная головная повязка', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд LW-971:$B$B10 гибельных кожаных головных повязок.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 10 гибельных кожаных головных повязок и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера: гибельная кожаная головная повязка (Прилагается)', 'Гибельная кожаная головная повязка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9185, 'Задание мастера: накладки из грубой кожи', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд LW-448:$B$B25 комплектов грубой брони.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 25 комплектов грубой брони и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', 'Грубая броня – вещь весьма функциональная, $N. Это не просто броня. Например, вот эту деталь можно использовать как чехол для чайника.', 'Явился с заказом, $C?', NULL, NULL, 'Задание мастера – комплект грубой брони (Прилагается)', 'Комплект грубой брони', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9186, 'Задание мастера: гибельный кожаный пояс', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд LW-736:$B$B9 гибельных кожаных поясов.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 9 гибельных кожаных поясов и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера: гибельный кожаный пояс (Прилагается)', 'Гибельный кожаный пояс', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9187, 'Задание мастера: рунические кожаные штаны', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд LW-8485:$B$B4 пары рунических кожаных штанов.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 4 пары рунических кожаных штанов и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера: рунические кожаные штаны (Прилагается)', 'Рунические кожаные штаны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9188, 'Задание мастера: штаны из яркой ткани', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд TR-95:$B$B6 пар штаны из яркой ткани.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 6 пар штанов из яркой ткани и соответствующее задание мастера караванщику Камнетесу в яасовню Последней Надежды в Восточные Чумные земли.', 'Ничего себе – да я вижу в них свое отражение!', 'Явился с заказом, $C?', NULL, NULL, 'Задание мастера: штаны из яркой ткани (Прилагается)', 'Штаны из яркой ткани', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9189, 'Посылка в Гробницу', 'Тебе удалось тронуть женское сердце, хоть оно и не бьется.$B$BОднако мне нужно доставить кое-какие бумаги в Гробницу, расположенную в Серебряном бору. Наш представитель там - советник Соррелон.$B$BЕсли ты не собираешься лететь на летучей мыши, кратчайший путь - это выйти из Подгорода и двинуться по дороге на юг. Смотри на указатели, отыскать нужное место будет несложно. Соберись с духом. Гробница представляет собой полуразрушенный склеп.$B$BСтранные существа эти Отрекшиеся.', 'Отнесите запечатанные приказы син\'дорай советнику Соррелону в Гробницу в Серебряном бору.', 'Посол Печаль Солнца явно рассчитывает, что твое возвышение пойдет на пользу син\'дорай. Впрочем, неудачно получилось с леди Сильваной. Не обращай внимания, $N, ты не напрасно вернула ей ожерелье. Ей бы спасибо тебе сказать, но таковы уж все правители.$B$BЕсли ты возьмешься помогать Отрекшимся – смотри, не распускайся. Ты ведь не хочешь испортить наши отношения с Ордой?', 'Приветствую тебя, сестра. Какие вести ты принесла?', NULL, NULL, 'Запечатанные приказы син\'дорай (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9190, 'Задание мастера: сапоги из рунической ткани', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд TR-635:$B$B8 пар сапог из рунической ткани.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 8 пар сапог из рунической ткани и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера: сапоги из рунической ткани (Прилагается)', 'Сапоги из рунической ткани', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9191, 'Задание мастера: сумка из рунической ткани', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд TR-9999:$B$B8 сумок из рунической ткани.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 8 сумок из рунической ткани и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', 'С ума сойти! Это и в самом деле сумки? Солдаты ноют без перерыва, что им не во что складывать их барахло... В смысле необходимую амуницию. Один придурок даже нарисовал мне диаграмму – видали зануду?$B$BМожет теперь они хоть ненадолго перестанут канючить...', 'явилась с заказом, $C?', NULL, NULL, 'Задание мастера: сумка из рунической ткани (Прилагается)', 'Сумка из рунической ткани', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9192, 'Беда в Беспросветных рудниках', 'Беспросветные рудники к юго-западу отсюда захвачены гноллами, зовущими себя кланом Черной Лапы. Мне не надо напоминать тебе, сколь стратегически важны эти рудники для нашей кампании в Призрачных землях!$B$BСтупай по южной дороге из города и на развилке возьми вправо. Прямо за зиккуратом справа будет короткая грунтовая тропа на запад. Иди по ней.$B$BКак увидишь кучи руды, знай – ты $gпришел:пришла:.', 'Убейте 8 гноллов-чернолапов, 6 падальщиков-чернолапов и 4 шаманов-чернолапов и возвращайтесь к ловчему смерти Малтендису в Транквиллион, что в Призрачных землях.', 'Славную кровавую баню ты учинил там, $C! Теперь горняки вернутся к работе. Уверен, они будут разочарованы, что перекур кончился, но надо ковать оружие и доспехи, стало быть, добывать руду.$B$BВот, прими в награду за выполнение долга. Чини оружие и доспехи – и выпей за мое здоровье!', NULL, NULL, NULL, 'Гнолл-чернолап убито', 'Падальщик-чернолап убито', 'Шаман-чернолап убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9193, 'Обследование катакомб Амани', '$C, наши разведчики доносят, что тролли, погребенные в катакомбах Амани под пиком Солнечного пастбища, восстали из мертвых. Госпожа Златилен хочет, чтобы ты $gобследовал:обследовала: эти катакомбы и $gсжег:сожгла: все останки, что пока еще не ожили. Ни одна из этих тварей не должна восстать их мертвых!$B$BБыстрее всего туда можно добраться по северной дороге из города, а затем на первой развилке свернуть направо. Так ты доберешься до северного склона пика, стало быть, вход ищи на юге.', 'Обследуйте катакомбы Амани и сожгите 10 иссохших останков троллей, затем возвращайтесь к советнице Вальвин в Транквиллион в Призрачных землях.', 'Мерзко, но другого пути нет. Поверь мне. Ты сослужил нам хорошую службу, разобравшись с этим делом, $C. Прошу, прими это в знак нашего расположения и благодарности.', 'Это грязная и неблагодарная работа, $C. Но я надеюсь, что ты ее исполнишь, к вящему удовлетворению госпожи...', NULL, NULL, 'Погребено иссохших останков троллей', 'Пылающий факел (Прилагается)', 'Исследовать локацию', 'Обследование катакомб Амани');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9194, 'Задание мастера: одеяние из рунической ткани', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд TR-7229:$B$B8 одеяний из рунической ткани.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 8 одеяний из рунической ткани и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', 'О, не стоило! Нет, в самом деле не стоило этого делать. Не знаю, что там Метц себе думает, но в Наксрамасе этого давно не носят. $B$B*Караванщик Камнетес испускает тяжкий вздох*$B$BПревосходно, теперь я должен доставить на передовую еще один ворох хлама и получить за это еще один выговор от Чамберса!', 'явилась с заказом, $C?', NULL, NULL, 'Задание мастера: одеяние из рунической ткани (Прилагается)', 'Одеяние из рунической ткани', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9195, 'Задание мастера: гоблинская мина', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд EN-11:$B$B20 гоблинских саперных зарядов.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 20 гоблинских саперных зарядов и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера – гоблинский саперный заряд (Прилагается)', 'Гоблинская мина', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9196, 'Задание мастера: ториевая граната', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд EN-7:$B$B20 ториевых гранат.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 20 ториевых гранат и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', 'Да, похоже на них ушла уйма меди. Я прав или я прав, $N?', 'явилась с заказом, $C?', NULL, NULL, 'Задание мастера: ториевая граната (Прилагается)', 'Ториевая граната', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9197, 'Задание мастера: боевой цыпленок гномов', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд EN-0:$B$B4 боевых цыпленка гномов.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 4 боевых цыпленка гномов и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера – боевой цыпленок гномов (Прилагается)', 'Боевой цыпленок гномов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9198, 'Задание мастера: ториевая труба', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд EN-558:$B$B14 ториевых труб.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командор Метц, Серебряный Рассвет', 'Доставьте 14 ториевых труб и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', 'Ториевые трубы? О, моя благодарность не знает границ...$B$B*Караванщик Камнетес бросает связку труб к большую кучу разнокалиберного хлама*', 'явилась с заказом, $C?', NULL, NULL, 'Задание мастера: ториевая труба (Прилагается)', 'Ториевая труба', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9199, 'Джуджу троллей', 'Погребенные в катакомбах Амани тролли начали восставать из мертвых! Я хочу, чтобы ты $gотправился:оправилась: туда и $gвернулся:вернулась: с доказательствами их окончательной и бесповоротной смерти! На некоторых из этих тролльских мумий и их вполне живых двойниках есть джуджу – святящиеся предметы, в которых заключен неведомый источник силы. Возможно, от этого они и оживают!$B$BКатакомбы лежат под пиком Солнечного Пастбища, прямо на востоке. Мне говорили, что проще всего туда добраться через вход в северном склоне горы. Найди же его, $C!', 'Соберите 8 джуджу троллей и принесите их стражу смерти Малтендису в Транквиллион в Призрачных землях.', 'Значит, мумий поднимают тролльские жрецы... умно! Видать, тролли Призрачной Сосны пытаются пополнить свои ряды при помощи некромантии. Готов поспорить, что эти оракулы использовали джуджу во время обряда воскрешения.$B$BТы еще раз подтвердил свою верность долгу, а чего еще ждать от $C с такой репутацией? Прими это вместе с моей благодарностью!', 'Думаю, мне незачем напоминать тебе, что мы не можем позволить себе, чтобы эти тролли поднимались из покойников прямо у нас под носом! Нам хватает забот со Смертхольмом на юге!', NULL, NULL, 'Джуджу троллей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9200, 'Задание мастера – сильнейшее зелье маны', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд AL-473:$B$B10 мер хорошего зелья маны.$B$BВыполненные заказы доставлять караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: командир Метц, Серебряный Рассвет', 'Доставьте 10 сильнейших зелий маны и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли.', 'Только последний дурак усомнится в необходимости этого зелья для наших войск.', 'Явился с заказом, $C?', NULL, NULL, 'Задание мастера – сильнейшее зелье маны (Прилагается)', 'Сильнейшее зелье маны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9201, 'Задание мастера: сильное зелье защиты от тайной магии', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд AL-1420:$B$B15 мер сильного зелья чародейской защиты.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 15 мер сильного зелья чародейской защиты и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', '*Караванщик Камнетес откупоривает одну склянку зелья, делает хороший глоток и блаженно прикрывает глаза*$B$BО-ох... Знатно торкает...', 'явилась с заказом, $C?', NULL, NULL, 'Задание мастера – сильное зелье чародейской защиты (Прилагается)', 'Сильный чародейский эликсир', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9202, 'Задание мастера: огромный флакон с лечебным зельем', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд AL-169110:$B$B20 мер хорошего лечебного зелья.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 20 мер хорошего лечебного зелья и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', '\"А ты знаешь как это снадобье зовется на передовой? Солдаты зовут его \"джинном в бутылке\"!\"$B$B*Караванщик Камнетес поет противным голосом* \"Девять граммов в сердце или сто в кувшин – все в момент доставит всемогущий джинн!\"$B$B\"Чего это ты морщишься, сынок? Это же такая популярная песня, никогда не слышал?\"', 'Явился с заказом, $C?', NULL, NULL, 'Задание мастера – хорошее лечебное зелье (Прилагается)', 'Сильнейшее лечебное зелье', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9203, 'Задание мастера: зелье оцепенения', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд AL-90:$B$BЗелье оцепенения.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 1 зелье оцепенения и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Задание мастера: зелье оцепенения (Прилагается)', 'Зелье оцепенения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9204, 'Задание мастера: каменный угорь', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд FS-5:$B$B40 каменных угрей.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 40 каменных угрей и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', 'Ну-ну, а ведь мог бы найти этим угрям гора-аздо лучше применение, а, $N? Ну да поздно локти кусать!', 'Явился с заказом, $C?', NULL, NULL, 'Задание мастера – каменный угорь (Прилагается)', 'Каменный угорь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9205, 'Задание мастера: пластинчатая бронерыба', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд FS-12:$B$B30 латных бронерыб.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 30 латных бронерыб и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', 'Что, в самом деле не знаешь, что делают с этими рыбинами?$B$B*Караванщик Камнетес хохочет*$B$BИ не узнаешь!', 'Явился с заказом, $C?', NULL, NULL, 'Задание мастера – латная бронерыба (Прилагается)', 'Пластинчатая бронерыба', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9206, 'Задание мастера: молниевый угорь', 'Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд FS-9:$B$B30 молниевых угрей.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет', 'Доставьте 30 молниевых угрей и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.', 'Поверь мне, из этих угрей получаются самые лучшие роллы в мире. Да-да, в мире!', 'Явился с заказом, $C?', NULL, NULL, 'Задание мастера – молниевый угорь (Прилагается)', 'Молниевый угорь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9207, 'Образцы руды из Беспросветных рудников', 'Меня прислали сюда из святилища Солнца за образцами руды, но рудники захватили гноллы! Если я вскорости не доставлю эти образцы магистру, он мне голову оторвет. Ты не $gмог:могла: бы мне помочь, $C?$B$BРуду можно добыть из медных и оловянных жил, да и гноллы таскают ее там повсюду. Набрав достаточно руды, отнеси ее магистру Квалестису в святилище Солнца, что прямо на востоке отсюда. Когда пересечешь Тропу Мертвых, святилище будет прямо к югу от пика Солнечного Пастбища.', 'Принесите 6 образцов руды из Беспросветных рудников и доставьте их магистру Квалестису в святилище Солнца в Призрачных землях.', 'Значит, моя ученица не способна позаботиться о себе? Вернется – я с ней поговорю, и никакие гноллы ее не спасут. Кстати, почему она не вернулась с тобой?$B$B<Магистр вздыхает.>$B$BБеда с ней. Сколько же сил уйдет, прежде чем мне удастся вышколить ее как подобает? Спасибо, $C, за образцы. Мы надеемся открыть особые свойства в этой руде, которые помогут нам одолеть Плеть.$B$BПрошу, возьми эту монетку в знак моей признательности.', 'Чем могу помочь, $C?', NULL, NULL, 'Руда из Беспросветных рудников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9208, 'Защита Джунглей – Магический камень защиты', 'Занза владеет искусством древних троллей и может сделать множество полезных вещей. Тебе когда-нибудь приходилось слышать о Защите Джунглей? Ну конечно нет. Твой разум сбит с толку жалкой эльфийской магией.$B$BПринеси мне магический знак эльфийской работы. Тогда я дам тебе Защиту, и ты увидишь, что такое настоящая магия!', 'Занзе Неупокоенному в Зул\'Гурубе нужен магический камень защиты.', '', NULL, NULL, NULL, 'Магический знак защиты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9209, 'Защита Джунглей – Магический камень стремительности', 'Занза владеет искусством древних троллей и может сделать множество полезных вещей. Тебе когда-нибудь приходилось слышать о Защите Джунглей? Ну конечно нет. Твой разум сбит с толку жалкой эльфийской магией.$B$BПринеси мне магический знак эльфийской работы. Тогда я дам тебе Защиту, и ты увидишь, что такое настоящая магия!', 'Занзе Неупокоенному в Зул\'Гурубе нужен магический камень стремительности.', 'Жалкая эльфийская магия меня ужасно раздражает. Ничего, злость только придает мне сил.$B$BПринеси мне еще один магический камень, и я снова дам тебе Защиту Джунглей.', 'Ты принес магический камень?', NULL, NULL, 'Магический знак стремительности', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9210, 'Защита Джунглей – Магический камень сосредоточения', 'Занза владеет искусством древних троллей и может сделать множество полезных вещей. Тебе когда-нибудь приходилось слышать о Защите Джунглей? Ну конечно нет. Твой разум сбит с толку жалкой эльфийской магией.$B$BПринеси мне магический знак эльфийской работы. Тогда я дам тебе Защиту, и ты увидишь, что такое настоящая магия!', 'Занзе Неупокоенному в Зул\'Гурубе нужен магический камень сосредоточения.', '', NULL, NULL, NULL, 'Магический камень сосредоточения', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9211, 'Ледяная защита', 'Ледяная защита – это тончайшая пленка защитных чар, наносимая на отдельные элементы экипировки. Она позволяет усиливать защиту в бою с ледяными созданиями.$B$BОднако все, что делает Обрушивающий Гнев, имеет свою цену – и немалую! Клянчить скидку бесполезно. Ну что, $gготов:готова: раскошелиться?', 'Заплатите 10 знаков Марша и 30 золотых Матеусу Заклинателю Гнева в Часовню Последней Надежды в Восточные Чумные земли.', '*Матеус прячет золото*$B$BНу что ж, готовься платить за ремонт, $R. В Наксрамасе чужих не любят...', 'Если бы не Серебряный Рассвет, вряд ли бы тут сейчас мозолил мне глаза!', NULL, NULL, 'Значок Алого ордена', 'Требуется денег: 30', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9212, 'Бегство из Катакомб', 'Тролли устроили мне засаду и теперь держат в этой клетке. Боюсь, они хотят принести меня в жертву! Помоги мне выбраться отсюда!$B$BЗамок на клетке несложный... просто с этой стороны мне до него не дотянуться. Пожалуйста, отведи меня в Анклав Странников. Капитан Гелиос наверняка наградит тебя, а уж я-то век тебя не забуду!', 'Проводите следопыта Лилату к капитану Гелиосу в анклав Странников, что в Призрачных землях.', 'Ты настоящий герой, $C, раз сумел привести ее сюда в целости и сохранности! Полагаю, придется устроить рейд и зачистить еще и эти катакомбы. Можно подумать, нам не хватает проблем с живыми троллями!$B$BСегодня ты совершил великий подвиг, и я должен наградить тебя. Выбирай любой из этих предметов.', NULL, NULL, NULL, 'Проводите следопыта Лилату в Анклав Странников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9213, 'Теневая защита', 'Это гениальное изобретение! Также как и Ледяная защита, Теневая защита основана на использовании тонкой пленки защитной магии на элементах экипировки. Есть еще кое-что, что роднит ее с Ледяной защитой – ЦЕНА!$B$BНу что, $gготов:готова: выложить кругленькую сумму?', 'Заплатите 10 знаков Марша и 30 золотых Матеусу Заклинателю Гнева в Часовню Последней Надежды в Восточные Чумные земли.', '*Матеус поспешно прячет золото в складках своего одеяния*$B$BНу что ты болтаешься в дверях, $R? Забирай, что купил, и проваливай!', '*Матеус зевает*$B$BЕсли у тебя в карманах ветер, исчезни, насекомое.', NULL, NULL, 'Значок Алого ордена', 'Требуется денег: 30', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9214, 'Оружие Призрачной Сосны', '$C, я хочу, чтобы ты $gперебил:перебила: как можно больше троллей из племени Призрачной Сосны. Нам нужно как следует сократить их численность, прежде чем заняться Смертхольмом. И раз уж ты за это $gвзялся:взялась:, то давай-ка убьем двух зайцев одним выстрелом. Принеси мне их оружие – чего добру пропадать? А нам в борьбе против Плети оно может очень даже пригодиться.$B$BПрогуляйся вволю по их лагерям на востоке в Зеб\'Теле и на юге в Зеб\'Нове.', 'Принесите 3 топора охотников за головами, 3 булавы чародея, 3 когтя повелителей котов и 3 посоха проклинателя. Возвращайтесь к капитану Гелиосу в анклав Странников в Призрачных землях.', 'Тотчас же отправлю несколько следопытов оценить урон, нанесенный тобою троллям Призрачной Сосны. Если это оружие – действительно свидетельство твоего успеха, то не сомневаюсь, что после твоего подвига мы сотрем их с лица земли и вплотную займемся Плетью.$B$BВот, прими эти монеты за труды. У меня все равно карман дырявый.', 'Принес оружие? Теперь, когда этих троллей стало куда меньше, мы наконец сможем заняться Плетью.', NULL, NULL, 'Топор охотника за головами', 'Жезл темного чародея', 'Когти повелителя животных', 'Посох проклинателя');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9215, 'Награда за голову Келгаша!', 'РАЗЫСКИВАЕТСЯ: Капитану Гелиосу нужна голова Кел\'гаша Коварного, предводителя троллей племени Призрачной Сосны. Никаких полумер. Известно, что Кел\'гаш скрывается где-то на юге, в Зеб\'Нове.$B$B$B$BНАГРАДА: Будет, но никаких авансов!', 'Принесите голову Кел\'гаша Коварного капитану Гелиосу в анклав Странников, что в Призрачных землях.', 'А, так это благоухает голова Келгаша! Славная работа, $С!$B$BТеперь, когда их предводитель мертв, тролли Призрачной Сосны будут в полном смятении. А если учесть еще твои недавние успехи в деле сокращения их численности, нам выпадает блестящая возможность нанести им контрудар и стереть их с лица земли.$B$BПрими мою благодарность, $N. Не хочешь ли в награду выбрать какой-нибудь из этих предметов?', 'Чем так воняет?', NULL, NULL, 'Голова Кел\'гаша Коварного', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9216, 'Гниющие сердца', 'Я слыхала, будто тролли Амани пожирают сердца врагов, чтобы обрести их силу. Что-то в этом должно быть, $N. При должной обработке сердца нежити могут давать мощные эликсиры.$B$BПоохоться на зомби, что бродят по Тропе Мертвых, и принеси мне их сердца. А я покажу тебе, как мы сможем улучшить твои физические способности для борьбы с нежитью.', 'Принесите 10 гниющих сердец магистру Аминель в Транквиллион.', 'Возьми этот напиток, $N. Как только ты его выпьешь, твоя физическая сила в бою с Плетью усилится многократно. Если тебе понадобится еще порция напитка, принеси мне еще сердец.', 'Ты добыл необходимые мне сердца зомби, $N?', NULL, NULL, 'Гниющее сердце', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9217, 'Больше гниющих сердец', '', '', 'Это придаст тебе сил в борьбе с Плетью. Найдешь еще сердца, $N, - приноси.', NULL, NULL, NULL, 'Гниющее сердце', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9218, 'Позвоночный порошок', 'Темная энергия, которая струится в телах восставших мертвецов, накапливается в первую очередь в их позвоночниках. Я разработала метод перегонки этой энергии в зелье, которое резко увеличивает наши магические способности при борьбе с нежитью.$B$BПринеси мне позвоночного порошка, и я с радостью дам тебе этого зелья. Скелетов ты найдешь в избытке на Тропе Мертвых к западу отсюда.', 'Принесите 10 порций позвоночного порошка магистру Аминель в Транквиллион.', 'Вот, возьми, $N. Разницу ты почувствуешь тотчас же!$B$BМожешь приносить еще - все пойдет в дело. Побочные эффекты? Ну, может, суставы немного поноют. Но ничего хронического, уверяю тебя!', 'Ты добыл необходимые мне образцы, $N?', NULL, NULL, 'Позвоночный порошок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9219, 'Больше позвоночного порошка', '', '', 'Порошок мощный, как всегда, $N. Приноси его мне и впредь, если желаешь увеличить свою магическую силу для борьбы с Плетью!', NULL, NULL, NULL, 'Позвоночный порошок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9220, 'Война со Смертхольмом', 'Если хочешь помочь нам, то лучше это сделать здесь и сейчас.$B$BВосстановив святилище Солнца, мы подняли стяг сопротивления перед оплотом нашего врага – Смертхольмом. $B$BСтупай же и одолей орды нежити, что кишат в мерзостной крепости Плети.', 'Убейте 5 очей Дар\'Хана, 6 нерубов-центурионов и 6 плакальщиц в Смертхольме. Возвращайтесь к магистру Идонису в святилище Солнца в Призрачных землях.', 'Плеть познала силу нашего гнева, $N! Скоро их проклятая цитадель превратится в руины!$B$BТеперь, когда их силы ослабли, пора ударить и по другим стратегическим точкам.', NULL, NULL, NULL, 'Око Дар\'Хана убито', 'Неруб-центурион убито', 'Плакальщица убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9221, 'Превосходное боевое снаряжениее – Друг Рассвета', 'Приветствую тебя, $gбрат:сестра:. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?$B$BСразу предупреждаю, легендарное снаряжение очень дорого даже для друзей Рассвета. Рекомендую для начала заработать полное доверие Серебряного Рассвета!', 'За 30 знаков Рассвета и 30 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.', '', NULL, NULL, NULL, 'Значок Серебряного Рассвета', 'Значок Алого ордена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9222, 'Легендарное боевое снаряжение – Друг Рассвета', 'Приветствую тебя, $gбрат:сестра:. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?$B$BСразу предупреждаю, легендарное снаряжение очень дорого даже для друзей Рассвета. Рекомендую для начала заработать полное доверие Серебряного Рассвета!', 'За 110 знаков Рассвета и 110 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.', '', NULL, NULL, NULL, 'Значок Серебряного Рассвета (110)', 'Значок Алого ордена (110)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9223, 'Превосходное боевое снаряжение – Уважаемый Рассветом', 'Приветствую тебя, $gбрат:сестра:. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?$B$BСразу предупреждаю, легендарное снаряжение очень дорого даже для тех, кого уважают в Рассвете. Рекомендую для начала заработать полное доверие Серебряного Рассвета!', 'За 20 знаков Рассвета и 20 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.', '', NULL, NULL, NULL, 'Значок Серебряного Рассвета', 'Значок Алого ордена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9224, 'Легендарное снаряжение – Уважаемый Рассветом', 'Приветствую тебя, $gбрат:сестра:. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?$B$BСразу предупреждаю, легендарное снаряжение очень дорого даже для тех, кого уважают в Рассвете. Рекомендую для начала заработать полное доверие Серебряного Рассвета!', 'За 75 знаков Рассвета и 75 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.', '', NULL, NULL, NULL, 'Значок Серебряного Рассвета (75)', 'Значок Алого ордена (75)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9225, 'Легендарное боевое снаряжение – Чтимый Рассветом', 'Приветствую тебя, $gбрат:сестра:. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?$B$BНо помни, даже если тебя почитают в Серебряном Рассвете, эпические вещи будут стоить недешево!', 'За 45 знаков Рассвета и 45 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.', '', NULL, NULL, NULL, 'Значок Серебряного Рассвета (45)', 'Значок Алого ордена (45)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9226, 'Превосходное боевое снаряжениее – Чтимый Рассветом', 'Приветствую тебя, $gбрат:сестра:. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?$B$Bсякий, кого почитают в Серебряном Рассвете, получает вполне ощутимые скидки на приобретение товаров! Скорее же воспользуйся своим преимуществом!', 'За 7 значков Серебряного Рассвета и 7 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.', 'Всего хорошего, $N. С тобой приятно иметь дело.', 'Выбирай с умом. Выбранный предмет обмену и возврату не подлежит.', NULL, NULL, 'Значок Серебряного Рассвета', 'Значок Алого ордена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9227, 'Превосходное боевое снаряжениее – Восторг Рассвета', 'Приветствую тебя, $gбрат:сестра:. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?$B$Bвский, кого превозносят в Серебряном Рассвете, получает невероятные скидки на приобретение товаров! Скорее же воспользуйся своим преимуществом!', 'За 6 знаков Рассвета и 6 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.', 'Всего хорошего, $N. С тобой приятно иметь дело.', 'Выбирай с умом. Выбранный предмет обмену и возврату не подлежит.', NULL, NULL, 'Значок Серебряного Рассвета', 'Значок Алого ордена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9228, 'Легендарное боевое снаряжение – Восторг Рассвета', 'Приветствую тебя, $gбрат:сестра:. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?$B$Bвский, кого превозносят в Серебряном Рассвете, получает невероятные скидки на приобретение товаров! Скорее же воспользуйся своим преимуществом!', 'За 27 знаков Рассвета и 27 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.', '', NULL, NULL, NULL, 'Значок Серебряного Рассвета (27)', 'Значок Алого ордена (27)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9229, 'Кольцо Судьбы Рамаладни', 'Рамаладни был воином Братства и учеником верховного лорда Могрейна еще до возникновения Рассвета. Когда до него дошла весть о гибели Могрейна, гнев и ярость овладели его сердцем.$B$BПойми, $N, тот, кто позволяет гневу и жажде мести овладеть собой, теряет душу и разум. Именно это и произошло с Рамаладни, духом мести, вошедшим в Наксрамас, чтобы осуществить возмездие, и более не вернувшимся.$B$BОтправляйся в Наксрамас и найди то, что было некогда Рамаладни.', 'Идите в Наксрамас и найдите кольцо Судьбы Рамаладни. ', 'Это его кольцо! Но оно сломано... Других доказательств того, что ты и впрямь нашел Рамаладни, нет?$B$B*Корфакс морщится*$B$BЭто не лучшее, что ты мог найти. Впрочем, возможно, кольцо удастся восстановить.', 'Есть вести о Рамаладни?', NULL, NULL, 'Кольцо судьбы Рамаладни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9230, 'Ледяная хватка Рамаладни', 'Починить кольцо будет нелегко, $N. Видишь ли, оно было сделано из рун, которые можно найти только в сооружениях Плети – таких как Наксрамас. Мне также потребуются дополнительные материалы, однако основное затруднение представляют именно морозные руны. Принеси мне материалы, и я восстановлю кольцо в первозданном виде.', 'Принесите 1 морозную руну, 1 синий сапфир и 1 арканитовый слиток Корфаксу в часовню Последней Надежды в Восточные Чумные земли.', 'Сам Рамаладни не сделал бы лучше! Вот кольцо, как я и обещал.', 'Морозные руны можно найти в Наксрамасе.', NULL, NULL, 'Морозная руна', 'Синий сапфир', 'Арканитовый слиток', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9232, 'Не разгуляешься...', 'Ты, похоже, спишь и видишь себя героем Рассвета? Я видел, как летели головы лучших солдат под натиском шайки сброда Кел\'Тузада. Не понимаю, как такую бестолочь, как ты, можно вообще допускать в Наксрамас?$B$B*Вильгельм вздыхает*$B$BУвы, выбора у меня нет... попытаюсь хотя бы помочь.$B$BОмарион оставил мне всего один рецепт. Не разгуляешься... Я могу сделать несколько вариантов штанов – только принеси мне материалы.', 'Принесите 2 морозных руны, 2 сущности воды, 2 синих сапфира и 30 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли.', '*Вильгельм утирает пот со лба*$B$BИ-эх, тяжела и неказиста... Держи штаны, $С. По-крайней мере, сдохнешь во всем новом.', 'Ты ведь не встретил Омариона?', NULL, NULL, 'Морозная руна', 'Субстанция Воды', 'Синий сапфир', 'Требуется денег: 30');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9233, 'Руководство Омариона', 'Вильгельм!$B$BЕсли ты читаешь эти строки, то мечта твоя сбылась: я окочурился. Знай, что и на смертном одре я думал только о том, сколь негодный ремесленник из тебя вышел. К сожалению, податель сего вполне может отобрать у тебя звание худшего мастера.$B$BЧто касается настоящего руководства, в нем собраны все мои рецепты. Сделай для подателя сего все, что он попросит. Не сомневаюсь впрочем, что сдерешь ты втридорога, ибо канальей ты был, канальей и остался.$B$BС искренним презрением,$B$BОмарион.', 'Отнесите руководство Омариона ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли.', 'Да, похоже старина Омарион был совсем не в себе, когда писал письмо. Да мы ж с ним всегда были не разлей вода!$B$BНеважно, книга определенно расширяет мои возможности... Я смогу выполнить любой твой заказ – разумеется из предоставленных тобой материалов и за скро$Nю плату.', 'Это и в самом деле то, что я думаю?$B$B*У Вильгельма явно дрожат руки*', NULL, NULL, 'Руководство Омариона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9234, 'Рукавицы ледяной погибели', 'Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать рукавицы ледяной погибели. От тебя требуются лишь материалы и скромная плата за работу.', 'Принесите 5 морозных рун, 12 ториевых слитков, 2 арканитовых слитка, 2 сущности воды и 200 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Морозная руна', 'Ториевый слиток', 'Арканитовый слиток', 'Субстанция Воды');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9235, 'Наручи ледяной погибели', 'Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать наручи ледяной погибели. От тебя требуются лишь материалы и скромная плата за работу.', 'Принесите 4 морозных руны, 12 ториевых слитков, 2 арканитовых слитка, 2 сущности воды и 200 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли.', '', NULL, NULL, NULL, 'Морозная руна', 'Ториевый слиток', 'Арканитовый слиток', 'Субстанция Воды');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9236, 'Кираса ледяной погибели', 'Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать кирасу ледяной погибели. От тебя требуются лишь материалы и скромная плата за работу.', 'Принесите 8 морозных рун, 16 ториевых слитков, 2 арканитовых слитка, 4 сущности воды и 300 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли. Для выполнения задания вам также необходимо пользоваться полным доверием в Серебряном Рассвете.', '', NULL, NULL, NULL, 'Морозная руна', 'Ториевый слиток', 'Арканитовый слиток', 'Субстанция Воды');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9237, 'Ледовый плащ', 'Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать ледовый плащ. От тебя требуются лишь материалы и скромная плата за работу.', 'Принесите 5 морозных рун, 4 рулона рунической ткани, 2 сущности воды, 4 железошелковых паутины и 200 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли. Требуется превознесение в Серебряном Рассвете.', 'Получай свой заказ, $N! Все как ты просила.', NULL, NULL, NULL, 'Морозная руна', 'Рулон рунической ткани', 'Субстанция Воды', 'Железношелковая паутина');
