INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9243, 'Снежный мундир', 'Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать снежный мундир. От тебя требуются лишь материалы и скромная плата за работу.', 'Принесите 8 морозных рун, 16 кусков зачарованной кожи, 5 сущностей воды, 5 обработанных грубых шкур и 300 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли. Для выполнения задания вам также необходимо пользоваться полным доверием  в Серебряном Рассвете.', '', NULL, NULL, NULL, 'Морозная руна', 'Зачарованная кожа', 'Субстанция Воды', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9244, 'Наручи из ледяной чешуи', 'Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать наручи из ледяной чешуи. От тебя требуются лишь материалы и скромная плата за работу.', 'Принесите 4 морозные руны, 16 кусков толстой чешуи скорпида, 5 сущностей воды, 3 обработанных грубых шкуры и 200 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли.', 'Получай свой заказ, $N! Все как ты просила.', 'Ты достала материалы?', NULL, NULL, 'Морозная руна', 'Толстая чешуя скорпида', 'Субстанция Воды', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9245, 'Рукавицы из ледяной чешуи', 'Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать рукавицы из ледяной чешуи. От тебя требуются лишь материалы и скромная плата за работу.', 'Принесите 5 морозных рун, 16 кусков толстой чешуи скорпида, 5 сущностей воды, 3 обработанных грубых шкуры и 200 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли.', 'Получай свой заказ, $N! Все как ты просила.', 'Ты достала материалы?', NULL, NULL, 'Морозная руна', 'Толстая чешуя скорпида', 'Субстанция Воды', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9246, 'Кираса из ледяной чешуи', 'Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать кирасу из ледяной чешуи. От тебя требуются лишь материалы и скромная плата за работу.', 'Принесите 8 морозных рун, 24 куска толстой чешуи скорпида, 7 сущностей воды, 5 обработанных грубых шкур и 300 золотых ремесленнику Вильгельму в часовню Последней Надежды в Восточные Чумные земли. Требуется превознесение в Серебряном Рассвете.', 'Получай свой заказ, $N! Все как ты просила.', 'Ты достала материалы?', NULL, NULL, 'Морозная руна', 'Толстая чешуя скорпида (24)', 'Субстанция Воды', 'Обработанная грубая шкура');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9247, 'Зов Хранителя', '$N,$B$BВ прошлом тебе иногда приходилось браться за поручения в интересах Серебряного Рассвета, и всегда эти поручения оказывались выполнены в наилучшем виде. Ныне, в час великой нужды, мы вновь посылаем тебе зов.$B$BПожалуйста, $N, если ты желаешь вновь оказать нам помощь, явись к хранителю свитков в Часовню Последней Надежды, что в Восточных Чумных землях.', 'Отнесите письмо хранителя свитков самому хранителю в Часовню Последней Надежды в Восточные Чумные земли.', 'Мы в долгу перед тобой, $N, уже за то, что ты явился на наш призыв.Серебряный Рассвет надеется, что твой блистательный пример покажет всем, кто собрался здесь ради помощи нам, истинный путь к отражению угрозы со стороны Плети!', 'А, $N, я рад видеть тебя.', NULL, NULL, 'Письмо от хранителя свитков (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9248, 'Скромный подарок', 'Ишну-ала, $r. Покажи мне доказательство кончины лорда Совета Бездны и получишь в награду предмет, который поможет тебе справиться с киражами.', 'Принесите 1 скипетр бездны Аурель Золотой Лист из крепости Кенария в Силитусе. Требуется уважение со стороны Круга Кенария.', 'Анде\'торас-этиль. На моем родном языке это значит \"Да уменьшатся твои невзгоды\".$B$BПрими это кольцо и носи на здоровье!', 'Фэнду-дат-белоре? О, прости меня, $N, я не сразу тебя узнала. Ты принес мне скипетр?', NULL, NULL, 'Скипетр Бездны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9249, '40 купонов – пульт управления паровым танком', '', '', 'Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!', NULL, NULL, NULL, 'Подарочный купон ярмарки Новолуния', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9250, 'Основа Атиеша', 'Основа готова, и Атиеш собран почти полностью. Не хватает лишь набалдашника и основания. Да, и осталась небольшая проблемка – посох по-прежнему служит проводником зла Сарагаса в мир.$B$BНайди того, кто поможет тебе отыскать недостающие части, а заодно изгнать из посоха злого духа.', 'Найдите того, кто поможет отыскать недостающие части посоха и изгнать из него злого духа.', '', NULL, NULL, NULL, 'Основа Атиеша (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9251, 'Атиеш, оскверненный посох', 'Ты удивляешься, почему до сих пор $gжив:жива:? Ведь в твоих руках предмет, являющий собой средоточие зла. Ответ неочевиден, $N. Я делаю лишь то, что должно.$B$BКел\'Тузад сидит на троне Наксрамаса и вынашивает коварные планы... Он ищет то, что у тебя в руках, а у него в руках то, что ищешь ты.$B$BЧто же до острия посоха, то когда дворф Бранн Бронзобород отправился в Ан\'Кираж, оно было у него. Этого дворфа более нет в Ан\'Кираже, но основание Атиеша все еще там.$B$BЕсли тебе удастся отыскать оставшиеся части посоха, принеси их мне.', 'Анахронос из Пещер Времени, что в Танарисе, просит вас принести ему навершие и основание Атиеша.', 'В посохе заключено существо... Из другого мира.', 'Сейчас посоху опасно находиться в смертных руках.', NULL, NULL, 'Навершие посоха Атиеша', 'Основание Атиеша', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9252, 'Оборона деревни Легкий Ветерок', 'Нападения Плети происходят все чаще, $N! Мы уже с трудом держим оборону - а подкрепления из Луносвета что-то не видно и не слышно. Помоги нам оборонять деревню: перебей часть нежити, что бродит по Тропе Мертвых!', 'Убейте 4 гниющих мародеров и 4 темных призраков и вернитесь к следопыту Сарейн в деревню Легкий Ветерок, что в лесах Вечной Песни.', 'Спасибо тебе большое, $N. Работа у нас неблагодарная, но твоими стараниями она станет чуть-чуть полегче.', NULL, NULL, NULL, 'Гниющий мародер убито', 'Темный призрак убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9253, 'Хранитель рун Дериан', 'Ужесточение атак Плети заставляет меня предположить, что с одним из рунических камней, что стоят на границе с Призрачными землями, что-то неладно.$B$BМы использовали эти древние камни для защиты от нежити. Но большинство из них были уничтожены или пропали после нападения на Солнечный Колодец.$B$BСтупай по дороге на юг, в сторону Призрачных земель, и увидишь небольшую тропку, ведущую на запад. Там, у рунического камня, ты найдешь хранителя рун Дериана. Если что-то не в порядке, он об этом знает.', 'Поговорите с хранителем рун Дерианом в лесах Вечной Песни, близ границы с Призрачными землями.', 'Должно быть, тебя прислал кто-то из деревни Легкий Ветерок? Я знал, что рано или поздно помощь непременно подоспеет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9254, 'Упрямая ученица', 'Спасибо тебе за помощь, $N! Пока я буду все тут приводить в порядок, не окажешь ли мне услугу? Одна из моих бывших учениц предприняла весьма опасное исследование. Она отправилась в Восточное святилище, которое стоит посреди Тропы Мертвых.$B$BЯ опасаюсь за ее благополучие. Попробуй ее найти и убедить вернуться.', 'Поговорите с ученицей Мирведой в Восточном святилище в лесах Вечной Песни.', 'Очень приятно, что моя бывшая наставница обо мне не забывает. Жаль только, что она давно утратила веру в мой успех!$B$BНе пытайся уговорить меня вернуться к ней, не трать времени зря. Лучше помоги мне завершить исследование. Или уходи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9255, 'Исследовательские записи', 'Конечно, итоги моих исследований удручающи, но все же отрицательный результат – тоже результат. Прошу тебя, отнеси эти записи магистру Ландре Рассветной Страннице в деревню Легкий Ветерок, к западу отсюда.', 'Доставьте исследовательские записи магистру Ландре Рассветной Страннице в деревню Легкий Ветерок, что в лесах Вечной Песни.', 'Эти записи... шокируют. Если все это правда, то урон, нанесенный земле Тропы Мертвых, необратим!$B$BЯ немедленно сообщу об этом великому магистру! Тем больше причин нашему народу оставить этот мир и искать свою истинную судьбу в Запределье!', 'Вы что-то мне принесли?', NULL, NULL, 'Исследовательские записи (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9256, 'Деревня Легкий Ветерок', 'У меня для тебя есть еще одно задание, $N. Cледопыт Деголиен послал гонца в деревню Легкий Ветерок, чтобы выяснить подробности насчет нападения Презренных на находящуюся поблизости верфь. Он просит прислать подкрепление, но мы пока не можем этого сделать. Отыщи его и окажи посильную помощь.$B$BВ деревню Легкий Ветерок можно попасть, если идти по дороге, которая ведет от площади Соколиных Крыльев на юг. Удачи, $N!', 'Поговорите со следопытом Деголиеном в деревне Легкий Ветерок в лесах Вечной Песни.', 'Спасибо, что пришел, $N. Все хуже, чем мы думали. Презренные захватили причал Солнечного Паруса!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9257, 'Атиеш, большой посох Стража', 'Последнее задание будет самым трудным. Ты уже $gодолел:одолела: прихвостня Древнего Бога и Короля-лича, теперь же придется бросить вызов правой руке Саргераса.$B$BОтнеси посох в Стратхольм, к освященной земле, где пали величайшие рыцари Лордерона. Помести оскверененный посох на священную землю и готовься к схватке с неодолимой силой... Одержи верх над демоном, в чьей власти находится посох, и возвращайся ко мне.', 'Анахронос из Пещер Времени, что в Танарисе, просит вас отнести Атиеш, большой посох Стража, в Стратхольм и установить его на освященную землю. Одолейте силу, которая исторгнется из посоха, и вернитесь к Анахроносу.', '', NULL, NULL, NULL, 'Атиеш очищен', 'Атиеш, большой посох Стража (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9258, 'Выжженная роща', 'Вторжению Плети в новые земли всегда предшествует порча, проникающая в почву. В прошлом рунические камни, стоящие вдоль границы с Призрачными землями, хранили наш край от этой напасти.$B$BОднако самый западный из камней был уничтожен во время вторжения Плети. Это вынудило нас выжечь землю вокруг него, чтобы остановить распространение порчи.$B$BМоя сестра, Ларианна Речной Ветер, следит за Выжженной рощей. Ступай, отыщи ее – возможно, у нее найдется для тебя работа.', 'Найдите Ларианну Речной Ветер вблизи Выжженной рощи на юго-западе лесов Вечной Песни.', 'Тебя прислал мой брат? Да, у меня есть дело, в котором мне пригодится помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9259, 'Предатель Кровавого Паруса', '', '', 'Объявим же минуту молчания в честь павших товарищей, $N.$B$B*Предатель шайки Кровавого Паруса ухмыляется и подмигивает вам*$B$BОдно дело быть предателем, а другое – убивать своих... Это уж слишком позорно!', NULL, NULL, NULL, 'Шелковый материал', 'Красная краска', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9260, 'Что делает Плеть в Штормграде?', 'Войска Короля-лича стали лагерем у самых наших дверей. Мы не можем оставаться в бездействии! Выступишь ли ты на защиту Штормграда против этих проклятых захватчиков?$B$BТам, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху. Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно. Пока ты занимаешься этим, уменьши количество этих искажений природы, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!', 'Соберите три тусклых Некротических камня Плети, которые носит при себе нежить собравшаяся у Штормграда, и исследуйте светящиеся рунические круги вблизи лагеря Плети.', 'Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то. Я содрогаюсь при мысли о том, с каким извращенным разумом осуществляется связь посредством подобной магии. Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу.', 'Расследование уже завершено? Нет? Тогда за дело!', NULL, NULL, 'Тусклый некротический камень', 'Исследовать локацию', 'Исследуйте круги.', NULL);
