INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9267, 'Исцеление старых ран', '', '', 'Я рад, что ты решила исправиться, $N. Смотри, продолжай приносить нам все необходимое, мы так быстро не прощаем!', NULL, NULL, NULL, 'Льняной материал', 'Пустая колба', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9268, 'Морской бой', '', '', 'Даже и не думай, что этого хватит! Мы, гоблины, не слишком быстро забываем обиды!', NULL, NULL, NULL, 'Магическая ткань', 'Сильный плавень', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9269, 'Атиеш, большой посох Стража', 'Последнее задание будет самым трудным. Ты уже $gодолел:одолела: прихвостня Древнего Бога и Короля-лича, теперь же придется бросить вызов правой руке Саргераса.$B$BОтнеси посох в Стратхольм, к освященной земле, где пали величайшие рыцари Лордерона. Помести оскверененный посох на священную землю и готовься к схватке с неодолимой силой... Одержи верх над демоном, в чьей власти находится посох, и возвращайся ко мне.', 'Анахронос из Пещер Времени, что в Танарисе, просит вас отнести Атиеш, большой посох Стража, в Стратхольм и установить его на освященную землю. Одолейте силу, которая исторгнется из посоха, и вернитесь к Анахроносу.', '', NULL, NULL, NULL, 'Атиеш очищен', 'Атиеш, большой посох Стража (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9270, 'Атиеш, большой посох Стража', 'Последнее задание будет самым трудным. Ты уже $gодолел:одолела: прихвостня Древнего Бога и Короля-лича, теперь же придется бросить вызов правой руке Саргераса.$B$BОтнеси посох в Стратхольм, к освященной земле, где пали величайшие рыцари Лордерона. Помести оскверененный посох на священную землю и готовься к схватке с неодолимой силой... Одержи верх над демоном, в чьей власти находится посох, и возвращайся ко мне.', 'Анахронос из Пещер Времени, что в Танарисе, просит вас отнести Атиеш, большой посох Стража, в Стратхольм и установить его на освященную землю. Одолейте силу, которая исторгнется из посоха, и вернитесь к Анахроносу.', '', NULL, NULL, NULL, 'Атиеш очищен', 'Атиеш, большой посох Стража (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9271, 'Атиеш, большой посох Стража', 'Последнее задание будет самым трудным. Ты уже $gодолел:одолела: прихвостня Древнего Бога и Короля-лича, теперь же придется бросить вызов правой руке Саргераса.$B$BОтнеси посох в Стратхольм, к освященной земле, где пали величайшие рыцари Лордерона. Помести оскверененный посох на священную землю и готовься к схватке с неодолимой силой... Одержи верх над демоном, в чьей власти находится посох, и возвращайся ко мне.', 'Анахронос из Пещер Времени, что в Танарисе, просит вас отнести Атиеш, большой посох Стража, в Стратхольм и установить его на освященную землю. Одолейте силу, которая исторгнется из посоха, и вернитесь к Анахроносу.', '', NULL, NULL, NULL, 'Атиеш очищен', 'Атиеш, большой посох Стража (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9272, 'Костюм пирата', '', '', 'Гррр... Если тебе нравится общаться с нами, настоящими морскими волками, одевайся как мы! Ну же, надень что-нибудь приличное, пока я тебя под килем не протащил.Эта одежда подойдет тебе еще лучше, чем этому старому псу Красноглазому Бену. Он сгинул в чудовищной буре в море.Носи ее с честью, дружище!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9274, 'Духи утопших', 'Озеро к северу отсюда - обитель духов моих предков. Они блуждали там всегда, сколько себя помню, $N. Эти несчастные - жертвы трагической случайности, в результате которой десятки душ погибли и покоятся ныне на дне озера.$B$BЧто именно там произошло - никто уже и не помнит, но их неотвязные крики постоянно напоминают о постигшем их проклятии.$B$BЕсли ты $gготов:готова: взяться за это дело, то ступай к озеру и положи конец их страданиям, $N. Я был бы очень благодарен тебе... как, впрочем, и они.', 'Следопыт Кренн\'ан из Анклава Странников в Призрачных землях хочет, чтобы вы убили 8 мстительных и 8 ненасытных теней в водах ближнего озера.', 'Благодарю за помощь, $N. Мое сердце разрывалось на части от осознания того, что души моих предков не могут найти пристанище. Да обретут они, наконец, заслуженный покой.', NULL, NULL, NULL, 'Ненасытная тень убито', 'Мстительная тень убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9275, 'Острое блюдо', 'Я временно направлен к Странникам, чтобы попытаться решить их проблемы с троллями.$B$BУ меня есть немного сильного яда. Тролли, как тебе известно, являются живыми существами, стало быть, должны принимать пищу. Если мы приправим их пищу моим ядом... то получим предсказуемый результат!$B$BХочешь помочь нам избавиться от троллей Призрачной Сосны в Зеб\'Нове на юге? Их лагерь раскинулся по северную и южную стороны дороги на Зул\'Аман.', 'Отравите припасы троллей в лагере в Зеб\'Нове и возвращайтесь к аптекарю Венустусу в анклав Странников, что в Призрачных землях.', 'О, блестяще! Я знал, что $r-курьер – самый эффективный способ доставки яда! Если нам повезет, то тролли из племени Призрачной Сосны вскорости объедятся и лопнут от обжорства. И не будут больше сидеть бельмом на глазу у Странников, а я вернусь в Транквиллион.$B$BПриятно было иметь с тобой дело, $C!', NULL, NULL, NULL, 'Отравите балку для подвешивания сырого мяса', 'Отравите коптильную раму для мяса', 'Отравите раму для подвешивания свежей рыбы', 'Яд фармацевта');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9276, 'Нападение на Зеб\'Телу', 'С ресурсами тут у нас туго, $C, так что твоя помощь будет просто неоценима. Капитан поручил мне держать троллей Призрачной Сосны в постоянном напряжении. Мы устраиваем мелкие нападения до того дня, когда сможем одним жестоким ударом вышвырнуть их отсюда.$B$BНо пока нам пригодятся любые добровольцы, которые вызовутся сократить численность этих клятых троллей.$B$BКак думаешь – сможешь прогуляться на восток к Зеб\'Теле и малость пощекотать их?', 'Убейте 8 темных чародеев из племени Призрачной Сосны и 8 охотников за головами из племени Призрачной Сосны, затем возвращайтесь к Страннице Соланне в анклав Странников, что в Призрачных землях.', 'Славно, славно! Ты прекрасно справился с этим делом! Поищем теперь для тебя задачку потруднее.', NULL, NULL, NULL, 'Темный чародей из племени Призрачной Сосны убито', 'Охотник за головами из племени Призрачной Сосны убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9277, 'Нападение на Зеб\'Нову', 'Пришла пора устроить кое-что покруче. В Зеб\'Нове, что к югу отсюда, угнездились более могучие тролли Призрачной Сосны. Мы постоянно пытаемся свести их численность к минимуму, а потому я отправляю тебя туда. Учини им кровавую баню любыми средствами.$B$BНу, что скажешь, $N? $gГотов:Готова: разобраться еще с горсткой троллей?', 'Убейте 10 повелителей животных из племени Призрачной Сосны, 10 проклинателей из племени Призрачной Сосны и возвращайтесь к Страннице Соланне в анклав Странников, что в Призрачных землях.', 'Невероятно! Нет, тебе надо поговорить с нашим капитаном насчет вступления в ряды Странников.$B$BЛадно, Мельтемар, ты дал нам передышку, достаточную для того, чтобы собраться с силами в здешних краях. Благодаря тебе троллей тут почти не осталось! Может, теперь мы сможем объединиться с Транквиллионом и напасть на Смертхольм?$B$BДумаю, ты заслужил небольшую награду. Выбирай.', NULL, NULL, NULL, 'Повелитель животных из племени Призрачной Сосны убито', 'Мастер проклятий из племени Призрачной Сосны убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9278, 'Привет!', 'Добро пожаловать в мир World of Warcraft!$B$BВ знак особой благодарности за приобретение коллекционного издания вы получаете подарок! Передайте этот подарочный сертификат Джалейл на Лазурной заставе. Взамен вы получите маленького спутника, который будет сопровождать вас на пути к славе.$B$BЕще раз благодарим вас и желаем приятного времяпровождения в мире World of Warcraft!', 'Принесите подарочный сертификат Лазурной заставы Джалейл.', '', NULL, NULL, NULL, 'Подарочный сертификат Лазурной заставы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9279, 'Тебе удалось выжить!', 'Не обращай внимания на мои раны, $gбрат:сестра:. Чудо, что мы вообще живы!$B$BЯ и не чаял, что ты уцелеешь; еще бы - несколько недель без сознания!$B$BЧто-то случилось, и \"Экзодар\" потерпел крушение. Многие погибли.$B$BХорошо, что ты $gжив:жива:, $N. Если ты в наших рядах, то вскоре все мы окажемся в безопасности! Проэнитус хотел поговорить с тобой, как только ты проснешься. Он ждет тебя у подножия холма. Ступай по тропе на юго-запад.', 'Поговорите с Проэнитусом на месте крушения в долине Аммен.', 'Клянусь бессмертной душой, я рад видеть тебя, $N! Не знаю, что стряслось с Экзодаром. Кажется, в живых остались лишь те, кто был в этой части корабля.$B$BЕсли мы хотим спасти других выживших, время у нас на исходе!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9280, 'Исцеляющие кристаллы', 'Первым делом надо зарядить исцеляющие кристаллы. И побыстрее!$B$BК сожалению, в настоящий момент для этого придется добывать кровь долинных мотыльков, она отлично подойдет.$B$BМотыльки водятся во всей долине, особенно в северо-западной ее части.', 'Добудьте 8 фиалов с кровью мотыльков из долинных мотыльков и принесите их Проэнитусу на место крушения в долине Аммен.', 'Жаль, что приходится обменивать жизни этих существ на наши – подобная жестокость чужда духу дренеев. Зато собранная кровь наполнит исцеляющие кристаллы, так что мотыльки погибли не зря.', 'Тебе удалось набрать достаточно крови мотыльков для создания исцеляющих кристаллов? Время не ждет, раненых очень много!', NULL, NULL, 'Фиал с кровью мотылька', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9281, 'Расчистка пути', 'Магистр Кендрис послал меня истребить всех враждебно настроенных существ в округе. Магистр намерен основать здесь что-то вроде форпоста против Плети, как только обстановка будет позволять.$B$BЕсли я чему-то и научился у него, так это перекладывать ответственность на чужие плечи – особенно когда существует угроза для жизни!$B$BЕсли возьмешься истребить больших пауков-прядильщиков и светлопалых опустошителей к западу и югу отсюда, я хорошо заплачу тебе.', 'Ученик Ворэль из поместья Андилиен в Призрачных землях желает, чтобы вы убили 10 больших пауков-прядильщиков и 10 светлопалых опустошителей.', 'Спасибо за помощь, $N. Мне даже думать страшно было о том, чтобы отправиться в леса так близко от Смертхольма.', NULL, NULL, NULL, 'Большой паук-прядильщик убито', 'Светлопалый опустошитель убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9282, 'Анклав Странников', 'Магистры и Странники не всегда сходятся во мнениях, $N. Однако когда дело касается Дар\'Хана, мы едины в том, что необходимо найти способ победить его и разбить его легионы.$B$BСледопыт Винна в анклаве Странников к северо-востоку отсюда нашла важную информацию о нашем противнике. Поговори с ней и узнай, сможешь ли ты чем-нибудь помочь.', 'Магистр Кендрис из святилища Солнца просит вас поговорить со следопытом Винной в анклаве Странников в Призрачных землях.', 'Тебя прислал Кендрис? Возможно, у меня найдется задание для тебя, $C.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9283, 'Помощь выжившим', 'Мы снова зарядили исцеляющие кристаллы, но есть и другие способы помочь раненым. Все дренеи наделены даром Наару - возможностью лечить. Воспользуйся этой способностью и исцели одного из выживших в катастрофе.$B$BБольшая часть раненых находится на западе и на северо-западе отсюда, хотя в результате крушения нас разбросало по всей долине.$B$BВсе выжившие дренеи подверглись воздействию радиоактивных кристаллов, поэтому их легко узнать по красному свечению.$B$BСпаси их, $N.', 'Воспользуйтесь даром наару и исцелите одного из выживших дренеев в долине Аммен. Затем вернитесь к Зальдууну на место крушения в долине Аммен.', 'Хвала Свету! Лишь настоящий герой способен на такие подвиги! Дренеи обязаны тебе своей жизнью!$B$BПожалуйста, возьми этот мешочек для припасов. Думаю, он тебе больше пригодится.', NULL, NULL, NULL, 'Спасено выживших дренеев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9284, 'Тест группы Алдора', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9285, 'Тест группы Консорциума', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9286, 'Тест группы Провидцев', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9287, 'Наставник паладинов', '', '', 'Я ряд, что ты пожелал обратиться ко мне. В прошлом я занимался обучением молодых паладинов, только что вступивших в наш орден. Я снова принял на себя эту почетную обязанность. Говорят, ты стремишься к Свету. Это честь для меня - помочь тебе сделать первые шаги на этом пути.Вот мой первый урок...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9288, 'Обучение охотника', '', '', 'Хорошо, что ты пришла ко мне. Я давно занимаюсь обучением молодых охотников, и в этом мире не собираюсь изменять своему призванию. Я к тебе давно присматриваюсь, и с радостью помогу сделать первые шаги на пути охотника.Приступим?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9289, 'Обучение воина', '', '', 'Хорошо, что ты ищешь моей помощи. Я обучаю молодых воинов уже несколько сотен лет, и знаю, с чего лучше начать. В тебе я вижу задатки великого воина, но для этого придется хорошенько поработать. Слушай внимательно.Ты готов приступить к обучению?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9290, 'Обучение мага', '', '', 'Хорошо, что ты ищешь моей помощи. Нам предстоит много работы.Я обучаю новичков более сотни лет, и уже сроднилась с тайной магией, а также магией Льда и Огня. Хочешь, я передам тебе часть своих знаний?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9291, 'Обучение жреца', '', '', 'Ты явилась ко мне за знаниями, и это вселяет в меня большую надежду. Хотя большую часть моего времени отнимает забота о раненых, я смогу выкроить несколько минут и помочь тебе сделать первые шаги по пути жреца. Пути Света - высочайшие из всех путей, и я не сомневаюсь, что ты далеко пойдешь!Когда решишь приступить к обучению, обращайся ко мне.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9292, 'Треснувший некротический кристалл', 'На трупе павшего поганища вы обнаруживаете треснутый кристалл, медленно пульсирующий некротической энергией.', 'Отнесите треснувший некротический кристалл лейтенанту Оррину, находящемуся за воротами Штормграда.', 'Хм, так это было на трупе одного из этих мерзостных поганищ?$B$BМы слышали о лагерях-некрополях, призванных Плетью. Я подозреваю, что они хотят создать такой лагерь в Штормграде. Хорошо что им это не удалось.', 'Тебе что-нибудь нужно?', NULL, NULL, 'Треснутый некротический кристалл (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9293, 'То, что должно быть сделано...', 'Один из обломков кристаллов корабля упал в озеро неподалеку отсюда и заразил его радиацией. В результате многие растения и животные долины Аммен подверглись различным мутациям.$B$BУ меня есть идея, как излечить озеро, но сначала я должна заполучить образцы корнехлестов-мутантов и проанализировать их. Их можно найти на западе от полей Аммен.$B$BПоможешь мне, $C?', 'Соберите 10 образцов корней корнехлестов и отнесите их ботанику Таэрикс на место крушения в долине Аммен.', 'О, спасибо тебе, $C!$B$BПока ты ходил за образцами, я ухитрилась собрать кое-какое оборудования для анализов. Подожди немного...', 'Все образцы должны быть в хорошем состоянии, иначе не получится провести качественный анализ.$B$BВремени у нас в обрез, $C!', NULL, NULL, 'Образец корнехлеста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9294, 'Исцеление озера', 'Если будет на то воля Света, этот состав сработает! Я хочу, чтобы ты $gобработал:обработала: им Серебристое озеро на юге. Надеюсь, нам удастся очистить воду от радиоактивного заражения.$B$BПодплыви поближе к кристаллу и вылей туда нейтрализующее вещество. Не беспокойся, ты не успеешь заразиться.', 'Вылейте нейтрализующее вещество в воду рядом с радиоактивным кристаллом силы на месте крушения в долине Аммен, затем вернитесь к ботанику Таэрикс.', 'Судя по твоему описанию, нейтрализующее вещество сработало! Интересно, надолго ли его хватит; по-хорошему, нужно удалить весь кристалл из озера.$B$BСпасибо, $N! Я скажу Тедону, чтобы он поскорее испытал нейтрализующее вещество на пойманных зверях.', 'Чем скорее ты растворишь нейтрализующее вещество в озере, чем меньше местных зверей, приходящих на водопой, мутируют. Да и мы сами тоже!$B$BЖаль, что я не в силах помочь бедным тварям, уже пораженным радиацией. Ах, если бы уцелело оборудование из моей лаборатории!', NULL, NULL, 'Вылейте нейтрализующее вещество', 'Нейтрализующее вещество', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9295, 'Письмо с фронта', 'Это письмо найдено у одного из множества приспешников Плети, убитых вами. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды захотел бы на него взглянуть...', 'Отнесите порванное письмо хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.', 'Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.$B$BИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...$B$BСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.', 'Да? Что у тебя там?', NULL, NULL, 'Порванное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9299, 'Записка с фронта', 'Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...', 'Отнесите потертую записку хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.', 'Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.$B$BИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...$B$BСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.', 'Да? Что у тебя там?', NULL, NULL, 'Потертая записка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9300, 'Страничка с фронта', 'Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...', 'Отнесите разорванную страницу хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.', 'Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.$B$BИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...$B$BСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.', 'Да? Что у тебя там?', NULL, NULL, 'Разорванная страница (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9301, 'Конверт с фронта', 'Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...', 'Отнесите конверт, запятнанный кровью, хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.', 'Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.$B$BИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...$B$BСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.', 'Да? Что у тебя там?', NULL, NULL, 'Запятнанный кровью конверт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9302, 'Послание с фронта', 'Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...', 'Отнесите смятое послание хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.', 'Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.$B$BИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...$B$BСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.', 'Да? Что у тебя там?', NULL, NULL, 'Смятое послание (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9303, 'Прививка', 'Жаная должна починить излучатель, и ей нужны запчасти. Без нашей помощи ей не обойтись. Таэрикс приготовила особую прививку для совунов с Совиных холмов, населяющих территорию, на которой особенно много обломков корабля.$B$BПостарайся подобраться поближе к незараженным совунам и воспользуйся кристаллом. К сожалению, остальных придется убить. Совуны живут в Совиной чаще и Совиных холмах на юго-востоке.', 'Сделайте прививку шести совунам с Совиных холмов при помощи особого кристалла. Затем вернитесь к воздаятелю Алдару на место крушения в долине Аммен.', 'Большая часть совунов привита, и мы сможем сосредоточить усилия на том, чтобы выбраться отсюда, не беспокоясь об уничтожении совунов.$B$BВыбери, что тебе больше подходит. Хорошая работа заслуживает награды!', 'Чем быстрее мы очистим Совиные холмы, тем быстрее Жаная сможет взяться за работу.', NULL, NULL, 'Привейте совунов с Совиных холмов', 'Прививочный кристалл (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9304, 'Документ с фронта', 'Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...', 'Отнесите испачканный документ хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.', 'Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.$B$BИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...$B$BСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.', 'Да? Что у тебя там?', NULL, NULL, 'Испачканный документ (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9305, 'Запасные части', 'Мы обнаружили среди обломков корабля поврежденный голографический передатчик. Если его починить, можно попытаться связаться с выжившими дренеями за пределами долины Аммен.$B$BДля ремонта нужны запчасти, которые можно вытащить из других обломков, валяющихся в округе, но их уже утащили местные совуны.$B$BОтправляйся на юг, в Совиную чащу и Совиные холмы, и найди запасные части.', 'Соберите 4 запчасти для передатчика и отнесите их технику Жанае на место крушения в долине Аммен.', 'Дай-ка поглядеть.$B$BДа, эти части подойдут. Спасибо, $N. Передатчик - сложное устройство, так сходу его не починишь. Я сообщу тебе, когда закончу работу.$B$BПока что ты можешь заглянуть к воздаятелю Алдару, может, ему нужна твоя помощь.', 'Если мы соберем все детали, я смогу починить передатчик. Если повезет, нам даже найдется, с кем поговорить по нему.', NULL, NULL, 'Запчасть для излучателя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9309, 'Пропавший разведчик', 'У нас есть несколько сообщений о том, что на Хребте Теней творится что-то неладное.$B$BНичего хорошего в этом нет: мы ведь думали, что разведчики тщательно обследовали окрестности. Впрочем, один из них еще не вернулся.$B$BОтправляйся на юго-запад, на другую сторону Серебристого озера и найди Толаана. Узнай, что его задержало.', 'Найдите Толаана у хребта Теней в долине Аммен и поговорите с ним.', 'Помоги... Эльфы крови! Я... попал в засаду. Мне... недолго осталось.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9310, 'Тусклый некротический кристалл', 'На трупе павшей твари вы находите кристалл, излучающий тусклую некротическую энергию.', 'Отнесите тусклый некротический кристалл лейтенанту Рукагу во внутренний двор Подгорода.', 'Это было у одной из тварей, напавших на город?$B$BМы слышали о лагерях-некрополях, призванных Плетью. Я подозреваю, что они хотят создать такой лагерь в Подгороде. Впредь мы должны быть бдительными.', 'Я могу чем-нибудь помочь?', NULL, NULL, 'Тусклый некротический кристалл (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9311, 'Шпион эльфов крови', 'У меня есть план. Мы должны убить их главаря. Тогда, может быть, им придется отступить. В конце концов, наша задача – выиграть время на ремонт остатков корабля.$B$BУбей геодезиста, а потом расскажи обо всем воздаятелю Алдару – он должен быть в курсе.', 'Убейте геодезиста Кандресс и расскажите о случившемся воздаятелю Алдару на месте крушения в долине Аммен.', 'Спасибо тебе за то, что ты убил лидера эльфов крови, $N. Можешь не сомневаться, с остальными эльфами мы скоро разберемся.$B$BВыбери в награду любое оружие.', NULL, NULL, NULL, 'Геодезист Кандресс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9312, 'Излучатель', 'Пока ты $gбродил:бродила: по Хребту Теней, Жаная занималась голографическим излучателем. Тебе стоит поговорить с ней.', 'Поговорите с техником Жанаей на месте крушения в долине Аммен.', 'Получилось! Получилось! Кажется, я починила излучатель! Сейчас я активирую последний кристалл - и дело в шляпе.$B$BСмотри на излучатель, $N. Похоже, он заработал... Кто-то появляется!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9313, 'На Лазурную заставу', 'Ради всего святого, $N, отправляйся на Лазурную заставу и поговори с Дивууном!$B$BС нашего островка есть узкая тропа на запад. Иди по ней, перейди через Хрустальную реку, и окажешься в другой части острова. Если идти дальше, не сходя с дороги, она приведет тебя на Лазурную заставу.$B$BМожет быть, они помогут нам и снабдят нас припасами? Остальные последуют за тобой, когда смогут.$B$BСпасибо, без тебя нам не справиться!', 'Поговорите с техником Дивууном на Лазурной заставе на острове Лазурной Дымки.', 'О, рад тебя видеть! Хорошо, что удалось починить оба излучателя, иначе бы нам не отыскать друг друга. Не беспокойся, мы позаботимся о том, чтобы в долину Аммен отправили побольше припасов и войск.$B$BКстати говоря, раз уж ты здесь, пойди, познакомься с другими обитателями форпоста. Дел здесь полно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9314, 'Вести с Лазурной заставы', '$C! На меня напала пара зверей-мутантов и ранила меня в ногу.$B$BПосле того как нам удалось связаться с Жанаей, меня отправили с Лазурной заставы на разведку. Пожалуйста, поговори вместо меня c корчмарем Челланой. Ей нужно знать, скольких беженцев ждать в нашем поселении. Перейди Хрустальную реку и иди по дороге до самой Лазурной заставы.$B$BОбязательно скажи ей, что тебе нужно где-то остановиться.', 'Поговорите с корчмарем Челланой на Лазурной заставе на острове Лазурной Дымки.', 'О, должно быть, ты один из выживших, о которых в последнее время столько говорят!$B$BХорошо, что ты пришел. Не беспокойся, мы отправим кого-нибудь на помощь Аэуну.$B$BЯ с радостью послушаю, как умудрились выжить дренеи в соседней долине! Ты храбрец, раз решился пойти сюда.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9315, 'Анок\'сутен', 'Подойди поближе... я умираю...$B$BМеня послали сюда... убивать этих нерубов, но Вандрил... не знал... что у них есть... предводительница...$B$B*Умирающий эльф крови кашляет кровью.*$B$BНайди и убей... Анок\'сутен. Приведи помощь. Она рыщет вокруг... деревни Солнечной Короны...', 'Убейте Анок\'сутен и возвращайтесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.', 'Прости за неточные разведданные, $C. Знай я раньше об этой Анок\'сутен, то непременно тебе сказал бы.$B$BНас тут слишком мало, и многое просто проскальзывает меж пальцев!', NULL, NULL, NULL, 'Анок\'сутен убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9317, 'Освященное точило', '', '', 'Спасибо, $N. Вот освященное точило. Используй его с толком.', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9318, 'Благословленное волшебное масло', '', '', 'Надеюсь, этот предмет пригодится тебе в грядущих битвах.', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9319, 'Свет в темных местах', 'Мы не единственные, кто справляет сегодня праздник, $N. Все создания, все народы возжигают пламя. Даже в самых темных уголках сегодня горят огни.$B$BЕсли хочешь увидеть их своими глазами, спустись в глубины. Отыщи костры, горящие в Стратхольме, Некроситете, у огров в Забытом Городе и в залах самого пика Черной горы. Я буду ждать твоего возвращения.', 'Найдите костры, размещенные в пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени.', 'Твоя сущность поет, переполненная энергией найденного тобой пламени, Поняха. Огонь, с которым тебе пришлось столкнуться, весьма силен, и тот, кто наделен нужным знанием, может обуздать эту силу...$B$B*Хранитель праздничных костров бормочет заклинание на странном, загадочном языке, затем достает сияющую бутыль.*$B$BА, вот. Пусть это озарит твой путь, куда бы он ни лежал.', NULL, NULL, NULL, 'Пламя Забытого Города', 'Пламя пика Черной горы', 'Пламя Стратхольма', 'Пламя Некроситета');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9320, 'Гигантский флакон с зельем маны', '', '', 'Вот, $N. Но соблюдай осторожность. Нас не так много, чтобы мы могли позволить себе большие потери в бою.', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9321, 'Гигантский флакон с лечебным зельем', '', '', '', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9322, 'Костры Калимдора', 'Праздник Огненного солнцеворота отмечается повсюду в Азероте, и различные регионы Калимдора – не исключение. Похоже, тебе приходилось много путешествовать, и у тебя есть опыт в странствиях. $B$BПраздник Середины лета нельзя оценить должным образом, пока не увидишь горячие огни синего цвета. Зажигаются костры в холодных западных регионах Зимних Ключей, в северо-восточной Азшаре, возле Покоя Доблестных в пустошах Силитуса и у входа в обширный ркатер Ун\'Горо. Возвращайся по завершении путешествия.', 'Посетите лагеря праздника Огненного солнцеворота, размещенные в Азшаре, Силитусе, Кратере Ун\'Горо и Зимних Ключах, затем вернитесь к хранителю праздничного пламени.', 'Твой дух сияет жаром костров Калимдора. Разве это пламя не воодушевляет тебя?$B$BКогда тебя покинут силы, быть может, это поможет тебе вновь возжечь этот жар.', NULL, NULL, NULL, 'Пламя Азшары', 'Пламя Силитуса', 'Пламя Ун\'Горо', 'Пламя Зимних Ключей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9323, 'Костры Восточных королевств', 'Огненный праздник распространился по всем землям, $C. Нет ни единого уголка, куда не проник бы жар этого празднества, а самые сильные огни пылают ярко-синим цветом. Найди их.$B$BОдин из них можно обнаружить к северу от пика Черной горы. Другие размещаются в глубине территории Восточных Чумных земель возле полуразрушенного города, вдоль дороги, ведущей на утесы гористых Внутренних земель, и на пути к Темному порталу в Выжженных землях.$B$BВозвращайся, когда завершишь свое путешествие.', 'Посетите лагеря Праздника Огня, размещенные в Выжженных землях, Восточных Чумных землях, во Внутренних землях и Тлеющем ущелье, затем поговорите с хранителем праздничного пламени.', 'А, вот и ты. Чуть больше усталости, чуть больше пыли, но внутри сияет свет! В это время года жар касается нас всех и объединяет нас. Сама твоя суть сияет силой костров, которых тебе довелось касаться.$B$BО, но в эти дни просвещение считается довольно ничтожным вознаграждением за выполнение задания, как мне кажется. Так прими это и наслаждайся праздником.', NULL, NULL, NULL, 'Пламя Выжженных земель', 'Пламя Чумных земель', 'Пламя Внутренних земель', 'Пламя Тлеющего ущелья');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9324, 'Похищение пламени Оргриммара', 'Это пламя, похищенное из сердца Оргриммара, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...', 'Верните Пламя Оргриммара хранителю мудрости Праздника.', 'Что это? Если я не ошибаюсь, это пламя добыто из самого сердца Оргриммара! Свирепая сила, наполняющая души орков и троллей, чувствуется в неистовом жаре этого огня. Какое чудесное добавление к коллекции! И сколь велика твоя отвага, позволившая тебе пробраться в самое логово врага, дабы заполучить священное пламя!$B$BИнтересно, какая сила таится в других городах?..', 'Ты поистине светишься, $C. Что у тебя там?', NULL, NULL, 'Пламя Оргриммара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9325, 'Похищение пламени Громового Утеса', 'Это пламя, похищенное у шамана Громового Утеса, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...', 'Верните Пламя Громового Утеса хранителю мудрости Праздника.', 'Если я не ошибаюсь, это пламя добыто на уступах Громового Утеса! Как оно поет, исполненное силы духа! Твою ловкость можно назвать непревзойденной, $N. Прими это как малую плату за свое мастерство. Если бы у нас было пламя из всех трех городов...', 'Ты поистине светишься, $C. Что у тебя там?', NULL, NULL, 'Пламя Громового Утеса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9326, 'Похищение пламени Подгорода', 'Это пламя, похищенное из руин над Подгородом, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...', 'Верните Пламя Подгорода хранителю мудрости Праздника.', 'Хм... Какой странный огонь! Он слаб, почти угасает, но его жар силен. Ты говоришь, он из Подгорода? Поразительно. Кто знает, чего мы можем достичь, заполучив пламя из всех трех городов?', 'Ты поистине светишься, $R. Что у тебя там?', NULL, NULL, 'Пламя Подгорода (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9327, 'Отрекшиеся', 'Понимаю, что это звучит странно, но Отрекшиеся готовы помогать нам. Поговори с их предводителем, верховным вершителем Мавреном. Он в башне на западной окраине города.$B$BИ, $C, после разговора с ним возвращайся ко мне – у меня есть одно неприятное дело, которое требует немедленного решения!', 'Поговорите с верховным вершителем Мавреном в Транквиллионе, что в Призрачных землях.', 'Я понимаю, что для тебя мы выглядим чудовищами, но уверяю, мы не хотим зла вашему народу. У нас общий враг – предатель Дар\'Хан! Он вернулся и ныне командует Плетью, чьи полчища вторглись в эти края из его логова, Смертхольма, что на юге.$B$BНаша предводительница, леди Сильвана Ветрокрылая, родом из этих мест, а при жизни она была эльфийкой! У Дар\'Хана перед ней должок, и она жаждет его смерти не меньше, чем вы.$B$BВместе мы разобьем его, $C!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9328, 'Герой син\'дорай', '$N, начинается новая глава в истории эльфов крови. Наконец-то мы вернем свои земли! А заодно и укрепим отношения с Сильваной и ее союзниками.$B$BОтнеси голову предателя лорду-регенту Лор\'темару Терону в Луносвет и расскажи о том, что произошло.', 'Принесите голову Дар\'Хана Лор\'темару Терону в Луносвет.', 'М-да... Не ожидал увидеть это лицо так скоро.$B$BЧто ж, ты принесла мне весьма радостную весть, Котейшество.', 'Ты хочешь поговорить со мной, $C? Не припомню, чтобы назначал тебе встречу.', NULL, NULL, 'Голова Дар\'Хана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9329, 'Отрекшиеся', 'Понимаю, что это звучит странно, но Отрекшиеся готовы помогать нам. Поговори с их предводителем, верховным вершителем Мавреном. Он в башне на западной окраине города.$B$BИ, $C, после разговора с ним возвращайся ко мне – у меня есть одно неприятное дело, которое требует немедленного решения!', 'Поговорите с верховным вершителем Мавреном в Транквиллионе, что в Призрачных землях.', 'Мы, Отрекшиеся, пришли сюда потому, что у нас с вами общий враг – Дар\'Хан! Он вернулся и ныне командует Плетью, чьи полчища вторглись в эти края из его логова, Смертхольма, что на юге.$B$BНаша предводительница, леди Сильвана Ветрокрылая, родом из этих мест, при жизни она была эльфийкой! У Дар\'Хана перед ней должок, и она жаждет его смерти не меньше, чем вы.$B$BВместе мы разобьем его, $C!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9330, 'Похищение пламени Штормграда', 'Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...', 'Верните Пламя Штормграда Праздничному Сказителю.', 'И это ярко горящее пламя... ты говоришь, оно из Штормграда? Замечательно! Должно быть, это было славное приключение! Конечно же, я заплачу тебе за это. Если ты найдешь еще что-нибудь подобное, обязательно приходи поговорить со мной.', 'Ты поистине светишься, $R. Что у тебя там?', NULL, NULL, 'Пламя Штормграда (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9331, 'Похищение пламени Стальгорна', 'Это пламя, похищенное из сердца Стальгорна, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...', 'Верните Пламя Стальгорна Праздничному Сказителю.', 'Это сильное пламя, должно быть, явилось из залов Стальгорна; оно столь же неукротимо, как сами дворфы. Отличная добыча, Профессия. Если бы у меня был огонь из других городов... а, неважно. Вот твоя плата.', 'Ты поистине светишься, $R. Что у тебя там?', NULL, NULL, 'Пламя Стальгорна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9332, 'Похищение пламени Дарнаса', 'Это пламя, похищенное с берегов Тельдрассила, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...', 'Верните пламя Дарнаса праздничному сказителю.', 'Этот огонь полон древней скорби, $N. Ты говоришь, он добыт от корней Тельдрассила? Невероятно! Вот награда за твое мастерство. Возвращайся ко мне, если найдешь еще что-либо подобное; возможно, у меня найдется применение этому.', 'Ты поистине светишься, $R. Что у тебя там?', NULL, NULL, 'Пламя Дарнаса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9333, 'Перчатки Серебряного Рассвета', '', '', 'Хорошая работа, $N. Возьми выбранные тобой защитные перчатки в благодарность за твои усилия.', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9334, 'Благословленное волшебное масло', '', '', 'Надеюсь, этот предмет пригодится тебе в грядущих битвах.', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9335, 'Освященное точило', '', '', 'Спасибо, $N. Вот освященное точило. Используй его с толком.', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9336, 'Гигантский флакон с лечебным зельем', '', '', '', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9337, 'Гигантский флакон с зельем маны', '', '', 'Вот, $N. Но соблюдай осторожность. Нас не так много, чтобы мы могли позволить себе большие потери в бою.', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9338, 'Верность Кругу Кенария', '', '', 'Работать с тобой – честь для нас, $N. Благодаря твоим усилиям, мы преодолеем все трудности.', NULL, NULL, NULL, 'Кенарийский знак бойца', 'Кенарийский знак тыловика', 'Кенарийский знак тактика', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9339, 'Награда вора', 'Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...', '', 'Сегодняшние твои деяния свидетельствуют сами за себя, Профессия.$B$BЯ мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости. Пусть он озарит твой путь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9340, 'Глубокий Разлом', 'Альянс обложил нас со всех сторон. Пилигримы син\'дорай все идут и идут из Азерота, так что мы должны найти дорогу, о которой наши вездесущие враги не прознают.$B$BЯ подумал немного, и кое-что придумал. Мы проложим тайный путь через Глубокий Разлом.$B$BДа, там кишмя кишат горные камнедеры, но они всего лишь звери и быстро научатся нас бояться. Отправляйся к Глубокому Разлому и убей всех камнедеров, которых встретишь. Думаю, остальных это напугает.', 'Ступайте на восток от Соколиного дозора, к Глубокому разлому, и убейте 8 детенышей камнеруба и 3 камнерубов-вожаков по приказу капитана следопытов Венн\'рена.', 'Неплохо, $N. Это научит камнедеров держаться от нас подальше.', NULL, NULL, NULL, 'Детеныш камнеруба убито', 'Камнеруб-вожак убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9341, 'Гербовая накидка Серебряного Рассвета', '', '', 'Возьми эту гербовую накидку и носи его с гордостью. Быть может, твой пример побудит и других взяться за оружие, чтобы поддержать нас в борьбе против Плети.', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9342, 'Хищный землерой', 'Будто бы ган\'аргов нам было недостаточно, так теперь еще гигантские земляные черви!$B$BТраллмарскому гарнизону не до нас, он сражается с Легионом, так что предполагается, что мы разберемся здесь сами. В смысле, я и вот эти.$B$BШтейгер кивает на спящих батраков.*$B$BМожно подумать, много от них пользы.$B$BЯ лучше тебе заплачу, если ты очистишь рудник от червяков.', 'Убейте 15 хищных землероев по просьбе штейгера Разлкраза. Эти черви предпочитают нападать неожиданно, из-под земли.', '', NULL, NULL, NULL, 'Хищный землерой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9343, 'Гербовая накидка Серебряного Рассвета', '', '', '', NULL, NULL, NULL, 'Некротическая руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9344, 'Поспешный отъезд', 'Приветствую, $N. Запределье – очень опасное место, многие из нашей экспедиции это быстро поняли. Боюсь, юный Грелаг может убедиться в этом на собственном опыте.$B$BГрелаг очень способный ученик, но ему не хватает терпения. Он так увлечен историей своего народа, что подчас забывает об опасностях, которые поджидают нас в настоящем.$B$BОн ушел с Заставы Хребтолома, не подозревая ни о Легионе, ни об орках Скверны, которые шарятся по окрестностям. Как бы с ним чего-нибудь не случилось.', 'Разыщите Грелага, ученика провозвестницы Регулкут.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9345, 'Изготовление мази', 'Я не добрался даже до Зет\'Гора, как патруль Легиона меня засек. Я побежал, надеясь укрыться в башне неподалеку, но одна из гончих Скверны вцепилась мне под колено.$B$BСбежать-то я сбежал, но с ногой творится что-то ужасное. Каменный страж Амбелан нашел меня и перетащил сюда.$B$BМне надо хоть немного подлечиться. В Долине Костей, к северу отсюда, растет трава шиполист. Я смогу сделать из нее обезболивающую мазь, которая позволит мне ходить.', 'Соберите 12 листьев пламенного шиполиста и возвращайтесь к Грелагу на Заставу Хребтолома.', 'Это должно помочь. Сейчас я приготовлю мазь, а затем наложу шину. В таком виде кое-как до Траллмара доковыляю. Могу представить, что скажет провозвестница Регулкут, когда меня увидит.$B$B*Грелаг тяжело вздыхает.*$B$BСпасибо тебе за помощь, $N. У меня осталось несколько листьев гребнелиста, возьми с собой, если хочешь. Как знать, может, и пригодятся.', 'Ты принес листья?', NULL, NULL, 'Пламенный шиполист', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9346, 'Зловепрь – птица гордая', 'Зловепрь – птица гордая! Не сунешь в катапульту – не полетит!$B$B*Командир стражи Кранк хохочет.*$B$BПосле атаки на лагеря Легиона у нас закончились боеприпасы для катапульт. Ничего, я как раз хотел попробовать что-нибудь новенькое.$B$BМожно использовать обычные камни, но у меня есть идея получше. Я обстреляю лагеря Легиона тушами голодных зловепрей, пропитанными горючим составом, и посмотрим, как им это понравится! Туши валяются рядом с восточными руинами, все зловепри там давно подохли от голода.$B$BПойдешь собирать туши добровольцем, или тебя назначить?', 'Принесите командиру стражи Кранку из Траллмара 10 раздутых трупов голодных зловепрей.', '', NULL, NULL, NULL, 'Раздутый труп Зловепря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9349, 'Сбор яиц опустошителей', 'Я есть хочу!$B$BДумаешь, голодный повар – это смешно?$B$B<Легасси саркастически хмыкает и указывает на вынутый из кармана кусок пергамента.>$B$BСудя по этой туристической карте, мы пролетали где-то здесь, пока столь стремительно не свалились вниз... К северо-западу отсюда есть одно местечко в лесу Тероккар, называется дорога Острого Шипа. Там полным-полно яиц опустошителей, которые считаются отменным деликатесом.$B$BЕсли кто-нибудь не побоится их раздобыть, у нас будет настоящий праздник жи$N!', 'Принесите 12 яиц опустошителей Легасси на место крушения дирижабля на полуострове Адского Пламени.', 'Чтобы блюдо было отменным, его надо готовить из отменных продуктов! Эти яйца прекрасны.$B$BСейчас я дочищу свою сковородку, и можешь присоединяться к трапезе!', 'Ну, где яйца?$B$B<Живот Легасси издает голодное бурчание.>', NULL, NULL, 'Яйцо опустошителя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9351, 'Дикие демоны Бездны', 'Даже если я восстановлю оболочку дирижабля, все равно мне нечем заправить двигатель. Топливо закончилось, и я ума не приложу, где его можно достать.$B$BРазве что, к югу отсюда находится место под названием Искривленные поля. Там полно всякой нечисти и бесконтрольных демонов Бездны, но ведь это, можно сказать, ходячие батарейки!$B$BПринеси мне сущности демонов Бездны, я запущу двигатель и мы наконец уберемся отсюда. Ставлю пять золотых, что выжму из этого демона настоящую демоническую скорость!', 'Принесите 10 конденсированных сущностей демона Бездны \"Крикуну\" Скриду Многослову на место крушения дирижабля.', 'Отлично! Вот это мощь! Мне придется усовершенствовать двигатель, чтобы воспользоваться всеми преимуществами этой штуки. Если... в смысле, когда мы отсюда выберемся, в Зоне 52 ахнут, увидев, что я придумал!', 'Удалось добыть сущности?', NULL, NULL, 'Конденсированная сущность демона Бездны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9352, 'Вторжение из Дарнаса', 'Помимо постоянной угрозы со стороны Презренных мне еще регулярно приходится разбираться с сообщениями об атаках ночных эльфов!$B$BБольшинство этих сообщений оказываются ложными, но один недавний инцидент требует более пристального внимания. В Западном святилище, одном из наших главных источников энергии, произошла крупная авария. Ходят слухи, что это дело рук дарнасских диверсантов!$B$BСтупай туда и разберись со всеми, кто выглядит подозрительно. Потом отправляйся к хранительнице энергии Велании, которая заведует святилищем.', 'Отправляйтесь в Западное святилище, к юго-западу от площади Соколиных Крыльев, и уничтожьте всех чужаков, которых вы там встретите. Затем сообщите о результатах хранительнице энергии Велании.', 'Ночные эльфы? Здесь? Вот крысы!$B$BДумаешь, они имеют отношение к аварии в моем святилище? Если у тебя есть какие-то сведения, лучше незамедлительно передать их капитану Печати Солнца!', NULL, NULL, NULL, 'Чужак уничтожен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9355, 'Работа для сообразительных', 'Привет, $C. Наконец-то прибыло подкрепление, так что мы можем себе позволить хоть какое-то подобие нормальной жизни.$B$BОдна из первых задач – восстановить поток путников и торговых караванов по юго-западной дороге, но для этого надо очистить эту область от землероев.$B$BСыны будут тебе благодарны, если ты поможешь нам разобраться с этой напастью. Место обитания землероев очень легко опознать. Видишь вздыбленную землю – значит, внутри они и сидят.', 'Убейте 15 хищных землероев и возвращайтесь к штейгеру Большие Десны в Оплот Чести.', 'Хорошая работа, $N. Хотя, наверное, не стоит торопится поздравлять нас с решением этой проблемы. Уверен, немалая часть червей затаилась и еще выползет. Но если мы опять заметим их логова, то расправимся безо всякой пощады!', 'Ну что, очистил дорогу от червей?', NULL, NULL, 'Хищный землерой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9356, 'Летать как птица', 'Скрид любит говорить, что, дескать, он летает, как птица. Ага, как дохлая курица!$B$BТы только посмотри на эти обломки. Он называет это \"жесткой посадкой\"!$B$BКонечно, нас подстрелили, и я бы его даже пожалел, если бы он так не бахвалился своим мастерством!$B$BПожарю-ка я для него парочку птичьих крыльев, пусть он поразмыслит о своем поведении. К востоку отсюда, в Долине Костей, обитают канюки-костеклюи. У них мясистые, сочные крылья, это именно то, что надо.', 'Принесите 12 мясистых крыльев канюка Легасси на место крушения дирижабля.', 'Яйца опустошителей. Раз!$B$BБекон адского вепря. Два!$B$BКрылья канюка. Три!$B$BОтличное меню. Ты обязательно должен это попробовать.', 'Предвкушаю, какое у него будет лицо, когда он это увидит. С самого момента аварии он постоянно ворчит, что я думаю только о еде. Но кто-то же должен всех кормить, пока остальные чинят дирижабль!', NULL, NULL, 'Мясистое крыло канюка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9357, 'Задание Аэльдона Озаренного Солнцем', 'Если ты ищешь работу, обратись к капитану Печати Солнца за Внутренними эльфийскими воротами, что у меня за спиной.$B$BА теперь оставь меня в покое, мне нужно допросить этого негодяя.', 'Поговорите с Аэльдоном Озаренным Солнцем у Внутренних эльфийских ворот в Лесах Вечной Песни.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9358, 'Следопыт Сарейн', 'Наша деревня только выглядит мирной. На самом деле мы живем в осаде. С востока нам угрожает Плеть, с запада – Презренные.$B$BСледопыт Сарейн стережет наши границы от нежити, которая лезет с Тропы Мертвых. Ступай по дороге на восток и узнай, не нужна ли ей помощь.', 'Поговорите со следопытом Сарейн у деревни Легкий Ветерок, что в лесах Вечной Песни.', 'Ты здесь, чтобы помочь нам? Так что же ты молчишь? Помощь нам всегда пригодится!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9359, 'Обитель Странников', 'Ты $gоказал:оказала: нам неоценимую помощь в борьбе с Презренными. Такие бойцы наверняка пригодились бы Странникам в их борьбе с троллями из племени Амани.$B$BСтупай в обитель Странников к северо-востоку отсюда, поговори с лейтенантом Вестницей Зари и узнай, не нужна ли ей твоя помощь.', 'Поговорите с лейтенантом Вестницей Зари в обители Странников, что в лесах Вечной Песни.', 'Ты хочешь нам помочь? Замечательно!$B$BБорьба с племенем Амани дается нам недешево, и хорошие бойцы вроде тебя нам всегда нужны.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9360, 'Вторжение племени Амани', 'Вы не понимаете языка, которым написаны эти планы, но узнаете карту, на которой отмечено расположение обители Странников и деревни Легкий Ветерок.$B$BОб этом следует сообщить лейтенанту Вестнице Зари в обитель Странников!', 'Доставьте планы вторжения племени Амани лейтенанту Вестнице Зари в обитель Странников.', 'Тролли отвлекали нас своими атаками, планируя нападение на деревню Легкий Ветерок? Мы этого совершенно не ожидали!', 'Что это у тебя?', NULL, NULL, 'Планы вторжения племени Амани (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9361, 'Зловепрь – тоже мясо', 'Отличные яйца, но что скажешь, если мы добавим к ним еще один штрих?$B$BХороший кусок бекона станет достойным завершением нашего блюда, и я даже знаю, где его достать.$B$BЭто место просто кишит зловепрями. По-хорошему, их мясо надо бы хорошенько вымочить и замариновать, но нам повезло.$B$B<Легасси роется в своем барахле и достает оттуда фляжку.>$B$BКонечно, это вовсе не для приготовления свинины, но в поварском деле главное – импровизация!', 'Легасси требует принести ему 8 кусков мяса зловепря на место крушения дирижабля. Убейте зловепря, добудьте порченое мясо зловепря, а затем очистите его с помощью микстуры очищения.', 'Хм...$B$BВыглядит съедобным, если проперчить хорошенько. Лучше не будем говорить Скриду, откуда взялся его завтрак, ладно?', 'Что там с очищенным мясом зловепря? Удалось приготовить?', NULL, NULL, 'Очищенное мясо зловепря', 'Микстура очищения (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9362, 'Полководец Креллиан', 'У меня мало времени, $N! С помощью чар магического зрения я обнаружил мощный источник магии. Я не могу покинуть башню, поэтому прошу тебя убить мерзкое создание, завладевшее мощным артефактом. $B$BЖалкий недоумок, известный как полководец Креллиан, прячется за широкими спинами своих стражей в храме Зин-Малор. Испепели это ничтожество и принеси мне радужную раковину, которую он прячет.', 'Принесите радужную раковину верховному магу Ксилему в башню в утесах Азшары.', 'Должен заметить, у этой раковины странная аура. Очень хорошо, что частью твоей награды будет уникальная возможность исследовать свойства этого артефакта.', 'Мы не можем терять не минуты! Ты принес раковину?', NULL, NULL, 'Радужная раковина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9363, 'Предупреждение деревне Легкий Ветерок', 'Ступай в деревню Легкий Ветерок и предупреди следопыта Деголиена о планах Амани. Несмотря на то что Зул\'Марош мертв, деревне стоит приготовиться к нападению троллей. Скажи Деголиену, что я пришлю ему подкрепление при первой же возможности.', 'Отправляйтесь в деревню Легкий Ветерок в лесах Вечной Песни и поговорите со следопытом Деголиеном.', 'Ты принес очень важные сведения, $N. Теперь, когда мы знаем о планах троллей, мы будем готовы к нападению.$B$BНас не застанут врасплох!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9364, 'Частицы магии', 'В ходе исследований я выявил потрясающее свойство радужной раковины. $B$BВозьми раковину и наложи заклинание превращения на тварей Бича Злобы в Азшаре. Через несколько мгновений хаотическая аура раковины создаст нескольких маленьких клонов. Клонов надо убить – как можно скорее! – и тогда раковина вберет в себя их сущность. $B$BВозвращайся ко мне, когда раковина будет полна.', 'Наложите заклинание превращения на тварей Бича Злобы в Азшаре и убейте клонов, которые появятся несколько мгновений спустя. Убейте 50 клонов и возвращайтесь к верховному магу Ксилему в Азшару.', 'Прекрасно! Прекрасно! $B$BТеперь мы можем использовать собранную магическую силу для создания нового заклинания!', 'Ты выполнил мое поручение?', NULL, NULL, 'Клонированная овца убито', 'Радужная раковина (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9365, 'Награда вора', 'Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...', '', 'Сегодняшние твои деяния свидетельствуют сами за себя, $N.$B$BЯ мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости. Пусть он озарит твой путь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9366, 'Оскверненная кровь', 'К северо-востоку отсюда лежат пруды Аггонара. Когда-то там было священное место дренеев, но потом кровь демона осквернила воды этих прудов.$B$BС тех пор минуло много лет, но кровь, даже разбавленная, все еще таит в себе огро$Nю силу. Рядом с прудами разгуливают исчадия ужаса, насыщаясь энергией, разлитой в воде. Уничтожь их и принеси мне их оскверненную кровь. Выполни это задание, и получишь награду.', 'Принесите 6 образцов оскверненной крови исчадий ужаса, обитающих у прудов Аггонара, Риатену Мрачному из Соколиного дозора на полуострове Адского Пламени.', 'В этих образцах содержится неимоверная энергия, $N. Нам необходимо наладить постоянную и беспрепятственную доставку оскверненной крови.', 'Оскверненная кровь... Где она, $N?', NULL, NULL, 'Образец оскверненной крови', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9367, 'Праздник Огня', 'Вновь наступает праздник Огненного солнцеворота!$B$BКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Середине Лета.$B$BНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!', 'Прикоснитесь к пламени праздничных костров в Штормграде, Стальгорне и Дарнасе, затем поговорите с хранителем мудрости праздника в столичных городах.', 'Превосходно! Похоже, в этом году мы избрали ответственных Хранителей праздничных костров, если огни поддерживаются так хорошо, как ты утверждаешь. Спасибо за проведенное исследование; вот, прими это как небольшой знак моей благодарности.', 'Горят ли костры?', NULL, NULL, 'Пламя Штормграда', 'Пламя Стальгорна', 'Пламя Дарнаса', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9368, 'Праздник Огня', 'Вновь наступает праздник Огненного солнцеворота!$B$BКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Середине Лета.$B$BНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!', 'Прикоснитесь к пламени праздничных костров в Оргриммаре, Громовом Утесе и Подгороде, затем поговорите с Праздничным сказителем в столичных городах.', 'Превосходно! Похоже, в этом году мы избрали ответственных Хранителей праздничных костров, если огни поддерживаются так хорошо, как ты утверждаешь. Спасибо за проведенное исследование; вот, прими это как небольшой знак моей благодарности.', NULL, NULL, NULL, 'Пламя Оргриммара', 'Пламя Громового Утеса', 'Пламя Подгорода', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9369, 'Исцеляющие кристаллы', 'Мы дренеи. Наш корабль разбился, и поскольку раненых очень много, первым делом надо зарядить исцеляющие кристаллы. И побыстрее!$B$BК сожалению, в настоящий момент для этого придется добывать кровь долинных мотыльков, она отлично подойдет.$B$BМотыльки водятся во всей долине, особенно в северо-западной ее части.', 'Добудьте 8 фиалов с кровью мотылька из долинных мотыльков и принесите их Проэнитусу на место крушения в долине Аммен.', 'Жаль, что приходится обменивать жизни этих существ на наши – подобная жестокость чужда духу дренеев. Зато собранная кровь наполнит исцеляющие кристаллы, так что мотыльки погибли не зря.', 'Тебе удалось набрать достаточно крови мотыльков, чтобы зарядить исцеляющие кристаллы? Время не ждет, раненых очень много!', NULL, NULL, 'Фиал с кровью мотылька', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9370, 'Остановить очищение', 'Наши разведчики захватили у прудов Аггонара какого-то дренейского паладина. Он подготавливал ритуал по очистке прудов. Мы должны остановить дренеев, а не то потеряем бесценный источник оскверненной крови!$B$BВот этим сигнальным самоцветом он должен был пометить место, где их жрец – \"анахорет\", как они себя называют, – мог бы спокойно провести ритуал. Поставь камень на алтарь Аггонара и убей всех дренеев, которые появятся.$B$BДумаю, тебе стоит прихватить парочку друзей на помощь.', 'Поставьте сигнальный самоцвет на алтарь Аггонара, рядом с прудами Аггонара, и уничтожьте дренейского анахорета и всех, кто явится на сигнал. После выполнения задания заберите самоцвет и возвращайтесь к Риатену Мрачному в Соколиный дозор.', 'Пусть эти святые фанатики не лезут не в свое дело.', 'Ты вернулся, $N. Что, я уже могу начинать оплакивать этих дренейских идиотов?', NULL, NULL, 'Дренейский анахорет убито', 'Сигнальный самоцвет (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9371, 'Ботаник Таэрикс', '$N, ботанику Таэрикс нужна твоя помощь. Она вместе с учениками расположилась на западе отсюда, рядом с кораблем.', 'Поговорите с ботаником Таэрикс на месте крушения в долине Аммен.', 'О, слава Небу, что ты здесь. У нас очень много работы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9372, 'Распространение демонической скверны', 'Добро пожаловать на Кенарийскую заставу, $C. Я благодарна, что ты $gзашел:зашла: сюда, нас нечасто балуют визитами. Я исходила эти земли вдоль и поперек, исследуя существ, которые их населяют.$B$BИзучая по поручению Кенарийской экспедиции наиболее опасных тварей, я сделала поразительное открытие. Многие из здешних существ уже подверглись кардинальным изменениям, но все равно продолжают мутировать. Чтобы следить за этими изменениями, мне нужны образцы крови, так что я буду рада любой помощи.', 'Соберите 6 образцов крови зловепря у крупных зловепрей по просьбе Тии Рыжей Гривы с Кенарийской заставы на полуострове Адского Пламени.', 'Прекрасно, $N. Эти образцы крови не только помогут мне в исследованиях, но пригодятся Экпедиции для дальнейшего изучения дикого мира Запределья.$B$BЕсли мы узнаем, что заставляет обитателей этих земель постоянно мутировать, то, возможно, сможем изготовить противоядие.', 'Тебе удалось выполнить мою просьбу?', NULL, NULL, 'Образец крови зловепря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9373, 'Потерянное послание', 'Взглянув на кожу чехла повнимательней, вы понимаете, что его разъели желудочные соки червя. Кажется, на чехле был какой-то узор, но детали украшений разобрать невозможно.$B$BЕдинственное, что можно опознать, так это полустертый знак Круга Кенария. О содержимом чехла ничего не известно, и вы решаете, что лучше всего отнести его кому-нибудь из Круга.', 'Доставьте подпорченный кожаный чехол Тие Рыжей Гриве, которая стоит лагерем рядом с руинами Ша\'наара на западе полуострова Адского Пламени.', 'Спасибо, что принес мне эту вещь, $C. Я-то думала, почему так долго нет вестей от Экспедиции. Хотела бы я знать, как давно было отправлено это послание и что случилось с его курьером.$B$BВозьми за труды немного денег.', 'Добрый день, $C. Что привело тебя в наш лагерь?', NULL, NULL, 'Подпорченный кожаный чехол (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9374, 'Записи Арелиона', 'Мой муж Арелион заинтересовался прудами Аггонара, едва мы прибыли в Запределье. Больше всего времени он проводил, изучая свойства местного ила.$B$BНесколько дней назад его не стало. Мне сказали, что он мертв, а с этим ничего уже не поделаешь.$B$BНо я бы не хотела, чтобы исследования моего мужа бесследно сгинули после его смерти. Ступай на северо-восток, к прудам, и поищи его дневник. Арелион носил его в коричневом ранце.', 'Отправляйтесь к прудам Аггонара и найдите записи Арелиона по просьбе магистра Каринды из Соколиного дозора на полуострове Адского Пламени.', 'Записи моего мужа... Да там нет ни слова о научных изысканиях!$B$BКак я могла быть такой идиоткой? \"Магические свойства оскверненного ила...\" Да он просто пудрил мне мозги!', 'Как успехи, $N? Пруды Аггонара лежат к северу от цитадели Адского Пламени.', NULL, NULL, 'Записи Арелиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9375, 'Дорога к Соколиному дозору', '$gЭльфийка крови смотрит на вас и на ее израненном лице появляется надежда.>$B$BПожалуйста, $C, помоги мне выбраться из этой клетки! Я по глупости отбилась от основной группы, идущей из Траллмара. Предупреждал же меня Мартик Тор\'сельдори!$B$BНа меня напали ужасные создания, судя по всему, те самые опустошители, о которых он говорил. Мне удалось отогнать их, но это было только начало.$B$BТолько я занялась своими ранами, как меня разыскали проклятые птицелюды. Они притащили меня сюда, в пещеру, и заперли в этой клетке. Освободи меня, пожалуйста, я должна добраться до Соколиного дозора!', 'Помогите израненной эльфийке крови – пилигриму добраться до Соколиного дозора, затем поговорите с Талерисом Созерцателем Рассвета.', '<Талерис рявкает, обращаясь к эльфам крови на заставе>$B$BЗанесите ее внутрь и перевяжите!$B$B<Затем снова обращается к вам.>$B$BЕй повезло, что ты нашел ее, $C. Я думаю, она недолго бы протянула.$B$BТы понял, о чем она говорила?', 'Что тебе нужно, $C?', NULL, NULL, 'Проводите израненную эльфийку крови – пилигрима до Соколиного дозора.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9376, 'Скарб пилигрима', 'Наша раненая путница все продолжает кричать о какой-то сумке.$B$BТы не $gзаметил:заметила: ничего похожего на том месте, где ее $gнашел:нашла:? Хм...$B$BДолжно быть, она потеряла сумку, когда бежала от преследователей. Перозубые опустошители из вон той лощины на юге часто нападают на одиноких путников.$B$BЕсли она не успокоится, я не смогу наложить повязку на рану. Как она не понимает, что упрямство может стоить ей жизни!$B$BСтупай в Лощину Пыльного Пера, и попробуй разыскать место ее стоянки. Держу пари, она оставила свои сумки где-то там.', 'Перозубые опустошители напали на израненную эльфийку крови – пилигрима, когда она остановилась в Лощине Пыльного Пера. Разыщите ее стоянку и потерянные вещи.', 'Спасибо, что вернул сумки, $N. Не знаю, что там такого важного, но она не подпускала к себе никого, пока не получила свои вещи обратно.', 'Не нравится мне все это. Вряд ли она бы кинула сумку на дороге. Ты можешь разыскать ее вещи?', NULL, NULL, 'Разорванная сума пилигрима', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9380, 'В погоне за большим', 'Клянусь, что если получу еще хоть одно письмо из Стальгорна...$B$BТы когда-нибудь $gпытался:пыталась: что-нибудь объяснить тому, кто тебя в упор слышать не хочет, а, $C? Я послал этим парням из Стальгорна астральную гончую, которую они заказывали, но им, видите ли, нужна целая \"упаковка\" подобных созданий! Подумать только, - упаковка!$B$BЯ попытался им объяснить, что астральные гончие - одиночки, но они отказались меня слушать. Я уже понял, что вразумить их невозможно. Можешь собрать штук шесть самых лучших гончих, они встречаются к востоку от крепости, и принести сюда?', 'Соберите 6 неповрежденных трупов астральных гончих и доставьте в Оплот Чести геологу Мурантусу.', '', NULL, NULL, NULL, 'Неповрежденный труп астральной гончей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9381, 'Стрелы, бьющие без промаха', 'Пилигримы идут нескончаемой чередой, а силы Альянса зашевелились, так что дел в Соколином дозоре, – только успевай поворачиваться. Обычно я делаю стрелы для наших следопытов, но уже довольно давно у меня нет времени даже собрать перья на оперение.$B$BЯ дам тебе денег, если принесешь хвостовые перья стервятника-костеклюя. В последний раз я видела, как они кружили около костей каких-то огромных тварей к северу от Соколиного дозора.', 'Принесите 8 хвостовых перьев стервятника-костеклюя сокольничему Дренне Речной Ветер в Соколиный дозор.', 'Да, это подойдет. Нашим следопытам давно не хватает стрел, так что одной головной болью стало меньше. Спасибо за помощь, $C.', 'Ты принес перья?', NULL, NULL, 'Хвостовое перо стервятника-костеклюя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9382, 'Жестокий рок копытня', 'Приветствую, $N.$B$BДумаю, во время пути через Запределье ты $gзаметил:заметила:, что эта земля поражена скверной. Животные или погибли, или оказались искажены до полной неузнаваемости.$B$BКогда-то копытни, пасущиеся на юге и на западе отсюда, были мирными травоядными, но скверна зажгла в них неугасимую ненависть. Нас очень печалит необходимость проливать кровь, но только смерть сможет избавить их от этой пытки. Помоги щетинистым копытням упокоиться с миром.', 'Убейте 15 щетинистых копытней и возвращайтесь к Амаану Мудрейшему в Храм Телхамата.', '', NULL, NULL, NULL, 'Щетинистый копытень убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9383, 'Честолюбивый план', 'Эльфы крови используют магию совершенно безответственно, $C. Они не умеют контролировать магическую энергию. Наоборот, они ее бездумные рабы, и способны на что угодно, только бы утолить свою магическую жажду. Чтобы усилить свою демоническую магию, они пожирают энергию демонов Бездны.$B$BЯ создала кристалл, заряженный заклинанием, который позволит нам нейтрализовать демонов Бездны и оборвать их связь с этим миром. Я видела демонов Бездны на Искривленных полях, к юго-востоку от цитадели Адского Пламени.', 'Используйте освященный кристалл против раненого неконтролируемого демона Бездны, затем возвращайтесь к Элсаане в храм Телхамат.', 'Молодец, $N. Судя по всему, сдерживающий кристалл работает, но сколько это будет продолжаться, неизвестно. Мы будем за ним присматривать, а заодно приготовим побольше кристаллов на будущее.', 'Сработала ли магия кристалла против демона Бездны?', NULL, NULL, 'Светящийся освященный кристалл', 'Освященный кристалл', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9385, 'Разъяренные Опустошители', 'Оплот Чести послал нас разобраться с араккоа, и мы разбили здесь лагерь, думая, что никто нас не потревожит. Как выяснилось, мы встали слишком близко к перозубым опустошителям.$B$BЭти безжалостные твари сводят на нет всю нашу работу. Мы заплатим тебе, если ты с ними разделаешься. Ну что, по рукам?', 'Убейте 10 перозубых опустошителей и возвращайтесь к Гремни Длиннобороду на полуострове Адского Пламени.', 'Молодцом, $N. Пусть эти твари знают, кто тут главный!', 'Как продвигается охота на опустошителей?', NULL, NULL, 'Перозубый опустошитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9386, 'Свет в темных местах', 'Неужели тебе этого так хочется? Ну что ж, если снова желаешь спуститься в глубины, я с радостью тебя вознагражу. $B$BОтыщи костры, горящие в Стратхольме, Некроситете, Забытом Городе и в залах самого пика Черной горы. Я буду ждать твоего возвращения, $N.', 'Найдите костры, размещенные в пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени.', '', NULL, NULL, NULL, 'Пламя Забытого Города', 'Пламя пика Черной горы', 'Пламя Стратхольма', 'Пламя Некроситета');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9387, 'Источник порчи', 'Все дренеи, не попавшие под влияние Скверны, – истинные паладины Света, и наш невезучий приятель не исключение. Но мне интересно, как Скверна смогла низвести эту великую расу до Сломленных и Заблудших.$B$BЯ слышал о теории, что мутацию вызывает энергия Скверны. Я хочу ее проверить.$B$BК северо-западу отсюда лежат руины Ша\'наара. Туда иллидарские надсмотрщики согнали Сломленных. Принеси мне несколько демонических сущностей, которые можно добыть из надсмотрщиков, и я проверю их на этом дренее.', 'Отправляйтесь в руины Ша\'наара на полуострове Адского Пламени и добудьте из иллидари-надсмотрщиков 5 демонических сущностей. После завершения задания возвращайтесь к аптекарю Азетену в Соколиный дозор.', 'Ты оказал мне большую услугу, $N. А теперь посмотрим, что скажет наш синий друг.', 'Ты добыл образцы?', NULL, NULL, 'Демоническая сущность', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9388, 'Мерцающие огни Калимдора', 'Сегодня по всему миру горит множество огней, $N. Сложнее всего присматривать за теми кострами, которые пылают зеленым; без присмотра они не будут гореть долго. Убедись, что изумрудные огни все еще горят в Калимдоре – пусть наш Хранитель костров успокоится.$B$BТы найдешь эти костры вблизи Кабестана в Степях, неподалеку от Меча Властителя на Темных берегах, в Ясеневом лесу у моста около Аванпоста Среброкрылых, и поблизости от дороги на Утес Ветрорезов вдоль главного тракта в Когтистых горах.', 'Посетите праздничные костры в Ясеневом лесу, Степях, на Темных берегах и в Когтистых горах, затем поговорите с хранителем праздничного пламени.', '', NULL, NULL, NULL, 'Пламя Ясеневого леса', 'Пламя Степей', 'Пламя Темного Берега', 'Пламя Каменного Когтя');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9389, 'Мерцающие огни Восточных королевств', 'Во время праздника Огненного солнцеворота по всей земле традиционно зажигаются мириады огней. Кое-кто считает, что зеленое пламя является самым изящным, поскольку его труднее всего поддерживать, и оно имеет столь уникальный оттенок.$B$BУбедись, что это пламя все еще горит в Восточных королевствах, чтобы успокоить нашего хранителя огня. Эти костры размещены около Дун Модра в Болотине, поблизости от деревни Погребальных Костров в Серебряном бору, на утесах неподалеку от маяка Западного края и возле разрушенной башни в предгорьях Хиллсбрада.', 'Посетите праздничные костры в предгорьях Хилсбрада, в Серебряном бору, Западном Крае и Болотине, затем поговорите с хранителем праздничного пламени.', 'Так ты возвращаешься, повидав изумрудное пламя, горящее в разных уголках континента... И что ты об этом думаешь? Несомненно, это редкостное и замечательное зрелище. Однако я осознаю, что весомая награда ценится больше... поэтому возьми вот это за твои труды.', NULL, NULL, NULL, 'Пламя Хилсбрада', 'Пламя Серебряного бора', NULL, 'Пламя Болотины');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9390, 'Найти Седаи', 'Выслушай меня, $C. Мой брат Седаи отправился на встречу с орками с заставы маг\'харов. Этот несчастный идеалист считал, что время излечило взаимные обиды, и мы сможем договориться о мире.$B$BУже несколько дней о нем ничего не слышно, и я опасаюсь самого худшего.$B$BМожешь отправиться на его поиски и дать отдых моей измученной душе? Седаи должен быть где-то на востоке.', 'Разыщите Седаи, брата анахорета Обадия. Седаи может находиться где-то поблизости, на востоке, на полуострове Адского Пламени.', 'Вы находите тело юного дренейского паладина. Он убит стрелой в спину.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9391, 'Осветить путь', 'Теперь, когда численность камнедеров уменьшилась, надо указать пилигримам безопасную дорогу. Возьми этот факел и возвращайся к Глубокому Разлому. Разыщи там три маяка, которые стоят вдоль дороги на восток.$B$BЗажги их, и после этого возвращайся ко мне. Будь $gосторожен:осторожна: – огонь маяков наверняка привлечет камнедеров.', 'Отправляйтесь к Глубокому разлому на полуострове Адского Пламени и зажгите южный маяк, западный маяк и центральный маяк. После выполнения задания возвращайтесь к капитану следопытов Венн\'рену из Соколиного дозора вместе с зажженным факелом.', 'Глубокий разлом все еще опасен, но, по крайней мере, там можно пройти.$B$BЕсли бы Альянс не караулил все известные нам дороги, вряд ли бы мы решились на такое дело.', 'Ты выполнил мою просьбу, $N?', NULL, NULL, 'Западный Маяк', 'Центральный маяк', 'Южный маяк', 'Горящий факел (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9392, 'Обучение разбойника', 'По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных разбойников на острове Солнечного Скитальца тренирует налетчик Авокор. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.$B$BАвокор, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.', 'Поговорите с наставником разбойников налетчиком Авокором в Солнечном Шпиле на острове Солнечного Скитальца.', 'Твое имя прошептали мне тени, Авй. Говорят, ты ищешь опытного наставника, который покажет тебе что к чему, - то есть кого-то вроде меня. Что же, я могу тебе помочь, но это будет тебе стоить небольшого процента со всей добычи каждый раз, как я буду чему-нибудь тебя учить. Да, я расскажу тебе, что значит быть разбойником.$B$BНо запомни: если тебя уличат в воровстве, ты меня не знаешь. А теперь иди сюда и покажи, из какого теста ты сделана!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9393, 'Обучение охотника', 'По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных охотников на острове Солнечного Скитальца тренирует следопыт Саллина. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.$B$BСаллина, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.', 'Поговорите с следопытом Саллиной в Солнечном Шпиле на острове Солнечного Скитальца.', 'Привет тебе, $N. Охотник должен быть зорок как ястреб, ловок как обезьяна и быстр как гепард. Ты можешь стать таким после надлежащего обучения. Путь охотника - путь к власти над зверями этого мира, непревзойденной меткости и умения выживать в таких ситуациях, когда другие погибают.$B$BЕсли тебе это интересно, я обучу тебя - естественно, за небольшое вознаграждение. Начнем?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9394, 'Куда подевался Виллитен?', 'Смотритель земель Блеклых Сумерек куда-то запропастился! Должно быть, его забыли предупредить, что надо уходить, когда магистр и все прочие покинули шпиль. Я знаю, что он до сих пор где-то здесь, однако не решаюсь отправиться на поиски: вокруг слишком много магических тварей.$B$BПрошу тебя, $C, найди его и убедись, что с ним все в порядке!', 'Найдите смотрителя Виллитена в землях Блеклых Сумерек, что в лесах Вечной Песни.', 'Кто ты? Ты не из учеников магистра, это точно!$B$BТебя прислали помочь мне уладить это безобразие?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9395, 'Вилла Салтерила', 'Клянусь, если я получу еще хоть один запрос от лорда Салтерила касательно припасов для его вечеринки, я запущу в кого-нибудь огненным шаром! Я что, похожа на массовика-затейника? Между нами говоря, этот глупец и его прихлебатели живут в убеждении, что нам тут ничто не угрожает!$B$BА ведь кое-кто из нас всерьез занят... ну, например, я не знаю, обороной того, что осталось от Кель\'Таласа! Слушай, $C, может быть, тебе удастся угомонить Салтерила? Его вилла находится дальше по дороге, к западу отсюда...', 'Поговорите с лордом Салтерилом на вилле Салтерила в лесах Вечной Песни.', 'О, магистр Рассветная Странница наконец-то откликнулась на мои скромные просьбы! Как мило с ее стороны. Надо будет доложить о ее поведении лорду-регенту в Луносвет. Она чудовищная грубиянка!$B$BНо тебе не о чем беспокоиться. Полагаю, твое появление означает, что я наконец-то получу долгожданные припасы для моей вечеринки!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9396, 'Магия араккоа', 'Запределье, $N, хранит множество секретов. Рано или поздно ты с ними столкнешься, это только вопрос времени.$B$BАраккоа, эти полулюди- полуптицы, владеют древним чародейным знанием, которое бы нам очень пригодилось. Отправляйся в логово Хаал\'эш, к югу отсюда. Найди все магические свитки, которые хранит племя Хаал\'эш, и принеси их мне.', 'Принесите 4 свитка племени Хаал\'эш чародею Калестрису Утренней Звезде в Соколиный дозор на полуострове Адского Пламени.', 'Неплохо сработано, $N. Запределью не удасться утаить от нас свои секреты.$B$BНаше призвание - стать хозяевами этого мира!', 'Тебе удалось добыть свитки, $N?', NULL, NULL, 'Свиток племени Хаал\'эш', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9397, 'Пух и перья', 'Араккоа из логова Хаал\'эш вывели необыкновенных птиц, которых они называют калири.$B$BМне удалось поймать несколько молодых самцов, и, кажется, они вполне поддаются дрессировке. Добыть самочку куда труднее, но если бы у меня была хотя бы одна, я смогла бы получить от них потомство. Лучше всего, если самочка будет очень молоденькая... совсем птенец. Взрослая дикая птица не выживет в неволе.$B$BВозьми эту клетку и ступай на юг, в логово Хаал\'эш. Разыщи гнезда с яйцами, из которых должны вылупиться птенцы. Если ты раздобудешь юную самку калири, я награжу тебя по-царски.', 'Отправляйтесь в логово Хаал\'эш на полуострове Адского Пламени и найдите молодую самку калири в гнезде калири. Посадите птенца в пустую клетку и принесите сокольничему Дренне Речной Ветер в Соколиный дозор.', 'Вот она! Настоящая юная самка калири!$B$BКакая она хорошенькая! Спасибо тебе, $N.', 'Ты вернулся. принес самку калири?', NULL, NULL, 'Молодая самка калири в клетке', 'Пустая птичья клетка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9398, 'Смертельно опасные хищники', 'В Запределье Сломленные не испытывали ничего, кроме насилия и жестокости. Не удивительно, как только открылся Темный портал, они кинулись к нему, стремясь выбраться из этого мира.$B$BК несчастью для наших ошеломленных братьев и сестер, пришедших с юга, они стали легкой добычей для камнедеров из Глубокого разлома. Если хочешь помочь выжить моему племени, отправляйся к Разлому и уничтожь хищников.', 'Убейте 8 детенышей камнеруба и 4 камнерубов-вожаков по просьбе разведчицы Вануры из храма Телхамат на полуострове Адского Пламени.', 'Ты сделал что должно, $N. Ужасно, что нам приходится отнимать жизнь, даже если это жизнь таких опасных тварей, как камнедеры.$B$BЭто было необходимо, хотя и жестоко, и я благодарна тебе.', NULL, NULL, NULL, 'Камнеруб-вожак убито', 'Детеныш камнеруба убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9399, 'Безжалостные десятники', 'Ты думаешь, все Сломленные несут в себе семена зла? На самом деле, очень многое зависит от обстоятельств. Пока я не встретил Оменай, меня тоже можно было считать потерянным.$B$BНаш разум сильно пострадал от воздействия демонической магии орков. В таком состоянии очень легко сбиться с пути и лишиться воли.$B$BДемоны, заключившие союз с Иллиданом, день за днем обыскивали полуостров Адского Пламени, находили нас и делали своими рабами. Оменай принесли нам надежду. Если хочешь, чтобы мои родичи обрели свободу, отправляйся в руины Ша\'наара, что на юго-западе отсюда, и убей иллидари-надсмотрщиков.', 'Убейте 4 иллидари-надсмотрщиков на руинах Ша\'наара и возвращайтесь к Икану в храм Телхамат на полуострове Адского Пламени.', 'Ты сделал это! Я твой вечный должник, $N. Посмотри на это Отребье.$B$BУвидишь, я научу их жить снова.', NULL, NULL, NULL, 'Иллидарский надсмотрщик убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9400, 'Убийца', '$N, недавно мы обнаружили, что готовится покушение на нашего посланника в Соколином дозоре. Цитадели Адского Пламени стали известны планы нашей экспедиции, и они решили устроить засаду.$B$BРазведчики доложили, что убийца по имени Крун Хребтолом поджидает на дороге к цитадели. Ступай и уничтожь его. Пусть орки Скверны знают, как с нами связываться!', 'Ступайте по дороге к северу от цитадели Адского Пламени и разыщите убийцу по имени Крун Хребтолом по просьбе Назгрела.', 'Тело соответствует описанию Круна Хребтолома, убийцы из цитадели Адского Пламени. Перевернув тело, вы замечаете, что из его спины торчит каменный топор.', NULL, NULL, NULL, 'Исследовать локацию', 'Разыщите убийцу по имени Крун Хребтолом', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9401, 'Странное оружие', 'Вы вытаскиваете каменный топор из тела, чтобы рассмотреть его повнимательней. В этом оружии есть что-то необычное.$B$BВроде бы сделано орками, но вы раньше никогда не видели, чтобы орки работали с таким материалом. Возможно, топор следует показать Назгрелу.', 'Принесите тяжелый каменный топор Назгрелу в Траллмар на полуострове Адского Пламени.', 'Он был убит этим оружием? Не может быть...$B$BНеужели... мы нашли их?', 'Скажи, убийца мертв?', NULL, NULL, 'Тяжелый каменный топор (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9402, 'Апорт!', 'Ты кто? $N? Можешь не зазнаваться от того, что я знаю тебя по имени: $gодна из моих студенток:один из моих студентов: только о тебе и твердит.$B$BХм... если уж ты хочешь произвести на $gнее:него: впечатление, отчего бы тебе не оказать мне услугу? На дне пруда, что позади меня, лежит лазурный фиал. Нырни, добудь его и принеси сюда.', 'Нырните на дно пруда Тихого Шелеста и добудьте лазурный фиал для инструктора Антеола.', 'Что ж, молодец, молодец... Стоило мне попросить тебя прыгнуть в пруд, и ты это сделал! Интересно, чего бы ты ни сделал, если бы тебя попросил об этом один из лучших друзей!$B$BЕсли ты ждешь награды за труд, вот тебе в награду совет: никогда не берись за дело, не узнав сначала, что ты с этого будешь иметь. Главное оружие мага – это его ум. Запомни это и постарайся впредь первым делом пускать в ход мозги.', 'Ну, как водичка?', NULL, NULL, 'Лазурный фиал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9403, 'Чистейшая вода', 'Ну а теперь, когда ты кое-чему $gнаучился:научилась:, я тебе предложу кое-что более существенное. Речь идет о твоей способности защищаться в ближнем бою. Разумеется, лучше вообще не вступать в бой без крайней необходимости, но нужно быть $gготовым:готовой: ко всему.$B$BЯ могу помочь тебе изготовить посох, подобающий магу. Для начала возьми флакон, добытый тобою со дна, и наполни его водой у подножия водопада Элрендар. Ступай вдоль реки на юго-восток, и увидишь водопад.', 'Наполните лазурный флакон водой из водопада Элрендар для Антеола.', '', NULL, NULL, NULL, 'Наполненный лазурный фиал', 'Лазурный фиал', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9404, 'Живая ветка', 'Тебе, наверное, случалось видеть ходячие деревья вблизи водопада Элрендар? Эти хранители природы пронизаны первородной магией, которую мы можем использовать в собственных целях с помощью чистой воды, которую ты уже $gпринес:принесла: мне.$B$BК несчастью, наши хранители леса такие древние и ветхие, что тебе, возможно, придется перебить нескольких из них, прежде чем удастся найти хоть одну живую ветку.', 'Убивайте хранителей лесов Вечной Песни, пока не найдете животворную ветвь для инструктора Антеола.', '', NULL, NULL, NULL, 'Животворная ветвь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9405, 'Поручение Вождя', 'Как известно, вождь затеял экспедицию только с одной целью. Это мир, из которого мы пришли. Там наши корни.$B$BВ этом путешествии у орков и эльфов крови разные цели. В отличие от нас, они ищут землю обетованную.$B$BКто бы не создал этот топор, он знаком с прежними днями и мы должны найти его. Дело слишком важное, чтобы использовать обычный способ поиска. Покажи топор провозвестнице Регулкут, она скажет, что делать.', 'Принесите тяжелый каменный топор провозвестнице Регулкут в Траллмар на полуострове Адского Пламени.', 'Я выполню просьбу Назгрела, $C. Больше ни слова.', 'Скажи мне, чего ты ищещь. Может быть, я помогу тебе.', NULL, NULL, 'Тяжелый каменный топор (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9406, 'Маг\'хары', 'Новости, которые ты $gпринес:принесла: о другой земле за Темным порталом... Я должен поверить, что вся земля там принадлежит сыну Дуротана... и свободна от демонической скверны? Но как его народ смог вернуться в этот мир?$B$BНадеюсь, для твоего же блага, что это не шутка, $C. Новость, которую ты $gпринес:принесла: слишком много для нас значит. Я немедленно отправлю донесение в Награнд! Адский Крик должен узнать об этом!$B$BОтнеси письмо обратно в Траллмар, своему командиру. Скажи, что маг\'хары шлют ему привет!', 'Доставьте письмо маг\'харов Назгрелу в Траллмар на полуострове Адского Пламени.', 'Ты уверен? Настоящие орки... Здесь, на полуострове Адского Пламени! Вот это новости, $N.$B$BНадо немедленно доложить вождю.', 'Какие вести ты принес нам, $N?', NULL, NULL, 'Письмо от маг\'харов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9407, 'Через Темный портал', 'Много лет Темный портал оставался безмолвным... забытым. Но теперь он проснулся.$B$BПосле того как наши войска отразили нападение демонов, они пробились через портал и встретились с врагом на его территории!$B$BНыне мы втянуты в безжалостную войну, и кое-кто думает, что мы не сможем победить. Наш долг, наша мрачная радость – сразиться с демонами в Запределье, обеспечив нашу победу. $B$BЕсли ты хочешь помочь нам, $N, то немедленно сообщи об этом генерал-лейтенанту Ориону. Он ждет тебя в Запределье...', 'Пройдите через Темный портал и найдите генерал-лейтенанта Ориона. Он ждет вашего прибытия на другой стороне, в Запределье.', 'Наша экспедиция благополучно прошла через портал и основала новую базу, именуемую Траллмар. Но, как ты видишь, Пылающий Легион своим вторжением отрезал нас от наших собратьев. Любому понятно, что демоны надеются отбить Темный портал и не позволить нам получить подкрепление с Азерота.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9408, 'Забытые герои', 'Мы потеряли уже столько солдат в битве за этот портал, но по-прежнему продолжаем держать оборону.$B$BТрудно поверить, но эта крепость, – живое свидетельство стойкости солдат Альянса.$B$BЗдесь находится один из великих героев – Данат Троллебой! Разыщи его, $C. Он поговорил с каждым солдатом, и, несомненно, захочет видеть и тебя.', 'Поговорите с командиром армии Данатом Троллебоем в Оплоте Чести.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9409, 'Срочная доставка', 'Благодаря тебе мы собрали все необходимое, чтобы зарядить исцеляющие кристаллы. Отнеси эти фиалы Зальдууну, нашему жрецу. Он ухаживает за ранеными в центральной части корабля.', 'Отнесите сверток с фиалами Залдууну на место крушения в долине Аммен.', 'Превосходно! Эта кровь прекрасно подойдет для наших исцеляющих кристаллов.$B$BРаз уж ты здесь, у меня найдется для тебя поручение. Ты не против?', 'Привет тебе, $C. Что ты несешь? Это мне?', NULL, NULL, 'Сверток с фиалами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9410, 'Хранитель душ', 'Их возможности превосходят нюх наших самых лучших волков, $N. У духов есть свой способ отыскать кого-то. Ты призовешь существо, которое чует не запах, но сущность.$B$BА теперь ступай, $C. Возьми с собой этот тотем и установи его там, где $gнашел:нашла: каменный топор.', 'Установите тотем духа волка на том месте, где вы нашли тело Круна Хребтолома. Когда появится дух древнего волка, следуйте за ним.', 'Кто ты, незваный гость? Я приказал своим бойцам не трогать тебя только потому, что Рига учуяла рядом с тобой духов.$B$BГовори, не бойся, но выбирай слова. Мы редко доверяем чужакам, особенно в такой близости от цитадели.', 'Тебе повезло остаться в живых.', NULL, NULL, 'Тотем духа древнего волка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9415, 'Маршал Синяя Синестен', 'Ты новобранец маршала Синестена? Ну, конечно.$B$BЧего ты ждешь? Наши солдаты умирают там, в пустыне. Правда, тебе не терпится к ним присоединиться?$B$BИди, и смотри, не присохни к песку по пути.', 'Поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.', 'Альянсу нужна помощь всех, кто способен держать оружие. Орда регулярно получает подкрепление с северной части континента, и мы изо всех сил стараемся от них не отстать.$B$BПозволь, я объясню тебе ситуацию.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9416, 'Генерал Кирика', 'Должно быть, ты $gодин:одна: из новобранцев генерала Кирики. Пора тебе браться за дело. В пустыне тела очень быстро портятся.$B$BДворфы ежедневно получают подкрепление, а мы не должны им уступать. Полезные ископаемые Силитуса наши!$B$BГенерал тебя проинструктирует. Не мое дело – учить тебя. Мне приказали только найти тебя.', 'Поговорите с генералом Кирикой в лагере Орды рядом с Ульем Регал.', 'Хорошо, что ты здесь, но на любезности времени нет. Я проведу инструктаж, и ты сразу отправляйся в бой.$B$BСлушай.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9417, 'Угроза Араккоа', 'Араккоа умные твари... Почти такие же, как гномы. У них неистовый нрав, и они отлично владеют магией.$B$BНедавно они напали на патруль Оплота Чести, поэтому-то нас сюда и отправили. Миррен и я - лучшие стрелки в мире, так-то! Но птички, в которых мы обычно стреляем, не имеют обыкновения поливать нас молниями.$B$BМожет, пособишь нам немного? Ты найдешь логово Хаал\'эш к юго-западу отсюда.', 'Убейте 4 ветроступов и 6 коготарей из племени Хаал\'эш по просьбе Гремни Длинноборода с полустрова Адского Пламени.', 'Великолепно, $N! На сим нарекаю тебя истинным Длиннобородым!$B$BНе уходи, это непременно надо обмыть!', NULL, NULL, NULL, 'Ветроступ из племени Хаал\'эш убито', 'Коготарь из племени Хаал\'эш убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9418, 'Сфера Авруу', '$gВы подносите сферу ближе к себе, и до вас доносится голос.>$B$BЯ чувствую, ты не араккоа, так что мы сможем договориться. Мое имя Аэранас, когда-то я правил восточным ветром. В эту сферу меня заключил Авруу, один из магов племени Хаал\'эш. Я могу выкупить у тебя свою свободу.$B$BНайди алтарь, который араккоа использовали, чтобы поработить меня. Он сокрыт где-то на юго-востоке их логова. Поднеси сферу к алтарю, а когда я стану свободен, отдай ее мне. В обмен на свою свободу я отдам тебе древнее сокровище.', 'Отнесите сферу Авруу на алтарь племени Хаал\'эш, который находится на юго-востоке от логова Хаал\'эш на полуострове Адского Пламени. После того как Аэранас обретет свободу, отдайте ему сферу.', 'Эта сфера вернула мне свободу. Вот твоя награда, смертный. Я всегда расплачиваюсь с долгами.', 'Наконец-то я на свободе!', NULL, NULL, 'Сфера Авруу (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9419, 'Истощение пустыни', 'Совсем недавно мы выяснили, что Орда добывает в Силитусе полезные ископаемые. Мы думали, что в таком климате не стоит держать много войск.$B$BК сожалению, выяснилось, насколько важны эти полезные ископаемые, и теперь мы тщетно пытаемся догнать Орду по масштабам добычи.$B$BЕсли ты хочешь мне помочь, ступай в пустыню и принеси оттуда силитист.', 'Найдите и принесите силитист к экстрактору силитистов и поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.', 'Хвала Свету! Ты добился успеха!$B$BНачни мы добычу кристаллов раньше, не оказались бы в таком отчаянном положении. Мы не допустим, чтобы сокровища пустыни попали в руки Орды.', 'Соблюдай осторожность, но не медли. Время на исходе.', NULL, NULL, 'Верните силитист', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9420, 'Прекрасное оперение', 'Араккоа из логова Хаал\'эш, что к югу отсюда, удалось вывести невероятных птиц, которых они называют калири. Перья этих калири оторвали бы с руками на любом базаре на Азероте. Только подумай, сколько бы эля я тогда смог купить!$B$BВот что я тебе скажу. Принеси мне перьев калири, и я отдам тебе свою собственную шляпу. Соглашайся, отличная сделка, такую шляпу ты больше нигде не найдешь! Ну что, по рукам?', 'Принесите Миррену Длиннобороду на полуострове Адского Пламени 8 перьев калири от различных калири из логова Хаал\'эш.', 'Ты выполнил свою часть сделки. Дело есть дело!$B$BВозьми, дружище. Заботься о ней как следует.', 'Ты принес мне перья калири, $C?', NULL, NULL, 'Перо Калири', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9421, 'Обучение шамана', '', '', 'Я Фирманваар. Ты не зря пришел ко мне. Мое призвание - учить молодых шаманов, особенно тех, что лишь теперь ступают на этот путь.Дренеи заново открывают для себя шаманизм, $N. Избрание не самого накатанного пути требует особого мужества.Я с радостью помогу тебе, как только ты сочтешь, что пришло время снова поучиться.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9422, 'Истощение пустыни', 'Мы давно начали добычу кристаллов пустыни Силитуса. Поначалу мы сталкивались лишь с опасностями, исходящими от местных жителей, песка, пыли и жары.$B$BТеперь же Альянс пронюхал, чем мы тут занимаемся, и началась гонка за добычей полезных ископаемых.$B$BУ меня каждая пара рук на счету, надеюсь, ты мне тоже поможешь.', 'Найдите и принесите силитист к экстрактору силитистов и поговорите с генералом Кирикой в лагере Орды возле Улья Регал.', 'Ты молодец, $N. Мы отправим добытые ресурсы на склад, а наши приобретения все равно что потери для наших врагов!', 'Пустыня очень опасна,будь настороже, $N. В барханах шныряют сторонники Альянса, и каждый шаг может оказаться последним.', NULL, NULL, 'Принесите силитист', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9423, 'Возвращение к Обадию', 'Вы получили подтверждение смерти Седаи, так что придется вернуться к Обадию с мрачными новостями.', 'Возвращайтесь к анахорету Обадию в храм Телхамат на полуострове Адского Пламени и расскажите о смерти Седаи.', 'Седай, брат мой...$B$BЭти трусливые орки! Как они могли, он же был безоружен!$B$BОставь меня, $N. Спасибо, что принес эту горькую весть, но теперь мне нужно побыть наедине с собой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9424, 'Месть Макуру', 'Седаи был Макуру как брат. Мы все обязаны ему жизнью. Оменай называют Макуру безумным, но если они не станут мстить за Седаи, то они сами лишились ума!$B$BВ этом мире немногое принадлежит Макуру, но он отдаст тебе все, чем обладает, если ты отомстишь за Седаи.$B$BЯ видел маг\'харских рубак в холмах к северо-востоку. Они нас ненавидят! Они не заслуживают нашей пощады! Ступай, отомсти за Седаи! В качестве доказательства смерти принеси их ожерелья предков.', 'Принесите 10 ожерелий предков маг\'харов Макуру в храм Телхамат на полуострове Адского Пламени.', 'Да... Месть! Ты поступил как должно.$B$BВозьми это. Теперь оно приносит Макуру только горе...', 'Ты отомстил за Седаи?', NULL, NULL, 'Бусы предков маг\'харов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9425, 'Возвращение в Мельницу Таррен', 'Рад видеть тебя, $C! У меня есть задание как раз для тебя.$B$BМы лишь недавно вступили в Орду и должны убедить всех, что готовы их поддерживать и помогать в трудную минуту. Тогда и они с большей готовностью придут нам на помощь.$B$BСтупай в город Отрекшихся – Мельницу Таррен. Он расположен в предгорьях Хилсбрада, на юго-востоке. По прибытии поговори с советником Вечерней Зарей.', 'Отправляйтесь в Мельницу Таррен в предгорьях Хилсбрада и поговорите с советником Вечерней Зарей.', 'Ну и ну! Еще один из моих братьев. Отлично! Нам предстоит многое сделать для наших новых друзей-Отрекшихся. Пройдись по городу и выясни, кому из жителей нужна помощь.$B$BНе сомневаюсь, ты найдешь время, чтобы помочь всем!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9426, 'Пруды Аггонара', 'Много времени прошло с тех пор, как мы назвали эту землю Дренором. Демоническая печать безвозвратно ее изменила.$B$BЯ помню одно место, сейчас его называют пруды Аггонара. Когда-то там били благословенные источники, теперь же кровь демона Аггонара запятнала их самую суть. Оскверненная кровь породила гнусных тварей, от которых надо избавиться, если мы хотим очистить эти пруды. Ступай к востоку, к прудам, и уничтожь исчадья ужаса и прочую нечисть, которая там развелась.', 'Отправляйтесь к прудам Аггонара и убейте 6 исчадий ужаса и 6 волдырных гнилостней по просьбе Амаана Мудрого.', 'Да, я чувствую, что пруды очистились от скверны, пусть и не до конца.$B$BТы проделал большую работу, $N.', NULL, NULL, NULL, 'Исчадие ужаса убито', 'Волдырный гнилостень убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9427, 'Очищение вод', 'Я прошу тебя закончить дело, которое мы начали. Теперь, когда демоническое влияние ослабело, ты $gдолжен:должна: взять фиал Очищения и вылить его содержимое на сам источник скверны – тело Аггонара.$B$BКости демона лежат в самой северной части прудов. Будь $gосторожен:осторожна:, я думаю, что сущность Аггонара не полностью оставила этот мир.', 'Отправляйтесь к прудам Аггонара и используйте фиал очищения над телом Аггонара по просьбе Амаана Мудрого. После того как вода будет очищена от сущности Аггонара, возвращайтесь обратно к Амаану.', 'Сущность Аггонара воплотилась в его грязном порождении, Аггонисе. Теперь, когда демоны побеждены, мы можем начать восстановление изначальной чистоты прудов.$B$BПрими нашу благодарность, $N. Плоды твоих деяний изменят этот мир к лучшему.', 'Ты вернулся $N. Воды очищены от скверны?', NULL, NULL, 'Очистите сущность Аггонара', 'Фиал очищения (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9428, 'На заставу Расщепленного Дерева', '$gПосланница наклоняется поближе и переходит на шепот.>$B$BТвоя слава обгоняет тебя, $N! Я прошу тебя отправиться на заставу Расщепленного Дерева в Ясеневом лесу. Пешком туда проще всего добраться, если идти на запад через Дуротар и Степи, а потом на развилке повернуть на север.$B$BКогда прибудешь туда, поговори с советником Верным Солнцу. Только осторожнее, Ясеневый лес – место опасное!', 'Поговорите с советником Верным Солнцу на заставе Расщепленного Дерева в Ясеневом лесу.', 'Да, посланница мне уже сообщила, я тебя ждал.$B$BОна просто хочет, чтобы ты помог нам здесь, чем сможешь. Она что-то говорила насчет того, чтобы укрепить наши связи с остальной Ордой...$B$BПорасспрашивай здесь, на заставе - тут наверняка найдутся те, кому нужна помощь. Кроме того, я слышал, что на побережье, к западу отсюда, есть еще один форпост Орды, который называется форт Зорам\'гар.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9429, 'Путешествие в Темнолесье', 'Слышал я, что у королевства Штормграда есть настоящая заноза в боку - Сумеречный лес. Местность эта наполнена страхом и зловонием нежити.$B$BПоскольку мы пытаемся помочь им по мере сил, я хотел бы, чтобы ты $gотправился:отправилась: на юго-восток, в главное тамошнее поселение людей - городок под названием Темнолесье. Анахорет Делан будет ждать вас.', 'Поговорите с анахоретом Деланом в городе Темнолесье в Сумеречном лесу.', 'Приветствую вас, $C. Хотелось бы верить, что путешествие ваше обошлось без неожиданностей?$B$BЭти несчастные со всех сторон окружены исчадиями ночи. Мы хотим, чтобы вы оказали им посильную помощь и разогнали тьму.$B$BПобродите по городу, познакомьтесь с его жителями. Пожалуйста, $N, помогите им, чем сможете.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9430, 'Реликвии Ша\'наара', 'Чтобы видеть недоступное всем остальным, мне не нужны глаза. Я не стану осуждать тебя за то, что ты $gвыполнил:выполнила: просьбу Макуру. Я хочу, чтобы ты $gнаучился:научилась: не просто смотреть, но видеть.$B$BСтупай к юго-западу, в руины Ша\'наара и собери все реликвии, которые там найдешь. Если судьба будет благосклонна, нам попадется то, что нужно.$B$BВозможно, тебе покажется неясным смысл моей просьбы, $N, но отбрось всякие сомнения. Чтобы понять, нужно иметь терпение.', 'Отправляйтесь в руины Ша\'наара и соберите 10 реликвий Ша\'наара по просьбе Амаана Мудрого из храма Телхамат на полуострове Адского Пламени.', 'Тебе сопутствовала удача. Как я и надеялся, мы нашли то, что искали.', 'Ты принес реликвии Ша\'наара, $N?', NULL, NULL, 'Реликвия Ша\'наара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9431, 'Разный подход', 'Что син\'дорай делает здесь, на этой выветренной вершине в Тысяче Игл, так далеко от роскошных дворцов Луносвета?$B$BВсе очень просто. Мои собратья изгнали меня и сожгли все мои записи о натуральных лекарствах от магической зависимости.$B$BЗдесь я могу продолжать исследования, вот только реагентов у меня нет. Поэтому я буду бесконечно признательна, если ты соберешь немного очищающей земли с грохочущих булыжней, а потом отнесешь ее моему помощнику на заставу Белого Плеса. Булыжни обитают у западных игл.', 'Соберите 2 горсти очищающей земли с грохочущих булыжней и отнесите Визло Фингалету на заставу Белого Плеса.', 'Что? Она не сказала про лунный колодец? Так ведь у нее именно это и было на уме. Признаться, все это выглядит немного странно, но не буду же я в здравом уме лишаться клиента! Тем более - единственного.$B$BКонечно, я бы не сказал, что это очень благоразумно - лезть в поселок ночных эльфов и воровать воду из их колодца, но раз она за это платит, то стоит попробовать.', 'Письмо магистра Элозай немного запутанно, но я, кажется, понял, что она хочет от меня. Если у вас есть земля, про которую она упоминала, то я могу положить ее в сосуд для воды из лунного колодца.', NULL, NULL, 'Очищающая земля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9432, 'Дорога в Астранаар', 'Я рад, что ты $gпришел:пришла: на помощь. Тут тебе и правда найдется дело.$B$BМне хотелось бы, чтобы ты $gотправился:отправилась: в городок ночных эльфов Астранаар. Он расположен в Ясеневом лесу, огромном лесу к югу от Темного Берега на Калимдоре.$B$BПожалуйста, поговори с воздаятельницей Паланаарой, когда прибудешь туда, и посмотри, чем сможешь помочь местным жителям.', 'Отправляйтесь в Астранаар в Ясеневом лесу и поговорите с воздаятельницей Паланаарой.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9433, 'Проба из Лунного колодца', 'Да не смотри ты на меня так! Я ж не говорил, что пошлю тебя черпать воду из колодца фляжкой!$B$BЯ вот тут как раз... гм... настраивал одно изобретение для моего клиента. Эта штука, Роботрон, двигается с помощью портативной панели управления, которую я запрятал ее в кустах на границе с Таланааром. Вот, возьми это устройство, найди ту панель и включи робота - а он сам наберет воды.$B$BЕсли бы мой клиент прознал, что мы тут вытворяем с его заказом, он бы меня за уши подвесил!', 'На каменной игле, ближайшей к границе с Таланааром, в кустах спрятано устройство управления Роботроном 3000. Найдите ее и включите робота при помощи устройства, которое вам дал Визло. Подведите робота к западному краю Тысячи Игл, где находится застава Альянса под названием Таланаар, и прикажите ему набрать немного воды из Лунного колодца, после чего вернитесь к Визло Фингалету на заставу Белого Плеса.', 'Все вышло даже лучше, чем я хотел! Запиши за гоблинами еще одно гениальное изобретение!$B$BЕдинственная проблема в том, что оно безнадежно покрыто пылью. У меня вся жизнь уйдет на то, чтобы его отчистить и вернуть на место.$B$BХотя чего-чего, а времени у меня хватает.', 'Ну и как, сработало?', NULL, NULL, 'Вода из Лунного колодца Таланаара', 'Устройство управления Роботроном (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9434, 'Испытание тоника', '*Визло берет пробу воды из робота и кладет ее в ящик, где уже лежит земля, добытая с булыжней, и несколько других вещей*$B$BНу вот, заказ магистра Элозай готов. Передай ей, что мне очень понравилось с ней работать и что я желаю ей всяческих успехов в ее исследованиях.', 'Доставьте ящик с реагентами магистра Элозай на Заставу Вольного Ветра.', 'Замечательно, все на месте. Осталось только перемешать и посмотреть, что выйдет. Если этот тоник сработает так, как я предполагаю, то, возможно, я смогу ослабить зависимость от магии у моего народа.$B$BСмотри, Намисан, на твоих глазах вершится история! Подумать только - без твоей помощи у меня ничего бы не вышло!', 'Вам с Визло удалось собрать реагенты?', NULL, NULL, 'Ящик с реагентами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9435, 'Пропавшие кристаллы', 'Если что и можно с уверенностью сказать про Хилсбрад, так это то, что эти края обречены вечно жить в тени войны. Нападают даже на обозы с камнем.$B$BВ обычной ситуации нас не очень расстраивает утрата строительных материалов, но в последней поставке из Лазуритового рудника был ящик с редкими кристаллами, которые мне не терпится изучить. Отрекшиеся-налетчики перехватили обоз и угнали его на северо-восток, к недостроенной башне. Нам непременно нужны эти кристаллы, $C!', 'Отберите у нежити посылку с редкими кристаллами и верните ее Ураану из Южнобережья.', 'Хвала Свету! Судя по тону письма штейгера, в этом ящике содержались все кристаллы, найденные в руднике. Лишись мы их, может, таких бы и не нашлось.$B$BНе знаю, как тебя и благодарить.', 'Тебе удалось отобрать у Отрекшихся кристаллы?', NULL, NULL, 'Посылка с редкими кристаллами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9436, 'Изучение Кровавого Скальпа', 'Рад знакомству, $C. В последнее время я стал изучать боевые приемы различных племен троллей, и заметил одну особенность. Тролли племени Кровавого Скальпа, живущие в руинах Ткаши и Бал\'лал, пользуются той же тактикой, что и Амани северных лесов.$B$BУ них очень необычная магия, и благодаря ей они стали самым могучим племенем в здешних краях. Благодаря этому можно создать сильное оружие против Амани, но нужно докопаться до сути.', 'Немет Остроглаз из лагеря Гром\'гол попросил вас принести ему тотем Кровавого Скальпа, добыв его у шамана из племени Кровавого Скальпа.', 'Молодец. Вот что любопытно...$B$BНадпись на этом тотеме сделана на языке, незнакомом троллям, зато хорошо известном нам. Она гласит, что носитель сего - союзник элементаля воды по имени Найас и достоин владеть его силой.$B$BНеожиданно, но не так уж плохо, $N. Я бы хотел, чтобы ты помог мне и на следующем этапе.', 'Не подведи меня, $N. Если нам удастся овладеть магией племени Кровавого Скальпа, быть может, мой народ сможет справиться с угрозой, исходящей от племени Амани.', NULL, NULL, 'Тотем Кровавого Скальпа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9437, 'Сумерки \"Гонца Рассвета\"', 'От тутошних огров не жди ничего, кроме тупых шуток, дурного эля да мигрени.$B$BКогда мой корабль \"Гонец Рассвета\" пристал к здешним берегам, эти негодяи из Терамора смылись с моим грузом и последним членом экипажа. Я добрался сюда в поисках помощи, но эти самые ни на что не годные огры просто тупо смотрели на меня, пока я рассказывал им свою историю. $B$BМогу ли я надеяться на помощь $gотзывчивого:отзывчивой:|3-1($gраса:), в выяснении того, что случилось с моим грузом и в освобождении Итании из северной башни, к северо-востоку отсюда, куда они ее посадили?', 'Верните груз с \"Гонца Рассвета\" Балиндару Ясной Звезде в деревню Гиблотопь и спасите его первого помощника Итанию из рук тераморцев, из Северной башни.', 'Благодарю тебя, $N! Как только Итания передохнет, а я закончу подготовку к отплытию, я покину эти влажные пустоши и вернусь обратно к цивилизации.', 'Ты освободил Итанию и спас мой груз из рук этих проклятых пиратов?', NULL, NULL, 'Спасите Итанию из Северной башни', 'Груз с \"Гонца Рассвета\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9438, 'Донесение Траллу', 'Вождь ждал этой вести с того самого момента, как мы ступили в Запределье. Тебе выпала огромная честь доставить ему донесение о маг\'харах.$B$BПоторопись, $N. Возьми письмо, на нем стоит моя собственная печать. Для Тралла нет вести желанней, чем та, которую ты ему принесешь.', 'Отправляйтесь в Оргриммар и доставьте Траллу письмо Назгрела.', '*Вы видите, что напряжение уходит с лица Тралла по мере того, как он читает донесение Назгрела* $B$BМой народ... Мы должны отправиться к ним. Мы должны отправиться в Награнд как можно скорее!', 'Ты принес вести из Запределья? Докладывай немедленно!', NULL, NULL, 'Письмо Назгрела (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9439, 'Потерянный багаж', 'Это что же, Каргат? Матушки... Я ожидал что это какое-то поселение, оазис цивилизации в пустыне... $B$BДолжно быть, тут какая-то ошибка. Не может же быть эта клоака, кишащая немытыми, неотесанными дикарями, штаб-квартирой экспедиционных войск! Эти грубые варвары начали ржать во всю глотку, когда я сообщил, что меня ограбили дворфы Черного Железа и скрылись в направлении Крепости Ангор. Могу ли я рассчитывать, что ты поможешь мне вернуть мое имущество?', 'Верните советнику Сарофасу в Каргат вещи советника и рапиру советника из Крепости Ангор.', 'О, спасибо тебе, Лейнир! Как я мечтал переодеться! $B$BИ моя рапира! Честное слово, без нее я чувствую себя просто голым! $B$BТы будешь вознагражден за труды - никто не скажет, что Сарофас неблагодарен по отношениию к низшим, оказавшим ему помощь!', 'Ну что уставился?! Я вынужден торчать в этой дыре, не имея возможности даже сменить сорочку! Ты смог добыть мои вещи из этой кротовой норы, которую клан Черного Железа гордо именуют крепостью?', NULL, NULL, 'Вещи советника', 'Рапира советника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9440, 'Маленькие кусочки', 'Я совершенствую антидренейское оружие, и ты мне в этом поможешь.$B$BЗаблудшие - родня дренеям, хотя и отсталые, поэтому экспериментирую я на них. От тебя требуется скормить несколько зараженных Скверной кусочков еды их домашнему скоту. Они в свою очередь убьют и съедят эту скотину и попадут под власть проклятия. Я покажу этому анахорету Авууну из Убежища!$B$BИди и поторопись! Ты найдешь Заблудших и их загоны для скота к северо-востоку от Болотного пристанища.', 'Накормите испорченными кусочками мяса домашний скот Заблудших. Потом верните отстатки Серсее Певице Заката в Каменор на Болото Печали.', 'Прекрасно! Жду не дождусь, когда смогу оценить эффект от последней партии!$B$BТы все сделал замечательно, прелесть моя. Я бы дала тебе и больше за то развлечение, которое ты мне устроил, но ты же знаешь, здесь на болотах денег днем с огнем не найти.$B$BНо я уверена, что забава того стоит!', 'Ты скормил скоту все оскверненные кусочки? Погоди! А тому глупому человечишке, что сидит у них в клетке? Ему - нет, я надеюсь?$B$BУф! Было бы очень жаль!', NULL, NULL, 'Попавшийся кроколиск накормлен', 'Пойманный ягуар накормлен', 'Пойманный тарантул накормлен', 'Зараженные Скверной кусочки мяса (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9441, 'Посол к маг\'харам', 'Принесенные тобой вести чрезвычайно важны. Я бы тотчас отправился в Запределье, но... Неотложные дела требуют моего присутствия в Дуротаре.$B$BКонечно, я немедленно отправлю маг\'харам подобающие дары. И отправлю с ними самых опытных и надежных дипломатов. Но все это потребует времени... А мне нужно, чтобы наш представитель отправился туда прямо сейчас!$B$BЯ полагаюсь на тебя, $N. Ступай на заставу маг\'харов на полуострове Адского Пламени и помоги моим родичам, чем можешь. Не подведи меня, $N! От тебя зависит слишком многое.', 'Вернитесь к Горкану Кровопалу на заставу маг\'харов на полуострове Адского Пламени и предложите ему свои услуги.', 'Для нас очень важно, что ты предлагаешь нам свою помощь в час нужды! Мы этого не забудем - ни тебе, ни тому, кто тебя прислал.$B$BМы благодарим тебя!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9442, 'Изнуряющая слабость', 'Я рада, что ты $gсогласился:согласилась: помочь нам, $N. Наши рубаки заболели, выпив зараженной воды, а у меня нет необходимых ингредиентов, чтобы создать целебную мазь. Мне нужен очень редкий гриб, который называется сухошляпка.$B$BЯ сама бы пошла его искать, но мы должны сохранять наше местоположение в строгом секрете, и рисковать никак нельзя. Единственное место, где на Полуострове Адского Пламени растут сухошляпки, - это Глубокий Разлом, он лежит к югу отсюда.$B$BБудь $gосторожен:осторожна:, когда отправишься искать его.', 'Принесите гриб-сухошляпку заклинательнице земли Риге с заставы маг\'харов на полуострове Адского Пламени. Сухошляпки растут только в пещере внутри Глубокого разлома.', 'Горкан хорошо отзывался о тебе. Похоже, он говорил правду.$B$BСпасибо за помощь.', 'Тебе удалось отыскать нужный гриб, $N?', NULL, NULL, 'Гриб-сухошляпка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9443, 'Так называемый знак Светоносного', 'Некогда я был учеником Утера Светоносного, основателя ордена рыцарей Серебряной Длани. Я сам видел, как неправильно он воспитал принца Артаса. Это привело к гибели моей родины, Кель\'Таласа, и я виню Утера в трагедии моего народа! А теперь он покоится в величественной гробнице - скажите, как мило.$B$BМои шпионы доносят, что эти алые идиоты держат на одной из сторожевых башен рядом с воротами Дольного Очага \"святую\" реликвию, связанную с Утером.$B$BОтправляйся в Западные Чумные земли и принеси ее.', 'Добудьте знак Светоносного и принесите его Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях.', 'Первый шаг сделан. Дай мне знак Светоносного и я превращу его в кое-что более подходящее.$B$BВот тогда-то и придет время моей мести, $C!', 'Когда тебе удастся добыть этот \"знак\", мы немного изменим его, сделаем получше.', NULL, NULL, 'Знак Светоносного', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9444, 'Осквернение гробницы Утера', 'Вот так-то лучше. Я наложил на этот знак магию скверны.$B$BА теперь отнеси его в место его упокоения в Западные Чумные земли. Воспользуйся оскверненным священным символом перед статуем Утера и оскверни тем самым его гробницу! Для этого придется подобраться поближе.$B$BГробница находится на юго-востоке от руин Андорала. Как выполнишь мое поручение, возвращайся ко мне.$B$BИ поторапливайся, $C!', 'Оскверните гробницу Утера и возвращайтесь к Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях.', 'Он прощает меня? ПРОЩАЕТ МЕНЯ?!!!$B$BМне наплевать, что болтает этот старый призрак, но это он во всем виноват! Трагедия Кель\'Таласа - результат его некомпетентности!$B$BЯсно одно, оскверненить гробницу не вышло. Убирайся! Я должен все хорошенько обдумать.', 'Итак, дело сделано? Ты уже осквернил гробницу Утера?', NULL, NULL, 'Могила Утера осквернена', 'Оскверненный знак Светоносного (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9446, 'Гробница Светоносного', 'Тебе удалось добыть знак Светоносного, остается отнести его к гробнице Утера.$B$BСходишь со мной? Это недалеко, а я буду рад твоему обществу. Потом можешь вернуться и рассказать о нашем путешествии верховной жрице Макдонелл.$B$BЧто скажешь, $N?', 'Проводите анахорета Трууна к гробнице Утера в Западные Чумные земли. После поговорите с верховной жрицей Макдонелл из Лагеря Промозглого Ветра.', 'Тебе явился Светоносный? Поразительно! Это результат твоей самоотверженной помощи анахорету.$B$BДаже если половина историй про Утера - правда, он был великим человеком. А ты, как и он, настоящий герой для всех существ доброй воли на Азероте!', NULL, NULL, NULL, 'Проводить анахорета Трууна к гробнице Утера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9447, 'Применение целебной мази', 'Из того, что ты мне $gпринес:принесла:, я приготовила мазь, которая восстановит силу наших рубак. Вот, возьми. Нанеси ее на всех изнуренных рубак, которых увидишь, и возвращайся ко мне.', 'Нанесите целебную мазь на 10 изнуренных маг\'харских рубак рядом с заставой маг\'харов на полуострове Адского Пламени по просьбе заклинательницы земли Риги.', 'Да благословят тебя духи, $N. Маг\'хары в долгу перед тобой.', 'С возвращением, $N. Ты выполнил мое задание?', NULL, NULL, 'Вылечено изнуренных рубак', 'Целебный бальзам (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9448, 'Милость к проклятым', 'Эта ведьма из эльфов крови - Серсея Певица Заката - заражает порчей Заблудших, я знаю это, и все тут! Я не знаю, зачем и как она это делает, но результаты ужасают. Некоторые из Заблудших еще сильнее подпали под влияние порчи, под воздействие еще более мощных энергий Скверны!$B$B$C, не проникаешься ли ты жалостью к этим несчастным существам? Они не должны прожить остаток дней своих под действием проклятья.$B$BТы найдешь этих несчастных в Болотном пристанище, по дороге к востоку отсюда.', 'Убейте 3 проклятых из племени Заблудших, потом вернитесь к анахорету Авууну в Убежище на Болото Печали.', 'Дело сделано. Я благодарю тебя за проявленное милосердие, однажды попав под власть того, что им скармливала Серсея, они уже были безнадежны. Сейчас они обрели покой, и я надеюсь, мое наблюдение за остальными принесет плоды, и они смогут исцелиться.', NULL, NULL, NULL, 'Проклятый из племени Заблудших убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9449, 'Зов земли', 'Выслушай меня, $N. Пришло время тебе поговорить с духами стихий напрямую.$B$BВпрочем, соблюдай осторожность. Мы оказались в этом мире случайно и невольно принесли ему зло, разъярили духов земли и нарушили природное равновесие.$B$BЕсли ты хочешь создать тотем Земли, поговори прежде с духом долины. Он находится в Священной роще, в холмах на северо-западе отсюда.', 'Поговорите с духом долины в Священной роще в долине Аммен.', 'Не думал, что кто-то из твоего народа отважится искать у меня мудрости, после того, что вы натворили на наших островах! Впрочем, храбрости тебе не занимать, так что знаниями я с тобой все же поделюсь.$B$BЗемля у тебя под ногами - основа всего сущего. Небо, вода, даже великий огонь - все опираются на ее плечи. Прочие стихии порой крушат все на пути своем, и лишь земля стоит крепко. Она дарует силу и стойкость всем, живущим на ней.$B$BА теперь покажи, на что ты способен, шаман.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9450, 'Зов земли', 'Крушение корабля дренеев привело к нарушению природного равновесия в этой долине. Духи Земли в ярости обратились против других стихий, пытающихся утихомирить их. Вскоре ты поймешь, как важна гармония стихий для их познания.$B$BИтак, я поручаю тебе восстановить исконное равновесие. За моей спиной располагается роща, в которой духи Земли воюют с тремя другими стихиями. Наведи там порядок.', 'Убейте 4 неупокоенных духов земли и возвращайтесь к духу долины в Священную рощу в долине Аммен.', 'Что ж, молодец. Сократив число неупокоенных духов ты помог восстановить равновесие стихий, невольно нарушенное твоим народом.$B$BПомни об этом, идя путем шамана и призывая нашу силу. Храни равновесие.', 'Стихии так и не пришли в равновесие, $N.', NULL, NULL, 'Неугомонный дух земли убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9451, 'Зов земли', 'Я передам тебе частицу моего физического облика, и ты положишь ее в основу своего тотема Земли. Отнеси эту частицу тому, кто послал тебя сюда.$B$BМы с тобой будем связаны навеки. До самой смерти силы Земли будут верно служить тебе, а отплатишь ты нам в тот миг, когда самая плоть твоя станет землей.$B$BПостарайся распорядиться своей силой мудро.', 'Отнесите кристалл Земли Фирманваару на место крушения в долине Аммен.', 'Молодец, $N. Восстановив природное равновесие в роще, ты достиг мира и согласия между стихиями этого мира и дренеями. Быть может, это привлечет на нашу сторону тех, кто с презрением смотрит на избравших путь шамана?$B$BЯ создам для тебя тотем, который позволит тебе подчинить силу Земли. Со временем тебе откроются и другие тайны земли.$B$BВозьми свой тотем, шаман.', 'Падшие и дренеи познают неведомые прежде тайны стихий.$B$BТы несешь мне все необходимое для создания тотема Земли?', NULL, NULL, 'Кристалл земли (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9452, 'Деликатесный красный луциан', 'Я обнаружила, что в этих водах много красного луциана - а это очень вкусная рыба! Сетью я могла бы наловить столько, что хватило бы на дюжину дренеев! К сожалению, недавно во время рыбалки на меня напала тварь, которую называют мурлоком. Из-за ран я не могу ловить рыбу. Помоги мне!$B$BПоставь эту сеть в водах Хрустальной реки на востоке, и у тебя будет огромный улов.$B$BЧто скажешь? Не забудь потом вернуть сеть.', 'Поймайте 10 красных луцианов рыболовной сетью дренеев. Отдайте рыбу и сеть Диктинне на острове Лазурной Дымки.', 'Надеюсь, мурлоки тебя не тронули, $N. Я глубоко тебе признательна.$B$BМожет, научить тебя ловить рыбу? Я готова подарить тебе удочку и блесну.', 'Остерегайся мурлоков: это странные и крайне надоедливые существа.', NULL, NULL, 'Красный луциан', 'Рыболовная сеть дренеев (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9453, 'Поиски Актеона', 'Великолепная работа, $N. Наш народ будет признателен тебе за рыбу. Кстати, не отнесешь ли наловленного красного луциана Актеону на Лазурную заставу?$B$BЕго будет несложно отыскать - он ждет этот улов.', 'Отнесите ящик красного луциана Актеону на Лазурную заставу.', 'Бедная Диктинна... Мурлок ее сильно напугал.$B$B<Актеон вздыхает.>$B$BНадеюсь, она скоро оправится от ран...$B$BПолагаю, ты ищешь работу. Чего-чего, а этого на Лазурной заставе хватает!', 'Тебе нравятся мои доспехи? Я сделал их сам! Они отличаются от привычных нам, но зато очень удобные.', NULL, NULL, 'Ящик красного луциана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9454, 'Великая охота на лунных оленей', 'Ты начинаешь завоевывать себе репутацию, $N. Не хочешь поучиться охоте?$B$BНа Дреноре наши величайшие охотники гнали дичь, похожую на лунных оленей здешних мест, талбуков.$B$BЕсли ты $gнастоящий дреней:настоящая дренейка:, отправляйся в лес и убей столько оленей, чтобы весь мешок набить мясом.$B$BОни пасутся на юге от Лазурной заставы. Остерегайся их рогов!', 'Принесите 6 кусков вырезки лунного оленя Актеону на Лазурную заставу.', 'Молодец, $N, молодец!$B$BПока ты охотился, я приготовил тебе немного вырезки. Может, ты и от рецепта не откажешься?', 'Шкура у оленей тонкая, зато мясо нежное, сочное.', NULL, NULL, 'Вырезка лунного оленя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9455, 'Странные находки', 'Похоже, найденный тобой в теле ночного ловца-недоростка кристалл – часть \"Экзодара\". Это объясняет необычную внешность и поведение некоторых животных этих земель.$B$BОтнеси кристалл на Лазурную заставу. Экзарху следует узнать о твоей находке.', 'Отнесите слабо мерцающий кристалл экзарху Менелаусу на Лазурную заставу.', 'Как такая вещь могла оказаться в желудке ночного ловца? Не заражены ли и другие звери осколками от разбившегося корабля?', 'Что ты нашел? Где?', NULL, NULL, 'Слабо мерцающий кристалл (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9456, 'Истребление ночных ловцов, остров 2...', 'Не буду скрывать от тебя горестного значения твоей находки. Здесь, несомненно, наша вина. До нас доходили сообщения об осколках кристаллов в реке на востоке, но мы не обращали на них внимания. Теперь же остается либо сидеть и сокрушаться о случившейся трагедии, либо постараться ограничить распространение заразы.$B$BЕсли тебе такое дело по плечу, отправляйся в лес и постарайся уничтожить как можно больше зараженных ночных ловцов.', 'Уничтожьте 8 зараженных ночных ловцов – недоростков и вернитесь на Лазурную заставу.', 'Надеюсь, еще не поздно...', 'Необходимо остановить распространение инфекции. Судя по сведениям с Кровавой заставы, дело плохо. Мы должны немедленно принять меры!', NULL, NULL, 'Зараженный ночной ловец-недоросток убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9457, 'Необычный посетитель', 'Так значит, за племенем Кровавого Скальпа и их необычной магией стоит Найас? Признаться, не думал, что расследование пойдет таким путем, но неважно, полученные сведения нам пригодятся.$B$BНедалеко от северо-западной части побережья находится остров, населенный малыми элементалями воды. Там есть грубая каменная плита, которая, должно быть, служила троллям алтарем для поклонения. Отнеси найденный тобой тотем на этот алтарь. Посмотрим, не удастся ли выманить этого Найаса и перелить его силу в более подходящую форму.', 'Воспользуйтесь даром Найаса неподалеку от алтаря Найаса и призовите этого элементаля воды. Одолейте его и принесите сердце Найаса Немету Остроглазу в лагерь Гром\'гол.', 'Я чувствую, как много первозданной силы заключено в этом камне, $N. Надо отправить его в Луносвет, нашим магистрам - пусть изучают. Я уверен в одном - он пригодится в нашей борьбе против Амани.$B$BТы оказал нам неоценимую помощь, добыв этот камень. Я прослежу, чтобы Странники узнали имя |3-1(таурен), нашедшего его.', 'Какие вести о Найасе ты несешь?', NULL, NULL, 'Сердце Найаса', 'Дар Найаса (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9460, 'Объединенными усилиями', 'Келтус Темный Лист для доклада явился!$B$BДа, а ты, собственно, кто $gтакой:такая:? Если хочешь получить мои донесения, сначала помоги мне.$B$BЯ тут собираюсь напасть на часовых-шпионов, но сначала хочу выслать вперед мою верную Шептунью. Однако ей нужен запах, чтобы знать, на кого нападать.$B$BУж конечно, тебе не составит труда подкрасться и стянуть какую-нибудь вещицу у их предводительницы?', 'Украдите у предводительницы часовых кружевной носовой платок и принесите его Келтусу Темному Листу.', 'Отлично! По этому запаху Шептунья без труда найдет дорогу...', 'Ну что, получилось?', NULL, NULL, 'Кружевной носовой платок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9461, 'Зов Огня', 'Пророк заинтересовался тобой, услышав об успешном прохождении испытания. Прежде чем создать Тотем огня, тебе следует поговорить с ним.$B$BМало кому выпадает эта честь, спеши в Экзодар на встречу с Пророком!', 'Найдите пророка Велена в Чертоге Света Экзодара.', 'Приветствую, $N. Я ждал тебя. Надеюсь, ты сегодня в добром здравии?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9462, 'Зов Огня', '$N! Пришло время двинуться дальше по пути духов. Отыщи Тулууна, шамана Лазурной заставы. Он начнет обучать тебя пониманию и усмирению силы пламени.', 'Поговорите с Тулууном на Лазурной заставе на острове Лазурной Дымки.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9463, 'Ради науки', 'Выяснилось, что побеги хлестунов, которые растут на острове, имеют целебные свойства. При правильной обработке из них получается сильнодействующая лечебная мазь. К сожалению, на Лазурной заставе так много раненых дренеев, что никаких запасов не хватает.$B$BНашу хрупкую гостью нашли вчера возле Хрустального ручья. Если ты принесешь мне побеги – кто знает, может быть, удастся ее спасти.$B$BКорнехватов можно отыскать на юге и на востоке от Лазурной заставы.', 'Принесите 8 побегов корнехватов анахоретке Фатиме на Лазурную заставу.', 'Будем надеяться, что мазь укрепит ее дух и поможет больной встать на ноги!', 'Боюсь, что состояние нашей больной стремительно ухудшается.', NULL, NULL, 'Побег корнехвата', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9464, 'Зов Огня', 'И снова тебя ожидает испытание. На сей раз ты $gдолжен:должна: понять хаотическую составляющую огня, если собираешься создать тотем, обуздывающий его силу.$B$BНа северо-востоке находится священное место огня, именуемое Тлеющая поляна. Среди ее опаленных деревьев стоит Пламенрав, могущественный элементаль огня, и с ним-то тебе и предстоит поговорить.$B$BСтупай к нему, и да хранят тебя все стихии Азерота.', 'Поговорите с Пламенравом на Тлеющей поляне на острове Лазурной Дымки.', 'В твоих глазах пылает жажда расти над собой и постигать новое. Отлично!$B$BТулуун послал тебя сюда, потому что верит, что ты -способный ученик и сможешь решить проблему, вызванную крушением вашего Экзодара.$B$BПосмотрим.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9465, 'Зов Огня', 'Один из моих соплеменников, Спесивец, сошел с ума после крушения вашего корабля. Он начал требовать от местных совухов поклонения.$B$BЭто необходимо прекратить! Никто не смеет выдавать себя за бога! Придется тебе восстановить равновесие.$B$BПервым делом надо отнять у них ритуальный факел, который безумные дикие совухи утащили в логово племени Тихвой на западе.$B$BВерни мне этот факел.', 'Верните ритуальный факел Пламенраву на Тлеющую поляну на острове Лазурной Дымки.', 'Видишь, он не гаснет. Это работа Спесивца, символ его заносчивости. Пламя должно поглощать то, что горит, и погибать само, чтобы возродиться вновь.$B$BЯ помог бы тебе затушить факел, но он должен пылать, чтобы ты смог справиться с Спесивцем. Пусть пока горит...', 'И где же факел?', NULL, NULL, 'Ритуальный факел', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9466, 'Разыскивается: Свирепая Черноскребка', 'Согласно приказу капитана следопытов, объявлена награда за голову крайне опасной твари, матриарха камнедеров, известной как Свирепая Черноскребка.$B$BВ последний раз ее видели в пещерах на дне Глубокого Разлома. В качестве доказательства смерти Черноскребки охотники должны принести ее когти.', 'Принесите когти Черноскребки капитану следопытов Венн\'рену в Соколиный дозор на полуострове Адского Пламени.', 'Ты достойный, $C, $N. Эта тварь унесла жизни многих охотников.$B$BВозьми награду, ты ее заслужил.', 'Ты слышал про Черноскребку?', NULL, NULL, 'Когти Черноскребки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9467, 'Зов Огня', 'Совухи из прибежища Лунных Крыльев на острове Серебряной Дымки, что на юго-западе, приняли Спесивца за бога и начали поклоняться ему. На самом деле он - падший элементаль, которого следует остановить. Этот факел - ключ к его низвержению.$B$BСпесивец требует, чтобы совухи устраивали в его честь возжигания. Устрой возжигание, и он явится на зов. Убей его и собери пепел. Затем вернись ко мне при помощи этой сферы.', 'Добудьте пепел Спесивца и принесите его и ритуальный факел Пламенраву на Тлеющую поляну на острове Лазурной Дымки. Вы можете воспользоваться сферой возвращения, чтобы телепортироваться к Пламенраву.', 'Сегодня ты усвоил важный урок. Это история о возрождении из пепла.$B$BВ нашем первом разговоре я упоминал, что огонь не только разрушает, но и обновляет. Благодаря тебе Спесивец не просто уничтожен;, он спасен - потому что восстанет из праха.', 'Даже не заговаривай со мной, пока не добудешь пепел Спесивца.', NULL, NULL, 'Пепел Спесивца', 'Ритуальный факел', 'Огнеупорная сумка', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9468, 'Зов Огня', 'Сегодня тебе удалось далеко продвинуться по пути постижения сути огня. Относись к нему с уважением, или пламя пожрет тебя!$B$BЯ оставил тебе немного пепла Спесивца. Используй его для создания тотема огня и помни все, чему ты $gнаучился:научилась:.$B$BА теперь возвращайся к Тулууну.', 'Отнесите пепел Спесивца Тулууну на Лазурную заставу на острове Лазурной Дымки.', 'Ты прошел очищение огнем и вышел из него обновленным, $N. Эти испытания подобны тем, через которые пришлось пройти дренеям. И, спасая Спесивца от него самого, тебе удалось установить связь со стихией огня этого мира.', 'Похоже, пламя опалило тебя. Насколько тебе удалось приобщиться к стихии огня?', NULL, NULL, 'Пепел Спесивца (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9469, 'Встреча с Перобородом', 'Когда меня, наконец, удостоят аудиенции с Фалстадом Громовым Молотом, я хочу, чтобы вместе со мной пошел один из наших лучших представителей среди дворфов.$B$BБольшим уважением среди них пользуется Перобород – во-первых, за его потрясающее мастерство дрессировки грифонов, а во-вторых, за его мудрость. Если кто и сможет убедить Фалстада Громового Молота, то только он.$B$BЯ бы сходил к Перобороду сам, но мне нельзя покидать Заоблачный Пик, потому что аудиенцию могут назначить в любой момент. Пожалуйста, сходи к нему и спроси, не согласится ли он поговорить со мной. Перобород живет на юге.', 'Навестите дворфа Пероборода в его домике. Если там его нет, то поищите, где он может быть.', 'В дневнике Пероборода очень много записей. Вы пролистываете его до конца и ищете в тексте информацию о том, где может быть хозяин.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9470, 'Жест доброй воли', 'Кроме дворфов и их грифонов во Внутренних землях живут еще и лесные тролли.$B$BЭти тролли считают, что дворфы оскверняют из священные земли, и никогда не упускают возможности напасть на грифонов. Отличный шанс снискать уважение клана Громового Молота – убить главу племени Сухокожих, знахаря Май\'джина. Это поумерит у троллей наглости. Май\'джин живет в гроте Богена, это к западу от Шадра\'Алора.', 'Убейте знахаря Май\'джина и его питомца-паука Чаказа по поручению посла Руалета с Заоблачного пика.', 'Большое спасибо, $N. Клан Громового Молота будет рады узнать, что противостоит племени Сухокожих не в одиночку. Пусть тролли знают, что на нашей стороне грифоны – глядишь, наглость свою и поумерят.', NULL, NULL, NULL, 'Знахарь Май\'джин убито', 'Чаказ убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9471, 'Охота на хищников', 'Дворфы из клана Громового Молота - верные товарищи и отличные дрессировщики для грифонов, у которых полно врагов, в особенности среди лесных троллей.$B$BОднако помимо троллей у них есть и естественные враги, например, волки. Один волк грифону не страшен, но они часто нападают стаей, потому что другой добычи здесь мало. Если уменьшить поголовье волков, то местные леса станут чуть безопаснее для грифонов, а дворфы будут нам благодарны.', 'Убейте 10 облезлых среброгривов и 5 среброгривых волков по поручению посла Руалета с Заоблачного пика.', '<Посол Руалет кивает и берет у вас отчет.>$B$BПрекрасная работа. Клан Громового Молота обязательно узнает о том, что поголовье среброгривов уменьшилось. Когда я встречусь с их предводителями, я непременно прослежу за тем, чтобы твои старания не прошли незамеченными перед Альянсом. Пожалуйста, прими это в знак моей благодарности, Дэломар.', NULL, NULL, NULL, 'Облезлый среброгрив убито', 'Среброгривый волк убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9472, 'Любовница Арелиона', 'У Арелиона было столько важных дел, а он тратил свое время на какую-то любовницу!$B$BТеперь-то мне все ясно. Виера Шепот Солнца, эта маленькая потаскушка... Я покажу ей, как переходить дорогу магистру!$B$BВозьми свиток. Разыщи Виеру и вымани ее из города. Когда это удастся, прочитай над ней заклинание.$B$BАрелион упоминал, что эта маленькая дрянь обожает вино, которое делают друиды. Я думаю, его можно найти в Кенарийском приюте, как раз в Зангартопи, к западу отсюда.', 'Выманите Виеру Шепот Солнца из поселения и примените к ней свиток воздаяния Каринды по приказу магистра Каринды из Соколиного дозора.', 'Отлично! Теперь эта предательница больше никогда не соблазнит ничьего мужа.$B$BВот, возьми за труды. Надеюсь, все останется между нами, $N.', NULL, NULL, NULL, 'Свиток Воздаяния Каринды использован', 'Свиток воздаяния Каринды', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9473, 'Другое решение', 'Эта девушка слишком слаба, чтобы ей помогла мазь. Должен быть другой способ...$B$BЛеса Лазурной Дымки хранят много тайн. Например, здесь можно отыскать редкое растение, которое зовется лазурный львиный зев. Некоторые считают его настоящей панацеей от всех болезней.$B$BТы сможешь отличить его от других растений Лазурной Дымки по цвету. Кроме того, он растет только у подножия лазурных сосен. Спеши!$B$BОстерегайся корнезубов, они питаются лазурным львиным зевом.', 'Принесите 5 луковиц лазурного львиного зева Дедалу на Лазурную заставу.', 'Смотри, как растение исцеляет больную.', 'Время на исходе! Торопись!', NULL, NULL, 'Луковица лазурного львиного зева', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9474, 'Знак Светоносного', 'То недолгое время, что я пробыл на Азероте, я посвятил изучению великих героев. Славнейший из них Утер Светоносный, преданный самым лучшим своим учеником, Артасом.$B$BЯ бы хотел почтить его память и отнести одну из утраченных им вещей к его гробнице. Говорят, что сторонники Алого ордена держат на одной из сторожевых башен рядом с воротами Дольного Очага реликвию Утера.$B$BПрошу тебя, $C, ступай и принеси ее.', 'Добудьте знак Светоносного и принесите его анахорету Трууну в Лагерь Промозглого Ветра, что Западных Чумных землях.', 'Спасибо, $C! Возвращение реликвии - большая радость для всех, кто чтит память Утера Светоносного.', 'Знак Светоносного - могущественный символ веры Утера в Свет.', NULL, NULL, 'Знак Светоносного', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9475, 'Похищенные яйца', 'Осмотрев скелет, вы понимаете, что это все, что осталось от бедного Пероборода. В одной руке скелет сжимает истлевший кусок бумаги, который вы осторожно вынимаете и разворачиваете. На бумаге от руки нарисована карта и нацарапаны какие-то заметки.$B$BСудя по всему, это схема Шадра\'Алор, и три местных храма тут отмечены крестиками - должно быть, именно там находятся украденные яйца. Вы прячете карту в сумку, чтобы потом, в безопасном месте, рассмотреть ее поподробнее.', 'Соберите 5 яиц грифона и принесите их послу Руалету на Заоблачный пик.', '<Вы отдаете послу яйца и рассказываете о том, что обнаружили в лачуге Пероборода и в Шадра\'Алоре.>$B$BТролли из племени Сухокожих убили Пероборода?$B$B<Риалет приходит в ужас, услышав об ужасной смерти дворфа и о ее последствиях:$B$BЯ понимаю, почему он пошел искать яйца сам, но лучше бы он привел с собой подмогу. Вне всяких сомнений, его смерть приведет Фалстада Громового Молота в ярость, и моя аудиенция будет вновь отложена на неопределенный срок.', 'Судя по вашему виду, вы принесли мне дурные вести. Что вам удалось узнать?', NULL, NULL, 'Яйцо грифона', 'Карта Пероборода', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9476, 'В поисках Пероборода', 'В последних записях дневника Перобород выражает свое беспокойство участившимися нападениями троллей из племени Сухокожих на грифонов клана Громового Молота и постоянными кражами грифоньих яиц. Разведка в маленьком поселении Сухокожих не дала никаких результатов.$B$BВ последней записи Перобород пишет о своих подозрениях насчет того, что за этими набегами может стоять знахарь Майд\'жин, а в самом последнем, поспешно накарябанном предложении говорится о том, что дворф собирался пойти в Шадра\'Алор и поискать яйца там.', 'Отправляйтесь в Шадра\'Алор и поищите следы Пероборода.', 'На алтаре лежит куча костей, с виду принадлежавших дворфу. Никаких особых примет не видно, но вы решаете осмотреть тело и убедиться в том, что это и впрямь останки Пероборода.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9483, 'Изысканные удовольствия жизни', '', '', 'Думаю, мы можем подружиться. Давай со мной, мы ведь не хотим ни с кем делиться, правда?', NULL, NULL, NULL, 'Кенарийская настойка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9484, 'Приручение зверя', 'Несомненно, тебе неоднократно доводилось охотиться на зверей и убивать их как ради пропитания, так и ради самозащиты. Но теперь тебе уже по силам подружиться с ними и использовать их способности в своих целях. Я научу тебя, как это сделать.$B$BВот, возьми этот магический хлыст приручения. Он позволяет временно подчинить себе дикого зверя и заставить его сражаться на твоей стороне. Начни с безумного дракондора, сравнительно мирной птицы. Они водятся поблизости от обители Странников. Когда управишься, возвращайся ко мне.', 'Приручите безумного дракондора с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.', 'Чтобы выдержать яростные атаки дракондора, тебе потребовалось немало мужества... Ну что, хватит ли тебе сил продолжить обучение?', 'Покорился ли тебе дракондор?', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите безумного дракондора', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9485, 'Приручение зверя', 'Молодец, $N! Ты быстро обучаешься понимать природу.$B$BМрачница – хитроумный охотник, она сочетает стремительность дракондора с яростью прыголапа. Мрачницы водятся к югу от реки Элрендар и нападают на злосчастных путников, которые забредают в Призрачные земли.$B$BИспользуй этот последний хлыст приручения, чтобы подружиться с мрачницей, а когда управишься, возвращайся ко мне.', 'Приручите мрачницу с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.', 'Ну что ж, $N, как видишь, больше мне тебя учить нечему. Ты уже знаешь, как подружиться с теми, кто прежде был для тебя лишь добычей. Теперь тебе осталось лишь выбрать себе союзника, наиболее подходящего тебе по повадкам.', 'Покорилась ли тебе мрачница?', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Мрачница приручена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9486, 'Приручение зверя', 'Взрослый прыголап - ловкий охотник. Сдружиться с ним непросто - ведь поначалу он считает тебя добычей. Но ты не отчаивайся.$B$BИспользуй хлыст приручения, подчини себе эту крупную кошку и попробуй поохотиться вместе с ней. Прыголапы водятся в Лесах Вечной Песни повсюду, и порой подходят совсем близко к жилью. Когда управишься, возвращайся ко мне.', 'Приручите взрослого прыголапа с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.', 'Да, у тебя достаточно сил и упорства. Тебе осталось пройти последнее испытание, после чего ты сможешь приручать зверей без помощи магии...', 'Ну что, удалось тебе поохотиться вместе с прыголапом?', NULL, NULL, 'Хлыст приручения (Прилагается)', 'Приручите взрослого прыголапа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9487, 'Волшебные разорители', 'Волшебные разорители – создания, наделенные неземной силой. Они защищены крепкой броней, их удары сокрушительны. Однако ты можешь обойти их защиту и избежать их атак. Твое заклинательское искусство дает тебе неоспоримые преимущества, $N.$B$BОтправляйся в башню Утренней Звезды и разнеси в клочья этих магических стражей. Из останков собери осколки кристаллизованной магический энергии, а потом возвращайся ко мне. Башня Утренней Звезды находится на востоке, за озером.', 'Чародей Вандрил хочет, чтобы вы принесли ему 10 осколков тайной магии.', 'Как же непродуктивно тратить магию на создание тварей, обладающих только физической силой! В конце концов, разве не ради грубой силы мы заключили союз с низшими расами?$B$BХорошо, что ты уничтожила их, теперь мы используем эти осколки для более подходящих целей.', 'Надеюсь, тебе удалось подобраться к этим тварям?', NULL, NULL, 'Осколок тайной магии', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9488, 'Простое одеяние', 'Те осколки тайной магии, что ты $gдобыл:добыла:, пригодятся как нельзя лучше.$B$BСпрашиваешь, для чего? Да для изготовления замечательного одеяния для $gтакого:такой:c: $C, как ты!$B$BНам нужно всего-то немного льняной ткани и паутинная железа. Железу можно добыть у любого паука-прядильщика, лучше у предварительно убитого.', 'Чародей Вандрил хочет, чтобы вы принесли ему 15 кусков льняной ткани и паутинную железу паука-прядильщика.', '', NULL, NULL, NULL, 'Льняной материал', 'Паутинная железа паука-прядильщика', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9489, 'Поднять боевой дух', 'А, $N! Хорошо, что ты здесь. Яростные атаки Плети вселяют отчаяние в души наших городских стражей...$B$BСтупай скорее на Тропу Мертвых к югу от города. Там стоят в дозоре Джела и ее следопыты. Благослови их, наполни их силой Света!', 'Примените \"Слово Силы: Стойкость\" к 6 следопытам из лесов Вечной Песни на Тропе Мертвых.', 'Следопыты говорят о твоем приходе с почтением и благоговением! Теперь ты видишь, как служит нам Свет? Он дает нам силы помогать другим, но только после того, как мы помогли себе сами...', NULL, NULL, NULL, 'Благословлено следопытов из лесов Вечной Песни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9490, 'Матриарх камнедеров', 'Все камнедеры - отвратительные, крайне опасные и злобные существа. Впрочем, обычные камнедеры - просто ручные зверюшки по сравнению с их матриархом Свирепой Черноскребкой.$B$BОна убила моего кузена и сожрала его безо всякой пощады. Ничего, в один прекрасный день она за это заплатит. Принеси мне доказательство ее смерти, и я отдам тебе все, что у меня есть. Договорились?$B$BВ одиночку ее не одолеть, тебе понадобится помощь. Помощь верных друзей с острыми клинками. Черноскребка обитает в пещере на дне Глубокого Разлома. Удачи тебе!', 'Добудьте когти Свирепой Черноскребки, которая обитает в Глубоком Разломе и принесите их Икану в храм Телхамат на полуострове Адского Пламени.', 'Да, я помню эти ужасные когти.$B$BВот, возьми, $N. Вряд ли эту тварь было так просто убить, так что ты заслужил свою награду.', 'Ты принес доказательство смерти Черноскребки?', NULL, NULL, 'Когти Черноскребки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9491, 'Не откажусь', 'Вчера сюда заявился до неприличия богатый торговец. Говорил о каком-то кольце \"чрезвычайной археологический важности\", которое вроде бы заперто в одном из бесчисленных погребальных сундуков в катакомбах Амани. Потом он еще долго рассказывал, сколько готов за это самое кольцо отвалить.$B$BДавай так: я добуду воровской инструмент, и если тебе удастся принести колечко, то отсыплю тебе столько, что на десяток колечек хватит!', 'Эраланна из Транквиллиона хочет, чтобы вы добыли исцарапанное золотое кольцо из катакомб Амани.', 'Так это то самое кольцо и есть? Смотреть не на что. Но ты сама знаешь, сколько слухов ходит вокруг этого эльфийского хлама...$B$BКстати, не будем забывать о твоей награде - не стесняйся, можешь прокутить ее прямо здесь, сестричка!', 'Не говори мне, пожалуйста, что у тебя нет кольца! Иначе этот купец найдет другого желающего.', NULL, NULL, 'Исцарапанное золотое кольцо', 'Отмычки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9492, 'Новый поворот событий', 'Запределье живет в постоянном ожидании нападения орков, такова печальная истина. Было время, когда Сыны Лотара думали, что смогут оплатить безопасность Оплота Чести ценой собственной крови, но и это не принесло мира.$B$BТеперь Сыны не потерпят на своих землях никаких орков - ни зеленых, ни кориченевых, ни красных! Мы победим их или умрем, сражаясь. У нас есть шансы на победу, если мы сразимся с ними в цитадели Адского Пламени. Принеси мне оружие их самозванного вождя Каргата Острорука, и я щедро награжу тебя.', 'Принесите кулак вождя Каргата боевому командиру Данату Троллебою в Оплот Чести.', 'Отличная работа, $N. Твоя победа - это сокрушительный удар по оркам из цитадели Адского Пламени.$B$BЯ должен обсудить с боевым командиром Ромусом наши дальнейшие действия. Мы хотим вынудить орков Скверны уйти в глухую оборону. Теперь, получив подкрепление, мы способны на нечто большее, чем просто оборонять Оплот Чести.', 'Ты принес мне подтверждение гибели \"вождя\" Каргата Острорука?', NULL, NULL, 'Кулак вождя Каргата', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9493, 'Элита Орды Скверны', 'Мы мало что знаем об Орде Скверны, хотя за информацию заплачено многими жизнями.$B$BКаргат Острорук командует безжалостными, закаленными в боях воинами, чьи возможности к тому же усилены магией скверны. У этого войска есть своя элита – легионеры, воители и центурионы из клана Изувеченной Длани. Они внушают страх обычным солдатам и исполняют роль офицерского состава.$B$BЕсли мы хотим добиться хоть каких-то успехов в сражении с Ордой Скверны, сначала надо лишить ее командования.', 'Убейте 8 легионеров клана Изувеченной Длани, 4 центуриона клана Изувеченной Длани и 4 воителей клана Изувеченной Длани по приказу боевого командира Ромуса из Оплота Чести.', 'Какие хорошие новости, $N, в самом деле. Если мы разберемся с цитаделью Адского Пламени, то сможем начать охоту за орками Скверны по всему полуострову, да что там – по всему Запределью!', NULL, NULL, NULL, 'Легионер клана Изувеченной Длани убито', 'Центурион клана Изувеченной Длани убито', 'Воитель клана Изувеченной Длани убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9494, 'Угли Скверны', 'Наши твердолобые азеротские академики слишком засиделись в своих башнях. Пришло время показать им, что такое настоящие исследования! Дескать, они боятся играть с огнем. Ничего, как только у меня окажется огонь, я вдоволь с ним поиграю!$B$BВ Разрушенных залах цитадели Адского Пламени главный чернокнижник Пустоклят достиг невероятного магического мастерства, используя силу двух странных жаровен. $N, возьми сосуд, в котором он хранит угли Скверны, достань один уголь и принеси мне.', 'Принесите уголь Скверны волхву Забраксис из Оплота Чести.', 'Отлично, отлично! В мои планы не входит повторять подвиги чернокнижника Пустоклята, но надо быть полным дураком, чтобы не замечать силы угля Скверны.$B$BПравда, исследования вроде моего хотят запретить, так что все нужно держать в секрете. $N, ты ведь никому не расскажешь?', '*Волхв Забраксис оглядывается на Амитиэль Странницу Туманов и понижает голос\"$B$BНу что, где ээээ... уголь?', NULL, NULL, 'Уголь Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9495, 'Воля Вождя', 'Вырвать орков из уз нашей проклятой крови было не так просто, $N. Вождь Тралл повидал слишком много героев, которые пали под ударами судьбы. Похоже, теперь к ним следует присоединить и Каргата Острорука.$B$BВ Разрушенных залах цитадели Адского Пламени Каргата называют \"вождем\" Орды Скверны. Он и орда его безумных, жаждущих крови орков не остановятся, пока не сотрут Траллмар с лица земли. Вождь Тралл приказал нам любой ценой остановить Каргата.', 'Принесите кулак вождя Каргата Назгрелу в Траллмар.', 'Отличная работа, $N. Когда-то Каргат был славным воином, героем и вождем своего народа.$B$BМы все скорбим об этой потере, особенно Вождь Тралл. Орки Скверны еще заплатят за то, что случилось с Каргатом. А пока что пусть его падение послужит уроком для всех нас.$B$BВВ награду за служение Орде, $N, выбирай любое оружие.', 'Ты принес доказательство смерти Каргата?', NULL, NULL, 'Кулак вождя Каргата', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9496, 'Элита Орды Скверны', 'Даже если не считать ругани Изуверского Кулака, с Ордой Скверны шутки плохи.$B$BКаргат Острорук командует безжалостными, закаленными в боях воинами, чьи возможности к тому же усилены магией Скверны. У этого войска есть своя элита - легионеры, воители и центурионы Изувеченной Длани. Они внушают страх обычным солдатам и исполняют роль офицерского состава.$B$BЕсли мы хотим добиться хоть каких-то успехов в сражении с Ордой Скверны, сначала надо лишить ее командования.', 'Убейте 8 легионеров клана Изувеченной Длани, 4 центуриона клана Изувеченной Длани и 4 воителей из клана Изувеченной Длани по приказу темного охотника Туджина из Траллмара.', 'Прекрасная работа, $N. Теперь, когда Орда Скверны лишилась своих легионеров, ее будет гораздо легче одолеть на поле боя.', NULL, NULL, NULL, 'Легионер клана Изувеченной Длани убито', 'Центурион клана Изувеченной Длани убито', 'Воитель клана Изувеченной Длани убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9498, 'Соколиный дозор', 'Мы отстроили Соколиный дозор совсем недавно, и теперь это наша военная база на юго-западе полуострова Адского Пламени, совсем рядом с цитаделью. Союзникам вроде тебя, $N, здесь всегда рады.$B$BЕсли ты ищешь работу, то отправляйся к капитану следопытов Венн\'рену и скажи, что тебя послал я. Он поручит тебе что-нибудь достойное.', 'Доложитесь капитану следопытов Венн\'рену в Соколином дозоре на полуострове Адского Пламени.', 'Добро пожаловать в Соколиный дозор, $R. Союзникам Орды здесь всегда рады, особенно, если их рекомендовал Мартик.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9499, 'Соколиный дозор', 'Ты что до сих пор здесь делаешь, $N? Не $gслышал:слышала:, что ли - мы основали свою собственную, син\'дорайскую заставу на полуострове Адского Пламени!$B$BПоверь, среди эльфов крови гораздо комфортнее, чем среди этой... эээ... вонищи. Соколиный дозор находится к юго-западу отсюда, как раз рядом с цитаделью Адского Пламени. Поговори с капитаном следопытов Венн\'реном, он о тебе позаботится.$B$BДорога довольно опасна, к тому же патрулируется разведчиками Альянса. Я бы не рекомендовал отправляться в одиночку. Лучше присоединись к какой-нибудь компании, лучше всего эльфов крови.', 'Отправляйтесь в Соколиный дозор, на юго-запад полуострова Адского Пламени, и поговорите с капитаном следопытов Венн\'реном.', 'Добро пожаловать в Соколиный дозор, брат. Не всем эльфам крови посчастливилось так далеко забраться.$B$BЧто ж, очень жаль. Впрочем, наша работа в Запределье только начинается.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9500, 'Зов Воды', 'Я чувствую, много времени прошло с тех пор, когда тебе довелось пройти последнее испытание... О тебе спрашивал предсказатель Нобундо. Должно быть, твоя мудрость возросла – ибо ныне тебя призывают, дабы открыть тебе тайны стихии воды.$B$BПолагаю, тебе не нужно напоминать, где в Кристальном зале Экзодара ты сможешь найти предсказателя. Я права?', 'Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9501, 'Зов Воды', 'Водяница, могущественный элементаль воды, пожелала встретиться с тобой. Судя по всему, со стихией воды на острове Кровавой Дымки происходит что-то неладное. Ничего удивительного, впрочем – если принимать во внимание, насколько странно эльфы крови относятся ко всему, что их окружает.$B$BУ северного берега острова Кровавой Дымки есть подводный риф, ты найдешь Водяницу там.$B$BВозьми это зелье – когда ты войдешь в воду возле рифа, оно поможет тебе попасть к Водянице.', 'Найдите Водяницу у Подводного Рифа возле острова Кровавой Дымки и поговорите с ней.', 'Не страшись, $N. Просто мы, духи, предпочитаем общаться телепатически.$B$BЯ благодарна предсказателю Нобундо за то, что он прислал тебя сюда. Воды острова Кровавой Дымки и море у его берегов отравлены скверной. Можно представить себе, что эта вода творит с животными и растениями...$B$BНадеюсь, если мы возьмемся за дело вместе, то нам удастся исцелить зло, причиненное этой земле, и очистить ее воды.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9502, 'Зов Воды', 'Я чувствую, много времени прошло с тех пор, как тебе довелось пройти последнее испытание... О тебе спрашивал предсказатель Нобундо. Должно быть, твоя мудрость возросла – ибо ныне тебя призывают, дабы открыть тебе тайны стихии воды.$B$BПолагаю, тебе не нужно напоминать, где в Кристальном зале Экзодара ты сможешь найти предсказателя. Я права?', 'Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним.', 'Вот мы и встретились снова. Я вижу, избранный тобою путь шамана не был ошибкой, а твои успехи доставляют мне истинную радость.$B$BИтак, для тебя настало время постижения стихии Воды: ты познаешь ее тайны, и Вода примет тебя, открыв тебе свою сокровенную суть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9503, 'Зов Воды', 'Вода - источник жизни и залог существования всего сущего, благословение, заставляющее расцветать бесплодную землю и гасящее всепожирающий огонь... Однако отравленная вода способна нести погибель.$B$BМы должны понять, насколько велик ущерб, нанесенный источникам воды. К юго-западу отсюда находится Смрадный пруд. Тебе нужно отправиться туда и добыть смрадную эссенцию водяных духов, обитающих в пруду.', 'Принесите 6 бутылочек смрадной эссенции на остров Кровавой Дымки в храм Сокрытого Рифа и отдайте Водянице.', 'Благодарю тебя, о избравший путь шамана! Полагаю, этого будет достаточно, и я смогу понять, в чем суть скверны. Тогда мы, быть может, сумеем найти пути ее исцеления...', 'Смрадная эссенция - вот все, что осталось от моих злосчастных сестер... Неужели тебе удалось достать ее так быстро, $N?', NULL, NULL, 'Смрадная эссенция', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9504, 'Зов Воды', 'Дела обстоят хуже, чем я думала. Скверна может распространиться до самого океана и по всему Азероту вместе с океанскими течениями...$B$BЧтобы не дать этому случиться, нам нужен образец самой чистой воды, какую только можно достать. К юго-востоку отсюда, на нетронутой скверной части острова, находятся руины. Отправляйся туда и найди фонтан, который охраняют наги из племени Зловещей Чешуи.$B$BНаполни этот бурдюк водой из фонтана. Прошу тебя, $N, не медли!', 'Наполните пустой бурдюк, а затем вернитесь на остров Кровавой Дымки в храм Сокрытого Рифа и отдайте бурдюк Водянице.', 'Вода легко расступается; но стремительной реке или океанской волне не сможет противостоять ни одна стихия.$B$BМы подобны реке и волне, $N; мы - сила воды, которой нет преград! Мы, а не те, кто отравил остров Кровавой Дымки!', 'Ну как, принес чистую воду из руин?..', NULL, NULL, 'Наполненный бурдюк', 'Пустой бурдюк', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9505, 'Пророчество Велена', 'Пророк предвидел наступление этого дня. Он говорил, что на острове в новом мире мы найдем союзников.$B$B\"Нам предстоит испытание. Они попросят нас искупить грехи наших отцов...\"$B$BТогда мы не поняли значения его слов, но, видя это существо и его реакцию на наше появление, мы все яснее видим, о чем было пророчество. Даже здесь почувствовали падение дренеев.$B$BСтупай на юг. Именно там мы нашли это существо. Найди ее родичей и поведай им о нашем народе.', 'Отправляйтесь на юг и отыщите народ, о котором говорило раненое существо.', 'Ты говоришь, что найдена одна из наших? И что она ранена? Я немедленно пошлю в вашу деревню одного из своих воинов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9506, 'Начало положено', 'Я – адмирал Одиссий из командования ВМС Альянса. Наш корабль был вынужден причалить к острову из-за своего рода нашествия. Мне даже неловко говорить об этом, но в трюмах обоих кораблей ухитрились спрятаться гоблины.$B$BПрошлой ночью, когда большая часть команды спала, они нанесли удар!$B$BЕще удивительнее то, что они украли наши навигационные приборы и спрыгнули с корабля!$B$BВоры скрылись в чаще к востоку отсюда. Не поищешь ли ты наше оборудование? Ты $gоказал:оказала: бы нам большую услугу.', 'Верните адмиралу Одиссию морской компас и морскую карту, украденные Торговой компанией.', 'С такими способностями ты далеко пойдешь! При помощи навигационных принадлежностей мы сможем определить, далеко ли отклонились от курса.$B$BВпрочем, стой, что это? В карту что-то завернуто. Посмотрим...$B$BЭто приказы шефа Разданка из Торговой компании. Согласно этим планам, они должны собрать на острове все кристаллы и похитить наши корабли.$B$BКлянусь кустистыми бровями Бронзоборода! Вот зачем нас заставили причалить! Но как они прознали о наших планах?!$B$BЭто предательство...', 'Как продвигаются поиски, незнакомец?', NULL, NULL, 'Морской компас', 'Морская карта', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9508, 'Зов Воды', 'Мне удалось определить, что является источником порчи. Это побочный продукт неких безумных опытов, которым нужно положить конец. И займешься этим ты!$B$BК юго-западу от Смрадного пруда находится небольшой лагерь. Там проводит свои \"исследования\" Телатион Нечистый - и именно оттуда распространяется мерзость, отравляющая воды острова.$B$BИспользуй чистую воду из Ясеневого леса, чтобы уничтожить бочки в его тайном хранилище. Не сомневаюсь, это выманит Телатиона из его логова.$B$BМы положим конец этой мерзости!', 'Принесите голову Телатиона на остров Кровавой Дымки в храм Сокрытого Рифа и отдайте Водянице.', 'Итак, дело сделано! Кризис предотвращен. Благодаря тебе воды острова Кровавой Дымки снова станут чистыми, избавившись от скверны.$B$BК сожалению, эльфы крови не понимают, что, оскверняя все вокруг, они тем самым убивают и самих себя...', 'Надеюсь, ты добился успеха?', NULL, NULL, 'Голова Телатиона', 'Бурдюк с чистейшей водой (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9509, 'Зов Воды', 'Я сохранила немного воды из Ясеневого леса; не потому, что не верила, что ты справишься с ситуацией, нет, я даже скорее была уверена в успехе... Мне просто показалось - будет неплохо, если ты сможешь принести Нобундо что-нибудь особенное.$B$BВот, держи, $N, полный флакон чистейшей воды. В обмен на него ты получишь могущественный водяной тотем.$B$BПредсказатель Нобундо ждет твоего возвращения в Экзодаре.', 'Отнесите флакон чистейшей воды предсказателю Нобундо. Его можно найти на острове Лазурной Дымки в Экзодаре.', 'Ты мудр не по годам, $N. Я чувствую, что дух воды доволен тобой. Великой честью для меня будет воплотить самую суть принесенной тобой чистой воды в водяном тотеме.$B$BПомни уроки, что дала тебе стихия воды; надеюсь, со временем тебе удастся глубже проникнуть в ее тайны и постичь ее силу.', 'Духи стихий поведали мне о твоих великих деяниях. Что ж, поговорим...', NULL, NULL, 'Флакон чистейшей воды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9510, 'Шкура щетинистого копытня', 'Хочешь сделать что-нибудь полезное? У нас постоянная нехватка шкур копытня, $N.$B$BЭти звери водятся на юго-западе, рядом с Соколиным Дозором, их там тьма тьмущая. В кожевничестве нет ничего лучше, чем шкура копытня. Если сумеешь добыть их, я в долгу не останусь.', 'Добудьте 5 шкур щетинистого копытня по просьбе поставщика Бракнара с Заставы маг\'харов на Полуострове Адского Пламени.', '', NULL, NULL, NULL, 'Шкура щетинистого копытня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9511, 'Боевые планы Каргата', '<TXT>В документах, обнаруженных на теле Каргата, подробно излагается план вторжения в Оплот Чести.', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9512, 'Крабовый супчик поваренка', 'Адмирал прав, в тебе и впрямь кладезь талантов. Не поможешь Поваренку?$B$BЕсли я снова подам на обед курицу, команда меня утопит.$B$BЯ смотрю, вдоль берега бродят крабы – и сколько! Притащи мне крабьего мяска, и можешь считать – я твой должник.$B$BВыручишь бывшего пирата?', 'Принесите 6 кусков мяса шустрых крабов \"Поваренку\" Максоусу в лагерь Одиссия.', 'Ой, спасибо тебе огромное, незнакомец. Команда сразу взбодрится!', 'Гр-р-р... Яр-р-р... Лопни моя селезенка... Ой, прости, парень, приходится балакать иногда по-пиратски, а то совсем разучусь...', NULL, NULL, 'Мясо шустрого краба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9513, 'Возвращение руин', 'Хотя многие считают наше затруднительное положение следствием несчастливой случайности, я чувствую, что мы недаром оказались здесь. Невидимая рука судьбы подтолкнула нас к этой земле. Для чего – со временем станет ясно.$B$BК западу отсюда находится древний эльфийский город, лежащий в руинах и заселенный нагами. Мне не хотелось бы сидеть сложа руки, пока наги оскверняют земли предков.$B$BТы $gнаделен:наделена: неплохими способностями, $C. Почти мой народ и очисти руины от нежеланных обитателей.', 'Убейте 5 мирмидонов, 5 наг и 5 сирен из клана Зловещей Чешуи для жрицы Кайлин Ил\'динар.', 'Хвала Элуне! Неприкаянные души теперь могут обрести покой.', NULL, NULL, NULL, 'Мирмидон из клана Зловещей Чешуи убито', 'Нага из клана Зловещей Чешуи убито', 'Сирена из клана Зловещей Чешуи убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9514, 'Покрытая рунами табличка', 'Вы не можете разобрать ни одного из символов на табличке. Быть может, прочесть таинственные руны сумела бы жрица?', 'Отнеcите покрытую рунами табличку жрице Кайлин Ил\'динар в лагерь Одиссия на острове Лазурной Дымки.', 'Нет, я не могу прочесть эти руны, но я знаю, кто может...', 'Нашел что-нибудь?', NULL, NULL, 'Покрытая рунами табличка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9515, 'Полководец Шрисс\'тиз', 'Вторжение наг может плохо для нас закончиться, $N. Мне приходилось видеть, на что они способны, и такого я ни одному живому существу не пожелала бы. Подозреваю, что их полководец Шрисс\'тиз прячется в пещере - скорее всего в западной части побережья.$B$BОтыщи полководца Шрисс\'тиза и положи конец его правлению.', 'Жрица Кайлин Ил\'динар из лагеря Одиссия попросила вас убить полководца Шрисс\'тиза.', 'Полководец Шрисс\'тиз мертв, и наги не скоро оправятся от этого удара. Теперь мы в безопасности... на время.$B$BДолжна признать, что я напрасно относилась к тебе с подозрением. Ты не имеешь ничего общего с мерзавцем Архимондом. Прими этот дар от ночных эльфов.', NULL, NULL, NULL, 'Полководец Шрисс\'тиз убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9516, 'Уничтожить Легион!', 'Я не потерплю их присутствия в нашем мире! Пылающий Легион чуть не унитожил нашу расу, и мы бежали сюда, чтобы построить себе новый дом в новом мире. Теперь они снова пришли. И мы снова отступили, и снова, и снова!$B$BДовольно! $B$BОстатки Легиона затаились к югу от Холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона. Это все, что осталось от полчищ, что некогда вторглись в этот мир.$B$BСтупайте же и перебейте сколько сможете, пока еще не поздно!', 'Уничтожьте 6 бичевательниц Маннорока, 6 стражей Скверны и 6 опаляющих инферналов, а затем вернитесь к воздаятелю Ведаару в Лесную Песнь в Ясеневом лесу.', 'Примите мое почтение и благодарность, $С. Может быть, нам все же удастся построить здесь новый дом, не страшась больше Пылающего Легиона.', NULL, NULL, NULL, 'Бичевательница Маннорока убито', 'Странствующий страж Скверны убито', 'Опаляющий инфернал убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9517, 'Напрасные усилия', 'Добро пожаловать в Лесную Песнь, $C. Там, где ныне стоят палатки, однажды вырастут дома, но для этого необходимы постоянные поставки строительных материалов. Я не посмею просить никого из наших рабочих рубить древние деревья этой рощи, но наши соседи на юге и западе не столь трепетно относятся к лесу.$B$BМы избавим лесорубов клана Песни Войны от избытков древесины, и заберем немного оскверненного дерева из цитадели сатиров на западе. Доставь древесину Кривокрону, который очистит ее для нас от порчи.', 'Доставьте 15 связок древесины Песни Войны и 5 связок оскверненной древесины Сатирнаара Кривокрону в Лесную Песнь.', 'Дерево, поваленное орочьими грубыми клинками, изуродовано так, словно его ураганом повалило. Из него ничего путного не построишь, но я очищу его от порчи и верну архитектору Немосу и его работникам. Хоть какое-то добро выйдет из этого лиха, в конце концов.', '*Древний со скрипом поворачивается к вам.*$B$BАрхитектор Немос сказал, что ты можешь доставить древесину, спасенную из лагеря лесогубов и мерзостного Сатирнаара?', NULL, NULL, 'Древесина клана Песни Войны', 'Связка оскверненной древесины Сатирнаара', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9518, 'Пособники разрушения', 'Лесозаготовки Песни Войны – нарыв на теле нашей истерзанной земли. Каждый раз, как нам удается пресечь их работу, надзиратель Гортак приказывает своим лесорубам удвоить усилия!$B$BТеперь орки валят столько леса, что даже использовать весь не могут, рубят живые стволы, когда у них бревна гниют за ненадобностью! Это плевок нам в душу, $N, и мы покажем им, что не потерпим дальнейшего разорения наших земель!$B$BСтупай и не ведай покоя, пока этот надзиратель Гортак и его пособники не будут мертвы!', 'Часовая Люсьель Шепот Звезд из Лесной Песни хочет, чтобы вы убили надзирателя Гортака, 2 пилотов крошшеров клана Песни Войны, 5 ордынских лесозаготовителей и 10 ордынских разведчиков.', '', NULL, NULL, NULL, 'Надзиратель Гортак убито', 'Крошшер клана Песни Войны убито', 'Ордынский лесозаготовитель убито', 'Разведчик Орды убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9519, 'Потерянная чаша', 'В области к западу отсюда, что нынче зовется Сатирнаар, некогда было прославленное святилище, которое возвел мой народ. В нем хранилась бесценная реликвия, чаша Элуны, доверенная хранителям святилища жрецами Элуны. Некогда к святилищу стекались пилигримы, дабы испытать целительную силу чаши, которой она, как говорят, обладала.$B$BМожет, это просто байки, но если в них есть доля правды, то эта святыня может стать ключом к возрождению нашего истерзанного леса. Мне надо точно это выяснить, $N.', 'Принесите чашу Элуны Кайнету Штилю в Лесную Песнь.', '', NULL, NULL, NULL, 'Чаша Элуны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9520, 'Демонические планы', 'Этот пергамент выронил демон, но что странно - он написан на Всеобщем! В нем упоминаются два имени - Диатор и Горганнон. Эти два  повелителя ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Лесную Песнь на севере отсюда – место, где основали свое поселение дренеи.$B$BВозможно, это заинтересует воздаятеля Ведаара из Лесной Песни?', 'Доставьте демонические планы воздаятелю Ведаару в Лесную Песнь в Ясеневом лесу.', 'Клянусь Семью Кристаллами Ата\'мала, этого не может быть! Они хотят напасть на нас здесь, в Лесной Песне?!$B$BНе будет этого, доколе я жив!$B$B<Воздаятель Ведаар сминает в кулаке пергамент с демоническими планами.>$B$BНет. Мы этого не допустим!', 'Что тут у вас, сударь?', NULL, NULL, 'Демонические планы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9521, 'Донесение с северного фронта', 'Борьбу с лесозагатовками Песни Войны ведет не только Лесная Песнь, $N. К юго-западу, на границе со Степями, в роще Среброкрылых, находятся Среброкрылые. Часовая Дальняя Песня из этой рощи направляет наши действия против тех, кто готов разорить наши земли.$B$BЯ немного припозднилась с отправлением моего последнего донесения часовой Дальней Песне, но покидать Лесную Песнь без сопровождения мне тоже не хочется. Если твой путь приведет тебя к роще Среброкрылых, передашь мое донесение?', 'Доставьте донесение часовой Люсьель часовой Дальней Песне в рощу Среброкрылых.', 'Благодарю за доставку этого донесения, $С. Из того, что пишет часовой Люсьель, видно, что оправдываются наши худшие опасения. С каждым нашим очередным успехом Орда все решительнее пытается нанести нам как можно больше урона.$B$BМы не можем позволить себе отступить. Судьба земель наших предков стоит на кону. Но если на границе будет больше таких, как ты, мы точно победим. Будешь ли ты биться вместе с нами?', 'Что у тебя такое, $C?', NULL, NULL, 'Донесение Люсьели (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9522, 'Больше никогда!', '$N, на твои плечи ложится обязанность сорвать нападение Пылающего Легиона! Твоя задача – уничтожить их предводителей. Остальные демоны, по большей части – безмозглые твари. $B$BГорганнона ты найдешь в каньоне Гибели Демона к югу за холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над грядой Гибели Демона. Чтобы найти эту гряду, отыщи уступ, по которому можно подняться из каньона Гибели Демона близ памятника Громмашу Адскому Крику.', 'Убейте Горганнона и Диатора Ищейку и вернитесь к воздаятелю Ведаару в Лесную Песнь в Ясеневом лесу.', 'Никогда более Пылающий Легион не потревожит нас в этих местах! Вы избавили нас от битвы, которую мы наверняка проиграли бы, $С.$B$BЯ приношу вам благодарность и глубочайшее уважение от лица Длани Аргуса. Для меня большая честь, что вы сражаетесь на нашей стороне.', NULL, NULL, NULL, 'Горганнон убито', 'Диатор Ищейка убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9523, 'Хрупкие предметы. Не кантовать!', 'Жрица говорит, что руины на западе отсюда – это разрушенный город ночных эльфов. Я сразу вспомнил, что говорил мой папаша про такого рода развалины: \"Сынок, если тебе попадутся эльфийские развалины, знай, что там полно эльфийских реликвий.\"$B$BЧто я за дворф, если не найму первого встречного, чтобы добыть эльфийские реликвии? Вперед!', 'Принесите 8 древних реликвий археологу Адаманту Железному Сердцу в лагерь Одиссия на острове Лазурной Дымки.', 'Папаша бы мной гордился! Его мальчик нагрел руки на первых же встреченных им эльфийских руинах... С твоей помощью, конечно. Да, не беспокойся, я не собираюсь присвоить себе все почести. Как тебя зовут? $N? Я непременно расскажу о тебе в Стальгорне.', 'Без реликвий можешь даже не возвращаться.', NULL, NULL, 'Древняя святыня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9524, 'Узник цитадели', 'Альянс, здесь? Тогда слушай внимательно, $C.$B$BКаргату удалось захватить несколько наших солдат. Среди них капитан Алина, один из самых важных офицеров. Надо успеть спасти ее, пока ее не казнили.$B$BОбо мне не беспокойся, я смоюсь отсюда, как только переведу дыхание.', 'Спасите капитана Алину в цитадели Адского Пламени до того, как ее казнят.Это задание выполняется только в героическом режиме.', '', NULL, NULL, NULL, 'Капитан Алина спасена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9525, 'Узник цитадели', 'Мне удалось сбежать из тюрьмы Каргата, $N. Сегодня должны казнить нескольких заключенных, и среди них одного очень важного офицера.$B$BЕсли мы потеряем капитана Костолома, это будет ощутимый удар для всей нашей армии. Ты $gдолжен:должна: сделать все, что в твоих силах, чтобы его спасти. Я бы отправился с тобой, но, к сожалению, я слишком слаб...', 'Спасите капитана Костолома в цитадели Адского Пламени до того, как его казнят.Это задание выполняется только в героическом режиме.', 'У меня прямо камень с души свалился, $C. Всегда был уверен, что умру на поле боя, покрытый кровью убитых врагов.', NULL, NULL, NULL, 'Капитан Костолом спасен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9526, 'Возрождение Холма Демонического Огня', '$gМалыш:Малышка:, к югу отсюда находится место, что зовется лесами Ночной Песни. С недавнего времени его называют Холмом Демонического Огня. Прискорбно видеть, как по этой земле бродят демоны и разносят везде свою порчу.$B$BНе поможешь ли ты возродить эту землю?$B$BУ меня есть несколько саженцев, которые я приберег на этот случай. Отнеси их на Холм Демонического Огня и посади их в кучи плодородной земли.', 'Посадите 8 древесных саженцев в кучи плодородной земли и вернитесь к Кривокрону в Лесную Песнь в Ясеневом лесу.', 'Добро. Хотя много твоих годов утечет прежде, чем эти саженцы превратятся в Древних, но со временем они помогут нам в борьбе против демонов на Холме Демонического Огня.$B$BСтупай же с миром, младший брат.', NULL, NULL, NULL, 'Посажено саженецев', 'Саженцы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9527, 'Все, что осталось', 'Долгие годы мы мирно жили на острове по соседству с совухами. Представь себе мое удивление, когда они наводнили наш берег и напали на нас!$B$BЯ сражался изо всех сил, но меня легко скрутили. Теряя сознание от жестоких ударов, я надеялся лишь на то, что моя семья не пострадает.$B$BКогда я пришел в себя, вокруг было тихо, но песок покраснел от крови. Их крови. Мою жену и дочь сожрали заживо.$B$BЯ не жажду мести, $N. Мне бы только похоронить как должно то, что от них осталось.', 'Верните Коулену останки его семьи.', 'Благодарю тебя, $N. Теперь их души упокоились в мире.', 'Мою жену звали Талриса, а дочь – Магвин.', NULL, NULL, 'Останки семьи Коулена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9528, 'Крик о помощи', 'Несколько недель назад на мою семью напали мурлоки и совуны. Мне удалось сбежать, но и мать и отца убили. Не знаю, как быть дальше, ясно одно: мне нужно вернуться домой – или в то, что осталось от дома... Помоги мне пробраться через лес!', 'Проводите Магвин через остров до дома.', '<По лицу Коулена струятся слезы радости.>$B$BЧем я смогу отплатить тебе, $N? Возьми эту фамильную драгоценность. Она символизирует священные узы дружбы, доверия и любви между ночными эльфами. Отныне и вовек ты мой брат...', NULL, NULL, NULL, 'Магвин сопровождена до безопасного места.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9529, 'Камень', 'Я уверена, что твой бес оказался полезным и даже забавным слугой, однако пора тебе подчинить себе более могущественное существо - демона Бездны.$B$BСтупай по Тропе Мертвых до переправы через реку Элрендар. Перейдя через реку, отыщи на южном берегу светящийся голубой камень и возьми его. Тогда ты поймешь, что тебе делать дальше.', 'Добудьте камень Бездны с Тропы Мертвых.', 'Вы смотрите на камень, и перед глазами все расплывается...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9530, 'Созревший план', 'Я давно подозревал нечто подобное, но теперь исчезли последние сомнения.$B$BСреди нас есть предатель.$B$BГоблинские планы прямо указывают на существование заговора. Поскольку я не могу представить, кто из моих людей нас предал, мне понадобится твоя помощь. Теперь никому из команды нельзя доверять.$B$BДля осуществления плана мне понадобится выдолбленный ствол и листья. Их можно поискать неподалеку от стоянки лесорубов к северу от нас. Охапки листьев ты и $gсам:сама: наберешь в лесу.', 'Принесите выдолбленный ствол и 5 охапок листьев адмиралу Одиссию в лагерь Одиссия на острове Лазурной Дымки.', 'Предупреждаю, я собираюсь дать тебе опасное поручение. Даже если ты откажешься от него, $N, я не разочаруюсь в тебе.', 'Обожаю, когда планы воплощаются в жизнь...', NULL, NULL, 'Выдолбленный ствол', 'Куча листьев', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9531, 'У деревьев есть уши', 'Если верить планам, предатель должен встретиться с предводителем гоблинов Гизлом в бухте на западном острове. Проследи за ними, $N.$B$BПомнишь, я просил тебя набрать листьев и принести выдолбленный ствол? Их-то ты и наденешь! Прекрасная маскировка.$B$BОтправляйся в бухту и посмотри, выставлен ли нагский флаг. Если да, то встреча должна вот-вот состояться. Замаскируйся и жди. В конце концов предатель заявится на встречу. Дождись окончания встречи и сообщи мне, кто этот негодяй.', 'Проследите за встречей Гизла с предателем.Расскажите обо всем увиденном адмиралу Одиссию.', 'Ушам своим не верю! Во всем виноват гном... и как я не догадался!', 'Предатель еще пожалеет, что связался с ВМС Альянса!', NULL, NULL, 'Предатель найден', 'Набор маскировки под дерево (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9532, 'Найти Келтуса Темного Листа', '$N, один из наших разведчиков чересчур увлекся своими обязанностями! Он неусыпно следит за нашими врагами, но при этом забывает присылать донесения о том, что ему удалось выяснить!$B$BНайди этого шпиона, Келтуса Темного Листа, убеди его сообщить, наконец, о том, что он узнал, и как можно быстрее возвращайся ко мне. Он далеко отсюда, на юго-западе, там, где река Элрендар расходится на два рукава и огибает деревню Золотистой Дымки. Келтус выслеживает ночных эльфов из Ан\'дарота, так что, должно быть, он где-то там.', 'Найдите Келтуса Темного Листа.', 'Надеюсь, ты соображаешь, что я надежно замаскирован... что я был надежно замаскирован?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9533, 'Рука помощи', 'Мой народ принялся за важное дело в восточной части Ясеневого леса при поддержке и помощи кальдораев.$B$BПод руководством архитектора Немоса и воздаятеля Ведаара они восстанавливают древний форт ночных эльфов. Это непростая задача, $N, ибо кругом много врагов. Я знаю, что архитектор Немос и его сторонники в Лесной Песни будут благодарны любой помощи, и он просил меня присылать к нему всякого, кого это заинтересует.', 'Отправляйтесь в Лесную Песнь и поговорите с архитектором Немосом. ', 'Радостно видеть нового гостя в Лесной Песни.$B$BПоборница Паланаар присылает на помощь столько народу, сколько может, и мы рады каждой паре рук.$B$BПосмотрите вокруг, $С. Может, сейчас вид не слишком впечатляет, но пройдет время, и при помощи наших союзников ночных эльфов мы построим здесь поселение, которое будет достойно называться домом. Сделать предстоит очень много, и любую помощь мы примем с радостью.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9534, 'Уничтожить Легион!', 'Остатки демонического Пылающего Легиона то и дело совершают налеты на наши лесозаготовки Песни Войны!$B$BХватит!$B$BЭти демоны лезут от холма Демонического Огня, каньона Гибели Демона и гряды Гибели Демона на востоке.$B$BСтупай и уничтожь их сколько сумеешь - и покроешь славой и себя, и Орду!', 'Уничтожьте 6 бичевательниц Маннорока, 6 стражей Скверны и 6 опаляющих инферналов, а затем вернитесь к Валуше на заставу Расщепленного Дерева в Ясеневом лесу.', 'Это куда лучше! Нет ничего достойнее, чем очищать наш мир от демонов. Да и противники они стоящие, не то что эти дохляки из Альянса.', NULL, NULL, NULL, 'Бичевательница Маннорока убито', 'Странствующий страж Скверны убито', 'Опаляющий инфернал убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9535, 'Демонические планы', 'Этот пергамент выронил демон, но что странно – он написан на орочьем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на заставу Расщепленного Дерева к северу отсюда.$B$BВы уверены, что это очень заинтересует Валушу на заставе Расщепленного Дерева.', 'Доставьте демонические планы Валуше на заставу Расщепленного Дерева, что в Ясеневом лесу.', 'Повелители ужаса! Они хотят напасть на заставу Расщепленного Дерева?!$B$BПока жива – не допущу!$B$B<Валуша сминает в кулаке пергамент с планами демонов.>$B$BНет. Они не пройдут! Они – погибель для нашего мира!', 'Что тут у тебя, брат?', NULL, NULL, 'Демонические планы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9536, 'Больше никогда!', '$N, сделай так, чтобы эта атака Пылающего Легиона сорвалась! Иди и убей этих повелителей ужаса! Остальные демоны, кроме них – по большей части безмозглые твари. $B$BГорганнона ты найдешь в каньоне Гибели Демона к югу за холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над грядой Гибели Демона. Чтобы найти эту гряду, отыщи уступ, по которому можно подняться из каньона Гибели Демона близ памятника Громмашу Адскому Крику.', 'Убейте Гроганнона и Диатора Ищейку.', 'Никогда больше Пылающему Легиону не поработить ни орков, ни какую другую расу Орды!$B$BТы отважный боец, $C! В груди твоей бьется сердце истинного сына Орды! Мы гордимся тобой!', NULL, NULL, NULL, 'Горганнон убито', 'Диатор Ищейка убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9537, 'Не ведая пощады', 'Перемолоттер должен быть привлечен к ответственности!$B$BСтупай на берег, отыщи там вероломного гнома и вытряси из него все возможные сведения!$B$BЕсли высокопоставленные представители Альянса способны на предательство, чего остается ждать от других?!$B$BИ последнее, $N: не колеблясь, применяй силу...', 'Добудьте для адмирала Одиссия переписку предателя у инженера \"Искра\" Перемолоттера', 'Немыслимо! Мы имеем дело с масштабным заговором!$B$BОб этом должен узнать король и ваши вожди. Последствия могут быть ужасны.', 'Удалось ли тебе отловить лживого шакала?', NULL, NULL, 'Переписка предателя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9538, 'Изучение языка', 'Кажется, я докопался до сути, $N!$B$B<Ауррен указывает на тотем.>$B$BВсе, что нам нужно знать о языке фурболгов из племени Тихвой, написано на их тотемах. Имея общее представление о том, как работают эти символы, мы можем изучить тотемы и научиться разговаривать с фурболгами.$B$BЗначения из таблицы символов я выписал на этот пергамент. Изучи его хорошенько, а потом займись тотемом. Он укажет тебе путь к следующему тотему языкознания.$B$BКогда изучишь язык, поговори с Аругу!', 'Изучите пергамент \"Язык фурболгов из племени Тихвой для начинающих\", полученный от Ауррена, а затем изучите тотемом Акиды на Лазурной заставе.', 'На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: \"А-К-И-Д-А\".', 'От тотема исходит негромкое гудение.', NULL, NULL, 'Чтение учебника языка фурболгов Тихвой.', '\"Язык фурболгов из племени Тихвой для начинающих\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9539, 'Тотем Ку', 'Вы начинаете читать надпись на тотеме, едва произнося непонятные слова и фразы. Постепенно смысл написанного становится ясен. Кажется, тотем велит отправиться на ближайший холм на северо-востоке.', 'Найдите тотем Ку с помощью проводника.', 'На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: \"Ку\".', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9540, 'Тотем Тикти', 'Вы начинаете читать надпись на тотеме, с большей легкостью произнося непонятные слова и фразы. Постепенно смысл написанного делается вам ясен. Кажется, тотем велит переправиться через Хрустальную реку на востоке. Быть может, Предназначение ждет вас по ту сторону реки.', 'Найдите тотем Тикти с помощью проводника.', 'На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: \"Т-И-К-Т-И\".', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9541, 'Тотем Йора', 'Символы этого тотема переводятся куда быстрее. Узоры и картинки превращаются в знакомые слова. Вы почти уверены, что тотем призывает вас двинуться на юг, вниз по реке. Что-то ожидает вас на дне реки.', 'Найдите тотем Йора с помощью проводника.', 'На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: \"Й-О-Р\".', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9542, 'Тотем Варк', 'Теперь все символы языка фурболгов вам хорошо знакомы. Надписи на тотеме Йора вы читаете свободно, как на родном языке.$B$BСудя по всему, на западе отсюда располагается еще одно селение фурболгов. Совершенное знание языка позволяет вам понять, что ваша цель – деревня Косолапов. Йор поведет вас, но если вы собьетесь с пути, то знайте: через лес, точно к месту вашего назначения, ведет древняя эльфийская дорога.', 'Найдите тотем Варк с помощью проводника.', 'Вы читаете надпись на тотеме, и губы сами собой произносят: \"В-А-Р-К\".', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9543, 'Искупление', 'Сколько длится наша история, столько мы и воюем с орками, $N. Однажды, одержимые жаждой крови, они чуть не истребили нас поголовно, и с тех пор мы предпочитаем держаться от них подальше, пусть даже им и удалось избавиться от власти демонов.$B$BА теперь... эта новая связь... Не скажу, чтобы она нас обрадовала. Поговори с нашим старейшиной, Амааном Мудрейшим, он поможет пролить свет на эти события.', 'Поговорите с Амааном Мудрым в храме Телхамат на полуострове Адского Пламени.', 'Что я могу сделать для тебя, $N? Ты выглядишь обеспокоенным.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9544, 'Пророчество Акиды', 'На тотеме изображена война между племенами Тихвой и Косолапов. Судя по всему, фурболги из племени Косолапов вытворяли немыслимые вещи с собратьями из племени Тихвой.$B$BИ вот среди хаоса начало сбываться пророчество: придет герой иной крови и спасет племя Тихвой.$B$BУбейте фурболгов из деревни Косолапов и отберите у них ключи. Отоприте клетки с пленниками из племени Тихвой. Освободив всех, возвращайтесь к Аругу из племени Тихвой.', 'Освободите 8 пленников из племени Тихвой из клеток в деревне Косолапов. Вернитесь к Аругу из племени Тихвой на Лазурную заставу.', '<язык фурболгов>: Пророчество гласило, что явится Избранный, который избавит нас от смертельной хватки Косолапов, и сами духи возвестят прибытие этого героя.$B$BИ вот ты здесь.$B$BПреклоняюсь пред тобой, о великий.', NULL, NULL, NULL, 'Освободите пленников из племени Тихвой', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9545, 'Реликвия ясновидца', 'Упрямцы ограничивают свой разум, утверждая, что истина может быть только одна. Но мудрые распахивают свой ум навстречу множеству вероятностей, которые коренятся в настоящем и прорастают в будущее.$B$BОтнеси эту реликвию туда, где ты $gнашел:нашла: Седаи. Смотри глазами, но видь разумом, $N,', 'Вернитесь к телу Седаи, которое находится к северо-востоку от храма Телхамат, и используйте там реликвию ясновидца по просьбе Амаана Мудрого из храма Телхамат на полуострове Адского Пламени. После выполнения задания возвращайтесь к Амаану.', 'Надеюсь, что видение, представшее твоим глазам, помогло понять, что случилось в результате смерти Седаи. Реликвия показала тебе ряд событий, которые могли бы привести к тому, что сейчас происходит. Правда может быть разной, и ее никогда нельзя знать точно.$B$BИзменился ли твой образ мысли теперь, когда ты обладаешь этим знанием?$B$BКто может сказать, продолжатся ли наши распри с орками? Важно оставаться открытым для всех возможностей.', 'Что тебе удалось увидеть, $N?', NULL, NULL, 'Видение явлено', 'Реликвия ясновидца (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9547, 'Зов воздуха', '$N, предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!$B$BЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.', 'Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9548, 'Украденное снаряжение', 'Тсс! Говори тише, не привлекай ко мне внимания.$B$BЕсли мурлоки меня обнаружат, весь эксперимент пойдет прахом! Я и так весьма близок к тому, чтобы утратить все полученные данные...$B$BВчера, пока я пополнял запасы, один из мурлоков, надо думать, подошел слишком близко и обнаружил мой лагерь. Я возвращаюсь – и что же вижу? Эти пучеглазые куда-то волокут ящик с моим снаряжением! Уверен, они его припрятали в одном из поселений. Только мне высовываться не резон, не будет от этого добра. Может, ты мне поможешь? А?', 'Верните Клопперу Бацбаху его оборудование. Клоппера можно найти в старом черепашьем панцире на берегу.', 'Фантастика, просто фантастика! Кража моего оборудования позволила мне узнать об этих мурлоках столько, сколько я не узнал бы за недели наблюдений!$B$BЯ уже знаю, что напишу в отчете.$B$B\"Столкнувшись с элементами значительно более развитой в технологическом плане культуры, мурлоки из племени Черного Ила не проявили ни малейшего любопытства, свойственного представителям развивающихся культур гуманоидов.\" Да! Именно так!$B$BЭто же просто шедевр! Уверен, в Стальгорне будут просто восхищены моим отчетом! Словами не выразить, как я тебе благодарен, $N!', 'Ну как, ты нашел мое оборудование?', NULL, NULL, 'Оборудование Клоппера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9549, 'Артефакты племени Черного Ила', 'Мои наблюдения и заметки о мурлоках из племени Черного Ила, несомненно, станут большим вкладом в науку, можешь мне поверить, $N. Однако все это - лишь начало. Я намереваюсь вернуться в Стальгорн и продемонстрировать там примитивные творения этого клана.$B$BОднако есть одно маленькое \"но\", мешающее осуществлению моих планов. Дело в том, что мурлоки постоянно носят нужные мне предметы при себе, а я не вынесу бремени убийства... Но если ты поможешь мне заполучить идолов, которых носят с собой провидцы племени Черного Ила, а также несколько ножей - из тех, которыми вооружены их воины, я не стану допытываться, как эти вещи попали к тебе.', 'Принесите 3 варварских идола и 6 варварских ножа мурлоков Клопперу Бацбаху, который прячется в старом черепашьем панцире на берегу.', 'Ошеломляюще! Потрясающе! Сногсшибательно! Эти артефакты - само совершенство! Представь себе, $N, как они будут смотреться в стеклянной витрине в музее Стальгорна! Нужно только снабдить их сопроводительным текстом...$B$BТвоя помощь была поистине неоценимой! Как пишется твое имя? Обещаю тебе, в самом скором времени ты прославишься как мой соавтор!$B$BДа, кстати, один из парней с корабля в уплату карточного долга дал мне вот это - говорит, это \"карта сокровищ\" или что-то в этом роде. Ну, моряцкие легенды и прочие суеверия меня никогда особо не интересовали...', 'Ну что? Ну как? Получилось у тебя, э-э, достать артефакты, которые я мог бы отправить в Стальгорн?', NULL, NULL, 'Варварский идол мурлоков', 'Варварский нож мурлоков', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9550, 'Загадочная карта', 'Небрежно нарисованная карта не может рассказать ничего о том, кто сделал ее – кроме того, что у картографа была нетвердая рука. Здесь изображен небольшой павильон с полуразрушенной колоннадой – похоже, он находится к западу от частично затопленной башни.$B$BЕсли верить карте, эти руины находятся на восточном побережье острова. Неизвестно, что там находится, но неведомый картограф, видимо, считал это достаточно важным.', 'Найдите павильон, изображенный на карте, и выясните, что в нем необычного.', 'Внимательно изучив книгу, вы пришли к выводу, что это дневник. Все страницы заполнены аккуратным почерком, явно отличающимся от почерка автора, который на большинстве страниц карты делал пометки и рисунки своей рукой.$B$BИз-за его отчетов о буйных попойках на берегу разобрать первоначальный текст практически невозможно.', 'Возможно, эта старая рукопись и есть то важное, ради чего была нарисована карта...', NULL, NULL, 'Потертая карта сокровищ (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9551, 'Зов воздуха', '$N, предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!$B$BЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.', 'Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9552, 'Зов воздуха', 'Тебя призывает великий дух воздуха, и пришло время ответить на зов.$B$BПоднимись по Штормовому пути на северном склоне горы, в которую врезался Экзодар. На вершине ты найдешь пещеру. В ней живет одна из моих самых лучших учениц, Велаада.$B$BВыслушай ее мудрые слова и повинуйся ей. Так ты обретешь глубокое понимание стихии Воздуха.', 'Поговорите с Велаадой на Штормовом Пике острова Лазурной Дымки.', 'Ветер нашептал мне, что ты уже в пути, $C.$B$BПредсказатель, Нобундо, очень высокого мнения о тебе, и я вполне с ним согласна.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9553, 'Зов воздуха', 'Хотя воздух неосязаем, это - могучая сила, окутывающая все вокруг и проникающая повсюду.$B$BЕго не видит око, но даже камень этой горы состоит по большей части из воздуха, воздух растворен и в морской воде, а огонь не смог бы пылать без него. Только не говори об этом другим стихиям!$B$BТот, кто может научить тебя этой мудрости, находится совсем рядом. На северном крае этого пика тебя ждет Шептатель. Благодаря ему ты познаешь суть стихии Воздуха.', 'Поговорите с Шептателем на Штормовом Пике острова Лазурной Дымки.', 'Я ждал тебя, $C. Ты ищешь мудрости и, чувствую, не только ее.$B$BЧто ж, начнем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9554, 'Зов воздуха', 'Хотя мои братья и сестры других стихий просили тебя выполнить различные задания, я ничего не хочу от тебя. Мне кажется, ты и так $gсовершил:совершила: немало, расплатившись за корабль, рухнувший в эти земли с моих небес. Я вижу, у тебя довольно мудрости, чтобы разумно распорядиться стихией воздуха.$B$BОтнеси эту часть моей сущности предсказателю Нобундо, и он поможет тебе создать тотем. Я готов отнести тебя в Экзодар по воздуху.', 'Отдайте Завихрение воздуха предсказателю Нобундо в Экзодаре.', 'Я горжусь тобой, $N. Ты устоял там, где пали другие. Тебе удалось обрести познание стихий и себя. Помни эти уроки всю жизнь, и сделаешься мудрее.$B$BТеперь давай мне завихрение, которое вручил тебе Шептатель, - я вложу его в твой тотем Воздуха. Так же, как и другие тотемы, он поможет тебе сосредоточиться и послужит напоминанием о связи со стихиями.', 'Уже вернулся? Вид у тебя взъерошенный!$B$B*Нобундо понимающе ухмыляется.*', NULL, NULL, 'Завихрение воздуха (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9555, 'Зов огня', 'Я рад, что ты $Gизбрал:избрала; нелегкий путь шамана. Немногие решаются на это, но я провижу, что нам не обойтись без шаманизма, который мы переняли от Сломленных.$B$BДа, теперь их называют именно так, но они некогда были дренеями. Их изменила магия Скверны, и поэтому они не могут призывать на помощь силу Света. Многие относятся к ним, а заодно и к шаманизму, с подозрением, но они не несут зла.$B$BЯ хочу, чтобы ты $gпобеседовал:побеседовала: с предсказателем Нобундо. Он - мудрейший из известных мне шаманов, и под его руководством ты многому научишься.', 'Поговорите с предсказателем Нобундо в Кристальном зале Экзодара.', 'Приветствую тебя. Всегда отрадно встретить дренея, избравшего путь шаманизма. Увы, нас сейчас так мало.$B$BТы уже понял, что нельзя судить о пламени по его виду. И ты не суди обо мне.$B$BИтак, ты здесь, чтобы научиться создавать тотем Огня.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9556, 'Вода для мага', 'Ты без сомнения прекрасно $gпроявил:проявила: себя в борьбе за башни, $r, и непременно получишь свою награду за доблесть. Но сначала ты $gдолжен:должна: доказать, что понимаешь всю глубину разыгравшейся здесь трагедии.$B$BОтправляйся на улицы Стратхольма и найди сосуд со святой водой. Отнеси его в Квартал Магов в Штормград или Подгород... Если твои сородичи одержали верх в тех землях, тебе удастся добраться до кого-то из моих коллег.', 'Найдите бутылку святой воды Стратхольма на улицах Стратхольма и доставьте ее Лордеронскому магу в квартал магов в Штормграде или Подгороде, если вашей стороне удалось одержать верх в Восточных Чумных землях.', '', NULL, NULL, NULL, 'Святая вода Стратхольма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9557, 'Расшифровка книги', 'Прочесть записи невозможно – изначальный текст нельзя отделить от скорописи картографа. Но, может быть, кто-нибудь все-таки сумеет это сделать?..$B$BАнахорет Пайтеус собрал множество артефактов различных культур: возможно, его опыт поможет расшифровать и эти записи?', 'Отнесите древние записи на Кровавую заставу и покажите анахорету Пайтеусу.', 'Хмм... Непростая задача. Да, вероятно, я сумею выяснить, что же написал на этих страницах первый автор.$B$BСначала мне нужно взять все необходимое для расшифровки. Это не займет много времени...', 'Да озарит благословенный Свет все твои начинания, $C. Ну, показывай, с чем пришел...', NULL, NULL, 'Потрепанный дневник (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9558, 'Длиннобородые', 'У нас тут проблемы с араккоа, которые нападают на наши караваны с продовольствием, так что пришлось нанять пару дворфов, чтобы они разобрались с птичками.$B$BЭто двое братьев, Гремни Длиннобород из них старший.$B$BНо если честно, я немного беспокоюсь. Эти чокнутые дворфы взяли с собой эля вдвое больше, чем провизии и снаряжения вместе взятых! Может быть, ты проследишь за ними?$B$BАраккоа гнездятся в логове Хаал\'эш, которое находится к западу отсюда – довольно далеко, у Глубокого разлома. Дворфы должны были разбить там лагерь, к югу от лощины Пыльного Пера.', 'Найдите Гремни Длинноборода на северо-западе от логова Хаал\'эш на полуострове Адского Пламени.', 'Как ты нас нашел, $C? Впрочем, не важно, наверное, тебя прислали нам на помощь. Ну тогда давай за работу!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9559, 'Логово племени Тихвой', '$gИзбранный:Избранная:, отправляйся на север, к дому моего народа – в логово племени Тихвой. Именно там тебя ждет самое сложное испытание.$B$BСтупай, верховный вождь племени Тихвой ждет твоего прибытия.', 'Поговорите с верховным вождем в логове племени Тихвой.', 'Много сотен лет мы жили в относительном мире с прочими обитателями этих земель. Несколько месяцев назад Курц увидел грозные предзнаменования. Долгий мир подошел к концу. Но мы и не представляли, насколько серьезны будут последствия катастрофы!$B$BКажется, будто сами боги принесли раздор в наши края: против нас выступили и враги, и друзья. Но пророчество говорит и о другом... Среди всеобщего хаоса нам явится герой – герой не нашей крови. Избранный спасет нас от гибели.$B$BЭтот герой – ты.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9560, 'Звери Судного дня!', 'Мы с братом охотились в лесах на востоке, и на нас неожиданно напали странные твари, похожие на насекомых. Такого на острове Лазурной Дымки еще не видали! Может, грядет Судный день? И именно тебе суждено его предотвратить?$B$BЕсли ты в самом деле $gИзбранный:Избранная:, то легко поразишь тварей Судного дня... и принесешь мне их шкуры. Из таких шкур я смогу сделать великолепные доспехи!$B$BЗверей ты можешь найти на востоке, за дорогой.', 'Принесите 8 шкур опустошителей Мурдо в логово племени Тихвой.', 'Пророчество воистину сбылось, а доспехи получились великолепные! В самый раз для защитника! Я продам их тебе со скидкой, о Безволосый.$B$BШутка... Первый доспех – в подарок.', 'Какие гнусные твари! Даже Слепой Наблюдатель их видит... а ведь он слеп.', NULL, NULL, 'Шкура опустошителя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9561, 'Записи Нолкаи', 'Ну вот, $N, перевод готов.$B$B*Анахорет Пайтеус указывает на последний переведенный фрагмент.*$B$B\"Враги уже близко. Мы собрали всех, кто выжил, и отошли на восток, к храму. Храм - наш последний оплот на этом острове. Многие думают, что именно здесь нам суждено принять последний бой. Я спрятал то немногое, что у меня было, у подножия храма - надеюсь, кто-нибудь найдет мой тайник и узнает, что здесь произошло...\"', 'Найдите место, описанное в дневнике Нолкаи, и отыщите его тайник.', 'Земляной холмик, явно искусственного происхождения, зарос травами и кустарником.$B$BЧерез несколько минут из-под слоя земли появляется старый ящик. Вероятно, это именно то, о чем говорилось в записях Нолкаи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9562, 'Мурлоки... За что нам эта напасть?', 'Темные настали дни, $gИзбранный:Избранная:. Даже мурлоки наступают нам на пятки – в прямом смысле слова. К сожалению, недавно они посягнули не только на мое самолюбие.$B$BУ нас всегда были напряженные отношения с племенем Илистых Плавников, но я и помыслить не мог, что они осмелятся напасть на нас и похитить запасы продовольствия! Отправляйся на запад, к Илистому берегу, и верни наши припасы!$B$BИ если тебе попадется темнокожий мурлок с клоком белой шерсти, застрявшим между пальцами...', 'Верните 5 мешков зерна племени Тихвой.', 'М... Вкусное зерно... Паркат будет в восторге!', 'Мурлок дал мне пинка и плюнул на меня... среди бела дня!', NULL, NULL, 'Зерно племени Тихвой', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9563, 'Доверие Миррена', 'Хочешь, чтобы мы тебе доверяли? Да в наше время никому верить нельзя!$B$BНе так давно араккоа прикончили одного из наших, это меня здорово разозлило.$B$BВот что я тебе скажу. Если ты хочешь доказать свою верность Оплоту Чести... и... и... вообще! – то принеси мне кружку горькой настойки Стражей Пустоты... Да, пожалуй, это было бы недурно. Может быть, потом я и доверю тебе какое-нибудь несложное дело.$B$BНастойку можно достать у Берни из крепости Стражей Пустоты, у него всегда есть запасы.', 'Принесите Миррену Длиннобороду 1 кружку горькой настойки Стражей Пустоты. Для выполнения этого задания необходимо иметь дружелюбное отношение Оплота Чести.', 'О, да! Похоже, с тобой все в порядке, $r. Думаю, что могу тебе доверять.', 'У тебя проблемы с настойкой? Старый добрый Берни из крепости Стражей Пустоты обычно запасает ее бочками.$B$BЕсли, конечно, он не смылся оттуда куда подальше... Вот это была бы беда так беда!', NULL, NULL, 'Горькая настойка Стражей Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9564, 'Клок шерсти Гурфа', 'Вы нашли клок шерсти, потерянный Гурфом в борьбе с мурлоками. Отнесите его Гурфу и сообщите, что ужасный Мургургул убит.', 'Верните Гурфу клок его шерсти в логово племени Тихвой на острове Лазурной Дымки.', '<Гурф плюет на клок шерсти и пытается приспособить его к плеши на заду.>$B$BПока и так сойдет! Надеюсь, кто-нибудь из наших шаманов мне поможет.', 'Неужели это он?', NULL, NULL, 'Клок шерсти Гурфа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9565, 'Поиски в логове племени Тихвой', 'Я верховный вождь, и поэтому более всего меня волнует причина предательства союзников.$B$BПочему дикие совухи – наши бывшие друзья – решили на нас напасть? Почему они поселились в логове племени Тихвой?$B$BМожет быть, ответ на мой вопроc таится внутри. Попытайся докопаться до правды.', 'Найдите в логове племени Тихвой причины предательства совухов. ', 'От кровавого кристалла исходит болезненная аура, отравляющая воды пещеры.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9566, 'Кровавые кристаллы', 'На первый взгляд этот кристалл кажется частью Экзодара. На самом деле с ним что-то не так – он кроваво-красный и быстро растворяется в пещерной воде.$B$BВозможно, именно этим объясняется необычно агрессивное поведение существ острова Лазурной Дымки. Сообщите об этом верховному вождю племени Тихвой.', 'Поговорите с верховным вождем в логове племени Тихвой. ', 'Мои разведчики видели много таких же кристаллов на севере.$B$BБлагодарю за помощь, но теперь мне нужно посоветоваться со старейшинами. По окончании совещания я пошлю за тобой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9567, 'Лицо врага', 'Приветствую, $C. Приятно видеть на Кровавой заставе, еще $gодного искателя:одну искательницу: приключений. Конечно, эльфы крови сейчас представляют наиболее явную угрозу; однако на острове Кровавой Дымки есть и другие твари, от которых нельзя ждать ничего хорошего.$B$BСатиры из племени Наззивус – источник постоянной тревоги для нас. Это ужасные существа – демонические создания, использующие черную магию; порча, порожденная падением \"Экзодара\", питает их и придает им сил.$B$BМы должны сдержать сатиров – но для этого нам нужно знать о них как можно больше. Отправляйся на юго-запад в Наззивиан, отыщи их нелепый монумент и попробуй что-нибудь разузнать.', 'Найдите в Наззивиане монумент Наззивуса, возьмите один из иероглифов с монумента и вернитесь к воздаятельнице Аалезии на Кровавую заставу.', 'Прекрасно, $N! А теперь посмотрим, о чем мне поведает этот иероглиф - от этого зависят наши дальнейшие действия.', 'Удалось ли тебе узнать хоть что-то новое о сатирах из племени Наззивус?', NULL, NULL, 'Иероглиф монумента Наззивуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9568, 'Лучшая защита', 'Дела обстоят хуже, чем я думала, $N. Нам, дренеям, хорошо известно, что происходит с теми, кто решается продать душу Легиону в обмен на обещание бессмертия и могущества...$B$BПлемя сатиров этого острова – Наззивус – это потомки злосчастных существ, вступивших в союз с Легионом. Боюсь, они найдут способ использовать оскверненные кристаллы как оружие и обратят их силу против нас.$B$BТы $gвидел:видела:, во что кристаллы превратили эту землю - так представь себе, на что окажутся способны сатиры, если к ним попадет такое оружие!.. Отправляйся на северо-запад, в Наззивиан, и помни: иногда нападение - лучшая защита!', 'Воздаятельница Аалезия с Кровавой заставы просит убить 10 сатиров, 5 разбойников и 5 скверноподанных из племени Наззивус.', '', NULL, NULL, NULL, 'Сатир из племени Наззивус убито', 'Разбойник из племени Наззивус убито', 'Скверноподданный из племени Наззивус убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9569, 'Противостояние', 'Теперь, когда мы дали сатирам понять, что не уйдем с этой земли, пора показать, что терпеть здесь отродий Пылающего Легиона мы также не намерены.$B$BСлишком долго дренеи стремились избежать столкновения с Легионом и его приспешниками, $N; слишком долго - и это не принесло нам ничего, кроме горестей. Когда псы Легиона находили нас, они не щадили никого.$B$BСатиры не должны воспользоваться оскверненными кристаллами, оставшимися после гибели \"Экзодара\"; тем более они не должны использовать эти кристаллы в качестве оружия. Отправляйся на север, в Аксариен, разыщи предводителя сатиров, убей его и верни нам те кристаллы, которые он уже успел собрать.', 'Убейте Зевракса, 5 аксариенских тенеловов и 5 аксариенских призывателей огня, соберите 5 оскверненных кристаллов и отнесите их на Кровавую заставу воздаятельнице Аалезии.', 'Лишившись своего предводителя, а заодно и уже собранных оскверненных кристаллов, сатиры стали значительно менее опасными для нас. Но лишь Предвечному Свету ведомо, сколько здесь еще этих злосчастных тварей...$B$BМы – я и вестник Миколаас – благодарны тебе за помощь: если бы не это, сатиры стали бы для нас слишком серьезной угрозой. Решимость и отвага – вот ключ к победе над Легионом и его приспешниками!', '<Воздаятельница Аалезия смотрит словно бы сквозь вас; она явно обдумывает предстоящую борьбу с сатирами.>$B$BТы исполнил мою просьбу? Сразился c предводителем сатиров?', NULL, NULL, 'Зевракс убито', 'Аксариенский тенелов убито', 'Аксариенский призыватель огня убито', 'Оскверненный кристалл');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9570, 'Куркен-жмуркен', 'Когда кристальная буря улеглась, в нашу деревню явилось чудище из древних легенд. Оказалось, что этого зверя, Куркена, привели сюда дикосовухи. Он погубил многих моих соплеменников, пытавшихся отстоять родную деревню, и с тех пор еще больше погибло, попытавшись бросить ему вызов.$B$BМне было видение, что победа над тварью близка. Я не сомневаюсь, что именно тебе суждено совершить этот подвиг, $N. Ты - наша последняя надежда. Ступай в логово племени Тихвой, убей Куркена и в доказательство принеси мне его шкуру.', 'Убейте Куркена и принесите его шкуру Курцу Прорицателю в логово племени Тихвой на острове Лазурной Дымки.', 'Избранный вернулся с победой!$B$BПророчество почти исполнилось. Что же до шкуры...', '<Курц недовольно ворчит.>', NULL, NULL, 'Шкура Куркена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9571, 'Шкура Куркена', 'Отнесите шкуру Куркена Мурдо на другою сторону деревни. Он сделает из нее все, что вы захотите.', 'Отнесите шкуру Куркена Мурдо в логово племени Тихвой. ', 'Такой крепкой брони я еще не делал! Пусть она служит тебе верой и правдой, $N.', 'Привет герою!', NULL, NULL, 'Шкура Куркена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9572, 'Ослабить оборону валов', 'Нужно торопиться, у нас мало очень времени. На карту поставлено само существование Траллмара!$B$BМы зажаты между цитаделью Адского Пламени на западе и Пылающим Легионом на востоке. Если внимание Легиона окажется привлечено к Темному порталу, то мы сумеем нанести удар оркам Скверны. Но для этого надо будет прорваться через валы цитадели Адского Пламени!$B$BОтправляйся к валам, убей тех, кто командует там орками Скверны, а доказательства их смерти принеси Каза\'ресу.', 'Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Каза\'ресу в Траллмар на Полуострове Адского Пламени.', 'Неплохое начало. Смерть командиров внесет панику в их ряды. Обезвредив их артиллерию, мы получим достаточно времени, чтобы подобраться к самой цитадели.$B$BНо орков по-прежнему больше, чем может охватить глаз, так что жди нового задания.$B$BНо пока я тобой доволен. Можешь выбрать в оружейной Траллмара, что захочешь.', '$N, точно? Сток-Тон говорил, что ждет твоего доклада.$B$BНадеюсь, ты принес хорошие новости?', NULL, NULL, 'Рука Гарголмара', 'Копыто Омора', 'Голова Назана', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9573, 'Вождь Умуру', 'Я – Тихвой Младший, наследник рода. Как видишь, мои защитники выстроили ловушку для буйных диких совухов, нападающих на нас изнутри логова. Пока что нам удается удерживать их, но ни один из воинов не смог проникнуть внутрь. Если ты сумеешь пробраться туда и убить их главаря, у нас появится шанс нанести им решающий удар!$B$BОтыщи вождя Умуру и уничтожь его. Прикончи всех безумных диких совухов, которые тебе встретятся.', 'Убейте вождя Умуру и 9 безумных диких совухов.', 'Теперь у нас появилась возможность выкурить озверевших тварей из форта! Я немедленно отправляю туда бойцов! Племя Тихвой благодарит тебя за помощь, $N!', NULL, NULL, NULL, 'Вождь Умуру убито', 'Безумный дикий совух убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9574, 'Отравленные скверной', 'С нашим прибытием жизнь на острове Кровавой Дымки изменилась навсегда. Обломки от падения \"Экзодара\" разбросаны по всему острову – боюсь, это оказывает скверное влияние на здешнюю природу.$B$BОднако прежде чем делать окончательные выводы, мне хотелось бы получить некоторые данные. Похоже, в первую очередь действие кристаллов сказалось на деревьях; вероятно, у древней должны проявляться ярко выраженные симптомы заражения... Думаю, я смогу начать углубленные исследования, если ты принесешь мне образцы коры оскверненных древней.', 'Принесите на Кровавую заставу 6 кусков коры, покрытой кристаллами, и отдайте Морэ.', 'Для моих исследований здесь более чем достаточно. Благодарю, $N. Если тебе удастся найти другие свидетельства того, что кристаллы являются источником скверны, отравляющей остров, - дай мне знать.', 'Ну как, удалось тебе найти нужные образцы?', NULL, NULL, 'Кристаллизованная кора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9575, 'Ослабить оборону валов', 'Нужно торопиться, у нас очень мало времени. На карту поставлено само существование Оплота Чести!$B$BМы зажаты между цитаделью Адского Пламени на западе и Пылающим Легионом на востоке. Если внимание Легиона будет привлечено к Темному порталу, то мы сумеем нанести удар оркам Скверны. Но для этого надо будет прорваться через бастионы цитадели Адского Пламени!$B$BОтправляйся на бастионы, убей тех, кто командует там орками Скверны, а доказательства их смерти принеси Пушкаренку.', 'Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Пушкаренку в Оплот Чести на полуострове Адского Пламени.', 'Знаешь, что я ненавижу больше, чем ошибаться? Проигрывать деньги. Я поспорил, что ты не справишься с заданием, дорогуша.$B$BНеплохое начало. Смерть командиров внесет панику в их ряды. Обезвредив их артиллерию, мы получим достаточно времени, чтобы подобраться к самой цитадели.$B$BНо орков по-прежнему больше, чем может охватить глаз, так что жди нового задания.$B$BНо пока я тобой доволен. Можешь выбрать в оружейной, что захочешь.', '$N, точно? Чадвик говорил, что ждет твоего доклада.$B$BНадеюсь, ты принес хорошие новости?', NULL, NULL, 'Рука Гарголмара', 'Копыто Омора', 'Голова Назана', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9576, 'Ожерелье Жестокого Плавника', 'Грубо сработанная подвеска украшена слабо светящимся кристаллом. Хотя его пульсирующий свет еле виден, от кристалла исходит отчетливое ощущение угрозы.$B$BЧто могло заставить Жестого Плавника создать эту подвеску?.. Как бы то ни было, эта вещь кажется слишком важной, чтобы не придавать ей значения. Необходимо показать ее кому-нибудь на Кровавой заставе.', 'Покажите подвеску красного кристалла Морэ на Кровавой заставе.', 'Занятно, $С, чрезвычайно занятно... Кажется, нам еще никогда не приходилось видеть, чтобы мурлоки носили такие украшения.$B$BСудя по тому, что мы знаем об оскверненных кристаллах, мурлок, носивший эту подвеску, полагал, что она дает ему власть над сородичами... Не удивлюсь, если он был много крупнее и сильнее мурлоков своего клана.', 'Что это у тебя?', NULL, NULL, 'Подвеска Красного Кристалла (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9578, 'В поисках Галена', 'Скажи, $N, часто ли ты вспоминаешь свою семью?.. На \"Экзодаре\" было много семей, но я почти не слышала о таких, которым удалось воссоединиться.$B$BСама я пытаюсь найти хоть какие-то следы моего мужа, Галена, который работал техником в криогенном блоке. Обломки блока находятся к западу отсюда, и там тьма тьмущая эльфов крови!$B$BНо я обязана выяснить, что случилось с Галеном! Даже весть о его смерти будет лучше этой страшной неизвестности! Вот смотри: видишь эту подвеску? У моего мужа точно такая же – их нам подарила моя сестра.', 'Найдите Галена, мужа Морэ.', 'На трупе одежда экзодарских техников, но подвески, о которой говорила Морэ, нет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9579, 'Судьба Галена', 'По рассказу Морэ невозможно опознать тело; однако заметно, что его одежду разорвали, когда обыскивали труп в поисках ценностей.$B$BЭльфы крови, живущие в этих местах, несомненно, забрали бы все мало-мальски ценное, тем более драгоценный амулет Галена.$B$BКонечно, то, что Гален погиб при крушении, станет для Морэ тяжелым ударом. Но возможно, ей будет немного легче, если удастся отобрать у эльфов крови амулет ее супруга...', 'Принесите на Кровавую заставу амулет Галена и отдайте его Морэ.', '<Вы рассказываете Морэ о том, что удалось обнаружить среди обломков криогенного блока.>$B$BЗначит... Он...$B$BГде-то в глубине души я знала, но никак не могла заставить себя поверить в это. Ты принес не те новости, которых я ждала, но прими мою искреннюю благодарность за то, что нашел Галена.', '<Во взгляде Морэ читается надежда.>$B$BСкажи, удалось ли тебе отыскать хоть какие-то следы Галена?', NULL, NULL, 'Амулет Галена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9580, 'Вскормленные медвежатиной', 'Полагаю, за время, проведенное на острове Кровавой Дымки, ты $gуспел:успела: понять, что после нашего прибытия все здесь переменилось. Однако мой опыт свидетельствует о том, что натуральные продукты можно использовать всегда – даже если их источником является природа, подобная здешней.$B$BРесурсов у нас мало, так что приходится полагаться исключительно на собственные умения. Я вот поставляю в лавки медвежье мясо – знаешь ведь, на острове медведей немало; а если мясо готовить, соблюдая некоторые предосторожности, оно вполне съедобно. Так вот, я тут подумал: ты все равно бродишь по всему острову – может, если тебе по дороге попадется пара медведей, поможешь нам с припасами?', 'Принесите зверолову Лисеону на Кровавую заставу 8 кусков мяса с боков старых бурых медведей.', 'На некоторое время нам этих припасов хватит. Да и мне найдется чем заняться: буду готовить еду... Благодарю тебя, $N.', 'Ну что, $N, как охота?', NULL, NULL, 'Бок старого бурого медведя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9581, 'Изучение кристаллов', 'Добро пожаловать на Кровавую заставу, $C. Конечно, основная моя задача – защита заставы, но наши вожди в Экзодаре возложили на меня и другие обязанности.$B$BПроблема в том, что на острове слишком опасно – а мы не можем рисковать нашими исследователями, посылая их на смерть. Но при этом мне нужно добыть образцы кристаллов из разных районов острова. Понимаешь, к чему я веду?$B$BПервый образец – из тех, что мне нужны, – можно найти в обломках корабля к югу отсюда. Он недалеко, только мост перейти... правда, как я слышал, в тех местах водится множество опустошителей...', 'Добудьте образец кристалла с места крушения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу.', 'Этот осколок кристалла даст нашим исследователям базу для сравнения – он принесен из той части острова, которую не так сильно затронула скверна.$B$BОднако же пока не имеет смысла посылать образец в Экзодар – сначала нам нужно собрать полный набор кристаллов. Начало, безусловно, положено. Поверь, если ты поможешь мне и в остальном, я сам прослежу за тем, чтобы твои усилия были вознаграждены.', 'Ну как, удалось тебе раздобыть первый образец кристалла?', NULL, NULL, 'Кристалл с места крушения', 'Кайло для добычи кристаллов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9582, 'Силой единой', 'Когда наш корабль разбился, весь зверинец разметало по северо-восточному побережью. Мне дали ключ от клетки одного из наиболее страшных зверей, смертоносного опустошителя. Панцирь у этой твари не очень прочный, зато на нее почти не действуют заклинания. Ее нужно убить простым клинком.$B$BВозьми этот ключ и избавь опустошителя от плена и страданий. Не допусти, чтобы он сбежал и причинил еще больший вред окружающей среде.', 'Откройте клетку смертоносного опустошителя, убейте его и вернитесь к Руаде на Лазурную заставу на острове Лазурной Дымки.', '', NULL, NULL, NULL, 'Смертоносный опустошитель убито', 'Ключ от клетки опустошителя (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9584, 'Второй образец', 'Теперь, когда у нас есть первый кристалл, нам понадобятся другие образцы, которые я мог бы отправить в Экзодар. Увы, там, где можно раздобыть эти кристаллы, тебя поджидает еще большая опасность, чем прежде...$B$BВторой образец ты сможешь найти в лесу Клинков, к северо-западу от Кровавой заставы. Правда, в этом лесу обосновались эльфы крови... Попытайся найти кристалл, который они еще не успели прибрать к рукам и использовать в своих целях, и отколи от него образец.', 'Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте его предвестнику Миколаасу.', '*Предвестник Миколаас изучает образец кристалла.*$B$BДолжен сказать, этот образец сильно отличается от предыдущего.$B$B*Предвестник поднимает кристалл и рассматривает его на свет.*$B$BВидишь, как он пульсирует? Весьма, весьма тревожный признак. В своем отчете я непременно отмечу те изменения, которые эльфам крови удалось внести в этот кристалл. Прими мою благодарность, $N, твоя помощь неоценима.', 'Ты сумел добыть второй образец кристалла? Он у тебя с собой?', NULL, NULL, 'Образец измененного кристалла', 'Кайло для добычи кристаллов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9585, 'Последний образчик', 'Остался всего один образец, и я смогу отправить эти кристаллы в Экзодар. Послушай, $N: последний кристалл нужно добыть в Аксариене, оплоте сатиров – а он находится к северо-западу отсюда.$B$BНе знаю, чего можно ждать от этого кристалла, но уверен, что обнаружу в нем следы скверны. Помнишь кристаллы, от которых были отколоты предыдущие образцы? Тебе нужно найти такие же, иначе наши исследователи не смогут провести сравнительный анализ.', 'Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу.', '*Предвестник Миколаас берет последний образец кристалла.*$B$BТеперь мой набор полон. Осталось уложить образцы в ящик и отправить их в Экзодар.$B$B*Похоже, предвестник рад, что покончил с этим заданием.*$B$BНе пойми меня неправильно, $N: я уверен, что это очень важные исследования, но у нас тут и без них хватает проблем.', 'Ну, где последний образец для моего драгоценного набора?', NULL, NULL, 'Образец аксариенского кристалла', 'Кайло для добычи кристаллов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9586, 'Помощь Таваре', 'Тавара, одна из наших травниц, решила пополнить свои запасы и ушла в лес. Ее давно не видно – боюсь, бедняга нуждается в помощи. Я сам не могу пойти на поиски.$B$BПрошу тебя, $C, найди ее и исцели, если нужно. Она вышла с Лазурной заставы и направилась на восток, в сторону горячих источников.', 'Найдите Тавару и исцелите ее раны.', 'Спасибо, что помог Таваре. Многие не освоились в этих землях и часто забредают туда, где их поджидает смертельная опасность.$B$BЯ почту за честь, если ты примешь в дар это одеяние. Его могут носить только защитники Лазурной заставы и ревностные служители Света.', NULL, NULL, NULL, 'Исцелите Тавару', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9587, 'Предвестье беды', 'Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква \"И\". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его должен прочесть Данат Троллебой!', 'Доставьте угрожающее письмо боевому командиру Данату Троллебою в Оплот Чести на полуострове Адского Пламени.', 'Говоришь, на нем стоит подпись Иллидана? Дай-ка взглянуть.$B$B<Командир читает письмо, задумывается на минуту, затем снова его перечитывает.>$B$BЭто действительно зловещие новости. Мы должны как можно быстрее воплотить в жизнь наш план атаки на цитадель Адского Пламени и Кузню Крови. Ты доказал, что отлично справляешься с работой, так что именно ты этим и займешься.$B$BГанни даст тебе новое задание, думаю, оно будет куда более смертоносным, чем предыдущее.$B$BДа хранит тебя Свет, $N!', 'Ну, что у нас тут, парень?', NULL, NULL, 'Угрожающее письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9588, 'Предвестье беды', 'Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква \"И\". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его надо доставить Назгрелу в Траллмар!', 'Доставьте угрожающее письмо Назгрелу в Траллмар на Полуострове Адского Пламени.', 'Говоришь, на нем стоит подпись Иллидана? Дай-ка взглянуть.$B$B<Назгрел читает письмо, задумывается на минуту, затем снова его перечитывает.>$B$BЭто действительно зловещие новости. Мы должны как можно быстрее воплотить в жизнь наш план атаки на цитадель Адского Пламени и Кузню Крови. Ты доказал, что отлично справляешься с работой, так что именно ты этим и займешься.$B$BЦентурион Каза\'рес даст тебе новое задание, думаю, оно будет куда более смертоносным, чем предыдущее.$B$BЛок\'тар огар, $N!', 'Что это за письмо, $C?', NULL, NULL, 'Угрожающее письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9589, 'Кровь есть жизнь', 'Это письмо всех поставит на уши. Если бы мы знали, как были созданы орки Скверны, то наверника бы придумали, как с ними справиться. Будто бы нам было недостаточно Пылающего Легиона на востоке.$B$BТак что нам крупно повезло, моя радость! Тебе придется прогуляться к так называемой Кузне Крови, в цитадель Адского Пламени. Так сказать, в самое пекло.$B$BСтупай, поубивай орков Скверны и добудь образцы их крови.$B$BНадеюсь, ты справишься.', 'Принесите 10 фиалов крови орков Скверны Пушкаренку в Оплот Чести на полуострове Адского Пламени.', 'Не хрена себе, сказал я себе! На данный момент ты мой самый любимый штатская штафирка из всех жалких штафирок этого жалкого мира.$B$BКлянусь, яйцеголовые выпрыгнут из штанов от радости, когда я выложу перед ними образцы крови. Кто знает, может, мы обнаружим новый способ борьбы с проклятыми скверноорками?', 'Ну что, приятель, собрал кровь? Это очень важно, иначе мы бы тебя не просили ее достать.', NULL, NULL, 'Фиал крови орка Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9590, 'Кровь есть жизнь', 'Это письмо меня беспокоит, но вовсе не потому, что его написал Предатель. Если мы будем знать, как были созданы орки Скверны, то сумеем победить их! Мало нам атак Легиона с запада, так теперь еще с востока эти проклятые орки!$B$BТы $gдолжен:должна: пробраться в Кузню Крови в цитадели Адского Пламени. Убей орков Скверны, которые тебе попадутся, и принеси мне образцы их крови.', 'Принесите 10 фиалов крови орков Скверны центуриону Каза\'ресу в Траллмар на Полуострове Адского Пламени.', 'Твои способности меня поражают, $N. Уже второй раз ты отправляешься в цитадель Адского Пламени, выполняешь задание и возвращаешься невредимым!$B$BЯ отправлю эту кровь к тем, кто сможет раскрыть ее секреты. Может быть, мы найдем способ все исправить.', 'Ты уже принес кровь? Так быстро?', NULL, NULL, 'Фиал крови орка Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9591, 'Приручение зверя', 'Когда $C избирает свой путь, $gего:ее: учат лишь убивать. Мне кажется, тебе пора сделать следующий шаг.$B$BФурболги из племени Тихвой придумали, как можно приручить зверя, не тратя на это долгие месяцы. Они вырезают тотем в форме определенного животного, и он позволяет установить временную связь с существами этого вида.$B$BНачнем первый урок. Возьми этот тотем и приручи при его помощи одного из колючих крабов на западном побережье острова.', 'Используйте тотем приручения и приручите колючего краба. Вернитесь к охотнице Келле Тетиве Ночи.', 'Не сомневаюсь, первым делом тебе пришлось столкнуться с несговорчивостью крабов. Так и машут клешнями, пока не убедятся, что ты их не собираешься варить.', 'Помогла ли магия тотема приручить колючего краба? Эти мелкие твари на редкость вздорные!', NULL, NULL, 'Тотем приручения (Прилагается)', 'Приручение колючего краба', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9592, 'Приручение зверя', 'Крабы, конечно, злобные твари, но лесоног - гораздо более сложное испытание. Чем сильнее будущий союзник, тем больше стойкости требуется от охотника во время приручения.$B$BВозьми этот тотем приручения и приручи большого лесонога. Их можно найти на севере острова Лазурной Дымки.', 'Используйте тотем приручения и приручите большого лесонога, после чего вернитесь к охотнице Келле Тетиве Ночи.', 'Похоже, лесоног не выклевал тебе глаза.$B$B*Келла отводит взгляд.*$B$BХотя я на это и не рассчитывала, разумеется!', 'Лесоноги - сильные птицы. Иногда на них по ошибке нападают хищники, и последствия оказываются плачевны.', NULL, NULL, 'Тотем приручения (Прилагается)', 'Приручение большого лесонога.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9593, 'Приручение зверя', 'Во время приручения большого лесонога ты, должно быть, $gзаметил:заметила: огромных кошек, зовущихся ночными ловцами. Эти хищники смертельно опасны... но и союзники из них превосходные.$B$BПриручи ночного ловца при помощи тотема приручения, отправляйся с ним на охоту и береги его. Как закончишь - возвращайся ко мне.', 'Используйте тотем приручения и приручите ночного ловца. Вернитесь к охотнице Келле Тетиве Ночи.', 'Должна сказать, что ты учишься куда быстрее, чем я полагала, Фиринити. Похоже, последний тотем приручения нам не понадобится. Честно говоря, я не очень понимаю, что за зверь изображен на нем. Похоже на огро$Nю ящерицу с крыльями и длинным хвостом... Ладно, в другой раз!$B$BТеперь тебе хватит опыта, чтобы справиться без помощи тотема приручения. Удачи!', 'Ночные ловцы - всего лишь большие кошки. Правда, их когти острее бритвы, и мясо они ох как любят...', NULL, NULL, 'Тотем приручения (Прилагается)', 'Приручение ночного ловца', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9594, 'Знаки Легиона', 'Это обломок доспеха, выкованного из совершенно черного металла, который, похоже, поглощает свет. Вроде бы он даже не зачарован, но с первого взгляда очевидно, что с ним что-то не так.$B$BТакие доспехи носит лишь одна армия – армия Пылающего Легиона. Присутствие Легиона здесь может означать только одно – они собираются натравить островных сатиров на дренеев.$B$BСначала разберитесь с местными сатирами, затем вернитесь на Кровавую заставу и покажите этот обломок доспеха воздаятельнице Аалезии.', 'Убейте 8 сатиров из племени Наззивус и 8 скверноподданных из племени Наззивус, а затем отнесите латный доспех Тзерака воздаятельнице Аалезии на Кровавую заставу.', 'Хорошо, что ты принес мне эту броню, $N. Вне всякого сомнения, это часть доспехов солдата Пылающего Легиона.$B$BКак я и опасалась, сатиры племени Наззивус снова наладили связь с Легионом. Если их не остановить, сатиры и их союзники-демоны уничтожат нас. Я должна немедленно сообщить обо всем предвестнику Миколаасу!', 'Да, $C? Что это у тебя?', NULL, NULL, 'Сатир из племени Наззивус убито', 'Скверноподданный из племени Наззивус убито', 'Латный доспех Тзерака (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9595, 'Контроль', 'Ты $gрешил:решила: пойти путем $c и поэтому тебе надо научиться контролировать свои силы. Неразумное применение магии может совращать души и разрушать миры.$B$BТы поймешь это, когда встретишься с существом, одержимым темной стороной магии. Отправляйся на северо-западные пляжи острова Лазурной Дымки и воспользуйся силой своих заклинаний для уничтожения мурлоков. Подобная демонстрации твоей мощи обязательно привлечет внимание злобного призрака кель\'дорайского мага, обитающего там. Убей его. Затем ступай к Бати, она находится в Чертоге Света Экзодара.', 'Убивайте мурлоков с Илистого Берега до тех пор, пока не появится призрак кель\'дорайского мага, затем уничтожьте его. После этого поговорите с Бати в Чертоге Света Экзодара.', 'Творя заклинания, противься их соблазнам, пользуйся ими только ради благих целей. Надеюсь, что, глядя на призрака, ты поняла, в кого можешь превратиться по собственной беспечности – в бездумного раба магии.', NULL, NULL, NULL, 'Призрак кель\'дорайского мага убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9598, 'Искупление', 'Я - наставница паладинов. Я та, кто ведет их стезей добродетели к Истинному Свету, дабы они защищали наш народ от любой угрозы.$B$BИ для тебя пришло время сделать первый шаг на пути праведности. Если ты решишься принять этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, чего от тебя ожидают. Постигнув мудрость, заключенную в этой книге, ты откроешь в себе новые, удивительные способности.', 'Прочтите Фолиант Божественности и поговорите с Джоль.', 'Надеюсь, ты все это время изучал фолиант?$B$BВ таком случае ты должен быть готов к испытанию. После крушения \"Экзодара\" в этих новых землях много дел для таких, как мы: всегда есть те, кто нуждается в помощи, сострадании и понимании; всегда есть враждебные твари, которых необходимо уничтожать...$B$BДоказав, что ты обладаешь достаточным терпением, чтобы помогать ближним, ты тем самым покажешь, что твои помыслы чисты и что ты воистину служишь Свету.', 'С возвращением, $N.', NULL, NULL, 'Фолиант божественности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9600, 'Искупление', 'Итак, $N, твоя задача - помочь нашим новым союзникам, фурболгам из племени Тихвой.$B$BНесколько молодых шаманов наткнулись на лагерь Косолапов и погибли, все до единого. Возьми этот знак жизни и воскреси одного из шаманов.$B$BАнклав Косолапов находится к востоку от дороги, сразу за мостом, соединяющим острова Лазурной и Кровавой Дымки. Когда выполнишь задание, возвращайся ко мне.', 'Воскресите молодого фурболга-шамана из племени Тихвой при помощи знака Жизни, а затем вернитесь к Джоль.', 'Не стоит смущать души тех, кому тебе довелось помочь. Видишь ли, те, кто волею судьбы был возвращен в мир живущих, некоторое время обычно пребывают в растерянности. Думаю, потрясение от встречи с чужаком, да еще и непривычного вида, может оказаться слишком большим испытанием...$B$BБлагодаря тебе юный шаман сумел пережить это жестокое испытание; полагаю, ты вполне достоин того, чтобы использовать силу священного Символа.', NULL, NULL, NULL, 'Молодой фурболг-шаман племени Тихвой воскрешен', 'Символ Жизни', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9601, 'В Бастион', 'С тобой желает поговорить рыцарь крови Мелар Клинок Рассвета. Мелара можно найти в Бастионе, он охраняет проход между Тирисфальскими лугами и Западными Чумными землями.$B$BТерпение - не его сильная сторона. Не советую заставлять его ждать.', 'Поговорите с Меларом Клинком Рассвета из Бастиона.', 'А... Похоже, время пришло.$B$B*Мелар с заговорщическим видом кивает.*', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9602, 'Избавь их от лукавого...', 'Сообщи об этом своему народу, $N. Хотя твои подвиги нарушили планы Кель\'таса и его темного властителя, негодяи не оставят попыток напасть на нас.$B$BОтнеси переписку предателя вождям своего народа. Они должны взглянуть на это своими глазами. Быть может, они лучше поймут, о чем здесь идет речь.', 'Отнесите переписку предателя экзарху Менелаусу на Лазурную заставу.', '*Экзарх Менелаус берет у вас письмо и начинает читать.*$B$BПроклятье... проклятье на их головы. Среди нас затесался шпион, следивший за каждым нашим шагом! И давно ли?$B$BЯ немедленно сообщу об этом Велену!$B$BТы оказал нам огро$Nю услугу, $N. Будь готов, я свяжусь с тобой, как только Пророк укажет мне, что делать.', 'Ты вернулся!', NULL, NULL, 'Переписка предателя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9603, 'Лежанки, лекарства и прочая ерунда', 'Добро пожаловать на Кровавую заставу, $C. Не обращай внимания на беспорядок. Все почему-то считают, что, как только напишешь на вывеске \"Таверна\", так внутри сразу сами собой образуются и мебель, и припасы, и все такое. А если таверна строится с нуля?..$B$BНам удалось приспособить под таверну одну из спасательных капсул; но пока тут нет мебели и запаса лекарств, это всего лишь шикарная палатка. Нургуни из Экзодара предложила собрать для меня кое-какие припасы – хотя бы то, что необходимо на первый случай, – но мне нужно, чтобы кто-нибудь отвез ей список...', 'Отвезите список Тофера на Кровавую заставу дрессировщику гиппогрифов Лаандо.', 'Итак, тебе нужно отправиться в Экзодар?$B$BПуть неблизкий - но ты не беспокойся, я знаю, как быстро доставить тебя туда.', 'Приветствую тебя, $N. Что, тебе нужен гиппогриф?', NULL, NULL, 'Список Тофера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9604, 'На крыльях гиппогрифа', 'За небольшую плату ты можешь взять одного из моих гиппогрифов, чтобы долететь до Экзодара.$B$BНет ничего быстрее и безопаснее гиппогрифа – в особенности для тех, кому необходимо доставить важное послание. Захочешь прокатиться – подходи, и мы обо всем договоримся.', 'Возьмите у Лаандо гиппогрифа и летите в Экзодар. В Экзодаре отдайте список Тофера Нургуни. Нургуни можно найти у трона Наару в Экзодаре.', 'Итак, ты привез список Тофера. Прекрасно! Я надеялась, что уже сегодня этот список будет у меня. Ну-ка, посмотрим, что там ему нужно...$B$B*Нургуни читает список и начинает складывать разные предметы в ящик.*$B$BТут большая часть вещей, которые ему нужны. Детали кроватей слишком велики, чтобы отправлять их с гиппогрифом... Ну ничего, я договорюсь и отправлю их на повозке.', 'Здравствуй, друг. Похоже, тебе пришлось пройти долгий путь... Чем я могу тебе помочь?', NULL, NULL, 'Список Тофера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9605, 'Укротитель гиппогрифов Стефанос', 'А вот и ящичек, $N, держи. Думаю, тут есть все, что нужно Тоферу, чтобы дела в таверне пошли на лад. Передай ему, что он без стеснения может заказывать все необходимое. На Кровавой заставе срочно необходимо помещение, где можно было бы ухаживать за ранеными, а также место, где путешественники смогут восстановить свои силы.$B$BКогда будешь $gготов:готова: вернуться на заставу, найди сначала Стефаноса – он обычно бывает у ворот Экзодара.', 'Найдите Стефаноса у ворот Экзодара и наймите гиппогрифа для возвращения на Кровавую заставу.', 'Итак, ты возвращаешься на Кровавую заставу и везешь туда груз? Отлично, $C, никаких проблем! Мы с тобой еще раз поговорим, а потом отправим тебя вместе с вещами туда, куда надо.', 'И куда же ты направляешься, $C?', NULL, NULL, 'Припасы Нургуни (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9606, 'Возвращение к Тоферу Лоаалу', 'Если мне память не изменяет, дрессировкой гиппогрифов на Кровавой заставе занимается Лаандо. Если тебе уже приходилось с ним встречаться, значит, ты можешь передать ему одного из моих гиппогрифов.$B$BС гиппогрифами есть одна тонкость, которую надо постоянно держать в голове: их обучают возвращаться в родной город, но к другому дрессировщику гиппогрифов они полетят только в том случае, если тебе уже доводилось у него бывать.$B$BПоскольку ты $gприбыл:прибыла: сюда на одном из гиппогрифов Лаандо, тебе не составит труда вернуться на Кровавую заставу и отвезти туда припасы.', 'Договоритесь со Стефаносом и наймите у него гиппогрифа для путешествия на Кровавую заставу. На заставе доставьте припасы Нургуни корчмарю Тоферу Лоаалу.', '<Тофер забирает ящик и выслушивает сообщение о том, что крупные предметы будут отправлены на повозке.>$B$BВеликолепно! Теперь мне наконец-то удастся поставить у себя хотя бы несколько кроватей и обеспечить раненых первой помощью!$B$BСловами не передать, как я тебе благодарен, $N, и не только я, но и все защитники Кровавой заставы!', 'Рад твоему возвращению, $N. Ну как, удалось Нургуни достать все, что было в моем списке?', NULL, NULL, 'Припасы Нургуни (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9607, 'В сердце ярости', '$C, немеденно собирай силы и отправляйся на разведку к Кузне Крови в цитадели Адского Пламени! Да-да, вот прямо сегодня, моя радость!$B$BНаши маги сумели засечь, что там происходит что-то из ряда выходящее. Но дальшейшее наблюдения оказалось заблокировано очень мощной защитной магией. Это вам не баран чихнул!$B$BТебе придется столкнуться с жестоким сопротивлением - ни одна группа из тех, что мы отправили на задание, не вернулась.$B$BРазведай все детали, вернись и доложи о результатах боевому командиру.', 'Детально изучите Кузню Крови и доложите об увиденном командиру армии Данату Троллебою в Оплот Чести на полуострове Адского Пламени.', 'У НИХ ЕСТЬ ВЛАСТИТЕЛЬ ПРЕИСПОДНЕЙ?!$B$B<Боевой командир оглядывается на остальных и понижает голос.>$B$BЭто все объясняет. Должно быть, они использовали кровь этого властителя преисподней, чтобы создать орков Скверны. Значит, они тоже связаны с Пылающим Легионом. Если они смогли это сделать с коричневыми орками, значит, рано или поздно доберутся и до зеленых. Если из Темного портала выйдут орки новой Орды, нам придется несладко.$B$BМы должны нанести превентивный удар, и как можно скорее!', NULL, NULL, NULL, 'Исследовать локацию', 'Детально изучите Кузню Крови', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9608, 'В сердце ярости', '$C, ты $gдолжен:должна: собрать отряд и немедленно отправиться в Кузню Крови, в цитадель Адского Пламени! Магические кристаллы показывают, что там происходит что-то странное. Но понять, что именно, не удается, потому что видение заблокировано мощной защитной магией. Ясно только одно, - там творится что-то очень важное.$B$BРассчитывай, что встретишься с жестоким сопротивлением. Ни одна из групп, которые мы отправили на это задание, не вернулась.$B$BРазведай детально, что там происходит, и доложи Назгреллу, советнику Тралла.', 'Детально изучите Кузню Крови и доложите об увиденном Назгрелу из Траллмара на Полуострове Адского Пламени.', 'У НИХ ЕСТЬ ВЛАСТИТЕЛЬ ПРЕИСПОДНЕЙ?!$B$B*Назгрел оглядывается на остальных и понижает голос.*$B$BЭто все объясняет. Должно быть, они использовали кровь этого властителя преисподней, чтобы создать орков Скверны. Значит, они тоже связаны с Пылающим Легионом. Если они смогли сделать это с коричневыми орками, значит, рано или поздно доберутся и до нас!$B$BМы должны нанести превентивный удар, и как можно скорее!', NULL, NULL, NULL, 'Исследовать локацию', 'Детально изучите Кузню Крови', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9609, 'Помощь дозорному Биггсу', 'Магтур сообщил мне, что дозорному, который находится неподалеку, нужна помощь. Очевидно, караван, который он сопровождал из Темнолесья, был атакован Заблудшими. Сдается мне, он единственный, кто выжил после этого нападения.$B$BОн сейчас где-то к югу отсюда. Прошу тебя, $C, помоги ему.', 'Найдите дозорного Биггса на Болоте Печали.', 'Тебя послали дренеи из Убежища? Как странно.$B$BЧто же, я не в том положении, чтобы отказываться от помощи. Спасибо, что пришел, $C!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9610, 'Озеро Слез', 'Я интересуюсь прошлым Азерота. Не хочешь ли мне помочь?$B$BЗдесь в трясинах по соседству находится весьма интересная в историческом отношении местность, в которое я и попросил бы тебя отправиться. К юго-востоку отсюда расположено озеро Слез. Говорят, что на его берегах и в глубинах спрятаны артефакты цивилизации троллей Атал\'ай.$B$BНо берегись, озеро охраняет Сомнус,, древний зеленый дракон и его сородичи, а само оно просто кишит плотоядной рыбой.', 'Добудьте 5 артефактов Атал\'ай и вернитесь с ними к Холаару в Убежище на Болото Печали.', 'Благодарю тебя, $С. Изучение этих артефактов займет меня на какое-то время. Как еще мы, Падшие и дренеи сможем приспособиться к этому миру, если мы не можем понять его истории?', 'Я жду, пока ты соберешь достаточно артефактов Атал\'ай, чтобы можно было начать их изучение. Я просто жажду узнать, что случилось с этой некогда великой цивилизацией.', NULL, NULL, 'Артефакт Атал\'ай', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9612, 'Большое спасибо!', 'Ты $gспас:спасла: мне жизнь, $N! Спасибо огромное! Если бы не ты, эта тварь разорвала бы меня на части.$B$BЕсли будешь на Лазурной заставе, расскажи о своем подвиге ээкзарху. Не сомневаюсь, он очень обрадуется!', 'Поговорите с экзархом Менелаусом на Лазурной заставе.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9616, 'Бандиты!', 'Похоже, это объявление о награде. Язык эльфов крови вам непонятен, но на картинке изображен мертвый дреней, улыбающийся эльф крови, попирающий его труп, и символ, вероятно, означающий денежные единицы.$B$BОказывается, они хотят истребить дренеев! Следует сообщить об этом экзарху.', 'Отнесите сообщение эльфов крови экзарху Менелаусу на Лазурную заставу.', 'Клянусь безбородой кубической головой О\'роса! Хорошо, что ты принес это мне, $N. Эльфы крови жаждут нашей... хм, крови. Необходимо уведомить Велена! Прими это в награду.', 'Да? Я очень занят, $N.', NULL, NULL, 'Сообщение эльфов крови (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9617, 'На поиски Странников', 'Лейтенант Вестница Рассвета в обители Странников созывает к себе всех, кто посвятил себя ремеслу охотника. Тебе стоит повидаться с ней, $N. Она подлинный светоч мудрости для всех нас.$B$BОбитель Странников находится к югу от Луносвета.', 'Поговорите с лейтенантом Вестницей Рассвета в обители Странников.', 'Хорошо, что ты здесь, $N. Наших союзников все меньше, и не всем сторонникам нашего дела можно доверять. Именно поэтому мы, следопыты, обращаемся за помощью к природе.$B$BВ лесу ты найдешь помощников, которые никогда не предадут тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9618, 'Возвращение с донесениями', 'Да, ловкости рук тебе не занимать! Несомненно, тебе эти донесения доверить можно.', 'Отнесите донесения Келтуса Темного Листа Зеланису в Луносвет.', 'Что, это все от него? Да уж, потрудился Келтус на славу!$B$BВот уж всем разбойникам разбойник! Он редко выполняет приказы буквально и часто поступает по своему разумению. Но не пойми меня неправильно: Келтус - один из наших лучших шпионов, без него мы как без рук.$B$BНу, и ты сегодня неплохо потрудилась. Вот, возьми этот клинок - и вонзи его в спину врагу!', 'Ну что, удалось тебе обнаружить Келтуса?', NULL, NULL, 'Стопка донесений (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9619, 'Руна призыва', 'В камне Бездны проступает многоярусное здание, по которому бродят призрачные фигуры. По мере того как изображение становится отчетливее, появляются все новые здания. Судя по всему, это деревня Золотистой Дымки.$B$BВнезапно крыши и кроны деревьев проносятся мимо, и открывается путь в деревню Золотистой Дымки, ведущий вдоль реки Элрендар на запад.$B$BСтупайте туда; оказавшись там, используйте камень пустоты близ руны призыва на вершине центрального здания и повергните вызванного демона Бездны. Только после этого вы можете вернуться к своей наставнице.', 'Используйте камень Бездны, чтобы призвать демона Бездны в деревню Золотистой Дымки, одолейте демона и вернитесь к Талионии в Луносвет.', 'Я рада видеть тебя здесь, Котячий. Немало учеников погибло в битве с демоном Бездны; немало и таких, кого погубил сам камень Бездны.$B$BТеперь этот демон Бездны подчиняется только тебе. Используй его с умом!', 'Прошла ли ты по пути, указанному тебе камнем Бездны?', NULL, NULL, 'Призванный демон Бездны убито', 'Камень Бездны (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9620, 'Пропавшие картографы', 'После того как мы обосновались здесь, на Кровавой заставе, я посылал разведовательные группы, чтобы составить более точные карты острова. Обычно разведчики возвращались целыми и невредимыми и исправно снабжали меня необходимыми сведениями; но группа, которую я отправил на восток, к развалинам, так и не вернулась.$B$BБоюсь, с ними что-то случилось... но нас не так много, чтобы снаряжать поисковую экспедицию. Прошу тебя, $N, разыщи их! Помоги им, если они нуждаются в помощи. Надеюсь, они вернутся – и не с пустыми руками...', 'Предвестник Миколаас просит разыскать группу разведчиков, которую он послал к развалинам Лорет\'Арана, и помочь группе чем только возможно.', 'Живых не осталось. Разведчики-дренеи погибли, сраженные оружием наг. Их вещи разбросаны по земле, и только кристаллы с исследовательскими данными исчезли бесследно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9621, 'Посол к Орде', 'Наши потенциальные союзники сомневались в наших способностях. Какая им от нас польза, если мы собственные проблемы решить не можем?$B$BТеперь все изменилось. В нашей силе никто не усомнится. Мы сможем вступить в Орду как равные.$B$BОтнеси это письмо Сильване, правительнице Отрекшихся. Она и так на нашей стороне, но весть о смерти Дар\'Хана будет воистину музыкой для ее ушей. Готовься к долгому пути, $N. Если все сложится благополучно, Сильвана пошлет тебя в Оргриммар.', 'Отнесите письмо от Лор\'темара Терона леди Сильване Ветрокрылой в Подгород, столицу Отрекшихся в Тирисфальских лесах.', 'Итак, свершилось. Подлый предатель получил по заслугам.$B$BТак этот подвиг совершила ты? Подобные свершения доказывают, что ваша раса не ослабела, Котейшество.$B$BЯ вижу, что вести Лортемара значительно улучшат его отношения с Траллом.', 'А, гость из Кель\'Таласа! Какие вести ты принесла?', NULL, NULL, 'Письмо Лор\'темара Терона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9622, 'Предупреди свой народ', 'Форт спасен. Скоро мой народ вернется в дом предков. Пророчество исполнилось, и для племени Тихвой наступает век процветания.$B$BУвы, твой народ ожидает темный путь. Пророчество говорило не обо всем, многие вопросы остались без ответа.$B$BВозвращайся к своим правителям и расскажи им обо всем, что $gвидел:видела: здесь.$B$BИ помни, $gИзбранный:Избранная:: стоит только попросить, и племя Тихвой придет тебе на помощь.', 'Поговорите с экзархом Менелаусом на Лазурной заставе.', 'Видения, говоришь? Интересно... Так пророчество сбылось?$B$BЗначит, они видели энергетическое ядро Экзодара? И О\'рос тоже являлся им в видении? Что бы это значило?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9623, 'Время пришло', 'Ты $gпокорил:покорила: дикие леса нашей новой родины и $gпроявил:проявила: себя с лучшей стороны. Я думаю, ты $gготов:готова: отправиться на остров Кровавой Дымки и вступить в бой с нашими врагами. Такие как ты нужны Длани Аргуса. $B$BПоговори с Тораллиусом Пастухом. Он присматривает за элекками неподалеку от Экзодара. Передай ему мои распоряжения, чтобы он немедленно ознакомил тебя с новыми обязанностями на острове Кровавой Дымки.', 'Передайте распоряжения экзарха Тораллиусу Пастуху. Он находится у Экзодара, недалеко от входа.', '<Тораллиус вздыхает.>$B$BЛадно, давай распоряжения – почитаем.', '<Тораллиус поправляет повязку на глазу и пристально изучает вас.>$B$BНеужели мы не можем послать на помощь Длани Аргуса достойного героя?', NULL, NULL, 'Распоряжения Экзарха (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9624, 'Любимое блюдо', 'Послушай, $C, Я сделал замечательное, грандиозное открытие! В той части острова, которая не была затронута скверной, растет восхитительный фрукт, именуемый песчаной грушей. Их находят у корней деревьев.$B$BЯ готовил с ними грушевые пироги, но выяснилось, что элекки – большие охотники до песчаных груш, так что они частенько подъедали мои запасы. Тогда я решил делать запас побольше, чтобы хватало и мне, и элеккам, – но, увы, все мои запасы пропали, а пирогов-то хочется... Я вот и подумал: может, ты мне поможешь запастись песчаными грушами? А я с тобой непременно поделюсь, когда напеку пирогов, обещаю!', 'Принесите 10 песчаных груш Аонару в лагерь Кессела.', 'Нелегко собирать груши, да? У меня на это уходит все больше и больше времени...$B$BНаверное, скоро мне и вовсе придется отказаться от грушевых пирогов. Даже не представляю, как я тогда буду жить. Но пока что, благодаря тебе, Кудзор, мне хватит груш, чтобы испечь один-два пирога...', 'Найти песчаные груши все труднее – а это значит, что я могу печь все меньше пирогов, а уж элеккам и вовсе почти ничего не останется... Но, может, ты принесешь мне хоть немного груш?', NULL, NULL, 'Песчаная груша', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9625, 'Элекки – это серьезно', 'Он что, спятил? Разве можно доверять $gбезвестному:безвестной: $r такое важное дело!$B$BИ запомни, малявка: тебе никогда не войти в ряды Длани Аргуса! Кишка у тебя тонка!$B$BВпрочем, на сей раз придется пойти у него на поводу. Поговори с Ворканом в лагере Кессела на острове Кровавой Дымки. Иди по этой дороге на север, на развилке не сворачивай, иди все время на север.', 'Поговорите с Ворканом Пастухом Элекков на острове Кровавой Дымки.', 'Ну, раз ты так далеко добрался, надо приставить тебя к работе, пока у тебя не наберется достаточно познаний.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9626, 'Встреча с вождем', 'Я по-прежнему всей душой люблю свою родину и свой народ. Я билась зубами и когтями за то, чтобы Луносвету предоставили место за столом переговоров наравне с Подгородом и Оргриммаром.$B$BЭто должно заставить всех недовольных умолкнуть. Отнеси это письмо Траллу в Оргриммар. Ему, как главе Орды, принадлежит последнее слово относительно того, будет ли удовлетворена просьба син\'дорай.$B$BК этому письму приложена моя личная печать, как доказательство подлинности. Ступай на северо-запад города и у башни сядь на дирижабль до Дуротара.', 'Отнесите письмо с печатью Леди Сильваны Ветрокрылой Траллу в Оргриммар, столицу Дуротара.', '*Тралл открывает письмо и начинает читать.*$B$BЭтой леди Сильване упорства не занимать. Значит, теперь она прислала одного из героев Луносвета... Но что это меняет?', 'Ты ко мне, $R? Говори, да побыстрее. Мне не до ваших церемоний.', NULL, NULL, 'Письмо с печатью Сильваны (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9627, 'Верность Орде', 'Предательство Альянса навлекло на твой народ множество бед. Тебе удалось отбить нападение дарнассийцев и противостоять шпионам Стальгорна, а теперь на твоем счету еще и победа над могучим командиром Плети. Только глупец сможет усомниться в твоей силе.$B$BВозвращайся к Лортемару и скажи, что я получил его послание.$B$B*Вождь сминает письмо в руке.*$B$BДобро пожаловать в Орду, эльф.', 'Возвращайтесь в Луносвет и поговорите с Лор\'темаром Тероном. ', 'Ты оказала нам неоценимую услугу. Теперь Тралл считает нашу расу сильной и могущественной и верит, что сможет с нашей помощью воззвать к своим сородичам в Запределье.$B$BЧто ж, он почти прав. Почти.$B$BНастала эпоха великих перемен, Котейшество. Теперь мы стали частью Орды.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9628, 'Цена знания – жизнь', 'Похоже, картографам уже не понадобится никакая помощь. Однако они, скорее всего, успели собрать информацию, которая так нужна предвестнику Миколаасу. Кристалла с результатами наблюдений среди вещей убитых не обнаружилось – следовательно, он попал в руки наг из клана Зловещей Чешуи.$B$BПредвестник Миколаас, конечно, будет весьма огорчен, узнав о гибели своих картографов, но еще больше его огорчит, если все их труды пропадут впустую.', 'Неподалеку от того места, где были убиты картографы, обитают наги из клана Зловещей Чешуи. Отберите у них кристалл с результатами наблюдений и доставьте его на Кровавую заставу предвестнику Миколаасу.', '<Выслушав рассказ о судьбе исследовательской группы и забрав кристалл, предвестник Миколаас не сразу решает продолжить разговор.>$B$BОни были одними из лучших, $N, и знали, на что идут. Я благодарен тебе за помощь. Хотя судьба наших исследователей и оказалась столь печальной, но тебе все же удалось принести кристалл...$B$B<Вестник сжимает кулаки.>$B$BМы уже потеряли слишком многих - а наша миссия еще далека от завершения!..', 'Тебе удалось выяснить, что помешало исследовательской группе вернуться?', NULL, NULL, 'Кристалл с исследовательскими данными', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9629, 'Поймать и отпустить', 'Живущие на юго-западном побережье мурлоки из племени Черного Ила – весьма любопытные создания. В некоторых случаях они поступают почти как неразумные звери, в других же проявляют завидную организованность.$B$BУ меня на этот счет есть несколько теорий, но до сего момента я не имела возможности их проверить. Я разработала одно устройство, позволяющее следить за интересующими меня особями мурлоков, не нанося им существенного вреда и не влияя на их естественное поведение. Если ты поможешь мне с метками, можешь быть $gуверен:уверена:: я хорошо тебе заплачу.', 'Морэ с Кровавой заставы просит вас \"пометить\" 6 разведчиков из племени Черного Ила при помощи маркировщика мурлоков.', 'Прекрасная работа, $N. Я боялась, что маркировщик не сработает так, как надо, но, похоже, все прошло именно так, как задумывалось.', 'Ну как, сработал мой маркировщик? Тебе удалось поставить мурлокам метки? Это помогло бы мне существенно продвинуться в исследованиях...', NULL, NULL, 'Пометьте разведчиков из племени Черного Ила', 'Маркировщик мурлоков (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9630, 'Дневник Медива', 'Я слышал о тебе, $N. Ты заходишь в Каражан и выходишь обратно так свободно, как никто из смертных.$B$BЯ хочу попросить тебя об особой услуге. Аметистовое Око пыталось выяснить местонахождение собственноручных дневников Медива - это было одним из предметов наших поисков.$B$BК сожалению, никто из посланных агентов назад не вернулся. Вравьен был одним из последних, отправленных нами. Разыщи его, если сможешь, и узнай что-нибудь о записях.', 'По поручению верховного мага Альтура на Перевале Мертвого Ветра войдите в Каражан и поговорите с Вравьеном.', 'Сколько всего нового и неизведанного! Я готов провести здесь годы! Я уверен, в Даларане поймут меня...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9631, 'Взаимовыручка', 'Есть одна небольшая деталь, про которую я совершенно забыл. Остаток сущности Медива, заключенный в этом фрагменте кости, абсолютно лишен жизни - так же, как и Чарозмей.$B$BНо, тем не менее, есть способ все исправить. И я знаю человека, который может помочь нам.$B$BСтупай в Область 52 в Пустоверти и покажи эту кость Калинне Латред. Она сообразит, что можно сделать.', 'Доставьте фрагмент обугленной кости Калинне Латред в Зону 52 в Пустоверти.', 'Альтур хочет, чтобы я подняла из мертвых целого дракона? Мда, такое дело трудно даже представить.$B$BНо, думаю, я сумею вам помочь, $N. Если вы, в свою очередь, поможете мне.', 'Вас прислал Альтур. Звезды предупредили меня о вашем прибытии.', NULL, NULL, 'Фрагмент обугленной кости (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9632, 'Новые союзники', 'Думаю, тебе уже известно, $C, сколько усилий приложил предвестник Миколаас, чтобы обеспечить надежную защиту Кровавой заставе. Но несмотря на это, нам по-прежнему не хватает ресурсов, зато врагов явный избыток.$B$BВрагам хорошо известна эта наша слабость, однако они не принимают в расчет то, что мы можем заручиться поддержкой Альянса. Я подготовил рекомендательное письмо: его нужно доставить в Аубердин, ближайший к нам оплот Альянса. Надеюсь, они прислушаются к нашему предложению, и вместе мы разгромим врагов. Отнеси это письмо охотнице Келле Тетиве Ночи на пристань к западу от Экзодара.', 'Доставьте рекомендательное письмо охотнице Келле Тетиве Ночи на Остров Лазурной Дымки.', 'Конечно, я помогу тебе попасть в Аубердин. По счастью, тут по морю совсем недалеко.', 'Приветствую тебя, $C. У тебя ко мне дело?', NULL, NULL, 'Рекомендательное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9633, 'Дорога к Аубердину', 'Подожди на пристани. Скоро из порта Аубердин, что на Темном Берегу, прибудет корабль. Когда пассажиры сойдут на берег, ты сможешь подняться на борт.$B$BПутешествие будет недолгим - конечно, если ты не страдаешь морской болезнью. Сойдешь на берег в Аубердине, а там уже доставишь письмо по назначению.$B$BДумаю, лучше всего обратиться к моему старому другу и весьма уважаемому жителю Аубердина; его зовут Тандрис Ветропряд.', 'Сядьте на корабль, идущий в Аубердин. Пристань находится неподалеку от дома охотницы Келлы Тетивы Ночи. В Аубердине отдайте рекомендательное письмо Тандрису Ветропряду.', '*Тандрис берет рекомендательное письмо, пробегает его глазами и кивает.*$B$BВ давние времена мой народ жил на островах, которые дренеи называют островами Лазурной и Кровавой Дымки. Анахорет Пайтеус и его братия, по всей видимости, столкнулись с древними врагами ночных эльфов...$B$BУверен, Аубердин окажет своим новым союзникам всю возможную поддержку. Я пошлю весточку Пайтеусу, как только поговорю с жителями города и часовыми.', 'Добро пожаловать в Аубердин, добрый друг. Что привело тебя на Темный Берег?', NULL, NULL, 'Рекомендательное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9634, 'Чужие-хищники', 'В наших странствиях мы хорошо усвоили один урок: нужно быть крайне осторожным, перенося животных и растения из одного мира в другой. На \"Экзодаре\" при крушении были образчики многих видов нездешних существ, в том числе насекомовидный хищник, который зовется опустошителем.$B$BНекоторые экземпляры погибли; другие не только выжили, но и приспособились к новым условиям. Если мы не озаботимся этим вопросом, они могут нарушить экологический баланс на островах.$B$BТы найдешь опустошителей неподалеку от лагеря Кессела, к западу отсюда. Насколько мне известно, они поселились неподалеку от берега.', 'Убейте 10 детенышей опустошителя с острова Кровавой Дымки и вернитесь к Воркану Пастуху Элекков. Воркана можно найти на острове Кровавой Дымки в лагере Кессела.', 'Прекрасная работа, $N! Нам придется еще некоторое время следить за местной популяцией опустошителей, но начало, безусловно, положено.', NULL, NULL, NULL, 'Детеныш опустошителя с острова Кровавой Дымки убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9635, 'Удаленный конденсатор выхлопов!', 'Болотный газ – потрясающая вещь! Он может быть весьма ценным! Но сначала его нужно собрать - а вот для этого-то нам и потребуется удаленный конденсатор выхлопов!$B$BЯ могу тебе дать чертежи такого конденсатора, но хочу получить что-нибудь взамен. Например, мне нужны кое-какие запчасти. Я знаю, что еще не так давно куча полезных деталей валялась вокруг сломанного парового насоса в Мертвой трясине, к северо-востоку отсюда.$B$BЯ слышал, что это иссохшие великаны растащили детали по всему дну пересохшего озера.', 'Принесите 15 деталей парового насоса Маку Дайверу в Забра\'джин в Зангартопи.', 'Отлично! Теперь, если добыть скользящую петлю, пергаментное крепление, хлебательную трубку и липкую ленту, получится то, что надо!$B$BНу ладно, ладно! Ты заслужил награду, я же и не спорю! Счастливо, $N.', 'Ну что, где запчасти? Мой водолазный костюм нуждается в ремонте...', NULL, NULL, 'Деталь парового насоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9636, 'Удаленный конденсатор выхлопов!', 'Доводилось ли вам видеть болотный газ? Блестящая штука, не правда ли?$B$BНо для того, чтобы извлечь из него все полезное, нужен удаленный конденсатор выхлопов! Я могу вам дать чертежи такого конденсатора, но мне нужны запчасти для ремонта техники.$B$BЯ знаю, что еще не так давно куча деталей валялась вокруг парового насоса в Мертвой трясине, к северо-востоку отсюда. Думаю, это иссохшие великаны разрушили насос.$B$BНу что, поможем друг другу?', 'Принесите 15 деталей парового насоса К. Ли Мелюзге в Телредор в Зангартопи.', 'Блестяще! Знаете, лишние запчасти инженеру никогда не лишние! А может быть, я продам часть из них, и куплю себе клубничного мороженого Тигуле и Форора? Обожаю клубнику! Как вы думаете, где его тут продают поблизости?$B$BАх, ну да, ну да! Думаю, вы это заслужили, $N. Счастливо!', 'Ну что, где запчасти? Мне нужно починить кольцедав, пока анахорет Ахуурн не настучал мне по голове!', NULL, NULL, 'Деталь парового насоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9637, 'Требование Калинны', 'Мне пришлось покинуть Кирин-Тор в поисках знаний, которые орден считал запретными. Есть некая ирония в том, что теперь орден просит моей помощи именно по этому вопросу.$B$BМожет быть, я помогу тебе. Но сначала хочу, чтобы ты кое-что для меня $gсделал:сделала:. Мне нужны две книги, я уже давно пытаюсь их раздобыть $B$BПервая называется Фолиант Сумерек. Им владеет орочий чернокнижник Пустоклят. Вторая, Книга Забытых Имен, находится у араккоа, известного как Темнопряд Сит.', 'Калинна Латред требует отыскать и принести ей фолиант сумерек и книгу забытых имен. Первой владеет главный чернокнижник Пустоклят, его можно найти в Разрушенных залах цитадели Адского Пламени. Вторая принадлежит заклинателю тьмы Ситу, который находится в Сетеккских залах в Аукиндоне.Это задание должно быть выполнено на героическом уровне сложности.', 'Блестяще, $N. Я долго пыталась завладеть этими книгами. Большая удача, что мы смогли помочь друг другу.', 'Ну что, ты принес мои книги?', NULL, NULL, 'Книга Забытых Имен', 'Фолиант сумерек', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9638, 'В хороших руках', 'Мне надо было искать эти записи? Быть того не может. Не помню ничего подобного.$B$BНу конечно! Ты имеешь в виду Градава. Это он искал какую-то книгу, когда я тут торчал. Мне кажется, вряд ли он до сих пор сумел ее отыскать. А почему бы тебе не поговорить с ним лично?$B$BЯ б тебе помог, но... эти книги такие... захватывающие!', 'Поговорите с Градавом в Библиотеке стража в Каражане.', 'Не видишь, что ли, что я очень занят? Чего тебе нужно?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9639, 'Камсис', 'Дневник, какой дневник? Конечно, ты имеешь в виду Камсис.$B$BСтупай и спроси ее об этом. Если я сейчас оторвусь от работы, то все пойдет н$Nку!', 'Поговорите с Камсис в Библиотеке Стража в Каражане. ', 'Эти записи, о которых ты говоришь... Меня послали найти их, да?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9640, 'Тень Арана', 'Дай мне подумать секунду. Аметистовое Око... Журнал Медива... Да, теперь я что-то припоминаю.$B$BМне кажется, у меня был этот журнал, пока я не начала читать эти манускрипты...$B$BАран... Да, Аран тоже спрашивал меня об этой книге. Правда, какое милое совпадение? Так и есть, должно быть, я отдала книгу ему. В конце концов, он же отец Медива.', 'Достаньте дневник Медива и верните его Камсис в Библиотеку Стража в Каражане.', 'Ну как, нашел, что искал? Ты ведь искал что-то, правда?', 'Не ищещь ли ты, часом, что-нибудь вроде журнала?', NULL, NULL, 'Дневник Медива', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9641, 'Осколки облученного кристалла', 'В результате крушения \"Экзодара\" фрагменты оскверненных кристаллов оказались разбросанными по всему острову Кровавой Дымки; их скверна отравила воды и землю.$B$BМы обнаруживали осколки кристаллов даже в плоти животных, добытых на охоте. Однако я нашел способ очищать кристаллы от скверны и использовать их по назначению. Если ты принесешь мне достаточное количество осколков, взамен я отдам тебе один из целых кристаллов. Думаю, тебе нужно знать, что осколки обнаруживались в телах медведей, опустошителей, бражников и древней, обитающих в оскверненной части острова.', 'Принесите 10 осколков облученного кристалла воздаятелю Боросу на Кровавую заставу.', 'Неплохо. Теперь у меня есть исходные материалы для воссоздания кристаллов.$B$BТы можешь выбрать один из трех видов кристаллов, которые я могу создать. Каждый вид хорош для охоты на определенную добычу...', 'Ну как, удалось тебе собрать осколки кристаллов? Я говорил, их можно найти в телах животных и на стволах деревьев...', NULL, NULL, 'Осколок облученного кристалла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9642, 'И снова облученные кристаллы', '', '', 'Прекрасно, прекрасно! А вот и мои кристаллы, $N. Надеюсь, ты найдешь им применение.', NULL, NULL, NULL, 'Осколок облученного кристалла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9643, 'Удушающая лоза', 'У хорошего лесника все идет в дело, $C. Даже самые странные существа зачастую обладают весьма полезными для нас особенностями.$B$BСолнечные Ястребы постоянно нападают на Кровавую заставу; тут уж все средства защиты хороши, не исключая и ловушки. Мне тут на ум пришла одна ловушка, для которой прекрасно подойдет колючая лоза. Острые шипы и смертельный яд – прекрасная комбинация, которая надолго отобъет охоту у любого соваться на заставу. Принеси мне несколько побегов мутировавшей удушающей лозы, и я немедленно примусь за работу.', 'Принесите зверолову Лисеону 6 побегов колючей удушающей лозы. ', 'Да, похоже, лозы достаточно прочные и вполне подойдут для моих целей. Благодарю за помощь, $N, ты сделал большой вклад в наше дело.', 'Что, удалось тебе добыть побеги?', NULL, NULL, 'Колючая удушающая лоза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9644, 'Ночная Погибель', 'Ты $gсделал:сделала: то, что $gобещал:обещала:. Теперь я соединю твою сущность с сущностью мертвого синего дракона.$B$BНа террасе Мастера находится урна, дотронувшись до которой ты высвободишь энергию, позволяющую оживить обугленные останки Арканагоса. Тебе придется немедленно сразиться с ним, а потом извлечь сущность из этой твари и отнести Альтурусу.$B$BЗвезды говорят, что если ты потерпишь поражение в бою с этим драконом, то позволишь страшной угрозе обрушиться на мир.$B$BИмя этой угрозе – Ночная Погибель!', 'Ступайте на террасу Мастера в Каражане и прикоснитесь к урне Калинны, чтобы призвать Ночную Погибель. Извлеките из тела Ночной Погибели слабую чародейскую сущность и доставьте ее верховному магу Альтуру.', 'Невероятно. Вам удалось добыть не только записи Медива, но даже часть его собственной сущности.$B$BХотя эта сущность невероятно слаба, она все равно сумеет дать нам жизненно важные сведения о Медиве. Мы не забудем того, что вы для нас сделали.', 'Какие вести с фронта, $N?', NULL, NULL, 'Слабая чародейская сущность', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9645, 'Терраса Мастера', 'Дневник? Какой дневник?$B$BА, точно! Тот самый дневник! Меня послало за ним братство Аметистового Ока. Кажется, теперь что-то припоминаю.$B$B*Камсис указывает на страницу из дневниковых записей.*$B$BАльтуру нужна вот эта страница. Знаешь, если другие ведут записи, чтобы сохранить память о событиях, то Медив буквально впечатал в них собственную память.$B$B<Сам:Сама: посмотри. Поднимись на террасу Мастера, прочти эту страницу - и поймешь, что я имею в виду. Можешь рассказать об этом Альтуру, если ты все равно к нему возвращаешься. Боюсь, мне придется тут задержаться еще на некоторое время.', 'Поднимитесь на террасу Мастера в Каражане и прочитайте дневник Медива. После этого возвращайтесь вместе с дневником к верховному магу Альтуру.', 'Просто позор, что наши люди поддались магии Каражана. Ну, по крайней мере, тебе удалось добыть то, за чем их послали.', 'Ты вернулся! Какие новости ты принес мне?', NULL, NULL, 'Дневник Медива (Прилагается)', 'Запись прочитана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9646, 'РАЗЫСКИВАЕТСЯ: Коготь Смерти', 'Указ предвестника Миколааса: \"Награда в 18 серебряных монет будет выплачена тому смельчаку, кто покончит с медведем по кличке Коготь Смерти и предоставит доказательства его смерти.$B$BЭтот медведь признан крайне опасным; имеются подтвержденные сведения о том, что именно он уничтожил отряд, исследовавший берег острова к северо-западу от Кровавой заставы. Путешественникам временно не рекомендуется посещать эту территорию.\"', 'Принесите лапу Когтя Смерти предвестнику Миколаасу на Кровавую заставу.', 'Прекрасно. Я вижу, бой был не из легких... Полагаю, ты вполне заслуживаешь награды, $N.', 'Я могу тебе чем-нибудь помочь, $C?', NULL, NULL, 'Лапа Когтя Смерти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9647, 'Ловля бражников', 'Когда мы впервые столкнулись с бражниками, мы не заметили у них никаких отклонений. Однако скверна расползалась по острову, и вскоре у всех живых существ начали проявляться признаки заражения.$B$BДошло до того, что бражники, прежде не доставлявшие нам особого беспокойства, начали разрушать все, с чем соприкасаются. Как будто мало вреда было от кристаллов, усеявших все вокруг после крушения \"Экзодара\"!.. У нас просто не оставалось иного выбора: приходится отлавливать их, чтобы хоть немного исправить ситуацию в землях к северу от Кровавой заставы.', 'Зверолов Лисеон просит убить 10 царственных синих бражников.', 'Со временем мы найдем способ вернуть этот вид к его природному состоянию, но пока что мы можем только периодически сокращать их количество. Другого выхода у нас нет. Благодарю за помощь, $N.', NULL, NULL, NULL, 'Царственный синий бражник убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9648, 'Грибная похлебочка Матпарма', 'А известно ли тебе, что грибная охота намного опаснее, чем поглощение грибов? Грибники подвергают себя множеству неведомых опасностей – ведь в лесу видимо-невидимо разных тварей!$B$BС другой стороны, что такое жизнь без риска? К тому же мне нужны грибы. Для коллекции. В здешних неисследованных землях можно найти четыре весьма любопытных типа грибов: водянистый смрадорог, кровавый гриб, губительную полиспору и скверноконус. В каждом регионе острова Кровавой Дымки растет только один из видов этих грибов. Принеси их мне.', 'Матпарм просит принести ему на Кровавую заставу по одному экземпляру водянистого смрадорога, кровавого гриба, губительной полиспоры и конусовидной поганки.', 'Ну, я же тебя предупреждал, верно? Впрочем, надеюсь, оплата послужит достаточной компенсацией за те небольшие неудобства, которые тебе довелось испытать. Когда восстановишь силы, возвращайся: возможно, я найду для тебя новое задание... Грибы – такая вещь, которой не бывает много!', 'Помни: в каждой части острова Кровавой Дымки растет только один из видов нужных мне грибов.', NULL, NULL, 'Водянистый смрадорог', 'Кровавый гриб', 'Губительная полиспора', 'Скверноконус');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9649, 'Слеза Изеры', 'Рад снова тебя видеть, $N! Тебе просто блестяще удалось выполнить мое предыдущее задание. Так вот, я тут подумал: может, тебя не затруднит выполнить еще одну небольшую просьбу?$B$BК северо-востоку отсюда находится остров Драконьей Скорби, где можно отыскать редчайшую разновидность грибов, именуемую \"Слезой Изеры\" - это в честь зеленых дракончиков, обитающих на острове. Нет, сами грибы не зеленые. А какая тут связь?.. Хм, позволь мне не вдаваться в подробности. Мне нужен только малюсенький образец этих грибов... Да, совсем забыл: обитатели острова не слишком гостеприимны, так что будь поосторожнее...', 'Матпарм просит принести ему на Кровавую заставу 2 экземпляра Слезы Изеры.', 'Надеюсь, это задание не было слишком обременительным, $N? О да, любой $r может позавидовать твоим знаниям и умению серьезно подходить к делу. Позволь заверить тебя в моей искренней благодарности - а заодно предложить небольшое вознаграждение...', 'Что, уже вернулся?', NULL, NULL, 'Слеза Изеры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9663, 'Дуга Кессела', 'Ты как раз вовремя, $N. За последнюю неделю активность эльфов крови подозрительно возросла. Наши разведчики докладывают, что та часть эльфов, которая называет себя Солнечными Ястребами, в ближайшее время собирается напасть на остров Лазурной Дымки. Я хочу, чтобы ты $gпередал:передала: это предупреждение нашим союзникам и сподвижникам...$B$BТебе нужно повидать верховного вождя племени Тихвой в логове племени Тихвой, экзарха Менелауса на Лазурной заставе и адмирала Одиссия в лагере Одиссия.$B$BВремя дорого, потому ты отправишься в путь на моем элекке. И помни: не загоняй его в воду.', 'Сообщите верховному вождю племени Тихвой, экзарху Менелаусу и адмиралу Одиссию о готовящемся вторжении эльфов крови, а затем возвратитесь к Кесселу. У вас есть 15 минут. Элекка следует держать подальше от воды.', 'Прекрасно, $N! Конечно, для тебя это была суровая проверка, однако ты блестяще выдержал ее! Но помни: чтобы стать воином Длани, тебе придется пройти не одно испытание...', NULL, NULL, NULL, 'Предупредите верховного вождя племени Тихвой', 'Экзарх Менелаус предупрежден', 'Предупредите адмирала Одиссия', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9664, 'Новые форпосты', 'Добро пожаловать в Чумные земли,$N. Как тебе известно, Отрекшиеся и их приспешники удерживают земли к западу отсюда, несмотря на все наши усилия. Командующие Альянса приняли решение укрепить наши прифронтовые позиции, завоевав новые укрепления.$B$BБашни, давно заброшенные и позабытые еще в дни Лордерона, необходимо захватить и восстановить. Это очень опасные земли, и нам потребуется твоя помощь.', 'Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и башню Проклятого леса в Восточных Чумных землях и вернитесь к посланнику Белобороду в Часовню Последней Надежды.', 'Превосходно, $N. Теперь необходимо удерживать эти башни до прибытия подкрепления – для этого нам потребуется твоя помощь.', NULL, NULL, NULL, 'Захватите башню Королевской Стражи', 'Захватите Восточную башню', 'Захватите башню Северного перевала', 'Захватите башню Проклятого леса');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9665, 'Укрепим оборону', 'Разведчики Отрекшихся раскрыли планы Альянса создать новые форпосты в Восточных Чумных землях на базе заброшенных башен.$B$BНельзя позволить им закрепиться на наших восточных границах, поэтому необходимо помешать планам Альянса. Мы должны выманить их войска из тех башен, которые они уже успели захватить, и занять те, которые еще не были захвачены.', 'Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и башню Проклятого леса в Восточных Чумных землях и возвращайтесь к посланнику Гормоку в Часовню Последней Надежды.', 'Это хорошие вести, $N. Мы будем биться в Чумных землях до конца, пока окончательно не разобьем силы Альянса.$B$BДо этого дня надеюсь на твою помощь.', NULL, NULL, NULL, 'Захватите башню Королевской Стражи', 'Захватите Восточную башню', 'Захватите башню Северного перевала', 'Захватите башню Проклятого леса');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9666, 'Демонстрация силы', 'Тебе уже доводилось видеть змеелюдей? Тех самых, которые называют себя нагами?$B$B<Кессел с отвращением сплевывает.>$B$BТри ночи прошло с тех пор, как они осмелились напасть на этот лагерь. Примитивные твари! Какова наглость, а?$B$BПослушай, $N, я хочу, чтобы ты кое-что $gсделал:сделала: для меня. На северо-востоке отсюда находится логово клана Зловещей Чешуи, где обитает лорд Ксиз. Найди его, убей и пронзи его тело древком этого знамени!$B$BПусть скользкие твари трепещут при виде нашего штандарта!', 'Проникните в логово клана Зловещей Чешуи, убейте лорда Ксиза и пронзите его тело древком дренейского знамени.', 'Мне очень жаль, что тебе пришлось сделать это, $N. Насилие - не тот путь, который предпочитают дренеи; однако иногда другого пути попросту нет.$B$BЭто - одна из тех истин, понимание которых ко многим приходит слишком поздно. Так было и с нашим народом, когда орки уничтожали нас...$B$BСтав одним из братства Длани Аргуса, ты родишься вновь. Но помни, что рождение - это всегда боль...', NULL, NULL, NULL, 'Лорд Ксиз убито', 'Демонстрация силы', 'Дренейское знамя', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9667, 'Спасение принцессы Тихвой', 'Умоляю тебя, $N, помоги мне! Меня взяли в плен фурболги из племени Косолапов. Они хотят принести меня в жертву их нечистым богам!$B$BКлюч от клетки – у вождя племени. Но он так просто здесь не объявится. Чтобы вынудить вождя сделать это, тебе придется убить обитающих здесь фурболгов – уничтожить два лагеря племени Косолапов к западу отсюда. Не сомневайся: вождь непременно придет, чтобы отомстить за смерть соплеменников – а когда это произойдет, ты убьешь его и заберешь ключ.$B$BЕсли ты спасешь меня, мой отец не поскупится на награду!', 'Выпустите принцессу Тихвою из клетки, а затем найдите на Кровавой заставе посла племени Тихвой Олорга и поговорите с ним.Чтобы раздобыть ключ от клетки, убейте верховного вождя племени Косолапов.', 'И вот еще одно доказательство тому, что пророчества говорили именно о тебе. Прими мою вечную благодарность, $N, а в придачу – одну из реликвий племени Тихвой...', NULL, NULL, NULL, 'Спасите принцессу Тихвой', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9668, 'Доклад экзарху Адметиусу', 'Солдат Длани Аргуса должен обладать многими качествами: быть покорным, отважным, разумным - но прежде всего благородным. Надеюсь, у тебя еще будет возможность проявить хотя бы часть этих качеств, $C.$B$BЕсли ты все еще хочешь присоединиться к братству Длани, отправляйся на Кровавую заставу к экзарху Адметиусу. Он и его подчиненные обучат тебя и превратят в настоящего солдата дренеев. Насколько это возможно.$B$BИ вот еще что запомни, $N: не всегда благородные существа ведут себя честно и благородно. Иногда они просто не могут позволить себе этого.$B$BНу, довольно болтовни, отправляйся на Кровавую заставу - это прямо по дороге на север.', 'Поговорите с экзархом Адметиусом на Кровавой заставе.', 'Я чувствовал, что ты сумеешь пройти этот путь, $С. Что ж, если ты хочешь и дальше следовать своему предназначению, я готов учить тебя...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9669, 'Пропавшая экспедиция', 'Около недели назад мы проводили разведку западных пустошей острова Кровавой Дымки, когда на нас напали кровожадные пауки. Насколько я могу судить, их размеры и чрезвычайная агрессивность обусловлены действием кристаллов.$B$BМне удалось спастись, но моим спутникам повезло меньше. Нельзя допустить, чтобы и других постигла та же печальная участь. Отправляйся на запад к перевалу Янтарной Паутины: нужно уничтожить пауков и их матриарха Зарак.', 'Убейте 8 пауков-ткачих, 8 паучих-кровопийц и матриарха пауков – Зарак. По завершении задания вернитесь на Кровавую заставу к Акелусу.', 'Невероятно! А удалось тебе хоть кого-то найти, или все погибли?$B$B*Акелус понижает голос до шепота.*$B$BЯ буду с тобой откровенен, $N: это задание больше никто не хотел выполнять. Отважный ты $C...', NULL, NULL, NULL, 'Паучиха-кровопийца убито', 'Ткачиха убито', 'Зарак убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9670, 'Они живы! Может быть...', 'Ты представить себе не можешь, $N, что мне пришлось пережить! Ужас! Кошмарный сон!.. На нас набросились пауки, будь они прокляты, да к тому же их прародительница, чтоб у нее все лапы поотсыхали, как с неба свалилась и тут же запеленала нас всех в коконы!$B$BНо это было еще полбеды, эта членистоногая зараза пристроилась рядом с нами и начала откладывать яйца! Представляешь? Она решила, что мы - отличный корм для ее молодняка. КОРМ! Вообрази только!$B$BМне-то кое-как удалось выбраться, а мои товарищи так и валяются там, спеленутые, как младенцы. В одиночку мне их не спасти, я даже близко не могу подойти к тому проклятому месту. Ты ведь поможешь мне, верно?$B$BРаспутай коконы! Может, хоть кто-то еще из наших остался в живых!', 'Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса.', 'Тебе удалось спасти больше половины экспедиции! Клянусь, я позабочусь о том, чтобы рассказ о твоем деянии дошел до Кровавой заставы и до самого экзарха! Благодарю тебя, $N!', 'Ну, как успехи?', NULL, NULL, 'Освобождено ученых экспедиции', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9671, 'Срочная доставка', '', '', 'Ты - $N? Что ж, вовремя! Я уже и не надеялся тебя найти.Загляни в почтовый ящик - там тебя ждет срочное письмо. Мне его передал один человек, адмирал с острова Лазурной Дымки. Как же его звали... Одиссей? Одессит?.. Нет, не помню: из головы вылетело. Но он сказал, что ты его непременно вспомнишь.<Гермесий пожимает плечами.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9672, 'Наследие Проклятой Крови', 'Дорогой друг!$B$BПеро дрожит в моих руках, когда я пишу эти строки. Надеюсь, ты получишь письмо вовремя.$B$BПрошлой ночью в моем шатре появился Эдвард Хейнс, капитан \"Утерянной надежды\". Да-да, тот самый Эдвард Хейнс, который умер от цинги двадцать лет назад.$B$BПризрак поведал мне историю, от которой кровь застыла у меня в жилах. Тебе непременно нужно услышать эту историю – и выполнить одно задание. Прошу тебя, разыщи Эдварда на острове Драконьей Скорби; ты сможешь найти его к северо-востоку от своего лагеря.$B$BС наилучшими пожеланиями,$B$BАдмирал Одиссий.', 'Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним.', 'Скажи, ты, сухопутный червяк, тебе приходилось слышать о проклятии? Ну да, конечно, разумеется, ничего! А между тем именно проклятье и потопило все эти корабли; вернее сказать, это сделал риф Проклятой Крови – мерзейшее место в мире. Я и сам здесь торчу уже двадцать лет, если ты этого не знаешь.$B$BЯкорь мне в глотку!.. Вот тут-то я и помер, стал падалью, которой даже драконы брезгуют... Впрочем, это совсем другая история. Я сейчас не о том. Мы должны помочь тем злосчастным душам, которые попали в ловушку на этом рифе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9673, 'Дрессировка', 'Тебе удалось приручить питомца, но теперь нужно его выдрессировать. Обратись к Хальтенису, лучшему дрессировщику Луносвета.$B$BХальтенис всегда рад моим ученикам. Прояви уважение - и он обязательно поможет тебе. Удачи!', 'Поговорите с Хальтенисом в Луносвете.', 'Что ж, похоже, ты уже не новичок.$B$B*Хальтенис пристально смотрит на вас.*$B$BЯ помогу твоему питомцу освоить новое умение - потрошение врагов. Оно пригодится тебе для служения нашему великому городу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9674, 'Проклятые наги', 'Говорят, когда мир раскололся, эти земли возопили... Именно здесь канули в бездну забвения тысячи ночных эльфов, а вместо них в мир вступили чудовищные твари, порождение ночных кошмаров – наги.$B$BНаги повиновались лишь своей королеве Азшаре; они уничтожали любого, кто решался плыть по их морям. Так было тысячи лет... но теперь, возможно, все переменится.$B$BПервым делом нужно будет истребить проклятых наг на этом рифе.', 'Капитан Эдвард Хейнс с острова Драконьей Скорби просит убить 10 наг с острова Проклятой Крови.', 'Отличное начало – но только начало...', NULL, NULL, NULL, 'Нага с острова Проклятой Крови убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9675, 'Дрессировка', 'Да, и еще одно! Тебе не помешает поговорить с Ганааром из Экзодара. Он научит тебя заботиться о твоем питомце и дрессировать его.$B$BГанаара можно отыскать в юго-западном углу Торгового ряда.', 'Поговорите с Ганааром в Торговом ряду Экзодара.', 'Главное - понять, что умение кормить и спасать своего питомца от смерти - не пустяк, как полагает твой учитель. Ведь дрессировка позволяет питомцу обучиться тому, что ему нипочем не постичь без тебя.$B$BФурболги меня многому научили, поэтому слушай внимательно, и я передам тебе свои знания.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9676, 'Наставник паладинов', 'По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных паладинов на острове Солнечного Скитальца тренирует Джестенис Солнцесвет. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.$B$BДжестенис, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.', 'Поговорите с наставником паладинов Джестенисом Солнцесветом в Солнечном Шпиле на острове Солнечного Скитальца.', 'Вижу, тебя распирает от гордости. Ты уже видишь себя среди Рыцарей крови.$B$BКогда-нибудь ты заслужишь себе место в наших рядах, но сначала тебе придется научиться управлять силой Света, отточить свое боевое мастерство и доказать, что ты достоин стать рыцарем.$B$BГотовься сносить насмешки, боязнь и неприязнь со стороны тех, кого поклянешься защищать. Ибо они не способны понять цену великой силы, что хранит их. Не теряй веры и держи меч наготове, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9677, 'Призыв предводителя рыцарей Доблестной Крови', '$N, ты $gпреуспел:преуспела: в начале своего обучения и $gсумел:сумела: отличиться среди тех, кто жаждет стать рыцарями крови. Ты $gготов:готова: к следующему этапу обучения. Сам предводитель рыцарей Доблестная Кровь желает поговорить с тобой.$B$BНе сомневаюсь, предводитель устроит тебе испытание, чтобы проверить твои способности и уровень обучения. Ты найдешь его в штабе рыцарей крови на площади Странников в Луносвете. Желаю удачи, $N!', 'Поговорите с предводителем рыцарей Доблестной Кровью на площади Странников в Луносвете.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9678, 'Первое испытание', 'Ты прекрасно $gосвоил:освоила: искусство сражения, но этого недостаточно.$B$BСосредоточенность и несгибаемая сила воли – вот что отличает настоящего рыцаря крови от обычного головореза.$B$BХочешь закалить характер? Тогда отправляйся на Остров Напастей, к северо-востоку от Призрачных земель. Там, в одной из пещер, найди жаровню и встань перед ней на колени. Затем разожги в жаровне пламя и не своди глаз с того, что представится твоему взору.', 'Отправляйтесь на остров, описанный предводителем рыцарей Доблестной Кровью, найдите пещеру и разожгите огонь в жаровне. Пройдя первое испытание, возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.', 'Я знаю, о чем ты думаешь.$B$BДа, я действительно послал Безмолвного Клинка, чтобы убить тебя.$B$BНичего личного, $N. Я просто хотел преподать тебе урок. Теперь ты знаешь, что настоящий рыцарь Крови должен всегда быть начеку. Оправдывает ли это смерть Безмолвного Клинка, спросишь ты?$B$BБезусловно, оправдывает. Считай это очередной тренировкой.', NULL, NULL, NULL, 'Пройдите первое испытание', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9680, 'Тайны прошлого', 'Камсис была права! Это очень, очень ценные сведения. $B$BЕсли Медив во время сражения с драконом объединил свою душу с магическими силами, то вполне возможно, что мы сумеем извлечь из останков дракона хотя бы слабый отпечаток сущности Медива. Под слоем пыли на Перевале Мертвого Ветра нас ожидают великие открытия.$B$BСтупай в горы к югу от Каражана, разыщи фрагмент драконьей кости и принеси его мне.', 'Верховный маг Альтур желает, чтобы вы нашли в горах к югу от Каражана на Перевале Мертвого Ветра фрагмент обугленной кости и доставили ему.', 'Великолепно! Этот маленький костяной обломок буквально лучится энергией, я чувствую это!', 'Ну как, удалось отыскать нужный фрагмент кости, $N?', NULL, NULL, 'Фрагмент обугленной кости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9681, 'Источник силы', 'Жестоко? Ну что ты, $N. Безмолвный Клинок прекрасно знал, на что идет, и выполнил свой долг с честью и достоинством. Его самоотверженность должна послужить примером для всех нас.$B$BНо это далеко не последний подвиг Безмолвного Клинка, $N. Ему предстоят еще многие свершения. Да-да, ты не $gослышался:ослышалась: - нам нужно воскресить его. И займешься этим именно ты!$B$BДоселе ты $gограничивался:ограничивалась: простыми заклинаниями, но теперь, когда нас предал Кель\'тас, когда мы утеряли источник энергии, тебе придется научиться нести Свет по-новому. Отправляйся к магистру Асталору Кровавой Клятве.', 'Поговорите с магистром Асталором Кровавой Клятвой в тайной зале, расположенной под штабом рыцарей крови.', 'Добро пожаловать, юный $C!$B$BУзри источник нашей силы!$B$B*Магистр указывает на огромное существо в середине залы.*$B$BЭто прекрасное существо было преподнесено нам в дар самим принцем Кель\'тасом. Оно противится нам, но мы нашли способ использовать его силу и без его согласия.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9682, 'Отчаявшиеся', 'На краю рифа, глубже, чем обитают проклятые наги, находится обитель отчаявшихся – там обитают проклятые путешественники, неупокоенные призраки тех, кого унесло проклятие...$B$BМне горько, что приходится просить тебя об этом, но... Их должно уничтожить.$B$BОтлученные души должны обрести покой. Вернись ко мне, когда исполнишь все, как нужно, – я дам тебе еще одно, последнее задание.', 'Капитан Эдвард Хейнс с острова Драконьей Скорби просит освободить 4 души с острова Проклятой Крови.', 'Ты оказал отчаявшимся неоценимую услугу, $N. Осталось сделать только одно: уничтожить предводителя наг с острова Проклятой Крови.', 'Не стоит оплакивать их гибель, $N, по сути, они уже давно мертвы...', NULL, NULL, 'Душа с острова Проклятой Крови', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9683, 'Избавление от Проклятой Крови', 'К югу отсюда находится остров Проклятой Крови. В центре острова расположено святилище, посвященное возлюбленной королеве наг – Азшаре. Разрушь статую! Уничтожь это чучело! Не сомневаюсь: это разъярит предводителя наг, Атофа.$B$BУбей Атофа, а потом возвращайся ко мне.', 'Капитан Эдвард Хейнс с острова Драконьей Скорби просит уничтожить статую королевы Азшары и убить Атофа Проклятую Кровь.', 'Подумать только! Тебе это удалось!.. Благодарение сотен и сотен душ пребудет с тобой.$B$BПозволь кое-что предложить тебе...', 'Нужно выманить Атофа из его логова!', NULL, NULL, 'Атоф Проклятая Кровь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9684, 'Получение силы Света', 'Прими этот зачарованный сосуд, $N, и наполни его магической силой, окружающей магистров, до краев. Когда-то эти магистры охраняли плененного наару, и часть его энергии еще находится в них. Этого сосуда хватит, чтобы вернуть к жизни падшего рыцаря.$B$BНе беспокойся о магистрах, за ними присмотрят. Лорд Соланар сообщил мне, что Леди Лиадрин занимается поиском нового источника магической силы.', 'Используйте мерцающий сосуд на эльфах крови-магистрах, чтобы наполнить его магической силой, и возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.', 'Прекрасно, $N. Каким бы могущественным не был М\'ууру, он не способен противостоять воле рыцарей крови.$B$BТеперь для тебя открыт новый путь. Мало кто решается вступить на него, но я уверен, что ты справишься и станешь новой гордостью ордена.', 'Тебе удалось поговорить с магистром Асталором Кровавой Клятвой?', NULL, NULL, 'Наполненный мерцающий сосуд', 'Мерцающий сосуд', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9685, 'Воскрешение', 'Пока ты $gнаполнял:наполняла: сосуд, отряд посвященных принес тело Сангриаса Безмолвного Клинка. Отправляйся на верхний этаж таверны Луносвета и воскреси Сангриаса с помощью магической силы, заключенной в сосуде.$B$BПоторопись, $N. Если не успеешь вовремя, даже все могущество Света не сможет вернуть его к жизни. Возвращайся ко мне, когда закончишь.', 'Отправляйтесь в таверну Луносвета и воскресите Сангриаса Безмолвного Клинка с помощью силы, заключенной в наполненном мерцающем сосуде.', 'Рад снова видеть тебя, юный рыцарь. Ты узрел источник нашей силы и смог подчинить его себе. Теперь я научу тебя воскрешению падших непосредственно в бою.$B$BПродолжай служить ордену и оттачивай мастерство, и тебе откроются новые грани силы.', NULL, NULL, NULL, 'Сангриас Безмолвный воскрешен', 'Наполненный мерцающий сосуд', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9686, 'Второе испытание', 'От титула адепта тебя отделяет лишь одно испытание, $N.$B$BОно совсем не похоже на предыдущее – в этот раз все четко и понятно: брось вызов четырем лучшим рыцарям крови и победи их в честном бою.$B$BКогда будешь $gготов:готова: начать, прикоснись к кристаллу, что появится посередине павильона. После этого просто дождись начала испытания.$B$BНачнем?', 'Пройдите второе испытание, победив воителя Ярокрова, воителя Светореза, воительницу Быстромеч и воителя Солнцесвета в павильоне у наставника Келерана Алого Взмаха.', 'Превосходно, $N! Ты доказал, что достоен носить почетный титул адепта и стать настоящим рыцарем Крови. Правда, перед посвещением тебе придется выполнить еще пару поручений.', 'Рыцарь Крови скорее погибнет, чем сдастся. Не забывай об этом, $N.', NULL, NULL, 'Пройдите второе испытание.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9687, 'Святотатство', 'Не так давно на берегах этого острова стали появляться совухи. Они приходили поодиночке и с единственной целью: похитить кости павших драконов. Не знаю, что произошло с этими существами – прежде совухам никогда не приходило в голову тревожить прах ушедших; но ныне души драконов лишились покоя, не в силах вынести святотатства.$B$BЕсли ты отправишься на запад и минуешь Кровавый берег, то доберешься до гряды Яростного Пера. Там, в поселениях совухов, можно отыскать похищенные кости драконов...', 'Принц Торет с острова Драконьей Скорби просит отыскать 8 костей драконов.', 'Ритуал?.. Совухи тысячи лет жили в гармонии с природой и этой землей. Это безумие какое-то!..$B$BКак жаль...', 'Давно минули времена войн драконов. Все, что осталось, – древние кости и немногие живые из выводка Изеры...', NULL, NULL, 'Кость дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9688, 'Дорога в Сон', 'То, что ты видишь, – это беспокойные духи зеленых драконов. Подобно мне, они привязаны к этой земле и не могут достичь места своего упокоения в Изумрудном Сне.$B$BТо, что тебе удалось вернуть кости погибших, немного успокоило их, однако еще рано останавливаться на достигнутом...$B$BНеобходимо уничтожить астральные тела этих заблудших драконов и освободить их души. Пока это не будет совершено, я не сумею покинуть остров!', 'Принц Торет с острова Драконьей Скорби просит убить 5 темно-зеленых дракончиков и 5 детенышей зеленого дракона.', 'Каким бы отвратительным ни было это деяние, его нужно было совершить. И теперь тебе предстоит взглянуть в лицо истинному злу.', NULL, NULL, NULL, 'Темно-зеленый дракончик убито', 'Детеныш зеленого дракона убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9689, 'Острозуб', 'В битвах погибли многие черные драконы; но дух одного из них, военачальника Смертокрыла, все еще скитается в этих краях. Взгляни на небо – и ты увидишь, как его астральный образ кружит над тобой. Его ненависть так велика, что даже смерть не смогла притушить это пламя.$B$BОтнеси собранные тобой кости драконов на вершину горы и положи в неугасающий погребальный костер. Для Острозуба это будет знаком спуститься. Когда это произойдет, уничтожь его.', 'Принц Торет с острова Драконьей Скорби просит убить Острозуба.', 'Сколько же времени прошло? Тысяча лет? Или, может, десять тысяч?.. Ты даже представить себе не можешь, $N, какая это огромная услуга для меня и моего народа. Прошу тебя, прими этот волшебный предмет из Лорет\'Арана в знак моей вечной благодарности.', NULL, NULL, NULL, 'Острозуб убито', 'Связка драконьих костей', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9690, 'Второе испытание', 'Что ж, $gюный:юная: $N. Ты $gузнал:узнала: истинную природу нашего могущества и $gприложил:приложила: немало усилий, чтобы овладеть им и стать настоящим рыцарем крови.$B$BПришло время второго испытания. Выдержишь его – и я наделю тебя титулом адепта. Отправляйся к наставнику Келерану Алому Взмаху. Чтобы найти его, держи свой путь на север, через руины Луносвета, а затем сверни на восток прямо перед мостом к острову Солнечного Скитальца.', 'Поговорите с наставником Келераном Алым Взмахом.', 'Подготовься как следует. Когда почувствуешь в себе силы, возвращайся ко мне, и я поведаю тебе о предстоящем испытании.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9691, 'Возвращение в Луносвет', 'Возвращайся в Луносвет и встреться с предводителем рыцарей Доблестной Кровью. Не беспокойся: твой визит будет лучшим доказательством того, что испытание успешно пройдено.$B$BПредводитель сам расскажет тебе, что осталось совершить для получения титула адепта. Тебе есть чем гордиться, $N. Поверь, немногим удается пройти это испытание и остаться в живых.', 'Возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.', 'Я знал, что в тебе есть силы пройти испытание, $N. Теперь до получения титула остались простые формальности - правда, не менее опасные, чем поединки с лучшими рыцарями ордена. Слушай внимательно, я расскажу тебе, что нужно сделать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9692, 'Путь адепта', 'Прежде вступить в орден, каждый кандидат должен собрать все необходимые компоненты для ковки особого оружия рыцарей крови – закаленного кровью протазана.$B$BКроме того, каждый рыцарь должен носить особый знак отличия. Выковать знак нельзя – его можно только получить от ветерана ордена. Знак, который будешь носить ты, принадлежал бесстрашному рыцарю, павшему при осаде Смертхольма. Но сначала тебе нужно найти его.$B$BЯ подготовил несколько записок, которые помогут тебе в поисках.', 'Принесите оскверненный самоцвет Кора, ящик со слитками, закаленными в крови, нужное количество крови разгневанных и знак отличия рыцаря крови предводителю рыцарей Доблестной Крови в Луносвет.', 'Прекрасно, $N. Все готово. Осталось лишь выковать оружие.', 'Ты принес все необходимое?', NULL, NULL, 'Оскверненный самоцвет Кора', 'Ящик с закаленными в крови слитками', 'Кровь разгневанных', 'Знак отличия Кровавого Рыцаря');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9693, 'Что для тебя Аргус?..', 'Скажи, что для тебя значит Аргус? А, $N?.. Многие дренеи не знают или не помнят нашей родной планеты. Именно там мы отделились от ман\'ари - демонических сущностей, искаженных отражений нас самих, получивших \"дар\" от Саргераса. От тех, кто именует себя \"эредар\".$B$BЭредар... когда-то у этого слова был смысл...$B$B*Адметиус словно бы пробует слово на вкус.*$B$BОтвратительно.$B$BНу, довольно попусту тратить время. Найди воздаятеля Бороса - у него тебе предстоит начать свое обучение.', 'Экзархх Адметиус с Кровавой заставы просит поговорить с воздаятелем Боросом.', 'Ах, $N... Да, я слышал о тебе. Говорят, тебе удалось дугу Кессела за 15 минут проскочить? Хотя мне как-то не очень верится.$B$BТы готов жить и умереть во имя Света? Во имя Велена? Во имя Аргуса?..$B$B<Борос смеется.>$B$BЛадно, ладно, что-то я увлекся.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9694, 'Кровавая застава', 'Кровавая застава – одна из двух застав, которыми управляет Длань Аргуса. Вторая – Лазурная застава, где тебе уже довелось побывать. Так вот, запомни: на острове Кровавой Дымки все не так, как на острове Лазурной Дымки. Когда мы прибыли сюда, эта земля была не менее прекрасной, чем земли острова Лазурной Дымки; мы даже назвали ее островом Серебряных Ветров... Но ныне эта земля отравлена; к тому же эльфы крови, с которыми мы сражались на \"Экзодаре\", выжили и стали появляться здесь. Собственно, с этим-то и связано задание, которое я хочу тебе дать. Отправляйся на северо-запад, в лес Клинков. Если тебе встретятся эльфы крови – убивай их без колебаний.', 'Убейте 10 шпионов Солнечных Ястребов и сообщите об этом на Кровавую заставу воздаятелю Боросу.', 'О, ты вернулся! Поверить не могу - цел и невредим!$B$BА у меня для тебя есть хорошие новости, $N. Обнаружено еще одно место крушения. Как только я покончу с этими делами, непременно вызову тебя.', NULL, NULL, NULL, 'Шпион из клана Солнечного Ястреба убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9696, 'Переводы...', 'Наша старшая дознавательница Элизия свободно говорит на талассийском. Отнеси ей этот документ, посмотрим, что она скажет.', 'Доставьте послание Солнечных Ястребов дознавательнице Элизии на Кровавую заставу.', '<Элизия читает документ.>$B$BЕсли то, что здесь написано, – правда, значит, эльфы крови открыли портал в Запределье. Да, это объясняет, почему их становится все больше и больше...', 'Агент $N, вы отрываете меня от работы. Надеюсь, у вас действительно важное дело...', NULL, NULL, 'Послание Солнечных Ястребов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9697, 'Наблюдательница Лиса\'о', 'Экология местных существ, в особенности спорлингов и болотников, требует серьезного исследования. Казалось бы, что в этом такого? Но, занявшись полевыми исследованиями, ты обнаружишь, что дело это опасное и требует мужества и находчивости.$B$BОтыщи наблюдательницу Лиса\'о у кенарийского караульного поста на юго-западе болот. Ступай по дороге на запад, и рано или поздно придешь туда. Она, правда, чересчур погружена в свои научные исследования, но не обращай на это внимания.$B$BДа, и еще: осторожнее с ее кошкой!', 'Поговорите с наблюдательницей Лиса\'о у кенарийского караульного поста в Зангартопи.', 'О, замечательно! Наконец-то хоть какая-то помощь! У меня так много дел, а я вынуждена сидеть здесь, чтобы организовывать работу.$B$BНадеюсь, ты не боишься грязной работы?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9698, 'Аудиенция у Пророка', 'Послушай, $N, мне нужно, чтобы ты лично $gдоставил:доставила: переведенные документы Велену. Этому ненормальному посланнику я не доверяю.$B$BОбъясни пророку, что эльфы крови получают подкрепление из Запределья и что среди дренеев в Экзодаре у них есть шпион. Ты сможешь найти Велена в Чертоге Света Экзодара.$B$BСпеши!', 'Доставьте переведенное послание Солнечных Ястребов Пророку Велену в Экзодар.', '<Велен читает документ.>$B$BЛюбопытно... Это действительно многое объясняет...', '*Велен улыбается.*$B$BПриветствую, $N. Я ждал тебя.', NULL, NULL, 'Переведенное послание Солнечных Ястребов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9699, 'Правда или вымысел', 'Благодарю, $N, ты $gуспел:успела: как раз вовремя. Похоже, ты - один из лучших агентов Длани Аргуса.$B$BЕсли бы мы еще знали, с кем на острове Кровавой Дымки они поддерживают связь и где находится Солнечный портал... Где бы ни был этот портал, похоже, его надежно охраняют.$B$BНе хочешь ли заняться его поисками?$B$BЕсли ты не против, доставь эти распоряжения воздаятелю Боросу. Он расскажет тебе, что делать.', 'Доставьте распоряжения Велена воздаятелю Боросу на Кровавую заставу.', 'План неплох – но и опасен. Но, я уверен, ты справишься.', 'Ну что?', NULL, NULL, 'Распоряжения Велена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9700, 'Магия против Тьмы', 'Велен говорит, что если эльфы крови попытались создать переход между этими островами и Запредельем, то в местах открытия порталов непременно объявятся аномалии: это неизбежный побочный эффект. Тебе нужно обыскать остров и обнаружить места скопления подобных аномалий.$B$BПомни, $N: некоторые из этих существ – выходцы из Бездны. Если они встретятся тебе, убивай их без колебаний! Если тебе удастся выяснить что-то новое, сообщи об этом мне. Поиски лучше начать с севера, от сверхускорителя.', 'Воздаятель Борос с Кровавой заставы просит найти солнечный портал и убить 5 аномалий Бездны.', 'И сколько этих тварей у сверхускорителя?.. Сколько же раз они открывали этот проклятый солнечный портал?! Скверно, очень скверно...$B$BУвы, $N, я научил тебя всему, чему мог. Когда придет время, Курос позовет тебя...', NULL, NULL, NULL, 'Аномалия Бездны убито', 'Исследовать локацию', 'Местонахождение Солнечного портала установлено', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9701, 'Наблюдение за спорлингами', 'Нам следует как можно больше узнать о спорлингах из Спореггара и их взаимоотношениях с окружающим миром. Один из способов это сделать – это незаметно наблюдать за спорлингами, как делаю это я.$B$BА тебя я попрошу сходить на Грибную поляну к западу отсюда. Исследуй весь тот район, вернись и расскажи мне, что тебе удалось узнать.', 'Исследуйте Грибную поляну в Зангартопи, затем вернитесь к наблюдательнице Лиса\'о к кенарийскому караульному посту в Зангартопи и расскажите об увиденном.', 'Что?! Болотники с гряды Квагг пожирают отпрысков спорлингов?! Это ужасно!', NULL, NULL, NULL, 'Исследовать локацию', 'Исследуйте Грибную поляну', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9702, 'Вопросы питания', 'Я все не могу понять, зачем болотники переходят через дорогу на Грибную поляну. Должно быть, они голодают? В любом случае, так дело не пойдет!$B$BЯ имею в виду, что в обычных условиях не стала бы вмешиваться, но если они и дальше будут пожирать отпрысков спорлингов, спорлинги окажутся истреблены!$B$BВот как мы поступим: я останусь здесь, а ты отправляйся к гряде Квагг на востоке и попытайся выяснить, почему болотники вторгаются на территорию спорлингов.', 'Соберите 10 образцов выброшенного корма и вернитесь к наблюдательнице Лиса\'о на кенарийский караульный пост в Зангартопи.', 'Вот это и есть твои находки? Странно. Эти объедки грибов выглядят необычно, и в то же время как-то знакомо…$B$BПодожди минутку, мне необходимо подумать. Смотри, никуда не уходи!', 'Смотри, $C, материал для исследований нужно собирать очень тщательно! Мы как бы складываем большую головоломку. И одна-единственная ошибка с твоей стороны может привести нас к ложным выводам.$B$BА нам необходимо разобраться в экологии Зангартопи!', NULL, NULL, 'Выброшенный корм', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9703, 'Криогенный блок', 'У нас есть кому заняться поиском порталов, $N. Для тебя есть другая, не менее важная задача.$B$BБоросу недавно доложили об обнаружении нового места падения обломков \"Экзодара\". Кроме того, нам удалось выяснить, что этот обломок фактически является криогенным блоком \"Экзодара\". Там находятся капсулы – точно такие же, как те, из которых некогда вышли дренеи в долине Аммен.$B$BКроме того, там находятся медицинские припасы. Отправляйся на запад от Кровавой заставы – именно там находится криогенный блок. Постарайся найти припасы – и выживших, если, конечно, они там есть.', 'Воздаятель Курос хочет, чтобы вы доставили на Кровавую заставу 12 коробок с медицинскими припасами.', 'Только эльфы крови? И ни одного выжившего?.. Скверно, скверно... Мне нужно время, чтобы обдумать это, $N. А пока, возможно, у Эсома или Бороса найдется для тебя какое-нибудь дело.', 'Ну что, сведения были точны?', NULL, NULL, 'Медикаменты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9704, 'Смерть от рук Презренных', 'Нелегко быть курьером и поддерживать связь между островом Солнечного Скитальца и площадью Соколиных Крыльев. Жесткие сроки, работа допоздна и, что хуже всего – Презренные!$B$BДорога на юг проходит через руины Луносвета... они кишат Презренными, которые готовы прикончить любого за пару кристаллов маны. Боюсь, эта печальная участь и постигла курьера, с которым мы сегодня отправили одну из посылок Эроны.$B$BВижу, тебе не терпится показать себя. Ступай на Рассветную улицу и попробуй найти какие-нибудь следы пропавшего курьера.', 'Отправляйтесь на юг, в руины Луносвета, и отыщите убитого курьера на Рассветной улице.', 'С тела курьера похищено все, кроме одной посылки. Судя по описанию Аларион, это и есть посылка Эроны.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9705, 'Возвращение посылки', 'Вы берете посылку и удостоверяетесь, что она и правда от магистра Эроны. Аларион, наверное, хотела бы, чтобы вы вернули ее.', 'Вернитесь к курьеру Аларион с посылкой Эроны.', 'Во имя Солнечного Колодца! Это третий курьер, которого мы потеряли за последний месяц!$B$BЯ ценю твою отвагу – не каждый осмелится сунуться на Рассветную улицу. Стражам нужно лучше следить за этими злосчастными Презренными.', 'Что тебе удалось найти, $N?', NULL, NULL, 'Сверток Эроны (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9706, 'Дневник Галена: судьба воздаятеля Саруана', 'Когда вы поднимаете эту книжку, ваши руки дрожат. Курос непременно должен узнать об этой трагедии. Отдайте книжку ему.', 'Доберитесь до Кровавой заставы и отдайте дневник Галена воздаятелю Куросу.', '<Читая дневник, Курос бледнеет; по его лицу катятся слезы.>$B$BСаруан был моим господином... моим учителем... наставником... Я лишь недавно занял его место в Триумвирате – и только после того, как мы уверились, что самого Саруана не отыщем.$B$B<Лицо Куроса искажается от гнева.>$B$BАх, вот как?.. Матис!', 'Что это у тебя, $N? Дневник?', NULL, NULL, 'Записи Галена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9707, 'Ковка оружия', 'Что ж, ты $gдоказал:доказала:, что $gдостоен:достойна: стать рыцарем нашего ордена. Для меня большая честь даровать тебе титул адепта, $N. Сам принц Кель\'тас гордился бы тобой.$B$BТы будешь опорой для тех, кто сражается рядом с тобой, и примером для тех, кто стремится присоединиться к нам. Не щади врагов и не показывай свою слабость, защищай свой народ и стань истинным владыкой Света.$B$BА теперь пришло время выковать оружие, положенное тебе с новым титулом.', 'Принесите ящик с материалами Бемаррину в Луносвет.', 'Теперь у меня есть все, что нужно. Приступим!', 'Поздравляю, $N. Заслужить титул адепта может далеко не каждый. Уж поверь моим словам - я видел много страждущих, и лишь единицам удавалось довести дело до конца.', NULL, NULL, 'Ящик с материалами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9708, 'Знакомые грибы', 'Да-да, я же знала, что уже встречала этот тип грибов в другом районе болот!$B$BУ меня есть гипотеза... К северу отсюда есть место, которое называют Болотными вырубками. Мне лично это название кажется странным, но, с другой стороны, я же там не бывала... Так вот, мне нужны образцы тамошних грибов, чтобы проверить мои соображения.$B$BТолько смотри, $C, будь $gосторожен:осторожна:c:! Я слышала, что в тех краях появились огры. Возможно, тебе придется отбирать образцы у них. Может быть, это из-за огров болотники больше не решаются добывать там пищу?', 'Соберите 15 образцов грибов и принесите их наблюдательнице Лиса\'о на караульный пост Кенария в Зангартопи.', 'Да, все сходится... Присутствие огров и то, чем они занимаются, объясняет все. Да уж, теперь понятно, отчего та местность называется Болотными вырубками!$B$BНужно как-то исправить положение, но как? Не можем же мы просто истребить этих огров! В конце концов, они точно так же имеют право на жизнь, как и любые другие жители болот!', 'Ну что, образцы у тебя?', NULL, NULL, 'Образец грибов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9709, 'Ворованные грибы', '$C, у меня есть идея! Возвращайся на север и проберись на территорию огров.$B$BК северо-западу от Болотных вырубок есть место, которое называется крепость Анго\'рош. Крепость находится на парящем острове, куда ведет мост из большого гриба.$B$BДолжно быть, огры хранят собранные грибы именно там. Могу поручиться, они там есть повсюду, и уж тем более у самих огров!$B$BПринеси мне побольше этих грибов, и я попытаюсь предложить болотникам новый источник пищи.', 'Соберите 10 ящиков грибов и вернитесь с ними к наблюдательнице Лиса\'о на караульный пост Кенария в Зангартопи.', 'Великолепно! Ох, $C, спасибо тебе!$B$BТы действовал так осторожно, не нарушая естественный порядок вещей, и при этом за короткий период времени нам удалось собрать столько сведений!$B$BА теперь давай взглянем, сработал ли наш план по выращиванию новых запасов пищи для болотников...', 'Ну что, достаточно ли у нас грибов, чтобы устроить новый сад для болотников?', NULL, NULL, 'Ящик грибов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9710, 'Закаленный кровью протазан', 'Все готово, $N. Скоро ты получишь свое новое оружие.', 'Дождитесь, пока Бемаррин смастерит оружие.', 'Вот твое оружие, $N. Да поможет оно в твоей праведной службе ордену и Луносвету.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9711, 'Матис Жестокий', 'Матис должен предстать перед судом, $N; надеюсь, с твоей помощью он будет обнаружен и предстанет перед Триумвиратом.$B$BОбыщи остров и найди этого ублюдка. Вот тебе сигнальное ружье – выстрелишь, когда разыщешь Матиса, и мои следопыты помогут тебе задержать его. Потом возвращайся ко мне.', 'Воздаятель Курос с Кровавой заставы требует, чтобы Матис Жестокий был пойман.', 'Триумвират решил немедленно предать Матиса суду. Благородный $С, сегодня благодаря тебе мы обезвредили величайшего преступника.$B$BДва задания из трех исполнены безукоризненно; посмотрим, что поручит тебе Эсом.', NULL, NULL, NULL, 'Поймайте Матиса Жестокого.', 'Сигнальное ружье', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9712, 'Талассийский боевой конь', 'Тебе удалось добиться поистине впечатляющих успехов, $N. Магистр Асталор и его поверенные позволили тебе прикоснуться к силе Света - и ты $gсумел:сумела: обратить ее себе во благо. Пришло время получить новые знания.$B$BСила Света дарует способность вызывать талассийского тяжеловоза, который станет твоим верным скакуном.$B$BПродолжай служить ордену, $N. Тебя ждут еще большие свершения.', 'Поговорите с предводителем рыцарей Доблестной Кровью, чтобы научиться вызывать талассийского боевого коня.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9714, 'Принеси мне еще одну клумбу!', '', '', 'Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?', NULL, NULL, NULL, 'Кровавый гибискус', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9715, 'Принеси мне клумбу!', 'Нам необходимо пополнить наши запасы кровавого гибискуса. Мы его используем в самых разнообразных целях. Раньше этого гибискуса было много повсюду, но теперь, когда болота пересыхают, он водится только в Нижетопи в резервуаре Кривого Клыка, что под Змеиным озером.$B$BГоворят, что для тамошних шаркунов, болотоходов и подболотных скатов он – лучшее лакомство. Так что, если хочешь нам помочь, добудь у них эти цветы.', 'Добудьте 5 растений кровавого гибискуса и отнесите их Гзхун\'тту в Спореггар в Зангартопи.', 'Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?', 'Ну что, удалось тебе добыть гибискус, как я просил?', NULL, NULL, 'Кровавый гибискус', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9716, 'Неприятности на озере Тенетопь', 'Мы явились в Запределье, рассчитывая найти здесь крохотные островки сохранившейся жизни. Но в Зангартопи мы обнаружили обширную, процветающую экосистему!$B$BОднако наши первые радужные впечатления оказались обманчивыми. Уровень воды в озерах и болотах непрерывно понижается все то время, что мы делаем замеры!$B$BДля местных животных и растений это может обернуться катастрофой. Отправляйся на озеро Тенетопь к юго-западу отсюда и попробуй отыскать причину убывания воды.', 'Выясните причину убывания воды в озере Тенетопь. Затем вернитесь к Исиэль Песни Ветра в Кенарийский приют в Зангартопи.', 'За этим стоят наги! Но зачем им это? Судя по тому, что ты описываешь, этот паровой насос может быть причиной того, почему уровень воды в болоте падает!$B$BЭто объясняет то, отчего они относятся к нам столь враждебно... Что ж, не будем тратить времени. Я попрошу тебя выполнить для нас еще одно задание.', 'Ну что, $N, удалось что-нибудь выяснить?', NULL, NULL, 'Исследовать локацию', 'Исследуйте озеро Тенетопь.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9717, 'Удачный ход', 'Мы – народ мирный, но вести войну со споровыми великанами мы просто вынуждены, нравится нам это, или нет. А у нас есть поговорка, что, когда речь идет о грибах и о войне, все средства хороши!$B$BОдин из предводителей споровых великанов, Болотоглад, уже в течение нескольких тысяч лет бережно взращивает особое растение, известное как подспорник. Если с этим растением что-то случится, дух Болотоглада, несомненно, будет сломлен!$B$BОтправляйся в Нижетопь, что в резервуаре Кривого Клыка, и укради у него это растение! Поверь мне, на это он внимание обратит непременно!', 'Добудьте ветку подспорника и вернитесь с ней к Т\'шу в Спореггар в Зангартопи.', '<Спорлинг издает звук, отдаленно напоминающий хмыканье.>$B$BВеликолепно! Несомненно, боевой дух споровых великанов упадет ниже дна болота, как только они поймут, что тебе удалось совершить.$B$BПравда, возможно, они так разгневаются, что нападут на нас снова...$B$B<Т\'шу делает такое движение, как будто пожимает плечами.:', 'Нижетопь - очень опасное место! Я, конечно, не сочту тебя трусом, если ты не рискнешь отправиться туда. Однако, если уж ты возьмешься за дело, стыдно тебе будет вернуться с пустыми руками.', NULL, NULL, 'Ветка подспорника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9718, 'С высоты птичьего полета', 'Нужно определить, сколько озер затронула деятельность наг, и затем уже действовать.$B$BРазумеется, обследовать каждый водоем в Зангартопи – дело долгое. С помощью магии я могу изменить твой облик, приспособив его для этой разведки.$B$BКогда будешь $gготов:готова:, подойди ко мне и используй этот амулет. А когда дело будет окончено, я помогу тебе благополучно вернуться обратно.', 'Используйте амулет буревестника, чтобы исследовать основные озера Зангартопи по просьбе Исиэли Песни Ветра.', 'Все как я подозревала! Наги установили насосы на всех крупных озерах Зангартопи!$B$BИх необходимо остановить, если мы хотим спасти болота...', 'Привет тебе, $N!', NULL, NULL, 'Амулет буревестника (Прилагается)', 'Исследуйте основные озера Зангартопи.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9719, 'Охота на Охотницу', 'Испокон веков наибольшую угрозу для моего народа представляли болотоходы. Теперь, когда нам угрожают еще и споровые великаны, мы не можем допустить, чтобы на нас нападали наши старинные враги!$B$B$C, отваги тебе не занимать, ты $gдоказал:доказала: это. Как ты думаешь, ты сумеешь пробраться в Нижетопь, что в резервуаре Кривого Клыка, и уничтожить великую мать болотоходов, Черную Охотницу?$B$BА в доказательство принеси мне ее мозг!', 'Принесите мозг Черной Охотницы Кхн\'иксу в Спореггар в Зангартопи.', 'Черная Охотница мертва! Нехорошо радоваться убийству, но эта великая мать и все ее племя на протяжении веков причиняли моему народу неисчислимые страдания.$B$BУвы, теперь одна из ее потомков преобразуется и займет ее место, однако это все же займет какое-то время, и мы сможет перевести дух. В течение некоторого времени болотоходы перестанут нас тревожить...', 'Ты вернулся. Означает ли это, что Черной Охотницы больше нет?', NULL, NULL, 'Мозг Черной Охотницы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9720, 'Необходимо поддерживать равновесие!', 'Я представления не имею, для чего нагам понадобилось осушать свои собственные озера. Но знаю одно: их необходимо остановить!$B$BЭти семена несут в себе гнев самой земли. Отнеси их к паровым насосам, установленным нагами, и осыпь ими все эти рычаги и приводы.$B$BИз семян прорастут лозы толщиной в руку и прочные, как сталь. Ступай, $N. Восстанови природное равновесие, нарушенное нагами!', 'Осыпьте семенами железной лозы пульты управления паровым насосом в Змеином озере, озере Тенетопь, озере Болотных Огоньков и в Лагуне. Затем вернитесь к Исиэль Песни Ветра в Кенарийский приют в Зангартопи и отдайте ей оставшиеся семена.', 'Стало быть, дело сделано. Теперь болото спасено.$B$BОднако не стоит обольщаться – наверняка нам еще не раз придется столкнуться с нагами. Здесь, в Запределье, мы не должны терять бдительности ни на секунду.', 'Дело сделано, $C?', NULL, NULL, 'Выведите из строя пульт в озере Тенетопь', 'Выведите из строя пульт на озере Болотных Огоньков', 'Выведите из строя пульт в Змеином озере', 'Выведите из строя пульт в Лагуне');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9721, 'Призыв леди Лиадрин', 'Твоя преданность ордену не осталась незамеченной: Лорд Соланар Кровогнев, правая рука самой Леди Лиадрин, пожелал встретиться с тобой.$B$BТакой чести удостаиваются немногие, $N. Обычно новыми кандидатами занимаюсь я, но Лорд Соланар считает, что ты - $gособенный:особенная:. Не упусти свой шанс, $N!', 'Поговорите с Лордом Соланаром в Луносвете.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9722, 'Путь мастера', 'В нашем ордене есть круг посвященных, в который входят только самые преданные, опытные и умелые рыцари. Отличить их можно по особой породе скакунов - талассийским скакунам.$B$BКаждый кандидат на титул мастера должен доказать свою верность идеалам ордена и заручиться поддержкой одного из посвященных.$B$BЕсли ты действительно желаешь стать мастером - я лично буду твоим покровителем.', 'Поговорите с Лордом Соланаром еще раз и примите предложение о покровительстве.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9723, 'Жест преданности', 'Истинная преданность ордену доказывается не мечом, $N. Настоящий рыцарь должен быть готов выполнить любые поручения - какими бы мелкими и незначительными они не казались.$B$BИ сейчас тебе предстоит выполнить одно из таких поручений. Я дам тебе список предметов, которые необходимы поверенным магистра Асталора Кровавой Клятвы для поддержания энергии Света. Найди их и вернись ко мне.', 'Принесите лорду Соланару в Луносвет 40 отрезов рунической ткани, 6 арканитовых слитков, 10 солнечников, 5 темных рун и 150 золотых.', '', NULL, NULL, NULL, 'Руническая ткань', 'Арканитовый слиток', 'Солнечник', 'Темная руна');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9724, 'Предупреждение Кругу Кенария', 'Кенарийская экспедиция теперь сделалась крупной, практически самостоятельной организацией. Однако эти события достаточно важны, чтобы предупредить о них Круг Кенария.$B$BНе тревожься, тебе не придется возвращаться обратно на Лунную поляну. Посланцы Круга Кенария есть неподалеку отсюда, на полуострове Адского Пламени.', 'Поговорите с Амитиэль Странницей Туманов на Заставе Кенария на полуострове Адского Пламени.', 'Принесенные тобой новости о деятельности наг в Зангартопи воистину ужасны! Исиэль поступила разумно, что сообщила об этом нам. Она не забывает, что экспедиции не выжить без поддержки Круга...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9725, 'Доказательство лояльности', 'Защита земель Кель\'Таласа – священный долг рыцарей крови, $N. Только благодаря нам и нашим союзникам жители Луносвета могут спать спокойно. Пришло время тебе разделить с нами эту обязанность.$B$BМне сообщили, что на северо-восточной границе, на окраине Восточных Чумных земель замечены воины Плети. Инженеры готовят свои машины к нападению на Призрачные земли. Их надо остановить!', 'Лорд Соланар Кровогнев из Луносвета просит уничтожить 3 мясных фургона и убить 15 инженеров Плети.', '', NULL, NULL, NULL, 'Инженер Плети убито', 'Уничтожьте мясные фургоны Плети', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9726, 'Теперь, когда мы друзья...', 'Наги из анклава Кровавой Чешуи, что к северо-востоку отсюда, начали истреблять наш народ! $C, их необходимо остановить!$B$BНаучи их уму-разуму в доказательство нашей дружбы...', 'Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун\'тту в Спореггар в Зангартопи.', '*Гзхун\'тт кивает вам.*$B$BМы рады тому, что ты действительно надежный друг, $N! Быть может, теперь, когда у нас есть такой союзник, как ты, поганые наги подумают дважды, прежде чем нападать на нас!', 'Ты еще не побывал в гостях у наг?', NULL, NULL, 'Надсмотрщик за рабами из клана Кровавой Чешуи убито', 'Чародейка из клана Кровавой Чешуи убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9727, 'Раз уж мы по-прежнему друзья...', 'Поступили сведения, что наги из анклава Кровавой Чешуи на северо-востоке продолжают истреблять наш народ! А мы было решили, что тебе, $C, удалось с ними покончить!$B$BБыть может, ты поучишь их уму-разуму, в доказательство того, что наша дружба по-прежнему прочна?', 'Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун\'тту в Спореггар в Зангартопи.', '*Гзхун\'тт кивает вам.*$B$BМы рады тому, что ты продолжаешь оставаться нашим надежным другом, $N! Уж наверное, теперь, когда ты уже не раз дал им понять, как опасно связываться с нами, эти бессмысленные нападения на наших сородичей прекратятся?', NULL, NULL, NULL, 'Надсмотрщик за рабами из клана Кровавой Чешуи убито', 'Чародейка из клана Кровавой Чешуи убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9728, 'Теплый прием', 'Друиды из экспедиции занимаются тем, что изучают растения и исследуют озера, ну, а мое дело – разбираться с враждебными существами.$B$BС тех самых пор, как мы появились в Зангартопи, наги то и дело нападают на нас без вызова и предупреждения. Мы делаем все, что можем, чтобы противостоять им, но наши возможности ограничены.$B$BЯ бы попросил тебя побывать в нескольких крепостях наг в Зангартопи и показать этим тварям, что с нами лучше не связываться. А в доказательство твоих подвигов принеси мне их когти!', 'Принесите стражу Хамуту из Кенарийского приюта 30 когтей наг.', 'Молодец, $N! И если вдруг тебя терзают угрызения совести - избавься от них. Здешние наги - гнусные твари, еще хуже азеротских.', 'Рад видеть тебя снова, $N. Как продвигается охота на наг?', NULL, NULL, 'Когти наги', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9729, 'Фхвур крушить!', 'Мелкие наги злить Фхвура! Спорлинг - добрый друг Фхвура, Фхвур забрать ковчег наг!$B$BИдем в ближнюю деревню наг. Ты помогать? Веди друзей!', 'Проводите Фхвура к паровому насосу на озере Болотных Огоньков, чтобы добыть ковчег Ссслита. Потом доставьте обратно Фхвура и ковчег в целости и сохранности, и вернитесь к Гзхун\'тту в Спореггар в Зангартопи.', 'Фхвур – хороший великан. Мы когда-то спасли его от наг, и теперь он живет с нами и помогает нам.$B$BМы можем только надеяться, что наги поймут намек и осознают, что, раз мы можем проникнуть в их деревню и похитить самое ценное из их сокровищ, то мы способны и на большее. Может быть, они наконец вернутся в свой резервуар и оставят нас в покое?', NULL, NULL, NULL, 'Доставьте ковчег Ссслита в Спореггар.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9730, 'Предводитель Темного Гребня', 'Кенарийская экспедиция назначает награду за голову раджи Хагазеда, предводителя наг из клана Темного Гребня. В последний раз кенарийские разведчики видели Хагазеда в Лагуне, в центре южной части Зангартопи.$B$BКлан Темного Гребня стоит за многочисленными нападениями на Кенарийскую экспедицию, и их предводитель считается крайне опасным существом.$B$BЖелающие получить награду могут обращаться к стражу Хамуту.', 'Убейте раджу Хагазеда в Лагуне и вернитесь к стражу Хамуту из Кенарийской экспедиции в Зангартопи, чтобы получить награду.', 'Мне эти наги еще на Азероте не нравились, а тут - и подавно. Очень жаль, что наша экспедиция - мирная, а не военная. Но, в любом случае, над мертвой нагой я рыдать не стану.$B$BВот тебе твоя заслуженная награда за предводителя Темного Гребня!', NULL, NULL, NULL, 'Раджа Хагхазед убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9731, 'Схема стоков', 'На добытой вами схеме изображена система подземных труб и насосов, ведущих от крупных озер Зангартопи к Змеиному озеру.$B$BЕсли верить этой схеме, в центре Змеиного озера находится огромная труба, куда и уходит вода. Проверьте эту информацию и передайте ее в Кенарийский приют.', 'Найдите в Змеином озере признаки утечки воды. Вернитесь к Исиэли Песни Ветра в Кенарийский оплот и сообщите о своем открытии.', 'Наги превратили Змеиное озеро в огро$Nю дыру, куда постепенно сливаются все воды Зангартопи... Что же они задумали?$B$BТы правильно поступил, $N, что поспешил сообщить нам эту новость. Мы отправим отряд, чтобы исследовать это место утечки. А для тебя у меня пока что будет другое задание...', 'Какие вести с фронта, $N?', NULL, NULL, 'Схема стоков (Прилагается)', 'Исследовать локацию', 'Утечка обнаружена', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9732, 'Назад в болото', 'Возвращайся к Исиэль и дай ей знать, что помощь будет прислана при первой же возможности.$B$BНаших соратников удерживали дела на Лунной поляне и в Силитусе, однако мы сделаем все, что в наших силах, чтобы отправить подкрепление в Кенарийский приют!', 'Вернитесь к Исиэль Песни Ветра в Кенарийском приюте в Зангартопи.', 'Рада тебя видеть, $N! А у нас в Кенарийском приюте после твоего ухода дела идут все хуже и хуже...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9733, 'Предупреждение Кругу Кенария', 'Кенарийская экспедиция теперь сделалась крупной, практически самостоятельной организацией. Однако эти события достаточно важны, чтобы предупредить о них Круг Кенария.$B$BНе тревожься, тебе не придется возвращаться обратно на Лунную поляну. Посланцы Круга Кенария есть неподалеку отсюда, на полуострове Адского Пламени.', 'Поговорите с Махурамом Крепким Копытом в Траллмаре на Полуострове Адского Пламени.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9734, 'Возвращение на болота', 'Возвращайся к Исиэль и дай ей знать, что помощь будет прислана при первой же возможности.$B$BНаших соратников удерживали дела на Лунной поляне и в Силитусе, однако мы сделаем все, что в наших силах, чтобы отправить подкрепление в Кенарийский приют!', 'Вернитесь к Исиэль Песни Ветра в Кенарийском приюте в Зангартопи.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9735, 'Истинные владыки Света', 'Рыцари крови – настоящие владыки Света. Но те, кто называет себя \"паладинами\", отказываются верить в наше превосходство и желают подчинить Свет себе.$B$BПора показать им, что с нами шутки плохи. И я придумала, как это сделать! Сначала проберись в библиотечное крыло аббатства Длани Тира и выкради один фиал святой воды...', 'Принесите фиал святой воды Длани Тира Лорду Соланару Кровогневу в Луносвет.', '', NULL, NULL, NULL, 'Святая вода Длани Тира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9736, 'Истинные владыки Света', 'Теперь, когда у нас есть святая вода, пора приняться за поиски недостающих реагентов. Я подскажу тебе, где отыскать два из них, $N.$B$BОтправляйся на площадь, что возле Тропы Мертвых, и найди в одной из лавок торговку по имени Залле. У нее сможешь купить чародейский катализатор. А за вторым реагентом, сумеречным порошком, тебе прямая дорога к Дарлии, торговке ядами. Найти ее можно неподалеку от наставников разбойников в Закоулке душегубов.$B$BОставшиеся реагенты – азеротский бриллиант и чистый черный бриллиант – тебе придется искать $gсамому:самой:.', 'Принесите Лорду Соланару Кровогневу в Луносвет 1 чародейский катализатор, 1 меру сумеречного порошка, 1 азеротский алмаз и 1 безупречный черный алмаз.', '', NULL, NULL, NULL, 'Чародейский катализатор', 'Сумеречный порошок', 'Азеротский алмаз', 'Нетронутый черный алмаз');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9737, 'Истинные владыки Света', 'Только мы можем повелевать силой Света, $N. Пришло время раз и навсегда объяснить это глупцам, называющим себя \"паладинами\".$B$BЧасовня Алонсия, оплот рыцарей Серебряной Длани, оказалась нетронутой даже после разрушения Стратхольма. Неугасимое пламя, что горит внутри часовни, - вот что защищает ее. Потуши пламя с помощью огнетушительной смеси, и пусть весь мир узнает, кто настоящие владыки Света!', 'Потушите неугасимое пламя часовни Алонсия с помощью огнетушительной смеси и уничтожьте всех, кто попробует защитить часовню.', 'Замечательно, $N. Благодаря тебе весь мир узнал, что ждет каждого, осмелившегося противостоять нам.$B$BТы доказала, что достойна титула мастера. Твои деяния послужат примером для всех рыцарей крови. Помимо нового титула, я дарую тебе способность вызывать талассийского скакуна.', 'Ты преподала этим еретикам урок?', NULL, NULL, 'Снимите защиту с часовни Алонсия', 'Огнетушительная смесь (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9738, 'Пропавшие без вести', 'Умоляю, помоги мне! Нас прислала сюда Исиэль, чтобы мы разгадали загадку этих паровых насосов и выяснили, зачем они откачивают воду из болота. Однако мои друзья поступили опрометчиво - они разделились и отправились в разные стороны в одиночку.$B$BЭти четверо бывают такими недоумками, и все же я очень люблю их.$B$BПожалуйста, выясни что с ними сталось - я очень беспокоюсь. Поищи их в Узилище и в Нижетопи.$B$BБлагодарю тебя, $C.', 'Выясните, что стало с заклинателем земли Гневвсом, натуралистом Кусом, культиватором Зеленопалом и призывателем ветров Когтем. Затем возвращайтесь к дозорному Джанг в резервуар Кривого Клыка в Зангартопь.', 'Я рада, что хоть кто-то из моих друзей уцелел, и все же судьба остальных разбила мне сердце... $B$BПо крайней мере они погибли, занимаясь любимыми делом. Моя благодарность тебе безгранична, $N. $B$BПрошу тебя, прими это в знак моей признательности.', 'Ты выяснил, что стало с моими друзьями?', NULL, NULL, 'Найден землепряд Гневвс', 'Найден натуралист Кус', 'Найден культиватор Зеленопал', 'Найден призыватель ветров Коготь');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9739, 'Проблемы спорлингов', 'Эй, ты! Ты $gобязан:обязана: нам помочь!$B$BГрибные великаны пожирают все наши мешочки со спорами! Сделай что-нибудь, иначе мы останемся без потомства!$B$BМешочки со спорами поначалу большие, а потом уменьшаются, по мере того, как выходит наполняющий их воздух. Отыщи побольше маленьких зрелых мешочков со спорами и спаси их – столько, сколько сможешь!', 'Соберите 10 мешочков зрелых спор по просьбе Фассна с Грибной поляны.', 'Тебе это удалось! Мой народ несказанно благодарен тебе.$B$BНадеюсь, ты нас поймешь... ведь из этих мешочков появляются на свет наши малыши! Мы не можем допустить, чтобы эти чудовища пожирали мешочки!', 'Мешочки со спорами! Они у тебя?', NULL, NULL, 'Мешочек зрелых спор', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9740, 'Солнечные Ворота', 'Благодаря тебе и тому, что ты $gсделал:сделала:, мои разведчики сумели отыскать солнечные врата. Эльфы постарались сделать так, чтобы их можно было переместить в любой момент – именно потому на том месте, которое ты $gисследовал:исследовала:, ничего не оказалось.$B$BОднако преимущество такой системы также является и ее величайшей слабостью. Солнечные врата стабилизируются при помощи пультов управления. Если мы сможем их уничтожить, то нам удастся уничтожить и сам портал. В настоящее время солнечные врата находятся к западу отсюда, к югу от энергоблока. Найди и уничтожь их!', 'Воздаятель Эсом с Кровавой заставы хочет, чтобы солнечные врата были уничтожены.', 'Шикарно! Мы перерезали их линии снабжения. Теперь осталось нанести последний сокрушительный удар!', NULL, NULL, NULL, 'Солнечные Ворота уничтожены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9741, 'Твари из Бездны', 'Несколько дней назад Эсом послал мой отряд на поиски Солнечных Ворот. Понятное дело, мы их нашли...$B$B<Лорай указывает на Джорли.>$B$BНе знаю уж, что идиоты-эльфы таскают через этот портал, но оно вызывает выброс энергии Бездны. Всякие твари из Бездны там кишмя кишат.$B$BИх нужно уничтожить, пока они не превратились в аномалии. Все эти существа ползут от Солнечных Ворот: их несложно найти, если пойдешь отсюда на юго-запад. Когда покончишь с ними, не забудь доложить Эсому.', 'Убейте 12 тварей Бездны и сообщите об этом на Кровавую заставу воздаятелю Эсому.', 'Вот это драка, а?.. Но для тебя, $N, как я вижу, такие дела не в новинку. Что ж, а я пошлю анахоретов на помощь Лорай и Джорли.', NULL, NULL, NULL, 'Тварь Бездны убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9742, 'Новые мешочки со спорами', '', '', 'Да! Благодаря тебе спасено еще несколько мешочков со спорами!$B$BТы не такой, как другие пришельцы. Я поведаю моему народу о твоих деяниях!$B$B<Это задание можно выполнять повторно до тех пор, пока не добьешься дружелюбного отношения.:', NULL, NULL, NULL, 'Мешочек зрелых спор', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9743, 'Природные враги', 'Мы, спорлинги, и болотники никогда особо не ладили. Однако в прошлом нам удавалось обороняться от них копьями и камнями. А в последнее время они сделались более агрессивными... или же более отчаянными. Они не боятся ни нас, ни нашего оружия.$B$BНо ты – ты куда страшнее, и оружие у тебя лучше нашего. Если ты согласишься сразиться за нас против болотников, мы будем твоими вечными должниками! Принеси мне их усики, чтобы знать, сколько их тебе удалось перебить.', 'Принесите Фассну с Грибной поляны в Зангартопи 6 усиков болотника.', 'Ты вернулся живым! Я расскажу о тебе другим спорлингам! $N - победитель великанов!', 'Ну, как идет истребление болотников? Объясни этим тварям, что в земли спорлингов соваться не следует!', NULL, NULL, 'Усик болотника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9744, 'Еще усиков!', '', '', 'Невероятно! Нужны сотни спорлингов, чтобы перебить столько же великанов, сколько ты! Я позабочусь о том, чтобы о твоих деяниях стало известно всем.$B$B<Это задание можно выполнять повторно до тех пор, пока не добьешься дружелюбного отношения.>', NULL, NULL, NULL, 'Усик болотника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9746, 'Границы возможного', 'Выше голову, $N! Победа близка! Теперь, когда Солнечные Ворота обнаружены, мы скоро прекратим эти эльфийские поставки. Думаю, заодно пришло время и сократить количество самих эльфов крови...$B$BК западу отсюда разбито множество лагерей Солнечных Ястребов - шагу нельзя ступить, чтобы не столкнуться с их воином или пиромантом. Найди и убей их, а потом возвращайся ко мне.', 'Убейте 10 пиромантов и 10 защитников Солнечных Ястребов и сообщите об этом на Кровавую заставу воздаятелю Эсому.', 'Это, несомненно, ослабит их оборону. Теперь эльфы Крови не раз подумают, прежде чем попытаться напасть на нас!', NULL, NULL, NULL, 'Пиромант из клана Солнечного Ястреба убито', 'Защитник клана Солнечного Ястреба убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9747, 'Племя Тенетопи', 'Да, наги ужасны. Но еще ужаснее племена предателей, Сломленных и Заблудших, которые им помогали!$B$BИ хуже всех – Заблудшие из племени Тенетопи. Они используют черную магию, чтобы захватывать и порабощать других! К беглым рабам они особенно жестоки. Если я покину убежище хоть на день, меня поймают и перережут мне горло!$B$BОтправляйся в деревню Тенетопь к югу отсюда, и перебей их и их предводителя, Катару. Пока они живы, я не перестаю опасаться за свою жизнь!', 'Отправляйтесь в деревню Тенетопь и убейте Катару, 8 провидцев, 6 знахарей и 6 оракулов из племени Тенетопи по просьбе Икейена из Кенарийского приюта.', 'Спасибо тебе, $N! Наконец-то я смогу спать спокойно по ночам. Не будь я так стар и слаб, я бы и сам расправился со своими врагами...$B$BВот, прими это золото. Тут немного, но твое благородство не должно остаться без награды!', NULL, NULL, NULL, 'Катару убито', 'Оракул из племени Тенетопи убито', 'Провидец из племени Тенетопи убито', 'Знахарь из племени Тенетопи убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9748, 'Не пей эту воду!', 'Наш шаман утверждает, что загрязнение источника привело в замешательство духов воды. Мы знаем, что силовое ядро Экзодара сокрыто в западных горах. Должно быть, там произошла утечка летучего реагента, отравившего запасы воды... Дополнительная информация нам бы не помешала.$B$B<Эсом кивает на флакон.>$B$BТебе надо прихватить с собой этот флакон и прогуляться по берегу на север до того места, где реки острова Кровавой Дымки впадают в океан. Возьми там образец воды и принеси его мне.', 'Воздаятель Эсом на Кровавой заставе попросил вас принести пробу воды с острова Кровавой Дымки во флаконе, который он предоставил.', 'Как я и думал, вода покраснела от примесей, просочившихся из силового ядра.$B$BНадеюсь, тебе не пришло в голову искупаться в этой водичке?', 'Послушай меня, $N, не вздумай пить эту воду!', NULL, NULL, 'Проба воды с острова Кровавой Дымки', 'Флакон для пробы воды', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9749, 'Они живы! Может быть…', 'Ты представить себе не можешь, $N, что мне пришлось пережить! Ужас! Кошмарный сон!.. На нас набросились пауки, будь они прокляты, да к тому же их прародительница, чтоб у нее все лапы поотсыхали, как с неба свалилась и тут же запеленала нас всех в коконы!$B$BНо это еще полбеды: эта членистоногая зараза пристроилась рядом с нами и начала откладывать яйца! Представляешь? Она решила, что мы - отличный корм для ее молодняка. КОРМ! Вообрази только!$B$BМне-то кое-как удалось выбраться, а мои товарищи так и валяются там, спеленутые, как младенцы. В одиночку мне их не спасти: я даже близко не могу подойти к тому проклятому месту. Ты ведь поможешь мне, верно?$B$BРаспутай коконы! Может, кто-то из наших еще остался в живых!', 'Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса.', '', NULL, NULL, NULL, 'Освобождено ученых экспедиции', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9751, 'Наследие Проклятой Крови', 'Прошлой ночью в моем шатре объявился Эдвард Хейнс, капитан \"Утерянной надежды\". Да-да, тот самый Эдвард Хейнс, который умер от цинги двадцать лет назад.$B$BПризрак поведал мне историю, от которой кровь застыла у меня в жилах. Тебе непременно нужно услышать эту историю – и выполнить одно задание. Прошу тебя, разыщи Эдварда на острове Драконьей Скорби; ты сможешь найти его к северо-востоку от Кровавой заставы.', 'Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним.', 'Скажи, ты, сухопутный червяк, тебе приходилось слышать о проклятии? Ну да, конечно, разумеется, ничего! А между тем именно проклятье и потопило все эти корабли; вернее сказать, это сделал риф Проклятой Крови – мерзейшее место в мире. Я и сам здесь торчу уже двадцать лет, если ты этого не знаешь.$B$BЯкорь мне в глотку!.. Вот тут-то я и помер, стал падалью, которой даже драконы брезгуют... Впрочем, это совсем другая история. Я сейчас не о том. Мы должны помочь тем злосчастным душам, которые попали в ловушку на этом рифе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9752, 'Спасение с озера Тенетопь', 'Пожалуйста, помоги мне выбраться отсюда!$B$BЯ собирала травы неподалеку от этого места, когда меня похитила толпа этих маленьких дикарей! Я пыталась сопротивляться, но их было слишком много.$B$BПомоги мне вырваться от этих жестоких тварей с их гнусной магией и вернуться в Кенарийский приют!', 'Проводите Кайру Длинную Гриву в Кенарийский приют в Зангартопи. Выполнив эту задачу, поговорите с Исиэль Песнью Ветра.', 'Ты спас одну из моих друидов! Мы перед тобой в неоплатном долгу, $N.$B$BВ знак благодарности всей экспедиции прими от меня вот это.', NULL, NULL, NULL, 'Проводите Кайру Длинную Гриву в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9753, 'То, что мы знаем...', 'За последние дни мы много узнали о наших врагах. Эльфы крови хотят уничтожить нас; их предводителя зовут Сиронас. Их цель – поработить О\'роса и захватить \"Экзодар\".$B$BБлагодарение Свету, нам удалось лишить их снабжения, уничтожив солнечные врата. Увы, они по-прежнему используют энергоблок, чтобы отравлять землю мутагенными веществами.$B$BУзнав об этом, Адметиус разработал план действий. Тебе нужно разыскать его.', 'Поговорите с экзархом Адметиусом на Кровавой заставе.', 'Послушай, $N, мне необходима твоя помощь. У меня есть план, благодаря которому мы сумеем разгромить армию Солнечных Ястребов, однако для его осуществления понадобится дополнительная информация.$B$BНам необходимо найти слабое место в их обороне. К сожалению, никому еще не удалось подобраться достаточно близко к энергоблоку, чтобы это выяснить. Если нам удастся заставить пленника говорить, возможно, мы сумеем прорвать оборону и разрушить энергоблок.$B$BТы понимаешь, о чем я, не так ли? Я хочу, чтобы проклятый энергоблок был взорван!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9756, 'То, чего мы не знаем...', 'Должен сказать, $N, что допрос не дал никаких результатов. Разумеется, пытать пленных мы не можем, ты же понимаешь... Вот если бы мы могли послать лазутчика!..$B$BЯ могу использовать заклинания, чтобы придать тебе сходство с эльфами крови по облику и речи. Возможно, эта хитрость поможет нам получить информацию о захваченном в плен разведчике.$B$BНадеюсь, под личиной $gэльфа:эльфийки: тебе удастся вытянуть из пленника нужные сведения.$B$BДа, кстати, $N, должен тебя предупредить: не покидай Кровавую заставу под чужой личиной, иначе действие заклинания немедля прекратится...', 'Поговорите с пленным агентом Солнечных Ястребов, которого держат на Кровавой заставе. Передайте полученные сведения экзарху Адметиусу.', 'Ага! Отличная работа, $N, просто прекрасная! А теперь - как насчет того, чтобы избавить наш остров от угрозы со стороны эльфов крови?', NULL, NULL, NULL, 'Сведения о Солнечных Ястребах получены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9757, 'Охотница Келла Тетива Ночи', 'Охотница Келла Тетива Ночи ищет способных охотников. Она научит тебя приручать диких зверей - это очень важное умение для охотника.$B$BКелла живет рядом с причалом Валаара, небольшом порту на западе от Экзодара.', 'Поговорите с охотницей Келлой Тетивой Ночи рядом с причалом Валаара.', 'Что ж, я готова преподать тебе первый урок...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9758, 'Возвращение к чародею Вандрилу', 'Не окажешь ли теперь и мне любезность? Вернись к чародею Вандрилу, я знаю, что он просто жаждет отправить тебя на первое твое задание здесь, в Призрачных землях.$B$BМы очень рассчитываем на тебя, $N. Не подведи нас.', 'Возвращайтесь к чародею Вандрилу в Транкивиллион, что в Призрачных землях.', 'А, ты здесь! И как раз вовремя! Нам многое предстоит сделать!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9759, 'Отречемся от старого мира', 'Если тебе дорога жизнь, не берись за это задание. Силовое ядро видишь? Вон ту громадную штуку, которая выпирает из склона горы - ну, там, вдали?.. Кто возьмется за это безнадежное дело, тому нужно будет пробиться к горе, сразившись с целой армией Солнечных Ястребов, притом прикрывать меня, покуда я буду готовить эту штуковину ко взрыву. К тому же где-то там, наверху, находится эредар Сиронас.$B$BКороче, $N, если ты просто развернешься и уйдешь, я не буду о тебе худого думать.$B$BНо, может, ты и есть $gтот:та:, кто уничтожит энергоблок и прикончит Сиронас... Как думаешь?', 'Подрывник Легосо собирается разрушить энергоблок и убить Сиронас. Попытайтесь защитить его и, если задание будет успешно выполнено, расскажите об этом экзарху Адметиусу на Кровавой заставе.', 'Ты спас острова Лазурной и Кровавой Дымки, $N! Теперь дренеи Азерота могут жить спокойно. Нет награды, которая оказалась бы чрезмерной за такое деяние, а уж о нашей благодарности и говорить нечего, ибо она безгранична.$B$BОднако же многие и многие остались на Дреноре - их не было здесь в этот исторический момент. А потому тебе нужно вернуться. Отправляйся в Запределье, герой Аргуса. Приведи наш народ домой - в ту землю, что была спасена благодаря тебе. Домой, на Азерот...', NULL, NULL, NULL, 'Энергоблок разрушен, Сиронас убита', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9760, 'Привал Защитника', 'Конечно, $N, никто не ожидает от тебя, что ты в одиночку уничтожишь энергоблок или прикончишь Сиронас; однако, полагаю, ты поможешь расчистить путь для тех, кто решится выполнить это опасное задание.$B$BЗнаешь дорогу, идущую на север от Кровавой заставы? Иди по ней до развилки, а там сверни налево. Твоя цель - селение Привал Воздаятеля, расположенное чуть западнее дороги. Там тебя встретит Корин.', 'Поговорите с воздаятельницей Корин в селении Привал Защитника на острове Кровавой Дымки;.', 'Возможно, именно ты укажешь нашему народу путь к миру и процветанию...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9761, 'Расчистка пути', 'Только тот, кто закален в боях, только самый благородный и бесстрашный из дренеев сможет выполнить задание Легосо! Экзарх не станет поручать разрушение энергоблока и уничтожение Сиронас простому дренею. Он никого не желает посылать на верную смерть – а это значит, что новое задание, по сути, почти невыполнимо...$B$B<Корин вздыхает.>$B$BВпрочем, мое дело – всего лишь ослабить оборону Солнечных Ястребов. Тебе нужно убить тех из них, кто охраняет энергоблок, и расчистить путь для того, кому суждено стать героем... или получить это звание посмертно.', 'Убейте 8 саботажников и 8 посланников из клана Солнечных Ястребов и сообщите об этом воздаятельнице Корин в Привале Защитника.', 'Надеюсь, герой объявится раньше, чем Ястребы вызовут подкрепление, – а иначе и путь ему расчищать не имело смысла...', NULL, NULL, NULL, 'Посланник из клана Солнечного Ястреба убито', 'Саботажник из клана Солнечного Ястреба убито', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9762, 'Неписаное пророчество', '', '', 'Эти острова станут домом для тысяч и тысяч; многие останутся здесь на всю жизнь. Если таково твое желание, можешь присоединиться к ним - но ты ведь вовсе не этого хочешь, $N?*Велен кивает.*Да, ты многое свершишь, прежде чем покинешь этот мир. Не страшись своей судьбы, шагни ей навстречу!На прощание прими от меня два дара: гербовую накидку и перстень. Такие накидки носят только достойнейшие из братства Длани Аргуса, а права носить эти перстни-печатки удостаиваются лишь величайшие мудрецы. Ты достоин этих даров - носи их с гордостью.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9763, 'Убежище врага', 'Врага иногда можно уничтожить, тайком подобравшись к самому его логову.$B$BНесколько часов назад я видела, как отряд наг прошел через каменную арку во второй туннель слева. Я почти не понимаю их языка, однако одно слово сумела разобрать: Калитреш.$B$BДолжно быть, это вход в паровые подземелья, откуда полководец Калитреш осуществляет командование войсками. Найди и убей его! Я слишком слаба, чтобы помочь тебе.', 'Дозорный Джанг хочет, чтобы вы нашли и убили полководца Калитреша в резервуаре Кривого Клыка.', 'Наконец-то самый жестокий враг наших земель мертв. Благодарю тебя за помощь, $N. Экспедиция навечно у тебя в долгу.', 'Ты убил Калитреша, $N?', NULL, NULL, 'Полководец Калитреш убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9764, 'Приказы Леди Вайш', 'Письмо содержит подробные указания нагам из клана Кривого Клыка, работающим в паровых подземельях. В письме сообщается о прибытии кенарийских друидов в регион и содержиться приказ уничтожать их на месте. Количество воды, перенаправляемой в резервуар Кривого Клыка из окрестных озер, велено удвоить. Приказ скреплен печатью леди Вайш.$B$BПисьмо явно будет интересно друидам из Кенарийской экспедиции. Отнесите его их предводительнице, Исиэль Песни Ветра.', 'Отнесите приказы леди Вайш Исиэль Песни Ветра в Кенарийский приют в Зангартопи.', 'Вайш! $B$BВсе куда хуже, чем я думала. Все наши маленькие победы здесь - ничто по сравнению с величием врага. $B$BЕсли с этим связана госпожа Вайш, это значит, что в дело втянуты такие серьезные силы, с которыми наша экспедиция едва ли сможет тягаться. $B$BСпасибо тебе, $N. Полагаю, мы должны готовиться к войне.', 'Что там у тебя, $N!', NULL, NULL, 'Приказы Леди Вайш (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9765, 'Готовится к войне', 'Кенарийская экспедиция была начата как вполне мирное мероприятие. однако теперь мы, видимо, стоим на пороге войны с нагами.$B$BМногие из нас не против вступить в бой с врагов, но мы слишком плохо вооружены. Принеси мне оружие наг, и мы перекуем его на глефы и наконечники стрел.$B$BИмей в виду, нам подойдет только самое лучшее оружие, $N. Ищи наг в резервуаре Кривого Клыка.', 'Добудьте оружие клана Кривого Клыка у наг в резервуаре Кривого Клыка и принесите его Исиэль Песни Ветра в Кенарийский приют в Зангартопи.', 'О, это прекрасное оружие, $N! Если удастся достать еще, непременно приноси. Мы так плохо вооружены!', 'Удалось добыть оружие, $N?', NULL, NULL, 'Оружие Кривого Клыка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9766, 'Оружие Кривого Клыка', '', '', 'Отлично, $N! Теперь-то наги поймут, что нас нельзя недооценивать.', NULL, NULL, NULL, 'Оружие Кривого Клыка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9767, 'Врага нужно знать в лицо', 'Для того чтобы разбить врага, не всегда достаточно превосходить его силой или численностью. Часто победа основана на знании слабых мест противника, предугадывании их стратегии или тактики.$B$BМы знаем о нагах много, и все же их магия остается для нас загадкой.$B$BЯ хочу изучить магию наг резервуара Кривого Клыка. Принеси мне одну из их книг заклинаний!', 'Добудьте книгу заклинаний клана Кривого Клыка у наг из резервуара Кривого Клыка и принесите ее Ашьену в Кенарийский приют в Зангартопи.', '', NULL, NULL, NULL, 'Книга заклинаний Кривого Клыка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9769, 'Мода непредсказуема!', '$gМагаша беззвучно хихикает.>$B$BБьюсь об заклад: если бы они знали, что одеваются в мушиные крылья, эта ихняя мода быстро бы прошла!$B$BПоначалу мы истребляли насекомых просто так, чтобы не путались под руками. А тут заехал к нам какой-то ушлый торговец, покрутился – и скупил все крылья разом!$B$BГоворит, будет из них одежду шить. Ну, я-то свои доспехи ни на что не променяю... Но, если ты добудешь крылья каких-нибудь светлячков, я их с удовольствием куплю!', 'Принесите 8 прозрачных крыльев любых видов светлячков, обитающих в Зангартопи, Магаше с заставы Болотной Крысы.', 'О, отличные крылья, $N! Вот твоя плата.$B$B*Магаша выгибает одно из крыльев и прикладывает его к голове.*$B$BНе, не для меня это. Ну, оно и к лучшему!$B$B*Магаша пожимает плечами.*$B$BГлавное, чтоб платили!', 'Ну, и чего ты тут? Какая муха тебя укусила?$B$B<Магаша хихикает над собственной шуткой.>', NULL, NULL, 'Прозрачное крыло мотылька', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9770, 'Опасные болотные клыки', 'Иногда я жалею, что Денжай не отправил с нами шамана, или не дал нам с собой хотя бы тотема, который мог бы отпугивать болотных потрошителей.$B$BЭта местность буквально кишит ими! Просто кошмар какой-то. Такое впечатление, что у них вообще нет естественных врагов.$B$BМы все по очереди занимаемся тем, что истребляем этих тварей. Ты $gпришел:пришла: как раз вовремя, $N. Поздравляю! Теперь засучи рукава и перебей побольше этих тварей!', 'Убейте 10 болотных потрошителей по просьбе Реавижа с заставы Болотной Крысы.', 'Ну что, хватило с тебя?$B$B<Реавиж смеется.>$B$BВот потому-то гости у нас надолго и не задерживаются!$B$BЯ бы и сам предпочел выбрать для своей заставы местечко поприятнее, но лучше уж болотные клыки, чем гнев Денжая!', NULL, NULL, NULL, 'Болотный потрошитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9771, 'Поиски разведчика Джиобы', 'Теперь, когда здешние места тебе более или менее знакомы, я хотел бы попросить твоей помощи в еще одном деле. Мертвая трясина – так мы зовем топи к северо-западу отсюда, – место гиблое. Никто никогда не видел там ни единой живой души – но, с другой стороны, никто там подолгу и не задерживался.$B$BИ вот наш разведчик, Джиоба, вызвался исследовать эту местность и доложить о том, что ему удалось обнаружить. Он ушел с заставы три дня тому назад и до сих пор не вернулся. А между тем Джиоба не из тех, кто уходит надолго и не подает о себе вестей. Попытайся его найти, $N!', 'Найдите разведчика Джиобу в Мертвой трясине, что в Зангартопи.', 'Да, труп действительно полностью соответствует описанию. Существо, убившее Джиобу, очевидно, застигло его врасплох, потому что оружие разведчика осталось в ножнах, а по земле разлито содержимое маленькой походной чернильницы...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9772, 'Донесение разведчика Джиобы', 'Тело разведчика Джиобы усеяно кусочками засохших грибов. Кто бы его ни убил, он явно принадлежал к той же породе гигантских вянущих грибов Мертвой трясины. Возможно, один из этих высохших великанов застал разведчика врасплох, когда тот писал свое донесение...$B$BНо не имея текста донесения, невозможно узнать, что же сумел обнаружить разведчик. Если донесение удастся найти, его необходимо доставить Зураю.', 'Добудьте донесение разведчика Джиобы у высохших великанов и вернитесь с ним к Зураю на заставу Болотной Крысы.', '<Зурай берет у вас донесение и пробегает его взглядом.>$B$BБольшая часть этих сведений нам уже известна... Действительно, такое впечатление, что все в тех местах вянет и сохнет. Но есть и нечто новое.$B$BОн говорит, что грибные великаны, похоже, бесятся от недостатка влаги. Судя по твоему описанию, они-то его и убили...$B$BЯ прикажу своим подчиненным избегать тех мест. Мы не можем позволить себе новых потерь.', 'Ты вернулся, но без Джиобы. Что же с ним стало?', NULL, NULL, 'Донесение разведчика Джиобы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9773, 'Довольно грибов!', 'Грибной суп, жаркое из грибов, грибной соус...$B$BГрибы, грибы, грибы! Кроме грибов, есть тут вообще нечего! Если ты говоришь, что хочешь есть, повар вручает тебе топор и велит нарубить себе грибов на ужин!$B$BТак вот, меня это достало. Я знаю: тут, в озерах, водится рыба! Конечно, она мерзкая на вид, но все лучше, чем эти грибы!$B$BСколько ты потребуешь с меня за то, чтобы я впервые за несколько недель могла нормально поесть?', 'Добудьте 8 филе угря с угрей из озера Тенетопь и принесите их Магаше на заставу Болотной Крысы.', 'О, наконец-то хоть какое-то разнообразие! Я бы тебя расцеловала, если бы от тебя не так сильно воняло рыбой…$B$BВот увидишь, как будут мне завидовать остальные, когда почуют запах нормальной еды!', 'Ну скажи, $N, ты ведь не с пустыми руками, правда?', NULL, NULL, 'Филе угря', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9774, 'Толстая чешуя гидры', 'Реавиж правильно сделал, что привез сюда кожаные доспехи. Мой доспех от здешней сырости ржавеет на глазах. Я мало-помалу заменяю проржавевшие чешуйки. У местных гидр – отличная, прочная чешуя, и болотная сырость им нипочем.$B$BНо отыскать подходящие чешуйки не так-то просто! Самые лучшие иногда оказываются обломанными или слишком истертыми. Так что принеси мне побольше хорошей чешуи, какую сумеешь добыть у гидр, водящихся в больших озерах.', 'Принесите Зураю на заставу Болотной Крысы 12 толстых чешуек гидры. ', 'Спасибо, $N! Мне дорога каждая лишняя чешуйка.$B$BКонечно, возни с этим много, но посмотрим правде в глаза: чем еще тут можно заняться в перерыве между дежурствами?', 'Чего ухмыляешься? Да, я знаю, мой доспех будет выглядеть странновато до тех пор, пока я не заменю все металлические чешуйки на новые, но лучше уж такой доспех, чем вовсе никакого!', NULL, NULL, 'Толстая чешуя гидры', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9775, 'Донесение темному охотнику Денжаю', 'Темный охотник Денжай, несомненно, рассчитывает получить донесение о моих успехах в обустройстве нашего форта. Я приготовил краткий отчет о том, что уже сделано здесь, но теперь, после гибели разведчика Джиобы, мне некого послать гонцом на базу Денжая, в Забра\'джин на западе.$B$BЕсли тебе все равно нужно в ту сторону, может быть, занесешь ему мой доклад? Поначалу Денжай может показаться жутковатым, но, когда к нему привыкнешь, он, в сущности, неплохой малый.', 'Отнесите донесение Зурая темному охотнику Дэнжаю в Забра\'джин, что в Зангартопи.', 'У тебя донесение от Зурая? Так что ж ты сразу не сказал! Я давно жду от него вестей!$B$BЯ отправил его туда, чтобы закрепить наше присутствие на восточной границе, а не затем, чтобы он сидел сложа руки! Ну, посмотрим, что он имеет сказать...', 'Ты не похож на одного из моих подчиненных. Говори, с чем явился, $R!', NULL, NULL, 'Донесение Зурая (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9776, 'Прибежище Оребор', 'Как тебе известно, среди обитателей Телредора немало беженцев той войны, в результате которой число дренеев уменьшилось вдесятеро. И моя цель – сделать Телредор безопасной гаванью для всех наших союзников в этой борьбе. Есть и такие, кто хотел бы присоединиться к нам, но пока не готов к этому.$B$BМы должны помогать им, чем можем, $N! Группа Сломленных под предводительством Икути укрылась в развалинах старого храма к северо-западу от Змеиного озера. Отыщи их и протяни им руку помощи!', 'Поговорите с Икути в Прибежище Оребор, что в Зангартопи. ', 'Если анахорет Ахуурн считает тебя другом, возможно, ты и впрямь достоин доверия. Пожалуйста, $r, прости мне мою недоверчивость: зачастую она бывает единственным, что спасает меня и моих товарищей от гибели. Ты можешь найти приют среди нас, и, быть может, наше взаимное доверие со временем укрепится.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9777, 'Споры гриба-блескуна', 'Видишь ли, $r, у нас на болотах гореть особо нечему, поэтому приходится искать другие способы освещения. Многие из болотных животных и растений испускают слабое свечение.$B$BДержать в клетках светящихся животных сложно, да и жестоко, поэтому мы используем для освещения грибы.$B$BМы собираем и выращиваем грибы-блескуны прямо здесь, однако периодически все же приходится пополнять запасы. Эти маленькие зеленые грибочки часто растут у подножия больших грибов в окрестностях Телредора.', 'Принесите 6 спор гриба-блескуна Руаму в Телредоре. ', 'Отличные споры! Их нам хватит надолго. Спасибо за помощь, $N!', 'Судя по всему, скоро нам понадобятся новые грибы-блескуны...', NULL, NULL, 'Спора гриба-блескуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9778, 'Страж Хамут', 'Прежде чем покинуть Кенарийский приют, поговори-ка со стражем Хамутом. Он отвечает за безопасность экспедиции.$B$BЕсли я не отправлю к нему $gтакого опытного искателя приключений:такую опытную искательницу приключений:, как ты, он мне этого никогда не простит!', 'Поговорите со стражем Хамутом в Кенарийском приюте в Зангартопи. ', 'Ты от Исиэли? Ну да, разумеется, такой, как ты, мне всегда пригодится! Опытные, стойкие бойцы нам никогда не помешают.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9779, 'Перехват сообщения', 'Рад видеть тебя снова, $N. У меня тут возникла проблема - и, возможно, ты поможешь мне решить ее.$B$BНаши лазутчики в тылу врага доложили, что видели у Солнечных Ястребов какой-то странный документ.$B$BК сожалению, нам не удалось снять копию этого документа. А потому нужно, чтобы ты $gотправился:отправилась: к этим Ястребам и $gпопытался:попыталась: его раздобыть. Уверен: применив соответствующие методы, ты добьешься успеха. Как понимаешь, в средствах я тебя не ограничиваю...', 'Найдите послание Солнечных Ястребов. Возможно, для этого придется убить нескольких из них. Послание должно быть доставлено на Кровавую заставу воздаятелю Боросу.', '<Воздаятель Борос разглядывает документ.>$B$BНаписано на талассийском... По счастью, я знаю, кто это сможет перевести...', 'Что, уже вернулся? Быстро! А где же послание?', NULL, NULL, 'Послание Солнечных Ястребов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9780, 'Филе угрей из озера Тенетопь', 'Приятно видеть здесь новое лицо! Когда мы с Хаалруном впервые прибыли в Телредор, мы здесь были единственными чужаками, но с тех пор много воды утекло...$B$BТем не менее мы стараемся радушно принимать новоприбывших и заботимся о том, чтобы в городе не было недостатка в еде и припасах. Перед анахоретами Телредора мы в неоплатном долгу, однако мы стремимся не уступать им в великодушии и принимаем новичков так, как когда-то приняли нас.$B$BЕсли ты не против нам помочь, то в соседних озерах водится рыба, которая называется угорь из озера Тенетопь. Ею мы в основном и питаемся.', 'Принесите Нораани из Телредора 8 филе угря. ', 'Спасибо за помощь, $N! Твоя щедрость не будет забыта.', 'Ну что, пополнишь ли ты наши запасы рыбы?', NULL, NULL, 'Филе угря', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9781, 'Слишком много ртов!', 'Когда я в последний раз ходил на охоту, мне попалась на глаза новая застава, которую строит группа троллей. Они тоже наверняка собираются охотиться в здешних местах!$B$BЕсли они вздумали поселиться здесь навсегда, конкуренция за добычу будет жестокая. На троллей мы напасть не можем – это приведет к войне. Но мы можем хотя бы убавить количество хищников, которые тоже конкурируют с нами.$B$BКаждая убитая тобой болотная гидра – это на три голодных рта меньше!', 'Убейте 10 болотных гидр и вернитесь к Хаалруну в Телредор. ', 'Молодец! На ближайшее будущее этого должно быть достаточно, чтобы уменьшить конкуренцию. Но, конечно, со временем придется искать новые источники пищи. На одной рыбе и грибах прожить можно, но разнообразие не помешает...', NULL, NULL, NULL, 'Болотная гидра убито', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9782, 'Мертвая трясина', 'Я довольно долго прожил среди анахоретов Телредора, и за это время неплохо изучил болота. В последнее время я начал замечать, что земли на северо-востоке меняются, и не в лучшую сторону.$B$BПрактически вся местная флора и фауна начала вянуть, чахнуть и гибнуть, причем без всяких видимых причин. У меня есть несколько идей относительно того, что там происходит, но все это не выходит за рамки гипотезы. Если бы тебе удалось принести мне оттуда образец почвы, я бы, возможно, сумел постичь эту тайну...', 'Принесите пробу почвы Мертвой трясины воздаятелю Идаару в Телредоре. ', 'Почва, похоже, истощена. Но это еще ничего не объясняет. В чем же дело? Отчего же все внезапно принялось вымирать?', 'Ну что, удалось тебе добыть образец почвы Мертвой трясины?', NULL, NULL, 'Проба почвы Мертвой трясины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9783, 'Неестественная засуха', '$N, принесенный тобой образец почвы практически лишен влаги! Если уж сама земля теряет влагу, значит, существа, обитающие в Мертвой трясине, жестоко страдают от засухи!$B$BЯ видел, что бывает, когда грибные великаны начинают вянуть и умирать от засухи. Они впадают в бешенство от мучений и нападают на всех, кого встретят на своем пути!$B$BЭти существа не понимают, что происходит. Спасти их мы не в силах - лучшее, что мы можем сделать, это прекратить их мучения.', 'Убейте 12 иссохших великанов по просьбе воздаятеля Идаара из Телредора.', 'Спасибо за помощь, $N. Это была трудная задача. Наша работа в Мертвой трясине далеко еще не завершена, но теперь мы можем сосредоточиться на восстановлении природного равновесия в этих землях.', NULL, NULL, NULL, 'Высохший великан убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9784, 'Определение растений', '', '', 'Отлично. Если найдешь другие части растений, приноси их мне.$B$B<Это задание можно повторять, пока не будет достигнуто уважительное отношение.:', NULL, NULL, NULL, 'Неопознанные части растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9785, 'Благословение Древ', '$N, тебе удалось заслужить доверие Кенарийской экспедиции! Пора тебе побеседовать с древними мудрецами, Ашьеном и Келетом, и попросить их благословения.$B$BЗнак древнего мудреца даст тебе великую силу. И по мере того, как наше уважение к тебе будет расти, его действие будет только усиливаться.$B$BСтупай, $N, попроси благословения у древних мудрецов!', 'Призывательница ветров Черное Копыто просит вас поговорить с древами Ашьеном и Келетом в Кенарийском приюте и получить их благословение.', 'Ты вернулся! Удалось ли тебе получить благословение Древ?', '$N, ты уже поговорил с древними мудрецами?', NULL, NULL, 'Знак мудрости', 'Знак войны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9786, 'Руины Боха\'му', 'До того как орки истребили большую часть моего народа, Телредор служил убежищем дренейским анахоретам и спиритуалистам. Небольшой орден анахретов и воздаятелей имел множество святилищ в здешних краях.$B$BВо время войны мы потеряли связь с анахоретами из святилищ, в особенности из храма Боха\'му на юго-западе. До меня доходили сведения, что в тех местах обосновалась группа Заблудших, и они, возможно, даже используют развалины храма. Побывай в руинах Боха\'му и расскажи мне о том, что там найдешь.', 'Исследуйте руины Боха\'му по просьбе анахорета Ахуурна из Телредора. ', 'Так значит, в руинах поселились Заблудшие Дикотопи? Как интересно... Должно быть, они помнят что-то из своего прошлого и сознают значимость этого места. Нужно узнать об этом побольше, Печенькус! Возможно, в этом храме таится ключ к тому, чтобы вернуть Заблудших и восстановить былое величие дренеев.', NULL, NULL, NULL, 'Исследовать локацию', 'Исследуйте руины Боха\'му', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9787, 'Идолы Дикотопи', 'Судя по твоим рассказам о том, что происходит в руинах Боха\'му, это племя Заблудших поклоняется духам животных. Но прежде, чем познакомиться с ними поближе, нам следует больше узнать об их верованиях!$B$BВозвращайся в деревню Дикотопь и добудь втайне несколько их идолов, чтобы я мог их изучить. Только постарайся не рассердить самих Заблудших – это может помешать нам установить с ними контакт...', 'Соберите 6 идолов Дикотопи и вернитесь с ними к анахорету Ахуурну в Телредор.', 'Да, $N, этого будет более чем достаточно. Они, кажется, помешаны на птицах - это странно: ведь в Зангартопи изначально никаких птиц не водилось. Что бы это могло значить?$B$BБыть может, они встречались с араккоа? Народу шаманов араккоа могли показаться воплощением могущественного духа...', 'Ну что, идолы у тебя?', NULL, NULL, 'Идол Дикотопи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9788, 'Темное, сырое место', 'Вскоре после того, как мне удалось бежать от племени Тенетопи, я укрылся в пещере к югу от их деревни. Я ведь не знал, что за эту пещеру сражаются между собой болотные твари и гриболюди!$B$BМне пришлось в спешке бежать оттуда, и я оставил там сундучок со всем, что у меня было.$B$BКакая насмешка судьбы: спасти свое имущество из деревни Тенетопь, чтобы почти сразу его потерять! Если ты согласишься принести мне мой сундучок, я подарю тебе какую-нибудь ценную вещь. Что скажешь, $N?', 'Отыщите вещи Икейена в пещере к югу от Тенетопи. Верните их Икейену в Кенарийском приюте в Зангартопи.', 'Мои вещи! Все здесь, ничего не пропало!$B$BСпасибо тебе, $N! Теперь я, как и обещал, разрешу тебе выбрать одну из моих вещей. Их у меня осталось немного, но мой народ всегда делился тем немногим, что имеет!', 'Тебе удалось отыскать мои вещи, $N? Эта пещера недалеко от Тенетопи, на границе с Награндом...', NULL, NULL, 'Вещи Икейена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9789, 'Охота на копытней', 'Хочешь стать $Gохотником:охотницей;? Сначала докажи, что ты этого $gдостоин:достойна:.$B$BМеня не волнует, сколько у тебя трофеев и как они были добыты. Если ты ни разу не $gбыл:была: с нами на охоте – считай, ты вообще ничего в этом не смыслишь. Начни с копытней, если $gты настоящий мужчина:тебе хватит смелости:.$B$BКак раз недавно я видел поблизости стадо копытней. Еще они водятся на юге.', 'Убейте 12 копытней и вернитесь к Хемингу Эрнестуэю в его охотничий лагерь в Награнде.', 'Для начала неплохо. Но лишь для начала.$B$BМелкие копытни – это несерьезно. Надо поручить тебе более сложное задание!', NULL, NULL, NULL, 'Копытень убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9790, 'Прозрачные крылья', 'Живя в такой отдаленной и дикой местности, мы научились пользоваться всем, что есть под рукой. Разумеется, поначалу мы старались не думать, из чего это все сделано...$B$BЯ обнаружил, что крылья бледносветных острожалов – отличный водооталкивающий материал. Они прочные, легкие и эластичные.$B$B<Хаалрун хмыкает.>$B$BДа-да, вижу, тебе эта идея не по вкусу! Что поделаешь, надо просто привыкнуть. Так вот, если уж ты все равно будешь шляться по болотам, не принесешь ли мне таких крыльев, если они тебе попадутся?', 'Принесите Хаалруну из Телредора 8 прозрачных крыльев любых видов светляков, обитающих в Зангартопи.', 'Спасибо тебе, Вэлс!$B$B*Хаалрун сочувственно улыбается.*$B$BНу, порадуйся хотя бы тому, что тебе не придется их отчищать! Это самая противная часть работы. Однако если их как следует отскоблить, ни за что не скажешь, что это крылья гигантского насекомого.', 'Ну что, удалось тебе раздобыть прозрачные крылья?', NULL, NULL, 'Прозрачное крыло мотылька', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9791, 'Опасные болотные клыки', 'Пока орки вели войну против моего народа, собиратели редко выбирались за пределы Телредора, поскольку боялись нападения или плена. Теперь мы чаще выходим за стены, но болота не стали менее опасными!$B$BТакое впечатление, что за последние несколько месяцев скаты Пустоты совершенно обнаглели. Не знаю, в чем дело, может быть, им сделалось труднее охотиться на их обычную добычу, но сейчас они то и дело нападают на наших собирателей. Если бы нам удалось уменьшить их численность в окрестностях Телредора, возможно, они оставили бы нас в покое...', 'Убейте 10 болотных потрошителей и вернитесь к Нораани в Телредор. ', 'Спасибо тебе за помощь, $N! Если бы болотные потрошители были хотя бы отчасти разумны, быть может, это научило бы их не связываться с нами...$B$B*Нораани пожимает плечами.*$B$BЖуки-переростки, наделенные разумом... Интересно, как бы это выглядело?', NULL, NULL, NULL, 'Болотный потрошитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9792, 'Послание в Телаар', 'В нынешние времена завоевать доверие моего народа непросто, но ты, $N, неизменно $gпоступал:поступала: с нами честно и благородно.$B$BВ древнем дренейском городе Телаар в Награнде, к югу отсюда, обитает большая группа моих собратьев. Чтобы попасть в Телаар, ступай по дороге, ведущей на юг, в Награнд, а там поверни на юго-восток и иди, пока не очутишься на утесах к востоку от Ошу\'гуна.$B$BВ Телааре рады будут любому, кто помогал нам так, как ты.$B$BОтыщи там Нахууда и скажи ему, что я тебе доверяю.', 'Поговорите с Нахуудом в Телааре в Награнде. ', 'Икути мне как брат! Его друзья - мои друзья! Добро пожаловать в Телаар, $N. Мы благодарны тебе за помощь нашему народу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9793, 'Судьба Туурема', 'Поиски союзников, которые вел пророк Велен, ободрили дренеев, оставшихся в Запределье, и заставили их тоже приняться за поиски. Нападение Легиона заставило наш народ покинуть свои города и храмы, однако же наша цивилизация не была разрушена полностью.$B$BТуурем, мой родной город, находящийся в лесу Тероккар, был захвачен орками одним из первых. Я уже давно не получал известий о том, что там происходит. Отнеси это письмо в бастион Аллерии в лесу Тероккар и отдай его Андарлу.', 'Отнесите письмо воздаятеля Идаара Андарлу в бастион Аллерии в лесу Тероккар.', 'Хм... Да, я помню, как наши разведчики упоминали о руинах дренейского поселения в северной части леса. Самому мне об этих развалинах мало что известно, но ты, если хочешь, можешь поговорить с разведчиками.', 'Чем могу помочь?', NULL, NULL, 'Письмо воздаятеля Идаара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9794, 'Не время для любопытства', '$N, я вынужден просить тебя об услуге. В другое время я сделал бы это сам, но у меня и без того дел невпроворот.$B$BУ меня есть соратник, по имени Киалон. Он живет в Сильванааре, что в Острогорье к северу отсюда. Он ждет от меня письма, хотя, подозреваю, ему не понравится то, что он прочтет.$B$BЕсли ты доставишь ему мой ответ, я буду тебе очень признателен. Только смотри, не вздумай читать это письмо! Оно предназначено только Киалону, и никому другому.', 'Доставьте письмо Тимоти Киалону в Сильванаар в Острогорье.', 'А, так ты принес ответ Тимоти?$B$B<Киалон пробегает глазами письмо, потом разражается хохотом.>$B$BНу конечно же, у него все под контролем, и помощь ему не нужна! Я так и знал!$B$BНекоторые все-таки никогда не меняются. Ты погляди, у него даже нашлось время указать мне на ошибки в правописании!$B$B<Киалон вздыхает.>$B$BНе стоило ему и писать. Я совсем забыл, что он за человек. Ну разумеется, у настоящего специалиста всегда все под контролем!', '<Киалон смотрит на вас с подозрением.>$B$BЯ тебя не знаю, $C. У тебя ко мне дело?', NULL, NULL, 'Письмо Киалону (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9795, 'Угроза со стороны огров', 'На болотах становится все больше огров. Как будто мало нам было наг и их союзников! Огры уже захватили большую территорию на северо-западе, и слишком близко подобрались к нашим землям.$B$BНа место каждого убитого нами огра тотчас встают несколько новых. Даже не знаю, долго ли мы продержимся, если им взбредет в голову напасть на Забра\'джин! Ступай на север, в горы, в орочий оплот Громоборцев, и сообщи Нехтару о нашем положении. Мы были бы рады любой помощи!', 'Отправляйтесь в оплот Громоборцев в Острогорье и поговорите с Нехтаром.', 'Денжай просит о помощи? Нет, я, конечно, пошлю ему подкрепление, но у нас и тут бойцов негусто... И нас тоже донимают огры.$B$BЯ при первой же возможности сообщу ему все, что нам известно о местных племенах огров и об их тактике. Быть может, если Денжай продержится достаточно долго, мы сумеем ударить по этим гнусным тварям с двух сторон одновременно...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9796, 'Новости из Зангартопи', 'Темный охотник Денжай – не единственный, кто ждет от меня вестей. Мокаса из форта Камнеломов в Тероккаре ждет не дождется известий о том, как идут наши дела, тем более, что большинство ее посланцев проходит через болота.$B$BОна просила меня прислать ей весточку, когда мы достроим заставу Болотной Крысы. Не согласишься ли ты доставить ей мое послание? Я буду тебе очень признателен. Мы тут работаем не покладая рук, но все равно дел по горло...$B$BЧтобы попасть в форт Камнеломов, ступай по дороге, что ведет из Зангартопи на юг, в лес Тероккар, за Туурем.', 'Поговорите с Мокасой в форте Камнеломов в лесу Тероккар. ', 'Да уж, давно пора ему достроить эту заставу! Слишком много наших гонцов погибло от рук разбойников из Альянса...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9797, 'Подкрепление для Гарадара', '$gПосланник, все еще запыхавшийся, делает вам знак сесть.>$B$BБоюсь, им не выстоять, $r! Беги в Гарадар со всех ног.$B$B<Видя ваш недоумевающий взгляд, посланник поясняет.>$B$BГарадар – это поселение маг\'харов, оно находится в Награнде, к югу отсюда. Ступай по дороге, ведущей с болот на юг, на первой развилке сверни на восток, и придешь в большое поселение на озере.$B$BОтыщи там нашего командира, капитана Крогана, и предложи ему помощь. Гарадар не должен пасть!', 'Поговорите с капитаном Кроганом в Гарадаре в Награнде. ', '<Кроган старается этого не показывать, но тем не менее на его лице отражается облегчение.>$B$BТы как раз вовремя! Конечно, мы предпочли бы увидеть целую армию, но сейчас нам пригодится любой опытный $R, способный носить оружие или применять заклинания. Народ Гарадара – не чужой Орде, и мы гордимся тем, что проливаем кровь, защищая их!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9798, 'Планы эльфов крови', 'Кажется, дренеи должны узнать об этих планах. Отнесите их воздаятелю Алдару на место крушения.', 'Отнесите планы эльфов крови воздаятелю Алдару на место крушения в долине Аммен.', 'Ну-ка, дай я посмотрю на планы.$B$BНеужели эльфы крови выследили нас? Вот уж в ком зло пустило корни, так это в них. Их надо уничтожить!$B$B<Воздаятель пытается сдержать волнение.>$B$BПрошу прощения, это так неожиданно. На самом деле я очень благодарен тебе за эту находку.', 'Что там у тебя?', NULL, NULL, 'Планы эльфов крови (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9799, 'Сбор трав', 'На полях Аммен, что на западе отсюда, обитают здешние корнехлесты. Воды ближайшего к ним озера очень загрязнены, и ботаник Таэрикс беспокоится, что после их очистки популяция корнехлестов не восстановится.$B$BСходи на поля Аммен, сорви несколько оскверненных цветов. Я взгляну на них и подумаю, что можно сделать. Их легко отличить от других по необычным красным лепесткам.', 'Сорвите 3 оскверненных цветка и вернитесь к ученице Вишаэль на месте крушения в долине Аммен.', 'Неплохие образцы. Спасибо за помощь. Как только я найду время и проведу анализ этих растений, можно будет примерно понять, сколько усилий потребуется для восстановления полей.', 'Привет, $C. Набрал цветов?', NULL, NULL, 'Оскверненный цветок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9800, 'Редкий деликатес', 'Ты еще не $Gготов:готова; встретиться с беспокойными стихиями Награнда. Прежде чем браться за задания Служителей Земли, тебе нужно сначала помочь $gсамому:самой: себе.$B$BНа западе ты найдешь кучки помета, оставленные местными четвероногими. Надо просеять помет и выбрать оттуда семена награндской караколлы. Из них я смогу приготовить пилюлю, которая поможет тебе в бою с беспокойными силами природы.$B$BВозвращайся, когда наберешь две горсти семян. Горсти отмеряй по меркам огров.', 'Принесите Повелителю стихий Ло\'апу к Трону Стихий в Награнде 8 семян караколлы.', 'Только, пожалуйста, не вздумай купаться в священных водах Трона.$B$B<Ло\'ап протягивает вам готовую пилюлю из семян караколлы.>$B$BПоложи ее под язык и дождись, пока она полностью не растворится. После этого ты сможешь дышать под водой подобно рыбам.', '<Ло\'ап берет бобы в руки и неодобрительно качает головой.>$B$BЯ же сказал, по меркам огров...', NULL, NULL, 'Семя караколлы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9801, 'Сбор реагентов', 'У меня такое ощущение, что эти Заблудшие не будут рады видеть дренея, а вот араккоа примут с распростертыми объятиями. Я могу создать зелье, которое позволит тебе ненадолго принять облик араккоа. Однако для этого требуется пара реагентов, которые нельзя хранить подолгу и необходимо использовать в течение нескольких часов после того, как они были добыты.$B$BТебе придется принести мне горсть глаз спороската и несколько щупалец болотного долгонога. Оба вида обитают поблизости от Телредора.', 'Принесите анахорету Ахууму в Телредоре 4 глаза спороската и 4 щупальца болотного долгонога.', 'Да, это отлично подойдет! Минутку, я сейчас приготовлю зелье...', 'Ну что, реагенты при тебе?', NULL, NULL, 'Глаз спороската', 'Щупальце болотного долгонога', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9802, 'Растения Зангартопи', 'Озера Зангартопи мало-помалу пересыхают. Почему – мы точно не знаем, но известно, что многие виды растений уже находятся на грани вымирания.$B$BПоскольку я – каталогизатор экспедиции, в мои обязанности входит отслеживать и идентифицировать вымирающие растения, чтобы мы могли понять, что с ними происходит.$B$BЕсли вы хотели бы нам помочь, приносите мне неопознанные части растений. Их можно собирать самостоятельно, если вы $gтравник:травница:, а еще их иногда имеют при себе обитатели болот.', 'Принесите 10 неопознанных частей растений Лоранне Тар\'велл в Кенарийском приюте в Зангартопи.', 'Да, сокращение числа местных эндемиков не может не тревожить. А распространение видов, занесенных извне, может быть связано с недавними проблемами в экосистеме. У меня пока недостаточно информации, чтобы сделать окончательные выводы...$B$B<Лоранна перебирает растения и делает какие-то пометки в своем дневнике.>$B$BВозьми вот это, $N. Возможно, они тебе пригодятся.$B$BПриноси мне и другие части растений, которые тебе встретятся.', 'Ну что, $N, удалось вам найти какие-нибудь части растений?', NULL, NULL, 'Неопознанные части растений', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9803, 'Посланец в Дикотопь', 'Пришло время встретиться с племенем Дикотопи и внушить им, что Свет не отрекся от них. Возьми с собой приготовленное мною зелье и отправляйся в руины Боха\'му.$B$BПридя в руины, выпей зелье. Оно придаст тебе облик одного из их птичьих духов. Поговори со старейшиной Курути и дай ему знать, что дренеи готовы принять его народ, как своих давно потерянных собратьев.', 'Отправляйтесь в руины Боха\'му и выпейте эликсир Ахуурна. Приняв обличье араккоа, поговорите со старейшиной Курути.', 'Они отказались? Разумеется, они вправе сами выбирать свой путь, и все же их выбор меня изумляет. Мне казалось, что все дренеи, будь то Сломленные или Заблудшие, должны в глубине души помнить, что все мы когда-то были единым народом…$B$BПолагаю, он прав, и глупо было пытаться их обмануть, но неужели он не понимает, что мы сделали это с наилучшими намерениями?', 'Ты поговорил со старейшиной Дикотопи?', NULL, NULL, 'Ответ старейшины Курути', 'Эликсир Ахуума (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9804, 'Беспокойные духи озера Небесной Песни', 'Нарушение цикла приливов и отливов награндских вод взбудоражило водных духов озера Небесной Песни. И они, в свою очередь, тоже стали нести разрушение по водным путям.$B$BВатуусан Водный явился нам в видении и дал разрешение устранить эту проблему – при условии, что мы разберемся и с изначальным источником беспокойства...$B$BНо всему свое время. Сначала нам следует устранить опасность, непосредственно угрожающую Трону. Уничтожь взбешенных озерных духов и возвращайся ко мне.', 'Уничтожьте 8 озерных духов по просьбе Повелителя cтихий Ло\'апа, обитающего у Трона Стихий.', '<Повелитель стихий Ло\'ап встает на колени в воде и читает молитву.>$B$BСлужители Земли скорбят о содеянном. Но мы делаем все, что в наших силах, чтобы исцелить раны земли.', NULL, NULL, NULL, 'Озерный дух убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9805, 'Благословение Возжигателя', 'Презренные Заблудшие до сих пор не высовывались из Зангартопи, но теперь они собираются разнести свою скверну по всему нашему миру.$B$BЯ попросил совета у сил природы и получил их благословение. Чтобы остановить нашествие, мы должны натравить на Заблудших стихии!$B$BЯ одолжу тебе живой огонь, взятый от пылающей сущности самого Возжигателя. Отправляйся на юго-восток, в деревню Трепещущего Тростника, и запусти им живой огонь под крыши! Пусть мерзавцы познают ярость стихий!', 'Спалите самый большой дом и три лачуги на западной, восточной и южной окраинах деревни Трепещущего Тростника.Когда выполните поручение, верните живой огонь повелителю стихий Ло\'апу.', 'Твои усилия приостановили распространение скверны, но теперь возникли иные трудности.', 'С великим стыдом я признаюсь, что это мой собственный народ пытается запрудить реки Награнда и превратить добрые земли в болото.', NULL, NULL, 'Большой дом уничтожен', 'Западная лачуга уничтожена', 'Южная лачуга уничтожена', 'Восточная лачуга уничтожена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9806, 'Прорастающие споры', 'Спороскаты и болотоброды бродят среди высоких грибочков и собирают прорастающие споры своими конечностями.$B$BМы, как видишь, народец низкорослый, и сами добывать эти споры можем с большим трудом. Ищи спороскатов и болотобродов, и собирай прорастающие споры. Весь Спореггар будет тебе крайне признателен.', 'Соберите 6 прорастающих спор с различных спороскатов и болотобродов. Выполнив задачу, вернитесь к Гшаффу в Спореггар.', 'Отличные споры, $N! Высокие грибочки необходимы нам для того, чтобы отстроить наш город. А после всех нападений болотников, которые мы пережили, их у нас осталось совсем мало...', 'Ты снова здесь, $N! Удалось ли тебе раздобыть прорастающие споры?', NULL, NULL, 'Прорастающие споры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9807, 'Новые прорастающие споры', '', '', 'Мы ценим твою помощь, $N. Ждем новых спор!', NULL, NULL, NULL, 'Прорастающие споры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9808, 'Грибы-огнешляпки', 'Я видел, как твои сородичи обменивают нужные им вещи на блестящие металлические кругляшки. Мы от вас не так сильно отличаемся. У нас тоже есть свои деньги: блестящие кругленькие грибочки.$B$BГрибы-огнешляпки растут на болотах повсюду, нужно только уметь добыть их из земли, не повредив. Я тебя этому научу, если только обещаешь принести несколько штук нам, в нашу казну. Ну что, идет?', 'Принесите 10 огнешляпок Мссхи\'фну в Спореггар в Зангартопи. ', 'Это поможет нам приобретать еду и припасы у других спорлингов! Спореггар благодарит тебя, $N!', 'Ну что, $N, удалось тебе добыть грибы-пламеневики? Они тут повсюду, буквально прямо под ногами!$B$BИх яркое сияние видно издалека, если внимательно приглядеться.', NULL, NULL, 'Огнешляпка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9809, 'Нужно больше грибов!', '', '', 'Спасибо тебе, $N! Я, как старейшина Спореггара, должен заботиться о том, чтобы у моего народа всего было в достатке. И ты сильно облегчаешь мою задачу!', NULL, NULL, NULL, 'Огнешляпка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9810, 'Оскверненный дух', 'Ватусану удалось остановить распространение скверны, но при этом он нечаянно создал искаженного духа. И этот дух вобрал в себя всю скверну и порчу!$B$BТебе нужно найти этого искаженного духа болот. Он укрылся в глубинах озера Солнечного Источника к юго-западу отсюда.$B$BРазыщи и уничтожь искаженного духа Ватусана, а также все его порождения, также тронутые скверной.', 'Уничтожьте загрязненную сущность Ватуусана и 8 озерных волноплесков по просьбе Повелителя cтихий Ло\'апа.', 'Стихии воспели твою победу в ту же секунду, когда ты уничтожил искаженного духа! Служители Земли благодарны тебе, $N. Ты можешь выбрать любую награду.', NULL, NULL, NULL, 'Загрязненная сущность Ватуусана убито', 'Озерный волноплеск убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9811, 'Друг син\'дорай', '$N, начинается новая глава в истории эльфов крови. Укрепление отношений между нашими расами - во многом твоя заслуга, $r.$B$BОтнеси голову предателя лорду-регенту Лор\'темару Терону в Луносвет и расскажи о том, что произошло.', 'Принесите голову Дар\'Хана Лор\'темару Терону в Луносвет. ', 'Так значит, ты убил Дар\'Хана, $R? Прекрасно, прекрасно. Думаю, это станет началом крепкой дружбы между нашими народами.', 'Ты хочешь поговорить со мной, $C? Не припомню, чтобы назначал тебе встречу.', NULL, NULL, 'Голова Дар\'Хана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9812, 'Посол к Орде', 'Наши потенциальные союзники сомневались в наших способностях. Какая им от нас польза, если мы собственные проблемы решить не можем?$B$BТеперь все изменилось. В нашей силе никто не усомнится. Мы сможем вступить в Орду как равные.$B$BОтнеси это письмо Сильване, правительнице Отрекшихся. Она и так на нашей стороне, но весть о смерти Дар\'Хана будет воистину музыкой для ее ушей. Готовься к долгому пути, $N. Если все сложится благополучно, Сильвана пошлет тебя в Оргриммар.', 'Отнесите письмо от Лор\'темара Терона леди Сильване Ветрокрылой в Подгород, столицу Отрекшихся в Тирисфальских лесах.', 'Итак, свершилось. Подлый предатель получил по заслугам.$B$BТы оказал огромную услугу эльфам крови и Орде. Тралл отказывался принять в наши ряды эльфов, покуда был жив Дар\'Хан. Ты же открыл дорогу обновленной Орде.$B$BЯ вижу, что вести Лортемара значительно улучшат его отношения с Траллом. Превосходно!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9813, 'Встреча с вождем', 'Я по-прежнему всей душой люблю свою родину и свой народ. Я билась зубами и когтями за то, чтобы Луносвету предоставили место за столом переговоров наравне с Подгородом и Оргриммаром.$B$BЭто должно заставить всех недовольных умолкнуть. Отнеси это письмо Траллу в Оргриммар. Ему, как главе Орды, принадлежит последнее слово относительно того, будет ли удовлетворена просьба син\'дорай.$B$BК этому письму приложена моя личная печать, как доказательство подлинности. Ступай на северо-запад города и у башни сядь на дирижабль до Дуротара.', 'Отнесите письмо с печатью Леди Сильваны Ветрокрылой Траллу в Оргриммар, столицу Дуротара.', '<Тралл открывает письмо и начинает читать.>$B$BАга, значит, эльфы крови наконец разобрались со своей проблемкой... Неважно, что для этого потребовалась твоя помощь и целый отряд Отрекшихся.$B$B<Тралл хохочет.>$B$BНу, с этим уж ничего не поделаешь. В конце концов, они нам нужны не меньше, чем мы им.', 'Да, $C?', NULL, NULL, 'Письмо с печатью Сильваны (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9814, 'Грибы-пороховики, слышь?', 'Любишь грибочки, а? Тут, в Зангартопи, у самого Забра\'джина, растут крутые грибочки!$B$BТолько смотри, держи ухо востро! Их не зря зовут пороховиками. Если подойдешь слишком близко, и не остережешься, они взрываются прямо тебе в лицо. Бабах – и ты с головы до ног в ядовитых спорах!$B$BЯ их использовал, чтобы толковать предсказания, но мои запасы почти закончились...', 'Принесите знахарю Тор\'геш 6 грибов-пороховиков. ', 'Во, отлично!$B$BСлышь, че я тебе скажу? За эти грибочки я тебе устрою потеху!', 'Ну че, где мои грибочки?', NULL, NULL, 'Гриб-пороховик', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9815, 'Грязные делишки', 'Духи воды, подвергшиеся наиболее пагубному воздействию, обитают в котловине Халаани к юго-западу отсюда, у заброшенного города Халаа. И хотя некоторые зараженные духи могут быть уничтожены без вреда для окружающей среды, останки порождений грязи тоже должны быть устранены.$B$BИначе эти ядра, остающиеся после уничтожения порождений, могут снова загрязнить окружающую среду.$B$BУничтожь порождения грязи и принеси мне их ядра.', 'Принесите повелителю стихий Ло\'апу к Трону стихий в Награнде 5 ядер порождений грязи.', 'Служители Земли благодарят тебя, $N. Стихии также передают тебе благодарность. Мы отметили и оценили твои усилия по очищению этого мира.', 'Смотри, чтобы там не осталось ни единой крупинки грязи!', NULL, NULL, 'Ядро порождения грязи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9816, 'Видали вы такое?', 'Все в этом болоте есть, одного не хватает: мурлоков!$B$BНо ты не дрейфь: я придумал, как это уладить. Вон, видишь Булька с Гурглом, какие они прикольные? Так вот, я собираюсь подарить Заблудшим таких же забавных мурлоков!$B$BВот, бери эту клетку, тащи ее к деревне Остротопь и выпусти этих малявок среди северо-восточного скопления хижин. Нет, Булька с Гурглом я с тобой не отпущу. Но эти разноцветные мелкие мурлоки ничем не хуже! Поставь клетку на большой плоский камень, который там увидишь, и открой дверцу!', 'Отнесите клетку с мурлоками в деревню Остротопь и оставьте ее на плоском камне.', 'Ай, молодца! Надеюсь, им там теперь не скучно!', NULL, NULL, NULL, 'Выпустите мурлоков у деревни Остротопь', 'Клетка с мурлоками', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9817, 'Глава клана Кровавой Чешуи', 'Кенарийская экспедиция назначает награду за голову раджис Фьяше, предводительницы наг из клана Кровавой Чешуи. В последний раз эту чародейку видели в Змеином озере, на севере Зангартопи.$B$BКлан Кровавой Чешуи чрезвычайно опасен, и с их предводительницей нужно быть крайне осмотрительным!$B$BЖелающие получить награду могут обращаться к стражу Хамуту в Кенарийском приюте.', 'Убейте раджис Фьяше в Змеином озере и вернитесь к стражу Хамуту в Кенарийский приют в Зангартопи, чтобы получить награду.', 'Могу поручиться, что теперь клан Кровавой Чешуи подумает дважды, прежде чем нападать на наших разведчиков! Вот твоя награда, $N. Она честно заслужена!', NULL, NULL, NULL, 'Раджис Фьяше убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9818, 'Из глубин', 'Что-то происходит там, под землей. Почва дрожит, будто ее истязают. $B$B*Унтраг бьет себя кулаком в грудь.*$B$BЭтот звук повторяется сто тысяч раз. Без конца. Земля содрогается. Она взывает к нам.$B$BГордауг говорил со мной. Он сказал, что нечто вытесняет стихии наружу. Нечто из глубин.$B$BИди и поговори с Гордаугом. Нет, не говори ничего, просто слушай Гордауга. Слушай Гордауга и услышь...', 'Поговорите с Гордаугом. ', '<Гордауг, кажется, кивает вам.>$B$BСадись.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9819, 'Истерзанные духи земли', 'Приведи узурпатора. Ты найдешь его. Иди по земляной тропе. Сначала успокой истерзанных духов земли. Пусть уснут снова.$B$B<Гордауг бьет кулаком о землю, и от удара куски дурно пахнущей почвы летят во все стороны.>$B$BПусть уснут!$B$B<Гордауг указывает на юго-восток.>$B$BИщи духов у гор. У холмов. У камней. У земли.$B$BПусть духи уснут.$B$BТелаарская котловина... На юго-востоке.', 'Уничтожьте 10 истерзанных духов земли по просьбе Гордага из Трона Стихий Награнда.', '<Гордауг одобрительно кивает.>$B$BХорошо. Духи уснули.', NULL, NULL, NULL, 'Истерзанный дух земли убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9820, 'РАЗЫСКИВАЕТСЯ: Главарь Грог\'ак', 'Разыскивается живым или мертвым главарь Грог\'ак из клана Анго\'рош, ответственный за операцию по сбору грибов.$B$BЭтот мерзавец и его прихвостни повинны в вырубке грибов к северу от поселения! Если их не остановить, эта банда прорубит тропу к самым стенами Забра\'джина!$B$BТот, кто доставит голову Грог\'ака темному охотнику Денжаю, получит щедрое вознаграждение!', 'Принесите голову главаря Грог\'ака темному охотнику Денжаю в Забра\'джин.', 'Молодец, $N! Однако то, что эти огры подобрались так близко к нашему форпосту, изрядно меня тревожит. Похоже, они уже давно пробираются сюда с северных гор...', 'Что там у тебя, $N?', NULL, NULL, 'Голова главаря Грог\'ака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9821, 'Попробовать зло на зуб', '$gГордауг берет кусок породы и пробует его на зуб.>$B$BГордауг пробует. Гордауг знает, откуда эта земля.$B$B<Гордауг поднимает тяжеленную ногу и с силой впечатывает ступню в землю.>$B$BСмотри. Это Награнд.$B$B<Гордауг указывает на отпечаток ступни. Он оказывается подробной геологической картой Награнда, где обозначено местоположение элементалей, которых Гордауг хочет уничтожить.>$B$BРАЗДАВИ ИХ! Принеси Гордаугу осколки, я их съем.$B$BВозьми карту.', 'Принесите Гордаугу к Трону Стихий 10 средоточий разъяренных сокрушителей.', '<Гордауг разжевывает камни и с отвращением сплевывает их, обдавая вас градом осколков.>$B$BЯд. Эти камни не из Награнда. Эти камни – яд. Уничтожь ядовитые скалы. Найди захватчика.', 'Гордауг есть камни. Гордауг найти захватчика. Неси камни!', NULL, NULL, 'Средоточие разъяренного сокрушителя', 'Отпечаток Гордауга', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9822, 'Угроза нападения', 'Сдается мне, что огры не случайно затеяли вырубать грибы именно в этом направлении. Я подозреваю, что они готовят нападение на Забра\'джин!$B$B$N, мне нужно знать это наверняка! У огров есть еще один форпост на северо-западе, земли Анго\'рош. И если они готовятся напасть, там непременно должны быть признаки этого. Ступай в земли Анго\'рош, $N, и постарайся выяснить это. Если обнаружишь что-нибудь подозрительное, возвращайся ко мне.', 'Принесите планы нападения клана Анго\'рош темному охотнику Денжаю в Забра\'джин.', '<Темный охотник Денжай внимательно изучает план.>$B$BЯ так и знал! Где завоняло огром – там без войны не обойдется... Ну, теперь, когда у нас есть доказательство их намерений, следует их опередить!', 'Ну что, удалось ли тебе обнаружить доказательства намерений огров?', NULL, NULL, 'План нападения клана Анго\'рош', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9823, 'Мы и они', 'Чтобы покончить с угрозой клана Анго\'рош, нужно убить их вождя, властителя Кровавого Кулака. Однако мы не просто убьем его – судьба властителя и его приверженцев станет примером для всего клана!$B$BСтупай в крепость Анго\'рош и покончи с нашими врагами. Крепость находится на маленьком острове к северо-западу от Забра\'джина. Пройди лагерь Анго\'рош, и увидишь мост из поваленного гриба.$B$BНе давай им пощады, $N! Они нас щадить не будут.', 'Убейте властителя Кровавого Кулака, 10 извергов из клана Анго\'рош и 10 пожирателей душ из клана Анго\'рош и вернитесь к темному охотнику Денжаю в Забра\'джин.', '$N, твоя победа над кланом Анго\'рош – большой праздник для нас! Интересно, много ли времени пройдет, прежде чем эти кровожадные огры отыщут себе нового вождя?$B$BВпрочем, неважно. Мы будем готовы отразить их нападение!', NULL, NULL, NULL, 'Властитель Кровавый Кулак убито', 'Изверг из клана Анго\'рош убито', 'Пожиратель душ из клана Анго\'рош убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9824, 'Колебания тайной магии', 'Я пытаюсь получить отпечаток энергии Каражана... Разумеется, для своего собственного исследования. К сожалению, здесь мне не удается ничего уловить. Если бы я мог добраться до источника подземных вод, мой кристалл принимал бы сигналы без помех.$B$BЯ слышал, что в подземельях под нами есть источник с колодцем и целое подземное озеро. Правда, это место кишит призраками, а я уже не в том возрасте, чтобы с ними сражаться. Что скажете насчет того, чтобы помочь старику – спуститься в подземелье и задействовать гадальный кристалл $gсамому:самой:?', 'Активируйте кристалл ясновидения Аметистового Ока рядом с подземными источниками вод в Хозяйском погребе и вернитесь к верховному магу Альтуру, находящемуся у входа в Каражан.', 'Результаты ни о чем хорошем не говорят, $N. Каражан должен излучать потоки тайной магии... Вместо этого мы наблюдаем полную тишину. Никаких сигналов. Вообще ничего. За исключением очень слабого демонического эха.$B$BЭто плохие новости, $N.', 'Как там замеры энергии, $N? Вам удалось их провести?', NULL, NULL, 'Показания у колодца в подземелье', 'Показания у подземного пруда', 'Кристалл ясновидения Аметистового Ока (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9825, 'Неустанный труд', 'Как вы могли заметить, снаружи стен Каражана блуждают призраки. Почему и как они там возникли, неизвестно, и это очень меня беспокоит!$B$BДоставьте мне одну из призрачных сущностей, чтобы я мог изучить ее. В Каражане много секретов, $N, и я полон решимости раскрыть их все.', 'Принесите 10 призрачных сущностей верховному магу Альтуру, находящемуся у входа в Каражан.', 'Поразительно. Теперь я смогу изучить эти сущности, $N. Спасибо вам за помощь.', 'Удалось собрать сущности призраков, $C?', NULL, NULL, 'Призрачная сущность', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9826, 'Вести из Даларана', 'Все это не сулит нам ничего хорошего, $N. Я никогда не понимал необходимости в особой секретности, поэтому расскажу тебе немного о нас, то есть об Аметистовом Оке $B$BМы все – агенты Кирин-Тора, Совета магов Даларана. Нам было поручено следить за Каражаном и Медивом – на случай, если что-нибудь пойдет наперекосяк.$B$BЧто и случилось... причем очень скоро, после того, как Медив исчез.$B$BВ этом письме изложены все подробности моего личного расследования. Доставь его верховному магу Седрику, он тоже из Аметистового Ока. Его можно отыскать на склонах даларанского кратера.', 'Доставьте письмо Альтуруса верховному магу Седрику на окраину кратера Даларана.', 'Альтур доверил тебе такую важную информацию? Вот старый дурень!$B$BС другой стороны, дело уже сделано, так что все, что мы можем - надеяться, что ты окажешься нам полезен. Полагаю, ты не откажешься сотрудничать с нами?', 'Вы знаете об Аметистовом Оке? Кажется, мы не знакомы...', NULL, NULL, 'Донесение Альтура (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9827, 'Высохшая базидия', 'Пристально разглядев базидию, вы обнаруживаете выемки, в которых раньше, по-видимому, что-то находилось. Ком грибной ткани представляет собой загадку. Ясно, что она поражена каким-то заболеванием, но вы не понимаете, что это такое и что с ним не так.$B$BБыть может, кто-то из тех, кто лучше вашего разбирается в обитателях Зангартопи, сумеет объяснить вам, в чем дело...', 'Отнесите высохшую базидию Руаму в Телредор, что в Зангартопи. ', 'Это выглядит как базидия болотохода, но мне еще никогда не встречались базидии в таком состоянии...Я слышал, что великаны Мертвой трясины начинают вянуть, но тут дело зашло куда дальше, чем я предполагал…$B$BМертвая трясина когда-то была таким же озером, как и остальные озера на болотах, и великаны как раз там и плодились. Теперь же, когда вода отступила, им, похоже, просто негде рассеивать споры. Если так пойдет и дальше, великаны могут полностью исчезнуть...', 'Что там у тебя, $N?', NULL, NULL, 'Высохшая базидия (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9828, 'Высохшая базидия', 'Пристально разглядев базидию, вы обнаруживаете выемки, в которых раньше, по-видимому, что-то находилось. Ком грибной ткани представляет собой загадку. Ясно, что она поражена каким-то заболеванием, но вы не понимаете, что это такое и что с ним не так.$B$BБыть может, кто-то из тех, кто лучше вашего разбирается в обитателях Зангартопи, сумеет объяснить вам, в чем дело...', 'Отнесите высохшую базидию Реавижу на заставу Болотной Крысы, что в Зангартопи.', 'Это выглядит как базидия болотника, но мне еще никогда не встречались базидии в таком состоянии... Я слышал, что великаны Мертвой трясины начинают вянуть, но тут дело зашло куда дальше, чем я предполагал…$B$BМертвая трясина когда-то была таким же озером, как и остальные озера на болотах, и великаны как раз там и плодились. Теперь же, когда вода отступила, им, похоже, просто негде рассеивать споры. Если так пойдет и дальше, великаны могут полностью исчезнуть...', 'Что там у тебя, $N?', NULL, NULL, 'Высохшая базидия (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9829, 'Кадгар', 'Альтур прислал тревожные вести. Когда Каражан закрылся от всего мира, нам это не понравилось. Там работали наши агенты, а связь с ними прервалась. А теперь этот... демонический выброс. Нужно расследовать его!$B$BЕдинственные, кто мог открыть Каражан - Кадгар и Медив, - признаны умершими.$B$BМы надеемся, что Медив исчез навсегда, но вот его ученик, Кадгар, еще жив и находится в Шаттрате. Найдите его и отдайте ему письмо Альтура.', 'Доставьте письмо Альтура Кадгару в Шаттрат - город в лесу Тероккар. ', 'Аметистовое Око? Подумать только!$B$BПокажите-ка мне это письмо.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9830, 'Яд паразита', 'Когда я говорю с дренеями, у меня всегда создается впечатление, что они не ощущают связи с родной природой. Вот моих собратьев, Сломленных, многие жалеют, говорят, что они как будто что-то потеряли.$B$BНу, может быть, мы и впрямь лишились стремления к Свету, но зато пережитое сделало нас ближе к земле.$B$BМой народ способен найти применение многому, что дренеи считают за мусор. Вот взять, к примеру, яд болотных паразитов, что водятся к юго-западу отсюда. Его ведь можно использовать и на охоте, и в медицине...', 'Принесите 6 порций яда болотного паразита Пулуу в прибежище Оребор. ', 'Спасибо тебе за яд, $N! Теперь я смогу показать дренеям все, что нужно, не исчерпав при этом своих запасов.', 'Я надеюсь показать анахорету Ахуурну и другим жителям Телредора, как можно использовать яд болотного паразита. Но для этого мне потребуется удвоить свои запасы.', NULL, NULL, 'Яд болотного паразита', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9831, 'Вход в Каражан', 'Меня очень взволновали эти известия, $N, однако пробраться в Каражан будет не так-то просто.$B$BВидишь ли, когда стало ясно, что мне придется тут задержаться, я разломил ключ на три фрагмента.$B$BКаждый фрагмент я поместил в зачарованный контейнер и поместил их в места, которые на тот момент были самыми безопасными.$B$BОднако теперь нам нужно вернуть их. Первый фрагмент находится в части Аукиндона, которой завладел Совет Теней. Принеси мне этот фрагмент.', 'Пройдите в Темный лабиринт в Аукиндоне, найдите там волшебный контейнер и возьмите из него первый фрагмент ключа, после чего вернитесь к Кадгару.', 'Вы отлично справились, $N, я даже и не ожидал.$B$BЭти контейнеры защищены сильными чарами, скрывающими их от недобрых глаз. Рад видеть, что на вас эти чары не подействовали.', 'Вы нашли фрагмент, $C? Советую вам не терять времени попусту.', NULL, NULL, 'Первый фрагмент ключа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9832, 'Второй и третий фрагменты', 'Второй фрагмент я спрятал в Змеином озере, еще задолго до того, как оно получило это название. После того как озеро захватили наги и установили там гигантский сток, контейнер, скорее всего, оказался в глубине резервуара Кривого Клыка.$B$BДостать третий фрагмент будет сложнее всего, так как его я оставил в Крепости Бурь – она тогда еще принадлежала наару. Теперь крепость захватил Кель\'тас, а зал, где я оставил фрагмент, превратили в тюрьму.$B$BПринеси мне недостающие фрагменты, $N. От твоего успеха зависит очень многое.', 'Добудьте второй фрагмент ключа из волшебного контейнера в резервуаре Кривого Клыка, а третий фрагмент ключа – из волшебного контейнера в Крепости Бурь, после чего вернитесь к Кадгару в Шаттрат.', 'Вы добыли фрагменты. Что ж, это впечатляет, $N. Несомненно, вам можно доверить ключ от Каражана.$B$BОднако есть еще одна небольшая проблема.', 'Как продвигаются поиски фрагментов ключа?', NULL, NULL, 'Второй фрагмент ключа', 'Третий фрагмент ключа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9833, 'Линии связи', 'Одна из причин, по которой Икути привел нас в Зангартопь – это необходимость поддерживать связь между дренеями и Телааром в Награнде, родиной Куренай. А для этого дороги должны быть безопасны.$B$BПо пути сюда на нас то и дело нападали болотные терзатели. Мы-то отражали их нападения, но для одинокого путника они чрезвычайно опасны! Если бы тебе удалось уменьшить их численность, нашим гонцам было бы куда спокойнее.', 'Убейте 12 болотных терзателей по просьбе Пулуу из прибежища Оребор. ', 'Отличные новости! Конечно, до полной безопасности здешним дорогам пока далеко, однако же наши посланцы умны и находчивы...', NULL, NULL, NULL, 'Болотный терзатель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9834, 'Природная броня', 'Дренеев в их блестящих доспехах Макту видит за милю, даже сквозь болотный туман!$B$BМакту хочет над ними смеяться, но потом вспоминает, что они были добры к куренай, и Макту хочет показать им, как куренай делают доспехи.$B$BИз темных чешуйчатых шкур болотных твердозубов получаются самые лучшие доспехи, какие когда-нибудь носил Макту. Если $N принесет Макту несколько шкур болотных твердозубов, плавающих в глубинах Змеиного озера, Макту охотно поделится своими доспехами!', 'Принесите 8 шкур болотных твердозубов Макту в прибежище Оребор. ', 'Макту думает, это хорошие шкуры. Из них получатся отличные доспехи.$B$BКто знает? Возможно, тут хватит и на несколько доспехов для дренеев.', 'У $N есть шкуры для Макту?', NULL, NULL, 'Шкура болотного твердозуба', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9835, 'Вторжение клана Анго\'рош', 'Небольшой отряд Сломленных, который ты видишь, – посланцы из большого поселения в Награнде. Куренай, как мы себя называем – это Сломленные, которые стремятся воссоединиться со своими собратьями-дренеями.$B$BМы прибыли сюда, чтобы укрепить связи Куренай с дренеями Телредора.$B$BЕсли огры из клана Анго\'рош возьмут верх, этот храм долго не продержится. Они вырубили все крупные грибы на Болотных вырубках, и подбираются все ближе к нашему убежищу. Если ты хочешь считаться нашим другом, помоги нам бороться с этими врагами!', 'Убейте 10 огров из клана Анго\'рош и 5 шаманов из клана Анго\'рош и вернитесь к Икути в прибежище Оребор.', 'Угроза, исходящая от клана Анго\'рош, пока нейтрализована, но ясно, что просто так они не сдадутся. С тех пор как мой жизненный путь дренея завершился, я многое позабыл, но упрямство огров забывается не скоро.', NULL, NULL, NULL, 'Шаман из клана Анго\'рош убито', 'Огр из клана Анго\'рош убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9836, 'Разрешение учителя', 'Я сумел воссоздать ключ, которым пользовался, будучи учеником. С виду он вполне рабочий - в общем-то, ключ как ключ. Но если попытаться открыть им Каражан, ключ не подействует. С тем же успехом можно использовать и обычную железку.$B$BСобственно, это и есть никчемная железка. Ключ не будет работать без согласия Медива. Да, я знаю, что Медив мертв. Но это не значит, что с ним невозможно связаться.$B$BВ Азероте есть место, которое называют Пещерами Времени. Их охраняют бронзовые драконы. Проберись в пещеры, вернись в прошлое и уговори Медива дать разрешение на пользование ключом.', 'Отправляйтесь в Пещеры Времени и уговорите Медива дать разрешение на использование Восстановленного ключа.', 'Ага, точно. Я его узнаю. Ключ Кадгара... Разумеется, я еще не давал ему никакого ключа.', 'Кто ты и что тебе нужно?', NULL, NULL, 'Восстановленный ключ ученика (Прилагается)', 'Разрешение учителя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9837, 'Возвращение к Кадгару', 'Похоже, я помню кое-что о грядущих событиях, связанных с тобой и этим ключом.$B$B*Медив смотрит на вас так, будто увидел привидение.*$B$BТебя ждут нелегкие времена, $N. Будем надеяться, у тебя хватит сил вынести все испытания.$B$BЧто касается ключа, то я должен отдать его Кадгару, когда он придет ко мне. О таком ученике можно только мечтать.$B$BЯ так понимаю, тебе понадобится твой собственный ключ.$B$B*Медив роется в карманах своего одеяния и вручает вам ключ.* $B$BВот он. Желаю тебе удачи, $C.', 'Вернитесь в Шаттрат к Кадгару и покажите ему хозяйский ключ. ', 'Его собственный ключ? Невероятно!$B$BЯ не чувствую никаких возмущений в нашей временной линии, так что, думаю, это действительно произошло. Дороги назад нет, $N. Этот ключ твой и только твой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9838, 'Аметистовое Око', 'На тебя была возложена великая ответственность, $N. Если знаки, которые удалось разглядеть Аметистовому Оку, истинны, то ты $gдолжен:должна: помочь им.$B$BНесмотря на все мои расхождения с Седриком, я признаю, что люди вроде Альтура ведут очень важную работу. Но будь $gосторожен:осторожна: - они могут тебя использовать. Всегда помни о том, что ключ принадлежит тебе, а не им. Но если в Каражане и правда таится опасность, то именно они лучше всего научат, как ее одолеть. Возвращайся к Альтуру и помогай ему, чем сможешь.', 'Поговорите с верховным магом Альтуром, который находится снаружи Каражана.', 'Я послал вас, чтобы доставить письмо, а вы вернулись с ключом от этого места? Похоже, в вас скрыто нечто большее, чем кажется на первый взгляд, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9839, 'Властитель Кровавый Кулак', 'Основа любого огрского клана – это его вождь. Лишившись вождя, клан Анго\'рош распадется, и огры примутся драться между собой, выясняя, кто теперь будет главным.$B$BХотя здесь немало разных огров, их основные силы сосредоточены в крепости Анго\'рош на северо-западе. Крепость представляет собой пещеру на небольшом островке, на который с болота можно попасть по стволу поваленного гриба.$B$BСтупай туда и одолей властителя Кровавого Кулака! Это обеспечит нам давно заслуженную передышку.', 'Убейте властителя Кровавого Кулака и 10 извергов из клана Анго\'рош по просьбе Икути. Выполнив задачу, вернитесь в прибежище Оребор.', 'Наконец-то! Мы благодарим тебя за помощь – благодаря тебе наше положение упрочилось. Я пошлю весть о твоих деяниях в куренайский город Телаар в Награнде. У наших народов еще не раз будет случай сражаться плечом к плечу!', NULL, NULL, NULL, 'Властитель Кровавый Кулак убито', 'Изверг из клана Анго\'рош убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9840, 'Оценка ситуации', 'Теперь, когда мы - вернее, ты -$gнашел:нашла: путь обратно в Башню Медива, нам надо в первую очередь попытаться узнать, что же происходит внутри.$B$BОдна из наших агентов, которой удалось проникнуть в Каражан, вела закодированную запись событий. К несчастью, сразу после того, как Каражан закрылся, мы узнали о ее смерти. На нас работал Корен, кузнец из Каражана. Хотя он не член Аметистового Ока, думаю, он поможет нам отыскать записи Кеанны. Ты найдешь его внутри.', 'Найдите Корена в Каражане.', '*Корен смотрит на вас непонятным взглядом.*$B$BЯ ничего не знаю про Аметистовое Око. Я всего лишь кузнец.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9841, 'Поделом гнусным тварям!', 'Что за адское жужжание! Просто работать невозможно! Слышишь?$B$BЯ от него буквально с ума схожу. И, главное, я ведь знаю, кто это жужжит! Это все проклятые болотные паразиты! И шум всегда доносится с юго-западной стороны от деревни.$B$BЭти твари такие здоровенные, что их не прихлопнешь, не раздавишь, и отмахнуться от них тоже не получится. С ними надо воевать всерьез! В общем, меня не волнует, как ты это сделаешь, $N, главное - заставь их заткнуться!', 'Убейте 8 болотных паразитов и вернитесь к Гамбаринке в Забра\'джин. ', 'Так я и думал. Разница сразу заметна. Наконец-то я снова смогу взяться за работу! Спасибо тебе большое! Если тебе снова понадобятся мои товары, не забудь про Гамбаринку!', NULL, NULL, NULL, 'Болотный паразит убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9842, 'Острейшие резцы', 'Болотная сырость не пошла на пользу моим железным инструментам. Я уже зарекся их точить. Работа по дереву не идет совершенно.$B$BОднако обнаружилось, что зубы болотных терзателей, обитающих к югу и к западу от города, куда острее любых стальных резцов, какими я когда-либо владел! Кроме того, они не тупятся и не боятся ржавчины. Правда, вделывать их в рукоятку не так-то просто, но я, кажется, решил и эту проблему. Так что приноси мне их зубы, я буду очень признателен.', 'Принесите 10 зубов болотного терзателя Гамбаринке в Забра\'джине. ', 'О, ну, этого мне хватит надолго! Мне кажется, кое-кто догадывается, в чем дело. У меня уже несколько раз спрашивали, не продам ли я свои резцы. Может быть, продавать их на сторону окажется даже выгоднее, чем мастерить что-то самому...', 'Ну что, удалось тебе раздобыть резцы для меня?', NULL, NULL, 'Зуб болотного терзателя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9843, 'Записи Кинны', 'Кого ты там искал, повтори-ка еще разок? Кинну?$B$BКогда-то я встречал кого-то с похожим именем. Она останавливалась наверху, в Гостевых залах. Я не должен был болтать об этом, да?$B$BКак ты $gговорил:говорила:, ты из Аметистового Ока? Никогда них не слыхал.$B$BА теперь я бы вернулся к своей работе, если не возражаешь.$B$B*Похоже, Корен уже забыл о вас.*', 'Найдите Гостевые залы в Каражане, а в них - записи Кеанны, и доставьте их верховному магу Альтуру.', 'Тебе удалось найти записи. Я уверен, они содержат информацию, которая даст ответ на наши вопросы, $N.', 'Записи Кеанны... Вам удалось их найти?', NULL, NULL, 'Записи Кинны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9844, 'Присутствие демонов', 'Последние несколько записей Кеанны подтверждают наши предположения, что в Каражан пробрались демоны.$B$BЕй удалось засечь прибытие агента Пылающего Легиона. По ее словам, он обосновался на самом верху башни.$B$BНа этом ее записи обрываются.$B$BКаражан - это очень важное для нас место, $C. Это портал в бездну, маяк, сияющий для других миров. Я не хочу даже думать о том, что может случиться, если он попадет не в те руки. Необходимо остановить демонов. А ключ от Каражана, $N, есть только у вас.', 'Верховный маг Альтур просит вас уничтожить демона на вершине башни Каражана.', 'Вам удалось это сделать! Наши данные снова пришли в норму!$B$BНеобходимо сообщить новости Седрику. Он будет просто поражен.', 'Я боюсь услышать ваш ответ, $N. Что происходит в Каражане?', NULL, NULL, 'Демон уничтожен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9845, 'Не распугивайте рыбу!', 'Как же хорошо наконец очутиться в месте, где есть вода, после всех этих пустынь полуострова Адского Пламени! А то я уж боялась, что тут, в Запределье, и рыбку толком половить негде.$B$BНо, оказывается, я все-таки не зря тащила с собой снасти. Рыбалка здесь отменная, только вот болотные твердозубы из Змеиного озера жизнь отравляют страшно.$B$BМало того, что рыбу распугивают, так еще и наживку с крючка срывают. Не столько ловишь, сколько насаживаешь новых живцов!', 'Убейте 10 болотных твердозубов и вернитесь к Зурджайе в Забра\'джин. ', 'Мне не терпится поскорее вернуться к рыбалке! Наконец-то я принесу в город полное ведро рыбы! А то Гамбаринка меня уже засмеял.', NULL, NULL, NULL, 'Болотный твердозуб убито', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9846, 'Духи Дикотопи', 'Говорят, что самое могущественное племя Заблудших на болотах, племя Дикотопи, владеет могучей магией. Может быть, это и вранье, но я не могу пренебрегать ничем, что поможет мне управлять духами этого мира.$B$B$N, отыщи мистиков, охотников и друидов Дикотопи, и захвати их тотемы. Все, что мне надо знать, станет понятно по их резьбе.', 'Принесите 10 тотемов-хранителей Дикотопи ясновидящей Джаниди в Забра\'джин.', 'Хм... Похоже, здесь наличествуют духи двух видов: в змеином обличье и в облике птицы. Разумеется, птице ни один уважающий себя тролль из племени Черного Копья поклоняться не станет. Духи птиц слабы и капризны. Оставим их в удел племени Амани.$B$BНо змея, $N, змея обладает значительным могуществом! Я займусь изучением этого духа.', 'И где тотемы?', NULL, NULL, 'Тотем-хранитель Дикотопи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9847, 'Дух-союзник?', 'Нужно выяснить, велико ли могущество змеиного духа Дикотопи, и можно ли его подчинить нашей воле. Только представь, что можно было бы совершить, повелевая могуществом духа Запределья!$B$BВозьми с собой этот тотем и проберись к подножию лестницы, ведущей в руины Боха\'му. Установи тотем на землю, остальное он сделает сам. Дух не сможет явиться, пока кто-нибудь не воспользовался тотемом.', 'Отнесите тотем Дикотопи к подножию лестницы руин Боха\'му и установите его на землю. Расскажите о том, что вы видели, ясновидящей Джаниди в Забра\'джине.', '<Вы рассказываете провидице Джаниди о том, что произошло, когда вы использовали тотем.>$B$BДух напал на тебя? Должно быть, он теснее связан с этими Заблудшими, чем я думала... Значит, его не удастся заставить служить мне, не применяя значительных усилий... Придется искать другой источник могущества!', 'Удалось ли тебе призвать духа Дикотопи?', NULL, NULL, 'Призовите змеиного духа', 'Тотем Дикотопи (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9848, 'Тайны Остротопи', 'Насекомые, насекомые! Болота кишат насекомыми, и мои товарищи, похоже, помешались на них.$B$BНу, а с меня довольно! Меня интересует куда более важный вопрос. К западу отсюда есть деревня Заблудших, которые называют себя кланом Остротопь.$B$BВсе они – высокопрофессиональные убийцы. Я обнаружил, что они изготовляют и применяют особенно действенный сорт яда. И мне до смерти хочется узнать побольше об этом яде. Однако для этого нужно раздобыть рецепт и фиал с образчиком...', 'Принесите справочник по ядам Остротопи и фиал яда Остротопи Тимоти Даниэльсу в прибежище Оребор.', '<Тимоти бросается листать справочник.>$B$BОни используют в качестве основного компонента кисейницу? Ерунда какая-то. Кисейница же совершенно не ядовита!$B$BВводить в состав яда кисейницу – это все равно, что разбойнику сражаться двумя палицами. Можно, конечно, но какой смысл?! Решительно не понимаю...$B$B<Тимоти прочищает горло.>$B$BВ общем, спасибо большое. Попробую приготовить этот яд, как только будет время...', 'Надеюсь, твои поиски в деревне Остротопь не были безрезультатными? Мне не терпится разрешить эту загадку!', NULL, NULL, 'Справочник по ядам Остротопи', 'Фиал яда Остротопи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9849, 'Сорвать личину', '<Гордауг отламывает кусок черного камня со своей спины.>$B$BТеперь в твоих руках сила гнева земли. Возьми камень Гордауга и метни в ядовитую скалу. Разбей их панцири – открой правду. Убей приспешников захватчика и узнай его имя.$B$BТы найдешь расколотых грохотунов на краю земли. На юго-западе.', 'Убейте 30 прислужников Гурока. ', 'ГУРОК! Гурок предал стихии!', 'Гордауг хочет свой камень назад.', NULL, NULL, 'Прислужник Гурока убито', 'Камень Гордауга (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9850, 'Охота на копытней', 'Я уже убедился, что ты $gспособен:способна: разыскать и завалить обыкновенного копытня, но их самцы гораздо опаснее!$B$BУбей двенадцать самцов копытня, и тогда уже поговорим о твоем охотничьем мастерстве.$B$BЭти звери обитают в центральных районах Награнда, к западу и югу отсюда.', 'Убейте 12 самцов копытня и вернитесь к Хемингу Эрнестуэю в его охотничий лагерь в Награнде.', 'Очень даже неплохо.$B$BИз тебя может выйти хороший охотник, малыш. Пора дать тебе шанс позабавиться по-настоящему.', NULL, NULL, NULL, 'Самец копытня убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9851, 'Охота на копытней', 'Бантар – самая свирепая и самая неуловимая из всех копытней в Запределье. И самая косматая.$B$BГоворят, она сейчас отвела свое стадо на Поле Духов близ Ошу\'гуна.$B$BХочешь, чтобы я убедился в твоем охотничьем мастерстве? Принеси мне ее рог!', 'Добудьте рог Бантар и отнесите его Хемингу Эрнестуэю в лагерь Эрнестуэя в Награнде.', 'У тебя получилось! Ты убил саму Бантар! Впрочем, я в тебе не сомневался, $N.$B$BВот, возьми. Ты заслужил награду.', 'Домашний очаг, супруга под боком, досужие сплетни – эти обывательские радости не для нас. Мы охотимся за крупной дичью и рискуем при этом жизнью.', NULL, NULL, 'Рог Бантар', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9852, 'Опасный спорт', 'Клыкач – королева животного царства Награнда. Гигантская самка элекка, равных которой нет на свете!$B$BОдно ее имя наводит страх, и ее не зазорно бояться. Хол\'стяк, Потрошитель и Бантар – жалкие мошки по сравнению с ней. Говорят, ее можно найти на отвесной скале неподалеку от Ошу\'гуна, на юго-западе отсюда. Если тебе хватит смелости, принеси мне сердце королевы элекков.$B$BУ тебя есть родные? Не хочешь написать им записку? Если ты не вернешься... а скорее всего, так и будет... я обязательно передам ее безутешным родственникам.', 'Принесите сердце Клыкач Хемингу Эрнестуэю в его лагерь в Награнде. ', '$N! Отрадно видеть тебя живым и невредимым!$B$BТеперь уж никто не усомнится, что ты достоин войти в ряды лучших охотников! Все остальные либо в страхе бежали, либо погибли, затоптанные свирепой зверюгой. Но ты подтвердил свое мастерство охотника, проявив ум, хитрость, смелость и решимость.$B$BВот, возьми этот подарок и знай: я всегда буду рад, если ты пожелаешь присоединиться к моей охотничьей партии!', 'Нет ничего постыдного в том, чтобы признаться, что тебе не хватает смелости выйти на самого могучего и страшного зверя на этой земле, $N.', NULL, NULL, 'Сердце Клыкач', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9853, 'Гурок Узурпатор', 'Надо вызвать Гурок. Ты вызвать Гурок и убить.$B$BТы иди в северо-запад, холм Боевого Молота, и ищи место, где огр молиться Гурок. Черепа огров Боевого Молота клади на алтарь Гурок. Только потом Гурок придет. Семь черепов.$B$BБудешь $gживой:живая:, приноси Гордаугу земляную голову Гурока. Гордауг разбить голову.$B$B<Гордауг топает так, что трясется земля.:', 'Убейте Гурока Узурпатора и принесите его голову Гордаугу к Трону стихий.', '<Гордауг вгрызается в голову Гурока, размалывая камень почти что в пыль.>$B$BВласть Гурока кончилась. Свобода духам земли. Теперь все спать. Награду ты получать!', 'Гордауг поедать силу Гурок.', NULL, NULL, 'Голова земли Гурока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9854, 'Охота на ветрухов', 'Ты тоже живешь лишь охотой, $C? Тоже ищешь покоя, что нисходит на душу охотника, когда он выслеживает добычу? Знаешь ли ты, что такое трепет перед последними ударами сердца сраженного зверя? Я помогу тебе узнать все тонкости нашего ремесла!$B$BНагранд – край, исполненный жизни. Нетронутый островок жизни посреди этого опустошенного мира. Принеси мне убитых тобою ветрухов, и тогда мы продолжим разговор.$B$BВетрухов найти легко – они бродят повсюду вокруг нашего лагеря.', 'Убейте 12 ветрухов и вернитесь к Фитцу в охотничий лагерь Эрнестуэя в Награнде.', 'Каждый прожитый день – это великий дар. И этим даром надо воспользоваться в полной мере. И, может быть, уже завтра наши шаги по земле станут еще стремительнее и легче. А наши руки протянутся немного дальше в извечном стремлении схватить ускользающую мечту.', NULL, NULL, NULL, 'Ветрух убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9855, 'Охота на ветрухов', 'Только $gдостойнейший:достойнейшая: из достойнейших сможет приблизиться к великой добыче! Пока ты еще не $gготов:готова:, я буду тебя направлять.$B$BСуществует еще один вид ветрухов – свирепее и опаснее прочих. Разыщи прожорливых ветрухов и испытай свою храбрость. Ты найдешь их в самом сердце Награнда, к западу и юго-западу отсюда.', 'Добудьте 12 прожорливых ветрухов и вернитесь к Фитцу в лагерь Эрнестуэя в Награнде.', 'Ты еще раз подтвердил свое мастерство, $C. Теперь тебе предстоит охота на самого свирепого и лютого ветруха.', NULL, NULL, NULL, 'Прожорливый ветрух убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9856, 'Охота на ветрухов', 'Теперь ты $gготов:готова:, $C. $gГотов:Готова: предстать перед матерью всех ветрухов, самой Потрошительницей! Закон чести требует, чтобы ты $gдал:дала: ей возможность сразиться с тобой, после того как ты $gлишил:лишила: жизни стольких ее детей! Ищи ее среди больших ветрухов далеко к западу отсюда.$B$BЕсли ты выйдешь $gпобедителем:победительницей: из этой схватки, принеси мне глаз Потрошительницы.', 'Принесите глаз Потрошительницы Фитцу в охотничий лагерь Эрнестуэя в Награнде.', 'Глаз - как живой! Как ты считаешь, может быть, Потрошительница по-прежнему заглядывает тебе прямо в душу?$B$B$N, теперь можешь считать, что тебя приняли в ряды лучших охотников. И ты приблизился еще на шаг к величайшей добыче на этой земле, гигантскому элекку!$B$BТы заслужил достойную награду.', 'Ты уже сразился с Потрошительницей?', NULL, NULL, 'Глаз Потрошительницы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9857, 'Охота на талбуков', 'Сегодня я вряд ли пойду на охоту. Не желаешь меня заменить?$B$BЯ сказал Хемингу, что постараюсь добыть побольше талбуков, которые здесь встречаются на каждом шагу. Лучше всего охотиться на самцов. Кстати, я видел, как они собирались в ближайшей роще.$B$BНу что? Поохотишься за меня?', 'Убейте 12 талбуков-самцов и возвращайтесь к Гарольду Лейну в лагерь Эрнестуэя в Награнде.', 'Ты славно управился... (кашляет)...с этими талбуками, $C. Но мне кажется, ты способен на большее. У меня есть для тебя еще одно задание...', NULL, NULL, NULL, 'Талбук-самец убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9858, 'Охота на талбуков', 'Эта проклятая царапина меня доконает. Не хочешь еще раз... (кашляет)... меня заменить?$B$BНа этот раз твоя цель – шипоеды. Они умнее и хитрее обычных талбуков, так что их просто так не возьмешь. Ищи их... (кашляет)... в рощах в центральном Награнде, к западу и югу отсюда.$B$BИди. А потом возвращайся с добычей... (кашляет)... пусть Хеминг увидит, на что ты $gспособен:способна:. А за меня не волнуйся, со мной все будет в порядке.', 'Убейте 12 талбуков-шипоедов и возвращайтесь к Гарольду Лейну в лагерь Эрнестуэя в Награнде.', '*кашляет* Поздравляю, $N! Ты все-таки справился с ними! Значит, у нас остается... *кашляет*... всего одно дело.', NULL, NULL, NULL, 'Талбук-шипоед убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9859, 'Охота на талбуков', '*Сильно кашляет.*$B$BЗа меня... *кашляет*... не волнуйся. Со мной все будет в порядке. Это просто... *кашляет*... царапина.$B$BВсе равно... *кашляет*... в любом случае тебе пришлось бы... *кашляет*...меня подменить... *кашляет*... еще раз.$B$BТебе надо будет найти Хол\'стяка, короля... *кашляет*... талбуков. Я бы советовал тебе... *кашляет*... взять с собой пару-тройку друзей.$B$BПринеси мне копыто Хол\'стяка... *кашляет*... в подтверждение, что у тебя все получилось.$B$BТы найдешь его и его стадо... *кашляет*...на западе Награнда.', 'Добудьте копыто Хол\'стяка и принесите его Гарольду Лейну в охотничий лагерь Эрнестуэя в Награнде.', 'Ничего себе! Это и вправду копыто Хол\'стяка!$B$BПохоже, мне уже лучше. Вот, держи подарок. Ты его заслужил!', '<Гарольд смотрит на вас и улыбается слабой бледной улыбкой.>$B$BТы принес... *кашляет*.. копыто?', NULL, NULL, 'Копыто Хол\'стяка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9860, 'Новое направление', 'Немедленно возвращайтесь к Седрику, $N. Ваша помощь Аметистовому Оку будет вознаграждена. $B$BМожете думать о нас и о нашей организации что хотите, $C, но об обретении благосклонности верховных магов Даларана вы не пожалеете.', 'Поговорите с верховным магом Седриком на окраине кратера Даларана. ', 'Альтур рассказал мне, что случилось, $N, но это еще не все. Если Каражан так и останется запечатанным от пришельцев извне, захватить нас врасплох станет для Легиона делом времени.$B$BЕсли только вы не примете на себя ответственности, наложенной на вас самой судьбой.$B$B*Седрик протягивает вам раскрытую ладонь, на которой лежит знак с символом Аметистового Ока.*$B$BЧто скажете, $N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9861, 'Вой-Ветер', 'Эта аморфная масса воздушной стихии говорит с вами на языке, которого вы не понимаете. Скорее всего, это язык стихий – калимаг. Может быть, у Трона стихий найдется кто-то, кто подскажет вам, что это за странная находка.', 'Разыщите у Трона стихий кого-нибудь, кто знает язык калимаг, и покажите ему или ей Вой-Ветра.', 'Это крик боли и призыв о помощи, $R. Некая внешняя сила пытается разрушить стихии.', 'Дай это мне! Быстро!', NULL, NULL, 'Вой-Ветер (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9862, 'Разлагатели Темной Крови', 'Племя Темной Крови ловит и пытает духов воздуха! Мне горько об этом говорить, ведь они – мои сородичи. Их клан продался подлому Мусел\'еку, владыке болот из клана Кривого Клыка.$B$BДух воздуха утверждает, что разлагатели из племени Темной Крови ловят его сородичей и используют их, чтобы сеять хаос в рядах стихий. Насколько я знаю, недавно они захватили заставу Солнечного Источника, поселение орков к юго-западу отсюда, и используют магию стихий, чтобы потревожить озеро. Найди разлагателей и убей их.', 'Убейте 5 разлагателей из племени Темной Крови по просьбе повелителя стихий Морха, находящегося у Трона Стихий.', 'Ты своими глазами видел, как они управляют стихиями? Ветер послушен их воле?$B$B*Моргх на секунду задумывается.*$B$BМне это очень не нравится, $N. Надо посоветоваться с остальными.$B$BМы благодарны тебе за помощь, $N. Может быть, тебе стоит вернуться в свою деревню и проверить, нет ли еще каких сведений о Падших Темной Крови и их гнусных планах.', NULL, NULL, NULL, 'Разлагатель из племени Темной Крови убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9863, 'Вражеские святыни', 'Теперь, когда мы остались без предводителя, мы открыты для нападения со всех сторон. Эти мерзавцы из клана Мертвой Крови выбрали самый что ни на есть \"подходящий\" момент для нападения!$B$BЗа последние несколько дней нам пришлось выдержать целых пять атак Сломленных. Они захватили наше единственное, помимо Гарадара, укрепленное владение в этих краях – Заставу Солнечного Источника.$B$BМы должны показать этим мерзавцам, что нас так просто не запугаешь! Проникни в лагерь этих идолопоклонников и укради их поганые идолы. Представляю, какой это будет для них удар!', 'Принесите 10 идолов Темной Крови предсказателю Куркашу в Гарадар. ', 'Ты дал надежду Сынам Молнии, $N. Увы, наш вождь не способен более защитить свой народ, но быть может, найдутся герои, которые спасут нас... такие, как ты.', 'Нам не хватит сил для набега, поэтому мы попросили тебя о помощи.', NULL, NULL, 'Идол Темной Крови', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9864, 'Пропавший отряд', 'После набега племени Темной Крови группа наших юнцов решила им отомстить. Мы пытались их остановить, но ярость оказалась сильнее. Прошла уже неделя, а от наших детей нет ни единой весточки.$B$BПрошу тебя, $r, отыщи их. Они еще очень юные – куда им тягаться со свирепыми дикарями?!$B$BОни направились по западной дороге. Поезжай по ней и попытайся обнаружить следы наших юных отпрысков.$B$BИ еще одно, $N, если ты дорожишь своей жизнью, обходи Халаа стороной. Там идет война.', 'Отыщите пропавший гарадарский отряд. ', 'Я знаю предания своего народа. В них говорится, что когда-то мы были великими воинами…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9865, 'Да, были воины в наше время...', 'Я не знаю, кто ты, $gстранник:прекрасная госпожа:, но молю о помощи. Мне горько говорить об этом, но я – последний из орков, оставшихся здесь.$B$BЯ ощутил что-то такое, чего не чувствовал прежде... Я... я жажду мести. Кровь за кровь. Ты когда-нибудь $gчувствовал:ощущала: что-либо подобное? Меня охватывает непреодолимое желание схватить топор и сокрушить им моих врагов. Я готов сражаться до тех пор, пока рука не опустится в изнеможении.$B$BЗастава Солнечного Источника лежит к югу отсюда. Там ты найдешь наших врагов... Убей их... Убей их всех...', 'Убейте 20 падальщиков из племени Темной Крови и 10 налетчиков из племени Темной Крови.', '<Саурфанг смотрит на вас.>$B$BДа, я чую запах крови! Жаль, я не смог сам поучаствовать в этой битве. Тебе есть чем гордиться. Это честь для меня – знать, что ты совершил этот подвиг ради моего народа.$B$BКто ты? Откуда? В вашей стране есть герои, подобные тебе?', 'За каждого убитого ими сородича пусть погибнут десять моих врагов!', NULL, NULL, 'Падальщик из племени Темной Крови убито', 'Налетчик из племени Темной Крови убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9866, 'Он будет странствовать по земле...', 'Окажи мне последнюю услугу, $N. Я не хочу возвращаться в Гарадар. Я убежден, что судьба уготовила мне иной путь, на котором меня ждут великие свершения.$B$BПожалуйста, найди предсказателя Корхука и скажи ему, что я не вернусь. Я не могу повернуть назад. Я должен странствовать по земле... Он поймет.', 'Доставьте известие предсказателю Корхуку в Гарадар. ', '<Предсказатель Корхук смотрит себе под ноги, погруженный в раздумья. Потом кивает и вытирает скупую слезу.>$B$BСын – весь в отца... И пусть духи смилостивятся над теми, кто встанет у него на пути.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9867, 'Главари Темной Крови', 'За последние недели мы потеряли многих друзей.$B$BДесят$Nиями мы боролись с ограми Награнда, но теперь нам угрожает новый враг. Сломленные из племени Темной Крови напали на заставу Солнечного Источника на юго-западе. Все орки были убиты или бежали из города.$B$BМногие считают, что врагов следует убивать всех без разбора, но я уверен, что начать надо с их главаря. Не знаю, кто там у них верховодит, но подозреваю, что узнать его будет нетрудно.', 'Принесите предсказателю Маргадешу в Гарадар голову Ортора Темной Крови.', 'Значит, я смотрю в лицо нашего врага? Я прикажу насадить эту голову на кол и выставить над воротами Гарадара. Если они соберутся напасть на нас снова, пусть видят, к чему приводят столь необдуманные шаги…', 'Принеси мне голову их вождя, $N.', NULL, NULL, 'Голова Ортора Темной Крови', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9868, 'Тотем К$Nа', 'Спасибо тебе, $gчужестранец:чужестранка:. Если бы не ты, эти твари наверняка прикончили бы меня.$B$BМеня взяли в плен три ночи назад во время ночного рейда на Гарадар. За время своего пребывания здесь я выяснил ужасную вещь: оказывается, эти дикари собираются отыскать тотем К$Nа! Мы никак не можем допустить, чтобы тотем попал в руки племени Темной Крови!$B$BТы $gдолжен:должна: помочь мне бежать отсюда. Если я не доберусь до Гарадара – ты, $gчужестранец:чужестранка:, расскажешь Гаррошу о том, что здесь произошло...', 'Помогите пленному маг\'хару бежать с заставы Солнечного Источника. Расскажите Гаррошу в Гарадаре обо всем, что вам удалось узнать.', 'Какая разница? Великая мать умирает. Нет смысла жить дальше...', NULL, NULL, NULL, 'Помогите пленному маг\'хару бежать', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9869, 'Трон стихий', 'Приветствую тебя, $r. Я – Локи, повелитель стихий из Служителей Земли. Я пришел в Телаар, чтобы рассказать куренай о состоянии стихий.$B$BМогу я тебя попросить об одной небольшой услуге? Ты не $gмог:могла: бы сходить к Трону стихий – это в северных холмах Награнда, за озером Небесной Песни, – и сообщить повелительнице стихий Шарвак, что я благополучно добрался до Телаара? Без вознаграждения ты не останешься. Я уверен, что Шарвак предложит тебе компенсацию за беспокойство.', 'Поговорите с повелительницей стихий Шарвак у Трона стихий. ', 'Большое спасибо за новости. Не желаешь ли ты оказать содействие Служителям Земли? Стихии находятся в движении. Сейчас мы не откажемся от любой помощи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9870, 'Трон стихий', 'Приветствую тебя, $r. Я – повелитель стихий Ялхан из Служителей Земли. Я пришел в Гарадар, чтобы проинформировать маг\'харов о состоянии стихий.$B$BМогу я попросить тебя об одной небольшой услуге? Ты не $gмог:могла: бы сходить к Трону стихий – это в северных холмах Награнда, за озером Небесной Песни – и сообщить повелительнице стихий Шарвак, что я благополучно добрался до Гарадара? Без вознаграждения ты не останешься. Я уверен, что Шарвак предложит тебе компенсацию за беспокойство.', 'Поговорите с повелительницей стихий Шарвак у Трона стихий. ', 'Большое спасибо за новости. Не желаешь ли ты оказать содействие Служителям Земли? Стихии находятся в движении. Сейчас мы не откажемся от любой помощи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9871, 'Захватчики из племени Темной Крови', 'На пергаменте нарисована грубая и схематичная карта Награнда. Телаар обозначен большим красным \"X\". Похоже, племя Темной Крови готовит вторжение в город. Передайте планы вторжения племени Темной Крови Арехрону в Телааре.', 'Передайте планы вторжения Темной Крови Арехрону в Телаар, что в Награнде.', '*Арехрон бьет кулаком по ладони.*$B$BОртор... Гнусный предатель!', 'Что это?', NULL, NULL, 'Планы вторжения Темной Крови (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9872, 'Захватчики из племени Темной Крови', 'На пергаменте нарисована грубая и схематичная карта Награнда. Гарадар обозначен большим красным \"X\". Похоже, племя Темной Крови готовит вторжение в город. Передайте планы вторжения племени Темной Крови Гаррошу в Гарадаре.', 'Передайте планы вторжения Темной Крови Гаррошу. ', '<Гаррош мнет карту и бросает ее в огонь.>$B$BКакая разница? Это уже далеко не новость. Они давно нас атакуют. Мы пока держимся, но...$B$BНеужели ты не понимаешь? Все кончено... Великая Матерь Гейя умирает.', 'Что это?', NULL, NULL, 'Планы вторжения Темной Крови (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9873, 'Ортор, мой старый друг...', 'Эти планы вторжения составлял мой давний знакомый. Ортор Темная Кровь, некогда знатный Сломленный, посвященный в науку стихий, теперь сделался лизоблюдом Мусел\'ека, этого царя пиявок.$B$BИз плана следует, что они захватили заставу Солнечного Источника, деревушку орков к северо-западу отсюда.$B$BОтправляйся на заставу Солнечного Источника и избавь мир от Ортора. Так будет лучше для всех...', 'Арехрон из Телаара в Награнде поручил вам убить Ортора Те$Nю Кровь. ', 'Говоришь, тысяча мертвых орков? Что могло вызвать столь дерзкое вторжение на орочьи земли? Я рад, что с этим мерзавцем покончено, но впереди нас ждет еще много серьезных дел.', 'Имей в виду, $N: Ортор - могущественный шаман.', NULL, NULL, 'Ортор Темная Кровь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9874, 'Остановить заразу', 'Мне только что стало известно о катастрофе поистине устрашающего масштаба, $N. Эти мерзавцы из племени Темной Крови захватили орочью заставу Солнечного Источника... это к северо-западу отсюда... перебили всех тамошних жителей, а тела принялись сбрасывать в озеро Солнечного Источника. Если все эти тела начнут разлагаться в озере, наш главный источник пресной воды в этой области будет отравлен.$B$BЯ понимаю, что это работа не из приятных, но ее надо сделать. Возьми этот зачарованный факел, иди на заставу и сожги все трупы орков...', 'Сожгите 10 трупов жителей заставы Солнечного Источника с помощью факела жидкого огня. Когда исполните поручение, верните факел Отонбу Ведуну.', '<Отонбу вздыхает.>$B$BПосле того что мы сделали, на ближайшие десять лет можно оставить всякую надежду заключить с орками мир. Но, во всяком случае, у нас будет шанс прожить это десят$Nие. А если бы мы не уничтожили эти тела... даже страшно подумать, чем бы все это закончилось!', 'Орки нас не поймут. Но мы должны это сделать. Во имя общего блага – и орков, и Сломленных.', NULL, NULL, 'Сожгите тела жителей заставы Солнечного Источника', 'Факел жидкого огня (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9875, 'Неизвестный науке вид', 'А вот это растение Лоранна, очевидно, упустила из виду. Вы уверены, что обнаружили вид, еще не описанный Лоранной. Стоит показать это растение Лоранне и посмотреть, что она скажет.', 'Принесите неизвестный науке вид Лоранне Тар\'велл в Кенарийский приют в Зангартопи.', 'Новый вид! Точно?$B$B<Лоранна листает свои записи и таблицы.>$B$BОтличная работа, Ондумм! Да, нам еще только предстоит занести этот вид в наши справочники. Как тебе нравится название \"Ондуммрий пурпурнолистный\"? Неплохо звучит, а?', 'Ты хочешь мне что-то показать?', NULL, NULL, 'Неизвестный науке вид (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9876, 'Провалившийся рейд', 'Я отправила небольшой отряд наших друидов, чтобы исследовать обнаруженную тобой трубу в Змеином озере. Я рассчитывала на их скорое возвращение. Нужно ли говорить, что они не вернулись до сих пор?$B$BТы – $gодин:одна: из самых способных наших союзников. Пожалуйста, отыщи их и выясни, что с ними стало.', 'По просьбе Исиэли Песни Ветра отыщите следы друидов из Кенарийской экспедиции у входа в Резервуар Кривого Клыка , что в Зангартопи.', 'Слава Кенарию, что ты здесь! Я не могла выбраться наружу из-за ран...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9877, 'Приводящее в сознание зелье', 'В битве с Плетью не избежать потерь. Каждый день многие погибают, но еще большему числу выпадает куда более страшный удел.$B$BПлеть захватывает пленников. И лучше им умереть, чем испытать то, что ждет их в Смертхольме. Их допрашивают и пытают, используя ужасный, ломающий волю яд. $B$BАптекарь Рензитен из Транквиллиона разработал противоядие - ступай к нему и принеси его приводящее в сознание зелье.', 'Поговорите с аптекарем Рензитеном в Транквиллионе. ', 'Так, значит, Джанеда посылает тебя вызволить пленников Смертхольма? Стало быть, она высоко ставит тебя, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9878, 'Устранение проблемы', 'Появление племени Темной Крови в Награнде отрицательно сказалось на наших землях. Стихии пришли в движение, что, в свою очередь, вызвало беспокойство среди животных. Мало того, разрушение заставы Солнечного Источника разбудило старую вражду между орками и моим народом.$B$BКуренай и Темная Кровь – разные племена, но орки видят в них лишь Сломленных.$B$BЭту проблему надо устранить. Отправляйся на северо-запад, на заставу Солнечного Источника, и реши этот вопрос.', 'Убейте 10 падальщиков и 5 налетчиков из племени Темной Крови. ', 'Сомневаюсь, что орки поймут и оценят то, что ты для них сделал, но с этой поры Награнд станет намного чище. Спасибо тебе.', NULL, NULL, NULL, 'Падальщик из племени Темной Крови убито', 'Налетчик из племени Темной Крови убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9879, 'Тотем К$Nа', 'Если бы не ты, $gнезнакомец:прекрасная незнакомка:, меня бы точно убили. Они перебили уже стольких куренаев в поисках своей утерянной реликвии!$B$BОни ищут тотем К$Nа. Не понимаю, с чего они взяли, что мы что-то знаем о нем. Этот тотем, как я понимаю, – реликвия орков, и уже в силу своей природы он может быть только орочьим орудием.$B$BЭти сведения нужно немедленно сообщить Арехрону. Быть может, он знает, почему Падшие из клана Темной Крови похищают куренаев и пытают их, чтобы добыть информацию об орудии орков.$B$BПомоги мне бежать.', 'Помогите куренайскому пленнику бежать с заставы Солнечного Источника. Расскажите Арехрону из Телаара обо всем, что вам удалось узнать.', 'Да, я знаю об этом тотеме... с ним связано очень многое. Однако это секретная информация, и я не вправе ее разглашать. Это опасное знание, которое можно доверить лишь немногим избранным.', NULL, NULL, NULL, 'Освободите куренайского пленника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9882, 'Украсть у вора', 'Принц нексуса Харамад пока не разрешает нам работать внутри Ошу\'гуна, поскольку это может разозлить некоторых влиятельных наару. Так что время идет, а работа стоит.$B$BНо я, кажется, нашел лазейку.$B$BПонимаешь, мы не единственные, кого тянет к этому гигантскому алмазу. Вор по имени Гава\'кси возглавил банду головорезов, которые проникли в Ошу\'гун и принялись откалывать от камня крупные куски.$B$BТвоя задача, $r, найти их и забрать то, что принадлежит нам по праву.', 'Раздобудьте 10 осколков кристалла Ошу\'гуна и отдайте их Гезхе в Небесном лагере в Награнде.', 'Прекрасный цвет. И качество в основном отличное.$B$BЯ сообщу нашим людям, как ты нам помогаешь.', 'Ты принес осколки кристалла, $N?', NULL, NULL, 'Осколок кристалла Ошу\'гуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9883, 'Снова осколки кристалла', '', '', 'Принеси нам еще осколков, $N. Все, которые сумеешь собрать. Нельзя позволять этим ворам расхищать нашу собственность.$B$BПусть даже она еще не совсем наша. Хотя, разумеется, уже почти наша. Во всяком случае, на бумаге.', NULL, NULL, NULL, 'Осколок кристалла Ошу\'гуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9884, 'Выгодное сотрудничество', '', '', 'Консорциум, как известно, не обижает своих друзей. В начале каждого месяца я буду тебе выдавать определенное количество самоцветов в счет оплаты услуг, которые ты нам окажешь.Качество самоцветов будет зависеть только от твоей преданности Консорциуму. Надеюсь, ты сделаешь правильный выбор и останешься с нами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9885, 'Выгодное сотрудничество', '', 'Рад снова видеть тебя, $N. Вот твои самоцветы, плата за месяц.Я там немного добавил сверх оговоренного... В знак нашего доброго расположения к тебе.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9886, 'Выгодное сотрудничество', '', '', 'Консорциум, как известно, не обижает своих друзей. В начале каждого месяца я буду тебе выдавать определенное количество самоцветов в счет оплаты услуг, которые ты нам окажешь.Качество самоцветов будет зависеть только от твоей преданности Консорциуму. Надеюсь, ты сделаешь правильный выбор и останешься с нами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9887, 'Выгодное сотрудничество', '', 'Ба, $N! Какие люди! Что такой важный господин делает в этом убогом местечке?Конечно, я уже приготовил камушки. Самоцветы высшего качества - не разбрасывайся ими попусту, $R.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9888, 'Слабосильный владыка', 'Я избежал верной смерти. Эти трусливые сволочи из клана Тяжелого Кулака ночью напали на наш городок, и я чудом уцелел.$B$BНо скажи, $gнезнакомец:незнакомка:: кто виноват в нашей беде?!$B$B<Джорин указывает на Гарроша.>$B$BОн отказал нам в помощи. Огры разоряют мой город, а он сидит тут и размазывает сопли. Что с нами стало? Во что мы превратились?! И что будет дальше?$B$BЯ отправил разведчика Килрата в поселение, который теперь называют руинами Кровавой Глазницы. Сможешь разыскать Килрата и помочь ему, если нужно? Он скрывается на границе Награнда и леса Тероккар.', 'Джорин Мертвый Глаз просит вас найти Килрата и поговорить с ним.', '<Килрат говорит, понизив голос.>$B$BЭти огры какие-то странные... И на редкость тупые. Смотри, как тот толстый заставляет плясать тех, которые... э... менее толстые. Завораживающее зрелище.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9889, 'Толстяка не убивать', 'Я уже несколько дней слежу за этими тварями. Толстяк говорит, что чего-то ждет. Чего конкретно – неизвестно.$B$BУ меня есть план, но тут придется применить насилие. Нужно убить нескольких его подчиненных, а потом избить его до полусмерти. После этого, я уверен, он выложит все, что нам надо узнать.', 'Убейте 10 захватчиков из клана Тяжелого Кулака, затем избейте и допросите Анкора Безжалостного.', 'Не убивай меня, я все расскажу!', 'Я сдаюсь! Сдаюсь!', NULL, NULL, 'Захватчик из клана Тяжелого Кулака убито', 'Анкор сдается', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9890, 'Готово!', 'Долгие годы клан Тяжелого Кулака правил над всеми ограми в Запределье. При Кроле огры объединились и жили дружно. Они довольствовались теми землями, которые им были даны. Однако в последние месяцы многие огры погибли от рук их же сородичей из клана Боевого Молота. Этот клан захватил почти все наши земли в Награнде и перебил многих наших собратьев.$B$BМы должны были взять этот город. У нас просто не было выбора. Нас истребляют...$B$BКрол пропал без вести, клан Тяжелого Кулака в полной растерянности. Лантрезор Клинок правит в его отсуствие.', 'Передайте все сведения, которые вы выбили из Анкора, Килрату в лес Тероккар.', 'Эй, притормози, $N... Я всего лишь скромный разбойник. Что мне делать с такими сведениями?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9891, 'Потому что Килрат – трус', 'Расскажи обо всем Джорину в Гарадаре. Уверяю тебя, его не обрадует известие об уничтожении деревни и почти поголовном истреблении ее жителей из-за претензий огров на территорию.$B$BДа хранят тебя предки... Если я тебе снова понадоблюсь, я буду прятаться здесь в кустах. В общем, ты знаешь, где меня найти.', 'Передайте информацию, которую вы выбили из Анкора, Джорину Мертвому Глазу в Гарадаре.', 'Они что, считают, у них есть право убивать орков и изгонять их с исконных земель? Надо думать, это никоим образом не связано с тем обстоятельством, что наш предводитель – сопливый щенок... Если бы в нем была хоть десятая доля той ярости, что полыхала в душе его отца...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9892, 'Поиски обсидиановых боевых ожерелий', '', '', 'Теперь мы получим хорошую прибыль, $N. Я позабочусь о том, чтобы Хораади узнал, как ты нам помогаешь.', NULL, NULL, NULL, 'Обсидиановые боевые бусы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9893, 'Обсидиановое боевое ожерелье', 'Гора Ошу\'гун еще не готова к раскопкам, и мы теряем немалую прибыль, $N.$B$BК счастью, я обнаружил дополнительный источник дохода. Огры Награнда носят боевые ожерелья из обсидиана – минерала, который во многих мирах ценится весьма высоко.$B$BЗерид уже разобрался с парочкой этих громил - в интересах безопасности, разумеется. В данном случае ожерелья можно рассматривать как дополнительные премиальные... А еще лучше вообще никак их не рассматривать, а просто собрать и принести мне сюда.', 'Принесите 10 обсидиановых боевых ожерелий Гезхе в Небесный лагерь в Награнде.', 'Замечательно. Теперь у нас есть чем заняться, пока Ша\'тар не закончат необходимые приготовления в Ошу\'гуне.', 'Как тебя встретили эти огры, $N? Надо думать, не слишком приветливо?', NULL, NULL, 'Обсидиановые боевые бусы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9894, 'Защита наблюдателей', 'В твоих странствиях тебе наверняка случалось сталкиваться с наблюдателями экспедиции. Они выполняют колоссальное количество работы в поле: описывают уникальных обитателей болот, собирают образцы, устанавливают контакты с разумными существами.$B$BОбеспечение их безопасности – дело первостепенной важности, $C. Недавно из-за участившихся нападений болотных тварей нам пришлось отозвать наблюдателей, которых мы отправили в пещеру Грибгор. Страж Хамут полагает, что со смертью их предводителя владыки Клака атаки сразу должны прекратиться.', 'Убейте владыку Клака и вернитесь к призывательнице ветров Черное Копыто в Кенарийский приют.', 'Я признательна тебе, $N, и все наблюдатели тоже. Они воспрянут духом, узнав, что могут продолжать свои исследования на юге, не опасаясь нападений!', NULL, NULL, NULL, 'Лорд Клак убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9895, 'Гибнущее равновесие', 'Приглядись внимательно к природе вокруг нас, $N. Эти болота умирают. Они отчаянно борются за то, чтобы сохранить экологическое равновесие, но терпят поражение в этой борьбе.$B$BПризнаки этого очевидны, если знать, где искать. Представители отдельных видов достигают гигантских размеров и становятся все агрессивнее.$B$BВот взять, к примеру, болотоброда Топехлыста. Если хочешь на него посмотреть, далеко ходить не надо: достаточно выйти на болота к югу от Оплота.$B$BТолько без оружия не ходи! Эта тварь не ведает пощады.', 'Найдите Топехлыста и уничтожьте его, потом вернитесь к Летину Лунному Пламени в Кенарийский приют.', 'Теперь ты своими глазами видел признаки нарушения равновесия. Не упускай их из виду в своих будущих странствиях.', NULL, NULL, NULL, 'Топехлыст убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9896, 'Проклятие черной бракониды', 'Жарковато здесь, клянусь огненным чревом Каз\'горота! Вполне понимаю первую экспедицию, которая отсюда сбежала. Впрочем, все знают, что сбежали они не из-за жары. Их выжила черная браконида, хотя, конечно, они в этом ни за что не признаются!$B$BОни встали лагерем на юг от светящихся дренейских башен, что к западу отсюда, чуть на север от деревни Дикотопь. И тут, откуда ни возьмись, появляется гигантская оса и нападает на них! Жду не дождусь увидеть, какие у них будут лица, когда я привезу в Стальгорн жало этой самой осы!', 'Принесите жало черной бракониды геологу Коналлу в Телредор. ', 'У меня просто слов нет, чтобы выразить, как я тебе благодарен! Ох, и потеха будет...', 'Ну что, удалось тебе добыть жало? Имей в виду, оно мне нужно целым и невредимым!', NULL, NULL, 'Жало черной бракониды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9897, 'Я спасена!', 'Я не жадная. Могу поделиться. Главное, я спаслась от этого паршивца Ганкли! С Зангартопи я притащила целую тонну шкур, так что с меня не убудет!', 'Отнесите сверток шкур Гарольду Лейну в лагерь Эрнестуэя в Награнде. ', 'Ну, меня там не было, так что я не знаю, действительно ли ты спас Кристен. Впрочем, если она поделилась с тобой шкурами – то больше мне ничего знать не надо.', 'Кристен такая приятная... (кашляет)... барышня... Правда? Шкурами вот поделилась... Очень мило с ее стороны.', NULL, NULL, 'Сверток шкур (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9898, 'Уважение к ближнему', '', '', '', 'Скоро мне повезет, нутром чую!', NULL, NULL, 'Жало черной бракониды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9899, 'Несделанное дело', 'Хотелось бы, чтобы кто-нибудь нашел способ вразумить этого Реавижа! Он совершенно забыл про свои обязанности, а вместо этого посвящает все свое время и силы тому, чтобы добиться моего расположения. Я пыталась не обращать на него внимания, я умоляла его перестать, – ничто не помогает!$B$BА до тех пор, пока он не придет в себя, мне приходится разгребать за ним несделанную работу! Например, он должен был разобраться со Спорокрылом, но могу поручиться, что это чудовище до сих пор летает на свободе! Послушай, если у тебя есть время, не сходишь ли ты в западную часть Мертвой трясины, чтобы убить этого ската? А я пока что разберусь с Реавижем...', 'Убейте Спорокрыла по просьбе Магаши с заставы Болотной Крысы. ', 'Ну, наконец нашелся хоть кто-то, кто готов делать дело! Спасибо тебе, $N, что покончил с этой тварью. А мне надо будет поговорить насчет Реавижа с Зураем. Его фантазии и хитрости завели его чересчур далеко...', NULL, NULL, NULL, 'Спорокрыл убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9900, 'Гава\'кси', 'Присутствие эфириалов-мошенников в этих краях, может быть, и забавляет Гезхе, который во всем ищет выгоду... однако это серьезная угроза безопасности нашей операции.$B$BИх вождь Гава\'кси – опасный преступник, и сейчас моя главная задача – нейтрализовать его как можно скорее.$B$BЕсли хочешь быть нам $gполезным:полезной:, убей мерзавца Гава\'кси. Я лично прослежу за тем, чтобы ты $gполучил:получила: достойное вознаграждение.', 'Убейте Гава\'кси, который скрывается близ Ошу\'гуна, и возвращайтесь к Зериду в Небесный лагерь в Награнде.', 'Теперь, когда ты прикончил Гава\'кси, мы избавились от лишнего повода для беспокойства. Большое спасибо. А сейчас давай определимся с твоим вознаграждением.', NULL, NULL, NULL, 'Гава\'кси убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9901, 'Неоконченное дело', 'Первая экспедиция, которую отправила сюда Лига, сообщала о встрече с гигантским зангарским скатом, которого они прозвали Спорокрылом. Экспедиции пришлось срочно уходить, поэтому они не успели убить этого ската, как собирались. Я же решил заняться этим.$B$BВ обрывках их отчета говорится, что это существо обитает в юго-западной части Мертвой трясины. Кажется, воздаятель Идаар упоминал, что это к северо-востоку от Телредора.', 'Убейте Спорокрыла по просьбе геолога Коналла из Телредора. ', 'Молодец, $N! Мы с тобой опередили целый отряд горняков! Когда вернусь в Стальгорн, это поможет мне заметно продвинуться в карьере...', NULL, NULL, NULL, 'Спорокрыл убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9902, 'Ужас озера Болотных Огоньков', 'Путешествуя по землям, захваченными нагами, я увидел, как обходятся там с моими собратьями, которым повезло меньше моего. На юго-западе озера Болотных Огоньков я наблюдал, как один особенно жестокий десятник играет в жуткую игру. Он отправляет своих рабов на острова, когда знает, что Жутеклешень, гигантский крабстер, вышел на охоту.$B$BЯ не стану описывать, чем заканчиваются эти игры. Нас слишком мало, чтобы напасть на наг, но мы, по крайней мере, можем лишить их любимой забавы, убив их страшного питомца!', 'Убейте Жутеклешня и вернитесь к Пулуу в прибежище Оребор. ', 'Благодарю тебя, $N. Быть может, в один прекрасный день с помощью дренеев это болото освободится от наг. Просто представить не могу, каково это - быть вынужденным служить им.$B$BМакту тоже когда-то был рабом. Он не любит об этом говорить...', NULL, NULL, NULL, 'Жутеклешень убито', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9903, 'Самый здоровенный', 'Тебе удалось уничтожить большинство мелких гидр, но Мрагеш – дело другое! Это свирепая, коварная тварь, и в свое время он изводил многих рыбаков.$B$BНо я буду последней, кому он досаждает! Он прячется где-то в глубине Змеиного озера, на северо-востоке. Он уже покойник, хотя сам этого еще не знает!', 'Убейте Мрагеша и вернитесь к Зурджайе в Забра\'джин. ', 'Я уверена, старина понимал, что ему скоро конец. Теперь все так переменилось, что старым обитателям болот осталось жить недолго. Оно и к лучшему, что старик теперь покоится в мире.', NULL, NULL, NULL, 'Мрагеш убито', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9904, 'Охота на Жутеклешня', 'Мне случалось ловить всякую рыбу, какая водится в озерах, но есть одна, которую мне поймать никак не удается. Конечно, я ловила и угрей, и илистых бешенок. Но в последний раз, как я удила на одном из островов на озере Болотных Огоньков, у меня клюнул огромный крабстер. Эта тварь перекусила мне леску и уплыла прочь.$B$BЕго зовут Жутеклешень, и я не успокоюсь, пока он не сдохнет! Он такой здоровый, что его ни одному рыбаку не поймать. Наверное, придется его просто укокошить по старинке.', 'Убейте Жутеклешня и вернитесь к Зурджайе в Забра\'джин. ', 'Ну, наконец-то! Говорят, у всякого великого рыболова непременно есть история о здоровенной твари, которая перекусила леску и уплыла, но лично я еще ни разу не встречала такой рыбы, которую бы я не сумела одолеть, так или иначе.', NULL, NULL, NULL, 'Жутеклешень убито', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9905, 'Месть Макту', 'В прошлый раз, когда Макту охотился на гидр на Змеином озере, на него напала самая здоровенная гидра, какую он видел в своей жизни. Макту потянулся было за копьем, но было слишком поздно. Гидра чудом не сожрала его.$B$BИ кто знает? Вдруг в следующий раз Макту повезет меньше? Макту хочет, чтобы следующего раза не случилось. Поможешь ли ты Макту отомстить этой гидре, Мрагешу?', 'Найдите и убейте Мрагеша, и вернитесь к Макту в прибежище Оребор. ', '<Макту одобрительно кивает.>$B$BМакту благодарит тебя за помощь. Его гордость успокоена. Больше его не застанут врасплох!', NULL, NULL, NULL, 'Мрагеш убито', 'Зелье подводного дыхания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9906, 'Клинок вместо слов', 'Огры уважают лишь силу. Даже так: Силу с большой буквы. Если мы покажем им свою слабость, они тут же этим воспользуются и сметут нас с лица земли.$B$BВозможно, Гаррош готов сдаться на милость огрским псам, но только не я! Я буду драться до последней капли крови! И сейчас я посылаю тебя, $N, с посланием клану Тяжелого Кулака. Эти животные понимают только язык силы.$B$BОтправляйся в руины Пылающего Клинка, к юго-востоку отсюда, и покажи этим ограм, на что способны маг\'хары.', 'Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 8 сокрушителей и 8 мистиков из клана Тяжелого Кулака.', 'Это только начало. Есть и другие, кому мы должны преподать урок!', NULL, NULL, NULL, 'Мистик из клана Тяжелого Кулака убито', 'Сокрушитель из клана Тяжелого Кулака убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9907, 'Дерзкий набег', 'Прямо на западе отсюда лежит котловина Халаани. В котловине есть отроги-близнецы: расщелина Северного Ветра и расщелина Южного Ветра. В них огры из клана Тяжелого Кулака спрятали свои поселения.$B$BЯ хочу, чтобы ты $gвыследил и уничтожил:выследила и уничтожила: всех огров в этих расщелинах. Во имя маг\'харов!', 'Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 10 воинов и 10 магов из клана Тяжелого Кулака.', 'Уж если и это их не напугает - тогда нам не на что рассчитывать. Ты сослужил маг\'харам достойную службу, $N. И получишь достойную награду.', NULL, NULL, NULL, 'Воин из клана Тяжелого Кулака убито', 'Маг из клана Тяжелого Кулака убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9910, 'Страх и уважение', 'Если ты собираешься в руины Пылающего Клинка, у меня есть для тебя поручение. Возьми эти боевые штандарты маг\'харов и водрузи их на видном месте на территории огров. Лучше всего – где-нибудь на возвышении. Ищи гигантские погребальные костры на верхних уровнях. Помести по одному знамени возле первого, второго и третьего погребальных костров клана Пылающего Клинка.$B$BЭти знамена надолго запомнятся всем ограм, которые уклонились от битвы.', 'Установите по одному боевому штандарту маг\'харов возле первого, второго и третьего погребальных костров клана Пылающего Клинка. Когда выполните поручение, верните Илкай\'гану Мистику оставшиеся штандарты.', 'Может, возьмешься еще за одну работенку? На этот раз, скажем так, более деликатного свойства?', 'Боятся – значит уважают! Ты исполнил мое поручение?', NULL, NULL, 'Первый боевой штандарт установлен', 'Второй боевой штандарт установлен', 'Третий боевой штандарт установлен', 'Боевой штандарт маг\'харов (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9911, 'Владыка болот', 'Эта окровавленная челюсть принадлежит гигантскому существу! Скат Пустоты, которому она принадлежала, должен быть самым огромным, какого когда-либо встречали в Зангартопи! Судя по состоянию челюсти, это существо – уже не падальщик, а хищник...$B$BКенарийская экспедиция наверняка заинтересуется подобным экземпляром. Обратитесь к наблюдательнице Лиса\'о, которая живет в небольшом лагере к западу от гряды Квагг.', 'Принесите челюсть \"Графа\" Унгула наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.', 'Она что, действительно настоящая? Нет, я знаю, что на болотах встречаются очень крупные животные, но ведь это же великан какой-то!$B$BХотя, с другой стороны, спорлинги рассказывали байки о каком-то жутком скате Пустоты, который терроризировал их еще до появления болотников...$B$BМожет быть, это все же не байки, а правда? Ну надо же... Пожалуй, это надо сохранить. Экспедиция наверняка захочет знать об этом существе.', '<Наблюдательница изумленно моргает.>$B$BОткуда у тебя... это?', NULL, NULL, 'Челюсть \"Графа\" Унгулы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9912, 'Кенарийская экспедиция', 'Главные представители Круга Кенария в Запределье – это Кенарийская экспедиция. Изначально она возникла как небольшой отряд, напрямую контролируемый Кругом Кенария. Но со временем экспедиция сделалась мощной, практически независимой организацией.$B$BГлава экспедиции, Исиэль Песнь Ветра, просила нас направлять добровольцев на ее базу. Она находится в Кенарийском приюте на востоке Зангартопи. Ступай по главной дороге, ведущей на запад, и она выведет тебя, куда нужно.', 'Поговорите с Исиэль Песнью Ветра в Кенарийском приюте в Зангартопи. ', 'Добро пожаловать в Кенарийский приют, $N! Надеюсь, ты здесь затем, чтобы помогать нам? У нас тут дел по горло!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9913, 'Консорциум ждет вас', 'Консорциум заинтересован в предприимчивых сотрудниках вроде вас. Трудно найти более честных, работящих и милых в общении компаньонов, чем мы.$B$BВсе, что мы требуем, – это преданность, верность делу и достаточная моральная гибкость. Если вы заинтересовались, обращайтесь к Гезхе, руководителю операционного отдела. Его можно найти в Небесном лагере, к северу от Ошу\'гуна.', 'Обратитесь к Гезхе. Его можно найти в Небесном лагере в Награнде. ', 'Готов приступить к работе? У нас как раз есть для тебя отличное задание.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9914, 'Кость на вес золота', 'Кость элекка – материал весьма ценный. Мои постоянные клиенты из дальних краев уже встали в очередь и предлагают за материал хорошую цену.$B$BЯ готов поделиться с тобой долей прибыли, если ты будешь мне помогать.$B$BМне нужна кость высшего качества, а именно – бивни диких элекков, обитающих в Награнде. Кость самцов элекка не дотягивает до стандарта.$B$BИ не волнуйся, это не браконьерство. У меня есть твердая договоренность и с орками, и с дренеями.$B$BНу что, мы с тобой договорились?', 'Добудьте 3 пары бивней элекков и принесите их Шадреку в Небесный лагерь в Награнде.', 'Я не сомневался в тебе ни секунды, дружище. Это именно то, что нужно, хотя бивни могли бы быть немного почище. И без царапин. Тем не менее, это хороший товар, и наш договор остается в силе.$B$BТы получишь оговоренную долю прибыли, и я очень надеюсь, что мы будем сотрудничать и в дальнейшем.', 'Вот та самая кость, которая мне нужна. Только такая и никакая иная. Разумеется, если желаешь, мы можем пересмотреть наше давешнее соглашение насчет размера твоей доли прибыли. Однако я сомневаюсь, что ты будешь доволен результатом.', NULL, NULL, 'Пара бивней', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9915, 'Кость на вес воздуха', '', '', 'Отлично, отлично. Еще несколько превосходных бивней, хотя можно было и получше отыскать.$B$BТы заслужил безграничную признательность Консорциума, $N.', NULL, NULL, NULL, 'Пара бивней', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9916, 'Припасы клана Кровавой Глазницы', 'Огры из клана Тяжелого Кулака спрятали украденные у нас припасы в расселинах Награнда, к западу отсюда, в котловине Халаани.$B$BРаз уж ты все равно туда отправляешься, поищи сундуки с припасами. Если удастся их вернуть, это сильно облегчит жизнь нашим матронам в Гарадаре.', 'Найдите 10 ящиков с припасами клана Кровавой Глазницы и принесите их Илкай\'гану Мистику.', 'Почти все наши пожитки либо погибли, либо были украдены при нападениях. Я мало что могу тебе предложить, но кое-что интересное у меня есть... Оно тебе наверняка пригодится...', 'Дети смогут протянуть еще один день без еды...', NULL, NULL, 'Ящик с припасами клана Кровавой Глазницы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9917, 'Не верь глазам своим', 'То ли зрение меня подводит, то ли там вдалеке и вправду огры? Как это они забрались так далеко от своего холма? Мне это очень не нравится, $gстранник:странница:. Сначала Темная Кровь, теперь огры. Нам просто не справиться со всеми напастями.$B$BПопробуй разузнать, почему огры забрались на восток. Их передовой лагерь где-то в 200 шагах восточнее отсюда. Увидишь охотников из клана Тяжелого Кулака – значит, $gдобрался:добралась: до места. Перебей всех и забери их планы вторжения.', 'Добудьте планы клана Тяжелого Кулака для охотницы Бинтук из Телаара. ', '<Бинтук просматривает планы.>$B$BВо имя Света! Почерк отвратительный. Не могу понять, то ли они собираются \"съесть синекожих и захватить их деревню\", то ли испечь пирог с голубикой. И так и так можно прочесть. Надо с этим разобраться!', 'Есть какие-то новости?', NULL, NULL, 'Планы клана Тяжелого Кулака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9918, 'Только не в мою смену!', 'План сражения составил кто-то из лейтенантов-огров по имени то ли Грыб, то ли Глыб.$B$B<Бинтук переворачивает пергамент и склоняет голову набок.>$B$BИли вообще Билли.$B$BКак бы там ни было, тебе надо пойти и переговорить с этим Билли, или Глыбом, или Грыбом, или как там его! Только не надо сразу стучать ему по голове. Для начала попробуем дипломатичный подход. Ну а уж если совсем ничего не получится, тогда можешь применить силу.', 'Поговорите с Глыбом. Когда получите необходимые сведения, возвращайтесь к охотнице Бинтук.', 'Вот черт! Говоришь, небольшой разведывательный отряд? Надо немедленно сообщить Мо\'мору!', NULL, NULL, NULL, 'Вы поговорили с Глыбом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9919, 'Спореггар', 'Ты $gдобрый:добрая:$r, $N. Не как другие, с которыми я встречался.$B$BТебе стоит встретиться с моими сородичами - они будут очень благодарны тебе за помощь. Отнеси эти мешочки со спорами к нашему предводителю, Мссхи\'фну. Ты найдешь его в Спореггаре, к северу отсюда.', 'Отправляйтесь в Спореггар, что в Зангартопи, к северу от Грибной поляны, и отнесите спасенные мешочки спор Мссхи\'фну.', 'Нежить, ты помог защитить новое поколение спорлингов! Мы можем тебе отплатить только одним: пригласив в свои дома. Поживи у нас, познакомься с другими спорлингами. Они захотят тебя о многом расспросить – но ты, надеюсь, не будешь против?', 'Ты хочешь мне что-то показать, $N?', NULL, NULL, 'Трофейный мешочек спор (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9920, 'Мо\'мор Разрушитель', 'Надо немедленно рассказать обо всем Мо\'мору! Ты найдешь его в центре Телаара, у фонтана. Перескажи ему все, что сказал тебе огр.', 'Охотница Бинтук из Телаара хочет, чтобы вы поговорили с Мо\'мором Разрушителем.', '<Мо\'мор озадаченно хмурится.>$B$BСтало быть, новый клан огров оттесняет клан Тяжелого Кулака все дальше и дальше на юг. Это тревожные новости. Сначала мы должны разобраться с опасностью, грозящей нашему дому...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9921, 'Руины Пылающего Клинка', 'Эти вылазки огров – явные предвестники большого вторжения. Мы должны нанести им удар до того, как они соберут армию для атаки на город.$B$BЕсли ты не боишься испачкать руки, у меня есть для тебя поручение, $r.$B$BСамый крупный отряд клана Тяжелого Кулака расположился сейчас в руинах Пылающего Клинка, почти прямо к востоку от Телаара, на границе леса Тероккар. Иди туда и покажи этим мерзавцам, что Телаар никогда не подчинится их воле!', 'Мо\'мор Разрушитель из Телаара желает, чтобы вы убили 8 мистиков и 8 сокрушителей из клана Тяжелого Кулака.', 'Отлично. Кстати, тебе удалось обнаружить Лантрезора, о котором было упомянуто в письме этого болвана?$B$BКак бы там ни было, это еще далеко не конец. Мне донесли, что огры опять что-то затевают, так что у нас есть чем заняться в ближайшее время!', NULL, NULL, NULL, 'Сокрушитель из клана Тяжелого Кулака убито', 'Мистик из клана Тяжелого Кулака убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9922, 'Расселины Награнда', 'Твоя сила изумляет, $N! Ты $gготов:готова: к новым подвигам?$B$BМне донесли, что большой отряд огров из клана Тяжелого Кулака скрывается в расселинах Награнда, в котловине Халаани к северо-западу отсюда.$B$BСпустись в расселины и разберись с ограми.', 'Мо\'мор Разрушитель из Телаара желает, чтобы вы убили 10 воинов и 10 магов клана Тяжелого Кулака.', 'Отлично сработано! Я сейчас собираю сведения о клане Боевого Молота, о котором упоминал лейтенант из клана Тяжелого Кулака. Ты проделал большую работу, пришло время проверить ее результаты.', NULL, NULL, NULL, 'Воин из клана Тяжелого Кулака убито', 'Маг из клана Тяжелого Кулака убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9923, 'На помощь!', 'НА ПОМОЩЬ! Они сожрут меня заживо! Точно-точно сожрут, я знаю!$B$BНайди ключ. Он у кого-то из этих огров.$B$BЕсли поможешь мне выбраться отсюда, мой отец щедро тебя наградит! Я – сын Арехрона, владыки Телаара.', 'Найдите ключ клана Тяжелого Кулака и освободите Корки. После этого отправляйтесь к Арехрону в Телаар за наградой.', 'Мне очень жаль, $R, что все так получилось. У моего дорогого сыночка редкий талант находить приключения на свою голову. Ладно, будет ему приключение... розгой по мягкому месту...', NULL, NULL, NULL, 'Корки освобожден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9924, 'Корки снова пропал!', '$gАрехрон вздыхает.>$B$BМне даже как-то неловко... Помнишь моего сына Корки? Недавно ты $gспас:спасла: его из руин Пылающего Клинка. Так вот, его неуемное любопытство вновь вонзило ему шило в то самое место. Он заявил мне, что собирается провести небольшое расследование для \"дядюшки\" Мо\'мора и убежал на курганы огров в котловину Халаани, к северу отсюда.$B$BСможешь его разыскать и вернуть? Я буду безмерно тебе благодарен.', 'Найдите и освободите Корки. ', 'Большое спасибо, $N. А Корки теперь займется его матушка. Может, хоть она его вразумит.', NULL, NULL, NULL, 'Корки освобожден в очередной раз', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9925, 'Вопросы безопасности', 'Гезхе разместил нас как можно ближе к Ошу\'гуну, совсем не заботясь о безопасности команды. Почему? Да просто он посчитал, что тут он сможет заработать на десять процентов больше, чем если бы мы расположились в горах к югу отсюда.$B$BНаплевать на бешеных отроков Бездны, которые шастают буквально в десяти шагах от нас. Это же проблема службы безопасности, а не Гезхе.$B$BВот что. Перебьешь отроков Бездны – получишь десятую долю денег, выделенных на охрану. И не слишком радуйся: денег там ворг наплакал.', 'Убейте 8 отроков Бездны поблизости от Ошу\'гуна по просьбе Зерида из Небесного лагеря.', 'Благодаря тебе, $N, мое лицо вновь озарилось улыбкой. То есть озарилось БЫ, будь у меня лицо. Продолжай в том же духе, и мы станем лучшими друзьями.', NULL, NULL, NULL, 'Отрок Бездны убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9927, 'Безжалостное коварство', '<Лантрезор вручает вам ранец, набитый знаменами.>$B$BЭто – знамена огров из клана Боевого Молота, которыми я недавно разжился в немалых количествах.$B$BОтправляйся в бастион Вечной Скорби, прямо к югу отсюда, и убей всех поганых прихвостней Совета Теней, которые встретятся тебе на пути. Вонзи древко знамени в сердце каждого убитого защитника бастиона. Потом возвращайся ко мне.', 'По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде вонзите 10 знамен клана Боевого Молота в тела защитников бастиона Вечной Скорби.Верните Лантрезору Клинку оставшиеся знамена.', 'Надо думать, они были изрядно удивлены, $R? Ты потрудился на славу!', '<Глаза Лантрезора широко раскрываются от изумления.>$B$BТы все сделал?!', NULL, NULL, 'Знамя огров Боевого Молота установлено', 'Знамя огров Боевого Молота (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9928, 'Военная хитрость', 'Чтобы мой план сработал, мне нужно, чтобы ты $gвыкрал:выкрала: оружие из бастиона Вечной Скорби.$B$BОбыщи крепость. Ищи сундуки с оружием из бастиона Вечной Скорби. Все, что найдешь, неси мне.$B$BБастион расположен прямо на юге и чуть к западу от руин Пылающего Клинка.', 'Принесите Лантрезору Клинку в руины Пылающего Клинка 10 ящиков с оружием бастиона Вечной Скорби.', 'Замечательно! Наша следующая мишень – руины Веселого Черепа.', 'Мы разожжем пламя доселе невиданной ненависти между этими двумя кланами!', NULL, NULL, 'Оружие Вечной Скорби', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9929, 'Пропавший торговец', 'Думаю, вы еще не знакомы с Дугаром, не так ли? Это торговец, который торгует с различными фракциями Шаттрата.$B$BНе спрашивайте, как он это делает, но ему как-то удается выменивать у них такое товары, которых нашим интендантам в жизни не достать.$B$BДугар три дня назад уехал в Шаттрат и до сих пор не вернулся, а обычно на поезду туда и обратно у него уходит куда меньше времени. Если вдруг поедете в лес, не поищете ли его там?', 'Отправляйтесь по дороге на северо-запад, по направлению к Шаттрату, и поищите какие-нибудь намеки на то, что могло случиться с Дугаром.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9930, 'Пропавший торговец', 'Думаю, вы еще не знакомы с Дейромом, не так ли? Это торговец, который торгует с различными фракциями Шаттрата.$B$BНе спрашивайте, как он это делает, но ему как-то удается выменивать у них такое товары, которых нашим интендантам в жизни не достать.$B$BДугар три дня назад уехал в Шаттрат и до сих пор не вернулся, а обычно на поезду туда и обратно у него уходит куда меньше времени. Так что вы уж поищите его, а обо всех находках сообщите капитану Тандеру, хорошо?', 'Отправляйтесь по дороге на северо-запад, по направлению к Шаттрату, и поищите какие-нибудь намеки на то, что могло случиться с Дейромом.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9931, 'Взаимная вежливость', 'Теперь мы дадим хорошего пинка этим жирным тупицам из клана Боевого Молота. На северо-западе, у горного кряжа, ты найдешь руины Веселого Черепа.$B$B<Лантрезор указывает на содержимое сундука с оружием, который вы ему принесли.>$B$BУзнаешь? Это знамена Вечной Скорби. Возьми их с собой и воткни по одному знамени в трупы огров из клана Боевого Молота. Помнишь, где их найти? На северо-западе.', 'По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде воткните 10 знамен Вечной Скорби в трупы огров клана Боевого Молота, обитающих в руинах Веселого Черепа.Оставшиеся знамена верните Лантрезору.', 'У меня отличный план, $N. Я уже вижу, каковы будут плоды твоих трудов.', 'Сможешь предугадать, что будет дальше?', NULL, NULL, 'Знамя Вечной Скорби установлено', 'Знамя Вечной Скорби (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9932, 'Вещественное доказательство', 'Твоя вылазка в бастион Вечной Скорби открыла нам новые возможности. Теперь у нас есть целая куча мертвых тел, с помощью которых можно инсценировать великую битву.$B$BОтправляйся на внутренний двор руин Веселого Черепа. Там горит костер. Убедись, что поблизости никого нет, и воспользуйся этим одеялом, чтобы подать дымовые сигналы. Когда мои огры увидят дым, они проникнут туда и живописно разложат повсюду трупы убитых защитников бастиона.$B$BЭто добьет наших врагов!', 'По поручению Лантрезора Клинка из руин Пылающего Клинка в Награнде найдите костер клана Боевого Молота во внутреннем дворе руин Веселого Черепа. С помощью мокрого шерстяного одеяла подайте дымовой сигнал ограм.', 'Давненько я ничего подобного не проворачивал! Спасибо за помощь, $N!', 'Теперь ты понимаешь, почему меня невозможно победить?', NULL, NULL, 'Трупы врагов живописно разложены', 'Мокрое шерстяное одеяло (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9933, 'Послание в Телаар', '$gЛантрезор указывает на сундук.>$B$BВозьми его. Это мой дар твоему народу. Ты $gодин:одна:, без какой-либо помощи, $gспас:спасла: мой клан от истребления.$B$BСкажи своему предводителю, что Лантрезор из клана Пылающего Клинка и огры из клана Тяжелого Кулака принимают его предложение о мире.$B$B<Лантрезор склоняется в поклоне.:', 'Отнесите мирное подношение Пылающего Клинка Арехрону в Телаар, что в Награнде.', 'Ты заслужил награду, $N. Бери все, что хочешь, из этих даров. В конце концов, если бы не ты, никаких бы даров и не было.', 'Значит, мир?', NULL, NULL, 'Мирное подношение клана Пылающего Клинка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9934, 'Послание в Гарадар', '$gЛантрезор указывает на сундук.>$B$BВозьми его. Это мой дар твоему народу. Ты $gодин:одна:, без какой-либо помощи, $gспас:спасла: мой клан от истребления.$B$BСкажи своему предводителю, что Лантрезор из клана Пылающего Клинка и огры из клана Тяжелого Кулака принимают его предложение о мире.$B$B<Лантрезор склоняется в поклоне.:', 'Отнесите мирное подношение клана Пылающего Клинка Гаррошу в Гарадар. ', '<Гаррош с пренебрежением пинает сундук.>$B$BТы только зря тратишь время, $R. Бери все, что хочешь, из этого сундука. Или вообще забирай все, что есть. Ни мне лично, ни Гарадару не нужны эти никчемные побрякушки.', '<Гаррош, похоже, не рад подаркам.>', NULL, NULL, 'Мирное подношение клана Пылающего Клинка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9935, 'Разыскивается: Гизельда Колдунья', 'Разыскиваются:$B$BГизельда Колдунья из бастиона Вечной Скорби и ее приспешники по обвинению в убийствах, ритуальных жертвоприношениях, пособничестве Легиону, похищении мирных граждан и многочисленных кражах со взломом.$B$BВ настоящее время скрывается в бастионе Вечной Скорби в юго-восточном Награнде, на окраине леса Тероккар.$B$BТот, кто сумеет поймать преступницу и предать ее в руки правосудия, получит награду от стража-смотрителя Быккрока в Гарадаре.', 'Убейте Гизельду Колдунью и 10 любых служителей бастиона Вечной Скорби. Получите награду у стража-смотрителя Быккрока в Гарадаре.', 'Мегера мертва! Отличные новости, $N. Вот твоя награда.', NULL, NULL, NULL, 'Гизельда Колдунья убито', 'Посланник бастиона Вечной Скорби убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9936, 'Разыскивается: Гизельда Колдунья', 'Разыскивается:$B$BГизельда Колдунья из бастиона Вечной Скорби и ее приспешники по обвинению в убийствах, ритуальных жертвоприношениях, пособничестве Легиону, похищении мирных граждан и многочисленных кражах со взломом.$B$BВ настоящее время скрывается в бастионе Вечной Скорби в юго-восточном Награнде, на окраине леса Тероккар.$B$BТот, кто сумеет поймать преступницу и предать ее в руки правосудия, получит награду от стража-смотрителя Мой\'прна Джилла в Телааре.', 'Убейте Гизельда Колдунью и 10 любых служителей бастиона Вечной Скорби. Получите награду у стража-смотрителя Мой\'прна Джилла в Телааре.', 'Мегера мертва! Отличные новости, $N. Вот твоя награда.', NULL, NULL, NULL, 'Гизельда Колдунья убито', 'Посланник бастиона Вечной Скорби убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9937, 'Разыскивается: Дарн Ненасытный', 'Ты $gуничтожил:уничтожила: двух величайших злодеев, угрожавших Награнду, $N. Ты $gготов:готова: сразиться с Дарном Ненасытным, истинным бедствием Полей Духов?$B$BДарн Ненасытный бесчинствует на землях, окружающих Ошу\'гун, неся погибель всем на своем пути. Пока что никто не сумел избавить Награнд от этого лютого гронна. Собери своих верный друзей, отправляйся на Поля Духов к юго-западу отсюда. У самого Ошу\'гуна разыщи Дарна и убей его. Это будет нелегко, но награда за подвиг тебя не разочарует.', 'Убейте Дарна Ненасытного. Вернитесь к стражу-смотрителю Быккроку и получите награду.', 'Ты избавил Награнд от страшной угрозы. Ты – настоящий герой, поистине величайший из всех!', NULL, NULL, NULL, 'Дарн Ненасытный убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9938, 'Разыскивается: Дарн Ненасытный', 'Ты $gуничтожил:уничтожила: двух величайших злодеев, угрожавших Награнду, $N. Ты $gготов:готова: сразиться с Дарном Ненасытным, истинным бедствием Полей Духов?$B$BДарн Ненасытный бесчинствует на землях, окружающих Ошу\'гун, неся погибель всем на своем пути. Пока что никто не сумел избавить Награнд от этого лютого гронна. Собери своих верный друзей, отправляйся на Поля Духов к юго-западу отсюда. У самого Ошу\'гуна разыщи Дарна и убей его. Это будет нелегко, но награда за подвиг тебя не разочарует.', 'Убейте Дарна Ненасытного. Вернитесь к стражу-смотрителю Мой\'прну Джиллу и получите награду.', 'Ты избавил Награнд от страшной угрозы. Ты – настоящий герой, поистине величайший из всех!', NULL, NULL, NULL, 'Дарн Ненасытный убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9939, 'Разыскивается: Зорбо Советчик', 'Разыскивается живым или мертвым!$B$BЗорбо Советчик разыскивается за организацию ряда спланированных нападений на Гарадар. При содействии разрушителей и шаманов преступник убил бессчетное количество орков. Зорбо вооружен, беспощаден и очень опасен.$B$BСейчас он скрывается в руинах Веселого Черепа в северных горах Награнда.$B$BУбивший или поймавший Зорбо Советчика может обратиться за наградой к стражу-смотрителю Быккроку в Гарадаре.', 'Убейте Зорбо Советчика, 5 шаманов и 5 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Быккрока.', 'Это великая победа для Гарадара! Ты – настоящий герой, $N!', 'Ты пришел за наградой?', NULL, NULL, 'Зорбо Советчик убито', 'Шаман из клана Боевого Молота убито', 'Разоритель из клана Боевого Молота убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9940, 'Разыскивается: Зорбо Советчик', 'Разыскивается живым или мертвым!$B$BЗорбо Советчик разыскивается за организацию ряда спланированных нападений на Телаар. При содействии разрушителей и шаманов преступник убил бессчетное количество Сломленных. Зорбо вооружен, беспощаден и очень опасен.$B$BСейчас он скрывается в руинах Веселого Черепа в северных горах Награнда.$B$BУбивший или поймавший Зорбо Советчика может обратиться за наградой к стражу-смотрителю Мой\'прну Джиллу в Телаар.', 'Убейте Зорбо Советчика, 5 шаманов и 5 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Мой\'прна Джилла.', 'Это великая победа для Телаара! Ты - герой, $N!', NULL, NULL, NULL, 'Зорбо Советчик убито', 'Шаман из клана Боевого Молота убито', 'Разоритель из клана Боевого Молота убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9941, 'Выслеживание преступников', 'Следы араккоа и две неглубокие колеи ведут на север, через дорогу. Водимо, араккоа утащили что-то с поля боя в свое ближайшее поселение.$B$BНа сломанной телеге остались следы битвы, но мы до сих пор не знаем, что сталось с Дейромом. Ступайте по следам араккоа на север и продолжайте искать торговца – если его взяли в плен, то он, возможно, до сих пор жив.', 'Продолжите поиски Дейрома в поселении араккоа к северу от сломанной повозки.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9942, 'Выслеживание преступников', 'Следы араккоа и две неглубокие колеи ведут на север, через дорогу. Водимо, араккоа утащили что-то с поля боя в свое ближайшее поселение.$B$BНа сломанной телеге остались следы битвы, но мы до сих пор не знаем, что сталось с Дугаром. Ступайте по следам араккоа на север и продолжайте искать торговца – если его взяли в плен, то он, возможно, до сих пор жив.', 'Продолжите поиски Дугара в поселении араккоа к северу от сломанной повозки.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9943, 'Обратно к Тандеру', 'Груз Дейрома явно представлял для араккоа интерес, но судя по тому, что товары не повреждены и даже не открыты, пленник интересовал их куда больше. Остается неясным, какую же цель преследовали араккоа, напав на торговца и похитив его, но одно можно сказать точно – здесь Дейрома нет.$B$BУ вас не осталось никаких идей о том, где можно продолжить поиски, поэтому лучше всего будет пойти и рассказать обо всем Тандеру.', 'Вернитесь к Тандеру в Бастион Аллерии и расскажите ему о том, что вам удалось обнаружить.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9944, 'Пропавший маг\'харский караван', 'Великая мать говорит, что мы не должны сидеть сложа руки. Мы должны подать пример Гаррошу – показать, что жизнь продолжается, несмотря ни на что.$B$BУ меня столько дел... особенно после того, как великая мать заболела. Может быть, ты окажешь честь маг\'харам и поможешь мне?$B$BНесколько дней назад мы отправили похоронную процессию в Земли Предков, и она до сих пор не вернулись. Ты поможешь нам ее разыскать? Процессия ушла на запад от Гарадара. Иди по ее следам, но не заходи в Халаа.', 'Найдите пропавший маг\'харский караван. ', 'Тридцать орков, $R! Из тех тридцати в живых остались лишь Унгриз да я. Мы нашли молодого орка, Саурфанга, близ заставы Солнечного Источника. Он был едва жив. Как я понимаю, он случайно попал ограм под горячую руку...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9945, 'Войной на Боевой Молот', 'Мы направлялись в земли Предков, когда нас окружили огры из клана Боевого Молота. Они напали одновременно со всех сторон, убили нескольких воинов из похоронной процессии и многих других. Более того, они осквернили останки старейшины, покоившиеся в катафалке.$B$BСпрашивается, зачем? Чтобы унизить нас и продемонстрировать свою силу? Даже огры из клана Тяжелого Кулака до такого бы не опустились.$B$BЯ - благочестивый и праведный орк, $N, но у всякого терпения есть пределы. Ты найдешь этих негодяев к северо-западу отсюда, у холма Боевого Молота. Уничтожь их всех!', 'Старейшина Йорли из Маг\'харского Каравана в Награнде попросил вас убить 8 громил и 8 чернокнижников клана Боевого Молота.', 'Для начала неплохо, но надо еще разобраться с их вожаком, чтобы закрепить результат.', NULL, NULL, NULL, 'Громила из клана Боевого Молота убито', 'Чернокнижник из клана Боевого Молота убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9946, 'Чо\'вар Погромщик', 'Доводилось ли тебе, $r, встречаться с главарем огров? Немногие остались в живых после такой встречи. Но я в тебя верю.$B$BГлаварь этих варваров – огр по имени Чо\'вар. Поговаривают, что именно он выгнал гронна из пещеры. Потом Чо\'вар объявил себя королем и распустил кланы огров, которыми правил гронн. Так появился клан Боевого Молота.$B$BРазыщи Чо\'вара в глубинах пещер холма Боевого Молота, убей негодяя и принеси мне его голову.', 'Убейте Чо\'вара Погромщика и принесите его голову старейшине Йорли в Маг\'харский Караван.', 'Его голову выставят на всеобщее обозрение у ворот Гарадара. В следующий раз огры сто раз подумают, прежде чем прерывать священные ритуалы маг\'харов.', 'Его наверняка хорошо охраняют.', NULL, NULL, 'Голова Чо\'вара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9947, 'Обратно к Рокагу', 'Груз Дугара явно представлял для араккоа интерес, но судя по тому, что товары не повреждены и даже не открыты, пленник интересовал их куда больше. Остается неясным, какую же цель преследовали араккоа, напав на торговца и похитив его, но одно можно сказать точно – здесь Дугара нет.$B$BУ вас не осталось никаких идей о том, где можно продолжить поиски, поэтому лучше всего будет пойти и рассказать обо всем Рокагу.', 'Вернитесь к Рокагу в Форт Камнеломов и расскажите ему о том, что вам удалось обнаружить.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9948, 'Спасательная экспедиция', 'Огры обожают свежатинку, уж я-то знаю. А это значит, что маг\'харов, которых они захватили, скорее всего, держат живыми, пока не придет время подать их к столу. Мерзко звучит, но нет худа без добра.$B$BПроберись к холму Боевого Молота и отыщи там пленных маг\'харов. Ключи от их клеток, скорее всего, хранятся у огров из клана Боевого Молота, шатающихся где-то поблизости.$B$BУбей этих огров, забери ключи и освободи пленников.', 'Освободите 5 пленных маг\'харов по просьбе старейшины Унгриза из маг\'харского каравана в Награнде.', 'Ты совершил невозможное, и наши братья и сестры снова с нами. Ты - благодетель маг\'харов, $N. Твое имя и подвиги навсегда останутся в наших сердцах.', NULL, NULL, NULL, 'Освобождено пленных маг\'харов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9949, 'Птичьи Глаза', 'Больше у нас информации нет, и положение не из легких... Но я все равно буду искать Дейрома и спасу его во что бы то ни стало. Его похищение – не случайность, $N.$B$BАраккоа что-то затевают, но вот что?$B$BАндарл в башне магов кое-что понимает в их магии, и если предоставить ему все необходимое, он сможет узнать для нас кое-что еще. Однако ему потребуются так называемые \"ока\" из каждого поселения араккоа на Костяных пустошах – гнездовий Скит, Рескк и Шиенор.', 'Принесите Око Гнездовья Скит, Око Гнездовья Шиенор и Око Гнездовья Рескк Андарлу в Бастион Аллерии.', '', NULL, NULL, NULL, 'Око Гнездовья Рескк', 'Око Гнездовья Шиенор', 'Око гнездовья Скит', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9950, 'Птичьи Глаза', 'Больше у нас информации нет, и положение не из легких... Но я все равно буду искать Дугара и спасу его во что бы то ни стало. Его похищение – не случайность, $N.$B$BАраккоа что-то затевают, но вот что?$B$BЧернокнижник Каргаток кое-что понимает в их магии, и если предоставить ему все необходимое, он сможет узнать для нас кое-что еще. Однако ему потребуются так называемые \"ока\" из каждого поселения араккоа на Костяных пустошах – гнездовий Скит, Рескк и Шиенор.', 'Принесите Око Гнездовья Скит, Око Гнездовья Шиенор и Око Гнездовья Рескк Каргатоку в Форт Камнеломов.', '', NULL, NULL, NULL, 'Око Гнездовья Шиенор', 'Око Гнездовья Рескк', 'Око гнездовья Скит', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9951, 'Он следит за тобой!', 'Скорее, прячьтесь! Нафталар следит за вами... за всеми нами следит!$B$BЯ не смею взбираться на башню и говорить с ним, но вы... вы, похоже, знаете нужные слова. Только будьте осторожны – он не любит шуток и быстр на расправу с дураками.$B$BЕсли сможете, уговорите его спуститься и попить чайку... Но в любом случае, сделайте что-нибудь, чтобы он перестал на меня смотреть!', 'Убейте Нафталара и вернитесь к хранителю Древлосу в перелесок Кенария в лесу Тероккар.', 'Ну что ж, это только к лучшему. Если ему не хватает вежливости принять приглашение, значит, больше не будем его звать.$B$B<На лице хранителя Древлоса на миг застывает растерянное выражение.>$B$BКто вы и что здесь делаете? Уходите отсюда, пока не стало слишком поздно!', 'Не надо нам было приглашать его на ужин, это точно!$B$BИли, по крайней мере, надо было настоять хотя бы на паре блюд перед десертом, который они принесли!', NULL, NULL, 'Нафталар убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9952, 'Геолог Бальморал', 'Значит, Андарл считает, что Дейрома удерживают в Гнездовье Шалас? Это самое большое поселение араккоа из тех, что мы знаем.$B$BГнездовье Шалас находится в самой южной части леса, рядом с восточной границей Костяных пустошей. К сожалению, я почти ничего не знаю об этом поселении, но там поблизости обосновался член Лиги исследователей, который сможет рассказать вам побольше. Его зовут геолог Бальморал, а лагерь его находится на самом краю земель к юго-западу от Гнездовья Шалас. Поговорите с ним, прежде чем предпринимать какие-либо действия против араккоа.', 'Найдите геолога Бальморала и поговорите с ним.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9953, 'Наблюдатель Нодак', 'Значит, Каргаток считает, что Дугара удерживают в гнездовье Шалас? Это самое большое поселение араккоа из тех, что мы знаем.$B$BГнездовье Шалас находится в самой южной части леса, рядом с восточной границей Костяных пустошей. К сожалению, я почти ничего не знаю об этом поселении, но там поблизости обосновался член Лиги Исследователей, который сможет рассказать вам побольше. Его зовут Нодак, а лагерь его находится на самом краю земель к юго-западу от Гнездовья Шалас. Поговорите с ним, прежде чем предпринимать какие-либо действия против араккоа.', 'Найдите наблюдателя Нодака и поговорите с ним.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9954, 'Выкуп за Корки', 'Арехрон показывает вам письмо на заляпанном грязью листе бумаги.*$B$BЭто от огров из клана Боевого Молота, который правит северо-западными землями Награнда. Они пишут, что захватили в плен Корки, и требуют выкуп. Грозятся съесть его, если мы не согласимся на их условия. Корки, конечно, редкостный идиот, но он все же мой сын, плоть от плоти, и так далее. Ты спасешь его, $N?$B$BКак я понимаю, его держат в клетке где-то на холме Боевого Молота.', 'Арехрон просит вас найти Корки на холме Боевого Молота. ', 'На этот раз они меня заперли надежно, $N. А ключ - у Чо\'вара, главы Боевого Молота.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9955, 'Чо\'вар Погромщик', 'Его называют Чо\'вар Погромщик, $N. Именно он сверг гронна, который правил местным кланом огров. Он действительно очень силен, об этом следует помнить!$B$BГоворят, Човар живет в огромной пещере... знать бы еще, где она находится... Найди его, возьми ключ от клетки и освободи меня! Если ты мне поможешь отсюда выбраться, мой отец щедро тебя наградит!', 'Найдите Чо\'вара, отберите у него ключ и освободите Корки из клетки. После этого отправляйтесь к Арехрону в Телаар за наградой.', 'Спасибо, $N. Мы отправили Корки к ночным эльфам в Острогорье. Будем надеяться, они присмотрят за ним и сумеют уберечь его от неприятностей.$B$BТеперь, что касается твоей награды...', NULL, NULL, NULL, 'Корки освобожден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9956, 'Разграбленный караван', 'Я сопровождала караван, направлявшийся в прибежище Оребор в Зангартопи. На подходе к болотам на нас напали огры из клана Боевого Молота. Они забрали груз, перебили всех наших, а меня взяли в плен.$B$BК счастью, они не озаботились тем, чтобы укрепить замок моей клетки. Когда они все заснули, мне удалось выбраться и сбежать.$B$BМоих мертвых товарищей уже не спасти, но мы можем хотя бы забрать груз из разграбленного каравана. Огры спрятали краденое на холме Боевого Молота в горах на северо-западе Награнда.', 'Помогите охотнице Киме вернуть 10 телаарских ящиков с припасами. ', 'Поразительно! Как тебе удалось утащить это все в одиночку?!', 'Вот незадача... Корки, сын Арехрона, спросил меня, что случилось. Выслушав новости, он снова пропал!', NULL, NULL, 'Телаарский ящик с припасами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9957, 'Что случилось в перелеске Кенария?', 'От друидов из перелеска Кенария в лесу Тероккар уже давно нет никаких вестей.$B$B$N, я прошу тебя отправиться туда и узнать, что происходит. В перелесок ведет несколько дорог, но быстрее всего будет пойти сначала на юг, а потом, когда доберешься до леса, свернуть на дорогу, что идет на восток от Шаттрата.', 'Поговорите с одним из друидов в перелеске Кенария в лесу Тероккар.', 'Хорошо, что к нам хоть кого-то прислали. Всех местных друидов убили! Выжить удалось только мне и еще одному, да и тот сошел с ума.$B$BНе знаю, что тут стряслось, но обязательно докопаюсь до правды. Что бы это ни было, все случилось очень быстро и оставило ощущение какой-то неестественности.$B$BВы мне поможете?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9958, 'Разведка укреплений', 'За все то время, что я провел здесь, я несколько раз встречался с араккоа, и ни одну из этих встреч нельзя назвать нормальной. Они очень нервно относятся к любому посягательству на свою территорию, как, впрочем и мы...$B$BЭти птицелюди владеют некоей изначальной магией, которая неподвластна нашим видящим, и эту магию они используют для защиты своего поселения – Гнездовья Шалас. Прежде чем нападать на них, надо узнать, что там за защита – неразумно было бы нападать вслепую.', 'Подойдите поближе к Гнездовью Шалас и осмотрите защитные укрепления городка.', '', NULL, NULL, NULL, 'Осмотрите защитные укрепления Гнездовья Шалас', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9959, 'Разведка укреплений', 'За все то время, что я провел здесь, я несколько раз встречался с араккоа, и ни одну из этих встреч нельзя назвать нормальной. Они очень нервно относятся к любому посягательству на свою территорию, как, впрочем и мы... Однако даже у наших предков нет никаких записей об араккоа.$B$BЭти птицелюди владеют некоей изначальной магией, которая неподвластна нашим видящим, и эту магию они используют для защиты своего поселения – Гнездовья Шалас. Прежде чем нападать на них, надо узнать, что там за защита – неразумно было бы нападать вслепую.', 'Подойдите поближе к Гнездовью Шалас и постарайтесь узнать, что за магия защищает это поселение.', '', NULL, NULL, NULL, 'Осмотрите защитные укрепления Гнездовья Шалас', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9960, 'Что случилось в перелеске Кенария?', 'Здравствуй, $C. От друидов из перелеска Кенария уже давно нет никаких вестей.$B$BЯ прошу тебя отправиться туда и узнать, что с ними случилось. Это место к северо-западу отсюда, если ехать через лес.', 'Поговорите с одним из друидов в перелеске Кенария в лесу Тероккар.', 'Очень хорошо, что из форта Камнеломов кого-то наконец прислали! Всех друидов убили, выжить удалось только мне и еще одному, да и тот сошел с ума.$B$BНе знаю, что случилось, но я обязательно это расследую! Что бы это ни было, все случилось очень быстро, и оставило чувство какой-то неестественности.$B$BВы мне поможете?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9961, 'Что случилось в перелеске Кенария?', '$C, у меня к тебе важное дело. От друидов из перелеска Кенария уже давно нет никаких вестей, и это тревожит меня, потому что раньше они связывались с нами довольно часто.$B$BЯ прошу тебя отправиться туда и проверить, все ли с ними в порядке. Перелесок находится к северо-западу отсюда, если ехать через лес.', 'Поговорите с одним из друидов в перелеске Кенария в лесу Тероккар.', 'Очень хорошо, что из бастиона Аллерии кого-то наконец прислали! Всех друидов убили, выжить удалось только мне и еще одному, да и тот сошел с ума.$B$BНе знаю, что случилось, но я обязательно докопаюсь до правды! Что бы это ни было, все случилось очень быстро, и оставило чувство какой-то неестественности.$B$BТы мне поможешь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9962, 'Кольцо Крови: Хромоног', 'Ты $gготов:готова: к своей первой битве? Дай мне знать, и я объявлю о начале боя. Тебе останется только ждать в Кольце Крови, когда появится твой противник.$B$BТы будешь сражаться против Хромонога, свирепого копытня.$B$BУдачи! Надеюсь, ты $gпривел:привела: с собой верных друзей.$B$BИ помни, поединок закончится только тогда, когда кто-то из вас – либо ты, либо соперник – упадет на арену и больше не встанет.', 'Одержите победу над Хромоногом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.', 'Гм... неплохо, неплохо... У тебя очень хорошие данные, малыш. Вот тебе немного золота – пусть звенит в карманах.', 'Поединок закончится только тогда, когда один из вас упадет замертво.', NULL, NULL, 'Одержана победа над Хромоногом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9963, 'Помощь от врага', 'Да, защитная магия араккоа настолько сильна, что мы вряд ли когда-нибудь сможем постигнуть ее, и нам остается только выведать этот секрет у самих араккоа.$B$BДа, я знаю, о чем вы думаете – с чего бы нашим врагам выдавать свои тайны? Разумеется, они ничего не скажут. Но, возможно, вы когда-нибудь слышали о старом, выжившем из ума араккоа по имени Кокорек? Говорят, что он живет в Гнездовье Литик, в западной части Костяных Пустошей, и ждет там возвращения былых времен.', 'Найдите Кокорека в Гнездовье Литик и поговорите с ним.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9964, 'Помощь от врага', 'Да, защитная магия араккоа настолько сильна, что мы вряд ли когда-нибудь сможем постигнуть ее, и нам остается только выведать этот секрет у самих араккоа.$B$BДа, я знаю, о чем вы думаете – с чего бы нашим врагам выдавать свои тайны? Разумеется, они ничего не скажут. Но, возможно, вы когда-нибудь слышали о старом, выжившем из ума араккоа по имени Кокорек? Говорят, что он живет в Гнездовье Литик, в западной части Костяных Пустошей, и ждет там возвращения былых времен.', 'Найдите Кокорека в Гнездовье Литик и поговорите с ним.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9965, 'Проявление веры', 'Я хочу предложить некую сделку: вы продемонстрируете свои добрые намерения и поможете мне решить одну проблему, а я помогу вам спасти товарища.$B$BОгры – заклятые враги моего народа, и недавно они вновь начали забредать в наши леса из Награнда.$B$BОдин огр, зовут его Муг\'гок, очень смелый, но не особо умный. Он шатается туда-сюда, пытаясь спровоцировать нас, и тем самым доставляет много проблем своим приятелям из руин Кровавой Глазницы.', 'Принесите голову Муг\'гока Кокореку в Гнездовье Литик.', '', NULL, NULL, NULL, 'Голова Муг\'гока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9966, 'Проявление веры', 'Я хочу предложить некую сделку: вы продемонстрируете свои добрые намерения и поможете мне решить одну проблему, а я помогу вам спасти товарища.$B$BОгры – заклятые враги моего народа, и недавно они вновь начали забредать в наши леса из Награнда.$B$BОдин огр, зовут его Муг\'гок, очень смелый, но не особо умный. Он шатается туда-сюда, пытаясь спровоцировать нас, и тем самым доставляет много проблем своим приятелям из руин Кровавой Глазницы.', 'Принесите голову Муг\'гока Кокореку в Гнездовье Литик.', '', NULL, NULL, NULL, 'Голова Муг\'гока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9967, 'Кольцо Крови: братья Блю', 'В следующей схватке тебе придется сразиться сразу с двумя противниками - а точнее, с братьями-близнецами. Они называют себя \"Братья Блю.\"$B$BЕще не поздно отказаться от боя, $N. Если откажешься, я пойму.$B$BНо если ты $gготов:готова: драться, тогда войди в Кольцо Крови и жди выхода близнецов из племени Темной Крови.$B$BКто упал и не поднялся, тот проиграл. Кто устоял, тот победитель!', 'Одержите победу над близнецами из племени Темной Крови, которые называют себя \"Братья Блю\". После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.', 'Честно признаюсь, я уже и не верил, что ты победишь, $N! Это было потрясающе! Не хочешь сразиться еще раз? У Гаргтока есть для тебя достойный противник.', 'Поединок закончится только тогда, когда один из вас упадет замертво.', NULL, NULL, '\"Братья Блю\" побеждены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9968, 'Странная энергия', 'Живущие в чащобе пухоспинки почему-то изменились.$B$BРаньше там бурлила жизнь, но теперь остались только эти бабочки, и если раньше они были очень мирными, то теперь нападают на всякого, кто приблизится к ним.$B$BМне нужно сравнить агрессивных пухоспинок с нормальными, а для этого мне понадобятся образцы и тех, и других. Обычных можно найти и к югу, и к северу отсюда.$B$BУверен, это как-то связано с гибелью всех друидов.', 'Соберите 4 образца пухоспинки и 4 образца агрессивной пухоспинки для землепряда Тавгрена. Его можно найти возле Перелеска Кенария в лесу Тероккар.', 'Странно. Образцы агрессивных пухоспинок словно бы пропитаны чистейшей маной...$B$BПохоже то, что убило друидов, оставило после себя сильное энергетическое поле. Но пухоспинки почему-то не погибли от него, а только стали очень агрессивными.$B$BНо в одном я теперь уверен – эта странная энергия является побочным продуктом того, что убило всех друидов в чащобе.', 'Вы принесли образцы?', NULL, NULL, 'Образец ткани пухоспинки', 'Образец ткани агрессивной пухоспинки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9969, 'Последние реагенты', 'Я могу изготовить предмет, который нейтрализует охранные заклинания Гнездовья Шалас. Но предупреждаю, $N – магия будет действовать только пока вашего друга удерживают в плену. Я не стану добровольно давать вам средства для нападения на мой народ.$B$BУ меня есть почти все нужные материалы, но кое-что придется добыть вам. Мне потребуются сущности прыгуаны-охотника и горсть тероккарской черной рябины. Все это можно найти поблизости от Гнездовья.', 'Принесите 5 сущностей прыгуаны-охотника и 30 ягод тероккарской черной рябины Кокореку в Гнездовье Литик.', '', NULL, NULL, NULL, 'Сущность прыгуаны-охотника', 'Тероккарская черная рябина', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9970, 'Кольцо Крови: Камнедар Выщербленный Повелитель', 'Это будет нелегкий бой, $N. Надеюсь, у тебя есть отважные друзья, которые смогут тебе помочь? Огры нашли великана в Острогорье. Его зовут Рокдар! Поверь мне на слово, $gодин:одна: ты не справишься. Этот Рокдар непобедим! Он тверд, как скала, в прямом смысле слова!$B$BЕсли хочешь сразиться с ним, войди в Кольцо Крови, и он примет вызов.', 'Победите Камнедара Выщербленного Повелителя. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.', 'Ты хорошо погонял этих огров, малыш! Заставил их попотеть! Вот тебе кое-что сверху оговоренного – смотри, не трать все сразу!$B$BТы готов к следующей схватке? Гаргток ставит на тебя! Смотри не подведи!', NULL, NULL, NULL, 'Победа над Камнедаром Выщербленным Повелителем одержана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9971, 'Ответы в чащобе', 'Ума не приложу, что же убило всех местных друидов? Меня самого тут пару дней не было – я изучал Костяные пустоши на юге.$B$BПожалуйста, помоги мне выяснить, что за трагедия здесь произошла! Нужно сходить в чащобу и поискать там какие-то улики, подсказки, которые смогут навести нас на след. Когда я был там – правда, очень не долго – то видел труп некоего Сломленного и странный предмет около него.$B$BА насчет Древлоса не волнуйся – он, возможно, и сошел с ума от того, что там произошло, но вообще он безобиден.', 'Осмотрите странный предмет рядом с трупом Сломленного и постарайтесь узнать, что случилось в перелеске Кенария. Затем вернитесь к заклинателю земли Тавгрену в лес Тероккар.', 'Значит, я был прав. Это и в самом деле был труп Сломленного? И вы можете точно сказать, что рядом с ним на земле лежал странный предмет?$B$BЧто-то тут не сходится... С чего бы Сломленному соваться сюда? И что за предмет он с собой притащил?$B$BИ что послужило причиной его смерти – уж не этот ли самый предмет?', NULL, NULL, NULL, 'Странный предмет исследован', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9972, 'Кольцо Крови: Скрагат', 'Ты сметаешь их всех, $gмалыш:красавица:! Валишь просто пачками! На следующий поединок они выставляют действительно сильного бойца. Говорят, он повелитель Бездны или как там его... В общем, они в нем уверены. Ты $gслышал:слышала:, как этот слабак Могор тявкал на тебя, словно грязная шавка? Ставки взлетели до небес!$B$BНо я в тебя верю. Сейчас ты войдешь в этот круг и по-быстрому прикончишь их хваленого бойца!', 'Одержите победу над Скрагатом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.', 'МАЛЫШ! СВЕРШИЛОСЬ! Следующий бой будет воистину грандиозным! Бой за звание чемпиона!$B$BБрось, не стоит паниковать. Спокойствие, только спокойствие! Мы же не хотим, чтобы эти огры узнали, что у нас тут затевается кое-что интересное. В конце концов, у меня есть и свой интерес. И своя доля во всем этом деле.', NULL, NULL, NULL, 'Победа над Скрагатом одержана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9973, 'Кольцо Крови: чемпион клана Боевого Молота', 'Им пришлось привезти этого бойца из гладиаторских ям Острогорья. Его тренировали на горных великанах – он выходил в одиночку против троих...$B$BЕсли ты выиграешь этот бой, то станешь новым чемпионом. Как ты думаешь, каковы твои шансы, $gмалыш:красавица:? Ну что, попробуешь? Скажи только слово, и я поставлю на тебя целое состояние.$B$BА теперь иди и побеждай!', 'Одержите победу над чемпионом клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.', 'О, боги. Герой Боевого Молота Могор желает воспользоваться своим правом выйти на бой. Тебе придется сразиться с ним!$B$BИ знаешь, молотобойцы ведь не зря так зовутся.', 'Поединок закончится только тогда, когда один из вас упадет замертво.', NULL, NULL, 'Победа над чемпионом клана Боевого Молота одержана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9974, 'Последние реагенты', 'Я могу изготовить предмет, который нейтрализует охранные заклинания Гнездовья Шалас. Но предупреждаю, $N – магия будет действовать только пока вашего друга удерживают в плену. Я не стану добровольно давать вам средства для нападения на мой народ.$B$BУ меня есть почти все нужные материалы, но кое-что придется добыть вам. Мне потребуются сущности прыгуаны-охотника и горсть тероккарской черной рябины. Все это можно найти поблизости от Гнездовья.', 'Принесите 5 сущностей прыгуаны-охотника и 30 ягод тероккарской черной рябины Кокореку в Гнездовье Литик.', '', NULL, NULL, NULL, 'Сущность прыгуаны-охотника', 'Тероккарская черная рябина', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9975, 'Изначальная магия', 'Я заключил заклинание в этот талисман. Выпустите его рядом с охранными тотемами на подходе к Гнездовью Шалас – этого должно хватить для снятия защиты.$B$B<Вы обращаете внимание на то, что фигурка в талисмане совсем не похожа на араккоа:$B$BМой народ не всегда выглядел так, как сейчас. Когда-то мы были великолепными созданиями, но... слишком много раз сделали неправильный выбор, и провалили свою священную миссию. Это стоило нам нашей красоты, нашей силы и едва ли не всей нашей жизни. Не повторяйте наших ошибок, $N.', 'Используйте талисман Кокорека возле тотемов, охраняющих завесу Шалас, после чего поговорите с геологом Бальморалом.', '', NULL, NULL, NULL, 'Используйте талисман Кокорека', 'Талисман Кокорека', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9976, 'Изначальная магия', 'Я заключил заклинание в этот талисман. Выпустите его рядом с охранными тотемами на подходе к Гнездовью Шалас – этого должно хватить для снятия защиты.$B$B*Вы обращаете внимание на то, что фигурка в талисмане совсем не похожа на араккоа*$B$BМой народ не всегда выглядел так, как сейчас. Когда-то мы были великолепными созданиями, но... слишком много раз сделали неправильный выбор, и провалили свою священную миссию. Это стоило нам нашей красоты, нашей силы и едва ли не всей нашей жизни. Не повторяйте наших ошибок, $N.', 'Используйте талисман Кокорека возле тотемов, охраняющих завесу Шалас, после чего поговорите с наблюдателем Нодаком.', '', NULL, NULL, NULL, 'Используйте талисман Кокорека', 'Талисман Кокорека', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9977, 'Кольцо Крови: последнее испытание', '$gГаргток пересчитывает монеты в большой куче золота.>$B$BТвоими стараниями, $gмалыш:красавица:, я сделал хорошие деньги. Если сумеешь побить Могора, даю тебе слово, что твои усилия не пропадут даром. Вся боль, которую ты $gиспытал:испытала: в Кольце Крови, вознаградится вдвойне!$B$BВойди в Кольцо Крови и покажи этим ограм, на что ты $gспособен:способна:!', 'Одержите победу над Могором, героем клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.', 'Гаргток обещал, что ты получишь достойную награду. И он свое слово сдержит!', 'Поединок закончится только тогда, когда один из вас упадет замертво.', NULL, NULL, 'Победа над Могором, героем Боевого Молота, одержана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9978, 'Любыми средствами', 'Не знаю, что все это значит, но знаю, где нам найти еще подсказок.$B$BЕсть такой торговец – Эмпур – у него можно купить любой товар и любую информацию. Если сумеешь его разговорить, то он наверняка скажет много интересного.$B$BОн путешествует по дороге между Тууремом и Шаттратом. Но будь начеку – у Эмпура есть телохранитель.', 'Найдите Эмпура на дороге между и Тууремом и Шаттратом в лесу Тероккар. Убедите его рассказать вам все, что ему известно.', 'Хорошо, хорошо... Я скажу тебе, что знаю, только знаю я не так уж много!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9979, 'Латрай Торговец Ветром', 'Меня попросили забрать у некоего эфириала несколько коробок с товарами и доставить их по назначению.$B$BПоследний раз я видел его возле таверны \"На краю земли\" в Нижнем городе. Звать его торговец ветром Латрай, и это все, что я знаю!$B$BОб остальном расспрашивай у него!', 'Поговорите с торговцем ветром Латраем возле таверны \"На краю земли\" в Нижнем городе Шаттрата.', 'Да? Чем могу помочь, $R?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9980, 'Спасите Дейрома!', 'Как можно быстрее отправляйтесь в завесу Шалас, $N! Время не терпит. Когда араккоа прознают, что вы сделали с их защитой, они попытаются перевезти Дейрома в другое место или даже убить его!$B$BЕсли можете, возьмите с собой друга, или даже двоих – вам там придется нелегко. Эти птицелюди очень дорожат пленником, и просто так с ним не расстанутся. Когда найдете Дейрома и расправитесь с его похитителями, возвращайтесь в Бастион Аллерии и поговорите с Тандером.', 'Проберитесь в гнездовье Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Леди Дене Кеннеди в Бастионе Аллерии.', '', NULL, NULL, NULL, 'Луанга Пленитель убито', 'Освободите Дейрома', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9981, 'Спасите Дугара!', 'Как можно быстрее отправляйтесь в завесу Шалас, $N! Время не терпит. Когда араккоа прознают, что вы сделали с их защитой, они попытаются перевезти Дугара в другое место или даже убить его!$B$BЕсли можете, возьмите с собой друга, или даже двоих – вам там придется нелегко. Эти птицелюди очень дорожат пленником, и просто так с ним не расстанутся. Когда найдете Дугара и расправитесь с его похитителями, возвращайтесь в Форт Камнеломов и поговорите с Рокагом.', 'Проберитесь в завесу Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Рокагу в Форте Камнеломов.', '', NULL, NULL, NULL, 'Луанга Пленитель убито', 'Освободите Дугара', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9982, 'Его звали Алтруис...', 'На прошлой неделе в наш город прибыл незнакомец верхом на драконе Пустоты. Он назвался Алтруисом и принялся расспрашивать про Награнд.$B$BУтверждал, что охотится на тварей Легиона. Что это безумие – его работа. Ты представляешь?! Чтобы кто-то по собственной воле охотился на демонов?!$B$BПрежде, чем покинуть нас, он просил передать всем смельчакам, что будет ждать их в западном Награнде. Так что, если тебе хочется подвигов, обратись к нему.', 'Если у вас есть желание сразиться с Пылающим Легионом, разыщите Алтруиса Страдальца в западном Награнде.', 'Тебя пугает мой вид? Ты знаешь, кто я?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9983, 'Его звали Алтруис...', 'На прошлой неделе в наш город прибыл незнакомец верхом на драконе Пустоты. Он назвался Алтруисом и принялся расспрашивать про Награнд.$B$BУтверждал, что охотится на тварей Легиона. Что это безумие – его работа. Ты представляешь?! Чтобы кто-то по собственной воле охотился на демонов?!$B$BПрежде, чем покинуть нас, он просил передать всем смельчакам, что будет ждать их в западном Награнде. Так что, если тебе хочется подвигов, обратись к нему.', 'Если у вас есть желание сразиться с Пылающим Легионом, разыщите Алтруиса Страдальца в западном Награнде.', 'Тебя пугает мой вид? Ты знаешь, кто я?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9984, 'Хозяин Сокрытого Города', 'Вы не можете прочитать текст свитка, но узорная печать внизу явно принадлежит некоему высокопоставленному араккоа. Даже если Луанга и руководил похищением и допросом Дейрома, приказы он принимал от кого-то еще.$B$BТандер упоминал, что Андарл изучает араккоа – возможно, он сумеет расшифровать содержимое свитка.', 'Отнесите приказы Луанги Андарлу в Бастион Аллерии, что в лесу Тероккар.', '', NULL, NULL, NULL, 'Приказы Луанги (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9985, 'Хозяин Сокрытого Города', 'Вы не можете прочитать текст свитка, но узорная печать внизу явно принадлежит некоему высокопоставленному араккоа. Даже если Луанга и руководил похищением и допросом Дугара, приказы он принимал от кого-то еще.$B$BРокаг упоминал, что Каргаток изучает араккоа – возможно, он сумеет расшифровать содержимое свитка.', 'Отнесите приказы Луанги Каргатоку в Форт Камнеломов, что в лесу Тероккар.', '', NULL, NULL, NULL, 'Приказы Луанги (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9986, 'Сдержать араккоа', 'Нужно показать араккоа, что за нападения на наших людей их ждет быстрая и жесткая расправа. Если не остановить их сейчас, ни торговцы, ни курьеры, ни солдаты больше не смогут спокойно передвигаться по этим дорогам.$B$BМои разведчики донесли мне, что в каждом поселении араккоа есть лидер – их зовут Ашказ, Аийт и Урдак, и живут они соответственно в гнездовьях Рескк, Шиенор и Скит. Найдите их и убейте.', 'Убейте Ашказа в гнездовье Рескк, Аийта в гнездовье Шиенор и Урдака в гнездовье Скит, после чего вернитесь к Тандеру в бастион Аллерии.', 'Замечательно, $N. Теперь можно не беспокоиться хотя бы о том, что араккоа нападут на наших торговцев и курьеров - и без этого забот полно.', NULL, NULL, NULL, 'Ашказ убито', 'Аийт убито', 'Урдак убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9987, 'Сдержать араккоа', 'Нужно показать араккоа, что за нападения на наших людей их ждет быстрая и жесткая расправа. Если не остановить их сейчас, ни торговцы, ни курьеры, ни солдаты больше не смогут спокойно передвигаться по этим дорогам.$B$BМои разведчики донесли мне, что в каждом поселении араккоа есть лидер – их зовут Ашказ, Аийт и Урдак, и живут они соответственно в гнездовьях Рескк, Шиенор и Скит. Найдите их и убейте.', 'Убейте Ашказа в гнездовье Рескк, Айита в гнездовье Шиенор и Урдака в гнездовье Скит, после чего вернитесь к Рокагу в форт Камнеломов.', 'Замечательно, $N. Теперь можно не беспокоиться хотя бы о том, что араккоа нападут на наших торговцев и курьеров - и без этого забот полно.', NULL, NULL, NULL, 'Ашказ убито', 'Аийт убито', 'Урдак убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9988, 'Лучший друг щеголя', 'Не дайте Тандеру и его шайке обмануть вас! Они, может, и похожи на отряд суровых воинов, но под стальными доспехами скрываются обычные пижоны!$B$BА уж без своих шляп они в жизни на публике не покажутся. Эти шляпы сшиты из фетра и меха, и украшены самыми яркими перьями, которые только можно найти.$B$BСамые красивые перья, разумеется, у араккоа, и они-то как раз у меня и заканчиваются. Если принесете мне пучок, я с радостью заплачу вам за него.', 'Принесите 30 перьев араккоа Роз\'алете в бастион Аллерии.', '', NULL, NULL, NULL, 'Перо араккоа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9989, 'Неведомые духи', 'Когда я впервые попал в Запределье и прислушался к голосам местных духов, я был поражен тем, что услышал. Со временем я также начал замечать, что есть духи, чьих голосов я слышать не могу.$B$BНапример, несмотря на все мои старания, я так и не смог установить связь с духом предков араккоа. Их магия полностью отличается от нашей, но, думаю, поговорить с их духами все же возможно.$B$BПринесите мне побольше перьев араккоа, возможно, с их помощью мне удастся установить связь с духом.', 'Принесите 30 перьев араккоа Малуказу в форт Камнеломов.', '', NULL, NULL, NULL, 'Перо араккоа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9990, 'Исследование Туурема', 'Знаешь, я и правда вспомнил: около месяца назад Эмпур купил у меня несколько коробок каких-то странных деталей. Я не знаю, зачем они были нужны, но могу точно сказать, что их доставили в Туурем.$B$BМожет, там еще завалялся один из тех ящиков?', 'Найдите запечатанный ларец и отнесите его заклинателю земли Тавгрену. Тавгрена можно найти около перелеска Кенария в лесу Тероккар.', 'Эфириалы? Товары, доставляемые в Туурем? Странные детали? И эльф крови, готовый доставить последний ящик в лагерь Огнекрылых?$B$BЧто все это означает?! Какое отношение это имеет к тому, что случилось с друидами в перелеске Кенария?!$B$BНадо посмотреть, что там в коробке.', 'Какие вести с фронта, $N?', NULL, NULL, 'Запечатанный ларец', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9991, 'Разведка', 'Ты будешь моими глазами, но тебе придется проявить усердие. Нетрандамус пронесет тебя над лагерями Легиона, и ты $gдолжен:должна: будешь запомнить все, что увидишь. Вплоть до мельчайших деталей. Каждая мелочь, на первый взгляд несущественная и неважная, может нам пригодиться и оказаться весьма полезной для наших целей.$B$BИ самое главное - я хочу знать, какие там есть постройки и оборонительные сооружения, и как вообще организована защита лагерей.$B$BНетрандамус уже готов к полету. Он ждет только тебя, $N. Не бойся, с тобой ничего не случится. Мой дракон позаботится о твоей безопасности.', 'Приведите спинку кресла в вертикальное положение и пристегните ремни безопасности. Приятного полета! Когда закончите осмотр лагерей с воздуха, доложите Алтруису обо всем, что вы видели.', 'Отлично сработано, $N! Теперь мы знаем слабые места врага и можем планировать контратаку.', NULL, NULL, NULL, 'Осмотрите лагеря Легиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9992, 'Семена олембы', 'Взгляните на лесные деревья, разве они не прекрасны? Я часто задаюсь вопросом, приживутся ли такие в Азероте?$B$BМне бы не хотелось отправлять туда саженцы, потому что они могут не пережить дороги. А вот мешочек семян – это самое то, их перевозить безопасно. Семена обычно содержатся в крепких шишках, которые падают с деревьев, когда созревают.$B$BЕсли вдруг увидите шишку на земле, то постарайтесь выковырять из нее семена и принесите мне, ладно?', 'Соберите 30 семян олембы и отнесите их Роз\'алете в бастион Аллерии.', 'Спасибо за семена! У меня набралось почти достаточно для отправки первой партии!', 'Я начала собирать семена, но мне потребуется некоторая помощь, прежде чем я смогу отправить их в Штормград.', NULL, NULL, 'Семя олембы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9993, 'Масло из семян олембы', 'Маслянистые семена лесной олембы обладают очень большой ценностью. Мне бы хотелось собрать их побольше, выжать масло и посмотреть, что с ним можно сделать.$B$BТолько подумайте – целый лес семян, которые пропадают зря! Неважно, где его можно использовать – в готовке, в лампах или для смазки оружия, я не позволю ему пропадать впустую!$B$BПринесите мне семена, которые сумеете собрать – они там повсюду.', 'Принесите 30 семян олембы Ракории в форт Камнеломов.', 'Неплохо, но для того, чтобы изготовить достаточное количество масла, потребуется куда больше.', 'Вы принесли мне семян?', NULL, NULL, 'Семя олембы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9994, 'Что это такое?', 'Не знаю, как ты, а я понятия не имею, что это за штуки, но могу сказать точно, что выглядят они опасно!$B$B$N, мне кажется, тебе надо отнести эту коробку Дженайе Шепот Звезд в бастион Аллерии, это к юго-востоку отсюда. Может, она знает, что это.', 'Доставьте ящик с деталями Дженайе Шепот Звезд в бастион Аллерии в лесу Тероккар.', 'О нет! Какие ужасные вести! Неужели из всех наших друзей в живых осталось только двое?!$B$BХорошо, дайте-ка взглянуть на эти части. Надеюсь, это не то, о чем я думаю.$B$BДа, все именно так, как я и боялась – это детали бомбы. Наши разведчики из Шаттрата передавали нам информацию о том, что некоторые духи Астрала ввозят запрещенные товары из других измерений, с которыми у них налажены связи.', 'Вас что-то тревожит. Что такое, $C?', NULL, NULL, 'Ящик с деталями (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9995, 'Что это такое?', 'Не знаю, как ты, а я понятия не имею, что это за штуки, но могу сказать точно, что выглядят они опасно!$B$B$N, мне кажется, тебе надо отнести эту коробку Туки в форт Камнеломов, это к юго-востоку отсюда. Может, он знает, что это.', 'Доставьте ящик с деталями Туки в форт Камнеломов в лесу Тероккар.', 'О нет! Какие ужасные вести! Неужели из всех наших друзей в живых осталось только двое?!$B$BХорошо, дайте-ка взглянуть на эти части. Надеюсь, это не то, о чем я думаю.', 'Вас что-то тревожит. Что такое, $C?', NULL, NULL, 'Ящик с деталями (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9996, 'Нападение на лагерь Огнекрылых', 'Мы знаем, что эльфы крови из лагеря Огнекрылых работают на Кель\'таса и Иллидана. А судя по твоим рассказам, они используют Сломленных из Туурема для того, чтобы те поставляли им необходимые ресурсы для создания какого-то ужасного оружия.$B$BЧто бы они там ни затевали, самое эффективное, что мы можем сделать сейчас – это уменьшить их численность.$B$BТак что отправляйся в лагерь – это к северо-востоку отсюда – и убей как можно больше тамошних эльфов крови.', 'Убейте 10 защитников, 10 кровавых стражей и 10 чернокнижников из армии Огнекрылых, после чего вернитесь к лейтенанту Меридиану на заставу Аллерии в лесу Тероккар.', 'Для начала неплохо, но судя по тому, что вы там видели, и тому, что мне донесла разведка, у нас появилось куда более неотложное дело!', NULL, NULL, NULL, 'Защитник из армии Огнекрылых убито', 'Кровавый страж из армии Огнекрылых убито', 'Чернокнижник из армии Огнекрылых убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9997, 'Нападение на лагерь Огнекрылых', 'Мы знаем, что эльфы крови из лагеря Огнекрылых работают на Кель\'таса и Иллидана. А судя по твоим рассказам, они используют Сломленных из Туурема для того, чтобы те поставляли им необходимые ресурсы для создания какого-то ужасного оружия.$B$BЧто бы они там ни затевали, самое эффективное, что мы можем сделать сейчас – это уменьшить их численность.$B$BТак что отправляйся в лагерь – это к северо-востоку отсюда – и убей как можно больше тамошних эльфов крови.', 'Убейте 10 защитников, 10 кровавых стражей и 10 чернокнижников из армии Огнекрылых, после чего поговорите с сержантом Чауни в лагере Камнеломов, что в лесу Тероккар.', 'Для начала неплохо, но судя по тому, что вы там видели, и тому, что мне донесла разведка, у нас появилось куда более неотложное дело!', 'Докладывай. Какие новости в лагере Огнекрылых?', NULL, NULL, 'Защитник из армии Огнекрылых убито', 'Кровавый страж из армии Огнекрылых убито', 'Чернокнижник из армии Огнекрылых убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9998, 'Беспокойные соседи', 'Недавнее появление орков Скверны в руинах очень озадачило и напугало Тандера. Они не покладая рук возводят укрепления и ремонтируют здания. Стройка не останавливается ни днем, ни ночью, $N. Я отправил туда одного из своих лучших агентов, чтобы он наблюдал за постройкой, но мы не можем оставаться в бездействии. Убей их рабочих, а потом поговори с Телорией Плащ Теней на заставе Аллерии – это к северу от руин Костеглодов. Она расскажет, что делать дальше.', 'Убейте 12 астральных батраков и доложите об этом Телории Плащ Теней на заставу Аллерии.', '<Высшая эльфийка кивает.>$B$BНеплохо для начала, но Бертельм правильно сделал, что прислал тебя ко мне. Я обнаружила кое-что, что может объяснить присутствие здесь этих орков Скверны.', NULL, NULL, NULL, 'Астральный батрак убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (9999, 'Выиграть время', 'Пока у них есть транспортеры, наши набеги на Лагеря легиона не дадут никакого результата. Надо найти способ разрушить постройки Легиона.$B$BМне нужно время на разработку плана атаки. Если ты сможешь отвлечь вражеских инженеров и $Nнщиков, мы выиграем драгоценное время.$B$BДержись подальше от надзирателей, $N. Это очень опасные существа.', 'Убейте 2 стражей Скверны - легионеров, 3 мо\'аргов-инжененеров и 8 ган\'аргов-ремонтников.', 'Этого я и боялся. Железо Скверны так просто не уничтожить. Но отчаиваться рано...', 'Что, уже вернулся?', NULL, NULL, 'Страж Скверны - легионер убито', 'Мо\'арг-инженер убито', 'Ган\'арг-ремонтник убито', 'Рекомендуемое количество игроков: 3');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10000, 'Нежелательное присутствие', 'Наши воины из Траллмара считали, что орки Скверны не осмелятся высунуться из цитадели Адского Пламени и прилегающих территорий, но разведчики, вернувшиеся из руин к востоку отсюда, говорят совершенно противоположное.$B$BНельзя дать им закрепиться там. Рокаг отправил в руины тенелова Кайда, но в одиночку он может лишь наблюдать.$B$BОтправляйтесь в руины, убейте их батраков и поищите Кайда в роще на севере. Он скажет, что делать дальше.', 'Убейте 12 астральных батраков и доложите об этом тенелову Кайду.', 'Для того чтобы остановить орков Скверны, недостаточно пугать их рабочих. Я обнаружил кое-что, что объясняет их присутствие здесь, и еще больше убедился в том, что действовать надо быстро.', NULL, NULL, NULL, 'Астральный батрак убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10001, 'Главный планировщик', 'Все лагеря Легиона строятся по единому плану, утвержденному главным планировщиком. Он всегда таскает при себе целую кипу чертежей. Они-то нам и нужны.$B$BОбладая детальной информацией, мы сможем уговорить одного моего знакомого оказать нам содействие.$B$BРазыщи мо\'арга-главного планировщика и отними у него чертежи. Ты найдешь его за кузницами.', 'Алтруис Страдалец из западного Награнда просит вас раздобыть чертежи главного планировщика.', 'Надеюсь, мой знакомый найдет способ стереть эти лагеря с лица земли. В конце концов, он когда-то был инженером в Легионе…', 'Любым способом избегай встречи с надзирателями. Они не должны тебя заметить. Иначе может случиться беда!', NULL, NULL, 'Чертежи главного планировщика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10002, 'Посредник Огнекрылых', 'За последние пару дней я видела, как в крепость орков Скверны и обратно ходила эльфийка крови, а еще она разговаривала с их лидером. Судя по жестам, она явно отдавала ему приказы. Но почему? Чьи приказы она ему передает?$B$BЛюбопытство не давало мне покоя, поэтому я последовала за ней, когда она вышла из лагеря орков. Эльфийка направилась на север, в лагерь Огнекрылых, но туда я за ней не пошла.$B$BУбей эту эльфийку до того, как она в следующий раз выйдет из лагеря орков Скверны.', 'Найдите и убейте Лизель Огнепрядку, после чего вернитесь к Телории Плащ Теней.', '<Телория кивает.>$B$BПрекрасно, мы выиграли немного времени. Эльфы крови непременно захотят узнать, что произошло с их подругой, но к тому времени, надеюсь, мы сумеем разобраться в их намерениях.', NULL, NULL, NULL, 'Лизель Огнепрядка убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10003, 'Посредник Огнекрылых', 'Последнюю пару дней я видел, как в крепость орков Скверны и обратно ходила эльфийка крови, а еще она разговаривала с их лидером. Судя по их жестам, она явно отдавала ему приказы. Но почему? Чьи приказы она ему передает?$B$BМое любопытство не давало мне покоя, поэтому я последовал за ней, когда она вышла из лагеря орков. Эльфийка направилась на север, в лагерь Огнекрылых, но я не рискнул проникать внутрь.$B$BУбей эту эльфийку до того, как она еще раз выйдет из лагеря орков Скверны.', 'Найдите и убейте Лизель Огнепрядку, после чего вернитесь к тенелову Кайду.', '<Кайд кивает.>$B$BПрекрасно, мы выиграли немного времени. Эльфы крови непременно захотят узнать, что произошло с их подругой, но к тому времени, надеюсь, мы сумеем разобраться в их намерениях.', NULL, NULL, NULL, 'Лизель Огнепрядка убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10004, 'Терпение и понимание', 'Возьми чертежи и отправляйся в город Шаттрат в лесу Тероккар. Добравшись до места, ступай в Нижний город и найди там мо\'арга по имени Саль\'салабим. Скорее всего, он сидит в баре, пытаясь утопить печаль в стакане.$B$BКстати, тебе придется как-то склонить его к сотрудничеству. Сначала попробуй интеллигентный подход: терпение и понимание. Если не поможет, набей ему морду.', 'Покажите чертежи главного планировщика Саль\'салабиму в Шаттрате и уговорите его помочь вам.', 'Тихо, ясноглазый! Саль\'салабим поможет.', '<Саль\'салабим чешет в затылке.>$B$B(говорит на языке демонов) Ик ил ромат сардон.', NULL, NULL, 'Чертежи главного планировщика (Прилагается)', 'Уговорите Саль\'салабима помочь вам.', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10005, 'Вести для землепряда Тавгрена', '$N, когда закончишь праздновать, думаю, тебе стоит отправиться в перелесок Кенария и поговорить там с заклинателем земли Тавгреном.$B$BУверен, он захочет узнать, что здесь произошло на самом деле.', 'Поговорите с заклинателем земли Тавгреном возле перелеска Кенария в лесу Тероккар.', 'Бомба на чистейшей мане, способная стирать с лица земли целые города! Но зачем? Зачем эльфам крови создавать нечто подобное и сбрасывать на нас? Перелесок Кенария всегда был мирным и спокойным местом.$B$BКаковы бы ни были причины, они наверняка сокрыты в сознании хранителя Древлоса, и я не имею ни малейшего понятия о том, как вылечить его. Быть может, его разум со временем излечится сам?$B$BЯ могу лишь надеяться на то, что такое несчастье больше никогда не постигнет нас!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10006, 'Вести для землепряда Тавгрена', '$N, когда закончишь праздновать, думаю, тебе стоит отправиться в перелесок Кенария и поговорить там с заклинателем земли Тавгреном.$B$BУверен, он захочет узнать, что здесь произошло на самом деле.', 'Поговорите с заклинателем земли Тавгреном возле перелеска Кенария в лесу Тероккар.', 'Бомба на чистейшей мане, способная стирать с лица земли целые города! Но зачем? Зачем эльфам крови создавать нечто подобное и сбрасывать на нас? Перелесок Кенария всегда был мирным и спокойным местом.$B$BКаковы бы ни были причины, они наверняка сокрыты в сознании хранителя Древлоса, и я не имею ни малейшего понятия о том, как вылечить его. Быть может, его разум со временем излечится сам?$B$BЯ могу лишь надеяться на то, что такое несчастье больше никогда не постигнет нас!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10007, 'Ослабление врага', 'Зная Тандера и Бертельма, я могу сказать, что они не позволили бы врагу собрать такую армию прямо у нас под носом. Просить их выслать своих воинов, чтобы те напали на лагерь – тоже не вариант, это лишь сделает нас еще более уязвимыми.$B$BОстается только ослабить орков Скверны – ты убей, сколько сможешь, а я прослежу, чтобы к ним не прорвалось подкрепление.', 'Убейте 10 уничтожителей и 6 спиноломов из клана Костеглодов, после чего вернитесь к Телории Плащ Теней.', 'Дело начинает проясняться. Думаю, что если мы сумеем не дать оркам закрепиться здесь, мы удержим позиции за собой.', NULL, NULL, NULL, 'Уничтожитель из клана Костеглодов убито', 'Спинолом из клана Костеглодов убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10008, 'Секреты Тероккара не покидают его границ', 'Если до Траллмара дойдет весть о том, что орков Скверны сдержать не удалось, у нас тут быстро нарисуется большая и веселая компания. Мне бы не хотелось привлекать столько внимания, поэтому нужно справиться с этой проблемой самим, понятно?$B$BЕсли мы сумеем нанести оркам Скверны достаточно потерь, то есть шанс, что об их присутствии не станет известно за пределами форта Камнеломов. Так что давай по-быстрому с этим разберемся.$B$BОтправляйся туда, доставай оружие, маши руками – в общем, делай, что хочешь, только поубивай этих орков.', 'Убейте 10 уничтожителей и 6 спиноломов из клана Костеглодов по просьбе тенелова Кайда.', 'Я знаю, что вы много путешествовали и о многом можете рассказать, $N, но некоторым историям лучше оставаться на том месте, где они произошли. Понимаете, о чем я?', NULL, NULL, NULL, 'Уничтожитель из клана Костеглодов убито', 'Спинолом из клана Костеглодов убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10009, 'Золото за тумаки', '$gСаль\'салабим смеется.>$B$BЭто все Саль\'салабим придумал.$B$B<Саль\'салабим показывает на строительные чертежи.>$B$BГляди – башни. Охотник за демонами ничего не видать! Бедный, бедный Алтруис. Был бы глаз – он бы плакать. $B$BДа, Саль\'салабим дам помощь, но первый ты дай помощь Саль\'салабиму.$B$B<Саль\'салабим вручает вам список.>$B$BЭти должен Саль\'салабим золотой. Много золотой. Ходи возьми золотой для Саль\'салабим. Они не захочет отдать Саль\'салабим золотой так просто. Надо побить, но ты – $gсильный:сильная:. Ты же $gпобил:побила: Саль\'салабим!', 'Взыщите долги с Ралика, Куш\'куша и Флуна.', 'Саль\'салабим держит свой договор, только ты не будь злой потом, да?', 'Обратно не ходи без золотых Саль\'салабима!', NULL, NULL, 'Долг Ралика', 'Долг Куш\'куша', 'Долг Флуна', 'Рекомендуемое количество игроков: 3');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10010, 'Не так просто?', '$gСаль\'салабим тычет в чертеж.>$B$BПушку Скверны $gвидел:видела:?$B$B<Саль\'салабим рисует стрелку, обозначая поворот.>$B$BПовороти пушку и стреляй в дом.$B$BСтой! Не торопись! Ты $gпонял:поняла: не все. Для поворота пушки надзиратель имеет ключ. Сначала имей ключ! Один от каждого надзирателя!$B$BНе так легко, а?$B$BРасскажи Алтруису.', 'Вернитесь к Алтруису Страдальцу в западный Награнд.', 'Ну конечно! Мы побьем их собственным оружием!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10011, 'Лагеря Легиона: уничтожены', 'Зови союзников, $N. Ты не справишься в одиночку. Тебе понадобится поддержка, если ты собираешься выйти против надзирателей.$B$BКогда соберешь подходящий отряд, найдите в каждом из лагерей тамошних надзирателей, убейте их и заберите у них ключи, чтобы активировать пушки Скверны и направить их на лагеря. Когда уничтожите оба лагеря, возвращайся ко мне.', 'Уничтожьте лагеря Легиона: Страх и Ненависть. ', 'Мы побеждаем! Нам удалось сдержать натиск Легиона!$B$BТы совершил героический подвиг и теперь можешь выбрать награду.', 'Дело сделано?', NULL, NULL, 'Уничтожьте лагерь Легиона: Ненависть', 'Уничтожьте лагерь Легиона: Страх', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10012, 'Планы орков Скверны', 'Надписи на планах слишком красивые и четкие, чтобы принадлежать перу орка Скверны. Вы не можете разобрать текста, но и без этого понятно, что орки получают указания от эльфов крови из лагеря Огнекрылых.$B$BНо зачем бы им работать сообща? Наверное, стоит спросить об этом у Бертельма – нужно вернуться в бастион Аллерии и показать ему карту.', 'Добудьте планы орков Скверны для Бертельма в Бастионе Аллерии, что в лесу Тероккар.', '<Бертельм берет у вас планы и изучает их.>$B$BЕсли бы вы не принесли мне эту карту, я бы подумал, что вы выжили из ума, однако вот она, тут! Орки Скверны не только служат эльфам крови, но им еще и приказано отвлекать нас.$B$BЭта карта дает вопросов больше, чем ответов, но, по крайней мере, мы теперь знаем, с чем имеем дело.', 'Что у вас там, $N?', NULL, NULL, 'Планы орков Скверны (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10013, 'Невидимая длань', 'Надписи на планах слишком красивые и четкие, чтобы принадлежать перу орка Скверны. Вы не можете разобрать текста, но и без этого понятно, что орки получают указания от эльфов крови из лагеря Огнекрылых.$B$BНо зачем бы им работать сообща? Наверное, стоит спросить об этом у Рокага – нужно вернуться в форт Камнеломов и показать ему карту.', 'Добудьте планы орков Скверны для Рокага. Его можно найти в Форте Камнеломов, что в лесу Тероккар.', '*Рокаг берет у вас планы и изучает их*$B$BКайд все же был прав! Эти гнусные орки Скверны и впрямь что-то затевали, хотя я бы в жизни не подумал, что они скооперируются с эльфами крови.$B$BСудя по карте, орки должны отвлекать нас... но от чего? Это очень нехорошие новости, $N. вы правильно сделали, что сразу вернулись ко мне.', 'Что у вас там, $N?', NULL, NULL, 'Планы орков Скверны (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10014, 'Проект лагеря Огнекрылых', 'Как я и говорил, по новым данным разведки, у нас возникла еще одна, гораздо большая проблема.$B$BЭльфы крови не покладая рук собирают в лагере Огнекрылых еще одну бомбу, и я не могу даже выразить всю серьезность последствий, которые ждут нас, сбрось они эту бомбу в бастион Аллерии.$B$BМои разведчики доложили, что коды от этой бомбы прячут в четырех зданиях вокруг центрального двора. Проберись туда и укради коды, пока еще не поздно!', 'Украдите 4 листа кодирования мана-бомб и отнесите их лейтенанту Меридиану на заставу Аллерии в лесу Тероккар.', '', NULL, NULL, NULL, 'Мана-бомба - лист кодирования 1', 'Мана-бомба - лист кодирования 2', 'Мана-бомба - лист кодирования 3', 'Мана-бомба - лист кодирования 4');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10015, 'Проект лагеря Огнекрылых', 'Как я и говорила, по новым данным разведки, у нас возникла еще одна, гораздо большая проблема.$B$BЭльфы крови не покладая рук собирают в лагере Огнекрылых еще одну бомбу, и я не могу даже выразить всю серьезность последствий, которые ждут нас, сбрось они эту бомбу на форт Камнеломов.$B$BМои разведчики доложили, что коды от этой бомбы прячут в четырех зданиях вокруг центрального двора. Проберись туда и укради коды, пока еще не поздно!', 'Украдите 4 листа кодирования мана-бомб и отнесите их сержанту Чауни в лагерь Камнеломов в лесу Тероккар.', '', NULL, NULL, NULL, 'Мана-бомба - лист кодирования 1', 'Мана-бомба - лист кодирования 2', 'Мана-бомба - лист кодирования 3', 'Мана-бомба - лист кодирования 4');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10016, 'Хвосты лесных воргов', 'Не встречались ли вам в ваших путешествиях лесные ворги? Когда я составлял карту северных регионов леса, то имел возможность понаблюдать за ними. Не советую вам приближаться к этим животным, если вы не готовы к бою.$B$BОни нисколько не боятся нас, и будут яростно защищать свою территорию.$B$BИ, разумеется, у таких существ потрясающие хвосты! Я хотел бы собрать немного, чтобы украсить новый плащ, но ворги постоянно обходят мои ловушки. Не хотите ли мне помочь?', 'Принесите 12 хвостов лесных воргов Бертельму в бастион Аллерии. Хвосты можно добыть с лесных воргов или их вожаков.', 'О, большое спасибо, друг мой. Эти хвостики даже еще лучше, чем я думал, из них выйдет прекрасный плащ.$B$B<Бертельм бросает быстрый взгляд на таверну.>$B$BО да, плащ выйдет отличный.', 'Вы не погибли в лесу, это очень хорошо! Удалось добыть хвостиков для моего плаща?', NULL, NULL, 'Хвост лесного ворга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10017, 'Нехватка припасов', 'С каждым днем в Шаттрат прибывает все больше и больше беженцев, и некоторые так изранены, что я удивляюсь, как они вообще смогли добраться сюда.$B$BС большинством ран я справляюсь – я прошла хорошее обучение у Алдоров, но вот с отравленными ранами дела обстоят хуже, потому что у меня кончаются запасы противоядий.$B$BПринесите мне ядовитых желез местных пауков-смертеплетов, чтобы я могла приготовить новые. Эти пауки живут на юго-востоке Тероккара.', 'Принесите 8 ядовитых желез пауков-смертеплетов Ша\'нир в Шаттрат.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Благодарю вас, $N. Алдоры непременно узнают о ваших деяниях.', 'Вы достали ядовитые железы, $N? Без лекарств беженцы долго не протянут.', NULL, NULL, 'Ядовитая железа Смертеплета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10018, 'Одежды духа волка', 'Много поколений назад, когда орочьи кланы еще считали лес Тероккар своим домом, дух волка играл очень важную роль в их жизни. Когда орки ушли оттуда, дух остался покинутым и потерял для них свою значимость.$B$BСо временем духу стало одиноко, и он тоже покинул лес.$B$BЯ думаю, что сумею помочь духу волка вернуться в свой родной дом так же, как вернулись и мы, орки! Однако для ритуала мне понадобятся одежды из шкур местных волков, чтобы духу было легче найти дорогу домой.', 'Принесите 12 шкур лесного ворга Малуказу в форт Камнеломов.', 'Отлично, $N! Лучше и быть не могло!', 'Вы нашли все шкуры, какие я просил?', NULL, NULL, 'Шкура лесного ворга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10019, 'Больше ядовитых желез', '', '', 'Большое спасибо, $N. Теперь, когда эти несчастные находятся под защитой наару в Шаттрате, было бы очень жаль, если б они умерли от полученных ран.$B$B*Это задание можно повторять до тех пор, пока вы не заслужите равнодушное отношение.*', NULL, NULL, NULL, 'Ядовитая железа Смертеплета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10020, 'Лекарство для Залии', 'Женщина справа от меня получила тяжелую травму головы. Она осталась жива, но потеряла зрение.$B$BСреди моего народа популярно лекарство, изготавливаемое из крови очень старого василиска.$B$BНо, к сожалению, на василисков Тероккара идет такая охота, что до старости они не доживают... Однако есть один василиск – я знаю о нем еще с детства, – его зовут \"Камневзор\", и вроде бы он живет к востоку отсюда, у края земли.$B$BПринесите мне его кровь, и тогда я смогу вернуть Залии зрение.', 'Принесите Ша\'нир в Шаттрат кровь Камневзора.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Спасибо, $N. Заботиться о больных нелегко, но со временем я поняла, что это само по себе является отличной наградой.', 'Вы достали кровь, $N? Без нее Залия может никогда больше не увидеть своего сына.', NULL, NULL, 'Кровь Камневзора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10021, 'Возрождение Света', 'Большую часть этой земли некогда населяли дренеи, а мы, Алдоры, должны были охранять наши священные города и алтари, многие из которых с тех пор были разрушены или захвачены врагами.$B$BК востоку отсюда находится застава араккоа. Предположительно, ее построили на месте наших трех священных алтарей, и теперь араккоа с помощью своей грязной магии искажают и оскверняют силу наших святынь.$B$BВозьмите с собой вот это и очистите три алтаря на заставе.', 'Отправляйтесь на заставу Араккоа, что к востоку от Шаттрата, и при помощи благословленного фиала очистите восточный, западный и северный алтари, после чего вернитесь к Ишане.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Благодарю вас, $N. Мы - хранители света, и даже в самые трудные времена не можем пренебрегать своим долгом.', 'Вы выполнили свое задание, $N?', NULL, NULL, 'Северный алтарь', 'Восточный алтарь', 'Западный Алтарь', 'Благословенный фиал');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10022, 'Неуловимый Железнозуб', 'Ну вот, мех на отделку у меня есть. Но я еще подумал, что из шкуры одного особенного волка может выйти отличный капюшон! Представьте, что вы увидели своего врага одетого в шкуру самого хитрого хищника из леса!$B$BЯ уже долго и безуспешно охочусь на Железнозуба – пытался загнать его в угол, перехитрить, приманить... Но ничего не получилось.$B$BОн бродит в северо-восточной части леса, и я с радостью награжу вас, если вам удастся сделать то, что не удалось мне.', 'Принесите шкуру Железнозуба Бертельму в бастион Аллерии.', 'Снимаю шляпу перед вашим мастерством, $N. Вы и впрямь превосходный охотник.$B$BЯ никогда не забуду, как вы помогли мне! Я сошью из этих шкур самый лучший плащ и буду с гордостью носить его.', 'Ну что, старина Железнозуб и вам задал трепку? Или вы сумели его перехитрить?', NULL, NULL, 'Шкура железнозуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10023, 'Патриарх Железнозуб', 'Что ж, шкуры, которые вы собрали, очень хороши.$B$BОднако для того, чтобы закончить одежды, мне понадобится еще одна, особенная шкура. Ее можно снять только с одного, очень старого и хитрого волка, считающемся патриархом всех лесных волков. Его называют Железнозуб – великий охотник.$B$BВ видениях мне открылось, что он бродит в северо-восточной области леса. Если я украшу его шкурой свои одежды, это непременно поможет духу волка найти верную дорогу.$B$BНо не стоит скорбеть по Железнозубу. Он счел бы это за честь.', 'Принесите шкуру Железнозуба Малуказу в форт Камнеломов.', 'Эта шкура еще прекраснее, чем я думал! Это добрый знак, $N, и духи непременно оценят все, что вы сделали для этой церемонии.$B$BВот, я сшил для вас шлем из оставшихся шкур, $N. Все, кто увидит вас в нем, поймут, что вы - великий охотник и союзник духа волка из леса Тероккар.', 'Дух ждет, $N. Вы принесли шкуру волчьего патриарха?', NULL, NULL, 'Шкура железнозуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10024, 'Видения Ворен\'таля', 'Наш лидер, Ворен\'таль Предсказатель, некогда был близким советником Кель\'таса. Его пророческие видения указывали на то, что действия Кель\'таса приведут к уничтожению нашего народа.$B$BОбычно эти видения довольно туманны и неточны, однако наши алхимики изобрели эликсир, который помогал Ворен\'талю видеть более ясно. К сожалению, для этого эликсира требуется очень редкий компонент – глаза василиска, а мой обычный поставщик – жалкий эфириал – подвел меня.$B$BРазыщи гладкоспинных василисков в скалистых районах Тероккара и принеси мне их глаза.', 'Принесите 8 глаз гладкоспинных василисков чародейке Адирии в Шаттрат.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Они в отличном состоянии, $N! Не останавливайтесь на достигнутом, и скоро Провидцы станут воспринимать вас как друга.', 'Вы добыли глаза василисков, необходимые для изготовления эликсира для Ворен\'таля?', NULL, NULL, 'Глаз гладкоспинного василиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10025, 'Больше глаз василисков', '', '', 'Спасибо, $N. Когда-нибудь, возможно, видения Ворен\'таля решат судьбу всей нашей расы, поэтому нам нужно проследить, чтобы они были точны, как никогда.$B$B<Это задание можно повторять до тех пор, пока вы не заслужите равнодушное отношение.:', NULL, NULL, NULL, 'Глаз гладкоспинного василиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10026, 'Нарушение магического равновесия', 'Мне немного неловко говорить об этом, но в лесу Тероккар со мной произошло кое-что неприятное, чего со мной не приключалось со времен студенчества.$B$BМои заклинания вдруг перестали действовать, хотя я все делал правильно! Когда это произошло в первый раз, я чуть с ума не сошел.$B$BНо, кажется, я узнал причину. В лесу полно прыгуан – эти существа очень тонко чувствуют магию и могут изменять течение ее потоков. Самый легкий способ разобраться с ними – это просто их поубивать.', 'Убейте 10 прыгуан по просьбе Андарла из бастиона Аллерии.', '<Андарл вытирает лоб рукавом мантии.>$B$BУфф... Большое спасибо! Если бы эти твари остались в живых, они бы причиняли нам массу неудобств.', NULL, NULL, NULL, 'Прыгуана убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10027, 'Нарушение магического равновесия', 'Когда готовишься прочитать заклинание, а его вдруг прерывает какая-то неведомая сила, это просто выводит из себя! Когда это произошло во второй раз, я понял, что это не совпадение, и отправил Кеб\'езила выяснить, что происходит.$B$BУверяю вас, такого болтливого беса, как Кеб, вы не встретите никогда и нигде.$B$BОн отыскал-таки источник проблемы – мерзкую тварь под названием прыгуана. Они изменяют течение магических потоков везде, где бы ни находились, но я больше не намерен этого терпеть!', 'Убейте 10 прыгуан и вернитесь к Каргатоку в форт Камнеломов.', 'Кеб\'езил очень рад, что вы разобрались с этой проблемой, правда, Кеб?$B$B<Бес не обращает на хозяина ни малейшего внимания. Возможно, он слишком возмущен.>$B$BПростите его за дурные манеры. Демоны, что с них взять...', NULL, NULL, NULL, 'Прыгуана убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10028, 'Сосуды силы', 'В руинах Туурема разбросано множество сосудов, в которых заключена чистая магическая энергия. Нам повезло, что Сломленные, которые захватили город, не обратили внимания на тамошние ресурсы, но, думаю, долго это не продлится.$B$BНекоторым представителям моего народа удалось выжить, и если они получат эти сосуды, то смогут сопротивляться демонической магии. Каждый кель\'дорай, спасенный от злых чар нашего принца – это лишний шанс вернуть нашу былую славу. Принеси мне эти сосуды, $C.', 'Принесите 8 сосудов дренеев Роз\'алете в бастион Аллерии.', 'Надеюсь, это не все сосуды, что были в том городе. На первое время этого хватит, но потом нам потребуется намного больше.', 'Удалось найти неповрежденные сосуды?', NULL, NULL, 'Дренейский сосуд', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10029, 'Зов духов', 'Духи мертвых взывают ко мне из Костяных пустошей, и молят избавить их от страшной боли!$B$B$C, тебе нужно отправиться на Костяные пустоши, к югу отсюда, и найти там моего помощника Сулавина в караване беженцев. Он, должно быть, тоже слышит зов духов, и ему потребуется твоя помощь, чтобы успокоить их.$B$BЕсли поспешишь, то сумеешь их догнать. Я знаю, что они собирались делать остановку в северной части Костяных пустошей, а потом двинуться южнее, в Аукиндон.', 'Найдите помощника анахоретки Литиры по имени Сулавин в караване беженцев на Костяных пустошах в лесу Тероккар.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10030, 'Сбор останков', 'Костяные пустоши усеяны костями дренеев, погибших при взрыве в Аукиндоне. Их души до сих пор не упокоены и не могут перейти к следующей жизни.$B$B$C, помоги мне собрать их кости и похоронить их как следует. Только после этого они, наконец, обретут покой.$B$BСобери разбросанные кости и отнеси их Рамдору Безумному в Аукиндон, что в центре Костяных пустошей. Несмотря на свое имя, он как нельзя лучше позаботится о них.', 'Соберите 10 неупокоенных костей и отнесите их Рамдору Безумному на западную сторону Ритуального круга в Аукиндоне. Аукиндон находится в центре Костяных пустошей в лесу Тероккар.', 'Отлично, именно этого мне и не хватало... еще костей.$B$B<Рамдор вздыхает.>$B$BДа, да, я прослежу за тем, чтобы эти останки наших высокочтимых предков были надлежащим образом захоронены, так что не беспокойся.$B$BА раз уж ты так хочешь помочь мертвым, то я могу дать тебе еще одно дело.', 'Что это? Вы кто?', NULL, NULL, 'Неупокоенные кости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10031, 'Возвращение заблудших душ', 'Взрыв в Аукиндоне осквернил души многих дренеев, и теперь они в мучениях блуждают по Костяным пустошам.$B$BЯ нижайше прошу тебя даровать им покой. Уничтожь заблудших духов и скелетов сломленных, что блуждают по Костяным пустошам за стенами Аукиндона.$B$BЧто? Думаешь, лучше позволить им и дальше блуждать там и мучиться в агонии?$B$BКогда закончишь, поговори с Сулавином в караване беженцев и расскажи ему все.', 'Уничтожьте 10 заблудших духов и 10 скелетов Сломленных, после чего поговорите с Сулавином в караване беженцев в Костяных пустошах леса Тероккар.', 'Вы сделали то, что нужно было сделать, и прощения просить вам не за что. То, что они превратились в ужасную нежить, разумеется, очень печально, но вы упокоили их, и это хорошо.$B$BСпасибо, что освободили эти бедные души, $N. Примите этот скромный дар в знак моей благодарности за вашу работу.', NULL, NULL, NULL, 'Заблудший дух убито', 'Скелет сломленного убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10033, 'Награда за убитых костеклювов!', 'Костеклювы с костяных пустошей – разносчики чумы, поэтому за их уничтожение назначена награда.$B$BКостеклювов можно найти на всей территории пустошей, но больше всего их скапливается на холме Падальщика, что к северу.$B$BЗа наградой обращаться к Тэле Вечной Страннице.', 'Убейте 20 костеклювов и вернитесь к Тэле Вечной Страннице в бастион Аллерии в лесу Тероккар.', 'О, разумеется, вы убили целую стаю костеклювов! Вы читали сообщение капитана о том, что нужно приносить мне доказательства?$B$B<Таэла смотрит на вас с сарказмом.>$B$BЛадно, поверю на слово. Не знаю уж, за что мне такое наказание, но благодарю вас за ваши усилия от имени всего Альянса. Вот вам награда за труды.', NULL, NULL, NULL, 'Костеклюв убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10034, 'Награда за убитых костеклювов!', 'Костеклювы с Костяных пустошей искусали Мауга, и теперь ему больно! Он хочет, чтобы все они исчезли!$B$BИх можно найти в любом месте Костяных пустошей, но больше всего живет на холме Падальщика.$B$BКогда убьете всех, приходите к Маугу Лютострелу и получите хорошую награду.', 'Убейте 20 костеклювов и вернитесь к Маугу Лютострелу в форт Камнеломов в лесу Тероккар.', 'Вы, должно быть, убили много костеклювов! Тьфу, как я ненавижу этих тварей! С тех пор, как меня покусал один из них, у меня случаются периодические обмороки.$B$BПредставляете, как это неприятно? Вот, возьмите это в благодарность за то, что отомстили за меня.', NULL, NULL, NULL, 'Костеклюв убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10035, 'Торгос!', 'В Костяных пустошах живет существо настолько ужасное, что едва ли кто отважится напасть на него.$B$BЯ имею в виду Торгоса, короля костеклювов – он кружит над гнездовьем Рейз, что на западном краю пустошей.$B$BХитрые араккоа поставили там пугало, назвали его Погибель Торгоса, и это пугало не дает ему приблизиться. Но если положить к подножию пугала останки самки Торгоса – Трашелы – то он спустится вниз. Самку можно найти на холме Падальщика, это на севере пустошей.$B$BПринеси мне перо из хвоста Торгоса.', 'Приманите Торгоса останками Трашелы, добудьте перо из его хвоста и отнесите его Тэле Вечной Страннице в бастион Аллерии в лесу Тероккар.', 'Впечатляет, $C! Торгос был одним из самых страшных существ на этой стороне Награнда.$B$BЧто ж, думаю, ты заслуживаешь кое-что из сокровищницы бастиона Аллерии. Выбирай.', 'Принесли перо? Вас можно достойно наградить?', NULL, NULL, 'Хвостовое перо Торгоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10036, 'Торгос!', 'Я хочу, чтобы Торгос, вожак костеклювов, сдох!$B$BНедавно я охотился в гнездовье Рейз, и эта тварь напала на меня!$B$B<Мауг показывает на повязку на глазу.>$B$BОн вырвал мне глаз, и за это должен умереть! Вырви из его трупа хвостовое перо и получишь хорошую награду.$B$BДля того, чтобы приманить это чудовище, тебе потребуются останки его самки, Трашелы. Положи их под пугалом, которое араккоа назвали Погибель Торгоса, он и спустится.$B$BТрашелу можно найти на холме Падальщика, это на севере пустошей.', 'Приманите Торгоса останками Трашелы, добудьте перо из его хвоста и отнесите его Маугу Лютострелу в форт Камнеломов в лесу Тероккар.', 'Спасибо, $N! Вы отомстили за меня, а я, как и обещал, награжу вас.$B$BВот, выбирайте и пользуйтесь на здоровье.', 'Вы убили его? Торгос мертв?!$B$BА доказательство?', NULL, NULL, 'Хвостовое перо Торгоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10037, 'Без рыбалки', 'Кстати, об озерах – тут к северо-востоку есть отличное озеро для рыбалки! Раньше я ходил туда с друзьями, но потом мама запретила.$B$BОна говорит, что там опасно, но я ничего особо странного там не видел, разве что маленьких паучков. Да разве ж они могут как-то навредить?$B$BЭх, а я так любил есть тамошних угрей, до чего ж они вкусные... Если вдруг попадете на это озеро, может, принесете мне немного рыбки? Угри немного злые, но вообще с ними не так уж трудно справиться.', 'Принесите 8 тушек блестящих угрей Сету в Шаттрат.', 'Спасибо! Я уж и забыл, когда в последний раз ел угря!$B$BИ как же мне их приготовить?', '<Сет хватает вас за плащ.>$B$BВы нашли угрей? А?', NULL, NULL, 'Тушка блестящего угря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10038, 'Разговор с рядовым Виксом', 'Мы только что получили донесение от разведчика из деревни Грангол\'вар. Он пишет, что в тамошние руины пришла какая-то темная компания.$B$B$N, я прошу тебя поговорить с рядовым Виксом и помогли ему выяснить, что это за группа и что она затевает. Отправляйся на запад, мимо форта Камнеломов – рядовой должен быть где-то около северного входа в деревню.', 'Найдите рядового Викса возле северного входа в деревню Грангол\'вар в лесу Тероккар и поговорите с ним.', 'Наконец-то хоть кто-то пришел! Я отправил донесение в бастион Аллерии неделю назад.$B$BЧертовы бюрократы!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10039, 'Разговор с разведчицей Нефтис', 'Мне сообщили, что наша разведчица близ деревни Грангол\'вар заметила группу неизвестных, которая недавно обосновалась там.$B$B$N, отправляйся туда, поговори с разведчицей Нефтис и помоги ей выяснить, что это еще за компания.$B$BОтправляйся отсюда на юг, а потом поверни на запад, чтобы пройти мимо северной части Костяных пустошей. В своем последнем донесении Нефтис писала, что расположилась около южного входа в деревню.', 'Найдите разведчицу Нефтис возле южного входа в деревню Грангол\'вар в лесу Тероккар и поговорите с ней.', 'Наконец-то, хоть кто-то явился! Я ведь послала письмо в форт Камнеломов неделю назад!$B$BВечно эти эльфы крови бюрократию разведут!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10040, 'Кто они?', 'Не знаю, кто это, но ведут они себя очень враждебно!$B$BЯ дам вам маскировочный костюм, чтобы вы пошли туда и поговорили с тремя из них, наиболее болтливыми – с посвященным, работником и советником.$B$BНо будьте осторожны – там есть несколько охотников, которые узнают вас даже в камуфляже, а с ними лучше не связываться. И что бы ни произошло, ни в коем случае не покидайте деревни, потому что маскировочный костюм очень непрочен! Если вдруг потеряете его, то приходите, я дам вам новый.', 'Замаскируйтесь и поговорите с мрачным посвященным, мрачным работником и мрачным советником, после чего вернитесь к рядовому Виксу у деревни Грангол\'вар в лесу Тероккар.', 'Наконец-то вы вернулись! Ну, что удалось узнать? Кто они такие?', 'Вы со всеми поговорили? Что они сказали?', NULL, NULL, 'Вы поговорили с Мрачным посвященным', 'Вы поговорили с Мрачным работником', 'Вы поговорили с Мрачным советником', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10041, 'Кто они?', 'Не знаю, кто это, но ведут они себя очень враждебно!$B$BЯ дам вам маскировочный костюм, чтобы вы пошли туда и поговорили с тремя из них, наиболее болтливыми – с посвященным, работником и советником.$B$BНо будьте осторожны – там есть несколько охотников, которые узнают вас даже в камуфляже, а с ними лучше не связываться. И что бы ни произошло, ни в коем случае не покидайте деревни, потому что маскировочный костюм очень непрочен! Если вдруг потеряете его, то приходите, я дам вам новый.', 'Замаскируйтесь и поговорите с Мрачным посвященным, Мрачным работником и Мрачным советником, после чего вернитесь к разведчице Нефтис в деревню Грангол\'вар в лесу Тероккар.', 'Наконец-то вы вернулись! Ну, что удалось узнать? Кто они такие?', 'Вы со всеми поговорили? Что они сказали?', NULL, NULL, 'Вы поговорили с Мрачным посвященным', 'Вы поговорили с Мрачным работником', 'Вы поговорили с Мрачным советником', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10042, 'Убить Совет Теней!', 'Что?! Совет Теней?!$B$B$N, вернись туда и убей их всех! Нужно избавиться от их главаря и от как можно большего количества призывателей и палачей.$B$BКогда закончишь, ступай к лейтенанту Булыжному Молоту в бастион Аллерии.$B$BУдачи, $C!', 'Убейте 10 мрачных палачей, 10 мрачных призывателей и повелителя теней Скорбного, после чего вернитесь к лейтенанту Булыжному Молоту в бастион Аллерии в лесу Тероккар.', 'Это ужасные новости! Похоже, я правильно поступил, что отправил вас на помощь Виксу. Чего нам не надо, так это чтобы Совет Теней обосновался прямо у нас под носом.$B$B$N, в знак признательности за проявленное вами мужество в деревне Грангол\'вар я даю вам право выбрать себе одну из этих прекрасных наград.', NULL, NULL, NULL, 'Мрачный палач убито', 'Мрачный призыватель убито', 'Повелитель теней Скорбный убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10043, 'Убить Совет Теней!', 'Что?! Это Совет Теней?!$B$B$N, вы должны вернуться туда и убить их всех! Нужно избавиться от их главаря и от как можно большего количества призывателей и палачей.$B$BКогда закончишь, поговори с советницей Файлой в форте Камнеломов.$B$BУдачи, $C!', 'Убейте 10 мрачных палачей, 10 мрачных призывателей и повелителя теней Скорбного, после чего вернитесь к советнице Файле в форт Камнеломов в лесу Тероккар.', 'Это ужасные новости! Похоже, я правильно поступила, что отправила вас на помощь Нефтис. Чего нам не надо, так это чтобы Совет Теней обосновался прямо у нас под носом.$B$B$N, вы заслужили хорошую награду. Вот, выбирайте.', NULL, NULL, NULL, 'Мрачный палач убито', 'Мрачный призыватель убито', 'Повелитель теней Скорбный убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10044, 'Разговор с Великой матерью', 'Великая мать незамедлительно требует тебя к себе.$B$BМой дух сломлен печалью, но берегись, $N: если ты рассердишь Великую мать, я обрушу на тебя все силы, которые только смогу собрать. Она в главном зале.$B$B*Гаррош указывает на большое здание к северу.*$B$BВыслушай ее и выполни ее приказ.', 'Поговорите с Великой Матерью Гейей и сделайте все, о чем она вас попросит.', 'Для того чтобы общаться с предками, надо сначала открыть свое сознание.', 'Присядь, дорогой.', NULL, NULL, 'Выслушайте Великую Матерь Гейю', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10045, 'Компоненты зелья', 'Мать Кашур хочет поговорить с тобой, $N. Но это произойдет не раньше, чем ты соберешь травы. Они необходимы для изготовления снадобья, которое откроет твой разум и позволит тебе говорить с духами.$B$BТебе надо найти корень олембы в лесу Тероккар, клюкву в Зангартопи, телаарский папоротник в Награнде и драконий шип в Острогорье. Я записала инструкции на этом пергаменте, чтобы ты $gсумел:сумела: распознать необходимые травы. Когда соберешь все, что нужно, возвращайся ко мне.', 'Принесите великой матери Гейе в Гарадар 1 корень олембы, 1 кустик клюквы, 1 телаарский папоротник и 1 побег драконьего шипа.', 'Ты все сделал правильно, $N. И ты молодец. Даже самые лучшие наши травники не справились бы с этой работой быстрее тебя. !$B$B*Великая Матерь Гейя добавляет травы в напиток и подносит кубок к вашим губам, заставляя вас выпить снадобье.*$B$BНе бойся.', 'Здравствуй, сынок.', NULL, NULL, 'Корень олембы', 'Клюква', 'Телаарский папоротник', 'Драконий шип');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10046, 'Через Темный портал', 'Две недели назад наши разведчики доложили о выступлении из крепости Стражей Пустоты хорошо вооруженных сил Альянса под командованием боевого командира Ромуса. Если они отрядили столько солдат и ресурсов под управлением такого выдающегося командира, то цель может быть только одна – Запределье.$B$BВождь послал передовые отряды через портал, но если Альянс считает нужным отправить такое большое войско, возможно и нам лучше было бы послать подкрепление. Отправляйся через Темный портал и поговори с Назгрелом в Траллмаре.', 'Пройдите через Темный портал и поговорите с Назгрелом в Траллмаре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10047, 'Путь Славы', 'Они называют ее \"Путем Славы\". Дорога, которая ведет от их ужасной крепости к Темному порталу, вымощена костями моего народа.$B$BМало того, что они травят нас, как зверей, разрушают наши города и пытают тех, кто выжил. Нет, этого им недостаточно. Они вымостили дорогу костями моих соратников, лишив их достойного погребения.$B$BИстерзанные души этих несчастных бродят по земле, не зная покоя. Умоляю тебя, $N, помоги мне освободить их.', 'Окропите 8 истоптанных скелетов, лежащих на Пути Славы, святой водой дренеев, после чего возвращайтесь в Оплот Чести к провидцу бед Криву.', 'Я искренне благодарен тебе за помощь, $N. Еще многое нужно сделать, но я рад, что мы помогли кому-то обрести заслуженный и долгожданный покой.', 'Плач вроде бы стих... Милосердие Света превосходит всякое разумение смертных.', NULL, NULL, 'Окроплено истоптанных скелетов', 'Святая вода дренеев (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10048, 'Магическая пыль', 'Мне потребуется пыль, но не абы какая.$B$BНеобходимую пыль собирают с крылышек царственных пухоспинок, которые живут в близлежащем лесу – с помощью этой пыли пухоспинки усмиряют тех, кто за ними охотится. Если вы наберете мне немного, я смогу преодолеть сопротивление тех глаз, что вы принесли мне, а потом с их помощью разыскать Дейрома.$B$BПыли потребуется около десяти горстей.', 'Принесите 7 горстей пыли усмирения Андарлу в Бастион Аллерии.', '', NULL, NULL, NULL, 'Усмиряющая пыль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10049, 'Магическая пыль', 'Мне потребуется пыль, но не абы какая.$B$BНеобходимую пыль собирают с крылышек царственных пухоспинок, которые живут в близлежащем лесу – с помощью этой пыли пухоспинки усмиряют тех, кто за ними охотится. Если вы наберете мне немного, я смогу преодолеть сопротивление тех глаз, что вы принесли мне, а потом с их помощью разыскать Дугара.$B$BПыли потребуется около десяти горстей.', 'Принесите 7 горстей пыли усмирения Каргатоку в Форт Камнеломов.', '', NULL, NULL, NULL, 'Усмиряющая пыль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10050, 'Непреклонные духи', 'Где-то в конце нашего вторжения, Оружейная на юге попала под удар коварных Рыцарей Смерти Орды. Защитники Оружейной пали от колдовства и оказались прокляты - их души застряли навеки между жизнью и смертью.$B$BМы должны освободить этих доблестных солдат. Умоляю тебя, $N, прекрати мучения моих соратников. Мне самому не хватает духа их уничтожить.', 'Убейте 12 непреклонных пехотинцев, 10 непреклонных колдунов и 5 непреклонных рыцарей в оружейной экспедиции на юге по просьбе отважного стража Весилоу.', 'О том, что происходит в Оружейной, многие предпочитают умалчивать, но Сыны благодарны тебе за помощь.', NULL, NULL, NULL, 'Непреклонный пехотинец убито', 'Непреклонный колдун убито', 'Непреклонный рыцарь убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10051, 'Побег из лагеря Огнекрылых', 'О, наконец-то хоть кто-то появился!$B$B$C, помоги мне сбежать! У меня есть информация, жизненно важная для бастиона Аллерии и, возможно, для всего Запределья!$B$BЯ прибыла сюда из Кенарийской экспедиции с дипломатической миссии, но, как видишь, меня ждал отнюдь не дружеский прием! Если ты поможешь мне спастись, то я обязательно прослежу, чтобы тебя достойно наградили. $B$BОднако вдвоем нам не справиться. Надеюсь, ты $gпривел:привела: с собой друзей?', 'Проводите Ислу Звездную Гриву в безопасное место, после чего расскажите об этом капитану Аурику Ловчему Солнца в бастионе Аллерии в лесу Тероккар.', 'Исла Звездная Грива только что ушла, но она рассказала мне обо всем, что произошло в лагере Огнекрылых. Вполне понятно, что она очень расстроена тем происшествием в перелеске Кенария... Проклятые эльфы крови!$B$BОна рассказала мне и о том, как ты помог ей спастись и донести до нас эту информацию, так что бастион Аллерии перед тобой в долгу.$B$BПожалуйста, прими это в благодарность ото всех нас.', NULL, NULL, NULL, 'Проводите Ислу Звездную Гриву в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10052, 'Побег из лагеря Огнекрылых', 'О, наконец-то хоть кто-то появился!$B$B$C, помоги мне сбежать! У меня есть информация, жизненно важная для форта Камнеломов и, возможно, для всего Запределья!$B$BЯ прибыла сюда из Кенарийской экспедиции с дипломатической миссией, но, как видишь, меня ждал отнюдь не дружеский прием! Если ты поможешь мне спастись, то я обязательно прослежу, чтобы тебя достойно наградили. $B$BОднако вдвоем нам не справиться. Надеюсь, ты $gпривел:привела: с собой друзей?', 'Проводите Ислу Звездную Гриву в безопасное место, после чего расскажите об этом советнице Файле в форте Камнеломов в лесу Тероккар.', 'Исла Звездная Грива только что ушла, но она рассказала мне обо всем, что произошло в лагере Огнекрылых. Вполне понятно, что она очень расстроена тем происшествием в перелеске Кенария... Проклятые эльфы крови!$B$BОна рассказала мне и о том, как ты помог ей спастись и донести до нас эту информацию, так что форт Камнеломов перед тобой в долгу.$B$BПожалуйста, прими это в благодарность ото всех нас.', NULL, NULL, NULL, 'Проводите Ислу Звездную Гриву в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10053, 'Расправиться с Зет\'Гором', 'Ситуацией, возникшей в результате уничтожения боевого командира Некрогга, нужно обязательно воспользоваться, $N. Если нам повезет, то командование Зет\'Гора еще некоторое время не узнает о его смерти.$B$BВ Зет\'Горе клан Костеглодов возглавляет Гриллок Пустой Глаз. Его логово находится рядом с крепостью, это пещера, вырубленная в камне. Разыщи его и убей. Потом обыщи пещеру и найди военные планы орков Скверны. Мы должны избавить Оплот Чести от неприятных сюрпризов.', 'Убейте Гриллока Пустого Глаза, обыщите его логово и найдите планы атаки Кровавой Глазницы.', '', NULL, NULL, NULL, 'Гриллок \"Пустой Глаз\" убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10054, 'Надвигающийся рок', 'Быстро проглядывая планы, вы понимаете, что за атакой, возглавляемой костяным волхвом Варлором, стоял полководец Морк. Но на карте обозначены не только войска Морка.$B$BВ планах говорится, что войска Костеглодов должны атаковать Оплот Чести вместе с силами Цитадели Адского Пламени.$B$BПредупреждать Оплот Чести нет времени. Вы должны остановить Костеглодов, пока они не начали атаку.', 'Убейте 15 рубак, 10 некролитов, 5 батраков из клана Кровавой Глазницы и полководца Морка. О выполнении задания доложите лейтенанту Амади, которая находится в западной башне Оплота Чести.', '', NULL, NULL, NULL, 'Воевода Морх убито', 'Рубака из клана Кровавой Глазницы убито', 'Некролит из клана Кровавой Глазницы убито', 'Батрак из клана Кровавой Глазницы убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10055, 'Ничто не пропадет даром', 'Подкрепление – это хорошо, но я не вижу, чтобы они присылали металл или древесину.$B$BОглянись вокруг, $gдружище:подруга:. Все деревья вырублены, а на рудниках хозяйничают приспешники Легиона.$B$BМне постоянно не хватает материалов. Поверь, я делал все, что можно, но пришло время пускать вторсырье на переработку.$B$BВ южной части Пути Славы повсюду валяются обломки техники. Некоторые из них можно снова пустить в дело. $gГотов:Готова: приступить ко сбору вторсырья?', 'Принесите 8 кусков металлолома и 8 кусков древесины Болтую в Оплот Чести.', 'Выглядит лучше, чем я думал. Уйдет немало времени, чтобы счистить всю эту пыль и ржавчину, но выбора у меня все равно нет.', 'Ну как, удалось найти что-нибудь полезное среди этого пепла, пыли и хлама?', NULL, NULL, 'Кусок металлолома', 'Кусок древесины', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10056, 'Припасы Кровавой Глазницы', 'Орки из Цитадели Адского Пламени основали военную базу на руинах старого оркского поселения Зет\'Гор, и их число постоянно растет.$B$BСыны Лотара когда-то сражались с ними, но я бы никогда не поверил их рассказам, если бы не видел этих \"орков Скверны\" собственными глазами.$B$BОни изменились так, что стали ни на что не похожи. Нельзя позволить, чтобы они сумели накопить силы. Ступай в Зет\'Гор и уничтожь там все припасы, какие найдешь.', 'Уничтожьте 6 складов припасов Кровавой Глазницы. О выполнении задания доложите лейтенанту Амади из Оплота Чести.', '', NULL, NULL, NULL, 'Припасы клана Кровавой Глазницы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10057, 'Солдатская верность', 'Несмотря на все твои усилия, в оружейной экспедиции по-прежнему неспокойно. Никто не знает, что же там происходит, и что вообще привело духи павших солдат в эти руины.$B$BВозможно, мы что-то сделали не так. Я чувствую, что солдаты каким-то образом связаны с этим местом. Может быть, они хранят верность своим командирам?$B$BПодчиненные всегда любили верховного мага Ксинтора и лейтенанта-командора Талвоса. Может быть, если нам удастся победить их духи, то и все остальные отправятся на вечный покой?', 'Победите духов верховного мага Ксинтора и лейтенанта-командора Талвоса и возвращайтесь к отважному стражу Весилоу в северо-западную башню Оплота Чести.', 'Мы можем только надеяться, что простые солдаты последуют примеру своих командиров. Еще раз благодарю тебя за помощь, Хочукекать.', 'Тебе удалось победить призраки офицеров?', NULL, NULL, 'Верховный маг Ксинтор убито', 'Лейтенант-командор Талвос убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10058, 'Старый дар', '<Жрец медленно отрывается от кружки и подымает на вас взгляд.>$B$BНеужели тебя не учили, что не следует мешать человеку, когда он пьет?$B$BЛадно, ладно. Новое лицо – это хороший знак. Интересно, что бы подумал Туралион?$B$BЯ помню тот вечер перед нашим отправлением, когда я вручил ему \"Таинства Света\". В течение нескольких лет, пока длилась кампания, он не забывал каждый день прочитывать по главе своим людям.$B$BКогда он покидал нас, то вернул книгу обратно мне. А я, дурак, верил, что в моем доме, к югу от Оружейной, она будет в безопасности.', 'Верните \"Таинства Света\" отцу Малгору Девидикусу в Оплот Чести.', 'Это правда она? Невероятно, как эта книга сумела уцелеть во время битвы. Время, проведенное среди руин, не пошло ей на пользу, но я рад, что она снова ко мне вернулась.$B$BЭто моя единственная память о Туралионе.$B$B<Отец Девидикус пытается сдержать слезы.>$B$BЕсли ты долго сражаешься с кем-то плечом к плечу, то он становится тебе дороже, чем брат.', 'Кажется, я уже говорил тебе меня не трогать. Что на этот раз?', NULL, NULL, '\"Таинства Света\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10059, 'Расправиться с Зет\'Гором', 'Ситуацией, возникшей в результате уничтожения боевого командира Некрогга, нужно обязательно воспользоваться, $N. Если нам повезет, то командование Зет\'Гора еще некоторое время не узнает о его смерти.$B$BВ Зет\'Горе клан Костеглодов возглавляет Гриллок Пустой Глаз. Его логово находится рядом с крепостью, это пещера, вырубленная в камне. Разыщи его и убей. Потом обыщи пещеру и найди военные планы орков Скверны. Мы должны избавить Траллмар от неприятных сюрпризов.', 'Убейте Гриллока Пустого Глаза, обыщите его логово и найдите планы атаки Кровавой Глазницы.', '', NULL, NULL, NULL, 'Гриллок \"Пустой Глаз\" убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10060, 'Надвигающийся рок', 'Быстрый осмотр планов показывает, что за атакой, возглавляемой костяным волхвом Варлором, стоял полководец Морк. Но на карте обозначены не только войска Морка.$B$BВ планах обозначено, что войска Костеглодов должны атаковать Траллмар вместе с силами Цитадели Адского Пламени.$B$BПредупреждать Траллмар нет времени. Вы должны остановить Костеглодов, пока они не начали атаку.', 'Убейте 15 рубак, 10 некролитов, 5 батраков из клана Кровавой Глазницы и полководца Морка. О выполнении задания доложите каменному стражу Амбелану на Заставу Хребтолома.', '', NULL, NULL, NULL, 'Воевода Морх убито', 'Рубака из клана Кровавой Глазницы убито', 'Некролит из клана Кровавой Глазницы убито', 'Батрак из клана Кровавой Глазницы убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10061, 'Непреклонные', 'Орки из клана Костеглодов быстро покончили с защитниками оружейной экспедиции. Произошла кровавая резня, в которой никто не уцелел.$B$BТела мертвых были преданы огню, но души поселились в этих руинах. Недавно мне было видение, что эти духи могут представлять угрозу для Траллмара.$B$BМы можем сделать только одно. Души этих солдат нужно упокоить. Сразись с ними и победи их в бою.', 'Убейте 12 непреклонных пехотинцев, 10 непреклонных колдунов и 5 непреклонных рыцарей в оружейной экспедиции к югу от Оплота Чести по просьбе Грелага.', '', NULL, NULL, NULL, 'Непреклонный пехотинец убито', 'Непреклонный колдун убито', 'Непреклонный рыцарь убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10062, 'Солдатская верность', 'Несмотря на все твои усилия, в Оружейной Экспедиции по-прежнему неспокойно. Никто не знает, что же там происходит, и что вообще привело туда духи павших солдат.$B$BКажется, мы что-то упустили. Я чувствую, что солдаты каким-то образом привязаны к этим руинам. Может быть, они хранят верность своим командирам?$B$BПодчиненные всегда любили верховного мага Ксинтора и лейтенанта-командора Талвоса. Может быть, если нам удастся победить их духи, то и все остальные отправятся на покой?', 'Победите духов верховного мага Ксинтора и лейтенанта-командора Талвоса и возвращайтесь к Грелагу на Заставу Хребтолома.', '', NULL, NULL, NULL, 'Верховный маг Ксинтор убито', 'Лейтенант-командор Талвос убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10063, 'Лига исследователей: что здесь делают гномы?', 'Я – нянька?! Нет, кому такое только в голову могло прийти?!$B$BОтрывают меня от исследований – весьма многообещающих, замечу, исследований! – и посылают в экспедицию с капитаном Одиссием. И зачем, как ты думаешь? Чтобы я нянчился с этим гномским недомерком!$B$BТо есть теперь мы в геологи берем гномов; а вот именно этот гном с ума сходит по мурлокам!$B$BХуже того, он решил устроить лавку в старом черепашьем панцире. Не веришь? А ты сходи на северный берег – увидишь своими глазами!', 'Найдите Клоппера Бацбаха – он обосновался в старом черепашьем панцире на берегу к северу от Кровавой заставы.', 'Так я и думал! Между прочим, этот старый ворчливый тип должен был мне помочь с оборудованием и сбором информации. Как же! Двадцать раз! Конечно, ему гораздо больше нравится торчать в этом дренейском городе и надираться в стельку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10064, 'Длань Аргуса', 'Передовая база Длани Аргуса расположена в селении Привал Воздаятеля. Увы, бойцам Длани приходится нелегко: их теснят эльфы крови и животные-мутанты. Без поддержки их оплот падет – и тогда мы потеряем последнюю возможность узнать, что же происходит возле энергоблока.$B$BНайди в Привале Воздаятеля разведчицу Джорли и предложи ей помощь.', 'Найдите в селении Привал Защитника разведчицу Джорли.', 'Я надеялась, что как только на Кровавой заставе поймут, что нам противостоит, к нам пришлют подкрепление.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10065, 'Зеленая улица', 'Мы проводили разведку, выясняя, где расположились Солнечные Ястребы и где находится их портал, но, к несчастью, я была тяжело ранена. Разведчица Лорай сумела остановить кровь; надеюсь, ей удастся найти способ переправить меня на Кровавую заставу.$B$BУвы, чтобы вернуться туда живыми, нам придется покинуть наше убежище.$B$BКак только мы покинем эту освященную землю, на нас набросятся разъяренные опустошители. Однако если тебе удастся расчистить нам путь, возможно, мы сумеем добраться до Кровавой заставы в целости...', 'Убейте 10 разъяренных опустошителей и вернитесь на Привал Защитника к разведчице Джорли.', 'Похоже, вокруг стало поспокойнее... А все-таки, может, лучше остаться здесь и дождаться лекаря?', NULL, NULL, NULL, 'Разъяренный опустошитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10066, 'Тенета судьбы', 'Мы не смеем ни покинуть пост, ни удалиться от Привала Воздаятеля, $r. Те существа, которые находились ближе всего к энергоблоку, совершенно изменились: мутировали под влиянием энергии кристаллов.$B$BДаже плеточники-мутанты, похоже, обрели разум – насколько растения вообще могут быть разумными. Они научились создавать и расставлять смертоносные ловушки; к тому же ловушки эти замаскированы так, что в любую может попасться даже опытный и осторожный воин.$B$BТы $gдолжен:должна: понимать: мы никогда не сумеем выступить против Солнечных Ястребов, если будем вынуждены в буквальном смысле слова следить за каждым своим шагом. Но ты ведь сумеешь разрешить эту небольшую проблему, верно, $N?', 'Убейте 8 тенеплетов-мутантов и вернитесь к воздаятельнице Корин в селение Привал Защитника.', 'Прекрасно, $N. Теперь, когда можно не беспокоиться по поводу тенеплетов, нам будет гораздо легче привести подкрепление с Кровавой заставы и организовать атаку на Солнечных Ястребов.', NULL, NULL, NULL, 'Тенеплет-мутант убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10067, 'Смрадные водные духи', 'С теми существами, которых коснулась энергия кристаллов, происходит в основном одно и то же: на плоти появляются странные метки, заметны впившиеся в тело осколки кристаллов, а агрессивность возрастает многократно. Однако смрадные водные духи к северу отсюда, похоже, полностью превращаются в кристаллы.$B$BНикогда не видела, чтобы живые существа так реагировали на кристаллы. Но в том мерзком озерце они были особенно агрессивны. Думаю, от этих тварей надо избавиться, пока Солнечные Ястребы не прибрали их к рукам и не использовали против нас.', 'Убейте 6 смрадных водных духов и вернитесь к воздаятельнице Корин в селение Привал Защитника.', 'Прекрасно, $N. Нужно приложить все усилия, чтобы лишить Солнечных Ястребов поддержки.', NULL, NULL, NULL, 'Смрадный дух воды убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10068, 'Хранитель Колодца Соланиан', 'А теперь мне нужно, чтобы ты кое-что $gсделал:сделала:.$B$BХранителю Колодца Соланиану нужна твоя помощь. Тебе будет полезно заслужить его благосклонность.$B$BОн ждет тебя на внешней платформе, на которую выходит пандус из этого зала.', 'Поговорите с хранителем Колодца Соланианом в Солнечном Шпиле на острове Солнечного Скитальца.', 'Я ждал тебя, $C.$B$BУ меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
