INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10073, 'Хранитель Колодца Соланиан', 'А теперь мне нужно, чтобы ты кое-что $gсделал:сделала:.$B$BХранителю Колодца Соланиану нужна наша помощь. Тебе будет полезно заслужить его благосклонность.$B$BОн ждет тебя на внешней платформе, на которую выходит пандус из этих палат.', 'Поговорите с хранителем Колодца Соланианом в Солнечном Шпиле на острове Солнечного Скитальца.', 'Я ждал тебя, $C.$B$BУ меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10074, 'Порошок кристалла Ошу\'гуна', 'Раньше здесь располагался исследовательский центр первородных дренеев. Они изучали кристаллы наару.$B$BНам удалось обнаружить бесценное сокровище: древние записи о кристаллах из \"алмазной\" горы Ошу\'гун. Насколько мы поняли, на территориях, прилегающих к горе, все несет на себе остаточный след порошка кристалла Ошу\'гуна. Если ты вдруг найдешь порошок, когда окажешься в тех краях, собери его и принеси мне сюда. В знак моей безграничной признательности ты получишь награду, которую сможешь обменять на многие полезные вещи.', 'Принесите старшему ученому Амерельдине в Халаа 10 порций порошка кристалла Ошу\'гуна.', 'Замечательно, $N. Это очень поможет нам в битве с мерзавцами из Альянса, которые недавно появились в Запределье.', 'Кристаллический порошок из горы зарождается в глубинах земли этой области.', NULL, NULL, 'Образец порошка кристалла Ошу\'гуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10075, 'Порошок кристалла Ошу\'гуна', '', '', 'Я всегда буду готова принять кристальный порошок, сколько бы ты ни принес, $N. За каждую партию порошка, которую ты нам доставишь, ты получишь достойное вознаграждение.', NULL, NULL, NULL, 'Образец порошка кристалла Ошу\'гуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10076, 'Порошок кристалла Ошу\'гуна', 'Раньше здесь располагался исследовательский центр дренеев. Они изучали кристаллы наару.$B$BНам удалось обнаружить бесценное сокровище: древние записи о кристаллах из \"алмазной\" горы Ошу\'гун. Насколько мы поняли, на территориях, прилегающих к горе, все несет на себе остаточный след порошка кристалла Ошу\'гуна. Если ты вдруг найдешь порошок, когда окажешься в тех краях, собери его и принеси мне сюда. В знак моей безграничной признательности ты получишь награду, которую сможешь обменять на многие полезные вещи.', 'Принесите 10 порций порошка кристалла Ошу\'гуна старшему ученому Картосу в Халаа.', 'Замечательно, $N. Это очень поможет нам в битве с мерзавцами из Орды, которые недавно появились в Запределье.', 'Кристаллический порошок из горы зарождается в глубинах земли этой области.', NULL, NULL, 'Образец порошка кристалла Ошу\'гуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10077, 'Порошок кристалла Ошу\'гуна', '', '', 'Спасибо за помощь, $N. Если найдешь еще порошок - ты знаешь, куда его нести!', NULL, NULL, NULL, 'Образец порошка кристалла Ошу\'гуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10078, 'Сжечь старье!', 'Теперь, когда мы успешно завершили нашу операцию по сбору вторсырья, можно перейти ко второй части плана.$B$BВдоль Пути Славы все еще стоят старые самонаводящиеся клинкометы Орды. И пусть их возраст не вводит тебя в заблуждение, $N, они по-прежнему очень, очень опасны. Мы сами пытаемся пустить на переработку все, что возможно, так что не думаю, что Орда просто так возьмет и забудет про эти машины.$B$BВозьми факел и подожги все уцелевшие осадные орудия. Не должно остаться ни малейшего шанса, что их снова будут использовать против Оплота Чести.', 'Используйте горящий факел и подожгите клинкометы Орды, стерегущие Путь Славы. После выполнения задания верните факел Болтую в Оплот Чести.', 'Вот это сила духа!$B$BЯ рад, что мы наконец получили подкрепление, но я не уверен в их отношении к Орде. На моей родине считают врагом любого, кто поднял на тебя руку, а с врагом у нас разговор короткий!', 'Похоже, ты в хорошем настроении. Что, горящие осадные машины Орды согрели твою душу?', NULL, NULL, 'Восточный клинкомет горит', 'Центральный восточный клинкомет горит', 'Центральный западный клинкомет горит', 'Западный клинкомет горит');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10079, 'Весь рудник ходуном', 'На руднике просто не продохнуть от ган\'аргской заразы!$B$BМало того, что они вышвырнули всех моих рабочих из штреков, так продолжают там днем и ночью вести подрывные работы! И вдобавок на меня ополчился сам Данат. Сказал, что если я не справлюсь с проблемой, и немедленно, он лишит меня поставок пива.$B$BНикто из шахтеров не работает, а стража от страха напилась до потери пульса.$B$BУмоляю, $N, спаси меня! Можешь меня презирать, но пиво мне дороже, чем гордость!', 'Убейте 12 ган\'аргов-саперов и вернитесь к штейгеру Большие Десны.', 'Клянусь золотой бородой Бронзоборода, ты сделал это! Да ты просто герой, Михухоль.', 'Скажи мне, что все уже закончилось и мои ребята могут вернуться к работе... ну пожалуйста!', NULL, NULL, 'Ган\'арг-сапер убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10081, 'Встреча с Матерью Кашур', 'Не бойся того, что увидишь, когда снадобье подействует! Духи – они всегда рядом с нами. Повсюду, всегда. Снадобье просто откроет твой разум, чтобы ты $gвидел их и понимал:видела их и понимала:. Иначе ты просто не сможешь поговорить с Матерью Кашур.$B$BТы найдешь ее на юго-западе, далеко-далеко отсюда, в Землях Предков.', 'Поговорите с Матерью Кашур.', 'Снадобье, которое ты выпил, на самом деле не дает никакого эффекта. Если дух не захочет тебе показаться, ты его не увидишь, несмотря ни на какие \"волшебные\" зелья. Снадобье – это всего лишь символ твоей веры и преданности. Это было испытание, и ты его прошел...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10082, 'Покой предков', 'Видишь, они разгуливают среди нас? Обычно ничто не тревожит покой Земель Предков.$B$BОднако в последнее время духи предков пробудились от мирного сна, и они явно чем-то встревожены. Что-то нарушило их покой. Мы должны выяснить, что именно. Но сначала мы должны разобраться с угрозой, которую следует устранить незамедлительно.$B$BЭти призраки, которые ходят среди живых... на самом деле это не духи, а зримые образы их состояния. Я хочу, чтобы ты $gуничтожил:уничтожила: потревоженных духов орков. Когда исполнишь мое поручение, возвращайся ко мне.', 'Уничтожьте 8 потревоженных духов орков по просьбе Матери Кашур. ', 'Бесполезно. Они восстают вновь и вновь. Ладно, будем разбираться...', 'Тебе нужно особое зелье, для того чтобы видеть духов, $N.', NULL, NULL, 'Потревоженный дух орка убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10084, 'Атака на Магеддон', 'Мо\'арги-инженеры прикладывают все свое умение, а ган\'арги получают непрерывные поставки сырья. Этак они запустят скверноботов раньше, чем мы успеем отправить хотя бы словечко Стражам Пустоты.$B$BЕдинственное, что нам остается – как можно скорее атаковать их. К сожалению, нельзя перебросить войска с защиты Оплота Чести, это равносильно самоубийству. Орки Скверны и Орда вцепятся в нас при малейшем намеке на слабость.$B$BОплот чести простоял 20 лет, и мы не можем позволить потерять его сейчас.', 'Убейте Владыку ночи Малфаса, находящегося на Кузнечной Базе: Магеддон. О выполнении задания доложите командиру армии Данату Троллебою из Оплота Чести.', '', NULL, NULL, NULL, 'Владыка ночи Малфас убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10085, 'Навестить предков', 'Я хочу, чтобы ты, $N, $gобъехал:объехала: поселения предков. Посети их все, один за другим, и убедись, что все в порядке.$B$BЗастава Солнечного Источника на севере, руины Веселого Черепа у подножия северных гор, Гарадар на северо-востоке и, наконец, руины Кровавой Глазницы на востоке, на границе Награнда и леса Тероккар.$B$BКак закончишь, возвращайся ко мне с отчетом.', 'Мать Кашур хочет, чтобы вы посетили заставу Солнечного Источника, руины Веселого Черепа, Гарадар и руины Кровавой Глазницы.', 'Это тревожные новости. То есть в поселениях не осталось ни одного предка? Все движутся на юг?', 'Лети быстрее ветра, $N.', NULL, NULL, 'Посетите заставу Солнечного Источника', 'Посетите руины Веселого Черепа', 'Посетите Гарадар', 'Посетите руины Кровавой Глазницы');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10086, 'Я служу... Орде!', 'Ты можешь себе это представить? Орки наняли меня чинить укрепления и изготавливать взрывчатку. Не работа, а мечта! Единственно что, – материалов не хватает, но умный гоблин всегда что-нибудь да придумает.$B$BПомоги мне немного, а? Мне нужна древесина и металл, которые можно найти в обломках вдоль Пути Славы. Отправляйся туда и собери, что сможешь, но остерегайся краснокожих орков!$B$BВернешься с добычей – о награде не пожалеешь!', 'Принесите 8 кусков металлолома и 8 кусков древесины Мегзегу Крутогруду в Траллмар.', 'Отличный материал! Здесь немного покореженный, здесь малость обгорелый, но даже из этого старья я сооружу отличную взрывчатку.$B$BСпасибочки, $N. Сразу видно, что ты знаешь толк в мусоре!', 'Как там поживает сбор утиля? Нашел что-нибудь стоящее?', NULL, NULL, 'Кусок металлолома', 'Кусок древесины', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10087, 'Сжечь! Во имя Орды!', 'Я невероятно счастливый гоблин. Я изготавливаю взрывчатку и прочие орудия убийства, которые жизненно необходимы для ведения военных действий!$B$BКстати, что касается дел. Я только что узнал об одном приказе из Траллмара. Надо спалить все пушки Альянса на той стороне Пути Славы... слишком они близко к укреплениям Орды. Вот, возьми факел и не пропусти ни одной пушки. Подожги их как следует, и можешь наслаждаться фейерверком.', 'Используя горящий факел, подожгите восточную пушку Альянса и западную пушку Альянса. После выполнения задания возвращайтесь к Мегзегу Крутогруду в Траллмар.', 'Так я и думал! Отсюда, конечно, было ничего не разглядеть, но могу представить, как оно взрывалось. Прелестно, просто прелестно!$B$BНеплохая работенка, $N. В Траллмаре будут рады слышать о твоих подвигах.', 'Странно, почему я ничего не слышал, – ни воплей паленых орков Скверны, ни запаха дыма...$B$BЗадание-то выполнил?', NULL, NULL, 'Восточная пушка горит', 'Западная пушка горит', 'Горящий факел (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10088, 'Весь рудник ходуном', 'На руднике и так было не продохнуть от ган\'аргской заразы, а теперь еще все рабы решили, что сейчас самое время вздре$Nть! Не представляю, как им удавалось делать вид, что они спят, когда весь рудник содрогался, но, по крайней мере, это были не мои проблемы.$B$BЕсли мы не избавимся от ган\'аргских саботажников, поставки руды и остальных материалов в Траллмар полностью прекратятся! Я обращался к командиру стражи Кранку, но он ответил, что, дескать, не может выделить людей, пока город находится под угрозой. Может быть, хотя бы ты нам поможешь?', 'Убейте 12 ган\'аргов-саперов и возвращайтесь к Штейгер Разлкразу.', '', NULL, NULL, NULL, 'Ган\'арг-сапер убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10089, 'Лагеря Легиона', 'Лагеря Легиона бомбардировали Траллмар со времен его основания. Нам удалось продержаться до сих пор, но с каждым днем положение становится все более и более безнадежным.$B$BЛовец духов Туджин попытался выяснить хоть что-нибудь про эти лагеря, но ни один из его разведчиков не вернулся.$B$BПришло время для решительных действий, $N. проложи себе мечом путь в Лагерь Легиона Легиона: Ярость и выясни, что они там замышляют.', 'Убейте 10 ган\'аргов-прислужников, 5 легионеров лагеря Легиона и 5 сестер Скорби, затем обыщите лагерь Легиона: Ярость, чтобы узнать намерения Легиона.', '', NULL, NULL, NULL, 'Ган\'арг-прислужник убито', 'Легионер из лагеря Легиона убито', 'Сестра Горя убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10090, 'Планы Легиона', 'Вы делаете копию мерцающих иероглифов, вытравленных на поверхности, но без второй половины невозможно понять, что изображено на диаграмме.$B$BИероглифы показывают, что на западе есть еще один Лагерь Легиона: Злоба, который также имеет отношение к проекту. Может быть, вторая часть плана находится именно там?$B$BЕсли Легион решил изготовить что-то действительно чудовищное, то логично, что производство идет сразу в нескольких местах.', 'Разыщите Лагерь Легиона: Планы Злобы и возвращайтесь к властителю Хану Изуверу в Погибель Сквернобота.', '', NULL, NULL, NULL, 'Планы лагеря Легиона: Злоба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10091, 'Инструменты души', 'Ох! Они пытали меня, хотели вытянуть из меня все, что я знаю...$B$BЯ потерпел неудачу – они скормили всех наших Адской Глотке, и я должен был быть следующим... Но я ничего, ничего им не выдал!$B$BОни просто сумасшедшие. Они упрямо призывают демонические силы, которые не могут контролировать.$B$BОни увеличивают мощность вызова при помощи специальных машин, которые усиливают их осколки души. Эти устройства нужно украсть!$B$BЯ бы присоединился к тебе, но мне нужно как можно скорее вернуться в Шаттрат и доложить начальнице разведки Нижнего города.', 'Украдите 5 инструментов души и доставьте их повелительнице шпионов Мелисе Высокий Венец в Шаттрат на Террасу Света.', 'То\'гун уже был здесь и доставил мне донесение. А мог бы, на самом деле, остаться и помочь тебе.$B$BЯ отослала его обратно, помогать Грик\'те. Думаю, из них выйдет милая парочка...$B$BИтак, это и есть инструменты души, которые Совет Теней использует, чтобы увеличивать силу призыва? Мне кажется, что это опасные предметы. Может быть, Провидцы знают, что с ними делать?$B$BПожалуйста, прими от меня награду за то, что помешал Совету Теней делать свое черное дело.', 'Да? Чем могу быть полезна, $C?', NULL, NULL, 'Инструмент души', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10092, 'Атака на Магеддон', 'Мо\'арги-инженеры прикладывают все свое умение, а ган\'арги получают непрерывные поставки сырья. Этак они запустят скверноботов раньше, чем мы успеем отправить хотя бы словечко в Оргриммар.$B$BЕдинственное, что нам остается – как можно скорее атаковать их. К сожалению, я не могу дать тебе гарнизон Траллмара, иначе мы станем слишком уязвимы.$B$BСлишком много тех, кто захочет запустить в нас когти, включая тот же Альянс, если мы останемся безоружны. Не подведи нас, $N. От тебя зависит слишком многое.', 'Убейте Владыку Ночи Малфаса, который находится на Кузнечной базе: Магеддон и возвращайтесь к властителю Хану Изуверу в Погибель Сквернобота.', '', NULL, NULL, NULL, 'Владыка ночи Малфас убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10093, 'Храм Телхамат', 'К счастью, Путь Славы – не единственный, по которому может пройти мой народ. К западу отсюда уцелело несколько святых мест, хотя часть из них захватили враги.$B$BПока Велен готовился к путешествию на Азерот, те из нас, кто остался на юге, пытались возродить там жизнь.$B$BНа западе полуострова Адского Пламени, в храме Телхамат, ты найдешь небольшую горстку дренеев, которую возглавляет Амаан Мудрый. Уверен, ему будет интересно с тобой познакомиться.', 'Поговорите с Амааном Мудрым в храме Телхамат, который находится на западе полуострова Адского Пламени.', 'А, ты знаешь провидца Крива. Он мудр и обладает многими добродетелями. Любой $R, который зовет его другом, станет другом и мне.$B$BРасполагайся здесь. Можешь познакомиться с остальными обитателями храма.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10094, 'Кодекс Крови', 'Два года назад Совет Теней вызвал демона и не сумел его удержать. В результате произошел взрыв, который обрушил эту великую некогда усыпальницу. На ее месте образовались Костяные пустоши.$B$BА теперь Совет Теней собрался воевать с какими-то невероятно могучими силами.$B$B$N, тебе придется пробраться в Темный лабиринт и узнать, на кого они ополчились, и представляет ли это опасность для нас. Наши разведчики доносят, что они используют запретную книгу призывания нечисти, известную как Кодекс Крови.$B$BЯ думаю, на ее страницах ты найдешь ответы на все наши вопросы.', 'Прочитайте Кодекс Крови в Темном лабиринте в Аукиндоне.', 'Как только вы открываете парящую в воздухе книгу, вас охватывает ужас.$B$BЗдесь определенно происходит что-то страшное!$B$BВы пытаетесь читать, но то, что написано в книге, кажется совершенно невероятным.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10095, 'В самом сердце Лабиринта', 'Два года назад Совет Теней призвал некое космическое существо, но потерял над ним контроль. Именно это привел к взрыву Аукиндона и появлению Костяных пустошей.$B$BТеперь это создание, известное как Бормотун, пытается прорвать заслоны Совета Теней и проникнуть во внешний мир.$B$BГроссмейстер и все верховное руководство Совета мертвы, так что ты – наша последняя защита от этого чудовища!$B$B$N, ты и твои товарищи не могут потерпеть поражение!', 'Уничтожьте Бормотуна и доложите о том, что произошло внутри Темного лабиринта, повелительнице шпионов Мелисе Высокий Венец, которую можно найти на террасе Света в Шаттрате.', 'Бормотун едва не вырвался на волю? Почти два года они худо-бедно контролировали это существо... Но я знала, что рано или поздно они совершат ошибку и потеряют над ним контроль.$B$B$N, уничтожив этого монстра, ты спас всех нас. Боюсь даже подумать, что стало бы с Запредельем, если бы эта тварь вырвалась на свободу!$B$BЯ счастлива, что ты помог нам справиться с угрозой, которая пришла в Аукиндон по милости Совета Тени! Чем мы можем отблагодарить тебя?', NULL, NULL, NULL, 'Бормотун убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10096, 'Спасение спорлоков', 'Икейен немало рассказывал мне о том, что с ним произошло в этих пещерах. По-моему, это просто кошмар!$B$BЗнаете, наверное, мы должны что-то сделать, чтобы помочь этим бедным спорлокам. Икейен говорит, что они живут в пещере Грибгор, но недавно туда вторглись твари с болот.$B$BМожет быть, вы сходите туда и попробуете избавиться хотя бы от части болотных хищников? Пещера находится на юго-западе.', 'Убейте 10 болотных черпальщиков и 10 болотных скрытней и вернитесь к Лоранне Тар\'велл в Кенарийский приют в Зангартопи.', 'Отлично! Эти болотные твари не имеют никакого права захватывать дом спорлоков!$B$BКонечно, было бы лучше, если бы эти существа научились мирному сосуществованию, но, раз уж это невозможно, нам следует взять дело в свои руки!$B$BВот, пожалуйста, возьмите это в благодарность за труды.', NULL, NULL, NULL, 'Болотный черпальщик убито', 'Болотный скрытень убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10097, 'Брат на брата', 'Когда Аукиндон взорвался, племя Сетек с большой помпой покинуло Скеттис. Они сочли взрыв знаком прибытия их господина.$B$BМой брат Сит был одним из лидеров племени Сетек, и именно ему принадлежала идея, что мы должны выйти к руинам храма и встретить нашего бога.$B$BПосле того как мы поселились в руинах, назвав их Сетеккскими залами, я начал сомневаться в разумности моего брата и его союзника, Айкисса.$B$BЧерез некоторое время Сит изгнал меня из племени, но запретил забрать с собой нашу сестру Лакку. Ты поможешь мне спасти ее?', 'Проникните в Сетеккские залы и убейте Темнопряда Сита. Освободите из плена Лакку. После этого вернитесь к Исфару, который находится неподалеку от входа в Сетеккские залы.', 'Мне не хватает слов, чтобы выразить, как я тебе благодарен, $N! Теперь, когда Лакка свободна, оборвались последние нити, связывающие меня с племенем Сетекков.$B$BЯ никогда не прощу себе смерти Сета, но это должно было свершиться. По возвращении в Скеттис я сам исполню по нему похоронные ритуалы. Может быть, его дух обретет покой, когда искупит вину перед нашим народом, который он сбил с пути...', 'Ты сумел найти ее, $N? Или она все еще в плену?', NULL, NULL, 'Темнопряд Сит убито', 'Освободить Лакку', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10098, 'Наследство Терокка', 'Мой народ свято чтит древнего героя по имени Терокк. Птенцы араккоа упиваются историями о его подвигах и описаниями его роскошного оперения.$B$BМногие сотни лет он жил с моим народом, а потом бесследно исчез, оставив лишь маску, копье и свои труды.$B$BАраккоа почитают эти реликвии, и они были убиты горем, когда племя Сетекков, уходя из Скеттиса, похитило их и унесло с собой.$B$BЯ записал то немногое, что мне известно о местонахождении этих реликвий.', 'Принесите Маску Терокка, Перо Терокка и Сагу о Терокке Исфару, который находится неподалеку от Сетеккских залов.', 'Я стоял у истоков злодеяний племени Сетекк, и за это нет мне прощения. Может быть, возвращение реликвий Терокка хоть немного оправдает меня в глазах моего народа.$B$BСпасибо тебе за помощь, $N. Ты даже не представляешь, сколь велико совершенное тобой дело.', 'Реликвии, принадлежащие Терокку, слишком давно покинули Скеттис. Удалось ли тебе вырвать их из лап племени Сетекк?', NULL, NULL, 'Сказание о Терокке', 'Маска Терокка', 'Перо Терокка', 'Реликвии Терокка');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10099, 'Мозговой центр', 'Эти чертовы ган\'арги продолжают расползаться по всему руднику! Только убьешь одного, как его место занимают сразу трое!$B$BНаверняка есть кто-то, кто руководит этим вторжением из самых глубин рудника. В прошлый раз ты $gвел:вела: себя достаточно храбро, и я не исключаю, что ты $gединственный:единственная: у кого достанет отваги, чтобы спуститься в рудник еще раз. Найди того, кто стоит у истоков всех этих беспорядков, и пусть он дорого нам заплатит!', 'Найдите и убейте З\'крала в рудниках под Оплотом Чести, и доложите об этом штейгеру Большие Десны.', 'Я так рад, что ты смог позаботиться о...о... Как, ты говоришь, оно себя называло? З\'Крел?$B$BПо твоему описанию я не смог понять, какого оно пола. Но это совершенно не важно, раз оно уже дохлое.', 'Я даже боюсь спрашивать. Если ты выбрался из рудника живым, то варианта только два: тебе удалось прикончить эту сволочь, или у тебя отказали нервы. Ну так что, в итоге?', NULL, NULL, 'З\'крел убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10100, 'Мозговой центр', 'Не пойми меня неправильно, $N, я рад, что ты $gсогласился:согласилась: помочь нам, но на каждого убитого подрывника приходится двое живых.$B$BЯ отправил донесение командиру Кранку, но он так и не прислал мне помощи. Только какое-то невнятное бормотание про зловепрей. Если бы я не боялся, что это выйдет мне боком, я бы сказал ему, что не время думать об охоте!$B$BВ любом случае, похоже, кто-то тут, на рудниках, заправляет этими беспорядками. Его надо найти и убить!', 'Найдите и убейте Урга\'зза в рудниках под Траллмаром, и доложите об этом штейгеру Разлкразу.', '', NULL, NULL, NULL, 'Урга\'зз убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10101, 'Когда говорят духи', 'Ошу\'гун, алмазная гора, когда-то была святыней моего народа. Каждый год все кланы собирались у ее подножия, чтобы отпраздновать наступление весны. Именно там верховный шаман взывал к духам наших досточтимых предков. Гора была центром нашей культуры, пока сумрак не поглотил нас. Когда кланы стали дикой и неуправляемой ордой, духи Ошу\'гуна умолкли. Предки отвернулись от нас.$B$BНо что-то нарушило их вечный покой. Отправляйся к Ошу\'гуну и узнай у него, что потревожило покой наших предков.', 'Разыщите К\'уре в Ошу\'гуне.', '<К вам в сознание проникает нежный, мелодичный голос.>$B$BЯ – наару по имени К\'уре, $N. Ты проник в самое сердце моего древнего корабля.$B$BОшу\'гун, как его называют орки, на самом деле – корабль, который впервые принес дренеев в этот мир. Хотя мы потерпели крушение много веков назад, моя энергия до сих пор заперта внутри обломков корабля. Увы, именно я и есть источник страданий орочьих духов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10102, 'Раскрытая тайна', 'Долгие столетия я беспомощно наблюдал, как иссякает моя энергия, затягивая в образовавшуюся пустоту поколения орочьих душ. Но недавно мои враги подчинили себе этот водоворот и принялись пополнять Пылающий Легион бессчетными ордами тварей Бездны.$B$BИ теперь, чтобы разорвать этот круг и освободить души орков, нужна помощь другого наару – А\'дала. Я ощущаю его присутствие в древнем городе Шаттрате в лесу Тероккар.', 'Поговорите с А\'далом в Шаттрате.', 'К\'уре поступил мудро, отправив тебя сюда. Увы, мы не в силах облегчить страдания орочьих предков, но я знаю, кто сможет тебе помочь.$B$BЭто тот, кому очень скоро предстоит возродиться в лучах Света...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10103, 'Донесение Зураю', 'После прибытия полевого командира Ромуса с подкреплением Альянс и его дренейские приятели чересчур осмелели. Они окопались во всех дренейских руинах отсюда и аж до Шаттрата.$B$BВ ответ тролли заложили новую заставу в восточной части Зангартопи, к югу от Мертвой трясины, и окрестили ее заставой Болотной Крысы. Они еще способны шутить, обитая в подобном месте! Я вот так не могу.$B$BКомандир заставы просил меня прислать к ним кого-нибудь из резерва.', 'Поговорите с Зураем на заставе Болотной Крысы в Зангартопи.', 'Откровенно говоря, я ожидал большего, но и для тебя дело найдется. Добро пожаловать на заставу Болотной Крысы!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10104, 'Опасения за судьбу Туурема', 'О судьбе Туурема ходят тревожные слухи. Говорят, что в развалинах города ютятся обезумевшие Сломленные и Заблудшие, а тем временем охотники за сокровищами расхищают дренейские реликвии. Что тут правда, а что нет, сказать трудно, однако мы обязаны сберечь эти руины, насколько это возможно. Отправляйся в бастион Аллерии в лесу Тероккар и отыщи там Андарла. Он немного интересуется магическими артефактами. И если кто-то и знает, что происходит в Тууреме, то это именно Андарл.', 'Поговорите с Андарлом в бастионе Аллерии в Тероккаре. ', 'Я, разумеется, польщен тем, что твой друг-сломленный считает меня специалистом по реликвиям его народа, но, если честно, с тех пор, как я сюда прибыл, у меня почти не было возможности их изучать. Конечно, я явился сюда именно ради них, но по прибытии обнаружилось, что здесь есть много куда более важных дел...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10105, 'Вести для Ракории', 'Теперь, когда застава Болотной Крысы достроена, нам будет куда проще охранять дороги, ведущие на болота. А вот в лесу Тероккар все куда хуже... И тем не менее Ракория, которая живет в Форте Камнеломов, ждет известий о том, как у нас дела.$B$BОна – баба расторопная и сметливая, но ты, $N, держи с ней ухо востро. Она заинтересована в том, чтобы дороги были безопасны, но не думай, будто у нас с ней общие интересы. Ракорию прежде всего интересует прибыль.', 'Поговорите с Ракорией из форта Камнеломов в лесу Тероккар. ', 'Я рассчитывала, что его бойцы достроят заставу раньше, но ему-то куда спешить, он на этом денег не теряет. Ну, хоть теперь достроили, и на том спасибо.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10106, 'Штурмовые укрепления', 'Цитадель Адского Пламени уже долгое время отбивает все наши атаки. Мы сохраняем позиции, но не можем перейти в решительное наступление. Нам необходимо укрепить передовые.$B$BРазведчики обнаружили рядом с цитаделью Адского Пламени три форта. Мы должны их захватить. Помоги нашим войскам и доложи мне, когда все три перейдут к нам.$B$BПусть удача сопутствует тебе в битве, $N. Скорее всего, Орда тоже положила глаз на эти укрепления, так что тебе придется иметь дело с ее войсками.', 'Захватите обзорную площадку, ристалище и Изрезанный холм, и возвращайтесь к прапорщику Трейси Праудвелл в Оплот Чести на полуострове Адского Пламени.', 'Ты славно потрудился, $N. Благодаря твоим ратным подвигам мы еще долго продержимся на Полуострове Адского Пламени!', NULL, NULL, NULL, 'Захватите Обзорную площадку', 'Захватите Ристалище', 'Захватите Изрезанный холм', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10107, 'Дипломатическая миссия', 'Килрат передал нам сведения про вождя клана Тяжелого Кулака: это орк! Древний орк, который прошел через Темный портал еще во времена наших отцов и вернулся назад. Если бы ты $gнашел:нашла: его и $gубедил:уговорила: отозвать огров... Его ставка находится на верхнем плато руин Пылающего Клинка на юго-востоке, на окраине леса Тероккар. Удачи, $N!$B$BИ будь $gосторожен:осторожна:, он мастерски владеет мечом...', 'Джорин Мертвый Глаз из Гарадара в Награнде попросил вас поговорить с Лантрезором Клинком в руинах Пылающего Клинка.', 'Так что ты решил? Мы будем воевать или ты окажешь нам помощь?', 'Говори.', NULL, NULL, 'Выслушайте историю Лантрезора.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10108, 'Дипломатическая миссия', 'Лазутчики-охотницы передали нам сведения про вождя клана Тяжелого Кулака: это орк! Древний орк, который прошел через Темный портал еще во времена наших отцов и вернулся назад. Если бы ты $gнашел:нашла: его и $gубедил:уговорила: отозвать огров... Его ставка находится на верхнем плато руин Пылающего Клинка на юго-востоке. Удачи, $N!$B$BИ будь $gосторожен:осторожна:, он мастерски владеет мечом...', 'Мо\'мор Разрушитель из Телаара в Награнде попросил вас поговорить с Лантрезором Клинком в руинах Пылающего Клинка.', 'Так что ты решил? Мы будем воевать или ты окажешь нам помощь?', 'Говори.', NULL, NULL, 'Выслушайте историю Лантрезора.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10109, 'Я их достану!', 'Видишь? Клянусь зловонным дыханием Газлоу, я достану эти яйца! Кстати, ты мне можешь пригодиться.$B$BВот что я тебе скажу, $r: найди мне кое-какие детали для моего \"Прыготрона-4000\", а я дам тебе ключ для управления этим механизмом. У меня как раз есть запасной! Ты спросишь, на что способна эта штуковина? Легче сказать, чего \"Прыготрон-4000\" не может...$B$BМне понадобится пар элементалей воздуха, собранный с Награндских элементалей воздуха. И не спрашивай, как их найти: они там повсюду!', 'Принесите 3 порции пара элементалей воздуха Вазату в Южный Награнд. ', 'Великолепно! Еще пара деталей – и будет как новенький. Ах да, вот твой ключ. Держи!$B$BПрыготрон еще не отлажен. Так что… поосторожнее с ним.', 'Газ достал?', NULL, NULL, 'Пар элементалей воздуха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10110, 'Штурмовые укрепления', 'Мы должны стереть проклятых орков Скверны с лица нашей земли! Но перед тем, как напасть на цитадель Адского Пламени, необходимо укрепить позиции.$B$BГонцы обнаружили три форта, которые хорошо подходят для наших целей. К сожалению, Альянсу пришла в голову та же идея, и он уже выдвинул войска, чтобы захватить эти укрепления.$B$BТы $gдолжен:должна: отбросить силы Альянса и помочь нашему войску захватить все три форта. Когда выполнишь это задание, возвращайся ко мне.$B$BВо славу Орды!', 'Захватите Обзорную площадку, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.', 'Славная работа, $N. Я как наяву слышу звуки битвы, которая там разыгралась. Хотела бы я это видеть своими глазами!', 'Возвращайся, когда все укрепления будут захвачены!', NULL, NULL, 'Захватите Обзорную площадку', 'Захватите Ристалище', 'Захватите Изрезанный холм', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10111, 'Принеси мне яйцо!', 'Ну, раз уж тебя пригласили туда, постарайся добыть для меня это яйцо! Воспользуйся прыготроном и попробуй попасть в самый центр гнезда. Но будь $gосторожен:осторожна:! Неудачный прыжок может закончиться серьезными травмами или неизлечимым увечьем.', 'С помощью Прыготрона-4000 запрыгните в гнездо на ближайшем дереве и украдите оттуда таинственное яйцо.', 'Э... это не яйцо... Погоди-ка! Цыпляток я тоже люблю! Их огромные коготочки так славно хрустят на зубах! Вот спасибо!', 'Я говорил, как люблю яйца?', NULL, NULL, 'Попытайтесь украсть яйцо', 'Отрубленный коготь Матриарха', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10112, 'Личное одолжение', 'Мммм? Коробка, говорите? Или несколько коробок? А из какого материала она была сделана?$B$BИ как звали торговца? Эмпур? Вы уверены, что он из Сломленных? Я вообще-то с ними дел не имею.$B$BХотя я мог бы сделать для вас исключение, но только в обмен на услугу!$B$BЭти примитивные колдуны – скитийские араккоа – недавно украли большую партию моих экзотических товаров, и я хочу вернуть их!$B$BОни утащили мои вещи в гнездовье Скит, это к югу от Шаттрата.', 'Найдите 5 украденных товаров Латрая и верните их хозяину. Латрая можно найти возле таверны \"На краю земли\" в Нижнем городе Шаттрата.', 'Да, в самом деле, я все вспомнил!$B$BИ я думаю, что вы заработали чуть больше, чем ваша драгоценная информация.', 'Хммм, неужто моя память улучшается?', NULL, NULL, 'Украденные товары Латрая', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10113, 'Охотничий лагерь Эрнестуэя', '\"Иди и найди какие-нибудь припасы!\" – так он и сказал. Да меня раз пятнадцать чуть не укокошили, пока я сюда добирался! Эти Сломленные, конечно, не самые добродушные ребята на свете, но они хотя бы не пытаются меня освежевать.$B$BТак или иначе, назад я не вернусь. Кончились мои охотничьи деньки. Если ты направишься на северо-восток, в сторону Зангартопи, и вдруг набредешь на охотничий лагерь Эрнестуэя, передай им, что \"Дробовик\" отстрелялся!$B$BПослушай, а может, ты займешь мое место? Попробуй, и пусть тебе улыбнется удача, $gнезнакомец:незнакомка:.', 'Поговорите с Хемингом Эрнестуэем в охотничьем лагере Эрнестуэя на северо-восточной границе Награнда.', 'М-да, придется искать нового мальчика на побегушках. Э...Ну или девочку. Ты мне подойдешь, $C. Может, поработаешь на меня? Или ты собираешься охотиться?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10114, 'Охотничий лагерь Эрнестуэя', 'Эти орки никогда раньше не видели тауренов, как бы невероятно это ни звучало. Если бы не капитан Крогхан, они бы уже готовили из меня ужин.$B$BНо простите мою бестактность, я же не представился. Я – Олорм Странник, величайший из охотников! Я вхожу в экспедицию Эрнестуэя, прибывшую сюда из Азерота в поисках большой добычи. Если вас интересует охота, присоединяйтесь к моим людям в охотничьем лагере Эрнестуэя. Он находится к востоку отсюда, у границы с Зангартопью.', 'Олорм Странник просит вас поговорить со Странником Шадо \"Фитцем\" в охотничьем лагере Эрнестуэя в Награнде.', 'Отрадно слышать, что он в безопасности. Ты хочешь присоединиться к охоте?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10115, 'Искажение Остротопи', 'Куренай и дренеи не всегда сходятся во взглядах, особенно когда речь идет о Заблудших. Мы помогаем Заблудшим, которые к нам обращаются, но не донимаем их своими наставлениями. Некоторые же дренеи слишком навязчиво пытаются их \"обратить\".$B$BОднако бывают случаи, когда Заблудшие заходят чересчур далеко. Таково и племя Остротопи. В своей деревне к западу отсюда эти Заблудшие изготовляют яды и упражняются в обмане и подлости. Эти ремесла никогда не были близки дренеям!$B$BНеобходимо это пресечь, пока подлое племя Остротопи не распространило свое влияние дальше...', 'Убейте 3 убийц Остротопи и 15 грязекопов Остротопи. ', 'Молодец, $N. Племя Остротопи абсолютно безнадежно, с какой стороны ни взгляни, но я не уверен, что дренеям хватило бы духу быстро принять соответствующие меры.', NULL, NULL, NULL, 'Убийца Остротопи убито', 'Грязекоп Остротопи убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10116, 'Разыскивается: вождь Муммаки!', 'Объявляется розыск вождя Муммаки, предводителя гнусного и выродившегося племени Заблудших, обитающего в Остротопи, за жестокие нападения на прибежище Оребор.$B$BВождь и его банда убийц виновны в смерти множества куренаев и дренеев. С ними стоит иметь дело только опытным бойцам!$B$BПутешественникам рекомендуется избегать окрестностей деревни Остротопь, расположенной к западу от прибежища Оребор.$B$BЧтобы получить награду, следует представить Икути доказательства смерти вождя.', 'Принесите тотем вождя Муммаки Икути в прибежище Оребор. ', 'Неплохо! До тебя были и другие, кто надеялся получить награду, но они так и не вернулись за ней. Нетрудно представить, что с ними стало.$B$BЯ рад, что Муммаки и его ублюдки больше не будут нас тревожить.', 'Так ты хочешь получить награду за вождя Муммаки?', NULL, NULL, 'Тотем вождя Муммаки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10117, 'Разыскивается: вождь Муммаки!', 'Объявляется розыск вождя Муммаки, предводителя гнусного и выродившегося племени Заблудших, обитающего в Остротопи, за жестокие нападения на Забра\'джин и его обитателей.$B$BВождь и его банда убийц виновны в смерти множества разведчиков и гонцов. С ними стоит иметь дело только опытным бойцам!$B$BПутешественникам рекомендуется избегать окрестностей деревни Остротопь, расположенной к северо-западу от Забра\'джина.$B$BЧтобы получить награду, следует представить доказательства смерти вождя темному охотнику Денжаю.', 'Принесите тотем вождя Муммаки темному охотнику Денжаю. ', 'Благодарю тебя, $N! А то я уже начал думать, что мне придется отправиться туда самому, взяв с собой значительную часть гарнизона. А что бы тогда могло стать с Забра\'джином – и думать не хочется...', 'Так ты хочешь получить награду за вождя Муммаки?', NULL, NULL, 'Тотем вождя Муммаки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10118, 'Разговор с Остротопью', 'Из всех племен Заблудших в Зангартопи племя Остротопи – самое злобное и хитрое! Они хорошо организованы и не скрывают, что стремятся подчинить себе всех прочих Заблудших, что живут на болотах.$B$BОни уже не раз нападали на моих разведчиков и гонцов. Я не могу себе позволить и дальше терять воинов!$B$BЕсли мы ничего не предпримем в ближайшее время, они перекроют все дороги, и Забра\'джин окажется в осаде!', 'Убейте 3 убийц и 15 грязекопов из племени Остротопи, и вернитесь к темному охотнику Денжаю в Забра\'джин.', 'Думаю, твоя беседа окажется для них достаточно доходчивой. Этот язык они понимают отлично. Теперь и мои бойцы не будут так страшиться встречи с племенем Остротопи. Или же, по крайней мере, они станут стыдиться своей трусости!', NULL, NULL, NULL, 'Убийца Остротопи убито', 'Грязекоп Остротопи убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10119, 'Через Темный портал', 'В течение двадцати лет Темный портал оставался безмолвным монументом – памятником давно забытым временам. $B$B<Релторн оглядывается по сторонам.>$B$BНикогда не думал, что доживу до этого дня, и тем не менее мы стоим здесь и смотрим в бездну.$B$BПо другую сторону этого портала мы втянуты в жестокую войну – войну, которую без поддержки нам не выиграть. Тебе следует пройти через Темный портал и помочь нашим войскам, $C.$B$BНемедленно явись к командиру Дарону. Он ждет тебя в Запределье...', 'Пройдите через Темный портал и найдите командора Дарона. Он ждет вашего прибытия на другой стороне, в Запределье.', 'Добро пожаловать в Запределье, $N, добро пожаловать в кошмар! Наш экспедиционный корпус благополучно добрался сюда, но с тех пор Легион непрерывно пытается отбить Темный портал и отрезать нас от подкреплений с другой стороны.$B$BИ хотя нам не помешала бы твоя помощь, наши войска и солдаты Орды пока могут отбивать атаки Легиона и удерживать этот плацдарм.$B$BТвои таланты нужны там, где им найдется наилучшее применение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10120, 'Прибытие в Запределье', 'С помощью Альянса наши силы будут удерживать эти позиции, но ты $gдолжен:должна: доставить мое донесение генералу Кракорку в Траллмар. Когда он присоединится к нам, мы вышвырнем демонов обратно в бездну, которая их породила! Поговори с Влаггой Легкоперой, она стоит на площадке позади нас. Она поможет тебе добраться побыстрее.', 'Доставьте донесение Ориона Влагге Легкоперой у Темного портала на полуострове Адского Пламени.', 'Значит, теперь ты новый посланник Ориона. Надеюсь, ты стоишь больше, чем предыдущие, $C. Легион постоянно нас атакует, и идти пешком до Траллмара лучше даже не пробовать. Ничего, моя испытанная виверна доставит тебя, куда скажешь, и волос с головы не упадет.', 'Я слышала, ты говорил с Орионом. Должно быть, важное дело.', NULL, NULL, 'Донесение Ориона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10121, 'Истребить Пылающий Легион', 'Эти земли полны угроз, но Пылающий Легион по-прежнему остается самым главным врагом Экспедиции. Один из моих самых верных воинов, сержант Лободроб, как-то изучал тактику Легиона – пытался понять, что же им нужно в этих землях. Его можно найти в одном из караванов рядом с южной стеной.$B$BБудь поосторожнее с Легионом, $N. Зло нельзя недооценивать.', 'Поговорите с сержантом Лободробом, который находится при караване к востоку от Траллмара.', 'Несомненно, ты видел войска Легиона с воздуха, когда летел от Темного портала. Лет пять назад мы разгромили их в битве за гору Хиджал, но проклятые демоны снова ползут сюда, как тараканы. Если они хотят войны, то они ее получат!$B$BУ нас, орков, солидный счет к Легиону. Что, $N? Рассказать тебе о наших врагах?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10122, 'Вблизи цитадели', 'День за днем цитадель Адского Пламени открывает свои врата, из нее выплескивается новая волна орков Скверны и растекается по лагерям, разбитым вдоль крепостного вала к югу.$B$BЯ отправила одного из своих самых способных разведчиков, рядового Имариона, следить за численностью орков, их передвижениями и подготовкой, но от него до сих пор нет ответа.$B$BИмарион должен был наблюдать за самым ближним лагерем у южного бастиона, там, где он соединяется с цитаделью. Найди его, $N. Без его сведений мы станем легкой добычей.', 'Найдите следы рядового Имариона у самого северного лагеря орков Скверны, расположенного у Южного бастиона.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10123, 'Лощина Вспышки Скверны', 'В Запределье Пылающий Легион возглавляет владыка судеб Каззак. До самого Каззака нам, к сожалению, не дотянуться. Но мы можем, – и должны! – убрать его лейтенантов, которые находятся здесь и отдают приказы войскам Легиона.$B$BВ Лощине Адской Искры, к востоку отсюда, расположились повелители ужаса. Именно они вызвали этот адский шторм, который обрушился на наши головы. Уничтожь их, и пусть их прислужники сочтут за лучшее убраться отсюда.', 'Убейте 4 бесов-поджигателей, 6 инферналов-завоевателей и 1 вестника Ужаса по просьбе сержанта Лободроба, который находится при караване к востоку от Траллмара.', 'Славная работа, солдат! Могу сказать точно, частота атак сократилась, – хотя бы на время, пока они не призовут новых повелителей Ужаса.$B$BА теперь плохие новости: у меня для тебя новое задание.', NULL, NULL, NULL, 'Вестник Ужаса убито', 'Бес-поджигатель убито', 'Инфернал-завоеватель убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10124, 'Передовая застава: Останки Сквернобота', 'Верховное командование заметило твою доблесть в бою, $C. Тебя хотят отправить на передовую для встречи с командой Изуверского кулака. Это радикалы, твердо намеренные извести под корень Пылающий Легион, так что подойдешь...$B$BИди на восток 200 шагов, потом повернешь на юг у возвышенности. Увидишь останки Сквернобота на том месте, где прежде стояла старая ферма. Как окажешься там, докладываешься передовому командиру То\'Арху.$B$BШагом марш!', 'Доложитесь командиру передовой То\'арху по прибытии к останкам Сквернобота.', 'Да ты, оказывается, один из тех, кто участвовал в зачистке лощины Вспышки Скверны? Приятно слышать. Нам нужны солдаты, способные отправить демонов обратно в Преисподнюю!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10125, 'Задание: разрушить связь', 'Прямо на восток отсюда проходит передовая Легиона. Одновременно она служит линией связи, - приглядись, и увидишь, что везде торчат антенны. Они обеспечивают связь между лагерями Легиона по всему Запределью, и вдобавок создают возмущения, которые не дают считывать передачи и вести магическое наблюдение.$B$BВозьми взрывчатку и уничтожь все антенны. Очень важно не пропустить ни одной, $N. Они тянутся вдоль всей передовой Легиона с севера на юг.', 'Уничтожьте Антенну Легиона: Злоба, Антенну Легиона: Ярость, Антенну Легиона: Ненависть, Антенну Легиона: Страх с помощью взрывчатки То\'арха по приказу командира передовой То\'арха в Погибели Сквернобота на Полуострове Адского Пламени.', '', NULL, NULL, NULL, 'Антенна Легиона: Злоба – уничтожена', 'Антенна Легиона: Ярость – уничтожена', 'Антенна Легиона: Ненависть – уничтожена', 'Антенна Легиона: Страх – уничтожена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10126, 'Приказы боевого командира Некрогга', 'В приказе, подписанном боевым командиром Некроггом, значится, что отряд орков Скверны должен доставить пленников из этого лагеря куда-то на юг, для дальнейшего дознания.$B$BЛейтенант Амади просила передать, что весь Южный бастион испещрен лагерями орков Скверны. Возможно, туда и переведут рядового Имариона.$B$BПо какой-то причине его приказано оставить в живых. Попытайся спасти Имариона, пока они не изменили свое решение.', 'Проследуйте к югу вдоль западной части Южного бастиона и разыщите в одном из лагерей следы рядового Имариона.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10127, 'Задание: Ослабить врага', 'Не приказать тебе уничтожить демонов передовой Легиона, который находится к востоку от нашей базы, было бы нарушением воинского долга.$B$BОбе линии переводой организованы по одному и тому же принципу: между лагерями патрулируют укротители Скверны, которых, в свою очередь, охраняют стражи гнева. За обеспечение всей операции отвечает шиван-поработитель. Убей всех, кто тебе попадется, пусть Каззак сам разбирается, кого поутру недостанет в его войске.$B$BТолько остерегайся скверноботов. Я знаю, ты не $gслабак:слабачка:, но эта штука заставит попотеть даже тебя.', 'Убейте 4 укротителей Скверны, 8 гневостражей и поработительницу Ши\'азив по приказу командира передовой То\'арха у останков Сквернобота на Полуострове Адского Пламени.', '', NULL, NULL, NULL, 'Поработительница Ши\'азив убито', 'Укротитель Скверны убито', 'Страж гнева убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10128, 'Спасти рядового Имариона', 'От места, где мы обнаружили вещи Имариона, следы ведут куда-то югу, вдоль Южного бастиона. Многочисленные знаки говорят о том, что его похитители очень торопились. Не понятно только, почему. $B$BМожет быть, Имариона желает допросить сам боевой командир Некрогг? Именно его имя стояло в том приказе, который ты $gпринес:принесла:.$B$BБрошенный щит и оставленные следы загадывают больше загадок, чем разрешают, но мне кажется, что где боевой командир Некрогг, там будет и рядовой Имарион.', 'Следуйте дальше к югу вдоль Южного бастиона и постарайтесь найти, где боевой командир Некрогг держит в плену рядового Имариона.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10129, 'Задание: Врата Муркет и Шаадраз', 'Мы обнаружили два главных портала, через которые Пылающий Легион получает подкрепление. Это Врата Муркет и Врата Шаадраз.$B$BПосмотри на восток, туда, куда ведет Путь Славы. Порталы стоят по обе стороны от него, и я приказываю стереть их с лица земли.$B$BВозьми эти бомбы, они разработаны гоблинами Зоны 52 специально для подобных целей. И пусть командир звена Бракк даст тебе виверну.', 'Поговорите с командиром звена Бракком, разбомбите Врата Муркет и Шаадраз, затем возвращайтесь к командиру передовой То\'арху к останкам Сквернобота.', 'Теперь они долго не сумеют оклематься! Просто фантастика, $N! Такого яростного сопротивления Легион точно не ждал!', 'Даже если промахнешься, не унывай, попробуй еще раз...', NULL, NULL, 'Врата Муркет уничтожены', 'Врата Шаадраз уничтожены', 'Сефориевый модулятор Пустоты PU-36 (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10130, 'Западный фланг', 'Орки Скверны получили новый приказ – готовить войска и боевую технику к наступлению.$B$BОплот Чести хотят зажать в тиски и армия боевого командира Некрогга должна сформировать западный фланг.$B$BЕсли Оплот атакуют с запада, когда гарнизон будет занят обороной восточных стен, то вряд ли мы сумеем отбиться. Единственная наша надежда – вывести из строя западный фланг еще до начала сражения.', 'Убейте 10 стражников, 10 берсерков и 5 послушников из клана Изувеченной Длани. О выполнении задания доложите лейтенанту Амади, которая будет ждать вас в западной сторожевой башне Оплота Чести.', '', NULL, NULL, NULL, 'Стражник из клана Изувеченной Длани убито', 'Берсерк из клана Изувеченной Длани убито', 'Послушник из клана Изувеченной Длани убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10131, 'План побега', 'Как я уже говорил, выбраться отсюда будет непросто. Боевой командир Некрогг выглядит как тупой бугай, но он отнюдь не дурак.$B$BОн внимательно следит за ключом и не вылезет из своей башни, вон там, наверху, пока все не будет готово для допроса. Допрашивать станут меня или вон того орка, которого тоже поймали.$B$BДолжно случиться что-то из ряда вон выходящее, чтобы он спустился, но у меня есть идея. Найди кого-нибудь из гренадеров, которые патрулируют Южный бастион и принеси мне его взрывчатку.', 'Убейте гренадера клана Изувеченной Длани и принесите примитивную взрывчатку рядовому Имариону в форт Гор\'газ.', '', NULL, NULL, NULL, 'Примитивная взрывчатка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10132, 'Колоссальная угроза', 'Видишь огромный красный кристалл, там, на севере? Он недавно свалился с неба, при этом содрогнулась вся земля.$B$BКогда мы пришли посмотреть, что же случилось, вокруг кристалла уже собрались великаны. Им тоже было интересно, что такое упало с небес.$B$BВ этом кристалле есть что-то странное... и в излучаемой им энергии... но у меня нет времени разбираться. Прежде всего меня беспокоят горные великаны.$B$BНужно, чтобы ты $gсобрал:собрала: друзей, $gотправился:отправилась: на Гряду Упавшего Неба и $gразделался:разделалась: с ними.', 'Убейте 5 яростных колоссов и возвращайтесь к Тола\'тиону на Кенарийскую заставу на полуострове Адского Пламени.', 'Хорошо сработано.$B$BЯ считаю, что если мы уничтожим достаточно горных великанов, то можно не беспокоиться о кристалле, который свалился на самую середину хребта.$B$BПрими этот небольшой дар от Кенарийской экспедиции.', NULL, NULL, NULL, 'Гневный колосс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10133, 'Задание: убить гонца', 'Ты уже изрядно $gнавредил:навредила: Легиону, $N. Разведчики доносят, что теперь они отправляют важные бумаги только курьером. Их войска лишены связи с центром!$B$BЯ дам тебе задание, которое не по силам обычному солдату.$B$BКурьер Легиона направится по маршруту от прудов Аггонара до Кузнечной базы: Магеддон, к северу отсюда. Ты $gдолжен:должна: выследить и перехватить его, и доставить мне послание Легиона.', 'Найдите Арикс\'малидаша, убейте его и заберите Послание Легиона по приказу командира передовой То\'арха у останков Сквернобота.', '', NULL, NULL, NULL, 'Послание Легиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10134, 'Ключ к разгадке алого кристалла', 'Глядя на убитого вами колосса, вы замечаете, что он сжимает в руке кусок красного кристалла.$B$BКристалл кажется совершенно незаметным в гигантской ладони, но с вашей точки зрения это довольно большой и тяжелый кусок. Кристалл – уменьшенная, но точная копия своего гигантского собрата, упавшего на гребень.$B$BОпределенно, здесь таится ключ к разгадке всех происходящих странностей, и вы уверены, что друиды на Кенарийской заставе должны увидеть этот странный кристалл.', 'Доставьте осколок алого кристалла Тола\'тиону на Кенарийскую заставу на полуострове Адского Пламени.', 'Хммм... На вид просто глыба необработанного кристалла.$B$BПравда, я чувствую некую ауру зла, которая его окружает, но такими вещами я не занимаюсь. Я должен очистить это место от горных великанов, остальное – не мое дело.', 'Какой большой кристалл. Ты нашел его на гребне после сражения с колоссами?$B$BДай взглянуть.', NULL, NULL, 'Осколок алого кристалла (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10135, 'Задание: доставить послание', 'Я всего лишь полевой командир, $C. Когда речь идет о подобных сведениях, принимать решение может только наш вождь, Назгрел. Ты $gдолжен:должна: доставить ему донесение в Траллмар. Попутного ветра тебе, солдат. Желаю добраться в целости и сохранности.', 'Доставьте Послание Легиона Назгрелу в Траллмар на Полуострове Адского Пламени.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10136, 'Безжалостные планы', 'Магистр Кровавый Ястреб наконец раскодировал послание Легиона, которое ты нам $gдоставил:доставила:. Как выяснилось, мы перехватили планы наступления, за которое отвечает один из лейтенантов владыки Каззака, Араззиус Безжалостный. Этот Араззиус командует наземными войсками Легиона на полуострове. Ничего, $N, не долго ему осталось командовать.$B$BОтправляйся к западу от прудов Аггонара и избавь мир от этого \"владыки Легиона\". Полуостров Адского Пламени принадлежит Орде! Пусть Легион катится обратно к себе в преисподнюю.', 'Убейте Араззиуса Безжалостного и возвращайтесь к Назгрелу в Траллмар.', 'Сменится много поколений, но песни о твоей отваге не смолкнут, $N. Хотел бы я, чтобы Тралл мог отпраздновать твою победу вместе с нами. Легион отступил, отныне Полуостров Адского Пламени принадлежит только Орде! Для нас снова возродилась надежда, что мы поднимем этот мир из руин.$B$BЛок\'тар Огар!', NULL, NULL, NULL, 'Араззиус Безжалостный убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10137, 'Провокация', 'Сработает план или провалится, зависит только от взрывчатки.$B$BНенавижу полагаться на что-то, сделанное орками, но это наш единственный шанс выбраться отсюда. Возьми взрывчатку и швырни об флаг, вывешенный на башне.$B$BОн должен взорваться с большим грохотом, и Нейкрогг не устоит перед желанием выйти наружу, поймать нарушителя и сделать из него котлету. Убей его, возьми ключ и открой мою клетку. Удачи тебе, $N.', 'Используйте примитивную взрывчатку, чтобы создать шум и выманить боевого командира Некрогга из его башни. Убейте его, заберите Ключ Некрогга и откройте клетку рядового Имариона. Об освобождении рядового Имариона доложите лейтенанту Амади.', '', NULL, NULL, NULL, 'Спасите рядового Имариона', 'Ключ Некрогга', 'Примитивная взрывчатка', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10138, 'Кто отдает приказы?', 'Ясно только одно, $N: долго мы здесь не продержимся. Мы окружены, и на место одного убитого орка Скверны тотчас становятся трое новых. Мы не выиграем эту войну, спрятавшись за полуразрушенными стенами Оплота Чести и считая дни, когда же нас прикончит если не Легион, так орки Скверны. $B$BТы уже $gсовершил:совершила: подвиг, сорвав основную атаку орков Скверны, но сейчас тебе придется пробиться через Путь Славы и узнать, кто ими управляет.', 'Убейте 20 рубак и 10 чернокнижников клана Изувеченной Длани и захватите распоряжения военного инструктора Зурока. После этого возвращайтесь к лейтенанту Амади в западную сторожевую башню Оплота Чести.', '', NULL, NULL, NULL, 'Рубака клана Изувеченной Длани убито', 'Чернокнижник клана Изувеченной Длани убито', 'Распоряжения военного инструктора Зурока', 'Рекомендуемое количество игроков: 2');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10139, 'Разжаловать командира', 'Насколько мне известно, военный инструктор Зурок – правая рука предводителя орков Скверны, командира соединения Горакса.$B$BЭтот Горакс, – не то, что обычные оркские бугаи. Он так ловко и изощренно вынуждает нас постоянно обороняться, что восхищает даже меня.$B$BВ приказах Зурока упоминается, что ставка командования Горакса расположена в конце Пути Славы, там где Цитадель сходится с Северным бастионом. Думаю, можно не говорить, что от тебя ожидается, $N, но в одиночку туда лучше не отправляться.', 'Уничтожьте командира соединения Горакса и доложите о выполнении задания лейтенанту Амади, которая находится в западной башне Оплота Чести.', '', NULL, NULL, NULL, 'Командир соединения Горакс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10140, 'Путешествие в Оплот Чести', 'Как только будешь $gготов:готова:, я организую для тебя прямой перелет в Оплот Чести.$B$BПо прибытии доложись маршалу Исилдору и передай ему донесение Дурона. Уверен, маршал будет рад еще одному новобранцу из своих земель. К тому же в донесении речь наверняка пойдет о делах крайней важности.', 'Долетите до Оплота Чести и доставьте донесение Дурона маршалу Исилдору.', 'Наша экспедиция едва сдвинулась с места в этом заброшенном, проклятом мире, $N. Мы оказались не готовы к сопротивлению.$B$BСтолкнуться лицом к лицу с Пылающим Легионом еще не так страшно – ужасы этой земли превосходят все, что нам раньше встречалось.', 'Хвала Свету, ты добрался благополучно. Оплоту Чести нужны закаленные в боях солдаты.', NULL, NULL, 'Донесение Дурона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10141, 'Возрожденный Легион', 'Пока шло вторжение в Азерот, Легион не ослаблял позиций и здесь, в Запределье. Мы наблюдаем за его активностью уже много лет, но в последнее время, $C, творится что-то совсем невообразимое.$B$BРазыщи сержанта Альтуму, она находится при Восточном караване. Альтума долго наблюдала за Легионом, может быть, она поймет, что там сейчас происходит.$B$BДействовать надо быстро, но осторожно. Не забывай, Легион нельзя недооценивать!', 'Поговорите с сержантом Альтумой, которая находится рядом с восточным караваном, к востоку от Оплота Чести.', 'Должно быть, командир армии Данат не понял, что я просила о подкреплении. Ты выглядишь годным для службы, но я просила целый батальон!$B$BПонимаешь, у нас тут небольшая проблема с демонами...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10142, 'Путь Страданий', 'В Запределье Пылающий Легион возглавляет владыка судеб Каззак. До самого Каззака нам пока, к сожалению, не дотянуться. Но мы можем, – и должны! – убрать его лейтенантов, которые находятся здесь и отдают приказы войскам Легиона.$B$BОни расставили повелителей ужаса на Пути Страданий, к востоку отсюда. Именно они вызвали этот град из инферналов, который обрушился на наши головы. Уничтожь их, и тогда их прислужники, возможно, сочтут за лучшее убраться подальше отсюда.', 'Убейте 4 бесов-поджигателей, 6 инферналов-завоевателей и 1 вестника ужаса по приказу сержанта Альтумы из восточного каравана, который находится на востоке от Оплота Чести на полуострове Адского Пламени.', 'Славная работа, солдат! Могу сказать наверняка, что частота атак сократится, – по крайней мере до тех пор, пока они не призовут новых повелителей Ужаса.$B$BА теперь плохие новости: у меня есть для тебя новое задание.', 'Оплот Чести в безопасности, пока наше небо охраняют лучники.', NULL, NULL, 'Вестник Ужаса убито', 'Бес-поджигатель убито', 'Инфернал-завоеватель убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10143, 'Лагерь экспедиции', 'Верховное командование заметило твою доблесть в бою, $C. Тебя хотят отправить на передовую для встречи с командой Рохамуса. Они радикалы, твердо намеренные извести под корень Пылающий Легион, так что ты подойдешь...$B$BИди на восток 400 шагов, потом повернешь на юг у возвышенности. Увидишь разрушенного сквернобота на том месте, где прежде стояла старая ферма. Как окажешься там, доложись командиру передовой Кингстону.$B$BШагом марш!', 'Доложитесь командиру передовой Кингстону в лагере экспедиции.', 'Рад тебя видеть, солдат!$B$BОднако хватит болтовни, слушай меня внимательно – для тебя есть важное задание, и я хочу, чтобы ты не только его успешно выполнил, но еще и вернулся живым!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10144, 'Лишить Легион подкрепления!', 'На северо-восток отсюда тянется передовая Легиона. По всей ее длине расположены порталы и ворота, по которым к Легиону поступает подкрепление со всего Запределья. Мы должны разрушить эти порталы!$B$BВот, возьми запал. Его разработали в Зоне 52, взрывчатым веществом для него служит собственная энергия демонов. Нужно отбросить войска Легиона от порталов Грим и Каалез, собрать камни с рунами демонов, забросить в портал запалы... и наслаждаться фейерверком.$B$BСтупай, $N, вернешься ко мне, когда выполнишь задание.', 'Уничтожьте врага вокруг порталов Грим и Каалез и соберите камни с рунами демонов.Забросьте запалы Кингстона в порталы Грим и Каалез.После выполнения задания возвращайтесь к командиру передовой Кингстону вместе с оставшейся взрывчаткой.', 'Отлично, $N. Без порталов к Легиону не скоро придет подкрепление.$B$BНо мы не можем позволить себе отдыхать...', 'Хотел бы я на это посмотреть. Эти запалы взрываются будь здоров!', NULL, NULL, 'Выведите из строя портал Грим', 'Выведите из строя портал Каалез', 'Запалы Кингстона (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10145, 'Mission: Sever the Tie UNUSED', 'Не приказать тебе уничтожить демонов с передовой Легиона, который находится к востоку от нашей базы, было бы нарушением воинского долга.$B$BОбе линии передовой организованы по одному и тому же принципу: между лагерями патрулируют укротители Скверны, которых, в свою очередь, охраняют стражи гнева. За обеспечение всей операции отвечает шиван-поработитель. Убей всех, кто тебе попадется, пусть Каззак сам разбирается, кого поутру недостанет в его войске.$B$BЕдинственно что, – остерегайся скверноботов. Я знаю, ты не $gслабак:слабачка:, но эта штука заставит попотеть даже тебя.', 'Уничтожьте 4 укротителя Скверны, 8 гневостражей и Поработителя Ялквиза по приказу командира передовой Кингстона из лагеря экспедиции на Полуострове Адского Пламени.', '', NULL, NULL, NULL, 'Поработитель Ялквиз убито', 'Укротитель Скверны убито', 'Страж гнева убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10146, 'Задание: Врата Муркет и Шаадраз', 'К западу от Темного портала находится еще два больших портала: портал Муркет и портал Шаадраз.$B$BЕсли взглянуть на восток, то увидишь их с обеих сторон Пути Славы. Я хочу, чтобы ты $gразбомбил:разбомбила: их до самого основания.$B$BВозьми эти бомбы, гоблины из Зоны 52 разработали их специально для подобных целей. И отправляйся к командиру звена Даби\'ри – он даст тебе грифона и подготовит тебя к вылету.', 'Поговорите с командиром звена Даби\'ри, разбомбите Врата Муркет и Врата Шаадраз, затем возвращайтесь к командиру передовой Кингстону в Лагерь экспедиции.', 'Даже дураку ясно, что теперь их продвижение существенно замедлится. Давненько я не был в таком прекрасном настроении, $N!', 'Это очень важное задание, $N. Я бы не всякому его доверил.', NULL, NULL, 'Врата Муркет уничтожены', 'Врата Шаадраз уничтожены', 'Сефориевый модулятор Пустоты PU-36 (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10147, 'Задание: убить гонца', 'Ты уже изрядно $gнавредил:навредила: Легиону, $N. Разведчики доносят, что теперь они отправляют важные бумаги только с курьером. Нам удалось лишить их войска связи с центром!$B$BЯ дам тебе задание, которое не по силам обычному солдату.$B$BКурьер Легиона направится по маршруту от прудов Аггонара до Кузнечной базы: Магеддон, к северу отсюда. Ты $gдолжен:должна: будешь выследить и перехватить его, а послание Легиона доставить мне.', 'Отыщите Арикс\'малидаша, убейте его и заберите Послание Легиона по приказу командира передовой Кингстона из лагеря экспедиции на Полуострове Адского Пламени.', '', NULL, NULL, NULL, 'Послание Легиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10148, 'Задание: доставить послание', 'Я всего лишь боевой командир, $C. Когда речь идет о подобных сведениях, принимать решение может только командир армии Данат Троллебой. Ты $gдолжен:должна: доставить ему донесение в Оплот Чести. Попутного ветра тебе, солдат. Желаю добраться в целости и сохранности.', 'Доставьте Послание Легиона командиру армии Данату Троллебою в Оплот Чести на Полуострове Адского Пламени.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10149, 'Задание: со щитом или на щите', 'Знаешь, что будет, если тебе не удастся перехватить это донесение, $N?$B$B*Данат качает головой.*$B$BВ наши ворота постучится вся армия Легиона. И против них у нас не будет ни единого шанса.$B$BСуществует только один способ сделать так, чтобы это письмо не добралось до Передовой Легиона. Тебе придется отправиться к Прудам Аггонара, которые находятся на северо-западе отсюда, и убить Араззиуса.$B$BЕсли это удастся, я собственноручно вынесу тебе благодарность.', 'Убейте Араззиуса Безжалостного по приказу командира армии Даната Троллебоя из Оплота Чести на Полуострове Адского Пламени.', '', NULL, NULL, NULL, 'Араззиус Безжалостный убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10150, 'Вблизи цитадели', 'День за днем цитадель Адского Пламени открывает свои врата, из нее выплескивается новая волна орков Скверны и растекается по лагерям, разбитым вдоль крепостного вала к югу.$B$BЯ отправил одну из своих самых способных разведчиц, Маху, следить за численностью орков, их передвижениями и подготовкой, но от нее до сих пор нет ответа.$B$BМаха должна была наблюдать за самым ближним лагерем у северного бастиона, там, где он соединяется с цитаделью. Найди ее, $N. Без информации мы станем легкой добычей.', 'Постарайтесь найти следы разведчицы Махи в одном из лагерей, расположенных вдоль Северного бастиона.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10151, 'Приказы боевого командира Некрогга', 'В приказе, подписанном боевым командиром Некроггом, значится, что патруль орков Скверны должен доставить пленников из этого лагеря куда-то на юг, для дальнейшего дознания.$B$BЛовец духов Туджин просил передать, что весь Северный бастион испещрен лагерями орков Скверны. Возможно, разведчицу Маху переведут именно туда.$B$BПо какой-то причине ее приказано оставить в живых. Попытайся спасти Маху, пока они не изменили свое решение.', 'Отправляйтесь к югу вдоль западной стороны Северного бастиона и постарайтесь найти следы разведчицы Махи в одном из лагерей.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10152, 'Западный фланг', 'Орки Скверны получили новый приказ – готовить войска и боевую технику к наступлению.$B$BОплот Чести планируется взять в клещи, и армия боевого командира Некрогга должна сформировать западный фланг.$B$BЕсли Оплот атакуют с запада, когда гарнизон будет занят обороной восточных стен, то вряд ли мы сумеем отбиться. Единственная наша надежда – вывести из строя западный фланг еще до начала сражения.', 'Убейте 10 стражников, 10 берсерков и 5 послушников из клана Изувеченной Длани. О выполнении задания доложите каменному стражу Амбелану, который находится на заставе Раздробленного Хребта, рядом с Зет\'Гором.', '', NULL, NULL, NULL, 'Стражник из клана Изувеченной Длани убито', 'Берсерк из клана Изувеченной Длани убито', 'Послушник из клана Изувеченной Длани убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10153, 'Спасти разведчицу Маху', 'От того места, где была обнаружена экипировка Махи, следы ведут куда-то к югу, через Путь Славы. Многочисленные знаки говорят о том, что похитители очень торопились. Не понятно только, почему. $B$BМожет быть, Маху желает допросить сам боевой командир Некрогг? Именно его имя стояло в том приказе, который тебе удалось добыть.$B$BБрошенный щит и оставленные следы скорее загадывают загадки, чем их разрешают, но мне кажется, что где боевой командир Некрогг, там и Маха.', 'Следуйте дальше к югу вдоль Южного бастиона и постарайтесь найти, где боевой командир Некрогг держит в плену разведчицу Маху.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10154, 'План побега', 'Как я уже говорила, выбраться отсюда будет непросто. Боевой командир Некрогг выглядит как тупой бугай, но он отнюдь не дурак.$B$BОн внимательно следит за ключом и не вылезет из своей башни, вон там, наверху, пока все не будет готово для допроса. Допрашивать станут меня или вон того человека, которого тоже поймали.$B$BДолжно случиться что-то из ряда вон выходящее, чтобы он спустился, но у меня есть идея. Найди кого-нибудь из гренадеров, которые патрулируют Южный бастион, и принеси мне его взрывчатку.', 'Убейте гренадера клана Изувеченной Длани и принесите примитивную взрывчатку разведчице Махе в форт Гор\'газ.', '', NULL, NULL, NULL, 'Примитивная взрывчатка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10155, 'Провокация', 'Сработает план или провалится, зависит только от взрывчатки.$B$BНенавижу полагаться на что-то, сделанное орками, но это наш единственный шанс выбраться отсюда. Возьми взрывчатку и швырни об флаг, вывешенный на башне.$B$BОн должен взорваться с большим грохотом, и Нейкрогг не устоит перед желанием выйти наружу, поймать нарушителя и сделать из него котлету. Убей его, возьми ключ и открой мою клетку. Удачи тебе, $N.', 'Используйте примитивную взрывчатку, чтобы создать шум и выманить боевого командира Некрогга из его башни. Убейте его, заберите Ключ Некрогга и откройте клетку разведчицы Махи. Об освобождении разведчицы Махи доложите каменному стражу Амбелану на Заставу Разрушенного Хребта рядом с Зет\'Гором.', '', NULL, NULL, NULL, 'Спасите разведчица Маху', 'Ключ Некрогга', 'Примитивная взрывчатка', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10156, 'Кто отдает приказы?', 'Ясно только одно, $N: долго мы здесь не продержимся. Мы окружены, и на место одного убитого орка Скверны тотчас заступают трое новых. Мы не выиграем эту войну, если наши силы будут сражаться на два фронта одновременно – против орков Скверны и демонов Легиона. $B$BТы уже $gсовершил:совершила: подвиг, сорвав основную атаку орков Скверны, но сейчас тебе придется пробиться через Путь Славы и узнать, кто ими управляет.', 'Убейте 20 рубак и 10 чернокнижников клана Изувеченной Длани и захватите распоряжения военного инструктора Зурока. После этого возвращайтесь к каменному стражу Амбелану на Заставу Хребтолома.', '', NULL, NULL, NULL, 'Рубака клана Изувеченной Длани убито', 'Чернокнижник клана Изувеченной Длани убито', 'Распоряжения военного инструктора Зурока', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10157, 'Разжаловать командира', 'Насколько мне известно, военный инструктор Зурок – правая рука предводителя орков Скверны, командира соединения Горакса.$B$BЭтот Горакс, – не то, что обычные оркские бугаи. Он так ловко и изощренно вынуждает нас постоянно обороняться, что восхищает даже меня.$B$BВ распоряжениях Зурока упоминалось, что командный центр Горакса расположен в конце Пути Славы, там, где Цитадель сходится с Северным бастионом. Думаю, можно не говорить, что от тебя ожидается, $N, но лучше не отправляться туда в одиночку.', 'Уничтожьте командира соединения Горакса и доложите о выполнении задания темному охотнику Ти\'джину из Траллмара.', '', NULL, NULL, NULL, 'Командир соединения Горакс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10158, 'Припасы Кровавой Глазницы', 'Ну руинах старого оркского поселения Зет\'Гор обосновались орки из Цитадели Адского Пламени. Они устроили там свою военную базу, и их число постоянно растет.$B$BЛовец духов Туджин послал меня наблюдать за ними.$B$BЭти орки вообще ни на что не похожи, нельзя, чтобы они сумели накопить силы. Ступай в Зет\'Гор и уничтожь все их припасы.', 'Уничтожьте 6 складов припасов клана Кровавой Глазницы и доложите о выполнении задания каменному стражу Амбелану с Заставы Хребтолома.', '', NULL, NULL, NULL, 'Припасы клана Кровавой Глазницы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10159, 'Очистить холм Колючего Клыка!', 'Мы ведем бесконечную войну с опустошителями, пытаясь сохранить свободным путь на запад через холм Колючего Клыка. Недопустимо, чтобы мы оказались полностью отрезанными от убежища в Зангартопи.$B$BМы бы не стали трогать этих тварей, но они все чаще нападают на путешественников.$B$BПожалуйста, помоги нам очистить эту местность от опустошителей.', 'Убейте 8 опустошителей Колючего Клыка и 8 ядоплюев Колючего Клыка. После выполнения задания возвращайтесь к Махураму Крепкому Копыту на Кенарийскую заставу на полуострове Адского Пламени.', 'Теперь, когда опустошителей не стало, добираться до Кенарийского приюта в Зангартопи стало куда безопасней.$B$BКенарийская экспедиция в долгу перед тобой.', 'Как продвигается зачистка холма Колючего Клыка?', NULL, NULL, 'Опустошитель Колючего Клыка убито', 'Ядоплюй Колючего Клыка убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10160, 'Врага нужно знать в лицо', 'Ходят слухи, что появилась какая-то новая порода орков. Более мозговитая, чем те бугаи, с которыми нам приходилось драться. Если эти слухи подтвердятся, то нашим войскам, у которых силы и так на исходе, придется несладко.$B$BЯ поручил расследование лейтенанту Амади. Если хочешь в эти непростые времена оказать нам помощь, разыщи ее. Она находится в разрушенной башне в западной части Оплота Чести.$B$BИ еще, $N, будь $gосторожен:осторожна:. Ты вступаешь в неведомый и очень опасный мир.', 'Поговорите с лейтенантом Амади в старой сторожевой башне на западе Оплота Чести.', '<Лейтенант Амади кивает.>$B$BОтлично, мы рады любой помощи. Меня беспокоит увеличение численности орков Скверны в Южном бастионе. Я отправила туда разведчика, но он до сих пор не вернулся.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10161, 'В случае чрезвычайной ситуации...', 'В случае чрезвычайной ситуации основная ответственность ложится на пилота, особенно если второй пилот способен думать только о том, чем бы набить брюхо.$B$BУ меня есть две новости: хорошая и плохая. Хорошая новость – мы сможем обойтись с ремонтом своими силами. Плохая – части нашего дирижабля разбросаны отсюда и к востоку аж до самой Долины Костей.$B$BЧто еще плохого? Можно сказать, что собственно запчастей у нас нет. А что было, то попадало вниз во время нашего... хм... экстренного снижения. Поможешь нам отыскать запчасти, чтобы мы снова смогли подняться в воздух?', 'Соберите 30 обломков дирижабля и принесите Скриду Многослову по прозвищу \"Крикун\" на место крушения дирижабля.', 'Часть из них в ужасном состоянии, но с остальными можно работать. Немного фантазии, и я уверен, эта штука еще поднимется в воздух!', 'Удалось собрать хоть что-нибудь? Если нет, то придется конфисковать у Легасси сковородку, которой он так яро размахивает. М-да, тогда мой дирижабль можно будет смело называть летающей сковородкой...', NULL, NULL, 'Обломки дирижабля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10162, 'Задание: Косогор Бездны', 'Может быть теперь, когда у тебя есть крылья, ты захочешь снова отправиться на бомбардировку?$B$BМы обнаружили главный производственный цех Легиона, в котором куются силы для северных лагерей. Приказываю тебе взять виверну и уничтожить этот оплот Скверны!$B$BБомбы лежат вот здесь. Поговори с командиром звена Бракком, когда будешь $gготов:готова: к вылету.', 'Уничтожьте 20 ган\'аргов-батраков, 5 мо\'аргов-надзирателей и 5 пушек Скверны по приказу командира передовой То\'арха у останков Сквернобота на полуострове Адского Пламени.', 'Ты летаешь так, будто занимался этим всю жизнь, $N. Я восхищаюсь твоим умением! На вивернах ни царапины!', 'Пусть узнают, что небеса им тоже не рады!', NULL, NULL, 'Ган\'арг-батрак убито', 'Мо\'арг-надзиратель убито', 'Уничтожено пушек скверны', 'Сюрприз из Зоны 52 (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10163, 'Задание: Косогор Бездны', 'Может быть теперь, когда у тебя появились крылья, ты хочешь снова отправиться на бомбардировку?$B$BМы обнаружили главный производственный цех Легиона, в котором куются силы для северных лагерей. Приказываю тебе взять грифона и уничтожить этот оплот Скверны!$B$BБомбы лежат вот здесь. Поговори с грифоньером Ветроревом, когда будешь $gготов:готова: к вылету.', 'Уничтожьте 20 ган\'аргов-батраков, 5 мо\'аргов-надзирателей и 5 пушек Скверны по приказу командира звена Грифонгара с Парящей заставы на полуострове Адского Пламени.', 'Ты летаешь так, будто занимался этим всю жизнь, $N. Я восхищаюсь твоим умением! Ни царапины ни на одном грифоне!', 'Пусть узнают, что небеса им тоже не рады!', NULL, NULL, 'Ган\'арг-батрак убито', 'Мо\'арг-надзиратель убито', 'Уничтожено пушек скверны', 'Сюрприз из Зоны 52 (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10164, 'Все будет в порядке', 'Чувствую, тебе хватило приключений еще до того, как ты $gвступил:вступила: в Аукенайские гробницы, $N.$B$BЯ могу назвать себя счастливым духом, - я никогда не попадался ни Левиксусу, ни экзарху Маладаару, и на мне не ставили эти ужасные некромантические эксперименты. Левиксиуса тебе удалось уничтожить, но Маладаар жив и продолжает терзать пленных духов.$B$BЯ прошу только об одном. Проберись в Аукенайские гробницы и уничтожь экзарха Маладаара, чтобы духи могли наконец упокоиться с миром.', 'Проникните в Аукенайские гробницы и уничтожьте экзарха Маладаара по просьбе Великого Отца Алдримуса, который находится снаружи Аукенайских гробниц Аукиндона.', 'У тебя получилось, $N! Духи наконец обрели свободу!$B$BУ меня нет материального тела, но я дам тебе в награду предмет из мира духов. Используй его с осторожностью, подобные предметы очень непостоянны и могут причинить вред обладателю.', 'Освободи духов, $N!', NULL, NULL, 'Экзарх Маладаар убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10165, 'Жестокая вещь – конкуренция', 'А этот Шаффар не дурак, как я погляжу. Ухитрился выставить отсюда весь Консорциум и теперь спокойненько обчищает гробницу! Я не верю, что мои идиоты смогут прорвать оборону Шаффара, так что предлагаю тебе сделку, $r.$B$BОтправляйся в Гробницы Маны и убей Шаффара. Принеси его одеяние в знак доказательства его смерти, и я щедро награжу тебя.', 'Убейте принца нексуса Шаффара по просьбе принца нексуса Харамада, находящегося снаружи Гробниц маны, и принесите ему обмотки Шаффара.', 'Минус еще один конкурент... Для маленького кусочка плоти ты неплохо справился, $R. Если окажешься еще раз в Пустоверти, дай мне знать. Меня можно найти в Штормовой Вершине.', 'Я очень не люблю делиться!', NULL, NULL, 'Обмотки Шаффара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10166, 'Память о Белостволе', 'Эта подвеска напоминает мне иные времена. Лучшие времена...$B$BУвы, сейчас мне не до воспоминаний!$B$BПрошу тебя, зарой ее возле рунического камня в Выжженной роще. Именно там я впервые встретилась со старейшиной-древнем. Пусть воспоминания о моем старом друге покоятся в мире.', 'Заройте подвеску Старого Белоствола у рунического камня в Выжженной роще по просьбе Ларианны Речной Ветер.', 'Я более не принадлежу к этому миру и вынужден признать свое поражение. Мир изменился навеки, ничто уже не будет прежним.$B$BОставь подвеску здесь, со мной, $N. Может быть, в один прекрасный день, когда эльфы исчезнут, на этом самом месте прорастет новое дерево - среди сгоревшего леса и остовов мертвых древней.', 'Ты вернулся, $N! Сделал ли ты то, о чем я просила?', NULL, NULL, 'Подвеска Старого Белоствола (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10167, 'Аукиндон...', 'В глубине Аукенайских гробниц находится могила, не похожая ни на какую другую могилу в этой разоренной стране. С этой первой гробницы началась история огромного мавзолея Аукиндона.$B$BТебе надо проникнуть в Аукенайские гробницы и разыскать эту могилу. Убей хранителя склепа и освободи заточенного внутри духа. Он – ключ к разгадке...', 'Отправляйтесь в Аукенайские гробницы в Костяных пустошах леса Тероккар, убейте экзарха Маладаара и освободите дух Д\'оре.', 'Мои воспоминания не поблекли с годами, $N. Катастрофа полностью отняла мои силы. Когда Пророк Велен и его земляки-дренеи принесли сюда мои останки, в них теплилась лишь тусклая искорка энергии. После долгой церемонии мое истощенное воплощение упокоилось в этом саркофаге. Почти тысячу лет я потратил на восстановление. Цикл почти завершен...', NULL, NULL, NULL, 'Экзарх Маладаар убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10168, 'Что видит душа', 'Многие века духи Аукиндона сливались с моей обессиленной душой. Большая часть несчастий, обрушившихся на эти гробницы, произошла из-за того, что я был ослаблен и немощен.$B$BК сожалению, остановить этот цикл невозможно. Это закон существования наару: без пустоты не бывает Света.$B$BТвой единственный выход – уничтожить древних духов Награнда прежде, чем они превратятся в созданий Бездны. Используй зеркала Души, которые найдешь в гробницах, чтобы освободить их...', 'Найдите зеркало Души в Аукенайских гробницах и используйте его, чтобы выманить темного духа из древнего орка-предка в Награнде. Уничтожьте 15 темных духов, чтобы орочьи предки могли упокоиться с миром.Когда исполните поручение, возвращайтесь к Матери Кашур в Земли Предков.', 'Ты завершил долгое и опасное путешествие, рисковал своей жизнью ради безопасности маг\'харов и покоя наших предков. Мою благодарность невозможно выразить словами.', '<Мать Кашур заметно расcтроена.>$B$BЭти наару умнее всех существ в мире.', NULL, NULL, 'Темный дух убито', 'Зеркало души', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10169, 'Проиграть с честью', 'Сегодня Алдоры заслужили благорасположение Ша\'тар! Тоже мне, неожиданность!$B$BТолько посмотрите, как они выставляются перед А\'далом - а все для того, чтобы подлизаться к наару.$B$BУ снайперов Харонема такая строгая дисциплина, что они даже притащили свой котел, чтобы не делать долгих перерывов на обед. Думаю, надо их угостить как следует, $N.$B$BВот, вылейте это в их еду. Результат себя ждать не заставит... будет весело.', 'Вылейте сонную сыворотку в котел Харонема на террасе Света, после чего вернитесь к магистру Фальрису.', '', NULL, NULL, NULL, 'Фиал с сонной сывороткой (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10170, 'Возвращение к Великой Матери', '$N, возвращайся в Гарадар к великой матери Гейе и сообщи ей о своей победе. Это поднимет дух маг\'харов. Может быть, даже юный Адский Крик оправится от болезни.', 'Возвращайтесь в Гарадар и поговорите с великой матерью Гейей. ', 'Я хочу, чтобы ты лично доставил эти известия Гаррошу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10171, 'Безутешный Вождь', '$N, ты так много $gсделал:сделала: для маг\'харов, что весть о твоих деяниях достигла до ушей самого Гарроша. Иди к нему и расскажи о своей последней победе. Скажи, что ты делаешь все это для него и его народа. Ему понравятся такие слова. Может, он даже слегка взбодрится.', 'Поговорите с Гаррошем.', 'Все гордятся и радуются. Радуются, что увидят еще одну зиму. А дальше? Что будет дальше?$B$BМожет быть, тебе стоит возглавить мой клан, $N? И тогда, после ухода Великой матери, мне, может быть, будет позволено умереть и вернуть честное имя моему роду. Я жажду покоя...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10172, 'Надежды нет', 'Ты $gблагородный:благородная:$r, $N. Ты много $gсделал:сделала: для маг\'харов и $gоказал:оказала: нам поистине неоценимые услуги. Увы, время маг\'харов закончилось. Ты ясно мне $gпоказал:показала:, что я не гожусь на роль вождя своего народа. Моя проклятая кровь... Я не хочу стать вторым Адским Криком, который навлечет беду на орков.$B$BПрошу тебя, $N, возвращайся к Великой Матери и передай ей мои слова. Мне стыдно предстать перед ней самому... стыдно смотреть ей в глаза.', 'Вернитесь к Великой Матери Гейе и передайте ей слова Гарроша. ', '*Слезы текут по щекам Великой Матери.*$B$BИди к своему вождю и скажи ему, что я жду его здесь...', NULL, NULL, NULL, 'Поговорите с Великой Матерью Гейей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10173, 'Посох верховного мага', 'Позволь мне представиться, $C.$B$BЯ Равандвир, ученик верховного мага Варгота.$B$BМой учитель... скажем так, нездоров. Я здесь по чрезвычайно важному делу. $B$BВ руинах Арклона к юго-востоку от города активно действует Пылающий Легион. Цель пребывания этих демонов в руинах не касается ни меня, ни моего учителя, однако их предводительница, Эккораш, завладела посохом верховного мага.$B$BВот волшебный порошок, он позволит тебе выманить демоницу из укрытия. Брось порошок на жаровню в центре руин.', 'Отнимите посох верховного мага Варгота у Эккораш Инквизитора и принесите Равандвиру в Зону 52. Чтобы выманить Эккораш из укрытия, бросьте волшебный порошок на жаровню в центре руин.', 'А, так тебе удалось добыть посох. Великолепно, $N. Возможно, именно тебя я и искал все это время.$B$BАх да, твоя награда...$B$B*Равандвир кладет тебе на ладонь несколько монет.*$B$BНесомненно, это не оправдывает твои ожидания, но всему свое время. Отныне ищи возможность для получения истинной награды.', 'Я не буду знать покоя, пока посох верховного мага Варгота не вернется к нему. Удалось ли тебе вырвать посох из лап демона?', NULL, NULL, 'Посох верховного мага Варгота', 'Волшебный порошок (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10174, 'Проклятие Аметистовой башни', 'Теперь ты можешь использовать посох верховного мага, чтобы связаться с ним.$B$BОн обитает в Аметистовой башне, на \"острове\" к юго-востоку отсюда. Эта башня служит ему одновременно убежищем и тюрьмой – она проклята. Никто из Кирин-Тора не может ни войти туда, ни выйти оттуда, и я разлучен со своим учителем.$B$BМагия посоха может пробиться через защиту башни, но ее должен пробудить кто-то, не принадлежащий к Кирин-Тору. $B$BВозьми посох верховного мага и используй, чтобы вызвать его проекцию. Расскажи ему о том, что произошло, и скажи, что я все-таки не окончательно подвел его.', 'Используйте посох верховного мага Варгота, чтобы связаться с верховным магом Варготом.Если вы утратили посох верховного мага Варгота, поговорите с Равандвиром в Зоне 52, чтобы получить замену.', '*Изображение верховного мага Варгота изучает тебя, пока ты пересказываешь сообщение Равандвира.*$B$BРавандвир наделен всем, что любой учиитель хотел бы видеть в своем ученике. Когда я отдал ему этот посох и приказал бежать, я надеялся, что он использует этот посох, дабы найти помощь и освободить меня, как только войска Кель\'таса отступят от башни. С тех пор я многое узнал о природе проклятья.$B$BПроклятье можно разбить, $N, но для этого потребуется твоя помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10175, 'Тралл, сын Дуротана', 'Возвращайся в свой мир, $N. Разыщи моего внука и скажи ему, что у него еще остались близкие в этом разрушенном мире.$B$BСкажи ему, что наследие его отца продолжает жить.$B$BРасскажи ему все...', 'Отправляйтесь в Оргриммар и передайте Траллу сообщение от Гейи. ', '*Голос Тралла становится глухим и гулким, как далекий раскат грома.*$B$BУ меня... у меня есть бабушка? Она жива?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10176, 'Страж Ар\'келос', 'Теперь, когда тебе удалось собрать все предметы, необходимые для того, чтобы снять проклятие Кель\'таса, осталось сделать еще только одно. Когда Кель\'тас запечатал башню, он поставил у ее подножия чародейского голема, известного как Ар\'келос.$B$BТебе нужно победить голема, чтобы я вновь смог работать с магией внутри башни.$B$BКогда ты войдешь в Аметистовую башню, проклятье начнет действовать на тебя.$B$BКак только победишь Ар\'келоса, поднимайся на башню и помоги мне провести приготовления к ритуалу.', 'Войдите в Аметистовую башню, расположенную в центре деревни Кирин\'Вар, и победите Ар\'келоса, затем поговорите с верховным магом Варготом.', 'Хорошая работа, $N. Благодаря уничтожению подавляющего поля мне будет гораздо легче подготовить магию, которая наконец-то снимет проклятье с башни.', 'Наконец-то мы встретились.', NULL, NULL, 'Ар\'келос убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10177, 'В Аукиндоне неспокойно', 'Мои шпионы шлют очень тревожные донесения из Аукиндона. Со времени взрыва это место не доставляло нам ничего, кроме проблем.$B$BИ опять там происходит что-то ужасное. Похоже, Совет Теней вознамерился развязать войну. Хотя донесения недостаточно подробные, понятно, что приготовления идут вовсю.$B$BТебе придется пробраться в Темный Лабиринт. Боевой командир Мафуун скажет тебе, что делать.', 'Доложите о своем прибытии боевому командиру Мафууну, который находится неподалеку от входа в Темный лабиринт в Аукиндоне в Лесу Тероккар.', 'Ты появился очень вовремя.$B$BМы уже довольно долго здесь сражаемся, и еще несколько дней назад Мелиса обещала прислать подкрепление.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10178, 'Найти шпиона То\'гуна!', 'То\'гун – идиот! Мы и здесь-то держались с трудом, а он отправился на разведку, и вдобавок решил спасти всех остальных шпионов.$B$BДаже не знаю, молиться за него или прибить, когда вернется.$B$BСовет Теней, должно быть, использовал магию, чтобы нас обнаружить, и нам пришлось бежать отсюда в ужасной спешке. Многие не сумели выбраться.$B$BПожалуйста, если у тебя хватит храбрости, чтобы войти в Темный лабиринт, глянь хотя бы одним глазком, не найдешь ли ты То\'гуна! Прошло уже столько времени, и я опасаюсь худшего...', 'Найдите шпиона То\'гуна в Темном лабиринте в Аукиндоне.', 'Что? Грук-та отправила тебя сюда за мной?$B$BНет, это, конечно, трогательно, но она с ума сошла!$B$BПоможешь мне выбраться из этой клетки? А то тут тесновато!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10179, 'Смотритель Кирин\'Вара', 'Когда стало ясно, что наша экспедиция попала в ловушку в Запределье и не может вернуться обратно на Азерот, отряд Кирин-Тора отправился на равнины Фаралона и построил деревню Кирин\'Вар. Я оставил дела в руках смотрителя Дайворта, но когда Кель\'тас и его войска заключили меня в Аметистовой башне, я потерял с ним связь связь.$B$BОтыщи его в деревне Кирин\'Вар и помоги ему во всем, в чем только сможешь, $N. Я уверен, что у него полно хлопот с преодолением последствий нападения.', 'Поговорите с блюстителем Ценой Смерти в деревне Кирин\'Вар в Пустоверти.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10180, 'Неудержимый', 'Я пытался убедить Исфара, что нам лучше оставаться в безопасности в Шаттрате, но он не стал даже слушать. Наоборот, он решил, что отправится в Аукиндон в одиночку.$B$BОднажды ему посчастливилось выбраться из Сетеккских залов, но если его обнаружат, второго шанса у него не будет.$B$BЯ понимаю, что он хочет спасти сестру, но без посторонней помощи ему не справиться.$B$BНайди Исфара и поговори с ним, $N. Если ты не сможешь убедить его вернуться обратно, может быть, тебе удасться помочь ему спасти Лакку?', 'Поговорите с Исфаром, которого можно найти неподалеку от входа в Сетеккские залы в Аукиндоне.', 'Я должен был догадаться, что это он отправил тебя за мной. Он пытался отговорить меня от возвращения в Сетеккские залы, но разве я смогу жить спокойно, если позволю Лакке погибнуть там?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10182, 'Боевой маг Датрик', 'Этот меч великолепен даже для боевого мага: он искусно откован и идеально сбалансирован. На оголовье меча выгравированы печать Кирин-Тора и имя \"Датрик\".$B$BВертя оружие в руках, ты замечаешь, что от металла исходит ощущение некой неправильности, как будто предмет разрывается между двумя мирами. Быть может, это предмет, привязывающий дух боевого мага Датрика к этому миру?$B$BВозможно, возвращение меча на должное место разорвет эту связь и освободит дух Датрика, чтобы он наконец-то мог покоиться в мире?', 'Найдите апартаменты боевого мага Датрика в переулке Волшебников и верните меч в оружейную стойку. Затем поговорите со смотрителем Дайвортом в деревне Кирин\'Вар.', 'Это было доброе дело, $N. Я больше не чувствую беспокойства, исходящего от духа Датрика. Я много бы отдал за возможность еще раз поговорить с ним, но достаточно и того, что он наконец-то нашел покой.', 'Что это за находка, $N?', NULL, NULL, 'Упокойте дух Датрика', 'Клинок Датрика', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10183, 'В Зону 52', 'Я тут изучаю Пустоту – астральные течения и все такое. Это идеальное место, вдали от городских огней и шума. Разве этот мост не великолепен? Если бы мне еще удалось заставить этот хлам работать!$B$BКстати, если ты ищешь работу, то в Зоне 52 ее полно. Иди вот по этой тропе, а на развилке сверни направо.$B$BЗаодно почему бы тебе не передать мои последние исследовательские записи ведущему ракетостроителю Фьюзеляжу? Я уверен, что у него для тебя найдется масса дел, с этим его ракетным кораблем Х-52 и всем прочим.', 'Передайте записки пустолога ведущему ракетостроителю Фьюзеляжу, находящемуся в Зоне 52 в Пустоверти.', 'А, Медноклеппер наконец-то решил сообщить о своих открытиях? Эти мне ленивые ученые!$B$BВ чем дело?$B$B<Ведущий ракетостроитель несколько раз пролистывает записки с явно недоверчивым видом.>$B$BОн утверждает, что неистовая энергия, плавающая в Пустоверти, всего через несколько месяцев разнесет тут все на мелкие кусочки.$B$BЭто ужасно – нам теперь придется сдвигать график постройки ракетного корабля!', 'Занят, занят. Нет времени. Нужно построить ракетный корабль!$B$BЧто тебе нужно?', NULL, NULL, 'Записки Пустолога (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10184, 'Зловещие останки', 'Большинство духов в деревне – не более, чем бледные останки магов Кирин-Тора. Они ничего не знают о своих былых \"я\" и просто блуждают среди руин в слепой ярости.$B$BОднако так было не всегда. Сразу после нападения духи были беспокойными, но не злобными. Но с течением времени они становились все более агрессивными. Я не осмеливаюсь заходить в южную часть деревни, ибо они не пощадят даже меня. Заставь их умолкнуть, и будем надеяться, что это уймет их ярость.', 'Смотритель Дайворт в деревне Кирин\'Вар просит вас победить 20 покалеченных духов на площади Кирин\'Вара.', '<Смотритель Дайворт тихонько покачивает головой.>$B$BЭто не то, чего они заслуживали, но это лучшее, что мы могли сделать.', NULL, NULL, NULL, 'Покалеченный дух убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10185, 'Участь хуже, чем смерть', 'После того как эльфы крови уничтожили деревню Кирин\'Вар, они начали строительство огромного здания к северо-западу отсюда. Без знаний верховного мага мы не можем точно сказать, что там происходит.$B$BОднако ясно одно. Деятельность эльфов крови вызвало массовые нападения на деревню элементалей маны. Они, судя по всему, рыщут среди руин в переулке Волшебников, производя дальнейшее опустошение. Мы не можем допустить, чтобы это продолжалось.', 'Убейте 10 убийц магов и 10 искателей маны и вернитесь к смотрителю Дайворту в деревню Кирин\'Вар.', '<Блюститель выглядит встревоженным.>$B$BЯ уже вижу новую волну, вздымающуюся на горизонте. Истребление этих тварей поможет лишь на некоторое время, однако нужны более действенные меры.', NULL, NULL, NULL, 'Искатель маны убито', 'Убийца магов убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10186, 'Тебя наняли!', 'Позволь мне первым поприветствовать тебя, младший лаборант 3-й степени $N!$B$BМы здесь строим мое изобретение - ракету Х-52!$B$BНо для начала нам нужно раздобыть все детали и топливо для нее. Именно этим ты и займешься.$B$BПервым делом мне нужны кристаллы – МНОГО кристаллов – для астраллитиевой матрицы двигателя ракеты. Эти кристаллы выпадали у дренеев из ушей.$B$BТак что отправляйся на север, в руины Энкаата, и добудь для меня кристаллы. На призраки дренеев не обращай внимания.', 'Соберите 10 астраллитиевых матричных кристаллов и принесите их ведущему ракетостроителю Фьюзеляжу в Зону 52 в Пустоверти.', 'Ха! Выглядят достаточно грубо. Может быть, мы сможем их использовать в многоцелевой камере третьей ступени двигателя. $B$BИ все же это хорошая работа, младший лаборант 3-ей степени! Похоже, ты очень скоро заслужишь 2-ю степень!', 'Похоже ли, что ракета Х-52 готова к старту? И что я скоро буду курсировать по Круговерти Пустоты, удобно расположившись в командирском кресле? Буду исследовать новые интересные миры? Искать возможность заполучить новые технологии и наладить деловые связи? Отважно бросаться туда, где не бывал еще ни один гоблин?$B$BНет!$B$BТак где же те кристаллы, за которыми я тебя посылал?', NULL, NULL, 'Эфирлитиевый матричный кристалл', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10187, 'Послание для верховного мага', 'Хотя ситуация здесь довольно мрачная, мы слегка воодушевились, услышав от тебя, что верховный маг не забыл о положении нашей деревни.$B$B<Блюститель бросает взгляд на башню.>$B$BСмешно, не так ли? Иногда кажется, что нас разделяет лишь обычная каменная стена. О стене магии довольно легко забыть.$B$BНе затруднило бы тебя подняться на башню и уведомить верховного мага Варгота о том, что у нас в деревне дела продвинулись довольно далеко и что вскоре мы составим план избавления от мана-тварей.', 'Поговорите с Верховным магом Варготом на вершине Сиреневой башни в Пустоверти.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10188, 'Печать Краса', 'Прежде чем мы много лет назад отбыли с Азерота, Кирин-Тор доверил нашей экспедиции мощный артефакт, Печать Краса. Она очень помогла нам в битве против орков, и может сыграть важную роль в том, чтобы разбить заклинание, удерживающее меня здесь.$B$BОднако когда Кель\'тас отнял у меня мои волшебные принадлежности, он отдал печать чароплету Мариане, которая не принимала участия в битве. Если бы Кель\'тас понимал, чем он завладел, он не отдал бы это так легко.', 'Заберите Печать Краса у чароплета Марианы, находящейся в Манагорне Коруу, к северо-западу от Аметистовой башни.', 'О, эта печать осталась такой же великолепной, какой я ее запомнил. Разве ты не чувствуешь силу, которую она излучает?$B$BКонечно, нужно сделать еще очень многое, но я благодарен тебе за возвращение печати.', 'Чтобы освободиться от проклятия башни, мне необходима эта печать.', NULL, NULL, 'Печать Краса', 'Посох верховного мага Варгота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10189, 'Манагорн Б\'наар', 'Может быть, по пути сюда тебе попался на глаза один из манагорнов Келя. Это такие большие лиловые здания, высасывающие энергию из неба. $B$BМы посланы сюда Ша\'тар, дабы побольше узнать об этих манагорнах. Ты можешь помочь нам в сборе сведений, раздобыв список персонала. Это даст нам представление о том, кто находится там и что они делают; такая информация была бы бесценной.$B$BМы полагаем, что капитан Аратин, командующий отрядом баллист, который расквартирован возле манагорна Б\'наар, располагает экземпляром этого списка. Добудь его для нас.', 'Патрон шпионов Талодиен, находящийся в Зоне 52, хочет, чтобы вы направились в окрестности манагорна Б\'наар и отобрали список персонала манагорна Б\'наар у капитана Аратина.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Превосходно! При наличии этого списка мы сможем принимать более взвешенные решения, намечая целью кого-нибудь из последоватей Келя в манагорнах.$B$BКак ни печально, мне уже начало нравиться убивать всех его приспешников без разбора.', 'Удалось ли тебе раздобыть то, о чем я тебя просил, $N?', NULL, NULL, 'Список персонала Б\'наара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10190, 'Перезарядка батарей', 'У меня очень важная задача – отыскивать и забирать машины, оставшиеся в этих руинах, однако существуют проблемы с тем, чтобы подзаряжать всех моих роботов. $B$BВнепространственные охотники – эти червеподобные твари – содержат массу энергии! Их можно найти по окраинам этого острова, они приплывают из пустоты.$B$BНаполни энергией батареи, вставленные в это зарядное устройство, применив его к внепространственному охотнику, пока он слаб, а затем прикончи его, чтобы выдавить последнюю энергию.', 'Используйте зарядное устройство для батарей применительно к достаточному количеству внепространственных охотников, чтобы довести зарядку батарей до уровня 10. Затем вернитесь к роботехнику Элли в руины Энкаата в Пустоверти.', 'Эй, смотри, куда направляешь эту штуку! Она выставлена на смертельное поражение!!!$B$BПохоже, тебе удалось как следует подзарядить батарейки. Ну что ж, теперь мои ребятки смогут двигаться.', 'Ну как, удалось зарядить батарейки в устройстве?', NULL, NULL, 'Перезарядка батарей', 'Устройство для перезарядки батарей (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10191, 'Робот модели V жив!', 'Привет тебе, $r. Я заряжен и полностью функционален. $B$BВ этих руинах находятся хрупкие дренейские машины, которые я должен забрать. Я оборудован точно настроенными сервоприводами в запястных механизмах и пневматическими компенсаторами сотрясений последней конструкции. Осторожное обращение с деталями – для меня не проблема.$B$BОднако призраки, обитающие в этих руинах, наверняка нападут на меня, поэтому я прошу тебя и твоих друзей обеспечить мне защиту.', 'Сопроводите \"Маккса А. Миллиона V\" через руины Энкаата и обратно, обеспечив ему безопасность. Потом поговорите с роботехником Элли за пределами руин Энкаата в Пустоверти.', 'Получилось! Получилось! Я готова тебя расцеловать!$B$BОй... у \"Маккса А. Миллиона V\" опять кончилась энергия. Ну ладно, он сегодня хорошо поработал, а остальное неважно!$B$BВедущий ракетостроитель Фьюзеляж будет доволен – он сможет подключить эти дренейские машины к своей ракете Пустоты Х-52! А я получу повышение! Я так рада! Сейчас, я чем-нибудь тебя вознагражу.$B$BВот, выбирай из этого.', 'Ты уже вернулся, так быстро? $B$BС \"Макксом А. Миллионом $N\" все в порядке?', NULL, NULL, 'Сопроводите \"Маккса А. Миллиона V\" через руины Энкаата', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10192, 'Компендиум Краса', 'Кирин-Тор послали с нашей экспедицией еще одну вещь, принадлежавшую Красу. Это его книга заклинаний, именуемая компендиум Краса. В ней содержатся все заклинания, которые он освоил, и она могла бы дать нам весомое преимущество в войне. $B$BЕще до того, как Кель\'тас со своим войском осадил Кирин\'Вар, компендиум был похищен у меня мятежным учеником, намеревавшимся заняться некромантией. Этот ученик и его последователи разделили книгу на отдельные части и втайне изучали ее, заперевшись в своих домах в южной части города.', 'Заберите компендиум Краса – глава 1, компендиум Краса – глава 2 и компендиум Краса – глава 3 из района Городской площади деревни Кирин\'Вар.', '*Изображение верховного мага Варгота словно бы изучает Компендиум.*$B$BДа, книга в плохом состоянии, но если учесть, как с ней обращались, чудо еще, что она вообще сохранилась. Сбереги ее, $N. Без нее у нас мало надежды пробиться через стену, ограждающую башню.', 'Ты принес книгу?', NULL, NULL, 'Руководство Краса - Глава 1', 'Руководство Краса - Глава 2', 'Руководство Краса - Глава 3', 'Посох верховного мага Варгота');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10193, 'Высокие цели', 'Основываясь на сведениях из этого списка, мы узнали, что \"мозгами\" во всех действиях, совершаемых в манагорнах, являются мастера искажения и инженеры искажения. Именно они присматривают за притягиванием так называемой \"энергии искажения\" в манагорн, а также передачей этой энергии на расстояние посредством системы подземных трубопроводов.$B$BПомимо них, единственными специалистами в том регионе являются геологи. Все остальные или состоят в армии, или являются приверженцами магистра; и тех, и других легко заменить.$B$BОтправляйся туда и убей специалистов Келя – это причинит ему наибольший вред.', 'Патрон шпионов Талодиен, находящийся в Зоне 52, просит вас отправиться в манагорн Б\'наар и убить 2 мастеров пространственных искривлений, 6 инженеров пространственных искривлений и 8 геологов из клана Ярости Солнца.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Ты надежный парень, $N. Если мне что-то и нравится больше, нежели убийство приспешников Келя, - это когда кто-то убивает их вместо меня. Чем меньше крови на моей одежде, тем лучше.', NULL, NULL, NULL, 'Мастер пространственных искривлений из клана Ярости Солнца убито', 'Инженер пространственных искривлений из клана Ярости Солнца убито', 'Геолог из клана Ярости Солнца убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10194, 'Незаметный полет', 'После твоего ухода мои подчиненные обнаружили еще один манагорн. Он находится к востоку отсюда и известен как манагорн Коруу.$B$BДвое моих лучших шпионов оборудовали тайную площадку для высадки поблизости от этого манагорна. Нужно помочь им внедриться в войско Келя и собрать всю информацию, какую только возможно.$B$BПоговори с Веронией, ожидающей за городскими стенами; она нашла ветрокрыла, который отнесет тебя к манагорну Коруу. Оказавшись там, поговори с Каледисом Сияющим Рассветом, он посвятит тебя в детали задания.', 'Поговорите с Веронией, находящейся за пределами Зоны 52, и летите к манагорну Коруу.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Устроить все для твоего полета стоило немалых денег. Будем надеяться, что ты сумеешь как следует справиться со своей работой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10195, 'Наемник видит, наемник делает', 'С тех пор, как вы впервые принесли мне пучок перьев и я закончил шляпу Бертельма, все другие наемники потребовали себе такие же, даже Тандер! Я сказал, что тут же начну шить, но мне потребуются еще перья араккоа.$B$BЯ с радостью возьму у вас все перья, что вы найдете в лесу.', 'Принесите 30 перьев араккоа Роз\'алете в Бастион Аллерии.', '', NULL, NULL, NULL, 'Перо араккоа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10196, 'Больше перьев араккоа', 'Связь с духами араккоа потихоньку налаживается, но они все же слишком пугливы. Возможно, если я украшу свои одеяния, они согласятся приблизиться ко мне в трансе.$B$BДля этого мне понадобится еще немного перьев – тех, что вы однажды приносили. Приносите все, что удастся собрать, я с радостью приму их!', 'Принесите 30 перьев араккоа Малуказу в форт Камнеломов.', '', NULL, NULL, NULL, 'Перо араккоа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10197, 'Убедительная маскировка', 'Проникнуть в ряды армии Келя – нелегкая задача. С моим знанием магии иллюзий я могу придать тебе вид одного из приспешников Келя, однако в их форме есть некоторые детали, которые я не могу воспроизвести. $B$BПринеси мне комплект одеяний, пару перчаток и медальон охранников из клана Ярости Солнца. Это сделает камуфляж куда более убедительным.', 'Добудьте комплект одеяний чародея из армии Ярости Солнца, одну пару перчаток ученого из армии Ярости Солнца и медальон охранника из армии Ярости Солнца и принесите все это Каледису Сияющему Рассвету в манагорн Коруу в Пустоверти.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Превосходно! Когда я закончу работу, ты сможешь неузнанным проникнуть в ряды армии Келя!', 'Удалось ли тебе добыть те детали одежды, о которых я тебе говорил?', NULL, NULL, 'Перчатки ученого клана Ярости Солнца', 'Медальон охранника из клана Ярости Солнца', 'Одеяния чародеев клана Ярости Солнца', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10198, 'Сбор информации', 'Я подготовил форму вместе с добытыми тобою деталями. Она усилена магией для довершения иллюзии.$B$BМы заметили, что несколько минут назад командир Кузня Солнца в сопровождении охраны отправился на встречу с чародеем Ардонисом. Видимо, встреча будет невероятно важной; посмотрим, сможешь ли ты что-либо разузнать.$B$BО, едва не забыл: тебе нужно держаться подальше от чародейских големов, патрулирующих манагорн. Они могут видеть сквозь иллюзию.', 'Используя маскировку клана Ярости Солнца, проникните в Манагорн Коруу и подслушайте разговор между командиром Кузней Солнца и чародеем Ардонисом. По завершении задачи доложите о результатах Каледису Сияющему Рассвету. Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Проблены в манагорне Даро? Я уверен, Талодиен не прочь услышать такие новости. Но сначала закончим работу здесь.', 'Ну и как, удалось что-то подслушать, $N? Поспеши. У меня полно срочных дел.', NULL, NULL, 'Маскировка под воина клана Ярости Солнца (Прилагается)', 'Сбор информации', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10199, 'Дополнительная сила', 'Мне не хватает только одного ингредиента, который придаст моему составу дополнительную силу. $B$BШипы скатов Пустоты, болтающихся вокруг глиношкурых камнедеров, содержат массу действенного вещества. Принеси мне несколько таких шипов, и я извлеку яд прямо из них.$B$BЯ уверен, что результат будет просто взрывным!', 'Принесите 5 шипов скатов Пустоты Бутсу, находящемуся в Зоне 52 в Пустоверти.', 'Ух ты! Отлично, теперь и поговорим!$B$BДай, я только возьму эту прелесть и выжму из нее всю пакость. Если добавить это в ракетное топливо, то все просто из штанов повыпрыгивают!$B$BПогоди, я только примешаю этот яд к глинистой нефти, и посмотрим, что будет...', 'Если я смогу выкачать яд из достаточного количества шипов ската, то, думаю, мы сумеем получить самое взрывчатое топливо в истории!', NULL, NULL, 'Шип ската Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10200, 'Возвращение к Талодиену', 'Нужно, чтобы эти сведения попали к Талодиену как можно быстрее. Я останусь здесь, чтобы замести следы. $B$BБудет плохо, если Кель\'тас обнаружит, что мы тут занимались шпионажем. Тайная информация всегда ценнее, если враг не знает, что она у тебя есть.', 'Вернитесь к патрону шпионов Талодиену в Зону 52 в Пустоверти.', 'Ты не перестаешь удивлять меня, $N. Тебе удалось многое узнать в манагорне Коруу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10201, 'Момент истины', 'Масло готово, можно испытывать. Оно достаточно густое, чтобы из него вышла высококачественная смазка для оружия.$B$BЕдинственный способ проверить это – устроить профессиональное испытание. Видишь Грека, вон там, у объявлений о розыске? Он грубоват, но в оружии разбирается, как никто.$B$BОтнеси ему немного масла и попроси, чтобы он смазал им свое оружие. Когда испробует, пусть скажет, как оно ему понравилось.', 'Найдите Грека и попросите его смазать маслом свое оружие, после чего вернитесь к Ракории.', '<Вы рассказываете Ракории о результатах испытания и она громко хохочет, запрокинув голову.>', 'Ну, как прошло испытание?', NULL, NULL, 'Возьмите тестовое масло олембы у Грека', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10202, 'Дезертир', 'Недавно с нами связался магистр из клана Ярости Солнца, который желает вступить в наши ряды и утверждает, что у него есть нужные нам сведения. Мы провели проверку на предмет того, не является ли он двойным агентом, и он эту проверку прошел.$B$BОн находится в манагорне Ара, что сильно затрудняет переговоры. Поговори с ним и узнай, много ли ему известно. Если он хотя бы вполовину так полезен, как утверждает, то мы найдем ему хорошее применение.', 'Отправляйтесь в манагорн Ара и поговорите с магистром Теледорном. Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Ты вовремя. Я уже начал думать, что Провидцам нет никакого дела.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10203, 'Захват бесценного оборудования', 'Видишь расселину, идущую через Зону 52? Мы сделали это! $gухмыляется:. $B$BПосредством ее мы доставляем всякие полезные штуки для ракеты X-52, однако у нас не хватает оборудования. $B$BДо вторжения Пылающего Легиона мы проводили некую операцию в руинах Арклона к юго-востоку отсюда. Я прошу тебя отнести в эти руины ультра-разуплотняющий захват. Используй его, чтобы вернуть оттуда наши механизмы старшему саперу Бджимбуму, находящемуся на том конце расселины. $B$BМладший лаборант 3-й степени $N, это твой шанс на продвижение. Не упусти его!', 'Используйте ультра-разуплотняющий захват, чтобы доставить гиперротационный Рой-О-Мат, сервоприводную пневматическую землечерпалку, радужный световой анализатор грунта и большой фургон с взрывчаткой обратно в Зону 52. Затем сообщите старшему саперу Бджимбуму, находящемуся на восточном конце расселины, идущей через Зону 52 в Пустоверти.', 'Должно быть, это ты вернул нам все это саперное оборудование из руин! Ура!$B$BЯ уже распределил это оборудование по другим точкам. Теперь мы сможем выполнять наши операции по всему острову в порядке возрастания! Ракета Пустоты вот-вот будет построена.$B$BХмм, это странно. Минутку, сколько предметов ты нам послал? Я получил только три...', 'Классное местечко, скажи? И каждый день появляется что-нибудь новое и необычное. $B$BКак удачно, что мы едва не уничтожили поселение, копаясь здесь.', NULL, NULL, 'Гиперротационный Рой-О-Мат возвращен', 'Сервоприводная пневматическая землечерпалка возвращена', 'Радужный световой анализатор грунта возвращен', 'Большой фургон с взрывчаткой возвращен');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10204, 'Кристаллы камня Крови', 'Магистры Келя отточили свое использование кристаллов маны до такой степени, что могут откачать большое количество энергии за несколько секунд.$B$BДля этого они настраивают осколки более мелких кристаллов камня крови на более крупные, полностью заряженные кристаллы.$B$BОтправляйся в манагорн Б\'наар и отними один из этих осколков у магистра из клана Ярости Солнца, чтобы использовать его для перекачивания энергии из одного из более крупных кристаллов.$B$BВозвращайся ко мне, чтобы я могла изучить эффект ауры. Не беспокойся: любые побочные эффекты будут временными.', 'Магистр Ларинна просит вас отправиться в манагорн Б\'наар и отобрать осколок камня крови у магистра из клана Ярости Солнца. Используйте этот осколок поблизости от более крупного кристалла камня крови и возвращайтесь к Ларинне в Зону 52.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Хмм... как я и подозревала.$B$BВоздействие такого уровня сырой энергии во много раз увеличивает нашу природную зависимость от магии.$B$BЯ не удивлена, что Келю сходит с рук то, что он творит; все его подчиненные в основном упиваются этим.', NULL, NULL, NULL, 'Заберите осколок камня Крови и перекачайте с его помощью энергию более крупного кристалла.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10205, 'Астральный налетчик Несаад', 'С астральным налетчиком Несаадом должно быть покончено! Я понятия не имею, как он пережил мою атаку, но ему нельзя позволить продолжать творить все, что он хочет.$B$BВозвращайся и повергни Несаада. Он устроил маленький астральный лагерь поблизости от юго-западной оконечности Груды.$B$BПусть тебе повезет больше, чем мне, $C.', 'Убейте астрального налетчика Несаада, затем возвращайтесь к ловчему Пустоты Кай\'джи, находящемуся в Зоне 52 в Пустоверти.', 'Какое облегчение - услышать, что с этим негодяем наконец-то покончено. Отличная работа, $N... может быть, я слишком поспешил, назвав тебя по имени?$B$BЕсли ты не против, то у меня есть еще одно задание, которое требует исполнения. Оно чрезвычайно важно, и некоторые из уже проявленных тобою умений позволят тебе справиться с ним без труда.', 'Все кончено? Астральный налетчик Несаад мертв?', NULL, NULL, 'Астральный налетчик Несаад убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10206, 'В погоне за технологиями', 'Эти астральные шуты так же предприимчивы, как мы, это я за ними признаю. Но никто – то есть именно что НИКТО – не имеет права на то, что принадлежит МОЗГу!$B$BГруда на юге – наша!$B$BЕсли мы собираемся закончить ракету Пустоты Х-52, нам потребуются все новые технологии, которые мы только сможем заполучить. А поскольку духи Астрала крадут ее у нас, я думаю, будет только честно, если мы ответим им тем же.$B$BПочему бы тебе не отправиться туда и не посмотреть, можешь ли ты похитить их технологические наработки прямо у них из-под носа?', 'Соберите 10 астральных технологий и вернитесь с ними к Папаше Колесуну, находящемуся в Зоне 52 в Пустоверти.', 'Хе-хе, астральные неудачники!$B$BСпасибо за помощь, $C. Держу пари, мы сможем встроить эти штучки в ракету. Интересно, что они делают? Ну, вот и узнаем! $B$BХмм, погоди, я пороюсь в карманах и посмотрю, есть ли у меня чем заплатить тебе.', 'Как ты быстро – а технологии? С этим лучше не тянуть.$B$BУспех проекта Х-52 зависит от того, сможешь ли ты доставить нам технологии!', NULL, NULL, 'Астральная технология', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10207, 'Forward Base: Reaver\'s Fall REUSE', 'Верховное командование заметило твою доблесть в бою, $C. Тебя хотят отправить на передовую для встречи с командой Изуверского кулака. Они радикалы, твердо намеренные извести под корень Пылающий Легион, так что подойдешь...$B$BИди на восток 200 шагов, потом повернешь на юг у возвышенности. Увидишь Гибель Скверномора на том месте, где прежде стояла старая ферма. Как окажешься там, докладываешься передовому командиру То-Арху.$B$BШагом марш!', 'Доложитесь командиру передовой То\'арху по прибытии к останкам Сквернобота.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10208, 'Лишить Легион подкрепления!', 'На восток отсюда тянется передовая Легиона. По всей ее длине расположены порталы и ворота, по которым на полуостров Адского Пламени к Легиону поступает подкрепление. Мы должны их разрушить!$B$BВот, возьми эти запалы. Их разработали в Зоне 52, взрывчатым веществом для них служит собственная сила демонов. Нужно отбросить войска Легиона от порталов Зилус и Круул, собрать камни с рунами демонов и с помощью запала и четырех камней подорвать порталы. После выполнения задания возвращайся ко мне.', 'Уничтожьте врагов вокруг портала Зилус и портала Круул, соберите камни с рунами демонов.Используйте запалы То\'арха внутри порталов Зилус и Круул.Возвращайтесь к То\'арху в Гибель Сквернобота на полуострове Адского Пламени вместе с оставшимися запалами.', 'Просто прекрасно! Я, можно сказать, чуть ли не самолично почувствовал, как земля содрогнулась от взрыва!$B$BКак насчет еще одной подрывной работенки?', 'Ну как Легион, обрадовался подарочку, который мы для него подготовили, а, $N?', NULL, NULL, 'Выведите из строя Портал Зилус', 'Выведите из строя Портал Круул', 'Запалы То\'арха (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10209, 'Трофей призывателя Кантина', 'Следующее, что мы должны сделать – это забрать моего фамилиара, Студенора, у заклинателя из эльфов крови, который держит его в заточении. Призыватель Кантин был одним из старших магистров в войске, которое Кель\'тас отправил на уничтожение Кирин\'Вара. И, естественно, он забрал моего фамилиара в качестве трофея.$B$BЯ уверен, что Кантин, дурень этакий, пытался заставить Студенора служить ему. Прозрение открыло мне, что Кантин сейчас находится в так называемом \"манагорне Даро\", если это название о чем-нибудь тебе говорит.', 'Победите призывателя Кантина, находящегося в Манагорне Даро, на острове к северу от Форта Ярости Солнца, и заберите у него камень Студенора.', '<Сложно сказать, искажается ли изображение или верховный маг действительно улыбается.>$B$BТеперь, когда мне возвращено все, что было отобрано, у меня есть все необходимое, дабы пробиться сквозь магию Кель\'таса. Я немедленно начинаю работать над заклинанием.', 'Удалось ли тебе добыть камень Студенора?', NULL, NULL, 'Камень Студенора', 'Посох верховного мага Варгота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10210, 'А\'дал', 'Добро пожаловать в Шаттрат, $C. Возможно, это единственное место во всем Запределье, где можно почувствовать себя в безопасности.$B$BГруппа наару, известная как Ша\'тар, изгнала отсюда демонов.$B$BЕсли ты никогда не $gвидел:видела: наару, непременно зайди на террасу Света и поговори с А\'далом – это предводитель Ша\'тар и, пожалуй, самый харизматичное существо из тех, что я встречал. Он очень выделяется среди всех жителей этих суровых земель.', 'Поговорите с А\'далом, предводителем Ша\'тар, в центре террасы Света.', '<Когда вы приблизились к А\'далу, вас пронизал внутренний свет, а когда вы обратились к нему, свет усилился и в голове зазвучала нежная мелодия.>$B$B<Здесь вы в безопасности.:', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10211, 'Город Света', 'Не беспокойте А\'дала незначительными вопросами, $C. Это, возможно, самое могущественное существо из тех, что вы встречали.$B$BОднако ваше лицо мне незнакомо... Вы, должно быть, мало знаете о нашем городе?$B$BНадеюсь, вы простите меня за то, что я не поведу вас на экскурсию лично, – мне нужно очень многое обсудить с А\'далом. Вас устроит призванный слуга? Вот и отлично!', 'Проследуйте за слугой Кадгара и выслушайте историю, которую он вам расскажет, после чего вернитесь к Кадгару.', 'Надеюсь, вы узнали кое-что о Шаттрате, $N. Понадобится время, чтобы информация устоялась в вашей памяти.', 'Истории о людях недолговечны, $N. А вот истории о городах живут столетиями.', NULL, NULL, 'Город Света', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10212, 'Герой маг\'харов', 'Перед отъездом я должен уладить кое-какие дела. Вернись к Великой матери и скажи, что ее внук скоро прибудет.', 'Вернитесь к великой матери Гейе в Гарадар в Награнде. ', 'Ты - настоящий герой маг\'харов, $N. Если бы не ты, нас подмяли бы огры и Сломленные.$B$BМы небогаты, но у нас есть артефакты, наделенные немалой силой. Пожалуйста, я прошу... нет, я настаиваю... загляни в наш сундук и возьми, что захочешь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10213, 'Найти место крушения', 'Меня ранили при отступлении, но я видел, как потерпел крушение гоблинский дирижабль. Он упал куда-то на северо-запад, за оружейной экспедиции.$B$BДирижабль был весь в огне. Пронзительно визжащие гоблины выпрыгивали из него на лету, как живые факелы. Я тогда не помнил себя от боли и вдобавок потерял много крови. Могу представить, каково пришлось этим бедолагам.$B$BЕсли ты найдешь кого-нибудь уцелевшего, мы предоставим ему убежище на заставе Хребтолома.', 'Отыщите уцелевших в катастрофе.', 'Нас подбил Пылающий Легион, хотя мы и размахивали белым флагом. Кто же знал, что они там такие тупые ублюдки?$B$BК сожалению, мы не сможем отправиться на Заставу Хребтолома. Надо чиниться и двигаться дальше.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10214, 'Весь рудник ходуном', 'На руднике и так было не продохнуть от ган\'аргской заразы, а теперь еще все батраки решили, что сейчас самое время вздре$Nть! Не представляю, как им удается спать во время этого бедлама, но это уже не мои проблемы.$B$BЕсли мы не избавимся от этих ган\'аргов, поставки руды и остальных материалов в Траллмар полностью прекратятся! Я обращался к командиру стражи Кранку, но он ответил, что, дескать, не может выделить бойцов, пока город находится под угрозой. Может быть, хотя бы ты нам поможешь?', 'Убейте 15 ган\'аргов-саперов и возвращайтесь к штейгеру Разлкразу.', '', NULL, NULL, NULL, 'Ган\'арг-сапер убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10216, 'Прежде всего - безопасность!', 'Астральные слуги Шаффара полностью перекрыли нам вход в Гробницы Маны. К счастью, у меня есть план. Мы не можем воспользоваться главным входом, но внутри должно быть несколько порталов.$B$BЯ хочу, чтобы ты сначала $gрасчистил:расчистила: дорогу для моей команды, а затем $gактивировал:активировала: один из порталов, чтобы телепортировать нас внутрь.$B$BПортал находится в комнате направо от входа в залы Шаффара. Не беспокойся, я позабочусь, чтобы ты не $gостался:осталась: внакладе.', 'Убейте 10 эфириалов – осквернителей гробниц, 5 эфириалов-колдунов, 5 ловчих нексуса и 5 эфириалов-чароплетов по просьбе работника Морфалиуса.После этого найдите эфириальский телепорт в зале, предшествующем палате Шаффара, и активируйте его.', '*Вы зажмуриваетесь и наугад нажимаете одну из кнопок.*', 'Прямо перед вами находится устройство с множеством кнопок непонятного назначения.', NULL, NULL, 'Эфириал - осквернитель гробниц убито', 'Ловчий нексуса убито', 'Эфириал-колдун убито', 'Эфириал-чароплет убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10218, 'Someone Else\'s Hard Work Pays Off', 'А ты кого $gждал:ждала:? Этот идиот Морфалиус разжалован. Теперь мне придется расхлебывать кашу, которую он заварил. Тебе нужно только прикрывать меня, пока я не дойду до Шаффаровых собирателей астральной субстанции и не выжму из них все, что они насобирали. Если мне это удастся, тебя наградит сам Харамад.$B$BНу, что скажешь? Проводишь меня в Гробницы Маны, где тебя ждут несметные сокровища? Ты уже и так, почитай, полдела $gсделал:сделала:! Ведь позади нас никого не осталось, верно?', 'Проводите криоинженера Ша\'хина в Гробницы маны, чтобы он мог собрать астральную субстанцию в коллекторах Шаффара.В случае успеха явитесь к принцу нексуса Харамаду в лагере Консорциума.', 'Поскольку это была идея Морфалиуса, я решил поручить ему его прежнюю работу. А ты очень неплохо поработал, маленький кусочек плоти. Совсем, совсем неплохо!$B$BЕсли опять окажешься в Пустоверти и тебе будет нужна работа, разыщи меня в Штормовой Вершине.', NULL, NULL, NULL, 'Сопроводите крио-инженер Ша\'хина.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10220, 'Заставь их слушать', 'Меня послали, чтобы установить контакт с Непреклонными духами. Когда-то они были гордыми солдатами Альянса, но потерпели поражение, и теперь их проклятые души населяют западные руины.$B$BЕсли бы нам удалось уговорить их присоединиться, мы приобрели бы могучих союзников. Представь себе легион бессмертных воинов, которые атакуют наших врагов! К сожалению, Непреклонные пришли в ярость и отказались меня выслушать.$B$BМожет быть, мы заставим их сотрудничать силой?', 'Убейте 12 непреклонных пехотинцев, 8 непреклонных рыцарей и 6 непреклонных колдунов в оружейной экспедиции к западу от заставы Хребтолома по просьбе Мордибы.', 'Пусть эти Непреклонные знают, как иметь дело с Ордой! Не сомневаюсь, скоро они согласятся перейти на нашу сторону.', NULL, NULL, NULL, 'Непреклонный пехотинец убито', 'Непреклонный рыцарь убито', 'Непреклонный колдун убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10221, 'Доктор Бум!', 'Знаешь, $N, мой бывший подопечный, Живчик Вечнодвигатель, никогда не надевал шлем, находясь здесь, внизу, и в один прекрасный день превратился в печально известного Доктора Бума!$B$BОн сбежал на северо-восток, украв большую часть нашего подрывного оборудования! Он и его взрыв-боты с тех самых пор представляют собой угрозу для Зоны 52.$B$BЯ хочу послать тебя в Лагерь Бума, находящийся за городом, дабы покончить с этим негодяем. Используй эти бомбы Рока Бума, чтобы избавиться от него.$B$BИ ни в коем случае не подходи близко к нему и к его взрыв-ботам!', 'Убейте Доктора Бума и возвращайтесь с хорошими новостями к старшему саперу Бджимбуму в Зону 52 в Пустоверти.', 'Я всегда буду тосковать по Живчику. (хлюпает носом) Но мы все будем спать спокойнее теперь, зная, что доктор Бум больше не будет терроризировать нас!$B$BПусть это послужит тебе уроком! Никогда не спускайся сюда без шлема Пустоты!$B$BНу что ж, чем я могу оплатить твои хлопоты?', 'Удалось ли тебе спасти нас от разрушений, причиняемых Доктором Бумом? Я обещаю, что на этот раз не будет никаких взрывающихся повозок, хотя это очень весело!$B$BНеплохо бы устраивать такое почаще.', NULL, NULL, 'Доктор Бум убито', 'Бомба Бума (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10222, 'Гарнизон Ярости Солнца', 'После того как войска принца Кель\'таса уничтожили это поселение и заточили верховного мага в Аметистовой башне, они отступили на северо-восток, в форт Ярости Солнца. Те самые солдаты, которые уничтожили наши дома и убили наших товарищей, празднуют свою \"великую победу\", в то время как мы не можем даже отомстить за павших.$B$BМы не должны позволить, чтобы подобное преступление осталось без ответа. Будь орудием нашего возмездия, $N. Ступай в форт Ярости Солнца и отними жизни у тех, кто виновен в этом преступлении.', 'Смотритель Дайворт из деревни Кирин\'Вар просит вас убить 10 лучников из армии Ярости Солнца.', 'Пусть даже сделанное тобой не сможет вернуть к жизни павших, но, быть может, даст покой их душам. Хотя, правду сказать, даже море крови не угасит мой гнев, вызванный деяниями Кель\'таса.', NULL, NULL, NULL, 'Лучник клана Ярости Солнца убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10223, 'Покончить с Даэллисом', 'Я никогда не забуду эльфа крови, возглавлявшего ту атаку. Поверх алого доспеха на нем была гербовая накидка с эмблемой, которую я никогда прежде не видел.$B$BОн был свиреп и безжалостен и шел впереди всех, хотя большинство офицеров из эльфов крови так ни за что не поступили бы. В тот день он убил множество магов Кирин-Тора. Однако в форте Ярости Солнца он пробыл недолго. Кель\'тас отослал его в манагорн Даро, дабы помочь тамошним эльфам в их попытках взять контроль над этим регионом. Найди его, $N, и пусть его лук никогда больше не выстрелит.', 'Смотритель Дайворт из деревни Кирин\'Вар просит вас убить наставника Даэллиса Стрелка Рассвета.', '<Может быть, вам это всего лишь кажется, но смотритель Дайворт словно бы готов разрыдаться.>$B$BНаконец-то это свершилось. Если бы я мог по собственной воле завершить свое существование, я бы сделал это, но истина в том, что я не знаю, как уйти. Для обитателей деревни это сложно, однако все впереди. Я полагаю, такова цена, которую мы платим за сильную привязанность к этому месту.', NULL, NULL, NULL, 'Наставник Даэллис Стрелок Рассвета убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10224, 'Эссенция для двигателей', 'Как главный инженер проекта ракеты Пустоты Х-52 я должен сделать так, чтобы главный двигатель был в наилучшем виде.$B$BК несчастью, я его еще не построил.$B$B$C, я в отчаянном положении! У меня есть почти все детали. Отсутствует только ядро двигателя.$B$BК счастью, для того, чтобы запустить двигатели, мы, вероятно, можем использовать эссенцию из местных призраков магии.$B$BИх можно найти почти возле каждой светящейся канавы в северной части острова. За исключением Зоны 52, конечно.', 'Соберите 7 единиц эссенции призрака магии и доставьте главному инженеру Трепу в Зону 52 в Пустоверти.', 'Ого, тут полно эссенции!$B$BОтлично, посмотрим, что будет, когда я смешаю ее с астраллитиевыми матричными кристаллами.', 'Ну как, удалось набрать эссенции?', NULL, NULL, 'Сущность призрака магии', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10225, 'Рапорт главному инженеру', '$N! Я прошу тебя доставить эти астраллитиевые кристаллы главному инженеру Трепу, моему... э-э... начальнику в области инженерного дела.$B$BОн должен знать, что с ними делать. А если не знает, то поймет, вот увидишь!', 'Передайте астраллитиевые матричные кристаллы главному инженеру Трепу, находящемуся в Зоне 52 в Пустоверти.', 'О-о, астраллитиевые матричные кристаллы! Да, это важное дело!$B$BДавай положим их вот сюда, и я немного над ними поразмыслю.', 'А, привет. Я тут малость занят. Что там у тебя?', NULL, NULL, 'Астралитиевые матричные кристаллы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10226, 'Извлечение силы стихии', 'Проклятье, это не сработало!$B$BЛадно, у меня есть другая идея! Я заставил Ксирола собрать экстрактор силы стихии. Я не уверен, что именно делает эта сила, но знаю, что могу использовать ее.$B$BВыщербленные грохотуны и астральные аберрации, встречающиеся на уступе Гиблого пустыря к югу отсюда, – именно то, что мне нужно для заправки двигателей!$B$BЭкстрактор превратит их силу в нечто материальное, так что ты сможешь собрать ее – после того, как одолеешь ее носителей.', 'Извлеките 5 единиц силы стихии для главного инженера Трепа, находящегося в Зоне 52 в Пустоверти.', 'Вот это уже лучше! Ну ладно, теперь займемся делом.$B$BДай я только перелью всю эту субстанцию вот в эту штуковину, и я уверен, что ядро фазового двигателя будет функционировать.$B$BАга, полагаю, я тебе что-то должен за спасение моей головы? Хе-хе...', 'Ну как, удалось извлечь энергию элементалей? Да нет, какой смысл спешить? На кон поставлены всего лишь моя жизнь и карьера.', NULL, NULL, 'Сила стихии', 'Экстрактор силы элементалей (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10227, 'Я вижу мертвых дренеев', 'Я вижу мертвых дренеев. Они тут повсюду.$B$BНо мне никто не верит, потому что я всего лишь ребенок. Даже мама, и та не верит.$B$B<Ха\'лей указывает на Рамдора.>$B$BТолько он верит. Он тоже их видит. Но ему тоже не верят, и это выводит его из себя!$B$BСтранно, правда? Когда я вижу призраков, люди улыбаются и гладят меня по головке. А когда он видит призраков, все считают его чокнутым. Надеюсь, я никогда не стану, как эти взрослые!$B$BНо ты бы лучше $gпоговорил:поговорила: с Рамдором перед тем, как полезешь внутрь. Все-таки раньше он был жрецом мертвых.', 'Поговорите с Рамдором Безумным, который стоит на груде костей неподалеку от Аукенайских гробниц.', 'Ребенок прав. Когда-то я в самом деле был \"жрецом мертвых\".$B$B<Рамдор кривится.>$B$BМалоприятный титул.$B$BЭтот коридор ведет в Аукенайские гробницы. Там, внутри, ты найдешь то, что осталось от моей паствы. Разумеется, теперь все они совершенно безумны. Сошли с ума, все до единого. Очевидно, я слишком выделялся среди них, будучи единственным, кто сохранил хотя бы остатки здравого смысла. Конечно же, меня изгнали за мои убеждения.$B$BХочешь знать, за какие?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10228, 'Иезекииль', 'Я полагал, что мертвецов, которыми мы занимались последние 500 лет, пора оставить в покое. Но у Маладаара другие планы. Он забрался в склеп Воспоминаний и начал там свои эксперименты... с некромантией.$B$BЯ надеюсь, ты не собираешься туда соваться? Ну, по крайней мере, для начала помоги мне избавиться от этих проклятых духов. Я знаю, где они хранят свои сокровища, $r! Что, интересно?$B$BТак вот, принеси мне книгу мертвых, которой владеет Алдор, Иезекииль из Шаттрата.', 'Найдите Иезекииля из Шаттрата в городе Шаттрат и поговорите с ним.', 'Книга мертвых? Никогда о такой не слышал... О чем вообще речь? Кто тебя прислал?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10229, 'Секрет фолианта', 'Похоже, в этом фолианте записана некая история, но не просто так, а секретным шифром Альянса. Альтен, историк с Заставы Хребтолома, какое-то время изучал Непреклонных. Может быть, ему удастся расшифровать код и прочитать эту книгу.', 'Отнесите таинственный фолиант Альтену Историку на Заставу Хребтолома.', 'Я изучаю историю древних всю свою жизнь, но не видел ничего похожего на эту книгу. В ней изложена вся история Оружейной, даже то, что произошло после ее разрушения.$B$BТела Непреклонных остались лежать на поле сражения, но они все равно продолжали вести свою летопись. Эта книга должна нам помочь понять Непреклонных, и уговорить их вступить в наши ряды.', 'Что это? Эта книга была у Непреклонного духа? Как странно. Дай-ка посмотреть. Возможно, теперь я узнаю историю Непреклонных.', NULL, NULL, 'Таинственный фолиант (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10230, 'Боевой рог', 'Может быть, мы выбрали к Непреклонным не тот подход?$B$BВ фолианте написано, что оружейную экспедиции когда-то давным-давно разрушили рыцари смерти. И Непреклонные – это духи мщения, обреченные вести нескончаемую войну с орками Скверны.$B$BВсе их помыслы – только о мести. Мы должны пообещать, что дадим им возможность сразиться со своими самыми злейшими врагами. Отправляйся в оружейную снова и разыщи лейтенанта-командора Талвоса. У него есть боевой рог, который призывает Непреклонных. Принеси его мне.', 'Заберите у лейтенанта-командора Талвоса Боевой рог Непреклонных и принесите его Альтену Историку на Заставу Хребтолома.', 'Ты хорошо потрудился, $N. Этот древний рог позволит нам призывать Непреклонных.$B$BКонечно, если они согласятся.', 'Скоро мы сможем помочь Непреклонным. Если мы убедим их присоединиться к Орде, они станут могучими союзниками!', NULL, NULL, 'Боевой рог непреклонных', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10231, 'Какая книга? Не вижу никакой книги', 'Рамдор? Хмм... Дай-ка подумать... Рамдор... Ах да, жрец мертвых. Чего он хочет, какую книгу? Ладно, это не важно. Конечно, я тебе соврал и никакой книги у меня нет. Была, а теперь нет. Ее у меня украли. Наверное, кто-то из этих мерзких беженцев.$B$BКроме того, Аукиндон давно развалился, и книгу все равно уже невозможно использовать. Если найдешь ее, смело можешь оставить себе.$B$BКак я уже говорил, на прошлой неделе тут шныряли какие-то бандиты, можешь начать поиски с них. Я думаю, они режутся в кости где-нибудь в трущобах.', 'Иезекииль говорит, что книга могла быть украдена. Найдите головорезов и попытайтесь узнать что-нибудь у них.', 'Ладно, хватит, больно же! У нас была какая-то книга, но мы ее сбагрили...', 'Че надо?', NULL, NULL, 'Победить \"Грязного\" Ларри и добыть информацию', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10232, 'Легион – на мусор!', 'Пылающий Легион ступил в наши владения на Захламленном поле, что находится вниз по тропе отсюда, а далее по мосту на восток.$B$BДля нас это может представлять серьезную проблему. Пребывание Легиона в руинах Арклона – а он сейчас находится там – несет угрозу и нам, и всему проекту по построению ракеты здесь, в Зоне 52.$B$B$N, отправляйся туда и покончи с этими демонами. Я бы и сам это сделал, но я не боец, а так, д$Nант.$B$BНу да, если дело пойдет плохо, я это почую!', 'Убейте 5 мо\'аргов-кузнецов рока и 15 ган\'аргов-инженеров. Затем возвращайтесь к Папаше Колесуну в Зону 52 в Пустоверти.', 'Ну что ж, хорошие новости и плохие новости, верно? Мы нанесли им удар, но все же Пылающий Легион продолжает заполонять всю Пустоверть и подбирается к нам все ближе. Я теперь уж и не знаю, как все обернется.$B$BУ меня такое чувство, что нам придется на некоторое время сменить курс. Надеюсь, ты сможешь нам помочь, $N.', NULL, NULL, NULL, 'Мо\'арг-кузнец рока убито', 'Ган\'арг-инженер убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10233, 'Пожар в форте Ярости Солнца', 'Если даже очистить форт Ярости Солнца от гарнизона, это не помешает эльфам крови вновь занять его. Последователи Кель\'таса упорны и полны решимости. Оставить в форте Ярости Солнца что-либо, что они могут использовать, равносильно приглашению вернуться.$B$BНет, это все следует уничтожить. Проследи, чтобы все их шатры и боевые орудия превратились в угли и пепел!$B$B<Призрак сжимает кулаки.>$B$BДля того чтобы выполнить эту задачу, надо похить факелы у хранителей пламени из армии Ярости Солнца, $N.', 'Используя горящий факел, уничтожьте 4 баллисты и 4 шатра в форте Ярости Солнца, затем вернитесь к лейтенанту-чародею Моррану в деревню Кирин\'Вар.', '<Лейтенант-колдун Морран мрачно кивает.>$B$BВолшебники Кирин-Тора не любят разрушение как таковое, но мы без колебаний пускаем его в ход против наших врагов, даже после смерти.', 'Дым поднимается над укреплениями форта Ярости Солнца. Это твоя работа?', NULL, NULL, 'Уничтожено баллист Ярости Солнца', 'Уничтожено шатров Ярости Солнца', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10234, 'Что одному демону мусор...', 'Похоже, ты много на что $gспособен:способна:! А не можешь ли ты мне помочь?$B$BК востоку отсюда находится Захламленное поле, куда вторгся Пылающий Легион. Там полно огромных частей скверноботов. И еще там целые горы более мелких деталей, которых, похоже, никому не нужны.$B$BЯ прошу тебя отправиться туда и принести мне много-много этих мелких деталей от скверноботов!', 'Соберите 10 деталей сквернобота и доставьте их Мамаше Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти.', 'Полагаю, пока что хватит. Если бы мы только могли собрать их все...$B$BАга, у меня возникла идея!', 'Удалось ли добыть детали? Пылающий Легион попирает все наши права, одно за другим, и у нас, увы, осталось мало времени.', NULL, NULL, 'Деталь сквернобота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10235, 'Коготь Рока? Вырвать с мясом!', 'Ты знаешь, что может лишить их храбрости? Гибель их предводителя!$B$BСудя по тому, что я слышала, это срабатывает всегда и везде. А когда они увидят, как $gтакой:такая:c: $C, как ты, повергает их вожака... держу пари, они подожмут хвосты и удерут в холмы!$B$BВозвращайся туда и пристукни самого большого, которого они называют Коготь Рока. Я слышала, он прячется в восточной части Захламленного поля под трубой.$B$BПринеси мне его коготь. Может, и ему найдется применение.', 'Заберите руку Когтя Рока и доставьте ее Мамаше Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти.', 'Он... что он сказал? ОНИ СОБИРАЮТСЯ ПОЙТИ НА ЗОНУ 52?!$B$BО, это плохо... ужасно плохо!', 'Ну что, с Когтем Рока покончено?', NULL, NULL, 'Рука Когтя Рока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10236, 'Гадость это ваше Запределье!', 'Не могу поверить, что я бросил свою родную Пиратскую Бухту и перебрался сюда, в Запределье. Мой кузен Скрид Счастливчик наобещал мне золотые горы, а сам сел на дирижабль и смылся, оставив меня в прямом смысле слова выскребать из рудника средства к существованию.$B$BНе понимаю, как можно жить, когда на тебя постоянно нападают то зловепри, то демоны, то орки Скверны? Вчера у меня сломался крошшер, а запчасти к нему сперли орки Скверны. Они отправились куда-то на юго-запад, и наверняка уронили мои драгоценные детали в одну из тамошних расщелин.', 'Найдите 6 частей крошшера и верните их штейгеру Разлкразу на рудник, который находится к северо-западу от Траллмара.', 'Ура, ура, запчасти снова у меня! Может быть, теперь я смогу починить крошшер. Если я заработаю достаточно денег, то смогу выбраться отсюда и вернуться домой.$B$BНадеюсь, к этому времени кузен Счастливчик наконец расколотит свой дирижабль! Не могу поверить, что он обманом затащил меня в это гадское Запределье.', 'Ну как, удалось вам найти запчасти от крошшера? Если я не починю его, то не смогу работать! А мне нужны деньги, чтобы вернуться в мою драгоценную Пиратскую Бухту!', NULL, NULL, 'Запчасти крошшера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10237, 'Предупредить Зону 52!', '$N, тебе следует немедленно возвращаться в Зону 52! Живо!$B$BСкажи командующему ракетами, что Пылающий Легион идет на нас!', 'Передайте плохие новости ведущему ракетостроителю Фьюзеляжу в Зоне 52 в Пустоверти.', 'Эй, ты же шутишь, да? Пылающий Легион винит во всем этом нас?$B$BНо это же все ТВОИ деяния!$B$BОх, у меня голова распухла до размеров этой ракеты. Ладно, ладно, придется менять планы.$B$BЕсли Пылающий Легион думает, что может вот так запросто прийти сюда, уничтожить наш город и разрушить мои мечты о путешествии через Круговерть Пустоты, то они глубоко ошибаются.$B$BЯ знаю гоблина, который нам поможет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10238, 'Каково работать на гоблинов', 'Ну почему эти орки Скверны свистнули запчасти от моего крошшера? Как я их ненавижу! Они все время проползают в мой лагерь и прут все, что плохо лежит. Несколько дней назад они утащили даже троих батраков! А теперь все остальные поразбежались, потому что боятся, что орки Скверны тоже поймают их и сожрут.$B$BКак прикажете управлять рудником, когда на нем не осталось батраков? Если вы спасете тех, кого увели орки, может быть, и все остальные вернутся? Лагеря орков Скверны расположены вдоль стены на юго-западе.', 'Спасите Манни, Моха и Джакка из лагерей орков Скверны и доставьте их штейгеру Разлкразу на рудник, который находится к северо-западу от Траллмара.', 'Спасибо, что спасли моих батраков! Может быть, теперь мне удастся заставить их починить крошшер, благо запчасти вы мне тоже вернули. И тогда я наконец заработаю денег и смогу вернуться в Пиратскую Бухту!', 'Ну как, удалось вам спасти моих батраков? Поторопитесь, пожалуйста. Их могут съесть, а они не особенно вкусные... Страшно подумать, как на меня разозлятся орки Скверны, если рабы придутся им не по вкусу!', NULL, NULL, 'Манни спасен', 'Мох спасен', 'Джакк спасен', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10239, 'Потенциальный источник энергии', 'Мы не единственные, кто борется со вторжением мана-тварей. Эльфы крови тоже встревожены их появлением, однако я не знаю точно, почему.$B$BОднако во что бы они ни были втянуты, похоже, они не намерены останавливаться. Напротив, я вижу, что они применяют различные методы для убиения тварей. Самые эффективные способы включают в себя установку магической защиты, питаемой каким-то видом концентрированной энергии.$B$BЗахвати несколько таких источников энергии и принеси их мне. И если представится возможность в чем-либо помешать эльфам, сделай это без колебаний.', 'Лейтенант-чародей Морран из деревни Кирин\'Вар просит вас захватить 10 энергетических кубов-изоляторов, используемых эльфами крови в манагорне Коруу.', '<Морран осторожно берет одно из вместилищ.>$B$BМне кажется, ранее я не видел ничего подобного. В нем определенно содержится множество энергии, однако в необработанном, сыром виде. Мы должны быть осторожны с ней, однако я думаю, мы найдем, как приспособить ее для защиты от мана-тварей.', 'Тебе удалось заполучить источники их энергии?', NULL, NULL, 'Энергоизоляционный куб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10240, 'Постройка периметра', 'Мы решили соорудить вокруг деревни защитный периметр, используя источники энергии, отобранные у эльфов крови. Я не могу гарантировать, что это сработает, но мы должны попытаться.$B$BИначе мана-твари, несомненно, будут продолжать поглощать духов погибших магов из Кирин-Тора.$B$BИспользуй это устройство на малых рунах по периметру поселения, чтобы высвободить энергию. Если я правильно соткал это поле, то разница будет заметна сразу же после того, как ты применишь это устройство на каждой руне.', 'Используйте устройство пробуждения рун поблизости от восточной, северо-восточной и западной руны. Руны можно найти по периметру районов переулка Волшебников и главной площади деревни Кирин\'Вар. По завершении задачи вернитесь к лейтенанту-чародею Моррану.', 'Отличная работа, $N. Теперь держи за меня кулаки - я собираюсь включить щит.', 'Все ли руны пробуждены? Я хочу узнать, удалось ли нам улучшить методы эльфов крови. Все, что могут сделать подчиненные Кель\'таса, настоящие маги Кирин-Тора могут сделать лучше.', NULL, NULL, 'Пробудите Восточную руну', 'Пробудите Северо-восточную руну', 'Пробудите Западную руну', 'Устройство пробуждения рун (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10241, 'Отвлекающий маневр в манагорне Б\'наар', 'Мы были посланы Ша\'тар, чтобы провести расследование по поводу манагорнов, которыми управляет армия Кель\'таса. К несчастью, Провидцы угрожают отказаться от своих обязанностей по сбору сведений, если мы не поддержим их путем военных действий.$B$BМы не можем позволить, чтобы эта миссия потерпела провал из-за политики, поэтому согласились ослабить защиту манагорнов, дабы Провидцы могли выполнить свою работу.$B$BПрояви свою верность Алдорам – убей магистров и кровостражей клана Ярости Солнца, которые охраняют манагорн Б\'наар.', 'Убейте 8 магистров и 8 кровостражей клана Ярости Солнца, затем возвращайтесь к экзарху Орелису в Зону 52.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Превосходная работа, $N! Благодаря твоим отвлекающим действиям Провидцы сумели добыть ценные сведения. Может быть, на этот раз они действительно поделятся этими сведениями с нами.', NULL, NULL, NULL, 'Магистр из клана Ярости Солнца убито', 'Кровостраж клана Ярости Солнца убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10242, 'Застава Хребтолома', 'К сожалению, $N, у меня нет оборудования, чтобы провести все исследования, какие нужно. Но нужные инструменты есть у моего коллеги, аптекаря Альбрека, на заставе Хребтолома.$B$BАгенты Траллмара во время своей прошлой экспедиции собрали кровь орков из клана Кровавой Глазницы, и мне удалось добыть образец. Отнеси его Альбреку, пусть изучит его как следует.$B$BЕсли хочешь без помех добраться до заставы Хребтолома, разыщи командира звена Бракка. Он где-то на юге, рядом с вивернами.', 'Доставьте образец крови орков из клана Кровавой Глазницы аптекарю Альбреку на заставу Хребтолома по просьбе аптекаря Зеланы из Погибели Сквернобота. Чтобы добраться до заставы на виверне, обратитесь к командиру звена Бракку.', 'Протестировать образец крови, да? С превеликим удовольствием! Работать с кровью всегда приятно...', 'Добро пожаловать на Заставу Хребтолома! Чем могу служить?', NULL, NULL, 'Образец крови орка из клана Кровавой Глазницы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10243, 'Технология наару', 'Провидцы раздобыли список персонала манагорна Б\'наар и теперь работают над тем, чтобы выбрать цели для убийства.$B$BОни упустили одну маленькую крупицу информации – запись на обратной стороне списка. Похоже, это пароль или код, используемый для доступа к созданным наару технологиям, таким как \"Экзодар\" или Крепость Бурь.$B$BИди в манагорн и взгляни на панель управления. Скопируй ее показания на этот свиток как можно точнее. Мы должны подтвердить наши подозрения относительно этой технологии.', 'Зайдите в манагорн Б\'наар и найдите панель управления манагорном.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Ты разворачиваешь свиток и готовишься скопировать странные символы.', 'Символы, разворачивающиеся перед тобой, выглядят чуждыми и непонятными.', NULL, NULL, 'Чистый свиток (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10244, 'Учи матчасть!', 'Сломав печать на этом огромном томе, ты не можешь понять, что в нем говорится. Похоже, книга написана на языке демонов.$B$BОднако ты вполне понимаешь картинки, которые сами по себе говорят о многом.$B$BЯсно, что это инструкция по созданию сквернобота, и ты точно знаешь, что Мамаша Колесун очень захочет на это взглянуть!', 'Отнесите инструкцию по созданию сквернобота Мамаше Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10245, 'Описание панели управления Б\'наара', 'Ты пытаешься описывать рисунки и знаки, вспыхивающие у тебя перед глазами. Результаты получаются далеко не точными, однако вполне могут послужить доказательством того, насколько правильны – или неправильны – подозрения Алдоров.', 'Передайте описание панели управления Б\'наара анахорету Карже в Зону 52 в Пустоверти.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Неплохая работа, $N. Подожди минуту, я прогляжу это описание. $B$BЖречество благодарно тебе, $C.', 'Давай посмотрим, что это такое, $N.', NULL, NULL, 'Описание панели управления Б\'наара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10246, 'Нападение на манагорн Коруу', 'Тебе удалось добиться примечательных успехов в манагорне Б\'наар. Я уверен, что анахорет Каржа попросит тебя повторить то же самое в манагорне Коруу.$B$BМы узнали, что туда отправлено подразделение, состоящее из известных чародеев и ученых клана Ярости Солнца. Если ты выберешь это подразделение своей целью и преуспеешь в его уничтожении, то нанесешь сокрушительный удар по врагу.', 'Отправляйтесь к манагорну Коруу и убейте 8 чародеев и 5 ученых из армии Ярости Солнца. По завершении задачи возвращайтесь к экзарху Орелису.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Превосходная работа, $N. Подобная решимость, несомненно, позволит нам победить врага.', NULL, NULL, NULL, 'Ученый клана Ярости Солнца убито', 'Чародей клана Ярости Солнца убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10247, 'Вомиза, доктор псевдотехнических наук', 'За восточной окраиной города располагается Испытательный полигон. Наш главный экспериментатор, доктор Вомица, играл там с сочетанием технологий скверноботов, эфириалов и, конечно же, гоблинов.$B$BИ в немалой степени это удалось благодаря твоим усилиям по сбору сведений, младший лаборант 3-й степени $N!$B$BОтправляйся к доктору; я знаю, что он нашел решение проблемы - как спасти Зону 52.$B$BИ поскольку он скорее всего захочет задействовать тебя как объект для испытаний, то на твоем месте я на всякий случай взял бы с собой друга.', 'Поговорите с доктором псевдотехнических наук Вомизой на Испытательном полигоне в Пустоверти.', 'Ну-ну, похоже, нам повезло, юноша.$B$BЯ недавно завершил сборку моего последнего изобретения, \"Утилизатора Х6000\"!$B$BИ тебе выпала высокая честь – помочь мне испытать этот утилизатор, чтобы его можно было использовать при защите Зоны 52!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10248, 'Ты, робот', 'Доктор псевдотехнических наук Вомиза к вашим услугам. Вот, возьми этот пульт управления. Активируй его и погоняй мой новоизобретенный \"Утилизатор Х6000\".$B$BТолько оставайся поблизости! Пульт связан с моей панелью управления, и если ты отойдешь слишком далеко, робот перестанет действовать.$B$BПопробуй все функции... Я буду смотреть и калибровать сервомоторы, основываясь на проведенных тобой испытаниях.', 'Активируйте пульт управления \"Утилизатора Х6000\" и проверьте его возможности. Затем передайте результаты доктору псевдотехнических наук Вомице, находящемуся на испытательном полигоне в Пустоверти. Если возникнут проблемы, разберитесь с ними..', 'Что ж, приятель, это было просто великолепно! Я бы сказал, что \"Утилизатор Х6000\" справился великолепно, невзирая на столь неуклюжее управление.$B$BХе-хе, не обижайся, я просто шучу. В конце концов, твои действия спасли Зону 52 и ракету Пустоты Х-52 от уготованной им судьбы!', 'И что ты думаешь? Требуется еще доработка, ага?', NULL, NULL, 'Испытайте \"Утилизатор Х6000\"', 'Устройство управления \"Утилизатором Х6000\" (Прилагается)', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10249, 'Обратно к командующему!', 'Я уверен, что ведущий ракетостроитель захочет перемолвиться с тобой парой слов.$B$BНа твоем месте я сразу же отправился бы в Зону 52, чтобы поговорить с ним!', 'Немедленно явитесь к ведущему ракетостроителю Фьюзеляжу в Зону 52 в Пустоверти!', '$N! Или мне следует сказать - младший лаборант 1-й степени $N?! Но шутки в сторону. Даже повышение на две степени будет слишком маленькой наградой за твои деяния. Я собираюсь сделать тебя своим первым офицером!$B$BТы спас нас всех, более того - ракету Х-52! Я мог бы расцеловать тебя... но не буду. $B$BВместо этого позволь мне одарить тебя в знак признательности от имени всей Зоны 52! Вот твоя награда!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10250, 'Кровавая месть', 'К востоку отсюда стоит разрушенная осадная башня Альянса. Мародеры давно растащили по кусочку все, что там осталось. Когда-то давно в этой башне простились с жизнью многие солдаты Альянса, а их знамя было захвачено Уртраком, командиром орков Скверны.$B$BПодуй в боевой рог Непреклонных рядом со знаменем Альянса. Это привлечет внимание Уртрака. Но рог призовет и души тех, кто пал здесь в сражении много лет назад.', 'Подуйте в боевой рог Непреклонных рядом со знаменем Альянса. Убейте Уртрака и возвращайтесь к Альтену Историку на Заставу Хребтолома.', 'Я рад слышать, что Непреклонные присоединились к тебе в битве. Я предполагал, что они придут на звук своего старого боевого рога, но не был в этом уверен. Возможно, мы дали им насытиться местью, которой они так жаждали.$B$BО твоей победе над Уртраком необходимо доложить командиру Хогарту в оружейную экспедиции. Он должен знать, чем ты рисковал ради нас.', 'Ты протрубил в рог, найденный в осадной башне? Это нужно сделать как можно скорее. Кто знает, когда еще Непреклонные пригодятся Траллмару.', NULL, NULL, 'Уртрак убито', 'Боевой рог непреклонных (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10251, 'Великий замысел господина?', 'Вчера вечером у нас побывала парочка дренеев. Они как-то прознали, что у нас есть эта книга, и великодушно предложили избавить нас от такой обузы.$B$BНе в наших обычаях интересоваться планами чужаков, но тот, что помоложе, все повторял что-то про \"великий замысел господина\", что бы это ни значило.$B$BКогда мне платят, я вопросов не задаю. Они дали нам кучу золота, а мы им – книгу.$B$BОн говорил, они живут где-то в Награнде, в старой заброшенной оружейной, к северу от Телаара.', 'Найдите Нитрина Сведущего в Заброшенной оружейной в Награнде. ', 'Я видел, к чему все идет, но предпочитал не обращать внимания.$B$BС каждым днем влияние Легиона все усиливается... даже в наших краях.$B$BЕсли бы я знал... Если бы я знал, что мой мальчик свяжется с демонами... Они пообещали ему силу и дали вкусить ее... Этого ему хватило.$B$BИ вот, книга утеряна для нас. Теперь она у Левиксуса. Об его планах известно только мне и его темному владыке.$B$BО странник, я не знаю, следуешь ли ты путем добра, но того, кто служит демонам, надо остановить любой ценой!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10252, 'Посмотри в глаза мертвым', 'Сбылись наши самые худшие опасения. Левиксус стоит над руинами Аукиндона и читает книгу мертвых. Он призывает умерших по именам, и с помощью древнего демонического ритуала подчиняет своей воле их злосчастные души. Если его не остановить, он призовет под свои знамена души всех, кто когда-либо умер в Аукиндоне!$B$BНо... Сначала тебе нужно подготовиться. Невозможно сражаться с тем, кого ты не в состоянии даже увидеть.$B$B<Нитрин дает вам пергамент.>$B$BДостань необходимые компоненты, чтобы я смог изготовить нужное снадобье. Оно раскроет твой разум и позволит узреть мир духов.', 'Принесите Нитрину из Заброшенной оружейной Награнда 1 глаз горного гронна, 1 безупречный клюв большого вертуха и 1 сальник старого копытня.', 'Странник... Я не сказал тебе всей правды. Как только ты выпьешь это зелье, ты отныне и навсегда обретешь способность видеть мир духов. Это питье давали жрецам мертвых Аукиндона во время инициации. Многие после этого сходили с ума... Видеть мертвых – это тяжелое испытание для живущего.$B$B<Нитрин подносит зелье к вашим губам.>$B$BТы не боишься?', 'Армия Левиксуса разрастается с каждой секундой. Тебе следует торопиться!', NULL, NULL, 'Глаз горного гронна', 'Безупречный клюв большого ветруха', 'Сальник старого копытня', 'Рекомендуемое количество игроков: 3');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10253, 'Левиксус Призыватель Душ', 'А теперь ступай, $N. Ты найдешь Левиксуса на самом верху руин Аукиндона. Лучше всего заходить с юга Костяных пустошей. Левиксус поднял целый смерч душ и стоит в самом его центре.$B$BУбей его и забери книгу мертвых. И как только эта проклятая книга окажется у тебя, немедленно уничтожь ее! Уничтожь, чтобы подобное зверство никогда больше не повторилось.', 'Убейте Левиксуса и заберите у него Книгу Мертвых.Отнесите Книгу Рамдору Безумному, который находится неподалеку от входа в Аукенайские гробницы в Аукиндоне.Вы ведь с ним об этом договаривались, помните?', 'Старый дреней велел тебе уничтожить книгу. Так почему ты этого не сделал, а?$B$B<Рамдор бросает на вас мрачный взгляд.>$B$BА-а... Вот в чем дело. Может быть, ты и жадный, зато честный.$B$BЯ же, надо сказать... Я солгал, чтобы завладеть этой книгой. Понятия не имею, где эти бедные духи хранят свои сокровища, а если знал бы – все равно не сказал. Впрочем, у меня найдется кое-что для тебя. Возможно, кое-что весьма стоящее. Не бойся, ты не останешься без награды.$B$BКстати, добро пожаловать в нашу компанию!$B$B<Рамдор указывает на духов.:', 'Кто ты, и что тебе надо? А-а... Я тебя помню...', NULL, NULL, '\"Книга мертвых\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10254, 'Командир армии Данат', '<Маршал Исилдор сплевывает в пыль.>$B$BЧто ж, пришло время платить по счетам. Немедленно отправляйся в крепость с докладом к командиру армии Данату Троллебою.$B$B<Маршал Исилдор отдает вам честь.>$B$BВо имя Альянса!', 'Доставьте по приказу маршала Исилдора донесение командиру армии Данату Троллебою в Оплот Чести.', 'Добро пожаловать, брат. Я рад тебя видеть. Мое имя Данат, я предводитель Сынов Лотара и командир армии этой крепости.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10255, 'Проверка противоядия', 'Я думаю, мы можем использовать эту кровь для создания противоядия. Не смотри на меня так, будто я сошла с ума!$B$BЭто очень распространено в природе. Часто противоядие является производным от яда. Именно это я сейчас и попытаюсь проверить.$B$BЕсли мы освободим вепрей от демонического влияния, это снизит их агрессивность и, возможно, поможет нам понять, как помочь остальным животным.', 'Введите кенарийское противоядие крупному зловепрю и пронаблюдайте за результатом. После проведения эксперимента возвращайтесь к Тие Рыжей Гриве на Кенарийскую заставу на полуострове Адского Пламени.', '*Глаза Тии расширяются по мере того, как вы описываете результаты эксперимента*$B$BНо как это могло случиться? Я уверена, что приготовила противоядие правильно!$B$BОно срабатывало и с паучьим, и со змеиным ядом, почему же на этот раз дало сбой? Возможно, все дело в специфике Запределья, $N. Нужно сообщить о результатах всем моим соратникам.', 'Как прошел эксперимент?', NULL, NULL, 'Дать противоядие', 'Кенарийское противоядие (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10256, 'Найти Хранителя Ключей', 'Сейчас, несколько запоздало, я полагаю, что должен был понимать, насколько сильна магия Кель\'таса. Он всегда был талантливым магом, но я никогда не видел мощи, подобной той, которую он применил во время нападения на эту башню. $B$BОграждающая магия не дает мне рассмотреть силу, поддерживающую ее, однако тебе эта ограда не будет препятствием.$B$BОднако тебе требуется фокусировка. По равнинам к западу от манагорна Даро бродит великан-кристаллоноситель по имени Камнегор. Один из его кристаллов послужит превосходным средством сосредоточения взгляда.', 'Выследите Камнегора и заберите у него кристальное средоточие. Вернитесь к Аметистовой башне и используйте кристальное средоточие Камнегора поблизости от шара верховного мага Варгота для того, чтобы обнаружить, у кого хранятся ключи от проклятия башни.', '<Вы описываете результат наблюдения.>$B$BГоворишь, командир Сараннис? Хмм...$B$BОна одна из советников Кель\'таса, но определенно не маг. Я помню ее – она была среди тех, кто напал на деревню Кирин\'Вар. Думаю, твое прозрение оказалось верным, $N. Она не поддерживает проклятье сама, но хранит ключи от него.', 'Что открывается твоему взору?', NULL, NULL, 'Узнайте, у кого хранятся ключи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10257, 'Захват краеугольного камня', 'Меня не удивляет, что Кель\'тас отдал ключ от тюрьмы в руки такой, как командир Сараннис. Принц Кель\'тас горд, но он не дурак.$B$BДля того чтобы уничтожить это проклятье раз и навсегда, тебе следует войти в Крепость Бурь и забрать ключ.$B$BТолько после того, как ключ будет уничтожен, я вновь обрету свободу.', 'Проникните в Ботанику в Крепости Бурь и заберите ключ у командира Сараннис. Отнесите ключ верховному магу Варготу в Аметистовую башню.', '<Когда вы протягиваете верховному магу Ключ-камень, глаза мага озаряются светом.>$B$BВеликолепно! Хотя я видел немногое из того, что случилось с Фаралоном, я не уверен, что хочу оказаться снаружи. Но это лучше, чем быть запертым здесь до конца дней своих.', 'Тебе удалось добыть краеугольный камень?', NULL, NULL, 'Ключ', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10258, 'Честь Павших', 'Командир Оружейной Хогард находится в восточной башне. Пойди, расскажи ему о победе над Уртраком. Может, он будет к тебе благосклонен. Хотя не исключаю, что попытается пожрать твою душу. С такими духами, как этот, трудно угадать наверняка.$B$BНепреклонные так и не согласились сотрудничать с нами, так что, скорее всего, попытаются убить тебя. Будь $gосторожен:осторожна:, $N.', 'Явитесь к командиру Хогарду, который находится в оружейной экспедиции.', 'Когда-то давно мы потерпели поражение от орков Скверны. Убив Уртрака, ты вернул нам хотя бы часть утраченной славы.$B$BПрими в награду это оружие. Обнажи его, когда будешь сражаться с нашими злейшими врагами, и тогда те из нас, кто свободен от проклятья, придут тебе на помощь.$B$BПока ты еще не ушел, – погибшие во время осады тоже хотят поблагодарить тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10259, 'Битва в Проломе', 'В портале неустанно кипит бой! Серебряный Рассвет отчаянно сражается - и если мы проиграем, то демонический огонь уже не остановить.$B$BПомоги нам, $N. Войди в пролом и протяни руку помощи нашим братьям и сестрам. Помоги остановить этот темный прилив! Серебряному Рассвету - и всему миру - нужна твоя сила!', 'Убейте 6 вторгшихся стражей Скверны и затем вернитесь к посланнику ордена Серебряного Рассвета Праудвелл.', 'Благодарю тебя, $N. Среди хаоса битвы герои подобны яркому свету во тьме. И твой свет воистину сияет!', NULL, NULL, NULL, 'Вторгшийся страж Скверны убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10260, 'Пустолог Медноклеппер', 'Твой путь, должно быть, пролегал по главному мосту, ведущему в Пустоверть от Острогорья. Не довелось ли тебе увидеть там пустолога Медноклеппера, работающего над всяким дурацким оборудованием?$B$BСтранно... Я ожидал от него рапорта уже некоторое время назад. Должно быть, он забыл. Ты ведь знаешь, каковы эти \"ученые\". $B$BОтправляйся обратно к мосту и найди пустолога. Не слушай никаких его объяснений, просто получи с него рапорт для меня.$B$BСпасибо!', 'Поговорите с Пустологом Медноклеппером у моста, ведущего от Пустоверти к Острогорью.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10261, 'Разыскивается: аннигиляторный сервопривод!', 'РАЗЫСКИВАЕТСЯ: 1 аннигиляторный сервопривод для замены сломанного в моем спектральном анализаторе Длинношеего.$B$BТы и твои друзья могут проверить, нет ли запасных сервоприводов у эльфов крови в манагорне Б\'наар к западу отсюда. Кажется, у них валялись там несколько волшебных уничтожителей. $B$BПожалуйста, доставь сервопривод в хорошем состоянии Папаше Колесуну в Зону 52.', 'Заберите аннигиляторный сервопривод и доставьте его Папаше Колесуну в Зону 52 Пустоверти.', 'Ура! Ты знаешь, как трудно раздобыть эти штуки? Тут у нас не существует регулярной поставки запчастей.$B$BВот что я скажу – в качестве платы можешь взять что-нибудь из моей коробки с хламом. Я уверен, там ты найдешь для себя что-нибудь полезное. А если нет, то продай.$B$BНу ладно, давай, я заберу у тебя эту штуку и встрою в свой спектральный анализатор Длинношеего прежде, чем неисправный сервопривод взорвется!', 'Надеюсь, ты здесь из-за того объявления о розыске, которое я вывесил!', NULL, NULL, 'Аннигиляторный сервопривод', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10262, 'Груда духов Астрала', 'Есть еще одно дело, в котором мне нужна твоя помощь.$B$BГруппа духов Астрала, известная как Заксис, разорвала свои отношения с Консорциумом и занимается бизнесом в собственных интересах. Они даже заключают сделки с эльфами крови из Ярости Солнца. Этого нельзя допустить!$B$BЯ проник в их отряд в Груде на юге отсюда. Но после того, как я убил их вожака, мне пришлось бежать сюда, в Зону 52.$B$B$C, отправляйся туда и принеси мне их знаки отличия. Конечно же, не все они носят такие знаки, поскольку эти типы очень трусливы.', 'Соберите 10 знаков отличия братства Заксис и принесите их ловчему Пустоты Кай\'джи, находящемуся в Зоне 52 в Пустоверти.', 'Эти знаки отличия – хорошее начало.$B$BК несчастью, за время твоего пребывания в Груде еще один мой агент в Заксис сообщил мне, что астральный налетчик Несаад все еще жив!', 'Дело сделано? Удалось ли тебе стереть с лица Запределья этих негодяев из братства Заксис и достать их знаки отличия?', NULL, NULL, 'Знак отличия братства Заксис', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10263, 'Содействие Консорциуму', 'Наару города Шаттрат пытаются донести до Консорциума свою точку зрения.$B$BХорошо еще, что деловые отношения между духами Астрала и эльфами крови здесь, в Пустоверти, в последнее время разладились.$B$BВ городе находится представитель Консорциума ловчий Пустоты Кай\'джи, который недавно попал в неприятности по вине шайки астральных духов-изменников. Как представитель Алдоров, я хотел бы попросить тебя помогать ему во всем, в чем только можно.', 'Поговорите с ловчим Пустоты Кай\'джи в Зоне 52 в Пустоверти.', 'Привет тебе, $R.$B$BНе возьмешься ли ты за довольно важную миссию по изъятию имущества?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10264, 'Содействие Консорциуму', 'Наару города Шаттрат пытаются донести до Консорциума свою точку зрения.$B$BХорошо еще, что деловые отношения между эфириалами и эльфами крови здесь, в Пустоверти, в последнее время разладились.$B$BВ городе находится представитель Консорциума ловчий Пустоты Кай\'джи, который недавно попал в неприятности по вине шайки астральных духов-изменников. Как представитель Альдора, я хотел бы попросить тебя помочь ему во всем, в чем только можно.', 'Поговорите с ловчим Пустоты Кай\'джи в Зоне 52 в Пустоверти.', 'Привет тебе, $R.$B$BНе возьмешься ли ты за довольно важную миссию по изъятию имущества?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10265, 'Добыча артефакта для Консорциума', 'Наш предводитель, принц нексуса Харамад, поставил передо мной задачу: добыть кристаллический артефакт из руин Арклона на юго-востоке отсюда.$B$BЭто старинные руины дренейских построек. К несчастью как для меня, так и для здешних гоблинов, Пылающий Легион тоже решил заняться там раскопками.$B$BЕсли хочешь помочь мне, отправляйся в руины и забери кристаллический артефакт у повелителя ужаса по имени Пентатарон.', 'Заполучите кристаллический артефакт Арклона и верните его ловчему Пустоты Кай\'джи, находящемуся в Зоне 52 в Пустоверти.', 'Дай-ка я взгляну.$B$BХмм, не похоже, что в нем есть что-то особенное. Я сомневаюсь, что это именно то, что нужно, хотя, если судить по твоему описанию действий Пылающего Легиона в руинах, они тоже ищут нечто особенное.$B$BБудем надеяться, что предмет их поисков – не тот кристалл, который так нужен принцу.', 'У меня такое впечатление, что принц ищет вполне определенный кристалл, но какой именно?$B$BУдалось ли тебе забрать артефакт у повелителя Ужаса?', NULL, NULL, 'Кристалл-артефакт Арклона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10266, 'Запрос о содействии', 'Во время твоего пребывания в руинах Арклона я получил запрос о содействии от одного из наших представителей, отправленных на задание. Похоже, у Консорциума возникли затруднения с изъятием у эльфов крови собственности, за которую те отказываются платить. $B$BПожалуйста, отправляйся на восток от Зоны 52 и по мосту перейди на следующий остров. Ты найдешь моего коллегу Гаруджа на заставе внутри заповедника \"Срединные земли\" в Пустоверти.', 'Найдите Гаруджа и предложите ему свои услуги. Он находится на заставе внутри заповедника \"Срединные земли\" в Пустоверти.', 'Да, это правда. Эльфы крови отказались платить за еще одну партию товаров, только что доставленную им. $B$BКак сообщил тебе ловчий Пустоты Кай\'джи, я надеюсь, что ты сможешь помочь мне в этом вопросе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10267, 'Изъятие по праву', 'Похоже, нашим деловым отношениям с эльфами крови наступает конец. Несколько дней назад в манагорне Даро им была передана большая партия геодезического снаряжения. Они отказались платить за нее.$B$B$N, я хотел бы попросить тебя нанести визит эльфам крови в манагорн Даро. Похоже, у них там какие-то неприятности в связи с нашествием мана-тварей, так что воспользуйся этим положением. $B$BМне все равно, что случится с ними, но мне очень хотелось бы вернуть назад нашу собственность.', 'Заберите 10 ящиков с геодезическим снаряжением и верните их Гаруджу, находящемуся на заставе внутри заповедника \"Срединные земли\" в Пустоверти.', 'Ну, лично я рад, что это маленькое дельце уже улажено. Припомнить не могу, когда еще Консорциуму приходилось иметь дело с такими невоспитанными и вероломными существами.$B$BА вот тебе, $N, похоже, можно доверять. Быть может, ты не против оказать мне еще одну услугу?', 'Удалось ли тебе изъять геодезическое снаряжение, за которое нам задолжали эльфы крови?', NULL, NULL, 'Ящик с геодезическим снаряжением', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10268, 'Аудиенция у принца', 'Принц нексуса Харамад сообщил мне, что он заинтересован в том, чтобы его имущество немедленно было возвращено ему лично. Я буду очень рад, если ты возьмешься доставить ему это имущество.$B$BЭто великая честь – получить аудиенцию у принца нексуса, и я уверен, что он будет чрезвычайно заинтересован в том, чтобы услышать повествование о твоих приключениях здесь, в Пустоверти.$B$BЕго залу можно отыскать на верхнем уровне Штормовой Вершины к северу отсюда. Он часто присутствует там в виде голографической проекции, к которой ты можешь обратиться.', 'Доставьте геодезическое снаряжение к проекции принца нексуса Харамада в Штормовую Вершину в Пустоверти.', 'Приветствую тебя в Штормовой Вершине, $C. Наслаждайся гостеприимством Консорциума.$B$BСнаряжение ты можешь положить где угодно. Подозреваю, что довольно скоро ты вновь заберешь его.', 'Подойди.', NULL, NULL, 'Геодезическое снаряжение (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10269, 'Триангуляция: точка первая', 'Есть еще одна причина для изъятия геодезического снаряжения. Это кристалл из дренейской легенды, который очень важен для меня.$B$BГоворят, что кристалл дарует своему носителю сверхъестественную силу! Но существует опасность, что его добудут другие - а именно Пылающий Легион.$B$B$N, возьми это снаряжение и используй его, чтобы найти первую точку триангуляции. Мы знаем, что она должна находиться где-то к востоку отсюда поблизости от манагорна Ультрис.$B$BПосле этого отметься у моего агента, дельца Хаззина, на острове манагорна Ультрис.', 'Используйте триангуляционный прибор, чтобы найти путь к первой точке триангуляции. Как только найдете точку, сообщите ее местонахождение дельцу Хаззину, находящемуся на заставе Протектората на острове манагорна Ультрис в Пустоверти.', '<Делец Хаззин понижает голос до шепота.>$B$BА, я знаю о твоей миссии. Она очень важна для принца нексуса Харамада!$B$BТеперь, когда мы знаем местонахождение первой точки триангуляции, тебе следует побыстрее отыскать вторую!', 'Привет тебе, путешественник. Тебе нужно приобрести у Хаззина какие-то товары?', NULL, NULL, 'Триангуляционный прибор (Прилагается)', 'Исследовать локацию', 'Найдите первую точку триангуляции.', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10270, 'Нескромное предложение', 'Просто взглянув на твое лицо, $r, я могу сказать, что ты ценишь хорошую выгоду.$B$BЯ составил себе репутацию как торговец экзотическими товарами, и сейчас я намереваюсь начать новое предприятие.$B$BМне нужен надежный субподрядчик для доставки товаров с Небесной гряды.$B$BСначала тебе нужно подзарядить площадку телепорта. Запасной силовой пакет есть у входа в шахту Зеон, расположенного на южной стороне манагорна Ультрис. Там действует Протекторат, так что тебе, возможно, удастся следовать их индикаторам ради собственных целей.', 'Найдите аккумулятор для телепортатора и отнесите его к площадке астрального телепорта на Небесной гряде. Активируйте площадку и отдайте аккумулятор проекции торговца ветром Марида, чтобы он мог установить его.', 'Эта энергетическая ячейка подойдет для наших целей. Как только начнется оборот денег, мы дополнительно улучшим ее.$B$BНу, довольно. Каждый момент, проведенный за обсуждением, приводит к потере прибыли.', 'Как насчет того, чтобы обсудить деловые вопросы, $N?', NULL, NULL, 'Аккумулятор телепортатора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10271, 'Деловая активность', 'Как тебе, несомненно, удалось заметить, этот регион кишит драконами Пустоты на разных стадиях роста. Все драконы Пустоты, молодые и старые, содержат эссенцию, которая очень нужна К... одному моему клиенту.$B$BМало кто желает рисковать жизнью для сбора этой эссенции, так что это дело зарезервировано за нами. Можешь начать с любого дракона поблизости, лишь бы поставки начались немедленно – это очень важно. Возвращайся, как только добудешь первую партию.', 'Соберите 8 единиц эссенции дракона Пустоты, затем возвращайтесь в зону площадки астрального телепорта. Эссенцию дракона Пустоты можно получить из старых или молодых драконов Пустоты.', 'И подумать только, этот коварный дух Астрала собирался продавать эту эссенцию эльфам Крови, словно какие-нибудь сласти...', 'Я уверен, у тебя множество вопросов, но все ответы будут получены в должное время.', NULL, NULL, 'Сущность дракона Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10272, 'Многообещающее начало', 'Мы здесь для того, чтобы расследовать, правдивы ли слухи о странной породе драконов, которые, возможно, являются потомками самого Смертокрыла. Однако это явно не обычные черные драконы.$B$BМы узнаем больше, если у нас будет возможность изучить их яйца. Их ненависть к моему племени велика, так что я не могу подобраться достаточно близко, чтобы собрать яйца. Ты не согласишься мне помочь?', 'Соберите 15 яиц драконидов Пустоты, затем возвращайтесь к Тири и Джораду на Небесную гряду.', 'Это прекрасно подойдет, $N. Спасибо за помощь нам.$B$BОднако прежде, чем мы сможем продолжить, нам нужно обратиться к другому вопросу.', 'Удалось ли тебе набрать яиц?', NULL, NULL, 'Яйцо дракона Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10273, 'Пустые хлопоты', 'Твой бывший наниматель, торговец ветром Марид, должно быть, плюется оттого, что ты теперь помогаешь нам. Благодаря своей проекции я вижу его странников хаоса, шныряющих по этому региону и надеющихся выследить нас.$B$BДо сих пор нам удавалось ускользать от них, но с Маридом нужно что-то делать, прежде чем проблема станет еще более серьезной.$B$BЕсли твои впечатления относительно Марида верны, он сделает почти все, чтобы обезопасить поставки своего товара. Возвращайся к нему и сообщи о своей готовности заключить сделку. Вымани его и убей.', 'Поговорите с торговцем Ветром Маридом и выманите его из торгового поста. Покончите с ним, затем вернитесь к Тири и Джораду на Небесную гряду.', 'Теперь, когда с этим назойливым эфириалом покончено, мы можем сосредоточить наши усилия на исследовании драконов Пустоты. У меня была возможность изучить их яйца, и я сделала несколько открытий.', NULL, NULL, NULL, 'Марид Торговец ветром убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10274, 'Безопасность Небесной гряды', 'Драконы Пустоты отличаются тем же свирепым характером, что и их предки – черные драконы, но есть в них что-то непостижимое. Они быстро созревают и взрослеют благодаря той странной энергии, которая создала их вид во время уничтожения Дренора.$B$BМне еще очень многое нужно о них узнать, но я полагаю, что эта энергия может быть использована моим собственным родом. Если бы мы сместили вожака этих драконов, Вераку, показав свое превосходство, мы смогли бы подчинить своей власти всех остальных представителей их вида.', 'Используйте вызов синих драконов, чтобы вызвать на бой Вераку, живущего на южном склоне Небесной гряды. Победите его и возвращайтесь к Тири и Джораду, ожидающим на Небесной гряде.', 'Хорошая работа, $N, поистине хорошая. Сначала драконы Пустоты не примут в свою среду синего дракона, однако со временем, при жесткой демонстрации моей власти, они придут под мое крыло. Они разъединены, разбросаны, у них нет решительного лидера. Мы должны быть бдительными, чтобы не дать им пасть под натиском злых сил. Необходимо постоянно следить за ними.', 'Удалось ли тебе вызвать на бой Вераку и победить его?', NULL, NULL, 'Убейте Вераку', 'Рог вызова Синих Драконов (Прилагается)', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10275, 'Триангуляция: точка вторая', 'Я перенастроил триангуляционный прибор, используя те сведения, которые тебе удалось добыть при поиске первой точки. Воспользуйся этим прибором точно так же, как и в первый раз, чтобы найти вторую точку.$B$BВсе, что я могу тебе сказать – это то, что вторая точка находится где-то далеко к западу отсюда. $B$BКак только засечешь ее, поговори с торговцем ветром Тулуманом – это еще один агент принца нексуса. Он изображает торговца оружием в маленьком торговом посту около моста, ведущего на тот остров, где размещается манагорн Ара.', 'Используйте триангуляционный прибор, чтобы найти путь ко второй точке триангуляции. Как только найдете точку, сообщите ее местонахождение торговцу ветром Тулуману, находящемуся в лагере Тулумана, по другую сторону моста, ведущего от острова манагорна Ара в Пустоверти.', 'Просто прекрасно. Принц будет доволен!$B$BТеперь у нас есть вторая точка, благодаря чему мы сможем найти третью, а потом – приблизительное местоположение кристалла!', 'Желаешь что-нибудь купить или продать?', NULL, NULL, 'Триангуляционный прибор (Прилагается)', 'Исследовать локацию', 'Найдите вторую точку триангуляции.', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10276, 'Полный треугольник', 'Если брать в расчет данные с первой и второй точки, я уверен: кристалл находится на вершине руин Фаралона к северо-востоку отсюда.$B$BК несчастью, данные указывают, что кристалл движется, то есть он уже обнаружен и, вполне вероятно, обнаружен Пылающим Легионом!$B$BНа всякий случай я советую тебе взять с собой друзей.$B$BУбей демона, у которого находится этот кристалл, и возвращайся к принцу нексуса Харамаду.', 'Заберите кристалл Ата\'мала и передайте его проекции принца нексуса Харамада, находящейся в Штормовой Вершине в Пустоверти.', 'Это превзошло мои самые смелые ожидания, я не думал, что тебе удастся забрать этот кристалл!$B$BИ ты отдаешь его мне? Ты понимаешь, какую силу он таит?$B$BТвое бескорыстие поистине впечатляюще и непревзойденно, $N! Твое поведение заставляет меня лучше думать о разумных существах.', 'Вновь приветствую тебя. Как продвигается поиск кристалла?', NULL, NULL, 'Кристалл Ата\'мала', 'Исследовать локацию', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10277, 'Пещеры Времени', 'Приветствую тебя, $N. Пожалуйста, следуй за хранительницей. Она покажет тебе пещеры, и ты... хотя бы начнешь понимать, что происходит.', 'Андорму попросил вас пройти по пещерам вместе с хранительницей времени.', 'Надеюсь, теперь ты составил себе представление о том, чего от тебя ожидают.', 'Возвращайся не раньше, чем начнешь понимать, как здесь все устроено.', NULL, NULL, 'Изучите пещеры Времени.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10278, 'Астральные провалы', 'Когда-то давно я бродил по Запределью, ища истину среди пустоты. А теперь я стар и слаб. Ты мне поможешь?$B$BЯ должен изучить секреты демонов Бездны. Отыщи Искривленные поля к западу отсюда. Еще западнее оружейной экспедиции лежит темное место на самом краю бездны, где истончаются время и пространство. Запусти там мой нестабильный генератор астральных провалов и создай провал. Собери пыль Пустоты с тех созданий, которые появятся.', 'Используйте нестабильный генератор астральных провалов на Искривленных полях. Соберите три горсти пыли Пустоты с нестабильных демонов Бездны и возвращайтесь к Огафу Безумному на заставу Хребтолома.', 'Невероятно. Тебе удалось прикоснуться к самой пустоте! $N, ты спас дело всей моей жизни. Но, если ты и правда хочешь помочь мне, мы должны сделать еще многое и многое.', 'Ты догадался, как запустить мой прибор? Я думаю, генератор заработает, если расположить его поближе к бездне.', NULL, NULL, 'Пыль Пустоты', 'Нестабильный генератор астральных провалов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10279, 'Логово господина', 'А, $N. Мы тебя ждали. Сейчас один из моих братьев доставит тебя к нашему господину. Он ожидает тебя внизу...', 'Поговорите с Андорму в пещерах Времени.', 'Мы должны подготовить тебя к грядущим сражениям...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10280, 'Специальный груз в город Шаттрат', 'Я всегда держу свое слово, $N. Тебе поистине удалось произвести на меня впечатление.$B$BЯ намереваюсь дать тебе кристалл Ата\'мала для передачи наару. Я прошу тебя доставить его им – твой героизм делает это вполне возможным.$B$BМожешь использовать мой личный телепорт, чтобы переправиться прямо в город Шаттрат. Просто пройди через него, и окажешься там.$B$BОтдай кристалл наару по имени А\'дал, обитающему на террасе Света. Пусть несут тебя попутные ветры торговли!', 'Передайте кристалл Ата\'мала А\'далу на террасе Света в городе Шаттрат. ', 'Тебе удалось обрести Песню Духа! Это кристалл Ата\'мала, который пророк Велен оставил на сохранение своему народу, прежде чем отправиться в свою злосчастную миссию в Экзодар.$B$BКак ни странно, он не предвидел, что кристалл попадет в руки Пылающего Легиона, пусть и на короткое время.$B$BА может быть, и нет? Может быть, он предвидел все это и оставил кристалл здесь, чтобы ты мог забрать его и доставить ко мне?$B$BЯ чувствую, что истина именно такова. Поистине велик твой героизм, $N!', '<Музыкальный перезвон речи наару наполняет ваш разум.>$B$BЯ чувствую, что у тебя с собой вещь великой силы, $R. Что ты принес мне?', NULL, NULL, 'Кристалл Ата\'мала (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10281, 'Формальное представление', 'Приветствую тебя, $N. Не надо тревожиться. Это лишь проекция моей нынешней формы. Это единственный способ, при котором я и мой товарищ можем нести стражу, ничем не выдав себя.$B$BДух Астрала Марид, который беседовал с тобой - немногим лучше, нежели обманщик под личиной законопослушного торговца. Может быть, ты подумаешь о том, чтобы работать на меня, а не на него? Моя цель здесь - побольше узнать о необычном виде драконов, обитающих в этих горах. Встреться со мной на северной оконечности этой горной цепи, и мы обсудим этот вопрос.', 'Найдите Тири на северной оконечности Небесной гряды и поговорите с ней.', 'Мое имя Тиригоса из рода Малигоса, но большинство называют меня Тири. Мой товарищ – паладин Джорад Мейс.$B$BСлухи об этих странных драконах уже распространились достаточно широко, и я боюсь, что очень многие поспешат воспользоваться этим ради выгоды, не осознавая истинной природы того, с чем имеют дело. С твоей помощью мы надеемся понять суть этих созданий, прежде чем другие обнаружат их присутствие.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10282, 'Старый Хилсбрад', 'Дорога времени, лежащая к западу, приведет тебя в прошлое Хилсбрада – на семь лет назад, если быть точным.$B$BНекие странные силы пытаются предотвратить побег Тралла из крепости Дарнхольд. Они хотят, чтобы он остался там навсегда.$B$BЕсли Траллу не удастся вырваться на свободу, настоящее этого мира непоправимо изменится.$B$BСобери отряд таких же, как ты, искателей приключений и отправляйся в старый Хилсбрад по тропе времени. Там тебя будут ждать двое наших агентов.$B$BКогда прибудешь в Хилсбрад, обязательно поговори с Эрозионом.', 'Отправьтесь по тропе времени в старый Хилсбрад и поговорите с Эрозионом.', 'То, чего мы больше всего боялись, может случиться уже очень скоро. Силы, которые вмешиваются в ход времени, – это новый клан драконов, что именуют себя драконами Бесконечности. Мы не знаем, откуда они появились и почему они разрушают наши линии времени.$B$BНа этом участке времени они похитили Тарету Фокстон, дочь Таммиса Фокстона. Он служит секретарем у Аделаса Блэкмура, правителя Дарнхольда и надзирателя лагерей для военнопленных в Азероте.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10283, 'План Тареты', 'Только благодаря Тарете Тралл сумел выжить. Она воспитала его и сделала тем, кто он есть.$B$BИменно Тарета придумала первоначальный план, как помочь Траллу бежать из Дарнхольда.$B$BНо драконы Бесконечности захватили ее и сейчас держат в плену в Мельнице Таррен. Без нашей помощи Траллу вряд ли удастся сбежать. Я дам тебе зажигательные бомбы: подожги ими бараки на выселках в Дарнхольде. Потом отыщи юного Тралла – его держат в подземной темнице.', 'Проберитесь в крепость Дарнхольд и заложите пять зажигательных бомб возле бочек внутри каждого из бараков на выселках. Используйте упаковку зажигательных бомб, полученных от Эрозиона.После того как подожжете бараки, разыщите Тралла в подземной темнице.', 'Тебя прислала Тарета? То есть теперь у нее новый план? Ну хорошо...', 'Кто ты?', NULL, NULL, 'Бараки горят', 'Упаковка зажигательных бомб', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10284, 'Побег из Дарнхольда', 'Ты видишь во мне только мальчишку, $gчужак:незнакомка:, но у этого мальчишки есть свои сокровенные мечты. Я знаю, что нужно моему народу. В один прекрасный день он сбросит своих притеснителей и встанет с колен. Мы порвем свои цепи и выкуем новую Орду, закалив ее в пламени мятежа. Я обещаю тебе, $gчужеземец:незнакомка:: если мы выйдем отсюда живыми, ты получишь щедрую награду за свой самоотверженный поступок. Я буду искать тебя... и непременно найду.$B$B<Тралл кивает.>$B$BКак только будешь $gготов:готова: идти, дай мне знать.', 'Когда вы будете готовы идти, сообщите об этом Траллу. Помогите ему бежать из крепости Дарнхольд, освободить Тарету и исполнить свое предназначение.После этого возвращайтесь к Эрозиону в Старый Хилсбрад.', 'Тебе удалось совершить невозможное, $N. К сожалению, юный вождь этого не запомнит. В его памяти должны остаться только те события, которые случились бы, не будь искажения линии времени... Андорму ждет тебя в логове нашего господина.', NULL, NULL, NULL, 'Предназначение Тралла исполнено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10285, 'Возвращение к Андорму', 'Эта линия времени восстановлена, и нападение драконов Бесконечности на Хилсбрад провалилось.$B$BНемедленно возвращайся к Андорму. Он ждет тебя в логове нашего господина.', 'Возвращайтесь к маленькому Андорму в Пещеры Времени.', 'Прими этот дар от бронзовых драконов. Он поможет тебе в путешествиях во времени.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10286, 'Тайна Арелиона', 'Да этот дневник ничего общего не имеет с научными изысканиями! Арелион там в деталях описывает свои развлечения с одной молоденькой эльфийкой крови. $gВидал:Видала: придурка?$B$BК сожалению, он не написал, кто же была эта потаскушка. У Арелиона был друг, Аледис. Найди его и выясни, с кем же это Арелион мог развлекаться.$B$BЯ видела, как Аледис отправлялся из Соколиного дозора в Зангартопь. Дорога в Зангартопь уходит от северного выхода из города.', 'Расспросите магистра Аледиса, которого в последний раз видели отправляющимся из Соколиного дозора в Зангартопь, по требованию магистра Каринды.', 'Я все расскажу, $C. Опусти оружие, у меня и так проблем хватает.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10287, 'Кем оказалась любовница', 'Я друг Арелиона, но не собираюсь положить за него жизнь. Его любовницей была Виера Шепот Солнца.$B$BТеперь ступай, докладывайся этой гарпии, жене Арелиона. Ну узнает она, и что дальше?', 'Возвращайтесь к магистру Каринде в Соколиный Дозор, что на Полуострове Адского Пламени.', 'Виера Шепот Солнца? Эта маленькая дрянь?$B$BНу я ей покажу, как переходить мне дорогу!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10288, 'Прибытие в Запределье', 'Чтобы долететь до Оплота Чести, тебе надо будет поговорить с Амишем Громовым Молотом, он находится в 30 шагах отсюда к югу. Когда прибудешь в Оплот, встреться с маршалом Исилдором. Я подготовил донесение, в котором подробно описал, что у нас происходит. Отдай донесение ему и доложи, что $gготов:готова: к дальшейшему несению службы.$B$BЭто приказ. А теперь, $gсвободен:свободна:, солдат! Я не сомневаюсь, что ты страстно желаешь помогать нам в сражениях с демонами, но в Оплоте Чести ты $gнужен:нужна: больше, чем здесь.', 'Доставьте донесение Дарона Амишу Громовому Молоту по приказу командира Дарона у Темного портала на полуострове Адского Пламени.', 'Донесение в Оплот Чести? Без проблем. Мой грифон доставит тебя туда в целости и сохранности.', 'Я видел, что с тобой говорил Дарон. Должно быть, важное дело.', NULL, NULL, 'Донесение Дурона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10289, 'Путешествие в Траллмар', 'Когда будешь $gготов:готова:, я призову виверну, которая отнесет тебя в Траллмар. По прибытии передай донесение Ориона генералу Кракорку.$B$BЛок\'тар огар, $N, удачи тебе.', 'Долетите на ветрокрыле Влагги Легкоперой в Траллмар. Доставьте донесение Ориона генералу Кракорку.', 'Я соберу все доступные резервы и отправлю их к Темному порталу, на помощь Ориону. Легион не скоро забудет боевой клич Орды! Что касается тебя, $N, то ты оказал Траллмару великую услугу. Я надеюсь, ты сможешь помочь нам и здесь... Если у тебя хватит ума остаться в живых, конечно же...', 'Донесение Ориона? Давай сюда, живо!$B$B<Нахмурившись, генерал Кракорк просматривает изорванные бумаги.>$B$BПроклятье, именно этого мы и боялись! Ориона и его армию могут в любой момент отбросить!', NULL, NULL, 'Донесение Ориона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10290, 'В поисках фаралита', 'К северо-востоку отсюда находится регион, именуемый Осколки Пустоты; его не было видно, когда эта земля была зеленой и цветущей. Среди скопления кристаллов, очутившихся на поверхности земли, мы обнаружили новый минерал, который назвали фаралитом, в честь прежнего имени этих земель.$B$BХотя нам удалось добыть лишь небольшое количество фаралита, он уже оказался востребован нашими клиентами. Наиболее высококачественный минерал содержится не в отложениях – его производят великаны, обитающие по всем Осколкам Пустоты. Я предлагаю тебе долю в доходах, если ты поможешь добыть высококачественный фаралит.', 'Соберите 4 куска сырого фаралита и вернитесь к Зубену Элгенуби в Штормовую Вершину.', 'О да! Именно то качество, на которое я надеялся. Можно не разбивать скопления кристаллов, если можно добыть минерал непосредственно от производителя.', 'Я понимаю, что собирать фаралит очень опасно, но таковы обстоятельства. Торговец, не желающий рисковать, может попросту закрыть двери и тем самым уберечься от неприятностей.', NULL, NULL, 'Сырой фаралит', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10291, 'Донесение Назгрелу', 'Наши воины не знают себе равных, но наши позиции в этих пустошах по-прежнему ненадежны. Доложи Назгрелу, что нам нужны еще агенты... вроде тебя. Если мы не сумеем отстоять здесь свои позиции, от нас не будет никакой пользы. А теперь ступай!', 'Поговорите с Назгрелом по приказу генерала Кракорка из Траллмара.', 'Мы уже потеряли в этих проклятых степях не одну сотню отважных солдат. Посылать туда новобранцев – все равно что телят на бойню.$B$B<Назгрел сверкает суровым взглядом из-под волчьей маски.>$B$BЕсли уж генерал Кракорк отправил тебя ко мне, значит, он что-то в тебе разглядел. Ну, что скажешь, $N? Готов верой и правдой служить нашему вождю?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10292, 'Больше энергии!', 'В том, чтобы собирать драгоценный товар мелкими партиями, есть что-то своеобразное, похожее на надомное производство, однако на современном рынке такое производство не выдержит конкуренции.$B$BНет, нам нужен именно массовый способ добычи фаралита! Тогда его количество на рынке будет под нашим полным контролем.$B$BУ меня есть идея, но для ее выполнения потребуется источник мощной, сфокусированной энергии. Есть только одно место, где можно добыть столь мощный источник энергии. Отправляйся в лагеря Легиона к северу отсюда и \"позаимствуй\" несколько их пушек.', 'Зубен Элгенуби хочет, чтобы вы захватили 8 пушек Легиона и принесли их в Штормовую Вершину.', '', NULL, NULL, NULL, 'Пушка Легиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10293, 'Попасть на главную жилу', 'Теперь, когда у нас есть неплохой основной продукт, мы должны получить что-то более высокого качества. Фаралит, который мы собирали до сих пор, несомненно, хорош, но я знаю, что существует и лучший.$B$BНам нужно получить образец непосредственно от Скалсаара, патриарха фаралонских великанов! Ты можешь найти его среди других великанов в Осколках Пустоты. Из спины у него торчат огромные куски фаралита – именно этот минерал нам и нужен. Напади на этого великана и добудь из его тела фаралитовую сердцевину.', 'Зубен Элгенуби, находящийся в Штормовой Вершине, хочет, чтобы вы добыли фаралитовую сердцевину.', 'Превосходно! Жду не дождусь, когда я смогу приступить к проверке.', 'Тебе удалось остаться в живых – значит, или фаралитовая сердцевина при тебе, или ты передумал. Так то или другое?', NULL, NULL, 'Фаралитовое ядро', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10294, 'Пустынный обрыв', 'Мне нужно усовершенствовать нестабильный генератор астральных провалов. Отнеси его на Пустынный обрыв, к востоку отсюда. По дороге лежит Зет\'Гор, и лучше обогнуть этот оплот скверны. К востоку от Зет\'Гора находится небольшой горный перевал. Именно там ты и найдешь Пустынный обрыв, жуткое место, приютившееся на самом краю бездны.$B$BУбей тварей, которые там обитают, и принеси мне осколки их душ. С их помощью мы улучшим мой нестабильный генератор и откроем портал в самые глубины бездны.', 'Отправляйтесь на Пустынный обрыв и убейте существ, которые там обитают. Соберите 40 осколков душ Пустынного обрыва и возвращайтесь к Огафу Безумному на Заставу Хребтолома.', 'Отлично, теперь нестабильный генератор астральных провалов работает как надо. Остался только один, самый последний компонент. Скоро, скоро мы откроем провал в самые глубины Бездны.$B$BКто знает, что за существа пожалуют к нам оттуда? $N, только подумай о могуществе, которое мы обретем.', 'Ты уже вернулся с Пустынной Гряды? Достал осколки душ?', NULL, NULL, 'Осколок души Пустынного обрыва', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10295, 'Сила бездны', 'Наконец-то нестабильный генератор астральных провалов работает как надо. Теперь мы призовем истинного владыку Бездны, осколок души которого сможет поведать нам столько, что трудно даже представить.$B$BСтупай на юг Пустынного обрыва и запусти генератор рядом с камнями пустоты. Наблюдай за гроздью кристаллов рядом с границей бездны. Когда астральный провал сформируется, появится Барон Бездны Галаксис.$B$BУничтожь его и принеси осколок его души.', 'Убейте Барона Бездны Галаксиса и добудьте осколок его души. Принесите осколок души Огафу Безумному на Заставу Хребтолома.', 'Ты спас работу всей моей жизни, $N.$B$BМеня называют безумцем и смеются надо мной, говорят, что я одержим Пустынной грядой и Полями искривления. Теперь, с этим осколком души, я открою все секреты демонов Бездны. Силы Бездны будут повиноваться мне!', 'Ты убил Барона Бездны Галаксиса? Где осколок его души?', NULL, NULL, 'Осколок души Галаксиса', 'Генератор астральных провалов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10296, 'Черные топи', 'Драконы Бесконечности, похоже, утратили свою хваленую проницательность. Они собираются уничтожить Хранителя Медива, чтобы он не открыл Темный портал. На первый взгляд, это могло бы усилить Альянс, но на самом деле приведет к катастрофе и гибели этого мира.$B$BТебе нужно будет отправиться по тропе времени в Черные топи. Иди на запад, потом на юг, мимо будущего меня, пока не дойдешь до тоннеля, где обитают болотные жители. Пройди этот тоннель и поговори с Са\'атом.', 'Пройдите сквозь Пещеры времени до Черных топей времен открытия Темного портала и поговорите с Са\'атом.', 'На самом деле, если бы в Азерот не пришли орки, то никакого Альянса и не было бы. В конечном итоге началась бы гражданская война, которая ослабила бы человеческие королевства.$B$BИ Пылающий Легион захватил бы растерзанный междоусобицами беззащитный Азерот.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10297, 'Открытие Темного портала', 'За пределами этой дороги времени, в самом сердце Черных топей, Хранитель Медив пытается открыть Темный портал, дабы возвестить эру орков на Азероте.$B$BДраконы Бесконечности послали повелителей временных разломов, чтобы остановить его.$B$BДраконы откроют в топях разломы времени, попытаются разрушить щиты Медива и уничтожить его самого.$B$BТвоя задача – помочь Медиву завершить задуманное и уничтожить его противников. Возьми с собой маяк времени и используй его, если тебе понадобится помощь.', 'Защищайте Медива, пока он не откроет Темный портал.Когда выполните задание, возвращайтесь к Са\'ату в Черные топи.', 'Ты отлично справился с заданием, $N. Юный Андорму снова желает с тобой говорить.', 'На каждом участке времени можно использовать только один маяк.', NULL, NULL, 'Откройте Темный портал.', 'Маяк времени', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10298, 'Герой драконьего племени', 'Возвращайся к Андорму, $N. Он ожидает тебя за пределами этого участка времени, в логове нашего господина.$B$BЯ слышу какой-то шум. Похоже, драконы Песчаной Чешуи проявляют к тебе интерес. Возможно, они захотят побеседовать с тобой.', 'Возвращайтесь к маленькому Андорму в пустыню Танарис в Пещерах Времени.', 'Ты снова спас прошлое и будущее этого мира, $N. Мы благодарны тебе и просим принять эту скро$Nю награду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10299, 'Отключить манагорн Б\'наар', 'Мы не можем отключить манагорн силовыми методами, поскольку рискуем вызвать взрыв, который сотрясет Запределье до самой сердцевины.$B$BСогласно твоему описанию, существует аварийное отключение, которое надолго, если не навсегда, останавливает процесс – механизм безопасности, общий для всех конструкций наару.$B$BДля выполнения этой процедуры тебе нужно заполучить кристалл, который позволит тебе связаться с панелью управления. Согласно нашим сведениям, кристаллом доступа владеет инспектор по имени Тередис.', 'Вернитесь в манагорн Б\'наар и заберите кристалл доступа у надзирателя Тередиса. Используйте его на панели управления манагорна, чтобы выключить его, затем сообщите об этом анахорету Карже. Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Свет улыбается тебе, $N. Мы все молились за твой успех.', 'Успешно ли выполнена задача, $N?', NULL, NULL, 'Отключите манагорн Б\'наар', 'Кристалл доступа в Б\'наар', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10300, 'Восстановление посоха', '$gРавандвир осматривает посох и замечает, что часть навершия отсутствует.>$B$BЭто просто варварство! Эккораш, должно быть, использовала кристалл от навершия, чтобы вставить в какую-то другую безделушку, не понимая, что эта часть действует в гармонии с остальным посохом.$B$BВ отсутствие этой части сила посоха заметно уменьшается. Если бы у меня был подходящий дренейский кристалл, я смог бы его отремонтировать. Я слышал, что гоблины видели такие кристаллы у призраков, обитающих в руинах Энкаата на севере.', 'Заберите 4 осколка безупречного кристалла у призраков в руинах Энкаата и принесите Равандвиру в Зону 52.', '<Равандвир тщательно осматривает кристаллы, затем выбирает один.>$B$BЭтот кристалл подойдет. Я изменю форму гнезда посоха, чтобы закрепить новое навершие.$B$BКогда верховный маг Варгот увидит это, он будет разочарован, но я переживу разочарование учителя, если это будет означать, что мы освободим его.', 'Удалось ли тебе найти кристаллы, пригодные для изготовления нового навершия к посоху верховного мага?', NULL, NULL, 'Осколок безупречного кристалла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10301, 'Открыть Компендиум', 'Хотя я рад получить обратно большую часть компендиума Краса, он бесполезен без халцедонового ока. Видишь ли, Крас хорошо сознавал всю силу заклинаний, записанных в книге, и предпринял шаги, чтобы обезопасить их от любопытных глаз.$B$BТолько знающий маг может использовать око, чтобы открыть тайны компендиума.$B$BВо время атаки Кель\'таса одна из его лейтенантов, рушительница чар Маратель, захватила око и унесла его в форт Ярости Солнца, находящийся к северо-востоку от этой башни. Несомненно, она думала, что это милая побрякушка.', 'Заберите Халцедоновое око у Рушительницы Чар Маратиль, находящейся в Форте Ярости Солнца.', 'Превосходно, $N. Теперь у нас есть большая часть того, что необходимо для попытки разрушения магии Кель\'таса.$B$BА если эльфы крови буду страдать, потеряв местное командование, то так им и надо.', 'Удалось ли тебе заполучить око?', NULL, NULL, 'Гелиотропное око', 'Посох верховного мага Варгота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10302, 'Неустойчивые мутации', 'Радиоактивные силовые ядра Экзодара – настоящая беда для местной фауны и флоры. Например, рядом с ними появились странные, невиданные твари.$B$BМожет быть, им можно чем-то помочь, но в настоящий момент они так расплодились, что представляют собой серьезную угрозу.$B$BОтправляйся и сократи их число. Может быть, тем временем я что-нибудь придумаю.', 'Убейте 8 неустойчивых мутаций и вернитесь к ботанику Таэрикс на месте крушения в долине Аммен.', 'Так быстро? Что ж, отлично. Надеюсь, скоро я придумаю, как справляться с этими мутантами, не убивая их.$B$BУ меня появилась пара идей, но без твоей помощи мне не обойтись.', 'Я скоро придумаю, что делать с этими тварями. Дай мне время.', NULL, NULL, 'Неустойчивая мутация убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10303, 'Эльфы крови', 'Останови... нашествие... эльфов крови. Узнай... что они замышляют!$B$BОни у хребта... у меня за спиной.', 'Убейте 10 эльфов крови – разведчиков и вернитесь к Толаану на хребет Теней в долине Аммен.', 'Эльфы крови хотят убить нас всех. Как бы им помешать?', NULL, NULL, NULL, 'Эльф крови-разведчик убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10304, 'Воздаятель Алдар', 'С твоей помощью мы отыскали решение наших проблем гораздо быстрее, чем я надеялся.$B$BДругой работы для тебя у меня нет. Остальным займутся мои ученики.$B$BПоговори с воздаятелем Алдаром на другой стороне корабля.', 'Поговорите с воздаятелем Алдаром на месте крушения в долине Аммен.', 'Тебя $N зовут, верно? Я слышал про тебя много хорошего. Ты успела принести своему народу немало пользы.$B$BИ нам без твоей помощи тоже не обойтись. Например, Жанае срочно нужен подручный. Вон она стоит.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10305, 'Клятвопреступница Белмара', 'Этот потрепанный, но все еще прочный том – не книга заклинаний, как можно было бы ожидать от фолианта, принадлежащего магу Кирин-Тора. Страницы тома покрыты рукописными строчками историй и цветными иллюстрациями.$B$BПохоже, этот том старше своей бывшей владелицы и вполне может быть фамильным наследием. Мощная привязанность к этой книге – возможно, последняя нить, привязывающая Белмару к руинам Кирин\'Вара. Быть может, возвращение книги на ее законное место на полке дарует свободу неупокоенному духу Белмары.', 'Найдите апартаменты клятвопреступницы Белмары в переулке Волшебников и верните книгу на полку. Затем поговорите со смотрителем Дайвортом в деревне Кирин\'Вар.', 'Ах, да. Я слышал, что у клятвопреступницы Белмары была древняя книга историй, но я и понятия не имел, что она взяла ее с собой в Запределье. Я уверен, что душа Белмары будет спать спокойно, зная, что книга нашлась и возвращена на свое место.', NULL, NULL, NULL, 'Упокойте дух Белмары', 'Фолиант Белмары', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10306, 'Кудесник Люминрат', 'Этот плащ, несомненно, работы высших эльфов; он превосходно сшит даже по меркам Кирин-Тора. Символы и буквы, вышитые на ткани плаща, не имеют, с твоей точки зрения, никакого смысла, однако явно указывают на то, что плащ наделен магическими свойствами.$B$BБыть может, этот предмет привязывает своего бывшего владельца к этому миру. Если так, то возвращение этого плаща в гардероб в апартаментах кудесника Люминрата может оборвать связь духа с этим миром и даровать душе бывшего владельца плаща покой.', 'Найдите апартаменты кудесника Люминрата в переулке Волшебников и верните плащ в его гардероб. Затем поговорите со смотрителем Дайвортом в деревне Кирин\'Вар.', 'Мы всегда отмечали, что Люминрат носит этот плащ поверх практически любой одежды. Красный цвет для него в равной степени сочетался с белым, черным, пурпурным, синим, желтым, оранжевым и зеленым. Он никогда не носил одно облачение два дня подряд, но плащ был на нем всегда...', NULL, NULL, NULL, 'Упокойте дух Люминрата', 'Мантия Люминрата', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10307, 'Кольен Повелитель Льда', 'Глядя на эту шляпу, ты задаешься вопросом, мог ли кто-то из магов Кирин-Тора носить этот головной убор. Судя по виду шляпы, похоже, что в ней постоянно разгуливал гном.$B$BТы пытаешься проверить шляпу, но не обнаруживаешь у нее никаких магический свойств, кроме слабого побуждения потанцевать.$B$BДолжно быть, этот предмет, милый сердцу покойного мага, – последнее, что привязывает его дух к деревне. Если положить шляпу на вешалку в апартаментах Кольена, его дух, возможно, обретет свободу.', 'Найдите апартаменты Кольена Повелителя Льда в переулке Волшебников и верните шляпу на вешалку. Затем поговорите со смотрителем Дайвортом в деревне Кирин\'Вар.', '<Комендант улыбается при упоминании имени Кольена.>$B$BНасчет шляпы – все именно так. Он все время носил ее, а если снимал, то не спускал с нее глаз.$B$BПару раз один из его товарищей-магов, оставшийся неизвестным, \"заимствовал\" шляпу и прятал ее – просто в шутку. Но угроза получить от Кольена одну из его ледяных стрел заставила его отказаться от подобных шуток.$B$BЯ буду скучать по маленькому Кольену. Он умел найти подход к эльфийским дамам.', NULL, NULL, NULL, 'Упокойте дух Кольена', 'Шляпа Кольена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10308, 'Еще одна группа духов Астрала', '', '', 'Предатели, все они предатели! $B$BА ты – молодец, $C! Если снова окажешься там, то приноси новые знаки отличия в мою коллекцию!', NULL, NULL, NULL, 'Знак отличия братства Заксис', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10309, 'Это сквернобот, но у него есть сердце!', 'Видишь, вон разобранный сквернобот к югу отсюда? Разве это не красота?$B$BЯ хочу получить его сердце!$B$BЧто? Да, конечно, у него есть сердце... а разве нет?$B$B<На момент вид у Н. Д. становится возмущенный.>$B$BИди туда, вскрой его, принеси мне то, что я хочу, и за это я выдам тебе хорошую премию.$B$BДа, и на твоем месте я взял бы с собой одного-двух друзей. Эти Заксисы – чрезвычайно злобные создания! $B$BВозьми этот пульт управления Скверны, чтобы запустить его сердце перед тем, как приступишь к работе.', 'Заберите сердце сквернобота и отнесите Н. Д. Лагерфелту на Груду в Пустоверти.', 'Ого, посмотрите-ка на это... бьющееся сердце сквернобота! Ну, на самом деле это нельзя назвать \"биением\", но ты понимаешь, что я хочу сказать.$B$BЖду не дождусь, чтобы найти этой вещи хорошее применение. А может быть, продать ее. Я знаю несколько воню... то есть клиентов, которых это может заинтересовать.$B$BНу что ж, вот твоя заслуженная плата!', 'Должно быть, мое зрение ослабло от постоянного излучения Пустоты. Тебе удалось заполучить сердце сквернобота?', NULL, NULL, 'Сердце сквернобота', 'Электростимулятор Скверны (Прилагается)', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10310, 'Саботаж в портале', 'Пылающий Легион находится поблизости, на Захламленном поле скверноботов, и мы должны сделать все возможное, чтобы остановить этих демонов и не дать им захватить этот регион.$B$BУ них есть портал на юге, в районе, который они назвали достаточно ясно – точка вторжения: Разрушитель.$B$BВот что мне нужно: пойдем со мной туда, будешь охранять меня, пока я занимаюсь там саботажем.$B$BПосле этого отправляйся на заставу, расположенную на севере, внутри заповедника \"Срединные земли\", и сообщи Гаруджу о нашем успехе.$B$BНам нужно взять с собой одного-двух друзей, чтобы они нам помогли.', 'Сопроводите Дризья до точки вторжения: Разрушитель и проследите за безопасностью во время попыток саботажа. Затем поговорите с Гаруджем на заставе в заповеднике \"Срединные земли\" в Пустоверти.', 'Это превосходные новости, $N!$B$BТы и Дризья проделали отличную работу. Пока портал не действует, находящиеся поблизости демоны не получат подкрепления.$B$BПозволь мне вознаградить тебя, как это принято в Консорциуме.', NULL, NULL, NULL, 'Попытка саботажа проведна успешно', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10311, 'Дризья нужна твоя помощь', '$C, хорошо, что поблизости оказался хоть кто-то способный помочь.$B$BДемоны Пылающего Легиона, собравшиеся вокруг ближайшей груды скверноботов стали действовать более решительно, и я начинаю бояться за нашу безопасность здесь. Они постоянно получают подкрепления из Места Вторжения \"Разрушитель\" на юге.$B$BМой земляк Дризья отправился туда на разведку, посмотреть, нельзя ли что-нибудь сделать с порталом Пылающего Легиона.$B$BПрошу тебя, разыщи его и окажи любую помощь, какую сможешь.', 'Поговорите с Дризья, находящимся около Места Вторжения \"Разрушитель\" в Пустоверти.', 'Надеюсь, Гарудж послал тебя, чтобы помочь мне в моей миссии.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10312, 'Анналы Кирин\'Вара', 'Заставив духов умолкнуть, мы не избавили их от агрессии, как надеялись. Укрощенные тобою злобные духи снова появились на наших улицах.$B$BМы должны понять, чем это вызвано. Уничтожение Кирин\'Вара было лишь началом, иначе духи уже успокоились бы.$B$BВ городской ратуше в южной части Кирин\'Вара находилась регистрационная книга, куда вносились записи обо всех обитателях деревни. Последнее, что я слышал – ее взял на хранение боевой маг Датрик. Быть может, его дух все еще хранит книгу.', 'Заберите анналы Кирин\'Вара из ратуши деревни Кирин\'Вар и отнесите ее смотрителю Дайворту.', '<Смотритель Дайворт берет у вас книгу и пролистывает страницы.>$B$BХмм...$B$BПохоже, я был прав. Есть некая закономерность.$B$BСамые агрессивные и опасные призраки принадлежат самым сильным и высокопоставленным магам Кирин-Тора, жившим в деревне. Обычные жители и торговцы в сравнении с ними почти не представлены. Что бы это могло значить?', 'Удалось ли тебе найти регистрационную книгу?', NULL, NULL, 'Анналы Кирин\'Вара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10313, 'Измерение энергии Искажения', 'Если наши инстинкты не лгут и эти манагорны построены с использованием технологий из Крепости Бурь, тогда всему Запределью грозит страшная опасность. $B$BЭнергозарядные механизмы Крепости Бурь никогда не рассчитывались на использование так близко от суши. Энергия искривления способна уничтожить саму эту землю, даже будучи заключена в трубопроводы Келя.$B$BОтнеси этот шар в манагорн Б\'наар; он приспособлен к измерению энергии искривления. Используй его возле окончания трубопровода, там, где трубы уходят в землю.', 'Экзарх Орелис, находящийся в Зоне 52, просит вас отнести настроенный на энергию искривления шар к манагорну Б\'наар и использовать шар у окончания четырех трубопроводов. Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Это мрачные новости, $N. Уровень энергии Искажения, излучаемой трубопроводами, опасно высок.$B$BМы должны найти способ закрыть Манагорн, иначе то немногое, что осталось от Запределья, разлетится на кусочки.', 'Удалось ли тебе провести нужные нам измерения, $N?', NULL, NULL, 'Северный трубопровод измерен', 'Восточный трубопровод измерен', 'Южный трубопровод измерен', 'Западный трубопровод измерен');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10314, 'Длительные подозрения', 'Странное магическое устройство не напоминает ничто из того, что тебе приходилось видеть прежде. Это определенно не работа эльфов крови. $B$BКогда ты ощущаешь, как к зданию приближаются духи, шар начинает светиться сильнее, и тускнеет, когда духи уходят. Нет сомнений, что он играет какую-то роль в порче, павшей на духов.$B$BТо, как это устройство работает, остается загадкой. Быть может, смотритель Дайворт сможет что-либо прозреть, если ты предъявишь останки духов и поделишься своими наблюдениями.', 'Соберите 10 омерзительных останков искаженных духов во дворе часовни деревни Кирин\'Вар и отнесите их смотрителю Дайворту.', '<Смотритель Дайворт изучает останки.>$B$BСудя по описанию, это устройство похоже на средоточие некромантии... Мне следовало бы знать, что этот испорченный ученик не устоит перед этим. Я думал, что обучение не даст ему зайти так далеко, но я оказался не прав.', 'Что тебе удалось обнаружить, $N?', NULL, NULL, 'Омерзительные останки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10315, 'Нейтрализовать чародеев Пустоты', 'Эльфы крови – глупцы! Я рад, что наши торговые отношения с ними расторгнуты. Ни в одном своем путешествии по космосу я не встречал создания столь эгоистичных.$B$BОни продолжают уничтожать эти земли при помощи своих манагорнов, так что надо бы попробовать помешать их действиям по ту сторону моста, при манагорне Ара.$B$BИх чародеи Пустоты направляют энергию в камни крови и выкачивают из них для того, чтобы стабилизировать поток силы. Отправляйся туда и уничтожь их!', 'Убейте 15 пустомантов клана Ярости Солнца и возвращайтесь к ловчему Пустоты Оазулу в Лагерь Тулумана в Пустоверти.', 'Что бы мы ни сделали ради того, чтобы заставить их прекратить работу манагорнов, все это будет благим делом.$B$BПохоже, разумные доводы на них не действуют. И мне ясно, что какие бы замыслы ни лелеяли их вожди, они, несомненно, безумны.$B$BВ качестве вознаграждения за твою верную службу целям Консорциума я хотел бы предложить тебе денежную единицу твоего мира, если это не оскорбит тебя.', 'Сколько чародеев Пустоты пало от твоей руки?', NULL, NULL, 'Пустомант из клана Ярости Солнца убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10316, 'В поисках доказательств', 'Тот, кто стоит за изменением духов, действует явно намеренно, выбирая своей целью, в первую очередь, души самых могущественных магов. Но почему? Магия, необходимая для того, чтобы подчинить своему влиянию убитых магов Кирин-Тора, должна быть очень могущественной. $B$BЗачем такому сильному магу брать на себя все эти хлопоты? Я склонен считать, что это еще один план Кель\'таса, направленный на то, чтобы нанести нам как можно больше урона. Если здесь есть эльфы крови, они, скорее всего, скрываются в домах за крытым мостом.', 'Поищите во дворе часовни в деревне Кирин\'Вар свидетельства того, кто именно манипулирует духами убитых.', 'Светящийся шар установлен на вершине квадратного пьедестала. С первого взгляда он кажется просто вместилищем магической энергии, однако какой именно энергии? И кто ею пользуется?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10317, 'Покончить со штейгером', 'Эльфы крови называют шахту, расположенную под манагорном Ара, рудником Треллеума. С тех пор, как они потеряли шахту под манагорном Ультрис, этот рудник остался последним источником материала для работы манагорнов.$B$BЧто и говорить, для нас было бы выгодно помешать работам на руднике. Быть может, мы сумеем даже сделать больше и забрать шахту себе.$B$BКак бы то ни было, я прошу тебя отправиться туда и покончить со штейгером Закатом Солнца. Рудник находится с обратной стороны острова по левую сторону.', 'Покончите со штейгером Закатом Солнца, находящимся в руднике Треллеума под манагорном Ара в Пустоверти.', '<Штейгер говорит едва ли не шепотом.>$B$BТы здесь для того, чтобы убить меня? Ха. Полагаю, духи Астрала знают не так-то много, верно?$B$BЯ не тот, кто тебе нужен, поверь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10318, 'Покончить с Подчинителем', 'Некогда я был штейгером здесь. Но теперь, когда меня понизили в звании, я начал осознавать, что наше паломничество из Кель\'Таласа в Запределье – это сплошная ложь.$B$BЛожь, изобретенная Кель\'тасом для усиления его войск здесь, в Пустоверти.$B$BЯ пытался убедить моих собратьев, что нам нужно уходить прочь, особенно если учесть, что здесь находится Пылающий Легион, но все они так упрямы! $B$BНе окажешь ли ты мне услугу? Убей Подчинителя Гриндгарра. Затем возвращайся к своему духу Астрала и скажи ему, что я больше ему не враг.', 'Убейте Подчинителя Гриндгарра. Затем вернитесь к торговцу Ветром Тулуману в Лагерь Тулумана в Пустоверти.', 'Надсмотрщиком там был стражник Ужаса? Странно! Что здесь делает Пылающий Легион?$B$BИтак, кое-кто из эльфов крови дезертирует. Мы будет иметь это в виду, если попытаемся захватить этот регион силой. По крайней мере, хоть какие-то хорошие новости во всем этом есть, не так ли?$B$BПрими мою глубочайшую благодарность, $N, а вместе с ней вот это.', NULL, NULL, NULL, 'Подчинитель Гриндгарр убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10319, 'Захватить талисман', 'Я полагаю, необходимо объяснение. Тебе уже приходилось встречаться с одним из учеников нашего верховного мага – Рандивиром. Однако был еще один ученик, по имени Набериус. $B$BОн был весьма прилежен и талантлив, однако увлекся некромантией. Когда явился Кель\'тас со своим воинством, Набериус воспользовался этой возможностью, чтобы предать верховного мага, и выдал тайну защиты башни.$B$BТеперь, похоже, он стал личом. Если мы хотим остановить его, мы должны захватить его талисман. Зная его, могу сказать, что он, вероятнее всего, зарыл его где-нибудь за пределами своих владений.', 'Заберите филактерию Набериуса из района часовни деревни Кирин\'Вар и принесите его смотрителю Дайворту.', 'Превосходная работа, $N. Обретение талисмана может стать ключом к нашей победе. Когда ты выйдешь на бой с Набериусом, я разобью талисман и лишу нашего врага защиты.', 'Прежде чем напасть на самого Набериуса, нужно забрать его талисман. Иначе он будет неуязвим.', NULL, NULL, 'Оберег Набериуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10320, 'Уничтожить Набериуса!', 'Верховный маг Варгот видел опасность в стремлении Набериуса к некромантии, однако вряд ли он подозревал, что его собственный ученик навлечет столько бедствий на Кирин-Тор.$B$BЕго нужно остановить, $N, иначе он продолжит порабощать души наших павших собратьев, лишая их покоя и уничтожая то немногое, что осталось от Кирин\'Вара.$B$BСо своим талисманом он может противостоять двум-трем бойцам, но кто знает, насколько сильна его магия и что он может противопоставить большему количеству врагов?', 'Смотритель Дайворт в деревне Кирин\'Вар просит вас сразиться с Набериусом, находящимся во дворе часовни, и уничтожить его.', 'Уничтожение Набериуса - великое достижение, $N. Не могу отделаться от мысли, что мы могли бы противостоять войскам Кель\'таса, если бы этот ученик мага не предал нас.', NULL, NULL, NULL, 'Набериус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10321, 'Отключить манагорн Коруу', 'Твой успех в манагорне Б\'наар подарил нам великую надежду, $N.$B$BМы поделились нашими открытиями с Провидцами, и в ответ они предоставили нам сведения по оставшимся манагорнам.$B$BТри других манагорна еще работают, и их полностью контролирует армия Ярости Солнца.$B$BМанагорн Коруу ты найдешь к востоку отсюда. Кристалл доступа от нее хранится у надзирательницы Сейланны. Забери этот кристалл и примени его к панели управления манагорном, дабы начать аварийное отключение. $B$BВсе мы рассчитываем на тебя, $N.', 'Отправляйтесь в манагорн Коруу к востоку от Зоны 52 и заберите кристалл доступа Коруу у надзирательницы Сейланны. Используйте его на панели управления манагорна Коруу, чтобы отключить манагорн, затем вернитесь к анахорету Карже.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Прекрасно. Теперь работают только два манагорна.$B$BВскоре Кель\'тас будет отрезан от своего главного источника энергии.', 'Удалось ли тебе выполнить задачу, $N?', NULL, NULL, 'Отключите манагорн Коруу', 'Кристалл доступа к Коруу', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10322, 'Отключить манагорн Даро', 'Мы получили новости с одной из двух все еще действующих манагорнов. Армия Ярости Солнца теряет контроль над манагорном Даро. $B$BУвеличившееся производство энергии привлекло туда стада блуждающих мана-тварей, и теперь там царит полный беспорядок.$B$BВзрыв на Даро, вполне вероятно, будет настолько силен, что вызовет цепную реакцию, из-за чего под угрозой окажется все Запределье. У надзирателя Атанеля хранится кристалл доступа, который нужен, чтобы безопасно отключить манагорн.', 'Анахорет Каржа просит вас отправиться в манагорн Даро и забрать кристалл доступа у надзирателя Атанеля. Используйте этот кристалл на панели управления манагорном Даро, чтобы отключить его.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Да пребудет с тобой благословение наару, $N. Твоя преданность нашему делу будет должным образом отмечена и вознаграждена.', 'Удалось ли тебе выполнить задачу, $N?', NULL, NULL, 'Отключите манагорн Даро', 'Кристалл доступа к Даро', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10323, 'Отключить манагорн Ара', 'Один манагорн – это все, благодаря чему Крепость Бурь все еще действует. После того как мы отключим манагорн Ара, Келю придется черпать энергию из тех запасов, которые у него есть.$B$BОтправляйся к манагорну Ара, расположенному на северо-западе, и отключи ее, нанеся тем самым последний удар. $B$BПоследний кристалл доступа находится у надзирателя Азарада. Осторожно – последний из действующих манагорнов наверняка будут защищать изо всех сил. Тебе, вероятно, понадобится помощь надежных друзей.', 'Отправляйтесь в манагорн Ара и заберите кристалл доступа у надзирателя Азарада. Используйте его на панели доступа манагорна Ара, чтобы отключить его.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Пылающий Легион в союзе с Кель\'тасом Солнечным Скитальцем?$B$BЭто страшные новости. Они многое объясняют относительно того, что мы видели здесь и в Долине Призрачной Луны.$B$BМы должны немедленно послать известие об этом в город Шаттрат.', 'Удалось ли тебе выполнить порученное задание, $N?', NULL, NULL, 'Отключите манагорн Ара', 'Кристалл доступа в Ару', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10324, 'Великая охота на лунных оленей', 'Молодец, $N! Молодец!$B$BМне кажется, что, потренировавшись на лунных оленях, ты можешь перейти к более сложной добыче. Не обманывайся спокойствием самцов лунного оленя: если их разозлить, они оказываются непростыми противниками.$B$BСамцы пасутся к северу отсюда. Доброй охоты.', 'Принесите 6 шкур самцов лунного оленя Актеону с Лазурной заставы.', 'Чудесно! Ты становишься настоящим охотником, $N.$B$BХочешь выглядеть, как я? Почему бы и нет! Пока ты охотился, я сделал несколько предметов из оленьих шкур. Выбирай любой!', 'У маралов чрезвычайно прочные шкуры, хотя мясо очень жесткое – практически несъедобное. Но мы их применим для других целей.', NULL, NULL, 'Шкура самца лунного оленя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10325, 'Знаки Кил\'джедена', 'Как ты, наверное, уже знаешь, $N, Алдоры – это хранители Света и слуги наару.$B$BНаши главные враги – это Пылающий Легион, армия демонов, жаждущая разрушить и осквернить все миры.$B$BЕсли ты желаешь проявить себя перед Алдорами, принеси мне знаки различия легионеров низшего ранга и последователей Легиона из Совета Теней. Одна из баз Совета находится в Костяных пустошах, а заставы Легиона разбросаны по всему Награнду и Острогорью.', 'Принесите 10 знаков Кил\'джедена Адуину Стражу Света в Шаттрат.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Сражаться с демонами Пылающего Легиона и культистами, которые им поклоняются, - задача не из легких, $N, но у вас достаточно смелости и решительности. Продолжайте в том же духе, и отношение Алдоров к вам будет постоянно улучшаться.', 'Принес ли ты, вражеские знаки отличия, $N?', NULL, NULL, 'Знак Кил\'джедена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10326, 'Больше знаков Кил\'джедена', '', '', 'Вы растете в наших глазах, Профессия. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.$B$B*Это задание можно выполнять до тех пор, пока вы не заслужите почтительное отношение.*', NULL, NULL, NULL, 'Знак Кил\'джедена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10327, 'Знак Кил\'джедена', '', '', 'Вы растете в наших глазах, $N. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.$B$B*Это задание можно выполнять до тех пор, пока вы не заслужите уважительного отношения к себе.*', NULL, NULL, NULL, 'Знак Кил\'джедена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10328, 'Инструкции Ярости Солнца', 'Что-то в этих манагорнах беспокоит меня, $N. Технология наару чрезвычайно развита, Келю потребовались бы годы только для того, чтобы начать постигать ее.$B$BСбор сведений относительно этого вопроса очень труден, так как армия Кель\'таса очень дисциплинирована и уничтожает все свидетельства письменного общения.$B$BНам сообщили, что манагорн Даро подвергается нападению мана-тварей. Возможно, что из-за необходимости обороняться там еще не успели уничтожить инструкции. Забери их и принеси мне.', 'Отправляйтесь в манагорн Даро и заберите военные инструкции Ярости Солнца и чародейские инструкции Ярости Солнца. По завершении задачи возвращайтесь к экзарху Орелису.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Превосходная работа, $N! Посмотрим, что мы можем узнать из этих инструкций.', 'Повезло ли тебе добыть инструкции из манагорна Даро?', NULL, NULL, 'Военный инструктаж Ярости Солнца', 'Чародейский инструктаж Ярости Солнца', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10329, 'Отключить манагорн Б\'наар', 'За время твоего отсутствия у меня состоялась дружеская дискуссия с Алдорами. Манагорны выглядят точь-в-точь как несколько измененные технологии наару из Крепости Бурь. Судя по всему, в большинстве конструкций наару существовал предохранитель, позволявший в случае аварии отключить их навсегда.$B$BОбычно это действие выполнялось с панели управления через кристалл доступа. И знай, что согласно принесенному тобою списку персонала, подобный кристалл находится в руках некоего типа, известного как надзиратель Тередис. Завладей этим кристаллом и посмотри, что сумеешь сделать.', 'Вернитесь в манагорн Б\'наар и заберите кристалл доступа у надзирателя Тередиса. Используйте его на панели управления манагорна Б\'наар, чтобы выключить его, затем сообщите об этом патрону шпионов Талодиену. Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Конечно же, это сработало! Я глава шпионов, и мои сведения всегда точны. $B$BВ любом случае, у меня для тебя есть отличная новая работа. Хочешь услышать, что именно? Несомненно, хочешь.', 'Сработал ли план? Правду говоря, я наполовину ожидал, что тебя схватят.', NULL, NULL, 'Отключите манагорн Б\'наар', 'Кристалл доступа в Б\'наар', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10330, 'Отключить манагорн Коруу', 'Талодиен рассказал нам, что тебе удалось отключить манагорн Б\'наар. Он ожидает, что здесь произойдет то же самое, и просил нас высмотреть, у кого находится кристалл для доступа к панели управления. Мы уверены, что кристалл доступа находится у надзирателя Сейланны.$B$BОтправляйся туда и доверши дело. Больше нет необходимости в кражах; заполучи кристалл, начни отключение, убей техников, которые попытаются тебя остановить, и возвращайся.$B$BПоспеши, скоро ищейки Келя отыщут нас.', 'Заберите кристалл доступа Коруу у надзирателя Сейланны. Используйте его на панели управления Коруу, чтобы отключить манагорн, затем вернитесь к Каледису Сияющему Рассвету.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Мы слышали весь этот шум и уже собирались убраться отсюда. Хорошо, что тебе досталось не очень сильно.', 'Удалось ли тебе выполнить задачу, $N?', NULL, NULL, 'Отключите манагорн Коруу', 'Кристалл доступа к Коруу', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10331, 'Необходимые инструменты', 'Тебе случайно не попадался на глаза тяжелый кузнечный молот – нигде там не валяется? Я принес его с собой, чтобы закончить ковать подковы для лошадей старины Армолина, но что-то никак не могу найти.$B$BЯ обыскал весь амбар полдюжины раз, но так и не нашел. Может, кто-то из учеников забрал его и отнес обратно в кузницу? Ты не сходишь туда, чтобы удостовериться? Кузница находится на северо-востоке от башни на Городской площади.', 'Заберите кузнечный молот у кирин\'варских учеников и отнесите обратно ученику Андретану в деревню Кирин\'Вар.', 'Хвала небесам! Теперь я могу вернуться к работе. Я знаю, ты думаешь, будто я сумасшедший, поскольку работаю над изделием, которое принесет мне статус подмастерья, не в кузнице, как положено, а едва ли не в чистом поле. Но я не могу рисковать – вдруг остальные ученики скопируют мою разработку?', 'Удалось ли тебе найти мой молот?', NULL, NULL, 'Дробящий молот', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10332, 'Мастер-кузнец Ронсус', 'Наконец-то мое изделие, дающее право на звание подмастерья, готово! Не могу дождаться, чтобы официально предъявить его мастеру Ронсусу.$B$B<Ученик смотрит на вас, пока вы описываете свои действия по изъятию молота.>$B$BОни напали на тебя? Все? Во имя Света, они сошли с ума!$B$BЧто нам делать, $N? Мне горько говорить об этом, но, возможно, понадобится убить мастера Ронсуса. В этом случае я останусь единственным кузнецом в Кирин\'Варе, но, полагаю, я достаточно обучен, чтобы справиться с работами, необходимыми поселению.', 'Ученик Андретан из деревни Кирин\'Вар просит вас убить призрак Ронсуса, мастера-кузнеца поселения.', 'Мастер Ронсус научил меня всему, что я знаю о моем ремесле. Я почту его память тем, что использую свои умения на службе у живущих в Кирин\'Варе.', NULL, NULL, NULL, 'Ронсус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10333, 'Помощь Мамаше Колесун', 'Скажи, $N, не можешь ли ты оказать мне еще одну услугу?$B$BМоя напарница осуществляет работу непосредственно на месте, и ей, вероятно, приходится нелегко. Ты ее не проведаешь?$B$BЯ уверен, что Мамаша Колесун оценит твою помощь. Просто не обращай внимания на ее колкости.$B$BОна отстаивает наши интересы в восточной части этих земель. Ты найдешь ее в заповеднике \"Срединные земли\" на заставе.', 'Поговорите с Мамашей Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти.', 'Что? Он назвал меня \"напарницей\"? Я его жена!$B$BИ он утверждает, что я говорю колкости? Ну все, как только вернусь в Зону 52, отрежу его здоровенные зеленые уши!$B$BНо я рада, что ты здесь. Насчет одного он точно был прав: твоя помощь мне пригодится!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10334, 'Колокольчик для коровы', 'Где же, где же моя Бесси? После нападения я обыскал все поля и Церковный двор, но ее нигде не было!$B$BВсе, что мне осталось от нее – это вот этот старый колокольчик. Когда она слышала его звон, то обычно прибегала, но мои руки уже совсем ослабли. Даже для того, чтобы звонить в колокольчик.$B$BЯ одолжу тебе колокольчик Бесси, если ты согласишься пойти в поле и звонить в него как можно громче. Быть может, Бесси просто ждет, пока в колокольчик позвонят погромче и подольше.', 'Найдите Бесси в полях близ Часовенного холма деревни Кирин\'Вар в Пустоверти.', '<Достав колокольчик, вы несколько раз звоните в него, потом показываете его Бесси, которая, похоже, узнает этот предмет. Корова позволяет вам завязать у нее вокруг шеи веревку и выжидательно смотрит на вас.>', '<Корова недоверчиво смотрит на тебя, но стоит на месте.>', NULL, NULL, 'Колокольчик Бесси (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10335, 'Исследование руин', 'Я намереваюсь отправиться в руины Фаралона, чтобы начать там раскопки. Проблема в том, что это место кишит демонами. $B$BМожет быть, ты проведешь для меня кое-какую подготовительную работу?$B$BВ северо-восточной части руин находятся три точки, где нужно разместить геодезические знаки. Каждый – поблизости от дренейского знамени.$B$BВозвращайся, когда установишь все три знака.', 'Разместите три геодезических знака, затем возвращайтесь к Зефириону в Штормовую Вершину в Пустоверти.', 'Это ведь не шутки, верно? Отличная новость!$B$BТеперь, когда геодезическая разметка участка проведена, я могу откомандировать бригаду в руины и посмотреть, что там можно найти. $B$BПрими мою благодарность, $C.', 'Ого, как быстро! Ты, должно быть, работаешь очень эффективно, если установил все три знака за такое короткое время.', NULL, NULL, 'Первый геодезический знак размещен', 'Второй геодезический знак размещен', 'Третий геодезический знак размещен', 'Геодезические знаки (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10336, 'Приспешники Кулутаса', 'Несколько недель назад Пылающий Легион вторгся в руины Фаралона, нарушив наши планы относительно раскопок в поисках артефактов.$B$BА сегодня я узнал, что один из их повелителей ужаса, Кулутас, убил своих собратьев из Пылающего Легиона и с тех пор призывает демонов, которые служат ему.$B$B$C, я прошу тебя отправиться в эти руины, находящиеся к северо-востоку отсюда, и уничтожить кишащих там демонов.', 'Убейте 10 псов Кулутаса и 5 злобоглазов Кулутаса. Затем вернитесь к ловчему Пустоты Наутису, находящемуся в Штормовой Вершине в Пустоверти.', 'Поистине отличная работа.$B$BТеперь, когда демоны Кулутаса убиты, Зефирион сможет безопасно заняться раскопками в руинах Фаралона.$B$BПрими эти деньги в знак моей признательности.', NULL, NULL, NULL, 'Гончая Кулутаса убито', 'Око Кулутаса убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10337, 'Когда коровы возвращаются домой', 'Осознав, что Бесси все еще смотрит на тебя, ты жестом указываешь туда, где находится Таделл. Ты считаешь, что обещание выполнено – корова благополучно прибыла домой. Но еще не закончив говорить, ты осознаешь, что корова все равно не сможет понять ни единого слова. $B$BПожав плечами, ты готовишься сопровождать скотину, пока она не вернется к Таделлу.', 'Благополучно сопроводите Бесси к ее владельцу, Таделлу.', 'Бесси, это ты?$B$B*Фермер поворачивается к тебе.*$B$BСпасибо за возвращение моей Бесси, $N! Я без нее жить бы не смог!', NULL, NULL, NULL, 'Проводите Бесси домой.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10338, 'Отключить манагорн Даро', 'Так на манагорн Даро совершено нападение, и войска Ярости Солнца теряют контроль? Какая дилемма. Если Даро падет, то падет и Крепость Бурь. Единственная загвоздка... если Крепость Бурь будет разрушена, взрыв, вероятно, уничтожит то немногое, что осталось от этой проклятой земли.$B$BСмерть Кель\'таса – это хорошо. Смерть всех остальных... полагаю, не очень. Мне больно просить тебя об этом, но отправляйся в манагорн Даро и отключи его прежде, чем он загорится. Кристалл доступа находится у надзирателя Атанеля.', 'Вернитесь в манагорн Даро и заберите кристалл доступа у надзирателя Атанеля. Используйте его на панели управления манагорна Даро, чтобы отключить его, затем сообщите об этом патрону шпионов Талодиену. Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Итак, $N, ты уже отключил три манагорна. Должно быть, у Кель\'таса теперь начались настоящие проблемы.', 'Отключение завершено? Поспеши, пока я не передумал насчет всех этих планов!', NULL, NULL, 'Отключите манагорн Даро', 'Кристалл доступа к Даро', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10339, 'Братство Эфириум', 'Прямо на юг отсюда ты найдешь полигон Братства Эфириум. Братство находится там, к чему-то готовясь... Возможно, к нападению на Ультрис.$B$BОднако мы не можем упускать шанс, $C. Нужно пробиться через их оборонительный периметр и захватить их учебную базу.$B$BКогда ты уничтожишь их солдат и капитана Зовакса, отыщи передатчик Эфириума Зета и используй его, чтобы связаться со мной для получения дальнейших указаний.', 'Командир Амир просит вас уничтожить 5 убийц из Эфириума, 5 штормовиков из Эфириума, 2 ученых Эфириума и капитана Зовакса из Эфириума, затем включить передатчик Эфириума Зета.', 'Мы должны собрать все данные, которые они спрятали в этом регионе.', NULL, NULL, NULL, 'Убийца из Эфириума убито', 'Штормовик Эфириума убито', 'Ученый Эфириума убито', 'Капитан Зовакс убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10340, 'Парящая застава', '$N, ты $gпроделал:проделала: на фронте большую работу, и отлично $gуправился:управилась: с тем бронированным грифоном... Я думаю, что нашел для тебя еще одно дело.$B$BНовое задание ждет тебя на Парящей заставе. Это передовой пост клана Громового Молота, этакий плавучий кусок земли рядом с порталом. Там немного неуютно, но я верю, что тебе хватит смелости. Все будет отлично.$B$BПоговори с командиром звена Даби\'ри, пусть он отправит тебя на Парящую заставу. Как прибудешь, доложись Грунтогу Громовому Молоту.', 'По приказу командира передовой Кингстона поговорите с командиром звена Даби\'ри, доберитесь на грифоне до Парящей заставы и поговорите с Рунтогом Громовым Молотом.', 'Ха-ха-ха! Свеженький $r с большой земли! Не боись, сначала тебя малость поукачивает, а потом перестанет.$B$BНа моем веку застава опрокидывалась только один раз. Ну... максимум два.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10341, 'Лежачего не бьют – лежачего пинают', 'Принесенные тобой новости радуют меня, $N. Тебе не только удалось пробраться в манагорн Даро $gнезамеченным:незамеченной: – это также дает отличную возможность нанести удар по армии Келя.$B$BИспользуй это нападение мана-тварей в свою пользу и перебей всех отбившихся от основного отряда солдат Ярости Солнца, на которых наткнешься.$B$BВ отличие от Талодиена, я не вижу ничего забавного в бессмысленном убийстве своих сородичей, но тактическое преимущество слишком ценно, чтобы отказаться от такого случая.', 'Убейте 8 кудесников, 6 лучников и 4 центурионов клана Ярости Солнца. После завершения задачи вернитесь к магистру Ларинне, находящейся в Зоне 52.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Хорошая работа, $N. Армия Келя нескоро оправится от нанесенного тобою удара.', NULL, NULL, NULL, 'Кудесник из клана Ярости Солнца убито', 'Лучник из клана Ярости Солнца убито', 'Центурион из клана Ярости Солнца убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10342, 'Добыча кожи глиношкурых', 'Я делаю неплохие деньги, продавая выпивку местным пьяницам. Но мне нужно кое-что еще!$B$BВедущий ракетостроитель постоянно говорит мне, что не может усовершенствовать ракетное топливо, необходимое, чтобы запустить Х-52.$B$BМы можем решить эту мелкую проблему вместо него.$B$BДля начала мне нужно извлечь нефть из кожи местных глиношкурых камнедеров! Она образует концентрированную, пусть даже несколько взрывчатую, основу для смеси, придуманной мною.$B$BКамнедеров, равно как и их кожу, можно найти повсюду около лиловых скал.', 'Соберите 5 кусков кожи глиношкурых и отдайте Бутсу в Зоне 52 в Пустоверти.', 'Отлично! Ингредиент номер один получен.$B$BТеперь, если тебя интересует, мы должны перейти к тому, что придаст добытой из глины нефти дополнительную силу, необходимую, чтобы отправить ракету Пустоты в Круговерть Пустоты... или в небытие, как уж получится.', 'Тебе удалось собрать достаточно глины? Мне нужно довольно много, чтобы добыть то количество нефти, которое мне нужно, дабы создать топливо для ракеты Х-52.', NULL, NULL, 'Кожа глиношкурого', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10343, 'Бесконечное вторжение', 'Атака Кель\'таса на Кирин\'Вар началась с громового раската и яркой вспышки света в офицерском квартале в северо-западной части поселения. Разрушения там были наиболее страшными, а после ухода эльфов крови начали происходить странные вещи. $B$BСущества, состоящие из чистой маны, буквально хлынули на деревню из этого района. Пока что мы справляемся с ними, как можем, однако я надеюсь, что если у меня будет больше сведений об этом оружии Кель\'таса, я сумею прекратить вторжение мана-тварей.', 'Обыщите кишащий мана-тварями район деревни Кирин\'Вар в поисках фрагмента мана-бомбы и принесите его лейтенант-колдуну Моррану.', 'Мана-бомба?$B$B<Морран вертит фрагмент в руках.>$B$BЭто непредставимо! Даже самые светлые умы Даларана не могли придумать подобное оружие. Резкое усиление возмущений, должно быть, создало разрыв в Пустоте, позволив этим тварям проникнуть в наши земли.', 'Удалось ли тебе найти оружие, которое Кель\'тас использовал против нашей деревни?', NULL, NULL, 'Фрагмент мана-бомбы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10344, 'Командир звена Грифонгар', 'За старшего здесь командир звена Грифонгар. Если ты в первый раз на Парящей заставе, то следует доложить ему о прибытии.$B$BЕго можно найти во-он там, где-то среди остатков той башни.', 'Поговорите с командиром звена Грифонгаром на Парящей заставе.', 'Ты говорил c Рунтогом? Отличный дворф! Он хорошенько следит за своими грифонами, они должны быть всегда готовы к бою.$B$BЯ Грифонгар, я здесь самый главный. Может, тут не очень уютно, зато эта скала – важнейший опорный пункт для налетов на полуостров. Видишь грифонов, которые все время снуют туда-сюда?$B$BМогу дать совет, если хочешь. Держи вещмешок наготове, желудок впроголодь и не спускай глаз с горизонта. А когда Парящую заставу начнет раскачивать, хватайся за то, что хорошо приколочено!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10345, 'Усеял мертвыми костями...', 'Ты видишь эти трупы, $r? В этом убийстве повинен Арконус. Он высосал их досуха, оставив лишь мертвую плоть. Но не дай виду этих трупов обмануть тебя! Внутри них скрываются пожиратели плоти, готовые наброситься на любого, кто подойдет поближе.$B$BУ меня есть приказ – оставаться здесь, пока не прибудет подмога. Однако ты можешь взять мой поджигатель и уничтожить эти высохшие трупы, которыми забита шахта. Так или иначе, миссия должна быть выполнена!', 'Примените поджигатель Протектората к 12 высохшим трупам. Когда задача будет завершена, верните поджигатель Протектората посланнику Араксису, находящемуся у входа в шахту Зеон.', 'Ты спас мои обмотки, $N. Протекторат узнает о твоих деяниях.', 'Удалось ли тебе найти Йасека?', NULL, NULL, 'Сожжено высохших трупов', 'Поджигатель Протектората (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10346, 'Возвращение на Косогор Бездны', '$N, ты $gпоказал:показала: себя $gотличным наездником:отличной наездницей: на грифоне, так что можешь участвовать и в дальнейших вылазках к Косогору Бездны. Что скажешь, $C? Хочешь еще полетать?', 'Уничтожьте 20 ган\'аргов-батраков, 5 мо\'аргов-надзирателей и 5 пушек Скверны по просьбе грифоньера Ветрорева с Парящей заставы на полуострове Адского Пламени.', 'Ну, как на этот раз? Я вижу, ты в отличной форме! В самый раз для нового вылета!', 'На Косогоре Бездны осталось еще множество отличных мишеней, $N. Бери грифона да лети.', NULL, NULL, 'Ган\'арг-батрак убито', 'Мо\'арг-надзиратель убито', 'Уничтожено пушек скверны', 'Сюрприз из Зоны 52 (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10347, 'Возвращение на Косогор Бездны', '$N, $gготов:готова: к очередной вылазке к Косогору Бездны? Если мы прекратим постоянные атаки на Легион, то они так укрепят свои позиции, что потом на севере мы не отобьемся от демонов.$B$BЧто скажешь, $C? Хочешь слетать еще раз на Косогор Бездны и размолоть в пыль все, что попадется?', 'Уничтожьте 20 ган\'аргов-батраков, 5 мо\'аргов-надзирателей и 5 пушек Скверны по просьбе командира звена Бракка из Гибели Сквернобота на полуострове Адского Пламени.', 'Все пилоты ветрокрылов отзываются о тебе с уважением, $N. Ты уничтожил много целей на Косогоре Бездны. Так держать!', 'И пусть Легион не думает, что наверху, на Косогоре Бездны, они в безопасности. Мы еще не раз устроим им ковровую бомбардировку!', NULL, NULL, 'Ган\'арг-батрак убито', 'Мо\'арг-надзиратель убито', 'Уничтожено пушек скверны', 'Сюрприз из Зоны 52 (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10348, 'Новые возможности', 'Я слышал, что группа \"друидов\" с Азерота заинтересовалась эффектами технологии наших экосфер. $B$BПредставители Кенарийской экспедиции желают получить доступ к растениям, растущим внутри экосфер, в особенности к одному из них, именуемому \"кремовый колокольчик\" и известному своими целительными средствами. Густые заросли их встречаются вокруг более крупных растений в заповеднике \"Срединные земли\".$B$BЯ поделюсь с тобой доходами, если ты соберешь этой травки для первой партии товара.', 'Соберите 15 \"кремовых колокольчиков\" и вернитесь к Мердаду на Заставу срединных земель.', 'Интересный выбор, не так ли? Эти целительные свойства должны быть поистине чудотворными. Я вкладываю кучу денег в такую невзрачную травку.', 'Тебе удалось собрать травку?', NULL, NULL, 'Кремовый колокольчик', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10349, 'Землепряд', 'Отнеси этот кусок хрусталя Галандрии, землепряду. Знаешь, вы с ней похожи. Все время пытаетесь что-то там расследовать и придумать.$B$BПо-моему, она слишком много думает.$B$BОтдай ей этот кристалл, и я даже не сомневаюсь, что она тут же нагрузит тебя работой. Будешь выяснять, что же там все-таки происходит.', 'Отнесите осколок алого хрусталя заклинательнице земли Галандрии Ночной Бриз на Кенарийскую заставу на полуострове Адского Пламени.', 'О, прекрасно! Я давно хотела заполучить кусок этого кристалла, но Тола\'тион все время ставил мне палки в колеса.$B$BОн должен помочь мне понять, что случилось на Гряде Упавшего неба, но способен лишь посылать простофиль вроде тебя – только без обид – на убой.$B$BОтдай мне этот кристалл. Думаю, я смогу найти связь между ним и горными гигантами.', 'Это осколок того самого гигантского кристалла, который свалился на Гряде Упавшего Неба?', NULL, NULL, 'Осколок алого кристалла (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10350, 'Бехомат', 'Хотя я многому тебя научила, пришло время передать тебя более умелому учителю.$B$BБехомат наставлял меня, когда я была совсем неопытным воином, и именно ему я хочу доверить твое обучение. Я уже сообщила о твоем прибытии, и он ждет тебя.$B$BТы отыщешь его в центре Террасы воинов, в самой высокой части Торгового ряда в Экзодаре.', 'Поговорите с Бехоматом в Торговом ряду Экзодара. Награда: Шестопер наемника, Большой меч наемника, Ст$N наемника или Меч наемника.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10351, 'Целительная сила природы', 'Должно быть, горных великанов привлекают сюда эманации этого гигантского кристалла, которые затем и сводят их с ума.$B$BВряд ли мы сможем убрать отсюда кристалл - он слишком велик, и уничтожить его тоже не получится. Но есть один способ заглушить его излучение.$B$BЯ создала Круг на гряде к северо-западу от кристалла. Опусти туда это семечко, и пусть его сила исцелит землю с помощью дождя, растений и насекомых.$B$BОстерегайся, $N, я чувствую чужеродное вмешательство... так не должно быть!', 'Посадите Семя Возрождения в Круге землепряда, чтобы исцелить землю вокруг кристалла. После этого возвращайтесь к землепряду Галандрии Ночной Бриз на Кенарийскую заставу и расскажите о том, что получилось.', 'Голиафон? Паталеон Вычислитель?$B$BКЕЛЬ\'ТАС?!$B$BТут замешан принц Кель\'тас?$B$B*Землепряд шипит от злости*$B$BДа это же просто безумие! Уронить с неба гигантский кристалл и опустошить всю землю способен только безумец!$B$BМогу тебя заверить, Кенарийская экспедиция больше не допустит ничего подобного.$B$BМы в огромном долгу пред тобой, $N.', 'Ну что, сработало? Тебе удалось что-нибудь узнать? Ты выяснил, что случилось на гряде Упавшего Неба?', NULL, NULL, 'Гряда Упавшего Неба исцелена', 'Семя возрождения (Прилагается)', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10352, 'Пожертвование: шерсть', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Шерсть', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10353, 'Арконус Ненасытный', 'Араксес и я были отправлены в Ультрис два дня назад. Наша миссия: найти и уничтожить повелителя Бездны Арконуса. Мы проследили его до этой шахты и обнаружили, что он высасывает энергию из существ, обитающих в этом регионе.$B$BВо время последовавшей перестрелки мы с Араксесом потеряли друг друга из вида. И вот я застрял здесь, тяжело раненный. Наша миссия в опасности!$B$BЕсли ты сможешь избавиться от Арконуса, наше командование будет тебе признательно. В том случае, если ты возьмешься за эту миссию, я помогу тебе – дам тебе в охранники свое отражение.', 'Посланник Иасикс, находящийся у входа в шахту Зеон, просит вас убить Арконуса Ненасытного и вернуться к командиру Амиру на заставу стражи Протектората в Пустоверти.', 'А Йасек? Он это сделал?$B$BБудем надеяться, что да. Мне не удалось послать им подкрепление... Теперь весь регион захвачен Братством Эфириум.$B$BПрошу прощения, я едва не забыл про твою награду.', NULL, NULL, NULL, 'Арконус Ненасытный убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10354, 'Пожертвование: шелк', '', '', 'Прекрасно! $N, благодарим тебя за щедрое пожертвование!', NULL, NULL, NULL, 'Шелковый материал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10355, 'Иссохшее тело', 'Нам необходимо определить, насколько велик причиненный урон. Принесенная тобой высохшая базидия принадлежит болотоходу. Их более крупные и мощные родичи, болотники, должны были оказаться более устойчивыми к вырождению, которое поразило великанов.$B$BХорошо было бы выяснить, как перемены в Мертвой трясине повлияли на других обитающих там созданий.$B$BВернись в Мертвую трясину и попробуй добыть образцы обитающих там болотников и гидр.', 'Соберите 5 образцов опаленной гидры и 5 образцов ткани высохшего болотника и принесите их Руаму в Телредор.', '*Руам изучает образцы. Вид у него озабоченный.*$B$BЭтого я и боялся, $N! Снижение уровня влажности окружающей среды отрицательно сказывается на всех болотных организмах. Нам придется продолжать свои наблюдения и проконсультироваться с Кенарийской экспедицией, чтобы выяснить, можно ли что-то предпринять.', 'Ну что, удалось тебе собрать образцы?', NULL, NULL, 'Образец ткани опаленной гидры', 'Образец ткани высохшего болотника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10356, 'Пожертвование: магическая ткань', '', '', 'Спасибо за щедрость, $N.', NULL, NULL, NULL, 'Магическая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10357, 'Пожертвование: руническая ткань', '', '', 'Спасибо за щедрость.$B$BЕсли ты сочтешь возможным продолжать пожертвования, я прослежу, чтобы о тебе узнали наши предводители в Экзодаре.', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10358, 'Больше рунической ткани', '', '', 'Благодарю за помощь, $N.', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10359, 'Пожертвование: шерсть', '', '', 'Ты принес шерстяную ткань! Жители Луносвета никогда не забудут твоей щедрости.', NULL, NULL, NULL, 'Шерсть', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10360, 'Пожертвование: шелк', '', '', 'Ты принес шелк! Жители Луносвета никогда не забудут твоей щедрости.', NULL, NULL, NULL, 'Шелковый материал', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10361, 'Пожертвование: магическая ткань', '', '', 'Ты принес магическую ткань! Мы никогда не забудем твоей щедрости.', NULL, NULL, NULL, 'Магическая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10362, 'Пожертвование: руническая ткань', '', '', 'Все как договорились! Ты принес мне руническую ткань, а я замолвлю за тебя словечко перед жителями Луносвета.', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10363, 'Больше рунической ткани', '', '', 'Что ж, вижу, ты справился с заданием. Теперь у меня еще больше рунической ткани!', NULL, NULL, NULL, 'Руническая ткань', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10364, 'Кедмос', 'Тебе удалось многого добиться за короткое время, $N. Гораздо больше, чем можно было надеяться. Пришло время продолжить обучение под руководством Кедмоса.$B$BОн уже получил вести о тебе и дожидается твоего прибытия в Экзодаре. Его можно найти в святилище анахоретов неподалеку от входа в Чертог Света.', 'Поговорите с Кедмосом в Чертоге Света Экзодара.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10365, 'Отключить манагорн Ара', 'Тебе удалось справиться лучше, чем ожидал кто-либо из нас. Манагорн Ара – последний работающий манагорн, оставшийся в распоряжении Келя. Он находится к северо-западу отсюда, хотя для того, чтобы попасть сюда тебе, наверное, лучше пойти кружным путем. Тебе необходимо выключить его.$B$BПоследний кристалл доступа находится в распоряжении у надзиратель Азарада. Насколько нам известно, это последний источник энергии Келя, так что сопротивление будет яростным. На твоем месте я взял бы с собой нескольких друзей.$B$BХмм... Азарад. Странное имя для син\'дорай.', 'Отправляйтесь в манагорн Ара, заберите кристалл доступа Ара у надзирателя Азарадда. Используйте его на панели управления манагорном Ара, чтобы отключить его. Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Кель в сговоре с Пылающим Легионом? Ха! Ворен\'таль по потолку будет бегать от таких сведений.$B$BТы думаешь, тысячи паломников, собравшихся со всего Азерота, захотят союзничать с Пылающим Легионом? Я думаю, нет!', 'Удалось ли тебе выполнить задачу, о которой я говорил тебе, $N?', NULL, NULL, 'Отключите манагорн Ара', 'Кристалл доступа в Ару', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10366, 'Джоль', 'Следовать путем света и чистоты нелегко. Даже мне порой случается оступиться.$B$BПоговори с моей наставницей Джоль в Экзодаре. Она помогла мне сделать первые шаги на этом пути, и я не сомневаюсь, что ты станешь ее $gлучшим учеником:лучшей ученицей:.$B$BДжоль можно отыскать в Чертоге Света Экзодара. Найди святилище воздаятелей – это комната, окруженная сиянием.', 'Поговорите с Джоль в Святилище поборников в Экзодаре.', 'Я давно тебя поджидаю, $N.$B$BТуллас превозносит тебя до небес, и я с радостью продолжу учить тебя пути Света. Я помогу тебе лучше разобраться в своих способностях и скрытом могуществе, когда ты будешь готов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10367, 'Предатель среди нас', 'Везде, где есть пленные Сломленные, найдется и предатель. Ничтожное создание, продавшее своих собратьев в обмен на обещание власти.$B$BСреди руин, на ступенях, примостилась его жалкая лачуга.$B$BПредателя сейчас там нет, так что ты сможешь подкрасться незаметно, если будешь $gосторожен:осторожна:. Внутри стоит сундук, в котором лежит ключ. Это ключ от цепей пленных старейшин Отребья. Принеси его мне.$B$BБудь $gосторожен:осторожна:, где-то неподалеку бродит Арзет Безжалостный.', 'Добудьте ключ Ша\'наара, спрятанный в лачуге в руинах Ша\'наара неподалеку от Наладу.', 'Спасибо тебе, $N. Благодаря тебе мой народ скоро обретет свободу.', 'Тебе удалось достать ключ, $N?', NULL, NULL, 'Ключ Ша\'Наараа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10368, 'Старейшины Отребья', 'Дух племени Отребья сломлен, потому что наши старейшины томятся в плену. Возьми этот ключ и ступай вниз, чтобы освободить их.$B$BИх зовут Мород Ветродув, Акору Призыватель Огня и Айлаан Пробуждающий Воду. Если они станут свободны, духи вернутся к Отребью.', 'Освободите Морода Ветродува, Акору Призывателя Огня и Айлаана Пробуждающего Водув руинах Ша\'наара. После выполнения задания возвращайтесь к Наладу.', 'Я чувствую, $N! Духи вернулись к нам.', 'Ответь мне, $N. Свободны ли старейшины Отбросья?', NULL, NULL, 'Мород свободен', 'Акору освобожден', 'Айлаан освобожден', 'Ключ Ша\'Наараа (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10369, 'Наследие Арзета', 'Да, стихии снова вернулись к нам! Это не та сила, что была когда-то, но и немного магии в умелых руках может сделать многое.$B$BАрзет обладает великой мощью, дарованной ему исчадиями преисподней. Возьми этот посох. Когда-то он был великим символом нашего племени. Если его использовать против Арзета, посох на время лишит его силы. Уничтожь Арзета и освободи мой народ!', 'Используйте посох старейшин племени Отребья против Арзета Безжалостного. После того как Арзет потеряет силу, убейте его. После выполнения задания возвращайтесь к Наладу в руины Ша\'наара.', 'Да, это правда, $N. Когда-то меня звали Наладу, хранитель Земли.$B$BИменно я предал старейшин Отбросья в обмен на пустое обещание силы. Можешь презирать меня, если хочешь. Мне важно только одно, - мой народ снова свободен, и духи вернулись к нам.$B$BПусть я не смогу вернуться к своим собратьям, зато умру с чистой совестью. Пусть дух земли найдет себе нового служителя среди моего народа.', 'Ты справился $N? Азрет мертв?', NULL, NULL, 'Арзет Бессильный убито', 'Посох старейшин Отребья (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10370, 'Приказ Назгрела <TXT>', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10371, 'Йорус Ячменовар', 'Воин-дворф по имени Йорус Ячменовар бросил вызов всем воинам Альянса.$B$BОн ждет в таверне Приозерья, что в Красногорье в Восточных королевствах. Путь предстоит долгий, но возможность испытать свои силы стоит того.', 'Поговорите с Йорусом Ячменоваром в таверне Приозерья , что в Красногорье.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10372, 'Деликатная просьба', 'Эраланна, моя поверенная из Транквиллиона, попросила помощи в выполнении какого-то срочного задания.$B$BНе знаю, что там у нее случилось, но думаю, что ты в любом случае справишься. Отправляйся в Транквиллион, что в Призрачных землях, и поговори с Эраланной. $B$BСлов она не выбирает, но можешь верить ей без опаски.', 'Поговорите с Эраланной в Транквиллионе.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10373, 'Призыв к оружию: Чумные земли!', 'Слушайте, слушайте все! Я обращаюсь к героям, и да услышат они мою речь!$B$BВКороль Штормграда призывает к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Стало известно, что над Чумными землями вновь сгущаются тучи!$B$BГерои королевства! Ищите командира Ашлама Отважного Кулака! Его гарнизон вы найдете в лагере Промозглого Ветра на севере Альтеракских гор!', 'Найдите командира Ашлама Отважного Кулака в лагере Промозглого Ветра на севере Альтеракских гор.', 'Добро пожаловать в Чумные земли, героиня. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10374, 'Призыв к оружию: Чумные земли!', 'Внимайте моим словам, о герои! Орда призывает к решительным действиям!$B$BВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.$B$BХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лугов!', 'Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лугов и Подгорода.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10375, 'Обсидиановое боевое ожерелье', 'Ты много $gсделал:сделала: для нашего народа и всегда $gбыл:была: для нас $gверным другом:доброй подругой:, $N. $gГотов:Готова: ли ты еще раз доказать свою преданность и выступить с нами против сильнейшего из врагов?$B$BОгры Запределья', '', '', NULL, NULL, NULL, 'Обсидиановые боевые бусы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10376, 'Символ надежды', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10377, 'Ничего не бойся', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10378, 'Поглощение магии', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10379, 'Прикосновение слабости', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10380, 'Темный пакт', 'Мы были столь слепы, $N, что союз между двумя нашими наиболее опасными врагами остался незамеченным. $B$BНе удивлюсь, если Провидцы имеют какое-то отношение к сокрытию от нас этих сведений, однако теперь мы должны посмотреть в лицо реальности. Пылающий Легион и армия Ярости Солнца Кель\'таса ныне выступают под одним знаменем. $B$BПрисутствие этих демонов – единственная причина, по которой Кель\'тас вообще сумел использовать эту технологию в Крепости Бурь. По приказу Орелиса я должен откомандировать тебя уничтожить их.', 'Кайлаан, находящийся в Лагере Тулумана в Пустоверти хочет, чтобы вы убили 6 ган\'аргов-астральных ремонтников, 3 Дочерей Судьбы и 3 мо\'аргов-мастеров искажения.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Значит, дело сделано. Мы приходим сюда, выслеживаем их и убиваем по приказу нашего начальства. Не давать пощады и не ждать ее.$B$BИногда это заставляет задумываться.', NULL, NULL, NULL, 'Ган\'арг-астральный ремонтник убито', 'Дочь Судьбы убито', 'Мо\'арг-мастер искажения убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10381, 'Нет больше Алдора', 'Моя миссия здесь завершена. Я сделал то, что приказал мне Орелис, и ни в чем его не подвел.$B$BДовольно. Я предвижу кровавую резню – они называют это не то походом, не то маршем, – которая последует за известием о союзе между Кель\'тасом и Пылающим Легионом.$B$BСначала они отдают наш священный город нашим врагам, а затем просят нас умирать в сражении против их врагов. Возвращайся к Орелису; скажи ему, что наару отныне могут сами сражаться в собственных битвах.', 'Вернитесь с сообщением к Экзарху Орелису в Зону 52.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Дурные новости, принесенные тобою, наполняют мое сердце скорбью. Два наших злейших врага объединились, а один из самых любимых сынов Шаттрата утратил свой путь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10382, 'Отправка на фронт', 'Хорошо, $N, надеюсь, ты $gготов:готова: сделать следующий шаг. Легион никогда не отдыхает, - значит, и нам нельзя раслабляться. Возьми грифона и отправляйся в Оплот Чести, – это небольшой форт, расположенный рядом с передовой Легиона. $B$BПо прибытии доложи фельдмаршалу Броку, он тебя проинструктирует, что делать дальше. Да, и передавай привет этому бледномордому щитогрызу.', 'Долетите до Пика Чести на грифоне и поговорите с фельдмаршалом Броком.', 'Рад встрече, $C. Наконец-то этот твердолобый Хрустик решил прислать нам хоть какую-то помощь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10383, 'Хлебные крошки!', 'Привет. Разберись-ка с этими кроликами.', 'Поговорите с Джонатаном Лекрафтом насчет кроликов.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10384, 'Данные Братства Эфириум', 'Оглянись вокруг, создание из плоти и крови. Поблизости от этого передатчика должна находиться информационная ячейка Братства Эфириум. Найди эту ячейку, открой ее и забери содержимое.$B$BЗатем немедленно возвращайся обратно к передатчику!', 'Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас забрать данные из информационной ячейки Эфириума.', '<Ты держишь информационную ячейку так, чтобы Амир мог прочесть планы.>$B$BНичего нет... Проклятье! Они хитры, но не хитрее Амира!$B$BТо, о чем я хочу тебя попросить, очень опасно. Я пойму, если ты решишь отказаться, создание из плоти и крови...', 'Удалось ли тебе найти информационную ячейку?', NULL, NULL, 'Ячейка данных братства Эфириум', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10385, 'Риск поражения мозга – высокий', 'Они используют передающие кристаллы, чтобы обмениваться данными между полигонами.$B$BДля тебя есть только один способ увидеть эти кристаллы и извлечь хранящуюся в них информацию. К несчастью, это может привести к необратимым повреждениям мозга.$B$BЕсли ты не откажешься рискнуть, тебе нужно убить представителей Эфириума здесь, на полигоне, и забрать их сущности. Когда сущность окажется у тебя в руках, выпей ее. Это на какое-то время позволит тебе видеть ретрансляторы Эфириума – у тебя будет достаточно времени, чтобы уничтожить ретранслятор и извлечь из него данные.', 'Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас забрать 15 передач данных из ретранслятора Эфириума.', 'Теперь мы окончательно осознали причины создания Протектората.$B$BБратство Эфириума находится здесь не для того, чтобы охотиться на Пространствуса! Они намереваются стать пустотой!$B$BВ этом манагорне они манипулируют энергией Бездны для того, чтобы соединить собственную силу в создании, известном как ловчий нексуса.$B$BОни, несомненно, используют первичный ускоритель для завершения этой трансформации.', 'Удалось ли тебе забрать данные из кристаллов?', NULL, NULL, 'Данные ретранслятора Эфириума', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10386, 'Гроза скверноботов', 'Властитель Хан Изувер славится своими безумными атаками на Легион, и ему всегда нужны добровольцы. Опредленно, ты ему подходишь.$B$BЕсли считаешь, что у тебя хватит выдержки и безрассудства, пойди и поговори с ним. Он пьет с друзьями вон там, рядом с разбитым скверноботом. Они завалили его всего несколько часов назад. Скажу честно, если бы не Хан, мы все бы здесь полегли.', 'Поговорите с властителем Ханом Изуверским Кулаком.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10387, 'Гроза скверноботов', 'Властитель Хан Изувер славится своими безумными атаками на Легион, и ему всегда нужны добровольцы. Опредленно, ты ему подходишь.$B$BЕсли считаешь, что у тебя хватит выдержки и безрассудства, пойди и поговори с ним. Он пьет с друзьями вон там, рядом с разбитым скверноботом. Они завалили его всего несколько часов назад. Скажу честно, если бы не Хан, мы все бы здесь полегли.', 'Поговорите с властителем Ханом Изуверским Кулаком.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10388, 'Назад в Траллмар', 'Надеюсь, полет тебе понравился, $gприятель:подруга:. Пока тебя не было, прибыл посланник – кажется, Назгрел нашел для тебя новую работу. Лучше тебе вернуться обратно в Траллмар и доложиться ему лично. Есть у меня подозрение, что Легион снова что-то затевает.', 'Возвращайтесь в Траллмар и поговорите с Назгрелом.', 'О, $N, ты как раз вовремя. Наши разведчики обнаружили, что Легион установил на гребне так называемые \"лагеря Легиона\". Именно там демоны собирают своих адских скверноботов. Если мы проведем быструю атаку, то уничтожим все, что они успели сделать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10389, 'Тьма и агония', 'Приветствую, $N. Мне удалось перехватить шифрованное послание Легиона. В нем говорилось, что Легион собирает отряды исчадий ужаса на западе, рядом с прудами Аггонара. Нам нельзя оставаться в бездействии, зная, что враг стягивает силы. Ты $gдолжен:должна: отправиться туда и уничтожить их.', 'Убейте 10 исчадий ужаса у прудов Аггонара по приказу магистра Кровавого Ястреба.', 'Браво, $N. Я знал, что ты справишься. Наша победа над Легионом все ближе!', NULL, NULL, NULL, 'Исчадие ужаса убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10390, 'Лагерь Легиона: Магеддон', '$N, у нас есть все основания считать, что самый восточный лагерь Легиона еще до конца не оборудован. Ган\'арги-прислужники трудятся днем и ночью, чтобы ввести его в строй. Мы не должны им это позволить!$B$BСтупай к востоку в лагерь Легиона: Магеддон и уничтожь 10 ган\'аргов. Принеси мне голову их хозяина, Остропила, и пусть в наших землях больше не останется ни одного сквернобота!', 'Атакуйте лагерь Легиона: Магеддон, убейте 10 ган\'аргов-прислужников и вернитесь с головой Остропила к Назгрелу в Траллмар.', 'Отлично, $C. Одной головной болью меньше. У Пылающего Легиона займет немало времени снова доставить оборудование и наладить производство. А именно время и нужно нам больше всего.', 'Давай быстрее, $C. Надо уничтожить лагерь Легиона: Магеддон до того, как демоны запустят его в работу!', NULL, NULL, 'Ган\'арг-прислужник убито', 'Голова хозяина кузни Остропила', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10391, 'Пушки Ярости', 'К северо-востоку от Траллмара лежит вторая производственная база – лагерь Легиона: Ярость. Он расположен на гребне, и демоны установили там пушки Скверны, нацелив их прямо на нас. Ты $gдолжен:должна: проникнуть в лагерь и уничтожить эти пушки.$B$B$N, нужно обязательно взорвать их все, - иначе ничего не помешает Легиону обрушить на наши головы всю мощь преисподней.', 'Уничтожьте 3 пушки Скверны первой модели в лагере Легиона: Ярость и возвращайтесь к Назгрелу в Траллмар.', 'Я знал, что на тебя можно положиться, $N, но на этот раз ты превзошел самого себя. Мы аж отсюда слышали, как взрываются эти проклятые пушки. Надеюсь, это научит Пылающий Легион не связываться с Сынами Дуротара!', 'Легион может начать наступление в любую минуту, $N! Ты должен уничтожить эти проклятые пушки!', NULL, NULL, 'Пушка Скверны, модель I убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10392, 'Дверь в Бездну', 'Твои деяния – честь для всех нас, $N. Мы должны нанести новый удар, пока Легион не оправился от предыдущего! К северу от Траллмара лежит точка вторжения: Аннигилятор. Там находится искажающий портал, по которому Легион получает подкрепление.$B$BТебе нужно перегрузить этот портал так, чтобы он отправился обратно в бездну, которая его породила. Ключ активации портала находится у завоевателя Арикс\'Амала. Уничтожь его. Забери ключ. Открой им портал и сделай, что должно. Да пребудет с тобой благословение вождя!', 'Убейте Арикс\'Амала и заберите ключ врат Пылающего Легиона. Используйте ключ на Руне Злобы и возвращайтесь к Назгрелу в Траллмар.', 'Хвала предкам, ты сделал это, $N! Легион потерпел сокрушительное поражение, Траллмар снова спасен! О, если бы у меня было сто воинов, обладающих подобной ловкостью и несгибаемым духом, я бы уже очистил от скверны эти проклятые земли! Позволь выразить мое восхищение.$B$B*Назгрел отдает вам салют.*', 'Поторопись, $N. Пока открыт портал, каждую секунду в наш мир проникает еще один поганый демон!', NULL, NULL, 'Завоеватель Арикс\'Амал убито', 'Закрытие врат Пылающего Легиона', 'Ключ врат Пылающего Легиона', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10393, 'Коварные планы', 'Текст, судя по всему, написан на каком-то странном языке, неразборчивым и спутанным почерком. Чем больше вы на него смотрите, тем труднее что-нибудь разобрать, и в конце концов буквы начинают прыгать перед глазами. Похоже, понять этот странный почерк сможет одно существо в Траллмаре – эльф крови магистр Кровавый Ястреб.', 'Доставьте послание Пылающего Легиона магистру Кровавому Ястребу в Траллмар.', 'Молодец, что обратил мое внимание на это письмо. Это может быть заказ на дополнительное производство скверноботов, или даже планы новой атаки! Правда, расшифровка займет некоторое время. Ступай. Я повозу тебя, как только что-нибудь узнаю.$B$B*Магистр кивает вам и оборачивается, чтобы уйти.*$B$BА ты не промах, $N. Понаблюдать за тобой будет интересно.', 'У меня мало времени, $C. Что у тебя тут за ерунда?', NULL, NULL, 'Послание Пылающего Легиона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10394, 'Уничтожение – лагерь Легиона: Магеддон', 'Слушай меня внимательно, $N. Мы обследовали лагеря Легиона, которые лежат вдоль гребня. Судя по всему, Легион сооружает своих проклятых скверноботов именно в этих лагерях Легиона.$B$BБлижайшая цель, лагерь Легиона: Магеддон, находится на западе, его отсюда видно. Разведка донесла, что он еще не введен в строй. Если ты уничтожишь ган\'аргов-прислужников и их хозяина, Остропила, то сборка скверноботов прекратится на неопределенное время.', 'Убейте 10 ган\'аргов-прислужников и Остропила. После выполнения задания возвращайтесь к передовому командиру Броку на заставу Чести.', 'Ну, могу сказать, что твои подвиги меня впечатляют, $N. Не думал, что тебе хватит пороху выполнить это задание. Отлично. Да, отличная работа.', 'Только не говори мне, что ты трусишь, $C. Если они закончат строительство лагеря Легиона, то придется бояться еще и скверноботов. Ступай и выполняй приказ!', NULL, NULL, 'Ган\'арг-прислужник убито', 'Остропил убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10395, 'Темное послание', 'Текст, судя по всему, написан на каком-то странном языке, неразборчивым и спутанным почерком. Чем больше вы на него смотрите, тем труднее что-нибудь разобрать, и в конце концов буквы начинают прыгать перед глазами. Похоже, понять этот странный почерк сможет одно существо в Оплоте Чести – дренейский провидец бед Крив.', 'Доставьте послание Пылающего Легиона провидцу бед Криву в главную крепость Оплота Чести.', 'Нам очень повезло, что ты сумел перехватить это послание, $N. Мне понадобится время, чтобы его расшифровать, но даже сейчас я чувствую ненависть, исходящую от этого свитка. Боюсь, скрытые намерения Легиона скоро станут явными...$B$BОдну минуту, сейчас я расшифрую, что здесь написано.$B$B*Провидец бед Крив углубляется в демоническое послание.*', 'Что случилось, $C? Я чувствую, ты принес послание надвигающегося рока.', NULL, NULL, 'Послание Пылающего Легиона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10396, 'Враг моего врага...', 'Теперь мы должны сконцентрироваться на второй цели, – лагерь Легиона: Ярость. Он расположен к западу от Магеддона. Как ни странно, для нас проблема заключается в том, что демоны навели пушки Скверны прямо на Траллмар, заставу Орды! В это трудно поверить, но, оказывается, чтобы удерживать оборону Темного портала, нам нужна Орда. Траллмар не должен пасть. Я приказываю тебе уничтожить пушки Скверны, пока Легион не стер в порошок наших вынужденных союзников.', 'Уничтожьте 3 пушки Скверны первой модели в лагере Легиона: Ярость и возвращайтесь к фельдмаршалу Броку на заставу Чести.', 'Уж в чем - в чем, а в этом тебе не откажешь - ты прирожденный воитель, $N. Ордынские выродки даже не поняли, что были на волосок от смерти. Надо иметь настоящее понятие о воинской чести, чтобы подвергать себя опасности ради благополучия врага. Но именно такими солдатами и крепок Альянс!$B$B*Фельдмаршал Брок отдает вам салют.*', 'Легион может начать бомбить Орду в любую минуту, $N! Ты должен уничтожить эти проклятые пушки!', NULL, NULL, 'Пушка Скверны, модель I убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10397, 'Точка вторжения: Аннигилятор', 'Нам наконец удалось обнаружить последнюю базу Легиона на гребне. Это точка вторжения: Аннигилятор. Она лежит к северо-западу от лагеря Легиона: Ярость. Там находится искажающий портал, по которому Легион получает подкрепление.$B$BТебе придется подобраться к самому порталу, чтобы прекратить проникновение демонов в наш мир. Ключ от этого места находится у его владыки, завоевателя Арикс\'Амала. Достань этот ключ и уничтожь портал.', 'Уничтожьте Арикс\'Амала. Заберите ключ врат пылающего Легиона. Примените ключ на Руне Злобы.', 'Великолепно! Это значительно снизит число демонов, которые пытаются подобраться к нам с тыла. У меня нет слов, чтобы отблагодарить тебя за все, что ты для нас сделал, $N.', 'Тебе удалось подобраться к искажающему порталу, $N? Пока ты здесь переминаешься с ноги на ногу, в Запределье проникает все больше и больше демонов!', NULL, NULL, 'Завоеватель Арикс\'Амал убито', 'Закрытие врат Пылающего Легиона', 'Ключ врат Пылающего Легиона', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10398, 'Возвращение в Оплот Чести', 'PH: Вернуться в Оплот Чести', 'PH: Вернитесь в Оплот Чести.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10399, 'Сердце тьмы', 'Этого я и боялся. Арикс\'Амал, демон, которого ты $gубил:убила:, служил тайному владыке легиона – Араззиусу Безжалостному. Похоже, это новое воплощение зла стягивает силы, состоящие из исчадий ужаса, к прудам Аггонара.$B$BТы $gдолжен:должна: отправиться туда и уничтожить их, прежде чем они нападут на нас. Будь $gосторожен, друг:осторожна: подруга; пруды Аггонара лежат посреди искаженной, ядовитой долины. Ты найдешь их, если отправишься на северо-запад отсюда, к цитадели Адского Пламени.$B$BДа хранит тебя Свет, $N.', 'Убейте 10 исчадий ужаса у прудов Аггонара и возвращайтесь к провидцу бед Криву в главную крепость Оплота Чести.', 'Я предвидел эту великую победу, $N. Святые наару посылают тебе свое благословение.', NULL, NULL, NULL, 'Исчадие ужаса убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10400, 'Владыка', 'Благородный провидец рассказал мне, какие опасности тебя подстерегали, $N. Ты $gобнаружил:обнаружила: нового врага? Если верить Криву, то Араззиус Безжалостный, – один из самых могущественных и злобных недругов, с которыми приходилось сталкиваться Сынам Лотара.$B$BТы останешься с нами, $N? Сумеешь встретиться лицом к лицу с предводителем Легиона, и принести ему возмездие во имя Света? Если да, то ты найдешь его у прудов Аггонара. Если нет, то его злоба рано или поздно сама разыщет тебя.', 'Убейте Араззиуса Безжалостного у прудов Аггонара и возвращайтесь к командиру армии Данату Троллебою в крепость Оплота Чести.', 'Хвала Свету, я знал, что ты справишься! Больше нет Араззиуса и его прислужников! Скоро, очень скоро мы заставим Легион убраться с этих исстрадавшихся земель, и здесь снова воцарится мир. На эти земли придет справедливость,а мы сами сможем вернуться домой.$B$BСегодня Альянс и Сыны Лотара возносят тебе хвалу, $N!', NULL, NULL, NULL, 'Араззиус Безжалостный убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10401, 'Задание: со щитом или на щите', 'Знаешь, что будет, если тебе не удастся перехватить это донесение, $N?$B$B*Назгрел качает головой.*$B$BВ наши ворота постучится вся армия Легиона. И против них у нас не будет ни единого шанса.$B$BСуществует только один способ сделать так, чтобы это письмо не добралось до Передовой Легиона. Тебе придется отправиться к Прудам Аггонара, которые находятся на северо-западе отсюда, и убить Араззиуса.$B$BЕсли тебе это удастся, получишь собственную благодарность Вождя.', 'Уничтожьте Араззиуса Безжалостного по просьбе Назгрела из Траллмара на Полуострове Адского Пламени.', '', NULL, NULL, NULL, 'Араззиус Безжалостный убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10403, 'Наладу', 'Возможно, не вся надежда еще потеряна для Отребья. Я один из четырех старейшин, которые возглавляли племя, пока нас не поработили иллидари. Я думал, что все остальные мертвы, но мне удалось узнать, что живы по крайней мере двое из них. Они находятся в плену и лишены сил, так же, как и я сам.$B$BНо я не могу найти Наладу и опасаюсь самого худшего. Наверху, в руинах, много лачуг. Может быть, в одной из них ты разыщешь его. Если бы все четверо старейшин оказались живы, это было бы великим благом для нашего племени.', 'Отыщите Наладу в руинах Ша\'наара.', 'Ты пришел, чтобы помочь моему племени, $R? Необычно. В этих землях мало кого интересует судьба Сломленных.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10404, 'Против Легиона', 'Мы установили, что Пылающий Легион снабжал Кель\'таса помощью в области технологии, во много раз усилив опасность, представляемую его армией.$B$BСогласно количеству представителей Легиона в округе, самый большой удар, который мы можем нанести по нашим врагам – это прямая атака на кузнечные базы на севере.$B$BОтправляйся на базы Легиона: Забвение и Геенна и уничтожь наших врагов. Пусть Свет ведет тебя, $N.', 'Экзарх Орелис, находящийся в Зоне 52, просит вас отправиться на базы Легиона: Забвение и Геенна и убить 12 ган\'аргов – работников кузни, 6 мо\'аргов – начальников кузни и 6 вестников гнева. Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', '', NULL, NULL, NULL, 'Ган\'арг-анжинер убито', 'Хозяин кузни Кибергнева убито', 'Вестник Зла убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10405, 'С-А-Б-О-Т-А-Ж', 'Мы должны уничтожить машины, из-за которых возникают эти мерзкие астраусы... или астральные странники, как их там? Удар по их прото-ускорителю вряд ли подействует, поскольку его строили духи Астрала. Вместо этого мы должны уничтожить трубу, по которой от манагорна подается энергия.$B$BДля создания устройства, которое вызовет перегрузку трубопровода, у меня есть все, кроме одного предмета. Мне нужны обмотки архонта или властителя, которые можно трансформировать для того, чтобы откалибровать устройство.', 'Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас добыть 1 комплект готовых обмоток Эфириума.', 'Превосходно! Теперь можно откалибровать устройство.', 'Удалось ли тебе раздобыть обмотки?', NULL, NULL, 'Готовая астральная обертка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10406, 'Передать послание', 'Я высылаю одного из своих уничтожителей, чтобы он разместил разрушающее устройство. Необходимо, чтобы никто не причинил ему вреда, пока он устанавливает агрегат.$B$BВозьми его под защиту! Если на него нападут, он не сможет сражаться, поскольку он – всего лишь голографическая проекция, но эту проекцию можно уничтожить!$B$BВозвращайся ко мне, как только работа будет выполнена.', 'Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас сопроводить подрывника из Протектората к трубопроводу манагорна Ультрис и охранять его, пока он готовит диверсию на трубопроводе.', 'Благодаря тебе их планы рухнули! Теперь осталось только одно... Салхадаар.', 'Он должен добиться успеха!', NULL, NULL, 'Диверсия на трубопроводе прошла успешно', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10407, 'Тень Сокретара', 'Известный своими злобными деяниями эредар Сокретар возглавляет Пылающий Легион в Пустоверти. Одного упоминания его имени достаточно, чтобы заставить многих дренеев вздрогнуть. Он отдает приказы, сидя на острове к северо-западу отсюда. Только самые его доверенные лейтенанты могут попасть на этот остров.$B$BЧтобы добраться дотуда, мы должны заполучить камень телепортации, а это само по себе нелегкая задача. Первая половина камня находится у начальника кузни Моруга на базе Легиона: Забвение. Вторую половину хранит демон Силрот на базе Легиона: Геенна.', 'Анахорет Каржа, находящийся в Зоне 52, просит вас забрать первую половину камня Сокретара у начальника кузни Моруга с базы Легиона: Забвение и вторую половину камня Сокретара у Силрота с базы Легиона: Геенна.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Твоя преданность нашему делу просто невероятна, $N. Теперь, когда у нас есть камень телепортации Сокретара, осталось сделать еще только одно.', 'Удалось ли тебе добыть камень телепортации Сокретара, $N?', NULL, NULL, 'Первая половина камня Сокретара', 'Вторая половина камня Сокретара', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10408, 'Соправитель Салхадаар', 'У меня есть еще один дезинтегратор, способный уничтожить три контура, окружающие Салхадаара. Когда контуры будут уничтожены, защитное поле Салхадаара отключится. Однако за это он обрушит на тебя столь яростный удар, которого даже тебе, $N, прежде не приходилось испытывать.$B$BНо если ты желаешь избавить мир от Салхадаара, я отдам тебе дезинтегратор.', 'Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас использовать дезинтегратор Протектората, чтобы отключить защитное поле Салхадаара, а затем уничтожить Соправителя Салхадаара.', 'Прошла тысяча лет, а может быть, и больше, с тех пор как Салхадаар развязал войну на уничтожение против всех, кто становился у него на пути. Едва могу поверить, что мы больше его не узрим... Ты сослужил нам всем добрую службу, $N, и за это тебе положена награда.', 'Он... он действительно мертв? Уничтожен?', NULL, NULL, 'Соправитель Салхадаар убито', 'Дезинтегратор Протектората (Прилагается)', 'Рекомендуемое количество игроков: 5', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10409, 'Удар по Легиону', 'При столкновении с эредаром, наделенным великой мощью, большие армии чаще всего оказываются бесполезны. Влияние Скверны на смертные души так велико, что только самые сильные волей существа могут противостоять ему. $B$BОтнеси этот камень на точку вторжения: Властитель между базами Легиона: Забвение и Геенна; возьми с собой самых близких и надежных друзей. Орелис и Каржа встретят тебя у Трона Сокретара. Я пошлю с ними Адиена.$B$BДа победит сегодня Свет, $N. Да встретит Сокретар свою смерть!', 'Верховная жрица Ишана просит вас отправиться к телепорту Легиона в северо-западной части Пустоверти и использовать его, чтобы переместиться к Трону Сокретара.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Дело сделано, $N. Сокретар уничтожен.$B$BМои раны и раны всех остальных исцелятся, $N. Однако злобная магия Сокретара оказалась слишком сильна для юного Кайлаана. Даже самые отчаянные мои молитвы не смогут воскресить его.$B$BКак невыносимо жаль, что таким юным приходится умирать в бою. Однако в конце концов его воля оказалась достаточно сильна, чтобы очиститься от скверны Легион. Быть может, мы сумеем найти в этом утешение.', NULL, NULL, NULL, 'Удар по Легиону', 'Сокретарский камень Телепортации', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10410, 'Помощь Ишаны', 'Пришло время для прямого столкновения с Сокретаром, $N. Однако к противостоянию предводителю эредаров мы относимся всерьез. Если мы не подготовимся как следует, одна ошибка будет стоить нам жизни. $B$BОтнеси камень телепортации Сокретара верховной жрице Ишане в Святилище Вечного Света в городе Шаттрат.Она определит, как нам лучше действовать в этой ситуации.', 'Отнесите камень телепортации Сокретара верховной жрице Ишане в святилище Вечного Света на возвышенности Алдоров в Шаттрате. Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Сокретар... я помню это имя. Когда-то он был достойным воином Света, и единственным его изъяном была гордость.', 'Что тревожит тебя, дитя?', NULL, NULL, 'Сокретарский камень Телепортации (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10411, 'Слава электрошоку!', 'Вокруг разрушенного манагорна ты увидишь последствия действий Пространствуса. Сочащиеся слякочи наполняют пруды, окружающие Ультрис. Прямо под этими прудами, где сейчас размещается полигон Эфириума, ты найдешь еще больше утечек – то есть отбросы Бездны.$B$BЛучший способ избавиться от этого – использовать электрошок, чтобы разбить слизнюков на капли. Используй этот эликсир, чтобы снабдить свои атаки электричеством. Получившийся в результате разряд переведет слизнюков в более примитивную форму каплей. Уничтожь эти капли!', 'Ученый Навууд, находящийся на заставе стражей Протектората в Пустоверти просит вас уничтожить 30 каплей отброса Бездны и 30 сочащихся каплей слякоча.', 'Надеюсь, еще не слишком поздно. Не встретились тебе необычайно большие слизнюки в том районе, куда стекают отходы Бездны, или поблизости от этого района?', 'И грязь, и отходы чрезвычайно токсичны. Если оставить все как есть, они превратятся в густой ужас Бездны!', NULL, NULL, 'Сочащаяся капля слякоча убито', 'Капля отброса Бездны убито', 'Варево Навууда (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10412, 'Перстни Огнекрылых', 'Не секрет, что Кель\'тас Солнечный Скиталец видит в нас большую угрозу. И вообще-то он прав: мало кто из син\'дорай, только что прибывших из Луносвета, готов присоединиться к тем, с кем принц водит компанию.$B$BТакже не секрет и то, что война эта ведется не только на словах. Провидцы и армии Кель\'таса бросаются в атаку, едва завидев друг друга. Если ты действительно хочешь принять нашу сторону, $N, докажи это – прими участие в войне.$B$BНизшие офицеры Кель\'таса носят перстни Огнекрылых – принеси их мне.', 'Принесите магистру Файленн 10 перстней Огнекрылых.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Хорошая работа, $N. Возможно, вы и впрямь сможете оказаться нам полезным.', 'Ну же, $N. Говорите.', NULL, NULL, 'Перстень Огнекрылых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10413, 'Ужасы загрязнения', 'Ты осторожно наполняешь фиал ужасной слизью павшего ужаса Бездны.$B$BИсследователь Навууд на заставе стражей Протектората будет весьма заинтересован в такой находке! Немедленно доставь это к нему!', 'Отнесите фиал со слизью ужаса Бездны к ученому Навууду на заставу стражей Протектората в Пустоверти.', 'ЧТО?! Ты столкнулся с ужасом Бездны? И выжил? Невероятно!$B$BЦенность этого образца – просто на вес золота! Такие находки заслуживают награды.', 'Хмм, где это тебе так удалось испачкаться? Во что ты вляпался?', NULL, NULL, 'Фиал со слизью ужаса Бездны (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10414, 'Перстень Огнекрылых', '', '', 'Да... Армия Келя скудеет, а наши ряды, наоборот, растут.$B$B<Это задание можно повторять до тех пор, пока вы не заслужите уважительное отношение.>', NULL, NULL, NULL, 'Перстень Огнекрылых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10415, 'Больше перстней Огнекрылых', '', '', 'Прекрасно! Пусть все наши враги исчезнут!$B$B<Это задание можно повторять до тех пор, пока вы не заслужите уважительное отношение.>', NULL, NULL, NULL, 'Перстень Огнекрылых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10416, 'Преобразование силы', 'Чародейские фолианты – это вам не просто книжки про магию. В них содержится большая сила, и я научился сосредотачивать ее в одной-единственной чародейской руне.$B$BЕсли вам попадется чародейский фолиант, то я с радостью обменяю его на такую руну, но фолианты бывают только у очень могущественных существ. В Запределье ими обычно владеют эльфы крови, последователи Келя, но вообще эти книги могут попасться где угодно.', 'Принесите чародейский фолиант Ворен\'талю Предсказателю в Шаттрат.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Вот, $N, как и обещал: вся сила книги, заключенная в одну руну.', 'А, $N! Как идут поиски чародейского фолианта?', NULL, NULL, 'Чародейский фолиант', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10417, 'Провести диагностику', 'Где бы Консорциум ни заявил о своем присутствии, мы приходим туда со своей технологией экосфер. Защитное поле позволяет нам работать в тщательно контролируемой благоприятной атмосфере, поскольку окружающая среда часто бывает враждебной. $B$BСуровые условия Пустоверти и обитающие здесь существа причиняют вред оборудованию, генерирующему наши сферы; в особенности пострадал генератор, находящийся к востоку отсюда. Я запустил там диагностику, надеясь понять, что можно сделать, дабы уменьшить ущерб. Не можешь ли ты снять показатели диагностики и доставить их мне?', 'Заберите результаты диагностики и доставьте их Мердаду на Заставу срединных земель.', '<Мердад кивает, затем изучает результаты диагностики.>$B$BТревожные показатели. Ущерб гораздо сильнее, чем я считал. Я могу послать в Штормовую Вершину за инструментами для ремонта, но это бесполезно, если мы, в первую очередь, не защитим генератор от того, что так сильно повредило его.', 'Удалось ли тебе снять результаты диагностики?', NULL, NULL, 'Результаты диагностики', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10418, 'Покончить с вредителями', 'Обыскивая район в поисках того, что причинило такой ущерб нашему оборудованию, я заметил детали генератора защитного поля на дне маленького озера к северу отсюда. Не знаю, почему кроколисков так заинтересовало оборудование, но мы должны устранить эту проблему.$B$BМнение Консорциума по этому вопросу ясно. Если дело доходит до выбора между оборудованием и кроколисками, животным придется уступить. Думаю, ты не откажешься взяться за это дело.', 'Мердад, находящийся на Заставе срединных земель, просит вас убить 8 шипастых кроколисков.', 'Этот район уже выглядит более чисто. Эти сферы довольно полезны, но у них есть недостатки – они ускоряют рост некоторых местных видов животных и растений.', NULL, NULL, NULL, 'Шипастый кроколиск убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10419, 'Чародейские фолианты', '', '', 'Этот фолиант наделен потрясающей силой! Однако тот, чей разум ясен, сумеет без труда заключить ее в одну руну.', NULL, NULL, NULL, 'Чародейский фолиант', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10420, 'Очищающий Свет', 'Этот храм – одно из самых священных мест в Запределье. Сила Света здесь настолько велика, что может очистить предметы, сильнее других пострадавшие от Скверны.$B$BЕсли тебе попадутся латные перчатки Скверны, – а это наверняка произойдет после нескольких схваток с демонами, – принеси их мне, и я продемонстрирую тебе всю очищающую силу Света.', 'Принесите латные перчатки Скверны Ишане в Шаттрат.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Смотри, как распадаются оскверненные материалы. Смотри, как металл обращается в пыль.$B$BСвет очищает все, оставляя лишь чистейший осадок.', 'Вам удалось добыть латные перчатки Скверны, $N?', NULL, NULL, 'Боеприпасы Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10421, 'Латные перчатки Скверны', '', '', 'Скверна изгнана из этого мира, остался лишь чистый светлый осадок.', NULL, NULL, NULL, 'Боеприпасы Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10422, 'Капитан Тиралиус', '10 дней назад капитан Тиралиус повел взвод солдат на юг, к полигону Эфириума. С тех пор мы ничего не слышали ни о нем, ни о его подчиненных.$B$BВероятнее всего, они попали в засаду и были убиты, однако мои приборы выдают любопытные показания.$B$BМне кажется, это сигнал бедствия, однако эти штуки и прежде ошибались. Если Тиралиус еще жив, они держат его в одной из тюрем. Тебе нужно отыскать эту тюрьму и открыть ее ключом, который, вероятнее всего, находится у стражника.', 'Укротитель плоти Виридиус, находящийся на заставе стражей Протектората в Пустоверти, просит вас найти и освободить капитана Тиралиуса.', 'Спасибо, $N. Тиралиус получил тяжелые ранения, но мы думаем, он выживет.$B$BОн упоминал, что тюрьмы, подобные той, в которой держали его, знаимают целые поля. И эти тюрьмы полны существ со всей вселенной!$B$BХорошо, что мы в курсе - на случай, если потребуется открыть все эти темницы. Консорциум уже выразил некий интерес в том, чтобы выслать туда специальные команды и поработать над технологией взлома замков Эфириума.', NULL, NULL, NULL, 'Капитан Тиралиус освобожден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10423, 'В Штормовую Вершину', 'Старший инженер Габар будет рад узнать результаты диагностики. Кстати, нас предупредили, что нужно присматривать за работой наших генераторов экосферы. По мере того, как поле делается все более и более нестабильным, его эффект становится труднее контролировать. Это может завершиться катастрофой для нашей экспедиции и для всех, кто обитает под сферой.$B$BТы найдешь Габара в Штормовой Вершине. Просто иди по дороге на север от этой экосферы, через мост. Она приведет тебя к подъемнику у подножия Вершины.', 'Поговорите с Гхабаром на Штормовой Вершине в Пустоверти.', '<Ты представляешься и сообщаешь результаты диагностики, проведенной Мердадом для заповедника \"Срединные земли\".>$B$BМердад – всего лишь техник, однако у него острый глаз на всякие мелочи. Если его наблюдение верно, нам нужно как можно скорее провести диагностику остальных наших генераторов экосферы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10424, 'Диагноз: критический', 'Если результаты, полученные Мердадом верны – а у меня нет причин в этом сомневаться – то остальные экосферы в опасности.$B$BНо я думаю, что Мердад не сумел опознать истинную причину неполадок. Время от времени разные твари повреждают генераторы, но не настолько сильно. $B$BРади пущей безопасности я попросил бы тебя провести диагностику главного генератора экосферы Штормовой Вершины. Этот генератор находится в заповеднике \"Сатерон\" у самого восточного края сферы.', 'Используйте диагностическое устройство, стоя поблизости от генератора экосферы заповедника\"Сатерон\", и отнесите результаты диагностики Габару в Штормовую Вершину.', 'Эти результаты точно совпадают с тем, что получил Мердад. Но почему? Единственное возможное объяснение, которое приходит мне в голову – это то, что часть деталей генераторов сферы вышла из строя или пропала. Это может значительно ослабить защитное поле сферы и вызвать дисбаланс, как указывают все результаты диагностики.', 'Удалось ли получить результаты диагностики?', NULL, NULL, 'Результаты диагностики', 'Диагностический прибор (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10425, 'Побег с полигона', 'Во имя К\'ареша! Он разорвал бы меня на части.$B$BЯ солдат Протектората. Мой взвод был послан на разведывательную миссию примерно 10 дней назад. Когда мы продвигались через верхние уступы этого острова, на нас напал отряд Братства Эфириума. По крайней мере, я думаю, что они были из Братства Эфириума. У них тот же самый цвет энергии, но обмотки выглядели так, словно сделаны из пустоты.$B$BВ живых остался только Тиралис. Думаю, они бросили его в темницу.$B$BЯ должен добраться до заставы стражей Протектората! Не можешь ли ты сопроводить меня?', 'Сопроводите пленного передового бойца Протектората обратно на заставу стражей Протектората в Пустоверти.', '<Командир Амир выглядит довольным.>$B$BХорошая работа, существо из плоти и крови! Этот солдат может дать нам ключ к разрушению всех планов Братства Эфириум.', NULL, NULL, NULL, 'Пленный передовой боец Протектората сопровожден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10426, 'Растительность заповедников', 'Только оглянись вокруг, $C! Разве это не удивительно? Конечно же, это невероятное возрождение жизни является побочным продуктом астральных сфер, но представь себе, что они попадут в руки нашей экспедиции. $B$BЯ готовлюсь вести переговоры с духами Астрала относительно доступа к их технологии, однако у меня есть лучшая идея касательно их воздействия на растительный мир.$B$BЯ создала прибор, способный сконцентрировать энергию сферы на хлестунах, растущих в этой зоне. Может быть, ты окажешь мне услугу – проверить действие этого прибора и поделиться со мной результатами?', 'Используйте модулятор энергетического поля на фаралонских плеточниках. Пронаблюдайте результаты и после того, как проведете 10 тестов, сообщите результаты Аурин Лунное Сияние, находящейся в Штормовой Вершине.', 'Ничего себе! Фокусирование энергии сферы, похоже, продолжает ускорять рост до той степени, на которой он порождает необычайную агрессию. Если мы действительно получим возможность использовать эту технологию, мы должны убедиться, что взяли правильные значения.', 'Удалось ли тебе сфокусировать энергию сферы?', NULL, NULL, 'Испытайте модулятор энергетического поля', 'Модулятор энергетического поля (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10427, 'Животные заповедников', 'Твоя работа с хлестунами дала нам неоценимые сведения, однако мне интересно, применимы ли они и к животным тоже?$B$BБоюсь, собирать информацию о талбуках, живущих под этой сферой, будет сложнее, чем изучать хлестуны.$B$BИспользуя это метящее устройство, ты можешь погрузить в сон ослабевшего талбука и нацепить на него метку, чтобы я могла следить, как он взрослеет. Механизм установки метки не сработает, если талбук не израсходовал большую часть своих сил.', 'Пометьте 12 талбуков для Аурин Лунное Сияние из Штормовой Вершины. Вы можете метить как самцов, так и самок талбуков, используя метчик для талбуков.', 'Превосходно. Я буду присматривать за помеченными особями и проверю, взрослеют ли они так же быстро, как другие формы жизни в сфере.$B$BПри наличии должного контроля мы сможем использовать эту технологию, чтобы восстановить разрушенные участки Запределья и Азерота.', 'Тебе удалось пометить достаточное число талбуков?', NULL, NULL, 'Помечено талбуков', 'Метчик талбуков (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10428, 'Пропавший рыбак', 'Мечась во сне, наша раненая гостья упоминала о рыбаке Коулене, который попал в беду на острове Серебристой Дымки, на юго-западе от побережья острова Лазурной Дымки.$B$BВ ту пору на нас свалилось множество бед, и никто не смог заняться этим делом. Может быть, ты возьмешь его на себя, $N?', 'Найдите Коулена на юго-восточной пристани острова Серебристой Дымки, неподалеку от побережья острова Лазурной Дымки.', 'Моя семья... Что я наделал... Но что я мог изменить?$B$BЗа что мне такие мучения?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10429, 'Когда природа заходит слишком далеко', 'В технологии эко-сфер задействовано столько энергии! Определенно, есть границы, за которые мы не смеем выходить, $N.$B$BКогда живые существа вырастают слишком быстро или слишком большими, это так же плохо, как и полное отсутствие жизни. $B$BДо меня доходили слухи, что одно такое существо обитает в пруду на востоке отсюда. Я слышала, что торговцы из числа духов Астрала сговорились поймать эту гидру для забавы, однако у меня на нее другие виды. Принеси мне сердце этого существа, чтобы я могла его изучить.', 'Аурин Лунное Сияние из Штормовой Вершины просит вас принести ей сердце гигантской гидры.', '<Аурин берет сердце.>$B$BЭто сердце слишком велико, даже для существа такого размера. Оно росло так быстро, чтобы угнаться за ростом гидры. Не сомневаюсь, что это создание умерло бы, не прожив и половины отпущенного природой срока.$B$BНо даже при наличии подобного риска я намереваюсь убедить Консорциум поделиться их технологиями. Они слишком многообещающи, чтобы мы могли сдаться.', 'Удалось ли тебе добыть образец тканей этой чудовищной гидры?', NULL, NULL, 'Сердце огромной гидры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10430, 'Испытание прототипа', 'Я работал над ремонтным набором для переносных генераторов для использования в суровом климате, где осуществляет свои действия Консорциум. Конечно, он не был предназначен для Пустоверти, но с этим проблем быть не должно.$B$BЯ уже составил план испытаний с участием одного из моих лучших техников – он сейчас находится в заповеднике \"Дальнее поле\" за Осколками Пустоты, на северо-востоке отсюда. Отнеси этот прототип Ташару. Он знает, что с ним делать. Если это сработает, мы сможем использовать данный прибор, чтобы усилить генераторы поля в крупных экосферах.', 'Отнесите ремонтный аппарат Ташару в заповедник \"Дальнее поле\" в Пустоверти.', 'Выглядит несколько странно. Гхабар определенно не думал о Пустоверти, когда разрабатывал это.$B$BНе смотри так удивленно, $N. Пустоверть - просто курорт по сравнению с некоторыми местами, где мне приходилось работать. Тем не менее, отказ генератора сферы - это всегда неприятно.', 'Похоже, это у тебя прототип. Тебя послал Гхабар?', NULL, NULL, 'Экспериментальный ремонтный аппарат (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10431, 'Помощь извне', 'Инструкции клана Ярости Солнца подтверждают теорию о том, что для сооружения манагорнов и управления ими Кель\'тас получил помощь извне. От кого именно, остается загадкой, но мы, скорее всего, узнаем это в манагорне Ара.$B$BЯ послал группу своих подчиненных обследовать прилегающий район. Отправляйся в лагерь Тулумана, находящийся к северу отсюда, и поговори с Кайлааном. Спроси, что он обнаружил возле манагорна Ара. Узнай, кто помогает армии Ярости Солнца, и прими меры.', 'Идите в Лагерь Тулумана, на север от Зоны 52, и поговорите с Кайлааном. Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Орелис прислал на помощь только тебя? Должно быть, он о тебе очень высокого мнения. $B$BЧто ж, к делу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10432, 'Надежное свидетельство', 'Как ты, наверное, $gзаметил:заметила:, в манагорне Ара полно прислужников Пылающего Легиона. Кель\'тас заключил союз с Пылающим Легионом. Должно быть, он учуял, что Иллидан впадает в безумие, и потому сменил хозяев.$B$BЕсли Провидцы получат твердое доказательство этого, то у них будет значительное политическое преимущество. Мне известно, что войска Легиона, расквартированные в этом манагорне, получили от Кель\'таса приказы с его личной печатью.$B$BЗаполучи эти приказы и отнеси их Талодиену.', 'Заберите у демонов, находящихся в манагорне Ара 8 приказов Кель\'таса и отнесите их патрону шпионов Талодиену в Зону 52.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Это важно, $N. Очень важно!$B$BВорен\'талю нужно услышать это как можно скорее.', 'Ну? Что хотел сказать мне $N?', NULL, NULL, 'Распоряжения Кель\'таса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10433, 'Поддерживая видимость', 'Эфириалы умны и очень наблюдательны, так что я не случайно здесь изображаю простого скорняка. На самом деле меня послали из Зоны 52, чтобы взглянуть на технологию, которую эфириалы используют для создания своих экосфер.$B$BЯ хочу попросить тебя о помощи, $C. Нам нужно как можно чаще задействовать агентов, не принадлежащих к расе гоблинов.$B$BТак вот, притворись, что охотишься, и принеси мне несколько шкур рыси-клыкодера. Рыси встречаются вокруг заповедника \"Срединные земли\".', 'Принесите 10 шкур рыси-клыкодера Шоли Пору на Заставу срединных земель.', '<Шоли демонстративно осматривает шкуры.>$B$BОни великолепны, просто великолепны! Я заплачу по самой высокой цене! Ты не против еще пару раз оказать мне услугу?', '<Шоли возвышает голос, словно бы для того, чтобы привлечь внимание всех духов Астрала в округе.>$B$BНу что, есть шкуры на продажу?', NULL, NULL, 'Шкура рыси-клыкодера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10434, 'Динамический дуэт', 'Прекрасно.$B$B<Шоли подмигивает вам.>$B$BЯ думаю, они это купят. Если я пошлю тебя поговорить с моими коллегами в Штормовой Вершине, то никаких подозрений это не вызовет.$B$BПоищи там Джема Бондса и Оди Иголку. Они расскажут тебе все, что нужно. Скажи им, что тебя послал Шоли.', 'Поговорите с Оди Иголкой на Штормовой Вершине в Пустоверти.', '<Вы представляетесь и говорите Оди, что вас послал Шоли.>$B$BАх да, мы ждали, что кто-нибудь придет и поможет нам... э-э... переместить кое-какие товары.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10435, 'Сбор деталей', '$gОди озирается по сторонам и понижает голос.>$B$BЯ уверена, что Шоли кое-что рассказывал тебе о нашей работе здесь. Когда мы с Бондсом ходили на \"охоту\", мы собирали детали генераторов экосфер эфириалов и прятали их в гнездах ящеров, на которых охотились в заповеднике \"Дальнее поле\".$B$BЭто удаленный регион к северо-востоку от Штормовой Вершины, поблизости от Осколков Пустоты. Вряд ли тебе там встретится много эфириалов, так что не согласишься ли ты помочь нам забрать детали генераторов экосферы?', 'Оди Иголка, находящаяся в Штормовой Вершине, просит вас принести ей 10 сегментов генератора защитного купола.', 'Прекрасно! Самая трудная часть проекта завершена. Теперь все, что нам нужно, – это вернуться обратно в Зону 52 и привлечь внимание Кенарийской экспедиции. Здесь достаточно для того, чтобы и самим применить это на деле, и немного заработать на стороне.', 'Все ли удалось собрать?', NULL, NULL, 'Сегмент генератора защитного купола', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10436, 'Все чисто!', 'Прежде чем мы найдем испытание, мы должны убедиться, что в районе нет никого, кто мог бы вмешаться. В нашем случае - это вон те ящерицы-переростки.$B$B*Ташар указывает в сторону cаблезубых ящеров.*$B$BНет смысла говорить, что случится, если один из них решит попробовать на вкус наш генератор, пока он заряжается. За много лет на должности техника я видел много странных вещей, в том числе и изрядное количество мерзких тварей, которые изначально были довольно милыми зверушками.', 'Ташар, находящийся в заповеднике \"Дальнее поле\", просит вас убить 12 саблезубых ящеров.', 'Отлично. Похоже, все в порядке. Мы готовы приступать.', 'Удалось ли очистить зону испытаний?', NULL, NULL, 'Саблезубый ящер убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10437, 'Рецепт уничтожения', 'Наверху манагорна Ультрис находится разрыв в Пустоте, через который пришел повелитель пустоты Пространствус. Этот разрыв обеспечивает Пространствусу связь с Пустотой, что дает ему невосприимчивость к физическому урону. Если бы мы могли навестись на стержень Пустоты, при помощи которого Пространствус сохраняет себя вне этого мира, то мы могли бы уничтожить разрыв, а потом и самого Пространствуса.$B$BЧтобы сделать это, для начала собери фрагменты Пространствуса, отняв их у тварей Пустоты, которых тот посылает для выполнения грязной работы.', 'Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы собрали 8 фрагментов Пространствуса.', 'Превосходно! При помощи этих фрагментов мы сможем настроить бомбу, которая уничтожит стержень Бездны над Ультрисом. Когда стержень Бездны будет уничтожен, связь Пространствуса с Бездной оборвется и он останется без защиты.', 'Удалось ли тебе собрать достаточно фрагментов?', NULL, NULL, 'Фрагмент Пространствуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10438, 'На крыльях Пустоты', 'Вот, $N. Возьми этот фазовый дезинтегратор и забирайся в седло. Дракон Пустоты Протектората доставит тебя достаточно близко к Ультрису, чтобы сбросить дезинтегратор на стержень Бездны.$B$BСкинь как можно больше дезинтеграционных зарядов, чтобы уничтожение было полным!$B$BКогда все будет сделано, скажи дракону Пустоты и он унесет тебя ввысь.$B$BЕсли промахнешься, то прежде, чем снова идти на задание, возьми у меня еще бомбы.', 'Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы использовали фазовый дезинтегратор, когда окажетесь вблизи от стержня Бездны наверху Ультриса. Скиньте как можно больше зарядов фазового дезинтегратора, чтобы обеспечить полное уничтожение. Заряды фазового дезинтегратора автоматически попадут в стержень Бездны, если вы будете достаточно близко, чтобы использовать их.Если вы преуспеете, возвращайтесь к профессору Дабири!', 'Настало время нанести удар! Когда разрыв исчезнет, Пространствус будет уязвим для физических и магических атак!', NULL, NULL, NULL, 'Стержень Бездны уничтожен', 'Фазовый дезинтегратор', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10439, 'Пространствус Всепоглощающий', 'Твои отважные подвиги заставили Амира действовать! Он отрядил капитана Саида и Мстителей!$B$BТеперь все, что осталось – это уничтожить Пространствуса.$B$BКогда все будет готово, я вызову Саида. Если он сейчас не сражается в очередной битве, он будет ожидать твоих приказов – ищи его к востоку отсюда.$B$BКогда подготовишься к сражению, уведоми его, и он поведет свои войска.$B$BЖелаю тебе удачи, о существо из плоти и крови! Мы охотились за Пространствусом тысячи лет!', 'Профессор Дабири, находящийся на заставе Протектората в Пустоверти, хочет, чтобы вы поговорили с капитаном Саидом, а потом вместе с его армией проследовали к манагорну Ультрис и убили Пространствуса Всепоглощающего!', 'На протяжении тысяч лет мы не знали ничего, кроме войны. Мы защищали наш народ от нападений тварей Бездны и эфириалов в равной степени.$B$BНыне один из самых ненавистных наших врагов мертв – наконец-то.$B$BО существо из плоти и крови, знай, что тебе благодарны сотни миллионов эфириалов!', 'Так что насчет повелителя Бездны?', NULL, NULL, 'Пространствус Всепоглощающий убито', 'Поговорите с капитаном Саидом', 'Рекомендуемое количество игроков: 5', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10440, 'Готово!', 'Проверка показала небывалый успех! Мы, несомненно, можем использовать этот прибор для починки сфер.$B$BСообщи о результатах проверки в Штормовую Вершину и дай Габару знать, что я, помимо этого, обнаружил некую схему в повреждениях генераторов поля. Из ряда мест пропали ключевые детали генераторов. Это не несчастный случай, $N, и не технологическая ошибка. Это намеренная кража.', 'Вернитесь в Штормовую Вершину, что в Пустоверти, и поговорите с Гхабаром.', 'Я немедленно пошлю своих техников на работу по починке.$B$BОднако подозрения Ташара относительно саботажа тревожат меня. Не могу вспомнить никого, кто оказался бы достаточно дерзок, чтобы взяться за похищение наших технологий. Во всяком случае, из тех, кто знает, на что мы способны. Быть может, настало время ограничить доступ в Штормовую Вершину.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10441, 'Торговля по мелочам', '<Оди снова понижает голос.>$B$BТеперь, когда у нас есть товар, я отошлю большую часть деталей в Зону 52. Их здесь достаточно, чтобы собрать не один генератор, и это дает идеальную возможность провернуть дельце.$B$BЯ видела, как представительница Кенарийской экспедиции пытается торговаться. Вот чего я хочу: намекни ей, что мы можем обеспечить то, что она ищет, по вполне разумной цене. Зачем ей и дальше иметь дело с этими жуликами – духами Астрала?', 'Поговорите с Аурин Лунное Сияние у подножия Штормовой Вершины в Пустоверти.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10442, 'Помощь Кенарийской заставе', '$C, некий таурен по имени Тиа Красная Грива непрерывно докучает нам просьбами о помощи. Она из Кенарийской экспедиции, их застава находится к юго-западу от дороги, ведущей в Зангартопь.$B$BЭто не доходя до Холма Колючего Клыка.$B$BОтправляйся туда и выясни, чего ей надо. Я не собираюсь беспокоить капитана следопытов Венн\'рена по таким мелочам.', 'Отправьтесь на помощь Тие Рыжей Гриве на Кенарийскую заставу на полуострове Адского Пламени по просьбе сокольничего Дренны Речной Ветер.', 'О, слава богам, должно быть, тебя прислал на помощь Соколиный дозор! $B$BОчень рада тебя видеть. У нас тут столько работы! У меня как раз есть дело, которое будет тебе по плечу для начала...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10443, 'Помощь Кенарийской заставе', 'Как я понимаю, Круг Кенария отправил в Запределье экспедицию, чтобы узнать, что там случилось, и при необходимости оказать помощь.$B$BОни разбили лагерь к юго-западу от дороги, ведущей в Зангартопь, не доходя до Холма Колючего Клыка.$B$BМожешь отправиться к ним на помощь? Найди там Тиу Рыжую Гриву, это она просила нас прислать подкрепление.', 'Отправьтесь на Кенарийскую заставу на полуострове Адского Пламени и предложите помощь Тие Рыжей Гриве по просьбе Амаана Мудрейшего.', 'О, слава богам, должно быть, тебя прислали на помощь из храма Телхамат! Я туда обращалась.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10444, 'Послание для Заставы Аллерии', 'Нужно немедленно действовать!$B$BРядом с лагерем Огнекрылых есть кое-кто, с кем тебе нужно поговорить – он лучше знает, что делать дальше.$B$BНайди лейтенанта Меридиана на заставе Аллерии и объясни ему ситуацию. Застава находится к северо-востоку от южного берега реки, протекающей южнее лагеря Огнекрылых.$B$BПоспеши, $N.', 'Доложите обстановку лейтенанту Меридиану на заставе Аллерии в лесу Тероккар по поручению Дженайи Шепот Звезд.', 'Детали бомб. Значит, я был прав, хотя именно здесь мне хотелось бы ошибиться.$B$BЛадно, тогда нам с вами предстоит одно очень серьезное дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10445, 'Сосуды Вечности', 'Иллидан наполнил семь сосудов из Источника Вечности. Три из них он вылил в озеро на горе Хиджал и создал второй Источник. Долгое время считалось, что остальные четыре сосуда были утрачены.$B$BНо после того как открылся Темный портал, мы узнали, что Иллидан отдал по одному сосуду своим союзникам Кель\'тасу и Вайш. Найди эти сосуды и принеси нам. Без них мы не можем открыть временные проходы к событиям, так или иначе связанным с горой Хиджал, – ни к недавним, ни к древним. Мы должны позаботиться о том, чтобы ничто не смогло изменить исход битвы за Хиджал.', 'Соридорми из Пещер времени желает, чтобы вы принесли ей неполный фиал леди Вайш из резервуара Кривого Клыка и неполный фиал Кель\'таса из Крепости Бурь.', 'Даже в одной капле воды из Источника Вечности заключены невероятные силы.$B$BТеперь я могу прозревать время и видеть все, что когда-либо происходило на Хиджале... Создание второго Источника Вечности, пленение Иллидана, заклятие Мирового Древа и... О, да! Битва за Хиджал!$B$BМы должны поспешить, иначе эта линия времени будет разрушена.', 'Я знаю, что прошу невозможного, но все равно верю в тебя. Сейчас судьба мира – в твоих руках.', NULL, NULL, 'Неполный фиал Вайш', 'Неполный фиал Келя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10446, 'Финальный код', 'Они собирают еще одну мана-бомбу во дворе! Разведка сообщила мне, что финальный код от этой бомбы находится у Шарта Волдуна, который руководит этим проектом в лагере Огнекрылых.$B$B$N, тебе нужно вернуться туда и отобрать у него этот код. Шарт живет на пике самой высокой башни.$B$BКогда добудешь код, найди эту недособранную бомбу и отключи ее.$B$BТолько тогда бастион Аллерии будет в безопасности.', 'Используйте финальный код, чтобы активировать мана-бомбу, как велел вам лейтенант Меридиан. После этого поговорите с Дженайей Шепот Звезд в бастионе Аллерии в лесу Тероккар.', 'ПОЛУЧИЛОСЬ! БАСТИОН АЛЛЕРИИ СПАСЕН!$B$BТеперь, когда их силы ослаблены, предводитель мертв, а бомба обезврежена, мы все сможем вздохнуть спокойно.$B$B$N, я никогда еще не встречал такой самоотверженности и такого... героизма! Пожалуйста, прими это в благодарность от всех нас!', NULL, NULL, NULL, 'Мана-бомба активирована', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10447, 'Финальный код', 'Они собирают еще одну мана-бомбу во дворе! Разведка сообщила мне, что финальный код от этой бомбы находится у Шарта Волдуна, который руководит этим проектом в лагере Огнекрылых.$B$B$N, тебе нужно вернуться туда и отобрать у него этот код. Шарт живет на пике самой высокой башни.$B$BКогда добудешь код, найди эту недособранную бомбу и отключи ее.$B$BТолько тогда форт Камнеломов будет в безопасности.', 'Используйте финальный код, чтобы активировать мана-бомбу, как велела вам сержант Чауни. После этого поговорите с Туки в форте Камнеломов в лесу Тероккар.', 'ПОЛУЧИЛОСЬ! ФОРТ КАМНЕЛОМОВ СПАСЕН!$B$BТеперь, когда их силы ослаблены, предводитель мертв, а бомба обезврежена, мы все сможем вздохнуть спокойно.$B$B$N, я никогда еще не встречал такой самоотверженности и такого... героизма! Пожалуйста, прими это в благодарность ото всех нас!', NULL, NULL, NULL, 'Мана-бомба активирована', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10448, 'Донесение в лагерь Камнеломов', 'Нужно немедленно действовать!$B$BРядом с лагерем Огнекрылых есть кое-кто, с кем тебе нужно поговорить – она лучше знает, что делать дальше.$B$BНайди сержанта Чауни в лагере Камнеломов и объясни ей ситуацию. Из крепости иди на север, а из центра Туурема поворачивай на восток. Лагерь находится на берегу реки, что к юго-западу от лагеря Огнекрылых.$B$BПоспеши, $N.', 'Поговорите с сержантом Чауни в лагере Камнеломов в лесу Тероккар по просьбе Туки.', 'Детали бомб. Значит, я была права, хотя именно здесь я предпочла бы ошибиться.$B$BЛадно, значит, нам с вами предстоит одно очень серьезное дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10449, 'Аптекарь Зелана', 'Аптекарь Зелана изучает тварей Полуострова Адского Пламени. Я знаю, тебе удалось достать кровь Костеглодов, так вот, ей нужно доставить образец. Может, она выяснит, почему шкура этих мерзких тварей стала красного цвета.$B$BТы найдешь Зелану в Гибели Сквернобота, к юго-востоку от Траллмара. Иди по дороге на восток. Как увидишь покореженную груду металла, мерцающую зеленым светом – значит, ты на месте. Зелана разбила свой лагерь неподалеку от виверн.', 'Доставьте образцы крови орков из клана Костеглодов аптекарю Зелане в Погибель Сквернобота по просьбе Вартока Топоруба из Траллмара.', 'А, да. Кровь орков из клана Костеглодов. Они вызывают у меня недоумение... С одной стороны, в них все еще чувствуется демоническая порча, но их сила и мощь превосходит всякое разумение... $B$BХорошо, давай приступим...', 'Служить Орде – это большая честь для меня. Чем могу помочь?', NULL, NULL, 'Образцы крови орков из клана Костеглодов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10450, 'Кровь клана Костеглодов', 'Костеглоды! Чтоб они все попередохли! При виде их красной шкуры в моих жилах кровь вскипает от ярости!$B$BУ меня к тебе дело, $N. Убивай орков из клана Костеглодов и собирай их подлую кровь. Наши аптекари простестируют ее и узнают, как эти орки попали под власть демонической порчи, той самой, от которой нам недавно удалось освободиться.$B$BКостеглоды обитают рядом с обрушенной стеной, которая тянется к югу, вдоль Пути Славы. После выполнения задания возвращайся ко мне.', 'Принесите 12 фиалов крови орков из клана Костеглодов Вартоку Топорубу в Траллмар.', 'Ага! Тебе все-таки повстречались наши ублюдочные сородичи Костеглоды. Похвально, $N. Одно плохо – их умерло слишком мало, чтобы пролитая кровь могла охладить мою ярость.', 'Ну что, нашел клан Костеглодов, $N? Надеюсь, ты хорошенько пустил им кровь.', NULL, NULL, 'Кровь орков из клана Костеглодов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10451, 'Спастись из водохранилища Змеиных Колец', 'Благодарение Матери-Земле! Я отбилась от остальных несколько дней назад, хотела обнаружить источник того беспокойства, которое чувствовали духи воды. Расследование привело меня к Змеиным Кольцам, где я обнаружила наг, оскверняющих запасы воды долины Призрачной Луны. $B$BК сожалению, меня заметили, и я попала в плен. У меня нет сил даже говорить о той судьбе, которую они мне уготовили.$B$BМы должны выбраться отсюда! Помоги мне бежать, а потом найти Торлока у Алтаря Проклятия.', 'Выведите целительницу земли Вильду из водохранилища Змеиных Колец и затем разыщите целителя земли Торлока у Алтаря Проклятия, на западной окраине Руки Гул\'дана.', 'Хвала Матери-Земле. Я уверен, что теперь Вильда и сама доберется домой. Прошу, прими это от нас как знак признательности.', NULL, NULL, NULL, 'Целительница земли Вильда доставлена в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10455, 'Угроза хищников', 'Мы выращивали Живую рощу ускоренными темпами, но лесные рыси каким-то образом вышли из-под нашего контроля.$B$BРаньше популяция рысей была стабильна, но теперь они начали проникать даже в Сильванаар, и недавно произошло несколько неприятных инцидентов.$B$BПодозреваю, что за этим стоят араккоа из гнездовья Лашш, но прежде надо разобраться с самим рысями.$B$BЯ была бы весьма тебе благодарна, если бы нам в этом $gпомог:помогла:.', 'Убейте 12 лесных рысей.', 'Как быстро... Ты уверен, что уничтожил столько, сколько надо?$B$BОтлично. Есть еще дела, в которых нам нужна помощь. Как ты на это смотришь?', NULL, NULL, NULL, 'Лесная рысь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10456, 'Волчья напасть', 'Эти подлые расы Орды захватили поселение на востоке. С собой они привели стаю лютых волков, на которых они ездят верхом и посылают как часовых.$B$BИ эти волки разбойничают на мосту, что разделяет нас. Они охотятся на наших волшебных драконов, необходимых для опыления Живой рощи.$B$BИди через восточный выход, чтобы пересечь мост над лощиной Кровавого Молота, который выводит к Зазубренной гряде на востоке, и принеси мне их хвосты в доказательство!', 'Соберите 4 хвоста лютого волка клана Громоборцев.', 'Славно. Постараюсь сделать из этих хвостов что-нибудь приличное.$B$BНе сомневаюсь, что Орда сумеет восполнить потерю этой волчьей стаи, но пока мы можем перевести дух.$B$BЕсли ты не против, $N, я попросила бы тебя сделать еще кое-что ради блага Сильванаара и Живой рощи.', 'Мне даже трудно выразить, насколько важно уничтожить этих лютых волков клана Громоборцев! Само их существование угрожает стабильности Живой рощи и всей нашей работе здесь.', NULL, NULL, 'Хвост лютого волка клана Громоборцев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10457, 'Защитить свой дом', 'Хотя ты и так много $gпотрудился:потрудилась: ради защиты нашего нового дома в этих краях, мне все еще кажется, что Живую рощу надо обезопасить.$B$BПрошу тебя, возьми вот эту маленькую ветку, которую я наполнила силой природы. Когда ты взмахнешь ей над саженцами, что я высадила в роще, она вызовет грозу, которая ускорит рост древней.$B$BЭти древни очень нужны для защиты рощи, особенно если ты не задержишься в Сильванааре надолго.', 'Взмахните ветвью Рины над 5 саженцами рощи, чтобы призвать на защиту Живой рощи силы природы.', 'Теперь, когда защита Рощи укреплена, я чувствую себя куда спокойнее.$B$BТы заслужил нашу благодарность и хвалу, $N.$B$BИ, конечно, я сразу же вспомнила об еще одном важном деле!', 'Как идет укрепление защиты Рощи?$B$BПоскольку мы не знаем о намерениях араккоа из Лашш, а Орда засела прямо на другой стороне ущелья, то я боюсь, что если мы не поторопимся, то не сумеем защитить ни наш дом, ни Рощу, ни все наши труды.', NULL, NULL, 'Призвано защитников Живой рощи', 'Ветвь Рины (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10458, 'Разъяренные бесы пламени и земли', 'Мы должны пробовать исправить причиненный ущерб. Мы должны найти общий язык со стихиями этого края и, может быть, нам удастся что-то исправить! $B$BВот тебе тотем духов, $r. Тотем поглощает души убитых рядом с ним разъяренных элементалей. Тебе придется собрать множество бесов, чтобы зарядить тотем.$B$BНачни с бесов земли и пламени и возвращайся, когда тотем будет полностью заряжен.', 'Поймайте с помощью тотема духов 8 бесов земли и 8 бесов пламени для целителя земли Торлока из Алтаря Проклятия.', 'Когда все души элементалей обретут пристанище в этом тотеме, мы сможем пообщаться с ними и выяснить, возможно ли что-нибудь сделать для Долины Призрачной Луны.', 'Я боюсь, эту землю уже ничто не спасет.', NULL, NULL, 'Поймано бесов земли', 'Пойманный бес пламени', 'Тотем духов (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10459, 'Почтительное отношение Кенарийской экспедиции', 'Мы знаем о твоих свершениях, $N. То, что ты $gсделал:сделала: для нас, выходит за рамки того, чего мы ждем от обычных союзников.$B$BУ меня к тебе будет особая просьба - но сначала мне нужно испытать твою преданность.', 'Исиэль Песнь Ветра из Кенарийского приюта хочет, чтобы вы добились почтительного отношения Кенарийской экспедиции.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
