INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10461, 'Посвящение в целители', '', '', 'Ты уверен, что хочешь избрать этот путь, $N? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.В этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10462, 'Посвящение в герои', '', '', 'Ты уверен, что хочешь избрать этот путь, $N? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.В этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10463, 'Посвящение в мудрецы', '', '', 'Ты уверен, что хочешь избрать этот путь, $N? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.В этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10464, 'Обет мудреца', 'Ты $gвыбрал:избрала: свой путь и $gдал:дала: обет. Теперь все зависит только от тебя, $C.$B$BБудешь верой и правдой служить драконам Песчаной Чешуи – получишь щедрую награду. Но помни: если ты не сумеешь исполнить свою задачу, линия времени будет разрушена, и ход истории изменится!', 'Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить уважительное отношение драконов Песчаной Чешуи.', 'Ты оправдал наше доверие, $R. Во всяком случае, до сих пор у нас не было повода усомниться в тебе.$B$BУчти, что доверие супруги и помощницы Ноздорму непросто заслужить.', 'Ты по-прежнему служишь нам верой и правдой, $N.', NULL, NULL, 'Кольцо вечности (Прилагается)', NULL, NULL, NULL);
