INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10467, 'Обет защитника', 'Ты $gвыбрал:избрала: свой путь и $gдал:дала: обет. Теперь все зависит только от тебя, $C.$B$BБудешь верой и правдой служить драконам Песчаной Чешуи – получишь щедрую награду. Но помни: если ты не сумеешь исполнить свою задачу, линия времени будет разрушена, и ход истории изменится!', 'Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить уважительное отношение драконов Песчаной Чешуи.', '', NULL, NULL, NULL, 'Кольцо вечности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10468, 'Клятва мудреца', 'Ты $gсдержал:сдержала: данное нам обещание, $N. Теперь мы знаем, чего ты стоишь.$B$BПока ты будешь странствовать во времени и охранять от вмешательства прошлое горы Хиджал, я наполню силой твое кольцо. Ждать осталось недолго - уже очень скоро оно обретет свою полную силу.', 'Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить почтительное отношение драконов Песчаной Чешуи.', 'Ты достойный союзник. Ты растешь в наших глазах, а вместе с тем прирастает и сила твоего кольца Вечности.', 'Ты вернулся. Тебе есть о чем рассказать?', NULL, NULL, 'Кольцо вечности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10469, 'Клятва целителя', 'Ты $gсдержал:сдержала: данное нам обещание, $N. Теперь мы знаем, чего ты стоишь.$B$BПока ты будешь странствовать во времени и охранять от вмешательства прошлое горы Хиджал, я наполню силой твое кольцо. Ждать осталось недолго - уже очень скоро оно обретет свою полную силу.', 'Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить почтительное отношение драконов Песчаной Чешуи.', 'Ты достойный союзник. Ты растешь в наших глазах, а вместе с тем прирастает и сила твоего кольца Вечности.', 'Ты вернулся. Тебе есть о чем рассказать?', NULL, NULL, 'Кольцо вечности (Прилагается)', NULL, NULL, NULL);
