INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10471, 'Клятва защитника', 'Ты $gсдержал:сдержала: данное нам обещание, $N. Теперь мы знаем, чего ты стоишь.$B$BПока ты будешь странствовать во времени и охранять от вмешательства прошлое горы Хиджал, я наполню силой твое кольцо. Ждать осталось недолго - уже очень скоро оно обретет свою полную силу.', 'Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить почтительное отношение драконов Песчаной Чешуи.', 'Ты достойная союзница. Ты растешь в наших глазах, а вместе с тем прирастает и сила твоего кольца Вечности.', 'Ты вернулась. Тебе есть о чем рассказать?', NULL, NULL, 'Кольцо вечности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10472, 'Договор мудреца', 'То, что ты $gсделал:сделала:, превзошло все мои ожидания, $N.$B$BТы перемещаешься во времени так же легко и свободно, как любой из бронзовых драконов. Ты $gсоздан:создана: для великой силы, и я рада помочь тебе обрести ее в полной мере.$B$BПродолжай верой и правдой служить драконам Песчаной Чешуи, и я сделаю так, чтобы твой дар обрел полную силу.', 'Принесите кольцо Вечности Соридорми в пещеры Времени, когда сумеете заслужить полное доверие драконов Песчаной Чешуи.', 'Ты пребываешь в единстве со временем, $N. Ты - один из нас. В капле воды из Источника Вечности заключена величайшая сила, превосходящая воображение смертных.$B$BПрими этот дар, и пусть все знают, что ты заключил договор с драконами Песчаной Чешуи... а это значит, что ты заключил договор с самим временем.', 'Пусть время всегда работает на тебя, $N.', NULL, NULL, 'Кольцо вечности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10473, 'Договор целителя', 'То, что ты $gсделал:сделала:, превзошло все мои ожидания, $N.$B$BТы перемещаешься во времени так же легко и свободно, как любой из бронзовых драконов. Ты $gсоздан:создана: для великой силы, и я рада помочь тебе обрести ее в полной мере.$B$BПродолжай верой и правдой служить драконам Песчаной Чешуи, и я сделаю так, чтобы твой дар обрел полную силу.', 'Принесите кольцо Вечности Соридорми в пещеры Времени, когда сумеете заслужить полное доверие драконов Песчаной Чешуи.', 'Ты пребываешь в единстве со временем, $N. Ты - одна из нас. В капле воды из Источника Вечности заключена величайшая сила, превосходящая воображение смертных.$B$BПрими этот дар, и пусть все знают, что ты заключила договор с драконами Песчаной Чешуи... а это значит, что ты заключила договор с самим временем.', 'Пусть время всегда работает на тебя, $N.', NULL, NULL, 'Кольцо вечности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10474, 'Договор героя', 'То, что ты $gсделал:сделала:, превзошло все мои ожидания, $N.$B$BТы перемещаешься во времени так же легко и свободно, как любой из бронзовых драконов. Ты $gсоздан:создана: для великой силы, и я рада помочь тебе обрести ее в полной мере.$B$BПродолжай верой и правдой служить драконам Песчаной Чешуи, и я сделаю так, чтобы твой дар обрел полную силу.', 'Принесите кольцо Вечности Соридорми в пещеры Времени, когда сумеете заслужить полное доверие драконов Песчаной Чешуи.', 'Ты пребываешь в единстве со временем, $N. Ты - один из нас. В капле воды из Источника Вечности заключена величайшая сила, превосходящая воображение смертных.$B$BПрими этот дар, и пусть все знают, что ты заключил договор с драконами Песчаной Чешуи... а это значит, что ты заключил договор с самим временем.', 'Пусть время всегда работает на тебя, $N.', NULL, NULL, 'Кольцо вечности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10475, 'Договор защитника', 'То, что ты $gсделал:сделала:, превзошло все мои ожидания, $N.$B$BТы перемещаешься во времени так же легко и свободно, как любой из бронзовых драконов. Ты $gсоздан:создана: для великой силы, и я рада помочь тебе обрести ее в полной мере.$B$BПродолжай верой и правдой служить драконам Песчаной Чешуи, и я сделаю так, чтобы твой дар обрел полную силу.', 'Принесите кольцо Вечности Соридорми в пещеры Времени, когда сумеете заслужить полное доверие драконов Песчаной Чешуи.', '', NULL, NULL, NULL, 'Кольцо вечности (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10476, 'Лютые враги', 'Лучший способ доказать нам свою преданность – это сразиться с нашими врагами.$B$BСамые свирепые и сильные из них – это огры. В грубой силе им просто нет равных. Покажи нам, на что ты $gспособен:способна:. Принеси мне обсидиановые боевые ожерелья, которые огры носят на шее. А я расскажу остальным о твоем доблестном подвиге.', 'Принесите стражу-смотрителю Мой\'прну Джиллу 10 обсидиановых боевых ожерелий, снятых с огров из Награнда.', 'Ты действительно верный союзник и добрый соратник. Надеюсь, ты еще не раз докажешь это.', 'Ну что, $N? У тебя есть что мне показать?', NULL, NULL, 'Обсидиановые боевые бусы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10477, 'Боевые ожерелья', '', '', 'Ты по-прежнему служишь нам верой и правдой, $N. Пусть твоя сила пребудет с тобой всегда.', NULL, NULL, NULL, 'Обсидиановые боевые бусы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10478, 'Боевые ожерелья!', '', '', 'Ты вновь подтвердил свою силу и благородство, $N.', NULL, NULL, NULL, 'Обсидиановые боевые бусы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10479, 'Покажи свою силу', 'Хотя мы сами ищем мира, у нас много врагов. И самые могучие из них – это огры. В грубой силе им просто нет равных.$B$BТы $gсилен и отважен:сильна и отважна:? Покажи свою силу. Принеси мне обсидиановые боевые ожерелья, которые огры носят на шее. А я расскажу остальным о твоем доблестном подвиге.', 'Принесите 10 обсидиановых боевых ожерелий, снятых с огров, населяющих Награнд, стражу-смотрителю Быккроку в Гарадар.', 'Ты действительно сильный союзник, $N. Пойти в одиночку на огров Запределья... на такое способен не каждый.', 'Надеюсь, ты вернулся не с пустыми руками, $N?', NULL, NULL, 'Обсидиановые боевые бусы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10480, 'Разъяренные бесы воды', 'Иллидарские наги захватили контроль над единственным в Долине Призрачной Луны источником чистой воды.$B$BИх логово расположено к северу отсюда в Змеиных Кольцах. Вокруг Змеиных Колец множество мелких озер, вода в которых бурлит и даже как будто стонет от боли. Это оттого, что в них обитают бесы воды.$B$BОтправляйся туда и используй тотем духов, чтобы подчинить их. Больше всего бесов сосредоточено возле водохранилища Змеиных Колец.', 'Используйте тотем духов, чтобы поймать 5 бесов воды для целителя земли Торлока у Алтаря Проклятия в Долине Призрачной Луны.', 'Теперь осталось только с воздухом разобраться, $N.', 'Где бы тебе ни встретились наги, поблизости всегда окажутся разъяренные бесы воды.', NULL, NULL, 'Поймано бесов воды', 'Тотем духов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10481, 'Разъяренные бесы воздуха', 'Отправляйся на юго-восток. Когда увидишь поля крупных голубых кристаллов, торчащих из земли – значит, ты на месте. Там, на полях Крыльев Пустоты, ты найдешь разъяренных бесов воздуха, что бродят по утесам и горным отрогам, окружающим поля.$B$BУничтожь их физические тела и улови души с помощью тотема духов. По исполнении возвращайся ко мне.', 'Поймайте с помощью тотема духов 10 бесов воздуха для целителя земли Торлока из Алтаря Проклятия.', 'Позволь мне вознаградить тебя за выполнение столь сложного задания, $N!$B$BТеперь пора приниматься за работу. Отойди в сторону, чтобы я мог установить тотем и выпустить бесов.', 'Скоро мы пообщаемся с бесами.', NULL, NULL, 'Поймано бесов воздуха', 'Тотем духов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10482, 'Падальщики орков Скверны', 'Падальщики, орки из клана Костеглодов, днем и ночью рыщут вдоль Пути Славы. Мы думаем, что они доставляют запчасти боевых машин в цитадель Адского Пламени. Их нужно остановить!$B$BОрки из клана Костеглодов водятся к северу отсюда, $N. Найди их и уничтожь! Но будь $gосторожен:осторожна:. Хотя Костеглоды – самый слабый из кланов орков Скверны, по мощи они превзойдут любого зеленокожего орка.', 'Убейте 20 орков из клана Костеглодов и возвращайтесь к Амади в Оплот Чести.', 'Очень хорошо. Я уверена, цитадель Адского Пламени вскоре заметит эту потерю. Ее неприступная тень нависает над нами, но пока у нас есть подобные воины, есть и надежда на победу!', NULL, NULL, NULL, 'Орк из клана Костеглодов убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10483, 'Дурные предзнаменования', '$N, на трупах убитых орков из клана Кровавой Глазницы стали находить очень нехорошие предметы. Эти орки срезали боевые знаки с мундиров павших солдат из Оплота Чести и при помощи черной магии превращали их в свои проклятые талисманы. Наши же боевые знаки обратились оружием против нас!$B$BУбей какого-нибудь орка из клана Кровавой Глазницы, сними с него талисман и доставь капралу Железному Хребту в лагерь экспедиции, к северо-востоку от Зет\'Гора.', 'Принесите 1 проклятый талисман капралу Железному Хребту в лагерь экспедиции по просьбе лейтенанта Амади в Оплоте Чести.', 'Ты отбил наш знак у орков из клана Кровавой Глазницы? Это делает тебе честь. Отвратительно, эти краснокожие твари осмеливаются использовать против нас наши же знаки!', 'Донесение из Оплота Чести, $N? Это хорошо – постоянные стычки с демонами и орками Скверны вымотают кого угодно...', NULL, NULL, 'Проклятый талисман', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10484, 'Проклятые талисманы', '$N, нельзя, чтобы орки из клана Кровавой Глазницы продолжали владеть этими проклятыми талисманами! Их необходимо изъять и уничтожить. Мы должны восстановить честь своих павших.$B$BСтупай в Зет\'Гор, гнусное обиталище клана Кровавой Глазницы, и исполни, что должно, не щадя ни себя, ни врагов. Возвращайся ко мне, когда соберешь талисманы.', 'Принесите 12 проклятых талисманов капралу Железному Хребту в Лагерь экспедиции.', 'Спасибо тебе, $N. При виде этих талисманов мое сердце обливается кровью. Они напоминают мне о потерях, которые Оплот Чести понес в борьбе с орками Скверны. Но твоя победа придала мне сил. Мы победим в этой войне, даже если придется уничтожить бессчетное количество орков!', 'Ты раздобыл талисманы, $N? Мне больно думать, что эти проклятые орки сделали со знаками наших солдат.', NULL, NULL, 'Проклятый талисман', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10485, 'Воевода клана Кровавой Глазницы', 'Должно быть, ты необычайно $gловок и удачлив:ловка и удачлива:, если тебе удалось проникнуть в Зет\'Гор и выбраться оттуда $gживым:живой:. Надеюсь, удача и дальше тебя не оставит, потому что у меня есть новое дело.$B$BВ Зет\'Горе засел воевода Морх, который командует армиями орков Скверны. Он превосходный полководец, и, с прискорбием вынужден отметить, он раз за разом одерживает над нами победу. Так что у меня к тебе просьба, $N, – надо бы отправить этого Морха в отставку. Принеси мне его доспехи, мы покажем их солдатам для поднятия боевого духа.', 'Принесите разбитые доспехи воеводы Морха капралу Железному Хребту в лагерь экспедиции.', 'Ты сделал это! Морх убит! Теперь у нас снова появился шанс одолеть орков Скверны!$B$BСпасибо тебе, $N. Твоя помощь неоценима.', 'Тебе удалось раздобыть доспехи Морха? Ты снова заставил Зет\'Гор содрогнуться от твоей отваги?', NULL, NULL, 'Разбитые доспехи Морха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10486, 'Угроза хищников', 'Некогда клан Громоборцев был гордым орочьим кланом – до того, как они стали орками Скверны из-за крови Маннорота.$B$BНедавно мы отбили эту орочью крепость у огров, что кишат в ущелье внизу. Они захватили эту крепость, когда клан Громоборцев ее оставил.$B$BМы будем удерживать эту крепость, и надеемся, что ты нам поможешь.$B$BПо Зазубренной гряде на юге и западе бродят кровопускатели, что стали для нас сущей напастью. Они беспрерывно жрут и плодятся! $B$BПеребей их и возвращайся ко мне.', 'Убейте 12 острокрылых кровопускателей.', 'Не такое уж и долгое дело, как оказалось. Ты уверен что уложил достаточно этих тварей?$B$BОтлично, у меня есть для тебя еще дельце. Куда более важное.', NULL, NULL, NULL, 'Острокрылый кровопускатель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10487, 'Пыльца волшебных драконов', 'Недавно Альянс сильно продвинулся на запад. При помощи своей эльфийской магии они тут быстро построили город и вырастили рощу. Мы должны их ослабить, чтобы они тут еще и корни не пустили.$B$BУ меня есть план, как покончить с этим. Я хочу, чтобы ты $gотправился:отправилась: через мост над лощиной Кровавого Молота на юго-запад до Живой рощи.$B$BНапади на их волшебных драконов в Живой роще и принеси магической пыльцы, что порой можно найти на их крыльях.', 'Соберите пыльцу с крыльев 4 волшебных драконов.', 'Ты не только ослабил их оборону! Мы используем эту пыльцу для усиления собственной защиты от сил Альянса!', 'Похоже, Альянс намерен преследовать нас повсюду. Покажем им, что мы их не боимся.$B$BТы принес то, что я просил?', NULL, NULL, 'Пыльца с крыльев волшебных драконов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10488, 'Защитить свой дом', 'Из добытой тобой волшебной пыльцы я сделал магическую мазь, которая поможет укрепить нашу собственную оборону.$B$BНаши лютые волки замечательно могут служить и верховыми животными, и часовыми, и они славные друзья, но эти гады из Альянса устроили им бойню у Зазубренной гряды.$B$B$N, я хочу, чтобы ты $gвзял:взяла: эту мазь и $gполечил:полечила: наших волков-друзей. Когда Альянс в следующий раз сунется сюда с очередной охотничьей партией, их будет ждать неприятный сюрприз.$B$BНекоторым волкам эта мазь может не понравиться, и они могут наброситься на тебя, так что поосторожнее.', 'Помажьте мазью Гор\'дрека 5 лютых волков клана Громоборцев.', 'Теперь, когда с твоей помощью волки стали сильнее, а оборона Зазубренной гряды крепче, не обратиться ли нам к более трудным проблемам, вроде огров?$B$BТы нам тут хорошо помог. Если решишь остаться, то мы бы охотно еще не раз воспользовались твоей помощью.$B$BНо что бы ты ни решил, ты уже заслужил мое уважение и почет.', 'Ну как, стали наши лютые волки крепче?', NULL, NULL, 'Усильте лютых волков клана Громоборцев', 'Мазь Гор\'дрека (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10489, 'Свалить ходячее древо!', 'РОЗЫСК!$B$BРазыскивается Лесодрев Глубокорень, древо войны и защитник Живой рощи к югу от Сильванаара!$B$BИщите его на западе за мостом через лощину Кровавого Молота.$B$BДоставьте его срубленный ствол Тор\'чанку Двукогтю на постоялый двор Оплота Громоборцев.', 'Добудьте ствол Лесодрева Глубокорня.', 'Ствол Лесодрева Глубокорня! Ты сам его завалил?$B$BЗуб даю – сам. Знаешь, мы с Рексаром искали молодого, сильного $C вроде тебя – тут дел выши крыши, особенно с ограми! Вижу, тут ты пришелся как нельзя к месту.$B$BНу, раз этот ствол определенно тот самый, стало быть, забирай награду и не слушай мою болтовню. Ну давай, выбирай.', 'Что это тут у тебя? Да ты силач!', NULL, NULL, 'Ствол Лесодрева Глубокорня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10490, 'Зов Воды', 'Я чувствую, много времени прошло с тех пор, когда тебе довелось пройти последнее испытание... Именно по этой причине о тебе и спрашивал предсказатель Нобундо.$B$BДолжно быть, твоя мудрость возросла – ибо ныне тебя призывают, дабы открыть тебе тайны стихии воды.$B$BПолагаю, ты помнишь, что нужно взять лодку в Аубердине на Темных берегах Калимдора и добраться на ней в Экзодар? Я надеюсь также, что тебе не нужно напоминать, где в Кристальном зале Экзодара ты сможешь найти предсказателя. Я права?', 'Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним.', 'Вот мы и встретились снова. Я вижу, избранный тобой путь шамана не был ошибкой, а твои успехи доставляют мне истинную радость.$B$BИтак, для тебя настало время постижения стихии Воды: ты познаешь ее тайны, и Вода примет тебя, открыв тебе свою сокровенную суть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10491, 'Зов воздуха', 'И снова предсказатель Нобундо призывает тебя, $N. Должно быть, настало время познать тайны воздуха, последней из стихий!$B$BВзойди на корабль в Аубердине на Темных берегах Калимдора. Пересеки Сокрытое море и найди предсказателя в Кристальном зале Экзодара на острове Лазурной Дымки.', 'Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.', 'Наконец-то мы дошли до последней из четырех великих стихий - воздуха. Думаешь, ты достаточно мудра, чтобы продолжить обучение, $N?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10492, 'Серьезное предложение', 'Рада встрече, $C. У меня найдется кое-что интересное для тебя.$B$BЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу.$B$BКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне изрядное количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.', 'Добудьте 15 порций крови животных Зимних Ключей и 20 золотых и отдайте их вместе с наручниками Стихий Делиане в Стальгорне.', '', NULL, NULL, NULL, 'Образец крови из Зимних Ключей', 'Наручники Стихий', 'Требуется денег: 20', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10493, 'Серьезное предложение', 'Привет тебе, $C! Судя по тому, как ты держишься, тебе немало довелось повидать на белом свете. Но бьюсь об заклад, что таких доспехов, как эти, тебе видеть не доводилось!$B$BОкажи мне небольшую услугу, и я отдам их тебе в обмен на наручи попроще.$B$BМне нужен яд тварей, обитающих в Силитусе. Принеси мне этот яд и немного золотых монет, и я произведу обмен.', 'Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами из светлостали Моквару в Оргриммар.', '', NULL, NULL, NULL, 'Образец яда силитида', 'Наручи из светлостали', 'Требуется денег: 20', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10494, 'Справедливое вознаграждение', 'Ты $gсдержал:сдержала: слово и $gпринес:принесла: устройство Мукса. И уж если я хочу, чтобы ты и дальше $gзащищал:защишала: мою шкуру, то награда должна быть соотвествующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.', 'Принесите шнурованный ремень Стихий и пару рукавиц Стихий в Стальгорн Делиане.', '', NULL, NULL, NULL, 'Шнурованный ремень Стихий', 'Рукавицы Стихий', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10495, 'Справедливое вознаграждение', 'Ты $gоказался:оказалась: чрезвычайно надежным $gпомощником:помощницей:, $N! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!$B$BОбменяю-ка я твой пояс и повязки на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.', 'Принесите Моквару в Оргриммар пояс из светлостали и рукавицы из светлостали.', '', NULL, NULL, NULL, 'Пояс из светлостали', 'Рукавицы из светлостали', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10496, 'Прощальные слова Антиона', 'В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!', 'Вернитесь в Стальгорн к Делиане с сапогами Стихий, килтом Стихий и наплечьем Стихий.', '', NULL, NULL, NULL, 'Сапоги Стихий', 'Килт Стихий', 'Наплечье Стихий', 'Верхняя часть амулета Лорда Вальтхалака');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10497, 'Прощальные слова Антиона', 'В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$B$BЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$B$BНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!', 'Отдайте Моквару в Оргриммаре сапоги из светлостали, ножные латы из светлостали и наплеч из светлостали.', '', NULL, NULL, NULL, 'Сапоги из светлостали', 'Ножные латы из светлостали', 'Наплеч из светлостали', 'Верхняя часть амулета Лорда Вальтхалака');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10498, 'Сладкое – на закуску', 'Замечательная история, $N! Спасибо тебе и сердечная благодарность всем, кто принимал участие. Может, сегодня ночью я хоть нормально посплю.$B$BВ награду хочу предложить несколько вещичек, что тебя, наверное, порадуют.', 'Отдайте Делиане капюшон Стихий и жилет Стихий.', '', NULL, NULL, NULL, 'Капюшон стихий', 'Жилет Стихий', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10499, 'Сладкое – на закуску', 'Воистину удивительная история, $N! Я тебе признателен от всей души – и не только я, но и все, кто замешан в этой истории. Благодаря твоим трудам мы избавились от ошибок нашего прошлого.$B$BПоговорим теперь о твоей награде. У меня есть кое-что, что наверняка придется тебе по нраву!', 'Отдайте Моквару шлем из светлостали и кирасу из светлостали.', '', NULL, NULL, NULL, 'Шлем из светлостали', 'Кираса из светлостали', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10500, 'Орде нужна твоя помощь!', 'Приветствую, я рада, что ты $gрешил:решила: поговорить со мной. Если мы хотим достойно подготовиться к ан\'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не следует оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, $N!$B$BПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, $C? Примешь участие в этом жизненно важном деле?', 'Поговорите с вождем Горчуком на аллее Духов Оргриммара.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10501, 'Альянсу нужна твоя помощь!', 'Приветствую. Хорошо, что ты $gрешил:решила: поговорить со мной. В подготовке к войне в Ан\'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый! Уже назначены ответственные за сбор разнообразных материалов, но без помощи простых граждан им не справиться, $N!$B$BЕсли хочешь поддержать Альянс, обратись с фельдмаршалу Снежной Лавине, который отвечает за сбор ресурсов. Что скажешь, $C? Примешь ли ты участие в этом жизненно важном деле?', 'Поговорите с фельдмаршалом Снежной Лавиной, который находится в Палатах войны Стальгорна.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10502, 'Клан Кровавого Молота', 'Над Сильванааром нависла угроза пострашнее Орды, что засела в оплоте Громоборцев.$B$BЯ говорю об ограх здешних гор. Прямо на юге и востоке, в той лощине живет клан Кровавого Молота. Хотя они не единственные огры, что угрожают нам, они ближе всех.$B$BЯ хочу попросить тебя отправиться на юг через Живую рощу, затем по тропе на восток, к их заставе. Уничтожь столько огров из клана Кровавого Молота на их заставе, сколько сумеешь.', 'Убейте 30 любых огров Кровавого Молота на заставе Кровавого Молота.', 'Это большой успех в защите Сильванаара и рощи.$B$BТеперь, когда их число поубавилось, эти Кровавые Молоты семь раз подумают прежде, чем нападать на нас.$B$BЕсли бы только они были единственным кланом огров, с которым у нас проблемы!', NULL, NULL, NULL, 'Убивайте огров из клана Кровавого Молота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10503, 'Угроза Камнерогов', 'Над оплотом Громоборцев нависла угроза пострашнее Альянса, что засел в Сильванааре. $B$BЯ говорю об ограх здешних гор. Прямо на западе, в той лощине живет клан Камнерогов. Хотя они не единственные огры, что угрожают нам, они ближе всех.$B$BИди на север через Зазубренную гряду, затем по тропе к их крепости. Уничтожь столько огров из клана Камнерогов в их крепости и на их землях, сколько сумеешь.', 'Убейте 30 любых огров из клана Камнерогов и 10 камнерогих ящеров в Форте Камнерогов и на землях Камнерогов.', 'Это большой успех в укреплении нашего положения в здешних краях.$B$BТеперь, когда их число поубавилось, эти Камнероги семь раз подумают прежде, чем нападать на оплот Громоборцев.$B$BЕсли бы только они были единственным кланом огров, с которым у нас проблемы!', NULL, NULL, NULL, 'Убивайте огров из клана Камнерогов', 'Ящер клана Камнерогов убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10504, 'Огры из клана Камнерогов', 'К северу от клана Кровавого Молота таится еще большая угроза – форт Камнерогов.$B$BКамнероги – самый могучий клан в этих горах, ибо пользуются благосклонностью гронна, известного как Груул Драконобой, и его семерых сыновей.$B$BТеперь, когда мы разделались с Кровавым Молотом, пора заняться и их противниками. $B$BОт крепости Кровавого Молота по лощине идет тропа до самой крепости Камнерогов и земель Камнерогов. Перебей там столько огров из клана Камнерогов, сколько сумеешь.', 'Убейте 30 любых огров из клана Камнерогов в Форте Камнерогов и на землях Камнерогов.', 'Твои подвиги в сражениях против кланов Кровавого Молота и Камнерогов надолго обеспечили будущее Сильванаара. Хотя мы не хотим ни пяди земли кроме той, что нашли пустой с самого начала, мы не дадим себя уничтожить!$B$BПоскольку ты сослужил нам хорошую службу, я награжу тебя от имени Альянса.', NULL, NULL, NULL, 'Убивайте огров из клана Камнерогов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10505, 'Клан Кровавого Молота', 'К югу от клана Камнерогов таится еще большая угроза – застава Кровавого Молота.$B$BХотя Кровавый Молот – не самый сильный клан в этих горах, ибо они не пользуются благосклонностью гронна, известного как Груул Драконобой, они мало чем уступают Камнерогам.$B$BТеперь, когда мы разделались с Камнерогами, пора заняться и их противниками. $B$BОт форта Камнерогов по лощине идет тропа на юг до самой заставы Кровавого Молота. Перебей там столько огров из клана Кровавого Молота, сколько сумеешь.', 'Убейте 30 любых огров Кровавого Молота на заставе Кровавого Молота.', 'Твои подвиги в сражениях против кланов Кровавого Молота и Камнерогов надолго обеспечили будущее оплота Громоборцев. Мы не дадим спуску тем, кто становится у нас на пути!$B$BПоскольку ты сослужил нам хорошую службу, я награжу тебя от имени Орды.', NULL, NULL, NULL, 'Убивайте огров из клана Кровавого Молота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10506, 'Тяжелая ситуация', 'Теперь, когда их волчья стая поредела, Орда ищет, чем бы восполнить потери. К сожалению, найдут, и достаточно близко.$B$BОгры из клана Кровавого Молота в той лощине на востоке держат сильную стаю для собственной охраны. Мне было тяжело посылать тебя убивать волков клана Громоборцев, так почему бы на этот раз не пойти иным путем?$B$BЯ создала магический порошок из пыльцы с крыльев наших волшебных драконов. Посыпь им лютых волков клана Кровавого Молота, чтобы Орда ими не интересовалась.', 'Рина Лунный Родник хочет, чтобы вы взяли ее уменьшающий порошок и посыпали им 5 лютых волков клана Кровавого Молота, которых можно найти на заставе и в лощине Кровавого Молота.', 'Рада, что получилось! Чем меньше детей Природы гибнет, тем лучше.$B$BНадо сказать, что после всего, что ты для нас уже сделал, мне начинает очень нравиться твое общество!$B$BПоберегись, $N.', 'Ну, как, удалось? Понимаю, что среди клана Кровавого Молота бродить опасно, но если можно избежать убийства зверей, то мне это по сердцу.', NULL, NULL, 'Ослабьте лютых волков клана Кровавого Молота', 'Уменьшающий порошок Рины (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10507, 'Поворотная точка', 'Это шанс, которого мы ждали, $N. Мы не только обнаружили свидетельства, необходимые для того, чтобы показать нашим людям, на кого реально работает Кель\'тас. Мы также можем доказать свою силу, победив его новых хозяев.$B$BМое слабое здоровье не дает мне лично помочь тебе в этом предприятии, но я предлагаю тебе предмет, который позволит мне простереть мою силу через весь континент.', 'Используйте камень телепортации Сокретара в точке вторжения: Властитель к северу от базы Легиона: Забвение, чтобы перенести свой отряд в лагерь Сокретара. Оказавшись там, используйте \"Присутствие Ворен\'таля\", чтобы победить Сокретара. Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Ты необычайно сильная личность, $N. Провидцы счастливы числить тебя среди своих союзников.$B$BКогда слух о том, кому ныне служит Кель, распространится достаточно широко, еще больше народа примет нашу точку зрения. Тот факт, что мы можем одержать столь решительную победу над новыми хозяевами Кель\'таса, ставит нас в весьма выгодное положение.$B$BЯ не забуду твои деяния.', 'Готово, $N?', NULL, NULL, 'Сокретар убито', 'Присутствие Ворен\'таля', 'Сокретарский камень Телепортации', 'Рекомендуемое количество игроков: 5');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10508, 'Дар для Ворен\'таля', 'Я не хочу посылать тебя к Ворен\'талю с пустыми руками. Не в моем стиле разочаровывать кого-либо. $B$BЧтобы добраться до Трона Сокретара на севере, мы должны воспользоваться его собственными телепортами – запертыми посредством камня телепортации Сокретара. Первая половина камня находится у начальника кузни Моруга на базе Легиона: Забвение. Вторую половину хранит демон Силрот на базе Легиона: Геенна.$B$BДобудь их, и Ворен\'таль потеряет дар речи от удивления.', 'Патрон шпионов Талодиен, находящийся в Зоне 52, просит вас забрать первую половину камня Сокретара у начальника кузни Моруга с базы Легиона: Забвение и вторую половину камня Сокретара у Силрота с базы Легиона: Геенна. Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Ты не перестаешь удивлять меня, $N! Хорошо, что ты на нашей стороне.', 'Удалось ли тебе добыть камень телепортации Сокретара, $N?', NULL, NULL, 'Первая половина камня Сокретара', 'Вторая половина камня Сокретара', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10509, 'И все ради славы', 'Теперь я без колебаний могу отослать тебя обратно в город Шаттрат. Тебе удалось добыть доказательства того, что Кель\'тас заключает соглашение с Пылающим Легионом, а также добыть ключ от черного хода к властителю.$B$BНо смотри, чтобы Ворен\'таль не упал в обморок от радости, получив такие новости, – старик несколько ослаб в последнее время, если ты понимаешь, что я имею в виду. Ты найдешь его в библиотеке Предсказателя на ярусе Провидцев.', 'Отнесите камень телепортации Сокретара Ворен\'талю Предсказателю на ярус Провидцев в Шаттрате. Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Ты даже не представляешь, $N, какое значение это имеет для Провидцев. Прошу меня извинить, мне нужно перевести дыхание и оценить сложившуюся ситуацию.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10510, 'В дренетистовые копи', 'Приятно, когда тебе готовы помогать!$B$BМы с Боргримом состоим в Лиге исследователей, а здесь мы для того, чтобы узнать побольше о тутошних горах. Баек ходит много, и мне не терпится разбить лагерь да начать работу.$B$BВ особенности меня привлек вот какой слух. Ночные эльфы говорили об одном местечке в ущелье на востоке, называя его дренетистовыми копями. Это к югу от заставы Кровавого Молота. Мне бы заполучить немного кристаллов, что там растут.', 'Соберите 5 кристаллов дренетиста.', 'Оооо, какие прекрасные образцы! Скорее бы распаковать исследовательское оборудование и как следует рассмотреть их!$B$BСпасибо тебе!', 'Разве не замечательно? После всей этой грязи и насекомых Силитуса здешние места – сущий край обетованный!', NULL, NULL, 'Кристалл дренетиста', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10511, 'Странное пиво', 'Я намерен на сей раз оттянуться по полной, и мне понадобится побольше выпивки. Увы, эльфы ничегошеньки не смыслят в благородном искусстве пивоварения.$B$BЯ тут услышал краем уха, что у огров из клана Кровавого Молота там внизу, в расщелине всякого пойла – хоть залейся! И захотелось мне его попробовать.$B$BНе окажешь ли услугу? Ступай на юг через Живую рощу, а затем вниз по восточному склону к заставе Кровавого Молота, и добудь мне немного тамошнего пойла. Сделаешь? Я слышал, у них огромные бочки пива просто валяются по лагерю, а их пивовары разносят их другим ограм.', 'Добудьте 11 бочонков забористого пойла Кровавого Молота.', 'Что это за запах? Ой, не говори только мне, что это огрское пойло!!!$B$BПрям жуть берет. Да ладно, где наша не пропадала? Залпом!', 'Тут прямо великий сушняк! И как же мне оттянуться-то без выпивки?', NULL, NULL, 'Забористое пойло клана Кровавого Молота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10512, 'Пусть Камнероги упьются!', 'Нет, больше я эту навозную жижу в рот не возьму! Но у меня возникла одна мыслишка.$B$B<Боргрим подмигивает.>$B$BПослушай-ка. Мы знаем, что огры из клана Кровавого Молота без этих помоев просто жить не могут. А что на этот счет думают их враги, клан Камнерогов?$B$B$N, отнеси-ка им остатки этой дряни, и посмотрим, упьются ли они! Их ты найдешь на севере отсюда, если идти от заставы Кровавого Молота через ущелье.', 'Возьмите бочонок забористого пойла Кровавого Молота и попытайтесь напоить допьяна 5 огров Камнерогов.', 'Ах ты, ха-ха-ха! Так я и думал. Я так и думал, что они все без разбору хлебают!$B$BТупые твари!$B$BЛадно, хотя я и остался без выпивки, с твоей помощью мой отдых начался лучше некуда!$B$BВот что я тебе скажу... У нас тут полно барахла, которое нам на самом деле и не нужно. Хочешь что-нибудь взять?', 'Ну, что скажешь? Эти Камнероги тоже пьют что попало, как и Кровавые Молоты, или они от этого пойла чуть не окочурились, как я?', NULL, NULL, 'Напоите огров из клана Камнерогов', 'Бочонок забористого пойла клана Кровавого Молота (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10513, 'Оронок Горемычный', 'Я не знаю, как нам получить то заклинание, о котором поведали духи, $N. По правде сказать, я даже не знаю, где можно начать поиски.$B$B*Торлок, задумавшись, глядит в пространство*$B$BХммм... Идея конечно сомнительная, но как бы это не оказался наш единственный шанс выиграть. Знал я одного орка, точнее даже не знал, видел однажды, но успел пообщаться накоротке. Он живет отшельником над водохранилищем Змеиных Колец к северо-востоку отсюда. Найди этого орка, - Оронока Горемыка.$B$BНу я же говорил, что идея сомнительная.', 'Найдите Оронока Горемычного на Разрушенной Отмели, на северном берегу водохранилища Змеиных Колец.', 'Слова проклятия? Никогда о таких не слышал, мой тебе совет: не тревожь мертвых попусту.$B$BНо раз уж ты все равно здесь, как насчет подработать? Что скажешь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10514, 'Кем только я не был...', 'Я сменил множество занятий. Но неважно, кем я был раньше. Важно, кем я являюсь сейчас, а сейчас я скромный фермер.$B$BЯ использую обученных скверносвинов, чтобы выкапывать клубни из плотной почвы Разоренных равнин. Но с недавних пор живодеры из гнезда, расположенного к северо-востоку, стали нападать на моих животных, и я больше не могу делать свою работу, как прежде.$B$BОтправляйся на север и собери для меня эти клубни. Используй этот свисток, стоя на грядке, чтобы позвать кабана, который разроет для тебя грядку.', 'Принесите 10 клубней долины Призрачной Луны с Разоренных равнин Ороноку Горемычному на его ферму.Ему также необходимо вернуть его свисток.', 'Ты говоришь, там целые стаи этих живодеров? Похоже пора на прополку.', 'Принеси мне клубни!', NULL, NULL, 'Клубни долины Призрачной Луны', 'Вепревый свисток Оронока (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10515, 'Усвоенный урок', 'Мы покажем этим тварям, что значит соваться на поля Оронока!$B$BОтправляйся обратно на Разоренные равнины и уничтожь все их яйца, сколько найдешь. Гнезда находятся глубоко на их территории, так что будь осторожней.', 'Уничтожьте 10 яиц прожорливого камнедера на Разоренных равнинах для Оронока Горемычного.', 'Это отучит этих грязных тварей нападать на моих свинок. Отличная работа, $N!', NULL, NULL, NULL, 'Уничтожено яиц прожорливого камнедера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10516, 'Вещи Поборницы', 'Я понимаю, что это странно, но я желаю оставаться в этой клетке. Это дает мне замечательную возможность сделать то, ради чего я здесь – собрать информацию о клане Камнерогов.$B$BЯ могу сбежать в любой момент, но я бы хотела вернуть мои меч и щит.$B$BМои вещи у двоих их предводителей. У Дроггама мой меч, а у Магдорга – щит.$B$BЕсли придется, добудь пойло с заставы Кровавого Молота к югу отсюда, и подпои этих двоих стражей, но опасайся их трезвых коллег, которые не упьются!', 'Добудьте клинок и щит воздаятельницы Вуулины.', 'Ныне я в великом долгу перед вами, ибо вы помогли мне вернуть мою честь. Но наши труды здесь еще не окончены.', '$N, ты принес мой меч и щит? $B$BХотя я и могу уйти в любой момент, мне не хочется возвращаться в Сильванаар без оружия.', NULL, NULL, 'Клинок воздаятельницы Вуулины', 'Щит воздаятельницы Вуулины', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10517, 'Горр\'Дим, твой час пробил...', 'Предводителя форта Камнерогов зовут Горр\'Дим. Да уж... подходящее имечко.$B$BНо я бы не стала его недооценивать. Он достаточно хитер, чтобы сделать свой клан любимчиком Груула Драконобоя, и теперь они властвуют в этих горах. И Горр\'Дим постоянно ходит с телохранителями, которые поклялись не брать в рот пойла клана Кровавого Молота.$B$BРади безопасности Сильванаара прошу тебя пойти туда и разобраться с ним.', 'Убейте Горр\'Дима, вождя огров форта Камнерогов.', 'Отлично. Из тебя выйдет толк, $C, это несомненно.$B$BНе согласишься ли ты сделать еще одно дело для меня и Сильванаара?', NULL, NULL, NULL, 'Горр\'Дим убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10518, 'Водружение знамени', 'Я желаю, чтобы ты $gпохитил:похитила: знамя клана Камнерогов у одного из их героев и $gдоставил:доставила: его на юг, на заставу Кровавого Молота. Водрузи его на башне Северного Молота.$B$BЭто разъярит клан Кровавого Молота, и они станут наседать на тебя со всей силой. Но зато это обратит их ярость на форт Камнерогов и отвлечет от Сильванаара.$B$BТвое дело будет закончено, когда ты одолеешь Гурна Обжору и заберешь его шлем. Вернись с ним в Сильванаар.$B$BЭто нелегкое дело, $N. Так что возьми с собой пару друзей.', 'Водрузите знамя Камнерогов на башне Северного Молота, чтобы раздразнить Гурна Обжору. Добудьте знамя и шлем Гурна.', 'Шлем Гурна Обжоры и знамя клана Камнерогов?$B$BВы с поборником придумали весьма хитроумный план! $B$BОбратив ярость клана Кровавого Молота на форт Камнерогов, вы ослабили их натиск в здешних местах.$B$BПрошу, $N, прими этот скромный дар Сильванаара.', 'Что это у тебя? Надеюсь, огры из клана Кровавого Молота уже нас не побеспокоят?', NULL, NULL, 'Знамя клана Камнерогов', 'Шлем Гурна Обжоры', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10519, 'Код Проклятия – правда и миф', '$gОронок разгибается и встает в полный рост.>$B$BЯ должен был убедиться, $N. А для этого я должен был испытать тебя. Прости меня за этот маскарад, на самом деле я – такой же фермер, как ты – скверносвин. То есть, откровенно говоря, никакой я не фермер. $B$BЕсли ты $gдолжен:должна: вернуть Код Проклятия, тебе придется выслушать то, что я тебе расскажу. Когда будешь $gготов:готова:, извести меня, и я расскажу тебе эту историю.', 'Поговорите с Ороноком Горемычным на его ферме и выслушайте историю, которую он вам поведает.', 'Теперь ты понимаешь, что тебе предстоит проделать? Найди сыновей Оронока. Найди моих мальчиков...', 'Терпение, $N.', NULL, NULL, 'Код Проклятия – миф и правда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10520, 'Помощь верховному друиду Оленьему Шлему', 'Простите, $C, не уделите ли вы мне крупицу вашего времени?$B$BДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит ни кто иной, как сам верховный друид Фэндрал Олений Шлем.$B$BПрошу вас, если вам интересно, поговорите с лим лично в анклаве Кенария в Дарнассе.', 'Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10521, 'Гром\'тор, сын Оронока', 'Мой первенец Гром\'тор отправился на поиски лагеря Змеиных Колец, к юго-западу отсюда. $B$BВ нашей семье он один воин – сварливый и кровожадный... Все это он унаследовал от своей матушки. Поищи его в окрестностях лагеря Змеиных Колец. Если ты увидишь груды порубленных наг, Гром\'тор обязательно будет где-то поблизости.$B$BКогда найдешь его, скажи: \"Мы проливаем кровь во имя справедливости.\" Тогда он поймет, что ты друг Горемычного, и ты избежишь преждевременной смерти.', 'Найдите Гром\'тора сына Оронока в лагере Змеиных Колец в долине Призрачной Луны.', '<Гром\'тор удовлетворенно ворчит.>$B$BХорошо, что ты пришел. Этот червяк только что раскололся. Наконец-то мы их достали!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10522, 'Код Проклятия: Вклад Гром\'тора', 'Эта мерзкая нага – уже четвертая, которую я допросил сегодня. У него какой-то модный доспех, и я решил, что он может что-то знать. Все остальные были для меня пустой тратой времени.$B$B<Гром\'тор показывает на трупы наг вокруг себя.>$B$BА этого, стоило только один раз ударить, и он тут же мне все и выложил.$B$BПервая часть кода спрятана в сундуке наг, в лагере Змеиных Колец, возле водохранилища Змеиных Колец к востоку отсюда. Он сказал, что наги хранят ключи, которыми открываются сундуки. Возвращайся ко мне, когда найдешь код.', 'Найдите первый фрагмент Кода Проклятия для Гром\'тора, сына Оронока из лагеря Змеиных Колец в долине Призрачной Луны.', 'Это должно попасть к моему отцу.', 'Ну, как успехи?', NULL, NULL, 'Первый фрагмент Кода Проклятия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10523, 'Код Проклятия: Первый Фрагмент', '<Гром\'тор сворачивает документ и убирает его в сейф.>$B$BОтнеси это моему отцу. Он ожидает твоего возвращения на ферме к северо-востоку отсюда.$B$BСкажи ему, что я скоро вернусь, как только закончу тут развлекаться...', 'Принесите Сейф Гром\'тора Ороноку Горемычному на ферму Оронока в Долине Призрачной Луны.', 'Когда Код будет собран целиком, мы покончим с этим проклятием!', 'Все прошло успешно?', NULL, NULL, 'Сейф Гром\'тора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10524, 'Сокровища клана Громоборцев', 'На артефактах клейма, которые говорят о том, что они сделаны орками из клана Громоборцев. Эти орки жили в оплоте Громоборцев до того, как стали орками Скверны.$B$BДо недавнего времени эту крепость занимали огры из клана Камнерогов, пока их оттуда не вышвырнула Орда.$B$BВы слышали и о других утраченных артефактах. Вы вспоминаете, что из этих предметов ищут барабан, стрелу и табличку.$B$BНайдите их в форте Камнерогов и вернитесь с ними к Рокге Живоглотке.', 'Добудьте барабан, стрелу и табличку клана Громоборцев.', 'Глазам своим не верю! Если это какой-то обман, я же шкуру с тебя спущу, $C!$B$BСкорее дай мне посмотреть на эти бесценные сокровища, пока ты не сломал их своими грубыми лапищами!', 'Мы знакомы?', NULL, NULL, 'Артефакт клана Громоборцев (Прилагается)', 'Стрела клана Громоборцев', 'Барабан клана Громоборцев', 'Табличка клана Громоборцев');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10525, 'Путеводный огонек', 'Что ты делаешь, $r? Ты чуть не $gуничтожил:уничтожила: барабан! $B$BЯ так долго старалась заполучить его, и до сих пор все было впустую. Но тебе повезло там, где другие потерпели поражение...$B$BПора призвать огонек, который приведет тебя к последнему сокровищу, которое я ищу.$B$BВозьми эту пылающую частицу моей души. Используй ее для превращения своего тела в пламя и преврати свой дух в путеводный огонек, который устремится вперед и укажет место, где лежит последнее сокровище клана Громоборцев!', 'При помощи фрагмента пылающей души превратите свой дух в путеводный огонек, который приведет вас туда, где находится последнее сокровище Громоборцев.', 'В самой глубине дренетистовых копей? Наверняка огры из клана Кровавого Молота украли это у клана Камнерогов.$B$BХа! Слишком далеко... Слишком глубоко придется заходить на земли клана Кровавого Молота... Это не по мне.$B$BНо тебе это по плечу. Дорогу ты знаешь. Ты пойдешь туда вместо меня!', 'Что ты видишь? Скажи мне, я должна знать, где оно!', NULL, NULL, 'Фрагмент пылающей души (Прилагается)', 'Найдите последнее сокровище клана Громоборцев.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10526, 'Громовая пика', 'Если видение, которое я тебе даровала, не лжет, то ты $gдолжен:должна: идти вниз в ущелье и выйти к южному концу лощины Кровавого Молота. Там ты найдешь копи дренейского аметиста.$B$BПроберись вглубь копей и добудь Громовую пику! Другое тебя волновать не должно - только пика! Мне плевать на тамошние кристаллы и огров.$B$BКак только найдешь пику, неси ее мне!$B$BИ, $N, будь с ней поосторожнее... мне страшно думать, что с тобой будет, если ты ее сломаешь.', 'Добудьте Громовую пику. ', 'Я потрясена! Знаешь, сколькие погибли, пытаясь добыть эти сокровища? $B$BНам очень повезло, что ты нам помогаешь, $N. Хотя ты немного тяжел на подъем.$B$BЯ непременно должна наградить тебя за преданность нашему делу! Выбирай – но с умом. Когда выберешь, я отнесу сокровища в оплот Громоборцев, дабы умиротворить тамошних призраков.', 'Я готова об заклад побиться – ты даже не понимаешь всего значения этих сокровищ!$B$BКогда добудем все пять предметов, наше право на обладание оплотом Громоборцев будет подтверждено тем, что духи мертвых этого места успокоятся.$B$BТеперь понимаешь, почему это так важно? Понимаешь, почему мне не до изящных манер?', NULL, NULL, 'Громовая пика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10527, 'Ар\'тор, сын Оронока', 'Мой младший сын Ар\'тор отправился к аванпосту иллидари далеко к юго-западу отсюда, между фортом Легиона и цитаделью Громового Молота.$B$BХотя Ар\'тор – выдающийся охотник и опытный следопыт, отсутствие вестей о нем меня тревожит. Аванпост иллидари служит тренировочной площадкой демонам Иллидана, тем, которые оставили Легион, чтобы присоединиться к Предателю.$B$BОтправляйся туда и найди Ар\'тора, $N.', 'Найдите Ар\'тора, сына Оронока, на аванпосте иллидари в долине Призрачной Луны.', 'Тело Ар\'тора неподвижно висит в воздухе. Ты не имеешь ни малейшего представления, как долго он уже мертв, но тебе бесконечно жаль Оронока.$B$BВозможно стоит попытаться стащить его тело вниз и отнести отцу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10528, 'Тюрьма из демонических кристаллов', 'Приглядевшись, вы замечаете, что тело Ар\'тора удерживается в воздухе лучами энергии, исходящими от кристаллов, висящих вокруг руны. Вы пытаетесь снять его, но тело остается неподвижным.$B$BВы замечаете, что кристаллы имеют отверстие в основании, очевидно для ключа. Кажется, суккубы время от времени проводят тут какие-то ритуалы.$B$BНайдите на аванпосте иллидари их лидера. Возможно, ключ, необходимый для освобождения Ар\'тора, хранится у нее.', 'На аванпосте иллидари разыщите и убейте госпожу боли Габриссу и вернитесь к телу Ар\'тора, сына Оронока, с хрустальным ключом.', 'Вы вставляете хрустальный ключ в специальные отверстия в основании каждого из демонических кристаллов.', 'Безжизненное тело Ар\'тора неподвижно висит перед тобой в воздухе.', NULL, NULL, 'Кристаллический ключ', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10529, 'Путь охотника', 'Лейтенант Вестница Рассвета из обители Странников желает поговорить со всеми способными охотниками. Тебе не помешает встретиться с ней, $N. Она - светоч мудрости для всех, следующих нашему призванию.$B$BОбитель Странников находится к югу от Луносвета.', 'Поговорите с лейтенантом Вестницей Зари в Обители Странников, что в Лесах Вечной Песни.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10530, 'Путь охотника', 'Лейтенант Вестница Рассвета из обители Странников желает поговорить со всеми способными охотниками. Тебе не помешает встретиться с ней, $N. Она - маяк мудрости для всех, следующих нашему призванию.$B$BОбитель Странников находится на юге от Луносвета.', 'Поговорите с лейтенантом Вестницей Зари в Обители Странников, что в Лесах Вечной Песни.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10531, 'Битва за Низину Арати', '$N, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов. Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки.$B$BСовершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найдите вражеское знамя и сорвите его с флагштока!$B$BКогда сумеете сделать это на четырех указанных базах, возвращайтесь ко мне.', 'Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.', '', NULL, NULL, NULL, 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на ферму совершено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10532, 'Перекрыть линии поставок Аратора', 'Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.$B$BТы, $N, можешь нам помочь. Отправляйся в низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захвати и удерживай под контролем те базы, которые сможешь, выиграй битву и возвращайся ко мне с ресурсами, которые тебе удастся добыть.', 'Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10534, 'Возвращение домой', '$R, $C...$B$BДа, к нам недавно заходил один жрец из ваших, $N. Он сказал, что тебе пора возвращаться в Экзодар, чтобы встретиться с Кедмосом. Кажется, он советовал поторопиться, так что не стоит тянуть время.', 'Кедмос из Экзодара просит вас прийти поговорить с ним.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10535, 'Ресурсы Низины Арати', 'Войну выигрывают солдаты, любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна, еще не начавшись!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо, и все можно добыть там.$B$BИ вот чего я хочу от вас, $N. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.', 'Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Маклир в Опорный пункт.', '', NULL, NULL, NULL, 'Почетный знак Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10537, 'Лон\'горон, лук Горемычного', 'Это знак, $N. Даже смерти не остановить меня. Мое предназначение вернуть эту часть Кода Проклятия, и с твоей помощью оно будет исполнено.$B$BПрежде чем мы предпримем это путешествие, мне понадобится большой лук Лон\'горон. Это - семейная реликвия, которая переходила от одного Вырывателя Сердец к другому на протяжении нескольких поколений. $B$BИнтуиция подсказывает мне, что его забрал демон, ограбивший мой труп. Убивай местных демонов, пока не найдешь мой лук.', 'Отберите у демонов Лон\'горон, лук Горемычного, и верните его духу Ар\'тора на аванпосте иллидари.', 'С моего родного языка это переводится как \"Награда героя\". Это название истинно даже сейчас, когда век наших героев давно миновал.$B$BХотя, сегодня один из них, похоже, стоит передо мной.', 'Не бойся, друг мой. В свое время я помогу тебе.', NULL, NULL, 'Лон\'горон, лук Горемычного', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10538, 'Кипящая кровь', 'Последний эксперимент не то, чтобы полностью не получился – часть крови, которую ты $gпринес:принесла:, удалось спасти. После кипения она должна быть свободна от любого проклятья, какое бы ни наложили на нее колдуны из клана Кровавой Глазницы.$B$BНо для дальнейшего изучения мне нужно еще крови. Ступай в Зет\'Гор и собери кровь орков из клана Кровавой Глазницы. После этого влей ее в котел и прокипяти. Кипящую кровь принеси мне.', 'Поместите кровь орков из клана Кровавой Глазницы в проклятый котел, чтобы получить кипящую кровь. Принесите 12 образцов кипящей крови аптекарю Альбреку на заставу Хребтолома.', 'Очень хорошо...Теперь проводить тесты станет гораздо проще...$B$BСпасибо, $N. Твои таланты заслуживают уважения.', 'Ты принес кипящую кровь, $N? Я хочу изучить ее медленно и со вкусом...', NULL, NULL, 'Кипяченая кровь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10539, 'Возвращение домой', '$r, $C...$B$BДа, к нам недавно заходил один жрец из ваших, $N. Он сказал, что тебе пора возвращаться в Экзодар, чтобы встретиться с Кедмосом. Кажется, он советовал поторопиться, так что не стоит тянуть время.', 'Кедмос из Экзодара просит вас прийти и поговорить с ним.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10540, 'Код Проклятия: Вклад Ар\'тора', 'Наконец-то мы готовы. Я отправлю с тобой часть своей души. Она будет охранять тебя и поможет бороться со злом.$B$BОтправляйся к югу, там у подножия аванпоста иллидари, в Пустоте прячется существо по имени Венератус Многий. Мой охотник на духов вызовет его, когда окажешься поблизости.$B$BУбей Венератуса и забери у него вторую часть Кода Проклятия.', 'Заберите вторую часть Кода Проклятия у Венератуса Многого для духа Ар\'тора с аванпоста иллидари. Существа, убитые или раненые охотником на духов, не приносят вам ни добычи, ни опыта.', '<Дух Ар\'тора мерцает.>$B$BКажется, мой срок истек, друг мой...', 'Ты должен раздобыть шифр!', NULL, NULL, 'Второй фрагмент Кода Проклятия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10541, 'Код Проклятия – Второй фрагмент', 'Благодарю тебя, друг мой, не будь тебя, мой дух бы навечно остался в этом гиблом месте.$B$B<Ар\'тор вручает тебе призрачный сейф.>$B$BВозьми это и отнеси моему отцу, на ферму к северо-востоку, над Водохранилищем Змеиных Колец... Внутри Лон\'горон и второй фрагмент шифра.$B$BТяжело ему станет от известия о моей гибели, но обещай рассказать ему, что я умер свободным. Скажи ему, что я видел Небесные Поля, они великолепны. Я буду ждать его там...', 'Отнесите сейф Ар\'тора Ороноку Горемычному на ферму Оронока в Долине Призрачной Луны.', '', '<Одинокая слеза сползает по щеке Оронока.>', NULL, NULL, 'Запертый сейф Ар\'тора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10542, 'У меня сперли кальян и выпивку!', 'Т\'чали всегда был добрым парнем-троллем! Я пришел сюда учить Кровавый Молот варить пиво! А они закопали меня по шею в землю!$B$BХуже всего – они сперли мой кальян!$B$BНе поможешь ли ты бедному Т\'чали? Верни мой кальян! Т\'чали думает, что те огры, что стянули его, пошли на юго-запад мимо шахты.$B$BИ раз уж ты туда идешь, заодно принеси мне немного выпивки!', 'Добудьте кальян Т\'чали и 10 кружек забористого пойла Кровавого Молота.', 'Да, Т\'чали как раз об этом и говорил! Хотя я и не знаю, чего это огры туда намешали – в кальяне не любимый табачок Т\'чали.$B$BЛадно, Т\'чали все равно рад. Настолько рад, что готов попросить тебя еще коео чем.', 'Эй, где мой кальян и выпивка?', NULL, NULL, 'Кальян Тчали', 'Забористое пойло клана Кровавого Молота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10543, 'Гримнок и Коргаах, я за вами!', 'Т\'чали так ждет этой мести!$B$BКогда они закопали Т\'чали и оставили его помирать, у них главным был Гримнок Дитя Войны. А на другой день на юг пришел набегом Коргаах и стукнул Т\'чали по голове.$B$BЯ хочу их убить!$B$BГримнок сидит на башне заставы Кровавого Молота. А Коргаах сидит на крыше дома в северном конце заставы Камнерогов. У Коргааха в телохранителях сплошные трезвенники, так что ты примани его на пойло, чтобы он от них отошел, потому как они-то пить не станут.', 'Убейте Гримнока Дитя Войны и Коргааха.', 'Т\'чали так рад, что Коргаах и Гримнок откинули копыта, как и он сам!$B$BНо Т\'чали еще не утолил жажду мести. Тебе надо сделать еще одну вещь!', NULL, NULL, NULL, 'Гримнок Дитя Войны убито', 'Коргаах убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10544, 'Чума на оба ваших клана!', 'Т\'чали желает отомстить всем ограм!$B$BТ\'чали при жизни был знаменитым знахарем! Если ты засунешь руку в мою могилу, то найдешь сильный губительный фетиш!$B$BПопроси колдунство фетиша, чтобы оно показало тебе все входы и выходы в дома и башни форта Камнерогов и заставы Кровавого Молота. Это вуду призовет злого духа, которого тебе надо будет одолеть. А это в свой черед навлечет проклятье на дом.$B$BБерегись – если наложишь проклятье на уже проклятый дом, ты призовешь еще одного проклятого духа!', 'При помощи сильного губительного фетиша прокляните 5 домов или башен в крепости Камнерогов и 2 на заставе Кровавого Молота.', 'Ахххха, как сладка месть!$B$BНо Т\'чали видит, что ты хочешь уйти теперь, когда помог Т\'чали отомстить. Понимаю тебя... Жизнь для живых.$B$BВот что я тебе скажу – у Т\'чали в могиле есть еще много хороших штучек. Выбирай то, что тебе больше всего нравится!', 'Тчали не будет говорить, пока $N не использует фетиш и не проклянет дома и башни кланов Камнерогов и Кровавого Молота!', NULL, NULL, 'Прокляните здания форта Камнерогов', 'Прокляните здания заставы Кровавого Молота', 'Сильный губительный фетиш (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10545, 'Бочонок клана Камнерогов', 'Как и говорил Т\'чали, он помогал своим друзьям из клана Кровавого Молота варить пиво. Но Т\'чали не сказал, почему!$B$BЭти Кровавые Молоты попали как куры в ощип. Их долбает клан Камнерогов, и им нужно новое оружие, иначе им хана.$B$BИ тут Т\'чали пришел с великой идеей! Почему бы не изобрести знатное пойло, которое прибавляет тебе сил, а врагов ослабляет? Беда только, что Т\'чали не знает, действует ли пойло.$B$BЗначится, неси это пиво в крепость Камнерогов и посмотри, как подействует!', 'С помощью бочонка забористого пойла Кровавого Молота напоите 5 огров из клана Камнерогов.', 'Хорошие новости! Это пойло очень подойдет для следующей задумки Т\'чали, на которую тебя сейчас Т\'чали подобьет.', 'Ну, не утаивай от Т\'чали – пойло действует? Оно пришлось по вкусу ограм из клана Камнерогов?', NULL, NULL, 'Напоите огров из клана Камнерогов', 'Бочонок забористого пойла клана Кровавого Молота (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10546, 'Борак, сын Оронока', 'Пока Ар\'тор охотился, а Гром\'тор воевал, Борак учился. Наконец, он стал ученым и отправился на Дренор. Он вернулся домой несколько лет назад, совершенно другим.$B$BЕго острая любознательность и острота восприятия сделали из него превосходного убийцу.$B$BТеперь он отправился добывать самую важную и лучше всех охраняемую часть шифра.$B$BНайди Борака возле лагеря Затмения, далеко на юге. Он прячется в тени моста.', 'Найдите Борака сына Оронока возле лагеря Затмения в долине Призрачной Луны.', '<Борак замолкает на мгновение.>$B$BЯ следил за этими эльфами крови уже многие недели, пытаясь добраться туда, где они хранят третью часть Кода Проклятия.$B$BТак или иначе, мне не удалось найти ни одной подсказки, где могло бы быть это место. Единственное, что я знаю, это, что Иллидан каждый день посылает сюда гонца из Черного храма.$B$BНо к этому гонцу невозможно подобраться! Я следил за ним неделю, выискивая способ разлучить его с его телохранителем. Но, к сожалению, тот никуда от него не отходит.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10547, 'Выгодный обмен', 'Я бы сдался, если бы не заметил одну вещь... Он подсел на кровопийку. Я сначала не замечал этого, но все признаки... $B$BТак что, если бы мы заполучили немного этой травы, он был бы у нас в кармане.$B$BВ своих странствиях я встретил одного подозрительного Сломленного по имени Тобиас.$B$BОн меняет эльфам кровопийку на протухшие яйца араккоа.$B$BРуины этих тварей находятся к западу отсюда. Найди яйцо и отнеси его Тобиасу.', 'Найдите тухлое яйцо араккоа и доставьте его Тобиасу Грязежору в город Шаттрат, расположенный на северо-западе леса Тероккар.', 'Так у тебя есть яйцо араккоа? Так чего ж ты молчал! Это ж совсем другое дело! $gТобиас широко улыбается, демонстрируя все свои гнилые зубы.:', '<Тобиас поднимает бровь.>$B$BКровопийка? Никогда не слышал... А ты что, миротворец? Так ты обязан представляться, я свои права знаю!', NULL, NULL, 'Тухлое яйцо араккоа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10548, 'Горькая правда', 'Помнишь - я рассказывала тебе о том жирном торговце, что искал это кольцо? Как оказалось, за кольцом охотился его сын-археолог, и кончил он не слишком хорошо. То есть его убили, отрезали голову и засушили ее.$B$BИ пусть это звучит цинично, расчетливо и даже жестоко, но торгаш готов отвалить кучу денег за голову сына. Работа как раз для тебя!$B$BСтупай на восток, пока не упрешься в развалины тролльских поселений Зеб-Тела и Зеб-Нова. Ты $gдолжен:должна: найти ее в одном из тамошних сундуков.', 'Эраланна из Транквиллиона просит вас найти усохшую голову археолога в одном из сундуков Зеб\'Телы или Зеб\'Новы.', 'Ох ты... Прямо скажем - не красавец. Но, думаю, торговцу он понравится больше, чем мне.$B$BВ оплату он предложил мне купить для тебя любой предмет из моих особых запасов, так что выбирай, милашка!', 'Ну, как охота за головами?', NULL, NULL, 'Усохшая голова археолога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10550, 'Пучок кровопийки', 'Я не лгал тебе. Это яйцо просто потрясающее. Где тебе посчастливилось его раздобыть?$B$BТеперь, если тебе понадобится еще кровопийка, ты знаешь, где меня найти и что мне надо.$B$BВот тебе пучок этой травы, отнеси ее своему покровителю.', 'Отнесите пучок кровопийки Бораку сыну Оронока на мост возле лагеря Затмения, в долине Призрачной Луны. ', '', 'Ты принес кровопийку?', NULL, NULL, 'Сверток кровопийки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10551, 'Присяга верности Алдорам', '', '', 'Вы уверены в своем выборе, $N? Алдоры с радостью примут вас в ряды своих союзников, но Провидцы вряд ли смогут вам это простить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10552, 'Присяга верности Провидцам', '', '', 'Вы уверены в своем выборе, $N? Провидцы с радостью примут вас в ряды своих союзников, но Алдоры вряд ли смогут вам это простить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10553, 'Ворен\'таль Предсказатель', 'Теперь, когда вы определились со стороной, самое время познакомиться с лидером Провидцев – Ворен\'талем Предсказателем.$B$BЕго можно найти в библиотеке Предсказателя на ярусе Провидцев.$B$BВозможно, вы сумеете оказаться ему $gполезным:полезной:, да и вообще Ворен\'таль будет рад тому, что вы решили сотрудничать с нами.', 'Поговорите с Ворен\'талем в его библиотеке на ярусе Провидцев в Шаттрате.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Кадгар прислал новенького? Что ж, за работу, $C!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10554, 'Ишана', 'Раз уж вы решили союзничать с Алдорами, неплохо бы представиться их лидеру – верховной жрице Ишане. Ее можно найти в святилище Вечного Света.', 'Поговорите с Ишаной в святилище Вечного Света на возвышенности Алдоров в Шаттрате.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Добро пожаловать, $N. Я очень рада, что вы решили помочь нам. Да хранит вас Свет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10555, 'Недомогание', 'Магия, которой владеют араккоа Лашш – противоестественна. Они выдирают у себя полные горсти – полные когти? – перьев и используют их в качестве реагентов!$B$BМне такая магия не нравится. Я пришла сюда узнать побольше об их заклинаниях. Увы, приближаться к ним – это для меня уже чересчур.$B$BНо у тебя может и получиться: наложи на себя одно из их заклинаний и возвращайся ко мне. Тебе придется найти одну из их книг заклинаний, что хранятся высоко на деревьях в Гнездовье Лашш.$B$BИ если не обрастешь перьями – а я их у тебя не вижу – то тебе придется добыть их для меня.', 'Соберите 18 выдернутых перьев Лашш.', 'Пролистывая страницы с нацарапанными на них замечаниями и тонкими письменами араккоа Лашш, вы обнаруживаете страницу с изображениями кругов Силы, которые вы видели в Гнездовье Лашш.', 'По грубым рисункам в древнем фолианте вы понимаете, что для творения заклинаний из этой книги понадобится очень много перьев Лашш.', NULL, NULL, 'Выдернутое перо Лашш', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10556, 'Рисунки', 'Рисунки показывают, как использовать перья, чтобы наложить заклятие в одном из кругов Силы в Гнездовье Лашш.$B$BНечеткие рисунки, похоже, показывают араккоа, в которого вселился дух калири.', 'При помощи горсти перьев в круге заклинаний Лашш наложите заклинания.', 'Не знаю, что и сказать. Очень странное заклинание. Это не просто заклинание или чары, но какой-то вид заклинания общения или связи.$B$BЯ не знаю, что с этим делать, $N. Мне придется еще некоторое время над этим подумать.$B$BНо все равно спасибо за помощь! Рано или поздно я с этим разберусь, я уверена.', 'Невероятно! Мне не терпится посмотреть, как работает это заклинание!', NULL, NULL, 'Позвольте Даранелле изучить дух калири', 'Горсть перьев (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10557, 'Испытательный полет: Конденсаторий зефира', 'Я соорудил сногсшибательное устройство, Конденсаторий зефира! Я уверен, что он работает как надо, но... не поможете ли мне испытать его?$B$BПлачу за риск!$B$BПоговорите с моим близнецом Ралли. Удачи, $N. После эксперимента возвращайтесь. Или... если ваши травмы окажутся несовместимы с жизнью, за деньгами может обратиться ваш ближайший родственник.', 'Поговорите с Ралли Быстроцапом и испытайте Конденсанторий зефира.', 'Мамочки мои, вы это сделали! И ни синячка, ни открытого переломчика! Ну, я же говорил, что все будет тип-топ! $B$BВот ваши деньги, $N, хотя я заложился на расходы на лечение, а оно вам не понадобится... Так что считайте премией!', 'Не бойтесь! Это все ради науки. А наука требует жертв!', NULL, NULL, 'Испытайте изобретения Талли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10558, 'Уважительное отношение Оплота Чести', 'Ты уже $gдоказал:доказала: нам, чего стоишь, $N. В один прекрасный день ты можешь стать великим лидером.$B$BЧтобы завоевать уважение моих людей, продолжай сражаться с нашими врагами в Разрушенных залах. Если оправдаешь мои ожидания, я дам тебе более ответственное задание.', 'Командир армии Данат Троллебой из Оплота Чести на полуострове Адского Пламени желает, чтобы вы заслужили уважительное отношение Оплота Чести, продолжив сражаться с орками Скверны в Разрушенных залах цитадели Адского Пламени.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10559, 'Уважительное отношение Траллмара', 'Ты уже $gдоказал:доказала: нам, чего стоишь, $C. Но тебя ждет новое дело.$B$BЕсли хочешь, чтобы твое имя стало известно всем сторонникам Тралла, продолжай сражаться с Ордой Скверны в Разрушенных залах цитадели Адского Пламени.', 'Заслужите уважение Траллмара, сражаясь с орками Скверны в Разрушенных залах цитадели Адского Пламени по совету Назгрела из Траллмара на полуострове Адского Пламени.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10560, 'Почтительное отношение Ша\'тар', '<Умиротворяющая мелодия А\'дала делается тише и печальнее.>$B$B<У вас в голове возникает образ постройки наару, известной как Крепость Бурь. Сейчас там размещены силы Кель\'таса, и сила крепости используется в дурных целях. А\'дал обещает дать вам более престижные задания после того, как вы отвоюете Крепость Бурь.:', 'Заслужите почтительное отношение Ша\'тар, сразившись с силами Кель\'таса в Крепости Бурь, после чего поговорите с А\'далом в Шаттрате.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10561, 'Уважение Хранителей Времени', 'Ты $gдоказал:доказала: свою верность Хранителям, $r. Но этой линии времени по-прежнему угрожает опасность.$B$BНам нужны настоящие герои и верные защитники, и мы очень надеемся на тебя.$B$BОгради события прошлого от враждебного вмешательства, и обретешь уважение Хранителей Времени.', 'Заслужите уважение Хранителей Времени. Для этого необходимо проследить, чтобы никто не нарушил течение времени и не изменил ход прошлых событий в старом Хилсбраде и в Черных топях в пещерах Времени.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10562, 'Окружены!', 'Не теряй бдительности, $r! Нам все еще грозит нападение демонов.$B$BСо своей базы в форте Легиона, к северо-западу отсюда, демоны безнаказанно бомбардируют нас инферналами! Как только мы успеваем справиться с одним отрядом, тут же появляется следующий, и конца им нет. $B$BМои воины измотаны, я не знаю, сколько они еще продержатся. Помоги нам остановить продвижение демонов, $N! Вступай в наши ряды.', 'Убейте 10 боевых инферналов для командира звена Нуаинна из цитадели Громового Молота.', 'Благодарю тебя за помощь, $N. С твоей помощью, мы еще можем удержать цитадель. Но, к сожалению, этого мало. Нам нужно найти способ перейти в наступление.', NULL, NULL, NULL, 'Боевой инфернал убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10563, 'В форт Легиона', 'Форт Легиона практически неприступен, и, если быть честным, у нас не хватает сил для лобовой атаки. Вся надежда на тебя, $N.$B$BЕдинственное, что нам удалось узнать, – в этом форте Легион производит инферналов. С помощью личины, которую я тебе выдам, проберись в Легион и разузнай, каковы их дальнейшие планы. Будем надеяться, что тебе удастся прервать, ну или хотя бы подслушать переговоры между их командирами.', 'Отправляйтесь в форт Легиона, найдите там переговорное устройство и, воспользовавшись маскировкой, выведайте планы Легиона. Вернитесь к командиру звена Нуаинну в цитадель Громового Молота, когда выполните задание.', '<Командир звена Нуаинн слушает твой доклад, вслушиваясь все внимательнее.>$B$BТы хочешь сказать, что они собираются усилить обстрел? Если мы не остановим их раньше, чем они начнут воплощать вторую часть своего плана, цитадель Громового Молота обречена.', 'Что тебе удалось узнать?', NULL, NULL, 'Выведайте планы Легиона', 'Ящик-сюрприз (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10564, 'Перебей инферналов!', 'Устройство, которое мы собрали, не победит на конкурсе красоты, но оно способно уничтожить инферналов, собранных в форте Легиона. Судя по тому, что энергия сердечника сквернобота сотворила с Зловонным прудом, в нем содержится достаточное количество энергии для взрыва.$B$BЕсли ты установишь это устройство в центре зеленого знака в форте, то его силы хватит, чтобы поразить всех инферналов.', 'Используйте бомбу Скверны, находясь в центре зеленого знака в форте Легиона, чтобы уничтожить огненных големов. Доложите о выполнении задания командиру звена Нуаинну из цитадели Громового Молота.', 'Отличная работа, $N! Хотел бы я надеяться, что после такого удара Легиону уже не подняться, но увы...$B$BТеперь наша задача – разобраться с этой Кузницей Смерти.', 'Тебе удалось уничтожить инферналов Легиона?', NULL, NULL, 'Destroy Legion Hold Infernals', 'Бомба Скверны (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10565, 'Камни Векх\'ниров', 'Араккоа Векх\'нира давно уже сущее бельмо у нас на глазу. Они исповедуют какую-то странную религию, которая заставляет араккоа развивать бешеную деятельность. Теперь они носят при себе эти кристаллы, которые используют для каких-то темных целей.$B$BЯ кое-что знаю об их ритуалах. Они приносят эти кристаллы в круг заклинаний и наполняют их какой-то силой. Мы хотим узнать больше. Устрой засаду на араккоа, добудь такой кристалл, заряди его и возвращайся ко мне.', 'Добудьте кристалл Векх\'ниров и отнесите в круг заклинаний Векх\'ниров, чтобы зарядить его.', 'Ах, посмотри, как он светится! Надо поработать над ним.', 'Араккоа Векх\'нира много лет были вполне благожелательными, но теперь что-то взбудоражило их.', NULL, NULL, 'Заряженный кристалл Векх\'ниров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10566, 'Пробы и ошибки', 'Я сделал четыре жезла, которые, на мой взгляд, должны усилить мощь кристаллов араккоа. Отнеси эти жезлы к участку Трогмы и испробуй на одном из огрских рабов.$B$BТебе надо будет для этого найти там пылающий кристалл араккоа.$B$BКогда узнаешь, какой жезл лучший, возвращайся ко мне.', 'Испытайте все жезлы Дертрока на огре-рабе араккоа, затем возвращайтесь к Дертроку. Для использования каждого жезла понадобится пылающий кристалл Векх\'ниров.', 'Эти сведения очень нам пригодятся, $N. Я улучшу свое изобретение, и посмотрим, не сумеем ли мы увеличить диапазон его действия.', 'С нетерпением жду результатов, $N.', NULL, NULL, 'Испытайте первый жезл', 'Испытайте второй жезл', 'Испытайте третий жезл', 'Испытайте четвертый жезл');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10567, 'Создание подвески', 'Араккоа чащобы Рууан избирают из своей стаи Предвестников Ворона, глашатаев своего бога.$B$BОни верят, что Предвестники смотрят на них с небес, получая там наставления Ворона, а затем спускаются, передавая его послания.$B$BПредвестники эти держат в мощной хватке души араккоа. Они используют магические подвески, которые нам и нужны.$B$BПримани одного из Предвестников, убив его стаю и забрав у них когти. Положи когти на алтарь, чтобы привлечь его внимание.', 'Добудьте 6 когтей Рууан\'оков и положите их круг оракула Рууан\'ока, чтобы призвать Предвестника Ворона. Убейте его и получите подвеску Предвестника.', 'Ты добыл ее!$B$BПри помощи этой подвески я смогу настроить тебя на араккоа из Гришната таким образом, что ты сможешь понимать их речь.$B$BТак мы сможем продвинуться в понимании араккоа и сущности Ворона. Для этого мне понадобится твоя помощь.', 'Как только Вестник узнает о вашем нападении на его стаю, он тут же отзовется.', NULL, NULL, 'Подвеска Вестника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10568, 'Таблички Баа\'ри', 'Много лет назад чернокнижник Гул\'дан поднял вулкан посреди долины Призрачной Луны. Дренейская деревня Баа\'ри к юго-западу отсюда, была погребена под потоками лавы, со всеми жителями и хранящимися там ценными артефактами.$B$BИллидан приказал вероломному племени Сломленных, известному как Пеплоусты, начать там раскопки. Мы должны использовать эту возможность вернуть таблички Баа\'ри, текст которых, по слухам, раскрывает секреты храма Карабора... известного сейчас как Черный храм.', 'Соберите для анахоретки Сейлы 12 табличек Баа\'ри. Таблички могут быть где-то закопаны или находиться у Пеплоустов-рабочих.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Таблички Баа\'ри! Это же неоценимый источник информации!', 'Нашел ли ты таблички, $N?', NULL, NULL, 'Фрагмент таблички Баа\'ри', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10569, 'Развалины Скет\'лона', 'Наши разведчики вернулись с руин поселений араккоа.$B$BКто бы мог подумать, что призраки их магов обладают такой невероятной силой. Они собираются, группируются, как будто к чему-то готовятся, и мы никак не поймем к чему. Мы не можем себе позволить больше оставаться в неведении.$B$BОтправляйся на развалины Скет\'лона, к северо-западу от Кузницы Смерти, и выясни, к чему вся эта активная деятельность.', 'Добудьте у темного конклава араккоа и принесите наезднику на грифоне Киерану первую, вторую и третью страницы дневника командира Скет\'лона.', '<Киеран изучает страницы.>$B$BБольшая часть записей абсолютно нечитаема, но из нескольких разборчивых фрагментов, можно понять, что они готовились к какому-то ритуалу. Тут описывается не сработавшее заклятие, стихийные катаклизмы и прочие неприятности... а еще тут есть любопытная запись о каком-то дезертире...', 'Что ты узнал?', NULL, NULL, 'Записи командира Скет\'лона, стр. 1', 'Записи командира Скет\'лона, стр. 2', 'Записи командира Скет\'лона, стр. 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10570, 'Охота на Посла', '$gБорак берет у вас пучок кровопийки и запихивает его в нос.>$B$BОстрая...$B$BТеперь возьми эту связку и положи на другом краю моста. Когда посол наткнется на нее на своем очередном маршруте, он будет вынужден собрать ее сам, без телохранителя. Понимаешь, эльфы крови – настоящие наркоманы, когда дело касается кровопийки. Если хоть кто-то из его соотечественников когда-нибудь узнает... $B$BВсе, что тебе остается, – лежать и ждать, пока он не отошлет телохранителя. Когда он останется один, нападай! Убей его и возьми письмо.', 'Заберите письмо Ярости Бури на мосту возле лагеря Затмения для Борака сына Оронока.', '*Борак берет у тебя письмо и начинает читать.* $B$BХитрые шельмы! Это предписание от Иллидана, который приказывает, где теперь нужно спрятать Код. Очевидно, они постоянно его перепрятывают. Тут нет указаний на то, где он находится сейчас... Если только мы могли бы доставить это письмо по назначению теперь, когда мы знаем следующее укрытие.$B$BЖаль, что печать уже сломана, теперь оно непригодно.$B$BХмм... Все же...', 'Поторопись, парень.', NULL, NULL, 'Послание Ярости Бури', 'Сверток кровопийки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10571, 'Старец Орону', 'Если верить этим табличкам, артефакт, известный как Медальон Карабора, хранился в Баа\'ри. Только дренеям высшего ранга могли предоставить допуск к таким медальонам, поскольку только им было разрешено войти в храм Карабор.$B$BМы должны узнать, вернули ли Пеплоусты медальон, который хранился в Баа\'ри. Его сила послужила бы неплохим подспорьем в нашей борьбе против Иллидана.$B$BЛейтенант Акамы в Баа\'ри, старец Орону, ежедневно получает от него письменные приказы. Раздобудь их и принеси мне.', 'Найдите в руинах Баа\'ри приказы Акамы, адресованные Орону Старцу, и принесите их анахоретке Сейле к алтарю Ша\'тар.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Почерк Акамы... Грустно видеть, что стало с таким могущественным и одаренным существом...', 'Как успехи, $N? Время сейчас играет против нас.', NULL, NULL, 'Распоряжения Акамы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10572, 'Сборка бомбы', 'Мы не можем позволить легиону осуществить свой план по уничтожению цитадели Громового Молота, стоящей на их пути к Черному храму.$B$BУ нас есть одна возможность остановить их, $N. Мы должны устроить взрыв такой силы, чтобы он уничтожил разом всех инферналов. В Зловонном пруду возле форта Легиона находится старый сердечник сквернобота, который можно использовать как основу для бомбы. Поройся в других обломках неподалеку, там еще могут быть сегменты его обшивки, из которых мы сделаем оболочку для бомбы.', 'Добудьте энергетический сердечник и часть обшивки сквернобота и принесите материалы командиру звена Нуаинну из цитадели Громового Молота.', '<Командир звена вставляет сердечник в металлическую оболочку и запечатывает ее.>$B$BДолжно сработать. Эта штука взорвется как надо, уж поверь мне.', '<Вы передаете материалы командиру звена.>', NULL, NULL, 'Энергетический сердечник сквернобота', 'Часть обшивки сквернобота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10573, 'Кузница Смерти', 'Из добытых тобой сведений нам стало известно, что союзный Легиону Совет Теней производит для них инферналов, в месте, именуемом Кузница Смерти. Я послал туда небольшой отряд, чтобы разведать обстановку, но им не удалось добыть все необходимые нам сведения.$B$BЕсли позволить Кузнице Смерти продолжать работу, они быстро восстановят ряды Легиона, и весь наш труд пойдет н$Nку.$B$BЯ хочу, чтобы ты $gвстретился:встретилась: с штормером Эваном Дикокрылом в башне Кузницы Смерти к северо-западу отсюда.', 'Поговорите с штормером Эваном Дикокрылом в башне Кузницы Смерти.', '<Дворф кивает.>$B$BЯ рад наконец получить поддержку. Мы тут собрали кой-какую информацию, о намерениях Совета Теней, но буду исключительно счастлив, когда от наблюдения мы перейдем к активным действиям.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10574, 'Осквернители из клана Пеплоустов', 'Если верить письму Акамы, 4 фрагмента медальона были им найдены и вручены осквернителям из племени Пеплоустов. Эти Сломленные когда-то были могущественными шаманами, но теперь они оскверняют те самые элементы, которым раньше поклонялись.$B$BХаалума – Осквернителя Воздуха можно найти на перевале Крыльев Пустоты. Айкенена и Уйлару, Осквернителей Земли и Огня, в последний раз видели в Ямах Скверны возле Руки Гул\'дана. Лакаан – Осквернитель Воды по слухам находится возле лагеря Змеиных Колец.$B$BНайди их и собери фрагменты медальона.', 'Добудьте 4 фрагмента медальона у Хаалума, Айкенена, Уйлару, и Лакаана и вернитесь к анахоретке Сейле к алтарю Ша\'тар в долине Призрачной Луны.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Да! Все четыре фрагмента собраны. Теперь сложим их вместе...', 'Ты собрал все четыре фрагмента, $N?', NULL, NULL, 'Фрагмент медальона Айкенена', 'Фрагмент медальона Хаалума', 'Фрагмент медальона Лакаана', 'Фрагмент медальона Уйлару');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10575, 'Клеть Стражницы', 'Те фрагменты, что ты $gпринес:принесла:, – это лишь половина медальона. Другая, скорее всего, хранится у предводителя Пеплоустов, Акамы.$B$BМне страшно просить тебя об этом, поскольку Акама так же коварен, как и зол.$B$BОн и его Пеплоусты – Служители Смерти – самые подлые и жестокие в своем племени – судя по слухам, сейчас находятся в пыточной камере в Клети Стражницы.$B$BЯ хочу, чтобы ты $gпробрался:пробралась: в эту жуткую тюрьму и $gузнал:узнала: о местонахождении Акамы. Его первый помощник – Сломленный по имени Санору, тебе придется расспросить его.', 'Отправляйтесь в Клеть Стражницы, к югу от руин Баа\'ри и расспросите Санору о местонахождении Акамы для анахоретки Сейлы.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Мы ждали тебя, $N. Акама говорил, что рано или поздно ты появишься.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10576, 'Уловки Призрачной Луны', '*Борак осматривает тебя с головы до ног.*$B$BЭто будет мудрено, но я справлюсь.$B$BЯ могу превратить тебя в одного из этих иллидарских эльфов крови, $N. Все что мне для этого понадобится, - несколько частей их доспехов. Главное, чтобы броня была чистой. Никаких следов крови! Нам необходимо избежать подозрений.$B$BПринеси их мне, и я позабочусь об остальных частях маскировки.$B$BКак только она будет готова, тебе нужно будет доставить письмо Верховному командиру - доставить лично!', 'Принесите 6 фрагментов доспехов из лагеря Затмения Бораку, сыну Оронока, на мост возле лагеря Затмения в долине Призрачной Луны.', 'Отлично, $N! Надеюсь, ты неплохой актер: следующий этап моего грандиозного плана потребует недюжинного актерского мастерства!', 'Это слишком сложно, $R. Тебе не понять.', NULL, NULL, 'Броня лагеря Затмения', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10577, 'Чего Иллидан хочет, Иллидан получит...', 'Возьми эту личину и проникни в лагерь Затмения. Там надень ее – и эльфы крови не смогут тебя узнать под ней. Это поможет тебе спокойно добраться до главнокомандующего Рууска.$B$BКак только ты найдешь Рууска, скажи ему, куда нужно переместить шифр. Тебе придется много притворяться, $N. Делать вид, что ты на его стороне и $gдоставил:доставила: ему донесение от его начальства. Это должно сработать!$B$BДа! И берегись дракондоров, они способны увидеть твою настоящую личину.', 'Доставьте послание Иллидана главнокомандующему Рууску в лагерь Затмения.', 'Теперь тебе осталось только заполучить Код. Сущие пустяки, не правда ли?', NULL, NULL, NULL, 'Доставьте послание Иллидана.', 'Маскировка под эльфа крови', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10578, 'Код Проклятия – Вклад Борака', 'Этот фрагмент Кода никогда не попадет в руки Зулухеда. Тебе придется перехватить Руула Светокрада и его транспорт, прежде чем он доставит Код.$B$BКрепость Драконьей Пасти находится к востоку отсюда за полями Крыльев Пустоты. Руула ты найдешь, где-то на полдороге между крепостью и святилищем Звезд. Бить надо аккуратно, но сильно. И, $N, судя по слухам, этот Руул – крепкий орешек. Не расслабляйся.$B$BПривези Код мне, и да сопутствует тебе удача!', 'Отберите для Борака, сына Оронока, третью часть Кода Проклятия у Руула Светокрада.Для выполнения этого задания вам потребуются помощники.', 'Наконец-то! Фрагмент шифра у нас в руках!$B$B<Борак кладет его в сейф.>', 'Поторопись!', NULL, NULL, 'Третий фрагмент Кода Проклятия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10579, 'Код Проклятия – Третий фрагмент', 'Отнеси этот сейф моему отцу. Он ожидает тебя на ферме Оронока, далеко на севере отсюда, у Водохранилища Змеиных Колец. Древний шифр возможно будет прочесть только тогда, когда вы соберете все три фрагмента.$B$BУдачи, $N. Передай моему отцу, что я скоро вернусь.', 'Принесите сейф Борака Ороноку Горемычному на ферму Оронока в Долине Призрачной Луны.', 'Как только мы соберем все три фрагмента Кода, можно будет узнать текст старинного проклятия.$B$BРаздобыть эту часть было непросто, и ты заслуживаешь, чтобы твои усилия были вознаграждены.', '$N!', NULL, NULL, 'Запертый сейф Борака (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10580, 'Куда подевались эти клятые гномы?', 'Несмотря на все добро, что мы сделали здесь, одна вещь камнем лежит у меня на душе – мы ведь выжили отсюда Тошли и его гномов.$B$BНо выбора у нас не было – они своими технологиями и экспериментами сводили на нет все наши труды в роще.$B$BЯ буду весьма благодарен, если вы узнаете, что с ними стало. Последнее, что мы слышали – это то, что они ушли на восток за мост. Я уверен, что они свернули на юг, подальше от оплота Громоборцев.$B$BНайдите, где они спрятались в южной части Зазубренной гряды.', 'Обыщите южные районы Зазубренной гряды Острогорья, чтобы найти, где сейчас Тошли и прочие гномы.', 'СИЛЬВАНААР? КОМАНДИР ТЕНЬ НЕБЕС?$B$BИДЕНТИФИКАЦИЯ НЕВОЗМОЖНА!$B$BОТОЙДИТЕ ПРЕЖДЕ ЧЕМ Я БУДУ ВЫНУЖДЕН СКАЗАТЬ ВАМ ГРОМКИЙ ЗВУК!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10581, 'Иди по крошечкам!', 'КОРОЧЕ, СИМ ИЗВЕЩАЮ ВАС, ЧТО НА ЭТОМ ХРЕБТЕ ВЫ НИЧЕГО НЕ НАЙДЕТЕ.$B$BНЕ ХОДИТЕ ПО СЛЕДУ ИЗ ПОТЕРЯННЫХ ЗАПЧАСТЕЙ, КОТОРЫЙ ВЕДЕТ НА СТАНЦИЮ ТОШЛИ! ВЫ НЕ НАЙДЕТЕ ТАМ НИ ТОШЛИ, НИ ЕДИНОГО ГНОМА ВООБЩЕ.', 'Пройдите по следу из запчастей вверх по склону на Островерхий гребень. Поговорите с Тошли на станции в Острогорье.', 'Хорошо, хотите принести пользу? Отлично, я предоставлю вам возможность зарекомендовать себя.$B$BУверен, вам понравится.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10582, 'Приспешники Совета Теней', '$gЭван, кивая, слушает, как вы перечисляете события, произошедшие в форте Легиона.>$B$BЭта информация заставляет по-новому взглянуть на то, что мы уже знаем. Нам было известно, что они отсылают инферналов в форт, но ничего кроме этого узнать не удалось.$B$BСовет Теней запечатал Кузницу крепче, чем новый бочонок громоварского, так что первое, что тебе придется сделать, это расколоть пару черепов, прорываясь туда, чтобы иметь возможность осмотреться. Уничтожь слуг Совета Теней, охраняющих вход в Кузницу Смерти!', 'Убейте 10 стражей и 5 призывателей из Кузницы Смерти для штормера Эвана Дикокрыла.', 'Хотел бы я пойти туда с тобой! У меня просто руки чешутся, пустить в ход свой молот, но моей задачей здесь является только наблюдение, а не битва.$B$BТеперь, когда ты проделал брешь в их обороне, настало время раз и навсегда прекратить производство в Кузнице Смерти.', NULL, NULL, NULL, 'Стражник из Кузницы Смерти убито', 'Призыватель из Кузницы Смерти убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10583, 'Судьба Фланиса', 'На самом деле командир звена Нуаинн посылал сюда троих, чтобы следить за Кузницей Смерти и собирать информацию. Фланис Быстрокрыл вызвался пробраться внутрь и с тех пор мы о нем ничего не слышали.$B$BБоюсь, что на то, что он жив, рассчитывать уже не приходится, $N. Фланис, опытный разведчик, но если ему вдруг требуется помощь, мы никак не можем узнать об этом. Разыщи его в Кузнице Смерти и принеси любые артефакты и информацию, которую он успел собрать.', 'Разыщите Фланиса Быстрокрыла в Кузнице Смерти, и принесите его сумку штормеру Эвану Дикокрылу в башню Кузницы Смерти.', '<Эван качает головой, принимая у вас сумку разведчика.>$B$BСдается мне. Фланис так до конца и не осознал, как хорошо охраняется Кузница Смерти. Теперь мы хотя бы знаем, что творится там внутри. Я не виню его, мне просто хотелось бы, чтобы Фланис подумал об этом, прежде чем отправляться туда.$B$BЯ надеюсь, в этой сумке найдется что-нибудь, что поможет нам навсегда уничтожить эту проклятую кузницу.', 'Ну как, удалось тебе найти Фланиса в Кузнице Смерти?', NULL, NULL, 'Сумка Фланиса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10584, 'Спасти преобразователи энергии!', 'Эти тупые огры с заставы Камнерогов на севере украли наши преобразователи энергии! Давай-ка ты мне их принесешь.$B$BНаверняка они своим лапищами изуродовали преобразователи! Так что я прошу тебя выпустить из них энергию, а потом при помощи протовольтаического магнетоколлектора поймать возникшего электроменталя.$B$BСкорее всего ты ему не понравишься, так что нужно будет \"отключить\" его, пока он будет сидеть в магнитосфере.', 'C помощью протовольтаического магнетоколлектора поймайте 5 электроменталей.', 'Замечательно! При помощи возвращенной нам энергии мы сможем в любом случае некоторое время поддерживать работу нашего оборудования.$B$BКонденсаторий зефира жрет энергию как лошадь!$B$BНадеюсь, с этими электроменталями было нетрудно справиться? У меня есть на примете еще работенка для тебя, если ты не против, но мне кажется, что она будет малость поопаснее.', 'Кого угодно впечатлит ход наших исследований электроменталей! Подумай только – разумные электрические существа, которых мы можем по желанию создавать, и которые будут подчиняться всем наши приказаниям!$B$BЧто тут может не получиться?', NULL, NULL, 'Поймано электроменталей', 'Протовольтаический магнетоколлектор (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10585, 'Чертог Призыва', 'Чтобы производить инферналов так быстро, они должны обзавестись специальным помещением для призыва стихий, которые и составляют суть голема.$B$BЧертог призыва, скорее всего, находится под землей возле пруда с оскверненной водой или лавой. Найди чертог призыва в Кузнице Смерти и отыщи способ прервать происходящий там ритуал. У мо\'аргов, участвующих в производстве инферналов, могут найтись инструменты, способные разрушить магию призыва.', 'Раздобудьте стихийный подчинитель у кузнеца или ремонтника из Кузницы Смерти и используйте его, чтобы прервать ритуал в чертоге призыва. Доложите о выполнении задания штормеру Эвану Дикокрылу из башни Кузницы Смерти.', 'Отлично, $N. С каждым нашим шагом, уничтожение Кузницы Смерти все ближе и ближе.', 'Мы не можем позволить им продолжать производство. Ты положил конец ритуалу призыва?', NULL, NULL, 'Прервите ритуал призыва инфернала', 'Стихийный подчинитель', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10586, 'Смерть вестнику войны!', 'Мы успешно помешали операциям Совета Теней в Кузнице Смерти, но настоящим триумфом станет победа над надзирателем Легиона.$B$BЯ нашел ключ среди всякого хлама в сумке Фланиса. Я уверен, что он поможет нам отыскать завоевателя Разууна, которого ты $gвидел:видела: в форте Легиона.$B$BПосле того как ты выследишь и убьешь Разууна, немедленно сообщи об этом командиру звена Нуаинну!', 'Убейте Разууна Завоевателя, заберите его приказы и вернитесь к командиру звена Нуаинну в цитадель Громового Молота.', '<Вы докладываете командиру звена и отдаете ему добытые приказы.>$B$BСмерть Разууна должна была означать, что все наши проблемы с Легионом окончены, но эти приказы свидетельствуют о том, что возникли новые трудности, которых я опасался. Боюсь, что нам предстоит еще много дел.', 'Какие новости из Кузницы Смерти?', NULL, NULL, 'Разуун Завоеватель убито', 'Приказы Разууна', 'Ключ от Кузницы Смерти', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10587, 'Тренировочная площадка Карабора', 'Наши разведчики донесли о большом количестве эльфов крови – рекрутов Ярости Солнца, направляющихся к руинам Карабора. По правде сказать, похоже на вооруженную угрозу, но я полагаю, что мы не обо всем осведомлены.$B$BСудя по описаниям их униформы и стиля боя, похоже, что это подразделения Иллидана. Я не хочу тревожиться попусту, поэтому отправляйся туда и принеси мне их оружие – так мы проверим, насколько обоснованы мои страхи.', 'Отберите для экзарха Онаалы у соискателей и посвященных охотников на демонов, сосредоточенных в руинах Карабора, 8 глеф армии Ярости Солнца.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Давай-ка взглянем поближе. $N. Хммм... Тревожный знак...', 'Ты выполнил то, о чем я тебя просила, $N?', NULL, NULL, 'Глефа Ярости Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10588, 'Код Проклятия', 'Сколько раз за историю обоих миров было использовано это заклятие? Его разрушающая сила, несомненно, не имеет себе равных.$B$BТы должен взять Код, раз уж он теперь собран весь, и прочитать его возле Алтаря Проклятия, где еще жива память Гул\'дана.$B$BКогда ты произнесешь это заклятие, ты увидишь, как воспоминания отпечатываются на земле. Продолжай оставаться на месте и жди появления Цируха.$B$BНеобходимо осуществить все это сейчас, $N. Еще одного потрясения эта земля не вынесет.', 'Используйте Код Проклятия у Алтаря Проклятия, чтобы призвать Цируха Повелителя Огня.Уничтожьте его и пообщайтесь с целителем земли Торлоком, которого вы найдете там же.', '<Целитель земли забирает у вас Код Проклятия.>$B$BТы выполнил просьбу Стихий. Мы благодарны тебе за это. Ты получишь награду, хотя наши беды на этом не заканчиваются. Духи огня в панике, им была предъявлена претензия, что это заклятие стало известно не только тебе.$B$BЗвучит загадочно, я признаю, но это все, что они смогли мне сказать. Это и вот этот символ...$B$B<Целитель земли Торлок поворачивается и показывает на небо.>$B$BЧто бы это могло значить?', 'Дело сделано?', NULL, NULL, 'Цирух Повелитель Огня убито', 'Код Проклятия (Прилагается)', 'Рекомендуемое количество игроков: 5', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10589, 'Получение доступа', 'Согласно приказам Разууна, область массового расположения инферналов называют Точкой вторжения: Катаклизм, и он находится в горах на севере. Единственный способ добраться до них – использовать телепорт в форте Легиона.$B$BУ некоторых членов Легиона есть устройства, позволяющие им активизировать телепорты. Твоя задача – захватить одно из этих устройств, чтобы получить доступ к телепорту. Вырежь всех демонов, если придется, но не вздумай возвращаться с пустыми руками.', 'Принесите пульт от телепорта Легиона командиру звена Нуаинну из цитадели Громового Молота. Пульты можно найти у мо\'аргов-оружейников в форте Легиона.', 'Дай-ка поглядеть, смогу ли я разобраться, как это работает...', 'Мы должны найти способ уничтожить всех остальных инферналов, Сабантул. Мы далеко продвинулись, но все же неудача дорого нам обойдется.', NULL, NULL, 'Пульт управления телепортатором Легиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10590, 'Доказательство ненависти', 'Пришло время вспомнить о событиях, которые должно помнить всегда... О резне, устроенной Артасом и его армией Плети.$B$BЛишь месть может обегчить нашу боль. К сожалению, бойцам Плети не доступны ни страх, ни страдание. Лишь полное уничтожение этой мерзости принесет малую толику утешения.$B$BПоговори с офицером Гарушем из ордена Серебряного Рассвета - он расскажет, что такое камни Плети и как их можно добудьте - я даже говорить с тобой не хочу, пока не увижу полную горсть таких камней. Так ты докажешь преданность нашему делу.', 'Принесите 20 камней приспешников Плети Мелару Клинку Рассвета из Бастиона.', 'Отлично, $N. Может быть, ты все же познаешь сладость мести.', 'Сколько воинов Плети пало от твоей руки?', NULL, NULL, 'Камень приспешника Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10592, 'Мудрость королевы банши', 'Если вырвать камни Плети из мертвенной хватки владельцев, они теряют силу. Стоило мне подержать их в руках, как они раскрошились.$B$B*Мелар превращает камни Плети в груду мусора.*$B$BОтнесите эти фрагменты королеве банши, Леди Сильване Ветрокрылой. Она восседает на троне в Подгороде. Ей ведомо, как обратить эти жалкие остатки в оружие против Плети.', 'Отнесите фрагменты камня Плети Леди Сильване Ветрокрылой в Подгород.', 'Эти камни затронуты порчей, о которой мне не хочется вспоминать, но и забыть я не в силах. Ты испытываешь мое терпение, принося эту мерзость к моему трону.$B$BИ все же я вижу, что твое сердце пылает той же жаждой мести, что и мое. Я помогу тебе.', 'Что ты мне принес?', NULL, NULL, 'Фрагменты камня Плети (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10593, 'Древнее зло', 'Если ты хочешь превратить эти камни в оружие против Плети, необходимо найти что-нибудь, исполенное такого же зла.$B$BНа дне храма Атал\'Хаккар в трясинах Скорби таится древняя сила. Освободи скрытое там существо и уничтожь его, а малую часть его тела отнеси Мелару Клинку Рассвета. А фрагменты камней Плети отнесут ему мои стражи.', 'Раскройте тайны храма Атал\'Хаккар, освободите Атал\'алариона и добудьте гнилую лозу из его плоти. По выполнении задания вернитесь к Мелару в Бастион.', '', NULL, NULL, NULL, 'Гнилая лоза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10594, 'Калибровка резонансной частоты', 'Доставьте эти сканеры на Звенящий гребень. Сбросив их на землю в определенном порядке, вы создадите перекрывающиеся поля, которые будут считывать амплитуду этих кристаллов. Встаньте в точке перекрытия пяти осцилляционных полей, и я получу нужную мне информацию!$B$BВаши сканеры будут работать в одном режиме с теми, что будут сброшены другими.$B$BОго, похоже, формируется разлом! Понятия не имею, что оттуда полезет, если полезет, но готовьтесь к худшему.', 'Расположите осцилляционные сканеры таким образом, чтобы стоя среди них вы оказались в точке перекрытия пяти осцилляционных полей.', 'Как неожиданно! Я и понятия не имел... эти кристаллы как будто живые!$B$BА вдруг есть какая-то симбиотическая связь между ними и драконам Пустоты?$B$BСпасибо вам, огромное спасибо! Вы просто должны принять в награду кое-что из моей коллекции всякой всячины, из тех штуковин, что я под страхом смерти не надену.$B$BНо вам может подойти.', 'Ну, сняли с поющих кристаллов те показания, которые я просил?', NULL, NULL, 'Вибрационные сканеры частоты (Прилагается)', 'Определите резонансные частоты кристаллов.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10595, 'Окружены!', '$gГалмок смотрит на небо.>$B$BНаши разведчики задали им хорошую трепку, но эти инферналы продолжают прибывать!$B$BСо своей базы в форте Легиона, к юго-западу отсюда, демоны безнаказанно бомбардируют нас! Даже элитная кор\'кронская стража не может вечно их сдерживать.$B$BМне понадобится $gлюбой здоровый:любая здоровая:$r, чтобы защитить деревню Призрачной Луны. Это не игрушки, $C. Выживание деревни – под угрозой. Исполни свой долг перед Ордой и присоединяйся к драке!', 'Убейте 10 боевых инферналов для кровавого стража Галмока из деревни Призрачной Луны.', 'Честно говоря, я удивлен, что тебе удалось пережить резню. Но теперь ясно, что ты именно тот, кому можно поручить трудное и опасное дело.', NULL, NULL, NULL, 'Боевой инфернал убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10596, 'В форт Легиона', 'Отправляйся в форт Легиона. Подкрепления не будет, потому атаковать в лоб не получится.$B$BСудя по всему, Легион готовит в этом форте своих инферналов. С помощью маскировки, которую я тебе выдам, ты $gдолжен:должна: проникнуть в форт Легиона и разузнать их дальнейшие планы.$B$BНадеюсь, тебе удастся подслушать переговоры между командирами.', 'Отправляйтесь в форт Легиона, найдите переговорное устройство и, замаскировавшись, выведайте планы Легиона. Вернитесь к кровавому стражу Галмоку в деревню Призрачной Луны, когда выполните задание.', '<Кровавый страж Галмок слушает ваш доклад, вслушиваясь все внимательнее.>$B$BТы хочешь сказать, что они собираются усилить обстрел? Мы не можем этого позволить. Возвращайся туда и позаботься, чтобы этого не произошло, пока от деревни Призрачной Луны еще что-то осталось.', 'Что тебе удалось узнать?', NULL, NULL, 'Выведайте планы Легиона', 'Ящик-сюрприз (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10597, 'Сборка бомбы', 'Мы не можем позволить Легиону по пути к Черному храму растоптать нас.$B$BНеобходимо найти способ уничтожить инферналов, которых они собираются использовать против нас. Это не просьба, $N, это приказ!$B$BВ Зловонном пруду возле форта Легиона находится старый энергетический сердечник сквернобота, который можно использовать как основу для бомбы. Поройся в других обломках на предмет сегментов обшивки. С их помощью у тебя выйдет бомба достаточно мощная, чтобы задать жару всем этим големам и хорошенько встряхнуть весь форт.', 'Добудьте энергетический сердечник и часть обшивки сквернобота для кровавого стража Галмока из деревни Призрачной Луны.', '<Галмок вкладывает сердечник в доспех и запечатывает его.>$B$BОтлично! Не хотел бы я оказаться в форте, когда эта штука сработает.', '<Вы вручаете материалы Галмоку.>', NULL, NULL, 'Энергетический сердечник сквернобота', 'Часть обшивки сквернобота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10598, 'Перебей инферналов!', 'Устройство, которое мы собрали, не победит на конкурсе красоты, но оно способно уничтожить инферналов, собранных в форте Легиона. Судя по тому, что энергия сердечника сквернобота сотворила с Зловонным прудом, в нем содержится достаточное количество энергии для взрыва.$B$BЕсли ты установишь это устройство в центре зеленого знака в форте, то его силы хватит, чтобы поразить всех инферналов.', 'Используйте бомбу Скверны, находясь в центре зеленого знака в форте Легиона, чтобы уничтожить инферналов. Доложите о выполнении кровавому стражу Галмоку из деревни Призрачной Луны.', '*Галмок мрачно кивает.*$B$BНе время радоваться, боец, мы еще далеко не в безопасности. У меня для тебя есть новое задание.', 'Тебе удалось уничтожить инферналов Легиона?', NULL, NULL, 'Destroy Legion Hold Infernals', 'Бомба Скверны (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10599, 'Кузница Смерти', 'Пока ты $gразбирался:разбиралась: с инферналами в Кузнице Смерти, я просматривал все наши отчеты. У нас нет оснований думать, что Легион лгал о том, что происходит в этой проклятой Кузнице. Они действительно штампуют там инферналов, так что я отправил разведывательный отряд покрутиться в этих местах и понаблюдать за тем, что там творится.$B$BЕсли мы не остановим их деятельность сейчас, они довольно быстро восстановят тех инферналов, которых ты $gуничтожил:уничтожила: в форте Легиона.$B$BОтправляйся к разведчику Заграну, наблюдающему за Кузницей Смерти с верхушки Вышки на золе.', 'Поговорите с разведчиком Заграном на Вышке на золе.', '<Орк кивает.>$B$BЯ рад наконец получить поддержку. Мы тут собрали кой-какую информацию о намерениях Совета Теней, но теперь пришло время обрушить на них наши молоты.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10600, 'Приспешники Совета Теней', '$gЗагран, кивая, слушает, как вы перечисляете события, произошедшие в форте Легиона.>$B$BЭто ответ на все наши вопросы. Мы знали, что они отсылают инферналов в форт, но на этом наши сведения заканчивались.$B$BСовет Теней хорошо охраняет Кузницу, и, похоже, тебе придется пробиваться туда с боем. Уничтожь слуг Совета Теней, охраняющих вход в Кузницу Смерти.', 'Убейте 10 стражей и 5 призывателей из Кузницы Смерти для разведчика Заграна с Вышки на золе.', 'Я бы и сам с удовольствием сокрушил там пару черепов. Но у меня строгий приказ, не привлекать внимания врага.$B$B<Разведчик ворчит, отлично подражая голосу кровавого стража Галмока.>$B$BДавай-ка прикроем эту лавочку.', NULL, NULL, NULL, 'Стражник из Кузницы Смерти убито', 'Призыватель из Кузницы Смерти убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10601, 'Судьба Кагроша', 'В разведывательном отряде сначала было трое членов, но потом Каргош решил поиграть в героя.$B$BОн проник в Кузницу Смерти, и с тех пор мы о нем ничего не слышали.$B$BПо всей вероятности, этот дуралей там и погиб. Члены Совета Теней не идиоты, а Кагрош не был силен в тонкой игре, если ты понимаешь, о чем я. Поищи его в Кузнице Смерти, но больше, чем его судьба, нас интересует информация или вещи, которые он мог собрать.', 'Разыщите Кагроша в Кузнице Смерти и принесите его сумку разведчику Заграну на вышку на золе.', '<Загран качает головой, принимая у вас суму.>$B$BГоворил я тебе, что он был форменным идиотом. Я надеюсь, тут внутри окажется хоть что-то, что оправдает твои усилия, затраченные на его розыски.', 'Ну как, удалось тебе найти Кагроша в Кузнице Смерти?', NULL, NULL, 'Сума Кагроша', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10602, 'Чертог Призыва', 'Чтобы производить инферналов так быстро, как выходит в Кузнице Смерти, они должны обзавестись специальным помещением для призыва стихий, которые и составляют суть голема.$B$BЧертог призыва, скорее всего, находится под землей возле пруда с оскверненной водой или лавой. Найди чертог призыва в Кузнице Смерти и отыщи способ прервать происходящий там ритуал. У мо\'аргов, участвующих в производстве инферналов, могут найтись инструменты, способные разрушить магию призыва.', 'Раздобудьте стихийный подчинитель у кузнеца или ремонтника из Кузницы Смерти и используйте его, чтобы прервать ритуал в чертоге призыва. Доложите о выполнении задания разведчику Заграну на Вышке на золе.', 'Отлично. Мы достигли определенных успехов. С каждым шагом мы все ближе к тому, чтобы покончить с этим делом и спокойно вернуться в деревню Призрачной Луны.', 'Мы не можем позволить им продолжать производство. Ты положил конец ритуалу призыва?', NULL, NULL, 'Прервите ритуал призыва инфернала', 'Стихийный подчинитель', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10603, 'Смерть вестнику войны!', 'Мы успешно помешали операциям Совета Теней в Кузнице Смерти, пришло время заканчивать это задание.$B$BЯ нашел ключ среди всякого хлама в сумке Кагроша. Ему все-таки удалось сделать хоть что-то полезное, прежде чем его схватили.$B$BЭтот ключ поможет нам выследить завоевателя Разууна, которого ты $gвидел:видела: в форте Легиона.$B$BПосле того как ты выследишь и убьешь Разууна, немедленно сообщи об этом кровавому стражу Галмоку. Мы не можем заставлять его ждать.', 'Убейте завоевателя Разууна, добудьте у него приказы Разууна и вернитесь к кровавому стражу Галмоку в деревню Призрачной Луны.', '*Ты отчитываешься перед Кровавым Стражем и сдаешь ему добытые Приказы.*$B$BОтличная работа, $N, но не думаю, что тебе за нее светит какая-нибудь ленточка на грудь. Оставим ночным эльфам навешивать на себя медали и прочие побрякушки. Удел настоящих вояк, рассказывать предания о своих битвах за кружкой доброго эля.', 'Какие новости из Кузницы Смерти?', NULL, NULL, 'Разуун Завоеватель убито', 'Приказы Разууна', 'Ключ от Кузницы Смерти', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10604, 'Получение доступа', 'Согласно приказам Разууна, обширную область производства инферналов называют точкой вторжения: Катаклизм и его последователи осели в северных горах. Единственный способ добраться до них – использовать телепорт в форте Легиона.$B$BУ некоторых членов Легиона есть устройства, разрешающие им активизировать телепорты. Твоя задача – захватить одно из этих устройств, чтобы получить доступ к телепорту. Вырежь всех демонов, если придется, но не смей возвращаться с пустыми руками. Не задерживайся, враги на подходе.', 'Принесите пульт от телепорта Легиона кровавому стражу Галмоку в деревню Призрачной Луны. Пульты можно найти у мо\'аргов-оружейников в форте Легиона.', 'Наконец-то у нас есть средство выкинуть легион из Долины Призрачной Луны!', 'Мы не можем более терпеть присутствие Легиона в самом сердце наших земель! Мы должны найти способ избавиться от них, прежде чем они смогут собрать силы для новой атаки.', NULL, NULL, 'Пульт управления телепортатором Легиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10605, 'Призыв Карендина', 'Вижу, ты жаждешь силы, $N. Что ж, я подскажу тебе, как стать сильнее.$B$BОтправляйся в Подгород и поговори с Карендином Халгаром. Этот старикан научит тебя парочке отличных приемов.', 'Поговорите с Карендином Халгаром в Подгороде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10606, 'Искусство ухода за скверноботом', 'Лучший способ уничтожить остатки припасов Легиона это обратить против них их же собственное оружие. Я работал над оборудованием, которое позволит нам взять под контроль одного из скверноботов-часовых.$B$BНо для этого мне потребуется еще несколько вещей. Например, мне необходимо руководство, которое доктор Потрошилло держит в сундуке у подножия площадки. Скорее всего, он не захочет отдавать тебе ключ без боя, поэтому придется добыть его силой. Принеси мне руководство по эксплуатации сквернобота, и я сделаю все остальное.', 'Убейте доктора Потрошилло и заберите у него ключ. Откройте этим ключом сейф доктора и заберите книгу \"Искусство ухода за скверноботом\". Принесите ее Плекси в Точку вторжения: Катаклизм.', 'Да! Это именно то, что надо. Я никогда не думал, что в Легионе способны на литературное творчество, но так или иначе, считай дело сделано!', 'Добыл руководство?', NULL, NULL, 'Искусство ухода за скверноботом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10607, 'Шепот Бога-ворона', 'Тотемы, оставленные Оракулами Ворона в Гришнате, позволяли араккоа слышать Слово Ворона. Увы, мы не понимаем языка араккоа.$B$BПри помощи подвески Вестника мы можем его понимать. Ты сможешь вызвать души араккоа, чтобы понять их язык. Когда ты будешь $gисполнен:исполнена: душ араккоа, ты сможешь посетить тотемы и понять их весть.$B$BУзнай это для нас, $N.', 'Убейте араккоа Гришны, чтобы на две минуты обрести Понимание речи Ворона. Находясь под действием этого заклятия, вы можете найти и получить пророчества в четырех святилищах.', 'Это очень тревожная весть. Араккоа долгое время жили мирно. Но этот культ Ворона – ничто иное, как сборище неудачников и безумцев.$B$BНо сила их растет, и не обращать на это внимания мы не можем. Возможно, нам еще много придется узнать об этом самом Вороне.', NULL, NULL, NULL, 'Получите первое пророчество', 'Получите второе пророчество', 'Получите третье пророчество', 'Получите четвертое пророчество');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10608, 'Ясно как день!', 'Эти проклятые камнедеры не дают мне проводить исследования на Звенящем гребне! Они выкапывают там кристаллы, и с каждым кристалликом мои шансы на изучение гармоник поющих кристаллов падают все ниже!$B$BВы мне кажетесь как раз тем, кто может мне помочь решить эту проблему! Ступайте на юг и очистите это место от камнедеров!', 'Убейте 10 кристальных камнедеров.', 'Туда им и дорога, вот что я вам скажу! Вонючие твари!$B$BИтак, если вы уверены в том, что истребили этих паразитов, то у меня для вас есть маленький исследовательский проектик. Думаю, вам понравится.', 'Ты уже избавил Звенящий гребень от этих кристаллодеров? Пока они там, мы не сможем начать исследования.', NULL, NULL, 'Кристальный камнедер убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10609, 'Что было первым, дракон или яйцо?', 'Я исследую возможность использования в моей лекарской работе драконьих субстанций. Мне думается, что эти вещества могут стать панацеей для уймы болезней!$B$BИ мне нужно, чтобы кто-нибудь отправился на юг, в Звенящий гребень и принес мне этой субстанции.$B$BХотите взять мой временный фазовый модулятор и опробовать его на дракончиках Пустоты, когда они начнут вылупляться? Добудьте нужное мне вещество из того, что там вылупится.$B$BИ должен добавить, что я совершенно не уверен в том, что оттуда вылезет, поскольку мы используем весьма опасную технику модифицирования времени и пространства.', 'Соберите 3 сущностей прародителя драконов Пустоты, 3 субстанции взрослого дракона и 3 субстанции зрелого дракона.', 'Вы понятия не имеете, насколько важными могут оказаться мои исследования! Благодарю вас!$B$BКак же интересно будет покопаться в сущности этих субстанций! А в особенности мне интересно посмотреть, не выйдет ли из эффекта Пустоты, который превратил яйца черного дракона в яйца дракона Пустоты, каких выгод для моих будущих исследований.$B$BНа самом деле, я думаю, что вы первым испробуете на себе благие качества моего состава. Вот, возьмите эти пробные образцы и используйте по мере надобности.', 'Вы их добыли? Вы принесли три драконовых субстанции, которые были мне так необходимы для продолжения моих исследований? $B$BВы знаете, ведь эти яйца драконов Пустоты прежде были яйцами черного дракона! Это факт! Но когда Дренор разнесло в клочья, внутрь хлынула Пустота, и яйца мутировали!', NULL, NULL, 'Сущность прародителя драконов Пустоты', 'Сущность молодого дракона Пустоты', 'Сущность взрослого дракона Пустоты', 'Временный фазовый модулятор (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10611, 'Искусство ухода за скверноботом', 'Лучший способ уничтожить остатки припасов Легиона это обратить против них их же собственное оружие. Я работал над оборудованием, которое позволит нам взять под контроль одного из скверноботов-часовых.$B$BНо для этого мне потребуется еще несколько вещей. Например, мне необходимо руководство, которое доктор Потрошиллер держит в сундуке у подножия площадки. Скорее всего, он не захочет отдавать тебе ключ без боя, поэтому придется добыть его силой. Принеси мне руководство по эксплуатации сквернобота, и я сделаю все остальное.', 'Убейте доктора Потрошиллера и заберите у него ключ. Откройте этим ключом сейф доктора и заберите книгу \"Искусство ухода за скверноботом\". Принесите его Наканси в Точку вторжения: Катаклизм.', 'Да! Это именно то, что надо. Еще немного отладить и вскоре ты сможешь управлять скверноботом.', 'Добыл руководство?', NULL, NULL, 'Искусство ухода за скверноботом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10612, 'Машина для убийства', '$gПлекси листает справочник.>$B$BНу что ж, тут есть все, что нам надо, но возникает небольшая проблема. Скверноботы не предназначены для удаленного контроля.$B$BМы можем перенастроить одного для тебя, но надолго его не хватит, работать придется быстро, или... тебе лучше не знать, что случится! Я не особо удивлюсь, если твой трюк со скверноботом привлечет внимание Легиона. Держи ушки на макушке и постарайся уничтожить как можно больше их прислужников.', 'Используйте панель управления скверноботом, чтобы захватить контроль над скверноботом-часовым. Уничтожьте 60 инферналов из Кузницы Смерти, прежде чем ваш сквернобот падет. По выполнении вернитесь к Плекси в точку вторжения: Катаклизм.', 'Блестяще! Тебе удалось то, что не смогли сделать все всадники на грифонах цитадели Громового Молота! Ты остановил продвижение легиона и спас нас, от массовой атаки их инферналов. За это мы будем вечно тебе благодарны. $N.', 'Ты вернулся, – значит операция прошла удачно, Что расскажешь?', NULL, NULL, 'Уничтожьте инферналов из Кузницы Смерти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10613, 'Машина для убийства', '$gНаканси листает справочник.>$B$BЗдесь есть вся необходимая информация, но будь осторожен, эти штуки не предназначены для удаленного контроля.$B$BМы можем перенастроить одного для тебя, но надолго его не хватит, работать придется быстро, или... тебе лучше не знать, что случится! Я не особо удивлюсь, если твой трюк со скверноботом привлечет внимание Легиона. Постарайся не лезть на рожон, но помни, что цель твоей миссии и безопасность деревни Призрачной Луны – прежде всего!', 'Используйте панель управления скверноботом, чтобы захватить контроль над скверноботом-часовым. Уничтожьте 60 инферналов из Кузницы Смерти, прежде чем ваш сквернобот падет. По выполнении вернитесь к Наканси в точку вторжения: Катаклизм.', 'Признаюсь тебе, $N, я потрясен тем, что тебе удалось проделать. То, что Легион лишен возможности развязать войну в Долине Призрачной Луны, развязывает нам руки.', 'Ты вернулся, – значит операция прошла удачно, Что расскажешь?', NULL, NULL, 'Уничтожьте инферналов из Кузницы Смерти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10614, 'Шепот ветра', 'Я собирал слухи о Мок\'Наталах по всему Запределью. Похоже, мы наконец-то сможем найти их дом.$B$BНо меня наполняет тревога. Тревога, которая не дает мне уснуть в ночи. Примут ли они меня?$B$BЯ... Я знаю имя их вождя: Леорокс. Найди его. Ты будешь моими глазами в этом деле.', 'Поговорите с Леороксом в деревне Мок\'Натал в Острогорье.', 'Что привело тебя в нашу деревню?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10615, 'Чащоба Рууан', 'Информация о природе араккоа, которую ты $gпомог:помогла: мне добыть, будет весьма интересна и другим.$B$BНас посетил представитель Кенарийской экспедиции, которую также интересуют намерения араккоа здесь, в Острогорье.$B$BНайди его. Его зовут Времион, ты найдешь его в Вечной роще в чащобе Рууан. Следуй по западной дороге отсюда, затем сверни на север после развилки у Островерхого гребня. Когда дорога снова разделится на две у лощины Клинков, ступай по западной.', 'Поговорите с Времионом в Вечной роще, что в чащобе Рууан в Острогорье.', 'А, да, Дертрок. Мы с ним мимоходом говорили об этих араккоа. Должен сказать, что причина нашего... интереса к ним сильно различается.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10617, 'Коконы шелкокрыла', 'Шелк из коконов шелкокрыла в нашей деревне много на что идет. Нам всегда не хватает, да и никогда не хватало.$B$BКоконы с личинок трудно собирать, когда те начинают превращаться.$B$BНаши воины заняты защитой деревни. Если бы ты $gсмог:смогла: набрать для нас коконов, это очень бы нам помогло.', 'Добудьте 8 коконов шелкокрыла с личинок шелкокрыла.Быстро убейте личинок, пока те не начали превращаться в шелкокрылов, прогрызая свои коконы.', 'Хорошие коконы. Вижу, ты навострился их собирать.$B$BМы пробовали выращивать личинок шелкокрыла сами, но, к сожалению, эти малышки не могли вырабатывать достаточно шелка.', 'Для сбора коконов нужна верная и быстрая рука. Надеюсь, тебе повезет.', NULL, NULL, 'Кокон шелкокрыла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10618, 'Нежнейшие крылья', 'Охота на личинок шелкокрыла – нелегкое дело для юных воинов, но хорошо то, что даже если им не удастся снять кокон с личинки, нам пригодятся и крылья вылупившихся шелкокрылов.$B$BНа самом-то деле крылья идут на куда больше изделий, чем коконы, и их никогда не бывает слишком много.$B$BЕсли пойдешь прогуляться, я была бы очень благодарна, если бы ты $gпринес:принесла: мне некоторое количество крыльев.', 'Соберите 12 радужных крыльев.', 'Спасибо тебе, $N. Мы сразу пустим их в дело – и глазом моргнуть не успеешь!', 'Эти крылышки очень нежные, но мы ими очень много вещей украшаем.', NULL, NULL, 'Радужное крыло', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10619, 'Клан Пеплоустов', 'Пеплоустов боятся все Сломленные, В этот клан входят самые жестокие и кровожадные представители племени, которых отбирает лично Акама. Свирепостью они не уступают ни нагам, ни демонам, ни эльфам крови из армии Иллидана, и сейчас они во множестве собрались в руинах Баа\'ри к юго-западу отсюда. Ступай туда и уменьши их число, прежде чем они соберутся напасть на нас.', 'Убейте для воздаятеля Алуумена 3 укротителей, 4 воинов и 6 шаманов из племени Пеплоустов.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Слава наару, $N! Ты исполнил волю Света, сокрушив тех, кто служит Иллидану.', NULL, NULL, NULL, 'Пеплоуст-укротитель убито', 'Пеплоуст-воин убито', 'Пеплоуст-шаман убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10620, 'Угроза горного хребта', 'Нас наняли в помощь Тошли, когда тот решил податься в Запределье, и с тех пор мы все переезжали с места на место.$B$BТеперь, похоже, мы наконец-то пустили корни. Все чокнутые ученые занимаются своими проектами, а мы, Коленорезы, защищаем их.$B$BНо прямо сейчас нам надо, чтобы вы отправились на север на Островерхий гребень или на восток к склону Чешуекрылых и расчистили их от пауков. Это скрытные пауки, что живут в отрогах гор и набрасываются на беспечных путников.', 'Убейте 10 пауков высокогорья. Награда: Очищенное зрение следопыта или Хитрость следопыта.', 'Неплохо для новичка! Как выяснилось, наши яйцеголовые хотят \"понаблюдать\" за технологией духов Астрала на севере. Они просто с ума сойдут от радости, узнав, что вы расчистили им дорогу.$B$BВот, возьмите. Много дать не можем, но, может, вам в будущем пригодится.', NULL, NULL, NULL, 'Паук высокогорья убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10621, 'Осколок погибели Иллидари', 'Похоже, что этот осколок – часть какого-то оружия. Четкие руны, выгравированные на металле, угрожающе светятся.$B$BВы не совсем понимаете, для чего могло быть предназначено это оружие, но не можете пройти мимо. Большинство мо\'аргов в форте Легиона, похоже, работают именно с этим металлом. Возможно, оружейники в цитадели Громового Молота скажут тебе о нем больше.', 'Принесите осколок проклятия иллидари Ординну Громовому Кулаку в цитадель Громового Молота.', '*Ординн забирает у тебя кусок странного оружия.*$B$BДавно я такого не видел. Дело даже не в том, что оно сделано из очень редкой руды, которую не для всяких целей используют. Это очень редкое оружие, не предназначенное для обычной битвы, $N. Оно наполнено магией, призванной уничтожать демонов. Если ты добыл это в Легионе, значит, они что-то замышляют против Иллидана. Удачная находка!', 'Что там у тебя?', NULL, NULL, 'Осколок погибели Иллидари (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10622, 'Доказательство верности', 'Акама пристально наблюдал за тобой все это время, $N.$B$BТе Пеплоусты, которых ты $gубил:убила: в руинах Баа\'ри, были самыми жестокими из нас. Акама тщательно подбирал их, чтобы скрыть от Иллидана истинную цель наших действий.$B$BПрежде всего мы должны были убедиться, что ты не заодно с Иллиданом. Сатир Зандрас наблюдает за нами по его приказу. Убив его, ты докажешь свою верность.', 'Убейте Зандраса в Клети Стражницы и возвращайтесь к Санору.', 'Отлично, $N. Теперь у нас не осталось никаких сомнений, и ты можешь встретиться с Акамой.', 'Выполнил ли ты порученное тебе задание, $N? Доверие не так-то легко заслужить.', NULL, NULL, 'Зандрас убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10623, 'Осколок погибели Иллидари', 'Похоже, что этот осколок – часть какого-то оружия. Четкие руны, выгравированные на металле, угрожающе светятся.$B$BВы не совсем понимаете, для чего могло быть предназначено это оружие, но не можете пройти мимо. Большинство мо\'аргов в форте Легиона, похоже, работают именно с этим металлом. Возможно, оружейники в деревне Призрачной Луны скажут тебе о нем больше.', 'Принесите осколок проклятия иллидари Грокому Мертвому Глазу в деревню Призрачной Луны.', '*Гроком забирает у тебя кусок странного оружия.*$B$BДавно я такого не видел. Дело даже не в том, что оно сделано из очень редкой руды, которую не для всяких целей используют. Вот эти руны наделяли клинок способностью поражать демонов. Представляешь, как Легион должен ненавидеть Иллидана, чтобы наделять своих воинов оружием против демонов? Мы должны попытаться обернуть этот факт себе на пользу.', 'Что там у тебя?', NULL, NULL, 'Осколок погибели Иллидари (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10624, 'История про привидений...', 'Чувствуешь легкий озноб? Или как будто кто-то трогает тебя за плечо? Это не галлюцинации, $r, – это души умерших, запертые в этой земле навечно.$B$BТы хочешь увидеть их? Точно? Подобные встречи непоправимо меняют людей, и не всегда эти перемены – к лучшему.$B$BХорошо. Мне нужно, чтобы ты $gсобрал:собрала: для меня неостывающего пепла. Найти его можно возле лавовых озер на западе Долины Призрачной Луны. В общем, везде, где есть зеленая лава...', 'Принесите главному аптекарю Хильдегард из деревни Призрачной Луны 15 горстей неостывающего пепла.', 'Твой мир скоро непоправимо изменится, $N.$B$B<Хильдегард мастерит что-то из пепла.:', 'Что значит, \"зачем?\"? Очевидно, я собираюсь кое-что приготовить из этого пепла.', NULL, NULL, 'Неостывающий пепел', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10625, 'Спектроскоп', 'Я называю этот прибор \"спектроскопом\" – классное слово, правда? Когда ты надеваешь эти очки, ты можешь видеть духов долины Призрачной Луны.$B$BПрежде чем я отдам их тебе, ты $gдолжен:должна: мне пообещать, что поможешь нам очистить нашу деревню от призраков.$B$BБери эти очки и уничтожь любого духа, который осмелится заявиться в деревню. Будем надеяться, что это заставит их держаться от нас подальше.', 'Убейте для главного аптекаря Хильдегард из деревни Призрачной Луны 12 ревнителей из клана Призрачной Луны.', 'Кровожад? Т... Терон Кровожад? Но... Как? Откуда? Этого не может быть!$B$BОдни легенды о Тероне заставляют трепетать даже Отрекшихся. Говорят, что это был один из чернокнижников Гул\'дана, и чуть ли не самым могущественным из них. Когда Оргрим Молот Рока убил его, Гул\'дан взял душу чернокнижника и поместил ее в доспех убитого рыцаря из Штормграда. Так на службе у Орды появился первый из рыцарей смерти.', 'Если потеряешь свои очки, дай мне знать, я сделаю тебе другую пару.', NULL, NULL, 'Ревнитель из клана Призрачной Луны убито', 'Спектроскоп (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10626, 'Сдать оружие!', 'Если бы нам только достать побольше такого материала, мы смогли бы сковать тебе необходимое оружие.$B$BДва властителя преисподней в форте Легиона: Маказрадон и Моргророн уже снаряжены этим оружием против демонов. Мы не знаем, сколько еще комплектов собирались произвести в Легионе, но если мы добудем эти образцы, нам вполне хватит.$B$B<Ординн ухмыляется.>$B$BЕсть в этом особое моральное удовлетворение, бить Легион его же оружием, как думаешь?', 'Принесите глефу Маказрадона и глефу Моргророна Ординну Громовому Кулаку в цитадель Громового Молота.', 'Отлично! Теперь давай придадим им более удобную форму.', 'Ну что, удалось тебе добыть это оружие?', NULL, NULL, 'Глефа Маказрадона', 'Глефа Моргророна', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10627, 'Сдать оружие!', 'Если бы нам только достать побольше такого материала, мы смогли бы сковать тебе необходимое оружие.$B$BДва властителя преисподней в форте Легиона: Маказрадон и Моргророн уже снаряжены этим оружием против демонов. Если мы добудем эти образцы, мы сможем создать свое собственное на их основе.$B$BЖду не дождусь, когда мы вступим в битву с этим оружием в руках. Это отучит Легион пренебрежительно относиться к магии охотников на демонов.', 'Принесите глефу Мазакрадона и глефу Моргророна Грокому Мертвому Глазу в деревню Призрачной Луны.', 'Отлично! Теперь давай придадим им более удобную форму.', 'Ну что, удалось тебе добыть это оружие?', NULL, NULL, 'Глефа Маказрадона', 'Глефа Моргророна', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10628, 'Акама', 'Ты $gдоказал:доказала:, на чьей ты стороне, и теперь я могу открыть тебе местонахождение нашего вождя.$B$BВ дальних залах ты найдешь подземный проход, замаскированный стоячей водой.$B$BНо никому не говори, о том, что ты там увидишь.', 'Поговорите с Акамой в тайной комнате Клети Стражницы.', 'Здравствуй, $N. Нам о многом надо поговорить.$B$BЯ надеюсь, ты окажешься более восприимчив, чем твои предшественники. Мало кто понимает меня, кроме разве что ближайших соратников, никто не видит тех предзнаменований, которые абсолютно ясны для меня.$B$BЯ примкнул к Иллидану из-за одного из моих видений, гласящего, что иначе мой народ будет уничтожен. Долгие годы я терпеливо ждал других знаков, исхода пророка Велена, открытия Темного портала и, наконец, твоего прибытия.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10629, 'Шизанутая работенка', 'Мне все-таки удалось заставить работать крошшер, но я, кажется, потерял ключи. Я держу в лагере небольшую свору гончих Скверны, на всякий случай, а то вдруг кто залезет. Не скажу, чтобы я был ими доволен – охраняют они не ахти, зато меня все время норовят ухватить за ногу. И тащат все, что плохо лежит. Боюсь, что вот эта собачка как раз и сожрала мой ключ. Я тебе заплачу, если ты выведешь ее погулять, убьешь парочку зловепрей и хорошенько ее накормишь. Потом, когда ее послабит, поищи там ключик.', 'Используйте свисток гончей Скверны, чтобы призвать гончую. Выведите ее на прогулку и убейте парочку безумных зловепрей. Поищите ключи от крошшера в помете гончей Скверны. Верните ключи штейгеру Разлкразу, который находится на руднике к северо-западу от Траллмара.', 'Фу, как ты воняешь! Зато нашлись мои милые ключики! Вот спасибо так спасибо! Теперь-то я точно запущу крошшер, подзаработаю денег и очень, очень скоро свалю подальше из этого Запределья. Никак не могу понять, почему ты тут торчишь, на редкость гадкое место. Не лучше ли вернуться со мной в Пиратскую Бухту?$B$BВот уж мы бы там порыбачили!', 'Ну как, нашлись мои ключики? Уверен, что их сожрала какая-то из этих тварей. Надеюсь, как раз та, которую ты повел на прогулку. Очень надеюсь.', NULL, NULL, 'Ключи от крошшера', 'Свисток гончей Скверны (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10630, 'Рядом с Траллмаром', 'Мне вечно не везет. Проблема в том, что на моем руднике повсюду ган\'арги. Я не могу послать туда батраков и совершенно не хочу рисковать свежепочиненным крошшером, если дело дойдет до драки. Там, в глубине рудника, сидит их главарь. Если ты его убьешь, может, ган\'арги отсюда уберутся? Тогда я наконец заработаю денег и тоже уберусь восвояси.', 'Убейте Урга\'зза и возвращайтесь к штейгеру Разлкразу на рудник к северо-западу от Траллмара.', 'Уф, все ган\'арги наконец убрались отсюда. Уже через неделю я собираюсь помахать всем платочком и отбыть в Пиратскую Бухту. Жду не дождусь, когда наконец снова смогу отправиться на рыбалку. Приехав в Запределье, я совершил огро$Nю ошибку! Послушай моего совета, убирайся и ты подальше отсюда. Можно приятно провести время в Тернистой долине, или, если любишь приключения, отправиться в кратер Ун\'Горо. Главное, только не оставаться здесь!', 'Ну как, он уже помер? Я боюсь туда глянуть.', NULL, NULL, 'Урга\'зз убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10632, 'Точи зубы!', 'Очень мило, что вы помогаете Тошли и его ученым. Но я не могу позволить себе роскоши потакать \"личным\" интересам.$B$BЕсли вам хочется изменить тут ситуацию, вы выполните мою просьбу – а мне сейчас нужно оружие.$B$BНаши ружья хорошо бьют на дальнем расстоянии, но когда эти жуки подбираются слишком близко, приходится держать наготове мощное оружие ближнего боя.$B$BИз зубов кнутохвостов каньона Кинжальной Пасти, что водятся в северной части Островерхого гребня выходят прекрасные виброклинки. Добудьте мне несколько штук.', 'Соберите 5 острейших зубов Кинжальной Пасти.', 'Превосходно, дружище! Если это спасет жизнь хотя бы одного моего солдата, то ваши труды не пропали даром!$B$BИ, думаю, вы тоже должны получить свою награду за пролитые пот и кровь. Раз уж мы скоро получим новое оружие, то почему бы вам не взять на выбор любое из моего?', 'Ну, как добыча зубов?$B$BУверен, что вы добудете их нам без проблем. Пока будете этим заниматься, мы станем удерживать здешнюю заставу.', NULL, NULL, 'Острейший зуб Кинжальной Пасти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10633, 'Терон Кровожад – Правда и Вымысел', 'Есть много историй о жизни Терона Кровожада, но большинство из них – всего лишь истории. Мы не знаем, что случилось с ним после того, как он возвратился в Дренор.$B$BЕдинственное, в чем мы уверены, это в том, что однажды он уже умер.$B$BЯ слышала, разведчики говорили о древнем духе какого-то орка, который обитает у Алтаря Теней, далеко к юго-востоку отсюда, если двигаться через поля и перевал Крыльев Пустоты. Возьми спектроскоп и разыщи дух этого орка. Скорее всего, у него будет больше сведений о Тероне, чем мы имеем сейчас.', 'Найдите древнего духа долины Призрачной Луны для главного аптекаря Хильдегард из деревни Призрачной Луны в одноименной долине. Если вы потеряете свой спектроскоп, Хильдегард может сделать вам новый.', 'Кровожад? Я уже много лет ничего не слышал о нем.$B$BПосле Второй войны он возвратился сюда вместе со своими рыцарями смерти. Неспособный справляться со своей новой оболочкой и без поддержки своего лидера, Гул\'дана, Терон убил себя. $B$BЕсли он теперь вернулся в эти земли как дух, для меня это такая же новость. Хотя я могу раздобыть кое-какие знания с твоей помощью.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10634, 'Прорицание: Броня Кровожада', 'Терон и при жизни был ублюдком, но после смерти он превратился в настоящий кошмар.$B$BК юго-востоку отсюда находится Кряж Крыльев Пустоты. Когда-то он был частью этой земли, а теперь превратился в летающий остров.$B$BОн был домом Велкара – потомка Смертокрыла, но теперь этот остров станет его могилой. Если ты хочешь добыть броню Кровожада, тебе придется убить Велкара, когда-то победившего Терона в бою.', 'Завладейте броней Кровожада по просьбе древнего духа Долины Призрачной Луны, что обитает у Алтаря Теней.', 'Чтобы узнать судьбу Кровожада, я должен заполучить все части его доспеха.', 'Отправляйся на кряж Крыльев Пустоты и раздобудь броню.', NULL, NULL, 'Броня Кровожада', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10635, 'Прорицание: Плащ Кровожада', 'Кровожад совершил множество злодеяний, но ни одно из них по своей тяжести не сравнимо с убийством караборских священников.$B$BПосле того как Орда Гул\'дана победила дренеев Карабора, выживших священников вывели оттуда и объявили, что они будут взяты в цитадель Адского Пламени как военнопленные.$B$BТерон Кровожад, тогда еще не ставший рыцарем смерти, хладнокровно убил их до единого. Теперь они бродят перед Черным храмом и лелеют мысли об отмщении.$B$BИменно у них и хранится плащ Кровожада.', 'Завладейте плащом Кровожада по просьбе древнего духа Долины Призрачной Луны, что обитает у Алтаря Теней.', 'Я не смогу открыть тебе местопребывание Терона Кровожада раньше, чем получу все три части его доспеха.', 'Используй Спектроскоп, чтобы увидеть духов долины Призрачной Луны.', NULL, NULL, 'Плащ Кровожада', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10636, 'Прорицание: буздыхан Кровожада', 'Один за другим становились они перед ним на колени, предлагая свои жизни как доказательство преданности. Кровожад убил их всех. Вскоре после этой резни, он совершил самоубийство.$B$BНо это не было знаком раскаяния, нет, он искал бессмертие! Павшие рыцари Смерти стали Призрачными Всадниками Карабора.$B$BТеперь они ездят по дорогам возле Руки Гул-дана, ожидая возвращения своего хозяина и храня его буздыхан. Добудь мне его.', 'Завладейте буздыханом Кровожада по просьбе древнего духа Долины Призрачной Луны, что обитает у Алтаря Теней.', 'Только соединив все три предмета, я смогу открыть тебе то, о чем ты так жаждешь узнать.', 'Используй Спектроскоп, чтобы увидеть духов долины Призрачной Луны.', NULL, NULL, 'Буздыхан Кровожада', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10637, 'Необходимая уловка', 'Это то самое оружие, а значит, мы не зря опасались. Иллидан тренирует охотников на демонов в руинах Карабора, и мы должны положить этому конец.$B$BПускай тебя не обманывает их название, $N, их оружие обращалось против нас так же часто, как против демонов, которых их чародеи призывают, чтобы тренировать на них новичков.$B$BВластитель преисподней, Азалот, оказался слишком силен, чтобы использовать его на тренировочной площадке, и был пленен. Найди способ освободить его из заключения, пока они будут разбираться с Азалотом, мы выиграем необходимое время.', 'Вернитесь в Руины Карабора и освободите для экзарха Онаалы Разрушителя Азалота.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Будем надеяться, что эта уловка отвлечет их достаточно долго, чтобы мы могли выработать план дальнейших действий.', NULL, NULL, NULL, 'Азалот на свободе', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10639, 'Терон Кровожад, то есть я...', 'Теперь, когда у меня в руках находятся эти вещи Кровожада, осталось раздобыть последнюю часть головоломки, – их хозяина. $B$B<Древний дух долины Призрачной Луны зло улыбается.>$B$BНадеюсь, ты не поверил той красивой сказочке, которую я рассказал? Алтарь Теней – моя тюрьма. Без твоей помощи, я бы навечно застрял бы здесь. Теперь, я заполучу твое тело, и ты убьешь моих пленителей и разрушишь узы, удерживающие меня здесь. Можешь отказаться, и мы оба застрянем тут навечно.$B$BТерон жестокосердный будет свободен!', 'Древний дух долины Призрачной Луны обвел вас вокруг пальца! Вы сделали все, что он просил, но оказалось, что этот дух – сам Терон Кровожад. Чтобы освободиться от его власти вы должны выполнить его распоряжение и убить Карсиуса Дозорного Древности.По выполнении задания вернитесь к главному аптекарю Хильдегард в деревню Призрачной Луны.', 'Что ты сделал? ИДИОТ!$B$BТеперь тебе придется самому расхлебывать последствия собственной ошибки. Возьми один из этих шлемов. Каждый из них сделан с помощью неостывающего пепла, который ты мне принес. Шлем поможет тебе увидеть призраков Долины Призрачной Луны, включая Терона Кровожада.$B$BКак только ты найдешь Терона, уничтожь его.', NULL, NULL, NULL, 'Карсиус Дозорный Древности убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10640, 'Алтруис', 'Редко сейчас услышишь о тех, кто избирает стезю охотника на демонов. Еще реже можно встретить таких, кто избирает, но не приносит при этом присяги Иллидану.$B$BХодят слухи, что один такой обретается здесь, в Запределье. Одно его имя наводит ужас на лагеря Легиона в Награнде больше, чем все воздаятели Алдоров, вместе взятые. И это имя – Алтруис.$B$BОтправляйся в западный Награнд и найди его. Он сможет рассказать тебе о новой тренировочной площадке для охотников на демонов.', 'Отправляйтесь в западный Награнд и найдите Алтруиса Страдальца.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Ты проделал долгий путь, странник. Удивительно, что тот, кто послал тебя, вообще обо мне слышал.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10641, 'Против Легиона', 'Пылающий Легион то и дело совращает души смертных. Если ты хочешь, чтобы я доверил тебе те знания, коих ты ищешь – докажи свою верность.$B$BДемоница по имени Саталь в свое время ускользнула от меня, ибо она бестелесна.$B$BОна опекает зловещих жриц, которые поклоняются ей на базе Легиона: Геенна. Убей одну из ее приспешниц и пролей ее кровь. Это оскорбление заставит Саталь на время принять материальное обличье. В это время убей ее.', 'Алтруис Страдалец просит вас добыть свежей крови зловещей жрицы на базе Легиона: Геенна в Пустоверти. Пролейте кровь на землю и убейте аватару Саталь. По выполнении задания вернитесь к Алтруису.', 'Ты доказал, что твоя душа не извращена Легионом, а враг моего врага – мой друг.', NULL, NULL, NULL, 'Аватара Саталь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10642, 'Дух из машины', 'Боюсь, эти дворфы не понимают, где они обосновались. Я имею в виду духов. Когда-то эта местность принадлежала оркам из клана Призрачной Луны, $r.$B$BПочти двадцать лет они мирно покоились под цитаделью Громового Молота. Но что-то их разбудило. $B$BОтправляйся за пределы крепости к озерам лавы. На их берегах можно найти неостывающий пепел. Принеси мне его, и я сделаю вещь, которая поможет тебе.', 'Принесите 15 горстей неостывающего пепла Зорусу Ревнителю в цитадель Громового Молота в долине Призрачной Луны.', '<Зорус начинает мастерить что-то из пепла.>$B$BГотово! Держи это – спектроскоп.', 'Да. Другое измерение существует... Я это чувствую.', NULL, NULL, 'Неостывающий пепел', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10643, 'Вестники Призрачной Луны', 'Да будет тебе известно, у Зоруса есть чувство юмора.$B$BДостаточно болтовни. Надень спектроскоп, иначе ты не сможешь увидеть дух орка, который блуждает в этих стенах. Не пугайся, как если бы мы действительно были бы захватчиками. Увы, их время ушло.$B$BУничтожь предвестников из клана Призрачной Луны, наводнивших цитадель Громового Молота, и возвращайся ко мне.', 'Убейте 12 предвестников из клана Призрачной Луны для Зоруса Ревнителя из цитадели Громового Молота.', 'Ты говоришь, что слышал шепот призраков? И они упоминали Терона Кровожада?$B$B<Зорус вздрагивает.>$B$BДа, я знаю его, точнее сказать, я о нем слышал. Но ведь считается, что он уже давно мертв? Почему же эти призраки говорят о нем?', 'Если потеряешь свои очки, дай мне знать, я сделаю тебе другую пару.', NULL, NULL, 'Предвестник из клана Призрачной Луны убито', 'Спектроскоп (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10644, 'Терон Кровожад – Правда и Вымысел', 'Есть много историй о жизни Терона Кровожада, но большинство из них – всего лишь истории. Мы не знаем, что случилось с ним, после того, как он возвратился в Дренор.$B$BЕдинственное, в чем мы уверены, это в том, что он уже однажды умер.$B$BЯ слышал, разведчики говорили о древнем духе какого-то орка, который обитает у Алтаря Теней, далеко к востоку отсюда, если двигаться через Поля и перевал Крыльев Пустоты. Возьми спектроскоп и разыщи дух этого орка. Скорее всего, у него будет больше сведений о Тероне, чем мы имеем сейчас.', 'Найдите древнего духа долины Призрачной Луны для Зоруса Ревнителя в цитадели Громового Молота. Если вы потеряете свой спектроскоп, Зорус может сделать вам новый.', 'Кровожад? Я уже много лет ничего не слышал о нем.$B$BПосле Второй войны он возвратился сюда вместе со своими рыцарями смерти. Неспособный справляться со своей новой оболочкой и без поддержки своего лидера, Гул\'дана, Терон убил себя. $B$BЕсли он теперь вернулся в эти земли как дух, для меня это такая же новость. Хотя я могу раздобыть кое-какие знания с твоей помощью.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10645, 'Терон Кровожад, то есть я...', 'Теперь, когда у меня в руках находятся эти вещи Кровожада, осталось раздобыть последнюю часть головоломки, – их хозяина. $B$B<Древний дух долины Призрачной Луны зло улыбается.>$B$BНадеюсь, ты не поверил той красивой сказочке, которую я рассказал? Алтарь Теней – моя тюрьма. Без твоей помощи, я бы навечно застрял бы здесь. Теперь, я заполучу твое тело, и ты убьешь моих пленителей и разрушишь узы, удерживающие меня здесь. Можешь отказаться, и мы оба застрянем тут навечно.$B$BТерон жестокосердный будет свободен!', 'Древний дух долины Призрачной Луны обвел вас вокруг пальца! Вы сделали все, что он просил, но оказалось, что этот дух – сам Терон Кровожад. Чтобы освободиться от его власти вы должны выполнить его распоряжение и убить Карсиуса Дозорного Древности.По выполнении задания вернитесь к Зорусу Ревнителю в цитадель Громового Молота.', 'Что ты сделал? ИДИОТ!$B$BТеперь тебе придется самому расхлебывать последствия собственной ошибки. Возьми один из этих шлемов. Каждый из них сделан с помощью неостывающего пепла, который ты мне принес. Шлем поможет тебе увидеть призраков Долины Призрачной Луны, включая Терона Кровожада.$B$BКак только ты найдешь Терона, уничтожь его.', NULL, NULL, NULL, 'Карсиус Дозорный Древности убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10646, 'Ученик Иллидана', 'Ты $gдоказал:доказала: свою преданность, $N. Прости мне мою недоверчивость и подозрительность, но в этом мире опасно полагаться на первое впечатление - внешность часто бывает обманчива.$B$BКогда будешь $gготов:готова:, я расскажу тебе о Варедисе.', 'Выслушайте рассказ Алтруиса. ', 'Теперь ты все знаешь. И нам осталось закончить всего одно дело.', 'Да, Варедис силен. Однако есть способ его одолеть.', NULL, NULL, 'Ученик Иллидана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10647, 'Разыскивается: Увурос, бич долины Призрачной Луны', 'Разыскивается – МЕРТВЫМ:$B$BУвурос – бич долины Призрачной Луны.$B$BПо приказу воеводы Ор\'бароха, тварь скверны – Увурос – должен быть убит, а его грива отделена от тела в знак выполнения этого задания. Доставьте пламенеющую гриву этого чудовища военному глашатаю Сардону Чистому Удару – и вас ждет награда.$B$BВ последний раз Увуроса видели возле Руки Гул\'дана, в самом сердце долины Призрачной Луны к востоку от деревни Призрачной Луны.', 'Убейте Увуроса и доставьте его пламенеющую гриву военному глашатаю Сардону Чистому Удару в деревню Призрачной Луны в одноименной долине.', 'Вот это да! Таки завалил его! Отлично! Теперь получишь награду. Не сумлевайся!', 'За наградой явился, приятель?', NULL, NULL, 'Пламенеющая грива Увуроса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10648, 'Разыскивается: Увурос, бич долины Призрачной Луны', 'Разыскивается – МЕРТВЫМ!$B$BУвурос – бич долины Призрачной Луны.$B$BПо приказу тана Йорегара, тварь Скверны – Увурос – должен быть убит, а его грива отделена от тела в знак выполнения этого задания. Доставьте пламенеющую гриву этого чудовища военному глашатаю Пивному Брюху, и вас ждет награда.$B$BВ последний раз Увуроса видели возле Руки Гул\'дана, в самом сердце долины Призрачной Луны к северо-востоку от цитадели Громового Молота.', 'Убейте Увуроса и доставьте его пламенеющую гриву военному глашатаю Пивному Брюху в цитадель Громового Молота в долине Призрачной Луны.', 'Вот твоя награда. Однако советую не спускать ее всю и сразу.', 'Я надеюсь, что ты совершил нечто необыкновенное, парень. В противном случае – брысь отсюда!', NULL, NULL, 'Пламенеющая грива Увуроса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10649, 'Книга Имен Скверны', 'Меня радует твое желание остановить Варедиса и его последователей, но сейчас тебе с ним не справиться. Сначала нужно найти артефакт, который наделил Варедиса его силой.$B$BХодят слухи, что в Темном лабиринте в Аукиндоне есть некто по имени Черносерд Подстрекатель. Он владеет Книгой Имен Скверны. Только она поможет тебе противостоять Варедису.', 'Проберитесь в Темный лабиринт в Аукиндоне и добудьте у Черносерда Подстрекателя Книгу Имен Скверны. После этого вернитесь в Награнд к Алтруису.', 'Сила, которую излучает эта книга, чувствуется даже на расстоянии. Очень сложно преодолеть искушение оставить ее у себя.', 'Удалось ли тебе добыть книгу, $N?', NULL, NULL, 'Книга Имен Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10650, 'Возвращение к Алдорам', 'Эта книга... С ее помощью моя сила возросла бы десятикратно... Но нет! Это нанесло бы непоправимый вред моей душе, я уверен. Возвращайся к тем, кто послал тебя, $N.$B$BТеперь у тебя есть средства остановить Варедиса. Дождись, пока он не покажет свою демоническую сущность в процессе перевоплощения, и в этот момент сожги перед ним эту книгу. Это единственный способ лишить его силы.', 'Поговорите с экзархом Онаалой у алтаря Ша\'тар, в долине Призрачной Луны.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Как ты посмел принести в святое место эту мерзкую книгу? Надеюсь, у тебя есть для этого действительно веские причины, $N. Иначе...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10651, 'Варедиса нужно остановить!', 'Мы должны избавиться от этого дурацкого артефакта, но не раньше, чем мы используем его для того, чтобы обессилить Варедиса.$B$BМы должны окончательно разрушить тренировочную площадку в руинах Карабора, что означает, что нам предстоит убить не только Варедиса, но и троих ночных эльфов – его помощников. Аландиен, Тераса и Нетариеля.$B$BСобери подходящий отряд и возвращайся в Руины Карабора. Следуй указаниям Алтруиса, чтобы победить Варедиса. Я очень надеюсь, что они сработают.', 'Отправляйтесь в Руины Карабора и убейте Аландиен, Тераса, Нетариеля и самого Варедиса. Используйте Книгу Имен Скверны, когда Варедис будет перевоплощаться, чтобы ослабить его. Вернитесь к экзарху Онаале с книгой Имен Скверны, по выполнении задания.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Браво, $N! Твоя победа над Варедисом очень важна для нашей войны с Иллиданом.$B$BТы зарекомендовал себя не только среди Алдоров, но и перед всем Запредельем. Позволь мне теперь уничтожить то, что осталось от этой чудовищной книги.', 'Удалось ли тебе исполнить то, о чем я просила, $N?', NULL, NULL, 'Варедис убито', 'Нетариель убито', 'Терас убито', 'Аландиен убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10652, 'В тылу врага', 'Мы приготовили все, чтобы провести тебя туда, где скрываются наши шпионы. Приходи, когда подготовишься, и мы укажем тебе дорогу.', 'Поговорите с Веронией, когда будете готовы отбыть в манагорн Коруу. Оказавшись там, поговорите с Каледисом Сияющим Рассветом.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Добро пожаловать, $C. Постарайся не демаскировать наше местоположение. $B$BМы не продержимся долго, если ищейки Келя вынюхают нас.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10653, 'Знаки Саргераса', 'Теперь тебе должно быть ясно, почему мы враждуем с Легионом и его приспешниками.$B$BЕсли ты хочешь упрочить свое положение среди Алдоров, принеси мне высшие знаки отличия Легиона и их последователей из Совета Теней. Здесь, в Долине Призрачной Луны, а также в Пустоверти сейчас находится множество воинов Легиона.', 'Принесите 10 знаков Саргераса Адуину Стражу Света в Шаттрат.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Сражаться с демонами Пылающего Легиона и культистами, которые им поклоняются, - задача не из легких, $N, но у вас достаточно смелости и решительности. Продолжайте в том же духе, и отношение Алдоров к вам будет постоянно улучшаться.', 'Принес ли ты, вражеские знаки отличия, $N?', NULL, NULL, 'Знак Саргераса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10654, 'Больше знаков Саргераса', '', '', 'Вы растете в наших глазах, $N. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.', NULL, NULL, NULL, 'Знак Саргераса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10655, 'Знак Саргераса', '', '', 'Вы растете в наших глазах, $N. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.', NULL, NULL, NULL, 'Знак Саргераса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10656, 'Перстни Ярости Солнца', 'Как ты уже, наверное, знаешь, между Провидцами и армией Кель\'таса идет война. Кель\'тас считает, что мы угрожаем его влиянию на эльфов крови, поэтому постоянно преследует нас.$B$BЕсли хочешь помочь нам в борьбе с Кель\'тасом, то работы для тебя найдется предостаточно. Воины Кель\'таса высшего ранга носят перстни Ярости Солнца – принеси мне их, сколько найдешь. Этих воинов можно найти в Пустоверти и Долине Призрачной Луны.', 'Принесите магистру Файленн 10 перстней Ярости Солнца.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Армия Келя отлично обучена, но, несмотря на это, вы прекрасно справились, $N.', 'Ну же, $N. Говорите.', NULL, NULL, 'Перстень Ярости Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10657, 'Оседлать молнию', 'На содержание Конденсатория зефира у нас в бюджете нет расходной статьи. Но мне удалось узнать, что змеи со склона Чешуекрылых на востоке отсюда выдыхают молнии, и у них есть железы которые нам могут пригодиться.$B$BЯ переполяризовал индукционный коллектор, чтобы поглощать удары молний, и хочу, чтобы вы отправились туда, активировали его и добыли нам дешевый источник энергии из этих змей.', 'Абсорбируйте 25 ударов молний от чешуекрылых змеев при помощи реполяризованной магнитной сферы. Также добудьте 5 молниевых желез чешуекрылых.', 'Ха-ха, сработало! Честно говоря, я не был уверен... вероятность того, что вас пришибет при третьем ударе, по моим подсчетам, была равна двадцати трем целым семидесяти двум десятым процента!$B$B<Тошли невинно улыбается.>$B$BИтак, теперь мы знаем, что моя сфера работает, так что у нас не будет проблем с нехваткой энергии для Конденсатория зефира... ну, в случае, если мы найдем достаточно добровольцев, чтобы ходить туда и подставляться под молнии!$B$BНо вы были первым, так что заслуживаете кое-какой награды!', 'Вся хитрость реполяризованной магнитной сферы в том, что нужно точно знать, когда ее выключить, чтобы не поджариться окончательно.$B$BКонечно, надо учитывать, встречу со сколькими крылатыми змеями вы намерены пережить.$B$BКстати, к слову – вы сумели зарядить сферу?', NULL, NULL, 'Поглощено ударов молний', 'Молниевая железа чешуекрылого', 'Реполяризованная магнитная сфера (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10658, 'Больше перстней Ярости Солнца', '', '', 'Прекрасно! Теперь Кель\'тас перестанет нас недооценивать!', NULL, NULL, NULL, 'Перстень Ярости Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10659, 'Перстень Ярости Солнца', '', '', 'Армия Келя скоро падет.', NULL, NULL, NULL, 'Перстень Ярости Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10660, 'Что за странные создания?', 'Я хочу заняться изучением странных рептилий, которые водятся возле потоков лавы в долине Призрачной Луны. Я никогда еще не видел животных способных противостоять обжигающему жару лавовых потоков!$B$BЗа пределами деревни Призрачной Луны, там, где земля просела, и лава выходит на поверхность через трещины, ты найдешь сквернопламенных деметродонов. Убей их и принеси мне их селезенки. Заполучив их, я смогу начать предварительные исследования их жароустойчивости.$B$BНачни с юго-востока.', 'Добудьте 8 селезенок сквернопламенных деметродонов для ученого Тиоруса в деревне Призрачной Луны в одноименной долине.', '<Ученый Тиорус берет у вас селезенки и начинает изучать их.>$B$BЭто займет какое-то время. Возьми, это деньги за твою работу.', 'Мне нужны селезенки! Где мои селезенки!', NULL, NULL, 'Селезенка сквернопламенного деметродона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10661, 'Умопотрошительно!', 'Тебе приходилось слышать о еде, которая готовится сама и всегда остается горячей? Мечта идиота, не правда ли?$B$BВозможно это отнюдь не мечта... За стенами крепости возле озер лавы обитают животные, которым не страшен невыносимый жар. Их называют сквернопламенными деметродонами.$B$BМестные дворфы сказали мне, что у этих деметродонов самая вкусная селезенка на свете, и что эту селезенку практически не надо готовить. Принесите мне ее, и я даже вам немного заплачу.$B$BНачинайте поиск к востоку отсюда.', 'Принесите 8 селезенок сквернопламенных деметродонов Гномусу в цитадель Громового Молота.', '<Гномус с голодным видом выхватывает у вас селезенки.>$B$BВот твои деньги, как я и обещал. Если мне понадобится еще, я с тобой свяжусь.$B$BКак вкусно... Даже не побоюсь этого слова \"Умопотрошительно!\"', 'Мне нужны селезенки! Где мои селезенки!', NULL, NULL, 'Селезенка сквернопламенного деметродона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10662, 'Кузнец–отшельник', '$gОрдинн изучает результат своих усилий и качает головой.>$B$BЯ не могу тебе помочь, но это не значит, что это оружие не может быть воссоздано.$B$BВ свое время, был один талантливый оружейник, который сопровождал Сынов Лотара на Дренор, Дэвид Уэйн. Он был выдающимся оружейником, но решил оставить экспедицию. Сейчас он обитает в маленьком лагере на полуострове к востоку от лагеря Огнекрылых в лесу Тероккар. Отнеси ему слитки, возможно, он сумеет помочь.', 'Принесите ящик со слитками Дэвиду Уэйну в приют Уэйна, который находится в лесу Тероккар.', 'Ординн послал тебя сюда?$B$B<Кузнец изучает слитки.>$B$BОн был прав. Большая часть магии ушла, но я еще в силах почувствовать ее след. Немного усилий, парочка редких ингредиентов, и ты получишь превосходное оружие против демонов.', 'Что привело тебя сюда, $C? У меня не часто бывают гости.', NULL, NULL, 'Ящик со слитками (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10663, 'Кузнец–отшельник', '$gОрк отрицательно качает головой.>$B$BЯ не могу тебе помочь, но это не значит, что это оружие не может быть воссоздано.$B$BКак ни больно мне это признавать, но единственной твоей надеждой сейчас является человеческий кузнец Дэвид Уэйн. Да, однажды он принимал участие в одной из экспедиций Альянса, но это было давным-давно, и с тех пор он оставил Сынов Лотара. Сейчас он обитает в маленьком лагере на полуострове к востоку от лагеря Огнекрылых в лесу Тероккар. Отнеси ему слитки, возможно, он сумеет помочь.', 'Принесите ящик со слитками Дэвиду Уэйну в приют Уэйна, который находится в лесу Тероккар.', '<Кузнец хмурится и оглядывает слитки.>$B$BПризнаюсь тебе честно, $C. В мои времена сотрудничество с Ордой было просто невозможно себе представить.$B$BНо я не настолько слеп, чтобы не видеть, что у нас появились общие враги. Я помогу тебе восстановить оружие против демонов, но это потребует от тебя много упорной работы и некоторых очень редких ингредиентов.', 'Что привело тебя сюда, $C? У меня не часто бывают гости.', NULL, NULL, 'Ящик со слитками (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10664, 'Дополнительные материалы', 'Слитки, которые ты $gпринес:принесла:, пойдут на лезвие, но мне понадобится множество других вещей, чтобы создать другие части меча.$B$BДавай посмотрим, чего мне не хватает... адамантитовой рамки, нескольких кусков толстой узловатой кожи и тотема защиты от демонов. Мастера-ремесленники смогут сделать рамку и кожу, но тотем можно достать только у Фантея, продавца реагентов в Нижнем городе Шаттрата – там же, где расположились и другие торговцы.', 'Принесите адамантитовую рамку, 4 куска толстой узловатой кожи и тотем защиты от демонов Дэвиду Уэйну в Приют Уэйна.', '<Кузнец забирает у вас материалы, одобрительно кивая.>$B$BОтлично, это подойдет. Но достать остальные необходимые материалы будет далеко не так просто.', 'Ну как? Удалось достать необходимые материалы?', NULL, NULL, 'Адамантитовая рамка', 'Толстая узловатая кожа', 'Тотем защиты от демонов', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10665, 'Новинка из Механара', 'Работа со слитками, что ты принес, требует высокой температуры – более высокой, чем может обеспечить обычная кузница.$B$BМне понадобится дополнительный источник тепла, но в Запределье не так уж много вещей, обладающих необходимой мощностью.$B$BВ Механаре в Крепости Бурь можно найти аккумуляторы маны, заряженные энергией с избытком. Найди такой аккумулятор возле механолорда Конденсарона и принеси его сюда.', 'Принесите избыточно заряженный аккумулятор маны Дэвиду Уэйну в Приют Уэйна.', 'Он даже более мощный, чем я ожидал! Его хватит, чтобы целую дюжину клинков отковать!', 'Удалось ли тебе стянуть аккумулятор маны в Механаре?', NULL, NULL, 'Избыточно заряженный аккумулятор маны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10666, 'Лексикон демоника', 'Чтобы восстановить чары на клинке, нужно произнести несколько заклинаний на языке демонов.$B$BБеда в том, что я ему не обучен. Но есть книга под названием \"Лексикон демоника\", где содержится большинство нужных слов. Ей владеет могущественный чернокнижник из Совета Теней.$B$BНайди великого мастера Ворпила, что скрывается в залах Темного лабиринта в Аукиндоне. Добудь эту книгу любыми средствами.', 'Добудьте книгу \"Лексикон демоника\" у великого мастера Ворпила и принесите его Дэвиду Уэйну в Приют Уэйна.', '*Давид дрожащими руками листает страницы книги* $B$BС этой штукой не стоит шутить, правда, $N? После того как твое оружие будет готово, я уничтожу ее. В мире и так достаточно демонской магии, чтобы еще и этой книгой мог воспользоваться любой желающий.', 'Ты принес книгу?', NULL, NULL, 'Лексикон демоника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10667, 'Суглинок из Нижнего мира', 'Форма, которую ты мне $gпринес:принесла: раньше, не способна выдержать расплавленный металл, ее нужно укрепить. Не каждый тип почвы способен охладить и укрепить форму, придавая адамантиту сверхъестественную крепость.$B$BСуглинок нижнего мира, так называется этот вид почвы, – в большом почете у наг. Но мало кто им обладает – а здесь, в Запределье, я знаю только одну такую нагу – гидромантку Теспию, обитающую в Паровом подземелье резервуара Кривого Клыка.', 'Достаньте фиал с суглинком Нижнего мира у гидромантки Теспии и принесите его Дэвиду Уэйну в приют Уэйна.', 'Это решит нашу проблему. Я надеялся, что ты принесешь больше, но – буду честен: нам категорически повезло, что мы и такое количество заполучили.', 'Ну и где суглинок?', NULL, NULL, 'Фиал с суглинком из Нижнего мира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10668, 'Против иллидари', 'Я все еще уважаю Иллидана. Без него я не нашел бы своего пути.$B$BНо он уже не тот, кем был. Его душу снедает жажда власти, его разум помрачился от поражения. Он стал тем, что я поклялся уничтожить. Его прихвостни, иллидари, такая же мерзость, как и демоны Пылающего Легиона.$B$BЗапределье выскальзывает из его хватки, но она еще крепка. Докажи, что ты не на его стороне, убив его лейтенанта Лотроса на аванпосте иллидари в долине Призрачной Луны.', 'Алтруис Страдалец просит вас убить Лотроса на аванпосте иллидари в долине Призрачной Луны.', 'Значит, ты не на стороне Иллидана. Ты на шаг приблизился к завоеванию моего доверия.', NULL, NULL, NULL, 'Лотрос убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10669, 'Вопреки всему', 'Некоторые демоны верны только себе. Но истинный враг демонов загоняет и убивает свою жертву несмотря на симпатии.$B$BДемон Кселет – перебежчик из Легиона – некогда почитался за бога у примитивных болотных созданий Зангартопи. Когда Дренор чуть не погиб, он погрузился в сон под водами озера Болотных Огоньков. Найди портал у озера и вонзи вот это копье в землю.$B$BКселет проснется – готовься убить его и доказать, что ты враг всем демонам!', 'Алтруис Страдалец хочет, чтобы вы взяли прочное серебряное копье и вонзили его на прогалине с порталом близ озера Болотных Огоньков, чтобы пробудить Кселета. Когда убьете демона, вернитесь к Алтруису.', 'Добрая работа, $N. Он еще помнил тот день, когда я пронзил его этим копьем? Как давно это было...', 'Ты вернулся. Кселет убит?', NULL, NULL, 'Кселет убито', 'Прочное серебряное копье (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10670, 'Слеза Матери-Земли', 'Зачаровывать меч нужно с использованием сильной призмы, например драгоценного камня. Но не так уж их много, таких, чтоб смогли выдержать такой магический заряд и не расколоться.$B$BТот, который нам нужен, называется Слеза Матери-Земли. Этот мощный артефакт находится у огров, которые его и создали, но у О\'мрогга Завоевателя, который и хранит этот камень множество врагов, особенно в Разрушенных залах цитадели Адского Пламени. Достань мне этот камень, $N.', 'Добудьте слезу Матери-Земли у О\'мрогга Завоевателя и принесите ее Дэвиду Уэйну в приют Уэйна.', '*Давид Вейн подносит камень к свету, любуясь им.*$B$BАбсолютно, безупречен, как раз то, что нам надо. Если бы в нем был какой-то изъян, то волшебство могло бы обернуться против владельца.', 'Удалось ли тебе вырвать камень из лап Омрогга?', NULL, NULL, 'Слеза Матери-Земли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10671, 'Не только фунт мяса', '$N, У меня есть для вас еще дело. Один из этих яйцеголовых хочет изучить злобных плотозверей, которых можно найти у лагеря Разаана, к северу от Островерхого гребня.$B$BБолее того, они хотят изучить мясо тамошних мясожоров.$B$B*Дина кривится от отвращения.*$B$BНо, конечно, сами-то они ручки пачкать не желают, им только надо мяса, напитанного энергией Астрала, у самих-то духу не хватает.$B$BПо мне, нечего им выкобениваться, но что тут поделаешь?', 'Добудьте 5 кусков мяса, напитанного энергией Астрала.', 'То, что надо. Ну. И воняет же, правда?$B$BНадеюсь, оно стоило твоих трудов... Я просто счастлива, что ты сделал это за меня!', 'Ну, где мой фунт мяса? Что, ты не понимаешь юмора?', NULL, NULL, 'Напитанное энергией Астрала мясо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10672, 'Честно говоря, это – бред!', 'Мы должны продолжать изучать этих существ.$B$BДалеко к востоку отсюда – около мощного потока лавы под руинами Баа\'ри, ты найдешь пульты управления чарами. Эти пульты были созданы гением по имени Гномус с единственной целью, – исследовать лаву с помощью механического скорпиона.$B$BОн давно потерял рассудок и теперь интересуется только едой, чем острее, тем лучше.$B$B<Тиорус весело на тебя смотрит.>$B$BЯ хочу, чтобы ты использовал эти пульты и пометил деметродонов в потоках лавы для их дальнейшего изучения.', 'Отправляйтесь к потокам лавы возле руин Баа\'ри и используйте пульт управления чарами, чтобы контролировать волшебного скорпиона. Переправьтесь на нем через лаву и пометьте 8 больших сквернопламенных деметродонов для ученого Тиоруса.', 'Слушай, сейчас не время тянуть. Я наблюдал за этими помеченными деметродонами и выяснил. Что все они подчиняются очень крупному, нет, ОГРОМНОМУ деметродону которого зовут Хребтоскверн Старший.', NULL, NULL, NULL, 'Помечено больших сквернопламенных деметродонов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10673, 'Хребтоскверн Старший', 'Гномус вызнал про гигантского деметродона и собирается им подзакусить! Он, вероятно, смог увидеть то же, что и я, глазами своего волшебного скорпиона. Мне некогда объяснять. Он совершенно свихнулся. И самое главное, что его сумасшествие грозит лишить нас огнеупорного обмундирования.$B$BВозвращайся к потокам лавы возле руин Баа\'ри и отыщи там Хребтоскверна Старшего. Убей его и принеси мне его шкуру.$B$BНе спорь со мной, $N, это ничего не изменит.', 'Убейте Хребтоскверна Старшего и принесите его шкуру ученому Тиорусу в деревню Призрачной Луны в одноименной долине.', 'Наконец-то! Наконец-то у меня будет универсальная защита от лавы! Конечно, я поделюсь и с тобой, $N. Ты заслужил.', 'Поспеши! Гномий аппетит ждать не будет.', NULL, NULL, 'Шкура Хребтоскверна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10674, 'Ловля фантастического света', 'Эфириалы – Разаани – экспериментировали с одной интересной технологией в лагере Разаана, что на севере отсюда.$B$BЯ уверен, что они не будут против, если вы поставите эту ловушку, чтобы поймать несколько образцов их розовых летучих световых шариков? Они все равно наверняка только для украшения.$B$BУ ловушки есть специальное свойство – когда она открыта, она она притягивает к себе эти летучие шарики. Конечно, это может всполошить астральных духов и привлечь их к вам.', 'Поймайте 15 световых сфер братства Разаани при помощи световой ловушки.', 'Эй! Да подожди ты минутку!!!$B$BЭто не смешно...', 'Как понимаю, после нашего разговора вы наловили световых шариков в лагере Разаана? Интересно будет посмотреть на них и понять, что на уме у духов Астрала.', NULL, NULL, 'Поймано световых сфер братства Разаани', 'Радужная световая ловушка (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10675, 'Попомните гномскую доброту!', '*От лица Тошли отливает кровь.*$B$BЭти шарики состоят из энергии Пустоты и из душ! И некоторые из этих душ - гномьи!$B$BКак они посмели! Значит, это они перебили наш народ, что ушел на север?!$B$B$N, необходимо немедленно покончить с этим, и единственный способ - прикончить их предводителя, принца Разаана.$B$BНо вам придется выманить его из укрытия. Думаю, это можно сделать, перебив побольше Разаани.$B$BПринесите мне его коллекцию душ - наверняка она у него есть!', 'Добудьте коллекцию душ. Награда: Гномские сапоги заклинателя, Шляпа героя станции Тошли, Поножи разбойника Разаани, Нагрудник спасителя душ, и Трансформатор.', 'Туда ему и дорога! Спасибо, что положили конец этому жуткому извращению магии и технологии.$B$BКак истинному герою всех гномов я ныне вручаю вам знак высочайшего нашего почтения... несколько преобразователей энергии – выбирайте любой!$B$BЯ знаю, что вы найдете им хорошее применение!', 'Вы еще не разделались с этим ублюдком, этим душекрадом Разааном?', NULL, NULL, 'Коллекция Душ', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10676, 'Проклятие иллидари', '$gДэвид берет компоненты для ковки.>$B$BТы неплохо $gпоработал:поработала: и $gдобыл:добыла: все, что нужно для изготовления клинка против демонов. Твой труд скоро будет вознагражден.$B$BПришло время отковать клинок!', 'Подождите, пока Дэвид Уэйн откует для вас клинок.', '<Дэвид утирает пот.>$B$BРабота почти закончена, но перед тем как зачаровывать клинок, его надо закалить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10677, 'Второе блюдо...', 'Видал я крупных деметродонов – восточнее Руки Гул\'дана, возле лавовых потоков, огибающих руины Баа\'ри. Чего я хочу, это чтобы ты $gдоставил:доставила: мне потроха крупного деметродона. Возможно, тебе придется убить нескольких, чтобы найти именно такого, как я тебе описывал. Ищи, пока не найдешь. Кто-то из них явно предназначен мне на трапезу!', 'Добудьте для Гномуса из цитадели Громового Молота в долине Призрачной Луны потроха крупного деметродона.', 'Все это конечно замечательно, но я только что получил ошеломляющие новости!', 'Блюдо дня: Потроха!', NULL, NULL, 'Потроха крупного деметродона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10678, 'Гвоздь программы', 'Короче говоря, работал я когда-то с одним эльфом крови по имени Тиорус. Наше сотрудничество закончилось, когда я решил все бросить и вести жизнь гурмана, а он продолжил все в одиночку, используя МОИ наработки! Во всяком случае, он через своих приспешников в Орде использовал образцы моих чародейских скорпионов в лавовых потоках на руинах Баа\'ри и нашел праматерь всех деметродонов.$B$BЯ хочу, чтобы ты $gдобрался:добралась: туда раньше него, $gубил:убила: там деметродона Хребтоскверна и $gпринес:принесла: его шкуру мне.$B$BПоторопись!', 'Принесите шкуру Хребтоскверна Гномусу в цитадель Громового Молота в долине Призрачной Луны.', 'Теперь мне нужно побыть одному, $N, спасибо за помощь!', 'Блюдо дня: Шкура Хребтоскверна.', NULL, NULL, 'Шкура Хребтоскверна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10679, 'Закалка Меча', 'Меч почти готов!$B$BМожно уже даже почувствовать, как магия начинает сливаться с его сталью в единое целое, но все еще осталось совершить один последний ритуал.$B$BТы $gдолжен:должна: взять откованный клинок с собой к Жгучим прудам, что возле подножия Руки Гул\'дана в долине Призрачной Луны и погрузить его в одно из озер лавы, чтобы закалить клинок. После этого возвращайся ко мне.', 'Отправляйтесь к Жгучим прудам возле подножия Руки Гул\'дана, и закалите кованый меч погибели иллидари в озерах лавы. После этого возвращайтесь к Дэвиду Уэйну в приют Уэйна.', 'Отлично!$B$B<Кузнец внимательно изучает меч.>$B$BЯ бы сказал, этот меч наконец-то уравновесит твои шансы против Легиона. Он уничтожает не только демонов Иллидари, но и прочих приспешников Легиона.', 'Ну как? Удалось тебе закалить меч в лавовых озерах возле Руки Гул\'дана?', NULL, NULL, 'Закаленный меч погибели Иллидари', 'Кованый меч погибели Иллидари', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10680, 'Рука Гул\'дана', 'Стихиям нужна твоя помощь, $r, – долина Призрачной Луны погрязла во зле. Духи стихий оставались в заключении до сего дня. Теперь многие из них разъярены и не желают сотрудничать со Служителями Земли.$B$BПомоги этому миру исцелиться, друг мой.$B$BК северо-востоку от цитадели Громового Молота простирается область, именуемая Алтарь Проклятия. Отправляйся туда и поговори с целителем земли Торлоком.', 'Поговорите с целителем земли Торлоком у Алтаря Проклятия в Долине Призрачной Луны.', 'Хорошо, что ты здесь, $R. Нам предстоит много работы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10681, 'Рука Гул\'дана', 'Стихиям нужна твоя помощь, $r, – долина Призрачной Луны погрязла во зле. Духи стихий оставались в заключении до сего дня. Теперь многие из них разъярены и не желают сотрудничать со Служителями Земли.$B$BПомоги этому миру исцелиться, друг мой.$B$BК юго-востоку от цитадели Громового Молота простирается область, именуемая Алтарь Проклятия. Отправляйся туда и поговори с целителем земли Торлоком.', 'Поговорите с целителем земли Торлоком у Алтаря Проклятия в Долине Призрачной Луны.', 'Хорошо, что ты здесь, $R. Нам предстоит много работы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10682, 'Время для переговоров...', 'Когда мы прибыли в чащобу Рууан, служители культа Змея уползли в пещеру Крыла Тьмы сквозь туннели на запад. Но теперь они нападают на нас.$B$BЯ хочу, чтобы ты $gнашел:нашла: инспектора служителей культа. Известно, что он регулярно патрулирует территорию между их лагерями в чащобе Рууан.$B$BПоговори с ним. Пусть знает, что мы готовы договариваться, но не допустим полного уничтожения диких животных и вырубки деревьев.', 'Переговорите с надзирателем Нуааром.', 'ЧТО?! Они сразу отмахнулись от наших предложений и прогнали тебя?$B$BЯ в бешенстве! Мы пришли к ним с добром, а они даже не хотят попытаться найти общий язык?$B$BНу-ну, они свое получат!', NULL, NULL, NULL, 'Поговорите с надзирателем Нуааром.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10683, 'Таблички Баа\'ри', 'Иллидан приказал сломленным из племени Пеплоустов провести раскопки в руинах Баа\'ри, далеко на севере. Они, несомненно, ищут реликвии дренеев. В Баа\'ри их было множество до того, как Гул\'дан похоронил город под лавовыми потоками. Мы должны использовать эту возможность вернуть таблички Баа\'ри, текст которых, по слухам, раскрывает секреты храма Карабор... известного сейчас как Черный храм.', 'Соберите для чародея Тэлиса из святилища Звезд 12 табличек Баа\'ри. Таблички могут быть где-то закопаны или находиться у Пеплоустов-рабочих.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Таблички Баа\'ри! Это же неоценимый источник информации!', 'Нашел ли ты таблички, $N?', NULL, NULL, 'Фрагмент таблички Баа\'ри', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10684, 'Старец Орону', 'Если верить этим табличкам, артефакт, известный как Медальон Карабора, хранился в Баа\'ри. Только дренеям высшего ранга могли предоставить допуск к таким медальонам, поскольку только им было разрешено войти в храм Карабор.$B$BМы должны узнать, вернули ли Пеплоусты медальон, который хранился в Баа\'ри. Его сила послужила бы неплохим подспорьем в нашей борьбе против Иллидана.$B$BЛейтенант Акамы в Баа\'ри, старец Орону, ежедневно получает от него письменные приказы. Раздобудь их и принеси мне.', 'Найдите в руинах Баа\'ри приказы Акамы, адресованные старцу Орону, и принесите их чародею Телису.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Почерк Акамы... Посмотрим, что он пишет', 'Как успехи, $N? Время сейчас играет против нас.', NULL, NULL, 'Распоряжения Акамы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10685, 'Осквернители из клана Пеплоустов', 'Если верить письму Акамы, 4 фрагмента медальона были им найдены и вручены осквернителям из племени Пеплоустов. Эти Сломленные когда-то были могущественными шаманами, но теперь они оскверняют те самые элементы, которым раньше поклонялись.$B$BХаалума – Осквернителя Воздуха можно найти на перевале Крыльев Пустоты. Айкенена и Уйлару, Осквернителей Земли и Огня, в последний раз видели в Ямах Скверны возле Руки Гул\'дана. Лакаан – Осквернитель Воды по слухам находится возле лагеря Змеиных Колец.$B$BНайди их и собери фрагменты медальона.', 'Соберите 4 фрагмента медальона у Хаалума, Айкенена, Уйлару, и Лакаана и вернитесь к чародею Тэлису в святилище Звезд.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Да! Все четыре фрагмента собраны. Теперь сложим их вместе...', 'Ты собрал все четыре фрагмента, $N?', NULL, NULL, 'Фрагмент медальона Айкенена', 'Фрагмент медальона Хаалума', 'Фрагмент медальона Лакаана', 'Фрагмент медальона Уйлару');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10686, 'Клеть Стражницы', 'Те фрагменты, что ты $gпринес:принесла:, – это лишь половина медальона. Другая, скорее всего, хранится у предводителя Пеплоустов, Акамы.$B$BМне страшно просить тебя об этом, поскольку Акама так же коварен, как и зол.$B$BОн и его Пеплоусты – Служители Смерти – самые подлые и жестокие в своем племени – судя по слухам, сейчас находятся в пыточной камере в Клети Стражницы.$B$BЯ хочу, чтобы ты $gпробрался:пробралась: в эту жуткую тюрьму и $gузнал:узнала: о местонахождении Акамы. Его первый помощник – сломленный по имени Санору, тебе придется расспросить его.', 'Отправляйтесь в Клеть Стражницы, к югу от руин Баа\'ри и расспросите Санору о местонахождении Акамы для чародея Телиса.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Мы ждали тебя, $N. Акама говорил, что рано или поздно ты появишься.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10687, 'Тренировочная площадка Карабора', 'Наши разведчики донесли о большом количестве эльфов крови – рекрутов Ярости Солнца, направляющихся к руинам Карабора. По правде сказать, похоже на вооруженную угрозу, но я полагаю, что мы не обо всем осведомлены.$B$BСудя по описаниям их униформы и стиля боя, похоже, что это подразделения Иллидана. Я не хочу тревожиться попусту, поэтому отправляйся туда и принеси мне их оружие – так мы проверим, насколько обоснованы мои страхи.', 'Отберите у соискателей и посвященных охотников на демонов, сосредоточенных в руинах Карабора, 8 глеф армии Ярости Солнца. Принесите их Лариссе Солнцесвет в святилище Звезд.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Давай-ка, взглянем поближе. $N. Хммм... Тревожный знак...', 'Ты выполнил то, о чем я тебя просила, $N?', NULL, NULL, 'Глефа Ярости Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10688, 'Необходимая уловка', 'Это то самое оружие, а значит, мы не зря опасались. Иллидан тренирует охотников на демонов в руинах Карабора, и мы должны положить этому конец.$B$BПускай тебя не обманывает их название, $N, их оружие обращалось против нас так же часто, как против демонов, которых их чародеи призывают, чтобы тренировать на них новичков.$B$BВластитель преисподней Азалот оказался слишком силен, чтобы использовать его на тренировочной площадке, и был пленен. Найди способ освободить его из заключения, пока они будут разбираться с Азалотом, мы выиграем необходимое время.', 'Вернитесь в Руины Карабора и освободите Азалота для Лариссы Солнцесвет.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Это даст нам немного времени, будем надеяться. Нам его хватит. Чтобы раздобыть необходимую информацию.', NULL, NULL, NULL, 'Азалот на свободе', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10689, 'Алтруис', 'Редко сейчас услышишь о тех, кто избирает стезю охотника на демонов. На них с подозрением смотрят даже близкие, ведь мало кто из них сейчас не связан с Иллиданом.$B$BХодят слухи об одном таком вольном охотнике. Его зовут Алтруис. Он ненавидит демонов всей душой и может быть поможет тебе, если ты сумеешь убедить его, что полностью разделяешь его убеждения.$B$BОтправляйся в западный Награнд и найди его. Возможно, он сумеет рассказать тебе что-то об этих тренировочных площадках.', 'Отправляйтесь в западный Награнд и найдите Алтруиса Страдальца.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Ты проделал долгий путь, странник. Удивительно, что тот, кто послал тебя, вообще обо мне слышал.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10690, 'Мать логова', 'РОЗЫСК!$B$BРазыскивается Рема, мать стаи и бывшая защитница Зазубренной гряды к югу от оплота Громоборцев.$B$BИщите ее к востоку от города за мостом через лощину Кровавого Молота. Она спряталась в туннеле на южном конце гряды.$B$BРапорт о ликвидации доставить командиру Тень Небес в Сильванаар.', 'Убейте Рему.', 'Невероятно. Вы сами убили Рему?$B$BСудя по вашему виду – можете. Понимаете, мы ищем молодого, крепкого $C, вроде вас, чтобы помочь нам разобраться с вечной проблемой огров. Давайте уж разберемся с ней окончательно, раз подвернулась возможность.$B$BЛадно, вы определенно заслужили ту награду, которую я назначил в том объявлении.$B$BПрошу, берите.', NULL, NULL, NULL, 'Рема убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10691, 'Возвращение к Провидцам', 'Эта книга... С ее помощью моя сила возросла бы десятикратно... Но нет! Вред, причиненный моей душе, был бы куда больше, я уверен. Возвращайся к тем, кто послал тебя, $N.$B$BТеперь у тебя есть средства остановить Варедиса. Дождись, пока он не покажет свою демоническую сущность в одном из перевоплощений, и в этот момент сожги перед ним эту книгу. Это единственный способ лишить его силы.', 'Поговорите с Лариссой Солнцесвет в святилище Звезд в долине Призрачной Луны.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Многие правую руку бы отдали за эту книгу. Жаль, что нам придется ее уничтожить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10692, 'Варедиса нужно остановить!', 'Мы должны уничтожить эту книгу, но не раньше, чем мы используем ее для того, чтобы победить Варедиса.$B$BЕсли мы хотим положить конец этой академии иллидановских приспешников, нам предстоит убить не только Варедиса, но и троих ночных эльфов – его помощников. Аландиен, Тераса и Нетариеля.$B$BСобери подходящий отряд и возвращайся в Руины Карабора. Следуй инструкциям Алтруиса, чтобы победить Варедиса, я искренне надеюсь, что они сработают. В любом случае, работать с тобой было для меня истинным удовольствием.', 'Отправляйтесь в Руины Карабора и убейте Аландиен, Тераса, Нетариеля и самого Варедиса. Используйте Книгу Имен Скверны, когда Варедис будет перевоплощаться, чтобы ослабить его. Вернитесь к Лариссе Солнцесвет с Книгой Имен Скверны по выполнении задания.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Браво, $N! Твоя победа над Варедисом очень важна для нашей войны с Иллиданом.$B$BТвое имя у нас запомнят надолго.$B$BПозволь мне забрать то, что осталось от Книги Имен Скверны. Я хочу удостовериться... Что от нее наконец-то избавятся.', 'Ты выполнил то, о чем я тебя просила, $N?', NULL, NULL, 'Варедис убито', 'Нетариель убито', 'Терас убито', 'Аландиен убито');
