INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10699, 'Один рекомендательный жетон', '', '', '', NULL, NULL, NULL, 'Рекомендательный жетон Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10700, 'Десять рекомендательных жетонов', '', '', '', NULL, NULL, NULL, 'Рекомендательный жетон Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10701, 'Низвергнуть Глыбня Пустоты', 'Всем, кто ждет своевременного сооружения ракеты Х-52!$B$BКороль местных горных великанов, Глыбень Пустоты, держит в страхе Гиблый пустырь. Он мешает нашим действиям по всему южному берегу острова!$B$BСобери своих друзей, чтобы справиться с ним. Затем возвращайся ко мне в Зону 52.$B$BВедущий ракетостроитель Фьюзеляж.', 'Убейте Глыбня Пустоты и сообщите об этом ведущему ракетостроителю Фьюзеляжу, находящемуся в Зоне 52 в Пустоверти.', 'Ого! Ого... тебе удалось справиться с Глыбнем Пустоты. Хорошая новость!$B$BТеперь, когда этот надоедливый горный великан больше не будет нам мешать, нам будет легче эксплуа... разумно использовать ресурсы Гиблого пустыря.$B$BРад слышать, что эти несчастные, ни в чем не повинные элементали могут теперь чувствовать себя в безопасности.$B$BЧем я могу тебе отплатить?', NULL, NULL, NULL, 'Глыбень Пустоты убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10702, 'Наряд вне очереди', 'Все силы Орды сейчас сплотились, дабы отражать атаки Легиона. Это значит, что у нас не хватает рук, чтобы выполнять подсобные работы.$B$BНашим караванам постоянно угрожает какая-то живность. Они пару метров не могут проехать по дороге, чтобы не наткнуться на химеру, скверносквина или скорпиона-переростка.$B$BОтправляйся туда и очисти Долину Призрачной Луны от чрезмерно агрессивной живности. Просто убей всех, кого сможешь.', 'Убейте 20 животных, водящихся в долине Призрачной Луны для воеводы Ор\'бароха.Тварями считаются скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым.', 'Блестяще! Когда нам снова понадобятся услуги чистильщика, я найду тебя.', NULL, NULL, NULL, 'Тварь Долины Призрачной Луны убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10703, 'Зачистка', 'Пришло время спускаться с небес на землю и слегка запачкаться. А чего ты $gждал:ждала:, а? Прежде чем начать ползать, придется сначала научиться ходить, как думаешь? Хм... разверни это!$B$BПо-любому, пришло время свистать всех наверх и разбираться с теми отбросами, которые посылает на нас Легион. А тебе придется взять на себя почетную обязанность почистить окружающее пространство от всяких диких тварей.$B$BБери меч, доспех, чего там тебе еще надо для полного счастья, отправляйся и убей всю живность, которая попадется на пути, чтобы наши караваны могли беспрепятственно продвигаться по долине.', 'Убейте 20 животных, водящихся в долине Призрачной Луны, для тана Йорегара из цитадели Громового Молота.Подойдут скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым.', 'Ха! Превосходно! Вот плата за твои труды, если нам потребуются еще чистильщики, мы с тобой свяжемся.', NULL, NULL, NULL, 'Тварь Долины Призрачной Луны убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10704, 'Как проникнуть в Аркатрац', 'В кристалле Ата\'мала, который ты $gпринес:принесла:, находилась записка. Принц нексуса Харамад передал очень важную информацию, которая непременно пригодится нам в борьбе с Крепостью Бурь.$B$BОн сообщил, что есть два обломка ключа, и если соединить их, то можно будет отпереть сектор Аркатрац.$B$BОдин из фрагментов находится у Узлодревня в Ботанике, а второй – у Паталеона Вычислителя в Механаре.$B$BПринеси мне оба фрагмента, и я соберу из них целый ключ Аркатраца.', 'Принесите А\'далу верхний и нижний обломок ключа Аркатраца, чтобы он собрал из них целый ключ.', 'Я впечатлен, $N, хотя именно этого и следовало ожидать от героя, который вернул нам кристалл ата\'мала.$B$BДай мне обломки, и я соединю их вместе. Тогда тебе будет открыт доступ в Аркатрац.', '<В вашей голове раздается мелодичный голос А\'дала.>$B$BТы вернулся. Принес ли ты два обломка ключа от Аркатраца?', NULL, NULL, 'Верхний обломок ключа Аркатраца', 'Нижний обломок ключа Аркатраца', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10705, 'Провидец Адало', 'Даже не знаю, как сказать тебе это, $N. Медальон Карабора, который тебе удалось добыть, – всего лишь копия.$B$B<На ладони Акамы лежит медальон, как две капли воды похожий на ваш.>$B$BМы со Служителями Смерти держали это в тайне от Иллидана. Однако в настоящем медальоне не хватает одной части.$B$BАдало явился мне во сне и сообщил, что нашел недостающую часть. К несчастью, Кель\'тас держит его в Аркатраце в Крепости Бурь.', 'Найдите провидца Адало в Аркатраце в Крепости Бурь.', 'Провидец Пеплоустов давно мертв. Перевернув его тело, вы замечаете письмена, нацарапанные на полу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10706, 'Таинственное знамение', 'Прежде чем умереть, Адало написал на полу возле себя единственное слово, надпись уже почти неразличима, но вам удается, разобрать слово \"Ата\'мал\".$B$BВозможно Акама разберется, что имел в виду его собрат.', 'Вернитесь к Акаме в Клеть Стражницы в долине Призрачной Луны.', 'Да... Конечно! Теперь все ясно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10707, 'Терраса Ата\'мала', 'Нам стало известно, что орки Скверны из отрядов Иллидана охраняют Кристалл Ата\'мала, именуемый Сердце Ярости, на террасе Ата\'мала. Они скрывают его от Ша\'тар с помощью темной магии.$B$BПробейся на террасу Ата\'мала, перед Черным храмом, и подними глаза к небу. Владыка теней Смертокрик будет кружить над террасой. Тебе нужно убить его и всех его чернокнижников, чтобы завладеть кристаллом.$B$BСделать это будет непросто, $N, удачи тебе!', 'Отправляйтесь на террасу Ата\'мала, в Долине Призрачной Луны и раздобудьте Сердце Ярости. По выполнении задания вернитесь к Акаме в Клеть Стражницы.', 'Теперь... Сила кристалла в моих руках!', 'Ты вернулся $N.', NULL, NULL, 'Сердце Ярости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10708, 'Обещание Акамы', '$gАкама вставляет кристалл в медальон, который держит в руке.>$B$BЯ уже не так силен как прежде, $N. Так тесно общаться со злом все эти годы, я не уверен, что у меня хватит сил совладать с таким могущественным артефактом.$B$BВозьми его как залог того, что когда ты встретишься лицом к лицу с Иллиданом, я буду на твоей стороне. Отнеси его тому, кому мы можем безоговорочно доверять, А\'далу в Шаттрат.', 'Принесите медальон Карабора А\'далу в Шаттрат.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10709, 'Воссоединение', 'Значит, ты из мира за порталом? И ты знаешь о Рексаре. Да, я хорошо с ним знаком.$B$BВидишь ли, это мой сын.$B$BНо он сделал свой выбор давным-давно. Он не с нами, и тут ему рады не будут. Нам хватает хлопот с кланом Кровавого Молота.$B$BЗапомни – если в тебе половина крови Мок\'Натала, от этого ты не становишься одним из Мок\'Наталов.', 'Поговорите с Рексаром в Оплоте Громоборцев в Острогорье.', 'Значит, мой отец жив. Я и не ждал, что он меня простит – не в его это духе. Но я надеялся, что с годами он перестанет гневаться на меня за мой уход. $B$BТридцать лет назад я покинул Мок\'Натал, чтобы присоединиться к Орде на Азероте. Леорокс был категорически против, но не мог привести ни одного веского аргумента, чтобы я остался... И все же я надеялся на лучший прием.$B$BОн хотел сына из Мок\'Наталов, и он у него есть, пусть даже он этого и не знает.$B$BЯ должен открыть ему глаза.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10710, 'Испытательный полет: Звенящий гребень', 'Я тут малость похимичил с Конденсаторием зефира и готов осуществить еще одно испытание! Не желаете ли помочь?$B$BЭтот полет будет коротким, но зато каким быстрым!$B$BГм... ну, я уверен, что опасности нет... и все же у меня тут есть один документик, вы уж подпишите. Это всего лишь формальность, честное слово!$B$BУдачи вам, самой большой удачи! Скажите Ралли, пусть он вас запустит, а после эксперимента приходите ко мне!', 'Подпишите отказ от претензий к Талли, затем поговорите с Ралли Быстроцапом насчет Конденсатория зефира.', 'Ох ты! Вы опять живы! Я куда лучший инженер, чем думал!$B$BВот ваши деньги! Свяжитесь со мной попозже... У меня в плане еще много экспериментов, так что подопытные герои мне еще понадобятся!', 'Не бойтесь, $N! Ракет бояться - в небо не летать!', NULL, NULL, 'Развейте все сомнения по ветру.', 'Отказ от претензий к Талли (неподписанный)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10711, 'Испытательный полет: лагерь Разаана', '$N, я повысил эффективность Конденсатория зефира на 30 процентов. А, значит, мне понадобится подопытный субъект вашего веса и более высокое аэродинамическое сопротивление! Хотите проверить мою теорию? Эксперимент потребует от вас полета в окрестности лагеря Разаана.$B$BПоговорите с Ралли... он подготовит вас к полету.', 'Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира.', 'Ох ты! Вы так быстро вернулись! Я видел – вы стартовали как ракета! Я думал, что вы после такого полета месяц переломы лечить будете! Вы парень не промах, вы смелы и безрассудны! Но прежде всего... Вы отважны!', NULL, NULL, NULL, 'Дотроньтесь до неба.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10712, 'Испытательный полет: чащоба Рууан', 'Эй, $N, хорошо, что я вас перехватил! У меня жутко важное дело!$B$BВот крутящийся флюгер Пустоты. Возьми его в полет для снятия показаний и доставь его моему кузену в чащобу Рууан.$B$BПоговори с Ралли и возьми в полет конденсаторий зефира. Во время полета крути этот флюгер!$B$BКогда приземлишься, отнеси его О\'Малли Цапнабберу.$B$BУдачи, $N. И не тяни!', 'Поговорите с Ралли Быстроцапом, чтобы узнать, как использовать Конденсаторий зефира. При полете в Чащобу Рууан крутите крутящийся флюгер Пустоты. Передайте крутящийся флюгер Пустоты О\'Малли Быстроцапу, который находится в Вечной Роще.', 'О, вы сняли данные с флюгера Пустоты? Замечательно! Данные, полученные с этого прибора – вместе с моими измерениями друидической магии – принесут великие плоды!$B$BО, применения моих открытий будут просто сногсшибательны, уж будьте уверены!', 'Привет-привет! Мой кло... то есть кузен Талли сказал, что вы заглянете. Вы что-то мне привезли?', NULL, NULL, 'Крутящийся флюгер Пустоты', 'Отправляйтесь в чащобу Рууан.', 'Флюгер Пустоты', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10713, '...и время действовать', 'Мы не станем сидеть сложа руки, пока они опустошают чащобу Рууан! Наш первый долг – защитить деревья.$B$B$C, я хочу, чтобы ты $gотправился:отправилась: в чащобу и $gпередал:передала: наше особое послание. Я хочу, чтобы ты $gубил:убила: всех их лесорубов, какие только тебе попадутся на пути!$B$BЕсли они не прислушаются к гласу рассудка, может, на них подействует более агрессивный метод убеждения!', 'Убейте 10 лесорубов Культа Змея.', 'Спасибо тебе, $N.$B$BМы проследим, чтобы природа побыстрее залечила нанесенные ей раны, но выращивание деревьев, особенно естественным путем, потребует куда больше времени.', NULL, NULL, NULL, 'Лесоруб Культа Змея убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10714, 'На крыльях Духа', 'Если огры из клана Кровавого Молота не дают покоя Мок\'Наталу, я остановлю их и их приспешников. Огры просты по натуре, и от преследования Мок\'Натала выгоды им мало.$B$BЗначит, тут другая причина. $N, возьми Духа, моего ястреба, и проследи за переговорами предводителей клана Кровавого Молота. Там, где нас заметят, на ястреба не обратят внимания.', 'Найдите занятых разговором ворожея и надсмотрщика из клана Кровавого Молота, затем при помощи свистка Рексара призовите Духа и проследите за ними.', '<Дух садится на плечо Рексара, пока тот внимательно слушает.>$B$BЗначит, действия огров направляют сыны Груула! Они натравливают огров из клана Кровавого Молота на Мок\'Натал, говоря, что так они заслужат их благосклонность!', 'Что тебе удалось узнать, $N?', NULL, NULL, 'Подслушайте планы огров из клана Кровавого Молота', 'Свисток Рексара (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10715, 'Прогулка в Беспокойную лощину', 'Значит, Рексар хочет, чтобы я приготовил ему яду? Что же, я исполню его просьбу, но не даром. Дармовщина разрушает дружбу.$B$BСначала тебе придется немного прогуляться на юго-запад, в Беспокойную лощину.$B$BТам обретаются самые ядовитые твари Запределья – да и не только Запределья. Я имею в виду землероев. А яд можно добыть из их ядовитых желез.', 'Добудьте 7 ядовитых желез землероев.', 'Очень хорошо. Простая, прямо-таки тупая часть задачи решена. Теперь давай мне железы, и я займусь самой трудной частью.', 'Ну как, добыл ядовитые железы? Если нет, то иди вон и не отнимай у меня времени, пока не сделаешь, как я велел.', NULL, NULL, 'Ядовитая железа землероя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10716, 'Test Flight: Raven\'s Wood $gneeds reward:', 'Конденсаторий зефира готов к самому долгому полету! Что скажешь, $N? Не хочешь ли еще разок полетать?$B$BЯ усовершенствовал двигательную систему, но пока я не отлажу все параметры, кондесаторию будет требоваться дополнительное топливо, чтобы получить нужный первоначальный импульс! Поговори перед вылетом с Ралли – он знает все детали.$B$BУдачи тебе, $N. Полет заведет тебя в далекий лес Ворона. Переживешь полет и унесешь ноги от лесных огров и араккоа – возвращайся, и мы отпразднуем успех!', 'Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира. Вернитесь к Талли Быстроцапу на станцию Тошли.', '', NULL, NULL, NULL, 'Отправьтесь в опасный полет.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10717, 'Вор у вора...', 'Прошу прощения, но я просто не могла не подслушать вашего разговора с Чауном. Я хотела бы вам помочь.$B$BЯ занималась изучением пещеры Крыла Тьмы и помогала друидам общаться с ее обитателями.$B$BЯ очень хотела бы заполучить несколько дракончиков – если мы будем знать, чему эти сектанты поклоняются, мы поймем, что они такое.$B$BНо сначала нам надо заполучить сети. Я заметила, что у браконьеров из культа Змея в чащобе Рууан их полно.', 'Добудьте 5 сетей Культа Змея.', 'О, замечательно. У этих служителей культа на хорошую работу глаз наметан.$B$BОчень жаль, что они выбрали не ту сторону.$B$BА теперь, когда у нас есть сети, не поможете ли вы старой больной женщине в одном дельце?', 'Как добыча сетей? Судя по тому, что я видела, сети у этих браконьеров достаточно крепкие, чтобы сгодиться для наших целей.', NULL, NULL, 'Сеть Культа Змея', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10718, 'У духов есть голоса', '$N, теперь, когда ты меня видишь, тебе будет что сказать Рексару. Я знаю, что он ищет свой народ, и я знаю, где он живет.$B$BМок\'Натал, как их называют, построили деревню на востоке за Островерхим гребнем.$B$BИди, передай Рексару эту весть. Его народ в опасности, и я знаю, что он бросится им на помощь.', 'Поговорите с Рексаром в Оплоте Громоборцев в Острогорье.', 'Ты о чем это?$B$BГарм Брат Волка? Он был последним вождем клана Громоборцев. Если ты говорил с его духом, тогда это правда!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10719, 'Где записка?', 'Эту записку доставил служитель культа. Похоже, ее надо доставить надзирателю Нуаару. Она подписана каким-то Колфисом Черной Чешуей.$B$BПохоже, это может заинтересовать хранителя деревьев Чауна.', 'Отдайте записку о встрече хранителю деревьев Чауну в Вечную рощу в Острогорье.', 'Интересно – но тревожно. Не знает ли Самия, кто такой этот Колфис Черная Чешуя?', 'Что это у нас тут? А это не пятно ли крови на записке?', NULL, NULL, 'Записка о встрече (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10720, 'Самые маленькие создания', 'Огры существа простые, но все же они заметят, что ты рассыпаешь яд по их лагерю. Я научу тебя, как в этом случае воспользоваться помощью самых маленьких творений природы.$B$BВыбив на этом барабане простейший ритм, ты приманишь сурка, и он будет выполнять твои приказы.$B$BРядом с лагерем клана Кровавого Молота на севере, у каньона Кинжальной Пасти, за Кругом Крови, в норах живут сурки.$B$BПримани сурков, пусть они подсыплют яда в бочки клана Кровавого Молота.', 'Ударьте в барабан из шкуры кодо возле норы сурка. Держа сурка под контролем, насыпьте яду в три бочонка в лагере Кровавого Молота.', 'Долгие годы я пытался усовершенствовать способы общения с природой. Это только малая часть еще нераскрытых возможностей творений природы, которые могут пойти на пользу тебе.', 'Дело сделано?', NULL, NULL, 'Отравите бочонок грога с зеленым пятном', 'Отравите бочонок выдержанного самогона', 'Отравите бочонок пивного сусла', 'Барабан из шкуры кодо (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10721, 'Подложим Груллоку свинью', '$N, есть у меня питомец-вепрь по имени Хаффер. Он хочет помочь тебе обдурить одного из тутошних сынков Груула.$B$BГруллок живет в местечке под названием Окаянная лощина. Как доберешься дотуда, выпусти Хаффера. Гронн начнет его гонять его по округе, а ты потихоньку стяни его мешок и отнеси его барону Черногриву.$B$BЧтобы добраться до Окаянной лощины, иди вниз по северному склону и на восток через Драконью Пагубу. Лощина на его восточной окраине.', 'Добудьте мешок Груллока.', '<Барон Черногрив с довольным видом заглядывает в мешок гронна.>$B$BОчень хорошо, ты свою часть уговора выполнил. Ну, раз уплачено, я дам Рексару то, что он ищет.', 'Так быстро? Ты пришел вернуть мне должок Рексара?', NULL, NULL, 'Мешок Груллока', 'Свисток Хаффера', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10722, 'Встреча в пещере Крыла Тьмы', 'Это необходимо сделать! $N, ты $gобязан:обязана: выдать себя за надзирателя Нуаара и побывать на этой встрече!$B$BСлужители культа Змея в ковене носят стандартное облачение, так что просто собери детали их одежды, и когда у тебя будет их достаточно, надень их.$B$BВыдай себя за инспектора Нуаара и поговори с Колфисом Черной Чешуей, чтобы узнать, что он скажет, а потом возвращайся к хранителю деревьев Чауну.$B$BКовен ты найдешь за туннелем Драконьего черепа, если пойдешь по тропе мимо леса Ворона и Гришната до конца.', 'Соберите костюм инспектора из деталей одежды, собранных у различных адептов Культа Змея. Отправьтесь в этом костюме на встречу с Колфисом Черной Чешуей.', 'Напасть на нас? Стереть нас с лица земли? Не выйдет!$B$BЭтим сектантам из пещеры Крыла Тьмы придется усвоить, что Кенарийская экспедиция им не по зубам!$B$BКак там говорят? Не рой другому яму!', NULL, NULL, NULL, 'Встретьтесь с Колфисом Черной Чешуей.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10723, 'Горгром Драконоед', 'Гронн, который нам нужен, это Горгром Драконоед. С помощью ловушки Черногрива тебе будет легко поймать его. Ты найдешь его там, где он принимает жертвоприношения от огров из Камен\'мока.$B$BИди по дороге на север от Круга Крови, затем сверни на запад у чащобы Рууан. Потом иди на северо-запад по туннелям.$B$BСначала просто посшибай ограм головы. Мы оставим им весточку – поставь ловушку на алтаре, а когда убьешь гронна, поставь возле него тотемы гризли – это они поймут.$B$BБери медведя.$B$B<Миша рычит.:', 'Добудьте 3 тотема гризли у огров Камен\'мока. Поставьте ловушку Черногрива на алтарь Горгрома, затем призовите и убейте Горгрома Драконоеда.Когда Горгром будет убит, поставьте 3 тотема гризли возле его туши.', 'Огры из клана Кровавого Молота и их хозяин Горгром теперь не будут угрожать Мок\'Наталу.$B$BИ все же я неспокоен, когда размышляю о влиянии наших действий на других гроннов. Сдается мне, надо покончить с этой войной раз и навсегда.', 'Когда дело будет сделано, клан Кровавого Молота больше нас не потревожит.', NULL, NULL, 'Установлено тотемов гризли', 'Ловушка Черногрива (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10724, 'Пленник Камнерогов', 'Вскоре после того, как я прибыл в эти горы, на меня напала шайка огров из клана Камнерогов.$B$BХотя я отбился от них и многих убил, они захватили мою виверну, Леокк. Дух нашел ее – она в клетке в самом центре лагеря Камнерогов близ логова Груула.$B$BУ одного из огров должен быть ключ от клетки. Найди его, и Дух сумеет открыть клетку Леокк.$B$BЛагерь расположен у северного края каньона Кинжальной Пасти.', 'Убивайте огров Камнерогов, пока не добудете ключ от клетки виверны. Как только добудете его, идите к клетке виверны и подуйте в свисток Духов чтобы призвать Духа, который отопрет клетку Леокка.', 'Леокк принесла нам голову одного из черных драконов Драконьей Пагубы. Этой головой мы раздразним Гока, гронна, который поймал его, и выманим его на битву.', 'Славно, что Леокк будет снова помогать мне.', NULL, NULL, 'Спасите Леокк', 'Свисток духов (Прилагается)', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10725, 'Аметистовое Око в восхищении', 'Твои достижения на службе Аметистовому Оку превзошли все наши ожидания, $N. Ты всего лишь на шаг отстоишь от самых высоких почестей, оказываемых в Даларане чужестранцам. $B$BПродолжай служить нам верой и правдой, и я увеличу мощь твоего перстня до предела.', 'Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока.', 'Теперь твой перстень сравнялся по силе с перстнем любого из верховных магов Совета. Носи его, не снимая. По нему посвященный признает, чьим союзником ты являешься. И пусть его сила послужит тебе добром, так же, как ты служил нам!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10726, 'Аметистовое Око в восхищении', 'Твои достижения на службе Аметистовому Оку превзошли все наши ожидания, $N. Ты всего лишь на шаг отстоишь от самых высоких почестей, оказываемых в Даларане чужестранцам. $B$BПродолжай служить нам верой и правдой, и я увеличу мощь твоего перстня до предела.', 'Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока.', '', NULL, NULL, NULL, 'Аметистовый перстень (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10727, 'Аметистовое Око в восхищении', 'Твои достижения на службе Аметистовому Оку превзошли все наши ожидания, $N. Ты всего лишь на шаг отстоишь от самых высоких почестей, оказываемых в Даларане чужестранцам. $B$BПродолжай служить нам верой и правдой, и я увеличу мощь твоего перстня до предела.', 'Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока.', 'Теперь твой перстень сравнялся по силе с перстнем любого из верховных магов Совета. Носи его, не снимая. По нему посвященный признает, чьим союзником ты являешься. И пусть его сила послужит тебе добром, так же, как ты служил нам!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10728, 'Аметистовое Око в восхищении', 'Твои достижения на службе Аметистовому Оку превзошли все наши ожидания, $N. Ты всего лишь на шаг отстоишь от самых высоких почестей, оказываемых в Даларане чужестранцам. $B$BПродолжай служить нам верой и правдой, и я увеличу мощь твоего перстня до предела.', 'Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока.', 'Теперь твой перстень сравнялся по силе с перстнем любого из верховных магов Совета. Носи его, не снимая. По нему посвященный признает, чьим союзником ты являешься. И пусть его сила послужит тебе добром, так же, как ты служил нам!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10729, 'Маг из Аметистового Ока', '', '', 'Ты уверен в своем решении, $N? Тебе предстоит сделать очень непростой выбор.Сила перстня Аметистового Ока станет возрастать по мере того, как ты будешь доказывать нам свою преданность.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
