INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10733, 'Путь Аметистового Ока', 'Ты $gвыбрал:выбрала: свой путь, $C. Следуй же ему, куда бы он тебя ни привел.$B$BЕсть свои преимущества в том, чтобы иметь друзей среди верховных магов Даларана. Если будешь служить нам верой и правдой, мы щедро наградим тебя.', 'Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум уважительное отношение Аметистового Ока.', 'Твоя служба делает честь всем нам, $N. Смотри же, как твое кольцо становится еще более могущественным!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
