INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10737, 'Разрешение учителя', 'Я сумел воссоздать ключ, которым пользовался, будучи учеником. Выглядит он полностью рабочим - насколько это возможно для ключа. Но Каражан им отпереть не проще, чем обычным куском металлолома. $B$BБез согласия Медива любой ключ будет всего лишь никчемной железкой. Да, я знаю, что Медив мертв. Но это всего лишь усложняет ситуацию, а не делает ее неразрешимой. $B$BВ Азероте есть место, называемое Пещерами Времени. Их охраняют Бронзовые драконы. Проберись внутрь, вернись в прошлое и уговори Медива дать мне возможность пользоваться этим ключом.', 'Отправляйтесь в Пещеры Времени и уговорите Медива разрешить пользоваться восстановленным ключом ученика.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10738, 'Выдающиеся заслуги', 'Ты не $gразочаровал:разочаровала: нас, $N. Мы продолжаем возлагать на тебя самые большие надежды. $B$BПродолжай служить Аметистовому Оку, и тебя ждет достойное вознаграждение.', 'Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум почтительное отношение Аметистового Ока.', 'Твое служение не осталось незамеченным, $N. Этот перстень внешне не изменяется, но сила его возрастает по мере того, как ты доказываешь нам свою преданность.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10739, 'Выдающиеся заслуги', 'Ты не $gразочаровал:разочаровала: нас, $N. Мы продолжаем возлагать на тебя самые наилучшие надежды. $B$BПродолжай служить Аметистовому Оку, и тебя ждет достойное вознаграждение.', 'Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум почтительное отношение Аметистового Ока.', '', NULL, NULL, NULL, 'Аметистовый перстень (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10740, 'Выдающиеся заслуги', 'Ты не $gразочаровал:разочаровала: нас, $N. Мы продолжаем возлагать на тебя самые наилучшие надежды. $B$BПродолжай служить Аметистовому Оку, и тебя ждет достойное вознаграждение.', 'Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум почтительное отношение Аметистового Ока.', 'Твое служение не осталось незамеченным, $N. Этот перстень внешне не изменяется, но сила его возрастает по мере того, как ты доказываешь нам свою преданность.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10741, 'Выдающиеся заслуги', 'Ты не $gразочаровал:разочаровала: нас, $N. Мы продолжаем возлагать на тебя самые наилучшие надежды. $B$BПродолжай служить Аметистовому Оку, и тебя ждет достойное вознаграждение.', 'Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум почтительное отношение Аметистового Ока.', 'Твое служение не осталось незамеченным, $N. Этот перстень внешне не изменяется, но сила его возрастает по мере того, как ты доказываешь нам свою преданность.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10742, 'Перед выстрелом', 'Вот и дождались. Мы выгоним Гока из его логова и уничтожим его. Когда Гок сдохнет, огры из клана Камнерогов больше не будут угрожать Мок\'Наталу. Отправляйся к алтарю Гока у логова Груула и протруби в мой рог. И я приду – мы вместе сразимся с отродьем Груула.', 'Протрубите в боевой рог Рексара у алтаря Гока, затем убейте Гока.', 'Тяжела была битва, и ты славно сражался, $N. Для меня честью было биться плечом к плечу с тобой против Гока. Не знаю, как и благодарить тебя.$B$BМок\'Натал должен узнать об этих великих свершениях, но я еще не готов предстать пред жителями деревни. Я знаю своего отца и знаю себя. Мне еще слишком многому предстоит научиться и стать сильнее, прежде, чем я сумею показать ему, что я его истинный сын.', 'Только смерть Гока и Горгрома Драконоеда освободит Мок\'Натал!', NULL, NULL, 'Гок убито', 'Боевой рог Рексара (Прилагается)', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10744, 'Вести о Победе', 'Вы должны немедленно известить о нашем успехе Курдрана Громового Молота! Его солдаты под командой командира звена Нуаинна сражались без устали, чтобы удержать цитадель Громового Молота, и ваше возвращение, конечно, их обрадует. Теперь, когда угрозы от легиона больше не существует, Курдран может, наконец, начать разбираться с войсками Иллидана. Здесь у нас не то, чтобы совсем безопасно, но сегодня мы выиграли переломное сражение.', 'Вернитесь в цитадель Громового Молота и поговорите с Курдраном Громовым Молотом.', '<Курдран слушает ваш рапорт.>$B$BЭто очень хорошая новость! Несколько дней назад, я и мечтать не мог, что мы сможем снять осаду Легиона с крепости.$B$BПусть не только вы остановили их наступление, но вы разрушили их военные машины! Клан Громового Молота благодарит вас за вашу храбрость, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10745, 'Вести о Победе', 'Немедленно извести о нашем успехе воеводу Ор\'бароха! Теперь, когда мы сокрушили Легион и стерли даже следы его присутствия в долине Призрачной Луны, воевода может, наконец, обратить внимание на других врагов. Хотя Кор\'кронская стража никогда в этом не признается, они будут рады, что мы больше не воюем на два фронта.', 'Возвращайтесь в деревню Призрачной Луны и поговорите с воеводой Ор\'барохом.', '<Воевода слушает ваш рапорт.> $B$BОтличные новости! Оборона от инферналов Легиона стоила нам уйму сил и ресурсов. Не то, чтобы я думал, что мои солдаты не справятся, но они уже были на грани изнеможения.$B$BТы доказал сегодня свою верность Орде. Кор\'кронская стража почтет за честь сражаться рядом с тобой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10747, 'Дракончики Культа Змея', 'Я должна исследовать тех отродий, что выращиваются в пещере Крыла Тьмы.$B$BИх должно быть полным полно в пещерах, где находится их база, а еще там должно быть много яиц, которые наверняка проклюнутся, как только ты к ним подойдешь.$B$BПрошу тебя, $N, возьми сеть и поймай мне пяток-другой, только живыми.$B$BИщи их на западе за мостом Драконьего Черепа, а затем иди по туннелю Драконьего Черепа. Иди до самого конца мимо Гришната и леса Ворона.', 'Поймайте 10 черных дракончиков Культа Змея при помощи сети.', 'О, невероятно, здесь даже больше, чем я надеялась! Вы определенно достойны похвал за свой героизм!$B$BОтличный выводок черных дракончиков. Как раз то, что нужно для начала. Начну исследования.$B$BПрошу примите это в награду. Я настаиваю!', 'У вас не возникло сложностей при ловле дракончиков? Надеюсь, вы не обожглись!', NULL, NULL, 'Темный дракончик Культа Змея', 'Сеть для ловли черных дракончиков (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10748, 'Да сгинет Макснар!', 'Они не оставили нам выбора, $N. Пора покончить с угрозой, исходящей от пещеры Крыла Тьмы – надо уничтожить их предводителя, Макснара Бледную Пасть.$B$BНе знаю, довелось ли тебе видеть его хоть мельком, пока ты там $gбыл:была:, но он один из драконьей породы – полудракон-получеловек. Он крепкий орешек, так что не недооценивай его! $B$BПрикончи его побыстрее, и если повезет, то ты освободишь от угрозы Вечную рощу и чащобу Рууан.', 'Убейте Макснара Бледную Пасть.', 'Теперь, когда мы знаем, что глава наших врагов убит, мы вздохнем свободнее. Но ты спас целую горную гряду от их злобы. $B$BЧто бы они ни задумывали, ты разрушил их планы!$B$BПрими нашу благодарность, $N. И прими это в знак нашей признательности, как и наше бесконечное гостеприимство.', NULL, NULL, NULL, 'Макснар Бледная Пасть убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10749, 'Яд барона Черногрива', 'Вот, отнеси своему хозяину. Уверен, что Рексар употребит его по делу.$B$BО, не забудь ему напомнить, что он мне должен.$B$BОн знает, чего я хочу, и поскольку он намерен добыть это для меня, то мы с тобой встретимся быстрее, чем ты думаешь.$B$BА теперь будь $gхорошим мальчиком:хорошей девочкой: – бегом к Рексару!', 'Доставьте яд барона Черногрива Рексару в оплот Громоборцев в Острогорье.', 'Грязное это дело – ядами травить. Но я сделаю, как он хочет.', '$c, ты так быстро вернулся? Яд при тебе?', NULL, NULL, 'Яд барона Черногрива (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10750, 'Путь Завоевания', 'От моих воздушных всадников пришли сведения, $N. Эльфы крови из лагеря Затмения затевают что-то крупное. Они начали сосредотачивать свои силы на Пути Завоевания, далеко на юго-востоке отсюда возле лагеря Затмения.$B$BЯ хочу, чтобы ты $gотправился туда и разобрался:отправилась туда и разобралась:, что они затевают. Когда закончишь, используй сигнальное ружье, чтобы подать сигнал воздушному всаднику. Передай ему все, что тебе удастся узнать и получи от него следующий приказ.', 'Отправляйтесь по Пути Завоевания в Долине Призрачной Луны.', 'Несомненно эти сволочи что-то замышляют. Нужно продолжать наблюдение.', 'Докладывай, солдат!', NULL, NULL, 'Исследовать локацию', 'Путь Завоевания обнаружен', 'Рекомендуемое количество игроков: 3', 'Кор\'кронское сигнальное ружье');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10751, 'Перерезанный путь', 'Нам нужно больше времени, $r. Я собираюсь лететь вперед с другими всадниками. Хотелось бы надеяться, что мы сможем раздобыть еще немного информации. Что мне нужно от тебя, это очистить нам путь и, что самое главное, удержать их стрелков подальше от нас!$B$BВызови одного из всадников на ветрокрылах с помощью кор\'кронского сигнального ружья, когда ты подсчитаешь точное их число.', 'Убейте 20 солдат, 10 кавалеристов и 10 чароплетов лагеря Затмения.', 'Ты не поверишь, приятель!', NULL, NULL, NULL, 'Солдат лагеря Затмения убито', 'Кавалерист лагеря Затмения убито', 'Чароплет лагеря Затмения убито', 'Рекомендуемое количество игроков: 3');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10752, 'Вперед, в Ясеневый лес', 'Недавно Раэна Волкопас проходила из Дарнаса через Аубердин, направляясь в Ясеневый лес. Она говорила что-то о фурболгах. Мне не удалось расспросить ее поподробнее, но, возможно, ты сумеешь ее найти и предложить ей помощь, $C. Иди из Аубердина по южной дороге. Как только доберешься до границы Ясеневого леса, продолжай идти по дороге. Там ты найдешь Астранаар и Раэну Волкопаса.', 'Поговорите с Раэной Волкопас в Астранааре.', 'Значит, Тандрис Ветропряд все еще считает, что мне нужна нянька? Надо бы ему напомнить, кто кого спасал - похоже, он забыл, что это я вытащила его из беды.$B$BНо хорошо, что ты сейчас здесь, $С, возможно, я найду для тебя дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10753, 'Зачистка пустоши', 'Неисчислимы злодеяния Пылающего легиона. Даже сейчас, пока мы говорим, они посылают свои полчища против здешних животных. Беспомощные перед ними, они гибнут одно за другим. $N, помоги мне прекратить эти преступления против природы, которую они поражают порчей! $B$BНа востоке отсюда, за холмом, ты увидишь, как порча расползается по лощине Клинков. Убей тех, кто совершил это злодеяние, осквернителей - а заодно и Скверноподданных, сколько получится.', 'Убейте 4 скверноподданных чешуекрылых змеев, 4 скверноподданных из каньона Кинжальной Пасти и 2 осквернителей.', 'Нет во мне радости, ибо мы убиваем сотворенных Элуной, но распространение порчи надо остановить. Ты сделал благое дело, $C.', NULL, NULL, NULL, 'Скверноподданный чешуекрылый змей убито', 'Скверноподданный из каньона Кинжальной Пасти убито', 'Осквернитель убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10754, 'Вход в цитадель', 'В этой форме только что отливали какой-то ключ. По клейму понятно, что она из цитадели Адского Пламени.$B$BВозможно, это заинтересует Даната, командира армии Оплота Чести.', 'Принесите форму для отливки ключа командиру армии Данату в Оплот Чести на полуострове Адского Пламени.', 'Не может быть! Дай-ка мне поближе взглянуть на эту форму.', 'У тебя что-то для меня есть, $N?', NULL, NULL, 'Форма для отливки ключа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10755, 'Вход в цитадель', 'В этой форме только что отливали какой-то ключ. По клейму понятно, что она из цитадели Адского Пламени.$B$BВозможно, это заинтересует Назгрела, командира сил Орды в Траллмаре.', 'Принесите форму для отливки ключа Назгрелу в Траллмар на полуострове Адского Пламени.', 'Форма для ключа? Может быть, с ее помощью мы попадем в Разрушенные залы?', 'У тебя что-то есть для меня, $N?', NULL, NULL, 'Форма для отливки ключа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10756, 'Великий мастер Рохок', 'Символ на рукояти этого ключа... Внутри формы его разглядеть трудно, но я узнаю его... Это знак клана Изувеченной Длани.$B$BЕсть шанс, что с его помощью ты сможешь проникнуть в Разрушенные залы.$B$BПоговори с Рохоком, это наш кузнец. Если кто-нибудь и сможет изготовить этот ключ, так это он.', 'Принесите форму для отливки ключа Рохоку в Траллмар, что на Полуострове Адского Пламени.', 'Назгрел хочет, чтобы я изготовил какой-то ключ? Он забыл, что у нас сейчас война? Мы должны ковать мечи и копья!', 'Что это?', NULL, NULL, 'Форма для отливки ключа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10757, 'Просьба Рохока', 'Возможно, кузнецы орков Скверны не самые искусные в мире, но у них есть чему поучиться. Для этой формы подойдет только оскверненное железо, если мы хотим получить рабочий ключ. Все остальное его только испортит.$B$BПринеси мне несколько слитков оскверненного железа, немного чародейской пыли и частицу огня. Я постараюсь сделать все, что смогу, но ничего не хочу обещать.', 'Принесите Рохоку 4 слитка оскверненного железа, 2 горсти чародейской пыли и 4 частицы огня в Траллмар на полуострове Адского Пламени.', 'Отлично. Посмотрим, как это сработает.', 'Ты достал все, что мне нужно?', NULL, NULL, 'Слиток оскверненного железа', 'Чародейская пыль', 'Частица огня', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10758, 'Жарче, чем в пекле', 'Вот незадача, $N! Сколько бы я ни кидал в топку угля, жара все равно не хватает.$B$BЯ думаю, есть только одна сила, которая могла бы поддержать температуру, достаточную для выплавки этого ключа, и она находится в легионовских скверноботах.$B$BКогда-то я видел, как повергли одного сквернобота. Помню, он весь задымился, начал изрыгать пламя и окутался облаками пара. Возьми эту форму и сунь ее в нутро поверженного сквернобота. Я бы рекомендовал тебе позвать на помощь друзей, если надумаешь за ним отправиться.', 'Уничтожьте сквернобота на полуострове Адского Пламени и погрузите внутрь него необожженную форму для отливки ключа. Принесите обожженную форму для отливки ключа Рохоку в Траллмар.', 'О, у тебя получилось! Теперь все, что тебе осталось – опробовать этот ключ.', 'Ну как, сделал то, что я тебе посоветовал?', NULL, NULL, 'Обожженная форма для отливки ключа', 'Необожженная форма для отливки ключа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10759, 'Найти дезертира', 'Я чувствую, что мы собрали все части головоломки, но порядок, в котором надо их сложить, чтобы получить хоть какой-то смысл, от меня ускользает.$B$BДумаю, нам стоит попытаться найти этого дезертира. Если он оставил своих товарищей, есть шанс убедить его помочь нам понять, что планирует темный конклав араккоа.$B$BНачни его поиски по дороге к Магмовым полям к северо-западу отсюда. Скорее всего, он попытается найти убежище именно там.', 'Найдите Паршаха в Магмовых полях и поговорите с ним.', '<Араккоа кудахчет.>$B$BДа, я тот самый дезертир, о котором писал командир. Я долго ждал того дня, когда другие поймут угрозу, исходящую от тех, кого я когда-то называл братьями.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10760, 'Развалины Скет\'лона', 'Развалины Скет\'лона к востоку отсюда – жуткое место. Батраки считают, что оно проклято.$B$BДеревьев тут мало, и батракам, хочешь не хочешь, приходится валить лес в руинах араккоа. Духи этих тварей охотятся на лесорубов. Высасывают из них все соки и используют их как пищу для своих проклятых чар.$B$BМы должны выяснить, что затеял темный конклав, и остановить их, прежде чем они наберут силу. Иди на развалины Скет\'лона и выясни замыслы конклава.', 'Добудьте у темного конклава араккоа и принесите сержанту Каргулу в деревню Призрачной Луны первую, вторую и третью страницы дневника командира Скет\'лона.', '<Сержант изучает страницы.>$B$BНе вижу здесь ничего такого уж полезного, однако есть пара записей, которые можно использовать. Тут написано, что до самой своей гибели араккоа готовились к какому-то сложному ритуалу, но больше про этот ритуал ничего не известно. И еще тут есть любопытная запись о каком-то дезертире...', 'Что ты узнал?', NULL, NULL, 'Записи командира Скет\'лона, стр. 1', 'Записи командира Скет\'лона, стр. 2', 'Записи командира Скет\'лона, стр. 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10761, 'Найти дезертира', 'Вряд ли кто-нибудь нам тут объяснит, почему души этих араккоа задержались в нашем мире или зачем им нужна кровь орков.$B$BДумаю, нам стоит попытаться найти этого дезертира. Если он оставил своих товарищей, есть шанс убедить его помочь нам понять, что планирует темный конклав араккоа.$B$BНачни поиски его по дороге к Магмовым полям к юго-востоку отсюда. Скорее всего, он попытается найти убежище именно там.', 'Найдите Паршаха в Магмовых полях и поговорите с ним.', '<Араккоа кудахчет.>$B$BДа, я тот самый дезертир, о котором писал командир. Я долго ждал того дня, когда другие поймут угрозу, исходящую от тех, кого я когда-то называл братьями.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10762, 'Великий Мастер Болтуй', 'Символ на рукояти этого ключа... По очертаниям в форме трудно разглядеть, но я узнаю его... Это знак клана Изувеченной Длани.$B$BЕсть шанс, что с его помощью ты сможешь проникнуть в Разрушенные залы.$B$BПоговори с Болтуем. Он великий мастер своего дела. Если кто-нибудь и сможет отковать этот ключ, так это он.', 'Принесите форму для отливки ключа Болтую в Оплот Чести.', 'Какой такой ключ? Данат что, забыл, – нам надо работать над осадными орудиями!', 'Что это?', NULL, NULL, 'Форма для отливки ключа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10763, 'Просьба Болтуя', 'Орки Скверны – полные дикари, но их кузнечное искусство отнюдь не так примитивно, как можно подумать. Для этой формы подойдет только оскверненное железо, если мы хотим получить рабочий ключ. Все остальное только его испортит.$B$BПринеси мне несколько слитков оскверненного железа, немного чародейской пыли и несколько частиц огня. Я постараюсь сделать все, что смогу, но ничего не обещаю.', 'Принесите Болтую 4 слитка оскверненного железа, 2 горсти чародейской пыли и 4 частицы огня в Оплот Чести на полуострове Адского Пламени.', 'Ну, давай попробуем. Посмотрим, на что годится кузнечное дело орков Скверны.', 'Ты достал все, что мне нужно?', NULL, NULL, 'Слиток оскверненного железа', 'Чародейская пыль', 'Частица огня', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10764, 'Жарче, чем в пекле', 'Ничего не выходит, $gприятель:подруга:, что бы я не делал, мне не достает жара.$B$BЗнаешь, в скверноботах жар поддерживается огнем Скверны, и он гораздо мощнее, чем обычный.$B$BЕсли соберешь достаточно народа, чтобы уничтожить какого-нибудь сквернобота, то сможешь закалить форму для ключа внутри него. Но будь $gосторожен:осторожна:, этот сквернобот сам кого хочешь уничтожит.', 'Уничтожьте сквернобота на полуострове Адского Пламени и закалите на его остатках необожженную форму для отливки ключа. Принесите обожженную форму для отливки ключа Болтую в Оплот Чести.', 'О, приятель, у тебя получилось! Единственное, что теперь осталось – отправиться с этим ключом в цитадель Адского Пламени и прикончить побольше орков!', 'Ну как, сделал то, что я тебе посоветовал?', NULL, NULL, 'Обожженная форма для отливки ключа', 'Необожженная форма для отливки ключа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10765, 'Война Миров', 'На южном конце Пути Завоевания, возле каравана, вставшего лагерем, мне удалось заметить великана и эльфийку крови в одеждах Советника, которые вроде бы организовали там встречу. Ты наверняка также $gзаметил:заметила: менее крупных гигантов на пути. Что-то в этом мире крупно не так, боец.$B$BЯ хочу, чтобы ты $gпроник:проникла: на такую встречу и $gиспортил:испортила: им праздник. Разузнай все, что можешь, а потом позови кого-нибудь из нас с помощью светового ружья.', 'Убейте канцлера Кровавую Листву и Корока Могучего и добудьте приказ Иллидана.', 'Так они собираются искать милости великанов? У меня есть план, как разрушить этот отвратительный союз.', 'Докладывай, солдат!', NULL, NULL, 'Канцлер Кровавая Листва убито', 'Корок Могучий убито', 'Приказ Иллидана', 'Рекомендуемое количество игроков: 3');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10766, 'Точка вторжения: Катаклизм', 'Теперь, когда у нас есть доступ к базе Легиона в точке вторжения: Катаклизм, нужно придумать способ положить конец их действиям. Цитадель Громового Молота не может спать спокойно, пока даже следы присутствия Легиона в этой местности не стерты с лица земли.$B$BЯ послал туда передовой отряд, чтобы помочь тебе уничтожить их припасы. Возвращайся в форт Легиона и воспользуйся телепортом, отмеченным зелеными кристаллами. Плекси встретит тебя на месте.', 'Доложитесь Плекси в Точке вторжения: Катаклизм.', 'Рад встрече, $N. Я - Плекси, а формальности отложим на потом. Мы оба знаем, зачем мы здесь, так что давай просто приступим к работе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10767, 'Точка вторжения: Катаклизм', 'Теперь, когда у нас есть доступ к базе Легиона в точке вторжения: Катаклизм, нужно придумать способ положить конец их действиям. Деревня Призрачной Луны не может спать спокойно, пока даже следы присутствия Легиона в этой местности не стерты с лица земли.$B$BЯ послал туда передовой отряд, чтобы помочь тебе уничтожить их припасы. Возвращайся в форт Легиона и воспользуйся телепортом, отмеченным зелеными кристаллами. Наканси встретит тебя на месте.', 'Доложитесь Наканси в Точке вторжения: Катаклизм.', 'Ты, должно быть, тот $R, о прибытии которого меня предупреждал Кровавый Страж Галмок. У меня есть план, но для того чтоб его осуществить, мне понадобится твоя помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10768, 'Гербовые накидки Иллидари', 'Всадники на ветрокрылах должны вернуться в деревню Призрачной Луны, чтобы подготовиться к следующему этапу нашего штурма. Теперь мне от тебя нужны гербовые накидки эльфов крови.$B$BКогда ты соберешь достаточно гербовых накидок, подай сигнал всадникам на ветрокрылах, используя кор\'кронское сигнальное ружье. Пришло время попробовать себя в шпионаже, $r!', 'Соберите 10 гербовых накидок Иллидари.', 'Ага! Неплохо проделано.', 'Докладывай, солдат!', NULL, NULL, 'Гербовая накидка Иллидари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10769, 'Удар исподтишка', 'Исследователь Тиорус был так добр, подготовить эту смесь для последней стычки. Я просто вылью ее на эту гербовую накидку, которую тебе удалось раздобыть и на ней возникнет образ негодяев иллидари.$B$BВозьми эту зачарованную гербовую накидку и отправляйся в Поля Затмения, к юго-западу от лагеря Затмения. Там используй гербовую накидку, чтобы превратиться в агента Иллидана. Пользуясь личиной, убей безумных колоссов, бродящих по полю. Они сочтут это нападением лагеря Затмения, и союз будет разорван.', 'Убейте 5 безумных колоссов в личине эльфа крови – иллидари и потом вернитесь к воеводе Ор\'бароху в деревню Призрачной Луны в одноименной долине. Верните ему кор\'кронское сигнальное ружье.', 'Так, так, так... Не тот ли это рядовой, которого я посылал в поле? Надо же, вернулся и даже целиком... $B$B<Орбарох кивает.>$B$BЯ знал, что ты меня не подведешь, солдат. Ты остановил продвижение иллидари, так что получай заслуженную награду!', 'Ты вернулся!', NULL, NULL, 'Убито безумных колоссов, будучи в облике посланника Иллидана', 'Кор\'кронское сигнальное ружье', 'Рекомендуемое количество игроков: 3', 'Зачарованная гербовая накидка Иллидари');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10770, 'Угольки', 'К северо-востоку отсюда, на плато над нами, лежит в пепелище моя родина. Прежде чем туда пришел Пылающий Легион и пригнал сюда своих огненных бесов, там росли пышные леса. Столько нас погибло, что даже сотни лет спустя мое усталое сердце жаждет мести. Врагов слишком много, чтобы мы могли вернуть себе наши земли, но ты-то можешь их устрашить.$B$BВедь ты поможешь мне?', 'Замшельник Древний просит вас убить 8 пламенных бесов, а затем вернуться к нему в чащобу Рууан.', 'Их столько, что всех не перебить, но ты дал мне надежду. Возможно, несколько следующих столетий я потрачу на возрождение моего любимого леса.', NULL, NULL, NULL, 'Пламенный бес убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10771, 'Из пепла', 'Если ты пойдешь отсюда по дороге, что идет на восток, а потом поднимается по склону горы, а затем свернешь на север, ты найдешь мой старый утраченный дом.$B$BНекода там рос лес. Название его уже забыто. Давным-давно Пылающий Легион призвал туда огненных бесов и прочих огненных тварей. Мой дом был разрушен, и мой народ бежал. Остался я один. $B$BЯ сумел спасти немного семян железнокорня, который можно посадить в плодородную вулканическую почву. Их магия сильна. Сделай это для меня, и я поделюсь с тобой сокровищами забытых веков.', 'Замшельник Древний хочет, чтобы вы отправились в Гарь и посадили семена железнокорня в три кучи плодородной вулканической почвы и вернулись к нему в чащобу Рууан.', 'Ты уничтожил множество этих мерзостных мелких тварей. Это приносит мне облегчение.', 'Дело сделано? Тебе удалось возродить хоть какую-то жизнь на моей древней родине?', NULL, NULL, 'Южная вулканическая почва', 'Центральная вулканическая почва', 'Северная вулканическая почва', 'Семена железнокорня (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10772, 'Путь Завоевания', 'От моих наездников на грифонах пришли сведения. Эльфы крови из лагеря Затмения затевают что-то крупное. Они начали сосредотачивать свои силы на Пути Завоевания, далеко на юго-востоке отсюда возле лагеря Затмения.$B$BЯ хочу, чтобы ты $gотправился туда и разобрался:отправилась туда и разобралась:, что они затевают. Когда закончишь, используй сигнальное ружье, чтобы подать сигнал всаднику на грифоне, передай ему все, что тебе удастся узнать и получи от него следующий приказ.', 'Отправляйтесь по Пути Завоевания в Долине Призрачной Луны.', 'Несомненно эти сволочи что-то замышляют. Нужно продолжать наблюдение.', 'Докладывай, солдат!', NULL, NULL, 'Исследовать локацию', 'Путь Завоевания обнаружен', 'Рекомендуемое количество игроков: 3', 'Сигнальное ружье клана Громового Молота');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10773, 'Перерезанный путь', 'Нам нужно больше времени, $r. Я собираюсь лететь вперед с другими наездниками на грифонах. Хотелось бы надеяться, что мы сможем раздобыть еще немного информации. Что мне нужно от тебя, это очистить нам путь и что самое главное, удержать подальше от нас их стрелков!$B$BВызови одного из всадников на грифоне с помощью сигнального ружья клана Громового Молота, когда ты подсчитаешь точное их число.', 'Убейте 20 солдат, 10 кавалеристов лагеря Затмения и 5 сынов Корока.', 'Ты не поверишь, солдат!', 'Докладывай, солдат!', NULL, NULL, 'Солдат лагеря Затмения убито', 'Кавалерист лагеря Затмения убито', 'Сын Корока убито', 'Рекомендуемое количество игроков: 3');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10774, 'Великан плюс эльфийка равно...', 'На южном конце Пути Завоевания, возле каравана, вставшего лагерем, мне пришлось наблюдать вроде как встречу великана и эльфийки крови в одеждах Советника. Что гиганты вообще здесь делают? Что-то здесь явно не так, солдат$B$BТебе придется пробиться к месту встречи и сорвать ее. Все, что ты сумеешь принести с места встречи, может нам поспособствовать. Как будешь $gготов:готова:, вызови одного из нас с помощью сигнального ружья.', 'Убейте канцлера Кровавую Листву и Корока Могучего и верните приказ Иллидана.', 'Так они собираются искать милости великанов? У меня есть план, как разрушить этот пугающий союз.', 'Докладывай, солдат!', NULL, NULL, 'Канцлер Кровавая Листва убито', 'Корок Могучий убито', 'Приказ Иллидана', 'Рекомендуемое количество игроков: 3');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10775, 'Гербовые накидки Иллидари', 'Наездники на грифонах должны вернуться в цитадель Громового Молота, чтобы подготовиться к следующему этапу нашего штурма. Теперь мне от тебя нужны гербовые накидки эльфов крови.$B$BКогда ты соберешь достаточно гербовых накидок подай сигнал всаднику на грифоне, используя сигнальное ружье клана Громового Молота. Пришло время попробовать себя в шпионаже, $r!', 'Соберите 10 гербовых накидок Иллидари.', 'Ага! Неплохо проделано.', 'Докладывай, солдат!', NULL, NULL, 'Гербовая накидка Иллидари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10776, 'Удар исподтишка', 'Гномус был так добр подготовить эту смесь для последней стычки. Я просто вылью ее на эту гербовую накидку, которую тебе удалось раздобыть и на ней возникнет образ негодяев иллидари.$B$BВозьми эту зачарованную гербовую накидку и отправляйся на Поля Затмения, к юго-западу от лагеря Затмения. Там используй гербовую накидку, чтобы превратиться в агента Иллидана. Пользуясь личиной, убей безумных колоссов, бродящих по полю. Они сочтут это нападением лагеря Затмения, и союз будет разорван.', 'Убейте 5 безумных колоссов, находясь в облике посланника Иллидана, потом вернитесь к тану Йорегару в цитадель Громового Молота в долине Призрачной Луны. Верните ему сигнальное ружье клана Громового Молота.', 'Так, так, так... Не тот ли это рядовой, которого я посылал в поле? Надо же, вернулся и даже целиком... $B$B<Орбарокх кивает.>$B$BЯ знал, что ты меня не подведешь, солдат. Ты остановил продвижение Иллидари, так что можешь готовиться к награде. Заслужил!', 'Ты вернулся!', NULL, NULL, 'Убито безумных колоссов, будучи в облике посланника Иллидана', 'Сигнальное ружье клана Громового Молота', 'Рекомендуемое количество игроков: 3', 'Зачарованная гербовая накидка Иллидари');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10777, 'Тотем Азгара', 'То, о чем ты $gпрочитал:прочитала: в дневнике командира – истинная правда. Пока Орда множилась под рукой Гул\'дана, мои соплеменники пытались отвести опасность, нападая на орков. Гул\'дан узнал об этом и уничтожил наши поселения, пленив души моих собратьев.$B$BИх необходимо остановить, пока они не натворили еще больше бед. На Развалинах Скет\'лона к северу отсюда найди Азгара и принеси хранящийся у него тотем. Он поможет нам спутать карты темному конклаву.', 'Принесите Паршаху в Магмовые поля военный тотем Скет\'лона.', '<Паршах изучает тотем.>$B$BОтлично. Этот древний артефакт еще не потерял свои силы, но одного его недостаточно, чтобы остановить темный конклав.', 'Ты добыл тотем у Азгара?', NULL, NULL, 'Военный тотем Скет\'лона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10778, 'Жезл Лиантэ', 'Силы одного тотема не хватит, чтобы одолеть магию темного конклава.$B$BМы можем скомбинировать его силу с другими артефактами и создать посох фокусирующий их энергию. И если мы не можем отвратить моих соплеменников от овладевшей ими порочности, то мы хотя бы можем остановить их.$B$BОдин из элементов, необходимых для посоха – Ветвь Лиантэ, которая хранится у эльфов крови в лагере Затмения к юго-востоку отсюда. Ты найдешь этот артефакт в павильоне на верхнем ярусе руин. Будь осторожнее, $N, его хорошо охраняют.', 'Заберите ключ Лиантэ у любого из эльфов крови в лагере Затмения, откройте сейф и заберите жезл Лиантэ. Вернитесь с ветвью к Паршаху в Магмовые поля.', 'Отлично! Такая вещь заслуживает лучшей участи, чем пылиться в темном сундуке. Уж мы то пристроим ее к делу.', 'Тебе удалось раздобыть Ветвь?', NULL, NULL, 'Ключ Лиантэ', 'Жезл Лиантэ', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10779, 'Путь охотника', 'Приветствую, $gюный охотник:юная охотница:. Мне кажется, ты уже $gспособен:способна: справиться со зверем и сделать его своим спутником.$B$BПоговори с охотницей Келлой Тетивой Ночи. Она расскажет тебе, как завести питомца.', 'Поговорите с охотницей Келлой Тетивой Ночи.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10780, 'Перья Скет\'лона', 'В посохе не хватает всего одной детали. Мы должны направить силу посоха против духов Темного Конклава.$B$BСделать это мы можем, собрав перья, разбросанные на земле в лагере Скет\'лона и использовав их при изготовлении посоха. Лагерь находится на юге отсюда, восточнее цитадели Громового Молота.$B$BЧары Гул\'дана уничтожили моих собратьев, оставив их души скитаться, однако на этом все не кончилось, – ведь чары питались тем заклинанием, которое араккоа готовили для подчинения духов.', 'Соберите 8 перьев Скет\'лона и принесите их Паршаху в Магмовые поля.', '<Паршах принимает пепельные перья, качая головой.>$B$BБыло бы лучше, если бы они умерли в тот день, но это было бы слишком просто. То, что чары Гул\'дана превратили их в угрозу, против которой они пытались бороться, это очень жестокая шутка...', 'Удалось ли тебе собрать перья для посоха?', NULL, NULL, 'Перо Скет\'лона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10781, 'Битва у Кровавого дозора', 'Как мы и подозревали, тебя уже ищут на Пути Завоевания. Пора уносить ноги, $r!$B$BОставь меня... Со мной все кончено. Они.. Я слышу их шаги, они уже близко. Сейчас или никогда... Убирайся! Если ты останешься, тебе придется сражаться.$B$BЕсли ты решил принять бой, и тебе каким-то чудом удастся уцелеть, передай те сведения, которые мы раздобыли А\'далу в Шаттрат.', 'Сразитесь с войском иллидари возле Кровавого дозора и останьтесь в живых!Вернитесь к А\'далу в Шаттрат, если сумеете победить.', 'Кровавой Печатью пора заняться. Они представляют немалую угрозу для всего Дренора. Я предвижу тот день, когда их хозяин ответит за все свои злодеяния. Возможно, именно тебе предстоит призвать его к ответу, герой.', NULL, NULL, NULL, 'Уничтожьте силы Кровавой Печати.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10782, 'Зарядка набалдашника', 'Посох почти закончен! $B$BОсталось только наполнить набалдашник силами, оставшимися в этих местах от Гул\'дана. На восток, около Ям Скверны, к югу от Кузницы Смерти, находится Алтарь Проклятия.$B$BТам заключены воспоминания о жизни Гул\'дана. Когда ты принесешь незавершенный набалдашник к алтарю, не удивляйся, если некоторые из объектов отреагируют на него: у тебя в руках будет опасный артефакт, связанный с катаклизмом.', 'Возьмите в руки Незавершенный Набалдашник. Отправляйтесь к Алтарю Проклятия и используйте его, пока вы находитесь возле Гул\'дана. Когда набалдашник зарядится, возвращайтесь к Паршаху в Магмовые Поля.', '<Паршах осторожно принимает набалдашник.>$B$BОн содержит силы, необходимые нам, чтобы свести на нет усилия темного конклава в Лагере Скет\'лона.', 'Набалдашник заряжен?', NULL, NULL, 'Насыщенный энергией набалдашник', 'Незавершенный набалдашник', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10783, 'Барон Черногрив', 'Вот мой план. Мы отравим огров и уничтожим их хозяина-гронна. $B$BВо время странствий в этих горах я повстречал одного человека по имени барон Черногрив. Он виртуоз алхимии, и мы можем попробовать уговорить его помочь нам.$B$BИщи его в Круге Крови дальше по каньону к северу отсюда. Какую бы цену он ни запросил, соглашайся.', 'Поговорите с бароном Черногривом в Круге Крови в Острогорье.', 'Добрая встреча, $R. Я барон Черногрив. Друг Рексара – мой друг.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10784, 'Уничтожить лагерь Кровавого Молота!', '$gТор\'чанк наклоняется поближе и шепчет.>$B$B$N, мы больше чем гордимся твоими подвигами в борьбе с ограми! И хотя я полностью уверен в планах Рексара, я все же хотел бы попросить тебя перебить огров в лагере Кровавого Молота прежде, чем ты вернешься к нему.$B$BТак мы лишний подстрахуемся.$B$BЧтобы добраться туда, ступай на север вниз по склону от оплота Громоборцев. Под склоном сверни на запад через Драконью Пагубу, а затем иди на север через Гниющую лощину и каньон Кинжальной пасти.', 'Убейте 10 извергов и 5 чернокнижников клана Кровавого Молота.', '*Тор-чанк кивает, откровенно довольный вашей убойной силой.*$B$BТы не перестаешь меня удивлять, $N. С каждым заваленным вонючим огром мы все ближе к избавлению от этих жалких врагов!', NULL, NULL, NULL, 'Изверг из клана Кровавого Молота убито', 'Чернокнижник из клана Кровавого Молота убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10785, 'Ловушка!', 'Ничто в этом мире не может вызвать у меня такого гнева, как этот Груул и его сыны! Они истребили мой народ – моих детей – но теперь я отомщу.$B$BЯ создал ловушку из драконьего огня, и если тебе хватит сообразительности, то с ее помощью ты сможешь прикончить даже гронна.$B$BТоропись, отнеси эту ловушку Рексару. Я хочу утолить жажду мести!', 'Отнесите ловушку пламени дракона Рексару в оплот Громоборцев в Острогорье.', 'Хмм, ловушка из субстанции драконьего огня? Интересно, откуда Черногрив берет такие редкие субстанции?$B$BДа ладно. Важно, что мы с помощью этой штуковины прикончим сына Груула.', 'Ты принес тот гроннов мешок от Черногрива? Что он тут нам дал?', NULL, NULL, 'Ловушка пламени дракона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10786, 'Резня в Камен\'моке', 'Я знаю, что Рексар хочет послать тебя в Камен\'мок. Мне нужно, чтобы ты там кое-что $gсделал:сделала:.$B$BМы должны пользоваться любой возможностью, чтобы нанести удар по этим горным ограм, иначе они задавят нас числом, и все наши кровь и пот будут пролиты задаром!$B$BКамен\'мок лежит далеко на севере. Иди на север в чащобу Рууан, а оттуда на запад через туннель и мимо леса Ворона.$B$B$N, я хочу, чтобы ты $gубил:убила: огров из племени Камнерогов, что живут в Камен\'моке! Стори их с лица земли!', 'Убейте 5 громил и 3 шаманов Камен\'мока, затем вернитесь к Тор\'чанку Двукогтю в Оплот Громоборцев в Острогорье.', '*Тор-чанк довольно скалится, слушая рассказ о ваших приключениях в Камен\'моке.*$B$BЭх, жаль что меня там не было! Вот что я тебе скажу, $N: никогда не соглашайся на дело, которое не приносит воинской славы! $B$BХа! Осталось ли для меня огров в этих горах после твоей кровавой бани?!', NULL, NULL, NULL, 'Громила Камен\'мока убито', 'Шаман Камен\'мока убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10788, 'Возвращение к Талионии', 'Талиония из Луносвета призывает тебя к себе, $N. Наверное, тебе пришло время научиться вызывать и контролировать более могучего демона. Отправляйся к ней – чем быстрее, тем лучше. Насколько я понимаю, Талионию можно найти в \"Святилище\", маленьком и уютном логове зла в Закоулке душегубов.', 'Поговорите с Талионией в Луносвете.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10789, 'Возвращение к Карендину Халгару', 'А, ты здесь, $N!$B$BКарендин Халгар велит тебе явиться к нему в Квартал Магов в Подгороде. Терпеливостью он не отличается, так что я бы на твоем месте не медлил.', 'Поговорите с Карендином Халгаром в Подгороде.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10790, 'Возвращение к Ган\'рулу Кровавому Глазу', 'Далеко же ты от дома, $r. Быть может, пришло время вернуться к твоему учителю, Ган\'рулу Кровавому Глазу? О нем слышали все наши собратья по ремеслу, даже в этих краях.$B$BГан\'рул живет в Расселине Теней в Оргриммаре.', 'Найдите Ган\'рула Кровавого Глаза в Оргриммаре и поговорите с ним.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10791, 'Приветствие духа Волка', 'Я почти закончил свои церемониальные одежды. Осталось только добавить несколько завершающих штрихов, а для этого мне бы хотелось, чтобы вы подожгли это возле свечей, которые находятся у рунического камня слева от меня.$B$BЭти благовония были сделаны еще во времена орочьих кланов, и я думаю, что они помогут привлечь дух волка. Я очень хорошо представляю себе, как мои предки использовали их для благодарственных церемоний после удачной охоты.$B$BЯ начну церемонию, как только вы воскурите эти благовония.', 'Зажгите обрядовые благовония около свечей в хижине Малуказа и наблюдайте за церемонией. По завершении церемонии поговорите с Малуказом еще раз.', 'Невероятно! Я отправился в это путешествие, не будучи уверенным в том, что дух волка отзовется на наш призыв, а теперь мне кажется, что он был здесь все это время! Я почти уверен в этом, $N!$B$BДолжно быть, он ждал, пока орки поймут, какие последствия имел их выбор.', 'Восстановление связи с духом волка – это лишь начало моего пути, а никак не конец.', NULL, NULL, 'Помогите Малуказу вызвать дух волка', 'Обрядовые благовония (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10792, 'Сжечь Зет\'Гор!', 'Клан Кровавой Глазницы отрекся от своего гордого рода! Мы, орки, которые сражались и умирали, только бы не запятнать себя Скверной Маннорота, видим в наших подлых сородичах лишь слабость и невежество... И поэтому они должны быть уничтожены!$B$BСтупай в Зет\'Гор, их оплот на востоке, и сожги его дотла. Убей батраков, забери у них факелы, зажги их в кузне и подожги все склады, стойла и казармы. Пусть все сгорит в огне! Уничтожь их и возвращайся ко мне.$B$BВо имя Орды!', 'Убейте батраков из клана Кровавой Глазницы, заберите у них факелы, зажгите факелы в кузне Зет\'Гора и забросьте горящие факелы в строения Зет\'Гора.', 'Ха! Я вижу огонь и чую дым, поднимаюшиеся над Зет\'Гором, даже отсюда! Пусть эти дьяволы из клана Кровавой Глазницы сгорят дотла, а их пепел развеет ветер, так, чтобы на земле, по которой ходят настоящие орки, даже следа не осталось!$B$BСпасибо тебе, $N. Ты помог нам очистить огнем наши души.', NULL, NULL, NULL, 'Казармы горят', 'Восточная лачуга горит', 'Западная лачуга горит', 'Стойла горят');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10793, 'Записи Вал\'зарека: Предвестье Войны', 'В этом журнале описаны недавние действия армии Иллидана. Так же в нем объясняется, почему Вал\'зарек так демонстративно использовал Путь Завоевания. Ему был поручен захват верховного генерала Ша\'тар.$B$BЭтот генерал находился в пункте известном как Кровавый дозор, расположенном в южном конце Пути Завоевания. Таинственная группа, называющая себя Кровавая Печать обвиняется в его похищении. Если ты решишь, разузнать больше об этом деле, захвати с собой подмогу.', 'Найдите Марка Аврелиона, верховного генерала Ша\'тар в Кровавом дозоре.Ищите его в кристаллической тюрьме.', 'Ты убил их предводителя? Тогда времени у нас уже нет... $B$BКровавая Печать – группа, состоявшая из элитных бойцов Иллидана. Они – верхушка всех сил иллидари вне Черного храма. Эти солдаты общаются непосредственно с Предателем, беспрекословно выполняя его приказы.$B$BЗлодеи, несомненно, готовые растоптать весь этот мир и любого, кто осмелится встать у них на пути.', '<Генерал Аврелион появляется в глубине кристалла.>$B$BСлушай... А ты что тут делаешь?', NULL, NULL, 'Записи Вал\'зарека (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10794, 'Разбойники Изувеченной Длани', 'Знаешь, $N, нам открыты далеко не все тайны мира. К примеру, искусством приготовления смертельных ядов мы так и не овладели. А вот орки из клана Изувеченной Длани постигли вершины этого мастерства. Отправляйся в Оргриммар и постарайся завоевать их доверие.$B$BСначала пройди в Подгород через портал в Луносвете, затем выйди за пределы города и следуй к ближайшей башне. Там ты сможешь сесть на дирижабль гоблинов и долететь до Оргриммара. Затем найди Шентула в Расселине теней.', 'Поговорите с Шентулом в Оргриммаре.', 'Что, еще одна желающая? Такими темпами у нас скоро места в клане не останется!$B$BЛадно, слушай внимательно. Сейчас расскажу, что тебе предстоит.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10795, 'Встреча с Доргоком', 'Отлично, я как раз хотел поговорить с тобой об одном важном деле.$B$BДонесения говорят, что огры из клана Кровавого Молота затевают налет на Сильванаар и чащобу Рууан. Мы не знаем, кто стоит за всем этим или толкает их к этому, но я намерен сорвать их план!$B$BНаступление готовится из лагеря Кровавого Молота. Иди на северо-запад вниз по склону из чащобы Рууан, и мимо не пройдешь. Я хочу, чтобы ты $gубил:убила: их предводителя, Доргока!', 'Убейте Доргока в лагере Кровавого Молота.', 'Раз Доргок убит, огры из клана Кровавого Молота остались без руководства и будут в панике, пока у них не появится новый предводитель.$B$BСпасибо тебе, $C, теперь мы легче вздохнем.', NULL, NULL, NULL, 'Доргок убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10796, 'Уничтожить лагерь Кровавого Молота!', 'Мы так гордимся твоими победами над ограми! Теперь я попрошу тебя снова сразиться с ними. Я хочу, чтобы ты $gперебил:перебила: огров в лагере Кровавого Молота! $B$BЧтобы добраться туда, спустись по склону на северо-запад из чащобы Рууан. Ты найдешь их под самым склоном.$B$BУдачи, $C!', 'Убейте 10 извергов и 5 чернокнижников клана Кровавого Молота.', '*Лейтенант кивает, откровенно довольная вашими убойными способностями.*$B$BВы поражаете меня, $N. Похоже, вы не зря заслужили свою репутацию.$B$BС каждым убитым огром мы приближаемся к на шаг к нашей цели - избавлению от опасности, ибо мы хотим жить в мире.', NULL, NULL, NULL, 'Изверг из клана Кровавого Молота убито', 'Чернокнижник из клана Кровавого Молота убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10797, 'Благоволение гронна', 'Из мертвой руки Доргока выпадает какая-то маленькая статуэтка. Она невероятно похожа на гронна.$B$BНесомненно, командир Гефус Камнестен из Вечной рощи в чащобе Рууан, что вверх по склону на востоке, заинтересуется этой вещицей!', 'Отнесите благоволение Горгрома командиру Гефусу Камнестену в Вечную рощу в Острогорье.', 'Ух ты, прелесть какая. Очень похоже на тех гроннов, которые вечно гоняют огров из клана Камнерогов. Но странно, что ты нашел ее у одного из главарей клана Кровавого Молота.', 'Привет, парень, какие новости?', NULL, NULL, 'Благоволение Горгрома (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10798, 'Визит к барону', 'Дурные вести. Горгром Драконоед стоит за недавней вылазкой Кровавых Молотов в Сильванаар!$B$BКак ему удается манипулировать ими, причем не только натравливая на них клан Камнерогов – я не знаю. Но если мы хотим разделаться с гронном, нам понадобится помощь.$B$BЯ знаю одного человека, который владеет необычной магией. Барон Черногрив зовут его. Ты найдешь его в Круге Крови, если пойдешь вниз по юго-западному склону, а затем на юго-запад по каньону.$B$BПопроси его сделать для нас ловушку на гронна.', 'Поговорите с бароном Черногривом, живущим в Круге Крови в Острогорье.', 'А, посланник напыщенного Альянса. Ну, говори мне, жалкая тварь, чего ради ты здесь? Почему твое блистательное командование само сюда не пришло с просьбой?$B$BНеужто они боятся меня? Это кое-что говорит о тебе, хотя я еще не решил, что именно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10799, 'Прогулка в Беспокойную лощину', 'Ладно, я сделаю эту ловушку, но сначала я кое-что потребую от тебя.$B$BИ уж так получилось, что это некая вещь, которой владеет живущий по соседству гронн, но пока тебе еще рано биться с ним.$B$BПотому мы с тобой сделаем сонный порошочек из яда живущих тут землероев.$B$BТы найдешь их в Беспокойной лощине на юго-западе. Принеси мне их железы, да побыстрее!', 'Соберите 7 ядовитых желез землероев.', 'Очень хорошо. Простая, прямо-таки тупая задача решена. Теперь давай мне железы, и я займусь самым трудным делом.', 'Ну как, добыл ядовитые железы? Если нет, то иди вон и не отнимай у меня времени, пока не сделаешь, как я велел.', NULL, NULL, 'Ядовитая железа землероя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10800, 'Спи спокойно, гронн', 'Я снова превзошел самого себя! Я сделал сонный порошок. Бери его и используй против Груллока, того самого гронна, который стережет ту вещь, что мне нужна.$B$BГруллок засел в Окаянной лощине, что в восточном конце Драконьей Пагубы по ту сторону Круга Крови.$B$BБудь я на твоем месте, я не стал бы тянуть, как только стянул бы его мешок. Действие порошка долго не продержится.', 'Украдите мешок Груллока.', '<Барон Черногрив заглядывает в мешок. Похоже, он доволен.>$B$BЧто же, свою часть сделки ты выполнил. И теперь я, так и быть, дам твоему командиру Каменной Стене ловушку.', 'И снова передо мной ты, $C. Стало быть, ты стянул мешок прямо из-под носа у Груллока.', NULL, NULL, 'Мешок Груллока', 'Сонный порошок Черногрива (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10801, 'Ловушка!', 'Никого в этом мире я не ненавижу сильнее чем этого Груула и его сыновей! Они истребили мой народ – моих детей – но теперь я отомщу.$B$BЯ создал ловушку из драконьего огня, и если тебе хватит сообразительности, то с ее помощью ты сможешь прикончить даже гронна.$B$BТоропись, отнеси эту ловушку твоему командиру Каменной Стене. Я хочу утолить жажду мести!', 'Отнесите ловушку пламени дракона командиру Гефусу Камнестену в Вечную рощу в Острогорье.', 'Хмм, ловушка из субстанции драконьего огня? Интересно, откуда Черногрив берет такие редкие субстанции?$B$BДа ладно. Важно, что мы с помощью этой штуковины прикончим сына Груула.', 'Барон изготовил ловушку? Она способна прикончить гронна?', NULL, NULL, 'Ловушка пламени дракона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10802, 'Горгром Драконоед', 'Мы должны показать этим ограм, что с нами шутки плохи! Так что надо вправить им мозги.$B$BИди в Камен\'мок и перебей тамошних огров. Забери их головы.$B$BА потом ступай к алтарю Горгрома и поставь там на него ловушку. Горгром явится – замани его в ловушку. Когда он сдохнет, поставь свои тотемы гризли возле его туши, чтобы огры, увидев своего убитого хозяина и сородичей и поняли, что им будет за нападения на нас!', 'Добудьте 3 тотема гризли у огров Камен\'мока. Поставьте ловушку Черногрива на алтарь Горгрома, затем призовите и убейте Горгрома Драконоеда.Когда Горгром будет убит, поставьте 3 тотема гризли возле его туши.', 'Славно, славно, $N. Отлично!$B$BДумаю, теперь об ограх и их хозяине мы ничего не услышим.', 'Ну, ты оставил им послание?', NULL, NULL, 'Установлено тотемов гризли', 'Ловушка Черногрива (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10803, 'Резня в Камен\'моке', 'Я знаю, что у нас были планы направить тебя в Камен\'мок. В связи с этим у меня есть для тебя одно поручение.$B$BМы должны пользоваться любой возможностью разбить огров из здешних гор, иначе они просто задавят нас числом, и все, за что мы заплатили кровью, пойдет прахом!$B$BКамен\'мок находится на западе. Отправляйся на юго-запад через мост, затем прямо в туннель. На западной стороне леса Ворона ты их и найдешь.$B$B$N, сотри с лица земли огров из Камен\'мока!', 'Убейте 5 громил и 3 шаманов Камен\'мока.', '*Лейтенант Файрвезер с ухмылкой выслушивает рассказ о ваших приключениях в Камен\'моке.*$B$BКак жаль, что меня там не было! Вот что я вам скажу, $N: никогда не беритесь за дело, которое не сулит воинской славы!$B$BХа! Небось, после такого кровопускания на мою долю в этих горах ни огра не осталось!', NULL, NULL, NULL, 'Громила Камен\'мока убито', 'Шаман Камен\'мока убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10804, 'Доброта', 'Что-то пугает их, $r.$B$B<Морденай показывает на кружащих над землей драконов Пустоты.>$B$BДаже добыча не заставит их спуститься на землю. Я видел, как некоторые из них, падали от истощения, умирая еще прежде чем коснуться земли.$B$BМы должны спасти их! Скалопалые камнедеры, которые водятся возле месторождений кристаллов – их естественная добыча. Убей этих тварей, и разложи их туши на поле. Если ты не будешь шевелиться и проявлять агрессию, тебя не тронут.', 'Накормите 8 взрослых драконов Пустоты по просьбе Морденая на Полях Крыльев Пустоты.', 'Ты – настоящий $R, друг мой.', 'Я не могу спасти их в одиночку, $N!', NULL, NULL, 'Накормлено взрослых драконов Крыльев Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10805, 'Резня в логове Груула', 'Ты хорошо себя $gпоказал:показала:, и теперь, думаю, использую-ка тебя в моей личной борьбе с Груулом и его сыновьями.$B$BЭтот гронн держит в милости клан Камнерогов, и хотя ты уже изрядно $gпроредил:проредила: их ряды, с самыми сильными из их числа тебе еще не доводилось сталкиваться.$B$BЛогово Груула защищают самые сильные огры, и вот их-то тебе и придется перебить. Иди сейчас на север через каньон Кинжальной Пасти, и в конце его найдешь логово Груула.', 'Убейте 10 головорезов, 5 боевых магов, 5 опустошителей из клана Камнерогов и их предводителя, Фингрома.', 'Очень хорошо. Я не ошибся, поставив на тебя, как на моего поборника. Пора, думаю, сделать шаг вперед.$B$BПомнишь ту маленькую штучку, которую ты стянул для меня прямо из-под носа у Груллока? Теперь тебе выпал шанс употребить ее по назначению.', NULL, NULL, NULL, 'Головорез из клана Камнерогов убито', 'Боевой маг из клана Камнерогов убито', 'Опустошитель из клана Камнерогов убито', 'Фингром убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10806, 'Перед выстрелом', 'Скоро настанет пора встретиться лицом к лицу с Гоком, хозяином огров из клана Камнерогов. И пора мне самому вмешаться, чтобы взять жизнь последнего гронна.$B$BВозьми мой перстень с печаткой. Когда придешь к алтарю Гока, надень его – и я приду.$B$BВместе мы одолеем Гока.', 'Воспользуйтесь перстнем Черногрива у алтаря Гока, затем убейте Гока.', 'Ты сражаешься на удивление хорошо для |3-1(ночной эльф), и для меня большая честь биться рядом с тобой. Наверное, мое преображение весьма удивило тебя. Надеюсь, я не слишком тебя напугал?$B$BПусть это останется нашей маленькой тайной, ладно? А я за твою верную службу даю тебе на выбор любую из этих вещиц.', 'Настанет время, и всем сынам Груула придет конец.', NULL, NULL, 'Гок убито', 'Перстень Черногрива (Прилагается)', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10807, 'Сломленные из племени Пеплоустов', 'Пеплоустов боятся все Павшие, В этот клан входят самые жестокие и кровожадные представители племени, которых отбирает лично Акама. Свирепостью они не уступают ни нагам, ни демонам, ни эльфам крови из армии Иллидана, и сейчас они во множестве собрались в руинах Баа\'ри к северу отсюда. Ступай туда и прореди их число, прежде чем они соберутся напасть на нас.', 'Убейте для Варена Исправителя 3 укротителей, 4 воинов и 6 шаманов из племени Пеплоустов.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Слава Провидцам, $N! Ты исполнил волю Провидца, сокрушив тех, кто служит Иллидану.', NULL, NULL, NULL, 'Пеплоуст-укротитель убито', 'Пеплоуст-воин убито', 'Пеплоуст-шаман убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10808, 'Крах темного конклава', 'Духи, входящие в темный конклав, намерены воззвать к темному и древнему злу через ритуал, который они проведут возле лавовых ям к югу от Лагеря Скет\'лона.$B$BМагия Гул\'дана, смешавшаяся с их собственной, призывает их вновь вернуть этого смертельно опасного чародея в наш мир. Мы не можем этого позволить, $N. Хаос и разрушения, которые он принесет с собой, будут неизмеримы.$B$BБери с собой посох, отправляйся на место проведения ритуала и останови темный конклав раз и навсегда.', 'Убейте ритуалистов Темного конклава и используйте посох Паршаха, чтобы прервать ритуал призыва. По выполнении задания вернитесь к Паршаху в Магмовые поля.', 'Я искал способ остановить темный конклав годами, а тебе это удалось так быстро! Теперь они больше не являются для нас угрозой.$B$BЯ часто чувствую свою вину за то, что бросил своих товарищей перед лицом смерти. Но теперь я знаю, что принял правильное решение. Если бы тогда моя решимость не дрогнула, я бы стал такой же безропотной тенью.', 'Как все прошло, $N? Удалось ли тебе прервать ритуал вызова?', NULL, NULL, 'Прервите ритуал Темного Конклава', 'Посох Паршаха (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10809, 'Разыскивается: повелитель воргов Крууш', 'В объявлении написано следующее:$B$B\"Повелитель воргов Крууш возглавляет наездников на воргах из клана Кровавой Глазницы. Он и его наездники виновны в совершении налетов на караваны с припасами заставы Хребтолома. За их головы назначена награда.\"$B$B\"В последний раз разведчики видели Крууша возле Зет\'Гора. Храбрец, который принесет головы негодяев, заслужит благодарность Орды и солидное денежное вознаграждение.\"$B$B\"Капитан Мрачный Вой\"', 'Убейте повелителя воргов Крууша и принесите его голову капитану Мрачному Вою на Заставу Хребтолома.', 'Ага, ты убил этого негодяя Крууша! Отлично, $N! Отлично! Можно сказать, вырвал зубы этим проклятым наездникам на воргах. Надеюсь, тебе удалось уложить хотя бы несколько штук во время налета на Зет\'Гор?$B$BВот, возьми награду. Ты ее заслужил.', 'Докладывай, $N. Надеюсь, на твоей одежде кровь орков из клана Кровавой Глазницы?', NULL, NULL, 'Голова повелителя воргов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10810, 'Поврежденная маска', 'Исследуя поврежденную маску, вы слышите, что изнутри нее доносятся странные звуки. Не будь она повреждена, вы могли бы расслышать все гораздо четче.$B$BВозможно, О\'Малли Быстроцап из чащобы Рууан сможет ее починить.', 'Отнесите поврежденную маску О\'Малли Быстроцапу в Чащобу Рууан в Острогорье.', 'А, что там у тебя? Дай-ка посмотреть поближе, $C. Да, да… так я сразу и подумал. Ну давай, сейчас я ее залатаю.', 'Да что ты пристал ко мне! Не видишь, я пытаюсь высвободить таинственные силы?', NULL, NULL, 'Поврежденная маска (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10811, 'Поиски Нельтараку', 'Их предводитель высоко летает, $N. Возможно, участие, которое ты проявил к его детям, тронет его. Найди Нельтараку и воспользуйся его помощью, Вместе вы сможете выполнить твои обязательства перед драконами Крыльев Пустоты.$B$B*Морденай указывает на небо.*$B$BУдачного тебе полета...', 'Найдите Нельтараку, предводителя рода Крыльев Пустоты.', 'Мои дети рассказали мне о твоих подвигах, $R. Можешь ли ты помочь нам еще немного?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10812, 'Тайная маска', 'Ну, вот, теперь будет работать. Желаешь знать, что это такое? Да устройство связи – позволяет этим тупицам общаться друг с другом. И это Пылающий Легион! Я бы предложил отнести эту маску Владыке леса Антелариону. Он тут где-то снаружи прогуливается. Никогда на месте не сидит, понимаете ли.$B$BЕму такую штуку уже давно заполучить хочется.', 'Отнесите таинственную маску Владыке леса Антелариону в Чащобу Рууан в Острогорье.', 'Маска, что ты держишь в руках – это респиратор Верных Скверне, и судя по всему, он целый! Теперь мы можем устроить очень большие неприятности лагерю Легиона: Злоба. Не хочешь ли помочь нам, $N?', 'Глазам своим не верю!', NULL, NULL, 'Тайная маска (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10813, 'Очи Гриллока', '$N, у тебя хватило отваги забраться в Зет\'Гор, в логово проклятых орков из клана Кровавой Глазницы, и вернуться оттуда $gживым:живой:. Возможно, у тебя хватит сил помочь мне, ибо я собираюсь заглянуть в мысли их самого страшного колдуна Гриллока.$B$BВВозьми этот кристалл. С его помощью заколдуй око Гриллока, чтобы он оказался к тебе привязан. Затем возвращайся сюда и подойди к моему котлу... он поглотит это око.$B$BСтупай, $N. Но будь $gосторожен:осторожна: – малейшая заминка, и око выдаст тебя врагам!', 'Используйте кристалл Зеззака, чтобы захватить Око Гриллока, затем приблизьтесь к котлу Зеззака, чтобы тот смог извлечь Око. После выполнения задания верните Зеззаку кристалл.', 'Я в долгу перед тобой, $N. Ты снова мужественно проник в Зет\'Гор, преодолев его тьму. Я исследую этот глаз, возможно, он раскроет нам секреты своего хозяина Гриллока.$B$BБудем надеяться, что его магия больше никому не послужит!', 'Когда-то орки из клана Кровавой Глазницы были нашими добрыми союзниками... Но сейчас стали злейшими врагами.', NULL, NULL, 'Око Гриллока возвращено', 'Кристалл Зеззака (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10814, 'История Нельтараку', 'У меня есть информация, которая тебе пригодится. Слушай внимательно, $r.', 'Поговорите с Нельтараку и выслушайте его историю.', 'Так ты поможешь нам?', 'Мне будет позволено закончить?', NULL, NULL, 'История Нельтараку', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10815, 'Записи Вал\'зарека: Предвестье Войны', 'В этом журнале описаны недавние действия армии Иллидана. Так же в нем объясняется, почему Вал\'зарек так демонстративно использовал Путь Завоевания. Ему был поручен захват верховного генерала Ша\'тар.$B$BЭтот генерал находился в пункте известном как Кровавый дозор, расположенном в южном конце Пути Завоевания. Таинственная группа, называющая себя Кровавая Печать обвиняется в его похищении. Если ты решишь, разузнать больше об этом деле, захвати с собой подмогу.', 'Найдите Марка Аврелиона, верховного генерала Ша\'тар, в Кровавом дозоре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10816, 'Восстановление Святых земель', 'Ты неплохо себя проявил против Падших в Баа\'ри, $N. Посмотрим, как хорошо ты сработаешь против, самого страшного, - армии Иллидана. $B$BОрки Скверны из клана Призрачной Луны занимают Террасу Ата\'мала, когда-то священное место, где кристаллы Ата\'мала использовались на жреческих церемониях.$B$BМы думали, они прячут этот кристалл где-то неподалеку, но наша разведка не дала никаких результатов. Однако Орки Скверны находятся на святой земле дренеев, и с этим нужно что-то делать!', 'Убейте для воздаятеля Алуумена 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Прекрасно, $C. Да пребудет с тобой Свет.', NULL, NULL, NULL, 'Душегуб из клана Призрачной Луны убито', 'Избранный из клана Призрачной Луны убито', 'Темнопряд из клана Призрачной Луны убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10817, 'Великое воздаяние', 'Ты неплохо себя $gпоказал:показала: против сломленных из племени Пеплоустов, $N. Теперь у меня для тебя новое задание. $B$BНе так давно, святилище Звезд захватили иллидановы орки Скверны.$B$BНам известно, что это совершили орки из клана Призрачной Луны, которые сейчас занимают террасу Ата\'мала.$B$BПокажи им, что с Провидцами шутить не стоит.', 'Убейте для Варена Исправителя 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Сегодня ты завоевал мое безмерное уважение, $N.$B$BУбить одного орка Скверны не так то просто, но уничтожить столько... Это поистине подвиг!', NULL, NULL, NULL, 'Душегуб из клана Призрачной Луны убито', 'Избранный из клана Призрачной Луны убито', 'Темнопряд из клана Призрачной Луны убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10818, 'Барон Черногрив желает вас лицезреть', '$N, пока ты демон знает где $gгеройствовал:геройствовала:, сюда пр$Nал ручной дракон барона Черногрива с посланием.$B$BТребует тебя лично. Как я понял, он хочет, чтобы ты $gпомог:помогла: ему в его личной разборке с гронном.$B$BПонятно, что лучше тебя в Запределье ему не найти для этого дела, Но на твоем месте я оповестил бы парочку друзей и назначил бы им встречу у Круга Крови.', 'Поговорите с бароном Черногривом в Круге Крови в Острогорье.', 'А, вижу у тебя нашлось время ответить на мое приглашение.$B$BЛадно, у меня была уйма времени на подготовку отмщения, и ты будешь моим мечом в грядущей битве!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10819, 'Респиратор Искаженных', 'У меня есть для тебя особое поручение, $N. Мне нужно, чтобы ты $gпроник:проникла: в Лагерь Легиона: Злость, что к востоку отсюда. Когда войдешь в лагерь, тебе нужно будет надеть респиратор Искаженных и найти переговорное устройство Легиона. Как только найдешь его, заговори с любым, кто на другом конце линии связи.$B$BЕсли все получится, то ты сможешь сыграть над демонами злую шутку! Скажи им, что лагерь Злость взбунтовался.$B$BУдачи, $C.', 'Наденьте респиратор Искаженных и воспользуйтесь переговорным устройством Легиона в Острогорье в Лагере Легиона: Злость.', 'Это еще что такое! Кто смеет меня вызывать? Говори, или заставлю тебя умолкнуть навеки!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10820, 'Обмануть врага', 'Чем дольше ты молчишь, тем ближе ты к смерти! ГОВОРИ!$B$BЧто? В лагере бунт? Не может быть такого! Мои рабы не посмеют испытывать на прочность мою власть!$B$BНу, ужо им, все до единого они заплатят за предательство, и дорого заплатят! Заткни их, и покончим с этим! Как только выполнишь приказ, доложи мне, иначе я и с тобой разделаюсь!', 'Убейте 4 рабочих Кузни Рока и 4 инженеров Кузни Рока.', 'Это научить их повиноваться... $B$BКстати... где Вестница Рока? Почему ты доносишь об этом бунте мне, а не ей?', NULL, NULL, NULL, 'Рабочий Кузни Рока убито', 'Инженер Кузни Рока убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10821, 'Уволена!', 'И Вестница Рока не задавила бунт? Как она посмела! Она пыталась в свое время подсидеть меня. Ничего, эта попытка будет для нее последней. Призови ее и лично разберись с ней.$B$BЕе стражи злобы хранят ключи, при помощи которых ее можно вызвать в лагерь Легиона: Злоба. Добудь пять ключей и активируй пять обелисков Легиона. Они действуют недолго, потому постарайся активировать их одновременно. Помни, у стражей злобы больше ключей.', 'Убейте Вестницу Рока. +250 ед. репутации с Кенарийская экспедиция', 'Великолепная новость, даже великая, $N. Я и мечтать о таком исходе не смел! Мы высоко оцениваем твою службу на благо нашего народа. Выбери любой из этих достойных героя предметов.$B$BМы навсегда сохраним твое имя в наших сердцах.', NULL, NULL, NULL, 'Вестница Рока убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10822, 'Перстень Ярости Солнца', '', '', 'Победа Провидцев! Скоро силы Келя будут разгромлены', NULL, NULL, NULL, 'Перстень Ярости Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10823, 'Больше перстней Ярости Солнца', '', '', 'Скоро о тебе заговорят, $N. Продолжай в том же духе.', NULL, NULL, NULL, 'Перстень Ярости Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10824, 'Перстни Ярости Солнца', 'Выживут ли Провидцы, сейчас зависит от того, сможем ли мы прекратить рост армии Кель\'таса. Каждый путник из Кель\'Таласа, встающий под знамена принца, еще на один шаг приближает его к победе. В принципе, то же самое верно и для нас.$B$BКак только приток новобранцев кончится, война сведется к тому, кто быстрее перебьет войско противника. Докажи свою верность Провидцам, принеси мне перстни армии Ярости Солнца, которые носят высокопоставленные эльфы крови, союзники Кель\'таса и Иллидана. Ты найдешь этих эльфов в лагере Затмения к западу отсюда или в руинах Карабора на северо-востоке.', 'Принесите 10 перстней армии Ярости Солнца боевому магу Вияре в святилище Звезд.Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.', 'Победить эльфов Келя, не так-то просто. Превосходно!', 'Продолжай, $N.', NULL, NULL, 'Перстень Ярости Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10825, 'Тайна сферы', 'Этот странный магический шар выпал из-под контурных перьев араккоа. Шар светится неестественным лиловым светом и пульсирует, словно сердце. Вам не слишком приятно держать его в руках, потому вы быстро прячете его в сумку.$B$BВозможно, хранитель деревьев Чаун из чащобы Рууан на западе за туннелем и мостом Драконьего Черепа пожелает изучить его?', 'Доставьте сферу Гришны хранителю деревьев Чауну в Вечнуу рощу в Острогорье.', 'Да, это твоя сфера! Как странно – похоже, ее сделали араккоа. Ты что, только что из Гришната?$B$BТогда все понятно, но какой недоброй цели она служит – я не понимаю. Хотя она источает зло, у меня такое ощущение, будто она как-то связана с миром природы.$B$BДай-ка я попытаюсь активировать ее. Хотя в ней таится сильное зло, в ней есть и какая-то остаточная память...', 'Воин, ты тоже чувствуешь это? Что-то неестественное и злое совсем рядом!', NULL, NULL, 'Сфера Гришны (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10826, 'Знаки Саргераса', 'Теперь тебе должно быть ясно, почему мы враждуем с Легионом и его приспешниками.$B$BЕсли ты хочешь упрочить свое положение среди Алдоров, принеси мне высшие знаки отличия Легиона и их последователей из Совета Теней. Здесь в долине Призрачной Луны сейчас находится множество воинов Легиона, в особенности в западной части долины, возле форта Легиона и Кузницы Смерти.', 'Принесите 10 знаков Саргераса предвестнику Саронену в Долину Призрачной Луны.Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.', 'Ты отважна, друг мой. Пусть отныне все узнают, что ты – наш истинный союзник.', 'Принесла ли ты, вражеские знаки отличия, $N?', NULL, NULL, 'Знак Саргераса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10827, 'Больше знаков Саргераса', '', '', 'Уничтожь любого врага Света, который попадется тебе на пути, $N.', NULL, NULL, NULL, 'Знак Саргераса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10828, 'Знак Саргераса', '', '', 'Ты доказал, что от тебя может быть польза, $N.', NULL, NULL, NULL, 'Знак Саргераса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10829, 'Древоствол должен знать!', 'Очень тревожно! Эти араккоа делают так, что древни и защитники леса подпадают под власть злых духов!$B$BНо осталось еще одно древо, которое не пострадало. Его имя Древоствол, и ты $gдолжен:должна: тотчас пойти к нему, если мы хотим спасти деревья леса Ворона!$B$BВозвращайся в лес Ворона. Ты найдешь его на развилке тропы сразу после Гришната.', 'Найдите Древоствола, древо мудрости, обитающее в Лесу Ворона в Острогорье, и поговорите с ним.', 'Привет тебе, крошка $R. Птицы в моих ветвях напели мне о тебе, и я тебя ждал.$B$BТы здесь ради того, чтобы помочь деревьям нашего леса исцелиться от одержимости?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10830, 'Экзорцизм для деревьев', 'Из-за Гришны в листобородов и каменные стволы вселились злые духи кои-кои.$B$BМы должны как можно скорее избавить деревья леса Ворона от этой беды, иначе мы потеряем этот лес навсегда!$B$BВоспользуйся магией гришнатской сферы – эти сферы находят в Гришнате – и пером лютого ворона.$B$BПолучится перо экзорцизма. Изгони и перебей этих духов кои-кои как можно скорее! Каменные стволы для этого ритуала слишком могучи, но если удастся спасти достаточно листобородов, каменные стволы тоже освободятся.', 'Найдите 5 сфер Гришната и 5 перьев ужасающего ворона и превратите их в перья изгнания духов. При помощи этих перьев изгоните и уничтожьте 5 духов кои-кои из листобородов Леса Ворона.', 'Зло покидает лес Ворона! Чувствуешь, $N?$B$BТы спас нас и все живое вокруг от неизбежной погибели, малыш!$B$BУ меня в ветвях хранятся четыре магических кольца - на случай вроде нынешнего, когда надо наградить героя за великие подвиги.$B$BТы и есть этот герой! Приношу тебе благодарность от имени всего леса Ворона!', NULL, NULL, NULL, 'Очищено листобородов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10831, 'Обучение шитью из луноткани', 'Если хочешь, я могу научить тебя шить из луноткани. Ты научишься ткать изначальную луноткань, которой у тебя получится в два раза больше, чем у обычного портного, и сможешь изучить несколько специальных выкроек. Но сначала придется пройти небольшое испытание.$B$BТебе нужно изготовить образец изначальной луноткани в лунном колодце Кенарийского приюта. Все необходимые материалы я тебе дам. Когда изготовишь образец, приноси его мне, я посмотрю.', 'Возьмите отрез прочной ткани Пустоты, встаньте в лунный колодец Кенарийского приюта и изготовьте изначальную луноткань. Готовую ткань отнесите Назмаре Песне Луны в Нижний город Шаттрата.ВНИМАНИЕ! Вы можете специализироваться только на одном виде ткани.', '<Назмара внимательно рассматривает ткань, вертя ее в руках.>$B$BСпасибо, это замечательный образец, Ягамля. Ты научишься шить отличные вещи из луноткани.', 'Тебе удалось создать образец изначальной луноткани?', NULL, NULL, 'Образец изначальной луноткани', 'Запас изначальной луноткани', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10832, 'Обучение шитью из огненной чароткани', 'Я могу обучить вас шитью из чароткани огненных чар, но помните, что это довольно опасное занятие.$B$BКогда будете изготавливать чароткань в Пустоверти, вы привлечете внимание могущественных призраков. Я ищу способ избежать этого, но для исследований мне не хватает сущностей Призраков Пустоты.$B$BВот, возьмите с собой в Пустоверть этот маяк, вызовите с его помощью призрака и принесите мне его сущность - тогда я обучу вас. Те, кто умеет шить из ткани чароткани, изготавливают в два раза больше этой ткани и получают эксклюзивные выкройки.', 'Принесите образец сущности призрака Пустоты Гидже Чароплетке в Нижний город Шаттрата.ВНИМАНИЕ! Вы можете специализироваться только на одном виде шитья.', '*Гиджа рассматривает сущность Призрака Пустоты.*$B$BДаже такая малая часть этого существа наделена внушительной силой. Возможно, я не разглядела истинного положения вещей. Забирая энергию из окружающей среды, мы не злим призраков, скорее, призраки и окружающая среда являются единым целым!$B$BТеперь, когда вы научились шить из ткани чароткани, обязательно рассказывайте мне обо всех открытиях, которые вам удастся сделать.', 'Вы достали образец призрака Пустоты?', NULL, NULL, 'Сущность призрака Пустоты', 'Маяк призрака Пустоты (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10833, 'Обучение шитью из тенеткани', 'Если ты решишь специализироваться на шитье из тенеткани, то будешь изготавливать в два раза больше такой ткани по сравнению с обычными портными, а также получишь несколько эксклюзивных выкроек.$B$BРазумеется, любой портной может пользоваться алтарем теней, но специалисты по тенеткани чувствуют его силу гораздо лучше и обладают способностями, доступными далеко не всем.$B$BВот, отнеси этот кристалл в восточную часть долины Призрачной Луны и найди там перевал Крыльев Пустоты – он идет на юг от полей Крыльев Пустоты. Возле самого края земли стоит алтарь теней – задействуй кристалл именно там.', 'Укрепите связь с Алтарем Теней при помощи кристалла Глубоких Теней, после чего вернитесь к Андриону Темнопряду в Нижний город Шаттрата.ВНИМАНИЕ! Вы можете специализироваться только на одном виде шитья.', 'Вижу, ваш поход к алтарю прошел успешно. Вы кое-чем отличаетесь от других; немногим это отличие заметно, но, тем не менее, оно есть.', NULL, NULL, NULL, 'Укрепите связь с Алтарем Теней', 'Кристалл глубоких теней', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10834, 'Гриллок \"Пустой Глаз\"', 'Гриллок Пустой Глаз приобрел свою силу, заключив сделку с демонами и продав частицу себя за те$Nю магию. Теперь демоны играют его глазом в преисподней, поджаривая его на медленном огне. Пустой глаз, как напоминание о предательстве, Гриллок скрывает под повязкой, которая хранит свои собственные темные тайны.$B$BПринеси мне ее, $N, и я щедро награжу тебя за службу.', 'Убейте Гриллока Пустого Глаза и принесите Зеззаку на Заставу Хребтолома повязку на глаз Гриллока.', 'О, да. У воинов, потерявших в боях руку или ногу, отсутствующая конечность часто болит. Хотел бы я знать, что чувствует Гриллок, и мечтает ли он, глубоко-глубоко в душе, вернуть свой глаз обратно.$B$BЯ много думал об этом. Может быть, когда-нибудь я смогу узнать, что заставило Гриллока и орков из клана Кровавой Глазницы предаться демонам.', 'Злоба орков из клана Кровавой Глазницы не знает границ. В совершении преступлений с ними могут тягаться разве что их родичи из клана Изувеченной Длани.', NULL, NULL, 'Повязка на глаз Гриллока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10835, 'Аптекарь Антонивич', '$N, я подготовил промежуточный отчет о своей работе с кровью орков из клана Кровавой Глазницы. Думаю, мой траллмарский коллега аптекарь Антонивич будет счастлив получить его. Он тоже изучает феномен орков Скверны... При необходимости мы должны суметь оградить наших союзников-орков от трагедии, которая приключилась с их собратьями.$B$BДоставь Антонивичу мое донесение, а я пока продолжу исследование принесенных тобой образцов крови. Если нам повезет, мы поймем, чем вызвано появление орков Скверны.', 'Доставьте послание Албрека аптекарю Антонивичу в Траллмар на Полуостров Адского Пламени.', 'А-а, послание Албрека! Очень хорошо. Королевское фармацевтическое общество работает день и ночь, чтобы определить, как же орки Скверны стали орками Скверны. Их предательству нет прощения... Мы должны гарантировать, что сумеем защитить от подобной напасти наших друзей-орков.', 'Добрый день, $N. Как обстоят дела на полуострове Адского Пламени? Надеюсь, все благополучно?', NULL, NULL, 'Послание Албрека (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10836, 'Переполох в крепости Драконьей Пасти', 'Мне необходимо время, чтобы разработать план по спасению моих детей и супруги. И ты обеспечишь мне это время, $gсмертный:смертная:.$B$BОтправляйся в крепость Драконьей Пасти, расположенную на восточном краю полей Крыльев Пустоты, и убей всех орков, которые попадутся тебе на пути. Воцарившийся хаос сорвет все их планы.$B$BБудь $gосторожен:осторожна: – некоторые из моего народа не в себе, их разум подчинен шаманам клана. Единственный выход для них – смерть. Я надеюсь, ты поможешь им обрести ее.', 'Убейте 15 орков из клана Драконьей Пасти для Нельтараку.Засчитывается орк любого ранга.', 'Отличная работа, $N. А я за это время нашел способ освободить удерживаемых в крепости драконов.', NULL, NULL, NULL, 'Орк из клана Драконьей Пасти убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10837, 'На кряж Крыльев Пустоты!', 'Думаю, я смогу зарядить кристаллы лозы Пустоты своей энергией. И тогда силы их хватит на то, чтобы освободить пленных драконов.$B$BОтправляйся на кряж Крыльев Пустоты, – остров у края долины Призрачной Луны, там ты найдешь кристаллы лозы Пустоты, набей ими карманы и возвращайся ко мне.$B$BИ, $N, будь $gосторожен:осторожна:. Остров населяют орки из клана Драконьей Пасти.', 'Соберите для Нельтараку 12 кристаллов лозы Пустоты на кряже Крыльев Пустоты.', '<Нельтараку забирает у вас кристаллы.>$B$BТеперь я подготовлю их для тебя.', 'Где мои кристаллы.', NULL, NULL, 'Кристалл Лозы Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10838, 'Демонический кристалл', 'Демонический кристалл готов к работе. Отнеси его к цитадели Адского Пламени, в яму Адского Пламени, опусти на землю и воззови к нему. Он начнет проникать в цитадель. После того как проникновение завершится, обратись к кристаллу и тщательно запиши все, что он тебе скажет. Запись принеси мне.$B$BСтупай, $N, но только после должной подготовки. цитадель наверняка обнаружит кристалл и пошлет стражей, чтобы его разрушить.', 'Отнесите демонический кристалл в Яму Адского Пламени, подождите, пока произойдет соединение, и примите сообщение.Верните демонический кристалл и его сообщение аптекарю Антонивичу в Траллмар.', 'О, ты принес сообщение! Отлично, эти данные будут бесценны для наших исследований. Аптекари Зелана и Албрек второй раз умрут от зависти.$B$BМожешь гордиться, $N. Твоя сила и храбрость не подлежат ни малейшему сомнению... И служат на благо Орде.', 'Где сообщение? Ты выполнил мое задание?', NULL, NULL, 'Результаты работы демонического кристалла', 'Демонический кристалл (Прилагается)', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10839, 'Гнездовье Скит: Темный камень Терокка', 'Гнездовье Скит находится к северо-западу от каравана и к югу от Шаттрата, в чаще леса. Говорят, что там поселенцы Скеттиса воздвигли темный алтарь для поклонения своему богу. Если мы хотим, чтобы араккоа Скеттиса когда-либо узрели Свет, мы должны уничтожить этот Темный камень Терокка.$B$BВозьми этот жезл Очищения и направь его на Темный камень. Этот жезл благословлен самим А\'далом, и его чистоты должно хватить для того, чтобы изгнать всю скверну из этого алтаря. Ступай, и да озарит свет твой путь.', 'Очистите темный камень Терокка в Гнездовье Скит при помощи Жезла Очищения, после чего вернитесь к Киррику Пробужденному в Караван Беженцев в Костяные Пустоши.', 'Я слышал взрыв, но не ушами, а сердцем.$B$BЕсли священное прикосновение Наару не поможет этим араккоа, то им уже ничто не поможет. Те, кто не встал на путь Света, навечно останутся служителями зла и будут уничтожены.', 'Тьма окружает нас. Что ты можешь рассказать о гнездовье Скит?', NULL, NULL, 'Жезл очищения (Прилагается)', 'Попытайтесь очистить темный камень Терокка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10840, 'Гробница Света', 'На востоке, под обугленными песками, находится Гробница Света – заброшенное место для захоронения мертвых. Я собирался войти туда и изгнать злых духов, но потом на наш караван напали, и теперь мне немного не до того...$B$BЕдинственное, что мне удалось узнать – это то, что там теперь объявилось новое зло – духи Астрала. Они обыскивают мертвые тела и крадут с них украшения и амулеты.$B$BНо пока мой караван в таком состоянии, я мало что могу сделать для гробницы...', 'Отправляйтесь в Гробницу Света и убейте там 10 эфириалов-пустомантов и 10 эфириалов-расхитителей, после чего вернитесь к верховному жрецу Орглуму в Караван беженцев.', 'Здесь, в Запределье, лишь горстка героев способна как-то защитить нас, но вы сумели хорошенько припугнуть врагов, $C! Думаю, эти духи еще долго будут с ужасом вспоминать вас, $N!', NULL, NULL, NULL, 'Эфириал-пустомант убито', 'Эфириал-расхититель убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10841, 'Мстительный предвестник', '[PH] Отправляйтесь в Гробницу Света и активируйте устройство.', '', '', NULL, NULL, NULL, 'Рекомендуемое количество игроков: 3', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10842, 'Мстительные души', 'Гробницу Света захватил Совет Теней, и умершие дренеи превратились в проклятых духов, одержимых яростью и ненавистью ко всему живому.$B$BВойди в гробницу и отыщи этих невинных жертв. Даруй им покой, который они заслужили.', 'Верховный жрец Орглум велит вам отправиться в Гробницу Света и убить 5 мстительных дренеев.', 'Я не могу передать, какое большое дело вы совершили, $N. Вы спасли огромное количество наших собратьев от бесконечной тьмы. Я мало что могу сделать для живых и у меня нет ничего, что стало бы достойной наградой для вас. Возьмите сами то, что вам нужнее.', 'Вы спасли нас всех! Как нам отблагодарить вас?', NULL, NULL, 'Убито мстительных дренеев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10843, 'С незапамятных времен...', 'С незапамятных времен мы воюем с кланом Камнерогов.$B$BНам удалось оттеснить их так, что теперь они едва держатся на заставе Камнерогов. Это назад по той дороге, который ты $gпришел:пришла:, на юго-западной заставе Камнерогов.$B$BПокажи себя, убив их вождя, Гноша Брогната.$B$BПосмотрим по твоим делам с ограми, из какого теста ты $gслеплен:слеплена:.', 'Убейте Гноша Брогната, вождя огров на Заставе Камнерогов.', '<Леорокс меряет вас проницательным взглядом.>$B$BСмерть Гноша Брогната – большое благо для всех Мок\'Натал. И для тебя это благо.$B$BПосмотрим, не сможешь ли ты нам помочь в еще более важном деле.', NULL, NULL, NULL, 'Гнош Брогнат убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10844, 'Лагерь Легиона: Злоба', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10845, 'Убить мать драконов', 'Мои охотники только что вернулись с разведки на Звенящем гребне. Похоже, драконы Пустоты, что заразили тамошние кристаллы, сильно расплодились и того-гляди нам на голову сядут.$B$BРаз уж ты $gпоказал:показала: себя опытным бойцом, посмотрим, хватит ли тебе выдержки для драки со взрослым драконом.$B$BИщи Звенящий гребень на юге, за Склоном Чешуекрылых. Пойди и убей их мать-дракониху, Крыло Ужаса.', 'Убейте Крыло Ужаса. Награда: Пояс из шкуры Крыла Ужаса, Поножи матери драконов, Перчатки из шкуры Пустоты или Нагрудник защитника Пустоты.', 'Нет? Так ты убил Крыло Ужаса? Видать, я ошибался в тебе, $C.$B$BМожет быть и так.$B$BИ все же ты убил предводителей трех сильнейших наших врагов. Этим можно гордиться.$B$BЯ предлагаю тебе знак моей признательности, но не зазнавайся. Ты еще не понимаешь до конца что такое быть Мок\'Натал, так что мы еще можем воспользоваться твоими умениями!', NULL, NULL, NULL, 'Крыло Ужаса убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10846, 'Как понять Мок\'Натал', '<Леорокс смотрит вам в глаза так, что у вас мороз идет по коже.>$B$BТы $gпришел:пришла: к Мок\'Натал, но ты нас не понимаешь. Ты не понимаешь нашей борьбы за выживание.$B$BЕсли ты хочешь понять нас, тебе придется вкусить этой борьбы.$B$BНа юге живут араккоа из племени Вех\'нир. Они поработили группу огров из пещер, известных как участок Трогмы, и их предводитель Вех там живет.$B$BУбей его!', 'Убейте Векха, предводителя араккоа Векх\'нира.', 'Векх\'нир – вовсе не самые страшные наши враги.$B$BНу знаешь ты теперь, как разделаться с птицей-переростком. Истинным воином ты от этого не стал. И до конца нас не поймешь.$B$BНо это только начало.', NULL, NULL, NULL, 'Векх убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10847, 'Глаза Скеттиса', 'С утесов Скеттиса на нас движется неумолимый рок.$B$BМоему народу, араккоа, уготована невыразимо жестокая участь. Мы долгое время использовали те$Nю магию в дурных целях, но благодаря А\'далу я познал свет и глубоко раскаялся.$B$BТерокк наблюдает за своими поселениями из Скеттиса через сферы, на которые наложены темные чары. Украдите эти Глаза из Гнездовья Рескк и Гнездовья Шиенор – это в северном Тероккаре. Я хочу увидеть то же, что видит Терокк, хочу посмотреть через очи Скеттиса.', 'Принесите Око Рескка и Око Шиенор Рилаку Освобожденному в Нижний Город Шаттрата.', 'Ваша храбрость заслуживает похвалы – насколько я знаю, стражи Скеттиса ни за что не расстанутся со своим имуществом добровольно.$B$BНо героические деяния прошлого сейчас почти не имеют значения – важно лишь то, сохранится ли храбрость и дальше, потому что Терокк обратил свой взгляд на юг.$B$BЭти Глаза видят все.', 'Вы снова здесь, $N. Какие новости?', NULL, NULL, 'Око Гнездовья Рескк', 'Око Гнездовья Шиенор', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10848, 'Гнездовье Рейз: неживое зло', 'Гнездовье Рейз – это особо неприятное поселение Скеттиса.$B$BНесмотря на то, что эту деревню уничтожила Аукиндонская катастрофа, Терокк все еще держит в своей власти оставшихся там неупокоенных духов. Тебе нужно отправиться в гнездовье Рейз и истребить это гнусное отродье – их можно найти к западу от Гробницы Тени, на границе Костяных пустошей и леса Тероккар.$B$BЭто будет нашим первым ударом по Терокку и стражам Скеттиса.', 'Убейте 4 духа Когтя Смерти, 4 кричащих духа и 2 духа ворона, после чего вернитесь к Киррику Пробужденному в Караван Беженцев.', 'Эти злобные духи заслужили смерть, ибо они сами были готовы убивать, не задумываясь.$B$BДля тех, кто находится во власти Терокка, спасения нет, но мы по крайней мере можем нанести ему сокрушающий удар во имя Света.', NULL, NULL, NULL, 'Дух Когтя Смерти убито', 'Кричащий дух убито', 'Дух ворона убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10849, 'Поиски Киррика', 'Еще один араккоа отступился от Терокка!$B$BКиррик признал его шарлатаном, а никаким не пророком. Единственное видение, которое явилось Терокку, говорило лишь о злой участи, уготованной тем, кто призовет его.$B$BКиррик храбро увел нас всех из Скеттиса, а после того, как мы прибыли в Шаттрат, он ушел в другие колонии в поисках новых последователей.$B$BВ этом послании написано о том, что увидели Глаза, и нужно непременно рассказать об этом Киррику! Ступай из Шаттрата на юг, к Костяным пустошам, и высматривай караван.', 'Отнесите послание Риллака Киррику Пробужденному в Караван беженцев на Костяных Пустошах.', 'Рилак прислал дурные вести, странник. Взгляни на наш караван и сам поймешь, что лес Тероккар сейчас полон скорби и тьмы.', 'Ты пришел издалека и у тебя есть для меня новости.', NULL, NULL, 'Послание Рилака (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10850, 'Газ хаоса в двигателе', '', '', 'Сквернобот начинает трястись и чихать, по мере того как вы загружаете его неправильным топливом.', NULL, NULL, NULL, 'Конденсированный газ Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10851, 'Тотем врага моего', 'Почитать предков можно достойным образом – и недостойным.$B$BОгры из клана Камнерогов носят с собой тотемы, но не почитают их. Они пытаются использовать тотемы, управлять с их помощью!$B$BМы должны украсть у них эти тотемы, потому как огры их недостойны! Мы найдем им лучшее применение.$B$BОтправляйся на заставу Камнерогов на запад, что прямо у юго-западной части Островерхого гребня. Убей их мистиков и сокрушителей и забери у них тотемы!', 'Добудьте 5 тотемов Камнерогов.', 'Хорошая подборка. Мы сумеем достойно использовать одного-двух.$B$BИ я, кстати, знаю, как это сделать!', 'Ну, побывал на заставе Камнерогов и отобрал у них тотемы?', NULL, NULL, 'Тотем клана Камнерогов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10852, 'Пропавшие друзья', 'Ночью кто-то пришел и очень страшно шумел, мы испугались и бросились врассыпную. Очень страшно было! Даже и не знаю, когда мы поедем дальше.$B$BНекоторые мои друзья до сих пор не вернулись – наверное, эти страшные птицелюди утащили их на северо-запад и заперли в клетках. Было бы здорово, если бы вы нашли их, а то я за них волнуюсь!', 'Найдите 12 друзей Итана в гнездовье Скит и вернитесь к нему в Караван беженцев.', 'Вы нашли всех моих друзей! Теперь мне больше не будет скучно. Спасибо, дядя $N!$B$BНу, а раз мне есть с кем играть, я отдам вам одну из моих игрушек! А то вам скучно, наверное.', 'Мне скучно и поиграть не с кем! Вы нашли моих друзей?', NULL, NULL, 'Дети спасены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10853, 'Призыв духов', 'Духи драконов Пустоты Звенящего гребня жаждут освобождения.$B$BЭти драконы Пустоты не всегда были драконами Пустоты. Прежде они были черными драконами.$B$BНо когда этот мир рухнул, по нему прошла всесокрушающая волна энергии Пустоты, и в качестве побочного эффекта изменила драконьи яйца.$B$BТеперь они – лишь искаженные подобия прежних себя. Мы должны помочь им обрести мир.$B$BСделай это, убив дракона близ тотема созывания духов, затем освободи из тотема его дух.', 'Соберите 8 духов младших драконов Пустоты при помощи тотемов вызова духов.', 'Ты сегодня сделал доброе дело, $C. Теперь освобожденные души драконов воистину воспоют. А та остаточная часть души, которую они оставили после себя – могучее лекарство.$B$BХочу спросить – а не собираешься ли ты на север? Там есть кое-что весьма любопытное для меня, связанное с деятельностью духов Астрала.$B$BЯ чувствую, оттуда будет много лиха.', 'Драконы Звенящего гребня – угроза для нас, но я думаю, что они величественные существа.$B$BИли, по крайней мере, были таковыми. Надеюсь, ты сумеешь спасти их души.$B$BИ если тебе понадобится еще тотемов. У меня найдется несколько штук.', NULL, NULL, 'Дух младшего дракона Пустоты', 'Тотемы вызова духов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10854, 'Силы Нельтараку', 'Забери зачарованный кристалл лозы Пустоты и отправляйся обратно в крепость Драконьей Пасти. Найди там порабощенных драконов и активируй кристалл. Моя сила поможет драконам освободиться от удерживающих их чар. Когда ты увидишь, что дракон освободился, помоги ему справиться с надсмотрщиком, поскольку сам он, скорее всего, будет ослаблен пленом.$B$BОсвободи всех, кого сможешь, и возвращайся ко мне, $N.', 'Освободите для Нельтараку 5 порабощенных драконов Крыльев Пустоты.', '<Нельтараку смеется.>$B$BОрки должно быть были в ужасе, когда их драконы обратились против них. Отличная работа, $N! Наше племя благодарно тебе.', 'Не теряй времени. У нас очень много дел!', NULL, NULL, 'Освободите порабощенных драконов Крыльев Пустоты', 'Колдовской кристалл Лозы Пустоты (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10855, 'Сквернобот – нет, спасибо!', 'Ах да, скверноботы! Несомненно, самые ужасные механические создания Легиона. И не меньше трех этих ходячих кошмаров нацелены на Штормовую Вершину. $B$BК счастью для нас, они еще не активны. Это дает нам возможность справиться с ними путем саботажа, а не грубой силы.$B$BВозьми у ган\'арга на базе Легиона: Забвение конденсированный газ Пустоты и наполни им топливный бак ближайшего сквернобота. Мне кажется, что его двигатель не очень-то хорошо с этим справится.', 'Заберите 5 единиц конденсированного газа Пустоты у ган\'аргов-анжинеров на базе Легиона: Забвение, к северо-западу от Штормовой Вершины, и загрузите их в ближайший бездействующий сквернобот. После завершения задачи возвращайтесь к ловчему Пустоты Наутису.', 'Это превосходные новости, $N. Теперь, когда мы знаем, как справляться с разрушителями, я могу провести саботаж в отношении оставшихся машин.', NULL, NULL, NULL, 'Бездействующий сквернобот уничтожен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10856, 'Наилучшая защита', 'Отважные действия по промышленному саботажу больше не дадут нам ничего, $N. Точно так же, как база Легиона: Забвение служит местом сборки скверноботов, база Легиона: Геенна является полигоном для их армии, где размещена большая часть телепортационных установок Пылающего Легиона. $B$BЯ хочу послать тебя туда, чтобы уменьшить их количество. У них сейчас, должно быть, собрался полный личный состав вестников гнева, и мы не можем этого допустить.', 'Ловчий Пустоты Наутис просит вас убить 12 вестников гнева на базе Легиона: Геенна к северу от Штормовой Вершины.', 'Отличная работа, $N. Продолжай в том же духе, и я замолвлю за тебя слово перед принцем.', 'Как дела? Удалось ли тебе преподать Легиону пару уроков?', NULL, NULL, 'Вестник Зла убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10857, 'Телепортируй это!', 'Может быть, убивать демонов и забавно, но толку от этого мало, пока Легион использует свои телепорты, чтобы заменять тех, кого мы убили, новыми. $B$BК несчастью, у меня под рукой нет достаточно мощной взрывчатки... но она есть у мо\'арга, который присматривает за телепортами. $B$BВозьми этот жезл... я настроил его силу так, чтобы она взаимодействовала с частотой, на которой работает мозг мо\'арга. Возвращайся на базу Легиона: Геенна и используй жезл на любом мо\'арге, которого встретишь. Действие будет недолгим, но ты сможешь использовать их разрушительные заряды, чтобы уничтожить ближайшие телепорты.', 'Ловчий Пустоты Наутис просит вас применить жезл ментального вмешательства против мо\'аргов, находящихся в лагере Легиона: Геенна и использовать их способность взорвать телепорт для того, чтобы уничтожить три телепорта в лагере Легиона.', 'Благодаря твоим деяниям, $N, я могу вздохнуть с облегчением. Это, конечно, лишь словесный оборот.$B$BПолагаю, за это ты хочешь получить какую-нибудь награду.', 'Все сделано как надо? Телепорты закрыты?', NULL, NULL, 'Западный телепорт уничтожен', 'Центральный телепорт уничтожен', 'Восточный телепорт уничтожен', 'Жезл ментального вмешательства (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10858, 'Каринаку', 'Мне стыдно снова просить тебя о помощи. $N, но ты сейчас – единственная надежда всего выводка. Без моей супруги нам грозит вымиранье как виду.$B$BОтправляйся в крепость Драконьей Пасти и найди Каринаку. Мы будем неподалеку, на случай если тебе понадобится помощь.', 'Найдите Каринаку в крепости Драконьей Пасти.', 'Это все цепи, они лишают меня сил. Единственный способ освободиться, это отобрать ключ у Зулухеда и отпереть замок.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10859, 'Собрать шары', 'У духов астрала Разаани есть странные устройства, которые испускают маленькие розовые светящиеся шарики. Чем-то они напоминают мне души.$B$BНе путай их с большими желтыми шарами, которые вылетают из духов Астрала, когда они гибнут, это что-то совсем другое.$B$BХочу я, чтобы ты $gсходил:сходила: на север к лагерю Разаана и $gразбросал:разбросала: там несколько тотемов, которые притянут к себе розовые светящиеся шарики.$B$BЗатем принеси их мне, чтобы я попытался определить. что же это такое на самом деле.', 'Соберите 15 световых сфер братства Разаани при помощи тотема для собирания сфер.', 'Что-то тут не так.$B$BДай мне, пожалуйста, тотем, $N. Я должен посмотреть на эти шары!', 'Удалось собрать необходимое количество световых сфер братства Разаани?', NULL, NULL, 'Собрано световых сфер братства Разаани', 'Тотем для собирания сфер (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10860, 'Лакомства Мок\'Натал', '$gОголодал:Оголодала:, $r? Великий дух помогает тем, кто сам себе помогает. Если хочешь заработать обед, то слушай сюда, потому что Браагор даром ничего не даст, да и такой вкусноты ты у него не получишь!$B$BЯщеры и чешуекрылы Островерхого гребня и Склона Чешуекрылых – все, что нужно для самого лакомого блюда, которое тебе только доведется попробовать! Принеси мне ребрышек ящера и змеиного мяса, и я приготовлю его для тебя.$B$BДаже могу научить, как готовить это блюдо, если быстро обернешься.', 'Добудьте 3 ребра ящера и 3 куска змеиного мяса.', 'Мммм, уже прямо чувствую вкус. Ну, давай побыстрее... Сейчас порежу – и на огонь!$B$BТебе повезло – это блюдо долго хранится! Вот, бери, и полагаю ты еще и рецепты получишь, если будешь пополнять запасы в моем мясном погребе.', 'Еще не все добыл? Говорить не могу – слюнки текут!', NULL, NULL, 'Ребра ящера', 'Змеиное мясо', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10861, 'Гнездовье Литик: превентивный удар', 'К юго-западу отсюда находится поселение араккоа под названием Гнездовье Литик, где прислужники Терокка накладывают злые чары на своих птенцов еще до того, как они вылупятся из яиц, чтобы сразу после рождения они бездумно повиновались Терокку.$B$BОтправляйтесь в Гнездовье Литик и разбейте птичьи яйца до того, как злые чары полностью поглотят их, а если опоздаете, то просто убейте нечестивых птенцов.$B$BИ помните, что ярче всего Свет сияет во тьме.', 'Разбейте проклятые яйца в Гнездовье Литик. Освободите 3 птенцов и убейте 3 злобных птенцов, после чего вернитесь к Киррику Пробужденному в Караван беженцев.', 'Очень неприятно вредить чужим детенышам, однако нельзя пускать такую угрозу на самотек. Вы хорошо поработали. Да пребудет в вашем сердце милость А\'дала.', 'Вы выполнили то, что обещали? Уничтожьте зло, пока не стало слишком поздно!', NULL, NULL, 'Освобождено птенцов', 'Злобный птенец убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10862, 'Сдаться Орде', 'Эти мерзкие араккоа нападают на нас каждый день! Они устраивают засады на наших охотников, а иногда даже проникают за стены! Мы, конечно, убиваем их при любой возможности, но они владеют очень сильной магией, которая часто помогает им спастись.$B$BМне сказали, что есть араккоа, которые считаются союзниками Орды, и якобы они живут в Шаттрате, к северо-западу отсюда. Их предводителя зовут Рилак Освобожденный, найдите его в Нижнем городе и убедите капитулировать.', 'Найдите Рилака Освобожденного в Нижнем Городе Шаттрата и потребуйте, чтобы он и его народ сдались Орде, как велел вам Рокаг.', 'Ваши люди сердятся, но я мало что могу сделать. Некоторые из нас преклоняются перед силой наару, и благодаря ей мы изменились навеки. Однако те из нас, кто до сих пор живет на воле, остались такими же, как прежде.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10863, 'Тайны араккоа', 'Здесь, на границе, нам каждый день приходится иметь дело с араккоа – они постоянно нападают на нас, грабят караваны с провизией, убивают наших разведчиков...$B$BИ, тем не менее, нам на удивление мало известно об этих загадочных существах. Я слышала, что к северо-западу отсюда, в Шаттрате, есть араккоа, которые не проявляют никакой враждебности. Возможно, они согласятся поделиться с нами секретами своей расы.$B$BИх предводителя зовут Рилак Освобожденный, он живет в северной части Нижнего города.', 'Найдите Рилака Освобожденного в Нижнем Городе Шаттрата и попытайтесь выведать у него несколько секретов араккоа по просьбе леди Дены Кеннеди.', 'Хорошо, что вы нашли меня. Мне многое надо вам показать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10864, 'Урожай душ', 'У меня есть одно устройство, демонический кристалл, он способен анализировать магию Скверны. Я дам его тебе, но сначала... Кристалл нужно умиротворить. Внутри него находится очень умная сущность, но с очень эээ специфическими потребностями.$B$BЧтобы умиротворить кристалл надо убивать орков. Лучше всего подходят орки из клана Изувеченной Длани, – их души кристалл забирает с особой радостью.$B$BВозвращайся ко мне, когда соберешь урожай душ. Орков можно найти и на севере, и на юге... рядом с цитаделью Адского Пламени они просто кишат.', 'Убейте 20 орков из клана Изувеченной Длани, затем возвращайтесь к аптекарю Антонивичу в Траллмар.', 'Неплохо, $N. Эти души обременены грузом многих смертей... А демонический кристалл готов к работе.$B$BБудем надеяться, что ты успешно пройдешь это испытание...', NULL, NULL, NULL, 'Убито орков из клана Изувеченной Длани', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10865, 'Доложить Леороксу!', 'Быстрее, надо скорее доложить Леороксу о том, что случилось в лагере Разаана!$B$BЭти шарики были сделаны из душ, причем некоторые – из душ Мок\'Натал!', 'Расскажите Леороксу о том, что затеяли духи астрала Разаани. Его можно найти в деревне Мок\'Натал в Острогорье.', 'Да что ты говоришь! Разве возможно такое? Да что я говорю! Конечно, возможно, если уж призыватель духов так говорит!$B$BПомнишь, я говорил, что нам еще может понадобиться твоя помощь? Похоже, этот час настал.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10866, 'Зулухед Измученный', 'Он внутри моих мыслей. Хочет, чтобы я сдалась... Подчинить меня своей воле.$B$BИ это будет его гибелью. Я вызову его. Я скажу ему, что сделаю, как он просит. Когда он появится, убей его и возьми ключ!$B$BЗнай: Зулухед – древний орк, и силы его, несомненно, полученные от Иллидана, неизвестны. Ты рискуешь жизнью, выполняя для меня это задание, поэтому я спрашиваю, действительно ли ты готов на такую жертву?', 'Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку.', 'Свободна! Ты спас нас, $N!', '<Каринаку стонет.>', NULL, NULL, 'Каринаку свободна', 'Зулухед Измученный убито', 'Рекомендуемое количество игроков: 5', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10867, 'Ответ будет только один', 'На это... ИЗДЕВАТЕЛЬСТВО над душами наших предков ответ может быть только один!$B$B$N, если ты согласишься помочь нам вернуть души наших почитаемых ушедших туда, где им должно пребывать, возвращайся в лагерь Разаана.$B$BСтупай туда и убивай Разаани, пока их вождь, принц Разаан не высунет свою трусливую морду! Убей его, отними души и передай их вызывателю духов Догару!', 'Добудьте Собрание душ. Награда: Мантия клана Мок\'Натал, Маска призывателя духов, Кюлоты героя клана Мок\'Натал или Пояс спасителя душ.', 'Славно, что эти мерзкие духи Астрала и их вождь мертвы. тысяча проклятий на головы их собратьев!$B$BЯ награжу тебя за твои подвиги от имени всех Мок\'Натал, $N! Воистину, ты теперь один из наших героев.$B$BДавай же выпустим души наших предков и предадим их очистительному пламени.', 'Уже? Души наших предков освобождены от этих злобных духов Астрала?', NULL, NULL, 'Коллекция Душ', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10868, 'Тропа войны араккоа', 'Араккоа снова напали на нас, на этот раз ночью, и потом скрылись с помощью своей черной магии, прежде чем мы успели собрать все наши силы. Они спасают своих воинов от верной смерти с помощью кругов призыва, но если мы нападем на их дома, им не скрыться. Гнездовье Рескк и Гнездовье Шиенор находятся к северу и северо-востоку отсюда.$B$BНайдите эти гнездовья араккоа и убейте столько существ, сколько сможете.', 'Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к советнице Файле в форт Камнеломов.', 'Прекрасно, $C. Вы преподали араккоа хороший урок, теперь они станут бояться Орды.', NULL, NULL, NULL, 'Шиенорский когант убито', 'Шиенорский колдун убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10869, 'Уменьшить стаю', 'Араккоа снова напали на нас, на этот раз ночью, и потом скрылись с помощью своей черной магии, прежде чем мы успели собрать все наши силы. Они спасают своих воинов от верной смерти с помощью кругов призыва, но если мы нападем на их дома, им не скрыться. Гнездовье Рескк и Гнездовье Шиенор находятся к северу и северо-западу отсюда.$B$BНайдите эти гнездовья араккоа и убейте столько существ, сколько сможете.', 'Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к лейтенанту Булыжному Молоту в бастион Аллерии.', 'Прекрасно, $C. Вы преподали араккоа хороший урок, теперь они станут бояться Альянса.', NULL, NULL, NULL, 'Шиенорский когант убито', 'Шиенорский колдун убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10870, 'Союзник Крыльев Пустоты', 'Позволь мне вернуть тебя к Морденаю. Я уверен, он не откажется снова тебя повидать', 'Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты.', 'Ты доказал, что являешься настоящим другом Крыльям Пустоты. Наша мать свободна, мои братья и сестры спасены.$B$BВозможно когда-нибудь нам еще потребуется твоя помощь, но знай, что когда бы ты ни пришел, тебя встретят с распростертыми объятьями, брат!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10871, 'Союзник Крыльев Пустоты', 'Позволь мне вернуть тебя к Морденаю. Я уверен, он не откажется снова тебя повидать', 'Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты.', 'Ты доказал, что являешься настоящим другом Крыльям Пустоты. Наша мать свободна, мои братья и сестры спасены.$B$BВозможно когда-нибудь нам еще потребуется твоя помощь, но знай, что когда бы ты ни пришел, тебя встретят с распростертыми объятьями, брат!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10872, 'Зулухед Измученный', 'Он внутри моих мыслей. Хочет, чтобы я сдалась... Подчинить меня своей воле.$B$BИ это будет его гибелью. Я вызову его. Я скажу ему, что сделаю, как он просит. Когда он появится, убей его и возьми ключ!$B$BЗнай: Зулухед – древний орк, и силы его, несомненно, полученные от Иллидана, неизвестны. Ты рискуешь жизнью, выполняя для меня это задание, поэтому я спрашиваю, действительно ли ты готов на такую жертву?', 'Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку.', 'Свободна! Ты спас нас, $N!', NULL, NULL, NULL, 'Каринаку свободна', 'Зулухед Измученный убито', 'Рекомендуемое количество игроков: 5', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10873, 'Захваченные в ночи', 'На нашу маленькую заставу постоянно нападают. Вот, например, несколько дней назад напали пауки с гряды Пустопутов – это на юго-восточном краю Костяных пустошей. Пауки отравили много наших людей, опутали их своими тенетами и уволокли за собой. Несколько воинов похватали оружие и пустились в погоню, не подготовившись как следует...$B$BС тех пор мы их и не видели. Однако мы надеемся, что они все еще живы. Как знать, может, пауки просто держат их в плену? Но людей у нас осталось совсем мало... Быть может, ты поищешь наших пропавших воинов?', 'Пойдите на Гряду Пустопутов и освободите там 6 опутанных воинов Ша\'тар, после чего вернитесь к разведчику Наврину на заставу Ша\'тар.', 'Вы спасли очень многих, я уж и не думал, что мы когда-нибудь увидим их снова! Мы премного обязаны вам, $N.', NULL, NULL, NULL, 'Освобождено воинов Ша\'тар', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10874, 'Гнездовье Шалас: сигнальные огни', 'Обитель Терокка, Скеттис, возвышается над Костяными пустошами на востоке. У основания Скеттиса находится гнездовье Шалас, самое примечательное поселение Терокка. Именно из укреплений гнездовья Шалас боевые маги Терокка идут войной против Света.$B$BЗлодеи из гнездовья Шалас общаются со своим повелителем посредством сложной системы сигнальных огней. Тебе, $r, нужно будет отправиться на восток и погасить эти огни. Как только гнездовье Шалас погрузится в молчание, мы сможем спланировать падение Скеттиса.$B$BНо не будем забегать вперед.', 'Потушите четыре сигнальных огня в Гнездовье Шалас по просьбе Киррика Пробужденного из Каравана Беженцев.', 'Мы видели, как оттуда поднимался столб дыма. Вы очень смелы, $C.', 'Гнездовье Шалас должна умолкнуть!', NULL, NULL, 'Сапфирный огонь потушен', 'Изумрудный огонь потушен', 'Фиолетовый огонь потушен', 'Огонь Кровавого камня потушен');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10875, 'Донесение Назгрелу', '$N, пока ты $gсовершал:совершала: набег с демоническим кристаллом, я отправил донесение о твоих подвигах в сражениях с орками Скверны. Назгрел, наш великий вождь в Траллмаре, хочет поговорить с тобой. Надеюсь, он приготовил для тебя особое, смертоносное задание...', 'Поговорите с Назгрелом в Траллмаре на Полуострове Адского Пламени.', 'Я рад слышать о твоих победах над орками Скверны, $N. Аптекари потратили много времени и ресурсов, изучая причину их изменения, но все равно нам жизненно важна любая информация. Мои орки горят желанием как следует проучить этих предателей!$B$BСлушай внимательно, я расскажу тебе о новом задании...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10876, 'Вступить в цитадель', 'Командир соединения Горакс сам тренирует капитанов клана Изувеченной Длани, острее бритвы оттачивая их умения. Его смерть станет непоправимой утратой для орков Скверны, $N, и именно поэтому мы должны убить его.$B$BНо это еще не все.$B$BВозьми этот стяг. Положи его на труп Горакса. Если в начальнике Горакса, подручном Каргата, осталась хотя бы капля чистой орочьей крови, он ответит на твой вызов.$B$BМне нужна его голова, голова прислужника Каргата.', 'Убейте командира соединения Горакса, положите на его труп Вызов Орды, убейте прислужника Каргата и принесите голову прислужника Каргата Назгрелу в Траллмар.', 'Ты совершил великий подвиг, $N. Орки Скверны - позор для каждого настоящего орка. У нас есть всего лишь один страх - страх вновь попасть в сети демонической скверны. Война с орками Скверны - это не просто сражение с ненавистным врагом. Это еще и битва с темной стороной нашего \"я\".$B$BТвой пример вселяет в нас надежду, что мы выиграем эту войну.', 'Ты встретился c подручным Каргата?', NULL, NULL, 'Голова подручного Каргата', 'Вызов Орды', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10877, 'Реликвия Ужаса', 'Когда-то давно из Аукиндона вышел караван, задачей которого было забрать реликвию Ужаса из древних гробниц под некрополем. Им не удалось этого сделать, и причиной тому была сама реликвия – она несет зло и притягивает его, стоит только ее коснуться. Их караван был уничтожен где-то к востоку отсюда.$B$BС помощью этого артефакта можно уничтожить Жутуса Проклятого – существо, летающее над Костяными пустошами. Если хочешь, помоги мне, но помни, что ты подвергнешь риску и себя, и свою душу.', 'Отыщите Реликвию Ужаса к востоку от Брошенного каравана, после чего вернитесь к Оакуну.', 'Поверить не могу, что вам это удалось. Реликвия Ужаса еще сильнее, чем я думал. Только истинный герой мог выжить в этом путешествии и вернуться назад, неся с собой эту проклятую вещь.', 'Вы нашли Реликвию Ужаса? Она нам необходима.', NULL, NULL, 'Реликвия Ужаса', 'Ключ от сундука древнего каравана (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10878, 'До наступления тьмы', 'Когда на наш караван напали сектанты Совета Теней, разведчики помчались в Шаттрат за помощью. Стражи думают, что теперь мы в безопасности, однако они недооценивают этих безумцев.$B$BЛично мне бы не хотелось, чтобы какой-нибудь фанатик ночью перерезал мне горло. Прошу, сделайте нам одолжение – разберитесь с ними, пока они не добрались до нас.$B$BСлужители культа расположились к югу отсюда, у северного входа в Аукиндон.', 'Убейте 8 кабалистов-рыскателей, 4 кабалистов-чаропрядов и 2 кабалистов-посвященных по просьбе Мекеды из Каравана Беженцев.', 'Спасибо, $N! Теперь Совет Теней немного поутихнет, и я смогу спокойно вздохнуть.$B$BОни трусы и убийцы, и вы поступили очень храбро, разделавшись с ними.', NULL, NULL, NULL, 'Кабалист-застрельщик убито', 'Кабалист-чаропряд убито', 'Кабалист-посвященный убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10879, 'Нападение Скеттиса', 'Скеттис пошел на нас войной! Вы собрали народ для защиты Шаттрата?$B$BОтразите нападение!', 'Отбейте атаку, а потом поговорите с Рилаком.', 'Ты отлично сражался, $C, и тем самым доказал, что являешься истинным защитником Света. Да пребудет с тобой благословение А\'дала даже в самый тяжелый час.$B$BНо нельзя забывать и о будущем – из Скеттиса надвигается тьма, Терокк, без сомнения, готовится сделать следующий шаг. Пока что Шаттрат в безопасности, но кто знает, какие беды обрушатся на нас завтра?', 'Некогда болтать, $N! На нас напали! Отрази нападение!', NULL, NULL, 'Атака отбита', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10880, 'Распоряжения заговорщиков', 'На этом письме стоит темная печать, и хотя язык кажется знакомым, слова, похоже, зашифрованы.$B$BВозможно, кто-нибудь в Караване беженцев сумеет это расшифровать.', 'Принесите кабалистические приказы Мекеде в караван беженцев в Костяных пустошах.', 'Ах да... Это написано основным теневым шифром. Я не очень хорошо его знаю, но это перевести смогу.$B$BЧему только не научишься, живя среди изгнанников и беженцев в Нижнем городе...', 'Вы хотите мне что-то показать, $N?', NULL, NULL, 'Распоряжения заговорщиков (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10881, 'Гробница Тени', 'Многие считают, что именно Совет Теней произвел тот взрыв, который разорвал Аукиндон на части. Говорят, они разбудили в его глубинах какое-то древнее зло.$B$BЕсли это так, то нужно обратить это зло против них. Судя по этим бумагам, часть Совета Теней бежит из Аукиндона, а в Гробнице Тени они хранят могущественные артефакты оттуда.$B$BСреди этих артефактов находятся три священные реликвии, принадлежавшие патриархам Арунену, К\'алену и Аталору. Я прошу вас вернуть их.', 'Войдите в Гробницу Тени, что к западу от Каравана беженцев и найдите там пелерину Арунена, молот К\'алена и свиток Аталора, после чего вернитесь к Мекеде в Караван беженцев.', 'Даже если Свет забыл обо мне, я о нем не забыл! Когда-то эти реликвии были священными для моего народа.$B$BЯ не могу даже представить того, что может произойти, попади они в руки Совета Теней!', 'Вы принесли реликвии, $N? Нельзя, чтобы Совет Теней использовал их в дурных целях.', NULL, NULL, 'Пелерина Арунена', 'Молот К\'алена', 'Свиток Аталора', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10882, 'Вестник Рока', '$gВ голосе А\'дала слышатся негармоничные ноты.>$B$BПринцу Кель\'тасу следовало тщательнее выбирать тюремщика: все, кто был заперт в Аркатраце, выбираются наружу.$B$BСреди них есть один служитель Древних богов – предвестник Скайрисс, который стремится помочь своему хозяину завоевать все миры.$B$B$N, нельзя дать ему сбежать. Вернись в Крепость Бурь, проберись в Аркатрац и убей предвестника Скайрисса, пока еще не поздно!', 'Отправьтесь в спутник Крепости Бурь Аркатрац и убейте там предвестника Скайрисса, после чего вернитесь к А\'далу на террасу Света в Шаттрат.', '*Хрустальный мелодичный голос А\'дала звучит спокойнее, чем при ваших прошлых разговорах.*$B$BВы снова проявили недюжинную смелость. Если бы предвестник Скайрисс освободился, то унес бы тысячи жизней, как и другой слуга Древних Богов - Скерам, в вашем мире Азерота.$B$BТо, что я предложу вам взамен, может показаться несравнимой малостью, но помните, что вместе с этим вы получаете вечную благодарность Ша\'тар.', NULL, NULL, NULL, 'Предвестник Скайрисс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10883, 'Ключ Урагана', 'Ты $gдоказал:доказала:, что $gспособен:способна: на многое, $N. Важнейший из твоих подвигов – открытие Кода Проклятия и планов Кель\'таса. Если Кель\'тас успеет воспользоваться Кодом, от этого мира совсем ничего не останется.$B$BА\'дал считает, что Кель\'таса необходимо остановить, и потому он ищет искателей приключений, готовых пройти наши испытания. Те, кто успешно их пройдет, заслужат благосклонность наару.$B$B<Кадгар кивает.>$B$BА\'дал ждет тебя...', 'Поговорите с А\'далом в Шаттрате.', 'Крепость Бурь – творение наару, смертный. Лишь мы можем дать доступ к нашему кораблю. Нам самим казалось, что возвращаться туда незачем. Быть может, смертная раса могла бы гордиться этим, но наару не понимают подобных чувств.$B$BМы возвращаемся туда, потому что иного выхода нет. Мы не позволим Кель\'тасу произнести слова проклятья.$B$BСейчас путь открыт, но лишь глупец может отправиться внутрь, не убедившись в собственных силах. Не стоит недооценивать значение наших испытаний.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10884, 'Испытание наару: милосердие', 'Прежде чем наару признают тебя $gдостойным:достойной:, тебе предстоит пройти четыре испытания.$B$BВ Разрушенных залах цитадели Адского Пламени заточены трое из вашего племени. Их держит там безжалостный Каргат Острорук. Он хочет казнить их в знак своего могущества. Спаси этих несчастных, пока их не постиг столь печальный конец. В доказательство принеси мне неиспользованный топор палача. Пусть на лезвии не будет ни капли крови!', 'А\'дал из Шаттрата просит добыть неиспользованный топор палача из Разрушенных залов цитадели Адского Пламени.Это задание выполняется только в героическом режиме.', 'Молодец, $N. Ты прошел испытание милосердием.', '<А\'дал приветствует вас.>', NULL, NULL, 'Неиспользованный топор палача', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10885, 'Испытание наару: сила', 'Прежде чем наару признают тебя $gдостойным:достойной:, тебе предстоит пройти четыре испытания.$B$BИспытание силы делится на два этапа. Сначала уничтожь главу Парового подземелья Кривого Клыка, полководца Калитреша, и принеси мне его трезубец. Потом убей пришельца из иных миров, Бормотуна, в Темном лабиринте Аукиндона, и принеси мне его сущность.$B$BЕсли ты справишься с этим заданием, я сочту, что ты $gпрошел:прошла: испытание силой.', 'А\'дал из Шаттрата просит добыть трезубец Калитреша и сущность Бормотуна.Это задание выполняется только в героическом режиме.', 'Молодец, $N. Ты прошел испытание силой.', '<А\'дал приветствует вас.>', NULL, NULL, 'Трезубец Калитреша', 'Сущность Бормотуна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10886, 'Испытание наару: упорство', 'Прежде чем наару признают тебя $gдостойным:достойной:, тебе предстоит пройти четыре испытания.$B$BМного опасных тварей встретилось нам в пути. Некоторых из них мы посадили в заточение и поместили в то, что ныне именуется Аркатрацем Крепости Бурь.$B$BВпрочем, есть там один пленник, жертва обстоятельств. Он полез, куда его не просили.$B$BСтупай в Аркатрац и найди там гнома, Милхауса Манашторма. Позаботься, чтобы он выжил.', 'А\'дал из Шаттрата просит спасти Милхауса Манашторма из Аркатраца, что в Крепости Бурь.Это задание выполняется только в героическом режиме.', 'Молодец, $N. Ты прошел испытание упорством.', NULL, NULL, NULL, 'Милхаус Манашторм спасен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10887, 'Побег из гробницы', 'Благодарю вас за помощь, $N. Я уж было попрощался с жизнью...$B$BДавайте выбираться отсюда, пока не прибежали другие служители культа.', 'Помогите Акуно добраться до Каравана беженцев, после чего поговорите с Мекедой.', 'Вы спасли Акуно, моего доброго друга, и я бесконечно обязан вам, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10888, 'Испытание наару: Магтеридон', 'Прежде чем наару признают тебя $gдостойным:достойной:, тебе предстоит пройти четыре испытания.$B$BОсталось лишь одно препятствие, $gсмертный:смертная:. Собери армию побольше и отправляйся в логово Магтеридона в глубины цитадели Адского Пламени. Пробейся в центральный чертог и убей гнусного сеятеля скверны!', 'По заданию А\'дала из Шаттрата убейте Магтеридона.', 'Ты сумел доказать нам свое могущество. Наару согласны...', NULL, NULL, NULL, 'Магтеридон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10889, 'Обратно в Шаттрат', 'Вы действовали очень храбро, но ответ разъяренного Терокка не заставит себя ждать.$B$BПоспешите в Шаттрат, расскажите обо всем Рилаку!', 'Доберитесь до Шаттрата и поговорите там с Рилаком Освобожденным в Нижнем Городе.', 'В Скеттисе собирают все силы, Шаттрат в опасности! Терокк, разумеется, хочет отомстить нам.$B$BСкорее, соберите группу помощников и идите к защитнику Грашне – скажите ему, что вы готовы защищать город от нападения!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10891, 'Имперские латы', 'Есть в Прибамбасске дворф по имени Деротайн Грязеглот, который научит тебя ковать имперские латы. И всего-то надо добраться до пустыни Танарис и найти его там. Ну, как?', 'Поговорите с Деротайном Грязеглотом в Прибамбасске, что в Танарисе.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10892, 'Имперские латы', 'Есть в Прибамбасске дворф по имени Деротайн Грязеглот, который научит тебя ковать имперские латы. И всего-то надо добраться до пустыни Танарис и найти его там. Ну, как?', 'Поговорите с Деротайном Грязеглотом в Прибамбасске, что в Танарисе.', 'Делать имперские латы? Научу, конечно! Только это обойдется тебе в некоторую сумму... в виде ториевых слитков!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10893, 'За всем стоит Длиннохвостка', 'Когда служители культа Крыла Тьмы заполоняют туннель, нам приходится туго. Короче, их больше.$B$BИ хотя нам удается не подпускать их слишком близко к выходу, факт остается фактом – будут сильно напирать, нас опрокинут. $B$BНужно, чтобы кто-то зашел с другого конца туннеля и прикончил их предводительницу, Драаку Длиннохвостку. Хочешь развлечься?', 'Устраните Драаку Длиннохвостку, предводительницу служителей культа Змея в туннеле Драконьего черепа.', 'Теперь, когда Драаку можно сбросить со счетов, мы воспользуемся ситуацией. Сейчас они передерутся за власть, и нам станет полегче.$B$BРазве только инспектор, упомянутый в той записке, что ты мне доставил не займет ее место.$B$BМожет, ты сумеешь этому помешать!', 'Она мертва?$B$B$N, если мы хотим устоять, то нам надо внести смятение в их ряды - убей Драаку Длиннохвостку!', NULL, NULL, 'Драака Длиннохвостка убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10894, 'Страж Драконьего черепа', 'Хмм, прямо не знаю, что и делать. Я не великий стратег.$B$BДозорный Лунный Сумрак разберется. Он возглавляет нашу оборону у тоннеля Драконьего черепа на западе в конце моста Драконьего черепа. Мы держим там отряд на случай, если сектанты что учудить пожелают.$B$BПрошу, отнеси ему эту записку как можно скорее.', 'Передайте записку о встрече дозорному Лунному Сумраку у входа в туннель Драконьего черепа в Острогорье.', 'Я так и думал, и это весть недобрая!$B$BЯ знаю, как тебе можно помочь, но сначала ты нам помоги. $B$BУслуга за услугу.', 'Чем могу помочь? У тебя новости из Вечной рощи?', NULL, NULL, 'Записка о встрече (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10895, 'Сжечь Зет\'Гор!', 'Пришло время напасть на Зет\'Гор с воздуха! Наездники на грифонах готовы к вылету, $N. Единственное, что нужно, это чтобы кто-нибудь навел их на цель с земли. Примешь участие в секретной операции?$B$BДоставь эти дымовые маяки в Зет\'Гор, в крепость клана Кровавой Глазницы на западе. В крепости четыре сторожевые башни: одна у северной стены, одна у южной, одна рядом с кузней, и последняя у предгорья. Установи маяки у подножия каждой башни, чтобы мы знали, куда сбрасывать бомбы!', 'Установите дымовые маяки у каждой из башен Зет\'Гора и возвращайтесь к командиру звена Даби\'ри в лагерь экспедиции.', 'Даже отсюда я вижу дым и пламя! Превосходно, $N! Наши наездники на грифонах будут от души тебе благодарны. Сделанная тобой работа требовала изрядного мужества...', 'Время не ждет, $N. Сторожевые башни должны быть разрушены!', NULL, NULL, 'Северная башня отмечена', 'Южная башня отмечена', 'Башня у кузницы отмечена', 'Башня у подножия отмечена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10896, 'Зараженные защитники', 'Деревья этой земли пожирает сила, вырвавшаяся из Аукиндона. Сами видите, во что превратила землю эта темная магия. Уцелевшие деревья заражены древесными клещами, которые точат их древесину под корой.$B$BБольше всего этих клещей живет в гниющих лесогневах и зараженных корнеходах, эти существа - настоящие рассадники паразитов. Их можно найти на краю леса к востоку отсюда: сначала убейте носителей, а потом паразитов, которые населяют их.', 'Убейте 25 лесных клещей и вернитесь к Лакотаю в Караван беженцев. Клещи живут в телах гниющих лесных гневней и зараженных корнеходов.', 'Вы очень помогли лесу Тероккар, $N. Самая большая колония клещей уничтожена, так что, возможно, нам еще удастся исцелить эту землю.', 'Вы убили самых опасных паразитов?', NULL, NULL, 'Древесный клещ убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10897, 'Мастер зелий', 'Как вам известно, растения обладают свойствами, которые позволяют алхимикам возвращать другим существам силу и энергию с помощью зелий.$B$BЗнакомство с растениями Запределья позволяет мне учить алхимиков извлекать из растений все, что они могут дать. Если ты хочешь расширить свои познания в области зелий, я готова тебя этому научить, но прежде попрошу тебя об одной услуге.$B$BХодят слухи, что старший ботаник Фрейвинн из Крепости Бурь написал подробное руководство по ботанике. Принеси его мне вместе с образцами твоих работ, и я поделюсь с тобой теми знаниями, которых ты ищешь.', 'Отправляйтесь в Ботанику в Крепости Бурь и добудьте у старшего ботаника Фрейвинна \"Полевой справочник ботаника\". Принесите его Лоранне Тар\'велл вместе с 5 отменными лечебными зельями, 5 отменными зельями маны и 5 большими зельями спокойного сна.<ВНИМАНИЕ!> Вы можете избрать только одну алхимическую специальность!', 'Великолепно! Я вижу, вы жаждете знаний. Что ж, приступим к обучению. Я научу вас, как воспользоваться всеми возможными свойствами растений, которые вы применяете в своих алхимических зельях.$B$BВы обнаружите, что от трав можно добиться куда большего, чем обычно, если точно знать, что делаешь. Иногда у вас будут получаться целых два зелья из того сырья, из которого вы намеревались изготовить только одно...', 'Тверда ли ты в своем решении, $N? Если ты изберешь своей специальностью зелья, то уже не сможешь специализироваться в алхимии ни на чем другом!', NULL, NULL, 'Полевой справочник ботаника', 'Гигантский флакон с лечебным зельем', 'Гигантский флакон с зельем маны', 'Большое зелье спокойного сна');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10898, 'Небокрыл', 'Небокрыл летает вокруг вас.$B$BУ вас такое чувство, будто он хочет, чтобы вы последовали за ним.', 'Проводите Небокрыла и вернитесь к Рилаку Освобожденному в Шаттрат.', 'Увы, на бедном Небокрыле лежало проклятие Луанги Пленителя!$B$BНебокрыл отправился в завесу Шалас, чтобы наставить других на путь Света, но в такой опасной близости от Скеттиса к его действиям отнеслись более чем жестко.$B$BЛуанга когда-то был одним из самых грозных агентов Терокка. Ты правильно поступил, освободив Небокрыла! Благодарю тебя.', NULL, NULL, NULL, 'Сопровождение Небокрыла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10899, 'Мастер трансмутации', 'Любой алхимик скажет тебе, что материя податлива, что любую субстанцию можно трансформировать в другую - но ничто на самом деле не создается и не уничтожается.$B$BИстинный мастер трансмутации может научить, как преодолевать это ограничение - и я могу рассказать тебе, как достигнуть этого мастерства!$B$BБудучи перспективным трансмутатором, ты, несомненно, знаешь об изначальной мощи - сочетании материального представления всех изначальных сил. Предъяви мне доказательство своих трансмутационных способностей, и я поделюсь с тобой моими знаниями.', 'Заревхи, находящийся Штормовой Вершине в Пустоверти просит вас принести ему 4 единицы изначальной мощи.ВНИМАНИЕ! Вы можете выбрать только одну алхимическую специализацию.', 'Превосходная работа, $N! Трансмутация выполнена во всех отношениях идеально!$B$BТеперь я научу тебя тому, как процесс алхимической трансмутации может создать материю буквально из ничего! Найди хорошее применения своим знаниям, мастер-трансмаутатор.$B$BТеперь прошу меня извинить, я поищу покупателя, заинтересованного в изначальной мощи.', 'Ты точно желаешь стать мастером трансмутации? Если выберешь эту отрасль, то не сможешь специализироваться на зельях или эликсирах.', NULL, NULL, 'Изначальная мощь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10900, 'Медальон Вайш', '', '', 'Убить! Уничтожить! Более они ничего не заслуживают! НИЧЕГО! Они должны заплатить за содеянное! За все, что они продолжают творить! Я убил бы Вайш собственными руками, если бы только мог освободиться от оков! А может быть, ты хочешь послужить Нептулону? Уверен, ты жаждешь ее смерти не меньше меня, мягкотелый! Поможешь мне создать священную дубину и освободиться от оков?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10901, 'Дубина Кардеша', 'Для создания оружия мне необходимы печати стихий. Принеси мне их!$B$BПечать земли ты найдешь в логове Груула Драконобоя в Острогорье.$B$BПечать огня – это сердце существа, именуемого Ночной Погибелью. Это легендарное чудовище по слухам обитает в священных залах пророка Медива.$B$BПоторопись!', 'Принесите печати земли и огня Скартису Еретику в Узилище (героический уровень сложности) в резервуар Кривого Клыка.', 'Наконец-то! $B$BМои оковы разбиты, и скоро эта дубина обрушится на голову проклятой морской ведьмы и повергнет ее обратно в ледяные глубины...', 'Когда я воссоздам дубину, я разобью свои оковы и отправлюсь в Змеиное святилище свершить возмездие над Вайш и ее прихвостнями!', NULL, NULL, 'Печать земли', 'Печать огня', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10902, 'Мастер эликсиров', 'Я посвятил всю свою жизнь совершенствованию эликсиров, но, несмотря на все мои успехи, так и не сумел приготовить эликсира вечной жизни.$B$BНо, кажется, понял, какого реагента мне не хватает. Говорят, в Азероте есть место под названием Пещеры Времени - туда проникают существа, способные создавать временные разломы.$B$BВ разломах конденсируется энергия и выпадает в форме кристаллов - так называемых \"сутей Бесконечности\". Принесите мне их, а также не забудьте несколько образцов ваших работ, - и я научу вас всему, что знаю сам.', 'Отправляйтесь в Черные топи в Пещерах времени и добудьте 10 кристаллов сути бесконечности с повелителей и хранительниц временных разломов. Затем отнесите кристаллы, 5 хороших эликсиров защиты, 5 эликсиров власти и 5 хороших эликсиров ловкости Лорокиму в Нижний город Шаттрата.ВНИМАНИЕ! Вы можете специализироваться только на одном виде алхимии.', 'У вас получаются отличные эликсиры, если, конечно, эти слова что-то значат для вас. Из вас выйдет отличный ученик.$B$BЭтих ингредиентов мне хватит для того, чтобы вывести новую формулу, которая прославит меня как величайшего алхимика!$B$BА теперь, если вы готовы учиться, я готов вас учить.', 'Ну как? Принесли то, что я просил?', NULL, NULL, 'Суть Бесконечности', 'Большой эликсир защиты', 'Эликсир власти', 'Большой эликсир ловкости');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10903, 'Возвращение в Оплот Чести', '$N, пока ты $gбыл:была: на задании в Зет\'Горе, я получил известия о моем командире, полковнике Джулсе. Во время сражения у форта Горгаза его поразила демоническая порча, и сейчас он находится в крайне тяжелом состоянии.$B$BВ боях с орками Скверны тебе нет равных, но силен ли твой дух так же, как твоя плоть?$B$BПожалуйста, вернись в Оплот Чести и поговори с Клату. Ты отыщешь его в таверне Оплота Чести, на верхнем этаже.', 'Поговорите с ассистентом Клату. Его можно найти в таверне Оплота Чести.', 'Да, это так. За последние несколько дней состояние полковника Джулса снова ухудшилось. Анахорет Берада день и ночь возносит за него молитвы. Будем надеяться, что полковник все-таки поправится.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10904, 'Боеприпасы Скверны', 'Мы должны отрезать Пылающему Легиону доступ к Вратам Смерти, но сначала тебе придется разрушить два их портала!$B$BПроблема в том, что мы даже поцарапать такие штуки не можем, так что придется тебе использовать против них их собственное оружие.$B$BБойцы, стражи, старшие кузнецы и техники кузницы смерти могут подносить снаряды для пушек Скверны.$B$BОбычно это на них не влияет, но если ты сумеешь принести мне ядер их пушек, я наполню их неукротимым гневом природы!', 'Соберите 5 ядер пушек Скверны. +250 ед. репутации с Кенарийская экспедиция', 'Воняют хуже, чем я думал!$B$BДавай их мне побыстрее, и я наполню их силой Природы так, что они окажутся смертельными для их мерзостных хозяев и их отвратительных тварей.', 'Ядра уже у тебя?', NULL, NULL, 'Пушечное ядро Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10905, 'Мастер зелий', 'Я очень даже неплохой алхимик, но только общего профиля. Если ты хочешь сосредоточиться на одной из областей знаний, придется поискать другого учителя.$B$BЗельями занимается Лоранна Тар\'велл из Кенарийской экспедиции.$B$BОна специализируется на растениях, и научит тебя наилучшим способом использовать сырье. Ее можно найти в Зангартопи. Непременно скажи, что ты от меня.', 'Поговорите с Лоранной Тар\'велл в Кенарийском приюте в Зангартопи.ВНИМАНИЕ! Вы можете выбрать лишь одно из направлений алхимии!', 'Тебя интересуют зелья? Будь по твоему, $N. Я возьмусь тебя учить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10906, 'Мастер эликсиров', 'Я очень даже неплохой алхимик, но только общего профиля. Если ты хочешь сосредоточиться на одной из областей знаний, придется поискать другого учителя.$B$BЭликсирами занимается араккоа по имени Лороким.$B$BОн превосходно разбирается в эликсирах, хотя и зарывает свой талант в землю, безуспешно пытаясь создать эликсир жизни. Найди его, он будет неплохим учителем.', 'Поговорите с Лорокимом из Нижнего города Шаттрата.ВНИМАНИЕ!Вы можете выбрать лишь одно из направлений алхимии!', 'Ты хочешь у меня учиться? Хммм, да. Может быть, из тебя и выйдет неплохой ученик.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10907, 'Мастер трансмутации', 'Я очень даже неплохой алхимик, но только общего профиля. Если ты хочешь сосредоточиться на одной из областей знаний, придется поискать другого учителя.$B$BЕсли тебя интересует трансмутация, найди эфириала по имени Заревхи. Он живет в Штормовой Вершине в Пустоверти.$B$BЧто Заревхи не знает о трансмутации, и знать не надо! Попробуй стать его $gучеником:ученицей:, но берегись – цены эфириалы заламывают... астрономические!', 'Поговорите с Заревхи из Штормовой Вершины Пустоверти.ВНИМАНИЕ!Вы можете выбрать лишь одно из направлений алхимии!', 'Ты хочешь изучать трансмутацию? Хорошо, $N. Я стану твоим учителем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10908, 'Поговорите с Рилаком Освобожденным', 'Вы так удивленно смотрите на меня... Не извиняйтесь, я привык. Мой народ, араккоа, заслуживает того, чтобы его боялись.$B$BЕсли хотите узнать больше, поговорите с Рилаком Освобожденным в Шаттрате. Его можно найти в северной части нижнего города, он живет там с другими изгнанниками из Скеттиса.$B$BИ да, $N, я не прощаюсь!', 'Поговорите с Рилаком Освобожденным в Нижнем Городе Шаттрата по просьбе Киррика Пробужденного.', 'Итак, мы встретились, Коломенский. Простите мне мою прямоту, но времени мало, так что сразу к делу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10909, 'Духи Скверны', 'Полковник Джулс попал под проклятье в битве за Форт Горгаза, укрепление орков Скверны. Мой учитель Берада день и ночь проводит возле несчастного человека, но ему нужна помощь. Измученный дух полковника ищет покоя, и я боюсь, что единственный способ вернуть ему желанный покой, – это отомстить за него.$B$BОтнеси эту реликвию анахорета на Заставу Горгаза. Положи ее на землю рядом с орками из клана Изувеченной Длани и сразись с ними. Смерть освободит их проклятые души, и ты сможешь их уничтожить, чтобы исцелить дух полковника Джулса.', 'Задействуйте по просьбе Клату из Оплота Чести реликвию анахорета на Заставе Горгаза, к юго-западу от Оплота Чести, и убивайте берсерков из клана Изувеченной Длани рядом с этой реликвией. После этого уничтожьте 10 освобожденных духов Скверны, чтобы отомстить за полковника Джулса.', 'Души орков Изувеченной Длани нечисты, и нет надежды на их исцеление, но мое сердце скорбит о том, что мы вынуждены использовать столь кровавый путь, чтобы вернуть покой душе полковника Джулса.', 'Оскверненные духи орков Изувеченной Длани разъедают несчастную душу полковника Джулса. Скажи мне, $N... тебе удалось принести ему покой?', NULL, NULL, 'Джулс отмщен', 'Реликвия анахорета (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10910, 'Врата Смерти', 'Существует еще одна опасность, даже более страшная, чем Пылающий Легион. К югу отсюда находится портал, который называют Врата Смерти. Он открывается в чудовищный мир, в котором Легион выращивает своих ужасных псов.$B$BЧтобы дотуда добраться, выйди из Вечной рощи и иди на восток вверх по склону. Потом по южной дороге, через лощину Клинков, лагерь Разаана, Островерхий гребень и склон Чешуекрылых. Затем по склону вниз к перелеску Векхаар, и попадешь к Вратам Смерти через туннель к югу от Мок\'Натала.$B$BКак только окажешься там, используй этот сигнальный огонь друидов.', 'Воспользуйтесь сигнальным огнем друидов возле Врат Смерти, чтобы призвать друидов Вечной рощи и поговорить с ними.', 'Какое счастье, что Владыка леса Антеларион послал тебя к нам. Угроза куда страшнее, чем мы думали!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10911, 'Открыть огонь!', 'Теперь, когда эти боеприпасы стали опасны для Пылающего Легиона, пришла пора их использовать.$B$BСуществуют два портала, которые используются для телепортации и пополнения сил ужасня Бездны. Один находится на юге, другой на севере, и каждый в радиусе поражения пушки Скверны.$B$BПри помощи наполненных силой Природы боеприпасов завладей пушками, и уничтожь порталы.$B$BНачни с артобстрела порталов, а когда полезут защитники порталов, будь $gготов:готова: перебить их, чтобы пушки продолжали стрелять.', 'Используйте боеприпасы, наполненные силой Природы, для установления контроля над пушками Скверны Врат Смерти. Разрушьте Северный и Южный порталы при помощи пушек.', 'Твоя доблесть просто поразительна!$B$BПрекрасно. Раз порталы уничтожены, остается сделать только одно дело.', 'Ты уже оба портала уничтожил?', NULL, NULL, 'Южный портал уничтожен', 'Северный портал уничтожен', 'Наполненные силой Природы боеприпасы (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10912, 'Псарь', 'Балмон Псарь должен умереть! Он совершает ритуалы, которые поддерживают действие портала!$B$BПортал Врата Смерти находится в северном конце каньона. Найдешь его – найдешь Балмона.$B$BТебе понадобится помощь, так что возьми этот жезл. Когда будешь биться с Псарем, воспользуйся им – и парочка моих друзей придет к тебе на помощь.$B$BКогда побьешь Балмона, вернись к Владыке леса Антелариону.$B$BИ спасибо тебе, $N, за все, что ты уже $gсделал:сделала: для нас.', 'Убейте Балмона Псаря.', 'Ты воистину замечательный $R! Если я и прежде считал, что мы у тебя в долгу, то теперь даже и не знаю, чем тебя отблагодарить!$B$BНо все же попытаюсь. Спасибо тебе, герой Вечной рощи!', 'Итак, свершилось? Угроза Врат Смерти предотвращена?', NULL, NULL, 'Бэлмон Псарь убито', 'Сигнальный огонь друидов', 'Жезл Вечной рощи (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10913, 'Недостойные похороны', 'Неужели ничего нельзя сделать для того, чтобы прекратить это осквернение? Мои солдаты бьются с Аукенаями уже много дней, и конца этой битве не видно. Тело каждого погибшего – неважно, Аукеная или Ша\'тар – похищается с поля боя, а души их не находят должного упокоения.$B$BЯ этого не потерплю! Даже если мы и не можем как следует похоронить павших, эти твари не получат их души! Возьми этот факел, отправляйся на поле боя, это прямо к востоку отсюда, и сожги там все трупы, какие только увидишь. Пусть ничего не останется для их грязных ритуалов.', 'Сожгите 8 убитых аукенайских воинов и 8 павших поборников Ша\'тар по поручению командира Ра\'ваджа. Командира можно найти на заставе Ша\'тар в Костяных пустошах в лесу Тероккар.', '<Командир Ра\'вадж хватается за голову.>$B$BЭтого мало... Этого совершенно недостаточно.', 'Я знаю, ужасно просить о таком...', NULL, NULL, 'Сожжено тел павших воздаятелей Ша\'тар', 'Сожжено тел убитых аукенайских воинов', 'Факел Ша\'тар (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10914, 'Требуется герой', 'Этого недостаточно. Нужен герой. Аукенайская армия постоянно растет и превосходит числом нашу.$B$B<Командир Ра\'вадж глядит на вас.>$B$BСтанете $gтем самым героем:той самой героиней:? Для этого вам нужно отправиться на поле боя и напасть на их солдат, тогда они отвлекутся, и мои солдаты смогут пробраться за линию фронта и посмотреть, что они там затевают.', 'Убейте 12 аукенайских посвященных и 5 аукенайских прорицателей по поручению командира Ра\'ваджа. Командира можно найти на заставе Ша\'тар в Костяных пустошах в лесу Тероккар.', 'Все получилось, $N! Благодаря вам мы совершили новое открытие...', 'Пленных не брать!', NULL, NULL, 'Аукенайский посвященный убито', 'Аукенайский прорицатель убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10915, 'Падший экзарх', 'Они скармливают похищенные души некоему саркофагу, который вытащили из Аукенайских гробниц. Мои разведчики считают, что в нем покоятся останки первого тамошнего экзарха, и враги хотят его воскресить!$B$BВам нужно пробиться к западному краю Аукиндона и разбросать содержимое гроба, пока ему не скормили достаточно душ. Если вы вдруг собьетесь с дороги, то следуйте за блуждающими духами.$B$BЧто бы там ни было в этом гробу, уничтожьте это!', 'Уничтожьте содержимое аукенайского гроба по поручению командира Ра\'ваджа. Командира можно найти на заставе Ша\'тар в Костяных пустошах в лесу Тероккар.', 'Победа за нами! Теперь Аукенай несколько недель не даст о себе знать!', 'Вы должны уничтожить древнее зло, пока оно еще не набрало силу.', NULL, NULL, 'Содержимое Аукенайского гроба уничтожено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10916, 'Откопать благословенные четки', 'Анахорет Берада собирается проводить обряд по исцелению полковника Джулса от скверны, и для этого ему понадобится помощник. Который обязательно должен надлежащим образом подготовиться...$B$BМне стыдно признаться, но я потерял свои благословенные четки во внутреннем дворе Оплота Чести. Уверен, их утащил Шар-Ик и закопал где-нибудь, но вопрос где? Поговори с хозяйкой этой собаки, прапорщиком Трейси Праудвелл, может быть, она скажет, где Шар-Ик закапывает свои сокровища.', 'Разыщите дренейские четки и принесите их ассистенту Клату в Оплот Чести.', 'О, мои четки нашлись! Спасибо тебе, $N. Ты, можно сказать, творишь настоящие чудеса, – мановением одной руки рассеиваешь ужасы полуострова Адского Пламени, мановением другой возвращаешь утраченные сокровища.$B$BЭто очень хорошо, что ты вернул мне четки. Без них не удалось бы провести обряд экзорцизма.', 'Ты нашел мои молельные четки, $N? Они необходимы для проведения многих святых ритуалов... В том числе экзорцизма.', NULL, NULL, 'Дренейские четки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10917, 'Затруднительное положение изгнанника', 'Я изгнанник, и приговорен к смерти теми, кто остался верен Скеттису. Я не выхожу из города, опасаясь за свою жизнь, но ведь я могу достать своих врагов и отсюда!$B$BУ меня тут есть небольшие сбережения, и я с радостью отдам их вам, если вы убьете тех, кто желает мне смерти. В качестве доказательства принесите мне перья араккоа из разных завес Тероккара.', 'Принесите 30 перьев араккоа Векаксу в Нижний город Шаттрата.', '*Векакс издает радостный клекот, увидев доказательства смерти своих врагов*$B$BДа, теперь-то Скеттис узнает, что мы, Изгнанники, не будем молча терпеть их притеснения! А вот и обещанная награда. Если принесете мне еще перьев, то получите больше.$B$B*Это задание можно выполнять до тех пор, пока вы не заработаете к себе уважительное отношение*', 'Вы принесли перья, которые я просил, $N?', NULL, NULL, 'Перо араккоа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10918, 'Больше перьев', '', '', '<Векакс издает радостный клекот, увидев доказательства смерти своих врагов.>$B$BДа, теперь-то Скеттис узнает, что мы, Изгнанники, не будем молча терпеть их притеснения! А вот и обещанная награда. Если принесете мне еще перьев, то получите больше.$B$B<Это задание можно выполнять до тех пор, пока вы не заработаете к себе уважительное отношение*', NULL, NULL, NULL, 'Перо араккоа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10919, 'Собачья радость', '', '', '<Шар-Ик счастливо гавкает и хватает лакомство. Потом оглядывается по сторонам, размышляя, где бы зарыть новое сокровище…>', NULL, NULL, NULL, 'Собачье лакомство для Шар-ика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10920, 'За павших', 'Когда на нашу заставу напали паучихи, мы услышали глас наару, призывающий нас к битве, и последовали за этими тварями во тьму. Некоторых из наших людей мы нашли мертвыми, но кто-то еще боролся с похитителями.$B$BК утру мы пришли в это место и дрались не на жизнь, а н$Nь, однако все не выстояли. Паучий яд скоро убьет моих товарищей, да и мне долго не продержаться. Но до того, как я умру, я хотел бы увидеть, как этим мерзким жуткопалым черным вдовам придет конец.', 'Убейте 20 жуткопалых черных вдов и вернитесь к воздаятелю Хайлену на западную сторону Гряды Пустопутов.', 'Я слышал звуки битвы даже отсюда, $C, и ваша победа вселила в мое сердце надежду. Если уж вы смогли справиться с такими жуткими тварями, то и я, возможно, найду в себе силы вытащить моих товарищей из этого отвратительного места.', 'По моим жилам течет яд. Наару зовут меня, я вижу свет... Что паучихи? Они мертвы?', NULL, NULL, 'Жуткопалая черная вдова убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10921, 'Тероккарантул', 'Вы убили много паучих, но они продолжают плодиться и скоро нападут на нас снова. Нужно убить их матку – Тероккарантула, она живет глубоко в Гряде Пустопутов. Если мы хотим раз и навсегда истребить этих пауков, то начинать нужно с нее.', 'Убейте Тероккарантула и вернитесь к воздаятелю Хайлену на западную сторону Гряды Пустопутов.', 'Наконец-то мы избавились от этих пауков. Вы убили многих из них и даже саму их матку, но я слишком сильно отравлен, чтобы выбраться отсюда.$B$BПожалуйста, возьмите некоторые из моих вещей - это немного облегчит мою ношу и поможет вам добраться до заставы Ша\'тар.', 'Тероккарантул убит?', NULL, NULL, 'Тероккарантул убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10922, 'Костяные раскопки', 'Эй! Ты, похоже, $r не из робких, а? Мы с моей командой собираемся наведаться в карьер к северу отсюда и ищем охранника, который бы нас прикрыл. Оплата хорошая, и работа нетрудная – следить, чтобы меня и моих ребят не сожрала какая-нибудь тварь.$B$BЕсли все мои рабочие вернутся живыми и здоровыми, Дворфовитц хорошенько тебе заплатит.', 'Проводите Летолла и его команду и защищайте их, пока они будут копать. После этого вернитесь к Дворфовитцу на заставу Ша\'тар.', 'Костяной червь! Фантастика! Первый раз в жизни Летолл сделал хоть какое-то открытие!', NULL, NULL, NULL, 'Защитите изыскателей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10923, 'Зло приближается', 'Если вы хотите лично сразиться с Жутусом Проклятым, вам придется использовать Реликвию Ужаса в черном некромантском ритуале. К северо-востоку отсюда, за Аукиндоном, находится Перекопанный курган – место, где собираются все некроманты.$B$BВестники смерти и прорицатели аукенай носят с собой черепа, на которые наложены мощные некромантские чары. Если вы соберете достаточно черепов, то сможете использовать их силу и силу Реликвии Ужаса, чтобы призвать Жутуса.', 'Отнесите Реликвию Ужаса на Перекопанный курган, как вам велел Оакун. В круге убивайте аукенайских вестников смерти и прорицателей, пока не соберете 20 роковых черепов. Затем найдите круг призыва Призрачного Кургана, при помощи Реликвии Ужаса призовите Жутуса Проклятого, убейте его и вернитесь к Оакуну.', 'Из Тероккара изгнано великое зло. Ша\'тар в долгу перед вами.', 'Исчез ли Жутус Проклятый с небес над Тероккаром?', NULL, NULL, 'Жутус Проклятый убито', 'Реликвия Ужаса (Прилагается)', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10924, 'Кровная м... есть!', 'Кровь прыгуан-ловцов, обитающих в этом районе – это очень сильный и редкий реактив. Торговля им идет весьма успешно.$B$BОбычно я посылаю за ней Зеппита, моего беса. Кровь прыгуана-ловца слишком едкая, чтобы ты или я могли без опаски обращаться с ней, но Зеппита это не волнует.$B$BУ меня тут много дел в лавке, так что, если я пошлю с тобой Зеппита, ты не поможешь в сборе крови? Зеппиту трудно на чем-то сосредоточиться надолго, так что тебе нужно быть поблизости от бегуна в момент его смерти, чтобы заставить Зеппита выполнить работу.', 'Принесите 8 фиалов крови прыгуаны-ловца Саб\'аофу, находящемуся в Космовороте.', 'Этого будет вполне достаточно для моих нужд.$B$BНадеюсь, бес не доставил тебе слишком много хлопот. Вообще-то он изрядный пакостник.', 'Удалось ли собрать нужное мне количество крови? Как вел себя Зеппит?', NULL, NULL, 'Кровь прыгуаны-ловца', 'Кристалл Зеппита (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10925, 'Зло приближается', '', '', '', NULL, NULL, NULL, 'Жутус Проклятый убито', 'Реликвия Ужаса (Прилагается)', 'Роковой череп', 'Рекомендуемое количество игроков: 3');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10926, 'Обратно в лагерь Ша\'тар', 'Мы не сможем вернуться сами – паучий яд слишком силен. Вернитесь в лагерь Ша\'тар и скажите разведчику Наврину, чтобы он выслал за нами подмогу.', 'Вернитесь в лагерь Ша\'тар и поговорите с разведчиком Наврином в Костяных пустошах по просьбе воздаятеля Хайлена.', 'Я очень рад слышать, что наши воины храбро сражались с пауками. За ними сейчас же отправится группа спасателей.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10927, 'Убийство пауков', 'Командир Тень Небес хочет, чтобы этот туннель был очищен от всякой пакости, и чтобы мы могли вести торговлю с Убежищем. Я не могу оставить пост, потому поручаю эту задачу вам. Проведите в туннеле зачистку и отчитайтесь командиру Тень Небес немедленно!', 'Убейте 6 пещерных пауков.', 'Хорошая работа, $C. Этот туннель – наша дорога жизни до болот.', NULL, NULL, NULL, 'Пещерный паук убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10928, 'Убийство пауков', 'Тор\'чанк Двукоготь хочет, чтобы этот туннель был очищен от всякой пакости, и чтобы мы могли вести торговлю с Болотной крысой. Я не могу оставить пост, потому поручаю эту задачу тебе. Проведи в туннеле зачистку и отчитайся Тор\'чанку Двукогтю немедленно!', 'Убейте 6 пещерных пауков.', 'Хорошая работа, $C. Этот туннель – наша дорога жизни до болот.', NULL, NULL, NULL, 'Пещерный паук убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10929, 'Барабанный бой', 'Не хочешь еще немного поработать на Лигу исследователей? Эти костяные черви чрезвычайно нас занимают.$B$BВот, у меня тут есть барабан, в который ты можешь постучать в Костяных пустошах. Просто ударь в него и посмотри, что получится. Если выползет червь – убей его и принеси нам останки для изучения. Предупреждаю, нам их потребуется немало.', 'Принесите 8 трупов взрослых просеивателей костей Дворфовитцу в лагерь Ша\'тар в Костяных пустошах.', 'Песчаные гномы? Ага, конечно... Чего только пустыня не делает с народом.$B$BА мы, кажется, на грани величайшего открытия касательно этих червей!', 'Мы думаем, что червяк, вылезший на раскопках, был всего лишь детенышем!', NULL, NULL, 'Труп взрослого просеивателя костей', 'Древний барабан Фампер (Прилагается)', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10930, 'Большой костяной червь', 'Я был прав! Эти останки, что вы принесли, принадлежат детенышам костяных червей! Знаешь, что это означает? Это означает, что где-то скрывается и большой червь! Думаю, его можно выманить, с помощью подходящей еды. Чего-то такого... большого! Да!$B$BК востоку отсюда, на другой стороне Костяных пустошей живут копытни – убейте одного, а потом начинай бить в барабан. Надеюсь, большой червь вылезет, чтобы покормиться, а если тебе удастся убить его, то вырежь у него органы и возвращайся ко мне.', 'Принесите органы гигантского костяного червя Дворфовитцу в лагерь Ша\'тар в Костяных пустошах.Заодно верните ему барабан Фампер.', 'Потрясающе! Вы только посмотрите! Вот в этой как-же-ее-штуке есть как-его-там-пузырь, а в нем – какая-то пыль! Ладно, не буду утомлять вас научным жаргоном. Я тут выдернул немного зубов из маленьких червей, и изготовил из них довольно острые ножички. Хотите такой?', 'Позовите с собой друга!', NULL, NULL, 'Органы гигантского костяного червя', 'Древний барабан Фампер (Прилагается)', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10931, 'Возвращение в Экзодар', 'Тебя желает видеть твой наставник из Экзодара, Кедмос. Речь пойдет о твоем обучении, но о чем именно, я не знаю.', 'Поговорите с Кедмосом в Экзодаре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10932, 'Возвращение в Экзодар', 'Тебя желает видеть твой наставник из Экзодара, Кедмос. Речь пойдет о твоем обучении, но о чем именно, я не знаю.', 'Поговорите с Кедмосом в Экзодаре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10933, 'Возвращение в Луносвет', 'Тебя желает видеть твой учитель из Луносвета, Альдрэ. Речь пойдет о твоем обучении, но о чем именно, я не знаю.', 'Поговорите с Альдрэ из Луносвета.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10934, 'Возвращение в Луносвет', 'Тебя желает видеть твой учитель из Луносвета, Альдрэ. Речь пойдет о твоем обучении, но о чем именно, я не знаю.', 'Поговорите с Альдрэ из Луносвета.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10935, 'Экзорцизм над полковником Джулсом', '$N, нам нужно спасти полковника Джулса. Его состояние все ухудшается. Берада боится, что если его не избавить от скверны, то мы навсегда его потеряем.$B$BВозьми эти благословленные четки и скажи анахорету Бераде, чтобы он начинал ритуал. Помни, что экзорцизм нельзя прерывать ни на минуту! Это очень важно! Если ритуал пройдет благополучно, полковник Джулс будет спасен. После окончания ритуала поговори с полковником и возвращайся ко мне.', 'Поговорите с анахоретом Берада. Используйте благословенные четки, чтобы провести ритуал. После окончания ритуала поговорите со спасенным полковником Джулсом. Возвращайтесь к ассистенту Клату.', 'Тебе удалось сделать это, $N. Ты спас душу полковника Джулса и изгнал тьму туда, откуда она пришла. Это дело, достойное героя.', 'Ступай к анахорету Бераде, $N. Если он проведет ритуал успешно, полковник будет спасен.', NULL, NULL, 'Полковник Джулс спасен', 'Ритуальные молитвенные четки (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10936, 'Тебя ищет Троллебой', 'Мы были заняты, и я попросил посланника подождать в зале. Похоже, это ему надоело, или он сбежал, увидев, как Джулс парит в воздухе.$B$BЯ к тому, что тебя ищет командир армии Данат. Рекомендую поскорее отправиться в казармы и отыскать его.', 'Ассистент Клату сообщает, что вас искал командир армии Данат Троллебой. Поговорите с Данатом в казармах Оплота Чести на полуострове Адского Пламени.', 'Очень вовремя! Я слышал о твоих приключениях с тем дренейским жрецом. Мой посланник изрядно перепугался!$B$BТеперь, когда ты разделался с предыдущим делом, у меня есть для тебя небольшая работенка в цитадели Адского Пламени...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10937, 'Перемастерить мастера', 'Я получил донесение, что орки Скверны из клана Изувеченной Длани планируют серьезную атаку. Без сомнения, твои победы их не порадовали.$B$BТебе нужно пробраться в самое основание их цитадели, туда, где заканчивается Путь Славы. Орки сейчас заняты приготовлениями, так что ты легко застанешь их врасплох.$B$BУничтожь того, кто отвечает за подготовку к битве! Убей военного инструктора Зурока!', 'Убейте военного инструктора Зурока, и как можно скорее. Это приказ боевого командира командира армии Даната Троллебоя. После выполнения задания возвращайтесь к Данату в Оплот Чести на полуострове Адского Пламени.', 'Я отказывался верить, пока не услышу от тебя лично. Мои разведчики уже донесли, что орки Изувеченной Длани суетятся в полном беспорядке, потому что теперь некому говорить им, что делать.$B$BТы проделал долгий путь, $N. Прими же из моих рук эту броню! Носи ее с честью, ибо награда заслужена тобой по праву.', 'Что, Зурок уже мертв? Выходит, мои разведчики ошибаются?', NULL, NULL, 'Военный инструктор Зурок убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10938, 'Колода карт Новолуния: Благословения', 'Как только вы собираете вместе восемь карт из колоды Молитв, девятая карта с такой же \"рубашкой\" появляется в колоде мистическим образом. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите колоду Благословений на ярмарку Новолуния.', 'Итак, ты собрал колоду Благословений. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрала все карты Благословений! Поздравляю!', NULL, NULL, 'Колода Благословений (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10939, 'Колода карт Новолуния: Вихри', 'Как только вы собираете вместе восемь карт из колоды Ураганов, девятая карта с такой же \"рубашкой\" появляется в колоде мистическим образом. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите карты Вихрей на ярмарку Новолуния.', 'Итак, ты собрал колоду Вихрей. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты Вихрей! Поздравляю!', NULL, NULL, 'Колода Вихрей (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10940, 'Колода карт Новолуния: Ярость', 'Как только вы собираете вместе восемь карт из колоды Мстителей, девятая карта с такой же \"рубашкой\" появляется в колоде мистическим образом. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите карты Ярости на ярмарку Новолуния.', 'Итак, ты собрала колоду Ярости. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрала все карты Ярости! Поздравляю!', NULL, NULL, 'Колода Ярости (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10941, 'Колода карт Новолуния: Безумие', 'Как только вы собираете вместе восемь карт из колоды Безумцев, девятая карта с такой же \"рубашкой\" появляется в колоде мистическим образом. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите колоду Безумия на ярмарку Новолуния.', 'Итак, ты собрал колоду Безумия. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты Безумия! Поздравляю!', NULL, NULL, 'Колода Безумия (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10942, 'Детская неделя', 'Одна маленькая девочка будет очень рада, если вы побудете ее опекуном, пусть и ненадолго.$B$BВот, возьмите свисток - с его помощью вы всегда сможете позвать свою воспитанницу. Долго он не прослужит, хватит как раз на Детскую неделю.$B$BПопробуйте позвать сиротку, $N! Она будет очень рада с вами познакомиться и выйти за пределы города.', 'Дуньте в эльфийскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели.', '', NULL, NULL, NULL, 'Эльфийская детская свистулька', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10943, 'Детская неделя', 'Одна маленькая девочка будет очень рада, если вы побудете ее опекуном, пусть и ненадолго.$B$BВот, возьмите свисток - с его помощью вы всегда сможете позвать свою воспитанницу. Долго он не прослужит - хватит как раз на Детскую неделю.$B$BПопробуйте позвать сиротку, $N! Она будет очень рада с вами познакомиться и выйти за пределы города.', 'Продудите в дренейскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели.', '', NULL, NULL, NULL, 'Дренейская детская свистулька', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10944, 'Тайна под угрозой', 'Благодарю тебя, $N. Мне известно твое имя. Акама посвятил тебя в свои планы, и я также поверю тебе свои.$B$BНагам стало известно о том, что я в тайне веду деятельность против Иллидана, и они попытались под пытками вытянуть из меня правду. Я не сказал ни слова - Акама научил меня превозмогать боль с помощью медитации.$B$BИллидан велел нагам привести меня к нему. Он прочел мои мысли, и я ничем не мог помешать ему.$B$BТы $gдолжен:должна: предупредить Акаму. Наши замыслы под угрозой!', 'Отправляйтесь в Клеть Стражницы в долину Призрачной Луны и поговорите с Акамой.', 'Благодарю тебя, $N. Олум один из самых близких моих друзей и самых преданных соратников. Он внес неоценимый вклад в осуществление наших замыслов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10945, 'Хч\'уу и народ грибов', 'У меня была подруга по имени Хч\'уу. Она сказала мне, что очутилась в приюте, потому что заблудилась, убегая от злобного грибного великана.$B$BМы с ней очень подружились, но в прошлом году приехали ее сородичи и забрали ее. Кажется, она сказала, что едет в Спореггар.$B$BЯ бы хотела увидеть ее и посмотреть на ее грибную деревню. Попечительница сирот говорит, что это где-то на западной стороне Зангартопи, между озерами Спороветра и Болотных Огоньков.$B$BМожно мы туда пойдем? Можно? Пожалуйста!', 'Отведите вашу подопечную Саландрию, в Спореггар в Зангартопь. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с Хч\'уу.', '', NULL, NULL, NULL, 'Отведите Саландрию в Спореггар.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10946, 'Коварство Пеплоустов', 'Жертва Олума велика. Я никогда не потребовал, чтобы он расстался с жизнью ради нашего дела. Но теперь ничего не изменишь.$B$BЧтобы поддержать в душе Иллидана иллюзию безопасности, нужно какое-то время покорно исполнять все его повеления.$B$BПод моим командованием огромная армия, но доверять я могу лишь Пеплоустам.$B$BТебе придется исполнить все, что прикажет Иллидан. Возьми этот клобук. Он зачарован: чей бы взгляд не упал на тебя, всем будет казаться, что перед ними один из моих солдат. В этом обличье тебе придется убить феникса Келя, Ал\'ара.', 'Отправляйтесь в Крепость Бурь и, облачившись в клобук Пеплоуста, убейте Ал\'ара. Затем возвращайтесь к Акаме в долину Призрачной Луны.', 'Молодец, $N. Возможно, тебе удалось на время отвлечь внимание Иллидана от нас и от... $B$B<Акама оглядывается на Майев Песнь Теней:$B$BОднако впереди еще много работы.', 'Ты расправился с фениксом, $N? Иллидан не привык ждать!', NULL, NULL, 'Клобук Пеплоуста (Прилагается)', 'Коварство Пеплоустов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10947, 'Артефакт из прошлого', 'Теперь внимание Иллидана сосредоточено на Кель\'тасе. Время действовать!$B$BМне было видение – артефакт, который сможет помочь нам в борьбе. Это амулет лича, именуемого Лютым Хладом. Однако амулет утратил свою силу после того, как его хозяин потерпел поражение в битве за гору Хиджал.$B$BНо я уверен, что есть способ вернуть артефакту его силу. Есть легенда о неком месте в Азероте, охраняемом бронзовыми драконами... месте, где встречается прошлое и будущее. Там ты найдешь то, что нам нужно.', 'Отправляйтесь в пещеры Времени в Танарисе и вступите в битву за гору Хиджал. Сразите Лютого Хлада и принесите амулет из прошлого Акаме в долину Призрачной Луны.', 'Мое зрение... Я чувствую мощь чар амулета, чувствую, как мне открывается незримое... Я использую эту силу, чтобы вернуть то, что принадлежит мне по праву. Пришло время сразиться с Иллиданом!', 'Тебе удалось вернуть силу амулету, $N?', NULL, NULL, 'Амулет из прошлого', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10948, 'Пленная душа', 'Тебя, вероятно, удивляет то, что я так долго скрывал свои намерения. Наверное, ты недоумеваешь, почему я не вступил в союз с наару в открытую?$B$BБеда в том, что душа моя заключена в Черном храме, и пока она там, Иллидан может уничтожить меня в любой момент. Но теперь все будет иначе! С помощью этого амулета я верну себе свою душу! $B$BВремя пришло, $N. Я поведу Майев и моих Служителей Смерти к порогу Иллидана.$B$BОтправляйся к А\'далу и расскажи ему о нашем плане. Если мы нанесем удар одновременно, мы сокрушим оборону Иллидана.', 'Отправляйтесь в Шаттрат и расскажите А\'далу о просьбе Акамы. ', '<Вас окутывает сияние, исходящее от А\'дала – наару приветствует вас. Вам кажется, он уже прочел в вашем сознании то, что вы должны были ему рассказать.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10949, 'Вход в Черный храм', '$gА\'дал показывает вам наару, сражающегося вместе с дренеями-воздаятелями и магистрами эльфов крови у Черного храма. Вы понимаете, что это и есть тот самый момент, которого ждал Акама.:', 'Отправляйтесь ко входу в Черный храм в долине Призрачной Луны и поговорите с Зи\'ри.', '<Кажется, Зи\'ри чувствует ваше присутствие. Однако он сосредоточен на битве.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10950, 'Аукиндон и Ритуальный Круг', 'Один из приходивших к нам жрецов рассказал нам об одном месте неподалеку отсюда. Оно называется Аукиндон, и, по идее, очень важно для дренеев.$B$BОн сказал, что раньше туда относили тела умерших дренеев. Но некоторое время назад случилось что-то плохое и все взорвалось.$B$BЯ бы хотела взглянуть на этот Ритуальный круг. Попечительница сирот говорила, что оно находится в центре Костяных пустошей, на юге от леса Тероккар.$B$BПожалуйста, $gгосподин:госпожа: $N, пойдем туда!', 'Отведите свою подопечную, сиротку Дорнаа, к камню встречи у Ритуального круга в центра Аукиндона. Аукиндон находится в центре Костяных пустошей, что в лесу Тероккар. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.', '', NULL, NULL, NULL, 'Сводить Дорнаа к Ритуальному Кругу', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10951, 'Путешествие к Темному порталу', 'Как можно смотреть на всякие интересные места и не побывать у Темного портала?!$B$BВзрослые всегда рассказывают страшилки, как там опасно, как много демонов и прочих ужасов.$B$B<Саландрия закатывает глаза.>$B$BНо ты же здесь, и в полном порядке, значит, ничего такого страшного там нет.$B$BЯ хочу сама посмотреть. Ты помнишь, в какой части восточного края полуострова Адского Пламени он находится?', 'Отведите свою подопечную, сиротку Саландрию, на Ступени Судьбы, к Темному порталу на полуострове Адского Пламени. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом.', '', NULL, NULL, NULL, 'Отведите Саландрию к Темному порталу.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10952, 'Путешествие к Темному порталу', 'Есть одно место, куда надо непременно сходить: Темный портал!$B$BПопечительницы сирот вечно пугают нас сказками про то, как там опасно, про ужасных демонов и про то, как такие как ты чудом остаются в живых, попав туда.$B$B<Дорнаа закатывает глаза.>$B$BНо ты же здесь, и в полном порядке, значит, не так уж там и плохо, да?$B$BЯ хочу сама поглядеть. Он ведь находится на восточной окраине полуострова Адского Пламени?', 'Отведите свою подопечную, сиротку Дорнаа, на Ступени Судьбы, к Темному порталу на полуострове Адского Пламени. Обязательно призовите Дорнаа, если по прибытии ее не будет рядом.', '', NULL, NULL, NULL, 'Отведите Дорнаа к Темному порталу.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10953, 'Путешествие к Трону стихий', 'Ты когда-нибудь $gслышал:слышала: о Троне стихий? Кажется это такое место в Награнде, где живут все эти элементали.$B$BКогда-нибудь я стану могущественным магом или чернокнижницей. Я все узнаю про эти силы стихий!$B$BКак ты думаешь, можно туда сходить?$B$B<Саландрия лукаво смотрит на вас.>$B$BНаверняка это будет очень познавательно. Кажется, Трон находится на севере от Гарадара, на другой стороне озера Небесной Песни.', 'Отведите свою подопечную, сиротку Саландрию, к Трону стихий в Награнд. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с повелительницей стихий Шарвак.', '', NULL, NULL, NULL, 'Отведите Саландрию к Трону стихий.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10954, 'Джил находится в Небесном лагере!', 'Я соскучилась по брату, Джилу. Он старше меня на два года, поэтому ему разрешили поступить в обучение к эфириалам в Награнде.$B$BМне бы хотелось его навестить! Он увлекается геологией и тому подобным, так что ему там нравится.$B$BПопечительница сирот говорит, что он в обучении в Небесном лагере. Кажется, этот лагерь находится прямо у дороги, далеко на западе от Телаара и на северо-западе от великой горы Ошу\'гун.', 'Отведите свою подопечную, сиротку Дорнаа, в Небесный лагерь в Награнде. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом. Затем поговорите с Джилом.', '', NULL, NULL, NULL, 'Сводить Дорнаа в Небесный лагерь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10955, 'Мортис Шелест Крыла', 'До того, как все ордена друидов объединились в Круг Кенария, друиды-вороны отвечали за обучение талантливых молодых друидов искусству полета. Когда орден был распущен, бывшие его члены не оставили своего дела, но попасть к ним в ученики не так-то просто.$B$BВ настоящий момент Мортис Шелест Крыла ищет себе ученика. Немногие друиды освоили все доступные им облики, но ты, кажется, $gнаделен:наделена: теми талантами, которые нужны Мортису. Найди его в Кенарийском приюте в Зангартопи.', 'Найдите Мортиса Шелест Крыла в Кенарийском приюте в Зангартопи.', '*Мортис смотрит на вас с сомнением.*$B$BЯ давно ищу ученика, которому смогу передать собственные занания. Хотя орден друидов-воронов распался, я останусь одним из них до самой смерти.$B$BЯ возьму тебя к себе в ученики и обучу тайнам буревестника. Ты же должен выполнять все мои приказы. Ясно?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10956, 'Трон наару', 'Что ты знаешь про наару? Это же те ангелы, которые издавна помогают дренеям. Я видела их в Шаттрате.$B$BГоворят, что один из наару, О\'рос, был на \"Экзодаре\" во время полета к вашей родине. Я бы хотела сама посмотреть.$B$BОтведи меня туда, пожалуйста. Готова поспорить, что мы мигом обернемся, если воспользуемся одним из порталов на террасе Света в Шаттрате! А когда мы доберемся до места, то если заблудимся, сможем посмотреть на твою карту.', 'Отведите свою подопечную, сиротку Дорнаа, к О\'росу, который находится у подножия Трона наару в Экзодаре. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.Не забывайте пользоваться картой, чтобы сориентироваться в столице.', '', NULL, NULL, NULL, 'Отведите Дорнаа к Трону наару.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10957, 'Искупление Пеплоустов', 'Когда Иллидан вступил в союз со Сломленными, нашим вождем был Акама. Он понимал, что если наша раса осмелится противостоять Предателю в открытую, все мы будем уничтожены.$B$BПоэтому он сделал вид, что готов союзничать с Иллиданом, и до сегодняшнего дня выжидал случая нанести ему удар в спину. Неудача была бы непоправимой... не только для Акамы, не только для Сломленных, но и для всего Запределья. Никто из приближенных Иллидана не наносил ему столь сокрушительного удара.$B$BПомоги Акаме освободить душу, и он впустит тебя в святилище Иллидана.', 'Верните Акаме власть над его душой, сразив тень Акамы в Черном храме. Затем возвращайтесь в провидцу Канаи.', 'Дело сделано, $N. Пора расправиться с Иллиданом', 'Да, $N?', NULL, NULL, 'Тень Акамы убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10958, 'Найти Пеплоустов', '$gВы смотрите на Зи\'ри, и ваш разум проясняется, а дух укрепляется. Ваша работа здесь закончена, теперь вы должны войти в Черный храм и найти последователей Акамы.>$B$B<От его действий зависит судьба многих.:', 'Найдите Служителей Смерти Акамы в Черном храме.', 'Мы ждали тебя, $N. Акама нуждается в твоей помощи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10959, 'Судьба Предателя', 'Когда воины Иллидана будут разбиты, Акама сможет открыть путь в святилище Предателя. Будь $gготов:готова: отправиться туда немедленно.$B$BНам все еще не известно, что сталось с Майев, но мы должны двигаться дальше без нее.$B$BНадеюсь, ты справишься. Иллидан едва ли придет в восторг при виде Акамы.', 'Провидец Канаи хочет, чтобы вы победили Иллидана в Черном храме.', 'Все вышло так, как мы предполагали, $N! Воины Иллидана пали один за одним и наконец и сам Иллидан принял кару! $B$BЗнай, что многие годы Акама жил мыслями об этой минуте! Наконец-то Иллидан мертв, а мой народ свободен!', 'Да, $N?', NULL, NULL, 'Иллидан Ярость Бури убито', 'Медальон Карабора', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10960, 'Когда я вырасту...', 'А когда тебе было столько же лет, сколько мне, ты уже $gзнал:знала:, что будешь $C, когда вырастешь?$B$BА я не знаю, кем хочу быть. Может, магом или чернокнижницей? Или, может, рыцарем крови паладином? Да, рыцарем крови лучше всего!$B$BГоворят, что настоящие рыцари крови обучаются в Луносвете! И что наставников паладинов можно найти на площади Странников. Ты отвезешь меня туда?$B$BНу, пожалуйста, отвези меня туда, пожалуйста!', 'Отведите свою подопечную, сиротку Саландрию, к наставникам паладинов на площадь Странников в Луносвет. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с леди Лиадрин, матриархом рыцарей крови.Не забывайте пользоваться картой, чтобы сориентироваться в городе, а найти наставников паладинов вам помогут стражи.', '', NULL, NULL, NULL, 'Сводить Саландрию к наставникам паладинов в Луносвет.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10961, 'Зелье пробуждения', 'Давным-давно одному древнему друиду доверили реликвии, обучавшие пути буревестника.$B$BПоскольку они нужны тебе для занятий, придется пробудить хранителя от сна.$B$BЯ приготовлю зелье, которое позволит сделать это без особого труда. Для составления зелья необходимы вполне обычные травы, а также топлянник, который растет на самых высоких грибах в болоте. Лети туда и набери его, но соблюдай осторожность, растение хрупкое и может взорваться, если неаккуратно с ним обращаться.', 'Принесите 10 топлянников, 10 древних лишайников и 10 цветков сияния грез Мортису Шелесту Крыла в Кенарийский приют.', '<Мортис берет у вас травы и внимательно осматривает их. Затем достает сосуд и начинает варить зелье.>$B$BЭто не займет много времени, $N. Потом тебе придется отправиться на Лунную поляну.', 'Ты принес все составляющие зелья? Пожалуйста, не стряхивай на меня пыльцу. Я от нее начинаю чихать.$B$B*Мортис фыркает, показывая, как неприлично чихать.*', NULL, NULL, 'Топлянник', 'Древний лишайник', 'Сияние грез', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10962, 'Время посетить Пещеры', 'Один старый жрец в приюте рассказывал нам сказки про пещеры Времени. Он говорил, что они находятся в центре времен, и очень важно, чтобы все шло своим чередом.$B$BНе знаю, что он имел в виду, но я запомнила, что там сидят драконы, которые помогают спасти мир! Я хочу посмотреть на драконов!$B$BКак ты думаешь, можно туда сходить? Он говорил, что вход в пещеры находится в восточной части огромной пустыни, Танариса.$B$BМожет быть, ты купишь мне сувенир, когда мы будем там?', 'Отведите свою подопечную, сиротку Дорнаа, к дракону на возвышении в центре пещер Времени, Заладорму. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.Купите ей игрушечного дракона у начальника снабжения Хранителей Времени, Алурми, в конце входного туннеля.', '', NULL, NULL, NULL, 'Игрушечный дракон', 'Сводить Дорнаа в пещеры Времени', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10963, 'Время посетить Пещеры', 'Один старый жрец в приюте рассказывал нам сказки про пещеры Времени. Он говорил, что они находятся в центре времен, и очень важно, чтобы все шло своим чередом.$B$BНе знаю, что он имел в виду, но я запомнила, что там сидят драконы, которые помогают спасти мир! Я хочу посмотреть на драконов!$B$BЯ хочу туда сходить. Он говорил, что вход в пещеры находится в восточной части огромной пустыни Танарис.$B$BМожет быть, ты купишь мне сувенир, когда мы будем там?', 'Отведите свою подопечную, сиротку Саландрию, к дракону на возвышении в центре пещер Времени, Заладорму. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом.Купите ей игрушечного дракона у начальника снабжения Хранителей Времени, Алурми, у входа в туннель.', '', NULL, NULL, NULL, 'Игрушечный дракон', 'Сводить Саландрию в пещеры Времени.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10964, 'Пробуждение спящего', 'Возьми зелье и отправляйся на Лунную поляну, в кельи Малфуриона. В самой южной из них, той самой, которую охраняют Хранители снов, ты найдешь Клинтара Странника Снов.$B$BНапои его зельем и дождись его пробуждения. В момент соединения души с телом он будет очень уязвим и несомненно не узнает тебя. Представься, как только он придет в чувства. Ему понадобится твоя помощь для сбора реликвий для церемонии.', 'Разбудите Клинтара Странника Снов при помощи зелья Пробуждения. Когда он придет в себя, поговорите с ним.', '*Друид пробуждается от сна. Вид у него сонный, непонимающий. Взгляд мечется по комнате в поисках невидимых преследователей.*$B$BМортис?$B$BНет, ты не Мортис... Кто ты, $R, и зачем тревожишь меня?$B$B*Хотя вопрос - не воплощение дружелюбия, друид явно рад пробуждению.*', '*Вы готовитесь напоить спящего друида зельем.*', NULL, NULL, 'Зелье пробуждения (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10965, 'Не просто сон', '*Клинтар внимательно слушает, пока вы перечисляете инструкции Мортиса, кивает, но вид у него весьма испуганный.*$B$BЯ не могу полностью отринуть Изумрудный Сон и отправиться тебе на помощь, но частица моей души поможет тебе в поисках реликвий. Обращайся с ней бережно, она очень хрупкая.$B$BИзумрудный Сон стал чуждым и опасным местом. Он крепко держит меня, и я не смогу стать сам собой, пока он не станет таким, как прежде. Вокруг тебя лишь отзвук реальности сна!', 'Охраняйте дух Клинтара Странника Снов, пока он будет собирать реликвии Авианы. Потом поговорите с Луросой Хранительницей Снов.', 'Тебе повезло, что Клинтару смог так долго удерживать частицу своего духа, $N. Немногим друидам под силу такое, когда на них нападают враги в Изумрудном сне. Храни эти реликвии!', 'Торопись, $R. Если эти твари сбегут из обители, в опасности окажется не только Клинтар Странник Снов.', NULL, NULL, 'Помогите Клинтару собрать реликвии', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10966, 'Возвращение в приют', 'Увы! Боюсь, что пора возвращаться в приют в Шаттрат.$B$BА мне было так хорошо! Ты лучше всех на свете, $N! Теперь ты $gмой старший брат:моя старшая сестра:!$B$B*У Дорнаа наворачиваются слезы на глаза.*$B$BЯ буду по тебе очень скучать! Когда я вырасту, я стану такой же, как ты!!!', 'Отведите свою подопечную обратно в приют Шаттрата, вернув дренейскую детскую свистульку попечительнице сирот Миле в Нижнем городе.', '', NULL, NULL, NULL, 'Дренейская детская свистулька', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10967, 'Возвращение в приют', 'Увы! Боюсь, что пора возвращаться в приют в Шаттрат.$B$BА мне было так хорошо! Ты лучше всех на свете, $N! Теперь ты $gмой старший брат:моя старшая сестра:!$B$B*У Саландрии наворачиваются слезы на глаза.*$B$BЯ буду по тебе очень скучать! Когда я вырасту, я стану такой же, как ты!!!', 'Отведите свою подопечную обратно в приют Шаттрата, вернув эльфийскую детскую свистульку попечительнице сирот Миле в Нижнем городе.', '', NULL, NULL, NULL, 'Эльфийская детская свистулька', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10968, 'Зов предсказателя', 'Это необыкновенный ребенок.$B$BОтведи ее к предсказателю Нобундо. Он здесь, в Экзодаре, и уже ждет вас.$B$BНобундо можно найти на самой высокой террасе Кристального зала.', 'Отведите свою подопечную, сиротку Дорнаа, к предсказателю Нобундо в Кристальный зал Экзодара. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.Не забывайте пользоваться картой, чтобы сориентироваться в городе.', '', NULL, NULL, NULL, 'Сводить Дорнаа к предсказателю Нобундо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10969, 'В поисках Амира', 'Похоже, что внешние силы проявляют интерес к деловой практике Консорциума. Пятеро посредников Консорциума пропало за последние два дня. У нас есть причины считать, что к этому причастно Братство Эфириум. Если ты не против нам помочь, отыщи командира Амира на заставе стражей Протектората. $B$BЗаставу стражей Протектората ты найдешь прямо к востоку отсюда, на следующем острове.', 'Найдите командира Амира на заставе стражей Протектората.', 'Так точно, это правда, но Консорциум не единственная группа, заявляющая о потерях.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10970, 'Миссия милосердия', 'Мы подобрали этот шар-темницу во время нашей последней разведывательной миссии на территории Эфириума. Мы никогда бы не нашли его, если бы не сигнал бедствия, который этот шар слабо излучал.$B$BМы думаем, что внутри может быть заключен один из наших сородичей, однако мы не знаем, как вскрыть шар, не причинив вреда тому, кто находится в нем.$B$BЧто мы точно знаем об Эфириуме – так это то, что любой из принадлежащих к нему может в любой момент времени иметь при себе ключ, открывающий шар. Заполучи один из этих ключей и вернись к нам, чтобы мы могли разгадать тайну шара.', 'Раздобудьте ключ от найденной темницы Эфириума для командира Амира, находящегося на заставе стражей Протектората в Пустоверти.', 'Отойди подальше, $N. Это вполне может быть ловушка Эфириума.', 'Ну, как успехи?', NULL, NULL, 'Трофейный ключ от тюрьмы братства Эфириум', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10971, 'Секреты Эфириума', '$gАмир держит в руках табличку.>$B$BЯ нашел эту бирку узника среди трупов солдат передового отряда. Могу лишь предположить, что на каждого узника у них заведена такая бирка.$B$BЯ собираюсь начать заносить эти бирки в каталог в надежде понять смысл их карательной системы. Если в своих странствиях ты найдешь еще ключи от тюрем Эфириума, ты можешь использовать их, чтобы открыть тюрьмы Эфириума на Полигоне Эфириума – прямо на юг отсюда. Принеси мне все бирки, которые найдешь.', 'Командир Амир, находящийся на заставе стражей Протектората в Пустоверти, просит вас принести ему бирки пленников Эфириума.', 'Кажется, это больше, чем просто идентификация. На этих табличках записан какой-то шифр. Похоже, я скоро его разгадаю. Может быть, для этого мне нужно еще несколько таких табличек.', 'Тебе удалось найти идентификационные таблички?', NULL, NULL, 'Идентификационная табличка пленника Эфириума', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10972, 'Каталог бирок пленников Эфириума', 'Мне нужно больше идентификационных табличек, $N. До сих пор мне удалось обнаружить, что это не просто способ составить каталог узников, но также указание на различные точки размещения!$B$BКогда шифр будет раскрыт, мы сможем точно узнать, где содержатся наши союзники, и освободить их с минимальными потерями.', 'Мне нужно больше бирок, $N. Мне удалось обнаружить, что это не просто способ составить каталог узников, но также указание на различные точки размещения!Когда шифр будет раскрыт, мы сможем точно узнать, где содержатся наши союзники, и освободить их с минимальными потерями.', 'Истина где-то рядом, $N.', NULL, NULL, NULL, 'Идентификационная табличка пленника Эфириума', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10973, 'Тысяча миров', 'Я понял шифр! Каждая табличка разбита на несколько частей. Лицевая сторона всех табличек одинакова и надпись на ней гласит \"Тысяча Миров..\" Я не знаю, каково значение этой фразы, но звучит загадочно.$B$BНа обратной стороне таблички находятся важные данные. Первый набор рун указывает на местонахождение, а второй – на вид узников. Более того, похоже, ключи можно соединить, чтобы получить особый ключ, дающий доступ к тюрьмам другого типа. Теперь мне просто нужно больше ключей...', 'Командир Амир, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы принесли ему 5 ключей от тюрьмы братства Эфириум.', '<Амир ловко соединяет ключи и начинает читать надписи на получившейся ключевой таблице.>$B$B\"Тысяча миров расколоты, тысячу миров предстоит одолеть... Такова воля Соправителя Хаоса.\"$B$B<Амир переворачивает табличку и начинает читать с обратной стороны.>$B$BСтазисные камеры Баш\'ира?', 'Я знаю, что прошу многого, но подумай, сколько жизней этим можно спасти!', NULL, NULL, 'Ключ от тюрьмы братства Эфириум', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10974, 'Стазисные камеры Баш\'ира', 'Эфириум основал на северных склонах Острогорья поселение, известное как лагерь Баш\'ира. Согласно табличке с шифром, в лагере Баш\'ира размещена большая тюрьма. Следует также заметить, что представители Эфириума именуют эту тюрьму стазисными камерами.$B$BКлючевая табличка дает доступ к особой стазисной камере, известной как стазисная камера \"Альфа\". Возьми ключ и исследуй эту камеру.$B$BМоя проекция будет ожидать твоего возвращения в лагере Баш\'ира. Поговори со мной там.', 'Используйте табличку-ключ \"Альфа\" Эфириума, чтобы открыть стазисную камеру \"Альфа\" в лагере Баш\'ира в Острогорье.Предоставьте свидетельства из камеры \"Альфа\" проекции командира Амира в лагере Баш\'ира.', '<Проекция командира Амира просматривает свидетельства.>$B$BЭто хуже, чем я думал... В этих палатах содержатся свирепые твари и существа из многих, многих разных миров. Они надеются, что когда-нибудь эти твари будут повиноваться их приказам. Мы должны уничтожить их всех!', 'Готово? Повезло ли тебе?', NULL, NULL, 'Свидетельство из Альфы', 'Табличка-ключ Альфа Эфириума (Прилагается)', 'Рекомендуемое количество игроков: 5', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10975, 'Очищение камер Баш\'ира', '', '', 'Сделать предстоит больше, чем сделано, $N. Теперь отыщи стазисную камеру и уничтожь зло, таящееся в ней!', NULL, NULL, NULL, 'Ключ от тюрьмы братства Эфириум', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10976, 'Знак короля нексуса', 'Теперь я должен узнать, что именно Эфириум хранит в Гробницах маны Аукиндона.$B$BВозможно, во время сражений с тварями, содержащимися в стазисных камерах Баш\'ира, тебе посчастливится наткнуться на предмет, известный как знак короля нексуса. Если ты найдешь этот предмет, возвращайся ко мне немедленно! Это последняя деталь для создания ключа, который даст доступ в стазисную камеру внутри Гробниц маны.', 'Проекция командира Амира, находящаяся в лагере Баш\'ира в Острогорье просит вас принести ему знак короля нексуса.', 'Наконец-то!$B$B<Командир Амир читает то, что написано на знаке короля нексуса.>$B$BДве последние тюрьмы? Боюсь даже подумать, какой ужас таится там...', 'Это будет самой важной твоей задачей, $N.', NULL, NULL, 'Знак Соправителей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10977, 'Стазисные камеры Гробниц маны', 'Найденный тобой знак короля нексуса позволяет мне выковать новый ключ для стазисных камер, обнаруженных внутри Гробниц маны.$B$BСогласно надписи на знаке, существуют две камеры: одна поблизости от входа, вторая – около покоев принца Шаффара. Этот ключ, который я собираюсь тебе вручить, открывает ту стазисную камеру, что расположена ближе к входу.$B$BЯ прошу тебя отправиться в Гробницы маны Аукиндона и открыть стазисную камеру Гробниц маны.', 'Проекция командира Амира, находящаяся в лагере Баш\'ира в Острогорье просит вас использовать ключ от стазисной камеры Гробниц маны, чтобы открыть стазисную камеру внутри Гробниц маны Аукиндона. Это задание можно выполнить только в героическом режиме.', 'До нас дошло известие о товем героизме, $N. Мы с Харамадом оба согласны, что ты заслуживаешь великой награды.$B$BХотя... Нет, неважно, того, что сделано тобой, более чем достаточно. Я, будучи в здравом уме, не могу просить тебя сделать больше.', 'Я пойму, если ты решишь отказаться от дальнейших действий, $N.', NULL, NULL, 'Ключ от стазисной камеры Гробниц маны (Прилагается)', 'Исследуйте стазисную камеру Гробниц маны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10978, 'Возвращение к Мортису Шелесту Крыла', 'Теперь, когда все реликвии у тебя, беги отсюда. Стараясь тебе помочь, Клинтар поставил под удар свою безопасность... И безопасность Хранителей сна.$B$BОтнеси реликвии Мортису Шелесту Крыла и расскажи ему, что здесь происходит. Вдруг он поможет нам разобраться, с чем борется Клинтар.', 'Отнесите реликвии Авианы Мортису Шелесту Крыла в Кенарийский приют в Зангартопи.', '*Мортис берет у вас реликвии и слушает рассказ о происходящем в обители друидов.*$B$BТревожные вести, $N. В Изумрудном сне давно творится что-то странное, но я первый раз слышу, что к этому имеют отношение сторонние силы. Ты уверен, что Клинтар так считает?', 'Значит, Клинтар помог тебе отыскать реликвии?', NULL, NULL, 'Реликвии Авианы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10979, 'В Вечную рощу', 'Ты $gуверен:уверена:, что видела именно ворона?$B$BЭто особенно скверно. Мы не сможем помочь Клинтару и Хранителям сна напрямую, но если узнать, кто вмешивается в Изумрудный сон, можно помешать ему.$B$BДо нас дошли слухи о возрождении в Острогорье древнего культа араккоа - культа бога-ворона. Ступай в Вечную рощу и найди там Арторн Песню Ветра. Может быть, есть какая-то связь между этим культом и Изумрудным сном.', 'Поговорите с Арторн Песней Ветра из Вечной рощи, что в Острогорье.', '<Арторна внимательно выслушивает все подозрения Мортиса о связи между культом бога-ворона и странными событиями на Лунной поляне. Хотя новости ее несомненно ошеломляют, кажется, ее больше огорчает суть послания.>$B$BНу и ну...$B$BЯ помогала Времиону исследовать культ ворона, но мы и не подозревали, что он простирается за пределы Острогорья.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10980, 'Книга Ворона', 'Судя по всему, подозрения Мортиса обоснованны, но убедиться не помешает.$B$BВ ходе своих исследований Времион выяснил, что священным писанием для культа ворона служила некая книга Ворона.$B$BДухи араккоа не захотят являться тебе. Отнеси этот камень в западную часть Острогорья, на вершины, к югу от леса Ворона. Не забудь добыть глаз воздухоската. При помощи этих предметов ты сможешь обострить собственное зрение. Отыщи призрака Времиона. Он зовется Сай\'ккал Старейшина.', 'Усильте свое зрение при помощи ока летучего ската и камня Провидца и разгядите призраков сторонников культа Ворона. Отыщите на Нагорье Смерчей старейшину Сай\'ккала и расспросите его про книгу Ворона. Затем возвращайтесь к Арторн Песне Ветра.', 'Правда, поразительно, что даже среди араккоа эти сектанты считались еретиками? Невероятно - жрецы так ненавидели их, что решились уничтожить священные тексты! Мы должна заполучить эту книгу,$N.$B$BОна поможет нам разгадать великую тайну бога-ворона и освободить от него Изумрудный сон.$B$BМожет быть, если мы добьемся успеха, Мортис согласится взять меня в ученики?', '*Арторна смотрит на вас с надеждой.*$B$BТебе удалось что-нибудь узнать про книгу?', NULL, NULL, 'Узнайте о книге Ворона', 'Камень Провидца (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10981, 'Личная палата принца Шаффара', '', '', '', NULL, NULL, NULL, 'Знак Соправителей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10982, 'Око Харамада', '', '', 'Твои заслуги перед Протекторатом и Консорциумом поистину велики, $N. Так что будет только правильно, если первый из наших ключей будет отдан тебе. Этим ключом ты в любое время можешь открыть личную стазисную камеру Шаффара, не утратив при этом сам ключ.<Амир кивает.>Ключ неотъемлем и пребудет с тобой навечно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10983, 'Мог\'дорг Мудрый', 'Мог\'дорг мудрый! Послал Грока в город за помощью. Клану Кровавого Молота надо помочь.$B$BМог\'дорг велел отправлять всех сильных малышей к нему в Острогорье. Он там стоит на вершине башни, у Круга Крови. Мог\'дорг умный!', 'Сходите к Мог\'доргу Мудрому, который живет на вершине башни в Острогорье, сразу за Кругом Крови.', 'Грок сказал, что я мудр? Вот уж не знаю.$B$BВозможно, это потому, что я единственный, кто пытается спасти наш клан от клана Камнерогов и поддерживающего их Груула с сыновьями.$B$BНадеюсь, ты здесь, чтобы помочь нам избавиться от ужасной участи, $C?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10984, 'Разговор с огром', '$gГолос В\'еру раздается в вашей голове чистым хрустальным звоном.>$B$BВ Нижнем городе есть огр, который молит всех прохожих о помощи, однако никто не желает выслушать его.$B$BМожет быть, вы поможете ему в беде?$B$BЕго зовут Грок, он сидит около торговцев, на юго-востоке.$B$BСпасибо, $N.', 'Поговорите с огром по имени Грок в Нижнем городе Шаттрата. ', 'Ты помогать Гроку? Гроку надо помогать! Кровавому Молоту надо помогать!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10985, 'Отвлекающий маневр', '<Зи\'ри излучает пульсирующее сияние, отдавая приказания войскам Алдоров и Провидцев. Армия Зи\'ри готова отбросить силы Иллидана и тем самым отвлечь их, чтобы Акама мог проникнуть в храм. Наару ждет вашего сигнала, чтобы начать атаку.>', 'Убедитесь, что Акама и Майев вошли в Черный храм в долине Призрачной Луны после того, как войска Зи\'ри совершат отвлекающий маневр.', '<Зи\'ри излучает волны энергии, и вы чувствуете, как в ваших руках возникает некий предмет. Это медальон, который вы отдали А\'далу от имени Акамы – его сила многократно увеличена магией наару. Ша\'тар доверили вам медальон Карабора, а вместе с ним и возможность войти в Черный храм.:', '<Зи\'ри чувствует ваше присутствие.>', NULL, NULL, 'Помогите Акаме и Майев войти в Черный храм.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10986, 'Небесные очи', 'Если части книги Ворона и уцелели, найти их будет нелегко. Можно надеяться лишь на помощь более острых глаз, чем твои.$B$BВ западной части Награнда на восточном уступе Сумеречной гряды, живет дозорная Элайра. Она изучает птиц, гнездящихся в этой части гор. Поговори с ней, может быть, она поможет тебе призвать на помощь острое зрение хищных птиц, и ты соберешь воедино книгу Ворона.', 'Поговорите с дозорной Элайрой на Сумеречной гряде в Награнде.', '*Элайра слушает рассказ о поисках книги Ворона и предложении Арторны воспользоваться помощью птиц для поисков недостающих частей таблички.$B$BОтличная мысль. В Награнде полно подходящих птиц, но какая подойдет больше всего?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10987, 'Поймать скальную пустельгу', 'Из всех хищных птиц Награнда самое острое зрение у дикой пустельги. Впрочем, из-за небольших размеров этих пичуг их почти повсеместно вытеснили более крупные ветрухи.$B$BПустельга по большей части гнездится здесь, на Сумеречной гряде. Если тебе удастся поймать одну из них, я натаскаю ее на поиски частей закопанной таблички.$B$BВпрочем, поймать ее будет будет нелегко. Пустельга – увертливая птица, и при виде охотника старается убраться подальше. Я предлагаю загнать одну из них в угол или просто подкрасться поближе и накинуть на нее сеть.', 'Поймайте дикую пустельгу при помощи специальной сети и принесите ее дозорной Элайре на Сумеречную гряду.', 'Молодец! Мне пока не удалось завоевать доверие птиц, но для твоих нужд я смогу ее натаскать.', 'Тебе удалось поймать скальную пустельгу?', NULL, NULL, 'Пойманная пустельга', 'Сеть для ловли скальной пустельги (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10988, 'Вороньи камни', 'Я научила твою пустельгу отвечать на свист особого манка. Услышав его, птица слетит к тебе и укажет следующее место, в котором спрятан фрагмент таблички. Арторна сообщила, что искать их следует в Скеттисе, что в юго-восточной части леса Тероккар, так что птица будет ждать тебя там.$B$BКогда ты соберешь все камни, верни манок Арторн, и она позаботится о птичке.$B$BПередай Арторн от меня большой привет.', 'Соберите в Скеттисе 8 вороньих камней и принесите их Арторн Песне Ветра в Вечную рощу в Острогорье.', '*Арторна забирает у вас фрагменты книги Ворона и начинает складывать их вместе.*$B$BНекоторые символы стерлись от времени, но большую часть разобрать можно...', 'Удалось ли тебе собрать воедино большую часть книги Ворона?', NULL, NULL, 'Вороний камень', 'Свисток кенарийской пустельги (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10989, 'Мог\'дорг Мудрый', 'Мог\'дорг Мудрый ждет тебя на той башне. Он сказал мне искать $C вроде тебя. Ты иди говорить с ним про мудрые вещи.$B$BИди теперь, но никому не говори. Это тайна!', 'Поговорите с Мог\'доргом Мудрым на вершине башни, где стоит Фырк, прямо у Круга Крови в Острогорье.', 'Наконец-то Фырк прислал ко мне того, кто, похоже, может помочь. Я пытаюсь спасти Кровавый Молот от уничтожения кланом Камнерогов и сынами Груула, которые стоят за ними.$B$BЯ верю, что ты поможешь нашему тайному обществу и приведешь нас к свободе!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10990, 'Сущность орла', 'Книга Ворона гласит, что его последователи ловили души соперников ворона и заключали их в каменные святилища. К каждому из них был приставлен страж, чтобы никто не вздумал их освободить.$B$BПервое святилище посвящено орлу. Оно находится в холмах на юге от озера Йорун и на западе от форта Камнеломов в лесу Тероккар.$B$BНа табличке говорится, что орел доблестно бился, но был окружен полчищами врагов. Для этого сражения отлично подойдет обличье медведя.', 'Одолейте стража Орла и добудьте у него сущность орла. Призовите пустельгу Арторн особым манком, чтобы сообщить новости об успешном выполнении задания.Если вы потеряете манок Арторн для пустельги, вернитесь к Арторн в Вечную рощу за новым.', '*Кажется, пустельга передает Арторн силу добытой сущности.*$B$BДаже тысячи лет плена не лишили орла силы. Если другие сущности не хуже этой, бог-ворон правильно тебя боится.', '*Кажется, пустельга говорит голосом Арторн.*$B$BУдалось ли тебе освободить сущность духа орла?', NULL, NULL, 'Сущность орла', 'Манок пустельги Арторн (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10991, 'Сущность сокола', '*Птица говорит голосом Арторны.*$B$BВторой душой, попавшейся в лапы последователей ворона, стал сокол.$B$BЕго пленили недалеко от Скеттиса, в назидание жрецам ворона.$B$BК северо-западу от Скеттиса, на берегах озера Эре\'Нору, находится святилище сокола.$B$BЧтобы одолеть его стража, воспользуйся сильными сторонами сокола. Для этого как нельзя лучше подойдет твой облик кошки. Главное – воспользоваться силой и ловкостью, пока страж не наберется сил!', 'Одолейте стража Сокола и добудьте у него сущность сокола. Призовите пустельгу Арторн особым манком, чтобы сообщить новости об успешном выполнении задания.Если вы потеряете манок Арторн для пустельги, вернитесь к Арторн в Вечную рощу за новым.', '*Пустельга покорно передает слова Арторн.*$B$BМолодец. Я опасалась, что темница сокола пострадала при взрыве Аукиндона. Мы почти готовы к сражению с Анзу, $N. Я бы с радостью пришла тебе на помощь, и низвергла самозванного бога в породившую его бездну!', '*И снова скальная пустельга говорит голосом Арторн.*$B$BУдалось ли тебе освободить сущность души сокола?', NULL, NULL, 'Сущность сокола', 'Манок пустельги Арторн (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10992, 'Сущность ястреба', '*К вам обращается голос Арторны.*$B$BПоследний и сильнейший из духов, о которых идет речь в книге Ворона. Его пленили далеко от Скеттиса, в святилище на далеком острове на юго-востоке от Аукиндона.$B$BКажется, это описание больше всего подходит к острову, который мы зовем Вершина Крыльев Скорби.$B$BСогласно табличке, страж ястреба практически неуязвим для птичьих когтей. Забудь о грубой силе, обрушь на врага силу звезд. Не повторяй ошибки ястреба.', 'Одолейте стража Ястреба и принесите сущность ястреба Арторне Песне Ветра в Вечную рощу.', 'Мы собрали все сущности, и Мортис Шелест Крыла должен отыскать способ создать из них амулет, который поможет бросить вызов богу-ворону, извлечь его из Изумрудного сна и одолеть. Я пошлю ему свои записи про духов, надеясь, что он осознает их ценность.$B$BЯ приготовила для тебя оберег, и его благословили все духи.', 'Удалось ли тебе одолеть стража ястреба и освободить сущность его души ?', NULL, NULL, 'Сущность ястреба', 'Манок пустельги Арторн (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10993, 'Возвращение в Кенарийский приют', 'Отнеси все сущности Мортису Шелесту Крыла, и расскажи ему обо всем, что мы узнали про бога-ворона.$B$BМортис лучше всех знает, как при помощи этих сущностей и полученных сведений вызвать Анзу на бой. Торопись, ведь неизвестно, сколько Клинтар и Хранители снов смогут противостоять натиску ворона!$B$B*Только вы собираетесь уходить, как Арторна хватает вас за руку.*$B$BПожалуйста, передай Мортису, что я очень тебе помогла. Я боюсь, что он не поймет, как много я сделала!', 'Отнесите сверток Арторны Мортису Шелесту Крыла в Кенарийский приют.', '*Мортис разворачивает сверток и достает из него записи Арторны. Он читает их, не говоря ни слова об авторе.*$B$BС одной стороны, полезно понять, кто твой враг, но Анзу очень силен. Да, необходимо точно представлять себе природу противника и знать его имя, но мы не готовы выступить против него.', 'Я давно жду вестей от Арторны. Что тебе удалось узнать?', NULL, NULL, 'Сверток Арторн (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10994, 'В поисках лунного камня', 'Если воссоединить эти сущности в редком самоцвете, лунном камне реки Строптивая, ты сможешь вызвать на бой Анзу.$B$BЕсть одно затруднение - такие камни можно найти лишь на стороне Азшары, на скалах рядом с истоком.$B$BПоследняя попытка ночных эльфов добыть эти камни окончилась плачевно. Их лодка все еще стоит на якоре там, где они заметили лунные камни. Смотри в оба и подбирайся к нужному месту по суше, со стороны Азшары.', 'Принесите лунный камень реки Строптивая Мортису Шелесту Крыла в Кенарийский приют.', '*Кажется, Мортис не знает, то ли смеяться над вашей историей, то ли ужасаться, как близки вы были к тому, чтобы лишиться камня. В конечном итоге он просто смотрит на сияние самоцвета.*$B$BЯ немедленно возьмусь за работу и волью в него сущности духов птиц. Скоро ты сможешь бросить вызов нашему врагу.', 'Похоже, тебе пришлось пройти сквозь суровые испытания. Неужели лунный камень так тяжело добыть?', NULL, NULL, 'Лунный камень из реки Строптивая', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10995, 'У Груллока два черепа', 'На востоке, на конечной станции Драконья Пагуба, находится Окаянная лощина. Там обитает Груллок, сын Груула, и строит свои тупые планы.$B$BЯ слышал, что один предмет из его сокровищ был у него похищен хитростью. Это не ты ли $gсделал:сделала:? Жаль, что ты его при этом не $gубил:убила:.$B$BЕсли мы хотим вернуть себе свободу, то ты забери у него самое его драгоценное сокровище, драконий череп. Его отец убил многих Черных драконов, и теперь Груллок похваляется этим черепом! Добыть его можно только одолев его.', 'Добудьте драконий череп Груллока.', 'Воистину, это был нелегкий бой, $C. Я испытываю великое облегчение от того, что он больше не дышит нам в затылок.$B$BЯ отошлю этот череп Фырку на хранение. Начинаю думать, что при твоей помощи мы, возможно, и избавимся от наших бед.', 'Груллока больше нет?', NULL, NULL, 'Драконий череп Груллока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10996, 'Сундук с сокровищами Маггока', 'На Островерхом гребне – наверху и к юго-востоку – рыщет Маггок. Его отец велел ему охранять восточные горные кряжи, и радость его только в том, чтобы стращать и убивать все живое на своем пути.$B$BПоскольку он – сын Груула, он должен быть уничтожен ради выживания моего клана. И это сделаешь ты.$B$BМаггок постоянно таскает с собой сундук с сокровищами. Принеси мне его драгоценный сундук в знак победы над ним! А себе можешь взять все, что в этом сундуке найдешь.', 'Добудьте сундук с сокровищами Маггока.', 'Говоришь, он пуст? Жаль – но ты сам видишь ту тупую жестокость, с которой нам приходится сталкиваться.$B$BТеперь, когда Маггок мертв, мы на шаг приблизились к осуществлению моей мечты о доме для огров и о том времени, когда мы сами будем определять нашу судьбу.', 'Сундук при тебе?', NULL, NULL, 'Сундук с сокровищами Маггока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10997, 'Даже у гроннов есть штандарты', 'Приходилось ли тебе бывать в Шаттрате, $C? Над городом, на северо-западе есть место, называемое Защитные холмы, куда можно добраться только по воздуху.$B$BОдин из сынов Груула, Слааг, укрылся там и захватил власть над ограми из клана Гордунни, что живут там. Хотя он и далеко отсюда, мы не можем позволить ему хозяйничать там - иначе он вернется, когда его братья будут все перебиты.$B$B$N, Иди туда и принеси его штандарт в доказательство того, что ты $gпокончил:покончила: с ним.', 'Добудьте штандарт Слаага.', 'Какое облегчение! Слааг мертв. Больше над нами не будет висеть угроза его возвращения!$B$BЕсли ты не против, я возьму штандарт себе как символ надежды для всех огров здешних гор.$B$BБлагодарю тебя, $N.', 'Ты возвращаешься со штандартом Слаага в руке?', NULL, NULL, 'Штандарт Слаага', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (10998, 'Черно(книжн)ый бизнес', 'Осталось убить еще одного гронна – Черепона Разрушителя Душ. Он прячется, но есть способ выманить его. $B$BЕго учил один огрский чернокнижник, известный под именем Вим\'гол Зловещий, и ты $gдолжен:должна: добыть его черную книгу!$B$BВим\'гола тебе придется вызвать лично, как и четырем твоим спутникам. Все вы должны встать каждый в свой огненный круг, расположившись по кругу. Найди Круг Вим\'гола в горах на северо-востоке отсюда, у Скалистых пустошей.$B$BИ если ты, $N, услышишь, как Вим\'гол говорит о том, что собирается вырасти, возвращайся в огненный круг!', 'Добудьте гримуар Вимгола Зловещего.', 'Мне боязно даже прикасаться к этой нечестивой книге. Но нам придется ее читать, если мы хотим проникнуть в суть знаний, что в ней имеются, и выманить Черепона из укрытия!', 'Удалось ли тебе призвать Вимгола Зловещего и вырвать черную книгу из его мертвой хватки?', NULL, NULL, 'Гримуар Вимгола Зловещего', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11000, 'В сердце Разрушителя Душ', 'Этот гримуар – ключ к падению Черепона.$B$BПрочитай отрывок из книги у холма Разрушителя Душ, чтобы начать обряд. Появится объект, именуемый разрушителем душ, а с ним призраки жертв Черепона, которые попытаются его уничтожить. Не дай им сделать это, пока Черепон не появится в мире полностью.$B$BИди на север через каньон Кинжальной Пасти, холм будет по другую сторону Круга Крови. Это на правой стороне перед логовом Груула.$B$BПринеси мне душу Черепона.', 'Добудьте душу Черепона.', 'Кончено, значит. Ты освободил нас от оков сынов Груула. Ты спас клан Кровавого Молота от полного укничтожения.$B$BСловами не выразить, в каком долгу перед тобой ВСЕ огры Острогорья, как Кровавый Молот, так и Камнероги, $N.$B$BСмотри вниз - уже теперь огры собрались воздать тебе почести. Пусть Груул и его марионетка, старый король Молгар, прячутся в его логове. Иди же к ограм вниз, как наш новый король!', 'Где же душа Черепона?', NULL, NULL, 'Душа Черепона', 'Гримуар Вимгола (Прилагается)', 'Рекомендуемое количество игроков: 5', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11001, 'Изгнание бога-ворона', 'Мы должны, не теряя времени, положить конец бесчинствам бога-ворона. Чтобы выманить его из относительной безопасности Изумрудного Сна, тебе понадобится лунный камень Сущности.$B$BСпустившись в Сетеккские залы, войди в тот зал, что находится перед королевским, и вставь лунный камень в когти ворона.$B$BПусть Анзу поверит, что его призывают в мир последователи. Как только он воплотиться, не знай пощады!', 'Убейте бога-ворона и возвращайтесь к Мортису Шелесту Крыла в Кенарийский приют.Это задание выполняется только в героическом режиме.', 'Рад тебя видеть, $N. Победа над богом-ворон стоит всех испытаний, которые я мог бы тебе задать, вместе взятых.$B$BТы действительно достоин знаний, собранных друидами-воронами за долгие века.', 'Какие вести из Сетеккских залов? Повержен ли Анзу?', NULL, NULL, 'Анзу убито', 'Лунный камень Сущности', 'Материалы Мортиса', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11002, 'Падение Магтеридона', 'Источник, откуда Иллидан Ярость Бури получал новых орков Скверны для своего воинства, уничтожен. Фабрика прекратила выпуск своей зловещей продукции, или хотя бы приостановила его на время. Все, что от нее осталось – несколько безделушек, и эта отрубленная голова: достойный трофей для героя Альянса!$B$BОтнеси голову Магтеридона Данату Троллебою в Оплот Чести.', 'Доставьте голову Магтеридона командиру армии Данату Троллебою в Оплот Чести на полуострове Адского Пламени.', 'Это победа не только над Иллиданом, $N. Не стоит забывать о Легионе. Побежден сам командир властителей преисподней. Теперь осада цитадели Адского Пламени для Пылающего Легиона не имеет никакого значения. Скорее всего, они бросят все силы на Черный храм.$B$BСкоро для Иллидана настанет час расплаты...', 'Наконец-то здесь стало тихо – впервые на моей памяти!', NULL, NULL, 'Голова Магтеридона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11003, 'Падение Магтеридона', 'Источник, откуда Иллидан Ярость Бури получал новых орков Скверны для своего воинства, уничтожен. Фабрика прекратила выпуск своей зловещей продукции, или хотя бы приостановила его на время. Все, что от нее осталось – несколько безделушек, и эта отрубленная голова: достойный трофей для героя Орды!$B$BОтнеси голову Магтеридона Назгрелу в Траллмар.', 'Доставьте голову Магтеридона Назгрелу в Траллмар на полуострове Адского Пламени.', 'Это победа не только над Иллиданом, $N. Не стоит забывать о Легионе. Побежден сам командир властителей преисподней. Теперь осада цитадели Адского Пламени для Пылающего Легиона не имеет никакого значения. Скорее всего, они бросят все силы на Черный храм.$B$BСкоро для Иллидана настанет час расплаты...', 'Наконец-то здесь стало тихо – впервые на моей памяти!', NULL, NULL, 'Голова Магтеридона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11004, 'Мир Теней', 'Во время нападения на Скеттис небесный командир Адарис был серьезно ранен, и с тех пор он без сознания.$B$BБоюсь, он впал в горячечный бред, но иногда его сознание проясняется, и он требует, чтобы я приготовил эликсир из теневой пыли араккоа. Он думает, что это зелье поможет ему \"заглянуть в мир теней\", где таятся истинные предводители араккоа.$B$BЯ, разумеется, не верю в эту чушь, но капитан не успокоится, пока не получит свой эликсир. Вы поможете нам?', 'Проберитесь в Скеттис и добудьте 6 горстей теневой пыли с местных араккоа, после чего отнесите пыль Северину.', 'Благодарю вас, $N. Я дам немного капитану, надеюсь, это его успокоит. А остальное оставьте себе, может, еще пригодится.', 'Вы принесли мне пыль, $N?', NULL, NULL, 'Теневая пыль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11005, 'Тайны жрецов Когтя', 'Спасибо, что выслушали мой горячечный бред. Все это время мы пытались обнаружить и уничтожить командование Скеттиса, и нам удалось узнать о трех так называемых жрецах Когтя, но в глаза мы их никогда не видели. И теперь стало ясно, почему.$B$BПоговорите с Северином – пусть приготовит вам еще своего эликсира, тогда вы сможете разыскать трех жрецов Когтя: Ишааля, Скиззика и Зеллека. Говорят, они обитают в Гнездовье Ала\'рак, у восточного берега озера Черного Ветра.', 'Возьмите у Северина эликсир теней и с его помощью найдите и убейте жрецов Когтя: Ишааля, Скиззика и Зеллека в Скеттисе. После этого вернитесь к командиру Адарису.', 'Вы отлично поработали, $N. Убийство жрецов станет очень сильным ударом для наших врагов.', NULL, NULL, NULL, 'Жрец Когтя Ишааль убито', 'Жрец Когтя Скиззик убито', 'Жрец Когтя Зеллек убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11006, 'Больше теневой пыли', '', '', 'Приносите мне еще пыли, и я приготовлю столько эликсиров, сколько потребуется.$B$BПриказ командира.', NULL, NULL, NULL, 'Теневая пыль', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11007, 'Кель\'тас и зеленеющая сфера', 'Воздух вокруг вас наполняется легким гудением. Наару известно о вашей победе. Кажется, они хотят, чтобы вы забрали эту сферу с еще не остывшего тела Кель\'таса Солнечного Скитальца. Какие секреты она скрывает?$B$BВозможно, А\'дал в Шаттрате сможет вам что-то разъяснить.', 'Отнесите зеленеющую сферу А\'далу в Шаттрат.', '<Мысли А\'дала звучат в вашем сознании: $B$BСфера... Очень странно. Он был жив? Да, он здесь, заключен в эту сферу. Он изувечен. Он взывает в высшей силе. Нет, не к Иллидану.$B$BВыше. $B$BКил\'джеден Искуситель грядет... $B$BНет, не сюда он явится... $B$B<А\'дал уводит ваши мысли в иное место: $B$BАзерот. Неизвестно. $B$BОтдыхай. Теперь твои братья и сестры отвоюют Крепость Бурь. $B$B<А\'дал поет песнь битвы.>', 'Ты услышал мой зов...', NULL, NULL, 'Зеленеющая сфера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11008, 'Огонь над Скеттисом', 'Думаете, что можете присоединиться к Страже Небес? Сначала нам нужно посмотреть, как вы поведете себя в воздухе.$B$BМестные араккоа выводят прожорливых боевых животных, а потом натравляют их на наших разведчиков. Вот, возьмите эту взрывчатку и сбросьте на гнезда, которые находятся на верхушках домиков араккоа. Только не попадитесь этим чудовищным калири, которые охраняют гнезда – оглянуться не успеете, как они сбросят вас на землю.', 'Найдите яйца чудовищных калири на верхушках домов Скеттиса и сбросьте на них взрывчатку Стражи Небес, после чего вернитесь к небесному сержанту Дорину.', 'Отличная работа, $N! Теперь наши разведчики смогут летать спокойно.', 'Ты уже выполнил мое поручение?', NULL, NULL, 'Уничтожено яиц чудовищной калири', 'Взрывчатка Стражи Небес (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11009, 'Огрские небеса', 'Теперь, когда ты $gизбавил:избавила: нас от уз, мы можем начать объединение кланов. Это займет много времени, ибо старые обиды нелегко забыть.$B$BНо ближе к делу: отправляйся в Огри\'ла, что под небесами на западе. Ты $gдолжен:должна: защитить ее и нас от тех сил, от которых нас раньше защищали гронны – от духов Астрала, демонов и самых страшных – черных драконов.$B$BКогда найдешь этот рай огров, ищи мудрости у Чу\'а\'лора. Он знает, что делать дальше.', 'Поговорите с Чу\'а\'лором в Огри\'ле в Острогорье.', 'Могдорн прислал вперед весть, говоря чтобы я ждал тебя. Я рад, что ты пришел.$B$BРаз с сынами Груула покончено, разные населители этих горных террас и тех что на севере начнут охотиться на наших братьев-огров внизу, и это только вопрос времени.$B$BЯ верю, что ты поможешь нам это не допустить, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11010, 'Бомбардировка', 'Ну, есть у тебя воздушный транспорт, и что? Ты думаешь, этого достаточно, что ли?$B$BЛагеря Легиона Гнев и Ужас на севере и юге – вот сущее шило у меня в заднице! Они еще и угрожают мирной Огри\'ла... Эти проклятые пушки Скверны лупят по Страже Небес справа и слева, и мы не можем пробиться сквозь заградительный огонь и выполнить свой долг.$B$BХочешь показать себя? Бери бомбы и разнеси их боеприпасы! И постарайся, чтобы они сами тебя не сбили!', 'Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес.', 'Ха-ха, я так и знала, что вы в конце концов их уделаете! Хорошая работа! Может, старина Келлер и ошибался на ваш счет.$B$B<Небесный сержант Вандерлип ухмыляется.:', 'Ну как – еще не разделались с их пушечными ядрами?', NULL, NULL, 'Уничтожено груд пушечных ядер', 'Бомбы Стражи Небес (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11011, 'Вечная бдительность', 'Победа над Анзу, богом-вороном, настоящий подвиг. Но боюсь, он не оставит своей затеи вернуться в Запределье.$B$BПока у него остаются последователи, он может снова восстать из праха. На всякий случай держи при себе лунный камень Сущности.', 'Попросите у Мортиса Шелеста Крыла лунный камень Сущности.', 'Держи при себе этот лунный камень. Если тебе покажется, что Анзу набирается сил, чтобы снова вернуться в мир, камень поможет одолеть его еще раз.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11012, 'Клятва в верности Крыльям Пустоты', '', '', 'Наши земли потеряны, наши дети похищены под покровом ночи, проданы в рабство, а то и того хуже...<Голос Морденая срывается.>Пора, мой соратник, пришло время все вернуть! Ты проявил себя как отважный воитель и к тому же отзывчив душою.Обещаешь ли ты помочь клану Крыльев Пустоты вернуть наши земли и восстановить наши дома? Клянешься ли ты поддерживать наше племя, пока род не будет продолжен? Поклянись, и мы начнем битву за наши дома и наших близких!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11013, 'В услужении у Иллидари', 'Кряж Крыльев Пустоты... Там где когда-то был бастион Крыльев Пустоты, теперь кишат орки из клана Драконьей Пасти. Хотя они полностью контролируют эту территорию, наша магия там еще сильна, достаточно сильна для того, чтобы скрыть твой подлинный облик и позволить тебе проредить ряды клана.$B$BЯ приготовил тебе вот это письмо, для их лидера – воеводы Мор\'гора. Отправляйся прямо в пасть к Драконьей Пасти и найди там их лагерь, где ты начнешь новую жизнь – орка Скверны и верного слуги Иллидана Ярости Бури.', 'Отправляйтесь на кряж Крыльев Пустоты и доставьте докладные записки иллидари воеводе Мор\'гору, в лагере Драконьей Пасти.', '<Мор\'гор читает письмо и смеется.>$B$BРыцарь смерти? Да ты сапоги им лизать недостоин, салага.$B$B<Мор\'гор оглядывает вас с ног до головы.>$B$BОднако... Ты сможешь начать с батрака, либо я просто брошу тебя в яму и оставлю подыхать...', '<Мор\'гор рычит.> Ты опоздал...', NULL, NULL, 'Служебные бумаги Иллидари (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11014, 'Задание десятника', '$gМор\'гор комкает служебную записку и выбрасывает ее.: Хорошо $gприятель:подруга: сначала о главном. Если ты хочешь присоединиться к моей прославленной армии клана Драконьей Пасти, тебе придется попотеть. Здесь работают все! Получай задание и смотри не отлынивай, а я посмотрю, к чему тебя еще можно будет пристроить.$B$BОтправляйся к надсмотрщику Варкулу Дыханию Дракона, найдешь его в центре города, он проверит, на что ты годишься, и назначит тебе задание.$B$BА теперь убирайся с глаз моих.', 'Поговорите с надсмотрщиком Варкулом Дыханием Дракона в лагере клана Драконьей Пасти.', 'Варкул пристроит тебя к делу, рубака. Будешь заниматься тем, что лучше всего умеешь, и что будет полезно для сбора кристаллов. Задания будешь получать по одному в день.$B$BРаботенка преимущественно грязная, но даже лучшим из лучших в свое время пришлось пройти через это.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11015, 'Кристаллы Крыльев Пустоты', 'Ни к чему не годен? Ну, это уже что-то. Даже полным тупицам вроде тебя здесь найдется работа. Находи на кряже всяких тварей и убивай их. Иногда на их тушках обнаруживаются кристаллы, собери их и принеси мне, и я приму у тебя сегодняшнюю работу.', 'Принесите 30 кристаллов Крыльев Пустоты надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти.', 'На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.', 'Кристаллы Крыльев Пустоты, используются во многих предметах, в большинстве своем в оружии и доспехах.', NULL, NULL, 'Кристалл стаи Крыльев Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11016, 'Шкуры живодеров-пустокопов', 'Скорняк, говоришь? Ну здесь-то кожи в избытке. Вокруг месторождений кристаллов можно найти уйму живодеров. Убей их и забирай шкуры. Хотя у некоторых из них, шкуры попрочнее, чем у остальных, этих принесешь мне,', 'Принесите 35 шкур живодеров-пустокопов из Копей Пустоты надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти в долине Призрачной Луны.', 'На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.', 'Нам нужны эти шкуры на подкладку для брони и прочие технические нужды.', NULL, NULL, 'Шкура живодера-пустокопа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11017, 'Пыльца пустопраха', 'Цветочки собираешь? Забааавно... К сожалению, наши маги и шаман нуждаются в твоих услугах. Кусты пустопраха, что растут на этом уступе, вырабатывают особенную пыльцу, которая необходима им в их колдовстве. Принеси мне этой штуки, и я приму у тебя сегодняшнюю работу.', 'Принесите 40 порций пыльцы пустопраха надсмотрщику Варкулу Дыханию дракона в лагерь Драконьей Пасти.', 'На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.', 'Как я уже говорил, пыльца пустопраха используется нашими заклинателями.', NULL, NULL, 'Пыльца пустопраха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11018, 'Хаотитовая руда', 'Привет шахтерам! $B$B<Варкул отдает честь.>$B$BНастоящий орк, клянусь собственным сердцем! Варкул тоже когда-то начинал в шахте. Нет ниче лучше, чем ковыряться в грязи под землей, правда?$B$BТеперь выбирайся оттуда и отыщи эти, как их... хаотитовые залежи. Вычисти их полностью, и принеси мне всю руду.', 'Принесите 40 порций хаотитовой руды надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти в долине Призрачной Луны.', 'На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.', 'Эти умники там, собираются использовать эту руду, чтобы укрепить наше оружие и доспехи.', NULL, NULL, 'Хаотитовая руда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11019, 'Друг в тылу врага', '', '', 'Не думай, что тебе придется встретиться с армией орков Скверны в одиночку.*В глазах Ярзила мерцают синие искры.*Так вот мы здесь с тобой, $N. В любой услуге, которую ты сможешь оказать оркам Скверны, действуя во имя отвоевания земель Крыльев Пустоты, мы будем рядом, чтобы удостовериться, что все идет по нашему плану.Тебе надо вести себя осторожно и не привлекать к себе нежелательного внимания во время твоих акций саботажа.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11020, 'Медленная смерть', 'Клан Драконьей Пасти разместил своих батраков возле каждой друзы кристаллов. Убийство средь бела дня привлекло бы слишком много нежелательного внимания к тебе, но я знаю, как уменьшить количество батраков и не навлечь подозрения Мор\'гора.$B$BОтправляйся в дебри долины Призрачной Луны и убей несколько больных животных. Возьми их порченые железы. Смешай их с бараниной, которую я дам тебе, и разбросай около батраков. Достаточно будет одного укуса, чтобы они смертельно отравились!', 'Возьмите у Язрилла Наемника из долины Призрачной Луны баранину. Смешайте ее с оскверненными железами и отравите 12 лагерей батраков из клана Драконьей Пасти.', '*Ярзил тихо шепчет.* Отличная работа, $N. Теперь надо затаиться. Приходи ко мне завтра, и мы пропробуем повторить этот трюк.', 'Это грязная работенка, $N.', NULL, NULL, 'Заражено лагерей батраков из клана Драконьей Пасти', 'Баранина Ярзилла (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11021, 'Альманах Ишааля', 'Эта таинственная книга взята с тела жреца Когтя по имени Ишааль. В ней содержатся чародейские символы и изображения небесных существ, которых вы никогда не видели.$B$BВесь текст написан на неизвестном языке, возможно, на древнем наречии араккоа. Наверное, стоит отнести эту книгу небесному командиру Адарису.', 'Принесите альманах Ишааля небесному командиру Адарису к северу от Скеттиса.', 'Что это вы мне принесли? Я не могу ничего разобрать, $N... Наверное, от потери крови мое зрение ослабло.', 'Вы хотите мне что-то показать?', NULL, NULL, 'Альманах Ишааля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11022, 'Разговор с Мог\'доргом', '$gВладыка:Владычица: $N! Говори с Мог\'доргом Мудрым, прежде чем ходить в Огри\'ла!', 'Поговорите с Мог\'доргом Мудрым. Он находится на вершине башни на восточной стороне Круга Крови в Острогорье.', 'Сударь мой, я рад, что ты решил еще раз поговорить со мной прежде, чем уйти.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11023, 'Еще разок задать им жару!', 'У нас все еще проблемы с этой клятой зенитной артиллерией, $N! $B$BНе подведи меня – я считаю, что в прошлый раз ты блестяще $gсправился:справилась: с заданием – но эти проклятые демоны, похоже, пополняют свои запасы снарядов куда быстрее, чем мы их уничтожаем. А, значит, нам приходится тратить демонову уйму времени и гонять туда наших бойцов, не говоря уж о том, какую угрозу эти демоны представляют для Огри\'ла!$B$BЧто скажешь? Слетаешь еще разок?', 'Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес.', 'Выдающаяся работа, $N! Я бы еще раз отправила вас на вылет, но тутошняя политика велит давать нашим пилотам время на отдых, даже вопреки их желанию. Простите, правила не я устанавливаю, но, демон меня побери, я их выполняю!$B$BЗавтра свидимся, ас!', 'Ну, как бомбардировка?', NULL, NULL, 'Уничтожено груд пушечных ядер', 'Бомбы Стражи Небес (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11024, 'Союзник в Нижнем городе', 'В Нижнем городе живет араккоа по имени Рилак... Ему можно доверять. Отнесите ему книгу...$B$B<Адарит отдает вам книгу и теряет сознание.:', 'Принесите альманах Ишааля Рилаку Освобожденному в Нижний Город Шаттрата.', 'Не может быть... Это когда-то принадлежало жрецу Когтя... Откуда вы это взяли?', 'От вас так и разит Скеттисом! Немедленно объяснитесь!', NULL, NULL, 'Альманах Ишааля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11025, 'Кристаллы', 'Если с этими кристаллами гор обращаться правильно, они источают странную силу, которая наделяет живых существ ясностью ума. Мы обрели просветление тут, в Огри\'ла.$B$BВсе существа с вершин гор ищут осколки этих кристаллов и используют их для своих целей. Кристаллы даже начали продавать!$B$BЧтобы помочь нам, найди осколки апексита и принеси их мне. Их можно отобрать у существ, бродящих поблизости, или найти там, где у крупных кристаллов роются камнедеры.', 'Добудьте 5 осколков апексита. +250 ед. репутации с Огри\'ла', '*Левая голова Чу\'а\'лора начинает говорить.* $B$BЭто то, что надо.$B$BЗапомни, $N, ценность осколков не в цене. Даже не в том, что они могут сделать для тебя, если оковать их как следует, хотя об этом спорят.$B$B*Его правая голова заканчивает,...*$B$BИстинная их ценность в том пути, который надо проделать, чтобы их добыть.', 'Когда ты проникнешь в суть осколков и кристаллов, ты лучше сможешь защищать нас и наших братьев-огров внизу.$B$BСами осколки получили свое название от древней ныне мертвой цивилизации араккоа, что жили на вершинах здешних гор.$B$BТы принес осколки?', NULL, NULL, 'Апекситовый осколок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11026, 'Гони демонов!', 'Ты как раз вовремя, друг! Нам нужна помощь. За это ты получишь одну редкую вещь, которая под конец поможет нам обоим.$B$BМы уже не жестокие огры, но тутошние демоны грозят перерезать и нас, стражу Небес. Беда в том, что как убьешь демона, он тут же приходит назад в новом теле!$B$BНо если ты возьмешь кристалл и сделаешь портал изгнания, то если их убивать рядом с ним, их субстанции втянет в портал, и они уйдут откуда пришли!', 'При помощи кристалла изгоните 15 демонов из Лагеря Легиона: Гнев или Ужас в Острогорье.', 'Это им урок! А теперь, конечно, будет награда.$B$BДемоны из лагеря Легиона: Гнев, что на севере, сделали особый транспортер на своей южной границе. Этот экспериментальный портал использовался для расширения лагеря, и мы думаем, тебе не надо говорить, что будет, если он слишком расширится.$B$BОднако на твоем месте мы бы отнесли Гаку вот эту те$Nю руну и спросили его, чем помочь. Ты только полегче с ним, $N. Он, как и ты, тут новенький.', 'Мы так думаем, ты использовала кристалл изгнания, чтобы послать целую кучу этих демонов Пылающего Легиона паковать вещички?!', NULL, NULL, 'Изгнано демонов', 'Кристалл Изгнания (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11027, 'Есть у тебя темная руна?', '', '', '', NULL, NULL, NULL, 'Темная руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11028, 'Оставшееся время', 'В этом альманахе предсказано возвращение Терокка, самого могущественного и ужасного короля Скеттиса в истории араккоа.$B$BЯ всегда считал, что это только легенда, $N, однако возвращение жрецов когтя и вот этот том утверждают обратное.$B$BВозвращение Терокка близится с каждым днем, и наш единственный шанс - выдернуть его в этот мир неподготовленным. Возвращайтесь в Скеттис и поговорите с Адарисом - будем надеяться, у него хватит мудрости, чтобы не ошибиться в выборе.', 'Расскажите небесному капитану Адарису о возвращении Терокка. Вы сможете найти его в лагере Черного Ветра в лесу Тероккар.', 'Араккоа хотят призвать Терокка из-за завесы времени, а Рилак... хочет ускорить процесс? Он что, совсем спятил?$B$B*Силы покидают Адариса, и он укладывается обратно*$B$BВы сделали все, что нужно, $N. дальше действовать будут мои люди - это исключительно военное дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11029, 'Потрепанная маскировка', 'Открывайте, $N. Это маскировочный костюм. Выглядит не очень-то убедительно, да?$B$BЯ шью их для астральных контрабандистов, которые ищут редкие книги. В центре Скеттиса, в местечке под названием Покой Терокка, живет писатель араккоа - совсем старый и почти слепой.$B$BНаденьте этот костюм и постарайтесь выманить у него книгу \"Кровная вражда\". Но будьте осторожны - других араккоа этот костюм не обманет.', 'Оденьтесь в потрепанный маскировочный костюм араккоа, возьмите книгу \"Кровная вражда\" у Сахаака и вернитесь к Хаззику.', 'Отлично! В этой книге говорится обо всех потомках древнейших врагов Терокка. Есть пророчество, что после их смерти Терокк вернется.', 'Ну как, $N, достали книгу?', NULL, NULL, 'Кровная Вражда', 'Поношенный наряд араккоа (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11030, 'Наш мальчик хочет быть следопытом Стражи Небес', '$C, у нас есть одна проблема – у нас много сыновей. И поскольку рядом обосновалась Стража Небес, наши сыновья только и говорят, что хотят вступить в ее ряды.$B$BБудучи гордым отцом, мы хотим для них самого лучшего. Потому не сходишь ли ты к хрустальной кузнице Скверны в лагерь Легиона на север или юг, чтобы добыть магический настой для наших сыновей? Иди на зеленый дым – и найдешь лагерь.$B$BМы думаем, что на настой пойдет десять апекситовых осколков. Мы бы их тебе дали, да у нас нету.', 'Добудьте нестабильный настой Зверя.', 'Ты наш спасатель, $N. Наши мальчики узнают это с таким восторгом! $B$BЛадно, одно дело сделано, другое еще нет. Мы не говорили тебе про другой настой, которы им будет нужен, а?', 'Ты уже добыл этот магический настой? Для Торкуса-младшего он имеет большое значение.', NULL, NULL, 'Нестабильный настой Зверя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11031, 'Перестать быть верховным магом из Аметистового Ока', '', '', 'В следующий раз выбирай более тщательно. Мы делаем все, что можем, для наших союзников, но даже ресурсы Даларана не бесконечны.', NULL, NULL, NULL, 'Аметистовый перстень верховного мага', 'Требуется денег: 75', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11032, 'Перестать быть защитником из Аметистового Ока', '', '', 'В следующий раз выбирай более тщательно. Мы делаем все, что можем, для наших союзников, но даже ресурсы Даларана не бесконечны.', NULL, NULL, NULL, 'Аметистовый перстень Великого Защитника', 'Требуется денег: 75', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11033, 'Перестать быть убийцей из Аметистового Ока', '', '', '', NULL, NULL, NULL, 'Аметистовый перстень искусного убийцы', 'Требуется денег: 75', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11034, 'Перестать быть исцелителем', '', '', '', NULL, NULL, NULL, 'Аметистовый перстень Восстановления', 'Требуется денег: 75', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11035, 'Недружелюбные небеса', 'На северо-восточном краю этого острова есть док, в котором пакуют и вывозят кристаллы Крыльев Пустоты и прочие реликвии. Перевозчики из клана Драконьей Пасти транспортируют товары от дока до клановой крепости, в то время как лидеры клана охраняют это место от любого, кто осмелится напасть.$B$BЕдинственный путь добраться туда и напасть на клан, – Заоблачная тропа Драконьей Пасти.$B$BЛети к расколотым островам по Небесной дороге и устрой там засаду на перевозчиков, которые пользуются этим маршрутом. Возврати наши утраченные реликвии!', 'Верните Язриллу Наемнику в лагере Драконьей Пасти в долине Призрачной Луны 10 реликвий Крыльев Пустоты.', '*Ярзилл шепчет.*$B$BТы оказываешь Крыльям Пустоты большую услугу, $N. Шаг за шагом мы покончим с Драконьей Пастью. Рыба гниет с головы и с каждым днем все сильнее и сильнее... $B$BВозвращайся завтра, если тебя еще интересует работа на Заоблачной тропе.', 'Мертвые орки не кусаются, $N. Убедись, что ни один перевозчик из клана Драконьей Пасти не уйдет.', NULL, NULL, 'Реликвия стаи Крыльев Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11036, 'Еще один пункт долой!', 'Я первым признаюсь, что не знаю, зачем ему это, но указания ведущего ракетостроителя Фьюзеляжа весьма конкретны – только лучшие плоды, законсервированные для долгого путешествия и запечатанные, чтобы предохранить их от действия стихий. $B$BЕсть и другие указания – там невесомость, тут низкое давление. Я даже не пытаюсь понять, но платит он хорошо, так что вот тебе эта суперпровизия. Доставь ему этот ящик в Зону 52. Как попадешь в Пустоверть, держись дороги, которая приведет тебя прямо в город.', 'Доставьте консервированные фрукты командующему ракетами Фюзеляжу в Зону 52 Пустоверти.', '<Командир осматривает содержимое ящика.>$B$BВроде бы все как надо. Можем вычеркнуть из списка еще один пункт. Теперь только остается сделать так, чтобы ракета оторвалась от земли!', 'Это поставка от старины Орока?', NULL, NULL, 'Консервированный фрукт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11037, 'Странное видение', 'Мне было странное видение, $N. Я так и не понял, что оно значит. Я видел стрелу, огро$Nю стрелу с огненным оперением, устремленную в небо. Для опытного чародея сотворить что-то подобное - раз плюнуть, но я почему-то уверен, что эта стрела - не творение магов.$B$BЭто совсем не похоже на то, что умеют и могут мастера Азерота. Разыщи тех, кто создал эту стрелу, $N. И предложи им свою помощь, ибо не исключено, что без помощи со стороны все их усилия пропадут втуне.', 'Поговорите с ведущим ракетостроителем Фьюзеляжем в Зоне 52. ', '<Командующий внимательно слушает рассказ о видении провидца.>$B$BМне ничего не известно об этом, но мы, безусловно, воспользуемся твоей помощью. Видишь вон ту громадину у меня за спиной? Это X-52...$B$BТы когда-нибудь видел подобную красоту?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11038, 'Помощь экзарху Орелису', 'Недавно верховная жрица Ишана отправила в Пустоверть группу отшельников под началом экзарха Орелиса. Они должны были проследить за действиями Кель\'таса и его приспешников, но пока что от них не поступило никакой информации.$B$BБоюсь, что у нас не хватит сил на это задание, поэтому ваша помощь придется экзарху очень кстати. Не желаете ли отправиться в Зону 52 и помочь ему?', 'Поговорите с экзархом Орелисом в Зоне 52. ', 'Значит, вы хотите помочь нам узнать планы Кель\'таса? Это хорошо. Пустоверть так и кишит агентами эльфов крови, из-за которых эта земля скоро распадется на части.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11039, 'Отчет патрону шпионов Талодиену', 'Не так давно Ворен\'таль отправил в Пустоверть небольшую группу слежения за действиями Кель\'таса. Наш предводитель безоговорочно доверяет патрону шпионов Талодиену и его соратникам, поэтому не отказал ему в просьбе о подкреплении.$B$BОтчет Талодиена был очень кратким, но из него было понятно, что он обнаружил что-то очень важное. Отправляйтесь к нему в Зону 52 и помогите ему всем, чем сумеете.', 'Доложитесь патрону шпионов Талодиену в Зоне 52. ', '<По лицу главы шпионов проскальзывает тень разочарования.>$B$BЯ надеялся, что мне пришлют команду, но если Ворен\'таль решил прислать только вас, то остается лишь скорректировать мои планы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11040, 'Детали для ведущего ракетостроителя', 'Я сотрудничала с гоблинами считаное количество раз – по пальцам одной руки можно пересчитать! Гораздо чаще мы с ними по разные стороны баррикад, но отказать ведущему ракетостроителю Фьюзеляжу я не могу.$B$BЭтот ящик набит деталями, которые мне тут не нужны, но командующий ракетами может использовать их для своего проекта. Не будете ли вы столь любезны доставить их, если вы отправляетесь в Зону 52?$B$BКто знает, может наши славные гномские детальки не дадут его творению взорваться!', 'Доставьте запчасти Босси командующему ракетами Фюзеляжу в Зону 52 Пустоверти.', 'Чтоб я еще знал, на кой нужны некоторые из этих деталей... Нет, я найду им применение, но никогда не думал, что однажды придется научиться думать по-гномски!', 'Похоже, что это ящик гномского мастера-инженера. Стало быть, вас Босси прислала?', NULL, NULL, 'Запчасти Босси (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11041, 'Неоконченное дело', 'Во имя нашего великого мастера... Во славу Иллидана!$B$BПо приказу воеводы Мор\'гора, большое плато кряжа Крыльев Пустоты должно быть зачищено. Все эти драконы из стаи Крыльев Пустоты, захваченные или вызванные из земли, и камнедеры, встающие на дыбы, срывают наши планы по сбору кристаллов.$B$BУбей их всех, и мать стаи, и ее супруга, Арвоара.$B$BТак приказал Мор\'гор!$B$B<Кажется, этому орку не удалось очистить плато. Пришло время доказать свою верность Мор\'гору!:', 'Убейте 10 надземных живодеров и Бараш Мать Стаи. По выполнении вернитесь к властителю Мор\'гору в лагерь Драконьей Пасти.', 'Как докладывает один из моих наблюдателей, ты получил приказ и взял дело в свои собственные руки? Хм... Неплохо. Тебе удалось удивить меня.', 'Кто осмеливается тревожить Мор\'гора? Твои сведения должны быть достаточно важными, иначе...', NULL, NULL, 'Надземный живодер убито', 'Бараш Мать Стаи убито', 'Полупереваренная рука (Прилагается)', 'Рекомендуемое количество игроков: 2');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11042, 'Таинственное видение', 'Меня преследует странное видение, $N. Я вижу столп дыма, поднимающийся в небо вслед за гигантским огнем. Это не природное явление и не исчадие зла - в этом я абсолютно уверен.$B$BЯ не знаю, что это такое. Знаю только, что его создали трудом многих существ. Да... В одиночку это было бы невозможно осуществить. $B$BОтправляйся в Пустоверть, $C. Найди тех, кто сотворил этот дым, и предложи им свою помощь.', 'Поговорите с ведущим ракетостроителем Фьюзеляжем в Зоне 52. ', '<Командующий внимательно слушает рассказ о видении провидца.>$B$BМне ничего не известно об этом, но мы, безусловно, воспользуемся твоей помощью. Видишь вон ту громадину у меня за спиной? Это X-52...$B$BТы когда-нибудь видел подобную красоту?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11043, 'Усовершенствованный грифон', 'Я слышал, что эти дворфы из клана Громового Молота устроили грифоний насест в своей крепости внизу в южной долине Призрачной Луны. Если ты туда идешь, поговори с ними от моего имени, ладно? У меня есть кое-какие идеи насчет того, как бы получше оснастить их грифонов!$B$BЧего останавливаться-то, если можно приделать к ним альтиметр, зеркало заднего обзора и ракету? Представляешь, как быстро можно летать, если привязать к заднице грифона вот такую малышку! Я назову ее \"Турбо-грифон 8000\"!', 'Поговорите с Брюнном Жаробородом в Цитадели Громового Молота в Долине Призрачной Луны.', '<Брюнн начинает медленно багроветь, пока лицо его не становится такого же цвета, что его борода.>$B$BЧТО он хочет сделать с моими грифонами?$B$BЕсли эта мелочь пузатая привяжет к моим грифонам что-то кроме седла, я лично доберусь до Острогорья и затолкаю эту ракету ему в глотку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11044, 'Страшные видения', 'Мой покой часто бывает нарушен видениями катастрофы: с небес на землю обрушивается зеленый огонь, поражая храбрых защитников крепости. Это видение мучает меня уже не одну неделю, но только недавно я осознал, к чему это предзнаменование.$B$BДалеко на востоке, в долине Призрачной Луны, дворфы из клана Громового Молота сдерживают постоянные атаки Пылающего Легиона и других многочисленных неприятелей. Они отчаянно сражаются, но без помощи союзников им не выстоять. Встань на их сторону, $N. Помоги им в их борьбе.', 'Поговорите с командиром звена Нуаинном в цитадели Громового Молота. ', 'Видения, говоришь? Не важно, видения, письмо от престарелой тетушки, или властитель преисподней нашептал. Он попал в самую точку! Важно то, что ты здесь, друг. Нам сейчас пригодится любая помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11045, 'Зорус Ревнитель', 'У долины Призрачной Луны очень непростая история. Мало кто решается войти туда – из страха пробудить к жизни таящиеся в долине ужасы.$B$BОднако смельчаки все же находятся, например, Зорус Ревнитель – он исследует призраки прошлого этой долины. Занятие это очень опасное, так что, думаю, он будет рад любой помощи.$B$BЕсли вы вдруг попадете в долину, поищите там Зоруса – он чаще всего бывает в цитадели Громового Молота, это в самом центре южной части долины.', 'Поговорите с Зорусом Ревнителем в цитадели Громового Молота. ', 'Фантей говорит правду: я действительно с радостью приму вашу помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11046, 'Главный аптекарь Хильдегард', 'У долины Призрачной Луны очень непростая история. Мало кто решается исследовать ее – из страха пробудить к жизни таящиеся в долине кошмары.$B$BОднако смельчаки все же находятся. Главный аптекарь Хильдегард исследует призраки прошлого долины Призрачной Луны – это очень опасное дело; уверен, она будет рада любой предложенной помощи.$B$BЕсли попадешь в ту долину, поищи там аптекаря Хильдегард – наверняка найдешь ее в деревне Призрачной Луны в северо-западной части долины.', 'Поговорите с главным аптекарем Хильдегард в деревне Призрачной Луны. ', 'У Фантея хорошая память. Я уже несколько месяцев не покупала реагентов в Шаттрате. Однако он прав, помощь мне не помешает.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11047, 'Просьба ученика', 'Мне, как подмастерью укротителя ветрокрылов, поручено ухаживать за животными, когда они не летают. Беда в том, что их так мало, что они почти не отдыхают.$B$BБоюсь, что мы их до смерти загоним, если не будет сменных. В деревне Призрачной Луны на западе, что в долине Призрачной Луны, есть большие стойла. Там за обучением всадников и уходом за животными присматривает Дама Буйная Грива.$B$BНе поговоришь ли ты с ней от нашего имени и не расскажешь ли о нашем положении?', 'Поговорите с Дамой Буйногривой в Деревне Призрачной Луны, что находится в Долине Призрачной Луны.', '<Дама выслушивает просьбу Агадая.>$B$BЯ не могу гарантировать, что у меня найдутся сейчас ветрокрылы, но я посмотрю, чем смогу помочь. Мы и так с трудом удовлетворяем спрос других покупателей и застав.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11048, 'Рапорт Крогхана', 'Мне было приказано задержаться в Гарадаре на непродолжительный срок, оценить обстановку, а потом доложить обо всем кровавому стражу Галмоку в деревню Призрачной Луны. Если судить по тому, что я видел, Гарадар только выиграет от долгосрочного сотрудничества с Ордой.$B$BЯ понимаю, что у Галмока сейчас на счету каждый воин, но я думаю, он поймет, что моя миссия здесь еще не закончена. Отправляйся в деревню Призрачной Луны на северо-западе долины Призрачной Луны и объясни кровавому стражу Галмоку, в чем причина задержки.', 'Объясните кровавому стражу Галмоку в деревне Призрачной Луны, почему Крогхан не может явиться к нему.', '<Узнав о решении Крогхана, Галмок недовольно ворчит.>$B$BЯ понимаю его точку зрения, но у нас на счету каждый воин! Легион денно и нощно посылает против нас инферналов. Если Крогхан не торопится возвращаться, ты займешь его место в окопах!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11049, 'Большая Охота', 'Если вдруг в твоих странствиях ты обнаружишь яйца драконов Крыльев Пустоты, не затруднит ли тебя принести их мне?$B$BПредупреждаю, это редкая вещь, не огорчайся, если тебе не удастся найти ни одного. Клан Драконьей Пасти потратил уйму времени и сил, собирая эти яйца и пряча их в разных укромных местах.$B$BИх можно обнаружить у существ, обитающих на острове, возле месторождений кристаллов, в копях, или даже в кустах пустопраха.$B$BНо соблюдай осторожность – мы же не хотим, чтобы Мор\'гор засек тебя?', 'Найдите яйцо дракона Крыльев Пустоты для Язрилла Наемника, находящегося в лагере Драконьей Пасти, что в долине Призрачной Луны.', 'Отлично, $N! Нельтараку будет доволен!', 'Как продвигается охота?', NULL, NULL, 'Яйцо дракона из стаи Крыльев Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11050, 'Собрать их все!', '', '', 'Ты настоящий герой, $N!', NULL, NULL, NULL, 'Яйцо дракона из стаи Крыльев Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11051, 'Демонов – долой!', 'Если мы что-то понимаем в демонах, а мы понимаем, потому что усердно их изучаем, то они быстро устраняют любой урон, нанесенный их драгоценным транспортерам.$B$BСтало быть, если ты хочешь попытать удачи с другой темной руной, возьми еще раз наш кристалл изгнания и уничтожь еще демонов. Кстати, ты ведь хочешь помочь нам справиться с ними?$B$BМы говорили – \"попытать удачи\", потому что результаты получаются разные. Ты можешь получить те$Nю руну, а можешь получить и совсем не то.', 'При помощи кристалла изгоните 15 демонов из Лагеря Легиона: Гнев или Ужас в Острогорье.', 'Мы хотим чтобы процесс создавания темной руны был снабжен защитой от дурака, Фэникс. Увы, сейчас это не так. Прошу, возьми эту сумку и посмотри, что мы сделали сегодня. Мы не в силах видеть это сами.$B$BПомни, если ты получишь те$Nю руну, отнеси ее Гахку и обменяй на хрустальнокованную те$Nю руну. Тогда ты сможешь сразу сломать транспорт Шартуула.$B$BО, Фэникс, не забудь вернуться завтра утром и взять кристалл изгнания. Всегда найдутся демоны, которых надо изгнать.', 'Такой опытный профессионал с легкостью сможет изгнать демонов. Правда же, $C?', NULL, NULL, 'Изгнано демонов', 'Кристалл Изгнания (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11052, 'Обещание Акамы', '<Акама вставляет кристалл в медальон, который держит в руке.>$B$BЯ уже не так силен как прежде, $N. Так тесно общаться со злом все эти годы, я не уверен, что у меня хватит сил совладать с таким могущественным артефактом.$B$BВозьми его как залог того, что когда ты встретишься лицом к лицу с Иллиданом, я буду на твоей стороне. Отнеси его тому, кому мы можем безоговорочно доверять, А\'далу в Шаттрат.', 'Принесите медальон Карабора А\'далу в Шаттрат.', '<Вы протягиваете медальон А\'далу, и он исчезает в ослепительной вспышке.>$B$B<В этой вспышке вам является видение, возможно, это видение будущего. Вы видите, как Акама и Майев выходят из Клети Стражницы и пробиваются к Черному храму, третья фигура, укрытая в тени, помогает им, приглядевшись, вы понимаете, что это вы.>', '<А\'дал замечает твое приближение, и теплый свет окутывает тебя. Кажется, он уже знает, зачем ты здесь.>', NULL, NULL, 'Медальон Карабора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11053, 'Новое назначение', '$gРедкий батрак:редкая батрачка: протянет так долго, как удалось тебе. И еще реже $gпростому батраку:простой батрачке: удается возвыситься.$B$B<Варкул хлопает в ладоши.>$B$BВластитель зовет тебя. Я не сомневаюсь, что это означает для тебя новое, более высокое назначение.', 'Поговорите с властителем Мор\'гором в лагере Драконьей Пасти в долине Призрачной Луны.', 'Я внимательно наблюдал за тобой, $N. Ты доказал свою неоценимую пользу для нашего клана. Так что я собираюсь повысить тебя в звании до инспектора. Это звание налагает на тебя новые обязанности.$B$BПоднимайся, инспектор $N! Поднимайся - и иди, ищи в этом лагере тех, кто нуждается в твоей помощи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11054, 'Ты – инспектор: как делать все правильно', 'Так ты – новый инспектор, да? Есть одна штука, которую должен иметь каждый инспектор для поддержания дисциплины. Прежде чем ты приступишь к работе и начнешь вколачивать здравый смысл в пустые головы, тебе нужно обзавестись такой штукой. Каждый инспектор сам добывает все, что нужно для ее изготовления, и ты не будешь исключением.$B$BМне нужна узловатая кожа и прочная шкура Тирантия. Тирантия можно найти в заповеднике \"Дальнее поле\" в северных пределах Пустоверти.', 'Принесите 10 кусков узловатой кожи и прочную шкуру Тирантия надзирателю Грязевику в лагерь Драконьей Пасти в долине Призрачной Луны.', 'Аррр! Теперь-то ты настоящий инспектор. Эта ящерица-переросток была грозой многих орков!$B$B<Надзиратель Грязевик начинает мастерить оружие.>', 'Эти пеоны палки просят! Надо как следует их проучить, $N! Чего ты ждешь?', NULL, NULL, 'Узловатая кожа', 'Прочная шкура Тирантия', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11055, 'Ботиранг: лекарство для нерадивых батраков', 'Вот твой ботиранг, похожих много, но этот сделан специально под тебя.$B$BБудучи инспектором, ты с его помощью будешь сеять страх в душах непокорных. Его правильное использование гарантирует тебе повиновение.$B$BОтправляйся на хрустальные поля и призови к порядку этих разгильдяев-батраков. Пускай на своей шкуре почуют мощь ботиранга!', 'Призовите к порядку 20 ленивых батраков в лагере Драконьей Пасти. Ботиранг нужно будет вернуть надзирателю Грязевику.', 'Тяжелый выдался денек! Но и плата будет хороша, верно? И не греет ли тебе душу вид того, как эти никчемные шмакодявки копошатся вокруг кристаллов. Как бы то ни было, на сегодня все. Завтра тебя ждет еще один раунд насаждения дисциплины с помощью ботиранга, так что возвращайся.', 'Вся штука в запястье, $N.', NULL, NULL, 'Призвано к порядку батраков из клана Драконьей Пасти', 'Ботиранг (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11056, 'Просьба Хаззика', 'Не привлекайте внимания, Адарису не понравится, если он увидит, что мы разговариваем.$B$BЯ принадлежу к низшей касте араккоа, $N. Во времена правления Терокка меня бы давно принесли в жертву темным силам, которым поклоняются его жрецы когтя. Если то, что вы говорите - правда, и жрецы на самом деле хотят вернуть Терокка, тогда вы обязательно должны помешать им, что бы там ни говорил ваш лидер!$B$BЯ могу предложить вам кое-что полезное. В моем старом доме, в верхнем гнездовье Шил\'ак, лежит сверток - принесите его мне.', 'Заберите сверток Хаззика из его дома в восточном Скеттисе и верните сверток хозяину.', 'Отлично, $N. Вот увидите, я своему слову верен.', 'Вы вернулись, $N. А я уж было подумал, что вы забыли про меня.', NULL, NULL, 'Сверток Хаззика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11057, 'Огрское подполье', 'Мы ценим твое рвение оказать нам помощь здесь, в Огри\'ла, $C. Но мы имеем честь попросить тебя сделать кое-что прежде, чем примем твою помощь.$B$BТам, внизу, наши братья порабощены сынами Груула. Просим, поговори с Мог\'доргом Мудрым, который руководит сопротивлением огров против их хозяев-гроннов.$B$BИщи его на башне на восточной стороне арены Круга Крови.', 'Поговорите с Мог\'доргом Мудрым на вершине одной из башен рядом с Кругом Крови в Острогорье.', 'Тебя прислали сверху? Воистину, благословенна моя миссия! Я пытаюсь спасти Кровавый Молот от уничтожения кланом Камнерогов и сынами Груула, которые стоят за ними.$B$BЯ верю, что ты поможешь нашему тайному обществу и приведешь нас к свободе!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11058, 'Апекситовая реликвия', 'Давным-давно тут обитала ныне несуществующая секта араккоа, известная как Апекс. Но оставшиеся после них предметы здесь еще попадаются. Мы зовем их апекситовыми реликвиями.$B$BМы знаем, что если ими воспользоваться как должно, то они могут принести огромное благо. Каждая реликвия выдает цветовую последовательность, соотвественно которой надо нажимать на кристаллы. Так ты проходишь через несколько уровней, каждый из которых труднее предыдущего.$B$BДля того чтобы реликвия заработала, необходим апекситовый осколок. Возвращайся, когда постигнешь суть вибраций Апекса.', 'Получените вибрации Апекса от апекситовой реликвии.', '*Чу\'а\'лор кивает головами, удовлетворенный вашими деяниями.*$B$BУ тебя острый разум, $N. Мы куда больше времени потратили, чтобы научиться успешно пользоваться этой реликвией.$B$BТеперь, когда ты уже это умеешь, ты можешь пользоваться ею сколько тебе угодно. Помни только, что для того, чтобы реликвия заработала, требуется апекситовый осколок.', NULL, NULL, NULL, 'Постигните суть вибраций Апекса.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11059, 'Страж монумента', 'Ты $gпонял:поняла: как использовать одиночные реликвии, но как ты $gвидел:видела: они стоят вокруг более крупных реликвий.$B$BЭти большие апекситовые монументы работают почти так же, но для их активации нужно больше апекситовых осколков, и еще управлять ими надо вчетвером.$B$BНас весьма волнуют стражи, которые приходят, когда начинаешь активировать монументы. Эти кристаллические создания давным-давно обратились против своих хозяев-араккоа, а теперь они угрожают Огри\'ла.$B$BМы хотели бы попросить тебя унитожить одного и принести доказательства.', 'Принесите голову стража апексидов.', '<Чу\'а\'лор расплывается в улыбке и смотрит на вас с явным уважением.>$B$BМы не просто впечатлены проницательным умом твоим и твоих друзей, но мы еще в долгу перед тобой, как и вся Огри\'ла, и Стража Небес, за твою помощь в защите жизни здесь.$B$BИ помни, $N, в любое время ты можешь собрать друзей и вернуться к этим большим апекситовым монументам, чтобы воспользоваться ими, пока у тебя хватает апекситовых кристаллов для их активации.', 'Мы чураемся жестокости, но, по крайней мере, создание, которое мы послали тебя уничтожить, не было живым.$B$BКстати – голова при тебе?', NULL, NULL, 'Голова стража апекситов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11060, 'Кристалл с темными рунами', '', '', 'Крошка $R, помни, когда будешь получить контроль над деградатором, возьми молот, чтобы разбить щит портала и выпустить запертого демона.$B$BЗатем ударь этого демона и возьми над ним власть. Затем придет еще демон, ты и его тоже возьми под контроль, пока не придет надсмотрщик эредар!$B$BТогда ты и его ударь!!!', NULL, NULL, NULL, 'Темная руна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11061, 'Отцовский долг', 'Второй магический настой можно добыть только в одном месте: лагере Баш\'ира. Это база астральных духов и они не очень любят чужаков, дак что добыть ее будет немного опасно.$B$BТы спрашиваешь, где лагерь Баш\'ира? Ну, если ты полетишь на северо-северо-восток, чтобы далеко обогнуть лагерь Легиона: Гнев, ты в конце концов его заметишь. Хрустальная кузница лагеря Баш\'ира находится в его северо-восточном конце.$B$BСпасибо, что помогаешь нам, $N. Это много значит для наших сынишек!', 'Добудьте нестабильный настой волшебника.', 'Мы не знаем, как и благодарить тебя, $N!$B$BТеперь у нас два настоя, пускай и нестабильных, и мы можем послать одного из наших мальчиков на заставу Стражи Небес.$B$BПодожди минуточку, мы сейчас его позовем.$B$B*Правая голова Торкуса испускает низкий рык, призывая сына.*', 'Этот настой волшебника непременно сделает моих мальчиков еще умнее, чем они есть, и очень поможет им выполнять свои обязанности, как только их возьмут в стражи небес Ша\'тар.', NULL, NULL, 'Нестабильный настой Волшебника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11062, 'Застава Стражи Небес', '$N, мы думали - не посетишь ли ты наших друзей на севере на заставе Стражи Небес?$B$BНебесный командир Келлер и его Стража защищают там всех нас, и он просит нас прислать кого-нибудь, кто, по нашему мнению, мог бы помочь нам.$B$BИ это будешь ты!$B$BИди туда как можно скорее и, пожалуйста, передай ему наш поклон.', 'Поговорите с небесным командиром Келлером на заставе Стражи Небес на вершинах Острогорья.', 'Добро пожаловать на заставу Стражи Небес! Я своими руками ее строил!$B$BДа, всю, целиком!$B$B<Небесный командир явно не шутит.>$B$BНу, раз ты тут со мной говоришь, стало быть, хочешь подраться да трофеев добыть? Для того тебя старик Чу\'а\'лор и прислал. Нам тут свежая кровь всегда нужна.$B$BЕжели ты не против, иди-ка поговори с моим сержантом там, через дорогу. Ее зовут Вандерлип. И не обижайся на нее – язычок у нее острее того здоровенного меча, что она при себе таскает.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11063, 'Заработай крылья', '', '', 'Так ты хочешь примкнуть к усмирителям небес? Ты неплохо себя показал в клане Драконьей Пасти, но это ничего не значит тут, в небесах Запределья. Вопрос в том, умеешь ли ты летать?Полет – это не просто взгромоздиться на спину дракону Пустоты и отвезти в форт партию кристаллов, с этим-то любой дурак справится. Полет – это быть лучшим, первым среди орков.К западу отсюда есть шесть пилотов, победи их всех – и я пожалую тебе крылья усмирителя небес.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11064, 'Гонки Драконьей Пасти: баллада о старине Макстаре', 'Пусть моя седина не вводит тебя в заблуждение, рядовой, я все равно в десять раз искуснее тебя. И не думай, что у старика не найдется в рукаве пары козырей.$B$BВсе, что тебе остается, это гнаться за мной и постараться не слететь со своего зверя. Если тебе это удастся, – ты $gвыиграл:выиграла:.$B$BНачнем, как только ты будешь $gготов:готова:.', 'Следуйте за \"Стариной\" Маргом Сквернословом, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны.', 'Тыквы?! Да-а, вот так проходит мирская слава... Я уверен, что другие наездники будут посильнее Старины.', NULL, NULL, NULL, 'Победите \"Старину\" Марга Сквернослова.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11065, 'Ловим летучих скатов!', 'Хочешь помочь Страже Небес и Огри\'ла?$B$BПрежде чем уйдешь. слушай сюда, $gпарень:подруга:. Нам нужны сменные летучие животные! Бомбардировки и полеты в лагерь Баш\'ира занимают всех наших летунов.$B$BВоздухоскаты, что роятся вокруг нагорья Смерчей и Хрустального поля на северо-востоке как раз нам подошли бы. Тебе не надо даже тащить их сюда, хотя было бы неплохо. Просто зааркань их, а потом мы их подберем.$B$BКак думаешь, сумеешь?', 'Поймайте 5 летучих скатов при помощи веревочного аркана.', 'Ого! Отлично, $N! Из этих скатов выйдут отличные верховые летуны!$B$BТы не уходи... Стража Небес Ша\'тар всегда найдет дело парню с такими талантами!', 'Ну, удалось заарканить хоть сколько-нибудь? Похоже, с веревкой ты обращаться умеешь, так что много времени у тебя это не отнимет.', NULL, NULL, 'Поймано летучих скатов', 'Веревочный аркан (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11066, 'Нам нужно больше летучих скатов!', 'Надеюсь, ты здесь, чтобы помочь нам наловить еще летучих скатов! Вижу, ты словно $gродился:родилась: с арканом! И это хорошо, поскольку мы получим не только новых летунов, но и сможем защитить Огри\'ла, а огры это оценят.$B$BЗапомни – летучие скаты кружат вокруг Вершины Смерча и Хрустального поля на северо-востоке.$B$BСумеешь еще их наловить, как думаешь?', 'Поймайте 5 летучих скатов при помощи веревочного аркана.', 'Ты все продолжаешь изумлять меня! Вот что... Приходи-ка ты завтра, пусть аркан малость отдохнет, а?$B$B*Кати смеется.*$B$BОгромное тебе спасибо, $N!', 'Ты хорошо потрудился для нас, $N. Знай - мы действительнго очень тебе благодарны за сменных летунов!', NULL, NULL, 'Поймано летучих скатов', 'Веревочный аркан (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11067, 'Гонки Драконьей Пасти: Троп Смраднорыг', 'В этом клане все по-честному, правда, $N? Даже такому отребью, как я, дается честный шанс. Теперь, если ты хочешь доказать Усмирителям небес, что чего-то стоишь, тебе придется победить меня.$B$BЯ собираюсь стряхнуть тебя с хвоста, как надоедливую блоху.$B$BНачнем, когда ты будешь $gготов:готова:.', 'Следуйте за Тропом Смраднорыгом, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны.', 'Интересно... Твой следующий заезд, безусловно, будет сложнее. Корлока неуклюжим не назовешь.', NULL, NULL, NULL, 'Троп Смраднорыг побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11068, 'Гонки Драконьей Пасти: Корлок Ветеринар', 'Ты вызываешь на бой МЕНЯ? Не смеши мои сапоги!$B$BТак ты серьезно?! Ну, тогда ладно. Все что тебе нужно – это не умереть, с этим-то ты справишься? Даже если я буду швыряться в тебя черепами и летать вокруг тебя кругами, смеясь над твоими жалкими потугами на полет?$B$BСкажи, когда будешь готов, и погнали.', 'Следуйте за Корлоком Ветеринаром, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны.', 'Следующие два всадника – лучшие наездники среди дворфов и орков Азерота. У тебя нет против них ни единого шанса!', NULL, NULL, NULL, 'Победите Корлока Ветеринара.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11069, 'Гонки Драконьей Пасти: командир звена Ромеон', 'Три года я провел в этой грязной дыре. Три года в плену у проклятого клана Северного Волка. Три года сидеть в их башне взаперти и слушать их бесконечное нытье по поводу моста Дун Болдар, о том, \"как это нечестно\" и бла-бла-бла... Война вообще нечестная штука! Демоны их всех побери!$B$BКак меня освободили, я подался сюда, чтобы начать новую жизнь. Теперь мы с Маэстром боремся за первый приз в орочьих гонках. Если ты на него всерьез нацеливаешься, придется сначала победить меня, $gмалыш:детка:.$B$BСтартуем, как только ты будешь $gготов:готова:.', 'Следуйте за командиром звена Ромеоном, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны.', 'Глазам своим не верю! Теперь тебе нужно обойти Маэстра, а уж тут-то у тебя нет никаких шансов.', NULL, NULL, NULL, 'Командир звена Ромеон побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11070, 'Гонки Драконьей Пасти: командир звена Маэстр', 'Три года в поту, в крови и в слезах. В основном в слезах. Количество слез, которые проливает грубый солдат, когда дело доходит до тотальной войны, просто не поддается описанию!$B$B\"Они запрыгивают к нам в башню на лошадях!\" \"Почему их база так хорошо укреплена?\" \"Они захватили наш Приют Успокоения, я ухожу в самоволку!\"$B$BСлабаки...$B$BЯ удрал из этой \"юдоли скорби\" за минуту до открытия Темного портала, теперь я один из лучших бойцов клана Драконьей Пасти. Если ты хочешь взобраться на вершину, сначала придется миновать меня.$B$BНачнем, когда скажешь.', 'Следуйте за командиром звена Маэстром, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны.', 'Похоже, между тобой и победой остался только капитан, парень. Удачи! Она тебе пригодится.', NULL, NULL, NULL, 'Победите командира звена Маэстра.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11071, 'Гонки Драконьей Пасти: капитан Небокрушитель', 'Ты осмеливаешься вызвать Небокрушителя? Мир вокруг тебя обрушится в бездну, и небо разлетится на куски под ударами моих метеоров.$B$BУ тебя нет шансов, солдат. Впрочем, если ты желаешь таким образом свести счеты с жизнью...$B$BЯ удовлетворю твое желание, хотя бы для того, чтобы больше ни один идиот не лез ко мне с подобными просьбами.$B$BНачнем по твоему сигналу.', 'Следуйте за капитаном Небокрушителем, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны.', 'Мне и в голову прийти не могло, что кому-то удастся одолеть Небокрушителя. Ты знаешь, что это значит. Верно? Ты теперь первый среди орков. Но этот титул тебе придется отстаивать.', NULL, NULL, NULL, 'Капитан Небокрушитель побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11072, 'Кровные враги', 'Потомки, которых держат в плену жрецы Когтя из Скеттиса, упомянуты в этой книге: Охотница Геззарак, хрустальный гигант Каррог, еретик по имени Темный Крикун Аккарай и Ваккиз Ветрояр. Для того чтобы Терокк вернулся в этот мир, нужно будет убить их всех.$B$BДля этого вам потребуются свитки затерянных во времени араккоа – с помощью свитков вы сможете призвать потомков в специальных кругах в Скеттисе. Принесите мне какую-нибудь вещь от каждого из них, но помните, что все они очень сильны, и лучше бы вам позвать с собой друзей.', 'Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттика, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра.', '', NULL, NULL, NULL, 'Когти Аккарая', 'Хребет Каррога', 'Когти Геззарак', 'Чешуя Ваккиза');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11073, 'Падение Терокка', 'Послушайте... Я не обращал внимания на все ваши разговоры с пленником араккоа, $N, потому что ваше с ним сотрудничество может принести нам пользу.$B$BВидите ли... Если бы я помог вам с призыванием Терокка, здесь бы вспыхнул настоящий мятеж.$B$BТак что возьмите все, что вам дал Хаззик и следуйте своему плану. Мои люди прикроют вас, когда потребуется, но советую и вам привести с собой помощников. Боюсь, второго шанса вам не представится.', 'Возьмите приготовленное Хаззиком Подношение Затерянного во Времени и отнесите его к груде черепов в центре Скеттиса. С помощью подношения призовите Терокка и сразитесь с ним, после чего вернитесь к небесному командиру Адарису.', 'Мы все очень гордимся вами, $N. Я обязательно передам вести о ваших подвигах в Шаттрат. Стража Небес навечно в долгу перед вами.', NULL, NULL, NULL, 'Терокк убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11074, 'Кровные враги', 'Потомки, которых держат в плену жрецы Когтя из Скеттиса, упомянуты в этой книге: Охотница Геззарак, хрустальный гигант Каррог, еретик по имени Темный Крикун Аккарай и Ваккиз Ветрояр. Для того чтобы Терокк вернулся в этот мир, нужно будет убить их всех.$B$BДля этого вам потребуются свитки затерянных во времени араккоа – с помощью свитков вы сможете призвать потомков в специальных кругах в Скеттисе. Принесите мне какую-нибудь вещь от каждого из них, но помните, что все они очень сильны, и лучше бы вам позвать с собой друзей.', 'Добудьте у затерянных во времени араккоа их свитки и отнесите их к груде черепов в центре круга призыва в Скеттисе. Вызовите и победите потомков врагов Терокка, после чего отнесите Хаззику коготь Аккарая, хребет Гарокка, чешую Векказа и коготь Геззарака.', 'Отлично! Вот, возьмите. Я приготовил это из того, что вы принесли мне, и теперь вы сможете вызвать Терокка.$B$BНо будьте осторожны, Дрранош! Это самый могущественный араккоа из тех, что вам приходилось встречать, так что недооценивать его опасно.', 'Для того чтобы призвать Терокка, потребуются вещи от каждого из потомков его величайших врагов.', NULL, NULL, 'Когти Аккарая', 'Хребет Каррога', 'Когти Геззарак', 'Чешуя Ваккиза');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11075, 'Копи Крыльев Пустоты', 'В Копях Крыльев Пустоты требуется твоя помощь, инспектор, $N.$B$BДва дня назад нам пришлось прервать работу в одной из копей из-за одного крайне неприятного открытия. Шахтер, который работал на нижних ярусах, стукнул киркой по необычному скоплению кристаллов. К сожалению, на другом конце этого скопления оказался очень злой дракон Пустоты. Животное очнулось от спячки и первым делом истребило всех наших работников.$B$BДоложи об этом Госпоже Копей. Тебя ждут возле входа в копи к юго-западу отсюда.', 'Найдите Госпожу Копей на кряже Крыльев Пустоты.', 'Шахтеры упорно трудятся, но ни один не осмеливается ступить в эту шахту. Они предпочитают умереть, но не спускаться в ее глубины. Теперь в твои обязанности будет входить выполнение всех тех заданий, с которыми не справились они.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11076, 'Собрать по кусочкам...', 'Большая часть добытых минералов лежит сейчас в беспорядке за дверями этой шахты. Брошенные груженые тачки стоят там повсюду, а мы не можем до них добраться из-за этого вторжения.$B$BИ здесь в игру вступаешь ты, $N. Твоей задачей будет собрать груз из этих тачек, оставленных шахтерами.$B$BСобери весь груз и верни его мне или моей сестре.', 'Соберите для Госпожи Копей груз 15 тачек в Долине Призрачной Луны.', 'Отлично, $N. Возвращайся завтра, за новым заданием.', 'Ты все собрал?', NULL, NULL, 'Груз Копей Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11077, 'Драконы – это не самое страшное', 'Этот дракон проснулся в злобе на мелких надоедливых существ, кишащих в этих копях. И для клана Драконьей Пасти они тоже – как шило в боку. Особенно живодеры-пустокопы и опустошители-пустокопы из Копей Пустоты. Помоги нам от них избавиться. Я не прошу тебя отдать этому все свое время – будет достаточно одного раза в день.$B$BОтправляйся туда и убей столько, сколько сможешь.', 'Убейте 15 живодеров-пустокопов и 5 опустошителей-пустокопов из Копей Пустоты для штейгера из клана Драконьей Пасти.', 'На сегодня достаточно, инспектор. Возвращайся завтра для нового раунда зачистки.', NULL, NULL, NULL, 'Живодер-пустокоп убито', 'Опустошитель-пустокоп убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11078, 'В небесах останется только один!', 'Когда ты $Gлетал:летала; по округе, наверняка $Gзамечал:замечала; драконов в вышине. Хорошо, что ты не $Gпопал:попала; им под горячую лапу. Помоги нам покончить с этим, $N!$B$BЧернокрыл и Обсидия царят на своей террасе, а Инсидион и Ярокрыл - хозяйничают в небе вон над той террасой на северо-востоке. У каждого есть насест в своих владениях. А вот не собраться ли тебе с друзьями, $gпарень:подруга: да не слазать ли до какого-нибудь насеста, да не разбить ли яйцо, чтобы сманить дракона вниз?$B$BПринеси-ка мне драконьи зубы в доказательство. В небесах дожен остаться только кто-то один - мы или они.', 'Добудьте драконьи зубы.', 'Да! Такими зубками что угодно можно перегрызть!$B$BВы с друзьями сделали хорошую работенку! Эти драконы – жуткие хищники, и в небесах от них спасу нет.$B$BНебось, и драконьи чешуи на глаза попадались? Говорят, из них делают славные плащи. А если тебе плащ по нраву не придется, я его обменяю на апекситовый кристалл.', 'И как дела, $N? Думаю, незачем напоминать тебе, что мы должны постоянно патрулировать эти места с воздуха.', NULL, NULL, 'Зубы дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11079, 'Бич Скверны для Гахка', 'Гак думать – быть умный иногда тупо. Гак не хотеть думать. Моя хочет от крошка $r убивать большие демоны! $B$BУ них есть начальники, а у начальников есть бичи бить маленькие демоны. Ты приносить Гаку бич! $B$BТвоя вызывать драться главный демон в лагерь Легиона в зеленая, горящая скверная крристалловая призма! Бери много апекситовый осколка, чтобы они пришли! Их зовут Гальванот, Браксус, Зарцин и Мо\'арг Испепелитель.', 'Добудьте бич Скверны. +500 ед. репутации с Огри\'ла', 'Гахку нравится бич. Может, Гахк будет бить демонов!$B$BМоя сказать $R, что $R вызывать главные демоны всегда, когда $R приходить с друзьями и иметь при себе много осколков.', 'Твоя принесла бич?', NULL, NULL, 'Бич Скверны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11080, 'Излучение реликвии', 'Теперь, когда ты $gпознал:познала: просветляющую вибрацию апекситовой реликвии, пора глубже изучить принципы ее действия. Мы будем с нетерпением ждать результатов твоих изысканий!$B$BЧем лучше ты настроишься на взаимодействие с реликвией, тем выше станет уровень твоих познаний. Ты поймешь это по излучению от реликвии.$B$BВернись к нам, когда почувствуешь это излучение.', 'Испытайте на себе излучение от апекситовой реликвии.', 'Ты продолжаешь изумлять нас своею проницательностью, $N. Может, позанимаешься этой реликвией хотя бы один день для оттачивания своего разума?', 'Ты уже чувствуешь апекситовое излучение?', NULL, NULL, 'Вы почувствовали на себе апекситовое излучение', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11081, 'Восстание в племени Темной Крови', 'Этот документ говорит о восстании, планируемом Сломленными из племени Темной Крови. Видимо дракона использовали, для того, чтобы отвлечь внимание от их исчезновения, но, глядя на их тела, разбросанные по шахте, придется признать, что план их провалился.$B$BВерни планы побега Госпоже Копей.', 'Отнесите планы побега племени Темной Крови Госпоже Копей.', 'Прекрасно Инспектор. Мор\'гор услышит о твоей верной службе клану Драконьей Пасти.$B$BТеперь возвращайся к этим собакам из Темной Крови. Планируют побег, говоришь? Надеются противостоять истиному Лорду Запределья? Их лидеры заплатят за это!', 'Что это?', NULL, NULL, 'Планы побега Темной Крови (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11082, 'Искатель Истины', 'Эти шахтеры слишком тупы, чтобы придумать какой бы то ни было план побега. Мы должны найти и наказать того, кто помог им. Отправляйся в шахту и найди там надзирателей из племени Темной Крови. Если они впутались в эту заварушку с побегом, то, скорее всего, они будут скрываться.$B$BКак только ты найдешь хоть одного, пытай его, пока он не выдаст тебе, кто стоял за составлением этого плана. Вернешься ко мне с именем этого предателя и рукой надзирателя.', 'Найдите надзирателя из племени Темной Крови и допросите его. Вернитесь к Госпоже Копей с информацией об организаторе побега и рукой надзирателя.', 'Нечего сказать? Возможно, когда он будет истекать кровью на полу этой шахты, он вспомнит... Вспомнит, что значит идти против сил Иллидана!', 'Ну? Неужели это заняло столько времени?', NULL, NULL, 'Рука Вождя', 'Соберите сведения о планах Темной Крови.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11083, 'Спятившие и очень опасные...', 'Не волнуйся из-за дракона, $N. Мы нашли на него управу.$B$BНа нижних ярусах этой копи обитает банда психов из клана Темной Крови. После того как дракон вырвался, они оказались отрезанными от выхода. И вот спустя всего 2 дня они утратили всякие представления о приличиях, обратились к каннибализму и прочим дикостям. Нам там эти психи не нужны! Поэтому иди и убей их. Всех!', 'Убейте для Ронага Деспота из копей Крыльев Пустоты безумного штейгера и 5 шахтеров из племени Темной Крови.', 'Да, я такого не понимаю... Кто бы мог подумать, что они так оголодают всего за два дня. Клан Темной Крови...$B$B<Ронаг качает головой.>$B$BКакие же они все-таки тупые...', NULL, NULL, NULL, 'Безумный штейгер из племени Темной Крови убито', 'Безумный шахтер племени Темной Крови убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11084, 'Стой прямо, капитан!', 'Так... Так... Так... Все еще $gжив:жива: как я погляжу. Хорошо. Потому что Мор\'гор, хочет тебя видеть немедленно. Шевелись!', 'Поговорите с властителем Мор\'гором в лагере Драконьей Пасти в долине Призрачной Луны.', '*Моргор кивает*$B$BВерно, я сказал Капитан. Ты заработал повышение, Нихаза.$B$BРаботаешь лучше, чем любой орк Скверны, которого я когда-либо видел. Продолжай в том же духе и когда-нибудь станешь и властителем.$B$BТеперь иди и принимай командование. Я предлагаю тебе попробовать заработать крылья Усмирителя небес.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11085, 'Побег из Скеттиса', 'Здравствуй, $N. Спасибо, что $gпришел:пришла: мне на помощь.$B$BЯ был на разведке, когда эти жуткие араккоа сбили меня с моего ската.$B$BДавай выбираться отсюда, пока еще можем!', 'Проводите плененного Стража Небес в безопасное место, а затем доложите небесному сержанту Дорину.', 'Спасибо за помощь нашему разведчику, Фэникс. Мы слишком часто теряем хороших людей, и новобранцев не хватает, чтобы заменить их.', NULL, NULL, NULL, 'Плененный Страж Небес освобожден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11086, 'Разрушение сумеречного портала', 'Одной из твоих обязанностей как капитана клана Драконьей Пасти является следить за действиями Пылающего Легиона в Запределье, и затыкать рты тем, кто пытается противостоять владыке Иллидану.$B$BДемоны пытаются сделать устойчивым портал на Сумеречной гряде в западном Награнде. Они заплатят за свое вероломство, и ты будешь тем, кому предстоит осуществить наше возмездие.$B$BОтправляйся на Сумеречную гряду и истреби ее обитателей. Я жду от тебя как минимум одного успешного штурма в день.', 'По поручению властителя Мор\'гора из лагеря Драконьей Пасти в долине Призрачной Луны убейте 20 посланников Смертной Тени.', 'Превосходно, капитан! Владыка Иллидан узнает о твоем подвиге!', NULL, NULL, NULL, 'Посланник Смертной Тени убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11089, 'Пушка души Рет\'хедрона', 'Рет\'хедрон теперь правит Сумеречной Грядой в Награнде. Эредар такой силы, пришедший в этот мир, не сулит ничего хорошего Иллидари. Увы, у нас не хватает сил, чтобы справиться с ним. Особенно сейчас, когда Ша\'тар развязали войну у Черного храма. Однако у меня есть план.$B$BТы победишь Рет\'хедрона и отправишь его обратно через сумеречный портал. Для этого необходимо использовать пушку души.$B$BВот тебе список материалов, когда раздобудешь все, возвращайся ко мне.', 'Принесите повелителю иллидари Балтасу, находящемуся в лагере Драконьей Пасти, 2 слитка оскверненной стали, 1 адамантитовую рамку, 1 кориевый сердечник и 1 безупречную чародейскую сущность.', '<Балтас, умело соединяет компоненты, принесенные вами.> Настало время для второй части нашего плана, капитан.', 'Ты собрал все компоненты, необходимые для изготовления пушки души?', NULL, NULL, 'Слиток оскверненной стали', 'Адамантитовая рамка', 'Кориевое силовое ядро', 'Безупречная чародейская сущность');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11090, 'Покорить Покорителя', '$gБалтас держит в руках странно выглядящий предмет.>$B$BЭто пушка душ. Правильно настроенная, она обладает разрушительным эффектом. Эта настроена на мою кровь, такую же, как та, что течет в венах Рет\'хедрона – моего брата, которого погубит его неуместная лояльность.$B$BВозьми пушку и лети на Сумеречный хребет, в западном Награнде, найди там Рет\'хедрона и стреляй! Оставайся на своем летающем транспорте, в пределах видимости, чтобы достичь необходимого эффекта. Держись и ему ничего не останется, кроме как спасаться бегством.', 'Используйте пушку душ против Рет\'хедрона Покорителя в Награнде. Потом верните пушку повелителю иллидари Балтасу в лагерь Драконьей Пасти, в долине Призрачной Луны.', 'Он вернется, но теперь силы Легиона, посланные против владыки Иллидана, ослаблены. Иллидан непременно узнает о твоих заслугах. Капитан.', 'Дело сделано?', NULL, NULL, 'Пушка души (Прилагается)', 'Покорите Рет\'хедрона Покорителя.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11091, 'Особая благодарность', 'Для нас великая честь, что ты помогаешь нам. А теперь мы хотим, чтобы ты кого-то встретил.$B$BДжо\'насс наш самый верный эконом. Он хранит товары на продажу только для самых верных другов Огри\'ла.$B$BТы и есть один такой друг, $N.$B$BКогда у тебя будет время, иди поговорить с ним. Насколько мы понимаем, он приготовил для тебя одну вещь в знак нашей благодарности.', 'Поговорите с Джо\'нассом в Огри\'ле на вершинах Острогорья.', 'Ох ты, парень, мы рады! Мы слышали, что ты много хорошего нам дела! Круто! Нам сдается, разберешься с проблемами Огри\'ла и спасешь нас, и все будет в шоколаде!$B$BВот, бери. Это мелочь, просто неприкосновенный запас да индивидуальный пакет, кототрый мы тебе собрали в благодарность за труды.$B$BПолюбуйся на наши товары. У нас много что есть тебе полезного.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11092, 'Приветствую тебя, Командир!', 'Капитан $N!$B$B*Варкул отдает тебе честь.*$B$BВластитель Мор\'гор вызывает тебя к себе немедленно!', 'Поговорите с властителем Мор\'гором в лагере Драконьей Пасти в долине Призрачной Луны.', 'Сам владыка Иллидан велел, чтобы я возвел тебя в ранг командира. Это неслыханно, ты будешь первым из этого клана, получившим такой высокий ранг вне стен Черного храма.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11093, 'Пропитание для скатов Пустоты', 'При должной дрессировке скаты Пустоты становятся на удивление послушными и преданными питомцами, но, к сожалению, эта война не щадит и их. У нас бывает по нескольку десятков вылетов в день – бедные звери едва успевают перевести дух. К тому же с кормом в последнее время перебои, и если скатов не убьют эти мерзкие птицелюди, то они умрут сами, от голода!$B$BЕсли вы не против, возьмите одного ската в лес, к югу отсюда. Там он сможет покушать – они не против мяса прыгуан-ловцов, но только если оно свежее.', 'Возьмите клетку для скатов Пустоты в лес к югу от лагеря Черного Ветра и убейте прыгуан-ловцов долины Черного Ветра около голодного ската Пустоты. После этого вернитесь к укротителю Диисаку из Стражи Небес.', 'Спасибо, что позаботились о скате, $N! Когда они сыты, то летают гораздо лучше. Нам вовсе не надо, чтобы враги сбивали наших воинов только потому, что их скаты слишком ослабели.', 'Вы вернулись! Как себя вел скат?', NULL, NULL, 'Корм для ската Пустоты', 'Клетка для скатов Пустоты (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11094, 'Всех убей, один останься!', 'Командир $N, смирно! Твоя задача – взять батальон Усмирителей Небес и уничтожить заставу Провидцев, расположенную у полей Крыльев Пустоты. После того как Святилище Звезд будет разрушено, пути к нашим постам в лагере Затмения и аванпосту иллидари снова будут открыты.$B$BВперед! Используй сигнальное ружье, чтобы подать Усмирителям Небес сигнал к атаке!', 'Доставьте информацию о вашей новой миссии вместе со сигнальным ружьем чародею Телису в святилище Звезд.', 'Хорошо, что ты пришел к нам, возможно, мы сможем использовать эту атаку в своих целях и побить клан Драконьей Пасти его же оружием.', 'Присаживайся, дитя мое.', NULL, NULL, 'Сигнальное ружье клана Драконьей Пасти (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11095, 'Командор Хобб', 'Клан Драконьей Пасти смеет нападать на нас, только когда мы вынуждены уменьшать охрану. Если бы они напали на нас, когда мы были бы готовы к этому, их ждало бы неминуемое поражение.$B$BЯ хочу, чтобы ты позволил им сделать это, $N.$B$B<Телис кивает.>$B$BДа... западня, – вот что нам нужно! Возьми сигнальную ракету, которую тебе дал их воевода, и отдай ее командору Хоббу. Он стоит на посту возле этого здания.', 'Отдайте сигнальную ракету клана Драконьей Пасти командору Хоббу в святилище Звезд в долине Призрачной Луны.', '<Хобб ухмыляется.>$B$BНеплохая получится ловушка...', '<Хобб кивает.>', NULL, NULL, 'Сигнальное ружье клана Драконьей Пасти (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11096, 'Угроза извне', 'Вы хотите вступить в ряды Стражи Небес? Что ж, летать вы умеете, а вот как насчет боя?$B$BСтража Небес охраняет Шаттрат от всех опасностей – как ближних, так и дальних. Одна из таких опасностей – это огры из клана Гордунни, населяющие Пограничные холмы на севере.$B$BНаземным войскам Шаттрата тяжело подобраться к ограм, поэтому эту задачу передали нам. Может быть, вы что-нибудь сможете с ними сделать.', 'Убейте 20 любых огров из клана Гордунни в Защитных холмах, после чего вернитесь к Юуле в Шаттрат.', 'Прекрасно! Думаю, мы с вами сработаемся.', 'Вы выполнили свое задание, $N?', NULL, NULL, 'Огр из клана Гордунни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11097, 'Самая Опасная Ловушка', 'Возьми эти медали Провидцев. Мор\'гору понадобится доказательство \"победы\", когда все закончится. Он решит, что медали сняты с наших павших воинов. $B$BТеперь все, что тебе остается, – использовать сигнальную ракету, чтобы известить налетчиков из клана Драконьей Пасти. Мы сокрушим их, когда у тебя все будет готово, только дай нам знак.', 'Помогите командору Хоббу защитить святилище Звезд. Когда войска клана Драконьей Пасти будут разгромлены, вернитесь к воеводе Мор\'гору в лагерь Драконьей Пасти с медалями Провидцев.', '<Мор\'гор смеется.>$B$BХа! Я знал, что ты меня не подведешь! Я хочу, чтобы ты устраивал набеги на святилище Звезд как минимум раз в день, Они поймут, что у них нет выбора, кроме как покинуть долину Призрачной Луны!', 'Ты сокрушил их командир?', NULL, NULL, 'Медали Провидцев (Прилагается)', 'Разгромите войска клана Драконьей Пасти.', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11098, 'В Скеттис!', 'Защитные Холмы – лишь один из пределов, которые нам приходится защищать. Куда большая опасность, хотя и не столь заметная, грозит нам со стороны гор Скетил, из города араккоа, Скеттиса.$B$BНесколько месяцев назад наши лазутчики заметили, что араккоа явно оживились. За этим последовало несколько нападений на Шаттрат. С тех-то пор город и окружают войска.$B$BОтнеси эту взрывчатку сержанту Дорину в лагерь Черного Ветра рядом со Скеттисом. Скажи ему, что ты его новобранец.', 'Отнесите упаковку взрывчатки сержанту Дорину в лагерь Черного Ветра рядом со Скеттисом.', 'Спасибо за взрывчатку; мы найдем ей применение! Новобранец, да? Посмотрим, на что ты годишься.', 'Что ты принес?', NULL, NULL, 'Упаковка взрывчатки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11099, 'Всех убей, один останься!', 'Командир $N, Смирно! Твоя задача – взять батальон Усмирителей Небес и уничтожить заставу Алдоров, расположенную к северо-западу от нашего любимого Черного храма. После того как алтарь Ша\'тар будет разрушен, пути к нашим постам в Змеиных Кольцах снова будут открыты.$B$BОтправляйтесь! Используй сигнальное ружье, чтобы подать Усмирителям Небес сигнал к атаке!', 'Доставьте информацию о вашей новой миссии вместе с сигнальным ружьем анахоретке Сейле к алтарю Ша\'тар.', 'Хорошо, что ты пришел к нам, возможно, мы сможем использовать эту атаку в своих целях и побить клан Драконьей Пасти его же оружием.', 'Присаживайся, дитя мое.', NULL, NULL, 'Сигнальное ружье клана Драконьей Пасти (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11100, 'Командор Аркус', 'Клан Драконьей Пасти смеет нападать на нас, только когда мы вынуждены уменьшать охрану. Если бы они напали на нас, когда мы были бы готовы к этому, их ждало бы неминуемое поражение.$B$BЯ хочу, чтобы ты позволил им сделать это, $N.$B$B<Сейла кивает.>$B$BДа... западня, – вот что нам нужно! Возьми сигнальную ракету, которую тебе дал их воевода, и отдай ее командору Аркусу. Он стоит на посту, возле этого здания.', 'Отдайте сигнальную ракету клана Драконьей Пасти командору Аркусу у алтаря Ша\'тар.', '<Аркус ухмыляется.>$B$BНеплохая получится ловушка...', '<Аркус кивает.>', NULL, NULL, 'Сигнальное ружье клана Драконьей Пасти (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11101, 'Самая Опасная Ловушка', 'Возьми эти медали Алдоров. Мор\'гору понадобится доказательство \"победы\", когда все закончится. Он решит, что медали были сняты с трупов солдат. $B$BТеперь все, что тебе остается, – использовать сигнальную ракету, чтобы известить налетчиков из клана Драконьей Пасти. Мы сокрушим их, когда у тебя все будет готово, только дай нам знак.', 'Помогите командору Аркусу защитить алтарь Ша\'тар. Когда войска клана Драконьей Пасти будут разгромлены, вернитесь к воеводе Мор\'гору в лагерь Драконьей Пасти с медалями Алдоров.', '<Мор\'гор смеется.>$B$BХа! Я знал, что ты меня не подведешь, командир! Я хочу, чтобы ты устраивал набеги на алтарь Ша\'тар как минимум один раз в день, Они поймут, что у них нет выбора, кроме как покинуть долину Призрачной Луны!', 'Ты сокрушил их командир?', NULL, NULL, 'Медали Алдоров (Прилагается)', 'Разгромите войска клана Драконьей Пасти.', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11102, 'Бомбардировка', 'Ну, положим, умеешь ты летать как ворон, и что? Да-да, и уничтожать все, что внизу. Хочешь попробовать? $B$BЛагеря Легиона Гнев и Ужас на севере и юге – вот сущее шило у меня в заднице! Они еще и угрожают мирной Огри\'ла... Эти проклятые пушки Скверны лупят по Страже Небес справа и слева, и мы не можем пробиться сквозь заградительный огонь и выполнить свой долг.$B$BХочешь показать себя? Бери бомбы и разнеси их боеприпасы! Только смотри, как бы они сами тебя не сбили!', 'Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес.', 'Ха-ха, я так и знала, что вы в конце концов их уделаете! Хорошая работа! Может, старина Келлер и ошибался на ваш счет.$B$B<Небесный сержант Вандерлип ухмыляется.:', 'Ну как – еще не разделались с их пушечными ядрами?', NULL, NULL, 'Уничтожено груд пушечных ядер', 'Бомбы Стражи Небес (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11103, 'Отказ мудреца', '', '', 'Время – оно как река, и течение ее подчиняется определенным законам. Как и всякую реку, время можно повернуть вспять, но это будет непросто и потребует многих усилий.', NULL, NULL, NULL, 'Кольцо вечного мудреца', 'Требуется денег: 75', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11104, 'Перестать быть исцелителем', '', '', '', NULL, NULL, NULL, 'Кольцо вечного восстановителя', 'Требуется денег: 75', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11105, 'Отказ героя', '', '', '', NULL, NULL, NULL, 'Кольцо вечного защитника', 'Требуется денег: 75', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11106, 'Отказ защитника', '', '', '', NULL, NULL, NULL, 'Кольцо вечного поборника', 'Требуется денег: 75', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11107, 'Склонитесь перед верховным господином', 'Я недостоин даже принести вам это известие, $gсэр:мадам:, умоляю о снисхождении. Властитель Мор\'гор хочет видеть вас у себя.', 'Поговорите с властителем Мор\'гором в лагере Драконьей Пасти в долине Призрачной Луны.', 'Ты станешь первым верховным господином в этом клане, $N. Сам Хозяин явится сюда, чтобы лично повысить тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11108, 'Владыка Иллидан Ярость Бури', 'Пойдем, сам Владыка Иллидан ждет нас!', 'Встретьтесь с Иллиданом Яростью Бури. Найдите Бартамуса в Нижнем городе Шаттрата, если останетесь в живых.', 'Я был первым, ты ведь знаешь. Брошенный отпрыск чудовища...$B$B*Бартамус качает головой.*$B$BМы в неоплатном долгу перед тобой, $N. Ты голыми руками развалил империю клана Драконьей Пасти и добыл столько информации, что моим собратьям хватит на десять жизней вперед.$B$BЭто весьма скромная плата за то, что ты сделал для нас, но... Мои родичи, предложили тебе свою помощь, когда ты отправишься в Запределье, тебе нужно только попросить, и они отправятся с тобой.', NULL, NULL, NULL, 'Встреча с Иллиданом Яростью Бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11109, 'Кобальтовый дракон Пустоты Хорус', '', '', 'Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.Если Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.Но ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
