INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11111, 'Ониксовый дракон Пустоты Ониксиен', '', '', 'Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.Если Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.Но ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
