INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11114, 'Зои, изумрудный дракон Пустоты', '', '', 'Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.Если ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.Но ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11116, 'Испытание Наару: Магтеридон (QUEST FLAG)', 'Прежде чем наару признают тебя достойным, тебе предстоит пройти четыре испытания.$B$BОсталось лишь одно препятствие, $gсмертный:смертная:. Собери армию побольше и отправляйся в логово Магтеридона в глубины Цитадели Адского Пламени. Пробейся в центральный чертог и убей гнусного сеятеля скверны!$B$BНаградой тебе станет ключ Урагана.', 'А\'дал из Шаттрата просит вас убить Магтеридона.', '', NULL, NULL, NULL, 'Магтеридон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11117, 'Поймать дикого зайцелопа!', 'Ну вот. Слышишь? Страшный шум в холмах. Это зайцелопы! Коварные звери так и прут на запах Хмельного фестиваля! Я хотел бы поймать парочку, да вот беда, ушиб ногу, мне их не догнать. Ты можешь мне помочь!$B$BВозьми сеть и накинь ее на мелких гадов. Принеси мне не меньше пяти, а уж за мной не заржавеет! Ах, да, еще одно – чтобы увидеть зайцелопов, тебе придется хорошенько заложить за воротник! Пей, не жалей – или хотя бы одолжи у меня Синтехмельные очки!', 'Голдарк Меткий Охотник попросил вас поймать 5 оглушенных диких зайцелопов с помощью особой сети. Он намекнул, что необходимо достичь состояния сильного алкогольного опьянения – или надеть Синтехмельные очки.', 'Ну, смотри-ка! Целая куча зайцелопов, любо-дорого глядеть.$B$B<Он делает большой глоток из кружки.>$B$BВот, что я сделаю. Раз ты так ловко их поймал, оставь себе одного!', 'Ты не слишком ли трезвый? Может, поэтому ты не видишь этих гадов?', NULL, NULL, 'Оглушенный зайцелоп', 'Сеть для ловли зайцелопов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11118, 'Розовые элекки на марше', 'Напиваться на Хмельном фестивале – почетная традиция! Дело в том, что со всего Азерота идут жалобы – весь праздник портят галлюцинации! Так дело не пойдет!$B$BПроклятых элекков не берет обычное оружие – проходит сквозь них – так что возьми этот образчик гномьей инженерии, обойди все сады спелого хмеля и уничтожь розовых тварей. И не забудь, для этого надо хорошенько напиться – или хотя бы одолжить у меня Синтехмельные очки!', 'Отправляйтесь в сады спелого хмеля рядом с Штормградом, Дарнасом и Экзодаром, истребите по три элекка в каждом из мест и возвращайтесь к Голдарку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо напиться или надеть Синтехмельные очки.', 'Прекрасно! Розовые элекки... Что за бред!', 'Ну что, дурацкие розовые элекки пропали?', NULL, NULL, 'Розовый элекк с острова Лазурной Дымки убито', 'Элвиннский розовый элекк убито', 'Тельдрассилский розовый элекк убито', 'Луч рассеяния элекков (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11119, 'Налет на лагерь Баш\'ира!', 'Эй, $gприятель:подруга:! Хочешь поразвлечься, а?$B$BКаждые пару часов мы, эфир-техи, совершаем налет на лагерь Баш\'ира, там, далеко на северо-востоке Острогорья. Говорят, что мы \"изучаем\" тамошнюю хрустальную кузницу, но на самом-то деле это налет, и ничто иное. Нам хрустальная кузница нужна для дозаправки, да еще остается на продажу.$B$BИди-ка на посадочную площадку и переговори с учеником эфир-техника. Он тебе скажет, когда очередной вылет.', 'Поговорите с учеником эфир-теха на заставе Стражи Небес в Острогорье.', 'Как бы Келлер это ни называл, я предпочитаю считать, что наша миссия – исследовательская.$B$BНо врать не стану, бывая там мы пополняем запасы Стражи Небес. Только кто же нам даст там задержаться подольше... $B$BПохоже, вы сумеете не дать духам Астрала ударить нам в спину. Если вы продержитесь достаточно долго, мы продадим вам избыток того, что сделаем в хрустальной кузнице, так что несите свои апекситовые осколки и кристаллы!$B$BВылетаем в 0 |4минуту:минуты:минут;.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11120, 'Розовые элекки на марше', 'Слушай, мы тут на жизнь зарабатываем. Народ хочет выпить – можно денег наварить. Одна беда – галлюцинации. Ребята говорят, будто алк... постоянные клиенты видят повсюду розовых элекков.$B$BКлиенты – дело важное. Слышь, возьми этот луч и походи по другим садам спелого хмеля, разберись с элекками, а? Только хорошенько наберись перед этим или хотя бы надень Синтехмельные очки. Если они тебе нужны, обращайся.', 'Отправляйтесь в сады спелого хмеля рядом с Луносветом, Громовым Утесом и Подгородом, истребите по три элекка в каждом из них и возвращайтесь к Глодраку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо напиться – или хотя бы надеть Синтехмельные очки.', 'Молодец, дружище. Вот, возьми это в уплату за проделанную работу.', 'Ну как, ты разобрался с той проблемкой, о которой я недавно упоминал?', NULL, NULL, 'Розовый элекк из лесов Вечной Песни убито', 'Мулгорский розовый элекк убито', 'Тирисфальский розовый элекк убито', 'Луч рассеяния элекков (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11122, 'Туда и обратно', 'Хочешь помочь нам на Хмельном фестивале? У меня есть отличное задание. Садись на скакового барана и дуй в Каранос. Мне надо прихватить там кой-какие бочки.$B$BНа холме рядом с грудой бочек тебя дожидается Флинн Огневое Пойло. Когда ты подойдешь поближе, он кинет тебе бочку. Тащи ее сюда и отдавай Полу Янтарлену. Больше одной бочки разом тебе не поднять.$B$B<Готов:Готова:?', 'Возьмите бочку у Флинна $N и верните ее Полу Янтарлену. Пока баран не сбежит от вас, постарайтесь доставить три бочки.', 'Огромное спасибо за помощь! Пока дворфы Черного Железа не сложили оружие, а Хмельной фестиваль продолжается, мне не обойтись без помощников. Если ты хочешь еще подзаработать, приходи завтра.$B$BВпрочем, довольно болтать. Надо заплатить тебе за труды. Вот жетоны, желаю веселого Хмельного фестиваля!', NULL, NULL, NULL, 'Бочек доставлено', 'Поводья скаковых баранов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11123, 'Исследование пепелища', 'Бедняга Джеймс так и не оправился после пожара в \"Последнем привале\" и гибели семьи. Мы с ребятами делаем все, что в наших силах, чтобы найти ублюдков, ответственных за это.$B$BЯ послал нашего лучшего следователя, инспектора Тарема, на пепелище, но одному там не справиться. Если вы поможете Тарему, мы этого не забудем. Видит Свет, мы все хотели бы помочь.$B$BДо таверны можно дойти по главной дороге, только будьте поосторожнее. В такую глухомань мои патрули не заходят.', 'Поговорите с инспектором Таремом у трактира \"Последний привал\".', 'Я рад, что капитан Ваймс наконец-то и других привлек к этому делу.$B$BЯ здесь все посыпал отражательным порошком – с его помощью можно увидеть подозрительные предметы и знаки и здорово сэкономить время. Иди и собери все, что светится от этой пыли.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11124, 'Исследование пепелища', 'Если ты пойдешь по дороге на юг от деревни, а затем свернешь на запад к Степям, ты найдешь пепелище таверны \"Последний привал\".$B$BТерамор направил туда следователя, чтобы разобраться, с чего бы это вдруг таверна сгорела. В другое время я бы тебе посоветовал держаться подальше, но у нас есть приказ из Оргриммара \"помочь\" в расследовании.$B$BПринимай любую помощь от следователя из Терамора, даже выдай ему пару обрывков информации, если хочешь, - но ни в коем случае не раскрывай все карты.', 'Поговорите с инспектором Таремом у трактира \"Последний привал\".', '*Инспектор смотрит на вас с нескрываемым недоверием.*$B$BМне сказали, что ты будешь... помогать в расследовании. Что же, хорошо.$B$BЯ обработал тут все вот этим порошком, чтобы узнать, кто напал на гостиницу. Он поможет выявить улики, связанные с эти нападением. Обследуй все, что покажется подозрительным.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11126, 'Чужой среди своих', 'Хорошо, что я тебя встретила, $C. Вот, прибыла в Терамор, чтобы разобраться с дезертирством. Солдаты покидают свои посты, вражеские агенты проникают в город!$B$BОни распространяют лживую пропаганду, надеясь, что и другие к ним присоединятся!$B$BАгенты буквально повсюду – у всех сторожевых постов в городе и доках. Необходимо выявить их и дискредитировать! Пока ничего больше и сделать нельзя, иначе только вызовешь к ним еще больше доверия.', 'Прогоните 5 дезертиров-подстрекателей и вернитесь к докам Терамора к Калии Гастингс.', 'Очень хорошо, $N. Думаю, нам удалось застать их врасплох. Похоже, эти агенты считали себя в безопасности за городскими стенами.$B$BСо временем подстрекатели вернутся и снова будут распространять дезинформацию. А мы пока воспользуемся тем временем, что ты для нас выиграл, чтобы отогнать их как можно дальше.', NULL, NULL, NULL, 'Выявлено дезертиров-подстрекателей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11128, 'Пропагандистская война', 'Вражеские агенты не просто так заводят беседы со стражниками. Мы обнаружили множество листовок с призывом к дезертирству – каким-то образом их умудрились доставить в доки.$B$BКорабль, что привез листовки, еще стоит в Тераморе, в дальнем доке. Если тебе удастся проникнуть на борт и выкрасть оставшиеся пропагандистские листовки, то вражеские агенты утратят свое самое мощное оружие. Только осторожнее! Команда – опытные каперы. Груз, скорее всего, держат в капитанской каюте.', 'Доставьте дезертирскую пропаганду Калии Гастингс к докам в Тераморе.', '<Агент ШРУ одобрительно кивает.>$B$BБлестяще. Остается только дискредитировать дезертиров так, чтобы они больше носу не сунули в Терамор, и у меня на этот счет есть план.', 'Тебе удалось найти и захватить оставшиеся пропагандистские листовки?', NULL, NULL, 'Ящик с листовками дезертиров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11129, 'Пропал Кайл!', 'Помоги мне, $N! Мой любимый щенок Кайл сбежал! Я знаю, он потерялся и теперь бегает вокруг Деревни Кровавого Копыта, голодный и несчастный.$B$BПожалуйста, отыщи его и покорми. Он поест, утешится и вернется домой.$B$BНо сначала надо найти для него еду. Его любимое блюдо - нежное мясо долгоногов. Отправляйся на восток, там их - хоть пруд пруди. Убей одного из них и принеси его сочное мясо Кайлу. Как увидишь Кайла в городе - предложи ему мясо, и он непременно подойдет к тебе.', 'Анаб Пшеничная Грива из деревни Кровавого Копыта в Мулгоре попросил найти его лучшего щенка, Кайла Бесноватого.Покормите Кайла нежным мясом долгонога и возвращайтесь к Анабу Пшеничной Гриве.', 'Отличная работа, $N! Как только Кайл наелся, он сразу вернулся домой и завалился спать. Спасибо за помощь.', 'Ну как, ты нашел Кайла?', NULL, NULL, 'Накормите Кайла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11130, 'Ой, блестяшечки!', 'Ходи сюда, $gпарниша:лапуля:! Дай старине Грифтаху посмотреть на твои блестяшечки...$B$BХммм. Да-да, неплохо, но ты можешь добыть больше. Куда больше.$B$B*Грифтах наклоняется к вам и шепчет.*$B$BСлавные блестяшечки - они повсюду, $N, только надо знать, где искать! Нынче тебе свезло так свезло - я знаю парня, который поможет тебе найти столько блестяшек, что и не унесешь.$B$BЗайди к моему старому приятелю, Бадду - он болтается близ Зул\'Амана, и покажи ему вот это. Он поймет, что тебя послал старый Грифтах, и он тебя посвятит в свою затею.', 'Жуль хочет, чтобы вы взяли его записку и отнесли ее Бадду в Призрачные земли к Зул\'Аману.', '*Бадд читает записку.*$B$BА, друг Жуля? Добро пожаловать!$B$BКак раз вовремя. По роковому стечению обстоятельств я недавно лишился своих партнеров. Настоящая трагедия, но большой выигрыш стоит больших затрат. Но лучше не думать о плохом!$B$BТы, несомненно, уже знаешь о моих бесчисленных изобретениях и открытиях, но все они – ничто по сравнению вот с этим! Честно говоря, мы тут в Зул\'Амане, можно сказать, творим историю, и ты по велению судьбы вступаешь в дело с самого начала!', '*Бадд с подозорением рассматривает записку.*$B$BЧто тут у тебя, $C?', NULL, NULL, 'Записка Жуля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11131, 'Гаси пожар!', 'Вы должны помочь нам! Всадник без головы напал на деревню! Кругом пожар! Дети в опасности!$B$BПожалуйста, $N, помогите пожарной бригаде. Берите ведро и заливайте пожар или передавайте ведра по цепочке! Погасите пожар, и мы, может, еще спасемся!', 'Переодетая попечительница сирот просит вас помочь потушить пожар в деревне. Когда пожар будет потушен, снова поговорите с попечительницей сирот.', 'О, спасибо! Да благословит Свет ваши добрые деяния, добрый господин. Тень Темного Всадника все еще стоит у нас за спиной, но по крайней мере хотя бы на некоторое время деревня может не опасаться пожара.', '$N, вы обещали спасти детей!', NULL, NULL, 'Пожар потушен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11132, 'Все обещаешь и обещаешь', 'Мои изыскания подтверждают слухи об огромном сокровище, спрятанном в Зул\'Амане. Там для каждого найдется своя гора золота с холмиком! Но сначала ты $gдолжен:должна: заработать свою долю в этом пироге.$B$BНаша первая попытка достать эти сокровища пошла не так гладко, как я надеялся. Фактически, моя карта и те неумехи, которым я ее вручил, пропали без вести. Они отправились за троллем по имени Налоракк.$B$BЗабудь об этих неудачниках, мне нужна карта! Добейся успеха и ты войдешь в историю как тот, кто помог Бадду Недреку раскрыть тайны Зул\'Амана.', 'Разыщите карту Бадда Недрека на террасе верховного шамана Налоракка в Зул\'Амане и верните ее хозяину.', '*Бадд выглядит слегка ошеломленным.*$B$BЧто? Ты нашел ее?$B$BКхм... ТО есть, что это я... Конечно нашел! Отлично, $C.$B$BДай-ка взглянуть, смогу ли я найти, что-нибудь стоящее, чтобы отблагодарить тебя. О! Это подойдет.', 'Ну что, нашел мою карту?', NULL, NULL, 'Карта Зул\'Амана, принадлежащая Бадду', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11133, 'Дискредитация вражеской агентуры', 'Я кое-что изменила в листовках, которые ты $gпохитил:похитила: у наших заклятых друзей в доках. Теперь они пропагандируют совсем другое!$B$BЕсли мы подкинем побольше этих листовок страже, врагам вряд ли удастся так легко снова угнездиться в наших стенах.$B$B<Калия вручает вам стопку подправленных листовок.>$B$BНе займешься этим, пока я обдумываю наш очередной шаг?', 'Калия Гастингс просит вас всучить подправленные листовки 6 тераморским стражникам. После этого вернитесь к Калии и доложите о выполнении задания.', '<Калия прищелкивает языком, когда вы описываете ей реакцию стражников на листовки.>$B$BКак я и надеялась! Думаю, теперь-то уж точно любого вражеского агента, который попытается сунуться в Терамор, просто высмеют.', 'Мне показалось, что я слышала смех из казарм. Ты раздал мои листовки?', NULL, NULL, 'Листовок роздано', 'Подправленные листовки (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11134, 'Конец вражеской пропаганде', 'С дезертирами из Терамора мы разобрались, операцию пора завершать. Местные осведомители сообщили, что база дезертиров – на корабле, который швартуется у небольшого острова к юго-востоку от пристани.$B$BЕсли арестовать их главаря Гависа Серого Щита, то у остальных отпадет всякая охота сражаться. Найди его на том корабле и заставь сдаться. Не удивлюсь, если сначала он набросится на тебя, но когда поймет, что ему не победить, то успокоится.', 'Арестуйте Гависа Серого Щита, затем доложитесь Калии Гастингс у доков Терамора.', 'Просьба Гэвиса не так нелепа, как может показаться. Если провести операцию должным образом, то леди Джайна сумеет вернуть дезертиров на путь истинный, но решение, конечно же, за ней.$B$BПриятно было работать с тобой, $N. Сомневаюсь, что без твоей помощи операция прошла бы столь же гладко. Когда буду писать рапорт в Штормград, обязательно скажу, что ты - тот самый $C, который покончил с угрозой дезертирства.', NULL, NULL, NULL, 'Гавис Серый Щит арестован', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11135, 'Всадник без головы', 'Ты $gпрогнал:прогнала: Всадника без головы, но пока существует Тыквовин, он будет возвращаться. Прошу тебя, $N, положи конец нашим несчастьям! Сил больше нет выслушивать безумные причитания Всадника! Сразись с ним, пока голова еще сидит на его плечах!$B$BОн покоится в Покинутом ските Монастыря Алого ордена в Тирисфальских лесах. Найди его святилище тыквы и скажи такие слова:$B$BВсадник, встань$BПришла пора$BУмереть в последний раз!$B$BИди же, $N. И да пребудет с тобой Свет.', 'Найдите святилище тыквы Всадника без головы.', 'Откуда взялось это святилище, никому не ведомо, но кому оно посвящено – никаких сомнений нет...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11136, 'Тревожные события', 'В последнее время доклады патрульных все тревожнее. На Зловещем берегу, что к северу от стен Терамора, видели людей с красными повязками Братства Справедливости.$B$BВ том районе нашли обломки корабля, так что они могли выжить в кораблекрушении... но у нас мало сведений об этом. Капитан Ваймор со Сторожевого поста – это башня к северу от города – ищет помощников, которые возьмутся за прояснение ситуации.', 'Поговорите с капитаном Ваймором на Сторожевом посту.', '*Капитан откровенно оценивает вас взглядом.*$B$BЗначит, вам известно о недавнем кораблекрушении? Отлично, я буду рад помощи в выяснении моих подозрений насчет выживших. Добро пожаловать на борт, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11137, 'Братство Справедливости в Пылевых топях?', 'Мои разведчики донесли о кораблекрушении на северо-востоке побережья. Кораблекрушения здесь - дело обычное, но донесения говорят о том, что выжившие носят красные банданы Братства Справедливости!$B$BОни ремесленники и цеховики, но не мореходы. Что они делают на месте кораблекрушения на континенте, который не представляет для них интереса?$B$BГоворят, их предводитель живет на большом острове недалеко от побережья, к северо-востоку от города. Убей его и принеси все документы, какие удастся найти.', 'Добудьте приказы Братства Справедливости у Гарна Маферса и принесите его капитану Ваймору на Сторожевой пост.', '<Капитан Ваймор берет у вас приказы и просматривает их.>$B$BЧто значит \"драгоценный груз\"? Братство Справедливости по мелочам протаскивало контрабанду в Штормград, но язык, которым написаны эти поручения, указывает на богатого и знатного клиента. Это совершенно не похоже на работу Братства.', 'Удалось выследить главаря?', NULL, NULL, 'Приказы Братства Справедливости', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11138, 'Ренн Макгилл', 'Судя по содержанию раздобытых тобой приказов, главная цель Братства Справедливости – обнаружение и захват груза.$B$BУ ШРУ уже достаточно давно в Тераморе действует ныряльщик по имени Ренн Макгилл. Когда он узнал про кораблекрушение, Ренн отправился нырять на север, к островам, которые сейчас заняло Братство Справедливости.$B$BЕсли мы хотим добраться до груза раньше, чем Братство, нам нужна помощь Ренна. Ищи его у северо-восточного побережья островка, расположенного чуть севернее, чем тот остров, на котором ты $gпобывал:побывала: до этого.', 'Отнесите приказы Братства Справедливости Ренну Макгиллу. Он плавает недалеко от Зловещего берега.', '<Ренн просматривает приказы.>$B$BЗначит, на борту был ценный груз! Нужно обойти Братство Справедливости и найти его первыми. Ныряльщики из этих ребят никудышные, но вот их снаряжение мне бы пригодилось.', 'Здорово, $C. Что привело тебя в такую даль?', NULL, NULL, 'Приказы Братства Справедливости (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11139, 'Старое водолазное снаряжение', 'Отсюда и до Алькаца все дно усеяно обломками затонувших кораблей, и водолазы Братства Справедливости уже вовсю собирают \"урожай\". С помощью их снаряжения мы и тебя отправим на охоту, но сначала его надо, так сказать, \"позаимствовать.\"$B$BВ общем, так: обойди остров, найди ящик с испорченным водолазным снаряжением и инструменты для починки. Потом тащи все это мне, и я тебя быстренько экипирую!', 'Принесите набор инструментов и испорченное водолазное снаряжение Ренну Макгиллу в Пылевые топи.', 'М-да... состояние плачевное... Я думал, что будет получше. И инструменты... ну ладно.$B$BЯ обещал починить снаряжение, и я его починю. Вот прямо сейчас и займусь.', 'Ну-ка, посмотрим, что тебе удалось \"позаимствовать\" у Братства.', NULL, NULL, 'Поврежденное снаряжение подводника', 'Набор инструментов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11140, 'Вернуть груз!', 'Ну что ж, я кое-как заштопал снаряжение, так что немного понырять ты сможешь. Но особо долго сидеть под водой не советую.$B$BОбломки корабля разбросаны по дну, начиная от восточного побережья этого острова и до самого острова Алькац. Пока шлем держится, походи по дну между островами и поищи обломки, а потом попытайся извлечь из них груз с помощью этого набора спасателя. Но слишком близко к Алькацу не подходи, а то тебя там гидры сожрут.', 'Принесите 6 поднятых со дна сундуков Ренну Макгиллу в Пылевые топи.', '<Ренн копается в содержимом сейфов, которые вы нашли.>$B$BТы молодец. Посмотрим, что это за ценный груз такой...', 'Ну что, нашлось какое-нибудь добро Братства Справедливости?', NULL, NULL, 'Трофейный сейф', 'Набор спасателя', 'Припасы Ренна', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11141, 'Джайна должна быть в курсе', 'Немедленно оповести леди Джайну о том, что нам удалось узнать! Бандиты перевозили пленника, и мы не знаем, кто это и жив ли он или она до сих пор!$B$BНо в одном нет сомнений, $N. Эти бандюги в петлю по мелочам не полезут. Наверняка их пленник – очень важная персона. Леди Джайна должна знать об этом больше, чем кто-либо другой. Найди ее на вершине башни магов в центре Терамора.', 'Поговорите с леди Джайной Праудмур в Тераморе.', 'Вы с Ренном просто молодцы, что вывели на свет эти сведения и тотчас же доложились мне. Несомненно, Братство Справедливости затевает что-то недоброе против Штормграда и его союзников. Но для них этот замысел уж слишком хитроумен, стало быть, у них где-то завелся богатенький покровитель.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11142, 'Исследование острова Алькац', 'Похоже, догадка Ренна насчет острова Алькац оказалась верной. Нам надо обследовать этот остров, но, чтобы пробиться туда, потребуется целый вооруженный отряд.$B$BОборона Терамора сейчас не может позволить себе такую роскошь, поэтому я договорилась с Коссой Багровое Крыло, ученицей тераморского укротителя грифонов, чтобы она дала тебе одно из своих животных для обследования Алькаца с воздуха.$B$BТолько на острове Алькац можно найти намек на то, что Братство Справедливости причастно к похищению.', 'Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы обследовать остров Алькац. После выполнения поручения отрапортуйте леди Джайне Праудмур в Тераморе.', '<Леди Джайна внимательно выслушивает ваш доклад по результатам обследования острова Алькац.>$B$BКруг рун, драконид? Я знаю, что в Братстве Справедливости есть тайные маги, но не особенно могущественные, чтобы пользоваться такими вещами!$B$BИ почему черные дракониды вдруг заинтересовались островом, кишащим нагами? Слишком много вопросов без ответов, но в одном я точно уверена: у Братства Справедливости есть сильный союзник в высшем руководстве Альянса.', 'Ты закончил исследование острова Алькац?', NULL, NULL, 'Исследование острова Алькац', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11143, 'Мрачные выводы', 'Я говорил с инспектором Таремом по поводу информации, добытой тобой на пепелище \"Последнего привала\". Похоже, он уверен, что следы копыт и найденный тобой щит указывают на тауренское племя Зловещего Тотема.$B$BС учетом донесений об их активности на болотах это вряд ли можно считать простым совпадением. Я отправляю тебя к капитану Дариллу, он у нас что-то вроде специалиста по делам этого племени. Из города ступай по дороге на север, к Северной башне. Это вторая застава на дороге.', 'Доложитесь капитану Дариллу в Северной башне.', 'Капитан Ваймс считает, что племя Зловещего Тотема повинно в преступлении, совершенном в таверне \"Последний привал\"? Я бы не ставил их первыми в списке подозреваемых, но раз капитан Ваймс прислал тебя для дальнейшего расследования, должно быть, у него были на то причины. В любом случае, племя Зловещего Тотема давно у нас как заноза в пятке, и мы всегда рады принять любую помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11144, 'Подтвержденные подозрения', 'Возможно, Зловещий Тотем – самое воинственное из тауренских племен, но они весьма организованы. Если это они подожгли \"Последний привал\", значит, действовали по приказу одного из своих старейшин.$B$BБольшое селение племени – деревня Черного Копыта – находится на северо-западе отсюда. Там и была база для нападений на башню. Могу поклясться – в деревне ты найдешь те самые приказы, которые тебе нужны. Поищи их у старейшин.', 'Принесите боевой план племени Зловещий Тотем капитану Дариллу в Северную башню.', '<Капитан Дарилл просматривает боевой план.>$B$BЯ бы сказал, что все яснее ясного. Они берут на себя уничтожение людских поселений в этих краях, и я не сомневаюсь, что следующим в списке будет Терамор.', 'Удалось найти какие-нибудь следы приказов?', NULL, NULL, 'Боевой план племени Зловещего Тотема', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11145, 'Пленники Зловещего Тотема', 'Мы делаем все возможное, чтобы сдерживать племя Зловещего Тотема, но они так и продолжают нападать на башню. А хуже всего то, что они похитили патрульных, которых наш капитан посылал на поиски информации и охрану дороги.$B$BЯ думаю, что заложников держат в деревне Черного Копыта, она на северо-западе. Зная племя Зловещего Тотема, можно сказать, что ключи от клеток с заложниками наверняка у стражей – защитников поселения. Делай что угодно, $C, только верни наших ребят живыми!', 'Сержант Лукас из Северной башни просит вас спасти 5 тераморских пленников.', 'Освобожденные пленники уже возвращаются из деревни Черного Копыта. Информация, которую получит от них капитан, позволит нам лучше подготовиться к следующей битве с племенем Зловещего Тотема.$B$BБлагодарю тебя от себя лично и от имени всех наших солдат.', NULL, NULL, NULL, 'Освобождено тераморских пленников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11146, 'Ловля ящеров', 'Полоса болот к северо-востоку отсюда - гнездо особенно мерзких ящеров. Из-за них мы потеряли уже не одного беспечного солдата, однако, полагаю, нам удасться натравить их на наших соседей из племени Зловещего Тотема.$B$BВозьми эту веревку и поймай с ее помощью несколько ящеров из Кровавой топи или крикунов из Кровавой топи. Впрочем, я бы не стал пытаться ловить этих тварей, пока не удастся хотя бы немного ослабить их в драке. А драка будет нешуточная.', 'Сержант Лукас из Северной башни просит вас поймать 6 ящеров. Вы можете ловить как ящеров Кровавой Топи, так и крикунов Кровавой Топи.', 'Видок у тебя малость помятый, но ничего страшного. В любом случае Зловещим Тотемам придется куда круче, когда наши чешуйчатые приятели займутся ими.', 'Удалось наловить ящеров?', NULL, NULL, 'Ящеров поймано', 'Прочная веревка (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11147, 'Боевые ящеры', 'Так, у нас есть ящеры, теперь их нужно как-то \"воодушевить\" на бой, чтобы они атаковали тауренов из племени Зловещего Тотема в деревне Черного Копыта на северо-западе.$B$BВот тут у меня остатки мяса... э-э... в общем, не важно, чье это мясо. Главное, что оно будет хорошей приманкой. Положи его на землю в деревне Черного Копыта, рядом с мельницей в центре поселка. А об остальном позаботятся ящеры.', 'Сержант Лукас из Северной башни хочет, чтобы вы положили приманку на ящера близ ветряной мельницы в деревне Черного Копыта.', '<Сержант не скрывает довольной усмешки.>$B$BВот и славно. Теперь они дважды подумают, прежде чем совершить очередной набег.', NULL, NULL, NULL, 'Ящеров отпущено', 'Приманка на ящера', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11148, 'Оружие племени Зловещего Тотема', 'Если обнаруженное тобой на пепелище таверны снаряжение принадлежало воинам из племени Зловещего Тотема, то наверняка в их лагере на северо-западе найдется еще больше.$B$BНам не удалось собрать достаточно информации о деревне Черного Копыта, но, судя по численности нападавших, там базируются значительные силы.$B$BСделай все, чтобы получить их снаряжение и сравнить с найденным у таверны.', 'По просьбе капитана Дарилла из Северной башни принесите ему 7 предметов вооружения из деревни Черного Копыта.', '<Капитан Дарилл осматривает принесенное вами из деревни Черного Копыта вооружение.>$B$BСомневаться не приходится – вооружение в точности соответствует описанию. Но дело в том, что оно ни разу не побывало в бою. Должно быть, деревня Черного Копыта – не единственный аванпост племени Зловещего Тотема в топях.', 'Ты принес вооружение из деревни Черного Копыта?', NULL, NULL, 'Оружие Черного Копыта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11149, 'Помощь Табеты', 'В помощь второй заставе племени Зловещего Тотема выделить мне некого, но я, кажется, знаю, кто тебя выручит. $B$BВ самом сердце Трясины, к югу отсюда, стоит маленький домик, хозяйку зовут Табета. На первый взгляд, просто старая отшельница, но на самом деле она волшебница и провидица, причем небезызвестная. Иди по дороге на юг до самого ее дома и попроси Табету помочь найти виновных в преступлении, совершенном в таверне \"Последний привал\".', 'Поговорите с Табетой в ее доме.', 'Значит, ты хочешь, чтобы я предсказала будущее племени Зловещего Тотема? А если я скажу, что нужды в том нет?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11150, 'Уничтожение заставы Дикого Рога', 'Незачем гадать, чтобы увидеть угрозу, которая исходит от моих \"соседей\". И если это та самая банда, что сожгла \"Последний привал\", как ты говоришь, то нужно действовать немедля.$B$BБери вот этот факел и предай их лагерь огню! Ты найдешь заставу Дикого Рога к северу от моей усадьбы. Пропустить ее совершенно невозможно, эти варвары уже успели наставить вокруг свои драгоценные тотемы.', 'Сожгите северную, восточную и северо-восточную палатки на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.', 'Надеюсь, племя Зловещего Тотема усвоило урок. Попытаются вернуться – мы их встретим не только факелом. Мои ученики помогут мне дать отпор.', 'Ну что, хорошо разгорелось?', NULL, NULL, 'Северный шатер подожжен', 'Северо-восточный шатер подожжен', 'Восточный шатер подожжен', 'Факел Табеты (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11151, 'Справедливая месть за Хьялей', 'Пусть племя Зловещего Тотема досаждало мне немногим, капитан Ваймс захочет послушать о твоих свершениях. Доложи ему, что тебе удалось выследить и уничтожить тех, кто спалил таверну \"Последний привал\".$B$BХоть это и не воскресит семью Джима Хьяля, но, может, племя Зловещего Тотема теперь дважды подумает, перед тем как нападать на тех, кто связан с Терамором.', 'Поговорите с капитаном Гарраном Ваймсом в цитадели в Тераморе.', '<Капитан внимательно выслушивает ваш доклад.>$B$BМы отомстили за Джеймса и его семью, но это их не вернет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11152, 'Обрести покой', 'Как бы дать знать жене и сыну Джеймса Хьяля, что мы отомстили их убийцам?$B$B*Капитан Ваймс достает маленький венок.*$B$BГоворят, что души все видят, даже если мы и не можем говорить с ними. Это малость, но если бы вы возложили этот венок на могилу семества Хьяль, я был бы вам очень благодарен. Это один из самых больших могильных памятников на кладбище к северу от ворот Терамора.', 'По просьбе капитана Гаррана Ваймса из цитадели возложите венок к памятнику семейства Хьяль.', '<Капитан Ваймс мягко улыбается, слушая ваш рассказ о событиях, произошедших у памятника семейству Хьяль.>$B$BПриятно знать, что они все видят. Ты же не рассказал им о Джеймсе, правда?$B$BЯ отправлю ему послание жены, хотя сомневаюсь, что он поймет.', NULL, NULL, NULL, 'Венок к памятнику семейства Хьяль возложен', 'Венок', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11153, 'Прорвать блокаду', 'Все наши корабли затоплены! Нам нужна твоя помощь, чтобы прорваться сквозь пиратскую блокаду в Пролив Кораблекрушений!$B$BВозьми эти кассетные бомбы и садись на дирижабль, который \"одолжил\" нам Боронайзер. На нем ты пролетишь прямо над палубами этих проклятых пиратов и раздашь им наши подарочки!$B$BТы – наша последняя надежда прорвать блокаду. Надеюсь, тебе удастся разнести их корабли в мелкие щепки!', 'Возьмите кассетные бомбы Петрова и сбросьте их на корабли, убив 25 матросов абордажной команды и уничтожив 10 абордажных пушек. Как только задание будет выполнено, вернитесь к бомбардиру Петрову в Крепость Западной Стражи.', 'Именно это я и надеялся услышать! А ты знаешь, что надо делать, $N!$B$BМожет быть, ты заглянешь завтра, когда мы изготовим новую партию бомб? Я бы не стал так долго ждать, но у меня кончилось гуано летучих мышей, а мой помощник Фекнат куда-то запропастился.$B$BИнтересно, что его так задержало?', 'А, это снова ты! Неужели тебе удалось прорвать блокаду? Ты ведь показал этим проклятым пиратам Северных морей, где раки зимуют?$B$BТак ведь?', NULL, NULL, 'Матрос абордажной команды убито', 'Уничтожено абордажных пушек', 'Кассетные бомбы Петрова', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11154, 'Пусть обделаются от страха!', 'Эй, ты! Да, ты... иди сюда, мне нужна твоя помощь!$B$BПетров послал меня сюда собирать гуано летучих мышей для кассетных бомб, которые он мастерит в крепости, но я не собираюсь соваться прямо в лапы смерти!$B$BКороче, темнолапые летучие мыши водятся только на Вырубках к северу отсюда, но с этой платформы я сойду только в направлении дома!$B$BА вот ты... ты можешь совершить этот подвиг ради меня! Правда? Ну пожалуйста!!!$B$BВот, держи хлопушки. Основная мысль такова: бросаешь их рядом с летучими мышами, и они гадят от страха!', 'Соберите 10 кусков гуано темнолапых летучих мышей и отнесите их инженеру Фекнату к Стальным воротам.', 'Фу, чем тут воняет? А, это ты! Да, пахучую работенку я тебе подбросил!$B$BСпасибо тебе, $C. Не волнуйся, я сам доставлю груз Петрову, как только мы выберемся отсюда.$B$B<Фекнат кричит исследователям.>$B$BЭй, слышите, парни? Вытаскивайте нас отсюда!!!', 'Пожалуйста, скажи мне, что ты принес гуано!', NULL, NULL, 'Гуано темнолапой летучей мыши', 'Хлопушки Фекната', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11155, 'Снова суп из черпорога?', 'После всех этих таинственных исчезновений домашнего скота нам не мешало бы озаботиться припасами. Иначе хищные звери станут нашей последней заботой!$B$BПоскольку я тут несколько занята приготовлением пищи, тебе придется отправиться на восток и поохотиться на черпорогов. Именно их нежное мясо я хочу сегодня приготовить. $B$BСмотри, не попадись им на рога!', 'Шеф-повар Дымкотел поручила вам добыть 6 кусков мяса черпорогов и принести их ей в Крепость Западной Стражи.', 'А, вот и обед для мальчиков!$B$B<Шеф-повар наклоняется к вам и шепчет на ухо.>$B$BЗнаешь, малыш, тебе тоже не помешает чашка горячей похлебки. Только посмотри на себя – кожа да кости!', 'Нет ничего вкуснее нежного мяса черпорога, срезанного с боков!', NULL, NULL, 'Мясо черпорога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11156, 'Налетчики Дикого Рога', 'Племя Зловещего Тотема с заставы Дикого Рога наглеет день ото дня. По ночам часто слышно, как они горланят песни о своих подвигах на ниве борьбы с теми, кто пытается тут осесть.$B$BОни твердо намерены выгнать нас из домика Табеты, хотя она тут воспитала целое поколение учеников. Мы защищали дом как могли, но ученика Гариона во время последнего нападения ранили.$B$BСтупай на заставу Дикого Рога и перебей всех, кого встретишь! С этим надо покончить!', 'Убейте 12 тауренов из племени Зловещего Тотема с заставы Дикого Рога и вернитесь к ученику Морланну в усадьбу Табеты.', '<Ученик Морланн кивает.>$B$BЭто хорошо. И не могу сказать, что буду страдать без их общества. А то даже в сердце трясин уединения не найдешь!', NULL, NULL, NULL, 'Убивайте тауренов из племени Зловещего Тотема на заставе Дикого Рога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11157, 'В тисках зла', '$N, такое поручение я могу доверить только тебе. Нужно уничтожить яйца протодраконов и детенышей протодраконов в горящем лесу на юго-востоке! $B$BС тех пор, как мы прибыли сюда, в Пылающем Гнездовье не стихают пожары. Должно быть, это результат действия какой-то ужасной магии. В последнее время ситуация ухудшилась, и мои люди опасаются, что в ближайшие несколько недель мы все окажемся в огненной ловушке!$B$BОтправляйся туда и устрани угрозу, уничтожив яйца и детенышей протодраконов.', 'Уничтожьте 15 яиц протодраконов и 15 детенышей протодраконов, после чего вернитесь к капитану Адамсу в Крепость Западной Стражи.', 'Отличная работа! Если нам повезет, эти чудовища испугаются за своих детенышей и отступят, остановив распространение магического огня.$B$BПогоди... что это за звук? Похоже на хлопанье крыльев.', NULL, NULL, NULL, 'Разбито яиц протодракона', 'Детеныш протодракона убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11158, 'Перья Кровавой Топи', 'Твоя что, Брогг испугался, крошка $r? Не боись. Гоблины Шестермути Броггу друзья, и твоя может быть друг.$B$BБрогг ушел из Гиблотопи, когда наша новый властитель не стал делать мстю черным драконам за то, что они сломали наш старый дом и убили много друзей Брогга. Брогг сюда пришел упокоить души друзей и отомстить, но Броггу надо помогать подготовиться. Для ритуала Броггу надо перья с сильной магией, как у ящеров логова Кровавой Топи на западе от города.', 'Принесите 5 перьев Кровавой Топи Броггу в Шестермуть.', '<Брогг берет перья.>$B$BБрогг довольный этими перьями. Очень сильная магия. Брогг не знает, что делать ящеры, чтобы перья были сильные, но перья ящеров всегда лучшие для ритуала.', '<Брогг с надеждой смотрит на вас.>$B$BТвоя приносить Броггу перья?', NULL, NULL, 'Перо Кровавой Топи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11159, 'Духи в руинах деревни Каменного Молота', 'Брогг закончил мастерить тотем, который поможет душам его друзей обрести покой. Когда драконоры напали на деревню Каменного Молота, они убили всех, кто не спасся бегством. Брогг бежал вместе с владыкой Мок\'Морокком, надеясь повести выживших жителей деревни в контратаку.$B$BДо этого дело так и не дошло, а души убитых с тех пор не дают Броггу и всем остальным покоя. Отнеси этот тотем на север, в руины деревни Каменного Молота, и установи там рядом со скелетами огров, чтобы привлечь духов. Побежденный в бою дух сможет наконец упокоиться с миром.', 'Брогг из Шестермути просит вас дать покой 10 духам клана Каменного Молота.', 'Брогг благодарит тебя за помощь, хотя и знает, что от властителя Мок\'Морокка ты не дождешься слов благодарности. Но теперь, по крайней мере, выжившие члены клана могут наконец заняться насущными делами, и мертвые им больше досаждать не будут. А Броггу осталось сделать одну вещь.', 'Брогг должен знать, принес ли ты покой свирепым духам Каменного Молота?', NULL, NULL, 'Духов Каменного Молота упокоено', 'Заряженный тотем (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11160, 'Знамя Каменного Молота', 'Когда пришли драконы и отняли старый дом Брогга, огры Каменного Молота бежали и все бросили, даже знамя клана.$B$BБрогг знает, что знамя хранится глубоко в могильном кургане огров Каменного Молота, но теперь он зовется Огненное логово. Брогг должен получить клановое знамя, чтобы отомстить драконам, которые убили его друзей.$B$BДревний курган клана Брогга, Огненное логово, кишащее драконидами, находится на северо-западе от Шестермути. Знамя глубоко в пещере. Будь осторожнее, $N.', 'Добудьте знамя Каменного Молота и принесите его Броггу в Шестермуть.', 'Брогг тебе благодарен, $N. У Брогга большие планы на клановое знамя.', 'Принес знамя Каменного Молота?', NULL, NULL, 'Знамя Каменного Молота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11161, 'Сущность вражды', 'Чтобы сделать тотем для своего ритуала, Броггу понадобятся сущности тех, кто убил его друзей. Ненависть и ярость врагов Брогга придаст мстительной магии еще больше сил.$B$BВыследи огнегривых пеплохвостов, разведчиков или чешуйчатых губителей и поставь тотем Брогга рядом с их телами. Драконы отдают свои сущности только когда умирают.$B$BЛучше всего искать их в Огненном логове на северо-западе или в руинах деревни Каменного Молота на севере.', 'Принесите 10 сущностей черного дракона Броггу в Шестермуть.', 'Ты получаешь благодарность Брогга, $N. Как только Брогг отдает свою магию тотему, тотем освобождает духов убитых друзей Брогга.', 'Принес сущности? Они нужны Броггу, чтобы отомстить за друзей!', NULL, NULL, 'Сущность черного дракона', 'Тотем Брогга (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11162, 'Бросить вызов черным драконам', 'Брогг лелеет мысль отомстить черным драконам болот. $N, ты очень $gпомог:помогла: в подготовке к этому мероприятию. Хочешь помочь еще?$B$BБери клановое знамя Брогга и поезжай на восток, пока не найдешь пещеру, похожую на драконью пасть. Водрузи знамя Каменного Молота у входа в пещеру и брось Ониксии вызов Брогга!$B$BБрогг и Каменные Молоты вернут себе свою землю!', 'Установите знамя Каменного Молота у входа в Логово Ониксии, затем вернитесь к Броггу в Шестермуть.', '*Брогг слушает ваш рассказ о том, что произошло у входа в Логово Ониксии.*$B$BБрогг так и знал, что Ониксия побоится биться с тобой. Все черные драконы нападают, только когда победа однозначна.$B$BБрогг благодарен тебе за помощь, $N. Он никогда не забудет, что ты для него сделал. Брогг никогда не отступит от своей цели вернуть Каменный Молот на родину!', 'Брогг свершит свою месть!', NULL, NULL, 'Клан Каменного Молота отмщен', 'Знамя Каменного Молота (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11163, 'Тайная Сестрица', '*Донна подозрительно оглядывается по сторонам и шепчет тебе.*$B$BТо, что я тебе сейчас скажу, должно остаться между нами, смекаешь?$B$BМеня прислали сюда мирохранители Шаттрата, чтобы я проникла в банду Бадда. С самого твоего появления, ты привлек мое пристальное внимание. Но твои действия полностью очистили тебя от всех подозрений. А за то, что ты убил Зул\'джина, мне поручено вручить тебе награду.', 'Доберитесь до Донны Браско, чтобы получить причитающуюся вам награду. Найти Донну можно на Призрачных Землях, сразу за окраиной Зул\'Амана.', '*Донна подозрительно оглядывается по сторонам и шепчет тебе.*$B$BТо, что я тебе сейчас скажу, должно остаться между нами, смекаешь?$B$BМеня прислали сюда мирохранители Шаттрата, чтобы я проникла в банду Бадда. С самого твоего появления, ты привлек мое пристальное внимание. Но твои действия полностью очистили тебя от всех подозрений. А за то, что ты убил Зул\'джина, мне поручено вручить тебе награду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11164, 'Клыкастые всадники', 'Привет, $gчувак:чувиха:, ты тут типа $gновенький:новенькая:? Сделаешь для меня одну штуку?$B$BБадд затеял обновить свои личины лесных троллей. Говорит, что уже почти закончил, не хватает одной небольшой детали... Клыков.$B$BМое умение снимать шкуры тут абсолютно бесполезно...$B$BПринесешь мне десяток их клыков, а, $gдруг:подруга:?', 'Соберите для Пригмона 10 клыков лесных троллей в Зул\'Амане и принесите их ему в лагерь Бадда в Призрачных Землях.', 'Ага! Здорово! То, что надо!$B$BВот тебе обещанная награда.', 'Поторопись, чувак, Бадд сказал, что пошлет меня в лес проверять действенность его личин, если я не принесу ему эти клыки.', NULL, NULL, 'Клык лесного тролля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11165, 'Троль из троллей', 'Слушай $gприятель:подруга: есть еще кое-что. Что ты можешь сделать для старины Пригмона.$B$BЗунгам, мой совершенно никчемный кузен был засажен за решетку в Зул\'Амане. Он там все еже жив, я получил от него весточку, только прошлой ночью.$B$BНе должен я был ему позволять втягивать меня в эту заваруху, но он должен мне нехилую сумму денег.$B$BВытащи его, каким угодно способом, и не бойся помять, пока тащишь его ко мне.', 'Найдите Зунгама и помогите ему выбраться из Зул\'Амана.', 'Я свободен!$B$BОни меня ободрали как липку, $N, когда кинули сюда, - вот последняя моя монетка, тебе за труды.$B$BА мне видно придется пойти по миру...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11166, 'Крестом на карте обозначена... твоя смерть!', 'Нет, ну как они могли провалиться? Идиоты! Говорил я им, будьте осторожнее, и даже выдал им маскировку, чтобы было проще. Ладно, туда им и дорога. Теперь этим делом займешься ты.$B$BЕсли ты добьешься успеха, то я сочту тебя достойным вступить в ряды моей команды, молва о которой скоро прогремит по всему миру. И на меньшее я не согласен.$B$BНам осталось заполнить еще несколько участков на моей карте, и тогда мы сможем начать раскопки.', 'Отправляйтесь в Зул\'Аман и посетите чертог Халаззи, платформу Джан\'алая и платформу Акил\'зона. Заметьте все подробности и по возвращении доложите о них Бадду в его лагере в Призрачных землях.', '*Бадд пытается скрыть свое замешательство.*$B$BЭээ... Да... $N. Ты, да... Как раз вовремя. По правде сказать. На тебе сейчас и держится вся операция.$B$BЛадно, давай продолжим разбираться с белыми пятнами на этой карте.', NULL, NULL, NULL, 'Посетите чертог Халаззи', 'Посетите платформу Джан\'алая', 'Посетите платформу Акил\'зона', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11167, 'Новая чума', 'Вскоре после того, как Артас приговорил нас к этому жалкому существованию, Королевское фармацевтическое сообщество начало разрабатывать штамм новой чумы, которая могла бы растворять любую плоть, будь то человека, животного или нежити.$B$BНедавно мы закончили наши исследования в Подгороде и уже собирались передать готовый штамм Плети, когда в наши планы вмешался Альянс. Он захватил корабль, перевозивший образцы чумы. Поэтому я прошу тебя отправиться на юго-восток, к месту кораблекрушения, и поискать любые сохранившиеся образцы.', 'Аптекарь Лисандер из Лагеря Возмездия просит вас собрать 10 неповрежденных флаконов с чумой с места кораблекрушения на юго-востоке.', 'Я рад видеть тебя живым и невредимым. Видишь ли, переноска этих контейнеров не абсолютно безопасна – можно было и заразиться. Наверное, мне стоило предупредить тебя об этом.', 'Ты принес флаконы, $N?', NULL, NULL, 'Неповрежденный чумной флакон', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11168, 'Добавить крепости', 'Похоже, долгое путешествие через море негативно сказывается на эффективности чумы. Нам надо добавить мощный токсин, чтобы усилить воздействие штамма.$B$BМне кажется, что вот эти береговые членистоногие могут быть дальними родственниками мелких темнопанцирных прибрежных крабов. Последние водятся в тропических районах и выделяют столь мощный паралитический яд, что одного укуса хватит на целого огра.$B$BНо мы же знаем – чем больше особь, тем лучше! Возможно, эти гигантские прибрежные крабы будут нам полезны. Принеси-ка мне несколько ядовитых желез!', 'Принесите 3 гигантские ядовитые железы гигантских прибрежных крабов аптекарю Лисандеру, который будет ждать вас в Лагере Возмездия в Ревущем фьорде.', 'Я рад нашему сотрудничеству, $N. Надеюсь, этого яда будет достаточно для того, чтобы усилить действие чумы.$B$BВ худшем случае, он хотя бы ослабит организм жертвы и сделает его более восприимчивым к болезни.', 'Ты принес мне ядовитые железы, $N?', NULL, NULL, 'Гигантская ядовитая железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11169, 'Оружие племени Зловещего Тотема', 'Во время последней атаки племени Зловещего Тотема меня ранили, но перед этим я успел захватить один любопытный тотем, который враги обращали против нас.$B$BПока шел бой, он будто испускал потоки энергии – но я так до сих пор и не смог понять принцип его работы. Я тебе одолжу этот тотем, если поможешь его испытать.$B$BВ водоемах вокруг фермы водятся крапчатые кроколиски-грязекупы и острозубы-грязекупы. Мерзкие твари. Попробуй сразиться с кроколисками, находясь рядом с тотемом.', 'Ученик Гарион из усадьбы Табеты хочет, чтобы вы испытали захваченный тотем на 10 крапчатых кроколисках-грязекупах или грязекупах-острозубах.', '<Вы подробно рассказываете о ходе эксперимента.>$B$BТуман и молния? И все? Но ведь этот тотем должен вызывать еще какие-то эффекты! Тотем бы не стали нести на поле брани, не будь у него каких-то полезных свойств.', 'Какие успехи в изучении тотема?', NULL, NULL, 'Тотем испытан', 'Захваченный тотем (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11170, 'Испытания на море', 'Мы только что узнали, что войска Альянса выслали подкрепление. Как раз вовремя! $B$BНам не хватает подопытных особей, а эти резервисты Северного флота как раз подойдут для испытаний!$B$BВозьми эти склянки с чумой и поговори с Камиллой, дрессировщицей нетопырей. Скажи ей, что тебе нужна летучая мышь для специального задания.$B$BКак только окажешься над морем, сбрось склянки на флот Альянса. Интересно будет посмотреть на результат!', 'Поговорите с дрессировщицей нетопырей Камиллой, возьмите ездового нетопыря и летите наперерез войскам Альянса. Когда вы будете пролетать над флотом, сбросьте склянки с чумой и заразите 16 резервистов Северного флота.', 'Хммм...результаты не очень впечатляющие...', 'А, вот и ты!', NULL, NULL, 'Заражены чумой резервисты Северного флота', 'Склянки с чумой', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11171, 'Повелитель Проклятий? Пффф!', 'Отлично! Скоро мы триумфально войдем в Зул\'Аман.$B$BТы выложился по полной для общего дела, $N, и я говорил со своими ребятами - они не возражают против тебя. Так что ты заслужил свое место в команде. Осталась одна небольшая заминка. Ты должен убить, этого, как его... повелителя проклятий. Ничего страшного, тебе стоит посмотреть ему в глаза, и он бросится наутек. Старые, бессильные тролли часто прибавляют к своему имени громкие титулы, чтобы скрыть свою беспомощность...', 'Убейте в Зул\'Амане повелителя проклятий Малакрасса и вернитесь к Бадду Недреку на Холмы Томагавков.', 'Наконец-то! Теперь, когда вся подготовка закончена, я впишу свое имя в историю! Но перед этим... У меня осталось еще одно незавершенное дело, - ты...$B$BБоюсь, $N, пришло время отпустить тебя. Я знаю, то чего ты здесь достиг, - это далеко не предел...$B$BНе страдай понапрасну. В конце концов, для таких приключений нужно обладать определенным складом характера... чтобы не растерять последние мозги, понимаешь? И, смотри, у меня есть тебе небольшая безделушка, будем считать, что это на память.', NULL, NULL, NULL, 'Повелитель проклятий Малакрасс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11172, 'Крушение дирижабля', 'Не так давно к востоку отсюда разбился гоблинский дирижабль.Несколько дней назад в ту сторону проезжала представительница картеля \"Хитрая Шестеренка\".$B$BОна искала информацию о судьбе груза с дирижабля и его пилота, Бизиля, но никто из нас на месте крушения не был. Сомневаюсь, что она самостоятельно подчистит обломки. Еще менее вероятно, что она получит груз, который переправлял дирижабль.$B$BЕсли есть время, сходи к ней на место крушения дирижабля Бизиля, прямо на востоке отсюда, возле гор.', 'Поговорите с Мокси Сталегриль на месте крушения дирижабля Бизила.', 'Так тебя прислали маги-отшельники? Почем мне знать, что тебе можно доверять?$B$BХотя помощь-то мне как раз не помешает, но вот магам это совершенно не интересно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11173, 'Подмена реактива', 'Что ученик Морланн действительно умеет делать, так это скулить о нехватке реагентов.$B$BОбычно я его нытье мимо ушей пропускаю, но это не всегда помогает! На сей раз я заткну его другим способом.$B$BМожет, если незаметно подбросить недостающий реактив, он от меня отвяжется. Наш самый распространенный реактив – болотный яд, который получают из ползунов-темножвалов и пагубных живорезов, обитающих в болотах к северу от усадьбы. Принесешь яда, и я подолью его, пока Морланн не видит.', 'Принесите 6 флаконов болотного яда ученику Гариону в усадьбу Табеты.', '<Ученик Гарион изучает яд.>$B$BПросто прекрасные образцы! Он и не отличит.', 'Удалось добыть яд? Морланн в любую минуту может спохватиться, что его не хватает...', NULL, NULL, 'Болотный яд', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11174, 'Профилактика коррозии', 'Ты только посмотри! Слизнюки прям кишмя кишат. Если с ними не покончить, сожрут и обломки, и груз с дирижабля!$B$BА я не могу вернуться ни с чем, $C! Помоги мне разогнать этих слизнюков, пока они тут все не понадкусывали!$B$BЕсли включить это устройство, оно направит энергию на слизнюков, и они начнут взрываться. Разбитый энергетический сердечник дирижабля подпитает устройство. Тот кусок, что рядом с местом крушения, работает стабильно, остальные – не особенно.', 'Мокси Сталегриль хочет, чтобы вы уничтожили 10 слизнюков и доложили ей о выполнении задания на месте крушения дирижабля Бизила.', 'Ну, похоже, там и правда стало немного почище...$B$BПолагаю, пора заняться делом и основательно порыться в обломках.', 'Ну как, тебе уже удалось покончить со слизнюками?', NULL, NULL, 'Уничтожено слизнюков', 'Слизнебой (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11175, 'Дочка моя', 'Скажи, это правда, что все исследователи, отправившиеся в Шепчущую теснину, сошли с ума?$B$BМоя дочка работает надзирательницей в Лиге исследователей, и ее группа отправилась куда-то на север, к месту, которое называется Стальные ворота. Честно говоря, после всех ужасных событий, обрушившихся на нас, я опасаюсь за ее безопасность. $B$BПрошу тебя, $C, найди Ирену и убедись, что с ней все в порядке. Я уже стар, и мне не по силам совершить такое путешествие.', 'Старик Каменная Мантия попросил вас найти его дочку, надзирательницу Ирену Каменная Мантия в Стальных воротах.', 'Грр! Так я и знала! Трясется надо мной, как курица над цыпленком. Стыдно-то как!$B$BНет, ты только не подумай, что я тебе не рада... наоборот! Мы все рады тебя видеть. Нам так нужна твоя помощь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11176, 'Присматривая за работой', 'Наша работа здесь только начинается, но с прибытием летающих машин из Крепости Западной Стражи дела пойдут веселее.$B$BПроблема в том, что нам не хватает опытных пилотов. Хуже того, на Вырубках к северу отсюда начались какие-то проблемы, так что мне бы хотелось побыстрее закончить дела и отправиться домой. $B$BЕсли хочешь помочь нам, поговори с одним из главных археологов. Они сейчас осматривают ветролеты к северу и югу от раскопок.', 'Надзиратель Ирена Каменная Мантия попросила вас поговорить с главным археологом Стальных ворот.', 'Тебя Ирена прислала, да? Отлично! У нас найдется для тебя работа.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11177, 'Отшельник из сторожки \"Болотный огонек\"', 'Есть тут один старикашка по имени Ярл. Его называют \"Болотный глаз.\" Живет на болоте. Не так давно он \"унаследовал\" сторожку \"Болотный огонек\", когда ее предыдущий хозяин пропал при таинственных обстоятельствах.$B$BМне нужен тот, кто будет периодически проверять, что там происходит у этого \"Болотного глаза\". Знаешь, он мне чем-то напоминает моего деда. Тоже чуток не в себе, мягко говоря.$B$BИди на северо-запад по дороге из Терамора. \"Болотный огонек\" стоит на Ведьмином холме, как раз перед тем поворотом, где дорога уходит на запад.', 'Поговорите с Ярлом \"Болотным глазом\" в сторожке \"Болотный огонек\".', 'Убирайся с моей лужайки... хотя нет, погоди... Может, поможешь старому \"Болотному глазу\" приготовить обед? Ну как, согласен?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11178, 'Кровь Вождя', 'Пока ты изучаешь пульсирующий фиал, твои мысли обращаются к маленькому, вздорному человечку за стенами Зул\'Амана.$B$BПодумать только, какое лицо будет у Бадда, когда он это увидит.', 'Принесите кровь Зул\'джина Бадду в его лагерь в Призрачных Землях. За пределами Зул\'Амана.', 'К-кровь самого Зул\'джина?$B$B*Собравшись, Бадд продолжает.*$B$BХмм... Ну хорошо, я ценю твои усилия, $С, но сам бы я наверняка справился с этим гораздо быстрее. Быть того не может, чтобы он был настолько страшен, как врут старые сказки. В конце концов, понимаешь, что все эти легенды и побасенки всегда преувеличивают. Скорее всего этот старый идиот помер сам от артрита или чего-то в этом роде.$B$BВ любом случае, это был тот минимум, которым ты мог отплатить за проявленную к тебе здесь доброту.$B$BТеперь иди, я должен разобраться с этим мерзким фиалом.', '*Бадд пытается скрыть свое недовольство при виде тебя.*$B$BОпять ты...$B$BЯ не знаю, как еще тебе это сказать, - короче я сейчас слишком занят подготовкой, чтобы возиться еще и с тобой.$B$BПоверь мне. $N. Это все для твоего же блага. Возможно. Когда-нибудь твое имя будет известно повсюду. Тогда ты сможешь с гордостью говорить, что начинал под руководством несравненного Бадда Недрека!', NULL, NULL, 'Кровь Зул\'джина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11179, 'У Финлея кишка тонка', 'У нас так много лучников! И кто же должен следить за состоянием их оружия? Я, Финлей Флетчер!$B$BКомандир приказал мне и моим помощникам подготовить Крепость Диккор к походу, а у меня не было времени выбраться наружу и добыть кишечные струны, из которых изготавливается тетива. $B$B$C, $gмиленький:миленькая:, принеси мне несколько кишечных струн! Их можно добыть с туманных саблезубов, которые бродят возле фьорда. Только не тащи какие попало – мне подойдут только самые лучшие! Рваные кишки никуда не годятся.', 'Соберите 7 безупречных кишечных струн туманных саблезубов для Финлея Флетчера из Крепости Западной Стражи.', '', NULL, NULL, NULL, 'Безупречные кишечные струны туманного саблезуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11180, 'Что таится на Ведьмином холме?', 'Я приехал сюда навестить Ярла в его новом доме и с тех пор живу в постоянном кошмаре! С этим местом что-то неладно, наверняка не я один замечаю...$B$BТы $gвидел:видела: призраков и неупокоенных мертвецов вокруг Ведьминого холма? Чую, если кто и знает, что тут творится, так это они. Разыщи в окрестностях восставших мертвецов и духов, отправь их в бою на вечный покой – и посмотрим, что нам удастся выяснить, прежде чем зло окончательно сожрет Ярла!', 'Моргант Мрачник из сторожки \"Болотный огонек\" хочет, чтобы вы добыли информацию у 10 восставших мертвецов или духов.', '*Моргант достает листок бумаги и перо и набрасывает какие-то заметки по ходу вашего рассказа.*$B$BСудя по твоим словам, духами этого места должны стать все, кто тут когда-либо жил, и не только прежние владельцы.$B$BЧто-то завладевает ими и убивает их. Те, кто приезжает на это место, узнает правду слишком поздно. Мы должны положить этому конец, $N!', 'Что тебе удалось узнать от здешних неупокоенных духов?', NULL, NULL, 'Сведения получены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11181, 'Ведьмина погибель', 'За долгие годы работы травником я часто видел, как природа сама незаметно решает самые неприятные проблемы. Я читал, что тайные маги и знахари часто изгоняют зло дымом травки, называемой ведьмина погибель.$B$BЕсли это так, то ведьмина погибель должна расти неподалеку, на мелководье близ Ведьмина холма. Ты узнаешь ее по широким листьям и красноватому стеблю. Принеси мне травы, сколько найдешь, $N. Может, это наша единственная надежда.', 'Принесите 9 ростков ведьминой погибели Морганту Мрачнику в сторожку \"Болотный огонек\".', '<Моргант принимает у вас пучок травы.>$B$BЭто растение в точности соответствует описанию! Я подготовил факел, пока тебя не было. Осталось только прикрепить траву вот сюда.', 'Ну как, удалось набрать травы? Действовать нужно быстро, пока зло окончательно не завладело этим местом.', NULL, NULL, 'Ведьмина погибель', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11182, 'В поисках первопричины', 'Все в мире стремится к равновесию, и помешать этому могут лишь те, кому неведома великая гармония природы. $B$BТы зря тратишь свое время, убивая драконов и их детенышей. Истинная причина распространения магического пожара – недавно пробудившиеся врайкулы во главе с их повелителем, Скелдом Сыном Дракона.$B$BЕсли ты жаждешь обагрить свои руки кровью, начни с них. Ты найдешь логово врайкулов на южной стороне Пылающего Гнездовья.', 'Убить 5 укротителей из клана Укротителей драконов и Скелда Сына Дракона. Если вам удастся выполнить это задание, вернитесь к древу Пылающего Гнездовья.', 'К несчастью, я вынужден был послать одного хищника, чтобы тот убил другого, но таков естественный порядок вещей. $B$BВозможно, теперь протодраконы и их детеныши смогут вернуться к спокойной жизни. Меня беспокоят только пробужденные врайкулы.', 'Как твои дела, малыш? Удалось ли тебе справиться с этими назойливыми тварями?', NULL, NULL, 'Укротитель из клана Укротителей драконов убито', 'Скелд Сын Дракона убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11183, 'Очищение Ведьминого холма', 'Факел готов. Установи его в конце доков и готовься к сражению со всем, что на тебя полезет.$B$BПонятия не имею, кого именно вспугнет дым факела... если вообще хоть что-то появится. Короче, я не очень верю в эту народную магию, но ни на что другое у нас просто времени нет. Желаю удачи и тебе, и Ярлу.', 'Моргант Мрачник из сторожки \"Болотный огонек\" хочет, чтобы вы установили факел в конце дока и сразились с тем, что выйдет на свет.', 'Получилось?$B$B*Моргант прокашливается.*$B$BТо есть... получилось! Мы с Ярлом в долгу перед тобой, $N. Единственной проблемой осталась разборчивость моего приятеля в мебели, и, боюсь, ее так просто я не решу.', 'Все позади?', NULL, NULL, 'Ведьмин холм очищен', 'Факел Ведьминой погибели (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11184, 'Разыскивается: Кровокоготь Ненасытный', 'Путешественникам и персоналу Хитрой Шестеренки, работающему в поле, рекомендуется держаться подальше от логова Кровавой Топи, что к западу от города.$B$BМестность кишит ящерами, а верховодит ими очень злой и хитрый Кровокоготь Ненасытный – он уже убил по меньшей мере двух инженеров Хитрой Шестеренки.$B$BДраззит Кранотек назначил щедрое вознаграждение тому, кто избавит Шестермуть от этой напасти.', 'Уничтожьте Кровокогтя Ненасытного и сообщите об этом Драззиту Кранотеку, который находится в Шестермути.', 'Хвала небесам, наконец кто-то откликнулся на это объявление! Я уж думал, что придется утроить награду за голову этого дурацкого ящера, а наш бюджет такого не потянет!', NULL, NULL, NULL, 'Кровокоготь Ненасытный убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11185, 'Письмо аптекаря', 'Это письмо, найденное при аптекаре Отрекшихся, говорит о тесном союзе племени Зловещего Тотема и новых хозяев Лордерона.$B$B\"В качестве демонстрации доброй воли и в знак новообретенного доверия мы посылаем вам в помощь аптекаря Силлу. Она посодействует в битве против нашего общего врага в Калимдоре. Никто не устоит перед нашей объединенной мощью и решимостью.\"$B$BПисьмо надо доставить агенту ШРУ Анделло Портеру в усадьбу Табеты.', 'Отнесите запечатанное письмо привратнику Анделло в усадьбу Табеты.', '<Анделло читает письмо, потрясенный его содержанием.>$B$BМы давно подозревали, что Орда и Отрекшиеся в союзе, и это письмо подтверждает наши подозрения. При помощи магии и оружия Отрекшихся племя Зловещего Тотема станет еще более страшным врагом. Баланс сил в Калимдоре может сильно измениться.', 'Что там у тебя, $C?', NULL, NULL, 'Запечатанное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11186, 'Свидетельство предательства?', 'Это письмо, найденное при аптекаре Отрекшихся, говорит о тайной связи племени Зловещего Тотема и Подгорода.$B$B\"В качестве демонстрации доброй воли и в знак новообретенного доверия мы посылаем вам в помощь аптекаря Силлу. Она посодействует в битве против нашего общего врага в Калимдоре. Никто не устоит перед нашей объединенной мощью и решимостью.\"$B$BВозможно, Назир Кровавое Копье из деревни Гиблотопь знает, как распорядиться этой информацией.', 'Доставьте запечатанное письмо Назиру Кровавому Копью в Деревню Гиблотопь.', 'Если все и вправду так, то Отрекшимся придется объясниться!$B$BТаурены из племени Зловещего Тотема своими выходками давно испытывает терпение вождя. Мы обычно оставляли такие дела улаживать самим тауренам, но это письмо может все изменить.$B$BЭти подозрения еще надо проверить, так что никому не рассказывай о том, что видел сегодня.', 'Что там у тебя, $C?', NULL, NULL, 'Запечатанное письмо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11187, 'Маг-лейтенант Малистер', 'КАКОЙ УЖАС! Протодраконы напали на крепость!$B$BОбычно таких зверей легко отпугнуть, расправившись с их кладкой и детенышами.$B$BНо мы ведь все это уже испробовали, верно?$B$B$N, придется нам действовать более решительно. Поговори с моим советником, магом-лейтенаном Малистером. Он расскажет тебе, как разделаться с этими тварями.', 'Капитан Адамс попросил вас поговорить с его советником, магом-лейтенаном Малистером. Его можно найти в Крепости Западной Стражи.', '<Малистер подзывает вас к себе и приглушенно шепчет.>$B$BЭтого-то я и боялся. Я пытался отговорить капитана, но он предпочитает сначала действовать, а потом думать.$B$BЛадно, давай посмотрим, что нам остается делать.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11188, 'Минус на минус', 'Теперь, когда мы разворошили гнездо протодраконов в Пылающем Гнездовье, они будут постоянно нападать на крепость. Этого мы не можем допустить.$B$BЯ, конечно, не люблю вышибать клин клином, но в данном случае нам остается только уничтожить этих созданий. Мне жаль, но другого пути нет. $B$BВозьми мою волшебную палочку. Вообще-то я пытался увеличить радиус ее действия, но ничего путного не вышло. Однако теперь она отлично привлекает внимание протодраконов.', 'Маг-лейтенант Малистер поручил вам уничтожить 3 протодраконов.', '<Маг-лейтенант тяжело вздыхает.>$B$BДа, нелегкая тебе выпала доля. Ну, ладно – что сделано, то сделано. Надеюсь, новое поколение протодраконов из Пылающего Гнездовья не запомнит то, что мы с ними совершили.$B$BА если нам повезет, границы магического леса не будут расширяться.$B$BВот, $N, возьми этот скромный сувенир из нашей сокровищницы. Это самое малое, что мы можем для тебя сделать.', NULL, NULL, NULL, 'Протодракон убито', 'Ледяной жезл Малистера', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11189, 'В последний раз', 'Привет. Я что, умер? Судя по тому, что я болтаюсь над собственным телом, это действительно так.$B$BМда, какая жалость. Только я собрался сделать предложение Ирене, как на нас напали солдаты Плети. $B$BНо я знаю, что она все еще жива... я чувствую это. $B$B$C, не $gмог:могла: бы ты проводить меня к ней? Плеть все еще может видеть мою душу, и мне страшно даже подумать, что они могут со мной сделать. $B$BА мне бы так хотелось в последний раз взглянуть на ее прекрасное лицо. Прошу тебя, передай ей, что я ее люблю.', 'Сопроводите привидение исследователя Джарена к надзирательнице Ирене Каменная Мантия в Стальные ворота Ревущего фьорда.', '', NULL, NULL, NULL, 'Сопроводить призрак исследователя Джарена к Ирене Каменная Мантия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11190, 'К каждой пушке затычка', 'Вот скажи мне, $Gдружище:подруга;, какому умнику пришла в голову светлая мысль сделать наши пушки нестандартного размера? Теперь нам приходится изготавливать особые ядра каждый раз, когда кому-нибудь приспичит выстрелить из этой поганой штуковины! $B$BСлушай, я был бы тебе очень благодарен, если бы ты $gпоходил:походила: вокруг и $gсобрал:собрала: уже использованные снаряды. Судя по тому, как стреляют наши пушки, земли к югу и востоку отсюда должны быть просто усеяны боеприпасами. $B$B<Канонир разводит ладони, показывая, какого размера должны быть ядра.>$B$BЕй-богу, проще собрать их, чем отливать новые!', 'Канонир Эли поручил вам собрать 10 пушечных ядер и отнести их в Крепость Западной Стражи.', 'Слава тебе, $N, вечная слава!$B$BСложи их прямо там, где стоишь. Я поручу нашим ребятам загрузить их в пушки, и скоро нам можно будет не волноваться о количестве ядер – хватит всему Скорну!', 'Этак у нас скоро совсем не останется ядер, $C. А враги наши не спят, особенно в Скорне!$B$BНу теперь-то нам есть, чем стрелять, правда?', NULL, NULL, 'Пушечное ядро Западной Стражи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11191, 'Этот старый маяк', 'Старый маяк к востоку отсюда некоторое время не работал, но Бабс Шипокрутка вбила себе в голову, что надо туда залезть и снова его зажечь.$B$BНе знаю, как у нее это выйдет, но она говорит, что от этого судам будет легче входить в гавань и доставлять товары с борта на склады, поэтому я не против. Дежурить в доках – работенка непыльная, особенно по сравнению с передовой, не так ли?', 'Поговорите с Бабс Шипокруткой на маяке на острове к востоку от Терамора.', 'Хорошо. Мне понадобится твоя помощь. Первым делом необходимо снова зажечь фонарь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11192, 'Жир крепкозуба', 'Старый журнал, найденный на маяке, указывает, что фонарь заправляли жиром крепкозубов, обитающих вдоль здешнего побережья.$B$B<Бабс морщит нос от одного упоминания о такой устаревшей технологии.>$B$BНу, решение практичное, хотя и неизящное. В журнале говорится, что лучше всего брать жир самых молодых черных крепкозубов, а они обитают прямо в доках Терамора.$B$BЕсли ты не против, может, добудешь топливо для маяка?', 'Принесите 4 контейнера жира крепкозуба Бабс Шипокрутке на маяк близ Терамора.', 'Ну, хотя у меня и есть сомнения на этот счет, но сейчас это лучшее решение. Как только мы зажжем маяк, у нас наверняка найдется время подыскать другое топливо для фонаря.', 'Тебе удалось добыть жир крепкозуба?', NULL, NULL, 'Жир крепкозуба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11193, 'Подлые обитатели глубин', 'Этот старый маяк – просто сокровищница! Чего здесь только ни найдешь! Вот, например, эта книга. Лежала в одном из старых сундуков.$B$B<Бабс берет книгу и читает название.>$B$B\"Подлые обитатели глубин\"!$B$BЯ, наверное, просто умру от восторга, если увижу воочию хотя бы одного. Да и книжица, думается, забавная. Но у меня сейчас просто нет времени читать.$B$BОднако я знаю, кого она может порадовать... Торговца рыбой из доков, Ленни Полечуда по прозвищу \"Весельчак.\" Он коллекционирует старые книги.', 'Отнесите книгу \"Подлые обитатели глубин\" в доки Терамора и отдайте \"Весельчаку\" Ленни Полечуду.', 'Какая Бабс заботливая... помнит, что я собираю книги. Да и книга отличная. Ты сам-то ее пролистал? Там, кстати, немало правдивых историй. Да, моряки любят приврать, но не все их рассказы – выдумки.', 'Что сегодня берем? Рекомендую морскую щуку.', NULL, NULL, 'Подлые обитатели глубин (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11194, 'Так это правда?', 'О, да я уверен, что вы с Бабс животики себе надорвали, читая эти чужеземные описания да разглядывая картинки в книге. А вы не подумали о том, что в легендах есть доля истины?$B$BТы удивишься, но моряки на полном серьезе говорят о Тетуре, морском существе, которое, как написано в книге, живет прямо здесь. Ну, а если ты хочешь точно знать, то всегда можно спросить старину Ната Пэгла.$B$BОн живет в маленьком рыбацком лагере на островке в заливе Яростных волн, это если плыть на юго-запад через Пылевую бухту.', 'Поговорите с Натом Пэглом в лагере Ната, который находится в Пылевых топях.', 'Так ты хочешь послушать о морских монстрах? Хм... Ну что ж, хорошо, но для этого потребуется море выпивки, а тебе потом будет немного стыдно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11195, 'Игра в куклы', 'Я, наверное, сошел с ума, $N, вот в чем штука-то. Не помню, когда кто-то последний раз кто-то помогал Зунгаму за просто так.$B$BЯ стянул это у одного из дикарей, которые меня тут приковывали. На вид, штуковина неказистая, но тот, кто согласиться ее принять, будет мне хорошим другом!$B$BУж если мне свезет выбраться отсюда живым и непотресканным, я, пожалуй, стаскал бы эту штуку в Шаттрат и показал бы ему.', 'Отнесите потрепанную куклу вуду Жулю в Шаттрат.', 'Ты где это надыбал?$B$BНет, не говори мне, не хочу знать... Эта штука принадлежит повелителю Проклятий. Теперь все ясно. Мощная штука. Того, у кого есть такая фиговина, неважно, как бы нищ он при этом не был, - уважают. Глазам своим не верю! $B$B*Пока Грифтах держит куклу в воздухе, небольшой ржавый амулет срывается с его шеи. Тролль пытается отбросить его, но потом поднимает на тебя горящие глаза.*$B$BСейчас у меня монет нету, но я бы не отказался, заполучить эту штуку.', 'Здорово, $N! Слыхал я, ты прибился к команде Бадда. Дело хорошее, жалеть не придется, обещаю.$B$BЧто это у тебя?', NULL, NULL, 'Потрепанная кукла вуду (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11196, 'TEMP X', 'Слушай $gприятель:подруга: есть еще кое-что. Что ты можешь сделать для старины Пригмона.$B$BЗунгам, мой совершенно никчемный кузен был засажен за решетку в Зул\'Амане. Он там все еже жив, я получил от него весточку, только прошлой ночью.$B$BНе должен я был ему позволять втягивать меня в эту заваруху, но он должен мне нехилую сумму денег.$B$BВытащи его, каким угодно способом, и не бойся помять, пока тащишь его ко мне.', 'Найдите Зунгама и помогите ему выбраться из Зул\'Амана.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11198, 'Сразить Тетура!', 'Чудовище, не чудовище – мы не можем рисковать безопасностью морских перевозок. Я приказал лучшим стрелкам приготовиться к бою с Тетуром. Артиллеристы усилили оборону доков тремя мортирами.$B$BЯ готов отдать приказ зажечь маяк. Если Тетур пойдет в атаку, твоя задача стрелять из мортир и прикончить тварь, прежде чем она уничтожит всех наших стрелков. При этом я не советовал бы долго стоять на одном месте. Стрельба из мортир обязательно привлечет его внимание.', 'Майор Миллз из доков Терамора хочет, чтобы вы покончили с Тетуром.', 'Отличная работа, $N! Признаюсь, когда я впервые увидел эту тварь, я засомневался, что мы сумеем защитить доки, но ты блестяще скоординировал действия защитников!', NULL, NULL, NULL, 'Защитить доки Терамора от Тетура', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11199, 'Доклад разведчика Ноулса', 'Теперь, $N, когда мы разобрались с этими проклятыми прототварями, я хочу поручить тебе другое задание. $B$BОдин из моих разведчиков доложил о некоей подозрительной деятельности Отрекшихся на юге. Похоже, что они обосновались в врайкульской деревне Халгринд и строят некие зловещие планы.$B$BЯ надеюсь, что ты лично займешься расследованием этого дела. Поговори с разведчиком Ноулсом, выясни, что ему удалось узнать, и начинай действовать.$B$BПоследний раз он докладывал свое местоположение у Тлеющей башни, к западу от Халгринда.', 'Капитан Адамс попросил вас разыскать разведчика Ноулса у Тлеющей башни.', 'Наконец-то, помощь прибыла!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11200, 'Не просто совпадение', 'Мы выяснили на пепелище гостиницы все, что могли. Боюсь представить, куда нас заведет это расследование, но мы должны узнать правду.$B$BСледы копыт и щит с клеймом Мозарна дают повод полагать, что в это дело может быть замешано племя Зловещего Тотема. Они недавно построили на болотах, к северо-востоку отсюда, поселение, деревню Черного Копыта. Отправляйся туда и поищи еще какое-нибудь оружие работы Мозарна.', 'Крог из Деревни Гиблотопь хочет, чтобы вы принесли ему 7 предметов оружия Черного Копыта.', '<Крог разглядывает оружие, которое вы принесли из деревни Черного Копыта.>$B$BЭто, несомненно, работа Мозарна. Если мы учиним ему допрос, это привлечет слишком много внимания, но вот с племенем Зловещего Тотема мы можем вести себя посвободнее.', 'Что тебе удалось найти в деревне Черного Копыта?', NULL, NULL, 'Оружие Черного Копыта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11201, 'Замысел племени Зловещего Тотема', 'Теперь, когда дела племени Зловещего Тотема в Тысяче Игл стали известны всем, многие таурены начали косо на них поглядывать. Мы знаем, что вожди племени замешаны в убийстве и похищениях ради своих целей, и я опасаюсь, что следующей их мишенью станем именно мы.$B$BДеревня Черного Копыта, что на северо-востоке рядом с Синей топью, новое крупное поселение племени Зловещего Тотема. Их старейшины получают приказы из Громового Утеса. Сумеешь перехватить приказы и выяснить, что они задумывают?', 'Принесите боевые планы племени Зловещего Тотема Крогу в деревню Гиблотопь.', '<Крог читает боевые планы.>$B$BВ том, что Зловещий Тотем двинется на людей, сомнений нет. Но что они замышляют против нас? Действия этого племени давно вызывают беспокойство в рядах Орды, но вождю до сих пор удавалось рассеивать его.', 'Удалось найти какие-нибудь следы приказов?', NULL, NULL, 'Боевой план племени Зловещего Тотема', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11202, 'Задание: вечный огонь', 'Насколько мне известно, Отрекшиеся задумали нечто недоброе, и эти контейнеры с чумой имеют прямое отношение к их зловещим планам. $B$BОсмелюсь предположить, $N, что нам следует уничтожить эти ящики прежде, чем Отрекшиеся смогут ими воспользоваться. Я взял на себя смелость принести несколько факелов из Пылающего Гнездовья. Эти штуки горят уже несколько дней!$B$BВот, возьми – у тебя лучше получится поджечь эти контейнеры.', 'Разведчик Ноулс посоветовал вам воспользоваться неугасимыми факелами, чтобы уничтожить четыре контейнера с чумой, окружающих Халгринд.', 'Отлично!$B$BНо что нам делать с этими штуками, которые ты нашел в контейнерах? Неужели Отрекшиеся действительно распространяют чуму среди врайкулов?', NULL, NULL, NULL, 'Уничтожен юго-западный контейнер с чумой', 'Уничтожен северо-западный контейнер с чумой', 'Уничтожен северо-восточный контейнер с чумой', 'Уничтожен юго-восточный контейнер с чумой');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11203, 'Найти Табету', 'Оружие, которое ты $gзахватил:захватила: в деревне Черного Копыта, никогда не видело других сражений, кроме тренировочных боев. А это говорит о том, что Зловещих Тотемов, разоривших \"Последний привал\", еще много.$B$BНа юге, в самом сердце Трясины, живет ведьма Табета. Хоть она и человек, но ведет себя с нами по чести и даже воспитала некоторых наших магов.$B$BПопроси у нее помощи в поисках виновных из племени Зловещего Тотема, которые сожгли таверну. Альянс должен знать, что мы не замешаны в этом преступлении.', 'Поговорите с Табетой в ее доме на Трясине.', '<Табета улыбается.>$B$BЗначит, Крог хочет знать, где сейчас племя Зловещего Тотема? Что ж, магия для этого не понадобится.$B$BПохоже, это наш общий враг. Воины племени Зловещего Тотема построили неподалеку отсюда форпост и стали постоянной угрозой для меня и моих учеников.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11204, 'Возвращение к Крогу', 'Надеюсь, хоть чем-то тебе помог. Жаль, больше ничего не могу рассказать. Я со своими учениками делаю столько оружия, что вспомнить одну какую-то вещь уже просто невозможно.$B$BМы поставляем вооружение не только славным защитникам земель тауренов. Моими услугами пользуется и племя Зловещего Тотема. Опытным воинам достаточно одного взгляда, чтобы оценить качество моей работы.', 'Поговорите с Крогом в деревне Гиблотопь.', 'Он сказал, что племя Зловещего Тотема – его основные покупатели? Мозарн помог нам гораздо больше, чем ему кажется. Думаю, благодаря ему у нас появились главные подозреваемые.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11205, 'Уничтожение заставы Дикого Рога', 'Незачем гадать, чтобы увидеть угрозу, которая исходит от моих \"соседей\". И если это та самая банда, что сожгла \"Последний привал\", как ты говоришь, то нужно действовать немедля.$B$BБери вот этот факел и предай их лагерь огню! Ты найдешь заставу Дикого Рога к северу от моей усадьбы. Пропустить ее совершенно невозможно, эти варвары уже успели наставить вокруг свои драгоценные тотемы.', 'Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.', 'Надеюсь, племя Зловещего Тотема без труда поймет, что им хотели сказать.$B$BА что касается тебя, то твой осведомитель в деревне Гиблотопь захочет узнать, каковы твои успехи. Я понимаю, что разрушение таверны \"Последний привал\" может вызвать напряжение между Ордой и Альянсом. Если я встречу следователей из Терамора, то с радостью сообщу, что племя Зловещего Тотема действовало по собственной инициативе.', 'Ну что, хорошо разгорелось?', NULL, NULL, 'Северный шатер подожжен', 'Северо-восточный шатер подожжен', 'Восточный шатер подожжен', 'Факел Табеты (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11206, 'Акт правосудия', 'Сомневаюсь, чтобы племя Зловещего Тотемп оставило свои планы выжить людей с болот. Но по крайней мере, мы разобрались с ответственными за поджог \"Последнего привала\".$B$BУверен, что следователю, который тебя послал, и так это ясно, но Орда больше не будет давать спуску Зловещему Тотему. Когда-нибудь Орде очень печально аукнутся их действия.$B$BНи леди Джайна, ни вождь Тралл не хотят очередной войны, но готовы ли они сделать все, чтобы не допустить ее?', 'Вернитесь к Крогу в деревню Гиблотопь.', '<Крог выслушивает ваше донесение.>$B$BОчень впечатляет, Серокопыт. Мне казалось, что этих преступников из племени Зловещего Тотема будет труднее найти. $B$BСлово Табеты было услышано, но не мне карать это племя. Конечно, я доложу об этом вождю. Никому об этом не рассказывай, пока Тралл не разберется со Зловещим Тотемом. Ты славно потрудился, распутав тайну \"Сомнительного отдыха\" и сняв с нас подозрения Терамора.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11207, 'Защитить груз!', 'Этот дирижабль вез в Шестермуть припасов на полгода! Они там, конечно, что-то на что-то выменивают, но на обмене долго не протянешь.$B$BМеня отправили сюда собрать все оставшееся от груза, да вот только обломки разбросало по всему болоту. Большая часть, конечно, аварии не пережила, но, может, поищем то, что еще на что-то годится?', 'Мокси Сталегриль попросила вас собрать 8 контейнеров груза с дирижабля и принести ей на место крушения Бизиля.', 'Ого! Ты нашел куда больше, чем я ожидала! Не знаю, сколько ждал от нас Драззит, но, думаю, этому он сильно обрадуется.', '<Мокси сходит с ума от волнения.>$B$BНу, как там груз? Ты хоть что-нибудь нашел?', NULL, NULL, 'Груз с дирижабля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11208, 'Поставка для Драззита', 'Драззит ожидает вскорости получить от меня вести, но место мне кажется довольно опасным, чтобы ехать туда самой. Если у тебя найдется время, не свезешь ли ты часть спасенного груза ему в Шестермуть?$B$BЭто небольшое поселение к юго-западу отсюда, за руинами Деревни Каменного Молота, если тебе еще не доводилось там бывать. Также туда можно дойти по дороге от усадьбы Табеты. Когда доберешься до Шестермути, ищи парня по имени Драззит Кранотек.', 'Доставьте груз с дирижабля Драззиту Кранотеку в Шестермуть.', '<Драззит принимает от вас груз.>$B$BЯ так проголодался, что целого дракона бы съел! Наконец-то Мокси доставила часть груза сюда. А то я уже было начал играть в кости с огром на то, что ему удавалось добыть на охоте!', 'Да?', NULL, NULL, 'Груз с дирижабля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11209, 'Сделка Ната', 'Значит, ты $gнашел:нашла: экземпляр \"Подлых обитателей глубин\"? Что же, скажу по собственному опыту - все, что там написано, - правда. Кое-кого я собственными глазами видел.$B$BНо ты спрашиваешь про Тетура. Давай заключим сделку. Вот что мне от тебя надо: я тут разрабатываю новую линию наживок, но вот эту я еще не испытывал.$B$BВозьми эту пасту - да, запашок у нее не из приятных - намажься ею и плыви к тому разбитому кораблю на юго-запад. Выживешь - расскажешь, как все прошло!', 'Нат Пэгл из лагеря Ната хочет, чтобы вы испытали его новую наживку для рыбы.', 'Что ж, неплохо, неплохо, но на твоем месте я бы срочно отправился в душ.$B$BА теперь о том морском чудище...$B$BПропусти пока кружку-другую.', 'Уговор такой – без улова не возвращаться!', NULL, NULL, 'Рыбная паста испытана', 'Особая рыбная паста Пэгла (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11210, 'Он настоящий!', 'Да, Тетур вполне настоящий, живет он в тераморских водах.$B$BПриходит на яркий огонь. Именно поэтому маяк там не работает...$B$BСтоит его зажечь, как чудище вернется. Но в здравом уме никто на это не пойдет.$B$BСоответственно, это работка для тебя. Приятно было с тобой выпить, но не обижайся на Ната, если Тетур на самом деле примет тебя за наживку. Если намереваешься с ним повидаться, поговори сначала с майором Миллзом из доков Терамора.', 'Поговорите с майором Миллзом в доках Терамора.', '<Вы рассказываете о вашем разговоре с Натом, тщательно обходя тему испытания наживки.>$B$BЧто ж, видимо, работка как раз для нас. Я все подготовлю.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11211, 'Помощь деревне Шестермуть', 'Когда та гоблинша... как бишь ее там... Токси, Рокси... Мокси, вот! Короче, когда она проезжала здесь к месту крушения дирижабля, то говорила, что в деревне Шестермуть какие-то проблемы.$B$BЭтот разбившийся дирижабль вез им свежие припасы. Если поедешь отсюда по южной дороге мимо руин Деревни Каменного Молота, в конце концов упрешься в Шестермуть.$B$BПочему бы тебе там не встретиться с Драззитом Кранотеком и не спросить, какая помощь нужна?', 'Поговорите с Драззитом Кранотеком в Шестермути.', 'Хорошо, что Табета прислала тебя. Неплохо было бы, если б она передала каких-то припасов, пока сюда не доставят груз с разбившегося дирижабля, но, как мне известно, сейчас ей просто нечем поделиться. Если у тебя есть вкус к приключениям, то я назначил награду за одного особенно противного ящера.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11212, 'Ферма Табеты', 'Среди болот живет старая женщина по имени Табета. Мы немного знаем о ней – пожалуй, только то, что она куда старше, чем кажется. Она время от времени помогает нам, пока что ей удается поддерживать здесь мир между нашими силами и Ордой.$B$BОбычно она держала с нами постоянную связь, но недавно эта связь прервалась.$B$BЕсли у тебя выдастся минутка, может, проведаешь ее? Иди по дороге мимо Северной башни, там она сворачивает на юг к Трясине. Усадьбу Табеты видно с дороги.', 'Поговорите с Табетой в ее доме на Трясине.', 'Хорошо, что Терамор прислал сюда хоть кого-то. Опасения вашего приятеля-стража небезосновательны. У нас появились новые соседи, и добрыми их никак не назовешь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11213, 'Навестить Табету', 'Среди болот в маленькой усадьбе живет человеческая женщина по имени Табета. Обычно я дел с людьми не веду, но она не раз нам помогала.$B$BОднако в последнее время я не могу с ней связаться, так что ищу кого-нибудь, кто пошел бы в ее усадьбу да проверил, все ли там ладно.$B$BЕсли пойдешь по дороге на юг из деревни, а затем свернешь на болота, то найдешь ее усадьбу в самом сердце Трясины.', 'Поговорите с Табетой в ее усадьбе на Трясине.', 'Назир очень кстати решил послать кого-нибудь сюда. У нас появились новые соседи, и с тех пор жить стало просто невыносимо.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11214, 'Миссия в Шестермуть', 'Картель Хитрой Шестеренки недавно построил новый форпост в южной части Пылевых топей. Называется он вроде Шестермуть и расположен на главной дороге к югу от домика Табеты и руин деревни Каменного Молота.$B$BЭто прекрасная возможность завести новые торговые отношения, и леди Джайна хочет, чтобы я отправил туда представителя для налаживания контактов. Возьмешься?', 'Поговорите с Драззитом Кранотеком в Шестермути.', 'Значит, Терамор хочет наладить с нами деловые отношения? Ну, от такого предложения не отказываются. Сейчас у нас как раз жутко не хватает провианта, так что мы рады любым бизнес-контактам!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11215, 'Помощь Шестермути', 'На новом форпосте картеля Хитрой Шестеренки в южной части Трясин дела не так уж и хороши. Дирижабль с припасами для Шестермути разбился, и они остались без жизненно необходимых инструментов, провизии и медикаментов.$B$BИди по дороге на юг, прямо в глубь болот. Ты пройдешь усадьбу Табеты и руины Деревни Каменного Молота, прежде чем дорога приведет тебя в Шестермуть. Помоги городскому управлению, чем сможешь.', 'Поговорите с Драззитом Кранотеком в Шестермути.', 'Я не откажусь от любой помощи! Мы тут как раз обживаемся, поэтому используем все доступные средства на полную катушку, пока дирижабль не доставил груз.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11216, 'Верховный маг Альтур', 'Мой наставник прислал меня сюда искать помощи, но увы – меня не выпускают из Нижнего Города, а от тех, кто часто посещает это заведение,толку, мягко говоря, мало.$B$BНо ты другое дело, ты больше $gпохож:похожа: на тех, кто не боится приключений. Если ты не против помочь нам, поговори с верховным магом Альтурусом близ старой обители Медива, Каражана. $B$BА я пока постараюсь получить доступ к другим частям города. Говорят, тут сейчас находится один из наших старых помощников.', 'Поговорите с верховным магом Альтуром близ Каражана на перевале Мертвого Ветра.', 'Благодарю за то, что уделили нам толику времени. Нам предстоит важное дело.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11217, 'Тяни змею за хвост!', 'Поскольку дирижабль разбился, поставка задерживается, и мы остались без медикаментов и бинтов.$B$BКонечно, выручают подручные средства, но среди всех этих насекомых, отбиваясь от врагов и неся потери, мы вряд ли долго продержимся! Я нашел тут одну травку, которая, сдается, помогает при лечении любых ран и притупляет боль, но и ее мало.$B$BОна называется змейкин хвост, в Земле Драконов и Драконьих топях к востоку от города ее целые заросли. Сами растения представляют собой свившиеся кольцами стебли. Когда смотришь на них, кажется, будто они пульсируют.', 'Гиззикс Грязебульк из Шестермути просит принести ему 8 стеблей змейкиного хвоста.', 'Спасибо тебе! Теперь наши парни продержатся в поле, пока Мокси не доставит груз, оставшийся после крушения дирижабля.', 'Ты нашел, где растет змейкин хвост?', NULL, NULL, 'Змейкин хвост', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11218, 'Осторожно! Взрывчатка!', '$N, капитан поручил мне задание, с которым мне не справиться без твоей помощи.$B$BМои товарищи из Лиги исследователей отправились на север, вести раскопки в Шепчущей теснине, и что-то в этом месте свело их с ума. Теперь они нападают на всех, кто осмеливается к ним приблизиться. $B$BА капитана заботит только руда для крепости! К счастью, я знаю, как решить эту проблему.$B$BОтправляйся туда, взорви месторождение и принеси сюда осколки руды вместе с драгоценными камнями. Эта раскопки недешево нам обходятся, знаешь ли.$B$BПравда, должен тебя предупредить – это очень странная руда!', 'Воспользуйтесь динамитом Стальной Чеки, чтобы собрать 6 кусков руды из Шепчущей теснины и 18 драгоценных камней из Шепчущей теснины. Затем принесите руду и камни саперу Стальной Чеке в Крепость Западной Стражи.', 'Говоришь, тебе было неприятно прикасаться к этой руде? Может быть, нам не стоит больше ее использовать.$B$B<Стальная Чека бросает быстрый взгляд на вашу добычу и быстро меняет тему разговора.>$B$BКакие симпатичные камешки! Интересно, сколько удастся за них выручить? Ну конечно, эти деньги пойдут на ремонт и новые инструменты...$B$BЗнаешь, с тобой довольно выгодно сотрудничать! Вот, возьми... это самое малое, что я могу для тебя сделать.', 'Кажется, мы никогда не закончим возводить эту крепость. Надеюсь, ты несешь нам припасы, необходимые для продолжения строительства.', NULL, NULL, 'Кусок руды из Шепчущей теснины', 'Самоцвет из Шепчущей теснины', 'Динамит Стальной Чеки с предохранителем', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11219, 'Гаси пожар!', 'Спасите детей Орды, $N! Всадник без головы, который некогда был человеком-паладином, а теперь стал безумным демоном, поджег нашу деревню! Вы должны потушить пожар!$B$BХватайте ведро и тушите огонь или передавайте ведра по цепочке! Потушите пожар и прогоните всадника без головы!', 'Попечительница сирот в маске просит вас помочь потушить пожар в деревне. Когда пожар потухнет, снова поговорите с попечительницей сирот в маске в городе.', 'Пожар потушен! Вы с пожарной бригадой победили! Ха!$B$BНападение Всадника без головы провалилось, но пока он и его голова не уничтожены, он будет возвращаться.$B$BА пока утешайтесь тем, что вы спасли наших детей. Для меня великая честь быть свидетельницей вашей отваги!', 'Вы нужны детишкам Орды! Не бросайте их!', NULL, NULL, 'Пожар потушен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11220, 'Всадник без головы', 'Пока голова Всадника не уничтожена, не будет конца его неистовству.$B$BОн покоится в Покинутом ските Монастыря Алого ордена в Тирисфальских лесах. Найди его святилище тыквы и скажи такие слова:$B$BВсадник, встань$BПришла пора$BУмереть в последний раз!$B$BТогда он восстанет. Уничтожь голову Всадника, и он не будет больше преследовать нас.', 'Найдите святилище тыквы Всадника без головы.', 'Откуда взялось это святилище, никому не ведомо, но кому оно посвящено – никаких сомнений нет...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11221, 'Донесения с полей', 'Мы пришли в Нордскол, чтобы одержать победу над Артасом. Альянс – это незначительная помеха нашим планам, которую мы вскоре устраним.$B$BМы уже уничтожили их флот на востоке, но выжившие моряки укрылись на Обнажившемся дне, к югу отсюда.$B$BМы рассчитывали легко разрушить их самодельные укрепления, но недооценили их волю к жизни. Найди моих полевых офицеров, темного следопыта Лиану и стража смерти Разаэля. Мне нужен их отчет о текущей ситуации.', 'Поговорите с темным следопытом Лианой и стражем смерти Разаэлем на поле боя в Кровоточащей долине к югу от Лагеря Возмездия, после чего вернитесь к Верховному палачу Ансельму.', 'Пушки заставили нас отступить? Я им покажу, как стрелять по нашим войскам!', NULL, NULL, NULL, 'Вы выслушали отчет Разаэля', 'Вы выслушали отчет Лианы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11222, 'Доказательство измены', 'Хотя мы получили ответы отнюдь не на все вопросы, необходимо, чтобы вы оповестили о результатах наших изысканий короля Вариана Ринна немедленно!$B$BОн должен знать, что Братство Справедливости в Штормграде обзавелось влиятельным покровителем и связано с его похищением! Сомневаюсь, что после этого он пощадит причастных к этому преступлению людей.$B$BЯ могу воспользоваться магией для ускорения вашей поездки в Штормград. Просто скажите мне, когда будете готовы, $N.', 'Поговорите с королем Варианом Ринном в Крепости Штормграда.', '*Верховный лорд Болвар выслушивает от вас сообщение Джайны.*$B$BТы уверен? Это очень серьезное обвинение...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11223, 'Возвращение к Джайне', 'Мы должны составить план, как уничтожить остатки Братства Справедливости. Пожалуйста, передай мою благодарность леди Джайне в Терамор. Она всегда была мне добрым другом и надежным союзником. $B$BСтупай в Квартал Магов в западной части города и поговори с верховным магом Малином у тамошней башни. Он поможет тебе поскорее вернуться в Терамор.', 'Поговорите в Тераморе с леди Джайной Праудмур.', 'Это замечательная новость, $N! Я беспокоилась, что верховный лорд станет сомневаться в достоверности нашей информации, но, вижу, зря волновалась.$B$BТы будешь щедро вознагражден за труды во благо Терамора и Альянса.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11224, 'Пришли мулов сюда', 'Я слышала о том, что случилось в Шепчущей теснине на севере. Туда спустились многие члены Лиги исследователей, и, говорят, сошли с ума от того, что они там обнаружили.$B$BЭто, впрочем, не меняет того факта, что они забрали с собой почти всех наших мулов и оборудование. Мулов мне особенно жалко!$B$BЕсли ты вдруг окажешься в тех краях и наткнешься на бедных животных, просто подойди к ним и пригрози рукой. Они испугаются и побегут домой.', 'Исследовательница Эбигейл просит вас пригрозить рукой (команда /рука) 10 брошенным груженым мулам, после чего вернуться к ней в Крепость Западной Стражи.', 'Не знаю даже, как отблагодарить тебя, $C. Теперь, когда мы вернули большую часть мулов и оборудования, можно попытаться продолжить работу.$B$BПрошу тебя, прими эту награду.', NULL, NULL, NULL, 'Отправлено домой брошенных груженых мулов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11225, 'Отшельник с Ведьминого холма', 'Болото как-то странно влияет на тамошних жителей. Многие трогаются умом.$B$BА те, кто селится в сторожке \"Болотный огонек\", просто съезжают с катушек, да еще как! Все как один. Последний хозяин, некто Ярл по прозвищу \"Болотный глаз\", уже проявляет все признаки безумия.$B$BЯ не до конца понимаю, что там происходит, и буду очень тебе благодарен, если ты сходишь и разберешься.$B$BПоместье находится на восточном краю болота. Иди на восток через Синюю топь, мимо Северной башни. Дом стоит на Ведьмином холме, где водятся призраки.', 'Поговорите с Ярлом \"Болотным глазом\" в сторожке \"Болотный огонек\".', 'Пришел шпионить за мной? Нет?$B$BТогда, может, откушаешь вкусненького? Вот и славно, а то я как раз собирался добыть еды и мне нужна помощь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11227, 'Пусть едят вволю!', 'Верховный палач требует, чтобы мои собаки отправились вынюхивать следы шпионов противника, но я-то знаю, что чумные псы и с места не сдвинутся, пока их не накормят нормальной едой. $B$BЭти тупоголовые вояки не понимают, что мои звери не будут есть всякие отбросы. Как можно требовать каких-то успехов от голодных собак?$B$BСлушай, у тебя не найдется свободной минутки? Пожалуйста, возьми одного из псов поохотиться на ворон к западу отсюда. Их мясо не очень-то вкусное, но мои песики его обожают!', 'Понтий, псарь из Лагеря Возмездия, просит вас забрать голодного чумного пса из клетки и накормить его мясом ворон фьорда, которые кружат к югу от Лагеря Возмездия.', 'Ты поймал самую большую ворону, малыш? Хороший песик!$B$BАх, помнится, когда-то я разводил чистокровных овчарок в Тирисфале... хорошие были времена!', NULL, NULL, NULL, 'Чумной пес накормлен', 'Клетка чумного пса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11228, 'Во власти ледяного кошмара...', 'Фордрагон совсем с ума сошел, если он и впрямь думает, что этот отряд зеленоротых юнцов, которых он послал на защиту Валгарда, продержится хотя бы сутки.$B$B<Макалрой с удивлением рассматривает ваше обмундирование.>$B$BА вот ты, пожалуй, справишься гораздо лучше.$B$BЯ не могу даже описать, насколько велика ценность этого порта. А после того, как на нас напали эти летающие твари, ситуация резко ухудшилась.$B$BНайди вице-адмирала Келлера на северо-западе и сообщи ему, что ты уже $gвырос:выросла: из коротких штанишек.', 'Поговорите с вице-адмиралом Келлером в Валгардском порту.', 'Этот дворф знает, что говорит. Мы действительно не можем допустить, чтобы порт был захвачен. Это одна из двух безопасных гаваней Альянса в этом ледяном кошмаре – вторая находится на сотню миль к западу, на побережье Борейской тундры.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11229, 'Флагман \"Ветрокрылая\"', 'Три наших фрегата – \"Ветрокрылая\", \"Месть королевы\" и \"Забвение\" стоят на якоре к востоку от Обнажившегося дна. Передай капитану флота Харкеру, что ему приказано уничтожить пушки Альянса.$B$BПоговори с нашей дрессировщицей нетопырей Камиллой и попроси ее довезти тебя до места дислокации флота. Поторопись, $N, ибо каждую минуту, которую мы тратим на стычки с Альянсом, мы могли бы посвятить войне с Артасом.', 'Поговорите с дрессировщицей нетопырей Камиллой в Лагере Возмездия и летите к флагману \"Ветрокрылая\". Доложите о своем прибытии капитану Харкеру.', 'Надеюсь, ты готов к сражению, $N. Флотилии Королевы нужны отважные бойцы!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11230, 'В засаде!', 'Мы думали, что это будет легкой прогулкой. Их войска плохо экипированы, солдаты изранены и страдают от голода. Однако каким-то образом мы угодили в их ловушку. $B$BМы хотели использовать южные рифы как укрытие, но на подходе были взяты на абордаж этими вонючими псами Альянса.$B$BМне очень жаль, но если ты рассчитываешь на нашу огневую поддержку, тебе придется сначала вернуть наши корабли.', 'Капитан Харкер на борту \"Ветрокрылой\" просит вас убить 15 стражей бухты Северного флота.', 'Молодец, поставил этих поганцев на место. С оставшимися разберутся мои люди.', 'Ну, и чего ты ждешь? Убей этих мерзавцев!', NULL, NULL, 'Страж бухты Северного флота убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11231, 'О ключах и клетках', 'Возможно, капитану это безразлично, но мы-то знаем, что врайкулы совершают какие-то омерзительные ритуалы \"пробуждения\" к северу от Гьялерброна.$B$BВ ходе этих обрядов проливается кровь невинных жертв!$B$B$C, ты $gдолжен:должна: остановить это! Неважно, кого они держат в своих клетках для жертвоприношений – их надо освободить. Могу поспорить, врайкулы носят ключи при себе.$B$BВидит Свет, нам не нужны эти мерзкие врайкулы поблизости, и еще меньше нам хочется разбираться с тем злом, которое они пытаются пробудить!', 'Отец Левариол попросил вас собрать достаточное количество ключей от гьялербронских клеток, чтобы освободить 10 гьялербронских узников. Когда вы выполните задание, вернитесь к нему в Крепость Западной Стражи.', 'Слава тебе, дитя мое, ибо ты несешь Свет даже в самые темные уголки этого мира!$B$BПожалуйста, прими это скромное вознаграждение твоим благим делам. Я лично прослежу за судьбой освобожденных тобой пленников, и пусть будет даровано спасение тем, кто служит Свету и Альянсу.', NULL, NULL, NULL, 'Освобождено гьялербронских узников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11232, 'Дайте нам знак', 'Скорее всего, мы сможем пробиться назад, к пушкам. К несчастью, нам лучше не привлекать к себе внимания, поэтому тебе придется пометить цели с земли.$B$BВозьми с собой эти дымовые сигнальные ракеты и обозначь местонахождение пушек вдоль северной стены на контролируемой Альянсом территории к западу отсюда. Как только путь для наших наземных отрядов будет расчищен, дай знак Лиане. Об остальном мы позаботимся сами.', 'С помощью дымовых сигнальных ракет обозначьте местонахождение пушек Альянса вдоль северной стены Обнажившегося дна. Доложите о выполнении задания темному следопыту Лиане из Кровоточащей долины.', 'Превосходно. Я дам знать нашим наземным отрядам, что они могут выступать.', NULL, NULL, NULL, 'Восточная пушка помечена', 'Западная пушка помечена', 'Дымовая сигнальная ракета канонира', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11233, 'Решающий удар', 'Ты отлично $gпроявил:проявила: себя на поле боя, $N. Возможно, именно ты $gизменил:изменила: ход битвы в нашу пользу.$B$BТеперь я хочу поручить тебе очень ответственную миссию. Не знаю, сколько еще времени понадобится противнику, чтобы прийти в себя, но времени для действий осталось не так уж много.$B$BВоспользуйся замешательством неприятеля, вызванным нашим нападением, проберись за линию фронта и уничтожь их предводителей. Вот их имена и звания: капитан Ольстер, лейтенант Селейна и сержант Лоррик. Удачи, $C.', 'Темный следопыт Лиана из Лагеря Возмездия послала вас убить капитана Ольстера, сержанта Лоррика и лейтенанта Селейну, обосновавшихся на Обнажившемся дне.', 'Скоро наши войска одержат великую победу. Ансельм будет рад услышать эти вести.', NULL, NULL, NULL, 'Капитан Ольстер убито', 'Лейтенант Селейна убито', 'Сержант Лоррик убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11234, 'Доложите Ансельму', 'Давай пошлем весточку старине Ансельму. Мы долго шли к этой победе – но лучше уж поздно, чем никогда. Скажи ему, что через несколько часов все будет кончено.$B$BСлава королеве Банши!', 'Вернитесь к верховному палачу Ансельму в Лагерь Возмездия в Ревущем фьорде.', 'Наконец-то. Войска Альянса давно уже не давали нам спать спокойно.$B$BОднако, сейчас не время праздновать. Взгляни на запад; похоже, к нам идут гости.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11235, 'Очистить Гьялерброн', 'Увы, теперь перед нами стоит другая проблема. Выжившие разведчики сообщили, что врайкулы замышляют нечто недоброе в своей главной крепости к северу отсюда. $B$BОни называют это место Гьялерброн, хотя вообще-то первая буква этого слова произносится как \"Ш\". Странные существа. $B$BНо все это не важно; важно то, что тебе надо пробраться туда и убить как можно больше этих мерзких существ, чтобы сорвать их зловещие планы. $B$BЯ знаю, что могу на тебя рассчитывать, $N.', 'Капитан Адамс поручил вам убить 15 гьялербронских воинов, 8 гьялербронских руночаров и 8 гьялербронских сноходцев. После чего вам надлежит вернуться к нему в Крепость Западной Стражи.', 'Ты молодец, $N. Хорошо, что мы от них избавились.$B$BНо это место все еще меня беспокоит, и я боюсь, что наша война еще не окончена.', NULL, NULL, NULL, 'Гьялербронский воин убито', 'Гьялербронский руночар убито', 'Гьялербронский хранитель снов убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11236, 'Некро-владыка Мезхен', 'Армия Плети уже пришла в Гьялерброн, и в их рядах есть несколько некромантов! Должно быть, они пытаются провести врайкулов в крепость Артаса.$B$BПредводитель этих некролордов должен умереть!$B$B$N, на твои плечи ложится огромная ответственность – ты $gдолжен:должна: сорвать планы некро-владыки Мезхена и уничтожить его самого.$B$BЯ не допущу, чтобы эти врайкулы заключили союз с Плетью! $B$BМезхена можно найти на платформе в дальнем правом квартале Гьялерброна.', 'Убейте некро-владыку Мезхена. Затем вернитесь к капитану Адамсу в Крепость Западной Стражи.', '<Капитан облегченно вздыхает.>$B$BНу, теперь мы можем слегка расслабиться.$B$B$N, ты снова подтвердил свою значимость для Крепости Западной Стражи и всего Альянса. Пожалуйста, выбери себе что-нибудь из нашей сокровищницы. Это самое меньшее, что мы можем для тебя сделать!', NULL, NULL, NULL, 'Некро-владыка Мезхен убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11237, 'Гьялербронский план нападения', 'Вы держите в руках планы нападения на Крепость Западной Стражи. Похоже, что врайкулы собираются использовать для атаки ледяного змея, Ледиона, который кружит у вас над головой.$B$BНаверняка, маг-лейтенант Малистер сможет что-нибудь предпринять, если вы доставите эти планы к нему в южную крепость.', 'Отнесите гьялербронский план нападения магу-лейтенанту Малистеру в Крепость Западной Стражи.', '$N, мы не можем допустить, чтобы эти планы осуществились!', 'Что это?! Планы нападения на крепость?$B$BОНИ ПОСЫЛАЮТ ЛЕДЯНОГО ЗМЕЯ?!', NULL, NULL, 'Гьялербронский план нападения (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11238, 'Ледяной змей и его повелитель', 'Ты мудро $gпоступил:поступила:, доставив ко мне этот документ. Теперь тебе следует взять несколько помощников и отправиться на север, в Гьялерброн. Убей этого змея и его хозяина, Зловещего призывателя змей!$B$BНадеюсь, они еще не выпустили это ледяное чудовище в небо.$B$BНо, даже если это уже произошло, и змей движется на нас, его можно отозвать обратно с помощью рога призывателя змей. Звук рога привлечет Ледиона, и он приземлится обратно, на платформу слева от Гьялерброна.$B$BПожалуйста, $N, когда все закончится, принеси мне этот рог. Нельзя допустить, чтобы он попал не в те руки.', 'Убейте Зловещего призывателя змей и воспользуйтесь его рогом, чтобы позвать обратно Ледиона. Убейте ледяного змея и принесите рог магу-лейтенанту Малистеру в Крепость Западной Стражи.', 'Ого, какой холодный!$B$BЗнаешь ли ты, что только что спас Крепость Западной Стражи от неминуемой гибели? Ах, если бы у нас в союзниках было больше таких неординарных личностей, как ты!$B$BПолагаю, ты заслуживаешь щедрой награды.', 'Ледяной змей и его хозяин мертвы?$B$BНо где же рог?', NULL, NULL, 'Зловещий призыватель змей убито', 'Ледион убито', 'Рог призывателя змей', 'Рекомендуемое количество игроков: 2');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11239, 'На службе Света', 'Твоя помощь бесценна для нас, $N. Увы, наша война далека от завершения, и омерзительные создания Плети беспокоят меня больше, чем когда-либо.$B$BСвет презирает этих существ, и мы тоже не должны терпеть их присутствие. Я понимаю, что прошу от тебя слишком многого, но ты $gдолжен:должна: вернуться на север, в Гьялерброн, и сокрушить логово этой нечестивой Плети. Не забудь проверить, не остались ли эти презренные твари в чертогах Пробуждения, что под Гьялерброном.$B$BОчищение – путь к спасению, дитя мое. Мы будем гордиться тобой!', 'Убейте 10 бессмертных дозорных, 4 кошмарных ужаса и 2 тлетворных существа по просьбе отца Левариола из Крепости Западной Стражи.', '<Священник тихо шепчет слова молитвы.>$B$BДитя мое, $N, ты был послан в ответ на мои молитвы. Гордо стой в лучах Света, ибо подвиг твой священен!$B$BКстати, в сокровищнице храма наверняка найдется что-то, что тебе пригодится.', NULL, NULL, NULL, 'Бессмертный дозорный убито', 'Кошмарный ужас убито', 'Тлетворное существо убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11240, 'Предводитель Спятивших', 'Знаешь, дружище, мне тоже все это не нравится, но, пока тебя не было, капитан пересмотрел свое мнение об этом месте.$B$BПохоже, он хочет убить моего бывшего начальника Лиги исследователей. Могу предположить, что за этим последует нападение на их лагерь.$B$BМожет быть, ты окажешь мне услугу? Отправляйся назад, в Шепчущую теснину, и убей Сквига Идолохотника. Насколько я помню, он прячется в пещере на северо-западе.', 'Убейте Сквига Идолохотника и сообщите об этом саперу Стальная Чека, который находится в Крепости Западной Стражи.', '<Сапер недовольно морщится, как будто не рассчитывал на успех вашей миссии.>$B$BКапитан будет рад слышать, что его задание выполнено.$B$BСпасибо тебе за помощь в Шепчущей теснине. Выбери себе что-нибудь из этого в награду.', NULL, NULL, NULL, 'Сквиг Идолохотник убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11241, 'Путь огня', 'Спасибо, что $gвытащил:вытащила: меня из этой передряги, $N. Не хотелось бы узнать, что за судьбу готовили мне эти мерзавцы из Альянса.$B$BДавай попробуем выбраться отсюда. Надеюсь, нам еще удастся с ними рассчитаться. Есть ли здесь наш лагерь поблизости?', 'Выведите аптекаря Хейнса из Обнажившегося дна после чего сообщите о произошедшем аптекарю Лисандеру из Лагеря Возмездия в Ревущем фьорде.', 'Аптекарь Хейнс жив? Говоришь, вы с ним сожгли припасы Альянса? Бедняга; наверное, ему досталось в плену.$B$B$N, Королевское фармацевтическое сообщество у тебя в долгу. Благодарим тебя от всего нашего черного, прогнившего сердца.', NULL, NULL, NULL, 'Спасти аптекаря Хейнса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11242, 'Наконец, свободен!', 'Гнев был моей темницей, $N, а ты $Gосвободил:освободила; меня. Хотя я считал себя правым, душа моя ныне кровоточит от всех тех ужасов и смертей, которые обрушил я на жителей Азерота.$B$BБлагодарю тебя, что ты $gпривел:привела: меня к Свету. Да не сверну я с этого пути!$B$BОтнеси этот потрепанный молитвенник попечительнице сирот, чтобы дети узнали, что больше я их не потревожу.', 'Возьмите книгу Томаса Томсона и отнесите ее переодетой попечительнице сирот в Златоземье, Каранос или на Лазурную заставу.', '', NULL, NULL, NULL, 'Книга Томаса Томсона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11243, 'Если Валгард падет...', 'Если Валгард падет, мы потеряем главный источник снабжения в Нордсколе. После этого нам останется только преклонить колени перед Королем-личом. Не знаю, как насчет тебя, а у меня в Элвинне осталась жена и трое детишек. И будь я проклят, если не буду сражаться за свою жизнь до последнего вздоха!$B$BСитуация дошла до критической точки, и мы должны использовать все имеющиеся у нас ресурсы. Отправляйся к воротам и помоги нашим солдатам защитить город от захватчиков!', 'Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас убить 12 захватчиков из клана Укротителей драконов или воргов из клана Укротителей драконов.', 'Ты оказал значительную помощь нашим защитникам и помог поднять моральный дух солдат. Надеюсь, теперь они справятся с оставшимися захватчиками. А для тебя у меня есть более важное задание...', NULL, NULL, NULL, 'Захватчик из клана Укротителей драконов убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11244, 'На помощь спасателям', 'Эти жуткие великаны появились буквально из воздуха через месяц после того, как мы прибыли сюда. Мы были плохо подготовлены к нападению и дорого поплатились за свою беспечность. Мы потеряли всю археологическую бригаду и нескольких жителей, которых похитили и утащили в руины. С тех пор мы находимся на осадном положении.$B$BХуже того, наших разведчиков, которых мы послали на помощь похищенным, поймали врайкулы, насадили на гарпуны и оставили умирать в лесу к северу от Валгарда. Пожалуйста, найди их и освободи!', 'Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 8 валгардских разведчиков, которых проткнули гарпунами и оставили умирать.', 'Какая дикость! Не могу поверить, что врайкулы так поступили с нашими разведчиками. Они хотели запугать нас, ослабить нашу решимость... заставить спасаться бегством.$B$BНо их замысел не удался.$B$BМы покажем этим мерзавцам, что будет с теми, кто осмелится развязать войну с Альянсом!', NULL, NULL, NULL, 'Освобождено валгардских разведчиков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11245, 'Смертельно опасные башни', '$N, мы не можем двигаться дальше, не уничтожив сторожевые башни.$B$BНо на вершине каждой вышки несет стражу множество волшебников. Стоит тебе только приблизиться к башне – и мы обречены!$B$BКонечно, мы можем призвать бомбардиров из Крепости Западной Стражи, но они должны видеть цель, которую им предстоит разбомбить. Для этого тебе придется подкрасться к башням и забросить на вершину каждой ды$Nю сигнальную ракету.$B$BГлавное – не подходи слишком близко.', 'Сержант из крепости Западной Стражи сообщил вам, что сторожевые башни Скорна разумнее всего разрушить с воздуха.', 'Какой ты меткий, $N! Надо будет проставиться бомбардирам, когда мы вернемся обратно в крепость.', NULL, NULL, NULL, 'Cеверо-западная башня помечена', 'Восточная башня помечена', 'Юго-западная башня помечена', 'Юго-восточная башня помечена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11246, 'Тяжело, но необходимо', 'Нам докладывали, что врайкулы могут восставать из мертвых. Нет, они не похожи на оживших мертвецов Плети, но их понятие жизни после смерти несет нам не меньшие беды.$B$BМы не можем так рисковать!$B$BВот, возьмите мой мачете. Пока мы будем продвигаться вперед, кромсайте им все трупы врайкулов, которые встретятся вам по пути. Я бы и сам это сделал, но у меня слабые нервы.$B$B<Сержант глупо ухмыляется.>$B$BЯ потратил все утро на заточку клинка, так что теперь он разрубит даже самые толстые кости.', 'Сержант из крепости Западной Стражи попросил вас разрубить на куски 20 снежескорнских врайкулов в Скорне.', 'Ух ты, сэр,а вы знаете, как обращаться с этой штуковиной.$B$B<Сержант бросает на вас настороженный взгляд.>$B$BЗнаете что, давайте-ка я заберу у вас мачете. А то вдруг вы поскользнетесь, споткнетесь, да зарубите меня ненароком!', NULL, NULL, NULL, 'Разрублено тел снежескорнских врайкулов', 'Мачете сержанта', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11247, 'Гори, Скорн, гори!', 'Капитан Адамс приказал мне разрушить множество зданий в Скорне.$B$BНо теперь я могу смело доверить это ответственное задание своему командиру – то есть, вам, $N.$B$BПредлагаю сжечь два больших дома и казармы в нижнем квартале Скорна. Нам надо просто прокрасться в каждый дом и поджечь его факелом изнутри.', 'Сержант из крепости Западной Стражи поручил вам поджечь два больших дома и казармы в Скорне.', 'Отличная работа, сэр! Без вас я бы не справился с заданием.$B$BУверен, капитан будет доволен моим отчетом.', NULL, NULL, NULL, 'Северо-западный большой дом подожжен', 'Северо-восточный большой дом подожжен', 'Казармы подожжены', 'Факел сержанта');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11248, 'Операция: Атака на Скорн', '$N! Только тебе я могу доверить столь рискованное и смертельно опасное поручение.$B$BНа восточной границе нашего форта находится крепость врайкулов, Скорн. Мои разведчики доложили, что эти \"великаны\" планируют нападение, которое мы вряд ли сможем отразить.$B$BГрубой силой мы ничего не добьемся, поэтому я хочу пустить в дело хитрость. Я выслал вперед сержанта и снабдил его всеми необходимыми инструкциями. Отправляйся в Скорн и покажи ему этот знак отличия командира.', 'Капитан Адамс попросил вас воспользоваться знаком отличия командира Западной Стражи в Скорне и поговорить с сержантом из крепости Западной Стражи.', 'Рад познакомиться с тобой, $N!Это честь для меня – работать с тобой в одной команде.$B$BКстати говоря, у нас много дел!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11249, 'Остановить вознесение!', 'Этот огромный сверток сделан из драконьей кожи. Развернув его на всю длину, вы видите таинственные знаки на чешуйчатой поверхности, изображающие ход врайкульского ритуала. $B$BТам нарисован тан врайкульского клана, поднимающийся в небо в окружении ангелоподобных существ. Позади него во мраке изображена темная, загадочная фигура.$B$BЧто-то подсказывает вам, что тан скорнского клана собирается пройти через этот ритуал. Вы должны его остановить! Напротив дома тана уже вздымается в небо огромный погребальный костер.', 'Разверните врайкульский свиток вознесения рядом с погребальным костром тана, призовите и убейте его. Исходя из магической природы ритуала, вы можете предположить, что отцу Левариолу из Крепости Западной Стражи будет очень интересно взглянуть на этот свиток.', 'Да, сын мой, воистину, это странный документ! Впрочем, похоже, ты правильно расшифровал надписи.$B$BСпасибо тебе за этот свиток. Я внимательно изучу его и постараюсь постигнуть его предназначение. Пока что я могу предположить, что эти врайкулы нашли способ обмануть смерть; во всяком случае, это касается самых достойных их представителей.$B$BПобедив тана Снежескорнов, ты показал, что он был недостоин такой чести. Кто знает, какие беды принесло бы нам его перерождение, если бы он остался в живых!', 'Чем я могу помочь тебе, дитя мое?', NULL, NULL, 'Халфдан Ледяное Сердце убито', 'Врайкульский свиток вознесения (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11250, 'Слава покорителю Скорна!', 'Мы – точнее, ты – $gсделал:сделала: все, за чем нас сюда посылали. Я горжусь тем, что мне довелось служить под началом $gтакого юного, но мудрого:такой юной: но мудрой:r; |3-1($gраса:). $B$BНе сомневаюсь, капитан будет рад слышать о твоих достижениях, но если ты по какой-то причине решишь остаться тут на некоторое время, то я всегда в твоем распоряжении.', 'Отнесите знак отличия командира Западной Стражи капитану Адамсу в Крепость Западной Стражи.', 'Какие прекрасные новости! Я знал, что ты сможешь осадить их, $N!$B$BНу, хоть на кого-то здесь можно положиться.$B$BПолагаю, ты заслужил награду. Давай, выбирай – для тебя ничего не жалко.', 'Полагаю, раз ты вернулся то Скорн больше нам не угрожает?', NULL, NULL, 'Знак отличия командира Западной Стражи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11251, 'С новыми силами', 'Мы заплатили высокую цену, но все-таки закончили разведку местности.$B$BК сожалению, сведения не очень обнадеживают. Практически всех жителей захватили в плен или убили. Пропавшими без вести числятся лишь несколько опытных стражей.$B$BРазведчики сделали все, что могли – теперь настала твоя очередь действовать.$B$BИз-за холма на северо-востоке доносятся звуки сражения. Узнай, что там происходит, $C. Будем надеяться, мы найдем выживших, и они дадут нам информацию, которую можно будет использовать против наших врагов.', 'Разведчица Валори просит вас узнать, что за звуки битвы доносятся из-за холма на северо-востоке Деревни Драконьего Черепа.', 'Ну, наконец-то, помощь пришла! Рад видеть тебя, дружище.$B$BА теперь хватит стоять столбом, принимайся за работу!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11252, 'На Утгард!', 'Слушай, $gюнец:девчонка:,. Я уже убил столько этих тварей, сколько тебе за всю жизнь не положить. Сечешь?...$B$BВрайкулы не знают страха в битве. Иногда кажется, что они равнодушны к смерти. Учитывая их свирепость и их численность – мы обречены. Вот так-то.$B$BЕсть, правда, среди них один врайкул, которого они уважают. Зовут его Ингвар. Не знаю уж, почему они так перед ним пресмыкаются, но твоя победа над ним повергнет их в ужас.$B$BТогда, возможно, у нас появится шанс...', 'Защитник Мордун поручил вам казнить Ингвара Грабителя, который обитает в Утгарде, и принести его голову вице-адмиралу Келлеру.', 'Потрясающе!$B$BНеужели удача наконец-то повернулась к нам лицом?$B$BТы молодец, $N!', 'Рад видеть тебя в добром здравии, $N.$B$BМы и так уже потеряли слишком много славных воинов.', NULL, NULL, 'Голова Ингвара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11253, 'По следу врага', 'Теперь, когда этот подлец набил свое брюхо, возможно, он захочет немного потрудиться. Вот его поводок – иди и забери его из клетки.$B$BНе знаю, что там хочет от тебя Ансельм, но этот пес точно приведет тебя к цели.', 'Воспользуйтесь ошейником чумного пса и заберите из клетки в Лагере Возмездия чумного пса-ищейку. Идите с ним по следу, куда бы он вас не привел.', 'Этот потрепанный свиток покрыт яркими рисунками. Вы чувствуете, что собаколов говорил вам именно о такой находке.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11254, 'Карта на шкуре дракона', 'Внимательно изучив свиток, вы понимаете, что это подробная карта фьорда. Местонахождения различных деревень отмечены символами, напоминающими племенные знаки. $B$BЛагерь Возмездия помечен огромным рисунком, изображающим череп.$B$BЭта карта, несомненно, представляет огромный интерес для верховного палача Ансельма.', 'Принесите карту на шкуре дракона верховному палачу Ансельму в Лагерь Возмездия.', '<Верховный палач внимательно рассматривает карту, изучая символы вокруг Фьорда.>$B$BТак, это восточное побережье. Значит, деревни Укротителей драконов и Снежескорнов находятся здесь и здесь... а это, должно быть, мы, приговоренные к смерти.', 'Ты хочешь мне что-то показать, $C?', NULL, NULL, 'Карта на шкуре дракона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11255, 'Пленники в Деревне Драконьего Черепа', 'Эта война еще не закончена, $N. Если наши люди в деревне все еще живы, кто-то должен пойти туда и спасти их. $B$B<Вице-адмирал Келлер указывает на вас.>$B$BОтправляйся на север, в Деревню Драконьего Черепа. Как только окажешься в поселении, ищи наших людей. Если они в плену – найди способ освободить их. $B$BВозможно, они смогут дать нам больше информации о нашем противнике.', 'Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 3 пленных валгардских узников.', 'Спасенные тобой солдаты предоставили нам крайне важную информацию. Эти твари называют себя \"врайкулами\". Их племя, обосновавшееся в Деревне Драконьего Черепа, возглавляет мистик по имени Янис, который провозглашает себя служителем другого врайкула, Ингвара Расхитителя.', NULL, NULL, NULL, 'Спасено валгардских узников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11256, 'Скорн должен пасть!', '$N! Врайкульская крепость – Скорн – находится на юге. Недавно в ней пробудились некие странные великаны, которые теперь повсеместно атакуют наши войска.$B$BМои разведчики сообщают, что они планируют напасть на наш лагерь, и мы не сможем им противостоять. Единственный выход для моего народа – покинуть эти земли и уйти на север, в более безопасное место.$B$BЯ прошу тебя, приложи все свои умения и выиграй для нас немного времени. Я выслал вперед храбреца из нашего племени. Покажи ему эту эмблему, и он расскажет тебе, что надо сделать.', 'Вождь Прахтотем попросил вас воспользоваться эмблемой Заиндевевшего Копыта в Скорне и поговорить с храбрецом из Лагеря Заиндевевшего Копыта.', 'Интересно будет познакомиться с твоим народом, $C. Скоро мы будем сражаться бок о бок! $B$BНу, что, за работу?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11257, 'Тяжело, но необходимо', 'Наши старейшины говорят, что врайкулы могут восставать из мертвых. Нет, они не похожи на оживших мертвецов Плети, но их понятие жизни после смерти несет нам не меньшие беды.$B$BМы не можем так рисковать!$B$BВот, возьми мое мачете. Пока мы будем продвигаться вперед, кромсай им все трупы врайкулов, которые встретятся тебе по пути.$B$BЯ потратил все утро на заточку клинка, так что теперь он разрубит даже самые толстые кости.', 'Храбрец из лагеря Заиндевевшего Копыта попросил вас разрубить на куски 20 снежескорнских врайкулов в Скорне.', 'Тебе уже приходилось держать в руках мачете? Кажется, ты с ним вполне неплохо управляешься.$B$B<Храбрец с опаской смотрит на вас.>$B$BДавай-ка я заберу его у тебя, $C. На всякий случай.', NULL, NULL, NULL, 'Разрублено тел снежескорнских врайкулов', 'Мачете Храбреца', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11258, 'Гори, Скорн, гори!', 'Вождь Прахтотем приказал мне разрушить множество зданий в Скорне.$B$BНо теперь я могу смело доверить это ответственное задание своему командиру – то есть тебе, $N.$B$BПредлагаю сжечь два больших дома и казармы в нижнем квартале Скорна. Нам надо просто прокрасться в каждый дом и поджечь его факелом изнутри.', 'Храбрец из Лагеря Заиндевевшего Копыта поручил вам поджечь северо-восточный большой дом, северо-западный большой дом и казармы в Скорне с помощью его факела. Когда дело будет сделано, поговорите с ним еще раз.', '<Храбрец одобрительно кивает, увидев, как ловко вы обращаетесь с факелом>$B$BПусть эти врайкулы почувствуют на себе всю ярость земли. Пусть они познают страх, который доселе вселяли в сердца других!', 'Знаешь, когда здания загорятся, нам лучше отбежать подальше. Дух огня не знает жалости в своем стремлении разрушать.', NULL, NULL, 'Северо-западный большой дом подожжен', 'Северо-восточный большой дом подожжен', 'Казармы подожжены', 'Факел Храбреца');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11259, 'Смертельно опасные башни', 'Продвигаясь в самое сердце Скорна, мы должны уничтожить сторожевые башни.$B$BНо на вершине каждой вышки несут стражу множество волшебников. Стоит тебе только приблизиться к башне – и ты $gобречен:обречена:.$B$BНо мы можем призвать ветрокрылов из Лагеря Заиндевевшего Копыта. Правда, для этого тебе придется подкрасться к башням и забросить на их вершину сигнальную ды$Nю ракету.$B$BГлавное – не подходи слишком близко.', 'Храбрец из Лагеря Заиндевевшего Копыта сообщил вам, что сторожевые башни Скорна разумнее всего разрушить атакой с воздуха, предварительно отметив их местонахождение с помощью сигнальной ракеты Храбреца.', 'А у тебя неплохо получилось, $N.$B$BНаконец-то и ветрокрылы нам пригодились. До сих пор они просто шатались по лагерю и пьянствовали круглыми сутками.', NULL, NULL, NULL, 'Cеверо-западная башня помечена', 'Восточная башня помечена', 'Юго-западная башня помечена', 'Юго-восточная башня помечена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11260, 'Остановить вознесение!', 'Этот огромный сверток сделан из драконьей кожи. Развернув его на всю длину, вы видите таинственные знаки на чешуйчатой поверхности, изображающие ход врайкульского ритуала. $B$BТам нарисован тан врайкульского клана, поднимающийся в небо в окружении ангелоподобных существ. Позади него во мраке изображена темная, загадочная фигура.$B$BЧто-то подсказывает вам, что глава скорнского клана собирается пройти через этот ритуал. Вы должны его остановить! Напротив дома тана уже вздымается в небо огромный погребальный костер.', 'Разверните врайкульский свиток вознесения рядом с погребальным костром тана, призовите и убейте его. Исходя из магической природы ритуала, вы можете предположить, что Великой Матери Анкхе из Лагеря Заиндевевшего Копыта будет очень интересно взглянуть на этот свиток.', 'Какая странная вещь! Впрочем, похоже, ты правильно расшифровал надписи.$B$BСпасибо тебе за этот свиток. Я внимательно изучу его и постараюсь постигнуть его предназначение. Пока что я могу предположить, что эти врайкулы нашли способ обмануть смерть; во всяком случае, это касается самых достойных их представителей.$B$BПобедив тана Снежескорнов, ты показал, что он был недостоин такой чести. Кто знает, какие беды принесло бы нам его перерождение, если бы он остался в живых!', 'Да? Чем я могу помочь тебе, дитя мое?', NULL, NULL, 'Халфдан Ледяное Сердце убито', 'Врайкульский свиток вознесения (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11261, 'Покоритель Скорна!', 'Ты $gсделал:сделала: все, ради чего нас сюда послали, $C. Должен признать, ты храбро $gсражался:сражалась:. Твой народ не такой уж и странный, как мне показалось сначала.$B$BВождь Прахтотем будет рад услышать о твоей победе, но если ты по какой-то причине решишь задержаться здесь – обращайся ко мне. Я всегда к твоим услугам.', 'Верните эмблему Зимнего Копыта вождю Прахтотему в Лагерь Заиндевевшего Копыта.', 'Отличные новости! Теперь мы можем спокойно подготовиться к отступлению.$B$BПрошу, возьми это в знак нашей благодарности.', 'Какие вести из Скорна, $N?', NULL, NULL, 'Эмблема Заиндевевшего Копыта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11262, 'Ингвар должен умереть!', 'Наконец-то! Я провела здесь слишком много времени, и разум уже начинает меня подводить. Я единственная оставшаяся в живых из всего разведывательного отряда. $B$BЯ передам тебе мой отчет с надеждой, что ты сможешь правильно распорядиться полученной информацией. Знай же, $C, что она досталась мне нелегко. $B$BЭти врайкулы – безжалостные воины. Учитывая их численность и беспощадность, у нас есть единственная надежда на спасение – убить их предводителя и уповать на то, что тем самым мы повергнем их войска в хаос. $B$BЗапомни это имя – Ингвар. Выполни свой долг и принеси его голову Ансельму.', 'Темный следопыт Марра просит вас убить Ингвара Расхитителя в Крепости Утгард и принести его голову верховному палачу Ансельму в Лагерь Возмездия.', 'Отличная работа, $N. После смерти предводителя врайкулов мы должны добиться более впечатляющих успехов в войне против этих тварей. $B$BТакой подвиг должен быть достойно вознагражден!', 'Выше нос, $R. $B$BНам еще так много предстоит совершить. Грубо говоря, это всего лишь верхушка айсберга.', NULL, NULL, 'Голова Ингвара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11263, 'Очистить Гьялерброн', 'Выжившие гонцы сообщили, что врайкулы замышляют нечто недоброе в своей главной крепости к западу отсюда. $B$BЭто запретное место зовется Гьялерброн. Мои выносливые гонцы доложили, что врайкулы проводят там некие странные ритуалы. $B$BЭтого мы не можем допустить.$B$BХочешь помочь нам? Тогда убей врайкулов в Гьялерброне прежде, чем они закончат свои приготовления и нападут на нас!', 'Вождь Прахтотем попросил вас убить 15 гьялербронских воинов, 8 гьялербронских руночаров и 8 гьялербронских сноходцев, после чего вернитесь в Лагерь Заиндевевшего Копыта.', 'Благодарю тебя, $N. Я знаю, что ты ничем не обязана моему народу.$B$BНо это место все еще меня беспокоит, и я боюсь, что наша война еще не окончена.', NULL, NULL, NULL, 'Гьялербронский воин убито', 'Гьялербронский руночар убито', 'Гьялербронский хранитель снов убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11264, 'Некро-владыка Мезхен', 'Мертвецы уже пришли в Гьялерброн, и они привели с собой некромантов?$B$BПредводитель этих некролордов должен умереть!$B$B$N, на твои плечи ложится огромная ответственность – ты $gдолжен:должна: сорвать планы некро-владыки Мезхена и уничтожить его самого.$B$BЯ не допущу, чтобы эти врайкулы заключили союз с мертвецами! $B$BМезхена можно найти на платформе в дальнем правом квартале Гьялерброна.', 'Убейте некро-владыку Мезхена. Затем вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта.', '<Вождь Прахтотем облегченно вздыхает.>$B$BНу, теперь мы можем вздохнуть спокойно.$B$B$N, ты снова подтвердила свою значимость для Лагеря Заиндевевшего Копыта и всех таунка. Пожалуйста, выбери себе что-нибудь из нашей сокровищницы. Я настаиваю.', NULL, NULL, NULL, 'Некро-владыка Мезхен убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11265, 'О ключах и клетках', 'Насколько нам известно, врайкулы совершают какие-то омерзительные ритуалы \"пробуждения\" к северу от Гьялерброна.$B$BВ ходе этих обрядов проливается кровь невинных жертв!$B$B$N, ты $gдолжен:должна: остановить это! Неважно, кого они держат в своих клетках для жертвоприношений – их надо освободить. Могу поспорить, врайкулы носят ключи при себе.$B$BНам не нужны эти мерзкие врайкулы поблизости, и еще меньше нам хочется разбираться с тем злом, которое они пытаются пробудить!', 'Великая Мать Анкха попросила вас собрать достаточное количество ключей от гьялербронских клеток, чтобы освободить 10 гьялербронских узников. Когда вы выполните задание, вернитесь к ней в Лагерь Заиндевевшего Копыта.', 'Когда я услышала о твоем успехе, у меня словно камень свалился с плеч! И еще больше я рада узнать, что некоторые из освобожденных тобой пленников были из племени таунка.$B$BПожалуйста, прими это в знак признательности за все, что ты сделал для нас. А я пока позабочусь о несчастных узниках.', NULL, NULL, NULL, 'Освобождено гьялербронских узников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11266, 'Гьялербронский план нападения', 'Вы держите в руках планы нападения на Лагерь Заиндевевшего Копыта. Похоже, что врайкулы собираются использовать для атаки ледяного змея, Ледиона, который кружит у вас над головой.$B$BНаверняка, Целея Ледогрив сможет что-нибудь предпринять, если вы доставите эти планы к ней в восточный лагерь.', 'Отнесите гьялербронский план нападения Целее Ледогрив в Лагерь Заиндевевшего Копыта.', '$N, мы не можем допустить, чтобы эти планы осуществились!', 'Что это?! Планы нападения на лагерь?$B$BОНИ ПОСЫЛАЮТ К НАМ ЛЕТУЧЕГО ЗМЕЯ?!', NULL, NULL, 'Гьялербронский план нападения (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11267, 'Ледяной змей и его повелитель', 'Ты мудро $gпоступил:поступила:, доставив ко мне этот документ. Увы, мои ветрокрылы вряд ли справятся с ледяным драконом. Тебе придется $gсамому:самой: отправиться на север, в Гьялерброн. Убей этого змея и его хозяина, Зловещего призывателя змей!$B$BНадеюсь, они еще не выпустили это ледяное чудовище в небо.$B$BНо, даже если это уже произошло, и змей движется на нас, его можно отозвать обратно с помощью рога призывателя змей. Звук рога привлечет Ледиона, и он приземлится обратно, на платформу слева от Гьялерброна.$B$BПожалуйста, $N, когда все закончится, принеси мне этот рог. Нельзя допустить, чтобы он попал не в те руки.', 'Убейте Зловещего призывателя змей и воспользуйтесь его рогом, чтобы позвать обратно Ледиона. Убейте ледяного змея и принесите рог Целее Ледогрив в Лагерь Заиндевевшего Копыта.', 'Этот рог холоднее льда, покрывающего землю!$B$B$N, ты спасла Лагерь Заиндевевшего Копыта от неминуемой гибели. Признаться, раньше я с предубеждением относилась к представителям твоей расы.$B$BЧто ж, ты заслужила эту награду. Выбирай!', 'Ледяной змей и его хозяин мертвы?$B$BНо где же рог?', NULL, NULL, 'Зловещий призыватель змей убито', 'Ледион убито', 'Рог призывателя змей', 'Рекомендуемое количество игроков: 2');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11268, 'Ходячие мертвецы', 'Ты уже $gсделал:сделала: для нас больше, чем мы рассчитывали, $N, но меня по-прежнему беспокоит одна проблема: Плеть.$B$BДухи земли и воздуха, огня и воды не переносят присутствия этих тварей, но ничего не могут им противопоставить. Это значит, что за дело должны взяться мы! $B$BВозможно, я прошу слишком многого, но ты $gдолжен:должна: вернуться на запад, в Гьялерброн, и уничтожить логово этой омерзительной Плети! Не забудь проверить, не остались ли эти презренные твари в чертогах Пробуждения, что под Гьялерброном.', 'Убейте 10 бессмертных дозорных, 4 кошмарных ужаса и 2 тлетворных существа, после чего уведомите Великую Мать Анкху из Лагеря Заиндевевшего Копыта об успешном выполнении поручения.', '<Великая Мать одобрительно кивает, слушая ваш рассказ.>$B$BСпасибо тебе, $N. Ты правильно поступила, и, благодаря твоим усилиям, у нас появилось время, чтобы закончить приготовления к походу. Скоро начнется наше путешествие на север.$B$BЯ уже слишком стара; мне не унести с собой все эти пожитки. Пожалуйста, возьми одну из этих вещей.', NULL, NULL, NULL, 'Бессмертный дозорный убито', 'Кошмарный ужас убито', 'Тлетворное существо убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11269, 'Работаем до упора', 'Со дня на день прибудет авангард войск Альянса. Всех этих солдат надо переодеть в зимнюю униформу, а я еще не закончил шить плащи. $B$BЯ подбиваю наши плащи пухом пятнистых гиппогрифов, но мои запасы не бесконечны!$B$BПомоги мне, $N. Капитан Адамс с меня шкуру сдерет, если плащи не будут готовы к сроку! Принеси мне весь пух, который сможешь найти. В чаще вокруг форта всегда полно линяющих гиппогрифов. Их пух валяется повсюду.', 'Гил Гризерт просит вас принести ему 10 клочков пуха пятнистых гиппогрифов.', 'Слава богам! Этого хватит, чтобы закончить пошив плащей к сроку. Ночами спать не буду, но закончу работу до прибытия войск. Все лучше, чем попасться под горячую руку капитану Адамсу.$B$BНаслышан я про этого вояку!', 'Ты нашел пух гиппогрифов? Ох, как он мне сейчас нужен!', NULL, NULL, 'Пух пятнистого гиппогрифа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11270, 'Ужасы войны', 'Мы постепенно заканчиваем зачистку северного флота Штормграда, высадившегося на побережье. Схватка была ожесточенной, чему свидетельствует множество мертвых тел на западе.$B$BНет, эти трупы не оскорбляют мое чувство прекрасного, но они могут стать угрозой всем нам.$B$BВидишь ли, в землях Короля-лича мертвецов очень легко превратить в оружие. Возьми этот факел и сделай все возможное, чтобы этого не произошло.', 'Верховный палач Ансельм из Лагеря Возмездия просит вас взять горящий факел и сжечь десять трупов, лежащих к западу от города.', 'Рад слышать, что ты ответственно относишься к приказам. Если бы мне давали по медной монете за каждого самонадеянного дурака в нашей армии, считающего, что он умнее своего командира... пожалуй, я бы уже скопил несколько золотых.$B$BТеперь же, когда ты доказал свою дисциплинированность, я могу поручить тебе более ответственное задание.', NULL, NULL, NULL, 'Сожжено павших бойцов', 'Горящий факел', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11271, 'Спешные приготовления', 'Пух пятнистых гиппогрифов очень ценится среди моего народа и используется в самых разнообразных целях – от оперения стрел до пошива церемониальной одежды. Поскольку мы готовимся покинуть аванпост, это наша последняя возможность набрать пух в сезон линьки.$B$BС твоей помощью я сделаю достаточный запас пуха, которого хватит на все путешествие. А дорога обещает быть нелегкой!$B$BИщи клочья пуха повсюду на земле вокруг аванпоста.', 'Ахота Белый Иней из Лагеря Заиндевевшего Копыта просит вас принести ему 10 клочков пуха пятнистых гиппогрифов.', 'С твоей помощью мы сможем хорошо подготовиться к этому нелегкому путешествию. Мне почти нечем тебя отблагодарить, но все же возьми одну из этих вещей, лежащих у меня без дела.', 'Ты нашел пух гиппогрифов?', NULL, NULL, 'Пух пятнистого гиппогрифа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11272, 'Сведение счетов', 'Этот эльфийский принц думает, что может ворваться в мой город, оскорбить королеву, убить моих людей и уйти безнаказанным? Он полагает, что мы будем стоять в стороне, пока орды Утгарда будут готовиться к нападению?$B$BНе бывать этому!$B$BТы отправишься в Утгард и убьешь его на глазах этих мерзких горилл. Пусть Артас знает, что намерения наши серьезны.', 'Верховный палач Ансельм повелел вам отправиться в Утгард и убить принца Келесета.', 'Ах, месть сладка. Подумать только – и это лишь начало!$B$BСкоро Артас получит по заслугам. Тогда и только тогда я умру счастливым.', NULL, NULL, NULL, 'Принц Келесет убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11273, 'Объединение людей', 'Мы были на грани величайшего археологического открытия, когда эти чудовища напали на наш лагерь! Увы, вернуться в Валгард удалось только мне одному. Я даже не знаю, что стало с моими людьми, и куда пропали артефакты, которые мы достали из раскопа! Как бы то ни было, их надо вернуть!$B$BРаз уж ты все равно направляешься в Деревню Драконьего Черепа, поищи, пожалуйста, моих сослуживцев! Если есть хоть какая-то надежда сохранить полученную информацию, мы должны ей воспользоваться!$B$BПрежде всего постарайся найти Пулроя. Когда я бежал из лагеря, он был еще жив.', 'Найдите Пулроя в Деревне Драконьего Черепа.', 'Вы нашли Пулроя – увы, слишком поздно.$B$BОбыскав тело археолога, вы видите журнал, крепко зажатый в руке Пулроя. Похоже, это предсмертные записи несчастного дворфа.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11274, 'Зедд мертв, детка?', 'Тому, кто найдет этот журнал:$B$BЭти кровожадные мерзавцы захватили руины Драконьего Черепа. Я не знаю, зачем они сюда пришли и чего добиваются. Честно говоря, мне все равно – я беспокоюсь только за сохранность артефактов.$B$BПрячась в этом месте, мы с Зеддом натолкнулись на потрясающее открытие: мы обнаружили шифр к табличкам! К несчастью, прошлой ночью Зедд отстал. Шифр все еще у него. Таблички унесли Глоренфелд и Дегарн. Где они – неизвестно...$B$BНайди Зедда.$B$B-Пулрой', 'Найдите Зедда в Деревне Драконьего Черепа.', 'Вы нашли Зедда. Увы, не надо быть доктором, чтобы понять, что для бедняги все кончено.$B$BПохоже, его собирались скормить воргам. Бедняга...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11275, 'Охотничий рог', 'Многие поколения мои соплеменники охотились на гигантских йети, обитающих в этих холмах. В этом году наконец-то настал мой черед присоединиться к охоте. Надеюсь, мы успеем загнать немало йети перед тем, как навсегда покинем эти края.$B$BЧтобы подготовиться к охоте, мне надо вырезать охотничий рог из рогов жутких баранов, которые бродят вокруг нашего лагеря. Старейшины сказали, что звук охотничьего рога напоминает брачный зов самки йети, но мне в это верится с трудом.$B$BВпрочем, неважно – главное, сделать рог. Давай ты принесешь мне самые лучшие рога барана, а я выберу себе один для отделки.', 'Нокома Заклинатель Снегов из Лагеря Заиндевевшего Копыта просит вас принести ей 6 неповрежденных рогов барана.', 'Какие отличные рога, $N! Сейчас я осмотрю их повнимательнее и выберу один для обработки.$B$BА остальные я отдам нашим мастерам – пусть сделают из них что-нибудь красивое.', 'Ты нашел какие-нибудь подходящие рога?', NULL, NULL, 'Неповрежденный бараний рог', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11276, 'И их осталось двое...', 'Похоже, у Зедда не было с собой шифра. Тщательно осмотрев местность, вы находите в грязи надпись, которая гласит:$B$B\"Глор и Дег в катакомбах. Шифр и таблички у них.\"$B$BПохоже, вам придется отправиться в катакомбы, которые находятся к северу от этого места, и найти Глоренфелда и Дегарна. За мостом, перекинутым через яму с воргами, виднеется туннель, который ведет прямо в катакомбы.', 'Обыщите Катакомбы Утгард в поисках Глоренфелда.', 'Ну наконец-то! Пулрой и Зедд мертвы.$B$BА Дегарн...$B$B<Глоренфелд качает головой.>$B$BВождь Укротителей драконов утащил его в глубину катакомб. Я услышал краем уха, как этот гамадрил-переросток говорил что-то о \"пожертвовании Королю ужаса\"$B$BШифр у него, спрятан в бороде.$B$BЧего-о? Дворфы всегда прячут самые ценные вещи в бороде!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11277, 'Глубины порока', 'Они держат Дегарна в запертой клетке на огромной арене для гладиаторских боев. Насколько я понял, Укротители драконов выпускают своих пленников на эту арену, чтобы те сражались с самыми безжалостными врайкульскими бойцами. Неудачников они скидывают вниз, в подвалы, где Плеть превращает их в зомби! Ужасно, не правда ли?$B$BНо сначала мы должны решить первоочередные проблемы. Главное – собрать таблички, которые разбросаны по всему подземелью! Найди их – а потом можешь играть в героя-освободителя!', 'Глоренфелд из Катакомб Утгард просит вас собрать 10 табличек Драконьего Черепа.', 'Ты молодец, дружище. Теперь, когда таблички в безопасности, мы можем попытаться спасти Дегарна и вернуть шифр, который поможет нам расшифровать тайный смысл этих древних надписей!$B$BДавай так: я буду сторожить таблички, а ты освободишь моего коллегу.', 'Проверь каждый уголок!', NULL, NULL, 'Табличка Драконьего Черепа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11278, 'Возвращение в Валгард', 'Мне горько думать о том, что мы потеряли двух наших лучших дворфов в поисках этих святынь. Они пожертвовали своими жизнями, чтобы сохранить и донести до нас эту информацию.$B$B<Глоренфелд заворачивает шифр и таблички в потрепанный платок.>$B$BОтнеси это назад, в Валгард. Максорф знает, что надо делать.$B$BЯ? Со мной все будет в порядке. Видишь – я пока что цел и невредим.', 'Отнесите сверток Глоренфелда Белтранду Максорфу в Валгардский порт.', 'Мне понадобится время, чтобы рассортировать эти таблички. Но я уверен, что мои исследования прольют свет на тайну происхождения людей. Я уверен, что когда-то здесь жили наши предки, но все они были уничтожены врайкулами. Как только я расшифрую надписи на этих святынях, мы узнаем правду.', 'Ты вернулся!', NULL, NULL, 'Сверток Глоренфелда (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11279, 'Зеленые и светящиеся', 'Мы разработали превосходную чуму, и мне не терпится расширить поле экспериментов. $B$BМожет быть, нам испытать ее на детенышах протодраконов?!$B$BТы только подумай о том, какие возможности открываются перед нами! Мы станем первооткрывателями штамма, способного поражать всех живых существ!$B$BВот, я отложил на всякий случай запасную канистру с чумой. Полагаю, я могу доверить ее тебе.$B$BОбрызгай яйца протодраконов в Пылающем Гнездовье на северо-западе, после чего возьми образцы зачумленных детенышей протодраконов, которые вылупятся из зараженной кладки.', 'Распространитель чумы Тилингаст попросил вас собрать 10 образцов плоти зачумленных детенышей протодраконов и отнести их к нему в Новый Агамонд.', 'Что?! Нет, не может быть!$B$BПРОКЛЯТИЕ!$B$BЭтот штамм чумы не оказал практически никакого воздействия на детенышей протодраконов – разве что теперь они стали зелеными и светящимися!$B$BА я так мечтал изобрести чуму, которая уничтожала бы любое живое существо!', 'Без этих образцов я не смогу доказать нашему научному сообществу, что мой штамм способен поражать все живые организмы!', NULL, NULL, 'Образец плоти зачумленного детеныша протодракона', 'Чумная канистра Тиллингаста', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11280, 'Драконис гастритис', 'У меня появилась мысль. Что если чума не убила дракончиков потому, что мы распыляли отраву снаружи?$B$B$N, мы должны как-то заразить их изнутри!$B$BПридумал! Вот, держи кусок зачумленного мяса. Отнеси его в Пылающее Гнездовье и скорми дракончикам!$B$BХотя нет, мы должны мыслить шире. Лучше примани с его помощью большого протодракона – пусть он спустится с неба и сожрет наше угощение.$B$BЯ гений!$B$BКстати, не отходи далеко от нашего подопытного и наблюдай, что произойдет. Он, конечно, может напасть на тебя... но такова цена прогресса!', 'Распространитель чумы Тилингаст просит вас приманить протодракона с помощью куска зачумленного мяса Тилингаста и понаблюдать за его реакцией на угощение.', 'НЕЕЕЕЕЕЕЕТ!!!$B$B<Распространитель чумы рвет на себе волосы.>$B$BМои надежды... все мои мечты пошли прахом!$B$BОставь меня, Профессия. Оставь меня наедине с моим горем. Я ничтожество.$B$BВот, забери все, что у меня есть. Когда остальные фармацевты узнают о моей неудаче, со мной будет все кончено. Все равно я не заберу эти побрякушки с собой в могилу.', NULL, NULL, NULL, 'Результаты заражения протодраконов получены', 'Зачумленное мясо Тилингаста', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11281, 'Подражая зову природы', 'Я обточила рог, но прежде чем наносить на него традиционную резьбу, надо убедиться, что он работает. Ахота говорил, что он испытывает свои охотничьи рога у подножия замерзшего водопада на северо-востоке лагеря. Он утверждает, что наши охотники уже много поколений используют акустику льда для этой цели.$B$BТы поможешь мне испытать рог? Если я правильно его вырезала, то на его зов может откликнуться сам великий йети! Только не забудь вернуть мне рог после проверки.', 'Испытайте вырезанный рог и верните его Нокоме Заклинателю Снегов в Лагерь Заиндевевшего Копыта.', '<Нокома слушает о результатах испытания.>$B$BПриятно слышать, что рог сработал, как надо... может быть, даже лучше, чем я рассчитывала. Но... неужели этот зверь действительно говорил с тобой? Не знаю даже, как теперь на него охотиться. Надо посоветоваться с вождем Прахтотемом.$B$BВозможно, в итоге мне никогда не придется воспользоваться этим рогом, но это не уменьшает его ценности. Спасибо тебе за помощь, Профессия.', 'Довелось ли тебе испытать рог?', NULL, NULL, 'Рог Нокомы испытан', 'Вырезанный рог', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11282, 'Урок страха', 'Когда ты побываешь в стольких же переделках, как и Горт, ты поймешь, что врага можно победить лишь тогда, когда он боится тебя до смерти! $B$BНо эти врайкулы нас не боятся. Убьешь одного – на его место приходит другой... только вопит еще громче, и секира у него больше в два раза.$B$BТолько смерть самого большого и страшного врайкула может напугать все это племя.$B$BИди же и сражайся со Снежескорнами, пока не появятся их чемпионы. Убей их всех и проткни трупы древком флага Отрекшихся. Пусть они узнают, что такое страх!', 'По приказу Горта вам надо победить Улфа Кровопускателя, Орика Зловещего и Гуннара Торвардссона, после чего проткнуть их тела древком знамени Отрекшихся. Убивайте врайкулов вдоль баррикады, возведенной Отрекшимися, пока не появятся чемпионы.', 'Молодец, ты хорошо потрудился. Я видел, как пали врайкулы, пронзенные древком флага Сильваны. Да, сегодня победа на нашей стороне!', NULL, NULL, NULL, 'Труп Орика Зловещего проткнут древком', 'Труп Улфа Кровопускателя проткнут древком', 'Труп Гуннара Торвардссона проткнут древком', 'Знамя Отрекшихся');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11283, 'Кровавая бойня в Гибльхейме', 'Эти врайкулы так и прут из западного поселения! Можно подумать, они там почкованием размножаются – так их много.$B$BНо у Горта есть идея. Ты $gсам:сама: пойдешь в этот город и перебьешь всех Снежескорнов. Тогда они перестанут лезть к нам!', 'Сержант Горт просит вас убить 16 снежескорнских врайкулов в Гибльхейме.', 'Я гляжу, тебе не впервой убивать! Справляешься с этим делом не хуже Горта!', NULL, NULL, NULL, 'Убито врайкулов в Гибльхейме', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11284, 'Соседство с йети', 'Если охранники не желают помогать мне – может быть, ты меня поддержишь? Я – старшина шахты, которая находится за мостом. Мои люди добывают руду, которая пойдет на выплавку оружия для разведывательных отрядов. Без наших поставок они не смогут расчистить путь к Седым холмам.$B$BНо недавно шахту захватил гигантский йети, преградив путь к тоннелю, который нам необходимо расширить! Мы пытались напугать его криками и даже пробовали выкурить его оттуда, но ничего не получилось.$B$BМожет быть, ты сможешь разбудить его запахом свежей баранины? Вокруг города по снегу бродят множество ледорогих баранов. Пожалуйста, помоги нам! Мы в отчаянии!', 'Старшина Колби из крепости Вилдервар просит вас убить Сколорога.', 'Удалось? Во имя Света, ты мой спаситель! Я уж начал подбирать слова, как извиняться перед капитаном Адамсом за то, что оружие для его солдат все еще не готово!', NULL, NULL, NULL, 'Сколорог убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11285, 'Гори, Гибльхейм!', 'Недостаточно просто убить Снежескорнов – мы должны сжечь их дома! Э... и мосты тоже. Давай спалим весь город – на всякий случай!$B$BВот, возьми факел. Иди в Гибльхейм, на запад, и сожги его ДОТЛА! Это научит их бояться.', 'Сержант Горт послал вас в Гибльхейм с факелом Горта, чтобы вы сожгли 1 снежескорнское здание, 1 снежескорнскую сторожевую башню, 1 снежескорнский мост и 1 снежескорнские казармы.', 'Похоже, ты сжег почти все постройки. Осталось несколько зданий... но Горт доволен тем, что видит.', NULL, NULL, NULL, 'Снежескорнское здание подожжено', 'Снежескорнская сторожевая башня подожжена', 'Снежескорнский мост подожжен', 'Снежескорнские казармы подожжены');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11286, 'Артефакты Стальных ворот', 'Я пришел сюда по другой причине – мой старый друг явился ко мне во сне и просил о помощи. Но когда я увидел эти штуковины, роющие огро$Nю яму в земле, меня охватила ярость.$B$BНасколько я понимаю, эти так называемые дворфы выкапывают древние артефакты, которые могут пролить свет на наше прошлое.$B$BПожалуйста, спустись туда и принеси их мне. Надеюсь, ни один из дворфов не станет у тебя на пути.', 'Ведун Странник Туманов попросил вас принести 10 артефактов Стальных ворот. Когда вы соберете их все, вернитесь к ведуну в Стальные ворота.', '<Ведун одобрительно кивает.>$B$BВозможно, мне удастся выкроить время для исследования этих артефактов и понять их предназначение.$B$BНо сейчас меня ждут более важные дела.', 'Сколько артефактов ты нашел в Стальных Воротах?', NULL, NULL, 'Артефакт Стальных ворот', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11287, 'Найти ведуна Странника Туманов', '$C, я беспокоюсь за своего сына, ведуна Странника Туманов. Земли эти жестоки и беспощадны, а от него давно не было никаких вестей.$B$BОн сказал, что видит сны про какого-то волка, после чего собрал маленькую группу выносливых гонцов и отправился на запад. Мне кажется, он упоминал некое место под названием Стальные ворота.$B$BНе $gмог:могла: бы ты отправиться на его поиски? Я должна убедиться, что с ним все в порядке.', 'Великая Мать Анкха попросила вас найти ведуна Странника Туманов. Она полагает, что он сейчас находится где-то рядом со Стальными Воротами.', 'Ах, мама слишком заботится о моей безопасности. Но, в любом случае, спасибо за то, что разыскал меня, незнакомец.$B$BКстати, раз уж ты здесь, может быть, поможешь мне в одном деле?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11288, 'Сияние света', '$gАрес тяжело дышит, пытаясь обратиться к вам.>$B$BЯ – посланник Серебряного Авангарда, исполняющий свой священный долг.$B$BНаши силы были уничтожены в Чумных землях. Сиянием рассвета артефакт был очищен и избавлен от скверны. Многие из нас сгинули ради возвращения этой святыни.$B$BНо надежда все еще жива...еще есть время.$B$BАртефакт был унесен в логово Павших, что вырыто глубоко под нами. Его охраняют безжалостные мертвецы.$B$B<Тело Ареса начинает светиться непереносимо ярким светом.>$B$BСвет... защитит... тебя...', 'Арес Поклявшийся, лежащий при смерти в Катакомбах Утгард, попросил вас вернуть священный артефакт.Это задание ограничено по времени.', 'Вам кажется, что будет правильно положить священный клинок рядом с телом Ареса.$B$BКак только вы кладете меч, вас снова ослепляет яркий свет.', '<Арес без сознания.>', NULL, NULL, 'Священный артефакт', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11289, 'Ведомый честью', '$gАрес улыбается.>$B$BСлава Свету. Ты $gуспел:успела:! $B$B<Арес кашляет.>$B$BВозьми этот артефакт и отнеси его в Валгард. Лорд Ирулон Верный Клинок ожидает его возвращения.$B$BСражайся с честью, друг мой. Всегда. Честь превыше всего.$B$B<Арес умирает.:', 'Верните священный артефакт лорду Ирулону Верный Клинок в Валгард.', 'Многие мужчины и женщины пожертвовали своими жизнями ради возвращения этого клинка. Увы, я боюсь, что со смертью благородного Ареса кровопролитие не закончится. $B$BНо ты совершил угодный Свету поступок. Этот священный клинок возьмет в свои руки сам лорд Тирион Фордринг. Даже в эти минуты Серебряный Авангард продолжает наступление на Ледяную Корону. Лорд Фордринг поклялся самолично разрушить стены этой проклятой крепости! Теперь же он сможет обратить этот клинок против самого Короля-лича.$B$BЛорд Фордринг – это наша последняя надежда и опора.', 'Во имя Света!', NULL, NULL, 'Священный артефакт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11290, 'Военные планы Укротителей драконов', 'Хотя мы мало что знаем о местонахождении Ингвара, нам точно известно, что Янис обитает в пещере рядом с воргской ямой в Деревне Драконьего Черепа.$B$BРазведданные, полученные от спасенных солдат, подтверждают, что Янис охраняет военные планы клана Укротителей драконов.$B$BТы $gдолжен:должна: вернуться в Деревню Драконьего Черепа и забрать эти планы. Убивай всех врайкулов, которые встретятся тебе на пути, включая Яниса!', 'Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде поручил вам достать военные планы клана Укротителей драконов.', '<Вице-адмирал Келлер бегло проглядывает планы.>$B$BНевероятно! Судя по всему, в фьорде есть несколько поселений врайкулов. Еще одно племя планирует нападение на Крепость Западной Стражи. О боги, возможно, мы уже опоздали! Я уже несколько дней не получал известий из крепости. Как бы то ни было, мы должны их предупредить!', 'Военные планы у тебя?', NULL, NULL, 'Военные планы клана Укротителей драконов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11291, 'В Крепость Западной Стражи!', '$gВице-адмирал Келлер сворачивает тактические планы.>$B$BС помощью этой информации мы укрепим оборону Валгарда. Отнеси эти военные планы в Крепость Западной Стражи, которая выстроена на западном обрыве фьорда. Поговори с помощницей распорядителя полетов, Эмиленой Зимний Ветер. Пусть она подыщет тебе грифона, знающего путь в Крепость.$B$BКак только прибудешь на место, найди капитана Адамса. Он командует крепостью и знает, что делать с этими планами.', 'Отнесите военные планы Укротителей драконов капитану Адамсу в Крепость Западной Стражи в Ревущем фьорде.', '<Капитан Адамс забирает у вас планы.>$B$BХорошо, что ты нашел время занести сюда эти планы. Моим советникам понадобится немало времени, чтобы изучить их досконально. Чувствую я, грядут тяжелые времена!', 'Валгард еще стоит на месте? Вот чудеса.$B$BСомневаюсь, что Келлер обошелся без твоей помощи.', NULL, NULL, 'Военные планы клана Укротителей драконов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11292, 'Слабое звено', 'Рад встрече, $N. Я пришел сюда с Седых холмов, чтобы вести дела с твоими союзниками. Мои люди раскинули огромный лагерь на севере, и я искренне рекомендую тебе заглянуть туда.$B$BКстати, по пути я расставил множество силков в лесах и на заснеженных полянах. Частенько в них попадаются зверьки, чей мех и мясо я обмениваю на всякие полезные товары.$B$BМогу предложить тебе долю от доходов, если ты согласишься время от времени приносить мою добычу. Только будь $gосторожен:осторожна: – мы здесь не единственные хищники.', 'Зверолов Джетан из крепости Вилдервар просит вас принести ему 8 пойманных зверьков.', '<Зверолов Джетан осматривает пойманных зверьков.>$B$BЗа эту добычу я выручу хорошие деньги, но для торговли мне надо скопить побольше товара.', 'Надеюсь, ты вернулся не с пустыми руками. Мы же договорились!', NULL, NULL, 'Пойманный зверек', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11293, 'Пивоварня Ячменоваров ищет зазывалу!', 'На Хмельном фестивале нам не обойтись без рекламы наших напитков. В Палатах войны, в Зале исследователей и в Палатах магии установлены флаги. Возле каждого из них нужно зычно прокричать хвалу Ячменевцам. Чтобы упростить задачу, я одолжу тебе на 4 минуты поводья и скакового барана. Подгоняй его с помощью поводьев, но не переусердствуй.', 'Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах войны, в Зале исследователей и в Палатах магии.', 'Молодец! Надеюсь, мы к себе переманили клиентов.$B$BА вот и обещанная награда. Мы, Ячменовары, держим слово.$B$BАх да, заходи завтра, можешь еще раз поработать зазывалой.', NULL, NULL, NULL, 'Зазывайте посетителей возле банка', 'Зазывайте посетителей в Палатах войны', 'Зазывайте посетителей в Зале Исследователей', 'Зазывайте посетителей в Палатах Магии');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11294, 'Пивоварня Громоваров ищет зазывалу!', 'Пора сообщить народу, что его мольбы о добром пиве услышаны! В Палатах войны, в Зале исследователей и в Палатах магии установлены флаги. Возле каждого из них нужно зычно прокричать хвалу Громовару.$B$BМы решили упростить твою задачу. Тебе будет выдан баран и поводья на целых 4 минуты!$B$BТолько не очень-то гони барана, ящиков с яблоками в Стальгорне нет... Мы не позволим зазывалам Ячменевца нас обойти!', 'Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах войны, в Зале исследователей и в Палатах магии.', 'Отлично! Думаю, мы показали этим нахалам, Ячменоварам.$B$BМы обещали тебе награду. Вот она. Мы, семейство Громоваров, одариваем тебя призами, а Ячменовары – только вонью и ложными посулами.$B$BТы сделал правильный выбор.$B$BЕсли ты и дальше хочешь держаться нашей семьи, заходи завтра и еще раз поработай зазывалой.', NULL, NULL, NULL, 'Зазывайте посетителей возле банка', 'Зазывайте посетителей в Палатах войны', 'Зазывайте посетителей в Зале Исследователей', 'Зазывайте посетителей в Палатах Магии');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11295, 'В наступление!', 'Мы практически ничего не знаем о врайкулах. За многие века они никак себя не проявляли, и потому не упомянуты в наших записях. Но стоило нам выступить против Артаса, как они появились на нашем пути. $B$BПринесенная тобой карта подтверждает, что мы сначала должны разделаться с ними, и только потом следовать вглубь материка. $B$BОдин из моих лучших сержантов, поганище по имени Горт, надзирает за баррикадой у подъемника, наверху. Окажи ему помощь в организации превентивного удара по Гибльхейму. Если врайкулы решат напасть на нас, то это произойдет именно там.', 'Поговорите с сержантом Гортом на баррикаде рядом с подъемником к западу от Лагеря Возмездия в Ревущем Фьорде.', 'Пришел помочь нам? Это хорошо...$B$BГорту уже надоело весь день убивать врайкулов. Помощь мне пригодится!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11296, 'Пленники терзающих вдов', 'Что-то беспокоит обитающих в этих краях существ – возможно, это живые мертвецы Плети.$B$BСопровождая ведуна, мы потеряли почти половину отряда из-за терзающих вдов – огромных и смертоносных пауков, населяющих Вырубки к северу отсюда.$B$BУвы, я не могу оставить оставшихся людей без защиты, но... ты ведь можешь узнать, что случилось с моими выносливыми гонцами? Возможно, терзающие вдовы не убили их, а только заключили в свои коконы.$B$BТы поможешь мне, $gнезнакомец:незнакомка:?', 'Тученеб попросил вас освободить 7 выносливых гонцов из лагеря Заиндевевшего Копыта. Выполнив это задание, вернитесь к нему в Стальные ворота.', 'Ты совершил подвиг, $C. Я даже не представлял, что твой народ способен на такую жертвенность ради других.$B$BВ следующий раз я прислушаюсь к предостережениям старейшин и стану обходить Вырубки стороной. Чего и тебе советую.', NULL, NULL, NULL, 'Освобождено гонцов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11297, 'Слежка за нарушителями границ', 'Даже сама земля не в силах сдержать натиск смерти. Бродят по ней мертвецы, распространяя скверну с ужасающей скоростью. $B$BОдному небольшому исследовательскому отряду нежити удалось подняться по западным склонам и разбить лагерь возле Шепчущей теснины. Скажи мне, $N, сможешь ли ты понять их стремление и убедить их не отравлять наши земли? Отправляйся на юго-запад от заставы и следуй к обрывам, нависающим над западным побережьем. Ты найдешь их лагерь к западу от раскопок у Стальных ворот.', 'Поговорите с аптекарем Малтусом в Аптекарском поселке.', 'А, тебя послали эти бизоноподобные люди, обитающие на севере. Я видел, как они пытаются следить за нами, наивно полагая, что мы их не замечаем. Полагаю, они считают эти земли своими? Увы, придется их разубедить.$B$BЯ не ожидал твоего визита, но, раз уж этот глупец послал тебя сюда, я мог бы воспользоваться твоими услугами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11298, 'Что они пьют?', 'К юго-востоку отсюда пролегает Шепчущая теснина. Ее захватили обезумевшие члены Лиги исследователей! Они напали на наш караван, который следовал через их территорию, и ограбили продовольственный отряд.$B$BЯ должен понять, что свело их с ума! Может быть, всему виной то варево в бочках, которые расставлены по всей теснине? Слушай, прикати мне несколько бочонков, пока эти дворфы будут заняты раскопками.', 'Аптекарь Малтус из Аптекарского поселка просит вас принести ему 5 дворфийских бочонков.', '<Аптекарь нацеживает себе большую кружку напитка.>$B$BНу, поехали!', 'Так ты несешь мне бочки или нет?', NULL, NULL, 'Дворфский бочонок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11299, 'Круг Правосудия', 'Возможно, ты уже $gвидел:видела: комнату, в которой держат Дегарна – она находится рядом с тем коридором, где ты $gискал:искала: таблички. Спустись по ступенькам, и ты найдешь его в запертой камере у подножия лестницы. $B$BОтправляйся туда и отыщи его. Возможно, он хотя бы сможет сообщить тебе шифр.', 'Найдите Дегарна в Круге Правосудия. Он заперт в Катакомбах Утгард.', 'Ура. Ты меня нашел. Йо-хо-хо!$B$BВот только шифра у меня нет. Эти мерзавцы первым делом покопались у меня в бороде! Теперь шифр у Олуфа – он глава местных гладиаторов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11300, 'Поражение на ринге', 'До Олуфа можно добраться только одним способом – перебить всех остальных гладиаторов. Иначе нам никогда не вернуть тайнопись. Так что не медли – ступай в Круг Правосудия. Если тебе удастся получить тайнопись, принеси ее Глоренфелду ко входу в эти катакомбы. $B$BА что я? Ты обо мне не беспокойся! Самое главное – найти связующее звено, которое откроет тайну происхождения всего человечества!', 'Победите гладиаторов в Круге Правосудия, сразитесь с Олуфом Неистовым и заберите у него древнюю тайнопись.Отнесите тайнопись Глоренфелду ко входу в Катакомбы Утгард.', 'Какое потрясающее приключение! Так значит, кто-то действительно вершит суд над этими несчастными созданиями? Но для чего?$B$BА, не обращай на меня внимания. Пусть с этим разбирается кто-нибудь другой. Главное, мы получили тайнопись и таблички – и потеряли всего двоих людей на этом пути.', 'Где Дегарн? А тайнопись?', NULL, NULL, 'Древняя тайнопись', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11301, 'Мозги! Мозги!', 'Малтус уже рассказывал тебе эти бредни про пивные бочонки и спятивших дворфов? $B$BНет, я не отрицаю того, что дворфы сошли с ума, но таскать у них пиво – дурная затея.$B$BЧто нам действительно надо – это мозги. Много мозгов. Скоро мы разгадаем эту тайну и, возможно, найдем новый компонент для создания чумы.$B$BВозьми эту пилу, отправляйся в Шепчущую теснину и убей несколько дворфов. Потом распили их черепные коробки, вынь мозги и принеси их мне.', 'Аптекарь Грик из Аптекарского поселка просит вас принести ему 12 мозгов спятивших исследователей.', 'Какие миленькие мозги! Прелесть, честное слово! То, что надо.$B$BСпасибо за помощь, $N. Теперь я покажу Малтусу всю глубину его заблуждения.', 'Ты принесла мне мозги? Нет? Тогда отдай пилу. Лучше тебе не разгуливать здесь с этой штукой.', NULL, NULL, 'Мозг спятившего исследователя', 'Костяная пила Грика', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11302, 'Загадочные ледяные нимфы', 'Впервые осматривая окрестности форта, мы заметили враждебно настроенных существ на двух полянах к северу отсюда. Когда мы проходили мимо заснеженной прогалины к югу от города, дриады с интересом наблюдали за нами, но не нападали. $B$BМестный климат порядком измотал моих людей, и они могли с легкостью уничтожить половину нашего отряда, но не стали. $B$BВозможно, эти дриады хотят стать нашими союзниками. Не желаешь ли ты отправиться на Заиндевевшую поляну и попытаться установить с ними контакт?', 'Поговорите с Луриэль на Заиндевевшей поляне.', '<Луриэль внимательно слушает вас.>$B$BЯ рада наконец-то познакомиться с тобой, $N. Мы надеялись, что кто-нибудь из новоприбывших пришлет к нам своих представителей. Сами мы редко выходим за границы наших полян, особенно после того, как окружающий нас мир претерпел изменения.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11303, 'Засада', 'Врайкулы в Гибльхейме повержены – в этом нет никаких сомнений. Но их предводители остались в городе и не собираются сдаваться.$B$BГорт послал Лиделла и его головорезов помахать кулаками на северо-западе. Иди, поговори с ним и выясни, как выманить врайкульского вождя и убить его. Смотри только, чтобы он помучился перед смертью!', 'Поговорите с Лиделлом в Засаде Лиделла.', 'Вечеринка в разгаре, но наш \"почетный гость\" предпочитает отсиживаться дома.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11304, 'Новый Агамонд', 'Боюсь, что Лагерь Возмездия недостаточно хорошо оборудован. В конце концов, это всего лишь военная база.$B$BПожалуйста, отнеси этот штамм главному распространителю чумы Харрису в Новый Агамонд. Чтобы найти город, иди по южной дороге мимо Гибльхейма, а потом поверни на запад. Он располагает более совершенным оборудованием, и знает, что делать с этим штаммом. $B$BПоторопись, $N. Наши враги превосходят нас силой и числом. Нам надо создать оружие, с помощью которого мы одержим победу!', 'Отнесите штамм Лисандера главному распространителю чумы Харрису в Новый Агамонд на запад Ревущего фьорда.', 'Друг мой, это вполне эффективный штамм! Эти идиоты из Лагеря Возмездия чуть не проморгали все на свете!', 'Что тебе, $N?', NULL, NULL, 'Выжимка Лисандера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11305, 'Идеальная формула', 'Мы уже несколько недель распространяем чуму в деревне врайкулов, Халгринде, а эти макаки по-прежнему живее всех живых! $B$BСкажу прямо, $N: на настоящий момент мы испытали штамм на людях, дворфах, собаках, домашнем скоте... на ком угодно. Но когда вирус приспосабливается к организму носителя, он изменяется и становится менее стабильным. Поэтому нам надо разработать штамм, идеально подходящий для организма врайкулов.$B$BНезадолго до того, как мы захватили Халгринд, из деревни бежал врайкульский вождь и укрылся к западу отсюда. А что может быть чище крови предводителя клана Укротителей драконов?', 'Добудьте кровь патриарха Укротителей драконов – вождя Торвальда, который укрылся в Лагере Торвальда, и принесите ее главному распространителю чумы Харрису в Новый Агамонд.', 'Да, этот образец подойдет. А теперь, $N, мы наконец-то приступим к работе!', 'Ты принес образец, $N?', NULL, NULL, 'Кровь патриарха Укротителей драконов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11306, 'Нагреть и перемешать', '$N, ты уже многого $gдостиг:достигла: на нашем поприще. Теперь я хочу обучить тебя некоторым более сложным способам изготовления чумы.$B$BВозьми эту флягу и наполни ее кровью из котла слева от меня. Смешивай ее с образцами чумы, которые лежат справа, пока не получишь однородную смесь.', 'Наполните пустой аптекарский флакон кровью из котла с кровью врайкулов, после чего добавляйте во флакон с кровью врайкула образцы чумы Харисса, пока не получите равномерную смесь. Когда вы выполните это поручение, вернитесь к Главному распространителю чумы Харрису.', 'Превосходно! Ты мой самый талантливый ученик, $N.$B$BА теперь займемся кое-чем более интересным: опытами!', 'Ну, как проходит эксперимент, $N? Если возникнут какие-либо вопросы – дай мне знать!', NULL, NULL, 'Равномерная смесь', 'Пустой аптекарский флакон', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11307, 'Полевые испытания', 'Теперь, когда мы получили штамм чумы, адаптировавшийся к нашим врайкулам-переносчикам, настало время испытать его на подопытных особях в Халгринде. Если все пойдет по плану, они распадутся на части через секунду после того, как чума проникнет в их организм!$B$BХалгринд находится к северу отсюда. Ты найдешь его с легкостью – наши распространители чумы уже там поработали.', 'Отправляйтесь в Халгринд и заразите ассимилированным штаммом чумы 10 зачумленных врайкулов из клана Укротителей драконов, после чего вернитесь к главному распространителю чумы Харрису.', 'Чума не уничтожила наших подопытных? Ты в этом уверен?$B$BДолжно быть, мы не учли какой-то внешний фактор... может быть, климатический? Или... возможно, произошла мутация штамма!', NULL, NULL, NULL, 'Заражено зачумленных врайкулов', 'Распылитель чумы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11308, 'Пора заметать следы', 'Будучи человеком практичным, я могу заявить, что мы достигли успеха в наших исследованиях. В конце концов, любую армию можно остановить, если натравить ее рядовых солдат друг на друга.$B$BСкоро я доложу о наших успехах в Лагерь Возмездия. Но сначала мы должны замести следы.$B$BПопроси Дженни по прозвищу \"Пила\" сделать тебе базовое поганище. Пусть только она добавит в него побольше взрывчатки – если ты понимаешь, к чему я клоню.', 'Поговорите с Дженни по прозвищу \"Пила\" в Новом Агамонде.', 'Что тебе нужно? Не видишь – я очень занята!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11309, 'Запчасти для Дженни', 'А, Харрис хочет что-то взорвать? Да, тогда он обратился по адресу. $B$BПравда, тебе придется достать мне кое-какие запчасти. Я не хочу тратить собственные запасы на штуку, подлежащую уничтожению. $B$BПрежде всего, мне понадобятся жилы черпорога... они гораздо прочнее человеческих.$B$BЕще нужно свежее мясо. Есть тут один парень – Антон – он продает дешевое мясо. Найти его легко: он часто ходит по западной дороге.', 'Принесите 6 жил черпорога и 1 килограмм свежего мяса Дженни по прозвищу \"Пила\" в Новый Агаманд.', 'Да, это вполне сгодится. Молодец!', 'Ты достал то, что я просила?', NULL, NULL, 'Жила черпорога', 'Килограмм свежего мяса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11310, 'Внимание: требуется сборка', 'А, вот ты где! Наш дружок получился немного... непредсказуемым. Я бы тебе порекомендовала собрать его на месте, в Халгринде.$B$BКак только доберешься туда, отправь поганище в толпу врайкулов, чтобы он уничтожил как можно больше этих тварей.$B$BКогда все закончится, подбери останки и принеси их сюда. Запчасти мне всегда пригодятся!', 'Воспользуйтесь набором для сборки поганища в Халгринде и сгоните в одно место как минимум 20 зачумленных врайкулов. Взорвите их с помощью поганища, после чего вернитесь к Дженни по прозвищу \"Пила\" в Новый Агамонд.', 'Отличная работа, $N. Слушай, а тебе не хотелось бы создать нечто менее... взрывоопасное? Мне пригодилась бы твоя помощь по сбору запчастей!', 'Ну что, зачистка в Халгринде закончена?', NULL, NULL, 'Уничтожено зачумленных врайкулов', 'Набор для создания поганища', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11311, 'Сопротивляясь стихиям', 'Если хочешь выжить в этом месте – научись приспосабливаться к изменениям, как это сделали мы. Количество элементалей в северных предгорьях неуклонно возрастает, что только подтверждает тот факт, что любая стихия может стать смертоносной, если мы не будем достаточно бдительны, чтобы предотвратить угрозу.$B$BПеред тем как покинуть это место, мы должны в последний раз сократить численность элементалей. Не хочешь ли ты помочь нам, пока мы завершаем подготовку к походу?$B$BУбивай всех осколочных ледяных элементалей и завывающих циклонов, которые встретятся тебе на снежных предгорьях, окружающих аванпост.', 'Укротитель ветра Каган из Лагеря Заиндевевшего Копыта просит вас убить 8 горных элементалей. Уничтожайте завывающих циклонов или осколочных ледяных элементалей.', 'Влияние стихий уменьшилось, но элементали еще вернутся. К счастью, мы успели выиграть время для приготовлений к уходу.', NULL, NULL, NULL, 'Убито горных элементалей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11312, 'Заиндевевшая поляна', 'Многие поколения среди нашего народа ходили легенды о ледяных нимфах, прячущихся далеко в заснеженных чащах. Как-то ребенком я отправилась на их поиски вопреки запретам родителей, а в итоге едва не замерзла до смерти.$B$BИ вот настали дни, когда нам больше не надо прочесывать леса в поисках этих чудесных созданий. По неведомым причинам они решили открыться нам, и мы обязаны узнать, чем вызвано их появление. Отправляйся на юго-восток, к заиндевевшей поляне, и поговори с ледяными нимфами. Но будь $gосторожен:осторожна: – по пути тебе придется миновать Холмистую поляну.', 'Поговорите с Луриэль на Заиндевевшей поляне.', '<Луриэль внимательно выслушивает вас.>$B$BПриятно познакомиться, $C. Мои сестры часто видели, как таунка искали нас в лесах, но наша королева запретила нам вступать в контакт с чужаками. Сегодня ты видишь нас только потому, что эти земли сильно изменились, и многие мои сестры ныне в опасности.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11313, 'Духи льда', 'Ледяные элементали, охраняющие эту поляну, были нашими союзниками, но некая жестокая и разрушительная сила пронеслась по этим землям, изменяя их сущность. Теперь они обратились против нас!$B$BЭта одна из многих бед постигнувших меня и моих сестер. Мы явились к вам в надежде, что вы сможете помочь нам остановить скверну, проникшую в наши леса и отравляющую моих сестер!$B$BМы собираем ядра ледяных элементалей и складываем в безопасное место в надежде, что когда-нибудь сможем их возродить. Ты нам поможешь?', 'Луриэль с Заиндевевшей поляны просит вас принести ей 15 ледяных ядер.', '<Луриэль бережно принимает ядра из ваших рук.>$B$BСпасибо, $N.$B$B<Луриэль печально смотрит на ледяные ядра.>$B$BОбещаю, друзья мои, я сделаю все возможное, чтобы возродить вас.', 'Ты принес хоть несколько ядер?', NULL, NULL, 'Ледяное ядро', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11314, 'Падшие сестры', 'К юго-западу отсюда есть поляна, которая некогда была очень похожа на эту. Но странные силы и чужеродная магия изменили эту землю. Поляна исказилась, а жившие на ней сестры сошли с ума, ибо были не в состоянии принять произошедшие перемены.$B$BМы пытались воззвать к ним, но они напали на моих подручных. Боюсь, многих из моих несчастных сестер уже не спасти, но я не теряю надежды.$B$BВозьми мою подвеску, отправляйся на юго-запад, к Светлой поляне, и попытайся с ее помощью освободить моих сестер.', 'Луриэль с Заиндевевшей поляны попросила вас воспользоваться ее подвеской, чтобы освободить 7 морозных нимф.', 'Значит, для моих сестер еще не все потеряно?$B$B<Луриэль отворачивается и печально смотрит вдаль.>$B$BЯ должна была сразу вспомнить про подвеску. Возможно, тогда мы могли бы спасти всех моих сестер.', NULL, NULL, NULL, 'Освобождено морозных нимф', 'Подвеска Луриэль', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11315, 'Дикие ветви', 'Сестры, жившие на Светлой поляне, что к юго-западу отсюда, любили проводить время в тени алого плюща, но та же сила, что свела их с ума, изменила и их возлюбленные цветы.$B$BОтныне ветви некогда мирных цветов хватают за ноги неосторожных путников и хлещут по лицу каждого, кто осмелится приблизиться к поляне. Если мы хотим исцелить эти земли, мы должны сначала усмирить и выкорчевать эти растения.$B$BУничтожь столько цветков алого плюща, сколько сможешь. Увы, у нас больше нет над ними власти.', 'Луриэль с Заиндевевшей поляны попросила вас уничтожить 8 цветков алого плюща.', 'Спасибо тебе за помощь, $N. Светлая поляна была прекрасным местом, и я надеюсь возродить ее, когда мы сможем туда вернуться.', NULL, NULL, NULL, 'Алый плющ убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11316, 'Порождения Холмистой поляны', 'Некогда чудесная поляна на западе превратилась в ужасное место, которое прозвали Холмистой поляной. Там, среди деревьев, камней и озер бродят чудовищные звери.$B$BЯ не могу даже представить себе, откуда взялись эти существа и какая омерзительная магия вдохнула в них жизнь, но мы должны что-то сделать с этими тварями!$B$BБоюсь, что если мы и дальше позволим им бродить по поляне, они отравят землю настолько, что мы уже не сможем ее возродить. Очисти поляну от существ, погубивших наших сестер.', 'Луриэль с Заиндевевшей поляны просит вас убить 10 терноплющей.', 'Ты хорошо потрудился, $N. Если бы у нас с самого начала были такие союзники, как ты, мы бы смогли уберечь от скверны гораздо больше земель, которые ныне для нас потеряны.', NULL, NULL, NULL, 'Терноплющ убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11317, 'Очищение', 'Мы отправились в Вырубки потому, что мне было видение про моего друга, ворга по имени Улклык. Он звал на помощь, и потому ты $gдолжен:должна: его найти.$B$BК сожалению, ты не можешь ходить среди воргов и общаться с ними, но я могу тебя научить.$B$BСначала тебе придется изгнать свое внутреннее смятение путем медитации. $B$BДалеко на северо-востоке, на Вершине Ледяного Клинка есть святилище. К нему ведет единственная тропинка, начинающаяся от западного подножия горы.$B$BОтправляйся туда, очисти свой дух и возвращайся ко мне.', 'Ведун Странник Туманов у Стальных ворот посоветовал вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка.', 'Я чувствую произошедшие в тебе перемены.$B$BГотов ли ты сделать следующий шаг?', NULL, NULL, NULL, 'Внутреннее смятение изгнано', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11318, 'А теперь гонки на баранах... Или вроде того.', 'Хочешь попробовать себя в роли наездника на баране? Надеюсь, ты любитель быстрой езды. Но. Прежде чем допустить тебя к соревнованиям, покажи, что справишься с нашими скакунами.$B$BВот, что я предлагаю: возьми скакового барана и поводья и покажи, что умеешь ездить верхом.$B$BПусти барана рысью на 8 секунд, потом легким галопом и галопом. Если ты не знаешь, как управляться с баранами, обратись к моему ученику, Полу Янтарлену.', 'У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.', 'Неплохо, неплохо! Не так-то просто справиться с бараном. Но как уж научишься им управлять, сразу захочешь, чтобы все бараны были верховыми.$B$BЧто-что? Где твоя награда? Ха-ха-ха! Тебе разрешили покататься на самом быстром баране в округе! Мало? Тогда так...$B$BТебе выпал шанс помочь другим участникам Хмельного фестиваля. Молодому наезднику на баранах хватит и работы, и наград.', NULL, NULL, NULL, 'Промчитесь рысью 8 секунд', 'Промчитесь легким галопом 8 секунд', 'Промчитесь галопом 8 секунд', 'Поводья скаковых баранов');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11319, 'Семена негодующих хранителей', 'Раньше на Холмистой поляне, к западу отсюда, обитали хранители рощи. Вместе с сестрами они ухаживали за ее обитателями.$B$BКогда поляна изменилась, все сестры погибли, но хранителям каким-то образом удалось выжить. Однако теперь они засеивают землю ядовитыми растениями, которые губят здоровые ростки.$B$BПриближаться к этим спорам опасно, но я дам тебе ядро одного из ледяных элементалей. Как только уничтожишь спору, заморозь ее с помощью кристалла, чтобы она больше не ожила.', 'Луриэль с Заиндевевшей поляны поручила вам заморозить 8 спор.', 'Ледяное ядро сработало? Хорошо. Боюсь, мне еще не раз придется его применить. Я уверена, что хранители не остановятся и будут продолжать засеивать поляну.', NULL, NULL, NULL, 'Заморожено спор', 'Зачарованное сердце льда', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11321, 'Кто сказал \"сувениры\"?', 'Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.$B$BВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.', 'Найдите в лагере Хмельного фестиваля Белби Быстросмен, отдайте ей купон и получите бесплатную праздничную пивную кружку.', '', NULL, NULL, NULL, 'Купон на получение кружки Хмельного фестиваля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11322, 'Очищение', 'Недавно мне приснился кошмарный сон про ворга по имени Улклык. Он звал меня на помощь! $N, ты $gдолжен:должна: его найти.$B$BК сожалению, ты не можешь ходить среди воргов и общаться с ними, но я могу тебя научить.$B$BСначала тебе придется изгнать свое внутреннее смятение путем медитации. $B$BДалеко на северо-востоке, на Вершине Ледяного Клинка есть святилище. К нему ведет единственная тропинка, начинающаяся от западного подножия горы.$B$BОтправляйся туда на медитацию, очисти свой дух и возвращайся ко мне.', 'Дозорная Лунный Лепесток у Стальных ворот посоветовала вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка.', 'Я чувствую произошедшие в тебе перемены.$B$BГотов ли ты сделать следующий шаг?', NULL, NULL, NULL, 'Внутреннее смятение изгнано', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11323, 'В обличье ворга', 'Во сне я видел Улклыка в пещере на заснеженном краю Вырубок, где-то на северо-западе.$B$BЕму грозит страшная опасность!$B$BЯ сделал магическую личину, которая сделает тебя $gпохожим:похожей: на ворга. Это очень нестабильная личина, которая действует только в пределах Вырубок. Однако с ее помощью ты сможешь обмануть воргов и добраться до Улклыка.$B$BПрошу тебя, $C, отыщи Улклыка и помоги ему.', 'Ведун Странник Туманов попросил вас найти Улклыка в Вырубках и помочь ему.Если вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.', 'Ты как-то странно выглядишь, и запах у тебя необычный... ты не из моей стаи. Расскажи, что привело тебя сюда. Все равно мне больше нечем заняться, пока я заперт в этом месте.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11324, 'Альфа-ворг', 'Теперь, когда ты $gсъел:съела: глаза Когтекрыла, ты сможешь увидеть Гарвала и вырвать его глотку!$B$BДитя |3-1($gраса:), разыщи Гарвала в западных Вырубках и убей его. Когда он умрет, вернись к ведуну Страннику Туманов и сообщи ему, что я снова стал вожаком стаи воргов!', 'Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга ведуну Страннику Туманов в Стальные ворота.', 'Гарвал был не воргом! Судя по твоему рассказу, эта тварь больше похожа на воргена!$B$BНо Улклык вроде бы упоминал, что Гарвал пришел на юг из Седых холмов? Как странно. Воргены не водятся в тех местах...$B$BКак бы то ни было, я благодарю тебя за то, что ты помогла Улклыку занять подобающее ему место в стае. Теперь мы оба можем спать спокойно. $B$BПожалуйста, не откажись принять этот дар в знак благодарности.', '$N! Какие новости об Улклыке?', NULL, NULL, 'Гарвал убито', 'Личина ворга', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11325, 'В обличье ворга', 'Во сне я видела Улклыка в пещере на заснеженном краю Вырубок, где-то на северо-западе.$B$BЕму грозит страшная опасность!$B$BЯ сделала магическую личину, которая сделает тебя $gпохожим:похожей: на ворга. Это очень нестабильная личина, которая действует только в пределах Вырубок. Однако с ее помощью ты сможешь обмануть воргов и добраться до Улклыка.$B$BПрошу тебя, $C, отыщи Улклыка и помоги ему.', 'Дозорная Лунный Лепесток попросила вас найти Улклыка в Вырубках и помочь ему.Если вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она даст вам новую.', 'Ты как-то странно выглядишь, и запах у тебя необычный... ты не из моей стаи. Расскажи, что привело тебя сюда. Все равно мне больше нечем заняться, пока я заперт в этом месте.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11326, 'Альфа-ворг', 'Теперь, когда ты $gсъел:съела: глаза Когтекрыла, ты сможешь увидеть Гарвала и вырвать его глотку!$B$BДитя |3-1($gраса:), разыщи Гарвала в западных Вырубках и убей его. Когда он умрет, вернись к Луннолисту и сообщи ей, что я снова стал вожаком стаи воргов!', 'Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга дозорной Лунный Лепесток в Стальные ворота.', 'Гарвал был не воргом! Судя по твоему рассказу, эта тварь больше похожа на воргена!$B$BНо Улклык вроде бы упоминал, что Гарвал пришел на юг из Седых холмов? Как странно. Воргены не водятся в тех местах...$B$BКак бы то ни было, я благодарю тебя за то, что ты помог Улклыку занять подобающее ему место в стае. Теперь мы оба можем спать спокойно. $B$BПожалуйста, не откажись принять этот дар в знак благодарности.', '$N! Какие новости об Улклыке?', NULL, NULL, 'Гарвал убито', 'Личина ворга', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11327, 'Задание: найти сверток', 'Ох, как же нам нужны образцы этой чумы!$B$BА, придумал!$B$BПока ты $gуничтожал:уничтожала: резервуары, я проследил из одним из аптекарей из Нового Агамонда. Его утащили в Халгринд местные врайкулы. И поделом.$B$B$N, я могу поспорить, что у него были с собой какие-то вещи. Может быть, тебе стоит отправиться в Халгринд и достать его пожитки?', 'Разведчик Ноулс просит вас найти сверток аптекаря в Халгринде. Принесите его разведчику в Тлеющую башню.', 'Великий свет... это еще что?! Ты только посмотри!$B$BНам надо как можно скорее доставить этот сверток в крепость!', 'Какое ужасное место! Даже врайкулы не заслуживают страшной гибели от рук Королевского фармацевтического сообщества.$B$BХорошо, что здесь я в безопасности. Кстати, ты уже отыскал сверток?', NULL, NULL, 'Сверток аптекаря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11328, 'Задание: чума Отрекшихся', 'Так вот; отнеси эту штуку обратно в крепость и отдай Пеппи Нетосопло. Она, конечно, не самый лучший алхимик, но другого у нас нет.$B$BТолько учти – она очень любит выпить, так что для начала загляни в таверну.$B$BВ общем, она знает, что делать с этой штукой.', 'Разведчик Ноулс просит вас отнести сверток аптекаря Пеппи Нетосопло в Крепость Западной Стражи.', 'А... это же совершенно меняет дело!$B$BЛадно, дай-ка взглянуть... Обожаю все эти алхимические штучки!$B$BНу-ка, ну-ка... Ага, знаю! Надо всего лишь смешать эту фигню вот с этой бурдой в равных пропорциях.$B$BИ, пожалуй, не будет лишним добавить кусочек гнилых внутренностей... ик!', 'Эй, чего надо...ик?', NULL, NULL, 'Сверток аптекаря (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11329, 'Я готов на все!', 'Как же мне надоели эти бочки с засоленной рыбой! Я набиваю их целыми днями, а работы еще непочатый край!$B$BАх, если бы только у меня осталась эта приманка Ната Пэгла! Вот уж действительно чудесная штука. Теперь же я радуюсь, если удается поймать за час хотя бы одну рыбку. $B$BСлышал я, что из северной рыбы-шипа получается неплохая приманка, но кто же в здравом уме полезет в ледяную воду и будет бултыхаться среди водорослей в поисках этой пронырливой рыбки? Не я, это точно... разве что тебя удастся уговорить...', 'Принесите Кристоферу Слоану из крепости Вилдервар 5 северных рыб-шипов.', 'Фу, какие мерзкие твари! Ладно, неважно, как они выглядят – лишь бы на них кто-нибудь клюнул. Скорее бы экспедиция убралась отсюда. Тогда я смогу рыбачить для собственного удовольствия.', 'Ты смотри – кажется, рыбки тебя не сильно покусали. Наживку-то принес?', NULL, NULL, 'Северная рыба-шип', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11330, 'Это... точно сработает!', 'Ага, вакцина от чумы готова.$B$BПравда, я не собираюсь испытывать ее на себе. Могу предположить, что ты тоже не горишь желанием стать подопытным кроликом?$B$BО, точно!$B$BУ нас же есть врайкульский пленник в темнице под крепостью! Давай-ка ты отнесешь ему эту мешанину и заставишь его выпить...ик, до дна?', 'Пеппи Нетосопло предложила вам отнести ее особую смесь врайкулу-узнику из клана Укротителей драконов. Когда он выпьет смесь, вернитесь в Крепость Западной Стражи и расскажите Пеппи о результатах эксперимента.', 'Что? Ой, как все плохо... Хотела как лучше, а получилось как всегда. Выходит, я даже усовершенствовала чуму...ик!$B$B<Пеппи морщится и в очередной раз прикладывается к бутылке.>$B$BЭх, я надеялась, что до этого дело не дойдет, но теперь...ик! – у нас нет выхода.', NULL, NULL, NULL, 'Смесь Пеппи доставлена врайкульскому пленнику', 'Особая смесь Пеппи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11331, 'Ик... Ты ему и скажи!', 'Короче, так. Я не собираюсь идти к капитану с такими новостями! В мои обязанности это не входит, и вообще, у меня перерыв. $B$BОн же такая злюка... да ты не хуже меня его знаешь!$B$BВ общем, топай в крепость $gсам:сама:. Я уверена, он тебя выслушает, и все такое... ик! $B$B<Пеппи снова прикладывается к бутылке.:', 'Пеппи Нетосопло уговорила вас сообщить плохие новости о новой чуме Отрекшихся капитану Адамсу. Его можно найти в Крепости Западной Стражи.', 'Да, $N, что еще ты хочешь мне доложить?$B$BЧТО?! Отрекшиеся создали чуму, которая может в считанные мгновения превратить человека в лужу? И ты расплавил моего пленного врайкула?$B$B<Капитан огорченно смотрит по сторонам и презрительно сплевывает на пол.>$B$BНу, ладно. Я знаю, что нам делать. Точнее, не нам, а ТЕБЕ!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11332, 'Задание: уничтожить чуму!', 'В Королевском фармацевтическом обществе собираются запустить новую чуму, которая может расплавить человека на месте?!$B$BТолько не во время моего дежурства!$B$BОтправляйся во внутренний двор и поговори с Гриром Рудомолотом. Он должен был уже приготовить для тебя грифона и несколько бомб. Я хочу, чтобы ты $gразнес:разнесла: в щепки резервуары с чумой в Новом Агамонде.', 'Капитан Адамс приказал вам сбросить 5 бомб на резервуары с чумой в Новом Агамонде. Вернитесь к нему в Крепость Западной Стражи, когда это поручение будет выполнено.', 'Молодец, $N, отличная работа!$B$B<Капитан чуть ли не пляшет от радости.>$B$BТеперь эти жалкие Отрекшиеся поймут, что с нами не стоит связываться!$B$BПожалуй, ты заслужил награду из нашей сокровищницы!', NULL, NULL, NULL, 'Поражено контейнеров с чумой', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11333, 'В мир духов', 'Пока Лига исследователей копается в земле в поисках осколков прошлого, а вице-адмирал пытается постигнуть суть настоящего путем грубой силы, истина скрывается от нас среди призраков.$B$BС помощью особых реагентов я могу заглянуть в мир духов, где мне откроется прошлое, настоящее и будущее Нордскола.$B$BЕсли хочешь узнать больше, принеси мне мой мешочек с реагентами. Я потерял его на корабле, который ныне покоится на дне Бухты Кинжалов, к востоку отсюда.', 'Торалиус Мудрый в Валгарде просит вас найти его мешочек с реагентами.', 'Мда, носить ее уже не придется, но содержимое в целости и сохранности.$B$B<Торалиус запускает руку в сумку и достает несколько причудливых корешков.>$B$BА теперь надо бросить их в огонь и вдохнуть дым!$B$B<Торалиус кладет корешки в тлеющую жаровню.>$B$B<Он глубоко вдыхает, и тело его начинает корчиться в судорогах.>$B$BЧто...Что такое... Не может... Я не могу...', 'Где мой мешочек с реагентами?', NULL, NULL, 'Мешочек с реагентами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11335, 'Призыв к оружию: низина Арати', 'Беда битвы на несколько фронтов, $gпарень:подруга:, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление.Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $N, и принеси нам победу. Мы не можем позволить Ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!', 'Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Прекрасная новость, $C! Если наши тактические действия будут и впредь столь же успешны, Орде очень скоро придется отступать по всем фронтам!', NULL, NULL, NULL, 'Победа в Низине Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11336, 'Призыв к оружию: Альтеракская долина', 'Беда битвы на несколько фронтов, $gпарень:подруга:, в том, что приходится растягивать силы, в результате мы рискуем потерять все!$B$BДень ото дня все необходимее подкрепление. Сегодня войскам в Альтеракской долине требуются отважные бойцы.$B$BСтупай прямо сейчас, $N, и помоги экспедиции клана Грозовой Вершины. Мы не можем допустить, чтобы клан Северного Волка ушел без возмездия после всего того зла, что они причинили нашим собратьям!', 'Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Это мне и хотелось улышать! Победа в Альтеракской долине - пусть и временная - необходимое звено в нашей общей стратегии войны с Ордой.', NULL, NULL, NULL, 'Победа в Альтеракской долине', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11337, 'Призыв к оружию: Око Бури', 'Война с Ордой не ведает границ, $N. Даже в Запределье застарелая ненависть и территориальные претензии вынуждают нас воевать.$B$BИди в Око Бури и измени равновесие в Запределье в пользу Альянса, как в Азероте.', 'Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Мы на шаг приблизились к полной победе над Ордой! Мы не можем позволить врагу завоевать плацдарм ни в этом мире, ни в каком другом!', 'Поведай мне, $N, что за вести несешь ты с передовой?', NULL, NULL, 'Победа на поле боя Ока Бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11338, 'Призыв к оружию: ущелье Песни Войны', 'Среброкрылые часовые защищают лес в ущелье Песни Войны. Мы помогаем им не из любви к деревьям, а потому, что этот лес является природным защитным барьером вокруг территории Альянса.$B$BСегодня им как никогда нужна помощь. Нам нужно подкрепление прямо сейчас, иначе Ясеневый лес постигнет судьба Степей!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Славная работа, $N. Мы должны любой ценой обеспечить нерушимость наших границ!', 'Какие вести с фронта, $N?', NULL, NULL, 'Победа в ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11339, 'Призыв к оружию: низина Арати', 'Мы вот-вот отобъем Низину Арати у сил Альянса! Мы немедленно должны послать туда подкрепление, иначе все наши труды пойдут прахом.$B$BНе медли, $C, отправляйся в Низину Арати и сокруши врагов. Орда победит!', 'Победите на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Ты принес великую славу Орде, $N. Твоя победа сегодня принесет тысячу побед завтра!', NULL, NULL, NULL, 'Победа в игре на поле боя Низины Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11340, 'Призыв к оружию: Альтеракская долина', 'Мы почти изгнали врагов из клана Грозовой Вершины, что вторглись в Альтеракскую долину. Теперь надо перебросить наши силы на помощь клану Северного Волка.$B$BРешительная победа там высвободит ресурсы, необходимые для сокрушения этих подонков из Альянса на всех остальных фронтах.$B$BСтупай, $N. Заслужи великую честь, откликнувшись на зов отважных воинов клана Северного Волка.', 'Победите на поле боя Альтеракской долины и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Нет высшей чести, чем изгнать захватчиков с земель Орды! Мы ныне славим твою великую отвагу в помощи нашим войскам!', 'Ты вернулся! Надеюсь, с победной вестью?', NULL, NULL, 'Победа в игре на поле боя Альтеракской долины', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11341, 'Призыв к оружию: Око Бури', 'Мы сражаемся с врагами везде, где только встретим - в Азероте, в Запределье, повсюду.$B$BМы не можем позволить Альянсу одолеть нас в Оке Бури! Ступай биться с ними сегодня... Завтра будет поздно!', 'Победите в игре на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Ты принес славу всем нам, $N. Мы должны показать врагу, что будем сражаться с ними везде и всегда!', 'Ты вернулся! Надеюсь, с победной вестью?', NULL, NULL, 'Победа в игре на поле боя Ока Бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11342, 'Призыв к оружию: ущелье Песни Войны', 'Альянс – коварный враг, $N. Они говорят, что защищают Ясеневый лес, дабы оправдать свою агрессию против наших территорий в Степях.$B$BНынче у нас есть возможность вытеснить врага с наших земель раз и навсегда! Отправляйся в ущелье Песни Войны и верни то, что наше по праву!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Орда в долгу перед тобой, Деретник. Твой народ гордится твоей отвагой на защите наших земель.', NULL, NULL, NULL, 'Победа в ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11343, 'Эхо Имирона', 'Мир духов пал под натиском Короля-лича. Ужасные существа, порождения кошмаров, ныне сторожат владения стихий. Я чувствую, что эти валь\'киры охраняют страшную тайну.$B$BЯ слишком стар и слаб, чтобы пережить еще одно путешествие, поэтому ты, $N, отправишься вместо меня.$B$BВозьми эту курительницу и отправляйся в Деревню Драконьего Черепа. Зажги ее, чтобы проникнуть в мир духов, и обыщи все здания в деревне на северо-востоке. Но будь $gосторожен:осторожна: – валь\'киры могут навсегда оставить тебя в своем мире!', 'Торалиус Мудрый просит вас обыскать Деревню Драконьего Черепа в мире духов и найти информацию о тайнах Ниффлвара.', 'Не понимаю. Говоришь, эти существа были похожи на врайкулов, которые нападают на Валгард?', NULL, NULL, NULL, 'Разгадать тайну Деревни Драконьего Черепа', 'Курильница', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11344, 'Страдания Ниффлвара', 'Наши скромные познания о врайкулах позволяют сделать вывод, что они лишь недавно появились в Нордсколе. Почему же тогда мы видим их в пророчествах, сделанных 15,000 лет назад? Если бы врайкулы раньше обитали на этом континенте, мы бы об этом знали.$B$BТебе надо продолжить работу в Ниффлваре. Чтобы добраться туда, иди на северо-восток, через Деревню Драконьего Черепа, после чего сверни на дорогу, идущую через дамбу. Ниффлвар расположен на одном из обрывов фьорда. $B$BКак только прибудешь туда, зажги курительницу и осмотри все вокруг в поисках важной информации.', 'Торалиус Мудрый поручил вам осмотреть Ниффлвар из мира духов и найти информацию о тайнах Ниффлвара.', 'От врайкулов рождались человеческие дети? И Имирон приказал убить всех полукровок?$B$B<На мгновение Торалиус умолкает.>$B$BУвы, бессмысленно отрицать очевидное. Нет никакого \"утерянного звена\", ведущего к возникновению человека. Лига исследователей ошибалась – врайкулы и есть то самое недостающее звено. Они – прародители человечества.', NULL, NULL, NULL, 'Разгадать тайну Ниффлвара', 'Курильница', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11346, 'Книга Рун', 'Железные дворфы захватили Тропу великанов – огромное, каменистое плато на юго-востоке. Мои разведчики доложили, что видели дворфов, откапывающих каменных великанов из-под земли и вырезающих на них руны.$B$BЯ не могу постигнуть их замыслы, но смею предположить, что они пытаются превратить этих великанов в оружие. Говорят, что призыватели камня и связыватели из клана Железной Руны носят с собой толстые книги с рунами, которые они вычерчивают на телах великанов. $B$BСобери несколько отрывков из этих томов, сложи их вместе и принеси мне.', 'Геолог Белвар из крепости Вилдервар просит вас найти Книгу Рун.', '<Геолог Белвар листает книгу Рун.>$B$BОго... здесь так много информации. Мне потребуется время, чтобы изучить эту книгу. Если мы постигнем смысл этих рун, то сможем воспользоваться ими в своих целях.', 'Ты достал книгу?', NULL, NULL, 'Книга Рун', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11348, 'Руна подчинения', 'Чувствуешь силу, исходящую от рун, которые я вырезал на этой табличке? Это всего лишь уменьшенная версия тех символов, что используют железные дворфы. Мы же обернем эти руны против них самих. $B$BОтнеси эту табличку на Тропу Великанов и используй на каменном великане, которого еще не успели изменить дворфы. $B$BВеликан будет подчиняться тебе, но недолго. Видишь ли, я вырезал такую руну, которая со временем позволит ему стать самим собой. Пока же этот великан может стать ценным союзником в борьбе против Мурдиса, предводителя железных дворфов.', 'Геолог Белвар из крепости Вилдервар просит вас испытать руну подчинения и сразиться с Мурдисом-обуздателем.', 'Ты совершил великое дело, победив Мурдиса-обуздателя, но железные дворфы так просто не сдадутся. $B$BПо пути на север мы еще не раз столкнемся с этими существами. Но в следующий раз мы будем готовы дать им отпор.', NULL, NULL, NULL, 'Руна подчинения испытана', 'Мурдис-обуздатель убито', 'Руна подчинения', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11349, 'Освоение рун', 'У меня есть с собой несколько молотков, отверток и рубильников, но обычные орудия не подходят для вырезания этих рун. Железные дворфы используют зачарованные инструменты. $B$BКаждый раз, когда они вырезают очередную руну с помощью этих инструментов, они придают словам новое, магическое значение. С помощью таких рун можно привязать к себе, изменить и подчинить любое существо. $B$BЕсли бы мне удалось получить набор магических инструментов, я бы смог вырезать руны, изображенные в книге. Поищи их возле палаток дворфов на Тропе Великанов.', 'Принесите геологу Белвару из крепости Вилдервар резной инструмент, который используют дворфы клана Железной Руны.', '<Белвар бережно берет инструменты.>$B$BЯ попробую ими воспользоваться. Если мы хотим понять логику действий Железных дворфов и победить их, мы должны знать, какое воздействие оказывают эти руны.', 'Неужели ты несешь мне инструменты?', NULL, NULL, 'Резной инструмент дворфов Железной Руны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11350, 'Книга Рун', 'Вождь Прахтотем отправил меня на разведку к Тропе Великанов. Это широкое, каменистое плато к юго-востоку отсюда, сразу за Заиндевевшей поляной.$B$BЭтот район захватили Железные дворфы, которые, похоже, каким-то образом изменяют великанов, появляющихся из-под земли. $B$BПризыватели камня и связыватели из клана Железной Руны носят с собой толстые книги с рунами, которые они вычерчивают на телах великанов. $B$BСобери несколько отрывков из этих томов, сложи их вместе и принеси мне. Тогда у нас появится шанс постигнуть их замыслы.', 'Выносливый гонец Пембе из Лагеря Заиндевевшего Копыта просит вас принести ему Книгу Рун.', '<Выносливый гонец листает принесенную вами книгу.>$B$BЯ не мудрец, но немного знаком с языком Железных дворфов. Кажется, эти руны, которые они вырезают на телах великанов, как-то связаны с их наречием, но различия слишком велики.', 'Ты достал книгу?', NULL, NULL, 'Книга Рун', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11351, 'Освоение рун', 'Кажется, я догадался, что делают Железные дворфы. Они используют зачарованные инструменты. $B$BКаждый раз, когда они вырезают очередную руну с помощью этих инструментов, они придают словам новое, магическое значение. С помощью таких рун можно привязать к себе, изменить и подчинить любое существо. $B$BЕсли бы мне удалось раздобыть набор магических инструментов, я бы смог вырезать руны, изображенные в книге. Мне удалось украсть ящик из палатки на Тропе Великанов, но он оказался пуст. Попробуй найти похожий ящик и принеси мне хранящийся в нем набор инструментов.', 'Принесите выносливому гонцу Пембе из Лагеря Заиндевевшего Копыта резной инструмент, который используют дворфы клана Железной Руны.', '<Пембе изучает инструменты.>$B$BКакие изящные орудия труда! Подожди немного, я хочу их испытать.', 'Неужели ты несешь мне инструменты?', NULL, NULL, 'Резной инструмент дворфов Железной Руны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11352, 'Руна подчинения', 'Чувствуешь силу, исходящую от рун, которые я вырезал на этой табличке? Это всего лишь уменьшенная версия тех символов, что используют железные дворфы. Мы же обернем эти руны против них самих. $B$BОтнеси эту табличку на Тропу Великанов и используй на каменном великане, которого еще не успели изменить дворфы. $B$BВеликан будет подчиняться тебе, но недолго. Видишь ли, я вырезал такую руну, которая со временем позволит ему стать самим собой. Пока же этот великан может стать ценным союзником в борьбе против Мурдиса, предводителя железных дворфов.', 'Выносливый гонец Пембе из Лагеря Заиндевевшего Копыта просит вас испытать руну подчинения и сразиться со Мурдисом-обуздателем.', 'Ты совершил великий подвиг, победив Мурдиса, но Железные дворфы так просто не сдадутся. $B$BПо пути на север мы еще не раз столкнемся с этими существами. Но в следующий раз мы будем готовы дать им отпор.', 'Ты испытал руну?', NULL, NULL, 'Руна подчинения испытана', 'Мурдис-обуздатель убито', 'Руна подчинения', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11354, 'Разыскивается: Ездовой хлыстик Назана', 'Мой нынешний заказчик интересуется одной штучкой, которую хранит верховое животное глашатая Иллидана. Естественно, я имею в виду Вазрудена Глашатая и его дракона Назана.$B$BЕсли хочешь получить награду, назначенную мной за этот предмет – ищи его над бастионами цитадели Адского Пламени и принеси мне хлыстик для верхового дракона.$B$BМои осведомители сообщают, что искомый предмет хранится лично у дракона. Говорят, что Назан не позволяет Вазрудену погонять себя им.', 'Торговец ветром Зарим просит вас добыть ездовой хлыст Назана. Доставьте его ему в Нижний город Шаттрата и получите награду.Это задание выполняется только в героическом режиме.', 'Значит, еще один клиент вскоре будет удовлетворен. А вы будете вознаграждены.$B$BПриходите поутру, и я подберу вам новое дельце.', 'Прошу предъявить ездовой хлыст.', NULL, NULL, 'Ездовой хлыст Назана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11355, 'Марш великанов', 'К востоку отсюда, на Тропе Великанов, были замечены изрисованные рунами каменные великаны, бредущие на север к Вершине Ледяного Клинка. Увы, я точно не знаю, куда они стремятся.$B$BОчевидно, мерцающие руны, вырезанные на каменной плоти, управляют их движением.$B$BВоспользуйся этой киркой, чтобы отключить руны на теле великанов, и сообщи мне все, что тебе удастся узнать.', 'Ученый Адеран из крепости Вилдервар попросил вас использовать кирку поиска рун на трупах 4 рунических каменных великанов.', '<Ученый Адеран внимательно слушает рассказ о ваших находках.>$B$BЗначит, руны со значением \"север\" и \"запад\" повторялись несколько раз? Это похоже на явный приказ двигаться в том направлении, но не только эти руны приводят их в движение. Что-то притягивает к себе великанов, но что именно?', NULL, NULL, NULL, 'Изучено трупов рунического каменного великана', 'Кирка поиска рун', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11356, 'Переодетая попечительница сирот', 'Во время Тыквовина сиротские приюты людей организуют для сироток поездки по деревням Альянса. Этим бедным детишкам так приятно будет увидеть $gнастоящего:настоящую:c: |3-3($C) вроде вас!$B$BПочему бы тебе не сходить к ним? Сироток ты найдешь в Златоземье, что в Элвиннском лесу, в Караносе, что в Дун Мороге, и на Лазурной заставе на острове Лазурной Дымки. Поговори с переодетой попечительницей сирот, и она тебя им представит.', 'Поговорите с переодетой попечительницей сирот в Златоземье, Караносе или на Лазурной заставе.', 'Вы пришли к детишкам! Замечательно! Они столько горя испытали за свою недолгую жизнь... Хорошо, что они посмотрят на настоящих героев, вроде вас. Это так поднимет их дух!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11357, 'Попечительница сирот в маске', 'В Тыквовин орчат-сироток возят с экскурсией по разным поселениям Орды. Попечительницы сирот считают, что детишкам хорошо бы посмотреть на настоящих героев, совершающих подвиги.$B$BПочему бы вам не навестить их? $gТакой отважный:такая отважная:c: $C может воодушевить их рассказами о своей доблести! Отправляйтесь в Колючий Холм в Дуротаре, Брилл в Тирисфальских лесах или на площадь Соколиных Крыльев в лесах Вечной Песни. Поговорите с попечительницей сирот в маске, и она представит вас детишкам.', 'Поговорите с попечительницей сирот в маске в Колючем Холме, Брилле или на площади Соколиных Крыльев.', 'Детям нравится наблюдать за героями в деле. Надеюсь, что однажды эти сиротки станут сильными воителями Орды и погибнут в славной битве!$B$BАх, у меня все в глазах плывет от одной мысли о столь блистательной кончине...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11358, 'Магнит', 'Надо узнать, почему великаны стремятся на северо-запад. Только так мы сможем остановить их до того, как они достигнут места назначения. $B$BХотя образцы рун дали мне пищу для размышлений, меня больше беспокоят эти неизвестные символы. $B$BОднажды, когда я бродил по Тропе Великанов, я заметил огро$Nю расколотую скрижаль, выступавшую из земли на северо-востоке области, там, где у подножия Вершины Ледяного Клинка появляется снег. Возьми этот образец и сравни руны с теми, что начертаны на скрижали. Посмотрим, что нам удастся узнать.', 'Ученый Адеран из крепости Вилдервар просит вас сравнить образцы рун с надписями на расколотой скрижали.', '<Адеран внимательно слушает описание вашей находки.>$B$BМегалит? Это же буквальный перевод надписи с таблички! Должно быть, все тайные замыслы железных дворфов основаны на этом Мегалите. Мы должны уничтожить его, прежде чем они примутся за воплощение своих планов!', NULL, NULL, NULL, 'Руны сравнены с надписями на разбитой скрижали', 'Рунический образец', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11359, 'Уничтожить Мегалита', 'Мурдис-обуздатель создал Мегалита, чтобы тот созвал рунных великанов и повел их за собой. Если мы победим Мегалита, то оставим великанов без их предводителя. Пока мы будем двигаться на север, я попрошу вождя Прахтотема выделить несколько воинов для уничтожения последних рунных великанов. Лишившись своих подручных, железные дворфы ничего не смогут нам противопоставить. $B$BОтправляйся к подножию Вершины Ледяного Клинка, разыщи Мегалита к северу от Тропы Великанов и уничтожь это создание!', 'Уничтожьте Мегалита и вернитесь к ученому Адерану в крепость Вилдервар.', 'Ты совершил подвиг, победив Мегалита, но меня крайне обеспокоили его последние слова. Ты уверен, что он упомянул Каменную Кузню?$B$BМне ничего не говорит это название, хотя по звучанию оно напоминает язык $Nв. Но при чем тут Железные дворфы? Надо найти эту Каменную Кузню до того, как наши враги смогут претворить в жизнь свои планы.', NULL, NULL, NULL, 'Мегалит убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11360, 'Учения пожарной бригады', 'Пока Всадник без головы еще угрожает нам, герои Златоземья всегда готовы сформировать пожарные бригады. Не хотите ли помочь?$B$BК северу отсюда стражники организовали небольшой полигон для учений пожарных бригад. Идите туда и носите ведрами воду, чтобы тушить пожар. Воду можно черпать ведром из этих бочек с водой.$B$BУдачи, $N. Когда поучаствуете в учениях пожарной бригады, возвращайтесь к нам!', 'Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.', 'Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!$B$BОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!', 'Здравствуйте, $N. Вы когда-нибудь совершенствовались в технике тушения пожаров? Не забывайте об учебном полигоне на севере!', NULL, NULL, 'Потушено пожаров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11361, 'Учения пожарной бригады', 'Рубаки устроили полигон для учений пожарной бригады около деревни. В нынешние времена дома Колючего Холма часто горят, так что помоги им и поупражняйся в тушении пожара!$B$BИди на запад от Колючего Холма, за стеной сразу сверни направо. Найди полигон, хватай ведро и туши учебный пожар!', 'Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Колючем Холме.', 'Славная работа, $N! Детишки, берите пример с этого $C. Растите сильными и отважными, как он и настанет день, когда вы тоже будете сражаться за Орду!', NULL, NULL, NULL, 'Потушено пожаров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11362, 'Разыскивается: Украшенный перьями посох Кели\'дана', 'О вкусах не спорят. Взять, например, моего последнего заказчика.$B$BВ цитадели Адского Пламени есть такой орк Скверны по имени Кели\'дан Разрушитель. У него есть совершенно простенький посох. Ну просто смотреть не на что. И все же моему клиенту нужен именно этот посох.$B$BКто я такой, чтобы отказывать?$B$BЕсли желаете получить компенсацию за труды, ищите его вместе с посохом в Кузне Крови.', 'Торговец ветром Зарим просит вас добыть украшенный перьями посох Кели\'дана. Принесите его ему в Нижний город Шаттрата и получите награду.Это задание выполняется только в героическом режиме.', 'Наверное, надо будет навязать на него новых перышек прежде, чем отдавать заказчику. Думаю, с таким количеством араккоа по соседству с перьями проблем не будет. Дело невеликое, и в любом случае ваша награда от этого меньше не станет.$B$BПриходите утром, и я вам новое дельце подберу.', 'Раз мы с вами снова беседуем... То посох у вас.', NULL, NULL, 'Украшенный перьями посох Кели\'дана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11363, 'Разыскивается: печать Острорука', 'Один мой очень богатый клиент сделал заказ на действительно уникальную вещь.$B$BВождь Каргат Острорук имеет личную печать, которой он заверяет официальные документы. Добудь ее для меня.$B$BТы найдешь Каргата в глубине Разрушенных залов. Тебе придется перебить немало орков, чтобы добраться до него, но ты справишься, я уверен.', 'Торговец ветром Зарим просит вас добыть печать Острорука. Принесите ее ему в Нижний город Шаттрата и получите награду.Это задание выполняется только в героическом режиме.', 'Воистину геройское деяние, достойное воспевания бардов! Вот, ты более чем заслужил эту награду.$B$BПриходи завтра – у меня найдется для тебя новое дельце.', 'Слышал я, что у вождя вместо на месте рук клинки... Это правда?', NULL, NULL, 'Печать Острорука', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11364, 'Разыскиваются: Центурионы клана Изувеченной Длани', 'А ты споришь с хозяином? Вот и Ма\'дуун тоже.$B$BМне нужна кровь центурионов из клана Изувеченной Длани. Ты найдешь их в Разрушенных залах цитадели Адского Пламени.$B$BХочешь получить награду – не возвращайся, пока всех их не перебьешь.', 'Ловчий Пустоты Ма\'дуун поручает вам убить 4 центурионов из клана Изувеченной Длани. Вернитесь к нему в Нижний город Шаттрата за наградой, как только перебьете их всех.', 'Очень хорошо. Ты заслужил свою награду.$B$BПриходи завтра, а ветер еще разок пошепчется с Ма\'дууном.', 'Ты вернулся. Все центурионы мертвы?', NULL, NULL, 'Центурион клана Изувеченной Длани убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11365, 'Марш великанов', 'К востоку отсюда, на Тропе Великанов, были замечены изрисованные рунами каменные великаны, бредущие на север к Вершине Ледяного Клинка. Увы, я точно не знаю, куда они стремятся.$B$BОчевидно, мерцающие руны, вырезанные на каменной плоти, управляют их движением.$B$BВоспользуйся этой киркой, чтобы отключить руны на теле великанов, и доложи мне все, что тебе удастся выяснить.', 'Ведун Эдан из Лагеря Заиндевевшего Копыта попросил вас использовать кирку поиска рун на трупах 4 рунных каменных великанов.', '<Ведун внимательно слушает рассказ о ваших находках.>$B$BЗначит, руны со значением \"север\" и \"запад\" повторялись несколько раз? Это похоже на явный приказ двигаться в том направлении, но не только эти руны приводят их в движение. Что-то притягивает к себе великанов, но что именно?', NULL, NULL, NULL, 'Изучено трупов рунного каменного великана', 'Кирка поиска рун', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11366, 'Магнит', 'Надо узнать, почему великаны стремятся на северо-запад. Только так мы сможем остановить их до того, как они достигнут места назначения. $B$BХотя образцы рун дали мне пищу для размышлений, меня больше беспокоят эти неизвестные символы. $B$BОднажды, гуляя по Тропе Великанов, я заметил огро$Nю расколотую скрижаль, выступавшую из земли на северо-востоке области, на границе со снегами Вершины Ледяного Клинка. Возьми этот образец и сравни руны с теми, что начертаны на скрижали. Посмотрим, что нам удастся узнать.', 'Ведун Эдан из Лагеря Заиндевевшего Копыта просит вас сравнить образцы рун с надписями на расколотой скрижали.', '<Эдан внимательно слушает описание вашей находки.>$B$BМегалит? Это же буквальный перевод надписи с таблички! Должно быть, все тайные замыслы железных дворфов основаны на этом Мегалите.', NULL, NULL, NULL, 'Руны сравнены с надписями на разбитой скрижали', 'Рунический образец', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11367, 'Уничтожить Мегалита', 'Мурдис-обуздатель создал Мегалита, чтобы тот призвал краеугольным камнем рунных великанов и повел их за собой. Если мы победим Мегалита, то оставим великанов без их предводителя. Пока мы будем двигаться на север, я попрошу вождя Прахтотема выделить несколько воинов для уничтожения последних рунический великанов. Лишившись своих подручных, Железные дворфы ничего не смогут нам противопоставить. $B$BОтправляйся к подножию Вершины Ледяного Клинка, разыщи Мегалита к северу от Тропы Великанов и уничтожь это создание!', 'Уничтожьте Мегалита и вернитесь к ведуну Эдану в Лагерь Заиндевевшего Копыта.', 'Ты совершила подвиг, победив Мегалита, но меня крайне обеспокоили его последние слова. Ты уверена, что он упомянул Каменную Кузню?$B$BИмя это не знакомо нашему народу, но по звучанию оно похоже на одно из творений \"$Nв\", о которых говорят чужеземцы. Железные дворфы всегда были коварными и опасными противниками, $N. Нам следует присматривать за великанами и найти эту Каменную Кузню до того, как наши враги смогут претворить в жизнь свои планы.', NULL, NULL, NULL, 'Мегалит убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11368, 'Разыскивается: сердце Квагмирран', 'У меня к тебе довольно необычная просьба, $N. Одна состоятельная госпожа, моя постоянная клиентка, желает приобрести довольно жуткий предмет.$B$BЭто сердце чудовища, именуемого Зыбуном.$B$BВообще-то, у твари три сердца, однако нам будет довольно одного. Полагаю, ты найдешь Зыбуна в глубоком пруду в Узилище.', 'Добудьте сердце Зыбуна и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение. Задание можно выполнить только в героическом режиме.', 'Какая жалость, что я не догадался попросить тебя принести заодно и два других сердца... Может, в следующий раз. В любом случае, ты честно заслужил обещанную награду. $B$BЗаходи завтра – у меня найдется для тебя работа.', 'Надеюсь, ты знаешь, как сохранить сердце при транспортировке?', NULL, NULL, 'Сердце Зыбуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11369, 'Разыскивается: яйцо Черной Охотницы', 'Это великая праматерь болотоходов в Зангартопи. Она носит имя Черная Охотница. Умирая, она откладывает яйцо, из которого появляется новая Черная Охотница.$B$BОдин из моих клиентов желает приобрести такое яйцо. Вроде бы, он собирается держать тварь в частном зоопарке.$B$BЕсли хочешь получить вознаграждение, отправляйся в Нижетопь, убей Черную Охотницу и принеси мне ее яйцо.', 'Добудьте яйцо Черной Охотницы и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение. Задание можно выполнить только в героическом режиме.', 'В нем пульсирует жизнь – разве это не удивительно? Я должен поторопиться доставить его покупателю, пока новая Черная Охотница не вылупилась прямо здесь! $B$BВот и твоя награда. $B$BЗаходи завтра – у меня найдется для тебя работа.', 'Что, неужто принес яйцо? Показывай скорее!', NULL, NULL, 'Яйцо Черной Охотницы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11370, 'Требуется: трактат полководца', 'Многим известно, что полководец Калитреш по праву считался величайшим воином среди наг. Однако немногие знают, что он изложил свой военный опыт в трактате.$B$BСреди моих клиентов есть один господин, великолепно разбирающийся в военной истории. Он желает приобрести этот трактат.$B$BПрошу тебя отправиться в Паровое подземелье в резервуар Кривого Клыка и найти для меня эту книгу.', 'Добудьте трактат полководца и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение. Задание можно выполнить только в героическом режиме.', 'Да, это действительно весьма, весьма богатая работа – хорошо бы мой клиент смог поднять этот талмуд, не говоря уж о том, чтобы успеть детально изучить его, прежде чем враги пойдут на него с войной. $B$BЗаходи завтра – у меня найдется для тебя работа.', 'Мой клиент уже нервничает. Я думаю, он хочет самолично опробовать тактические уловки Калитреша на своих недругах как можно скорее.', NULL, NULL, 'Трактат полководца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11371, 'Разыскиваются: Мирмидоны Резервуара Кривого Клыка', 'Я прошу твоей помощи.$B$BМне было поручено уничтожить наг-воинов из клана Кривого Клыка. Отыщи их в сырых уголках Парового подземелья в резервуаре Кривого Клыка.$B$BИмей в виду, требуется уничтожить всех до единого!', 'Ловчий Пустоты Ма\'дуун требует, чтобы вы убили 14 мирмидонов из резервуара Кривого Клыка. По исполнению задания возвращайтесь к Ма\'дууну в Нижний город Шаттрата за вознаграждением.', 'Надеюсь, ты не пожалел, что в это ввязался. Принимай заслуженную награду. $B$BВозвращайся завтра – возможно, ветра подскажут мне, какую тебе дать работу.', NULL, NULL, NULL, 'Мирмидон Резервуара Кривого Клыка убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11372, 'Разыскиваются: головные перья Айкисса', 'Недавно ко мне пришла тауренка, мужу которой предстоит стать вождем. Она хочет сделать особое украшение для его головного убора.$B$BДля этого ей нужны головные перья трусливого Короля воронов Айкисса.$B$BЕсли тебя интересует предложенная награда, отправляйся в Сетеккские залы в Аукиндоне и найди его.', 'Добудьте перья с головы Айкисса и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.Это задание может быть выполнено только в героическом режиме.', 'Я уверен, эти перья подойдут к головному убору вождя. Ты заработал эти деньги, $C.$B$BВозвращайся завтра, у меня будет для тебя новое задание.', 'Церемония все ближе.', NULL, NULL, 'Головные перья Айкисса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11373, 'Разыскивается: Заговоренный Амулет Шаффара', 'Сегодня у меня есть для тебя персональное задание, и награда, конечно же, будет соответствовать уровню риска.$B$BУ моей семьи есть кое-какие \"претензии\" к принцу Шаффару и его последователям. Если кто-то принесет мне личный амулет Шаффара, это вполне убедит меня в том, что c хозяином побрякушки разобрались. $B$BЕсли тебя заинтересовало предложенное вознаграждение, отправляйся к его логову в Гробницах маны в Аукиндоне.', 'Добудьте заговоренный амулет Шаффара и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.Это задание может быть выполнено только в героическом режиме.', '<Вы чувствуете, что торговец ветром вами доволен.>$B$BЗамечательно. Я рад слышать о его смерти. Возможно, мне удастся самому постигнуть тайны этого амулета. Если же нет – я знаю, кому его можно продать за хорошие деньги.$B$BВозвращайся завтра, у меня будет для тебя новое задание.', 'Немногие знают, что магические силы Шаффара напрямую связаны с его амулетом. Без него он бессилен.$B$BЕсли амулет у тебя, то Шаффар, очевидно, мертв.', NULL, NULL, 'Чудесный амулет Шаффара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11374, 'Разыскивается: Самоцвет души Экзарха', 'В Аукенайских гробницах в Аукиндоне проводится множество сомнительных экспериментов в области некромантии. Там были замучены или уничтожены многие духи.$B$BОдин мой заказчик весьма заинтересован в освобождении одного из этих духов. Он заключен в камень, который носит не кто иной, как Экзарх Маладаар.$B$BКак можно скорее разыщи его в гробницах и принеси мне этот камень.', 'Добудьте самоцвет души экзарха и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.Это задание может быть выполнено только в героическом режиме.', 'Ты настоящий герой, $N. Я уверен, что мой клиент найдет способ освободить дух своего любимого человека из камня. За хорошую работу и плата полагается соответствующая.$B$BВозвращайся завтра, у меня будет для тебя новое задание.', 'Представляешь, каково это – быть навечно заключенным в камне.', NULL, NULL, 'Самоцвет души экзарха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11375, 'Разыскивается: Шепот Бормотуна', 'Когда я расскажу все до конца, ты можешь захотеть отказаться от этого задания.$B$BУ моего клиента весьма эксцентричное увлечение – он специализируется на погибших реальностях. Ходят слухи, что тот, кого мы знаем как Бормотуна, уничтожил мир, из которого он был вызван. Профессор хочет изучить его \"шепот\" – так он это называет, – чтобы понять, как Бормотуну это удалось.$B$BСможешь ли ты отправиться в Аукиндонский Темный лабиринт и добыть этот \"шепот\"?', 'Добудьте шепот Бормотуна и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.Это задание может быть выполнено только в героическом режиме.', 'Я беспокоился о тебе. Надеюсь, ты не оглох во время поединка с Бормотуном?$B$BВот твоя награда. Профессор будет очень доволен, хотя мне страшно представить, что он собирается с этим делать.$B$BВозвращайся завтра, у меня будет для тебя новое задание.', 'Не могу себе представить, как можно поймать шепот, но профессор заявил, что ты все поймешь, как только увидишь его.$B$BВозможно, тебе понадобится что-то вроде \"бормотографа\"...', NULL, NULL, 'Шепот Бормотуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11376, 'Разыскиваются: злобные инструкторы', 'Ма\'дуун слышал, будто нет никого злее шестируких демонесс из Темного лабиринта.$B$BОтправляйся в Аукиндон и убей их всех.$B$BЕсли ты не сможешь выполнить такое простое задание, то нам с тобой не о чем говорить.', 'Убейте для ловчего Пустоты Ма\'дууна 3 злобных инструкторов, по выполнении вернитесь к нему в Нижний город Шаттрата, чтобы получить свою награду.', 'Я доволен. И тот кто говорит со мной через Пустоту, тоже будет доволен. Ма\'дуун приготовил твою награду.$B$BПриходи завтра и ветра снова будут говорить с Ма\'дууном.', NULL, NULL, NULL, 'Злобный инструктор убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11377, 'Месть сладка', 'Сегодня я обслуживаю одну очень необычную вечеринку. Один тип летал в Скеттис, и его сбила чудовищная калири. У него тяжелый перелом ноги.$B$BОни заказали особое блюдо для вечеринки по случаю его выздоровления – похлебку из калири.$B$BЯ готов ссудить тебе мой кухонный котелок, так что можешь припасти немного похлебки для меня. Сам рецепт несложен, но тебе придется добыть крылышко гигантской калири и несколько готовых котлет из прыгуаны.', 'Скалл из Нижнего города просит вас приготовить похлебку из калири в его кухонном котелке. По выполнении вернитесь к нему.', 'О, да, наяву! Надеюсь, ты превратил эту пташку в хорошую отбивную?$B$BПрошу, бери, что хочешь из моих личных запасов. Уж ты при твоих талантах сумеешь воспользоваться ими по делу!', 'Какой восхитительный аромат! Неужто наяву?', NULL, NULL, 'Похлебка из калири', 'Котелок', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11378, 'Разыскивается: Голова Охотника Вечности', 'У моих клиентов вкусы – от самых простецких до самых экзотических. А иногда им желательна совершенно экзотическая вещь для самых простецких целей.$B$BНапример, последний заказ. Мой клиент, пожелавший остаться неизвестным, желает получить голову Охотника Вечности, дабы повесить ее на стене у себя дома.$B$B$C, не удастся ли вам найти способ вернуться в прошлое в старые Предгорья Хилсбрада и добыть искомую голову для моего клиента – любителя охотничьих трофеев?', 'Торговец ветром Зарим просит вас добыть голову Охотника Вечности. Доставьте ее в Нижний город Шаттрата и получите награду.Это задание выполняется только в героическом режиме.', 'Вижу, вы вернулись в настоящее целый и невредимый.$B$B<Торговец ветром озирается по сторонам.>$B$BВроде все как было. Но опять же – кто знает?$B$BХорошая работа – клиент будет доволен. Вот ваша награда.$B$BВозвращайтесь завтра, и у меня найдется для вас другое порученьице.', 'Голова Охотника Вечности...кому только в голову взбредет прибивать ее к стенке у себя дома?$B$BНо если даже и взбредет, то что он скажет друзьям, когда они будут спрашивать, как он ее добыл?$B$BСоврет, наверное.', NULL, NULL, 'Голова Охотника Вечности', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11379, 'Очень горячая похлебка', 'Я пытаюсь изобрести что-нибудь такое, чтобы уж вштыривало, так вштыривало. Но, честно говоря, я уже не тот гоблин, что прежде. Я утратил вкус к приключениям.$B$BНо ты напоминаешь мне меня в юности. Тогда я готов был завоевать весь мир с мечом в одной руке и сковородкой в другой.$B$BВозьми мой любимый кухонный котелок и ступай в Острогорье. Брось туда немного ребрышек и поджаристых змеек – заранее приготовленных ради аромата – и свари их над трупом демона Бездны – на свете нет ничего горячее, чтобы сварить такую похлебку.', 'Скалл из Нижнего города просит вас приготовить немного невероятной демонической похлебки в его кухонном котелке. Вернитесь, когда приготовите.', 'Посмотрим-посмотрим...$B$B<Скалл отхлебывает немного варева, и на лице его рисуется невероятная смесь восторга и страданияt.>$B$BА\'дал сладчайший, какая вкуснотища! Такому повару, как ты, просто неприлично не обзавестись собственными припасами! Возьми из моих, и да буду я гордиться твоими успехами!', 'Ну, как, удался мой экспериментик?', NULL, NULL, 'Невероятная демоническая похлебка', 'Котелок', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11380, 'Мания', 'Если хочешь знать, по мне так мои припасы первый сорт, но вот приходит ко мне некто и желает странного: манаягодной услады.$B$BУвы, манаягоды растут только в заповедниках Пустоверти. Даже не пытайся искать вокруг Штормовой Вершины – даром время потратишь, там все обобрали.$B$BЯ могу доверить сбор лучших ягод только тому, кто сведущ в кулинарии, так что не подведи меня!', 'Скалл из Нижнего города просит вас принести 15 манаягод из заповедников Пустоверти.', 'Более сочных манаягод не видел в жизни! Умнею от одного взгляда на них.$B$BПоскольку запасы мяса и рыбы мне уже не нужны, почему бы тебе в них не порыться? Уверен, ты сможешь приготовить настоящий деликатес!', 'Ну как, повезло?', NULL, NULL, 'Манаягода', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11381, 'Супчик для души', 'В воздухе пахнет смертью. Никогда я не имел столько заказов на мой замечательный супчик – он поднимает дух и утешает душу.$B$BА собрата-повара я узнаю издалека! Не хочешь ли мне помочь – а выручку поделим! $B$BВот, бери мой кухонный котелок, бери мясо копытня, и я открою тебе один маленький секрет. Знаешь, отчего мой супчик так ублажает душу? Не из-за куриного бульона – я варю его в Землях Предков в Награнде, дабы он впитывал духовность!', 'Скалл из Нижнего города просит вас приготовить суп предков в его кухонном котелке. По выполнении вернитесь к нему.', 'Судя по запаху – чудесный суп предков, не будь я Скалл! Добавить щепотку перчика – и готово.$B$BКак и обещал, вот твоя доля. И поскольку ты проделал такую славную работу, я добавлю туда немножко своих собственных специй.', 'Что за божественный запах?', NULL, NULL, 'Суп предков', 'Котелок', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11382, 'Разыскиваются: песочные часы Эонуса', 'Один из моих заказчиков точно чокнутый. Есть нормальные чокнутые, а есть такие, что и подумать страшно!$B$BНынешний мой клиент по такой шкале просто зашкаливает. Он возжелал песочных часов Эонуса!$B$BДа, вы не ослышались, Эонуса из рода Бесконечности!$B$BТаки ж разве я откажусь, если он платит по-королевски? Может, вы прогуляетесь в пещеры Времени и в Черную топь и добудете их для меня?', 'Торговец ветром Зарим просит вас добыть песочные часы Эонуса. Доставьте их в Нижний город Шаттрата и получите награду.Это задание выполняется только в героическом режиме.', 'Странно, что песчинки в этой штуке падают вверх. Думаю, надо как можно скорее отдать ее новому владельцу.$B$BБлагодарю за хорошую работу, $C. Вы честно заработали свои комиссионные.$B$BПриходите завтра и я приготовлю для вас очередную работу.', 'На вашем месте я очень осторожно бы странствовал во времени. Вы ведь не хотите случайно во что-нибудь вляпаться? Например, убьете какого-нибудь своего предка и в результате вычеркнете себя из настоящего!', NULL, NULL, 'Песочные часы Эонуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11383, 'Разыскиваются: Повелители временных разломов', 'Ма\'дуун знает, куда тебе идти. Ма\'дуун знает, что ты $gдолжен:должна: убить повелителей временных разломов. Но Ма\'дуун не знает, когда именно.$B$BЯ понимаю, что это звучит бессмысленно, но ветер не нашептал ничего более определенного.$B$BОтправляйся в Черную топь через пещеры Времени, и путь будет чист.', 'Ловчий Пустоты Ма\'дуун хочет, чтобы вы убили 4 повелителей временных разломов. Вернитесь к нему в Нижний город Шаттрата за наградой, когда они будут убиты.', 'Ты сумел попасть в прошлое и вернуться обратно. Ты наверняка великий $C, $R. Награда твоя заслуженна.$B$BВозвращайся завтра, и ветер нашепчет Ма\'дууну кое-что еще.', NULL, NULL, NULL, 'Повелитель временного разлома убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11384, 'Разыскивается: Отросток Узлодревня', 'Не так давно со мной связался калдорайский друид по одному щекотливому дельцу. И отвалит она за работу, конечно же, кучу золота!$B$BСдается, что силы Дарнаса намерены возродить ходячее древо тайной магии, известное под именем Узлодревень. Это гигантское дерево не то свихнулось, не то подверглось порче, точно сказать не могу, но найдете вы его в Ботанике в Крепости Бурь.$B$BОна сказала, что им всего-то надо маленький отросточек от него, чтобы вырастить древо заново.', 'Торговец ветром Зарим просит вас добыть отросток Узлодревня. Доставьте его ему в Нижний город Шаттрата и получите награду.Это задание выполняется только в героическом режиме.', 'Ах, так вы добыли его! Какой маленький. И все же, когда друиды закончат свое дело – а я слышал, что процесс займет очень много времени – Узлодревень вырастет заново.$B$BА вот и обещанная награда.$B$BПриходите утром – у меня будет для вас новое дельце.', 'Вы сбились с пути и не нашли Ботанику? Нет. Ее не заметить нельзя... Это же в Крепости Бурь на восточном краю Пустоверти.', NULL, NULL, 'Отросток Узлодревеня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11385, 'Разыскиваются: Солнцеловы-чаротворцы', 'Ветер нашептал Ма\'дууну, что заклинатели из военного подразделения под названием Солнечные Охотники должны быть убиты непременно сегодня.$B$BИх можно найти в Ботанике в Крепости Бурь.$B$BХочешь получить награду – убей заклинателей.', 'Ловчий Пустоты Ма\'дуун хочет, чтобы вы убили 6 солнцеловов-чаротворцев. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду.', 'Раз они мертвы, больше никто не будет творить заклинания. Тот, кто шепчет из Пустоты, доволен, и награда – твоя.$B$BВозвращайся утром, и ветер нашепчет Ма\'дууну что-нибудь еще.', NULL, NULL, NULL, 'Солнцелов-чаротворец убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11386, 'Разыскивается: Проектор Паталеона', 'Я всегда думал, что Паталеон Вычислитель пользуется магией, чтобы передавать свой образ в Запределье. Очевидно, я ошибался.$B$BОдин из моих клиентов сказал, что этот проклятый эльф крови пользуется механическим прибором для связи с руководителями особых проектов принца Кель\'таса. Насколько я понимаю, он забрал его у одного из отступников из братства Заксис в Пустоверти.$B$BМой клиент желает получить этот прибор. Не желаешь ли ты нанести визит Паталеону? Его можно найти в Механаре, в Крепости Бурь.', 'Торговец ветром Зарим просит вас добыть проектор Паталеона. Доставьте его в Нижний город Шаттрата и получите награду.Это задание выполняется только в героическом режиме.', 'Очень хочется придержать эту штуку и вернуть клиенту деньги. Проектор весьма расширит границы моей профессиональной деятельности.$B$B<Торговец ветром вздыхает.>$B$BНо я должен заботиться о своей репутации. Кстати, спасибо, что помог ее сохранить.$B$BВот твои комиссионные.$B$BПриходи утром, и я предложу тебе еще одно дельце.', 'Технология проекции сама по себе не сложна, но мощность этой модели – настоящий прорыв!', NULL, NULL, 'Проектор Паталеона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11387, 'Разыскиваются: разрушители из кузни бурь', 'В Механаре есть механические создания которые Ма\'дууну поручено разобрать.$B$BОтправляйся в Крепость Бурь, найди разрушителей из кузни бурь и разрушь их.$B$BПотом можешь вернуться за наградой.', 'Ловчий Пустоты Ма\'дуун хочет, чтобы вы уничтожили 5 разрушителей из кузни бурь. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду.', 'Ма\'дууну нравятся боевые механизмы – они не такие непредсказуемые, как органические создания.$B$BНаграда твоя.$B$BВозвращайся утром, и ветер нашепчет Ма\'дууну что-нибудь еще.', NULL, NULL, NULL, 'Разрушитель из кузни бурь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11388, 'Разыскивается: Свиток Скайрисса', 'Нынешний клиент хочет получить нечто воистину необычное.$B$BЕсть такой предвестник Скайрисс, слуга древних богов. Также говорят, что у него есть большой свиток, в котором содержатся их указания насчет того, как ему повелевать жизнью во вселенной от их имени.$B$BМой нынешний клиент желает заполучить этот свиток, хотя он – или она – даже прочесть его не сможет.$B$BТак что не будете ли любезны отправиться в Крепость Бурь в Аркатрац и добыть его для меня? Ну, по рукам, $C?', 'Торговец ветром Зарим просит вас добыть свиток Скайрисса. Доставьте его в Нижний город Шаттрата и получите награду.Это задание выполняется только в героическом режиме.', 'Я даже прикоснуться к свитку не осмелюсь, чтобы не привлечь к себе ненароком внимание древних богов. Пусть его доставит один из моих помощников.$B$BВы более чем заслужили свою награду, $C, и я желаю вам самой большой на свете удачи!$B$BПриходите поутру – у меня будет для вас новое дело.', 'Наверняка очень опасно вмешиваться напрямую в дела древних богов.$B$BТак что лучше вы, чем я!', NULL, NULL, 'Свиток Скайрисса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11389, 'Разыскиваются: Часовые Аркатраца', 'Часовые Аркатраца вышли из строя. Заключенные взбунтовались, а часовые нападают на тех, кто бы мог помочь.$B$BМа\'дуун слышит шепот ветров Пустоты. Шепот велит уничтожить часовых.$B$BСделай это – и сегодняшняя награда твоя.', 'Ловчий Пустоты Ма\'дуун хочет, чтобы вы навсегда деактивировали 5 часовых Аркатраца. Вернитесь к нему в Нижний город Шаттрата, когда выполните задание, чтобы забрать награду.', 'Теперь, когда часовые уничтожены, наверное, наару попросят Консорциум их заменить? Ма\'дуун не знает, да ему и все равно.$B$BТы заслужил награду.$B$BВозвращайся утром, и ветер нашепчет Ма\'дууну что-нибудь еще.', NULL, NULL, NULL, 'Часовой Аркатраца убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11390, 'У меня есть ветролет!', 'Ну, и чего ты ждешь? Работы невпроворот!$B$BВот ключи от ветролета. Хватай три мешка с реликвиями и вези их на платформы к северу и югу от Стальных ворот. Я отмечу на карте их местоположение.$B$BДа поторопись! У нас нет времени!', 'Главный археолог Стальных ворот просит вас отвезти 3 мешка с реликвиями из раскопа на платформы к северу и югу от Стальных ворот.Для этого вам надо будет воспользоваться погрузочным крюком ветролета.Выполнив задание, вернитесь к главному археологу.', 'Молодец, хотя вводный курс по пилотированию тебе явно не помешает. $B$BЛадно, дело сделано – и это главное. Вот твоя доля.', NULL, NULL, NULL, 'Мешков с реликвиями доставлено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11391, 'Патрулирование Стальных Ворот', 'А? Хочешь еще поработать?$B$BНу ладно, держи ключи. Таскать сегодня ничего не надо, так что просто смотри по сторонам – не заметишь ли чего подозрительного. $B$BЯ прикрутил к машине парочку ракет и пулемет – на всякий случай.', 'Теперь вы лучший пилот Стальных ворот, и главный археолог Стальных ворот поручил вам патрулировать раскопки.Отразите нападение агрессивных существ, после чего вернитесь к главному археологу.', 'Хорошо стреляешь! Сразу видно – профессионал.$B$BВот твоя доля. Приходи завтра за следующим заданием, ладно?', 'Горгулии?! Видел я парочку таких тварей! Надеюсь, ты с ними справился?$B$BНет, куда катится мир? Честному дворфу нельзя уже спокойно в земле покопаться, чтобы на него никто не напал!', NULL, NULL, 'Гьялербронская горгулья убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11392, 'Вызов Всадника без головы', 'Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...', 'Принесите мрачную свечу к груде рыхлой вывороченной почвы.', 'Осмелитесь ли вы положить свечу и вызвать Всадника без головы, пробудив его от проклятого сна?', 'Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.', NULL, NULL, 'Мрачная свеча (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11393, 'Куда пропал исследователь Джарен?', '$N! Мой возлюбленный, Джарен, отправился на запад вместе с маленьким отрядом исследователей, которые хотели проверить слухи об артефактах на Берегу Стылой Межи. Но я слышала, что там водятся мурлоки, и потому боюсь даже предполагать, что могло случиться с моим любимым. $B$BТы ведь не откажешься узнать, все ли у него в порядке? К пляжу ведет юго-западная дорога, но она не безопасна – рядом с ней по лесу бродят ворги и прочие опасные твари.', 'Надзирательница Ирена Каменная Мантия попросила вас отыскать ее суженого, исследователя Джарена.', '<Узнав, кто отправил вас на поиски, исследователь радостно улыбается и тихо шепчет.>$B$BТак, говоришь, Ирена обо мне беспокоится? Она так похожа на своего отца!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11394, 'Думаешь, мурлоки – самые вонючие существа?', 'Вообще-то, я приехал сюда для того, чтобы проверить слухи о погребенных здесь артефактах. Я слышал, что на побережье встречаются мурлоки, но даже не мог себе представить, с чем мне предстоит столкнуться. $B$B<Исследователь осторожно высовывает голову из-за дерева и оглядывается по сторонам.>$B$BЗдесь повсюду солдаты Плети, и они что-то делают с мурлоками и прочими тварями, превращая их в ходячих мертвецов!$B$B$C, мне кажется, мы должны что-то предпринять. Как ты думаешь, тебе по плечу победить несколько солдат Плети?', 'Исследователь Джарен поручил вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к нему.', '<Джарен очень рад вашим успехам, но старается выражать свои эмоции как можно тише.>$B$BТы молодец, $N! Правда, твои доспехи перепачканы в слизи. Может быть, тебе сходить искупаться в проливе? Вода там холодная, но зато ты быстро смоешь с себя эту пакость.', NULL, NULL, NULL, 'Убито солдат Плети с Берега Стылой Межи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11395, 'Устройство Плети', 'В когтях у только что убитого вами существа Плети оказалось устройство, инкрустированное драгоценными камнями, которые очень похожи на те, что украшают вершину смертоносных кристаллов.$B$BИсследователю Джарену непременно захочется изучить этот прибор.', 'Отнесите устройство Плети исследователю Джарену на Берег Стылой Межи.', 'Я знаю, что это! $N, с помощью этого прибора можно управлять смертоносными кристаллами!$B$BСпорим на что угодно, эта штука может отключить окружающие их силовые поля. Хмм.$B$B<Исследователь смотрит на вас в задумчивости, прикидывая, справитесь ли вы с прибором.:', 'Какое странное устройство! Дай-ка я на него взгляну...', NULL, NULL, 'Устройство Плети (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11396, 'Отключи защитное поле', 'Взгляни вот на эту кнопку сбоку пульта. Могу поспорить, если ты нажмешь на нее в непосредственной близости от смертоносных кристаллов, ты сможешь отключить защитное поле. Затем тебе останется только уничтожить кристалл до того, как защита будет восстановлена.$B$BЧто скажешь, $N? Справишься? Гарантирую, щедрая награда за уничтожение кристаллов тебе обеспечена. $B$BЭто меньшее, что мы можем сделать для того, чтобы предотвратить размножение Плети.', 'Исследователь Джарен поручил вам уничтожить 3 смертоносных кристалла.', 'Ура!$B$B<Джарен испуганно оглядывается в надежде, что его радостный возглас не привлек к нему излишнего внимания.>$B$BНу, дружище, ты заслужил награду. Возьми одну из этих вещей, которые я нашел здесь, на побережье.$B$BКстати, если будешь проходить мимо Стальных ворот, передай Ирене, что я ее люблю. Пусть знает, что со мной все в порядке.', NULL, NULL, NULL, 'Уничтожено смертоносных кристаллов', 'Пульт управления смертоносным кристаллом', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11397, 'Думаешь, мурлоки – самые вонючие существа?', 'Ходили слухи, что в этом месте видели солдат Плети – поэтому-то я сюда и приехала. Признаться, я ожидала встретить только мурлоков на побережье, и даже не могла себе представить, с чем мне предстоит столкнуться. $B$BЗдесь повсюду солдаты Плети, и они что-то делают с мурлоками и прочими тварями, превращая их в ходячих мертвецов!$B$B$C, мы не можем позволить им пополнить свою армию мурлоками! К северо-западу от лагеря есть обрыв, который ведет к побережью. Посмотрим, удастся ли тебе справиться с солдатами Плети!', 'Аптекарь Анастасия поручила вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к ней в Аптекарский поселок.', '<Анастасия на мгновение задумывается над вашими словами.>$B$BДа, ты неплохо потрудился, но этого недостаточно. Мы должны остановить Плеть и изгнать их с побережья!', NULL, NULL, NULL, 'Убито солдат Плети с Берега Стылой Межи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11398, 'Устройство Плети', 'В когтях у только что убитого вами существа Плети оказалось устройство, инкрустированное драгоценными камнями, которые очень похожи на те, что украшают вершину смертоносных кристаллов.$B$BАптекарю Анастасии непременно захочется изучить этот прибор.', 'Отнесите устройство Плети аптекарю Анастасии в Аптекарский поселок.', 'Я знаю, что это! $N, с помощью этого прибора можно управлять смертоносными кристаллами!$B$BСпорим на что угодно, эта штука может отключить окружающие их силовые поля. Хмм.$B$B<Аптекарь смотрит на вас в задумчивости, прикидывая, справитесь ли вы с прибором.:', 'Какое странное устройство! Дай-ка я на него взгляну...', NULL, NULL, 'Устройство Плети (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11399, 'Отключи защитное поле', 'Взгляни вот на эту кнопку сбоку пульта. Могу поспорить, если ты нажмешь на нее в непосредственной близости от смертоносных кристаллов, ты сможешь отключить защитное поле. Затем тебе останется только уничтожить кристалл до того, как защита будет восстановлена.$B$BЧто скажешь, $N? Справишься? Гарантирую, щедрая награда за уничтожение кристаллов тебе обеспечена. $B$BЭто меньшее, что мы можем сделать для того, чтобы предотвратить размножение Плети.', 'Аптекарь Анастасия поручила вам уничтожить 3 смертоносных кристалла.', '<Анастасия оборачивается и с улыбкой смотрит на своего суккуба.>$B$BПревосходно, $N. Полагаю, ты заслужила награду. Выбери себе что-нибудь из этого.', NULL, NULL, NULL, 'Уничтожено смертоносных кристаллов', 'Пульт управления смертоносным кристаллом', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11400, 'Скаковые бараны Хмельного фестиваля', 'Если ты покажешь этот штамп Дризу Неуклюге, начинающему наезднику на баранах, он позволит тебе купить скакового барана на Хмельном фестивале.', 'Покажите штамп Полу Янтарлену у входа на территорию Хмельного фестиваля в Дун Мороге.', '', NULL, NULL, NULL, 'Штамп \"Почетный пивовар\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11401, 'Вызов Всадника без головы', 'Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...', 'Принесите мрачную свечу к груде рыхлой вывороченной почвы.', 'Осмелитесь ли вы положить свечу и вызвать Всадника без головы, пробудив его от проклятого сна?', 'Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.', NULL, NULL, 'Мрачная свеча (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11403, 'Наконец, свободен!', 'Гнев был моей темницей, $N, а ты $Gосвободил:освободила; меня. Хотя я считал себя правым, душа моя ныне кровоточит от всех тех ужасов и смертей, которые обрушил я на жителей Азерота.$B$BБлагодарю тебя, что ты $gпривел:привела: меня к Свету. Да не сверну я с этого пути!$B$BОтнеси этот потрепанный молитвенник попечительнице сирот, чтобы дети узнали, что больше я их не потревожу.', 'Возьмите книгу Томаса Томсона и отнесите ее попечительнице сирот в маске в Дуротар, Брилл или на Площадь Соколиных Крыльев.', 'Что это? Этот священный фолиант принадлежал недоброй памяти паладину Альянса. Он и был всадником без головы? Неужели он, наконец, побежден?$B$BЧто за радостный день! $N, ваше имя будет прославлено в легендах, и пусть они проживут в два раза дольше, чем длилось ужасное владычество всадника!', 'Приятно снова видеть вас, $N. Уверена, детишки с радостью послушают рассказы о ваших геройских подвигах!', NULL, NULL, 'Книга Томаса Томсона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11404, 'Вызов Всадника без головы', 'Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...', 'Принесите мрачную свечу к груде рыхлой вывороченной почвы.', 'Осмелитесь ли вы положить свечу и вызвать Всадника без головы, пробудив его от проклятого сна?', 'Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.', NULL, NULL, 'Мрачная свеча (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11405, 'Вызов Всадника без головы', 'Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...', 'Принесите мрачную свечу к груде рыхлой вывороченной почвы.', 'Осмелитесь ли вы положить свечу и вызвать Всадника без головы, пробудив его от проклятого сна?', 'Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.', NULL, NULL, 'Мрачная свеча (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11406, 'Все должно быть готово', 'Скоро на север будут посланы несколько исследовательских отрядов, и капитан Адамс рассчитывает, что строительство крепости Вилдервар будет завершено к тому моменту. Разведчикам и ремесленникам было поручено подготовить обмундирование и припасы для наших людей, которые отправятся покорять скалы. $B$BКапитан известен своим буйным нравом, так что я хочу послать кого-нибудь вперед проверить ход подготовки. Крепость Вилдервар находится далеко на северо-востоке, за Скорном, рядом с Седыми холмами. Найди там Гила Гризерта и убедись, что все готово.', 'Поговорите с Гилом Гризертом в крепости Вилдервар.', 'А, тебя послал интендант? $B$B<Гил облегченно вздыхает.>$B$BЧестно говоря, мы немного отстаем от графика, так что помощь нам не помешает. $B$B<Он вздрагивает.>$B$BКому охота попасть под горячую руку капитану Адамсу?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11407, 'Пивоварня Дрона ищет зазывалу!', 'Значит, ты хочешь потрудиться во славу Хмельного фестиваля? Тогда поработай зазывалой возле флагов рядом с аукционным домом в Аллее Силы, в Аллее Чести, в Аллее Мудрости и в Аллее Духов.$B$BМы одолжим тебе скакового барана на 4 минуты и дадим тебе гоночные поводья.$B$BСоблюдай осторожность, жадины-гоблины не положили по дороге ни одного ящика с яблоками.', 'Зазывайте посетителей на Хмельной фестиваль у флагов на аллее Силы, на аллее Чести, на аллее Мудрости и на аллее Духов.', 'Ты сдержал слово и рассказал всем вокруг о нашей винокурне. Спасибо. Мы обещали наградить тебя б$Nами – что ж, бери. Думаю, тролли не так охотно с ними расстаются…$B$BЗаходи завтра, поработаешь еще денек зазывалой.', 'Ты уже всем рассказал о Хмельном фестивале?', NULL, NULL, 'Зазывайте посетителей у аукционного дома', 'Зазывайте посетителей на аллее Чести', 'Зазывайте посетителей на Аллее Мудрости', 'Зазывайте посетителей на Аллее Духов');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11408, 'Пивоварня Т\'чали Вуду ищет зазывалу!', 'Пусть все узнают, что на Хмельной фестиваль прибыли и тролли! Поработай зазывалой возле флагов рядом с аукционным домом в Аллее Силы, в Аллее Чести, в Аллее Мудрости и в Аллее Духов.$B$BМы одолжим тебе скакового барана на 4 минуты и дадим тебе гоночные поводья.$B$BСоблюдай осторожность, гоблины не положили по дороге ни одного ящика с яблоками. Вот такие они жадины.', 'Зазывайте посетителей на Хмельной фестиваль у флагов на аллее Силы, на аллее Чести, на аллее Мудрости и на аллее Духов.', 'Ну дела! Во зазывала из тебя получился! Самое время готовиться к наплыву посетителей! Спасибо!$B$BАх да, мы обещали тебе награду. Помним, как же, как же…$B$BЗаходи в любой день, поработай еще зазывалой.', 'Ты уже всем рассказал о Хмельном фестивале? И, что самое главное, о чудесном тролльском пиве?', NULL, NULL, 'Зазывайте посетителей у аукционного дома', 'Зазывайте посетителей на аллее Чести', 'Зазывайте посетителей на Аллее Мудрости', 'Зазывайте посетителей на Аллее Духов');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11409, 'А теперь гонки на баранах... Или вроде того.', 'Хочешь попробовать себя в роли $gнаездника:наездницы: на баране? Дворфы считают, что никто их не переплюнет, но будем откровенны, они же большую часть времени пьяны. Так что в этом может быть сложного? Но прежде чем я допущу тебя к соревнованиям, покажи, что справишься с нашими скакунами.$B$BВот что я предлагаю: возьми скакового барана и поводья и покажи, что умеешь ездить верхом.$B$BПусти барана на 8 секунд рысью, потом на 8 секунд легким галопом и на 8 секунд – галопом.', 'У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.', 'Эй, не так-то плохо... Ты точно не дворф?$B$BГонок в округе хватает, и не только здесь. На Хмельном фестивале хорошие наездники на баранах в цене. Иди, найди себе работу.$B$BИ не забывай, эти бараны куплены совершенно законным путем. Помни про это.', NULL, NULL, NULL, 'Промчитесь рысью 8 секунд', 'Промчитесь легким галопом 8 секунд', 'Промчитесь галопом 8 секунд', 'Поводья скаковых баранов');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11410, 'Та самая рыбка', 'Принесенная тобой рыба-шип подойдет в качестве наживки, но я, признаться, боюсь, что на нее клюнет настоящее чудовище! $B$BКогда я впервые забросил тут удочку Ната Пэгла с моей любимой наживкой, из воды высунулась огромная тварь с кошмарными зубами и сосульками на плавниках!$B$BЕсли бы я не обрезал леску, она утащила бы меня под лед. Нет, я не буду экспериментировать с новой наживкой, пока старина Ледяной Плавник плавает поблизости. Впрочем, если хочешь с ним повстречаться, забрось удочку в середине озера. Он не устоит перед такой рыбкой!', 'Кристофер Слоан из крепости Вилдервар просит вас победить Ледяного Плавника.', 'Наконец-то я могу рыбачить спокойно! Правда, к тому времени, как мы что-то поймаем, сюда прибудет экспедиция и заберет себе всю добычу. $B$BНо ты молодец, $N. Заходи еще, не стесняйся.', NULL, NULL, NULL, 'Ледяной Плавник убито', 'Приманка из свежей рыбы-шипа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11411, 'Лагерь Заиндевевшего Копыта', 'За все время работы курьером мне приходилось видеть множество странных обитателей Ревущего фьорда, но среди них особенно выделяется одна группа необычных существ. Издали они напоминают тауренов, но, изучив их внимательнее, я заметил, что они гораздо сильнее и грубее.$B$BОдно из их поселений находится на севере, за Халгриндом, Скорном и северными лесами. Зовется оно Лагерь Заиндевевшего Копыта, и располагается у подножия Гьялерхорна, рядом с Седыми холмами. Я поручаю тебе вступить в контакт с этими существами и выяснить, могут ли они оказаться нам полезны.', 'Поговорите с вождем Прахтотемом в Лагере Заиндевевшего Копыта.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11412, 'Туда и обратно', 'Хорошо, что ты здесь. Мы изрядно влипли! Гоблин, который подвозит пиво, попал в аварию возле Колючего Холма!$B$BПривези нам пиво!$B$BЯ посажу тебя на одного из своих верховых баранов, а ты скачи по этой дороге до самого Колючего Холма.$B$BКак мой гоблин тебя увидит, сразу кинет тебе бочку, а ты отвези ее сюда и отдай моему помощнику. В настоящий момент мне нужны три бочки. Хорошо поработаешь - мы тебе еще работенку подбросим.', 'Возьмите бочку у гоблина, застрявшего возле Колючего Холма, и отвезите ее помощнику Рэя, погонщика баранов. Пока баран не сбежит от вас, постарайтесь доставить три бочки.', 'Огромное спасибо за помощь! Пока дворфы Черного Железа не сложили оружие, а Хмельной фестиваль продолжается, мне не обойтись без помощников. Если ты хочешь еще подзаработать, приходи завтра.$B$BВот обещанные жетоны, желаю веселого Хмельного фестиваля!', NULL, NULL, NULL, 'Бочек доставлено', 'Поводья скаковых баранов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11413, 'Кто сказал \"сувениры\"?', 'Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.$B$BПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.', 'Найдите в лагере Хмельного фестиваля Бликса Чиништукса, отдайте ему купон и получите бесплатную праздничную пивную кружку.', '', NULL, NULL, NULL, 'Купон на получение кружки Хмельного фестиваля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11414, 'Братья-предатели', 'Дозорная Лунный Лепесток являлась мне во снах! Ее друг – и мой друг.$B$BДо последнего полнолуния я считался главным самцом в стае. Затем с севера пришел этот странный белый ворг, Гарвал, и с помощью моих бывших братьев встал во главе стаи. Но что-то в нем меня беспокоит.$B$BЕсли ты хочешь помочь мне, убей тех, кто предал меня. $B$BОдного из них зовут Бьомолф, и он охотится на северо-западе от места, которое вы называете Стальные ворота. Другой, Варг, обитает на юго-востоке, рядом с Западной башней.$B$BНо их ты не обманешь своим обличьем.', 'Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Когда вы убьете их, вернитесь к нему в Вырубки в обличье ворга.Если вы потеряете личину ворга, возьмите другую у дозорной Лунный Лепесток.', 'Меня радует запах их крови на твоей морде. Братья не должны предавать друг друга.', NULL, NULL, NULL, 'Бьомолф убито', 'Варг убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11415, 'Братья-предатели', 'Странник Туманов являлся мне во снах! Его друг – мой друг.$B$BДо последнего полнолуния я считался главным самцом в стае. Затем с севера пришел этот странный белый ворг, Гарвал, и с помощью моих бывших братьев встал во главе стаи. Но что-то в нем меня беспокоит.$B$BЕсли ты хочешь помочь мне, убей тех, кто предал меня. $B$BОдного из них зовут Бьомолф, и он охотится на северо-западе от места, которое вы, двуногие, называете Стальные ворота. Другой, Варг, обитает на юго-востоке, рядом с Западной башней.$B$BНо их ты не обманешь своим обличьем.', 'Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Выполнив его просьбу, наденьте личину ворга и вернитесь к Улклыку.Если вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.', 'Меня радует запах их крови на твоей морде. Братья не должны предавать друг друга.', '<Улклык негромко рычит.>$B$BБьомолф и Варг все еще живы!', NULL, NULL, 'Бьомолф убито', 'Варг убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11416, 'Глаза орлицы', 'Гарвал прячется под странным магическим покровом. Его невозможно увидеть, пока он сам этого не захочет. Но мы должны попытаться обойти эту защиту.$B$BГоворят, что мой старый враг, великая орлица Когтекрыл, может видеть сквозь любую магическую защиту. Если ты вырвешь ее глаза, то сможешь найти Гарвала.$B$BКогтекрыл свила гнездо у подножия водопада, к юго-западу от врайкульского поселения, которое называют Скорн. Если ты дотронешься до ее яиц, она спустится с небес, чтобы убить тебя. $B$BВырви ее глаза!', 'Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.Если вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она выдаст вам новую.', '<Улклык громко рычит, радуясь вашей победе над старым врагом.>$B$BЭта победа делает тебе честь. Хотел бы я лично сомкнуть свои зубы на ее шее!$B$BНо ее смерть не должна стать напрасной. Скорее, съешь ее глаза!', 'Ты принес глаза орлицы?', NULL, NULL, 'Глаза орлицы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11417, 'Глаза орлицы', 'Гарвал прячется под странным магическим покровом. Его невозможно увидеть, пока он сам этого не захочет. Но мы должны попытаться обойти эту защиту.$B$BГоворят, что мой старый враг, великая орлица Когтекрыл, может видеть сквозь любую магическую пелену. Если ты вырвешь ее глаза, то сможешь найти Гарвала.$B$BКогтекрыл свила гнездо у подножия водопада, к юго-западу от врайкульского поселения, которое называют Скорн. Если ты дотронешься до ее кладки, она спустится с небес, чтобы убить тебя. $B$BВырви ее глаза!', 'Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.Если вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.', '<Улклык громко рычит, радуясь вашей победе над старым врагом.>$B$BЭта победа делает тебе честь. Хотел бы я лично сомкнуть свои зубы на ее шее!$B$BНо ее смерть не должна стать напрасной. Скорее, съешь ее глаза!', 'Ты принес глаза орлицы?', NULL, NULL, 'Глаза орлицы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11418, 'Мы зовем его Стальное Перо', 'Я как-то видел одного наглого гиппогрифа, который охотился прямо над крепостью. Джетан пытался его сбить, но стрелы буквально отскакивают от его оперения!$B$BМы так и прозвали его – Стальное Перо. Хотелось бы еще понять, почему он кружит рядом с крепостью Вилдервар. Ведь обычно гиппогрифы опасаются людей.$B$BИсследователь Адеран сделал для нас амулет из пера этого существа. Он утверждает, что с его помощью можно взглянуть на мир глазами гиппогрифа.', 'Найдите Стальное Перо, который кружит над крепостью Вилдервар, и воспользуйтесь оперенным амулетом, чтобы разгадать тайну этого загадочного гиппогрифа. Расскажите Гилу Гризерту о вашей находке.', 'Ты видел гнездо с птенцами? Надо же! Значит, наша птичка женского рода!$B$BДа, это многое объясняет. Пожалуй, я не буду трогать целое гнездо с птенцами из-за такого неожиданного соседства. $B$B<Гил одаривает зверолова Джетана насмешливым взглядом.>$B$BДумаю, мы с ней славно поладим, если старина Джетан оставит свои попытки пополнить свой список трофеев.', 'Ну, что? Амулет Адерана работает?', NULL, NULL, 'Секрет Стального Пера разгадан', 'Оперенный амулет', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11419, 'Скаковые бараны Хмельного фестиваля', 'Если ты покажешь этот штамп Дризу Неуклюге, начинающему наезднику на баранах, он позволит тебе купить скакового барана на Хмельном фестивале.', 'Покажите штамп Дризу Неуклюге у входа на территорию Хмельного фестиваля в Дуротаре.', '', NULL, NULL, NULL, 'Штамп \"Почетный пивовар\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11420, 'Путь к отмщению', 'Две недели назад нашему главному инженеру удалось захватить врайкульскую гарпунную пушку. С помощью такого оружия эти мерзавцы топили наши корабли. Изучив ее, он смог составить подробное руководство по управлению этой штуковиной. $B$BК несчастью, его похитили и отвезли к северу отсюда, в Деревню Драконьего Черепа. Когда мы нашли его, едва живого, руководства при нем не оказалось. Из последних сил он поведал, что потерял свои записи в Катакомбах Утгард, находящихся к северо-западу от Деревни Драконьего Черепа. Ты $gдолжен:должна: вернуть это руководство!', 'Капитан стражи Зорек из Валгарда в Ревущем фьорде поручил вам вернуть руководство по управлению гарпунной пушкой.', '<Зорек листает руководство.>$B$BХм, как интересно... $B$BСудя по этим записям, у врайкулов есть специальное приспособление, с помощью которого они могут нацеливать гарпунные пушки с убийственной точностью. Оно слегка напоминает штурвал наших кораблей. Оказывается, его можно переносить с одной пушки на другую. Мы должны раздобыть такое устройство!', 'Ты нашел руководство?', NULL, NULL, 'Инструкция по пользованию гарпуном', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11421, 'До упора...', 'Пока войска врайкулов пребывают в замешательстве, мы должны нанести удар! Отнеси этот механизм управления гарпуном в Ниффлвар и найди там самую северную гарпунную башню на обрыве.$B$BКак только окажешься внутри, возьми на себя управление одной из врайкульских гарпунных пушек, которые стоят на террасе. С ее помощью ты сотрешь с лица земли Деревню Драконьего Черепа! Уничтожь большой дом, верфь, склад и всех защитников, которых пошлют врайкулы, чтобы остановить тебя!$B$BТолько так мы сможем сделать Бухту Кинжалов более безопасным портом!', 'Лейтенант Ледяной Молот из Ревущего фьорда хочет, чтобы вы уничтожили большой дом Укротителей драконов, верфь Укротителей драконов, склад Укротителей драконов и 8 защитников из клана Укротителей драконов. Как только поручение будет выполнено, верните лейтенанту механизм управления гарпуном.', 'Прекрасно, $N! Ты убил множество драконьих наездников и серьезно разозлила их предводителей. $B$BГотов вернуться в Валгард и сообщить хорошие новости Зореку? А то у меня появилась совершенно безумная идея!', 'Надеюсь, ты пришел сказать мне, что Деревня Драконьего Черепа охвачена пламенем?', NULL, NULL, 'Защитник клана Укротителей драконов убито', 'Большой дом Укротителей драконов уничтожен', 'Верфь Укротителей драконов уничтожена', 'Склад Укротителей драконов уничтожен');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11422, 'Трезубец сына', '$gОн царапает на камне несколько символов, которые, очевидно, обозначают трезубец, мур\'далака, разбившийся корабль и кусок сыра. Рядом с этими рисунками вы различаете грубое изображение самого себя.>$B$B<Вам не сразу удается понять, что хочет от вас старый мурлок. Очевидно, он просит принести ему трезубец с Берега Стылой Межи, но последнее изображение вас озадачивает. Наконец, вы понимаете, что мурлок имел в виду не кусок сыра, а своего сына.>$B$B<Все ясно! Видимо, его сына превратили в мур\'далака! Он хочет, чтобы вы убили его и принесли трезубец.:', 'Старый Ледоспин просит вас принести ему трезубец Гниложабера. Он будет ждать вас на маленьком острове возле Берега Стылой Межи.', '<Старый Ледоспин протягивает руку за трезубцем своего сына, и вы замечаете, что его пальцы слегка дрожат. Неужели этот дряхлый мурлок способен испытывать скорбь?:$B$B<Неужели вы видите скупые слезы в уголках его глаз – или это просто вода?>', '<Старый Ледоспин внимательно окидывает вас мутным взглядом. Очевидно, он ожидает увидеть в ваших руках трезубец его сына.>', NULL, NULL, 'Трезубец Гниложабера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11423, 'Наследие врагов', 'Когда наши армии пройдут по Нордсколу, наши враги познают всю горечь поражения. Их дома будут сожжены, их тела будут разлагаться под воздействием нашей чумы, и сам след их существования будет стерт с лица земли. $B$BКак историк, я беспокоюсь лишь за сохранность знаний. Скоро наши войска из Лагеря Возмездия разрушат восточный город Ниффлвар. Я слышал, что этом городе жил врайкульский бард Хельгус, автор трех книг: \"Саги о близнецах\", \"Саги о проклятии зимы\" и \"Саги о валькириях\". Добудь эти произведения прежде, чем Ниффлвар будет разрушен.', 'Отправляйтесь к северу Заставы Призрачного Клинка, в Ниффлвар, и найдите три свитка: \"Сагу о проклятии зимы\", \"Сагу о валькириях\" и \"Сагу о близнецах\".', 'Эти свитки имеют огромное культурное значение, $N. Я приложу все усилия к тому, чтобы сохранить и перевести на наш язык эти врайкульские произведения.$B$BТы только не пойми меня неправильно. Враг должен быть уничтожен... но древние знания надо сохранить.', 'Где же свитки, $N? Ты их принес?', NULL, NULL, '\"Сага о близнецах\"', '\"Сага о валькирии\"', '\"Сага о проклятии зимы\"', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11424, 'Заградительный холм', 'Во время войны моя работа значительно упрощается – подходящие части тел валяются повсюду.$B$BПравда, их не так-то легко достать. Эти яйцеголовые болваны, изобретающие новые штаммы чумы и насылающие заразу на города противников, портят большую часть материалов.$B$BОднако я знаю место, где можно достать подходящие образцы. К югу отсюда есть Заградительный холм, на котором в древности врайкулы хоронили своих павших воинов. Чума не тронула эти земли – ни наша, ни Короля-лича. Принеси мне несколько костей, и я хорошо тебе заплачу за них.', 'Дженни по прозвищу \"Пила\" просит вас принести ей 5 древних врайкульских костей оживших мертвецов с Заградительного холма, который находится к югу от Нового Агамонда.', 'Хммм... ладно, для начала сойдет. Странные какие-то эти кости.$B$BСкажу тебе начистоту – мне не раз приходилось держать в руках части тел, но ни разу до этого я не испытывала ничего подобного. Ладно; уговор есть уговор. Вот твоя награда.', 'Ну, где мои косточки?', NULL, NULL, 'Древняя кость врайкула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11425, '', 'Ступай выполнять задание!', 'Паразиты, ненавижу!', '', NULL, NULL, NULL, 'Кобольд-вредитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11426, 'В поисках механизма', 'Не волнуйся, $N, нас ждет нечто потрясающее! НЕВЕРОЯТНОЕ! Ты просто слушай меня и делай так, как я тебе скажу. $B$BСначала нам надо достать механизм, упомянутый в этом руководстве. Сдается мне, что ты с легкостью обнаружишь его у одного из врайкулов, которые управляют гарпунными пушками в Деревне Драконьего Черепа. Эти пушки стоят в восточной части деревни, на террасах больших домов.', 'Капитан стражи Зорек из Валгарда в Ревущем фьорде просит вас принести механизм управления гарпуном.', 'Потрясающе! Скоро эти макаки-переростки поплатятся за то, что встали на пути Альянса!', 'Ты нашел устройство?', NULL, NULL, 'Механизм управления гарпуном', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11427, 'Познакомьтесь с лейтенантом Ледяным Молотом', 'Видишь эти врайкульские постройки на северо-восточных склонах? Сами врайкулы называют это место Ниффлвар. Оттуда они обстреливают гарпунами наши фрегаты.$B$BЗнаешь, что? Нам это надоело, $N. Возьми этот механизм управления гарпуном и встреться с лейтенантом Ледяным Молотом, который прячется в одной из врайкульских хижин на северо-западе Ниффлвара.$B$BКогда будешь $gготов:готова:, я посажу тебя на грифона и отправлю тебя прямо к нему!', 'Капитан стражи Зорек просит вас отнести механизм управления гарпуном лейтенанту Ледяному Молоту, который укрывается недалеко от Ниффлвара.', '<Лейтенант Ледяной Молот забирает у вас механизм управления гарпуном.>$B$BА, подарочки!', 'Это еще зачем? Я что, похож на няньку?', NULL, NULL, 'Механизм управления гарпуном (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11428, 'Хранитель Листопад', '$N, ты $gстал нам добрым другом и верным союзником:стала нам доброй подругой и верной союзницей:. Поэтому я хочу обратиться к тебе еще с одной просьбой.$B$BТы собственными глазами $gвидел:видела: то, что случилось с Холмистой поляной, и какие жуткие твари населяют эти некогда мирные земли. Негодующие хранители не прекращают приманивать этих чудовищ, и вскоре они заполонят все земли и воды – если только мы не сможем им помешать.$B$BСамого могущественного негодующего хранителя зовут Хранитель Листопад. Убей его, $N, и дай этим землям шанс возродиться во всей былой красе.', 'Луриэль с Заиндевевшей поляны просит вас убить Хранителя Листопада.', 'Сердце мое обливается кровью, когда я думаю о несчастных хранителях, обративших свое оружие против нас. А ведь когда-то мы считали их братьями и самыми близкими друзьями!$B$BЯ оплакиваю братьев и сестер, которых мы потеряли, но твоя поддержка дает нам надежду на будущее. Отныне ты всегда желанный гость в наших землях, $N.', 'Ты избавил Холмистую поляну от Хранителя Листопада?', NULL, NULL, 'Хранитель Листопад убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11429, 'Защищай знамя до последнего!', 'Я не собираюсь доверять столь ответственное задание непроверенным людям.$B$BЕсли хочешь доказать мне, что ты обладаешь необходимыми качествами для выполнения этой миссии, делай так, как я тебе велю.$B$BВозьми это знамя и отправляйся в Гибльхейм, который находится на севере отсюда. Как только прибудешь на место, найди центр города и установи там этот флаг. Сразись с любым врайкулом, который осмелится прикоснуться к нашему великому знамени, после чего доложи мне о победе Альянса!', 'Лейтенант Ледяной Молот из Ревущего фьорда хочет, чтобы вы закрепили Знамя Альянса в Гибльхейме и защищали его от нападающих.Если вам удастся выжить в этом испытании, верните знамя лейтенанту Ледяному Молоту.', 'Слава Альянсу! А ты не робкого десятка, $N. Пожалуй, тебе хватит силенок, чтобы раскрошить парочку врайкульских черепов в Ниффлваре.', 'Ты смотри, на тебе ни царапинки. Можно подумать, ты ни с кем не сражался!', NULL, NULL, 'Знамя Альянса закреплено', 'Знамя Альянса (Прилагается)', 'Защитить знамя Альянса', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11430, 'Мастер-гарпунщик Явус', 'Ты хорошо $gпроявил:проявила: себя в Гибльхейме, $N. Но прежде, чем ты начнешь задирать нос, я хочу поручить тебе настоящее задание в Ниффлваре.$B$BМы обнаружили врайкула, обстреливающего наши фрегаты из гарпунной пушки. Зовут этого мерзавца Явус. Его легко найти на главной гарпунной станции, выстроенной на склонах Ниффлвара к юго-востоку отсюда.$B$BВыследи его и накажи за все преступления, совершенные им против Альянса!$B$BНе подведи меня, $N!', 'Лейтенант Ледяной Молот из Ревущего фьорда поручил вам убить мастера-гарпунщика Явуса в Ниффлваре.', 'Им понадобится какое-то время, чтобы найти Явусу замену. Самое время осуществить план Зорека! Пока они будут пытаться вышвырнуть нас из Ниффлвара, ты обратишь их гарпунные пушки против них самих!', NULL, NULL, NULL, 'Мастер-гарпунщик Явус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11431, 'Поймать дикого зайцелопа!', 'Эй ты! Я ненормальный дворф! Мы, дворфы, считаем, что если принять хорошенько в доброй компании, увидишь много интересного. И невидимого – пока ты трезвый. Небось, эти твари бродят по территории Хмельного фестиваля, а мы и знать не знаем! Они заметны только спьяну.$B$BНам, дворфам, любые поводы выпить хороши.$B$BТы ведь тоже от повода не откажешься? Ну вот, поймай в эту сеть 5 зайцелопов. Сеть мне дал один си-ильно напившийся дворф.$B$BА если ты не видишь зайцелопов, значит, надо еще выпить. Или хотя бы надеть Синтехмельные очки – у меня как раз есть парочка.', '\"Дворф\", Глодрак Меткий Охотник попросил вас поймать 5 оглушенных диких зайцелопов с помощью особой сети. Он намекнул, что необходимо достичь состояния сильного алкогольного опьянения – или хотя бы надеть Синтехмельные очки.', 'Что?! Они существуют! Как мне стыдно, ведь я пнул того дворфа...$B$BМинутку... Надо выпить...$B$B*Он делает долгий глоток из кружки.*$B$BПожалуй, можешь оставить себе одного... Надо доказать, что пьяные дворфы (а другие бывают?) говорят правду!', 'Ты несешь мне товар или ищешь повод напиться?', NULL, NULL, 'Оглушенный зайцелоп', 'Сеть для ловли зайцелопов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11432, 'Спящие великаны', 'Я случайно услышал твой разговор с отцом Левариолом. Смею предположить, он не позволил тебе предпринять решительные действия.$B$BНо ты $gдолжен:должна: уничтожить врайкулов, спящих в глубине чертогов Пробуждения под Гьялерброном!$B$BЯ не сомневаюсь, что ритуалы, в которых они должны принять участие, могут иметь ужасные последствия! Скорее всего, у некролордов есть некое устройство, позволяющее пробудить их на время.$B$BУничтожь спящих – и врайкулы никогда оправятся от таких потерь.', 'Маг-лейтенант Малистер поручил вам уничтожить 5 спящих врайкулов. Когда задание будет выполнено, вернитесь к нему в Крепость Западной стражи.', 'Ты сделал то, что должен был сделать. Хотя многие сочтут убийство беспомощных врайкулов бесчестным поступком, в нашем положении это был единственно верный выход.$B$BМы ведь не могли позволить, чтобы их пробудили в ходе неких ужасных ритуалов, верно?$B$BПоэтому ты можешь гордиться своей смелостью, $N.', NULL, NULL, NULL, 'Спящий врайкул убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11433, 'Спящие великаны', 'Я случайно услышал твой разговор с Великой Матерью Анкхой. Смею предположить, она не позволила тебе предпринять решительные действия.$B$BНо ты $gдолжен:должна: уничтожить врайкулов, спящих в глубине чертогов Пробуждения под Гьялерброном!$B$BЯ не сомневаюсь, что ритуалы, в которых они должны принять участие, могут иметь ужасные последствия! Скорее всего, у некролордов есть некое устройство, позволяющее пробудить их на время.$B$BУничтожь спящих – и врайкулы никогда не оправятся от таких потерь.', 'Ахота Белый Иней поручил вам уничтожить 5 спящих врайкулов. Когда задание будет выполнено, вернитесь к нему в Лагерь Заиндевевшего Копыта.', 'Ты сделала то, что должна была сделать. Хотя многие сочтут убийство беспомощных врайкулов бесчестным поступком, в нашем положении это был единственно верный выход.$B$BМы ведь не могли позволить, чтобы их пробудили в ходе неких ужасных ритуалов, верно?$B$BПоэтому ты можешь гордиться своей смелостью, $N.', NULL, NULL, NULL, 'Спящий врайкул убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11434, 'Забытое сокровище', 'Я сколотил целое состояние на сокровищах, которыми не интересуются обычные пираты – предметы искусства, картины, антиквариат. $B$BНесколько лет назад к югу отсюда затонул флот Блэка Конрада. Ныряльщики давно уже растащили все золото и драгоценности, но два древних сокровища так и остались лежать на дне моря. Одно из них – аманийская ваза, музейная редкость, а второе – статуэтка орла. $B$BДобудь эти ценности, и я замолвлю за тебя словечко перед остальными пиратами. Я даже подброшу кое-что звонкое, чтобы твое морское приключение стало для тебя не только увлекательным, но и прибыльным.', 'Красавчик Терри из Лагеря Скалаваг просит вас достать аманийскую вазу и статуэтку орла с места кораблекрушения на юге.', 'Определенно, нам стоит провернуть какое-нибудь дельце, $N. С моей внешностью и твоей... предприимчивостью мы непременно сорвем куш.', 'Ты принес мои сокровища, $N? Ничто в этой жизни не дается просто так, за красивые глаза... даже мне!', NULL, NULL, 'Аманийская ваза', 'Статуэтка орла', 'Рыбий желчный пузырь', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11436, 'Полетаем?', 'Как же нелегко путешествовать по крутым обрывам Ревущего фьорда! К счастью, мне пришла в голову идея, как облегчить эту задачу. Мое устройство сочетает в себе врайкульскую технологию и дворфийскую гениальность. Тут подкрутить, здесь припаять – и вот, позвольте продемонстрировать пульт управления гарпуном имени Ледяного Молота! Конечно, я его еще не испытывал, но ты вполне с этим справишься!$B$BОтнеси эту штуку к большой пушке в Ниффлваре и отправь себя в Валгард. Доложи о своем успехе Зореку. Кстати, пульт управления можешь оставить себе!', 'Воспользуйтесь большой врайкульской пушкой в Ниффлваре и запустите себя в Валгард. Доложите о победе над врайкулами капитану стражи Зореку.', 'Ты что, совсем с ума сошел, $N? Только полный идиот может выстрелить собой из гарпунной пушки, чтобы таким образом добраться до места назначения!$B$BНо, я полагаю, надо быть слега сумасшедшим, чтобы так сражаться на обрывах фьорда! Потрясающе! Мне доложили, что Ингвар, предводитель Укротителей драконов, в ярости от твоей выходки! Возможно, однажды именно тебе удастся втоптать его в грязь во славу Альянса!', NULL, NULL, NULL, 'Полет на гарпуне', 'Пульт управления гарпуном Ледяного Молота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11439, 'Учения пожарной бригады', 'Отважные дворфы Караноса готовы в один момент сформировать пожарную бригаду, раз поблизости Всадник без головы. Не хотите ли помочь?$B$BК югу отсюда горные пехотинцы устроили небольшой полигон для учений пожарных бригад. Идите туда и носите ведрами воду, чтобы тушить пожар. Воду можно черпать ведром из этих бочек с водой.$B$BУдачи, $N. Когда поучаствуете в учениях пожарной бригады, возвращайтесь к нам!', 'Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.', 'Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!$B$BОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!', NULL, NULL, NULL, 'Потушено пожаров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11440, 'Учения пожарной бригады', 'Пока остается угроза нападений Всадника без головы, миротворцам придется сформировать там, где необходимо, пожарные бригады. Не хотите ли помочь?$B$BК западу отсюда, в направлении Экзодара, миротворцы организовали небольшой полигон для учений пожарных бригад. Отправляйтесь туда и упражняйтесь в тушении пожаров. Воду можете набирать из бочек прямо здесь.$B$BДо свидания, $N. Когда закончите учения, пожалуйста, возвращайтесь к нам!', 'Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.', 'Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!$B$BОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!', NULL, NULL, NULL, 'Потушено пожаров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11441, 'Хмельной фестиваль!', 'Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом со Стальгорном и получите бесплатное пиво.', 'Поговорите с распорядителем Хмельного фестиваля.', 'Хо-хо! Думаешь, бесплатное пиво вкуснее?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11442, 'Добро пожаловать на Хмельной фестиваль!', '', '', 'Хо-хо! Думаешь, бесплатное пиво вкуснее?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11443, 'Подводное плавание в Бухте Кинжалов', 'Эй... ээ... Привет! А ты что тут делаешь?$B$BКто, я? А... Ну, понимаешь... Я... типа... обчищаю... ээ... Очищаю тут от обломков, вот что! Мне Келлер поручил! Ей-богу, так и сказал: \"Гарри, я хочу, чтобы ты надел водолазный шлем и поискал наши вещички среди обломков кораблей в Бухте Кинжала...\"$B$BНо я, если что, не откажусь от твоей помощи. Здесь, в бухте, полно всяких ценностей... то есть припасов. Так что, давай, тащи все, что найдешь мне. Только не забудь водолазный шлем – иначе задохнешься и умрешь!', 'Гарольд Лаграс из Бухты Кинжалов попросил вас найти 10 валгардских ящиков с припасами.', 'Ух ты! Хорошо работаешь. Ага, давай-ка сюда эти ящички. Я их внесу в ведомость, перепишу содержимое и займусь всякой прочей бюрократией, которой ты наверняка не обучен. Не волнуйся, я непременно расскажу Келлеру, как ты мне помог! Честное слово. Так что... это... Можешь идти! Ну давай уже, проваливай!', 'Ну, где припасы?', NULL, NULL, 'Вальгардский ящик с припасами', 'Шлем водолаза', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11446, 'Хмельной фестиваль!', 'Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом с Оргриммаром и получите бесплатное пиво.', 'Поговорите с распорядителем Хмельного фестиваля.', 'Что?! Бесплатное пиво? Да, да. Кажется, мы обещали нечто подобное.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11447, 'Добро пожаловать на Хмельной фестиваль!', '', '', 'Что?! Бесплатное пиво? Да, да. Кажется, мы обещали нечто подобное.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11448, 'Лагерь Лиги Исследователей', 'Чепуха какая-то! Даже применив шифр, я не могу разобрать, с какой стороны держать эту табличку. Надо признать, криптография никогда не была моей сильной стороной. $B$BОтнеси таблички вместе с шифром нашему криптографу, Станваду. К несчастью, я давно уже не получал от него никаких известий. Две недели назад он взял с собой группу из двадцати ученых и отправился на раскопки у юго-восточных обрывов фьорда. С тех пор о нем ничего не слышно. Остается только поручить МакГоуверу подвезти тебя на его ветролете.', 'Отвезите сверток Максорфа Станваду в Лагерь Лиги Исследователей в Ревущем фьорде.', '<Станвад берет у вас сверток и начинает сортировать таблички.>$B$BОго. Сколько, говоришь, людей погибло ради этой информации?$B$B<Станвад качает головой.>$B$BПолагаю, ты будешь счастлив узнать, что Максорф и его команда слюнявых имбецилов обнаружили рецепт древней тундровой похлебки. Он что, не заметил этот значок, обозначающий овощи, и изображение человеческого рта над вышеупомянутой растительностью? Чтобы понять смысл этих надписей, не нужен никакой шифр!', '<Станвад недовольно ворчит.>', NULL, NULL, 'Узелок Максорфа (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11449, 'Учения пожарной бригады', 'Ловчие смерти устроили учебный полигон за стенами города. Мы не можем допустить, чтобы дома Брилла продолжали гореть. Выполняйте свой долг и ступайте на учения пожарной бригады.$B$BИдите по дороге на запад мимо кладбища. Там увидите полигон.', 'Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Брилле.', 'Отлично, $N. Дети, посмотрите на этого $C. Да будет он вам примером!', NULL, NULL, NULL, 'Потушено пожаров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11450, 'Учения пожарной бригады', 'Стража устроила полигон для учений пожарных бригад за стенами города. Мы не дадим Всаднику разрушить все, что мы с таким трудом восстанавливали. Исполняйте ваш долг и примите участие в учениях пожарной бригады.$B$BСтупайте за ворота на юг и идите до перекрестка. Там найдете учебный полигон.', 'Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске на Площади Соколиных Крыльев.', '', NULL, NULL, NULL, 'Потушено пожаров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11451, 'Стишок Алисии', 'Привет, я тут написала стишок для моей подружки Кайли. Она любит гостить у Алдоров в Шаттрате. Ну, в Запределье, ты же знаешь?$B$BТы не отнесешь ей мои стишки? Моя мамочка говорит, что я еще слишком маленькая, чтобы ходить в Шаттрат!', 'Вас попросили отнести стишок Алисии Кайли Дак в Шаттрат в Запределье. ', 'Какой трогательный стишок, спасибо!', 'Ой, стишок?', NULL, NULL, 'Стишок Алисии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11452, 'Спящий король', 'Из мертвой руки некровладыки падает листок пергамента, на котором описан процесс одного из ритуалов, проходящих в подземных катакомбах. $B$BИз этого свитка вы узнаете, что королева врайкулов, Ангербода, пытается пробудить короля Имирона. Ритуал проводится в огромной палате, известной как Зимняя терраса. Она находится на севере Гьялерброна.$B$BЕсли вы поспешите, то, возможно, успеете остановить Ангербоду до того, как будет слишком поздно.', 'Убейте королеву Ангербоду и прервите ритуал пробуждения короля Имирона. Если вам удастся сделать это, вернитесь в Крепость Западной Стражи и доложите о своей победе капитану Адамсу.', 'Не нравится мне все это! Если Король-лич объединится с Имироном, это принесет нам одни неприятности. Какая жалость, что ты не прикончил его вместе с королевой.$B$BНо все же, тебе удалось значительно нарушить их планы, тем самым выиграв для нас время.$B$BКто знает – возможно, ты еще скрестишь клинки с королем Имироном. Могу поспорить, вашей следующей встречи он не переживет.', NULL, NULL, NULL, 'Королева Ангербода убито', 'Записи Мезхена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11453, 'Спящий король', 'Из мертвой руки некровладыки падает листок пергамента, на котором описан процесс одного из ритуалов, проходящих в подземных катакомбах. $B$BИз этого свитка вы узнаете, что королева врайкулов, Ангербода, пытается пробудить короля Имирона. Ритуал проводится в огромной палате, известной как Зимняя терраса. Она находится на севере Гьялерброна.$B$BЕсли вы поспешите, то, возможно, успеете остановить Ангерброду до того, как будет слишком поздно.', 'Убейте королеву Ангербоду и прервите ритуал пробуждения короля Имирона. Если вам удастся сделать это, вернитесь в Лагерь Заиндевевшего Копыта и сообщите о своей победе вождю Прахтотему.', 'Не нравится мне все это! Если Король-лич объединится с Имироном, это принесет нам одни неприятности. Какая жалость, что ты не прикончил его вместе с королевой.$B$BНо все же, тебе удалось значительно нарушить их планы, тем самым выиграв для нас время.$B$BКто знает – возможно, ты еще скрестишь клинки с королем Имироном. Могу поспорить, вашей следующей встречи он не переживет.', NULL, NULL, NULL, 'Королева Ангербода убито', 'Записи Мезхена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11454, 'Поиски диверсантов', 'Похоже, этот листок бумаги случайно оставили захватчики Черного Железа.$B$BХотя планы очень непростые и записаны особым дворфийским кодом, подпись в самом конце – \"Корен Худовар\" – разобрать легко. Упоминание \"Угрюмого Обжоры\" из Глубин Черной горы тоже. Найди виновника этого безобразия и положи конец набегам.', 'Найдите Худовара в \"Угрюмом обжоре\" в Глубинах Черной горы.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11455, 'Запах денег', 'Мы, пираты, много что любим – ром и золото, паруса и мачты – но порядок и чистота не входят в этот список! На многих пиратских кораблях плавает в пять раз больше крыс, чем членов команды.$B$BНе удивительно, что все медведи на острове подхватили бешенство! Короче говоря, босс хочет от них избавиться.$B$BА тут еще такое дело... попал мне однажды в руки рецептик духов, за которые любая штормградская модница отдаст кошелек и поцелуй в придачу. И знаешь, какой ингредиент стоит там на первом месте? Медвежий мускус! Тебе не кажется, что на этом можно хорошо заработать?', 'Красавчик Терри из Лагеря Скалаваг в Ревущем фьорде просит вас добыть 4 мускусные железы бешеных бурых медведей, которые бродят по всему острову.', 'Ай, молодчина! Может быть, это не столь захватывающе, как грабить корабли, но я буду последней сухопутной крысой, если упущу возможность обогатиться.', 'Ты ведь несешь мне мускусные железы, правда?', NULL, NULL, 'Медвежья мускусная железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11456, 'Мясо для выживших', 'Мы, клыкарры, живем в основном за счет рыбной ловли. Однако во времена большой нужды мы не гнушаемся охотой на животных. $B$BНедавно на близлежащую деревню Искаал напали пираты, и с тех пор оттуда не иссякает поток беженцев.$B$BНа этой неделе наш улов был скромен, но на острове полно черпорогов, чье мясо очень питательно.$B$BПожалуйста, помоги моим людям охотиться на этих огромных животных и принеси мне как можно больше мяса.', 'Предок Атуик из Камагуа в Ревущем фьорде просит вас принести 6 кусков мяса островного черпорога с Острова Копий.', 'Благодарю тебя, $N. Сейчас мои люди во многом нуждаются.', 'Ты принес нам мясо?', NULL, NULL, 'Мясо островного черпорога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11457, 'Вооружая Камагуа', 'Мой народ изображает Иссилрука, духа войны, в виде серебряного орла. Легенды гласят, будто однажды Иссилрук сражался с сотней воргов, чтобы спасти своего детеныша.$B$BТеперь и нам пора вступить в бой с врагами, чтобы защитить наших братьев. Но нам нужно новое оружие. Острые рога ледокрылых химер, что обитают на заснеженных частях острова, легко превратить в наконечники копий. Принеси мне самые лучшие рога, которые тебе только удастся добыть.', 'Старейшина Атуик просит вас добыть 3 рога химеры.', 'Ты невероятно ценный союзник, $N. Мы никогда не забудем то, что ты для нас сделал.', 'Я рад видеть тебя снова, $C.', NULL, NULL, 'Рог химеры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11458, 'Месть за Искаал', 'Тотем Иссилрука готов, $N, и я благодарю тебя за помощь в его изготовлении. В эти тревожные времена мы должны забыть о мирном пути и сразиться с теми, кто посягнул на наши земли и поднял руку на наш народ. $B$BПираты-работорговцы, совершившие налет на Искаал, сошли с ума и убили всех пленных. Отправляйся на восток, в Искаал, и выполни свой долг. Возьми с собой этот рог и призови на помощь моих братьев.', 'Старейшина Атуик просит вас отправиться в Искаал и убить 8 поработителей – пиратов Северных морей. Если вам понадобится помощь, воспользуйтесь Рогом Камагуа.', 'Хорошо, что ты на нашей стороне, $N. Мой народ в долгу у тебя.', 'Ты выполнил мою просьбу, $N?', NULL, NULL, 'Безумный поработитель - пират Северного моря убито', 'Рог Камагуа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11459, 'Что сказал Зех\'ген', 'Трави концы, друг. Значит хочешь, чтобы я гарпунул ту скользкую салаку, которая вильнула меж лап нашей братвы?$B$BТогда тащи мне квакуху, морячок. Потом я подсеку тебе эту тухлятину. Не, не, квакуха подсечет. Сам узыришь, своими маяками, тутжещас.$B$BДа, и не забудь жилорезку, сухоход. Дуй по курсу, чайник.', 'Вернитесь к Красавчику Терри и попросите объяснить, что хотел от вас Зех\'ген.', 'Говоришь, ты ничего не понял из того, что сказал Зех\'ген? Не удивительно.$B$BНу-ка, посмотрим...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11460, 'Завоевание доверия', 'Прежде всего сокольничий должен установить связь между собой и своей птицей, завоевать ее доверие. $B$B<Идальго указывает на соколов в клетке, стоящей у его ног.>$B$BЕсли хочешь, чтобы птицы тебе доверяли – накорми их до отвала!$B$BКак тебе, должно быть, известно, скальные соколы фьорда питаются в основном червяками. По всему фьорду легко можно найти расшатанные камни, под которыми обитает множество личинок. Найди червячка и накорми им сокола в клетке.', 'Идальго из Лагеря Лиги Исследователей в Ревущем фьорде послал вас найти червяка фьорда и скормить его одному из соколов в клетке, стоящей у его ног.', 'Да, $N. Я уже чувствую дружескую связь между тобой и птицей. Она признала тебя хозяином.', 'Это очень важное упражнение, . Если хочешь стать сокольничим – сначала научись правильно кормить птиц.', NULL, NULL, 'Накормить сокола фьорда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11461, 'ИСКЛЮЧЕНО', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11464, 'Карточный долг', 'Говорят, ты работаешь на Терри. Я, признаться, ожидал увидеть кого-нибудь более благонадежного.$B$BВидишь ли, пираты обожают азартные игры. Правда, потом они очень не любят расплачиваться по долгам.$B$BЕсли ты не против стрясти кое с кого парочку звонких монет, то я с удовольствием отсыплю тебе твою долю.$B$BНачнем с чего-нибудь попроще – скажем, с Гарри \"Луносвета\". Эксцентричный парень, обожает всякие эльфийские побрякушки – но стоит ему увидеть меня, как он сразу прикидывается нищим и обделенным. Вытряси из него мое золото!', 'Тарук из Лагеря Скалаваг просит вас взыскать долг Гарри \"Луносвета\".', 'Молодец, ты отлично справился. Вот твоя доля, $N. Ты можешь заработать еще больше – на этом острове еще полно должников.', 'А, ты вернулся. Ну что, где мое золото?', NULL, NULL, 'Долг Гарри \"Луносвета\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11465, 'Разграбленный караван', 'Я вел караван из Валгарда, когда на нас напали Укротители драконов. Выжить удалось только мне. К несчастью, я не смог довезти свой груз фьордовых индеек, но для тебя это будет легкой прогулкой!$B$B<Идальго протягивает вам клетку.>$B$BВот, возьми моего скального сокола и отправляйся на запад по дороге, ведущей из лагеря. Пусть сокол поймает сбежавших индеек, а ты принесешь их мне. $B$BТолько не забудь его покормить!', 'Идальго из Лагеря Лиги Исследователей в Ревущем Фьорде попросил вас поймать 5 индюков фьорда с помощью обученного скального сокола. Как только поручение будет выполнено, верните клетку сокольничему.', 'Хитрые мерзавцы! Но какие терпеливые! Мы должны перестать недооценивать нашего противника. Эти врайкулы – безжалостные убийцы!$B$BВпрочем, как бы то ни было, мы свое дело сделали. А тебе пора поохотиться на более ловкую дичь. Толстый индюк – разве это дело?', 'Всегда корми сокола до отвала перед охотой – иначе он съест всю добычу!', NULL, NULL, 'Фьордовая индейка', 'Обученный скальный сокол (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11466, 'Стаканчик для Джека', 'Наш следующий клиент, Джек Адамс, не такой простак, как Гарри. Он целыми днями выпивает в компании своих дружков – матерых пиратов. Силой тут действовать нельзя – можно пострадать. $B$BДавай лучше воспользуемся его пристрастием к бутылке. Рано или поздно он напьется так, что уже не сможет стоять на ногах. $B$BПоговори с девочками за стойкой – может быть, кто-нибудь из них тебе поможет. Как только он отрубится, запусти руку в его карман и забери то, что принадлежит мне.', 'Тарук из Лагеря Скалаваг просит вас взыскать долг Джека Адамса.', 'Я поражен твоим успехам, $N. А меня, знаешь ли, не так-то легко поразить.', 'Ты забрал то, что принадлежит мне?', NULL, NULL, 'Долг Джека Адамса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11467, 'Долг мертвеца', '$gСлышал:Слышала: о Блэке Конраде? Он, пожалуй, самый знаменитый пират в наших краях.$B$BТак вот; повадился он делать ставки на моих боях, а потом не платить за проигрыш.$B$BХотел бы я стрясти с него должок, да вот только этот подлец взял и помер.$B$BЯ уж было забыл про это дельце, как вдруг мне в руки попала занятная штучка...$B$B<Тарук разворачивает карту острова Копий, помеченную крестиком на северо-восточном плато.>$B$BВидишь, какие дела? Этот забулдыга зарыл целый клад на земле клыкарров. Достань мне это сокровище! Смерть – еще не повод не возвращать мне долги!', 'Тарук из Лагеря Скалаваг просит вас выкопать сокровище Блэка Конрада с северо-восточного побережья острова Копий, что к северу от Искаала.', 'Конрад задолжал мне только золото – его-то я и заберу. Остальное можешь оставить себе.$B$BКстати, если тебе вдруг захочется подзаработать, обращайся ко мне. Пожалуй, я смогу найти для тебя дельце. Попутного тебе ветра, дружище!', 'Ты нашел сокровище, $N?', NULL, NULL, 'Сокровище Блэка Конрада', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11468, 'Ястреб против сокола', 'Ты это чувствуешь, $N? Сейчас ты уже $gдолжен:должна: ощутить связь между собой и твоим соколом. Поверишь ли ты мне, если я скажу, что однажды ты сможешь взглянуть на мир глазами своей птицы? Да, это высшее мастерство, доступное лишь лучшим сокольничим. $B$BЧтобы достичь таких высот в нашем ремесле, надо много и упорно трудиться! Птица должна охотиться, оттачивать навыки и рефлексы. Выбери для нее более достойного противника! Скажем, ястребов фьорда, которые гнездятся на верхушках деревьев. Пусть они станут твоей следующей добычей!', 'Идальго из Лагеря Лиги Исследователей в Ревущем фьорде просит вас поймать 10 ястребов фьорда с помощью вашего обученного скального сокола.Когда вы выполните это задание, верните Идальго клетку с соколом.', 'Да, ястребы очень ревностно относятся к защите территорий и часто гнездятся большими стаями. Пожалуй, мне следовало предупредить тебя заранее.', 'Всегда корми сокола до отвала перед охотой – иначе он съест всю добычу!', NULL, NULL, 'Ястреб фьорда', 'Обученный скальный сокол (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11469, 'Мыло для чистки палуб', 'Ага, мне надо надраить палубу до того, как прибудет Безумный Иона. Только я не собираюсь ползать тут на четвереньках! $B$BУ меня, знаешь ли, мыло закончилось. Только это не моя проблема, а твоя, дружище. Ты у нас салага – так что тебе и бегать за припасами. $B$BНа северо-западном побережье острова полным-полно морских львов. Там, среди льдов, ты найдешь главного тюлева, Большого Роя. Принеси мне его сальник, и я сварганю нам лучшее мыло!', 'Побегушка Мерзлонос просит вас принести ей сальник Большого Роя, чтобы она могла сварить из него мыло для чистки палуб. Она ждет вас на восточном пиратском корабле в Лагере Скалаваг.', 'Фу, какой мерзкий запах!$B$BДавай, клади сюда эту штуку. Сейчас я произнесу нужное заклинание – и мыло появится само собой!', 'Где сальник? Только не говори, что ты его не нашел.$B$BЭтот Большой Рой такой жиртрест, что море должно выходить из берегов, когда он взмахивает плавником!', NULL, NULL, 'Сальник Большого Роя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11470, 'Птицы не знают о чести', 'Думаю, ты уже $gготов:готова: перейти на следующую ступень обучения соколиной охоте. $B$BОтнеси своего обученного сокола на восток, к Подъемнику Каменной стены, где гнездятся врайкульские ястребы. Они вьют гнезда в отдаленных расщелинах на обрыве. Найди, где они селятся, и поручи своему соколу украсть яйца из их гнезд.$B$BТолько остерегайся ястреба-матриарха фьорда. $N. Если она нападет на тебя, прикажи соколу подняться ввысь и беги!', 'Идальго из Лагеря Лиги Исследователей в Ревущем фьорде поручил вам выкрасть восемь яиц ястреба фьорда с помощью вашего обученного скального сокола.Когда вы выполните задание, верните Идальго клетку с соколом.', 'Молодец, $N! Браво! Ты чувствуешь, как окрепли узы, связывающие тебя с соколом? Возможно, вскоре мы сможем посылать вас на разведку врайкульских территорий!', 'Ты хозяин сокола, $N. Пошли его на добычу яиц.', NULL, NULL, 'Яйцо ястреба фьорда', 'Обученный скальный сокол (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11471, 'Конец игры', 'Я знаю, зачем ты $gпришел:пришла: сюда, $N. Тебя послали убить нашего предводителя, Иону Стерлинга.$B$BЯ хочу помочь тебе. Боюсь, под руководством Ионы вся наша операция провалится.$B$BНе понимаю, зачем нападать на флотилии Орды и Альянса одновременно? Это же самоубийство. А пытаться продавать пленных клыкарр, хотя на чужбине они умирают через несколько дней? Безумие какое-то.$B$BИона прячется в пещере к западу отсюда. Принеси мне подзорную трубу в доказательство его смерти – и я лично распоряжусь, чтобы нападения на твоих союзников прекратились.', 'Энни Бонн из Лагеря Скалаваг хочет, чтобы вы принесли ей подзорную трубу Ионы Стерлинга.', 'Наконец-то Иона Стерлинг сыграл в ящик! Эх, не предполагал он, что с ним разделается \"какая-то девка\"!$B$BКак только весть о смерти Ионы распространится среди пиратов, я возьму власть в свои руки. И я сдержу слово – мои люди больше не станут нападать на твоих союзников.', 'Итак, $N. Ты принес мне подзорную трубу Ионы?$B$BИзвини, я не могу поверить тебе на слово. Я же все-таки пиратка!', NULL, NULL, 'Подзорная труба Ионы Стерлинга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11472, 'Путь к его сердцу...', 'Пираты Cеверного моря убили вожака стаи рифовых буйволов, потому что им нужен был жир для варки мыла!$B$B<Ануниак грустно вздыхает.>$B$BТеперь морские львы не смогут размножаться. Помоги мне восстановить их численность.$B$BНа северном побережье Рифа Гарвана, что на юго-востоке отсюда, водится в изобилии рифовая смакрель. Поймай дюжину вкусных рыбин на восточных и западных берегах острова и подмани одного из буйволов прямо к рифовой корове.$B$BПоймать этих мальков просто – тебе даже не понадобится удочка.', 'Подкиньте несколько вкусных рифовых рыб рифовому буйволу, чтобы он последовал за вами к рифовой корове. Когда эти двое одиноких сердец найдут друг друга, вернитесь к Ануниаку в Камагуа.', 'Это замечательно! За этим буйволом последуют другие самцы, и вскоре в наших водах будут плавать маленькие морские львята!$B$BСпасибо, дорогой $R. Этим поступком ты искупил все злодеяния, совершенные тобой в прошлом.$B$BНо мы должны позаботиться о том, чтобы наши труды принесли плоды. Приходи ко мне завтра – возможно, нам удастся приманить еще одного буйвола.', NULL, NULL, NULL, 'Сопроводить рифового буйвола к рифовой корове', 'Сеть Ануниака', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11473, 'Предатель среди нас', 'В последнее время наша заместительница главаря, Энни Бонн, ударилась в паранойю. Всюду ей шпионы мерещатся, представляешь?$B$BА, впрочем, есть у нас давно испытанный метод выявления крыс на корабле. Видишь ли, дружище Зех\'ген – да, да, вон тот старикашка – настоящий колдун! Его предки обитали в самом Зул... как его там... неважно, в общем.$B$BИди, сообщи ему, что нам нужно воспользоваться его пророческим даром. Правда, должен тебя сразу предупредить – понять его непросто.', 'Поговорите с Зех\'геном в Лагере Скалаваг.', 'Дуй сюдыть, дружище. Шта, ко мне причухал?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11474, 'Беда на Крутых утесах', 'Ну, как всегда – вся тяжелая работа досталась мне и моим людям. К счастью, команда Максорфа погибла не напрасно. Шифр, который они обнаружили, поможет нам сделать перевод многих древних текстов, которые мы обнаружили во время раскопок – если, конечно, нам удастся до них добраться! Эти проклятые железные дворфы лезут, как вода из щелей, и пытаются забросать землей раскопы! Ты представляешь? Эти мерзавцы хотят закопать обратно все то, что мы с таким трудом подняли на поверхность!$B$BВ общем, иди и поговори с Уолтом. Он введет тебя в курс дела.', 'Поговорите с Уолтом.', 'Слушай, мелочь – мы и так уже лишились половины команды. Здесь, на крутых утесах остался наш последний оплот. Проклятые Железные дворфы захватили Руины Ивальда и раскопки Бейлгуна. Но у меня есть план, как вернуться обратно и отстоять наши находки до того, как они будут потеряны безвозвратно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11475, 'Орудия труда', 'Я уже несколько дней изучаю это создание, $N. Пожалуй, я мог бы построить точную копию такого голема, но управлять им будет изнутри наш оператор. Думаю, так мы сможем обмануть Железных дворфов и проникнуть в Бейлгун.$B$BНо не могу же я собрать такую конструкцию с помощью молотка и кочерги! Мне нужны инструменты! Увы, мой набор остался в Руинах Ивальда, захваченных железными дворфами. Пожалуйста, верни мои инструменты!$B$BРуины Ивальда находятся далеко на северо-востоке.', 'Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас вернуть его строительные инструменты.', 'Вот теперь я могу приступить к сборке. Ну, конечно, если у меня будут необходимые материалы. Полагаю, теперь ты займешься их поиском.', 'Этап первый: вернуть Уолту инструменты.', NULL, NULL, 'Строительный инструмент', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11476, 'Нож и лягушка', 'Знаешь, некоторые пираты... в общем, изъясняются на своем диалекте. Вот и Зех\'ген... скажем так, говорит на особом... языке.$B$BВ общем, насколько я понял, ему нужен нож и лягушка.$B$BУ Гарри \"Луносвета\" есть парочка дешевых ножей. Лягушек же легко найти в городе – так и прыгают повсюду. Хватай любую и тащи к Зех\'гену.$B$BЧестно говоря, не хотел бы я оказаться на месте этой несчастной твари.', 'Купите блестящий нож у Гарри \"Луносвета\" и поймайте скалавагскую лягушку. Отнесите все это Зех\'гену в Лагерь Скалаваг.', 'Мучо спасибос, парниша. Ну и зенки у квакухи!', 'Ну, тащишь квакуху, салага?', NULL, NULL, 'Скалавагская лягушка', 'Блестящий нож', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11477, 'Дворф другой породы', 'Тише, тише, $r. Эти железные дворфы такие вспыльчивые! Кстати, не думай, что они тут занимаются раскопками. Как раз наоборот! Эти железношкурые мерзавцы засыпают все наши находки землей! Похоже, они не хотят, чтобы кто-то обнаружил это место. $B$BНет, ну ты скажи мне – что это за дворф, который не интересуется археологическими находками? А я скажу тебе: увидишь такого дворфа – убей на месте! Иди, задай им трепку!', 'Донни из Руин Ивальда в Ревущем фьорде просит вас убить 10 разрушителей из клана Железной Руны, 5 работников из клана Железной Руны и 2 ведуна из клана Железной Руны.', 'Молодец, $N. Это их ненадолго замедлит.', NULL, NULL, NULL, 'Разрушитель из клана Железной Руны убито', 'Работник из клана Железной Руны убито', 'Ведун из клана Железной Руны убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11478, 'На той заставе...', 'Похоже, ты еще не $gпосетил:посетила: моих братьев из Лагеря Лиги Исследователей, что находится к югу отсюда. Послушай, окажи Донни услугу и отнеси эту записку Станваду. Ему необходимо узнать про действия Железных дворфов в наших краях. $B$BКак я уже сказал, тебе надо двигаться на юг. Лагерь расположен прямо перед Бейлгуном.', 'Доставьте письмо от Донни Станваду в Лагерь Лиги Исследователей.', '', NULL, NULL, NULL, 'Письмо Донни (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11479, '\"Хромой\" Дэн', 'Квакша назвала предателя! Кракен ему в глотку, вонючей крысе. Это \"Хромой\" Дэн, который прячется вон там, на корабле.$B$BИди-ка, проучи этого сосунка. Пусть знает – с пиратами шутки плохи. Топай к Терри, как протащишь этого мерзавца под килем.', 'Проучите \"Хромого\" Дэна, который прячется на одном из кораблей в Лагере Скалаваг. Когда выполните это задание, поговорите с Красавчиком Терри.', 'Какая жалость... Дэн был моим другом... И к тому же был должен мне кучу денег! Впрочем, если он действительно спутался с шайкой Южных морей, то он получил по заслугам.$B$BЧто же касается тебя, дружище – тебя ждет большое будущее. В буквальном смысле.', NULL, NULL, NULL, '\"Хромой\" Дэн убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11480, 'Познакомьтесь с номером два', 'Проделанная тобой работа не осталась незамеченной, $N. Наш второй командир, несравненная Энни Бонн, глубоко впечатлена твоими достижениями и мечтает с тобой познакомиться.', 'Поговорите с Энни Бонн в Лагере Скалаваг.', 'Ну-ка, ну-ка... К нам пожаловал сам $N. Говорят, ты явился в Лагерь Скалаваг, без рекомендаций, никто ничего о тебе не знает, кроме этого бездельника Терри.$B$BСкажем прямо – не нравится мне все это...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11481, 'Чрезвычайная ситуация у Солнечного Колодца', 'Благодарю тебя, $r, от имени наару за твои труды.$B$BНо до завершения нам еще далеко, и я должен просить тебя выполнить еще одну чрезвычайно важную миссию – не менее важную, чем те, что я поручал прежде.$B$BНаши силы очень растянуты. Чтобы ослабить напряжение, нам пришлось направить отряд в Азерот для отслеживания работ на плато Солнечного Колодца.$B$BТы $gнужен:нужна: там, $N. Найди Ларетора. Скажи ему, что больше я послать не могу.', 'Адиен Страж Света с возвышенности Алдоров в Шаттрате поручает вам отправиться на плато Солнечного Колодца и поговорить с Ларетором.', 'Еще подмога из Шаттрата? Радостное зрелище!$B$BХотелось бы, чтобы помощь была побольше, но будем обходиться с тем, что есть. События ждать нас не будут.$B$BОглядись вокруг, $C. Здесь многое надо сделать. Подключайся и делай свое дело.$B$BО, да, и не дразни этих Подлизцев... э-э, Провидцев. Сдается, сейчас мы заодно...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11482, 'Зов долга', 'Слушай меня, $r.$B$BДолг требует,чтобы ты $gвернулся:вернулась: на Азерот. Все, способные сражаться, немедленно должны явиться на плато Солнечного Колодца.$B$BБоюсь, больше ничего тебе сказать не могу, разве что следующее:$B$BТы присоединишься к объединенным силам Алдоров. Поговори по прибытии с дренеем по имени Ларетор.$B$BПохоже, ситуация такова, что мы должны забыть о наших распрях и объединиться.$B$BГотовься. Дело, похоже, серьезное.', 'Датрис Солнцесвет с яруса Провидцев Шаттрата настаивает, чтобы вы отправились на Азерот немедленно и поговорили с Ларетором у Солнечного Колодца.', 'Добро пожаловать на плато Солнечного Колодца, Подлизец? Нет, не так? А, Провидец, конечно.$B$BЛадно. Тут надо кое-что привести в порядок. За этими стенами творятся непростые дела, и в интересах наших народов надо с ними разобраться. И поскольку в одиночку никто из нас не справится, мы будем трудиться ВМЕСТЕ. Понятно?$B$BНу, так начнем?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11483, 'Мы тоже так можем!', 'Инструменты? Есть. Материалов нет!$B$BЕсли мы собираемся построить эту штуку, тебе придется достать материалы. Итак, по порядку: для возведения скелетной структуры мне потребуется большая бочка из Ниффлвара, несколько слитков черного железа из Валгарда и крепкий промышленный канат из Гибльхейма.$B$BНиффлвар и Гибльхейм – это врайкульские города к северо-западу отсюда. Валгард находится в Бухте Кинжалов, что тоже тебе по пути. Слитки получишь у МакГоувера. Он-то и отправит тебя обратно, когда ты соберешь все необходимое.', 'Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас достать ему большую бочку, крепкий промышленный канат и несколько слитков черного железа.', 'Превосходно. Теперь мы покроем эту шутку кожей – и получим точную копию создания, которых используют Железные дворфы.', 'Ты принес строительные материалы?', NULL, NULL, 'Большая бочка', 'Крепкий промышленный канат', 'Слитки черного железа', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11484, 'Мы знаем технологию', 'Внешний вид устройства столь же важен, как и его механическая часть. Если мы хотим обмануть Железных дворфов, нам придется создать абсолютно идентичного голема! $B$BНо я знаю, как этого добиться. $B$BПринеси мне безупречную шкуру местного черпорога и отбери стальной каркас у одного из врайкулов в Ниффлваре или Гибльхейме. Оба этих поселка находятся к северо-западу отсюда.', 'Уолт из Лагеря Лиги Исследователей просит вас достать ему безупречную шкуру черпорога и стальной каркас.', 'Как только механизм будет готов, я закончу работу над этим устройством.', 'Очень скоро мы снова займемся раскопками!', NULL, NULL, 'Безупречная шкура черпорога', 'Стальной каркас', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11485, 'Голем Железной руны: обучение \"Реактивному прыжку\"', 'Ну ладно, $N. Забирайся в эту штуковину – будем учить тебя основам управления. Как будешь $gготов:готова:, садись на верстак, и я помогу тебе занять место пилота внутри голема.$B$BДля начала попробуй понять принципы передвижения. Видишь вон те руны, которые железные дворфы вырезали вокруг раскопа? Големы используют их энергию, чтобы перелетать с места на место. Потренируйся вот на этой руне, которую я вырезал для тебя.', 'Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас воспользоваться способностью \"Реактивный прыжок\" голема Железной Руны, стоя на вырезанной Уолтом руне.После выполнения упражнения отпустите голема.', 'Скоро ты сможешь испытать эту штучку в деле, $N!', 'Только не надо устраивать тут бег через барьеры на этом големе!', NULL, NULL, 'Отработать \"Реактивный прыжок\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11488, 'Терраса Магистров', 'Добро пожаловать в Солнечный Колодец, $C. Устраивайся и помогай чем можешь – дел невпроворот!$B$BЯ? Да, у меня есть небольшое дело, но вряд ли ты за него возьмешься.$B$BМы внедрили на террасу Магистров разведчика. В последний раз он не вышел на связь, и я начинаю тревожиться.$B$BТерраса находится вверх по склону на востоке. Информация просто необходима для нашей миссии.$B$BКак думаешь, ты справишься, $gраса:?', 'Экзарх Ларетор с плацдарма армии Расколотого Солнца просит вас найти на террасе Магистров своего разведчика – эльфа крови Тирита.', '...Подойди ближе, $R... Слушай внимательно...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11489, 'Голем Железной руны: обучение \"Сбору информации\"', 'Мало просто управлять этим големом – надо еще уметь собирать информацию. Вот, смотри – я кладу в тележку реликвию железных дворфов. Это такой парящий, мерцающий кристалл.$B$BСадись обратно на верстак, и я помогу тебе занять место пилота. Как только устроишься внутри, воспользуйся способностью \"Сбор информации\", чтобы поднять тренировочный образец.', 'Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас воспользоваться способностью голема железной руны \"Сбор информации\", стоя рядом с реликвией железных дворфов.После выполнения упражнения отпустите голема.', 'Отлично! Это просто волшебство какое-то!', NULL, NULL, NULL, 'Собрано тестовых образцов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11490, 'Провидец Провидцев', '*Тирит морщится от боли.*$B$BИди на террасу...используй шар.$B$B...Они...подпитывают Солнечный Колодец...$B$B*Тирит задыхается.*$B$BСпеши... Их надо остановить... Пока они не...$B$B*Тирит умирает.*', 'Тирит просит вас использовать шар на балконе террасы Магистров.', 'Не случайно наши пути сегодня пересеклись.$B$BЯ чую трепет нитей судьбы...', 'Иди и смотри в шар, смертный.', NULL, NULL, 'Шар использован', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11491, 'Голем Железной руны: обучение \"Обманке\"', 'Запомни: всегда имей наготове \"План Б\" – на случай, если основной замысел не удастся! Вот почему я встроил в этого голема кое-какие оборонительные системы. $B$BТакое новенькое, сверкающее устройство может вызвать подозрения у дворфов Раскопки Бейлгуна. Вот тут-то и пригодится твоя \"Обманка\"! Пользуйся этой способностью каждый раз, когда на тебя кто-то нападет, и ты избежишь неприятностей.$B$BИди, потренируйся на Лебронски – потопчись на его коврике. А когда он начнет возмущаться, воспользуйся \"Обманкой\"! $B$BДавай, садись на верстак.', 'Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас потренироваться в использовании способности \"Обманка\" голема Железной руны. Для этого вам надо наступить на коврик Лебронски.После выполнения упражнения отпустите голема.', 'Эх, как ты его отделал! Ну все, теперь ты готов к работе в тылу врага.$B$BВолнуешься?', NULL, NULL, NULL, 'Применить \"Обманку\" на Лебронски', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11492, 'Страшный противник', 'Добро пожаловать к Солнечному Колодцу, смертные. Воистину, вовремя вы пришли.$B$BКак видите, силы Легиона неустанно трудились, управляя мощью Колодца, чтобы достичь своих злых целей.$B$BКель\'тас восстал из пепла поражения и вновь направляет их усилия. Найдите его, смертные. Его снова надо остановить.$B$BМеня зовут иные, не менее важные дела. Судьбу Кель\'таса поручаю вам. Не подведите.$B$BЕсли удача пребудет с нами, мы еще встретимся.', 'Калесгос велит вам уничтожить Кель\'таса на террасе Магистров. Отрубите Келю голову и вернитесь к Ларетору на плацдарм армии Расколотого Солнца.', '<Ларетор внимательно слушает ваш рассказ о событиях на террасе Магистров.>$B$BЖаль Тирита – он был хорошим эльфом. Но благодаря тебе он погиб не даром.$B$BЯ недооценивал тебя, $R. Прошу, прими это от имени наступательной группировки Солнечного Колодца – этот дар достоин такого героя как ты.', 'Что же, $C, должен признаться, я не был уверен, что мы снова свидимся.$B$BЧто за новости ты принес?', NULL, NULL, 'Голова Кель\'таса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11494, 'Заряженные молнией артефакты', 'Ну, все. Твой голем готов. Все механизмы смазаны, все программы проверены. Заодно я научил его понимать язык $Nв.$B$BДавай, отведи его к Раскопкам Бейлгуна, к югу отсюда, и собери данные о заряженных молнией артефактах, которые лежат по всему раскопу. Не забудь включать \"Обманку\" каждый раз, когда твой голем вызовет подозрение у Железных дворфов. Чтобы перепрыгивать с руны на руну, пользуйся \"Реактивным прыжком\". $B$BЗабирайся на верстак, когда будешь $gготов:готова: отправиться в путь!', 'Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас собрать 15 наборов данных о Железной Руне с помощью способности \"Сбор информации\" голема Железной Руны.После выполнения задания отпустите голема.', 'И снова Уолт доказал, что он умнее всех дворфов! Ну, что ты теперь скажешь про моего голема, Лебронски?$B$BСпасибо, $N. Эта информация чрезвычайно важна. Знать бы еще, как извлечь ее из этого механизма...', NULL, NULL, NULL, 'Данные о клане Железной Руны получены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11495, 'Нежный звук грома', 'Во время раскопок Бейлгуна мы наткнулись на пещеру, которую до сих пор обходят стороной даже самые отважные исследователи. Честно говоря, я их понимаю... Трудно остаться хладнокровным, когда из самого чрева пещеры доносятся ужасные раскаты грома!$B$BВ итоге мы прекратили раскопки в этом месте. Страшные беды постигли тех, кто отважился войти в пещеру – многие остались там навсегда.$B$BПрошу тебя, $N, осмотри это место, когда окажешься на раскопках, и расскажи мне о том, что тебе удастся обнаружить. Грохочущая пещера находится возле статуи титана.', 'Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас исследовать грохочущую пещеру на Раскопках Бейлгуна с помощью голема из клана Железной Руны.После выполнения задания отпустите голема.', 'Невероятно! Что же еще задумали эти железные существа? Что они делают на Грозовой Гряде? И кто такой Локен?! Надо незамедлительно передать эту информацию на центральную базу в Драконьем Погосте. Не волнуйся, $N, я не забуду упомянуть о твоих заслугах.', NULL, NULL, NULL, 'Грохочущая пещера исследована', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11496, 'Охрана святилища', 'Важнейшая наша задача – захватить святилище Солнечного Края. Как только мы его захватим, мы сможем использовать его энергию для открытия портала из Шаттрата.$B$BСейчас святилище захвачено Презренными – бывшими эльфами крови, которые опустились до того, что стали тупыми подобиями себя прежних. Будь все в порядке, защитное поле колодца само не пустило бы их, но Презренные украли источник энергии защитного поля колодца.$B$BПеребей Презренных и собери с них клочки маны. Используй их для подпитки защитного поля святилища.', 'Капитан Терис Рассветное Пламя с плацдарма армии Расколотого Солнца просит вас добыть 4 клочка маны у Презренных-злобней и Презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке.', '', NULL, NULL, NULL, 'Зарядите кристалл-хранитель', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11497, 'Орлята учатся летать', 'Хотя в перспективе это может повредить моему бизнесу, у тебя прямо на лбу написана мечта о полете, о том, чтобы завести своего летуна, чтобы парить в небесах, а не так, чтобы тебя перевозили с места на место.$B$BПолностью тебя понимаю.$B$BТебе надо пойти в цитадель Громового Молота на юго-западном краю долины Призрачной Луны. Доберешься туда – поговори с Ильсой Бурное Варево по поводу обучения полетам. Учти – ее наставления стоят недешево. Но они того стоят.', 'Поговорите с Илсой Бурное Варево в цитадели Громового Молота в долине Призрачной Луны.', 'Значит, тебя Нутрал послал, да? Добрый мальчик... Надо поставить ему выпивку за то, что посылает ко мне учеников.$B$BЕсли хочешь научиться летать как надо, то ты пришел в нужное место. Никто не умеет летать лучше Громовых Молотов и тех, кого мы обучаем. Я беру немало, но я обучу тебя парить как орел в небесах!$B$BА когда закончим, не забудь поговорить с Брюнном вон там насчет покупки одного из этих грифончиков-красавчиков!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11498, 'Орлята учатся летать', 'Хотя в перспективе это может повредить моему бизнесу, у тебя прямо на лбу написана мечта о полете, о том, чтобы завести своего летуна, чтобы парить в небесах, а не так, чтобы тебя перевозили с места на место.$B$BПолностью тебя понимаю.$B$BТебе надо пойти в деревню Призрачной Луны на северо-западном краю долины Призрачной Луны. Доберешься туда – поговори с Олрокком по поводу обучения полетам. Учти – его наставления стоят недешево. Но они того стоят.', 'Поговорите с Олрокком в деревне Призрачной Луны в долине Призрачной Луны.', 'Гром и молния, Нутрал посылает ко мне очередного сухопутного рубаку! Добрый он... для дренея.$B$B<Олрокк сплевывает вам под ноги.>$B$BЕсли хочешь знать, как летать на своем летуне в небесах, ты пришел в нужное место. За мешок золота я научу тебя всему, что нужно, чтобы позорно не свалиться и не разбиться в лепешку.$B$BКогда научишься, не забудь поговорить с Дамой Буйной Гривой насчет приобретения ветрокрыла из наших стойл!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11499, 'Разыскивается: перстень-печатка принца Кель\'таса', 'Сегодня, $C, я буду просить тебя о невозможном. Сегодня тебе придется добыть перстень-печатку Кель\'таса Солнечного Скитальца, правителя эльфов крови!$B$BНу, слухи о его гибели в Крепости Бурь не слишком-то достоверны. Он снова появился, теперь на террасе Магистров на острове Кель\'Данас. Что он там делает – это пусть тебе кто-нибудь другой расскажет. А я знаю, что огромное число коллекционеров жаждет заполучить его королевское кольцо, и я собираюсь его для них добыть.$B$BТочнее, добывать его будешь ты...', 'Торговец ветром Зарим хочет, чтобы вы добыли ему перстень-печатку принца Кель\'таса. Доставьте ее в Нижний город Шаттрата и получите награду. Это задание выполняется на террасе Магистров только в героическом режиме.', 'Значит, на сей раз принц эльфов крови и правда мертв? Жаль, я всегда считал, что он умеет вести себя в обществе. Подумать только – такую личность могут убить за такую плевую сумму.$B$BНо, как говорится, дело есть дело. Вы заслужили свою награду, искатель приключений.$B$BВозвращайтесь завтра, и у меня найдется для вас другое порученьице', 'Терраса Магистров, наверное, очень опасное место – слишком уж близко оно к Солнечному Колодцу.$B$BНадеюсь, ты не передумаешь?', NULL, NULL, 'Перстень-печатка принца Кель\'таса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11500, 'Разыскиваются: сестры Терзаний', 'Ветер нашептал Ма\'дууну, что сестры терзаний должны быть отправлены в бездну, из которой они явились.$B$BМа\'дуун знает, что этих демониц можно найти на террасе Магистров на острове Кель\'Данас.$B$BХочешь получить награду – убей их.', 'Ловчий Пустоты Ма\'дуун хочет, чтобы вы убили 4 сестер терзаний. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду.', 'Кто знает, почему должны быть убиты сестры-демоницы? Тебе не безразлично?$B$BНо Ма\'дуун думает, что награда-то тебе не безразлична. $B$BВозвращайся утром, и ветер нашепчет Ма\'дууну что-нибудь еще.', NULL, NULL, NULL, 'Сестра Мучений убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11501, 'Вести с востока', '$N, я хочу, чтобы ты лично $gдоложил:доложила: капитану Адамсу из Крепости Западной Стражи о том, что здесь происходит.$B$BДай мне знать, когда ты будешь $gготов:готова: отправиться в путь, и я посажу тебя в голема. Он доставит тебя в Крепость Западной Стражи – если не развалится на полпути.$B$BБыло приятно с тобой работать...', 'Поговорите с капитаном Адамсом из Крепости Западной Стражи.', 'Этого мне не хватало... Можно подумать, мало нам было проблем с Плетью! Нет, придется теперь еще и разбираться с какими-то древними созданиями титанов.$B$BЛадно, $C, мне надо обдумать эту информацию. Не уходи далеко – ты мне еще понадобишься.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11502, 'Защита Халаа', 'Мы не воинственная раса, $r. Но когда война приходит на наш порог, мы не бежим от нее.$B$BАльянс и Орда ведут войну в Халаа, на северо-западе отсюда. Мы не знаем, что затевают эти эльфы крови, но если победит Орда – это будет катастрофа. Между нами и орками старинная вражда, кровь и предательство.$B$BИди и убивай врагов в Халаа, и получишь золото, славу и честь!', 'Победите 10 игроков вражеской фракции в Халаа и вернитесь в Телаар к Лакуру.', 'Благодарю тебя, $N. Твои дела не будут забыты.', 'Дело сделано, $N?', NULL, NULL, 'Противник из Халаа убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11503, 'Враги старые и враги новые', 'Наши старинные враги, дренеи, вернулись с могущественными союзниками. Они ведут войну в Халаа, к юго-западу отсюда.$B$BМы не должны дать им победить, потому что потом они, вне всякого сомнения, ударят на Гарадар.$B$BИди и перебей тех, кто помогает нашим старинным врагам.', 'Победите 10 игроков вражеской фракции в Халаа и вернитесь в Гарадар к Карртогу.', 'Ты принес великую честь нашему народу. Прими нашу благодарность.', NULL, NULL, NULL, 'Противник из Халаа убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11504, 'Ожившие мертвецы', 'Клыкарры обычно охотятся на восточной дороге – во всяком случае, так было раньше...$B$BНедавно наши охотники вернулись из Камагуа с ужасной вестью – будто бы мертвецы восстали из могил и жаждут нашей крови! Старейшина Атуик поручил мне и моему сыну разобраться с этой проблемой.$B$BПротянешь ли ты нам руку помощи в час нужды? Я ищу героев, которые отважатся преступить границы Заградительного холма, что к юго-востоку отсюда. Осмотри раскопанные могилы и доложи мне о своих находках.', 'Орфус Камагуанский с Древнего подъемника просит вас принести ему улики из могил Фенгира, Родина, Исулдофа и Ветрана.', '<Усы Орфуса гневно топорщатся.>$B$BПираты... Кто положит конец их бесчинствам?$B$BМы должны разыскать украденные артефакты и вернуть их на место. Только тогда мой народ будет в безопасности.', 'Клыкаррам нужна твоя помощь!', NULL, NULL, 'Улика Фенгира', 'Улика Родина', 'Улика Исулдофа', 'Улика Ветрана');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11505, 'Духи Аукиндона', 'Духам Аукиндона нет дела до усобиц Альянса и Орды, но заслужив их расположение, наша сторона получит преимущество в этих краях.$B$BДревний обычай велит живым поклоняться Башням духов в Костяных пустошах – но только в определенное время дня. Если ты поможешь удерживать башни в это время, то привлечешь духов на нашу сторону.$B$BЕсли мы добьемся благосклонности духов, они даруют нам покровительство, которое поможет нам в наших делах.', 'Помогите Альянсу удерживать Башню духов в Костяных пустошах.', 'Теперь духи ближе к умиротворению. Хорошо, что мы заслужили их благосклонность, тем более что воюем так близко к месту их упокоения.', 'Духи все никак не успокоются, $Nо. Ты выполнил свое поручение?', NULL, NULL, 'Башня Духов захвачена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11506, 'Духи Аукиндона', 'Да, мы враждуем с дренеями, но неупокоенные духи их предков в Аукиндоне не служат никому из мира живых.$B$BОбычай дренеев требует от них поклонения Башням духов несколько раз в течение дня в определенное время. Если ты поможешь удерживать башни в это время, ты поможешь духам обрести покой в Аукиндоне.$B$BАльянс попытается захватить башни, чтобы заслужить благоволение усопших. Но победа должна быть за нами.', 'Помогите Орде удерживать Башню духов в Костяных пустошах.', 'Теперь духи стали ближе к умиротворению. Они благосклонны к нам.$B$BКакое унижение для наших врагов – знать, что души их предков обернулись против них, пусть и на время!', 'Вокруг нас духи Аукиндона. Даруют ли они нам свое покровительство?', NULL, NULL, 'Башня Духов захвачена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11507, 'Старейшина Атуик из Камагуа', '$gОрфус тщательно сворачивает принесенные улики.>$B$BМой народ давно уже не воюет с флибустьерами Северных морей. Худой мир лучше доброй драки. Так что я знаю только одного клыкарра, который может помочь нам вытрясти правду из пиратов. Зовут его старейшина Атуик из Камагуа. Отнеси ему эти доказательства.$B$BЧтобы добраться до Камагуа, тебе надо воспользоваться подъемником, который находится позади меня. Он доставит тебя прямиком в деревню, где ты и найдешь старейшину Атуика.', 'Орфус Камагуанский из Ревущего фьорда просит вас отнести узелок старейшине Атуику из Камагуа.', 'Орфус – хороший клыкарр, и один из лучших наших воинов. Я знал, что на него можно положиться.$B$BНу-ка, что там он мне передал?', 'Есть новости от Орфуса?', NULL, NULL, 'Узелок Орфуса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11508, 'Греззикс Иглохруст', 'Воришки-пираты обосновались в Лагере Скалаваг, далеко на юге. К несчастью, их аванпост слишком хорошо охраняется.$B$BВпрочем, я знаю одного товарища, который может помочь нам туда проникнуть.$B$BНедавно в деревню пришел пират-наемник, Греззикс Иглохруст, и попросил у нас убежища. В обмен на пищу и кров он дает информацию о наших врагах и передает пиратам ложные сведения о наших планах. Его лодка находится к юго-западу от берега.', 'Поговорите с Греззиксом Иглохрустом.', 'Хай, дружище. Греззикс никогда не любил связываться с грязными делишками! Всем хороша пиратская доля – пока не приходится пачкать руки в крови.$B$BВидел я эти артефакты – потому и сбежал из Лагеря Скалаваг. Плохие это штуки, очень плохие... $B$BВпрочем, это же твоя жизнь, верно? Хочешь пролезть в Скалаваг – пожалуйста, Греззикс тебе поможет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11509, 'Чудак среди чудаков', 'Флибустьеры Северных морей боятся и уважают Греззикса. Наверное, они просто завидуют моему интеллекту и трепещут перед моим грозным кораблем. Так что ты просто сядь на хвост моему юнге Луи, и скоро станешь своим в доску. Доска – это для пирата все.$B$BКак будешь $gготов:готова: к отправлению – свистни Луи, и он отведет тебя в Скалаваг.$B$BАх да – сначала тебе стоит поболтать с Гарри \"Луносветом\". Он расскажет тебе про эти древние штучки, которые они стырили у врайкулов. Только следи за языком, когда будешь с ним разговаривать. Он такой чудак... совершенно помешался на эльфах крови.', 'Поговорите с Гарри \"Луносветом\" в Лагере Скалаваг и расспросите его о пропавших врайкульских артефактах.', '<Гарри удивленно смотрит на вас.>$B$BА, еще один чудик в нашу команду. Добро пожаловать в клуб!$B$B<Гарри понижает голос.>$B$BЗнаешь, кроме нас тут никто не носит такие шмотки.$B$BА что касается артефактов... Все прикасавшиеся к этим штуковинам либо померли, либо пропали без вести.$B$BНеужели тебе все еще интересно о них узнать? Если что, я могу помочь – конечно, не за доброе слово, а за звонкую монетку.$B$B<Гарри подмигивает.>$B$BРука руку моет, да ножом не колет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11510, '\"Челюсти\"', 'Когда Иона Стерлинг сошел с ума, он первым делом отобрал у меня драгоценный гадальный шар син\'дорай и скормил его этой проклятой твари, дельфину-косатке по прозвищу \"Челюсти\".$B$BНет, это не я ее так обозвал. Я вообще ничего не знаю про эту зверюгу – помимо того, что она постоянно кружит возле наших кораблей на юго-востоке от Скалавага. Убей эту селедку-переростка, вспори ей брюхо и вытащи мой бесценный гадальный шар!$B$BПринесешь мне его – тогда и поговорим.', 'Гарри \"Луносвет\" из Лагеря Скалаваг просит вас достать гадальный шар син\'дорай, принадлежащий ему, из брюха дельфина-косатки по прозвищу \"Челюсти\".', '<Гарри бережно принимает кристалл из ваших рук и поглаживает его.>$B$BАх, ты моя прелесть! Этот мерзкий кит тебя обидел? Ничего, теперь все будет хорошо. Больше я никому тебя не отдам!$B$B<Гарри отрывается от созерцания шара и смотрит на вас.>$B$BТак на чем мы остановились?', 'Ты заблудился, что ли?', NULL, NULL, 'Гадальный шар син\'дорай', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11511, 'Посох Неистовства Бури', 'Эти артефакты прокляты, $r, и надо быть сумасшедшим, чтобы решиться на их поиски. Каждый, кто прикасался к ним, либо сходил с ума, либо умирал насильственной смертью. $B$BВозьмем, к примеру, этот посох. Перевозивший его корабль наткнулся на скалы и теперь гниет на побережье Острова Копий, к северу отсюда.$B$BЕсли тебе правда нужна эта штука, ищи ее в трюме.$B$BТолько не приноси этот посох сюда, если найдешь его! И держись подальше от Абдула. Попадешься ему – распрощаешься с жизнью.', 'Найдите посох Неистовства Бури и отнесите его Орфусу Камагуанскому в Ревущий фьорд.', 'Мы должны отыскать все четыре артефакта, $N. Когда мы возвратим святыни, ты положишь их на место, в захоронения.', 'Посох у тебя?', NULL, NULL, 'Посох Неистовства Бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11512, 'Ледяное сердце Исулдофа', 'Кое-кто считает, что Иона всегда был сумасшедшим, но я-то знаю правду. Все дело в сердце! В этом проклятом ледяном сердце! В тот самый момент, когда он достал его из могилы, что-то в нем перемкнуло. Я буквально почувствовал, как кровь застыла в его жилах... Именно тогда безумие охватило его. $B$BОн покинул нас и скрылся в пещере на севере острова. Говорят, он забросил проклятый артефакт в глубину своей берлоги. Увы, слишком поздно...$B$BНо если ты только помыслишь притащить сюда это сердце, я лично убью тебя!', 'Найдите ледяное сердце Исулдофа и отнесите его Орфусу Камагуанскому в Ревущий фьорд.', 'Мы должны отыскать все четыре артефакта, $N. Когда мы возвратим святыни, ты положишь их на место, в захоронения.', 'Это... это Ледяное сердце Исулдофа?', NULL, NULL, 'Ледяное сердце Исулдофа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11513, 'Перехват контейнеров с маной', 'Я разработал план, согласно которому мы сможем добыть достаточно сильные источники энергии для создания нашего портала.$B$BЭфириалы в лагере Баш\'ира, в горах у северо-западной оконечности Острогорья, контрабандой вывозят контейнеры с маной из Крепости Бурь и отправляют их Кель\'тасу к Солнечному Колодцу.$B$BОни прячут контейнеры, но их все же можно отыскать – эфириалы носят при себе синхронизаторы, при помощи которых можно увидеть контрабандный товар.$B$BОпасайся охраняющих контейнеры с маной синхзрозмей.', 'Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на террасу Света в Шаттрат.', '', NULL, NULL, NULL, 'Контрабандный контейнер с маной', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11514, 'Поддержка портала Солнечного Колодца', 'Мы должны постоянно снабжать энергией наш портал, иначе он уничтожится. Контейнеры с маной, которые Эфириум спрятал в лагере Баш\'ира, помогут нам. Лагерь расположен в горах, на северо-западной оконечности Острогорья, что далеко на севере отсюда.$B$BЗапомни: надо добыть у одного из них синхронизатор и с его помощью определить, где находится контрабанда.$B$BОстерегайся синхрозмей, которых они держат как охрану возле контейнеров с маной.', 'Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на террасу Света в Шаттрат.', 'Эти контейнеры помогут нам поддерживать портал.$B$BПриходи завтра, и я попрошу тебя добыть еще.', '$N, удалось ли тебе добыть для нас контейнеры с маной?', NULL, NULL, 'Контрабандный контейнер с маной', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11515, 'Кровь за кровь', 'Когда войска Келя отступили через этот портал, самые верные его приспешники получили мерзкий дар. Они остались здесь и много дней жадно пили кровь демонов.$B$BЭта кровь изменила их, дав им новую мощь. И эта кровь станет причиной их гибели.$B$BДобудь пробу крови у других демонов. Наполни ей этот конденсатор Скверны и лиши этих надменных глупцов новообретенной мощи. Они ослабнут – вот тогда ты убьешь их и вернешься ко мне!', 'Магистр Сейла у трона Кил\'джедена велит вам убить 4 истощенных сквернокровов при помощи конденсатора Скверны. Вам понадобится кровь демонов, которая течет по венам находящихся рядом зловещих глашатаев, чтобы наполнить конденсатор Скверны.', 'Глупцы. Они научились высасывать энергию Скверны, но не умеют ее накапливать.$B$BНам повезло, $N. Опытный эльф Крови Скверны - страшный противник.', 'Эти уроды - позор нашей расы. Их надо уничтожить, $N.', NULL, NULL, 'Истощенный сквернокров убито', 'Конденсатор Скверны (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11516, 'Взрыв врат', 'Мы должны закрыть эти врата, чтобы не допустить подхода подкрепления Легиона на Кель\'Данас.$B$BВозьми эти угли, в них живет одно из моих созданий – живая вспышка. Она обладает мощной разрушительной силой, если ей хватает энергии.$B$BНайди искры Скверны, что летают в тех краях, и убивай их рядом с живой вспышкой. От каждой убитой искры Скверны живая вспышка будет напитываться силой, пока не станет нестабильной.$B$BКак только живая вспышка достигнет этого состояния, иди к вратам. А живая вспышка уже сделает все сама.', 'Магистр Сейла у трона Кил\'джедена велит вам взять раскаленные угли, чтобы вызвать живую вспышку и убивать рядом с ней раскаленных искр Скверны, пока она не станет нестабильной живой вспышкой. Вернитесь к вратам Легиона вместе с нестабильной живой вспышкой, чтобы уничтожить врата.', 'Замечательная работа, $N. Демоны, конечно, со временем восстановят врата. Ну, ничего, снова взорвем.', 'Дело сделано, $N? Мы не должны допустить подхода на помощь Кель\'тасу сил Легиона.', NULL, NULL, 'Раскаленные угли (Прилагается)', 'Врата Легиона разрушены', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11517, 'Встреча с Назууном', 'Я рад, что ты здесь, $C! Теперь, когда мы захватили святилище, нам нужно срочно создать магический портал, который вел бы отсюда в Шаттрат, что в Запределье.$B$BМой господин, экзарх Назуун, возглавляет этот фронт работ наступательной группировки. Он просил меня посылать к нему любых многообещающих кандидатов, которые могли бы помочь в создании портала.$B$BПрошу тебя – отправляйся в Шаттрат и поговори с ним в чертоге А\'дала на террасе Света.', 'Торговец Портануус просит вас поговорить с экзархом Назууном на террасе Света в Шаттрате.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11519, 'Пропавший щит Эсиритса', 'Прислушайся! Слышишь канонаду на северо-востоке? Это ведет бой корабль капитана Эллис. Штука в том, что Эллис и его команда погибли около месяца назад. Смекаешь?$B$B<Гарри качает головой.>$B$BДа, это корабль-призрак...$B$BИ на нем плавает тот самый человек, который мог бы рассказать тебе про этот щит.$B$BКаждые пять минут \"Сестренка милосердия\" пристает к маленькому острову напротив Берега Сорлофа. Там они пополняют свою команду призраков, и у них никогда не бывает недостатка в неупокоенных душах.', 'Поговорите с капитаном Эллис на борту \"Сестренки милосердия\".', 'Ну да, мои салаги прибрали этот щит к рукам! Да вот только проклятый сухопутный шакал Сорлоф спер его у нас. Мож, ты поможешь его отобрать, а?$B$BА то сам видишь, что у меня за команда!$B$B<Капитан Эллис смеется.>$B$BМне на борту требуется еще один салага – заряжать вон те большие дуры на палубе. Справишься с работенкой, дорогуша?$B$BЯкорь мне в глотку! Если свалим Сорлофа – добычу пополам! Тебе щит, мне все остальное!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11520, 'Смотри в корень', 'Привет тебе, $r. $B$BБоюсь, мне мало есть что предложить тебе, пока не пополню запасов своих реагентов. $B$BИ прежде всего мне нужен корень Острого Шипа, который особенно трудно добывать.$B$BНо, к счастью, я знаю один секрет...$B$BПри помощи желез острошипа-живодера, можно контролировать разорителя и использовать его для выкапывания корней.$B$BЧтобы найти корень, надо отправиться в Запределье и полететь на северо-восток от Шаттрата, до уступа Острого Шипа.', 'Мар\'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа.', '', NULL, NULL, NULL, 'Корень Острого Шипа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11521, 'И опять – смотри в корень', 'Запасов мне пока хватает, но чтобы удовлетворять спрос, мне нужно много корня Острого Шипа.$B$BДобывать его нелегко Но я знаю особый способ его выкапывания.$B$BПри помощи желез острошипа-живодера, можно контролировать разорителя и использовать его для выкапывания корней.$B$BЧтобы найти корень, надо отправиться в Запределье и полететь на северо-восток от Шаттрата, до уступа Острого Шипа.$B$BКак только выкопаешь пять корней, $N, возвращайся.', 'Мар\'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа.', 'Замечательно, $N.$B$BЕще раз благодарю за помощь!', 'Честное слово, $N, мне не до разговоров.$B$BПросто дай мне знать, когда добудешь корни.', NULL, NULL, 'Корень Острого Шипа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11523, 'Подпитка для силового поля', 'Нам удалось реактивировать кристаллы-хранители, создающие поле вокруг святилища, но зачем останавливаться на достигнутом? Мы окружим защитой и другие строения, но Презренные упрямы – они продолжают похищать силу из кристаллов-хранителей.$B$BПеребей их и забери у них клочки маны. При их помощи активируй защиту святилища – от этого зависит успех наших операций здесь.', 'Капитан Терис Рассветное Пламя с плацдарма армии Расколотого Солнца просит вас добыть 4 клочка маны у Презренных-злобней и Презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке.', 'Хорошая работа, $N. Поле постепенно набирает силу. Солнечный Край скоро будет нашим!', NULL, NULL, NULL, 'Зарядите кристалл-хранитель', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11524, 'Хаотичное поведение', 'Нас слишком мало, чтобы захватить святилище в Солнечном Крае, но у меня есть план, который качнет чашку весов в нашу сторону.$B$BПросачивающаяся из Солнечного Колодца энергия привела к сбою в функционировании стражей, патрулирующих этот остров. Кристаллические сердечники, контролирующие их поведение, уже не подлежат ремонту.$B$BЯ сделала новые кристаллы, с помощью которых мы возьмем их под собственный контроль.Их надо поместить внутрь корпуса побежденного стража. Нам нужна любая помощь.', 'Воздаятельница Ксаяна на подготовительном плацдарме Расколотого Солнца просит, чтобы вы поместили настроенные кристаллы-сердечники в корпуса 5 побежденных магических стражей, чтобы перевести их в дружественный режим.', '', NULL, NULL, NULL, 'Введено в действие дружественных караульных', 'Настроенные кристаллы-сердечники (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11525, 'Дальнейшая перенастройка', 'Мой план заменить поврежденные кристаллы блуждающих караульных увенчался успехом. Мы сумели с их помощью захватить святилище Солнечного Края.$B$BЯ создала новые кристаллы, которые помогут контролировать большее их количество. Помести их в корпуса побежденных караульных. Как только мы их переделаем, мы переведем их в другие места.', 'Воздаятельница Ксаяна на подготовительном плацдарме Расколотого Солнца просит вас поместить настроенные кристаллы-сердечники в корпуса 5 побежденных блуждающих караульных, чтобы перевести их в дружественный режим.', 'Замечательно. Перенастроенные стражи помогут нам защитить наш периметр.', 'Удалось перенастроить стражей, $N?', NULL, NULL, 'Введено в действие дружественных караульных', 'Настроенные кристаллы-сердечники (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11526, 'Пропавший магистр', 'Мы послали одну из наших опытных сотрудниц обследовать портал Скверны посреди Рассветной площади, к югу отсюда. Она не вернулась.$B$BВозьми вот этот свиток – мы нашли его на одном из вражеских трупов. Мы уверены, что он даст тебе возможность пройти сквозь портал. Оказавшись там, найди магистра Сейлу и помоги ей, чем сумеешь.', 'При помощи захваченного свитка Легиона, пройдите сквозь портал на Рассветной площади. Как только пройдете сквозь портал, найдите магистра Сейлу.', 'Конечно, очень мило, что Терис заботится о моей шкуре, но у нас тут есть проблемы поважнее. И намного.', 'Тссс, $C. К югу от портала – сторожевой пост Легиона.', NULL, NULL, 'Захваченный свиток Легиона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11527, 'Бунт на корабле', 'Да, дружище, у нас проблемы. У меня пушкари взбунтовались! Я тут с остальными ребятами попробую надраить корму Сорлофу, но кому-то придется разобраться с этими бунтовщиками!$B$BИ, знаешь, что? Этим кем-то будешь ты! Топай в трюм, разберись с этими морскими волками-бунтарями, да притащи пороху для большой дуры на верхней палубе.$B$BЕсли ты зарядишь эту пушенцию, Сорлоф в штаны наложит от страха, и сам притащит сюда всю добычу!', 'Капитан Эллис на борту \"Сестренки милосердия\" в Ревущем фьорде просит вас принести 5 бочек с порохом из трюма корабля.', 'Надеюсь, ты хорошенько проучил этих вероломных трюмных крыс! А теперь пора зарядить нашу пушенцию, дружище!', 'Тут слишком много великанов и морских волков-бунтарей!', NULL, NULL, 'Бочка с порохом', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11528, 'Подарок к Зимнему Покрову', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11529, 'Сокровища Сорлофа', 'Ща, мои ребята начистят для тебя нашу большую дуру! Вон она валяется по другому борту. Иди, заряди пушку, да приготовься стрелять по Сорлофу!$B$BА как только мы пустим на дно эту сухопутную крысу, ты притащишь сюда всю добычу – нам-то с этого чертова корыта не сойти! Принесешь золотишко – получишь свою часть добычи. Тебе щит, нам все остальное...', 'Убейте Сорлофа из большой пушки и принесите капитану Эллис сокровища Сорлофа на борт \"Сестренки милосердия\".', 'Уговор есть уговор!', 'Не щелкай клювом, дорогуша!', NULL, NULL, 'Сокровища Сорлофа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11530, 'Щит Эсиритса', 'Вот твой щит. Надеюсь, на тебя не падет его проклятие, как на остальную команду. Только не оставляй его здесь! Могу поспорить, кто-то хочет забрать его. $B$BА теперь – убери эту штуковину с моего корабля!', 'Верните щит Эсиритса Орфусу Камагуанскому на Древний подъемник в Ревущем фьорде.', 'Мы должны отыскать все четыре артефакта, $N. Когда мы возвратим святыни, ты положишь их на место, в захоронения.', 'Ты вернулся!', NULL, NULL, 'Щит Эсиритса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11531, 'Странная деталь мотора', 'Этот странный механизм никоим образом не напоминает паровой насос. Возможно, К. Ли Мелюзга сможет сказать о нем больше.', 'Отнесите странную деталь мотора к К. Ли Мелюзге в Терелдор.', '<К. Ли смотрит на деталь, о чем-то задумавшись.>$B$BЭта штука, это что-то особенное... Сложно сказать, откуда она взялась, как будто просто с неба свалилась. Пожалуй, я оставлю ее себе, а тебе заплачу за беспокойство.$B$BМежду нами, я бы на твоем месте не болтала об это направо и налево.$B$B<Она очаровательно тебе улыбается.:', 'Мама дорогая, что это ты притащил!', NULL, NULL, 'Странная деталь мотора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11532, 'Отвлекающий маневр на Тропе Мертвых', 'Легион двинется на нас, как только его войска на юге освободятся. Пока силы Плети на Тропе Мертвых отвлекают демонов. Но это ненадолго.$B$BЯ прошу тебя взять дракондора, пролететь над Тропой и устроить демонам прореживание при помощи этих чародейских зарядов.$B$BЕсли все пройдет хорошо, они даже не заметят, как мы отобьем оружейную у прихвостней Келя. Поговори с Айреном, укротителем дракондоров, в западной части гавани Солнечного Предела, когда будешь $gготов:готова: к вылету.', 'Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов.', '', NULL, NULL, NULL, 'Владыка преисподней убито', 'Эредар-колдун убито', 'Зловещий головорез убито', 'Чародейские заряды (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11533, 'Воздушные атаки должны продолжаться!', 'Мы захватили у врага оружейную благодаря нашим атакам с воздуха на силы Легиона на Тропе Мертвых.$B$BСобственно говоря, они были столь удачны, что мы намерены продолжать бомбардировки. Возьми эти чародейские заряды и отбомби ими вражьи силы!$B$BПоговори с Айреном Ясным Небом в гавани Солнечного Края, когда будешь $gготов:готова: к вылету.', 'Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов.', 'Если можешь убить демона сегодня, не откладывай на завтра. Продолжай в том же духе.', 'Ты исполнил свое поручение, $N?', NULL, NULL, 'Владыка преисподней убито', 'Эредар-колдун убито', 'Зловещий головорез убито', 'Чародейские заряды (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11534, 'Встреча с Назууном', 'Я рад, что ты здесь, $C! Теперь, когда мы отбили святилище у Презренных, нам нужно срочно создать магический портал, который вел бы отсюда в Шаттрат, что в Запределье.$B$BМой господин, экзарх Назуун, возглавляет работы наступательной группировки по созданию портала. Он просил меня посылать к нему любых многообещающих кандидатов, которые могли бы помочь добывать источники энергии для портала.$B$BПрошу тебя – отправляйся в Шаттрат и поговори с ним в чертоге А\'дала на террасе Света.', 'Торговец Портануус просит вас поговорить с экзархом Назууном на террасе Света в Шаттрате.', 'Так тебя прислал Портануус? Отлично, время не терпит!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11535, 'Подготовка к работе', 'Припасы уже на подходе, или, по крайней мере, мне так сказали.$B$BКак бы то ни было, мы не можем сидеть сложа руки, надеясь, что помощь прибудет до того, как наше наступление завязнет. Будем обходиться тем, что есть.$B$BЛично мне нужна руда для ковки и наковальня, чтобы я могла начать совершенствовать наши оружие и доспех.$B$BНа побережье к востоку отсюда группа наг добывает руду и грузит в сундуки для отправки Легиону.$B$BЕсли мы избавим их от этой тяжести, это очень во многом поможет нам...', 'Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков.', '', NULL, NULL, NULL, 'Железная руда Черноспинов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11536, 'Продолжаем...', 'Теперь, когда у меня есть наковальня, можно приступить к настоящей работе.$B$BКакие бы к нам ни поступили поставки, руда Черноспинов мне всегда пригодится. Нам нужны бесперебойные поставки оружия и доспехов, если мы хотим здесь добиться успеха.$B$BНа побережье к востоку отсюда группа наг добывает руду и грузит в сундуки для отправки Легиону.$B$BЕсли мы избавим их от этой тяжести, это очень во многом поможет нам...', 'Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков.', 'Великолепно! Это поможет мне снабжать наших воинов оружием и доспехами.$B$BТвоя помощь просто неоценима!', 'Ты добыл нужную мне руду?', NULL, NULL, 'Железная руда Черноспинов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11537, 'Битва должна продолжаться!', 'Мы должны продолжать битву с армиями Легиона и лишать их боевого духа!$B$BЭмиссары Ненависти – это штормовики Легиона, развернутые для усиления тактических позиций. К ним стекаются враги, поскольку они боятся их больше, чем нас.$B$BСегодня мы переломим ситуацию. Возьми это знамя и повергни демонов Легиона. А когда столкнешься с Посланником Ненависти, срази его и пригвозди к земле.', 'Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара Ненависти на Рассветной площади. Пригвоздите к земле древком Знамени Расколотого Солнца труп Эмиссара Ненависти.', 'Твоя преданность достойна быть примером, $N. Мы покажем силам Пылающего Легиона, на что мы способны!', 'Была ли с тобой удача, $N?', NULL, NULL, 'Эмиссар Ненависти пронзен древком', 'Демон Пылающего Легиона убито', 'Знамя Расколотого Солнца (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11538, 'Сражение за оружейную Солнечного Края', 'Пылающий Легион удерживает оружейную Солнечного Края. Это – важный для наших операций пункт. Пока их боевой дух высок, нам не отбить у них это здание. $B$BЭмиссары ненависти – это штурмовики Легиона, развернутые для усиления тактических позиций. К ним стекаются враги, поскольку они боятся их больше, чем нас.$B$BСегодня мы переломим ситуацию. Возьми это знамя и повергни демонов Легиона. А когда столкнешься с эмиссаром ненависти, срази его и пригвозди к земле.', 'Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара ненависти на Рассветной площади или в оружейной Солнечного Края. Пригвоздите труп эмиссара ненависти к земле древком знамени армии Расколотого Солнца.', '', NULL, NULL, NULL, 'Эмиссар Ненависти пронзен древком', 'Демон Пылающего Легиона убито', 'Знамя Расколотого Солнца (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11539, 'Захват гавани', 'Отборные войска Кель\'таса – Клинки Рассвета – расположились в гавани Солнечного Края и в деревне Утренней Звезды.$B$BГавань чрезвычайно важна для наших планов, так что каждый убитый Клинок Рассвета – огромная помощь. Кель\'тас будет проклинать тот миг, когда обратился против собственного народа и заключил союз с Пылающим Легионом!', 'Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей крови и 3 стрелков из клана Клинка Рассвета.', '', NULL, NULL, NULL, 'Призыватель из клана Клинка Рассвета убито', 'Рыцарь крови из клана Клинка Рассвета убито', 'Стрелок из клана Клинка Рассвета убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11540, 'Клинки Рассвета должны быть сокрушены!', 'Мы вытеснили Клинков Рассвета из гавани Солнечного Края. Теперь Солнечный Край полностью наш. Но я почему-то не удовлетворен...$B$BПрошу тебя отправиться в деревню Утренней Звезды, к западу отсюда, и перебить всех уцелевших бойцов Клинков Рассвета. Они сами обрекли себя, последовав сюда за Келем.', 'Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей крови и 3 стрелков из клана Клинка Рассвета.', 'Интересно, что подумал принц Кель\'тас Солнечный Скиталец, когда услышал о поражении своей армии?$B$BОщутил ли он отчаянье? Беспомощность? Страх? $B$BОчень на это надеюсь.', NULL, NULL, NULL, 'Призыватель из клана Клинка Рассвета убито', 'Рыцарь крови из клана Клинка Рассвета убито', 'Стрелок из клана Клинка Рассвета убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11541, 'Зачистить берег Зеленожабрых!', 'Наги захватили берег Зеленожабрых к юго-востоку отсюда. Их самки, сирены из клана Черноспинов, используют магию для подчинения местных мурлоков.$B$BЯ обязана следить за тем, чтобы любая высунувшаяся нага была уничтожена. И в этом мне нужна твоя помощь.$B$B$C, я прошу тебя добыть сферы контроля у наг и разбросать их возле рабов из племени Зеленожабрых, разбив сферы и освободив рабов.$B$BПодозреваю, что разъяренные мурлоки набросятся на своих хозяев.', 'Капитан Валиндрия просит вас освободить 10 рабов из племени Зеленожабрых. Вернитесь к ней на борт \"Гордости Луносвета\" в гавань Солнечного Края по выполнении задания.', 'На сегодня хватит. Тут главное действовать неторопливо, но неотвратимо. Если им слишком сильно всыпать, они обратят на нас внимание, а нам этого не надо.$B$BПриходи завтра, и мы продолжим.', NULL, NULL, NULL, 'Рабов из племени Зеленожабрых освобождено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11542, 'Перехватить подкрепление', 'Мы изо всех сил стараемся укрепить свой контроль над Солнечным Краем. Следующая наша цель – захват гавани. К несчастью, в гавань направляется флот резервистов из армии Клинков Рассвета на помощь войскам Келя.$B$BБери это масло и возьми дракондора у Айрена Ясного Неба. Тебе надо будет подлететь почти к самым парусам – как только окажешься достаточно близко, подожги их.$B$BВысадись на один из кораблей и атакуй резервистов. Когда паруса их корабля вспыхнут, они не особо будут сопротивляться.', 'Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясным Небом насчет полета до флота Клинков Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса кораблей, а приземлившись, убейте 6 резервистов из армии Клинков Рассвета.', '', NULL, NULL, NULL, 'Паруса \"Син-лорен\" горят', 'Паруса \"Кровавой клятвы\" подожжены', 'Паруса \"Рассветного Охотника\" подожжены', 'Резервист из клана Клинка Рассвета убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11543, 'Загнать врага в угол', 'Нам удалось полностью захватить Солнечный Край. К несчастью, в гавань направляется флот резервистов из армии Клинков Рассвета на помощь войскам Келя.$B$BБери это масло и возьми дракондора у Айрена Ясного Неба. Тебе надо будет подлететь почти к самым парусам – как только окажешься достаточно близко, подожги их.$B$BВысадись на один из кораблей и атакуй резервистов. Когда паруса их корабля вспыхнут, они не особо будут сопротивляться.', 'Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясным Небом насчет полета до флота Клинков Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса кораблей, а приземлившись, убейте 6 резервистов из армии Клинков Рассвета.', 'Хорошая работа, $N. Нескоро теперь гавань получит подкрепление.', 'Задание выполнено, $N?', NULL, NULL, 'Паруса \"Син-лорен\" горят', 'Паруса \"Кровавой клятвы\" подожжены', 'Паруса \"Рассветного Охотника\" подожжены', 'Резервист из клана Клинка Рассвета убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11544, 'Оружие Ата\'мала', 'Терраса Ата\'мала на востоке Долины Призрачной Луны – священное место для дренеев, но ныне его захватили орки Скверны. Они добывают в тех местах особую руду, создают оружие и доспехи, полные порчи.$B$BМне нужно это вооружение, чтобы создать сплав с рудой наг. Наши анахореты благословили мою наковальню, и она может очистить их от скверны.$B$BДобудь оружие у избранных, душегубов и темнопрядов Долины Призрачной Луны. Принеси оружие сюда, раздроби его и очисти на моей наковальне и отдай мне то, что выйдет.', 'Кузнец Хаутаа просит вас сделать для нее 5 кусков очищенного металла Ата\'мала. Сделайте это, раздробив на ее наковальне оружие Ата\'мала в оружейной Солнечного Края на острове Кель\'Данас.', 'Благодарю тебя, мой друг. Теперь я смогу сделать больше специального сплава, который пойдет на изготовление оружия и доспехов для нашей армии.$B$BИ еще у меня осталось немного лишнего сплава, который наверняка пригодится тебе на оружие. Прошу – выбирай какой хочешь кусок.$B$BИ снова приходи поутру. Мне наверняка понадобится новая порция металла.', 'Мне нужно столько очищенного металла Ата\'мала, $C, сколько я сумею переработать.', NULL, NULL, 'Очищенный металл Ата\'мала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11545, 'Никто не забыт...', 'Мы отбили гавань Солнечного Края у врага, и окончательная победа уже не за горами. Цену мы заплатили высокую, и многие отважные бойцы положили свои жизни ради этой победы.$B$BЯ хочу, чтобы никто из погибших не был забыт. Прошу вас подумать насчет того, чтобы внести пожертвования в мемориальный фонд. Все оставшееся золото пойдет вдовам и сиротам погибших.', 'Анахоретка Аюри из Солнечного Края у Солнечного Колодца просит вас пожертвовать 10 золотых.', '', NULL, NULL, NULL, 'Требуется денег: 10', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11546, 'Взаимовыгодный бизнес', 'Добро пожаловать, $N.$B$BЯ много чем могу помочь тебе в твоих тутошних трудах.$B$BНапример, я недавно изобрела рецепт уникального эликсира.$B$BВо многих местах Азерота в изобилии растет дикая кровяника. Ее долгое время считали ни на что не годной. Но я узнала, что если подвергнуть это растение влиянию Солнечного Колодца, оно приобретает особые свойства. И если сделать из растения экстракт и выпить, оно будет усиливать твои способности.$B$BПринеси мне ягод с ближайшего куста, и я покажу тебе, что имела в виду.', 'Мар\'на из гавани Солнечного Края просит вас принести ей 5 ягод кровяники с кустов, которые можно найти на Кель\'Данасе.', 'Замечательно, $N.$B$BНадеюсь, это поможет тебе в твоих трудах.', 'Ну, как, принес ягод?', NULL, NULL, 'Кровяника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11547, 'Знай свою силовую линию!', 'Нахлебники!$B$BВам все сразу вынь да положь! Вы представления не имеете, сколько надо сил затратить, чтобы создать даже самый простенький портал!$B$BНу, ничего, я научу вас уважать мои труды!$B$BВозьми этот кристалл. Настрой его на кровавый кристалл, что на западе, на Рассветную площадь, что к югу отсюда, и на святилище наг на берегу Зеленожабрых к юго-востоку.$B$BМожет, тогда ты начнешь больше ценить дар перемещений в пространстве...', 'Звездочет Дарнариан из святилища Солнечного Края просит вас при помощи кристалла звездочета настроить кровавый кристалл, портал на Рассветной площади и святилище наг на берегу Зеленожабрых.', 'Да-да, давай-ка посмотрим...$B$BВроде все в порядке. Хорошо. Вот твой транслокатор.$B$BЕсли полученные тобой данные ошибочны, то куда тебя занесет – никто не знает, и виноват будешь только ты.', 'Ну как, уже настроил кристалл, $C?', NULL, NULL, 'Портал настроен', 'Святилище настроено', 'Кровавый кристалл настроен', 'Кристалл звездочета (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11548, 'Щедрое пожертвование', 'Мы построили мемориал в честь погибших в этой битве. Хоть какое-то утешение для семей, потерявших своих любимых.$B$BЯ собираю пожертвования для сирот и вдов героев войны. Если вы можете пожертвовать немного денег, им хватит на жизнь.', 'Анахоретка Аюри из Солнечного Края у Солнечного Колодца просит вас пожертвовать 10 золотых.', 'У вас благородная душа, $N. Среди грохота войны или ликования победы легко забыть о павших. Друзья и родственники погибших благодарят вас.', 'Вы хотите сделать пожертвование?', NULL, NULL, 'Требуется денег: 10', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11549, 'Великодушный благодетель', 'Ты столько $gсделал:сделала: для нас, $N. Мы высоко ценим твою помощь.$B$BНаверное, ты уже $gзаметил:заметила: анахоретку Аюри? Она великодушна и умеет убеждать, но пожертвования не так щедры, как она ожидала.$B$BЕсли ты пожертвуешь внушительную сумму, я постараюсь, чтобы известия о твоем поступке разошлись широко и далеко. Что скажешь?', 'Анахорет Каиртос просит вас пожертвовать 1000 золотых на дело анахоретки Аюри. Вас будут называть <имя> из армии Расколотого Солнца, если вы это сделаете.', 'У вас благородная душа, и вы - достойный союзник. Отныне вас будут называть $N из Расколотого Солнца, и все, кто здесь сражается, узнают о ваших деяниях!', 'Вы готовы сделать пожертвование?', NULL, NULL, 'Требуется денег: 1,000', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11550, 'Входи, Искуситель...', 'Несмотря на все наши усилия, страшные планы Кель\'таса свершились. Солнечный Колодец снова вспыхнул, готовый к прибытию Искусителя.$B$BПредмет, находящийся передо мной и ниже А\'дала представляет собой нынешнее положение дел с обороной Солнечного Колодца. Вокруг него воздвигнуты мощные преграды, не дающие нам напасть на внутренние чертоги. Если когда нашему миру и была нужна помощь, так теперь.$B$BСообщи обо всем верховному магу Нет\'улу на остров Кель\'Данас, что к северу от Кель\'Таласа.', 'Отнесите сообщение верховному магу Нет\'улу на остров Кель\'Данас, к северу от Кель\'Таласа.Любой распорядитель полетов в Стальгорне или Луносвете доставит вас до места назначения.', 'Кил\'джеден ведет в этот мир все силы Пылающего Легиона. Если обряд призыва свершится, наш мир снова будет повергнут в пучину хаоса. Твоя помощь на острове Кель\'Данас просто жизненно необходима для успешного противостояния Пылающему Легиону.$B$BНаши маги пытаются сокрушить преграды, блокирующие походы к Солнечному Колодцу. Внеси же свою лепту в битву с Пылающим Легионом, оказав помощь наступательной группировке Расколотого Солнца.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11554, 'Солдатская дружба', '', 'Твоя помощь наступательной группировке была замечена, $N. Объединенные силы Алдоров и Провидцев благодарят тебя.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11555, 'Уважение союзников', '', 'Ты непрестанно проявляешь себя в этой самой важной из битв, $N. Прошу - прими это в знак нашей великой благодарности.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11556, 'Почтение боевых друзей', '', '', 'Без тебя мы не смогли бы сделать того, что сделали, $N. Объединенных сил Алдоров и Провидцев недостаточно, чтобы сокрушить Легион и Келя. Мы рады, что у нас есть такие могучие союзники, как ты.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11557, 'Восхищение всего войска', '', '', 'Ты - один из наших лучших бойцов, $N. Твое имя будут помнить среди нас еще долго.Прошу - прими этот небольшой подарок от имени всего войска.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11558, 'Опасная любовь', 'И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.$B$BДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.$B$BОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.', 'Возьмите заплесневелую открытку стража и отнесите ее Фенстаду Аргайлу в Подгороде.', 'Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить. За этим должны крыться какие-то причины.', 'Был ли я прав, когда волновался? Наши идиоты-стражи поддались этой заразе?', NULL, NULL, 'Заплесневелая открытка стража', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11559, 'Торговля с Зимними Плавниками', 'Теперь, когда ты можешь говорить с Зимними Плавниками, самое время познакомиться с ними поближе. А один из лучших способов с ними познакомиться – это вступить с ними в деловые отношения.$B$BМурлоки больше всего ценят моллюсков, а торгует ими сейчас один только Ахлурглгр. На твоем месте я набрал бы моллюсков Зимних Плавников и подарил ему.$B$BМоллюсков можно набрать во рву, а также в деревне Зимних Плавников и в пещерах.', 'Соберите 5 моллюсков Зимних Плавников и отдайте их Ахлурглгру в Приюте Зимних Плавников.', 'Это мне, да? Это что, какая-то ваша уловка, да, $R? Нет?$B$BА-а, ну, тогда спасибо, спасибо! Будут еще моллюски – заходи в любое время, мне нравится иметь с тобой дело!', 'Что это? Кто это?$B$BТы ведь $C! Разве ты можешь говорить по-нашему?', NULL, NULL, 'Моллюск Зимних Плавников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11560, 'О нет, наши бедные малыши!', 'Как хорошо, что ты снова здесь!$B$BКогда из-за оползня в деревне напротив, обнажились пещеры, из одной из них вылез злобный лангустин, которого называют Клаксимус, и похитил малышню Зимних Плавников.$B$BЧто-то странное произошло со всеми мурлоками, погнавшимися за ним, и когда они показались вновь, то оказались подвластны ему.$B$B$C, ты $gдолжен:должна: переплыть эти воды и спасти малышей Зимних Плавников в деревне и в пещерах.$B$BБудущее племени Зимних Плавников зависит от тебя!', 'По поручению короля Мргла-Мргла спасите 20 головастиков Зимних Плавников. Вернитесь к королю в Приют Зимних Плавников, когда выполните задание.', 'Теперь, что бы ни случилось, будущее Зимних Плавников обеспечено.$B$BТебя стоит похвалить и вознаградить за бескорыстную помощь, $N!', NULL, NULL, NULL, 'Спасено головастиков Зимних Плавников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11561, 'Они!', 'Наши сестры и братья по ту сторону стали нашими злейшими врагами. Они похитили наших малюток, выгнали нас из деревни, а убили стольких, что и не счесть.$B$BДокажи нам, чего ты стоишь, $r! Переплыви расселину и убей их!$B$BНесмотря на расположение, выказанное тебе нашим новым королем, это единственное, чем ты можешь попытаться добиться нашего доверия. Если потерпишь неудачу – лучше не возвращайся!', 'По просьбе Брглмургла в Приюте Зимних Плавников убейте воинов, оракулов и гарпунеров Зимних Плавников – всего 15 мурлоков.', 'Я доволен. Я чую медный запах их крови на твоих руках.$B$BНеплохо для начала, $R.', NULL, NULL, NULL, 'Убито мурлоков Зимних Плавников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11562, 'Меня хотят очернить!', 'Я должен сознаться в некоем... конфузе: меня шантажируют!$B$BМрмрглмр согласился почистить кое-какие мои вещи и захватил мой запасной костюм мурлока. И теперь угрожает раскрыть мою истинную природу всем остальным мурлокам.$B$BНет нужды объяснять, какой катастрофой это было бы! Кроме того, у меня есть один план, предполагающий, что костюм нам понадобится вернуть. $B$BПрошу тебя, $N, пойди к Мрмрглмр на другую сторону Приюта, к северу, и сделай все, что он от тебя потребует.', 'По просьбе короля Мргла-Мргла поговорите с Мрмрглмром на северо-западной стороне Приюта Зимних Плавников.', 'Ах-ах, ты, должно быть, тот самый так называемый королевский помощничек? Полагаю, тот ночной эльф послал тебя меня умасливать?$B$BЛадно, у меня как раз есть дельце для такого сильного создания, как ты!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11563, 'Грммурглл Мрллглл Глрггл!', 'Если бы твои жалкие глазенки не были так подслеповаты, тебе не составило бы труда разглядеть, что нас истребляют косатки, живущие на севере бухты!$B$BРаз уж ваш ненаглядный король ночных эльфов желает получить обратно свой парадный костюмчик, думаю, ты согласишься оказать мне услугу и добыть голову короля косаток, Глрггла, того, кто плывет против течения судеб, губя при этом надежды тех, кто услышит песнь смерти над волнами!$B$BНе медли, $r, не медли: пока мы тратим время на болтовню, мурлоки Зимних Плавников гибнут один за другим!', 'Принесите Мрмрглмру в Приюте Зимних Плавников голову Глрггла.', 'Неплохо! То-то будет праздник!$B$BТеперь, когда король косаток мертв, эти махины будут драться между собой за власть, и на время оставят нас в покое!', 'Если у тебя нет головы Глрггла, мне с тобой говорить не о чем!', NULL, NULL, 'Голова Глрггла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11564, 'Сочное жаркое из косатки', 'Ходят слухи, $gчужеземный:чужеземная:$r, что ты, возможно, охотишься на короля косаток Глрггла.$B$BВсе это очень даже хорошо, но, если хочешь отведать жаркое, за которое можно полжизни отдать, принеси мне мясистых сальников косаток, что обитают в Мерцающей бухте.$B$BПоспеши... мне нужно будет долго обрезать мясо с костей, если ты захочешь насладиться плодами своих усилий.', 'По поручению Колуна Бмурглбрма добудьте и принесите 7 кусков мясистого сальника косатки. С мясом возвращайтесь к нему в Приют Зимних Плавников.', 'О-o да, эти куски отлично подойдут.$B$BПлюхни их тут где-нибудь. А пока можешь попробовать остатки моего вчерашнего жаркого.', 'Ну что, принес мне мясистые сальники?', NULL, NULL, 'Мясистый сальник косатки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11565, 'Запасной комплект', 'Отлично, тайна твоего короля останется со мной до тех пор, пока он не перестанет помогать нам бороться с нашими врагами.$B$BВот это доставь ему. Я как следует отчистил эту штуку, хотя не понимаю, зачем ему понадобился второй маскировочный костюм.$B$BМожет быть, у него что-то на уме касательно тебя?', 'Верните запасной костюм короля Мргла-Мргла королю Мрглу-Мрглу в Приют Зимних Плавников.', '<Увидев запасной костюм мурлока, король потирает принадлежности костюма.>$B$BОтлично. Теперь вернемся к неотложным делам. У меня есть для тебя дело чрезвычайной важности.', 'У тебя с собой мой запасной костюм, $N?', NULL, NULL, 'Запасной костюм короля Мргла-Мргла (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11566, 'Сдаться? Ни за что!', 'Настало время положить конец этой противоестественной ситуации, $N! Клаксимус должен умереть, иначе у Зимних Плавников нет будущего!$B$BВозьми мой запасной костюм мурлока и спустись в пещеры Зимних Плавников, делая вид, будто хочешь сдаться. Пока у тебя в руке будет белый флаг, мурлоки не нападут.$B$BТы найдешь Клаксимуса в самом дальнем юго-западном углу пещер. Подберись поближе и покончи с ним! И принеси мне его коготь в доказательство.', 'Принесите коготь Клаксимуса королю Мргл-Мргл в Приюте Зимних Плавников.', 'Печально, но необходимо. Я заберу этот коготь, $N.$B$BСпасибо тебе за оказанную нам помощь. Теперь, когда Клаксимус повержен, мы, возможно, сумеем воссоединить тех мурлоков, что остались в живых, и закрыть пещеры.$B$BПрошу тебя, друг мой, прими вот это... это самое меньшее, чем я могу отблагодарить тебя за услуги!', 'Ну что, $C, дело сделано? Клаксимус мертв?', NULL, NULL, 'Коготь Клаксимуса', 'Запасной костюм короля Мргла-Мргла', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11567, 'Древняя броня Квалдира', 'Да, я работал на судне, перевозившем доспехи. Мы закончили погрузку и направились обратно в лагерь, но тут на нас напал эсминец Отрекшихся.$B$BОни взяли нас на абордаж, забрали всю добычу себе, а корабль потопили.$B$BС тех пор я эти доспехи не видел. Если хочешь, возьми мою лодку в лагере Скалаваг и отправляйся на остров, где пришвартован этот эсминец. Поговори с моей бабой, Аланией – пусть она посадит тебя на бомбардировщик.$B$BДа, если найдешь эти железяки – не вздумай притащить их сюда!', 'Найдите древнюю броню Квалдира и отнесите ее Орфусу Камагуанскому в Ревущий фьорд.', 'Мы должны отыскать все четыре артефакта, $N. Когда мы возвратим святыни, ты положишь их на место, в захоронения.', 'Ты нашел доспехи?', NULL, NULL, 'Древняя броня Квалдира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11568, 'Возвращение святынь', '$gОрфус протягивает вам сумку.>$B$BВ этой сумке находятся найденные тобой артефакты. Далеко на юго-востоке есть Заградительный холм. Найди там курганы, из которых были похищены эти святыни, и верни их на место. Надеюсь, этот благородный жест умиротворит неприкаянных духов, что бродят по нашим охотничьим угодьям.$B$BКрепись, $N...', 'Используйте мешок с врайкульскими артефактами на разграбленных курганах Заградительного холма и верните на место Ледяное сердце Исулдофа, Щит Эсиритса, Посох Неистовства Бури и Древнюю броню Квалдира. Когда поручение будет выполнено, вернитесь к Орфусу Камагуанскому на Древний подъемник.', 'Печальные известия, $N. Мои люди в опасности, и их следует предупредить. Эти морские твари не пощадят Калу\'ак.', 'Дело сделано? Духи упокоились с миром?', NULL, NULL, 'Щит Эзиритов возвращен на место', 'Посох неистовства бури возвращен на место', 'Ледяное сердце Исулдофа возвращено на место', 'Древняя квалдирская броня возвращена на место');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11569, 'Хранитель ключей Ургргрл', 'Мне нужно выбраться из этих пещер! Из Хладарры, сверху, просвечивается какая-то магическая энергия и сводит всех с ума.$B$BЯ не хочу, чтобы меня взяли под контроль, как остальных!$B$BТам, ниже и к югу, в пещере, находится хранитель ключей Ургргрл; ключ от моей клетки – у него. Забери у него ключ и принеси сюда, чтобы я мог отпереть клетку и выбраться отсюда.$B$BСкорее!', 'По просьбе Глрглрглра в пещерах Зимних Плавников раздобудьте ключ Ургргрла.', 'Дай же, дай мне его скорее!', 'Ну, где же ключ?$B$BНет, до других мне нет никакого дела. Я просто хочу убраться отсюда!', NULL, NULL, 'Ключ Ургргрла', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11570, 'Бегство из пещер Зимних Плавников', 'Замок на моей клетке выглядит не особо прочным, но глупо было бы пытаться бежать без посторонней помощи.$B$BНе подсобишь ли мне выбраться из этих пещер? Нельзя терять ни минуты, $r!$B$BКогда вернешься в приют, пожалуйста, дай королю знать, что со мной все в порядке. Он наверняка вознаградит тебя!', 'Проводите Лургглбра в безопасное место и вернитесь к королю Мргл-Мрглу в Приют Зимних Плавников, чтобы сообщить ему хорошую новость.', 'Превосходное известие! Так значит, Лургглбр обнаружил, что безумие вызывают испарения этих пещер?$B$BДолжно быть, магия Хладарры становится все сильнее… Война Нексуса… битва между синими и всеми прочими драконами все разгорается.$B$BСкоро нас всех в это втянут!', NULL, NULL, NULL, 'Проводите Лургглбра в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11571, 'Обучение коммуникации', 'Чтобы помочь, тебе нужно научиться говорить на диалекте Зимних Плавников. В этом нам помогут силы природы и магии.$B$BВозьми эту пустую ракушку. На дне заполненного водой рва внизу обитает Скольдер – элементаль ярости воздуха и воды.$B$BКогда сразишь ее, воспользуйся ракушкой для того, чтобы уловить волшебный пар над ее останками. Принеси наполненную ракушку мне, и тогда я смогу передать тебе знание языка Зимних Плавников.$B$BТебе повезло – один друг научил меня заклинанию подводного дыхания, которое очень тебе пригодится.', 'Наполните ракушку, которую дал вам король Мргл-Мргл, над останками Скольдер. Верните наполненную ракушку короля Мрглу-Мрглу в Приют Зимних Плавников.', 'Теперь я смогу использовать сущность Скольдер для внедрения в тебя моего знания языка мурлоков Зимних Плавников.', 'Тебе удалось наполнить ракушку паром Скольдер?', NULL, NULL, 'Наполненная ракушка короля', 'Пустая королевская раковина', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11572, 'Возвращение к Атуику', 'Вернись к Старейшине Атуику в Камагуа. Надо предупредить его и остальных об угрозе, надвигающейся на них с моря. $B$B<Орфус вздрагивает.>$B$BЧтобы добраться до него, воспользуйся Древним подъемником. Но умоляю тебя, поторопись!', 'Доставьте тревожные известия старейшине Атуику в Камагуа.', 'Весь Калу\'ак благодарит тебя, $N. Теперь мы должны подготовиться к сражению и оповестить наших братьев и сестер на море. $B$BНадеюсь, мы еще не опоздали...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11573, 'Орфус Камагуанский', 'Приветствую тебя, $gпутешественник:путешественница:. Я – Тупобивень из племени Калу\'ак. Твой народ зовет нашу расу \"клыкарр\". Недавно меня с помощником послали разведать причину странных явлений на одной из наших охотничих троп. Но стоило нам приблизиться к западному кладбищу, известному как Заградительный холм, как на нас напали отряды нежити. Мне повезло – я смог добраться до этого лагеря, но судьба несчастного Орфуса мне не известна.$B$BНе $gмог:могла: бы ты отыскать его? Мы расстались возле Древнего подъемника, что к юго-востоку отсюда. Иди вдоль обрыва и убедись, что с ним все в порядке.', 'Найдите Орфуса Камагуанского на Древнем подъемнике в Ревущем фьорде.', 'Тупобивень жив? Ну, хоть одна хорошая новость за весь день...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11574, 'Переживания на грани', 'Я рассказала им все, что помню. Почему они мне не верят?$B$BЯ собирала травы у расселины. Они появились ниоткуда – темные волшебники с магическими зверями – и окружили меня!$B$BНадо мной возник волшебный ящик, он открылся и втянул меня внутрь. И когда он уже начал закрываться, тут-то и налетели мои спасители верхом на красных драконах. У меня аж дух захватило!$B$BЯ так и не поблагодарила их за спасение. Пожалуйста, $C, найди их и передай мою искреннюю признательность.', 'По просьбе Эндоры отправляйтесь на Янтарную Гряду к северу от крепости Песни Войны и поблагодарите тамошних обитателей за ее спасение.', 'Можешь сказать своей подруге, что ее спасение было нашей обязанностью, и притом приятной обязанностью.$B$BЕе случай был лишь маленьким фрагментом большой головоломки.$B$BДаларан не жалеет усилий для раскрытия этой тайны, и, честно говоря, нам не помешала бы кое-какая помощь...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11575, 'Своевременное спасение', 'Я рассказала им все, что помню. Почему они мне не верят?$B$BЯ собирала травы у расселины. Они появились ниоткуда – темные волшебники с магическими зверями – и окружили меня!$B$BНадо мной возник волшебный ящик, он открылся и втянул меня внутрь. И когда он уже начал закрываться, тут-то и налетели мои спасители верхом на красных драконах. У меня аж дух захватило!$B$BЯ так и не поблагодарила их за спасение. Пожалуйста, $C, найди их и передай мою искреннюю признательность.', 'По просьбе Мушки из крепости Отваги отправляйтесь на Янтарную гряду к северу и поблагодарите тамошних обитателей за ее спасение.', 'Можешь сказать своей подруге, что ее спасение было нашей обязанностью, и мы исполнили ее с радостью.$B$BЕе случай был лишь маленьким фрагментом большой головоломки.$B$BДаларан не жалеет усилий для раскрытия этой тайны, и, честно говоря, нам не помешала бы кое-какая помощь...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11576, 'Наблюдения за расселиной: обнаружена аномалия', 'Приветствую тебя, $r. Я Гаррен, из Даларана.$B$BНе так давно Расселина была еще весьма мирным местом, по крайней мере, в геотермальном отношении.$B$BОднако недавно начались все учащающиеся землетрясения, появились разломы в земле, сквозь которые проглядывают необыкновенные поля хаотической энергии.$B$BМоя задача здесь – составить список аномалий и наблюдать за ними. Мои инструменты показывают, что еще одна аномалия появилась на утесе к юго-западу отсюда.$B$BВозьми с собой этот прибор и воспользуйся им, когда найдешь новый раскол.', 'По просьбе Гаррена с Янтарной гряды воспользуйтесь тайнометром у аномалии утеса Западной расселины.', 'Поразительно! Это пока что самая большая аномалия.$B$BНо, боюсь, худшее еще впереди.', 'Тебе удалось собрать нужные мне данные, $C?', NULL, NULL, 'Замеры у аномалии утеса Западной расселины произведены', 'Тайнометр', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11580, 'Осквернение огня', '', '', 'Оскверните большой костер Орды в Серебряном бору!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11581, 'Осквернение огня', '', '', 'Оскверните большой костер Альянса в Западном крае!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11582, 'Наблюдения за расселиной: Расколотая бездна', 'Чувствуешь? Это был уже последний толчок... а что тут творилось несколько минут назад!$B$BБоюсь, мне снова придется попросить тебя о помощи. Мои инструменты указывают, что неподалеку, к западу отсюда, глубоко под водой образовалась огромная расщелина.$B$BКак и раньше, мне нужно, чтобы ты $gвзял тайнометр и зафиксировал:взяла тайнометр и зафиксировала: данные этой аномалии.$B$BЯ применю заклинание, которое позволит тебе дышать под водой. Если срок действия заклинания истечет раньше, чем ты найдешь аномалию, возвращайся ко мне – я его обновлю.', 'По поручению Гаррена с Янтарной гряды воспользуйтесь тайнометром у Расколотой бездны и возвращайтесь к нему с полученными данными.', 'Какая-какая она по размеру?!$B$BНевероятно! Я должен немедленно сообщить в Даларан!', NULL, NULL, NULL, 'Замеры у Расколотой бездны произведены', 'Тайнометр', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11583, 'Поклонение огню', '', '', 'Поклонитесь огню Западного края.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11584, 'Поклонение огню', '', '', 'Поклонитесь огню Серебряного бора.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11585, 'Бдение Адского Крика', 'Тром-ка, $r! Добро пожаловать в крепость Песни Войны. Мое сердце поет от радости, что столь $gпрославленный герой Орды откликнулся:прославленная героиня Орды откликнулась: на призыв, вняв чувству долга!$B$BЭта неприступная крепость – свидетельство невероятной стойкости Орды. Через многие препятствия пришлось нам пройти, чтобы создать этот плацдарм на Нордсколе. Именно отсюда начнется наш поход к леднику Ледяной Короны, и сын Адского Крика приведет нас к успеху!$B$BГаррош ждет твоего прибытия там, внизу.$B$BЛок\'тар огар!', 'Поговорите с Гаррошем Адским Криком в крепости Песни Войны.', 'Герой Орды, ты?$B$B<Гаррош обнюхивает воздух вокруг вас.>$B$BСтрахом пахнет…$B$B<Гаррош презрительно сплевывает.>$B$BТы долго не продержишься.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11586, 'Бдение Адского Крика', 'Тром-ка, $r! Добро пожаловать в крепость Песни Войны. Мое сердце поет от радости, что столь $gпрославленный герой Орды откликнулся:прославленная героиня Орды откликнулась: на призыв, вняв чувству долга!$B$BЭта неприступная крепость – свидетельство невероятной стойкости Орды. Через многие препятствия пришлось нам пройти, чтобы создать этот плацдарм на Нордсколе. Именно отсюда начнется наш поход к леднику Ледяной Короны, и сын Адского Крика приведет нас к успеху!$B$BГаррош ждет твоего прибытия там, внизу.$B$BЛок\'тар огар!', 'Поговорите с Гаррошем Адским Криком в крепости Песни Войны.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11587, 'Побег из тюрьмы', 'Приветствую тебя, $C. Я – Донатан, верный слуга Даларана.$B$BИзвини, я сразу к делу. У нас крупные проблемы. По всему Азероту начали исчезать маги, и мне поручено привлекать любого, кто способен помочь разгадать эту тайну.$B$BНаше расследование начнется в лагере к югу отсюда. Я призываю тебя помочь освободить одного из пленных магов, которого там держат. Для этого надо добыть ключ от магической клетки у одного из охотников на магов...', 'По просьбе библиотекаря Донатана с Янтарной гряды добудьте берилловый магический ключ у охотника на магов в Берилловом лагере и используйте его, чтобы освободить пленного мага из магической клетки.', 'Молодец, $N! Кирин-Тор благосклонно принимает оказанную тобой помощь. Знай, что ни одна твоя услуга не останется без награды!$B$BПрошу тебя, прими этот скромный дар в знак признательности Даларана.', NULL, NULL, NULL, 'Освобождено пленных магов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11590, 'Похищение', '$N, у нас тут возникла проблема.$B$BЯ только что узнал, что один из наших верховных магов по пути из Даларана пропал. Точнее, пропала. Естественно, мы полагаем, что за этим исчезновением стоят охотники на магов.$B$BВремя не ждет. Мы должны сейчас же разузнать, что случилось с леди Эванор, если хотим, чтобы у нас осталась надежда на ее спасение.$B$BВозьми этот прибор. Возвращайся в Берилловый лагерь и воздействуй этим прибором на одного из берилловых колдунов, когда он будет при смерти. Это должно связать его на достаточно долгий срок, чтобы привести его сюда для допроса.', 'Заключите в магические оковы раненого бериллового колдуна в Берилловом лагере и возвращайтесь вместе с ним к Донатану.', 'Отличная работа, $N.$B$BСейчас он будет готов к допросу.', 'Тебе уже удалось захватить бериллового колдуна, $N?', NULL, NULL, 'Пленный берилловый колдун', 'Магические оковы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11591, 'Явиться в караван Стальной Челюсти', 'Этот слабоумный, Стальная Челюсть, попытался провести наш караван с припасами напрямик через кладбище таунка!$B$BИ это тогда, когда нам только-только удалось наладить с ними отношения!$B$BВ результате караван теперь разгромлен и разметан духами таунка, которые встали из могил, через которые он поперся.$B$BСтупай на юг, $C, и посмотри, не сумеешь ли ты спасти положение. Я послал с караваном рубаку Гневную Длань и нескольких других воинов.$B$BСтупай, посмотри, может ты там пригодишься.', 'Поговорите с рубакой Гневной Дланью в караване Стальной Челюсти.', 'Плохо дело, $C.$B$BВыносливый гонец Гордое Копыто говорит, что тут погребены его почитаемые предки…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11592, 'Мы ударим!', 'Один из ваших – орк по имени Стальная Челюсть – пытался сэкономить себе немного времени и срезать дорогу, пройдя по нашему кладбищу. Хорошо бы это был единичный случай, нетипичный для Орды, $r, а не то таунка покончат с вами!$B$BНо, как мне кажется, ты хочешь помочь исправить положение. Отлично!$B$BПроклятый дух Стальной Челюсти блуждает теперь там и беспокоит останки моих предков. Мы должны положить этому конец!$B$BЕсли мы с этим справимся, отправишься с рассказом к властителю Бор\'гороку на заставу к северу отсюда.$B$BНу что, $gсогласен:согласна:?', 'Помогите выносливому гонцу Гордому Копыту и его налетчикам Песни Войны выжить во время нападения на караван Стальной Челюсти и прикончить дух командира соединения Стальной Челюсти.В случае успеха доложитесь властителю Бор\'гороку на заставе Бор\'горока.', 'Клянусь кровью и громом! Наши едва установленные отношения с таунка спасены благодаря тебе.$B$BСпасибо за нормализацию ситуации. Ака\'Магош, $N!', NULL, NULL, NULL, 'Помощь выносливому гонцу Гордому Копыту успешно оказана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11593, 'Последние почести', 'Наши павшие заслуживают настоящего геройского погребения, но мы не можем похоронить их на священном кладбище таунка.$B$BЯ не буду просить тебя притащить сюда их тела, но – вот, возьми этот факел и отправляйся вглубь кладбища. Когда наткнешься на останки охранников и погонщиков, сожги их с помощью факела.$B$BПочти павших, $C!', 'По просьбе рубаки Гневной Длани близ каравана Стальной Челюсти используйте факел Гневной Длани для сожжения мертвых стражей каравана и рабочих каравана (10 тел в любой комбинации).', 'Спасибо, $C. Мы – Орда, мы не оставляем наших мертвых лежать там, где их застигла смерть!$B$BНу, для начала, всего этого вообще не должно было понадобиться... Стальная Челюсть был глупцом!', NULL, NULL, NULL, 'Сожжено мертвых охранников и погонщиков каравана', 'Факел Гневной Длани', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11594, 'Пусть обретут покой!', 'Это все из-за тупости командира соединения Стальной Челюсти! Хватило же ума потащить караван через погребальный курган таунка!$B$BНу что ж, сделанного не вернешь! Остается только разгребать последствия.$B$BВластитель Бор\'горок велел мне помогать выносливому гонцу Гордое Копыто, чем только можно. Гонец попросил меня помочь упокоить духов его предков.$B$BЧто скажешь, $C? Хватит ли тебе сил на такое несложное задание?', 'Упокойте 20 духов таунка, фантомных ведунов либо восставших выносливых гонцов, и сообщите об этом рубаке Гневной Длани, который ожидает в Караване Стальной Челюсти.', 'Молодец, $C! Тебе, должно быть, не впервой сражаться с нежитью. Ну, а если для тебя это был первый раз, то теперь у тебя имеется ценный опыт!$B$BЭтот опыт пригодится тебе, если ты хочешь выжить в Нордсколе.', NULL, NULL, NULL, 'Упокоено духов таунка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11595, 'Оборона крепости Песни Войны', 'Адский Крик в ответе за всю Орду, $N. Это тяжкая ноша. Так что не отказывайся от выполнения своих обязанностей из-за его дурного нрава.$B$B<Саурфанг кивает.>$B$BА ты думаешь, я мог забыть имя героя Оргриммара? Не каждый день приходится видеть голову Нефариана на пике!$B$BПлеть начала осаду этой крепости. Наши солдаты держат оборону, но мы отчаянно нуждаемся в подкреплении. Отправляйся к Разгору. Он находится под стеной крепости Песни Войны.', 'Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11596, 'Оборона крепости Песни Войны', 'Не позволяй Адскому Крику уговорить тебя пренебречь своими обязанностями в качестве воина Орды, $r. Здесь, на этих стылых пустошах, он несет свое тяжкое бремя, ведь неизвестно, чем все закончится – победой над Плетью или истреблением всего живого в Азероте. Именно поэтому нам требуются твоя сила и твоя мудрость.$B$BПлеть начала штурм этой крепости. Наши воины держат оборону, но отчаянно нуждаются в подмоге. Доложи Разгору. Он находится сразу за стенами крепости Песни Войны.', 'Доложитесь властителю Разгору, находящемуся в хижине на южной стороне крепости Песни Войны.', 'Как раз вовремя... Нерубы, кажется, удвоились в числе буквально за неделю. Мы ни от чьей помощи не откажемся.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11597, 'Оборона крепости Песни Войны', 'Похоже, мы с тобой всегда встречаемся в самую лихую годину, $gПовелитель:Повелительница: Скарабеев! Ведь в последний раз, когда мы виделись, ты тоже $gспасал:спасала: мир от какой-то смертельной опасности?$B$B<Саурфанг усмехается.>$B$BТвоя помощь очень пригодится Нордсколу, что бы там ни говорил юный вождь!$B$BБудь у нас еще хоть десяток таких воинов, как ты, мы бы сейчас спокойно сидели в Оргриммаре, у жаркого очага.$B$BОтправляйся к властителю Разгору, он у главного входа в крепость Песни Войны, на юге.', 'Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11598, 'Отвоевывание карьера Камня Силы', 'В то время как крепость Песни Войны защищает со всех сторон по три метра стали и камня, этот карьер – незащищен и является первой целью для атак нерубов.$B$B<Разгор указывает на запад.>$B$BЗа этим карьером стоят тысячи воинов Плети, только и ждущие приказа к атаке. Если нерубы уничтожат наши внутренние линии обороны, нас тут же сметут легионы нежити Артеса.$B$BМы не можем этого допустить – поэтому ты $gдолжен напасть первым:должна напасть первой: и перебить нерубов в карьере.$B$BКровь и гром, солдат! Пусть и то, и другое сопровождают тебя в бою.', 'По заданию властителя Разгора из крепости Песни Войны убейте 15 неруб\'арцев.', 'Тебе удалось замедлить их продвижение, но все равно скоро в битву вступит еще больше. Тебе случайно не удалось найти их яйца, пока ты был в карьере?', NULL, NULL, NULL, 'Убито неруб\'арцев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11599, 'Тассариан, мой брат', 'Недавно Вильям Аллертон, друг нашей семьи, сообщил мне, что мой брат поступил на службу сюда, в крепость Отваги, в тот же день, что и он сам. Но дело в том, что… мой брат уже несколько лет как мертв!$B$BЯ продала все, чем владела, и приехала сюда искать Тассариана, но местные бюрократы ничего не хотят мне сообщать. Мне даже пригрозили арестом, если я буду и дальше тут ошиваться!$B$BМне нужен кто-то, кто был бы вхож к местному начальству... кто-то вроде тебя! Если ты не откажешь мне в помощи... Я слышала, что Вильям служит на шахте Далечья.', 'Найти Вильяма Аллертона в шахте Далечья.', 'Труп подходит под описание Вильяма Аллертона, которое дала вам Лерисса. Как ни странно, на нем не заметно следов ни от когтей, ни от зубов…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11600, 'Последние новости о Вильяме Аллертоне', 'Горло Вильяма перерезано чем-то острым.$B$BПри дальнейшем осмотре тела нашлась лишь единственная зацепка для Лериссы – воинское удостоверение на имя Вильяма Аллертона.', 'Отнесите воинское удостоверение Лериссе в Крепость Отваги в Борейской тундре.', 'Ты думаешь, Вильям стал случайной жертвой Плети? Все это выглядит весьма подозрительно.$B$BЧто-то происходит. Нам нужно найти Тассариана.', 'Удалось поговорить с Вильямом, $N?', NULL, NULL, 'Воинское удостоверение (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11601, 'Потерянный и обретенный', 'Возможно, бедный мистер Аллертон все-таки поможет нам отыскать моего пропавшего брата!$B$B<Лерисса достает объемистую книгу, смахивающую на ту, куда записывают рекрутов.>$B$BНу да, я ее позаимствовала, и что такого? Посмотрим, какого числа он поступил на службу?$B$BВильям видел Тассариана в списке рекрутов. Значит, они поступили почти одновременно... вот он!$B$BОн записался в... отряд С? Все прочие воинские подразделения носят названия городов Альянса...$B$BА кто еще состоит в этом отряде? Где они сражаются? Нужно разузнать. Может, хозяину таверны что-нибудь известно?', 'Поговорите с Джеймсом Диконом в таверне в крепости Отваги.', 'Я мало чем могу помочь, друг. Но я знаю кое-кого, кто может.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11602, 'Прервать на корню', 'Воздушная рекогносцировка карьера показала, что нерубы откладывают свои яйца на возвышениях, окружающих основание. Хитрые твари... Яйца лежат высоко и в сухом месте, подальше от центра конфликта.$B$BТебе придется вернуться туда и отследить, где лежат яйца. Найди их, разбей и уничтожь.$B$BКаждое уничтоженное яйцо – это на двадцать меньше воинов Неруба, жирующих на наших трупах.', 'По поручению властителя Разгора, находящегося в крепости Песни Войны, уничтожьте 10 неруб\'арских яиц.', 'Что бы мы ни делали, они все прибывают. Еще немного, и мы можем не выдержать, $N.', NULL, NULL, NULL, 'Яйца неруб\'аров уничтожены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11603, 'Истина в вине', 'Военная служба – это все, что было у старика Колберна. Когда он вышел в отставку, то продолжал живо интересоваться всем, что связано с армией, словно это было для него жизненно важно. Он знал имя каждого генерала, отряда, бригады, подразделения... буквально всё. Он – человек, который тебе нужен.$B$BПроблема в том, что у него неладно с головой. Он ни с кем не станет разговаривать, пока не глотнет своего кул-тирасского вина. Тогда он тут же вспоминает о временах, когда был моряком.$B$BЯ уже давненько не получал от поставщиков этого вина. Последний торговый корабль из Кул-Тираса затонул к северо-востоку отсюда. Посмотри – может, тебе удастся раздобыть бутылку, чтобы принести ее Колберну?', 'Раздобудьте бутылку кул-тирасского вина на месте кораблекрушения к северо-востоку от Крепости Отваги и принесите старику Колберну в таверну в Крепости Отваги.', 'М-мм... не слишком горькое... и не слишком сухое... Такое же, как мы пивали с ребятами в казармах в былые времена.', '<Старик смотрит на вас с отсутствующим выражением лица.>', NULL, NULL, 'Кул-тирасское вино', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11604, 'Дезертир', 'Отряд С, отряд С… хм… ерунда какая-то… Отряды называются по городам.$B$BТемнолесцев отправили в Драконий Погост. Ребят из Златоземья послали во Фьорд. А где же я…$B$BАх, да! Дезертир! В тюрьме при казармах был перебежчик. Его засадили не так давно. Он все говорил, что \"С\" значит \"самоубийство\".$B$BОтыщи этого дезертира. Возможно, он знает что-то, что тебе пригодится!', 'Найдите тюрьму во Внутренней крепости Отваги и поговорите с дезертиром.', 'Чего тебе надо? И без тебя тошно!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11605, 'Досточтимые предки', '<Далекий голос эхом звучит в вашей голове, пока вы рассматриваете каменное изваяние.>$B$BНе удивляйся, $gчужеземец:чужестранка:. Я – старейшина Атканок, древний предок клыкаррского народа, прославленный в свое время мастер, уже сотни лет находящийся на страже этого карьера.$B$BКарьер был опустошен, многие статуи остались незавершенными, а духи предков стали скитальцами. Поможешь ли ты мне исправить неправильное?$B$BДля начала я должен узнать имена этих неприкаянных предков. Поищи обозначения возле статуй.', 'По просьбе старейшины Атканока, находящегося у карьера Ледяного Булыжника, отыщите статуи, предназначенные для старейшины Кесука, старейшины Сагани и старейшины Такрета.', '<Голос старейшины Атканока приветствует вас, когда вы приближаетесь к его статуе.>$B$BХорошо, $N. Зная имена блуждающих духов предков, мы можем продолжить ритуал, прерванный нападением на карьер. Однако прежде чем можно будет препроводить духи старейшин в их изваяния, нам нужно успокоить духи убитых скульпторов и шамана. Иначе духи предков могут вообще не услышать зова ритуала.', '<Вы снова слышите далекий голос.>$B$BУдалось ли тебе разузнать имена неприкаянных предков?', NULL, NULL, 'Старейшина Кесук опознан', 'Старейшина Сагани опознан', 'Старейшина Такрет опознан', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11606, 'Терпение – добродетель, которая не требуется', 'Мы можем перебить всех нерубов, каких только увидим, и передавить все их яйца, какие найдем, но эти твари не перестанут прибывать, пока мы не взорвем их туннели и проходы. Конечно, мы не сможем этого сделать, не имея в арсенале мощных боеприпасов. К сожалению, большая часть наших запасов используется гоблинами и кузнецами для изготовления осадных танков и оружия.$B$BНо к счастью, есть очень неплохой запас того, что нам нужно, в карьере Силы Камня – под всей этой нерубской чепухой. Тебе нужно просто пойти и принести мне запасы.', 'По поручению интенданта Холгота раздобудьте 15 ящиков с боеприпасами Песни Войны.', 'Если мои расчеты верны – что, впрочем, бывает не так уж часто – тебе понадобится от 10 до 20 глубинных сефориевых зарядов.$B$BДа-да, ты установишь этих малюток прямо в их воронки!', 'Время на исходе, $C.', NULL, NULL, 'Боеприпасы Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11607, 'Заблудшие духи', 'Во время нападения на карьер работавшие там шаманы и ремесленники были убиты. Насилие повергло мир духов в хаос, и мы не сможем отправить предков домой, если не найдем способа утихомирить духов убитых. $B$BСами враги не обращают внимания на духов, но их спутники, берилловые гончие, чуют духов и держат их в рабстве. $B$BУбей берилловых гончих и, используя высвободившуюся чистую энергию, отпусти невинные души на волю.', 'Освободите дух 3 ремесленников клана Каскала и 3 шаманов клана Каскала по просьбе старейшины Атканока в окрестностях карьера Ледяного Булыжника.', 'Я чувствую, как смятение в мире духов мало-помалу затихает. Молодец, $N! Духам предков твоя помощь была как нельзя более кстати.', NULL, NULL, NULL, 'Освобождено духов ремесленников клана Каскала', 'Освобождено духов шаманов клана Каскала', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11608, 'Засыпать тараканьи норы!', 'Север, юг, восток и запад. Вот направления, которыми тебе предстоит заняться. Вокруг крепости в карьере Камня Силы расположены 4 неруб\'арские воронки.$B$B<Холгот передает вам сверток.>$B$BОсторожнее с ними, $N. Стоит что-то сделать не так – и ты труп.$B$BВнутри этого свертка – глубинные сефориевые заряды. Сходи ко всем неруб\'арским воронкам и установи заряды в центре каждой из них. Если все пойдет как надо, туннели завалит.$B$BДавай, вперед!', 'По поручению интенданта Холгота используйте сверток с глубинными сефориевыми зарядами для уничтожения неруб\'арских воронок к югу, востоку, западу и северу от крепости Песни Войны.', 'Это их остановит – по крайней мере, я надеюсь, что остановит. В любом случае, ты свое дело сделал. А о большем орк и просить не может, так ведь?', NULL, NULL, NULL, 'Южная неруб\'арская воронка уничтожена', 'Восточная неруб\'арская воронка уничтожена', 'Западная неруб\'арская воронка уничтожена', 'Северная неруб\'арская воронка уничтожена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11609, 'Сбор ритуальных предметов', 'Теперь, когда духи убитых ремесленников и шаманов упокоились, мы можем завершить ритуал, прерванный нападением. Тебе придется выполнять роль, которая по традиции отводится шаману клыкарров – а для этого тебе нужно иметь все необходимые ритуальные предметы.$B$BИзготовлять новые нет времени, поэтому нужно раздобыть те, что остались от жертв нападения. Обращайся с этими вещами бережно, $N, ведь некоторым из них по несколько сотен лет! Возможно, тебе придется отвоевывать их у захватчиков...', 'Принесите 6 клыкаррских ритуальных предметов старейшине Атканоку, который стоит у карьера Ледяного Булыжника.', '<Вы принесли предметы к статуе старейшины Атканока.>$B$BЭтого должно быть достаточно, хотя они и в жалком состоянии, увы! А ведь некоторые из них прослужили сотни лет – и все лишь затем, чтобы их терзали и трепали какие-то варвары!', 'Все ли ритуальные предметы удалось тебе отыскать?', NULL, NULL, 'Клыкаррский ритуальный предмет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11610, 'Возвращение предков', 'С твоей помощью духи предков смогут теперь направиться в достойные их обиталища – статуи, с любовью сделанные ремесленниками Каскалы и тамошним шаманом.$B$BРитуал возвращения предков был прерван во время нападения на карьер, и теперь тебе нужно будет завершить его. Возьми с собой предметы, добытые в карьере, встань перед наделенными именами статуями и продекламируй это.$B$B<Слова на странном, незнакомом языке наполняют ваше сознание, но вы запоминаете их без всякого труда.:', 'По просьбе старейшины Атканока проведите духов старейшины Кесука, старейшины Сагани и старейшины Такрета в их каменные изваяния.', 'Предки нашли свои статуи и благодарят тебя, $N. Ремесленники Каскалы вернутся в карьер и обеспечат непрерывность рода предков. А предки будут продолжать наблюдать за тобой с интересом: похоже, твой путь только начинается.', 'Ты завершил ритуал возвращения предков?', NULL, NULL, 'Церемония старейшины Кесука завершена', 'Церемония старейшины Сагани завершена', 'Церемония старейшины Такрета завершена', 'Клыкаррский ритуальный предмет');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11611, 'Захваченные Плетью', '$gМортуус вздыхает.>$B$BБатраки... С таким же успехом можно поставить рекламный щит с предложением бесплатной еды для неруб\'аров.$B$BПонимаешь, с батраками есть проблемы: во-первых, они тупее комка глины, а во-вторых, они слабее лепрогнома. Конечно, Плеть должна была их первыми и захватить!$B$BВ этом для меня есть небольшое затруднение – должно быть, тебе понятно: если не будет батраков, кто будет заниматься тяжелым ручным трудом? Нет батраков – нет строительства.$B$BНайди и освободи моих батраков, $r. Если они живы, то ты найдешь их запеленатыми в паутину по всему карьеру Камня Силы.', 'По заданию штейгера Мортууса из Крепости Песни Войны освободите 5 батраков клана Песни Войны.', 'Большинству из них удалось вернуться. По крайней мере, тем, у кого хватило ума сообразить, что мы внутри этих гигантских зданий из камня и металла…$B$BКак бы там ни было, ты хорошо справился с работой. Я слышал, тебе удалось освободить немало батраков.$B$BО да, ты теперь – первый парень на... ну... на крепости.', 'Нет батраков – нет зданий. И – нет, мы не собираемся заменять их гоблинами. Это нам чертовски дорого обошлось бы…', NULL, NULL, 'Батрак из клана Песни Войны освобожден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11612, 'Бой за карьер', 'Рад тебя видеть, $C. Меня зовут Этарук, и я был ремесленником здесь, в карьере Ледяного Булыжника.$B$BЯ и мои товарищи готовили новый комплект статуй для последней серии ритуалов, когда увидели, как эти таинственные синие платформы летят над плато.$B$BКогда они приземлились, карьер заполонили охотники на магов, пр$Nевшие на них, убивая моих товарищей и громя карьер. Если мы не остановим их, они уничтожат все наши статуи и сбегут с нашими артефактами. Поможешь ли ты мне одолеть захватчиков?', 'По просьбе Этарука, находящегося у входа в карьер Ледяного Булыжника, убейте 12 берилловых охотников за сокровищами.', 'Теперь, когда охотники на магов знают, что народ Каскалы и союзники не сдадут карьер просто так, мы должны удвоить наши усилия и нанести им окончательное поражение.$B$BМои братья в Каскале сами подверглись нападению и не смогут оказать нам поддержку, но с твоей помощью, $N, мы сможем справиться с этими грабителями.', NULL, NULL, NULL, 'Берилловый охотник за сокровищами убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11613, 'Клятва Карука', 'Они называют себя квалдирами. В моем народе бытуют легенды о них; мы называем их тук-харик – \"странники тумана\".$B$BМоя деревня была разрушена этими гигантскими туманными существами. Были убиты все, кого я знал, погиб и мой отец Ариут.$B$BСогласно клыкаррским обычаям, я должен искать мести тем, кто пролил кровь моего рода.$B$BНо я всего лишь рыбак, к тому же я даже не прошел испытание совершеннолетия... Я не выстою лицом к лицу со злобными квалдирами.$B$BЕсли бы ты $gмог:могла: взыскать долг крови вместо меня, я был бы очень тебе обязан.', 'По просьбе Карука убейте 6 скадирских налетчиков и 5 скадирских лодочников.', 'Ты оказал великую услугу моему народу, $N. Однако мне придется попросить тебя еще об одной...', NULL, NULL, NULL, 'Скадирский налетчик убито', 'Скадирский лодочник убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11614, 'Невысказанные истины', 'Мы здесь по приказу Вариматаса! Цель тенеловов проста: шпионить. Ну и еще убивать помаленьку.$B$BОдин из моих лучших агентов пропал. О нем уже несколько дней ни слуху, ни духу. Я опасаюсь худшего. Нет, не того, что его убили! Это был бы идеальный вариант. Я боюсь, что он дезертировал... возможно, даже предал нас!$B$BВ последний раз его видели на севере карьера Камня Силы. Он собирал сведения о воинах Неруба. Отыщи его.$B$BЛучше бы его убили...', 'Отыщите тенелова Лютера в карьере Камня Силы.', 'Да, мертвее не бывает… Странно, что нерубы не сожрали труп.$B$BПосле тщательного осмотра вы приходите к выводу, что это было самоубийство – Лютер отравился. Умно. К отравленному трупу нерубы на выстрел не подойдут.$B$BВ руке у Лютера зажат дневник...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11615, 'Неруб\'арские тайны', 'Вы листаете страницы книги в поисках чего-нибудь важного. На последней странице вы обнаруживаете нацарапанное диковинными каракулями:$B$BНекролорды. Как минимум дюжина, по моим подсчетам.$B$BФермы к западу используются как какие-то чудовищные инкубаторы Плети.$B$BЖертвы – ряд за рядом.$B$BДумаю, они теперь за мной идут. Бросился к крепости. Живым я не дамся.$B$BЖуткоядый гемотоксин. Если они решат меня погрызть, их ждет сюрприз.$B$BДоставьте эту информацию Бартусу.', 'Доставьте дневник Лютера тенелову Бартусу в Крепость Песни Войны.', '<Бартус быстро перелистывает дневник к последней странице и начинает читать.>$B$BЭто очень плохие новости. Адский Крик должен быть немедленно извещен об этом.', 'Он мертв?', NULL, NULL, 'Дневник Лютера (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11616, 'Послание Адскому Крику', '*Бартус вырывает последнюю страницу и скатывает ее в трубочку.*$B$BНемедленно доставь это Адскому Крику! А я тем временем отправлю отряд, чтобы разведать обстановку на фермах.$B$BНепременно скажи Адскому Крику, что нам понадобится подкрепление.', 'Отнесите записку Бартуса Гаррошу Адскому Крику в крепости Песни Войны.', '*Адский Крик читает записку.*$B$BЭто все?', 'Это еще что такое? Мне не до пустяков!', NULL, NULL, 'Записка Бартуса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11617, 'Никто не должен уйти', 'Я уверен, что ты $gвидел:видела: эти синие и белые платформы, летающие над карьером. Эти транспортные средства охотники на магов использовали для переброски своих сил, а теперь они нагружают их нашими артефактами и фрагментами наших статуй!$B$BМы должны остановить их, пока они не покинули карьер.$B$BМаленькие создания, копающиеся в карьере, носят с собой взрывчатку. Возьми их и используй для того, чтобы уничтожить три плавающие в воздухе платформы. Их вожак наблюдает за происходящим с четвертой, приземлившейся платформы, но с ним мы разберемся потом.', 'По поручению Этарука из карьера Ледяного Булыжника уничтожьте Северную, Восточную и Западную платформы.', 'Охотники на магов поймут, что разорить наш карьер и разграбить наши артефакты не так просто, как они думали. С твоей помощью мы отвоюем карьер и все восстановим.', NULL, NULL, NULL, 'Восточная платформа уничтожена', 'Северная платформа уничтожена', 'Западная платформа уничтожена', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11618, 'Подкрепление на подходе…', '$gАдский Крик качает головой.>$B$BТы, возможно, не $gзаметил:заметила:, $r, но мы тут пытаемся выиграть войну. Все, кто способен сражаться, отправлены в ключевые точки. А это значит, что на такие мелкие вторжения бойцов у нас уже не осталось.$B$B<Адский Крик делает паузу, чтобы поразмыслить.>$B$BНо Бартус требует подкрепления на ферме...$B$B<Адский Крик хлопает себя по лбу.>$B$BИ он их получит! Ступай к убийцам Бартуса на фермах, к западу отсюда. И дай им знать, что подкрепление прибыло.', 'Отыщите тенелова Икориса на заставе у ферм Песни Войны к западу от крепости Песни Войны.', 'И это все?! Один-единственный $R? $B$BБудь моя челюсть на месте, я уронил бы ее на пол!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11619, 'Геймел Жестокий', 'Моего отца убил предводитель этих разбойников, Геймел Жестокий. Он живет в пещере на берегу.$B$BС его людьми тебе покончить удалось. Доверши же начатое, $N! Отомсти за моего отца, и я поделюсь с тобой тем немногим, что у меня осталось.', 'Убейте Геймела Жестокого с Берега Терзающего Бича по просьбе Карука.', 'Да, $N, Геймел побежден! Теперь духи убитых клыкарров могут упокоиться в мире – их смерть отомщена!', 'Удалось ли тебе одолеть Геймела, $C?', NULL, NULL, 'Геймел Жестокий убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11620, 'Отцовские слова', 'Есть кое-кто, кто мог бы пролить свет на эту тайну, $r. Ходят слухи, что квалдиры держат живую жрицу-нагу в храме на западной стороне берега.$B$BОна-то, без сомнения, имеет все основания взъяриться на своих незваных квалдирских гостей. Возможно, моему отцу кажется, что она будет с тобой сотрудничать.', 'Поищите Вихью у святилища Чешуи на берегу Терзающего Бича.', 'Хссссссссссссс! Ты явился, чтобы насмехаться надо мной, $R?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11621, 'Табличка Левирота', 'Вы корпите над тем, что нацарапано на табличке, пытаясь найти хоть какой-то понятный текст. Наконец, вам удается прочесть следующий фрагмент:$B$B\"Сыновья тумана востребуют тысячу душ для того, кто обитает во мраке глубин. И тогда пробудится его посланец.\"$B$BДолжно быть, это заинтересует Карука.', 'Возвращайтесь к Каруку с информацией, обнаруженной вами на табличке.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11622, 'Тайны Терзающего Бича', 'Есть некто, кто способен пролить свет на эту тайну, $r. Ходят слухи, что квалдиры держали живыми в храме нескольких жриц-наг.$B$BИ верховная жрица, Вихья, явно имеет причины недолюбливать их за непрошеное гостеприимство. Быть может, она расскажет тебе, что означает надпись на табличке.', 'Найдите Вихью на развалинах Терзающего Бича в Борейской тундре.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11623, 'Визит к смотрителю', 'Силы охотников на магов возглавляет жуткое создание по имени смотритель Инзивиус. Бесчисленные поколения моего народа охотятся на морских тварей, но таких, как этот смотритель, мы никогда не видали. $B$BОн разместился на одном из летающих дисков на верхней кромке карьера и оттуда наблюдает за происходящим. $N, я могу только верить, что сами предки послали тебя мне в помощь, и надеюсь, ты поможешь мне выдворить охотников на магов из этого карьера раз и навсегда.', 'По заданию Этарука с края карьера Ледяного Булыжника убейте смотрителя Инзивиуса.', 'Смотритель и его подчиненные, должно быть, думали, что карьер станет для них легкой добычей, но ты показал им, как они ошибались, $N. Я глубоко благодарен тебе за помощь и уверен, что предки не лишат и впредь тебя своего благосклонного внимания.', NULL, NULL, NULL, 'Смотритель Инзивиус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11624, 'Небо знает', 'Мне нужно выяснить, что случилось с моим наставником, предсказателем Печальным Путником!$B$BЕще недавно он наблюдал за магнатаврами у Магмота. Но только что вернулся один из его рубак, он говорит, что отряд разбит, а предсказателя утащили в недра Магмота.$B$BНо, чтобы не отправить тебя навстречу верной смерти, мне нужно посоветоваться с духами.$B$BВ руинах Элдра\'ната к западу отсюда обитает элементаль воздуха, которую зовут Империан. Она мудра и, возможно, сообщит тебе нужные сведения.', 'Поговорите с Империан в руинах Элдра\'ната.', 'Не глупо ли было являться сюда, маленький $R? Чего ты ищешь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11625, 'Трезубец Наз\'жана', 'Пятьсот лет назад Азшара заключила в подводную темницу существо по имени Левирот. А теперь эти варвары хотят уничтожить труды нашей королевы!$B$BОни заняли наш город и начали приносить в жертву моих братьев, чтобы пробудить его! Когда наги кончились, они принялись за клыкарров. Их духи не будут ведать покоя!$B$BЯ помогу тебе, потому что это так или иначе поможет мне утолить мою месть. Их капитан, Рагнар, обитает в глубине Руин Терзающего Бича, в северо-восточной их части. Он владеет золотым трезубцем. Принеси мне его!', 'Отправляйтесь к дальнему северо-восточному краю Руин Терзающего Бича. Убейте Рагнара Драккарлунда, завладейте трезубцем Наз\'жана, а затем отнесите его Вихье на берег Терзающего Бича.', 'Хорошшшшшо! Мы убьем квалдирских зверей! Я покажу эти мерзавцам, что не стоит заступать путь жрице чешуи!', 'Ты уже раздобыл трезубец?', NULL, NULL, 'Трезубец Наз\'жана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11626, 'Посланник', 'Раж Наз\'жан был императором Терзающего Бича, когда был пленен Левирот. Сама Азшара благословила его трезубец так, что он убил бы чудовище, если бы оно попыталось бежать.$B$BТеперь он у тебя, $r. Хотя мне это претит, я все же отомщу этим жестоким великанам.$B$BВозьми трезубец и отправляйся в глубины под Терзающим Бичом. Там, под ближайшим к северной части берега айсбергом, ты и найдешь Левирота.$B$BВонзи трезубец в его плоть и убей его! Возвращайся потом к тому, кто тебя послал; а я желаю больше никогда тебя не видеть.', 'Найдите Левирота в водах под айсбергом, плавающим у северной окраины Руин Терзающего Бича. Воспользуйтесь трезубцем Наз\'жана, чтобы убить Левирота и возвращайтесь к Каруку, ожидающему вас на севере берега Терзающего Бича.', 'Духи моих соплеменников могут наконец успокоиться. Ты помог мне отомстить за отца... Может быть, однажды я тоже стану таким же сильным, как ты.', NULL, NULL, NULL, 'Левирот убито', 'Трезубец Наз\'жана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11627, 'Точка кипения', 'А, это информация, которая так тебе нужна: местонахождение и состояние твоего \"предсказателя\". Хорош предсказатель – не смог предвидеть поджидающей его самого беды.$B$BТем не менее я дам тебе средства, с помощью которых можно получить знание. Но сначала сделай кое-что для меня.$B$BБез сомнения, ты $gвидел:видела: битву огня и воды, что протекает к югу отсюда. Шкварчун не перестает нагревать пруд Вспеннера, и поэтому эти двое враждуют уже не первый век.$B$BОтправляйся на Обугленную вершину и Кипящий пруд и убеди каждого прекратить междоусобицу.', 'По просьбе Империан нанесите поражение Шкварчуну и Вспеннеру, а затем вернитесь к ней в руины Элдра\'ната.', 'Я довольна, хотя, конечно, они еще некоторое время будут ссориться.$B$BОднако тебе, прежде чем вернуться к твоей говорящей с духами, придется выполнить кое-что еще.', NULL, NULL, NULL, 'Шкварчун покорен', 'Вспеннер покорен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11628, 'Нечистое должно послужить чистому', 'К северо-востоку отсюда расположен храмовый город Эн\'кила – оплот Плети в Борейской тундре. Из-за его стен командующий силами Плети послал своих нерубов, чтобы окружить нас.$B$BОстаться в обороне означает смерть для моего народа, но мои советники разошлись во мнениях касательно стратегии. Дурм считает, что надо просто кинуться в атаку, а ведунья Эйри – что лучше сделать все скрытно.$B$BХрамовый город отравил окружающие земли и их обитателей. Эйри считает, что из шкур порабощенных Плетью мамонтов можно сделать плащ, который скроет от глаз Плети того, кто туда проберется.', 'Принесите вождю Зимней Стуже в деревню Таунка\'ле 5 оскверненных шкур мамонта.', 'Хотя я терпеть не могу, когда столь нечистые вещи приносят сюда, в деревню, они могут дать нам преимущество над врагами.$B$B<Вождь делает знак ведунье Эйри и машет рукой, чтобы шкуры поскорее убрали.>$B$BПока она обрабатывает шкуры, мы займемся добыванием еще одного компонента, необходимого для изготовления плаща.', 'Ты принес шкуры мамонта?', NULL, NULL, 'Оскверненная Плетью шкура мамонта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11629, 'Назад, к говорящей с духами', 'Ты $gсделал:сделала: то, о чем тебя просили, и теперь я дам тебе то, чего ты желаешь.$B$BОтнеси эту изначальную сущность говорящей с духами на заставу Бор\'горока. Если она мудра, то знает, какой ритуал нужен, чтобы добыть информацию, которую ты ищешь.', 'Доставьте изначальную сущность Империан говорящей с духами Рычеклык на заставу Бор\'горока.', 'Империан дала тебе свою собственную изначальную сущность? Да, я слышу, как ревут ее ветры!$B$BЯ знаю ритуал, который нам поможет. Но надо спешить, пока ее изначальная сущность не взорвалась изнутри!', '$N, ты снова здесь. Что тебе удалось узнать?$B$BЧто это за звук?', NULL, NULL, 'Изначальная сущность Империан (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11630, 'Оскверненная Плетью земля', 'Ведунья Эйри считает, что после обработки шкур оскверненной Плетью землей из окрестностей храмового города она сделает плащ, который поможет тебе оставаться $gнезамеченным:незамеченной: для приспешников Плети. Ты просто сольешься с ландшафтом, так она говорит.$B$BХорошо бы, она оказалась права. Это наш единственный шанс добыть информацию и составить план контратаки.$B$BТы $gдолжен:должна: найти нужную ей землю, покопавшись в почве к югу и к западу от крепости. Принеси ее мне, когда соберешь столько, сколько нужно.', 'Принесите 8 комков оскверненной Плетью земли вождю Зимней Стуже в деревню Таунка\'ле.', '<Вождь Зимняя Стужа с предосторожностями принимает принесенные вами комки земли.>$B$BМы должны передать землю в руки ведуньи Эйри как можно скорее.$B$B<Вождь ворчит, пытаясь сделать вид, что его ничуть не беспокоят эти зловещего вида грязные комья.>$B$BВедь мы не знаем, когда командующий силами Плети предпримет последнюю, решительную атаку на деревню.', 'Тебе удалось собрать землю, которая нужна ведунье Эйри для плаща?', NULL, NULL, 'Оскверненная Плетью земля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11631, 'Воздушные видения', 'Вот, $N, я настроила для тебя изначальную сущность.$B$BОткрой ей свою душу возле моего тотема воздуха и сконцентрируйся на судьбе предсказателя Печального Путника.$B$BДух ветра соприкасается со всем на свете. Если повезет, тебе будет даровано видение.', 'Воспользуйтесь изначальной сущностью Империан для проведения ритуала возле тотема говорящей с духами Рычеклык на заставе Бор\'горока, чтобы получить информацию о предсказателе Печальном Путнике.После этого поговорите с говорящей с духами Рычеклык.', 'Они заковали его дух! $N, нам нужно положить конец этой пытке!$B$BТебе нужно спуститься в недра Магмота и найти способ его освободить!', 'Когда почувствуешь, что увиденного достаточно, верни мне изначальную сущность.', NULL, NULL, 'Судьба предсказателя Печального Странника известна', 'Изначальная сущность Империан', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11632, 'Что несет холодный ветер?..', 'Вы держите в руках фрагмент панциря Ит\'рикса Жнеца и понимаете, что это только начало. Даже сейчас вас одолевает ощущение непрочности победы. Бесспорно, у Короля-лича найдется еще тысяча таких тварей, как Ит\'рикс, ждущих своей очереди, чтобы обрушиться на Орду.$B$BВозьмите свой трофей и передайте верховному правителю Саурфангу в Крепость Песни Войны. Его нужно известить о вашей победе над могучим посланником Плети.', 'Отнесите отвердевший панцирь Ит\'рикса верховному правителю Саурфангу в Крепость Песни Войны.', '', NULL, NULL, NULL, 'Отвердевший панцирь Ит\'рикса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11633, 'Вписаться в ландшафт', 'Ведунья Эйри закончила накидку. Возьми ее с собой и отправляйся в храмовый город Эн\'кила. Накинь плащ, когда войдешь в город – он скроет тебя от большинства созданий Плети. Это будет наилучшей возможностью собрать информацию об укреплениях и военном руководстве противника.$B$BНе снимая плаща, обследуй три высоких шпиля на территории города. В то время как накидка защитит тебя от большинства созданий Плети, поганища заметят тебя, если окажешься слишком близко к ним.', 'По поручению вождя Зимней Стужи отправляйтесь в храмовый город Эн\'кила, наденьте прочную накидку Плети и исследуйте Шпиль Крови, Шпиль Боли и Шпиль Порчи.', '<Вождь Зимняя Стужа внимательно слушает, пока вы описываете свои наблюдения.>$B$BИнформация, которую тебе удалось добыть, поможет нам составить план атаки на храмовый город. Нам нужно будет найти способ сразить указанных тобою офицеров и войти в этот некрополь.', 'Ты закончил исследование $Nей в крепости Плети?', NULL, NULL, 'Шпиль Порчи исследован', 'Шпиль Крови исследован', 'Шпиль Боли исследован', 'Прочная накидка Плети');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11634, 'Повелитель ветра То\'бор', 'Да, $N, $gотец:мать: из тебя чересчур $gсуровый:суровая:. Думаю, твои способности лучше пригодятся в другом деле – например, чтобы ликвидировать на корню саму эту проблему!$B$B<Разгор указывает на запад.>$B$BТысяча воинов Плети, минимум четыре полноразмерных машины смерти, и неизвестно что еще.$B$BВот ты-то и выяснишь, что именно. А потом постараешься совладать с этим... Да-да, я поручаю тебе задать перцу той самой армии, что сейчас задает жару нам.$B$BОтправляйся на вершину крепости Песни Войны и поговори с повелителем ветра То\'бором. Он ждет тебя.', 'Явитесь к повелителю ветра То\'бору в крепости Песни Войны.', 'Привет! Я ждал тебя$B$B<То\'бор указывает на запад.>$B$BГлянь-ка туда. Там, за тундрой – смерть. Смерть, понимаешь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11635, 'Дух предсказателя Печального Путника', 'Иди к Магмоту на восток.$B$BСпустись в глубь тамошних пещер.$B$BПоговори с духом предсказателя Печального Путника!', 'Поговорите с духом предсказателя Печального Путника в глубинах Магмота.', 'Спасибо за отсрочку, $C. Ах, если бы столь же легко достижимой была моя истинная свобода!..', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11636, 'Полет на ковре-самолете', 'Танки, $gдружище:сестренка:. Я об этих осадных машинах! У нас тяжелые танки есть в лагере Гарроша – ну, там, на западном берегу. Мы тебя подбросим до танка, а ты покатаешься на нем и маленько покажешь Плети, в чем ордынская правда, $gбрат:сестра:!$B$BПроблема будет только в том, чтобы тебя туда доставить. На ветрокрылах мы никак тебя не пошлем, факт – слишком много риска.$B$BВидишь вон того милашку? Эльфа такого блондинистого? Янни его зовут, $gбрат:сестренка:. Он-то может тебя на берег доставить без проблем. А как будешь там, поговори с крушителем Грек\'лором.', 'Поговорите с Янни в крепости Песни Войны, чтобы организовать вам безопасную доставку на побережье. Когда прибудете в лагерь Гарроша, поговорите с крушителем Грек\'лором.', 'НЕТ ПОЩАДЫ МЕРТВЫМ!$B$BНи у кого не хватило духу остаться защищать наши прославленные танки после того, как Адский Крик решил, что с побережья придется уйти. Теперь здесь спокойно, хотя Плеть и собирает силы для штурма крепости Песни Войны. Иногда мне удается наткнуться на заблудившегося зомби или вурдалака, но их надолго не хватает.$B$BА еще этот туман...$B$B<Грек\'лор вздрагивает.:', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11637, 'Каганишу', 'Когда мой небольшой отряд пехотинцев был перебит, меня притащили сюда, вниз и совершили ритуальное убийство. Снобольд, который сделал это, известен под именем Каганишу.$B$BХотя ты уже $gсразил:сразила: его помощников-шаманов, мой дух по-прежнему привязан к этому месту. После того как он убил меня, он изготовил амулет из моего тела, который и держит меня здесь. Каганишу использует его, чтобы узнать все, что я знаю о шаманском искусстве.$B$BТы $gдолжен:должна: забрать у него амулет и воздействовать им на мой дух. Каганишу обитает здесь рядом, в пещерах.$B$BТолько тогда я буду по-настоящему свободен.', 'Добудьте амулет Каганишу и задействуйте его над останками предсказателя Печального Путника.Вам нужно будет передать амулет предсказателю Печальному Путнику в Магмоте.', 'Я свободен. Спасибо, $N.$B$BА теперь у меня есть к тебе еще одна, последняя просьба.', 'Поспеши, $C, используй амулет, пока не стало слишком поздно.', NULL, NULL, 'Предсказатель Печальный Путник освобожден', 'Амулет Каганишу', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11638, 'Вернуть мои останки', '$N, теперь, когда мой дух свободен, не окажешь ли ты мне честь, вернув мои останки говорящей с духами Рычеклык? Они лежат на земле подо мной.$B$BЯ чую, что говорящая с духами по-прежнему на заставе Бор\'горока на западе, где мы виделись с ней в последний раз.', 'Доставьте останки предсказателя Печального Путника, которые покоятся под его духом, говорящей с духами Рычеклык на заставу Бор\'горока.', 'Спасибо тебе за то, что освободил его дух от Каганишу и вернул мне его останки. Чем же тебя вознаградить? Мы не богаты, но ты можешь взять в награду то, что тебе приглянется.$B$BТеперь же я верну его туда, где ему место.', 'Ты вернулся быстрее, чем я рассчитывала. Что тебе удалось выяснить?', NULL, NULL, 'Останки Печального Путника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11639, 'Месть в Магмоте', 'Властитель отказывается позволить шаману исцелить мои раны. Он говорит, что это послужит мне хорошим уроком и даст мне время поразмыслить над моим провалом.$B$BНо ты можешь отомстить за меня и за тех, кто пал у Магмота!$B$BЯ знаю, что говорящая с духами хочет, чтобы ты $gотправился:отправилась: туда ради спасения предсказателя.$B$BЭто совсем недалеко, к востоку отсюда. Иди, $C... иди, убей магнатавров и их прислужников-снобольдов. Восстанови честь заставы!', 'Убейте магмотов: 10 шаманов, 5 добытчиков, 3 сокрушителя и 3 жен Магмотрегара. Затем возвращайтесь к Орторошу на заставу Бор\'горока.', 'Честь мертвых отмщена благодаря твоим деяниям, Совух.$B$B<Раненый орк кивает, медленно выдыхая.>$B$BБыть может, теперь я смогу вновь стать воином, каким был когда-то.', NULL, NULL, NULL, 'Магмот-шаман убито', 'Магмот-добытчик убито', 'Магмот-сокрушитель убито', 'Жена Магмотрегара убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11640, 'Слова могущества', 'В описанных вами башнях живут главные приспешники предводителя Плети – верховные жрецы. Они не только командуют войсками Плети: они стерегут вход в Некрополь, и к своему хозяину.$B$BНескончаемый поток порождений Плети захлестнет нас с головой, если мы не сумеем найти и обезвредить их предводителя. Я не могу оставить свой народ без защиты, как бы сильно Дурму ни хотелось перенести войну на территорию противника. Именно вам, $N, придется истребить верховных жрецов и забрать свитки, которые хранятся у них.', 'Принесите свиток верховного жреца Наферсета, свиток верховного жреца Талет-Ха и свиток верховного жреца Андората вождю Зимней Стуже в деревне Таунка\'ле.', '*Вождь Зимняя Стужа читает то, что написано на свитках.*$B$B\"Шабтир бакх сохнен...\"$B$BЭто слова древнего, неблагозвучного языка, на котором говорят нерубы – и весьма подходящие слова:$B$B\"Слуга преклоняется перед властью господина\". Это слова, открывающие путь в некрополь!', 'Если мы хотим прорваться через Плеть и расчистить путь жителям деревни, нужно проникнуть в этот некрополь!', NULL, NULL, 'Свиток верховного жреца Наферсета', 'Свиток верховного жреца Талет-Ка', 'Свиток верховного жреца Андората', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11641, 'Смелость города берет!', 'С самого начала я советовал, чтобы вождь Зимняя Стужа собрал наших могучих воинов и напал на врага на его территории. Но он остался глух к моим советам и предпочел ходить вокруг да около, как предложила ведунья Эйри.$B$BЯ не собираюсь больше ждать. Если вождь Зимняя Стужа слишком труслив, чтобы отправить наших воинов в бой, может быть, ты покажешь ему, что лобовая атака может быть успешной. Ворвись в храмовый город Эн\'кила и сокруши все на своем пути, $N.', 'Убейте 15 вурдалаков и 5 некромантов из Эн\'кила и доложите об этом Дурму Ледяной Шкуре, который живет в деревне Таунка\'ле.', 'Ты доказал свое бесстрашие и продемонстрировал свое воинское мастерство. Я верю, что ты стал бы хорошим воином таунка. Хотелось бы только, чтобы и вождь был того же мнения.$B$BНам повезло, что мы можем рассчитывать на тебя как на союзника в наших попытках эвакуировать деревню раньше, чем по ней ударит Плеть.', NULL, NULL, NULL, 'Вурдалак из Эн\'кила убито', 'Некромант из Эн\'кила убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11642, 'Танк сам собой не починится!', 'Нам нужно, чтобы эти танки были вновь на ходу! А сами собой они, ясный перец, не починятся. Отвечать за это дело будет Мобу. Поговори с ним и узнай, что ему нужно. Может быть, тебе удастся заткнуть ему рот раньше, чем он приведет меня в бешенство, и я разрублю его пополам!', 'Поговорите с Мобу в лагере Гарроша.', 'А, так ты новый водитель танка, дружище? Сойдет! Нам нужно просто снова заставить эти штуковины ехать. Да уж, только попробуй забраться на равнины Назама без танка – и ты, считай, труп.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11643, 'Танковая пневматическая трансзажиматрица Мобу', 'Эти штуки бесполезны, дружище. Чтобы поставить на ход эти машинки, мне нужна моя танковая пневматическая трансзажиматрица! К сожалению, я оставил ее на прежнем месте, на другой стороне лагеря. В покосившемся домике рядом с конюшнями. Тебе придется пойти и принести мне инструмент, потому что меня хоть огнем демоническим жги – к туману я и близко не подойду.$B$BО да, дружище, берегись тумана. Это он исковеркал это побережье.', 'Принесите Мобу на берег Эха в Борейской тундре его танковую пневматическую трансзажиматрицу.', 'Отличная работа, дружище! Ммм, и куда ж я задевал запчасти-то...', 'Ну, что, удалось найти мою Т.П.Т.?', NULL, NULL, 'Танковая пневматическая трансзажиматрица', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11644, 'Сверхпрочные металлические пластины!', 'Мне нужен металл, чтобы подлатать эти танки! Сверхпрочные металлические пластины раскиданы почти по всему лагерю Гарроша и на дне залива.$B$BТолько будь осторожнее, когда пойдешь их искать. Туман, он... ну... АГРЕССИВНЫЙ! Именно туман уничтожил лагерь и соседний городок клыкарров. Бедняжки клыкарры...', 'По заданию Мобу соберите 10 сверхпрочных металлических пластин и принесите ему на берег Эха в Борейской тундре.', 'Отличная работа, дружище! Тэкс, куда ж я задевал эту пневматическую трансзажиматрицу для танков?', 'Помни, туман – плохо!', NULL, NULL, 'Сверхпрочная металлическая пластина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11645, 'Грязные, вонючие снобольды!', 'Грязные, вонючие снобольды! Они разворовали все мои припасы!$B$BТы спрашиваешь, что такое снобольды? Это те же кобольды, только они служат магнатаврам, вроде как заботятся о них. Странно, да, я знаю!$B$BНо это все неважно. Не согласишься ли ты мне помочь? Я знаю, куда эти мерзкие крысы уволокли все мое добро. Поделом мне: нечего было рассчитывать, будто на северном конце полосы припасы будут в безопасности.$B$BОкажи услугу, сходи на север, в их дурацкий Магмот! Если принесешь мое добро, я в долгу не останусь!', 'Добудьте 10 ящиков с вещами Умейки и верните их Умейке Шестеркрут на взлетной полосе Выкрутеня.', 'Ох, $N, какой же ты молодчина!$B$BА вот и обещанная плата…', 'Ну что, все мои припасы целы, $C? Я без этих вещей как без рук!', NULL, NULL, 'Вещи Умейки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11646, 'Борейские дознаватели', 'Слушай внимательно, $N, поскольку приходится дорожить каждой минутой.$B$BТвоего пленника готовят к допросу тут, в нашей башне. Если он не захочет откровенничать, может потребоваться твоя помощь.$B$BСходи туда, где его содержат, и скажи библиотекарю Нормантису, что я послал тебя ему в помощь.', 'По приказу Донатана пойдите к библиотекарю Нормантису в башню магов на Янтарной гряде и предложите ему свою помощь.', 'Донатан мудро поступил, прислав тебя, $C.$B$BТеперь выясняется, что мне понадобится кто-то, не входящий в Кирин-Тор.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11647, 'Обезвредить чумные котлы', 'Меня крайне тревожит существование чумных котлов в Храмовом городе Эн\'кила, $N. Очевидно, что вождь Зимняя Стужа доверяет твоему благоразумию и твоим знаниям о наших врагах. Не поможешь ли ты мне изничтожить котлы вместе с тем, что ты помогаешь вождю приводить в исполнение его планы касательно Храмового города?$B$BЯ приготовила тотем, который нападет на котлы и нейтрализует их содержимое. Тебе нужно только отыскать котлы и пустить в ход тотем возле каждого из них. Каждое орудие Плети, уничтоженное нами, – это еще один шаг к победе!', 'Используйте тотем ведуньи Эйри из деревни Таунка\'ле, чтобы нейтрализовать восточный котел, центральный котел и западный котел в Храмовом городе Эн\'кила.', '<Ведунья Эйри принимает у вас тотем.>$B$BТак тотем подействовал, как надо? Чтобы его сделать, пришлось прибегнуть к древней магии, которую ведуны не использовали поколениями. До нас дошли только обрывки древних знаний...', NULL, NULL, NULL, 'Восточный котел очищен', 'Центральный котел очищен', 'Западный котел очищен', 'Тотем ведуньи Эйри');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11648, 'Искусство убеждения', 'Как удачно, что ты здесь, $r!$B$BВидишь ли, кодекс чести Кирин-Тора не одобряет крайних мер, даже в таких отчаянных ситуациях, как теперь.$B$BНо ты – $gчужестранец:чужестранка:, тебя эти ограничения не касаются, так что тебе ничто не мешает предпринять действия, необходимые для получения информации.$B$BДелай все, что понадобится. Нам нужно немедленно узнать, где держат леди Эванор!$B$BА я пока приберусь на полочках... Да, и прихвати эту старую штуковину, она тебе может пригодиться!', 'Используйте генератор боли против закованного бериллового колдуна, пока тот не выдаст местонахождение леди Эванор, по просьбе библиотекаря Нормантиса с Янтарной гряды.', 'Отлично! Эти сведения были жизненно важными!$B$BМолодец, друг мой!', 'Ну что? Удалось тебе выяснить, где держат леди Эванор?', NULL, NULL, 'Пленный допрошен', 'Генератор боли', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11649, 'Частицы разгневанных бурь', 'Теперь, когда эта небольшая ссора улажена, остается только помочь тебе и твоей знакомой, говорящей с духами.$B$BКак видишь, мои подданные разгневаны непрекращающейся войной между огнем и водой. Боюсь, эта битва утихнет еще не скоро, но ты сможешь извлечь из нее пользу.$B$BЯ знаю, что может тебе помочь. Отправляйся в руины и собери частицы бури.', 'Добудьте 5 частиц бури и принесите Империан в руины Элдра\'ната.', 'Я сожалею о гибели этих бурь, но слово мое крепко... даже данное смертному существу вроде тебя.$B$BТеперь посмотрим, смогу ли я сделать что-то, что окажется тебе полезным.', 'Когда ты принесешь частицы бурь, я смешаю с ними часть своей сущности. В результате получится как раз то, что тебе надо.', NULL, NULL, 'Частица бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11650, 'Еще кое-что…', 'Как ты, должно быть, $gзаметил:заметила:, мы устроили взлетную полосу на южной границе логова магнатавров!$B$B*Умейка бормочет себе под нос что-то нелестное насчет Выкрутеня*$B$BНаш старикашка поручил мне найти… э-э… творческое решение проблемы, потому что если с ними не разобраться в ближайшее время, они явятся и разберут нас на запчасти!$B$BТак что нам нужна твоя помощь. Вот, держи список и раздобудь все, что тут перечислено. Пожалуйста!', 'Найдите инструменты Умейки, перегруженный конденсатор и горсть песка Рокнара. Доставьте все это Умейке Шестеркрут на взлетную полосу Выкрутеня.', 'А, вот так-то лучше! Теперь остается только собрать все это вместе.$B$BНу да, конечно, можно подумать, ты мне чем-то поможешь!$B$BНе суетись: теперь, когда я заполучила свои инструменты, это займет всего пару секунд!', 'Что-то мне не верится, будто ты уже собрал все, что было перечислено в списке!', NULL, NULL, 'Инструменты Умейки', 'Перегруженный конденсатор', 'Горсть песка Рокнара', 'Список покупок Умейки');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11651, 'Броня крепка, и танки наши…', 'Спасибо за помощь, друг! Передайте там Грек\'лору, что танки готовы к бою. Есть надежда, что вам удастся расчистить это место раз и навсегда!', 'Поговорите с крушителем Грек\'лором на берегу Эха.', 'При нынешнем состоянии наших кораблей и морских путей мы никак не могли доставить эту проклятую боевую машину в Песню Войны. Эти танки – все, что у нас осталось от первоначальной экспедиции. Теперь, когда они пригодны к работе, вы можете использовать их, чтобы стереть в порошок войска Плети на равнинах Назама.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11652, 'Равнины Назама', 'Как только будешь $gготов:готова:, запрыгивай в любой из танков и выезжай на равнины Назама, к юго-востоку отсюда.$B$BИспользуй вооружение танка, чтобы крушить войска Плети. Если танк застрянет, наш Фаршеватель порвет их в клочки, а мины прикончат тех, кто остался в живых! И последнее: баки с топливом стоят на равнине повсюду.$B$BПопытайся подобраться поближе к тому зданию в центре и выяснить, что там происходит.$B$BЕсли тебе удастся выполнить все это и остаться в живых, отправляйся к Адскому Крику!', 'Используйте ордынский осадный танк, чтобы уничтожить 100 солдат Плети и спасти 3 раненых солдата Песни Войны на равнинах Назама. Кроме того, выясните, кто возглавляет наступление Плети.Выполнив все это, отправляйтесь к Гаррошу Адскому Крику в крепость Песни Войны.', 'Кел\'Тузад? Так значит, это правда – Наксрамас возвращается…$B$BВозможно, я недооценивал тебя, $N. Ты оказал Орде серьезную услугу. Вождь мог бы гордиться тобой!$B$B<Гаррош ненадолго задумывается.>$B$BЕсли этими отрядами Плети управляет Кел\'Тузад, неизвестно, что еще готовит нам Король-лич. Мне нужно поразмыслить над этим, $Nх. Можешь идти.', NULL, NULL, NULL, 'Уничтожено боевых единиц Плети', 'Спасено раненых солдат Песни Войны', 'Исследовать локацию', 'Предводитель Плети опознан');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11653, 'Ха! Не такой уж ты и большой теперь!', 'Все будет отлично, шеф! Итак, вот что я хочу, чтобы ты сделал…$B$BВозьми мой самострел и отправляйся на север, к Магмоту. Если мы хотим иметь хоть какие-то шансы против этих монстров, то нам надо их, так сказать, подогнать под размер.$B$BДля калибровки самострела я хочу, чтобы ты убивал магнатавров, пока самострел еще действует на них. Подойдут любые сокрушители или супруги, а с мелкими не возись... малы слишком, чтобы о них беспокоиться.', 'Испробуйте прототип ультрасовременного укорачивающего излучателя Умейки на 5 магмотах-сокрушителях или женах Магмотрегара. Когда все будет сделано, вернитесь к Умейке на взлетную полосу Выкрутеня.', 'То ись как – не сработал?!$B$BНо... но…$B$B<Умейка начинает всхлипывать и готова разрыдаться.>$B$BЛадно, мы это переживем. Я уже большая девочка. Попробуем найти нестандартное решение!', NULL, NULL, NULL, 'Самострел Умейки испытан', 'Прототип ультрасовременного укорачивающего излучателя Умейки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11654, 'Шпиль Крови', 'Изучая взятую склянку с кровью, вы обнаруживаете, что ее содержимое еще теплое. Кровь у жертвы, должно быть, взяли совсем недавно, она может быть еще жива.$B$BНо зачем Плети кровь? Раньше захват пленных их никогда не интересовал. Может быть, если вам удастся установить, чья это кровь, вы сможете понять, что планируют создания Плети.', 'Поищите на Шпиле Крови информацию касательно склянки со свежей кровью.', '<Снежный следопыт таунка плохо выглядит и еле-еле отвечает вам.>$B$BЯ не... долго. Может... может, ты сможешь остановить их... прежде чем...', 'Как... как ты нашел меня?', NULL, NULL, 'Фиал свежей крови (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11655, 'В туман', 'Пройдя к северу через туман, ты доберешься до лагеря Гарроша. К югу – руины моего прежнего дома, Пал\'ии. Оба эти места были разорены древней силой, известной как квалдиры.$B$BЭти жуткие дикари безжалостно убили весь мой народ, а твой заставили уйти во внутренние земли.$B$BВсе, что осталось от клыкарров Пал\'ии – наши личные вещи, взятые квалдирами в качестве реликвий. Хотя мы не мстительная раса, справедливость должна быть восстановлена. Реликвии клыкарров должны быть возвращены мне. Войди в туман и найди их...', 'Убейте квалдиров, найдите 8 реликвий клыкарров и принесите их Вальтору из Пал\'ии на берег Эха в Борейской тундре.', '<Печаль охватывает Вальтора.>$B$BРуины... Это все, что квалдиры оставляют после себя. Им надо преподать урок.', 'Ты должен служить кровью и честью... Верни реликвии клыкарров!', NULL, NULL, 'Реликвия клыкарров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11656, 'Показательное сожжение', 'Клыкаррская магия очень похожа на то, что вы зовете шаманством. Правда, мы служим стихиям иначе, чем вы, но мощь, которую мы можем вызывать, огромна.$B$B<Вальтор помахивает перед вами похожим на факел жезлом.>$B$BЯ хочу, чтобы с помощью этого клыкаррского факела ты $gвернулся:вернулась: в туман и $gударил:ударила: по квалдирским судам. Три из них стоят за туманом у лагеря Гарроша, к северу отсюда, а еще один пришвартован у берегов Пал\'ии, на юге. Сожги их так, чтобы все видели!', 'По заданию Вальтора из Пал\'ии с Берега Эха сожгите квалдирские корабли у Пал\'ии и у лагеря Гарроша с помощью клыкаррского факела. Нужно уничтожить следующие суда: \"Змеиная Пасть\", \"Кур Драккар\", \"Молот Бора\" и \"Наковальня Бора\".', 'Демонстрация нашего сопротивления квалдирским дикарям – может быть, именно это и нужно, чтобы спасти моих соплеменников в других лагерях. Может быть, квалдирцы пересмотрят свои действия, если уверятся, что возмездие неизбежно.', 'Все сделано? Корабли запылали?', NULL, NULL, '\"Змеиная пасть\" уничтожен', '\"Кур Драккар\" уничтожен', '\"Молот Бора\" уничтожен', '\"Наковальня Бора\" уничтожен');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11657, 'Поймай факел!', 'Ну, факел ты теперь бросать умеешь, так посмотри, сможешь ли ты его еще и поймать!$B$BБери эту связку незажженных факелов. Ступай к костру и подбрось факел высоко в воздух. Поймай его прежде, чем он коснется земли... затем снова подбрось его в воздух! Поймай четыре факела подряд, затем возвращайся ко мне.$B$BОсторожнее! Они опасны при ударе о землю! И не пропусти ни одного! Если пропустишь, придется вернуться к костру и начать все с начала. Удачи!', 'Поймайте подряд 4 факела, затем поговорите с мастером-огнеглотателем.', 'Не обжегся? Если да, то дважды подумай прежде, чем играть с огнем...$B$BШучу! Все вышло здорово! И это уже не шутка. Ты – отличный огненный жонглер! Теперь иди, веселись!', 'Правда, весело факелами жонглировать? Только осторожнее, а то подпалишься!', NULL, NULL, 'Поймать 4 факела подряд.', 'Незажженные факелы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11658, 'План Б', 'Ладно, не паникуй! Ну не сработал самострел, но у нас есть и другие варианты.$B$B<Умейка щелкает пальцами.>$B$BМы собираемся отвлечь внимание от взлетной полосы! Чтобы это сделать, нам прежде всего понадобится несколько вещей.$B$B<Шестеркрут оценивающе оглядывает вас сверху вниз.>$B$BКараван Стальной Челюсти – прямо к западу отсюда – по глупости решил срезать дорогу через кладбище таунка и был уничтожен восставшими духами.$B$BОтправляйся-ка туда и стащи с мертвых орков какую-нибудь одежку. А заодно и одно из их знамен прихвати!', 'По просьбе Умейки Шестеркрут со взлетной полосы Выкрутеня соберите 10 комплектов одежды и знамя клана Песни Войны.', 'То, что нужно, но какая вонь!$B$BЯ лучше помру, чем надену такую дрянь. Но нам нужно порыться в этих тряпках и найти что-то что будет тебе к ли... впору.', 'Нам понадобится куча их одежд, если мы хотим, чтобы все сработало как надо. Я тебе не швея... нужно просто подобрать что-нибудь, что тебе подойдет!$B$BА потом я просто пройдусь прикосновением своего инженерного гения, и вуаля! – ты будешь выглядеть так, как и надо для твоей роли.', NULL, NULL, 'Униформа клана Песни Войны', 'Знамя клана Песни Войны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11659, 'Уничтожьте шары!', 'Они… выпускают кровь… из пленных… и вливают… в эти шары.$B$B<Глаза Грумма на миг закрываются, он роняет голову.>$B$BКровь… относят в Некрополь… кормить кровавого принца…$B$B<Грумм задыхается.>$B$BОб-бещай… что уничтожишь… кровавые… шары… сообщи Джунеку...$B$B<Снежный следопыт теряет сознание.:', 'Уничтожьте 5 кровавых сфер и сообщите о случившемся снежному следопыту Джунеку в деревне Таунка\'ле.', 'Я опасался, что Грумм в плену, но даже не подозревал, что с ним творят такие ужасные вещи! Никогда еще не видел, чтобы кто-то проиграл битву с Плетью и остался в живых…$B$BСпасибо, что принесла весточку о его судьбе, $N. Он был могучий воин, таким мы его и запомним.', NULL, NULL, NULL, 'Разбито кровавых сфер', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11660, 'Рог старого морехода', 'Квалдирский лейтенант по имени Орабус возглавлял первую волну нашествия на моих соплеменников в Пал\'ии. Под его руководством были разрушены обе наших деревни, после чего Орабус скрылся в тумане.$B$BВ те далекие дни ходили слухи о роге, который лейтенант передал ткачам тумана из племени Квалдир. С помощью этого рога можно было при необходимости призвать самого Орабуса.$B$BНам нужно заполучить этот рог, отобрав его у ткачей туманов, и провести этот ритуал. Если убить предводителя, может быть, эти дикари отступят.$B$BТкачей туманов ищи у Пал\'ии, к югу отсюда.', 'Принесите рог старого морехода Вальтору из Пал\'ии на берег Эха в Борейской тундре.', 'Ты должен призвать Орабуса с помощью рога старого морехода.', 'Найди рог старого морехода!', NULL, NULL, 'Рог старого морехода', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11661, 'Орабус Кормчий', 'Возьми рог и отправляйся на запад, к пристани Песни Войны. Доберись до конца пристани и протруби в рог. Этот звук должен пробудить Орабуса.$B$BУбей эту злобную тварь и возвращайся ко мне!', 'По заданию Вальтора из Пал\'ии с берега Эха в Борейской тундре протрубите в рог древнего моряка, чтобы призвать Орабуса Кормчего. Когда Орабус появится, убейте его.', 'Похоже, убийство их лейтенанта только разворошило осиное гнездо. Они стали еще злее и агрессивнее, чем раньше!$B$B<Вальтор вздыхает.>$B$BЧто ж, дружище, ты сделал здесь все, что мог. Тебе как минимум полагается компенсация за уменьшение их числа.', NULL, NULL, NULL, 'Орабус Кормчий убито', 'Рог старого морехода', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11662, 'Найти Карука', 'Еще один выживший из Пал\'ии – его зовут Карук – отправился на основную квалдирскую базу в Борейской тундре, далеко на юг, где когда-то было полно снега. Карук прячется в утесах, наблюдая за берегом Терзающего Бича.$B$BНайди Карука, и пусть он узнает о том, что $gсделал:сделала: ты ради моего народа здесь, на берегу Эха. Из крепости Песни Войны направляйся по дороге на юг и не сворачивай с нее, пока не доедешь до берега Терзающего Бича.', 'Найдите Карука на берегу Терзающего Бича.', 'Вальтор поступил мудро, прислав тебя ко мне, $R. Боги благосклонны к тем, кто восстанавливает справедливость. Ты станешь тем, кто накажет злодеев от нашего имени!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11663, 'Передача сведений', 'Спасибо, $C! Информация, которую тебе удалось извлечь, жизненно важна для Кирин-Тора.$B$BВозвращайся тотчас же к Донатану, пока мы составляем планы спасения леди Эванор.', 'По просьбе Нормантиса отчитайтесь библиотекарю Донатану на Янтарной гряде.', 'Прошу прощения, $N. Я знаю, что это была малоприятная работа.$B$BЕсли бы не то отчаянное положение, в каком мы оказались, я бы никогда не просил тебя помочь таким образом.$B$BИтак... что тебе удалось выяснить?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11664, 'Спастись из тумана', 'Я слышу снаружи тварей из тумана. Их вопли сводят меня с ума, но я не решаюсь бежать отсюда. Да и куда мне идти? Они догонят меня и казнят, как и остальных...$B$BСкажи, $gчужестранец:чужестранка:, далеко ли простирается туман? Может, он накрыл уже весь этот материк?$B$BБыть может, ты согласишься помочь мне вырваться из тумана? Думаю, я сумею найти дорогу обратно к моему отцу. Я все еще чувствую его живой дух. Он близко...', 'Выведите Муту Младшую из тумана. Если вам удастся спасти Муту Младшую, поговорите со старейшиной Муту.', 'Об этом шепчутся ветра, друг. Твое имя известно стихиям. Муту не забудут твоей услуги!', NULL, NULL, NULL, 'Муту спасена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11665, 'Кроколиски в городе', 'Привет, $gпарень:девчушка:. Славно, что $gостановился:остановилась: поболтать со старичком, у которого дома не все ладно.$B$BТут недавно один странствующий торговец продал партию детенышей кроколисков доверчивым детишкам. А кроколиски звери дикие, многие разбежались и теперь прячутся в городской канализации.$B$BБери-ка свою лучшую удочку и забрасывай леску в Штормграде или Оргриммаре. Притащи мне одну из этих тварюг. Уж очень посмотреть хочется.', 'Принесите старине Барло детеныша кроколиска. Он рыбачит на озере Силмир на северо-востоке от Шаттрата.', 'Вот убогая тварь! Уверен, Скалл сумеет из него сделать что-нибудь вкусненькое.$B$BДа шучу, шучу.$B$B<Старина Барло хитренько подмигивает.>', 'Ну, чего, еще не выудил крока из Стоков?', NULL, NULL, 'Детеныш кроколиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11666, 'Поймай бандюгу', 'Наверное, тебе приходилось слыхать о золотом ерше – их полно в реках леса Тероккар, и жрецы любят ими полакомиться. Но вот об одной рыбине ты вряд ли $gслыхал:слыхала: – о ерше чернопером.$B$BЭта рыба славится хитростью, и поймать ее нелегко. Приходится подсекать в последний момент, а то объест наживку – и поминай как звали.$B$BЗабрось удочку в одну из рек Тероккара и принеси мне черноперого ерша. В озерах ловить – пустое дело, он только в проточной воде живет.', 'Поймайте черноперого ерша и принесите его старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир.', 'Приятно посмотреть... Ты крупную рыбку выудил! Сегодня старику достанется королевский ужин.', 'Как улов, парнишка?', NULL, NULL, 'Черноперый ерш', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11667, 'Та самая рыбка', 'Ильная рыба Фиглюстера – невероятная юркая придонная рыбка. Она водится в водах Награнда. Эти рыбы всю свою жизнь растут и так просто поймать себя не дадут.$B$BМного лет назад я поймал самую большую в мире ильную рыбу... ну, по моему мнению... но она перекусила леску и удрала.$B$B<Рыбак:Рыбачка: твоего уровня знает, что делать – твоя добыча ждет тебя в озерах Награнда.', 'Поймайте величайшую ильную рыбу в мире и принесите ее старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир.', 'Она! Этот шрам я везде узнаю.$B$BНо, честно говоря, я думал, что она будет... побольше. Ладно. Отпущу-ка я ее и попытаюсь выловить в другой раз.', 'Скажи – ты ее поймал?Пожалуйста, скажи, что ты поймал эту щучью дочь!', NULL, NULL, 'Величайшая ильная рыба в мире', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11668, 'Ловить креветок – это не жук чихнул', 'В озерах Зангартопи водится много крупной рыбы. Как думаешь, кого они там жрут?$B$BКреветок. Гигантских пресноводных креветок. Скалл говорил, что из креветок можно приготовить просто необъятное количество блюд.$B$BНо креветки слишком маленькие, их на крючок не наловишь. Так что тут надо применить одну уловку: распотроши колючеусую форель – и найдешь в ней пару креветок, если повезет.', 'Принесите 10 гигантских пресноводных креветок старине Барло. Он рыбачит на озере Силмир на северо-востоке от Шаттрата.', 'Ты и с крючком, и с ножом славно управляешься. Давай-ка сюда этих миленьких креветочек, и я дам тебе попробовать блюдо.', 'Как улов, парень?', NULL, NULL, 'Гигантская пресноводная креветка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11669, 'Филе сквернокровного луциана', 'Старик скоро пойдет охотиться. Хочу поймать рыбу-молот на побережье Азшары.$B$BБеда в том, что мне для этого нужен яд, который не смоет с остроги водой. А чтобы сделать такой яд, мне нужны железы сквернокровного луциана.$B$BЭта ядовитая рыба водится в водах полуострова Адского Пламени и в Долине Призрачной Луны. Принеси мне такую рыбину, и я буду самым счастливым на свете стариком!', 'Принесите старине Барло чудовищного сквернокровного луциана. Старик удит рыбу к северо-востоку от Шаттрата в озере Силмир.', 'Никогда не видел такой огромной, такой уродливой рыбы. Даже представить не могу, на какую наживку ты ее ловил.$B$BПоложи тварюгу на землю, и как подохнет, я ее разделаю.', 'Эти сквернокровики – чудо эволюции. Выживает в любых водах, даже в лаве, и единственным природным врагом этой рыбки является рыбак.$B$BНу, как, удалось рыбку поймать?', NULL, NULL, 'Чудовищный сквернокровный луциан', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11670, 'Это были орки, честно!', 'Из всех этих одежек, что тебе удалось… э-э… раздобыть, я соорудила личину орка Песни Войны. Мне пришла в голову гениальная идея объединить это с кое-каким барахлом, завалявшимся с последнего Тыквовина, так, чтобы уж наверняка никто ни о чем не догадался!$B$BВот в этом мешке – личина и знамя, которое тебе удалось вернуть. Спустись в недра Магмота и убей вождя магнатавров, Магмотрегара.$B$BЕсли ты хочешь убедить их обратить свой гнев на орков Песни Войны, тебе нужно поднять это знамя, будучи в личине.', 'Переоденьтесь орком Песни Войны и водрузите знамя клана Песни Войны над трупом Магмотрегара. Затем вернитесь вместе с личиной к Умейке Шестеркрут на взлетную полосу Выкрутеня.', 'Ура-ура, все получилось!$B$BЛадненько, пусть теперь эти жуткие магнатавры и их прихвостни-снобольды сцепятся с Ордой!$B$BДаже не знаю, как тебя и отблагодарить, $N!', 'Ну, как? Ты сделал грязное дело и подставил орков с заставы Бор\'горока?', NULL, NULL, 'Знамя Песни Войны водружено над Магмотрегаром', 'Набор для переодевания в орка Песни Войны', 'Мешок Умейки', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11671, 'Наперегонки со временем', 'Так значит, это правда. Она у них.$B$BЯсно, что надо сделать, $r. Она БУДЕТ спасена.$B$BЯ должен оставаться здесь и помочь в подготовке спасения. Я позову тебя снова – на сей раз, чтобы добыть ключ от тюрьмы. Все, что мы знаем о личности этой Салранд, так это то, что ей нельзя повредить до тех пор, пока действует ее щит.$B$BМы сделали специальное взрывчатое вещество, которое должно снять ее защиту, позволив тебе сделать то, что должно. Возвращайся ко мне, когда раздобудешь ключ.$B$BПоспеши, $N. Леди Эванор страдает!', 'По поручению Донатана с Янтарной гряды уничтожьте щит в Берилловом лагере, воспользовавшись разрушителем Бериллового щита. Затем сразите Салранд и заберите найденный у нее ключ.', 'Сломан? $B$BДай-ка взглянуть...', 'Тебе удалось добыть ключ Салранд?', NULL, NULL, 'Сломанный ключ Салранд', 'Разрушитель бериллового щита', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11672, 'День зачисления', '$gПришел:Пришла: зачисляться на службу, так? В обычном случае тебе пришлось бы встать в общую очередь, как всем новобранцам. В обычном случае тебе не повезло бы, потому что пропала книга регистрации новобранцев, а я не могу никого принять, пока не будет новых книг.$B$BК счастью для тебя, $N, я слышал о тебе и о твоих деяниях в Запределье. По правде говоря, ты – на порядок лучше этих бедолаг. Торчать в обороне – не для тебя.$B$BИди к казармам и поговори с генералом Арлосом. Он будет более чем доволен встретиться с такой масштабной личностью, как ты.', 'Поговорите с генералом Арлосом в казармах крепости Отваги.', 'Мы ожидали твоего прибытия, $N. Добро пожаловать в Нордскол.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11673, 'Вытащите меня отсюда!', 'А я знал, что за мной рано или поздно кого-нибудь пришлют… разумеется, скорее поздно, чем рано.$B$BЯ прибыл сюда на переговоры со снобольдами, но их главный шаман, Каганишу, решил, что из меня выйдет лакомый кусочек для их Магмотрегара…$B$BПогодите... То есть как? Вас никто не присылал?!$B$BТак что, про меня просто забыли?!!$B$BНу ладно. Главное, что вы здесь.$B$BРазбейте немедленно эту цепь и идемте обратно к взлетной полосе. И можете сказать Выкрутеню, что я благополучно вернулся обратно.$B$BЕсли он, конечно, помнит, кто я такой.', 'Проводите Бонкера Тумблевольта в безопасное место и сообщите об этом Выкрутеню Разгоняйло со взлетной полосы Выкрутеня.', 'А? Что?$B$BБонкер? Какой Бонкер?$B$BНе знаю никакого Бонкера, но поверю вам на слово. Если вы спасли кого-то из ямы Магмота, вы, несомненно, заслуживаете награды.$B$BДайте взглянуть, у меня тут как раз валялась подходящая штуковина…', NULL, NULL, NULL, 'Бонкер Тумблевольт теперь в безопасном месте.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11674, 'Ведунья Высокий Холм пропала!', 'В наших землях творятся все новые таинственные дела. Одна из наших ведуний, Высокий Холм, опрометчиво отправилась на север в сопровождении всего лишь одного выносливого гонца, чтобы выяснить, что происходит близ Келий Смерти.$B$BЧто за Кельи, говоришь? Это место, священное для магнатавров. Они уходят туда в старости, чтобы умереть. Так вот, Высокий Холм видела, как что-то упало с неба несколько дней тому назад.$B$BЕсли ты друг таунка, поди и отыщи ее. Она упряма, но не настолько, чтобы отвергнуть твою помощь.', 'Найдите ведунью Высокий Холм близ Келий Смерти.', 'Тебя прислала бабушка? Она, должно быть, недовольна мною.$B$BНо когда я увидела огромный предмет, падающий с неба, я не смогла заставить себя дождаться, пока соберется целый отряд выносливых гонцов и снежных следопытов. Знание не ждет медлительных!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11675, 'Достойная смерть', 'Магнатавры в Кельях Смерти страдают от чумы. Мы должны выяснить причину заражения, но сначала нужно избавить их от страданий.$B$B<раса:, тебе нужно пойти на север, подняться по склонам, что впереди, и уничтожить как можно больше несчастных созданий.', 'Уничтожьте 10 чумных магнатавров и возвращайтесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти.', 'Что еще мы можем сделать, кроме как таким образом облегчить их страдания? В любом случае, сюда они пришли умирать, так что не оплакивай их. По крайней мере, благодаря тебе они достойно встретили смерть.$B$BА теперь мы должны положить конец тому, что явилось причиной чумы.', NULL, NULL, NULL, 'Чумной магнатавр убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11676, 'Наконец-то свобода!', 'Солдат, которых они не убили, держат в клетках, разбросанных по этому участку. Нам удалось украсть несколько ключей, но подобраться к пленным поближе так и не вышло: нас тут же атакуют.$B$BНам нужны твои \"дарования\", чтобы раздобыть все ключи и освободить пленников. Вышиби мозги некролордам и аберрациям и забери у них ключи. Открой ключами клетки и освободи пленников Плети.', 'Освободить 5 узников Плети по просьбе тенелова Канариуса с заставы у ферм Песни Войны.', 'Каждый спасенный пленник – это одной аберрацией меньше, $N. Орда тебе многим обязана.', NULL, NULL, NULL, 'Освобождено пленников Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11677, 'Остановить чуму!', 'Я уверена, что чуму вызывает нечто, находящееся в тамошних пещерах.$B$B$C, возьми эти семена. Я обычно использую их как оберег против Плети, но, быть может, они помогут избавиться и от той напасти, что обитает в Кельях.$B$BОтыщи источник заразы и брось туда эти семена.', 'Используйте очистительные семена ведуньи Высокий Холм у чумного котла в Кельях Смерти, чтобы нейтрализовать его, по просьбе ведуньи Высокий Холм, стоящей к югу от Келий Смерти.', '<Ведунья опускает голову и вздыхает с облегчением.>$B$BХорошее начало. Если бы это еще была единственная наша проблема…', NULL, NULL, NULL, 'Чумной котел нейтрализован', 'Очистительные семена ведуньи Высокий Холм', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11678, 'Поиски Торчащего Рога', 'Торчащий Рог давно уже должен был вернуться!$B$BЕще одна причина, по которой мы пришли сюда – это необходимость разведать, что это за сооружение, принадлежащее Плети, свалилось с неба. А Торчащий Рог нетерпелив, и, скорее всего, попал в беду…$B$BПрошу тебя, $N, сходи туда и найди его.', 'Найти выносливого гонца Торчащего Рога в Талрамасе.', 'Мне… недолго… осталось, $R…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11679, 'Воссоздание ключа', 'Задержки, задержки... Это единственное, чего мы никак не можем позволить себе именно сейчас!$B$BХотя мне очень не хотелось бы беспокоить лорда Сурристраза, он и только он способен спасти нашу дорогую Эванор.$B$BПринеси ему фрагменты ключа и $Nся, что он будет в хорошем расположении духа.$B$BИ не задерживайся, $C, наша штурмовая бригада уже готова.', 'По поручению Донатана поговорите с Сурристразом на Янтарной гряде.', 'Эти детские игры, в которые вы здесь играете, не имеют никакого значения…$B$BТы вместе со своими даларанскими друзьями – вы хватаетесь за отдельные болтающиеся ниточки, когда рвется ткань мироздания.$B$BОднако для моих драконов это может оказаться неплохим развлечением, в котором они нуждаются.$B$BПокажи-ка мне этот ключ...', 'Ты смеешь приблизиться ко мне, смертное существо?$B$BРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.', NULL, NULL, 'Сломанный ключ Салранд (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11680, 'Полетаем?', 'Ключ воссоздан.$B$BА теперь внемли моему совету, $r. Добейся успеха или умри… потому что если хоть одна чешуйка упадет с любого из моих драконов, отвечать за это будешь лично ты. $B$B<Свободен:Свободна:.', 'Отдайте ключ Салранд военному магу Анзиму, когда будете готовы освободить Эванор.', 'Вот он! Ключ – наш!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11681, 'Спасение Эванор', 'Наконец-то мы атакуем!$B$BКак только очистим платформу, я использую ключ.$B$BА вы позаботьтесь о том, чтобы леди Эванор осталась цела и невредима после освобождения.$B$BВперед! Скорей!', 'Отправляйтесь с боевыми магами и освободите леди Эванор из Бериллового лагеря по просьбе Анзима с Янтарной гряды. Затем явитесь к ней в башню магов на Янтарной гряде.', 'Ваши героические деяния не будут забыты, $C!$B$BПрошу вас, примите это вместе с моей искренней благодарностью.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11682, 'Беседа с драконом', 'Мне известно о твоих деяниях, $N. Еще раз благодарю тебя.$B$BЧто касается местной угрозы, мы уже узнали от них все, что было нужно. Вскоре с ними будет покончено. Однако впереди более важные дела…$B$BТы $gнужен:нужна: Азероту. Землям к западу отсюда грозит серьезная опасность.$B$BПодробности тебе расскажет лорд Сурристраз. Тебе нужно срочно поговорить с ним.$B$BУдачи тебе, друг Даларана!', 'Поговорите с Сурристразом по приказу леди Эванор с Янтарной гряды.', 'А, $R, вот и довелось нам встретиться снова!$B$BВпрочем, когда ты услышишь мои слова, ты пожалеешь об этом.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11683, 'Упавший некрополь', 'Упавший некрополь к западу отсюда наверняка по-прежнему кишит созданиями Плети.$B$BБудешь рядом с Талрамасом, $r, пожалуйста, разберись с любыми прислужниками Короля-лича, которых только найдешь там и в окружающих место его падения прудах.', 'Уничтожьте 20 созданий Плети любого вида в Талрамасе и Гнойных прудах. Затем возвращайтесь к ведунье Высокий Холм, находящейся к югу от Келий Смерти.', 'Спасибо, $N.$B$BКороль-лич и его Плеть – нарыв на теле Нордскола. Нам нельзя останавливаться, пока они не умрут истинной смертью, а его существованию будет положен конец!', NULL, NULL, NULL, 'Уничтожено созданий Плети в Талрамасе', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11684, 'Исследование воронок', 'Чувствуешь, как дрожит почва?$B$BЭто нерубы из Плети движутся глубоко под землей. Они показались к юго-западу отсюда, на Поле гейзеров, и нападают на патрули, высланные вождем Зимней Стужей.$B$B<Старейшина таунка передает вам потрепанную карту.>$B$BМожет быть, одиночка сможет добиться успеха там, где потерпели неудачу патрули. Возьми с собой на Поле гейзеров эту карту и отметь на ней воронки, через которые вылезают нерубы.', 'По просьбе Великого Отца Махана, находящегося в деревне Таунка\'ле, отметьте на карте Поля гейзеров Южную воронку, Северо-западную воронку и Северо-восточную воронку.', '<Великий Отец Махан берет у вас карту, но даже не смотрит на нее.>$B$BТвою информацию мы используем позже, когда будем готовы осуществить наш план.', 'Ну что, все воронки отмечены на карте?', NULL, NULL, 'Отметить расположение южной воронки', 'Отметить расположение северо-восточной воронки', 'Отметить расположение северо-западной воронки', 'Карта Поля гейзеров (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11685, 'Сердце стихий', 'Теперь, когда мы точно знаем местоположение нерубских воронок, мы можем их обрушить, чтобы остановить наступление Плети. Укротитель ветра Бара знает способ подчинить себе элементалей, чтобы уничтожить туннели, которыми пользуются воины Неруба. Но ей потребуется твоя помощь.$B$BК юго-востоку от деревни, близ побережья за Студеным пределом, найдешь местность, где владычествуют замороженные земляные элементали. Укротителю ветра Баре потребуются сердца этих стихий.', 'Принесите 5 сердец элементалей укротителю ветра Баре в деревне Таунка\'ле.', 'Этого должно хватить, чтобы создать основу для могущественного элементаля, однако одного камня недостаточно, чтобы вдохнуть в него жизнь…', 'Великий Отец Махан говорит мне, что ты согласился помочь обрушить туннели...', NULL, NULL, 'Сердце элементаля', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11686, 'Фермы Песни Войны', 'Согласно запискам Лютера, Плеть теперь использует это место, чтобы разводить чудищ, подобных тем, которые бродят по полю.$B$B<Икориса передергивает.>$B$BА ведь когда-то это были орки… таурены…$B$BДля того чтобы решить, как с этим бороться, нужны более точные сведения. Прошу тебя исследовать три места, сильно зараженных Плетью: Амбар Песни Войны, к юго-западу от нас, ферму Торпа, на запад отсюда, и старую скотобойню Песни Войны, что на севере.$B$BРазузнаешь, что к чему, возвращайся сюда.', 'Разведать положение дел в Амбаре Песни Войны, на ферме Торпа и на скотобойне Песни Войны по просьбе тенелова Икориса с заставы у ферм Песни Войны.', 'Все куда хуже, чем описано в дневнике Лютера! Порождения Плети здесь повсюду, они заражают все, к чему прикоснутся!$B$B<Икорис кивает.>$B$BДело становится все хуже и хуже, хотя, казалось бы, хуже некуда…', NULL, NULL, NULL, 'Разведать амбар Песни Войны', 'Разведать ферму Торпа', 'Разведать скотобойню Песни Войны', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11687, 'Доктор и Лич-Лорд', 'Нужно… убить… двоих…$B$BДоктор и… лич-лорд… они наверху. Найди их… убей… пока…$B$BПока не поздно…', 'Убейте доктора Щербохмыла и Лич-Лорда Хладолюта. Затем вернитесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти.', 'Торчащий Рог мертв?$B$BАх, не следовало отпускать его сюда одного!', NULL, NULL, NULL, 'Доктор Щербохмыл убито', 'Лич-Лорд Хладолют убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11688, 'Проклятые грязные свиньи', 'Только погляди на них! Мои красавцы кодо беспомощны и не в состоянии защититься от этих грязных свиней! Мне нужно, чтобы ты $gпомог:помогла: мне выиграть время, $r. Я думаю, что смогу вылечить кодо от их болезни, но нужно держать этих неживых кабанов подальше от них, а то лечить будет уже некого!$B$BИди и отправь хряков в землю навечно!', 'По просьбе фермера Торпа с заставы у ферм Песни Войны убейте 10 неживых кабанов.', 'Кажется, получилось, $R!', NULL, NULL, NULL, 'Неживой кабан убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11689, 'Вестник печали', 'Великая Мать должна узнать об этом, $N.$B$BМожно попросить тебя вернуться в Таунка\'ле? Скажи ей, что я вскоре прибуду.', 'Поговорите с Великой Матерью Тайгой в деревне Таунка\'ле.', 'Какие вести от ведуньи Высокий Холм несешь ты?$B$B<Вы рассказываете о том, что вам известно, и передаете Великой Матери печальные известия о выносливом гонце Торчащем Роге.>$B$BМой... мой внук!$B$B<Великая Мать всеми силами пытается сдержать эмоции.>$B$BОн погиб достойной смертью, как настоящий таунка!$B$BТы последний, кто был рядом с ним, $N, так что часть его навеки останется с тобой. Я благодарю тебя за исполнение его последней воли.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11690, 'Верни их живыми!', 'Вот уздечка, $N. Внутри удил спрятан небольшой контейнер с лекарством. Это лекарство исцелит кодо, как только животное прикусит удила. Вылечив кодо, его нужно привести домой. На нем можно будет ехать верхом, но животное будет слабым после болезни, так что ехать надо медленно.$B$BПриведи моих малюток домой, $N!$B$BДа, и последнее: на все про все у тебя десять минут! После этого противоядие внутри удил потеряет силу.', 'Спасите 8 зараженных кодо по просьбе фермера Торпа с Заставы у ферм Песни Войны.', 'Ты настоящий герой, $N! Если бы не ты, мои кодо бы все перемерли. Я тебе признателен, как и все солдаты и путники, которым эти кодо пригодятся в Нордсколе!', 'Уведи их с этих полей, запятнанных Плетью!', NULL, NULL, 'Кодо спасен', 'Уздечка Торпа для кодо', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11691, 'Призовите Ахуна', 'Мы с моими шаманами собрали все наши силы для борьбы с Повелителем Холода. $N, быть тебе $gзащитником:защитницей: Матери-Земли.$B$BВозьми этот тотем магмы. Установи его напротив Камня Льда, к северо-востоку от него. Ахун при помощи этого камня тянет силу. Мы надеемся, что тотем разрушит камень и разорвет связь с тем миром, где затаился этот элементаль.$B$BЕсли судьба будет к нам благосклонна, то мы, наверное. сумеем победить его.$B$BГотовься к битве, $N. Если придется сражаться с Ахуном, то ярость его будет неизмерима.', 'Принесите тотем магмы Служителей Земли к Камню Льда.', 'Из тотема магмы близ камня льда вырываются три языка пламени. Камень мерцает, затем исчезает...', 'В кристалле льда слышится далекий отголосок скрежета наступающих ледников. Исходящий от него холод заставляет думать о бесконечной мертвой зиме.', NULL, NULL, 'Тотем магмы Служителей Земли (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11692, 'В поисках Бикси', 'У тебя репутация настоящего героя. А у меня опять проблема!$B$BМой начальник, Тинки, отправился с Бикси Винтодер на восток, а я не могу добиться, чтобы выхлоп на этой штуке шел как следует! Тинки – единственный, кто может это поправить, а нам обязательно нужно, чтобы все на сто процентов работало.$B$BКак думаешь, тебе удалось бы их найти? Бикси говорила что-то о следовании за какими-то старыми магнатаврами к месту под названием Кельи Смерти.$B$BПодозреваю, там-то ты их и найдешь.$B$BМожешь отправиться туда, поговорив с Карой Тризведкой у взлетной полосы.', 'Как и просил вас Мордл Шестеренок, отправляйтесь на поиски Бикси Винтодер к югу от Келий Смерти.', 'Что тебе нужно, $C?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11693, 'Только не чумной магнатавр!', 'Мы с Тинки пришли сюда, выслеживая старого магнатавра. Похоже, в эти пещеры они сходятся умирать.$B$BРазумеется, мы и понятия не имели, что, входя сюда, они заражаются какой-то болезнью. Нельзя допустить, чтобы заразные твари бродили на свободе. Это нездорово!$B$BПослушайте, может, вы уложите несколько штук этих тварей, пока я соображу, что нам делать дальше?', 'Убейте 10 чумных магнатавров и возвращайтесь к Бикси Винтодер к югу от Келий Смерти.', 'Вы отлично потрудились, но на вашем месте я бы приняла душ при первой же возможности!$B$BНу, а теперь давайте разберемся с проблемой всерьез.', NULL, NULL, NULL, 'Чумной магнатавр убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11694, 'В пещерах что-то происходит...', 'Пока ты там с этими чумными зверьми $gразбирался:разбиралась:, мне удалось заглянуть в те пещеры наверху.$B$BОказывается, там засели сектанты, которые и наводят чуму на зверей!$B$BОни готовят в котле какой-то ядовитый отвар. У меня есть порошок, который я обычно использую в качестве противоядия, и я подмешала к нему еще кое-что. Я думаю, это должно нейтрализовать отраву в котле!$B$BСходи с порошком в одну из пещер и посмотри, сработает ли.', 'По просьбе Бикси Винтодер, что прячется к югу от Келий Смерти, всыпьте лечебный порошок Бикси в чумной котел в Кельях Смерти, чтобы нейтрализовать отвар в нем.', 'Я знала, что у тебя получится. А теперь – есть кое-что еще, о чем я хотела бы тебя попросить.', NULL, NULL, NULL, 'Чумной котел нейтрализован', 'Лечебный порошок Бикси', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11695, 'Рог неистовства стихий', 'Я могу изготовить подобие элементаля из этих кусков бездушного камня, однако вдохнуть в них жизнь – дело другое. Тут нам потребуется помощь и немного удачи.$B$BВ легендах говорится о древнем артефакте, который назывался рогом неистовства стихий. Я одолжу тебе свиток с текстом легенды. Не знаю, правда ли это, но больше нам рассчитывать не на что. Если легенда не лжет, части рога могут находиться на Затопленных равнинах, прилегающих к деревне с севера и с юго-запада.', 'Добудьте нижнюю половину рога и верхнюю половину рога у вождя Бурблгубля и вождя Гурглбугля и принесите их укротителю ветра Баре в деревне Таунка\'ле.', '<Бара берет у вас обломки рога и пытается соединить их.>$B$BШтормовое Копыто гордился бы тобой, Профессия. Быть может, когда мы покончим с Плетью, я возьму с собой этот рог и отправлюсь на могилу Штормового Копыта…', 'Удалось ли тебе отыскать рог? Правдива ли легенда?', NULL, NULL, 'Верхняя половина рога', 'Нижняя половина рога', 'Легенда о Роге', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11696, 'Ахун явился!', 'Хвала благим силам, $N, что ты здесь. В этой пещере затаился Ахун, собирая силы для нападения. Силы Служителей Земли уже выступили, но в одиночку им не справиться.$B$BРазведай обстановку, $N. Найди наших шаманов из Служителей Земли и поговори с их предводительницей, Лумой Матерью Небес. Возможно, с твоей помощью мы разгромим Ахуна прежде, чем свершится непоправимое!', 'Найдите Луму Матерь Небес в Узилище.', 'Хлад Ахуна растекается по этим пещерам, $N, семя леденящей погибели, что ждет нас, если он наберется сил. Хвала Матери Земле за то, что она прислала тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11697, 'Тинки в некрополе!', 'Говорила я Тинки, чтоб не ходила одна, но нет, ей же надо было проверить этот разрушенный Некрополь к западу отсюда!$B$BЯ на сто процентов уверена, что те сектанты выползли из этого Некрополя. А это значит, я на сто процентов уверена, что Тинки в беде!$B$BА ведь она – лучший инженер у нас на взлетной полосе! Без нее нам кранты!$B$BЯ бы сама ее отыскала, но одна из этих тварей ранила меня в ногу прежде, чем я успела смыться. $N, если кто может ее выручить, то только ты!', 'Отыщите Тинки Свистопляс внутри Талрамаса.', 'Ау! Ты кто?$B$BТебя Бикси прислала? Отлично, давай вытащим меня отсюда!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11698, 'Может, проще уничтожить Плеть?', 'Если сектанты в этих пещерах пережили катастрофу, то приходится предположить, что и в упавшем некрополе на западе по-прежнему кишат воины Плети. Да и в прудах их, наверное, пруд пруди!$B$BБудешь рядом с Талрамасом, $C, пожалуйста, разберись с любыми прислужниками Короля-лича, которых только найдешь!', 'Уничтожьте 20 воинов Плети любого рода в Талрамасе и Гнойных прудах. Потом вернитесь к Бикси Винтодер к югу от Келий Смерти.', 'Спасибо, $N! Король-лич и Плеть действительно ужасны, но нам нельзя останавливаться, пока мы не уложим их всех обратно в могилы!', NULL, NULL, NULL, 'Уничтожено созданий Плети в Талрамасе', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11699, 'Я застряла в проклятой клетке… но ненадолго!', 'Сектанты с помощью магии засадили меня в эту клетку без дверей. Ха! Они не знают, что у себя на взлетной полосе я – главный инженер передачника!$B$BС твоей помощью, немного повозившись, я отсюда выберусь в два счета!$B$BМне потребуется кристалл энергетического ядра одного из здешних вурдалаков, магический гироскоп их доктора и направляющий камень Плети Лич-Лорда, там, наверху.$B$BС помощью всего этого добра я сумею изготовить телепортационное устройство, которое позволит смыться отсюда по-гномьи и вернуться к Выкрутеню.', 'Найдите кристалл энергетического ядра, магический гироскоп и направляющий камень Плети и отдайте их Тинки Свистопляс в Талрамасе.', 'Отлично! Так, сейчас тут подправим, тут подкрутим…', 'Ну что, все удалось собрать?', NULL, NULL, 'Кристалл энергетического ядра', 'Магический гироскоп', 'Направляющий камень Плети', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11700, 'Сообщение для Бикси', 'Моя темная сторона куда-то делась.$B$BЯ уверена, что она не вернулась на взлетную полосу. В общем, где бы она ни оказалась, там еще холоднее, чем здесь. Но я смогла \"поймать\" ее лишь на минутку.$B$BНу, да, я перенастрою эту штуку и перенесусь на взлетную полосу достаточно скоро. А пока... как думаешь, ты $gмог:могла: бы направиться на восток и дать Бикси знать, что я встречусь с ней там?$B$BДа? Спасибо, $N!', 'Поговорите с Бикси Винтодер, находящейся рядом с Кельями Смерти, к югу от них.', 'У Тинки есть темная сторона?!$B$BНу, если она говорит, что в полном порядке и сможет сама вскоре добраться до взлетной полосы, я спокойна.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11701, 'Возвращение к взлетной полосе', 'Ладно, думаю, мне пора возвращаться к взлетной полосе. Разумеется, теперь, с раненой ногой, я хожу несколько медленнее…$B$BПослушай, не трудно ли тебе будет отправиться вперед меня и сообщить старине Выкрутеню приятные новости? Могу поручиться чем угодно, что без награды тебя не отпустят!$B$BСпасибо, $N!', 'Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня в Борейской тундре.', 'Вот так история, $N! Тут столько проблем, что даже удивительно, как это наша взлетная полоса до сих пор не стерта с лица земли!$B$BНо теперь благодаря тебе у нас стало одним врагом меньше.$B$BУ меня тут припасены особые награды для особо отличившихся. Выбирай, что больше нравится!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11702, 'Король Мргл-Мргл', 'Странно это звучит, должно быть, $C, но тут один мурлок есть, и он типа о помощи нас просит!$B$BИмя его – король Мргл-Мргл, а его подданные – мурлоки Зимних плавников. Его вместе с подданными выгнали из деревни, и теперь они хотят, чтобы ты их $gспас:спасла:.$B$BКак направишься на запад да вниз по утесам – тут-то его и найдешь. Он обретается на южной стороне Приюта Зимних Плавников.', 'Поговорите с королем Мрглом-Мрглом в Приюте Зимних Плавников.', 'Наконец-то прибыла помощь! Судя по твоему виду, ты из Орды?$B$BЭто неплохо… ваши – хорошие воины. Именно это нам и нужно, причем в больших количествах.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11703, 'Добраться до Гетри', 'Посланник Плети, присматривающий за похищением и превращением воинов Орды в монструозную нежить, использует для выведения своих кошмарных созданий северо-западную ферму. Тенелов Гетри шпионил за этой тварью всю последнюю неделю и собрал немало важной информации, которая может позволить нам справиться с ситуацией.$B$BДоберись до Гетри и узнай, не можешь ли ты ему помочь остановить этот жуткий конвейер Плети. Гетри можно найти в заброшенной башне на северо-западном краю этих ферм.', 'Найдите тенелова Гетри у ферм Песни Войны.', '<Гетри скептически осматривает вас.>$B$BА получше у Икориса никого не нашлось?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11704, 'Король Мргл-Мргл', 'Я понимаю, это звучит странно, $C, но одному мурлоку нужна наша помощь!$B$BОн известен под именем короля Мргла-Мргла и возглавляет мурлоков племени Зимних Плавников. Похоже, он вместе с подданными был вынужден бежать из своей деревни, а теперь они хотят, чтобы кто-нибудь их спас.$B$BИ этот \"кто-нибудь\" – ты!$B$BТы найдешь Приют Зимних Плавников и короля, направившись на запад по дороге, не доходя утесов. Иди к береговой линии близ Кипящего пруда.', 'Поговорите с королем Мрглом-Мрглом у Приюта Зимних Плавников.', 'Наконец-то прибыла помощь! Судя по твоему виду, ты из Альянса.$B$BЭто неплохо… у вас умелые воины. Именно это нам и нужно, в больших количествах.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11705, 'Бесполезные старания', 'Это просто безумие. Неужели они думают, что мы справимся с некролордом Плети и всеми его приспешниками, которых там невесть сколько?$B$B<Гетри вздыхает.>$B$BРаз Икорис прислал тебя сюда, он, очевидно, полагает, будто ты $gспособен:способна: на великие подвиги. Может, ты и чудеса творить умеешь, а?$B$BЧто ж, когда будешь $gготов:готова:, мы спустимся вниз и сразимся с Варидусом.$B$BЕсли уцелеем в этой заварухе, возвращайся к Адскому Крику в крепость Песни Войны.', 'Помогите Гетри одолеть Варидуса Свежевателя у ферм Песни Войны.Если вам это удастся, явитесь к Гаррошу Адскому Крику.', 'И ты возвращаешься с победой, как я и думал! Я же говорил Саурфангу, что с тобой все будет в порядке!$B$B<Адский Крик хмыкает.>$B$BМожет быть, этот старый пес хоть теперь поймет, что он не всеведущ?', NULL, NULL, NULL, 'Варидус Свежеватель побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11706, 'Обрушение', 'Для создания Аллювиуса использовался рог неистовства стихий. Протруби в этот рог, встав у самой южной воронки на Поле гейзеров, и Аллювиус откликнется на зов.$B$BОн устроит землетрясение, от которого все нерубские туннели обрушатся. Это положит конец их наступлению. Не удивлюсь, если после землетрясения наружу появится сам командир воинов Неруба. И если обрушение туннелей их не остановит, то гибель командира – наверняка!', 'Обрушьте нерубские воронки с помощью рога неистовства стихий и уничтожьте лорда Криксиса по просьбе укротителя ветра Бары из деревни Таунка\'ле.', 'Твои труды помогли нам на время остановить наступление Плети. Благодаря тебе, мы можем нанести удар по крепости Плети на северо-востоке, не опасаясь нападения с запада.$B$BЧто касается рога, я буду хранить его до тех пор, пока его мощь не понадобится снова. Штормовое Копыто отдал жизнь за то, чтобы спасти рог, и мы не можем позволить себе потерять его снова.', 'Удалось ли тебе выпустить Аллювиуса на волю и остановить наступление воинов Неруба?', NULL, NULL, 'Лорд Криксикс убито', 'Нерубские туннели обрушены', 'Рог неистовства стихий (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11707, 'Просьба о помощи', 'О, как хорошо! Ты ведь $N, верно?$B$BНам нужна твоя помощь на севере, на взлетной полосе Выкрутеня, причем нужна была еще вчера! Магнатавры, Плеть… а теперь еще и насосная станция!$B$BЯ тебе говорю – это безумие, чистое безумие!$B$BСтупай туда и поговори со стариком Выкрутенем на его взлетном поле. Срочно!!!', 'Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня.', 'Ага, наконец-то Небопрыгу пришло на ум прислать помощь! Как нельзя вовремя, не могу не отметить!$B$BЧто ж, добро пожаловать, брат, мы отчаянно нуждаемся в твоей помощи!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11708, 'Мехагномы', 'Теперь, когда ты здесь, пришла пора рассказать тебе, что к чему.$B$BА когда выслушаешь мой рассказ, ступай наружу и отыщи моего заместителя, Джинки Гайковорот. Впредь за это отвечает она.', 'Выслушайте рассказ Выкрутеня Разгоняйло и найдите на взлетной полосе Выкрутеня Джинки Гайковорот.', 'Что, старикан прислал тебя ко мне, да? А что к чему, объяснил?$B$BХорошо, тогда за дело!', NULL, NULL, NULL, 'Вы выслушали рассказ Выкрутеня.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11709, 'Поручение Нока Кровавое Бешенство', 'Ты немало $gсделал:сделала:, чтобы помочь нам закрепиться на этих ледяных пустошах, однако же во тьме подстерегают новые опасности. Я прошу тебя помочь стражу-смотрителю Ноку Кровавое Бешенство, который находится в лагере для военнопленных под стенами крепости Песни Войны. Отыщи его и предложи свою помощь в транспортировке и обмене пленными.$B$BМожешь идти, $N.', 'Поговорите со стражем-смотрителем Ноком Кровавое Бешенство из Крепости Песни Войны в Борейской тундре.', '<Нок фыркает.>$B$BПленные? Да какие это пленные! Это трусливые шавки! Ты только взгляни на них! Ты знаешь, что все они – все без исключения! – явились под стены нашей крепости и добровольно сложили оружие?$B$BНасколько мы поняли, если они попадают в плен, их потом разжалуют и отпускают по домам!$B$B<Нок плюется.>$B$BЖалкие твари!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11710, 'Что такое с передачником?', 'На востоке повсюду валяются запчасти: у Жгучих прудов, на Поле гейзеров… да они, наверное, даже на насосной станции валяются! Принеси мне их, да побольше. Может, мне все-таки удастся наладить телепорт отправки в этой штуковине, не говоря уже о том, чтобы состроить порты приема.$B$BНе хотелось бы новых несчастных случаев...', 'Соберите 15 запасных деталей Выкрутеня и доставьте их Мордлу Шестеренку на взлетную полосу Выкрутеня.', 'Прекрасно, $C! Отличные запчасти, во вполне рабочем состоянии.$B$BТеперь надо только придумать, как же починить эту хреновину…', 'Понадобится много запчастей, чтобы заставить эту штуку работать!$B$BСкажите, вы ведь достали все, что нужно, да?', NULL, NULL, 'Запасные детали Выкрутеня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11711, 'Доставка дезертиров: 30 минут, или вы не платите!', 'Здесь появляется все больше дезертиров с каждым днем. У нас просто нет больше места – нам некуда сажать этих трусливых тварей. Особенно, если мы не хотим утеснять свиней.$B$B<Норк хохочет с фырканьем.>$B$BЯ хочу, чтобы ты сопроводил одного из этих трусов к востоку отсюда и выстрелил из этого светового ружья. Один из их командиров выйдет на свет выстрела и заберет дезертира у тебя.$B$BКогда доставишь его и вернешься, доложись разведчику Тунгоку на восточной дороге.', 'Отведите дезертира Альянса к перекрестку восточнее крепости Песни Войны и выстрелите из сигнального ружья Песни Войны, чтобы дать сигнал представителям Альянса.Доложитесь разведчику Тунгоку, когда успешно доставите дезертира Альянса по месту назначения.', 'Хорошо, $N. Одним грязным, бесполезным шельмецом Альянса меньше…$B$BЕсли тебе нужна еще работа, вон тем таурену и эльфу Крови неподалеку требуется помощь.$B$BВпрочем, у нас тут и своих забот-хлопот тоже хватает…', '<Тунгок ворчит.>$B$BС дезертиром уже все, разобрался?', NULL, NULL, 'Дезертир Альянса доставлен по месту назначения', 'Сигнальное ружье Песни Войны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11712, 'Перепроклятие', 'Если ты $gвыслушал:выслушала: старика, то знаешь, что у нас тут есть гномы, которые изменились. Механизатор Механозод заразил их чем-то, что отменяет \"Проклятие Плоти\", и теперь они сделались роботами!$B$BМы думаем, что знаем способ перепроклясть их обратно, чтобы они снова стали нормальными. Возьми вот эту перепроклинальную передачниковую инъекцию и используй ее на трупах мехагномов, которые тебе встретятся.$B$BМы надеемся, что эта штука их исцелит и позволит нам отправить их отсюда.$B$BЧто скажешь, а, $N?', 'Используйте перепроклинальную передачниковую инъекцию на 6 мехагномах со станции Выкрутеня по просьбе Джинки Гайковорот со взлетной полосы Выкрутеня.', 'Получилось! Сработало!$B$BПросто не верится, что тебе удалось спасти столько гномов! Как удачно, что ты здесь!', NULL, NULL, NULL, 'Успешно проклято гномов Выкрутеня', 'Перепроклинальная передачниковая инъекция', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11713, 'Исследование воронок', 'Выкрутень отправил воздушную топографическую разведку, чтобы они составили карту нерубских воронок в южной части Поля гейзеров, но они до сих пор не вернулись. Я больше не могу дожидаться, пока они вернутся, придется мне отправить кого-нибудь на разведку пешим.$B$BЯ понимаю, насколько это опасно, и ты получишь соответствующее вознаграждение. Возьми с собой эту карту и запиши важные сведения обо всех воронках, которые тебе там встретятся.', 'Отметьте на карте Поля гейзеров расположение Южной воронки, Северо-западной воронки и Северо-восточной воронки по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.', '<Абнер берет у вас карту и пристально разглядывает ее.>$B$BОтлично! Это все, чего нам не хватало, чтобы начать операцию!', 'Ну что, все воронки отмечены на карте?', NULL, NULL, 'Отметить расположение южной воронки', 'Отметить расположение северо-восточной воронки', 'Отметить расположение северо-западной воронки', 'Карта Поля гейзеров (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11714, 'Дератизация', 'Может быть, ты не откажешься помочь мне в расчистке этих полей? Они просто кишат мелкими крысюками! Кобольды-шмобольды, как их там... они тут повсюду, повсюду! Одна вонь мне жизнь отравляет! Не говоря уже обо всем остальном… $B$BРазберись ради меня с этими вредителями, а я заплачу тебе за труды, $N.', 'По просьбе разведчика Тунгока на равнинах Кровавых Спор в Борейской тундре убейте 8 жнецов, 5 поджигателей и 2 обжарщика из стаи Кровавых Спор.', 'Отличная работа, $N. Спасибо большое!', NULL, NULL, NULL, 'Жнец из стаи Кровавых Спор убито', 'Поджигатель из стаи Кровавых Спор убито', 'Обжарщик из стаи Кровавых Спор убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11715, 'В поисках топлива', 'Я планирую построить машину, способную обрушить туннели, по которым Плеть подсылает своих нерубов. Однако наша буровая установка вышла из строя. Придется раздобыть топливо для машины другим способом.$B$BНа Поле гейзеров к юго-востоку отсюда от главной буровой установки растеклись лужи нефти. Если сумеешь набрать достаточно нефти из этих луж, я смогу сделать из нее какое-никакое топливо.$B$BПросто установи этот нефтесборник рядом с установкой, и он примется качать нефть в свой бак.', 'Соберите 8 баррелей нефти в портативный нефтесборник по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.', '<Абнер опорожняет бак собирателя.>$B$BКонечно, кустарная перегонка нефти – работа грязная, но я с этим быстро управлюсь. А пока что нам для постройки машины нужна еще одна вещь…', 'Ну что, удалось тебе набрать топлива?', NULL, NULL, 'Баррелей нефти собрано', 'Портативный нефтесборник (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11716, 'Удивительный кровоспор', 'Мы стоим на пороге изумительных открытий, $r! Целый неисследованный мир живет и дышит всего в нескольких шагах от нас! И я подозреваю, что вся здешняя экология держится на растении под название \"кровоспор\".$B$BЯ собрала немного пыльцы с находящихся по соседству мужских растений, но никак не могу найти женских экземпляров. Набери мне побольше плодолистиков кровоспор. Ты найдешь их поблизости от более крупных растений, растущих вокруг.$B$BНо берегись! Кобольды их добром не отдадут!', 'Добудьте 10 кровоспоровых плодолистиков по просьбе волшебницы крови Лаурит с равнин Кровавых Спор в Борейской тундре.', 'Великолепно! Просто великолепно!$B$B<Лаурит посыпает пыльцой один из кровоспоровых плодолистиков и произносит заклинание.>$B$BХм-м… Ничего не понимаю. Разве что… Ну да, конечно!', 'Нужно продолжать эксперименты!', NULL, NULL, 'Кровоспоровый плодолистик', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11717, 'Быстродействующая пыльца', 'Это же очевидно! Кровоспоровые мотыльки опыляют эти равнины. Должно быть, в организме мотылька что-то происходит, что действует на пыльцу как катализатор. Теперь все это начинает обретать смысл, $N. Теперь понятно, почему кобольды не убивают мотыльков, а наоборот, готовы на все, чтобы только защитить их! Эти маленькие крысы все поняли!$B$BЧто ж, нам нужно просто тоже достать себе пыльцу! Что скажешь? Принесешь мне немного – ради науки?', 'Принесите волшебнице крови Лаурит на равнины Кровавых Спор 5 щепоток пыльцы кровоспоровых мотыльков.', 'Агааа!$B$B<Лаурит посыпает пыльцой кровоспоровые плодолистики.>$B$BПогляди-ка!', 'Пыльца – ключ к разгадке!', NULL, NULL, 'Пыльца кровоспоровых мотыльков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11718, 'Автомат в мамонтовой шкуре', 'Я иначе собрал корпус старого автомата, который мог бы произвести достаточно сильное землетрясение для обвала туннелей, но начинка машины очень хрупка и чувствительна к жалящему холоду Нордскола.$B$BЯ придумал средство защитить ее, используя толстенные шкуры здешних мамонтов. Они бродят по равнинам к югу от взлетной полосы и рядом с полем Гейзеров. Принеси мне шкуры для защиты механизма, и тогда я смогу обрушить его мощь на нерубов!', 'Принесите Абнеру Шипокруту на взлетную полосу Выкрутеня 6 толстых шкур мамонта.', '<Абнер осматривает шкуры, закашлявшись пылью, скопившейся в них.>$B$BРазве у этих животных нет никаких понятий о гигиене? Некоторые из шкур просто до безобразия грязные. Эх, думаю, надо мне самому начать их чистить. Вряд ли у кого-то найдется здесь время на это...', 'Неси шкуры как можно быстрее! Я не смогу без них закончить подготовку машины!', NULL, NULL, 'Толстая шкура мамонта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11719, 'Подопытное животное', '$gЛаурит смотрит на вас, будто оценивая.:Итак, у нас есть опыленный цветок кровоспора, но никто не горит желанием испробовать его действие. Может, ты соблаговолишь стать участником эксперимента? Ну что, в конце концов, такого страшного может произойти?$B$BНе бойся, $N! Просто возьми образец и вотри его в кожу.', 'По просьбе волшебницы крови Лаурит, находящейся на Равнинах Кровавых Спор в Борейской тундре, используйте опыленный цветок кровоспора и позвольте ей изучить полученные результаты.', 'Старец Крутой Рог будет просто в восторге! Все даже лучше, чем я ожидала!$B$BМожет быть, настало время открыть тебе правду.', 'Не надо бояться.', NULL, NULL, 'Цветок кровоспора использован', 'Опыленный цветок кровоспора', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11720, 'Вторжение в Гаммот', 'Адский Крик назначил Крутому Рогу и мне тяжелое задание – истребить магнатавров у южной стороны крепости Песни Войны. С нами отправился целый взвод закаленных воинов Орды. Наше первое наступление на ближайшие логова успеха не имело – защищающие логова магнатавры смели весь отряд. Остались только мы...$B$BМы не ученые, не исследователи. Мы воины Орды – такие же, как ты. Солдаты на задании, которое нельзя провалить...$B$BПоговори со старцем Крутым Рогом, прямо сейчас.', 'Поговорите со старцем Крутым Рогом на равнинах Кровавых Спор в Борейской тундре.', 'Кровоспор, что ты собрал, должно как раз хватить, чтобы дать нам шанс против магнатавров Гаммота – конечно же, с твоей помощью.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11721, 'Гаммотра Мучитель', 'Магнатавры живут прайдами, подобно львам: один-два самца-вожака, и несколько самок с детенышами. В Гаммоте, логове магнатавров к западу отсюда, вожаком является Гаммотра. Именно Гаммотра повелевает магнатаврами, и именно его следует убить, чтобы остановить их.$B$BОтнеси этот мешочек с растертыми кровоспорами в Гаммот. Используй этот порошок, чтобы ослабить Гаммотру, а потом убей его! Принеси мне его голову в доказательство того, что задание выполнено.', 'Убейте Гаммотру и вернитесь с головой Гаммотры к старцу Крутому Рогу на равнинах Кровавых Спор в Борейской тундре.', 'Молодец, $N! Не окажешь ли ты честь нам с Лаурит, отнеся голову этого зверя Адскому Крику? Он будет весьма доволен.', 'Этот порошок можно использовать, чтобы ослабить всех магнатавров. Вот почему местные крысолюди так ревниво его берегут.', NULL, NULL, 'Голова Гаммотры', 'Мешочек растертого кровоспора', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11722, 'Трофеи из Гаммота', 'Мы не можем присвоить себе всю честь этой победы, $N. Ведь это ты $gрисковал:рисковала: жизнью, проверяя на себе кровавые споры, и именно ты, в конце концов, $gпокончил:покончила: с Гаммотрой!$B$BОкажи нам честь: отправляйся обратно в крепость Песни Войны и вручи голову Гаммотры лорду Адскому Крику!', 'Отнесите голову Гаммотры Гаррошу Адскому Крику в крепость Песни Войны.', '*Адский Крик поднимает голову Гаммотры за волосы и плюет ему в лицо.*$B$BОни еще узнают, $N… Все они узнают! Все поймут, что с Ордой шутить не стоит!', 'Ты вернулся? Так быстро?', NULL, NULL, 'Голова Гаммотры (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11723, 'Запустить Страх-и-ужас', 'Вот машина, которая спасет нас всех от нерубской угрозы!$B$B<Абнер сияет от гордости, демонстрируя готового робота.>$B$BВозьми с собой этот пульт дистанционного управления и отправляйся к самой южной из нерубских воронок на Поле гейзеров. С помощью этого пульта запусти Страх-и-ужас 5000. Остальное он сделает сам.$B$BТы только не удивляйся, если вдруг устроенное им землетрясение привлечет внимание предводителя нерубов. На самом деле, это будет подходящий случай покончить с их нападениями!', 'Используйте Страх-и-ужас 5000, чтобы обрушить нерубские туннели и уничтожить лорда Криксикса по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.', '<Абнер жадно выслушивает ваш доклад о ваших собственных успехах и об успехах Страха-и-ужаса 5000.>$B$BТо-то Выкрутень обрадуется! И кто знает – может, мы еще сделаем из тебя механика!', NULL, NULL, NULL, 'Лорд Криксикс убито', 'Используйте \"Страх-и-ужас 5000\"', 'Пульт управления Страх-и-ужасом 5000', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11724, 'Для гигантского омлета?', 'Это яйцо, очевидно, было кому-то очень нужно, о чем свидетельствует лежащее рядом тело. Когда вы осматриваете яйцо, то замечаете, что оно уже помечено к отправке на равнины Кровавых Спор, для волшебницы крови Лаурит. Но это же совсем рядом, к востоку отсюда!$B$BВозьмите яйцо и отнесите его к ожидающей волшебнице крови.', 'Отнесите массивное светящееся яйцо волшебнице крови Лаурит на равнины Кровавых Спор в Борейской тундре.', 'Значит, Алкора больше нет... Жаль... Что касается яйца, оно нам сейчас уже ни к чему. У нас тут возникли куда более сложные и неотложные проблемы.', 'Приветствую!', NULL, NULL, 'Массивное светящееся яйцо (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11725, 'Поиски пилота \"Штопора\"', 'Я должен был сам лететь на это задание. Не то чтобы я не доверял \"Штопору\". Вовсе нет. Черт, да он был лучшим ведомым, с которым я когда-либо летал!$B$BНет, все дело в том, что выполнение такого задания – моя обязанность.$B$BЯ послал \"Штопора\" с нашей самой быстрой разведгруппой, чтобы собрать информацию о деятельности нерубов в центре Поля Гейзеров.$B$BВ их последнем донесении значилось, что группа находится у прудов далеко на юг и чуть западнее нерубских воронок.$B$BНайди \"Штопора\", $N.', 'Отыщите Игги \"Штопора\" Шестероверта на Поле Гейзеров.', 'Слава механическим богам... Это было ужасно.$B$BЯркая вспышка на земле, а потом следующее, что я помню – весь отряд валится наземь. Я довольно сильно расшибся, так что у меня не было даже возможности прочесать окрестности в поисках других выживших, но что-то мне подсказывает, что вряд ли их будет много, если вообще будут$B$B<Лицо Игги перекашивает гримаса боли.>$B$BТы поможешь мне завершить мою миссию?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11726, 'Добавить специй по вкусу...', 'Волки рыщут здесь с самого крушения, и я боюсь, что они могли сожрать микропленку, на которую мы снимали весь процесс.$B$BУ меня есть идея, как найти эту микропленку, но мне нужна твоя помощь, чтобы идея сработала.$B$BК югу и востоку отсюда, на Затопленных равнинах, живут существа, которых называют горлоками. Они готовят себе пищу, используя ядовитые специи, которые отравили бы любое другое существо. Если ты сможешь собрать достаточно мешочков со специями, которые носят с собой горлоки-пародувы и горлоки-хромули, я смогу сделать приманку для волков.', 'По просьбе Игги \"Штопора\" Шестероверта, что стоит возле Жгучих прудов, соберите 4 мешочка с горлокскими специями.', '<Игги зажимает нос, опустошая мешочки со специями, и обращается к вам гнусавым голосом.>$B$BТеперь, когда у нас есть все необходимое, я смешаю специи со своим аварийным пайком, чтобы сделать приманку для волков.', 'Удалось найти мешочки со специями?', NULL, NULL, 'Мешочек горлокских специй', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11727, 'Время героев', 'Хорошо, что у нас есть ты, $N. Все мы слышали о твоих деяниях.$B$BКак ты знаешь, король Ринн выдвигает в Нордскол огромное войско, чтобы сразиться с войсками Артаса. Но армии – ничто, если в них нет настоящих героев, способных вдохновить бойцов и повести их за собой.$B$BЯ хочу, чтобы таким героем для моих воинов $gстал:стала: ты. Бейся плечом к плечу с ними против сил Плети, осадивших нашу крепость.$B$BДоложись сержанту Молотогору у внутренней крепости. Крепость Отваги не может пасть. От этого зависит будущее всей нашей кампании.', 'Доложитесь сержанту Молотогору в крепости Отваги.', 'Клянусь бородой Магни! Похоже, прибыла наша тяжелая артиллерия!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11728, 'Собаки-каки', 'Главное, ни в коем случае не ешьте эту приманку сами! Просто выложите ее неподалеку от промасленного волка. Если уж они такие голодные, что сожрали микропленку, то на приманку сбегутся как миленькие.$B$BА потом просто дождитесь, пока природа возьмет свое, и отыщите пленки в... э-э... побочном продукте пищеварения.$B$BЯ бы одолжил вам специальную усовершенствованную лопатку для собаки-каки, но она, увы, осталась на взлетной полосе. Боюсь, вам придется искать по старинке, дедовским способом...', 'Принесите 8 кусков микропленки Игги \"Штопору\" Шестероверту у Жгучих прудов.', '*Игги, зажав нос, берет у вас пленку.*$B$BОй, фу! Ну что, параграф 2 раздела 8.2 инструкций по действиям в чрезвычайной ситуации выполнен. Вот она, пленка. Ну, а насчет того, что я обязан ее отчищать, в инструкциях ничего не сказано!', 'Ну что, нашли пленку?', NULL, NULL, 'Микропленка', 'Волчья приманка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11729, 'Ультразвуковая отвертка', 'В механических недрах машины, которую вы только что разобрали по винтику, лежала странная вещица.$B$BВыглядит довольно сложным приспособлением... ясное дело, кто-нибудь на взлетной полосе с удовольствием посмотрит на это. Может, Умейка Шестеркрут?', 'Принесите ультразвуковую отвертку Умейке Шестеркрут на взлетную полосу Выкрутеня.', 'Моя отвертка... Ты нашел мою отвертку! А я-то гадала, куда она задевалась.$B$BХмм, говоришь, она была в одном из роботов? Это наводит меня на мысль...', 'Эй!', NULL, NULL, 'Ультразвуковая отвертка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11730, 'Хозяин и слуга', 'Ультразвуковая отвертка – это суперинструмент! С ее помощью с механизмами можно делать что угодно!$B$BВозвращайся к прудам и обезвредь несколько роботов Механозода. Затем поковыряйся в их останках нашей отверткой, и могу поручиться, что они перейдут на нашу сторону, хотя бы на короткое время.$B$BНа механогномов это почти наверняка не подействует, так что даже и не пробуй.$B$BДа, и если захочешь вытащить из роботов что-нибудь ценное, сделай это до того, как пустишь в ход отвертку!', 'Используйте ультразвуковую отвертку, чтобы перепрограммировать 15 роботов, затем вернитесь к Умейке Шестеркрут на взлетной полосе Выкрутеня.Не забудьте обыскать убитых роботов прежде, чем перепрограммировать их.', 'Ух ты! И отвертка тоже осталась целехонька?$B$BЭти перепрограммированные роботы будут нам чрезвычайно полезны в борьбе против Механозода! Полагаю, ты заслуживаешь за это небольшой награды…', NULL, NULL, NULL, 'Перепрограммировано роботов', 'Ультразвуковая отвертка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11731, 'Жонглирование факелами', 'Значит, ты хочешь научиться жонглировать горящими факелами? А у тебя есть необходимые для этого качества? Ловкость? Быстрота? Отвага? Если ты думаешь, что да, то давай попрактикуемся немного!$B$BБери эти факелы и беги к костру. Над ним увидишь жаровни, с горящими метками. Бросай факелы в отмеченные жаровни. И делать это надо быстро! До того, как метка погаснет, если хочешь получить очко за попадание!$B$BПопади в достаточное количество отмеченных жаровен прежде, чем выйдет время, затем возвращайся назад... для следующего урока.', 'Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом.', 'Отлично! Ты научишься жонглировать факелами – не успеешь и глазом моргнуть! Ну, готовься. Следующее испытание будет погорячее...', 'Быстро! Не тяни время!', NULL, NULL, 'Попадите в 8 жаровен.', 'Тренировочные факелы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11732, 'Осквернение огня', '', 'Оскверните большой костер Альянса на нагорье Арати!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11733, 'Переход через расселину', 'Мне известно о твоих стараниях, $gсмертный:смертная:. Не нужно притворяться, будто ты $gудивлен:удивлена:. Неужели ты не $gощущал:ощущала: на себе моего взгляда?$B$BПришло время сорвать завесу тьмы с твоего разума. Твоя душа созрела достаточно, чтобы принять некоторые суровые истины.$B$BНо прежде, чем выслушать эту историю, тебе следует воочию увидеть то, чему мы противостоим.$B$BПриведи свои дела в порядок, $C.', 'Отправляйтесь в Хладарру по распоряжению Сурристраза. Оказавшись там, поговорите с верховным магом Беринардом.', 'Добро пожаловать в Хладарру, $C! $B$BМаскировочный щит скрывает нас от Нексуса, твердыни великого аспекта Малигоса и его синих драконов, но на самом деле туда рукой подать.$B$BРасполагайся поудобнее…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
