INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11787, 'Осквернение огня', '', '', 'Оскверните большой костер Орды в Зангартопи!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11788, 'Смерть роботам!', 'Ладно, думаю, все готово к последнему и решительному бою… Но прежде чем уничтожить Механозода, тебе придется ликвидировать его помощников!$B$BИх зовут Шатунишка, ЕД-210, Макс Шмякс и Шлифовальщик, и находятся они, соответственно, на Западной станции, Северной станции, Средней станции и Южной станции.$B$BЧтобы выманить их наружу, просто открой клапаны на станциях, чтобы нарушить их работу. Найти их не трудно, там будут вращающиеся маячки.', 'Уничтожьте Шатунишку, ЕД-210, Макса Шмякса и Шлифовальщика, затем вернитесь к Джинки Гайковорот на взлетную полосу Выкрутеня.', 'Ух ты, тебе удалось выжить!$B$BНу что ж, насколько я понимаю, теперь осталось только разобраться с механизатором Механозодом.', NULL, NULL, NULL, 'Шатунишка убито', 'ЕД-210 убито', 'Макс Шмякс убито', 'Шлифовальщик убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11789, 'Солдат в беде', 'Эй, послушай! Мне нужна твоя помощь. Пожалуйста! Этот солдат станет жертвой яда могильщика, если не предпринять немедленных действий.$B$BМне удалось замедлить действие яда, но без хорошей порции антидота я не смогу устранить его.$B$BМне обещали противоядие, которое привезли на \"Рассекателе туч\" из последнего плавания на юг. Спустись в трюм \"Рассекателя туч\" и поищи там ящик со средствами оказания первой помощи.$B$BИ поспеши, $C! Мы не можем позволить себе просто так терять людей.', 'По просьбе медика Хауторна, находящегося за стенами крепости Отваги, спуститесь в трюм \"Рассекателя туч\" и принесите противоядие Хауторна из ящика со средствами оказания первой помощи.', 'Спасибо, $N. Этот парень пойдет на поправку медленно, но мы его не потеряем.$B$BЧто-что ты сказал? Сектанты на борту \"Рассекателя туч\"? Лучше сообщить об этом кому следует... и привести доказательства.', 'Противоядие... ты нашел его?', NULL, NULL, 'Противоядие Хауторна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11790, 'Сектанты среди нас', 'На этом алтаре полным-полно знаков Культа Проклятых. Похоже, фанатики с материка добрались уже и до Нордскола. Благоразумие требует сообщить об этом капитану корабля.$B$BВероятно, его можно найти на палубе.', 'Поговорите с капитаном \"Левшой\" Люггером на \"Рассекателе туч\" в Крепости Отваги.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11791, 'Сообщить Арлосу', 'Нужно немедленно сообщить это генералу Арлосу! Я знаю этого командира уже давно, и, уж поверь, он никогда не бывал замечен в небрежности!$B$BКто знает, сколько еще сектантов проникло в наши поселения в Нордсколе на других кораблях? Это может привести к катастрофе!', 'Поговорите с генералом Арлосом во Внутренней крепости Отваги.', 'Спасибо за заботу, $N. Нам не так давно уже сообщили о создавшейся ситуации.$B$BСоветник Тальбот уверяет, что это был случайный инцидент, и военным беспокоиться не о чем.$B$BНаши гражданские власти позаботятся о том, чтобы все виновные получили по заслугам.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11792, 'Враги света', 'Стоп, не так быстро. Не знаю, как тебя, $C, а меня слова генерала не особо убедили. Они звучали так... неуверенно... как будто это не его собственное мнение.$B$BТут что-то происходит. Все наши попытки сотрудничества откладываются и блокируются. Пришло время занять более независимую позицию.$B$BЕсли мы хотим больше узнать о сектантах в крепости, может быть, стоит... порасспросить тех, кто за ее стенами?$B$BРазведка донесла о небольшой группе сектантов, помогающих силам Плети к северу отсюда. Узнай – может быть, у них найдется ключ к разгадке.', 'По заданию предвестника Вуренна сразитесь с сектантами-некролитами возле Далечья к северу от крепости Отваги и добудьте сектантское коммюнике.', 'Осторожнее, $N. Мы не можем разглядывать добытые тобой доказательства под взглядами любопытствующих.', 'Ты уже вернулся, $N?', NULL, NULL, 'Сектантское коммюнике', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11793, 'Дальнейшее расследование', 'Боюсь, мне придется поручить это дело кому-то из моих агентов… кому-то, кто умеет работать втайне. Улики забери с собой и передай их воздаятелю Яаале в таверне.$B$BСкажи ей, что ты от меня, и больше ни с кем это не обсуждай. Неизвестно, кто еще может работать на секту.', 'Отнесите сектантское коммюнике воздаятелю Яаале в таверну в крепости Отваги.', 'Выкладывай побыстрее, $C! Что тебе известно о секте?', 'Тебя прислал предвестник Вуренн?', NULL, NULL, 'Сектантское коммюнике (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11794, 'Охота началась!', 'Я сочла своим долгом разузнать об этом гнусном культе смерти как можно больше. Я даже выучила их тайный язык.$B$BВуренн был прав. Сектанты упоминают, что их тайные приверженцы действуют в крепости Отваги в разных местах: в нижних доках, в темнице внутренней крепости, на кухне таверны...$B$BВозьми это око. Используй его во всех трех местах – любой, кто недавно прибегал к сектантской некромантии, будет окутан темной аурой. Разберись с этими сектантами, пока не стряслось что-нибудь непоправимое!', 'Используйте око экзорциста в трех указанных местах крепости Отваги, чтобы обнаружить и уничтожить последователей Культа Проклятых по просьбе воздаятеля Яаала.', 'Молодец, $N. Но тем не менее не могу избавиться от ощущения, что мы не в последний раз сталкиваемся с этими почитателями смерти.$B$BТьма умеет затаиться прямо у тебя под носом.', 'Мое задание выполнено, $N?', NULL, NULL, 'Сектант в доках побежден', 'Сектант в темнице побежден', 'Сектант на кухне побежден', 'Око экзорциста');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11795, '\"Действия в чрезвычайных ситуациях\": раздел 8.2, параграф 3', 'Неважно, ранен я или нет, но я командир отряда, и я отвечаю за то, чтобы найти и вернуть знаки всех своих павших пилотов. Все эти годы, что я летал с ребятами Выкрутеня, мы никогда не упускали ни одного знака.$B$BМои раны не позволяют мне удаляться от сравнительной безопасности этих обломков, но, может быть, вы не отказались бы помочь мне найти знаки? А тем временем я подготовился бы к выполнению своих последних обязанностей как командира отряда.', 'Снимите 6 значков пилота станции Выкрутеня с тел пилотов-разведчиков станции Выкрутеня и верните их Игги \"Штопору\" Шестероверту, который находится у Жгучих Прудов.', 'Спасибо еще раз, $N. Может быть, с вашей помощью мне удастся справиться с моей миссией, сколь бы ужасна она ни была, и вернуться к Выкрутеню для отчета и воздания подобающих почестей павшим.', 'Тебе удалось найти все знаки?', NULL, NULL, 'Значок пилота станции Выкрутеня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11796, '\"Действия в чрезвычайных ситуациях\": раздел 8.2, параграф 4', 'Прежде чем я наконец смогу вернуться к взлетной полосе и отчитаться перед начальством, осталось еще одно дело. Параграф 4 раздела 8.2 инструкции по действиям в чрезвычайной ситуации требует с максимальной тщательностью уничтожить все обломки, чтобы наши секреты не доставались врагу.$B$BЯ дам тебе горелку, если ты согласишься мне помочь. Мне не хочется думать, что способны натворить гоблины, союзники Орды, если эти аппараты попадут к ним в лапы!', 'Уничтожьте обломки на восточном месте крушения, южном месте крушения и северо-западном месте крушения по просьбе Игги \"Штопора\" Шестероверта.', 'Еще раз спасибо за помощь, $N. Только благодаря тебе мне удалось вернуть хоть что-то полезное после катастрофы!', 'Ну что, обломки уничтожены?', NULL, NULL, 'Уничтожить обломки на восточном месте крушения', 'Уничтожить обломки на южном месте крушения', 'Уничтожить обломки на северо-западном месте крушения', 'Горелка для аварийных ситуаций');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11797, 'Осада', 'Так-тааак. Хорошо, что Арлос вызвал сюда тяжелую артиллерию.$B$BНе пойми меня превратно – наши ребята делают все, что могут, но если столь знаменитый воин будет драться плечом плечу с ними, это может повернуть ход всей войны. Я не знаю, сколько еще мы сможем продержаться против этой нерубской нежити.$B$BЧто скажешь – не против сделать вылазку и прибить по моему заданию несколько этих жучков-паучков? Покажи парням, как это делается!', 'По заданию сержанта Молотогора убейте 6 некрорахнидов-ползунов в песках Назама за стенами крепости Отваги.', 'Неплохо сработано, $N. Покажи ребятам, как ты это делаешь. Хороший паук – дохлый паук!', NULL, NULL, NULL, 'Некрорахнид-ползун убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11798, 'Механизатор', 'Механизатор Механозод сошел с ума! Он утверждает, будто дарит нам бессмертие, снимая с нас то, что он называет \"Проклятием Плоти\". Но на самом деле он превращает нас в рабов-роботов!$B$B$N, мы почти уверены, что он и сейчас находится на насосной станции среди прудов на востоке.$B$BВ последний раз его видели в командной рубке наверху. Сходи туда и исследуй его записи.$B$BТебе придется сразиться с Механозодом, чтобы гномы... да не только гномы, чтобы все разумные существа могли жить!', 'Изучите Руководство механизатора и принесите голову Механозода Выкрутеню Разгоняйло.', '<Старый гном испускает шумный вздох облегчения.>$B$BЗначит, дело сделано… Ты нас спас! Если бы его не удалось остановить, кто знает, как далеко завело бы его безумие?$B$BА теперь, когда нам угрожают синие драконы и война с Нексусом, не говоря уже о Короле-личе, нам не хватало только обезумевшего творения титанов!$B$BСпасибо тебе, $N!', 'Джинки сказала мне, что ты придешь. Ну что, дело сделано?', NULL, NULL, 'Руководство Механизатора изучено', 'Голова Механозода', NULL, NULL);
