INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11864, 'Вступление', '', '', 'В разное время этот демон был известен под разными именами. Подробности не имеют особого значения, главное, что столкновения с ним всегда бывали гибельными.Но теперь, почти пятьдесят лет спустя после того, как все началось, наш демон наконец-то встретит свою гибель.На этот раз мы сумеем его повергнуть! Эрнестуэю не уйти!И Нордскол станет полем нашей битвы. Начинается охота на охотника!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11865, 'Им рано умирать', 'Прежде к югу от нас вольно бродили стада карибу. Но тут появился Эрнестуэй, и все изменилось. Теперь карибу не знают ни минуты покоя, они постоянно пребывают в панике. Их преследуют охотники, расставляющие в тундре свои ловушки…$B$BЭрнестуэевы палачи недостойны того, чтобы жить, но и умирать им еще рано. Пусть сперва на своей шкуре ощутят те страдания, на которые они обрекают карибу! $B$BВот, возьми эту охапку искусственных шкур и накрой ими ловушки для карибу, что расставлены на юге. Пусть охотники сами попадутся в свои смертельные капканы!', 'Используйте охапку искусственных шкур, чтобы поймать в ловушки 8 звероловов Эрнестуэя по просьбе Зазы из лагеря Д.Э.Г.О.Ж. в Борейской тундре.', 'Ты исполняешь волю Матери-Земли, $N, но не стоит упиваться своей победой! Мы обнаружили логово предводителя звероловов.', 'Не надо их жалеть, $C!', NULL, NULL, 'Поймано в ловушку звероловов Эрнестуэя', 'Охапка искусственных шкур', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11866, 'Уши мертвых врагов', 'Будь то искатели сокровищ или кровожадные охотники с пустошей, любые существа, поддерживающие Эрнестуэя и осмеливающиеся губить нашу драгоценную природу, объявляются врагами Д.Э.Г.О.Ж. Если вам случится убить кого-то из этих грязных прихвостней Эрнестуэя, принесите мне доказательства их смерти, и получите в награду благословение друидов Д.Э.Г.О.Ж.!', 'Принесите верховному друиду Латориусу из лагеря Д.Э.Г.О.Ж. в Борейской тундре 15 ушей прихвостней Эрнестуэя и получите награду.', 'Я буду носить их на шее! Пусть они слышат наше послание миру!', 'Да, уши отлично подойдут!', NULL, NULL, 'Ухо прихвостня Эрнестуэя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11867, 'Коллекция ушей', 'Будь то искатели сокровищ или кровожадные охотники с пустошей, любые существа, поддерживающие Эрнестуэя и осмеливающиеся губить нашу драгоценную природу, объявляются врагами Д.Э.Г.О.Ж. Если вам случится убить кого-то из этих грязных прихвостней Эрнестуэя, принесите мне доказательства их смерти и получите в награду благословение друидов Д.Э.Г.О.Ж.!', 'Принесите верховному друиду Латориусу из лагеря Д.Э.Г.О.Ж. в Борейской тундре 15 ушей прихвостней Эрнестуэя и получите награду.', 'Я буду носить их на шее! Пусть они слышат наше послание миру!', 'Будь то искатели сокровищ или кровожадные охотники с пустошей, любые существа, поддерживающие Эрнестуэя и осмеливающиеся губить нашу драгоценную природу, объявляются врагами Д.Э.Г.О.Ж. Если вам случится убить кого-то из этих грязных прихвостней Эрнестуэя, принесите мне доказательства их смерти, и получите в награду благословение друидов Д.Э.Г.О.Ж.!', NULL, NULL, 'Ухо прихвостня Эрнестуэя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11868, 'Сортировщица грядет!', 'У южного края утеса – вот где ты найдешь коварного лидера охотников на карибу. Она – дикарка, каких поискать, издевается над телами убитых животных: пьет их кровь и воет потом на луну!$B$BНайдите эту убийцу – ее зовут Карина – и положи конец ее никчемному существованию.$B$BПодготовься как следует, $N. Карина Сортировщица купается в богатстве, которое Эрнестуэй щедро излил на нее! Она будет хорошо вооружена и с охраной из своих прихвостней.', 'По заданию Заза из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Карину Сортировщицу.', 'Быть может, ее смерть послужит примером другим, смеющим убивать животных ради забавы и развлечения.', NULL, NULL, NULL, 'Карина \"Я не карибу\" Сортировщица убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11869, 'Судьба моллюсков', 'К западу от нас находится озеро Кум\'уа. Это, насколько нам известно, единственный пресный водоем в мире, где обитают гигантские моллюски.$B$BКонечно, прихвостни Эрнестуэя занялись там культивированием жемчуга. Их нужно остановить! Тем, кто покушается на жизнь целого вида, нужно преподать урок.$B$BОтправляйся к озеру Кум\'уа и найди этих загребущих ловцов жемчуга. Убивай их, пока воды озера не покраснеют от крови! Возвращайся, когда покажешь им, где раки зимуют!', 'По заданию иерофанта Сениуса из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте 10 загребущих ныряльщиков.', 'Посмотрим-ка, как они будут держаться, когда увидят, что сталось с их товарищами!', NULL, NULL, NULL, 'Загребущий ныряльщик убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11870, 'Покинутый предел', 'Мы только что получили сообщение от Лиандры, что наемники, работающие на Эрнестуэя, переносят добро с берега на главный корабль Эрнестуэя. Несомненно, они рассчитывают разбогатеть на своем убийственном ремесле!$B$BЛиандра просит, чтобы мы отправили помощь в Покинутый предел, к югу отсюда, на побережье Борейской тундры.$B$BТоропись, Лиандра ждет тебя!', 'Найдите иерофанта Лиандру в Покинутом пределе.', 'Вы от Сениус? Как нельзя более вовремя!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11871, 'Пока мы на страже', 'На берегу, среди обломков кораблекрушения, валяются ящики и мешки с частями тел животных. Похоже, Эрнестуэй в сговоре с флибустьерами Северных морей. Эти грязные пираты перевозят добычу, которую кровожадные прихвостни Эрнестуэя добывают на побережье. Несомненно, все это добро завершает свой путь на плечах не слишком щепетильных богатеев по всему Азероту!$B$BТак вот, не бывать этому! Во всяком случае, пока мы на страже! Принеси мне весь груз, какой найдешь на берегу. Они его не получат!', 'Добудьте 12 партий частей тел животных по просьбе иерофанта Лиандры из Покинутого предела в Борейской тундре.', 'Хорошая работа, $N. А теперь мы нанесем удар предводителю пиратов!', 'Мы устроим этим животным достойное погребение…', NULL, NULL, 'Груз рогов и копыт', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11872, 'Гнусный специалист по моллюскам', 'Специалист по моллюскам? Ишь ты! Знаем мы таких специалистов!$B$BОтыщи и убей его! В последний раз его видели на месте кораблекрушения у берегов Покинутого предела.$B$BА когда выполнишь это, возвращайся к иерофанту Сениус в лагерь Д.Э.Г.О.Ж., к северу отсюда, и сообщи ей, что дело увенчалось успехом.', 'Убейте специалиста по моллюскам К и возвращайтесь к иерофанту Сениус в лагерь Д.Э.Г.О.Ж.', 'Отличная работа, $N! Кольцо вокруг Эрнестуэя стягивается!', NULL, NULL, NULL, 'Специалист по моллюскам К убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11873, 'Новости для Выкрутеня', 'Не будешь ли ты так $gлюбезен:любезна: отправиться на взлетную полосу и сообщить Выкрутеню, что я скоро появлюсь и доложу обо всем, как положено? Мой ветролет потерпел крушение, я прибуду, как только разберусь с этим.$B$BНе сомневайся, я позабочусь о том, чтобы Выкрутень знал, что я обязан тебе жизнью и спасением.$B$BХотел бы я знать, что сделал бы старик, если бы сам летел с нами, как в старые добрые времена. Мне его изрядно не достает...', 'Вернитесь на взлетную полосу Выкрутеня и поговорите с Выкрутенем Разгоняйло.', '<Выкрутень слушает ваш доклад, и лицо его постепенно просветляется.>$B$BЭх, надо было мне полететь с ними! Может быть, мы сумели бы сделать дело, не потеряв ни одного пилота…$B$BОднако Штопор прав. Если хоть что-то удалось спасти, то благодаря тебе. Возможно, именно твои действия все-таки помогут нам взять верх над воинами Неруба.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11875, 'Обретение преимущества', 'Войска наступательной группировки Расколотого Солнца воспользуются любым преимуществом, чтобы разбить союзников Кил\'джедена. Мои коллеги из Штормграда создали масла, при помощи которых можно усиливать оружие и доспехи наших воинов.$B$BГлавный компонент – пыль Пустоты – изобилует в Запределье, если знать, где искать. Любой мастер-травник, специалист по снятию шкур или горняк, знающий приметы, может собирать ее по ходу дела. Она может найтись во всех травах, рудах и животных Запределья.', 'Принесите 8 горстей пыли Пустоты эмиссару Мордину в Шаттрат. ', 'Благодарю за помощь, $N. Любая помощь в час войны бесценна. Наши воины не должны упускать ни единого преимущества в этой войне.', 'Вы добыли для меня пыли?', NULL, NULL, 'Пыль Пустоты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11876, 'Помоги тем, кто не может помочь себе сам', 'Какие величественные звери, правда?$B$B<Латориус указывает на мамонтов северной тундры.>$B$BДень ото дня их число уменьшается. Демоны, называющие себя охотниками, убивают их ради забавы и богатства.$B$B<Лицо Латориуса перекашивается от гнева.>$B$BА этот плач просто сводит меня с ума, $N. Эти звуки приносит ветер: к нам взывают малыши-мамонтенки, попавшие в жестокие ловушки охотников.$B$BВозьми этот молот и сокруши ловушки. Освободи детенышей!', 'По заданию верховного друида Латориуса в лагере Д.Э.Г.О.Ж. в Борейской тундре освободите 8 мамонтят с помощью уничтожителя ловушек Д.Э.Г.О.Ж.', '<Верховный друид утирает слезы с глаз.>$B$BШансы их невелики. Осиротевшие, они все равно умрут...', 'Их нужно освободить!', NULL, NULL, 'Освобождено мамонтят', 'Уничтожитель ловушек Д.Э.Г.О.Ж.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11877, 'План нападения клана Ярости Солнца', 'Развивая наступление на Кель\'Данасе, мы обнаружили, что прихвостни Кель\'таса планируют контратаку. Отдав приказ эльфам крови Ярости Солнца, что базируются в Пустоверти, напасть на нашу операционную группировку в Запределье, он надеется, что мы отвлечемся от Солнечного Колодца и оттянем войска.$B$BМы не должны этого допустить, $N. На передовой каждый клинок драгоценен.$B$BОтправляйся в Пустоверть и захвати их военные планы. Они могут оказаться у любого эльфа крови Ярости Солнца. Удачи, $N.', 'Лорд Торвос из Шаттрата хочет, чтобы вы захватили планы нападения клана Ярости Солнца.', '*Лорд Торвос берет бумаги и просматривает их.*$B$BТы сослужил огро$Nю службу нашей наступательной группировке, $N, но времени на отдых нет. Не поручусь, что наши враги в будущем не затеют еще чего-нибудь.', 'Планы у тебя?', NULL, NULL, 'План нападения клана Ярости Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11878, 'Ку\'нок обо всем позаботится!', 'Ты $gпомог:помогла: освободить детенышей, попавших в ловушку, но многие из них все равно погибнут. Понимаешь, оставшись без матери, эти детеныши вынуждены будут заботиться о себе сами.$B$BНо выход есть! У них остается надежда на спасение!$B$BК северу отсюда, на равнинах у берегов Жгучих прудов, пасется Ку\'нок Чудовище, древний и мудрый мамонт. Возьми этого осиротевшего детеныша и отведи его к Ку\'ноку. Он обо всем позаботится!', 'Отведите мамонтенока-сиротку к Ку\'ноку Чудовищу в Борейской тундре.', '*Вы слышите внутри себя голос. Это говорит с вами Ку\'нок.*$B$BЯ услышал твое имя в шуме ветра, $N. Твоя помощь моим сородичам неоценима. Отныне ты – наш союзник. Увы, с нашими мучениями нельзя покончить без кровопролития и насилия.$B$BЦена мира и покоя для мамонтов – смерть Кау...', NULL, NULL, NULL, 'Мамонтенок-сиротка передан Ку\'ноку', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11879, 'Кау Гроза Мамонтов', 'В одиночку тебе не удастся убить существо, виновное в гибели моих сородичей. Но мамонты из тундры помогут тебе!$B$BСтупай на равнины и найди там могучего самца мамонта. Он позволит тебе сесть на него верхом и управлять им.Он привезет тебя на север, в Гнездо Кау, где обитает Кау. Вместе вы сумеете покончить с этим чудовищем!$B$BИстреби воинство Кау и отбери у него его драгоценную боевую алебарду.$B$BЕсли одержишь победу – возвращайся к Латориусу в лагерь Д.Э.Г.О.Ж.', 'Убейте Кау Грозу Мамонтов и добудьте боевую алебарду Кау. Доставьте ее верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж. в Борейской тундре.', '*Латориус берет у вас алебарду.*$B$BЭто действительно то, что я думаю?$B$B*Латориус расплывается в улыбке.*$B$BПоразительно! Великолепно! Еще один прислужник Эрнестуэя встретил заслуженную кару!', 'Что случилось?', NULL, NULL, 'Боевая алебарда Кау', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11880, 'Мультифазовый подход', 'Я уверен, что этот \"гном-изобретатель\" – чокнутый. Он все болтал о каких-то темных искажениях, что стали проявляться на Полях Духов вокруг Ошу\'гуна в Награнде.$B$BПо его словам эти, кхм, мультифазовые... кхм, спектрографические очки позволяют носителю видеть эти искажения и снимать с них данные. Он настаивал, что запись этих данных имеет фундаментальное значение для нашей кампании у Солнечного Колодца. Я думаю, он сумасшедший, но мне приказано исследовать все, что может помочь. Не хочешь ли провести считывание кое-каких данных?', 'Предвестник Харонем из Шаттрата просит вас при помощи мультифазовых спектрографических очков 6 раз провести считывание мультифазовых данных.', 'Спасибо за помощь. Ты понятия не имеешь, каково общаться с этим \"Доктором\" Ваффелем. Когда он не \"проверяет\", как идут у меня дела, он треплется о том или другом прибамбасе, который можно получить в результате его военно-технических изысканий.', 'Ты провел считывание? Этот гном опять будет на меня орать, если я не доставлю ему его драгоценных данных.', NULL, NULL, 'Считано мультифазовых данных', 'Мультифазовые спектрографические очки (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11881, 'Ценный груз', 'Доводилось ли тебе видеть в небе ветролеты? Любопытнейшая гномская новинка!$B$BДавненько мне хотелось наложить лапу на эти машинки, и вот, наконец, представился удобный случай это сделать! Один из их разведывательных отрядов потерпел катастрофу у Жгучих прудов, в юго-западной части Поля гейзеров.$B$BСвистни в этот свисток у одной из разбившихся машин, и к тебе прибежит моя верная ослица Дженни. Она послушно пойдет за тобой следом и понесет на себе обломки, но тебе следует ее защищать. Если на нее нападут, она начнет ронять груз.', 'Помогите ослице Дженни добраться с места крушения к Феззиксу Штукельверту в деревню Таунка\'ле, не растеряв груз.', '<Феззикс разглядывает добычу.>$B$BДженни немного стерла себе спину, но это ничего, заживет. А вот останки летательного аппарата пострадали несколько более, чем я ожидал… Ну да ничего, как-нибудь разберусь. Ты пока не уходи, еще пригодишься. Надо же восстановить эту игрушечку!', 'Смотри, не подведи! Я на тебя рассчитываю.', NULL, NULL, 'Верните Дженни в безопасное место, не растеряв груз', 'Свисток Дженни', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11882, 'Игра с огнем', 'Хочешь научиться кое-чему новому?$B$BНе знаю, сумеешь ли ты когда-нибудь сравниться со мной в искусстве, но если будешь слушать внимательно, то пару-другую фокусов переймешь. Поговори с мастером-огнеглотателем в любой столице Альянса. Они тебя научат.', 'Поговорите с мастером-огнеглотателем в любой из столиц Альянса.', 'Привет. Хочешь научиться новым пламенным шуткам?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11883, 'Танцы с огнем?', 'Хочешь научиться танцевать с огнем?$B$BЧто же, хорошо. Поговори с мастером огненного танца в любой из столиц Орды. Они тебе помогут.', 'Поговорите с мастером огненного танца в любой из столиц Орды.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11884, 'Нед, \"Повелитель люторогов\"', 'К западу отсюда, на высоких утесах над озером Кум\'уа, обитает презренное создание, известное под именем Недар. Самозваный \"Повелитель люторогов\" охотится в пустошах на раненых и молодых животных – люторогов, неспособных защититься от трусливых атак Неда. Чтобы добавить оскорбительности к истреблению, Нед взрастил своего собственного люторога, который служит ему и как ездовое животное, и как телохранитель.$B$BБольшая редкость – чтобы от Д.Э.Г.О.Ж. исходил призыв к смерти животного, но с порченым люторогом просто необходимо разобраться... Убей обоих и возвращайся ко мне.', 'По заданию Киллинджера Смотрителя Логова из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Недара, \"Повелителя люторогов\", и его спутника, люторога по кличке \"Закуска\".', 'По крайней мере, на какое-то время люторогов оставят в покое. Спасибо, $N.', NULL, NULL, NULL, 'Недар, Повелитель люторогов убито', '\"Закуска\" убито', 'Рекомендуемое количество игроков: 2', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11885, 'Кровные враги', 'Потомки, которых держат в плену жрецы Когтя из Скеттиса, упомянуты в этой книге: Охотница Геззарак, хрустальный гигант Каррог, еретик по имени Темный Крикун Аккарай и Ваккиз Ветрояр. Для того чтобы Терокк вернулся в этот мир, нужно будет убить их всех.$B$BДля этого тебе потребуются свитки затерянных во времени араккоа – с помощью свитков ты сможешь призвать потомков в кругах призыва в Скеттисе. Принеси мне какую-нибудь вещь от каждого из них, но помни, что все они очень сильны, и лучше бы тебе позвать с собой друзей.', 'Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттиса, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра.', 'Отлично! Вот, бери. Я приготовил этот сверток с предметами. символизирующими побежденных тобой врагов. Они позволят тебе вызват Терокка.$B$BОсторожнее, Фэникс. Он самый сильный из всех араккоа, что были и будут. Не надо его недооценивать!', NULL, NULL, NULL, 'Темный Крикун Аккарай убито', 'Каррог убито', 'Геззарак Охотница убито', 'Ваккиз Ветрояр убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11886, 'Необычная активность', 'Как говорится, потехе свой час, $C, но и делу время.$B$BКогда начался праздник, мы получили донесение с Зорамского взморья по поводу резкого усиления активности культа Сумеречного Молота. История праздника восходит к тем самым силам, которым эти безумцы поклоняются, так что это не совпадение. Отправляйся ко входу в Непроглядную Пучину – прямо к югу от него лежат руины. Посмотри, не сможешь ли ты получить какую информацию от этих фанатиков. Если понадобится – выбей ее силой. Когда понадобится помощь проводника, воспользуйся этим маячком.', 'Отправляйтесь в новый лагерь культа Сумеречного Молота к югу от входа в Непроглядную Пучину на Зорамском взморье, что в Ясеневом лесу, и добудьте сумеречную корреспонденцию, затем при помощи тотема-маяка свяжитесь с проводником из Служителей Земли.', 'Очень тревожные вести. Похоже, за смятением местных духов Огня и Воды стоит куда более опасный заговор, так что тут потребуется расследование...', 'Что удалось узнать?', NULL, NULL, 'Сумеречная корреспонденция', 'Тотем-маяк', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11887, 'Неприкосновенный запас', 'Роясь в вещах убитого гнома, вы находите небольшой мешок с припасами, инструментами и удобным рулончиком гномской клейкой ленты. Возможно, этот мешок пригодится Феззиксу Штукельверту, когда придется собирать из обломков гномские ветролеты.$B$BЕсли принести Феззиксу несколько таких мешков, можно получить приличную награду!', 'Соберите 7 гномских ремонтных наборов с тел погибших пилотов-разведчиков со станции Выкрутеня и принесите их Феззиксу Штукельверту в деревню Таунка\'ле.', 'Гномские ремнаборы? Это мне? Теперь чинить ветролеты станет еще проще!', 'Что это у тебя?..', NULL, NULL, 'Гномский ремонтный набор (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11888, 'Поездка в деревню Таунка\'ле', '$gраса:, вождь заставляет меня ждать... Время – это то, чего у Таунка\'ле нет!$B$BО твоем мастерстве ходят слухи. Чем ждать, пока Гаррош пошлет подкрепление, лучше я попрошу тебя пойти и помочь моим соплеменникам.$B$BДеревня Таунка\'ле находится далеко на северо-восток отсюда. Езжай по дороге на восток от крепости, поверни на север на перепутье. Немного погодя ты наткнешься на еще одно перепутье. Следуй по пути на восток, пройдя к югу, а затем к востоку от больших прудов вдоль Затопленных равнин.$B$BКогда прибудешь в деревню, поговори с ведуном земли и неба.', 'Поговорите с ведуном земли и неба в деревне Таунка\'ле.', 'Меня не удивляет, что у вождя орков нет времени выслушивать наши проблемы. Усилия посла – как туман, рассеивающийся по ветру…$B$BНо теперь здесь ты. Посмотрим, сделал ли он правильный выбор, прислав тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11889, 'Смерть с небес', 'Мы неплохо держимся на передовых линиях против этих жуков. Правда, кое-кто из этих нахальных тварей может перелетать те самые передовые линии, и они сильно терзают наши внутренние оборонительные порядки.$B$BЯ реквизировал укрепленные рыболовецкие сети с наших гражданских кораблей. Если руки у тебя приспособлены для метания, с помощью этих сетей можно сдернуть врагов с неба. Нужно уменьшить их количество, чтобы наши силы сумели удержать крепость.', 'По поручению сержанта Молотогора убейте вне стен крепости Отваги 6 порабощенных Плетью изрыгателей огня с помощью укрепленной сети.', 'Мы перебьем их на земле и перебьем, если они повалят на нас с неба. А если эта безродная нежить явится с моря, мы отделаем их так, что мало не покажется.', NULL, NULL, NULL, 'Порабощенный Плетью изрыгатель огня убито', 'Укрепленная сеть', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11890, 'Что там с ними?', 'У гномов на прудах к западу отсюда возникли какие-то проблемы. Поделом им, конечно, ведь они всю землю уже изгадили своими так называемыми изобретениями.$B$BЯ хочу, чтобы ты $gотправился:отправилась: к их насосной станции и $gразузнал:разузнала:, что ж там с ними приключилось. А потом возвращайся, расскажешь.', 'Исследуйте область вокруг насосной станции Выкрутеня, а затем возвращайтесь к ведуну земли и неба в деревню Таунка\'ле.', 'Тревожные новости.$B$BМой народ скоро покинет эти места. Мы собираемся прорваться через боевые порядки Плети, чтобы добраться до нашей столицы, Ледяной Пыли, что на Драконьем Погосте.$B$BНо прежде чем мы сделаем это, нужно разобраться с тем, что натворили гномы в своем безумии.', NULL, NULL, NULL, 'Исследовать локацию', 'Окрестности насосной станции Выкрутеня исследованы.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11891, 'Невинный маскарад', 'Судя по всему, похоже, что к северо-западу от большого скопления служителей культа на Зорамском взморье есть еще один их лагерь, и они разговаривают... с гостями?$B$BЕсли подслушать эти разговоры, то многое можно узнать, $r. Возьми эту сферу. Она поможет тебе принять вид одного из крабов, которых полно на побережье. Подслушай разговоры служителей культа с этими \"гостями\" в северо-западном лагере и, если все пройдет удачно, вернись ко мне и расскажи, что удалось узнать.', 'При помощи сферы Краба проникните в новый Сумеречный лагерь к западу от входа в Непроглядную Пучину на Зорамском взморье в Ясеневом лесу, затем вызовите проводника из Служителей Земли при помощи тотема-маяка.', 'Они хотят призвать в наш мир повелителя холода? Нет! Не позволю им нарушить равновесие!', 'Удалось ли тебе узнать их тайны?', NULL, NULL, 'Сфера краба (Прилагается)', 'Подслушайте разговор сумеречных сектантов.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11892, 'Убить Гарольда Лейна!', 'Ты много $gсделал:сделала: для животных Борейской тундры, $N. Тебе удалось как следует отделать прихвостней Эрнестуэя и преподать им урок, который они нескоро забудут.$B$BГарольд Лейн, в наибольшей степени ответственный за массовую бойню в Награнде, оказался тем же человеком, что отвечает за операции Эрнестуэя в тундре. Он расположился у озера Кум\'уа, к западу отсюда.$B$B<Латориус передает вам покрытый причудливой резьбой дубовый рог.>$B$BНайди Лейна и убей его. Если понадобится наша помощь – труби в рог.', 'По поручению верховного друида Латориуса из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Гарольда Лейна.', 'Увы, Эрнестуэй ушел. А может, его с самого начала тут не было…$B$B<Латориус вздыхает.>$B$BЭтот мерзавец чертовски увертлив, но дни его сочтены. Мы найдем его. А когда найдем...', NULL, NULL, NULL, 'Гарольд Лейн убито', 'Кенарийский рог', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11893, 'Сила стихий', 'Я все пытаюсь объяснить этому глупому гоблину, что его машины ненадежны.$B$BВот сила стихий – дело другое! И когда мое ученичество окончится, я овладею всей их мощью. Однако и того, что я уже знаю, будет достаточно, чтобы помочь нашему другу Феззиксу.$B$BВозьми этот тотем духа ветра и установи его вблизи одного из паровых яростней к западу от деревни. Тотем вберет в себя энергию убитых элементалей. Вернись ко мне с заряженным тотемом, остальное я беру на себя.', 'Дорейн Морозное Копыто из деревни Таунка\'ле просит вас использовать тотем духа ветра, чтобы собрать энергию 10 паровых яростней.', '<Дорейн кивает.>$B$BХорошо. Этого должно хватить, чтобы продемонстрировать Феззиксу то, что я пытаюсь ему объяснить.', NULL, NULL, NULL, 'Собрано энергии', 'Тотем духа ветра', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11894, 'Заплатки', 'Помнишь ту клейкую ленту, что ты мне $gпритащил:притащила:?$B$BНу вот, я нашел ей применение. Корпус этого ветролета пробит в стольких местах, что мне нужно обязательно укрепить его, если я хочу хоть когда-нибудь на нем полететь.$B$BДорейн – вон он, там стоит, – сказал мне, что таунка используют для изготовления водонепроницаемых контейнеров пропаренную кожу карибу. Болотные карибу тут в округе, возле деревни, повсюду живут, да и на Затопленных равнинах их хватает. Найди наилучшие шкуры и выделай их над паром на Полях гейзеров.', 'Принесите 5 пропаренных шкур Феззиксу Штукельверту в деревню Таунка\'ле.', 'Фантастика! Еще несколько таких трюков – и я стану настоящим воздушно-десантным гоблином!', 'Как там дела с выделанными шкурами карибу?', NULL, NULL, 'Пропаренная шкура', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11895, 'Одолеть бурю', 'Из твоего описания следует, что с этими металлическими созданиями несложно будет справиться. Но сначала тебе нужно справиться с бурей.$B$BПозади меня на гряде есть тотем. Когда будешь $gготов:готова:, сосредоточь на нем свою волю – и грянет шторм. Ты $gдолжен:должна: одолеть шторм и таким образом вобрать в себя его сущность.$B$BЕсли там есть еще кто-нибудь, можете сражаться сообща, этого достаточно. А потом, $C, возвращайся ко мне.', 'Одолейте порыв шторма, затем возвращайтесь к ведуну земли и неба в деревне Таунка\'ле.', 'Я чувствую, как ярость шторма кипит в тебе!$B$BТеперь ты готов, $N. Начнем.', 'Тебе уже удалось справиться со штормом?', NULL, NULL, 'Шторм побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11896, 'Уязвимы для молний', 'Ты теперь носишь в себе ярость шторма! Я научу тебя концентрировать эту силу, чтобы выводить из строя роботов в прудах.$B$BВот, возьми этот молниевый жезл. Используй его против роботов механогномов, которых найдешь среди прудов на западе. Против самих механогномов использовать его не трудись – у Великой матери Тайги другие планы на их счет.$B$BА когда сила бури ослабит роботов, разбери их полностью!', 'Уничтожьте 15 любых роботов, кроме механогномов, ослабленных воздействием ярости шторма, в области прудов вокруг насосной станции Выкрутеня.После этого вернитесь к ведуну земли и неба в деревне Таунка\'ле.', 'Теперь, когда с роботами покончено, пора взяться за добычу покрупнее! Увы, я чувствую, что ярость шторма в тебе уже убывает. $B$BТем не менее свое дело она сделала, и думаю, что тебе вполне по плечу сделать следующий шаг и без нее.', NULL, NULL, NULL, 'Ослаблено и уничтожено роботов', 'Молниевый жезл ведуна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11897, 'Заткнуть воронки!', 'Силы Плети и не собираются отступать, $N. Эти проклятые воронки: они соединены с туннелями на всем пути к леднику Ледяной Короны, насколько нам известно.$B$BЕсли годы занятий горным делами меня чему и научили, так это тому, что без опорных балок туннели легко обвалятся после взрыва.$B$BВозьми эту взрывчатку и установи заряды у входов в воронки на хребте над побережьем, к западу отсюда. Возвращайся, когда обвалишь туннели.', 'По поручению сержанта Молотогора используйте зажигательную взрывчатку, чтобы взорвать и обвалить воронки к юго-западу и северо-западу от крепости Отваги.', 'Отличная работа, $N. Без тебя крепость Отваги, быть может, и не продержалась бы против нападающих. Благодаря твоей помощи мы проживем и поборемся еще день…', NULL, NULL, NULL, 'Взрывчатка заложена в южную воронку', 'Взрывчатка заложена в северную воронку', 'Зажигательная взрывчатка', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11898, 'Прорыв', 'В нижнем ярусе Храмового города находится серый алтарь, окутанный светом. Ступи на него, и ты войдешь в некрополь Наксанар.$B$BНо будь осторожнее, $N! Принца Валанара наверняка обороняют его личные вассалы, которые готовы отдать жизнь ради того, чтобы не дать тебе взойти на вершину некрополя.$B$BТебе нужно пробраться через некрополь к трону принца. Если ты не сумеешь одолеть его, $N, боюсь, моему народу никогда не удастся укрыться в надежных стенах Ледяной Пыли...', 'Одолейте принца Валанара с его подручными, Вантрином Безжалостным и Лютионом Злобным, потом явитесь к вождю Зимней Стуже в деревне Таунка\'ле.', 'Теперь, когда принц побежден, владычеству Плети в Борейской тундре на время пришел конец. Конечно, это ненадолго – вскоре они вернутся. Поэтому я буду готовить Дурма к тому, чтобы увести жителей деревни в Ледяную Пыль.$B$B<Вождь медленно качает головой.>$B$BПри всех наших разногласиях с Дурмом, я доверяю его уму и способностям. А сам я не смогу заставить себя уйти из Таунка\'ле. Я буду оборонять деревню, пока не погибну.', NULL, NULL, NULL, 'Принц Валанар убито', 'Лютион Злобный убито', 'Вантрин Безжалостный убито', 'Рекомендуемое количество игроков: 3');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11899, 'Души распроклятых', 'Мехагномы, живущие в прудах к западу отсюда, представляют для нас крупную загадку. Они появились там вскоре после того, как с насосной станции и из ее окрестностей исчезли гномы.$B$BОни неестественны и опасны, с ними необходимо разобраться.$B$BВозьми этот Ловец Душ и используй его на останках мехагномов, чтобы взять их души в плен. Когда ты вернешься, мы выпустим их на волю и посмотрим, что будет.', 'Используйте ловца душ Великой Матери, чтобы захватить души 10 мехагномов со станции Выкрутеня. Затем вернитесь к Великой Матери Тайге в деревне Таунка\'ле.', 'Теперь освободим пойманные тобой души…', NULL, NULL, NULL, 'Поймано душ гномов', 'Ловец душ Великой Матери', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11900, 'Что показывают приборы?', 'Я надеялся, что влияние Нексуса ограничивается этой местностью. Но недавно пошли сообщения со всего Азерота, что геологическая нестабильность растет лавинообразно!$B$BМне нужно постоянно наблюдать за Нексусом, поскольку я работаю над решением. $B$BЯ разместил в Хладарре чувствительные инструменты, замаскировав их под гадальные шары Малигоса. Один лежит во рве рядом с Нексусом, а еще три спрятаны в разных структурах по периметру долины. Посети все четыре места и принеси мне данные их измерений.', 'По просьбе верховного мага Беринанда из лагеря под Маскировочным щитом соберите показания его приборов в Хладарре.', 'Ситуация еще хуже, чем я ожидал.$B$BМалигос вливает слишком много энергии в это место. Если его не остановить, Азерот станет вторым Запредельем!$B$BК счастью, я, кажется, выработал временное решение...', 'Используйте восстановитель измерений вблизи разрыва в Нексусе по просьбе верховного мага Беринарда.', NULL, NULL, 'Показания приборов в Нексусе', 'Показания приборов в южной Хладарре', 'Показания приборов в северной Хладарре', 'Показания приборов в западной Хладарре');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11901, 'Военные? Какие военные?', 'Плеть повсюду, $C. Мы организовали ополчение из фермеров и шахтеров, но ему не справиться.$B$BЕдинственное воинское подразделение, присланное из Крепости Отваги, защищает шахту. Мы о них уже несколько дней никаких вестей не получали!$B$BЕсли ты, правда, хочешь нам помочь, не сходишь ли на шахту – посмотреть, что там творится? Может быть, они смогут прислать нам хотя бы небольшое подкрепление.', 'По просьбе Джеральда Грина из Далечья отправляйтесь на север, в шахту, и выясните, что случилось с направленным туда воинским подразделением.', 'У вас буквально желудок начинает выворачивать, когда вы приближаетесь к зерну. Вонь от него идет почти невыносимая...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11902, 'Ужасное свидетельство', 'Мешки с зерном издают жуткое зловоние, которое наводит вас на мысли о Чуме. Вероятно, это объясняет, что случилось с пехотинцами, защищавшими рудник.$B$BЛучше бы сообщить об этом Джеральду Грину.', 'Возвращайтесь в Далечье к Джеральду Грину.', 'Бедняги... у них не было ни единого шанса!$B$BВсе выглядит так, будто это саботаж. Возможно, дело рук кого-то из Культа Проклятых. Чтоб они провалились со своим культом!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11903, 'Время действовать!', 'Итак, $N. Теперь, когда наши последние бойцы в Далечье или погибли, или их постигла еще худшая участь, нам остается только одно: самим сразиться с Плетью.$B$BМы развернули ополчение в том, что осталось от Далечья. Без твоей помощи у них практически нет надежды на победу. Иди и протяни им руку помощи. А я с ребятами останусь наблюдать за тропой. Мы не можем позволить Плети прорваться!', 'По просьбе Джеральда Грина из Далечья убейте 14 чумных падальщиков.', 'Ты обратился к Плети на единственном языке, который ей понятен: на языке насилия и смерти. К сожалению, Плеть все никак не остановится...', NULL, NULL, NULL, 'Чумной падальщик убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11904, 'Плоды трудов наших', 'Силы плети все прибывают... но мы не можем сдаться! Послушай, $N. В этой шахте осталась одна повозка с последней порцией руды, которую Альянс теперь долго не увидит на этой стороне континента.$B$BПроблема в том, что пусковой механизм повозки заблокирован. Когда сюда пришли военные, капитан Якобс реквизировал все важное оборудование, включая и ключ от повозки.$B$BЧума, поразившая всех солдат в шахте, должно быть, сразила и Якобса. Добудь у него ключ и спаси груз руды.', 'Отправляйтесь на шахту Далечья, добудьте ключ от повозки у капитана Якобса и используйте его для того, чтобы пустить повозку с рудой. По завершении задания вернитесь к Джеральду Грину в Далечье.', 'Спасибо, $N. Эта руда будет жизненно необходима Альянсу в будущем. Я хотел бы думать, что мы сегодня сделали большое дело.', NULL, NULL, NULL, 'Повозка с рудой запущена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11905, 'Оттянуть неотвратимое', 'Я определил причину нестабильности!$B$BСиловые линии Азерота перенаправлены на Нексус. Потрясающе! Если бы я мог провести остаток своих дней, исследуя эту аномалию…$B$BУвы, придется заняться текущими проблемами. Поток магической энергии расширяет разлом между измерениями.$B$BВ глубине Нексуса творится то, из-за чего ткань нашей вселенной истончается. Остановить это я не могу, однако нашел способ замедлить это.$B$BОтнеси это в Нексус и активируй поблизости от формирующегося разлома.', 'Используйте восстановитель измерений вблизи разлома в Нексусе по просьбе верховного мага Беринарда из лагеря под Маскировочным щитом.', 'Отличная работа, $N! Колебания уже начали слабеть.$B$BЕсли повезет, благодаря твоим усилиям мы получим отсрочку, достаточно долгую, чтобы успеть помешать планам Малигоса.', 'Ты уже побывал у разрыва в Нексусе?', NULL, NULL, 'Пространственный разлом стабилизирован', 'Восстановитель измерений (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11906, 'Очищение прудов', '$gПо лицу Стальных Глаз скатывается слеза.>$B$BЯ знаю, ты направляешься обратно к прудам, что на западе. Раз уж ты все равно там будешь, у меня есть для тебя поручение.$B$BГномы, которых не волнует судьба земли, загрязнили ее своей техникой. Я прошу тебя собрать валяющиеся на земле запчасти.$B$BПринеси их мне сюда. Я позабочусь о том, чтобы они были утилизованы должным образом прежде, чем мы уйдем отсюда навсегда.', 'Соберите 15 запасных деталей Выкрутеня и доставьте их Стальным Глазам в деревню Таунка\'ле.', 'Таунка считают справедливым оставить землю девственно чистой, когда уходят жить в другое место.$B$BМы отправимся в нашу столицу, Ледяную Пыль, и очень скоро. Твоя помощь поможет нам ускорить переселение.$B$BСпасибо тебе.', 'Если мы не будем заботиться о земле, она не станет долго нас терпеть!', NULL, NULL, 'Запасные детали Выкрутеня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11907, 'Подручные Механозода', 'Известно, что у механизатора Механозода имеется четверо подручных, которые управляют роботами в прудах.$B$BИх необходимо уничтожить!$B$BНаши выносливые гонцы и снежные следопыты говорят, что, если открыть клапаны на Западной, Северной, Центральной и Южной станциях, то эти подручные тут же явятся, чтобы устранить помеху в работе.$B$BСтанции расположены вокруг вращающихся маячков в прудах вокруг насосной станции.$B$BТоропись, $N!', 'Уничтожьте Шатунишку, ЕД-210, Макса Шмякса и Шлифовальщика, затем вернитесь к Ведуну земли и неба в деревню Таунка\'ле.', 'Благодарю тебя, $N.$B$BТеперь, когда эти странные создания ликвидированы, остальное будет проще.$B$BМы тебе искренне признательны.', NULL, NULL, NULL, 'Шатунишка убито', 'ЕД-210 убито', 'Макс Шмякс убито', 'Шлифовальщик убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11908, 'Справочные материалы', 'Я ведал уборочными големами – это была ответственная работа, пока Плеть не разорила большинство наших пахотных земель. У меня, впрочем, есть идея, как снова сделать големов полезными.$B$BЯ думаю, что могу переделать схему сборщиков урожая так, чтобы они помогли нам в войне с Плетью.$B$BЯ еще не большой специалист в этом, так что мне потребуется сверяться с руководством. Проблема в том, что я оставил его в мастерской... а моя мастерская, к несчастью, – вон то горящее здание рядом с шахтой. Как думаешь, удастся тебе вытащить оттуда руководство?', 'По просьбе Иеремии Хоунинга вынесите книгу \"Поля, заводы и мастерские\" из горящего здания рядом с рудником Далечья.', 'Отлично! Здесь должна быть нужная мне информация.', 'Тебе удалось вынести мою книгу?', NULL, NULL, 'Поля, заводы и мастерские', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11909, 'Убить механизатора!', 'Ясно, что этот механизатор Механозод не в своем уме. Если его идея исцеления и бессмертия состоит в том, чтобы все мы стали роботоподобными рабами, то его нужно остановить!$B$BВетра, что ведут меня, шепчут, что он находится на вершине насосной станции в центре прудов к западу отсюда.$B$BСкорее всего, его можно будет найти в лачуге на самом верху постройки. Войди туда и исследуй его труды.$B$B$N, тебе нужно сразиться с Мехазодом, если все мы хотим жить!', 'Изучите Руководство механизатора и принесите голову Механозода Великой матери Тайге в деревню Таунка\'ле.', '<Великая мать испускает вздох облегчения.>$B$BТак значит все сделано... Ты спасла нас! Если бы тебе не удалось его остановить, кто знает, как далеко зашли бы последствия этой ошибки гномов?$B$BУчитывая угрозу со стороны синих драконов, войну Нексуса, не говоря уже о Короле-личе – нам меньше всего нужно, чтобы на свободе бегало спятившее творение $Nв!$B$BСпасибо, $N.', 'С ним покончено? Угроза, исходящая от механизатора Механозода, ликвидирована?', NULL, NULL, 'Руководство Механизатора изучено', 'Голова Механозода', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11910, 'Тайны Древних', 'Постепенно становится ясно, что нестабильность в этой местности оказывает воздействие и на обитающих тут существ.$B$BЯ особо заинтересовался ледовыми древами и их недавними изменениями. Подозреваю, что их трансформация в зачарованные древа поможет нам разобраться в наших затруднениях.$B$BДля моих исследований мне нужны образцы и с тех, и с других. Поторопись...', 'По просьбе верховного мага Беринарда из-под Маскировочного щита принесите 3 ледяных осколка и 3 щепки зачарованного древа, собранных с древ в Хладарре.', 'Да-да. Вот эти отлично подойдут.$B$BСпасибо тебе, $R.', 'Ты уже собрал образцы, что я просил?', NULL, NULL, 'Ледяной осколок', 'Щепка зачарованного древа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11911, 'Преображение', 'Хотя мы, может быть, стоим на пороге прекращения нашего существования, я не перестаю изумляться. За короткое время, проведенное здесь, я узнал больше, чем за десят$Nия исследований.$B$BЭти древа постоянно находятся под воздействием магической энергии. Она буквально на глазах превращает их в нечто... иное.$B$BЯ уверен, что это еще одна ступень их трансформации. Я хочу, чтобы ты $gотправился:отправилась: прямо в Нексус и $gнашел:нашла: какие-нибудь свидетельства об их конечном состоянии.$B$BПожалуйста, будь осторожнее...', 'По заданию верховного мага Беринанда из лагеря под Маскировочным щитом отправьтесь в Нексус и соберите 5 магических обломков кристаллических заступников.', 'Как интересно!$B$BИ ты говоришь, они тоже агрессивны? Это может говорить о том, что за всеми манипуляциями стоит некий разум. Это может быть вовсе не естественным явлением…$B$BПожалуйста, $N, прими это в знак нашей благодарности за твои усилия. В Даларане узнают о твоих услугах нам.', 'Кристаллические древа… Существуют ли они?', NULL, NULL, 'Магический обломок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11912, 'На подножном корму', 'О! Как приятно в кои-то веки увидеть новое лицо! А то уже такое ощущение, будто мы тут вообще отрезаны от мира.$B$BВо всяком случае от снабжения мы уже несколько дней как отрезаны, так что перспективы у нас, скажем так, мрачноватые. По правде говоря, мы с самого начала шли на верную смерть, если хочешь знать.$B$BА может, это просто не по мне, все это насилие, убийства – не говоря уже о здешних холодах! Эх, сидеть бы сейчас в Даларане, изучать древние тексты...$B$BНо ближе к делу. Наши припасы на исходе. Пожалуйста, постарайся раздобыть какой-нибудь пищи и принеси ее мне!', 'Соберите 10 ягод снежевики с кустов снежевики в Хладарре по просьбе библиотекаря Серры из лагеря под Маскировочным щитом.', 'Ну, конечно, это немного, но все-таки поможет нам протянуть лишний день.$B$BДумаю, это будет справедливая плата за труды?', 'Ну что, удалось раздобыть что-нибудь съедобное?', NULL, NULL, 'Снежевика', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11913, 'Надо действовать наверняка', 'Я слышала, что ты $gсказал:сказала: Джеральду, и мне это совсем не нравится. Если сектантам удалось отравить зерно в шахте этой своей чумой, они с легкостью могли отравить зерно и снаружи.$B$BУ нас нет времени перебирать зерно, отделяя хорошее от зараженного. Нужно действовать быстро, и придется сжечь все.$B$BВозьми этот факел и сожги все мешки с зерном, какие найдешь. Будет настоящей трагедией, если мы переживем эту атаку только для того, чтобы стать жертвами чумы...', 'По просьбе Венди Даррен сожгите 8 мешков с зерном Далечья, воспользовавшись факелом Венди.', 'Спасибо, $N. Было бы ужасно видеть, как переживших нападение на Далечье погубило бы зараженное зерно...', NULL, NULL, NULL, 'Сожжено зерна Далечья', 'Факел Венди', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11914, 'Сохранение секретности', 'Само наше существование здесь зависит от нашей скрытности. Если щит падет, даже на мгновение, приспешники Малигоса будут тут как тут.$B$BОдной из моих обязанностей является возобновление и восполнение маны у военных магов, чтобы не ослабела их сосредоточенность. Поскольку мы отрезаны от поставок, мне приходится импровизировать.$B$BТы можешь помочь мне, $N.$B$BСовсем рядом с Нексусом среди потоков магической энергии плавают волшебные змеи. Сраженный змей выделяет субстанцию маны, которая может мне пригодиться.', 'По просьбе библиотекаря Серры убейте волшебных змеев и принесите за Маскировочный щит 5 субстанций маны Нексуса.', 'Твои услуги Даларану не останутся незамеченными, $R.$B$BЯ надеюсь, ты сочтешь эту плату достаточной.', 'Удалось собрать необходимое количество субстанций маны?', NULL, NULL, 'Субстанция маны Нексуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11915, 'Игра с огнем', 'Хочешь научиться кое-чему новому?$B$BНе знаю, сумеешь ли ты когда-нибудь сравниться со мной в искусстве, но если будешь слушать внимательно, то пару-другую фокусов переймешь. Поговори с пламеглотателем-виртуозом в любой столице Орды. Они тебя научат.', 'Поговорите с пламеглотателем-виртуозом в любой из столиц Орды.', 'Привет. Хочешь научиться новым пламенным шуткам?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11916, 'Воин Адского Крика', 'Ты встречаешь опасности лицом к лицу и сокрушаешь их железной рукой. Именно благодаря тебе, $N, Орда теперь надежно закрепилась в Нордсколе.$B$BНо наши труды здесь только начинаются. Наш путь лежит к Ледяной Короне! Мы должны сокрушить ее стены!$B$BСейчас же тебе следует отправиться на восток, в деревню Таунка\'ле. У наших союзников (таунка) большие неприятности, им нужна помощь. Добудь себе средство передвижения у Дуркота Брата Волка, смотрителя стойл. В Таунка\'ле отыщи вождя Зимнюю Стужу.', 'Отыщите вождя Зимнюю Стужу в деревне Таунка\'ле.', 'Боюсь, твоя помощь пришла слишком поздно. Многие из моих собратьев уже оставили Таунка\'ле. Они ищут убежища в Драконьем Погосте, далеко на востоке.$B$BОднако тут у нас еще много работы, и мало рук, чтобы ее выполнить…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11917, 'Ответный удар', 'Мы должны действовать! Мы должны сохранить равновесие. Время против нас.$B$BВозвращайся в лагерь на Зорамское взморье с большими Камнями Льда. Они пользуются ими для связи с элементалями, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', 'Убейте лейтенанта Хладоволна, помощника Ахуна, вызвав его при помощи Камня Льда на Зорамском взморье в Ясеневом лесу, затем вернитесь к старейшине Служителей Земли в столицу.', '', NULL, NULL, NULL, 'Лейтенант Хладоволн убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11918, 'Первое знакомство', 'Это война, $gсмертный:смертная:, и мы – в гуще схватки!$B$BВаши мелкие свары из-за земель или денег бледнеют перед этим конфликтом. Нас ждет встреча с Аспектом Малигосом и его синими драконами. Тебе достаточно знать, что, если Малигос одержит победу, этого мира больше не будет.$B$BНас тут мало, и мы сражаемся против многих. Можно считать, что мы обречены, и, если нам удастся хотя бы задержать врага, это уже будет успех.$B$BСтупай же. Найди себе какое-нибудь дело, пока я решу, что делать с тобой.', 'Убейте 10 чароплетов Хладарры по просьбе Релораза из лагеря под Маскировочным щитом.', 'Ну хорошо, $C, теперь, после первого знакомства с врагом, пришло время браться за работу.', NULL, NULL, NULL, 'Чароплет Хладарры убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11919, 'Охота на драконов', 'Синие начали наносить на своих драконов таинственные руны. Я должен выяснить их значение.$B$B<Релораз протыкает руку копьем и смазывает кровью наконечник.>$B$BВозьми это копье и воздействуй им на одного из них. Подожди, пока он не подчинится, а затем принеси мне, пока не кончится действие крови.$B$BИх детеныши кормятся на северо-западном крае долины.', 'По просьбе Релораза используйте копье с окровавленным наконечником, чтобы подчинить детеныша дракона Нексуса, а затем принесите Релоразу копье назад за Маскировочный щит.', 'Судьба этих юных драконов не должна лежать бременем на твоей совести, $R. За все это несет ответственность Малигос.$B$BЯ без устали тружусь над раскрытием тайн этих рун. И, конечно, мы не собираемся отнимать больше жизней, чем это необходимо.', NULL, NULL, NULL, 'Пленный дракон Нексуса', 'Копье Релораза', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11920, 'Сектанты среди нас', 'На этом алтаре полным-полно знаков Культа Проклятых. Похоже, фанатики с материка добрались уже и до Нордскола. Благоразумие требует сообщить об этом капитану корабля.$B$BВероятно, его можно найти на палубе.', 'Поговорите с капитаном \"Левшой\" Люггером на \"Рассекателе туч\" в Крепости Отваги.', 'Сектанты? Внизу?! Придется мне всю команду выпороть!$B$BПослушай... почему бы... почему бы адмиралу Кэнтлбри не разобраться с этой... с этой ситуацией?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11921, 'Опять бросаем факелы', 'Привет, $gфакельный жонглер:факельная циркачка:! Нравится устраивать огненную неразбериху? Приятно слышать! Думаешь, ты так уж и $gкрут:крута:?Давай проверим...$B$BПравила ты знаешь: бросаешь факел в отмеченные жаровни. Но на сей раз у тебя больше времени и НАМНОГО больше жаровен.$B$B<Готов:Готова:?', 'Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом.', 'Ух ты! Ну ты и даешь! Может, на следующий год получишь работку на празднике!', NULL, NULL, NULL, 'Попадите в 20 жаровен.', 'Тренировочные факелы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11922, 'Жонглирование факелами', 'Значит, ты хочешь научиться жонглировать горящими факелами? А у тебя есть необходимые для этого качества? Ловкость? Быстрота? Отвага? Если ты думаешь, что да, то давай попрактикуемся немного!$B$BБери эти факелы и беги к костру. Над ним увидишь жаровни, с горящими метками. Бросай факелы в отмеченные жаровни. И делать это надо быстро! До того, как метка погаснет, если хочешь получить очко за попадание!$B$BПопади в достаточное количество отмеченных жаровен прежде, чем выйдет время, затем возвращайся назад... для следующего урока.', 'Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом.', 'Отлично! Ты научишься жонглировать факелами – не успеешь и глазом моргнуть! Ну, готовься. Следующее испытание будет погорячее...', NULL, NULL, NULL, 'Попадите в 8 жаровен.', 'Тренировочные факелы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11923, 'Поймай факел!', 'Ну, факел ты теперь бросать умеешь, так посмотри, сможешь ли ты его еще и поймать!$B$BБери эту связку незажженных факелов. Ступай к костру и подбрось факел высоко в воздух. Поймай его прежде, чем он коснется земли... затем снова подбрось его в воздух! Поймай четыре факела подряд, затем возвращайся ко мне.$B$BОсторожнее! Они опасны при ударе о землю! И не пропусти ни одного! Если пропустишь, придется вернуться к костру и начать все с начала. Удачи!', 'Поймайте подряд 4 факела, затем поговорите с пламеглотателем-виртуозом.', 'Не обжегся? Если да, то дважды подумай прежде, чем играть с огнем...$B$BШучу! Все вышло здорово! И это уже не шутка. Ты – отличный огненный жонглер! Теперь иди, веселись!', 'Правда, весело факелами жонглировать? Только осторожнее, а то подпалишься!', NULL, NULL, 'Поймать 4 факела подряд.', 'Незажженные факелы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11924, 'Опять жонглирование факелами', 'При жонглировании факелами определенно приходится быть начеку. Как думаешь, долго продержишься?$B$BПосмотрим-ка...', 'Поймайте 10 факелов подряд, затем поговорите с пламеглотателем-виртуозом.', 'Как рука, $N? Вид у тебя просто зашибенский. Мастер-жонглер, как есть!', 'Правда, весело факелами жонглировать? Только осторожнее, а то подпалишься!', NULL, NULL, 'Поймайте 10 факелов подряд.', 'Незажженные факелы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11925, 'Опять жонглирование факелами', 'При жонглировании факелами определенно приходится быть начеку. Как думаешь, долго продержишься?$B$BПосмотрим-ка...', 'Поймайте 10 факелов подряд, затем поговорите с пламеглотателем-виртуозом.', 'Как рука, $N? Вид у тебя просто зашибенский. Мастер-жонглер, как есть!', 'Правда, весело факелами жонглировать? Только осторожнее, а то подпалишься!', NULL, NULL, 'Поймайте 10 факелов подряд.', 'Незажженные факелы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11926, 'Опять бросаем факелы', 'Привет, $gфакельный жонглер:факельная циркачка:! Нравится устраивать огненную неразбериху? Приятно слышать! Думаешь, ты так уж и $gкрут:крута:?Давай проверим...$B$BПравила ты знаешь: бросаешь факел в отмеченные жаровни. Но на сей раз у тебя больше времени и НАМНОГО больше жаровен.$B$B<Готов:Готова:?', 'Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом.', 'Ух ты! Ну ты и даешь! Может, на следующий год получишь работку на празднике!', NULL, NULL, NULL, 'Попадите в 20 жаровен.', 'Тренировочные факелы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11927, 'Встреча в трактире', 'Эй, $N! Тут одна девушка в таверне о тебе спрашивала. Ее зовут Лерисса.$B$BНет, не думаю, что она знакома с тобой, но сказала, что ей нужна твоя помощь. Судя по всему, она просто в отчаянии.', 'Найдите Лериссу в таверне в крепости Отваги.', 'Спасибо, что пришел ко мне. Я не знала, к кому еще обратиться.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11928, 'Далечье', 'Мои ребята сумеют продолжить с этого места, $N. Крепость Отваги построена так, чтобы выдержать неприятности и покруче этой. Я беспокоюсь только о наших пахотных землях и шахте в Далечье.$B$BМы послали целый отряд для защиты наших горняков прямо перед вторжением – должно быть, они сумеют защитить гражданское население.$B$BТамошними селянами руководит Джеральд Грин. Проход через северную стену крепости Отваги выведет тебя прямо к нему. Узнай, чем ты можешь ему помочь.', 'Отправляйтесь в Далечье в Борейской Тундре и поговорите с Джеральдом Грином.', 'Ты пришел нам на помощь? Тогда ты как раз вовремя!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11929, 'Гибель деревни Таунка\'ле', 'Для нас все потеряно, $N. Это место было нашим домом долгие поколения, но теперь здесь слишком опасно. Здесь царит смерть... Смерть и память о том, что когда-то было.$B$BЯ призвал к бегству из Таунка\'ле. Все оставшиеся в живых таунка должны покинуть деревню вместе и направиться в нашу столицу, Ледяную Пыль, расположенную на Драконьем Погосте.$B$B<Зимняя Стужа указывает на восток.>$B$BТы $gдолжен:должна: помочь моим соплеменникам добраться в безопасное место, $N. Мать Тауранук ждет тебя у ворот деревни. Скорее! Силы Плети приближаются со всех сторон!', 'Поговорите с матерью Тауранук у ворот деревни Таунка\'ле.', '<Мать Тауранук утирает слезы.>$B$BБыло время, когда я могла бродить по этой тундре, и только бесконечные снега открывались моему взору.$B$BНо снег покинул нас – это знак, что наше время здесь тоже подошло к концу. Мы оставляем позади себя деревню Таунка\'ле, Борейскую Тундру и много-много счастливых воспоминаний...$B$B<Мама Тауранук всхлипывает.>$B$BБыть может, в будущем нам доведется узнать радость возвращения – вместе со снегом.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11930, 'Через Трансборею', 'Путь через Трансборею на восток – единственная возможность добраться до Драконьего Погоста. Множество опасностей поджидает тебя во время путешествия через тундру. Опасайся Плети и ее влияния на зверей, населяющих эти земли. Пошли слухи даже о наших братьях и сестрах таунка, поднятых из мертвых и нападающих на караваны на пути к Драконьему Погосту! Защищай свой караван и доставь беженцев в безопасное место!$B$BВартук Дитя Льда ждет тебя за мостом, ведущим на Драконий Погост.', 'Проводите эвакуированных жителей Таунка\'ле через Трансборею на границу Драконьего Погоста, где их ждет Вартук Дитя Льда.', '<Вартук бросает на вас мрачный взгляд.>$B$BЛедяной Пыли более не существует...', NULL, NULL, NULL, 'Безопасный проход в Драконий Погост', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11931, 'Взломать шифр', 'Я чувствую определенную странность в здешних драконах, но значение рун, нанесенных на их тела, по-прежнему ускользает от меня.$B$BБез кодекса их интерпретация займет слишком много времени.$B$BНедалеко отсюда обитает один предатель ордена Кирин-Тор, Калерас, у которого, вероятно, есть экземпляр той книги, что мне нужна. У его приспешников есть руны, которые мне понадобятся для расшифровки.$B$BПоторопись, $gсмертный:смертная:. С каждым мгновением сила Малигоса прибывает.', 'Добудьте Лазурный кодекс у инквизитора Калераса и 3 мерцающих руны у его чародеев Хладарры и отнесите Релоразу за Маскировочный щит.', 'Ты отлично справился, $R.$B$BБудем надеяться, что мы найдем ключ, который можно будет использовать против Малигоса.', 'Поспеши, смертный.$B$BСилы Малигоса прибывают с каждой секундой.', NULL, NULL, 'Мерцающая руна', 'Лазурный кодекс', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11932, 'Дураки и трусы', 'Послушай меня, $N. Не хочу никого обидеть, но операция, во главе которой поставили Тассариана, была чистым самоубийством!$B$BГорстке наших бойцов было поручено атаковать самое крупное объединение Плети в этом регионе!$B$BМожет, я и идиот, но, на мой взгляд, штурмовать зиккурат Плети рядом с зачумленным нерубским городом с отрядом в десяток бойцов – это даже не смешно.$B$BЕсли ты все еще хочешь отыскать Тассариана, можешь отправиться на восток к клыкарру по имени Атаика. Он живет в Каскале, на северо-востоке. Ну, удачи тебе в твоем безумном предприятии!', 'Поговорить с Атаикой в Каскале, к северо-востоку от крепости Отваги.', 'Да, я помню того, о ком ты говоришь. Он носил знаки Каркута.$B$BДа оборонит Каркут наших павших!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11933, 'Похищение пламени Экзодара', 'Этот пламень, похищенный самого сердца Экзодара, омывает вас теплом. Эта неукротимая сила незнакома вам, но Праздничный сказитель должен знать больше...', 'Верните Пламя Экзодара Праздничному сказителю.', 'Этот огонь кажется таким новым... Говоришь, он из Экзодара? Невероятно! Пробраться на тот корабль… Конечно, я тебе за это заплачу. Если найдешь еще что-нибудь подобное, приходи снова!', 'Ты поистине светишься, $R. Что у тебя там?', NULL, NULL, 'Пламя Экзодара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11935, 'Похищение пламени Луносвета', 'Этот пламень, похищенный из Луносвета, омывает вас теплом. Эта неукротимая сила незнакома вам, но хранитель мудрости Празднества должен знать больше...', 'Верните пламя Луносвета хранителю мудрости Праздника.', 'Какой яркий огонь! Говоришь, он из Луносвета? Невероятно! Теперь, когда у нас есть пламень изо всех четырех городов, нам все по плечу!', 'Ты поистине светишься, $C. Что у тебя там?', NULL, NULL, 'Пламя Луносвета (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11936, 'Наклевывается план!', 'Наши цели в здешних краях просты. Надо скрываться от Малигоса, наблюдать за его отпрысками и мешать ему, чем только сумеем.$B$BВот это-то я и хочу поручить тебе.$B$BСиние драконы откладывают яйца у подножия Нексуса. Под влиянием столь мощной магической энергии яйца проклюнутся быстрее, и неизвестно, как это скажется на детенышах драконов.$B$BЧестно говоря, я и не стремлюсь это проверять. Перебей местных драконидов и используй их застывшие топоры, чтобы разбить яйца.', 'Убейте драконидов из Хладарры и используйте их застывшие топоры, чтобы разбить 5 яиц синих драконов по просьбе Релораза из лагеря под Маскировочным щитом.', 'Мне очень жаль уничтожать яйца драконов, пусть даже вражеских.$B$BНо увы, на войне как на войне…', NULL, NULL, NULL, 'Уничтожено драконьих яиц', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11938, 'Отвлечь противника', 'Теперь, когда у нас есть этот талисман, мне не составит труда раздобыть необходимые сведения. Однако Плеть в Храмовом городе скоро обнаружит, что что-то не так.$B$BОтразить полномасштабную атаку я не сумею. А может, и сумею… но проверять не хочется!$B$BПопробуй пробраться туда и организовать несколько несчастных случаев. Есть надежда, что это их отвлечет, и эти двое успеют расколоться... нет, естественно, в переносном смысле! Возьми с собой Лурида, он тебе пригодится.', 'Подстройте 20 несчастных случаев, в которых пострадает Плеть в Храмовом городе Эн\'кила, по просьбе Тассариана из Стонущего зиккурата в Борейской тундре. Используйте кости Лурида, если вам понадобится помощь.', 'Это позволит нам выиграть время. Исидорус согласился сотрудничать с нами, но без этой отсрочки я бы не справился.', NULL, NULL, NULL, 'Несчастный случай в Эн\'кила', 'Кости Лурида', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11940, 'Охота на драконов', 'Мне нужно больше детенышей драконов, чтобы продолжить исследовать руны, покрывающие их тела.$B$BИх можно найти у северо-западного края долины…$B$B<Релораз прокалывает копьем руку и смазывает наконечник своей кровью.>$B$BВот, возьми копье и воздействуй им на одного из детенышей, пока не подчинишь его. А потом принеси его мне, пока кровь еще действует.', 'По просьбе Релораза используйте копье с окровавленным наконечником, чтобы подчинить детеныша дракона Нексуса, а затем принесите ему копье за Маскировочный щит.', 'Судьба этих юных драконов не должна лежать бременем на твоей совести, $R. За все это несет ответственность Малигос.$B$BЯ без устали тружусь над раскрытием тайн этих рун.$B$BИ уж конечно, мы не собираемся отнимать больше жизней, чем это необходимо.', NULL, NULL, NULL, 'Пленный дракон Нексуса', 'Копье Релораза', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11941, 'Загадочный обломок', 'В этом металлическом обломке есть что-то, что не позволяет вам выбросить его.$B$BБыть может, Релораз сможет пролить свет на его назначение.', 'Принесите искрометный обломок Релоразу за Маскировочный щит.', 'С твоей стороны было мудро принести эту вещь мне, $N.$B$B<Релораз рассматривает обломок и медленно кивает.>$B$BЕсли ты и вправду хочешь внести свой вклад в наши усилия, то, сколь бы это ни было рискованно, я расскажу тебе о том, что это и для чего оно нужно.', 'Что это ты нашел, $C?', NULL, NULL, 'Искрометный обломок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11942, 'Слова могущества', 'Так сказал лич, $N. Тайну входа в Наксанар хранят верховные жрецы из Эн\'кила.$B$BОтправляйся к Шпилю Крови, Шпилю Боли и Шпилю Порчи и убей жрецов.$B$BВозвращайся, когда в твоих руках окажутся три свитка.', 'По поручению Тассариана, который находится у Стонущего зиккурата, отправляйтесь в храмовый город Эн\'кила и раздобудьте свиток верховного жреца Талет-Ха в Шпиле Боли, свиток верховного жреца Наферсета – в Шпиле Порчи и свиток верховного жреца Андората – в Шпиле Крови.', 'Отличная работа, $N. А теперь – последний кусочек информации.', 'Я смотрю, ты не торопишься? Не знаю, сколько еще я смогу сдерживать этого лича.', NULL, NULL, 'Свиток верховного жреца Андората', 'Свиток верховного жреца Наферсета', 'Свиток верховного жреца Талет-Ка', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11943, 'Магическая клетка', 'Ты $gобнаружил:обнаружила: фрагмент особой тюрьмы, $N.$B$BПодобные клетки подручные Малигоса используют для содержания пленных магов и иных магических существ, но эта тюрьма предназначалась для… для кого-то более могущественного.$B$BЕсть надежда, что враг нашего врага окажется другом. Отыщи оставшиеся фрагменты клетки.$B$BСкорее всего, они находятся в руках самых доверенных приверженцев Малигоса.', 'Добудьте тюремную обшивку у генерала Церулеана и энергетическое ядро у завоевателя Кровозмея по просьбе Релораза из лагеря под Маскировочным щитом.', '<Когда Релораз берет в руки собранные вами фрагменты, они начинают ярко светиться.>$B$BГотово!$B$BЯ чувствую, что в этой тюрьме заточено могущественное существо. Будем надеяться, что оно окажется союзником…', 'Удалось ли тебе обнаружить другие части тюрьмы?', NULL, NULL, 'Энергетическое ядро', 'Тюремная обшивка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11944, 'В окружении!', 'Наша ситуация почти безнадежна. Нам дали приказ занять Стонущий зиккурат с горсткой воинов.$B$BНам очень повезет, если нам удастся удержать эту позицию и не сдать ее Плети. Нас превосходят числом, многие из нас ранены, а бежать в случае чего здесь некуда.$B$BЕсли ты сможешь немного помочь нам, мы, наверное, смогли бы укрепить нашу позицию. Если ты убьешь некоторое количество нежити вокруг постройки, мы сдержим их продвижение.', 'По заданию капрала Венна убейте 7 защитников зиккурата.', 'Ты выиграл нам немного времени, $N. Вопреки всему мы надеемся, что придет подкрепление из крепости Отваги.', 'Тебе что-нибудь удалось сделать? Мы тут в такой переделке...', NULL, NULL, 'Защитник зиккурата убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11945, 'Подготовка к самому худшему', 'Темные времена для нас настали. Дух Каркута ходит по земле, собирая духи мертвых клыкарров.$B$BСыновья тумана забрали многих наших братьев. Скоро наша любимая Каскала превратится в пепелище.$B$BНо есть еще надежда. Быть может, не для нас – но ведь мы отослали наши семьи в Уну\'пе. Мы сражаемся здесь за то, чтобы у тех, кто там, было будущее.$B$BИм понадобятся съестные припасы, или они умрут с голода. В Уну\'пе еды маловато. Собери что-нибудь, пока для наших родных еще не слишком поздно.', 'По просьбе Утайка соберите в Каскале 8 ящиков припасов Каскала.', 'Благодарю тебя, $N. Эти припасы утолят голод наших родных и детей. Даже если Каскала падет, клан должен жить дальше.', 'Тебе все удалось, $N? Наши родные в Уну\'пе зависят от успеха твоих усилий.', NULL, NULL, 'Припасы Каскала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11946, 'Керистраза', 'Я... свободна?$B$BМне было суждено вечно скитаться в пустынной бездне, и теперь – я спасена и свободна? Неизмерима глубина моей благодарности, $gсмертный:смертная:.$B$BКогда я отказалась подчиниться воле Малигоса, он приковал меня к этой тюрьме, а затем расколол ее и разбросал осколки. Проживи я еще сотни твоих жизней, я и тогда не забуду этой услуги.$B$BБыть может, в свое время я найду способ отплатить тебе за нее. А сейчас мы должны сосредоточить наше внимание на Малигосе. Я ослабела, а сделать нужно так много.$B$BМне нужна твоя помощь, $N.', 'Поговорите с Керистразой, когда будете готовы к встрече с Малигосом.Если потеряете свою магическую клетку, поговорите с Релоразом у Маскировочного щита.', 'Мы не можем ждать, пока ко мне вернутся силы. $B$BЯ должна положиться на тебя в процессе подготовки...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11947, 'Ответный удар', 'Мы должны действовать! Мы должны сохранить равновесие. Время против нас.$B$BЕсть один лагерь в тени Этель-Ретор в северо-западных Пустошах. Там, при помощи Камней Льда, они держат связь с элементалями, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', 'Убейте лейтенанта Градня, помощника Ахуна, вызвав его при помощи Камня Льда к Этель-Ретор в Пустошах, затем вернитесь к старейшине Служителей Земли в столицу.', 'Доброе дело. Оно может показаться малым, но даже это поможет великой битве. Прими это вместе с моим благословением, а потом возвращайся, ибо у меня найдется для тебя еще дело.', NULL, NULL, NULL, 'Лейтенант Градень убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11948, 'Ответный удар', 'Мы должны действовать! Мы должны сохранить равновесие. Время против нас.$B$BУ Нептулона издавна была операционная база на островке к западу от Тернистой долины. Там сумеречный культ при помощи Камней Льда держит связь с царством Хозяина Приливов, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', 'Убейте лейтенанта Промозглый Ветер, помощника Ахуна, вызвав его при помощи Камня Льда на островке элементалей воды к западу от Тернистой долины, затем вернитесь к старейшине Служителей Земли в столицу.', 'Доброе дело. Оно может показаться малым, но даже это поможет великой битве. Прими это вместе с моим благословением, а потом возвращайся, ибо у меня найдется для тебя еще дело.', NULL, NULL, NULL, 'Лейтенант Промозглый Ветер убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11949, 'Не сдаваться без боя!', 'Каскала для нас священное место, $r. Наших предков привел сюда дух самой Таютки.$B$BА теперь эти гнусные твари появляются из тумана и нападают на нас без всякого повода!$B$BНо мы им покажем, что копья у нас не только для того, чтобы бить китов! Сражайся и ты с нами, друг! Быть может, в будущем мой народ вознаградит тебя по заслугам.', 'По просьбе Атаики убейте 12 налетчиков из племени Квалдир в Каскале.', 'Благодарю тебя, $N. Я у тебя в большом долгу – если мы, конечно, когда-нибудь выберемся отсюда живыми.', NULL, NULL, NULL, 'Квалдир-налетчик убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11950, 'Мудрость Муахита', 'Послушай, $N. Воинам вроде меня несложно найти замену. Если я паду, мои братья и родичи подхватят мое копье и продолжат сражаться.$B$BА вот без мудрых старейшин мой народ не проживет. Упрямый Муахит, наш самый почтенный шаман, отказывается покинуть алтарь Таютки на центральном острове. Мы понесем серьезную утрату, если его убьют эти чудовища.$B$BТы здесь $gчужестранец:чужестранка: – быть может, тебя он послушает? Объясни ему причины... уговори его уйти в безопасность Уну\'пе, пока еще не поздно.', 'Найдите в Каскале старейшину Муахита.', 'Тебя прислал Атаика, так ведь? Нет уж, меня не поколебать.$B$BЕще не все потеряно. Духи по-прежнему с нами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11951, 'Приманка', 'Находясь в плену, я сумела многое узнать о Малигосе. Теперь судьба распорядилась так, что я могу использовать это против него.$B$BВ небе над Нексусом кружит большой синий дракон, Сарагоса. Она одновременно страж аспекта и его супруга. Если возникает серьезная опасность, она предупреждает своего господина.$B$BВ плену я испытала немало страданий от руки Сарагосы, и вот настал ее черед умереть. Однако для начала нужно подготовить ловушку...', 'Соберите в Хладарре 10 осколков кристаллизованной маны по просьбе Керистразы.Если потеряете свою магическую клетку, поговорите с Релоразом у Маскировочного щита.', 'Спасибо тебе, $N.$B$BЗаточение измотало меня, и силы возвращаются ко мне очень медленно.$B$BЯ буду расходовать энергию этих кристаллов очень осторожно. Это побочный продукт коварных замыслов Малигоса. Но, если удача нам улыбнется, они же помогут нам победить его!', 'Ну что, все осколки маны собраны?', NULL, NULL, 'Осколок кристаллизованной маны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11952, 'Ответный удар', 'Мы должны действовать! Мы должны сохранить равновесие. Время работает против нас.$B$BГряда Огненной стражи в Тлеющем ущелье – известная позиция культа Сумеречного Молота. Недавно культ стал использовать Камни Льда для связи с царством Хозяина Приливов, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', 'Убейте лейтенанта Лютостужу, помощника Ахуна, вызвав его при помощи Камня Льда в пещере под горами Огненной стражи на северо-западе от Тлеющего ущелья, затем вернитесь к старейшине Служителей Земли в столицу.', 'Доброе дело. Оно может показаться малым, но даже это поможет великой битве. Прими это вместе с моим благословением, а потом возвращайся, ибо у меня найдется для тебя еще дело.', NULL, NULL, NULL, 'Лейтенант Лютостужа убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11953, 'Ответный удар', 'Мы должны действовать! Мы должны сохранить равновесие. Время работает против нас.$B$BСилитус – азеротская база культа Сумеречного Молота. Там на севере, они используют Камни Льда, чтобы связываться с царством Хозяина Приливов. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', 'Убейте лейтенанта Хладноглыба, помощника Ахуна, вызвав его при помощи Камня Льда в Сумеречной пещере в северном Силитусе, затем вернитесь к старейшине Служителей Земли в столицу.', 'Доброе дело. Оно может показаться малым, но даже это поможет великой битве. Прими это вместе с моим благословением, а потом возвращайся, ибо у меня найдется для тебя еще дело.', NULL, NULL, NULL, 'Лейтенант Хладноглыб убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11954, 'Ответный удар', 'Мы должны действовать! Мы должны сохранить равновесие. Время против нас.$B$BБлиз Темного портала на Дреноре возник мрачный культ, который хочет помочь Ахуну войти в наш мир. Они используют камни льда, чтобы обеспечить явление Повелителя Холода. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...', 'Убейте ледяного храмовника, помощника Ахуна, вызвав его при помощи камня льда к Темному порталу на полуострове Адского Пламени, затем вернитесь к старейшине Служителей Земли в столицу.', 'Доброе дело. Оно может показаться малым, но даже это поможет великой битве. Прими это вместе с моим благословением, а потом возвращайся, ибо у меня найдется для тебя еще дело.', 'Ты возвращаешься с победой?', NULL, NULL, 'Ледяной Храмовник убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11955, 'Ахун, Повелитель Холода', 'Надеюсь, тебе хватит сил на выполнение последнего задания.$B$BМы не можем позволить, чтобы заговор фанатиков из культа Сумеречного Молота и наг-отступников Нептулона осуществился. Во имя Азерота и всей жизни на нем мы должны действовать. Наша дорога ясна. Отправляйся в Узилище в недрах резервуара Кривого Клыка и встреться там с нашей шаманкой. Спеши!', 'Отправляйтесь в Узилище в резервуар Кривого Клыка, что в Зангартопи, и поговорите с Нумой Сестрой Облаков.', 'Хвала духам, ты пришел! Мы должны скорее призвать Ахуна, пока еще не поздно...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11956, 'Поиски талисмана', 'Для болтовни нет времени, $N. Меня послали сюда с самоубийственным заданием – занять зиккурат. Свой солдатский долг я выполнил, а теперь настала пора получить ответы на некоторые вопросы.$B$BЭтот лич обладает знанием, которого я ищу, но в то же время я не могу причинить боль его физическому телу, чтобы это знание заполучить.$B$BЛич поместил свою душу в талисман, и, пока он сокрыт, я не смогу вырвать из лича информацию.$B$BВозвращайся в лагерь и возьми моего коня, Сумрака. Он привезет тебя к талисману. Принеси мне его.', 'Отправляйтесь на Стоянку Смерти и скачите на Сумраке к месту, где находится талисман Танатала. Добудьте его и принесите Тассариану в Стонущий зиккурат.', 'Ты как раз вовремя, $N. Припереть к стенке лича – не так легко, как кажется...', 'Ты вернулся, $N. Тебе удалось добыть талисман?', NULL, NULL, 'Талисман Танатала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11957, 'Смерть Сарагосе!', 'Используя предоставленные тобой кристаллы маны, я изготовила это средоточие магии.$B$BСарагоса же обжора! Она не сможет устоять перед такой приманкой. А внутри приманки – магия, которая очень и очень ее ослабит. Будем надеяться, она не заметит мою хитрость...$B$BСоберись с духом, $N, и скажи мне, когда будешь $gготов:готова: встретиться лицом к лицу с Сарагосой.', 'По просьбе Керистразы используйте средоточие магии для привлечения внимания Сарагосы, а затем сразитесь с ней.', 'Этот мир стал немного лучше теперь, когда больше нет Сарагосы, но наша работа еще не завершена.$B$BПришло время нанести удар самому Малигосу!', 'Сарагоса не должна остаться в живых!', NULL, NULL, 'Труп Сарагосы', 'Средоточие тайной магии', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11958, 'Чтоб ничего не пропало!', 'Волчеры всегда были нашими естественными врагами. Но после того, как в Большой Драконий Погост вторгся ваш народ, они оказались заперты на тесном пятачке на севере.$B$BА после сегодняшнего колебания земли они совсем озверели. Они уже несколько раз совершали набеги на наши припасы... припасы, без которых нам не обойтись, если мы хотим пережить это путешествие!$B$BЕсли ты нам друг, отбери наше добро у волчеров Поляны Снегопада!', 'Отберите у волчеров 6 украденных припасов Моа\'ки. Верните их старейшине Ко\'нани в Гавани Моа\'ки.', 'Не могу сказать, что мне приятно донимать тебя подобными просьбами. Однако мы делаем все, чтобы как можно быстрее подготовиться к переселению – хотя куда мы переселяемся, мы еще и сами не ведаем.$B$BМои колдуны говорят мне, что ты здесь затем, чтобы спасти эти земли от Того, Кто Бродит во Мраке.$B$BНадеюсь, что ты спасешь не только земли, но и народы, живущие на них!', 'В последнее время природное равновесие то и дело нарушается!$B$BНадеюсь, ты сумеешь помочь нам пережить изменение нашего образа жизни!', NULL, NULL, 'Украденные припасы Моа\'ки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11959, 'Убить Логуна!', 'Дела идут все хуже и хуже. Остался один-единственный выход... к сожалению, это смерть Логуна!$B$BЭто вожак племени Поляны Снегопада, злобный волчер. Его смерть позволит нам хоть ненадолго прервать постоянные нападения волчеров и их грабительские набеги.$B$B\"Сокрушителя плоти\" ты найдешь перед его лачугой, на северном откосе поляны. Он крупнее остальных – не ошибешься. Убей его и измажься его кровью, чтобы продемонстрировать свое превосходство над волчерами и уважение к клыкаррам.', 'Намажьтесь кровью Логуна и возвращайтесь к старейшине Ко\'нани в гавань Моа\'ки.', 'Честное и достойное жертвоприношение Логуна, совершенное твоими руками, – это именно то, что нужно моим соплеменникам. Теперь мы извлечем выгоду из внутренних распрей среди волчеров за его место.$B$BЭтого должно быть достаточно.', 'Это на тебе кровь Логуна или твоя собственная, $R?', NULL, NULL, 'Кровь Логуна намазана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11960, 'Планы на будущее', 'Если мы хотим выжить, нам следует бороться с волчерами. Я только боюсь, как бы мы в своем рвении не истребили слишком многих.$B$BВолчеры Поляны Снегопада имеют такое же право на жизнь, как и мы сами. И мы с тобой позаботимся о том, чтобы они получили свой шанс.$B$BЕсли старейшина Ко\'нани не просил тебя с ними разобраться, значит, еще попросит. Когда будешь на севере, на их поляне, собери, пожалуйста, щенков и принеси их мне.', 'Соберите 12 щенков Поляны Снегопада. Принесите их зверолову Мау\'и в гавани Моа\'ки.', 'О, тебе удалось спасти многих! Спасибо тебе, $R.$B$BТеперь волчеры получат шанс выжить среди нас. Если, конечно, мы сами вообще выживем.$B$BКак думаешь, будет ли у тебя завтра время, чтобы спасти и других лохматиков?', 'Ну, сколько щенков можно было спасти за такое короткое время?', NULL, NULL, 'Щенок Поляны Снегопада', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11961, 'Духи присматривают за нами', 'Могущественные духи присматривают за моим кланом – Каскала не будет утрачена.$B$BИссилрук дарует нам смелость, Таютка обеспечит выживших едой и кровом, а Каркут присмотрит за павшими, чтобы они не потеряли свой путь.$B$BРуководство Иссилрука – то, что нам больше всего нужно прямо сейчас. Я просил своего племянника, Ирука, принести мне тотем Иссилрука, но квалдирские копья сразили его, и его тело скатилось в воды к северу отсюда. Принеси мне этот тотем, $N. Пусть смерть моего племянника не будет напрасной.', 'Найдите тело Ирука в воде, заберите тотем Иссилрука и принесите старейшине Муахиту в бухту Дыхания Ньорда.', 'Ты чувствуешь присутствие Иссилрука, $N? Он не хочет, чтобы его дети были погублены руками странников тумана!', 'Тотем, $C – он уже у тебя?', NULL, NULL, 'Тотем Иссилрука', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11962, 'Последняя партия', 'Значит, так. С последней партией руды, которую тебе удалось спасти, у нас выходит достаточно, чтобы отправить груз в крепость Отваги.$B$BЕсли Далечье окажется стерто с лица Азерота, по крайней мере, нас запомнят как тех, кто первым встал на защиту родной земли и кто сдался последним.$B$BДоставь эту руду Хильде Каменной Кузне – это мой хороший друг. Скажи ей, пусть изготовит из нее доброе оружие. Оно нам еще очень и очень понадобится!', 'Доставьте ящик руды из Далечья Хильде Каменной Кузне в крепость Отваги.', 'Руда из Далечья? Что-то рановато… Что-нибудь случилось?', 'Что это у тебя?', NULL, NULL, 'Ящик руды из Далечья (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11963, 'Оружие для Далечья', 'Далечье вот-вот будет захвачено, а Джеральд не может придумать ничего умнее, кроме как отправить мне очередную партию руды? Этот человек так же бессердечен, как и все солдаты!$B$BМы не можем допустить, чтобы мирные жители теряли свои земли, иначе они не захотят сражаться, когда придет нужда! Правда, мы не можем отправить подкрепление, зато у нас есть для них оружие!$B$BПравда, оно предназначалось для новобранцев, но я успею сделать новое из привезенной тобой руды. Передай Джеральду, что оружие вот-вот будет!', 'Вернитесь к Джеральду Грину в Далечье.', 'Хильда пришлет нам оружие? Это отличная новость, $N! А то я уже собирался приказать парням собирать вещички…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11964, 'Благовония для летних пламеней', 'Известно ли тебе, что наши праздничные костры горят во всех краях, где есть поселения Альянса? Их поддерживают стражи Пламени в лагерях близ каждого городка, чтобы огонь горел ярко до конца праздника.$B$BПри каждом страже Пламени есть летний пламень - посланец духов стихии Огня.$B$BНе хочешь ли выказать почтение пламеню, $N? Возьми эти благовония и преподнеси любому летнему пламеню. Ублажи маленького духа огня, и он, возможно, отблагодарит тебя.', 'Хранитель мудрости Праздника хочет, чтобы вы отнесли благовония Лета летнему пламеню к любому поселению Альянса.', 'О, что это? Какое благоухание! Уверен, это расцветет чистейшим и ярчайшим пламенем!$B$BПрими этот цветок, $N. Прими, и покинь меня... Хочу насладиться этим благоуханным пламенем...', 'Пламенный привет тебе, почтенный $C. Добро пожаловать на священную землю праздника Огненного солнцеворота.', NULL, NULL, 'Благовония лета (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11965, 'К оружию!', 'У Далечья появился шанс побороться, $N. Это все, о чем мы просили, и благодаря тебе это стало возможным.$B$BВсе, что нам еще нужно теперь – это сборный пункт. Я скажу своим людям отнести оружие в ратушу. И ты иди туда же и звони в колокол, чтобы собрать всех выживших.$B$BНастало время показать Плети, из какого теста мы сделаны.', 'Войдите в здание ратуши в Далечье и позвоните в колокол, находящийся в этом здании.', 'Еще раз спасибо за помощь, $N. Жители Далечья всегда будут помнить о тебе.', NULL, NULL, NULL, 'Колокол Далечья прозвонил', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11966, 'Благовония для праздничных сполохов', 'Известно ли тебе, что наши праздничные костры горят во всех краях, где есть поселения Орды? Их поддерживают стражи Пламени в лагерях близ каждого городка, чтобы огонь горел ярко до конца праздника.$B$BПри каждом страже Пламени есть праздничный пламень - посланец духов стихии Огня.$B$BНе хочешь ли выказать почтение Сполоху, $N? Возьми эти благовония и преподнеси любому праздничному пламеню. Ублажи маленького духа огня, и он, возможно, отблагодарит тебя.', 'Праздничный сказитель хочет, чтобы вы отнесли благовония Лета праздничному сполоху к любому поселению Орды.', 'О, что это? Какое благоухание! Уверен, это расцветет чистейшим и ярчайшим пламенем!$B$BПрими этот цветок, $N. Прими, и покинь меня... Хочу насладиться этим благоуханным пламенем...', 'Пламенный привет тебе, почтенный $C. Добро пожаловать на священную землю праздника Огненного солнцеворота.', NULL, NULL, 'Благовония лета (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11967, 'Сбор красных драконов', 'Малигос явно заметил, что что-то не так.$B$BЯ его знаю. Он не умеет думать о нескольких вещах за раз. Я наверняка сумею выманить его из безопасного логова, когда он узнает, что стало с его ненаглядной Сарагосой.$B$BОтведи меня к Релоразу, $N, и немедленно! Пусть поднимает своих драконов на бой с Малигосом!', 'Отведите Керистразу к Релоразу к Маскировочному щиту.', 'Да, до меня уже доходили слухи о спасении Керистразы. Ты заслуживаешь уважения.$B$BМне нужно срочно поговорить с ней!', 'У тебя есть вести для меня, $N?', NULL, NULL, 'Усиленная магическая клетка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11968, 'Поворот колеса Фортуны', 'Духи услышали наш крик о помощи, $N. Это знак, что Каскалу еще можно спасти.$B$BВоспользуйся неразберихой, которую внесли капризы погоды, и убей квалдирского вожака. Твои действия склонят чашу весов на нашу пользу, я уверен.', 'По просьбе старейшины Муахита убейте Хейгарра Душегуба в бухте Дыхания Ньорда.', 'Ты оказал нам большую услугу, $R. Битва еще не выиграна, но теперь у моего народа есть шанс.', NULL, NULL, NULL, 'Хейгарр Душегуб убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11969, 'Сработавший капкан', 'Мы добились этого во многом благодаря твоим усилиям, $N.$B$BБудет справедливо, если именно ты возглавишь атаку на Малигоса!$B$BВозьми этот сигнальный огонь и запали его у северо-западного входа в Нексус. К тебе присоединится Керистраза.', 'Используйте сигнальный огонь Релораза у северо-западного входа в Нексус по просьбе Релораза.', 'Мы нанесли Малигосу серьезный удар, но это далось нам дорогой ценой.', 'Удалось ли тебе встретиться с Керистразой?', NULL, NULL, 'Малигоса удалось выманить', 'Сигнальный огонь Релораза', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11970, 'Хранитель мудрости праздника Середины Лета', 'Нынешний праздник – время смеха и забав. Но важно не забывать о его происхождении. Найди же того, кто поделится с тобой этим знанием, и насладись древними преданиями.$B$BВ этом тебе поможет Хранитель мудрости Праздника в любой из столиц Альянса. Ступай же.', 'Поговорите с Хранителем мудрости Празднества в любой из столиц Альянса.', 'С радостью поведаю тебе все, что знаю.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11971, 'Сказитель Летнего праздника', 'Нынешний праздник – время смеха и забав. Но важно не забывать о его происхождении. Найди же того, кто поделится с тобой этим знанием, и насладись древними преданиями.$B$BВ этом тебе поможет Праздничный сказитель в любой из столиц Орды. Ступай же.', 'Поговорите с праздничным сказителем в любой из столиц Орды.', 'С радостью поведаю тебе все, что знаю.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11972, 'Осколки Ахуна', 'Эти осколки пульсируют, испуская какую-то недобрую энергию. Не сохранилось ли в них остатков сущности Повелителя Холода?', 'Принесите ледяные осколки Луме Матери Небес.', 'Да, в этих осколках сохранился остаток сущности Повелителя Холода. Мы уничтожим их и изгоним Ахуна в ледяную Пустоту.$B$BСпасибо тебе, $N. Имя твое навеки останется в песнях Служителей Земли. Прошу тебя - окажи нам честь и прими этот скромный дар, знак твоего родства с теплом и светом.', 'Приветствую, $N. Вид у тебя встревоженный - но возрадуйся! Повелитель Холода побежден!', NULL, NULL, 'Осколки Ахуна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11973, 'Пленница', 'Малигос забрал Керистразу и заставляет ее стать его супругой?! Немыслимо!$B$BОна никогда не согласится на это, но Малигос – могучий аспект. Рано или поздно он сломит ее волю.$B$B$N, нельзя этого допустить. Я не позволю ей страдать, испытывая такое унижение.$B$BТы $gдолжен:должна: войти в Нексус и сделать все, чтобы избавить ее от этой ужасной судьбы.', 'По просьбе Релораза из лагеря под Маскировочным щитом отправьтесь в Нексус и освободите Керистразу.', 'Так, значит, все кончено…$B$BМы никогда не забудем самопожертвования, совершенного Керистразой. И никогда не забудем роль, которую довелось сыграть тебе, $N.$B$BПусть это трагическое событие послужит дальнейшему укреплению нашей решимости противостоять угрозе, с которой мы столкнулись.$B$BОт имени красных драконов прими этот дар как знак нашей благодарности.', 'Ты нашел Керистразу? Удалось ли тебе освободить ее от ее уз?', NULL, NULL, 'Керистраза упокоена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11975, 'Когда я вырасту...', 'Может, я уже спрашивала, но когда тебе было столько же лет, сколько мне, ты уже $gзнал:знала:, что будешь |3-4($C), когда вырастешь?$B$BА я не знаю, кем хочу быть. Может, магом или чернокнижницей, или рыцарем крови, как я уже говорила. Или... рок-звездой! Как Сиг Шивес, эльф крови из группы \"Вожди тауренов\"!$B$BЯ слышала, что когда они не ездят с гастролями, они находятся в Луносвете! Они сидят на балконе на Пути Старейшин и ждут, когда возле них остановятся. $B$BОчень прошу, отвези меня туда, ну, пожалуйста!', 'Отведите свою подопечную, сиротку Саландрию, посмотреть на группу \"Вожди тауренов\" в Луносвет на Путь Старейшин. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11976, 'Ледяные осколки', 'Эти осколки пульсируют, испуская какую-то недобрую энергию. Не сохранилось ли в них остатков сущности Повелителя Холода?', 'Принесите ледяные осколки Луме Матери Небес. Награда: Гербовая накидка летних небес и Пылающий цвет.', '', NULL, NULL, NULL, 'Осколки Ахуна (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11977, 'Таурен среди таунка', '<Вартук указывает на северо-восток.>$B$BОна очень добра, знаешь ли. Если бы не твое посольство, у оставшихся в живых беженцев могло вовсе не остаться никакой надежды. В то время как она, конечно, не таунка по рождению, племя избрало ее старейшиной деревни пожизненно.$B$BЕсли ты действительно $gтот:та:, за кого я тебя принимаю – пожалуйста, пойди нанеси визит эмиссару Светлое Копыто в лагере беженцев. Она тебя давно ждет.', 'Поищите эмиссара Светлое Копыто в лагере беженцев Западного Ветра.', 'То, что ты видишь, – это все, что осталось от таунка Борейской тундры и Драконьего Погоста. Это сломленный народ… измученный Плетью и поставленный ею же на грань уничтожения.$B$B<Светлое Копыто печально качает головой.>$B$BТолько Орда может теперь их спасти. Только Орда может поднять их сломленный дух. Мы будем заботиться о них, чтобы помочь им выздороветь, а они, в свою очередь, усилят позиции Орды в Нордсколе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11978, 'Добро пожаловать в Орду', 'Прежде чем мы сможем официально принять этих таунка в лоно Орды, мы должны отбить наше вооружение у нерубов-воинов Ануб\'ара, которые заполонили окрестные леса. Это вооружение было утеряно, когда на караван из Молота Агмара напали прошлой ночью силы Плети.$B$BОтправляйся в лес к востоку от лагеря беженцев Западного Ветра и верни вооружение, $r.', 'По просьбе эмиссара Светлое Копыто из лагеря беженцев Западного Ветра на Драконьем Погосте добудьте 10 ящиков с ордынским оружием.', 'Это как раз то, что надо, Профессия! Великолепное вооружение Орды поднимет их дух и даст им необходимую защиту от армии Плети.$B$BТы готов к церемонии инициации?$B$B<Светлое Копыто кивает.>$B$BДа, именно ты введешь в лоно Орды наших новых союзников.', 'Без доспехов и оружия наши новообретенные союзники будут беззащитны на своем пути в Молот Агмара.', NULL, NULL, 'Ордынское оружие', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11979, 'Таунка и таурены', 'Плеть захватила столицу таунка, деревню Ледяной Пыли! Всех выживших таунка держат пока в лагере беженцев Западного Ветра на западной границе Драконьего Погоста.$B$BЛорд Адский Крик считает, что, чтобы выжить, таунка необходимо примкнуть к Орде. Поэтому он отправил в лагерь Западного Ветра посланника-таурена, чтобы укрепить нашу дружбу с северными тауренами. Отправляйся в лагерь беженцев Западного Ветра и отыщи эмиссара Светлое Копыто. Ей понадобится твоя помощь.', 'Отыщите эмиссара Светлое Копыто в лагере беженцев Западного Ветра.', 'То, что ты видишь, – это все, что осталось от таунка Борейской тундры и Драконьего Погоста. Это сломленный народ… измученный Плетью и поставленный ею же на грань уничтожения.$B$B<Светлое Копыто печально качает головой.>$B$BТолько Орда может теперь их спасти. Только Орда может поднять их сломленный дух. Мы будем заботиться о них, чтобы помочь им выздороветь, а они, в свою очередь, усилят позиции Орды в Нордсколе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11980, 'Гордость Орды', 'Я был одним из стражей, сопровождавших караван с оружием, который шел в этот лагерь. На нас напали, стремительно и внезапно. Мы сражались и перебили десятки этих тварей, но их было слишком много. Нам с Тор\'зином еле удалось уйти живыми.$B$BКонечно, если бы не раны, мы бы сейчас сами бродили по лесам, выслеживая этих демонов. Поможешь ли ты нам восстановить нашу поруганную гордость? Обыщи леса к востоку отсюда, найди нерубов-воинов Ануб\'ара и убей их! Во имя Орды!', 'Убейте 15 ануб\'арских душителей по просьбе кровавого стража Рох\'килла из лагеря беженцев Западного Ветра в Драконьем Погосте.', '<Рох\'килл отдает вам честь.>$B$BТы спас нас от позора, $N!Мы с Тор\'зином благодарим тебя за самоотверженность!', NULL, NULL, NULL, 'Ануб\'арский душитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11981, 'Найди Куруна!', 'Каменная поверхность земельника-воина покрыта трещинами и впадинами. Хотя он не может истекать кровью, вы чувствуете, что великан находится при смерти.$B$BТихий, едва различимый голос срывается с губ умирающего.$B$B\"Найди... Куруна... ты $gдолжен:должна: найти... Куруна.\"$B$BВ ответ на ваши попытки выяснить, кто такой Курун, он беспомощно смотрит на вас из-под полуопущенных век.$B$B\"Наш... предводитель... он стоит на... холме, с которого виден весь Тор Модан... командует нашей армией. Прошу... скажи ему... мы не сможем взять... город... \"', 'Поговорите с Куруном, который стоит на холме, возвышающимся над Тор Моданом.', '<Вы передаете Куруну слова павшего земельника.>$B$BОни сражались храбро, но мой воин прав – одним нам не одолеть железных дворфов Тор Модана. Мои великаны и Воины земли уже давно сражаются со злом, но столь немногочисленное войско не сможет выиграть битву за Тор Модан. Можем ли мы рассчитывать на твою помощь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11982, 'Каменный дождь', 'Прямо под нами находится древняя крепость железных дворфов, Тор Модан. Тысячи лет назад каменные великаны вызвали землетрясение, обрушившее большую часть города в огро$Nю пропасть и стеревшее с лица земли то, что от него осталось.$B$BНо железные дворфы никогда не прекращали попыток отвоевать древнюю столицу. Мы не можем этого допустить! Мои гиганты засыпят пропасть щебнем и камнями вместе с работающими железными дворфами. Возможно, тогда нам удастся избавиться от них навсегда. Тебя же я попрошу помочь нам в этом деле, скинув в пропасть на северо-востоке как можно больше булыжников.', 'Курун, стоящий на холме, рядом с Тор Моданом, просит вас помешать железным дворфам, сбросив в котлован Тор Модана несколько булыжников.', 'Увы, железные дворфы успевают разгребать завалы. Похоже, одной атакой сверху нам не обойтись. Ты должен помочь моим братьям сражаться с противником в самом городе.', 'Какие успехи?', NULL, NULL, 'Операция железных дворфов сорвана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11983, 'Клятва крови Орды', 'Они готовы, $N. Эти таунка добровольно вольются в Орду и отдадут все, что у них есть, чтобы выдворить армию Плети из этого мира.$B$B<Светлое Копыто передает вам свиток, на котором – знак Орды.>$B$BНа этом свитке запечатлена клятва крови Орде. Традиция предписывает нашим новым братьям и сестрам из народа таунка произнести вместе священные слова клятвы.$B$BВозьми этот свиток и прими клятву таунка Орде, командор. Верни мне свиток, когда выполнишь эту почетную обязанность.', 'Поговорите с таунка в лагере беженцев Западного Ветра и примите у пятерых из них клятву верности Орде.Верните клятву крови Орды эмиссару Светлое Копыто, когда выполните задание.', 'Спасибо за это, командор $N. У них ведь ничего не осталось. А ты дал им цель, а с осознанием цели приходит надежда... Надежда на новое завтра... на новую жизнь.', 'Они усилят Орду, командор.', NULL, NULL, 'Таунка введены в Орду', 'Клятва крови Орды (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11984, 'Захлопнуть клетку', 'Эх, старина Бадд уже отжил свой век.$B$BС тех пор, как мы перебрались сюда из Призрачных земель, он просто висит у нас камнем на шее. А мы тут, между прочим, пытаемся как-то наладить жизнь! В смысле, продаем пленных троллей тому, кто больше заплатит.$B$BК счастью, для Бадда тоже нашлась работенка. В его состоянии легко втереться в доверие к троллям, так что мы обучили его кое-каким прибыльным трюкам.$B$BДа лучше $gсамому:самой: увидеть, чем сто раз услышать. Поговори с Баддом и отведи его на юго-запад к Руинам Драк\'Зина. После этого тебе останется только захлопнуть дверцу клетки за пойманным троллем!', 'Самир из Гранитных ключей просит вас запереть в клетку охотника оглушенного Баддом ледяного тролля.', 'Ай, молодчина, $С. Пожалуй, старина Бадд нам еще пригодится.$B$BСейчас я распоряжусь насчет клетки с троллем и выдам тебе твою часть награды.$B$BКстати, я же еще не поприветствовал тебя в нашем лагере! Не убегай далеко – тут для тебя всегда найдется работа...', 'Ну что, вы с Баддом поймали ледяного тролля?', NULL, NULL, 'Пойман живой ледяной тролль', 'Клетка охотника за головами', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11985, 'Битва в Проломе', 'Если мы не сможем подорвать оборону Тор Модана, то наша осада ни к чему не приведет. Дети земли отважно сражаются с големами, созданными сынами железа, но им не под силу проникнуть в город.$B$BВедущие туда тоннели слишком узки, и мои братья-великаны не могут ими воспользоваться. Но тебе под силу пробраться в самое сердце укреплений железных дворфов и убить их предводителя!', 'Курун, стоящий на холме, возвышающемся над Тор Моданом, просит вас убить железного тана Аргрума.', 'Молодец, $N. Надеюсь, гибель предводителя железных дворфов станет последней каплей, сокрушившей их сопротивление. Оставшимися ренегатами займутся мои братья.', 'Предводитель железных дворфов мертв?', NULL, NULL, 'Железный тан Аргрум убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11986, 'Потрепанный дневник', 'Этот потрепанный, запятнанный дневник знавал лучшие времена. Листая его, вы находите множество карт, диаграмм и других заметок.$B$BПочерк кажется смутно знакомым, но только обнаружив в конце одной из записей подпись Бранна Бронзоборода, вы понимаете, кому он принадлежит.$B$BВторая половина книги, содержащая самые последние записи, была грубо вырвана. Поле битвы усеяно разделенными страницами – чтобы узнать, что выяснил Бранн, придется собрать их в исходном порядке.', 'Разыщите 8 недостающих страниц, вклейте их в дневник и принесите его Тортену Глубокопу в Лагерь дружины Западного Края.', 'Ты нашел дневник Бранна? Невероятно! От него уже долгое время не было вестей, и мы начали беспокоиться, что с ним что-то случилось. Так что он обнаружил в Тор Модане?', 'Что ты мне принес?', NULL, NULL, 'Потерянный дневник Бранна Бронзоборода', 'Неполный дневник', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11988, 'Рунический краеугольный камень', 'В своем дневнике Бранн упомянул некий рунический краеугольный камень, с помощью которого можно перевести самые важные руны на найденной им табличке. Без этого камня мы не сможем понять ни единой надписи.$B$BВ самом конце дневника сказано, что камень был похищен железными дворфами-защитниками, которые поделили его части между собой. Мы должны собрать эти фрагменты, чтобы расшифровать табличку! Увы, Бранн не смог описать похитителей. А это значит, что куски камня могут оказаться у любого дворфа в Тор Модане.', 'Принесите 5 фрагментов рунического краеугольного камня Тортену Глубокопу в Лагерь дружины Западного Края.', '<Тортен спешно соединяет фрагменты камня.>$B$BНескольких кусочков не хватает, но этого достаточно, чтобы расшифровать большую часть надписей.', 'Ты собрал все обломки краеугольного камня?', NULL, NULL, 'Фрагмент рунического краеугольного камня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11989, 'Перемирие?', 'Осторожнее, $gдружище:подруга:.$B$BТы не представляешь, сколько таких хорошеньких голов полегло под топором Дракуру – я до стольки даже считать не умею. Повезло тебе, что я сижу в клетке – а то в моем списке стало бы на одну жертву больше.$B$BНо, возможно, на этот раз мы сможем что-нибудь придумать!$B$BДракуру знает много всего на свете, и кое-что из этого могло бы тебе помочь. $B$B<Дракуру царапает ладонь об один из своих клыков и протягивает вам руку меж прутьев клетки.>$B$BЧто скажешь? Заключим перемирие?', 'Дракуру из Гранитных ключей просит вас скрепить перемирие кровью, поцарапав свою руку тупым резаком, лежащим возле его клетки.', 'Отлично!$B$BОтныне ты мой брат по крови. Такую связь разорвать невозможно.$B$BА теперь слушай и запоминай, что тебе скажет Дракуру, $R. Нам предстоит многое совершить.', 'Ты сделал правильный выбор, дружище. Надеюсь, тебе не придется об этом пожалеть...', NULL, NULL, 'Заключен договор с Дракуру', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11990, 'Пузырек видений', 'Не будем торопиться, дружок. Сначала нам надо подготовиться. $B$BКто знает, как долго я смогу здесь оставаться. Поэтому, чтобы мы с тобой смогли общаться и дальше, тебе придется добыть очень мощный эликсир.$B$BК счастью, я знаю, что может нам помочь! И все его компоненты буквально лежат под рукой. $B$BМне нужна склянка одного из этих маленьких, миленьких троллей, которые тут стоят, немного водорослей из северного пруда и немного туманнолистника.$B$BТолько поторопись, пока они меня не утащили.', 'Дракуру из Гранитных ключей просит вас принести ему укрепленную колбу, сплетение водорослей и три листа туманнолистника.', '<Дракуру берет у вас ингредиенты и смешивает их в пузырьке.>$B$BВот так, дружище. А теперь – за работу!', 'Все принес, дружище ?', NULL, NULL, 'Укрепленная колба', 'Туманолистник', 'Сплетение водорослей', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11991, 'Требуется расшифровка', 'Говорят, что когда-то для укрепления Крепости Драк\'Тарон были созданы могущественные артефакты, но они были утеряны много веков назад.$B$BМногие считают, что это просто легенда, но Дракуру знает правду!$B$BЯ был близок к тому, чтобы обнаружить первый артефакт, но меня захватили в тот самый момент, когда я расшифровывал важные иероглифы, могущие привести нас к истине. Отправляйся на юго-запад, к жаровне в руинах Драк\'Зина и воспользуйся моим эликсиром, чтобы я смог закончить работу. $B$BУвы и ах, чтобы призвать меня туда, тебе придется смешать эликсир с застывшим настоем, который есть только у моих братьев. Мне больно думать о том, что ради этого тебе придется убивать моих родственничков, но наша цель оправдывает средства.', 'Дракуру просит вас добыть 5 застывших настоев у Драккари, обитающих среди Руин Драк\'Зина, и затем выпить эликсир возле жаровни Дракуру.', 'Ай, молодец, дружище!$B$BОтсюда мне прекрасно видно надписи на стенах...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11993, 'Рунические пророчества', 'Нельзя терять ни минуты! Теперь, когда рунический краеугольный камень практически собран, мы можем перевести те самые рунические таблички, над которыми работал Бранн до побега.$B$BК сожалению, нам неизвестно, какую часть информации ему удалось получить, так что будем предполагать, что он узнал достаточно для того, чтобы определить свой следующий шаг.$B$BПодойди к каждой табличке и воспользуйся руническим краеугольным камнем. Помни – Бранн может надеяться только на нас!', 'Тортен Глубокоп из Лагеря дружины Западного Края просит вас расшифровать три рунических диска.', '<Tортен внимательно слушает ваш пересказ того, что написано на табличках.>$B$BМолот Мадорана, он обнаружил новый город $Nв!$B$B\"Колыбель камня и железа...\"$B$B\"Ульдуар в центре бури.\"$B$BЧто бы это значило? Неужели, после стольких лет поисков мы найдем, наконец-то, священный источник, давший жизнь нашей расе?$B$BНадо идти за ним! Мы должны его найти!', NULL, NULL, NULL, 'Первое пророчество расшифровано', 'Второе пророчество расшифровано', 'Третье пророчество расшифровано', 'Рунический краеугольный камень');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11995, 'Безотлагательное путешествие в Покой Звезд', '$C, я знаю, эти клыкарры будут просить тебя о том и о сем, но тебе нужно поспешить в Покой Звезд.$B$BПертурбации, произошедшие этим утром, бесспорно, будут иметь куда больший резонанс, чем просто неудобство для местных жителей.$B$BПокой Звезд находится к западу отсюда, за перекрестком с дорогой, ведущей к северу из гавани. Верховный маг Модера будет ждать тебя там.', 'Поговорите с проекцией верховного мага Модеры в Покое Звезд.', 'Я ждала тебя, $C. У нас с тобой много дел...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11996, 'Безотлагательное путешествие в Молот Агмара', '$C, я знаю, эти клыкарры будут просить тебя о том и о сем, но тебе нужно поспешить в Молот Агмара.$B$BПертурбации, произошедшие этим утром, бесспорно, будут иметь куда больший резонанс, чем просто неудобство для местных жителей.$B$BМолот Агмара находится к западу отсюда, за перекрестком с дорогой, ведущей к северу из гавани. Там тебя будет ждать сам верховный маг Этас Похититель Солнца!', 'Поговорите с проекцией верховного мага Этаса Похитителя Солнца в Молоте Агмара.', 'Почему так долго? Время останавливается лишь для Аспектов, $R.$B$BУ нас с тобой полно дел.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11997, 'REUSE', 'Мы отправили дружинников Западного Края на северо-восток Седых холмов, чтобы они обеспечили безопасный проход для наших отрядов. Они разбили лагерь на северо-востоке от Седой Пасти, к юго-западу от Тор Модана.$B$BНадеюсь, ты помнишь капитана Гриана Камнегрива, почетного ветерана Лордеронской войны с Плетью? Он больше известен обитателям Западного Края за свое решение покинуть поле битвы и вернуться домой, чтобы выступить против Братства Справедливости.', 'Поговорите с капитаном Грианом Камнегривом в Лагере дружины Западного Края.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11998, 'Подсластить пилюлю', 'Я обнаружил самый быстрый способ перебросить наши войска на Ледник Ледяной Короны – через сеть туннелей, пролегающей под древним городом железных дворфов, Тор Моданом.$B$BБругар Гравировщик и его ребята из Лиги Исследователей, конечно, не обрадуются такому решению, но приказа не ослушаются.$B$BВпрочем, мы могли бы подсластить им пилюлю, прислав бочку самогона Полнолуния. Его продает Хью Гласс в Торговой лавке Красного леса. Этот магазин находится на юго-востоке отсюда, если идти вдоль просеки.$B$BОн, правда, слегка чокнутый – но зато у него самый ядреный самогон во всей долине!', 'Принесите Бругару Гравировщику из Лагеря дружины Западного Края бочку старого доброго самогона.', 'Ну-ка, ну-ка... С чего бы это незнакомому $R приносить мне бочку самого лучшего самогона в этом паршивом лесу? Признавайся, чего тебе надо?', 'Это что там у тебя такое?', NULL, NULL, 'Старый добрый самогон', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (11999, 'Обшарить трупы', 'Сады Лунного Покоя на юго-западе были местом последнего упокоения нескольких высокорожденных эльфов. Там находился и узел силовых линий.$B$BСиние драконы применили магическое устройство, которое они называют волноловами, чтобы уничтожить этот узел и высвободить энергию, перенаправив ее по своему усмотрению.$B$BМне нужны дополнительные сведения, и ты их мне добудешь!$B$BПосле того как эти земли были разорены, призраки высокорожденных восстали и уничтожили половину здешних охотников на магов. Обыщи их тела, чтобы добыть сведения.', 'Найдите планы в Садах Лунного Покоя и вернитесь с ними к проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара.', 'Любопытно. Они хотят заключить договор с Эфириумом? Эфириалы могут оказаться могущественными союзниками для Малигоса с его безумными замыслами…$B$BЭтого нельзя допустить!', 'Ты снова здесь. Что тебе удалось узнать?', NULL, NULL, 'Планы из Садов Лунного Покоя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12000, 'Обшарить трупы', 'Сады Лунного Покоя на юго-западе были местом последнего упокоения нескольких высокорожденных эльфов. Там находился и узел силовых линий.$B$BСиние драконы применили магическое устройство, которое они называют волноловами, чтобы уничтожить этот узел и высвободить энергию, перенаправив ее по своему усмотрению.$B$BМне нужны дополнительные сведения, и ты их мне добудешь!$B$BПосле того как эти земли были разорены, призраки высокорожденных восстали и уничтожили половину здешних охотников на магов. Обыщи их тела, чтобы добыть сведения.', 'Найдите планы в Садах Лунного Покоя и вернитесь с ними к проекции верховного мага Модеры в Покое Звезд.', 'Любопытно. Они хотят заключить договор с Эфириумом? Эфириалы могут оказаться могущественными союзниками для Малигоса с его безумными замыслами…$B$BЭтого нельзя допустить!', 'Ты снова здесь. Что тебе удалось узнать?', NULL, NULL, 'Планы из Садов Лунного Покоя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12002, 'Братья по оружию', 'Надеюсь, Гриан понимает, почему я отозвал своих людей из Тор Модана после начала сражения. Невозможно работать, когда над головой взрываются снаряды!$B$BСлушай, ты с виду не робкого десятка, да и Камнегрив тебе доверяет.$B$BОтправляйся в Тор Модан, что на северо-востоке отсюда, и помоги нашим братьям одолеть этих проклятых железных дворфов. А я тем временем составлю план поисков.', 'Убейте 10 рунических боевых големов и вернитесь к Бругару Гравировщику в Лагерь дружины Западного Края.', '<Бругар слушает ваш доклад.>$B$BПохоже, что битва слегка утихла. Можно начинать поиски туннелей, которые используют железные дворфы.', NULL, NULL, NULL, 'Рунический боевой голем убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12003, 'В поисках туннелей', 'На месте железных дворфов я бы спрятал вход в подземные туннели в одном из зданий, окружающих Тор Модан. Именно с них мы и начнем наши поиски.$B$BПравда, надо быть осторожным, осматривая эти постройки – я заметил, что именно там укрылись выжившие железные дворфы-защитники.$B$BСкорее всего, вход в туннели будет с обратной стороны здания. Не знаю уж, что там надеется найти Камнегрив, но железные дворфы вряд ли станут помогать нам в поисках.', 'Бругар Гравировщик из Лагеря дружины Западного Края просит вас осмотреть северное, восточное и южное строения в Тор Модане.', '<Бругар громко и нецензурно ругается на дворфийском языке.>$B$BВходов нет? Ни одного?$B$BНу, нам вряд ли стоило рассчитывать на быстрый успех. Видимо, придется начинать поиски в самом городе. Неужели мои люди так и не смогут нормально поработать?', NULL, NULL, NULL, 'Осмотрено северное строение', 'Осмотрено восточное строение', 'Осмотрено южное строение', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12004, 'Предотвратить союз', 'Нам тут нужно убить двух птиц одним выстрелом, $C. И выстрелом этим будешь ты.$B$BНаши две птички – торговец Ветром Му\'фа и Горамош. Они должны быть где-то в западной части Садов Лунного Покоя. Скорее всего, они в большом двухэтажном здании, наблюдают за провалом.$B$BНадеюсь, ты не откажешь мне в любезности продемонстрировать доказательства их смерти.', 'Принесите проекции верховного мага Модеры в Покой Звезд останки торговца Ветром Му\'фа и чешую Горамоша.', 'К сожалению, Горамош подтвердил, что соглашение уже было достигнуто.$B$BТем не менее двумя мелкими поводами для беспокойства меньше. Давай-ка займемся более важными делами.', 'Тебе удалось воспрепятствовать объединению усилий синих драконов и Эфириума?', NULL, NULL, 'Останки Му\'фы Торговца Ветром', 'Чешуя Горамоша', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12005, 'Предотвратить союз', '$C, сейчас нам нужно убить одним выстрелом сразу двух зайцев. И этим выстрелом будешь ты!$B$BА зайцами будут Му\'фа Торговец Ветром и Горамош. Они должны быть где-то здесь, в западной части садов Лунного Покоя. Скорее всего, они в большом двухэтажном здании, которое стоит над обрывом.$B$BИ, будь так $gлюбезен:любезна:, принеси мне доказательства их смерти!', 'Доставьте останки Му\'фы Торговца Ветром и чешую Горамоша к проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара.', 'Отлично, $C, положи их пока на землю перед троном Агмара.$B$B<На лице изображения проступает тень улыбки.>$B$BУвы, судя по Горамошу, союз уже заключен...$B$BНо, по крайней мере, эти два змея больше нас не побеспокоят. Займемся более важными делами!', 'Удалось ли тебе предотвратить заключение договора между синими драконами и Эфириумом?', NULL, NULL, 'Останки Му\'фы Торговца Ветром', 'Чешуя Горамоша', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12006, 'Месть за бесчинства!', 'Эти так называемые охотники на магов явились сюда и уничтожили наше место отдыха.$B$BОтомсти за нас, или я позабочусь о том, чтобы вашу операционную базу заполонили духи умерших!', 'Убейте охотников на магов с Драконьего Погоста, ловчих из Садов Лунного Покоя, колдунов Волноловов и волшебников средоточия, общим числом 15, после чего возвращайтесь к Этениалу Тени Луны в Сады Лунного Покоя.', 'Очень хорошо, ты выполнил мою просьбу. $B$BСпасибо тебе, $R.', 'Каким-то образом я чувствую, что ты еще не убил достаточное количество этих осквернителей!', NULL, NULL, 'Убито сил синих драконов у Садов Лунного Покоя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12007, 'Необходимые жертвы', 'Я все понял, $gдружище:подруга:!$B$BНа севере, на зиккурате в Зеб\'Халак стоит каменная голова с рубиновыми глазами. Один из этих рубинов – Око пророка! Отнеси его к моей жаровне и выпей эликсир.$B$BИ снова для этого тебе понадобится настой – на этот раз вождя Зим\'бо. Он прячется в одной из хижин Зеб\'Халака.$B$BЖаль будет убивать Зим\'бо, но он поклялся защищать Драк\'Тарон до последней капли крови – и не сдержал обещание. Теперь он сможет послужить нам, отдав свой настой во имя благого дела.', 'Дракуру просит принести ему Око пророка к жаровне в Зеб\'Халаке.Чтобы эликсир Дракуру сработал на пьедестале, вам придется добыть настой Зим\'бо.', 'Это оно!$B$BЕще лучше, чем я надеялся! Вот она, последняя надежда человечества в эти темные времена.$B$BНе будем тратить время зря. Давай-ка найдем следующий артефакт!', 'Ты добыл Око пророка, дружище ?', NULL, NULL, 'Око пророка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12008, 'Молот Агмара', 'К востоку от нашего лагеря, совсем рядом, находится Молот Агмара – главное укрепление Орды на Драконьем Погосте.$B$BНесомненно, наши братья и сестры уже могли воочию убедиться в том, что ты всеми силами помогаешь таунка стать частью Орды. Однако я хочу, чтобы ты лично $gдоставил:доставила: известие о своем успехе командиру Агмару.$B$BИди же, $N! Лети на крыльях ветра! На восток, в Молот Агмара!', 'Отправляйтесь в Молот Агмара на Драконьем Погосте и поговорите с командиром Агмаром.', 'Хотя ты, несомненно, являешься доблестным защитником дела Орды, многие работают не покладая рук над тем, чтобы укрепить и расширить наши позиции в Нордсколе. И сейчас у нас есть силы, организовывающие базы на мерзлых просторах этих пустынных земель.$B$BМы окружаем армию Плети со всех сторон. Победа становится все ближе по мере того, как увеличивается наша армия у подножия Врат Гнева, Ангратара. Скоро мы разнесем врата и ворвемся на Ледяную Корону.$B$BНо еще многое нужно сделать...$B$BДля начала нужно остановить нерубов!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12009, 'Крабовые ловушки Туа\'кеа', 'Из-за всех этих проблем я потерял своих помощников. Я тут подумывал, вдруг ты захочешь мне помочь?$B$BПод водой в гавани я расставил множество ловушек на крабов. Не принесешь ли их мне? Я уже слишком стар для таких вещей, да и в воде небезопасно.$B$BПрошу тебя, возьми эту воздушную камеру, она поможет тебе дышать, когда будешь там, внизу.', 'Соберите 8 ловушек Туа\'кеа для крабов и принесите их ему в гавань Моа\'ки.', 'Я простой охотник. Мир внезапно как будто встал с ног на голову. Бессмыслица какая-то.$B$BНадеюсь, тебе удастся поставить его на ноги обратно.', 'Сколько крабов тебе удалось раздобыть?', NULL, NULL, 'Крабовая ловушка Туа\'кеа', 'Воздушный пузырь Туа\'кеа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12010, 'Что случилось с Орлондом?', 'Когда мы начали раскопки города, я послал геодезиста Орлонда проверить устойчивость туннелей в Тор Модане. Признаться, я не видел его в числе эвакуировавшихся после начала сражения, и я опасаюсь, что он может все еще оставаться в городе.$B$BА его исследования жизненно необходимы нам для того, чтобы обеспечить безопасную транспортировку армии через Тор Модан! Камнегрив с меня живьем шкуру снимет, если под обвалом окажется одна из его дружин!', 'Найдите геодезиста Орлонда в Тор Модане.', 'Быстрый осмотр тела свидетельствует о том, что геодезист умер несколько дней назад. Обыскав его сумку, вы находите рукописные заметки, сделанные рукой бедняги Орлонда.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12011, 'Признаки большой проблемы', 'Эта ловушка для крабов, похоже, была уничтожена чем-то более крупным, чем шныряющие поблизости акулы.$B$BМожет быть, стоит рассказать об этом Туа\'кеа – рыбаку из гавани Моа\'ки?', 'Сообщите рыбаку Туа\'кеа о разрушенной ловушке на крабов.', 'Это не те новости, которых я ждал, $R.$B$BНет-нет... хорошо, что ты мне об этом рассказал, просто я боюсь, что один мой старый заклятый враг вернулся в эти воды.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12012, 'Сообщи старейшинам', 'Эти сведения должны быть переданы всем Служителям Земли. Не знаю, что делать дальше, но это может знать тот, кто тебя послал сюда. Пожалуйста, вернись к нему и узнай, что делать дальше – нельзя сидеть сложа руки!', 'Отправляйтесь в столицу и поговорите со старейшиной Служителей Земли.', 'Воистину, недобрая весть. Мы должны приложить все усилия, чтобы не дать начаться этой войне.', 'Что тревожит тебя, дитя мое?', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12013, 'Покончить с Арканимусом!', 'Осталась еще одна вещь, которую ты $gдолжен:должна: сделать, $N-$r. Я хочу, чтобы ты $gуничтожил:уничтожила: Арканимуса!$B$BКолдуны к западу отсюда использовали то гигантское устройство в небе для того, чтобы высверлить огромный провал там, где мы отдыхаем. Когда они это сделали, то выпустили монстра!$B$BЯ бы так не беспокоился, если бы это было просто угрозой для смертных, но Арканимус питается духами умерших.$B$BТы $gдолжен:должна: немедленно положить этому конец!', 'Уничтожьте Арканимуса и вернитесь к Этениалу Тени Луны в сады Лунного Покоя.', 'Моя глубочайшая признательность, $N.$B$BЕсли ты еще этого не сделал, срочно извести свое начальство об опасности, выпущенной в мир синими драконами. Разрушая якорь силовой линии под садами, они угрожают разрушением всем нам!', 'Ты меня за дурака держишь? Арканимус по-прежнему пожирает души моих братьев и сестер, $C!', NULL, NULL, 'Арканимус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12014, 'Крепкий как камень?', 'Судя по записям, Орлонд привез с собой некий \"переносной сейсмограф\", но поблизости нет ничего похожего на этот прибор. $B$BВ исследовательском дневнике указано, что Орлонд закончил измерения в туннеле Тор Модана, за исключением одного места, помеченного как \"восточный тупик открытого прохода\". $B$BВ последней записи сказано, что Орлонд пытался укрыться в воде, но на него напали подземные крепкобузы. Возможно, именно они забрали его оборудование. Вам надо вернуть сейсмограф, чтобы закончить исследования.', 'Верните портативный сейсмограф и сделайте последний замер колебаний в Тор Модане, после чего вернитесь к Бругару Гравировщику в Лагерь дружины Западного Края.', '<Бругар бегло листает отчет.>$B$BНе нравится мне все это. Даже если нам удастся откопать туннели под обвалом, нет никакой гарантии, что они не обрушатся нам на голову. Похоже, этими проходами не пользовались уже много поколений. Придется огорчить капитана Гриана.', 'Что тебе удалось обнаружить?', NULL, NULL, 'Сведения о состоянии Тор Модана', 'Портативный сейсмограф', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12015, 'Тестовое задание для Крейга', 'олджолджод', 'Принесите 5 незнамо чего Крейгу Амай незнамо куда.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12016, 'Наживка', 'Я уверен в этом... Вернулся наш древний заклятый водный враг, Ту\'у\'гвар – \"Тот, кто играет с добычей\". Мы должны приготовить для него ловушку – ты и я. Есть один вид мяса, мимо которого он уж точно не сможет проплыть равнодушно. $B$BЭто матриарх всех крабов, Кили\'уа \"Огромные Клешни\". Она нежится на своем острове, в водах к юго-западу отсюда. Нанеси-ка ей визит... и возвращайся с ее мясом.', 'Добудьте мясо матриарха по прозвищу \"Огромные Клешни\" и принесите его Туа\'кеа в гавань Моа\'ки.', 'Тебе удалось убить Кили\'уа... тогда, может быть, удастся сделать то же самое и с Ту\'у\'гваром.$B$BА может, и нет...', 'Ты принес мне сочную плоть Кили\'уа?', NULL, NULL, 'Мясо матриарха \"Огромные Клешни\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12017, 'Наживка на крючке', 'Настала пора, мой друг: с Ту\'у\'гваром должно быть покончено!$B$BЯ подготовил мясо таким образом, что эта тварь обязательно придет, когда насадишь наживку на крючок, который я установил под водой. Просто следуй за этой рыболовной леской.$B$BЧто бы ты ни $gделал:делала:, не дай Ту\'у\'гвару проглотить тебя целиком, $N!', 'Убейте Ту\'у\'гвара, а затем вернитесь к Туа\'кеа в гавань Моа\'ки.', 'Возрадуемся твоему успеху, мой юный друг! В воде разлита кровь – и это кровь нашего врага!$B$BЭтот старый рыбак навечно тебе благодарен, а также тебя ждет благодарность всех калу\'аков, как только я сообщу им!$B$BВот, я настаиваю, чтобы ты хоть что-то взял себе в качестве награды. Пожалуйста!', 'Мне показалось, я заметил какое-то волнение и следы борьбы... Ту\'у\'гвар мертв?', NULL, NULL, 'Ту\'у\'гвар убито', 'Наживка Ту\'у\'гвара', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12019, 'Последние ритуалы', 'Я служил Артасу в смерти, потому что у меня не было выбора. Он управлял моей волей и моим телом. А приверженцы Культа Проклятых служат Артасу живыми… добровольно…$B$BТеперь, когда мы знаем слова могущества, необходимые для того, чтобы войти в Наксанар, мы можем положить конец этой язве! Ступай в Эн\'кила и отыщи под парящей цитаделью сферу телепортации!$B$BПроберись наверх, встретимся на вершине. Тебе понадобится все твое мужество – возможно, живыми мы оттуда не выберемся...', 'Отправьтесь в Храмовый город Эн\'кила и отыщите сферу телепортации под парящей цитаделью Наксанар. Используйте сферу, чтобы попасть на вершину цитадели и помочь Тассариану.', 'Молодец, $N… Я надеялся, что моя сестра останется в стороне от всего этого. Благодаря тебе она жива и невредима.$B$BЯ выполнил свой долг перед королем и войском. Очевидно, что мои товарищи больше не рады меня видеть. Придется мне искать свой собственный путь, вести собственную войну и повиноваться лишь приказам своего сердца.$B$BБыть может, мы еще встретимся, $C. А пока – прими это в знак моей признательности.', 'Привет тебе, $N!', NULL, NULL, 'Последние ритуалы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12020, 'Однажды, напившись в...', 'Дворфы Черного Железа потерпели поражение! Убегая в \"Угрюмого обжору\", они потеряли почти весь свой транспорт. Но главное – наш лагерь цел и невредим. $B$BБеги к Бокси и расскажи ему о нашей славной победе над кланом Черного Железа.', 'Поговорите с Бокси Болтокрутом в лагере Хмельного фестиваля.', 'Значит, даже немалое количество выпитого пива не помешало тебе расстроить зловещие планы клана Черного железа? Вот это действительно в духе Хмельного фестиваля! Полагаю, ты заслужил призовые жетоны.$B$BСпасибо за помощь, $N. Веселого тебе Хмельного фестиваля!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12021, 'Письмо домой', 'Это письмо, похоже, адресовано одному из жителей Штормграда одним из последних селян с Полей Падальщиков. Может быть, кто-то из выживших в восточном лагере возьмется переправить письмо по адресу.', 'Доставьте письмо домой к леди Алистре на восточные Поля Падальщиков.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12022, 'Пей до дна!', 'Эй! Похоже, с выпивкой ты обращаться умеешь. А вот с пивной кружкой? $B$BЭти дворфы из клана Черного Железа опять вернулись! Мстить хотят и праздник нам порушить! Легче всего их отогнать, если запустить в них пивной кружкой, но сначала посмотрим-ка, попадешь ли ты в чучелко – С.С.М.?$B$BЭто просто – хлебни бесплатного пивка, только встань сначала лицом к С.С.М. Попади в цель пять раз, тогда поговорим.', 'Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Бокси Болтокрутом.', 'Знаешь, что это? Гномское инженерное дело во всей ее красе! С.С.М. Выдерживает побои прям героически!$B$BДумаю, если кто из дворфов Черного Железа сюда сунется, ты сумеешь им дать по носу!', 'Хлебай да бросай, С.С.М. все стерпит – чего бы я тогда его сооружал?', NULL, NULL, 'Вы попали в ССМ', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12026, 'Порванный журнал', 'Этот потрепанный, запятнанный дневник знавал лучшие времена. Листая страницы, вы находите множество карт, диаграмм и заметок, написанных на дворфийском языке.$B$BВам удается разобрать только имя Бранна Бронзоборода, написанное в конце одной из заметок.$B$BВторая половина книги, содержащая самые последние записи, была грубо вырвана. Похоже, кто-то счел этот дневник достаточно важным, и попытался уничтожить. Вы надеетесь, что недостающие страницы все еще можно отыскать на поле боя.', 'Разыщите 8 недостающих страниц, вклейте их в дневник и верните его Ведунье Палуне в Лагерь Уанква.', 'А кто такой этот Бранн Бронзобород? Я еще могу понять, почему железные дворфы не стали с ним связываться – но что полезного может поведать нам его дневник?', 'Что ты мне принес?', NULL, NULL, 'Потерянный дневник Бранна Бронзоборода', 'Неполный дневник', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12027, 'Удивительное приключение мистера Ушастика', 'Простите, $gгосподин:госпожа:, вы не могли бы подсказать нам дорогу в военный лагерь?$B$BМы с мистером Ушастиком решили погулять в лесу вместе с моим братиком Волтером, но в последний момент его куда-то позвали.$B$BТак что мы с мистером Ушастиком пошли гулять одни, но сразу же заблудились, а потом за нами погнались голодные волки, но мы нашли эту башню и спрятались внутри. $B$BВолки убежали, но мы теперь не знаем, куда идти.$B$BМожет быть, вы нам поможете? Пожа-алуйста!', 'Помогите Эмили и мистеру Ушастику вернуться в Лагерь дружины Западного Края, после чего поговорите с оруженосцем Волтером.', 'Слава богам, Эмми в порядке! Я так боялся, что она без меня заблудится.$B$BХорошо, что мистер Ушастик тоже не пострадал.', NULL, NULL, NULL, 'Помогите Эмили и мистеру Ушастику вернуться в лагерь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12028, 'Духовное озарение', '$gраса:, мы не слышали о наших соплеменниках в деревне Инду\'ле с того самого момента, как земля затряслась и стала раскалываться!$B$BТебе когда-нибудь доводилось выполнять обряд поиска видений? Ты ведь $gпревзошел:превзошла: Логуна, так что у тебя должно получиться.$B$BЯ дам тебе особое благовоние, которое нужно будет всыпать в мою жаровню. Глубоко вдохни его дым, и твой дух воспарит, чтобы увидеть, что произошло в Инду\'ле.$B$BА пока дух твой будет в полете, я смогу смотреть твоими глазами.', 'Поговорите с Тоалу\'у Мистиком после того, как пройдете обряд поиска видений.', 'Призраки и полное безумие? Не может быть!$B$BМы должны искать дальше, что делать.', 'Ну, что скажешь?', NULL, NULL, 'Видение о судьбе деревни Инду\'ле получено.', 'Спиритические благовония Тоалу\'у', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12029, 'Пылающая Плеть', '$gИк:... сжечь надо эти трупы, пока они снова не начали ходить.$B$BЗнаешь, что говорил мне мой папочка? Нет ничего хуже тролля, которого приходится убивать дважды.$B$BВот..$gик:... как нам оттеснить этих троллей на север, если их так много?$B$BДавай-ка ты избавишь этих мерзавцев от печальной участи жизни после смерти?', 'Мак с Гранитных ключей просит вас поджечь 20 голодающих троллей Плети с помощью его грога.', 'Ай, молодца!$B$B<Мак заходится истерическим хохотом.>$B$BАйй... ну что ты так смотришь, смешно же было... ик!', NULL, NULL, NULL, 'Сожжено троллей', 'Темный грог Мака', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12030, 'Старейшина Мана\'лоа', 'Мой народ…$B$B<Мистик едва не теряет самообладание.>$B$BПока дух твой летал по территории деревни, я почувствовал, что тебя заметил старейшина Мана\'лоа. $N, он хочет поговорить с тобой. Каменных старейшин мы почитаем как источники древней мудрости.$B$BНаверное, старейшине нужна помощь. Найди его в северо-западном углу деревни.', 'Поговорите со статуей старейшины Мана\'лоа в деревне Инду\'ле.', 'Я ждал тебя, $R. Я видел, как мимо пролетал твой дух, и почуял мистическое наблюдение, которое велось твоими глазами.$B$BТвоя судьба и судьба калу\'аков отныне связаны.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12031, 'Свобода перемещения', 'Священная земля эльфов на западе была расколота. Теперь их магия течет по земле, сея разрушение на своем пути.$B$BДуши калу\'аков в опасности, поскольку силы синих драконов пытаются взять эту магию под контроль.$B$BЭнергия поднялась из озера, в мгновение ока убив большинство жителей деревни. Те, кто выжили, сошли с ума.$B$B$N, тебе нужно освободить их души, чтобы они могли свободно двигаться. А свихнувшихся живых оставь в покое – может быть, они со временем придут в себя.', 'Успокойте рыбаков, мистиков и воинов из деревни Инду\'ле (общим числом 15 противников), а затем вернитесь к старейшине Мана\'лоа в деревню Инду\'ле.', 'Не самое приятное дело тебе пришлось выполнять, зато необходимое и благое.$B$BА теперь есть кое-что еще, что тебе суждено сделать для народа калу\'аков.', '<Старейшина Мана\'лоа видит вас насквозь и чувствует, что вы еще не выполнили его задание.>', NULL, NULL, 'Упокоены духи деревни Инду\'ле', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12032, 'Разговор с бездной', 'Нужно посоветоваться с богиней воды, Оача\'ноа, только она может знать, какая судьба ожидает калу\'аков. И лишь Жемчужина Бездны может вызвать ее из темных глубин.$B$BНа юго-западе, неподалеку от берега, возвышается Соленая вершина. На ней стоит алтарь, на алтаре – жемчужина.$B$BОбратись к алтарю, и Оача\'ноа услышит твой зов. Смотри, делай все, как она велит, не то навлечешь на себя ее гнев и погубишь всех клыкарров!$B$BЕсли выживешь, возвращайся к мистику.', 'Обратитесь к Жемчужине Бездны и выполните распоряжения морской богини Оача\'ноа.Если вы переживете все испытания, вернитесь к Тоалу\'у Мистику в гавани Моа\'ки.', 'Удалось ли тебе поговорить с Оача\'ноа?$B$BЧто ж, если богиня велит, чтобы мы были заодно с твоим народом, да будет так. Старейшина Ко\'нани повинуется этому решению, будь то на беду или на радость.$B$BМой народ верит, что все души едины с магией мира. И мы должны противостоять синим драконам, что пытаются подчинить магию себе. Иначе все мы обречены!$B$BНикогда не думал, что $r станет на защиту калу\'аков, но ты – доказательство того, что я ошибался. Я благодарю тебя, $N, от имени моего народа.$B$BДа улыбнутся тебе боги, и да хранят они тебя в пути.', NULL, NULL, NULL, 'Исследовать локацию', 'Повиновение приказам Оача\'ноа.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12033, 'Послание с запада', '$gТорвус пожимает вам руку, и одновременно сует в нее письмо.>$B$B<Говорит, не разжимая губ.>$B$BПодыграй мне, $N!$B$BРад видеть тебя здесь, солдат! Лорд Адский Крик, несомненно, отправил к лорду Агмару самых сильных своих бойцов!$B$B<Говорит, не разжимая губ.>$B$BПрочитай его, и тут же сожги в жаровне рядом со мной.', 'Прочитайте письмо от Саурфанга и уничтожьте его.Выполнив это, поговорите с посланником Торвусом.', '<Торвус кивает вам.>$B$BТак мы поняли друг друга? Я вернусь к своему лорду и скажу ему, что ты согласен.', 'Мы раздавим Плеть!', NULL, NULL, 'Письмо от Саурфанга прочитано и уничтожено', 'Письмо от Саурфанга', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12034, 'Победа близка…', 'Теперь у нас на пути остаются лишь две основных угрозы. Одна – жуткая цитадель Наксрамас далеко на востоке, парящая над альянсовской крепостью Стражей Зимы, а вторая – Провал Наржуна, откуда появляются армии нежити Ажол-Неруба. Именно из Провала Наржуна появились нерубы – воины Ануб\'ара, которые атаковали и стерли с лица земли Ледяную Пыль, деревню таунка.$B$BМы уничтожим воинов Ануб\'ара и закроем Провал Наржуна!$B$BЯвись к главному сержанту Юктоку, он отдаст тебе соответствующие распоряжения.', 'Поговорите с главным сержантом Юктоком в Молоте Агмара.', 'Клянусь землей и ветром, мы покончим с угрозой Ануб\'ара!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12035, 'Переналадка технологии', 'Да, теперь я понял! Перемонтаж – штука непростая, но $gтакой умный:такая умная:$r, как ты, разберется.$B$BВозьми мои инструменты и обесточь несколько сборщиков урожая. Когда они придут в нерабочее состояние, используй инструменты, чтобы воткнуть все красные провода в синие розетки. Это должно перевести сборщиков в режим самообороны. Поспеши, $N. А то еще немного – и будет нечего спасать.', 'По поручению Иеремии Хоунинга обезвредьте 5 сборщиков урожая, а затем воспользуйтесь инструментами Иеремии, чтобы перемонтировать их.', 'Хорошая работа! Наконец-то я снова чувствую себя нужным... а это кое о чем говорит!', NULL, NULL, NULL, 'Переделано сборщиков урожая', 'Инструмент Иеремии', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12036, 'Глубины Азжол-Неруба', 'Нерубы, напавшие на деревню Ледяной Пыли, явились из гигантской воронки, известной как Провал Наржуна. Если их оставить в покое, эти кошмарные твари, несомненно, обойдут с флангов наши силы у Врат Гнева и станут серьезной преградой на нашем пути к победе.$B$BМне нужны глаза на земле, $N. Ты направишься на запад и обследуешь Провал Наржуна. Нам нужно вычислить их основную точку выхода и запечатать ее. Найди же эту точку.', 'Исследуйте Провал Наржуна и возвращайтесь с данными к главному сержанту Юктоку, ожидающему у Молота Агмара.', 'Эта треклятая воронка, должно быть, напрямую связана с Азжол-Нерубом. Это хуже, чем я думал.$B$B<Юкток замолкает на минуту, раздумывая.>$B$BНайти и уничтожить… это будет нашим следующим ходом.', NULL, NULL, NULL, 'Исследовать локацию', 'Провал Наржуна исследован', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12037, 'Спасательная операция', 'Орки такие упрямые, сил нет... ик. Ты со мной $gсогласен:согласна:, $r?$B$BВот, например, Курцель – столько лет уже работает с нами. Даже макака успела бы усвоить, как надо проворачивать дела. Нашел дурака делать за тебя самую опасную работу, а награду положил себе в карман. Неужели так сложно это понять?$B$BТак ведь нет... эта срывается с места и берет все в свои руки. Наверное, она уже мертва... но мне все равно как-то не по себе из-за того, что мы бросили ее одну. Жаль, что я не в том состоянии, чтобы прийти ей на помощь... ик!$B$B<Дружище:Подруга:, может быть, ты попробуешь ее отыскать?', 'Мак из Гранитных ключей просит вас отправиться в Драк\'Тарон и узнать, все ли в порядке с Курцель.', 'Так я и знала!$B$BПровались я сквозь землю – никто из этих бесхребетных слизняков не протянет мне руку.$B$BНу, во всяком случае, они прислали тебя. Будем считать, проявили хоть какую-то заботу... $B$BВот, держи. Лучше уж я тебе отдам эту штуку, чем этим слабакам из нашего лагеря.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12038, 'Пылающая Плеть', 'Чего ждем, $C? Думаешь, эти тролли сами по cебе скопытятся?$B$BДавай-ка, за работу. Идешь на север, в Драк\'Тарон. Черпаешь грог и плещешь на этих мерзавцев...$gик:. А потом отбегаешь в сторонку и смотришь, как они будут гореть!', 'Мак из Гранитных ключей просит вас поджечь 30 голодающих троллей Плети с помощью его грога.', 'Ай, молодца!$B$B<Мак заходится истерическим хохотом.>$B$BАйй... ну что ты так смотришь, смешно же было... ик!', NULL, NULL, NULL, 'Сожжено троллей', 'Темный грог Мака', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12039, 'Черная кровь Йогг-Сарона', 'Ангратар, Врата Гнева… Я был свидетелем тому, как металл, удерживающий створки ворот, пульсировал и бился, будто живой! За 50 лет я никогда не видел, чтобы металл \"дышал\"…$B$BОб этом могут знать только клыкарры. Они называли это \"черной кровью Йогг-Сарона\" и предупреждали меня, чтобы я не приближался.$B$BЗа пределами деревни Ледяной Пыли, на запад от нее, есть воронка, называемая \"Провалом Наржуна\". Я слышал, что подобные воронки богаты этой странной рудой. Если путь твой лежит в ту сторону, можешь попробовать найти руду и принести мне несколько образцов?', 'Принесите Борусу Железные Клещи из Молота Агмара на Драконьем Погосте 10 образцов черной крови Йогг-Сарона.', 'Ох, какая легкая… Как будто вовсе ничего не весит! Мне понадобится время, чтобы проанализировать состав металла и понять, могу ли я что-нибудь изготовить из него. Опыты! Нужно провести опыты!$B$BЯ буду на связи, $N. Если из этого что-нибудь выйдет, ты первым об этом узнаешь!', 'Чего стоит жизнь, в которой нет места риску?', NULL, NULL, 'Образец черной крови Йогг-Сарона', 'Шахтерская кирка Боруса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12040, 'Общий враг в лице Артаса', 'У нас гражданская война в разгаре. В самом сердце этого мира существа моего вида пытаются защититься от тотального уничтожения. Король-лич жаждет править царством Азжол-Неруба любой ценой. Несогласные объявляются врагами Плети и приговариваются к смерти.$B$BАртас – наш общий враг...$B$BПрисоединяйся к нашей кампании и очисти это место от скверны воинов Ануб\'ара! Пусть сам Ануб\'арак услышит их мучительные предсмертные крики!', 'По заданию Киликса Разрушителя у Провала Наржуна на Драконьем Погосте убейте 6 ануб\'арских владык подземелий.', 'Их еще тысячи и тысячи, и они выползают из каждой темной расщелины в Нордсколе. В одиночку у тебя нет ни единого шанса, но вместе... Может быть...', 'Ажольская империя поднимется из руин!', NULL, NULL, 'Ануб\'арский владыка подземелий убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12041, 'Потерянная империя', 'Ты $gдоказал, что готов:доказала: что готова; помочь империи Ажол в ее трудные времена – и, в таком случае, ажольская империя поможет Орде.$B$BОтнеси этот свиток своему вождю. Там перечислены сильные и слабые стороны нерубов, напавших на деревню Ледяной Пыли. Считай это жестом доброй воли – добровольным желанием помочь твоему народу. Воспользуйся знанием, зафиксированным на этих страницах, для того, чтобы сразить воинов Ануб\'ара – и ты сослужишь хорошую службу всем нам.$B$BПрощай, $r.', 'Доставьте боевые планы Киликса командиру Агмару в Молот Агмара на востоке.', '<Командир Агмар просматривает документ.>$B$BЭто то, о чем я думаю? С информацией, содержащейся здесь, мы просто РАЗМАЖЕМ наступающих воинов Ануб\'ара!$B$BХорошо, что ты принес этот документ мне, $N. Может быть, тебе будет дозволено понаблюдать за решающей битвой у Ангратара или даже поучаствовать в ней! ЛОК\'ТАР!', 'Что это у тебя?', NULL, NULL, 'Боевые планы Киликса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12042, 'Сердце древних', 'Тайны древности, откройтесь мне!$B$B<Дракуру смотрит через Глаз пророков.>$B$BО-о, меня ждет великая судьба, $N. Повезло тебе оказаться рядом со мной.$B$BАга! Вижу! Вижу Сердце древних! Ну, до него будет легко добраться...$B$BОно лежит рядом с трупом гоблина, в какой-то постройке, что рядом с рекой к востоку отсюда.', 'Дракуру просит вас отправиться в самую верхнюю комнату Лесозаготовок Синего Неба и найти Сердце древних.', 'Наверное, этот несчастный гоблин нашел Сердце древних во время раскопок.$B$BБедняга даже не понял, что за сокровище попало ему в руки.$B$BНеудивительно, учитывая весь этот бардак, который творится в наших краях.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12043, 'Защита Лагеря Соплозабилось', 'Слышь, ты, $C! Эта нежить к югу от нас просто до жути мешает нам работать. Сходи-ка зачисть там, а?', 'Убейте 12 землекопов пустошей и одного надсмотрщика пустошей на раскопках, окружающих Покой Галакронда. Вернитесь к Нарфу в Лагерь Соплозабилось, когда задание будет выполнено.', 'А... Ну да, нежить. Вот твои деньги – и катись отсюда.', NULL, NULL, NULL, 'Надсмотрщик пустошей убито', 'Землекоп пустошей убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12044, 'Припасти руды', 'Привет-привет! Силы Плети к югу отсюда выкапывают из земли какого-то древнего дракона. Мне абсолютно по барабану, какого лешего им это надо, но в процессе выкапывания они достают кучи композитной руды.$B$BПойди принеси мне немного такой руды. Эта руда будет подороже всего оружия, что в Орде изготавливают.', 'Соберите 8 пригоршней композитной руды на раскопках, окружающих Покой Галакронда и принесите их Зинку в Лагерь Соплозабилось.', 'Ха! Вот это ты набрал! Спину не надорвал?', 'Ты собрал руду? Мой посыльный скоро вернется – мы должны отправить посылку, пока битва еще продолжается!', NULL, NULL, 'Композитная руда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12045, 'Битый лед', 'Никогда тебя раньше не видела. Ты что, новичок в Погани? Очень приятно. Лишние рабочие руки никогда не помешают.$B$BДобудь мне материалы, я доделаю свою машину, загоним ее этим воякам и уедем домой богатыми!$B$BВообще-то все основные компоненты у меня уже есть, но мне недостает кое-каких материалов для снаряда. Нарф говорил, что из зазубренных осколков льда, полученных от северных элементалей, выйдет замечательная шрапнель. Добудь мне таких осколков, а?', 'Соберите 4 горсти осколков льда от ледяных элементалей на севере и принесите их Живликс в Лагерь Соплозабилось.', 'Великолепно! Ой, какие острые-то! Сложу их в снег, пока не доделаю бомбу.$B$BТак… что у нас там дальше…', 'Ну что, где осколки? А то основную холодильную установку я уже почти достроила!', NULL, NULL, 'Горсть осколков льда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12046, 'Мягкая оболочка', 'Мне нужна какая-то новая оболочка для этих разрывных бомб. Все, что у меня есть, слишком прочное, осколки не разлетаются при взрыве.$B$BЧто нам нужно, так это тонкая звериная шкура. Например, сгодятся туннельные йормунгары… или кондоры, которые роются в драконьих костях... Короче, принеси что найдешь.', 'Соберите 12 тонких шкур животных, убив нужное количество туннельных йормунгаров или глодателей драконьих костей близ Лагеря Соплозабилось. Добыв шкуры, вернитесь с ними к Живликс.', 'Хорошо… хорошо… Да, это подойдет. Мои бомбы почти готовы!$B$BПостой! А как же мои ледяные осколки? Нарф говорил мне, что осколки этих элементалей зачарованные, а они тают совершенно так же, как и те сосульки, что свисают с Нарфова подбородка!', 'Ну, как охота? Где шкуры?', NULL, NULL, 'Тонкая звериная шкура', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12047, 'Нечто тугоплавкое', 'Нет-нет-нет! Эти ледяные осколки совершенно не годятся! Они растают, не успев никому причинить вреда! Чтоб я еще поверила Нарфу, когда речь идет о материалах! Значит, для изготовления шрапнели нужно что-то совершенно другое…$B$BЗнаю! Я гений! Осколки костей.$B$BТут повсюду валяются кости, йормунгары их постоянно точат. Попробуй найти для меня осколки, которые сгодятся в дело.', 'Найдите среди драконьих костей к востоку от лагеря Соплозабилось 12 расколотых костей.', 'Отлично! Это последнее, чего мне не хватало, чтобы испытать новые бомбы. Минутку, сейчас испробуем!', 'Ну что, есть подходящие осколки?', NULL, NULL, 'Расколотая кость', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12048, 'Доспехи воинов Плети', 'Я из этой проклятущей руды ничего сделать не могу. Ничего держаться не будет! Несмотря на все мои усилия, металл Плети не гнется и не тянется!$B$BМожет быть, если бы у меня были образцы доспехов воинов Плети, я мог бы разобраться в процессе их изготовления.$B$BДеревня Ледяной Пыли кишит бронированными воинами Неруба. Иди принеси мне элементы доспехов воинов Плети! С твоей помощью я, должно быть, преуспею в изготовлении хоть чего-нибудь из этой руды.$B$BДеревня Ледяной Пыли находится к западу отсюда.', 'Принесите 8 элементов доспехов воинов Плети Борусу Железные Клещи из Молота Агмара.', 'О, ты принес отличные образцы, $N. Я немедленно приступаю к работе. Если из этого что-нибудь выйдет, ты об этом первым узнаешь!', '<Борус отшвыривает прочь свои инструменты.>$B$BВсе это бесполезно!', NULL, NULL, 'Элемент доспеха воина Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12049, 'Мясо с пылу с жару', 'Эти войска бесспорно нужно хорошенько накормить.$B$BЯ открою тебе один ма-а-аленький секрет, который $gтакой брезгливый:такая брезгливая:$r, как ты, никогда не $gузнал:узнала: бы самостоятельно... Эти йормунгарские черви по вкусу – что твои цыплята.$B$BИди, разозли одного из этих огромных неповоротливых йормунгаров, к востоку отсюда. Вряд ли тебе удастся убить такого, так что просто запихни вот это ему в глотку, когда он рот откроет. Принеси мне столько мяса, сколько дотащишь.', 'К востоку от Лагеря Соплозабилось сразитесь с огромным йормунгаром – до тех пор, пока тот не откроет рот. Затем бросьте ему в глотку мощную взрывчатку. После взрыва соберите 6 кусков обугленного мяса йормунгара с земли и принесите их Зинку.', 'Ха-ха! Один из кусков мяса прям вон там приземлился! Отлично сработано!', 'Собрал? От тебя воняет йормунгарами!..', NULL, NULL, 'Обугленное мясо йормунгара', 'Мощная взрывчатка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12050, 'Лесорубы', 'Теперь надо раздобыть древесины – Альянсу нужно много дерева для строительства башен! На юге растут кое-какие деревца, но для строительства куда больше подходят деревья на севере, на которых гнездятся гарпии.$B$BВозьми это. Когда придешь к месту гнездовий гарпий, нажми на кнопку, и к тебе явится один из моих крошшеров. Добудь как можно больше древесины! Конечно, гарпии будут против – но с ними ты, думаю, разберешься.$B$BВперед, за дело!', 'Используйте пульт управления Крошшером Зинка, чтобы вызвать Крошшер, когда доберетесь до гнездовья гарпий на севере. Соберите 50 связок бревен и возвращайтесь к Зинку в Лагерь Соплозабилось.Если потеряете пульт управления Крошшером Зинка, поговорите с Зинком в Лагере Соплозабилось, чтобы получить новый.', 'Если в лесу падает дерево, а ты этого даже не слышишь за визгом пил, то какая разница?', 'И где же этот носильщик? Надеюсь, он не попадется йормунгарам… На этот раз у него с собой внушительный груз.', NULL, NULL, 'Дрова для Морозной выси', 'Пульт управления крошшером Зинка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12051, 'Выдирание перьев', 'Эти гарпии слишком долго замедляли получение нами прибылей! Убей их всех!', 'По просьбе Нарфа из лагеря Соплозабилось убейте 20 гарпий к северо-западу от Лагеря Соплозабилось.', '', NULL, NULL, NULL, 'Гарпии Морозной Выси', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12052, 'Смерть гарпиям!', '$C, ты это $gвидел:видела:? Проклятая гарпия напала на наш груз, приготовленный к отправке к вратам! Кажется, я уже встречался с ней на Морозных высях.$B$BМы и так уже понесли значительные убытки из-за этих гарпий! Убей их всех!', 'Убейте госпожу Морозной выси и 15 гарпий Морозной выси в горах к северо-западу от лагеря Соплозабилось. Когда задание будет выполнено, возвращайтесь к Нарфу.Если вам понадобится пульт управления крошшером Зинка, обратитесь к Зинку в Лагерь Соплозабилось.', 'Теперь эти тварюги сначала дважды подумают. Вот... держи свою награду и проваливай отсюда.', NULL, NULL, NULL, 'Госпожа Морозной выси убито', 'Гарпии Морозной Выси', 'Пульт управления крошшером Зинка', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12053, 'Мощь Орды', 'Таунка теперь – наши братья по оружию. Мы должны доказать им нашу солидарность и отвоевать деревню Ледяной Пыли.$B$BОна находится к западу от Молота Агмара, устроившись у подножья гор. Отправляйся туда и начни бой с нерубскими воинами Ануб\'ара! Установи наше ненаглядное знамя Орды в деревне Ледяной Пыли и уничтожь любого, кто попытается сорвать его!$B$BПусть ануб\'ары почувствуют мощь Орды! Пусть наше боевое знамя станет последней вещью, которую они увидят в жизни!', 'Установите боевой штандарт клана Песни Войны в деревне Ледяной Пыли и защитите его от нападающих.Затем верните боевой штандарт клана Песни Войны главному сержанту Юктоку в Молот Агмара на Драконьем Погосте.', 'Мы разгромили их на земле! А скоро повергнем их и с воздуха!', 'Это вызов, $N!', NULL, NULL, 'Боевой штандарт клана Песни Войны (Прилагается)', 'Боевой штандарт клана Песни Войны защищен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12054, 'Расшифровать записи', 'Вор\'такх прав – мы не можем упустить такую возможность.$B$BК счастью, я знаю способ, как перевести дневник этого Бранна.$B$BШаманы племени Красного Клыка, обитающие в Святилище Кровавого Сердца к югу от лагеря, выращивают траву, известную как дыхание духа. Опытные мистики используют ее в качестве благовония, позволяющего входить в транс и советоваться с духами предков. $B$BНайди шамана Грумбальда Одноглазого. У него должен быть с собой запас травы для проведения обрядов в Урсоке.', 'Принесите пучок дыхания духа ведунье Палуне в Лагерь Уанква.', 'Ты молодец, $N. Сейчас я приготовлю благовоние, и мы узнаем, что этот благородный дворф делал так далеко от дома.', 'Надеюсь, ты принес достаточно травы.', NULL, NULL, 'Дыхание духа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12055, 'Странное приспособление', 'Взяв в руки это странное приспособление, вы сразу обретаете уверенность, что оно – магической природы. К сожалению, по его внешнему виду никак не определить, как и для чего это устройство используется.$B$BМожет быть, верховный маг в Покое Звезд на восток от Садов Лунного Покоя сможет сказать, для чего оно нужно?', 'Отнесите странное устройство Горамоша проекции верховного мага Модеры в Покой Звезд.', 'Плютей, если только я не ошибаюсь, ты обнаружил ключ, который позволит нам точно определить, что замыслили силы охотников на магов!', 'Что это у тебя?', NULL, NULL, 'Странное устройство Горамоша (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12056, 'Приговорен к смерти: верховный сектант Зангус', 'Предательство произошло на моих глазах! Этот изменник повел воинов Ануб\'ара в атаку на крепость и погубил некоторых из моих лучших бойцов.$B$B<Горт горько качает головой.>$B$BОн все это время работал на Плеть, а мы и знать не знали! Сколько здесь еще таких, подобных Зангусу? Мы найдем их всех, а когда найдем...$B$B<Горт делает выразительный жест поперек шеи.>$B$BОднако Зангус возглавляет список. Наши разведчики докладывают, что он скрывается в Провале Наржуна, к западу отсюда. Найди его, убей и принеси мне его голову.', 'Убейте верховного сектанта Зангуса и отнесите его голову капитану Горту в Молот Агмара на Драконьем Погосте.', '<Горт поднимает голову и долго всматривается в мертвые глаза.>$B$BЯ говорил тебе, что мы тебя достанем…$B$BВот твоя награда, $C. Теперь у нас одной головной болью меньше.', 'У тебя с собой отрезанная орочья башка или ты просто рад меня видеть?', NULL, NULL, 'Голова верховного сектанта Загнуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12057, 'Сшитый плотью фолиант', 'Фолиант обтянут плотью и, кажется, из него сочится кровь. Просматривая его страницу за страницей, вы обнаруживаете, что они покрыты странными символами, похоже, написанными кровью.$B$BКакое бы знание ни было скрыто на этих страницах, оно может оказаться важным. Отнесите фолиант капитану Гортку в Молот Агмара, к востоку от деревни Ледяной Пыли.', 'Доставьте сшитый плотью фолиант капитану Горту в Молот Агмара.', '<Горт принимает фолиант у вас из рук.>$B$BСволочи... Это орочья плоть... А язык... Его существование никогда не получало подтверждения. Это наречие смерти... Язык Плети.', '<Горт вопросительно поднимает бровь.>', NULL, NULL, 'Сшитый плотью фолиант (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12058, 'Рунические пророчества', 'В журнале Бранна есть расшифровка некоторых символов железных дворфов. Я нацарапала их на краеугольном камне, чтобы ты с его помощью $gсмог:смогла: перевести надписи на рунических дисках.$B$BСудя по прочим записям, Бранн пытался узнать, откуда произошла его раса. Постарайся понять, что открылось ему на этих табличках. $B$BВозвращайся в Тор Модан, что к северо-востоку отсюда, подойди к каждой табличке и воспользуйся краеугольным камнем. Нельзя допустить, чтобы Альянс нашел его прежде нас!', 'Ведунья Палуна из Лагеря Уанква просит вас перевести надписи на трех Рунических дисках.', '<Ведунья Палуна слушает ваш перевод табличек.>$B$BТак Бранн полагает, что он обнаружил новый город $Nв? Колыбель камня и железа...\'$B$B\'Ульдуар в центре бури.\'$B$BНадо попросить вождя отправить гонцов в Грозовую Гряду. Это наш последний шанс найти след сбежавшего дворфа.', NULL, NULL, NULL, 'Первое пророчество расшифровано', 'Второе пророчество расшифровано', 'Третье пророчество расшифровано', 'Рунический краеугольный камень');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12059, 'Странное приспособление', 'Взяв в руки это странное приспособление, вы сразу обретаете уверенность, что оно – магической природы. К сожалению, по его внешнему виду не определить, как и для чего это устройство используется.$B$BВозможно, верховный маг в Молоте Агмара на северо-востоке от Садов Лунного Покоя сможет сказать, для чего оно нужно?', 'Отнесите странное устройство Горамоша проекции верховного мага Этаса Похитителю Солнца в Молот Агмара.', '$N, если только я не ошибаюсь, ты обнаружил ключ, который позволит нам точно определить, что замыслили силы охотников на магов!', 'Что это у тебя?', NULL, NULL, 'Странное устройство Горамоша (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12060, 'Проекты и проекции', 'Это устройство телепортации. Если бы мне пришлось угадывать, я сказала бы, что оно ведет к платформе-волнолову, плавающей над Садами Лунного Покоя, к западу отсюда.$B$BМне нужно, чтобы ты $gиспользовал:использовала: его для того, чтобы разведать, что там творится. Похоже, устройство работает в обоих направлениях, так что у тебя не предвидится проблем с возвращением.$B$BЯ думаю, что когда ты переместишься на вершину волнолова, там будет некий аппарат, который нужно будет изучить.$B$BТелепортироваться обратно ты сможешь из любой точки в пределах Садов.', 'Подберитесь поближе и обследуйте конструкцию на вершине волнолова, плавающего в воздухе над Садами Лунного Покоя.После этого возвращайтесь с полученной информацией к проекции верховного мага Модеры в Покой Звезд.', 'То, что ты описываешь... это же проекция \"Чарономикона\"!$B$B<Появившееся было тревожное выражение на лице верховного мага тотчас скрывается под бесстрастно-непроницаемой маской.>$B$B\"Чарономикон\" – это карта всех пересечений магических силовых линий в мире. Синие драконы используют ее для поиска и разрушения так называемых якорей этих силовых линий, чтобы магическая энергия ушла обратно в Нексус.$B$BВопрос в том, почему путь разрушения ведет на восток, когда, по идее, он должен идти в прямо противоположном направлении – на запад?', NULL, NULL, NULL, 'Объект на вершине волнолова осмотрен', 'Телепорт к Волноловам', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12061, 'Проекты и проекции', 'Это устройство телепортации. Если бы мне пришлось угадывать, я сказал бы, что оно ведет к платформе-волнолову, плавающей над Садами Лунного Покоя, к юго-западу отсюда.$B$BМне нужно, чтобы ты $gиспользовал:использовала: его для того, чтобы разведать, что там творится. Похоже, устройство работает в обоих направлениях, так что у тебя не предвидится проблем с возвращением.$B$BЯ думаю, что когда ты переместишься на вершину волнолова, там будет некий аппарат, который нужно будет изучить.$B$BТелепортироваться обратно ты сможешь из любой точки в пределах Садов.', 'Подберитесь поближе и обследуйте конструкцию на вершине волнолова, плавающего в воздухе над Садами Лунного Покоя.После этого возвращайтесь с полученной информацией к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара', 'То, что ты описываешь... это же проекция \"Чарономикона\"!$B$B<Появившееся было тревожное выражение на лице верховного мага тотчас скрывается под бесстрастно-непроницаемой маской.>$B$B\"Чарономикон\" – это карта всех пересечений магических силовых линий в мире. Синие драконы используют ее для поиска и разрушения так называемых якорей этих силовых линий, чтобы магическая энергия ушла обратно в Нексус.$B$BВопрос в том, почему путь разрушения ведет на восток, когда, по идее, он должен идти в прямо противоположном направлении – на запад?', 'Так быстро?', NULL, NULL, 'Объект на вершине волнолова осмотрен', 'Телепорт к Волноловам', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12062, 'Оскорбить Корена Худовара', 'Корен Худовар сидит в соседней комнате, вынашивает очередные планы нападения дворфов Черного Железа на Хмельной фестиваль. Ты $gдолжен:должна: его остановить!$B$BИди к Корену и разозли его хорошенько. Например, можешь сказать ему, что его пивом даже свинья побрезгует.$B$BА после этого приготовься к драке! Последний храбрец, осмелившийся раскритиковать его пиво... пошел на корм диким кабанам.', 'Поговорите с Кореном Худоваром.', 'Что? Что ты сказал? Да как ты смеешь! Мое пиво и рядом не стояло с этими помоями, которые подают на Хмельном фестивале!$B$BТы за это поплатишься, $C!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12063, 'Сила Ледяной Пыли', '<Великая мать Ледяная Пыль кланяется.>$B$BДля меня честь познакомиться с тобой, $gнаш герой:наша героиня:. Именно благодаря твоим действиям нас здесь сейчас так много – живых-здоровых и готовых к битве против сил Плети.$B$BТы так много $gсделал:сделала: для нас, что мне стыдно еще раз просить тебя о содействии. Несмотря на мои мольбы, мой единственный сын, Банток, ушел на поиски своего отца, верховного вождя Ледяной Пыли. В последний раз его видели направляющимся на запад, к деревне Ледяной Пыли. Я не знаю, что со мной будет, если я потеряю сына...', 'Найдите Бантока Ледяную Пыль в окрестностях деревни Ледяной Пыли.', 'Мой отец по-прежнему жив! Мы должны спасти его! Я не смогу сделать это в одиночку, $R. Ты должен мне помочь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12064, 'Ануб\'арские оковы', 'Они заковали моего отца в магические оковы в центре деревни Ледяной Пыли. Я сумел разузнать, что его узилище контролируют три могущественных ануб\'арских мага – каждый из них держит при себе фрагмент ключа.$B$BЗачисть деревню и найди этих магов. Убей их и забери фрагменты ключей. Когда у нас будут все три фрагмента, мы сможем заняться освобождением моего отца. А когда он будет свободен...$B$BВозмездие будет скорым.', 'Принесите Бантоку Ледяной Пыли, ожидающему у деревни Ледяной Пыли на Драконьем Погосте, фрагмент ключа Анок\'ры, фрагмент ключа Тивакса и фрагмент ключа Синока.', 'Да, это сработает.$B$B<Банток умело манипулирует фрагментами.>$B$BКлюч готов, $C. С его помощью мы освободим моего отца из ануб\'арского узилища.', 'Принеси мне фрагменты ключа!', NULL, NULL, 'Фрагмент ключа Анок\'ры', 'Фрагмент ключа Тивакса', 'Фрагмент ключа Синока', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12065, 'Фокусы на взморье', 'Силы охотников на магов проявляют активность на Сверкающем взморье, к югу от Садов Лунного Покоя. Я так полагаю, что ты обнаружишь на берегу хорошо охраняемый фокус и командира, отвечающего там за все.$B$BНесомненно, у него или у нее будет при себе некое контролирующее устройство. Раздобудь его и используй на средоточии.$B$BЕсли получится, мы сможем получить дополнительную информацию о том, что они там на самом деле замышляют.', 'Добудьте кольцо управления средоточием силовых линий и воспользуйтесь им для получения информации о средоточии силовых линий на Сверкающем взморье.Затем вернитесь к проекции верховного мага Модеры в Покое Звезд.', 'Как необычно, что информация была запечатлена в тебя посредством магии!$B$BТак, значит, мы теперь знаем не только то, что они перенаправили поток энергии, идущий из Садов Лунного Покоя, но и то, что эта энергия намеренно изменена определенным образом. Но что же они намерены делать со всей этой магией?$B$BМне совсем не нравится, к чему это все ведет, $N.', NULL, NULL, NULL, 'Информация о средоточии силовых линий получена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12066, 'Фокусы на взморье', 'Силы охотников на магов проявляют активность на Сверкающем взморье, к югу от Садов Лунного Покоя. Я так полагаю, что ты обнаружишь на берегу хорошо охраняемый фокус и командира, отвечающего там за все.$B$BНесомненно, у него или у нее будет при себе некое контролирующее устройство. Раздобудь его и используй на средоточии.$B$BЕсли получится, мы сможем получить дополнительную информацию о том, что они там на самом деле замышляют.', 'Добудьте кольцо управления средоточием силовых линий и воспользуйтесь им для получения информации о средоточии силовых линий на Сверкающем взморье.Затем вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара.', 'Как необычно, что информация была запечатлена в тебя посредством магии!$B$BТак, значит, мы теперь знаем не только то, что они перенаправили поток энергии, идущий из Садов Лунного Покоя, но и то, что эта энергия намеренно изменена определенным образом. Но что же они намерены делать со всей этой магией?$B$BМне совсем не нравится, к чему это все ведет, $N.', NULL, NULL, NULL, 'Информация о средоточии силовых линий получена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12067, 'Письмо домой', 'Вы находите письмо, упрятанное под подкладку еe одеяния. Оно гласит:$B$B\"Отец,$B$BПрости меня за то, что я исчезла. Если ты читаешь это письмо – значит, я мертва.$B$BМеня заставили работать на армию Малигоса угрозами, что нашу семью убьют, если я этого не сделаю. Мне так стыдно!$B$BЕсли можешь сделать хоть что-нибудь, чтобы сражаться с ними, не думай обо мне. Я их одурачила и наношу им вред изнутри.$B$BЯ люблю тебя, папа!$B$BЭм\"$B$BЭто письмо нужно непременно показать командиру Сайа Лазурная Сталь!', 'Доставьте письмо капитана Малин командиру Сайе Лазурной Стали в Покой Звезд.', 'О, нет!.. И мы послали тебя туда, чтобы убить ее, ведь так?<Командующий сокрушенно качает головой и вздыхает.>$B$BМне очень жаль. Я прослежу, чтобы письмо доставили ее отцу, верховному магу Малину в Штормград, немедленно. Не волнуйся, о тебе не будет сказано ни слова... твоей вины в случившемся нет.$B$BПостарайся не думать об этом. Ты никак не мог узнать, $N.', 'Письмо? Мне?$B$B<Командир секунду-другую изучает ваше лицо.>$B$BПолагаю, что нет… должно быть, снова плохие новости…', NULL, NULL, 'Письмо капитана Мэлина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12068, 'Голоса прошлого', '$gДракуру кладет Око пророка себе на лоб, а Сердце древних – на грудь.>$B$BМы уже почти достигли цели, дружок!$B$BОсталось только найти скрижали Драккари. Никто не знает, когда они были написаны, и что именно они гласят, но око и сердце Дракуру помогут расшифровать послание. А лежат они глубоко в склепе Дракил\'джин, что к востоку отсюда. $B$BКак только найдешь скрижали, забери священный настой у оракулов и заступников. С его помощью ты сможешь призвать меня к себе. Не переживай – они будут счастливы умереть во имя благого дела.', 'Дракуру просит вас собрать скрижали Драккари в Руинах Дракил\'джин и отобрать 5 священных настоев у оракулов и заступников Драккари. Затем вам надо будет выпить эликсир Дракуру возле жаровни в руинах, чтобы призвать его дух.', 'Получилось, Профессия!$B$BТеперь у нас есть все компоненты для проведения очищающего ритуала.', 'Рад видеть тебя, $N .$B$BЗначит, ты нашел таблички?', NULL, NULL, 'Скрижали Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12069, 'Возвращение верховного вождя', '$gБанток протягивает вам ключ от тюрьмы.>$B$BТоропись, $N! Возьми этот ключ и выпусти моего отца из ануб\'арской темницы! Когда он будет свободен, помоги ему уничтожить предводителя Ануб\'ара, короля подземелий Ануб\'ет\'кана. Когда король подземелий будет повержен, отруби кусок его хитинового панциря и отнеси его, как трофей, в Молот Агмара. Пусть Агмар узрит мощь верховного вождя!', 'Освободите верховного вождя Ледяную Пыль с помощью ключа от ануб\'арской темницы и помогите ему одолеть короля подземелий Ануб\'ет\'кана.Добудьте кусок панциря Ануб\'ет\'кана и вернитесь с ним к командиру Агмару в Молоте Агмара в Драконьем Погосте.', 'Ты отважный $C, $N. Ты оказал Орде большую услугу тем, что спас верховного вождя.', 'В чем дело, $N? Я очень занят!', NULL, NULL, 'Кусок панциря Ануб\'ет\'кана', 'Ключ от Ануб\'арской темницы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12070, 'Второе дыхание', 'Дети железа подчиняют своими рунами моих братьев и посылают их на штурм Тор Модана. Как бы я хотел избежать братоубийства... но у нас нет другого выхода.$B$BМоим великанам не выстоять против них.$B$BЯ зарядил этот осколок земли великой силой, которая поможет нашим союзникам. Отнеси его на поле боя в Каменистые холмы и помоги моим братьям.$B$BУбивай любого железного дворфа, что осмелится встать у тебя на пути.', 'Воспользуйтесь осколком земли, чтобы излечить великанов с Седых холмов, сражающихся в Каменистых холмах, убейте всех железных дворфов, что осмелятся встать у вас на пути, и вернитесь к Куруну на холм, возвышающийся над Тор Моданом.', 'Спасибо тебе за то, что ты придал смелости моим союзникам. Но все равно, мы должны найти способ выиграть эту битву до того, как наши силы иссякнут.', 'Ты помог моим великанам?', NULL, NULL, 'Исцелено великанов с Седых холмов', 'Убито мстителей из клана Железной Руны', 'Осколок земли', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12071, 'Ударим с воздуха!', 'Они уже видели, какова мощь Орды на земле, теперь пусть почувствуют, какова она в небе! Я хочу, чтобы ты немедленно $gдоложился:доложилась: Вальноку Ветрояру. Он здесь, в Молоте Агмара.$B$BВальноку уже даны указания насчет твоей миссии, он ждет тебя.', 'Поговорите с Вальноком Ветрояром в Молоте Агмара.', '<Вальнок отдает вам честь.>$B$BТак это ты, стало быть, герой нашего времени, да?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12072, 'Будь прокляты эти чумные звери!', 'Без сомнения, ты $gвидел:видела: армию ануб\'арских гнилостных зверей, которых создают в деревне Ледяной Пыли. У ануб\'арцев есть планы послать этих монстров против наших солдат у Врат Гнева. Этого не должно произойти!$B$BОтправляйся на запад, в деревню Ледяной Пыли, с этим световым ружьем и воспользуйся им, чтобы вызвать одного из моих боевых наездников. Заберись к нему на спину и прикажи уничтожить гнилостных зверей, до которых нельзя дотянуться с земли.$B$BКогда достаточно проредишь их воздушные силы, возвращайся ко мне за наградой!', 'С помощью сигнального ружья Вальнока вызовите в деревню Ледяной Пыли кор\'кронскую боевую виверну. Воспользовавшись ею, убейте 25 ануб\'арских гнилостных зверей!Если выполните задание, возвращайтесь к Вальноку Ветрояру в Молот Агмара.', '<Валнок отдает вам честь.>$B$BТеперь мы сокрушили их и с воздуха! Может быть, вскоре тебя призовут в Ангратар, герой!', 'Помни, что боевые наездники обучены сражаться только в деревне Ледяной Пыли. Попробуй полететь на них куда-нибудь еще – и они просто сбросят тебя.', NULL, NULL, 'Ануб\'арский гнилостный зверь убито', 'Сигнальное ружье Вальнока', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12073, 'Куй железо, пока горячо', 'Солдаты Альянса – не единственные наши противники в Седых холмах. Все восточное побережье удерживают железные дворфы, а Тор Модан на северо-востоке захвачен каменными великанами.$B$BНо умелый воин никогда не упустит возможность воспользоваться слабостью врага. Железные дворфы ослаблены стычками в Тор Модане, и потому наиболее уязвимы. Не давай им пощады, $N. Убивай каждого дворфа, ставшего у тебя на пути. $B$BПусть сыны железа научатся бояться Орды.', 'Убейте 10 любых железных дворфов, охраняющих Тор Модан, после чего доложите разведчику Вор\'такху из Лагеря Уанква об успешном выполнении его поручения.', '<Разведчик Вор\'такх улыбается.>$B$BЗначит, Тор Модан вот-вот падет?$B$BПревосходно. Вскоре мы начнем наступление на Дун Аргол.', NULL, NULL, NULL, 'Убито железных дворфов-защитников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12074, 'Удобный союзник', 'Древнюю столицу железных дворфов, Тор Модан, что далеко на северо-востоке отсюда, осадили войска таинственных каменных и земляных великанов.$B$BМеня мало интересуют разборки между детьми $Nв, но Орде не стоит упускать шанс сокрушить железных дворфов силами других рас.$B$BОтправляйся в Тор Модан и поговори с этим \'Куруном\', возглавляющим армию великанов и служителей земли. Расскажи ему о наших интересах и предложи свою помощь в войне против железных дворфов.', 'Поговорите с Куруном, который стоит на вершине холма рядом с Тор Моданом.', '<Вы называете себя.>$B$BТак значит, у нас с вами есть общий враг – сыновья железа?$B$BМои войска осадили город железных дворфов, но своими силами нам не взломать их оборону. Не желаешь ли ты нам помочь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12075, 'Образец каменной плоти', 'Холодно тут, да, $r?$B$BКо\'чар отказался со мной встречаться. Похоже, у него голова сейчас другим занята. Я про йормунгаров, кишащих в пещере внизу. Может быть, ты поможешь мне убедить Ко\'чара, что я хороший парень?$B$BЯ видел великана, которого черви жрали у входа в пещеру к северу отсюда... Ума не приложу, как червям удалось его так легко одолеть. Принеси мне образец ткани из раны этого великана.', 'Возьмите образец каменной плоти с тела ледяного великана у входа в пещеру в ущелье Порочных Кристаллов, к северу от места, где стоит Зорт. Выполнив это задание, вернитесь к Зорту, ожидающему вас у центра каньона.', 'Отличный образец. Спасибо, $C.', 'Так ты уже принес мне образец? Рад, что мороз не забрал тебя.', NULL, NULL, 'Образец каменной плоти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12076, 'Грязное дело', 'С первого взгляда могу сказать, что принесенный тобой образец носит следы воздействия чьей-то едкой слюны. Естественно будет предположить, что вещество, с помощью которого эти змеи прокладывают себе путь в земле, является в то же время превосходным оружием против ледяных великанов! Возьми этот скребок и вступи в схватку с несколькими змеями. Когда они плюнут в тебя, соскреби слюну с помощью скребка и принеси мне.$B$BМне нужна как минимум пара образцов – я собираюсь использовать эту слюну как основу для эликсира.', 'Соберите два фиала едкой слюны йормунгаров с помощью скребка. Выполнив задачу, принесите сосуды Зорту в ущелье Порочных Кристаллов.', 'Свеженькая! Минутку, сейчас смешаю ее с остальными компонентами…', 'Посмотри-ка, $R, кажется, у тебя еще на плече слюна осталась. Будь осторожнее, а то она прожжет твои доспехи!', NULL, NULL, 'Фиал едкой слюны', 'Скребок Зорта', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12077, 'Употреблять дважды в день', 'Этот эликсир должен защищать от их плевков. Предложи его Ко\'чару от моего имени, ладно? И скажи, что у меня этого добра еще много – если только он согласится оказать мне ответную услугу.', 'Предложите приготовленный Зортом эликсир Ко\'чару Неуязвимому.', 'Скажу прямо, малявка: я этой микстуре не доверяю и пользоваться ею не стану. Возьми ее себе… если ты больше моего доверяешь этому зеленому коротышке. Может, она тебе пригодится.', 'Думаю, этот коротышка хочет, чтобы мы сражались за него… Я удивлен, если ты не заметил.', NULL, NULL, 'Охранный эликсир Зорта (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12078, 'Червячный наездник', 'Так и быть. Если великаны не придут к нам на помощь, мы можем использовать этих червей. Они наверняка есть в пещере, вместе с маткой. Возьми эту коробку, поймай 3 штуки и принеси мне.$B$BКогда дипломатия терпит неудачу, отличной альтернативой становится порабощение.', 'Отправляйтесь в пещеры в ущелье Порочных кристаллов и заманите 3 порождения йормунгаров в крепкие ящики. Не забудьте собрать ящики, когда порождения йормунгаров окажутся в них!Принесите пойманные порождения йормунгаров Зорту в ущелье Порочных кристаллов.', 'Эти вполне подойдут. Может быть, когда я выращу этих червячков до нормальных размеров, то отнесу их обратно и лично представлю их великанам.$B$BПо мне, так они просто бесполезные кучи камней.', 'Ты вернулся! Удалось поймать червей? Мне нужно отсюда выбраться… Я уверен, Ко\'чар пытался достать меня несколько минут назад.', NULL, NULL, 'Пойманное порождение йормунгара', 'Прочные ящики', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12079, 'Излюбленное место червяков', 'Привет, $gмалец:малявка:. Не знаю, что за безумие привело тебя в пещеру порочных кристаллов, но – добро пожаловать ко мне.$B$BЭти ледяные черви… эти йормунгары, они повадились есть моих собратьев. Сомневаюсь, что в это жестокое время ты найдешь мне подобных хоть сколько-нибудь дружелюбными, но если ты здесь для того, чтобы помочь мне с червями, я буду благосклонен к тебе.$B$BЕсли мы хотим отвоевать эту пещеру, для начала нужно очистить каньон от воспитателей йормунгаров. Присоединяйся, $r!', 'Отправляйтесь в пещеру у северной оконечности ущелья Порочных кристаллов и убейте по поручению Ко\'чара Неуязвимого 8 йормунгаров-трутней Ледяного Сердца.', 'Приятное зрелище хорошей бойни.', NULL, NULL, NULL, 'Йормунгар - трутень Ледяного Сердца убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12080, 'Вот это червяк!', 'Там, в пещерах, живет матка йормунгаров. Мы зовем ее Грохотуньей – это имя дал ей один искатель приключений из Чумных земель. Я видел ее только мельком, отражая их первоначальный натиск. Она так огромна, что даже у меня пробежал мороз по жилам. Эта пещера не будет нашей, пока тут обитает она!$B$BСобери друзей и покончи с ней.', 'Войдите в пещеру Ледяного Сердца и убейте Грохотунью. Не забудьте использовать защитный эликсир Зорта, чтобы спастись от едких плевков йормунгаров – если, конечно, этот эликсир у вас еще есть.Выполнив задачу, вернитесь к Ко\'чару Неуязвимому в ущелье Порочных кристаллов.', 'Значит, она мертва. Как тому и следует быть. Похоже, ты действительно благороднее, чем те коротышки.$B$BЗа северным каньоном ты найдешь леса Поющих кристаллов. Это проклятое место, $R, опасное место. Если тебе нужно туда, будь осторожнее.$B$BВозьми за труды вот это, малявка, и ступай своей дорогой. Счастливого пути!', NULL, NULL, NULL, 'Грохотунья убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12081, 'Гаврок', 'Если бы не ты, нам не удалось бы переломить ход сражения за Тор Модан в нашу пользу. Этот древний город давно уже стал полем битвы для сил земли и камня, и нам остается лишь надеяться, что на сей раз наша победа была окончательной.$B$BНо железные дворфы все еще пользуются своей силой, чтобы порабощать моих братьев. Гаврок пытается отыскать способ освободить рунических великанов. Ты найдешь его на маленьком скоплении островов посреди Побережья Восточного Ветра на юге. Это место зовется Руины Тетиса. Поспеши!', 'Поговорите с Гавроком в Руинах Тетиса.', 'Знаю, Курун очень благодарен тебе за помощь. Взятие Тор Модана – это великая победа, но она ни на шаг не приблизила нас к освобождению наших братьев.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12082, 'Дун-да-Дун-та!', 'Слушай, $gмалыш:малышка: тут тебе не площадка для игр.$B$BЯ собираюсь уносить отсюда ноги. Держись рядом со мной, и я выведу нас на волю.', 'Сопроводите Харрисона по пути из руин Дракил\'джин, после чего поговорите с Харкором в лагере Харкора.', 'Говорят, ты выбрался из переделки вместе с нашим старым-добрым дружком?$B$BПожалуй, это само по себе может считаться наградой, но тебе повезло – я сегодня щедрый.', NULL, NULL, NULL, 'Харрисон сопроводил вас в безопасное место.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12083, 'В лесах', 'Я уверена, что существует еще несколько средоточий силовых линий, и каждое из них каким-то образом перенаправляет энергию. Но что они делают со всей этой энергией, до сих пор доподлинно не известно.$B$BЯ подозреваю, что еще одно средоточие можно найти в глубине Лоталорского редколесья на юго-востоке. Тебе снова понадобится отыскать главного и отобрать у него управляющее устройство – для каждого средоточия оно свое.$B$BБудь осторожнее, $N, эти леса очень опасны!', 'Добудьте амулет управления средоточием силовых линий и используйте его для получения сведений о средоточии силовых линий в Лоталорском редколесье.После этого вернитесь к проекции верховного мага Модеры в Покое Звезд.', 'Они увеличивают с их помощью свою собственную силу? Не может быть! Охотники на магов не настолько могущественны.$B$BЭто, должно быть, означает, что они перенаправляют энергию силовых линий куда-то еще!$B$BЕсли мы хотим найти и остановить их, нам потребуются дополнительные сведения!', NULL, NULL, NULL, 'Информация о средоточии силовых линий получена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12084, 'В лесах', 'Я уверен, что существует еще несколько средоточий силовых линий, и каждое из них каким-то образом перенаправляет энергию. Но что они делают со всей этой энергией, до сих пор доподлинно не известно.$B$BЯ подозреваю, что еще одно средоточие можно найти в глубине Лоталорского редколесья на юге. Тебе снова понадобится отыскать главного и отобрать у него управляющее устройство – для каждого средоточия оно свое.$B$BПоторопись, $C! У меня такое ощущение, что время на исходе!', 'Добудьте амулет управления средоточием силовых линий и воспользуйтесь им для получения сведений от средоточия силовых линий в Лоталорском редколесье.Затем вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара.', 'Они увеличивают с их помощью свою собственную силу? Не может быть! Охотники на магов не настолько могущественны.$B$BЭто, должно быть, означает, что они перенаправляют энергию силовых линий куда-то еще!$B$BЕсли мы хотим найти и остановить их, нам потребуются дополнительные сведения!', NULL, NULL, NULL, 'Информация о средоточии силовых линий получена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12085, 'Письмо домой', 'Вы находите письмо, упрятанное под подкладку его одеяния. Оно гласит:$B$B\"Дейно,$B$BТа\'зинни просит прощения за исчезновение. Если ты это читаешь, то я мертв.$B$BМеня заставили работать на армию Малигоса угрозами, что иначе мою семью убьют. Та\'зинни не мог допустить такое!$B$BНе беспокойся за меня, главное – береги детишек. Я дурю врагов и наношу им вред изнутри.$B$BЯ люблю тебя, сестренка!$B$BТа\'зинни\"$B$BЭто письмо нужно непременно показать командиру Агмару!', 'Отнесите письмо лейтенанта Та\'зинни командиру Агмару в Молот Агмара.', 'Буагагага… ух ты, как трогательно!$B$B<В утробном смехе командира явно чувствуется снисходительность.>$B$BНу, что я говорил? Предатели! Правда, Дейно я знал когда-то. По крайней мере она троллиха с чувством чести!$B$BЯ позабочусь о том, чтобы она узнала, что случилось с ее братцем. Даже забуду сказать ей, что это ты его убил.$B$B<Агмар пристально и оценивающе смотрит на вас.>$B$BНо теперь, $C, ты у меня в руках!', 'Это еще что такое?! Думаешь, можешь просто так письмецо отправить?$B$BВся почта сначала проходит через меня. Среди нас есть шпионы и предатели!$B$B<Командир окидывает вас таким взором, что вам становится интересно, не собирается ли он прибить вас на месте.>$B$BЛадно, выкладывай, да поживее. Но если мне не понравится то, что я прочитаю, я скормлю тебя своим воргам.$B$B<Агмар скалится, видя, как Гар\'мак и Лак\'тук поворачиваются к вам и смотрят на вас, как на свою следующую трапезу.>', NULL, NULL, 'Письмо лейтенанта Та\'зинни (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12086, 'Сын Каркута', 'Человек, которого ты ищешь, ушел далеко на восток, к месту на побережье, называемому Стоянка Смерти, за Уну\'пе.$B$BСоблюдай осторожность, если собираешься идти искать его, $N. На нем – знак Каркута... того, кто наблюдает за мертвыми.', 'Идите на восток к Стоянке Смерти, находящейся сразу за Уну\'пе.', 'Тассариан? Да, он был здесь... и что? У нас тут прямо сейчас есть проблемы куда важнее, друг мой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12087, 'Немного помочь? DEPRECATED', 'Нас послали сюда, чтобы захватить Воющий зиккурат к северу отсюда. Мы уже не чаяли вернуться живыми… половину отряда потеряли!$B$BТам был Тассариан и другие… в общем, он им чем-то не понравился.$B$BОн ушел сегодня утром… возможно, отправился к зиккурату в одиночку. Но сейчас у нас есть более неотложные проблемы. Плеть все ближе к лагерю, и с ними надо разобраться – немедленно!', 'Убейте 8 защитников зиккурата по просьбе капрала Венна со Стоянки Смерти.', '', NULL, NULL, NULL, 'Защитник зиккурата убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12088, 'Тассариан, рыцарь Смерти', 'Ну что ж, $N, ты $gпомог:помогла: нам, будет только справедливо, если мы поможем тебе.$B$BТы ищешь Тассариана? Он исчез сегодня утром. Мы думаем, он отправился на север, к Стонущему зиккурату. Если бы нам не доводилось сражаться плечом к плечу, мы бы даже подумали, что он предатель...$B$BВидишь ли, он – рыцарь Смерти. Я знаю, что они на нашей стороне, и все такое... но еще не так давно они были слугами Артаса.$B$BКто угодно, но только не Тассариан. Он славный малый. Ступай в Стонущий зиккурат, проверь, все ли с ним в порядке.', 'Отыщите Тассариана внутри Стонущего зиккурата, к северу от Стоянки Смерти.', 'Лерисса… Лерисса меня ищет? Помоги мне, $N. Нужно закончить это, пока она не пострадала.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12089, 'Разыскивается: магистр Кельдонус!', 'По велению командира Агмара приказано выследить магистра Кельдонуса.$B$BОн обвиняется в предательстве. На данный момент он жив.$B$BМагистра Кельдонуса, бывшего мага-командира Молота Агмара, надлежит убить на месте во имя Орды.$B$BВ последний раз его видели, когда он направлялся на юго-запад, в сторону садов Лунного Покоя, чтобы присоединиться к синим драконам в их борьбе против магии.$B$BСледует соблюдать осторожность: Кельдонус весьма могущественный маг. В одиночку в бой не ввязываться!$B$BНаграду за его убийство можно получить у капитана Горта в Молоте Агмара.', 'Убейте магистра Кельдонуса и вернитесь к капитану Горту в Молот Агмара в Драконьем Погосте.', 'Это был не первый из колдунишек, которые нас предали. И, боюсь, не последний. Жаль, жаль… Это был один из лучших наших магов. Умел творить такие заклинания, что аж слюнки текли и сердце прыгало от радости…$B$BТьфу ты!', NULL, NULL, NULL, 'Магистр Кельдонус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12090, 'Разыскивается: Гигантавр', 'Указ командира Агмара!$B$BПриговаривается: Гигантавр$B$BПреступления: нападения на войска Орды; \"гнусность характера\"$B$BСтатус: жив$B$BПовелитель магнатавров Гигантавр разыскивается в связи с совершением многочисленных нападений на воинов орды и ее сооружения на Драконьем Погосте.$B$BВ последний раз Гигантавра видели бродящим по лесам и дорогам к югу и юго-востоку от Молота Агмара.$B$BГигантавр является хорошо вооруженным и чрезвычайно опасным противником. Не пытайтесь справиться с ним в одиночку!$B$BВознаграждения выплачиваются капитаном Гортом в Молоте Агмара.', 'Убейте Гигантавра и приходите за вознаграждением к капитану Горту в Молоте Агмара на Драконьем Погосте.', 'Тебе удалось достать этого проклятого кобыльего сына, а? Ну, что ж, одной неприятностью для наших солдат в этой мерзлой пустыне меньше.', NULL, NULL, NULL, 'Гигантавр убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12091, 'Разыскивается: Коготь Ужаса', 'Указ командира Агмара!$B$BПриговаривается: Коготь Ужаса$B$BПреступление: нападения на Орду.$B$BСтатус: жив$B$BКогтежут разыскивается за многократные нападения на караваны Орды, идущие в Ядозлобь и из Ядозлоби.$B$BОбиталище Когтя Ужаса – на утесе, возвышающемся над Рубиновым святилищем драконов, к востоку от Молота Агмара. Приближайтесь со всей возможной осторожностью! Не пытайтесь справиться с ним в одиночку!$B$BВознаграждения выплачиваются капитаном Гортом в Молоте Агмара.', 'Убейте Когтя Ужаса и вернитесь за вознаграждением к капитану Горту в Молот Агмара на Драконьем Погосте.', 'Очень вовремя! Наконец хоть кто-то положил конец череде убийств этого гнусного зверя! Отличная работа, Профессия.', NULL, NULL, NULL, 'Коготь Ужаса убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12092, 'Усиление древняков', 'То, что натворили синие драконы, затрагивает не только твою расу. Затронуло оно и древняков Лоталорских лесов.$B$BНекоторые оказались подвергнуты порче – остерегайся их во что бы то ни стало! – но остальных, их большинство, еще можно спасти. Однако лесные древни, кажется, оказались невосприимчивы к магии, текущей по этим землям, и волшебным змеям, пришедшим вместе с ней.$B$BПопроси у древней их кору и скорми ее древнякам. Надеюсь, этого будет достаточно, чтобы их спасти.', 'Воспользуйтесь корой древня для усиления 3 древ Лоталора, а затем вернитесь к Сарендриане в Покой Звезд.', 'Спасибо, $R! Мы и так уже потеряли слишком много. Благодаря тебе мы не потеряем самых величественных детей Нордскола.$B$BСкоро я уйду говорить с древняками, спасенными тобой, чтобы узнать, помогут ли они нам в нашей беде.', NULL, NULL, NULL, 'Усилено древ Лоталора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12093, 'Руны порабощения', 'Несмотря на то, что Курун выступил против Тор Модана, железные дворфы продолжают порабощать наших братьев. Они призывают их из земли, сковывают рунами и принуждают их воевать против детей камня.$B$BПовсюду вдоль Побережья Восточного Ветра бродят подневольные великаны, принуждаемые отправиться на поля сражений. $B$BНайди четыре руны порабощения и заставь проклятых надзирателей ответить за преступления против моих братьев, убив четырех руноплетов, создавших эти руны. Без надзирателей эти руны потеряют силу.', 'Гаврок с Руин Тетиса просит вас отключить четыре руны порабощения, убив надзирателя Дюрваля, надзирателя Коргана, надзирателя Лочли и надзирателя Брунона.', 'Хорошо. Теперь нам надо действовать быстро, пока сыны железа не осознали, что их руны не действуют.', NULL, NULL, NULL, 'Надзиратель Дюрваль убито', 'Надзиратель Корган убито', 'Надзиратель Лочли убито', 'Надзиратель Брунон убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12094, 'Спящая сила', 'Пока руны подчинения бездействуют, у нас есть шанс освободить рунических великанов.$B$BЯ дам тебе кусок камня, который был частью меня с самого рождения. Если его правильно зарядить, ты сможешь освободить пленных великанов.$B$BМеста скопления силы отмечены тремя древними камнями. Два из них стоят между Путем Железа и лесной опушкой, отмечая пересечение силовых линий, как называет это место твой народ. А третий камень возвышается на южном краю острова, среди руин. Заряди мой камень у этих монолитов и возвращайся ко мне.', 'Зарядите осколок Гаврока у первого, второго и третьего древних камней, после чего вернитесь к Гавроку в Руины Тетиса.', 'Да, я чувствую силу, исходящую от этого камня. Надеюсь, ее будет достаточно для того, чтобы разрушить магию рун.', 'Нашел ли ты древние монолиты?', NULL, NULL, 'Получена энергия первого камня', 'Получена энергия второго камня', 'Получена энергия третьего камня', 'Осколок Гаврока (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12095, 'В Драконью Погибель', 'К востоку отсюда, в самом сердце Драконьего Погоста, есть равнина, где нет ничего – только снег и кости драконов. Плеть устроила в центре тундры многочисленные лагеря, и теперь создает ледяных змеев, которых насылает на наши войска у Врат Гнева. С большинством из этих змеев без труда справляется Рокхан и его охотники на драконов, но вот один из них доставляет нам немало хлопот.$B$BСтупай на северо-восток и найди Рокхана в Драконьей Погибели. Помоги ему и его воинам убить Сарастру, и тебя щедро наградят!', 'Поговорите с Рокханом в Драконьей Погибели в Драконьем Погосте.', 'И с чего это тебе взбрело в голову, что тебе удастся то, что не по зубам Рокхану, а?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12096, 'Усиление древняков', 'На древняков Лоталорских лесов к югу отсюда наводят порчу волшебные змеи... змеи, что восстали из земли!$B$BТе, кто уже подвергнуты порче, с теми мы ничего не можем поделать, но остальных – а их большинство – еще можно спасти. К счастью, лесные древни, кажется, оказались невосприимчивы к магии, текущей по этим землям, и волшебным змеям, пришедшим вместе с ней.$B$BПопроси у древней их кору и скорми ее древнякам. Это усилит их.$B$BА мне дай заняться своими делами. Мне нужно приглядывать за этими аптекарями!', 'Воспользуйтесь корой древня для усиления 3 древ Лоталора, а затем вернитесь к хранителю земли Грифу в Молот Агмара.', 'Благодарю тебя, $C.$B$BКак только я закончу слежку за этими отвратительными аптекарями и пойму, что они замышляют, я направлюсь в леса, чтобы попробовать убедить древняков присоединиться к нам.$B$BИли, если ничего не выйдет, попробую уговорить их хотя бы не нападать на тех, кто их спас!', NULL, NULL, NULL, 'Усилено древ Лоталора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12097, 'Сарастра, бич Севера', 'Мои охотники или померли, или от холода окочурились, $N. Только ты и твои друзья, кого с собой приведешь, больше рассчитывать не на кого. Все еще хочешь этим дельцем заняться? Скажи только слово – и я еще раз позову дракона, да.$B$BЕсли убьешь его, возьми его ледяное сердце, отнеси в Молот Агмара и преподнеси Горту. Он тебя, $gдружок:сестренка:, хорошо наградит – это как пить дать.', 'Поговорите с Рокханом, чтобы призвать ледяного змея Сарастру.Убейте змея и отнесите ледяное сердце Сарастры капитану Горту в Молот Агмара.', 'ХА! Тебе удалось! Воины у Врат Гнева в долгу теперь перед тобой, $N! Теперь некоторые из них хоть на денек подольше проживут.', '<Горт изумленно поднимает брови.>$B$BУже вернулась, так быстро?', NULL, NULL, 'Ледяное сердце Сарастры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12098, 'Поиски в деревне Инду\'ле', 'Я уверена, что следующее средоточие силовой линии ты обнаружишь где-нибудь в развалинах деревни Инду\'ле к юго-востоку отсюда. Проблема в том, что у меня нет совершенно никаких сведений о том, что оно там.$B$BМне нужно, чтобы ты $gотправился:отправилась: туда и $gобследовал:обследовала: деревню и окрестности в поисках признаков средоточия или охотников на магов и их командира.$B$BИщи даже в озере, если придется!', 'Найдите командира охотников на магов в деревне Инду\'ле либо на озере Инду\'ле.', 'Вы нашли труп командира охотников на магов.$B$BСудя по его внешнему виду и состоянию окружающих, вряд ли они утонули. Скорее всего, призывая фокус, они не ожидали, что из разломов на дне озера восстанут элементали и набросятся на них.$B$BПохоже, охотники на магов сами себя погубили.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12099, 'Долгожданная свобода', 'Надеюсь, этот заряженный камень сможет рассеять магию рун, пленившую моих братьев.$B$BВозьми его с собой и отправляйся на поиски рунических великанов, что бродят на востоке вдоль Побережья Восточного Ветра. Освободи силу, заключенную в камне, и проследи за великанами. $B$BЕсли все пойдет, как задумано, они придут в себя и перестанут подчиняться железным дворфам. Но если камень не сработает, великаны набросятся на тебя. Даже ослабленные магией, они очень опасны. Но другого пути нет – не можем же мы обречь их на вечное рабство!', 'Воспользуйтесь Руноломом Гаврока, чтобы освободить четырех рунических великанов, после чего вернитесь к Гавроку в Руины Тетиса.', 'Значит, этот метод срабатывает, но не всегда? Хотелось бы мне не полагаться на удачу, но, во всяком случае, я чувствую, что мы на верном пути. Без твоей помощи у детей камня не было бы ни малейшей надежды. Если тебе удастся узнать еще что-нибудь о планах железных дворфов, позови нас, $N, и мы услышим.', 'Ты смог освободить моих братьев?', NULL, NULL, 'Освобождено рунических великанов', 'Рунолом Гаврока', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12100, 'Сдерживание гнили', 'Рука об руку с Плетью идут смерть и болезнь. Мы часто упускаем из виду, что фауна зараженных Плетью районов в ужасном состоянии и сильно повреждена гнилью и заразой.$B$BДля многих местных животных уже слишком поздно. Терзающая зараза, которую распространяет Плеть, уже поразила их, и теперь эти звери гниют и больны бешенством.$B$BПридется тебе отправиться на запад, к Провалу Наржуна, и уничтожить пораженных животных. Поищи на их телах неповрежденный орган – он нужен нам для изготовления вакцины.', 'По заданию Соара Ярости Ястреба из Молота Агмара на Драконьем Погосте убейте 15 зараженных тварей и добудьте орган сопротивления гниению.', 'Мне больно, что животных приходится убивать, но это дело, которое должно быть сделано. А теперь мы приступим к следующему этапу – вакцинации.', 'Убей этих животных, дабы пресечь распространение заразы, и принеси мне орган сопротивления гниению.', NULL, NULL, 'Зараженная тварь убито', 'Орган сопротивления гниению', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12101, 'Добрый доктор...', 'Наши союзники-Отрекшиеся послали сюда своих лучших аптекарей, чтобы те помогли нам уничтожить силы Плети у Врат Гнева. Один из них, доктор Синтар Злобениус, особо сведущ в гнили Плети и методах ее распространения. Я раньше немало работал с ним над изготовлением вакцины для фауны. С тех пор он ждет орган.$B$BОтнеси этот орган сопротивления гниению доктору Злобениусу и скажи ему, что это от меня. А уж он даст тебе следующее задание.', 'Отнесите орган сопротивления гниению доктору Синтару Злобениусу в Молот Агмара.', 'Так этому бычаре действительно удалось раздобыть орган сопротивления гниению? Тысяча проклятий... я был уверен, что это займет его неповоротливый ум как минимум на ближайшие несколько сотен лет.$B$BЛадно, давай сюда, юноша. У меня и без твоих мелких нужд своих забот хватает.', 'И что на этот раз?', NULL, NULL, 'Орган сопротивления гниению (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12102, 'В поисках рубиновой сирени', 'Как это неожиданно и хорошо, что Рубиновое святилище драконов находится совсем рядом, на восток отсюда. Там ты и найдешь цветок, который называют рубиновой сиренью. Это животворное растение – единственное, что мне нужно, чтобы изготовить вакцину для неоскверненных животных в этих землях.$B$BОтправляйся на восток и поищи в Рубиновом святилище драконов эту сирень.$B$BИмей в виду только одно: это святилище драконов, как и все остальные, занято силами Плети. Будь $gосторожен:осторожна:. Мы не хотели бы, чтобы тебя сожрал тлеющий змей.$B$B<Синтар смеется.:', 'Принесите 1 цветок рубиновой сирени доктору Синтару Злобениусу в Молот Агмара на Драконьем Погосте.', 'Ну, было не так уж трудно, правда же?$B$BА теперь погоди минутку, дай мне приготовить вакцину.', 'Тебе удалось отыскать рубиновую сирень?', NULL, NULL, 'Рубиновая сирень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12104, 'Вакцина для Соара', '<Доктор Злобениус передает вам сосуд, наполненный мутной жидкостью.>$B$BНу, вот $r. Отнеси это бычаре и скажи, что все долги выплачены. Мы с ним официально в расчете.$B$BА теперь иди отсюда, пока я Дженнингса на тебя не напустил.', 'Отнесите вакцину Синтара Соару Ярости Ястреба в Молот Агмара.', '<Соар поднимает флакон и изучает на свету его содержимое.>$B$BОсталось выяснить только одно.', 'Ты получил вакцину?', NULL, NULL, 'Вакцина Синтара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12105, 'Погружение во мрак', 'Этот дневник вел житель Среброречья по имени Михаил. В нем описывается появление некоей темной секты, называющей себя \"Культ Волка\".$B$BЖители деревни с подозрением отнеслись к новой секте, но потом симпатии обитателей деревни резко изменились.$B$BНастороженный столь внезапными переменами, Михаил отправил свою старшую дочь Сашу подальше от Среброречья. Сам же он остался в деревне, надеясь переубедить своих соплеменников.$B$BВ последней записи дневника говорится о городском собрании, на котором должны были обсуждаться странные явления на Руднике Полого Камня.', 'Отнесите дневник Михаила лейтенанту Думонту в Приют Янтарной Сосны.', 'Так я и знал, что в этой деревне что-то нечисто.$B$BЯ отправил отряд к Руднику Полого Камня; может быть, им удастся что-нибудь разузнать.', 'Что это у тебя в руках?', NULL, NULL, 'Дневник Михаила (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12106, 'Поиски в деревне Инду\'ле', 'Я уверен, что следующее средоточие силовой линии ты обнаружишь где-нибудь в развалинах деревни Инду\'ле к юго-востоку отсюда. Проблема в том, что у меня нет совершенно никаких сведений о том, что оно там.$B$BМне нужно, чтобы ты $gотправился:отправилась: туда и $gобследовал:обследовала: деревню и окрестности в поисках признаков средоточия или охотников на магов и их командира.$B$BИщи даже в озере, если придется!', 'Поищите командующего силами охотников на магов в деревне Инду\'ле и озере Инду\'ле.', 'Здесь вы обнаружили тело командира охотников на магов.$B$BСудя по его виду и состоянию его павших подчиненных, вы рискнули бы утверждать, что они не захлебнулись. Скорее, когда они призвали силу средоточия, они не ожидали нападения элементалей, поднявшихся из провалов в дне озера.$B$BВыходит, охотники на магов сами обрекли себя на смерть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12107, 'Конец цепочки', 'В его одеяниях вы находите две интересных вещи.$B$BВо-первых, талисман, который явно представляет собой устройство для управления фокусом. А во-вторых, несколько приказов от некоего Сидрагоса, предназначенных предводителю в садах Лунного Покоя.$B$BВетхий промокший пергамент извещает Горамоша, что ему следует перевести всех охотников за магами на восток, к Лазуритовому святилищу драконов.$B$BБыть может, следует добыть из фокуса все сведения, какие можно, и отправиться на восток, чтобы понаблюдать за драконьим святилищем с западного уступа?', 'Используйте талисман управления средоточием силовых линий, чтобы получить сведения о средоточии силовых линий под озером Инду\'ле. Затем отправляйтесь на восток, к Лазуритовому святилищу драконов, расположенному почти в центре южного Драконьего Погоста, и с западного уступа понаблюдайте за тем, что там происходит.После этого вернитесь к проекции верховного мага Модеры в Покое Звезд.', 'Что-о?!$B$B<Изображение перед вами на миг искажается, пока верховный маг пытается взять себя в руки.>$B$BРазумеется, нам с самого начала следовало догадаться, что они замышляют! Скорей, нельзя терять времени!$B$BНужно предупредить Драконий Покой!', NULL, NULL, NULL, 'Информация о средоточии силовых линий получена', 'Лазуритовое святилище драконов обследовано', 'Талисман управления средоточием силовых линий', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12108, 'ИСКЛЮЧЕНО', 'Эта куча земли очень похожа на спешно зарытую могилу. Лежащее под ней тело опознать невозможно, но вы обнаруживаете записку, которая адресована некоему Михаилу.$B$BВ записке также встречается очередное упоминание Рудника Полого Камня. Возможно, кто-то из Приюта Янтарной Сосны может пролить свет на это дело.', 'Принесите дневник Михаила картограферу Тобиасу в Приют Янтарной Сосны.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12109, 'И снова к Гриану Камнегриву...', 'Дружинников Западного Края послали на восток в поисках прохода на северные территории. Их вторая задача – обеспечить безопасность стратегически важных точек, поэтому они вряд ли откажутся обследовать этот рудник.$B$BНайди Лагерь дружины Западного Края на северо-востоке и поговори с Грианом Камнегривом. Возможно, ты уже $gвстречался:встречалась: с ним по дороге в Западный Край. Не забудь сказать ему, что это я тебя послал. $B$BОн будет счастлив отдать действующий рудник своему королю.', 'Поговорите с капитаном Грианом Камнегривом в Лагере дружины Западного Края.', 'Говоришь, тебя послал Думонт? Отлично. Посмотрим, чем тебя можно занять.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12110, 'Конец цепочки', 'В его одеяниях вы находите две интересных вещи.$B$BВо-первых, талисман, который явно представляет собой устройство для управления фокусом. А во-вторых, несколько приказов от некоего Сидрагоса, предназначенных предводителю в садах Лунного Покоя.$B$BВетхий промокший пергамент извещает Горамоша, что ему следует перевести всех охотников за магами на восток, к Лазуритовому святилищу драконов.$B$BБыть может, следует добыть из средоточия все сведения, какие можно, и отправиться на восток, чтобы понаблюдать за драконьим святилищем с западного уступа?', 'Используйте талисман управления средоточием силовых линий, чтобы получить сведения о средоточии силовых линий на дне озера Инду\'ле. Затем отправляйтесь на восток, к Лазуритовому святилищу драконов, расположенному почти в центре южного Драконьего Погоста, и с западного уступа понаблюдайте за тем, что там происходит.После этого вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара.', 'Что-о?!$B$B<Изображение перед вами на миг искажается, пока верховный маг пытается взять себя в руки.>$B$BРазумеется, нам с самого начала следовало догадаться, что они замышляют! Скорей, нельзя терять времени!$B$BНужно предупредить Драконий Покой!', NULL, NULL, NULL, 'Информация о средоточии силовых линий получена', 'Лазуритовое святилище драконов обследовано', 'Талисман управления средоточием силовых линий', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12111, 'Где бродят дикие звери', 'В этой упаковке – несколько сосудов с вакциной, изготовленной Синтаром. Я прошу тебя отыскать в находящихся поблизости лесах снегопадных лосей и полярных гризли. Когда найдешь этих животных, метни в них с безопасного расстояния один их сосудов. Из разбившегося сосуда распространится газ, который и вакцинирует животных. Им достаточно очутиться в облаке газа, и они окажутся привиты.$B$BНужно привить как можно больше животных. Как закончишь, возвращайся ко мне.', 'Используйте суму с вакцинами, чтобы привить 5 снегопадных лосей и 5 полярных гризли по просьбе Соара Ярости Ястреба из Молота Агмара в Драконьем Погосте.', 'Ты совершил достойное деяние, $N. Прошу тебя, выбери себе награду.', NULL, NULL, NULL, 'Привито снегопадных оленей', 'Привито полярных гризли', 'Сума с вакцинами', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12112, 'Деловые отношения', 'Ну, похоже, наконец-то и ты $gоказался полезным:оказалась полезной:. Нечасто мне $gвстречался полезный:встречалась полезная:$r.$B$BЗдесь ты нам больше не понадобишься. Отправляйся-ка в Погань и узнай, не нужна ли помощь моему братцу Зорту. Он пошел посмотреть, не удастся ли ему убедить великанов пожертвовать своими жизнями, чтобы этого не пришлось делать нам. Определенно, если кого в семье и обделили мозгами, так это его.', 'Найдите Зорта в центре ущелья порочных кристаллов, к северо-востоку от Лагеря Соплозабилось.', 'Я могу найти тебе кое-какое применение. Проходи-ка вперед и постой минутку.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12113, 'Здравствуй, мяско!', 'Привет, $C! Давай, присаживайся у огонька!$B$BЯ бы тебе предложил что-нибудь перекусить, но у меня ничего нет. Не знаю даже, что делать – то ли понадеяться на чью-нибудь помощь, то ли заняться охотой самому.$B$BСлушай, тебе же все равно нечем заняться? Может быть, принесешь мне немного мяса? Смотри, сколько его тут пасется!', 'Харкор из Лагеря Харкора просит вас принести 10 кусков жилистого мяса ворга, которые можно добыть, поохотившись на хищников Ночного Воя, и 10 стейков из черпоклыка. Их можно вырезать из туш травоядных веслорогов.', 'Ух, здорово!$B$BМясо с дымком и кружка с пивком – что может быть лучше?', 'У меня уже в животе бурчит, $R. Надеюсь, ты несешь мне еду?', NULL, NULL, 'Жилистое мясо ворга', 'Стейк из черпоклыка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12114, 'Анти-стрессовая терапия', 'Тролли... терпеть их не могу! $gХаркор сплевывает на пол.>$B$BЭти мерзавцы однажды схватили меня... еще чуть-чуть – и стал бы я на голову короче!$B$BДрузья говорят, что я должен забыть обо всем и жить дальше, но я просто не могу простить троллям это оскорбление!$B$BЗнаешь, что бы сделало меня самым счастливым человеком, $r? Куча трупов этих поганцев, гниющих на солнце! Ей-богу, я даже готов заплатить, если кто-то организует мне такое удовольствие.', 'Харкор из Лагеря Харкора просит вас убить 10 заступников Драккари и 10 оракулов Драккари возле Руин Дракил\'джин.', 'Ох, спасибочки, $C.$B$BБудет время – схожу сам посмотрю на это зрелище.', 'Ну, как идет охота на троллей?', NULL, NULL, 'Заступник Драккари убито', 'Оракул Драккари убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12115, 'Кольтира и язык смерти', 'В наши ряды не так давно вступил некто, кто сумеет прочесть эту книгу. Освободившийся от уз рыцарь смерти по имени Кольтира Ткач Смерти временно поселился здесь, в Молоте Агмара. Поскольку он некогда был рыцарем смерти Артаса и воином Плети, он, возможно, умеет понимать язык мертвых.', 'Отнесите сшитый плотью фолиант Кольтире Ткачу Смерти.', 'Знаешь, деревенщина, меня интересуют только две вещи в мире, и перевод книжонок Плети в их число не входит.$B$BХотя… возможно, мы сумеем извлечь из этого взаи$Nю выгоду?$B$B<Кольтира обнажает оружие.>$B$BВот мой рунический меч, Замороз. Он жаждет крови Короля-лича и его прихвостней, но сначала мне нужно укрепить его рунами могущества, знаками холода, крови и тени. Принеси мне подходящие источники могущества, и я переведу тебе эту книгу.', 'Что это, $R?', NULL, NULL, 'Сшитый плотью фолиант (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12116, 'Только смелым покоряются...', 'Приветствую тебя, $C. Спасибо, что $gзашел:зашла: поболтать со стариной Кразом.$B$BВот уже много лет Краз слушает голоса духов и выполняет их просьбы.$B$BНедавно из глубины этих развалин к Кразу воззвали множество голосов несчастных душ, что не могут обрести покой.$B$BЕсли ты хочешь помочь душам наших предков, войди в склеп и собери то, что принадлежало когда-то несчастным призракам.', 'Краз из Лагеря Харкора просит вас войти в Руины Дракил\'джина и собрать 5 каноп Драккари.', 'Внутренности? Странный выбор, $С.$B$BКраз узнает, что они могут нам поведать. Спасибо тебе за то, что ты отважился войти в этот ужасный склеп.', 'Что ты нашел в этом склепе, $C?', NULL, NULL, 'Канопа Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12117, 'Путешествие в гавань Моа\'ки', '$r, с лодки из гавани Моа\'ки пришло сообщение. Сегодня утром там случилось нечто ужасное!$B$BТы здесь нам очень $gпомог:помогла:. Может быть, ты $gсогласился:согласилась: бы отправиться к великому Драконьему Погосту?$B$BСудя по тону сообщения, старейшине Ко\'нани очень пригодится твоя помощь...', 'Отправляйтесь в гавань Моа\'ки на Драконий Погост и поговорите со старейшиной Ко\'нани.', 'Что-что, $R? Тебя прислал Хотава?$B$BХорошо, очень хорошо... Так много нужно сделать. Нам пригодится любая помощь, какую мы можем получить!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12118, 'Путешествие в гавань Моа\'ки', '$r, с лодки из гавани Моа\'ки пришло сообщение. Сегодня утром там случилось нечто ужасное!$B$BТы здесь нам очень $gпомог:помогла:. Может быть, ты $gсогласился:согласилась: бы воспользоваться лодкой и сплавать к великому Драконьему Погосту?$B$BСудя по тону сообщения, старейшине Ко\'нани очень пригодится твоя помощь...', 'Отправляйтесь в гавань Моа\'ки на Драконий Погост и поговорите со старейшиной Ко\'нани.', 'Что-что ты говоришь, $R? Тебя Ануниак прислал?$B$BХорошо, очень хорошо... сделать предстоит очень многое. Нам пригодится любая помощь, какую мы можем получить!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12119, 'Добиться аудиенции', '$N, отправляйся как можно быстрее в храм Драконьего Покоя и вручи это письмо распорядителю, Тариолстразу.$B$BХрам находится в центре Драконьего Погоста. Ступай по дороге, ведущей на восток, пока она не кончится, а потом иди напрямик через Драконьи пустоши, и придешь к храму.$B$BЯ уверена, что, когда распорядитель прочтет твое рекомендательное письмо, он позаботится о том, чтобы королева Алекстраза дала тебе аудиенцию. Остается только надеяться, что еще не поздно.$B$BСпасибо тебе за все, что ты $gсделал:сделала: для нас. Желаю тебе благополучно добраться до цели!', 'Вручите свое приглашение Тариолстразу в храме Драконьего Покоя.', 'Рекомендательное письмо? Тебе нужно видеть королеву? Дай-ка взглянуть…$B$BКаково бы ни было твое дело, надеюсь, оно достаточно важное. Сегодня неба не видно за крыльями нападающих синих драконов!', 'Да, $C? Чем могу служить?', NULL, NULL, 'Приглашение в Храм Драконьего Покоя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12120, 'Молот Драк\'агуула', 'Скверна и разложение...$B$BКраз почувствовал их присутствие задолго до того, как ты $gпринес:принесла: сюда эти кувшины. Скверна поразила древних духов Драккари и не дает им обрести покой.$B$BКразу незачем обманывать тебя, $C. Очистить это место будет нелегко, но об этом мы поговорим в другой раз.$B$BСначала мы должны добыть то, что поможет совершить акт очищения. Этот предмет находится в руках одного из смертных, Драк\'агуула. Принеси Кразу его молот!', 'Краз из Лагеря Харкора просит вас убить Драк\'агуула возле Руин Дракил\'джин и принести ему Дракил\'джинский молот.', '', NULL, NULL, NULL, 'Дракил\'джинский молот', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12121, 'Увидимся в другом мире', 'Эти драккари не проявили к тебе ничего, кроме жестокости. Не стоит чувствовать вину перед ними. Знай, что лишь немногие могли бы выполнить поручение, которое Краз хочет доверить тебе. $B$BЧтобы очистить это место и даровать духам долгожданный покой, тебе придется шагнуть в мир смерти.$B$BВнутри этого склепа тебя ждет тот, кто сможет нам помочь. Только он обладает знаниями, которые направят нас на истинный путь. $B$BУдарь молотом в гонги, и населяющие это место духи утащат тебя в потусторонний мир.$B$BКраз будет ждать твоего возвращения.', 'Краз из Лагеря Харкора просит вас ударить Дракил\'джинским молотом в гонги, окружающие Руины Дракил\'джин. После этого вас, скорее всего, убьют, и тогда вы сможете войти в руины, чтобы поговорить с Ган\'джо из мира мертвых.', '', NULL, NULL, NULL, 'Смерть от рук полководца Джин\'аррака', 'Заряженный молот Дракил\'джин', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12122, 'Добиться аудиенции', '$N, отправляйся как можно быстрее в храм Драконьего Покоя и вручи это письмо распорядителю, Тариолстразу.$B$BХрам находится в центре Драконьего Погоста. Ступай по дороге, ведущей на восток, пока она не кончится, а потом иди напрямик через Драконьи пустоши, и придешь к храму.$B$BЯ уверен, что, когда распорядитель прочтет твое рекомендательное письмо, он позаботится о том, чтобы королева Алекстраза дала тебе аудиенцию. Остается только надеяться, что еще не поздно.$B$BСпасибо тебе за все, что ты $gсделал:сделала: для нас. Желаю тебе благополучно добраться до цели!', 'Вручите свое приглашение в храм Драконьего Покоя Тариолстразу в храме Драконьего Покоя.', 'Рекомендательное письмо? Тебе нужно видеть королеву? Дай-ка взглянуть…$B$BКаково бы ни было твое дело, надеюсь, оно достаточно важное. Сегодня неба не видно за крыльями нападающих синих драконов!', 'Да, $R? Чем могу служить?', NULL, NULL, 'Приглашение в Храм Драконьего Покоя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12123, 'Информация для королевы', '<Дракон-распорядитель достает из рукава ваше рекомендательное письмо.>$B$BДа… да, думаю, ты уже $gготов:готова: встретиться с королевой.$B$BКогда будешь $gготов:готова:, обратись ко мне снова, и я прикажу одному из этих драконов доставить тебя на вершину храма. Тебе следует лично вручить письмо королеве Алекстразе.', 'Вручите свое приглашение Алекстразе Хранительнице Жизни в храме Драконьего Покоя.', 'Чтобы принести нам эти сведения, потребовалось немалое мужество! А я-то не могла понять, отчего синие драконы так дерзко решились напасть на сам храм. Теперь мы знаем, что они использовали огромные запасы той самой магии, которая, как они считают, угрожает Азероту.$B$B<Королева печально качает головой.>$B$BЛицемерие, конечно, но тут уж ничего не поделаешь. Если Малигос не одумается, у нас не останется выбора: придется напасть на них в ответ!', 'Приятно наконец встретиться с тобой лично, $N. Я знала тебя еще до твоего рождения…', NULL, NULL, 'Приглашение в Храм Драконьего Покоя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12124, 'Информация для королевы', '<Дракон-распорядитель достает из рукава ваше рекомендательное письмо.>$B$BДа… да, думаю, ты уже $gготов:готова: встретиться с королевой.$B$BКогда будешь $gготов:готова:, обратись ко мне снова, и я прикажу одному из этих драконов доставить тебя на вершину храма. Тебе следует лично вручить письмо королеве Алекстразе.', 'Вручите свое приглашение в храм Драконьего Покоя Алекстразе Хранительнице Жизни в храме Драконьего Покоя.', 'Чтобы принести нам эти сведения, потребовалось немалое мужество! А я-то не могла понять, отчего синие драконы так дерзко решились напасть на сам храм. Теперь мы знаем, что они использовали огромные запасы той самой магии, которая, как они считают, угрожает Азероту.$B$B<Королева печально качает головой.>$B$BЛицемерие, конечно, но тут уж ничего не поделаешь. Если Малигос не одумается, у нас не останется выбора: придется напасть на них в ответ!', 'Приятно наконец встретиться с тобой лично, $N. Я знала тебя еще до твоего рождения…', NULL, NULL, 'Приглашение в Храм Драконьего Покоя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12125, 'Ради крови', 'Кровь невинных уже однажды использовалась для того, чтобы насытить жажду этого клинка. К сожалению, для меня это больше невозможно.$B$B<Кольтира замолкает, размышляя.>$B$BПридется импровизировать. К югу отсюда, на высоких утесах, расположена клыкаррская деревня Инду\'ле. Попавшие под мощное воздействие хаотической магии синих драконов, жители Инду\'ле сошли с ума.$B$BВозьми этот кровавый самоцвет и воздействуй им на сумасшедшего жителя деревни. Если я не могу брать кровь невинных, возьму кровь убогих!', 'По просьбе Кольтиры Ткача Смерти воздействуйте кровавым самоцветом на спятившего селянина Инду\'ле, а затем возвращайтесь к Кольтире в Молот Агмара на Драконьем Погосте с наполненным кровавым самоцветом.', 'Простое задание для простака. Ты действовал согласно моим ожиданиям.', 'Принеси мне кровь убогих.', NULL, NULL, 'Наполненный кровавый самоцвет', 'Кровавый самоцвет', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12126, 'На службе нечестивости', 'Такие, как я, жаждут силы нечестивости. Она составляет самую суть нашего существования, приносит смерть тем, кто осмеливается смеяться над ней! По счастью, у меня есть источник этой силы, из которого я могу черпать при необходимости.$B$BВот, возьми этот нечестивый самоцвет и ступай в Рубиновое святилище драконов, к востоку отсюда. Там ты найдешь герцога Валленхола, рыцаря смерти Артаса. Измотай его в поединке, а потом обрушь на него мощь самоцвета. Самоцвет убьет его и вберет его нечестивую силу!', 'Используйте нечестивый самоцвет против герцога Валленхола и вернитесь с наполненным нечестивым самоцветом к Кольтире Ткачу Смерти в Молот Агмара на Драконий Погост.', '<Глаза Кольтиры расширяются от удивления.>$B$BВпечатляюще! Тебе удалось одолеть рыцаря смерти Артаса… не в одиночку, очевидно… но все же…', 'Наполни этот камень силой нечестивости!', NULL, NULL, 'Наполненный нечестивый самоцвет', 'Самоцвет нечестивости', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12127, 'На службе у мороза', 'Трескучий мороз защищает рыцаря смерти и в то же время распугивает его врагов. Кто владеет холодом, способен сеять хаос и разрушение!$B$BВозьми этот ледяной самоцвет и отправляйся напрямик через тундру Драконьего Погоста, пока не выйдешь к Зеркалу Рассвета, к востоку от храма Драконьего Покоя. Там тебе придется сразиться с полчищами загробников льда, обитающих на поверхности озер, чтобы забрать у них суть холода. Когда они ослабеют, используй силу самоцвета, $N!', 'Используйте ледяной самоцвет против загробников льда и вернитесь к Кольтире Ткачу Смерти в Молот Агмара на Драконий Погост с наполненным ледяным самоцветом.', 'О, $N, я уже чувствую, как холод проникает в меня!', 'Тут, в Нордсколе, мы все на службе у мороза!', NULL, NULL, 'Наполненный ледяной самоцвет', 'Ледяной самоцвет', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12128, 'Как дела у Регара?', 'Из-за всего этого переполоха с армией, штурмующей Тор Модан, я чуть не забыл про отряд Регара в Лагере горняков.$B$BЯ отправил Регара и его помощников разбить лагерь возле Дун Аргола, на юге Побережья Восточного Ветра.$B$BОни должны были собрать сведения о железных дворфах, замеченных в южных холмах, но с тех пор я не получил от них ни единого отчета. Не $gмог:могла: бы ты узнать, как у них дела?', 'Поговорите с Регаром Бровебоем в Лагере горняков.', 'Хм... что-то не похож ты на ученого. Впрочем, какая разница. Железные дворфы готовятся к войне, а мои исследователи пропали без вести. Пожалуй, я бы не отказался от любой помощи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12129, 'Безукоризненный замысел', 'Железные дворфы не делают тайны из своих приготовлений к войне. Учитывая наличие в их армии големов, великанов и наэлектризованных элементалей, можно смело утверждать, что их преимущество над дружиной Западного Края огромно. Если нашим ребятам не удастся вовремя найти проход на север, железные дворфы застанут их врасплох. $B$BНам надо выиграть время для дружины Западного Края, и я знаю, что мы можем предпринять. В Дун Арголе полно кователей рун, собирающих боевых големов. Они часто носят с собой чертежи деталей, с помощью которых мы могли бы создать собственного голема. Собери все эти чертежи и принеси их мне!', 'Принесите полный набор чертежей боевого голема Регару Бровебою в Лагерь горняков.', 'Ты собрал все чертежи? Превосходно! Ты только подумай, какие у них будут лица, когда они увидят нашего голема!', 'Удалось ли тебе отобрать чертежи у кователей рун?', NULL, NULL, 'Чертежи боевого голема', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12130, 'Зачем ковать то, что можно отобрать?', 'Что толку от чертежей, если у нас нет ни инструментов, ни материалов, чтобы выточить детали? Впрочем, в Дун Арголе эти запчасти валяются повсюду...$B$BВот тебе новое задание!$B$BНайди-ка этим деталям новое применение.$B$BОни валяются повсюду вокруг мастерских железных кователей рун. Правда, я не стал бы рассчитывать на то, что железные дворфы будут тебе рады. Я бы тоже рассердился, если бы кто-то попытался стянуть результаты моего труда.', 'Принесите 8 частей боевого голема Регару Бровебою в Лагерь горняков.', '<Регар утирает пот со лба.>$B$BОх, ну почему все так непросто? Неужели так сложно нанести какую-нибудь маркировку на эти детали?$B$BВот так всегда! Как только понадобится гном, его не оказывается под рукой…', 'Надо же – ты еще жив. А запчасти у тебя с собой?', NULL, NULL, 'Часть боевого голема', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12131, 'Нам нужна энергия', 'Наш боевой голем почти готов! Остается только вложить в него энергобатареи. Судя по сведениям, которые мне удалось собрать в Дун Арголе, созданием зарядных ячеек занимаются два дворфа – рунический кузнец Дурар и рунический кузнец Каторн.$B$BЧтобы наш голем заработал, в него надо установить две энергобатареи.$B$BНайди этих рунических кузнецов. Их мастерские должны быть в самом центре Дун Аргола.', 'Принесите энергобатареи Дурара и Каторна Регару Бровебою в Лагерь горняков.', '<Регар выхватывает у вас энергобатареи.>$B$BПревосходно! Наконец-то все готово!', 'Ну, где же энергобатареи?', NULL, NULL, 'Энергобатарея Дурара', 'Энергобатарея Каторна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12132, 'Сила разрушения', 'Ты уже многое $gсделал:сделала: для меня, и осталось последнее задание.$B$BКроме мира, который все видят каждый день, существует и другой. Именно из того, другого мира, где царствует тень, нападают на меня мои мучители. Хоть я и бессилен против своих собственных демонов, но ты $gмог:могла: бы положить конец их бесправному засилию. У тебя есть сила, я видел это своими собственными глазами.$B$BВойди в мир теней и сразись с демонами, мучающими меня!$B$BСделай это, и я переведу тебе фолиант, как и обещал.', 'По просьбе Кольтиры Ткача Смерти из Молота Агмара, что на Драконьем Погосте, войдите в мир теней и сразите 6 мрачных мучителей.Если вам нужно будет еще раз войти в мир теней, обратитесь к Кольтире.', 'Сила, которой я владею, дорого мне обходится, Профессия. Многие рыцари, и светлые, и темные, полегли в сече у часовни Последней Надежды. Будущее кажется мрачным, но, по крайней мере, я знаю теперь, перед лицом чего я стою. Король-лич никогда не разожмет свою ледяную хватку, и уже хотя бы по этой причине он должен умереть!', NULL, NULL, NULL, 'Мрачный мучитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12133, 'Разбей тыкву!', 'Посреди деревни лежит большая тыква. Взгляд ее горит мрачной злобой.$B$BРазбив тыкву, вы видите старый, опаленный священный символ.', 'Отдайте опаленный священный символ переодетой попечительнице сирот.', 'Вы нашли это в тыкве всадника без головы? Это древний символ Света. Наверняка он прежде принадлежал всаднику, до того, как на него пало проклятье, и он превратился в чудовище. Спасибо вам, $N. Этот символ должно отдать паладинам.Я постараюсь, чтобы он попал к ним.$B$BО, я чуть не забыла! У вас есть тайный поклонник...$B$BОдин из моих подопечных хочет, чтобы я вам передала вот это. Он слишком стесняется, чтобы отдать вам это лично.', 'Да, $N?', NULL, NULL, 'Опаленный священный символ (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12134, 'Саша выходит на охоту', 'Это... проклятие... вот, что овладело Среброречьем и Деревней Солнцестояния... оно превратило наших жителей в диких зверей.$B$BОтец пытался их предупредить, но они слушали лишь голос волков...$B$BТеперь их уже не спасти. Можно лишь покончить с ними... ради их собственного блага.', 'Саша просит вас убить 12 охотников солнцестояния в Деревне Солнцестояния.', 'Убив этих чудовищ, я не верну отца... но ведь дело не в мести, понимаешь?', NULL, NULL, NULL, 'Охотник солнцестояния убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12135, '\"И гори все огнем!\"', 'Всадник без головы нападет на деревню в любой момент! Повсюду начнется пожар!$B$B$N, вы ведь поможете нам бороться с пожаром Всадника без головы? Когда он придет, присоединяйтесь к пожарной бригаде. Берите ведро и заливайте пожар или передавайте ведра по цепочке! Погасите пожар, и мы, может, еще спасемся!', 'Переодетая попечительница сирот просит вас помочь потушить пожар в деревне, если ее подожжет Всадник без головы. Когда пожар будет потушен, снова поговорите с попечительницей сирот.', 'О, спасибо! Да благословит Свет ваши добрые деяния, добрый господин. Тень Темного Всадника все еще стоит у нас за спиной, но по крайней мере хотя бы на некоторое время деревня может не опасаться пожара.', 'Данхельм, вы обещали спасти детей!', NULL, NULL, 'Пожар потушен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12136, 'Переведенная книга', 'Вот, $N. Я перевел все, запечатленное на страницах этого фолианта. В нем ты найдешь список имен последователей Культа Проклятых, разбросанных по всему континенту.$B$BИх сеть шпионов и агентов по меньшей мере впечатляет.$B$BПрощай, друг мой. Пусть эта книга хорошо послужит тебе и твоему народу.', 'Доставьте переведенный сшитый плотью фолиант капитану Горту в Молот Агмара.', '<Горт берет у вас из рук книгу и начинает читать.>$B$BЧТО? Это не может быть правдой! Некоторых из этих орков я знаю уже много лет!$B$BОставь меня, Профессия. У меня много дел – и много предателей, которым нужно воздать по заслугам. Сегодня ты оказал Орде неоценимую услугу.', 'Как раз вовремя! Ты где был?', NULL, NULL, 'Переведенный сшитый из плоти фолиант (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12137, 'Остынь, чудо!', 'Все как по пророчеству, $gдружище:подруга:! $gраса:-$C придет, чтобы освободить души умерших... Долго же мы ждали твоего пришествия!$B$BДраккари стали диким народом, жестоким и беспощадным. $B$BНо наши души страдают безвинно, $gдруг мой:подруга:. Это место надо очистить, и только смертному под силу совершить подобное.$B$BПоговори со мной, когда будешь $gготов:готова: вернуться в свое тело. Возьми снег из ближайшего сундука и упокой моих братьев. Затем отнеси их останки своему хранителю душ. Он подскажет тебе, что делать дальше.', 'Ган\'джо просит вас собрать снег вечного сна из его сундука в руинах Дракил\'джин.Им надо окропить древних духов Драккари и отнести крупицы духов Драккари Кразу в Лагерь Харкора.', 'Ты молодецl.$B$BА теперь присядь и выслушай, что я тебе скажу. Нам надо многое обсудить.', 'Ты выполнил мое поручение в склепе, $C?', NULL, NULL, 'Снег вечного сна', 'Крупицы духов Драккари', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12138, '... а может быть, и нет', 'Думаешь, эти ребята, изготавливающие энергобатареи, догадались их зарядить? Нет, конечно! Это было бы слишком просто.$B$BНу ладно; не хотят по-хорошему – будем действовать по-плохому. Остаточного заряда хватит на то, чтобы обеспечить моторные системы голема, но в бою на него можешь не рассчитывать.$B$BВидишь грозовых караульных, которые патрулируют периметр Дун Аргола? Подведи голема поближе, и он сам впитает энергию после смерти часового.', 'Подзарядите вашего Боевого голема от десяти грозовых караульных и вернитесь к Регару Бровебою в Лагерь горняков.', 'Ну наконец-то, голем готов. Надеюсь, он не развалится на пол-пути! Боюсь, если мы не свергнем главу клана Дун Аргола, капитан Гриан будет очень недоволен.', NULL, NULL, NULL, 'Уровень заряда', 'Пульт управления големом', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12139, '\"И гори все огнем!\"', 'Всадник без головы нападет на деревню в любой момент! Повсюду начнется пожар!$B$B$N, вы ведь поможете нам бороться с пожаром Всадника без головы? Когда он придет, присоединяйтесь к пожарной бригаде. Берите ведро и заливайте пожар или передавайте ведра по цепочке! Погасите пожар, и мы, может, еще спасемся!', 'Попечительница сирот в маске просит вас помочь потушить пожар в деревне. Когда пожар потухнет, снова поговорите с попечительницей сирот в маске в городе.', 'Пожар потушен! Вы с пожарной бригадой победили! Ха!$B$BНападение Всадника без головы провалилось, но пока он и его голова не уничтожены, он будет возвращаться.$B$BА пока утешайтесь тем, что вы спасли наших детей. Для меня великая честь быть свидетельницей вашей отваги!', NULL, NULL, NULL, 'Пожар потушен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12140, 'Славься, Роанук!', 'Как таурены, Отрекшиеся, тролли и эльфы Крови, таунка тоже нуждаются в вожде, в жилах которого течет их кровь. Таким вождем станет тот, кого ты $gспас:спасла:, Роанук Ледяная Пыль.$B$B<Командир Агмар передает вам пергамент.>$B$BЯ даю тебе нечто, с чем ты уже $gзнаком:знакома: – клятву крови Орды.$B$BОтнеси эту клятву Роануку Ледяной Пыли и введи его в лоно Орды в качестве вождя таунка.$B$BДавай не будем заставлять его ждать.$B$B<Агмар кивает.:', 'Найдите Роанука Ледяную Пыль в Молоте Агмара, примите его в лоно Орды и посвятите его в вожди сил Орды.Когда ритуал будет завершен, вернитесь к командиру Агмару с клятвой крови Орды.', 'Имея поддержку столь могущественного шамана, мы, несомненно, одержим победу у Врат Гнева!', 'Не теряй времени попусту, $N. Ангратар ждет!', NULL, NULL, 'Роанук Ледяная Пыль посвящен', 'Клятва крови Орды', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12141, 'Дипломатическое поручение', 'Я вижу, $N, вы очень хотите помочь. Разумеется, вы не для того добирались до Нордскола, чтобы торчать в городе! У меня как раз есть для вас задание… связанное с дальней поездкой.$B$BМы давно пытаемся добиться расположения клыкарров, коренных жителей Нордскола. Не так давно к нам явился молодой клыкарр. Он просил помощи, но мы тогда были не в состоянии ее оказать.$B$BНо теперь, когда вы здесь, быть может, вы согласитесь ему помочь? Отыщите Карука на берегу Терзающего Бича, к юго-западу отсюда, и узнайте, чем вы можете ему помочь.', 'Поговорите с Каруком на берегу Терзающего Бича, к юго-западу от крепости Отваги.', 'Ты явился мне на помощь? Благодарю тебя, $N!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12142, 'Контроль над чумой', 'Уф! Один из снобольдов устроил погром в нашем лагере, пока мы бились с драконом. Эти снобольды вредят нам, стоит только отвернуться. Сколько можно?!$B$BК югу отсюда ты найдешь снобольдов, живущих под опекой здешних магнатавров. Иди и прибей их.$B$BЕсли магнатавры вмешаются на стороне своих рабов, покончи и с ними.', 'По заданию Дуана с передовой 7-го легиона убейте 10 снобольдов Снежных равнин и 3 магнатавров Драконьего Погоста в лагерях магнатавров, окружающих Драконий Покой.', 'Ну, наконец-то!', NULL, NULL, NULL, 'Снобольды Снежных равнин', 'Магнатавр Драконьего Погоста', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12143, 'Преследование в каньоне', 'Не могу поверить! Еще одна шайка этих вредителей только что попыталась сбежать с очередной порцией наших припасов. Они несутся вон к тому северному каньону, гонись-ка за ними и разберись с тем, к кому они спешат!', 'Дуан просит вас идти по следу снобольдов по каньону к северо-востоку от передовой 7-го легиона и разобраться с их вожаком.', 'Ледобивень, говоришь? Да, это имя я и раньше слыхал. Неплохая работа, $C. Надеюсь, теперь мы сможем вновь сосредоточить наше внимание на угрозе со стороны драконов.', NULL, NULL, NULL, 'Ледобивень убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12144, 'Заразу – под контроль!', 'Слышь, ты! Один из этих коротышек-снобольдов обчистил наш лагерь во время последнего налета драконов. Они набрасываются на нас каждый раз, стоит только повернуться спиной! Меня это достало.$B$BВон там, к востоку, ты найдешь снобольдов, которые прячутся под юбками у каких-то местных магнатавров. Перебей их. А если магнатавры вздумают заступиться за своих рабов, так и их перебей тоже.', 'Убейте 10 снобольдов Снежных равнин и 3 магнатавров Драконьего Погоста в лагерях магнатавров, расположенных к юго-востоку от Драконьего Покоя. Выполнив задачу, вернитесь к Контоканису в Драконьей Погибели в северо-западных Драконьих пустошах.', 'Избавились от них – и ладно!', NULL, NULL, NULL, 'Снобольды Снежных равнин', 'Магнатавр Драконьего Погоста', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12145, 'Преследование в каньоне', 'Не могу поверить! Еще одна шайка этих вредителей только что попыталась сбежать с очередной порцией наших припасов. Они несутся сейчас по каньону, гонись за ними и разберись с тем, к кому они спешат!', 'По поручению Контоканиса преследуйте снобольдов по каньону к югу от Драконьего Зова и разберитесь с их вожаком.', 'Ледолап, да? Знакомое имечко! Молодчина! Есть надежда, что мы, тролли Черного Копья, сможем теперь вплотную заняться драконами!', NULL, NULL, NULL, 'Ледолап убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12146, 'Зловещие выводы', 'Нижняя сторона рога украшена гравировкой с изображением молота и разряда молнии. Что-то с этим рогом не так, не подходит он магнатавру...$B$BВозьмите его, идите на юг по Пути $Nв к Драконьему Покою и найдите кого-нибудь, кому станет интересна эта диковина.', 'Отнесите расписанный боевой рог к Драконьему Покою и найдите того, кто захотел бы оценить исходящую от него угрозу.', 'Воистину нелеп был бы магнатавр, украсивший себя таким рогом... Я очень рада, что ты показал мне этот рог, он встревожил меня не на шутку.', 'Да, $C?', NULL, NULL, 'Расписанный боевой рог (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12147, 'Зловещие выводы', 'Нижняя сторона рога может похвастаться украшенной гравировкой печатью с изображением молота и разряда молнии. Что-то в этом роге кажется абсолютно несоответствующим магнатаврам.$B$BВозьмите этот рог, идите на восток через Драконьи пустоши к Драконьему Покою и найдите того, кого могли бы заинтересовать эти пугающие находки.', 'Отнесите расписанный боевой рог к Драконьему Покою и найдите того, кто заинтересовался бы возможностью оценить потенциальную угрозу.', 'Действительно, это очень странно, что такой предмет оказался у магнатавра... странно и очень тревожно. Я очень рада, что ты показал мне это.', 'Да, $R?', NULL, NULL, 'Расписанный боевой рог (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12148, 'Единственный в своем роде', 'Такая странная печать – и у магнатавров… это говорит о необычно высокой организации.$B$BМагнатаврам редко удается забыть о своей агрессивной натуре настолько, чтобы начать взаимодействовать друг с другом. Я подозреваю, что они задумали ограбить крупное поселение.$B$BЯ сильно сомневаюсь, что этот рог – единственный в своем роде. Мне нужны доказательства того, что я не права. В каньоне к северо-западу от Лазуритового святилища драконов ты найдешь Расщепителя костей. Иди сразись с ним и возвращайся с любыми свидетельствами, которые могут подтвердить мои опасения.', 'Найдите и убейте Расщепителя Костей в каньоне (или рядом с ним), находящемся к северо-западу от Лазуритового святилища драконов. Принесите найденное вами свидетельство Аурастразе в храм Драконьего Покоя.', 'Так, значит, это правда. Они не могли выбрать более удачного времени для такого нападения… Разрываясь между армией Плети и синими драконами, вряд ли кто-то что-то мог уже заметить…', 'Тебе удалось что-нибудь отыскать?', NULL, NULL, 'Расписанный боевой рог', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12149, 'Могучие магнатавры', 'Магнатавры – чрезвычайно агрессивные существа… и это основная причина, почему мы редко видим, чтобы они сосуществовали в сколь-нибудь значимых количествах, не начав убивать друг друга. Однако из их среды выделился могучий вожак, и мы должны выследить его и уничтожить, если хотим справиться с этой угрозой.$B$BЯ поспрашиваю тут в округе. А ты, тем временем, вреди им как только сможешь.$B$BК востоку отсюда установлены три факела. Рядом с ними – три крупных магнатавра. Убей их, чтобы выиграть немного времени для охоты на их вожака.', 'Выследите и убейте Кровавого Пира, Ледоскала и Дракрова к востоку от Драконьего Покоя.Кровавый Пир обитает в юго-восточном углу Драконьих Пустошей, прямо к северу от изумрудного святилища драконов. Ледоскал патрулирует северную оконечность Зеркала Рассвета. Дракров бродит у подножья утесов к западу от бронзового святилища драконов.Когда все три магнатавра будут убиты, возвращайтесь к Аурастразе в Драконий Покой.', 'Отличная работа! Никто не смог сказать мне имя вожака магнатавров, зато мне удалось выяснить имя того, кто знает ответ на наш вопрос.', 'Тебе удалось сразить магнатавров?', NULL, NULL, 'Ледоскал убито', 'Кровавый Пир убито', 'Дракров убито', 'Рекомендуемое количество игроков: 2');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12150, 'Мастер рун-затворник', 'Дрегмар Рунический Знак – магнатаврский мастер рун. Редкая пташка. Обычно он держится особняком, но прежде водился с более могущественными и влиятельными магнатаврами Драконьего Погоста. Так что он должен знать, кто у них новый вождь.$B$BМы вряд ли дождемся помощи в борьбе с Плетью и синими драконами, так что получить эти сведения от Дрегмара совершенно необходимо.$B$BМне говорили, его можно найти среди утесов, что нависают над Зеркалом Рассвета.', 'Отыщите Дрегмара Рунического Знака неподалеку от его пещеры, на тропе, ведущей в утесы над Зеркалом Рассвета. Бросьте ему вызов и любой ценой узнайте имя повелителя магнатавров. Добыв нужные сведения, вернитесь к Аурастразе в Драконьем Покое.', 'Гром\'тар Громовержец. Хорошо. Этот магнатавр опасен – чем раньше мы покончим с этой угрозой, тем лучше.', 'Удалось ли тебе узнать имя? Кто теперь командует магнатаврами?', NULL, NULL, 'Имя вождя магнатавров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12151, 'Распоясавшийся полководец', 'Нет никаких причин подозревать, что слова Дрегмара не соответствуют действительности. Сразит ли Гром\'тар тебя или будет сражен тобой – его это уже не касается.$B$BСледуй его указаниям… возьми рог, что ты $gпринес:принесла: мне ранее, отправляйся к кругу факелов к югу от лазуритового святилища драконов и протруби в рог, чтобы объявить о своем вызове. Когда Гром\'тар Громовержец появится, убей его, а потом принеси мне его голову.', 'Отправляйтесь к кругу факелов к югу от лазуритового святилища драконов и протрубите в расписанный боевой рог. Сразите Гром\'тара Громовержца и принесите его голову Аурастразе в Драконий Покой.', 'Ты и впрямь великолепен.$B$BТеперь, когда Гром\'тара Громовержца больше нет, мы можем предоставить остаткам магнатавров перебивать друг друга и вновь обратить наше внимание на куда более серьезные угрозы.$B$BВпечатляющая работа, $C.', 'Тебе удалось покончить с этой угрозой?', NULL, NULL, 'Голова Гром\'тара', 'Расписанный боевой рог', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12152, 'Погибель Джин\'аррака', 'Я рад снова видеть тебя в мире живых. Многие из тех, что отправились по дороге смерти, так и не вернулись обратно. $B$BПока ты $gотсутствовал:отсутсвовала:, Краза посетило видение, которое открыло ему, что надо делать дальше.$B$BСвященное подношение лежит где-то в склепе. Возьми эту пыль духов, сотворенную из собранных тобой останков, и рассей ее над подношением. $B$BЗаряженное подношение положит конец правлению падшего вождя и освободит многие замученные души.$B$BДа пребудет с тобой мудрость предков, $N.', 'Краз из Лагеря Харкора просит вас найти cвященное подношение Драккари в руинах Дракил\'джина и осенить его пылью духов Драккари. После этого положите подношение к гонгам у руин Дракил\'джина.', '', NULL, NULL, NULL, 'Полководец Джин\'аррак повержен', 'Пыль духов Драккари', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12153, 'Тан и его Наковальня', 'Теперь, когда голем полностью заряжен, мы сможем направить его силу в нужное русло. Чтобы взять на себя управление, активируй его в периметре Дун Аргола. $B$BНаша информация о предводителе Дун Аргола, тане Гневном Топоре, свидетельствует о том, что его защищает личный телохранитель.$B$BЗовут это чудовище Наковальня, но оно не так неуязвимо, как кажется. Отключи этого голема – и тан останется беззащитным.$B$BТы найдешь нашего противника на вершине Дун Аргола, где он инспектирует производство.', 'Воспользовавшись боевым големом, убейте тана Гневного Топора, после чего вернитесь к Регару Бровебою в Лагерь горняков.', 'Все получилось?$B$B<Регар смущенно кашляет.>$B$BТо есть... конечно, я и не сомневался! Ты молодец!$B$BКогда-нибудь, Альтшифт, нашим детям будут рассказывать повесть о том, как Регар Бровебой победил тана Дун Аргола с помощью куска ржавого железа!', NULL, NULL, NULL, 'Железный тан Гневный Топор убито', 'Пульт управления големом', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12154, 'Затмение', 'В огромном помещении на вершине Дун Аргола находится источник энергии, питающий весь город. Если ты сможешь его уничтожить, то повергнешь в хаос весь Дун Аргол.$B$BБез энергии ни големы, ни часовые не будут функционировать; к тому же, отключится все освещение.$B$BНам выдали эту взрывчатку для раскопок, но тан Гневный Топор сорвал нашу работу. Впрочем, теперь она нам пригодится для других нужд – например, разрушить источник питания.', 'Воспользуйтесь взрывчаткой Регара, чтобы уничтожить руническое силовое ядро в Дун Арголе. Доложите о своем успехе Регару Бровебою из Лагеря горняков.', '<Регар одобрительно кивает.>$B$BХорошо, что взрывчатка наконец-то пригодилась.', NULL, NULL, NULL, 'Энергетический сердечник Дун Аргола уничтожен', 'Взрывчатка Регара', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12155, 'Разбей тыкву!', 'Посреди деревни лежит большая тыква. Взгляд ее горит мрачной злобой.$B$BРазбив тыкву, вы видите старый, опаленный священный символ.', 'Отдайте опаленный священный символ попечительнице сирот в маске.', 'Вы нашли это в тыкве всадника без головы? Это древний символ Света. Наверняка он прежде принадлежал всаднику, до того, как на него пало проклятье, и он превратился в чудовище. Спасибо вам, $N. Этот символ должно отдать паладинам.Я постараюсь, чтобы он попал к ним.$B$BО, я чуть не забыла! У вас есть тайный поклонник...$B$BОдин из моих подопечных хочет, чтобы я вам передала вот это. Он слишком стесняется, чтобы отдать вам это лично.', 'Да, $N?', NULL, NULL, 'Опаленный священный символ (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12156, 'DEPRECAED', 'Примерно час назад я должен был отправиться в Среброречье, к северо-западу отсюда, но мой эскорт еще не прибыл.$B$BБудь я проклят, если моя дипломатическая миссия сорвется из-за какого-то проспавшего рекрута!$B$BМы пытаемся наладить связь с местными обитателями, и сейчас каждая минут на счету. Послушай, может быть, ты согласишься сопроводить меня – за определенную плату?', 'Сопроводите посланца Альянса в Среброречье. Выполнив это задание, вернитесь к лейтенанту Думонту в Приют Янтарной Сосны.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12157, 'Пропавший курьер', 'Нам еще повезло, что мы добрались сюда, $N. Едва приземлившись, мы угодили в засаду Плети.$B$BОдин из наших оказался шпионом Культа Проклятых. А у Тассариана, похоже, есть и другие доказательства того, что тут замешаны сектанты. Похоже, они сумели пробраться на самый верх...$B$BОдин из моих лучших курьеров отправился на заставу в западном Драконьем Погосте, но до сих пор не вернулся. Боюсь, его перехватили прислужники Плети. Не согласишься ли ты отправиться в Драконий Погост и поискать его? Его зовут курьер Лансон.', 'Поговорите с курьером Лансоном в Покое Звезд, что в Драконьем Погосте.', 'Как только я миновал мост, ведущий в Драконий Погост, я угодил в засаду! Меня подстерег небольшой отряд воинов Ануб\'ара! Меня окружили! Эти чудовища знали, что я еду. Я чудом вырвался живым. Вот этот список необходимо доставить в крепость Стражей Зимы, но я слишком тяжело ранен, чтобы продолжать путь...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12158, 'Рудник Полого Камня', 'Я и сам собирался послать кого-нибудь проверить, что происходит на Руднике Полого Камня, но все как-то не было времени этим заняться. $gСам:Сама: понимаешь, Орда на западе и железные дворфы на востоке не дают скучать. $B$BВпрочем, если тебя послал Дюмонт – мне остается только указать тебе направление.$B$BВход в рудник находится на северо-западе, недалеко отсюда. Надеюсь, его еще можно использовать. Нам бы не помешал дополнительный источник ресурсов, пока мы не вернемся к разработке рудника в Далечье.', 'Обыщите Рудник Полого Камня к северо-западу от Лагеря дружины Западного Края.', 'Ты пришел меня спасти?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12159, 'Неупокоенные души', '$gПетров тяжело дышит и настороженно осматривает рудник.>$B$BТоварищи мои... их души должны обрести покой! Я убиваю их одного за другим, но... они возвращаются снова и снова!$B$BКажется, я знаю, что надо делать, но у меня не хватит смелости.$B$BМожет быть, ты возьмешься за это нелегкое дело? Возьми эту лампу и подожги с ее помощью их трупы, чтобы они больше не смогли восстать из мертвых. $B$BПомоги моим друзьям – и я отвечу на все твои вопросы!', 'Петров с Рудника Полого Камня просит вас поджечь с помощью шахтерского фонаря трупы 8 шахтеров с Рудника Полого Камня.', 'Покойтесь с миром, братья мои! Не волнуйтесь – я расскажу всем о вашем подвиге!', NULL, NULL, NULL, 'Упокоено шахтеров', 'Шахтерский фонарь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12160, 'Имя из прошлого', 'Получилось! Наконец-то мои товарищи смогут упокоиться...$B$BА я останусь здесь и закончу работу. Мы, шахтеры Полого Камня, всегда доводим любое дело до конца. И никогда не опускаем руки!$B$BВот почему Аругал ставит нас в пример. Мы не стали ему подчиняться, понимаешь? Мы отказались поклоняться культу Волка!', 'Вернитесь к капитану Гриану Камнегриву в Лагерь дружины Западного Края.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12161, 'Рууна Слепая', 'Эй! Я случайно подслушал твой разговор с капитаном, и подумал, что тебе надо кое-что узнать. Видишь ли... здесь, в Нордсколе, не все так просто, как кажется.$B$BДаже мертвецов нельзя сбрасывать со счетов.$B$BК юго-западу отсюда, рядом с Перевалом Фордрассил, живет колдунья, которая называет себя Рууна Слепая. Говорят, она может разговаривать с духами умерших, видеть прошлое и будущее.$B$BЯ толком не знаю, на что она способна, но тебе не помешал бы такой союзник.', 'Поговорите с Рууной Слепой, которая живет в Лагере Рууны рядом с Перевалом Фордрассил.', 'Ты ищешь знания, которые тебе недоступны. Но знай, незнакомец – тебе может не понравиться то, что ты услышишь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12162, 'Деревня Солнцестояния', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12164, 'Час ворга', 'Время пришло, $N. Аругал должен умереть.$B$BСобери несколько верных товарищей и отправляйся на Остров Кровавой Луны. Ты найдешь его на востоке, недалеко от побережья.$B$BМы нанесем стремительный удар. Возьми на себя лейтенантов Аругала, а я присоединюсь к тебе, когда дело дойдет до битвы с главарем.', 'Саша из Торговой лавки Белой Сосны посылает вас на Остров Кровавой Луны убить Селаас, Варлама, Вспоробрюха и Тень Аругала.', 'Мы хорошенько потрепали его, $N. Жаль, не удалось с ним покончить.$B$BВпрочем, теперь мы можем вздохнуть свободно – он не осмелится больше сунуть сюда свой нос.', NULL, NULL, NULL, 'Варлам убито', 'Селас убито', 'Вспоробрюх убито', 'Тень Аругала убита');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12165, 'Коварный план', 'Геолог Рокар решил нам помочь и разработал план, как обернуть изобретения железных дворфов против их самих. $B$BНадо признать, от нашего нового лучшего друга все-таки есть какая-то польза. В одном он точно прав – нас слишком мало, чтобы действовать открыто. $B$BИди в Дун Аргол, в заснеженный край на юго-востоке, и захвати чертежи их боевых големов, которые носят с собой железные кователи рун. Доставь чертежи Рокару – пусть приступает к осуществлению своего плана.', 'Принесите полный комплект чертежей боевого голема геологу Рокару в Лагерь Уанква.', 'Значит, Тормак одобрил мой план? Да... иначе он не стал бы тебя посылать.$B$BОх, беда, беда-огорчение... Как же мне теперь разобраться, что к чему в этих чертежах, когда Тормак дышит мне в спину?', 'Ты... ты принес чертежи?', NULL, NULL, 'Чертежи боевого голема', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12166, 'Жидкое пламя Элуны', '$gраса:, не поможешь мне?$B$BСилы плети вошли в деревню Ледяной Пыли к северу отсюда. Где бы они ни проходили, они повсюду сеют свою порчу, и невинные обитатели этой земли страдают.$B$BВозьми этот сосуд, наполненный жидким пламенем Элуны из Лунного колодца. Пожалуйста, воспользуйся этой жидкостью, чтобы очистить тела несчастных чумных животных, какие найдешь.', 'По просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд воспользуйтесь жидким пламенем Элуны для очищения трупов 6 гнилостных маралов и 6 бешеных гризли.', 'Мы сделали для существ, обитающих на этой земле, все, что могли. А теперь мы должны предпринять решительные действия против тех, кто причинил все это!', NULL, NULL, NULL, 'Очищено трупов гнилостного марала', 'Очищено трупов бешеного гризли', 'Жидкое пламя Элуны', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12167, 'Убить сектантов', 'Ануб\'арские сектанты виновны, пусть и косвенно, в эпидемии среди животных. Мы обязаны положить этому конец!$B$BПары, исходящие от костюмов сектантов, впитываются во все, что только есть поблизости, загрязняя и отравляя землю и воду!$B$BСтупай на север, в деревню Ледяной Пыли, и перебей их. Принеси те их костюмы, что останутся целы после битвы – я позабочусь о том, чтобы ликвидировать их должным образом.', 'Соберите 5 рабочих костюмов сектантов по просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд.', 'Молодец!$B$BЯ избавлюсь от этих гнусных одеяний, омыв их в Лунном колодце, а затем уничтожив их силой богини!', 'Сектанты – это язва на лике творения!', NULL, NULL, 'Рабочий костюм сектанта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12168, 'Памятный дар Зангуса', 'Надпись на обратной стороне памятного дара гласит:$B$B\"Моему любимому ученику. Если продолжишь делать успехи – я научу тебя невообразимым чудесам.$B$BА если нет – я тебя уничтожу!$B$BВсегда твой,$B$BВерховный сектант Зангус\"$B$BНесомненно, стража-смотрителя из Покоя Звезд это заинтересует.', 'Принесите памятный дар Зангуса стражу-смотрителю Джоди Песни Луны в Покой Звезд.', 'Итак, лидер сектантов раскрыл себя. У нас есть его имя.$B$BТщеславие и гордыня станут причинами его падения!', 'Я чувствую приближение чего-то нечистого.$B$BОно на тебе! Что это, Нортанс?', NULL, NULL, 'Памятный дар Зангуса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12169, 'Верховный сектант', 'Мне и раньше грезился Зангус, но без контекста, открытого тобой, я не знала, что все это значило. Ты $gвнес:внесла: ясность в видение, которым богиня одарила меня, и теперь я знаю, что его можно найти в Провале Наржуна к северу отсюда.$B$BТы знаешь свою цель, $N. Если можно положить конец страданиям этой земли, верховный сектант должен умереть!', 'По заданию Стража-смотрителя Джоди Песни Луны из Покоя Звезд убейте верховного сектанта Зангуса.', 'Теперь, когда верховный сектант уничтожен, остатки его сил могут быть сметены, а земля и ее обитатели постепенно восстановятся.$B$BСпасибо, $N. Пусть богиня освещает твой путь!', NULL, NULL, NULL, 'Верховный сектант Зангус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12170, 'Схватка в Черноречье', 'Вскоре после нашего появления Торговая Компания свернула свою деятельность и удрала отсюда. Не сомневаюсь, мерзкие гоблины испугались за свои жадные, трусливые задницы!$B$BНе могу сказать, что меня это огорчает – нашим машинам требуется топливо, а эти торгаши оставили без охраны множество лесопилок. Забрав оттуда припасы, мы могли бы без проблем добраться до Ледника Ледяной Короны.$B$BК несчастью, Альянсу пришла в голову та же идея. Мы должны их опередить! Отправляйся на лесопилку и помоги нам избавиться от присутствия воришек из Альянса.', 'Капитан налетчиков Кронн просит вас убить 10 представителей или игроков Альянса на Лесопилке Черноречья.', 'Отличная работа, $N. Мы еще не установили полный контроль над лесопилкой, но эта победа вплотную приблизила нас к цели.', 'Псы Альянса мертвы? Тогда победа будет за нами!', NULL, NULL, 'Убито представителей Альянса в Черноречье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12171, 'О предателях и предательстве', 'Думаю, этот список следует доставить главнокомандующему Халфорду Змеевержцу! Он командует 7-м легионом, стоящим в крепости Стражей Зимы на восточной границе Драконьего Погоста.$B$BЕсли кто-то из предателей, упомянутых в этом списке, находится в крепости Стражей Зимы... это может привести к катастрофе!$B$BСкорее, $N! Покажи этот документ Палене Серебряное Облако здесь, в Покое Звезд, и объясни, куда и зачем ты направляешься. Она даст тебе самого быстрого из своих гиппогрифов!', 'Покажите депешу Альянса Палене Серебряное Облако в Покое Звезд.', '<Палена читает записку.>$B$BБери самого быстрого из моих гиппогрифов, $R! Эти сведения необходимо срочно доставить главнокомандующему Змеевержцу!', 'Здравствуй, $C.', NULL, NULL, 'Депеша Альянса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12172, 'Настройка на Даларан', 'Добро пожаловать, маг.$B$BДо сих пор тебе, должно быть, интересно где же находится Даларан и как туда попасть. Я помогу тебе.$B$BНо прежде чем я научу тебя телепортироваться в наш великий город, тебе нужно настроиться на силовые линии Нордскола.$B$BВозьми этот кристалл настройки и используй его в провале под волноловом у Садов Лунного Покоя к западу отсюда. Тогда ты будешь $gготов:готова: выучить нужное заклинание.', 'По заданию проекции верховного мага Модеры в Покое Звезд настройтесь на силовые линии Нордскола.', 'Отлично. Если ты готов, то и я тоже.', NULL, NULL, NULL, 'Вы настроились на силовые линии Нордскола', 'Кристалл направления силовых линий', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12173, 'Настройка на Даларан', 'Приветствую тебя, маг.$B$BДолжно быть, тебе интересно, где же находится Даларан и как туда попасть. Я помогу тебе, если сумеешь пройти простенький тест.$B$BПрежде чем я научу тебя телепортироваться в наш великий город, тебе нужно настроиться на силовые линии Нордскола. Иначе ты просто умрешь в процессе перемещения!$B$BВозьми этот кристалл настройки и используй его в провале под волноловом у Садов Лунного Покоя к юго-западу отсюда. Тогда ты будешь $gготов:готова: узнать то, чему я могу тебя научить.', 'По заданию проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара настройтесь на силовые линии Нордскола.', 'Ладно. Если ты считаешь, что готов, давай не будем тратить мое время попусту.', NULL, NULL, NULL, 'Вы настроились на силовые линии Нордскола', 'Кристалл направления силовых линий', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12174, 'Главнокомандующий Халфорд Змеевержец', '$gПалена возвращает вам послание.>$B$BМетель доставит тебя к Стражам Зимы. Можешь поверить, это будет самый быстрый полет в твоей жизни. Отправляйся прямо сейчас!', 'Доставьте депешу Альянса главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы в восточной части Драконьего Погоста.', '<Прочитав послание, главнокомандующий сминает его в руке.>$B$BТы знаешь, где теперь все те люди, что перечислены в этом списке? Вон, посмотри – там, у главных ворот. Это они там свисают с арок.$B$BПриманка для вурдалаков…', 'Что у тебя, боец?', NULL, NULL, 'Депеша Альянса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12175, 'Серые шкуры воргов', 'Я тебе вот что скажу, $gдружище:подруга:: паршивая это работенка – заниматься обмундированием для солдат Орды!$B$BА тут еще эта волчица, Завоевательница Кренна, кнутом подгоняет. Вынь да положь ей полный комплект обмундирования к концу недели – иначе сбросит меня в яму к медведям.$B$BПомоги мне – а я уж в долгу не останусь. Мне нужны шкуры серо-дымчатых охотников.$B$BИх легко найти на севере, где они гоняются за оленями. Учти, я тебе хорошо заплачу!', 'Торговец шкурами Джун\'ик из Крепости Завоевателей просит вас добыть 3 серые шкуры ворга с серо-дымчатых охотников, которые водятся в лесах на севере.', '', NULL, NULL, NULL, 'Шкура серого ворга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12176, 'Мелкая подмена', 'Кренна хочет сменить обмундирование нашего войска и пошить новое из шкур воргов – а наших запасов, естественно, не хватит, чтобы одеть всю армию. Хоть ты лопни, не наберется у нас столько шкур!$B$BТощие они, эти ворги, и меха с них – кот наплакал. Но у меня есть идея! Могу и с тобой поделиться – если обещаешь держать язык за зубами.$B$BК востоку от Волдруна живут медведи гризли, жирные как огры. Их огромные шкуры мы могли бы пустить в дело!$B$BДавай, $gбратишка:сестренка:, принимайся за дело. Кренна ждать не любит.', 'Торговец шкурами Джун\'ик просит вас принести ему 6 шкур медведей гризли.', 'Я у тебя в долгу, дорогуша. Вот, держи свою долю.', 'Тащишь шкуры, дружище?', NULL, NULL, 'Шкура гризли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12177, 'Уловка Джун\'ика', 'Ой... кажется, у нас возникла проблема. Эти шкуры... они коричневого цвета! $B$BДумай, думай, голова...$B$BВо, придумал! Серый цвет – это помесь белого и черного, верно? Тащи сюда уголь и муку! Я их перемешаю и посыплю шкуры этой пудрой. Никто и не заметит!$B$BТак... уголь продают кузнецы, а муку можно достать у поставщика.', 'Принесите кусок угля и пять горстей простой муки торговцу шкурами Джун\'ику в Крепость Завоевателей в Седых холмах.', 'Скрести пальцы, дружище.', 'Ну, ты все принес?', NULL, NULL, 'Уголь', 'Простая мука', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12178, 'Сверток для Кренны', 'Вот, $gдружище:подруга:. Давай-ка отнесем эти шкуры Кренне и посмотрим, как она отреагирует.$B$BОчень надеюсь, что она ничего не заметит.', 'Отнесите связку шкур Кренне в Крепость Завоевателей.', 'За кого ты меня принимаешь? От этих шкур за километр пахнет мукой!$B$BХочешь оскорбить всю Орду?', 'Ты хоть знаешь, с кем разговариваешь?', NULL, NULL, 'Связка шкур (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12180, 'Пленные геологи', 'Регар послал в Дун Аргол отряд старателей, поручив им поиски артефактов и информации о происхождении сего поселения. Правда, они не ожидали обнаружить, что Дун Аргол до сих пор обитаем.$B$BТеперь железные дворфы держат их пленниками, пешками в грядущей войне. У нас нет людей, которых мы могли бы послать им на помощь, а Регар витает в облаках, мечтая о победе над железными дворфами без посторонней помощи.$B$BВся надежда на тебя, $N. Ключи от клеток могут быть у любого железного дворфа или его прислужника.', 'Освободите геолога Ганна, геолога Торгана и геолога Варана, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков.', '<Горный пехотинец Килиан внимательно слушает ваш пересказ слов пленных геологов.>$B$BГоворишь, они упоминали Локена и войну с каменными великанами? Ты ничего не перепутал?$B$BЗначит, Регар все-таки был прав. Надо найти способ пробраться внутрь и узнать, что они затевают.', NULL, NULL, NULL, 'Геолог Ганн спасен', 'Геолог Торган спасен', 'Геолог Варана спасен', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12181, 'Имя для заразы', 'Сколько дней, сколько бессонных ночей... Знаешь ли ты, как давно мы приступили к работе над этой проклятой чумой? Нас преследовали неудачи, но мы наконец одержали победу! Смотри! Я еще даже не придумал название для этой гнили... Точно! ГНИЛЬ! Эта гниль разрушит само представление о нетленности бытия!$B$B<Харрис протягивает вам склянку.>$B$BБеги к Тобиасу, дрессировщику нетопырей. Покажи ему этот образец – пусть он немедленно отправит тебя в Ядозлобь.', 'Покажите образец гнили Тобиасу Саркхоффу в Ядозлоби.', 'Э... все понятно, можешь не показывать мне образец. Я тебе верю.', 'Доставка смертельно ядовитого газа в Ядозлобь? Это ко мне!', NULL, NULL, 'Образец гнили (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12182, 'В Ядозлобь!', 'Вот, я оставил для тебя специального нетопыря. Он самый быстрый и ловкий из всех, что у меня есть! Доставит тебя прямо в Ядозлобь – глазом моргнуть не успеешь.$B$BА там просто передай этот флакон главному распространителю чумы Миддлтону.', 'Передайте образец гнили Главному распространителю чумы Миддлтону, который живет в Ядозлоби на востоке Драконьего Погоста.', 'О, превосходно! Ты только посмотри – прямо за горой, на северо-востоке, ползет целая армия Плети! С нее-то мы и начнем испытания.', 'Ты посыльный?', NULL, NULL, 'Образец гнили (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12183, 'Часть маскировки', 'Если геолог Варана права, и с Локеном общаются только некоторые высокопоставленные дворфы, то я могу поспорить, что в их число входят надзиратели.$B$BНам придется послать тебя на разведку под прикрытием, для чего надо раздобыть для тебя подходящую униформу. $B$BЗатем я постараюсь придумать, как загримировать тебя под одного из железных дворфов.$B$BВ общем, отправляйся в Дун Аргол, убей одного из надзирателей и принеси мне его униформу. Учти, зальешь ее кровью – будешь отстирывать $gсам:сама:!', 'Принесите униформу надзирателя горному пехотинцу Килиану в Лагерь горняков.', '<Килиан забирает у вас униформу.>$B$BСойдет. Извини, у меня нет времени вышивать на ней твое имя. Зато когда я закончу работать над твоим гримом, никто не отличит тебя от настоящего надзирателя!', 'Ты принес униформу?', NULL, NULL, 'Униформа надзирателя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12184, '$Nтесь, вас снимают!', 'Отлично! У нас есть униформа, и не хватает только немного дополнительной информации, чтобы сделать маскировку идеальной.$B$BЯ тут вспомнил, что Регар привез с собой фотокамеру – отснять результаты исследований, но мы найдем для нее другое применение. Возьми ее с собой в Дун Аргол и сделай несколько снимков железных дворфов.$B$BКонечно, твои модели вряд ли обрадуются такой популярности, так что тебе придется их немного... утихомирить. И не забудь вернуть мне камеру со снимками!', 'С помощью камеры Килиана сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков.', 'Прекрасные фотографии! С их помощью мы с легкостью замаскируем тебя под железного дворфа. Никто и не догадается!', 'Ты принес снимки?', NULL, NULL, 'Сфотографировано железных дворфов', 'Камера Килиана (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12185, 'Лучшая маскировка для Локена', 'С помощью этих изображений я смог сделать отличный набор для маскировки. $gДружище:Подруга:, из тебя получится отличный железный дворф!$B$BВот, возьми этот сверток в Дун Аргол, замаскируйся и отправляйся к самому восточному зданию на центральном ярусе.$B$BТам ты увидишь пьедестал, с помощью которого главы кланов и надзиратели получают указания от Локена. Прикоснись к нему и запомни все, что услышишь.', 'Замаскируйтесь под железного надзирателя рун, перехватите послание от Локена и передайте его горному пехотинцу Килиану в Лагерь горняков.', 'Неужто Локен не преувеличивает? Каменные и железные дети $Nв сражаются за власть в древнем городе Ульдуаре? Это безумие, Альтшифт, и оно может уничтожить наш единственный шанс узнать тайну происхождения расы дворфов!', NULL, NULL, NULL, 'Получено послание от Локена', 'Набор для переодевания в надзирателя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12188, 'Гниль Отрекшихся и вы: как не заразиться самим', 'Знать во всех подробностях о том, как действует гниль, тебе, пожалуй, ни к чему. Главное, свое дело она делает. Мне удалось вывести инертный штамм гнили.$B$B<Миддлтон открывает пробирку и вдыхает ее содержимое.>$B$BКак видишь, мое тело практически не пострадало. Но если теперь смешать это с нужным реактивом, все мы обратимся в бесформенные лужи слизи.$B$BНа побережье к югу отсюда находятся жалкие призраки древних солдат Альянса. Перебей их и принеси мне эктоплазменный осадок.', 'Принесите главному распространителю чумы Миддлтону из Ядозлоби в Драконьем Погосте 10 образцов эктоплазменного осадка.', 'Да, $N, это отлично подойдет. Что, эти жалкие существа хотя бы сопротивлялись, или только обливались призрачными слезами?$B$BОй, они такие чувствительные…', 'Осадок необходим для изготовления реактива, который активирует штамм!', NULL, NULL, 'Эктоплазменный осадок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12189, 'Меня окружают идиоты!', 'Груз из Нового Агамонда должен был прибыть в Ядозлобь на прошлой неделе, а потом его должны были передать мне после простейших полевых испытаний. Это последнее, чего недостает Орде для победы.$B$B<Синтар вздыхает.>$B$BКак же тяжко жить, когда кругом одни идиоты!$B$BОтправляйся в Ядозлобь, что близ восточных границ Драконьего Погоста. Отыщи этого шута Миддлтона и напомни ему, что я жду свой груз!', 'Отправляйтесь в Ядозлобь в Драконьем Погосте и поговорите с главным распространителем чумы Миддлтоном.', 'У нас тут, знаете ли, небольшая проблемка. Все, кто пытался иметь дело с этой заразой, испарились на месте. Мы работаем над тем, чтобы несколько изменить формулу. Ну, чтобы она не убивала на месте любого, кто взглянул на нее краем глаза. Но есть и хорошие новости. Мне, кажется, удалось получить нужный состав!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12190, 'Поздоровайся с моим маленьким другом', 'У Харкора челюсть отвалится, когда он увидит такие отборные продукты! Осталось только решить вопрос с доставкой.$B$BОн разбил лагерь на восточном краю леса, рядом с проклятыми руинами Дракил\'джин, так что добраться до него проще простого. Ну что, отнесешь ему ингредиенты – или предпочитаешь помочь мне с бальзамировкой трупов?', 'Пригмон просит вас отнести ингредиенты для Харкора в Лагерь Харкора.', 'Ух ты! Это от старины Пригмона?$B$BДа тут продуктов на целый пир! Правда, кое-чего не хватает...', 'Чего тебе?', NULL, NULL, 'Ингредиенты Харкора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12191, 'Пей до дна!', 'Эти дворфы из клана Черного Железа опять вернулись! Опять! Надо, чтобы ты $gсмог:смогла: дать им отпор, если что. Еще важнее, чтобы ты $gзащитил:защитила: нашу собственность! $B$BЧучелко, С.С.М., уже наготове? Выпей бесплатного пива на пробу и метни кружку в чучелко! Попади в цель пять раз, и возвращайся ко мне.', 'Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Биззлем Эхпрокачуном.', 'Ха... Крепкий С.С.М. ... Хмм... Кто бы мог подумать?$B$BТо есть ура, ты попал! Рука у тебя тверда, по крайне мере, лагерь защитишь. Теперь, думаю, ты вполне готов надавать Черному Железу, если эти дворфы вновь понабегут!', 'Хлебни из кружки, затем швырни ее в С.С.М. Ничего, потерпит. Я бы не стал его кра...делать, если бы не стерпело!', NULL, NULL, 'Вы попали в ССМ', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12192, 'Однажды, напившись в...', 'Нам удалось на время остановить клан Черного Железа, но они вернулись и жаждут мести! Они то и дело выныривают невесть откуда, выпивают наше пиво и убегают в \"Угрюмого обжору\". Первым делом нам надо защитить наш лагерь, если мы сохраним наш бочонок – это будет победа!', 'Поговорите с Биззлем Эхпрокачуном в лагере Хмельного фестиваля.', 'Значит, даже немалое количество выпитого пива не помешало тебе расстроить зловещие планы клана Черного железа? Вот это действительно в духе Хмельного фестиваля! Полагаю, ты заслужил призовые жетоны.$B$BСпасибо за помощь, Профессия. Веселого тебе Хмельного фестиваля!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12193, 'А не будет ли сувенирчика в нынешнем году?', 'Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.$B$BВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.', 'Найдите в лагере Хмельного фестиваля Белби Быстросмен, отдайте ей купон и получите бесплатную праздничную пивную кружку.', 'Ах-х, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$B$BЕще увидимся. Ты ведь захочешь отоварить и другие праздничные купоны... Помни, я вся твоя...$B$BИли его... $B$BМожет, его...', 'Что такое, красавчик? Ты ко мне по делу?', NULL, NULL, 'Купон на получение кружки Хмельного фестиваля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12194, 'А не будет ли сувенирчика в нынешнем году?', 'Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.$B$BПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.', 'Найдите в лагере Хмельного фестиваля Бликса Чиништукса, отдайте ему купон и получите бесплатную праздничную пивную кружку.', 'Что это? Купон на кружку? Любишь выпить? Отлично! Я дам тебе кружку, а ты пойди и выпей за мое здоровье! А потом еще немного выпей... А потом возвращайся сюда.$B$BВсе пути ведут ко мне, знаешь ли. Тебе придется отоваривать праздничные жетоны, штампы защитника бочек и так далее.$B$BКороче, вот кружка. Приходи, еще поболтаем.', 'Что такое, красавчик? Ты ко мне по делу?', NULL, NULL, 'Купон на получение кружки Хмельного фестиваля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12195, 'Незваный гость', 'Недавно наши охотники вернулись с вылазки с необычной добычей.$B$BОни наткнулись на раненого дворфа, бежавшего из крепости железных дворфов Дун Аргол. Возможно, он мог бы предоставить нам ценную информацию о нашем старом противнике, но пока что он не в состоянии говорить из-за сильной лихорадки.$B$BЯ слышал, что для изготовления лекарств отлично подходят рога серебристых оленей, которые бродят по ближайшему лесу. Если ты принесешь мне достаточное количество рогов, я позабочусь о том, чтобы разговорить нашего дорогого гостя.', 'Принесите 5 рогов взрослых оленей Тормаку Бывалому из Лагеря Уанква.', 'Да, эти рога вполне сгодятся для настойки. Посмотрим, поможет ли она.', 'Ты принес рога?', NULL, NULL, 'Рог взрослого оленя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12196, 'С самого начала', 'У нас слишком мало времени, чтобы самим браться за ковку. Литейные мастерские в Дун Арголе работают день и ночь, и пока мы выкуем детали для одного конструкта, они соберут десять таких же големов из готовых запчастей. $B$BТы $gдолжен:должна: вернуться обратно и раздобыть детали, упомянутые в этих чертежах.$B$BДолжно быть, они валяются повсюду вокруг зданий, где работают железные кователи рун. $B$BПоторопись, $N. Кажется, Тормак только и ищет предлога для того, чтобы выполнить свою угрозу!', 'Принесите 8 частей боевого голема геологу Рокару в Лагерь Уанква.', '<Рокар облегченно утирает пот со лба.>$B$BСлава Свету! Он грозился оставить меня без еды, пока ты не вернешься. Ладно, давай посмотрим, что тебе удалось раздобыть.', 'Т-ты ведь несешь мне запчасти, правда?', NULL, NULL, 'Часть боевого голема', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12197, 'Нам нужна энергия', 'Итак, я полностью закончил сборку оболочки голема, но Тормаку этого мало. Он просто не понимает, что механизм не заработает сам по себе, по его велению! Чтобы включить его, нам понадобятся батареи.$B$BВ Дун Арголе созданием зарядных ячеек занимаются два дворфа – рунический кузнец Дурар и рунический кузнец Каторн.$B$BЧтобы наш голем заработал, в него надо установить две энергобатареи.$B$BНайди этих рунических кузнецов. Их мастерские должны быть в самом центре Дун Аргола.', 'Принесите энергобатареи Дурара и Каторна Геологу Рокару в Лагерь Уанква.', '<Рокар выхватывает у вас энергобатареи.>$B$BОтлично! Заряд очень низкий, но, во всяком случае, мы сможем запустить голема. Правда, для битвы он еще не готов.', 'Ты нашел энергобатареи?', NULL, NULL, 'Энергобатарея Дурара', 'Энергобатарея Каторна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12198, '... а может быть, и нет', 'Энергобатарея голема практически разряжена. Ее заряда хватит для питания двигателя, но на оборонные системы можно не рассчитывать.$B$BК счастью, периметр Дун Аргола патрулируют грозовые караульные – от них мы сможем подзарядить батарею.$B$BПодведи голема поближе, и он впитает энергию после смерти часового.', 'Подзарядите вашего Боевого голема от десяти грозовых караульных и вернитесь к геологу Рокару в Лагерь Уанква.', 'Ну вот – эта штучка готова к бою. Может, Тормак хоть теперь угомонится?$B$BНадеюсь, эта корова-переросток отпустит меня после того, как ты проложишь себе путь в Дун Аргол...', 'Ты подзарядил голема? Тормак опять проявляет беспокойство...', NULL, NULL, 'Уровень заряда', 'Пульт управления големом', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12199, 'Свержение железного тана', 'Теперь, когда голем полностью заряжен, мы сможем свергнуть предводителя Дун Аргола с его помощью.$B$BПока я шпионил за таном Гневным Топором, я заметил, что его повсюду сопровождает личный голем-телохранитель.$B$BЗовут это чудовище Наковальня, но он не так неуязвим, как кажется. Один электромагнитный импульс может разрушить его изнутри и отключить защитную функцию. Возьми нашего голема и активируй его в периметре Дун Аргола.$B$BТы найдешь тана на вершине главного завода, где он инспектирует производство.', 'Воспользовавшись особой функцией вашего Боевого голема, убейте железного тана Гневного Топора, после чего вернитесь к Тормаку Бывалому в Лагерь Уанква.', 'Значит, геолог сдержал слово? Это хорошо. Я уж было начал сомневаться в целесообразности его работы.$B$BЖаль, но больше он нам не пригодится.', 'Пожалуйста, скажи мне, что все получилось...', NULL, NULL, 'Железный тан Гневный Топор убито', 'Пульт управления големом', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12200, 'Слезы изумрудного дракона', 'Теперь, когда инертный образец чумного состава завершен и у нас имеется активирующее его вещество, остается лишь найти подходящее вместилище для этих компонентов.$B$BК юго-западу отсюда, на берегах в центре Драконьего Погоста, находится Изумрудное святилище драконов. Внутри святилища ты найдешь затвердевшие остатки слез зеленого дракона. Я не знаю всей истории, но, видимо, перед смертью они немало плачут. Иди $gсам:сама: посмотри.$B$BОтправляйся в Изумрудное святилище драконов и принеси оттуда слезы.', 'Принесите 8 слез изумрудного дракона главному распространителю чумы Миддлтону в Ядозлобь в Драконьем Погосте.', 'Я уверен, что настой порчи теперь готов к полевым испытаниям. По счастливой случайности силы жуткой цитадели Наксрамас осаждают крепость Стражей Зимы. Прямо из-под земли, на которой выстроена крепость, лезут ожившие мертвецы, жаждущие выполнить волю Кел\'Тузада.$B$BСилы Альянса, естественно, уступают и численно, и в отношении вооружения. Люди, упокоенные в усыпальнице Стражей Зимы, восстают из мертвых, алкая плоти!$B$BМожет, дать им испробовать вкус чумы, а?', 'Нам повезло, что рядом с нами есть место, в котором в избытке слезы изумрудных драконов. Иначе мне пришлось бы посылать тебя за ними в Фералас.', NULL, NULL, 'Слеза изумрудного дракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12201, 'Тень надзирателя', 'Похоже, этот Локен стоит за всеми приготовлениями к войне со стороны железных дворфов.$B$BБоюсь, что приказы от него получают только высокопоставленные дворфы, поэтому нам придется замаскировать тебя под надзирателя. Только так ты сможешь узнать, что они замышляют.$B$BЯ знаю, как это сделать, но мне понадобятся кое-какие материалы.$B$BДля начала тебе придется убить одного из железных надзирателей рун в Дун Арголе на юго-востоке и принести мне его униформу.', 'Принесите униформу надзирателя Разведчику Вор\'такху в Лагерь Уанква.', 'Отлично, эта униформа нам очень пригодится. Но нам понадобится еще кое-какой грим. Иначе даже эти тупоголовые железные дворфы узнают в тебе переодетого шпиона.', 'Ты принес униформу?', NULL, NULL, 'Униформа надзирателя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12202, '$Nтесь, вас снимают!', 'Теперь нам осталось только сделать тебя $gпохожим:похожей: на железных дворфов.$B$BХорошо бы иметь перед собой образец, с которого мы будем копировать их мерзкие рожи.$B$BЯ тут вспомнил, что однажды охотничий отряд Тормака наткнулся на заблудившегося геолога и отобрал у него фотокамеру в качестве трофея. Пожалуй, теперь она нам пригодится.$B$BВозьми ее с собой в Дун Аргол, убей несколько железных дворфов и запечатлей их физиономии. Как сделаешь достаточное количество фотографий, возвращайся ко мне.', 'С помощью камеры Рокара сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к Разведчик Вор\'такху в Лагерь Уанква.', 'То, что надо! Во имя Гарроша, ну и мерзкие рожи!', 'Снимки готовы?', NULL, NULL, 'Сфотографировано железных дворфов', 'Камера Рокара (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12203, 'Приказы Локена', 'Вот, я собрал все, что надо для того, чтобы замаскировать тебя под надзирателя. Знаю, выглядит мерзко, но ты уж постарайся сдержать свои эмоции, когда будешь напяливать эту гадость. Ну, ты понимаешь – надо, чтобы в тебе никто не усомнился.$B$BДержи маскировочный набор и отправляйся на юго-восток, к Дун Арголу. Там переоденься и иди к самому восточному зданию в центральной части города.$B$BТам ты увидишь пьедестал, где надзиратели получают указания от Локена. Прикоснись к пьедесталу и запомни все, что услышишь.', 'Замаскируйтесь под железного надзирателя рун, перехватите послание от Локена и передайте его разведчику Вор\'такху в Лагерь Уанква.', 'Значит, он собирается развязать гражданскую войну между детьми $Nв? Странно... Зачем ему город древних богов, Ульдуар? Впрочем, Курун и его великаны постараются не допустить его вмешательства.$B$BЧто ж, я сомневаюсь, что мы в состоянии удержать великанов от распрей, но мы можем воспользоваться этой ситуацией в своих целях. Надо немедленно известить наших командиров!', 'Что тебе сказал Локен?', NULL, NULL, 'Получено послание от Локена', 'Набор для переодевания в надзирателя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12204, 'Во имя Локена', 'Железные дворфы были и остаются нашими самыми организованными и жестокими конкурентами за влаcть в Нордсколе. Куда бы мы не сунулись, они всюду преследуют нас с именем Локена на устах.$B$BМы должны узнать, кто такой этот Локен и чего он добивается.$B$BК северо-востоку отсюда есть Торговая лавка Красного леса, в которой торгует человек по имени Хью Гласс. А на востоке, среди Руины Тетиса, обитает каменный великан Гаврок. Эти двое могут рассказать тебе кое-что полезное о Локене.', 'Поговорите с Хью Глассом и Гавроком о Локене, после чего передайте полученные сведения разведчику Вор\'такху из Лагеря Уанква.', 'Значит, он руководит военной кампанией железных дворфов? Мы должны узнать, что они замышляют!', NULL, NULL, NULL, 'Хью Гласс допрошен', 'Гаврок допрошен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12205, 'Разыскивается: Алый Натиск', 'Приказом верховного палача Роса все члены незаконной организации, известной как Алый Натиск, подлежат немедленной казни на месте!$B$BПощады не давать никому. Тем, кто участвует в этом деле, следует иметь в виду, что любой, попавший в плен к людям, будет убит, или того хуже.$B$BКак сказал верховный палач, \"Пусть белый снег станет красным от их крови!\"', 'Убейте 20 членов Алого Натиска и доложите об этом верховному палачу Росу из Ядозлоби.', 'Отлично, отлично, $R! Полагаю, убитые успели помучиться перед смертью?$B$BНу-ка, сейчас погляжу, что ценного завалялось у нас в гробах… кхм, прошу прощения – у нас в сундуках.', NULL, NULL, NULL, 'Убито членов Алого Натиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12206, 'Испорченные последние ритуалы', 'Ты $gчитал:читала: доску объявлений? Что думает верховный палач?$B$B<Вики оглядывается и продолжает на пониженных тонах.>$B$BМы же не можем позволить, чтобы этих идиотов из Алого Натиска подняли их жрецы или, что еще хуже, чтобы они были подняты как воины Плети, правда?$B$BНет, я полностью с тобой согласна, мы просто должны что-то сделать с телами.$B$BИ у меня есть то, что нужно. Возьми этот настой порчи, что мы только что изготовили, и опробуй его на пленнике, сидящем в клетке – здесь, рядом.$B$BНикаких заморочек – никакого возвращения врагов.', 'По просьбе аптекаря Вики Левин из Ядозлоби испробуйте настой порчи на узнике Алого Натиска.', 'ЧТО?! Это невозможно. Мы же сделали настой совершенным. У этого состава – стопроцентная смертность!$B$B<Аптекарь заламывает руки, ее лицо нежити охвачено тревогой. Явно расстроенная, она сердито продолжает.>$B$BВсе это очень странно. Передай-ка мне флакон, $C. Я не желаю, чтобы обо мне говорили как об аптекаре, который провалил все дело!', 'Ну что там, готово?$B$BЭй, я ж забыла тебе сказать, чтобы ты по возможности на себя не пролил этого добра! Гадкое зелье, пятна потом не выведешь, не говоря уж о том, сколько времени придется залечивать язвы и раны от отваливающихся кусков плоти.', NULL, NULL, 'Опробован настой порчи', 'Настой порчи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12207, 'Падение Фордрассила', 'Давным-давно некие могущественные друиды посадили мировое древо на северо-востоке.$B$BИмя ему было Фордрассил. По неведомой причине те же самые друиды решили уничтожить его, когда оно выросло.$B$BИ вот, с тех пор, как мы прибыли сюда, я слышу плач земли. Она стонет, ибо ядовитая слизь разъедает ее в тех местах, где упали обломки великого древа. $B$BПрошу тебя, принеси мне образцы этой слизи, и я попытаюсь исцелить землю.', 'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас отправиться к Ветвям Фордрассила, Сердцу Фордрассила или Слезам Фордрассила и принести ей 6 образцов слизи энтропических слизнюков.', '', NULL, NULL, NULL, 'Образец слизи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12208, 'Удачи в охоте за троллями!', 'Никчемные твари!$B$BНеужели нельзя было договориться по-хорошему? Мы протянули им руку мира! Им оставалось только предоставить нам безопасный проход через Драк\'Тарон – и мы бы оставили их в покое. $B$BНо нет, эти заносчивые ледяные тролли решили, что они хотят войны. Теперь мы сотрем их с лица земли и захватим их драгоценную крепость!$B$BМы уже наняли банду головорезов, которые будут поставлять нам захваченных троллей для допроса. Поговори с Самиром, если ты тоже не хочешь оставаться в стороне. Его легко найти на северо-западе отсюда, к югу от Зеб\'Халека.', 'Сержант Туркин отправил вас к Самиру в Гранитные ключи.', 'Тоже хочешь поохотиться за ледяными троллями?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12209, 'Кража материальных ценностей', 'Ах, да, свежее мясо прибыло. Хочешь проявить себя, салага?$B$BВоины Алого Натиска – самого фанатичного и расистского крыла Алого ордена – у нас уже под самым носом, к югу. Если мы хотим с ними сразиться, нам понадобится больше доспехов и оружия, чем я сумею раздобыть за столь короткое время.$B$BПочему бы нам не позаимствовать их вооружение?$B$BЯ бы даже сказал, почему бы ТЕБЕ его не позаимствовать?', 'По заданию интенданта Бартлетта из Ядозлоби похитьте 8 доспехов Алого Натиска и 8 единиц оружия Алого Натиска.', 'Что-то от тебя не слишком свежо пахнет, молодое мясо.$B$BЛадно, весь этот хлам сгодится. Как тебя звать-то, $C?', 'Я возьму любое оружие и доспехи, какие ты найдешь, молодое мясо.$B$BХотя качество их будет ужасным по сравнению с тем, что можно изготовить здесь, но это все же лучше, чем ничего...', NULL, NULL, 'Доспех Алого Натиска', 'Оружие Алого Натиска', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12210, 'Сезон охоты на троллей!', 'Эй, $r! Хватит стоять столбом, у нас полно работы!$B$BМы нашли самый короткий путь в Зул\'Драк – через Крепость Драк\'Тарон. Мы должны захватить ее, чтобы обеспечить безопасный проход для войск Альянса. А пока мы собираем армию для осады крепости, самое время заняться истреблением ледяных троллей и сбором разведданных.$B$BДля этих целей мы собрали отряд головорезов, которые будут захватывать и доставлять к нам живых троллей для допроса. Отправляйся на северо-запад, к Гранитным ключам, и поговори с Самиром. Он скажет тебе, что делать дальше.', 'Лейтенант Думонт из Приюта Янтарной Сосны послал вас поговорить с Самиром в Гранитных ключах.', 'Что, ты тоже решил стать охотником за головами?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12211, 'Не дадим им подняться!', 'Я просто не понимаю. Этот настой должен был сработать!$B$BНу, нечего теперь об этом беспокоиться.$B$B<По какой-то причине аптекарь вовсе не выглядит сильно расстроенной.>$B$BХотя он по каким-то причинам не подействовал на этих, из Натиска, мы все же должны сделать так, чтобы их жрецы не смогли поднять трупы.$B$BУ меня есть другая идея – идея, против которой у трупов нет никакой защиты.$B$B$N, возьми мою клетку с крысами и выпусти их на любые тела Алого Натиска, на какие наткнешься в Новом Дольном Очаге. Я морила голодом этих тварей, так что они должны оказаться весьма прожорливыми!', 'По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь ее клеткой с крысами в Новом Дольном Очаге, чтобы ободрать дочиста 15 тел, принадлежащих Алому Натиску.', 'Ох! На секунду мне показалось, что придется тестировать этих крыс на ком-то еще, чтобы удостовериться, что они не дефективные.$B$BНаконец-то, хоть какой-то прогресс!', NULL, NULL, NULL, 'Обглодано до костей тел Алого Натиска', 'Клетка с крысами', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12212, 'Пополнение запасов', 'Доброго тебе дня, $C.$B$BВон тот славный лейтенант утверждает, что набег Орды на наши склады практически оставил нас без продовольствия.$B$BМы, конечно, заставим этих мерзавцев пожалеть о содеянном, но сначала нам надо восполнить наши запасы. Мои люди трудятся не покладая рук, без твоей помощи нам не обойтись.$B$BПолагаю, тебе не составит труда добыть немного оленины – в этих краях полно диких оленей. Удачной охоты!', 'Старший лесник Андорхол из Приюта Янтарной Сосны просит вас убить несколько высокорогих оленей и принести ему 8 кусков сочной оленины.', 'Какие отборные куски мяса!', 'Как идет охота, $R?', NULL, NULL, 'Сочная оленина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12213, 'Подземная тьма', 'Что-то страшное случилось с этим деревом, Фордрассилом. После того как друиды уничтожили мировое древо, его обломки пустили корни глубоко в землю.$B$BЯ хочу, чтобы ты $gразыскал:разыскала: три части великого ствола, упавших далеко на севере-востоке, и $gуглубился:углубилась: как можно дальше под землю.$B$BКак только ты окажешься на месте, воспользуйся этим шаром, чтобы замерить выброс энергии. Возможно, наши исследования прольют свет на тайну уничтожения мирового древа.', 'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас отыскать Сердце Фордрассила, Слезы Фордрассила и Ветви Фордрассила, углубиться под землю и воспользоваться Геомантской сферой для измерения уровня энергии.', 'Этот шар... он вобрал в себя... чудовищно темную силу.$B$BЯсно одно: я должна как можно быстрее закончить исследования энергии и уничтожить ее вместилище.', NULL, NULL, NULL, 'Замерен выброс энергии под Сердцем Фордрассила', 'Замерен выброс энергии под Ветвями Фордрассила', 'Замерен выброс энергии под Слезами Фордрассила', 'Геомантская сфера');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12214, 'Новые кони', 'Здравствуйте, я Ханзел. Рад познакомиться, $gгосподин:госпожа:.$B$BВерховный палач пришел ко мне и говорит: \"Ханзел, раздобудь нам новых коней\".$B$BА где я ему возьму этих коней? Из-под земли достану?$B$B<шепотом: На самом деле можно и из-под земли, главное, найти подходящий скотомогильник...$B$BНо скотомогильников у нас под рукой нет, так что придется вам отправиться на юг, в Новый Дольный Очаг, чтобы убивать там рыцарей и забирать их боевых скакунов.$B$BВернитесь на коне ко мне сюда и передайте мне поводья.', 'Украдите 3 боевых коней Алого Натиска и доставьте их Ханзелу Бауэру в Ядозлобь. Передайте Ханзелу поводья из рук в руки.', 'Ну что может быть лучше хорошо выполненной работы?$B$BДобыв этих коней, ты оказал Ядозлоби большую услугу, $C.', 'Очень удачно вы подвернулись. А то я уж боялся, что придется самому идти коней добывать!', NULL, NULL, 'Переданы поводья боевого коня Алого Натиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12215, 'Мы или они!', 'Вот только этого нам еще не хватало...$B$BНынешний кризис продовольствия поставил нас в такое тяжелое положение, что мы вынуждены бороться за каждый кусок мяса с местными воргами. Ситуация ухудшается с каждым днем, и я боюсь, что скоро мы просто истребим всю дичь в округе. $B$BОтправляйся в лес, $r, и убей всех воргов, которые попадутся тебе на пути. Мои разведчики видели целую стаю на другом берегу реки к западу отсюда.', 'Андерхол из Приюта Янтарной Сосны просит вас найти и убить 6 серо-дымчатых охотников в Седых холмах.', 'Отличная работа, $С.$B$BТеперь мы можем быть уверены, что добыча в этих лесах достанется только нам.', NULL, NULL, NULL, 'Серо-дымчатый охотник убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12216, 'Бери самое нежное!', 'Хотя мы еще не достигли поставленной цели, наш упорный труд уже начал приносить плоды. Увы, теперь стало очевидно, что местных оленей не хватит, чтобы обеспечить пропитанием всех жителей. $B$BБоюсь, нам придется обратить внимание на более опасную добычу – медведей гризли. В Седых холмах они водятся в изобилии, питаясь рыбой из многочисленных ручьев.$B$BУдачи тебе!', 'Андерхол из Приюта Янтарной Сосны просит вас добыть 8 боков медведей гризли, которые водятся в Седых холмах.', 'Превосходно!$B$BТеперь на наших складах достаточно мяса. Спасибо тебе за помощь, $N.', 'Смотрите все: вернулся наш герой!', NULL, NULL, 'Бок гризли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12217, 'Орлиный взор', 'Итак, $N, теперь мы знаем, каким образом Орде удается выслеживать наши склады с продовольствием. $B$BОни магическим образом привязывают свой дух к зрению ничего не подозревающих орлов, которые кружат над верхушками деревьев. С их помощью они безнаказанно шпионят за каждым нашим шагом.$B$BПо приказу лейтенанта мы должны уничтожить этих величественных птиц, попавших под влияние наших врагов.', 'Андерхол из Приюта Янтарной Сосны просит вас убить 5 императорских орлов и доложить ему о выполнении задания.', 'Знаю, это было нелегко. Но теперь мы можем вздохнуть спокойно – враги больше не смогут шпионить за нами.', NULL, NULL, NULL, 'Императорский орел убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12218, 'Добрые вести не ждут на месте', 'Прежде чем я смогу отправить тебя к доктору Злобениусу с хорошими новостями, тебе придется еще провести обычное полевое испытание, но с некоторыми изменениями.$B$BИз останков старой крепости Стражей Зимы по-прежнему прут проголодавшиеся покойники. Выезжай на машине из восточных ворот и направляйся на северо-восток, через перевал Возмездия, пока не доберешься до двух башен на юго-восточной окраине крепости. Метни чумную бомбу в нежить, которая там кишит. И доложи мне о результатах!', 'Используйте чумную бомбу распространителя гнили Отрекшихся, чтобы уничтожить 30 голодающих покойников на краю Полей Падальщиков по приказу главного распространителя чумы Миддлтона из Ядозлоби в Драконьем Погосте.', 'Меня, конечно, бесит, что мы невольно помогаем Альянсу, но тем не менее полевые испытания прошли успешно! Тебя ждет Молот Агмара!', NULL, NULL, NULL, 'Проголодавшийся покойник убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12219, 'Обломки мирового древа', 'Давным-давно мои предки посадили дерево в самом сердце Седых холмов.$B$BБудущее мировое древо было названо Фордрассил.$B$BОднако когда дерево выросло, по неведомым мне причинам его решили уничтожить. Гигантский ствол раскололся на три обломка, которые упали далеко на севере.$B$BНо в том месте, где они коснулись земли, из-под обломков начала распространяться омерзительная слизь, заражая все вокруг. Пожалуйста, принеси мне несколько образцов этой заразы, чтобы я смогла найти способ излечить землю.', 'Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Ветви Фордрассила, Сердце Фордрассила или Слезы Фордрассила и принести ей 6 образцов слизи энтропических слизнюков.', '', NULL, NULL, NULL, 'Образец слизи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12220, 'Темное влияние', 'Когда Фордрассил был уничтожен, его обломки пустили корни глубоко в землю.$B$BЯ хочу, чтобы ты $gразыскал:разыскала: три части великого ствола, упавших далеко на севере, и $gуглубился:углубилась: как можно дальше под землю.$B$BКак только ты окажешься на месте, воспользуйся этим шаром, чтобы определить выброс энергии в этом месте. Если мы хотим исцелить землю, нам прежде всего надо выяснить, что привело к гибели мирового древа.', 'Иерофант Тайрин из Приюта Янтарной Сосны просит вас отыскать Сердце Фордрассила, Слезы Фордрассила и Ветви Фордрассила, углубиться под землю и воспользоваться Геомантской сферой для измерения уровня энергии.', 'Сила, заключенная в этом шаре... она огромна...$B$BВся земля вокруг обломков Фордрассила пропитана темной энергией. Мы должны узнать больше об этом явлении!', NULL, NULL, NULL, 'Замерен выброс энергии под Сердцем Фордрассила', 'Замерен выброс энергии под Ветвями Фордрассила', 'Замерен выброс энергии под Слезами Фордрассила', 'Геомантская сфера');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12221, 'Гниль Отрекшихся', 'Я подготовил пакет, который нужно доставить доктору Синтару Злобениусу в Молот Агмара. Содержимое этого пакета составляет окончательный образец гнили вместе с инструкциями по изготовлению и образцами реагентов.$B$BМолот Агмара находится в западной части Драконьего Погоста. Как увидишь черные зубчатые металлические орочьи здания, – это и есть Молот Агмара.', 'Доставьте образец гнили Отрекшихся доктору Синтару Злобениусу в Молот Агмара.', 'БДоктор Злобениус просматривает содержимое пакета.>$B$BПревосходно! Точь-в-точь по прописям!$B$BВот твоя плата, $N. Держи рот на замке обо всем, что ты видел и делал. Это совершенно секретная работа – информация выдается только по принципу \"необходимого знания\".', 'Что ж, пора как никогда!', NULL, NULL, 'Гниль Отрекшихся (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12222, 'Тайны прядильщиц пламени', 'Пока мы пытаемся дать отпор Орде, клан Укротителей драконов вербует новую армию в деревне Волдрун, которая находится у побережья на юге.$B$BСамые могущественные воины в этой деревне носят огнепрочные талисманы, которые дают им власть над могущественными протодраконами. Нам бы подчинить себе этих драконов – и можно было бы не опасаться угрозы, исходящей из Волдруна!$B$BА создают эти магические талисманы огневязы из клана Укротителей драконов. Убей их и принеси мне амулеты!', 'Принесите 3 огнепрочных талисмана плотнику Дрейку в Приют Янтарной Сосны.', 'С этими талисманами нам не составит труда подчинить протодраконов. Ты только представь себе выражение лица тана, когда он увидит, что ты командуешь его протодраконами!', 'Ты нашел талисманы?', NULL, NULL, 'Огнепрочный талисман', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12223, 'Ослабление врага', 'Наши разведчики докладывают, что врайкулы опять проявляют бурную активность в южной деревне Волдрун. Тан Торвальд Эрикксон и его шавки готовятся к войне. А пока большинство наших людей разбираются с подлыми засадами ордынцев, Приют Янтарной Сосны не сможет оказать сопротивления захватчикам!$B$BОтправляйся на южное побережье, в Волдрун, и покажи этим Укротителям драконов, что нас лучше обходить стороной.$B$BУбей всех хускерлов, которые встретятся тебе на пути. Пусть они дважды подумают, стоит ли с нами связываться.', 'Убейте 12 хускерлов из клана Укротителей драконов и вернитесь к плотнику Дрейку в Приют Янтарной Сосны.', 'Отличные новости, $N. Однако, не будем останавливаться на достигнутом! Надо воспользоваться нашим преимуществом.', NULL, NULL, NULL, 'Хускерл из клана Укротителей драконов убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12224, 'Авангард кор\'крона', 'Ты молодец, $gбрат:сестра:. Во всех своих деяниях ты $gпоказал:показала: себя $gверным:верной: $gзащитником:защитницей: Орды. Ты $gпопирал:попирала: ногами воинов Ануб\'ара из Азжол-Неруба! Именно благодаря тебе у Орды теперь есть новые союзники, таунка, сильные и отважные! И наше супер-оружие в войне с Плетью также испытано и усовершенствовано тобой!$B$BПришел час твоей славы – тебя ждет наше элитное подразделение у Врат Гнева. Сын Саурфанга ждет твоего прихода в авангард кор\'крона! Твой путь лежит на северо-восток, к Вратам Гнева.', 'Явитесь к Саурфангу Младшему в авангард кор\'крона.', 'Лок\'тар огар! Я наслышан о тебе, $N. На тебе немало глубоких боевых шрамов – это свидетельство отваги и верности!$B$BТеперь силы Короля-лича на западе и востоке почти подавлены, остаются лишь войска, обороняющие ворота. Мы каждый день понемногу продвигаемся вперед. Скоро мы проломим эту стену и ворвемся в Ледяную Корону!$B$BКак только мы остановим драконов-скелетов, мы с верховным лордом Фордрагоном двинемся вперед.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12225, 'М-м-м... Янтарные желуди!', 'Вы чувствуете аппетитный запах сочных орехов, доносящийся из корзинки с семенами, и ваш желудок протестующе урчит.$B$BВидимо, какая-то добрая душа оставила здесь эти семена для подкрепления уставших путников. Вы с благодарностью съедаете оставшиеся орешки.$B$BВкус у этих семян еще лучше, чем запах! Теперь вы непременно хотите узнать, где можно достать еще больше этого лакомства.', 'Поговорите с искусным резчиком по дереву Андерхолом в Приюте Янтарной Сосны.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12226, 'Ух, пронесло!', 'Надо действовать быстро, $r! Нельзя допустить, чтобы эти драгоценные семена полностью разложились. Мы должны извлечь их, и немедленно!$B$BСкорее, принеси мне несколько стеблей чернокорня – он растет на берегу реки к западу отсюда – и я сделаю тебе эффективное слабительное.$B$BНу что ты стоишь столбом, беги! В конце концов, ты $gсам виноват:сама виновата:...', 'Андерхол из Приюта Янтарной Сосны просит вас принести ему 5 стеблей чернокорня.', 'Да, эти стебли вполне сгодятся...$B$B<Андерхол ловко скручивает стебли, выжимая вязкий сок в маленькую бутылочку.>$B$BВот так! А теперь – за дело!', 'Неужели так сложно найти чернокорень?', NULL, NULL, 'Стебель чернокорня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12227, 'За дело!', 'Держи слабительное, $r.$B$BУчти – оно срабатывает мгновенно, так что сначала отыщи отхожее место и запрись там покрепче.$B$BВсе, иди за желудями!', 'Андерхол из Приюта Янтарной Сосны просит вас взять слабительную настойку Андерхола и воспользоваться ближайшим туалетом, чтобы извлечь частично переваренные янтарные желуди.', '', NULL, NULL, NULL, 'Частично переваренные янтарные желуди', 'Слабительная настойка Андерхола', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12229, 'Возможная связь', 'Не так давно мы отправили на восток экспедицию, которую растерзали бешеные фурболги. Единственный выживший рассказал, что видел странную темную жидкость, вытекавшую из тела убитого нападавшего.$B$BМногие тысячи лет фурболги жили в мире друг с другом и с окружающими. Мне кажется, что их агрессивность как-то связана с этой темной жидкостью и со зловещей силой, которую мы обнаружили ранее.$B$BПожалуйста, принеси мне несколько образцов крови фурболгов. Ты найдешь их в Святилище Красного Клыка и Святилище Кровавого Сердца, которые находятся на востоке.', 'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас принести 8 образцов крови безумных фурболгов, обитающих в Святилище Кровавого Сердца и Святилище Красного Клыка.', '', NULL, NULL, NULL, 'Кровь безумного фурболга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12230, 'Кража у осадных мастеров', 'Мне поручено уничтожить баллисты Алого Натиска. К сожалению, мы с аптекарями расходимся во мнениях касательно использования имеющихся ресурсов, так что мне просто нечем их уничтожить!$B$BК северо-востоку отсюда находятся Поля Падальщиков. Осадные мастера Плети со своей кузницей и полными повозками мяса большие мастера разрушения.$B$BК счастью для нас, они оставляют без присмотра свои бомбы.$B$BЯ хочу, чтобы ты $gраздобыл:раздобыла: их для меня. И мне все равно, где ты их достанешь: поднимешь с земли или отберешь у осадных мастеров.', 'По поручению Стража смерти Молдера из Ядозлоби раздобудьте 6 осадных бомб.', '<Страж смерти в предвкушении потирает руки.>$B$BОтлично. Что у них с возу упало, ко мне… ммм, к нам попало!$B$BУ тебя как, проблем не возникло по дороге? Кое-что тут выглядит очень нестабильно. Я, может, и нежить, но своим существованием очень даже дорожу!', 'Думаешь, они разрешили бы мне как-то с толком использовать распространителей гнили?.. Например, зарядить их чем-нибудь гадким, чтобы разрушить баллисты.$B$BНо нет, мне сказали, что они только для специальных миссий.$B$BНу и ладно!', NULL, NULL, 'Осадная бомба', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12231, 'Отпрыски медвежьего бога', 'Возможно, фурболгов Седых холмов затронула та же скверна, что заразила Фордрассил. Иначе я не могу объяснить, почему после стольких лет мира они оказались вовлечены в страшную, братоубийственную войну.$B$BНа востоке отсюда есть тщательно охраняемые святилища, которые стали домом отпрыскам Урсока.$B$BОстается лишь уповать на то, что порча не возымела действие на наследников бога, Кодиан и Орсонна.$B$BРазыщи их и выслушай, что они могут нам поведать.', 'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас разыскать Орсонна в Святилище Красного Клыка и Кодиан в Святилище Кровавого Сердца.', 'Дети Урсока мудры. Их слова объясняют все то, что я не могла понять.', NULL, NULL, NULL, 'История Орсонна', 'История Кодиан', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12232, 'Бомбардировка баллист', 'Наконец-то у нас появился шанс ударить по их осадным машинам! Не облажайся!$B$BШучу.$B$BОтчасти.$B$B$C, ты $gдолжен:должна: уничтожить баллисты Нового Дольного Очага с помощью этих бомб.$B$BМы покажем Королевскому фармацевтическому обществу, как это делалось в старые добрые времена! Никаких замысловатостей, никаких сложных рецептов!', 'По заданию Стража смерти Молдера из Ядозлоби уничтожьте 5 баллист Нового Дольного Очага с помощью осадных бомб.', 'О, счастливый день!$B$BНе затратив ни времени, ни средств фармацевтов на выполнение задачи, я уж точно привлеку внимание верховного палача!$B$BНестандартное мышление – в этом весь я. Да-да, ты тоже немного помог.$B$BПослушай, если я тебе заплачу, обещаешь не упоминать о своей роли во всем этом деле?', NULL, NULL, NULL, 'Уничтожено баллист Нового Дольного Очага с помощью бомб', 'Осадные бомбы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12234, 'Надо знать', 'Мне нужно знать, что замышляют в Новом Дольном Очаге.$B$BУкради их сегодняшние приказы, чтобы я могла это выяснить.$B$BСтупай на юг и осмотри аббатство, казармы и побережье – найди их текущие планы действий!$B$BЕсли вдруг заблудишься, казармы – это такое здоровенное здание рядом с кузницей.', 'Украдите текущие приказы Алого Натиска в аббатстве, в казармах и на побережье по просьбе госпожи шпионов Репины из Ядозлоби.', 'Ну, $R, чего ждешь? Давай их сюда!', 'Не тяни, не то их планы успеют измениться, и придется начинать все заново.$B$BНе теряй времени!', NULL, NULL, 'Текущие приказы Алого Натиска: аббатство', 'Текущие приказы Алого Натиска: казармы', 'Текущие приказы Алого Натиска: берег', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12235, 'Наксрамас и падение крепости Стражей Зимы', 'Лорд Фордрагон возглавил сокрушительную атаку на Артаса у Врат Гнева. За это Артас направил против нас Наксрамас. В то время как Кел\'Тузад скрывается в парящей цитадели, его военачальник, Тельзан, осаждает крепость Стражей Зимы. Нижняя часть поселения уже потеряна, и надежда вызволить выживших тает с каждой минутой.$B$BДействовать нужно быстро! Срочно обратись к командиру грифонов Урику на грифоньей площадке! Он поможет тебе быстро добраться до места.$B$BСтупай!', 'Поговорите с командиром грифонов Уриком на грифоньей площадке в крепости Стражей Зимы.', '<Урик указывает на грифона.>$B$BДоводилось ли тебе летать на этих животных? Впрочем, это проще простого. Садись и говори ему, куда лететь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12236, 'Урсок, медвежий бог', 'Время пришло, $N. Возьми этот пепел и принеси его фурболгу, о котором упоминала Кодиан. Если он отправился на поиски Урсока, то его следы должны привести тебя к логову на севере Седой Пасти.$B$BУвы, ты не справишься без его помощи. $gОдному:Одной: тебе никогда не одолеть Урсока.$B$BКак только вы одержите победу над Урсоком, воспользуйся этим пеплом, чтобы очистить его дух. Даже если его физическое тело будет уничтожено, душа должна быть спасена.', 'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас найти Тура Яролапа возле Логова Урcока и победить Урсока с его помощью. Когда Урсок падет, осыпьте его тело очищенным пеплом Фордрассила.', '<Друид выглядит бледной, и ее взгляд устремлен куда-то мимо вас. Вы замечаете, что она оставила вам сверток в благодарность за ваши труды.>', NULL, NULL, NULL, 'Урсок очищен', 'Очищенный пепел Фордрассила', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12237, 'Полет защитника Стражей Зимы', 'При помощи этого свистка ты можешь призвать грифона Стражей Зимы. Взбирайся на него и направляйся к руинам деревни Стражей Зимы, ныне известным как Поля Падальщиков, на юго-восток отсюда. Когда доберешься до полей, смотри в оба и ищи беспомощных селян Стражей Зимы. Когда заметишь кого-то из них, опускайся ниже и с помощью грифона подбери несчастного. Привези спасенного сюда, на грифонью площадку.$B$BТам повсюду кишат воины Плети, так что не зевай! Удачи!', 'Спасите 10 беспомощных селян Стражей Зимы и возвращайтесь к командиру грифонов Урику в крепость Стражей Зимы.', 'Прекрасно, $N! С возвращением наших жителей мы снова сможем привести эту крепость в нормальное состояние.', NULL, NULL, NULL, 'Спасено беспомощных селян', 'Свисток для вызова грифона Стражей Зимы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12238, 'Очищение Драк\'Тарона', 'Друг мой, настало время действовать.$B$BСкоро Драк\'Тарон будет очищен от этой мерзкой нежити и засияет во всей своей былой славе. Моя душа обретет покой, а ты в награду за свои великие деяния обретешь великое сокровище!$B$BЭта крепость ведет к священному зиккурату. Встань на его вершине и призови меня в последний раз, чтобы я провел ритуал очищения. $B$BУвы, но тебе снова придется заплатить за вызов моего духа. Но в крепости еще остались выжившие, у кого ты сможешь забрать еще немного настоя.', 'Дракуру просит вас выпить эликсир возле его жаровни в Драк\'Тароне. Для использования эликсира вам понадобится пять настоев терпения.', 'Мы совершили великое дело, дружище! И это только начало...$B$BКогда придет время, отыщи меня в Зул\'Драке.$B$BМы с тобой выиграем эту битву!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12239, 'Шпион в Новом Дольном Очаге', 'В рядах Алого Натиска у меня есть шпионка. Мне нужно, чтобы ты $gпередал:передала: ей дневное задание, чтобы она могла спланировать следующую фазу нашей атаки.$B$BОна откликается на имя агента Скулли и находится там под личиной кладбищенского смотрителя Алого Натиска.$B$BВот это задание, отнеси ей и сделай то, о чем она попросит. Кладбище находится рядом с аббатством.', 'Доставьте текущие приказы Алого Натиска агенту Скулли в Новый Дольный Очаг.', 'У тебя сообщение от госпожи шпионов?$B$B<Агент кладет лопату на землю, попутно оглядываясь, чтобы удостовериться, что никто не смотрит на вас.>$B$BДай-ка мне взглянуть на эти планы.', '<Агент внимательно осматривает вас и, наконец, подзывает вас к себе жестом.>$B$BСмотри, не нарушь мое инкогнито, $C!', NULL, NULL, 'Текущие приказы Алого Натиска (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12240, 'Цель и средства', 'Моя сестра, живущая на родине, в Бастионе, прислала мне с последним кораблем несколько бочонков с термитами. Думаю, они пригодятся для того, что я от тебя хочу.$B$BНам очень мешает лесопилка в Новом Дольном Очаге, но до сих пор мы никак не могли пробраться внутрь, чтобы выманить их десятника.$B$BДумаю, что если натравить этих термитов на его драгоценные доски и бревна, он уж точно прибежит как миленький!$B$BНу что, $C, возьмешься его ликвидировать?', 'Используйте термитов семейки Левин, чтобы выманить штейгера Калейки и убить его по просьбе аптекаря Вики Левин из Ядозлоби.', 'Да, я знала, что моя сестрица не подведет!$B$BМолодец, $N! Теперь лесопилка Натиска на некоторое время вышла из строя, а значит, им не из чего будет строить свои баллисты!$B$BСпасибо за помощь! Честь нашей семьи не посрамлена!', NULL, NULL, NULL, 'Штейгер Калейки убито', 'Термиты семейки Левин', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12241, 'Уничтожить саженец', 'Увы, $N, нам придется вмешаться в работу фурболгов. Я понимаю их благие намерения, но не могу допустить, чтобы заражение распространялось.$B$BЭтот саженец – источник зла, и потому он должен быть уничтожен. Возьми этот факел, подожги им зараженный саженец, и принеси мне пепел. $B$BОчищенный огнем, он поможет нам побороть скверну. С помощью этого пепла ты изгонишь злые силы из Урсока.', 'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас взять лиственный факел и сжечь саженец Фордрассила. Принесите пепел Фордрассила Серому Рогу.', '', NULL, NULL, NULL, 'Пепел Фордрассила', 'Лиственный факел', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12242, 'Семена Фордрассила', 'Мы должны убедиться в том, что Фордрассил никогда не вырастет вновь. Я боюсь, что фурболги уже посадили его семя. $B$BОтправляйся в Седую Пасть, что в самом сердце Седых холмов, и собери все семена, которые сможешь найти. Я постараюсь их уничтожить.', 'Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас отправиться в Седую Пасть и принести ей 8 семян Фордрассила.', '', NULL, NULL, NULL, 'Фордрассилское семя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12243, 'Огонь над водами', 'У меня есть для тебя еще одно задание.$B$BМне удалось переработать кое-что из настоя порчи в мою знаменитую на весь мир огненную воду. Я хочу, чтобы ты $gвзял:взяла: ее и $gподжег:подожгла: паруса \"Глупости грешника\"!$B$BИспользуй воду прямо из дока. Когда паруса вспыхнут, матросы будут сильно заняты, разбираясь с ними, а ты пока проскользнешь в нижнее помещение и добудешь бумаги капитана.$B$BКорабль найдешь в Стоянке рыцарей, ниже и к югу от Нового Дольного Очага. Капитанская каюта расположена на первой нижней палубе, под лестницей.', 'По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь Пылающей водой аптекаря, чтобы поджечь паруса \"Глупости Грешника\".Пока матросы будут заняты тушением пожара, спуститесь вниз и раздобудьте у капитана лоцию капитана Шели.', 'Уахахахаха!$B$BБез их лоций им больше некуда бежать теперь.$B$BПо мне так Алому Натиску конец – и надо же, как раз тогда, когда они начинали! Какая досада.$B$BХаха.', 'Только, пожалуйста, НЕ ВЗДУМАЙ говорить мне, что на их паруса не действует моя огненная вода!$B$BЯ очень не хотела бы снова проводить с ней эксперименты.', NULL, NULL, 'Паруса \"Глупости грешника\" подожжены', 'Лоция капитана Шели', 'Пылающая вода аптекаря', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12244, 'Починка крошшеров', 'Эй, $gдружище:подруга:! Закатай рукава и берись за работу! У нас тут полно дел! Вон те крошшеры еще вчера надо было подлатать и отправить в Бухту торговцев!..$B$BЧто? У тебя нет инструментов? А зачем ты вообще сюда $gпришел:пришла:? $gТопал:Топала: бы себе вместе с остальными дурнями сражаться с Ордой!$B$BМожет быть, твоих жалких мозгов хватит хотя бы на то, чтобы отвезти эти сломанные крошшеры на ремонт и не растрясти их по дороге?', 'Синипус с Лесозаготовок Синего Неба просит вас привезти ему 3 сломанных крошшера.', '<Синипус насвистывает.>$B$BАх, ты мой красавец! Сейчас мы тебя починим, будешь лучше прежнего!$B$BА тебе что, делать нечего? Иди к Гордуну, пусть он тебя отправит в Бухту торговцев. Им точно не помешает твоя помощь.$B$BТы еще здесь? На тебе ключи, заведи отремонтированного крошшера. Посмотрим, на что способны эти малышки.', NULL, NULL, NULL, 'Доставлено крошшеров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12245, 'Никакой пощады пленникам', 'Много еще есть глупцов, которых тебе нужно будет убить.$B$BМои агенты сообщают, что кое-кто из наших добрых горожан вот-вот упадет прямо в объятия Алого Натиска.$B$BНет уж, этого не произойдет.$B$BОтправляйся в Новый Дольный Очаг и прикончи стража смерти Шнайдера, главного писаря Киннедия, инженера Бурка и канцлера Амай.$B$BКак я слышала, они содержатся в разных местах. Уж конечно, сидят в клетках и дрожат в ожидании казни.$B$BПоговори с ними, а затем убей!', 'По поручению главы шпионов Репайн убейте Стража смерти Шнайдера, главного писаря Киннедия, инженера Бурка и канцлера Амай.Когда выполните это задание, сообщите об этом верховному палачу Росу в Ядозлобь.', 'Что? Ты что, думал, мы тебя отправляем их спасать?$B$BС какой бы стати, когда есть подтвержденная запись, что они уже пленены?$B$BНордскол – жестокое место, юный $N. И тебе придется к этому приспособиться.', NULL, NULL, NULL, 'Страж смерти Шнайдер убито', 'Главный писарь Киннедий убито', 'Инженер Бурк убито', 'Канцлер Амай убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12246, 'Возможная связь', 'Живущие на востоке фурболги более дикие и агрессивные, чем те, с которыми тебе уже приходилось встречаться. Нашим отрядам случалось сталкиваться с этими тварями, и каждый раз немногочисленные выжившие рассказывали о темной вязкой жидкости, сочившейся из трупов поверженных фурболгов. $B$BВозможно, это как-то связано с порчей, обнаруженной нами на останках Фордрассила. $B$BПожалуйста, принеси мне несколько образцов крови фурболгов. Ты найдешь их в Святилище Красного Клыка и Святилище Кровавого Сердца, которые находятся на востоке.', 'Иерофант Тайрин из Приюта Янтарной Сосны просит вас принести 8 образцов безумных фурболгов, обитающих в Святилище Кровавого Сердца и Святилище Красного Клыка.', '', NULL, NULL, NULL, 'Кровь безумного фурболга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12247, 'Дети Урсока', 'Теперь я уверена, что эту скверну распространяют фурболги Седых холмов. Долгие годы они жили в мире, но с недавних пор меж их племенами идет кровопролитная война.$B$BОсталось лишь узнать, затронула ли порча двух медведей, которых они почитают как богов.$B$BДвое отпрысков Урсока, Орсонн и Кодиан, обитают в Святилище Красного Клыка и Святилище Кровавого Сердца, что на юге и юго-востоке Седой пасти.$B$BОбратись к ним – может быть они могут поведать нам что-нибудь об этой беде.', 'Иерофант Тайрин из Приюта Янтарной Сосны просит вас разыскать Орсонна в Святилище Красного Клыка и Кодиан в Святилище Кровавого Сердца.', 'Дети Урсока мудры. Их слова объясняют все то, что я не могла понять.', NULL, NULL, NULL, 'История Орсонна', 'История Кодиан', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12248, 'Саженец Фордрассила', 'У древних друидов были веские причины уничтожить Фордрассил. Мы не можем позволить фурболгам возродить его!$B$BПроблема в том, что спасение духа Урсока зависит от магии, содержащейся в саженце мирового древа.$B$BВозьми этот факел и сожги саженец, произрастающий в центре Седой Пасти, в старой кадке Фордрассила.$B$BПринеси мне пепел, оставшийся после сожжения дерева. Я надеюсь, что огонь очистит его от скверны, и мы сможем воспользоваться его магией для исцеления духа Урсока.', 'Иерофант Тайрин из Приюта Янтарной Сосны просит вас взять зеленый факел и сжечь саженец Фордрассила. Принесите ей пепел Фордрассила.', 'Какое счастье! Магия Фордрассила все еще жива. Возможно, мы еще сможем подарить надежду Урсоку.', 'Ты принес мне пепел, $N?', NULL, NULL, 'Пепел Фордрассила', 'Лиственный факел', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12249, 'Урсок, медвежий бог', 'Время пришло, $N. Возьми этот пепел и принеси его фурболгу, о котором упоминала Кодиан. Если он отправился на поиски Урсока, то его следы должны привести тебя к логову на севере Седой Пасти.$B$BУвы, ты не справишься без его помощи. $gОдному:Одной: тебе никогда не одолеть Урсока.$B$BКак только вы одержите победу над Урсоком, воспользуйся этим пеплом, чтобы очистить его дух. Надеюсь, все наши труды были не напрасны...', 'Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Тура Яролапа возле Логова Урcока и победить Урсока с его помощью. Когда Урсок падет, осыпьте его тело очищенным пеплом Фордрассила.', '<Девушка-друид выглядит бледной, и ее взгляд устремлен куда-то мимо вас. Вы замечаете, что она оставила вам сверток в благодарность за ваши труды.>', NULL, NULL, NULL, 'Урсок очищен', 'Очищенный пепел Фордрассила', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12250, 'Семена Фордрассила', 'Мы должны убедиться в том, что Фордрассил никогда не вырастет вновь. Я боюсь, что фурболги уже посадили его семя. $B$BОтправляйся в Седую Пасть, что в самом сердце Седых холмов, и собери все семена, которые сможешь найти. Я постараюсь их уничтожить.', 'Иерофант Тайрин из Приюта Янтарной Сосны из Крепости Завоевателей просит вас отправиться в Седую Пасть и принести ей 8 семян Фордрассила.', '', NULL, NULL, NULL, 'Фордрассилское семя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12251, 'Возвращение к верховному главнокомандующему', 'Вернись скорее к верховному главнокомандующему Халфорду Змеевержцу, $N. Скажи ему, что твоя миссия выполнена и что немногие оставшиеся в живых жители деревни вернулись к работе.', 'Поговорите с верховным главнокомандующим Халфордом Змеевержцем в крепости Стражей Зимы на Драконьем Погосте.', '<Халфорд отдает вам честь.>$B$BВсе жители вернулись к работе? Так быстро! Молодцом, солдат! Мы вновь отстроим и укрепим этот городок – глазом моргнуть не успеешь! И вскоре будет готово подкрепление, чтобы помочь лорду Фордрагону у Врат Гнева.$B$BЯ, конечно, забегаю вперед, на самом деле, еще многое нужно сделать, прежде чем мы сможем даже начать думать о том, чтобы послать тебя на помощь Болвару.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12252, 'Истязание истязателя', 'Достаточно! Я хочу, чтобы ты $gположил:положила: конец мучениям моего народа!$B$BИстязатель Алого Натиска, Альфонс, клещами вытягивает информацию из любого, кто попадется этим мерзавцам! Мне нужно знать, что им известно.$B$BМои источники сообщают, что он организовал свою \"мастерскую\" в подвале казарм, прямо рядом с кузницей.$B$BЯ тебе одолжу свое собственное клеймо, чтобы быть уверенным, что дело будет сделано как надо.$B$BНайди его – и добудь информацию.', 'По поручению верховного палача Роса из Ядозлоби пять раз припечатайте клеймом истязателя Альфонса, чтобы вытянуть из него нужную информацию. Получив ее, убейте Альфонса.', 'И все это они знали? И кто, лич побери, этот верховный адмирал Вествинд, о котором он говорил?!$B$B<Верховный палач ворчит себе под нос что-то о нелюбви к сюрпризам.>$B$BЛучше, чтобы мы знали, чем нам пришлось бы догадываться. Надеюсь, ты оставил на нем свою... эээ... то есть, МОЮ метку.', NULL, NULL, NULL, 'Истязатель Лекрафт тщательно допрошен', 'Истязатель Альфонс убито', 'Тавро верховного палача', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12253, 'Спасение с городской площади', 'Эта дорога ведет на городскую площадь крепости Стражей Зимы. Некогда там кипела жизнь, теперь же это зона боевых действий, кишащая злобными упырями, жаждущими мести всему живому.$B$BА в зданиях, окружающих площадь, заперты деревенские жители. Их надо спасти! Понимаю, $N, я прошу очень многого, но ты – единственный солдат, без которого я могу обойтись. Освободи наших людей. Ступай на площадь, войди в эти дома. Убивай всех, кто попытается тебе помешать! Если выживешь, возвращайся ко мне.', 'Спасите 6 пойманных жителей крепости Стражей Зимы по просьбе главнокомандующего Халфорда Змеевержца из крепости Стражей Зимы в Драконьем Погосте.', '<Халфорд молится за души погибших.>$B$BТы творишь дело Света, $N! $B$BБоюсь, наши труды только начинаются…$B$B<Халфорд показывает вам некий документ.>', NULL, NULL, NULL, 'Спасено пойманных жителей крепости Стражей Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12254, 'Без молитвы – никак', 'Эти планы показывают, что грядет нечто неотвратимое.$B$BНо сначала нужно разобраться с той странной защитой, которая есть у сил Алого Натиска. Если Ядозлобь хочет разобраться с ним раз и навсегда, мы должны выяснить, кто стоит за всем этим, и уничтожить его.$B$BЯ заметила, что епископ в часовне на дальней стороне Нового Дольного Очага, что напротив мельницы, дал свое благословение войскам. Убей его и забери его молитвенник.$B$BМожет быть, это даст нам ключ к разгадке.', 'По заданию агента Скулли из Нового Дольного Очага раздобудьте молитвенник епископа Стрита.', 'Новое благословение, написанное на последней странице?$B$B<Агент смотрит вам через плечо, пока вы пролистываете книгу до последней страницы.>$B$BДа что б мне провалиться на этом месте! Это же почерк верховного настоятеля! Ручаюсь твоей собственной жизнью.', 'Ты добыл молитвенник епископа? Обнаружил ли ты в нем что-то необычное?', NULL, NULL, 'Молитвенник епископа Стрита', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12255, 'Тан Волдруна', 'Теперь, когда мы захватили огнепрочные талисманы и ослабили оборону Волдруна, настало время бросить вызов самому предводителю врайкулов, тану Торвальду Эрикксону.$B$BЕго любимое верховое животное – дикий протодракон по кличке Огнедышащий. Его держат закованным в цепи на западе Волдруна, но тебе не составит труда подчинить его себе с помощью талисманов и обратить его против хозяина. $B$BПриручи Огнедышащего и обыщи верхушки всех башен Волдруна. Тан должен скрываться где-то там.', 'Одержите победу над таном Торвальдом Эрикксоном с помощью Огнедышащего и доложите об успехе плотнику Дрейку из Приюта Янтарной Сосны.', '', NULL, NULL, NULL, 'Тан Торвальд Эрикксон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12256, 'Тайны огневязов', 'Пока мы пытаемся дать отпор трусливым захватчикам из Альянса, клан Укротителей драконов вербует новую армию в деревне Волдрун, которая находится у побережья на юге. Врайкулы – серьезные противники, и мне хотелось бы уничтожить их прежде, чем они решат выступить против нас.$B$BСамые могущественные воины в этой деревне носят огнепрочные талисманы, которые дают им власть над могущественными протодраконами. Эти талисманы создают прядильщицы пламени из клана Укротителей драконов. Убей их и принеси мне амулеты!', 'Принесите 3 огнепрочных талисмана сержанту Назгриму в Крепость Завоевателей.', 'Протодраконы подчиняются только владельцам талисманов. Теперь судьба тана решена!', 'Ты нашел талисманы?', NULL, NULL, 'Огнепрочный талисман', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12257, 'Демонстрация силы', 'Во врайкульской деревне Волдрун полным ходом идут приготовления к войне. Хотя местный тан не может выставить против нас большую армию, мы все равно не можем чувствовать себя в безопасности.$B$BНельзя дать им возможность напасть, когда мы к этому будем не готовы, поэтому я предлагаю самим сделать первый шаг. Если ты – истинный представитель Орды, ты с радостью ухватишься за возможность продемонстрировать свою силу.$B$BУбей всех хускерлов, которые встретятся тебе на пути. Пусть они дважды подумают, стоит ли связываться с Ордой!', 'Убейте 12 хускерлов из клана Укротителей драконов и вернитесь к сержанту Назгриму в Крепость Завоевателей.', 'Молодец, ты выполнил мое поручение в точности. Теперь Укротители драконов будут вынуждены обороняться, а у нас будет время, чтобы расправиться с их главой клана.', NULL, NULL, NULL, 'Хускерл из клана Укротителей драконов убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12258, 'Судьба погибших', 'По городской площади, куда ведет эта дорога, бродят жители крепости, превращенные в нежить! Наш собственный склеп превратился в источник все новых воинов Плети! Это наши бывшие собратья, да, но не надо их щадить, $N. Когда-то все они были смертными, способными мыслить и сострадать, теперь же это лишь гнусная нежить, у которой одна цель: уничтожить нас!$B$BСтупай на городскую площадь и отправь мстительных упырей к их создателю. Пусть упокоятся в мире.', 'Убейте 15 мстительных упырей по приказу командира Линоры Порыв Ветра в крепости Стражей Зимы в Драконьем Погосте.', 'Быть может, теперь они смогут упокоиться в мире, и души их свободно поднимутся навстречу Свету.$B$BЯ же буду молиться за лорда Фордрагона и наших воинов у Врат Гнева. Мы здесь должны выстоять, хотя бы затем, чтобы позволить им выиграть время и одолеть Короля-лича. Крепость Стражей Зимы не должна пасть!', NULL, NULL, NULL, 'Мстительный упырь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12259, 'Тан Волдруна', 'Теперь, когда мы захватили огнепрочные талисманы и ослабили оборону Волдруна, настало время бросить вызов самому предводителю врайкулов, тану Торвальду Эрикксону.$B$BЕго любимое верховое животное – дикий протодракон по кличке Огнедышащий. Его держат закованным в цепи на западе Волдруна, но тебе не составит труда подчинить его себе с помощью талисманов и обратить его против хозяина. $B$BПриручи Огнедышащего и обыщи верхушки всех башен Волдруна. Тан должен скрываться где-то там.', 'Одержите победу над таном Торвальдом Эрикксоном с помощью Огнедышащего и доложите сержанту Назгриму из Крепости Завоевателей.', 'Теперь жалкие остатки племени Укротителей драконов не осмелятся выступить против нас. Никакой пощады врагам – вот девиз Орды!', NULL, NULL, NULL, 'Тан Торвальд Эрикксон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12260, 'Полное несходство', 'Ты, должно быть, удивляешься, как мне удается поддерживать эту личину? Я пользуюсь волшебным зеркальцем, которое мне одолжила госпожа шпионов.$B$BСилы в нем не так уж много, но я думаю, что на нас обоих хватит. Вот, возьми. Я хочу, чтобы ты $gиспользовал:использовала: его, чтобы замаскироваться под одного из жрецов-воронов Алого Натиска.$B$BДавай быстрее... я понятия не имею, сколько продержится маскарад, пока зеркальце у тебя.$B$BПомни, что идеальная маскировка проявится не сразу, так что не особо рассчитывай не нее, пока у меня не появится возможность тебе помочь.', 'По заданию агента Скулли из Нового Дольного Очага похитьте образ жреца-ворона Алого Натиска. После этого верните Волшебное зеркало банши агенту Скалли.', 'Неплохо, $C. Теперь, когда образ жреца пойман зеркалом, есть еще одно дельце.', 'Что такое? Скажи, надеюсь, ты не разбила зеркальце?!', NULL, NULL, 'Облик жреца-ворона Алого Натиска похищен', 'Волшебное зеркало банши (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12261, 'Отрезать пути к отступлению', 'Они вытягивают силу из костей моих мертвых собратьев…$B$BУ меня нет никакой симпатии к Культу, но я удивлен их дерзостью. К ним не будет снисхождения… впрочем, я никогда и не был снисходительным.$B$BСделай так, чтобы им некуда было бежать, когда начнется бойня. Установи тотем уничтожения в конце тропы, ведущей из святилища... где дорогу начинает заносить снегом. Защищай его, пока он не зарядится полностью.', 'Поместите тотем уничтожения в конце тропы, ведущей из Обсидианового святилища драконов, там, где дорогу начинает заносить снегом. Защищайте его до полной зарядки, затем вернитесь к Серинару.', 'Отлично. Когда они в страхе побегут, тотем будет тут как тут, чтобы сказать им последнее \"прощай\".', 'Ты установил защиту?', NULL, NULL, 'Тотем уничтожения полностью заряжен', 'Тотем уничтожения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12262, 'Без надежды на спасение', 'Мы никого не пощадим.$B$BТам, за нашими стенами, презренные некролиты и их скелеты-прислужники оскверняют мою землю своим присутствием на ней. Убей их всех до единого.', 'Убейте 6 некролитов Пылающих Глубин и 10 тлеющих скелетов за пределами Обсидианового святилища драконов, после этого вернитесь к Серинару.', 'Они умоляли тебя пощадить их никчемные жизни? Слабаки…', NULL, NULL, NULL, 'Некролит Пылающих Глубин убито', 'Тлеющий скелет убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12263, 'С наилучшими намерениями', 'Культ Проклятых явился сюда не просто для того, чтобы вытягивать энергию из тел мертвых драконов. Думаю, я догадываюсь, что они замыслили, но мне нужно, чтобы ты $gподтвердил:подтвердила: мою правоту.$B$BЯ придам тебе обличье вот этого мертвого некролита. Доберись до конца пещеры и выясни, зачем они здесь, в этом священном месте. А я буду смотреть твоими глазами.$B$BБудь осторожнее, $N: если тебе нанесут хоть какой-то урон, это разобьет хрупкую иллюзию.', 'Дождитесь, пока Серинар замаскирует вас под некролита Пылающих Глубин, потом проникните в глубь Пасти Нелтариона, чтобы узнать, что там делает Культ Проклятых. Вернитесь к Серинару и расскажите о том, что они замышляют.', 'Мы – черные драконы. Тысячи лет мы сеяли разрушение в землях Азерота. Этот жалкий Культ Проклятых все же поклоняется смерти – что ж, мы будем рады им помочь!', 'О, как я устал от этих мерзавцев!', NULL, NULL, 'Исследовать локацию', 'Обнаружить зал воскрешения магмазмеев', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12264, 'Разборка с Проклятыми', 'Пещера наверху буквально кишит злодеями Культа. С такими созданиями можно разобраться только одним способом... и ты знаешь, каким.', 'Убейте 3 некромантов Пылающих Глубин, 6 тлеющих созданий и 6 тлеющих упырей в Пасти Нелтариона, а затем возвращайтесь к Серинару.', 'Слышать их вопли... Видеть, как последнее биение жизни исчезает из их жалких тел... вдохновляет, не правда ли?$B$BСмакую каждый момент!..', NULL, NULL, NULL, 'Некромант Пылающих Глубин убито', 'Тлеющее создание убито', 'Тлеющий упырь убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12265, 'Осквернение осквернителей', 'Я чувствую крупное средоточие магии в рунах, обнаруженных при исследовании пещеры. У нас нет времени на сложные магические ритуалы... порою самое грубое решение является и самым эффективным.$B$BУничтожь руны. Разрушь их и сделай так, чтобы последователи Культа никогда не получили доступа к заключенной в них мощи.', 'Найдите и уничтожьте 8 некромантских рун, выявленных на дне Пасти Нелтариона. Выполнив это, возвращайтесь к Серинару.', 'Хорошо. Но это еще не все.', NULL, NULL, NULL, 'Уничтожено некромантских рун', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12266, 'Рассказ о разрушении', 'Можешь идти, $r.$B$BИди скажи Нелис, что она пропустила сочный махач.', 'Отправляйтесь обратно в Драконий Покой и расскажите Нэлис, что задание Серинара выполнено.', 'А, это ты.$B$BЯ надеялась, что Серинар просто вернется, когда задание будет выполнено. А он, видно, в очередной раз отвлекся, погнавшись за какой-нибудь жертвой. Он рискует пропустить славную заварушку!$B$BТы что, еще здесь? Я с тобой закончила.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12267, 'Пламя Нелтариона', 'Теперь, когда ряды сектантов поредели и сил у них поубавилось, самое время нанести удар по источнику заразы.$B$BРотин Гниющий в глубине пещеры воскрешает черных драконов в облике магмазмеев. Проберись в чертог Призыва и очисти оставшиеся кости – единственным способом, который не позволит их больше использовать: пламенем!$B$BКонечно, как только Ротин обнаружит, что кости горят, он тут же явится сам, так что тебе придется уничтожить и его тоже.$B$BЭтот магический сосуд поможет тебе выполнить задачу.', 'Используйте пламя Нелтариона, чтобы очистить область призыва в глубине Пасти Нелтариона. После того как привлечете внимание Ротина Гниющего, убейте его, затем вернитесь к Серинару у входа в пещеру.', 'Кости моих родичей избавлены от жалкой участи. Ты хорошо послужил мне, и получишь достойную награду.', 'Ты весьма эффективное орудие, $C. Твоя помощь в очищении не будет забыта!', NULL, NULL, 'Область призыва очищена', 'Ротин Гниющий убито', 'Пламя Нелтариона', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12268, 'Запчасти', 'Фу! Ну и мешанина!$B$BНет, гоблинам все-таки далеко до нас в области механики. Вот, ты только посмотри! Удивительно, что эта штуковина вообще работает.$B$BСлушай, может, ты мне слегка пособишь? Чтобы довести это устройство до ума, мне надо будет заменить несколько колесиков, шестеренок и пружин. Найти их не составит труда – они в изобилии валяются вокруг лесопилки.', 'Трубкочист с Лесозаготовок Синего Неба просит вас собрать 4 рифленых шестеренки, 3 зубчатых колеса и 2 тугих пружины.', 'Сгодится. Ну-ка, подкрутим здесь... $B$BВсе готово! Еще один крошшер готов к бою. Спасибо, $N.', 'Что, уже тащишь запчасти?', NULL, NULL, 'Рифленая шестеренка', 'Зубчатое колесо', 'Тугая пружина', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12269, 'Только не c нашего рудника!', 'Этот проклятый некрополь совершил нападение так неожиданно! Пока мы отражали атаку, мы потеряли рудник Стражей Зимы. Что еще хуже, приспешники Кел\'Тузада подняли убитых горняков как воинов Плети и теперь используют их для поставки их осадных дел мастерам материалов с нашего рудника!$B$BЭту линию поставок надо прервать, а наших павших братьев – упокоить как положено.$B$BОтправляйся на рудник Стражей Зимы, расположенный на Полях Падальщиков, к северо-востоку отсюда, и уничтожь поднятых Плетью горняков. Возвращайся ко мне с их шахтерскими удостоверениями, чтобы я мог зарегистрировать их как погибших.', 'По поручению верховного лорде Леорика фон Цельдига из крепости Стражей Зимы на Драконьем Погосте добудьте 10 удостоверений шахтера Стражей Зимы.', '<Леорик берет у вас удостоверения.>$B$BЯ отнесу это нашему регистратору и принесу печальные вести семьям погибших горняков.$B$BСделать предстоит еще очень многое, если мы хотим добиться успеха здесь и, в конечном счете, у Врат Гнева. Лорд Фордрагон рассчитывает на нас.', 'Тебе удалось раздобыть их удостоверения?', NULL, NULL, 'Удостоверение шахтера Стражей Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12270, 'Искрошить Альянс', 'Читай по губам, $C: мне-нужны-крошшеры! Нельзя допустить, чтобы они попали в руки Альянса!$B$BДо сих пор они захватывали крошшеры, чинили их и обращали против наших братьев в Бухте торговцев. Но теперь мы сами воспользуемся их уловкой!$B$BУвидишь бесхозный крошшер – тащи его сюда! Увидишь крошшер в руках жалкого червя из Альянса – убей его и отними крошшер! А мы уже позаботимся о том, чтобы эти малютки работали как надо.$B$BВольно!', 'Грекк с Лесозаготовок Синего Неба просит вас добыть для него 3 крошшера.', 'Молодец, солдат!$B$BА теперь возьми этот ключ и отправляйся в Бухту торговцев. Я даже доверю тебе один из отремонтированных крошшеров, чтобы ты смог испытать его в деле.$B$BКстати, если хочешь поскорее попасть в бухту, поговори с Дарроком – он знает короткий путь.', NULL, NULL, NULL, 'Доставлено крошшеров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12271, 'Жезл принуждения', 'Жезл падает из рук мертвого Альфонса. По всей длине жезла пульсируют магические руны.$B$BМогло ли быть, чтобы таким способом он выбивал признания?$B$BНужно, чтобы на это взглянул верховный палач.', 'Отнесите жезл истязателя верховному палачу Росу в Ядозлобь.', 'Так ты говоришь, вот это нашлось у Альфонса? Все ясно.$B$BЯ знаю этот жезл еще с тех пор, как служил мучителем при дворе короля Теренаса в Лордероне. Он называется жезлом принуждения.$B$B<Верховный палач заламывает руки, тревожимый зловещим предчувствием того, что должно произойти.>$B$BУ меня есть идея, какое ему можно найти применение!', 'Ты забрал жезл у их истязателя?', NULL, NULL, 'Жезл истязателя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12272, 'Кровоточащая руда', 'За считанные часы до вторжения сил Наксрамаса один из шахтеров наткнулся на кусок руды, покрытый клейкой жидкостью. В хаосе, возникшем во время эвакуации рудника, мы потеряли образцы, взятые с точки, где были чужаки. А теперь Плеть осматривает всю руду с целью использовать ее в своих машинах смерти.$B$BТебе нужно вернуться на рудник Стражей Зимы – он как раз на северо-востоке отсюда, на Полях Падальщиков – и раздобыть эту странную руду. Это непреложное условие нашего успеха!', 'По поручению осадного инженера Полувспыха из крепости Стражей Зимы на Драконьем Погосте добудьте 10 образцов странной руды на руднике Стражей Зимы.', 'Может быть, именно сейчас и настал тот момент, когда чаша весов качнется не в пользу Плети. $N, ты заслуженно являешься настоящим героем Альянса, по крайней мере, в моих глазах.$B$BА теперь, пожалуйста, отпусти меня. Мне потребуется дополнительное время для изучения этой руды с целью определить нечистые компоненты и слабые стороны.$B$BОтдохни, союзник. Я свяжусь с тобой, когда у меня будет новая информация.', 'Тебе удалось добыть образцы той странной руды?', NULL, NULL, 'Странная руда', 'Шахтерская кирка Полувспыха', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12273, 'Отречение', 'Пришло время окончательно деморализовать силы Алого Натиска!$B$BЯ хочу, чтобы ты $gвзял:взяла: жезл и $gвоздействовал:воздействовала: им на четырех его лидеров. Командир Джордан находится в казарамах наверху, главный канонир Зирхат – на юго-восточном склоне, ведет наблюдение за берегом, кузнец Гудман – в кузнице, а смотритель стойл Мерсер – в конюшнях.$B$BВоздействуй на них жезлом принуждения, сосредоточься на том, чтобы заставить их отречься от Алого Натиска, а затем убей!', 'По заданию верховного палача Роса из Ядозлоби воздействуйте жезлом принуждения на командира Джордана, главного канонира Зирхата, кузнеца Гудмана и смотрителя стойл Мерсера.Когда они подпадут под влияние жезла, убейте каждого из них, вырвав у них перед смертью признание об отречении от Алого Натиска.', '<Вам кажется, что вы успеваете заметить слабый намек на улыбку на лице Роса, которая, впрочем, тут же исчезает.>$B$BО, ты теперь мой любимый $C, $N. Если у тебя будет желание, я бы предложил тебе подумать на тему присоединения к нам в качестве офицера Длани Возмездия.$B$BМы могли бы назначить тебя Стражем смерти, а через несколько десятилетий, я думаю, тебя можно было бы уже смело продвигать в младшие палачи!$B$BНет? Ну, не стоит слишком торопиться с ответом... располагай временем, обдумай все хорошенько.', 'Ну, и?!', NULL, NULL, 'Отречение и смерть командира Джордана', 'Отречение и смерть главного канонира Зирхата', 'Отречение и смерть кузнеца Гудмана', 'Отречение и смерть смотрителя стойл Мерсера');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12274, 'Греховное падение', 'Нам нужны сведения, которые можно получить у верховного настоятеля. Теперь, когда у нас есть облик жреца-ворона, думаю, у тебя получится потолковать с ним.$B$BУвы, нужно будет еще как-то разлучить его с его телохранителями, иначе ты от него ничего не добьешься.$B$B<Агент некоторое время размышляет, опершись на лопату.>$B$BВо, придумала! Прими этот облик, поднимись на башню аббатства и позвони в колокол. Телохранители настоятеля бросятся наружу, а ты сможешь спуститься и поговорить с ним.', 'Позвоните в колокол аббатства, затем поговорите с верховным настоятелем по просьбе агента Скулли из Нового Дольного Очага.', 'Что за чертовщина?$B$BПрыгнул? Сам? А ты его… не того? Не подтолкнул?$B$B<Агент всматривается в вас с подозрением.>$B$BЛадно… Очевидно, тут все куда более запутанно, чем мы думали сначала.', 'Ну как? Удалось тебе с ним поговорить?', NULL, NULL, 'Позвонить в колокол аббатства', 'Поговорить с верховным настоятелем', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12275, 'Демогном', 'Полувспых недавно потребовал у моей группы специалиста, которого можно было бы отправить на разведку на рудник Стражей Зимы. Я отправил к нему Слинкина, своего подрывника. Я-то думал, что он сможет закрыть эту проклятую яму, после того как выполнит поручение Полувспыха, обеспечив нам таким образом еще одну победу над Плетью.$B$BНо вот прошел уже целый день, а Слинкина до сих пор нет! Мне нужен ответ! Поговори с осадным инженером Полувспыхом и отыщи моего пропавшего агента!', 'Поговорите с осадным инженером Полувспыхом в крепости Стражей Зимы в Драконьем Погосте.', 'Я ужасно виноват, друг мой. Боюсь, что, торопясь добыть ту незнакомую руду из рудника Стражей Зимы, я нечаянно обрек агента Слинкина на смерть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12276, 'В поисках Слинкина', 'Я не получал вестей от Слинкина и не знаю, какая судьба его постигла, однако же, возможно, могу помочь его отыскать.$B$B<Полувспых протягивает вам маленькую заводную игрушку.>$B$BЭто тебе не игрушка, наш новый друг. Это мое последнее изобретение! Эта машинка предназначена для того, чтобы отыскивать потерянное. Ситуация, конечно, неблагоприятная, однако эта машинка – твой единственный шанс найти Слинкина.$B$BКогда будешь $gготов:готова: приступить к поискам, поставь робота на землю рядом со мной.', 'Отыщите Слинкина Демогнома в руднике Стражей Зимы. Используйте самонаводящегося робота Полувспыха, если вам нужна будет помощь в поисках рудника.', '<В окостеневшей руке Слинкина зажата записка.>$B$BМеня загнали в тупик. Пока прячусь, но они знают, что я тут. Скоро меня найдут.$B$BШахтеры трудятся не покладая рук, добывая странную руду, на которой работают боевые машины Плети. Очень много болтают. Языка смерти я не понимаю, однако же некоторые, самые распространенные слова и фразы различать научился. Слово \"Йогг-Сарон\" произносится с большим презрением, и обычно сопровождается раскатами хохота. Руду они называют \"саронит\". Что бы это значило?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12277, 'Ничего не оставлять на волю случая', 'Если в твоем сердце есть добро, и твоя совесть чиста, читай дальше.$B$BВ этом руднике, неподалеку от помоста штейгера, спрятан внушительный запас динамита. Ступай туда, возьми несколько пачек взрывчатки и проберись ко входу в рудник. Оказавшись там, установи взрывчатку и взорви вход. Не забудь проделать это и с верхним, и с нижним входами в рудник Стражей Зимы!$B$BНичего не оставляй на волю случая. Тут обитает зло, нельзя допустить, чтобы оно выбралось наружу! Да хранит тебя Свет.', 'Добудьте бомбу Стражей Зимы и используйте ее, чтобы взорвать верхний и нижний стволы рудника Стражей Зимы. Выполнив задачу, вернитесь к осадному инженеру Полувспыху в крепость Стражей Зимы в Драконьем Погосте.', 'Но смерть его была не напрасной, друг мой! Сведения, ради которых Слинкин пожертвовал жизнью, помогут нам победить Короля-лича. Так оно и будет, обещаю!', NULL, NULL, NULL, 'Верхний ствол рудника Стражей Зимы разрушен', 'Нижний ствол рудника Стражей Зимы разрушен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12278, 'Клуб \"Пиво месяца\"', 'Думаю, тебе понравится быть членом нашего клуба \"Лучший пивовар месяца\". Ведь это означает, что у тебя всегда будет самое лучшее и свежее пиво.$B$BЗаполни членскую карточку \"Лучшего пивовара месяца\" и отнеси ее Ларкину Громовару в таверну \"Горючий камень\" в Стальгорне.', 'Отнесите членскую карточку \"Лучшего пивовара месяца\" Ларкину Громовару в таверну \"Горючий камень\" в Стальгорне.', '', NULL, NULL, NULL, 'Анкета для вступающих в клуб \"Пиво месяца\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12279, 'Медвежий аппетит', 'Наконец-то ты вернулся, Лимпи! Я уж боялся, что мы с Гризельдой останемся одни.$B$BЯ тут приготовил нам обед, но Гризельде вряд ли понравится моя стряпня.$B$BОна предпочитает рыбку, которая водится вдоль Побережья Восточного Ветра на востоке. Да я этих рыб сам на дух не переношу, но она у нас настоящий гурман. Поймай ей шесть больших рыбин – и она будет счастлива.$B$BНу давай, беги же! Не стоит заставлять нашу девочку ждать!', 'Принесите 6 северных лососей Хью Глассу в Торговую лавку Красного леса.', 'Эй! Да ты не Хромоногий Джо!', 'Если не поторопишься, будешь сам бурчать у нее в желудке!', NULL, NULL, 'Северный лосось', 'Рыболовная сеть', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12280, 'Текущий ремонт', 'Двадцать крошшеров к завтрашнему утру!$B$BЧто за светлая голова составляет эти графики? Могу поспорить, он даже близко не подходил к этим консервным банкам... $B$BМда... если я хочу уложиться в график, мне понадобится помощь. Если протянешь мне руку – отсыплю тебе кое-что из моей доли! $gСогласен:Согласна:?$B$BМне нужны колеса, шестеренки и пружины – они тут валяются повсюду.', 'Лурц с Лесозаготовок Синего Неба просит вас собрать 4 рифленых шестеренки, 3 зубчатых колеса и две тугих пружины.', 'Спасибо, $N. Этого мне хватит – во всяком случае, до завтра...$B$BА вот и обещанные деньги.', 'Что, уже тащишь запчасти?', NULL, NULL, 'Рифленая шестеренка', 'Зубчатое колесо', 'Тугая пружина', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12281, 'Понимание военной машины Плети', 'Мы должны утешаться тем фактом, что смерть Слинкина, хотя и трагическая, послужила высшему благу. Его открытие, вкупе с твоими героическими деяниями в шахте и образцами, которые ты $gвернул:вернула:, делает нас на шаг ближе к пониманию военной машины Плети.$B$BДоставь этот пакет главнокомандующему Халфорду Змеевержцу. В нем – образец этой странной руды и результаты моих исследований.', 'Доставьте амуницию Полувспыха главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.', '<Халфорд открывает пакет и читает исследование Полувспыха.>$B$BЯ, с какой стороны ни глянь, не являюсь ученым, $N, так что прости мне мое простецкое понимание того, что тут написано. Итак, согласно этому исследованию – предположим, что у меня мозги хотя бы не хуже, чем у школьника-подростка, – мы до сих пор не знаем практически ничего о военной машине Плети. Единственное, что нам известно, – это то, что в армии Плети для изготовления осадных машин, доспехов и оружия используется этот зловещий металл.$B$B<Халфорд испускает долгий, протяжный вздох.>', 'Я наслышан о храбрости, проявленной тобою в шахте, $N.', NULL, NULL, 'Амуниция Полувспыха (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12282, 'Отпечатки былого', 'Эта земля наполнена воспоминаниями о былом, $N. По всему Нордсколу отдаются немым эхом взывающие ко мне голоса.$B$BНа всем, чего коснулся Артас, он оставил жуткие отпечатки. Там, где он прошел, остаются лишь смерть и увядание. Вот почему так важно тщательно изучать историю, чтобы знать врага в лицо. Быть может, рано или поздно из глубины веков всплывут забытые истины, которые пригодятся нам в настоящем.$B$BДля начала, $N, добудь из ратуши мой гадальный шар. Выйдя из башни, ступай налево, и выйдешь на городскую площадь.', 'Принесите Зелигу Иллюзорному из крепости Стражей Зимы в Драконьем Погосте его гадальный шар.', 'Молодец, $N! Именно ты поможешь нам пережить эти страшные времена, ибо так предрешено судьбой. Но это лишь начало нашего долгого пути…', 'Удалось тебе найти мой шар?', NULL, NULL, 'Гадальный шар', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12283, 'Правду не скроешь', 'Нужно выяснить, что здесь происходит. Нам нужен дневник генерала!$B$BЯ почти уверена, что ты найдешь дневник на ее ночном столике на втором этаже ее дома. Этот дом находится рядом с церковью, напротив стойл и лесопилки.$B$BКак добудешь дневник, отнеси его в Ядозлобь, верховному палачу.$B$BДелать это придется по старинке: сила зеркала иссякла, мне самой едва хватит!$B$B<Агент ухмыляется.:', 'Добудьте дневник верховного генерала Аббендис по просьбе агента Скулли и передайте этот дневник верховному палачу Росу в Ядозлоби.', 'Провались оно все! Нет бы принести мне хорошие новости!', 'Давно пора, $N! Что тебя задержало?', NULL, NULL, 'Дневник верховного генерала Аббендис', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12284, 'Преследуй по пятам', 'Мы понесли серьезные потери, $r.$B$BТолько одно утешает меня – наши враги пострадали не меньше. Я запросил подкрепление, но большая часть наших отрядов застряла в Бухте торговцев. Похоже, пока что нам придется рассчитывать только на себя.$B$BКак бы тяжело нам не приходилось, мы должны сражаться до конца! Эти земли богаты ресурсами, необходимыми Орде для операций в Нордсколе.$B$BМы должны сдерживать наступление Альянса, пока не прибудет помощь. Иди же и заставь их войска повернуть назад.', 'Командир Баргок приказал вам убить 15 представителей или игроков Альянса на Лесозаготовках Синего Неба.', 'Говоришь, ты прикончил 15 врагов, $C? Приятно слышать.$B$BПо крайней мере, ты выиграл для нас несколько дней.$B$BДержи. Ты заслужил награду.', NULL, NULL, NULL, 'Убито представителей Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12285, 'Без головы не возвращайся!', 'Их нападение неизбежно, $C. Мне нужно, чтобы ты $gпробрался:пробралась: туда и $gлишил:лишила: Алый Натиск его главы. Я имею в виду в буквальном смысле!$B$BЭто будет нелегко... Аббендис, безусловно, будет окружена множеством своих людей. Предлагаю тебе взять с собой хотя бы пару друзей.$B$BПринеси мне ее голову, и я позабочусь о том, чтобы тебя достойно вознаградили за спасение Ядозлоби.$B$BПровалишь задание – не смей возвращаться!', 'По заданию верховного палача Роса из Ядозлоби убейте верховного генерала Аббендис и принесите ему ее голову.', 'Посмотрим-посмотрим, как им удастся оживить ее при отсутствии головы!$B$B<Смех верховного палача вызывает немало удивленных взглядов украдкой.>$B$BЯ немного беспокоюсь, что ты упустила верховного адмирала, но все равно – ты герой нашего времени, $N.$B$BВозьми свою награду... ты заслужила ее!', 'Должен ли я дать приказ своим силам прорываться к Молоту Агмара?$B$BИли тебе удалось убить верховного генерала?', NULL, NULL, 'Голова верховного генерала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12286, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12287, 'Орик Чистосердечный и Забытое взморье', 'Я смотрел на сферу и видел путь, которым тебе должно пройти, $N.$B$BМного лет назад ужасное злодеяние было совершено на берегах Драконьего Погоста. Что тебе надлежит сделать – то покрыто тьмой, но я уверен, что твоя судьба – на юге, среди руин Забытого взморья.$B$BОтправляйся по дороге на юго-восток через разоренную городскую площадь. Следуй этим путем, пока не доберешься до Рассветного края. Там встретишь моего старого друга по имени Орик Чистосердечный. Он будет ждать тебя.', 'Ищите помощи у Орика Чистосердечного в Рассветном краю на Драконьем Погосте.', 'Зелиг сообщил, что ты придешь, друг мой.$B$BЯ Орик Чистосердечный, паладин Серебряного Авангарда. Жрица, что стоит напротив меня на другой стороне костра – Тильда Даратан. Мы здесь по заданию Серебряного Авангарда – присланы успокоить несчастные проклятые души, пытающиеся сбежать из крепости Стражей Зимы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12288, 'В военном лазарете', 'Эй, $C! Пожалуйста, помоги нам!$B$BМы понесли тяжелые потери. Столько раненых... одной мне никогда не исцелить всех их. А если наши солдаты не встанут на ноги, нам придется сдавать позиции и уходить из Седых холмов!$B$BВот, возьми этот бинт и приступай к перевязке раненых на поле боя.$B$BПоторопись, $N, иначе они умрут!!!', 'Аумана с Лесозаготовок Синего Неба просит вас перевязать медицинским жгутом 10 израненных рыскателей.', 'Спасибо, дорогой $N!$B$BБлагодаря тебе мы сможем продержаться еще один день. Может быть, для нас еще есть надежда выжить...', NULL, NULL, NULL, 'Исцелено израненных застрельщиков', 'Медицинский жгут', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12289, 'Нападем, пока враг слаб!', 'Сегодня был черный день для Альянса. Много хороших парней полегли на поле битвы. Остается только утешать себя тем, что они храбро сражались и забрали с собой жизни многих врагов.$B$BТеперь, когда большую часть наших сил переправили в Бухту торговцев, мы остались одни перед лицом грядущей опасности. Мы должны защитить стратегически важные регионы, в которых добываются ресурсы, необходимые для победы над Ордой. Мы не можем подвести Альянс!$B$BИди же, $N. Не дай нашим врагам зализать раны и собраться с силами. Отомсти за павших братьев и подари нам надежду на победу!', 'Сержант Хартсман поручил вам убить 15 игроков или представителей Орды на Лесозаготовках Синего Неба.', 'Отличная работа, $N.$B$BТы выиграл для нас немного времени – вряд ли больше, чем один день, но Альянс благодарен тебе за каждую минуту передышки.', NULL, NULL, NULL, 'Убито представителей Орды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12290, 'Эликсир из темноплевела', 'На побережье бродят духи проклятых. В жизни то были отважные и благородные воины Альянса, но в смерти их настигло проклятие – они прикованы к этому миру до конца времен. Чтобы их освободить, нужно узнать, что их так терзает!$B$BК юго-востоку отсюда, на зловещей Возвышенности, растет редкая травка, именуемая темноплевелом. Из этого темноплевела я могу приготовить эликсир, который позволит тебе на время войти в мир забытых душ. Ступай, набери этой травы.', 'Добудьте на Зловещей возвышенности 5 экземпляров темноплевела по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте.', '<Орик берет траву и принимается готовить эликсир.>$B$BНе волнуйся, $N, долго ждать не придется.', 'Удалось ли тебе набрать темноплевела?', NULL, NULL, 'Темноплевел', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12291, 'Забытая повесть', 'Яды, содержащиеся в эликсире из темноплевела, заставят тебя потерять сознание. Темноплевел оказывает столь мощное воздействие, что даже твой дух будет обманут. Это позволит тебе на время вступить в мир мертвых.$B$BСделавшись духом, поговори с призрачными обитателями Забытого взморья. Узнай, отчего они так страдают, и возвращайся ко мне.$B$BПомни, $N: некогда эти духи были солдатами Альянса! Держись с ними почтительно, как то подобает их достоинству!$B$BНу, вот тебе эликсир, ступай на юг, на Забытое взморье.', 'Выслушайте повесть о бедствиях забытого крестьянина, забытого ружейника, забытого рыцаря и забытого пехотинца по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте.', '<Глаза Орика наполняются слезами.>$B$BОни не знают. Никто из них не знает! Они считают Артаса великим героем, в то время как именно Артас приказал сжечь корабли! Именно Артас бросил нас всех в этой ледяной пустыне!$B$B<Орик плачет.>$B$BНо не все солдаты из флота принца погибли во время той суровой зимы. Я был еще мальчишкой, когда мне представился случай сразиться с Плетью и спасти наш дом от верной гибели. И я воспользовался этим шансом, $N!', 'У меня достаточно темноплевела, я могу сделать новый эликсир, $N.', NULL, NULL, 'Забытый крестьянин опрошен', 'Забытый ружейник опрошен', 'Забытый рыцарь опрошен', 'Забытый пехотинец опрошен');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12292, 'Помощь местных жителей', 'Наше противостояние с Ордой в Седых холмах зашло в тупик. До сегодняшнего дня силы были равны, и я не видел выхода из этой ситуации.$B$BНо сегодня к нам за помощью обратилась группа местных звероловов. Похоже, ордынцы ограбили их и отобрали что-то важное... какую-то реликвию. $B$BОни пообещали нам свою поддержку взамен за возвращение этой штуковины. Так что я поручаю тебе сходить в Торговую лавку Вечнозеленого леса, что к западу от Крепости Завоевателей, и забрать оттуда кедровый сундук.', 'Лейтенант Думонт из Приюта Янтарной Сосны поручил вам добраться до Торговой лавки Вечнозеленого леса и забрать кедровый сундук.', 'Ты пробовал его открыть? С виду – ящик как ящик...$B$B<Лейтенант Думонт встряхивает коробку, в глубине которой что-то глухо перекатывается.>$B$BВпрочем, что мне дело до того, что там внутри. Если в обмен на эту штуку мы получим помощь в войне с Ордой, то меня мало волнует ее содержимое. Пусть там даже будет лекарство от чумы – какая разница!', 'Ты достал ящик, $N?', NULL, NULL, 'Кедровый сундук', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12293, 'Дело сделано', 'Теперь у нас есть то, что нужно звероловам. Осталось только подписать с ними договор о сотрудничестве! $B$BОтнеси ящик зверолову по имени Иван на Заставу Тополиной рощи, что к северу отсюда.$B$BЕсли наши предположения верны, местные звероловы с радостью присоединятся к королевской армии.', 'Отнесите кедровый сундук Ивану на Заставу Тополиной рощи.', '', NULL, NULL, NULL, 'Кедровый сундук (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12294, 'Заключение договора', 'Рад слышать, что твои люди выполнили свою часть сделки. $B$BСкажи Думонту, что мы тоже сдержим слово.', 'Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12295, 'Урок дипломатии', 'Мы уже давно пытались договориться со звероловами, но они отказывались идти нам навстречу. Однако теперь, когда у нас есть их дурацкий ящик, дело должно сдвинуться с мертвой точки.$B$BХорошие новости для наших послов в Среброречье! Неделю назад мы отправили туда Дюкаля, и ему даже удалось добиться некоторого прогресса, судя по его последнему донесению.$B$BСтупай в Среброречье и помоги ему заключить договор. Город находится прямо по дороге на северо-запад.', 'Поговорите с военным атташе Дюкалем в Среброречье.', 'Я так рад наконец-то познакомиться с тобой, $N! До нас доходили слухи о твоих подвигах. Добро пожаловать в Среброречье.$B$BЭти звероловы – отличные ребята! Крепкие, отважные, знают эти края как свои пять пальцев. Хорошо, что мы наконец-то перетянули их на свою сторону.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12296, 'На грани жизни и смерти', 'Какая страшная битва...$B$BЯ побывала во многих сражениях, $C, но эта резня была самой жестокой из всех. Наши стычки с Ордой стали еще более ожесточенными. Идет война за право оставаться здесь, в Нордсколе – война не на жизнь, а на смерть.$B$BЕсли мы хотим продержаться здесь еще хотя бы день, нам надо перевязать раненых. Их здесь слишком много... мне не справиться одной.$B$BВот, я подготовила специальные бинты. Возьми их, если хочешь помочь мне исцелить наших бойцов.', 'Реанна с Лесозаготовок Синего Неба просит вас перевязать медицинскими бинтами 10 израненных пехотинцев отряда Западного Края.', 'Отлично!$B$BБлагодаря тебе Альянс продержится еще один день.$B$BСпасибо тебе, друг.', NULL, NULL, NULL, 'Вылечено пехотинцев из дружины Западного края', 'Медицинские бинты', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12297, 'О предателях и предательстве', 'Этот список необходимо доставить главнокомандующему Халфорду Змеевержцу. Он командует седьмым легионом, расположенным в Крепости Стражей Зимы на восточной границе Драконьего Погоста.$B$BЕсли кто-нибудь из предателей, упомянутых в этом списке, умудрился втереться к нему в доверие... последствия могут быть необратимыми.$B$BТоропись, $N. Покажи этот документ Гриру Рудомолоту в Крепости Западной Стражи и объясни всю важность твоего поручения. Тогда он посадит тебя на самого быстрого грифона, знающего путь в Крепость Стражей Зимы!', 'Капитан Адамс попросил вас показать депешу Альянса Гриру Рудомолоту из Крепости Западной Стражи.', '<Грир читает депешу поверх очков, время от времени бросая на вас заинтересованные взгляды.>$B$BБудет тебе самый стремительный грифон! Эту информацию нужно немедленно передать главнокомандующему Змеевержцу!', 'Здравствуй, $C.', NULL, NULL, 'Депеша Альянса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12298, 'Главнокомандующий Халфорд Змеевержец', '<Грир отдает вам депешу.>$B$BНебесная Песня отвезет тебя в Крепость Стражей Зимы, $N. Могу поспорить, ты еще никогда не $gлетал:летала: на таком быстром грифоне. Вперед!', 'Отвезите депешу Альянса главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, которая находится на востоке Драконьего Погоста.', '<Главнокомандующий дочитывает депешу и раздраженно комкает ее.>$B$BТы знаешь, где сейчас эти люди, упомянутые в списке? Вон они, рядом с главными воротами, болтаются на виселице.$B$BПриманка для упырей...', 'Что там у тебя, солдат?', NULL, NULL, 'Депеша Альянса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12299, 'Северное гостеприимство', 'Рад познакомиться с тобой, $N. Давай скрепим наш союз кровью ордынцев?$B$BПочему бы тебе не поохотиться на мародеров из Крепости Завоевателей, которые бродят вокруг нашего города, к западу отсюда? Эти мерзкие животные не заслуживают пощады.$B$BВ конце концов, было бы неплохо узнать, на что способны наши новые союзники.', 'Сергей из Среброречья просит вас убить 8 мародеров из Крепости Завоевателей.', '', NULL, NULL, NULL, 'Мародер из Крепости Завоевателей убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12300, 'Испытание смелости', 'Ладно, дружок. Пару раз ты нас действительно $gвыручил:выручила:, но это еще не показатель смелости. $B$BВ наших краях нельзя стать настоящим охотником, не почувствовав себя в шкуре жертвы.$B$B<Сергей вытаскивает из ножен свой охотничий нож и протягивает его вам.>$B$BПредводителя проклятых орков, нападающих на наш город, зовут Костехват. Его легко найти в лагере на северо-западе.$B$BДа, ты меня правильно $gпонял:поняла:: я поручаю тебе освежевать этого мерзавца.', 'Найдите часового Костехвата к северо-западу от Среброречья и пройдите испытание смелости.', 'Не делай этого, $N. Люди, пославшие тебя сюда... им нельзя доверять.', NULL, NULL, NULL, 'Испытание смелости', 'Покрытый кровью скальпель', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12301, 'Правда вернет нам свободу', 'Зелиг дал мне эту хрустальную сферу много лет назад, особо проинструктировав касательно ее использования. В течение пяти лет – чувствовал ли я гнев, беспокойство или печаль из-за событий, происходивших здесь – я должен был сосредотачивать свои мысли на этой сфере.$B$BТеперь я понимаю, почему Зелиг отдал этот кристалл мне.$B$BОтнеси мою хрустальную сферу на Забытое взморье. Найди развалины моей старой базы в верхней части побережья и помести сферу в центре поселения. Пусть обитающие там увидят мир через призму моего сердца и моей души.', 'По просьбе Орика Чистосердечного из Рассветного края, что на Драконьем Погосте, задействуйте хрустальную сферу Орика в развалинах, расположенных на Забытом взморье, для освобождения обитающих там Забытых.', '<Лицо Орика освещается улыбкой.>$B$BТы сделал сегодня доброе дело, $N. Благодаря тебе сотни потерянных душ обрели свободу и покой.', 'Готово?', NULL, NULL, 'Забытые освобождены', 'Хрустальная сфера Орика', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12302, 'Предупреждение', 'Спасибо за помощь, $N. Меня зовут Саша. Послушай, мне очень надо выбраться отсюда.$B$BЛюди, которые послали тебя сюда... мои товарищи... с ними что-то произошло. Они изменились... Они хотят... сделать тебя $gодним:одной: из них.$B$BЭто испытание – всего лишь начало...$B$BДойди до северо-запада Среброречья, и ты увидишь все собственными глазами.$B$BУдачи... и помни – никому нельзя доверять!', 'Дойдите до северо-западного края Среброречья.', 'Кто здесь? Ты хочешь меня убить?$B$BНе надо! Пожалуйста, не трогай меня!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12303, 'Финансовое обеспечение военных нужд', '$gИнтендант понижает голос и шепчет.>$B$B$C, мне нужна твоя помощь; наша казна пуста! Отряд Кор\'крона у Врат Гнева забрал все деньги на тамошние сражения.$B$BОднако до меня дошли слухи, что в местах кораблекрушений на Забытом взморье к юго-востоку отсюда можно найти затонувшие сокровища.$B$BНам непременно нужно что-то срочно предпринять, или мы не сможем продолжать войну с Алым Натиском. Война, знаешь ли, обходится недешево!', 'По заданию интенданта Бартлетта из Ядозлоби добудьте 6 сундучков с забытыми сокровищами.', '<Интендант раскрывает рот от удивления, но затем его глаза сужаются, и он пару секунд пристально смотрит на вас.>$B$BЯ надеюсь, ты не прихватил ничего с собой? Ты ж не будешь настолько эгоистичен, когда на кону – судьба Ядозлоби?$B$BКроме того, я намереваюсь дать тебе в награду определенный процент от добытого тобой. Не очень много, конечно, но в такие времена всем нам приходится чем-то жертвовать.', 'Ну, и на сколько сокровищ Альянса тебе удалось наложить свою руку?', NULL, NULL, 'Забытое сокровище', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12304, 'Недвижимость на взморье', 'Ядозлоби пора расширить свое влияние!$B$BВ свое время мы разберемся с Алым Натиском, ну, а пока я хочу, чтобы ты $gотправился:отправилась: в место, называемое Забытым взморьем. У тех мест – огромный потенциал, а $gвидел:видела: бы ты, какой там ландшафт!..$B$BК сожалению, там полным-полно людских призраков, членов экипажей затонувших кораблей и прочих, еще не осознавших, что они уже умерли.$B$BРасчисти берег и прибрежные воды – и, быть может, мы с тобой вскоре уже сможем говорить о постройке там новой, миленькой, уютной усыпальницы.', 'По поручению наблюдателя Хансена, находящегося к северу от Забытого взморья убейте 20 призраков Забытого взморья.', 'Теперь ты понимаешь, $C? Это же будет самый популярный курорт Нордскола!$B$BКак тебе нравится название \"Убежище Хансена\" – или, к примеру, \"Залив $N\"? Звучит довольно привлекательно, согласись!', 'И почему я сомневаюсь в твоей искренности, когда ты пытаешься уверить меня, что сделал все, что мог, чтобы очистить берег от призраков?..', NULL, NULL, 'Убито призраков Забытого взморья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12305, 'Прощальные мысли', 'Ты $gоказал:оказала: честь и мне, и памяти сотен ветеранов Альянса, $N. Зелиг поступил мудро, прислав тебя сюда. Пожалуйста, вернись к нему и передай ему мою благодарность. Он будет рад услышать о том, что произошло на Забытом взморье.$B$BЯ, в отличие от Зелига, не наделен пророческим даром, но уверен, что тебя, друг, ждет великая судьба.$B$BПрощай!', 'Вернитесь к Зелигу Иллюзорному в крепость Стражей Зимы в Драконьем Погосте.', '<Зелиг улыбается.>$B$BНет, это я тебе обязан. Орик мне как брат. Ты изменил его жизнь и вернул надежду бесчисленному множеству других.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12306, 'Клуб \"Пиво месяца\"', 'Чем нас больше - тем лучше, $N. Вступив в клуб \"Лучший пивовар месяца\", ты сможешь дегустировать самые выдающиеся сорта пива.$B$BЗаполни членскую карточку \"Лучшего пивовара месяца\" и отнеси ее Рай\'ме в Пристанище Темнотерна. Оно находится в Оргриммаре, в Аллее Духов.', 'Отнесите заполненную членскую карточку \"Лучшего пивовара месяца\" Рай\'ме в Пристанище Темнотерна. Оно находится в Оргриммаре, в Аллее Духов.', '', NULL, NULL, NULL, 'Анкета для вступающих в клуб \"Пиво месяца\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12307, 'Аконитовый корень', '$gСлышал:Слышала: когда-нибудь про волчий борец? Мерзкая трава... из-за нее гибнет половина наших посевов.$B$BМы пололи сорняки всю прошлую неделю, но оставшиеся корни опять дали всходы!$B$BДумаешь, это все чепуха? Учти: если волчий борец опять заколосится, произойдет... нечто ужасное! Так что если увидишь этот сорняк возле деревни – выдерни его немедленно, и ты окажешь нам очень большую услугу!', 'Катя из Среброречья просит вас выдернуть восемь аконитовых кореньев.', '', NULL, NULL, NULL, 'Аконитовый корень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12308, 'Побег из Среброречья', 'Ты... ты не $gодин:одна: из них? Быстрее! Выпусти меня отсюда!$B$BНужно как можно скорее вернуться в Приют Янтарной Сосны! Как только лейтенант Думонт узнает, что представляют из себя эти люди, он немедленно прикажет сравнять этот лагерь с землей!', 'Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Когда вы доберетесь до Приюта Янтарной Сосны, доложите лейтенанту Думонту обо всем, что вы видели.', 'Воргены. Мерзкие, вонючие, Светом проклятые воргены. $B$BПора показать этим тварям, где их место.', NULL, NULL, NULL, 'Побег из Среброречья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12309, 'Найти Дюркона!', 'После того как Плеть пробила южную стену, я приказал кавалеристу Дюркону разведать городской склеп. И вот буквально только что мне передали его доклад.$B$BДонимающая нас нежить лезет из двух мест: из развалин крепости Стражей Зимы, где теперь плодятся воины Плети, и из нашего же собственного городского склепа! Плеть под шумок сумела поселить там своего некролорда!$B$BДюркон просит подмоги. Отыщи его и помоги ему, $N. Склеп находится на западном краю городской площади.', 'Отыщите кавалериста Дюркона в склепе Стражей Зимы в Драконьем Погосте.', 'Ох, братишка, что там творится! В последний раз я еле ноги унес. Собственно, потому и попросил помощи у главнокомандующего.$B$B<Дюркон смерил вас взглядом.>$B$BЧеловек, у тебя безумный взгляд настоящего искателя приключений! Это хорошо, потому что для того, чтобы выполнить мою просьбу, надо быть безумцем.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12310, 'Мгновенный ответ', 'Наша реакция должна быть незамедлительной. Сокрушительной. Мы должны проучить этих мерзавцев раз и навсегда.$B$BНаши разведчики засекли местонахождение выживших звероловов Среброречья... тех, кому удалось спастись от пожара. Сейчас они прячутся вдоль юго-восточной дороги... видимо, пытаются заманить нас в ловушку.$B$BОтправляйся на Заставу на опушке и разберись с ними. Судя по донесениям, их предводителя зовут Владек... сделай так, чтобы я больше ничего о нем не слышал.', 'Лейтенант Думонт отправил вас к Заставе на опушке убить Владека и 7 охотников Среброречья.', 'Как жаль, что звероловы оказались... немного не теми, кем мы их себе представляли. Нам бы не помешали хорошие бойцы.$B$BПокойтесь с миром, мерзавцы.', NULL, NULL, NULL, 'Охотник Среброречья убито', 'Владек убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12311, 'Подземная обитель некролорда', 'Упрятанные за холодные каменные стены этого склепа покоятся останки благородных и знаменитых личностей, нашедших свою смерть в Нордсколе. В самой глубине усыпальницы обитает некролорд, поднимающий тела умерших в качестве слуг Плети.$B$BТебе нужно прорваться вглубь склепа Стражей Зимы и убить некролорда Амариона. Только так можно остановить зло, идущее изнутри!$B$BИ еще, $N: внимательно осмотри помещение, где найдешь Амариона – там может храниться важная информация.', 'По заданию кавалериста Дюркона из крепости Стражей Зимы убейте некролорда Амариона.', 'Теперь если бы мы смогли остановить атаки армии Плети на крепость извне, то у нас появилась бы возможность послать помощь лорду Фордрагону к Вратам Гнева.', NULL, NULL, NULL, 'Некролорд Амарион убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12312, 'Тайны Плети', 'Вся эта обтянутая плотью книга испещрена коряво нацарапанными, будто вырезанными клинком, странными символами и изображениями. Вы и понятия не имеете, что здесь написано, но совершенно уверены, что это очень важно.$B$BОтнесите том кавалеристу Дюркону, стоящему на страже наверху склепа Стражей Зимы.', 'Отнесите сшитый плотью фолиант кавалеристу Дюркону, находящемуся в крепости Стражей Зимы на Драконьем Погосте.', 'Какая бы информация ни содержалась в этой книге, она, должно быть, очень важна! Когда ты выбегал из склепа, я слышал, как вслед тебе неслись вопли и завывания!$B$BНужно сообщить обо всем главнокомандующему!', 'Фолиант Плети?', NULL, NULL, 'Сшитый плотью фолиант (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12314, 'Смерть капитану Зорне!', 'Если мы будем бездействовать, силы Орды прорвут нашу оборону и окончательно захватят Бухту торговцев. Командует ими капитан Зорна, которая неотлучно находится на своем корабле, пришвартованном в дальнем конце бухты.$B$BЕсли тебе удастся ее победить, обороноспособность Орды значительно понизится, и мы постараемся воспользоваться этим шансом, чтобы отвоевать порт. Только учти, $N: Зорна – превосходный боец. В одиночку тебе с ней не справиться. Захвати с собой подмогу – или воспользуйся работающим крошшером, если такой у тебя имеется.', 'Убейте капитана Зорну и вернитесь к барону Фриману в Бухту торговцев.', 'Отлично, $N! Оставшись без предводителя, Орда растеряет все свое преимущество. Я немедленно прикажу нашим солдатам начать штурм.', NULL, NULL, NULL, 'Капитан Зорна убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12315, 'Смерть капитану Брайтвотеру!', 'Наши солдаты постоянно сталкиваются с отрядами подкрепления Альянса. Такое ощущение, будто их предводитель предугадывает каждый наш шаг!$B$BНастало время покончить с капитаном Брайтвотером. Он командует войсками с борта флагмана Альянса, пришвартованного на дальнем конце бухты.$B$BПобедить его будет нелегко, $N. Возьми с собой несколько проверенных друзей – или хотя бы воспользуйся ключом от одного из отремонтированных крошшеров. Мне все равно, каким образом умрет Брайтвотер – но я больше не хочу слышать его имя в списках живых!', 'Убейте капитана Брайтвотера и доложите о своей победе генералу Хазгару из Бухты торговцев.', 'Ты – истинный воин Орды, $N. Твоя храбрость вдохновляет наши войска!', NULL, NULL, NULL, 'Капитан Брайтвотер убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12316, 'Припрем их к стенке!', 'Нельзя допустить, чтобы Орда захватила Бухту торговцев! Этот порт чрезвычайно важен для наших операций в Седых холмах и за их пределами.$B$BКапитан Камнегрив забрал оставшихся дружинников из бригады Западного Края на поиски прохода в горах, так что на его помощь рассчитывать не приходится. $B$BОтправляйся на поле битвы, $N, и убей берсерков из Крепости Завоевателей. Орда послала их сражаться с нами, но мы не оставим им ни единого шанса вытеснить нас из Бухты!', 'Убейте 10 представителей или игроков Орды в Бухте торговцев, после чего вернитесь к лейтенанту Стюарту.', 'Твоя отвага служит примером всем дружинникам из бригады Западного Края. Теперь они будут сражаться с удвоенной силой, и вскоре этот порт будет наш!', NULL, NULL, NULL, 'Убито представителей Орды в Бухте Торговцев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12317, 'Припрем их к стенке', 'Проклятые солдаты из дружины Западного Края оказались более стойкими, чем мы предполагали. Они сражаются до последней капли крови, храбро и безрассудно, а у нас нет времени ждать, когда их силы иссякнут. $B$BЗавоевательница Кренна приказала как можно быстрее захватить этот порт, поэтому ты, $N, сделаешь все, чтобы переломить ситуацию в нашу пользу. Убивай наших врагов, сломи их моральный дух. Только тогда мы сможем водрузить наш флаг над Бухтой торговцев.$B$BИди же – Завоевательница Кренна не любит ждать.', 'Убейте 10 представителей или игроков Альянса в Бухте торговцев, после чего вернитесь к центуриону Каггруму.', 'Скоро этот порт будет принадлежать нам. Отличная работа, $N.', NULL, NULL, NULL, 'Убито представителей Альянса в Бухте Торговцев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12318, 'Спасем Хмельной фестиваль!', '$N, наши шпионы обнаружили, что дворфы Черного Железа замышляют сорвать Хмельной фестиваль!$B$BДворфов из Глубин Черной горы возглавляет пивовар-отступник Корен Худовар. Нас беспрестанно атакуют их буровые комбайны!$B$BНаш шпион сейчас прячется в \"Угрюмом Обжоре\", таверне в Глубинах Черной горы. Он располагает наиболее свежей информацией о замыслах Худовара.$B$BНайди нашего шпиона и спаси Хмельной фестиваль!', 'Поговорите со шпионом Хмельного фестиваля в таверне \"Угрюмый обжора\" в Глубинах Черной горы.', 'Ты из лагеря Хмельного фестиваля? Ну наконец-то! Хмельной фестиваль еще можно спасти.$B$B$N, мы должны остановить Корена Худовара! Нельзя допустить, чтобы наш священный праздник был сорван. Мы должны совершить возлияния пивным богам!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12319, 'Тайна книги', 'Что же это может быть, $N? Проклятый лич явно наложил на тебя не просто обычное проклятие!$B$B<Дюркон листает зловещие страницы.>$B$BЯ даже не знаю, правильно ли я держу эту книгу. Однако необходимо выяснить, какие важные сведения в ней содержатся!$B$B<Дюркон возвращает вам книгу.>$B$BГлавнокомандующий должен знать, что делать. Отнеси сшитый плотью фолиант к нему и расскажи ему о том, что произошло.', 'Отнесите сшитый плотью фолиант главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы в Драконьем Погосте.', '<Глаза Халфорда расширяются.>$B$BЯ вижу, $N, судьба улыбается нам. Я знаю, к кому следует обратиться по поводу этой книги!', 'Некролорда больше нет в живых?', NULL, NULL, 'Сшитый плотью фолиант (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12320, 'Язык Смерти', 'Возьми эту книгу и иди по дороге, ведущей к казармам. Как войдешь в казармы, спустись по лестнице, ведущей в тюрьму. В тюрьме ты найдешь инквизитора Халларда и нашего мэра, Годфри. Полагаю, именно Годфри и окажется недостающей деталью головоломки, и именно Халлард – тот человек, который сумеет ее собрать.$B$BСтупай!', 'Отнесите сшитый плотью фолиант инквизитору Халларду в тюрьме крепости Стражей Зимы.', 'Быть может, Годфри и расскажет нам то, что ему известно об этой книге, если у него будут на то серьезные основания.$B$B<Халлард оборачивается к мэру Годфри.>$B$BНе правда ли, а, мэр?', 'Ты от главнокомандующего, сын мой?', NULL, NULL, 'Сшитый плотью фолиант (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12321, 'Праведная проповедь', 'Годфри Хорошер, некогда человек праведный и мэр Стражей Зимы, теперь принадлежит Плети. Его трансформация из человека в неумирающего вурдалака шла медленно и в течение длительного времени. Теперь он слышит зов Короля-лича и живет только для того, чтобы служить своему господину.$B$BНо, как и любой представитель Плети, Годфри знает язык смерти и, если его правильно мотивировать, расскажет об этом фолианте то, что нам нужно.$B$BКогда услышишь то, что надлежит услышать, возвращайся к главнокомандующему на линию фронта. А я здесь приберу, по необходимости.', 'Дождитесь, пока инквизитор Халлард закончит свою праведную проповедь, и возвращайтесь к главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы на Драконьем Погосте с добытой информацией.', 'Мы должны были знать об этой проклятой усыпальнице. Это же нелепо! Герцога Августа Крушителя Врагов и Амбо Кэша нужно послать на передовую, готовить наше следующее нападение.$B$BКогда шахты будут расчищены, я пошлю тебя к Крушителю Врагов, чтобы мы могли начать нападение на наксрамасские силы Плети!$B$BИнформация, которую тебе удалось собрать за это время, будет отправлена лорду Фордрагону к Вратам Гнева на крыльях нашего самого быстрого грифона!', NULL, NULL, NULL, 'Праведная проповедь прослушана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12323, 'Выкурим их!', 'В некоторых зданиях в центе Бухты торговцев все еще прячутся мелкие банды трусливых работников Торговой Компании. Я не могу позволить этим крысам прятаться в щелях, пока мои солдаты сражаются с Ордой. $B$BМожет быть, тебе удастся \"убедить\" их убраться отсюда подобру-поздорову? Вот, возьми ды$Nю шашку и выкури этих бродяг из бараков, лесопилки и конюшни. Только не связывайся с ними – они кусаются.', 'С помощью дымовой шашки выкурите 20 отставших работников Торговой Компании из зданий. Доложите об успешном выполнении поручения сержанту Дауни.', 'Отличная работа, солдат! Теперь наши люди могут сосредоточиться на войне с Ордой.', 'Ты уже выкурил трусливых работников Торговой Компании из наших зданий?', NULL, NULL, 'Выкурено трусливых работников Торговой компании', 'Дымовая шашка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12324, 'Выкурим их!', 'Мало того, что в нашем порту шныряют трусливые лазутчики Альянса – так еще и мерзкие работники Торговой Компании окопались в самом центре Бухты! Но я не собираюсь посылать за ними солдат – много чести для этих паршивцев. $B$BМожет быть, тебе удастся \"убедить\" их убраться отсюда подобру-поздорову? Вот, возьми ды$Nю шашку и выкури этих бродяг из бараков, лесопилки и конюшни. Только не связывайся с ними – вдруг они заразные?', 'С помощью дымовой шашки выкурите 20 отставших работников Торговой Компании из зданий. Доложите об успешном выполнении поручения Каменному стражу Тотему Ярости.', 'Генерал будет рад узнать, как ловко мы расправились с Торговой Компанией. Теперь нас ничто не будет отвлекать от войны с Альянсом.', NULL, NULL, NULL, 'Выкурено трусливых работников Торговой компании', 'Дымовая шашка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12325, 'Заброс на вражескую территорию', 'Ты многое $gсделал:сделала: для поддержки наших усилий в борьбе с Плетью, $N. На самом деле, боевой дух тех, кто с тобой общается, поднимается до небывалых высот! Таково твое влияние среди военных и гражданских в крепости Стражей Зимы, $gсоюзник:союзница:.$B$BИ именно благодаря тебе мы теперь готовы к наступлению! Тебе следует доложиться герцогу Августу Крушителю Врагов – он находится к востоку отсюда, на заставе Торсона, через Поля Падальщиков. Командир грифонов Урик на грифоньей площадке подготовил специального грифона, который высадит тебя за вражескими линиями. Вперед!', 'Поговорите с командиром грифонов Уриком, чтобы организовать полет на заставу Торсона на Драконьем Погосте. Когда прибудете на заставу, доложитесь герцогу Августу Крушителю Врагов.', 'А, вот и наш знаменитый герой. Что ж, добро пожаловать в эпицентр, $N. Позволь мне быстренько ввести тебя в курс дела.$B$BСамые мощные силы Тель\'зана пробились в усыпальницу Стражей Зимы. Они роются в ее глубинах в поисках тел и душ, чтобы послать их против Стражей Зимы, пока из Наксрамаса нас будут поливать своим огнем ужасные чумные машины Плети!$B$BМы должны ударить сейчас и надеяться, что лорд Фордрагон сможет продержаться у Врат Гнева еще немного.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12326, 'Паровой сюрприз', 'Это задание типа \"найти и уничтожить\". Поведешь танк на Поля Падальщиков с целью разрушить чумные телеги Плети. Танку придан экипаж, состоящий из бойцов Седьмого легиона. Миссия будет признана выполненной, только если все они останутся в живых!$B$BТебе нужно будет приблизиться к чумной телеге и выпустить инженеров. Пусть они делают свое дело, а потом двигайтесь к следующей телеге. Когда поле будет очищено от чумных телег, направляйся к усыпальнице, расположенной перед разрушенной крепостью и высади там экипаж. Встретишься там внутри с Амбо Кэшем.', 'Воспользовавшись паровым танком Альянса, уничтожьте 6 чумных телег и доставьте гвардейцев 7-го легиона к усыпальнице Стражей Зимы. Если успешно выполните задание, поговорите с Амбо Кэшем внутри усыпальницы Стражей Зимы на Драконьем Погосте.', 'А вот почему я без штанов – не имеет значения. Скажем, меня не в то место шрапнелью ударило – и больше не будем об этом, договорились?$B$BТак, значит, ты порушил все чумные телеги на полях и привез моих солдат в целости и сохранности. Впечатляет. Ты один из первых, кто сумел зайти так далеко. Как жаль, что тебе придется ехать обратно на Поля Падальщиков. Ага, у нас тут вроде как рецидив.', NULL, NULL, NULL, 'Уничтожено чумных фургонов', 'Гвардейцы 7-го легиона благополучно доставлены', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12327, 'Опыт вне тела', 'А, ты ищешь знаний о прошлом. Это признак мудрости, $r.$B$BОбычно меня просят предсказать будущее, но дожившие до моих седин понимают, что мудрость прошлого гораздо более полезна, нежели туманные видения грядущего. $B$BВыпей это снадобье и загляни в мой хрустальный шар. Посмотрим, что откроется тебе в его глубинах.', 'Выпейте зелье из легчайшей пыльцы возле хрустального шара Рууны и узрите видение из прошлого.', 'Помогло ли тебе это видение? Кажется, в трансе ты упомянул Деревню Солнцестояния. Странно... вот уже второй раз за сегодня я слышу это название.', 'Да, $N?', NULL, NULL, 'Видение из прошлого', 'Зелье из легчайшей пыльцы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12328, 'Просьба Рууны', 'Я не возьму с тебя деньги за мои услуги, ибо чувствую, что ты действуешь во имя общего блага, и многое будет зависеть от того, что ты сегодня узнаешь.$B$BНо я попрошу тебя принести один важный компонент для зелья – легчайшую пыльцу папоротниковых мотыльков, которые водятся на северо-востоке отсюда. Принеси пыльцу, и я помогу тебе перенестись в то время и место, где произошли интересующие тебя события.', 'Рууна Слепая просит вас принести ей четыре горсти легчайшей пыльцы.', 'Отлично! Это то, что надо.$B$BТеперь осталось только закончить приготовление зелья.', 'Ты собрал пыльцу, $N?', NULL, NULL, 'Легчайшая пыльца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12329, 'Судьба и совпадения', 'В этом мире есть два типа людей, $N: одни верят в совпадения, а другие – нет.$B$BПотеряв зрение, я обрела дар ясновидения. Полагаю, теперь ты можешь догадаться, к какому типу я принадлежу.$B$BСегодня утром у одной девушки по имени Саша было такое же видение, как у тебя. Думаю, ты захочешь с ней поговорить.$B$BТы найдешь ее на востоке, в Торговой лавке Белой Сосны, что по пути в Деревню Солнцестояния.', 'Поговорите с Сашей в Торговой лавке Белой Сосны.', 'Ну наконец-то! Ты пришел помочь мне?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12330, 'Слабое место Анатолия', 'Моя сестра где-то неподалеку, а этот мерзавец не хочет признаваться, где они ее прячут.$B$BКажется, собственная судьба ему безразлична, но у меня есть кое-какие планы. Когда-то я была знакома с женой Анатолия, Татьяной – она работала на конюшне.$B$BВозьми этот дротик с транквилизатором, оглуши женщину и притащи сюда. Только не убивай ее – она нам понадобится, чтобы разговорить Анатолия.$B$BОбещаю, как только мы найдем мою сестру, я помогу тебе расправиться с человеком, который стоит за всем этим.', 'Саша из Торговой лавки Белой Сосны просит вас выстрелить усыпляющим дротиком в Татьяну, жительницу Деревни Солнцестояния. Принесите ее в Торговую лавку Белой Сосны.', 'Мы... едва не опоздали.$B$BНадо спасти Аню. Вперед!', NULL, NULL, NULL, 'Татьяна доставлена на место', 'Усыпляющий дротик', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12331, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
