INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12372, 'Защита храма Драконьего Покоя', 'Воодушевленные избытком магической энергии, текущей сейчас через лазуритовое святилище драконов, синие драконы осмелились напасть на сам храм Драконьего Покоя!$B$BЯ хочу, чтобы ты $gполетел:полетела: на одном из наших защитников в самую гущу битвы, убивая их драконов, больших и малых, и атакуя выбросы энергий силовых линий в самом святилище с целью его дестабилизации.$B$BЗащитники Драконьего Покоя находятся снаружи, на восточной и западной террасах. Поговори с кем-нибудь из них, чтобы полететь на битву.$B$BБез твоей помощи, $N, нас ждет поражение.', 'По просьбе Деврестраза из храма Драконьего Покоя убейте 3 лазурных драконоидов, 5 лазурных драконов и дестабилизируйте Лазуритовое святилище драконов.', 'Невероятно! Позволь мне сказать, что я не устаю поражаться, на что способны вы, представители молодых рас.$B$BМы в долгу перед тобой. Вернешься ли ты завтра, чтобы продолжить помогать нам?', 'Как протекает битва? Мы их тесним?', NULL, NULL, 'Лазурный дракон убито', 'Лазурный дракончик убито', 'Лазуритовое святилище драконов дестабилизировано', NULL);
