INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12410, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12411, 'Спасение сестры', 'Прошу тебя, $N! Я знаю, что ты собираешься убить Аругала. Клянусь могилой своего отца, я помогу тебе осуществить задуманное.$B$BНо... Я не могу бросить Аню среди этих дикарей. Она еще так молода и невинна!$B$BПомоги мне спасти сестру, и я буду сражаться с тобой бок о бок против Аругала.$B$BЯ знаю, где находится логово, о котором говорил Анатолий. Оно с другой стороны холма. Надо действовать без промедления, мы должны освободить мою сестру.', 'Найдите Аню в Логове Ночного Воя рядом с Деревней Солнцестояния.', 'Дяденька, заберите меня отсюда! Эти воргены злые, я их боюсь!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12412, 'Друг моего врага', 'Я хочу, чтобы ты $gвдолбил:вдолбила: в свою пустую голову хотя бы одну истину: Альянс никогда не закрепится в Седых холмах.$B$BЗдесь слишком много источников руды, дерева и прочих полезных ресурсов – и потому мы не можем сдать им ни одного стратегического рубежа.$B$BДо сих пор удача была на нашей стороне... но вскоре ход битвы может измениться в пользу нашего врага.$B$BМы узнали, что к силам Альянса могут присоединиться местные зверобои. Убей их прежде, чем они заключат союз с нашим врагом.', 'Завоевательница Кренна из Крепости Завоевателей приказала вам убить 8 охотников Среброречья и их предводителя Владека с Заставы на опушке.', 'А, ты вернулся. $B$BНу, расскажи мне, что за дурацкие слухи про воргенов ходят в моей крепости?', NULL, NULL, NULL, 'Охотник Среброречья убито', 'Владек убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12413, 'Нападение на Среброречье', 'Несколько часов назад эти звероловы были всего лишь простыми крестьянами, способными разве что пополнить ряды Альянса.$B$BТеперь же они превратились в нечто... иное. А мне не нравится то, что я не могу объяснить. Отправляйся на север Седых холмов, найди их столицу, Среброречье, и помоги моим людям стереть этих бродяг с лица земли.', 'Завоевательница Кренна из Крепости Завоевателей просит вас yбить 8 защитников Среброречья в Холмах Среброречья.', 'Неплохо, $N. Возможно, ты не настолько бестолков, как мне показалось вначале.', NULL, NULL, NULL, 'Защитник Среброречья убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12414, 'Лошадки для лагеря', 'Ну, капитан Камнегрив отозвал большую часть нашей квава... кавава... короче, отправил всех всадников сражаться за Бухту торговцев.$B$BА мы выбрали хорошее местечко для лагеря, потому что тут бегает множество мустангов нагорья – и здесь, и на Каменистых холмах на северо-востоке. Так вот, капитан поручил мне поймать парочку этих лошадок. $B$BНе желаешь мне помочь? У меня есть палка с веревкой, а вокруг лагеря растет куча дикой моркови. Ты привяжи морковку к веревке, подмани мустанга поближе и отведи его прямо в лагерь.', 'Приведите 5 мустангов нагорья к оруженосцу Перси в Лагерь дружины Западного Края.', 'Ух ты! Какие выносливые лошадки! Да, капитан будет очень доволен нашими успехами.', 'Что, неужели в лагере уже слышится ржание мустангов?', NULL, NULL, 'Поймано мустангов нагорья', 'Палочка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12415, 'Пугалка для коней', 'Дружина Западного Края, прихлебатели Альянса, разбили лагерь на севере, возле Тор Модана. Они совершили ошибку, послав часть своих отрядов в Бухту торговцев, так что в их лагере практически не осталось кавалерии.$B$BСейчас они пытаются поймать и приручить несколько диких мустангов нагорья, которые бродят повсюду вокруг Лагеря дружины Западного Края и на Каменистых холмах. Надо помешать им прежде, чем они пополнят свои опустевшие стойла. Брось эту штуку рядом с лошадьми – это обратит их в бегство.', 'Обратите в бегство 15 мустангов нагорья и вернитесь к Соулоку Штормовая Ярость в Лагерь Уанква.', '<Соулок одобрительно кивает.>$B$BМолодец, Профессия. нельзя позволить Альянсу взять над нами верх.', NULL, NULL, NULL, 'Испугано мустангов нагорья', 'Светошумовая граната', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12416, 'Горячая битва', 'Армия Плети заполонила святилище. Его хранительница, Далия Благословение Солнца, пропала. Красные змеи, павшие при защите святилища, теперь окружают нас, приняв форму жутких скелетов тлеющих змеев. Опасная ситуация, $r.$B$BГруппу тебе подобных, пытающуюся поуменьшить поток воинов Плети из святилища, возглавляет капитан Искандар.$B$BПриди к нему на помощь... но, пожалуйста, оставайся позади его бойцов. Поток воинов Плети бесконечен, а мне вовсе не хочется потерять тебя в одном из этих ущелий.', 'Помогите капитану Искандару удержать каньоны, приняв участие в смерти 12 хладных атакующих вурдалаков, 8 хладных атакующих упырей и 1 хладного атакующего поганища.Когда это будет выполнено, возвращайтесь к Церистразу.', 'Неприятная работа, я знаю – и от всего сердца благодарю тебя за ее выполнение.$B$BПлети нельзя позволить продвинуться ни на йоту ближе к Драконьему Покою, иначе мы неизбежно его потеряем.', 'Я рад, что ты по прежнему с нами, $C.', NULL, NULL, 'Хладный агрессивный вурдалак убито', 'Хладный агрессивный упырь убито', 'Хладное агрессивное поганище убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12417, 'Погребение', 'Есть еще одно дело, требующее внимания. Мои собратья гибнут в битве, и если мы не поторопимся, они лишь пополнят ряды тлеющих змеев.$B$BОтправляйся в святилище через один из проходов к югу или к северу... Там, должно быть, плотность сил Плети не так велика.$B$BПоищи в святилище рубиновые желуди, упавшие с дерева, и посади их рядом с телами моих павших соплеменников. Они положат начало новой жизни... а это – гордая и счастливая судьба для любого из нас.', 'Отправляйтесь в Рубиновое святилище драконов через любой из южных или северных проходов и поищите рубиновые желуди. С помощью рубиновых желудей предайте тела павших красных драконов земле. По выполнении задания вернитесь к Церистразу.', 'Преданные земле, мои собратья смогут вновь дарить жизнь. Ты спас их от судьбы куда худшей, чем смерть.$B$BЯ не знаю слов на твоем языке, которые могли бы выразить, как много это значит для меня и мне подобных. Я благодарю тебя, $R.', NULL, NULL, NULL, 'Предано земле рубиновых хранителей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12418, 'Через огненные поля', 'У меня есть для тебя последнее задание, $r… дело, которое должно повернуть ход сражения в нашу пользу.$B$BВозвращайся в святилище и убей некромантов, раздувающих горнило этой бойни. Когда они будут мертвы, нам, должно быть, удастся отбросить их силы и в результате отвоевать святилище.$B$BМне также нужно, чтобы ты $gотыскал:отыскала: источник осквернения под святилищем и $gуничтожил:уничтожила: его.$B$BЯ знаю, что уже и так потребовал от тебя слишком многого, но если ты выполнишь и эту мою просьбу, мы одержим победу в этой битве.', 'Отправляйтесь в Рубиновое святилище драконов через любой из северных или южных проходов, затем убейте 6 хладных некромантов и уничтожьте источник осквернения, находящийся под святилищем. По выполнении задания вернитесь к Церистразу.', 'Далия… так они и ее обратили?$B$BДалия хранила нам верность очень долгое время… если они смогли совратить такую возвышенную душу, как ее, то для других представителей молодых рас это тревожный знак. Спасибо за то, что она теперь свободна. Я надеюсь, она пребывает в мире.$B$BСегодня ты протянул нам руку самоотверженной помощи, $R. Я пошлю сообщение Совету о том, какой подвиг ты здесь совершил.', NULL, NULL, NULL, 'Хладный некромант убито', 'Рубиновое осквернение вычищено', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12419, 'Судьба Рубинового святилища драконов', 'Вы берете в руки брошь и замечаете, что ее слабое сияние становится чуть ярче.$B$BКрас, конечно, захочет узнать о судьбе Далии. Отнесите брошь ему в Драконий Покой.', 'Принесите рубиновую брошь Далии Благословения Солнца Красу в чертог правящего Совета в Драконий Покой и расскажите ему о судьбе Далии.', 'Далию захватила Плеть? Печальный день для всех нас...$B$BЯ займусь поисками нового хранителя, когда святилище вновь станет нашим. Спасибо тебе за труды... Рубиновое святилище – священное для нас место, и твои свершения не будут забыты.$B$BПриятно знать, что есть еще такие герои, как ты, я призову тебя в один прекрасный день. А пока он не наступил – пусть странствия укрепляют твою душу и тело.', 'Приветствую тебя, $R. Я ощущаю присутствие моей рубиновой броши. Передай мне ее.$B$BА что случилось с Далией?', NULL, NULL, 'Рубиновая брошь (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12420, 'Клуб \"Пиво месяца\"', 'Думаю, тебе понравится быть членом нашего клуба \"Лучший пивовар месяца\". Ведь это означает, что у тебя всегда будет самое лучшее и свежее пиво.$B$BЗаполни членскую карточку \"Лучшего пивовара месяца\" и отнеси ее Ларкину Громовару в таверну \"Горючий камень\" в Стальгорне.', 'Отнесите членскую карточку \"Лучшего пивовара месяца\" Ларкину Громовару в таверну \"Горючий камень\" в Стальгорне.', '', NULL, NULL, NULL, 'Анкета для вступающих в клуб \"Пиво месяца\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12421, 'Клуб \"Пиво месяца\"', 'Чем нас больше - тем лучше, $N. Вступив в клуб \"Лучший пивовар месяца\", ты сможешь дегустировать самые выдающиеся сорта пива.$B$BЗаполни членскую карточку \"Лучшего пивовара месяца\" и отнеси ее Рай\'ме в Пристанище Темнотерна. Оно находится в Оргриммаре, в Аллее Духов.', 'Отнесите заполненную членскую карточку \"Лучшего пивовара месяца\" Рай\'ме в Пристанище Темнотерна. Оно находится в Оргриммаре, в Аллее Духов.', '', NULL, NULL, NULL, 'Анкета для вступающих в клуб \"Пиво месяца\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12422, 'Расчетливая доброта', 'Слушай внимательно, $N. Ты $gдолжен:должна: действовать быстро и решительно.$B$BОдин из сержантов Кренны захватил зверолова-изгнанника из Среброречья. Обычно они казнят пленников до заката солнца.$B$BМы не можем это допустить! Видишь ли, эта пленница похожа по описанию на старшую дочь Михаила, знакомую тебе по этому дневнику. $B$BЕсли мы отпустим ее и проследим, куда она пойдет, то сможем обнаружить местонахождение главаря звероловов. Вот, отнеси ей эту бумагу.', 'Отнесите приказ о помиловании пленному зверолову в Холмы Среброречья.', 'Вы меня отпускаете? Правда? Слушай, я не хочу неприятностей... эти чудовища убили моего отца и похитили сестру. Честно говоря, у меня сейчас совсем другие заботы.', 'Ты пришел убить меня?', NULL, NULL, 'Приказ о помиловании (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12423, 'Дневник Михаила', 'Насколько вы можете понять, этот дневник некогда вел житель Среброречья по имени Михаил.$B$BОн написан на неизвестном вам диалекте всеобщего человеческого языка. Вы думаете, что эти записи могут заинтересовать Завоевательницу Кренну.', 'Отнесите дневник Михаила Завоевательнице Кренне в Крепость Завоевателей.', 'Ха! Это что, шутка такая?$B$BК чему мне книга, которую я не могу прочесть?', 'Что это у тебя в руках?', NULL, NULL, 'Дневник Михаила (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12424, 'Горгонна', 'Эта книга написана на собачьем языке мерзких людишек. Ее надо сжечь, и немедленно.$B$BОтдай ее Горгонне и не трать больше мое драгоценное время на всякие гадости.', 'Отнесите дневник Михаила Горгонне в Крепость Завоевателей.', '', NULL, NULL, NULL, 'Дневник Михаила (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12425, 'Рууна Слепая', 'Не нравится мне эта ситуация со звероловами.$B$BЕсли они не на стороне Альянса – значит, возможно, они помогают Плети. А это не приведет ни к чему хорошему.$B$BНо наши предыдущие усилия увенчались успехом. Мы засекли, как наша бывшая пленница встречалась с некой предсказательницей.$B$BК сожалению, потом мы потеряли след беглянки, но я уверена, что она могла бы привести нас к их предводителю. Найди Рууну Слепую и вытяни из нее все, что сможешь.', 'Поговорите с Рууной Слепой из Лагеря Рууны, что находится рядом с Перевалом Фордрассил.', 'Ты ищешь знания, которые тебе недоступны. Но знай, незнакомец – тебе может не понравиться то, что ты услышишь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12427, 'Бойцовская яма: медвежьи бои!', 'Ах, так ты тоже хочешь помахать кулаками? Честно говоря, Кренна запретила своим профессиональным гладиаторам участвовать в боях на арене. Но ты, $gдружок:подруга: – птица вольная, и потому чисто теоретически под этот запрет не попадаешь.$B$BЗдорово я придумал, верно?$B$BВ общем, если ты $gнастроен:настроена: решительно, можешь начать с какого-нибудь слабенького противника. Попробуй для начала одолеть медведя! Я, пожалуй, даже разрешу тебе привести с собой парочку друзей на подмогу.', 'Одержите победу над Железной Шкурой в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.', 'Отличная работа, дружище! Вот твоя доля.', NULL, NULL, NULL, 'Железная Шкура побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12428, 'Бойцовская яма: битва с бешеным фурболгом', 'Молодец, неплохо сражаешься!$B$BА убить фурболга тебе по зубам? Как насчет того, чтобы сразиться с одним из громадных бешеных фурболгов Нордскола?$B$BПрекрасно, прекрасно. Собирай свою команду и отправляйся на арену. Давай устроим для них настоящее шоу... Может быть, нам даже удастся немного заработать на этом представлении!', 'Одержите победу над Торггом Громовым Тотемом в Бойцовской яме, после чего поговорите с букмекером Вел\'дженом.', 'Какой тонкий расчет, дружище! Учитывая, сколько ставок было сделано против тебя, мы можем праздновать победу!', NULL, NULL, NULL, 'Торгг Громовой Тотем побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12429, 'Бойцовская яма: кровь и железо', 'Наконец-то у нас $gпоявился настоящий боец:появилась настоящая воительница:! Зрителям уже порядком надоело смотреть на вялых пленников и голодных зверей.$B$BЛадно, ближе к делу. Твой следующий противник – настоящий железный голем из глубин Тор Модана... Как ты думаешь, тебе по плечу с ним справиться?', 'Одержите победу над Кроворжавом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.', 'Эта металлическая бочка едва тебя не задавила! Честное слово, у меня чуть сердце из груди не выскочило!', NULL, NULL, NULL, 'Кроворжав побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12430, 'Бойцовская яма: смерть близка', 'Скажу тебе напрямик, детка: твой следующий соперник – убийца.$B$BВ прямом смысле этого слова.$B$BНа прошлой неделе его должны были казнить, но он задушил палача одной левой рукой. После этого солдаты Кренны разрешили мне забрать его на арену.$B$BТак что если ты откажешься от боя – не стану тебя упрекать.', 'Одержите победу над Хоргренном Страшным Расколом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.', 'Ишь, какой ловкий! Быстро ты уделал этого бешеного орка.$B$BСтавки были семь к одному против тебя, так что мы неплохо заработали!', NULL, NULL, NULL, 'Хоргренн Страшный Раскол побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12431, 'Бойцовская яма: последняя битва', 'Похоже, ты действительно $gразозлил:разозлила: Кренну. Она заключила пари с Горгонной, и теперь вызывает тебя на ринг. $B$BХодят слухи, что это будет смертельная битва! Что ж, тем хуже для тебя, и тем лучше для нашего бизнеса. $B$BВ общем, от судьбы не убежишь... так что не медли. Отправляйся на ринг и покончи с ней.', 'Одержите победу над Кренной в Бойцовской яме и обратитесь к Горгонне за наградой.', '', NULL, NULL, NULL, 'Рекомендуемое количество игроков: 3', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12432, 'Верхом на красной ракете', 'Эй, ты, $r! Тащи сюда свою ленивую задницу!$B$BАльянс приготовил груз пиломатериалов для отправки. Он сейчас хранится на их корабле к северо-востоку отсюда. Поскольку мы не можем украсть эти дровишки, нам остается только одно – сжечь все их припасы!$B$BУ гоблина на пристани есть отличные торпеды, а топливо для них хранится на гоблинском корабле, пришвартованном к северу отсюда.$B$BЗалей чуток топлива в торпеду и направь ее прямо к грузовому кораблю.$B$B<Свободен:Свободна:!', 'Генерал Горлок с маяка в Бухте торговцев приказал вам уничтожить грузовой корабль Альянса. Генерала Горлока можно застать только тогда, когда маяк находится под контролем Орды.', 'Ха-ха! Хорошо прокатился $C?$B$BЕсли уж мы не сможем наложить лапу на дровишки – то они не достанутся никому!$B$BИ когда уже эти жалкиe псы Альянса осознают свое ничтожество перед могущественной Ордой?', NULL, NULL, NULL, 'Грузовой корабль Альянса уничтожен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12433, 'В поисках растворителя', 'Нет! Только не это! Еще одна прокладка полетела...$B$BТеперь смазочное масло опять полезет из всех щелей. Без растворителя я эту гадость и за час не отчищу!$B$BСлушай, $r. Здесь, на барже Торговой Компании есть отличное топливо для ракет – кажется, они называют его \"элемент 115\". Из него получится отличный растворитель!$B$BДавай-ка ты принесешь мне немного этого топлива – конечно, за достойную плату!', 'Гуртор из Торговой бухты Орды просит вас принести ему канистру с элементом 115.', 'О, да! То, что надо! Эта штука поможет мне сэкономить усилия. $B$BВот, дружище, возьми пару звонких монет за труды. Кстати, если тебе попадется в руки еще одна канистра с топливом – кати ее сюда!', 'Ты несешь мне элемент 115, $N?', NULL, NULL, 'Элемент 115', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12434, 'Растворитель всегда пригодится!', '', 'Надеюсь, у тебя есть еще немного 115 элемента для меня, $N?', 'Молодец, дружище!$B$BНеси еще.', NULL, NULL, NULL, 'Элемент 115', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12435, 'Явиться к лорду Деврестразу', 'Я испытываю отвращение к уничтожению жизни... любой жизни. Но я не стану сидеть сложа крылья и ждать, пока Малигос перебьет всех нас и осквернит храм!$B$BЯ назначила командующим обороной Драконьего Покоя лорда Деврестраза.$B$BПоговори с Торастразой, она даст тебе дракона, который отнесет тебя к нему.$B$BПрошу тебя, $N, окажи ему помощь! Возможно, именно твое участие в обороне Драконьего Покоя позволит нам выстоять в бою с синими драконами.', 'Поговорите с лордом Деврестразом в храме Драконьего Покоя.', 'Ты, должно быть, $N? Королева предупредила меня о твоем приходе.$B$BДа, мы будем рады твоей помощи. Она нам очень нужна.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12436, 'Прибавка к зарплате', 'Здравствуй, $C. Здесь, в Крепости Завоевателей, мы продаем и покупаем то, что велит нам Кренна... и по той цене, которую она установила.$B$BЧестно говоря, бизнес идет ни шатко, ни валко. Но я собираюсь срубить немного денежек на стороне – и заодно накормить наших бугаев. Ты не откажешься поохотиться на оленей и принести мне немного отборного мяса?$B$BПоверь мне, этих зверей здесь так много, что тебе не придется их искать.', 'Поставщик Лоркран из Крепости Завоевателей просит вас убить несколько высокорогих оленей и принести ему 5 кусков сочной оленины.', '', NULL, NULL, NULL, 'Сочная оленина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12437, 'Верхом на красной ракете', 'Слушай, $N: исход этой битвы зависит как от численного, так и от тактического превосходства над противником. $B$BЯ хочу поручить тебе задание, которое может изменить ход событий в пользу Альянса. У нас появилась возможность нанести сокрушительный удар, но удобный момент не будет длиться вечно. $B$BВ конце этого причала есть торпеды, с помощью которых мы могли бы потопить грузовой корабль Орды, стоящий на якоре к северо-западу отсюда.$B$BДобудь немного топлива с гоблинского корабля, который пришвартован на севере, и направь одну из торпед прямо на их грузовоз!', 'Командир Хоузер с маяка Бухты торговцев поручил вам уничтожить грузовой корабль Орды.Командира Хоузера можно застать только тогда, когда маяк находится под контролем Альянса.', 'Рад слышать, что тебя не задело взрывом.$B$BОтличная работа, $С.$B$BМы просто не могли допустить, чтобы Орда получила этот груз пиломатериалов!', NULL, NULL, NULL, 'Ладья Орды разрушена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12438, 'Разыскивается: Креуг Клятвопреступник', 'Размещено: Илюсия Лунэ.$B$BМясистый великан Плети, известный как Креуг Клятвопреступник, несет ответственность за смерть моего мужа, детей и моих дорогих друзей семьи Шелестящая Завеса. Тот, у кого хватит смелости претендовать на эту награду, может найти Креуга на юго-восточной оконечности Полей Падальщиков.$B$BЯ взываю о справедливости! Убейте Креуга Клятвопреступника!$B$BНа случай, если Креуг действительно будет убит, я выделила деньги и некоторые вещи и передала верховному лорду Леорику фон Цельдигу, чтобы они были выданы как награда.$B$BПожалуйста, защитите нас!', 'Убейте Креуга Клятвопреступника и возвращайтесь за наградой к верховному лорду Леорику фон Цельдигу в крепость Стражей Зимы на Драконьем Погосте.', 'Хорошая работа, $N. Я извещу Илюсию, что нашелся герой, услышавший ее зов о помощи и восставший на бой с этим злодеем! Вот твоя награда.', NULL, NULL, NULL, 'Креуг Клятвопреступник убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12439, 'Проблемы на западе', 'Появилась новая сила, угрожающая разрушить все, над чем мы трудились, $N. Тебе придется отправиться на запад, в Покой Звезд. Верховный маг Модера чувствует сильное возмущение силовых линий нашего мира, которое следует немедленно ликвидировать!$B$BОтправляйся прямо сейчас, $N! Поговори с Родни Веллсом на грифоньей площадке и объясни ему, зачем тебе нужно в Покой Звезд. Он даст тебе самого быстрого из своих грифонов. Прибудешь на место – поговори с верховным магом Модерой.', 'Поговорите с Родни Веллсом в крепости Стражей Зимы, чтобы отправиться в Покой Звезд в западном Драконьем Погосте.', 'Нет, друг, еще одного Раскола нам не надо! Я сделаю все, что в моих силах, чтобы помочь тебе в твоей миссии…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12440, 'В Покой Звезд!', 'Когда будешь $gготов:готова:, я посажу тебя на своего самого быстрого грифона, который отнесет тебя в Покой Звезд. Когда будешь там, найди верховного мага Модеру и поговори с ней.', 'Поговорите с проекцией верховного мага Модеры в Покое Звезд в западной части Драконьего Погоста.', 'Стало быть, Вас услышал мой крик о помощи? Ты как раз вовремя, друг мой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12441, 'Разыскивается: верховный шаман Кровохват', 'Размещено: Дролфи$B$BКогда я был на Зловещей возвышенности с моими родичами, Бездарем и Бротом, на нас напала злобная шайка волчеров из стаи Кроволапов. Мы пытались бежать, но, боюсь, они схватили Бездаря и Брота.$B$BЯ требую отмщения! Найдется ли кто-нибудь достаточно храбрый, чтобы отправиться в юго-восточные пределы Драконьего Погоста, на Зловещую возвышенность, и убить верховного шамана Кровохвата и его окружение?$B$BЯ передал увесистый кошель с золотом верховному лорду Леорику фон Цельдигу, чтобы он отдал деньги тому, кто заявит о своем свершении!', 'Убейте верховного шамана Кровохвата и приходите за наградой к верховному лорду Леорику фон Цельдигу в крепость Стражей Зимы на Драконьем Погосте.', 'Отлично проделанная работа, $N! Я сообщу Дролфи, что нашелся достойный герой, и жестокого Кровохвата больше нет!', NULL, NULL, NULL, 'Верховный шаман Кровохват убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12442, 'Разыскивается: командир Алого Натиска Иустус', 'Размещено: верховным лордом Леорик фон Цельдиг$B$BНа северо-восточной тропе, ведущей в крепость Стражей Зимы, попал в засаду и был уничтожен батальон 7-го легиона. Это совершил командир Алого Натиска Иустус с отрядом безмозглых приспешников Алого Натиска. Подобные холодные, расчетливые преступники достойны справедливого возмездия!$B$BКрепость Стражей Зимы требует правосудия! Отыщите командира Иустуса в лагере Натиска к северо-востоку отсюда и прекратите его гнусное существование!$B$BЛюбой, кто осмелится взять на себя эту задачу, получит от меня награду!', 'Убейте командира Алого Натиска Иустуса и возвращайтесь к верховному лорду Леорику фон Цельдигу в крепости Стражей Зимы в Драконьем Погосте, чтобы получить награду.', 'Наконец-то хоть кто-то воспрепятствовал гнусным планам Алого Натиска! Ты оказал крепости Стражей Зимы большую услугу, $N!', NULL, NULL, NULL, 'Командир Алого Натиска Иустус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12443, 'В поисках растворителя', 'Нет! Только не это! Еще одна прокладка полетела...$B$BТеперь смазочное масло опять полезет из всех щелей. Без растворителя я эту гадость и за час не отчищу!$B$BСлушай, $r. Здесь, на барже Торговой Компании есть отличное топливо для ракет – кажется, они называют его \"элемент 115\". Из него получится отличный растворитель!$B$BДавай-ка ты принесешь мне немного этого топлива – конечно, за достойную плату!', 'Барблфинк с Базы Альянса просит вас принести ему канистру с элементом 115.', 'О, да! То, что надо! Эта штука поможет мне сэкономить усилия. $B$BВот, подруга, возьми пару звонких монет за труды. Кстати, если тебе попадется в руки еще одна канистра с топливом – кати ее сюда!', 'Ты несешь мне элемент 115, $N?', NULL, NULL, 'Элемент 115', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12444, 'Резня в Черноречье', 'Торговая Компания свернула лесозаготовки в Седых холмах – очевидно, они испугались за свои шкуры.$B$BИх склады остались без присмотра, и мы не можем позволить Орде наложить на них лапы. $B$BЛесопилка Черноречья – меньшая из лесозаготовок в этом районе, но нам все равно хотелось бы получить ее в свое распоряжение. Оттесни силы Орды и помоги нам захватить лесопилку. Нельзя позволить, чтобы накопленные материалы были использованы для изготовления оружия, которое будет обращено против нас.', 'Капитан разведчиков Картер просит вас убить 10 представителей или игроков Орды на Лесопилке Черноречья.', 'Отличная работа, $N. Нам бы пригодилась помощь таких ребят, как ты. Тогда мы могли бы прищучить Орду раз и навсегда!', NULL, NULL, NULL, 'Убито представителей Орды в Черноречье', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12446, 'Растворитель всегда пригодится!', '', 'Надеюсь, у тебя есть еще немного 115 элемента для меня, $N?', 'Молодец, дружище!$B$BНеси еще.', NULL, NULL, NULL, 'Элемент 115', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12447, 'Обсидиановое святилище драконов', 'Армия Плети идет. Кориалстраз взывает к своим союзникам в тщетной попытке спасти свое Рубиновое святилище, но, похоже, добрая воля красных драконов не распространяется на защиту святилищ других драконов.$B$BТы $gудивлен:удивлена:? А я ничуть.$B$BЗдесь есть и другие представители моего крыла – те, кто остался вычищать из нашего обсидианового святилища вредителей-нежить, что заполонили его. Все, что тебе нужно, чтобы доказать, что ты благороднее и праведнее самой Алекстразы, – это прогуляться до святилища и пару раз взмахнуть там мечом, или что там у тебя?$B$BХоть какое-то развлечение.', 'Отправляйтесь в Обсидиановое святилище драконов к северо-западу от Драконьего Покоя, совсем рядом с Вратами Гнева. Найдите в святилище Серинара и предложите ему свою помощь.', 'Никак не могу решить, чему больше удивляться – тому, что ты действительно пришел на помощь черным драконам или что ты остался цел после общения с Нэлис.$B$BЕе слова источают яд, но, я думаю, в Драконьем Покое могут иногда подумать и о нас тоже.$B$BА может быть, просто вокруг нее кишмя кишат красные драконы...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12448, 'Горячая битва', 'Армия Плети заполонила святилище. Его хранительница, Далия Благословение Солнца, пропала. Красные змеи, павшие при защите святилища, теперь окружают нас, приняв форму жутких скелетов тлеющих змеев. Опасная ситуация, $r.$B$BГруппу тебе подобных, пытающуюся поуменьшить поток воинов Плети из святилища, возглавляет капитан Дрейзен.$B$BПриди к нему на помощь... но, пожалуйста, оставайся позади его бойцов. Поток воинов Плети бесконечен, а мне вовсе не хочется потерять тебя в одном из этих ущелий.', 'Помогите капитану Дрейзену удержать каньоны, приняв участие в смерти 12 хладных атакующих вурдалаков, 8 хладных атакующих упырей и 1 хладного атакующего поганища.Когда это будет выполнено, возвращайтесь к Варгастразу.', 'Неприятная работа, я знаю – и благодарю тебя за ее выполнение.$B$BПлети нельзя позволить продвинуться за пределы святилища, иначе ее воины заполонят все эти земли.', 'Я рад, что ты по прежнему с нами, $R.', NULL, NULL, 'Хладный агрессивный вурдалак убито', 'Хладный агрессивный упырь убито', 'Хладное агрессивное поганище убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12449, 'Погребение', 'Есть еще одно дело, требующее внимания. Мои собратья гибнут в битве, и если мы не поторопимся, они лишь пополнят ряды тлеющих змеев.$B$BОтправляйся в святилище через проход на юге... Там, должно быть, плотность сил Плети не так велика.$B$BПоищи в святилище рубиновые желуди, упавшие с дерева, и посади их рядом с телами моих павших соплеменников. Они положат начало новой жизни... а это – гордая и счастливая судьба для любого из нас.', 'Отправляйтесь в Рубиновое святилище драконов через южный проход и поищите там рубиновые желуди. С помощью рубиновых желудей предайте тела павших красных драконов земле. По выполнении задания вернитесь к Варгастразу.', 'Преданные земле, мои собратья смогут вновь дарить жизнь. Ты спас их от судьбы куда худшей, чем смерть.$B$BЯ не знаю слов на твоем языке, которые могли бы выразить, как много это значит для меня и мне подобных. Я благодарю тебя, $R.', 'Я уж начал беспокоиться, что силы Плети, обосновавшиеся в святилище, покончили с тобой. Хорошо, что ты еще жив.', NULL, NULL, 'Предано земле рубиновых хранителей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12450, 'Через огненные поля', 'У меня есть для тебя последнее задание, $r… дело, которое должно повернуть ход сражения в нашу пользу.$B$BВозвращайся в святилище и убей некромантов, раздувающих горнило этой бойни. Когда они будут мертвы, нам, должно быть, удастся отбросить их силы и в результате отвоевать святилище.$B$BМне также нужно, чтобы ты $gотыскал:отыскала: источник осквернения под святилищем и $gуничтожил:уничтожила: его.$B$BЯ знаю, что уже и так потребовал от тебя слишком многого, но если ты выполнишь и эту мою просьбу, мы одержим победу в этой битве.', 'Отправляйтесь в Рубиновое святилище драконов через южный проход, затем убейте 6 хладных некромантов и уничтожьте источник осквернения, находящийся под святилищем. По выполнении задания вернитесь к Варгастразу.', 'Далия… так они и ее обратили?$B$BДалия хранила нам верность очень долгое время… если они смогли совратить такую возвышенную душу, как ее, то для других представителей молодых рас это тревожный знак. Спасибо за то, что она теперь свободна. Я надеюсь, она пребывает в мире.$B$BСегодня ты протянул нам руку самоотверженной помощи, $R. Быть может, не все в Орде унаследовали черные сердца от своих предков. Я пошлю сообщение Совету о том, какой подвиг ты здесь совершил.', NULL, NULL, NULL, 'Хладный некромант убито', 'Рубиновое осквернение вычищено', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12451, 'Вперед, в Лагерь Уанква', 'Когда мы возводили Крепость Завоевателей, я отправил разведчика Вор\'такха на восток с поручением. Он должен был вступить в контакт с нашими союзниками, таунка, которые обитают в Лагере Уанква, на восточной границе Седых холмов, возле Седой Пасти.$B$BНайди Вор\'такха, выслушай его отчет и предложи свою помощь. Я уверен, он будет рад переложить часть забот на плечи героя, которого так высоко ценит Крепость Завоевателей.', 'Поговорите с разведчиком Вор\'такхом в Лагере Уанква.', '<Вы называете себя и объясняете, что вас послал сержант Назгрим.>$B$BА, тебя прислали нам на помощь. Это хорошо. $B$BЛюди Тормака найдут дело для твоего клинка.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12452, 'zzOLD Судьба рубинового святилища драконов', '', 'Принесите Церистразу рубиновую брошь Далии и расскажите ему о ее судьбе.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12453, 'Взгляд с высоты', 'Меня попросили оказать помощь в борьбе против Альянса. В данный момент наши силы примерно равны, но мы постоянно ищем способ переломить ситуацию в нашу пользу.$B$BНапример, императорские орлы, кружащие над горами на востоке, могли бы стать отличными разведчиками. Возьми это серебряное перо. С помощью него можно объединить мое зрение с глазами птиц. $B$BПредставляешь, насколько велико будет наше преимущество, если мы сможем свысока следить за всеми перемещениями противника?', 'Заклинательница ветра Серый Рог просит вас коснуться серебряным пером шести императорских орлов в Седых холмах.', '', NULL, NULL, NULL, 'Привязано взглядов императорских орлов', 'Серебряное перо', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12454, 'Жизненный цикл', 'Изера спит в Изумрудном Сне, наблюдая и за Сном, и за Азеротом. Но во Сне поселилось ужасное зло, и я боюсь, что оно имеет влияние и на Изеру.$B$BНедавно я попросила ее о помощи в борьбе против сил Плети, поднимающих ледяных змеев в других драконьих святилищах. Она не поняла меня...$B$BВместо этого она велела защитникам нашего святилища расценивать других драконов, не зеленых, как врагов.$B$BМне нужно, чтобы ты $gубил:убила: несколько когтемахов. В святилище должен быть восстановлен баланс.', 'По просьбе Нишеры Хранительницы Садов из изумрудного святилища драконов убейте 5 изумрудных небесных когтей.', 'Не сожалей о той роли, которую тебе пришлось сыграть в жизненном цикле. Рождение, смерь и возрождение – все это части естественного хода вещей.', 'Чем скорее мы разберемся с изумрудными небесными когтями, тем скорее изумрудное святилище возвратится к своему естественному балансу.', NULL, NULL, 'Изумрудный небесный коготь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12455, 'Унесенные ветром', 'С боеприпасами плохо дело, дружище. Поставки боеприпасов из крепости Стражей Зимы были прерваны из-за ледяных змеев, летающих над нами. Ветролеты были за считанные секунды разодраны в клочья, а груз их рассеян по ветру. Большая часть их так и лежит на Полях Падальщиков.$B$BМне нужно, чтобы ты $gотправился:отправилась: обратно и $gподобрал:подобрала: ящики с оружием и боеприпасами, разбросанные по всему этому треклятому месту.$B$BИ поторопись! Мы же не можем начать наступление без ружей и пуль к ним, $gприятель:детка:!', 'По поручению Амбо Кэша из усыпальницы Стражей Зимы соберите 8 ящиков снаряжения Стражей Зимы.', 'Как раз вовремя! Кое-кто из моих ребят немного погорячился – они решили полезть в склепы, что к востоку и к западу от нас. Нечего и говорить, эти безмозглые гули одолели их числом. Нужно спасти тех, кто остался в живых!', 'Ну и где мое вооружение, малец?', NULL, NULL, 'Снаряжение Стражей Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12456, 'Перо Алистоса', 'Я чувствую, что святилище не полностью пришло в равновесие. Хранитель Малахитора был разгневан нашими действиями, и я чувствую, он не станет слушать доводов разума.$B$BАлистос – огромный небесный коготь, обитающий на южном конце изумрудного святилища драконов. Он возглавляет силы воздушной обороны святилища. Боюсь, что нам придется с ним драться.$B$BВозьми эти сброшенные перышки небесных когтей и положи их на землю, где он сможет их увидеть. Он придет. Принеси мне его перо.', 'Добудьте и принесите Нишере Хранительнице Садов в Изумрудное святилище драконов перо Алистоса.', 'Не оплакивай судьбу Алистоса. Он посвятил свою вечную жизнь защите Изумрудного святилища драконов, он возродится.$B$BНадеюсь, когда он вернется к нам, он не окажется во власти Изумрудного кошмара, который, кажется, завладел Дремлющей.', 'Тебе уже удалось сразить Алистоса? Не стесняйся попросить помощи у друзей.$B$BНа самом деле, поскольку хранитель Малахитора очень силен, я рекомендую тебе именно так и поступить!', NULL, NULL, 'Перо Алистоса', 'Сброшенные перышки небесного когтя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12457, 'Ты и пушка', 'Мы установили скорострельные пушки и баррикады к востоку и к западу отсюда. Наши раненые прячутся в обеих комнатах и изо всех сил стараются не привлекать внимания вурдалаков.$B$BТеперь, когда у нас есть боеприпасы, я прошу тебя встать к одной из пушек и проложить с ее помощью путь для наших солдат! Оказавшись у пушки, вызови солдата, который прячется в укрытии, и прикрой его огнем, чтобы не подпускать к нему воинов Плети!$B$BВперед!', 'Спасите 8 раненых солдат 7-го легиона по просьбе Амбо Кэша из усыпальницы Стражей Зимы в Драконьем Погосте.', '$N, я не видел подобного героизма со времен войны в Силитусе!$B$BУверен, что любой из этих солдат выскажется за то, чтобы лорд Фордрагон повысил тебя в должности!$B$BА теперь вернемся к делам насущным. Наши разведчики доносят, что Тель\'зан близко.', NULL, NULL, NULL, 'Спасено раненых солдат 7-го легиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12458, 'Семена плеточника', 'Нам нужно больше оружия для борьбы с Плетью! Помочь могут естественные свойства Изумрудного святилища драконов, которое находится на юго-востоке.$B$BЛюбое неживое существо, кроме освобожденных Сильваной, вступившее в драконье святилище, рассыпается в прах.$B$BЯ хочу проверить одну гипотезу, и ты мне в этом поможешь, $gюный:юная:$r. Ступай в Изумрудное драконье святилище и добудь там семена изумрудного плеточника.', 'Принесите 3 семени плеточника лорду Итару на вершине храма Драконьего Покоя.', 'О, я уже чувствую биение пульса природы внутри этих семян!$B$BНужно использовать их с умом.', 'И сколько семян тебе пока что удалось раздобыть?', NULL, NULL, 'Семя плеточника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12459, 'Что создает, то может и разрушать', 'Поскольку семян у нас только три, надо их использовать максимально эффективно.$B$BТвои цели – это один из оживленных ледяных змеев, что кружит на севере близ Покоя Галакронда, Турджид Зловещий в разрушенных казармах на Полях Падальщиков на востоке и надзиратель Убийственный Взгляд в Джинта\'каларе далеко на северо-востоке.$B$BВ то время, как более слабых воинов Плети семена попросту уничтожат, этих, более могучих, они значительно ослабят. Ослабят достаточно, чтобы позволить тебе справиться с ними в одиночку.', 'Уничтожьте ослабленного оживленного ледяного змея, ослабленного Турджида Зловещего и ослабленного наблюдателя Убийственного Взгляда по просьбе лорда Итара, который находится на вершине храма Драконьего Покоя.', 'Отлично! Все как я и рассчитывал. Надо будет связаться с Изерой и посмотреть, что она на это скажет.$B$BЕсли ее, конечно, удастся выманить из ее кошмаров…$B$BСпасибо, $N. Ты незаменим.', NULL, NULL, NULL, 'Ослабленный оживленный ледяной змей убито', 'Ослабленный Турджед Зловещий убито', 'Ослабленный надзиратель Убийственный Взгляд убито', 'Семена гнева природы');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12460, 'Прибытие в Рубиновое святилище драконов', 'Ты нам $gнужен:нужна: в Рубиновом святилище драконов.$B$BДраконов осаждают со всех сторон: тут и синие драконы, и Плеть… Им приходится не легче, чем нам. Похоже, дела плохи. Но зато это предоставляет нам редкую возможность заключить ценный союз.$B$BЯ собрала отряд, чтобы отправить его на помощь красным драконам. Если в тебе живет боевой дух, иди к Церистразу и помогай ему во всем. Его можно найти на уступе к востоку от Рубинового святилища.', 'Явитесь к Церистразу на уступе к востоку от Рубинового святилища драконов, к западу от Драконьего Покоя.', 'Тебя прислала посол Лориэль?$B$BЕсли тебе доведется беседовать с ней снова, передай, что мы очень ценим ее помощь. Нам приходится вести войну на несколько фронтов сразу…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12461, 'Прибытие в Рубиновое святилище драконов', 'Ты отбываешь в Рубиновое святилище драконов. Это не обсуждается.$B$BДраконы находятся со всех сторон в окружении синих драконов и сил Плети… так что они не в лучшем положении, чем мы. Не так уж часто нам выпадает возможность самим искупить прегрешения наших предков.$B$BЯ поручил одному из полков помочь красным драконам сражаться с силами Плети в Рубиновом святилище. Присоединяйся к ним и размозжи воинов Плети подошвами своих сапог!$B$BЗа Орду!', 'Явитесь к Варгастразу на хребте у Рубинового святилища драконов, к востоку от Молота Агмара.', 'Тебя прислал посол Голлук?$B$BЕсли тебе доведется еще раз говорить с ним, передай ему, что мы весьма признательны за эту помощь. Нам приходится вести борьбу на несколько – слишком много! – фронтов одновременно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12462, 'Кирпичик за кирпичиком', 'Спустись по этой лестнице – и вот они, врата проклятия: воины Плети повсюду, насколько глаз хватает, и их толпа становится все плотнее, с каждой секундой. Скудные сведения, которые нам удалось добыть, указывают, что два некролорда Плети со страшной скоростью опустошают первые два склепа там, внизу. Прежде чем мы вломимся в нижнюю палату, к Тель\'зану, нам нужно позаботиться об этих двух болванах и их дружках из Наксрамаса.$B$BСпустись в усыпальницу и уничтожь некролордов, а также наксрамасских грозных стражей и теней.', 'По заданию Йорда \"Бедствия\" Снегоборода, находящегося у усыпальницы Стражей Зимы, убейте некролордов Кс\'авиуса и Гора, а также 15 наксрамасских воинов Плети.', 'Это даст Амбо немного времени, чтобы все разложить по полочкам.', NULL, NULL, NULL, 'Некролорд Гор убито', 'Некролорд Кс\'авиус убито', 'Убито наксрамасских воинов Плети', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12463, 'Жаднобород должен быть найден!', 'Ходят слухи о прорытом Плетью туннеле, соединяющем бальзамировочные палаты с большими склепами, ныне разрытыми Тель\'заном и его приспешниками. Я недавно послал своего лучшего лазутчика, Жадноборода, в поисках ответов на свои вопросы, но пока еще не получил от него известий. Если бы я был человеком азартным, побился бы об заклад, что он уже на том свете.$B$BЯ хочу, чтобы ты $gспустился:спустилась: по этой лестнице, $gнаправился:направилась: прямиком в бальзамировочную палату и $gпоискал:поискала: Жадноборода. Живой или мертвый – он даст ответы.', 'По просьбе Амбо Кэша у усыпальницы Стражей Зимы найдите Жадноборода.', '<Обследуя тело Жадноборода, вы обнаруживаете его дневник.>$B$BЗапись первая$B$BОни протаскивают мертвые тела через туннель в бальзамировочную – для экспериментов. Поток этот непрерывен. Из тех, кого нельзя оживить, делают костяных созданий того или иного рода.$B$BЗапись вторая$B$BЯ боюсь, что в этом личе, Тель\'зане, скрыта какая-то темная тайна. Кто он? Был ли он когда-то... одним из нас?$B$BЗапись третья. Я обнаружил место, где находится филактерия этого лича. Она...$B$B<Остальные страницы дневника вырваны.:', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12464, 'Мой старый враг', 'Мой старый враг, верховный генерал Аббендис, прибыла в Нордскол.$B$BЕй каким-то образом удалось пережить нападения на Длань Тира, и она привела с собой на север небольшое войско. Они основали Новый Дольный Очаг к югу отсюда.$B$BКонечно, это войско может принести пользу в борьбе с Плетью, однако сама Аббендис – слишком умный противник, чтобы оставлять ее в живых. Поверь мне, если оставить их в покое, мы и оглянуться не успеем, как она вцепится нам в глотку!$B$BТак что мы оставим их без командира и займемся своими делами. Принеси мне ее голову в доказательство того, что все прошло успешно.', 'Принесите голову верховного генерала командиру Элигору Вестник Рассвета из крепости Стражей Зимы.', 'Малоприятное решение, но это было необходимо. Быть может, будь наш мир иным, я и мог бы сражаться с ней плечом к плечу…$B$B<Командир умолкает, на некоторое время задумывается, затем продолжает.>$B$BЯ несколько обеспокоен твоим рассказом об этом величественном адмирале. Как, говоришь, его имя? Бареан Вествинд? Просто не верится, что он еще жив. Он, должно быть, уже глубокий старик... Однако с ним придется разобраться позднее.$B$BНу, а пока, думаю, пришла тебе пора получить заслуженную награду.', 'Что, дело сделано?', NULL, NULL, 'Голова верховного генерала', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12465, 'Дневник Жадноборода', 'Что бы ни было написано на остальных страницах дневника Жадноборода, нужно этот дневник разыскать. Поищите в палатах на другой стороне тоннеля тех, кто напал на Жадноборода. Должно быть, они-то и разодрали его дневник!$B$BЕсли найдете недостающие страницы, принесите их Амбо Кэшу ко входу в усыпальницу Стражей Зимы.', 'Найдите недостающие страницы дневника Жадноборода: страницу 4, страницу 5, страницу 6 и страницу 7. Отнесите их Амбо Кэшу, ожидающему рядом с усыпальницей Стражей Зимы на Драконьем Погосте.', '<Амбо читает найденные вами страницы дневника.>$B$BЕсть хорошие новости, но есть и плохие. Какую рассказать первой?$B$BДа ну вот еще, зачем тебе выбор? Итак, хорошая новость в том, что если мы сможем добыть филактерию Тель\'зана, то сможем уничтожить его. Плохая – в том, что филактерия эта находится на ледяном змее весьма внушительных размеров.', 'Да уж, победителем я себя определенно не чувствую…', NULL, NULL, 'Дневник Жадноборода, стр. 4', 'Дневник Жадноборода, стр. 5', 'Дневник Жадноборода, стр. 6', 'Дневник Жадноборода, стр. 7');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12466, 'Погоня за Ледяной Бурей: передовая 7-го легиона', 'Тебе нужно отыскать передовую 7-го легиона в северном Драконьем Погосте. Вернись в крепость Стражей Зимы и выйди из города через северные ворота. Ступай на север, пока не дойдешь до дороги. Поверни налево и иди по дороге до тех пор, пока не дойдешь до линии снегов. Иди дальше на запад, пока не выйдешь на Путь Титанов. Ступай на север, и он выведет тебя прямо на передовую 7-го легиона.$B$BКак придешь туда, поговори с командиром легиона Тиралионом. Он ждет тебя.$B$BПриятно было познакомиться, $N. Прощай!', 'Явитесь к командиру легиона Тиралиону на передовой 7-го легиона в центральном Драконьем Погосте.', 'Теперь ты понимаешь, почему этот край зовется Драконьими пустошами. Повсюду, куда ни глянь, валяются кости.$B$BМы завалили, наверное, с десяток или больше ледяных змеев, но им конца не видно. У Плети хватит запасов еще на десять тысяч таких змеев, когда костей вокруг сколько угодно.$B$B<Тиралион прочищает горло.>$B$BВпрочем, не буду донимать тебя скучными подробностями. Змея, который тебе нужен, можно увидеть отсюда.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12467, 'Охота на Ледяную Бурю: филактерия Тель\'зана', 'Твой ледяной змей там.$B$B<Тиралион указывает на запад.>$B$BИ он очень большой!$B$BКогда ты будешь $gготов:готова: к бою, иди, поговори с \"Приманкой для драконов\". Он \"приведет\" змея. Когда Ледяная Буря будет достаточно близко, мы прикуем ее к земле и прикончим! Надеюсь, с твоей помощью, мы сумеем победить змея и добыть тебе эту филактерию.$B$BКогда она будет у тебя, возвращайся в крепость Стражей Зимы к главнокомандующему Халфорду Змеевержцу. Он ведет подготовку к последнему столкновению с Тель\'заном.', 'Добудьте с тела Ледяной Бури филактерию Тель\'зана и отнесите ее главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.', 'Мы из-за этого чудовища, Тель\'зана, столько хороших солдат потеряли!.. Хотел бы я видеть своими глазами, как ты разобьешь эту филактерию у него на глазах и покончишь с ним.', 'Тебе удалось достать филактерию Тель\'зана?', NULL, NULL, 'Филактерия Тель\'зана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12468, 'Поручение Завоевательницы', 'Орда – это могущественная боевая машина, в которой ты всего лишь мелкая шестеренка. $B$BЯ обеспечиваю топливо для этой машины. Если моя работа будет недостаточно эффективной, это скажется на всех нас.$B$BЛесозаготовки, руда, вода... нам нужны все эти ресурсы – равно как и Альянсу.$B$BНо прежде, чем мы выступим против этих ничтожных людишек, нам надо установить полный и безоговорочный контроль над западными территориями. $B$BПоговори с сержантом Назгримом – ему было поручено истребить врайкулов в Волдруне. Возможно, если ты хорошо проявишь себя на этой работе, мы решим доверить тебе более ответственные задания.', 'Поговорите с сержантом Назгримом в Крепости Завоевателей.', 'Значит, тебя послала Кренна? Наверное, ты не произвел на нее особого впечатления. Впрочем, ей мало кто может понравиться с первого взгляда. $B$BЧто ж, нас с тобой ждет тяжелая работа – надо выкурить врайкулов из этого гнезда.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12469, 'Вернуть отправителю', 'При ближайшем рассмотрении выяснилось, что гоблин, очевидно, вез через пустоши груз взрывчатки. Судя по торчащим из снега перьям гарпии, до места бедолага не добрался.$B$BПо-видимому, он вез взрывчатку к Вратам Гнева откуда-то с востока. Разумнее всего будет вернуться вдоль гряды обратно на восток и сообщить отправителю о судьбе его гонца.', 'Ступайте на восток вдоль гряды и доставьте груз взрывчатки Зинку в Лагерь Соплозабилось в северном Драконьем Погосте.', 'Ого! Что, значит, мы еще одного потеряли? Как же надоели эти гарпии!$B$BЛадно, неважно. Есть дело. Поможешь, а?', 'Эй, привет!', NULL, NULL, 'Сума со взрывчаткой Лагеря Соплозабилось (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12470, 'Тайна бесконечности', 'Временная буря в бронзовом святилище драконов на северо-востоке не позволяет бессмертным войти в него.$B$BВнутри драконы Бесконечности ведут бой с защитниками святилища за контроль над ним. Мы должны использовать эту возможность для получения информации.$B$BТы же не $gбессмертный:бессмертная:. Ты можешь проникнуть в святилище и задействовать там песочные часы Вечности. Защищай часы достаточно долго – и вожак драконов Бесконечности раскроет себя.$B$BБудь осторожнее: драконы Бесконечности обязательно попытаются остановить тебя!', 'Отправляйтесь в бронзовое святилище драконов. Когда проникнете в святилище, поставьте на землю песочные часы Вечности.Защищайте часы, пока они идут, а потом возвращайтесь к Хроми на вершину храма Драконьего покоя и передайте ей полученную вами информацию.', 'Ты видел Ноздорму? Бессмыслица какая-то.$B$B<Хроми пару секунд обдумывает ваши слова.>$B$BНа самом деле, это отличная новость! Мы и понятия не имели, куда делся Повелитель Времени. Мы знали только, что он исчез, отправившись решать очень важные проблемы.$B$BИтак, хотя вожак драконов Бесконечности и не объявился, тебе удалось выяснить кое-что важное: Ноздорму жив и здоров – и снова борется с ними!$B$BСпасибо тебе, $N!', NULL, NULL, NULL, 'Песочные часы Вечности защищены', 'Песочные часы вечности', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12471, 'Жестокость квалдиров', 'Благодарю тебя за спасение, $N! Эти квалдиры просто звери!$B$BОни заставляли нас сражаться с другими узниками. Милосерднее было бы просто убить нас всех!$B$BЮный Карук все еще жив, я видел, как он появился. Скажи ему, что его отец сражался до конца!', 'Расскажите Каруку о пленном узнике-клыкарре.', 'Благодарю тебя, $N. Ты подлинный друг нашему клану.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12472, 'Шаг к победе', 'Благодаря твоим подвигам лорд Фордрагон смог дать приказ о полномасштабном наступлении на Тель\'зана. Седьмой легион пробился в Чертог призыва в усыпальнице и обнаружил нечто похожее на врата в преисподнюю. Теперь дело за тобой.$B$BВозьми филактерию и доложись командиру легиона Йорику в усыпальнице Стражей Зимы.$B$BТам, у стен крепости, есть туннель, прокопанный воинами Плети, так что ты сможешь быстро добраться до Йорика. Иди же, $N! Принеси нам победу!', 'Отнесите филактерию Тель\'зана командиру легиона Йорику в усыпальницу Стражей Зимы в Драконьем Погосте.', 'Когда будешь готов, я помещу филактерию перед вратами и вызову Тель\'зана.', '<Йорик облегченно вздыхает.>$B$BМы уж боялись, что ты не появишься, $N.', NULL, NULL, 'Филактерия Тель\'зана (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12473, 'Конец и начало', 'У каждой хорошей истории есть свое начало и свое окончание, $N. Хотя твоя история еще далека от завершения, будь я проклят, если она недостойна уже сейчас стать легендой! Неважно, что случится с нами, когда все это закончится, о том, что тебе удалось сделать у Стражей Зимы, будут вспоминать и рассказывать еще долгие годы.$B$BА теперь, $gмой храбрый союзник:моя отважная союзница:, когда будешь $gготов:готова:, я воспользуюсь филактерией, чтобы вытащить Тель\'зана из его укрытия.$B$BЕсли нам будет сопутствовать успех, доложи о победе главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.', 'Сразите Тель\'зана Мраконосца и доложите об этом главнокомандующему Халфорду Змеебою из крепости Стражей Зимы на Драконьем Погосте.', 'Стражи Зимы спасены благодаря тебе, $N. Подумать только: один воин смог в одночасье повернуть судьбу битвы! Это нелегко постичь – и все же мы одержали эту победу! Тебе удалось укрепить веру этих людей и завоевать уважение вышестоящих офицеров.$B$B<Халфорд отдает вам честь.>$B$BЛорд Фордрагон вернулся в Ангратар для подготовки наших сил к разрушению Врат Гнева. Он повелел тебе присоединиться к нему. Лучше тебя нам никого не найти, $N.', NULL, NULL, NULL, 'Тель\'зан Мраконосец сражен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12474, 'За крепость Фордрагона!', 'Теперь, когда военная машина Наксрамаса застопорилась, тебе пришло время помочь нашим воинам в Ангратаре, у Врат Гнева. У подножия горы в северном Драконьем Погосте расположена наша база, крепость Фордрагона. Лорд Фордрагон ждет тебя! Ступай туда, $N!$B$BВыйди из города через северные ворота, ступай на север, потом на северо-запад, и придешь, куда нужно.$B$BДа хранит тебя Свет!', 'Отправляйтесь в крепость Фордрагона в Драконьем Погосте и поговорите с верховным лордом Болваром Фордрагоном.', 'Эта награда дается лишь тем, кто делает все мыслимое и немыслимое на службе Альянсу. Я могу по пальцам пересчитать случаи, когда мне доводилось ее вручать, и никто не заслуживал ее более тебя, $N! Поздравляю!$B$BА теперь давай взглянем на Врата Гнева. Знакомое зрелище, не правда ли? Еще бы. Эти ворота сделаны из того самого странного материала, который ты обнаружил в руднике Стражей Зимы. Ничего, мы еще найдем слабое место этой руды! А пока...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12475, 'Какие тайны они скрывают?', 'После предательства на Забытом взморье принц Артас вместе с Мурадином пустился на поиски Ледяной Скорби. Быть может, пещера, где был найден этот печально знаменитый меч, где-то поблизости? И какие тайны она скрывает? Шар не может дать ответов на эти вопросы, и все же кое- что я могу разглядеть.$B$BК северо-востоку от крепости Стражей Зимы находится застава, выстроенная Алым Натиском. Где-то там хранится карта. Шар подсказывает мне, что эта карта нам бы очень пригодилась.$B$BДобудь ее!', 'Добудьте карту Натиска по просьбе Зелига Иллюзорного из крепости Стражей Зимы в Драконьем Погосте и вернитесь с ней к Зелигу.', 'Пещера? Возможно ли такое? Но других вариантов быть не может!', 'Ну что, удалось тебе найти карту Натиска?', NULL, NULL, 'Карта Натиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12476, 'Возвращение Алого ордена?', 'К северо-востоку от крепости Стражей Зимы находится новый лагерь, возведенный Алым орденом – а точнее, Алым Натиском, как они себя теперь называют. Мы пока не знаем, зачем они явились в Нордскол, но они, несомненно, не менее опасны, чем были прежде. Только вчера Алый Натиск убил двенадцать наших солдат! Пора их проучить, $N.$B$BСтупай в лагерь Алого Натиска и задай им жару!', 'Убейте 20 воинов Алого Натиска в лагере Алого Натиска по приказу командира Линоры Порыв Ветра.', 'Надеюсь, теперь до них дойдет. Есть надежда, что суровый урок заставит их задуматься над тем, что они делают.', NULL, NULL, NULL, 'Убито воинов Алого Натиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12477, 'Путь искупления', 'Знаешь, что такое \"Путь искупления\"? Похоже, это дневник, в котором изложены пророческие откровения Аббендис, верховного генерала Алого Натиска. Там, помимо всяческой чепухи, упомянуты все цели и задачи приверженцев Алого Натиска.$B$BПроберись в лагерь Натиска, к северо-востоку от крепости Стражей Зимы, и добудь у одного из солдат Натиска копию \"Пути искупления\".', 'Принесите копию \"Пути искупления\" главнокомандующему Халфорду Змеевержцу из крепости Стражей Зимы в Драконьем Погосте.', '<Халфорд листает дневник.>$B$BАббендис, похоже, совсем рехнулась. Теперь, значит, с ней Свет лично беседует?$B$BИ тем не менее, несмотря на весь этот бред, эта писанина дает бесценную возможность заглянуть в умы и сердца приверженцев Алого Натиска. Замечательный трофей, $N! Лорд Фордрагон будет тобой очень доволен.', 'Ну что, удалось тебе найти копию дневника?', NULL, NULL, 'Путь искупления', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12478, 'Пещера Ледяной Скорби', 'Они окрестили ее пещерой Ледяной Скорби. Не знаю, к чему она Алому Натиску, но, судя по всему, окрестности пещеры надежно охраняются. И тем не менее, нам нужно действовать!$B$BВозьми этот гадальный шар и ступай на север от города, а потом – на северо-запад, в сторону заставы Алого ордена. Проберись в пещеру и пробейся вглубь, на самое дно. Там пусти в ход шар. Потом вернись и расскажи, что тебе удастся обнаружить.', 'Используйте гадальный шар Зелига на дне пещеры Ледяной Скорби по просьбе Зелига Иллюзорного из крепости Стражей Зимы в Драконьем Погосте. Откройте тайны былого!', 'Мурадин жив? Возможно ли такое? Я тотчас сообщу об этом королю Бронзобороду!$B$BМне нужно воспользоваться шаром. Где-то должна быть какая-то еще информация!', NULL, NULL, NULL, 'Тайны былого раскрыты', 'Гадальный шар Зелига', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12481, 'Оскорбительное поражение', 'Эти врайкулы – хитрые твари. К счастью, у меня еще есть парочка трюков в рукаве.$B$BИх предводитель, Бьорн, отличается очень вспыльчивым нравом. Мы тут разобрали кое-какие слова из их языка и составили фразу, которая, по идее, может считаться оскорбительной. Там говорится что-то про его маму и крупный рогатый скот... честно говоря, мы и сами до конца не поняли. $B$BВот, зачитай ему текст с этой бумажки, а когда он бросится за тобой – приведи его прямо к нам. А мы уж постараемся, чтобы он не выбрался отсюда живым.', 'Зачитайте врайкульское оскорбление Бьорну Халгудссону из Гибльхейма, после чего приведите его прямо к Засаде Лиделла и помогите его убить.', 'Молодец! Этот болван даже не понял, что произошло.', 'Работа наемного убийцы – далеко не такая увлекательная, какой ее изображают в романах.', NULL, NULL, 'Бьорн Халгурдссон оскорблен', 'Бьорн Халгурдссон побежден', 'Врайкульское оскорбление', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12482, 'Атака на Ниффлвар', 'Мы ожидаем прибытия подкрепления из Лагеря Возмездия, чтобы осадить Ниффлвар. Но если мы приступим к зачистке прямо сейчас, это даст нам огромное преимущество перед Альянсом.$B$B', 'Капитан следопытов Арейел просит вас отправиться в Ниффлвар и убить 5 воинов из клана Укротителей драконов, 4 руномантов из клана Укротителей драконов и 4 гончих-охотников из клана Укротителей драконов.', 'Ты молодец, $N. Теперь, когда наши войска прибудут из Лагеря Возмездия, мы с легкостью разделаемся с оставшимися врайкулами.', NULL, NULL, NULL, 'Воин из клана Укротителей драконов убито', 'Руномант из клана Укротителей драконов убито', 'Гончая-охотник из клана Укротителей драконов убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12483, 'Похлебка из снежных грибов', 'Слушай, раз уж ты здесь... может, поможешь старине Пригмону? Есть у меня дружок, который умеет готовить изумительную мясную похлебку – ты, небось, даже и не $gпробовал:пробовала: ничего подобного.$B$BПравда, ему для этого нужны кое-какие ингредиенты, которые можно найти среди руин на юго-западе и в северном лагере. $B$BНе хочешь нам помочь?', 'Пригмон из Гранитных ключей просит вас собрать 5 мерцающих снежных грибов и 5 глаз ледяных змеев из руин Драк\'Зина и 5 сладокорней из Зеб\'Халака.', 'Ох, мамочка, неужели я скоро отведаю похлебки из снежных грибов?', 'Ты достал ингредиенты для старины Пригмона, $N?', NULL, NULL, 'Глаз ледяного змея', 'Мерцающий снежный гриб', 'Сладокорень', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12484, 'Шашлык из Плети', 'Фух.$B$BСердце кровью обливается при виде этих несчастных троллей, но спина моя болит еще сильней.$B$BДружок, помоги старому Пригмону, оттащи один из трупов Маку.$B$BЕсли мы их не сожжем в ближайшее время – придется сражаться с ними снова!', 'Пригмон из Гранитных ключей просит вас отнести мумифицированный труп тролля Маку Фирсену и бросить его в огонь.', 'Какое удовольствие – смотреть, как горят эти мерзавцы... <ик>.$B$BЯ даже написал про это маленький сонет. Хочешь послушать? Жил-был когда-то...', 'Что там у тебя, $R?', NULL, NULL, 'Сожжено мумифицированных трупов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12486, 'Быстро, на заставу Бор\'горока!', 'Чувствуешь?$B$B<Сауранок в замешательстве хватается за сердце. Когда он отнимает руку, за ней тянется алая дымка.>$B$BЧто-то ужасное случилось с моим старым другом, предсказателем Печальным Путником. Я просто почувствовал это. $N, у него была ученица, которую он взял с собой, отправляясь на север. Они собирались помочь властителю построить заставу на краю Низины Шолазар. Ее зовут Рычеклык. Она – говорящая с духами.$B$BМожет быть, она знает, что стряслось. Или, по крайней мере, поможет тебе выяснить это.', 'Поговорите с говорящей с духами Рычеклык на заставе Бор\'горока.', 'Мистик уже знает? Ты говоришь, он почувствовал, что с предсказателем Печальным Путником случилось нечто ужасное?$B$BЭтого-то я и боялась!..', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12487, 'В крепости Завоевателей держи ухо востро!', 'Я получил просьбу о помощи с нашей базы в Седых холмах. Я отправляю тебя к завоевательнице Кренне.$B$B<Верховный палач небрежно помахивает листом пергамента.>$B$BОна пытается обезопасить все природные ресурсы или что-то в этом духе. Ты с ней поосторожнее. Говорят, она агрессивная даже для орка.$B$BОтправляйся по дороге на восток, потом на юго-восток. Перейди мост у Кладовой Драконьего хребта и отправляйся на восток от торговой лавки Вечнозеленого леса.', 'Явитесь к завоевательнице Кренне в крепости Завоевателей в Седых холмах.', 'Ты кто?$B$BБыстро объясни, почему мне не стоит зарубить тебя на месте!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12488, 'Запрос от верховного палача', 'Хорошо, что я перехватил этот запрос от верховного палача Роса раньше, чем он попал к командиру Агмару. О чем Рос только думает?$B$B<Сержант вскрывает письмо, которое он держит в руках.>$B$B$C, иди узнай, чего там хочет верховный палач.$B$BСледуй по дороге на восток, затем иди через Драконьи Пустоши. Найдешь тропинку, ведущую из пустошей на юго-востока. Город Отрекшихся, Ядозлобь, окажется перед тобой на южном склоне горы.', 'Поговорите с верховным палачом Росом в Ядозлоби, что в Драконьем Погосте.', 'Тебя прислали из Молота Агмара? Как раз вовремя!$B$BНет, помощь нужна не мне. Мне просто некого больше отрядить, поэтому пойдешь ты.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12489, 'Добро пожаловать в Низину Шолазар', 'Ну, и откуда же ты тут $gвзялся:взялась:? Ведь не этот же недалекий верховный маг тебя послал, верно? $B$BЗнаешь, $gпарень:красотка:, тебе здорово повезло, что ты $gостался целым и невредимым:осталась целой и невредимой:. Ты почти $gвзорвался:взорвалась:!$B$BЗдешние джунгли – место опасное, особенно когда поблизости шляется народ из Компании.$B$BА теперь не рассиживайся тут! Тебе надо повидаться с боссом... он скажет тебе, что делать. Иди по этой тропе на запад и как раз доберешься до лагеря.$B$BДавай-давай!', 'Идите по тропе на запад, пока не дойдете до лагеря, о котором говорил Монти.', 'Ха! Нечасто встречаешь в джунглях незнакомцев!$B$BТебя прислали эти прислужники друидов, чтобы \"остановить меня и то зло, которое я несу?\" Ну, удачи в этом нелегком деле!$B$B<Хеминг от души смеется и поглаживает свое ружье.>$B$BДа ладно, я ничего такого и не думал! Если хочешь, присоединяйся к нашей охотничьей компании – конечно, после того, как мы разберемся с этими шелудивыми псами из Торговой Компании. Их тут кругом навалом.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12490, 'Месть Вихьи', 'Теперь у нас общий враг, $r! Мой народ истребили эти квалдиры… мой город почти разрушен! Пришло время мести!$B$BЯ помогла тебе – перебей же жестоких чудовищ, оскверняющих Терзающий Бич! Тебя ждет достойная награда, $C.', 'Убейте 6 скадирских моряков, 3 скадирских ткачей туманов и 2 скадирских заклинателей рун по просьбе Вихьи из Святилища Чешуи.', '', NULL, NULL, NULL, 'Скадирский моряк убито', 'Скадирский ткач туманов убито', 'Скадирский заклинатель рун убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12491, 'Худое варево Худовара', 'Даже после смерти Корен Худовар не выпустил из рук маленькую фляжку, прижатую к животу. Должно быть, в ней хранится знаменитое худое варево!', 'Отнесите худое варево Худовара Ипфелькоферу Железному Бочонку в лагерь Хмельного фестиваля возле Стальгорна.', 'Так это и есть варево Корена Худовара? То самое пиво, которое он хотел во что бы то ни стало выставить на Хмельном фестивале? Ну, наши правила не позволяют принять эту заявку, но из уважения к павшему пивовару я, пожалуй, сделаю глоточек...', 'Что за грустное лицо? Что-то случилось?', NULL, NULL, 'Худое варево Худовара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12492, 'Худое варево Худовара', 'Даже после смерти Корен Худовар не выпустил из рук маленькую фляжку, прижатую к животу. Должно быть, в ней хранится знаменитое худое варево!', 'Отнесите худое варево Худовара Слухарю Жмухли в лагерь Хмельного фестиваля возле Оргриммара.', 'Значит, Худовар все-таки сварил свое пиво. Как жаль, что за это он поплатился жизнью...$B$BА, впрочем... Чем не повод выпить?', 'Экая у тебя чумазая физиономия, $N! Ты, наверное, возвращаешься из Глубин Черной горы?', NULL, NULL, 'Худое варево Худовара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12495, 'Аудиенция у королевы драконов', 'Наша атака на Ангратар заставила Плеть поколебаться, но отступать они не торопятся. Они высылают на поле битвы своих ледяных змеев, так что подступиться к самим воротам невозможно. Нужно прекратить нападения ледяных змеев. Но прежде чем осквернить кости древних драконов, нужно испросить дозволения их королевы.$B$BОтправляйся на юго-восток, в храм Драконьего Покоя, и отыщи королеву Алекстразу. Расскажи ей о том, что мы вынуждены сделать, и попроси ее совета.$B$BСтупай, $N!', 'Отыщите Алекстразу Хранительницу Жизни в храме Драконьего Покоя в Драконьем Погосте.', 'Ты просишь моего совета, о смертный. Это я знаю, но знаешь ли ты, с чем тебе предстоит столкнуться?$B$B<Алекстраза указывает на север.>$B$BК северу отсюда простираются вымирающие земли Галакронда – прародителя драконьего племени. Именно из него титаны создали аспектов. Представь же, каково должно быть могущество самого Галакронда! Он один был огромнее всех аспектов, вместе взятых! Попытайся же теперь представить, что делает Плеть в Великом Драконьем Погосте.$B$BПо сравнению с этим ледяные змеи далеко не так страшны...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12496, 'Аудиенция у королевы драконов', 'Хотя я знаю, что ты горишь желанием уничтожить армию Плети, противостоящую нам у Врат Гнева, сначала нам надо разобраться с угрозой, висящей в небе. До того, как мы остановим непрекращающиеся налеты ледяных змеев, мы не сможем двигаться дальше.$B$BНо прежде чем мы вторгнемся в умирающие земли драконов, мы должны получить разрешение на это. Отправляйся же в священные залы драконьего племени: в храм Драконьего Покоя. Там найди королеву Алекстразу.$B$BЕзжай сейчас же, $N! На юго-восток, к Драконьему Покою!', 'Отыщите Алекстразу Хранительницу Жизни в храме Драконьего Покоя в Драконьем Погосте.', 'Ты пришел искать моего совета, смертный. Это я знаю, но знаешь ли ты, с чем столкнулся?$B$B<Алекстраза указывает на север.>$B$BК северу отсюда находятся умирающие пространства Галакронда – предка всех драконов. Именно от Галакронда Титаны произвели Аспекты. Вообрази же силу Галакронда! Даже по величине он больше всех Аспектов, вместе взятых! А теперь попробуй понять, что делает Плеть на великом Драконьем Погосте.$B$BЛедяные змеи, смертный, должны меньше всего тревожить тебя.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12497, 'Галакронд и армия Плети', 'На вершине Пагубного Серпантина на плечах воссозданного повелителя штормовых великанов Тиасси восседает верховный некролорд Плети Антиок. Оттуда он командует легионами нежити, работающими день и ночь над выкапыванием тяжеленных костей Галакронда. Если им удастся поднять Галакронда, все твои усилия пойдут прахом.$B$BВ то время как я не могу вызвать полномасштабную ярость красных драконов, чтобы помочь тебе в этом деле, я дам тебе свое благословение. Иди же и поговори с моей управительницей Торастразой.', 'Поговорите с Торастразой в храме Драконьего Покоя на Драконьем Погосте.', 'Храбрость смертных не перестает поражать меня. Смерть хватает тебя за горло ледяной хваткой, а в ответ ты бросаешь вызов ее притязаниям! За это вас так любят… и так ненавидят.$B$BХотя красные драконы ведут войну с Малигосом, есть кое-что, в чем мы можем помочь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12498, 'На рубиновых крыльях', 'Используй этот маяк, чтобы послать сигнал покорителю из Драконьего Покоя. Заберись к нему на спину и лети на север, к Покою Галакронда. Когда будешь там, прикажи дракону уничтожить мусорщиков Плети, пытающихся извлечь из земли Галакронда. Очистив эту область, лети к Пагубному Серпантину, что над Покоем Галакронда, чтобы уничтожить верховного некролорда Антиока и добыть косу, которую он использует для контроля над змеями.$B$BСделай это и возвращайся к королеве Алекстразе за подобающей $gтакому герою:такой героине: наградой!$B$B$N, опасайся гниющих штормовых великанов, бродящих по этой местности!', 'Уничтожьте 30 мусорщиков Пустошей и добудьте косу Антиока. При выполнении задания возвращайтесь к Алекстразе Хранительнице Жизни в храм Драконьего Покоя.', 'Я знала, что ты вернешься, $N. Ты сослужил службу Драконьему союзу и спас свой народ от неминуемой гибели. Пусть это станет известно всем и записано для потомков!', 'Уничтожь силы Плети у Покоя Галакронда, пока не стало слишком поздно!', NULL, NULL, 'Мусорщик пустошей убито', 'Коса Антиока', 'Рубиновый маяк королевы драконов', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12499, 'Возвращение в Ангратар', 'Теперь, когда Антиок убит, а коса находится в наших руках, нападения ледяных змеев на ваши силы в Ангратаре замедлятся. Змеев, что остались еще на Драконьем Погосте, выследят и уничтожат, а их кости возвратят в землю.$B$BПришло время твоей решающей битвы, $N. Возвращайся в крепость Фордрагона и расскажи обо всем верховному лорду Фордрагону.', 'Поговорите с верховным лордом Болваром Фордрагоном в крепости Фордрагона и расскажите ему о своей победе над силами Плети.', 'Знай же: все, что было тобою совершено, вело к этому моменту. Без твоих усилий с нами было бы покончено. А теперь встань в караул. Я отправляюсь на поле битвы, чтобы покончить со всем этим!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12500, 'Возвращение в Ангратар', 'Теперь, когда Антиок убит, а коса в нашем распоряжении, нападений ледяных змеев на ваши силы в Ангратаре станет меньше. Змеи, оставшиеся на Драконьем Погосте, будут перебиты, а их кости возвращены в землю.$B$BПришла пора решающей битвы, $N. Возвращайся в отряд Кор\'крона и доложи обо всем Саурфангу Младшему.', 'Поговорите с Саурфангом Младшим в отряде Кор\'крона и расскажите ему о своей победе над силами Плети.', 'Отец был прав насчет тебя, $N. Все, что он говорил, так и сбылось. Только последний долг остается неисполненным. Теперь я поведу кор\'кронцев в первых рядах войска! Пора покончить с этой войной. Сегодня настанет конец владычеству Короля-лича!$B$BЗайми же мой пост, $N, и стой на страже.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12501, 'Тролльский дозор', 'Расчехляй оружие, $r. Пора отправляться в дозор!$B$BУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$B$BНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$B$BКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$B$BВсе, выполняй!', 'Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.Заставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, к юго-востоку, застава капитана Гронделя – в Драк\'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб\'Валоке, к северу.', 'Ну что ж, $N, по крайней мере, ты вернулся целым и невредимым. А это чего-то да стоит...', NULL, NULL, NULL, 'Задание капитана Брендона выполнено', 'Задание капитана Руперта выполнено', 'Задание капитана Гронделя выполнено', 'Задание алхимика Финкльштейна выполнено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12502, 'Тролльский дозор: выше знамена!', 'Слушай, $C. Это Серебряный Авангард. Наши солдаты будут сражаться до конца и готовы терпеть многие трудности и лишения.$B$BОднако мы понесли очень большие потери, и уже много месяцев нашим воинам не удается как следует выспаться. Все это подрывает их боевой дух, хотя вслух об этом не говорится.$B$BМожет быть, это не так уж и много, но когда наши солдаты видят свое боевое знамя, реющее над полем сражения, это их воодушевляет. Возьми эти знамена и расставь их на пьедесталах в Драк\'Сотре.', 'По поручению капитана Брендона расставьте знамена Серебряного Авангарда на пьедесталах Драккари в Драк\'Сотре.', 'Спасибо, друг.$B$BЗнамя – это всего лишь символ, но на поле боя этот символ творит чудеса.$B$BТеперь отправляйся к капитану Руперту. Его пост – у стены, на северо-востоке отсюда.', NULL, NULL, NULL, 'Знамя Серебряного Авангарда установлено на юге', 'Знамя Серебряного Авангарда установлено на севере', 'Знамя Серебряного Авангарда установлено на востоке', 'Знамя Серебряного Авангарда');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12503, 'Защита заставы', 'Несмотря на наши значительные успехи в нижней трети Зул\'Драка, нам все равно тяжело сдерживать натиск Плети. Такова жизнь в этом студеном аду.$B$BМоим людям необходима хотя бы какая-то передышка. Если хочешь, можешь им помочь.$B$BТам внизу, во внутреннем дворе, битва в самом разгаре. Иди туда и убей столько приспешников Плети, сколько сможешь, $C.', 'По поручению командира Фальштава убейте 10 приспешников Плети во внутреннем дворе Серебряной заставы.', 'Мы благодарны тебе за помощь. Если бы не ты, мы бы не сумели сдержать натиск нежити.', NULL, NULL, NULL, 'Уничтожено воинов Плети у Серебряной заставы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12504, 'Серебряный Авангард, уходим!', '$gСержант быстро просматривает бумаги с приказами, которые вы ему передали, и хмурится.>$B$BСлушай, $gприятель:красавица:, я бы с радостью взял и ушел из этого мрачного места, но ты посмотри, что тут творится. Все мои люди сражаются.$B$BСлушай, раз уж ты все равно здесь, может, сделаешь мне одолжение – войдешь туда и соберешь всех моих солдат?$B$BСкажи, что сержант дал приказ, чтобы все немедленно собрались здесь. Если кто-то нуждается в помощи, помоги им.', 'Поговорите с 10 солдатами Серебряного Авангарда и скажите им, чтобы они немедленно возвращались к сержанту Метателю Молота к алтарю Шшератуса.', 'Ну, ладно. Мы соберем остальных и вернемся на заставу.$B$BХотя жалко, что нам приходится уходить так скоро. Мы здесь явно еще не закончили, и, если по правде, у меня нехорошее предчувствие, что этот пророк у алтаря – потенциальный источник немалых бед.', 'Этого мало. Надо, чтобы их было больше.', NULL, NULL, 'Солдатам Серебряного Авангарда велено вернуться к сержанту', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12505, 'Новый приказ для сержанта Метателя Молота', '$C, ты здесь, чтобы нам помогать, правильно? У меня новый приказ для нашего войска, которое сейчас дислоцировано у алтаря Драккари к северу отсюда.$B$BЕго невозможно не заметить. Иди все время прямо по этой дороге и придешь, куда нужно. Найти сержанта Метателя Молота тоже труда не составит.', 'По поручению командира Кунца доставьте приказ о передислокации сержанту Метателю Молота к алтарю Шшератуса.', '<Сержарнт-дворф подозрительно косится на бумаги у вас в руках.>$B$BЭто новый приказ для меня, господин?', 'В чем дело?', NULL, NULL, 'Приказ о передислокации (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12506, 'Волнения у алтаря Шшератуса', 'У алтаря бога-змея сейчас неспокойно.$B$BПрисутствие Плети ослабило землю, $r. Что, в свою очередь, ослабило богов дикой природы.$B$BНам известно, что Драккари этим воспользовались, и теперь творят страшные вещи с богами.$B$BМне нужна достоверная информация. Иди на север, к алтарю Шшератуса. Зайди с заднего входа и попытайся проникнуть в главное святилище. Смотри, слушай, запоминай, а потом возвращайся ко мне с донесением.$B$BИ самое главное, постарайся не попадаться на глаза пророку!', 'По поручению мастера проклятий Убунго отправляйтесь на разведку в главный храм у алтаря Шшератуса.', 'Мертв?!$B$B<Мастер проклятий удручен и встревожен.>$B$BОни убили Шшератуса и напились его настойки; и больше всех, небось, выпил этот пророк!$B$BНам надо срочно придумать, как устранить его, пока он не выпил больше!', NULL, NULL, NULL, 'Исследовать локацию', 'Храм у алтаря Шшератуса исследован.', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12507, 'Странная настойка', 'Может быть, этот флакон со странной настойкой и есть ключ к разгадке того, что здесь происходит.$B$BНадо его показать зандаларскому троллю, мастеру проклятий Убунго, на Серебряной заставе.', 'Отнесите странную настойку мастеру проклятий Убунго на Серебряную заставу.', 'Это напиток богов дикой природы, $C!$B$BИ это очень тревожный знак!', 'Что это там у тебя?', NULL, NULL, 'Странная настойка (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12508, 'Зачистка территории', 'Я случайно подслушала, о чем вы говорили с сержантом. Но это не отменяет работы, которую надо доделать здесь.$B$BСможешь помочь нам прикончить хотя бы нескольких из приверженцев Шшератуса?', 'По поручению капрала Маги у алтаря Шшератуса убейте 10 приверженцев Шшератуса – воителей Шшератуса, жрецов Шшератуса или факиров драккари.', 'Спасибо, $C. А то было бы жаль уходить, не разобравшись с тем делом, для которого мы сюда явились.', NULL, NULL, NULL, 'Убито последователей Шшератуса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12509, 'Тролльский дозор: сила духа', 'А вот, наконец, и дозорный!$B$BСразу введу тебя в курс дела, $r. В этой кампании мы потеряли многих доблестных воинов, так что нам спешно пришлось набирать новичков.$B$BПоследняя битва была жестокой, и, как оказалось, многие из новобранцев были просто не готовы сражаться с таким сильным противником. У нас впереди еще много сражений, и мне нужно, чтобы мои солдаты были готовы немедленно выполнить любой приказ.$B$BБольше всего на свете я ненавижу трусость. Может быть, ты сумеешь помочь новобранцам найти в себе мужество воевать дальше.', 'По поручению капитана Руперта из Драк\'Сотры поднимите боевой дух рекрутов Серебряного ордена.', 'Ты замечательно справился, $С. И как раз очень вовремя. Мне пришло донесение, что противник готовит контратаку.$B$BТебе пора идти дальше. Следующий форт – на северо-востоке, рядом с Колизеем. Капитан Грондель будет ждать тебя там.', NULL, NULL, NULL, 'Боевой дух восстановлен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12510, 'Совершенные элементальные флюиды', '$gМастер проклятий пристально изучает графин с настойкой.>$B$BЕсть у меня одна мысль, как нам управиться с пророком Шшератуса. Но сначала нам надо добыть несколько необходимых вещей.$B$BК югу отсюда раскинулись поля Драк\'Сотры. Из-за напряжения, созданного нашествием Плети и смертями богов, стена между мирами ослабла, и элементали проникают сюда.$B$BНам нужны совершенные флюиды их владык. Если мы сложим три элементальных флюида, мы сможем установить связь с миром элементалей и сможем вызвать кого-нибудь из их владык.', 'Добудьте 3 образца совершенных элементальных флюидов для мастера проклятий Убунго с Серебряной заставы.', 'Замечательно. Если добавить их в настойку, флюиды ослабят ее действие, не уничтожив саму ее полностью.$B$BДа, и еще кое-что...', 'Где совершенные элементальные флюиды?', NULL, NULL, 'Совершенные элементальные флюиды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12511, 'У холмов есть не только глаза', 'Пока мы сосредоточены на удержании наших позиций в крепости Стражей Зимы и на том, чтобы разобраться с событиями, разворачивающимися у Врат Гнева, батальоны из самого Западного Края прокладывают себе дорогу сквозь плотные заросли и множество негостеприимных обитателей Седых холмов. И все это – в надежде найти другой путь к Ледяной Короне.$B$BЛейтенант Думонт, находящийся в Приюте Янтарной Сосны, составил список физически крепких жителей, готовых рискнуть жизнью и плотью в этих неизведанных диких местах. Не хочешь ли тоже принять этот вызов?', 'Отметьтесь у лейтенанта Думонта в Приюте Янтарной Сосны в западной части Седых холмов.', 'Чуть не подстрелили тебя, а? Дикари, изверги – эти ордынцы…$B$BРасплата будет ждать их – за все, что они сделали. По крайней мере, $C, на это ты можешь рассчитывать.$B$BА теперь настало время приставить тебя к делу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12512, 'Спасти всех', 'Ну, наконец-то. Я уж думал, что нам никого не пришлют.$B$BСлушай, $r. Нужна помощь. Нам пришлось отступать, Плеть выбила нас из Драк\'Сотры. Никто не знает, откуда они появились...$B$BУ нас сейчас каждый солдат на счету, а лучшие из лучших еще не вернулись из боя.$B$BИди на развалины, где сражение уже закончилось, разыщи наших раненых, перевяжи им раны и приведи сюда ко мне.$B$BПрочеши всю Драк\'Сотру и найди их! Далеко они уйти не могли...', 'Разыщите рыцаря Ламуфа, рыцаря Джонатана и рыцаря Жозефину. Перевяжите их раны бинтами и проводите к доктору Роджерсу в Драк\'Сотру.', 'Ты спас всех? Замечательно!$B$BМожет, задержишься тут ненадолго? Нам нужны такие помощники...', 'Тебе удалось разыскать наших солдат, $N?', NULL, NULL, 'Рыцарь Джонатан спасен', 'Рыцарь Ламуф спасен', 'Рыцарь Жозефина спасена', 'Бинты для рыцарей');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12513, 'Милая шляпка...', 'Тебе нравится моя шляпа? Да, она и впрямь необычная. Настоящий антиквариат... теперь уже никто и не помнит, как шить такие головные уборы.$B$BЭх, когда я был молод и горяч, я обещал отдать ее тому, кто сможет одолеть меня в битве. Многие пытались выиграть эту шляпу... но, как видишь, она все еще на мне. $B$BУвы, времена эти давно в прошлом. Старый я стал; пью да рыбачу, но больше уже не дерусь.', 'Сам того не желая, Дон Карлос сподвиг вас сразиться с ним молодым в Старом Хилсбраде. Принесите ему шляпу Дона Карлоса в доказательство вашей победы. Он будет ждать вас в Танарисе.', 'Это... это же моя шляпа! Так значит... это был ты? Так я и подумал. Мои старые шрамы заныли, как только ты подошел ближе, но... столько лет прошло! А ты совсем не изменился$B$BНу что ж... теперь ты знаешь мою тайну. Однажды я все же был побежден. Вот, возьми эту шляпу в обмен на мою. Ты заслуживаешь носить ее больше, чем я.', 'Ах, когда-то я был непобедим... и горжусь этим. Никому не удалось выиграть у меня это великолепную шляпу.', NULL, NULL, 'Шляпа дона Карлоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12514, 'Грибная добавка', 'Теперь нам нужно придумать, как испортить настойку. Нужна особая добавка, чтобы, когда пророк выпьет смесь, его сила иссякла.$B$BВ Драк\'Агале, что на востоке отсюда, произрастает один грибочек... местные называют его гриб-дурман. Думаю, это именно то, что нам нужно.$B$BПринеси мне побольше этих грибов. Мы подмешаем их в настойку, и у каждого, кто его выпьет, помутится разум.', 'Соберите 10 грибов-дурманов и принесите их мастеру проклятий Убунго на Серебряную заставу.', '<Мастер проклятий одобрительно кивает.>$B$BДавай сюда эти грибы, я смешаю их с напитком и элементальными флюидами.', 'Ты принес грибы?$B$BКстати, будь осторожнее – в том районе водятся василиски.', NULL, NULL, 'Гриб-дурман', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12515, 'Милая шляпка...', 'Тебе нравится моя шляпа? Да, она и впрямь необычная. Настоящий антиквариат... теперь уже никто и не помнит, как шить такие головные уборы.$B$BЭх, когда я был молод и горяч, я обещал отдать ее тому, кто сможет одолеть меня в битве. Многие пытались выиграть эту шляпу... но, как видишь, она все еще на мне. $B$BУвы, времена эти давно в прошлом. Старый я стал; пью да рыбачу, но больше уже не дерусь.', 'Сам того не желая, Дон Карлос сподвиг вас сразиться с ним молодым в Старом Хилсбраде. Принесите ему шляпу Дона Карлоса в доказательство вашей победы. Он будет ждать вас в Танарисе.', 'Это... это же моя шляпа! Но...каким образом?$B$BНу что ж... теперь ты знаешь мою тайну. Однажды я все же был побежден. Вот, возьми эту шляпу в обмен на мою. Ты ее заслужил.', 'Ах, когда-то я был непобедим... и горжусь этим. Никому не удалось выиграть у меня это великолепную шляпу.', NULL, NULL, 'Шляпа дона Карлоса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12516, 'Хорошенького понемножку', 'Вот, я изменил состав напитка. Теперь, когда пророк его выпьет, он не только утратит часть своей силы, но еще и слегка помутится рассудком под воздействием гриба.$B$BВо всяком случае, теоретически.$B$BКак заставить его выпить зелье? Да просто швырни ему фляжку. Он перехватит ее и выпьет с присущей ему самонадеянностью.$B$BУбей его, $C, иначе для Серебряного Авангарда все закончится очень печально и страшно.', 'Убейте одурманенного пророка Шшератуса и возвращайтесь к мастеру проклятий Убунго на Серебряную заставу.', 'Замечательно! Ты спас свой народ и весь остальной Нордскол от его безумия.$B$BК несчастью, этим безумием заражены многие в высших кругах Зул\'Драка.', 'И как все прошло?$B$BПодействовал ли мой настой?$B$BТы отомстил за Шшератуса, лишив жизни его пророка?', NULL, NULL, 'Одурманенный пророк Шшератуса убито', 'Измененный настой', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12517, 'Карты Новолуния: колода Разбойников', 'Теперь, когда вы собрали все карты колоды Разбойников, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$B$BВы чувствуете, что с помощью этой карты можно кого-то призвать.', 'Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Разбойников.', 'Знай же, что карты таро пользуются большой популярностью на Ярмарке Новолуния, так что если тебе удастся собрать еще одну колоду – не стесняйся, обращайся к нам. Среди нас много успешных торговцев, так что без награды ты не останешься.', 'Ты собрал колоду Разбойников! Вот это да!', NULL, NULL, 'Колода Разбойников (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12518, 'Карты Новолуния: колода Магов', 'Теперь, когда вы собрали все карты колоды Магов, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$B$BВы чувствуете, что с помощью этой карты можно кого-то призвать.', 'Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Магов.', 'Знай же, что карты таро пользуются большой популярностью на Ярмарке Новолуния, так что если тебе удастся собрать еще одну колоду – не стесняйся, обращайся к нам. Среди нас много успешных торговцев, так что без награды ты не останешься.', 'Ты собрал колоду Магов! Поздравляю!', NULL, NULL, 'Колода Магов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12519, 'Тролльский дозор: сбор медальонов', 'Посмотри на меня, $r. Я похож на кого-то, у кого есть время строчить донесения?$B$BЯ тут убиваюсь, защищаю наш пост от паршивой Плети, а меня еще пытаются загрузить идиотской бумажной работой!$B$B<Вздыхает.: Хотя что толку роптать? Все равно ведь придется писать донесение начальству, сколько было убито троллей в последнем бою. Начальство требует – надо делать.$B$BНе желаешь помочь? Иди собери все медальоны с убитых троллей, какие сумеешь найти. Сколько их будет, столько мы и запишем.', 'Принесите капитану Гронделю к Колизею в Драк\'Агале 7 медальонов Драккари, снятых с убитых троллей Драккари.', 'Вот и славно!$B$BТы мне очень помог, сэкономил мне кучу времени. Большое спасибо. Я обязательно упомяну о твоей верной службе, когда буду писать донесение.$B$BА теперь отправляйся на запад, к Финкльштейну. Он уже наверняка тебя ждет.', 'Ты принес мне медальоны, $R?', NULL, NULL, 'Медальон Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12520, 'Охота на люторогов: проверка', 'Ничто не остановит старину Хеминга, если он решил поохотиться на самых крупных зверей низины Шолазар. В джунглях к северо-западу от лагеря водятся груборогие лютороги. Если ты, $gпарень:подружка:, отважишься встретиться с люторогом лицом к лицу, это докажет, что ты и вправду можешь участвовать в экспедиции.', 'Убейте 15 груборогих люторогов и вернитесь в лагерь Эрнестуэя к Хемингу Эрнестуэю.', 'Ну-ка, ну-ка, посмотрим... Похоже, тебе все-таки удалось пережить встречу с люторогами. А вот им – нет. Как погляжу, ты в хорошей форме! Но знай: в охоте за люторогами много своих тонкостей, недоступных простым охотникам. Чтобы убить патриарха люторогов, который, по слухам, обитает в этих джунглях, тебе понадобится нечто большее, чем верная рука и зоркий глаз...', NULL, NULL, NULL, 'Груборогий люторог убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12521, 'Куда запропастился Хеминг Эрнестуэй?', 'Когда я услышал, что легендарный Хеминг Эрнестуэй отправляется в плаванье к берегам Низины Шолазар, я предложил помощь в финансировании его экспедиции. Мы мало знаем о Шолазаре – но, говорят, это подлинный рай посреди покрытого льдом континента.$B$BХеминг согласился прислать оттуда образцы экзотических растений, кристаллов и реагентов. Но с тех пор от него ничего не было слышно. Монти Мушкетон должен был доставить экспедиции припасы, но он так и не вернулся. Я готов предоставить тебе ветролет, если ты решишь разобраться в этой таинственной истории...', 'Поговорите с верховным магом Пентарусом, когда соберетесь отправиться в Низину Шолазар. По прибытии поговорите с Монти Мушкетоном в диких мангровых зарослях Низины Шолазар.', 'Ну да, Хеминг здесь. Он в своем лагере: отправляйся на запад к реке, и скоро его увидишь. И заклинаю тебя именем света, друг, пусть он пришлет кого-нибудь, чтобы вытащить меня отсюда!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12522, 'Нужен двигатель – найдем двигатель!', 'Все пропало! Мой ветролет… он уничтожен! Я говорил капитанше, что с этим бесценным грузом нужно быть осторожнее, но разве она стала меня слушать?! О, нет!$B$BКогда корабль выбросило на берег, мой ветролет, \"Дух Гномрегана\", погиб! И теперь мы не сможем отправить домой наши отчеты!$B$BПравда, тут нам могут быть на руку шалости Торговой Компании. Говорят, они сбили еще один летательный аппарат – как раз там, где Монти приземлился в болото: это на восток отсюда. Отправляйся туда и принеси двигатель. Возможно, это наша последняя надежда.', 'Веслекс Вездеключ из лагеря Эрнестуэя просит вас принести ему мотор для ветролета.', 'Сюда… сюда его ставь… Осторожнее! Если этот расколотишь, у нас будут серьезные проблемы! А теперь посмотрим, что я могу сделать…', 'Ну как, удалось раздобыть двигатель? Я только что узнал: верховный маг, который финансировал экспедицию, начинает нервничать…', NULL, NULL, 'Двигатель ветролета', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12523, 'Есть детали? – Тащи сюда!', 'Отлично! Теперь у нас есть двигатель. Но для того, чтобы отремонтировать ветролет, нам нужно множество других деталей. Не беспокойся, я знаю, что делаю.$B$BХороший механик может собрать механизм практически из чего угодно, но лучше бы нам обойтись без этого.$B$BВ любом случае, у этих тупиц из Компании навалом запчастей для их оборудования. У Раскопа Хитрохмыла этих частей полно: это по ту сторону той колонны с желтыми кристаллами на северо-востоке. Принеси сюда несколько штук, договорились?', 'Принесите 7 запчастей Торговой Компании Веслексу Вездеключу в лагерь Эрнестуэя.', 'Думаю, немного работы – и этого вполне хватит. Бедный мой ветролет, он скоро станет больше похож на крошшер Торговой Компании… Бедненький мой, придется подождать, пока мы не доберемся до Даларана – уж там-то я приведу тебя в порядок, как положено…', 'Ну как, детали есть?', NULL, NULL, 'Запчасти Торговой Компании', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12524, 'Проблемы Торговой Компании', 'С тех самых пор, как мы прибыли сюда, Торговая Компания мешает нам укрепить лагерь и изучить окрестности. Обычно Компания нас не беспокоит, но теперь они начали бороться с нашими разведчиками и сбивают летательные аппараты с припасами.$B$BМы не можем потерпеть такой наглости. Экспедиция Хеминга Эрнестуэя прибыла сюда, чтобы охотиться – а это значит, мы будем охотиться! $B$BОтправляйся к Раскопу Хитрохмыла, что с дальней стороны усыпанной кристаллами колонны на северо-востоке. Убей всех работников Компании, которые попадутся тебе на пути!', 'Дебаар из лагеря Эрнестуэя хочет, чтобы вы убили 15 членов Торговой Компании. Вы можете убить бузотеров или землечерпов Компании.', 'Это приостановит деятельность Компании; но я боюсь, что они пришлют сюда новых рабочих. Попробуем закончить все наши дела здесь как можно скорее.', NULL, NULL, NULL, 'Убито членов Торговой компании', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12525, 'Сотри ухмылку с его лица', 'Если мы собираемся прикрыть рудник Хитрохмыла, то нужно поторопиться с этим делом. Но будь $gосторожен:осторожна:! Телохранитель штейгера Хитрохмыла, Мясной Пирог – самый настоящий злобный огр; он не пропустит тебя к хозяину без боя.$B$BЭти двое наверняка устроились так, чтобы наблюдать за всеми действиями Компании у Раскопа Хитрохмыла.$B$BНе забудь: раскоп находится на северо-востоке, возле Колонны Солнечного Благословения. Удачи тебе, $N!', 'Убейте штейгера Хитрохмыла и его телохранителя Мясного Пирога, а затем вернитесь к Дебаар в лагерь Эрнестуэя.', 'Какое счастье знать, что Торговая Компания нас больше не потревожит! Прими мою благодарность и благодарность Эрнестуэя: ведь ни один охотник не поднимет оружия против себе подобного…', NULL, NULL, NULL, 'Штейгер Хитрохмыл убито', 'Мясной Пирог убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12526, 'Охота на люторогов: погоня', 'Что ж, значит, решено. Нам надо найти этого местного мудреца и поговорим с ним. Правда, навряд ли он с готовностью предоставит свои услуги…$B$BМне говорили, он живет неподалеку от Скелета Нозронна – это на юге, на том берегу реки. Разыщи его, представься и спроси, что он потребует за то, чтобы помочь нам разыскать этого патриарха люторогов.', 'Поговорите с Оракулом Су-рамом у Скелета Нозронна. ', 'Что привело тебя к обители Су-рама?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12527, 'Прожорливые твари', 'Мой хозяин, Финкльштейн, сейчас в святилище у Хеб\'Валока, что на северо-западе от дороги к Алтарю Шшератуса. Он готовит сыворотку правды, и для этого ему понадобились кристаллы василиска.$B$BК счастью для нас, на востоке от Драк\'Агала как раз водятся василиски.$B$BНалови зул\'дракских крыс и скорми их этим тварям. После пяти крыс василиски становятся сытыми, мирными и послушными – тогда у них можно спокойно забрать кристаллы.$B$BНе убивай василисков – иначе ты не соберешь ни одного целого кристалла.', 'Принесите 5 кристаллов василиска алхимику Финкльштейну в святилище в Хеб\'Валоке.', 'О, превосходно! Спасибо. Кристаллы, насколько я вижу, в отличном состоянии!$B$BМне что-то подсказывает, что хитрец Ступест подстроил все так, что ты выполнил за него всю работу. Как бы там ни было, я благодарен тебе за помощь!', 'Что это у тебя?$B$BКстати, ты случайно не видел моего никчемного подмастерья, Ступеста?$B$BЯ отправил его с поручением уже достаточно давно, но он до сих пор не вернулся!', NULL, NULL, 'Кристаллы василиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12528, 'Подыграть несложно', 'Моя добыча! Лапы убери! Моя добыча! $B$B<Гекгек грозит вам копьем.>$B$BТы бревно тупое, $r. Теперь ты в долгу у Гекгека! Будешь рабом Бешеного Сердца! Будешь убивать много разных тварей для Бешеного Сердца!$B$BИди к холму Бешеного Сердца на северо-восток и скажи верховному шаману Ракжаку, что ты новый раб.$B$BИди, $r! Не заставляй Гекгека говорить дважды!$B$B<Гекгек угрожающе поднимает копье.:', 'Найдите верховного шамана Ракжака на холме Бешеного Сердца и скажите, что вы – его новый \"раб\".', 'Ты новый раб?$B$BЭто хорошо. Рабов мало. Пригодишься.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12529, 'Раб охотника на обезьян', 'Думаешь, ты такой великий охотник, да? Ты не из племени Бешеного Сердца, ты ничего не смыслишь в охоте. $B$BГорегек – великий охотник на обезьян. Он может убить столько, что когтей не хватит сосчитать. $B$BПойдешь с Горегеком, будешь охотиться на барабанчей на востоке. Ты – $gраб:рабыня:, $r. Горегек говорит, ты делаешь.', 'Убейте 8 покорных барабанчей и 6 лютых барабанчей по просьбе верховного шамана Ракжака, живущего на холме Бешеного Сердца.Если вы потеряете кандалы Горегека, поговорите со старейшиной Харкеком на холме Бешеного Сердца.', 'Горегек покажет глупому $R, как это делается.', 'Ты до сих пор живой? И барабанчи тебя не задрали?$B$BНаверное, сейчас они просто сыты.', NULL, NULL, 'Покорный барабанч убито', 'Лютый барабанч убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12530, 'Вопли барабанчат', 'Слушай, $gраб:рабыня:!$B$BРакжак хочет, чтобы я присмотрел за тобой, пока буду охотиться на барабанчей. Но я сегодня щедр: я позволю и тебе убить нескольких, только не путайся под ногами у Горегека!$B$BРакжак еще не знает: Горегек выследил их большую и злобную мамашу. Мы идем к логову барабанчей: слегка потыкаем в барабанчат, и ты увидишь, она мигом примчится! $B$B<Горегек радостно потирает руки.:', 'Горегек дал вам прут для барабанчат: если потыкать их этим прутом, то на их крики из укрытия появится предводительница стаи барабанчей. Убейте предводительницу стаи и расскажите об этом верховному шаману Ракжаку на холме Бешеного Сердца.Если вы потеряете кандалы Горегека, поговорите со старейшиной Харкеком на холме Бешеного Сердца.', 'Горегек взял тебя охотиться на предводительницу племени барабанчей? Тебе здорово повезло!$B$BЭти плаксивые обезьяны так смешно ревут!$B$B<Ракжак издает громкий вопль и хохочет.:', 'Чего тебе, раб?', NULL, NULL, 'Предводительница стаи барабанчей убито', 'Прут для барабанчат', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12531, 'Подземная угроза', 'Убийца львов, охотник на цыплят и новый раб Бешеного Сердца…$B$BЯ знаю, ты не хочешь оставаться рабом. Я скажу тебе, что делать. Докажи, что ты лучше охотников Бешеного Сердца: тогда Ракжак станет уважать тебя.$B$BПод песками южной реки живет тварь, которая убивает ос, обезьян и даже волчеров. Его зовут Серфекс. Принеси Ракжаку коготь Серфекса, и, может, он освободит тебя.$B$BНадеюсь, Дажик хорошо тебя научит, и ты легко справишься с Серфексом.', 'Разыщите Серфекса под песками южной реки и принесите его коготь верховному шаману Ракжаку на холм Бешеного Сердца.Если вы потеряете кусок мела Дажика, поговорите со Старейшиной Харкеком на холме Бешеного Сердца.', 'Ты убил Серфекса? Уверен, ты просто пошел за каким-то могучим охотником-волчером и подобрал коготь.$B$BТеперь коготь мой.', 'Я тебя сюда не звал, $C. Чего ты хочешь?', NULL, NULL, 'Коготь Серфекса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12532, 'Побег из курятника', 'Глупый Горегек вломился в курятник и выпустил на волю всех куриц!$B$BОни там, за холмом. Верни нам наших куриц!$B$B<Старейшина Харкек отсылает вас прочь:', 'Поймайте 12 сбежавших куриц для старейшины Харкека.Если вы потеряете кусок мела Дажика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.', 'Здорово! Еда – это такой серьезный вопрос... Кстати, я уже успел проголодаться. $B$BПрими мою благодарность, $R.', 'Ты ловишь куриц?', NULL, NULL, 'Пойманная курица', 'Сетка для ловли кур', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12533, 'Ученик охотника на ос', 'Ракжак не глупый. Может, ты хорошо умеешь убивать. Может, народ Бешеного Сердца сделает тебя настоящим охотником.$B$BДажик охотится на огромных ос лучше любого волчера. Иди вместе с Дажиком на юго-восток к Сапфирному улью или к реке на юге. Учись охотиться.', 'Убейте 6 ос Сапфирного Улья и 9 рабочих Сапфирного улья для шамана Ракжака, живущего на холме Бешеного Сердца.Если вы потеряете кусок мела Дажика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.', 'Мы убиваем ос. Много ос!$B$BНо Ракжак думает, их не становится меньше.', NULL, NULL, NULL, 'Оса Сапфирного улья убито', 'Рабочий Сапфирного улья убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12534, 'Матка Сапфирового Улья', 'Барабанчи могут быть опасны, но они стараются держаться подальше от волчеров. А вот осы вовсе не боятся племени Мятежного Сердца... Они иногда даже убивают наших охотников.$B$BЯ знаю, Ракжак хочет, чтобы королева ос умерла, но никто из волчеров не пожелает лезть в ее улей. Иди на юго-восток и убей матку Сапфирного улья. Принесешь ее жало Ракжаку. Бьюсь об заклад, ему это понравится.', 'Принесите жало матки Сапфирного Улья верховному шаману Ракжаку, обитающему на холме Бешеного Сердца.Если вы потеряете кусок мела Дажика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.', 'Ты убил осу-матку! Ты сильнее, чем думал Ракжак.$B$BМожет, теперь осы уйдут. Может, перестанут нападать на охотников Бешеного Сердца.', 'От тебя воняет осами.', NULL, NULL, 'Жало матки сапфирного улья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12535, 'Кристаллы силы', 'Ты хороший охотник, но народ Бешеного Сердца может сделать тебя сильнее. Харкек думает, может, ты $gготов:готова: к чему-то большему.$B$BПрежде, чем Ракжак отправит тебя на важное задание, тебе надо собрать несколько вещей для Ракжака. Вдоль реки на юге можно найти синие кристаллы. Ракжаку нужны синие кристаллы, много кристаллов!$B$BИди и принеси их.', 'Верховный шаман Ракжак с холма Бешеного Сердца хочет, чтобы вы принесли ему 8 кристаллов Небесного Пути.', 'Отлично, $R! Теперь все готово.', 'Все уже готово к долгой дороге. Гекгек только что вернулся с кроколиском.', NULL, NULL, 'Кристалл Небесного Пути', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12536, 'Трудная поездка', 'Зепик – лучший охотник народа Бешеного Сердца. Зепик охотится на длинноязыких… на уродливых тварей, живущих у болот, на тех, кто пытается стащить все, до чего могут добраться.$B$BЗепик отправляется в долгий путь, чтобы найти святилище длинноязыких и разогнать их. Нам здесь больше не нужны длинноязыкие. Пусть убираются прочь!$B$BНа северо-восточном склоне горы прикован кроколиск; он там, рядом с деревом. Иди с Зепиком и делай, что Зепик тебе скажет!', 'Оседлайте пойманного кроколиска и отправляйтесь к убежищу Шепота Тумана; затем обратитесь к Зепику за дальнейшими указаниями.Если вы потеряете охотничий рог Зепика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.', 'Мы на месте! Теперь нужно все делать быстро.$B$BБерегись длинноязыких!', 'Зепик слышал, ты хороший охотник, хотя и не из племени Бешеного Сердца.', NULL, NULL, 'Отправляйтесь к убежищу Шепота Тумана.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12537, 'Молния все-таки бьет в то же место', 'Так вот, эти кристаллические штуки…$B$BДлинноязыкие их используют, чтобы давать силу алтарям дождя. Зепик не знает, как это работает, зато Зепик знает, что если взять не те кристаллы, облака и дождь сойдут с ума!$B$BЗепик пытался пробраться к одному из алтарей, но все пошло не так. Зато если пойти вдвоем, должно получиться!$B$BНадо взять кристаллы, поставить их на большую штуку вроде каменной колонны, а потом разбить их, чтобы выпустить силу. Зепик точно не знает, что тогда случится, поэтому Зепик первым не пойдет.', 'Зепик хочет, чтобы вы разрушили кристаллы Небесного Пути перед алтарем Шепота Тумана.Если вы потеряете охотничий рог Зепика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.', 'Хорошо сработало!$B$BТы видел, как молния шарахнула в Оракула? Вот это здорово!$B$B<Зепик потирает руки и злобно хихикает.>', NULL, NULL, NULL, 'Диверсия в святилище Шепота Тумана', 'Кристаллы Небесного Пути', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12538, 'Шептуны не станут слушать', 'Хуже барабанчей – только осы! Не знаю более надоедливых тварей. Вот длинноязыкие – это да, отличная добыча!$B$BПока мы возимся с алтарями дождя, всегда убиваем десяток-другой длинноязыких-шептунов. После этого у них отшибает хотение лезть в деревню.$B$B<Зепик кивает каким-то своим мыслям.:', 'Зепик хочет, чтобы вы убили 12 горлоков Шепота Тумана.Если вы потеряете охотничий рог Зепика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.', 'Я бью длинноязыких, как кроликов! $B$BМожет, и ты тоже ничего…$B$BДа нет, нет, я пошутил! Рад, что охочусь с тобой.', NULL, NULL, NULL, 'Горлок Шепота Тумана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12539, 'Вместе весело шагать', 'Ладно, тут мы закончили. Пора возвращаться. Правда, на этот раз прокатиться на кроколиске не получится.$B$BЕсли мы отправимся на восток и будем держаться хребта, то дорога приведет нас прямиком к холму Мятежного Сердца.$B$BТолько нужно там быть поосторожнее, чтобы не забрести в поселение длинноязыких. Зепик думает, они нас сейчас не очень-то любят – не знаю только, с чего бы это.', 'Найдите дорогу к холму Бешеного Сердца и поговорите с верховным шаманом Ракжаком.', 'Чего стоишь столбом?..$B$B<Ракжак коротко смеется.>$B$BТы хорошо охотишься. Ты нравишься Ракжаку. Может, когда-нибудь народ Бешеного Сердца и примет тебя…$B$BА может, и нет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12540, 'Исполнение приказа', 'Что ж, $gпарень:подружка:, у Ракжака есть для тебя очень, очень важное дело. Следопыт выследил к северу отсюда у реки раненого длинноязыкого. Иди и поймай его.$B$BНе бери охотника в этот раз, охотник его захочет убивать. А я хочу спрятать его у себя. Я буду тыкать в него, а он будет говорить мне разные вещи.$B$BТеперь иди и притащи мне длинноязыкого.', 'Найдите раненого оракула Гласа Дождя по просьбе верховного шамана Ракжака с холма Бешеного Сердца.', 'Не убивай меня! Не надо! Мы только искали рыбу. Мы не хотим умирать.', NULL, NULL, NULL, 'Раненый оракул Прибежища Гласа Дождя найден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12541, 'Тролльский дозор: в подмастерья к алхимику', 'Ага, ты, должно быть, обещанный нам патрульный. Ты как раз вовремя. Мне срочно нужен помощник.$B$BМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$B$BПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$B$BКогда будешь $gготов:готова:, дай мне знать, $r. И помни: самое главное – точный расчет времени!', 'Помогите алхимику Финкльштейну в Хеб\'Валоке в приготовлении сыворотки правды.Когда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.', 'Превосходно!$B$BСведения, которые мы добудем у этого тролля, безусловно, должны оказаться ценными. Я обязательно упомяну о твоей верной службе, когда буду писать донесение командованию.$B$BСпасибо,$N.', 'Видишь, $N, настоящая алхимия – это не просто умение тупо смешивать ингредиенты...', NULL, NULL, 'Сыворотка правды изготовлена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12542, 'Зов Ордена', '$C! Орден Серебряного Авангарда ищет закаленных солдат, которые готовы забыть о своих разногласиях и объединиться в борьбе против воинства Короля-лича. Хочешь ли ты встать в наши ряды?$B$BЕсли тебя это интересует, отправляйся на север, в Опору Света, и поговори с рыцарем Валусом.$B$BОпора Света находится среди развалин разоренного тролльского города Джинта\'калара, на границе с Зул\'Драком.$B$BПрощай!', 'Явитесь к рыцарю Валусу в Опоре Света в Драконьем Погосте.', 'Буквально в нескольких шагах отсюда лежит империя Драккари.$B$B<Валус указывает на восток.>$B$BНа протяжении тысячелетий Драккари пребывали в изоляции, держась в границах своих городов-храмов и зиккуратов. Тем более удивительно было обнаружить эти развалины. Дальше, за зловещими лестницами, ведущими в Зул\'драк, находится разрушенная крепость Драк\'Тарон. Весь первый ярус Зул\'Драка разрушен...$B$BНет, ну почему Плети непременно было нужно напасть именно теперь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12543, 'Подношение Су-раму', 'Мы не знаем тебя, $gчужестранец:чужестранка:, но мы знаем, что ты что-то ищешь. Мы будем говорить со Скелетом Нозронна, но сперва тебе следует доставить нам подношения. Нам нужны зубы императорской кобры, чтобы завершить ожерелье нашего оракула.$B$BОтправляйся на северо-восток отсюда, к диким мангровым зарослям, разыщи там кобр и принеси самые лучшие зубы. Тогда мы сделаем так, что кости заговорят с тобой.', 'Принесите оракулу Су-раму, живущему возле Скелета Нозронна, 5 целых зубов кобры.', '>Оракул внимательно осматривает змеиные зубы.>$B$BМы довольны! Кости Нозронна будут говорить. $N будет слушать.', 'Мы должны знать, принес ли ты зубы?', NULL, NULL, 'Целый зуб кобры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12544, 'Скелет Нозронна', 'О Скелет Нозронна, внемли оракулу Су-раму! $N идет к тебе, дабы узнать сокровенные тайны!$B$BМы приготовили для тебя благовония. Их нужно возжечь и поместить рядом с головой Нозронна: тогда ты услышишь его голос.$B$B<Вы смущенно сообщаете Су-раму, что даже не задали свой вопрос.>$B$BВерно: мы не знаем твоего вопроса, но великому Нозронну открыто все. Отринь сомнения. Нозронн ответит на вопрос, который ты хранишь в сердце.$B$BИди. Нозронн не будет ждать долго.', 'Используйте фимиам Су-рама возле скелета Нозронна, а затем вернитесь к Хемингу Эрнестуэю в его лагерь и расскажите о том, что узнали.', '<Хеминг слушает ваш рассказ.>$B$BЯ тебе так скажу, парень: ни один дохлый люторог не будет указывать Эрнестуэю Хемингу, где и на кого охотиться! Мы покажем этой груде костей, кто тут главный!', 'Ну, что, удалось посоветоваться с оракулом?', NULL, NULL, 'Обнаружено местонахождение Фаранна', 'Фимиам Су-рама', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12545, 'Очищение Джинта\'калара', 'Мы отбили этот древний храм драккари у целой толпы вторгнувшихся воинов Плети. Не более чем в ста шагах от того места, где мы стоим, расположен разрушенный город Джинта\'калар. Некроманты Плети бегают в исступлении, обращая оставшихся в живых троллей драккари в слуг Короля-лича.$B$BДля Света теперь все они потеряны. Всех их придется уничтожить.$B$B<Валус сурово смотрит на вас.>$B$BВсех до единого.', 'По заданию рыцаря Валуса из Опоры Света на Драконьем Погосте убейте 15 джинта\'каларских воинов Плети.', 'Как видишь, военная машина Плети все давит, а армии Орды и Альянса остаются разделенными, становясь для Плети легкими жертвами. Именно поэтому мы должны хранить единство.$B$B<Валус на минуту погружается в размышления.>$B$BСеребряному Авангарду может быть полезен такой, как ты. Может, тебя заинтересовала бы перспектива присоединиться к нам? Сражаться и умереть на стороне Испепелителя?', 'Сделай так, чтобы Королю-личу некого и нечего было бы воскрешать!', NULL, NULL, 'Убито джинта\'каларских воинов Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12546, 'Отмщение', 'Время настало, $N. В Этимидиане заключена вся разрушительная мощь $Nв, и мне больно выпускать его на свободу в своих владениях.$B$BОднако особого выбора нет. Враги принудили меня к решительным действиям; ярость $Nв принесет очищение этой земле!', 'Отправляйтесь к Застывшей лавине в Низине Шолазар и используйте руну \"Омега\", чтобы привести в действие Этимидиана. Используйте его, чтобы уничтожить 200 прислужников Плети, Битиуса Ваятеля Плоти, Ургрета из Тысячи Могил и Градохлада.Выполнив задание, поговорите с Аватарой Фрейи в Низине Шолазар.', 'Я благодарю тебя за помощь, $N. Мой долг – присматривать за этими землями и за всем живым, что их населяет.$B$BБлагодаря тебе, жизнь будет процветать здесь, несмотря на то, что в соседних землях царствует смерть.$B$BТвои деяния не будут забыты.', 'Те, кто угрожает жизни… с ними покончено?', NULL, NULL, 'Уничтожено приспешников Плети (200)', 'Битиус Ваятель Плоти убито', 'Ургрет из Тысячи Могил убито', 'Градохлад убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12547, 'Руна пробуждения', 'Это колоссальное создание неподвижно, как статуя. На его груди вы замечаете выемку в виде руны, но самой ее нигде нет.$B$BВозможно, пропавшая руна отыщется где-нибудь неподалеку?', 'Найдите руну \"Омега\" на Террасе Создателя и принесите ее к Этимидиану. Задание 78-го ур. из категории Кратер Ун\'Горо.', '<Вы слышите гул и скрежет камня о камень: Этимидиан пробуждается к жизни.>$B$BГде нужна моя помощь?', '<Выемка в виде руны на груди Этимидиана, кажется, излучает некую силу.>', NULL, NULL, 'Руна \"Омега\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12548, 'Этимидиан', 'Время пришло, $N. Впервые за семь веков Связующая спираль заработала. Используй ее, чтобы отправиться на поиски нашей последней надежды.$B$BПокончим с теми, кто хочет, чтобы тень смерти скрыла эти чистые земли. Пора освободить Этимидиана.', 'Войдите в Связующую спираль на южной границе Низины Шолазар и разыщите оружие, известное как Этимидиан.', '<Читая письмена, выгравированные на каменном великане, вы понимаете: это и есть оружие, о котором говорила Фрейя. Это Этимидиан.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12549, 'Охота на терропардов: стать хищником', 'Если тебе уже приходилось охотиться с Хемингом, ты знаешь, что он испытывал свое охотничье искусство на многих больших кошках; однако терропарды Шолазара – это совсем другое дело. Они способны одолеть добычу гораздо больших размеров, чем любое другое кошачье. Тот, кто сможет победить и убить такого хищника, по праву будет зваться настоящим охотником!$B$BЕсли хочешь доказать, что ты $gдостоин:достойна: этого высокого титула, проверь себя: отправляйся охотиться на терропардов. Они обитают в чащах вокруг лагеря, а еще к югу вдоль реки.', 'Убейте 15 терропардов и возвращайтесь в лагерь Эрнестуэя к Баку Кантвеллу.', 'Что ж, ты доказал, что можешь называться искусным охотником. А как насчет искусства следопыта?', NULL, NULL, NULL, 'Терропард убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12550, 'Охота на терропардов: по следу зверя', 'Я слышал, среди местных жителей ходят легенды об огромном терропарде, которого называют Шанго. Не знаю, существует ли этот Шанго или нет – из-за ран я не в силах покинуть лагерь.$B$BЕсли хочешь проверить свои способности следопыта, попробуй узнать правду о Шанго. Дебаар говорит, что она недавно видела какие-то большие следы. Отправляйся на север к озеру Горьких Волн и осмотри его южный берег. Может, тебе они тоже встретятся.', 'Бак Кантвелл из лагеря Эрнестуэя хочет, чтобы вы выявили 3 следа Шанго среди следов терропардов у озера Горьких Волн.', '<Бак выслушивает рассказ о том, что вам удалось обнаружить.>$B$BПохоже, тебе удалось разыскать доказательства существования Шанго. Мне кажется, я знаю, где нам его найти...', NULL, NULL, NULL, 'Обнаружено следов Шанго', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12551, 'Охота на кроколисков: испытание', 'Я тебя предупреждаю: о катастрофе – ни слова! Я уже об этом наслушалась от остальных в экспедиции! Хватит с меня!$B$BЕсли ты хочешь научиться нелегкому искусству охоты, начни с мангровых кроколисков. Они живут вдоль реки на юге и в мангровых зарослях на востоке. Докажи, что ты можешь с ними справиться, и тогда мы с тобой поговорим.', 'Убейте 15 мангровых кроколисков и вернитесь к Дебаар в лагерь Эрнестуэя.', 'Да, $C, это впечатляет. Весьма. Ты уверен, что не состоишь в экспедиции?..$B$BДа нет, пожалуй что, не состоишь. Уж кто-нибудь точно проболтался бы.', NULL, NULL, NULL, 'Мангровый кроколиск убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12552, 'Смерть некромагам!', 'Когда тролли обрушили Колрамас, он рухнул совсем рядом с нами, на юго-востоке. К несчастью, далеко не все выродки Плети, находившиеся внутри, были уничтожены при падении.$B$BСейчас они воскрешают наших людей из мертвых и обращают их против нас!$B$BНадо с этим покончить! Позаботься о том, чтобы их некромаги нашли свою смерть! Надеюсь, мы понимаем друг друга?', 'По поручению сержанта Осколка Луны в Драк\'Сотре убейте 8 некромагов Хат\'ар.', 'Этого недостаточно!$B$B<Голос сержанта дрожит от скорби по павшим товарищам, оскверненным вражеской магией.>$B$BМы должны сделать больше, чтобы почтить память наших товарищей!', NULL, NULL, NULL, 'Некромаг Хат\'ар убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12553, 'Прядильные органы', 'Вот почему мне всегда достается самая тяжелая работа?!$B$BПриспешники Плети построили в Колрамасе сеятели чумы, и они подбираются к нам. Это очень опасно. Я даже не буду тебе говорить, что может случиться, если они направятся в нашу сторону!$B$BУ меня есть идея, как их сбивать, но для ее воплощения мне нужно... в общем, одна небольшая деталь, скажем так, от их собственных творений.$B$BСобиратели Хат\'ар прядут очень прочную паутину, которую мы можем использовать для своих целей. Принеси мне их прядильные органы.', 'Принесите специалисту Зубоколесу в Драк\'Сотру 5 целых прядильных органов.', 'Это именно то, что нужно!$B$BНо для того, чтобы собрать катапульту, мне нужны еще и некоторые детали.', 'Прядильные органы должны быть целыми, без изъянов, и тогда я смогу сделать из них устройство, которое может тебе пригодиться.', NULL, NULL, 'Целый прядильный орган', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12554, 'Малас Осквернитель', '$N, возьми себе в помощь хотя бы одного друга и возвращайся сюда!$B$BТы найдешь главу Колрамаса, Маласа Осквернителя, на руинах разрушенного некрополя.$B$BУбей его и принеси мне его голову!', 'Принесите сержанту Осколку Луны в Драк\'Сотру голову Осквернителя. ', 'Ты – настоящий герой, $N.$B$B<Осколок Луны пинает голову ногой.>$B$BТы заслужил наше безграничное уважение и, разумеется, достойную награду.', 'Жду не дождусь, когда можно будет насадить его голову на копье. Посмотрим, сможет ли он ожить после этого!', NULL, NULL, 'Голова Осквернителя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12555, 'Оплетающие сети', 'Ну вот! Одна катапульта-сетемет готова, так что можешь сбивать этих сеятелей чумы.$B$BПросто целься и стреляй. Сети должны нейтрализовать заклинания, поднимающие их в воздух, так что они просто рухнут на землю, как это случилось с Колрамасом.$B$BЭто даже как-то поэтично... мне нравится!', 'По поручению специалиста Зубоколес из Драк\'Сотры сбейте 5 сеятелей чумы с помощью катапульты-сетемета.', 'Ух ты! Ты – лучший из лучших, $N!$B$BА то меня как-то не радовала перспектива быть обрызганной этой дрянью! Как я понимаю, теперь этим мерзким нерубам будет уже трудновато творить свои пакости!$B$BДумаю, ты не откажешься от небольшого вознаграждения за свою работу?', 'Ты уверен, что сбил достаточно этих тварей? А то как-то, знаешь, не хочется, чтобы нас тут заразили чумой.', NULL, NULL, 'Поймано в сеть и сбито сеятелей чумы', 'Метатель пряжи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12556, 'Охота на люторогов: смертельный удар', 'Теперь, когда мы знаем, где найти Фаранна, осталось только выйти на бой против этого великого люторога. Ответь мне, $N: $gготов:готова: ли ты прикончить его? Конечно, слухи многое преувеличивают; но я уверен, что сила Фаранна действительно огромна.$B$BЕсли решишься сразиться с этим люторогом, отправляйся на север: там, за Колонной Солнечного Благословения, на северо-восточном берегу Неспокойного озера ты найдешь Фаранна. Может быть, он даже до Мерцающей колонны дошел. Принеси мне его рог: это будет доказательством того, что люторог мертв.', 'Принесите рог Фаранна Хемингу Эрнестуэю в его лагерь. ', '<Хеминг внимательно разглядывает рог.>$B$BБесценный трофей – и поразительный зверь!.. Послушай, $N, до меня тут дошли слухи, что на севере для нас есть еще более крупная и опасная добыча. Я вот думаю: может, ты поможешь ее выследить?', 'Надеюсь, Фаранн мертв?', NULL, NULL, 'Рог Фаранна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12557, 'Лабораторная работа', 'Как я понимаю, ты хочешь, чтобы я взял тебя в $gученики:ученицы:.$B$BПохвальное стремление, очень похвальное... $B$BЕсли когда-нибудь я соглашусь, я должен быть уверен, что ты сумеешь сориентироваться в моей лаборатории. У меня тут хранятся различные ингредиенты. И в больших, и в малых количествах.$B$BДавай проверим тебя, $C. Найди грязную болотную личинку, иссохшее крыло нетопыря, янтарный желудь и замерзшую змеиную слизь.$B$BЕсли найдешь, я серьезно подумаю над твоей просьбой.', 'Отыщите в лаборатории Финкльштейна грязную болотную личинку, иссохшее крыло нетопыря, янтарный желудь и замерзшую змеиную слизь.', 'Так, так. Для начала неплохо.$B$BЕсли я стану тебя обучать, и мне вдруг потребуется твоя помощь в приготовлении снадобья по рецептуре, тебе нужно будет мгновенно разыскивать и подносить мне все нужные ингредиенты.$B$BПомни об этом, $C.$B$BА пока – до свидания.', 'Ну что, ты уже ориентируешься в моей лаборатории, $C?', NULL, NULL, 'Грязная болотная личинка найдена', 'Иссохшее крыло нетопыря найдено', 'Янтарный желудь найден', 'Замерзшая змеиная слизь найдена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12558, 'Охота на терропардов: прыжок', 'Шанго ждет, $N. Если ты $gпреуспел:преуспела: в искусстве следопыта, он не узнает, что ты ведешь на него охоту – а это преимущество.$B$BГоворят, что он более силен, свиреп и велик, чем любой другой терропард. Отправляйся на север, к западному берегу озера Горьких Волн; там, подле водопадов, питающих озеро, ты найдешь Шанго и сразишься с ним. Если добьешься успеха, принеси мне его шкуру.', 'Принесите шкуру Шанго Баку Кантвеллу в лагерь Эрнестуэя. ', 'Какая изумительная шкура – и какой породистый зверь! Мне приятно держать в руках доказательство того, что рассказы о Шанго – истинная правда, Козавлатах. Ты действовала безупречно – как истинный охотник.', 'Удалось тебе одолеть Шанго?', NULL, NULL, 'Шкура Шанго', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12559, 'Включение Спирали: Обитель Творцов', 'Итак, время пришло. Пора активировать Связующую Спираль.$B$BПервый переключатель можно отыскать в Обители Творцов в западной части низины. $B$BНо берегись, $N. Титаны использовали Обитель для наблюдения за своими созданиями. Многие из их каменных творений все еще охраняют это место.', 'Аватара Фрейи с водопадов Гласа Дождя хочет, чтобы вы отправились в Обитель Творцов и воспользовались активационным переключателем \"гамма\".', 'Мы уже сделали половину дела, $N. Нужно активировать еще один переключатель, и тогда мы сможем пробудить Этимидиана.', 'Вот ты и снова здесь, маленькое существо… Я уже начала волноваться за тебя.', NULL, NULL, 'Активационный переключатель \"гамма\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12560, 'Охота на кроколисков: план', 'Мангровые кроколиски умеют подолгу таиться в засаде: тут у них есть чему поучиться. Так что давай-ка придумаем для тебя подходящую маскировку. Возьмем травы, растущие по песчаным берегам реки и у озера.$B$BЛучше всего для этой цели подойдет песчаный папоротник. Он растет на песках возле разлома Морского Потока на юге, у озера Горьких Волн и водопада Горьких Волн на севере, а также за мангровыми зарослями на востоке, у озера Слияние рек.', 'Принесите 5 листьев песочного папоротника Дебаар в лагерь Эрнестуэя. ', '<Дебаар забирает у вас листья папоротника и начинает заворачивать вас в них.>$B$BДа, это должно сработать... Стой тихо! Сейчас ты станешь в точности как кустик папоротника.', 'Ну как, принес папоротник?', NULL, NULL, 'Песчаный папоротник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12561, 'Вопрос доверия', 'Такого не должно было случиться. Силы смерти атакуют колыбель жизни!$B$BЕсли ты здесь не для того, чтобы уничтожить прислужников Короля-лича, тогда уходи. Не отвлекай меня от моих обязанностей. Не гневи меня.', 'Завоюйте доверие Фрейи: уничтожьте 6 чумных трупов и 10 острокостных опустошителей в Затерянных землях.', 'Что ж, $R, очень хорошо. Я довольна, ибо знаю теперь, что ты не из прислужников Короля-лича. Возможно, ты все же сможешь нам помочь.', 'Не трать мое время впустую, смертное существо! Нужно защитить творения Титанов!', NULL, NULL, 'Чумной труп убито', 'Острокостный опустошитель убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12562, 'Элементали не для Драккари', 'По данным нашей разведки, как только на полях Драк\'Сотры появились эти элементали воды, шаманы Драккари сразу спустились с верхних ярусов Зул\'Драка, чтобы взять их под контроль.$B$BЭто крайне тревожные известия, $gгосподин:госпожа:. Нельзя допустить, чтобы они получили в свое распоряжение элементалей воды.$B$BКомандир приказал перебить всех водопрядов Драккари. Отправляйтесь на юг, как только будете готовы.', 'По заданию младшего лейтенанта Джакса из Серебряной заставы убейте 10 водопрядов Драккари.', 'Ты сослужил нам хорошую службу!$B$BЯ сообщу командиру о твоих достижениях.', NULL, NULL, NULL, 'Водопряд Драккари убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12563, 'Тролльский дозор', 'Расчехляй оружие, $r. Пора отправляться в дозор!$B$BУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$B$BНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$B$BКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$B$BВсе, выполняй!', 'Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.Заставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, застава капитана Гронделя – в Драк\'Агале, а застава алхимика Финкльштейна – в Хеб\'Валоке.', 'Ну что ж, $N, по крайней мере, ты вернулся целым и невредимым. А это чего-то да стоит...', NULL, NULL, NULL, 'Задание капитана Брендона выполнено', 'Задание капитана Руперта выполнено', 'Задание капитана Гронделя выполнено', 'Задание алхимика Финкльштейна выполнено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12564, 'Тролльский дозор: обезболивающее снадобье', 'Да, мои люди крепки и выносливы, но они все-таки смертные.$B$BРаны и боль выводят их из строя. Такова суровая правда жизни.$B$BНо, к счастью, один из наших алхимиков придумал целебную мазь, которая почти полностью снимает боль.$B$BВ рецепт этой мази входит экстракт из особого мака, который тролли выращивают на полях неподалеку отсюда, на западе. Иди на поля Драк\'Сотры и собери эти маки, чтобы у нас был хороший запас сырья для целебного снадобья.', 'Соберите 5 распустившихся водяных маков на полях Драк\'Сотры для капитана Брендона из Драк\'Сотры.', 'Отличные экземпляры, $N.$B$BБлагодарю тебя от имени всех моих воинов.$B$BТеперь иди на восток, к капитану Руперту. Его пост находится у стены.', 'Ты собрал водяные маки, $N?', NULL, NULL, 'Распустившийся водяной мак', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12565, 'Благословение Зим\'Абвы', 'Мне радостно видеть, с каким рвением ваш Серебряный Авангард разбирается с Плетью, $r. Я хочу вам помочь.$B$BРаньше тролли драккари из этого когда-то великого города регулярно приносили жертвы своим богам, но сейчас они уже не почитают богов так, как прежде.$B$BЕсли сделать богам щедрое подношение, в ответ боги одарят тебя своей милостью.$B$BИзваяние Зим\'Абвы находится прямо на юго-западе. Зим\'Абва с радостью примет в дар от тебя артефакты Драккари – в знак того, что ты защищаешь Зул\'Драк.', 'По поручению мастера проклятий Убунго принесите 10 подношений Драккари к изваянию Зим\'Абвы.', '<Если бы Зим\'Абва мог шевелить губами, они бы сложились в зловещую усмешку.>', '<Зим\'Абва смотрит на север и юг непроницаемым взглядом.>', NULL, NULL, 'Подношения Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12566, 'Помощь Лагерю Заиндевевшего Копыта', 'Я – выносливый гонец Наник из племени таунка. Меня послал сюда вождь лагеря Заиндевевшего Копыта на поиски союзников, которые могли бы присоединиться к нашей войне с врайкулами. Враги осадили нас с запада и юга, но хотя на каждого павшего таунка приходится десять мертвых врайкулов, мы не в силах изгнать захватчиков с наших земель.$B$BАптекарь Силлис пообещал прислать нам на помощь отважных |3-8($C). Не желаешь ли ты протянуть руку моим братьям и сестрам?$B$BСледуй по дороге на северо-запад, пересеки реку, и ты увидишь Лагерь Заиндевевшего Копыта у подножия гор.', 'Поговорите с вождем Прахтотемом в Лагере Заиндевевшего Копыта.', 'Значит, Наник выполнил мое поручение? Но скажи мне, $N, как тебе удалось добраться сюда без его помощи? Никто не знает эти земли лучше самих таунка.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12567, 'Благословение Зим\'Абвы', '', '<Застывший каменный взгляд Зим\'Абвы проникает вам в душу.Зим\'Абва доволен, но хочет, чтобы вы оказали ему еще больше почета и уважения в виде подношений Драккари.И тогда он вас вознаградит.>', '<Вы чувствуете, что Зим\'Абва доволен. И в то же время вы знаете, что Зим\'Абва хочет еще подношений!>', NULL, NULL, NULL, 'Подношения Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12568, 'Тролльский дозор: смертельная усталость', 'Поверь мне, $r. Я знаю...$B$BДаже меня, Отрекшегося, уже начинает подташнивать от запаха горелой плоти. Как бы там ни было, наш святой долг – проследить за тем, чтобы наши собратья не стали приспешниками Плети.$B$BПолей этой жидкостью тела наших павших товарищей, чтобы нам не пришлось встретиться с ними на поле боя уже как с врагами.', 'По поручению капитана Руперта полейте 5 павших пехотинцев Серебряного Авангарда в Драк\'Сотре маслом для сожжения.', 'Спасибо, $N.$B$BЭто не самая славная работа на поле боя, но ее надо делать. Я обязательно упомяну о твоей верной службе, когда буду писать донесение.$B$BКапитан Грондель наверняка уже ждет тебя на северо-востоке, сразу за амфитеатром.', NULL, NULL, NULL, 'Сожжено тел пехотинцев Серебряного Авангарда', 'Масло для сожжения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12569, 'Охота на кроколисков: засада', 'Самый большой кроколиск в долине, прозванный Прогрызателем за умение выбираться из ловушек, любит греться на солнце на отмелях Слияния рек. Это такое большое озеро в центре долины, к востоку от нашего лагеря.$B$BЯ хочу, чтобы ты $gнадел:надела: камуфляж, который я для тебя приготовила, и $gустроил:устроила: засаду на западном берегу Слияния рек. Если тебе удастся прикончить Прогрызателя – в чем я лично сомневаюсь, – принеси мне его челюсть.', 'Принесите челюсть Прогрызателя Дебаар в лагерь Эрнестуэя. ', '<Дебаар выслушивает рассказ о том, что маскировка не помогла.>$B$BЧто значит – наш план не сработал так, как ожидалось?$B$BВ конце концов, тебе удалось прикончить эту тварь – что делает тебе честь. Ты только посмотри, какая здоровенная челюсть! Хеминг может нами гордиться. Этот кроколиск был настоящим чудовищем!', 'Ну что, сработал наш план?', NULL, NULL, 'Челюсть Прогрызателя', 'Маскировка под песчаный папоротник', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12570, 'Счастливое непонимание', 'Прости, прости! Не хотел втянуть тебя в неприятности!$B$B<Раненый Оракул долго смотрит на вас остановившимся взглядом.>$B$BТы меня спасаешь! Мы благодарим тебя. Теперь мы вернемся в деревню. Ты тоже идешь... ты можешь остаться с нами. Волосатые бывают очень злы...$B$BСкажи мне, когда соберешься идти, хорошо?', 'Отведите раненого оракула в Прибежище Гласа Дождя и поговорите с верховным оракулом Су-сэем.', 'Ты помогаешь нам? Тогда мы рады тебе, сухая шкура.', NULL, NULL, NULL, 'Отведите раненого Оракула в Прибежище Гласа Дождя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12571, 'Большая Скверная Змея должна уйти', 'Мы пришли сюда задолго до волосатых, и не покинем это место – место великой святости.$B$BМожет, в твоем сердце живет только добро, но все же мы отправим с тобой Лафу. Мы ни в чем не можем быть уверены, пойми нас.$B$BЭти змеи все время пытаются пожрать наших детенышей. Вы с Лафу должны остановить их, понимаешь? Особенно ту большую змею, что живет у северо-восточного водопада.', 'Верховный оракул Су-сэй из Прибежища Гласа Дождя просит вас убить Ядоклыка и 10 императорских кобр.Если потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.', 'Змей больше нет?$B$BЭто хорошо, $R. Мы благодарим тебя.', NULL, NULL, NULL, 'Императорская кобра убито', 'Ядоклык убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12572, 'Боги любят блестящие штучки', 'Су-сэй говорит, мы идем с тобой. Ты только веди себя хорошо, ладно?$B$BО-о, о-о! Мы знаем! Су-сэй будет рад, если мы принесем больше подношений в святилище! Нам не придется идти далеко, возле деревни всегда можно что-то откопать… Присмотрись, и увидишь блеск в грязи!$B$BИдем! Идем! Подношения в святилище!..', 'Соберите 6 драгоценных блестяшек, которые выкопает Лафу, и принесите их верховному оракулу Су-сэю в прибежище Гласа Дождя.Если потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.', 'Блестящие вещи для Великого камня дождя! Хорошо! Хорошо!$B$BСделаем подношение прямо сейчас. Лафу об этом позаботился, верно? Он очень умный.', 'Приветствую тебя, сухая шкура. Ну как, поладили с Лафу?', NULL, NULL, 'Драгоценные блестяшки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12573, 'Заключение мира', 'У нас отличная мысль. Волосатые были твоими друзьями, может быть, они тебя слушать.$B$BМы хотим вот что: передай предложение мира шаману Векжику. Он там, на юго-западе, где река становится водопадом. Скажи волосатым: войны не хотим. Скажи: хотим дружбу.$B$BТы $gхороший:хорошая:$r. Мы верим, что ты все сделаешь правильно.', 'Верховный оракул Су-сэй из Прибежища Гласа Дождя хочет, чтобы вы пошли к шаману Векжику и предложили ему мир. Вернитесь к Су-сэю с ответом.Если потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.', 'Как это скверно! Почему мы поступаем хорошо, а они – скверно?$B$BОни пытаются что-то делать с большими камнями… может, не знают, что большие камни священны?', 'Волосатые решили играть честно?', NULL, NULL, 'Донесите до шамана Векжика предложение мира.', 'Предложение мира от Гласа Дождя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12574, 'Так скоро?', '$gВерховный оракул Су-сэй некоторое время смотрит на ваш лоб, а потом начинает говорить.>$B$BСу-ган просит помощи. Мы думаем, что их, возможно, снова атаковали волосатые.$B$BМы посылаем на помощь тебя и Джалута... идите вдоль западной реки, пока не доберетесь до убежища Шепота Тумана. Сделайте то, что вам скажет Су-ган... если волосатые будут злы, бейте их по носу: они этого не любят.$B$B<Верховный оракул Су-сэй замолкает и смотрит на ваш лоб до тех пор, пока вы не уходите.:', 'Отправляйтесь в убежище Шепота Тумана и поговорите с Призывателем туманов Су-ганом.Если вы потеряете любимый кристалл Джалута, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.', 'Нам кажется, мы уже видели тебя прежде. Тебе уже доводилось бывать в деревне Гласа Дождя?$B$BСу-сэй говорит, ты служишь добру. Су-сэй умный, потому мы тоже доверяем тебе.$B$B<Призыватель туманов Су-ган широко улыбается вам.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12575, 'Потерянное сокровище Шепота Тумана', 'Так вот эти волосатые приходят и разбивают синие кристаллы у великого камня тумана! Много-много дождя, молнии, вреда... Синий – неправильный кристалл для великого камня тумана! Невежественные волосатые…$B$BПосле молнии, волосатые похитили большое сокровище, что мы нашли в море-озере. Нам нужно вернуть сокровище назад, дать его великому камню тумана! Камень тумана сердит после того, что сделали волосатые!$B$BОдин, кто взял сокровище, его зовут Тартер... нет, Тиктак... нет, нет... Тартек! Да, точно – Тартек! Он пошел к этому их лагерю, на север. Верни нам сокровище!', 'Убейте полководца Тартека и добудьте сокровище Шепота Тумана по просьбе призывателя туманов Су-гана.Если вы потеряете любимый кристалл Джалута, поговорите с верховным оракулом Су-сэем в Прибежище Гласа Дождя.', 'Ты смог это сделать! Ты сильный и добрый! Хороший друг нас, из Шепота Тумана!$B$B<Призыватель туманов Су-ган улыбается во все зубы.>', 'Тупые лохматые воришки.', NULL, NULL, 'Полководец Тартек убито', 'Сокровище Шепота Тумана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12576, 'Тяжелая рука', 'С тех самых пор, когда волосатые появились тут, мы пытались быть добры с ними, но они платят нам злом за добро.$B$BМы привыкли к тому, что они глупы – вреда от них не много. Но теперь они вредят нашим святилищам. Это плохо. Святилищам нельзя причинять вред. Великие камни здесь с давних времен; с тех самых пор, когда Великие создали нас.$B$BМы не знаем, что делать, если великому камню Тумана причинят вред. Отправляйся в лагерь волосатых на севере... пусть они остановятся, пусть не возвращаются больше!', 'Убейте 8 копьеносцев племени Бешеного Сердца и 6 падальщиков племени Бешеного Сердца по просьбе Призывателя туманов Су-гана из убежища Шепота Тумана.Если вы потеряете любимый кристалл Джалута, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.', 'Ты хорошо поработал. Благодарю за помощь.', NULL, NULL, NULL, 'Копьеносец племени Бешеного Сердца убито', 'Падальщик племени Бешеного Сердца убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12577, 'Пора домой!', 'Ты $gхороший, сухокожий:хорошая: сухокожая;. Народ Шепота Тумана в безопасности, лохматые больше нас не беспокоят.$B$BИди в прибежище Гласа Дождя и скажи Су-сэю, что ты $gсправился:справилась:.', 'Возвращайтесь в прибежище Гласа Дождя. ', 'Ты уже вернулся?$B$BЗначит, все прошло хорошо?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12578, 'Разгневанный горлок', 'Не думал, что ты появишься вовремя – но, видно, я ошибся. Пошлю Мульда к мохобродам – нужно им врезать за то, что эти глупые не пришли смотреть на святилище. Их деревня на востоке, вверх по хребту, к северо-востоку от разрушенной колонны.$B$BТы иди с Мульдом! Мульд очень умный... ты его слушай.', 'Отправляйтесь в деревню Мохобродов и поговорите с Мульдом.Если вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.', 'Прежде чем скажешь что-нибудь, запомни: я не глуп, как полагает большинство Оракулов. Я повидал мир, выучил ваш язык, и меня нелегко провести.$B$BЯ знал, что мохоброды мертвы, еще до того, как мы пришли сюда, хотя и не знал того, что это – дело нежити.$B$BНежить не должна была проникнуть в эти земли... Должно быть, все дело в разрушении колонны Жизненной Силы. Нужно сделать так, чтобы они снова ушли.', 'Может, Су-сэй немного неловок, но он не глуп. Однако я думаю, что он слишком многое прощает... волосатые не остановятся и не оставят нас в покое. Единственный способ остановить их – это убить. Никакой мир между нами невозможен.$B$B<Мульд тычет себя в грудь.>$B$BВот в этом я хорош!', NULL, NULL, 'Отправляйтесь в деревню Мохобродов.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12579, 'Жизненная Сила для мохобродов', 'Я всегда подозревал, что колонны являются причиной того, какая погода стоит в долине; я также всегда думал, что именно они хранят нас от нежити. И, похоже, получил подтверждение...$B$BНе так давно я услышал взрыв: тогда обрушилась колонна Жизненной Силы. Почти мгновенно изменилась погода: начался снег, которого мы прежде никогда не видели.$B$BК великому камню Мха тогда принесли кристаллы жизненной силы, и снег прекратился. Быть может, если сейчас мы сделаем то же самое, это поможет прогнать нежить.', 'Мульд хочет, чтобы вы собрали 10 осколков Жизненной Силы, но при этом держались подальше от пещеры внутри самой колонны.Если вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.', 'Мы пришли слишком поздно: осколки уже не помогут. Но наши возможности были ограничены…', 'Мохоброды были хорошим народом… они не заслужили этого.', NULL, NULL, 'Осколок самоцвета жизненной силы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12580, 'Спаситель мохобродов', 'Возможно, еще не все мохоброды погибли… они не заслужили того, чтобы их перебили, как животных.$B$BМы отомстим за это подлое убийство – и, может быть, еще успеем кого-нибудь спасти.', 'Мульд хочет, чтобы вы спасли 6 мохобродов-жертв из деревни Мохобродов, хотя некоторые из них, возможно, уже мертвы.Если вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.', 'Я рад, что хотя бы нескольких удалось спасти. Если повезет, они сумеют добраться до прибежища Гласа Дождя.', 'Хотел бы я раньше знать, как важны колонны и камни… быть может, я сумел бы предотвратить это.', NULL, NULL, 'Мохобродов-жертв спасено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12581, 'Бремя героя', 'Может, кристаллы и помогут защититься от нежити, но нужно сделать еще одну вещь.$B$BНужно найти предводителя нежити и прикончить его: тогда некому будет вести на нас их войско. Если мои подозрения справедливы, он прячется где-то внутри упавшей колонны...$B$BПо крайней мере, то, что именно туда тащат мертвые тела, говорит о чем-то подобном.$B$BЯ разложу осколки, как надо, и передам новости Су-сэю... а ты пока что поищи другую помощь.', 'Убейте Артруиса Бессердечного.Мульд не сможет отправиться с вами. Вам потребуется помощь друзей.', '<В талисмане Артруиса вы видите непроглядную бездну... вам кажется, что вы слышите чей-то крик из глубины талисмана.>$B$B<Только под конец вы замечаете предмет, парящий в пустоте как раз в пределах досягаемости.>', '<Талисман Артруиса покоится на земле рядом с его телом.>', NULL, NULL, 'Артруис Бессердечный убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12582, 'Защитник племени Бешеного Сердца', '', '', 'В отличие от остальных, я знаю, что ты не предатель. Мы охотились вместе... Я знаю тебя лучше, чем любой из них. Спасибо за спасение.Может, это прозвучит забавно... Я не особый поклонник длинноязыких... Но даже мне немножко жаль, что длинноязыкие вот так умирают... они хорошо сражаются и заслуживают честной борьбы.Хочешь снова стать другом племени Бешеного Сердца? Думаю, я мог бы убедить их, что ты спас меня и хорошо все сделал с длинноязыкими. Но я не хочу из-за тебя выглядеть дураком. Так ты уверен, что больше не хочешь с ними общаться?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12583, 'Разбившийся сеятель', 'Я знаю, что один из сеятелей чумы разбился где-то в Драк\'Сотре к западу отсюда.$B$BПопытайся его разыскать. Я использую части, оставшиеся от него, для создания устройства, которое будет сбивать сеятели с неба!', 'Соберите детали сеятеля чумы для специалиста Зубоколеса в Драк\'Сотре.', '<Специалист отскакивает на пару шагов, когда вы пытаетесь вручить ей части сеятеля.>$B$BКакая пакость!$B$BЛадно, ладно, давай их сюда. Посмотрим, что из них можно сделать. Наверное, надо было сначала послать тебя с ними к жрецу, чтобы он их очистил.', 'Ты принес то, о чем я тебя попросила?', NULL, NULL, 'Детали сеятеля чумы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12584, 'Зло в чистом виде', 'Мы знаем, что в Колрамасе, некрополе на юго-востоке, был немалый запас руды, известной как саронит.$B$BМои разведчики говорят, что большая часть саронита так и осталась там после того, как некрополь разрушили тролли.$B$BЭйтригг и его товарищи с Серебряной заставы хотят получить образцы руды, чтобы как следует ее изучить.$B$BОтправляйся к павшему некрополю и собери образцы саронита.', 'По указанию капитана Руперта соберите 10 кусков саронита и отнесите их Эйтриггу на Серебряную заставу.', 'Ты разве не чувствуешь? Это не просто руда, это скверна и зло в чистом виде!$B$BНо мы должны изучить ее и узнать ее происхождение, для чего нам потребуется весь наш опыт, вся наша магия и благословение Света.$B$BДай мне саронит. Быстрее!', 'Да, $C?$B$BТы принес саронит от капитана Руперта?', NULL, NULL, 'Кусок саронита', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12585, 'Тролльский дозор: животворящее тепло', 'Да уж, приятного в этом мало, но долг есть долг.$B$BУже несколько дней мои солдаты отважно сражаются, стоя по колено в холодной воде. Они – храбрые воины, но они все-таки не железные.$B$BИм нужно обсохнуть, согреться, воспрянуть духом. А для этого нужен костер.$B$BЭта часть города вся затоплена, но у мертвых корней колючника есть свойство отталкивать влагу, они всегда остаются сухими.$B$BСобери нам дров для костра, и мы будем очень тебе благодарны.', 'Принесите капитану Гронделю в Драк\'Агал 20 кусков древесины высохшего колючника.', 'Спасибо, $N. Большое спасибо.$B$BТеперь иди к капитану Арнату. На запад, прямо за этим холмом.', 'Ты собрал нам дрова для костра, $C?', NULL, NULL, 'Высохший колючник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12586, 'В поисках крупной дичи', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12587, 'Тролльский дозор', 'Расчехляй оружие, $r. Пора отправляться в дозор!$B$BУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$B$BНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$B$BКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$B$BВсе, выполняй!', 'Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.Заставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, к юго-востоку, застава капитана Гронделя – в Драк\'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб\'Валоке, к северу.', 'Ну что ж, $N, по крайней мере, ты вернулся целым и невредимым. А это чего-то да стоит...', NULL, NULL, NULL, 'Задание капитана Брендона выполнено', 'Задание капитана Руперта выполнено', 'Задание капитана Гронделя выполнено', 'Задание алхимика Финкльштейна выполнено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12588, 'Тролльский дозор: будем копать', 'Во время последнего наступления мы нашли древнюю карту сокровищ. Если верить этой карте, то где-то рядом зарыт настоящий клад – бесценные тролльские артефакты.$B$BМоим воинам есть чем заняться, тем более теперь, когда мы зажаты между молотом и наковальней – между Драккари и Плетью. Так что поиском сокровищ придется заняться тебе.$B$BВозьми эту лопату и раскопай кучи земли к юго-западу отсюда. Когда отыщешь сокровища, возвращайся ко мне.', 'По поручению капитана Брана из Драк\'Сотры возьмите стальной заступ, раскопайте курганы древних троллей неподалеку и отыщите реликвию Драккари.', 'Спасибо, $N, ты нам очень помог. Я обязательно упомяну о твоей верной службе, когда буду писать донесение.$B$BТеперь иди к капитану Руперту. Его пост – у стены, на востоке отсюда.', NULL, NULL, NULL, 'Курганы древних обследованы', 'Стальной заступ', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12589, 'Ничего опасного', 'Итак, ты думаешь, что умеешь стрелять?$B$BЧто ж, давай проверим твои умения. Начнем с чего-нибудь не слишком крупного и агрессивного. И помни: если не собираешься стрелять, то и не целься!$B$BА теперь, если ты $gготов:готова:, прицелься в яблоко на голове Везучего Вильгельма, и стреляй!', 'Выстрелите из винтовки РЖР в яблоко на голове Везучего Вильгельма, а потом поговорите с Дростаном.', 'Стреляешь ты неплохо, но тебе нужна практика. Как ты посмотришь на то, чтобы заключить небольшое пари?', 'Ну что, довольна результатом?', NULL, NULL, 'Выстрелом сбито яблоко с головы Везучего Вильгельма', 'Винтовка РЖР', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12591, 'Тролльский дозор: подрывные работы', 'Умно...$B$BМы-то были уверены, что у нас все под контролем, а они сделали подкоп, прошли прямо под нами и захватили святилище!$B$BИ теперь мы оказались зажаты между двумя нерубианскими армиями, и с каждой минутой наше положение становится все отчаяннее и отчаяннее.$B$BНаша первоочередная задача – помешать этим двум армиями соединиться. Надо отрезать их друг от друга и засыпать тоннели.$B$BВозьми эти гранаты и сбрось их в кратеры наших врагов на северо-западе отсюда.', 'По поручению капитана Руперта из Драк\'Сотры взорвите 5 нерубианских кратеров с помощью фугасных гранат.', 'Угроза еще существует, но то, что ты сделал, существенно замедлит продвижение неприятеля.$B$BКапитану Гронделю в Драк\'Агале наверняка требуется твоя помощь.$B$BПрощай, $N.', NULL, NULL, NULL, 'Разрушено нерубских тоннелей', 'Фугасная граната', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12592, 'Вызов великого охотника', 'Итак, у тебя есть охотничий инстинкт. Стреляешь ты тоже неплохо, и Хеминг тебя не выгнал – а это значит, он возьмет тебя на охоту.$B$BА вот как насчет того, чтобы устроить соревнование? Только ты и я.$B$BХеминг и его приятели пригласят тебя на охоту, а мы подсчитаем, кто из нас сколько добудет. Только дело это небыстрое: придется убить много разных зверей... Удачи тебе!', 'Убейте 60 животных, помогая Хемингу и его друзьям на охоте. Когда покончите с этим, возвращайтесь к Дростану в лагерь Эрнестуэя, чтобы сравнить ваши результаты.', 'Ну что, думаешь сдаться?$B$B<Дростан разевает рот от изумления, узнав, что вы уже убили достаточное количество зверей.>$B$BБыть не может! Во имя Азерота, как тебе это удалось? Я только-только прикончил пятьдесят восьмого... И ведь такой небольшой разрыв!..$B$BНо это честная победа. Я тебя недооценивал, $N.', NULL, NULL, NULL, 'Убито животных', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12593, 'На службе Короля-лича', 'Все, что составляет мою сущность: злость, безжалостность, отмщение – я вкладываю в тебя, достойнейший рыцарь. Я даровал тебе бессмертие, ибо тебе суждено стать вестником новой, темной эры Плети.$B$BУзри же земли, лежащие перед тобой. Видишь ли ты, как Алый орден тщетно пытается разрушить созданное нами? Видишь батальоны Последней Надежды, бросающие вызов войскам Плети в Чумных землях? Все они должны поплатиться за свое упрямство. $B$BТы станешь моим возмездием, и страшен будет удел тех, кто станет у тебя на пути. Иди же и взгляни в лицо своей судьбе, мой рыцарь смерти.', 'Доложите о своем прибытии инструктору Разувию из Сердца Акеруса.', 'Ты слышал зов Короля-лича, рыцарь смерти. Настало время откликнуться на призыв своего господина.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12594, 'Тролльский дозор: зачистка местности', 'Из всех постов мне дали именно этот, самый поганый.$B$BВся местность затоплена грязной вонючей водой, а теперь здесь еще поселились какие-то вонючие болотные духи!$B$BЯ не знаю, что они собой представляют и что им здесь нужно, и, если честно, мне это по барабану. Для меня важно одно – они отравляют мой сектор! Мы здесь воюем, а как можно нормально вести боевые действия, когда все поле боя кишит этими грязными тварями?!$B$BТак что иди, $C, и не возвращайся, пока не убьешь хотя бы полдюжины этих гадов.', 'По поручению капитана Гронделя убейте 7 мшистых буянов в Драк\'Агале.', 'Ты уверен, $R?$B$BЛично мне кажется, что их стало больше, чем было раньше.', NULL, NULL, NULL, 'Убито мшистых буянов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12595, 'В поисках крупной дичи', 'Что ж, $N, тебе удалось подтвердить свое искусство охотника в выслеживании всех видов дичи: люторогов, кошек и кроколисков. Для многих этого хватило бы с лихвой – но не для таких, как я. Истинному охотнику нужны иные испытания. $B$BДориан Гроза Драконов разбил лагерь на севере, за озером Горьких Волн. До него дошли слухи о гигантских доисторических драконах. Ты только представь себе, какая это добыча! А какая слава! Давай-ка, навести Дориана и узнай – может, ему уже повезло.', 'Поговорите с Дорианом Грозой Драконов в его лагере в Низине Шолазар. ', 'А, так, значит, старина Хеминг еще не забыл про меня? Думаю, он захочет поучаствовать в охоте – конечно, после того, как мы сделаем за него всю грязную работу. Ну, беспокоиться нечего: тут полно всяких драконов, так что Хеминг останется доволен!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12596, 'Па\'трулль', 'Добро пожаловать на Серебряную заставу, $gновобранец:барышня:. Я – командир Кунц, но ты можешь называть меня просто \"Ваше превосходительство\".$B$BИ не думай, что тут у тебя будет вольница, и ты сможешь шляться по вверенной мне территории, берясь за любую работу, которая тебе подойдет, и ни перед кем не отчитываться.$B$BОбо всем, что ты делаешь, будешь докладывать лично мне – и готовься беспрекословно выполнять все мои приказы. Понятно?$B$BПерво-наперво ты познакомишься с моими людьми. И с районом, который нам поручили зачистить.$B$BОбойди всех моих капитанов и сделай все, что они тебе скажут. Когда закончишь обход, возвращайся ко мне с докладом.', 'Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.Заставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, к юго-востоку, застава капитана Гронделя – в Драк\'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб\'Валоке, к северу.', 'Ну, вот, не прошло и полгода! А я уж думал, что ты никогда не вернешься, что ты попал в лапы Плети... хотя это была бы небольшая потеря...$B$BЕсли хочешь и дальше служить Авангарду, выкладывайся на 200 процентов!$B$BЗапомни это, $R! Что касается твоих следующих патрулей: награда прямо пропорциональна скорости исполнения. Чем быстрее исполнишь, тем больше получишь.$B$BВсе, свободен.', NULL, NULL, NULL, 'Задание капитана Брендона выполнено', 'Задание капитана Руперта выполнено', 'Задание капитана Гронделя выполнено', 'Задание алхимика Финкльштейна выполнено');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12597, 'Обезболивающее снадобье', 'Да, мои люди крепки и выносливы, но они все-таки смертные.$B$BРаны и боль выводят их из строя. Такова суровая правда жизни.$B$BНо к счастью, один из наших алхимиков придумал целебную мазь, которая почти полностью снимает боль.$B$BВ рецепт этой мази входит экстракт из особого мака, который тролли выращивают на полях неподалеку отсюда, на западе. Иди на поля Драк\'Сотры и собери эти маки, чтобы у нас был хороший запас сырья для целебного снадобья.', 'Соберите 5 распустившихся водяных маков на полях Драк\'Сотры для капитана Брендона из Драк\'Сотры.', 'Отличные экземпляры, $N.$B$BБлагодарю тебя от имени всех моих воинов.$B$BТеперь иди на восток, к капитану Руперту. Его пост находится у стены.', 'Ты собрал водяные маки, $N?', NULL, NULL, 'Распустившийся водяной мак', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12598, 'Подрывные работы', 'Умно...$B$BМы-то были уверены, что у нас все под контролем, а они сделали подкоп, прошли прямо под нами и захватили святилище!$B$BИ теперь мы оказались зажаты между двумя нерубскими армиями, и с каждой минутой наше положение становится все отчаяннее и отчаяннее.$B$BНаша первоочередная задача – помешать этим двум армиям получить подкрепление. Надо засыпать тоннели.$B$BВозьми эти гранаты и сбрось их в кратеры наших врагов на северо-западе отсюда.', 'По заданию капитана Руперта из Драк\'Сотры обрушьте 5 нерубских тоннелей с помощью фугасных гранат.', 'Угроза еще существует, но то, что ты сделал, существенно замедлит продвижение неприятеля.$B$BКапитану Гронделю в Драк\'Агале наверняка требуется твоя помощь.$B$BПрощай, $N.', NULL, NULL, NULL, 'Взорвано нерубских тоннелей', 'Фугасная граната', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12599, 'Животворящее тепло', 'Да уж, приятного в этом мало, но долг есть долг.$B$BУже несколько дней мои солдаты отважно сражаются, стоя по колено в холодной воде. Они – храбрые воины, но они все-таки не железные.$B$BИм нужно обсохнуть, согреться, воспрянуть духом. А для этого нужен костер.$B$BЭта часть города вся затоплена, но у мертвых корней колючника есть свойство отталкивать влагу, они всегда остаются сухими.$B$BСобери нам дров для костра, и мы будем очень тебе благодарны.', 'Принесите капитану Гронделю в Драк\'Агал 20 кусков древесины высохшего колючника.', 'Спасибо, $N. Большое спасибо.$B$BТеперь иди к Финкльштейну. На запад, прямо за этим холмом.', 'Ты собрал нам дрова для костра, $R?', NULL, NULL, 'Высохший колючник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12601, 'В подмастерья к алхимику', 'Ага, ты, должно быть, обещанный нам патрульный. И очень вовремя, приятель – вообще-то, я не ждал, что ко мне пришлют барышню, но все равно... ты пришла очень вовремя. Мне срочно нужен помощник.$B$BМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$B$BПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$B$BКогда будешь $gготов:готова:, дай мне знать, $r. И помни: самое главное – точный расчет времени!', 'Помогите алхимику Финкльштейну в Хеб\'валоке в приготовлении сыворотки правды.Когда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.', '', NULL, NULL, NULL, 'Сыворотка правды изготовлена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12602, 'В подмастерья к алхимику', 'Ага, ты, должно быть, обещанный нам патрульный. <И очень вовремя, приятель:Вообще-то я не ждал> что ко мне пришлют барышню, но все равно... ты пришла очень вовремя;. Мне срочно нужен помощник.$B$BМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$B$BПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$B$BКогда будешь $gготов:готова:, дай мне знать, $r. И помни: самое главное – точный расчет времени!', 'Помогите алхимику Финкльштейну в Хеб\'Валоке в приготовлении сыворотки правды.Когда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.', '', NULL, NULL, NULL, 'Сыворотка правды изготовлена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12603, 'Время точить когти', 'Доисторические драконы обитают в большинстве земель на севере и востоке; даже на таком расстоянии я ощущаю жар их дыхания. Но прежде, чем мы бросим вызов самым могущественным из них, нам следует испытать свои способности на менее опасных противниках.$B$BОднако не следует расслабляться: любой из них способен сожрать человека целиком. После того, как убийство драконов станет для тебя обычным делом, возвращайся сюда: я скажу, каким будет следующий шаг.', 'Убейте 6 доисторических драконов, а затем поговорите с Дорианом Грозой Драконов в форпосте Дориана.', 'В твоих словах я слышу уверенность в себе. Что ж, это очень хорошо, приобретенный опыт поможет тебе в битве с Праматерью драконов.', NULL, NULL, NULL, 'Доисторический дракон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12604, 'Поздравляем!', '', '', 'Ты показал отличное время в этом дозоре, $R. Похоже, ты все-таки можешь быть нам полезным.Как и было обещано, вот тебе вознаграждение за труды.Продолжай в том же духе, $N.Свободен.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12605, 'Подготовка ловушки', 'Не думаю, что мы сумеем привлечь внимание Праматери Сливины, если будем прыгать и размахивать руками как идиоты; но если мы будем умны, то сможем заставить ее выйти на бой. А заодно заготовим немного, м-м, корма для моего небольшого проекта.$B$B<Дориан бросает взгляд на Любопытсона.>$B$BНо пока что об этом не стоит беспокоиться. Найди яйца доисторических драконов к востоку и северо-востоку от нашего лагеря. Яйца нужно разбить, а дракончиков притащить сюда. Как только Праматерь узнает, что мы сделали, ей придется встретиться с нами.', 'Принесите Дориану Грозе Драконов 6 доисторических дракончиков в форпост Дориана.', 'Отличная работа! Думаю, Любопытсон будет вовсе не против этих дракончиков!', 'Ну как, удалось найти хорошую наживку, чтобы привлечь внимание Праматери?', NULL, NULL, 'Доисторический дракончик', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12606, 'В коконах', 'Теперь, когда тоннели засыпаны, нам нужно подумать о том, как спасти наших товарищей, попавших в плен к неприятелю.$B$BЕсли нам повезет, то вполне может статься, что некоторые наши солдаты еще живы и относительно здоровы внутри нерубских коконов.$B$BОсвободи их, $C, пока не поздно!', 'Вскройте нерубские коконы в Драк\'Сотре и вернитесь к капитану Руперту в Драк\'Сотру, освободив 3 взятых в плен пехотинцев.', 'Эти нерубы убили немало наших, $C.$B$BКак бы там ни было, я благодарен тебе за старания.', NULL, NULL, NULL, 'Освобождено пленных пехотинцев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12607, 'Поимка мамонта', 'Дориан решил, что прежде, чем отправиться на бой с Праматерью Сливиной, вам с Хемингом было бы неплохо научиться действовать сообща, оседлав мамонта.$B$BВокруг лагеря полно этих зверюг. Возьми уздечку и набрось ее на твердобивневого мамонта. Выбирай самочек – самцы слишком опасны и терпеть не могут упряжи. Когда найдешь подходящего мамонта, веди его сюда.', 'Приведите Любопытсону в форпост Дориана твердобивневого мамонта. ', 'Прекрасно! Единственное, что нам теперь нужно – добыть для Хеминга стремянку…', NULL, NULL, NULL, 'Твердобивневый мамонт доставлен на место', 'Уздечка для мамонта', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12608, 'Вторжение сектантов', '$gПохоже, слова Аватары Фрейи были правдой. Нежить не могла войти в Низину Шолазар, пока была цела колонна Жизненной Силы: для проникновения в низину нежить использовала живых – служителей Культа Проклятых.>$B$B<Лучше предупредить Аватару Фрейи о том, что в Низине Шолазар находятся живые посланцы Короля-лича.:', 'Поговорите с Аватарой Фрейи у водопадов Гласа Дождя. ', 'Живые служат Королю-личу… по доброй воле?$B$BВсе это время я ошибалась, $R; я не там искала врага. Поторопимся: нужно изгнать сектантов из этой земли!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12609, 'Пополнение запасов', 'Слушай, $C. Я понимаю, что прошу слишком многого...$B$BДостать свежую паучью лимфу очень непросто, даже в этих зараженных краях. Но Финкльштейн говорит, что ему нужно ни много ни мало, а целый чан, причем чем скорее, тем лучше.$B$BМои люди сейчас собирают ему реагенты, и они просто не справятся с новым приказом алхимика вовремя. Им нужна помощь.$B$BКогда будешь в Зул\'Драке, смотри внимательно по сторонам: может, где и увидишь пауков-капканщиков. Принеси мне всю лимфу, которую сумеешь добыть.', 'Соберите 7 унций свежей паучьей лимфы от пауков-капканщиков в Зул\'Драке для капитана Арната из Хеб\'Валока.', 'Замечательные экземпляры, $N. Как раз то, что нужно.$B$BСпасибо за помощь.', 'Ты принес то, за чем я тебя посылал, $C?', NULL, NULL, 'Свежая паучья лимфа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12610, 'Подрезанные крылышки', 'С тех пор как у нас появился Финкльштейн, я только и делаю, что собираю различные ингредиенты для его экспериментов и снадобий.$B$BЯ выполняю приказы, потому что таков долг солдата, но я все-таки воин и ветеран многих битв. Мое место – на передовой, мое дело – сражаться с врагом.$B$BПомоги мне, $r. Собери за меня крылья летучих мышей, чтобы я мог поскорее заняться настоящим делом.', 'Соберите 7 безукоризненных крыльев нетопырей в Зул\'Драке для капитана Арната из Хеб\'Валока.', 'Отлично сработано, $N.$B$BБольшое спасибо за помощь.', 'Ты собрал крылья летучих мышей для Финкльштейна?', NULL, NULL, 'Безукоризненное крыло нетопыря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12611, 'Семикратное воздаяние', 'Посланники Короля-лича сделали глупость, ступив в эти земли, где правит Жизнь. Все зло, которое они совершат, вернется к ним семикратно.$B$BЧудовище, ответственное за порчу, причиненную этой земле, носит имя Талгран Сеятель Гнили: ты сможешь найти его к северу отсюда. Возьми этот оберег и воспользуйся им, чтобы зло обратилось само против себя. Покажи войску Плети, что сила Жизни побеждает все!', 'Аватара Фрейи хочет, чтобы вы победили Талграна Сеятеля Гнили при помощи Оберега Фрейи, отразив его проклятия и обратив их против него.', 'И снова ты прекрасно проявил себя, $N. Возможно, я судила о тебе слишком поспешно.$B$BЯ решила, что ты один из браконьеров, которые недавно появились в моих землях. Но, кажется, ты готов забыть о своем темном прошлом…', 'Готово, $N?', NULL, NULL, 'Талгран Сеятель Гнили убито', 'Оберег Фрейи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12612, 'Разрушенная колонна', 'Здесь титаны создавали самых разнообразных живых существ, и жизнь расцветала, не зная пределов.$B$BПять колонн, усыпанных кристаллами, окружают долину и источают чистую жизненную силу. Войско Плети не могло бы проникнуть сюда; но, к несчастью, одна из колонн была уничтожена.$B$BОтправляйся к колонне Жизненной Силы: возможно, ты сумеешь узнать, что произошло. Никто из нежити не мог приблизиться к ней: ищи живых врагов. Ты отыщешь то, что осталось от колонны, к югу от этого места.', 'Отправляйтесь к колонне Жизненной Силы и попытайтесь понять, как она была разрушена.', '<Тело сильно обожжено. Поблизости вы находите то, что осталось от бочонков с порохом.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12613, 'Включение Спирали: Дозор Творцов', 'Теперь мы не можем остановиться, $r. Первый переключатель сработал, остался еще один.$B$BТитаны создали другой наблюдательный пункт, чтобы следить за своими творениями. Ты найдешь его высоко в горах на востоке.$B$BЗадействуй активационный переключатель \"тета\", и Связующая спираль заработает.', 'Аватара Фрейи хочет, чтобы вы направились к Дозору Творцов на востоке Низины Шолазар и там задействовали активационный переключатель \"тета\".', 'Связующая спираль заработала, $N. Пора!', NULL, NULL, NULL, 'Активационный переключатель \"тета\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12614, 'Материнский гнев', 'Праматерь Сливина наверняка в ярости: сейчас это настоящий вихрь клыков, шипов и когтей. Ты $gпохитил:похитила: ее детенышей, а это ни одной матери не придется по нраву.$B$BТо есть, конечно, яйца – это не совсем детеныши, но, видать, сами драконы придерживаются другого мнения.$B$BОна в ярости и отчаянье: именно такую добычу и любит Хеминг. Думаю, вы с Хемингом, да еще и на этом мамонте, станете для нее достойными противниками.$B$BПраматерь можно найти на северной границе Дикой чащи. Помни: она жаждет мести!', 'Убейте Праматерь Сливину и возвращайтесь к Дориану Грозе Драконов в форпост Дориана.', 'Я приготовил целую речь к твоему возвращению, но старик и сам хочет сказать тебе пару слов.', NULL, NULL, NULL, 'Праматерь Сливина убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12615, 'Благословение Зим\'Торги', 'Мастер проклятий Убунго, наверное, уже рассказывал тебе о подношениях богам Зул\'Драка. Зим\'Абва – не единственный бог, брошенный и забытый племенем драккари.$B$BМы обрели убежище и защиту под покровительством Зим\'Торги, Матери Изобилия. Как и Зим\'Абва, она даст тебе благословение, если ты принесешь ей дары Драккари.', 'По поручению знахаря Кхуфу принесите 10 подношений Драккари к изваянию Зим\'Торги.', '<Мысли Зим\'Торги проникают к вам в голову и сливаются с вашими мыслями. Она чувствует, что вы принесли ей дары, и остается довольной.>$B$B<Она дает вам понять, что подношение принято и вас ждет подобающая награда.:', '<Вы чувствуете, что Мать Изобилия смотрит на вас. Ей любопытно, зачем такой $R как вы, пришел к ней.>', NULL, NULL, 'Подношения Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12616, 'Тайная комната', 'Опытный искатель приключений! То, что нам надо.$B$BСреди членов Кирин-Тора, охраняющих башню Медива, ходят слухи, что в Каражане что-то нечисто. Мол, появилась там некая новая сила, что не имеет отношения ни к Стражу, ни к Легиону. Насколько им удалось выяснить, в этом замешан эльфийский принц по имени Тенрис Мутная Кровь, который без сомнения служит Плети.$B$BИди, друг мой, обыщи его комнату и возвращайся с любой информацией.', 'Посланник Серебряного Рассвета просит вас обыскать комнату Тенриса Мутная Кровь, которая находится в квартале слуг Каражана.', 'Если ты ничего не перепутал, и эти приказы действительно имеют силу, то мы в большой опасности. Остается лишь надеяться, что мы успели вовремя прервать его работу.$B$BСпасибо тебе, $N. Пусть беды обходят тебя стороной в эти темные времена.', 'Что тебе удалось обнаружить?', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12617, 'Уничтожение захватчиков', 'Я – воплощение одного из аспектов Фрейи, дочери $Nв. Я – Хранительница Жизни; меня оставили здесь, чтобы охранять долину от войск Плети.$B$BЯ никогда не думала, что Король-лич найдет живых слуг, готовых выполнить его задание.$B$BЯ могла бы и сама сокрушить этих сектантов, однако только я стою между этой долиной и воинством Плети... Иди же, $N. Стань орудием моего гнева, покарай тех, кто так бесстыдно вторгся в долину!', 'Аватара Фрейи, стоящая у водопадов Гласа Дождя, попросила вас отправиться в лагерь Руки Смерти на северо-западе и убить 8 секретных агентов сектантов.', 'Я чувствую, что ты говоришь правду. Пришедшие были уничтожены… но, боюсь, уже слишком поздно.', NULL, NULL, NULL, 'Секретный агент сектантов убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12618, 'Благословение Зим\'Торги', '', '', '<Мать Изобилия лучится счастьем. Благословение получено.>', NULL, NULL, NULL, 'Подношения Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12619, 'Украшенный рунический меч', 'Единственный и самый важный инструмент рыцаря смерти – это рунический меч. Именно с его помощью ты подчинишь себе магию льда, крови и нечестивости. Рунический меч – это сосуд, вмещающий силы рун рыцаря смерти.$B$BДа, рыцарь, настал твой час обрести собственный клинок. Осмотри оружейные стойки на этом этаже и найди затупившийся в боях меч, после чего отнеси его к ближайшей кузне рун и перекуй в рунический.', 'Обыщите оружейные стойки в Черном оплоте, найдите затупившийся в боях меч и перекуйте его в рунический меч в рунной кузне.Принесите готовый клинок инструктору Разувию в Черный оплот.', 'Отличная работа, $N. Твой первый рунический клинок готов. С его помощью ты будешь сеять хаос и разрушение, его острием прольешь реки крови и заточишь его лезвие о трупы врагов, осмелившихся бросить вызов могуществу Плети.', 'Рунический меч – это продолжение твоей руки. Рыцарь смерти – ничто без своего клинка.', NULL, NULL, 'Рунический меч', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12620, 'Гнев Хранительницы Жизни', 'Мы действовали слишком медленно, $N. Проклятые сектанты добрались до Мерцающей колонны и готовятся уничтожить ее. Я чувствую их присутствие.$B$BУ нас мало времени. Протруби в этот рог на вершине Мерцающей колонны, чтобы направить мою энергию в кристаллы.$B$BМы покажем этим фанатикам, что не стоит связываться с творениями $Nв.', 'Аватара Фрейи у водопадов Гласа Дождя хочет, чтобы вы протрубили в Рог Фрейи на вершине Мерцающей колонны.', 'Впечатляюще. Для смертного существа ты действительно сильный союзник.$B$BНо наших усилий, похоже, было недостаточно. Войско Плети продолжает двигаться вперед.', NULL, NULL, NULL, 'Гнев Хранительницы Жизни', 'Рог Фрейи', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12621, 'Договор Фрейи', 'Мы разобрались с сектантами, однако вторжение Плети так и не удалось остановить. Положение становится отчаянным, $N.$B$BЕсть одно последнее средство. Но прежде чем я открою тебе его, я должна быть уверена, что тебе можно доверять.', 'Выслушайте то, что вам расскажет Аватара Фрейи. ', 'Пути назад нет. Если согласишься помочь мне, это нужно делать без сомнений и колебаний.', 'У нас мало времени. Войско Плети готовит последний удар.', NULL, NULL, 'Договор Фрейи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12622, 'Вожди у Джин\'Алаи', 'Знаешь, чего Ауне думать? $B$BМного троллей Драккари собрались у бассейна Джин\'Алаи, на юго-западе. Нам надо выманивать их вождей, и Ауне уже знает, как.$B$BТы ходишь туда, убиваешь всех троллей. Когда прикончишь много троллей, их вожди выйдут сами.$B$BИ, когда они появятся у своих тотемов, ты отберешь все сокровища у Кутубе\'сы, Гаванила и Чуло Безумного.', 'По поручению охотника за скальпами Ауне из Зим\'торги заберите сокровища у Кутубе\'сы, Гаванила и Чуло Безумного.', 'Вот это по-нашему, $R!$B$BА это что за конфетки? Они нам зачем?$B$BАуне думать, что ты можешь их забирать себе!', 'Жрец, наверное, вернулся к Ауне, потому что $C принес все сокровища.', NULL, NULL, 'Сокровище Кутубе\'сы', 'Сокровище Гаванила', 'Сокровище Чуло Безумного', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12623, 'К знахарю', 'Нам, зандаларам, нужна твоя помощь, $N. Мы должны положить конец тем бесчинствам, которые Драккари творят со своими богами!$B$BНа северо-востоке, на великих ступенях, что ведут на следующий ярус Зул\'Драка, располагается Зим\'Торга – дом еще одного из богов, где пребывает его изваяние, и убежище, которое мы так отчаянно пытаемся защитить.$B$BЯ хочу, чтобы ты $gотправился:отправилась: туда и $gпоговорил:поговорила: со знахарем Кхуфу. И будь $gосторожен:осторожна:. Драккари совершают набеги на эти края беспрестанно.', 'Поговорите со знахарем Кхуфу в Зим\'Торге.', 'Приветствую тебя, $С. Хорошо, что Убунго нашел кого-то, кому можно довериться.$B$BДобро пожаловать в Зим\'Торгу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12624, 'Оно может быть где угодно!', 'Когда я узнал, что мисс Булиан помогает Эрнестуэю с экспедицией, я тут же записался палубным матросом. Понимаешь, я уже много месяцев собираюсь жениться на ней!$B$BУ меня все было распланировано. Я хотел сделать ей предложение как раз в ту ночь, когда случилось кораблекрушение... но теперь обручальное кольцо пропало. Я уже везде искал!$B$BЯ знаю, это кажется невероятным, но мне кажется, оно где-то в Низине. Или его украл кто-нибудь из Торговой Компании, или, может, зверь проглотил; но оно здесь... я уверен!', 'Ищите золотое обручальное кольцо у всех обитателей Низины Шолазар. ', 'Не может быть! Ты действительно нашел кольцо! Вот счастье!$B$BЯ просто не знаю… не знаю, как тебя благодарить!', 'Кольцо, $N… прошу, скажи, что тебе удалось его найти!', NULL, NULL, 'Золотое обручальное кольцо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12625, 'Власть над Акерусом', 'Перед тобой Акерус, великая цитадель смерти! Ничто на земле не может с ней сравниться. Даже могучему Наксрамасу не устоять перед силами Черного оплота.$B$BХотя я чувствую смятение в твоих мыслях, у нас нет ни секунды на промедление. Ты $gдолжен:должна: собраться и взять власть над Акерусом в свои руки, ибо я уже слышу первые звуки боевых горнов.$B$BНа этом этаже со всех сторон есть лестницы, ведущие на верхний этаж, где располагаются наши войска. Найди там главного кузнеца крепости Корвия и потребуй у него отчет о состоянии дел. Таланор ждет нашего доклада.', 'Найдите главного кузнеца крепости Корвия на войсковом этаже Черного оплота.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12627, 'Прорыв в Джин\'Алаи', 'Я пытался поговорить с богами. Однако целители у бассейна Джин\'Алаи проводят ритуалы, которые препятствуют моим попыткам связаться с богами.$B$BНам надо развеять их чары. Это действительно очень важно. Я уверен, что где-то там, на юго-западе, ты найдешь котлы, которые они используют для своей магии.$B$BОпрокинь все котлы, чтобы помешать ритуалам, которые не дают мне говорить с богами.', 'По поручению знахаря Кхуфу из Зим\'Торги опрокиньте Синий котел, Зеленый котел, Фиолетовый котел и Красный котел.', 'Да, я уже чувствую разницу. Спасибо.$B$BПосмотрим, получится ли установить связь с богами теперь.', NULL, NULL, NULL, 'Синий котел опрокинут', 'Зеленый котел опрокинут', 'Фиолетовый котел опрокинут', 'Красный котел опрокинут');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12628, 'Разговор с Хар\'коа', 'Боги говорили с нами, $N. Теперь мы знаем, что тебе нужно сделать.$B$BИди к алтарю Хар\'коа к юго-востоку отсюда и поговори с богиней снежных леопардов', 'Поговорите с Хар\'коа у алтаря Хар\'коа.', 'Слушай внимательно, малютка-$r. У нас мало времени, и дважды я повторять не буду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12629, 'Можно убежать, но нельзя скрыться', 'Когда Плеть видит цель, она не остановится ни перед чем на пути к этой цели.$B$BМы обречены на бессмысленное существование ходячих трупов...$B$B<Стефан кривит губы в жестокой усмешке.>$B$B... если мы не сумеем обратить их стремления против них самих.$B$BЯ все объясню, но позже. Сейчас мне нужно подготовить одно достаточно сложное заклинание, для которого мне понадобятся определенные материальные компоненты.$B$BИди на восток, за Реликварий Агонии. Убей поганищ, собери слюну вурдалаков, которых там встретишь, и принеси мне их останки.', 'По указанию Стефана с Черной заставы отправляйтесь за Реликварий Агонии и соберите 5 клубков прогнивших внутренностей поганища с тлетворных поганищ и 5 сгустков вязкой слюны вурдалака.', '<Стефан смотрит на вонючую слюну.>$B$BДа, можно было найти и получше, но придется довольствоваться тем, что есть.$B$BА теперь мужайся, $C. Сейчас начинается самое интересное...', 'Ты принесла то, о чем я просил, $N?', NULL, NULL, 'Прогнившие внутренности поганища', 'Вязкая слюна вурдалака', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12630, 'Насса надо как следует пнуть', 'Прежде чем ты познакомишься с Нассом, ты $gдолжен:должна: кое-что уяснить.$B$BОн принял токсическую дозу гнили, в результате чего ослеп, оглох и практически утратил чувствительность.$B$BНо все не так плохо. Сейчас у него стойкий иммунитет к этой гадости, и поэтому он идеально подходит для выполнения определенных работ – вроде той, что я собираюсь тебе поручить.$B$BТут поблизости много троллей Плети, и нам хотелось бы изучить, как на них действует гниль. Для этого нам нужны образцы их волос. Возьми с собой Насса и этот сапог. Когда убьешь тролля, пни Насса как следует, и он поймет, что надо выдрать у тролля прядь волос.', 'С помощью Насса соберите образцы волос 10 иссохших троллей для Стефана с Черной заставы.Если вы потеряете Насса, возвращайтесь к Стефану.', 'Знаешь, а ты жутко похож на моего Насса.$B$BМожет быть, все дело в форме носа...', NULL, NULL, NULL, 'Собрано образцов волос', 'Окованный ботинок Стефана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12631, 'Приглашение', 'Вырезанное из кости и вымоченное в крови, это колье покрыто замысловатым узором.$B$BГлядя на этот узор, ты теряешь себя и подчиняешься зову зловещей силы – силы, которая требует, чтобы ты $gнадел:надела: его на себя. Однако ты можешь противиться этой силе, а значит, сумеешь отнести колье на Черную заставу.$B$BЕсли кто-то и сможет найти этому объяснение, то только рыцарь смерти...', 'Отнесите колье нежизни Стефану на Черную заставу.', 'Да, я и вправду знаком с подобными вещицами.$B$B<Стефан смотрит вам в глаза.>$B$BПохоже, $N, что ты... избранная.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12632, 'Первым делом – мои дети', 'Меня покорят последней из всех богов, а это значит, что первым делом мы должны попытаться освободить остальных. Связанная колдовством своих покорителей, я не могу прозревать их судьбу.$B$BЯ попрошу тебя об одолжении. Драккари уже обратили мои чары против меня. Они превратили моих детей в безобразных уродов.$B$BВозьми мой ус. Убей моих измученных детей, и магия моего уса освободит их от кошмара и возродит к жизни.', 'Используйте удивительные свойства уса Хар\'коа для того, чтобы освободить и воскресить ее детей. Когда все будет сделано, вернитесь к Хар\'коа. Она ждет вас у алтаря.', 'Спасибо, $N. Я никогда не забуду, что ты для меня сделал.', 'У меня есть еще дети, которых ты должен освободить от мучений!', NULL, NULL, 'Дети Хар\'коа воскрешены', 'Ус Хар\'коа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12633, 'Зов тьмы', 'Вырезанное из кости и вымоченное в крови, это колье покрыто замысловатым узором.$B$BГлядя на этот узор, вы теряете себя и подчиняетесь зову зловещей силы – силы, которая требует, чтобы вы надели колье. Однако вы можете противиться этой силе, а значит, сумеете донести колье до Черной заставы.$B$BЕсли кто-то и сможет найти объяснение произошедшему, то только рыцарь смерти...', 'Отнесите змеевидное колье Стефану на Черную заставу.', 'Да, я и вправду знаком с подобными вещицами.$B$B<Стефан смотрит вам в глаза.>$B$BПохоже, $N, что ты... избранный.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12634, 'Кому ликер, кому лимонад', 'На этот раз судьба подкинула мне полную тележку лимонов! Когда корабль выбросило на берег, все бочки с моей лучшей выпивкой разбились! У нас осталось всего несколько бутылок рома, а на тридцать участников экспедиции этого не хватит!$B$BНам нужно кое-что приготовить, причем поскорее!$B$BВ диких мангровых зарослях полно деревьев со спелыми фруктами, но мне до них не дотянуться. Посмотри, может, там есть какие-нибудь лианы, которые помогут стряхнуть фрукты с ветвей. Словом, тащи все, что удастся собрать.', 'Принесите Мрачнобуху Громовару в лагерь Эрнестуэя 1 апельсин, 2 грозди бананов и 1 папайю.', 'Что ж, ассортимент шире, чем я ожидал от этого места. А теперь – внимание, вопрос: сможем ли мы перегнать все это во что-нибудь пристойное? Приступим…', 'Удалось тебе собрать хоть немного фруктов с этих проклятых колючих деревьев?', NULL, NULL, 'Апельсин', 'Гроздь бананов', 'Папайя', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12635, 'Реликвии богини', 'Я слышал, ты собираешься к Хар\'коа. Удачи!$B$BМожет быть, соберешь для меня ее реликвии? Мне нужно немного, и тебе не придется идти далеко – всего лишь немного пройти на юго-восток.$B$BЧто скажешь?', 'По поручению То\'кини из Зим\'Торги соберите 10 хар\'коанских реликвий.', 'Отличные экземпляры!$B$BТут мы имеем явные отклонения от корневой символики. Да, интересно...$B$BЖалко, что ледяные тролли так решительно уничтожают свое собственное наследие.$B$BТы знаешь, к примеру, что сами же тролли изгнали племя Драккари – за их тягу к насилию и свирепый нрав?$B$BСобственно, поэтому им и пришлось поселиться в столь суровом и непригодном для жизни климате.', 'Драккари сами себя истребляют, но будет жаль, если будет утеряна и история их империи.', NULL, NULL, 'Хар\'коанская реликвия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12636, 'Око Акеруса', 'Осмотрись – это Акерус, великая цитадель смерти! Ничто на земле не может с ней сравниться. Даже могучий Наксрамас не смог бы устоять против Черного оплота. А над некрополем виднеется тень всевидящего ока Акеруса. С его помощью наш повелитель может узреть то, что находится за гранью досягаемости, на территориях врагов. То, что видит око, видит и Король-лич. Теперь же настал твой час заглянуть в его глубины! Король-лич призывает тебя к себе, $N.$B$BИди же, и да продлятся твои страдания, $gбрат:сестра:...', 'Предстаньте перед Королем-личом в Черном оплоте.', 'Скоро настанет время проливать кровь наших врагов. Но сначала ты должен увидеть то, что собираешься уничтожить. Нельзя безоглядно бросаться в битву, не имея представления о том, с чем тебе предстоит столкнуться. Именно это отличает рыцаря смерти от безмозглого вурдалака.$B$BМой защитник, я дарую тебе возможность заглянуть за пределы досягаемого. Ты воспользуешься оком Акеруса и познаешь тайны наших врагов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12637, 'Счастливое избавление', 'Ты $gпоступил:поступила: мудро, не надев это колье, $r. Или тебе просто повезло.$B$BКак бы там ни было, ты $gполучил:получила: его не случайно. Кто-то выбрал тебя. Кто-то или что-то... $B$BОтдай это колье Датуре Кровавой Розе. Пусть она продемонстрирует, какой страшной судьбы ты так счастливо $gизбежал:избежала:.', 'Отдайте колье нежизни Датуре Кровавой Розе.', 'Теперь ты знаешь, какая судьба тебя ожидала.$B$BКак я уже говорил, это все – не случайность. Изготовление подобного устройства – дело достаточно сложное, а значит, его создавали для какой-то конкретной цели. То есть, именно для тебя.$B$BТак что все очень просто: силы Плети хотят тебя заполучить...', 'Да, $C?', NULL, NULL, 'Назначение колье выяснено', 'Колье нежизни', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12638, 'На волосок от смерти', 'Ты $gпоступил:поступила: мудро, не надев это колье, $r. Или тебе просто повезло.$B$BКак бы там ни было, ты $gполучил:получила: его не случайно. Кто-то выбрал тебя. Кто-то или что-то... $B$BОтдай это колье Кровавой Розе. Пусть она продемонстрирует, какой кошмарной судьбы ты так счастливо $gизбежал:избежала:.', 'По предложению Стефана с Черной заставы отнесите змеевидное колье Датуре Кровавой Розе.', 'Теперь ты знаешь, какая судьба тебе грозила.$B$BКак я уже говорил, это все – не случайность. Изготовление подобного устройства – дело достаточно сложное, а значит, его создавали для какой-то конкретной цели. То есть, именно для тебя.$B$BТак что все очень просто: силы Плети хотят тебя заполучить... Что делать будем?', 'Да, $R?', NULL, NULL, 'Назначение колье выяснено', 'Змеевидное колье', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12639, 'Застывшая земля', 'Мы захватили этих элементалей неподалеку, и теперь у меня много защитников. Но чтобы они смогли выстоять против врагов, им надо придать много сил, на что уходит немало энергии.$B$BУ элементалей застывшей земли в Драк\'Мабве, к северо-западу отсюда, есть то, что мне нужно, чтобы поддерживать нашу защиту. Мне нужна их субстанция.', 'Принесите укротителю стихий Дагоде в Зим\'Торге 7 порций субстанции ледяной земли.', 'Спасибо, $C. Этой субстанции хватит для поддержания моих сил на достаточно долгий срок.', 'Надеюсь, ты принес мне достаточно субстанции. Атаки из района бассейна Джин\'Алаи сделались более яростными после того, что ты там у них натворил.', NULL, NULL, 'Субстанция ледяной земли', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12640, 'Закрытие порталов', 'Дагода отправит тебя на северо-запад, в Драк\'Мабву, собирать всякое разное, нужное для ее защитников.$B$BКогда будешь там, Ауне хочет, чтоб ты $gуничтожил:уничтожила: порталы, сквозь которые вылезают все эти элементали. Меньше всего нам охота, чтоб они атаковали нас!$B$BТолько будь $gосторожен:осторожна:, когда будешь пытаться закрыть порталы: элементали застывшей земли сразу полезут со страшной силой, и их будет много.', 'По поручению охотника за скальпами Ауне из Зим\'торги закройте 7 порталов элементалей.', 'Ауне надеется очень-очень, что Дагода успеть получить всех защитников, сколько ей нужно. Теперь порталы закрыты, и больше она ничего не получит.', NULL, NULL, NULL, 'Закрыто порталов элементалей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12641, 'Смерть подбирается с высоты', 'Око Акеруса возвышается над этой платформой. С его помощью ты вызовешь зонд и рассмотришь в деталях укрепления Алого ордена в Новом Авалоне, и благодаря особым способностям Ока сделать это проще простого.$B$BС помощью функции поглощения информации тебе нужно проанализировать кузню, ратушу, крепость и часовню. Механизмы управления Оком находятся по обе стороны этой платформы. Не теряй времени, $N.$B$BЭта земля будет принадлежать Плети, ибо того желает Король-лич!', 'Король-лич приказал вам заглянуть в Око Акеруса, чтобы осмотреть Крепость Алого ордена, Кузню Нового Авалона, Ратушу Нового Авалона и Часовню Багрового Пламени.Для этого воспользуйтесь механизмом управления Оком Акеруса.', 'Как мы и ожидали, они готовятся в битве. Но я почувствовал там кое-что другое... присутствие старого врага, которого считал уничтоженным много лет назад...$B$BВпрочем, это неважно. Мы обрушим на них всю мощь Плети прежде, чем они успеют опомниться. У них не будет ни единого шанса защитить себя и свои дома.', 'Нашу победу над Алым орденом воспоют в легендах.', NULL, NULL, 'Осмотрена Кузня Нового Авалона', 'Осмотрена Ратуша Нового Авалона', 'Осмотрена Крепость Алого ордена', 'Осмотрена Часовня Багрового Пламени');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12642, 'Дух Рунока', 'Мне что-то подсказывает, что у Рунока совсем мало времени.$B$BЯ доподлинно знаю, что дух бога белых медведей уже отделился от его ослабевшего тела. Тебе придется общаться с духом.$B$BЕго алтарь находится на северо-западе, за Драк\'Мабвой.', 'Поговорите с духом Рунока у алтаря Рунока.', 'Я едва держусь. Тебе надо действовать быстро, иначе все будет потеряно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12643, 'Серебряная отделка', 'Когда Плеть видит цель, она не остановится ни перед чем на пути к этой цели.$B$BМы обречены на бессмысленное существование ходячих трупов...$B$B<Стефан кривит губы в жестокой усмешке.>$B$B... если мы не сумеем обратить их стремления против них самих.$B$BЯ все объясню, но позже. Сейчас мне нужно подготовить одно достаточно сложное заклинание, для которого мне понадобятся определенные материальные компоненты.$B$BИди на восток, в край по ту сторону Реликвария Агонии. Убей вурдалаков и поганищ, которых там встретишь, и принеси мне их останки.', 'По указанию Стефана с Черной заставы отправляйтесь за Реликварий Агонии и соберите 5 клубков прогнивших внутренностей поганища с тлетворных поганищ и 5 сгустков вязкой слюны вурдалака.', '<Стефан перебирает вонючие останки.>$B$BДа, можно было найти и получше, но придется довольствоваться тем, что есть.$B$BА теперь дыши глубже, $C. Сейчас начинается самое интересное...', 'Ты принес то, о чем я просил, $N?', NULL, NULL, 'Прогнившие внутренности поганища', 'Вязкая слюна вурдалака', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12644, 'Выпивка – дело тонкое…', 'Теперь, когда у нас есть сырье, я велю моему помощнику подготовить перегонный куб. Он проследит за процессом, но я хочу, чтобы ты все это $gконтролировал:контролировала:. Ты, может, считаешь, что мы бросаем в куб все разом, и оставляем его без присмотра? Так вот, это не так.$B$BИнгредиенты нужно добавлять в строго определенное время; к тому же, нужно регулировать температуру и давление. На то, чтобы принять решение, есть не более 10 секунд. Когда будешь $gготов:готова: приступить к дистилляции, поговори с \"Поддатым\" Макманусом.', 'Завершите процесс дистилляции и принесите пунш \"Зов джунглей\" Мрачнобуха Громовара в лагерь Эрнестуэя.', '<Мрачнобух встряхивает бочонок.>$B$BТут, конечно, что-то есть, но вот вопрос на миллион золотых: можно ли это пить? Погоди, не уходи: возможно, тебе придется выяснить, хорош ли результат...', 'Ну, что у вас получилось?', NULL, NULL, 'Пунш \"Зов джунглей\" Громовара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12645, 'Дегустация', 'Настал момент истины!$B$B<Мрачнобух хихикает.>$B$BВсегда хотел это сказать. Обычно я новую выпивку выставляю на каком-нибудь банкете, но в джунглях банкета не устроишь.$B$BТак что давай-ка ты отнесешь кое-кому из моих дорогих друзей новый напиток на пробу, а потом расскажешь, что они насчет него думают. Дай-ка подумать... меня совершенно точно интересует мнение Хеминга Эрнестуэя и Гадриуса Гарлоу. Они тут, в лагере. А еще сходи в лагерь у озера, что в центре долины, и предложи немного на пробу Тамаре Шестеркрут.', 'Предложите Хемингу Эрнестуэю, Гадриусу Гарлоу и Тамаре Шестеркрут попробовать пунш \"Зов джунглей\", а затем вернитесь к Мрачнобуху Громовару в лагерь Эрнестуэя.', 'Значит, двое из трех довольны? Неплохо для первой попытки… совсем неплохо! Думаю, мне нужно будет придумать что-нибудь другое для Тамары в качестве извинения.$B$BА теперь – как бы нам назвать этот дивный напиток?', NULL, NULL, NULL, 'Дегустация Хемингом', 'Дегустация Гадриусом', 'Дегустация Тамарой', 'Глоток пунша \"Зов джунглей\"');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12646, 'Пророк мой – враг мой', 'Мой пророк слишком поспешно вобрал в себя всю мою силу – и не выдержал напряжения. Он покончил с собой. Последствия этого поступка хорошо видны у кратера, заполненного водой, к югу отсюда в Драк\'Мабве.$B$BМои бывшие жрецы уже воскресили его, чтобы он смог закончить свою работу. Они снова вливают в него мою силу, и уже очень скоро он должен проснуться.$B$BТебе надо его уничтожить и принести мне настой, пока не поздно.', 'Принесите духу Рунока настой бога белых медведей.', 'У тебя получилось!$B$BНо у меня есть еще одно поручение для тебя.', 'Быстрее, $C, ты принес мне настой?', NULL, NULL, 'Настой бога белых медведей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12647, 'Конец мучениям', 'Мое тело уже невозможно восстановить, $N. Настанет час, и они призовут нового пророка, который закончит то, что начали его предшественники.$B$BЯ отдам тебе всю силу, которая осталась во мне. У мучителя, который находится в храме у алтаря, есть фимиам, способный пробудить мое тело и сделать его уязвимым.$B$BВозьми фимиам и сделай мне одолжение: добей меня и положи конец моим мучениям.$B$BЯ заранее прошу прощения, если буду сопротивляться. Даже во мне воля к жизни сильна и неистребима.', 'Используйте фимиам мучителя, чтобы пробудить тело Рунока. Сила, которой вас наделил дух, поможет вам убить Рунока.Если по каким-то причинам аура амулета будет рассеяна, возвращайтесь к духу Рунока, чтобы возобновить эффект.', 'Ты сделал, что должно, и при этом проявил уважение ко мне.$B$BБлагодарю тебя, $N, и надеюсь, что вам с Хар\'коа удастся помочь остальным.', 'Поторопись, $N. Если мои мучения не прекратятся в ближайшее время, все будет потеряно.', NULL, NULL, 'Рунок убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12648, 'Маскировка', 'Вот... я придумал тебе маскировку, в которой ты будешь $gнеотличим:неотличима: от солдат Плети.$B$BПока она будет держаться, ты сможешь спокойно ходить среди них. Только гнилостные стражи смогут разоблачить созданную мной иллюзию. Так что старайся им не попадаться!$B$BТебе также следует знать, что маскировка достаточно нестабильна и может исчезнуть в любую минуту, так что будь начеку.$B$BДавай ее испытаем. Используй колье, отправляйся в лавку к торговцу из приспешников Плети на востоке отсюда и принеси мне бутылку горькой плазмы.', 'Используйте заколдованное колье, чтобы замаскироваться под воина Плети.Пребывая в личине воина Плети, купите для Стефана с Черной заставы горькую плазму у Гнилехряща.Если вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.', 'И как впечатления от жизни под властью Плети?$B$BПоверь мне на слово, все не совсем так, как о том говорят...', 'Ну что, $N?$B$BТы купил горькую плазму?', NULL, NULL, 'Горькая плазма', 'Заколдованное колье', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12649, 'Переодевание', 'Вот... я придумал тебе маскировку, в которой ты будешь $gнеотличим:неотличима: от солдат Плети.$B$BПока она будет держаться, ты сможешь спокойно ходить среди них. Только гнилостные стражи смогут разоблачить созданную мной иллюзию. Так что старайся им не попадаться!$B$BТебе также следует знать, что маскировка достаточно нестабильна и может исчезнуть в любую минуту, так что будь начеку.$B$BДавай ее испытаем. Используй колье, отправляйся в лавку к торговцу из приспешников Плети на востоке отсюда и принеси мне бутылку горькой плазмы.', 'Используйте Заколдованное колье, чтобы замаскироваться под воина Плети.Пребывая в личине воина Плети, купите горькую плазму у Гнилехряща.Если вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.', 'И как впечатления от жизни под властью Плети?$B$BПоверь мне на слово, там все не так замечательно, как о том говорят...', 'Ну что, $N?$B$BТы купил горькую плазму?', NULL, NULL, 'Горькая плазма', 'Заколдованное колье', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12650, 'Разграбленное святилище', 'Тут неподалеку есть еще один алтарь, откуда нужно спасти важные артефакты.$B$BГоворят, что Драккари у Алтаря Рунока на северо-западе, по ту сторону разоренной тундры Драк\'Мабвы, уже разграбили свое собственное святилище.$B$B$C, мне бы очень хотелось, чтобы ты $gспас:спасла: эти священные артефакты, дабы они не попали в недостойные руки.', 'Принесите летописцу То\'кини в Зим\'Торгу 7 артефактов Рунока.', 'Дай-ка я посмотрю, что ты принес.$B$B<Летописец рассматривает артефакты, которые вы принесли.>$B$BДа, должен сказать, нам крупно повезло, что тебе удалось их спасти, $C.$B$BТак-так, интересно... На этой вещи изображены события времен Раскола. Когда-то Нордскол был крайней северной оконечностью Калимдора.$B$BНо после Раскола эта земля отделилась и стала теперешним Нордсколом.$B$BВот почему Драккари встречаются и здесь, и на южных материках.', 'Драккари невозможно понять умом. Это племя изуверов и дикарей для которых нет ничего святого.', NULL, NULL, 'Артефакт Рунока', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12651, 'Лагерь у озера', 'Когда начались неприятности с Торговой Компанией, я попросил Марвина Шестеркрута и его жену Тамару отправить ветролеты на восток, к Слиянию рек. Я попросил их разбить там небольшой лагерь, чтобы хранить там запасы и наблюдать за окрестностями.$B$BПо моим расчетам, Шестеркруты уже должны быть на месте. Слияние рек находится почти в самом центре долины – там, где встречаются русла рек. Найди на северо-восточном берегу их лагерь: Марвин говорил, что это самое удобное место.', 'Поговорите с Тамарой Шестеркрут в лагере у озера. ', 'Значит, тебя прислал Хеминг? Мы как раз собирались сообщить ему, что благополучно устроились здесь. Прости, если Марвин не уделил тебе должного внимания, он просто слишком погружен в свою работу.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12652, 'Преющие вурдалаки проголодались', 'Подь сюды! Эй, я к тебе обращаюсь!$B$BПора, значит, кормить вурдалаков.$B$BСегодня у них будет пир, чаша мозгов и кишок... ням-ням, вкуснятина.$B$BТут ничего сложного нет: подходишь к вурдалачику, ставишь перед ним чашку. И все, считай, подружились.$B$BХочешь дружить с вурдалаком? Ха-ха-ха!', 'По поручению Гнилехряща из Реликвария Агонии возьмите чашу мозгов и кишок и накормите 10 преющих вурдалаков.', 'Ням-ням!', 'Ну чего? Вурдалаки накормлены?', NULL, NULL, 'Накормлено вурдалаков', 'Чаша мозгов и кишок', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12653, 'Назад к Хар\'коа', 'Тебе пора возвращаться к богине снежных леопардов. Мне что-то подсказывает, что у нее есть для тебя еще одно поручение.$B$BИ передай ей: что бы ни случилось, мы – вечны!', 'Поговорите с Хар\'коа у алтаря Хар\'коа.', '<Богиня-кошка воет от боли.>$B$BМое сердце почернело от горя, ибо я потеряла еще одного друга. Но не страшись, он обязательно вернется, и его дух будет жить вечно.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12654, 'Охотник на полставки', 'Когда Хеминг попросил меня сопровождать Марвина, я надеялась, что не буду все время заниматься ремонтом ветролетов и обустройством лагеря. $B$BЯ хотела убить одного злобного льва по прозвищу Острокол. Говорят, он обосновался к югу от лагеря – в том месте, где дикие мангровые заросли подходят к Колонне Небесного Пути с северной стороны. Если ты сумеешь найти эту тварь, может, принесешь мне его останки? Если слухи не врут, это будет такой трофей, которому и сам Эрнестуэй позавидует!', 'Доставьте останки Острокола Тамаре Шестеркрут в лагерь у озера. ', 'Тебе удалось! Теперь мне только остается сделать трофей. Сохранить его внешний вид будет непросто... чтобы при этом Хеминг не высмеял приложенные мной усилия.', 'Тебе удалось разыскать Острокола?', NULL, NULL, 'Останки Острокола', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12655, 'Благословение Зим\'Рука', 'Есть еще один бог Зул\'Драка, о котором ныне забыли.$B$BИзваяние Зим\'Рука находится прямо на севере. Известный под именем \"Мудрый\", Зим\'Рук славен еще и тем, как ревностно он защищает свои владения. Он создал стражей, которые убивают или калечат любого, кому не хватает ума и хитрости проскользнуть мимо них незамеченным.$B$BПроберись к Зим\'Руку так, чтобы стражи тебя не заметили, одари его подношениями Драккари и получи его благословение.', 'По поручению знахаря Кхуфу принесите 10 подношений Драккари к изваянию Зим\'Рука.', '<Зим\'Рук принимает ваши подношения, хотя знает, что вы собрали их с мертвых тел.>$B$B<Хоть и с неохотой, но все же, он дает вам свое благословение.:', '<Вы чувствуете, что Зим\'Рук вам не доверяет. Он пытается вызвать одного из своих стражей.>', NULL, NULL, 'Подношения Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12656, 'Благословение Зим\'Рука', '', '', '<Зим\'Рук посылает вам мысленный образ, как один из его стражей наступает на вас ногой и расплющивает в лепешку. Вероятно, вам стоит попробовать умилостивить Зим\'Рука и принести ему еще больше даров.>', NULL, NULL, NULL, 'Подношения Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12657, 'Мощь Плети', 'Слушай меня, рыцарь смерти, ибо мои слова развяжут великую войну. Я вынес свой приговор: смерть. Всем. И каждому. Никто более не посмеет бросать вызов Плети, не понеся должного наказания.$B$BТы верно $gпослужил:послужила: мне, выполнив первое поручение, и теперь я ожидаю от тебя не меньшего усердия. Передай мой приказ верховному лорду Могрейну на командный пост Акеруса. Скажи ему, что мы начинаем наступление.$B$BА когда Алый орден падет, мы покончим с Серебряным Рассветом.', 'Король-лич приказал вам передать его распоряжения верховному лорду Дариону Могрейну в Черный оплот.Чтобы попасть в Зал Власти, воспользуйтесь мерцающим телепортом позади Короля-лича.', 'Скоро звук рога войны эхом пронесется по этим землям, и мертвецы восстанут, приветствуя шествие Плети. Горе тем, кто станет у нас на пути!$B$BТы и твои братья, $N, будут стоять во главе нашего войска, и когда в следующий раз я брошу взгляд на земли Алого ордена, то увижу там легионы Акеруса. Наступление на Новый Авалон начинается!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12658, 'Моя ручная птица Рух', 'Дориан отдает мне дракончиков, которых ему удается поймать, чтобы я дрессировал и кормил их; но тут мне как-то вдруг пришло в голову, что я тоже хочу завести домашнего любимца.$B$BНет-нет, молодой дракончик не пойдет: мне не нужен любимец, который может руку откусить!$B$BНо к востоку от нашего лагеря, в Полях Костей, за теми землями, где живут драконы, обитает множество рухов-кровокрылов. Взрослого руха приручить невозможно, но если бы ты $gпринес:принесла: мне яйца, я мог бы воспитывать птенцов с того момента, как они вылупятся...', 'Принесите Любопытсону в форпост Дориана 7 яиц руха. ', 'О, как это чудесно! Мне уже надоели белки-роботы и цыплята: это не лучшая компания. И как замечательно иметь домашнего зверька, которому не нужно смазывать суставы машинным маслом!', 'Тебе удалось раздобыть яйца?', NULL, NULL, 'Яйцо руха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12659, 'Скальпы!', 'Самое время, $gдружище:подруга:, снять парочку скальпов! $B$BТролли в Хеб\'Драккар, что к северо-востоку, вполне подойдут. А то они вечно на нас нападают с этими своими дубинами, так что сами, считай, напросились!$B$BАуне даже даст тебе свой нож, чтобы было сподручнее.', 'По поручению Ауне из Зим\'торги возьмите нож Ауне и снимите скальпы с 10 хеб\'драккарских троллей.Не забывайте, сначала троллей следует обыскать.', 'Ага, моя думать, что это потешно, и очень. Вот это по-нашему, да!$B$B$N – славный $r!$B$BМой нож еще у тебя?', NULL, NULL, NULL, 'Оскальпировано хеб\'драккарских троллей', 'Нож Ауне', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12660, 'Орудия разрушения', 'Прислужники Короля-лича посмели принести орудия разрушения в мои владения. Я не потерплю этого.$B$BОтправляйся в их лагерь на северо-западе и уничтожь все, что они могут использовать против нас. Мы не позволим слугам Плети осквернить эту священную землю!', 'По поручению Аватары Фрейи отправляйтесь в лагерь Руки Смерти на северо-запад и уничтожьте 4 единицы нестабильной взрывчатки.', 'Благодарю тебя, $R. Ты можешь оказаться достойным помощников.', NULL, NULL, NULL, 'Уничтожено нестабильной взрывчатки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12661, 'На разведку в Волтар', 'Должно быть, ты уже $gдогадался:догадалась:, в чем состоит мой план.$B$BПлеть проявляет к тебе интерес, и мы этим воспользуемся. Ты будешь нашим лазутчиком в стане врага. Я понимаю, что это похоже на смертный приговор, но если мы будем сидеть сложа руки, то ты умрешь в любом случае.$B$BИди на северо-восток к Реликварию Боли и встань на платформу, надев маскировку. Когда ты проникнешь в Волтар, тебе нужно будет втереться в доверие к командиру Плети.$B$BКогда все будет готово, протруби в этот рог, и я прилечу к тебе, чтобы выслушать твой отчет.', 'По поручению Стефана используйте заколдованное колье, чтобы пробраться в Волтар. Там вы должны делать все, о чем вас попросит предводитель сил Плети.Если вы потеряете Заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.', 'Да... честно признаюсь, я не ожидал вновь увидеть тебя, $N.$B$BРассказывай, что ты узнал.', NULL, NULL, NULL, 'Задание властителя Дракуру выполнено', 'Рог Стефана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12662, 'Смерть Хеб\'Джина', '$gДагода смотрит на Ауне и вздыхает.>$B$BТы действительно хочешь идти в Хеб\'Драккар к тамошним троллям? Охота за скальпами – это, конечно же, замечательно. Но этого мало. Тебе нужно убить их вождя, Хеб\'Джина.$B$BПроблема в том, что он сейчас наверху, в гнездовье нетопырей, собирает войска.$B$BУдарь в его барабан, и он наверняка слетит вниз. И вот тогда ты его и убьешь.$B$BВозьми эту сеть, которую мы отобрали у одного из его охотников за головами. Набрось эту сеть на его нетопыря, когда он приземлится. И тогда тебе не придется сражаться с ними обоими.', 'По заданию укротителя стихий Дагоды из Зим\'Торги убейте Хеб\'Джина.', 'У тебя получилось!$B$B<Дагода радостно целует вас в щеку.>$B$BТы даже не представляешь, какое это огромное облегчение! Тролли наседают со всех сторон – это очень выматывает. Я уж не говорю о непрестанных воплях их главаря...это так раздражает!$B$BСпасибо, $N, можешь выбрать себе награду.', NULL, NULL, NULL, 'Хеб\'Джин убито', 'Сетка для ловли нетопырей', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12663, 'Воссоединение', '$N!$B$BСтало быть, ты $gполучил:получила: мой подарочек! А ну, поворотись, дай-ка я на тебя погляжу... да, я прямо тобой горжусь.$B$BМы прошли долгий путь вместе, а теперь вместе будем служить Королю-личу.$B$BДержись меня, $gдруг:подруга:, и мы замутим великие дела. Да, великие дела... но сначала нам надо, типа, ввести тебя в курс всего. С тех пор как мы виделись в последний раз, тут у нас многое изменилось!$B$BИди к Кровомесу, обговори с ним детали похода в Зул\'Драк. А потом я тебе расскажу что да как. Ну, типа, все, что тебе надо знать.', 'По заданию Дракуру из Волтара поговорите с Кровомесом и отправляйтесь в Зул\'Драк.', 'В общем, теперь ты уже вроде как в курсе, с чем нам придется столкнуться, дружище.$B$BИди, осмотрись, изучи эти края, типа, выработай стратегию...$B$BУ меня для тебя скоро будет работа.', 'Мы еще попляшем на развалинах Гундрака, дружище.', NULL, NULL, 'Прогулка по Зул\'Драку завершена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12664, 'Темный горизонт', 'Ага, еще $gодин проситель ответил:одна просительница ответила: на зов Короля-лича.$B$B<Дракуру обнюхивает вас.>$B$B<Новообращенный:Новообращенная:, да? От тебя все еще сильно воняет жизнью!$B$BМногие приходят выпрашивать милостей у Короля-лича. Если хочешь возвыситься над этим стадом, докажи, что $gдостоин:достойна: обладать истинной силой.$B$BОглядывая Зул\'Драк, я сразу почувствовал, что у тебя неплохой потенциал. Вот я, стало быть, и отправил тебе приглашение.$B$BА что будет дальше, зависит только от тебя...$B$BСтупай к Кровомесу, обговори с ним детали похода в Зул\'Драк. У меня для тебя будет, типа, работенка, а там уж посмотрим, чего ты стоишь.', 'По заданию Дракуру из Волтара поговорите с Кровомесом и отправляйтесь в Зул\'Драк.', 'Теперь ты знаешь, с чем нам придется столкнуться.$B$BСпускайся туда, изучи территорию, постарайся смешаться со своими собратьями. И готовься...$B$BУже очень скоро для тебя будет, типа, работа.', 'Ну что, дружище, ты уже понял расклад?', NULL, NULL, 'Прогулка по Зул\'Драку завершена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12665, 'Дурное предчувствие', 'Что-то случилось с Кетц\'лун, богиней крылатых змеев. Не знаю, что именно – не могу это почувствовать, – знаю только, что ее алтарь захватили могучие, сильные существа.$B$BНемедленно отправляйся туда. Ты поедешь верхом на одном из моих котят, спасенных тобою. Действуйте быстро и скрытно и узнайте, что стало с Кетц\'лун.$B$BПотом мой отпрыск доставит тебя обратно.$B$BКогда будешь $gготов:готова:, дай мне знать, и я позову одного из своих котят.', 'Узнайте, что случилось с Кетц\'лун. Хар\'коа даст вам в помощь одного из своих детей, чтобы незаметно пробраться к алтарю Кетц\'лун.Когда все выясните, возвращайтесь обратно к Хар\'коа – она ждет вас у своего алтаря.', 'Спасибо, что ты вернул моего котенка целым и невредимым.$B$BЯ предчувствовала недоброе. И ты подтвердил мои худшие опасения.$B$BИ все же я чувствую что-то еще. Все обстоит не так, как кажется.', 'Почему ты так долго собираешься, $N?', NULL, NULL, 'Судьба Кетц\'Лун выяснена.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12666, 'Путешествие в Нижний мир', 'Может быть, Кетц\'лун и мертва, но я чувствую, что ее дух задержался в Нижнем мире у алтаря. Тебе нужно проникнуть туда. Сейчас мы подумаем, как это сделать.$B$BК счастью для нас, тут полно бывших последователей, которым уже не нужны их священные украшения. Скорее всего, мои усмирители и Когти носят их до сих пор.$B$BПринеси мне украшения, и я использую их энергию, чтобы перенести тебя в Нижний мир к Кетц\'лун.', 'Соберите 8 священных украшений и принесите их Хар\'коа к алтарю Хар\'коа.', '<Богиня снежных леопардов смотрит на священные символы, которые вы принесли, и ее взгляд наполняется печалью.>$B$BБыло время, когда они что-то значили. Ладно, посмотрим, сумеем ли мы найти им более достойное применение.', 'Я не думала, что до этого дойдет. Драккари и вправду потеряны для нас.', NULL, NULL, 'Священное украшение', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12667, 'Поиски богини крылатых змеев', 'Ты $gподготовлен:подготовлена: неплохо, но у меня нет уверенности, что ты действительно $gготов:готова: к тому, что тебя ждет.$B$BКогда ты снова пойдешь к алтарю Кетц\'лун, тебе придется войти в царство мертвых. Если судить по тому, что я знаю, это будет не самый приятный опыт.$B$BПусть тебя не смущает то, что ты там увидишь. Ни на что не отвлекайся – просто иди к алтарю и разыщи дух Кетц\'лун.', 'Разыщите дух Кетц\'лун у алтаря Кетц\'лун.', 'Нежить, жалкий червяк. Скажи, что помешает мне уничтожить тебя на месте?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12668, 'Задел для мести', 'Для моих любимых верховных жрецов у меня приготовлено кое-что особенное. Но сначала я должна тебя испытать, чтобы знать, чего ты стоишь. Мне нужен хороший задел для мести, и ты этим займешься.$B$BТы ведь хочешь жить, да?$B$BКак ты $gсам уже видел:сама уже видела:, моим приверженцам нравится здесь, но их время уже пришло – время платить по последним счетам.$B$BСделай мне маленькое одолжение, $N. Замани их поближе к моим Темным купелям и убей.$B$BОни очень вкусные, так что их жертва не пропадет втуне, можешь не сомневаться.', 'Убейте 12 троллей из числа служителей Кетц\'лун или помешанных на змеях берсерков рядом с Темными купелями.Потом вернитесь к Кетц\'лун, которая будет ждать вас у алтаря.', 'Бесподобно. Быть может, ты все же на что-то годишься.', 'Почему ты вернулся, не закончив работу? Разве ты не понимаешь, что я могу уничтожить тебя одной силой мысли?$B$BСтупай, $R, и сделай все, что я тебе повелела!', NULL, NULL, 'Убито троллей у темных купелей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12669, 'Пока все идет на удивление паршиво', 'Добытые тобой сведения согласуются с тем, что мы уже знаем. Тебе надо как следует изучить Дракуру и втереться к нему в доверие.$B$BВозвращайся к нему и делай все, что он скажет. Постарайся, как следует, $N. Он должен поверить в искренность твоих намерений. От того, как ты сыграешь свою роль, зависит наше будущее.$B$BНа этот раз у тебя будет еще одно, дополнительное задание: как только представится возможность, подлей эту присадку в их чумные котлы. Она нейтрализует отравляющий реактив, так что их снадобье сделается бесполезным.', 'По поручению Стефана с Черной заставы вернитесь к Дракуру и выполняйте его приказы.Когда вернетесь в Реликварий Боли, вылейте растворитель в 5 котлов Плети.Если вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.', 'Молодец, $N!$B$BИспортив их зелье, ты не только спас множество жизней, но и замедлил наступление Плети на этот регион.$B$BА теперь расскажи, что ты узнал о планах Дракуру насчет Зул\'Драка.', 'Только не говори мне, пожалуйста, $N, что они тебя разоблачили...', NULL, NULL, 'Задание Дракуру выполнено', 'Котлы Плети обезврежены', 'Растворитель', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12670, 'Жатва Алых', 'Разлом Смерти – наш оплот под Акерусом и плацдарм, с которого начнется наступление на Алый орден. Сейчас ты возьмешь грифона из стойл, находящихся по обе стороны платформы, и отправишься туда с докладом к принцу Валанару. Служи ему верой и правдой – и тогда, возможно, ты доживешь до того дня, когда все эти земли падут перед нами.', 'Доложите о своем прибытии в Разлом Смерти принцу Валанару.', 'Ты это чувствуешь?$B$B<Валанар принюхивается к воздуху.>$B$BСвежим мясом запахло... Не иначе Алый орден подобрался поближе.$B$B<Валанар мечтательно сглатывает слюну.>$B$BАх, прошу прощения, рыцарь смерти. Вряд ли тебя интересуют мои кулинарные предпочтения. Ты ведь прибыл сюда по делу! Готов повести за собой наше войско? Знаю... готов. Король-лич все мне о тебе рассказал, $N.$B$BЧто ж, время битвы настало!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12671, 'Разведывательный полет', 'Думаю, пришло время запускать моторы и взлетать. Профессор меня просит выяснить, что это за странное погодное явление приближается к нам с северо-востока.$B$BНо штука в том, что мне понадобится второй пилот: места-то неисследованные... Короче, тролля с два я туда один полечу, ясно?$B$BНу, что ты на это скажешь, $gкрутой парень:красотка:? Может, чему полезному научишься. А уж если сумеешь справиться с северными ветрами, тогда вообще летай, куда хочешь!', 'Помогите пилоту Вику совершить разведывательный полет. ', 'Если бы не ты, тут бы мне и конец пришел. А так – ничего, здорово полетали!', NULL, NULL, NULL, 'Разведывательный полет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12672, 'Подготовка к мести', 'Я дам тебе шанс уцелеть.$B$BФрагменты силы, которая питает мое проклятие, рассеяны вокруг алтаря. Я хочу, чтобы ты $gсобрал и принес:собрала и принесла: их сюда. Не так много, чтобы снять проклятие, и все же достаточно для того, чтобы я смогла отомстить своему пророку.$B$BИди, $gничтожный:ничтожная:. Выполни мой приказ, пока я настроена подарить тебе жизнь. А то я могу и передумать.', 'Соберите 10 потусторонних энергетических фрагментов и вернитесь к алтарю Кетц\'лун.', 'Да, этого будет достаточно. Хотя теперь они вряд ли понадобятся.$B$BВпрочем, было забавно смотреть, как ты носишься по округе, выполняя мое повеление.', 'Жаль, что Хар\'коа не прислала тебя ко мне раньше. Хотя мы с ней никогда не ладили.$B$BВполне вероятно, что она специально тебя придержала, чтобы то, что случилось, успело случиться.', NULL, NULL, 'Потусторонний энергетический фрагмент', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12673, 'Сбор кристаллов', 'Если хочешь стать, типа, $gдостойным:достойной: даров Короля-лича, тебе надо бы научиться, как быть великим вождем – чтобы те, кто тебе подчиняются, тебя уважали! А то!$B$BУ меня как раз есть для тебя работенка, $gдружище:подруга:, так сказать, для пущего усовершенствования командных навыков...$B$BСейчас я обучаю своих упырят, чтобы они собирали кристаллы гнили, но они на удивление тупы и ленивы. В общем, бери их себе в подчинение.$B$BВот тебе скипетр, типа, орудие внушения и вразумления. Твоя задача – заставить этих ленивцев работать. Веди их вниз, и пусть они собирают кристаллы!', 'Командир Дракуру в Волтарасе хочет, чтобы вы взяли скипетр внушения и с его помощью заставили гнилостных упырей собрать 7 кристаллов гнили.', 'Ничего себе, сколько кристаллов! Раньше такого вообще не бывало!$B$BТы неплохо справляешься, $N. Так что жди – скоро будет еще работа.', 'Ну что, $N, как успехи?', NULL, NULL, 'Собрано кристаллов гнили', 'Скипетр внушения (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12674, 'Вся ярость преисподней', 'Ну что же, пора наказать моих верховных жрецов: Му\'фуну, Туа-Туа и Хавинни. Ты найдешь их вблизи алтаря.$B$BВозьми этот проклинающий жезл. Я зарядила его своей яростью и мощью. Это сильное оружие.$B$BУбей всех троих. А об остальном позаботится наложенное мной проклятие.$B$B<Кетц\'лун ехидно улыбается.>$B$BЕсли ты это сделаешь, может быть, я позволю тебе уйти. Если не сделаешь, ты умрешь.', 'По поручению духа Кетц\'Лун воздействуйте проклинаающим жезлом Кетц\'лун на верховного жреца Му\'фуну, верховную жрицу Туа-Туа и верховного жреца Хавинни. После этого вы должны их убить.', '<Ужасный дух издает хриплый смех, от которого кровь стынет в жилах.>$B$BОни получили по заслугам. И я позабочусь о том, чтобы все повторялось для них... вновь и вновь, вновь и вновь...', 'ТЫ СЧИТАЕШЬ МЕНЯ ИДИОТКОЙ?$B$BОНИ ВСЕ ЕЩЕ ЖИВЫ!', NULL, NULL, 'Верховный жрец Му\'фуну проклят перед смертью', 'Верховная жрица Туа-Туа проклята перед смертью', 'Верховный жрец Хавинни проклят перед смертью', 'Проклинающий жезл Кетц\'лун');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12675, 'И последнее...', 'У меня почти все готово, чтобы отомстить моему пророку, но мне нужно еще одно... самое главное. Фрагменты силы, которые ты $gсобрал:собрала:, нужно соединить с порцией духа живого бога. Тебе придется пойти к Хар\'коа и попросить, чтобы она дала тебе часть своего духа.$B$BКогда вернешься сюда, не иди в Нижний мир. Иди в материальный мир моего алтаря. Мои дети и стражи не тронут тебя, и ты спокойно пройдешь к моему пророку.', 'Отнесите Хар\'коа потусторонние энергетические фрагменты и попросите ее зарядить их частичкой ее духа. Вы найдете ее у алтаря Хар\'коа.', 'Часть моего духа?$B$B<Богиня снежных леопардов молчит, размышляя над вашей просьбой.>$B$BЭтот дар дорого тебе обойдется – тем более, если учесть, что он нужен для мести, а я сама сильно ослаблена действиями моих покорителей.$B$BИ все же я, кажется, знаю способ, как это сделать.', 'Ты вернулся, $N.', NULL, NULL, 'Потусторонние энергетические фрагменты (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12676, 'Диверсия', 'Пока мы пытаемся разобраться с предназначением этих кристаллов, нам нужно, чтобы ты $gвернулся:вернулась: в Волтар к Дракуру.$B$BВыполняй все его поручения. Пусть он видит, как ты стараешься. И тогда, может быть, он решит, что тебе можно довериться, и посвятит тебя в свои планы. Нам нужно знать, что он задумал.$B$BИ у тебя будет еще одно задание. Повозки Плети Дракуру представляют серьезную опасность. Их следует уничтожить. $B$BПроберись к повозкам, активируй эти заряды и немедленно уходи, чтобы тебя не накрыло взрывной волной!', 'По поручению Стефана с Черной заставы продолжайте выполнять поручения Дракуру.Кроме того, активируйте заряды взрывчатки, чтобы уничтожить 5 повозок Плети в Реликварии Боли.Если вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.', 'Замечательно!$B$BТы прирожденный диверсант, $N.$B$BА теперь давай посмотрим на этот скипетр...', NULL, NULL, NULL, 'Уничтожено повозок Плети', 'Задание Дракуру выполнено', 'Тайна Дракуру раскрыта', 'Взрывчатка');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12677, 'Опасные материалы', 'Кристаллы гнили?! Что он там затевает, этот мерзавец Дракуру?$B$BВполне очевидно, что он работает над каким-то действительно важным проектом. Продолжай служить ему \"верой и правдой\", и когда он узнает тебя получше, может быть, он посвятит тебя в свои планы.$B$BА нам надо бы посмотреть, что это за кристаллы.$B$BКогда будешь в Волтаре, постарайся как-нибудь незаметно добыть образцы кристаллов.$B$BНо будь $gосторожен:осторожна:! Соприкосновение с этими кристаллами может нарушить твою маскировку.', 'По поручению Стефана с Черной заставы вернитесь в Волтар и продолжайте выполнять поручения Дракуру. Также вам нужно украсть 5 добытых кристаллов гнили.Если вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.', 'Великолепно!$B$BМы прямо сейчас и приступим к изучению.$B$BА теперь расскажи мне, $N, что тебе удалось узнать нового о нашем добром приятеле Дракуру?', 'С возвращением, $N.$B$BТебе удалось выкрасть кристаллы у Дракуру?', NULL, NULL, 'Задание Дракуру выполнено', 'Добытый кристалл гнили', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12678, 'Когда Хаос правит бал, Страдание заказывает музыку', 'Они сейчас стоят у стен Разлома Смерти, тщетно пытаясь сдержать наш натиск, чтобы выиграть время для спасения лошадей, рудников, лесопилок и рабочих.$B$BНа их примере я преподам тебе первый урок военного искусства Плети: битвы выигрываются СТРАХОМ!$B$BОтправляйся к их передовым отрядам, осадившим нас на юге, и убей солдат Алого ордена. Их тела мы используем для создания собственной армии.$B$BНапоследок расправься с убегающими крестьянами. Мертвыми солдатами уже никого не напугать, но смерть безвинных людей посеет страх.', 'Принц Валанар из Разлома Смерти приказал вам убить 10 солдат Алого ордена или 10 крестьян из Алого ордена и 10 граждан Тихоземья.', 'Ты чувствуешь силу, которая пропитывает все твое тело, $N? Жалким смертным никогда не испытать этого восторга.$B$BИх авангард уничтожен. Мои упыри довершат начатое и подготовят почву для Разувия. Мы же обратим наше внимание на более насущные задачи.', NULL, NULL, NULL, 'Убито крестоносцев Алого ордена', 'Убито граждан Тихоземья', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12679, 'Сегодня мы ужинаем в Тихоземье', 'Затмители небес – это безмозглые големы, созданные с одной целью – убивать! Им приказано уничтожать всех мужчин и женщин, пытающихся спастись бегством из Тихоземья. Нельзя допустить, чтобы эти трусы нашли прибежище в Новом Авалоне и снова взялись за оружие!$B$BОднако у нас возникла одна небольшая проблема. Затмители вооружены саронитовыми стрелами, наносящими наибольший урон, а саронит – это очень редкий металл, который добывают только в Нордсколе, так что его запасы весьма и весьма ограничены. Принеси мне использованные стрелы, и я вознагражу тебя со всей щедростью.', 'Оритос Затмитель Небес из Разлома Смерти просит вас принести ему 15 саронитовых стрел.', 'Отличная работа, рыцарь смерти! Сегодня ты оказал великую помощь военной машине Плети!$B$BАх, да – вот и обещанная награда.', 'Судя по траекториям выстрелов, земля возле южной фермы Тихоземья должна быть буквально усыпана использованными стрелами.', NULL, NULL, 'Саронитовая стрела', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12680, 'Великий угонщик', 'Как удачно, что в двух шагах от этого аванпоста есть конюшня ордена! Хотя они тщательно охраняют своих лошадей, такому одаренному молодому рыцарю смерти не составит труда сломить их сопротивление и забрать то, что принадлежит нам по праву!$B$BКак только уведешь лошадь из Тихоземских стойл, приведи ее ко мне, и я постараюсь превратить ее в черного боевого коня-скелета, достойного того, чтобы носить на себе рыцаря смерти.$B$BЗапомни, $N: не пойман – не вор! И остерегайся их бешеного конюшенного, Китрика!', 'Саланар Всадник предложил вам украсть лошадь из Тихоземских стойл и привести ее в Разлом Смерти.', 'А теперь тебя ждет настоящее испытание. Сможешь ли ты укротить необъезженного скакуна и силой взять то, чего желаешь больше всего на свете?', 'Ты же не собираешься вечно ходить пешком?', NULL, NULL, 'Украдено лошадей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12681, 'Агент по реагентам', 'Верховный маг Пентарус из Даларана ждет, когда мы вернемся к нему с коллекцией разнообразных талисманов и реагентов. Говорят, местным особенно нравятся части тел животных, и больше всего – изогнутые когти птицы рух.$B$BНе знаю, верить или нет этим слухам, но попробовать можно.$B$BРухи живут на востоке, на Полях Костей; там они питаются трупами мамонтов. Ты же поможешь мне добыть когти для верховного мага, правда?', 'Принесите в форпост Дориана 5 изогнутых когтей руха и отдайте Колвину Норрингтону.', '<Колвин с удовольствием смотрит на принесенные когти.>$B$BЗдесь даже больше, чем нужно. У горлоков есть пословица: чем закрученнее коготь, тем больше в нем силы. Я уверен, верховный маг не зря потратился на эту экспедицию.', 'Ну как, удалось тебе найти когти?', NULL, NULL, 'Крученый коготь руха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12682, 'Неразведанная территория (DEPRECATED)', 'Не все мы в этой экспедиции здесь для того, чтобы гоняться за крупной и уникальной дичью. Кое у кого действительно серьезная работа.$B$BСамо существование этого места будоражит мозг – тропический рай в самом сердце Нордскола. Я не был бы достоит своего имени ученого, если бы не попытался понять это место.$B$BВозьми эти', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12683, 'Жгучее желание помочь', 'Во всей долине не сыскать более едкого материала, чем слюна гидры Горьких Волн. У меня есть специальные контейнеры, предназначенные именно для таких образцов. Верховному магу Пентарусу они нужны для исследований. И все, что мне нужно сейчас – это отважный, м-м... собиратель.$B$BТы выглядишь $gзакаленным и отважным:закаленной и отважной: $C. Может, тебе захочется подзаработать, а заодно приблизить час победы Даларана?$B$BТебе нужно всего-навсего прихватить этот резервуар с собой к озеру Горьких Волн, которое расположено к юго-западу отсюда. Разыщи гидр и с помощью контейнера собери слюну, которой они будут в тебя плеваться.', 'Колвин Норрингтон из форпоста Дориана хочет, чтобы вы принесли 5 образцов слюны гидры и убили 5 гидр Горьких Волн.', 'Великолепно! Вот твоя оплата, как договаривались. И прими маленький совет: если ощущение жжения не пройдет, возможно, тебе помогут горячие ванны.', 'Надеюсь, образцы у тебя?', NULL, NULL, 'Собрано образцов слюны', 'Гидра Горьких Волн убито', 'Резервуар для проб (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12684, 'Кровь мертвого бога', 'Мам\'тот, бог мамонтов, уничтожил себя, а вместе с собой – и изрядную часть своего храма, чтобы тролли не получили себе его силу.$B$BЯ принесу в жертву часть своей души, но чтобы все получилось, как надо, мне понадобится одна вещь.$B$BПосле смерти Мам\'тота остался гигантский кратер к северо-востоку отсюда, прямо на север от алтаря Кетц\'лун. В этом кратере его кровь до сих пор жива.$B$BПринеси ее мне.', 'Соберите 7 колб крови Мам\'тота и принесите их Хар\'коа к алтарю Хар\'коа.', 'Хорошо. Теперь посмотрим, получится или нет...', 'Жаль, что мы не можем вернуть Мам\'тота к жизни.$B$BНо мы можем почтить его память и продолжить борьбу против Драккари, чтобы его жертва была не напрасной.', NULL, NULL, 'Кровь Мам\'тота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12685, 'Что посеешь, то и пожнешь', 'Вот к чему все и пришло... к мести.$B$B<Хар\'коа вздыхает.>$B$BВозьми этот набор для обряда и выполни необходимый ритуал над телом Кетц\'лун на ее алтаре. Если все получится так, как надо, ее дух вернется в материальный мир, где она сможет вернуть силу, отобрав ее у пророка.$B$BА дальше действовать будешь ты, $N. Когда пророк обесс$N, тебе нужно будет его убить.', 'Убейте истощенного пророка Кетц\'лун и доложите об исполнении знахарю Кхуфу из Зим\'Торги.', '<Знахарь недоверчиво качает головой.>$B$BПохоже, ты еле ушел из Нижнего мира Кетц\'лун живым.$B$BЯ рад, что ты здесь. Не знаю, хватило ли бы мне храбрости разобраться с этой ситуацией в одиночку!', NULL, NULL, NULL, 'Ослабленный пророк Кетц\'лун убито', 'Ритуал Кетц\'лун', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12686, 'Терпение лопнуло', 'Невежество – вот источник всех бед и напастей! Не терплю недоумков, $gдружище:подруга:! Вся моя партия гнили – коту под хвост!$B$BЭтот кретин, Дармук! Он отвечает за то, чтобы приглядывать за гнилью. Он подвел меня, $gдруг:подруга:!$B$BПусть это послужит тебе уроком, $N. Скудоумие и неумение справляться с порученным делом – это та еще зараза. Если что-то такое подцепишь, надо сразу его убивать! Пока оно не убило тебя!$B$BВозьми этот скипетр. Он делает моих троллей Плети еще сильнее. Используй их для того, чтобы прикончить Дармука. Он шныряет, должно быть, где-то к югу отсюда, внизу.$B$BПусть это, типа, послужит примером для всех, $gдружище:подруга:. Не подведи Дракуру!', 'По поручению Дракуру из Волтара отправляйтесь в Реликварий Боли и примените скипетр Дозволенности к одному из слуг Дракуру. Потом с помощью этого слуги убейте Дармука.', 'Отлично сработано, $N. Ты учишься даже быстрее, чем я смел надеяться.$B$BТеперь ступай, отдохни. Очень скоро я дам тебе новое задание, и оно будет уже потруднее!', 'Ну что, Дармук поплатился за свою дурость, $N?', NULL, NULL, 'Дармук убит', 'Скипетр дозволенности (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12687, 'Путь в Долину Теней', 'Я отвел украденную тобой лошадь в Долину Теней. Именно там мои верные наездники оборвут его смертную жизнь и воскресят как коня смерти. Хватит ли тебе смелости $gсамому:самой: забрать его из Долины Теней?$B$BЕсли пожелаешь, я отправлю тебя в загробный мир. Как только окажешься на месте, найди темных всадников на полях к югу отсюда. Чтобы получить полную власть над своим конем, убей наездника, забери его скакуна и приведи обратно в Разлом Смерти. Вызови меня, если тебе улыбнется удача.', 'Саланар Всадник из Разлома Смерти предложил вам убить темного всадника Акеруса и забрать его скакуна.Если вам удастся совершить это, вернитесь в Разлом Смерти на коне и вызовите Саланара.', 'Ты преуспел там, где потерпели поражение многие опытные рыцари, $N. За это тебя ждет великая награда.$B$B<Саланар кланяется вам.>', NULL, NULL, NULL, 'Испытание Всадника пройдено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12688, 'Проектирование аварии', 'Варвары-гоблины и их прислужники решили, что эта колонна и кристаллы принадлежат им. Я пришла сюда, чтобы собрать и изучить образцы кристаллов, но гоблины не только не дали мне сделать этого – они еще и не дали мне вернуться в лагерь!$B$BЕсли ты поможешь мне выбраться отсюда, мы еще сумеем хорошенько проучить мерзавцев!', 'Помогите инженеру Хелис сбежать из Раскопа Хитрохмыла, а затем поговорите с Хемингом Эрнестуэем в лагере Эрнестуэя.', 'Спасибо за освобождение Хелис и за ее безопасное возвращение. Мы все беспокоились, когда она не вернулась со своей охоты за кристаллами.', NULL, NULL, NULL, 'Проводите инженера Хелис из Раскопа Хитрохмыла.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12689, 'Длань Оракулов', '', '', 'Здорово! Слушай, я так рад тебя видеть!Я знал, что мы друзья, я знал это! Ты хороший друг. Не только для нас: для всех Оракулов. Спасибо, ты спас всех нас!А здорово ты врезал тому волосатому! Я видел! Неживой сказал, что был твоим другом? Жаль, я не знал. Значит, ты больше не с волосатыми, ты теперь друг Оракулов?Только подумай хорошенько – ты правда-правда больше не хочешь дружить с волосатыми?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12690, 'Нам это на руку', 'Пора выступать на Гундрак, $gдружище:подруга:. Пора выпускать тебя на троллей!$B$BОни пробили нашу стену на севере и собрали там целую армию.$B$BХа-ха-ха!$B$BНам это на руку! Мы захватим вождей, а остальных попросту перебьем! Таков, типа, мой суперский план... $B$BВозьми этот скипетр и принимай командование над моими поганищами. Веди их на армию Драккари. Перебейте их всех! То-то будет потеха! А как только появятся вожди, мой любимец Глинокрыл схватит их и принесет мне сюда.', 'По поручению Дракуру из Волтара с помощью скипетра властности получите контроль над раздувшимися поганищами. С их помощью у Хладного разлома убейте 60 дробителей черепов Драккари, чтобы выманить 3 вождей племени.Вожди появятся, когда будет убито достаточно дробителей черепов.', 'Отлично, дружище! Мы это сделали!$B$BВожди уже в клетках, а мои поганища под твоим предводительством, типа, задали жару этим уродам.$B$BЭто надо отметить, дружище!', 'Ну что, ты расправился с этими троллями, $N?', NULL, NULL, 'Убито дробителей черепов Драккари', 'Вы выманили вождей Драккари', 'Скипетр властности (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12691, 'Старинный сундук', 'Похоже, этот каменный сундук заперт на ключ. Осталось всего ничего: вставить нужный ключ в каменную скважину…$B$BВозможно, ключ найдется у одного из стражей, находящихся поблизости?', 'Добудьте у стражей Шолазара огромный каменный ключ и старинный откройте сундук, который вы нашли в Дозоре Творцов.', 'Огромный каменный ключ поворачивается со скрежетом, крышка сундука открывается, и вашим глазам предстают сокровища.', 'Каменный сундук не отпирается.', NULL, NULL, 'Огромный каменный ключ', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12692, 'Возвращение охотника на личей', 'Ладно, я возвращаюсь на холм Бешеного Сердца. Я всем расскажу, что ты $gсделал:сделала: для волчеров и для Зепика. Кто думает, что ты не великий охотник, тот дурак.$B$BИди на холм и поговори со Старейшиной Харкеком… я расскажу ему, что ты не $gпредатель:предательница: племени Бешеного Сердца.$B$BПрими мою благодарность, охотник на личей.', 'Вернитесь на холм Бешеного Сердца и поговорите со старейшиной Харкеком.', 'Приятно видеть тебя снова. Я знал, что ты не предатель, я рад, что Зепек не ошибся в тебе.$B$BСлышал, теперь ты охотишься на личей – это очень хорошо! Харкек тобой гордится.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12695, 'Возвращение сухой шкуры', 'Ой-ой, наверное, Су-сэй о нас тревожится! Может, вернешься в город и скажешь ему, что все в порядке? Да-да, иди, поговори с Су-сэем.$B$BКак только заберу у дохлого лича светящийся шар, встречусь с тобой в городе! Иди-иди! Еще увидимся!', 'Вернитесь в прибежище Гласа Дождя и поговорите с верховным оракулом Су-сэем.', 'Рад тебя видеть снова! Мы волновались, не дождавшись твоего возвращения.$B$BДжалут очень быстрый; он вернулся скорее, он рассказал нам, как ты спас его от лича. Мульд рассказал, как ты спас мохобродов. Ты нам нравишься.$B$BНадеюсь, ты останешься тут подольше. Тут всегда столько дел...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12696, 'Воздушная разведка', 'Хорошо, что ты $gпомог:помогла: Весу с этим ветролетом. Теперь-то все работает как надо.$B$BЕсли хочешь и дальше помогать нам, у меня есть одно дельце. С северо-востока движется какой-то резкий циклон. У меня есть пилот, который готов его изучить, но ему нужен помощник.$B$BЕсли считаешь, что ты к этому $gготов:готова:, можешь лететь к озерному лагерю. А Вику скажи, что это я тебя послала.', 'Профессор Кальверт хочет, чтобы вы полетели в лагерь у озера и там поговорили с пилотом Виком.', 'Это профессор послала тебя сюда? Хорошо.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12697, 'Готик Жнец', 'Хаос воцарился на этих землях, $N! Орден пребывает в растерянности. Они отправили все войска Нового Авалона на защиту Заставы Света, которая находится к востоку отсюда. Таким образом они отчаянно пытаются опустошить Тихоземскую шахту и погрузить все добытые ресурсы на фрегаты, стоящие на якоре вдоль всего побережья.$B$BТебе не хочется слегка вмешаться в их планы? Недавно нас почтил своим присутствием сам Готик Жнец, великий некромант на службе Короля-лича. Он привез с собой небольшой подарок, который следует незамедлительно вручить Алому ордену. Отыщи его; он ждет твоего появления.', 'Поговорите с Готиком Жнецом в Разломе Смерти.', 'Вы сражались отчаянно, чтобы проникнуть в царство жнеца! Ох, погоди...$B$B<Готик пролистывает свои записи.>$B$BПрошу прощения, $R. Старые привычки неистребимы.$B$BПолагаю, тебя послал Валанар? Надеюсь, у него хватило ума послать кого-нибудь достаточно компетентного.$B$BВидишь ли, у меня есть небольшой подарок для жалких псов из Алого ордена. Сюрприз, который немного ускорит их работы на руднике.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12698, 'Подарок с подвохом', 'Я прибыл из самого ледяного сердца Наксрамаса, чтобы поглотить души и развеять тела наших кровных врагов.$B$BИнструмент, который я хочу доверить тебе – это переносной распространитель чумы. Отнеси его на восток, в Тихоземские шахты, и включи его, когда шахтеры из Алого ордена будут работать внутри. Когда все шахтеры обратятся в вурдалаков, возвращайся ко мне с собственной маленькой армией. А я пока освобожу для них место в моем вакуумном очистителе душ!', 'Готик Жнец из Разлома Смерти передал вам Дар Жнеца, с помощью которого вам надо обратить 5 шахтеров из Алого ордена в вурдалаков. Выполнив это поручение, верните прибор Жнецу.', 'Теперь они поймут, что на рудниках больше небезопасно, и постараются как можно быстрее убраться оттуда, забывая об осторожности!', 'Да, совсем забыл – прибор не всегда обращает людей в вурдалаков. Иногда они становятся разъяренными духами, одержимыми желанием убить тебя.', NULL, NULL, 'Обращено вурдалаков', 'Дар урожая', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12699, 'Затруднительное положение', 'Прежде чем мы двинемся в путь, нужно разрешить одну небольшую проблему. Видишь ли, я никак не могу найти ключи от своего ветролета. $B$BЯ уже везде их искал... Вот только что в озеро не нырял. Может, ты сумеешь мне помочь?$B$BЯ тебе даже свой кислородный баллон отдам! Правда, он почти пустой, но ненадолго его все-таки хватит...', 'Поищите ключи Вика в Слиянии рек. ', 'Великолепно!', 'Ну как, $N, не удалось найти ключи?', NULL, NULL, 'Ключи Вика', 'Аварийный кислородный баллон Вика', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12700, 'Момент для атаки', 'Только силы Алого ордена из Нового Авалона и с Заставы Света смеют бросать нам вызов! Настало время расправиться с их флотом на Заставе.$B$BДиверсия на руднике повергла в хаос их войска. Сейчас они отчаянно пытаются расчистить путь к своим кораблям.$B$BМедлить нельзя! Принц Валанар не упустит этого шанса раз и навсегда покончить с флотом Алого ордена. Немедленно отправляйся к нему!', 'Поговорите с принцем Валанаром в Разломе Смерти.', 'Ты служишь нам верой и правдой, рыцарь смерти. Немногие из твоих собратьев вернулись назад после нашей первой стычки с захватчиками из Алого ордена, но ты оказался в числе сильнейших.$B$B<Принц Валанар одобрительно кивает.>$B$BК востоку отсюда, за Тихоземской шахтой есть побережье, которое Алый орден пафосно именует Заставой Света. Их флот защищают тысячи верных солдат. Скажешь, нам никогда их не одолеть? Ошибаешься...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12701, 'Побоище у Заставы Света', 'В спешке люди ордена совершили одну роковую ошибку: они не стали проверять вагонетки.$B$BМы должны воспользоваться этой оплошностью. Возвращайся на восток, в Тихоземскую шахту, и найди вагонетку, оставленную моими прислужниками возле флигеля. Заберись в нее, и какой-нибудь шахтер с ветерком доставит тебя в тыл врага.$B$BКак только ты окажешься на борту одного из фрегатов, воспользуйся их пушками и перебей всех до единого!$B$BКогда выполнишь это поручение, позови грифона Плети, и он принесет тебя обратно.', 'Принц Валанар из Разлома Смерти приказал вам убить 100 защитников из Алого ордена.', 'Мы уничтожили весь флот Алого ордена в мгновение ока! Пожалуй, я заслужил одобрение Короля-лича! Нам осталось только разбить остатки армии Нового Авалона.$B$BЯ немедленно пошлю огненосцев и некромантов на Тихоземье. А ты лично доставишь мой доклад верховному лорду!', 'Рыцарь смерти не ведает страха!', NULL, NULL, 'Убито защитников Алого ордена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12702, 'И снова цыплята!', 'Бьюсь об заклад, никогда не догадаешься, что опять случилось!$B$BНет, это не связано с Горегеком и курами.$B$BЛадно, я вру. Из-за Горегека все куры опять разбежались. Глупый Горегек, бурчащее брюхо. $B$BДай мне знать, если тебе понадобится помощь охотников… они все где-то поблизости.', 'Поймайте 12 сбежавших кур для старейшины Харкека с холма Бешеного Сердца.', 'А ты неплохо их ловишь!$B$BМожет, однажды мы просто утопим Горегека в реке, чтобы тебе больше не приходилось ловить кур.', 'Обычно куры далеко не убегают… конечно, если их осы не съедят. Может, в следующий раз нам стоит оставить их на улице…', NULL, NULL, 'Пойманная курица', 'Сетка для ловли кур', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12703, 'Буйство Картака', 'Что, ты и есть великий охотник на личей? Хорошо, что в бою у племени Бешеного Сердца будет такой союзник. Может, У тебя достаточно сил, чтобы призвать самого Картака.$B$BБольшая битва на юго-западе, в Форте Картака. Иди, убивай сверкающих длинноязыких, пока не наберешь достаточно крови Оракулов. Принеси кровь к алтарю в форте Картака и позови Картака на пир.$B$BЕсли Картак решит, что ты $gдостоин:достойна:, он возьмет твое тело... могущество Картака поможет убить много длинноязыких, очень много.$B$BИди, охотник, иди и убивай!', 'Принесите чистый образчик Крови Оракула к алтарю Картака, чтобы призвать Картака. Используя его силу, уничтожьте 50 горлоков из племени Заиндевелых по просьбе шамана Джакжека в форте Картака.', 'Как легко прошел для тебя ритуал!$B$BНадеюсь, ту еще вернешься: тут осталось, кого убить.', NULL, NULL, NULL, 'Убито горлоков из племени Заиндевелых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12704, 'Умиротворение Великого камня дождя', 'С тех пор, как на мохобродов напали, я беспокоюсь: может быть, мы плохо относимся к Великому камню дождя... Может быть, мы слишком жадные. Мы должны жертвовать больше сокровищ!$B$BТебе в прошлый раз хорошо удалось найти блестящие штучки... Может быть, поищешь таких еще вокруг деревни? Тебе, может быть, понадобится кто-нибудь из наших добрых соплеменников в помощь? Скажи только, кто.', 'По просьбе верховного оракула Су-сэя из прибежища Гласа Дождя выберите себе спутника и с его помощью выкопайте 6 сверкающих сокровищ.Обязательно поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя, чтобы заручиться поддержкой кто-то из ваших прежних спутников.', 'Так много хороших блестящих штуковин! У тебя правда хорошо получается.$B$BПриходи потом еще, ладно?', 'Блестящих штучек всегда мало... Великий камень дождя добр к нам, мы должны быть добры к Великому камню дождя.', NULL, NULL, 'Драгоценные блестяшки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12705, 'Воля $Nв', 'Волосатые напали на Заиндевелых... Мы должны сражаться, или они нападут и на других оракулов тоже.$B$BТы $gбыл:была: нам хорошим другом – так что, может, мы окажем тебе особую честь. Великие давно-давно оставили защитника для святилищ... Он до сих пор здесь, но он не узнает, что что-то не так, до тех пор, пока это не коснется святилищ.$B$BУ волосатых там, внизу, есть плохие кристаллы, чтобы делать проблемы... принеси большой кристалл в святилище молний, чтобы Су-холу знал, что нужна помощь.$B$BНе пугайся, если Су-холу возьмет твое тело... он очень сильный, он тебя охранит.', 'Добудьте зараженный кристалл у одного из волчеров, что водятся рядом с Заиндевевшей гаванью и принесите его к великому камню молний, чтобы вызвать Со-холу. С помощью Со-холу убейте 50 находящихся поблизости волчеров Бешеного Сердца, после чего вернитесь к призывателю Су-мету в Заиндевелую гавань.', 'Со-холу сильный, да? Я очень счастлив, что он принял твое тело и разделил с тобой эту битву.$B$BОн больше доверяет тем, кого встречал уже – так что, может, как-нибудь придешь еще разок помочь нам?', NULL, NULL, NULL, 'Убито волчеров из племени Бешеного Сердца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12706, 'Победа у Разлома Смерти', '<Принц Валанар протягивает вам запечатанный свиток.>$B$BЭто полный отчет о нашей победе у Разлома Смерти. Я поручаю тебе доставить его верховному лорду Могрейну в Акерус. Я включил в доклад описание твоих героических действий, заслуживающих награды из рук самого Могрейна.$B$BИди же!', 'Доставьте доклад принца Валанара верховному лорду Дариону Могрейну в Акерус: Черный оплот.', '<Верховный лорд Могрейн просматривает доклад.>$B$BФлот Алого ордена ПОЛНОСТЬЮ уничтожен?$B$B<Верховный лорд Могрейн одобрительно качает головой.>$B$BКакая же сила скрыта в тебе, $N... Давно уже я не видел такой демонстрации превосходства... Пожалуй, с тех самых пор, как мой отец взял в руки...$B$B<Верховный лорд Могрейн взмахивает рукой.>$B$BВпрочем, это не важно...$B$BЧуть не забыл – вот твоя награда.', 'Не думал, что ты вернешься живым с поля битвы, рыцарь смерти. Возможно, я тебя недооценил.', NULL, NULL, 'Доклад принца Валанара (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12707, 'Яростное правосудие', 'Ауне слышать, что ты собираться идти к кратеру Мам\'тота, $gдружище:подруга:. Дети Мам\'тота беснуются в ярости и требуют правосудия!$B$BИди по этой дороге на северо-восток, на следующий ярус Зул\'Драка. Справа увидишь руины – то, что еще оставаться теперь от Алтаря Мам\'тота.$B$BКогда доберешься туда, ты потрясать этим вот медальоном Мам\'тота перед глазами у одного из разъяренных мамонтов. Он успокаиваться на время, и ты заберешься к нему на спину.$B$BСкачи на нем и затаптывай всех послушников мертвого Мам\'тота, которых найдешь!', 'По поручению Ауне из Зим\'торги используйте медальон Мам\'тота, чтобы успокоить одного из разъяренных мамонтов и забраться к нему на спину. Затем затопчите насмерть 12 послушников Мам\'тота.', 'Так им и надо, дружище!', NULL, NULL, NULL, 'Затоптано послушников Мам\'тота', 'Медальон Мам\'тота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12708, 'Заколдованные воины Тики', 'Я знаю, что ты направляешься в крепость Зол\'Маза на северо-востоке, $C. Мне нужно, чтобы ты $gразобрался:разобралась: с особыми стражами воеводы.$B$BИх называют заколдованными воинами Тики, и они представляют реальную угрозу. Если Драккари наладят их \"массовое производство\", нам перед ними не выстоять.$B$BНаша задача: продемонстрировать, что эти хваленые воины не стоят того, чтобы тратить на их создание силы, средства и время.', 'По заданию укротителя стихий Дагоды из Зим\'Торги уничтожьте 12 заколдованных воинов Тики.', 'Теперь они трижды подумают, прежде чем создавать этих тварей. Мне даже страшно представить, что было бы, если бы нам пришлось сражаться с целой армией этой пакости.$B$B<Укротитель стихий умолкает, о чем-то задумавшись.>$B$BВсе равно что сражаться с бесконечными толпами воинов Плети...', NULL, NULL, NULL, 'Уничтожено заколдованных воинов тики', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12709, 'Проклятые тайники', 'Прошу прощения, $N. До меня дошли слухи, что ты собираешься на северо-восток в крепость Зол\'Маза. Это как нельзя кстати. Хочу попросить тебя об услуге. Как ты, наверное, знаешь, мы собираем реликвии Драккари.$B$BМне стало известно, что вождь Драккари, патологический параноик, спрятал все свои сокровища в тайниках проклятой крепости, охраняемой темной магией. Ходят слухи, что его воины Тики обладают способностью снять проклятие, но доподлинно нам ничего не известно.$B$BЕсли сумеешь добыть хотя бы что-то из этих сокровищ, я буду очень тебе благодарен.', 'Принесите летописцу То\'кини в Зим\'Торгу 12 трофеев из крепости Зол\'Маза.', 'Нет, ты только посмотри!$B$BВзгляни сюда, $N. Видишь эти рисунки? Они явно доказывают, что Драккари уже давно знали об ослаблении земли, вызванном присутствием сил Плети.$B$BИ их вождь не преминул этим воспользоваться и подговорил пророков убить их богов, чтобы взять контроль над их силой и сразиться с воинством Короля-лича.$B$BВ любом случае, они обрекли себя на погибель. Пусть и непреднамеренно, но они обратили себя в инструмент своего собственного истребления.', 'Тебе удалось раздобыть сокровища?', NULL, NULL, 'Трофей из крепости Зол\'Маза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12710, 'Открытая тайна', 'Отлично справляешься, $N.$B$BЯ всегда знал: у меня нюх на таланты! А то! Теперь, стало быть, понимаешь, почему Король-лич меня выделяет... $B$BЯ так думаю, уже можно раскрыть тебе мой великолепный план, $gдружище:подруга:.$B$BСейчас ты поймешь, как мы прорвемся через полчища троллей драккари, чтоб занять свое место в великом дворце Гундрака. Место наше по праву! А то!$B$BВозьми этот скипетр, $gдружище:подруга:. Типа как в знак доверия. С ним ты сможешь проникнуть в мой верхний зал и поглядеть-подивиться на наше тайное оружие.', 'Телепортируйтесь в верхний зал Дракуру в Волтаре.', 'Ну вот, дружище, теперь ты знаешь.$B$BМы создаем мощную армию Плети в помощь Королю-личу. Он будет доволен! А то!$B$BОставь себе скипетр, $N. Он тебе пригодится, когда ты поведешь мою армию в бой...$B$BОчень скоро!', 'Ну что, уже поглядел на мои творения, $N?', NULL, NULL, 'Обследован верхний зал Дракуру', 'Скипетр господства', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12711, 'Заброшенный почтовый ящик', '', '', 'Сверху на почтовом ящике лежит пачка писем и свитков, накарябанных неразборчивым почерком. Какой хлам...Может быть, внутри ящика найдется что-то полезное?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12712, 'Ключ полководца Зол\'Маза', '$N, нам нужен ключ, чтобы отомкнуть оковы бога-люторога Акали. Его приготовили на убой, так что нам надо поторопиться.$B$BКлюч – у полководца Драккари, Зол\'Маза. Он наслышан о твоих подвигах, и поэтому скрылся вместе с семьей в их фамильной крепости к северо-востоку отсюда.$B$BТвой враг силен, ты не справишься с ним в одиночку. Чтобы вызвать полководца на поединок у ворот его фамильного гнезда, тебе потребуется помощь, и ты получишь ее, если объединишь амулет рода, меч и магическую формулу его домочадцев.', 'Раздобудьте ключ полководца Зол\'Маза для Хар\'коа из Зим\'Торги.', 'Наверное, мне надо было сказать тебе сразу, чтобы ты не возвращался сюда с ключом, а шел прямо в Гундрак.$B$BХотя, с другой стороны, хорошо, что ты здесь. Мне нужно тебе кое-что рассказать.', 'Надо добыть этот ключ любой ценой. Повторяю: любой ценой.', NULL, NULL, 'Ключ полководца Зол\'Маза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12713, 'Предательство', 'Пора заканчивать с этим фарсом, $N.$B$BИнформация, которую ты добываешь, она, безусловно, ценна, но нам нужно убрать Дракуру, пока он не завершил свой проект и не выпустил в мир всех своих жутких чудовищ.$B$BМы модифицировали твой скипетр. В нужный момент ты подчинишь себе гнилокровных троллей Дракуру и натравишь их на него. Это – единственная возможность его уничтожить.$B$BУдачи!', 'По поручению Стефана с Черной заставы убейте Дракуру.Если вы потеряете заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.', 'Стало быть, с этим мы разобрались.$B$BНам еще многое надо сделать, но теперь нам будет проще – благодаря тебе.$B$BПрими это в знак благодарности. И еще раз спасибо.', 'Ты сразился с Дракуру, $N?', NULL, NULL, 'Череп Дракуру', 'Скипетр господства', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12714, 'Воля Короля-лича', 'Нас движет вперед воля Короля-лича – кому, как не рыцарю смерти знать об этом. Все наше существование неразрывно связано с его повелением. Должно быть, ты уже $gчувствовал:чувствовала:, как в разговоре с тобой он с легкостью проникает в твои мысли...$B$BСлышишь ли ты сейчас его голос? Нет... должно быть, ты еще не $gготов:готова: к этому.$B$B<Могрейн закрывает глаза и кивает незримому собеседнику.>$B$BДа, мой повелитель. Все будет сделано.$B$B$N, тебе следует вернуться в Разлом Смерти и отчитаться перед принцем Валанаром. Приказ Короля-лича!', 'Возвращайтесь в Разлом Смерти и обратитесь к принцу Валанару.', 'Тихоземье пало! Тысячи трупов устилают землю, терпеливо ожидая воскрешения. Скоро мы нанесем решающий удар по нашему врагу со всей силой, на которую способна возрожденная Плеть!$B$BНаши вурдалаки уже начали осаду Нового Авалона; скоро к ним присоединятся и остальные войска, захватившие Склеп Воспоминаний.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12715, 'Склеп Воспоминаний', 'Мы начали осаду ворот последнего бастиона Алого ордена. В этот самый момент, когда вурдалаки разделываются с авангардом войск крепости, наши рабочие возводят передовое укрепление Плети – Склеп Воспоминаний.$B$BОтправляйся на юг, к склепу, граничащему с Новым Авалоном, и найди там моего дорогого брата, принца Келесета.$B$BЯ предупредил его о твоем прибытии.$B$BГотовься, $N, ибо тебе предстоит познать второй урок военного искусства плети: становление власти!$B$BВперед, рыцарь смерти!', 'Найдите принца Келесета в Склепе Воспоминаний.', 'Приветствую тебя, рыцарь смерти. Я – принц крови Келесет, правитель юго-восточных пределов Нордскола. Король-лич пожелал воспользоваться моими силами, чтобы покончить с жалким сопротивлением смертных, и я счастлив подчиниться воле моего господина. В конце концов, кто бы отказался насладиться страданиями бесчисленных тысяч душ?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12716, 'Просьба распространителя чумы', 'Смотри сюда, тыквенная твоя голова! Ты видишь, что тут чего-то не хватает? Конечно, не видишь, куда тебе! У тебя и при жизни мозгов не было – что уж говорить о послесмертии.$B$B<Нот тяжело вздыхает.>$B$BМне приказали сделать чумной котел, и ты мне в этом поможешь.$B$BПрямо за вратами Нового Авалона есть таверна. Найди там и укради пустой котел. Затем найди кузницу неподалеку от ворот и стащи оттуда железную цепь. Добавь к перечню 10 черепов рыцарей Света и принеси все это мне. Надеюсь, мне не надо объяснять тебе, откуда взять черепа?', 'Нот Чумной попросил вас принести ему пустой котел, железную цепь и 10 черепов рыцарей Света.', 'Отлично! Сейчас я все сделаю...', 'Ты все принес?', NULL, NULL, 'Пустой котел', 'Железная цепь', 'Череп рыцаря', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12717, 'Особое варево Нота', 'Скоро мы напоим из этого чумного котелка всю землю!$B$BА теперь, рыцарь смерти, я преподам тебе небольшой урок по обращению с чумными котлами. Пары, поднимающиеся над этим варевом, смертельны для любого живого существа – но не для посвященного Плети. Как и любое создание Плети, он питается смертью и крепчает с каждой поглощенной порцией.$B$BВозьми эти черепа рыцарей Света и брось их в варево. Могу поспорить, тебе это понравится!', 'Положите груду рыцарских черепов в чумной котел. Награда: Особое пойло Нота.', 'Чумной котел подпрыгивает, жадно принимая ваше подношение.$B$BЧерез несколько секунд на поверхности появляются несколько флаконов с черной жидкостью.', 'Варево в чумном котле лениво булькает.', NULL, NULL, 'Груда рыцарских черепов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12718, 'Черепа для пойла', '', '', 'Чумной котел подпрыгивает, жадно принимая ваше подношение.$B$BЕще несколько секунд – и вы сможете насладиться темным и пенистым пойлом Нота!', NULL, NULL, NULL, 'Череп рыцаря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12719, 'Некуда бежать и негде спрятаться', 'Меня устроит только полное уничтожение, $N. Несколько сотен безмозглых вурдалаков не смогут сокрушить врата Нового Авалона. Мы должны проникнуть во внутреннее святилище и уничтожить главу города. Мы дадим им понять, что от Плети нельзя укрыться за толщиной стен!$B$BПроберись в Ратушу Нового Авалона, которая находится к юго-западу отсюда, и убей мэра города. После этого обыщи здание и принеси мне учетную книгу Нового Авалона.', 'Принц Келесет из Склепа Воспоминаний приказал вам убить мэра Квимби и принести учетную книгу Нового Авалона.', 'Этот реестр расскажет нам много всего интересного о ничтожествах, именующих себя Алым орденом.$B$B<Келесет лениво перелистывает страницы.>$B$BТут есть все – уровень смертности, рождаемости и самое главное – их перемещения. $B$BВидишь, $N – они отправили из Нового Авалона целых три корабля. И куда они направляются? Ну-ка, посмотрим...$B$B<Келесет бормочет под нос что-то про широту и долготу, вычисляя координаты.>$B$BЧТО? Этого не может быть! Они плывут в Нордскол!$B$BЗдесь, под координатами есть подпись: \"Багровый Рассвет.\" Что бы это могло означать?', 'Спасения нет!', NULL, NULL, 'Мэр Квимби убито', 'Учетная книга Нового Авалона', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12720, 'Как завоевывать друзей и оказывать влияние на врагов', 'Путешествуя по миру, я сделал несколько важных открытий. Например, знаешь ли ты, что с помощью лести и подкупа можно вытянуть все тайны, скрытые в душе смертного? К счастью, у меня под рукой всегда есть подобные дары.$B$B<Келесет вынимает какой-то предмет из богато украшенной шкатулки.>$B$BВот мои лучшие \"доводы\", которые могут развязать язык любого смертного. Возьми их с собой на поле боя и предъяви солдатам Нового Авалона. Пусть они расскажут нам все про этот \"Багровый Рассвет.\"', 'Принц Келесет из Склепа Воспоминаний приказал вам узнать всю правду про \"Багровый Рассвет.\"Достаньте доводы Келесета из узорной шкатулки и \"разговорите\" с их помощью рыцарей Алого ордена.', 'Пробуждение? Что за чепуху ты несешь, парень! Какой глупец поведет за собой людей в самое сердце ледяных пустошей? Возможно, курьер даст нам ответ на этот вопрос...', 'Приведи мои доводы рыцарям Алого ордена. Рано или поздно кто-нибудь из них... поддастся на убеждения.', NULL, NULL, 'Вы узнали, что такое \"Багровый Рассвет\"', 'Расписанный орнаментами ящик', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12721, 'Буйство', '$N, времени уже не осталось. Мы должны забрать ключ и освободить Акали.$B$BЕго держат во внутреннем дворе перед входом в Гундрак, столицу Зул\'Драка. Цепи Акали держатся на четырех замках. Открой все замки и освободи бога-носорога.$B$BГундрак кишит ледяными троллями. И все же я думаю, что ты сможешь проскользнуть мимо них $gнезамеченным:незамеченной:. Главное – будь $gосторожен:осторожна:!$B$BКогда сделаешь все, что нужно, пожалуйста, сообщи об этом знахарю.', 'По поручению Хар\'коа из Зим\'Торги освободите Акали и сообщите об этом знахарю Кхуфу в Зим\'Торге.', 'Нет!$B$BЕще один бог уничтожен, и его сила похищена. Теперь пророк Акали угрожает нам напрямую.$B$BКогда он придет, он придет за Хар\'коа. Нельзя допустить, чтобы он забрал и ее силу тоже.$B$BНам надо вновь вопросить богов, $N. Они подскажут, что надо делать.', NULL, NULL, NULL, 'Акали освобожден от оков.', 'Ключ полководца Зол\'Маза', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12722, 'Овцы на бойне', 'Большинство людей спасаются бегством, стоит только тени некрополя пасть на их город. Но Алый орден не таков!$B$BДолжен признаться, война с орденом доставляет мне огромное удовольствие. За прошедшие годы наши стычки привели к нескольким величайшим трагедиям в человеческой истории, но они, как видно, никогда не начнут учиться на собственных ошибках.$B$BМы просто не можем отказать им в праве вновь послужить Королю-личу! Отправляйся в Новый Авалон и утоли их жажду смерти. Не щади никого!', 'Барон Ривендер из Склепа Воспоминаний приказал вам убить 10 солдат Алого ордена и 15 жителей Нового Авалона.', 'Ты прекрасно обращаешься с этим клинком, $N. Не желаешь стать моим прислужником – разумеется, с разрешения Короля-лича? Стратхольму нужен новый градоправитель.', NULL, NULL, NULL, 'Убито солдат Алого ордена', 'Убито граждан Нового Авалона', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12723, 'За Алым фронтом', 'Я отправил Орбаза, Тассариана и Кольтиру на поиски курьера. Они разбили лагерь за линией фронта, в Таверне Алого ордена, расположенной на юге Нового Авалона. Эта таверна хорошо скрыта от посторонних глаз между двумя садами неподалеку от Часовни Багрового Пламени. Найди ее и доложи о своем прибытии Орбазу Кровопорчу. Пусть он введет тебя в курс дела.', 'Найдите Орбаза Кровопорча в Таверне Алого ордена в Новом Авалоне.', 'Ты посмотри – похоже, нынче в рыцарей смерти посвящают кого попало. Когда мне была дарована великая честь вступить в ряды Плети, все было совсем по-другому!$B$BА что касается курьера...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12724, 'Путь истинного рыцаря', 'Мы понятия не имеем, где и когда должен появиться их проклятый курьер. Эти жалкие людишки тоже ничем не могут нам помочь.$B$B<Орбаз брезгливо указывает на трупы рыцарей Алого ордена, распростершиеся на полу.>$B$BВпрочем, мне все же удалось вытянуть кое-что из последнего слизняка. Оказалось, они хранят расписание патрулей в Крепости Алого ордена. Я поручаю тебе вломиться в крепость и достать этот документ. $B$BИщи самое большое здание в Новом Авалоне, который находится на северо-востоке.', 'Орбаз Кровопорч из Таверны Алого ордена в Новом Авалоне приказал вам украсть расписание патрулей Нового Авалона из Крепости Алого ордена.', '<Орбаз пролистывает расписание.>$B$BПохоже, у этих безмозглых слизняков полно работы! Расписание северных патрулей, восточных патрулей, южных патрулей, западных патрулей – и ни одного расписания курьеров! Минутку... А это еще что? Похоже на патрульный маршрут, проходящий возле Западных Чумных земель! В расписании он поставлен на сегодня! Надо все тщательно спланировать...', 'Обыщи всю крепость! Расписание хранится где-то там!', NULL, NULL, 'Расписание патрулей Нового Авалона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12725, 'Братья по смерти', 'Прорваться сквозь оборону Алого ордена было нелегко. Мы понесли серьезные потери, среди которых был один из наших лучших рыцарей смерти, Кольтира Ткач Смерти. Не знаю, жив он или мертв, но мы должны его найти.$B$BВ последний раз я видел его в цепях, пленником Крепости Алого ордена, которая находится на северо-востоке. Разбери это место на кучу камней, рыцарь смерти, но найди Кольтиру!', 'Найдите Кольтиру Ткача Смерти в Крепости Алого ордена.', 'Глупо было идти мне на помощь. Я подвел нас всех. Надо было бросить меня на откуп судьбе – ведь теперь мы оба рискуем жизнью. $B$B<Кольтира качает головой.>$B$BМы – рыцари смерти, верные слуги Плети. Мы связаны законами нашего темного братства.$B$BТассариан, ты идиот!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12726, 'Песнь Ветра и Воды', 'Слушаешь голос шторма? О да, здесь, на уступе Ваятеля Бурь можно услышать древнюю песнь – песнь Ветра и Воды…$B$BВеликая буря поглощает детей штормов и тайфунов. Возьми этот барабан, сыграй его песню… песню Хайфуна.$B$BПомоги ему насытиться ветром и водой, чтобы буря продолжалась.', 'Су-ни хочет, чтобы вы использовали Барабаны Шторма на уступе Ваятеля Бурь и помогли Хайфуну поглотить 3 загробников бури и 3 призраков дождя.', 'Благодарю тебя, $N. Благодаря тебе, великая буря будет милостива к нам.', NULL, NULL, NULL, 'Поглощено духов дождя', 'Поглощено загробников бури', 'Барабаны урагана', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12727, 'Кровавый побег', 'Я слышу вой сирен – скоро сюда прибудет верховный инквизитор и его послушники. Мои раны слишком тяжелы, но я все же постараюсь помочь тебе, чем смогу.$B$BУбей верховного инквизитора и его приспешников. Отруби ему голову и принеси ее Тассариану. Пусть этот акт отмщения прольется бальзамом на его ожесточенную душу. $B$BИ еще, $N... Если тебе удастся выжить и добраться до Тассариана, передай ему, что Алый орден казнит своих пленных в часовне. Возможно, он отправит тебя туда, чтобы ты $gсмог:смогла: проявить себя еще раз.', 'Убейте верховного инквизитора Валрота и отнесите его голову Тассариану в таверну Алого ордена в Новом Авалоне.', 'Я скормлю эту мерзкую голову вурдалакам!$B$B<Тассариан швыряет отрубленную голову в чулан.>$B$BКольтире удалось выбраться оттуда?$B$B<Тассариан умолкает.>$B$BНадеюсь, что да. Его не удержишь четырьмя стенами темницы.$B$BЧто ж, настало время расплаты!', 'Какие новости от Кольтиры?', NULL, NULL, 'Голова Валрота', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12728, 'Наблюдения за расселиной: пещера Зимних Плавников', 'Мне нужно собрать воедино мои заметки и подготовить выступление для моих коллег в Даларане.$B$BПока я займусь этим, я должен попросить тебя посетить пещеру Зимних Плавников на севере отсюда. Тебе нужно будет воспользоваться тайнометром, стоя у устья пещеры.$B$BВозвращайся ко мне, как только соберешь данные. Без них моя документация будет неполной.', 'По просьбе библиотекаря Гаррена с Янтарной гряды воспользуйтесь тайнометром у пещер Зимних Плавников.', 'Блестяще! Это довершит мой отчет.$B$BЯ непременно расскажу совету о твоих любезных услугах, $N.', NULL, NULL, NULL, 'Замеры у пещеры Зимних Плавников произведены', 'Тайнометр', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12729, 'Боги говорили с нами...', 'Боги говорили с нами, и нам не должно пренебрегать их мудростью.$B$BСобери друзей, $N. Отправляйтесь на север к Зим\'Руку, уничтожьте тамошних стражей и заберите у них безупречное сердце. Потом идите на юго-восток, к алтарю Кетц\'лун, и заберите у хранителей алтаря субстанцию ветра.$B$BПередайте то и другое Хар\'коа, и она призовет дух усопшего пророка Акали.', 'Принесите безупречное сердце стража и субстанцию ветра Хар\'коа в Зим\'Торгу.', 'Твоя храбрость, похоже, не знает границ, $N.$B$BОтдай мне сердце и субстанцию, и с их помощью я призову дух пророка.', 'Ты принес то, что требовалось, $N?', NULL, NULL, 'Безупречное сердце стража', 'Субстанция ветра', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12730, 'Вызов в Зол\'Хебе', 'Возьми этот инструмент насильственного призыва – вызова духов и сущностей – и отправляйся с друзьями в Зол\'Хеб, на юг от Гундрака.$B$BТам вы найдете круг силы. С помощью этого инструмента вы призовете пророка Акали.$B$BЗнай, $N, мое сердце – всегда с тобой. Мы столько всего пережили вместе, и ты $gспас:спасла: не только меня, но и многих богов, уничтоженных племенем Драккари.$B$BНо, боюсь, что теперь мы с тобой встретимся только в загробном мире.', 'По заданию Хар\'коа из Зим\'Торги убейте пророка Акали.', 'У тебя все получилось! $N, воистину ты – благословение для Зул\'Драка!$B$BМы у тебя в неоплатном долгу, и никакая награда не будет достойна твоих деяний, и все-таки зандалары оставили мне на хранение кое-какие предметы, которые, как они думали, могли бы тебя заинтересовать.$B$BПожалуйста, выбери себе награду. Но поторопись – у нас еще много важных дел!', 'Мне бы хотелось тебе помочь, но я могу дать тебе только теплое напутствие и сердечную поддержку.$B$BНе торопись, подготовься, как следует, и выступай, когда будешь готов. Только прошу, не затягивай слишком долго, потому что иначе пророк сам нагрянет сюда.', NULL, NULL, 'Пророк Акали убито', 'Вызов пророка Акали', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12732, 'Сила озаренной крови', 'Однажды Реджек станет могучим воином. Кровь и небесный огонь сделают Реджека сильным. Скоро увидишь.$B$BРеджек даст тебе фиал, а ты пойдешь далеко на запад, на самую вершину Колонны Солнечного Благословления. Наполни фиал водой.$B$BПотом иди к северному краю долины: там есть гряда к северу от Полей Костей. Там найдешь матриарха кровокрылов, убьешь ее и наберешь ее крови.$B$BСмешай кровь с водой, принеси Реджеку. Реджек выпьет, станет сильным.', 'Принесите фиал озаренной крови матриарха Реджеку на холм Бешеного Сердца.', 'Реджек благодарит. Реджек пьет, обретает силу; Реджек будет помнить твой подарок, $N.', 'У тебя подарок для Реджека?', NULL, NULL, 'Озаренная кровь матриарха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12733, 'Вызов смерти', 'Ритуал Вызова смерти родился после победы Короля-лича над Иллиданом Яростью Бури в самом сердце ледяных пустошей. Каждый рыцарь смерти должен пройти это испытание с честью.$B$BНайди других рыцарей смерти Акеруса и вызови их на дуэль. Они должны принять твой вызов и сразиться в смертельном поединке!$B$BИди же, $N, во имя Плети и Короля-лича!', 'Олрун Зовущая Битву приказала вам выиграть 5 дуэлей с другими рыцарями смерти.Выберите себе противников среди посвященных рыцарей смерти или других игроков.', 'Победа приносит славу, рыцарь смерти! Ты заслуживаешь похвалы самого Короля-лича!', NULL, NULL, NULL, 'Побеждено рыцарей смерти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12734, 'Реджек: первая кровь', 'Реджек стал самым юным воином племени Бешеного Сердца. Отец дал Реджеку могучий меч, чтобы побеждать врагов Бешеного Сердца – но древний обычай гласит, что сперва меч должен вкусить крови. Старшие воины обычно делают это. Ты окажешь Реджеку эту честь?$B$BБери меч, омой его в крови всех врагов Бешеного Сердца: ос, барабанчей, которые живут на юго-западе, и длинноязыких. Может, еще в крови шептунов: они далеко на северо-западе, возле озера Горьких Волн.', 'Омойте меч Реджека в крови осы Сапфирного улья, лютого барабанча и трех воинов или оракулов Шепота Тумана. Вернитесь на холм Бешеного Сердца к Реджеку.', 'Реджек видит пятна крови врагов на своем мече. Теперь у Реджека есть могучее оружие, и сам он станет могучим воином!', 'Меч Реджека омыт в крови врагов, да?', NULL, NULL, 'Клинок омыт кровью осы Сапфирного улья', 'Клинок омыт кровью воинов или оракулов Шепота Тумана', NULL, 'Клинок Реджека (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12735, 'Песнь Очищения', 'Земля низины Шолазар чиста. Колонны защищали эту низину многие века.$B$BВоды не столь чисты, ибо текут из-за пределов Шолазара… из океанов, озер и рек. Иногда вода приносит с собой недобрых духов; ее необходимо очистить.$B$BВозьми эти колокола – пусть они прозвенят подле озера Горьких Волн, у реки Ледяных Оков и у Слияния рек. Тогда злой дух разгневается... и ты убьешь его.', 'Су-ни из прибежища Гласа Дождя хочет, чтобы вы прозвонили в колокола Очищения возле озера Горьких Волн, у реки Ледяных Оков и у Слияния рек, а затем убили злых духов, отравляющих эти воды.', 'Воды отныне чисты. Да. Все хорошо.$B$BЯ вижу, $N, ты начинаешь нас понимать.', NULL, NULL, NULL, 'Дух Ата убито', 'Дух Кусу убито', NULL, 'Колокола очищения');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12736, 'Песнь Размышления', 'Само собой, ты не умнее горлока! Ты же всего-навсего $r.$B$BНо и для тебя еще есть надежда! Докажи, что можешь учиться. Может, кристаллы сделают тебя $gумным:умной:, как они делают умными нас.$B$BЯ научу тебя песне, которая очистит твой разум. Ты сыграешь песню перед кристаллами, а кристаллы сделают тебя умнее... не $gтаким умным:такой умной:, как горлоки, конечно, но лучше, чем сейчас. Колонна Жизненной Силы разрушена, но остальные колонны все еще стоят!', 'Су-ни из прибежища Гласа Дождя хочет, чтобы вы сыграли на диджериду созерцания на вершине Мерцающей колонны, Колонны Солнечного Благословения, Колонны Мохосвета и Колонны Небесного Пути.', 'Вот видишь? Ты уже становишься умнее. Ну, если уж не умнее, то счастливее наверняка!', NULL, NULL, NULL, 'Сыграйте на вершине Мерцающей колонны', 'Сыграйте на вершине колонны Небесного Пути', NULL, 'Сыграйте на вершине колонны Солнечного Благословения');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12737, 'Песнь Плодородия', 'Буря – разрушительная сила. Буря валит деревья и затапливает дома. $B$BНо буря может нести и силу жизни, если только знать верную песню. На уступе Ваятеля Бурь, что над Обителью Творцов, можно найти небольшие кучки грязи. Эта грязь плодородна и хранит в себе семена, способные дать могучие всходы. Нужно только подобрать правильную песню.$B$BВозьми этот рог и сыграй для них.', 'Оракул Су-ни из прибежища Гласа Дождя хочет, чтобы вы отправились на уступ Ваятеля Бурь, что к северо-западу от Обители Творцов, и сыграли на Роге Плодородия возле 8 кучек влажной плодородной грязи.', 'Ты быстро учишься, $N. Ты хорошо знаешь эту песнь. Может, в следующий раз я научу тебя еще одной.', NULL, NULL, NULL, 'Сыграна Песнь Плодородия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12738, 'Мольбы об отмщении', 'Мольбы об отмщении должны быть услышаны, $N. Командор Чумопал и его отряд рыцарей смерти сейчас направляется к Часовне Багрового Пламени, намереваясь стереть ее с лица земли и освободить наших пленных.$B$BЕсли поторопишься, ты все еще можешь их нагнать. Часовня находится к западу от этого места.', 'Найдите командора Чумопала в Часовне Багрового Пламени.', 'Смертные из плоти и крови – не соперники рыцарям Плети.$B$BМы не смогли освободить наших братьев, но зато обнаружили нечто весьма любопытное.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12739, 'Приятный сюрприз', 'Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий таурен, которого тебе будет особенно приятно предать смерти.', 'Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Малара Храброга, узника из Серебряного Рассвета, заключенного в темнице.', 'Не правда ли, приятно осознавать, что ты больше не на их стороне, Стритти. Ты – один из нас. Солдат Плети, отныне и навсегда...', NULL, NULL, NULL, 'Малар Храброг убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12740, 'Парашюты для Серебряного Авангарда', 'Эти чудовища с неба убивают моих людей! Падение с большой высоты – это страшная смерть.$B$B$C, тебе нужно передать им эти парашюты! По крайней мере, тогда у них будет хотя бы какой-то шанс выжить.', 'По поручению командира Фальштава на Серебряной заставе передайте парашюты 10 серебряным рыцарям или щитоносцам Серебряного Авангарда во внутреннем дворе.', 'Ты нам очень помог, $N. Даже не знаю, что бы мы без тебя делали.$B$BПобудь с нами еще. Я уверен, у нас тут найдется еще много дел, в которых нам может помочь такой храбрый $С, как ты.', NULL, NULL, NULL, 'Силы Серебряного Авангарда снабжены парашютами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12741, 'Сила Бури', 'Глупые длинноязыкие! Думают, если они станут петь облакам, это даст им силу. Реджек покажет длинноязыким, как обрести силу!$B$BДалеко-далеко на северо-западе есть большое ровное поле, которое длинноязыкие называют \"уступ Ваятеля Бурь\". Реджек уверен: туда можно добраться, только если летать, как птица.$B$BНа этом уступе – так слышал Реджек – обитают могучие духи воды и ветра. Убей их, забери их силу и принеси в храм длинноязыких – они называют его \"Святилищем бурь\". Как только ты обретешь абсолютную силу, Реджек будет ждать твоего возвращения.', 'Соберите 3 субстанции грозы и 3 субстанции бури и отнесите их в Святилище бурь. Вернитесь на холм Бешеного Сердца к Реджеку и принесите ему истинную силу бури.', 'Теперь Реджек покажет трусливым длинноязыким, как нужно использовать силу стихий!', 'Ты принес Реджеку истинную силу стихий?', NULL, NULL, 'Истинная сила бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12742, 'Приятный сюрприз', 'Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Однако нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий человек, которого тебе будет особенно приятно предать смерти.', 'Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Эллен Станбридж, узницу из Серебряного Рассвета, заключенную в темнице.', 'Не правда ли, приятно осознавать, что ты больше не на их стороне, Даргимн. Ты – один из нас. Солдат Плети, отныне и навсегда...', 'Ну, как ощущения?', NULL, NULL, 'Эллен Станбридж убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12743, 'Приятный сюрприз', 'Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий ночной эльф, которого тебе будет особенно приятно предать смерти.', 'Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Язмину Окенторн, узника из Серебряного Рассвета, заключенного в темнице.', 'Не правда ли, приятно осознавать, что ты больше не на их стороне, Мрачныйаскет. Ты – один из нас. Солдат Плети, отныне и навсегда...', 'Ну, как ощущения?', NULL, NULL, 'Язмина Окенторн убито', NULL, NULL, NULL);
