INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12750, 'Приятный сюрприз', 'Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий Отрекшийся, которого тебе будет особенно приятно предать смерти.', 'Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Антуана Брэка, узника из Серебряного Рассвета, заключенного в темнице.', 'Не правда ли, приятно осознавать, что ты больше не на их стороне, $N. Ты – один из нас. Солдат Плети, отныне и навсегда...', NULL, NULL, NULL, 'Антуан Брэк убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12751, 'Возвращение домой', 'Возвращайся к Тассариану в Таверну Алого ордена и сообщи ему, что мы отомстили за Кольтиру. Через несколько часов от Часовни Багрового Пламени останется только кучка пепла.$B$BТы – хладнокровное чудовище, $N. Я горжусь тобой, $gбрат:сестра:.', 'Возвращайтесь к Тассариану в Таверну Алого ордена, что в Новом Авалоне, и сообщите ему о вашей победе.', 'И снова Плеть празднует победу! Нет спасения псам Алого ордена. Смерть их близка...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12752, 'Отчаянный поиск', 'Настал час, $N, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $N, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.', 'Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.', 'Приветствую тебя, брат мой. Полагаю, тебя прислал сюда Орден Серебряного Рассвета, но я знаю, в чем истинная причина твоего появления. Ты хочешь помочь своему народу завоевать почет и уважение, которого мы заслуживаем. Любой Отрекшийся согласится с тем, что цель оправдывает средства, и наши разработки вакцины против чумы только подтверждают это вечное изречение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12753, 'Вынужденный союз', '$gОтважный:Отважная: $N, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, сможем мы выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $N.', 'Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.', 'Брат мой, я так горда быть рядом с тобой в эти дни скорби. Да благословят тебя небеса, и пусть этот союз людей и дворфов не пошатнется и за тысячу лет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12754, 'Засада в укреплении', 'Пока ты $gбыл занят:была занята: сжиганием церквей и истреблением паразитов, я разработал план дальнейших действий.$B$BСудя по расписанию, курьер Алого ордена должен через час пройти мимо Дозорного укрепления Алого ордена. Дорога вдоль укрепления пролегает по открытой местности, кишащей рыцарями Света. Воспользуйся этой маскировкой, чтобы спрятаться в самом укреплении, и жди там, пока не покажется курьер Алого ордена. Как только он приблизится, убей его и забери все, что при нем будет включая одежду!$B$BУкрепление находится на востоке в двухстах шагах от этого места.', 'Орбаз Кровопорч из Таверны Алого ордена в Новом Авалоне приказал вам убить курьера Алого ордена и забрать его пожитки и депешу.', '<Орбаз читает депешу.>$B$BТак значит, армии Дольного Очага и Тирисфальских лугов направляются прямо к нам в руки!$B$B<Орбаз ухмыляется.>$B$BОтлично, переходим ко второй части нашего плана. Ты лично доставишь это донесение верховному генералу Аббендис. Для этого-то тебе и пригодятся эти шмотки...', 'Если упустишь курьера – я с тебя лично голову сниму. И сделаю это с превеликим удовольствием.$B$BЧего стоишь, беги!', NULL, NULL, 'Вещи курьера Алого ордена', 'Дерево для маскировки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12755, 'Встреча с судьбой', 'Это сообщение должно попасть в руки Аббендис. Не стоит вызывать ненужные подозрения – пусть считает, что все идет по плану.$B$BТы облачишься в одежды курьера Алого ордена, а мы придадим тебе его облик с помощью черной магии.$B$BАббендис сейчас находится в Королевской гавани, что к юго-востоку от Дозорного укрепления Алого ордена. Отнеси это послание и постарайся вытянуть из нее как можно больше информации. Надеюсь, она поведает нам о \"Багровом Рассвете\".', 'Орбаз Кровопорч приказал вам доставить депешу курьера Алого ордена верховному генералу Аббендис в Королевскую гавань.', '<Верховный генерал Аббендис читает депешу.>$B$BПроклятие! Войска Дольного Очага и Тирисфальских лугов нельзя было посылать в Новый Авалон! Плеть разгромит их еще на подходе!', 'Где ты пропадаешь? Тебя ждали два часа назад. Мы уже собирались послать курьера к главнокомандующему.', NULL, NULL, 'Депеша курьера Алого ордена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12756, 'Алый Натиск', 'Слушай меня, курьер. Эти земли потеряны для Алого ордена. Плеть захватила Новый Авалон и Тихоземье, и над нашими головами уже реет призрак смерти.$B$BВернись к Галвару и передай ему мое сообщение:$B$B\"Поворачивайте назад и готовьте корабли к походу в северные земли. Встретимся в Нордсколе.\"$B$BОтдай это Галвару.$B$B<Аббендис протягивает вам свой дневник.>$B$BОн все поймет.$B$BАлого Ордена больше нет. Настал час Алого Натиска!', 'Отнесите Путь Искупления Орбазу Кровопорчу в Таверну Алого ордена в Новом Авалоне.', '<Орбаз листает журнал.>$B$BКакая чепуха! Так вот что значит \"Багровый Рассвет!\"$B$BОни плывут прямо в лапы смерти! Впрочем, сейчас мы должны сосредоточиться на устранении идущих к нам армий.', '<Орбаз хохочет.>$B$BЭто еще что? Детская раскраска?', NULL, NULL, 'Путь искупления (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12757, 'Теплый прием для армий Алого ордена', 'Мы должны подготовиться и достойно встретить армии захватчиков. Ты, $N, лично сообщишь эти сведения верховному лорду Могрейну! Я открою для тебя портал в Акерус. Войди в него, и он отправит тебя в нужное место.$B$BЗаодно отдай верховному лорду дневник Аббендис. Думаю, он почерпнет из него немало полезных сведений.', 'Отнесите Путь Искупления верховному лорду Дариону Могрейну в Акерус: Черный оплот.', 'Воистину, ты стал рукой самой судьбы, рыцарь смерти! Мы уничтожим эти армии, и их воскресшие солдаты примкнут к нашему войску!', 'Что?', NULL, NULL, 'Путь искупления (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12758, 'Шлем героя', 'Реджек слышал рассказы об огромных людях из железа с уступа Ваятеля Бурь. Этот уступ находится далеко на северо-западе, за краем низины.$B$BХорошо было бы, если бы Реджек получил одну такую железную голову! Реджек сделал бы из нее шлем. Реджек могучий! Реджек неукротимый!..$B$BТы это принеси Реджеку, хорошо? Только вот, может, железную голову от железного тела просто так не оторвешь. Можно стащить бомбы у маленького зеленого народца и их друзей из Раскопа Хитрохмыла у Колонны Солнечного Благословения. Бомба оторвет голову от железного тела, а ты принесешь голову Реджеку.', 'Заполучите взрывчатку у любого члена Торговой Компании возле Раскопа Хитрохмыла и используйте ее, чтобы заполучить голову наблюдателя бурь. Принесите голову на холм Бешеного Сердца и отдайте Реджеку.', 'Реджек видит, что удача на твоей стороне! А теперь Реджек наденет новый шлем…', 'Где новый шлем для Реджека?', NULL, NULL, 'Голова наблюдателя бурь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12759, 'Орудия войны', 'Зепик говорит – может, ты лучший охотник горлоков, которого он встречал… кроме Зепика. На юго-западе идет большой бой: иди туда и помоги.$B$BЗепик держит самые страшные и опасные ловушки в форте Картака… сказал Векгару, что их можно пустить в ход в бою, так что ты тоже можешь их взять. Иди, бери любые ловушки, какие хочешь. Убей много длинноязыких!$B$BОчень много длинноязыких!', 'Раздобудьте несколько ловушек Зепика из форта Картака. Используя ловушки, убейте 50 горлоков из племени Заиндевелых, а затем вернитесь к шаману Якжеку в форт Картака.', 'Ты управляешься с этими ловушками почти так же хорошо, как Зепик!', NULL, NULL, NULL, 'Горлок из племени Заиндевелых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12760, 'Тайная сила племени Бешеного Сердца', 'Битва у форта Картака все продолжается... Я думаю, для тебя настало время узнать большой секрет племени Бешеного Сердца.$B$BУ нас есть ягоды, которые мы принесли с собой из другой земли, откуда мы родом... В них самих по себе нет ничего особенного, но если смешать их с алкоголем, то смесь любого из наших сделает силачом! Ты же теперь тоже принадлежишь Бешеному Сердцу... Пришло время стать $gсильным:сильной:.$B$BЯ дам тебе один напиток – выпей его, тогда к тебе придет большая сила и ты сможешь перебить всех сверкающих длинноязыких.', 'Воспользовавшись силой секретного напитка племени Бешеного Сердца, перебейте 30 горлоков из племени Заиндевелых у форта Картака.', 'А ты боец что надо... Приходи, еще посражаешься! Хорошего боя много не бывает!', NULL, NULL, NULL, 'Горлок из племени Заиндевелых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12761, 'Власть над кристаллами', 'Волосатые все еще нападают на Заиндевелых… мы думаем, что, возможно, они не остановятся, если мы их не остановим. Но у нас есть тайное оружие…Мы послали его Су-мету: с его помощью он сумеет защитить всех Оракулов.$B$BЭто тайное оружие создали сами Великие... а сияющие кристаллы для него можно найти в священных храмах Великих. Будь очень $gосторожен:осторожна:... не разбей их.$B$BКристаллы в сундуке возле святилища в Заиндевелой гавани, далеко на юго-западе. Потом ты поможешь Су-мету использовать кристаллы, чтобы одолеть волосатых.', 'Добудьте кристаллы в Заиндевелой гавани и используйте их, чтобы убить 50 волчеров Бешеного Сердца, находящихся поблизости. Выполнив задание, возвращайтесь к призывателю молний Су-мету в Заиндевелую гавань.', 'Благодарю тебя, сухая шкура.$B$BЭти кристаллы останутся здесь, чтобы мы были в безопасности. Может, вскоре ты вернешься и снова сумеешь помочь нам.', NULL, NULL, NULL, 'Убито волчеров из племени Бешеного Сердца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12762, 'Могущество Великих', 'Мы должны что-то сделать. Надо остановить волосатых, нападающих на Заиндевелую гавань. Джалут принес мне особенный кристалл, который он нашел в Слиянии рек… такой мы видели лишь однажды.$B$BСейчас у кристалла нет силы, но она вернется, если только поднести его к разрушенной колонне Жизненной Силы. Когда кристалл обретет силу, иди в Заиндевелую гавань на юго-западе: пусть кристалл даст тебе великую мощь!$B$BТогда ты сумеешь справиться с волосатыми.', 'Зарядите отполированный дремлющий кристалл возле колонны Жизненной Силы. Затем отправляйтесь в Заиндевелую гавань и используйте силу кристалла, чтобы убить 30 волчеров из стаи Бешеного Сердца, находящихся поблизости, и поговорите с Призывателем молний Су-метом в Заиндевелой гавани.', 'В тебе столько энергии… столько силы Великих!$B$BЯ не лгу, я просто немного завидую тебе.', 'Хорошо, что ты здесь и помогаешь нам. Это был долгий бой.', NULL, NULL, 'Убито волчеров из племени Бешеного Сердца', 'Дремлющий полированный хрусталь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12763, 'Смена приоритетов', 'Да, нам сейчас приходится нелегко, но ситуация в северных землях еще более удручающая.$B$BЯ только что получил сообщения от Серебряного Авангарда. Судя по донесениям, отряды Плети готовятся захватить Зул\'Драк!$B$BДумаю, ты понимаешь, что в случае их успеха наша борьба становится бессмысленной. Прошу тебя, отправляйся туда и помоги рыцарям Света отразить нападение армии Короля-лича.$B$BПоговори с Макки, и он отправит тебя в Зул\'Драк.', 'Разведчик Вор\'такх просит вас отправиться в Зул\'Драк и разыскать сержанта Рианну в Разломе Света.Вам укажет дорогу Макки Зимний Ветер.', 'Во имя Света!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12766, 'Разговор с послом', '$gДракон в облике эльфа берет ваше рекомендательное письмо, с пару мгновений изучает его, а затем прячет себе в рукав.>$B$BПохоже, все в порядке. Но если не возражаешь, я попросил бы тебя поговорить с вашей посланницей здесь, в храме.$B$BУ нее есть к тебе какое-то важное дело, с которым нужно разобраться раньше, чем мы отправим тебя к королеве.$B$B<Он похлопывает по письму, скрытому в рукаве.>$B$BОно будет ждать тебя в целости и сохранности.', 'Поговорите с Лориэль Верный Клинок в храме Драконьего Покоя.', 'Ты, должно быть, $N. Мне сообщили, что ты прибудешь.$B$B<Посол кряхтит.>$B$BЕсть одно дело, с которым можешь справиться только ты. И тогда ты завоюешь доверие этих драконов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12767, 'Разговор с послом', '$gДракон в облике эльфа берет ваше рекомендательное письмо, с пару мгновений изучает его, а затем прячет себе в рукав.>$B$BПохоже, все в порядке. Но если не возражаешь, я попросил бы тебя поговорить с вашим послом здесь, в храме.$B$BУ него есть к тебе какое-то важное дело, с которым нужно разобраться раньше, чем мы отправим тебя к королеве.$B$B<Он похлопывает по письму, скрытому в рукаве.>$B$BОно будет ждать тебя в целости и сохранности.', 'Поговорите с Голлуком Каменным Кулаком в храме Драконьего Покоя.', 'Ты, должно быть, $N. Мне сообщили, что ты прибудешь.$B$B<Посол кряхтит.>$B$BЕсть одно дело, которое я хочу тебе поручить. Если сделаешь – покажешь здешним драконам, на что способен.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12768, 'Распорядитель храма Драконьего Покоя', 'Ты $gдоказал:доказала:, что тебе можно доверить все и даже больше.$B$BВозвращайся в храм Драконьего Покоя, $N, и снова поговори с его распорядителем, Тариолстразом.', 'Поговорите с Тариолстразом в храме Драконьего Покоя.', 'Уже вернулся $N?$B$BЦеристраз сообщил о тебе заранее. Спасибо за то, что ты совершил в Рубиновом святилище.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12769, 'Распорядитель храма Драконьего Покоя', 'Ты $gдоказал:доказала:, что тебе можно доверить все и даже больше.$B$BВозвращайся в храм Драконьего Покоя, $N, и снова поговори с его распорядителем, Тариолстразом.', 'Поговорите с Тариолстразом в храме Драконьего Покоя.', 'Уже вернулся $N?$B$BВаргастраз сообщил о тебе заранее. Спасибо за то, что ты совершил в Рубиновом святилище.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12770, 'Перераспределение', 'Слушай внимательно, $C!$B$BЗдесь твоя служба подошла к концу. Нет, нам все еще очень нужны умелые |3-7($C), но сейчас твоя помощь нужна на севере. По сравнению с тем, что там происходит, наши проблемы кажутся ничтожными. $B$BОказалось, что Плеть не теряла времени зря, и сейчас ее армия штурмует Зул\'Драк. Если эта твердыня падет, то погребет под собою всех нас.$B$BЗакончи все свои дела и немедленно отправляйся в Разлом Света. Самуэль поможет тебе добраться до места.$B$BВольно!', 'Гриан Камнегрив отправил вас к сержанту Рианне в Разлом Света, находящийся в Зул\'Драке.Обратитесь к Самуэлю Клирбуку, и он доставит вас на место.', 'Во имя Света!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12771, 'Стальгорн', 'Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $N. Охраняй ее как зеницу ока и доставь в Стальгорн в целости и сохранности. Я знаю, что Магни Бронзобороду не терпится выступить в Нордскол, и с помощью этого артефакта он быстрее достигнет цели.', 'Епископ Лазарил просит вас отнести заряженный Светом артефакт королю Магни Бронзобороду в Стальгорн.', 'Клянусь моей бородой, что за могущественный артефакт! Его силы хватит на то, чтобы поднять в воздух целый флот ветролетов! Я отдам его нашим боевым жрецам. Вот увидишь, скоро эти мерзкие некрополисы будут удирать обратно в Нордскол, а наши армии будут преследовать их по пятам!$B$BОх, Мурадин, брат мой, ты должен дожить до нашего прихода! Я найду тебя, клянусь честью Бронзобородов!', 'Приветствую тебя, $N! Я горд видеть перед собой столь могучего представителя нашей расы! Неужто тебя закалили ветры Запределья, брат мой?', NULL, NULL, 'Заряженный светом артефакт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12772, 'Вынужденный союз', '$gОтважный:Отважная: $N, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, мы сможем выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $N.', 'Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.', 'Приветствую тебя, о благородный ночной $r. Пусть Свет озарит твой путь, и да расступится тьма перед светочем мудрости вашей древней расы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12773, 'Дарнас', 'Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $N. Охраняй ее как зеницу ока и доставь в Дарнас в целости и сохранности. Я знаю, что Тиранда Шелест Ветра и ее жрецы смогут разумно распорядиться этой силой в борьбе против презренных порождений Плети.', 'Епископ Лазарил просит вас отнести заряженный Светом артефакт Тиранде Шелест Ветра в Дарнас.', '', NULL, NULL, NULL, 'Заряженный светом артефакт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12774, 'Штормград', 'Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $N. Охраняй ее как зеницу ока и доставь в Штормград в целости и сохранности. Не сомневаюсь, что новообретенный король найдет применение этому оружию.', 'Епископ Лазарил просит вас отнести заряженный Светом артефакт королю Вариану Ринну в Штормград.', 'Потрясающе! Эти святоши из Шаттрата сдержали слово! Значит, наше решение отправить туда целый отряд жрецов и паладинов было единственно верным. Кто знает, быть может именно этот артефакт поможет нам одержать окончательную победу над Королем-личом и его прислужниками!$B$BПрими мое благословение, благородный лорд.', 'Приветствую тебя, $N! Твоя сила и мудрость станут нам опорой в это смутное время.', NULL, NULL, 'Заряженный светом артефакт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12775, 'Вынужденный союз', '$gОтважный:Отважная: $N, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, сможем мы выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $N.', 'Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.', 'Брат мой, мы снова призваны сражаться с Плетью. Хвала Свету, что ты присоединишься к нашим рядам, ибо мы уповаем только на твою силу и благословение небес.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12776, 'Экзодар', 'Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $N. Охраняй ее как зеницу ока и доставь неприкосновенной в Экзодар, в Чертог Света. Отдай артефакт пророку Велену – пусть он направит его силу против проклятых созданий Плети.', 'Епископ Лазарил просит вас отнести заряженный Светом артефакт Велену в Экзодар.', 'Я чувствую силу наару, струящуюся сквозь артефакт, будто бы сам Свет заключен в этой святыне! Как много добра можно совершить с ее помощью; и я уже предвижу, как падут посланные с севера некрополисы.', 'Дитя мое, я вижу, как закалили твой дух земли людей и орков. Ты и сам не подозреваешь о скрытых в тебе силах...', NULL, NULL, 'Заряженный светом артефакт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12777, 'Вынужденный союз', '$gОтважный:Отважная: $N, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия двух противостоящих друг другу сторон, мы сможем выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $N.', 'Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.', 'Сердце мое наполняется Светом, когда я вижу в наших рядах столь благородного дренея, откликнувшегося на зов о помощи. Будь благословен твой путь, отважный $C!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12778, 'Конец Алого ордена', 'Мышеловка захлопнулась, рыцарь смерти. Армии Дольного Очага и Тирисфальских лесов прибыли как раз вовремя, чтобы узреть падение своего аванпоста! Если они решат повернуть назад, мы ударим им в спину. $B$B<Могрейн качает головой.>$B$BУвы, у них не осталось выбора, кроме как принять свою смерть!$B$BВ этот самый момент они готовятся к свой последней битве.$B$BКороль-лич ожидает твоего возвращения, защитник. Он взирает на нас с высоты Разлома Смерти.', 'Найдите Короля-лича в Разломе Смерти.', '$N, мой преданный рыцарь смерти, я вижу клеймо Плети, выжженное на этих землях твоей рукой. Ты посеял смерть и разрушение во всех пределах и привел ко мне жалкие остатки армии Алого ордена. $B$B<Король-лич обводит рукой пылающие останки Тихоземья и Нового Авалона.>$B$BНастало время закончить то, что было начато.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12779, 'Конец всему...', 'На твоих руках кровь бесчисленных жертв, но твое черное сердце все еще не насытилось их страданиями. Оно никогда не утолит эту жажду, $N.$B$B<Король-лич умолкает.>$B$BНо всему на свете приходит конец, рыцарь смерти. Армии Алого ордена собираются на последнюю битву против нас. Им нет спасения, пути назад отрезаны, и потому они будут сражаться с невиданной яростью.$B$BВозьми этот рог и призови одного из моих змеев. На его спине ты поведешь в бой наши войска, и рев его ознаменует конец Алого ордена.', 'Король-лич приказал вам покончить с Алым орденом.Возьмите рог ледяного наследия и призовите ледяного покорителя, с помощью которого вам надо будет убить 150 солдат из Алого ордена и уничтожить 10 баллист Алого ордена. Постарайтесь не попасть под обстрел и вовремя уходите с линии огня!', 'Преклони колени, воитель. Пусть этот шлем довершит твой ужасный облик, чтобы каждый противник, осмелившийся взглянуть тебе в лицо, увидел в нем отражение неминуемой смерти. Пусть ни один наглец, бросивший вызов твоему королю, не избежит твоего гнева, $N.$B$BНам остается только одно...$B$B<Король-лич устремляет взгляд на запад.>$B$BРазрушить Часовню Последней Надежды.', 'Убей их всех...', NULL, NULL, 'Убито солдат Алого ордена', 'Рог ледяного наследия', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12780, 'ИСПОРЧЕНО::Враг наших врагов', 'Вообще-то, мы не особенно жалуем рыцарей смерти, но сейчас мы не в том положении, чтобы быть слишком разборчивыми в выборе союзников.$B$BМы зажаты между силами Плети и свирепыми Драккари, причем и те, и другие пытаются нас уничтожить, чтобы пробиться друг к другу.$B$BИди на запад – на Черную заставу. Поговори со Стефаном и спроси, не нужна ли ему твоя помощь.', 'По поручению сержанта Рианны из Разлома Света поговорите со Стефаном на Черной заставе и предложите ему свою помощь.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12781, 'Добро пожаловать!', 'Добро пожаловать в World of Warcraft!$B$BВы приобрели коллекционное издание World of Warcraft и получаете в качестве благодарности этот подарочный сертификат. Отнесите его Банши Сиокси в Черный Оплот и получите подарок: маленького компаньона, который будет сопровождать вас на пути к приключениям и славе.$B$BЕще раз большое спасибо – и приятного пребывания в World of Warcraft!', 'Отнесите подарочный сертификат Черного Оплота в Черный Оплот и отдайте его Банши Сиокси.', '', NULL, NULL, NULL, 'Подарочный сертификат Черного оплота (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12782, 'Отчаянный поиск', 'Настал час, $N, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $N, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.', 'Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.', 'А, еще один подопытный для моих экспериментов! Признаться, в последнее время мы испытываем некоторую нехватку добровольцев. Так что, эльф... ты готов оправдать название своей расы? Отдашь ли ты свою кровь ради великой цели?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12783, 'Отчаянный поиск', 'Настал час, $N, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $N, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.', 'Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.', 'А, еще один подопытный для моих экспериментов! Признаться, в последнее время мы испытываем некоторую нехватку добровольцев. Нам пригодится новая кровь... особенно бурлящая от ярости.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12784, 'Отчаянный поиск', 'Настал час, $N, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $N, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.', 'Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.', 'А, еще один подопытный для моих экспериментов! Признаться, в последнее время мы испытываем некоторую нехватку добровольцев. Нам пригодится новая кровь... коей у тебя в избытке, здоровяк!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12785, 'Оргриммар', 'Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Оргриммар. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей анти-чумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Карлову. Ты найдешь его в доме вождя Тралла в Оргриммаре.', 'Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Карлову в Оргриммаре.', 'Превосходно! Обе эти чумы смертельно опасны, но нам ли сторониться смерти? Однажды, $N, ты поймешь, что разрушение – это единственный путь к спасению...', 'Добро пожаловать в Оргриммар, $N. Полагаю, тебя послал верховный аптекарь Гнилесс? Зараженный мозг у тебя с собой?', NULL, NULL, 'Разрываемый на части мозг (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12786, 'Громовой Утес', 'Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Громовой Утес. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей прото-чумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Чейни. Ты найдешь его в доме Магаты Зловещий Тотем в Громовом Утесе.', 'Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Чейни в Громовой Утес.', 'Превосходно! Обе эти чумы смертельно опасны, но нам ли сторониться смерти? Однажды, $N, ты поймешь, что разрушение – это единственный путь к спасению...', 'Добро пожаловать в Громовой Утес, $N. Полагаю, тебя послал верховный аптекарь Гнилесс? Зараженный мозг у тебя с собой?', NULL, NULL, 'Разрываемый на части мозг (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12787, 'Подгород', 'Будь благословенна трупная чума! Ты не поверишь, сколь ценные сведения о Плети мы получили, пытаясь изобрести вакцину от их заразы. Наши исследования привели к созданию оружия против них самих. Оружия и инструмента...$B$BВот, возьми эту голову зомби. Она была частично исцелена от чумы с помощью нашей последней разработки. Ее надо доставить аптекарю Фаранеллу для дальнейших опытов.', 'Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг опытному аптекарю Фаранеллу в Подгород.', 'Ах, какой прекрасный образец! Прелесть ты моя, что за видения возникают в твоем мозгу под влиянием двух великолепных штаммов чумы? Мы с тобой проведем много долгих, бессонных ночей за беседой, и я вытяну из тебя все мысли и знания, кусочек за кусочком.$B$BНе бойся, малыш! Сокрытые в тебе тайны стоят такой жертвы. Ты – великий дар всем Отрекшимся, предвестник новой эры, в которой мы завоюем уважение всех смертных этого мира. Ты займешь почетное место в истории...', 'Приветствую тебя, $N. Ты прибыл из Шаттрата? Тебя послал верховный аптекарь Гнилесс?', NULL, NULL, 'Разрываемый на части мозг (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12788, 'Луносвет', 'Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Луносвет. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей анти-чумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю $N. Ты найдешь ее в доме Лор\'темара Терона в Луносвете.', 'Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю $N в Луносвет.', 'Превосходно! Обе эти чумы смертельно опасны, но нам ли сторониться смерти? Однажды, $N, ты поймешь, что разрушение – это единственный путь к спасению...', 'Добро пожаловать в Луносвет, $N. Полагаю, тебя послал верховный аптекарь Гнилесс? Зараженный мозг у тебя с собой?', NULL, NULL, 'Разрываемый на части мозг (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12789, 'В Разлом!', 'Готовься, $C. Я отправляю тебя в Разлом Света, что к северо-востоку отсюда.$B$BЯ получил сообщение, что силы Плети из кожи вон лезут, чтобы захватить Зул\'Драк.$B$B<Валус не мигая смотрит вам прямо в глаза.>$B$BЭтого нельзя допустить.$B$BТы $gдолжен:должна: помочь в уничтожении сил Плети. Этого требует Свет.$B$B<Свободен:Свободна:.', 'По распоряжению рыцаря Валуса из Опоры Света доложите о своем прибытии сержанту Рианне из Разлома Света в Зул\'Драке.', 'Отлично. Должно быть, Валус получил мой отчет.$B$BЗа работу, $R.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12790, 'Как уйти и вернуться: магический путь', 'На всякий случай, если ты вдруг не знаешь... ты можешь использовать этот кристалл на платформе у меня за спиной, чтобы телепортироваться на Аметистовую заставу в лесу Хрустальной Песни у Даларана.$B$BТочно так же ты можешь использовать кристалл на развалинах, чтобы вернуться в комнату, расположенную прямо надо мной.$B$BМне бы очень хотелось, чтобы ты $gотправился:отправилась: в путь немедленно.', 'Воспользуйтесь кристаллом телепортации на Аметистовую заставу у Даларана и кристаллом телепортации в Даларан по просьбе верховного мага Селиндры из Даларана.', 'Замечательно, $C. Теперь ты знаешь, как попасть в лес Хрустальной Песни и вернуться обратно.', 'Я чувствую, ты еще не опробовал кристаллы.$B$BНу, ничего. Не спеши, подготовься, как следует.', NULL, NULL, 'Кристалл телепортации на Аметистовую заставу использован', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12791, 'Магическое королевство Даларан', 'Здравствуй, $N! Ты еще не $gслышал:слышала: о том, что Кирин-Тор перенес наш славный город сюда, в Нордскол?$B$BИстинная правда; Даларан больше не найти на берегах озера Лордамер. Теперь он волшебным образом парит над лесом Хрустальной Песни.$B$BПожалуй, ты уже $gготов:готова: совершить путешествие в наш город. Обратись ко мне, и я прочитаю заклинание телепортации.$B$BКак прибудешь на место, найди верховного мага Селиндру и передай ей мой перстень в знак того, что ты $gприбыл:прибыла: по моему поручению.', 'Отнесите кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана.', 'Отнесите Кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана.', 'Приветствую, $C.', NULL, NULL, 'Кирин-торский перстень (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12792, 'Первым делом', 'Слушай, $r!$B$BУ нас тут повсюду – один сплошной кризис. Куда ни глянь – нашим людям везде нужна помощь.$B$B<Кунц смотрит вам прямо в глаза.>$B$BНо конкретно на данный момент больше всех в помощи нуждается Рианна. Силы Плети заняли территорию между нами, и Рианна с ее отрядом оказалась отрезанной.$B$BРазлом Света, который удерживает Рианна, находится прямо на юго-западе отсюда.', 'По поручению командира Кунца помогите сержанту Рианне в Разломе Света.', 'Значит, мое донесение дошло до Кунца.$B$BЯ рада, что он жив-здоров.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12793, 'Дым на горизонте', 'Слышишь, $r?$B$BГрохот битвы далеко-далеко на западе слышен даже здесь, даже сквозь грохот нашей собственной битвы.$B$BСуществует реальная угроза, что силы Плети прорвут линию обороны тех, кто называет себя солдатами Серебряного Авангарда. Мы не должны этого допустить!$B$BИди в Разлом Света и помоги тем, кто сражается там. Поговори с Маакой, он обеспечит тебе безопасное путешествие.', 'По поручению Кхуфу из Зим\'Торги переговорите с сержантом Рианной в Разломе Света.Маака обеспечит вам безопасное путешествие.', 'Свет восторжествует!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12794, 'Магическое королевство Даларан', 'Здравствуй, $N! Ты еще не $gслышал:слышала: о том, что Кирин-Тор перенес наш славный город сюда, в Нордскол?$B$BИстинная правда; Даларан больше не найти на берегах озера Лордамер. Теперь он волшебным образом парит над лесом Хрустальной Песни.$B$BПожалуй, ты уже $gготов:готова: совершить путешествие в наш город. Обратись ко мне, и я прочитаю заклинание телепортации.$B$BКак прибудешь на место, найди верховного мага Селиндру и передай ей перстень в знак того, что ты $gприбыл:прибыла: по моему поручению.', 'Отнесите кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана.', 'Отнесите Кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана.', 'Приветствую, $C.', NULL, NULL, 'Кирин-торский перстень (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12795, 'На помощь заставе', 'Буквально пару секунд назад я заметила сигнальную вспышку над восточными лесами.$B$BЭто может означать только одно: у рыцарей Серебряной заставы что-то случилось, и явно что-то не очень приятное.$B$BЯ не могу бросить пост и уйти, $r, а ты можешь. При первой удобной возможности отправляйся туда, к командиру Фальштаву, и помоги им, чем сможешь.', 'По поручению Датуры Кровавой Розы поговорите с командиром Фальштавом на Серебряной заставе.', 'Да, нам нужна помощь, $C, так что ты можешь быть нам полезным.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12796, 'Магическое королевство Даларан', 'Здравствуй, $N! Ты еще не $gслышал:слышала: о том, что Кирин-Тор перенес наш славный город сюда, в Нордскол?$B$BИстинная правда; Даларан больше не найти на берегах озера Лордамер. Теперь он волшебным образом парит над лесом Хрустальной Песни.$B$BПожалуй, ты уже $gготов:готова: совершить путешествие в наш город. Обратись ко мне, и я прочитаю заклинание телепортации.$B$BКак прибудешь на место, найди верховного мага Селиндру и передай ей мой перстень в знак того, что ты $gприбыл:прибыла: по моему поручению.', 'Отнесите кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана.', '', NULL, NULL, NULL, 'Кирин-торский перстень (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12797, 'Назад по Связующей спирали', 'Ты говоришь правду, $r. Я чувствую, как сама сущность Низины Шолазар разрушается от тлетворного влияния нежити.$B$BЯ заключил свое естество в эту руну, $r. Отнеси руну той, что послала тебя сюда, ибо лишь ее сила позволит мне проникнуть в ее земли.', 'Принесите Аватаре Фрейи руну \"Омега\". Вы найдете Аватару в Низине Шолазар у водопадов Гласа Дождя.', 'Хорошо.$B$BГоре нашим врагам! Горе тем, кто служит Королю-личу и угрожает творениям $Nв, ибо Этимидиан уже здесь!', 'Ты вернулся, $N…', NULL, NULL, 'Руна \"Омега\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12798, 'Карты Новолуния: колода Мечей', 'Теперь, когда вы собрали все карты колоды Мечей, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$B$BВы чувствуете, что с помощью этой карты можно кого-то призвать.', 'Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Мечей.', 'Знай же, что карты таро пользуются большой популярностью на Ярмарке Новолуния, так что если тебе удастся собрать еще одну колоду – не стесняйся, обращайся к нам. Среди нас много успешных торговцев, так что без награды ты не останешься.', 'Гляжу, тебе удалось собрать всю колоду Мечей... Любопытно...', NULL, NULL, 'Колода Мечей (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12799, 'Сбор эктоплазмы', 'Говорили, что мы должны радоваться тому, что он придет именно к нам. Мол, он такой весь из себя замечательный, с ним так приятно общаться... $B$BВпрочем, выбора у меня все равно не было. Финкльштейн – лучший алхимик Ордена. Наверное, я должен гордиться тем, что он выбрал мою заставу в качестве места для своей лаборатории. Но как только он тут появился, я только и делаю, что собираю всякие алхимические ингредиенты.$B$BМожет быть, $r, ты мне поможешь? К югу отсюда лежат озера, где обитают духи древних троллей. Собери их эктоплазму и принеси ее мне.', 'Соберите 5 колб древней эктоплазмы от заблудших духов Драккари на озерах Жа\'Джина для капитана Арната из Хеб\'Валока.', 'Спасибо, $С.$B$BЭто сэкономит нам время, а время – дорого.', 'Добрый день, $R.$B$BТы собрал эктоплазму для Финкльштейна?', NULL, NULL, 'Древняя эктоплазма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12800, 'Приказ Короля-лича', 'Анклав Алого ордена пал, и жалкие остатки ордена не смогут оказать нам сопротивления в Нордсколе.$B$BТеперь настал час сокрушить Часовню Последней Надежды. Я не желаю больше терпеть присутствие этих мятежников!$B$BЯ подписал им смертный приговор. Командир Плети Таланор ожидает твоего прибытия возле лесопилки Бровача. Иди на северо-запад, через пещеру к Ядовитой поляне, от которой идет прямая дорога на лесопилку.$B$BНе подведи меня, $N.', 'Найдите Командира Плети Таланора у лесопилки Бровача.', 'Верховный лорд и его верные рыцари смерти готовы нанести удар! Скоро мы опустошим это место.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12801, 'Сияние Рассвета', 'Серебряный Рассвет оказал нам яростное сопротивление в Часовне Последней Надежды. Они осмелились противостоять могуществу Плети и теперь поплатятся за свою дерзость!$B$BМогучие армии Короля-лича готовы к решающей битве за Чумные земли. Сегодня мы покроем славой имена бессмертных рыцарей Плети!$B$B<Готов:Готова: ли ты стать $gодним:одной: из них? Обратись к верховному лорду Дариону Могрейну. Именно он отвечает за наступление на Часовню Последней Надежды.', 'Разбейте войска Серебряного Рассвета и найдите Сияние Рассвета.Если вам удастся выжить, доложите о своей победе верховному лорду Дариону Могрейну.', 'Нет для нас искупления, $N. Мы навеки обречены существовать в обличии чудовищ. Даже если Король-лич освободит нас от обязательств, призраки прошлого никогда не дадут нам жить спокойно. $B$BНам остается только следовать путем смерти и разрушений...$B$BТак войди же вместе со мной в Акерус и стань одним из рыцарей Черного Клинка. Вместе мы уничтожим Короля-лича и положим конец Плети.', '<Верховный лорд Могрейн кивает.>', NULL, NULL, 'Сияние рассвета найдено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12802, 'Мое сердце – в твоих руках', '$gГолос Дракуру проникает в ваш разум:$B$BЭй, $gдруг:подруга:! Какая потрясающая штука – этот глаз пророков! Я слежу за тобой с его помощью! Вижу, сердце уже у тебя в руках? Неплохо...$B$BДавай, неси его на мой пьедестал в Перевале Драк\'атала, что на востоке.$B$BТебе снова придется выпить мой эликсир!$B$BНа этот раз, подмешай в него немного настоя безнадеги!', 'Дракуру просит вас принести Сердце древних на его пьедестал в Перевале Драк\'атала.Но сначала вам надо будет собрать 5 настоев безнадеги – иначе эликсир не сработает.', 'Это впечатляет, дружище! Похоже, нас свела сама судьба.$B$BСкоро я отомщу моим братьям и очищу Драк\'Тарон, а ты получишь в награду его величайшее сокровище.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12803, 'Сила природы', 'Я не слишком уверен в том, что именно я видел, летя на северо-восток, но выглядело это как огромная женщина, легко расправляющаяся с силами Плети.$B$BЯ слыхал, как профессор говорила что-то о каком-то \"Хранителе Жизни\", которого – или которую – титаны назначили приглядывать за Шолазаром. Я, конечно, не спец по истории $Nв, но, судя по всему, она как раз подходит.$B$BЗнаю я и то, что если армия Плети перейдет границу между Затерянными землями и остальным Шолазаром, наша экспедиция, считай, мертва. Что скажешь – может, пойдешь поищешь ее и предложишь ей руку помощи?', 'Отправляйтесь на Увядшую поляну, расположенную между водопадами Гласа Дождя и Затерянными землями и найдите Аватару Фрейи.', 'Ты не принадлежишь этой земле. Но и Плети ты тоже не принадлежишь.$B$BЧто же мне делать с тобой?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12804, 'Стейк, достойный охотника', 'Иногда нет ничего хуже, чем целый лагерь охотников. Они все настолько заняты добычей, что не заботятся о еде, и все, что я получаю – жесткое и жилистое мясо… Навряд ли тебе хотелось бы получить такую пищу после целого дня, проведенного на охоте, верно?$B$BПо счастью, неподалеку отсюда можно добыть прекрасное мясо, нежное и сочное. К югу от лагеря, на том берегу реки обитают длинношеие травояды. Для наших голодных усталых охотников они стали бы отличной едой. Принеси мне лучшие куски мяса, и мы устроим нашим товарищам настоящий пир!', 'Принесите Коргу Тесаку в лагерь Эрнестуэя 5 стейков из длинношеего травояда.', 'Вот это я понимаю! Вот это мясо! Если в том, что мы потерпели кораблекрушение, и есть что-то хорошее, так это то, что мы избавлены от солонины на ближайший месяц! Еще раз благодарю тебя, $N!', 'Удалось тебе добыть мясо?', NULL, NULL, 'Стейк из длинношеего травояда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12805, 'Сохранение жизненной силы', 'Колонна жизненной силы обрушилась и спровоцировала подъем глубинных слоев грунта к поверхности .$B$BЭлементали, бродящие у одного из осколков колонны, носят в себе ту жизненную силу, что наполняла колонну энергией. Я не допущу, чтобы эта энергия пропала просто так, ведь осталось всего четыре колонны.$B$BОтправляйся к Одинокому осколку на юго-восток и поищи элементалей жизненной силы.$B$BИспользуй самоцвет жизненной силы на их останках, чтобы собрать пульсирующую в них энергию. Она нужна нам, чтобы залечить раны этой земли, когда испытания будут позади.', 'По просьбе Фрейи отправляйтесь к Одинокому осколку на юго-восток и примените самоцвет жизненной силы к 8 уничтоженным элементалям жизненной силы.', 'Спасибо, $N. Очень жаль, что колонна была разрушена, но мы должны собрать все, что сможем.', NULL, NULL, NULL, 'Собрано энергии жизненной силы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12806, 'На Уступ Смерти со всех ног!', 'Кто-то считает, что наша основная задача – это не война с Королем-личом, а полное уничтожение Алого Натиска. С моей точки зрения, это та еще глупость. Но кто я такой, чтобы судить о подобных делах?$B$BДалеко на юго-запад отсюда находится Уступ Смерти – большая скала, возвышающаяся над морем среди других скал. Там ты найдешь лорда-командира Арета, который лично командует уничтожением Натиска.$B$B<Барон прочищает горло.>$B$BСтупай к нему побыстрее. Он спрашивал о тебе лично.', 'Отправляйтесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.', 'Ну, наконец-то! Барон Раздор, я вижу, не особо спешил отправить тебя ко мне.$B$BНадо было давно отрубить ему голову! Вернее, этот пустой котелок у него на плечах!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12807, 'Немного истории...', 'Нам еще многое предстоит сделать, но сначала, я думаю, нужно вспомнить немного истории.$B$BУ нас, рыцарей смерти, в прошлом было много неприятностей с нашими Алыми друзьями, которые сейчас так неосмотрительно расположились со всеми удобствами в бухте под нами, на западе.$B$BКогда приготовишься выслушать мою историю, приходи, и я все расскажу.', 'Выслушайте рассказ лорда-командира Арета на Уступе Смерти.', 'То ли по глупости, то ли по недальновидности, Серебряный Авангард предпочел не замечать присутствия Алого Натиска. Но мы будем действовать по-другому.$B$BНам все равно, даже если они вдруг решат помогать нам в войне против Короля-лича. Мы искренне верим, что они недостойны топтать эту землю. И мы уничтожим их – раз и навсегда!', 'Думаешь, ты готов продолжить? Это не так... Ты еще не дослушал мою историю до конца!', NULL, NULL, 'История лорда-командира Арета выслушана.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12808, 'Вынужденный союз', '$gОтважный:Отважная: $N, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, сможем мы выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $N.', 'Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.', 'Сестра моя, я так горда быть рядом с тобой в эти дни скорби. Да благословят тебя небеса, и будем надеяться, что твой блестящий ум проложит нам путь к спасению...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12809, 'Стальгорн', 'Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $N. Охраняй ее как зеницу ока и доставь в Стальгорн в целости и сохранности. Главный механик Меггакрут будет счастлив пустить этот артефакт в дело.', 'Епископ Лазарил просит вас отнести заряженный Светом артефакт главному механику Меггакруту в Стальгорн.', 'Какая мощь! Этот предмет заключает в себе столько Света, что не измерить ни одним прибором! Ох, я уже предвкушаю, как можно было бы его использовать... Хо-хо! Как насчет антисумеречного фото-дисперсионного геноактиватора, который обратит вспять ход дня и ночи? Да Плеть даже не поймет, что стерло ее с лица земли в мгновение ока!', 'Здравствуй, $N! Ну, ты только посмотри! Со момента нашей прошлой встречи ты продросла ровно на одну целую семьдесят три микроспана! Не иначе, это благотворное влияние ветров Запределья так сказалось на твоем здоровье!', NULL, NULL, 'Заряженный светом артефакт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12810, 'Кровавая вода', 'Отряды противника в бухте Алого Натиска укреплены всадниками на грифонах. Для того чтобы их победить, тебе тоже нужен летучий \"скакун\". Но для начала необходимо добыть компоненты для специального ритуала, который поможет нам осуществить этот замысел.$B$BДля ритуала нужна кровь. Много крови.$B$B<Лорд-командир указывает вниз, на запад.>$B$BНо в бухте ее в избытке. Я имею в виду акул... Ступай туда и не возвращайся, пока не наберешь полный бурдюк их крови.', 'Соберите кровь 10 прожорливых акул в бурдюк для крови и принесите его лорду-командиру Арету на Уступ Смерти.', 'Отлично сработано. Ты пока немного обсохни, а потом мы продолжим.', NULL, NULL, NULL, 'Собрано крови прожорливых акул', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12811, 'Отчаянный поиск', 'Настал час, $N, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $N, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.', 'Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.', 'А, еще один подопытный для моих экспериментов! Признаться, в последнее время мы испытываем некоторую нехватку добровольцев. Нам пригодится новая кровь... особенно такая чистая!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12812, 'Оргриммар', 'Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Оргриммар. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей анти-чумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Карлову. Ты найдешь его в доме вождя Тралла в Оргриммаре.', 'Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Карлову в Оргриммар.', 'Превосходно! Обе эти чумы смертельно опасны, но нам ли сторониться смерти? Однажды, $N, ты поймешь, что разрушение – это единственный путь к спасению...', 'Приветствую тебя, $N. Ты прибыл из Шаттрата? Тебя послал верховный аптекарь Гнилесс?', NULL, NULL, 'Разрываемый на части мозг (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12813, 'Из праха восстаньте!', 'Какой он добрый... какой благородный... наш лорд-командир. Весь такой солнечный, ясный, как летний день, а в моем сердце – лишь черная ненависть.$B$BМне мало просто лишить их жизни... я хочу их унизить... смешать их с грязью!$B$BЧто может быть хуже и гаже, чем быть превращенным в то, что тебе ненавистно?! Посвятить всю свою жизнь искоренению скверны, а под конец в нее же и превратиться!$B$BЭто печально и страшно.$B$BОтнеси эту настойку на запад, в бухту Алого Натиска. Окропи ею тела мертвых и посмотри, что будет. Только не суйся в собор.', 'Возьмите настойку Темной Целительницы, которую дала вам Сетаал Темная Целительница на Уступе Смерти, и окропите тела любых 10 бойцов Алого Натиска, которых найдете.', '<Рыцарь смерти холодно смотрит на вас. Ее глаза мертвы, как надгробные камни.>$B$BЗавтра мне приготовят еще одну порцию настойки. Итак, я прощаюсь с тобой до завтра.', NULL, NULL, NULL, 'Окроплено тел бойцов Алого Натиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12814, 'Потребность в грифоне', 'А что, это было бы здорово: забрать у них одного из грифонов и использовать против них же! Отправляйся в бухту Алого Натиска и добудь одного грифона. Скажем так, вырви поводья из мертвых рук его всадника.$B$BКогда вернешься сюда, отведи грифона к Узо Призывателю Смерти. Он позаботится о его надлежащей трансформации и даст тебе дальнейшие указания.', 'Отведите грифона Алого Натиска к Узо Призывателю Смерти на Уступ Смерти.', 'Да, должно получиться неплохо!$B$BОтойди-ка в сторонку... сейчас я начну кровавый ритуал!', 'Чего ты так долго? У них такие медлительные грифоны? Ладно, мы это исправим!', NULL, NULL, 'Грифон Алого Натиска доставлен к Узо Призывателю Смерти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12815, 'Закрытое воздушное пространство', 'Теперь, когда у тебя есть свой костяной грифон, ты будешь летать туда каждый день. Очисти небо над бухтой Алого Натиска.$B$BСкажу тебе прямо: мне все равно, как ты это сделаешь. Но сдается мне, если ты избавишь нас от общества наездников, то тебе будет проще, гораздо проще.$B$BК тому же, твой костяной грифон, он, знаешь ли, много чего умеет. И эти умения тебе пригодятся.', 'Убейте 10 всадников на грифонах из Алого Натиска по распоряжению Узо Призывателя Смерти с Уступа Смерти.', 'Вот это выдержка, я понимаю! Но мне нужно, чтобы ты поднимался в воздух каждый день, пока мы находимся здесь.$B$BНадеюсь, завтра ты тоже придешь. Твой костяной грифон будет ждать.', 'Уже вернулся? Так быстро? Почему тогда небо над бухтой кишит грифонами?!', NULL, NULL, 'Всадник на грифоне из Алого Натиска убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12816, 'Нападение Плети на Луносвет', 'Армия нежити Короля-лича уже стоит у наших ворот. Мы не должны оставаться в стороне! Долг каждого солдата – защищать Луносвет от проклятых захватчиков до последней капли крови!$B $BВидишь эти странные рунические круги вокруг лагеря? Они пропитаны той же энергией, что окружает нежить и Некрополь. Ты $gдолжен:должна: выяснить, что они обозначают. Подойди к ним поближе, очисть местность от мерзких созданий Плети и приступай к исследованиям. И не забудь – я достойно вознагражу тебя за результаты, равно как и за доказательства твоей победы над Плетью. Иди же, не медли!', 'Соберите три тусклых Некротических камня Плети, которые носит при себе нежить, откружившая Луносвет, и исследуйте светящиеся рунические круги вблизи лагеря Плети.', 'Хм... Судя по тому, что ты мне поведал, голоса, доносящиеся из этих кругов... служат своего рода связью между отрядами. Страшно подумать, что за извращенный разум может создать магию такого рода. Хорошо, что ты вернулся целым и невредимым. Твои услуги еще понадобятся Серебряному рассвету.', 'Ты уже выяснил, связь между нападением Плети и светящимися кругами? Сейчас каждая секунда на счету!', NULL, NULL, 'Тусклый некротический камень', 'Осмотреть круг', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12817, 'Нападение Плети на Экзодар', 'Армия нежити Короля-лича уже стоит у наших ворот. Мы не должны оставаться в стороне! Долг каждого солдата – защищать Экзодар от проклятых захватчиков до последней капли крови!$B $BВидишь эти странные рунические круги вокруг лагеря? Они пропитаны той же энергией, что окружает нежить и Некрополь. Ты $gдолжен:должна: выяснить, что они обозначают. Подойди к ним поближе, очисть местность от мерзких созданий Плети и приступай к исследованиям. И не забудь – я достойно вознагражу тебя за результаты, равно как и за доказательства твоей победы над Плетью. Иди же, не медли!', 'Соберите три тусклых некротических камня созданий Плети, бродящих вокруг Экзодара, и изучите светящиеся рунические круги вокруг лагеря, после чего вернитесь к лейтенанту Крегору.', 'Хм... Судя по тому, что ты мне поведала, голоса, доносящиеся из этих кругов... служат своего рода связью между отрядами. Страшно подумать, что за извращенный разум может создать магию такого рода. Хорошо, что ты вернулась целой и невредимой. Твои услуги еще понадобятся Серебряному рассвету.', 'Ты уже выяснила, связь между нападением Плети и светящимися кругами? Сейчас каждая секунда на счету!', NULL, NULL, 'Тусклый некротический камень', 'Осмотреть круг', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12818, 'Сбор деталей', 'Давай сразу к делу... Рикет попросила меня собрать несколько мощных наземных мин, но у меня не хватает деталей.$B$BСразу за городом, на западе, ты найдешь обломки наших последних реактивных саней... Рикет слегка увлеклась, когда их заправляла. Хотя, наверное, я тоже не без греха: не надо было подносить насадку так близко к выхлопной трубе. Что ж поделать, век живи – век учись!$B$BТам, наверное, валяется много вполне еще годных деталей... вокруг раскуроченных саней... сходи туда, разгони всех мародеров и собери мне побольше деталей.', 'Принесите Глуму Свечекруту в К-3 10 деталей из обугленных обломков.', 'Да, эти сгодятся. Спасибо!$B$BТы, случайно, не видел Дима? Я отправил его с поручением уже давно, но он до сих пор не вернулся. Надеюсь, с ним все в порядке.$B$BКстати, о птичках... а где Янкс, интересно...', 'Нужно придумать какое-нибудь устройство, чтобы двигатели не глохли на таком жутком холоде... думай, Глум, думай!$B$BДа, кстати! Ты принес мне детали?', NULL, NULL, 'Обугленные обломки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12819, 'Плевое дело', 'Вот черт! Где мои инструменты? Они же вот только что были здесь.$B$BО! Наверное, я их забыл на минном поле к западу отсюда. М-да, приятного мало... Слушай, я буду очень тебе благодарен, если ты их заберешь. Только ты там осторожнее! Смотри под ноги! Там везде мины. Тебе нужно будет пройти в точности там же, где проходил я.$B$BДа, и еще одно... не пытайся добраться туда по воздуху. Не знаю, что на меня нашло, но я установил пушки, которые палят по всему, что летает. И они, как ты понимаешь, не разбираются, кто там летит и зачем.', 'По поручению Глума Свечекрута из К-3 принесите инструменты Свечекрута с минного поля.', 'Ха-ха! Да, это они! Большое спасибо. Надеюсь, ты там не сильно упарился, пробираясь по минному полю.', 'Если бы тут был Янкс, я бы поручил это ему.. Кстати... я тут подумал... кажется, я не сказал ему, где безопасный проход.$B$BТак что это большая удача, что ты к нам зашел.', NULL, NULL, 'Инструменты Свечекрута', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12820, 'Осторожное прикосновение', 'Я целую вечность ждала эти мины! Ну, как минимум, несколько дней. Чего он так долго?!$B$BТут, понимаешь, какое дело... тут поблизости бродит свирепая банда магнатавров – ну, знаешь, такие... огромные, волосатые, страшные, как смертный грех, и, похоже, они собираются захватить К-3!$B$BТолько у них ничего не получится.$B$BМы построили несколько защитных сооружений на северо-востоке отсюда. Но вот незадача: у наших лазерных пушек очень слабые источники питания. Вот тут-то нам и пригодятся мины! Отправляйся туда и задай жару этим уродам!', 'Рикет из К-3 просит вас воспользоваться усовершенствованными противопехотными минами на Побоище Гарма, чтобы оттеснить 12 противников: захватчиков из Гарма или последователей с Холмов Снежной Слепоты.', 'И вот сижу я тут... вся такая красивая и величественная, и вдруг слышу взрыв вдалеке! И еще! И еще! И еще добрую дюжину! А я сижу и улыбаюсь при мысли о том, что магнатавры и снобольды сами лезут на верную гибель.$B$BЭто поистине великолепно!', NULL, NULL, NULL, 'Убито бойцов Гарма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12821, 'Танго в тюремном блоке', 'Саперная команда готова! Что это значит? Это значит, что скоро будет веселье!$B$BМы бы уже прямо сейчас атаковали Гарм, но есть одно маленькое препятствие! Я отправила гонца установить телепортер сразу за Гармом – и, кстати, он его установил, а затем вернулся за батареей, чтобы активировать телепортер. Портал до сих пор не работает... что означает, что батарею до него не донесли.$B$BМне нужно, чтобы ты $gотправился:отправилась: на Побоище Гарма и $gразыскал:разыскала: батарею. Используй ее для активации телепортера на востоке Гармова Холма.', 'По поручению Рикет из К-3 разыщите батарею для телепортера и с ее помощью активируйте площадку телепортера у Подъема Гарма.', 'Отлично!$B$B<На лице Рикет появляется свирепая ухмылка.>$B$BСейчас мы им покажем, почем фунт лиха!', 'Даже магнатавру должно быть понятно, что с гоблинами лучше не связываться.', NULL, NULL, 'Батарея для телепортера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12822, 'Средство для устрашения', 'Теперь, когда у нас открыт телепорт, мой план усложнился... его воплощение потребует безукоризненной точности во всем. И нам еще надо собрать провиант! И набрать новых солдат! Работы явно не на одну неделю!$B$BВ общем так, $gмалыш:девочка:, проходи через телепорт и задай жару этим уродам! Наши саперы тебя прикроют... им все равно будет некуда отступать.', 'По заданию Рикет из К-3 убейте 6 дозорных Гарма и 8 приверженцев с Холмов Снежной Слепоты.', 'Ха-ха! Теперь эти скоты будут знать, как отнимать у нас время! Отныне и впредь зеленая кожа будет наводить страх и ужас на всех магнатавров!', NULL, NULL, NULL, 'Дозорный Гарма убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12823, 'Безупречный план', 'Ну, здравствуй! Как я понимаю, ты хочешь присоединиться к нашему отряду?$B$BУ меня для тебя есть задание... мы собираемся обрушить на них всю пещеру! В самом дальнем конце пещеры располагается алтарь Хладонутра. Тебе нужно к нему подобраться и положить где-нибудь рядом этот надежно перевязанный сверток со взрывчаткой.$B$BКогда положишь заряд, убедись, что Хладонутр его схватил, а потом сразу беги на выход! Неизвестно, сколько продержатся своды пещеры, когда оно там рванет!', 'Джино у Подъема Гарма просит вас положить надежно перевязанный сверток со взрывчаткой у алтаря Хладонутра, убить Тормара Хладонутра и выбраться из пещеры до того, как она обрушится.', 'Вся гора вздрогнула! Зрелище, согласись, впечатляющее, да? Иначе и быть не могло!$B$BА в Лиге изобретателей говорят, будто все мои изобретения только и делают, что постоянно взрываются. Да! Взрываются! И неслабо взрываются, я вам скажу! Ха-ха-ха!', 'Этот сверток со взрывчаткой – мое детище... я доводил его до ума не одну неделю. НЕ ОДНУ НЕДЕЛЮ!$B$BА это долго... да, долго.', NULL, NULL, 'Подложить сверток со взрывчаткой', 'Надежно перевязанный сверток со взрывчаткой', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12824, 'Выдающийся подрывник', 'А ты быстро бегаешь, $gприятель:подруга:! Спасибо за помощь со взрывами... Я давно ждал возможности испытать свои изобретения в деле!$B$BИди скажи Рикет, что теперь магнатавров опасаться не приходится: мои саперы этих гадов повычистят!$B$BИ еще раз спасибо!', 'Возвращайтесь к Рикет в К-3.', 'Ты подорвал всю пещеру? Неплохо! Джино, наверное, от радости пляшет.$B$BМы благодарны тебе за помощь, Совух. Прими этот маленький сувенир в знак признательности.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12825, 'Выражение благодарности', '', '[PLACEHOLDER] Используйте мини-самолет с камикадзе на вождя гноллов.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12826, 'Почти безопасны', 'Красота!$B$BНет, не ты, а мои новые мины. Я – гений, да! Истинный гений. Ничто не сравнится с моим интеллектом.$B$BТак о чем мы с тобой говорили? А, да! О моих новых минах! Новая, усовершенствованная модель... готовая к испытанию в деле. Рикет будет довольна.$B$BСлушай, будь $gхорошим мальчиком:хорошей девочкой:, отнеси эти мины Рикет, хорошо? Это будет поистине эпическое путешествие... Только ты с ней осторожнее. Она, конечно, хорошая, но малость с приветом.', 'Отнесите усовершенствованные противопехотные мины Глума Рикет в К-3.', 'Симпатичные взрывные устройства. Правда, они милые?', 'Глум доделал свои мины? Отлично.', NULL, NULL, 'Усовершенствованная противопехотная мина (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12827, 'Пополнение запасов провизии', 'Эй, ты! Ты что, $gновенький:новенькая:? Не хочешь помочь Рикет?$B$BУ нас тут возникла одна неожиданная проблема... нехватка продовольствия. Да, я все понимаю... о пополнении запасов надо заботиться заранее, но тут, понимаешь, какое дело... Мы с нашей саперной командой как-то вот не рассчитывали застрять здесь надолго. Да и народу у нас прибавляется постоянно. Похоже, старый добрый К-3 становится весьма популярным местом.$B$BКак решить эту проблему? К западу отсюда есть несколько лагерей гноллов... так вот, у них с продовольствием все в порядке. Не возьмешься стащить у них провиант?', 'По заданию Рикет из К-3 стащите 16 сухих пайков гноллов из ближайшего лагеря свирепых гноллов холмов.', 'Надеюсь, они не очень на нас обидятся. Мы же не обижаемся, когда они роются в нашем мусоре.', 'Ну что, как успехи? А то у меня уже в животе урчит...', NULL, NULL, 'Сухой паек гноллов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12828, 'Полет вдохновения', 'Фу! Ну и гадость! Может, для гноллов оно и вкусное, но нашим нужно что-нибудь более... съедобное.$B$BЛадно, попробуем подойти творчески...$B$BТора установила взрывной распределитель к северу от города... это неподалеку от входа в большую пещеру, ты его сразу увидишь. Эти штуки, как я понимаю, нужны для каких-то горнодобывающих работ, но у меня есть идея! Возьми бомбу из распределителя и грохни мамонта. Они обитают на западе. Возьми мясо и принеси его нам.', 'По просьбе Рикет из К-3 возьмите УРВР, убейте мамонта и принесите в К-3 8 больших кусков мяса мамонта.', 'Все получилось! Все-таки я очень умная, да!$B$BБольшое спасибо!', 'Я знала, что это был гениальный план!$B$BКак, вообще, ощущения в присутствии величия и мощи? Небось, поджилки трясутся, а?', NULL, NULL, 'Большой кусок мяса мамонта', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12829, 'Перед тем, как входить', 'Привет! Меня зовут Тора. Я возглавляю горные работы здесь, на К-3... ну, или буду возглавлять в ближайшее время!$B$BЭта пещера так и кишит всякими ползучими гадами. Думаю, нам бы надо избавиться от пауков перед тем, как туда вселяться... А ты как считаешь?', 'По заданию Торы Громыхалы у пещеры Хрустальной Паутины убейте 12 пауков в этой пещере.', 'Ха-ха! Работенка, конечно же, грязная, но ты неплохо с ней справился!$B$BБольшое спасибо, дружище!', NULL, NULL, NULL, 'Пауки Хрустальной Паутины убиты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12830, 'Изъятие руды', 'Мы идем дальше!$B$BКогда мы только пришли, здесь было несколько снобольдов... но их шахтерские работы, похоже, шли не особенно успешно. Несчастные случаи, травмы на производстве... Так что мы быстро отбили шахту.$B$BЯ послала туда нескольких рудокопов, чтобы они принесли мне образцы руды, которые можно использовать для точной настройки наших машин, но они до сих пор не вернулись.$B$BМожет быть, сходишь туда и принесешь мне образцы руды? Наверняка они есть у снобольдов, хотя я очень надеюсь, что большинство из них мы перебили.', 'По просьбе Тор Громыхалы у пещеры Хрустальной Паутины соберите 5 образцов нечистой саронитовой руды.', 'Фу! Ну там и воняет! Как я понимаю, ты все же столкнулся со снобольдами, да?$B$BНо ты замечательно справился!', 'Ты принес мне руду?', NULL, NULL, 'Нечистая саронитовая руда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12831, 'Ядовитый укус', 'Ой... у меня все внутренности раздирает так, будто там в животе – пропеллер.$B$BИдти я, наверное, смогу, но после того, как меня укусила та пакость в глубине пещеры, мне как-то нехорошо... Эта тварь была больше других пауков... и с яркой раскраской.$B$BРикет, может быть, и сумеет приготовить противоядие, но для этого ей понадобится ядовитая железа той твари, которая меня укусила. Может, найдешь эту пакость?$B$BА я пока поиграю с пауками в мертвого гоблина и, будем надеяться, они оставят меня в покое.', 'Принесите раненому гоблину-рудокопу в пещере Хрустальной Паутины ядовитую железу ледяного ползуна.', 'Вот спасибо... Надеюсь, Рикет сможет сделать мне противоядие. А теперь уходим отсюда! Скорее!', '<Раненый гоблин-рудокоп корчится от боли.>', NULL, NULL, 'Ядовитая железа ледяного ползуна', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12832, 'Побег', 'Вот спасибо! А мне уже стало страшно, что пойду на закуску какому-нибудь пауку. Впрочем, что это я болтаю? Надо скорее смываться из этого мрачного места!$B$BКогда будешь $gготов:готова: идти, сразу свисти... и пойдем уже, а?', 'Проводите раненого гоблина-рудокопа из пещеры Хрустальной Паутины в К-3, а потом поговорите с Рикет.', '', NULL, NULL, NULL, 'Проводите раненого гоблина-рудокопа в К-3.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12833, 'Излишки', 'Привет еще раз! Что, не захотелось сбежать, как это сделали все остальные? Ну, так ты просто лапочка, да? Я уж начала было думать, что от меня дурно пахнет или еще что!$B$BНам не помешала бы еще кое-какая помощь, а у тебя как раз есть необходимый опыт. Помнишь тех магнатавров? Ну, тут такое дело – пещера-то не полностью обвалилась... кое-кто там все-таки остался. И для Джино этих \"кое-кого\" многовато, понимаешь?$B$BК счастью, Глум мин наделал – мало не покажется. Ну, ты же понимаешь?..', 'Рикет из К-3 просит вас воспользоваться усовершенствованными противопехотными минами на Побоище Гарма, чтобы оттеснить захватчиков из Гарма и последователей с Холмов Снежной Слепоты.', 'Ты мне нравишься. Я бы сказала, ты просто супер!$B$BУра тебе!', NULL, NULL, NULL, 'Убито захватчиков Гарма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12834, 'Ни дождь, ни снег, ни катастрофа', '', '[PLACEHOLDER] Испытайте всепогодный бомбардировщик на великане.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12835, 'Все взрослые', '', '[PLACEHOLDER] Испытайте взрослого йормунгара на великане.', '', NULL, NULL, NULL, 'Дозорный Гарма убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12836, 'Выражение благодарности', 'Я знаю работку как раз для ретивого новичка! У нас тут проблема с гноллами возникла... можно сказать, все вокруг просто кишит этими мерзкими тварями. Их все больше и больше, теперь они уже вообще у нас на пороге, таскают наши запчасти! Просто ужас.$B$BВсем от начала и до конца заправляет их самонадеянный вожак, Кривошерст. Вот, кстати, насчет \"конца\"... нанеси-ка ему визит в лагерь – далеко на западе, в холмах Снежной Слепоты.$B$BИ когда я говорю \"нанеси ему визит\" – я говорю это вместо \"жестоко убей его\". Дошло? Вперед!', 'По заданию Рикет из К-3 убейте Кривошерста.', 'Чудесно! Такой $R, как ты, мне нравится – мой типаж.', 'Мне нравится Рикет – она тааааакая сладенькая!$B$BОй, привет еще раз! Как проходит дегноллизация?', NULL, NULL, 'Кривошерст убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12837, 'У Тор есть все, что надо', '', '[PLACEHOLDER] Явиться к Тор.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12838, 'Сбор информации', 'Мне нужно знать, что затевает Алый Натиск. И ты мне в этом поможешь.$B$BЛети в бухту Алого Натиска и обыщи их багажные сундуки. Ищи бумаги и документы. Сундуки будут заперты, так что тебе надо будет добыть ключи у бойцов Алого Натиска. Добыть любой ценой!', 'Соберите 5 донесений разведки Алого Натиска по заданию Аурока Мрачного Проклятия с Уступа Смерти.', 'Давай сюда все бумаги. Я их разберу и, если найду что-то важное, я тебя позову.$B$BВ любом случае, приходи завтра. Они, как известно, меняют планы чуть ли не ежедневно.', 'Ты собрал донесения?', NULL, NULL, 'Донесения разведки Алого Натиска', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12839, 'Грандиозные планы верховного адмирала', 'На первый взгляд эта записка мало чем отличается от остальных разведданных, но при внимательном прочтении становится ясно, что здесь содержатся действительно важные сведения.$B$BСудя по этому письму, верховный адмирал Вествинд находится где-то на острове, в тайном укрытии. Он говорит о великих и славных днях, которые наступят уже совсем скоро, когда воины Алого Натиска сокрушат Короля-лича, а потом и весь мир, и в Азероте наконец установится порядок.$B$BНадо показать это письмо лорду-командиру!', 'Отнесите письмо верховного адмирала лорду-командиру Аретy на Уступ Смерти.', 'Письмо, написанное Вествиндом? Так бы сразу и сказал!$B$B<Арет вырывает письмо у вас из рук и читает.>$B$BИдиот! Он действительно здесь?!$B$B<Лорд-командир смеется.>$B$BЭто новая информация. Интересно, и как он себе представляет завоевание мира после победы над Королем-личом? Разве что только в мечтах. Да и то у него вряд ли хватит на это воображения!', 'Данные по Алому Натиску надо доставить Ауроку Мрачному Проклятию.$B$B<Лорд-командир выразительно смотрит на вас, давая понять, что вы можете идти.>', NULL, NULL, 'Записка верховного адмирала (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12840, 'Совершенно секретно', 'Если кто-то и знает, где сейчас адмирал, так это его капитаны на судах в бухте Алого Натиска.$B$B<Лорд-командир потирает руки.>$B$BЕсли память меня не подводит, их зовут Вельсингтон и Хартфорд. Выбей из них информацию, а потом убей обоих.$B$BМне нужно знать, где верховный адмирал!', 'Выбейте информацию из капитанов Вельсингтона и Хартфорда, убейте обоих и возвращайтесь к лорду-командиру Арету на Уступ Смерти.', 'Они воскресили Ландгрена? Он наверняка должен знать, где верховный адмирал!', 'Где верховный адмирал Вествинд?', NULL, NULL, 'Капитан Вельсингтон выдал тайные сведения и был убит', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12841, 'Сделка с Каргой', 'Да, должно быть, ты ищешь этого зеленого пленника... Наверное, мы сможем друг другу помочь.$B$BСилой ты гоблина не отобьешь. По крайней мере, живым.$B$BМеня зовут Ирквинн, я мастер иллюзий. Как ты видишь, хильды держат меня в плену.$B$BЕсли ты сможешь добыть мои руны и принести их мне, я сделаю так, что ты пройдешь $gнезамеченным:незамеченной:, куда захочешь. Иди дальше вглубь шахты, там ты найдешь надзирательницу по имени Сира. Мои руны сейчас у нее. Принеси руны мне, и мы обсудим, что делать дальше.', 'По просьбе Лок\'лиры Карги принесите ей в Заброшенный рудник руны Ирквинн, отобрав их у надзирательницы Сиры.', 'У меня не было твердой уверенности, что ты вернешься. Мне страшно даже представить, что могло бы со мной приключиться, если бы я тут осталась еще на какое-то время.', 'Мои руны, $N? Они у тебя?', NULL, NULL, 'Руны Ирквинн', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12842, 'Ковка рун: подготовка к битве', 'Твоя душа отмечена знаком войны, рыцарь смерти. Ты $gобучился:обучилась: темному искусству рунической ковки, и теперь можешь наполнять энергией рун свое оружие.$B$BТеперь настало время подготовиться к битве. Отправляйся к одной из рунных кузней в Сердце Акеруса и нанеси могущественную руну на свой клинок!$B$BВозвращайся ко мне, когда твой меч наполнится темной энергией.', 'Инструктор Разувий из Черного оплота приказал вам выгравировать любую руну на вашем руническом клинке души.Выбранную гравировку можно заменить в любой момент, воспользовавшись ближайшей кузней рун.', 'Запомни, рыцарь смерти: кузня рун – это инструмент Плети. Найти его можно только в Акерусе, Наксрамасе и в самом сердце Ледяной Короны! Только с помощью рунической кузницы можно наносить гравировку на твое оружие.$B$BНе забывай покрывать рунами любой клинок, которым ты владеешь. Рыцарь смерти должен быть готов к любым опасностям, которые встретятся ему на пути!', 'Не трать, время зря, $N. Наш мир стоит на пороге апокалипсиса!', NULL, NULL, 'На оружие нанесены руны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12843, 'Они забрали наших мужчин!', 'Нам нужна твоя помощь! Мы как раз направлялись в горы, чтобы установить башню-передатчик, но по дороге на нас напали...$B$BВроде бы врайкулы, только кожа у них была голубая и как будто заиндевевшая... и среди них не было ни одного мужчины. Одни женщины! Они забрали всех наших мужчин, а нас, женщин, отпустили. Пожалуйста, $N! У нас есть подозрение, что их держат в Сифрельдаре – деревне, расположенной прямо над К-3.', 'По просьбе Гретхен Искрошип отправляйтесь в деревню Сифрельдар и спасите 5 плененных гоблинов.', 'У тебя получилось! Наши мальчики вернулись!', NULL, NULL, NULL, 'Освобождено пленных гоблинов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12844, 'Вернуть оборудование', 'Пожалуйста, $N, помоги нам. Когда хильды забрали наших мужчин, они забрали и все оборудование. Разумеется, самое главное, это спасти наших ребят, но, если ты вдруг случайно увидишь что-нибудь из нашего оборудования, постарайся забрать его и вернуть нам.$B$BИх деревня находится прямо над нами, на севере.', 'По просьбе Гретхен Искрошип принесите ей 8 предметов из снаряжения К-3, которые вы найдете в деревне Сифрельдар к северу от K-3.', '', NULL, NULL, NULL, 'Оборудование К-3', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12846, 'Найти всех до единого...', 'Все наши ребята вернулись... благодаря тебе, $N! Все... кроме одного.$B$BМой брат Зив не вернулся. Похоже, у них там какой-то рудник есть, где они держат пленников и заставляют их работать. Иди туда и попытайся что-нибудь разузнать.', 'Разыщите вход в Заброшенный рудник на севере деревни Сифрельдар и попробуйте выяснить, где может быть Зив Искрошип.', 'Ты явно не хильда... тогда что ты здесь делаешь? А... ты, наверное, ищешь нового пленника!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12847, 'Второй шанс', 'Я слышал, что у них в соборе есть какой-то архиепископ, но я не знал, что это воскрешенный и повышенный в чине Ландгрен! У Багрового собора всего один вход, он же выход, и его хорошо охраняют, так что $gодин:одна: ты не справишься.$B$BМы по-прежнему не знаем, где верховный адмирал, но на этот раз мы будем действовать наверняка!$B$BВозьми это устройство. Оно откроет врата, чтобы я мог пройти к вам туда, когда ты убьешь архиепископа.$B$BЯ подчиню себе его дух и заставлю его отвечать на мои вопросы! Мы найдем верховного адмирала Вествинда!', 'Убейте архиепископа Ландгрена и откройте Врата Арета рядом с трупом. Поговорите с лордом-командиром Аретом, когда тот закончит допрашивать дух архиепископа в Багровом соборе.', 'Потайная пещера на той стороне острова. Как интересно.$B$BПо крайней мере, теперь я знаю, где пропали все мои шпионы.', 'Да?', NULL, NULL, 'Архиепископ Ландгрен убито', 'Рекомендуемое количество игроков: 5', NULL, 'Врата Арета');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12848, 'Вечный голод', 'Скоро тобой овладеет неутолимый голод, $C, и когда это произойдет, ты испытаешь невообразимые страдания. От этой боли есть лишь одно средство, которое успокоит муки голода.$B$BИ я подскажу тебе путь к спасению.$B$BЗдесь, в сердце Акеруса, мы держим тех, кто оказался недостоин вступить в наше темное братство. Отомкни этим ключом цепи, в которые закованы недостойные ученики. Позволь им сразиться за свою свободу. Убей их – и боль пройдет. Уступи им – и твои страдания будут длиться вечно.$B$BВыбирай – жить тебе или умереть в муках.', 'Инструктор Разувий из Черного оплота приказал вам освободить недостойного ученика и хладнокровно убить его!Выжить должен только один!', 'Как я и ожидал, мой верный рыцарь смерти вернулся с победой! Твое обучение завершено, $N.', 'Две жизни, один ключ... Не разочаруй меня, $N.', NULL, NULL, 'Побеждено недостойных учеников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12849, 'Сила крови, льда и нечестивости', '', '', 'В Зале Власти тебя ждут учителя школ крови, льда и нечестивости, которые могут обучить тебя этим темным искусствам. Я, Лорд Торваль – глава школы крови, леди Алистра занимается нечестивыми практиками, а архилич Амал\'тазад безраздельно правит в школе льда.Приходи сюда почаще, ибо в этих знаниях заключена великая сила.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12850, 'Командир сил Плети Таланор', 'Командир сил Плети Таланор ожидает тебя на балконе к юго-востоку отсюда. Доложи ему о прибытии и потребуй предоставить грифона Плети, знающего дорогу в Разлом Смерти.$B$BПринц Валанар будет ждать тебя внизу.$B$BДа продлятся твои страдания, $gбрат:сестра:!', 'Найдите командира сил Плети Таланора на балконе первого этажа Черного оплота.', 'Война началась, рыцарь смерти! Я немедленно прикажу подать для тебя самого быстрокрылого грифона, который отвезет тебя в Разлом Смерти. Хаос, смерть, разрушение! Ты станешь их глашатаем!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12851, 'Медвежья хватка', 'Сейчас мы тебя испытаем, женщина!$B$BСейчас мы проверим, что там у тебя в груди – сердце сопливой швеи или сердце королевы воинов!$B$BОдно настоящее сражение – и мы узнаем ответ...$B$BТы можешь врать своей матери, своим сестрам и даже себе, но войне не соврешь. Она всегда вскроет твою истинную природу.$B$BКогда будешь готова – садись на Ледоклыка и мчись в бой. И пусть твои стрелы обрушатся градом смерти на головы наших врагов.', 'По заданию Бриджаны из деревни Бруннхильдар оседлайте Ледоклыка и застрелите 7 снежных воргов и 15 снежных великанов в долине Древней Зимы.', 'Быть может, и правда в твоей груди бьется сердце истинной воительницы.$B$BВремя покажет...', 'Ты уцелела в сражении, $N?', NULL, NULL, 'Сожжено снежных воргов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12852, 'Поиски адмирала', 'Когда на верховного генерала Аббендис напали в Новом Дольном Очаге, верховный адмирал сбежал, укрывшись в полностью непроницаемой защитной магической сфере.$B$BЯ хорошо разбираюсь в рассеивании магии.$B$BВозьми вот это и используй против него в Тайной Лощине, когда он активирует магическую сферу. Жалко, меня там не будет. Хотелось бы мне посмотреть на его лицо, когда ты проделаешь этот фокус.$B$BРазделайся же с ним.', 'Убейте верховного адмирала Вествинда, а потом возвращайтесь к лорду-командиру Арету на Уступ Смерти.', 'Мал\'Ганис?!$B$B<Лорд-командир громко смеется.>$B$BДемоны вновь приютили этих недоумков, но теперь они уничтожены!$B$BНадеюсь, мой доблестный $C не откажется тут задержаться и помочь нам прикончить всех остальных? Может, какая-то из этих вещиц будет достаточным поводом, чтобы остаться?', NULL, NULL, NULL, 'Верховный адмирал Вествинд убит', 'Аннулятор лорда-командира', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12853, 'Поторопить события', 'Эй, дружище!$B$BЛюбишь фейерверки и взрывы? Конечно, любишь! Так вот, я знаю одно интересное местечко, которое тебе непременно придется по вкусу. Там, в К-3, разрабатывают самые лучшие взрывчатые вещества, с помощью которых можно поднять на воздух что угодно! Заманчиво, а? Не пропусти все на свете, отправляйся туда прямо сейчас и поговори с Глумом Свечекрутом!$B$BНеобходимые разъяснения: для участия в эксперименте необходимо выполнить некоторые подготовительные работы.', 'Поговорите с Глумом Свечекрутом в лаборатории К-3 в Грозовой Гряде.', 'Добро пожаловать на К-3!$B$BМы прибыли сюда, чтобы обследовать эти горы и забрать себе по возможности больше этих удивительных механизмов $Nв. Однако все продвигается далеко не так быстро. Гноллы, снобольды, магнатавры... куда ни плюнь, повсюду – враги и препоны.$B$BНе говоря уже о том, что мы не можем поднять в воздух наши крылолеты, потому что у них замерзают моторы.$B$BТак что дел у нас много. Не хочешь помочь?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12854, 'По следам Бранна', 'После того как мы обнаружили журнал Бранна в Седых холмах, нам удалось с ним связаться всего один раз. В штаб-квартиру Лиги Исследователей в Стальгорне подбросили таинственную записку. От кого – непонятно. Там было сказано, что нам нужно встретиться с Бранном в его лагере и помочь ему в его поисках.$B$BНасколько я понимаю, его лагерь находится к северо-востоку отсюда, на том берегу реки Дыхания Бора, у подножия каких-то развалин подле Пути $Nв.', 'Заберите завернутую в мешковину записку из лагеря Бранна и возвращайтесь к археологу Андорину в Ледяную крепость.', '<Археолог Андорин смотрит на вас выжидательно.>$B$BПредполагалось, что ты вернешься с Бранном, а не с каким-то клочком бумаги. Что вообще происходит?', 'Ты нашел лагерь Бранна?', NULL, NULL, 'Завернутая в мешковину записка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12855, 'Найти преступника', 'Судя по намекам в записке Бранна, вместе с ней он должен был спрятать что-то еще. Может быть, сверток... или что-то похожее. Ты $gуверен:уверена:, что там больше ничего не было?$B$BЛадно, вот что мы сделаем. Возьми одну из северных гончих. У них острый нюх, и Зиморожденные используют их в качестве ищеек. Отведи ее в разрушенный лагерь, и пусть она возьмет след Бранна.$B$BС ее помощью ты найдешь пропавшие вещи, а если повезет – то и самого Бранна тоже.', 'Используйте ошейник северной гончей в Заброшенном лагере, чтобы выследить тех, кто забрал вещи Бранна. Когда вы их разыщете, включите переговорное устройство и свяжитесь с теми, с кем получится связаться.', 'Ты... ты не из Лиги Исследователей. Во всяком случае, я тебя что-то не помню. Но у тебя переговорное устройство, а это значит, что тебя прислали из Лиги. Ну что же, хорошо. Пусть и не совсем то, на что я надеялся, но сгодишься и ты.', 'Кто ты?', NULL, NULL, 'Выследить вора', 'Следопыт Тулин убито', 'Ошейник северной гончей', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12856, 'Холодные сердца', 'Умереть в яростной битве с оружием в руках – это почетная и славная смерть. Умереть замороженной в глыбе льда под непрестанные насмешки врагов – это стыд и бесчестье.$B$BЛети в Дун Ниффелем, что к востоку от Долины Древних Зим, и освободи пленного протодракона. Вместе с ней вы сумеете освободить наших сестер из ледяной тюрьмы и вернуть их домой.$B$BНо остерегайся дубинок великанов, если не хочешь оказаться в числе замороженных пленниц.', 'По заданию Бриджаны летите в Дун Ниффелем, освободите 3 пленных протодраконов, спасите 9 пленных бруннхильдарок и привезите их обратно, к востоку от деревни Бруннхильдар.', 'Прими мою искреннюю благодарность, сестра.$B$BТы принесла славу Бруннхильдару!', NULL, NULL, NULL, 'Спасено пленных бруннхильдарок', 'Освобождено протодраконов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12857, 'Плавник Ярогрива', 'Вождь Яростного Когтя объявляет:$B$BЯрогрив, верный тюлев вождя Яростного Когтя, покусал руку, которая его кормит. Яростный Коготь говорит: Ярогрив больше уже не хороший, из-за плохих троллей Дракуру он сам стал плохим. Вождь Яростного Когтя с прискорбием сообщает, что Ярогрива придется убить. Тот, кто убьет Ярогрива, пусть принесет вождю его плавник как доказательство, что дело сделано.$B$BЯрогрива можно найти на юге-востоке, в озере Яростного Когтя.$B$BВождь Яростного Когтя просит простить его за плохой почерк. В первый раз в жизни он пользуется этой штукой, плюс к тому вождь Яростного Когтя все-таки волчер, а не человек.', 'Принесите плавник Ярогрива вождю Яростного Когтя в Разлом Света в Зул\'Драке.', '<Вождь Яростного Когтя плачет.>$B$BОн был еще маленьким, Ярогрив. Я его вырастил, да. Недобрый день для Яростного Когтя. Сначала тролли напали на нас, потом тролли испортили Ярогрива, и он стал нехорошим. Яростный Коготь больше не будет иметь дела с троллями!', 'Бедный Ярогрив. Мне его подарил шурин.', NULL, NULL, 'Плавник Ярогрива', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12858, 'Кусочки головоломки', 'Слава Свету, что кто-то все-таки получил мое сообщение. Теперь, когда мне уже не угрожает опасность от железных дворфов, у меня есть одно дело, и мне нужна твоя помощь. Мне нужно собрать краеугольный камень Норганнона, охраняющий доступ к архивам Ульдуара. Титаны разделили его на две части и спрятали их в разных местах.$B$BОдна из частей, оболочка, хранится в Библиотеке Изобретателя на северном побережье, к югу от самого Ульдуара. Первым делом тебе надо будет собрать фрагменты диска доступа – отобрать их у стражей библиотеки.', 'Соберите 6 фрагментов диска изобретателя и сложите из них диск изобретателя.', 'Замечательно! Теперь с помощью этого диска мы сможем открыть хранилище изобретателя.', 'Ты собрал диск?', NULL, NULL, 'Диск Изобретателя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12859, 'Негасимый огонь', 'Тролли нападали на логово Яростного Когтя и выгоняли всех волчеров! А теперь – еще хуже. Тролли жгут нашу деревню! Совсем-совсем плохо. Вождь просил Моки, главного шамана Яростного Когтя, изучать их огонь. И вот что удивляет! Огонь по-прежнему жарок и может жечь и сжигать.$B$BПомоги волчерам погасить огонь. У Моки есть для тебя особый огнетушитель. Возьми его и потуши пожары в логове Яростного Когтя на юго-востоке. Иногда так бывает, что одна струя не потушит огонь – надо много. Но в огнетушителе вода есть всегда! Магия Яростного Когтя очень сильная, да!', 'Используйте огнетушитель Яростного Когтя, чтобы потушить 15 пожаров в логове Яростного Когтя по просьбе старого шамана Моки в Разломе Света в Зул\'Драке.', 'Странно. Я знаю, что ты потушил пожар, но огонь так и горит до сих пор. Может быть, эта штука не так хороша, как мы думали, а? И все равно Моки заплатит тебе за работу. Надеюсь, и тролли тоже сгорят!', NULL, NULL, NULL, 'Пожар в логове потушен', 'Огнетушитель Яростного Когтя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12860, 'Сбор информации', 'Этот диск, который ты $gсобрал:собрала:... он пустой! Наверное, Хранитель Мимир, который построил эту библиотеку, спрятал всю информацию в другом месте. Осмотри Библиотеку Изобретателя, там нигде нет банков данных?$B$BМожет, диск предназначен для них... Попробуй использовать его на каком-нибудь из банков данных. Может быть, он считывает и записывает информацию с этих устройств. Попробуй сделать, как я сказал, а потом свяжись со мной и расскажи, как успехи. А я тем временем попробую разыскать вторую половину ключа от архива.', 'Воспользуйтесь диском изобретателя, чтобы считать 7 фрагментов секретных данных из банков данных.', '<Бранн смотрит на диск, который вы ему показываете.>$B$BА как я отсюда пойму, записано там что-нибудь или нет?! Опиши мне подробно, что было..$B$B<Вы подробно описываете процесс поиска и считывания данных.>$B$BЗначит, там все работает? Надо отдать должное Хранителю Мимиру. Он – настоящий мастер своего дела, чего, по всей видимости, нельзя сказать об остальных хранителях...', 'Ну, что там с диском? Тебе удалось считать информацию?', NULL, NULL, 'Получено фрагментов секретных данных', 'Диск Изобретателя (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12861, 'Плохие тролли', 'Дракуру... Знаешь, кто этот тролль? Я думаю, этот Дракуру, он вождь плохих троллей. Они называют себя троллями Дракуру – вот я и смекнул, что к чему. Теперь понимаешь, почему я – вождь племени Яростного Когтя. Самый умный из всех волчеров!$B$BНо я с тобой говорю о другом. Плохие тролли пришли и прогнали племя из логова. Волчеры, которые не убежали, пойманы и сейчас в плену в деревне. Ты пойдешь в логово Яростного Когтя, это на юго-востоке, и освободишь пленных волчеров. Чтобы добыть отпиратель замка, надо убить плохого тролля. Отпирателей надо много – убивай много троллей.', 'По заданию вождя Яростного Когтя из Разлома Света в Зул\'Драке отберите у троллей Дракуру необходимое количество \"Отмычек\" Дракуру и освободите 8 пойманных волчеров из стаи Яростного Когтя.', 'Племя Яростного Когтя тебе благодарно, $N. И хотя логово, вероятно, потеряно навсегда, как и дружба волчеров с троллями... и, если подумать как следует, то и Ярогрив тоже потерян навсегда. И еще мой шурин. Его тоже больше нет. Хрм, кстати, знаешь подругу вождя? И ее нет.$B$BМожет быть, тебе лучше сейчас уйти. Вождь горюет.', NULL, NULL, NULL, 'Освобождено пленных волчеров из племени Яростного Когтя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12862, 'Когда остается единственный выход...', 'Что-то я сомневаюсь, что нам удастся закрепиться в этих горах.$B$BПоверь мне, я не из тех, кто легко сдается... но, когда ты зажат между замерзшими машинами, злобными врайкульскими бабами, какими-то непонятными существами, жаждущими стать драконами, и еще добрым десятком других воинственных тварей, это как-то не способствует оптимистическому настрою.$B$BНо ты все же не падай духом! Если мы не можем там закрепиться, это еще не значит, что мы не можем доставить тебя туда... поездка в один конец – это вовсе не сложно, когда привыкаешь.$B$B<Рикет указывает на ракеты неподалеку.:', 'Воспользуйтесь принадлежащим Рикет пропеллерным доставочным аппаратом Д16, чтобы продвинуться вглубь Грозовой Гряды.', 'Оох! Кажется, посадка вышла жесткой. Но прибытие было весьма эффектным, паренек!$B$BДобро пожаловать в Ледяную крепость! Ты хочешь помочь нам найти проход в Ледяную Корону?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12863, 'Большое спасибо', 'Вот спасибо, что ты $Gпришел, малыш:пришла, милая;.$B$BСудя по твоим удивленным глазам и дрожащим рукам, ты тут $gновенький:новенькая:. Я угадал? Тогда тебе надо скорее познакомиться с нашими великодушными хозяевами!$B$BУ нас тут образовался запас лишних медикаментов... то есть они никогда не лишние, но у нас их действительно избыток. Отнеси этот ящик Глорталу и спроси, не нужна ли ему помощь. А то не хотелось бы, чтобы они думали, будто мы им не благодарны за столь теплый прием.', 'Отнесите ящик с медикаментами Глорталу Жесткобороду из Ледяной крепости.', 'Медикаменты? Спасибо! Хотя, честно сказать, я не знаю, зачем нам столько, но они наверняка пригодятся.$B$BРад с тобой познакомиться... В последнее время гости к нам ходят редко, и новый товарищ – это всегда очень здорово!', 'Привет.', NULL, NULL, 'Ящик с медикаментами (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12864, 'Пропавшие разведчики', 'Раз уж ты здесь, надо этим воспользоваться.$B$BНаши разведчики уже давно должны были вернуться, но их все нет и нет... Эти горы – суровое место, и хотя эти ребята – настоящие мастера своего дела, я все равно беспокоюсь... $B$BИди на восток... в долину Дыхания Бора, к водопаду Бора... они ушли в том направлении. Если ты их найдешь, если найдешь хоть какие-то указания на то, где они могут быть, сразу же возвращайся сюда и докладывай мне. У нас тут немало врагов... и если наши ребята нуждаются в помощи, то чем быстрее мы об этом узнаем, тем лучше.', 'Обыщите долину Дыхания Бора и водопад Бора и попробуйте разыскать пропавших разведчиков из клана Зиморожденных.', 'Если разведчик не возвращается так долго... чего-то подобного и следовала ожидать. Значит, говоришь, гарпии?$B$BКороль Грозовое Сердце устроил нам жесткую боевую подготовку... зато теперь мы умеем сражаться что надо. И теперь я понимаю, зачем это нужно. Он – самый мудрый и самый могучий правитель из всех, которые были у моего народа... пусть тебя не обманывает его румянец.', NULL, NULL, NULL, 'Найти пропавших разведчиков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12865, 'Верные друзья', 'Новые люди! Свежая кровь! Очень рад познакомиться! У меня есть для тебя работа.$B$BНа северо-востоке отсюда лежит Подножие... суровый край, да... но мне донесли, что там видели целое стадо люторогов. Наши птицы очень уважают мясо люторогов, но сейчас стало опасно ходить на охоту – повсюду гнездовья протодраконов, житья от них нет!$B$BНе в службу, а в дружбу... постарайся добыть мяса для наших птичек и накорми их как следует, ладно?', 'По поручению Фьюрлина Ледоброва из Ледяной крепости добудьте 8 кусков свежего мяса люторога и покормите грозовестников, обитающих прямо над городом.', 'Спасибо, большое спасибо... и они, я уверен, тоже тебе благодарны. Эти птицы – сильные союзники, и с ними лучше дружить.', NULL, NULL, NULL, 'Накормлено грозовестников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12866, 'Сопротивление агрессорам', 'Проклятые гарпии. Мы уже столько раз задавали им трепку... и после каждого раза они какое-то время сидели тихо. Я думал, что после последнего раза они больше к нам не полезут.$B$BНо нет.$B$BНичему эти твари не учатся... но если их будет мало, они вряд ли станут нападать. Отправляйся в долины на севере и востоке и постарайся прикончить побольше гарпий.', 'По заданию Глортала Жесткоборода из Ледяной крепости убейте 8 крикуний и 8 ведьм из стаи Ледяного Пера.', 'Да, это грязная работа, я знаю, и мы очень тебе благодарны. Кстати, что за имя там разведчик упоминал... Сирана?', NULL, NULL, NULL, 'Крикунья из стаи Ледяного Пера убито', 'Ведьма из стаи Ледяного Пера убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12867, 'Похитители птенцов', 'Еще пару недель назад, если ты смотрел на небо, там повсюду парили эти прекрасные гордые орлы. А теперь – нет. И знаешь, почему? Потому что теперь им приходится постоянно дежурить у своих гнезд – охранять их от гарпий, которые повадились красть их яйца.$B$BНаверное, только что вылупившиеся птенцы считаются у гарпий деликатесом... Так иди же в долину, на север или на восток, найди яйца и принеси мне, а я положу их обратно в гнезда.', 'Принесите Фьюрлину Ледоброву из Ледяной крепости 15 яиц грозовестников.', 'Хорошо поработал, парень. Теперь орлы тебе доверяют.$B$BИ, если тебе будет нужно куда-то слетать, я уверен, они согласятся доставить тебя до места... теперь ты – их друг.', 'Когда мы решим эту проблемы, орлы снова будут свободно парить в небе над нами.', NULL, NULL, 'Яйцо грозовестника', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12868, 'Источник всех бед', 'Похоже, эта бесноватая Сирана Ледяной Вопль подстрекает всех гарпий. Я так думаю, если избавиться от нее, они перестанут на нас нападать. Один из наших странников бурь сказал, что заметил ее у вершины прямо к северо-западу отсюда. Разыщи эту мегеру и покончи с ней. Невозможно больше терпеть.', 'По просьбе Глортала Жесткоборода убейте Сирану Ледяной Вопль.', 'Значит, все сделано. Большое спасибо.$B$BЯ разговаривал с Фьюрлином – он сказал, что его отряд возьмется за приструнение гарпий. Главное – задать им хорошую трепку, и им вряд ли уже хватит смелости нападать. Я знаю, работенка была не из приятных – вот, держи это в знак моей благодарности.', NULL, NULL, NULL, 'Сирана Ледяной Вопль убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12869, 'Все слишком далеко зашло', 'Ты ведь $gбыл:была: там вместе с Локеном, да? Железные дворфы захватили Веранус, мать всех протодраконов. Разумеется, драконы этому не рады... они встревожены и потому агрессивны.$B$BНу, все и покатилось, как снежный ком... они захватили территорию, исконную территорию грозовестников... Ты знаешь, на чьей мы стороне... они всегда были нашими верными союзниками, и мы не можем их бросить. Поэтому мы отправляемся к Подножию, чтобы оказать им поддержку. $B$BКороль Грозовое Сердце оставил мне свой молот – возьми его и используй, как должно. Но потом непременно верни его мне.', 'По поручению Фьюрлина Ледоброва убейте с помощью грозовестника 16 змеев Грозовой Гряды в Подножии.', 'Мне что-то не верится, что драконы так быстро отступятся. Если можешь, задержись тут до завтра. Наверняка нам понадобится твоя помощь.', 'Все грозит выйти из-под контроля...', NULL, NULL, 'Змей Грозовой Гряды убито', 'Грозовой молот (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12870, 'Древние реликвии', 'Ха, здорово!$B$BПрежде, чем ты отправишься на опасные приключения, вершить великие дела, могу ли я попросить тебя о маленьком одолжении, $gпаренек:деточка:?$B$BВ этих горах полным-полно драгоценных реликвий и всяких побрякушек... Для Лиги эти места – просто кладезь! Я был бы тебе очень признателен, если бы ты $gтащил:тащила: все ценное, на что наткнешься, ко мне. Я тебя даже элем угощу, за труды! Поверь мне, $gпарень:девчушка: – сделка классная, не пожалеешь!', 'Принесите Рорку Остробороду в Ледяную крепость 10 реликвий Ульдуара.', 'Класс! А ты парень что надо!$B$BДавай-ка опрокинем по стаканчику! Отпразднуем эту славную находку!', 'Удалось найти для меня те реликвии, про которые я говорил тебе?', NULL, NULL, 'Реликвия Ульдуара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12871, 'Помощь Лиги исследователей', 'Интересно. Что-то я не вижу ни одного блокирующего механизма на этой оболочке, что дает все основания предположить, что для того, чтобы собрать краеугольный камень, недостаточно просто найти недостающий кусок и соединить их друг с другом.$B$BОтнеси оболочку руководителю экспедиции Лагнусу в Ледяную крепость. Может быть, он разберется, каким должно быть ядро, если судить по оболочке, и, может быть, даже сумеет уговорить снежных дворфов, чтобы они помогли нам его найти.$B$BА я пока попытаюсь придумать, как соединить обе части. Когда получим какие-то результаты, тогда и поговорим.', 'Отнесите оболочку Норганнона Лагнусу в Ледяную крепость.', 'Клянусь бородой Мурадина! Это то, что я думаю?! На этот раз Бранн превзошел сам себя... и ты, кстати, тоже, уж если на то пошло! Ребята там, дома, они просто не поверят, когда я им скажу!..', 'Привет!', NULL, NULL, 'Оболочка Норганнона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12872, 'Оболочка Норганнона', 'Идет зарядка диска изобретателя.$B$BДиск заряжен.$B$BЗагрузка аварийного протокола.$B$BАварийный протокол загружен. Пожалуйста, воспользуйтесь диском для активации охранника оболочки Норганнона, архивариуса Мехатона. Оболочка будет предоставлена вам после стандартной проверки личности.$B$BЖелаем вам приятного тысячелетия.', 'Заберите оболочку Норганнона у архивариуса Мехатона.', 'Да, это она! Первая половина краеугольного камня Норганнона. Отлично, $N. Когда я вернусь в Стальгорн, то позабочусь о том, чтобы тебя сделали почетным членом Лиги Исследователей!', 'Да не стой ты столбом! Покажи мне оболочку!', NULL, NULL, 'Оболочка Норганнона', 'Заряженный диск', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12873, 'Король Зиморожденных', 'Определенно... я хорошо представляю, как должно выглядеть ядро. Если кто-то из Зиморожденных видел его хоть раз, он узнает его по описанию.$B$BУ нас мало времени, так что давай сразу к делу. Иди к королю Грозовому Сердцу и проси его о помощи... он наверняка знает кого-то, кто поможет нам разыскать ядро. И будь с ним $gучтив и обходителен:учтива и обходительна: – он весьма уважаемый правитель.', 'Поговорите с Йоргом Грозовым Сердцем в Ледяной крепости.', 'Ядро Норганнона? В первый раз слышу. Но, кажется, я знаю, кто сумеет тебе помочь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12874, 'Рвение Зиморожденного', 'Я-то с радостью дам убежище путникам – накормлю, напою, все как надо. Но свои дела вы уж как-то решайте сами, я не стану принуждать своих людей заниматься чужими делами, да.$B$BВот, что я тебе скажу... мои люди – хорошие воины, настоящие воины. Когда юный Зиморожденный становится мужчиной, он доказывает свое мужество в битве. Чтобы, значит, все видели, что он настоящий мужчина, вот так.$B$BПокажи, что ты так же $gотважен, силен и свиреп:отважна: сильна и свирепа;, как наши воины – и тогда, может быть, мои люди тебе помогут. Поговори с Фьюрлином вон там, у скалы, и он назначит тебе испытание.', 'По указанию Йорга Грозового Сердца из Ледяной Крепости поговорите с Фьюрлином Ледобровом, который организует вам поездку и назначит для вас испытание.', 'Ха! Неплохо, малыш... в тебе, часом, нет крови Зиморожденных, хоть немножко? В общем, ты годен не только на праздную болтовню, и мне это нравится!', 'Ты вернулся ко мне. Ты вернулся с победой?', NULL, NULL, 'Железный смотритель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12875, 'Опытный проводник', 'Я не знаю, где спрятано это ядро, но я обещался помочь и сдержу свое слово.$B$BВ пещере к северу отсюда живет отшельник по имени Дром Ледохват... это внизу, в долине. Сами мы отошли от традиций $Nв, тем более что их почти и не осталось... но Дром верен древним обычаям: он присматривает за их наиболее ценными строениями и частенько беседует с часовым Кретеем.$B$BИди к нему в пещеру... скажи ему, что ты от меня, и он, стало быть, тебе поможет.', 'Разыщите Дрома Ледохвата. +250 ед. репутации с Зиморожденные', '<Дром кашляет кровью.>$B$BЯдро Норганнона? Я сам уже долго пытаюсь его разыскать, но, похоже, что эта реликвия из тех, которые тщательно охраняются и по сей день. И, надо думать, на то есть причины.$B$BТебя прислал король Грозовое Сердце, а это значит, что он увидел в тебе благородство и честность... и я не могу отказать своему королю.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12876, 'Нежеланные гости', 'Наши разведчики заметили железных дворфов в долине к северу отсюда. Я слышал, король Грозовое Сердце послал тебя навестить Дрома и, честно говоря, немного беспокоюсь из-за них.$B$BЕсли ты увидишь железных дворфов, когда туда направишься, задай им как следует от меня, идет? Я думаю, они точно не знают, где мы и как сюда добраться, и я предпочел бы, чтобы так оно и было впредь.', 'По просьбе Фьюрлина Ледоброва убейте 10 погромщиков из клана Закаленных Бурей.', 'Печальная новость, юноша. Этих железных дворфов, похоже, становится все больше... тут, в горах, они уже попадаются нам на каждом шагу. Чую, война на носу.$B$BСпасибо, что разобрался с той группой... мы выиграли немного времени.', NULL, NULL, NULL, 'Убито погромщиков из клана Закаленных Бурей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12877, 'Одинокий часовой', 'Я так и не нашел ядро... но я часто беседовал с часовым Кретеем и по его оговоркам понял, что он что-то знает. Ты найдешь Кретея в горах на востоке, в Подножии, где он наблюдает за Машиной Творцов. Вполне вероятно, что ядро находится где-то там, но тебе придется убедить Кретея помочь тебе в поисках.$B$BТам повсюду рыщут железные дворфы, явно что-то ищут... может быть, даже и ядро. Они забрали мое кольцо. Разыщи их предводителя, забери у него кольцо и покажи его Кретею, чтобы он убедился, что тебя прислал я.', 'Заберите у наблюдателя железных дворфов перстень-печатку Ледохвата и покажите его Кретею в Подножии.', 'Кольцо Дрома? Как я понимаю, дела у него идут неважно, раз уж он не смог представить тебя лично. Это печально. Дром – благороднейший из дворфов, хотя и чересчур любопытный.$B$BКак я понимаю, у тебя ко мне дело?', 'Здравствуй, $C. Ты даже не представляешь, как это приятно, когда начинают знакомство с вежливого и учтивого обращения, а не с того, чтобы сразу с порога махать мечом.', NULL, NULL, 'Перстень-печатка Ледохвата', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12878, 'Спрятанная реликвия', 'Пока тебя не было, мне довелось пообщаться с дворфом по имени Бранн Бронзобород. Он сказал мне, что ищет краеугольный камень, и намерения у него, как я понял, самые благие. Думаю, что камень-ключ именно для этого дворфа и был изготовлен.$B$BЯдро Норганнона спрятано в Стылом склепе на юго-востоке отсюда. Его охраняют древние существа, сделанные изо льда, и они не обрадуются твоему приходу. Забери краеугольный камень, и да пребудет с тобой удача, $r.', 'Найдите ядро Норганнона, руководствуясь информацией, которую дал Кретей в Подножии.', '<Сундук открывается, и из него вырывается заплесневелый запах – запах седой старины. На дне сундука лежит ядро Норганнона, совершенно целехонькое.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12879, 'Ярость короля Зиморожденных', '$gВы достаете ядро из сундука, и внезапно слышите тяжелые шаги в коридоре. Также до вас доносится едва различимый грохот битвы, идущей где-то вдалеке.:', 'Отнесите ядро Норганнона Кретею в Подножие.', 'Кто-то использует Кузню Воли для создания этого войска... В Ульдуаре стало небезопасно.$B$BХорошо, что тебе удалось опередить этих поганищ и забрать ядро первым.', 'Кто-то использует Кузню Воли для создания этого войска... В Ульдуаре стало небезопасно. $R, ты принес ядро?', NULL, NULL, 'Ядро Норганнона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12880, 'Главный исследователь', 'Для того чтобы собрать краеугольный камень, нам понадобятся узы Норганнона, устройство, которое находится в Машине Творцов, в большой шахте неподалеку отсюда. Бранн уже должен быть там, со второй половиной камня-ключа. Я сказал ему, чтобы он использовал это устройство. Он ждет тебя.$B$BЯ постараюсь сдержать железных дворфов, чтобы дать вам время. Но я сомневаюсь, что смогу их удерживать долго. Скоро король Грозовое Сердце со своими людьми снова возьмется за оборону Ледяной Крепости. Так что поторопись, $r.', 'Отнесите ядро Норганнона Бранну Бронзобороду к Машине Творцов.', 'Ты молодец, парень! Просто умница! Это будет поистине великий день.$B$BБыстрее, давай мне ядро, пока сюда не добрались железные дворфы.', 'Эй, приятель! Рад познакомиться с тобой лично. Ты нашел его?', NULL, NULL, 'Ядро Норганнона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12881, 'Братья Бронзобороды', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12882, 'Древние реликвии', 'Добро пожаловать на гряду.$B$BУ меня есть к тебе одна простая просьба, прежде чем ты отправишься в свое запланированное грандиозное путешествие. По этим горам разбросаны реликвии и сокровища древнего Ульдуара. Большинство из них, скорее всего, попали в руки представителей различных разумных рас.$B$BПринеси мне то, что тебе удастся найти, и я щедро вознагражу тебя. Может, я даже дам тебе отведать какого-нибудь из своих многочисленных и отменных напитков!', 'Отнесите 10 реликвий Ульдуара Олуту Пивобрюху на место крушения Гром\'арша.', 'О, эти отлично подойдут! Весьма признателен! Не хочешь горло прополоскать после тяжких трудов?', 'Тебе удалось обнаружить реликвии, о которых я говорил?', NULL, NULL, 'Реликвия Ульдуара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12883, 'Приказы Дракуру', 'Прислужники, слушайте зов вашего повелителя! Король-лич даровал Дракуру всю власть над армиями Плети в Зул\'Драке. Наш приказ – убить всех!$B$BУМЕРЕТЬ ДОЛЖНЫ ВСЕ!$B$BВсе трупы будут обрабатываться в Мертвых полях и посылаться к Принцу Навариусу в Зерамас для превращения в воинов Плети! Ничто не должно пропасть зря!$B$BСкоро мы будем пить кровь пророков и станем самым сильными! Плеть раздавит Зул\'Драк и Гундрак!', 'Отнесите приказы Дракуру главе рыцарей Лантинге в Разлом Света в Зул\'Драке.', 'Если это тот же Дракуру из крепости Драк\'Тарон, нам понадобится… помощь со стороны.$B$BТут неподалеку есть лагерь рыцарей смерти из Акеруса, они явно шли по тому же следу из разрушений, оставленных Плетью, который привел сюда и рыцарей Серебряного Авангарда. Половина нашего войска завязла у Серебряной Заставы, сражается с бешеными троллями драккари, и поэтому нам нужно объединить силы с рыцарями с Черной Заставы.$B$B<Лантинга бормочет что-то себе под нос.>$B$BА я-то надеялся, что после Часовни Последней Надежды больше уже не увижу этих мерзавцев...', 'Говоришь, Дракуру? Да, я слышал это имя...', NULL, NULL, 'Приказы Дракуру (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12884, 'Черная застава', 'На западе, по ту строну разрушенных дорог и строений, находится лагерь рыцарей смерти, именуемый Черной Заставой.$B$B<Глава рыцарей Лантинга сворачивает в трубочку бумагу с приказом Дракуру.>$B$BПередай эти бумаги Стефану Ваду. Стефан – рыцарь смерти, главный на Черной Заставе. Скажи ему, что Серебряный Авангард займется принцем Навариусом. А они пусть займутся Дракуру.$B$BБудь $gосторожен:осторожна:, $N. Путь к Черной Заставе проходит по землям, захваченным силами Плети.', 'Отнесите приказы Дракуру Стефану Ваду на Черную Заставу в Зул\'Драке.', '<Стефан читает письмо, потом комкает его и бросает в огонь.>$B$BЭти новости уже устарели. Серебряный Авангард, как всегда, подоспел к шапочному разбору. Мы следим за Дракуру от самых Седых холмов. Он у нас первый в списке кандидатов на уничтожение.', 'Что там у тебя, $C?', NULL, NULL, 'Приказы Дракуру (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12885, 'Изгнанники Ульдуара', 'Грозовая Гряда – интересное место, но тут есть не только развалины $Nв. Здешние люди живут в непрестанном страхе перед Локеном и его приспешниками.$B$BОн послал армию своих любимцев, железных дворфов, на жестокую и беспощадную войну против всех, кто создан из камня. Он изгнал земельников из Ульдуара, и они были вынуждены укрыться в Приюте Глыбоскала, на горе, к западу от Библиотеки Изобретателя. А сейчас железные дворфы добрались и туда и осаждают Глыбоскала и его собратьев. Помоги им защитить убежище, $N.', 'Поговорите с Глыбоскалом Камнетесом в Приюте Глыбоскала.', 'Значит, ты знаешь Бранна Бронзоборода? Это наш самый верный союзник из всех, кто создан из плоти и крови. Мы с ним как братья в нашей общей борьбе против Локена и его приспешников, в борьбе за Ульдуар.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12886, 'Драконобойца', 'Ну, вот. Ты прошла почти все испытания Круга хильд... осталось только одно, последнее...$B$BДраконобойца – это последнее, самое трудное испытание силы духа и воинской доблести хильд. У тебя будет только твой верховой дракон, гарпун и твое собственное мужество, и тебе нужно будет сразиться в нескольких поединках с нашими сестрами, лучшими из воительниц.$B$BБорьба будет жестокой. Не давай никому пощады и не жди ее ни от кого.', 'Воспользуйтесь хильдским гарпуном, чтобы победить 10 наездниц на драконе Круга хильд в Храме Штормов, после чего выстрелите гарпуном в украшение на колонне и поговорите с Торимом.', 'Сиф... это ты?', 'Убирайся!', NULL, NULL, 'Побеждено наездниц на драконе Круга хильд', 'Хильдский гарпун', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12887, 'Непростая работа', 'Рыцари Черного Клинка хотят захватить базу Плети, известную как Мрачный Cвод, на северо-западе отсюда. У меня есть доверенный человек в их отряде, и он просит помощи.$B$BПерво-наперво следует \"ослепить\" Короля-лича. У него есть Глаз – аппарат для наблюдения, который парит в небе над шпилями свода.$B$BНаши дворфы собрали одно устройство, которое можно использовать против него. Когда Глаз будет уничтожен, разыщи барона Раздора на территории свода. Он притворяется, что по-прежнему послушен воле Короля-лича.', 'Уничтожьте Глаз и переговорите с бароном Раздором в Мрачном Своде.', 'Теперь у нас, может быть, и получится что-то сделать. Только не обольщайся. Король-лич по-прежнему \"наблюдает\" за нами через приспешников Плети.$B$BСобственно, поэтому тебя и прислали сюда.', NULL, NULL, NULL, 'Глаз разрушен', 'Ослепляющий луч', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12888, 'УБЕР-И', 'Эта карта дает доступ к пульту управления хламоботом под названием УБЕР-И, чтобы осуществлять техническую поддержку и при необходимости перепрограммировать команды, отдаваемые машине.$B$BУБЕР-И, насколько известно, находится в здании Библиотеки Изобретателя. На карте представлен список сломанных комплектующих хламобота и нерабочих систем. Если заменить необходимые детали, агрегат можно отремонтировать и привести в рабочее состояние.', 'Принесите в Библиотеку Изобретателя карту доступа к УБЕР-И, 4 пригоршни кобальтовых болтов и 5 перегруженных конденсаторов и попробуйте починить УБЕР-И.', '<Сверяясь с картой доступа, вы принимаетесь за ремонт. Когда вы заканчиваете с ремонтом, вы закрываете панель доступа и включаете питание.>', '<Вы открываете панель доступа УБЕР-И.>', NULL, NULL, 'Пригоршня кобальтовых болтов', 'Перегруженный конденсатор', 'Карта доступа к УБЕР-И (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12889, 'Панель управления прототипом', 'Наименование: УБЕР-И.$B$BРаспоряжение: поддерживать работоспособность панелей управления и баз данных Библиотеки Изобретателя в отсутствие Хранителя Мимира.$B$BВремя, прошедшее с последнего цикла технического обслуживания: 489 дней.$B$BСтатус данных о проектируемой схеме: неизвестен.$B$BТекущая задача: ремонт панели управления прототипом.', 'Попробуйте разобраться с панелью управления прототипом в Библиотеке Изобретателя.', 'Вы рассматриваете дисплей на панели управления прототипом. Похоже, что как минимум одна схема Мимира \"пережила\" затяжной перерыв между циклами технического обслуживания. По диаграммам и инструкциям, представленным в файле схемы, вы без труда сконструируете мехагнома.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12890, 'Если размер имеет значение...', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12891, 'Воплощение идеи', 'Когда я прислуживал... э... состоял на службе у Короля-лича, мы часто использовали устройство под названием скипетр повеления, чтобы держать в узде шибко умных рабов Плети.$B$BЕсли ты мне поможешь, я сделаю тебе точно такой же скипетр.$B$BМожно сказать, что тебе повезло. Все необходимые компоненты у нас под рукой: скипетр сектанта, крюк поганища, веревка упыря и вдоволь эссенций Плети.$B$BЭто будет нетрудно, $C.', 'Принесите скипетр сектанта, крюк поганища, веревку упыря и 5 эссенций Плети барону Раздору в Мрачный Свод.', 'Быстрее, давай их сюда и отойди подальше, чтобы мне не мешать!$B$BПалка, крючок и веревка – их назначение, когда они вместе, вполне очевидно. Надо лишь пропитать их эссенциями, и тогда у нас будет очень полезное устройство.$B$BВещь, самая обыкновенная с виду, однако необыкновенная в употреблении!', 'Когда ты соберешь все необходимые компоненты, я смогу сделать скипетр повеления, только с некоторыми изменениями, потребными для наших целей, и мы перейдем к исполнению нашего плана.', NULL, NULL, 'Скипетр сектанта', 'Крюк поганища', 'Веревка упыря', 'Эссенция Плети');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12892, 'Непростая работа', 'Рыцари Черного Клинка хотят захватить базу Плети, известную как Мрачный Cвод, на северо-западе отсюда. У меня есть доверенный человек в их отряде, и он просит помощи.$B$BПерво-наперво следует \"ослепить\" Короля-лича. У него есть Глаз – аппарат для наблюдения, который парит в небе над шпилями свода.$B$BНаши гоблины собрали одно устройство, которое можно использовать против него. Когда Глаз будет уничтожен, разыщи барона Раздора на территории свода. Он притворяется, что по-прежнему послушен воле Короля-лича.', 'Уничтожьте Глаз и переговорите с бароном Раздором в Мрачном Своде.', 'Теперь у нас, может быть, и получится что-то сделать. Только не обольщайся. Король-лич по-прежнему \"наблюдает\" за нами через приспешников Плети.$B$BСобственно, поэтому тебя и прислали сюда.', NULL, NULL, NULL, 'Глаз разрушен', 'Ослепляющий луч', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12893, 'Освобождение разума', 'Злоб, леди Найтсвуд и Прыгун могут стать мощным оружием в борьбе против Короля-лича, если освободить их от его влияния. А для этого у нас есть скипетр повеления.$B$BТы найдешь их на балконах к востоку и западу от склепа, а также на среднем ярусе склепа над нами. Скипетром нужно подействовать на всех троих.$B$BЛети. Нам надо переманить их на свою сторону!', 'Подействуйте скипетром повеления на тела Злоба, леди Найтсвуд и Прыгуна, а потом возвращайтесь к барону Раздору в Мрачный Свод.', 'Эти трое нам пригодятся, когда мы наконец захватим склеп.$B$BКстати, о склепе...', 'Ты их не обратил! Не надо держать меня за дурака, $C!', NULL, NULL, 'Злоб обращен', 'Леди Найтсвуд обращена', 'Прыгун обращен', 'Скипетр повеления');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12894, 'Передовой лагерь рыцарей', 'Рыцарь Даргат, рыцарь Маккеллар, инженер Рид и близнецы Герк и Бурр, отправились на Мертвые поля, чтобы разбить лагерь на передовой. В их последнем донесении сказано, что они благополучно разбили лагерь на границе Мертвых полей, к северо-западу отсюда.$B$BВ свете того, что нам стало известно о Дракуру и принце Навариусе, думаю, нам нужно срочно послать кого-нибудь в Передовой лагерь рыцарей.$B$BСобирай вещи, $N. Ты выходишь немедленно!', 'Разыщите рыцаря Маккеллара в Передовом лагере рыцарей в Зул\'Драке.', 'Все было отлично, пока нас не атаковали воины Плети. Они захватили Даргата, Герка и Бурра и уничтожили наше средство передвижения. Угадай, кто был их предводителем?$B$B<Маккеллар кивает.>$B$BНавариус...$B$BПохоже, весь этот край превратился в одну большую фабрику для сил Плети. И мы находимся посреди открытой разработки сырья для этой проклятой армии нежити!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12895, 'Пропавший Бронзобород', 'Буквально перед самым отлетом разведчик Вор\'такх передал мне досье на этого Бранна Бронзоборода. Вполне очевидно, что Бранн направлялся к Грозовой Гряде – это понятно по записям в его журнале и по нашим находкам в Седых холмах. Незадолго до нашей аварии я видел сверху походный лагерь. К югу отсюда, на той стороне Подножия, на берегу замерзшей реки Дыхания Бора.$B$BЕсли Бранна там нет, обыщи лагерь и его окрестности, может быть, там остались какие-то следы... может, они нам подскажут, куда делся этот треклятый дворф. Все, что найдешь, неси мне.', 'Заберите завернутую в мешковину записку из лагеря Бранна и возвращайтесь к Боктару Кровавому Безумию на место крушения Гром\'арша.', 'Ну да, с нашим-то везением... можно было заранее предугадать, что именно так все и будет. Но просто так он от нас не уйдет. Давай-ка посмотрим, что там в этой записке.', 'Ты нашел лагерь Бронзоборода?', NULL, NULL, 'Завернутая в мешковину записка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12896, 'Последний аргумент', 'Рыцарей смерти, таких, как генерал Погибель Света, держат на слишком коротком поводке, и убедить их пойти против воли Короля-лича практически невозможно. Разве что представится исключительный случай.$B$BГенерал почти не выходит из Свода – следит за изготовлением нового оружия. Но если ты опрокинешь одну из его оружейных стоек в кузнице, тогда он точно придет, можешь не сомневаться. Я пошлю тебе в помощь Злоба, леди Найтсвуд и Прыгуна.$B$BМрачный Свод должен стать нашим, но для этого нам необходимо ликвидировать генерала Погибель Света!', 'Убейте генерала Погибель Света и доложите об исполнении Тассариану на борту \"Усмирителя небес\".', 'Генерал Погибель Света уничтожен, и его войско разбито? Мрачный Свод взят?', NULL, NULL, NULL, 'Генерал Погибель Света убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12897, 'Последний аргумент', 'Рыцарей смерти, таких, как генерал Погибель Света, держат на слишком коротком поводке, и убедить их пойти против воли Короля-лича практически невозможно. Разве что представится исключительный случай.$B$BГенерал почти не выходит из Свода – следит за изготовлением нового оружия. Но если ты опрокинешь одну из его оружейных стоек в кузнице, тогда он точно придет, можешь не сомневаться. Я пошлю тебе в помощь Злоба, леди Найтсвуд и Прыгуна.$B$BМрачный Свод должен стать нашим, но для этого нам необходимо ликвидировать генерала Погибель Света!', 'Убейте генерала Погибель Света и доложите об исполнении Кольтире Ткачу Смерти на борту \"Молота Оргрима\".', 'Генерал Погибель Света уничтожен, и его войско разбито? Мрачный Свод взят?', NULL, NULL, NULL, 'Генерал Погибель Света убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12898, 'Мрачный Свод', 'Как я понимаю, ты замечательно $gсправился:справилась:. И при этом еще $gпривлек:привлекла: трех очень нужных союзников на сторону рыцарей Черного Клинка.$B$B<Тассариан смотрит куда-то за горизонт.>$B$BТебе надо скорее возвращаться обратно. Барон Раздор и другие рыцари смерти сейчас сражаются с силами Плети, чтобы удержать Мрачный свод.$B$BЯ думаю, им понадобится твоя помощь.', 'Поговорите с бароном Раздором в Мрачном Своде.', 'Ты молодец, что вернулся. Как видишь, у нас тут на счету каждый боец.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12899, 'Мрачный Свод', 'Как я понимаю, ты замечательно $gсправился:справилась:. И при этом еще $gпривлек:привлекла: трех очень нужных союзников на сторону рыцарей Черного Клинка.$B$B<Кольтира смотрит на карту на полу.>$B$BТебе надо скорее возвращаться обратно. Барон Раздор и другие рыцари смерти сейчас сражаются с силами Плети, чтобы удержать Мрачный Свод.$B$BЯ думаю, им понадобится твоя помощь.', 'Поговорите с бароном Раздором в Мрачном Своде.', 'Ты молодец, что вернулся. Как видишь, у нас тут на счету каждый боец.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12900, 'Изготовление сбруи', 'Так ты хочешь ездить верхом? Ну, что же... пока что ты проявляешь себя достойно, и вполне можно дать тебе шанс испытать себя и в этом деле.$B$BЗначит, тебе нужна сбруя.$B$BВ горах на юге водятся йети. У них крепкая шкура как раз подходящей толщины. Принеси мне их шкуры, мы изготовим тебе упряжь, и ты сможешь попробовать научиться ездить на медведях.', 'По заданию Астрид Бьорнриттар из деревни Бруннхильдар раздобудьте 3 шкуры ледогривых йети.', 'Да, эти сгодятся. Я тебе в два счета сбрую сделаю!', 'Ты уже добыла шкуры? Ты найдешь йети внизу, в горах.', NULL, NULL, 'Шкура ледогривого йети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12901, 'Что-то из ничего', 'Принца Навариуса надо остановить. Нельзя допустить, чтобы Плеть и дальше использовала эти земли как фабрику зомби. Но если мы не сможем запустить танк, шансов у нас нет. Нужны запчасти.$B$BК северо-западу отсюда есть одно место, Тупик Трыма. У армии Плети там что-то вроде перевалочной базы. По всей базе разбросаны обломки металла. Собери их и принеси мне, а уж я попытаюсь найти им применение.', 'Принесите 10 обломков металлолома Плети инженеру Риду в Передовой лагерь рыцарей в Зул\'Драке.', 'Это просто негодный металлолом?! Проклятье! Железо Плети нам не подходит. Что будем делать?', 'Я не уверен, что мой план сработает, Жарь. Ты принеси мне эти железяки, а там посмотрим.', NULL, NULL, 'Металлолом Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12902, 'Кто за этим стоит?', 'Бедняги! Они единственные, кто уцелели.$B$BПо словам их предводителя, тролли Драккари и волчеры Яростного Когтя были союзниками на протяжении нескольких тысячелетий. Они жили здесь с давних времен бок о бок с троллями и даже не знали, что происходит в окружающем мире – в мире, который постоянно меняется. Для волчеров Яростного Когтя тролль – всегда тролль, и когда тролли напали на их логово, это стало для них неприятным сюрпризом. Они просто не ждали такого предательства.$B$BНам хотелось бы знать, кто за этим стоит. Кто натравил троллей на волчеров? Иди в их деревню, $N, – она на юго-востоке отсюда – и попытайся найти ответ.', 'Обыщите логово Яростного Когтя и попытайтесь узнать, кто был зачинщиком атаки на волчеров Яростного Когтя.', 'Вы подходите к странному алтарю, над которым парит в воздухе какой-то свиток. Наверное, это именно то, что искал глава рыцарей Лантинга!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12903, 'Для того и нужны друзья...', 'На нас напал принц Навариус и не менее дюжины воинов Плети. Я приказал Даргату и близнецам оставаться в танке, но они не послушались. Даргат посмотрел мне в глаза и сказал: \"Если кто-нибудь не выйдет из этого танка, мы все погибнем\". Потом он велел Риду вырубить двигатель и пошел в атаку. Я в жизни не видел такого героизма.$B$BЯ слышал, как принц отдает команды своим чудовищам. Насколько я понял, они направились к Тупику Трыма, на северо-запад. Нужно спасти наших друзей. Ты нам поможешь?', 'Разыщите рыцаря Даргата, Герка и Бурра по просьбе рыцаря Маккеллара из Передового лагеря рыцарей.', 'Эти трое пожертвовали собой, и их великая жертва не будет забыта. Их смерть не будет напрасной. Мы победим!', 'Я хотел бы помочь тебе в поисках Даргата и близнецов, но я должен остаться здесь и охранять Рида.', NULL, NULL, 'Рыцарь Даргат обнаружен', 'Герк обнаружен', 'Бурр обнаружен', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12904, 'Орудие мести', 'Они... Они убили моего брата.$B$B<Герк с трудом сдерживает слезы.>$B$BЗабили его, словно зверя. А теперь его тело разложено на столе на другом конце лагеря... и над ним будут ставить какие-то жуткие эксперименты. И Даргат тоже мертв. Паладин героически сражался на древних развалинах, что на северо-востоке, но вождь варгулов, Алгар, оказался сильнее.$B$BОстался лишь я, я один, и меня тоже скоро не станет. Я... я уже превращаюсь.$B$BЕсли Свет не дал мне возможности отомстить, может, ты станешь орудием мести, $C. Убей их всех.', 'Убейте 15 варгулов по просьбе Герка из Тупика Трыма в Зул\'Драке.', '<Герк умирает.>$B$BГоворят... говорят, эти варгулы – из тех... кого Король-лич счел ни на что непригодными... и недостойными... Ты... ты только представь... какой мощью должны тогда обладать достойные...$B$BЯ буду молиться за тебя в посмертии, отважный герой... И пусть тебе никогда не придется столкнуться с ними, когда их будет много.', 'Этих чудовищ надо остановить! Ты окажешь поистине неоценимую услугу всему нашему миру.', NULL, NULL, 'Убито варгулов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12905, 'Милдред Жестокая', 'Значит, мы договорились, $N. Ты меня освободишь, а я помогу тебе разыскать твоего зеленого друга.$B$BХильда, которая управляет шахтой, зовется Милдред Жестокая – и на то есть причины.$B$BСкажи ей, что тебя прислали ей в помощь. Делай все, что она говорит, пока не завоюешь ее доверие и она не отдаст тебе ключи от моих кандалов.', 'Поговорите с Милдред Жестокой в Заброшенном руднике.', 'Мне должны были прислать замену для одной из надзирательниц. Так что мы тебя ждали.$B$BДавай сразу же и приступай к работе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12906, 'Поучить уму-разуму', 'Для начала я дам тебе очень простое задание. Мужчины-врайкулы, которые работают на наших рудниках, работают на нас против воли, исключительно из страха перед нашими клинками.$B$BНо иной раз случается, что кто-то из них забывает о том, кто здесь главный. Разыщи всех забывшихся врайкулов и поставь их на место.$B$BВозьми этот вразумляющий жезл. Не надо их убивать. Надо просто сделать им очень больно. Обычно этого бывает достаточно... хотя и не всегда.', 'По заданию Милдред Жестокой из Заброшенного рудника накажите 6 обессиленных врайкулов с помощью вразумляющего жезла.', 'Для новенькой – очень даже неплохо. У меня есть еще одно поручение для тебя.', 'Все сделано? Надеюсь, не слишком многие передохли от наказания? Нам нужно побольше рабочих рук...', NULL, NULL, 'Наказано обессиленных врайкулов', 'Вразумляющий жезл', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12907, 'Нужны показательные примеры', 'На каждое действие существует противодействие, сестра. Вот и сейчас ходят слухи, что среди мужчин назревает мятеж...$B$BНам известно, кто подстрекатель. Бородатая свинья по имени Гархал. Убей его... и постарайся, чтобы мужчины при этом присутствовали. Пусть это послужит хорошим уроком для всех остальных. Нарушения субординации мы не потерпим!', 'По заданию Милдред Жестокой из Заброшенного рудника убейте Гархала.', 'Если у меня поначалу и были какие-то сомнения насчет твоей верности, то теперь они все рассеялись. Я думаю, тебе можно доверять. Еще немного – и ты пойдешь на повышение.', 'Ну что? Подстрекатель убит?', NULL, NULL, 'Гархал убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12908, 'Наглая пленница', 'Ты не знаешь жалости. Полезное свойство в наших краях.$B$BУ меня есть еще одно задание для тебя. Одна из пленных врайкулов доставляет мне больше хлопот, чем ожидалось.$B$BОна имела наглость заявить, что у нее есть право участвовать в Круге хильд – нашем священном соревновании в силе и воинской доблести.$B$BВот ключ от ее кандалов. Только не мучай ее – она все-таки женщина, пусть даже и не из наших.', 'Отнесите ключ Милдред Лок\'лире Карге в Заброшенный рудник.', 'Я знала, что ты вернешься! Сними с меня эти оковы, и я помогу тебе найти гоблина.', 'Наконец-то.', NULL, NULL, 'Ключ Милдред (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12909, 'Острый нюх', 'Для того чтобы выследить Бранна, нам нужно животное с острым нюхом и умением брать след. Охотничий пес – это было бы идеально, но на дирижабле их не было. Однако я, кажется, знаю, кто нам может помочь.$B$BПосле аварии я послал Калииси на восточный склон горы, чтобы она добыла нам провизию. Ее кошка, Ледокус, превосходно выслеживает добычу в снегу. Скажи Калииси, что ей придется на время расстаться со своей верной напарницей. Она может охотиться и в одиночку, а у нас нет никакого другого способа выследить Бранна Бронзоборода.', 'Поговорите с Калииси у подножья горы, на востоке от места крушения Гром\'арша.', 'Стало быть, Боктар подрядил Ледокуса на задание? Очень надеюсь, что это действительно важное дело. Забирать у охотника его зверя, пусть даже на время, для этого нужны очень веские причины!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12910, 'Найти преступника', 'Ладно, пусть в этот раз будет так, как хочет Боктар, но теперь он мой должник, и я потребую с него компенсацию. Что ты так смотришь? Да, Боктар у нас главный, но никто не смеет указывать охотнику, что ему делать.$B$B\"Убери эту зверюгу, – это он так говорит. – И сделай что-нибудь, чтобы она прекратила выть.\"$B$BА когда ему вдруг понадобится помощь, так Ледокус у него самая лучшая и замечательная! В следующий раз, когда он начнет на нее ругаться, Ледокус его точно укусит. Ты не волнуйся, она тебе выследит хоть черта лысого. Но, когда вы найдете тех, кто тебе нужен, разбирайся с ними $gсам:сама: – с железными дворфами, или с Бранном, или кого ты там ищешь.', 'Садитесь верхом на Ледокус и езжайте на юг, взяв след по записке Бранна. Когда вам удастся заполучить переговорное устройство Бранна, свяжитесь с его помощью с Бранном Бронзобородом.', '<Вы активируете переговорное устройство и видите проекцию дворфа. Это может быть только Бранн Бронзобород.>$B$B<Судя по его лицу, Бранн совсем не ожидал вас увидеть. Он принимается бешено жестикулировать.>', 'Кто... кто ты?', NULL, NULL, 'След прослежен до источника', 'Следопыт Тулин убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12912, 'Приближение великой бури', 'Ты не $gтакой:такая:, как все остальные, $gмалыш:малышка:. От тебя не несет древней смертью. Наверное, тебе можно доверять.$B$BЯ – Гимер, король штормовых великанов. Сюда меня заманил мой брат Тиасси, который теперь стал нежитью-прислужником Короля-лича. Когда я понял, что его крик о помощи был уловкой, чтобы заманить меня в ловушку, было уже слишком поздно. Теперь я – пленник Плети, и, боюсь, меня ждет та же печальная участь, что постигла многих штормовых великанов.$B$BПридумай способ, как мне выйти из этой клетки, и я помогу тебе. Сделаю все, что в моих силах.', 'Придумайте способ, как освободить из клетки Гимера, короля штормовых великанов. Поговорите с инженером Ридом в Передовом лагере рыцарей.', 'А... Штормовой великан? Даже не знаю, $N. С одной стороны, дело рискованное... А с другой стороны, выбора у нас нет.$B$BЯ помогу тебе освободить этого великана, если ты пообещаешь уговорить его, чтобы он помог нам в войне против Навариуса и его дружков.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12913, 'Говори по-орочьи!', '$gБранн принимается бешено жестикулировать и говорить на своем родном языке.>$B$BРук МогОт ред а могот та эфт Трос-гарЕ Халдир.$B$BХа гор рук хаз та ке рук хрим эфт трос-ам-ха рук кост-ум хавар го кост.$B$BА модосс хире рук бергум эфт трос-ам-ха га элф Халдир ке лох Тон ве ло гефрунон та митта.$B$BГар Рук дагУм лох ангор-маги та хар рук!$B$B<Вы понимате, что ничего не понимаете. Быть может, шаман Мотеха Дитя Ветра, на месте крушения Гром\'арша сможет как-то решить эту проблему.:', 'Отправляйтесь на место крушения Гром\'арша и узнайте, не сможет ли Мотеха Дитя Ветра вам помочь.', 'Барток совсем не обрадуется, что ты не сумел найти Бранна, но ты хотя бы вернулся не с пустыми руками. Давай посмотрим, что можно сделать по поводу этой дворфской тарабарщины.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12914, 'Спасение Гимера', 'Говоришь, его держат в запертой клетке высотой в 100 футов?$B$BЕсли мои расчеты верны, мы можем, как минимум, расшатать петли на двери, а остальное великан доломает сам.$B$BНо для того, чтобы все получилось, мне понадобятся пластификаторы и стабилизаторы.$B$BВ качестве пластификатора отлично пойдет субстанция банши. Ее можно добыть у банши на Мертвых полях, что на северо-востоке отсюда. Стабилизатор можно найти у землегневов, это на юго-западе, у Черной Заставы.$B$BОтправляйся немедленно!', 'Принесите 6 субстанций банши и 6 комьев диатомовой земли инженеру Риду в Передовой лагерь рыцарей в Зул\'Драке.', 'Хорошо, что у нас есть запасы взрывчатки. Теперь, когда ты принес необходимые материалы, изготовить огромный сефориевый заряд не составит труда.', 'Без пластификаторов и стабилизаторов я не смогу изготовить взрывчатку, чтобы освободить твоего друга из плена.', NULL, NULL, 'Субстанция банши', 'Диатомовая земля', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12915, 'Возобновление старых связей', 'Если я собираюсь отвоевать Храм Творцов у моего брата, мне нужно помириться с прежними союзниками.$B$BМожет быть, если мы уничтожим общего врага, это будет уже большой шаг в восстановлению дружбы со снежными великанами.$B$BФьорн осадил Дун Ниффелем со своей армией железных великанов. Мы должны уничтожить его у Наковальни Фьорна, что к востоку отсюда, и ослабить его войско, чтобы Сыны Ходира смогли вырваться из осады.$B$BВозьми этот амулет, $N. Используй его, чтобы вызвать себе на подмогу моих воинов земли. Когда сделаешь все, что нужно, возвращайся ко мне.', 'По заданию Торима из Храма Штормов убейте Фьорна и 5 железных великанов из клана Закаленных Бурей у Наковальни Фьорна к востоку от Дун Ниффелема. Чтобы вызвать на подмогу воинов земли, воспользуйтесь оберегом земли Торима. Чтобы его задействовать, нужен гранитный валун из Наковальни Фьорна.', 'Стало быть, с ним мы покончили.$B$BБудем надеяться, что этого достаточно.', NULL, NULL, NULL, 'Фьорн убит', 'Убито железных великанов из клана Закаленных Бурей', 'Оберег земли Торима', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12916, 'Наша единственная надежда', 'Я дам тебе сефорий – крайне неустойчивое взрывчатое вещество с уникальными свойствами. Оно очень мягкое и пластичное, и его можно замазать в петли и трещины клетки, чтобы причинить максимальный ущерб.$B$BВозвращайся к своему другу и освободи его с помощью огромного сефориевого заряда.$B$BБудем надеяться, что он сдержит слово и выполнит свои обязательства по договору. Он – наша единственная надежда.', 'Поговорите с Гимером в Тупике Трыма в Зул\'Драке после того, как освободите его из клетки Плети с помощью огромного сефориевого заряда.', 'СВОБОДА!$B$BНе бойся, малыш. Гимер – честный великан и всегда держит слово. У нас одна цель. Я тоже хочу, чтобы воинов Плети изгнали из этих краев, и чтобы Король-лич был уничтожен. Я обещал помочь – и я помогу. Сделаю все, что в моих силах.', 'Я – гигант мысли и великан слова, малыш.', NULL, NULL, 'Клетка Плети взорвана', 'Огромный сефориевый заряд', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12917, 'Поймай голос ветра!..', 'В общем-то, нам и не стоило надеяться найти Бранна так быстро. Не с нашим везением... Но если мы сможем понять, что говорит Бранн, тогда, может быть, у тебя получится уговорить его рассказать, где он прячется.$B$BСила ветра в этих горах велика, и это может оказаться для нас преимуществом. Знающий шаман способен расслышать в шуме ветра звуки всех языков, существующих в мире.$B$BНа северо-западе, на Снежных равнинах, обитают странники бурь – существа, сотканные из ветра. Завладей их голосами и принеси их мне.', 'Поймайте 5 голосов ветра, Мотеха Дитя Ветра на месте крушения Гром\'арша ждет, чтобы вы их принесли.', 'Должно быть, тебе удастся связаться с дворфом сейчас. Спроси Боктара, что ему от тебя нужно. И не будем терять времени. У нас его и так мало.', 'Ты поймал голоса ветра?', NULL, NULL, 'Голос ветра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12918, 'Огранка камней', 'Боги, тут холоднее, чем в пасти ледяного змея! Мало того, что покупатели не торопятся заказывать у меня побрякушки – так еще и запасы драгоценных камней практически иссякли! Знаешь, если бы ты $gпринес:принесла: мне несколько необработанных камней, я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.', 'Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Унгуло в Валгард.', 'Да, этого вполне хватит для пополнения моих запасов. Пожалуй, я не только обучу тебя искусству огранки, но и покажу тебе, как превратить один из этих камней в превосходную драгоценность.', 'Такая щедрость должна быть вознаграждена! Взамен ты узнаешь секреты огранки камней.', NULL, NULL, 'Огромный цитрин', 'Темный нефрит', 'Сумрачный кристалл', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12919, 'Месть короля Бурь', 'Король-лич уничтожил моих людей. Теперь силы Плети используют тела штормовых великанов, чтобы делать из них безмозглых мясистых великанов или, еще того хуже, чудовищ, сшитых из разных кусков, наподобие Трыма.$B$BЯ не остановлюсь ни перед чем, лишь бы стереть этих мерзавцев с лица земли. Мне нужна твоя помощь. Вместе мы уничтожим воинство Плети, угрожающее Зул\'Драку.$B$BМы перебьем их всех: Навариуса, Алгара и Трыма!$B$BКогда будешь $gготов:готова:, дай мне знать, и мы начнем истреблять этих гадов.', 'Когда будете готовы к битве, скажите об этом Гимеру.Сидя на голове у Гимера, уничтожьте 100 воинов Плети и убейте Алгара Избранного, Трыма и принца Навариуса. В случае успешного исхода доложите об этом серебряному рыцарю Маккеллару из передового лагеря рыцарей.', 'Невероятно! Этот подвиг войдет в историю, $N! Один воин, сидя на голове короля штормовых великанов, перебил целую армию Плети!$B$BИ я это видел своими глазами...', NULL, NULL, NULL, 'Убито воинов Плети', 'Алгар Избранный убито', 'Трым убито', 'Принц Навариус убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12920, 'Вдогонку за Бранном', 'Чего ты ждешь? Языковой барьер успешно преодолен, за что спасибо Мотехе. Свяжись с Бранном Бронзобородом и попытайся узнать, где он прячется и что он задумал.$B$BМожет быть, нам еще удастся хоть что-то спасти.', 'Используйте переговорное устройство Бранна, чтобы связаться с Бранном Бронзобородом. Потом доложите о результатах Боктару Кровавому Безумию, который ждет вас на месте крушения Гром\'арша.Если вы потеряете переговорное устройство Бранна, вам поможет Мотеха Дитя Ветра на месте крушения Гром\'арша.', '<Боктар слушает ваш пересказ разговора с Бранном.>$B$BДворф сказал правду. План Вор\'такха – это совсем не похоже на методы Орды. Если Бранн Бронзобород знает способ, как остановить этих железных дворфов и их покровителя, мы, безусловно, ему поможем.', 'Что ты узнал?', NULL, NULL, 'Поговорить с Бранном', 'Переговорное устройство Бранна', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12921, 'Смена декораций', 'Замечательно. В восточной части рудника есть выход к деревне Бруннхильдар. Иди туда, и там я тебя встречу.$B$BНикто не должен заподозрить, что ты мне помогаешь, и поэтому нас не должны видеть вместе. Я изменю облик с помощью магии. Не волнуйся, $r, мы найдем твоего друга.', 'Поговорите с Лок\'лирой Каргой в деревне Бруннхильдар.', 'Ты здесь... хорошо. Кажется, я знаю, где может быть твой гоблин.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12922, 'Очищающее пламя', 'Под пористой поверхностью мерцает какой-то загадочный металл.$B$BЗная историю этих краев, вы решаете, что было бы очень неплохо показать эту штуку Ториму.$B$BНо сначала было бы благоразумно выжечь весь шлак в Наковальне Фьорна.$B$BНо, когда вы задумываетесь о том, где бы взять горючие материалы в этой заледеневшей пустыне, вам на глаза попадается огненный призрак...', 'Соберите 10 гневных искр с пылающих загробников на Промерзшем озере и с их помощью разожгите огонь в Наковальне Фьорна.', 'Вы кладете металл на наковальню, и как только подносите искры, они выжигают руду.$B$BКогда все прогорает до конца, у вас остается большой кусок металла, который светится собственным светом.', 'Несмотря на ледяной воздух, поверхность наковальни раскалена.', NULL, NULL, 'Покрытый шлаком металл (Прилагается)', 'Гневная искра', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12924, 'Возобновление союза', '$gТорим улыбается – в первый раз за все время вашего знакомства.>$B$BПохоже, тут не обошлось без вмешательства судьбы.$B$BЗнаешь, что ты $gнашел:нашла:? Это то, что осталось от моих доспехов, которые я давным-давно выбросил в припадке горя и оставил на волю стихий.$B$BЛишь Сыны Ходира способны перековать их заново, поскольку они же и создали эти доспехи.$B$BМожет быть, того, что ты $gсделал:сделала:, будет достаточно, чтобы они перестали меня ненавидеть. Разыщи их короля, Йоккума, если он еще жив, и обратись к нему с просьбой о содействии. Надеюсь, тебе удастся завоевать его расположение.', 'Отправляйтесь в Дун Ниффелем и попросите короля Йоккума разрешить воссоздать доспех Торима. Выполнив поручение Йоккума, поговорите с Ньормельдом в Дун Ниффелеме.', 'Похоже, мое мастерство изрядно возросло. Или в легендах об этой наковальне есть немалая доля истины.$B$BЭти доспехи – они получились гораздо лучше, чем в изначальном своем варианте, а материалов на них ушло меньше.$B$BА из того, что осталось, я хочу сделать тебе подарок. В знак благодарности за помощь.', NULL, NULL, NULL, 'Наковальня Фьорна принесена в Дун Ниффелем', 'Очищенный светящийся металл', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12925, 'Верность традициям', 'Король-лич трижды посылал к нам своих эмиссаров. Всех троих расчленили на месте.$B$BНаши сестры в Валькирионе в отличие от нас не хранят верность традициям. Они купились на посулы сил Плети. И теперь, вместо того чтобы отлавливать диких драконов, они их выращивают из гнили и скверны, которые тащат с собой силы Плети.$B$BРаздобудь флаконы масла льда, которые носят с собой хильды Валькириона, и с помощью масла заморозь все пораженные гнилью яйца, которые сумеешь найти. Ходят слухи, что яйца хранятся в вонючем пруду, заполненном гнилью.', 'По заданию Тиры Квиншал из деревни Бруннхильдар отправляйтесь в Валькирион и добудьте у валькирионских претенденток флаконы масла льда. Используйте их, чтобы уничтожить 30 зачумленных яиц протодраконов.', 'Большое спасибо. Нельзя допускать, чтобы кто-то поганил священные традиции наших доблестных предков.', NULL, NULL, NULL, 'Зачумленное яйцо протодракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12926, 'Кусочки головоломки', 'Железные дворфы и их свирепые создания объявили войну всем существам из камня, которых Бранн называет земельниками, и их союзникам-великанам. Свяжись с Бранном и узнай, не нужна ли ему твоя помощь. И самое главное – помни: все, что мы от него узнаем, может стать хорошим подспорьем в нашей борьбе против железных дворфов и их хозяина.', 'Воспользуйтесь переговорным устройством Бранна, чтобы связаться с Бранном Бронзобородом и выяснить, что делать дальше.', 'Как ты быстро! Похвально, похвально... Теперь, когда у нас есть целый диск, нам надо понять, как с его помощью можно открыть первую половину ключа от архива.', 'Ты собрал диск?', NULL, NULL, 'Диск Изобретателя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12927, 'Сбор информации', 'Этот диск, который ты $gсобрал:собрала:... он пустой! Наверное, Хранитель Мимир, который построил эту библиотеку, спрятал всю информацию в другом месте. Осмотри Библиотеку Изобретателя, там нигде нет банков данных?$B$BМожет, диск предназначен для них... Попробуй использовать его на каком-нибудь из банков данных. Может быть, он считывает и записывает информацию с этих устройств. Попробуй сделать, как я сказал, а потом свяжись со мной и расскажи, как успехи. А я тем временем попробую разыскать вторую половину ключа от архива.', 'Воспользуйтесь диском изобретателя, чтобы считать 7 фрагментов секретных данных из банков данных.', '<Бранн смотрит на диск, который вы ему показываете.>$B$BА как я отсюда пойму, записано там что-нибудь или нет?! Опиши мне подробно, что было...$B$B<Вы подробно описываете процесс поиска и считывания данных.>$B$BЗначит, там все работает? Надо отдать должное Хранителю Мимиру. Он – настоящий мастер своего дела.', 'Ну, что там с диском? Тебе удалось считать информацию?', NULL, NULL, 'Получено фрагментов секретных данных', 'Диск Изобретателя (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12928, 'Оболочка Норганнона', 'Идет зарядка диска изобретателя.$B$BДиск заряжен.$B$BЗагрузка аварийного протокола.$B$BАварийный протокол загружен. Пожалуйста, воспользуйтесь диском для активации охранника оболочки Норганнона, архивариуса Мехатона. Оболочка будет предоставлена вам после проверки личности.$B$BЖелаем приятного тысячелетия.', 'Заберите оболочку Норганнона у архивариуса Мехатона.', 'Да, это она! Первая половина краеугольного камня Норганнона. Отлично, Продал. Дозорные из Лиги Исследователей уже столько времени ищут хотя бы какие-то указания, где она может быть. Они не поверят, когда я скажу, что оболочку разыскала бесстрашная |3-6(орчиха)!', 'Ты нашла оболочку Норганнона?', NULL, NULL, 'Оболочка Норганнона', 'Заряженный диск', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12929, 'Земельники Ульдуара', 'Локен захватил Ульдуар и изгнал всех земельников, которые построили этот город и жили в нем столько лет. Но и этого ему было мало. Его железные дворфы не прекращают атаковать изгнанников.$B$BОни укрылись в древнем строении $Nв, которое теперь называют Приютом Глыбоскала, на горе к западу от Библиотеки Изобретателя. Глыбоскал и его собратья отчаянно сражаются с железными дворфами, защищая убежище, но долго им не продержаться. Отправляйся туда и помоги им, $N.', 'Поговорите с Глыбоскалом Камнетесом в Приюте Глыбоскала.', 'Значит, ты знаешь Бранна Бронзоборода? Это наш самый верный союзник из всех, кто создан из плоти и крови. Мы с ним – как братья в нашей общей борьбе против Локена и его приспешников, в борьбе за Ульдуар.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12930, 'Редкоземельный элемент', 'Кажется, целая вечность прошла с тех пор, когда эти молоты били о камень, а не о железо. После того как нас изгнали из Ульдуара, самые слабые из нас погибли, а самые сильные из мастеров возродились уже в качестве воинов.$B$BНо в непрестанных сражениях с железными дворфами гибнут даже сильнейшие.$B$BМы не можем помочь нашим раненым – у нас почти не осталось зачарованной земли. Раньше мы добывали ее в скалах на северо-западе, но сейчас мы не можем пойти туда, потому что нам надо сражаться здесь. Ты нам поможешь?', 'С помощью шахтерской кирки земельника добудьте 7 комков зачарованной земли и принесите 5 отрезов ледяной ткани Глыбоскалу Камнетесу в Приют Глыбоскала.', 'Хороший запас. С ним мы поднимем на ноги многих раненых воинов. Спасибо, Консер, спасибо от имени всех, кто защищает этот приют.', 'Ты принес землю?', NULL, NULL, 'Зачарованная земля', 'Ледяная ткань', 'Шахтерская кирка земельника', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12931, 'Контратака', 'Защитники приюта делают все, чтобы сдержать натиск железных дворфов, но те все равно нас теснят. Мои люди, конечно, крепки и выносливы, но они все-таки не железные. Если к нам не придет подкрепление, мы не выстоим. Они нас просто задавят числом.$B$BПоможешь нам защитить убежище? Надо как-то поднять боевой дух моим воинам и дать им возможность собраться с силами, чтобы пойти в контратаку.$B$BУбей столько дворфов из клана Закаленных Бурей и их созданий, сколько сумеешь найти за пределами приюта.', 'По заданию Глыбоскала Камнетеса убейте 10 мародеров или разорителей из клана Закаленных Бурей и возвращайтесь к нему в Приют Глыбоскала.', 'Твои подвиги, безусловно, подняли боевой дух моих воинов. Теперь они будут сражаться с удвоенным рвением.', NULL, NULL, NULL, 'Убито бойцов из клана Закаленных Бурей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12932, 'Амфитеатр Страданий: Иггдрас!', 'Вот что я тебе скажу, $gприятель:красавица:: это тебе не равнины Награнда. Здешние тролли даже грязнее, чем огры. Но я всегда там, где золото, да! Так что добро пожаловать в Зул\'Драк, $gдружище:подруга:.$B$BТы тут $gновенький, еще не освоился:новенькая: еще не освоилась;, но я тебя быстро введу в курс дела. Я – владелец бойцовского клуба. Этот отважный тролль рядом со мной – Водин, мой телохранитель. Ты – инструмент для развлечения зрителей. Когда захочешь подраться, дай мне знать, и я организую поединок.$B$BЕсли ты чувствуешь, что $gготов:готова:, и у тебя есть с собой пара-тройка друзей, можно устроить все прямо сейчас. Ну, что скажешь?', 'Выйдите на арену в Амфитеатре Страданий и победите Иггдраса! Потом вернитесь к троллю-прислужнику Водину и получите награду.', 'Неплохо, приятель. У тебя есть все данные, чтобы хорошо заработать на этом деле – если сумеешь остаться в живых.', 'Награда – по окончании боя, приятель.', NULL, NULL, 'Иггдрас побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12933, 'Амфитеатр Страданий: магнатавр!', 'Следующий бой обещает быть жестким, $gдружище:подруга:. Как я понимаю, какому-то магнатавру из Драконьего Погоста пришла охота подраться. Тебе приходилось сражаться с подобными противниками? Скажу только одно: целься повыше!$B$BКогда будешь $gготов:готова:, дай мне знать, и мы сразу начнем.', 'Выйдите на арену в Амфитеатре Страданий и победите Смрадоборода! Потом вернитесь к троллю-прислужнику Водину и получите награду.', 'Ух ты! Когда я впервые увидел Смрадоборода, я подумал, тебе конец! Но ты молодец!', NULL, NULL, NULL, 'Смрадобород побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12934, 'Амфитеатр Страданий: существо из другого мира!', 'Скажу тебе правду, $gдружище:красавица:. В этом бою у тебя будет соперник, который вряд ли тебе по силам. Существо из Обители стихий! Я даже не знаю, что выйдет сейчас на арену!$B$BЕсли считаешь, что справишься, тогда выходи драться и всыпь ему по первое число!', 'Выйдите на арену в Амфитеатре Страданий и победите повелителя элементалей! Потом вернитесь к троллю-прислужнику Водину и получите награду.', 'Невероятно! Когда он вышел, я думал, что весь Амфитеатр взорвется! Но ты был явно сильнее!', NULL, NULL, NULL, 'Повелитель элементалей побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12935, 'Амфитеатр Страданий: Клыкаррмагеддон!', 'Твой следующий соперник явился из темного и нехорошего места. Это тьма потустороннего мира. Терзаемый голодом, он будет стремиться к победе любой ценой! Будь $gосторожен:осторожна:! Говорят, он сражается с йети просто ради разминки!$B$BКогда будешь $gготов:готова:, мы начнем.', 'Выйдите на арену в Амфитеатре Страданий и победите Ориноко Клыколома! Потом вернитесь к троллю-прислужнику Водину и получите награду.', 'А я уже начал слегка беспокоиться, $N. Когда он спустил на тебя всех тюленей и пингвинов... Честно сказать, я не знал, что и думать. Смотрелось, надо сказать, нелепо.', 'Награда – по окончании боя, приятель.', NULL, NULL, 'Ориноко Клыколом побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12936, 'Амфитеатр Страданий: Коррак Кровопуск!', 'Ты не поверишь, $gприятель:красавица:. В следующем поединке твоим соперником будет сам Коррак Кровопуск! Похоже, тролли Драккари решили сыграть по-крупному! Я тебя сразу предупреждаю: он пил настойку звериного бога. Он хороший боец и настроен на то, чтобы вбить тебя в землю.$B$BТы $gготов:готова: с ним сразиться?', 'Выйдите на арену в Амфитеатре Страданий и победите Коррака Кровопуска! Потом вернитесь к троллю-прислужнику Водину и получите награду.', 'А ведь я помню Коррака еще со времен моей юности, когда я работал на клан Северного Волка. Его было вообще не заткнуть! Думаю, ты оказал всему миру поистине неоценимую услугу, $N.', 'Награда – по окончании боя, приятель.', NULL, NULL, 'Коррак Кровопуск побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12937, 'Исцеление раненых', 'Защитники приюта сражаются храбро, но с натиском железных дворфов они не справляются.$B$BС помощью земли, что ты $gсобрал:собрала:, я смогу сделать повязки, которые помогут исцелить раны некоторых бойцов. Чем больше защитников мы сможем перевязать и поднять на ноги, тем дольше тут продержимся.$B$BВозьми эти земляные примочки и с их помощью исцели раны защитников, павших у приюта. Подними столько бойцов, сколько сможешь, $N. Нам не нужно бессмысленных потерь.', 'Используйте земляные примочки, чтобы вылечить 8 раненых земельников-защитников, потом возвращайтесь к Глыбоскалу Камнетесу в Приют Глыбоскала.', 'Воины, которых ты исцелил, вновь встанут в строй, и мы сможем сдерживать натиск врага еще какое-то время. Но, если мы хотим победить железных дворфов, нам надо придумать, как ударить в них с тыла.', NULL, NULL, NULL, 'Исцелено раненых земельников-защитников', 'Земляные примочки', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12938, 'Герцог', 'Нам нужна твоя помощь, $N. Мы еле-еле удерживаем Мрачный Свод. Как ты понимаешь, мы изрядно разозлили Короля-лича.$B$B<Барон фыркает.>$B$BПоговори с герцогом Ланкралом. Сейчас он здесь главный. Ты найдешь его в здании склепа.$B$BНе заставляй его ждать.', 'Поговорите с герцогом Ланкралом в Мрачном Своде.', 'Рад наконец познакомиться с тобой лично, Пыгык. Мы очень многим тебе обязаны, но нам снова нужна твоя помощь.$B$BСразу за этими горами, на западе, находится город врайкулов – Йотунхейм.$B$BЭти врайкулы только и делают, что затевают поединки, чтобы \"вознестись\", как они это называют. Победители отправляются в Имирхейм и становятся имирьярами, элитными воинами Короля-лича, а побежденных низводят до низшей касты – варгулов.$B$BПозаботься о том, чтобы у них стало больше варгулов, нежели имирьяров.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12939, 'Вызов чести', 'Наша первая операция пройдет на Диком уступе. Это такое место в Йотунхейме, сразу за горной грядой на западе.$B$BНа этой гряде солдаты врайкулов совершенствуются в боевых искусствах и проводят тренировочные поединки под руководством лучших воинов тана.$B$BВозьми это знамя и вызови на поединок нескольких воинов-врайкулов. Покажи им \"скромные\" приемчики, которыми владеет $gлюбой:любая:$r. Это их деморализует!$B$B<Герцог усмехается, его черные гнилые зубы тускло поблескивают в сумрачном освещении склепа.:', 'Возьмите флаг вызова, вызовите на поединок и победите 6 мьординских бойцов по просьбе герцога Ланкрала из Мрачного Свода.', 'Мне уже доложили о твоих доблестных подвигах на Диком уступе. Замечательно, $N... замечательно!$B$B<Герцог вновь улыбается своей гнилозубой улыбкой, и вам кажется, вы слышите, как у него в голове скрипят шестеренки.>$B$BЯ так понимаю, сейчас самое время написать декрет с нашими условиями для тана этих врайкулов, которых ты так легко победил.', NULL, NULL, NULL, 'Вызовите на бой и победите мьординов-бойцов', 'Флаг вызова', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12940, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12941, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12942, 'Черные крылья', 'Предательницы. Мы, хильды, всегда их недолюбливали!$B$BДавно пора наказать обитательниц Валькириона. Мы сохранили верность Ториму, а они стали комнатными собачонками Короля-лича!$B$BПринявшие дар Короля зовутся валь\'кирами. Они парят на оперенных крыльях, подобно гарпиям.$B$BВалькирион расположен на северо-западе, за Храмом Штормов. Отправляйся туда и убей этих крылатых волчиц, сестра. Убей всех, кого сможешь. А потом возвращайся сюда и получишь хорошее вознаграждение.', 'По заданию Ивы Мстительной из деревни Бруннхильдар отправляйтесь в Валькирион и убейте 12 рождающихся валь\'кир.', 'Валь\'киры, эти комнатные собачонки Короля-лича... бесчестные, ничтожные твари! Они сделали свой выбор, а теперь пусть поплатятся за него!', NULL, NULL, NULL, 'Рождающаяся валь\'кира убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12943, 'Указ Мрачного Свода', 'Тан Уфранг Могущественный засел в своем зале с видом на Дикий уступ. Я неплохо его изучил. Тан – терпеливый врайкул, неплохой стратег и воин. Насколько я его знаю, он постарается выбрать наиболее благоприятное время, поскольку не склонен переоценивать свои возможности в грядущей битве.$B$BОн нужен мне мертвым!$B$BЯ составил декрет. Зачитай его тану.$B$B<Герцог усмехается.>$B$BЭто заставит его... ну, как минимум, занервничать.', 'Зачитайте указ Мрачного Свода, составленный герцогом Ланкралом, тану Уфрангу Могущественному, после чего убейте Уфранга.', '<Герцог Ланкрал одобрительно кивает, выслушав ваш доклад об успешном выполнении задания.>$B$BМы сражаемся с врагом, который во всех отношениях больше нас: и по численности, и по росту. Чтобы победить в этой битве, мы должны их обхитрить. Взять умом, а не силой!$B$BТеперь Уфранг мертв, и это дает нам преимущество в Йотунхейме. А преимуществом надо пользоваться!', NULL, NULL, NULL, 'Тан Уфранг Могущественный убито', 'Указ Мрачного Свода', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12944, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12945, 'Кулек конфет', '', '', 'задание из категории Тыквовин. Награда: Пригоршня конфет. Введено в World of Warcraft: Wrath of the Lich King.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12946, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12947, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12948, 'Чемпион Амфитеатра Страданий', 'Все, $gдруг мой:красавица:, это будет последний бой! Самый последний – и самый трудный. Твой соперник – чемпион среди врайкулов из степей Ледяной Короны, и он жаждет крови! Если сумеешь его победить, ты станешь безоговорочным чемпионом Амфитеатра Страданий! Мы с тобой разбогатеем на этой схватке!$B$BКогда будешь $gготов:готова:, дай мне знать, и мы сразу начнем.', 'Выйдите на арену в Амфитеатре Страданий и победите Владофа Мясника! Потом возвращайтесь к троллю-прислужнику Водину и получите награду.', 'У тебя получилось, $N! Это был замечательный бой, самый лучший из всех! Что будешь делать с призовыми деньгами? Лично я собираюсь отправиться в Даларан и спустить все в Клоаке. Там у них так зажигают! Это надо видеть!', 'Награда – по окончании боя, приятель.', NULL, NULL, 'Владоф Мясник побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12949, 'Ключ от кандалов', '$C, ключ от моих кандалов висит на шее у инструктора Хрёгера там, снаружи.$B$BМожет быть, ты сумеешь добыть этот ключ путем отделения его головы от соответствующей шеи?', 'Добудьте ключ от цепей Вэлена и отдайте его Вэлену Разоблаченному в Зале Уфранга.', 'Спасибо, $R. Давай сюда ключ, а дальше я справлюсь сам.', 'Ключ у тебя?', NULL, NULL, 'Ключ от цепей Вэлена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12950, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12951, 'Известия для барона', 'Самое важное, что ты сейчас сможешь сделать – это вернуться в Мрачный Свод и сообщить барону Раздору, что у меня ничего не вышло.$B$BВидишь ли, я был не единственным пленником этих дьявольских врайкулов. Они захватили весь мой отряд рыцарей смерти.$B$BЯ должен был догадаться... должен был заметить ловушку... но к чему теперь плакать о пролитом молоке?!$B$BУходи, пока они не схватили и тебя тоже! Увидимся в Своде.', 'Поговорите с бароном Раздором в Мрачном Своде.', 'Что?! Мы не можем позволить себе потерять даже одного рыцаря смерти, не говоря уж о целом отряде!!!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12952, 'Огранка камней', 'Мой талант пропадает зря в этом проклятом месте! Столько лет я учился искусству огранки камней – и вот, теперь у меня совершенно нет материалов! Послушай, не $gмог:могла: бы ты принести мне несколько камней в обмен на кое-какие секреты мастерства? Я мог бы поведать тебе, как получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.', 'Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Картеру Тиффенсу в Лагерь Возмездия.', 'Отличные камни! Пожалуй, ты получишь в награду не только мои знания, но и превосходный образец их применения.', 'Да, эти камни подойдут. А теперь садись и слушай: я расскажу тебе кое-какие секреты огранки.', NULL, NULL, 'Огромный цитрин', 'Темный нефрит', 'Сумрачный кристалл', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12953, 'Гори, Валькирион, гори', 'Вот тебе ящик с зажигательными гарпунами. Там, снаружи, стоят гарпунные пушки и стога сена.$B$BМожет быть, Ива оценит твои старания и щедро тебя наградит.', 'С помощью валькирионских гарпунных пушек подожгите 6 валькирионских стогов сена.', 'Вот это мне нравится! Да, у этих предательниц теперь новый хозяин, но они никогда не забудут прощальный подарок своих сестер.', NULL, NULL, NULL, 'Пожаров устроено', 'Зажигательные гарпуны', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12954, 'Амфитеатр Страданий: Иггдрас!', 'А я все думал, когда ж ты придешь, $N! $GЧемпион:Чемпионка; Кольца Крови вновь на арене! Народ валом повалит, можешь не сомневаться! Мы разбогатеем, $gдружище:подруга:! ОЗОЛОТИМСЯ!$B$BЯ тебе вот что скажу: весь Зул\'Драк – это такое большое отхожее место для ледяных троллей. Но кого это волнует, верно? Мы с тобой просто делаем деньги!$B$BТы знаешь правила, $N. Когда будешь $gготов:готова:, дай мне знать, и мы сразу начнем. Устроим им представление!', 'Выйдите на арену в Амфитеатре Страданий и победите Иггдраса! Потом вернитесь к троллю-прислужнику Водину и получите награду.', 'Слушай, а я тебя знаю! Разговоры о твоей блестящей победе в Кольце Крови не умолкали в течение нескольких месяцев! Жалко, что ты не явился на следующий чемпионат, чтобы подтвердить свое звание чемпиона! Хотя, может, оно и правильно. Как говорится, как нажито, так и прожито. По крайней мере, ты до сих пор жив.', NULL, NULL, NULL, 'Иггдрас побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12955, 'Унижение соперников', 'Кх-кх...$B$B<Прыгун откашливается, прочищая горло.>$B$BПрошу прощения. Иногда я не очень понятно изъясняюсь. Ну, ты знаешь, как это бывает.$B$BЯ просто хотел убедиться, что ты помнишь, что надо делать, когда придешь на Дикий уступ в горах на западе отсюда, а именно: вызвать на поединок, побить и тем самым унизить в глазах врайкулов их лучших бойцов.$B$BОсобенно это касается Сигрид Дитя Льда, Ефрема Верного, Тинки Свистопляс и Ону\'Зуна.', 'Вызовите на дуэль и победите Сигрид Дитя Льда, Ефрема Верного, Ону\'Зуна и Тинки Свистопляс по поручению Прыгуна из Мрачного Свода.', 'Это действительно важно, $N. Если им показать, кто сильнее, они сами к тебе не полезут и не будут мешать тебе выполнять наше задание в тех краях.', NULL, NULL, NULL, 'Сигрид Дитя Льда побеждена', 'Ефрем Верный побежден', 'Ону\'Зун побежден', 'Тинки Свистопляс побеждена');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12956, 'Лучик надежды', 'Это явно не просто обычный кусок металла.$B$BВ отличие от обыкновенной руды эта – твердая, но не ломкая, удивительно легкая и вдобавок еще светится собственным светом.$B$BТорим непременно заинтересуется вашей находкой.', 'Отнесите очищенный светящийся металл Ториму в Храм Штормов.', 'Угрюмое лицо Торима озаряется радостью, когда он понимает, что именно вы ему принесли.', 'Что это там у тебя?', NULL, NULL, 'Очищенный светящийся металл (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12957, 'Рабы Закаленных Бурей', 'На юго-западе, в западной части Снежных равнин, у железных дворфов есть шахта. Они свозят туда пленных мехагномов, слуг Хранителя Мимира, и заставляют их добывать руду.$B$BЯ не знаю, откуда взялись эти мехагномы и что они стали бы делать, если бы обрели свободу, но, может быть, они станут нашими союзниками и смогут нам чем-то помочь.$B$BОтправляйся на Замерзший рудник, $N, и освободи пленников. И спроси, может быть, они станут сражаться бок о бок с нами против тирании железных дворфов.', 'По заданию Глыбоскала Камнетеса из Приюта Глыбоскала освободите 6 пленных мехагномов и убейте 3 надсмотрщиков из клана Закаленных Бурей.', 'Я надеялся, что большинство освобожденных пленников все-таки согласится присоединиться к нам, но я не могу их винить. Хороший союзник – это союзник по доброй воле, и мы очень тебе благодарны за помощь.', NULL, NULL, NULL, 'Попытка освободить пленного механогнома', 'Надсмотрщик из клана Закаленных Бурей убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12958, 'Заказ от торговой компании: амулет из кровавого нефрита', 'Одна богатая торговая компания заказала мне коллекцию амулетов из кровавого нефрита для продажи в Нижней Шахте. Если ты принесешь мне амулет, получишь в награду значок даларанского ювелира.', 'Создайте амулет из кровавого нефрита, объединив амулет врайкулов, темный нефрит и кровавый камень, после чего принесите его Тимоти Джонсу в Даларан. Амулет врайкулов можно добыть с любого врайкула в Нордсколе.', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!', 'Ты принес мне амулет из кровавого нефрита для отправки в Нижнюю Шахту?', NULL, NULL, 'Амулет из кровавого нефрита', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12959, 'Заказ от торговой компании: блестящая статуэтка из бивня', 'Одна богатая торговая компания заказала мне коллекцию блестящих статуэток из бивня для продажи в Нижней Шахте. Если ты принесешь мне статуэтку, получишь в награду значок даларанского ювелира.', 'Создайте блестящую статуэтку из бивня черпорога, объединив кальцедоний, сумрачный кристалл и бивень черпорога, и принесите ее Тимоти Джонсу в Даларан. Для того чтобы раздобыть бивень черпорога, вам нужно будет убить черпорога или мамонта в Нордсколе.', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!', 'Ты принес мне блестящую статуэтку для отправки в Нижнюю шахту?', NULL, NULL, 'Блестящая статуэтка из бивня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12960, 'Заказ от торговой компании: брошь Беспощадного солнца', 'Одна богатая торговая компания заказала мне коллекцию брошей Беспощадного солнца для продажи в Нижней Шахте. Если ты принесешь мне брошь, получишь в награду значок даларанского ювелира.', 'Создайте брошь Беспощадного солнца из броши железных дворфов, огромного цитрина и солнечного хрусталя и принесите ее Тимоти Джонсу в Даларан.Брошь железных дворфов можно добыть у любого железного дворфа в Нордсколе.', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!', 'Ты принес мне брошь Беспощадного солнца для отправки в Нижнюю Шахту?', NULL, NULL, 'Брошь Беспощадного солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12961, 'Заказ от торговой компании: изысканная костяная статуэтка', 'Одна богатая торговая компания заказала мне коллекцию изысканных костяных статуэток для продажи в Нижней Шахте. Если ты принесешь мне статуэтку, получишь в награду значок даларанского ювелира.', 'Создайте изысканную костяную статуэтку из кости протодракона, солнечного хрусталя и темного нефрита и принесите ее Тимоти Джонсу в Даларан. Кость протодракона можно добыть с любого протодракона в Нордсколе.', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!', 'Ты принес мне изысканную костяную статуэтку для отправки в Нижнюю шахту?', NULL, NULL, 'Изысканная костяная статуэтка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12962, 'Заказ от торговой компании: Реликвия из сияющей брони', 'Одна богатая торговая компания заказала мне коллекцию реликвий из сияющей брони для продажи в Нижней Шахте. Если ты принесешь мне реликвию, получишь в награду значок даларанского ювелира.', 'Создайте реликвию Сияющей брони из осколка элементальной брони, кровавого камня и огромного цитрина и принесите ее Тимоти Джонсу в Даларан. Осколок элементальной брони можно добыть у любого элементаля-загробника в Нордсколе.', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!', 'Ты принес мне реликвию из сияющей брони для отправки в Нижнюю шахту?', NULL, NULL, 'Реликвия из сияющей брони', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12963, 'Заказ от торговой компании: реликвия Восходящего Солнца', 'Одна богатая торговая компания заказала мне коллекцию реликвий Восходящего Солнца для продажи в Нижней Шахте. Если ты принесешь мне реликвию, получишь в награду значок даларанского ювелира.', 'Создайте реликвию Восходящего Солнца из реликвии Плети, солнечного хрусталя и сумрачного кристалла и принесите ее Тимоти Джонсу в Даларан. Реликвию Плети можно добыть у любого последователя Плети в Нордсколе.', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!', 'Ты принес мне реликвию Восходящего Солнца для отправки в Нижнюю шахту?', NULL, NULL, 'Реликвия Восходящего Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12964, 'Темная руда', 'В Застывшей шахте, в юго-западной части Снежных равнин, у железных дворфов из клана Закаленных Бурей есть рудник, где работают их рабы.$B$BЭто достаточно далеко отсюда, и мы не смогли выяснить, что именно там происходит, но мои разведчики сообщают, что там вроде бы добывают какую-то те$Nю руду тошнотворного вида.', 'Принесите 5 образцов руды Глыбоскалу Камнетесу в Приют Глыбоскала.', '<Глыбоскал тянется, чтобы взять образец руды, но потом отшатывается.>$B$BЭта руда... мне нельзя ее трогать. Она заряжена какой-то противоестественной энергией. Существам, созданным из камня, нельзя к ней прикасаться. Интересно, и что они собираются с ней делать?', 'Ты что-нибудь выяснил насчет этой руды?', NULL, NULL, 'Образец темной руды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12965, 'Дары Локена', 'Предводителя железных дворфов из клана Закаленных Бурей зовут руновидец Валдуран. Говорят, что его хозяин, Хранитель Локен, захвативший Ульдуар, передал Валдурану очень мощные артефакты $Nв.$B$BЭтим, наверное, и объясняется сила и ярость свирепых воинов клана Закаленных Бурей.$B$BОбиталище Валдурана – Нидавелир – находится на юго-западе, по ту сторону Снежных равнин. Отправляйся туда, $N, и попытайся нейтрализовать его силу. Уничтожь дары Локена и помоги нам лишить силы его последователей.', 'Уничтожьте Неистовство Локена, Мощь Локена и Благосклонность Локена, а затем вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала.', '<Глыбоскал мрачно кивает.>$B$BЭто существенно ослабит Закаленных Бурей, но они все равно будут сражаться. Им все равно, сколько их будет убито и ранено – они готовы пожертвовать сотнями, даже тысячами своих, лишь бы стереть нас с лица земли.', NULL, NULL, NULL, 'Неистовство Локена разрушено', 'Мощь Локена разрушена', 'Благосклонность Локена разрушена', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12966, 'Мимо него не пройдешь', '$gЙоккум внимательно выслушивает вашу просьбу, потом долго молчит, обдумывая ответ.>$B$BЗначит, это тебя мы должны благодарить за избавление от Фьорна?$B$BДа, это правда, ты $gпомог:помогла: нам в трудную минуту, но нам еще предстоит потрудиться, чтобы восстановить отношения с Торимом.$B$BЯ позволю Ньормельду заново перековать те доспехи, которые мы подарили Повелителю Бурь давным-давно. Считай это вознаграждением за избавление от Фьорна.$B$BНьормельд сейчас занимается восстановлением наковальни Фьорна. Там ты его и найдешь.', 'По поручению короля Йоккума из Дун Ниффелема разыщите Ньормельда у Наковальни Фьорна.', 'Заново перековать доспех Торима? Да, это возможно.$B$BГлавное – привести в порядок наковальню...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12967, 'Сражение со стихиями', 'Храппи когда-то был гордостью нашего народа. Могучий воин, гроза врагов.$B$BМы почитаем его как героя, хотя он уже не такой, как прежде. Все-таки годы берут свое, и силы Храппи уже не те... Но он по-прежнему горд и бесстрашен и никогда не упускает возможности поучаствовать в битве.$B$BКстати, о битвах... Мы сейчас остужаем наковальню Фьорна, чтобы забрать ее домой, но уцелевшие загробники огня пытаются нам помешать.$B$BПомоги Храппи возродить свою былую славу, $r. Вместе вы победите врагов.', 'По поручению Ньормельда отправляйтесь к наковальне Фьорна вместе с Храппи и помогите ему убить 10 пылающих загробников.', 'Ты молодец, $r. Я непременно скажу королю о твоем славном деянии.$B$BНаковальня уже почти остыла. Увидимся в Дун Ниффелеме!', 'Удалось ли тебе помочь Храппи одержать еще одну победу?', NULL, NULL, 'Убито пылающих загробников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12968, 'Безрассудство Юльды', 'Юльда Опустошительница – ведьма, которая заварила всю эту кашу – пришла прямо в нашу деревню. Ей хватило наглости посягнуть на наши благородные устои, принеся с собой пагубные обещания Короля-лича о безграничной власти.$B$BНе будь ее магия настолько сильной, ей не удалось бы уйти живой. $B$BОтправляйся в Валькирион, там в самом большом жилище найдешь Юльду. Покажи ей, что с нами шутки плохи.', 'По заданию Ивы Мстительной из деревни Бруннхильдар убейте Юльду Опустошительницу в Валькирионе.', 'Юльда сама напросилась. Всякий, кто оскорбит Круг хильд, не останется безнаказанным. Даже если он нашей крови.', 'Ты нашла Юльду?', NULL, NULL, 'Юльда Опустошительница убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12969, 'Это твой гоблин?', 'Думаю, это тот мелкий зеленокожий, которого ты ищешь. На твоем месте я бы поспешила вмешаться, пока эта хильда не разорвала его на части.$B$BКруг хильд в самом разгаре, так что все вызовы должны быть приняты. Ничто не должно помешать тебе занять место этого гоблина.', 'Бросьте вызов Агнете Тирсдоттар, чтобы спасти Зива Искрошипа. Добившись успеха, возвращайтесь к Лок\'лире Карге из деревни Бруннхильдар.', 'Хорошая работа. Похоже, наша сделка принесла удовлетворение обеим сторонам.', 'О, ты снова здесь!', NULL, NULL, 'Агнетта Тирсдоттар убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12970, 'Круг хильд', 'Не знаю, может, это прошло для тебя незамеченным, но, сразив свою первую хильду в рукопашном бою, тебе довелось вступить в Круг хильд – серьезное состязание между хильдами за право властвовать с благословения Торима.$B$BКруг хильд – причина моего содержания в неволе. Я хотела принять участие в состязаниях, но была для этого слишком стара и вряд ли могла бы биться на равных с кем-то из хильд.$B$BУ меня есть к тебе одно предложение, выслушай меня, если это тебе интересно.', 'Выслушайте предложение Лок\'лиры Карги.', 'Договорились. Ты примешь участие в состязаниях Круга хильд и с моей помощью восстановишь великого Торима на его законном месте.', NULL, NULL, NULL, 'Выслушать предложение Лок\'лиры', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12971, 'Вызов принят', 'Начнем. Хорошие новости – в том, что после победы над Агнеттой тебе достается место в следующем круге состязаний.$B$BПлохие новости – в том, что все твои новые соперницы тоже победили кого-то в первом круге. Так что легких побед не жди.', 'Сразите 6 дуэлянтов-победителей по заданию Лок\'лиры Карги из деревни Бруннхильдар.', 'Тебе и это удалось, $N. Тебе удалось одержать победу над несколькими из лучших воительниц, которые только есть у хильд.', 'Да, $N?', NULL, NULL, 'Дуэлянт-победитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12972, 'Тебе понадобится медведь', 'В первых раундах Круга хильд тебе сопутствовал успех. Чтобы продвинуться дальше, тебе понадобится собственный боевой медведь.$B$BК сожалению, хильды их просто так не раздают. Тебе придется выйти $gпобедителем:победительницей: из настоящего сражения, а не гладиаторского боя.$B$BБруннхильдарские хильды жестоко враждуют с Сынами Ходира, бывшими союзниками Торима. Поговори с Бриджаной неподалеку от деревни – быть может, есть способ помочь им и одновременно проявить себя должным образом.', 'Поговорите с Бриджаной неподалеку от деревни Бруннхильдар.', 'Думаешь, мы и тебе дадим такого же медведя? Тебе придется как следует проявить себя, прежде чем ты от нас хоть что-нибудь получишь.$B$BНе надо воображать о себе слишком много только потому, что тебе удалось одержать несколько побед в Круге хильд.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12973, 'Братья Бронзобороды', 'Вот оно! Наконец-то у нас есть краеугольный камень... Какая красота! Я немало попутешествовал по миру, но эта вещь снова приводит меня в восторг. Хотя сейчас явно не время застывать в эстетическом ступоре, восхищаться и ахать я буду потом, а сейчас надо скорее выбираться отсюда!$B$BЗабирайся в мой ветролет и прикрывай нас от железных дворфов!', 'Прикрывайте Бранна и ветролет, пока не доберетесь до Ледяной крепости.', 'Король Грозовое Сердце просил передать тебе слова благодарности за то, что ты помог ему воссоединиться с братьями. Он отправился в поход, чтобы рассчитаться со своими врагами – возможно, ты еще встретишься с ним у подножия трона Артаса.', 'Тысяч извинений, мой мальчик! Я был полностью захвачен моментом и совершенно не заметил тебя...', NULL, NULL, 'Сопроводить Бранна Бронзоборода в Ледяную крепость.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12974, 'Призыв бойцовского клуба', 'Пф-ф, разве это бой?! Это просто парочка неумех, скачущих вокруг знамени.$B$BХочешь узнать, что такое настоящий бой? Потому что, если вдруг есть у тебя такое желание, я тебе подскажу одно место, где все по-серьезному.$B$B<Слышал:Слышала: когда-нибудь о Гаргтоке и Водине – гоблине и тролле, которые держат Кольцо Крови в Запределье? Так вот, они сейчас здесь, в Нордсколе. Хотят открыть новый бойцовский клуб в Зул\'Драке. Если тебе интересно, иди в Зул\'Драк, на восток от леса Хрустальной Песни. Найдешь их на большой арене, в самом центре. Скажи, что тебя прислал Ловкий Викерс!', 'Разыщите Гаргтокa в Амфитеатре Страданий в Зул\'Драке.', 'Тебя прислал Ловкий Викерс?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12975, 'Мемориал', 'Торим наверняка рассказал тебе о трагических событиях, которые нас разделили.$B$BДело было в Громовержье, к северо-востоку отсюда. Замерзшие окаменелости до сих пор служат напоминанием о том черном дне – как и духи погибших, обитающие в этом месте.$B$BЕсли мы собираемся помириться с Торимом и простить его за дела тех давних дней, надо как-то то очистить Громовержье... Быть может, возвести мемориал в память о павших в знак того, что мы всей душой хотим мира.$B$BОтправляйся туда, $r, и собери фрагменты рога Ходира, который разбили в тот день.', 'По заданию короля Йоккума из Дун Ниффелема соберите 8 фрагментов рога в Громовержье.', 'Еще одно доброе дело, которое ты совершил от лица Торима, $C.$B$BЭто поможет смягчить сердце моего народа по отношению к нему.', 'Ты нашел фрагменты рога Ходира?', NULL, NULL, 'Фрагмент рога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12976, 'Памятник павшим', 'Отнеси эти фрагменты Ньормельду. Он использует куски этой священной реликвии для постройки могучего монумента.$B$BПусть он уймет боль в сердцах и излечит обиды и раны моего народа.$B$BПусть он станет ознаменованием новой эры, когда мы вновь будем сражаться на стороне Торима.$B$BИди, $C. Ньормельд ждет тебя.', 'По поручению короля Йоккума отнесите фрагменты рога Ходира Ньормельду в Дун Ниффелем.', '<На глаза Ньормельда наворачиваются слезы, когда он высыпает на наковальню содержимое мешка.>$B$BРог Ходира...$B$BСвященный дар моему народу, который мы получили из рук самого Ходира, $R!$B$BКогда в следующий раз ты придешь в нашу крепость, ты увидишь плоды своих трудов.$B$BПрощай.', 'Ты принес мне фрагменты рога Ходира, $C?', NULL, NULL, 'Фрагменты рога (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12977, 'Зов Ходира', 'Вы сослужили хорошую службу великанам Дун Ниффелема. Без вашей помощи они бы никогда не построили этот монумент.$B$BВы молча смотрите на монумент и осмысляете все его значение. Ваше сердце переполняется чувствами... а в голове появляются мысли и образы... вы чувствуете, как некая неодолимая сила побуждает вас к действию.$B$BПотом это ощущение проходит и вы понимаете, что надо делать. Беспокойные духи Громовержья должны упокоиться с миром.$B$BКогда вы отходите от монумента, вы вдруг обнаруживаете у себя в руках эфирный рог.', 'Убейте 5 ниффелемских прародителей и 5 неупокоенных дворфов из клана Зиморожденных в Громовержье. Протрубите над их телами в рог, затем вернитесь к рогу Ходира в Дун Ниффелем.', 'Вас переполняет чувство покоя и удовлетворения от завершенного дела. Вы точно знаете, что беспокойные духи Громовержья упокоились с миром и их мучения закончились.', NULL, NULL, NULL, 'Освобождено ниффелемских прародителей', 'Освобождено неупокоенных дворфов', 'Рог Ходира', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12978, 'Навстречу буре', 'Я, как и Глыбоскал, когда-то служил хранителям и был мастеровым в Ульдуаре, но после предательства Локена я обратил свой молот против наших новых недругов.$B$BКогда есть возможность, я собираю отряд, мы отправляемся на Нидавелир, чтобы помочь нашим защитникам. Однако долго им не продержаться.$B$BТы $gпоказал себя храбрым солдатом и верным союзником:умеешь сражаться и показала себя верной союзницей:. Может быть, ты возьмешь наше знамя и поведешь наши отряды на Нидавелир, крепость железных дворфов на юго-западе отсюда, на той стороне Снежных равнин?', 'По заданию Брюора Железоруба в Приюте Глыбоскала убейте 10 Закаленных Бурей из Нидавелира. Вы можете убивать воителей клана Закаленных Бурей, волхвов клана Закаленных Бурей или боевых големов клана Закаленных Бурей.', 'Теперь у нас есть надежда на победу, $N. Нам пока что ни разу не удавалось довести до конца наши атаки на клан Закаленных Бурей, но с твоей помощью мы, может быть, и одолеем Валдурана!', NULL, NULL, NULL, 'Убито Закаленных Бурей из Нидавелира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12979, 'Доспехи тьмы', 'Этот темная пластина гораздо толще и крупнее остальных доспехов голема. Быстрый осмотр трупа голема дает все основания предположить, что это дополнительная укрепленная пластина, которую навинтили поверх обычного доспеха.$B$BЗачем железные дворфы добавили эту явно лишнюю деталь к броне своих боевых големов?$B$BМожет быть, Брюор Железоруб сможет ответить на этот вопрос, если вы принесете и покажете ему эти пластины боевых големов клана Закаленных Бурей.', 'Принесите 4 образца темной пластины для доспехов Брюору Железорубу в Приют Глыбоскала.', 'Так, осторожнее. Не подходи слишком близко ко мне. Само присутствие этих пластин в непосредственной близости причиняет мне боль.$B$BНо ты прав, Консер, эти гигантские пластины сделаны для доспехов боевых големов нормальных размеров. Но зачем? Для чего? Есть только один способ это выяснить.', 'Что это там у тебя?', NULL, NULL, 'Образец темной пластины для доспехов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12980, 'Секрет доспехов', 'Какая-то странная латная пластина... Надо узнать о ней как можно больше. Вполне вероятно, что это одно из изделий Валдурана.$B$BОн положил много усилий для добычи, очистки и обработки такого металла.$B$BНа востоке отсюда, на северном склоне горы, есть Мастерская Мимира. Она давно не работает, но если нам повезет, может быть, там остался кто-нибудь из мастеров. Отнеси эту латную пластину туда и постарайся узнать о ней как можно больше.', 'Отнесите темную пластину для доспехов в Мастерскую Мимира и попросите рабочего Тока осмотреть ее. Потом возвращайтесь к Брюору Железорубу в Приют Глыбоскала.', '<Брюор слушает ваш рассказ о том, что вам удалось узнать в мастерской.>$B$BЗначит, хозяин Валдурана дал ему этот зловещий металл, чтобы он сконструировал гигантское оружие? Вполне вероятно, что он собирается использовать его против нас! Его надо остановить, пока он не закончил свою работу.', 'Что ты узнал?', NULL, NULL, 'Латный доспех исследован', 'Темная пластина для доспехов (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12981, 'Жар и холод', 'Глядя на наковальню, вы вспоминаете свои недавние деяния – и особенно те, в результате которых вы сейчас принесли сюда этот артефакт.$B$BВы вдруг понимаете, что нужно сделать еще кое-что. Вся земля на востоке усыпана дымящимися обломками – осколками снарядов, оставшихся после боев.$B$BЕсли получится их остудить и собрать, у снежных великанов будет хороший запас металла, да и очистить район от \"сувениров\" войны – это тоже хорошее дело.', 'Идите к Промерзшему озеру, убейте хрупких загробников, обитающих в тех краях, и с помощью субстанции Льда остудите дымящиеся осколки у наковальни Фьорна. Потом соберите 6 кусков застывшего железа и вернитесь к наковальне Фьорна в Дун Ниффелем.', 'Теперь у вас появляется ощущение завершенного дела. Вы понимаете: то, что вы сделали, укрепит узы возобновленной дружбы между Торимом и Сынами Ходира.', 'Яркое синее сияние окружает наковальню.', NULL, NULL, 'Кусок застывшего железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12982, 'Пленники из ордена Черного Клинка', 'Теперь, когда я вернулся, барон наверняка захочет, чтобы я вновь собрал свой отряд. Армия Короля-лича уже скоро прорвется сюда, и мы не сможем их остановить без моих рыцарей смерти.$B$BТы ведь поможешь мне, $N?$B$BОтправляйся в Йотунхейм и освободи моих людей из этих проклятых клеток.$B$BСломай эти чертовы замки, в выборе средств ты $gсвободен:свободна:. У врайкулов должны быть ключи...$B$BВ общем, делай что хочешь, но освободи моих людей!', 'Освободите 8 пленных рыцарей Черного Клинка по просьбе Вэлена Разоблаченного из Мрачного Свода. Пленников держат в клетках в районе Йотунхейма.', 'Спасибо, $C. С рыцарями смерти, которых ты освободил мы продержимся... значительно дольше.', NULL, NULL, NULL, 'Освобождено пленников из ордена Черного Клинка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12983, 'Последняя из рода', 'Сколько я себя помню, самых лучших медведей мы всегда получали из пещеры зимней спячки на востоке.$B$BНо похоже, теперь все закончилось. Пещеру захватили ненасытные йормунгары, которые истребили всех диких медведей.$B$BНо если ты сумеешь найти уцелевшую медведицу-матриарха, она – гарантирую – будет драться лучше любого медведя, выросшего в неволе.$B$BВозьми с собой в пещеру эту упряжь, и спаси уцелевшую медведицу-матриарха. Удачи тебе.', 'Спасите медведицу-матриарха в пещере зимней спячки по просьбе Астрид Бьорнриттар из деревни Бруннхильдар.', 'Да, впечатляет... Я уже и не думала, что когда-нибудь снова увижу медведицу-матриарха. Тем более такую огро$Nю.', NULL, NULL, NULL, 'Матриарх ледочревов спасена', 'Покрытая рунами упряжь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12984, 'Валдуран Дитя Бури', 'У нас нет выбора, $N. То, что ты $gузнал:узнала: в Мастерской Мимира, означает только одно: нам надо опередить Валдурана, пока он не собрал свое новое оружие.$B$BПрямо сейчас защитники убежища сражаются, чтобы выиграть время и дать нам возможность разобраться с Валдураном.$B$BИди в Нидавелир, это к юго-западу отсюда, по ту сторону Снежных равнин, разыщи Валдурана и попытайся его устранить. Но тебе не придется сражаться с ним в одиночку. Возьми с собой этот боевой рог и протруби в него, когда будешь $gготов:готова: сразиться с предводителем наших врагов. Мы с Брюором тебе поможем.', 'Протрубите в боевой рог Глыбоскала, когда разыщете Валдурана Дитя Бури. Одержите победу над ним и вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала.', 'Наконец-то, Валдуран мертв, и Закаленные Бурей ослабли, но если его похвальба была обоснована, нам придется продолжить биться с Закаленными Бурей и в его отсутствие. Это оружие, что они готовят, может покончить с нами.', 'Мы должны устранить Валдурана до того, как враги захватят убежище!', NULL, NULL, 'Валдуран Дитя Бури убито', 'Боевой рог Глыбоскала', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12985, 'Ковка шлема', 'Здравствуй, $r.$B$BУ меня есть работа, и король Йоккум считает, что ты вполне можешь с ней справиться – если, конечно, тебе все еще хочется заслужить уважение моего народа.$B$BЯ придумал, как можно воссоздать еще один артефакт, который принесет нашей крепости благословение и покровительство Ходира. У меня есть почти все, чтобы приступить к восстановлению. Осталось только добыть глаза наших павших врагов$B$BВозьми кирку и принеси мне глаза мертвых железных великанов, которые остались на поле боя.', 'По заданию Ньормельда в Дун Ниффелеме возьмите кирку с алмазным наконечником, вырвите с ее помощью глаза у мертвых железных великанов у Промерзшего озера и принесите ему 8 глаз Закаленных Бурей.', 'Вот, почти все готово.$B$BКогда шлем будет водружен на место, обитатели Дун Ниффелема будут заранее знать о грядущих опасностях.', 'Ты принес то, о чем я тебя просил, $R?', NULL, NULL, 'Глаз Закаленного Бурей', 'Кирка с алмазным наконечником', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12986, 'Судьба $Nв', 'Ядра Норганнона здесь нет. Я не знаю, зачем ты его ищешь, $r, и знаешь ли ты истинное назначение этой вещи.$B$BМожет быть, я помогу тебе в поисках ядра, но сначала ты помоги мне. Недавно мне довелось узнать о наблюдателе Ториме. Его власть оспаривают, а его судьба остается неопределенной. Это меня беспокоит, поскольку я ничего не знаю о других наблюдателях. Воспользуйся этим банком данных, чтобы исследовать их храмы на северо-востоке, и поделись со мной информацией.', 'По заданию Кретея из Подножия посетите Храм Изобретений, Храм Зимы, Храм Жизни и Храм Порядка. Используйте банк данных для изучения каждого из них.', 'Новости, что ты принес, печальны. Я не знаю ничего о судьбе остальных наблюдателей, но их отсутствие означает темные времена для всех земель Азерота.$B$BЯ изучу информацию, содержащуюся в банке данных, что возвращен мне тобой, и попытаюсь полностью осознать ситуацию. Однако, я считаю, что обладаю знанием, которое ты сейчас сочтешь более уместным, так что раздели со мной мудрость сказанного.', 'Удалось ли тебе добыть информацию, которую я ищу, $C?', NULL, NULL, 'Храм Изобретений обследован', 'Храм Зимы обследован', 'Храм Жизни обследован', 'Храм Порядка обследован');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12987, 'Шлем Ходира', 'Шлем уже выкован.$B$BМы оценили твои усилия, $gмалыш:невеличка:. Хотя еще многое предстоит сделать, мы, Сыны Ходира, благодарны тебе за помощь.$B$BВ знак благодарности ты получишь почетную возможность представить шлем Ходира нашему королю и нашим собратьям.$B$BЛети к острию этого ледяного шипа и прочитай моим людям текст скрижали.$B$BНикогда еще Сыны Ходира не оказывали чужаку такой чести, $C!', 'Летите к острию ледяного шипа в северной части Дун Ниффелема и прочитайте народу Ньормельда текст со скрижалей Утверждения.', '<Ньормельд смотрит на шлем Ходира, заметно растроганный.>$B$BХорошо, крошка-$R.$B$BХорошо...', 'Тебе удалось установить шлем Ходира, $C?', NULL, NULL, 'Шлем Ходира установлен', 'Скрижали Утверждения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12988, 'Штормовые кузни', 'Я изрядно сглупил. Я был уверен, что проект Валурана в Колыбели Нарвира, большой строительной площадке на юге, есть не более чем причудливый памятник жестокости \"Хранителя\" Локена.$B$BТеперь мы знаем правду: это оружие, которое они собираются применить против нас и наших союзников. $N, нельзя допустить, чтобы они завершили изготовление железного колосса. Против него наш приют не устоит.$B$BОтправляйся в Колыбель Нарвира, разыщи штормовые кузни, которые используют умельцы из клана Закаленных Бурей, и уничтожь их.', 'Разрушьте северную штормовую кузню, центральную штор$Nю кузню и южную штор$Nю кузню с помощью бомб Глыбоскала. Потом возвращайтесь к Глыбоскалу Камнетесу в Приют Глыбоскала.', 'Отлично сработано! Это, конечно, не остановит железных дворфов, но на восстановление кузниц у них уйдет время. И это время будет работать на нас.', NULL, NULL, NULL, 'Северная штормовая кузня разрушена', 'Центральная штормовая кузня разрушена', 'Южная штормовая кузня разрушена', 'Бомба Глыбоскала');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12989, 'Нашествие тьмы', 'Эти ползучие гады йормунгары захватили почти всю пещеру зимней спячки. Отвратительные создания… отродья Локена, подлого брата Торима.$B$BМы – слуги Торима, и обязаны убивать эту пакость везде, где она нам попадется. Пещеру найдешь на востоке, за деревней.', 'По заданию Астрид Бьорнриттар убейте 8 прожорливых йормунгаров в пещере зимней спячки на востоке от деревни Бруннхильдар.', 'Йормунгары – мерзопакостные создания. Их истребление – благое дело.', NULL, NULL, NULL, 'Прожорливый йормунгар убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12990, 'Червоточина', 'Принеси мне материалы – и я научу тебя обращаться с генератором червоточин.', 'Принесите Джону Лекрафту нужные ему материалы – и вы не только останетесь в живых, но и узнаете новое заклинание.', '', NULL, NULL, NULL, 'Сверхточный арканитовый преобразователь', 'Ториевое устройство', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12991, 'Удар по больному месту', 'У Глыбоскала есть замечательный план, как помешать железным дворфам в Колыбели Нарвира закончить этого железного колосса, и у меня тоже есть одна мысль... Не будет работников – работа встанет.$B$BКолыбель Нарвира располагается на южном склоне холма рядом с Приютом Глыбоскала. Иди туда и убей всех изобретателей из клана Закаленных Бурей, которые встретятся тебе по пути. Быть может, мы с ними во многом похожи, и когда-то мы сами были не лучше, но сейчас они создают оружие, которое угрожает всем нам.', 'Убейте 10 изобретателей из клана Закаленных Бурей и возвращайтесь к Брюору Железорубу в Приют Глыбоскала.', 'Было время, когда я бы не стал никого посылать с поручением, которое выполнил ты, но после достаточно тесного общения с железными дворфами я уже не питаю к ним теплых чувств. Главное, нам удалось помешать врагу, а значит, мы выиграли себе время.', NULL, NULL, NULL, 'Изобретатель из клана Закаленных Бурей убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12992, 'Истребление врайкулов', 'Врайкулов в Йотунхейме надо давить и давить!$B$B$N, займись истреблением этих гадов!', 'Убейте 15 врайкулов в районе Йотунхейма по заданию Злоба из Мрачного Свода.', '$N, ты самый лучший $R!', NULL, NULL, NULL, 'Убито врайкулов из Йотунхейма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12993, 'Колоссальная опасность', 'Ты хорошо $gпотрудился:потрудилась:, чтобы помешать им закончить железного колосса, но, боюсь, это только придало Закаленным Бурей решимости, и теперь они будут работать вдвойне активнее, чтобы скорее закончить оружие.$B$BУже сейчас они завозят туда новых рабочих, и надсмотрщики выжимают из них все силы. И теперь я уже не уверен, что мы сможем помешать привести колосса в действие. В таком случае, нужно знать, что нам грозит. Вернись на юг, в Колыбель Нарвира, и найди документы, в которых описаны наступательные и оборонительные характеристики колосса. Они должны лежать где-то у палаток и кузниц на нижнем уровне.', 'Разыщите документы с наступательными и оборонительными характеристиками колосса и принесите их Глыбоскалу Камнетесу в Приют Глыбоскала.', '<Глыбоскал начинает просматривать документы, и его глаза изумленно распахиваются.>$B$BЯ даже не думал, что железные дворфы на такое способны. Против этого чудовища, если они его соберут, у нашей армии не будет ни единого шанса. К счастью, у них, как я понял, не хватает одной ключевой детали.', 'Ты принес документы?', NULL, NULL, 'Наступательные характеристики колосса', 'Оборонительные характеристики колосса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12994, 'Контрразведчик', 'Вы установили контакт с обитателями Дун Ниффелема, что привело к нескольким неожиданным открытиям.$B$BНапример, вы обрели способность понимать рычание и резкие взвизги повелительницы логова – во всяком случае, вам кажется, что вы ее понимаете.$B$BПохоже, она чует опасность – что-то угрожает крепости извне – и повелительница логова хочет, чтобы вы приняли меры по устранению этой опасности.$B$BПередней лапой она снимает с шеи массивную цепь и бросает ее к вашим ногам. Вы поднимаете цепь и видите, что к ней прикреплен древний пожелтевший клык...', 'Убейте 3 Секретных агентов клана Закаленных Бурей в долине Древних Зим.С помощью клыка астрального ворга призовите призрачного ледяного ворга, который поможет вам обнаружить скрывающихся врагов. По выполнении задания вернитесь к повелительнице логова ледяных воргов в Дун Ниффелем.', 'Когда вы надеваете цепь обратно на шею повелительнице логова, она облизывает вам лицо, выражая тем самым свою благодарность.', 'Повелительница логова ледяных воргов смотрит на вас с любопытством.', NULL, NULL, 'Убито Секретных агентов клана Закаленных Бурей', 'Клык астрального ворга', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12995, 'Наша метка', 'Атака на врайкулов Йотунхейма должна проходить сразу на нескольких уровнях. Грубая сила – это, конечно, неплохо, но я все-таки предпочитаю работать мозгами.$B$BВрайкулов нужно деморализовать, и ты нам в этом поможешь.$B$BМои люди изготовили несколько знамен. Возьми их и воткни рядом с телами павших врайкулов.$B$BПусть эти знамена служат им постоянным напоминанием, что есть и более неотвратимая кара, нежели гнев Короля-лича.', 'По заданию барона Раздора из Мрачного Свода воткните 15 знамен Черного Клинка рядом с телами мертвых врайкулов в районе Йотунхейма.', 'Отлично, $N. Теперь, увидев оскверненные тела своих павших товарищей, они трижды подумают, прежде чем на нас нападать!$B$BЕсли ты придешь завтра, я позабочусь о том, чтобы мои люди подготовили для тебя еще знамена.', NULL, NULL, NULL, 'Воткнуто знамен Черного Клинка рядом с телами врайкулов', 'Знамя Черного Клинка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12996, 'Тренировочный заезд', 'Тебе улыбнулась удача, сестра. Такой могучей медведицы мы не видели уже много лет.$B$BНо как бы ни был хорош медведь, самое главное – это уметь на нем ездить.$B$BДумаю, для начала ты потренируешься на Киргарааке. Это самый крупный из всех йети, которых нам удавалось поймать, так что будь осторожна. И если почувствуешь, что не справляешься, то не бойся уйти... мы не зря держим его в цепях.', 'Воспользуйтесь поводьями матриарха ледочревов, чтобы сразиться с Киргарааком, как вам велела Астрид Бьорнриттар из деревни Бруннхильдар.', 'Неплохо. Я-то надеялась, что Киргараак свернет тебе шею, и я смогу взять себе твою медведицу.$B$BШучу, сестра, шучу. Но в каждой шутке есть доля правды... У тебя действительно замечательная медведица.', NULL, NULL, NULL, 'Киргараак побежден', 'Поводья боевой медведицы-матриарха', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12997, 'В Яму!', 'Победить скованного противника – это одно, а биться с другими наездниками на медведях на равных – совсем другое.$B$BТы уже многому научилась. Отправляйся в Яму Клыка и используй полученные тобой знания для победы. Удачи, сестра.$B$BВ случае успеха тебя ждет слава.', 'Отправляйтесь в Яму Клыка, воспользуйтесь поводьями матриарха ледочревов и победите 6 боевых медведей Круга хильд по заданию Астрид Бьорнриттар из деревни Бруннхильдар.', 'Ты сделала это! И вернулась целой и невредимой! Жаль, что нельзя сказать то же о твоей медведице.$B$BОна еще не скоро поправится. К счастью, она пока что тебе не понадобится.', NULL, NULL, NULL, 'Боевой медведь Круга хильд убито', 'Поводья боевой медведицы-матриарха', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12998, 'Сердце бури', 'Судя по документам, захваченным тобой в Колыбели Нарвира, железный колосс почти закончен, не хватает только последнего ключевого компонента – Сердца бури.$B$BБез него мощь оружия железного колосса будет намного слабее, чем предусмотрено проектом. Если мы спасем Сердце от надзирателя Нарвира, у нас появится шанс уничтожить колосса!$B$BВ примечании к документам сказано, что Сердце находится в Ульдисе, обители $Nв далеко на юге. Вход туда расположен на южном склоне высокой горы над рекой Дыхания Бора.', 'По поручению Глыбоскала Камнетеса из Приюта Глыбоскала отправляйтесь в Ульдис и сделайте все возможное, чтобы надзиратель Нарвир не сумел заполучить Сердце бури.', 'Если Сердце попадет в руки Нарвира, колосс обретет свою полную силу! У нас не останется выбора, нам придется сражаться.', NULL, NULL, NULL, 'Вы попытались защитить Сердце Бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (12999, 'Костяная ведьма', 'Ты же наверняка помнишь леди Найтсвуд, да? Она тебя помнит. Эта та самая одинокая и очень злая банши, которую ты \"$gспас:спасла:\", когда $gвырвал:вырвала: и меня со Злобом из-под власти Короля-лича.$B$BЛеди отправилась в Йотунхейм и вселилась в их костяную ведьму. Таким образом она собирается сеять смуту среди врайкулов – так сказать, изнутри.$B$BОна просила, чтобы ты ее $gразыскал:разыскала: в пещере на южной стороне деревни Ньорндар на юго-западе Йотунхейма.', 'Поговорите с костяной ведьмой в пещере в деревне Ньорндар.', '$N, ты пришел.$B$BЯ уже слышала о твоих достижениях на Диком уступе. Это хорошо. Я рада, что ты согласился помочь с истреблением этих врайкулов в Йотунхейме.$B$B<Губы костяной ведьмы кривятся в усмешке, но через силу, как будто она борется с волей леди Найтсвуд.>$B$BМы с тобой славно повеселимся!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13000, 'Чрезвычайные меры', 'Здесь, в горах, просто зверский холод. Еще день или два, и у нас закончатся все дрова.$B$BВ пещере к востоку отсюда мы заметили воргов. Найди пещеру и добудь их шкуры. Вроде бы мелочь, но вполне может так получиться, что именно этот мех не даст нам замерзнуть до смерти.$B$BВорги охотятся стаями, поэтому я дам тебе сигнальную ракету. Она поможет выиграть время, если силы окажутся неравными.', 'Отправляйтесь в Логово Гиморака на востоке и добудьте 6 шкур воргов по просьбе кровостража Лорги.', 'Ничего себе шкурки... какие большие. Боюсь даже представить тех воргов, с которыми тебе пришлось иметь дело.$B$BБольшое спасибо. Ты нас просто спас. Мороз уже начинает крепчать.', 'Ты принес шкуры?', NULL, NULL, 'Шкура ворга', 'Яркий огонь', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13001, 'Копье Ходира', 'Время пришло, $gмаленький:маленькая:c: $C. Этот день был предсказан по звездам.$B$BМне было видение от всемогущего Ходира. Он открыл мне секрет изготовления великой реликвии, копья Ходира.$B$BИ его надо сделать! Мы погибнем, если не сможем заполучить этот дар.$B$BКак верный слуга клана, я прошу тебя помочь мне в этом священном деле.$B$BОтправляйся в пещеру зимней спячки и набери осколков Вечного льда, а потом добудь шкуры мамонтов, что обитают вблизи пещеры.', 'Добудьте 3 осколка Вечного льда в пещере зимней спячки и 3 шкуры спокойных мамонтов в долине Древних Зим и отнесите все сказителю Рандвиру в Дун Ниффелем.', 'Отойди в сторонку, $R, и смотри, как сбывается пророчество!', 'Ты собрал материалы для копья, $C?', NULL, NULL, 'Осколок Вечного льда', 'Шкура спокойного мамонта', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13002, 'Огранка камней', 'Добро пожаловать в морозилку, $gдружок:подружка:. Хотя тут не слишком тепло, меня греет моя профессия – огранка камней. Не хватает только материалов!B$BТы бы $gнашел:нашла: для меня парочку блестяшек – а я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.', 'Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Геба\'ли в Крепость Песни Войны.', 'Сейчас мы их ограним – будут лучше некуда! Это, знаешь ли, искусство.', 'То, что надо! Теперь я с радостью научу тебя огранке.', NULL, NULL, 'Огромный цитрин', 'Темный нефрит', 'Сумрачный кристалл', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13003, 'Как убить дракона', 'Копье Ходира – символ великой воинской чести и мощи.$B$BВ присутствии этой реликвии в каждом, кто входит в Дун Ниффелем, загорается неутолимая жажда славы. И действительно: вы уже ощущаете неодолимую потребность испытать себя в битве.$B$BВсматриваясь в горизонт, вы замечаете летающего неподалеку дикого змея.$B$BИтак, решено. Из вас двоих только один доживет до рассвета...', 'С помощью копья Ходира загарпуньте дикого змея в долине Древних Зим и сразитесь с ним не на жизнь, а на смерть.', 'Свершилось.$B$BПосмотрев в глаза смерти, ты одержал победу.$B$BБлистательно справившись с грозным зверем, ты принес славу Дун Ниффелему!', NULL, NULL, NULL, 'Дикий змей убит', 'Копье Ходира', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13004, 'Огранка камней', 'Идет война, и каждый из нас должен внести свой вклад в победу! Я, например, занимаюсь огранкой камней, ибо мне под силу не просто обработать обычный камень, но и превратить его в идеальный. Знаешь, если бы ты $gпринес:принесла: мне несколько необработанных камней, я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.', 'Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Алестосу в Крепость Отваги.', 'Спасибо! Теперь я научу тебя резьбе по самоцветам и впридачу подарю один из превосходных камней!', 'Благодарю тебя за помощь нашему делу. А теперь – приступим к обучению!', NULL, NULL, 'Огромный цитрин', 'Темный нефрит', 'Сумрачный кристалл', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13005, 'Клятва детей земли', 'Годами я пренебрегал своим долгом, предаваясь печали и горечи поражения.$B$BА вот мои храбрые земельники оказались покрепче! Они не нарушили свою клятву – ценой своих жизней защищать это место.$B$BДаже сейчас они храбро и самоотверженно сопротивляются тлетворному воздействию железных дворфов, выжидая момент, чтобы переломить ситуацию.$B$BИ этот момент настал. Мы должны сплотить остатки земельников и привести их к славной победе. Звуки рога Вершин призовут их выйти на битву и помогут разгромить неприятеля и отвоевать Террасу Творцов.', 'Используйте рог Вершин, чтобы призвать земельников на битву с железными дворфами и убить 20 железных дворфов и 7 железных часовых по просьбе Торима с Террасы Творцов.', 'Неплохое начало. Но войска моего брата быстро перегруппируются и пойдут в контратаку. Нам нужна окончательная победа.', NULL, NULL, NULL, 'Убито железных часовых', 'Убито враждебных железных дворфов', 'Рог Вершин', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13006, 'Полировка кислотой', 'Вы подходите ближе и видите, что мороз уже оказал свое пагубное воздействие на поверхность шлема. Пока это лишь тонкий слой инея, но уже совсем скоро он превратится в толстую корку льда.$B$BЧтобы ваши усилия не пропали втуне, вы решаете осмотреть местность и попытаться найти решение этой проблемы.$B$BВы отходите на пару шагов и вдруг замечаете, как сверкнули глазницы шлема. В тот же миг в ваших мыслях возникает образ пещеры зимней спячки.', 'Идите в пещеру зимней спячки и соберите 5 сгустков вязкого масла злобных масленышей. Потом возвращайтесь в Дун Ниффелем и натрите маслом шлем Ходира.', 'Вы покрываете шлем тонким слоем масла, иней сразу же отпадает, и шлем начинает сверкать.', 'Иней сгущается на шлеме буквально у вас на глазах, и по краям уже начинают формироваться сосульки…', NULL, NULL, 'Вязкое масло', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13007, 'Железный колосс', 'Нам не удалось помешать им построить железного колосса, $N, а это значит, что у нас не осталось иного выхода, кроме как драться с этим чудовищем.$B$BУ этого колосса есть единственное слабое место, и Вруор придумал план, как на него надавить.$B$BКакой бы толстой ни была броня, кислота йормунгаров разъедает железо. Ими можно управлять при помощи сфер. Возьми одного йормунгара и отправляйся на северный край Снежных равнин. Прочеши всю равнину, найди колосса и сделай так, чтобы твой йормунгар дохнул на него своим кислотным дыханием. Если тебе нужна помощь в укрощении этих существ, поговори с одним из дрессировщиков.', 'Уничтожьте железного колосса с помощью прирученного йормунгара, а потом возвращайтесь к Глыбоскалу Камнетесу в Приют Глыбоскала.', 'Мы сделали это, мы справились! И Приют цел, и Закаленные Бурей разбиты! Надо предупредить Бранна, прежде чем Локен опомнится и наберет новое войско. Мы должны закрепить сегодняшнюю победу, а для этого надо отправиться в Ульдуар и окончательно разгромить Локена!', 'Ты уничтожил железного колосса? Приюту уже не грозит разрушение?', NULL, NULL, 'Железный колосс убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13008, 'Тактика Плети', 'Неожиданность была нашим главным козырем! Подрывники хорошо потрудились. Мы пробили тоннель в горе и ворвались в Плетхольм. Защитники лагеря отчаянно сопротивлялись, и у них было численное преимущество. Мы отступили обратно в долину и вели непрестанный артиллерийский огонь по преследователям. Какое-то время нам удавалось их сдерживать, а потом... эти чудовища стали использовать наших рыцарей, как живые щиты. Нам пришлось прекратить огонь, чтобы не стрелять по своим.$B$BОсвободи наших рыцарей, которых держат на поле за базой, $C!', 'Освободите 8 опутанных рыцарей по заданию командира рыцарей Энтари из Оплота Серебряного Авангарда в Ледяной Короне.', 'На том поле и в самом Плетхольме осталось еще немало солдат Серебряного Авангарда, $N. Я, безусловно, ценю твою помощь, но нам еще многое надо сделать.', NULL, NULL, NULL, 'Освобождено опутанных рыцарей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13009, 'Новое начало', 'Еще неизвестно, сможет ли мой народ позабыть все обиды и вспомнить о том, что когда-то мы с Торимом были соратниками и друзьями.$B$BПусть эти доспехи хотя бы напоминают ему о тех днях, когда мы с честью сражались плечом к плечу, непобедимые.', 'Отнесите перекованные доспехи Торима в Храм Штормов по просьбе Ньормельда.', '<Получив от вас перекованные доспехи, Торим поражен их великолепием.>$B$BТвои успехи бесспорны, $R, но нам предстоит еще многое сделать.', 'Ну, что, $C? Как успехи?', NULL, NULL, 'Перекованный доспех Повелителя Бурь (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13010, 'Кролмир, Молот Бурь', 'Остался всего один шаг до того, как я верну свой дом на Террасе Творцов.$B$BНужно найти Кролмир.$B$BВ тот злосчастный день я швырнул его о землю со всей силой и яростью, на которые был способен. Последовал страшный взрыв.$B$BДолгие годы я считал его утраченным, но теперь мне хотелось бы удостовериться...$B$BВозвращайся к королю Йоккуму и попробуй выяснить – вдруг он что-то знает о судьбе моего молота.', 'Поговорите с королем Йоккумом в Дун Ниффелеме и попробуйте выяснить, что ему известно о Кролмире, принадлежавшем Ториму.', 'Никакие слова не способны выразить мою благодарность, $С.$B$BТы сослужил мне поистине неоценимую службу. Прими это в знак благодарности.', NULL, NULL, NULL, 'Судьба Кролмира выяснена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13011, 'Усмирение Йормуттар', 'У меня есть для тебя поручение. Если справишься, это поможет тебе заслужить уважение моего народа.$B$BЙормунгары представляют серьезную угрозу, и с ними следует разобраться как можно скорее. Если им ничто не препятствует, они плодятся, как кролики, и распространяются, как пожар.$B$BОни появились на юго-западе, в пещере зимней спячки. И если в самое ближайшее время мы не убьем их матку, они захватят все наши земли.$B$BОна вечно голодная и никогда не отказывается от пищи. Возьми этот нож, найди в их пещере свежий труп медведя и срежь мясо с его боков. Положи мясо рядом с кратером, где она обитает, и убей ее, пока она будет кормиться.', 'По приказу короля Йоккума из Дун Ниффелема убейте Йоркуттар в пещере зимней спячки.', 'Стало быть, дело сделано.$B$BМы слышали вопли Йоркуттар. Они разносились по всей долине.$B$BТы сослужил нам хорошую службу, $R.', 'Ты убил Йоркуттар?', NULL, NULL, 'Йоркуттар убито', 'Бритва вечного льда', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13012, 'Предок Сардис', '', '', 'Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $N. Прими этот знак...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
