INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13034, 'Наблюдатель и герой', 'Еще в самом начале своего путешествия в Нордскол я посетил Борейскую тундру и там впервые в жизни увидел таунка. Укротитель ветра Бара рассказал мне о Штормовом Копыте и его битве против Северного Ветра, древнего врага его народа.$B$BЯ отправился к Грозовой гряде, чтобы побольше узнать об этом герое, но вот что странно... в Тунка\'ло о нем даже не слышали.$B$BВозможно, какая-то информация есть в исторических документах в этом лагере? Разыщи и прочти свитки, что хранятся в лагере – а потом перескажи мне все, что удастся узнать.', 'По просьбе Ксанатавра из лагеря Тунка\'ло прочитайте Первый, Второй и Третий свитки.', 'Как интересно… Это совсем не похоже на историю, которую мне рассказал укротитель ветра Бара.', 'Ты узнал, что написано в исторических документах лагеря Тунка\'ло?', NULL, NULL, 'Первый свиток прочитан', 'Второй свиток прочитан', 'Третий свиток прочитан', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13035, 'Прислужники Локена', 'Мой брат отправил на штурм Террасы Творцов отборные войска: легион железных дворфов и своих лучших командиров.$B$BВоспользуйся рогом Вершин, чтобы призвать земельников себе на помощь и победить прислужников Локена.$B$BВеликана Айзенфауста ты найдешь на севере, в Зале Творца. Остальные засели в глубине Террасы Творцов, за лестницей, ведущей на северо-запад.', 'Убейте Айзенфауста в Зале Творца, а также Халефнира Дитя Ветра и Даррона Рунокова на Террасе Творцов по просьбе Торима.', 'Один за другим, все прислужники моего брата повержены. Уже совсем скоро мятеж Локена будет подавлен.', NULL, NULL, NULL, 'Айзенфауст убито', 'Халефнир Дитя Ветра убито', 'Даррон Руноков убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13036, 'Великая миссия', 'Наш путь к спасению был долог и труден, $C. Для того чтобы добраться сюда, нам пришлось много сражаться – на всех континентах, во всех мирах! И теперь нам предстоит выполнить самую главную миссию: победить Короля-лича и Плеть.$B$BНо, увы, мы одиноки в своей борьбе. Орда и Альянс нам не помогут – у них своя собственная война. Однако мы не должны падать духом! Мы будем сражаться до конца! А иначе зачем вообще сражаться?$B$BТы будешь нашим союзником? Твоя отвага и сила могут нам пригодиться, $C! Мой командир, Энтари, ждет тебя у себя на заставе.', 'Поговорите с командиром рыцарей Энтари в Оплоте Серебряного Авангарда в Ледяной Короне.', 'Там, где были бессильны Орда и Альянс, Серебряный Авангард добился успеха. Успех, однако, был очень недолгим. Наш прорыв на Ледяную Корону получил мощный отпор.$B$BОтветный удар Короля-лича последовал незамедлительно, и удар был жестоким. И теперь нам пришлось занять оборонительную позицию.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13037, 'Воспоминания о Штормовом Копыте', 'Когда бронзовые драконы подарили мне бессмертие и наставили на путь наблюдателя, Ноздорму вручил мне Молот Знаний.$B$BОтклик молота на твои находки означает, что время здесь искажено, и наш долг – восстановить подлинную линию времени.$B$BА для этого нам надо ее найти. Отправляйся на северо-запад, в Ледяные глубины, где находится древнее захоронение воинов Тунка\'ло. Разыщи дух вождя Быстрое Копье, брата Штормового Копыта. Попроси его вспомнить о битве его брата с Северным Ветром.', 'Поговорите с вождем Быстрое Копье в Ледяных Глубинах и возвращайтесь к Ксанатавру в лагерь Тунка\'ло.', 'Даже вождь начинает терять память? Прошлое переиначивается прямо у нас на глазах, и если нам не удастся узнать, кто за этим стоит, все наследие Штормового Копыта будет утрачено навсегда!', 'Что рассказал тебе дух вождя Быстрого Копья?', NULL, NULL, 'Расспросить вождя Быстрое Копье о его воспоминаниях', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13038, 'Искажения времени', 'Эта гробница, захоронение воинов Тунка\'ло, всегда считалась священным местом, свободным от террора стихий.$B$BОднако некая странная сила проникла в Ледяные Глубины – сила, которая нарушает покой духов павших и как будто стирает мне память.$B$BКак будто кто-то пытается переиначить историю и убрать из нее наши деяния и воспоминания.$B$BПри жизни этот тотем служил символом моей власти. Сейчас это последнее связующее звено между мною и этим миром. Возьми его и сделай так, чтобы духи павших упокоились с миром, а потом верни его в лагерь Тунка\'ло.', 'Закройте 4 расселины в Ледяных глубинах с помощью тотема вождя, а затем отправляйтесь в лагерь Тунка\'ло и отдайте тотем Ксанатавру.', 'Дух вождя велел тебе принести это мне?$B$B<Ксанатавр внимательно рассматривает тотем.>$B$BАга, кажется, я понимаю, в чем дело. Когда он сказал, чтобы ты воспользовался тотемом, чтобы закрыть расселины в Глубинах, он дал нам подсказку к разгадке того, что происходит с линией времени. Мудрый вождь, этот Быстрое Копыто. Даже в посмертии он заботится о своих сородичах.', 'Что ты принес из гробницы?', NULL, NULL, 'Закрыто расселин в Ледяных Глубинах', 'Тотем вождя (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13039, 'Оборона аванпоста', 'Мы уже не справляемся, $gдруг:милая леди:. Когда они пробили брешь, шлюзы открылись. Плеть валит сюда бесконечным потоком.$B$BНам не хватает людей. И мы рады любому, кто способен сражаться и согласен помочь нам сдержать поток зла. Вставай в строй, $gдружище:воительница:, и убивай этих чудовищ. Чем больше, тем лучше!', 'Убейте 15 нерубов Забытых глубин по просьбе лорда Далфорса из Оплота Серебряного Авангарда в Ледяной Короне.', 'Сколько же их там?! Мы перебили их столько, что хватит на десяток погостов, а они все идут и идут. Как-то мне это не нравится.', 'Не сдавайся, $N!', NULL, NULL, 'Убито нерубов Забытых глубин', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13040, 'Исцеление неисцелимого', 'У нас с каждым днем прибавляется раненых, у всех – сильное отравление. Причем с таким ядом мы раньше не сталкивались. Я не знаю, что там за пакость в ядовитых железах у нерубов; известно только, что их яд смертелен и не поддается никаким целительным снадобьям. Пока что нам удавалось только замедлить процесс общего отравления. Но нам нужно найти противоядие!$B$BИди на северо-запад, в долину рядом с аванпостом, и убей десятка полтора нерубов Забытых глубин. Вырежи их ядовитые железы и принеси мне.', 'Принесите 10 ядовитых желез душителей Забытых глубин отцу Густаву в Оплот Серебряного Авангарда в Ледяной Короне.', 'Спасибо, $N. Я немедленно примусь за их изучение. Надеюсь, я смогу найти противоядие – и уже в самое ближайшее время.', 'Ты добыл ядовитые железы, $R?', NULL, NULL, 'Ядовитая железа Забытых глубин', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13041, 'Недостающий камень', 'Как удачно, что ты $gзашел:зашла:! Груз блестящих статуэток из бивня уже отправляется в Нижнюю Шахту, а мне, как назло, не хватает кальцедония – закончить глаз у последней статуэтки. Принеси мне кальцедоний, и я дам тебе еще один значок даларанского ювелира.', 'Принесите кусок кальцедония Тимоти Джонсу в Даларан.', 'Вот тебе значок даларанского ювелира, как и было обещано. У меня постоянно бывают большие заказы, так что ты время от времени заходи – мне может понадобиться твоя помощь.', 'Ты принес кальцедоний?', NULL, NULL, 'Кальцедоний', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13042, 'В недрах Глубинных чертогов', 'В недрах Глубинных чертогов на северо-востоке сумасшедший ученый по имени доктор Ужас творит всякие бесчинства, вполне соответствующие его имени.$B$BКороль-лич дал ему разрешение ставить эксперименты над варгулами – врайкулами, которые погибли в сражении, но их сочли недостойными, воскресили и поставили под знамена Плети.$B$BМы должны его остановить, но гадание не раскрыло мне его точного местонахождения. Однако мы знаем, что у него есть ученик.$B$BВыбей нужную нам информацию из этого ученика, а потом как-нибудь тихо избавься от тела.', 'По поручению костяной ведьмы из деревни Ньорндар выбейте информацию из ученика Остеркилгра: узнайте, где находится доктор Ужас.Потом убейте ученика.', 'Очень интересно. Похоже, ты справился как нельзя лучше. Странно, что учеником доктора был варгул... если учесть, чем он там занимается.', NULL, NULL, NULL, 'Ученик Остеркилгр выдал тайные сведения', 'Ученик Остеркилгр убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13043, 'Когда сумма больше слагаемых', 'Вы открываете книгу и видите очень подробные и четкие иллюстрации, отражающие процесс создания того, что доктор называет \"абсолютным оружием\"!$B$BОчевидный прототип, Нергельд, внушительный мясистый великан, неподвижно стоит в дальнем конце Зала Ужасов.$B$BЕсли будет создана целая армия подобных \"конструкций\", это действительно будет конец. Существует единственный способ это предотвратить: убить доктора Ужаса!$B$BМожет быть, доктор выйдет к вам, если вы попытаетесь взять контроль над его творением?', 'Заберитесь в Нергельда и возьмите над ним контроль. Защищайте его от обитателей Зала Ужасов, пока не покажется доктор Ужас.Используйте Нергельда, чтобы убить доктора, а потом возвращайтесь в деревню Ньорндар, в пещеру к костяной ведьме.', 'Тебе удалось сорвать планы доктора!$B$B<Ведьма, одержимая банши, улыбается и ласково треплет тебя по плечу.>$B$BНеплохой щелчок по носу Короля-лича, но можно придумать и кое-что получше.', NULL, NULL, NULL, 'Доктор Ужас убито', '\"Создание улучшенного мясистого великана\" доктора Ужаса', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13044, 'Пропавшие без вести', 'На той стороне Долины Эха, что к западу отсюда, за Проломом, расположилась первая застава Плети в Ледяной Короне – Плетхольм. Мы организовали вылазку на заставу и перебили немало чудовищ Плети, но затем нас отбросили назад. Нескольких солдат недосчитались – они пропали без вести.$B$BЕсли наши товарищи еще живы, их необходимо спасти! Ступай по этой тропе на юго-восток и найди Пенумбриуса. Он – союзник бронзовых драконов и попечитель протодраконов. Он поможет тебе.', 'Поговорите с Пенумбриусом в Оплоте Серебряного Авангарда в Ледяной Короне.', '<Пенумбриус важно кивает.>$B$BМои сородичи помогут тебе. Вместе мы сокрушим Короля-лича и его легионы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13045, 'В чащобу', 'Мы будем помогать тебе всеми силами, $N. Протодраконы полетят по Пролому в Плетхольм. Спаси всех рыцарей Серебряного Авангарда, которых встретишь. Доставь их в лазарет в самом центре Оплота Серебряного Авангарда.$B$BВозьми небесного когтя Серебряного Авангарда в палатке за моей спиной и ступай!$B$BПлетхольм расположен на северо-западе, по ту сторону Долины Эха, в большом Проломе.', 'Вытащите из Плетхольма 3 плененных рыцарей Серебряного Авангарда и доставьте их в лазарет в центре Оплота Серебряного Авангарда. После этого поговорите с верховным лордом Тирионом Фордрингом.', 'Артас... он бросается в бой очертя голову – без оглядки и без расчета. Мы застали его врасплох.$B$B<Предводитель Тирион Фордринг на минуту задумывается.>$B$BМы можем укрепить наши позиции и пережить штурм.$B$BТы умеешь обращаться с пушками, $N?', 'С каждой минутой их шансы выжить тают...', NULL, NULL, 'Спасено плененных рыцарей Серебряного Авангарда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13046, 'Муки Арнгрима', 'Голод Арнгрима вошел в легенды.$B$BДаже после смерти его лик искажен гримасой ненасытного голода. При одном только взгляде на это лицо у вас начинает бурчать в желудке.$B$BГоворят, что за всю свою жизнь он никогда не наедался досыта, а ведь он ел все подряд. Вы поневоле задумались: а есть ли способ накормить старого короля?$B$BКак только у вас возникает эта мысль, один из огромных замерзших зубов Арнгрима выпадает у него изо рта и, отскочив от его бороды, падает вам на ладонь.', 'Вы должны накормить Арнгрима пятью бесплотными йормунгарами и вернуться к замерзшему изображению Арнгрима в Дун Ниффелем.Идите в долину Древних Зим и воспользуйтесь зубом Арнгрима, чтобы воздействовать на блуждающих йормунгаров. Когда они развоплотятся, сражайтесь с ними, пока они не ослабнут.', 'Вы укрепляете зуб в десне Арнгрима, и у вас складывается впечатление, что муки голода старого короля ослабли… на какое-то время.', NULL, NULL, NULL, 'Дух Арнгрима накормлен', 'Зуб Арнгрима', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13047, 'Свидетель', 'Локен убил мою жену и настроил против меня моих учеников, а меня против них. Он отнял у меня самое дорогое, но сегодня... все изменится.$B$BСегодня мы вернем себе наши святые земли. Сегодня… Локен умрет.$B$BВстретимся у храма Мудрости, что к юго-западу от Ульдуара. Так или иначе, я положу этому конец.$B$BМне нужен только свидетель, тебе не нужно мне помогать – это дело личное.$B$BКогда все закончится, ты пойдешь к Йоккуму, королю снежных великанов, и расскажешь о том, что было. Он – добрый друг. Он поймет, что делать.', 'Встретьтесь с Торимом у храма Мудрости. Потом отправляйтесь к Йоккуму в Дун Ниффелем и расскажите ему об исходе сражения.', 'Нет… Не может такого быть...$B$BНикому не под силу победить Торима в схватке один на один. Ни великану, ни зверю… вообще никому! И уж точно никак не его братцу, мерзавцу и трусу.$B$BКлянусь именами моих славных предков...$B$BЛокен заплатит за это!', NULL, NULL, NULL, 'Станьте свидетелем сражения', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13048, 'Откуда время пошло не туда', 'Молот Знаний может помочь нам исправить поврежденную линию времени, но для этого нам надо найти тот момент в прошлом, откуда время пошло не туда. В противном случае у нас ничего не получится.$B$BСудя по тому, что рассказал вождь Быстрое Копье, и по твоим находкам в Ледяных глубинах, можно с уверенностью предположить, что искажение произошло более-менее одновременно со смертью Штормового Копыта.$B$BОтправляйся на север, в Стенающую ложбину, и обойди древние захоронения, разоренные приспешниками Северного Ветра. Молот Знаний среагирует на подлинные предметы из эры Штормового Копыта и сам настроится на истинное время.', 'Разыщите реликвии таунка и настройте Молот Знаний на истинное время Штормового Копыта. Когда он настроится на 6 реликвий из времени Штормового Копыта, возвращайтесь к Ксанатавру в лагерь Тунка\'ло.', '<Ксанатавр забирает у вас Молот Знаний.>$B$BМы наконец \"засекли\" время Штормового Копыта в истинной истории. Теперь мы сможем исправить искаженную линию времени.', 'Ты настроил Молот Знаний на время Штормового Копыта?', NULL, NULL, 'Молот Знаний настроен на время Штормового Копыта', 'Молот Знаний (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13049, 'Доспехи героя', 'Похоже, не все исторические документы были испорчены вмешательством в ход времени. Мои помощники смогли разыскать записи, отражающие события подлинной линии времени.$B$BТам написано, что Штормовое Копыто был похоронен со всеми почестями среди деревенских старейшин, на нижнем ярусе Стенающей ложбины.$B$BБольшинство захоронений в тех местах уже разграблено войсками Северного Ветра. Им удалось захватить несколько поистине бесценных реликвий. Отправляйся на север, в Стенающую ложбину, и попытайся забрать у потомков бури копье и доспехи Штормового Копыта.', 'Добудьте копье и кольчугу Штормового Копыта и верните их Ксанатавру в лагерь Тунка\'ло.', 'Это большая удача, $N, что тебе удалось вернуть их в целости и сохранности. Теперь мы сможем использовать Молот Знаний, чтобы отправить тебя в прошлое, в тот момент, когда Северный Ветер только начал искажать подлинную линию времени. Только так можно восстановить истинную историю этого места.', 'Нашлись ли доспехи и оружие Штормового Копыта?', NULL, NULL, 'Копье Штормового Копыта', 'Кольчужный доспех Штормового Копыта', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13050, 'Веранус', 'Если я собираюсь атаковать армию брата, мне нужно придумать, как к ней подобраться.$B$BКогда-то у меня была самка ездового дракона, но я отпустил ее на волю. Веранус была просто великолепна. Истинная предводительница своей стаи – в которую она и вернулась.$B$BНайти ее будет непросто... и все же, я думаю, есть один способ. Она остается в своем старом пустом гнезде – исключительно из гордости. Веранус – праматерь лишь номинально, поскольку давно миновала тот возраст, когда драконы способны к размножению.$B$BПринеси мне яйца из других гнезд, расположенных вблизи Бруннхильдарской деревни. У меня есть одна мысль...', 'Раздобудьте 5 маленьких яиц протодракона в горах рядом с деревней Бруннхильдар и принесите их Ториму в Храм Штормов.', 'Да... эти сгодятся. Будем надеяться, что мой план сработает, $N.$B$BВеранус действительно великая в своем роде, и я уже не удовольствуюсь кем-то меньшим.', 'Ты добыл яйца, $N?', NULL, NULL, 'Маленькое яйцо протодракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13051, 'Нарушение границ', 'У Веранус есть гордость. Я не знаю другого такого зверя, у которого было бы столько гордости. Она все еще удерживает свое старое гнездо и отгоняет от него молодых протодраконов.$B$BВозьми собранные тобой яйца и помести их в гнездо. Ты найдешь его на вершине невысокой скалы, прямо на юго-восток отсюда.$B$BЯ смогу взять ее под контроль, прежде чем она тебя растерзает. Ну, я надеюсь...', 'Отнесите похищенные яйца протодракона в гнездо праматери и возвращайтесь к Ториму в Храм Штормов.', 'Какое счастье, когда старый друг возвращается целым и невредимым! Похоже, удача вновь повернулась ко мне лицом... и все благодаря тебе!', 'Привет, $N!', NULL, NULL, 'Веранус \"клюнула\" на приманку', 'Похищенные яйца протодракона', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13052, 'Воздушная разведка', 'Ты хорошо $gпомог:помогла: Уэсу с починкой и возвращением в строй этого ветролета.$B$BЕсли хочешь и дальше помогать нам, то знай: на нас с северо-запада надвигается необычный атмосферный фронт. У меня есть пилот, но, боюсь, по такой погоде ему нужен напарник.$B$BЕсли ты считаешь, что сможешь справиться, отправляйся в Лагерь у озера. Скажи Вику, что ты от меня.', 'Отправляйтесь в Лагерь у озера по просьбе профессора Кальверт и поговорите там с пилотом Виком.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13053, 'В поисках уцелевших', 'Гретхен Искрошип хочет использовать мой ветролет, чтобы разыскать уцелевших людей из ее экспедиции. Она считает, что их держат в плену в деревне на севере.$B$BПроблема в том, что у меня нет второго пилота. Если ты согласишься лететь со мной, я обучу тебя паре приемов.$B$BЧто скажешь, $N? По рукам?', 'Помогите Заку Шестеркруту совершить испытательный полет.', '', NULL, NULL, NULL, 'Испытательный полет', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13054, 'Пропавший следопыт', 'Я не могу со спокойной совестью отправить тебя в пещеру воргов, не предупредив об опасности. Тот, кто пошел туда до тебя, не вернулся.$B$BМы уже приготовились к самому худшему, но оказалось, что он еще жив. Если ты поможешь ему вернуться, мы будем очень тебе благодарны. У нас осталось очень немного охотников, а следопыт Вал\'зиж – один из лучших.', 'Разыщите следопыта Вал\'зижа в логове Гиморака, на юго-востоке от места крушения Гром\'арша.', 'Очень больно… похоже, что долго я не протяну.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13055, 'Лекарство из пещер', 'Как приятно увидеть доброжелательное лицо. Кто знает, может быть, это в последний раз.$B$BЯ уже почти выбрался, и тут меня укусил йормунгар. А они ядовиты. Все мое тело уже немеет, я чувствую.$B$BМне нужно противоядие, а для этого надо добыть ядовитую железу у кого-то из этих тварей. И еще мне понадобятся пещерные грибы, чтобы замедлить действие яда... грибы растут здесь...$B$BПожалуйста, поторопись. У меня мало времени.', 'Добудьте 1 ядовитую железу йормунгара и 8 пещерных грибов и доставьте следопыту Вал\'зижу в Логово Гиморака.', 'Спасибо, друг. Теперь я смогу продержаться еще один день.', 'Уже вернулся, браток?', NULL, NULL, 'Пещерный гриб', 'Ядовитая железа', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13056, 'Всегда найдется время для мести', 'Теперь мне должно стать полегче. Думаю, как-нибудь справлюсь. И все же, $N, я попрошу тебя об одной услуге.$B$BНикто из этих червей не смог бы меня одолеть, если бы подлейший из воргов не убил моего крылатого змея, Хиишу.$B$BОбо мне можешь не беспокоиться. Мне станет легче, когда этот мерзавец ворг сдохнет. Ты найдешь его в глубине пещеры.', 'Убейте Гиморака в пещере Ледяного Воя по просьбе следопыта Вал\'зижа.', 'Мне уже лучше, честное слово. Не знаю, то ли подействовало противоядие, то ли меня греет мысль, что этот мерзкий ворг получил по заслугам.', 'Ты нашел эту подлую сволочь, $N?', NULL, NULL, 'Гиморак убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13057, 'Терраса Творцов', 'Время пришло, $N. Я готов к встрече с Локеном. Мы отправимся на Террасу Творцов и дадим бой армиям моего брата. Этот дурак пожалеет, что связался со мной.', 'Разыщите Торима на юго-восточном конце Террасы Творцов, к северо-западу от Дун Ниффелема.', 'Вот мы и прибыли, $N. Сегодня армия моего брата познает горечь поражения.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13058, 'Чтобы ветер переменился', 'Теперь у нас есть все необходимое, чтобы исправить все то, что испортил Северный Ветер и его приспешники. Ты $gнастроил:настроила: Молот Знаний на время и личность Штормового Копыта.$B$BСнова возьми молот и отправляйся к Храму Жизни, на равнины к северо-западу. Воспользуйся молотом, чтобы принять облик Штормового Копыта. Потом иди к Северному Ветру под личиной Штормового Копыта, но помни, что в той линии времени, которую нужно восстановить, Штормовое Копыто должен умереть, когда Северный Ветер ослабеет.$B$BТы используешь этот шанс и при помощи рога неистовства стихий уничтожишь Северного Ветра.', 'Используйте Молот Знаний, чтобы вернуться в прошлое и сразиться с Северным Ветром под личиной Штормового Копыта. Когда Штормовое Копыто падет, возьмите рог неистовства стихий и прикончите Северного Ветра, а затем возвращайтесь к Ксанатавру в лагерь Тунка\'ло.', 'Твой сегодняшний подвиг не даст Штормовому Копыту и его славным деяниям сгинуть в безвестности. Твое имя тоже навечно войдет в историю Азерота. Я все запомню и опишу твои подвиги, дабы они сохранились в веках!', 'Ну что, получилось? Истинная линия времени восстановлена?', NULL, NULL, 'Линия времени восстановлена', 'Молот Знаний (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13059, 'Месть за варгулов', 'Я молился Леди Меча, чтобы она прислала кого-то, кто придет и уничтожит моего врага.$B$BТан Иллскар должен сполна заплатить за то, что он со мной сделал!$B$BВ былые времена я бы и сам отомстил этому подлецу, но теперь от меня осталась лишь жалкая оболочка. Я был лучшим воином тана Уфранга Могущественного. Во время боя за власть в Вальхаласе Иллскар применил бесчестный прием: скрытую магию. Я проиграл, и ты видишь, во что я превратился.$B$BТы найдешь тана и его защитников внизу, в Круге Страдания. Вызови его на поединок от моего имени. Убей его, и пусть он тоже познает страдания и муки, как знаю их я!', 'Бросьте меч в Круге Страдания, вызовите на бой и убейте тана Иллскара по просьбе Бетода Фейгра из Глубинных чертогов.', 'Спасибо, $C... спасибо!$B$BМне будет приятно осознавать, что трус и подлец, из-за которого я оказался в таком положении, тоже будет страдать и гнить до скончания вечности!$B$BА теперь уходи, пока я не утратил контроль над собой и не изрубил тебя в капусту.', 'Я чувствую, ты еще не убил тана. Тебе что-то мешает?', NULL, NULL, 'Вызов брошен с помощью меча Бетода', 'Тан Иллскар убито', 'Меч Бетода', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13060, 'Когда остается единственный выход...', 'Что-то я сомневаюсь, что нам удастся закрепиться в этих горах.$B$BПоверь мне, я не из тех, кто легко сдается... но, когда ты зажат между замерзшими машинами, злобными врайкульскими бабами, какими-то непонятными существами, жаждущими стать драконами, и еще добрым десятком других воинственных тварей, это как-то не способствует оптимистическому настрою.$B$BНо ты все же не падай духом! Если мы не можем там закрепиться, это еще не значит, что мы не можем доставить тебя туда... поездка в один конец – это вовсе не сложно, когда привыкаешь.$B$B<Рикет указывает на ракеты неподалеку.:', 'Воспользуйтесь принадлежащим Рикет пропеллерным доставочным аппаратом Д16, чтобы продвинуться вглубь Грозовой Гряды.', '<Олут морщится.>$B$BДаже смотреть было больно. Хотя, надо сказать, это был эффектный выход.$B$BТы пришел, чтобы помочь нам найти проход к леднику Ледяной Короны? Как ты, наверное, знаешь, наша первая вылазка в том направлении закончилась, мягко скажем, бесславно. Думаю, в этот раз нам надо попробовать прорваться с другой стороны.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13061, 'Победа или смерть', 'Ну вот, время пришло. Я позабочусь о твоей медведице, сейчас она тебе не понадобится. Теперь тебе предстоит сразиться с великим Драконобойцей.$B$BПопрощайся с друзьями, приведи в порядок дела, ибо ты либо вернешься с победой... либо не вернешься вообще.', 'Поговорите с Лок\'лирой Каргой в деревне Бруннхильдар.', 'Ты неплохо справляешься. Честно сказать, я не думала, что ты сумеешь добиться столь выдающегося положения среди хильд за такое короткое время.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13062, 'Прощальный подарок Лок\'лиры', 'Твоя помощь неоценима, $N. Теперь пришло время для настоящего испытания. Тебе понадобится все твое мастерство, мужество и немного везения.$B$B<Лок\'лира прикрепляет к вашим волосам тонкую прядь волос.>$B$BУ тебя все получится. Должно получиться. Поговори с Греттой Судьей. Она скажет тебе, что делать.', 'Поговорите с Греттой Судьей в деревне Бруннхильдар.', 'Ты готова, сестра? Помни: назад пути нет.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13063, 'Посмотрим, чего ты стоишь', 'Сестра, ты добилась успеха там, где многих постигла неудача. Остается лишь выяснить, что тебе помогло: твоя сила и доблесть или простое везение.$B$BВозвращайся в деревню и разыщи там Астрид Бьорнриттар. Расскажи ей о своих достижениях. Только я тебя сразу предупреждаю: на нее нелегко произвести впечатление.', 'По просьбе Бриджаны отправляйтесь в деревню Бруннхильдар и поговорите с Астрид Бьорнриттар.', 'Так что же, сестра, ты считаешь себя героиней, потому что исполнила пару простых поручений?$B$BТебе еще многому предстоит научиться...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13064, 'Соперничество братьев', 'Сиф? Это ты? Правда, ты?$B$BНет? $gраса:? Но на мгновение мне показалось...$B$BВсе, хватит! Видения, в которых являлась мне моя Сиф, они терзали меня слишком долго! Пора отомстить за нее и почтить ее память, как должно.$B$BМой брат заплатит за все!', 'Выслушайте историю Торима.', 'Теперь ты знаешь историю этой земли... моей земли.$B$BЯ прошу тебя: помоги мне все исправить.', NULL, NULL, NULL, 'История Торима выслушана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13065, 'Предок Оханзи', '', '', 'Жизнь так и кипит в тебе, юный $С. Я принимаю твою дань уважения. Возьми взамен этот знак...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13066, 'Предок Яруак', '', '', 'Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $N. Прими этот знак...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13067, 'Предок Чоган\'гада', '', '', 'Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $N. Прими этот знак...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13068, 'Отважный герой', 'Вероятно, ты $gслышал:слышала: о доблестных подвигах нашего пропавшего героя?$B$BРыцарь Бриденбрад сражался с силами Плети на Прорванном фронте, и тут на союзников напало войско нежити. Многие солдаты союзных войск навечно остались на поле боя, но Бриденбрад уцелел и спас больше дюжины воинов – вытащил их из этой мясорубки, одного за другим.$B$BТак вот, $C, после этого он не вернулся. В последний раз его видели, когда он направлялся на северо-восток, в сторону Молчаливого Бдения. Найди его и приведи ко мне, и я воздам ему почести, подобающие доблестному герою.', 'Отправляйтесь в северо-восточную часть Ледяной Короны, разыщите героя, рыцаря Бриденбрада, в Молчаливом Бдении и приведите его к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Возле его стоянки обычно горит костер, заметный с воздуха.', 'Не подходи! Берегись! Я заражен! И не хочу, чтобы эта зараза коснулась тебя или кого-то еще!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13069, 'Пристрели их', 'Йотунхейм славится надежной воздушной обороной – это наездники на протодраконах и гарпунные пушки. Особенно много их возле наиболее уязвимых частей города: на севере и на западе.$B$BТак давай используем их оборону против них же!$B$B<Прыгун буравит вас своим единственным глазом и издает маниакальный смешок.>$B$BЗавладей гарпунной пушкой на любой из платформ, висящих над скалами на юго-западе, и уничтожь протодраконов и их наездников. Пристрели их!', 'По заданию Прыгуна из Мрачного Свода сбейте с помощью йотунхеймского скорострельного гарпуна 15 йотунхеймских протодраконов и их наездников.', 'Ты настоящий борец за справедливость, $N!$B$BМожет, придешь еще завтра? Еще протодраконов постреляешь.', 'Ай-ай-ай... Ты же сегодня еще не пристрелил положенное количество протодраконов!', NULL, NULL, 'Уничтожено йотунхеймских протодраконов и их наездников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13070, 'Приближение холодного фронта', 'С запада веет холодом смерти, и холод этот грозится заморозить наши сердца и души и отдать их под власть темного властелина этих снежных пустошей. Но мы не сдаемся! Мы будем сражаться!$B$BПодготовка уже началась. Поговори с осадным мастером Феззиком у главных ворот, и он объяснит тебе твое задание.', 'Поговорите с осадным мастером Феззиком в Оплоте Серебряного Авангарда в Ледяной Короне.', 'Нам надо поторопиться, иначе нам не устоять против сил Плети! У меня, честное слово, нет времени объяснять все подробно, $R. В общем, разбирайся по ходу дела и надейся на лучшее.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13071, 'Злоб любит огонь!', 'Злоб любит огонь! Злоб любит протодраконов!$B$B<Поганище радостно хлопает в ладоши.>$B$B<Малыш:Малышка: $N, ступай в Йотунхейм и укради симпатичного протодракончика в деревне Ньорндар. Заставь протодракончика поджечь с десяток построек в Йотунхейме. Чтобы красиво горело красивым огнем!', 'По просьбе Злоба из Мрачного Свода украдите ньорндарского протодракона и заставьте его поджечь 8 построек врайкулов в Йотунхейме.Цитадель Балагарда, в силу своей природы, гореть не может.', 'Да, да! Вот так! $N – лучший в мире похититель протодраконов!$B$BПриходи завтра, и мы устроим еще много огня!', NULL, NULL, NULL, 'Подожжено построек врайкулов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13072, 'Горькая участь героя', 'Я знаю, зачем ты $gпришел:пришла:... Тебя прислали за мной... только вернуться я не смогу. Я заражен чумой нежити, $C, и не хочу, чтобы эта зараза коснулась кого-то еще. Нет, я никуда не пойду.$B$BСмерти я не боюсь. Но я знаю, во что превращусь после смерти, и мне ненавистна сама мысль о том, что мне волей-неволей придется служить этому подлому предателю Артасу.$B$BОставь меня... и позаботься о том, чтобы меня не искали. Ты сослужишь мне плохую службу, если, желая спасти меня, ты невольно разнесешь эту заразу.', 'Расскажите о том, что случилось с рыцарем Бриденбрадом, верховному лорду Тириону Фордрингу на Вершине Рыцарей.', 'Бриденбрад заразился? Трудно представить более страшную участь для воина, который всю свою жизнь посвятил пути Света! Я не могу бросить его умирать, не попытавшись помочь.$B$BНет, мы не позволим ему стать нежитью. Мы найдем способ помочь этому доблестному герою.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13073, 'Благосклонность хранителя', 'В мире есть те, кто обладает неограниченной силой: силой Жизни, силой Света, силой Воскрешения. Бриденбрад – не просто обычный человек... Его доблесть и отвага удивительны. Нам остается только надеяться, что кто-то сможет спасти героя от участи худшей, чем смерть.$B$BОтправляйся к верховному друиду Лилиандре в Оплот Серебряного Авангарда. Попроси ее провести тебя к Лунной поляне и обратись за помощью к хранителю Ремулу.', 'По просьбе верховного лорда Тириона Фордринга с Вершины Рыцарей поговорите с верховным друидом Лилиандрой и доберитесь до хранителя Ремула на Лунной поляне.', 'Здравствуй, дитя мое.$B$BЯ понимаю, почему Тирион просит меня об этом, и доверяю ему. Итак, что же мы можем сделать для рыцаря Бриденбрада... Задача не из легких. Плеть ведь не из этого мира, и многие уже безуспешно пытаются преодолеть ее разрушительное влияние в течение долгих лет.$B$BОднако для тех, в чьем сердце живет Свет, а помыслы благородны, надежда всегда есть.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13074, 'Изумрудный кошмар', 'Нам нужны желуди, обладающие мощной восстанавливающей магией, а они есть только в Изумрудном Сне. Многое на этой священной поляне тесно связано со Сном, в том числе и мое святилище.$B$BЯ отправлю тебя в Сон, и ты добудешь там такие желуди. Но будь $gготов:готова: ко всему, $C: такой способ погружения в Сон очень опасен, и вполне возможно, ты окажешься в самом настоящем кошмаре.$B$BДобудь желуди как можно быстрее. Чтобы вернуться в реальный мир, тебе надо будет покинуть святилище – или же просто ущипнуть себя и проснуться.', 'По заданию хранителя Ремула с Лунной поляны погрузитесь в Изумрудный Сон и добудьте 3 изумрудных желудя.Чтобы пробудиться, покиньте святилище Ремула или ущипните себя.', 'Отличная работа, юный $С.', 'Приятно видеть тебя живым. Удалось достать желуди?', NULL, NULL, 'Изумрудный желудь', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13075, 'Дар Ремула', 'Я открою портал. Он приведет тебя обратно к друиду, который отправил тебя сюда. Желаю удачи тебе и особенно – твоему рыцарю. Надеюсь, этот желудь очистит твоего рыцаря от скверны и спасет его от печальной судьбы зараженных.$B$BПрощай, $r.', 'Отнесите изумрудный желудь рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.', 'Тирион отправил тебя к Ремулу? Я... Я польщен. К такому могущественному существу не обращаются за помощью просто так, даже c самыми благородными намерениями. И ты... ты столько для меня сделал. Прими мою искреннюю благодарность.$B$BА теперь посади семя – я готов.', 'Рад встрече, $C. Я знал, что ты все равно вернешься, несмотря на мое предупреждение, но ты хотя бы послушал меня и не стал подвергать риску кого-то еще. Что не может не радовать.$B$BПочему ты вернулся ко мне?', NULL, NULL, 'Изумрудный желудь (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13076, 'Время еще есть', 'Я чувствую себя как будто бы обновленным. Но чума не отступила до конца. Но невелика печаль! Я так благодарен тебе, ведь мы совсем незнакомы, а ты $gпроделал:проделала: ради меня такой путь. Ты $gподарил:подарила: мне несколько драгоценных часов жизни, когда я не буду заражать остальных, как это делает мерзкая нежить.$B$BСпасибо тебе, $C. И передай, пожалуйста, мою благодарность Тириону. Скажи ему, что помочь ему было для меня настоящей честью.', 'Возвращайтесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей и сообщите ему о том, каким действием обладают изумрудные желуди.', 'Жаль, что ничего не получилось. Однако беспокоиться не стоит, я знаю и других желающих помочь нам.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13077, 'Прикосновение Аспекта', 'Королева драконов Алекстраза всегда обладала способностями к магии. Своим огнем она умеет выжигать нежить и создавать новую жизнь. Кто знает, может, она и Бриденбраду поможет.$B$BАлекстраза живет в храме Драконьего Покоя, что в Драконьем Погосте. Отправляйся к ней и передай мою нижайшую просьбу о помощи.', 'Попросите о помощи Алекстразу Хранительницу Жизни из храма Драконьего Покоя.', 'Приветствую тебя, $R.$B$BЯ вижу печаль на твоем лице. Расскажи, что тебя беспокоит.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13078, 'Слезы Далии', 'В эти темные времена я не брошу поборника Света в беде.$B$BНам нужно что-то, наделенное святой силой: что-то, что даст нам надежду на спасение твоего Бриденбрада... Останки верного, преданного существа, павшего жертвой той же угрозы.$B$BОтправляйся к священной земле, окружающей Рубиновое святилище драконов. Когда Рубиновые хранители воспламенят землю под ногами нежити, ты увидишь, как зарождается и тянется к свету новая жизнь. Среди ростков будут и слезы Далии – принеси их мне.', 'Сорвите слезы Далии с земли, очищенной пламенем Рубиновых хранителей, и принесите их Алекстразе Хранительнице Жизни в храм Драконьего Покоя.', 'С помощью слез Далии и древней магии я сотворю крупицу надежды для твоего великого рыцаря.', 'О, милая Далия, как мне тебя не хватает!', NULL, NULL, 'Слезы Далии', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13079, 'Дар Алекстразы', 'Ты $gдолжен:должна: понимать, $gюный:юная:$r, что моей власти достаточно, чтобы очистить тело во имя новой жизни... но изгнать из него чуму нежити так, чтобы не повредить само тело – это выше моих сил.$B$BЕсли все обстоит так, как ты говоришь, и этот Бриденбрад и вправду столь доблестный рыцарь и верный поборник Света, может быть, он и выдержит обряд очищения, но я не могу ничего обещать. Вот, возьми это, и прими мое благословение.', 'Отнесите Дыхание Алекстразы рыцарю Бриденбраду в Молчаливое Бдение, что в в Ледяной Короне.', 'Дыхание Алекстразы... ты ходил к самой королеве драконов? Я безмерно тебе благодарен.$B$BЯ знаю, что это опасный обряд, и знаю, чем он грозит в случае неудачи, но я готов пойти на риск. Приступим, $C.', 'Ты снова вернулся ко мне, $C. Ради чего ты рискуешь собой?', NULL, NULL, 'Дыхание Алекстразы (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13080, 'Надежда жива', '$gБриденбрад машет вам рукой, одновременно пытаясь отдышаться.>$B$BКак я и ожидал, было очень больно, но я буквально почувствовал, как порча уходит из моего тела. Но чуму так легко не изгонишь.$B$BСпасибо тебе за все, $C. Твоя самоотверженность заставила меня поверить, что в мире еще есть много хорошего и надежда жива. Я могу уйти, не боясь, что в мое отсутствие тьма возобладает над светом.$B$BА теперь иди. Иди и ни о чем не жалей.', 'Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Расскажите ему о действии Дыхания Алекстразы.', 'Чума Плети – страшный враг. По словам Алекстразы, есть надежда, что Бриденбрад избежит участи нежити – в случае, если нам не удастся спасти его жизнь. Но я не хочу сдаваться так легко.$B$BЕсть еще один способ, который я хотел бы опробовать. Вероятно, одно существо способно предотвратить то, чего мы так боимся.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13081, 'Завещание наару', 'Мы очень благодарны за все, что ты для нас $gсделал:сделала:, $N. У меня есть к тебе последняя просьба... Последняя надежда для паладина, достойного большего, чем мы можем дать.$B$BОтправляйся в Шаттрат и поговори с А\'далом из народа наару. Он всегда был поборником Света и преданным другом паладинов. Расскажи ему историю Бриденбрада и попроси о помощи.$B$BЯ даже передать не могу, насколько это важно. Боюсь, если ты не поторопишься, ничто уже не спасет нашего рыцаря.', 'Попросите о помощи А\'дала из Шаттрата, который находится в лесу Тероккар.', '<По мере приближения к наару у вас в голове все громче звучит нежный перезвон.>$B$BЯ знаю, зачем ты пришел.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13082, 'Дар А\'дала', 'Рад тебя видеть, $N. Я знаю, что случилось с рыцарем Бриденбрадом. И как ты $gпытался:пыталась: его спасти, тоже знаю. Видно, отвага Бриденбрада передалась и тебе, а это уже само по себе чудо.$B$BСвет помогает тем, кто ему верен. Я благословлю Бриденбрада, и ему больше не будет угрожать участь нежити. Тебя же я перенесу обратно, в Даларан, чтобы ты $gсмог:смогла: его найти. И помни: я всегда с тобой.', 'Вернитесь к рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.', '<Приближаясь к рыцарю Бриденбраду, вы замечаете, что он сильно побледнел, а дыхание стало поверхностным и сбивчивым. Становится ясно, что жить ему остается недолго.>$B$BТы вернулся, $C. И признаюсь... меня это радует... Твое возвращение возрождает во мне надежду на то... что эта земля скоро будет освобождена от ига Артаса. Я горжусь знакомством с тобой.$B$B<Дыхание прерывается, Бриденбрад умирает со слабой улыбкой на устах, и в этот момент у вас в голове звучит тихий, приятный перезвон.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13083, 'Свет во тьме', '<Накидка рыцаря Бриденбрада лежит на дне сундука и легонько колышется от ветра, проникшего внутрь.>$B$BТирион наверняка захочет получить эту последнюю реликвию, оставшуюся от великого рыцаря.', 'Отнесите плащ рыцаря Бриденбрада верховному лорду Тириону Фордрингу на Вершину Рыцарей.', 'Я рад, что ты смог спасти его от участи слуги Плети. С благословением А\'дала зло не коснется его в ином мире.$B$BЕго благородство и доблесть всегда будут служить нам примером, как и твоя величайшая самоотверженность. Спасибо за все, что ты сделал для нас.', 'Он ушел, да? Его больше нет? Я почувствовал, как из этого мира исчез кусочек света, и в мире стало темнее...', NULL, NULL, 'Накидка рыцаря Бриденбрада (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13084, 'Психологическая атака', 'Нам удалось подорвать боевой дух врайкулов, $N, и надо бы продолжать в том же духе.$B$BЯ хочу, чтобы ты каждый день $gездил:ездила: в Йотунхейм и $gпредавал:предавала: огню их знамена. Может быть, это и примитивный подход, но каждый день видеть пожары на своей территории – это деморализует похлеще, чем силовые методы воздействия.$B$BКак бы то ни было... хуже не будет!', 'Сожгите 10 знамен врайкулов по поручению герцога Ланкрала из Мрачного Свода.', '<Герцог внимательно смотрит на вас и кивает>$B$BТы замечательно справился с заданием и подорвал боевой дух врайкулов. Это место для них священно, здесь они впервые вернулись к жизни. Важнее Йотунхейма для них – только Имирхейм.$B$BПродолжай давить на них дальше, пока я защищаю Склеп от атак Короля-лича.', NULL, NULL, NULL, 'Сожжено знамен врайкулов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13085, 'Возвращение Вэлена', 'Я только видел, как этот глупец Вэлен Разоблаченный прокрался в склеп.$B$BТы уж позаботься, чтобы он осознал свои ошибки и вернул мне моих рыцарей смерти.', 'Поговорите с Вэленом Разоблаченным в Мрачном Своде.', 'Кажется, я догадываюсь, зачем ты здесь, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13086, 'Последний рубеж', 'Я знаю, как укрепить оборону Оплота, $C! На верхушке каждой из четырех башен находится откатная пушка Серебряного Авангарда, освященная самим отцом Густавом. Ты полетишь на одну из этих башен и с помощью пушки будешь уничтожать штурмующие Оплот силы Плети.$B$BНо помни: на осаду башен наверняка пошлют ледяных змеев. Их надо сбить прямо в воздухе! Если змеи разрушат стены и башни, нам конец.', 'Уничтожьте 100 солдат Плети с помощью пушки Серебряного Авангарда. Также уничтожьте 3 ледяных драконов-разрушителей.В случае успеха вернитесь к осадному мастеру Феззику.', 'Ты стрелял не хуже гоблинского канонира! Оплот и весь Серебряный Авангард спасены – и все благодаря тебе. К тому же, ты помог самому верховному лорду! Молодец!', 'Вопли умирающих будут преследовать меня всю жизнь! Помогите им!', NULL, NULL, 'Уничтожено солдат Плети, штурмующих Оплот', 'Ледяной дракон-разрушитель убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13087, 'Кулинария севера', 'Ну и что ты тут $gзабыл:забыла:? Где мой обед? Я скоро с ГОЛОДУ сдохну! Принеси мне хотя бы охлажденного мяса, чтобы я сварил похлебку! Принесешь – дам тебе рецепт, будешь $gсам:сама: себе еду варить. БЫСТРЕЕ, НЕСИ МНЕ МЯСО!', 'Принесите четыре куска охлажденного мяса зверей Нордскола Брому Выпивастеру в Валгард.', 'Ура, мясо! Держи рецепт – а я займусь готовкой!', 'ГДЕ МОЕ МЯСО?!', NULL, NULL, 'Охлажденное мясо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13088, 'Кулинария севера', 'Как много новобранцев – и всех их надо хорошенько накормить! Если ты принесешь мне немного охлажденного мяса, я сделаю им мясную похлебку, а ты получишь рецепт.', 'Принесите четыре куска охлажденного мяса зверей Нордскола Роллику Маккрилу в Крепость Отваги.', 'Наконец-то мы накормим всех новобранцев! Держи, вот твой рецепт.', 'Эти парни хотят видеть мясо у себя в похлебке!', NULL, NULL, 'Охлажденное мясо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13089, 'Кулинария севера', 'Что может быть лучше согревающей мясной похлебки? Принеси мне немного охлажденного мяса проклятых тварей, что бродят по этому краю, и я научу тебя, как делать мою похлебку.', 'Принесите четыре куска охлажденного мяса зверей Нордскола Томасу Количио в Лагерь Возмездия.', 'Сейчас мы быстренько превратим это мясо в похлебку...', 'Похлебка ждет тебя...', NULL, NULL, 'Охлажденное мясо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13090, 'Кулинария севера', 'Воинам армии Песни Войны нужна горячая пища. Если ты принесешь мне немного охлажденного мяса люторогов и прочих зверей, я сделаю им мясную похлебку, а ты получишь рецепт.', 'Принесите четыре куска охлажденного мяса зверей Нордскола Орну Хрупкое Копыто в Крепость Песни Войны. Охлажденное мясо можно достать только убивая зверей, обитающих на континенте Нордскол.', 'Прими мою благодарность.', 'Будет мясо – будет и похлебка.', NULL, NULL, 'Охлажденное мясо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13091, 'Нелегко быть водным ужасом', 'Ворота шлюза за стенами моей пещеры так и кишат элементалями, которых врайкульским магам еще только предстоит укротить. Я научу тебя одной хитрости, которая позволит тебе ненадолго подчинять себе этих существ, и ты сможешь всерьез ударить по Йотунхейму.$B$B<Одержимая банши ведьма чертит что-то в воздухе и прикладывает вам ко лбу большой палец.>$B$BИди и открой ворота шлюза! Водный ужас выскочит оттуда и ты, завладев им, сможешь уничтожить всех врагов!', 'По заданию костяной ведьмы из деревни Ньорндар завладейте водяным ужасом и уничтожьте с его помощью 10 врайкулов в окрестностях Йотунхейма.Ваша кара может коснуться йотунхеймских хранителей снов, йотунхеймских воинов, мьординских волхвов воды, ньорндарских копьеносиц и валхальских варгулов.', 'Никогда мне не доводилось видеть такого ужаса в глазах врайкула. Они и впрямь считают себя самыми сильными на свете.$B$BПридется нам показать им, как глубоко они ошибаются.', 'Гадание на костях показывает, что мое задание до сих пор не выполнено.', NULL, NULL, 'Убито йотунхеймских врайкулов с помощью водного ужаса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13092, 'Гадание по костям', 'Завладев этим созданием, я получила доступ ко всей ее силе и знаниям. Это действительно очень удачно. Будучи костяной ведьмой и прорицательницей по рунам, она владеет искусством бросать кости и тем самым определять чью-то судьбу.$B$B<Костяная ведьма усмехается.>$B$BНам с тобой повезло, что я могу повлиять на ее предсказания своей властью.$B$BПринеси мне кости врайкулов, которых ты $gубил:убила: здесь в Йотунхейме, я их брошу и дам тебе шанс $gсамому:самой: определить свою собственную судьбу.', 'Принесите 15 костей врайкулов костяной ведьме в деревню Ньорндар.', 'Давай посмотрим, что готовит тебе день грядущий.$B$B<Костяная ведьма кидает кости на коврик перед собой.>$B$BВыбирай свою судьбу, $C.', 'Меня поражает, что эти создания когда-то имели еще и какую-то власть над миром. С такой примитивной магией!', NULL, NULL, 'Кости врайкула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13093, 'Гадание по костям', '', '', 'Выбирай свою судьбу, $N.', NULL, NULL, NULL, 'Кости врайкула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13094, 'Ни стыда, ни совести', 'Верховный маг Беринард – это представитель Кирин-Тора при Малигосе. Он провел всю свою жизнь, изучая особенности его поведения.$B$BНедавно он передал мне свою работу, \"Чарономикон\", которая содержит в себе карту, которую пытается раздобыть Малигос. К несчастью, я совершила глупость и показала ее неким путешественникам из Орды, которые покупали у меня припасы, и после их ухода карта исчезла!$B$BДолжно быть, они ее украли. Прошу тебя,$C. Последуй за ними в Нексус и найди книгу прежде, чем Беринард захочет ее вернуть.', 'Библиотекарь Серра просит вас зайти в Нексус и найти книгу с исследованиями Беринарда.', 'Ты ее нашел?! Да, слава богам, все на месте. $B$BПожалуйста, прими этот скромный знак признательности. Только умоляю тебя, не говори об этом инциденте Беринарду!..', 'Пожалуйста, $N, скажи мне, что ты нашел книгу Беринарда...', NULL, NULL, '\"Исследования Беринарда\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13095, 'Ни стыда, ни совести', 'Верховный маг Беринард – это представитель Кирин-Тора при Малигосе. Он провел всю свою жизнь, изучая особенности его поведения.$B$BНедавно он передал мне свою работу, \"Чарономикон\", которая содержит в себе карту, которую пытается раздобыть Малигос. К несчастью, я совершила глупость и показала ее неким путешественникам из Альянса, которые покупали у меня припасы, и после их ухода карта исчезла!$B$BДолжно быть, они ее украли. Прошу тебя, $C, последуй за ними в Нексус и найди книгу прежде, чем Беринард захочет ее вернуть.', 'Библиотекарь Серра просит вас зайти в Нексус и найти книгу с исследованиями Беринарда.', 'Ты ее нашел?! Да, слава богам, все на месте. $B$BПожалуйста, прими этот скромный знак признательности. Только умоляю тебя, не говори об этом инциденте Беринарду!..', 'Пожалуйста, $N, скажи мне, что ты нашел книгу Беринарда...', NULL, NULL, '\"Исследования Беринарда\"', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13096, 'Гал\'дара заплатит за все', 'Ты $gвидел:видела:?$B$BЯ в жизни не видел такого кошмара! Великий Акали убит у меня на глазах... Это было ужасно...$B$BЯ поклялся не лезть в это дело. Моя задача – наблюдать. Но всему есть предел! Гал\'дара не должен уйти безнаказанным! Он заплатит за все!$B$BИди в Гундрак и разыщи там Гал\'дара. Смерть Акали требует отмщения. И ты станешь орудием мести. Возвращайся ко мне, когда все будет сделано.', 'Отправляйтесь в Гундрак и убейте Гал\'дара по поручению Тол\'мара из Дубра\'джина.', 'Ты это сделал?! Гал\'дара уничтожен? Негодяй получил по заслугам!$B$BВот, прими это в награду за свои старания.', 'Тебе удалось отомстить за смерть Акали, $R?', NULL, NULL, 'Гал\'дара уничтожен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13097, 'Неоконченное дело', 'Да, это правда: пророк Акали больше не потревожит этот мир, – однако нам предстоит еще многое сделать.$B$BБольшую часть крови Акали принял другой, и именно он представляет угрозу.$B$BВот что, $N, отправляйся в Дубра\'джин, что на севере от Гундрака, и поговори с Тол\'маром. Он подскажет, что делать дальше.', 'Поговорите с Тол\'маром в Дубра\'джине по просьбе Хар\'коа.', 'Слушай, дружище. Работенка тебе предстоит не из легких!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13098, 'Для наших потомков', 'Гундрак обречен.$B$BИстория повторяется у нас на глазах. Когда тролли выступают против своих же богов, конец известен. И он непременно настанет. Это лишь вопрос времени...$B$BНо если мы составим правдивую летопись всех событий, может быть, нам удастся предостеречь будущие поколения, чтобы они не пошли по тому же гибельному пути.$B$BЕсли тебе хватит смелости, отправляйся в Гундрак и разыщи исторические доказательства, которые дадут нам ответ на вопрос, что стало причиной падения империи Драккари.', 'Отправляйтесь в Гундрак и заберите оттуда 6 табличек с летописью Драккари по поручению летописца Ба\'Кини из Дубра\'джина.', '<Ба\'Кини быстро просматривает таблички и вновь обращается к вам.>$B$BДа, это подлинники, $r. Помещу их в свою коллекцию, на подобающее им место.$B$BМожет, нам все-таки удастся вразумить если не современников, то хотя бы потомков.', 'Ты нашел таблички с летописью Драккари?', NULL, NULL, 'Табличка с летописью Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13099, 'Просто проверка', 'Понимаешь, какое дело... со стороны Гундрака постоянно доносится какой-то зловещий грохот. В последнее время – все громче и чаще.$B$BОдна моя давняя ученица ведет наблюдения на посту, расположенном к западу от Гундрака. Может быть, найдешь время, заглянешь к ней и проверишь, все ли у нее в порядке?', 'Поговорите с Ба\'Кини в Дубра\'джине по просьбе То\'кини.', 'Его давняя ученица? Ха!$B$BНу, если понятие \"давняя\" подразумевает \"всю жизнь от рождения\", тогда – да, можно сказать и так.$B$BТо\'кини – мой отец, и к тому же изрядный трус. Сам побоялся соваться так близко к Гундраку... и отправил сюда меня!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13100, 'Мясной рулет в странногрибном соусе', 'У нас снова заказ с доставкой! Мясной рулет с грибами для Ортона Беннета из \"Диковин и редкостей\".$B$BРаздобудь 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса, запеки их в форме для мясного рулета на любом открытом огне и отнеси Ортону.', 'Запеките 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса в форме для мясного рулета и отнесите готовое блюдо Ортону Беннету в лавку \"Диковины и редкости\" на площадь Руноплета в Даларане.', 'Выглядит аппетитно! Спасибо!', 'Ты принес мне поесть?$B$BА то сижу тут, как привязанный. Ни на секунду не выйти из лавки! А кушать-то хочется!', NULL, NULL, 'Мясной рулет в странногрибном соусе', 'Мясной рулет', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13101, 'Сбор в Приюте фокусника', 'Арилль Лазурный Взгляд из \"Приюта фокусника\" ожидает наплыва гостей, ему предстоит приготовить море угощений, чтобы хватило на всех, и очень быстро! $B$BПринеси-ка мне северной похлебки и кувшин с вином из сырной лавки \"Еще по сто\", она находится прямо в центре Даларана. Хозяин лавки как раз задолжал мне винишко. Оно должно быть где-то там, у него в магазине.$B$BОтнеси вино и мясо Ариллю.', 'Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в \"Приют фокусника\" на площади Руноплета.', 'О, да тут на всех с лихвой хватит! Думаю, гости будут довольны.', 'Где же еда? Я жду гостей! Они должны прибыть с минуты на минуту!', NULL, NULL, 'Северная похлебка', 'Кувшин с вином', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13102, 'Рагу для завсегдатаев Стоков', 'Аджаю Грину, хозяину таверны из Стоков Даларана, срочно понадобилось овощное рагу. Припасы подходят к концу, и скоро ему будет нечем кормить клиентов.$B$BСобери 4 морковки из леса Хрустальной Песни и потуши их с 4 кусками охлажденного мяса.$B$BВ лес Хрустальной Песни можно попасть через портал в восточном углу площади Руноплета.$B$BКогда рагу будет готово, отнесите его Аджаю.', 'Потушите 4 морковки из леса Хрустальной Песни с 4 кусками охлажденного мяса в кухонном горшке.Когда овощное рагу будет готово, отнесите его хозяину таверны Аджаю Грину в Стоки Даларана.', 'Его съедят в две секунды! Большое спасибо!', 'Мои постояльцы голодны! Мне срочно нужно рагу.', NULL, NULL, 'Овощное рагу', 'Казанок для жаркого', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13103, 'Сыр для Златоплава', 'Ранид Златоплав из кожевенной лавки вдруг возжелал вина с сыром.$B$BВозьми сыра с полки в сырной лавке под названием \"Еще по сто\" в центре Даларана, а потом пройдись по кабакам и слей остатки вина из всех недопитых стаканов в одну бутылку. Отнеси вино с сыром Раниду.$B$BЕсть предположение, что он ничего и не заметит.', 'Возьмите зрелый даларанский камамбер в сырной лавке \"Еще по сто\", потом пройдитесь по Даларану и слейте в бутылку остатки вина из 6 полупустых бокалов, стоящих на столах.Отнесите вино и сыр Раниду Златоплаву в кожевенную лавку в Торговой палате волшебников.', 'А что?! Неплохой букет!', 'Ты не видел слугу с моим вином и сыром? Жрать хочу – умираю!', NULL, NULL, 'Вино и сыр', 'Пустая сырная тарелочка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13104, 'И снова в Пролом', 'Аванпост укреплен, и ему ничто не угрожает. Мы отбили Долину Эха и уничтожили стены из паутины, закрывавшие вход в Пролом. Пришло время двинуться на Плетхольм и закрепиться в Ледяной Короне. Линия фронта сдвигается!$B$BЯ попросил черного хранителя помочь нам со штурмом Плетхольма. Он много знает о Плети, и эти знания нам пригодятся.$B$BИди к нему. Ты найдешь его в палатке у входа в Пролом, к северо-западу отсюда.', 'Отправляйтесь в распоряжение черного хранителя в Долине Эха, рядом с Проломом.', 'Никто лучше меня не знаком с тактикой Плети.$B$B<Черный хранитель некоторое время внимательно вас рассматривает.>$B$BДо битвы за Часовню Последней Надежды мы с моими рыцарями сражались на стороне Короля-лича. Он контролировал каждый наш шаг. Но все изменило сияние рассвета...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13105, 'И снова в Пролом', 'Аванпост укреплен, и ему ничто не угрожает. Мы отбили Долину Эха и уничтожили стены из паутины, закрывавшие вход в Пролом. Пришло время двинуться на Плетхольм и закрепиться в Ледяной Короне. Линия фронта сдвигается!$B$BЯ попросил черного хранителя помочь нам со штурмом Плетхольма. Он много знает о Плети, и эти знания нам пригодятся.$B$BИди к нему. Ты найдешь его в палатке у входа в Пролом, к северо-западу отсюда.', 'Поговорите с черным хранителем в Долине Эха у входа в Пролом.', 'Ты стал сильнее, мой верный рыцарь.$B$B<Верховный лорд Дарион Могрейн пристально смотрит на вас.>$B$BЧас отмщения близок, брат. Кольтира помогает Орде на борту \"Молота Оргрима\", а Тассариан – Альянсу на борту \"Усмирителя небес\". Очень скоро рыцари Черного Клинка захватят Ледяную Корону и разобьют армии Короля-лича!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13106, 'Черный дозор', 'На Мясопилке Плети создаются поганища и мясистые великаны. Если нам удастся закрыть Мясопилку, то Король-лич останется без значительной части армии.$B$BЯ послал туда те$Nю всадницу Арли. Ее штаб, Черный дозор, расположен на горном хребте, к западу от Корп\'ретара, прямо над Мясопилкой. Я слышал, что Серебряный Авангард собирается послать туда кого-то еще, но темная всадница точно знает, что делать. Найди Арли и помоги ей.', 'Поговорите с темной всадницей Арли в Черном дозоре, что в Ледяной Короне.', 'Хорошо. Я рада любой помощи. От Серебряного Авангарда приехал Олакин. Но меньше слов – больше дела. Надо оставить армию Плети без подкрепления.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13107, 'Сосиски с горчицей!', 'Верховный маг Пентарус любит смотреть битбол и сейчас собирается на матч, но ему нужно взять с собой что-нибудь перекусить.$B$BТебе нужно собрать ему корзинку для пикника. Положишь туда 4 сосиски из мяса люторога и 4 побега полевой горчицы, она растет прямо в городе, на зеленых участках.$B$BСобранную корзинку надо отдать верховному магу, чтобы у него было чем перекусить, пока он будет смотреть игру.', 'Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.Отнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане.', 'Замечательно! Надеюсь, \"Даларанские крушители\" сегодня вырвутся вперед!', 'Я почти готов. Осталось только дождаться, когда мне принесут еду и когда подойдут мои подру... э... мои коллеги-маги.', NULL, NULL, 'Корзинка сосисок с горчицей!', 'Пустая корзинка для пикника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13108, 'Любой ценой!', 'Так или иначе, Локен падет.$B$BДаже если мне лично придется поотрывать ему руки и ноги, он заплатит сполна за свои отвратительные деяния.$B$BЕсли встретишь его раньше меня, честь и слава победителя Локена достанутся тебе.$B$BПринеси мне его лживый язык – и заслужишь мою благодарность и благословение.', 'Отправляйтесь в Чертоги Молний и убейте Локена. Потом возвращайтесь к королю Йоккуму в Дун Ниффелем и отдайте ему язык Локена.', 'Этот подлый червь мертв?$B$BТы принес великое благо моему народу, $R.$B$BПрими этот дар в награду за доблесть и верность.', 'Так что? Локен получил по заслугам?', NULL, NULL, 'Язык Локена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13109, 'Диаметральные противоположности', 'Я скажу прямо, $gмалыш:невеличка:$r. С тех пор, как у нас порвались узы дружбы с Торимом, что-то в нас изменилось... Мы уже не те, что прежде.$B$BКак вождь и правитель, я желаю лишь одного: чтобы мой народ не таил зла на Торима, чтобы их сердца исцелились, и наша дружба с Повелителем Бурь была восстановлена. Твоя победа над Фьорном стала первым шагом на этом пути. Теперь надо сделать следующий шаг...И ты вновь нам поможешь.$B$BВолхан из Чертогов Молний – это враг посильнее Фьорна. И он намного опаснее, потому что он не успокоится, пока не уничтожит нас – или пока не погибнет сам.', 'Отправляйтесь в Чертоги Молний и убейте Волхана по поручению короля Йоккума из Дун Ниффелема.', 'Волхан больше не будет тревожить сон моего народа.$B$BПродолжай в том же духе, малыш $С. Со временем, я уверен, мой народ сумеет простить Торима.', NULL, NULL, NULL, 'Волхан сражен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13110, 'Неупокоенные', 'Далеко не все наши солдаты вернулись из Плетхольма. Многие были убиты и после смерти превращены в чудовищные подобия самих себя. Так поступает Плеть. Души этих бойцов не могут обрести покой. Мы должны помочь им.$B$BОтправляйся через Пролом в Плетхольм и уничтожь оживленных рыцарей. Окропи кости этой святой водой, и их души наконец обретут покой.', 'По поручению отца Густава из Долины Эха в Ледяной Короне окропите кости 10 оживленных рыцарей святой водой, чтобы освободить наконец их неупокоенные души.', 'На пути рыцаря всегда встречается несправедливость и зло. И единственный правильный выбор – бороться с ними до конца. Сегодня ты начал свой путь, и многое еще ждет тебя впереди.', 'Это невеселая задача, $N. Но кто-то должен это сделать.', NULL, NULL, 'Освобождено неупокоенных душ', 'Святая вода', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13111, 'Единственный в своем роде', 'Слушай сюда.$B$BНа первый взгляд, вроде обычная история: тролли выпустили в мир запретные силы, уничтожив своих же богов, которым должны поклоняться.$B$BТак-то оно так, но эти драккари – случай особый. Если все, что я слышала, правда, то в Гундраке сооружают какого-то особенного голема – говорят, что таких еще не было!$B$BТы же $gискал:искала: приключений, да? Вот и давай отправляйся в Гундрак и принеси мне кусок этого самого голема – на предмет изучения.', 'Отправляйтесь в Гундрак, добудьте обломок колосса Драккари и отнесите его летописцу Ба\'Кини в Дубра\'джин.', 'Да, это именно то, что нужно!$B$BВот, это тебе – награда за труды.', 'Ты принес то, о чем я тебя просила?', NULL, NULL, 'Фрагмент колосса Драккари', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13112, 'Мясной рулет в странногрибном соусе', 'Ортон Беннет из \"Диковин и редкостей\" желает мяса с грибами.$B$BРаздобудь 4 странных гриба и 2 куска охлажденного мяса в Стоках Даларана, свари их в котелке на любом открытом огне и отнеси Ортону.$B$BЭх... если бы Совет разрешил мне готовить мои фирменные блюда из гномов, я бы им показал, что такое настоящее объедение!', 'Сварите 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса, чтобы получить мясной рулет, и отнесите готовое блюдо Ортону Беннету в лавку \"Диковины и редкости\" на площадь Руноплета в Даларане.', 'Это мясо от Авило? А ты можешь поклясться, что там нет гномов?', 'Ты принес мне поесть? А то я практически не выбираюсь из лавки. А кушать-то хочется!', NULL, NULL, 'Мясной рулет в странногрибном соусе', 'Мясной рулет', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13113, 'Сбор в Приюте фокусника', 'Прикинь: в Орде приняли закон, запрещающий каннибализм... это кто же такое придумал, хотелось бы знать! И как мне теперь выполнять все заказы?! Это ж я так разорюсь... Впрочем, давай сразу к делу.$B$BАрилль Лазурный Взгляд в \"Приюте фокусника\" скоро принимает у себя гостей. Им надо обеспечить кормежку. Короче, иди в сырную лавку в центре Даларана и возьми там кувшин с вином. И еще ему нужна северная похлебка.$B$BШевелись, Арилль ждет!', 'Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в \"Приют фокусника\" на площади Руноплета.', 'Думаю, гости будут довольны. Только не говори им, что я заказывал еду у Авило.', 'Где еда? Гости прибудут с минуты на минуту!', NULL, NULL, 'Северная похлебка', 'Кувшин с вином', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13114, 'Рагу для завсегдатаев Стоков', 'У нас тут образовался еще один заказец. Хозяину таверны из Стоков Даларана срочно понадобилось овощное рагу, а то ему нечем кормить клиентов.$B$BОн просит именно овощное рагу, а то он, видишь ли, не оценил того сочного гнома, которого я добавил в рагу в прошлый раз. Собери 4 морковки в лесу Хрустальной Песни, потуши их с 4 кусками охлажденного мяса и отнеси Аджаю. В лес Хрустальной песни можно попасть через портал в восточном углу площади Руноплета.', 'Потушите 4 морковки из леса Хрустальной Песни с 4 кусками охлажденного мяса в кухонном горшке.Потом отнесите овощное рагу хозяину таверны Аджаю Грину в Стоки Даларана.', 'С виду вроде бы аппетитно. Спасибо за помощь.', 'Только чтобы на этот раз в рагу не было никаких гномов!', NULL, NULL, 'Овощное рагу', 'Казанок для жаркого', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13115, 'Сыр для Златоплава', 'Ранид Златоплав из кожевенной лавки требует вина и сыра. И чего бы ему не съесть сочного сытного гнома? Не понимаю!$B$BНабери сыра в сырной лавке в центре Даларана, а потом пройдись по кабакам и слей остатки вина из всех недопитых стаканов в одну бутылку. Отнеси вино с сыром Раниду.$B$BВино можешь назвать \"Хмельной сюрприз\", хе-хе.', 'Возьмите зрелый даларанский камамбер в сырной лавке \"Еще по сто\", потом пройдитесь по Даларану и слейте в бутылку остатки вина из 6 полупустых бокалов, стоящих на столах.Отнесите вино и сыр Раниду Златоплаву в кожевенную лавку в Торговой палате волшебников.', 'Замечательное вино! Надо будет узнать, где его производят.', 'Ты не видел слугу с моим вином и сыром? Жрать хочу – умираю!', NULL, NULL, 'Вино и сыр', 'Пустая сырная тарелочка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13116, 'Сосиски с горчицей!', 'Верховный маг Пентарус обожает смотреть свой дурацкий битбол, закусывая в это время чем-нибудь вкусненьким.$B$BТебе нужно собрать ему корзинку для пикника. Положишь туда 4 сосиски из мяса люторога и 4 побега полевой горчицы, она растет прямо в городе, на зеленых участках.$B$BВ общем, обеспечь верховного мага сосисками с горчицей.', 'Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.Отнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане.', 'Замечательно! Надеюсь, \"Даларанские крушители\" сегодня вырвутся вперед!', 'Только смотри, чтобы сосиски были на 100% из люторожьего мяса, без всяких там добавочных субпродуктов типа гномов!', NULL, NULL, 'Корзинка сосисок с горчицей!', 'Пустая корзинка для пикника', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13117, 'Откуда они берутся?', 'Слуги Короля-лича не знают усталости. Они трудятся день и ночь: собирают поганищ и мясных великанов в лабораториях в Мясопилке. Они создают их десятками! $B$BНо им этого мало. К ним туда постоянно прибывают скелетные создания, чтобы ускорить темп работ.$B$BЕсли мы не узнаем, откуда они появляются, и как они умудряются работать так быстро, они сотворят столько чудовищ, что те просто задавят нас числом. Отправляйся на юго-восток и попробуй узнать, откуда берутся эти скелеты.', 'Проведите разведку у алтаря призыва в восточной части Мясопилки и возвращайтесь с докладом к темной всаднице Арли, которая ждет вас в Черном дозоре.', '<Вы рассказываете темной всаднице обо всем, что узнали у алтаря призыва.>$B$BНечто подобное я и подозревала. Мы должны им помешать. Сейчас наша первоочередная задача: уничтожить эти алтари призыва, а потом – всех чудовищ, которых уже успели создать мастера Плети.', 'Ты узнал, откуда берутся эти скелеты?', NULL, NULL, 'Алтарь призыва исследован', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13118, 'Очищение Плетхольма', 'Силы Плети, отправленные на штурм Оплота Серебряного Авангарда, были отброшены. Теперь они, что называется, рвут и мечут. Все узники, находящиеся в Плетхольме, будут казнены и после смерти превращены в слуг Короля-лича.$B$BСеребряный Авангард наверняка обратится к тебе с просьбой достойно проводить этих бойцов. Я же не могу просить тебя об этом. Если мы хотим победить, то должны уничтожить Плеть на корню.$B$BОтправляйся через Пролом на северо-запад, в Плетхольм, уничтожая всех и вся на своем пути.', 'По заданию черного хранителя из Долины Эха в Ледяной Короне уничтожьте 3 верховных жрецов Забытых глубин, 3 королей Забытых глубин и 8 оживленных рыцарей.', 'Ты справился, Консер. Уменьшая таким образом численность вражеской армии, мы выигрываем драгоценное время для Серебряного Авангарда.', 'Не теряй времени, $N.', NULL, NULL, 'Верховный жрец Забытых Глубин убито', 'Король Забытых Глубин убито', 'Оживленный рыцарь убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13119, 'Разрушение алтарей', 'Значит, у этих алтарей они вызывают своих рабочих и воинов?$B$BИми мы и займемся в первую очередь. У мастера призыва должен быть посох для активации портала. Если убить главного призывателя и забрать его посох, с его помощью можно устроить перегрузку портала Призыва и разрушить соответствующий алтарь.$B$BУничтожь все четыре алтаря, и когда все будет сделано, возвращайся ко мне.', 'Убейте главного призывателя Зарода и используйте его посох призыва, чтобы уничтожить первый, второй, третий и четвертый алтари призыва. Когда все будет сделано, возвращайтесь к темной всаднице Арли в Черный дозор.', '<Темная всадница Арли одобрительно кивает.>$B$BХорошо. Теперь мы можем сосредоточить усилия на том, чтобы остановить все работы в остальной части Мясопилки.', 'Тебе удалось уничтожить алтари призыва?', NULL, NULL, 'Первый алтарь призыва уничтожен', 'Второй алтарь призыва уничтожен', 'Третий алтарь призыва уничтожен', 'Четвертый алтарь призыва уничтожен');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13120, 'Взгляд смерти', 'Мясопилка – это крупномасштабный проект, и нам будет трудно уследить за всем, что у них происходит. Но у меня есть план.$B$B<Из складок плаща Арли достает шар и показывает его вам.>$B$BЭто сфера взгляда смерти. С ее помощью мы можем следить за действиями Плети, чтобы знать, где лучше нанести удар.$B$BРазмести такие сферы у трех наиболее важных объектов: у лаборатории поганищ и лаборатории мясистых великанов на юго-западе, а также рядом с огромным зеленым котлом далеко на западе.', 'Разместите сферу взгляда смерти на стойке у лаборатории поганищ, стойке у лаборатории мясистых великанов и стойке в окрестностях котла. Когда все будет готово, возвращайтесь к темной всаднице Арли в Черный дозор.', '<Темная всадница Арли закрывает глаза, словно сосредоточившись на некоей далекой невидимой цели.>$B$BЯ наблюдаю за врагом глазами самой смерти. Теперь, владея информацией, мы уничтожим их всех до единого.', NULL, NULL, NULL, 'Сфера размещена у лаборатории поганищ', 'Сфера размещена у лаборатории мясистых великанов', 'Сфера размещена в окрестностях котла', 'Сфера взгляда смерти');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13121, 'Чужими глазами', 'Если мы хотим победить, то должны ударить по Королю-личу его же оружием.$B$BНа горе, находящейся к юго-западу отсюда, стоит крепость Кул\'галар. В ней живут йотунхеймские оракулы, которые подчиняются своему хозяину и следят за всеми с помощью Ока Короля-лича.$B$BВот это-то Око тебе и надо добыть. Увидеть, что происходит в цитадели Ледяной Короны, с его помощью не удастся, зато мы сможем узнать что-то важное о нашем противнике, чтобы затем принять верное решение.', 'По просьбе костяной ведьмы из деревни Ньорндар добудьте информацию о противнике с помощью Ока Короля-лича.', 'Отлично! Слухи не врут: Искальдер – действительно лучший воин-врайкул из всех когда-либо живших. Сама Вардмадра собирается его судить!$B$BДавай поторопимся, пока они не добрались до древнего героя первыми.', 'Тебе не удалось ничего узнать?! Так-то ты благодаришь меня за помощь тебе и рыцарям Черного Клинка?$B$BИди и без нужных мне сведений не возвращайся!', NULL, NULL, 'Сведения для костяной ведьмы собраны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13122, 'Камень Плети', 'Камень Плети дается каждому солдату Плети при рождении или после создания. Он дает им дополнительную силу, а их правителями – возможность наблюдать за тем, где находится и что делает каждый из солдат.$B$BЕсли у меня будет достаточное количество таких камней, то, возможно, я смогу отслеживать перемещение сил Плети внутри Ледяной Короны.$B$BУничтожая воинов Плети в Плетхольме, не забывай забирать у них камни. Когда их наберется достаточно, возвращайся ко мне.', 'Принесите черному хранителю из Долины Эха в Ледяной Короне 15 камней Плети.', 'Так, давай-ка посмотрим, что можно сделать с этими камнями.', 'Камни Плети помогут нам отслеживать перемещения сил противника.', NULL, NULL, 'Камень Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13124, 'И вновь продолжается бой', 'Битва продолжается, $N. Нам чудом удалось избежать обнаружения, и теперь мы по-прежнему пытаемся сорвать планы Малигоса. Но на этом хорошие новости заканчиваются... $B$BДаже самые лучшие наши попытки не привели практически ни к чему. Малигос и его прислужники продолжают набирать силу! К тому же, последний посланный нами диверсионный отряд был схвачен и помещен в окулус.$B$BМы должны попытаться их спасти! Белгаристраз и его товарищи крайне важны для выполнения нашей миссии. Мы можем на тебя рассчитывать, $N?', 'Релораз просит вас войти в Окулус и спасти Белгаристраза с его командой.', 'Слушай меня внимательно, $R.$B$BТвоя работа здесь только началась!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13125, 'Чистое небо', 'Если мы хотим освободить эти земли от сил Плети, надо уничтожить хозяев Плетхольма.$B$BСалнаракс Резчик Плоти руководит храмом на первом ярусе Плетхольма. Неподалеку от него, в башне духов на втором ярусе, располагается верховный жрец Ят\'амон. А король подземелий Талонокс находится в Яме чудовищ, это на верхней дороге.$B$BВсе трое очень опасны. Будь $gосторожен:осторожна: и, если понадобится помощь, труби в этот рог. Рыцари смерти Акеруса не оставят тебя в беде.', 'По заданию черного хранителя из Долины Эха в Ледяной Короне убейте Салнаракса Резчика, короля подземелий Талонокса и верховного жреца Ят\'амона.', 'Нелегко тебе досталась эта победа, Совух! Убитых врагов заменят другими, но по крайней мере, сегодня небо над Плетхольмом будет чистым.', 'Прикончи их, $N!', NULL, NULL, 'Салнаракс Резчик Плоти убито', 'Король подземелий Талонокс убито', 'Верховный жрец Ят\'амон убито', 'Боевой рог Акеруса');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13126, 'Единым фронтом', 'Прими нашу благодарность, $r.$B$BТы и твои друзья помогли нам одолеть Дракоса, но теперь нам придется объединить усилия.$B$BПрямо над нами за непроницаемым барьером скрывается Варос. Чтобы добраться до него, тебе придется убить Центрифужные создания, которые питают его щит. После этого мы с друзьями присоединимся к тебе... $B$BКаждый из нас предоставит тебе дрейка, с помощью которых ты сможешь одолеть Вароса.', 'Белгаристраз просит вас уничтожить 10 Центрифужных созданий, разрушить щит Вароса и одолеть самого Заоблачного Странника.', 'Все получилось так, как мы рассчитывали, $R. Мы хорошо сработались!$B$BПускай же наш союз приведет нас к новым победам.', NULL, NULL, NULL, 'Убито центрифужных созданий', 'Убит Варос Заоблачный странник', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13127, 'Маг-лорд Уром', 'Теперь нам осталось преодолеть только одно препятствие, $C, и имя ему Уром.$B$BОн ждет нас наверху, на третьем кольце. Берегись, друг, ибо он могучий волшебник. Только тебе под силу бросить ему вызов.$B$BУбей его, и пусть он поплатится за то, что встал на сторону нашего врага!', 'Белгаристраз просит вас победить Мага-лорда Урома в Окулусе.', 'Победа близка, друг мой.$B$BСосредоточься, ибо тебя ждет настоящее испытание.', 'Ты уже победил мага-лорда Урома ?', NULL, NULL, 'Маг-лорд Уром убит', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13128, 'Высокие ставки', 'Настало время сразиться с Эрегосом, друг мой.$B$BОн сильный и хитрый противник. Как один из наиболее доверенных слуг Малигоса, он черпает силы из энергии, которой он заряжен.$B$BОдолеть его будет непросто...$B$BНо победа над магом-лордом дала возможность воспользоваться полной силой наших дрейков, и теперь их умения будут в твоем распоряжении. Воспользуйся ими с умом – и Эрегос вскоре падет. $B$BЕсли тебе будет сопутствовать удача, вернись к Релоразу и расскажи ему о нашей победе.', 'Белгаристраз просит вас убить Эрегоса в Окулусе, после чего оповестить о его смерти Релораза из лагеря под Маскировочным щитом в Хладарре.', '<Релораз внимательно выслушивает ваш отчет.>$B$BВертэкс, это самые желанные новости за долгое время.$B$BС самого начала нашего противостояния нам еще не удавалось нанести такого сокрушительного удара Повелителю Магии. $B$BПрошу тебя, друг мой, прими этот скромный дар.', NULL, NULL, NULL, 'Эрегос уничтожен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13129, 'Игры разума', 'Этих лентяев только могила исправит... Погоди! Я знаю, как их проучить.$B$B<Курцель отрывает длинную полоску от своей рубахи и протягивает ее вам.>$B$BДержи, $r. Приложи ее к останкам этого мерзкого лича и принеси ее Маку в лагерь.$B$BПусть они помучаются угрызениями совести.$B$BБольше они никогда не позволят девушке разгуливать тут в одиночестве!', 'Курцель просит вас приложить клочок ее рубахи к трупу Новоса Призывателя, после чего отнести запятнанную лимфой ткань Маку.', '<Мак переводит на вас взгляд и начинает безудержно рыдать.>$B$BО нееет... Эта тупоголовая девка все-таки попалась кому-то в лапы?$B$BНадо сочинить про это песенку. Пожалуй, это умерит мою скорбь... ик!', '<ик>$B$BЭто что там у тебя за тряпка?', NULL, NULL, 'Запятнанная лимфой ткань', 'Клочок рубахи Курцель', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13130, 'Первый камень', 'Сейчас Плетхольм – мерзкая яма, кишащая порождениями мрака. Но однажды он станет славной и гордой твердыней. Верховный лорд Фордринг сказал, что назовет ее \"Крепость Справедливости\".$B$BУвы, строительство даже такой великолепной крепости, как цитадель Ледяной Короны, пришлось начинать когда-то с одного-единственного камня. Вот и нам нужен такой камень.$B$BОтправляйся в лес Хрустальной Песни, который лежит к югу отсюда. На востоке этого леса найди Дикую чащу. В ней собери с земли хрустальную древесину, а в руинах Шандарала найди старую эльфийскую кладку.', 'По заданию архитектора ордена Силаса из Долины Эха добудьте 10 бревен хрустальной древесины и 10 обломков древней эльфийской кладки.', 'Древесина сама по себе устойчива к порче и разложению. А уж хрустальная древесина и вовсе убивает всяческие грибки и болезни! Эльфийская кладка, столько лет испытывавшая на себе чудодейственное влияние Дикой чащи, обладает теми же свойствами.$B$BСкоро начнется строительство.', 'Ты что, заблудился?', NULL, NULL, 'Кристаллическая древесина', 'Древняя эльфийская кладка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13131, 'Пустой сундук', 'Нет, ты глянь! В моем сундуке шаром покати. Мне бы давно уже следовало наполнить десяток таких сундуков!$B$BМои товарищи прямо взвились при виде такой богатой добычи... и посмотри, что с ними стало теперь! Во что они превратились?! В ходячие скелеты, гремящие костями!$B$BМатушка мне всегда говорила: \"Хуже ненайденного сокровища может быть только проклятое сокровище!\"$B$BНо я так думаю, там дальше есть еще больше, и то золото уже не проклято, наверняка. Этим пьяницам оно ни к чему – для них это так, бесполезный мусор.$B$BДобудь для меня эти сокровища, а я уж тебя не обижу, отблагодарю, как положено.', 'Принесите Бриггу на вершину Утгард 5 непотускневших серебряных слитков, 3 сверкающих кристалла, 2 золотых кубка и нефритовую статуэтку.', 'Отлично! У тебя получилось, дружище!$B$BТеперь я могу пойти к капитану и не бояться, что он прикончит меня на месте. Так что большое тебе спасибо. И тебе, и твоим друзьям.$B$BВот, возьми. Так сказать, в знак благодарности. Ты заслужил.', 'Ну, что? Как успехи?', NULL, NULL, 'Непотускневший серебряный слиток', 'Сверкающий кристалл', 'Золотой кубок', 'Нефритовая статуя');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13132, 'Отмщение', 'Да! И я бы не стал их винить, $gдруг:подруга:. Любой на их месте сделал бы так же.$B$BОни набросились на это золото... думали, что нашли настоящее сокровище... золотые горы, ага... А посмотри, что с ними стало теперь! Во что они превратились?! В безмозглых прислужников, не способных поднять ни единого дублона.$B$BМне, считай, повезло. Только чудом меня миновала такая же злая судьба. Когда все бежали, меня сбили с ног – ну, вообще-то, я сам свалился, если начистоту... был малости подвыпивши, да. А потом я увидел, как первый из них превратился в...$B$BБудь $gдругом:добра:, найди, кто тут главный, и сделай так, чтобы он поплатился за то, что подсунул моим друзьям проклятое сокровище.', 'Убейте короля Имирона по просьбе Бригга из вершины Утгард.', 'Вот и славно! Может, теперь мои бывшие друзья упокоятся с миром.$B$BВот, возьми, друг. И пусть никто не говорит, что старина Бригг не умеет отблагодарить тех, кто проявляет к нему доброту и участие.$B$BС тобой приятно иметь дело.', NULL, NULL, NULL, 'Король Имирон убит', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13133, 'Поиски древнего героя', '$N, немедленно отправляйся на юго-запад, в Залы Предков!$B$BТам ты найдешь спящих мьординов. Разбуди их и разыщи Искальдера. Потом используй этот амулет и приведи Искальдера ко мне.$B$BСтупай прямо сейчас. Нельзя терять ни минуты!', 'Приведите Искальдера к костяной ведьме в деревню Ньорндар.', 'Он самый! Герой отлично послужит нашим целям.$B$BМы используем его, чтобы поймать Вардмадру в ловушку! Главное, сделать все правильно.', 'Где древний герой?$B$BУ нас нет времени на праздную болтовню. Иди в Залы Предков и разыщи его, пока не поздно!', NULL, NULL, 'Искальдер доставлен к костяной ведьме', 'Амулет костяной ведьмы', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13134, 'Пролитая кровь', 'Плеть не может создавать своих мясистых чудовищ без крови и бальзамирующей жидкости, которая консервирует части тел и дает им возможность функционировать. Если лишить их этого сырья, армия Плети скоро начнет разваливаться на части – в буквальном смысле слова, – и мы с легкостью уничтожим их поганые творения.$B$BВ лабораториях, где они создают своих мясистых великанов и поганищ, ты найдешь чаны с бальзамирующей жидкостью и громадные шары, заполненные кровью. Уничтожь их, а если кто-то попытается тебе помешать – убей его на месте!', 'Уничтожьте 5 чанов с бальзамировочным составом и 5 кровавых сфер по просьбе темной всадницы Арли из Черного дозора.', '<Мрачный, гулкий смех встречает вас по возвращении.>$B$BОт тебя пахнет победой, $N, и это поистине хорошие новости!', NULL, NULL, NULL, 'Уничтожено кровавых сфер', 'Уничтожено чанов с бальзамировочным составом', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13135, 'Кристаллы энергии', 'На юго-востоке отсюда, на восточных окраинах леса Хрустальной Песни, есть место, известное как Дикая чаща. В этой чаще живут самые разные существа, непохожие друг на друга. Но у них есть одно общее свойство: они все обладают магической энергией. В каждом из них заключен кристаллический источник чистой энергии. Ее там столько, что, если она по какой-то причине дестабилизируется, может произойти такой мощный выброс, что мы все погибнем!$B$BОтправляйся в Дикую чащу, убей нескольких тамошних обитателей и забери у них кристаллы энергии. Нам нужно топливо, а им нужно умереть. Это называется \"взаимовыгодный обмен\".', 'Принесите 8 источников кристаллизованной энергии инженеру ордена Шпицпатрику в Долину Эха в Ледяной Короне.', 'Замечательно. Теперь мы быстро раскочегарим наш бомбардировщик!', 'Ты добыл кристаллизованную энергию?', NULL, NULL, 'Кристаллизованная энергия', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13136, 'Зазубренные осколки', 'Вы вынимаете из тела вурдалака обломок какого-то темного ломкого металла. Обломок по краям зазубренный и неровный, что дает основания предположить, что либо его выковал неумелый мастеровой, либо это кусок, отломившийся от какого-то большого клинка.$B$BВы вспоминаете, что вы извлекали похожие куски из тел других вурдалаков в Мясопилке, – и задаетесь вопросом, зачем создатели этих тварей помещают в них куски металла. Может быть, рыцарь Олакин Сайнрит сумеет ответить на этот вопрос, если вы принесете ему еще несколько похожих железяк.', 'Принесите 10 зазубренных осколков рыцарю Олакину Сайнриту в Черный дозор.', '<Олакин перебирает осколки металла.>$B$BГоворишь, эти штуки есть в телах всех вурдалаков? Странно... Я уже столько лет сражаюсь с Плетью, но такого не видел ни разу.', 'Это что за мерзость?', NULL, NULL, 'Зазубренный осколок (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13137, 'Не совсем честный бой', 'Из всех вершин, нависающих над Йотунхеймом на юго-западе, ближе всех к облакам вершина Боевого Шрама. Это особое место для врайкулов, ристалище для поединков чести, второе по значимости после Валхаласа.$B$BНо мы отправимся туда не на поединок чести.$B$BСобери свою команду и лети на вершину. Когда будешь $gготов:готова:, зажги сигнальный огонь, и я вселюсь в тело Искальдера.$B$BМы будем драться, ты победишь, и Вардмадра непременно придет поглядеть на сражение.', 'Одержите победу над Искальдером на вершине Боевого шрама по поручению костяной ведьмы из деревни Ньорндар.', 'Я спрятала Вардмадру в надежном месте. Пусть подождет в безопасности, пока мы готовим окончательное отмщение!', 'Тебе все еще нужно победить древнего героя!', NULL, NULL, 'Искальдер побежден в бою', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13138, 'Непонятный металл', '$gОлакин перекатывает на бронированной ладони один из осколков.>$B$BТакой может пробить любую броню. Надо выяснить, из чего они сделаны, и что Король-лич собирается с ними делать.$B$BМаликрисс можно найти на востоке, рядом с Цитаделью Ледяной Короны. Из немногих сообщений, дошедших до нас, мы знаем, что там установлено много плавильного и кузнечного оборудования. Отнеси туда эти осколки и расплавь их в одном из горнов на нижнем уровне Маликрисса. Когда металл переплавится и затвердеет, мы сумеем его опознать.', 'Переплавьте мешок зазубренных осколков в одной из кузней Маликрисса. Потом возвращайтесь в Черный дозор и отдайте выплавленный слиток металла рыцарю Олакину Сайнриту.', 'Это, вне всяких сомнений, неочищенный саронит. Мы видели оружие, сделанное из него, в руках лучших воинов Короля-лича, а теперь они вооружают им кого ни попадя. Должно быть, они добывают руду в гигантских масштабах!', 'У тебя получилось расплавить куски металла?', NULL, NULL, 'Выплавленный слиток металла', 'Мешок зазубренных осколков', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13139, 'Ледяное сердце Нордскола', 'Сайлас и Шпицпатрик ушли добывать материалы и топливо, необходимые для того, чтобы начать строительство Крепости Справедливости. Благодаря тебе и рыцарям Черного Клинка, численность приспешников Плети в Плетхольме существенно сократилась, и все их лейтенанты убиты.$B$BЯ уже выбрал место, где мы приступим к работам, но сначала ты $gдолжен:должна: доставить мое донесение верховному лорду Тириону Фордрингу. Мы отправимся в Ледяную Корону по его приказу.', 'Доставьте донесение отца Густава верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.', 'С твоей помощью нам удалось закрепиться на линии фронта. Первая настоящая победа в этой войне уже практически в наших руках – осталось сделать последний, решающий шаг.$B$BМожешь не сомневаться, Консер, силы Плети не сдадутся без боя. Тебе предстоит непростая работа.', 'Вольно, $N. Докладывай.', NULL, NULL, 'Доклад отца Густава (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13140, 'Руноковы Маликрисса', 'Найденные тобой осколки могут быть только из Маликрисса. Именно там обрабатывают металл для армии Короля-лича. Маликрисс находится на востоке от Корп\'ретара.$B$BУдивительно другое: этот металл не используется ни при создании поганищ и мясистых великанов, ни для призыва скелетов. На самом нижнем уровне Маликрисса ты найдешь скелетов-руноковов. Добудь пластины, над которыми они работают. Надо узнать, зачем этот металл поставляется на Мясопилку.', 'Принесите рыцарю Олакину из Черного дозора 5 рунических саронитовых пластин.', 'Пластины практически идеально совпадают с найденными осколками. Должно быть, они используют их, чтобы получать еще более сильных вурдалаков. Плеть пойдет на все ради победы. И это еще один повод поскорее уничтожить это отвратительное место!', 'Тебе удалось добыть саронитовые пластины?', NULL, NULL, 'Руническая саронитовая пластина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13141, 'Битва за Вершину Рыцарей', '$gВерховный лорд Фордринг держит в руках знамя Серебряного Авангарда.>$B$BЭто не просто знамя, $N. Оно несет на себе благословение и потому способно очищать большие пространства зараженной порчей земли.$B$BОтнеси штандарт через Пролом на северо-запад, в место, которое эти мерзавцы из Плети в насмешку назвали Вершиной Рыцарей. Установи его там, где свалены в кучу черепа наших павших соратников и защити Вершину Рыцарей от нападения. Когда земля будет очищена, возвращайся к отцу Густаву.$B$BПоторопись, $N. И пусть твое сердце не знает страха!', 'Отправляйтесь на Вершину Рыцарей и установите благословенное знамя Авангарда на груде рыцарских черепов. Защищайте знамя от солдат Плети, пока земля на Вершине Рыцарей не очистится от порчи. Затем возвращайтесь к отцу Густаву в Долину Эха в Ледяной Короне.', 'Слава Свету! Мы взяли вершину! Наконец-то можно будет начать строительство Крепости Справедливости! Верховный лорд Фордринг и его рыцари уже на пути к нашему новому лагерю. Встреть их, $N!', NULL, NULL, NULL, 'Битва за Вершину Рыцарей', 'Благословенное знамя Авангарда', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13142, 'Месть банши', 'Пришло время, $N, тебе и твоим друзьям встретиться лицом к лицу с хозяином цитадели Балагарда, владыкой Йотунхейма, верховным таном Балагардом.$B$BНа вершине крепости, расположенной в юго-западной части Йотунхейма, есть рог. Дунь в него, и твой вызов будет услышан.$B$BБалагарду не останется ничего другого, кроме как выйти с тобой на поединок. А я... прости, но вместо меня пойдет Вардмадра.$B$B<Одержимая банши ведьма издает душераздирающий смех.:', 'Отомстите за костяную ведьму из деревни Ньорндар, бросив вызов верховному тану Балагарду и победив его.', 'У меня нет слов, чтобы описать, что я чувствую сейчас, $N. Месть свершилась. И мне остается лишь малое.$B$BКак жаль, что меня там не было и я не видела своими глазами, как пал Король-лич.$B$BНо ты особо не обольщайся: с Йотунхеймом еще далеко не покончено. Я буду оставаться в теле этой ведьмы, пока не пойму, что врайкулам ничто больше не угрожает.$B$BОсмотрись. В этой пещере много ценного. Выбирай.', 'Верховный тан Балагард все еще жив. Ты что, не нашла крепость?', NULL, NULL, 'Верховный тан Балагард убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13143, 'Новобранец', 'Начнем с самого главного. Я видел несколько гибких ловцов на крепостных стенах к востоку от нас. До того, как наши пути с Артасом разошлись, они служили мне и были отменными разведчиками… хотя для этого приходилось использовать глаз власти.$B$BСлетай туда, найди кого-нибудь из ловцов, задай ему трепку, а потом покажи эту печать Черного Клинка, и тогда он покорится тебе и будет слушаться беспрекословно. Ловец узнает печать, можешь не сомневаться. Отведи его на вершину скалы к северо-востоку отсюда, и он сам найдет дорогу ко мне.', 'Приведите укрощенного гибкого ловца на вершину скалы к северо-востоку от Высоты Страдания по указанию Верета Хитрого с Высоты Страдания.', 'Я приковал тварь к столбу, но мне не помешало бы заполучить еще парочку-троечку.$B$BА теперь давай займемся этим глазом власти.', NULL, NULL, NULL, 'Укрощенный гибкий ловец доставлен на место', 'Печать Черного Клинка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13144, 'Одним скелетом – двух воинов Плети!', 'В лаборатории поганищ в Мясопилке уже завершились работы сразу над несколькими созданиями. Пока что их держат прикованными к колоннам по периметру лаборатории, но если мы срочно не примем меры, эти создания выйдут на марш с армией Короля-лича.$B$BЦепкие руки, что тянутся из груд костей, разбросанных по всей Мясопилке – это руки скелетов, наделенных магической силой огня. Разыщи несколько этих скелетов, освободи их и приведи к завершенным поганищам. А потом отойди чуть в сторонку и наслаждайся спектаклем!', 'Уничтожьте 3 прикованных поганищ с помощью пылающих скелетов по поручению темной всадницы Арли из Черного дозора.', 'Замечательно. Что может быть лучше, чем проснуться с утра пораньше и вдохнуть запах поджаренной прогнившей плоти! Это запах победы над Плетью.', 'Тебе удалось уничтожить поганищ?', NULL, NULL, 'Сожжено прикованных поганищ', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13145, 'Зловещая крепость', 'Нам нужно понять, с чем нам придется столкнуться.$B$BРазведай местность, управляя гибким ловцом с помощью глаза власти. Есть несколько мест, которые мне показались особенно подозрительными, удели им особое внимание: дозорное укрепление на северо-востоке, цеха на юго-востоке, большая кузница ближе к центру и площадка для совершения обрядов на юго-западе.$B$BЛовец – отличный прыгун, и не боится глубоких провалов. Это тебе пригодится, чтобы преодолевать крепостные стены.', 'Используйте гибкого ловца для разведки в Маликриссе по поручению Верета Хитрого с Высоты Страдания.', 'Блестяще сработано. В общем, я знал, что какие-то рыцари смерти до сих пор хранят верность Артасу. Но я думал, что их значительно меньше.$B$BОн и вправду использует все средства, чтобы завладеть троном Акеруса. Разрушить крепость из чистого саронита будет непросто. Хотя это нам не нужно… мы можем помешать производству и нейтрализовать предводителей рыцарей смерти прежде, чем они станут серьезной угрозой.$B$BНо самое главное, нам надо отсечь рыцарей смерти от их командиров, чтобы мы могли нанести удар.', NULL, NULL, NULL, 'Исследован алтарь Жертвоприношения', 'Исследована Кровавая кузница', 'Исследовано укрепление Ледяного взора', 'Исследована лавка Чародейских товаров');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13146, 'Предсказуемые и тупые', 'Нужно посеять неразбериху… все, что угодно, лишь бы отрезать рыцарей смерти от их предводителей. Если мы разделаемся с их приспешниками, думаю, они станут более пристально следить за ходом операции.$B$BПоганища – легкая добыча, они медлительны, предсказуемы и, самое главное, тупы. Воспользуйся их доверием к ловцам, чтобы подтащить к ним побольше бомб Плети, которые разбросаны по всей стройке. Ты успеешь поджечь фитили значительно раньше, чем они сообразят, что происходит.', 'Используйте железную цепь гибкого ловца, чтобы подтащить бомбы Плети к 4 неповоротливым страшилищам внутри Маликрисса.', 'Они даже не сообразили тебя схватить? Я же говорил, что они предсказуемые и тупые.', NULL, NULL, NULL, 'Доставлено на место бомб Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13147, 'Сваха', 'Основное различие между варгулами и другой мелкой нежитью заключается в том, что у варгулов хватает сообразительности отлынивать от выполнения грязной работы. Ни один варгул не согласиться работать бок о бок со скелетами или вурдалаками.$B$BПредлагаю использовать этот факт и стравить между собой громил из тени и прочую нежить Малакрисса. Производство из-за этого неизбежно замедлится, и у рыцарей смерти начнутся проблемы.$B$BВсе просто: как только кто-то из громил оказывается рядом с другой нежитью, кидаешь в него камнем.', 'По поручению Верета Хитрого с Высоты Страдания с помощью гибкого ловца бросайте камни в громил из тени, когда они оказываются рядом с другой нежитью Маликрисса. Возвращайтесь, когда вам удастся развязать 5 драк.', 'А правда, зачем жертвовать своими солдатами, если эти ребята и так друг друга с радостью ухлопают?', NULL, NULL, NULL, 'Драка между рабочими развязана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13148, 'Починка ожерелья', 'На этом сломанном ожерелье выгравирована надпись, которая гласит: \"Собственность Тимоти Джонса – Ювелирные изделия, Картье и Ко. – Торговый район – Даларан\".$B$BВозможно, вам следует починить его и вернуть владельцу.', 'Почините ожерелье с помощью одного камешка кальцедония и верните его Тимоти Джонсу в его ювелирную мастерскую в Торговую палату волшебников Даларана.', 'Как ты его нашел? Очень много подобных ожерелий было украдено из одной из моих партий товара несколько недель назад! Позволь мне отплатить тебе за находку этим жетоном ювелира.', 'Что привело тебя сюда?', NULL, NULL, 'Прелестное ожерелье из кальцедония', 'Поврежденное ожерелье', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13149, 'Развеянные иллюзии', 'Вечно они вмешиваются...$B$BПроклятые драконы Бесконечности снова хотят нарушить ход истории, пытаясь предотвратить предательство принца Артаса.$B$BЕсли они смогут убедить его, что зерно не заражено чумой, то он не примет рокового решения уничтожить Стратхольм.$B$BНельзя этого допустить!$B$BКак только увидишь ящик с зерном, воспользуйся Разбивателем Чар, чтобы открыть его истинную сущность. Когда закончишь, найди меня у входа в Стратхольм – это к северу отсюда.', 'Хроми попросила вас снять маскировку с подозрительных ящиков с зерном с помощью Разбивателя Чар, после чего найти ее у входа в Стратхольм.', 'Ты отлично справился, $N! Артас нашел зачумленное зерно. $B$BНо, боюсь, наша работа на этом не заканчивается. Слушай внимательно...', NULL, NULL, NULL, 'Маскировка снята с зачумленного зерна', 'Разбиватель чар', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13150, 'zzOLDПотерянное устройство', 'К обратной стороне устройства прикреплена записка, из которой следует, что его владельцем является некий Тимоти Джонс, имеющий ювелирный магазин в некоем квартале Даларана. Пожалуй, он может вознаградить вас, если вы почините и вернете ему прибор.', 'Почините прибор и верните его Тимоти Джонсу в ювелирный магазин Даларана.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13151, 'Королевский эскорт', 'Драконы Бесконечности так просто не сдадутся. К сожалению, я не знаю, что еще они задумали, но что-то подсказывает мне, что мы с ними еще встретимся.$B$BВсего через мгновение Артасу придется принять судьбоносное решение.$B$BНе расслабляйся, $N, ибо на карту поставлено многое. Я прошу тебя сопровождать принца во время очищения Стратхольма. $B$BАртас должен остаться в живых и победить Мал\'Ганиса!', 'Хроми попросила вас сопровождать Артаса во время очищения Стратхольма. Вернитесь к ней, когда Мал\'Ганис будет убит.', 'Ты молодец, $N.$B$BМы сорвали планы драконов Бесконечности и сохранили историю неприкосновенной.$B$BОт лица всех Бронзовых драконов благодарю тебя за помощь!', NULL, NULL, NULL, 'Мал\'Ганис убит', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13152, 'Визит к доктору', 'Стало быть, эти деятели в Святилище воскрешения решили оснащать вурдалаков осколками саронита? Надо им помешать, пока они не применили этих вурдалаков против наших войск.$B$BРазыщи вход в Святилище воскрешения – это где-то в Мясопилке, рядом с лабораторией мясистых великанов. \"Отец-предводитель\" вурдалаков, доктор Сабнок, держит там самое грозное и опасное из всех своих созданий, Заплатня. Освободи Заплатня от цепей и помоги ему отомстить доктору за все. Пусть творение само расправляется со своим творцом!', 'По указанию темной всадницы Арли из Черного дозора отправляйтесь в Святилище воскрешения, разрушьте металлическую стойку, к которой прикован Заплатень, и помогите ему отомстить доктору Сабноку.', '<Темная всадница Арли недобро смеется, запрокинув голову>$B$BПодходящий конец для \"доброго доктора\", ты не находишь?', NULL, NULL, NULL, 'Заплатень освобожден', 'Помогите Заплатню убить доктора Сабнока', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13153, 'Охрана для воинов', '$N, рада тебя видеть. Пока в битве наступило затишье, мы должны торопиться и пополнить наши запасы. Проведенные мной исследования показывают, что доспехи солдат, недавно убитых у Ледопадов, накапливают невероятное количество энергии. Орда тоже собирает доспехи в этой области.$B$BОтправляйся к Ледопадам и уничтожь всех бойцов Орды, каких сможешь там обнаружить. Принеси мне их укрепленные доспехи.$B$BЕсли ты не встретишь там никого из Орды, может, наткнешься на доспехи какого-нибудь искателя приключений, сраженного элементалями.', 'Принесите 10 комплектов прочных доспехов Орды из Ледопадов по приказу колдуньи Кайланы из крепости Ледяных Оков.', 'Фу. Да они вся в крови. Нельзя, что ли, было их сначала хотя бы помыть?', 'Ну как, получилось достать доспехи?', NULL, NULL, 'Прочный доспех Орды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13154, 'Кости и стрелы', 'Эти драконы просто поразительны! Ну, по крайней мере, их кости! Я снабжал наших лучников наконечниками стрел из драконьей кости. К сожалению, после резни в Ангратаре собирать кости на Драконьем Погосте стало практически невозможно.$B$BНо в лесу Теней, что на западном краю Ледяных Оков, достаточно костей, чтобы пополнить наши запасы.$B$BНаправляйся в лес Теней и принеси любые осколки костей, какие только сможешь найти!$B$BОрда тоже собирает осколки в этом районе. Убей их всех!', 'По просьбе лучника Рандольфа из крепости Ледяных Оков отыщите 10 колчанов со стрелами из драконьих костей в лесу Теней.', 'Отлично! Этими дровишками мы подкормим костер войны на несколько дней вперед.', 'Как прошла охота на кости? До меня доходили слухи, что место это облюбовали духи, но у меня никак ноги не доходят сходить посмотреть на них самому.', NULL, NULL, 'Колчан со стрелами из драконьих костей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13155, 'Верет Хитрый', 'До меня уже доходили слухи про Маликрисс и про то, что Артас учредил новый орден рыцарей смерти, но я думал, что это так... баловство... чтобы заполнить пустое место. Но судя по этим цифрам, он нацелился на что-то большее.$B$BНе так давно мы отправили в Маликрисс нашего лучшего разведчика – Верета Хитрого. Ты найдешь его на Высоте Страдания, к западу от Маликрисса, во Дворе Костей.$B$BПостарайся проникнуть туда незаметно, не привлекая излишнего внимания.', 'Разыщите Верета Хитрого на Высоте Страдания в Ледяной Короне.', 'Зловещая Крепость... лишнее подтверждение тому, как сильно Артас не любит проигрывать. Ладно, всадим клинок поглубже.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13156, 'Редкое растение', 'Ух, ну и холодно же здесь! Напоминает мне штормовые вершины Каариноса на Аргусе. Меж тем, со всем этим снегом и льдом наши солдаты могут легко подхватить простуду.$B$BОтправляйся в степь Жизни, что в юго-западной части Ледяных Оков, и принеси мне 10 стелящихся красных растений. Я измельчу их и сделаю лекарство, которое поможет защититься от простуды.$B$BОрда тоже занимается сбором трав в этих краях. Не стесняйся, убивай их и забирай траву!', 'Отберите по просьбе анахорета Тессы из крепости Ледяных Оков 10 сумок Орды с травами у ордынских игроков в степях Жизни.', 'Отлично! Это поможет защитить наших бойцов от простуды.', 'Я надеюсь, ты случайно не тронул ни одного корнехлеста? Ох, ну и досталось от них рядовому Доану на прошлой неделе!', NULL, NULL, 'Сумка Орды с травами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13157, 'Вершина Рыцарей', 'Тебе есть чем гордиться. Ты $gпомог:помогла: нам упрочить положение Серебряного Авангарда в стенах Ледяной Короны, $N. Но теперь Король-лич со своими погаными приспешниками угрожает Вершине Рыцарей напрямую.$B$BВерховный лорд Фордринг и уцелевшие рыцари ждут тебя на Вершине Рыцарей. Тебе нужно снова пройти через Пролом и разыскать верховного лорда Фордринга.', 'Разыщите верховного лорда Тириона Фордринга на Вершине Рыцарей в Ледяной Короне.', 'Нас ждет долгий и трудный поход к воротам Цитадели Ледяной Короны. Благодарю тебя от имени всех рыцарей Серебряного Авангарда – за все, что ты для нас сделал. Теперь мы можем спать спокойно, зная, что ты будешь сражаться бок о бок с нами в этом проклятом месте.$B$B<Верховный лорд Тирион Фордринг отдает вам честь.:', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13158, 'Главное – скрытность', 'Послушай меня, $r.$B$BЯ только что узнал, что в Аметистовой крепости произошел один инцидент. Оказывается, синие драконы планируют масштабную атаку на Даларан!$B$BМне нужно, чтобы ты немедленно $gотправился:отправилась: в тюрьму и $gпоговорил:поговорила: с тюремщиком Альтурасом. Он посвятит тебя в детали.$B$BЭто еще не все. Я хочу, чтобы ты $gдействовал:действовала: очень осторожно. Незачем попусту тревожить жителей Даларана, особенно, если этой тревоги можно избежать. Я понятно выразился?$B$BОтлично. А теперь ступай!', 'Отправляйтесь в Аметистовую крепость в Даларане и поговорите с тюремщиком Альтурасом по поручению Ронина.', 'Как раз вовремя.$B$BТы готов встать на защиту Даларана, $С?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13159, 'Сдерживание', 'Вот ключ от тюрьмы.$B$BМы станем здесь в качестве последней линии обороны в том случае, если вы не сможете сдержать силы нападающих.$B$BТоропись, $r. Времени мало. Те несколько воинов, что я оставил внутри, не продержатся долго.$B$BОбязательно поговори с лейтенантом Синклари. Она даст вам доступ к системе защиты тюрьмы.$B$BЯ буду ждать твоего доклада о том, что силы нападающих были успешно истреблены.', 'Проникните по заданию тюремщика Альтураса в Аметистовую крепость и покончите с атакующими силами синих драконов. Вернитесь к нему с докладом, когда Синигоса будет повержена.', 'Так кризис преодолен?$B$BЭто и впрямь отличные новости. Я передам хорошие вести Ронину.$B$BПожалуйста, прими это в знак благодарности Даларана.', 'С нападением покончено? Смог ли ты противостоять им?', NULL, NULL, 'Синигоса убита', 'Ключ Аметистовой крепости', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13160, 'Сногсшибательное зрелище', 'Из горгулий получаются замечательные разведчики, к тому же они могут наносить смертоносные удары с воздуха. Но у них есть очевидные слабые стороны. Большинству горгулий приходится подолгу отдыхать, накапливая энергию для дальнейших полетов. В такие периоды они остаются неподвижными, как камень.$B$BЧерез око, которым ты пользуешься, я увидел на восточной и южной стенах десятки караульных ледошкуров. Ловец поможет тебе добраться до них, а ты уничтожишь их во сне.', 'По поручению Верета Хитрого с Высоты Страдания с помощью гибкого ловца поднимитесь к караульным ледошкурам и убейте 12 из них.', 'Пока ледошкуры спят, можно их не боятся.', NULL, NULL, NULL, 'Уничтожено караульных ледошкуров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13161, 'Всадник Нечестивости', 'Пришло время рубить ему головы, этому зверю.$B$BЯ довольно долго служил вместе с Рокиром. Он овладел нечестивыми искусствами лучше, чем подавляющее большинство остальных рыцарей смерти, которых я знал. И, подобно всем рыцарям смерти, он не знает жалости. Не $Nся, что он будет легким противником.$B$BКогда Рокир сражается на своей территории, его могущество возрастает. Увы, выбора у нас нет; однако постарайся остаться на ногах и не поддаться натиску нежити – тогда, быть может, тебе удастся победить. $B$BДействуй быстро и ловко, $C, и не забывай: Рокир хитер и жесток.', 'Убейте Рокира, всадника Нечестивости, по поручению Верета Хитрого с Высоты Страдания.', 'Без Рокира мир станет лучше, можешь мне поверить.', NULL, NULL, NULL, 'Рокир убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13162, 'Всадник Льда', 'Сапф... Сапф, она хоть и женщина, но среди рыцарей смерти ей нет равных. Она очарует тебя медоточивыми речами, и ты поклянешься чем угодно, что в ее сердце нет зла, а потом она просто пронзит тебя чем-нибудь острым, по-прежнему улыбаясь своей лучезарной улыбкой. Не дай ей себя обмануть.$B$BНе сомневаюсь, у тебя хватит сил одолеть Сапф; но помни – излишняя самоуверенность может тебя погубить. Сила Сапф в том, что она обманывает своих будущих жертв, притворяясь слабой, а затем обрушивает на них всю мощь ледяных атак. $B$BНе расслабляйся. Повторяю: стоит недооценить ее силы, и ты погибнешь.', 'Убейте Сапф, всадника Льда, по поручению Верета Хитрого с Высоты Страдания.', 'Честно признаюсь, мне будет слегка не хватать ее смеха... и этой улыбки, которой она улыбалась всегда перед тем, как кого-то убить. Зато теперь мне уже не придется все время оглядываться, ожидая удара в спину. Так что, наверное, грех жаловаться...', NULL, NULL, NULL, 'Сапф убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13163, 'Всадник Крови', 'Насколько мне известно, Бэлок – один из немногих врайкулов, которым удалось сделать карьеру. В основном, благодаря своей крайней жестокости, нежели сколько-нибудь выдающимся заслугам. Если он будет повержен, а еще лучше – мертв, то у тебя станет на одного противника меньше. А это, знаешь ли, не так плохо.$B$BКогда ты вступишь с ним в бой, старайся не приближаться к нему и держаться в стороне от своих спутников. Он воспользуется любой возможностью, чтобы лишить тебя жизненной силы: постарайся не допустить этого.$B$BЯ верю в тебя. Надеюсь, ты принесешь мне вести о его смерти.', 'Убейте Бэлока, всадника Крови, по поручению Верета Хитрого с Высоты Страдания.', 'Значит, его больше нет? Очень рад это слышать.', NULL, NULL, NULL, 'Бэлок убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13164, 'Судьба Кровопорча', 'Теперь, когда всадники воинства Страдания мертвы, пришло время разделаться с их предводителем – Орбазом Кровопорчем.$B$BПока тебя не было, нас нагнал Могрейн. Он нашел место, где прячется Орбаз. Под цитаделью Ледяной Короны располагается глубокая шахта – там ты и найдешь Орбаза, прямо у входа.$B$BНесколько лучших воинов Черного Клинка уже отправились к шахте, так что возьми кого-нибудь себе в помощь и присоединяйся к нашим. Пусть Кровопорч умрет!', 'Убейте Орбаза Кровопорча по поручению Верета с Высоты Страдания.', 'Стало быть, дело сделано? И Могрейн тоже был там? Как я понимаю, у него были какие-то свои счеты с Орбазом, так что не удивительно, что он тоже хотел поучаствовать в уничтожении старого врага.$B$BТы сослужил нам хорошую службу, $R, и получишь достойную награду. Прими благодарность рыцарей Черного Клинка.', NULL, NULL, NULL, 'Орбаз Кровопорч убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13165, 'Возвращение в Акерус', 'Туман развеялся. Теперь я четко вижу, что мы должны делать. Как и в тот день, когда я пронзил Испепелителем собственное сердце, чтобы освободить проклятую душу моего отца... тогда я тоже знал, на что иду.$B$BЕсли мы хотим, чтобы наш союз устоял перед грядущими переменами, мы должны отвоевать Акерус у Плети. Теперь ты знаешь, как открывать врата смерти – я сам учил тебя этому. Они перенесут тебя в Черный оплот, когда пожелаешь. Не медли, $N. Я буду ждать тебя в Акерусе. Грядет первая битва Рыцарей Черного Клинка, и Плеть будет уничтожена!', 'Воспользуйтесь заклинанием Врат смерти, чтобы вернуться в Акерус: Черный оплот, и найдите там верховного лорда Дариона Могрейна.', 'Король-лич вернулся в Нордскол, раненный Испепелителем, но остатки его армий все еще блокируют второй этаж крепости.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13166, 'Битва за Черный оплот', 'Мы отвоевали Зал Власти, но Король-лич оставил нам маленький подарок в самом Сердце Акеруса. Там, по второму этажу бродят толпы поганищ, возглавляемых этим гнусным чучелом, Лоскутиком.$B$BВоспользуйся телепортом и уничтожь оставшиеся войска Плети на втором этаже. Только не пытайся сразиться с Лоскутиком в одиночку! Одолеть его можно только объединившись с прочими рыцарями смерти Акеруса. $B$BИди же, $N, и пусть моя вера придаст тебе сил.', 'Убейте 10 солдат Плети и помогите одолеть Лоскутика, после чего вернитесь к верховному лорду Дариону Могрейну.', 'Отличная работа, рыцарь смерти. Скоро мы очистим Акерус от оставшихся существ Плети и начнем восстанавливать крепость.$B$BТебе осталось выполнить последнее мое поручение.', 'Акерус будет наш!', NULL, NULL, 'Лоскутик убито', 'Убито воинов Плети', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13167, 'Смерть королю-предателю!', 'Ануб\'арак, король-предатель, обитает в некогда славном подземном королевстве Азжол-Неруб.$B$BСовершив свое предательство, он превратил нашу родину в тот жалкий край, по которому мы сейчас ступаем. Он правит армией нерубов-нежити, которые, как и их лидер, поклялись в верности Королю-личу.$B$BПокончи с правлением короля-предателя, $C. Ты окажешь величайшую услугу обоим нашим народам.$B$BЕсли ты добьешься успеха там, где все прочие потерпели поражение, принеси мне панцирь Ануб\'арака.', 'Одержите победу над Ануб\'араком из Азжол-Неруба и принесите Киликсу Разрушителю в Провал Наржуна разбитый панцирь Ануб\'арака.', '<Глаза Киликса начинают светиться, когда он смотрит на панцирь.>$B$BС ним ПОКОНЧЕНО!$B$Bэльф крови! Твое имя будет высечено на страницах истории нашего народа.$B$BЯ пред тобой в долгу…', 'С ним покончено, $C? Король-предатель встретил свой неизбежный конец?', NULL, NULL, 'Разбитый панцирь Ануб\'арака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13168, 'Простой урок', 'Смотри-ка... Это глаза власти. Служители Культа делают все, чтобы сохранить эти предметы. Но думаю, у них будет мало шансов, когда мы нападем на них прямо у них дома.$B$BГлаза власти позволяют управлять нежитью. Как ты понимаешь, было бы здорово получить контроль над всеми этими неуклюжими вурдалаками и скелетами.$B$BХочешь попробовать? Используй глаз власти, чтобы управлять пойманным духом.', 'По заданию Керитоза Кровавого Клинка из Мрачного Свода возьмите под свой контроль пойманного эйдолонского наблюдателя, используя глаз власти.', 'Ничего сложного, правда? Любое разумное существо может научиться управлять мелкой нежитью. А вот с более сильными существами справится только настоящий некромант. Но это не беда: я уже придумал массу способов навредить врагу даже с помощью слабой нежити.$B$BПриступим?', 'Преимущества, которые дают нам глаза власти, очевидны. Полезная вещь.', NULL, NULL, 'Возьмите под свой контроль эйдолонского наблюдателя.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13169, 'Лучший друг нежити', 'Нежить, заправляющая добычей саронита на юго-западе отсюда, морит голодом местных чумных псов, чтобы они были еще злее. Подкрадись к ним, используя маскировку, и покорми нескольких псов. Я уверен, что они либо тут же оставят тебя в покое, либо вовсе решат присоединиться к тому, кто дал им еду.$B$BТолько пока не накормишь их, близко не подходи: твоя маскировка не обманет их чутье.', 'По просьбе Керитоза Кровавого Клинка из Мрачного Свода накормите с помощью эйдолонского наблюдателя 18 проголодавшихся чумных псов.', 'Сморило их, да?', NULL, NULL, NULL, 'Накормлено проголодавшихся чумных псов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13170, 'Честь – удел слабых', 'Вурдалаки, вообще-то, достаточно хрупкие и нежные существа, и дозорные на юго-западных разработках саронита – не исключение. Использовав одну из теней, ты без труда сможешь пробраться туда и бесшумно убрать дозорных одного за другим.$B$BПрикончи как можно больше дозорных. Время у тебя будет, но не много... нужно, чтобы к нашей атаке их ряды поредели как следует.', 'Убейте 20 неутомимых дозорных по поручению Керитоза Кровавого Клинка из Мрачного Свода.', 'Чистая работа!', NULL, NULL, NULL, 'Неутомимые дозорные убиты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13171, 'Откуда придет удар', 'Больше всего меня беспокоит саронитовый карьер на юго-западе отсюда. Там добывают такое невероятное количество руды, что я не представляю даже, что они собираются из нее делать. Но узнать это не так просто. Начнем с того, что ослабим их оборону.$B$BЯ заметил, что по всей базе разбросаны какие-то кристаллы. Думаю, они как раз служат для охраны. Ну, примерно, как зиккураты. Найди несколько таких кристаллов и уничтожь их с помощью эйдолонского наблюдателя.', 'По заданию Керитоза Кровавого Клинка из Мрачного Свода уничтожьте 10 сдерживающих кристаллов Плети.', 'Отлично! Теперь нам почти нечего бояться.', NULL, NULL, NULL, 'Уничтожено кристаллов Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13172, 'Семена Хаоса', 'Полезная вещь, не правда ли? Тебе отлично удалось ослабить их оборону, $C. Теперь мы можем отправить в наступление основные силы.$B$BПлан прост: мы уничтожаем все, что движется, прорываемся вовнутрь и, пользуясь всеобщим замешательством, похищаем нужную информацию.$B$BСкажешь, когда будешь $gготов:готова:. Я дам тебе грифона-скелета.', 'По указанию Керитоза Кровавого Клинка из Мрачного Свода уничтожьте 80 солдат нежити в Саронитовом карьере. Попросите у него грифона-скелета.', 'Да там защита – одно название. Проще не бывает.', 'Ну что, понравилось?', NULL, NULL, 'Уничтожено нежити в Саронитовом карьере', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13173, 'Под шумок', 'Нам удалось прибрать к рукам довольно много рабочих.Они отлично подойдут.$B$BЯ прошу тебя использовать глаз, чтобы привести одного из этих рабочих обратно в карьер. Сейчас, когда в лагере суматоха и неразбериха, они ни за что не отличат тебя от любого другого рабочего из тех, что разбежались во время нападения.$B$BНайди главного и приступай к работе. Если повезет, мы быстро выясним, куда они отправляют саронит. Я буду наблюдать за тобой через глаз.', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13174, 'Под шумок', 'Помешать осуществлению их проектов – это лишь часть нашего плана. Еще одна важная задача: выяснить, куда они отправляют столько саронита. Мы уже знаем несколько пунктов назначения, но его добывают в таких количествах, что вывод напрашивается сам собой: где-то ведутся работы над каким-то масштабным проектом.$B$BОтправляйся в карьер и попробуй добыть хоть какие-то сведения. Принеси мне все бумаги, какие найдешь. Если полетишь туда на грифоне, то можешь спешиться, как только покончишь с грязной работой.', 'Принесите документ из Саронитового карьера, гроссбух Саронитового карьера, карту Саронитового карьера и расписание работ в Саронитовом карьере Керитозу Кровавому Клинку в Мрачный Свод.', 'Так, посмотрим... посмотрим...$B$B<Керитоз внимательно изучает бумаги. Похоже, там нет ничего такого, чего он не знал раньше. И вдруг он находит то, что искал...>$B$BМаликрисс! Зловещая Крепость! Похоже, Артас никак не оправится после потери своих рыцарей смерти... Не знаю, что он там делает с таким количеством саронита, но у меня сложилось впечатление, что он как будто пытается отыграться и с лихвой компенсировать свои потери.$B$BПарень не привык проигрывать.', 'Ты принес, что я просил?', NULL, NULL, 'Документ из Саронитового карьера', 'Гроссбух Саронитового карьера', 'Карта Саронитового карьера', 'Расписание работ в Саронитовом карьере');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13175, 'Восстановление контроля', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
