INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13177, 'Беспощадным пощады не будет', 'Добро пожаловать в крепость Ледяных Оков, $N. Твое задание будет очень простым. Одержи победу над десятью представителями Орды. А теперь ступай! Принеси победу Альянсу!', 'Убейте 10 игроков Орды по приказу командира Заннета из крепости Ледяных Оков.', 'Великолепно! Истинно говорю я, ты – один из величайших воинов Альянса!', NULL, NULL, NULL, 'Убито игроков Орды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13178, 'Убить всех и каждого!', 'Добро пожаловать в крепость Ледяных Оков, $N. Вождь Гаррош требует лишь одного: убить их всех!$B$BВозвращайся ко мне, когда десять самых сильных воинов Альянса будут мертвы.', 'Убейте 10 игроков Альянса по приказу командира Дардоша с Озера Ледяных Оков.', 'Лок\'тар! Победа будет за Ордой!', NULL, NULL, NULL, 'Убито игроков Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13179, 'Беспощадным пощады не будет', 'Добро пожаловать в крепость Ледяных Оков, $N. Твое задание будет очень простым. Одержи победу над десятью представителями Орды. А теперь ступай! Принеси победу Альянсу!', 'Убейте 10 игроков Орды по приказу командира Заннета с Озера Ледяных Оков.', 'Великолепно! Ты – один из величайших воинов Альянса!', NULL, NULL, NULL, 'Убито игроков Орды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13180, 'Убить всех и каждого!', 'Добро пожаловать в крепость Ледяных Оков, $N. Вождь Гаррош требует лишь одного: убить их всех!$B$BВозвращайся ко мне, когда десять самых сильных воинов Альянса будут мертвы.', 'Убейте 10 игроков Альянса по приказу командира Дардоша с Озера Ледяных Оков.', 'Лок\'тар! Орду ждет победа!', NULL, NULL, NULL, 'Убито игроков Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13181, 'Победа на Озере Ледяных Оков', 'Командир Заннет, должно быть, очень доволен видом груды ордынских тел у его ног, но контроль над Озером Ледяных Оков – приоритетная задача экспедиции Отважных. Сделай все возможное, чтобы эта территория оставалась нашей.$B$BНе думай, что союзники сделают за тебя всю грязную работу. Если к концу битвы не станешь рекрутом хотя бы второго уровня, можешь не возвращаться.', 'Выиграйте битву на Озере Ледяных Оков и вернитесь к офицеру-стратегу Абрамису. Необходимо принять участие в битве, чтобы выиграть ее.', 'Это то, что я так надеялся услышать! Каждая победа на Озере Ледяных Оков крайне важна для нас. Орда будет разгромлена!', NULL, NULL, NULL, 'Победа на Озере Ледяных Оков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13182, 'И не забудь про яйца!', 'По всему Азжол-Нерубу порабощенные Плетью нерубы заботятся о яйцах, из которых вскоре должно появиться на свет их потомство, пополнив их и без того огро$Nю армию.$B$BСкверно получится, если мы уничтожим наводнившую пещеры нежить, а эти скверные яйца останутся дозревать. Тогда новые орды займут место павших.$B$BЕсли ты направишься в ту область, что когда-то была известна как Азжол-Неруб, обязательно избавь наш древний дом ото всех яиц Плети, что встретятся тебе на пути.', 'Проникните в Азжол-Неруб по просьбе Киликса Разрушителя из Провала Наржуна и уничтожьте 6 нерубских яиц Плети.', 'Меня глубоко печалит нынешнее положение вещей. Если бы только мы могли восстановить былое величие нашей империи…', 'Удалось ли тебе избавить наш дом от порченных Плетью яиц?', NULL, NULL, 'Уничтожено нерубских яиц Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13183, 'Победа на Озере Ледяных Оков', 'Хотя Дардош весьма успешно справляется с уничтожением наших врагов, более важным для нас является контроль над крепостью Ледяных Оков. Сделай все, что потребуется, чтобы она принадлежала нам. Не думай, что союзники сделают за тебя всю грязную работу. Если к концу битвы не станешь рекрутом хотя бы второго уровня, можешь не возвращаться.', 'Выиграйте битву на поле боя Озера Ледяных Оков и вернитесь к офицеру-стратегу Килрату в крепость Ледяных Оков. Необходимо принять участие в битве, чтобы выиграть ее.', 'Сегодня ты свершил великое дело. Мы признательны тебе за самоотверженность!', NULL, NULL, NULL, 'Победа на Озере Ледяных Оков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13184, 'Больше нет нужды', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13185, 'Остановка осады', 'Я слышать их! Альянс скоро прийти. Уничтожь три осадных машины Альянса и возвращайся к Мурпу.', 'Уничтожьте 3 осадных машины Альянса по приказу лейтенанта Мурпа из крепости Ледяных Оков.', 'Хорошая работа. Жаль, Мурпа рядом с тобой не было, он бы помог.', NULL, NULL, NULL, 'Разрушено осадных машин Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13186, 'Остановка осады', 'Рано или поздно крепость будет осаждена силами Орды. Уничтожь три их осадных машины и возвращайся ко мне.', 'Уничтожьте по приказу главного подрывника Легосо из крепости Ледяных Оков 3 осадных машины Орды.', 'Отлично. Это должно существенно ослабить их атаку.', NULL, NULL, NULL, 'Разрушено осадных машин Орды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13187, 'Безликие', 'Пытаясь избежать столкновения с силами нежити, мой народ копал все глубже и глубже, во всех смыслах теряя почву под ногами. В своем отчаянии они закопались слишком глубоко.$B$BМы случайно обнаружили щупальца воли Древнего Бога, воплощенной в созданиях, известных под названием безликих.$B$BВ конечном счете, мы не смогли драться на два фронта против столь могущественных врагов. Наша печальная судьба стоила нам проигранной войны против нежити и, в конце концов, нашего дома.$B$BВступи в Ан\'кахет, $C, и очисти наш бывший дом от этих ужасных безликих.', 'Убейте глашатая Волажа из Ан\'кахета и трех позабытых, по просьбе Киликса Разрушителя из Провала Наржуна.', 'Ты хорошо справился, $C.$B$BДа заставят твои дела вновь зажечься огнем надежды глаза нашего народа – надежды на то, что когда-нибудь мы сможем вновь вернуть себе город наших предков.', 'Удалось ли тебе победить безликих, $C?', NULL, NULL, 'Уничтожено Позабытых', 'Глашатай Волаж сражен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13188, 'Шаги короля', 'Ты, $N, отныне и навсегда нарекаешься рыцарем Черного Клинка. Но не забывай о том, что когда-то ты $gсражался:сражалась: за Альянс.$B$BЕсли мы хотим победить, нам необходимо обрести союзников. Я назначаю тебя представителем рыцарей Черного Клинка в Альянсе. $B$BНа платформе к юго-востоку отсюда есть портал, который ведет напрямую в Штормград. Возьми с собой это письмо, написанное самим лордом Фордрингом, и отдай его самому королю Вариану Ринну. Иди же!', 'Отнесите письмо в Штормград и отдайте королю Вариану Ринну.', '<Вариан задумчиво смотрит вдаль.>$B$BВоистину, это весточка от старого друга... Кровь и честь!$B$B<Вариан вновь смотрит прямо на вас.>$B$BЕсли бы не это письмо – лежать бы тебе с перерезанным горлом. Благодари за свое спасение одного из величайших паладинов нашего времени!$B$BМы... мы будем сражаться вместе с твоим орденом против Плети. Против Короля-лича.$B$BИ ВО СЛАВУ АЛЬЯНСА!', 'Говори, ибо сейчас ты умрешь.', NULL, NULL, 'Королю Вариану Ринну, предводителю Альянса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13189, 'Благословение вождя', 'Ты, $N, отныне и навсегда нарекаешься рыцарем Черного Клинка. Но не забывай о том, что когда-то ты $gсражался:сражалась: за Орду.$B$BЕсли мы хотим победить, нам необходимо обрести союзников. Я назначаю тебя представителем рыцарей Черного Клинка в Орде. $B$BНа платформе к юго-востоку отсюда есть портал, который ведет напрямую в Оргриммар. Возьми с собой это письмо, написанное самим лордом Фордрингом, и отдай его самому Траллу. Иди же!', 'Отнесите письмо в Оргриммар и отдайте Траллу, вождю Орды.', 'Эйтригг обязан жизнью этому паладину. Его должны были казнить в Стратхольме, когда лорд Фордринг пришел к нему на помощь.$B$BТирион Фордринг отдал все, чтобы спасти жизнь орка... лишь однажды я встречал человека, способного на такое самопожертвование.$B$B<Тралл с трудом сдерживает слезы.:Я всегда буду помнить о тебе, Тарета...$B$BА что касается тебя... Да. Я сделаю это во имя Тириона Фордринга и Эйтригга. Орда станет союзником вашему ордену.$B$BМы служим кровью и честью во имя Орды!', 'Интересный поворот событий!', NULL, NULL, 'Траллу, вождю Орды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13190, 'Все хорошо в свое время', 'Ан\'кахет, откуда мы пришли…$B$BОднажды, я верю, мы победим смерть и тьму, что окутали нашу древнюю родину. Чтобы это свершилось, у меня есть план, как ослабить защиту наших врагов.$B$BИх драгоценнейшие наблюдатели должны быть сожжены!$B$BСобери их трупы и сложи на жаровню в глубине этого города. Запах их горящих останков наполнит воздух, напоминая наших врагам об их слабости.$B$BНе забывай, $C! У них тела нежити – они весьма недолговечны и разрушаются очень быстро.', 'Заполучите труп наблюдателя Ан\'кахара по поручению Киликса Разрушителя из Провала Наржуна и поместите его на ан\'кахетскую жаровню в Ан\'кахете.Это задание может быть выполнено только на героическом уровне сложности.', 'Ахаха!$B$BДа опустошит их души горький дым поражения!$B$BСпасибо тебе, $С. Сегодня ты нанес внушительный удар этой нежити.', NULL, NULL, NULL, 'Тело ан\'кахарского наблюдателя сожжено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13191, 'Горючее для разрушителей', 'Лок\'тар, $N! Пусть, может быть, битва затихла, но мы должны быть готовы к следующей атаке Альянса! Отправляйся в Огненную котловину, что в юго-восточной части Ледяных Оков, и добудь десять неугасимых угольков.$B$BЭти угольки, смешанные с обычным углем, служат отличным топливом для разрушителей и осадных машин. $B$BСудя по донесениям, эти свиньи из Альянса собирают вечные угольки целые дни напролет. Убей их и забери у них все! Если они уже покинули это место, будь $gготов:готова: драться с огненными элементалями, пока не соберешь сколько нужно!', 'Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков.', 'Отлично! Это поможет нам победить Альянс в грядущих битвах!', 'Ну как? Получилось ли у тебя найти угли, или Альянс побил тебя, и ты убежал весь в слезах?', NULL, NULL, 'Неугасимый уголек', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13192, 'Охрана стен', 'Привет, $gбратишка:сестренка:. Это место может любого ввергнуть в глубокую депрессию, меня так уж точно, а тебя?$B$BСлишком уж здесь обитает много духов. Я бы хотел поставить тут колдовских стражей худу, но мне нужно несколько душ, $gбратишка:сестренка:. И не просто душ, а душ сильных воинов.$B$BУ Ледопадов в восточной части Озера Ледяных Оков есть все подходящие условия для извлечения душ. Убивай там представителей Альянса – может быть, у них окажется то, что нам нужно.$B$BПринеси мне куски доспехов убитых врагов. Если там не окажется Альянса, может быть, они найдутся у элементалей, $gбратишка:сестренка:.', 'Отправляйтесь к Ледопадам и заполучи 10 зачарованных доспехов Альянса по просьбе мастера худу Фу\'джина из крепости Ледяных Оков.', 'О-о, это то, что надо, братишка!', 'Добыл доспехи, братишка?', NULL, NULL, 'Зачарованный доспех Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13193, 'Кости и стрелы', 'И почему они отправили меня снаряжать наших лучников? Я был поэтом, а не рейнджером! Ну, что толку жаловаться. $N, мне требуется кость дракона для изготовления наконечников для стрел.$B$BОтправляйся в лес Теней, что в западной части Озера Ледяных Оков. Со времени последней заварушки Альянс собирает там кости драконов. Убей их и отбери у них кости.$B$BЕсли не получится найти там Альянс, может быть, тебе повезет, и ты добудешь кости у обитающих там духов. Я слышал, они любят насаживать на такие кости своих еще живых жертв.', 'Раздобудьте 10 колчанов со стрелами из драконьих костей у игроков Альянса в лесу Теней по просьбе лейтенанта Виерона Огненного Пера из крепости Ледяных Оков.', 'Похоже, мне предстоит еще одна ночка заточки костей для наконечников. И чего мне не сиделось в Луносвете, как моему брату?', 'Я не ждал тебя так рано. Ох, а я-то надеялся хоть немного отдохнуть.', NULL, NULL, 'Колчан со стрелами из драконьих костей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13194, 'Целительные розы', 'В затишье меж битвами могучий духом может поверить в том, что есть еще надежда на мир на этой земле. Увы, наша судьба не такова.$B$BОтправляйся в степь Жизни, в юго-западную часть Озера Ледяных Оков. Мне нужны растущие там розы для изготовления бальзама, исцеляющего раненых.$B$BК сожалению, роз стало маловато, потому что Альянс собирает их слишком быстро. Убей бойцов Альянса в степи Жизни и собери сумки с травами с их тел.$B$BЕсли же это тебе не удастся, может быть, сможешь найти несколько цветущих корнехлестов.', 'Отнимите 10 сумок с травами у игроков Альянса в степи Жизни по просьбе идолопоклонника Мулфорта.', 'Спасибо тебе, это поможет нам быстрее залечить раны наших солдат.', 'Удалось ли тебе отыскать травы? Число больных и раненых растет с каждым часом.', NULL, NULL, 'Сумка Альянса с травами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13195, 'Редкое растение', 'Ух, ну и холодно же здесь! Напоминает мне штормовые вершины Каариноса на Аргусе. Меж тем, со всем этим снегом и льдом наши солдаты могут легко подхватить простуду.$B$BОтправляйся в степь Жизни, что в юго-западной части Ледяных Оков, и принеси мне 10 сумок Орды с травами. Я измельчу их и сделаю лекарство, которое поможет защититься от простуды.$B$BОрда тоже занимается сбором трав в этих краях. Не робей, убивай врагов и забирай то, что они успели насобирать!$B$BТакже нужные травы можно найти у обитающих там плеточников.', 'Принесите анахорету Тессе 10 сумок Орды с травами из степей Жизни.', 'Отлично! Это поможет защитить наших бойцов от простуды.', 'Я надеюсь, ты случайно не тронул ни одного корнехлеста? Ох, ну и досталось от них рядовому Доану на прошлой неделе!', NULL, NULL, 'Сумка Орды с травами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13196, 'Кости и стрелы', 'Эти драконы просто поразительны! Ну, по крайней мере, их кости! Я снабжал наших лучников наконечниками стрел из драконьей кости. К сожалению, после резни в Ангратаре собирать кости на Драконьем Погосте стало практически невозможно.$B$BНо в лесу Теней, что на западном краю Ледяных Оков, достаточно костей, чтобы пополнить наши запасы.$B$BНаправляйся в лес Теней и принеси любые осколки костей, какие только сможешь найти!$B$BОрда тоже собирает осколки в этом районе. Убей их всех!', 'По просьбе лучника Рандольфа из крепости Ледяных Оков отыщите 10 колчанов со стрелами из драконьих костей у игроков Орды в лесу Теней.', 'Отлично! Этими дровишками мы подкормим костер войны на несколько дней вперед.', 'Как прошла охота на кости? До меня доходили слухи, что место это облюбовали духи, но у меня никак ноги не доходят сходить посмотреть на них самому.', NULL, NULL, 'Колчан со стрелами из драконьих костей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13197, 'Горючее для разрушителей', '$N! Ты как раз вовремя! Может быть, мы и проиграли последнюю битву, но нам уже надо готовиться к следующей! Отправляйся к Огненной котловине в юго-восточной части Озера Ледяных Оков и добудь мне несколько неугасимых угольков.$B$BЭти угольки, смешанные с обычным углем, служат отличным топливом для разрушителей и осадных машин. $B$BО, и если ты вдруг увидишь Орду в Котле, не стесняйся, убивай и забирай у них угольки. Мы должны сделать все возможное, чтобы они не удержали крепость!', 'Осадный кузнец Крепкохват из Крепости Ледяных Оков попросил вас собрать 10 неугасимых угольков с тел воинов Орды в Огненной котловине.', 'Отлично! Этими дровишками мы подкормим костер войны на несколько дней вперед.', 'Ну как? Получилось ли у тебя найти угли, или Орда побила тебя, и ты сбежал весь в слезах?', NULL, NULL, 'Неугасимый уголек', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13198, 'Охрана для воинов', '$N, рад тебя видеть. Мы должны подготовиться к следующей атаке на крепость. Проведенные мной исследования показывают, что доспехи солдат, недавно убитых у Ледопадов, накапливают невероятное количество энергии. Орда тоже собирает доспехи в этой области.$B$BОтправляйся к Ледопадам и уничтожь всех ордынцев, каких только обнаружишь. Принеси мне их укрепленные доспехи.$B$BЕсли ты не встретишь там никого из Орды, может, наткнешься на доспехи какого-нибудь искателя приключений, сраженного элементалями.', 'Принесите 10 комплектов прочных доспехов из Ледопадов по приказу колдуньи Кайланы из крепости Ледяных Оков.', '', NULL, NULL, NULL, 'Прочный доспех Орды', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13199, 'Кости и стрелы', 'И почему они отправили меня снаряжать наших лучников? Я был поэтом, а не рейнджером! Ну, что толку жаловаться. $N, мне требуется кость дракона для изготовления наконечников для стрел.$B$BОтправляйся в лес Теней, что в западной части Озера Ледяных Оков. Со времени последней заварушки Альянс собирает там кости драконов. Убей их и отбери у них кости.$B$BЕсли не получится найти там Альянс, может быть, тебе повезет, и ты добудешь кости у обитающих там духов. Я слышал, они любят насаживать на такие кости своих еще живых жертв.', 'Раздобудьте 10 колчанов со стрелами из драконьих костей у игроков Альянса в лесу Теней по просьбе лейтенанта Виерона Огненного Пера из крепости Ледяных Оков.', '', NULL, NULL, NULL, 'Колчан со стрелами из драконьих костей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13200, 'Горючее для разрушителей', 'Лок\'тар, $N! Пусть битва на сей раз и закончена, но мы должны приготовиться к возврату крепости! Отправляйся к Огненной котловине, что в юго-восточной части Озера Ледяных Оков, и добудь десять неугасимых угольков.$B$BЭти угольки, смешанные с обычным углем, служат отличным топливом для разрушителей и осадных машин. $B$BСудя по донесениям, эти свиньи из Альянса собирают угольки целые дни напролет. Убей их и забери у них все! Если они уже покинули это место, будь $gготов:готова: драться с огненными элементалями, пока не найдешь сколько нужно!', 'Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков.', 'Отлично! Это пробьет брешь в броне их военной машины!', 'Ну как? Удалось ли тебе найти угли? Или Альянс побил тебя, и ты убежала вся в слезах?', NULL, NULL, 'Неугасимый уголек', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13201, 'Целительные розы', 'В затишье меж битвами могучий духом может поверить в том, что есть еще надежда на мир на этой земле. Увы, наша судьба не такова.$B$BОтправляйся в степь Жизни, в юго-западную часть Озера Ледяных Оков. Мне нужны растущие там розы для изготовления бальзама, исцеляющего раненых.$B$BК сожалению, роз стало маловато, потому что Альянс собирает их слишком быстро. Убей бойцов Альянса в степи Жизни и забери сумки с травами с их тел.$B$BЕсли же это тебе не удастся, может быть, сможешь найти несколько цветущих корнехлестов.', 'Отыщите 10 сумок Альянса с травами в степи Жизни по просьбе идолопоклонника Мулфорта.', 'Спасибо тебе, это поможет нам быстрее залечить раны наших солдат.', 'Удалось ли тебе отыскать травы? Число больных и раненых растет с каждым часом.', NULL, NULL, 'Сумка Альянса с травами', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13202, 'Заколдованные стены', 'Привет, $gбратишка:сестренка:. Смотри-ка, проклятый Альянс разместился в своей крепости с комфортом, а?$B$BМне кажется, уж слишком им там комфортно, как считаешь? Я хочу немного околдовать это место, но для этого мне нужны души, $gбратишка:сестренка:. И не просто обычные души, а души храбрых воинов.$B$BУ Ледопадов в восточной части Озера Ледяных Оков есть все подходящие условия для извлечения душ. Убивай там бойцов Альянса – может быть, у них окажется то, что нам нужно.$B$BПринеси мне доспехи убитых врагов. Если там не окажется Альянса, может быть, доспехи найдутся у элементалей, $gбратишка:сестренка:.', 'Принесите 10 комплектов зачарованных доспехов Альянса из Ледопадов по просьбе мастера худу Фу\'джина из крепости Ледяных Оков', 'О-о, это то, что надо, братишка!', 'Добыл доспехи, братишка?', NULL, NULL, 'Зачарованный доспех Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13203, 'Подарок к Зимнему Покрову', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13204, 'Странные грибочки', 'Бесформенный кусок похожей на гриб плесени отваливается от особенно вонючего, покрытого слизью куска плоти пещерного зверя. Пока вы осматриваете отвалившийся кусок, вас просто передергивает от этого невыносимого смрада.$B$BВы удивляетесь про себя – неужели эту штуковину нерубы находят аппетитной? Положив липкую субстанцию к себе в сумку, вы собираетесь это выяснить...', 'Соберите 6 кусков диковинной плесени с диких пещерных зверей в Ан\'кахете и принесите их Киликсу Разрушителю в Провал Наржуна.', 'Ты хоть понимаешь, что ты мне притащил, $C?$B$BПещерные звери, на которых ты охотился, используют несколько нетрадиционный способ выведения отходов из организма. Ты, наверное, теперь захочешь пойти помыть руки…$B$BСпасибо тебе, конечно, но если ты снова наткнешься на ЭТО – оставь, пожалуйста, себе.', 'Что это, во имя создания?!', NULL, NULL, 'Чудовищный гриб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13205, 'Разоружение', 'Поверь мне на слово, $gдружище:подруга:: с врайкульскими топорами лучше близко не знакомиться!$B$BУ меня самого есть парочка шрамов от их клинков – отлично сбалансированных, чудовищно острых и совершенно смертоносных.$B$BДавай-ка, проникни в их крепость и стащи кое-что из врайкульского арсенала. Может быть, нам удастся разобраться, как они куют такое оружие. А может быть, и нет.$B$BВ любом случае – чем меньше у них топоров, тем лучше для нас.', 'Защитник Мордун поручил вам проникнуть в Крепость Утгард и украсть 5 образцов врайкульского оружия.', '<Мордун присвистывает.>$B$BТы только посмотри! Какая заточка!$B$BА я-то надеялся, что эти неандертальцы способны швыряться только камнями и палками-копалками.$B$BУвы, нам не повезло...', 'Ты никак тащишь мне охапку врайкульских топоров?', NULL, NULL, 'Оружие врайкулов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13206, 'Разоружение', 'Мы должны разобраться, как этим дикарям удается ковать столь острое оружие!$B$BЕсли бы ты только $gвидел:видела:, как легко они кромсают тела моих солдат своими топорами, ты бы тоже $gпришел:пришла: в ужас. $B$BОбыщи их крепость и принеси Ансельму любые образцы клинков, которые только сможешь найти.$B$BСмотри, не подведи меня, $C. Чем больше оружия ты сможешь принести – тем меньше окажется в руках у врайкулов на поле боя.', 'Темный следопыт Марра просит вас украсть в крепости Утгард 5 образцов врайкульского оружия и принести их верховному палачу Ансельму в Лагерь Возмездия.', 'Марра предупреждала нас о том, что врайкулы владеют невероятно мощным оружием. Теперь у нас появился шанс изучить его.$B$BВот тебе награда за труды, $C.', 'Ну, что у тебя там, $C?', NULL, NULL, 'Оружие врайкулов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13207, 'Чертоги Камня', 'Что ж, честно признаться, я удивлен, что в таком месте есть и другие искатели приключений! Так уж получается, что мне не помешала бы компания – в свете того, что ждет впереди.$B$BЕсли мои исследования этих чертогов верны, тут нас ожидают фундаментальные открытия!$B$BЕсли я, предположим, доверю тебе прикрывать себя, можешь присоединиться. Ну, что скажешь, $C? Интересное предложение?', 'Примите предложение Бранна Бронзоборода и сопровождайте его, пока он раскрывает тайны, хранящиеся в Чертогах Камня.', 'Как всегда – вопросов больше, чем ответов, да, мой мальчик?', 'Ну что, кажется, то, что мы вот так натолкнулись друг на друга, вовсе не плохо?', NULL, NULL, 'Исследование Бранна завершено', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13211, 'Сила очищающего огня', 'Плеть использует против нас наших же павших солдат, превращая их в вурдалаков и скелетов или расчленяя их тела и собирая из разных частей поганищ. Мы должны положить этому конец!$B$BНаши солдаты пали, защищая тех, кто остался в живых, и наш долг – избавить их после смерти от столь ужасной участи. К тому же, нам не хотелось бы, чтобы они служили подкреплением вражеским войскам на поле боя. Возьми этот факел с собой, когда пойдешь на Мясопилку, и сожги все трупы, которые найдешь в Святилище воскрешения или в лаборатории поганищ.', 'Рыцарь Олакин Сайнрит из Черного дозора просит сжечь 7 гноящихся трупов с помощью факела Олакина.', '<Рыцарь Олакин Сайнрит внимательно выслушивает вас.>$B$BКонечно, они заслуживали более достойного погребения, но это лучше, чем ничего. Нам всем теперь станет немного легче. Спасибо тебе, Пиронуар.', NULL, NULL, NULL, 'Сожжено гноящихся трупов', 'Факел Олакина', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13212, 'Части тела', 'Враги захватили рыцаря Олакина, и Серебряный Авангард лишился командующего как раз перед самой атакой на Мясопилку. Для меня-то все рыцари одинаковы, но сами они так не думают.$B$BМне не хотелось бы тратить на это время, но выбора у меня нет. Нашего благородного рыцаря, наверное, уже давно разрубили на мелкие кусочки, чтобы соорудить из них поганищ. Отправляйся в Мясопилку, перебей этих чудовищ, которые сражаются с нашими войсками, и верни части тела Олакина.', 'Принесите туловище Олакина, ноги Олакина, левую руку Олакина и правую руку Олакина темной всаднице Арли в Черный дозор.', 'Думаю, \"возвращение\" рыцаря – это хорошая новость, но, честно сказать, сомневаюсь, что его товарищи имели в виду именно это, когда говорили о том, что его надо вернуть. Ладно, посмотрим, что можно сделать, чтобы поставить его на ноги и завершить нашу миссию.', 'Ты принес мне… э… останки рыцаря Олакина?', NULL, NULL, 'Туловище Олакина', 'Ноги Олакина', 'Левая рука Олакина', 'Правая рука Олакина');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13213, 'Битва при Валхаласе', 'Я многое знаю, $N. С тех пор, как ты $gпобедил:победила: верховного тана Балагарда, произошло кое-что очень важное. Ты $gнужен:нужна: нам в битве за Валхалас!$B$BПоле боя находится на севере отсюда. А теперь иди вместе со своими друзьями к валь\'кире Джейрвиф. Тебе понадобится помощь друзей в сражениях с противниками, которых предложит валь\'кира.$B$BУдачи.', 'Поговорите с Джейрвиф из Валхаласа.', 'Ты одолела наших лучших бойцов. Ты заработала уважение, Ненамеренно.$B$BМожет, ты думаешь, что меня это хоть сколько-то волнует? Так нет же. Раз они все уступили тебе, значит, были плохими воинами и жалеть о них не стоит.$B$BНо у меня есть для тебе и твоих друзей другое развлечение! В Валхаласе еще много противников и мест для дуэлей.$B$BКогда будете готовы, сообщишь мне. Посмотрим, на что ты на самом деле годишься.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13214, 'Битва при Валхаласе: павшие герои', 'Есть у меня для тебя один противник, с которым ты точно не справишься.$B$BОчередной отряд самонадеянных чужеземцев попытался напасть на Валхалас. Спеси в них было много, но закончилось все, как обычно.$B$BЕсли ты считаешь себя $gдостойным:достойной: сражаться плечом к плечу с опытными бойцами, тогда прими и этот вызов.', 'Джейрвиф из Валхаласа передала вам вызов на битву, в которой вам предстоит за один раз одолеть всех шестерых павших героев: Элдрета, Генесса Полдуши, Джадраса, Масуда, Рита и Таллу.Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', 'Новая кровь…$B$B<Врайкульский рыцарь смерти плюет вам под ноги.>$B$BВсе вы считаете себя достойными воевать здесь.$B$BИ все вы ничто по сравнению с врайкулами и силой Плети!$B$BДа, тебе удалось одолеть шесть слабовольных трупов. Велика победа! В следующий раз тебе не устоять.', NULL, NULL, NULL, 'Павшие герои побеждены.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13215, 'Битва при Валхаласе: Кит\'рикс Темный Повелитель', 'Многие хотят доказать, что они достойны сражаться за Валхалас. Некоторые так даже из-под земли вылезают.$B$BВот, например, Кит\'рикс Темный Повелитель.$B$BКит\'рикс пришел из глубин, где правит бал безумие. И вот, он захотел встретиться в бою с кем-нибудь... необычным. Думаю, ты как раз подойдешь.$B$BНу что, ты осмелишься встретиться с нерубским кошмаром, $r?', 'Джейрвиф из Валхаласа передала вам вызов от Кит\'рикса Темного Повелителя.Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', 'Думаешь, меня можно впечатлить тем, что вы с друзьями целой толпой одолели одного-единственного нерубского жреца?$B$BУйди с глаз долой, а не то я сейчас на тебя вурдалаков напущу.', NULL, NULL, NULL, 'Кит\'рикс Темный Повелитель побежден.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13216, 'Битва при Валхаласе: возвращение Сигрид Дитя Льда', 'Твоя давняя соперница, Сигрид Дитя Льда, вернулась. Может, помнишь, как она уступила тебе в дуэли на Диком уступе?$B$BНеважно. Главное, что она это помнит. Она жаждет реванша.$B$BЛично я считаю, что это хорошая возможность еще раз себя показать.$B$BВ общем, решать тебе, $N. Хочешь снова встретиться с Сигрид?', 'Джейрвиф из Валхаласа передала вам вызов от Сигрид Дитя Льда.Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', 'Победа над одной из хильд меня лично не особо впечатляет, $R. К тому же, тебе помогали друзья.$B$BЭто вам еще повезло, что в драке не участвовал ее дракон.', NULL, NULL, NULL, 'Сигрид Дитя Льда побеждена.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13217, 'Битва при Валхаласе: Резчик-по-живому!', 'Пока что тебе везет, $N. Но следующее испытание ты едва ли выдержишь.$B$BПредупреждаю: лучше отступить сейчас. Резчик-по-живому – это настоящая гора гнилой плоти, порождение самых извращенных фантазий Короля-лича.$B$BНе представляю, как ты и твои друзья могут справиться с таким чудовищем. Но, как бы то ни было, решать тебе.', 'Джейрвиф из Валхаласа передала вам вызов от Резчика-по-живому.Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', 'Я начинаю уважать твое боевое мастерство, $N. Так что теперь ты мне еще меньше нравишься.$B$BЯ бы с гораздо большим удовольствием посмотрел, как эта гора мяса одной ногой раздавила бы тебя вместе с твоими друзьями!', NULL, NULL, NULL, 'Резчик-по-живому повержен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13218, 'Битва при Валхаласе: тан Смертельный Удар', 'Йотунхеймский врайкул заметил твои старания, $N. Сам тан Банахогг заинтересовался тобой и захотел стать твоим следующим противником.$B$BЕсли тебе показалось, что ты едва $gодолел:одолела: Резчика-по-живому, можешь отправляться домой и забудь о битве с таном. Прозвище тана – Смертельный Удар, и я думаю, ты догадываешься, за что он его получил.$B$BТы принимаешь вызов тана?', 'Джейрвиф из Валхаласа передала вам вызов от тана Банахогга Смертельного Удара.Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', 'Уж не знаю, что за прием ты применил, чтобы победить тана: мне отсюда не видно было. Но одно могу сказать точно: следующего противника тебе не одолеть.$B$BДа, я знаю, кто это будет. Беги, $R, беги. Спрячься как можно дальше и не высовывайся.$B$BИли же оставайся и прими смерть. Мне, в общем-то, все равно.', NULL, NULL, NULL, 'Тан Банахогг побежден.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13219, 'Битва при Валхаласе: последний бой', 'Боюсь, как бы твой успех не обернулся для тебя гибелью, $N.$B$B<Если бы валь\'кира не была белой, то она бы побледнела.>$B$BСлух о твоих успехах при Валхаласе дошел и до Цитадели Ледяной Короны, потревожив того, с кем тебе вряд ли захочется встречаться.$B$BСам принц Сандовал спешит сюда. Гьоннер считает, что тебе надо бежать. И я с ним согласна.$B$BТак что ты предпримешь? Он уже в пути. Ты $gготов:готова: сойтись с кровавым принцем в последнем бою?', 'Джейрвиф из Валхаласа передала вам вызов от принца Сандовала.Если вам удастся победить его, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа.', 'Мне больно слышать о поражении принца Сандовала. Да такая неумытая деревенщина, как ты, за счастье должна была счесть возможность отдать свою жизнь в бою с ним!$B$BЗабирай ты свою проклятую награду. Давай только поскорее.', NULL, NULL, NULL, 'Принц Сандовал повержен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13220, 'Воскрешение Олакина', 'У нас не слишком много времени на то, чтобы собрать Олакина. К счастью, Плеть приготовила отличное место, где ты сможешь провернуть эту операцию.$B$BРядом с Мясопилкой находится Святилище воскрешения. Поищи там катушку ниток и хирургический скальпель. Затем положи останки Олакина на большую плиту, находящуюся в центре святилища, и приступай к работе.', 'Найдите катушку ниток и хирургический скальпель, отнесите их в Святилище воскрешения к останкам Олакина и попытайтесь воскресить рыцаря. Затем вернитесь к темной всаднице Арли в Черный дозор.', 'Олакину крупно повезло. Никто еще не спасался из лап Плети, никто. В следующий раз ни отвага, ни крепкие нитки его не спасут. Надеюсь, он будет помнить об этом.', 'Ну что, тебе удалось собрать нашего храброго рыцаря?', NULL, NULL, 'Рыцарь Олакин Сайнрит воскрешен', 'Останки рыцаря Олакина', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13221, 'Я еще жив!', 'Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих \"работ\".$B$BВ одиночку мне не справиться, но с твоей помощью, дитя мое, я надеюсь спастись и повоевать еще с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?', 'Проводите отца Камароса в безопасное место, а затем доложите обо всем Абсалану Благочестивому на борту \"Усмирителя небес\".', 'Слава Свету! Мы уже думали, что отец Камарос умер, или того хуже. Твоя смелость и самоотверженность очень помогли Серебряному Авангарду. Прими нашу благодарность.', NULL, NULL, NULL, 'Доставить отца Камароса в безопасное место.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13222, 'Защита осадных машин', 'Внимание, $N! Мы начинаем атаку на крепость Ледяных Оков. Эти ордынские твари думают, что могут трусливо спрятаться за ее стенами? А вот я так не думаю! Мы покажем им силу гномской технологии и разберем эти стены по кусочкам!$B$BОднако даже самые могущественные осадные машины – ничто без тех, кто ведет их в бой. Защищай одну из осадных машин или управляй ею, пока она не уничтожит три ордынских строения.', 'По приказу главного подрывника Легосо из крепости Ледяных Оков защитите осадную машину или управляйте ею, пока она не уничтожит три строения.Осадные машины могут изготавливать игроки в звании \"рядовой\" и выше в гоблинских мастерских.', 'Вот так-то, знайте теперь силу гномских изобретений!', NULL, NULL, NULL, 'Осадные машины защищены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13223, 'Защита осадных машин', 'Проклятый Альянс не сможет долго удерживать эту крепость. Мурп разломал бы все ее стены, но Мурпу приходится оставаться в лагере. Эх, если бы Мурп мог передавить весь Альянс, который хочет повредить ордынские разрушители.$B$BЭй, ты, $N! Ты пойдешь вместо Мурпа. Защити 3 осадных машины, пока они разрушают постройки Альянса. Альянс не ожидает, что ты будешь защищать разрушители. Покажи Альянсу, какой Мурп умный!', 'Защитите осадную машину или управляйте ею, пока она не уничтожит три строения Альянса по приказу лейтенанта Мурпа из крепости Ледяных Оков.Осадные машины могут изготавливать лишь имеющие воинские звания игроки Орды в гоблинских мастерских.', 'Отличная работа. Жаль, Мурпа рядом не было, он бы тебе помог.', NULL, NULL, NULL, 'Осадные машины Орды защищены', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13224, 'Молот Оргрима', 'Солдаты Серебряного Авангарда унесли мое истерзанное тело с поля боя на Прорванном фронте. Это была великая битва, $r. Мой топор пел, захлебываясь кровью подонков из рядов Альянса и Плети.$B$BДолго мне не протянуть, но это будет достойная смерть. Я попрошу тебя передать кое-что от меня.$B$BНаш летательный аппарат под названием \"Молот Оргрима\" может подняться так высоко, что силам Плети его не достать. Он где-то между Морд\'ретаром и Алдур\'таром.$B$B<Хорк тщетно пытается по-военному отдать честь.>$B$BЛети как можно выше и старайся избегать джаггернаута Альянса под названием \"Усмиритель небес\". Скажи Корму... скажи ему, что я умер... в бою... в бою за Орду.', 'Найдите покорителя небес Корма Черного Шрама. Он находится на борту \"Молота Оргрима\", летающего над Ледяной Короной.', '<Корм отдает честь.>$B$BБудь проклят Альянс и будь проклята Плеть! Хорк был одним из наших лучших бойцов! Мы отомстим за него. Во имя Адского Крика и всей Орды!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13225, 'Усмиритель небес', 'Мы завязли по уши, сражаясь с силами Плети и Орды. От воплей умирающих солдат звенело в ушах. Это была жестокая, беспощадная битва!$B$BВ какой-то момент тело отказалось меня слушаться. Я упал, и меня подобрали рыцари Серебряного Авангарда. Они вынесли меня с Прорванного фронта и доставили сюда. Едва ли я выживу. Ты исполнишь волю умирающего солдата, $r? \"Усмиритель небес\" летает высоко над Ледяной Короной. Там ты и найдешь нашего командира старшего капитана Бартлетта. Скажи ему, что я умер, сражаясь за Альянс.', 'Найдите старшего капитана Джастина Бартлетта. Он находится на борту \"Усмирителя небес\", патрулирующего Ледяную Корону.', '<Капитан Бартлетт отдает честь.>$B$BОн был чертовски бравым солдатом. Будь проклята Орда и будь проклята Плеть!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13226, 'И пришел Судный День!', 'Мы не можем одолеть короля-лича порознь. Если мы не объединимся, то поражения не миновать!$B$BУслышь мой призыв, $gбрат:сестра:! Серебряный Авангард примет любую помощь! Сам верховный лорд Тирион Фордринг ждет тебя на Серебряном аванпосте! Отправляйся в юго-восточную часть Ледяной Короны, там ты и найдешь лорда Фордринга и солдат Серебряного Авангарда.$B$BНе медли, $C, ибо Судный День настает!', 'Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.', 'Мои верные рыцари послужили мне на славу. Похоже, они нашли мне настоящего героя!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13227, 'И пришел Судный День!', 'Мы не можем одолеть короля-лича порознь. Если мы не объединимся, то поражения не миновать!$B$BУслышь мой призыв, $gбрат:сестра:! Серебряный Авангард примет любую помощь! Сам верховный лорд Тирион Фордринг ждет тебя на Серебряном аванпосте! Отправляйся в юго-восточную часть Ледяной Короны, там ты и найдешь лорда Фордринга и солдат Серебряного Авангарда.$B$BНе медли, $C, ибо Судный День настает!', 'Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.', 'Мои верные рыцари послужили мне на славу. Похоже, они нашли мне настоящего героя!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13228, 'Прорванный фронт', 'Бой? Какой еще бой?! Эти полки производили разведку!$B$BА что там было про Альянс? Ты вообще $gуверен:уверена:, что он что-то говорил об Альянсе?$B$BПослушай-ка, $N! Мне надо знать, что происходит, причем прямо СЕЙЧАС!$B$BИди и без ответов не возвращайся. Прочеши поля боя – найди выживших, найди следы, хоть что-то найди!', 'По заданию Корма Черного Шрама с \"Молота Оргрима\" отправляйтесь к Прорванному фронту и, поговорив с умирающим берсерком, узнайте, что там произошло.', 'Увидев, что солдаты Альянса атакуют ворота, они напали на них с тыла...$B$B<Корм ненадолго замолкает и неожиданно разражается смехом.>$B$BВот! Вот что такое Орда!$B$BЕсли бы не они, Альянс бы уже давно захватил ворота!$B$BОтвага бойцов Орды помогла нам выиграть драгоценное время.', 'Ну, что, Викториал?$B$BЕсть что-нибудь новенькое?', NULL, NULL, 'Вы побеседовали с умирающим берсерком', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13229, 'Я еще жив!', 'Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих \"работ\".$B$BВ одиночку мне не справиться, но с твоей помощью, $C, мне, может быть, я надеюсь спастись и повоевать еще с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?', 'Проводите отца Камароса в безопасное место, а затем доложите обо всем брату Кельтану на борту \"Молота Оргрима\".', 'Ты все сделал правильно. Мы боялись, что отец Камарос погиб. Твоя храбрость станет примером для всех, кто сражается с силами Плети.', NULL, NULL, NULL, 'Проводить отца Камароса в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13230, 'Отомсти за меня!', 'Я слышу их, $gбрат:сестра:...$B$BСтоны раненых воинов Альянса... как будто они насмехаются надо мной...$B$BЗакончи то, что мы начали, $C. Беспощадно, не зная жалости... никто не должен остаться в живых.$B$BРади... Орды...', 'Добейте 5 умирающих солдат у Прорванного фронта по просьбе умирающего берсерка. Об исполнении доложите покорителю небес Корму Черному Шраму на борту \"Молота Оргрима\".', 'Прошло то время, когда мы еще как-то терпели Альянс, Ондумм.$B$BОни сами сделали все, чтобы мы возненавидели их всей душой! Они будут жить в вечном страхе перед Ордой – до тех пор, пока не перестанут поганить наш мир!', NULL, NULL, NULL, 'Убито умирающих солдат Альянса', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13231, 'Прорванный фронт', 'Что?! Нееет! Только не это!$B$BМы же как только ни изощрялись, чтобы сохранить операцию в тайне! Как в Орде про нее узнали?! Ресурсы… живая сила… все пропало? Немыслимо!$B$BВсе наши планы здесь, в Ледяной Короне, основывались на том, что мы захватим ворота раньше Орды. Нужно срочно перегруппироваться и готовить новый штурм.$B$BОтправляйся на поле боя и разыщи уцелевших. Расспроси их, как все было. Возможно, эта трагедия нас кое-чему научит.$B$BИ приготовься к войне на два фронта, $N...', 'Отправляйтесь на Прорванный фронт и расспросите умирающего солдата, после чего возвращайтесь к старшему капитану Джастину Бартлетту на борт \"Усмирителя небес\".', 'Значит, разгром... полное поражение. Но мы этого не забудем.$B$BПомяни мое слово, $C. Орда заплатит за это… Пощады не будет!', NULL, NULL, NULL, 'Вы расспросили умирающего солдата', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13232, 'Прикончи меня!', 'Они смеются над нами... даже умирая, они смеются... $B$BПрошу тебя, $gбрат:милая:... Не допусти, чтобы их издевательский смех стал последним, что я слышу в жизни... $B$BПрикончи меня... избавь от мучений... отправь меня... к Свету.$B$BРазыщи моих умирающих товарищей... добей и их тоже... из милосердия.$B$BЧтобы никто из нас не достался Плети!$B$BПрошу тебя...', 'По просьбе умирающего солдата добейте 5 умирающих солдат у Прорванного фронта и доложите об исполнении старшему капитану Джастину Бартлетту на борту \"Усмирителя небес\".', 'Это была непростая работа, $C. Но ты все сделал правильно.$B$BИ пусть память об этом скорбном деянии не лежит тяжким грузом у тебя на сердце. Обуздай скорбь и боль, преврати их в горящую ярость и направь ее против тех, кто причинил и тебе, и нам всем эту боль.$B$BОрда заплатит за все!', NULL, NULL, NULL, 'Убито умирающих солдат', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13233, 'Пощады не будет!', 'Я говорил серьезно, это не было приступом гнева.$B$BСнова и снова Орда выказывает свое пренебрежение ко всему, что для нас дорого и свято. За преступления против Света они должны заплатить своей жизнью!$B$BВсе они.$B$BТолько представь, насколько светлее станет мир без этих мерзавцев, $N. Насколько легче будет жить нашим потомкам и как глубоко они будут чтить нашу память, зная, что именно нам они обязаны своим спокойствием и счастьем.$B$BА теперь иди, и пусть мечты станут реальностью!', 'По заданию старшего капитана Джастина Бартлетта с борта \"Усмирителя Небес\" убейте 15 игроков, сражающихся на стороне Орды в Ледяной Короне.', 'Отличная работа, $N.$B$BУвидишь врага – догони его и расплатись с ним за все!', NULL, NULL, NULL, 'Убито игроков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13234, 'Они заплатят!', 'Время пришло!$B$BМы слишком долго терпели этих самодовольных болванов из Альянса! Слишком долго мы сдерживали свое желание очистить мир от отчаявшихся и слабых.$B$BИ теперь мы положим конец нашему унижению! Мы им покажем, что значит страх! Мы принесем честь и славу Орде!$B$BЗдесь, в Ледяной Короне, мы разобьем Альянс!$B$BСтупай, $C. Выслеживай их. Сломи. Отними у них волю к жизни!', 'Убейте 15 игроков Альянса в Ледяной Короне по поручению покорителя небес Корма Черного Шрама.', 'Молодец, $С.$B$BОчень скоро Альянс будет дрожать от страха при одном только упоминании твоего имени, а в Орде будут славить тебя, как героя!', NULL, NULL, NULL, 'Убито игроков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13235, 'Победитель мясистого великана', 'Мясопилка разрушена, слуги Короля-лича убиты – ты хорошо $gпотрудился:потрудилась:! Осталось только уничтожить главное достижение Мясопилки – мясистого великана по имени Тлетворец.$B$BБитва будет не из легких, но Мрачный Свод отправил туда подкрепление, Маргрейва Дакара с отрядом. Тебе надо встретиться с ним на высшей точке западной окраины Мясопилки. Когда будешь $gготов:готова: начать наступление, дай ему знать, и он поведет свое войско в атаку.', 'Поговорите с Маргрейвом Дакаром на западной оконечности Мясопилки, чтобы напасть на Тлетворца. Когда Тлетворец будет уничтожен, доложите об этом темной всаднице Арли из Черного дозора.', 'Теперь, когда мы уничтожили этого мясистого великана, Король-лич поймет, что остальные его войска тоже не неуязвимы. Говорят, что Король-лич не знает, что значит страх, но с твоей помощью мы напомним ему, что это такое.', NULL, NULL, NULL, 'Тлетворец убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13236, 'Войско проклятых', 'Может, ты считаешь себя очень $gсильным:сильной:, раз $gсмог:смогла: победить нежить?$B$BА ты знаешь, скольких трудов стоило их создание?$B$BЯ видел, как принц лично создавал солдат нежити. Если хочешь, могу и тебе показать.', 'По заданию Матиаса Нетлера из Лагеря сопротивления первого легиона создайте армию из 100 вурдалаков-прислужников.', 'Но способность создавать армии из трупов не была главным умением принца. Это давалось ему легко.$B$BНо вот убивать своих же солдат, с которыми не раз приходилось воевать плечом к плечу... Да. Поистине главным умением принца была способность делать то, чего требовала от него ситуация.', NULL, NULL, NULL, 'Оживлено вурдалаков-прислужников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13237, 'Тычки и тумаки', 'Пока ваш командир отвлекся на врагов из Альянса, мы можем сосредоточиться на основных противниках: Короле-личе и его прислужниках.$B$BЕсли мы еще надеемся взять цитадель, надо, чтобы твои люди контролировали каждые ворота.$B$BТак, будем действовать постепенно. Для начала вернись на поля боя и прорви оборону врага. Узнай, какие у них есть слабые стороны.$B$BЯ жду твоего доклада, $C.', 'По поручению Кольтиры Ткача Смерти, находящегося на борту \"Молота Оргрима\", вы должны отправиться на Прорванный фронт и уничтожить 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы.', 'Правда-правда, $C?$B$BТебе нечего мне рассказать? Совсем?$B$B<Кольтира замечает ошметки поганищ, прилипшие к вашей одежде, и начинает улыбаться.>$B$BПозволю себе тебе не поверить...', NULL, NULL, NULL, 'Уничтожено неповоротливых поганищ', 'Уничтожено злокозненных некромантов', 'Уничтожено адептов Тьмы', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13238, 'Какая-то полезная штука', 'Гоблины! Им вечно неймется! Они, что ли, рождаются с шилом в известном месте...$B$BСлушай, $N, Меднопал, наш местный инженер, очень хочет продемонстрировать мне какую-то штуку. Говорит, это очень полезная вещь.$B$BЯ сейчас не в том настроении, чтобы выслушивать его писклявые разглагольствования. В нашу последнюю встречу он верещал целый час, не умолкая! Я еле сдержался, чтобы не отправить его пинком в Каньон Гибели Сингдрагосы!$B$BСходи к нему вместо меня, хорошо? Пусть он покажет тебе эту \"полезную штуку\". Если это действительно что-то полезное, дай мне знать.', 'Поговорите с главным инженером Меднопалом на борту \"Молота Оргрима\" по поручению покорителя небес Корма Черного Шрама.', 'Занят? Пфф… Тоже мне, деловой нашелся! $B$BЛадно, неважно. Сойдешь и ты...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13239, 'Непостоянство', 'Даже не знаю, с чего начать... ну, ты, наверное, знаешь, что будучи главным инженером этого корабля, я имею неограниченный доступ ко всем данным разведки – да, это правда, и меня очень заинтересовали эти ледяные змеи, которых ты $gвидел:видела: на юге. Кажется, я придумал, как нам их изничтожить... но мне понадобится твоя помощь. Сооруди манекен из доспехов, обрызгай его этим раствором и сразу беги в укрытие!$B$B...Эй, ты еще здесь, $r?', 'Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.Для того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенный доспех.', 'Ничего себе! Даже отсюда мне было видно, как они загорелись! В общем, эксперимент удался. Я отмечаю очередной успех и начинаю разливать раствор по бутылкам – в плане подготовки к вторжению. Скорее всего, нам понадобится провести еще несколько испытаний. И мы их проведем! Ну, то есть, если тебе интересно...', NULL, NULL, NULL, 'Проведены полевые испытания', 'Летучее масло Меднопала', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13240, 'Времиар превидит встречу с центрифужными созданиями!', 'Ты $gдолжен:должна: отправиться в Окулус, дрейфующий над Хладаррой, $N.$B$BУ меня было видение, в котором ты уничтожаешь находящихся там центрифужных созданий. Уверяю тебя, если ты не нападешь $gпервым:первой: на эти магические создания, они уничтожат тебя и твоих друзей.$B$BТаким мне явилось будущее – и ты $gдолжен:должна: прислушаться к моему предчувствию.', 'Исполните волю верховного мага Времиара, обитающего в Даларане, которого посетило видение, где вы уничтожаете 10 центрифужных созданий.', '<Верховный маг кивает еще до того, как вы успели вымолвить хоть слово.>$B$BЯ знаю. Ты уничтожил эти создания, как я и предвидел, и даже смог победить Вароса Заоблачного Странника.$B$BОтличная работа, $N!', NULL, NULL, NULL, 'Центрифужное создание убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13241, 'Времиар превидит встречу имирьярскими берсерками!', 'Могучие воины короля Имирона в ближайшем будущем встанут на твоем пути к успеху! $B$BТебе следует отправиться в крепость, известную как Вершина Утгард, находящуюся в глубине лесов Ревущего фьорда. Трудно описать, насколько важная задача стоит перед тобой и твоими друзьями. Вы должны уничтожить имирьярских берсерков, вершащих там злые дела.$B$BЕсли вас постигнет неудача, смерть станет вашим наказанием, $N!', 'Уничтожьте по заданию верховного мага Времиара, обитающего в Даларане, 7 имирьярских берсерков.', 'Выдающаяся работа, Профессия.$B$BЕсли бы ты не смог это сделать, оставшиеся в живых берсерки помешали бы тебе во время битвы с королем.', NULL, NULL, NULL, 'Имирьярский берсерк убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13242, 'Шевеление Тьмы', 'Тьма зашевелилась, $N. Произошло трагическое событие, которое никто, кроме Вневременного, не мог предвидеть. Скоро твой народ охватит злоба и ненависть. Приближается война.$B$BКрасные драконы сделали все, что было в их силах. Теперь все зависит от смертных рас Азерота.$B$BУвы, твое путешествие начинается со страданий. Сегодня отец потерял свое дитя. Тебе предстоит стать вестником, приносящим скорбные новости. Собери вооружение Саурфанга и отнеси его Саурфангу-старшему.', 'Соберите на поле боя боевые доспехи Саурфанга и верните их верховному правителю Саурфангу в крепость Песни Войны, что в Борейской тундре.', '<Саурфанг смотрит в небеса.>$B$BМой сын погиб как герой, подобно Броксу. Не горюй по нему, $N. Для орка нет лучшей смерти! Нет более великой чести! И сейчас мое сердце наполняется гордостью.$B$BСпасибо тебе, что вернул мне его доспехи. Я возложу их на его погребальный костер в Землях Предков в Награнде.$B$BМы должны переключить наше внимание на более серьезные проблемы.', '<Гримаса боли искажает лицо Саурфанга.>$B$BМое сердце…моя сила...', NULL, NULL, 'Боевые доспехи Саурфанга', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13243, 'Времиар превидит встречу с посланницами из рода Бесконечности!', 'Драконы бесконечности угрожают существованию самого времени. Если ты не помешаешь им, ход времени будет искривлен!$B$BТы $gдолжен:должна: отправиться в Пещеры Времени и переместиться в прошлое, в период, известный нам как Очищение Стратхольма.$B$BУ меня начинает раскалываться голова даже от попыток просмотреть все вариации прошлого, но я точно знаю, как жизненно важно тебе уничтожить посланниц из рода Бесконечности.$B$BЛишь когда они будут убиты, истинное прошлое будет сохранено, а настоящее и будущее никогда больше не подвергнутся угрозе изменения!', 'Верховный маг Времиар из Даларана предчувствует, что вам необходимо убить 4 посланниц из рода Бесконечности.', 'Мы спасены. Спасибо тебе.$B$BУвы, природа их вмешательства такова, что драконы Бесконечности обладают практически неограниченными возможностями сделать это еще раз.$B$BИ если это случится, я ясно вижу в будущем, как ты ринешься в сердце битвы, чтобы остановить их, $N!', NULL, NULL, NULL, 'Посланница из рода Бесконечности убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13244, 'Времиар превидит встречу с $Nвыми воинами!', 'Опасность нависла над всем Азеротом. Безумный бог Локен действительно в силах уничтожить все живое!$B$BВ Земной сторожевой башне, что в Чертогах Молний, лучшие $Nвые воины пытаются исполнить смертоносную волю Локена, грозящую погубить неисчислимое количество жизней.$B$BЯ видел будущее, $N. Ты станешь $gтем:той:, кто не допустит, чтобы это произошло!', 'Убейте 7 $Nвых воинов, дабы предсказанное верховным магом Времиаром из Даларана сбылось.', 'Мы перед тобой в долгу, $N.$B$BЕсли я в чем и могу испытывать уверенность, так это в том, что ты никогда не подведешь нас в будущем, эм…как и в прошлом!', NULL, NULL, NULL, 'Титановый воин убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13245, 'Доказательство смерти: Ингвар Расхититель', 'Я хочу, чтобы ты $gсобрал:собрала: группу и $gотправился:отправилась: в крепость Утгард. Там тебе предстоит найти и уничтожить Ингвара Расхитителя – прежде, чем он поведет свои войска врайкулов в атаку на ближайшие города Альянса и Орды.$B$BМне потребуется его секира в качестве доказательства того, что с ним покончено. Дело не в том, что я тебе не доверяю. Просто разумно было бы на моем месте убедиться в том, что дело сделано.', 'Принесите секиру Расхитителя верховному магу Лан\'далоку, обитающему в Даларане.Это задание выполняется в героическом режиме.', 'Хорошо. Прислони секиру к стене.$B$BЯ уверен, что Валгард и Лагерь Возмездия сегодня будут спать более спокойно, зная, что с этим злодеем благодаря тебе наконец-то покончено.', 'Удалось ли тебе заполучить секиру? Ингвар мертв?', NULL, NULL, 'Топор Расхитителя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13246, 'Доказательство смерти: Керистраза', 'Известна ли тебе история Керистразы?$B$BКак она помогла убить Сарагосу, супругу Малигоса? Как затем он завладел Керистразой и заморозил ее в глыбе льда?$B$BМы узнали, что он использовал свою магию, чтобы сломить ее волю. Это свело ее с ума.$B$B$N, ты $gдолжен:должна: отправиться в Нексус, что в Хладарре, и уничтожить ее, прежде, чем она окончательно обезумеет.$B$BЭто печалит меня, но я настаиваю, чтобы ты $gпринес:принесла: мне ее сердце в качестве доказательства того, что ее больше нет.', 'Принесите в Даларан по заданию кровавого верховного мага Лан\'далока разбитое сердце Керистразы.Это задание выполняется в героическом режиме.', 'Увы, это было необходимо.$B$BОрден Кирин-Тор не мог позволить столь видной представительнице красных драконов пасть жертвой нашего величайшего врага. Если бы Малигос начал использовать ее в Войне Нексуса, настал бы конец всему.$B$BНо я горюю о том, что не могли мы спасти ее.', 'Если бы нам был известен способ, как исцелить ее, мы бы не просили тебя ее убить.$B$BНо мы знаем, насколько сильна стала власть Малигоса над магией. После его манипуляций с силовыми линиями Азерота он стал непревзойденным мастером тайной магии.', NULL, NULL, 'Разбитое сердце Керистразы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13247, 'Доказательство смерти: хранитель энергии Эрегос', 'Война Нексуса продолжает бушевать, $N, и нам нужно что-то предпринять, чтобы изменить ход событий! Хочешь ли ты отправиться в сердце битвы?$B$BХранитель энергии Эрегос охраняет канал, по которому Малигос выкачивает магию из силовых линий Азерота. Если мы сможем уничтожить его, это нанесет сильный удар по нашему врагу.$B$BПожалуйста, принеси мне одно из его устройств для настройки силовых линий, чтобы мы смогли изучить его.', 'Принесите устройство для настройки силовых линий верховному магу Лан\'далоку в Даларан.Это задание выполняется в героическом режиме.', 'Спасибо тебе, $N. Тщательное изучение этого устройства даст нам возможность лучше понять, как именно Малигос манипулирует силовыми линиями.$B$BЕсли мы сможем понять, как оно работает, может быть, у нас получится использовать его и изменить ход событий в свою пользу.', 'Встретил ли хранитель энергии свой неминуемый конец, $C?$B$BЯ думаю, мне можно не напоминать тебе о том, что Малигос пытается лишить весь наш мир возможности использовать магию, и что синие драконы убивают всех, кто знает о ней хотя бы что-нибудь и отказывается перейти на их сторону?', NULL, NULL, 'Устройство для настройки силовых линий', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13248, 'Доказательство смерти: король Имирон', 'Король Имирон с вершины Утгарда пребывает в милости у Короля-лича. Одной этой причины было бы достаточно для того, чтобы покончить с ним.$B$BНо если он протрубит в рог и созовет всех вождей племен, подобных имирьярам и мьординам, врайкулы станут силой куда более мощной, чем прочие армии Плети!$B$BТы, $N, $gдолжен:должна: сделать так, чтобы этого никогда не произошло. Принеси мне медальон с его шеи, чтобы я знал, что Имирон больше не представляет для нас угрозы.', 'Принесите медальон Усопшей королевы верховному магу Лан\'далоку в Даларан.Это задание выполняется в героическом режиме.', '<Верховный маг хмуро кивает вам, когда вы передаете ему достаточно большой образец ювелирного искусства.>$B$BЧто сделано, то сделано. Эти врайкулы – такой благородный народ. Как жаль, что Король-лич столь глубоко вонзил в них свои смертоносные крючья.', 'Нельзя позволить Имирону повести за собой народ врайкулов. Если он вернется в Ледяную Корону с победой, велика вероятность того, что все будет потеряно.', NULL, NULL, 'Медальон Усопшей королевы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13249, 'Доказательство смерти: пророк Тарон\'джа', 'Крепость Драк\'Тарон когда-то была гордым бастионом Драккари. Теперь это лишь перевалочный пункт для Короля-лича, пытающегося сокрушить Зул\'Драк и завладеть силой тролльих богов.$B$BНо если бы мы уничтожили здешнего предводителя, пророка Тарон\'джа, возможно, мы смогли бы остановить поступления все новых отрядов подкрепления для Плети из числа троллей. По крайней мере, это избавит Серебряный Авангард в Зул\'Драке хотя бы от одной из проблем.$B$BВозвращайся ко мне с его амулетом в качестве доказательства того, что пророк уничтожен.', 'Принесите верховному магу Лан\'далоку в Даларан заколдованный амулет пророка.Это задание выполняется в героическом режиме.', 'Если удача будет сопутствовать нам, теперь, обезглавленная, крепость Драк\'Тарон перестанет отвлекать нас от главной проблемы в этой области – от борьбы с Плетью.$B$B<Верховный маг переводит взгляд на амулет, который он держит в руке.>$B$BЭто к лучшему, что амулет потерял свою колдовскую силу. Теперь мне не придется размышлять ни о том, как его использовать, ни о том, вправе ли я вообще это делать.', 'Повержен ли пророк? С тобой ли у тебя амулет?', NULL, NULL, 'Заколдованный амулет пророка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13250, 'Доказательство смерти: Гал\'дара', 'Драккарские пророки Зул\'Драка совершили немыслимое: они уничтожили большинство своих богов и завладели их силой! Самый могущественный и опасный среди них – это верховный пророк Акали, Гал\'дара.$B$BУединившийся в недрах Гундрака Гал\'дара впитал в себя практически всю колдовскую силу убитого Акали и теперь хочет извергнуться из города вместе со своими последователями в окружающий мир. Если мы не убьем его сейчас, нас захлестнет море безумной и невообразимой силы!$B$BБыстрее, $N, принеси мне то, что осталось от колдовской силы Акали.', 'Принесите верховному магу Лан\'далоку в Даларан остатки колдунства Акали.Это задание выполняется в героическом режиме.', 'Спасибо тебе, $N. Я присмотрю за тем, чтобы само воплощение эссенции бога было надежно спрятано до тех пор, пока его не заберут представители племени зандаларов.$B$BМожет быть, они найдут способ, как с помощью того, что осталось, провести ритуал реинкарнации Акали?', 'У тебя ли остатки колдунства?$B$BТошно смотреть, как погибает еще одно великое племя троллей.$B$BЯ думаю лишь о том, что если бы не вмешательство Короля-лича, тролли бы никогда не восстали против своих богов и не украли их силу, чтобы противостоять армиям Плети.', NULL, NULL, 'Остатки колдунства Акали', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13251, 'Доказательство смерти: Мал\'Ганис', '$N, один друг из числа бронзовых драконов снабдил меня кое-какой информацией, и мы должны ею воспользоваться.$B$BЗагадочные создания Пылающего Легиона, называемые Повелителями ужаса, известны как раса Натрезим. Немногое мы знаем об их родном мире, и то – одни лишь слухи.$B$BНо известно, что Мал\'Ганис в своем прошлом совершил фатальную ошибку: он потерял артефакт из своего родного мира!$B$BЧерез Пещеры Времени ты $gдолжен:должна: отправиться назад в прошлое, в период, известный нам как Очищение Стратхольма. Отыщи и принеси мне тот артефакт.', 'Принесите артефакт из родного мира натрезимов верховному магу Лан\'далоку в Даларан.Это задание выполняется в героическом режиме.', 'Поразительно! Я никогда не видел ничего подобного. Я прослежу за тем, чтобы он попал в надежные руки в Аметистовой цитадели.$B$BЕсли бы только тебе было позволено изменять ход истории... Возможно, если бы мы смогли уберечь Артаса от… нет, если думать об этом, можно сойти с ума.$B$BКонечно же, Хранители Времени понимают в этом больше, чем простые смертные.', 'Мы должны использовать ошибку Мал\'Ганиса. Не каждый день мы получаем такой шанс.$B$BЕсли мы сможем изучить этот артефакт, может быть, мы лучше станем понимать натрезимов!', NULL, NULL, 'Артефакт с родины натрезимов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13252, 'Доказательство смерти: Сьоннир Литейщик', 'Немногое известно о том состоянии, что известно как Проклятие Плоти. Однако в Чертогах Камня хранится кое-какая информация.$B$BСьоннир Литейщик, похоже, знает многое об этом проклятии. Нам достоверно известно, что у него есть диск титанов, содержащий ответ на многие наши вопросы.$B$BПринеси мне этот диск, $N, чтобы мы смогли его изучить.', 'Принесите верховному магу Лан\'далоку в Даларан диск о Проклятии Плоти.Это задание выполняется в героическом режиме.', 'Разве технология титанов не поразительна? Информация содержится вот на этом диске!$B$BЯ лишь смею надеяться, что мы сможем найти способ извлечь ее оттуда.', 'Удалось ли тебе добыть диск?', NULL, NULL, 'Диск Проклятия Плоти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13253, 'Доказательство смерти: Локен', 'Локен, затаившийся в Чертогах Молний, жаждет положить конец всему нашем миру. Нужно ли мне еще что-то говорить, $N?$B$BОн восседает там, слушая безумные нашептывания Древнего Бога, запертого в глубинах под Нордсколом. Ты и твои друзья должны отправиться на Грозовую Гряду немедленно!$B$BБросьте вызов Локену в Земной сторожевой башне и остановите его, пока еще не слишком поздно! Принесите мне его рубиновое кольцо, и я пойму, что мы снова в безопасности.', 'Принесите верховному магу Лан\'далоку в Даларан божественное рубиновое кольцо.Это задание выполняется в героическом режиме.', '<Верховный маг Ландалок вздыхает с облегчением.>$B$BЕсли честно, я боялся, что с тобой случится самое худшее. Трудно вот так стоять и ничего не делать, когда другие, подобно тебе, оперируют с материями самой жизни и смерти, ежедневно угрожающими равновесию нашего мира.$B$BНу, и что же нам теперь делать с этим огромным кольцом?', 'Мы снова беседуем с тобой, $N. Значит ли это, что мы спасены от безумия Локена – или наоборот, что судьба наша предрешена?', NULL, NULL, 'Небесное рубиновое кольцо', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13254, 'Доказательство смерти: Ануб\'арак', 'Порабощенные Плетью нерубы – просто чума для наших армий.$B$BСейчас, дрейфуя над миром, мы пребываем в относительной безопасности, но стоит нам спуститься на землю, как мы начинаем думать лишь о том, что нерубы могут выбраться из глубин Азжол-Неруба и напасть на нас.$B$BХорошо было бы посеять среди них панику. Убей их бывшего короля, ныне – мажордома Короля-лича, владыку склепа Ануб\'арака.$B$BПожалуйста, принеси мне его корону... все равно он ее больше не носит.', 'Принесите бесполезную корону Ануб\'арака верховному магу Лан\'далоку из Даларана.Это задание выполняется в героическом режиме.', 'Я с содроганием представляю, что за неисчислимые ужасы повстречались тебе во время путешествия в Верхний город.$B$B<Ландалок бросает взгляд на потускневшую корону, зажатую в вашей руке.>$B$BМожет, нам стоит сохранить ее для нового короля нерубов – ведь рано или поздно они решат короновать кого-нибудь?', 'Я весьма рад, что это ты отправляешься в Азжол-Неруб, а не я.$B$BУж очень я не люблю спускаться под землю.', NULL, NULL, 'Бесполезная корона Ануб\'арака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13255, 'Доказательство смерти: глашатай Волаж', 'Нерубы Ан\'кахета копали слишком глубоко, пытаясь сбежать от наступающих армий Плети. Они подобрались слишком близко к Древнему Богу, влачащему свое существование в глубинах под Нордсколом.$B$BОбнаружив их присутствие, Древний Бог натравил на них своих безумных созданий, и нерубы попали между вошедшими в поговорку молотом и наковальней.$B$BЛидер сил Древнего Бога – глашатай Волаж – одно из кошмарных созданий, известных под именем Безликих. Покончи с ним и принеси мне его усохший мозг.$B$BНо, пожалуйста, постарайся $gсам:сама: не сойти с ума.', 'Принесите верховному магу Лан\'далоку в Даларан усохший мозг Безликого.Это задание выполняется в героическом режиме.', '<Верховный маг с опаской разглядывает мозг.>$B$BТеперь, когда я об этом думаю, мне не кажется, что находится рядом с этой штукой так уж безопасно. Говоришь, оно все еще живое?$B$B<Он качает головой.>$B$BУ нас есть подходящее место для хранения подобной штуковины в цитадели. Я прослежу, чтобы один из моих учеников отнес ее туда тотчас же.', '$N? Ты по-прежнему в своем уме?', NULL, NULL, 'Иссохший мозг безликого', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13256, 'Доказательство смерти: Синигоса', 'На нас напали! Синие драконы телепортировались в Аметистовую крепость и теперь планируют вторгнуться оттуда в Даларан!$B$BДо нас уже доходили слухи о заключенных, которые были – якобы случайно – освобождены ими. Я не удивлюсь, если они специально выпускают некоторых из них на волю.$B$B$N, не $gмог:могла: бы ты как можно быстрее сколотить команду и отправиться туда? Их силы ведет в бой Синигоса. Принеси мне ее голову!', 'Принесите верховному магу Лан\'далоку в Даларан голову Синигосы.Это задание выполняется в героическом режиме.', 'С опасностью покончено, а оставшиеся пленники, оказавшиеся на свободе, снова водворены в тюрьму.$B$BДаларан перед тобой в долгу, Профессия!$B$BТеперь мне нужно задать кое-кому пару вопросов, а конкретнее: почему легче всего было пробиться через анти-телепортационный барьер города именно в тюрьме?!', 'Если хорошенько подумать, зачем бы я телепортировался в тюрьму, чтобы потом пытаться из нее выбраться? Это же самое охраняемое здание в городе.$B$BМне кажется, эти синие совсем сошли с ума!', NULL, NULL, 'Голова Синигосы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13257, 'Глашатай войны', 'Вождь нуждается в тебе, $gвоин:воительница:. Оргриммар на военном положении. Торговля, оказание услуг – все теперь свернуто, когда вождь готовится к неизбежному конфликту.$B$BЯ не могу сказать тебе больше – во всяком случае, не сейчас. И не здесь.$B$BВождь приказывает всем самым сильным воинам направиться к нему на доклад в его тронную залу. Ступай, $N! Воспользуйся этим порталом, чтобы вернуться в Оргриммар и встретиться с Траллом.', 'Доложите о своем прибытии Траллу, который находится в крепости Громмаш в Оргриммаре.', 'Повелитель демонов Вариматас и главный аптекарь Отрекшихся Гнилесс – вот кто несет ответственность за это предательство.$B$B<Тралл кивает.>$B$BДа, тот самый Гнилесс, который нашел лекарство против недавней вспышки чумы.$B$BТе, кто не приняли их сторону, были убиты или изгнаны. Во время переворота чуть не погибла Сильвана.$B$BОрда потеряла Подгород. Оргриммар будет принимать беженцев-Отрекшихся у себя, пока не будет найдено решение этой проблемы. До тех пор мы находимся на военном положении.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13258, 'Замечательная возможность', 'Нам удалось заполучить документы и планы, в которых указано слабое место Цитадели Ледяной Короны. Брешь в их обороне – и в прямом, и в переносном смысле.$B$BНа планах указан какой-то проход, уходящий под землю на несколько сотен футов. Мы не знаем его назначения, но наши разведчики доносят, что этот проход очень важен для Плети.$B$BПоговори с сержантом Креггой под стенами Цитадели Ледяной Короны. Она командует нашими силами, штурмующими цитадель.', 'Поговорите с сержантом Креггой под стенами Цитадели Ледяной Короны.', 'Ты очень вовремя, $N. Кольтира хорошо о тебе отзывался. Он очень высокого мнения о тебе. Может быть, с твоей помощью мы сумеем склонить чашу весов на нашу сторону.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13259, 'Закрепить преимущество', 'У нас почти все готово, чтобы причинить ощутимый ущерб этому тепленькому местечку, но надо все сделать с умом.$B$BНам удалось раздобыть очень мощные саронитовые бомбы, изготовленные мастерами Плети. Но прежде чем мы их взорвем, нужно зачистить территорию.$B$BВремени мало, нам надо успеть, пока Плеть не прислала сюда подкрепление.$B$BПомоги моим солдатам, а потом возвращайся сюда, и мы устроим фейерверк.', 'Убейте 10 неповоротливых громад по поручению сержанта Крегги, находящегося у Цитадели Ледяной Короны.', 'Ты так быстро управился с силами Плети, $N! А теперь давай сделаем то, ради чего мы сюда пришли.', 'Ради чести и славы, $N!', NULL, NULL, 'Неповоротливая громада убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13260, 'Уж кто бы говорил!', 'Сражаясь против Альянса, мы не должны забывать и о Плети.$B$BВ ближайшие недели мы еще не сможем начать наступление, но это не значит, что мы не должны изучить оборону противника.$B$BЯ попросил прикрепленного к нашему войску рыцаря смерти дать тебе пару советов. Ведь если подумать, то кто может знать этого врага лучше, чем рыцари смерти?$B$BПозволь представить тебе: Кольтира Ткач Смерти.', 'По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту \"Молота Оргрима\".', '<Кольтира осматривает вас с ног до головы.>$B$BНадеюсь, ты справишься. Иначе тебе же хуже будет, $С.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13261, 'Непостоянство', 'Ух ты! Получилось! То есть я ни капельки не сомневался в своей сверхъестественной гениальности и мастерстве, я просто не был уверен, какова будет мощность взрыва – в общем, я рад, что ты не $gподпалил себе брови:подпалила себе реснички:. А теперь давай-ка покажем старине Корму, как ты подрываешь этих змеев. Он впечатлится и повысит меня до... э... кто там идет после главного инженера? В общем, бери еще пачку этой убойной штуковины и возвращайся на передовую, а я пойду приведу Корма...$B$BНу, чего ты стоишь? Вперед!', 'Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.Для того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенную броню.', 'Зря старались!$B$BСперва Корм был занят, а когда я все-таки вытащил его наверх – ну, чтобы он посмотрел, – ты уже все закончил. Он обозлился, окрысился на меня и сказал, чтобы я не попадался ему на глаза, ну, как минимум, до завтра...$B$BТак что приходи завтра, и мы попробуем еще раз!', NULL, NULL, NULL, 'Проведены полевые испытания', 'Летучее масло Меднопала', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13262, 'Мощный взрыв', 'Кажется, ситуация вышла из-под контроля уже настолько, что дальше некуда. Вот что мы сделаем, $N.$B$BМне нужно, чтобы кто-то поджег фитиль от этих бомб. И, похоже, это будешь ты.', 'Идите к ближайшему штабелю саронитовых бомб и подожгите фитиль.', 'С виду вроде бы мощные бомбы. Как минимум, они должны повредить окрестные здания.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13263, 'Фитиль короток!', 'Вы поджигаете фитиль и с удивлением замечаете, что он горит гораздо быстрее, чем вы ожидали.$B$BБомбы вот-вот взорвутся, и ваш единственный шанс на спасение – это спрятаться в яме и надеяться, что вас не накроет взрывом.', 'Ищите следы и подсказки, независимо от того, куда вас занесет взрывной волной.', 'Пульсирующий предмет, покрытый толстой коркой льда, таинственно мерцает под водой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13264, 'Как все погано!', 'Поганища…$B$BОни могут быть очень опасными противниками. Мне не раз доводилось видеть, как именно их вмешательство меняло весь ход битвы. Однако немногие догадываются, что поганища могут быть очень ценными союзниками.$B$BМозгов у них, считай, нет вовсе. И если ты знаешь тайны их создания, то сможешь отдавать им распоряжения, которые они будут выполнять, не задумываясь.$B$BМне этот секрет известен – к твоему счастью.$B$BЭтот набор позволит заново оживлять убитых тобой поганищ. Возьми его и используй поганищ против сил Плети у Врат смерти.', 'По заданию Кольтиры Ткача Смерти с \"Молота Оргрима\", используя набор для оживления, воскресите поганище и с его помощью уничтожьте 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса.', 'Вот видишь, $C?$B$BНаходчивость может иногда уравнять ставки даже против, казалось бы, серьезно превосходящего тебя противника.', NULL, NULL, NULL, 'Убито ледяных вурдалаков', 'Взорвано агрессивных упырей', 'Взорвано восставших солдат Альянса', 'Набор для оживления поганища');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13265, 'Сбор ткани', '', '', 'Получи пару лишних кусочков ткани и сшей из них нечто сногсшибательное!', NULL, NULL, NULL, 'Требуется денег: 5', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13266, 'Жизнь без сожалений', 'В день, когда за мной придет моя смерть, я хотел бы сказать, что жизнь прошла не зря. Те, кто станут оплакивать мою гибель, будут знать, что я был вождем, который принимал решения на благо своего народа.$B$BНо предательство Вариматаса и Гнилесса...Все, над чем мы работали, пошло прахом.$B$B<Тралл тяжело вздыхает.>$B$BПравосудие должно свершиться.$B$BПорталы, ведущие в Подгород, будут немедленно открыты. Вол\'джин будет ждать тебя. Вскоре я присоединюсь к тебе. Вместе мы сделаем то, что нужно сделать, $N.', 'Воспользуйтесь порталом в Подгород, расположенном в крепости Громмаш, и доложите о своем прибытии Вол\'джину.', 'Позволь мне ввести тебя в курс дела, Силаминка.$B$BПодгород на военном положении. Аптекари Гнилесса и демоны Вариматаса захватили власть над городом. Они ушли в глухую оборону внутри города и используют против наших войск свою проклятую чуму.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13267, 'Битва за Подгород', 'Весь Подгород под контролем Вариматаса. Наши солдаты находятся в боевой готовности, ожидая от вождя приказа идти в атаку.$B$BПомоги Орде отвоевать Подгород и встань в один ряд с нашими самыми великими воинами! Если останешься в живых, доложись Траллу.$B$BДай вождю знать, когда будешь $gготов:готова: вступить в бой.', 'Помогите Траллу и Сильване вернуть Орде контроль над Подгородом.В случае успеха отрапортуйте об этом Траллу.', 'Завтрашний день несет с собой неопределенность. Прошли те дни, когда Альянс и Орда бились плечо к плечу друг с другом против общего врага. Новая битва грядет, $N – битва, в которой победителя не будет.$B$BНо мы должны продолжить наш поход на Ледяную Корону. В этом у нас нет выбора. Наше спасение – в героях, подобных тебе, $N. Будущее Орды – будущее всего мира – зависит от тебя.$B$BДавай вернемся в Оргриммар. Тебе нужно немедленно отправляться в Нордскол.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13268, 'Сбор ткани', '', '', 'Возвращайся, когда наберешься опыта – и тогда, возможно, я смогу научить тебя еще кое-чему.', NULL, NULL, NULL, 'Требуется денег: 5', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13269, 'Сбор ткани', '', '', 'Пусть у тебя всегда будет много ткани.', NULL, NULL, NULL, 'Требуется денег: 5', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13270, 'Сбор ткани', '', '', 'С удовольствием помогу тебе в делах.', NULL, NULL, NULL, 'Требуется денег: 5', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13271, 'Голос во тьме', 'Этот предмет – вовсе не кристалл: скорее, он похож на некий орган, заключенный в ледяную оболочку. $B$BКогда вы касаетесь его, вашу руку обжигает невыносимая боль, словно бы от раны, хотя на руке не остается ни следа.$B$BИ вдруг вы слышите голос маленького мальчика. $B$B\"Тебе не стоило этого делать...\"', 'Идите на голос в Забытые Глубины – Наз\'анак.', 'Я видел, как он избавился от этой штуковины. Бросил ее прямо здесь.$B$BСказал, ему она больше не пригодится. Сказал, она забирает у него силы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13272, 'Сбор ткани', '', '', 'Думаю, что владея эти умением, ты значительно продвинешься на пути к совершенству в портновском деле!', NULL, NULL, NULL, 'Требуется денег: 5', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13273, 'В поисках ядра', 'Теперь, когда оболочка Норганнона у нас в руках, осталось найти вторую половину ключа от архива. По счастью, Лига исследователей немало потрудилась, разыскивая следы ядра Норганнона.$B$BДалеко к юго-востоку от Библиотеки Изобретателя, на склонах к северу от Дун Ниффелема, находится лагерь, который носит мое имя. В этом лагере живут представители Лиги исследователей, которые занимаются поисками второй половины ключа. Принеси мне их карты и записи, и мы сумеем найти то, что ищем.', 'Найдите записи геолога Хроны и записи геолога Сорена в главном лагере Бранна.', 'Разрушен? То есть как это – разрушен?$B$B<Бранн гневно стискивает кулаки.>$B$BНу, железные дворфы! Они мне за это заплатят! Что ж, пока что мы мало что можем сделать – займемся же тем, чтобы собрать ключ. Однако как только я попаду в чертоги Ульдуара, железные дворфы и их хозяева ответят за все, что они натворили!', 'Ну что, где записи?', NULL, NULL, 'Записи геолога Хроны', 'Записи геолога Сорена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13274, 'Хранитель ядра', 'В записках геолога Сорена сказано, что ядро Норганнона хранится у одного из созданий Мимира, стража по имени Атан.$B$BСорен говорит, что подземелье, где обитает Атан, в наше время зовется \"Сделка Локена\".$B$BЛокен. Любопытно, не правда ли? О нем упоминали земельники.$B$BГоворят, это подземелье находится к юго-западу от разрушенного лагеря Лиги изобретателей, круглый вход в подземелье расположен на склоне горы со стороны долины Древних Зим.$B$BОтыщи этого Атана и отбери у него ядро. Но, думаю, без боя он его не отдаст...', 'Добудьте ядро Норганнона.', 'Да, вот оно! Ключ практически у нас в руках! Осталось только выяснить, как соединить оболочку и ядро. Давай посмотрим, что говорится об этом у Сорена…', 'Ну что, прав был геолог Сорен? Удалось ли тебе отыскать ядро Норганнона?', NULL, NULL, 'Ядро Норганнона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13275, 'Пора прятаться!', 'Не стоило тебе трогать эту штуку! Теперь он непременно явится искать тебя.$B$BИ он тебя найдет. Если только ты не сумеешь от него спрятаться.$B$BХочешь выжить – принеси мне кровь безликих!', 'Добудьте 3 образца крови безликих по совету Матиаса Нетлера.', 'И чего ты ждешь? Натрись ею!$B$BБыстрей! А то он тебя увидит!', 'Ну что, где кровь?', NULL, NULL, 'Кровь безликого', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13276, 'Как все погано!', 'Ты знаешь, что делать, $C.$B$BВозьми этот набор и используй внутренности поганищ, чтобы создать свое собственное, а потом прикажи ему атаковать вражеские силы у врат.$B$BТебе стоит отработать эту тактику к тому времени, как мы пойдем на штурм врат.', 'Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Кольтиры Ткача Смерти с \"Молота Оргрима\".', 'Я вижу, ты все лучше управляешься с поганищами!$B$BПри должном усердии с твоей стороны Орда, глядишь, скоро возьмет врата.', NULL, NULL, NULL, 'Убито ледяных вурдалаков', 'Взорвано агрессивных упырей', 'Взорвано восставших солдат Альянса', 'Набор для оживления поганища');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13277, 'Борьба с великанами', 'Конечно, очень важно разгромить Плеть на поле битвы, но все-таки не следует пренебрегать и самими воротами.$B$BМясистые великаны, что обороняют укрепления, могут швырять массивные валуны и куски льда, нанося катастрофический урон вражеской пехоте.$B$BСоберись с силами и уничтожь этих великанов. Нам надо знать, насколько они сильны, чтобы предвидеть, с чем предстоит иметь дело.$B$BДа, и кстати, принеси мне их позвоночники. Если память мне не изменяет, с ними можно проделать одну любопытную штуку... Тебя я, конечно, тоже этому научу.', 'Принесите Кольтире Ткачу Смерти на борт \"Молота Оргрима\" 5 гноящихся позвоночников пустулезных ужасов из Морд\'ретара.', 'Великолепно. Похоже, это именно то, что надо.$B$BВсегда следует по возможности бить врага его же оружием…', 'Ну что, $R, удалось ли тебе одолеть великанов?', NULL, NULL, 'Гноящийся позвоночник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13278, 'Корпой Оскверненный', '$C, до меня дошли известия о том, что у Врат Смерти появился новый могучий зомби.$B$BМы не можем сидеть сложа руки, когда нам угрожает такой серьезный противник. Любые сведения о нем, какие тебе удастся раздобыть, – лучше, чем ничего.$B$BСтупай в западное караульное помещение у врат и найди это существо. Сразись с ним и отыщи брешь в его защите, которой мы могли бы воспользоваться.', 'Убейте Корпоя Оскверненного из Морд\'ретара по просьбе Кольтиры Ткача Смерти с \"Молота Оргрима\".', 'Отлично, $C!$B$BБыть может, проведя исследования, мы сумеем выяснить, как они изготовляют подобных созданий.', NULL, NULL, NULL, 'Корпой Оскверненный побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13279, 'Основы химии', '$gКольтира берет гноящиеся позвоночники и сливает из них жидкость во фляжку.>$B$BМалоизвестное свойство мясистых великанов...$B$BИх спинномозговая жидкость взаимодействует с чумой весьма любопытным образом: на выходе получается очень едкая кислота.$B$BЕсли разлить ее вниз с укреплений, войскам, что внизу, это не понравится, но зато жертвы уже не встанут и не пополнят собой ряды противника.$B$BВылей содержимое этой фляги в один из чумных котлов в западном караульном помещении Врат Смерти.', 'Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд\'ретаре по просьбе Кольтиры Ткача Смерти с борта \"Молота Оргрима\".', 'Молодец, $C!$B$BКогда наши войска двинутся на штурм цитадели, у нас будет готовый план по взятию Врат Смерти…', NULL, NULL, NULL, 'Чумной котел нейтрализован', 'Пустулезная спинномозговая жидкость', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13280, 'Царь горы', 'Короче, $N, мне надо, чтобы ты $gзагнал:загнала: мой прыгобот на са-амую макушку вон той горы на северо-западе, ясно?$B$BЭтот тупой и самодовольный Бубух Громбабах сейчас работает над своим собственным ботом, и, боюсь, он его почти доделал. Короче, мы договорились о соревновании, кто сумеет стать царем горы!$B$BКак доберешься наверх, воткни наш боевой штандарт в груду костей, чтобы все видели, что Альянс сильнее всех, а я – лучший изобретатель!', 'Используйте прыгобот Зуботески, чтобы установить боевой штандарт Альянса в груде черепов на вершине горы, по просьбе Фраззл Зуботески.', 'ПО-ЛУ-ЧИ-ЛОСЬ! ПО-ЛУ-ЧИ-ЛОСЬ!$B$B<Фраззл прыгает на месте и от всей души обнимает вас.>$B$BДа ты… Ты вообще мой самый любимый герой на свете!$B$BСлушай, а завтра прийти не сможешь, а?', NULL, NULL, NULL, 'Боевой штандарт Альянса установлен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13281, 'Избавление от чумы', 'Теперь ты управишься и без моей помощи, $r. Ты уже знаешь, как нейтрализовать вражеские чумные котлы.$B$BИди к Вратам Смерти, прибей пару-тройку мясистых великанов, набери жидкости из их хребтов и вылей ее в котлы, чтобы испортить всю партию этого чумного варева.$B$BБудем разить врага в самое сердце. Это очень важное задание, и его нужно выполнить любой ценой. Трудно сказать, сколько у тебя будет времени, но постарайся охватить побольше котлов.$B$BВеликанов и чумные котлы ты найдешь в Морд\'ретаре.', 'По приказу Кольтиры Ткача Смерти с \"Молота Оргрима\" отправляйтесь в Морд\'ретар и нейтрализуйте содержимое чумного котла с помощью пустулезной спинномозговой жидкости.Пустулезная спинномозговая жидкость изготовляется из позвоночника великана. Его можно получить, убивая пустулезных ужасов.', 'Вот и славно. Еще одним котлом меньше. Когда начнется сражение, в счет пойдет каждый котел.$B$BТвой командир будет доволен.', NULL, NULL, NULL, 'Чумной котел нейтрализован', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13282, 'Возвращение на поверхность', 'Теперь уходи. У меня за спиной есть портал – выходи через него на поверхность.$B$BМы еще встретимся. Он ведь будет тебя искать.$B$BИ найдет, рано или поздно.', 'Вернитесь к Кольтире Ткачу Смерти на борт \"Молота Оргрима\".', 'Это ты, $N! А мы уж думали – все, конец тебе. $B$BВо время взрыва погибло несколько наших… однако он нанес Плети серьезный урон. Они отводят свои войска обратно в цитадель, в их обороне зияют изрядные бреши. Пора на штурм!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13283, 'Царь горы', 'Короче, $N, мне надо, чтобы ты $gзагнал:загнала: мой прыгобот на вершину вон той горы на юго-востоке, ясно?$B$BЭта их девчонка, самодовольная Фраззл Зуботеска, уверена, будто ее бот круче моего. Ха! Короче, у нас тут соревнование, кто сумеет стать царем горы!$B$BКак доберешься наверх, воткни наш боевой штандарт в груду костей, чтобы все видели, что Орда сильнее всех, а я – лучший изобретатель!', 'Используйте прыгобот Громбабаха, чтобы установить боевой штандарт Орды в груде черепов на вершине горы, по просьбе Бубуха Громбабаха.', 'Я знал, я знал, что лучше тебя для этого дела никого не найти!$B$B<Бубух от всей души хлопает вас по спине.>$B$BМогу сразу признаться, что еще ни один $C мне не нравился так, как ты!$B$BСлушай, а как насчет того, чтобы повторить это представление завтра? Ты внакладе не останешься, уж я об этом позабочусь!', 'Постой-ка… А где же наш боевой штандарт?$B$BПочему его нет на горе, $N?!', NULL, NULL, 'Боевой штандарт Орды установлен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13284, 'Атака пехоты', 'Приветствую тебя, $C.$B$BНаши войска несколько раз пытались взять Имирхейм штурмом, но врайкулы оказались куда более серьезным противником, чем все, кто прежде встречался нам. Не раз наши люди попадали в засады: мы потеряли многих и многих... $B$BЕсли ты $gготов:готова: взяться за это дело и провести моих бойцов к вратам Имирхейма, мы щедро и с радостью вознаградим тебя за помощь. Мы намерены разбить лагерь у ворот и там дождаться подкрепления.', 'Сопроводите войска \"Усмирителя небес\" к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к востоку от Имирхейма к военачальнику Купу за наградой.', 'Прими мою благодарность.$B$B Это был не слишком изящный ход, но, с другой стороны, выбирать нам не из чего. Мы попытались атаковать крепость с воздуха, но это также закончилось неудачей. Если мы хотим выжить в Ледяной Короне, нам необходима победа над врайкулами. $B$B Скорее всего, нам снова понадобится помощь. Если это случится, не откажись поддержать нас...', NULL, NULL, NULL, 'Отряды Альянса достигли Имирхейма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13285, 'Изготовление краеугольного камня', 'Ага! Значит, Храм Изобретений, трон самого Хранителя Мимира! Ну разумеется: где же еще следует соединять две части ключа, как не там?$B$BСогласно записям геолога, Храм Изобретений – одна из самых высоких точек с западной стороны Террасы Творцов. Короче, он должен быть примерно на восток от места крушения Гром\'арша.$B$BВстретимся с тобой у храма и соединим части ключа.', 'Встретьтесь с Бранном Бронзобородом в Храме Изобретений и помогите Бранну сложить вместе оболочку Норганнона и ядро Норганнона. После этого вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша.', '<Вы рассказываете Боктару, как помогли Бранну отыскать части краеугольного камня и соединить их. Боктар одобрительно кивает.>$B$BДа, возможно, Бранн – тот самый союзник, который нужен нам, чтобы выяснить, что же на самом деле происходит в Ульдуаре. Правильно мы сделали, что помогли ему. Против этого Локена и его прихвостней, железных дворфов, никакая помощь не будет лишней.', NULL, NULL, NULL, 'Помогите Бранну собрать краеугольный камень', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13286, 'Хоть какая-нибудь помощь!', 'Тяжкие времена настали, $C…$B$BКак ни неприятно это признавать, я готов принять помощь от кого угодно, даже от нашего рыцаря смерти.$B$BСтупай к Тассариану и спроси, не согласится ли он помочь нам разработать тактику борьбы с Плетью, которая могла бы обеспечить победу.$B$BМы забрались слишком далеко... мы не можем потерпеть поражение!', 'Поговорите с Тассарианом по просьбе старшего капитана Джастина Бартлетта на борту \"Усмирителя небес\".', 'Капитан Бартлетт поступил мудро, прислав тебя ко мне.$B$BСам он слишком поглощен противостоянием с Ордой, но кому-то нужно полностью сосредоточиться на нашей главной миссии: взятии цитадели Ледяной Короны!$B$BКто же сумеет дать тебе лучший совет, как не бывший слуга Короля-лича?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13287, 'Тычки и тумаки', 'Тебе, при твоем богатом опыте, несомненно, известно, что лучший способ побольше разузнать о противнике – это сойтись с ним в бою.$B$BТы, несомненно, жаждешь обрести славу, взяв цитадель Ледяной Короны, но это невозможно сделать, пока не будут взяты все ворота Короля-лича. И для начала тебе следует сосредоточить свои усилия на первых из них...$B$BВозвращайся на Прорванный фронт. Вступи в бой с врагом. Отыщи в обороне противника брешь, которой мы могли бы воспользоваться, и возвращайся ко мне с подробным отчетом.', 'Убейте 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы по просьбе Тассариана, находящегося на борту \"Усмирителя небес\", корабля Альянса.', 'В самом деле, $C? Решительно ничего полезного?$B$B<Тассариан видит, что ваша одежда забрызгана останками поганищ, и улыбается.>$B$BНу что ж, по крайней мере, времени ты даром не терял!', NULL, NULL, NULL, 'Убито неповоротливых поганищ', 'Убито злокозненных некромантов', 'Убито адептов Тьмы', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13288, 'Как все погано!', 'Поганища…$B$BОни могут быть очень опасными противниками. Мне не раз доводилось видеть, как именно их вмешательство меняло весь ход битвы. Однако немногие догадываются, что поганища могут быть очень ценными союзниками.$B$BМозгов у них, считай, нет вовсе. И если ты знаешь тайны их создания, то сможешь отдавать им распоряжения, которые они будут выполнять, не задумываясь.$B$BМне этот секрет известен – к твоему счастью.$B$BЭтот набор позволит заново оживлять убитых тобой поганищ. Возьми его и используй поганищ против сил Плети у Врат смерти.', 'Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с \"Усмирителя Небес\".', 'Вот видишь, $С?$B$BПри должной изобретательности можно одолеть даже непобедимого на первый взгляд противника!', NULL, NULL, NULL, 'Убито ледяных вурдалаков', 'Взорвано агрессивных упырей', 'Взорвано восставших солдат Альянса', 'Набор для оживления поганища');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13289, 'Как все погано!', 'Ты знаешь, что делать, $C.$B$BВозьми этот набор и используй внутренности поганищ, чтобы создать свое собственное, а потом прикажи ему атаковать вражеские силы у врат.$B$BТебе стоит отработать эту тактику к тому времени, как мы пойдем на штурм врат.', 'Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с \"Усмирителя небес\".', 'Я вижу, ты все лучше управляешься с поганищами!$B$BПри должном усердии с твоей стороны Альянс, глядишь, скоро возьмет врата.', NULL, NULL, NULL, 'Убито ледяных вурдалаков', 'Взорвано агрессивных упырей', 'Взорвано восставших солдат Альянса', 'Набор для оживления поганища');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13290, 'Немного внимания', 'Главный инженер Болтоключ за время службы на \"Рассекателе туч\" проявил себя как совершенно незаменимый специалист. Если бы не его изобретательность, нас бы давно размазало тонким слоем по всему леднику.$B$BНо проблема в том, что он считает нужным делиться со мной любым своим открытием или изобретением, хотя я в этом практически ничего не понимаю.$B$BА сейчас мне и подавно не до того: все мои мысли заняты врагами. Я не могу допустить, чтобы меня отвлекали!$B$BПожалуйста, сходи к нему вместо меня, $N. И, если он попросит у тебя помощи, помоги ему, чем сумеешь. Он сейчас внизу, в трюме.', 'Поговорите с главным инженером Болтоключом на борту \"Усмирителя небес\" по просьбе старшего капитана Джастина Бартлетта.', 'Так стало быть, шеф прислал тебя вместо себя, да?$B$BЧто ж, $C, отлично. Засучи-ка рукава! У нас полно дел.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13291, 'Заимствованная технология', 'Понял, все понял! Шеф сейчас слишком занят, ему не до меня. Что ж, тем хуже для него!$B$BСлушай, мне тут удалось… э-э… позаимствовать у противника запас некоего раствора. Я, конечно, терпеть не могу возиться с примитивными гоблинскими технологиями, но в данном случае я готов сделать исключение.$B$BВозьми этот образец. Проведи для меня несколько испытаний – чисто чтобы убедиться, что это действительно полезная штука, – а я тем временем попытаюсь выяснить состав вещества, чтобы получить возможность его воспроизвести.$B$BСтупай на фронт и собери то, что может послужить приманкой, потом используй масло.', 'Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту \"Усмирителя небес\".Для этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте.', 'Отличные новости!$B$BА мне удалось изготовить такой раствор самому. Хотя это, конечно, не особо крупное достижение.$B$BВряд ли я доживу до того дня, когда тупоголовые гоблины сумеют сварить какое-то снадобье, которое гном не сможет воспроизвести одной левой, с закрытыми глазами!', NULL, NULL, NULL, 'Проведены полевые испытания', 'Краденый раствор', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13292, 'Решение проблемы', 'А, да-да. С возвращением. Лишняя практика никогда не повредит, ведь так?$B$BА вот и оно, решение проблемы этих мерзких ледяных змеев.$B$BПрореди их ряды, $r. Чем больше этих монстров погибнет сейчас, тем меньше останется, чтобы противостоять нам во время штурма цитадели.$B$BВот, возьми этот раствор и используй по назначению. А что не используешь, принеси обратно.', 'Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту \"Усмирителя небес\".Для этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте.', 'Молодец! Просто молодчина! Ты превращаешься в настоящего истребителя змеев!$B$BВозвращайся, когда будешь готов еще разок проредить их ряды.', NULL, NULL, NULL, 'Уничтожено ледяных небесных когтей', 'Краденый раствор', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13293, 'В Имирхейм!', 'Тебе нужно спуститься в Имирхейм, большой поселок ледяных врайкулов посреди Ледяной Короны.$B$BТам, на западной окраине поселка, находится наш парень, Бубух Громбабах. Он представляет армию Песни Войны в состязании с Альянсом. Проверяют, чей прыгобот лучше, наш или ихний.$B$BСмотри, $N, не подведи нас! На карту поставлена профессиональная честь гоблинских изобретателей! Кроме того, все наши ребята на тебя рассчитывают.$B$BИ, опять же, мы поставили деньги на то, что ты сумеешь отпинать этих трусов!', 'Поговорите с Бубухом Громбабахом в Имирхейме.', 'Ох, как же я рад тебя видеть? Тебя старшой прислал из Молота?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13294, 'Борьба с великанами', 'Конечно, очень важно разгромить Плеть на поле битвы, но все-таки не следует пренебрегать и самими воротами.$B$BМясистые великаны, что обороняют укрепления, могут швырять массивные валуны и куски льда, нанося разрушительный урон вражеской пехоте.$B$BСоберись с силами и уничтожь этих великанов. Нам надо знать, насколько они сильны, чтобы предвидеть, с чем предстоит иметь дело.$B$BДа, и кстати, принеси мне их позвоночники. Если память мне не изменяет, с ними можно проделать одну любопытную штуку... Тебя я, конечно, тоже этому научу.', 'Принесите Тассариану с \"Усмирителя небес\" 5 позвоночников пустулезных ужасов из Морд\'ретара.', 'Великолепно. Похоже, это именно то, что надо.$B$BВсегда следует по возможности бить врага его же оружием…', 'Ну что, $C, удалось ли тебе одолеть великанов?', NULL, NULL, 'Гноящийся позвоночник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13295, 'Основы химии', '$gТассариан берет гноящиеся позвоночники и сливает из них жидкость во фляжку.>$B$BМалоизвестное свойство мясистых великанов...$B$BИх спинномозговая жидкость взаимодействует с чумой весьма любопытным образом: на выходе получается очень едкая кислота.$B$BЕсли разлить ее вниз с укреплений, войскам, что внизу, это не понравится, но зато жертвы уже не встанут и не пополнят собой ряды противника.$B$BВылей содержимое этой фляги в один из чумных котлов в западном караульном помещении Врат Смерти.', 'Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд\'ретаре по просьбе Тассариана на борту \"Усмирителя небес\".', 'Отличная работа, $С!$B$BКогда наши войска двинутся на штурм цитадели, у нас будет готовый план по взятию Врат Смерти…', NULL, NULL, NULL, 'Чумной штамм нейтрализован', 'Пустулезная спинномозговая жидкость', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13296, 'В Имирхейм!', 'Тебе нужно спуститься в Имирхейм, большой поселок ледяных врайкулов посреди Ледяной Короны.$B$BТам, на южной окраине поселка, находится Фраззл Зуботеска. Она представляет Экспедицию Отважных в состязании с этими ордынскими уродами. Проверяют, чей прыгобот лучше, наш или ихний.$B$BСмотри, $N, не подведи нас! На карту поставлена профессиональная честь гномских изобретателей! Кроме того, все наши ребята на тебя рассчитывают.$B$BИ, опять же, мы поставили деньги на то, что ты сумеешь отпинать этих трусов!', 'Поговорите с Фраззл Зуботеской в Имирхейме.', 'А, тебя прислал наш главный с \"Усмирителя небес\"? Очень мило с его стороны!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13297, 'Избавление от чумы', 'Тебе больше не нужна моя помощь, чтобы обезвредить чумные котлы врагов, $r. $B$BУбей мясистых великанов у Врат смерти и используй их спинномозговую жидкость, чтобы нейтрализовать штаммы чумы. $B$BТы нанесешь сокрушительный удар по стратегии врага. Это крайне важное задание – жизненно важное для нашей победы, и его следует исполнить как можно скорее. $B$BПомни: и великанов, и чумные котлы можно найти в Морд\'ретаре.', 'По приказу Тассариана с \"Усмирителя небес\" отправляйтесь в Морд\'ретар и нейтрализуйте содержимое чумного котла с помощью пустулезной спинномозговой жидкости.Пустулезная спинномозговая жидкость изготовляется из позвоночника великана. Его можно получить, убивая пустулезных ужасов.', 'Что ж, можно не опасаться еще одного чумного котла в тот час, когда начнется битва. $B$BПолагаю, твой командир будет доволен.', NULL, NULL, NULL, 'Чумной котел нейтрализован', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13298, 'Корпой Оскверненный', '$C, до меня дошли известия о том, что у Врат Смерти появился новый могучий зомби.$B$BМы не можем сидеть сложа руки, когда нам угрожает такой серьезный противник. Любые сведения о нем, какие тебе удастся раздобыть, – лучше, чем ничего.$B$BСтупай в западное караульное помещение у врат и найди это существо. Сразись с ним и отыщи брешь в его защите, которой мы могли бы воспользоваться.', 'Убейте Корпоя Оскверненного из Морд\'ретара по просьбе Тассариана с \"Усмирителя небес\".', 'Отлично, $C!$B$BБыть может, проведя исследования, мы сумеем выяснить, как они изготовляют подобных созданий.', NULL, NULL, NULL, 'Корпой Оскверненный убит', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13299, 'zzOLDПлащ огонька', '', 'это Задание 75-го ур. Награда: Тончайший плащ.', '', NULL, NULL, NULL, 'Идеально ограненный императорский топаз', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13300, 'Рабы саронитовых шахт', 'Наш народ был порабощен и отправлен на саронитовые шахты Имирхейма, оплота врайкулов в центре Ледяной Короны. Король-лич заставляет рабов день и ночь добывать эту проклятую руду. $B$BЯ обещал верховному лорду Фордрингу, что мы поможем этим беднягам выбраться из рудников; именно этим мы и займемся. $B$BУвы, мне было приказано оставаться на этом корабле – как посланнику к Экспедиции Отважных. Может быть, вместо меня рабов спасешь ты, $N?', 'Абсалан Благочестивый, находящийся на борту \"Усмирителя небес\", просит вас освободить 10 рабов из саронитовых шахт.', 'Их что-то сводит с ума? Они слышат голоса?..$B$BГолоса в твоей голове?! $B$BПрошу тебя, дитя мое, очисти свои мысли от скверны, кою ты принес в эту чистую обитель.$B$BМы попытаемся вывести на волю остальных завтра утром, когда ты отдохнешь.', NULL, NULL, NULL, 'Освобождено рабов из саронитовых шахт', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13301, 'Атака пехоты', 'Приветствую тебя, $C.$B$BНаши войска несколько раз пытались взять Имирхейм штурмом, но врайкулы оказались куда более серьезным противником, чем все, кто прежде встречался нам. Не раз наши люди попадали в засады: мы потеряли многих и многих... $B$BЕсли ты $gготов:готова: взяться за это дело и провести моих бойцов к вратам Имирхейма, мы щедро и с радостью вознаградим тебя за помощь. Мы намерены разбить лагерь у ворот и там дождаться подкрепления.', 'Сопроводите кор\'кронские войска к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к северу от Имирхейма к командиру наземных войск Ксутье за наградой.', 'Прими мою благодарность.$B$B Это был не слишком изящный ход, но, с другой стороны, выбирать нам не из чего. Мы попытались атаковать крепость с воздуха, но это также закончилось неудачей. Если мы хотим выжить в Ледяной Короне, нам необходима победа над врайкулами. $B$B Скорее всего, нам снова понадобится помощь. Если это случится, не откажись поддержать нас...', NULL, NULL, NULL, 'Отряды Орды достигли Имирхейма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13302, 'Рабы саронитовых шахт', 'Наш народ был порабощен и отправлен на саронитовые шахты Имирхейма, оплота врайкулов в центре Ледяной Короны. Король-лич заставляет рабов день и ночь добывать эту проклятую руду. $B$BЯ обещал верховному лорду Фордрингу, что мы поможем этим беднягам выбраться из рудников; именно этим мы и займемся. $B$BК сожалению, мне было приказано оставаться на этом корабле – как посланнику к армии Песни Войны . Может быть, вместо меня рабов спасешь ты, $N?', 'Брат Келтан, находящийся на борту \"Молота Оргрима\", просит вас освободить 10 рабов из саронитовых шахт.', 'Их что-то сводит с ума? Они слышат голоса?..$B$BГолоса в твоей голове?! $B$BПрошу тебя, дитя мое, очисти свои мысли от скверны, кою ты принес в эту чистую обитель.$B$BМы попытаемся вывести на волю остальных завтра утром, когда ты отдохнешь.', NULL, NULL, NULL, 'Освобождено рабов из саронитовых шахт', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13304, 'Ремонт в полевых условиях', 'Мы атакуем, и Плеть отступает, $N. Надо воспользоваться моментом и закрепить наш успех.$B$BЭта долина под нами... кстати сказать, стратегически важный объект... открыта для всех. В юго-восточном конце долины Потерянной Надежды мы обнаружили разобранный разрушитель. Мы полагаем, что он в рабочем состоянии, но, безусловно, нуждается в ремонте.$B$BЕсли сумеешь забрать недостающие детали у этих падальщиков из Плети, у тебя должно получиться запустить разрушитель. Даже один разрушитель в рабочем состоянии может нанести ощутимый ущерб пехоте противника.', 'Кольтира Ткач Смерти с \"Молота Оргрима\" хочет, чтобы вы отобрали 5 деталей разрушителя у мусорных упырей в долине Потерянной Надежды и отнесли их к сломанному разрушителю.', 'Этот разрушитель знавал лучшие дни, но основной механизм вроде бы не поврежден. Во всяком случае, он поддается ремонту. Деталей, которые ты принес, должно быть достаточно, чтобы запустить его вновь. Он будет работать... пусть и недолго.', 'Разрушитель сильно пострадал.', NULL, NULL, 'Части разрушителя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13305, 'Все к худшему', 'Зачем тебе эта машина? С Плетью воевать? Машинами Плеть не одолеешь.$B$BТы можешь уничтожить сотни… да что там, даже тысячи воинов Плети! Но саму Плеть тебе не победить.$B$BКогда наиграешься вдоволь, ступай на север. Я встречусь с тобой возле заброшенного военного лагеря. И там я покажу тебе кое-что, чтобы ты $gпонял:поняла:, с чем имеешь дело.', 'Используйте отремонтированный разрушитель, чтобы уничтожить 150 изгнивших вурдалаков, 20 ледотленных волхвов и 2 костяных великана в долине Потерянной Надежды. Выполнив эту задачу, поговорите с Матиасом Нетлером в лагере сопротивления первого легиона.', 'Видишь? Ты можешь убивать их сколько угодно, но на место каждого убитого встанет из земли другой, новый.$B$BТы не понимаешь, с чем сражаешься, $N. Разреши, я тебе покажу.', NULL, NULL, NULL, 'Изгнивший вурдалак убито', 'Ледотленный волхв убито', 'Костяной великан убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13306, 'Строим баррикады!', 'Когда наши войска продвинутся за Алдур\'тар, они окажутся уязвимы для атак с Железного вала и большого ледника под ним.$B$BДля строительства нормальных укреплений у нас нет ни времени, ни материалов, однако мы можем возвести хотя бы баррикады, чтобы защитить наших бойцов от обстрела и сдержать атаки Плети.$B$BОтправляйся с этим набором для строительства баррикад в долину Павших Героев, к западу от Алдур\'тара. Отыщи установленные мной метки и сооруди на их месте баррикады.', 'Постройте 8 баррикад с помощью комплекта для возведения баррикад по просьбе Кольтиры Ткача Смерти, находящегося на борту \"Молота Оргрима\".', '<Кольтира кивает.>$B$BХорошо. Разумеется, баррикады – слабая защита, но все же это лучше, чем ничего. Врата по-прежнему неприступны – если, конечно, командиры Плети знают свое дело. Нужно захватить как можно большую часть прилегающей территории.', NULL, NULL, NULL, 'Построено баррикад', 'Комплект для возведения баррикад', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13307, 'Окровавленные знамена', 'В долине Павших Героев и на леднике Ледяной Короны, к западу от Алдур\'тара, Плеть пытается использовать против нас убитых. Слуги Плети пробудили мертвецов, спавших в долине, и наделили их невероятной силой и яростью. Источниками этой силы являются знамена, которые хранят у себя предводители Плети в районе ледника. Убей этих знаменосцев, и павшие герои, которых они возглавляют, лишатся своей сверхъестественной силы.$B$BИменно тебе выпало избавить нас от этого препятствия и расчистить путь нашим основным силам.', 'Убейте 5 знаменосцев Плети, 5 обратителей Плети и 20 обращенных героев по просьбе Кольтиры Ткача Смерти, который находится на борту \"Молота Оргрима\".', 'Так значит, знаменосцы Плети и их прихвостни истреблены? Отлично! Продолжим укреплять наши позиции…', NULL, NULL, NULL, 'Знаменосец Плети убито', 'Обращенный герой убито', 'Проповедник Плети убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13308, 'Игры разума', '$gГолос существа проникает вам прямо в мозг. Ощущения странные и болезненные.>$B$B<раса:, мне нужна твоя помощь. Как и твои порабощенные друзья, я – жертва алчности имирьяров Короля-лича. Поднявшись из глубин, чтобы выяснить, что за звуки доносятся из пещеры, я был захвачен в плен, и меня заковали в цепи.$B$BПоможешь мне? Ключ от моих кандалов – у бригадира шахтеров. Убей его!$B$B<Вы чувствуете давление в мозгу, словно существо пытается принудить вас выполнить его волю.:', 'Добудьте ключ штейгера от оков темного проповедника Р\'кхема в Саронитовых шахтах.', '<Приближаясь к этому существу, вы ощущаете очередную волну эйфории, смешанной с толикой боли.>$B$BХорошо… хорошо! А чтобы ты не сомневался, что я держу свое слово, сперва ты получишь награду.$B$BА потом, когда ты ее получишь, ты охотно отдашь мне ключ.', 'Сослужи мне эту службу – и получишь щедрую награду.$B$B<Темный проповедник проецирует в ваше сознание умиротворяющие вибрации покоя.>$B$BОсвободи меня! Даю слово, ты не пожалеешь.', NULL, NULL, 'Ключ штейгера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13309, 'Воздушный десант', 'У меня есть несколько ребят, подготовленных к заброске в Имирхейм. Мне нужно, чтобы десант был сброшен, и все прошло благополучно.$B$BУ врайкулов, обороняющих крепость, есть какие-то хитрые автоматические копьеметы. Они лупят по нашим самолетам и не дают им приблизиться. Наши инженеры установили на транспортном самолете подавительную пушку для нейтрализации этих копьеметов – просто дай пару залпов, и дым собьет их с прицела, а заодно и заблокирует механизмы.$B$BВ общем, пали из пушки и позаботься о том, чтобы все мои парни десантировались благополучно.', 'По приказу командира Купа, который расположился на склоне ледника к востоку от Имирхейма, воспользуйтесь подавительной пушкой \"Усмирителя небес\". Обеспечьте прикрытие для транспортного самолета, пока тот будет высаживать десант.', 'Отлично, ты молодец. Побольше бы нам таких воинов! Кстати, приходи завтра – может быть, для тебя будет новое задание.', NULL, NULL, NULL, 'Десант \"Усмирителя небес\" сброшен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13310, 'Воздушный десант', 'Ну, ладно, мелочь пузатая, есть у меня для тебя кое-какая работенка. Должна же быть от тебя какая-то польза, верно?$B$BДесант наших лучших разведчиков готов к заброске в Имирхейм. Тамошние врайкулы вооружены автоматическими копьеметами, которые разносят наш транспорт в клочья, но у нас очень толковые инженеры на \"Молоте Оргрима\", они создали блокиратор огня.$B$BТы будешь нашим канониром. Дашь несколько залпов по их копьеметам, чтобы создать им плохую видимость и заблокировать их механизмы. Твоя задача: сделать так, чтобы десант был сброшен благополучно, и чтобы наш транспортный аппарат вернулся на базу в целости и сохранности.', 'Командир наземных войск Ксутья на краю ледника возле Имирхейма приказал вам использовать кор\'кронскую заградительную пушку, чтобы обеспечить прикрытие для кор\'кронского транспортника, так чтобы десант был сброшен, а транспортный самолет остался целым.', 'Выходит, ты хоть на что-то годишься. Хвалю. Молодец.', NULL, NULL, NULL, 'Десант кор\'крона сброшен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13311, 'Карты Новолуния: колода Демонов', 'Теперь, когда вы собрали все карты колоды Демонов, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$B$BВы чувствуете, что с помощью этой карты можно кого-то призвать.', 'Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Демонов.', 'Знай же, что карты таро пользуются большой популярностью на Ярмарке Новолуния, так что если тебе удастся собрать еще одну колоду – не стесняйся, обращайся к нам. Среди нас много успешных торговцев, так что без награды ты не останешься.', 'Ты собрала колоду Демонов! Поздравляю!', NULL, NULL, 'Колода Демонов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13312, 'Железный вал', 'Железный вал возвышается над долиной Павших Героев, к западу от Алдур\'тара. Он окружает почти всю долину. Мы не сможем продвинуться дальше, пока не возьмем этот вал. Но там засел Гримкор Злобный и его приверженцы Культа Проклятых.$B$BЕсли ты одолеешь Гримкора, наши войска смогут взять эти стены. Возьми эту руну искажения. Ее мощь, высвобожденная в непосредственной близости от сферы Гримкора, в конце вала, обязательно привлечет внимание некроманта.', 'Убейте Гримкора Злобного и возвращайтесь к Кольтире Ткачу Смерти на \"Молот Оргрима\".', 'Итак, Гримкор пал от твоей руки? Отличная работа. Теперь, когда он не стоит у нас на пути, наши шансы на то, чтобы взять и удержать вал, изрядно повысились.', NULL, NULL, NULL, 'Гримкор Злобный убито', 'Руна искажения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13313, 'Ослепить соглядатаев!', 'Альянсу каким-то образом удалось запустить целую эскадрилью разведывательных машин, и теперь они кружат над долиной Павших Героев и ледником Ледяной Короны, к западу от Алдур\'тара.$B$BМы такого допустить не можем! Главный инженер Меднопал снабдил меня превосходным оружием как раз для такого случая: он называет эту штуку ЗГ-3. Он уверяет, что эта штука способна сбивать ветролеты Альянса с одного выстрела! Ступай и испытай ее в деле.', 'С помощью ЗГ-3 уничтожьте 6 разведывательных истребителей \"Усмирителя небес\", потом вернитесь к покорителю небес Корму Черному Шраму на борт \"Молота Оргрима\".', 'Хорошо. Чем меньше крыс из Альянса стоит у нас на пути, тем лучше. Мы им покажем, что такое настоящие воины!', NULL, NULL, NULL, 'Разведывательные истребители \"Усмирителя Небес\" уничтожены', 'ЗГ-3', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13314, 'Перехватить донесения', 'Орда что-то затевает, и мне это не нравится! После того, что они вытворяли на Прорванном фронте, стало ясно, что они способны на все – и нам следует их остановить.$B$BНебо над ледником Ледяной Короны, к западу от Алдур\'тара и Железного вала, кишит их разведчиками. Всадники на дракондорах переносят депеши и донесения. Используй этот стреломет, когда понадобится убить разведчиков с \"Молота Оргрима\". Пожалуй, будет лучше, если ты тоже будешь летать...', 'Заберите 6 донесений для \"Молота Оргрима\" у разведчиков с \"Молота Оргрима\" и отдайте их старшему капитану Джастину Бартлетту на борту \"Усмирителя небес\".', 'Хорошо все-таки иметь под рукой такую компетентную исполнительницу! Будь у нас целое войско таких, как ты, $N, мы бы показали Орде, на что мы способны! Эти перехваченные депеши помогут нам одержать верх в предстоящей битве. Эти мерзавцы у нас еще попляшут!', 'Удалось ли тебе перехватить их донесения?', NULL, NULL, 'Донесение для \"Молота Оргрима\"', 'Стреломет', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13315, 'Предварительная разведка', 'Дело движется. Мы разработали тактику, которая должна помочь нам взять Врата Смерти под контроль. Конечно, потери будут, и немалые, но в конце концов мы должны победить – особенно если Орда, с которой ты так жаждешь сразиться, нам не помешает.$B$BСледующей нашей целью станут Врата Горя. Слетай туда, ознакомься с местностью, посмотри, с чем предстоит иметь дело.$B$BА когда вернешься, я дам тебе новое поручение.', 'Слетайте к Вратам Горя и ознакомьтесь с южной, центральной, северной и северо-западной частями Врат по просьбе Тассариана с \"Усмирителя небес\".', 'Отлично, отлично, $C!$B$BТеперь, когда ты своими глазами видел, с чем приходится иметь дело, пора браться за работу…', NULL, NULL, NULL, 'Посетите южную часть Алдур\'тара', 'Посетите центральную часть Алдур\'тара', 'Посетите северную часть Алдур\'тара', 'Посетите северо-западную часть Алдур\'тара');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13316, 'Стражи Корп\'ретара', 'Корп\'ретар, именуемый также Вратами Ужаса, – это последнее препятствие между нами и цитаделью Ледяной Короны. Он расположен к югу от Железного вала, за ледником и Пожарищем. Переход будет долгим и трудным. Пока мы туда доберемся, наши солдаты выбьются из сил.$B$BНужно ослабить вражескую оборону, иначе мы все поляжем под этими стенами.$B$BУкрепления обороняют самые яростные и преданные солдаты Короля-лича. Сделай все возможное, чтобы их уничтожить – будем надеяться, этого будет достаточно.', 'Убейте 5 провозвестников ужаса и 5 стражей Корп\'ретара по приказу Кольтиры Ткача Смерти с \"Молота Оргрима\".', 'Надеюсь, твой успех в Корп\'ретаре принесет нам удачу и станет залогом победы в будущей битве. Король-лич не будет спокойно сидеть и смотреть, как мы подступаем к воротам его твердыни.', NULL, NULL, NULL, 'Провозвестник ужаса убито', 'Страж Корп\'ретара убито', 'Рекомендуемое количество игроков: 5', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13318, 'Перетащить и опустить', 'Так значит, Врата Горя обороняет Культ Проклятых? Неудивительно.$B$BЛадно, пора позабавиться. Ты говоришь, у южной части Врат тренируют новых сектантов? У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$B$BЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$B$BУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй их против поработителей.', 'Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Тассариана, который находится на борту \"Усмирителя небес\".', 'Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает…', NULL, NULL, NULL, 'Найдите и уничтожьте темных поработителей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13319, 'Вершина иерархии', 'Судя по твоему докладу и по тому, что мне известно о культе, в каждом их лагере имеется надзиратель, который всем и заправляет.$B$BРазумеется, уничтожение всех этих предводителей остановит сектантов лишь ненадолго, но все-таки на время выведет их из игры. На данный момент это вполне актуальная задача.$B$BОтыщи этих надзирателей и расправься с ними. Потом возвращайся ко мне.', 'Отправляйтесь в Алдур\'тар и убейте надзирателя Фэдриса, надзирателя Саврина, надзирателя Веража и надзирателя Джакона про просьбе Тассариана с \"Усмирителя небес\".', 'Отличная работа, $R. Но почивать на лаврах рановато! На место этих надзирателей скоро встанут новые…', NULL, NULL, NULL, 'Надзиратель Фэдрис убит', 'Надзиратель Джакон убит', 'Надзиратель Вераж убит', 'Надзиратель Саврин убит');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13320, 'Невоспроизводимый компонент', 'Я даже отсюда ощущаю запах, исходящий от их котлов – но нет, это не чумное зелье... $B$BПриверженцев культа заставляют пить смесь, лишающую их воли и навеки обращающую в рабов Короля-лича. $B$BНекоторые говорят, что одним из ингредиентов этого зелья является душа подвергшегося пыткам и безжалостно убитого существа, однако мне никогда не удавалось заполучить подобный компонент... $B$BНаполни эту флягу образцами зелья из трех котлов, находящихся к северо-западу от ворот, и отнеси главному инженеру Болтоключу.', 'Тассариан с корабля \"Усмиритель небес\" хочет, чтобы вы наполнили трехчастную флягу изо всех 3 котлов служителей культа в Алдур\'таре, а затем отнесли ее главному инженеру Болтоключу.', '<Болтоключ выливает содержимое фляги в свой анализатор жидкостей.>$B$BА здесь мы имеем неудачную попытку получить гомогенную жидкость...', 'Ну-ка, $C, что тут у тебя?', NULL, NULL, 'Взят синий образец', 'Взят зеленый образец', 'Взят темный образец', 'Секционная фляга (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13321, 'Все переиграть', 'Это должно подействовать!$B$BЗначит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безу$Nю похлебку? Ничего, мы им подсобим!$B$BНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено… ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.$B$BКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$B$BПоглядим, как им понравится собственное лекарство!', 'Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Болтоключа с \"Усмирителя небес\".', 'Ур-ра!$B$BТо-то же! Будут знать!', NULL, NULL, NULL, 'Корчащаяся масса уничтожена', 'Разбавленное снадобье сектантов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13322, 'Все переиграть', 'Значит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безу$Nю похлебку? Ничего, мы им подсобим!$B$BНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено… ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.$B$BКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$B$BПоглядим, как им понравится собственное лекарство!', 'Выпейте разбавленное снадобье сектантов по просьбе главного инженера Болтоключа с \"Усмирителя небес\", затем убивайте любых сектантов, каких встретите в Алдур\'таре, и забирайте их оскверненные сущности. После смешайте 10 сущностей, чтобы получить корчащуюся массу, и бросьте ее в любой из котлов сектантов.', 'Ур-ра!$B$BТо-то же! Будут знать!', NULL, NULL, NULL, 'Корчащаяся масса уничтожена', 'Разбавленное снадобье сектантов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13323, 'Перетащить и опустить', 'Что-то эти посвященные опять расплодились! Ты знаешь, что следует делать…$B$BУ южной части врат тренируют новых сектантов. У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$B$BЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$B$BУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй сферы против поработителей.', 'Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Тассариана, который находится на борту \"Усмирителя небес\".', 'Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает…', NULL, NULL, NULL, 'Найдите и уничтожьте темных поработителей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13324, 'Колода карт Новолуния: Призмы', 'Как только вы собираете вместе восемь карт из колоды Призм, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите колоду Призм на ярмарку Новолуния.', 'Итак, ты собрал колоду Призм. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты Призм! Поздравляю!', NULL, NULL, 'Колода Призм (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13325, 'Колода карт Новолуния: Хаос', 'Как только вы собираете вместе восемь карт из колоды Хаоса, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите колоду Хаоса на ярмарку Новолуния.', 'Итак, ты собрал колоду Хаоса. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты Хаоса! Поздравляю!', NULL, NULL, 'Колода Хаоса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13326, 'Колода карт Новолуния: Аристократы', 'Как только вы собираете вместе восемь карт из колоды Аристократов, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите колоду Аристократов на ярмарку Новолуния.', 'Итак, ты собрал колоду Аристократов. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты Аристократов! Поздравляю!', NULL, NULL, 'Колода Аристократов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13327, 'Колода карт Новолуния: Нежить', 'Как только вы собираете вместе восемь карт из колоды Нежити, девятая карта с такой же \"рубашкой\" появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...', 'Принесите колоду Нежити на ярмарку Новолуния.', 'Итак, ты собрал колоду Нежити. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.', 'Ты собрал все карты Нежити! Поздравляю!', NULL, NULL, 'Колода Нежити (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13328, 'Вдребезги', 'Слуги Короля-лича установили три кристалла: Ужаса, Отчаяния и Страдания, – на крепостных стенах Корп\'ретара. Если наши войска подойдут к стенам Корп\'ретара, король обрушит на нас мощь этого грозного оружия.$B$BЗаработав на полную мощность, кристаллы наполнят сознание наших бойцов болью и страхом. И тогда Плеть играючи расправится с ними.$B$BНайди эти кристаллы, разбей их и принеси мне их осколки. Нельзя допустить, чтобы Король-лич применил против нас это оружие!', 'Принесите Кольтире Ткачу Смерти на \"Молот Оргрима\" осколки кристалла Ужаса, кристалла Отчаяния и кристалла Страдания.', '<Кольтира забирает у вас осколки кристаллов и говорит тихим голосом.>$B$BЯ их помню…$B$BЭто оружие просто скосило бы наших людей. Ты сделал большое дело, устранив эту угрозу.', 'Тебе удалось разбить новое оружие Короля-лича?', NULL, NULL, 'Осколок Кристалла Ужаса', 'Осколок Кристалла Отчаяния', 'Осколок Кристалла Страдания', 'Рекомендуемое количество игроков: 5');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13329, 'Пред Вратами Ужаса', 'Войско Короля-лича выстроилось для защиты цитадели у Пожарища близ Корп\'ретара, южнее Железного вала.$B$BЛегион скелетов-разорителей под командованием рыцарей смерти перекрыл дорогу. Даже если мы уничтожим эту нежить, боюсь, Плеть просто оживит их и снова нашлет на нас.$B$BУ меня есть план, как этому помешать, но я не знаю, сработает он или нет... Возьми этот раствор и попробуй полить им останки скелетов-разорителей, чтобы растворить их.', 'Растворите останки 6 скелетов-разорителей летучей кислотой по заданию Кольтиры Ткача Смерти с \"Молота Оргрима\".', '<Кольтира слушает ваш рассказ.>$B$BПрекрасно. Я прикажу инженерам приготовить как можно больше этой кислоты, прежде чем мы начнем наступление на Корп\'ретар.', 'Ты сделал то, о чем я тебя просил?', NULL, NULL, 'Кости скелетов-разорителей растворены', 'Летучая кислота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13330, 'Кровь избранных', 'Врайкулы, сумевшие добиться благоволения Короля-лича, называют себя имирьярами. Они живут в городе, расположенном в центре Ледяной Короны. Прежде чем атаковать цитадель Ледяной Короны, нам нужно как следует подготовиться. Прежде всего, необходимо извести так называемых \"избранных\" Короля-лича.$B$BСтупай в их город, Имирхейм, и истреби их в их собственном гнезде. Пусть никто не сомневается, чье войско сильнее!', 'Убейте 20 врайкулов в Имирхейме по просьбе завоевателя Давоса Рихта с \"Молота Оргрима\".', 'Ага, значит, не так уж они непобедимы! Король-лич получит то, что ему причитается.', NULL, NULL, NULL, 'Убито врайкулов Имирхейма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13331, 'Ослепление Альянса', 'Альянсовцы, конечно, упрямы, этого у них не отнимешь, однако для того, чтобы нас остановить, потребуется нечто большее! Вот, возьми с собой ЗГ-3 и снова перестреляй бойцов-разведчиков с \"Усмирителя небес\"!$B$BВряд ли нам удастся вбить в их твердолобые башки побольше ума, но, по крайней мере, мы можем постараться: боеприпасов у нас хватит! Ты увидишь их бойцов, они кружат над долиной Павших героев, к западу от Алдур\'тара. Не возвращайся, пока не разгромишь их!', 'С помощью ЗГ-3 уничтожьте 6 разведывательных истребителей \"Усмирителя небес\", потом вернитесь к покорителю небес Корму Черному Шраму на борт \"Молота Оргрима\".', 'Отличная работа, молодец! Теперь Орда обеспечила себе превосходство, по крайней мере, до тех пор, пока эти альянсовские хмыри не решатся сунуться сюда снова.', NULL, NULL, NULL, 'Разведывательные истребители \"Усмирителя Небес\" уничтожены', 'ЗГ-3', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13332, 'Строим баррикады!', 'Когда наши войска продвинутся за Алдур\'тар, они окажутся уязвимы для атак с Железного вала и большого ледника под ним.$B$BДля строительства нормальных укреплений у нас нет ни времени, ни материалов, однако мы можем возвести хотя бы баррикады, чтобы защитить наших бойцов от обстрела и сдержать атаки Плети.$B$BОтправляйся с этим набором для строительства баррикад в долину Павших Героев, к западу от Алдур\'тара. Отыщи установленные мной метки и сооруди на их месте баррикады.', 'Постройте 8 баррикад с помощью комплекта для возведения баррикад по просьбе Тассариана с \"Усмирителя небес\".', '<Тассариан кивает.>$B$BХорошо. Конечно, баррикады – слабая защита, но все же это лучше, чем ничего. Но врата по-прежнему неприступны – разумеется, если командиры Плети знают свое дело. Нужно захватить как можно большую часть прилегающей территории.', NULL, NULL, NULL, 'Построено баррикад', 'Комплект для возведения баррикад', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13333, 'Перехват донесений', 'Несмотря на все наши усилия, Орда продолжает засылать разведчиков на территорию ледника Ледяной Короны, к западу от Железного вала и Алдур\'тара.$B$BНельзя допустить, чтобы ордынцы стали хозяином положения благодаря этой разведывательной операции. Так что бери ружье, стреляющее дротиками, и перебей всех разведичков с \"Молота Оргрима\", не щади никого! Все донесения, которые будут при них, неси мне.$B$BОрда хорошо потрудилась, а мы, так сказать, пожнем все плоды их трудов. Главное – вовремя подсуетиться.', 'Заберите 6 донесений для \"Молота Оргрима\" у разведчиков с \"Молота Оргрима\", и отдайте их старшему капитану Джастину Бартлетту на борту \"Усмирителя небес\".', '<Старший капитан забирает у вас донесения.>$B$BДа, это именно то, что нужно. Даже Орде хватает ума понять, что на армию Плети нельзя наступать вслепую. Теперь у нас есть информация, и мы сможем как следует подготовиться.', 'Тебе удалось перехватить донесения их разведки?', NULL, NULL, 'Донесение для \"Молота Оргрима\"', 'Стреломет', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13334, 'Окровавленные знамена', 'В долине Павших Героев и на леднике Ледяной Короны, к западу от Алдур\'тара, Плеть пытается использовать против нас убитых. Слуги Плети пробудили мертвецов, спавших в долине, и наделили их невероятной силой и яростью. Источниками этой силы являются знамена, которые хранят у себя предводители Плети в районе ледника. Убей этих знаменосцев, и павшие герои, которых они возглавляют, лишатся своей сверхъестественной силы.$B$BИменно тебе выпало избавить нас от этого препятствия и расчистить путь нашим основным силам.', 'Убейте 5 знаменосцев Плети, 5 обратителей Плети и 20 обращенных героев по просьбе Тассариана, который находится на борту \"Усмирителя небес\".', 'Так значит, знаменосцы Плети и их прихвостни истреблены? Отлично! Продолжим укреплять наши позиции…', NULL, NULL, NULL, 'Знаменосец Плети убито', 'Обращенный герой убито', 'Проповедник Плети убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13335, 'Пред Вратами Ужаса', 'Войско Короля-лича выстроилось для защиты цитадели у Пожарища близ Корп\'ретара, южнее Железного вала.$B$BЛегион скелетов-разорителей под командованием рыцарей смерти перекрыл дорогу. Даже если мы уничтожим эту нежить, боюсь, Плеть просто их восстановит и снова нашлет на нас.$B$BУ меня есть план, как этому помешать, но я не знаю, сработает он или нет... Возьми этот раствор и попробуй полить им останки скелетов-разорителей, чтобы растворить их.', 'Растворите трупы 6 скелетов-разорителей летучей кислотой по заданию Тассариана с \"Усмирителя небес\".', '<Тассариан слушает ваш рассказ об успешном испытании состава.>$B$BТо есть кислота их растворяет? Отлично. Она очень нам пригодится, когда начнется массированное наступление на войско нежити.', NULL, NULL, NULL, 'Кости скелетов-разорителей растворены', 'Летучая кислота', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13336, 'Кровь избранных', 'Врайкулы, сумевшие добиться благоволения Короля-лича, называют себя имирьярами. Они живут в городе, расположенном в центре Ледяной Короны. Прежде чем атаковать цитадель Ледяной Короны, нам нужно как следует подготовиться. Прежде всего, необходимо извести так называемых \"избранных\" Короля-лича.$B$BСтупай в их город, Имирхейм, и истреби имирьяров в их собственном гнезде. Пусть все знают, чье войско сильнее!', 'Убейте 20 врайкулов в Имирхейме по просьбе рыцаря-капитана Дроша с \"Усмирителя небес\".', 'Король-предатель умрет. Вне всяких сомнений.', NULL, NULL, NULL, 'Убито врайкулов Имирхейма', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13337, 'Железный вал', 'Железный вал возвышается над долиной Павших Героев, к западу от Алдур\'тара. Он окружает почти всю долину. Мы не сможем продвинуться дальше, пока не возьмем этот вал. Но там засел Гримкор Злобный и его приверженцы Культа Проклятых.$B$BЕсли ты одолеешь Гримкора, наши войска смогут взять эти стены. Возьми эту руну искажения. Ее мощь, высвобожденная в непосредственной близости от сферы Гримкора, в конце вала, обязательно привлечет внимание некроманта.', 'Убейте Гримкора Злобного и возвращайтесь к Тассариану на \"Усмиритель небес\".', 'Итак, Гримкор пал от твоей руки? Отличная работа. Теперь, когда он не стоит у нас на пути, наши шансы на то, чтобы взять и удержать вал, изрядно повысились.', NULL, NULL, NULL, 'Гримкор Злобный убито', 'Руна искажения', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13338, 'Стражи Корп\'ретара', 'Корп\'ретар, именуемый также Вратами Ужаса, – это последнее препятствие между нами и цитаделью Ледяной Короны. Он расположен к югу от Железного вала, за ледником и Пожарищем. Переход будет долгим и трудным. Пока мы туда доберемся, наши солдаты выбьются из сил.$B$BНужно ослабить вражескую оборону, иначе мы все поляжем под этими стенами.$B$BУкрепления обороняют самые яростные и преданные солдаты Короля-лича. Сделай все возможное, чтобы их уничтожить – будем надеяться, этого будет достаточно.', 'Убейте 5 провозвестников ужаса и 5 стражей Корп\'ретара по приказу Тассариана с \"Усмирителя небес\".', 'Надеюсь, твой успех в Корп\'ретаре принесет нам удачу и станет залогом победы в будущей битве. Король-лич не будет спокойно сидеть и смотреть, как мы подступаем к воротам его твердыни.', NULL, NULL, NULL, 'Провозвестник ужаса убито', 'Страж Корп\'ретара убито', 'Рекомендуемое количество игроков: 5', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13339, 'Вдребезги', 'Слуги Короля-лича установили три кристалла: Ужаса, Отчаяния и Страдания, – на крепостных стенах Корп\'ретара. Если наши войска подойдут к стенам Корп\'ретара, король обрушит на нас мощь этого грозного оружия.$B$BЗаработав на полную мощность, кристаллы наполнят сознание наших бойцов болью и страхом. И тогда Плеть играючи расправится с ними.$B$BНайди эти кристаллы, разбей их и принеси мне их осколки. Нельзя допустить, чтобы Король-лич применил против нас это оружие!', 'Принесите Тассариану на \"Усмиритель небес\" осколки кристалла Ужаса, кристалла Отчаяния и кристалла Страдания.', '<Тассариан забирает у вас осколки кристаллов и говорит тихим голосом.>$B$BЯ их помню…$B$BЭто оружие просто скосило бы наших людей. Ты сделал большое дело, устранив эту угрозу.', 'Тебе удалось разбить новое оружие Короля-лича?', NULL, NULL, 'Осколок Кристалла Ужаса', 'Осколок Кристалла Отчаяния', 'Осколок Кристалла Страдания', 'Рекомендуемое количество игроков: 5');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13340, 'Помощь в нападении', 'Нам нужны бойцы для нападения на Имирхейм!$B$BЛюбой воин, у которого есть хоть капля мозгов, скажет тебе, что врайкулы – отчаянные бойцы и голыми руками их не возьмешь. А уж имирьяры – тем более! Понятно, отчего Король-лич счел достойными именно их.$B$BРаспоряжение по осаде отдает командир наземных войск Ксутья. Сам город находится в центре Ледяной Короны. Войска Ксутьи стоят на краю ледника, к северу от города.', 'Явитесь к командиру наземных войск Ксутье на краю ледника к северу от Имирхейма.', 'А, новое мясо для мясорубки! Добро пожаловать в ад, солдат.$B$BМои бойцы атакуют ворота с этой позиции, а кроме того, у нас есть несколько транспортных самолетов и мы забрасываем в город диверсантов. Лишние воины ни там, ни там не помешают. У меня такое ощущение, что наша осада затянется надолго.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13341, 'Помощь в нападении', 'Нам нужны бойцы для нападения на Имирхейм!$B$BЛюбой воин, у которого есть хоть капля мозгов, скажет тебе, что врайкулы – отчаянные бойцы, и голыми руками их не возьмешь. А уж имирьяры – тем более! Понятно, отчего Король-лич счел достойными именно их.$B$BОсадой командует военачальник Куп. Сам город находится в центре Ледяной Короны. Войска Купа стоят на краю ледника, к северу от города.', 'Явитесь к военачальнику Купу на краю ледника к северу от Имирхейма.', 'Добро пожаловать в ад, солдат.$B$BМои бойцы атакуют ворота с этой позиции, а кроме того, у нас есть несколько транспортных самолетов и мы забрасываем в город диверсантов. Лишние воины ни там, ни там не помешают. У меня такое ощущение, что наша осада затянется надолго.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13342, 'Ненастоящий шпион', 'Что ж, $gдружище:барышня:, настало время нам обзавестись шпионом.$B$BНет, не настоящим шпионом, но для наших целей он подойдет.$B$BВ северной части Алдур\'тара сектанты, призыватели Бездны, порабощают демонов. Используй этот жезл, чтобы вытянуть те$Nю сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нашего маленького шпиона.$B$BПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.', 'Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Тассариана, который находится на борту \"Усмирителя небес\".', 'Отличная работа, $C!$B$BНаш посланец уже успел раздобыть кое-какую ценную информацию.', NULL, NULL, NULL, 'Призвано темных посланников', 'Жезл вытягивания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13343, 'Тайна бесконечности, мания преследования', 'Ах, снова ты! Или мы только что беседовали?$B$B<Хроми размышляет над причудами времени.>$B$BКак бы то ни было, за тобой охотятся драконы Бесконечности! Точнее, не совсем за тобой, а за той прошлой версией тебя, что обороняла песочные часы Вечности. Помнишь, да?$B$BАга, значит, тогда это $gбыл:была: все же ты, и теперь это снова ты. Постой, это все неважно! Важно то, что тебе следует вернуться в Бронзовое святилище драконов, чтобы защищать себя и песочные часы от атак драконов Бесконечности! Иначе ты исчезнешь из истории.', 'Хроми на вершине храма Драконьего Покоя просит вас снова отправиться в Бронзовое святилище драконов.Оказавшись в святилище, установите песочные часы Вечности и помогите Себе-в-Прошлом защитить их от атак драконов Бесконечности.', '', NULL, NULL, NULL, 'Песочные часы Вечности спасены от драконов Бесконечности.', 'Песочные часы вечности', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13344, 'Ненастоящий шпион', 'Сектанты отловили последнего отправленного тобой посланца, $r.$B$BКонечно, он успел доставить нам немало ценных сведений, и все же нам необходимо продолжать следить за каждым их шагом.$B$BИспользуй этот жезл, чтобы вытянуть те$Nю сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать еще одного шпиона.$B$BПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.', 'Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Тассариана, который находится на борту \"Усмирителя небес\".', 'Отлично, друг мой!$B$BПосланец уже продолжает работу…', NULL, NULL, NULL, 'Призвано темных посланников', 'Жезл вытягивания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13345, 'Слишком мало сведений', 'Культ Проклятых известен тем, что вечно строит грандиозные планы, которые никогда не исполняются. Но на этот раз явно вышло иначе…$B$BБыть может, это близкое соседство с Королем-личом на них так повлияло. Как бы то ни было, они держатся увереннее, чем обычно. Необходимо выяснить, что питает их отвагу, а затем найти способ усмирить их!$B$BПодозреваю, что все дело в их ученых. Узнай, что они затевают, и доложи мне во всех подробностях.', 'Отберите у ученых культа в Алдур\'таре 3 страницы Исследований Культа Проклятых и используйте их, чтобы составить доклад о Культе Проклятых по приказу Тассариана с \"Усмирителя небес\".', 'Да, это весьма тревожные известия…', 'Ну что, $C, удалось ли выяснить, чем заняты их ученые?', NULL, NULL, 'Доклад о Культе Проклятых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13346, 'Пусть злодеи не ведают покоя', 'Эти глупцы и впрямь обнаружили нечто, что может представлять серьезную угрозу для наших планов!$B$BПредводитель их секты, Алумет, совершил ритуальное самоубийство, и теперь его прихвостни передают его душе свою силу...$B$BЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$B$BСобери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$B$BТоропись, $r! Уничтожь его, пока он не стал слишком могуществен!', 'Повергните Алумета Восходящего в Алдур\'таре по просьбе Тассариана, который находится на борту \"Усмирителя небес\".', 'Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…', NULL, NULL, NULL, 'Алумет Перерожденный побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13347, 'Восставший из праха', 'Судьба от рождения начертана огненными письменами в наших душах. Падение Болвара – это трагедия, но оно было неизбежно. $B$BВсе, что ты можешь сделать ныне, $N – это почтить своего героя. Найди на поле боя щит Болвара и возврати его королю. Когда будешь отдавать шит Вариану, скажи ему так: \"Не все потеряно. Из праха падшего восстанет сила, которая объединит народы и очистит этот мир от скверны.\"$B$BОн не должен терять веру. Теперь иди, $N. Твоему народу нужен герой. Им $gнужен:нужна: ты.', 'Найдите щит Фордрагона на поле боя при Ангратаре, Вратах Гнева. Отнесите щит в крепость Штормграда и вручите королю Вариану Ринну.', 'Королева драконов права, $N. Наш бой еще не проигран. Я стану той силой, которая восстанет из праха; я очищу этот мир от скверны, которую несет Орда. Смерть наших сестер и братьев не будет напрасной!', '<Король Ринн смахивает слезу.> $B$B<Король Ринн кивает.>$B$BЭто моя вина...', NULL, NULL, 'Щит Фордрагона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13348, 'Тщета', 'Теперь понимаешь? Посылая своих бойцов на войну с полчищами принца, вы только пополняете их ряды.$B$BВпрочем, я и не рассчитывал, что ты поймешь… думаю, с тобой будет то же, что и с другими. Возвращайся лучше к тому, кто тебя прислал. Думаю, о тебе тревожатся...', 'Возвращайтесь к Кольтире Ткачу Смерти на борт \"Молота Оргрима\".', 'А, вот и ты! Неплохая работа. Вся долина усеяна убитыми…$B$BС тобой все в порядке? У тебя такой вид, словно ты увидел привидение.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13349, 'Колыбель ледяных драконов', 'Мы должны продолжать наступление. Нельзя давать передышку армии Плети.$B$BНа востоке, сразу за долиной Потерянной Надежды, находится Каньон Гибели Синдрагосы. Там всем заправляет Культ Проклятых под жестким контролем нежити из врайкулов, прислужников Короля-лича.$B$BЭто место великой силы – возможно, древнее кладбище синих драконов. Там из праха синих драконов создают вселяющих ужас ледяных драконов.$B$BЕсли мы нанесем удар по Каньону Гибели Синдрагосы, у наших врагов сильно поубавится ледяных змеев. Так что, $N? Возьмешься за это дело?', 'Отправляйтесь в Каньон Гибели Синдрагосы и убейте 5 воскресителей драконов, 8 сектантов-осквернителей и 3 врайкулов-некролордов по просьбе Кольтиры Ткача Смерти с \"Молота Оргрима\".', 'Ты замечательно справился, $N. Кстати, ты бы пошел отдохнул, а то что-то ты бледненький.', NULL, NULL, NULL, 'Воскреситель драконов убито', 'Сектант-осквернитель убито', 'Врайкул-некролорд убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13350, 'Пусть злодеи не ведают покоя', 'А, это Алумет… Снова набирает силу. Я это чую. Снова его прихвостни передают магию его душе.$B$BЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$B$BВозвращайся в его зал в северной части Алдур\'тара. Собери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$B$BТоропись, $r! Уничтожь его, пока он не стал слишком могуществен!', 'Повергните Алумета Восходящего в Алдур\'таре по просьбе Тассариана, который находится на борту \"Усмирителя небес\".', 'Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…', NULL, NULL, NULL, 'Алумет Перерожденный побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13351, 'Предварительная разведка', 'Дело движется. Мы разработали тактику, которая должна помочь нам взять Врата Смерти под контроль. Конечно, потери будут, и немалые, но в конце концов мы должны победить – особенно если Альянс нам не помешает.$B$BСледующей нашей целью станет Алдур\'тар, Врата Горя. Слетай туда, ознакомься с местностью, посмотри, с чем предстоит иметь дело.$B$BА когда вернешься, я дам тебе новое поручение.', 'Слетайте к Вратам Горя и ознакомьтесь с южной, центральной, северной и северо-западной частями Врат по просьбе Кольтиры с \"Молота Оргрима\".', 'Отлично, отлично, $C!$B$BТеперь, когда ты своими глазами видел, с чем приходится иметь дело, пора браться за работу…', NULL, NULL, NULL, 'Посетите южную часть Алдур\'тара', 'Посетите центральную часть Алдур\'тара', 'Посетите северную часть Алдур\'тара', 'Посетите северо-западную часть Алдур\'тара');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13352, 'Перетащить и опустить', 'Так значит, Врата Горя обороняет Культ Проклятых? Неудивительно.$B$BЛадно, пора позабавиться. Ты говоришь, у южной части Врат тренируют новых сектантов? У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$B$BЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$B$BУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй их против поработителей.', 'Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Кольтиры, который находится на борту \"Молота Оргрима\".', 'Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает…', NULL, NULL, NULL, 'Найдите и уничтожьте темных поработителей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13353, 'Перетащить и опустить', 'Что-то эти посвященные опять расплодились! Ты знаешь, что следует делать…$B$BУ южной части врат тренируют новых сектантов. У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$B$BЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$B$BУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй сферы против поработителей.', 'Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Кольтиры, который находится на борту \"Молота Оргрима\".', 'Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает…', NULL, NULL, NULL, 'Найдите и уничтожьте темных поработителей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13354, 'Вершина иерархии', 'Судя по твоему докладу и по тому, что мне известно о культе, в каждом их лагере имеется надзиратель, который всем и заправляет.$B$BРазумеется, уничтожение всех этих предводителей остановит сектантов лишь ненадолго, но все-таки на время выведет их из игры. На данный момент это вполне актуальная задача.$B$BОтыщи этих надзирателей и расправься с ними. Потом возвращайся ко мне.', 'Отправляйтесь в Алдур\'тар и убейте надзирателя Фэдриса, надзирателя Саврина, надзирателя Веража и надзирателя Джакона про просьбе Кольтиры с \"Молота Оргрима\".', 'Отличная работа, $R. Но почивать на лаврах рановато! На место этих надзирателей скоро встанут новые…', NULL, NULL, NULL, 'Надзиратель Фэдрис убит', 'Надзиратель Джакон убит', 'Надзиратель Вераж убит', 'Надзиратель Саврин убит');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13355, 'Невоспроизводимый компонент', 'Я даже отсюда ощущаю запах, исходящий от их котлов – но нет, это не чумное зелье... $B$BПриверженцев культа заставляют пить смесь, лишающую их воли и навеки обращающую в рабов Короля-лича. $B$BНекоторые говорят, что одним из ингредиентов этого зелья является душа подвергшегося пыткам и безжалостно убитого существа, однако мне никогда не удавалось заполучить подобный компонент...$B$BНаполни эту флягу образцами зелья из трех котлов, находящихся к северо-западу от ворот, и отнеси главному инженеру Меднопалу.', 'Кольтира с корабля \"Молот Оргрима\" хочет, чтобы вы наполнили секционную флягу изо всех 3 котлов служителей культа в Алдур\'таре, а затем отнесли ее главному инженеру Меднопалу.', '<Меднопал выливает содержимое фляги в свой анализатор жидкостей.>$B$BО! Я знаю нужное вещество!', 'Ну-ка, $R, что тут у тебя?', NULL, NULL, 'Взят синий образец', 'Взят зеленый образец', 'Взят темный образец', 'Секционная фляга (Прилагается)');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13356, 'Все переиграть', 'Это должно подействовать!$B$BЗначит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безу$Nю похлебку? Ничего, мы им подсобим!$B$BНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено… ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности оскверненного духа поверженных сектантов.$B$BКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$B$BПоглядим, как им понравится собственное лекарство!', 'Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Меднопала с \"Молота Оргрима\".', 'Ур-ра!$B$BТо-то же! Будут знать!', NULL, NULL, NULL, 'Корчащаяся масса уничтожена', 'Разбавленное снадобье сектантов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13357, 'Все переиграть', 'Значит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безу$Nю похлебку? Ничего, мы им подсобим!$B$BНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено… ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.$B$BКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$B$BПоглядим, как им понравится собственное лекарство!', 'Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Меднопала с \"Молота Оргрима\".', 'Ур-ра!$B$BТо-то же! Будут знать!', NULL, NULL, NULL, 'Корчащаяся масса уничтожена', 'Разбавленное снадобье сектантов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13358, 'Ненастоящий шпион', 'Что ж, $gдружище:барышня:, настало время нам обзавестись шпионом.$B$BНет, не настоящим шпионом, но для наших целей он подойдет.$B$BВ северной части Алдур\'тара сектанты, призыватели Бездны, порабощают демонов. Используй этот жезл, чтобы вытянуть те$Nю сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нашего маленького шпиона.$B$BПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.', 'Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Кольтиры, который находится на борту \"Молота Оргрима\".', 'Отличная работа, $C!$B$BНаш посланец уже успел раздобыть кое-какую ценную информацию.', NULL, NULL, NULL, 'Призвано темных посланников', 'Жезл вытягивания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13359, 'Место гибели драконов', 'Тут погиб целый выводок синих драконов. И вот теперь слуги принца воскрешают их, одного за другим.$B$BСамого могучего воскресил он сам. Принеси мне пыли костей молодых драконов, и я покажу тебе, как он это сделал.', 'Добудьте в Каньоне Гибели Синдрагосы 6 горстей пыли из костей дракончиков по приказу Матиаса Нетлера.', 'Даже могучие драконы были вынуждены подчиниться его зову. Неужели простой смертный вроде тебя может надеяться устоять?', 'Где пыль, Анкап?', NULL, NULL, 'Пыль из костей дракончиков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13360, 'Время ответов', 'Я вижу, у тебя много вопросов, $N. Ты – $gединственный:единственная:, кто может видеть меня, ибо $gкоснулся:коснулась: некоего предмета, принадлежавшего ему... Ты помнишь?$B$BТы не знаешь, что это? Нет-нет, я не могу просто так рассказать тебе... Он разгневается сверх всякой меры, а ведь ныне он не принц, но король!$B$BВстретимся во Дворе Костей, к северу от цитадели Ледяной Короны: там ты $gсам:сама: все увидишь.', 'Поговорите с Матиасом Нетлером во Дворе Костей.', 'Ах, вот и ты! Я уже начал сомневаться, придешь ты или нет...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13361, 'Охотник и принц', 'До того как стать королем, принц сражался во многих битвах... Но лишь в одной ему грозила смерть. $B$BБитва свершилась здесь, на этом месте. Позволь мне показать, что случилось, и ты все поймешь.$B$BНайди залитый кровью камень и осмотри его. Тогда тебе откроется прошлое.', 'Матиас Нетлер со Двора Костей хочет, чтобы вы нашли Окровавленный камень и увидели, что случилось с принцем.', 'После этого боя принц осознал: его сдерживает то, что он все еще человек... Он по-прежнему чувствует, его можно ранить, и у него живое сердце. $B$BСтав королем, он в первую очередь решил избавиться от сердца и бросил его в глубокую яму на том самом месте, где мы впервые встретились с тобой. Ты, $N, стал первым, кто коснулся его сердца за все это время.', 'Ты видел это, $N? Ты видел это?', NULL, NULL, 'Судьба принца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13362, 'Знание – тяжкая ноша', 'Теперь ты знаешь, что тебе предстоит, $N. Противник, которому неведомы ни боль, ни муки совести, ни человеческие чувства... Противник, который готов на все, чтобы добиться своего. $B$BЕдинственная слабость нынешнего короля в том, что его сердце все еще существует; и теперь король знает, что ты $gнашел:нашла: его. $B$BЕсли хочешь вернуться и найти сердце, лучше возьми кого-нибудь в помощь – его хорошо охраняют...', 'Вернитесь к Кольтире на борт \"Молота Оргрима\".', 'Призрак мальчика… Сердце Артаса… Погоди-погоди. У меня голова идет кругом.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13363, 'Помощь Серебряного Авангарда', 'Среди рыцарей смерти ходят слухи о тех событиях, о которых ты говоришь. Я всегда думал, что в этой истории есть… более глубокий смысл.$B$BНадо предупредить остальных, но это нужно сделать тихо. Если Король-лич хоть что-нибудь заподозрит, он тут же переправит Сердце в другое место. А подобного случая более не представится.$B$BКульт Проклятых уже проникал и в Орду, и в Альянс. Черный Клинок действует по соседству с Плетью...$B$BНадо связаться с Тирионом Фордрингом и его Серебряным Авангардом.', 'Поговорите с верховным лордом Тирионом Фордрингом на Вершине Рыцарей.', 'Мне тяжело слышать эти слова, $N. Если бы их произнес кто-то другой, я бы, наверное, счел его безумным...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13364, 'Гамбит Тириона', 'Этим утром разведчики сообщили мне, что из цитадели Ледяной Короны к Собору Тьмы движется процессия последователей Культа Проклятых, и что они несут некий артефакт. $B$BА теперь мне стало известно, что этим сокровищем может быть само сердце Артаса... Сердце, хранящее последние крупицы человеческого, еще оставшиеся в нем! $B$BЭто знак свыше. Пока подобный предмет существует, остается надежда, что Артас Менетил вновь сможет стать человеком!$B$BВстретимся у входа в собор. И не забудь прихватить капюшон сектанта-послушника: никто не должен узнать нас.', 'Тирион Фордринг с Вершины Рыцарей хочет, чтобы вы достали и надели капюшон сектанта-послушника, а затем встретились с ним у входа в Собор Тьмы, к северо-западу от цитадели Ледяной Короны.', 'То, что произошло с нами, нельзя считать поражением, $N... О нет, напротив! $B$BТы дал мне возможность заглянуть в глубины этого сердца и узнать то, что узнать было необходимо. Артаса Менетила больше нет: есть только Король-лич.', 'Да пребудет с тобой Свет, о $N.', NULL, NULL, 'Уловка Тириона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13365, 'Ненастоящий шпион', 'Сектанты отловили последнего отправленного тобой посланника, $r.$B$BКонечно, он успел доставить нам немало ценных сведений, и все же нам необходимо продолжать следить за каждым их шагом.$B$BИспользуй этот жезл, чтобы вытянуть те$Nю сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нового шпиона.$B$BПока этого посланника не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.', 'Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Кольтиры, который находится на борту \"Молота Оргрима\".', 'Отлично, друг мой!$B$BПосланец уже продолжает работу…', NULL, NULL, NULL, 'Призвано темных посланников', 'Жезл вытягивания', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13366, 'Слишком мало сведений', 'Культ Проклятых известен тем, что вечно строит грандиозные планы, которые никогда не исполняются. Но на этот раз явно вышло иначе…$B$BБыть может, это близкое соседство с Королем-личом на них так повлияло. Как бы то ни было, они держатся увереннее, чем обычно. Необходимо выяснить, что питает их отвагу, а затем найти способ усмирить их!$B$BПодозреваю, что все дело в их ученых. Узнай, что они затевают, и доложи мне во всех подробностях.', 'Отберите у ученых культа в Алдур\'таре 3 страницы Исследований Культа Проклятых и используйте их, чтобы составить доклад о Культе Проклятых по приказу Кольтиры с \"Молота Оргрима\".', 'Да, это весьма тревожные известия…', 'Ну что, $R, удалось ли выяснить, чем заняты их ученые?', NULL, NULL, 'Доклад о Культе Проклятых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13367, 'Пусть злодеи не ведают покоя', 'Эти глупцы и впрямь обнаружили нечто, что может представлять серьезную угрозу для наших планов!$B$BПредводитель их секты, Алумет, совершил ритуальное самоубийство, и теперь его прихвостни передают его душе свою силу...$B$BЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$B$BСобери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$B$BТоропись, $r! Уничтожь его, пока он не стал слишком силен!', 'Повергните Алумета Восходящего в Алдур\'таре по просьбе Кольтиры Ткача Смерти, который находится на борту \"Молота Оргрима\".', 'Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…', NULL, NULL, NULL, 'Алумет Перерожденный побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13368, 'Пусть злодеи не ведают покоя', 'А, это Алумет… Снова набирает силу. Я это чую. Снова его прихвостни передают магию его душе.$B$BЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$B$BВозвращайся в его зал в северной части Алдур\'тара. Собери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$B$BТоропись, $r! Уничтожь его, пока он не стал слишком могуществен!', 'Кольтира на борту \"Молота Оргрима\" хочет, чтобы вы убили Алумета Восходящего в Алдур\'таре.', 'Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…', NULL, NULL, NULL, 'Алумет Перерожденный побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13369, 'Против воли рока', 'По просьбе леди Праудмур я позволю ей отправиться в Оргриммар с посольством, дабы говорить с военачальником Орды Траллом. Ты будешь сопровождать и оберегать ее в пути. По возвращении я хочу узнать вести из Оргриммара.$B$BКогда будешь $gготов:готова:, поговори с Джайной.', 'Сопроводите леди Джайну Праудмур в Калимдор в Оргриммар. Поговорите с военачальником Орды Траллом.', 'Орда не хочет войны, $R. Слушай внимательно и запоминай...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13370, 'Королевский ход', 'Ваш воитель, Болвар, погиб, защищая весь наш мир. Орда опечалена гибелью такого героя, однако Орда не в ответе за трусливое нападение Гнилесса у врат Гнева. Мы тоже потеряли немало героев из-за его предательства. $B$BПередай вашему королю, что мы сделаем все, что в наших силах, чтобы призвать к ответу виновников этого злобного деяния. Мы также сделаем все возможно, дабы избежать конфликта с Альянсом. Однако если на нас нападут, мы будет защищаться без колебаний.', 'Воспользуйтесь порталом в крепости Громмаш, чтобы вернуться в крепость Штормграда и передать послание Тралла королю Вариану Ринну.', 'Они потеряли Подгород? Значит, настало время нанести удар! С Гнилессом мы разберемся сами, а руины Лордерона будут принадлежать Альянсу!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13371, 'В ожидании дальнейших распоряжений', 'Когда ты $gушел:ушла: в Оргриммар, я послал в Подгород Бролла и Валиру. Сейчас они расположились рядом с канализационным коллектором у входа в развалины и ждут дальнейших указаний.$B$BЛеди Праудмур откроет портал для наших войск прямо на подступах к Подгороду. Иди туда и разыщи Бролла. Мы с Джайной подтянемся чуть позже, но уже очень скоро.', 'Воспользуйтесь порталом в Крепости Штормграда и телепортируйтесь в Подгород. Когда прибудете на место, разыщите Бролла Медвежью Шкуру.', 'А ты, собственно, кто такой? Вариан сказал, что пришлет настоящих героев.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13372, 'Ключ к Радужному Средоточию', 'Выпавший из лап Сапфирона драгоценный камень в форме глаза издает мощный гул, явно магической природы, который не только слышен, но и ощущается всем телом. Для смертного слуха этот гул воспринимается как мучительная боль.$B$BТакой могущественный предмет можно отдать лишь королеве драконов, Алекстразе Хранительнице Жизни. Спросите ее совета на вершине храма Драконьего Покоя, что в Драконьем Погосте.', 'Отнесите ключ от Радужного Средоточия Алекстразе Хранительнице Жизни на вершине храма Драконьего Покоя в Драконьем Погосте.', 'Эти ключи принадлежат самым древним из синих драконов. Только им доверял их владыка, Малигос.$B$BПохоже, настал переломный момент, которого мы ждали, чтобы нанести удар по Аспекту Магии!$B$B<Королева драконов внимательно разглядывает вас.>$B$BТы не сможешь самостоятельно использовать ключ для доступа к Радужному Средоточию, но я могу наделить тебя толикой моей силы; этого хватит, чтобы немного приоткрыть Средоточие.$B$BМалигос это сразу заметит и не замедлит явиться, чтобы обрушить свой гнев на того, кто дерзнул подступиться к Средоточию!', 'Молодойсвин, ты завладела Ключом от Радужного Средоточия! Он у тебя с собой?$B$B<Королева с тревогой смотрит на своего супруга, Краса.>$B$BКак он к тебе попал? О, это был ключ Сапфирона?', NULL, NULL, 'Ключ к Радужному Средоточию (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13373, 'Последнее слово техники', 'Я установила инфра-зеленые излучатели на захваченные бомбардировщики. Они действуют как щиты и защитят тебя в первом боевом вылете на вражескую территорию. Поговори с Риззи Храпокруткой, возьми бомбардировщик и лети в Зону бомбардировки!$B$BУ тебя будет полный боекомплект: бомбы, ракеты и щиты. Следи за тем, чтобы щиты не разряжались, и уничтожай наземные войска Плети, расположившиеся в Зоне бомбардировки. Потом возвращайся сюда. У тебя будет новое задание.', 'Уничтожьте 40 пехотинцев из зоны бомбардировки, 8 капитанов из зоны бомбардировки и 15 горгулий-душительниц по заданию инженера-экспериментатора Теззлы.', 'Ага, у тебя получилось! И как тебе бомбардировщик? Надеюсь, ты с ним сроднился, потому что тебе предстоит новый боевой вылет... и на этот раз все будет гораздо серьезнее...', 'Ты еще не поразил свою долю целей, $N. Неужели эти бомбардировщики так сложны в управлении?', NULL, NULL, 'Пехотинец из зоны бомбардировки убито', 'Капитан из зоны бомбардировки убито', 'Горгулья-душительница убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13374, 'Боевое задание', '$N, такие задания мы даем только самым лучшим пилотам: проникнуть вглубь вражеской территории, практически безо всякой защиты, не считая энергетических щитов инфра-зеленого излучения.$B$BВозьми у Риззи еще один бомбардировщик и лети в долину Потерянной Надежды. На этот раз целей будет гораздо больше: как на земле, так и в воздухе. Так что смотри в оба и следи за тем, чтобы щиты не разрядились!$B$BУдачи!', 'Уничтожьте пехотинцев из зоны бомбардировки, боевые машины Плети, горгулий-душительниц и часовых ледяных драконов по заданию инженера-экспериментатора Теззлы.', '', NULL, NULL, NULL, 'Пехотинец из зоны бомбардировки убито', 'Горгулья-душительница убито', 'Боевая машина Плети убито', 'Ледяной караульный убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13375, 'Ключ к Радужному Средоточию (героический режим)', 'Выпавший из лап Сапфирона драгоценный камень в форме глаза издает мощный гул, явно магической природы, который не только слышен, но и ощущается всем телом. Для смертного слуха этот гул воспринимается как мучительная боль.$B$BТакой могущественный предмет можно отдать лишь королеве драконов, Алекстразе Хранительнице Жизни. Спросите ее совета на вершине храма Драконьего Покоя, что в Драконьем Погосте.', 'Отнесите ключ от Радужного Средоточия (героический режим) Алекстразе Хранительнице Жизни на вершине храма Драконьего Покоя в Драконьем Погосте.', 'Эти ключи принадлежат самым древним из синих драконов. Только им доверял их владыка, Малигос.$B$BПохоже, настал переломный момент, которого мы ждали, чтобы нанести удар по Аспекту Магии!$B$B<Королева драконов внимательно разглядывает вас.>$B$BТы не сможешь самостоятельно использовать ключ для доступа к Радужному Средоточию, но я могу наделить тебя толикой моей силы; этого хватит, чтобы немного приоткрыть Средоточие.$B$BМалигос это сразу заметит и не замедлит явиться, чтобы обрушить свой гнев на того, кто дерзнул подступиться к Средоточию!', '$N, ты завладел Ключом от Радужного Средоточия! Он у тебя с собой?$B$B<Королева с тревогой смотрит на своего супруга, Краса.>$B$BКак он к тебе попал? О, это был ключ Сапфирона?', NULL, NULL, 'Ключ для доступа к героическому режиму Радужного Средоточия (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13376, 'Война продолжается', 'Война продолжается, $N. К счастью, у нас есть хороший запас бомб и ракет! Самое время испытать наш инфра-зеленый бомбардировщик и разорвать этих мерзавцев из Плети на мелкие плеточки!', 'Уничтожьте 50 пехотинцев из зоны бомбардировки, 12 боевых машин Плети, 20 горгулий-душительниц и 12 часовых ледяных драконов по заданию инженера-экспериментатора Теззлы.', 'Отлично сработано, $N. Пока тебя не было, я слышала, что о тебе говорили остальные канониры... Я бы сказала, что тебя ждет блестящее будущее в военно-воздушных силах!', 'Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.', NULL, NULL, 'Пехотинец из зоны бомбардировки убито', 'Горгулья-душительница убито', 'Боевая машина Плети убито', 'Ледяной караульный убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13377, 'Битва за Подгород', 'Глубоко в недрах Подгорода прячется убийца, ответственный за гибель Болвара и наших отважных солдат у Врат Гнева.$B$BВариан привел сюда с собой всю мощь Альянса, чтобы взять город. Присоединись к нему и к леди Праудмур в охоте на ассасина! Это позволит тебе стать $gодним:одной: из первых героев Альянса!$B$BКогда будешь $gготов:готова:, поговори с королем Варианом Ринном.', 'Помогите королю Вариану Ринну и леди Джайне Праудмур покарать верховного аптекаря Гнилесса! Если вам это удастся, явитесь к королю Вариану Ринну.', 'Слишком долго Орда оставалась безнаказанной! Мы позволяли им процветать, и вот благодарность за нашу доброту! Они замыслили погубить нас!$B$BМир? Это бесполезно. Что дал нам этот мир? Гибель нескольких лучших героев? Посмотрим, что принесет нам битва…$B$BВозвращайся в Нордскол, $N. Завоюй его для своего короля – ради Альянса!', NULL, NULL, NULL, 'Помочь королю Вариану Ринну', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13378, 'Главный инженер Меднопал', 'Поговорите с главным инженером Меднопалом', 'Поговорите с главным инженером Меднопалом.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13379, 'Зеленые технологии', 'Надо тебя познакомить с Теззлой. Да, точно! Она научилась использовать новое волновое излучение – инфразеленое – и с его помощью ей удалось подобраться поближе к армии Плети! Достаточно близко, чтобы сбрасывать на них бомбы!$B$BЯ наделю тебя способностью видеть в инфразеленом диапазоне, чтобы разыскать ее над Алдур\'таром, Вратами Горя. Отправляйся немедленно... насколько я знаю, у нее всегда найдется работа для отважных героев, которые не прочь повзрывать то да се! Особенно прислужников Плети!$B$BИ еще $N, Альянс украл нашу технологию, и у него есть собственный невидимый аэропорт неподалеку. Избегай строений со знаменами Альянса!', 'Поговорите с инженером-экспериментатором Теззлой.', 'Да, да! Ты нашел меня! И очень вовремя!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13380, 'Возглавить нападение', 'Технология инфра-зеленого излучения позволяет нам оставаться \"невидимыми\" прямо под носом у Плети! Больше того, мы установили инфра-зеленые излучатели на специально сконструированные бомбардировщики... но вовсе не для того, чтобы скрыть эти машины от глаз врага, нет! Мы используем излучение как щит!$B$BСтупай туда, где стоит Карен Нет, попроси бомбардировщик. Лети в Зону бомбардировки... используй щиты и пушку для защиты, а бомбометы – понятное дело, для бомбометания. В общем, потренируйся, а потом возвращайся ко мне. Я дам тебе новое задание, которое будет уже посерьезнее!', 'Убейте 40 пехотинцев из зоны бомбардировки, 8 капитанов из зоны бомбардировки и 15 горгулий-душительниц по заданию Кибли Киллогерца.', 'Взрывы от твоих бомб были слышны даже здесь, $N. Как работают щиты? Твой аппарат не пострадал?$B$BНадеюсь, защита работает исправно, потому что тебе предстоит новый вылет... и на этот раз все будет гораздо серьезнее...', 'Да, $N, бомбардировщики непросты в обращении, но это действительно мощные аппараты. Так что придется нам их освоить, если мы собираемся победить Плеть.', NULL, NULL, 'Пехотинец из зоны бомбардировки убито', 'Капитан из зоны бомбардировки убито', 'Горгулья-душительница убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13381, 'Боевой вылет', 'Надевай свои счастливые носки, $N, и читай все любимые молитвы. Твое следующее задание – это будет уже настоящее испытание находчивости, и смекалки, и силы духа. Прямо как нежданный визит обожаемой $gтещи:свекрови:, хе-хе!$B$BПусть Карен Но даст тебе еще один бомбардировщик. Лети за Зону бомбардировки, к долине Потерянной Надежды. На этот раз целей будет гораздо больше: как на земле, так и в воздухе. В общем, чтоб тебе долететь и туда и обратно, и боеприпасы не кончились, и заряд у щитов не иссяк. Встретимся после боя, $N!', 'Уничтожьте пехотинцев из зоны бомбардировки, боевые машины Плети, горгулий-душительниц и часовых ледяных драконов по заданию Кибли Киллогерца.', '', NULL, NULL, NULL, 'Пехотинец из зоны бомбардировки убито', 'Горгулья-душительница убито', 'Боевая машина Плети убито', 'Ледяной караульный убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13382, 'Килотонны смерти', 'Бой продолжается! Для тебя есть задание дальнего действия. Цель – бомбардировка Долины Потерянной Надежды. Когда будешь $gготов:готова:, пусть Карен даст тебе бомбардировщик. Сбрось все ракеты и бомбы на головы этих уродов Плети!', 'Уничтожьте 50 пехотинцев из зоны бомбардировки, 12 боевых машин Плети, 20 горгулий-душительниц и 12 часовых ледяных драконов по заданию Кибли Киллогерца.', 'С возвращением, $N. Как прошел бой? Ты задал им жару? Ты пока отдыхай. Но потом возвращайся, для тебя будет новое боевое задание.$B$BВсе для победы Альянса!', 'Держись, $N. Держись. Победа в воздушном бою не происходит сама по себе! Ее делаем мы!', NULL, NULL, 'Пехотинец из зоны бомбардировки убито', 'Горгулья-душительница убито', 'Боевая машина Плети убито', 'Ледяной караульный убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13383, 'Киллогерц', 'Гоблинам удалось открыть новую форму энергии. Они называют ее инфра-зеленым излучением, и это действительно зеленое золото с технологической точки зрения. Они, ясное дело, те еще психопаты, но мозги у них есть, и иногда они даже работают. Стыдно признаться, но мы выкрали их технологию. Однако я с гордостью заявляю, что мы ее усовершенствовали!$B$BРазыщи Кибли Киллогерца. Он у нас главный по разработкам инфра-зеленого излучения. Его база находится в маленьком секретном аэропорту Альянса над Алдур\'таром, Вратами Горя. Я дам тебе прибор инфра-зеленого видения, чтобы ты $gсмог:смогла: найти аэропорт.', 'Разыщите Кибли Киллогерца на базе в скрытом аэропорту Альянса над Алдур\'таром, Вратами Горя, по приказу главного инженера Болтоключа.', 'Да, да, да! Тысячу раз – привет!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13384, 'Правосудие в Оке Вечности', 'Теперь, когда у тебя есть доступ к Радужному Средоточию, нужно использовать его в деле.$B$BКак бы мне ни хотелось, чтобы Малигос снова стал одним из нас, я понимаю, что это уже невозможно. Слишком многое поставлено на карту, и другие Драконьи аспекты решили, что Хранитель Магии должен умереть.$B$B<Крас произносит эти слова с дрожью в голосе.>$B$B$N, отправляйся к Оку Вечности, убей Малигоса и возвращайся сюда с Сердцем Магии.', 'Принесите Сердце Магии Красу на вершине храма Драконьего Покоя в Драконьем Погосте.Это задание предназначено для обычного уровня сложности и представляет собой версию Ока Вечности для 10 игроков.', 'Сегодняшний день принес скорбную весть, и не только для драконов, но и для всех обитателей Азерота. Мы потеряли одного из самых старых и мудрых друзей. Магия осталась без хранителя.$B$BБудем надеяться, Молодойсвин, что это было правильное решение. Буря на горизонте все еще набирает силу, а мы лишились одного из самых могущественных защитников.', 'Лишь Малигос обладает Сердцем Магии. Это самое ценное, что у него есть.', NULL, NULL, 'Сердце Магии', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13385, 'Героическое правосудие в Оке Вечности', 'Теперь, когда у тебя есть доступ к Радужному Средоточию, нужно использовать его в деле.$B$BКак бы мне ни хотелось, чтобы Малигос снова стал одним из нас, я понимаю, что это уже невозможно. Слишком многое поставлено на карту, и другие Драконьи аспекты решили, что Хранитель Магии должен умереть.$B$B<Крас произносит эти слова с дрожью в голосе.>$B$B$N, отправляйся к Оку Вечности, убей Малигоса и возвращайся сюда с Сердцем Магии.', 'Принесите Сердце Магии Красу на вершине храма Драконьего Покоя в Драконьем Погосте.Это задание можно выполнить в Оке Вечности для 10 и 25 игроков.', 'Сегодняшний день принес скорбную весть, и не только для драконов, но и для всех обитателей Азерота. Мы потеряли одного из самых старых и мудрых друзей. Магия осталась без хранителя.$B$BБудем надеяться, $N, что это было правильное решение. Буря на горизонте все еще набирает силу, а мы лишились одного из самых могущественных защитников.', 'Лишь Малигос обладает Сердцем Магии. Это самое ценное, что у него есть.', NULL, NULL, 'Сердце Магии', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13386, 'Разведка провала', 'У меня есть для тебя интересное задание, $N. Если возьмешься, конечно.$B$BНам сообщили о каком-то провале под Цитаделью Ледяной Короны. Наши инженеры изучили схемы и определили все слабые места.$B$BМы отправили туда наших ребят с \"позаимствованными\" саронитовыми бомбами. Командует ими капитан Кендалл.$B$BЕсли ты им поможешь, мы сможем нанести неслабый удар силам Плети. Что скажешь, $N?', 'Поговорите с капитаном Кендаллом под цитаделью Ледяной Короны.', 'Привет тебе, $N! Тассариан говорил, что ты придешь. Друг Тассариана – мой друг. Если это живой друг, конечно… А то он, знаешь ли, водит всякие знакомства.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13387, 'Круговая оборона', 'Саронитовые бомбы уже заложены, $N. Однако воспользоваться ими мы сможем только один раз. Надо использовать эту возможность максимально эффективно.$B$BЧтобы благополучно их взорвать, нужно хотя бы на время обеспечить себе контроль над этой территорией. Надо постараться уменьшить численность воинов Плети.', 'Капитан Кендалл у цитадели Ледяной Короны просит вас убить 10 неповоротливых громад.', 'Да, Тассариан не обманул меня, ты и впрямь молодец. Отличная работа!', 'За Альянс!', NULL, NULL, 'Неповоротливая громада убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13388, 'Поджигай!', 'Все идет отлично. Можно браться за дело.$B$BБомбы заложены у самой ямы. Я начинаю эвакуировать наших.', 'Капитан Кендалл под стенами цитадели Ледяной Короны просит вас отправиться к ближайшему штабелю саронитовых бомб и поджечь фитиль.', 'Похоже, эти бомбы довольно мощные. Они должны как минимум повредить стену.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13389, 'Фитиль короток!', 'Не успев поджечь фитиль, вы обнаруживаете, что он сгорает куда быстрее, чем вы рассчитывали!$B$BБомбы вот-вот рванут. Ваш единственный шанс на спасение – броситься в провал и надеяться, что там не слишком глубоко.', 'Там, куда вы падаете, вас ждет кое-что интересное!', 'Этот пульсирующий предмет закован в толстый слой льда. Он странно мерцает из-под воды.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13390, 'Голос во тьме', 'Нет, это не кристалл, это какой-то замороженный орган…$B$BВы прикасаетесь к нему – и руку пронзает немыслимая боль. Такое ощущение, будто руку отрубили напрочь. Но никаких ран на ней не заметно…$B$BПытаясь собраться с мыслями, вы вдруг слышите где-то рядом мальчишеский голос.$B$B\"Не стоило тебе этого делать, ой, не стоило!\"', 'Выясните, откуда доносится голос, который вы услышали в Наз\'анаке, Забытых глубинах.', 'Я видел, как он от него избавился, прикинь? Он швырнул его прямо сюда, вниз!$B$BСказал, что больше оно ему не понадобится. Сказал, оно делает его слабым.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13391, 'Пора прятаться!', 'Не стоило тебе трогать эту штуку! Теперь он непременно явится искать тебя.$B$BИ он тебя найдет. Если только ты не сумеешь от него спрятаться.$B$BХочешь выжить – принеси мне кровь безликих!', 'Добудьте 3 образца крови безликих по совету Матиаса Нетлера.', 'И чего ты ждешь? Натрись ею!$B$BБыстрей! А то он тебя увидит!', 'Ну что, где кровь?', NULL, NULL, 'Кровь безликого', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13392, 'Возвращение на поверхность', 'Теперь уходи. У меня за спиной есть портал – выходи через него на поверхность.$B$BМы еще встретимся. Он ведь будет тебя искать.$B$BИ найдет, рано или поздно.', 'Вернитесь к Тассариану на борт \"Усмирителя небес\".', 'Это ты, $N!А мы уж думали – все, конец тебе.$B$BЭтот твой взрыв нанес Плети серьезный урон. И капитану Кендаллу едва брови не спалило…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13393, 'Ремонт в полевых условиях', 'Хорошо. Но победу праздновать пока рановато. Нужно закрепить и развить успех, которого мы добились с помощью взрывов.$B$BМы заметили на поле боя вполне еще рабочую ордынскую катапульту класса \"разрушитель\". Но ее разбирают на части упыри.$B$BЕсли бы тебе удалось восстановить катапульту, мы могли бы нанести войскам Плети в долине куда более серьезный урон.$B$BДа, конечно, я понимаю, мертвяки превосходят нас по численности, но я в тебя верю!', 'Отберите у упырей-мародеров 5 деталей разрушителя и отнесите их к сломанной катапульте в долине Потерянной Надежды по просьбе Тассариана на борту \"Усмирителя небес\".', 'Конечно, этот разрушитель знавал и лучшие дни, но основной механизм вроде бы не поврежден. Во всяком случае, он поддается ремонту. Добытых тобой деталей должно быть достаточно, чтобы он снова заработал... хотя бы ненадолго.', 'Разрушитель сильно пострадал.', NULL, NULL, 'Части разрушителя', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13394, 'Все к худшему', 'Зачем тебе эта машина? С Плетью воевать? Машинами Плеть не одолеешь.$B$BТы можешь уничтожить сотни… да что там, даже тысячи воинов Плети! Но саму Плеть тебе не победить.$B$BКогда наиграешься вдоволь, ступай на север. Я встречусь с тобой возле заброшенного военного лагеря. И там я покажу тебе кое-что, чтобы ты $gпонял:поняла:, с чем имеешь дело.', 'Используйте отремонтированный разрушитель, чтобы уничтожить 150 изгнивших вурдалаков, 20 ледотленных волхвов и 2 костяных великана в долине Потерянной Надежды. Выполнив эту задачу, поговорите с Матиасом Нетлером в лагере сопротивления первого легиона.', 'Видишь? Ты можешь убивать их сколько угодно, но на место каждого убитого встанет из земли другой, новый.$B$BТы не понимаешь, с чем сражаешься, $N. Разреши, я тебе покажу.', NULL, NULL, NULL, 'Изгнивший вурдалак убито', 'Ледотленный волхв убито', 'Костяной великан убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13395, 'Войско проклятых', 'Ты, наверное, гордишься своим могуществом: ну как же, ты громишь эту нежить, давишь кости мертвяков своей машиной…$B$BНо это все пустяки по сравнению с тем могуществом, которое потребовалось, чтобы их создать!$B$BЯ видел, как принц это делал. И могу показать, как это было... если хочешь, конечно.', 'Оживите 100 вурдалаков-прислужников по просьбе Матиаса Нетлера в лагере сопротивления первого легиона.', 'Подлинное могущество принца было не в том, чтобы создавать армии из трупов – это-то как раз было легко.$B$BА вот убивать своих собственных солдат, с которыми он прошел немало битв… подлинное могущество принца состояло в том, чтобы поступать так, как велят обстоятельства.', NULL, NULL, NULL, 'Оживлено вурдалаков-прислужников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13396, 'Тщета', 'Теперь понимаешь? Посылая своих бойцов на войну с полчищами принца, вы только пополняете их ряды.$B$BВпрочем, я и не рассчитывал, что ты поймешь… думаю, с тобой будет то же, что и с другими. Возвращайся лучше к тому, кто тебя прислал. Думаю, о тебе тревожатся...', 'Вернитесь к Тассариану на борт \"Усмирителя небес\".', 'Отличный бой, $N! Все воинство Плети было не в силах тебе противостоять…$B$BС тобой все в порядке? У тебя такой вид, будто ты увидела привидение. Хотя, вообще-то, в здешних краях это не такая уж редкость…', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13397, 'Каньон Гибели Синдрагосы', 'Ты настоящий герой, $N. Видишь ли, когда я даю одному из своих солдат поручение, шансы, что он действительно его выполнит, примерно пятьдесят на пятьдесят. А шансов на то, что он вернется живым, и того меньше.$B$BНо ты другое дело! На тебя всегда можно положиться. Ты работаешь, как гномские часы!$B$BЭто я к чему: вот тебе еще одно дело. Каньон Гибели Синдрагосы находится к востоку от долины. Сектанты развили там слишком бурную деятельность. Они создают ледяных змеев – и не только. Ступай и разберись с ними!$B$BНенавижу сектантов.', 'Убейте 5 воскресителей драконов, 8 сектантов-осквернителей и 3 врайкулов-некролордов в Каньоне Гибели Синдрагосы по приказу Тассариана с \"Усмирителя небес\".', 'Неплохо сработано, $N. По сравнению с тобой все мы бездельники!', NULL, NULL, NULL, 'Воскреситель драконов убито', 'Сектант-осквернитель убито', 'Врайкул-некролорд убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13398, 'Место гибели драконов', 'Тут погиб целый выводок синих драконов. И вот теперь его слуги воскрешают их, одного за другим.$B$BСамого могучего воскресил он сам. Принеси мне пыли костей молодых драконов, и я покажу тебе, как он это сделал.', 'Добудьте в Каньоне Гибели Синдрагосы 6 горстей пыли из костей дракончиков по приказу Матиаса Нетлера.', 'Даже могучие змеи были вынуждены подчиниться его зову. Неужели простая смертная вроде тебя может надеяться устоять?', 'Где пыль, $N?', NULL, NULL, 'Пыль из костей дракончиков', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13399, 'Время ответов', 'Я вижу, у тебя много вопросов, $N. Ты – $gединственный:единственная:, кто может видеть меня, ибо $gкоснулся:коснулась: некоего предмета, принадлежавшего ему... Ты помнишь?$B$BТы не знаешь, что это? Нет-нет, я не могу просто так рассказать тебе... Он разгневается сверх всякой меры, а ведь ныне он не принц, но король!$B$BВстретимся во Дворе Костей, к северу от цитадели Ледяной Короны: там ты $gсам:сама: все увидишь.', 'Поговорите с Матиасом Нетлером во Дворе Костей.', 'Ах, вот и ты! Я уже начал сомневаться, придешь ты или нет...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13400, 'Охотник и принц', 'До того как стать королем, принц сражался во многих битвах... Но лишь в одной ему грозила смерть. $B$BБитва свершилась здесь, на этом месте. Позволь мне показать, что случилось, и ты все поймешь.$B$BНайди залитый кровью камень и осмотри его. Тогда тебе откроется прошлое.', 'Матиас Нетлер со Двора Костей хочет, чтобы вы нашли Окровавленный камень и увидели, что случилось с принцем.', 'После этого боя принц осознал: его сдерживает то, что он все еще человек... Он по-прежнему чувствует, его можно ранить, и у него живое сердце. $B$BСтав королем, он в первую очередь решил избавиться от сердца и бросил его в глубокую яму на том самом месте, где мы впервые встретились с тобой. Ты, $N, стала первой, кто коснулся его сердца за все это время.', 'Ты видела это, $N? Ты видела это?', NULL, NULL, 'Судьба принца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13401, 'Знание – тяжкая ноша', 'Теперь ты знаешь, что тебе предстоит, $N. Противник, которому неведомы ни боль, ни муки совести, ни человеческие чувства... Противник, который готов на все, чтобы добиться своего. $B$BЕдинственная слабость нынешнего короля в том, что его сердце все еще существует; и теперь король знает, что ты $gнашел:нашла: его. $B$BЕсли хочешь вернуться и найти сердце, лучше возьми кого-нибудь в помощь – его хорошо охраняют...', 'Вернитесь к Тассариану на борт \"Усмирителя небес\".', 'Погоди, погоди, $N. Почему бы тебе не начать снова – и с самого начала?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13402, 'Помощь Тириона', 'Я не в первый раз слышу рассказ об Артасе и его сердце... Правда, мне всегда казалось, что это выдуманная история. $B$BЧто ж, нам следует действовать по обстоятельствам. К сожалению, делать это придется в тайне. $B$BШпионы Артаса повсюду, и если он узнает о наших планах, мы все погибнем. $B$BНужно сообщить обо всем Серебряному Авангарду. Сам Тирион лично отбирал паладинов для этого ордена. Если и остались еще те, кто свободен от губительного влияния служителей культа, то это они.', 'Поговорите с верховным лордом Тирионом Фордрингом на Вершине Рыцарей.', 'Мне тяжело слышать эти слова, $N. Если бы их произнес кто-то другой, я бы, наверное, счел его безумным...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13403, 'Гамбит Тириона', 'Этим утром разведчики сообщили мне, что из цитадели Ледяной Короны к Собору Тьмы движется процессия последователей Культа Проклятых, и что они несут некий артефакт. $B$BА теперь мне стало известно, что этим сокровищем может быть само сердце Артаса... Сердце, хранящее последние крупицы человечности, еще оставшиеся в нем! $B$BЭто знак свыше. Пока подобный предмет существует, остается надежда, что Артас Менетил вновь сможет стать человеком!$B$BВстретимся у входа в собор. И не забудь прихватить капюшон сектанта-послушника: никто не должен узнать нас.', 'Тирион Фордринг с Вершины Рыцарей хочет, чтобы вы достали и надели капюшон сектанта-послушника, а затем встретились с ним у входа в Собор Тьмы, к северо-западу от цитадели Ледяной Короны.', 'То, что произошло с нами, нельзя считать поражением, $N... О нет, напротив! $B$BТы дала мне возможность заглянуть в глубины этого сердца и узнать то, что узнать было необходимо. Артаса Менетила больше нет: есть только Король-лич.', 'Да пребудет с тобой Свет, о $N.', NULL, NULL, 'Уловка Тириона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13404, 'Войска статического разряда: Зона бомбардировки', 'Это будет задание ближнего действия. Цель – Зона бомбардировки. Для разминки. $gГотов:Ты готова:?', 'Убейте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию Кибли Киллогерца.', 'С возвращением, $N. Вылет был хоть и короткий, но, как я понимаю, бодрящий, да? Ты пока отдыхай. Но потом возвращайся – для тебя будет новое боевое задание', 'Держись, $N. Держись. Победа в воздушном бою не происходит сама по себе! Ее делаем мы!', NULL, NULL, 'Пехотинец из зоны бомбардировки убито', 'Капитан из зоны бомбардировки убито', 'Горгулья-душительница убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13405, 'К оружию! Берег Древних', 'Здесь, в Нордсколе, мы сражаемся не только с армиями Короля-лича, но и с силами Орды.$B$BНедавно на Береге Древних была найдена могущественная реликвия $Nв. Мы, дворфы, уже многие годы оберегаем подобные артефакты, и потому считаем себя законными хранителями этой святыни.$B$BНо Орда разработала план по извлечению реликвии из руин $Nв. Несомненно, они намереваются использовать ее в качестве оружия против нас, и потому наш долг – остановить их, пока еще не поздно.', 'Выиграйте битву на поле боя Берега Древних и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа на Береге Древних', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13406, 'Новое излучение. Зона бомбардировки', 'Ну что, ты $gготов:готова: размяться и слегка побомбить врагов? Ну, тогда хорошо. У тебя есть задание, а у нас – бомбы.', 'Уничтожьте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию инженера-экспериментатора Теззлы.', 'Да, у тебя получилось! Даже здесь было слышно, как их разлетающиеся запчасти бьются о скалы. Ты молодец. В ближайшее время получишь новое задание...', 'Ты еще не поразил свою долю целей, $N. Лети назад и исполни задание, как положено.', NULL, NULL, 'Пехотинец из зоны бомбардировки убито', 'Капитан из зоны бомбардировки убито', 'Горгулья-душительница убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13407, 'К оружию! Берег Древних', 'Война с Плетью в Нордсколе – это еще не повод давать послабление Альянсу!$B$BЭти проклятые дворфы из Лиги Исследователей откопали какую-то могущественную реликвию $Nв. Мы не можем допустить, чтобы она попала в руки Альянса!$B$BИди, $N, и уничтожь наших врагов. Пусть они поймут, что им нигде от нас не скрыться.', 'Выиграйте битву на поле боя Берега Древних и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'You bring great honor to us, $N! The Alliance weaklings must be crushed under the heel of the mighty Horde!', NULL, NULL, NULL, 'Победа на Береге Древних', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13408, 'Штурмовые укрепления', 'Цитадель Адского Пламени уже долгое время отбивает все наши атаки. Мы сохраняем позиции, но не можем перейти в решительное наступление. Нам необходимо укрепить передовые.$B$BРазведчики обнаружили рядом с Цитаделью Адского Пламени три форта. Мы должны их захватить. Помоги нашим войскам и доложи мне, когда все три перейдут к нам.$B$BПусть удача сопутствует тебе в битве, $N. Скорее всего, Орда тоже положила глаз на эти укрепления, так что тебе придется иметь дело с ее войсками.', 'Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь к прапорщику Трейси Праудвелл в Оплот Чести на Полуострове Адского Пламени.', 'Ты славно потрудился, $N. Благодаря твоим ратным подвигам мы еще долго продержимся на Полуострове Адского Пламени!', NULL, NULL, NULL, 'Захватите Обзорную площадку', 'Захватите Ристалище', 'Захватите Изрезанный холм', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13409, 'Штурмовые укрепления', 'Мы должны стереть проклятых орков Скверны с лица нашей земли! Но перед тем, как напасть на Цитадель Адского Пламени, необходимо укрепить позиции.$B$BГонцы обнаружили три форта, которые хорошо подходят для наших целей. К сожалению, Альянсу пришла в голову та же идея, и он уже выдвинул войска, чтобы захватить эти укрепления.$B$BТы $gдолжен:должна: отбросить силы Альянса и помочь нашему войску захватить все три форта. Когда выполнишь это задание, возвращайся ко мне.$B$BВо славу Орды!', 'Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.', 'Славная работа, $N. Я как наяву слышу звуки битвы, которая там разыгралась. Хотела бы я это видеть своими глазами!', NULL, NULL, NULL, 'Захватите Обзорную площадку', 'Захватите Ристалище', 'Захватите Изрезанный холм', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13410, 'Штурмовые укрепления', 'Цитадель Адского Пламени уже долгое время отбивает все наши атаки. Мы сохраняем позиции, но не можем перейти в решительное наступление. Нам необходимо укрепить передовые.$B$BРазведчики обнаружили рядом с Цитаделью Адского Пламени три форта. Мы должны их захватить. Помоги нашим войскам и доложи мне, когда все три перейдут к нам.$B$BПусть удача сопутствует тебе в битве, $N. Скорее всего, Орда тоже положила глаз на эти укрепления, так что тебе придется иметь дело с ее войсками.', 'Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь к прапорщику Трейси Праудвелл в Оплот Чести на Полуострове Адского Пламени.', 'Ты славно потрудился, $N. Благодаря твоим ратным подвигам мы еще долго продержимся на Полуострове Адского Пламени!', NULL, NULL, NULL, 'Захватите Обзорную площадку', 'Захватите Ристалище', 'Захватите Изрезанный холм', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13411, 'Штурмовые укрепления', 'Мы должны стереть проклятых орков Скверны с лица нашей земли! Но перед тем, как напасть на Цитадель Адского Пламени, необходимо укрепить позиции.$B$BГонцы обнаружили три форта, которые хорошо подходят для наших целей. К сожалению, Альянсу пришла в голову та же идея, и он уже выдвинул войска, чтобы захватить эти укрепления.$B$BТы $gдолжен:должна: отбросить силы Альянса и помочь нашему войску захватить все три форта. Когда выполнишь это задание, возвращайся ко мне.$B$BВо славу Орды!', 'Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.', 'Славная работа, $N. Я как наяву слышу звуки битвы, которая там разыгралась. Хотела бы я это видеть своими глазами!', NULL, NULL, NULL, 'Захватите Обзорную площадку', 'Захватите Ристалище', 'Захватите Изрезанный холм', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13412, 'Корастраза', 'Привет тебе, $C. Я могу попросить тебя об услуге?$B$BУ красного дракона Релораза, командующего нашим аванпостом, есть сестра, Корастраза. Против его воли она поднялась в одно из верхних колец Нексуса, чтобы увидеть фантастически могущественных синих драконов.$B$BОн, конечно, не подает виду, но его беспокоит судьба сестры , и ему будет приятно узнать, что с ней ничего не случилось.$B$BПожалуйста, разыщи ее. И попроси ее на время забыть о гордости и послать весточку брату.', 'Поговорите с Корастразой в Хладарре по просьбе библиотекаря Серры.', 'Тебе не кажется, $R, что смертным негоже влезать в личные дела драконов?$B$BНу ладно, с моей стороны было бы несправедливо держать брата в неведении. Можешь передать своему невежливому другу, который так любит вмешиваться в чужие дела, что я буду держать брата в курсе.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13413, 'Асы, ввысь!', 'Ты настолько $gотважен и дерзок, смертный:дерзка и отважна: смертная;, что не боишься приблизиться к логову Малигоса? Или ты просто не знаешь, чем это грозит? Ладно, скоро мы это узнаем...$B$BЯ давно тренирую красных драконов. Моя задача: изучить врага и обучить моих питомцев такой тактике боя, которая будет наиболее эффективной, когда придет время сразиться с повелителем синих драконов.$B$BЯ хочу посмотреть тебя в деле – понять, на что ты $gспособен:способна:. И поэтому я разрешаю тебе взять одного из моих питомцев и вылететь на боевое задание.$B$BТебе стоит лишь попросить – и мои драконы в твоем распоряжении.', 'Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев.', 'Мой дракон говорит мне, что если ты потренируешься, из тебя выйдет хороший боец.$B$BНу что же. Ради победы над Малигосом я разрешу тебе тренироваться с моими питомцами, но только в свободное время.$B$BПодготовься как следует, $R, он – свирепый и беспощадный противник.', NULL, NULL, NULL, 'Чешуекляты-гвардейцы убиты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13414, 'Асы, ввысь!', 'Мы снова встретились, $r. Надо признаться, я уже начинаю к тебе привыкать.$B$BВерно ли я понимаю, что ты $gпришел:пришла: тренироваться, чтобы отточить свои навыки воздушного боя?$B$BМои питомцы всегда готовы сеять панику и разрушения в стане врага.$B$BТебе стоит лишь попросить – и они в твоем распоряжении.', 'Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев.', 'Сегодня, $C, у тебя получилось значительно лучше. Временами казалось, что ты составляешь одно целое с драконом.$B$BМожешь тренироваться с моими питомцами. В свободное время.', 'Да, $R?', NULL, NULL, 'Убито чешуеклятов-гвардейцев', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13415, 'Пульт в библиотеке', 'Мы знаем, где оболочка Норганнона, $N. Возьми диск изобретателя и иди в библиотеку. Там должен быть пульт, который нужно активировать с помощью этого диска. Я так думаю, Мимир спрятал там не только оболочку. Вполне вероятно, что там есть запас схем, которого инженерам Стальгорна хватит на несколько лет бесперебойной работы!$B$BВ любом случае, воспользуйся диском, чтобы добраться до оболочки. Будем надеяться, что фантазия Мимира на этом иссякла, и новые препятствия не предвидятся.', 'Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя.', '<Вы вставляете диск в предназначенную для него панель. На пульте внезапно включаются лампочки и вы слышите механический голос.>$B$BПодлинность диска изобретателя удостоверена. С возвращением, хранитель Мимир.', 'На пульте есть специальная панель, которая, кажется, предназначена как раз для диска изобретателя.', NULL, NULL, 'Диск Изобретателя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13416, 'Пульт в библиотеке', 'Мы знаем, где оболочка Норганнона, $N. Возьми диск изобретателя и иди в библиотеку. Там должен быть пульт, который нужно активировать с помощью этого диска. Я так думаю, Мимир спрятал там не только оболочку. Вполне вероятно, что там есть запас схем, которого инженерам Стальгорна хватит на несколько лет бесперебойной работы!$B$BВ любом случае, воспользуйся диском, чтобы активировать пульт. Будем надеяться, что фантазия Мимира на этом иссякла, и новые препятствия не предвидятся.', 'Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя.', '<Вы вставляете диск в предназначенную для него панель. На пульте внезапно включаются лампочки и вы слышите механический голос.>$B$BПодлинность диска изобретателя удостоверена. С возвращением, хранитель Мимир.', 'В панели, похоже, есть отверстие, предназначенное для диска изобретателя.', NULL, NULL, 'Диск Изобретателя (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13417, 'Братья Бронзобороды', 'Вот оно! Наконец-то у нас есть краеугольный камень... Какая красота! Я немало попутешествовал по миру, но эта вещь снова приводит меня в восторг. Хотя сейчас явно не время застывать в эстетическом ступоре, восхищаться и ахать я буду потом, а сейчас надо скорее выбираться отсюда!$B$BЗабирайся в мой ветролет и прикрывай нас от железных дворфов!', 'Прикрывайте Бранна Бронзоборода и его ветролет, пока не доберетесь до Ледяной крепости.', '', NULL, NULL, NULL, 'Сопровождение Бранна Бронзоборода в Ледяную Крепость.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13418, 'Подготовка к войне', 'Эй, ты!$B$BДа, я к тебе обращаюсь. С виду ты, вроде, $gнеглупый парень:неглупая барышня:. А нам тут, в Ледяной Короне, нужны адекватные кадры. И чем больше, тем лучше!$B$BТы, наверное, $gслышал:слышала:, что нам не удалось захватить ледник с земли, но пусть тебя это не слишком тревожит. Сейчас мы готовим новую атаку. Мы ударим по ним с нашего нового боевого корабля, который построен с помощью самых продвинутых технологий во всем Азероте. Против нашего \"Усмирителя небес\" не выстоять никому: ни Орде, ни Артасу.$B$BДай мне знать, когда будешь $gготов:готова: отправиться в путь.', 'Поговорите с офицером ван Россемом, который переправит вас на борт \"Усмирителя небес\" в Ледяной Короне, а потом побеседуйте со старшим капитаном Джастином Бартлеттом.', 'Добро пожаловать на \"Усмиритель небес\".$B$BЗдесь мы готовимся к атаке на Артаса. Как говорится, хорошая подготовка – залог успеха. Нам предстоит еще многое сделать, но прежде чем приступать к основной части, мы должны позаботиться о том, чтобы Серебряный Авангард получил необходимое подкрепление – когда придет время, нам понадобится их помощь.$B$BИди на верхнюю палубу и поговори с Абсаланом Благочестивым.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13419, 'Подготовка к войне', 'Эй, ты!$B$BДа, я к тебе обращаюсь. С виду ты, вроде, $gнеглупый парень:неглупая барышня:. А нам тут, в Ледяной Короне, нужны адекватные кадры. И чем больше, тем лучше!$B$BЭти мерзавцы из Альянса вошли в Ледяную Корону раньше нас, рванули без подготовки и получили именно то, что вполне заслужили из-за своего нетерпения. А мы не спешили. Мы подготовились как следует и уже очень скоро пойдем в атаку. Мы ударим по ним с нашего нового боевого корабля, который построен с помощью самых продвинутых технологий во всем Азероте. Против нашего \"Молота Оргрима\" не выстоять никому: ни Альянсу, ни Артасу.$B$BДай мне знать, когда будешь $gготов:готова: отправиться в путь и оказать нам посильную помощь.', 'Поговорите с покорителем небес Клумом, который переправит вас на борт \"Молота Оргрима\" в Ледяной Короне, а потом побеседуйте с покорителем небес Кормом Черным Шрамом.', 'Добро пожаловать на \"Молот Оргрима\".$B$BЗдесь мы готовимся к атаке на Артаса. Как говорится, хорошая подготовка – залог успеха. Нам предстоит еще многое сделать, но прежде чем приступать к основной части, мы должны позаботиться о том, чтобы Серебряный Авангард получил необходимое подкрепление – когда придет время, нам понадобится их помощь.$B$BИди на верхнюю палубу и поговори с братом Кельтаном.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13420, 'Вечный лед', 'Этот кусок льда подвергся очень сильному давлению и воздействию природной магии – где-то на большой глубине. В результате получился лед, который никогда не тает.$B$BМало что понимая в таких вещах, вы решаете отнести образец этого странного льда в Дун Ниффелем. Наверняка там есть кто-то, кто знает, что это такое.', 'Возвращайтесь в Дун Ниффелем и расспросите Кальдера насчет осколка Вечного льда.', '<Кальдер поднимает осколок Вечного льда к свету, в его глазах отражаются искрящиеся грани.>$B$BАаа, Вечный лед. Символ духа нашего народа...$B$BКогда-то его было здесь так много... Но за прошедшие века йормунгары уничтожили почти все. Теперь это большая редкость, которая ценится больше золота среди моего народа.$B$BУ меня к тебе просьба: пока будешь в здешних краях, ты посматривай по сторонам – если найдешь еще осколки, приноси их мне. А я найду, чем тебя отблагодарить.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13421, 'Больше Вечного льда!', '', 'Ты нашел еще Вечный лед, $C?', 'Замечательно, малыш $r.$B$BКогда-то здесь было много Вечного льда. Но за прошедшие века йормунгары уничтожили почти все. Теперь это большая редкость, которая ценится больше золота среди моего народа.$B$BУ меня к тебе просьба: пока будешь в здешних краях, посматривай по сторонам – если найдешь еще осколки, приноси их мне. А я найду, чем тебя отблагодарить.', NULL, NULL, NULL, 'Частичка Вечного льда', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13422, 'Поучить уму-разуму', 'Ты преуспела там, где другие потерпели поражение. Но почивать на лаврах еще рано.$B$BПокажи остальным, что такое настоящие сила и преданность!$B$BНепокорные врайкулы из Заброшенного рудника снова нуждаются во вразумлении. Покажи им, сестра, каково это – не повиноваться нам!', 'Накажите 6 обессиленных врайкулов из Заброшенного рудника с помощью вразумляющего жезла по заданию Гретты Судьи из деревни Бруннхильдар.', 'Ты снова подаешь всем пример. Мы рассчитываем на тебя, сестра!', NULL, NULL, NULL, 'Наказано обессиленных врайкулов', 'Вразумляющий жезл', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13423, 'Подтверждение победы', 'Все восхищены тобой, сестра. Но не теряй бдительности: любая из сестер, жаждущая славы, может попытаться отобрать у тебя титул королевы хильд!$B$BПокажи этим бездарностям, на что ты способна!', 'Одержите победу над 6 дуэлянтами-победителями по заданию Гретты Судьи из деревни Бруннхильдар.', 'Ты снова показала себя самой достойной. Твое присутствие делает нам честь!', NULL, NULL, NULL, 'Дуэлянт-победитель убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13424, 'Обратно в Яму Клыка', 'Чтобы оставаться в форме, нужно ежедневно соревноваться с другими хильдами!$B$BОтправляйся обратно в Яму Клыка и покажи всем, на что ты способна. Для них будет честью проиграть в поединке с тобой.', 'Отправляйтесь в Яму Клыка, воспользуйтесь поводьями матриарха ледочревов и победите 6 боевых медведей Круга хильд по заданию Гретты Судьи из деревни Бруннхильдар.', 'Ты снова доказала свою доблесть. Сестры не утратили уважения к тебе!', NULL, NULL, NULL, 'Боевой медведь Круга хильд убито', 'Поводья боевой медведицы-матриарха', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13425, 'Смерть гнусным тварям!', 'Доказать свою доблесть среди равных недостаточно, дорогая сестра. Нам ведь нужно еще и сражаться с врагами!$B$BПредательницы из Валькириона по-прежнему издеваются над нашими благородными традициями, выращивая зараженных протодраконов.$B$BВозьми масло льда, которое они используют, и заморозь эти гнусные яйца.', 'По заданию Гретты Судьи из деревни Бруннхильдар отправляйтесь в Валькирион и добудьте у валькирионских претенденток флаконы масла льда. Используйте флаконы масла льда, чтобы уничтожить 30 зачумленных яиц протодраконов.', 'Героиня в одном – героиня во всем! Мы благодарим тебя, сестра.', NULL, NULL, NULL, 'Зачумленное яйцо протодракона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13426, 'Ксанатавр, Свидетель', 'Похоже, мы тут не единственные гости. Гонец принес записку от таурена по имени Ксанатавр, который сообщает, что находится в деревне таун\'ка под названием лагерь Тунка\'ло. Записка была написана немного непонятно, но, кажется, этот самый Ксанатавр прибыл на Грозовую Гряду для изучения истории и легенд народа таунка.$B$BВстреться с ним, $N. Узнай – вдруг то, что он знает, может каким-то образом помочь нам. Из описания следует, что лагерь Тунка\'ло находится далеко на восток отсюда, над Террасой Творцов, к северу от Дун Ниффелема.', 'Поговорите с Ксанатавром в лагере Тунка\'ло.', 'Так Боктар получил мое послание? Это отличная новость. Я сомневался, что гонец, который должен был ее доставить, до кого-нибудь доберется.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13427, 'К оружию! Альтеракская долина', 'Беда битвы на несколько фронтов, $gпарень:подруга:, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление.Сегодня войскам в Альтеракской долине требуются отважные бойцы.$B$BСтупай прямо сейчас, $N, и помоги стражам Грозовой Вершины. Мы не можем допустить, чтобы клан Северного Волка ушел без возмездия после всего того зла, что они причинили нашим собратьям!', 'Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Это мне и хотелось услышать! Победа в Альтеракской долине – пусть и временная – необходимое звено в нашей общей стратегии войны с Ордой.', NULL, NULL, NULL, 'Победа в Альтеракской долине', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13428, 'К оружию! Альтеракская долина', 'Мы почти изгнали врагов, что вторглись в Альтеракскую долину из Грозовой Вершины. Теперь надо перебросить наши силы на помощь клану Северного Волка.$B$BРешительная победа позволит нам высвободить ресурсы, необходимые для сокрушения этих подонков из Альянса на всех остальных фронтах.$B$BСтупай, $N. Заслужи великую честь, откликнувшись на зов отважных воинов клана Северного Волка.', 'Победите на поле боя Альтеракской долины и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Нет высшей чести, чем изгнать захватчиков с земель Орды! Сегодня мы славим твою отвагу и благодарим тебя за помощь нашим войскам!', 'Ты вернулся с вестями о нашей победе?', NULL, NULL, 'Победа в Альтеракской долине', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13429, 'Отвлекающий маневр', '$gКси\'ри излучает пульсирующее сияние, отдавая приказания войскам Алдоров и Провидцев. Армия Кси\'ри готова отбросить силы Иллидана и тем самым отвлечь их, чтобы Акама мог проникнуть в храм. Наару ждет вашего сигнала, чтобы начать атаку.:', 'Убедитесь, что Акама и Майев вошли в Черный храм в долине Призрачной Луны после того, как войска Кси\'ри совершат отвлекающий маневр.', '', NULL, NULL, NULL, 'Помогите Акаме и Майев войти в Черный Храм.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13430, 'Испытание наару: Магтеридон', 'Прежде чем наару признают тебя достойным, тебе предстоит пройти четыре испытания.$B$BОсталось лишь одно препятствие, $gсмертный:смертная:. Собери армию побольше и отправляйся в логово Магтеридона в глубины Цитадели Адского Пламени. Пробейся в центральный чертог и убей гнусного сеятеля скверны!', 'По заданию А\'дала из Шаттрата убейте Магтеридона.', 'Ты сумел доказать нам свое могущество. Наару согласны...', NULL, NULL, NULL, 'Магтеридон убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13431, 'Дубина Кардеша', 'Для создания оружия мне необходимы эталоны стихий. Принеси мне их!$B$BЭталон земли ты найдешь в логове Груула Драконобоя в Острогорье.$B$BЭталон огня – это сердце существа, именуемого Ночной Погибелью. Это легендарное чудовище по слухам обитает в священных залах пророка Медива.$B$BПоторопись!', 'Принесите эталоны земли и огня Скартису Еретику в Узилище (героический уровень сложности) в Резервуар Кривого Клыка.', 'Наконец-то! $B$BМои оковы разбиты, и скоро эта дубина обрушится на голову проклятой морской ведьмы и повергнет ее обратно в ледяные глубины...', 'Когда я воссоздам дубину, я разобью свои оковы и отправлюсь в Змеиное Святилище свершить возмездие над Вайш и ее прихвостнями!', NULL, NULL, 'Печать земли', 'Печать огня', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13432, 'Сосуды Вечности', 'Иллидан наполнил семь сосудов из Источника Вечности. Три из них он вылил в озеро на горе Хиджал и создал второй Источник. Долгое время считалось, что остальные четыре сосуда были утрачены.$B$BНо после того как открылся Темный портал, мы узнали, что Иллидан отдал по одному сосуду своим лейтенантам Кел\'тасу и Вайш. Найди эти сосуды и принеси нам. Без них мы не можем открыть временные проходы к событиям, так или иначе связанным с горой Хиджал, – ни к недавним, ни к древним. Мы должны позаботиться о том, чтобы ничто не смогло изменить исход битвы за Хиджал.', 'Соридорми из Пещер Времени желает, чтобы вы принесли ей неполный фиал Леди Вайш из Резервуара Кривого Клыка и неполный фиал Кель\'таса из Крепости Бурь.', 'Даже в одной капле воды из Источника Вечности заключены невероятные силы.$B$BТеперь я могу прозревать время и видеть все, что когда-либо происходило в Хиджале... Создание второго Источника Вечности, пленение Иллидана, заклятие Мирового Древа и... О, да! Битва за Хиджал!$B$BМы должны поспешить, иначе эта линия времени будет разрушена.', 'Я знаю, что прошу невозможного, но все равно верю в тебя. Сейчас судьба мира – в твоих руках.', NULL, NULL, 'Неполный фиал Вайш', 'Неполный фиал Келя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13433, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
