INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13475, 'Великая честь', '', '', '', NULL, NULL, NULL, 'Почетный знак Берега Древних', 'Почетный знак Низины Арати', 'Почетный знак ущелья Песни Войны', 'Почетный знак Ока Бури');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13476, 'Великая честь', 'Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.$B$BСтупай же и вступи в схватку с Альянсом на всех фронтах. За честь! За Орду!', 'Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.', '', NULL, NULL, NULL, 'Почетный знак ущелья Песни Войны', 'Почетный знак Низины Арати', 'Почетный знак Берега Древних', 'Почетный знак Ока Бури');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13477, 'В едином порыве', '', '', '', NULL, NULL, NULL, 'Почетный знак Берега Древних', 'Почетный знак Низины Арати', 'Почетный знак ущелья Песни Войны', 'Почетный знак Ока Бури');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13478, 'В едином порыве', 'В войне против Орды решающей может оказаться любая битва, $gсынок:дочка:.$B$BПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.$B$BАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.', 'Принесите почетные знаки каждого поля боя бригадному генералу Альянса в любую столицу Альянса или в Шаттрат.', '', NULL, NULL, NULL, 'Почетный знак Берега Древних', 'Почетный знак Низины Арати', 'Почетный знак ущелья Песни Войны', 'Почетный знак Ока Бури');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13479, 'Большая охота за яйцами', 'Ах, Сад чудес, праздник весны и жизни! Надеюсь, тебе понравилось собирать яйца, $gдруг:дорогая:, потому что мне как раз $gнужен проворный помощник:нужна проворная помощница:.$B$BЯ не знаю, какую магию использовали при создании этих яиц, а друиды играют со мной в молчанку. Будешь разбивать яйца – сохрани для меня осколки скорлупы. Содержимое яиц можешь оставить себе, мне же понадобятся только скорлупки.', 'Принесите весеннему сборщику 20 осколков раскрашенной яичной скорлупы.', '', NULL, NULL, NULL, 'Осколок раскрашенной скорлупы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13480, 'Большая охота за яйцами', 'Ах, Сад чудес, праздник весны и жизни! Надеюсь, тебе понравилось собирать яйца, $gдруг:дорогая:, потому что мне как раз $gнужен проворный помощник:нужна проворная помощница:.$B$BЯ не знаю, какую магию использовали при создании этих яиц, а друиды играют со мной в молчанку. Будешь разбивать яйца – сохрани для меня осколки скорлупы. Содержимое яиц можешь оставить себе, мне же понадобятся только скорлупки.', 'Принесите весеннему собирателю 20 осколков раскрашенной яичной скорлупы.', '', NULL, NULL, NULL, 'Осколок раскрашенной скорлупы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13481, 'Валим отсюда!', 'Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих \"работ\".$B$BЯ не могу уйти сам, но с твоей помощью, $C, мне, может быть, и удастся спастись, и я еще повоюю с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?', 'Проводите отца Камароса в безопасное место и доложите об этом брату Кельтану на борту \"Молота Оргрима\".', 'Ты все сделал правильно. Мы боялись, что отец Камарос погиб. Твоя храбрость станет примером для всех, кто сражается с силами Плети.', NULL, NULL, NULL, 'Проводить отца Камароса в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13482, 'Валим отсюда!', 'Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих \"работ\".$B$BЯ не могу уйти сам, но с твоей помощью, $C, мне, может быть, и удастся спастись, и я еще повоюю с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?', 'Проводите отца Камароса в безопасное место, а затем сообщите об этом Абсалану Благочестивому на борту \"Усмирителя небес\".', '', NULL, NULL, NULL, 'Проводить отца Камароса в безопасное место', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13483, 'Весенние сборщики', 'Если тебе не сидится на месте, то поищи магов в поселениях рядом со столицами – в Колючем Холме, Брилле, деревне Кровавого Копыта и на Площади Соколиных Крыльев. Им нужна помощь в каких-то исследованиях, и они нанимают большое количество охотников за яйцами. Больше сказать не могу, подробности узнаешь у магов.', 'Поговорите с весенним сборщиком в Колючем Холме, Брилле, деревне Кровавого Копыта или Площади Соколиных Крыльев.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13484, 'Весенние собиратели', 'Если тебе не сидится на месте, то поищи магов в поселениях рядом со столицами – в Златоземье, Караносе, Доланааре и на Лазурной заставе. Им нужна помощь в каких-то исследованиях, и они нанимают большое количество охотников за яйцами. Больше сказать не могу, подробности узнаешь у магов.', 'Поговорите с весенним собирателем в Златоземье, Караносе, Доланааре или на Лазурной заставе.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
