INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13501, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13502, 'Что вам надо? Шоколада!', 'Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.', 'Соберите 10 праздничных шоколадных яиц и отдайте их продавцу Сада чудес вместе с корзиной для яиц.', '', NULL, NULL, NULL, 'Праздничное шоколадное яйцо', 'Корзина для яиц (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13503, 'Что вам надо? Шоколада!', 'Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.', 'Соберите 10 праздничных шоколадных яиц и отдайте их торговцу Сада чудес вместе с корзиной для яиц.', '', NULL, NULL, NULL, 'Праздничное шоколадное яйцо', 'Корзина для яиц (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13524, 'Побег из Среброречья', 'Ты… ты не $gодин:одна: из них? Быстрее! Освободи меня!$B$BНам нужно немедленно отправляться в Приют Янтарной Сосны! Как только лейтенант Думонт узнает, кто эти люди на самом деле, он камня на камне не оставит от этого города!', 'Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Доложитесь лейтенанту Думонту по прибытии в Приют Янтарной Сосны.', '', NULL, NULL, NULL, 'Побег из Среброречья', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13538, 'Южный саботаж', 'Три башни южнее реки Ледяных Оков вытягивают энергию из Крепости!$B$BУничтожь башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, затем возвращайся ко мне. И помни, только осадные машины могут навредить башне, поэтому тебе следует защищать их от Орды!', 'Уничтожьте башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, а затем вернитесь к офицеру-стратегу Абрамису на Озере Ледяных Оков.', 'Я слышал этот взрыв! Неплохо сработано! Мы уже приступили к перенаправлению энергии в реликвию $Nв, чтобы наделить наши войска суперсилой.', NULL, NULL, NULL, 'Уничтожена одна из трех южных башен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13539, 'Свержение башен', 'Хотя Альянс у нас на пороге, настоящий стратег всегда заглядывает дальше собственного носа.$B$B\"Напади там, где враг не готов дать отпор; появись там, где тебя не ждут.\"$B$B$N, я хочу, чтобы ты $gотправился:отправилась: через Реку Ледяных Оков и $gуничтожил:уничтожила: одну из башен на юге. Наши чернокнижники докладывают, что башни оттягивают энергию, которую мы могли бы использовать, чтобы укрепить наши войска.$B$BВозвращайся ко мне, как только ты разрушишь одну из башен.', 'Уничтожьте башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, затем вернитесь к офицеру-стратегу Килрату.', 'Чтобы убивать врагов, наших воинов нужно рассердить. Они должны знать, что после победы над врагом, награда не заставит себя ждать. Надеюсь это достойная плата за твою службу Орде.', NULL, NULL, NULL, 'Уничтожена южная башня', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13548, 'Кулек конфет', '', '', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13549, 'Хвост трубой', 'Помимо артефактов Драккари, меня также интересует животный мир Зул\'Драка. Мне бы очень хотелось привезти в Зандалар некоторые образцы местной фауны. У меня уже есть самцы леопарда и ледопалого медведя, но теперь мне нужно несколько самочек!$B$BК великому сожалению, мой ловчий внезапно скончался. Может быть, ты подменишь его?$B$BПожалуйста, возьми это ружье, оно стреляет усыпляющими дротиками. Усыпи зверя и загляни ему под хвост. Запомни – меня интересуют самки. Леопарды и медведи водятся возле алтарей Рунока, Кетц\'лун и Хар\'коа.', 'По просьбе летописца То\'кини из Зим\'Торги усыпляйте из воздушного ружья То\'кини северных леопардов и ледолапых медведей. Возвращайтесь к нему, поймав по три самки каждого вида.', 'Это прекрасные экземпляры, $N! теперь у моих коллег будет достаточно материала для изучений.', NULL, NULL, NULL, 'Обнаружено самок северного леопарда', 'Обнаружено самок ледолапого медведя', 'Воздушное ружье То\'кини', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13556, 'Яйца для Дубра\'джина', 'Как дела, $gпацан:деваха:? Думаешь, ты сможешь мне помочь? Ба\'Кини понадобится много яиц ящера для жертвоприношений Дубра\'джину.$B$BЕсли бы не ритуалы, нас давно бы уже поработили драккари! Дубра\'джин помогает нам!$B$BСобери яйца ящеров под деревьями здесь, в Гундраке. Иногда ящеры носят их с собой, чтобы держать их в тепле.', 'Соберите 12 яиц ящера Гундрака по заданию Га\'ваны из Дубра\'джина.', 'Ха-ха, достаточно, дружище! Теперь мы надолго в безопасности!', 'Кто бы мог подумать, что великому Дубра\'джину будет нужно столько яиц! Интересно, что он будет с ними делать?', NULL, NULL, 'Яйцо ящера Гундрака', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13559, 'Подношение Ходиру', '', '', 'Сыны Ходира принимают твое подношение, кроха. Ты не перестаешь доказывать свою ценность как нашего союзника.', NULL, NULL, NULL, 'Реликвия Ульдуара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13571, 'Бюро находок Флетчера', '', '', 'Вы чувствуете, как сквозь кислый запах немытого тела пробивается знакомый аромат! Похоже, этот некогда могучий искатель приключений знает толк в кунгалуше.Всматриваясь в пленника сквозь прутья решетки, вы едва различаете строки рецепта, нацарапанные у него на руке...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13592, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', 'Убейте 10 обращенных героев по заданию сэра Маркуса Барлоу из Павильона Серебряного союза на Ристалище Серебряного турнира.', 'С возвращением, $N. Даже во время тренировок мы не должны забывать о реальной угрозе, с которой придется иметь дело после окончания турнира.', 'Испытал ли ты свои силы в борьбе с Плетью?', NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13593, 'Искатель славы из Штормграда', 'Приветствую тебя, чемпион. Я наслышан о твоих достижениях! Буду рад включить тебя в число участников делегации Штормграда, если ты желаешь к нам присоединиться.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Штормграда позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Штормграда, поговорите еще раз с маршалом Якобом Алерием в Павильоне Серебряного союза.', 'Добро пожаловать, $N. Штормград рад принять тебя в ряды своих воинов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13600, 'Достойное оружие', 'Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', 'Принесите меч Драк\'Мара маршалу Якобу Алерию в Павильон Серебряного союза на Ристалище Серебряного турнира.', '<Маршал принимает у вас меч Драк\'мара.>$B$BПрекрасное оружие, отлично сбалансировано... этот клинок сослужит мне добрую службу в следующем поединке.', 'Ну что – бард не соврал? Где меч?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13603, 'Клинок, достойный чемпиона', 'Честно выкованные клинки нынче не в моде. Все мои соперники обзавелись заколдованными мечами, где мне с ними тягаться. Однако не все еще потеряно.$B$BДревняя легенда рассказывает о девушке, живущей в Седых холмах, у которой есть замечательный волшебный меч... Но вот незадача, ее превратили в лягушку, чтобы никто не смог заполучить этот клинок. Теперь она живет среди лягушек на Ясеневом озере, что к востоку от Ясеневой заставы. Говорят, что чары может развеять только поцелуй. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его маршалу Якобу Алерию в Павильон Серебряного союза на Ристалище Серебряного турнира.', 'Значит, легенда оказалась правдой? Прекрасный меч! С ним я выиграю любой турнир. Большое тебе спасибо, Игдежехилл.', 'Тебе удалось достать меч?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13604, 'Диск доступа к Архиву', 'Платиновый диск правильной формы выглядит совершенно новым – на нем нет ни единой царапины. По краю его выгравирована руническая надпись: \"АРХИВ\".$B$BДолжно быть, в глубинах Ульдуара есть устройство, с помощью которого можно прочитать этот диск.', 'Отнесите диск доступа к Архиву к панели управления Архивом в Ульдуаре.', 'Платиновый диск идеально подходит к гнезду на панели. Он начинает вращаться, белые лучи считывают с него какую-то информацию.', 'Гнездо приемника открывается, а панель управления жужжит и вибрирует.', NULL, NULL, 'Диск доступа к Архиву (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13606, 'Печать Фрейи', 'Печать Фрейи достать будет сложнее всего.$B$BСогласно данным из Архива, сущность печати связана с тремя старшими слугами Фрейи – Светлым Листом, Железной Ветвью и Каменной Корой. Если хоть один из них пострадает, сущность печати будет повреждена.$B$BНо если ты пощадишь слуг, силы Фрейи приумножатся.$B$BЧто еще сказать, $N... оказались мы между молотом и наковальней.', 'Добудьте печать Фрейи по заданию геолога Дорена.За дополнительными сведениями обратитесь к панели управления Архивом.', 'Молодчина, $N! Мы уже на шаг ближе к спасению Азерота!', 'Ты добыл печать Фрейи, $N?', NULL, NULL, 'Печать Фрейи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13607, 'Священный планетарий', 'Слушай внимательно! На кону – судьба всего Азерота.$B$BТолько одно спасет нас – нужно найти Священный планетарий и помешать этому Алгалону отправить сообщение его повелителям-титанам.$B$BОтыщи Священный планетарий и возвращайся со всеми данными, которые сможешь там собрать. Может быть, мы успеем подготовиться к прибытию Алгалона.', 'Найдите Священный планетарий по заданию геолога Дорена из Архива в Ульдуаре.', 'Закрыт? Так я и думал!$B$BДавай-ка посмотрим, что расскажет нам эта куча металлолома...', 'Ты нашел его, $N?', NULL, NULL, 'Исследовать локацию', 'Вход в Священный планетарий найден', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13609, 'Печать Ходира', 'Печать Ходира будет нелегко раздобыть. Во-первых, тебе придется одолеть самого Ходира. А во-вторых, одолеть его нужно до того, как он уничтожит сундук с печатью!$B$BВоспользуйся панелью управления Архивом, чтобы получить дополнительные сведения. Эта премудрая штуковина стоит всех библиотек мира!', 'Добудьте печать Ходира по заданию геолога Дорена.За дополнительными сведениями обратитесь к панели управления Архивом.', 'Потрясающе! Не знаю, как ты это сделал, но тебе это удалось!', 'Ну что, $N, где печать?', NULL, NULL, 'Печать Ходира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13610, 'Печать Торима', 'Торим не в себе, $N. Он во власти темных сил.$B$BТемная сущность приняла обличье его погибшей жены, Сиф.$B$BНельзя позволить иллюзии свести его с ума. Если это случится, то мы никогда не сможем найти печать Торима!$B$BВразуми его, и побыстрее.$B$BКак обычно, за подробностями этой жуткой истории можешь обратиться к панели управления Архивом... но они вряд ли тебе понравятся.', 'Добудьте печать Торима по заданию геолога Дорена.За дополнительными сведениями обратитесь к панели управления Архивом.', 'Ты не прекращаешь удивлять меня, Рокхан.$B$BДавай выпьем по кружечке после того, как все это закончится!', 'Итак, $N... Печать у тебя?', NULL, NULL, 'Печать Торима', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13611, 'Печать Мимирона', 'Мимирон хитер – в его комнате установлен какой-то механизм самоуничтожения.$B$BЕсли хочешь получить его печать, тебе придется победить его до того, как механизм завершит свой цикл. Если тебе нужно больше информации – воспользуйся панелью управления Архивом.', 'Добудьте печать Мимирона по заданию геолога Дорена.За дополнительными сведениями обратитесь к панели управления Архивом.', 'Надо отдать тебе должное, $N: шансы у нас неважные, но я чувствую себя гораздо увереннее с тех пор, как ты сражаешься на моей стороне.', 'Ну что, $N, где печать?', NULL, NULL, 'Печать Мимирона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13614, 'Алгалон', 'Ты $gсправился:справилась:, $N. Теперь возьми печати, отнеси их к панели управления Архивом и попытайся получить доступ к Священному планетарию.$B$BПоторопись, $gдруг:подруга: – дорога каждая секунда.', 'Принесите печати хранителей к панели управления Архивом в Ульдуаре.', 'Ожидайте подтверждения.$B$BДоступ в Священный планетарий разрешен. Пожалуйста, возьмите ключ.', 'Яркие лучи панели периодически освещают стеклянную поверхность, как будто ожидают ввода данных.', NULL, NULL, 'Печати хранителей (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13616, 'Клинок Зимы', 'Проклятый рыцарь смерти сломал мой клинок.$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Маршал Якоб Алерий из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', 'Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, Игдежехилл.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13622, 'Древняя история', 'Из кусочков вам удается сложить прекрасный боевой молот. Сразу заметно, что к созданию молота приложили руку титаны.$B$BПанель управления в Архиве наверняка содержит немало интересных сведений об этом оружии.', 'Принесите расколотый Вал\'анир к панели управления в Архив Ульдуара.', '', NULL, NULL, NULL, 'Расколотый Вал\'анир (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13625, 'Большая тренировка', 'Большая часть состязаний турнира требует от участников мастерства в управлении верховым животным. Чтобы познакомить тебя с этим видом поединков, мы разместили тренировочные манекены в северной части Ристалища турнира.$B$BЗайди в стойла на севере площадки, рядом с главной ареной, вооружись копьем и оседлай кель\'дорайского скакуна. Познакомься со всеми доступными приемами и используй новые знания в тренировке. Для освоения новых приемов можешь использовать все три вида манекенов.', 'Отработайте прием \"Выпад\" 5 раз на манекене для ближнего боя, прием \"Удар по щиту\" 2 раза на мишени для дальнего боя и прием \"Рывок\" 2 раза на манекене для стремительной атаки, затем вернитесь к разведчице Шалиндрии на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Молодец, $N. Не все воины легко осваивают приемы верхового поединка. Я не сомневаюсь, что ты продолжишь тренировки и превзойдешь многих воинов в этом виде состязаний.', 'Как прошла твоя тренировка?', NULL, NULL, 'Манекен для ближнего боя поражен', 'Мишень для дальнего боя поражена', 'Манекен для стремительной атаки поражен', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13627, 'Откуда дровишки?', 'Эй, иди сюда!.. Да не так близко, нас могут увидеть!$B$BДля постройки Колизея нужно гораздо больше дерева, чем я предполагал, а заказывать еще одну партию из Седых холмов я не стану ни за какие коврижки. В общем, слушай: на западной границе леса Хрустальной Песни, у Великого древа, растут молодые дубы.$B$BИх древесина как нельзя лучше подходит для строительства и возведения лесов. Возьми этот топор, повали несколько дубов Хрустальной Песни и принеси мне доски. Только смотри, не попадись никому на глаза!', 'Принесите 12 грубо обтесанных досок Беззлу Рвизасову на Ристалище Серебряного турнира.', 'Отличные досочки, да и достались почти даром! Недотепы из Серебряного Авангарда ни за что не пронюхают, откуда у меня материал! Они получат свой Колизей, а я – премию за своевременное окончание строительства. И все счастливы!', 'Как там дела с поставкой \"товара\"?', NULL, NULL, 'Грубо обтесанная доска', 'Топор дровосека', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13629, 'Вал\'анир, молот древних королей', 'С помощью панели управления Архивом вы узнаете способ воссоединения расколотого Вал\'анира: надо поместить его внутрь физической формы существа, известного как Йогг-Сарон.$B$BЭто звучит довольно опасно, но ради артефакта такой силы можно пойти на риск.', 'Бросьте расколотый Вал\'анир в пасть Йогг-Сарона во время \"Оглушающего рева\" и победите его, чтобы получить перекованный молот древних королей.Это задание можно пройти только в героическом режиме и только в том случае, если хотя бы один из хранителей Ульдуара не помогает вам.', '', NULL, NULL, NULL, 'Перекованный молот древних королей', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13631, 'Все хорошо, что хорошо кончается', 'Мы должны поторопиться, $N – надо передать код отклика из Даларана как можно скорее.$B$BОтнеси его Ронину, я встречу тебя там.', 'Доставьте код отклика \"Альфа\" Ронину в Даларан.', '', NULL, NULL, NULL, 'Код отклика \"Альфа\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13633, 'Черный рыцарь из Западного Края?', 'Не сомневаюсь, до тебя уже дошли тревожные слухи об участнике турнира, которого остальные называют Черным рыцарем. Говорят, будто каждый, кому выпал жребий стать его противником в следующем бою, внезапно умирает.$B$BКонечно, мы не можем ничего утверждать, но было бы неплохо проверить все, что нам известно про этого рыцаря.$B$BОн утверждает, будто он родом из семьи Купер, которая проживает в Западном Крае. Съезди в имение Куперов на западе Луноречья, чтобы подтвердить или опровергнуть его слова.', 'Узнайте правду о Черном рыцаре и поделитесь информацией с рыцарем Райдаллой на ристалище Серебряного турнира.', 'Значит, история рыцаря – это сплошной обман? Крайне подозрительная ситуация. Это бесчестно, а может стать и смертельно опасным в худшем случае. Но мы не сможем предъявить ему обвинения, пока у нас не будет доказательств.$B$BПостарайся не вызывать у него подозрений, $N. Если мы хотим продолжить расследование, надо делать это втайне.', 'Тебе удалось найти что-то, что могло бы подтвердить историю Черного рыцаря?', NULL, NULL, 'Пыльный дневник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13634, 'Черный рыцарь из Серебряного бора?', 'Не сомневаюсь, до тебя уже дошли тревожные слухи об участнике турнира, которого остальные называют Черным рыцарем. Говорят, будто каждый, кому выпал жребий стать его противником в следующем бою, внезапно умирает.$B$BКонечно, мы не можем ничего утверждать, но было бы неплохо проверить все, что нам известно про этого рыцаря.$B$BПо его словам, он прибыл с Поля Валгана, что в Серебряном Бору. Это маленькая ферма на западном берегу озера Лордамер. Съезди на эту ферму, чтобы подтвердить или опровергнуть его слова.', 'Узнайте правду о Черном рыцаре и поделитесь информацией с рыцарем Райдаллой на ристалище Серебряного турнира.', 'Значит, история рыцаря – это сплошной обман? Крайне подозрительная ситуация. Это бесчестно, а может стать и смертельно опасным в худшем случае. Но мы не сможем предъявить ему обвинения, пока у нас не будет доказательств.$B$BПостарайся не вызывать у него подозрений, $N. Если мы хотим продолжить расследование, надо делать это втайне.', 'Тебе удалось найти что-то, что могло бы подтвердить историю Черного рыцаря?', NULL, NULL, 'Пыльный дневник', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13641, 'Кристалл провидца', 'Теперь, когда мы знаем, что Черный рыцарь обманом проник на турнир, нужно найти доказательства его причастности к смерти других участников. $B$BЯ знаю, как нам вывести его на чистую воду, но для этого понадобится очень редкая вещь – кристалл провидца. Такие кристаллы можно найти только у диких провидцев, обитающих рядом с руинами ночных эльфов в Опустевших лесах, это в центре Леса Хрустальной Песни. $N, найди провидца и принеси кристалл.', 'Принесите кристалл провидца рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного турнира.', 'Да, этот кристалл подойдет. Осталось только зарядить его силой Света, чтобы он смог отличить правду от лжи.', 'Ты уже нашел кристалл провидца?', NULL, NULL, 'Кристалл провидца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13643, 'История погибших', 'Этот кристалл откроет нам правду о том, как погибли три участника турнира. Отнеси его на кладбище на востоке Ристалища к могилам сэра Венделла Балфура, Лориена Блеска Солнца и Коналла Железной Хватки.$B$BЕсли три этих доблестных мужа действительно были убиты, мы должны будем найти доказательства причастности Черного рыцаря до того, как он совершит очередное преступление. Внимательно изучи то, что покажет тебе кристалл, ибо мы должны быть абсолютно уверены, что эти смерти не были случайными.', 'Воспользуйтесь кристаллом провидца перед могилами сэра Венделла Балфура, Лориена Блеска Солнца и Коналла Железной Хватки, узнайте причину их гибели и доложите рыцарю Райдалле из Серебряного павильона.', 'Значит, Лориен Блеск Солнца был отравлен, а сэр Венделл сгорел заживо? Какая ужасная смерть постигла этих доблестных мужей. Один лишь Коналл погиб, сраженный мечом – но не в честном поединке, а от руки предателя.$B$BИ все трое должны были сражаться с Черным рыцарем на турнире. Это не может быть совпадением! Осталось доказать, что он причастен к их смерти.', 'Ты уже посетил могилы павших рыцарей?', NULL, NULL, 'Вы узнали причину смерти сэра Венделла Балфура', 'Вы узнали причину смерти Лориена Блеска Солнца', 'Вы узнали причину смерти Коналла Железной Хватки', 'Кристалл провидца');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13649, 'Веселая проверка Джастина', 'Эй! Похоже, с выпивкой ты обращаться умеешь. А вот с пивной кружкой? $B$BЭти дворфы из клана Черного Железа опять вернулись! Мстить хотят и праздник нам порушить! Легче всего их отогнать, если запустить в них пивной кружкой, но сначала посмотрим-ка, попадешь ли ты в чучелко – С.С.М.?$B$BЭто просто – хлебни бесплатного пивка, только встань сначала лицом к С.С.М. Попади в цель пять раз, тогда поговорим.', 'Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Бокси Болтокрутом.', '', NULL, NULL, NULL, 'С.С.М. поражен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13654, 'Странный оруженосец', 'Каждый день оруженосец Черного рыцаря Малорик устраивает целое представление, торжественно отправляясь в Лес Хрустальной Песни. Он хочет убедить всех, что рубит дрова, но обратно приносит всего несколько веток.$B$BНа самом деле он ходит к руинам на юго-западе Зеркала Сумерек. Учитывая его обязанности как оруженосца, он проводит там слишком много времени.$B$BОглуши его и обыщи хорошенько. Мы должны знать, что он затевает.', 'Добудьте большую бедренную кость дровосека-скелета и оглушите Малорика. Обыщите его и доложите обо всем рыцарю Райдалле из Серебряного павильона на Ристалище Серебряного турнира.', '<Рыцарь Райдалла с отвращением изучает содержимое сумки.>$B$BЗдесь все улики, $N: яд, которым был отравлен Лориен, набор ножей, факелы и масло. Не могу представить, зачем оруженосцу могли потребоваться эти предметы, если только он не выполнял приказ своего рыцаря. Мы нашли убийцу, $N, но по чьему приказанию он действовал?', 'Тебе удалось узнать что-нибудь об этом странном оруженосце?', NULL, NULL, 'Инструментарий убийцы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13662, 'Завоевать благосклонность', '', '', '', NULL, NULL, NULL, 'Окалина черного железа', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13663, 'Приказы для Черного рыцаря', 'Мы должны выяснить, кто послал Черного рыцаря на турнир, и чего именно добивался его хозяин, убивая наших участников.$B$BСовет Кирин-Тора оказал нам содействие в расследовании этого дела.$B$BОни предоставили нам эту волшебную уздечку. Отнеси ее к палатке Черного рыцаря, что на восточном краю Ристалища, с ее помощью приручи его грифона. Магия уздечки заставит грифона отнести тебя к жилищу хозяина рыцаря. Обыщи это место и возвращайся ко мне.', 'Воспользуйтесь волшебной уздечкой, чтобы подчинить грифона Черного рыцаря и попасть к дому его хозяина. Как только вы попадете на место, найдите украденное приглашение на турнир и приказы для Черного рыцаря, после чего отнесите их рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного Турнира.', '<Рыцарь Райдалла бледнеет, читая приказы.>$B$BЭто может означать только одно: Черный рыцарь – член Культа Проклятых! Его послал Артас, чтобы сорвать проведение турнира.$B$BНо он уже проявил себя как могучий воин, и тебе потребуется все твое искусство, чтобы одолеть его. Возвращайся, когда получишь звание чемпиона, и мы постараемся найти способ избавиться от этой угрозы.', 'Что тебе удалось обнаружить?', NULL, NULL, 'Грифон Черного рыцаря подчинен', 'Украденное приглашение на турнир', 'Приказы для Черного рыцаря', 'Волшебная уздечка');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13664, 'Падение Черного рыцаря', 'Мы должны положить конец зловещим планам Черного рыцаря и показать всем противникам, что мы не потерпим хладнокровного убийства наших лучших воинов!$B$BБрось вызов Черному рыцарю и одолей его в бою, $N.$B$BДля этой битвы я одолжу тебе моего боевого скакуна Серебряного Рассвета, который стоит в стойлах.$B$BПоговори с оруженосцем Кейвином на южной стороне Ристалища. Он вызовет Черного рыцаря на бой, и тебе останется лишь заставить того заплатить за преступления.', 'Одержите победу над Черным рыцарем, после чего поговорите с рыцарем Райдаллой в Серебряном павильоне на Ристалище Серебряного турнира.', 'После смерти Черного рыцаря турниру больше ничто не угрожает. Теперь чемпионы Орды и Альянса смогут проявить себя в состязаниях и подготовиться к тому дню, когда Артас и его приспешники будут повержены навсегда.$B$BЯ благодарю тебя от лица всего Серебряного Авангарда и тех, кто откликнулся на его призыв.', 'Дело сделано?', NULL, NULL, 'Черный рыцарь убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13665, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Люди Штормграда превозносят своих рыцарей и надеются на нашу победу. Лучший способ усовершенствовать свои навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BПослушай моего совета – иди в стойла за павильоном, оседлай штормградского скакуна и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Альянса.', 'Принесите три знака искателя славы капитану Джозефу Холли в шатер Альянса на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Молодец! Тренировка вместе с другими искателями славы – это лучший способ подготовиться к турниру. Я знаю, что ты принесешь победу Штормграду, $N.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13666, 'Клинок, достойный чемпиона', 'Некоторые бойцы полагают, что древнее оружие, выкованное в Нордсколе, может принести удачу в состязании. Я же согласился помочь им в поисках этих легендарных клинков.$B$BЕсть одна древняя легенда о деве из Ясеневого озера, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его чародею Таэлису в шатер Альянса на Ристалище Серебряного турнира.', 'Значит, в старых сказках есть доля правды? Во всяком случае, меч действительно прекрасный! Молодец, $N. Как же повезет тому чемпиону, которому в бою послужит этот клинок!', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13667, 'Серебряный Турнир', 'Мы пригласили тебя сюда для того, чтобы испытать твою ловкость и отвагу в поединке с теми, кто противостоит Плети день за днем. До сих пор мы сражались под разными знаменами, но теперь настал день, когда все герои должны скрестить мечи и проверить свою готовность перед битвой с нашим общим врагом.$B$BЧародей Таэлис является представителем Серебряного союза на турнире. Он внесет твое имя в списки и займется начальной подготовкой. Ищи его в огромном шатре Альянса в юго-восточной части Ристалища.', 'Чтобы принять участие в турнире, поговорите с чародеем Таэлисом в шатре Альянса на Ристалище Серебряного турнира, он внесет ваше имя в списки.', 'Я внес твое имя в списки, $N. Теперь ты можешь тренироваться как и другие претенденты на участие в турнире и оттачивать навыки верхового поединка. Докажи, что ты достойна – и сможешь участвовать в соревнованиях низкого ранга, защищая честь своей столицы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13668, 'Серебряный Турнир', 'Мы пригласили тебя сюда для того, чтобы испытать твою ловкость и отвагу в поединках с теми, кто противостоит Плети день за днем. До сих пор мы сражались под разными знаменами, но теперь настал день, когда все герои должны скрестить мечи и проверить свою готовность перед битвой с нашим общим врагом.$B$BМагистр Эдиен Солнечная Низина является представителем Похитителей Солнца на турнире. Он внесет твое имя в списки и займется начальной подготовкой. Ищи его в огромном шатре Орды в юго-восточной части Ристалища.', 'Чтобы принять участие в турнире, поговорите с магистром Эдиеном Солнечной Низиной в шатре Орды на Ристалище Серебряного турнира, он внесет ваше имя в списки.', 'Я внес твое имя в списки, $N. Теперь ты можешь тренироваться как и другие претенденты на участие в турнире и оттачивать навыки верхового поединка. Докажи, что ты достоин – и ты сможешь участвовать в соревнованиях низкого ранга, защищая честь своей столицы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13669, 'Достойное оружие', 'Похоже, нашим чемпионам понравились древние мечи, выкованные в Нордсколе.$B$BДо меня дошли слухи, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. Посмотрим, одарит ли тебя дева достойным клинком.', 'Принесите меч Драк\'Мара чародею Таэлису в Павильон Серебряного союза на Ристалище Серебряного турнира.', 'Это на самом деле потрясающий клинок – острый и отлично сбалансированный. Теперь я понимаю, почему эти мечи так ценятся среди чемпионов Альянса.', 'Так барды говорят правду? Меч действительно существует?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13670, 'Клинок Зимы', 'Один из оруженосцев Стальгорна рассказал мне занятную историю!$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Чародей Таэлис из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', 'Искатель славы не обманул – это прекрасный клинок. И откуда он только узнал про него? Неважно; он сослужит добрую службу новому владельцу. Будет справедливо, если он достанется абсолютному чемпиону Стальгорна.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13671, 'Тренировка на поле боя', 'Турнир – это возможность похвалиться своей силой перед другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем. Продемонстрируй свою отвагу, сразившись с Плетью – и ты заслужишь право участвовать в турнире. $B$BОтправляйся в Ледяную Корону и убей несколько приспешников Плети. Но не пересекай границы Зоны бомбардировки – тебе не удастся справиться со столь многочисленным противником.', 'Убейте 8 воинов Плети в Ледяной Короне по заданию Аварета Молниеносного Удара из Павильона Серебряного союза на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны, за исключением зоны бомбардировки.', 'Ты показал свою силу в бою, $N, и твой пример вдохновит других претендентов, желающих сражаться под знаменами Альянса.', NULL, NULL, NULL, 'Убито воинов Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13672, 'Подготовка к испытанию', 'Закончив тренировки, ты получишь возможность пройти испытания претендентов, которые определят твой уровень ведения верхового боя и покажут, стоит ли тебе искать славы. Если ты успешно выдержишь этот экзамен, то сможешь присоединиться к делегации твоего города в качестве искателя славы.$B$BВозвращайся ко мне, когда будешь $gготов:готова: к испытаниям.', 'Чтобы продемонстрировать свою готовность пройти испытание претендентов, покажите 15 печатей претендента чародею Таэлису из Павильона Серебряного союза на Ристалище Серебряного турнира.', 'Хорошо, я дам необходимые распоряжения.', 'Ты хочешь пройти испытание претендентов?', NULL, NULL, 'Печать претендента', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13673, 'Клинок, достойный чемпиона', 'Некоторые бойцы полагают, что древнее оружие, выкованное в Нордсколе, может принести удачу в состязании. Я же согласился помочь им в поисках этих легендарных клинков.$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', 'Значит, в старых сказках есть доля правды? Во всяком случае, меч действительно прекрасный! Молодец, Арним. Как же повезет тому чемпиону, которому в бою послужит этот клинок!', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13674, 'Достойное оружие', 'Похоже, нашим чемпионам понравились древние мечи, выкованные в Нордсколе.$B$BДо меня дошли слухи, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. Посмотрим, одарит ли тебя дева достойным клинком.', 'Принесите меч Драк\'Мара магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', 'Это на самом деле потрясающий клинок – острый и отлично сбалансированный. Теперь я понимаю, почему эти мечи так ценятся среди чемпионов Альянса.', 'Так барды говорят правду? Меч действительно существует?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13675, 'Клинок Зимы', 'Один из искателей славы Оргриммара рассказал мне занятную историю!$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Магистр Эдиен Солнечная Низина из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', 'Искатель славы не обманул – это прекрасный клинок. И откуда он только узнал про него? Неважно; он сослужит добрую службу новому владельцу. Будет справедливо, если он достанется абсолютному чемпиону Оргриммара.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13676, 'Тренировка на поле боя', 'Турнир – это возможность похвалиться своей силой перед другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем. Продемонстрируй свою отвагу, сразившись с Плетью – и ты заслужишь право участвовать в турнире. $B$BОтправляйся в Ледяную Корону и убей несколько приспешников Плети. Но не пересекай границы Зоны бомбардировки – тебе не удастся справиться со столь многочисленным противником.', 'Убейте 8 воинов Плети в Ледяной Короне по заданию Амариэля Верного Солнцу из Павильона Похитителей Солнца на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны, за исключением зоны бомбардировки.', 'Ты показал свою силу в бою, $N, и твой пример вдохновит других претендентов, желающих сражаться под знаменами Орды.', NULL, NULL, NULL, 'Убито воинов Плети', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13677, 'Большая тренировка', 'Большая часть состязаний турнира требует от участников мастерства в управлении верховым животным. Чтобы познакомить тебя с этим видом поединков, мы разместили тренировочные манекены в северной части Ристалища турнира.$B$BЗайди в стойла на севере площадки, рядом с главной ареной, вооружись копьем и оседлай крылобега Похитителей Солнца. Познакомься со всеми доступными приемами и используй новые знания в тренировке. Для освоения новых приемов можешь использовать все три вида манекенов.', 'Отработайте прием \"Выпад\" 5 раз на манекене для ближнего боя, прием \"Удар по щиту\" 2 раза на мишени для дальнего боя и прием \"Рывок\" 2 раза на манекене для стремительной атаки, затем вернитесь к Галатии Сияющий Рассвет в шатер Орды на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.', 'Молодец, $N. Не все воины легко осваивают приемы верхового поединка. Я не сомневаюсь, что ты продолжишь тренировки и превзойдешь многих воинов в этом виде состязаний.', NULL, NULL, NULL, 'Манекен для ближнего боя поражен', 'Мишень для дальнего боя поражена', 'Манекен для стремительной атаки поражен', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13678, 'Подготовка к испытанию', 'Закончив тренировки, ты получишь возможность пройти испытания претендентов, которые определят твой уровень ведения верхового боя и покажут, стоит ли тебе искать славы. Если ты успешно выдержишь этот экзамен, то сможешь присоединиться к делегации твоего города в качестве искателя славы.$B$BВозвращайся ко мне, когда будешь $gготов:готова: к испытаниям.', 'Чтобы продемонстрировать свою готовность пройти испытание претендентов, отдайте 15 печатей претендента магистру Эдиену Солнечной Низине из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Хорошо, я дам необходимые распоряжения.', 'Ты хочешь пройти испытание претендентов?', NULL, NULL, 'Печать претендента', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13679, 'Испытание претендента', 'Ты очень $gприлежно занимался:прилежно занималась: на тренировках, $N, и теперь пришло время проверить твои навыки верхового поединка в бою против опытного противника.$B$BНа Арене претендентов в северной части Ристалища тебя ждет мальчик – оруженосец Давид. Он проверит твою готовность к сражению и вызовет того, с кем тебе предстоит сразиться.$B$BУдачи, $N. Да не споткнется твой конь, и да будет крепкой твоя рука.', 'Поговорите с оруженосцем Давидом, чтобы вызвать на поединок вашего противника. Как только вы победите искателя славы Серебряного Авангарда, вернитесь к чародею Таэлису в шатер Альянса на Ристалище Серебряного Турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Мои поздравления, $N. Все испытания пройдены и ты полностью заслуживаешь право носить титул искателя славы.', NULL, NULL, NULL, 'Искатель славы Серебряного Авангарда побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13680, 'Испытание претендента', 'Ты очень $gприлежно занимался:прилежно занималась: на тренировках, $N, и теперь пришло время проверить твои навыки верхового поединка в бою против опытного противника.$B$BВооружись копьем и оседлай крылобега Похитителей Солнца.$B$BНа Арене претендентов в северной части Ристалища тебя ждет мальчик – оруженосец Давид. Он проверит твою готовность к сражению и вызовет того, с кем тебе предстоит сразиться.$B$BУдачи, $N. Да не споткнется твой конь, и да будет крепкой твоя рука.', 'Поговорите с оруженосцем Давидом, чтобы вызвать на поединок вашего противника. Как только вы победите искателя славы Серебряного Авангарда, вернитесь к магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.', '', NULL, NULL, NULL, 'Искатель славы Серебряного Авангарда побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13681, 'Обломки стен Ульдуара', 'Ух, $gдружище:подруга:, как же тяжело добыть камни для этой стройки! Тонны материала валяются в руинах в тихих и безопасных местах, но их святейшества паладины не позволяют к ним прикоснуться. \"Бесценные артефакты\", надо же.$B$BЛадно, жалобами делу не поможешь. В Подножии и Библиотеке Изобретателя в Грозовой Гряде некогда были постройки $Nв, сейчас же там одни руины. Вот, возьми эту штуку, так называемое \"гоблинское долото\" и попробуй разбить огромные обломки на более транспортабельные куски.', 'Принесите 15 небольших камней Боззлу Рвизасову на Ристалище Серебряного турнира.', 'Да, неплохой материал. Только смотри, не разболтай этим святошам, откуда ты его взял. Что-то мне подсказывает, что они огорчатся. Мне же кажется, что титаны не вернутся за этими камушками, так что все честно. Молодец, $N.', 'Ты принес камни?', NULL, NULL, 'Небольшой камень', '\"Гоблинское долото\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13682, 'Атака с воздуха', 'После того, как тебе удалось обнаружить лазутчика Культа Проклятых, верховный лорд Тирион Фордринг приказал удвоить охрану. Он не верит, что их остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа. Его видели на юго-западе, между Железным валом и Алдур\'таром.', 'Эдрик Чистый из Серебряного павильона на Ристалище Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов – сектантов.', '$N, ты и твои союзники защитили турнир от нападения врагов. Хотя наши воздушные разведчики не менее отважны, у них много дел по охране воздушного пространства. Мы благодарим тебя от лица Серебряного Авангарда и всех участников турнира.', NULL, NULL, NULL, 'Ледяная Пасть убито', 'Бомбист-сектант убито', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13684, 'Искатель славы из Штормграда', 'Ты достойно $gсражался:сражалась: под знаменами Штормграда, $N. Теперь тебе следует предстать перед маршалом Якобом Алерием. Это глава делегации Штормграда и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Если вы хотите стать искателем славы Штормграда, поговорите с маршалом Якобом Алерием в Павильоне Серебряного Союза на Ристалище Серебряного турнира.', 'В таком случае – добро пожаловать в нашу компанию, искатель славы Нагально. Делегация Штормграда приветствует тебя в своих рядах.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13685, 'Искатель славы из Стальгорна', 'Ты достойно $gсражался:сражалась: под знаменами Стальгорна, $N. Теперь тебе следует предстать перед Ланой Твердомолот. Это глава делегации Стальгорна и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Если вы хотите стать искателем славы Стальгорна, поговорите с Ланой Твердомолот в шатре Альянса на Ристалище Серебряного турнира.', 'Приятно познакомиться, искатель славы. Стальгорну нужны такие участники, как ты.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13688, 'Искатель славы из Гномрегана', 'Ты достойно $gсражался:сражалась: под знаменами Гномрегана, $N. Теперь тебе следует предстать перед Амброзом Искрокрутом. Это глава делегации Гномрегана и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Если вы хотите стать искателем славы Гномрегана, поговорите с Амброзом Искрокрутом в шатре Альянса на Ристалище Серебряного турнира.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13689, 'Искатель славы из Дарнаса', 'Ты достойно $gсражался:сражалась: под знаменами Дарнаса, $N. Теперь тебе следует предстать перед Джейлин Закатной Песней. Это глава делегации Дарнаса и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Чтобы стать искателем славы Дарнаса, поговорите с Джейлин Закатной Песней в шатре Альянса на Ристалище Серебряного турнира.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13690, 'Искатель славы из Экзодара', 'Ты достойно $gсражался:сражалась: под знаменами Экзодара, $N. Теперь тебе следует предстать перед Колосусом. Это глава делегации Экзодара и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Если вы хотите стать искателем славы Экзодара, поговорите с Колосусом в в шатре Альянса на Ристалище Серебряного турнира.', 'В таком случае – добро пожаловать в нашу компанию, искатель славы $N. Делегация Экзодара приветствует тебя в своих рядах.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13691, 'Искатель славы из Оргриммара', 'Ты достойно $gсражался:сражалась: под знаменами Оргриммара, $N. Теперь тебе следует предстать перед Мокрой Дробителем Черепов. Это глава делегации Оргриммара и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и проверять твои навыки.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Если вы хотите стать искателем славы Оргриммара, поговорите с Мокрой Дробителем Черепов в Павильоне Похитителей Солнца на Ристалище Серебряного турнира.', 'Значит, ты хочешь сражаться за Оргриммар? Если тебе удалось одолеть парочку манекенов – это еще не значит, что ты победишь в турнире, но теперь ты будешь тренироваться вместе с самыми лучшими воинами, что несколько повысит твои шансы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13692, 'Меч из моря', 'Мой меч канул в глубине моря. Найди его и принеси обратно!', 'Старина Барло из Леса Хрустальной Песни просит вас принести ему Меч Рыцарства.', '', NULL, NULL, NULL, 'Откушенная рука', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13693, 'Искатель славы из Сен\'джина', 'Ты достойно $gсражался:сражалась: под знаменами Сен\'джина, $N. Теперь тебе следует предстать перед Зул\'тором, предводителем воинов и абсолютным чемпионом Сен\'джина. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Если вы хотите стать искателем славы Сен\'джина, поговорите с Зул\'тором в Павильоне Похитителей Солнца на Ристалище Серебряного Турнира.', 'Думаешь, ты можешь сражаться под флагами Сен\'джина? Мы это проверим.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13694, 'Искатель славы из Громового Утеса', 'Ты достойно $gсражался:сражалась: под знаменами Громового Утеса, $N. Теперь тебе следует предстать перед Руноком Буйногривым. Это глава делегации Громового Утеса и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Если вы хотите стать искателем славы Громового Утеса, поговорите с Руноком Буйногривым в Павильоне Похитителей Солнца на Ристалище Серебряного турнира.', 'Приветствую тебя от лица всех воинов Громового Утеса! Сражайся с честью под нашими знаменами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13695, 'Искатель славы из Подгорода', 'Ты достойно $gсражался:сражалась: под знаменами Подгорода, $N. Теперь тебе следует предстать перед стражем смерти Визери. Это глава делегации Подгорода и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Если вы хотите стать искателем славы Подгорода, поговорите со стражем смерти Визери в Павильоне Похитителей Солнца на Ристалище Серебряного турнира.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13696, 'Искатель славы из Луносвета', 'Ты достойно $gсражался:сражалась: под знаменами Луносвета, $N. Теперь тебе следует предстать перед Эрессеей Певицей Рассвета. Это глава делегации Луносвета и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $N. Удачи тебе на состязаниях!', 'Если вы хотите стать искателем славы Луносвета, поговорите с Эрессеей Певицей Рассвета в Павильоне Похитителей Солнца на Ристалище Серебряного турнира.', 'Значит, ты хочешь сражаться за Луносвет? Отлично. Я добавлю тебя в списки, и ты немедленно сможешь приступить к тренировкам с другими искателями славы.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13697, 'Путь искателя славы', 'Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.', 'Принесите 25 печатей искателя славы Мокре Дробителю Черепов в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.', 'Впечатляюще, искатель славы! Я немедленно распоряжусь о проведении испытания.', 'Ты готов продемонстрировать свое искусство искателя славы?', NULL, NULL, 'Печать искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13699, 'Испытание искателя славы', 'Скоро ты будешь $gготов:готова: сразиться в великой битве во имя Штормграда. Если хочешь доказать, что $gдостоин:достойна: представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.', 'Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к маршалу Якобу Алерию на Ристалище Серебряного Турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Ты доказал, что достоин титула чемпиона, $N. Теперь ты будешь с оружием наготове защищать честь Штормграда на самом высоком уровне и носить наш герб на своем флаге.', NULL, NULL, NULL, 'Чемпион Серебряного Авангарда побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13702, 'Рождение героя', 'Поздравляю, $N. Ты $gпрошел:прошла: все испытания и $gотточил:отточила: до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты $gготов:готова: сразиться с лучшими воинами турнира – чемпионами столиц.$B$BНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!', 'Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.', 'Я приветствую тебя как чемпиона турнира, $N. В этом звании ты сможешь принять участие в самых крупных состязаниях. Ты также можешь стать искателем славы другого города и со временем завоевать звание его чемпиона.$B$BВсе чемпионы обязаны пользоваться услугами оруженосцев, и ты, $N, не исключение. Позволь мне порекомендовать тебе надежного помощника в будущих сражениях. Он будет гордо нести флаг столицы, которая избрала тебя своей представительницей.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13703, 'Искатель славы из Стальгорна', 'Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Не желаешь ли к нам присоединиться?$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Стальгорна позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Стальгорна, поговорите еще раз с Ланой Твердомолот в Павильоне Серебряного Союза.', 'Мы рады, что ты решил к нам присоединиться. Вскоре на поле битвы загорится новая звезда.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13704, 'Искатель славы из Гномрегана', 'Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Ты $gмог:могла: бы значительно усилить делегацию Гномрегана!$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Гномрегана позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Гномрегана, поговорите еще раз с Амброзом Искрокрутом в Павильоне Серебряного Союза.', 'Мы рады приветствовать тебя среди нас, $N. Надеюсь, вскоре мы будем тренироваться бок о бок.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13705, 'Искатель славы из Экзодара', 'Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Не желаешь к нам присоединиться?$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Экзодара позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Экзодара, поговорите еще раз с Колосусом в Павильоне Серебряного Союза.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13706, 'Искатель славы из Дарнаса', 'Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Буду рада включить тебя в число участников делегации Дарнаса, если ты желаешь к нам присоединиться.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Дарнаса позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Дарнаса, поговорите еще раз с Джейлин Закатной Песней.', 'Воины Дарнаса гордятся возможностью сражаться рядом с тобой.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13707, 'Искатель славы из Оргриммара', 'Значит, ты уже $gполучил:получила: звание чемпиона? Должно быть, ты $gпроявил:проявила: себя как достойный боец, и я буду рад включить тебя в число участников делегации Оргриммара.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Оргриммара позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Оргриммара, поговорите еще раз с Мокрой Дробителем Черепов в Павильоне Похитителей Солнца.', 'Добро пожаловать, $N. Жду не дождусь, когда ты начнешь тренировку с моими воинами.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13708, 'Искатель славы из Сен\'джина', 'Приветствую тебя, чемпион. Если желаешь, я могу записать тебя в делегацию Сен\'джина.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Сен\'джина позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Сен\'джина, поговорите еще раз с Зул\'тором в Павильоне Похитителей Солнца.', 'Хорошо, что ты решил к нам присоединиться! Скорее бы увидеть тебя в деле.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13709, 'Искатель славы из Громового Утеса', 'Приветствую тебя, чемпион. Как абсолютный чемпион Громового Утеса я буду рад включить тебя в число участников нашей делегации.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Громового Утеса позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Громового Утеса, поговорите еще раз с Руноком Буйногривым в Павильоне Похитителей Солнца.', 'Это честь для нас – приветствовать тебя в составе делегации. Я знаю, что ты принесешь нам победу, $N.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13710, 'Искатель славы из Подгорода', 'Приветствую тебя, чемпион. Твое присутствие значительно усилит делегацию Отрекшихся. Не желаешь ли присоединиться к нам?$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Подгорода позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Подгорода, поговорите еще раз со стражем смерти Визери в Павильоне Похитителей Солнца.', 'Мудрый выбор, $N. Мы оба только выиграем от этого решения.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13711, 'Искатель славы из Луносвета', 'Значит, ты уже $gполучил:получила: звание чемпиона? Должно быть, ты $gпроявил:проявила: себя как достойный боец, и я буду рада включить тебя в число участников делегации Луносвета.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Луносвета позволит тебе выступать под нашим флагом.', 'Если вы хотите стать искателем славы Луносвета, поговорите еще раз с Эрессеей Певицей Рассвета в Павильоне Похитителей Солнца.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13713, 'Испытание искателя славы', 'Скоро ты будешь $gготов:готова: сразиться в великой битве во имя Стальгорна. Если хочешь доказать, что $gдостоин:достойна: представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.', 'Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к Лане Твердомолот в шатер Альянса на Ристалище Серебряного Турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Ты доказал, что достоин титула чемпиона, $N. Теперь ты будешь с оружием наготове защищать честь Стальгорна на самом высоком уровне и носить наш герб на своем флаге.', 'Ты одержал верх над чемпионом Серебряного Авангарда?', NULL, NULL, 'Чемпион Серебряного Авангарда побежден', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13714, 'Путь искателя славы', 'Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.', 'Принесите 25 печатей искателя славы Лане Твердомолот в Павильон Серебряного союза на Ристалище Серебряного Турнира.', 'Впечатляюще, искатель славы! Я немедленно распоряжусь о проведении испытания.', 'Ты готов продемонстрировать свое искусство искателя славы?', NULL, NULL, 'Печать искателя славы', NULL, NULL, NULL);
