INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13732, 'Рождение героя', 'Поздравляю, $N. Ты $gпрошел:прошла: все испытания и $gотточил:отточила: до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты $gготов:готова: сразиться с лучшими воинами турнира – чемпионами столиц.$B$BНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!', 'Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13733, 'Рождение героя', 'Поздравляю, $N. Ты $gпрошел:прошла: все испытания и $gотточил:отточила: до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты $gготов:готова: сразиться с лучшими воинами турнира – чемпионами столиц.$B$BНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!', 'Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
