INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13741, 'Клинок, достойный чемпиона', 'Даже самым верным и острым клинком не выиграть это состязание. Мои соперники обзавелись заколдованным оружием, что ставит меня в невыгодное положение, но я не отчаиваюсь.$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его Лане Твердомолот в Павильон Серебряного союза на Ристалище Серебряного турнира.', 'Так значит, это не сказки? Какой замечательный клинок! Не сомневаюсь, он верно послужит мне на турнире. Спасибо тебе, $N.', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13742, 'Достойное оружие', 'Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', 'Принесите меч Драк\'Мара Лане Твердомолот в Павильон Серебряного союза на Ристалище Серебряного турнира.', 'БАбсолютный чемпион принимает у вас меч Драк\'Мара.>$B$BПрекрасное оружие, отлично сбалансировано... этот меч сослужит мне добрую службу в следующем поединке.', 'Так барды говорят правду? Меч действительно существует?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13743, 'Клинок Зимы', 'Проклятый рыцарь смерти сломал мой клинок.$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Лана Твердомолот из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', 'Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13744, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', 'Убейте 10 обращенных героев по заданию Ролло Меткострела из Павильона Серебряного союза на Ристалище Серебряного турнира.', 'С возвращением, $N. Даже во время тренировок мы не должны забывать о реальной угрозе, с которой придется иметь дело после окончания турнира.', NULL, NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13745, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Люди Стальгорна надеются на нашу победу. Лучший способ усовершенствовать свои навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BОни тренируются на арене за нашей палаткой. Послушай моего совета – иди в стойла за павильоном, оседлай стальгорнского барана и брось вызов искателям славы из Альянса.', 'Принесите три знака искателя славы Кларе Взубногой в шатер Альянса на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Молодец! Тренировка вместе с другими искателями славы – это лучший способ подготовиться к турниру. Я знаю, что ты принесешь победу Стальгорну, $N.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13746, 'Клинок, достойный чемпиона', 'Даже самым верным и острым клинком не выиграть это состязание. Мои соперники обзавелись заколдованным оружием, что ставит меня в невыгодное положение, но я не отчаиваюсь.$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его Амброзу Искрокруту в Павильон Серебряного союза на Ристалище Серебряного турнира.', 'Так значит, это не сказки? Какой замечательный клинок! Не сомневаюсь, он верно послужит мне на турнире. Спасибо тебе, $N.', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
