INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13749, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', 'Убейте 10 воинов Плети в Ледяной Короне по заданию Тикля Гайковерта из Павильона Серебряного союза на Ристалище Серебряного турнира. Вы можете найти их в любой части Ледяной Короны, за исключением Бомбардировки.', 'Тренировка прошла успешно, $N? Не сомневаюсь, ты принесешь нам победу на турнире.', NULL, NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13750, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Многие надеются на нашу победу, и мы не можем их разочаровать. Лучший способ усовершенствовать свои навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$B Послушай моего совета – иди в стойла за павильоном, оседлай турбодолгонога и брось вызов искателям славы. Они ждут тебя на Арене искателей славы Альянса, прямо за нашей палаткой.', 'Принесите три знака искателя славы Фликлю Гайковерту в шатер Альянса на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Молодец! Тренировка вместе с другими искателями славы – это лучший способ подготовиться к турниру. Я знаю, что ты принесешь нам победу, $N.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13752, 'Клинок, достойный чемпиона', 'Даже самым верным и острым клинком не выиграть это состязание. Мои соперники обзавелись заколдованным оружием, что ставит меня в невыгодное положение, но я не отчаиваюсь.$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его Колосусу в Павильон Серебряного союза на Ристалище Серебряного турнира.', 'Так значит, это не сказки? Какой замечательный клинок! Не сомневаюсь, он верно послужит мне на турнире. Спасибо тебе, $N.', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13753, 'Достойное оружие', 'Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', 'Принесите меч Драк\'Мара Колосусу в Павильон Серебряного союза на Ристалище Серебряного турнира.', '<Абсолютный чемпион принимает у вас меч Драк\'Мара.>$B$BПрекрасное оружие, отлично сбалансировано... этот меч сослужит мне добрую службу в следующем поединке.', 'Так барды говорят правду? Меч действительно существует?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13754, 'Клинок Зимы', 'Проклятый рыцарь смерти сломал мой клинок.$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Колосус из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', 'Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13755, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', 'Убейте 10 обращенных героев по заданию Саандоса из Павильона Серебряного союза на Ристалище Серебряного турнира.', 'С возвращением, $N. Даже во время тренировок мы не должны забывать о реальной угрозе, с которой придется иметь дело после окончания турнира.', NULL, NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13756, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Население Экзодара надеется на нашу победу. Лучший способ усовершенствовать навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BПослушай моего совета – иди в стойла за павильоном, оседлай элекка с острова Лазурной Дымки и брось вызов своим конкурентам. Они ждут тебя на Арене искателей славы из Альянса, прямо за нашей палаткой.', 'Принесите три знака искателя славы Рании в шатер Альянса на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Молодец! Тренировка вместе с другими искателями славы – это лучший способ подготовиться к турниру. Я знаю, что ты принесешь нам победу, $N.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13757, 'Клинок, достойный чемпиона', 'Даже самым верным и острым клинком не выиграть это состязание. Мои соперники обзавелись заколдованным оружием, что ставит меня в невыгодное положение, но я не отчаиваюсь.$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его Джейлин Закатной Песне а шатер Альянса на Ристалище Серебряного турнира.', 'Так значит, это не сказки? Какой замечательный клинок! Не сомневаюсь, он верно послужит мне на турнире. Спасибо тебе, $N.', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13758, 'Достойное оружие', 'Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', 'Принесите меч Драк\'Мара Джейлин Закатной Песне в шатер Альянса на Ристалище Серебряного турнира.', '<Джейлин принимает у вас меч Драк\'Мара.>$B$BПрекрасное оружие, отлично сбалансировано... этот меч сослужит мне добрую службу в следующем поединке.', 'Так барды говорят правду? Меч действительно существует?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13759, 'Клинок Зимы', 'Проклятый рыцарь смерти сломал мой клинок.$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Джейлин Закатная Песня из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести ей Клинок Зимы.', 'Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13760, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих вынужденных слуг Плети, тем самым подготовившись к настоящей битве.', 'Убейте 10 обращенных героев в Ледяной Короне по заданию Иллестрии Певицы Клинка из Павильона Серебряного союза на Ристалище Серебряного турнира.', 'С возвращением, $N. Даже во время тренировок мы не должны забывать о реальной угрозе, с которой придется иметь дело после окончания турнира.', NULL, NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13761, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Люди Дарнаса надеются на нашу победу. Лучший способ усовершенствовать свои навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BОни тренируются на арене прямо за нашей палаткой. Послушай моего совета – иди в стойла за павильоном, оседлай дарнасского туманного саблезуба и брось вызов искателям славы Альянса.', 'Принесите три знака искателя славы Айре Устремленной к Звездам в шатер Альянса на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Молодец! Тренировка вместе с другими искателями славы – это лучший способ подготовиться к турниру. Я знаю, что ты принесешь победу Дарнасу, $N.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13762, 'Клинок, достойный чемпиона', 'Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его Мокре Дробителю Черепов в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', 'Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13763, 'Достойное оружие', 'Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', 'Принесите меч Драк\'Мара Мокре Дробителю Черепов в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', 'Этот меч поможет мне одолеть соперников. Спасибо тебе, $N.', 'Так барды говорят правду? Меч действительно существует?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13764, 'Клинок Зимы', 'Проклятый рыцарь смерти сломал мой клинок.$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Мокра Дробитель Черепов из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', 'Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, Ламборджин.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13765, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', 'Убейте 10 обращенных героев в Ледяной Короне по заданию Акиноса из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Хорошая тренировка – залог успеха. Приятно видеть твои старания.', NULL, NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13767, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе не сомневаюсь. Продолжай тренировки верхом до тех пор, пока не будешь действовать как одно целое со своим верховым животным. $B$BЯ помогу тебе подготовиться к битве. Иди в стойла за павильоном, оседлай оргриммарского волка и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.', 'Принесите три знака искателя славы Море Сестре Воргов в шатер Орды на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.', 'Тренируясь с другими искателями славы, ты отточишь свои навыки и улучшишь реакцию. И вскоре ты будешь готов выйти на арену и победить.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13768, 'Клинок, достойный чемпиона', 'Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его Зул\'тору в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', 'Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13769, 'Достойное оружие', 'Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', 'Принесите меч Драк\'Мара Зул\'тору в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', 'Этот меч поможет мне одолеть соперников. Спасибо тебе, $N.', 'Так барды говорят правду? Меч действительно существует?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13770, 'Клинок Зимы', 'Проклятый рыцарь смерти сломал мой клинок.$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Зул\'тор из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', 'Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, Совух.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13771, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', 'Убейте 10 обращенных героев по заданию темного охотника Мезил-Кри из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Хорошая тренировка – залог успеха. Приятно видеть твои старания.', NULL, NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13772, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе не сомневаюсь. Продолжай тренировки верхом до тех пор, пока не сможешь действовать как одно целое со своим верховым животным. $B$BЯ помогу тебе подготовиться к битве. Иди в стойла за павильоном, оседлай ящера Черного Копья и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.', 'Принесите три знака искателя славы Гаджу в шатер Орды на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.', 'Сражаясь против других искателей славы, ты вскоре узнаешь, как их победить. Продолжай в том же духе – и вскоре ты без труда выиграешь соревнования.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
