INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13776, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся в область к юго-западу от долины Павших Героев и к северу от Корп\'Ретар. Там Плеть поднимает павших воинов из мертвых и отправляет их на битву с нами. Убей несколько приспешников Плети и готовься к дальнейшим подвигам.', 'Убейте 10 обращенных героев по заданию Дерна Тотема Ярости из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Хорошая тренировка – залог успеха. Приятно видеть твои старания.', NULL, NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13777, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверена. Продолжай тренировки верхом, до тех пор, пока не сможешь действовать как одно целое со своим верховым животным.$B$BЯ помогу тебе подготовиться к битве. Иди в стойла за павильоном, оседлай мулгорского кодо и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.', 'Принесите три знака искателя славы Анке Точеное Копыто в шатер Орды на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.', 'Тренируясь с другими искателями славы, ты отточишь свои навыки и улучшишь реакцию. И вскоре ты будешь готов выйти на арену и победить.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13778, 'Клинок, достойный чемпиона', 'Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его стражу смерти Визери в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', 'Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13779, 'Достойное оружие', 'Что за невезение!$B$BПропал мой турнирный меч – именно тогда, когда он мне так нужен на вечерних состязаниях.$B$BВпору обратиться за помощью к потусторонним силам. Один из бардов поведал мне о том, что когда-то путешественники одаривали некую одинокую деву зимними гиацинтами в обмен на чудесные дары. Эти гиацинты растут только на ледяных равнинах Железной плотины. Она находится на северо-западе Леса Хрустальной Песни, на границе с Ледяной Короной. Собери цветы и отнеси их к озеру Драк\'Мар. Оно находится на северо-востоке Драконьего Погоста, рядом с границей, отделяющей его от Зул\'Драка и Седых холмов.', 'Принесите меч Драк\'Мара Стражу смерти Визери на Ристалище Серебряного турнира.', 'Этот меч поможет мне одолеть соперников. Спасибо тебе, $N.', 'Так барды говорят правду? Меч действительно существует?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13780, 'Клинок Зимы', 'Проклятый рыцарь смерти сломал мой клинок.$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Страж смерти Визери из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', 'Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13781, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', 'Убейте 10 обращенных героев по заданию Сары Чолк из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Хорошая тренировка – залог успеха. Приятно видеть твои старания.', NULL, NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13782, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверен. Продолжай тренировки верхом, до тех пор, пока не сможешь действовать как одно целое со своим верховым животным.$B$BЯ помогу тебе подготовиться к битве. Иди в стойла и оседлай боевого коня Отрекшихся и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.', 'Принесите три знака искателя славы дрессировщику Дречу в шатер Орды на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.', 'Тренируясь с другими искателями славы, ты отточишь свои навыки и улучшишь реакцию. И вскоре ты будешь готов выйти на арену и победить.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13783, 'Клинок, достойный чемпиона', 'Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.', 'Раздобудьте меч Ясеневого озера и принесите его Эрессее Певице Рассвета в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', 'Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!', 'Меч у тебя?', NULL, NULL, 'Меч Ясеневого озера', 'Губная помада \"Бородавки прочь\"', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13784, 'Достойное оружие', 'Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами.', 'Принесите меч Драк\'Мара Эрессее Певице Рассвета в Павильон Похитителей Солнца на Ристалище Серебряного турнира.', 'Этот меч поможет мне одолеть соперников. Спасибо тебе, $N.', 'Так барды говорят правду? Меч действительно существует?', NULL, NULL, 'Меч Драк\'Мара', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13785, 'Клинок Зимы', 'Проклятый рыцарь смерти сломал мой клинок.$B$BВ центре озера Дыхания Зимы в ледяном плену томится прекрасная дева. Она – хранительница древнего меча, и отдаст его тому, кто ее освободит.$B$BНа юге Леса Хрустальной Песни, над выходом из ущелья Порочных Кристаллов, ты найдешь лорда Вечнопылающего. Убей его, забери жгучий уголь и с его помощью освободи деву. Докажи, что ты $gдостоин:достойна: этого меча.', 'Эрессея Певица Рассвета из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.', 'Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, Ламборджин.', 'Ну как? Получилось добыть меч?', NULL, NULL, 'Клинок Зимы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13786, 'Теория и практика', 'Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.', 'Убейте 10 обращенных героев по заданию Кетиэля Солнечного Копья из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Хорошая тренировка – залог успеха. Приятно видеть твои старания.', NULL, NULL, NULL, 'Обращенный герой убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13787, 'Великая битва', 'Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверена. Продолжай тренироваться вместе со своим верховым животным, пока вы не будете действовать как одно целое.$B$BЯ помогу тебе подготовиться к битве и покажу, на что способны другие искатели славы. Иди в стойла за павильоном, оседлай крылобега Луносвета и брось вызов искателям славы. Они ждут тебя на Арене искателей славы Орды, прямо за этой палаткой.', 'Принесите три знака искателя славы Анире Турон в Павильон Похитителей Солнца на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Серебряного союза.', 'Тренируясь с другими искателями славы, ты отточишь свои навыки и улучшишь реакцию. И вскоре ты будешь готов выйти на арену и победить.', 'Ты уже готов принять участие в великой битве?', NULL, NULL, 'Знак искателя славы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13788, 'Атака с воздуха', 'После того, как тебе удалось обнаружить лазутчика Культа Проклятых, Серебряный Авангард приказал удвоить охрану. Они не верят, что Культ остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа.$B$BТы должен перехватить их до того, как они нападут на нас. Ледяную Пасть видели на юго-западе, между Железным валом и Алдур\'таром.', 'Крок Гроза Плети с Ристалища Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов – сектантов.', '$N, ты и твои союзники защитили турнир от нападения врагов. Серебряный Авангард и все участники турнира в долгу перед тобой, и мы лично проследим, чтобы тебе были оказаны надлежащие почести. К сожалению, несмотря на все заявления о неусыпной охране нашей безопасности, миротворцы и воздушные разведчики больше занимаются пьяными драками, чем угрозой со стороны Плети.$B$BНу ничего. Мы и сами справимся.', NULL, NULL, NULL, 'Ледяная Пасть убито', 'Бомбист-сектант убито', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13789, 'Битва на вражеской территории', 'Для постройки Колизея было выбрано очень опасное место, $N. За эти земли, отбитые у Плети, мы заплатили кровью и болью, но враг и сейчас не прекращает атаковать нас бесчисленным войском.Хуже того, эту ненавистную нежить поддерживают приверженцы среди Культа Проклятых.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся.', 'Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Селлиана Первого Луча из Серебряного павильона на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны.', 'Ты настоящий чемпион, $N – как на ристалище, так и на поле боя. Мы должны сдерживать напор Плети, и ты только что подал отличный пример нашим братьям и своему народу.', NULL, NULL, NULL, 'Убито членов Культа Проклятых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13790, 'На равных с чемпионами', 'Итак, чемпион, ты $gосвоил:освоила: искусство верхового поединка и $gпрошел:прошла: испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.', 'Принесите 4 знака чемпиона Луури в павильон Серебряного союза на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне.', 'Молодец! Тренировка вместе с другими искателями славы – это лучший способ подготовиться к турниру. Я знаю, что ты не подведешь Альянс, $N.', 'Ты закончил тренироваться вместе с другими чемпионами?', NULL, NULL, 'Знак чемпиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13791, 'Битва на вражеской территории', 'Пока мы тут играем в войну, неплохо было бы вспомнить о том, что нас окружают реальные противники. Серебряный Авангард хочет найти лучших воинов с помощью турнира, но мы можем отыскать их и среди тех, кто вернулся с настоящей войны. Давай покажем этим паладинам, что мы можем сражаться с Плетью даже во время подготовки к состязаниям.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся. Чаще всего они бродят вокруг Алдур\'тара и Заставы Вестника Смерти.', 'Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Зор\'бе Кровопускателя с Ристалища Серебряного турнира. Вы можете действовать в любой области Ледяной Короны.', 'Пусть все знают – мы готовы сражаться с Плетью в любой момент, где бы мы ни были и чем бы ни занимались.', NULL, NULL, NULL, 'Убито членов Культа Проклятых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13793, 'На равных с чемпионами', 'Итак, чемпион, ты $gосвоил:освоила: искусство верхового поединка и $gпрошел:прошла: испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.', 'Принесите 4 знака чемпиона Иллирии Приходу Тьмы на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне Серебряного союза.', 'Ты отлично управляешься со своим верховым животным, $N. Когда-нибудь остальные участники будут страшиться тебя.', 'Ты закончил тренироваться вместе с другими чемпионами?', NULL, NULL, 'Знак чемпиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13794, 'Эдрик Чистый', 'Я обратилась к моим братьям из Серебряного Авангарда с просьбой обратить особое внимание на тех, кто сумел получить звание чемпиона. Эдрик Чистый, абсолютный чемпион нашего братства, лично следит за тренировками воинов из всех городов Азерота и помогает им подготовиться к главному состязанию.$B$BПожалуйста, подойди к нему и представься. Он будет рад встретиться с тобой и подготовить тебя к поединкам с величайшими воинами Азерота.', 'Поговорите с Эдриком Чистым из Серебряного павильона на Ристалище Серебряного турнира.', 'Наконец-то мы встретились, чемпион. Верховный лорд поручил мне координировать тренировки всех чемпионов и поддерживать порядок на Ристалище.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13795, 'Гроза Плети', 'Меня просил поговорить с тобой глава делегации Рыцарей Черного Клинка. Крок Гроза Плети – могучий воин, и я не сомневаюсь, что он многого потребует от тебя, $C.$B$BРыцари Черного Клинка разбили лагерь на северной стороне Ристалища, к западу от палаток Альянса.', 'Поговорите с Кроком Грозой Плети в северной стороне Ристалище Серебряного турнира.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13809, 'Атака с воздуха', 'После того, как тебе удалось обнаружить лазутчика Культа Проклятых, верховный лорд Тирион Фордринг приказал удвоить охрану. Он не верит, что их остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа. Его видели на юго-западе, между Железным валом и Алдур\'таром.', 'Эдрик Чистый из Серебряного павильона на Ристалище Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов – сектантов.', 'Профессия, ты и твои союзники защитили турнир от нападения врагов. Хотя наши воздушные разведчики не менее отважны, у них много дел по охране воздушного пространства. Мы благодарим тебя от лица Серебряного Авангарда и всех участников турнира.', NULL, NULL, NULL, 'Ледяная Пасть убито', 'Бомбист-сектант убито', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13810, 'Битва на вражеской территории', 'Для постройки Колизея было выбрано очень опасное место, $N. За эти земли, отбитые у Плети, мы заплатили кровью и болью, но враг и сейчас не прекращает атаковать нас бесчисленным войском. Хуже того, эту ненавистную нежить поддерживают приверженцы среди культа Проклятых.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа, которые тебе встретятся.', 'Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Селлиана Первого Луча из Серебряного павильона на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны.', 'Ты настоящий чемпион, $N– как на ристалище, так и на поле боя. Мы должны сдерживать напор Плети, и ты только что подал отличный пример нашим братьям и своему народу.', NULL, NULL, NULL, 'Убито членов Культа Проклятых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13811, 'На равных с чемпионами', 'Итак, чемпион, ты $gосвоил:освоила: искусство верхового поединка и $gпрошел:прошла: испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.', 'Принесите 4 знака чемпиона Луури в павильон Серебряного союза на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне Похитителей Солнца.', 'Молодец! Тренировка вместе с другими искателями славы – это лучший способ подготовиться к турниру. Я знаю, что ты не подведешь Орду, Профессия.', 'Ты закончил тренироваться вместе с другими чемпионами?', NULL, NULL, 'Знак чемпиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13812, 'Атака с воздуха', 'После того, как тебе удалось обнаружить лазутчика Культа Проклятых, Серебряный Авангард приказал удвоить охрану. Они не верят, что Культ остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа.$B$BТы должен перехватить их до того, как они нападут на нас. Ледяную Пасть видели на юго-западе, между Железным валом и Алдур\'таром.', 'Крок Гроза Плети с Ристалища Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов – сектантов.', '$N, ты и твои союзники защитили турнир от нападения врагов. Серебряный Авангард и все участники турнира в долгу перед тобой, и мы лично проследим, чтобы тебе были оказаны надлежащие почести. К сожалению, несмотря на все заявления о неусыпной охране нашей безопасности, миротворцы и воздушные разведчики больше занимаются пьяными драками, чем угрозой со стороны Плети.$B$BНу ничего. Мы и сами справимся.', NULL, NULL, NULL, 'Ледяная Пасть убито', 'Бомбист-сектант убито', 'Рекомендуемое количество игроков: 3', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13813, 'Битва на вражеской территории', 'Пока мы тут играем в войну, неплохо было бы вспомнить о том, что нас окружают реальные противники. Серебряный Авангард хочет найти лучших воинов с помощью турнира, но мы можем отыскать их и среди тех, кто вернулся из настоящей битвы. Давай покажем этим паладинам, что мы можем сражаться с Плетью даже во время подготовки к состязаниям.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся. Чаще всего они бродят вокруг Алдур\'тара и Заставы Вестника Смерти.', 'Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Зор\'бе Кровопускателя с Ристалища Серебряного турнира. Вы можете действовать в любой области Ледяной Короны.', 'Пусть все знают – мы готовы сражаться с Плетью в любой момент, где бы мы ни были и чем бы ни занимались.', NULL, NULL, NULL, 'Убито членов Культа Проклятых', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13814, 'На равных с чемпионами', 'Итак, чемпион, ты $gосвоил:освоила: искусство верхового поединка и $gпрошел:прошла: испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.', 'Принесите 4 знака чемпиона Иллирии Приходу Тьмы на Ристалище Серебряного турнира.Если вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне Похитителей Солнца.', 'Ты отлично управляешься со своим верховым животным, $N. Когда-нибудь остальные участники будут трепетать перед тобой.', 'Ты закончил тренироваться вместе с другими чемпионами?', NULL, NULL, 'Знак чемпиона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13816, 'Священный планетарий (героич.)', 'Слушай внимательно! На кону – судьба всего Азерота.$B$BТолько одно спасет нас – нужно найти Священный планетарий и помешать этому Алгалону отправить сообщение его повелителям-титанам.$B$BОтыщи Священный планетарий и возвращайся со всеми данными, которые сможешь там собрать. Может быть, мы успеем подготовиться к прибытию Алгалона.', 'Найдите Священный планетарий по заданию геолога Лорен из Архива в Ульдуаре.', 'Закрыт? Так я и думала!$B$BЯ сообщу Бранну... может быть, он обнаружит какие-либо сведения в Архиве.', 'Ты нашел его, $N?', NULL, NULL, 'Исследовать локацию', 'Вход в Священный планетарий найден', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13817, 'Диск доступа к Архиву (героич.)', 'Платиновый диск правильной формы выглядит совершенно новым – на нем нет ни единой царапины. По краю его выгравирована руническая надпись: \"АРХИВ\".$B$BДолжно быть, в глубинах Ульдуара есть устройство, с помощью которого можно прочитать этот диск.', 'Отнесите диск доступа к Архиву к панели управления Архивом в Ульдуаре.', 'Платиновый диск идеально подходит к гнезду на панели. Он начинает вращаться, белые лучи считывают с него какую-то информацию.', 'Гнездо приемника открывается, а панель управления жужжит и вибрирует.', NULL, NULL, 'Диск доступа к Архиву (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13818, 'Алгалон (героич.)', 'Ты $gсправился:справилась:, $N. Теперь возьми печати, отнеси их к панели управления Архивом и попытайся получить доступ к Священному планетарию.$B$BПоторопись, $gдруг:подруга: – дорога каждая секунда.', 'Принесите печати хранителей к панели управления Архивом в Ульдуаре.', 'Ожидайте подтверждения.$B$BДоступ в Священный планетарий разрешен. Пожалуйста, возьмите ключ.', 'Яркие лучи панели периодически освещают стеклянную поверхность, как будто ожидают ввода данных.', NULL, NULL, 'Печати хранителей (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13819, 'Все хорошо, что хорошо кончается (героич.)', 'Мы должны поторопиться, $N – надо передать код отклика из Даларана как можно скорее.$B$BОтнеси его Ронину, я встречу тебя там.', 'Доставьте код отклика \"Альфа\" Ронину в Даларан.', '', NULL, NULL, NULL, 'Код отклика \"Альфа\" (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13820, 'Семья Рвизасовов', 'Верховный лорд поручил мне завершить строительство Колизея как можно быстрее. Мы бросили все наши силы на эту работу, но очень скоро обнаружили, что нам потребуется помощь в доставке материалов. Для этого я наняла парочку гоблинов – Беззла Рвизасова и его брата Боззла.$B$BОни руководят строительством юго-восточной части Ристалища. Поговори с Беззлом и узнай, не нужна ли им помощь в доставке материалов.', 'Поговорите с Беззлом Рвизасовом на Ристалище Серебряного турнира.', 'Так тебя послала к нам Вершительница правосудия? Замечательно...$B$BНам всегда пригодится помощь с доставкой материалов.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13821, 'Печать Фрейи (героич.)', 'Печать Фрейи достать будет сложнее всего.$B$BСогласно данным из Архива, сущность печати связана с тремя старшими слугами Фрейи – Светлым Листом, Железной Ветвью и Каменной Корой. Если хоть один из них пострадает, сущность печати будет повреждена.$B$BНо если ты пощадишь слуг, силы Фрейи приумножатся.$B$BЧто еще сказать, $N... оказались мы между молотом и наковальней.', 'Добудьте печать Фрейи по заданию геолога Лорен.За дополнительными сведениями обратитесь к панели управления Архивом.', '', NULL, NULL, NULL, 'Печать Фрейи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13822, 'Печать Ходира (героич.)', 'Печать Ходира будет нелегко раздобыть. Во-первых, тебе придется одолеть самого Ходира. А во-вторых, одолеть его нужно до того, как он уничтожит сундук с печатью!$B$BВоспользуйся панелью управления Архивом, чтобы получить дополнительные сведения. Эта премудрая штуковина стоит всех библиотек мира!', 'Добудьте печать Ходира по заданию геолога Лорен.За дополнительными сведениями обратитесь к панели управления Архивом.', '', NULL, NULL, NULL, 'Печать Ходира', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13823, 'Печать Торима (героич.)', 'Торим не в себе, $N. Он во власти темных сил.$B$BТемная сущность приняла обличье его погибшей жены, Сиф.$B$BНельзя позволить иллюзии свести его с ума. Если это случится, то мы никогда не сможем найти печать Торима!$B$BВразуми его, и побыстрее.$B$BКак обычно, за подробностями этой жуткой истории можешь обратиться к панели управления Архивом... но они вряд ли тебе понравятся.', 'Добудьте печать Торима по заданию геолога Лорен.За дополнительными сведениями обратитесь к панели управления Архивом.', '', NULL, NULL, NULL, 'Печать Торима', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13824, 'Печать Мимирона (героич.)', 'Мимирон хитер – в его комнате установлен какой-то механизм самоуничтожения.$B$BЕсли хочешь получить его печать, тебе придется победить его до того, как механизм завершит свой цикл. Если тебе нужно больше информации – воспользуйся панелью управления Архивом.', 'Добудьте печать Мимирона по заданию геолога Лорен.За дополнительными сведениями обратитесь к панели управления Архивом.', '', NULL, NULL, NULL, 'Печать Мимирона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13825, 'Мидии с сюрпризом', '', 'Эй, а я тебя помню! Ты же $C, который помог мне раздобыть мидии!Заходи, я угощу тебя блюдом по новому рецепту – оно такое вкусное и простое в изготовлении!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13826, 'Нат Пэгл, великий рыболов', '', 'Привет, юный $R. То ли память меня подводит, то ли в прошлый раз я забыл отдать тебя это...', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13828, 'Мастер ближнего боя', 'Суть турнира – это верховой поединок. Возьми копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Джерану Локвуду, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Джеран обучит тебя тонкостям ведения ближнего боя, чтобы поединок не закончился для тебя с первым ударом.', 'Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Джераном Локвудом и отработайте прием \"Выпад\" 5 раз на манекене для ближнего боя. После этого вернитесь к чародею Таэлису в Павильон Серебряного союза на Ристалище Серебряного турнира.', 'Во время тренировки помни, чему учил тебя мастер.', NULL, NULL, NULL, 'Cовет от Джерана Локвуда получен', 'Манекен для ближнего боя поражен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13829, 'Мастер ближнего боя', 'Суть турнира – это верховой поединок. Возьми копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Джерану Локвуду, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Джеран обучит тебя тонкостям ведения ближнего боя, чтобы поединок не закончился для тебя с первым ударом.', 'Вооружитесь копьем и оседлайте крылобега Похитителей Солнца – он ждет вас снаружи павильона. Поговорите с Джераном Локвудом и отработайте прием \"Выпад\" 5 раз на манекене для ближнего боя. После этого вернитесь к магистру Эдиену Солнечной Низине в шатер Орды на Ристалище Серебряного турнира.', 'Во время тренировки помни, чему учил тебя мастер.', NULL, NULL, NULL, 'Cовет от Джерана Локвуда получен', 'Манекен для ближнего боя поражен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13830, 'Рыба-призрак', '$gВсякий стоящий рыболов:Всякая стоящая рыбачка: в Нордсколе знает о карликовой рыбе-прилипале, называемой среди знатоков \"сосокунем\". Она несъедобна, но алхимики часто используют ее для приготовления зелий.$B$BНо речь не об этом. Если ты внимательно присмотришься к косяку прилипал в водах Слияния рек в низине Шолазар, то заметишь затесавшуюся среди них рыбу-призрака. На воздухе она становится прозрачной и в конце концов попросту исчезает. Многие считают, что она возвращается в Шолазар, но есть и те, кто сочиняет о ней всякие небылицы.$B$BВылови эту рыбу и раскрой ее секрет!', 'Раскройте тайну рыбы-призрака по просьбе Марсии Чейз из Даларана.', 'Значит, съевший ее становится невидимым... чудны бывают творения природы.$B$BНадо бы съесть парочку. Ох, извини, $N, ничего личного! Правда! Заходи завтра, поболтаем.', NULL, NULL, NULL, 'Загадка рыбы-призрака раскрыта.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13832, 'Звезда сточных вод', 'Представляешь, некоторые граждане ловят в Стоках Даларана гигантских крыс и рыб-мутантов. А ведь в здешних водах можно найти столько ценного! Обманутые любовники, пойманные с поличным воры, неосторожные пьяницы – каждый сбрасывает или роняет сюда какую-нибудь приятную мелочь.$B$BДостаточно просто достать крючком до дна и не дергать леску слишком резко, когда что-нибудь попадется. Попробуй, $N. Что поймаешь – тащи ко мне. Будем торговаться!', 'Принесите Марсии Чейз в Даларан ржавое украшение.', 'Похоже, это что-то ценное. Трудно сказать наверняка, нужно счистить грязь и показать эту штучку оценщику. Но я все равно куплю ее у тебя – на всякий случай.', 'Как рыбалка?', NULL, NULL, 'Ржавые драгоценности', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13833, 'Густая кровь', 'Как можно понять из названия, ужорь – это весьма прожорливая рыбешка. Лекари используют ее для варки исцеляющих составов, поэтому если хочешь заработать – иди за ужрем-кровопийцей.$B$BОни падки на кровь, поэтому проще всего убить какую-нибудь зверушку в Борейской тундре, намазаться ее кровью, затем искупаться в озерной воде и начать рыбачить.', 'Принесите Марсии Чейз в Даларан 5 ужрей-кровопийц.', 'Храбрости тебе не занимать, $N. Надеюсь, ты не перегнул палку, добывая кровь для рыбалки. Если тебе понравилось ловить ужрей, приходи завтра.', 'Ну что – удалось поймать хоть одного ужорька? Не забывай – их проще всего приманить на кровь!', NULL, NULL, 'Ужорь-кровопийца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13834, 'Опасный деликатес', 'Чем ценнее улов, тем опаснее рыбалка. В озере Ледяных Оков водится редкая рыба, но ловить ее примется лишь безрассудный.$B$BЯ толкую о террорели. Она страшно ядовита и ужасно вкусна. Вот принесешь мне ее – тогда пойдет другой разговор.', 'Принесите Марсии Чейз в Даларан 10 террорелей.', 'Утопи меня кальмар! Это же террорель! Эхе-хе, помню, были времена...$B$B<Найдя благодарного слушателя, Марсия пускается в бесконечные воспоминания о прошлых рыбалках.:', 'Запомни – с террорелями переговоры не ведут!', NULL, NULL, 'Террорель', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13835, 'Мастер дальнего боя', 'Чтобы преуспеть в верховом поединке, нужно лишить противника защиты. Возьми вот это копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.$B$BПотом езжай к Валису Ловцу Ветра, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Валис научит тебя приему \"Удар по щиту\" – это поможет тебе ослабить противника.', 'Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Валисом Ловцом Ветра и отработайте \"Удар по щиту\" 2 раза на мишени для дальнего боя. После этого вернитесь к разведчице Шалиндрии на Ристалище Серебряного турнира.', 'Запомни уроки Валиса, $N. Они станут ключом к твоей победе в турнире.', 'Ты уже научился разбивать щиты противников?', NULL, NULL, 'Совет от Валиса Ловца Ветра получен', 'Мишень для дальнего боя поражена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13836, 'Обезручен!', 'До меня дошли слухи о трагедии в даларанской тюрьме – особо опасный заключенный отгрыз руку одному из охранников и выбросил ее в воду.$B$BДоктора из больницы скорой помощи говорят, что ее еще можно пришить.$B$BДостаточно порыбачить хорошенько возле тюрьмы и, ставлю свой любимый гарпун, рука непременно всплывет на поверхность. Найди руку и принеси ее Олисарре Доброй в Даларан. Остальное она сделает сама.', 'Принесите откушенную руку Олисарре Доброй в Даларан.', 'Здравствуй, $N. Марсия предупредила меня, что ты нашел руку этого бедняги.$B$BОна также сказала, что в благодарность за помощь ты можешь взять эту сумку. Если честно, из сумки чем-то отвратительно воняет – так что забери ее скорее!', 'Приветствую. У вас лишней руки не найдется?', NULL, NULL, 'Откушенная рука', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13837, 'Мастер стремительной атаки', 'Самым эффективным приемом в верховом поединке является \"Рывок\". Возьми копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Рагану Сталебрюху, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Он научит тебя этому удару и покажет основные стратегические приемы.', 'Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Раганом Сталебрюхом и отработайте \"Рывок\" 2 раза на манекене для стремительной атаки. После этого вернитесь к Аварету Молниеносному Удару в шатер Альянса на Ристалище Серебряного турнира.', 'С таким учителем, как Раган, ты не успеешь глазом моргнуть, как научишься премудростям верхового поединка.', NULL, NULL, NULL, 'Совет от Рагана Сталебрюха получен', 'Манекен для стремительной атаки поражен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13838, 'Мастер дальнего боя', 'Чтобы преуспеть в верховом поединке, нужно лишить противника защиты. Возьми вот это копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.$B$BПотом езжай к Валису Ловцу Ветра, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Валис научит тебя приему \"Удар по щиту\" – это поможет тебе ослабить противника.', 'Вооружитесь копьем и оседлайте крылобега Похитителей Солнца – он ждет вас снаружи павильона. Поговорите с Валисом Ловцом Ветра и 2 раза отработайте \"Удар по щиту\" на мишени для дальнего боя. После этого вернитесь к Галатии Сияющий Рассвет в шатер Орды на Ристалище Серебряного турнира.', 'Запомни уроки Валиса, $N. Они станут ключом к твоей победе в турнире.', NULL, NULL, NULL, 'Совет от Валиса Ловца Ветра получен', 'Мишень для дальнего боя поражена', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13839, 'Мастер стремительной атаки', 'Самым эффективным приемом в верховом поединке является \"Рывок\". Возьми копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Рагану Сталебрюху, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Он научит тебя этому удару и покажет основные стратегические приемы.', 'Вооружитесь копьем и оседлайте крылобега Похитителей Солнца – он ждет вас снаружи павильона. Поговорите с Раганом Сталебрюхом и отработайте прием \"Рывок\" 2 раза на манекене для стремительной атаки. После этого вернитесь к Амариэлю Верному Солнцу в шатер Орды на Ристалище Серебряного турнира.', 'Опыт и практика сделают из тебя непобедимым воином.', 'Ты научился приему \"Рывок\"?', NULL, NULL, 'Совет от Рагана Сталебрюха получен', 'Манекен для стремительной атаки поражен', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13845, 'Запечатанный фиал с ядом', 'Этот яд, похоже, смертельно опасен. Может быть, кто-нибудь в Даларане заинтересуется им.', 'Принесите запечатанный фиал с ядом алхимику Синесре в Стоки Даларана.', 'Только смельчак или дурак положил бы эту склянку в сумку. Если бы хоть одна капля попала тебе на кожу, ты умер бы в страшной агонии.$B$BНо раз уж ты жив, то, наверное, захочешь продать мне это зелье. Оно мне еще не раз пригодится.', 'Неужели это – то, о чем я думаю, $C?', NULL, NULL, 'Запечатанный фиал с ядом (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13846, 'Вклад в общее дело', 'Лучшие из лучших чемпионов ежедневно приходят к часовне, чтобы послушать речи исповедницы.$B$B<Видел:Видела: бы ты, как это их вдохновляет! Они находят в себе силы продолжать сражение за дело Серебряного Авангарда и вносят посильный вклад в наше общее дело.$B$BМожет быть, и ты, $N, внесешь свою лепту? Пожертвуй немного золота на нужды Авангарда!', 'Поговорите с оруженосцем Арти и пожертвуйте 10 золотых на нужды Серебряного Авангарда.', 'Благодарю. Будь уверен, эти деньги пойдут на благие дела!', 'Ты хочешь сделать пожертвование?', NULL, NULL, 'Требуется денег: 10', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13847, 'У вражеских врат', 'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию капитана Джозефа Холли из Павильона Серебряного союза на Ристалище Серебряного турнира.', 'Твоя доблесть на поле битвы показала рыцарям, что мы способны не только блистать на парадах, но и встретить врага лицом к лицу!', NULL, NULL, NULL, 'Костяной пехотинец убито', 'Костяной разведчик убито', 'Костяной лейтенант убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13850, 'Иммунитет к яду', 'Хочешь купить ядошкурого равазавра? Тогда я должен тебя предупредить.$B$BЭти зверюшки ядовиты от кончика носа до кончика хвоста: ядовитая кровь, ядовитая слюна, ядовитая шкура. Заберись на него, и через несколько часов ты труп.$B$BЧтобы этого не произошло, нужно выработать иммунитет к их яду, а это – долгий, очень долгий процесс... нужно, чтобы кровь равазавра попала на твою кожу бесчисленное количество раз. Если хочешь попробовать, то отправляйся на северо-запад отсюда – равазавры во множестве обитают на севере Топей.', 'Мор\'век из Кратера Ун\'Горо утверждает, что вам необходимо 20 раз отравиться кровью ядошкурого равазавра, чтобы выработать иммунитет к яду. Чтобы кровь равазавра попала на вашу кожу, нападите на него.', 'Да ну? Неужели?!$B$BХо-хо! Да ты упрямее моей благоверной!', NULL, NULL, NULL, 'Отравиться кровью ядовитого равазавра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13851, 'У вражеских врат', 'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Клары Взубногой из Павильона Серебряного союза на Ристалище Серебряного турнира.', 'Твоя доблесть на поле битвы показала рыцарям, что мы достойные союзники.', NULL, NULL, NULL, 'Костяной пехотинец убито', 'Костяной разведчик убито', 'Костяной лейтенант убито', NULL);
