INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13857, 'У вражеских врат', 'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Гаджу из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Твоя доблесть на поле битвы показала рыцарям, что мы не дрогнем перед полчищами Короля-лича.', NULL, NULL, NULL, 'Костяной пехотинец убито', 'Костяной разведчик убито', 'Костяной лейтенант убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13858, 'У вражеских врат', 'Несмотря на проводимый турнир, Серебряный авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Анки Точеное Копыто из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Твоя доблесть на поле битвы показала рыцарям, что мы не подведем их в битве с Королем-личом.', NULL, NULL, NULL, 'Костяной пехотинец убито', 'Костяной разведчик убито', 'Костяной лейтенант убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13859, 'У вражеских врат', 'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Аниры Турон из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Твоя доблесть на поле битвы показала рыцарям, что мы готовы встретить врага лицом к лицу!', NULL, NULL, NULL, 'Костяной пехотинец убито', 'Костяной разведчик убито', 'Костяной лейтенант убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13860, 'У вражеских врат', 'Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию дрессировщика Дреча из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Рыцари Серебряного Авангарда убедились в нашей доблести и теперь знают, что мы будем стоять до конца.', NULL, NULL, NULL, 'Костяной пехотинец убито', 'Костяной разведчик убито', 'Костяной лейтенант убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13861, 'Битва у Цитадели', 'Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'По заданию Эдрика Чистого из Серебряного павильона на Ристалище Серебряного турнира убейте 3 костяных командиров.', 'Как прекрасно, что на стороне Серебряного Авангарда сражается такой доблестный $C, как ты.', NULL, NULL, NULL, 'Костяной командир убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13862, 'Битва у Цитадели', 'Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'По заданию Эдрика Чистого из Серебряного павильона на Ристалище Серебряного турнира убейте 3 костяных командиров.', 'Как прекрасно, что на стороне Серебряного Авангарда сражается такой доблестный $C, как ты.', NULL, NULL, NULL, 'Костяной командир убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13863, 'Битва у Цитадели', 'Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'По заданию Крока Грозы Плети с Ристалища Серебряного турнира убейте 3 костяных командиров.', 'Всюду, где появляемся мы, Плеть бежит в ужасе. И следующая атака не будет исключением.', NULL, NULL, NULL, 'Костяной командир убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13864, 'Битва у Цитадели', 'Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $N – копыта твоего скакуна легко переломают их истлевшие кости.', 'По заданию Крока Грозы Плети с Ристалища Серебряного турнира убейте 3 костяных командиров.', 'Всюду, где появляемся мы, Плеть бежит в ужасе. И следующая атака не будет исключением.', NULL, NULL, NULL, 'Костяной командир убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13887, 'Яйца ядошкурого равазавра', 'Теперь, когда у тебя выработался иммунитет к яду равазавра, ты сможешь прикасаться как к самим животным, так и к ядовитым яйцам. Эти ящеры – хищные зверюги, и их надо приручать с самого рождения.$B$BТак что, если ты хочешь оседлать равазавра, найди невылупившееся яйцо – их полно в гнездах по всей Топи. Ищи яйца со светлой скорлупой – именно из таких рождаются ядошкурые равазавры.$B$BЕсли принесешь мне несколько яиц, я разрешу тебе взять одно из них и научу, как приручить твоего зверька.', 'Принесите Мор\'веку 4 яйца ядошкурого равазавра. Он будет ждать вас на юго-востоке Топей.', 'Молодец! Честно говоря, я удивлен тем, что тебе удалось достать так много яиц. В последнее время они встречаются все реже и реже.$B$BВот, возьми этого равазаврика. Он сам даст тебе знать, что ему нужно.', 'Ты нашел яйца?', NULL, NULL, 'Яйцо ядошкурого равазавра', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13889, 'Бедный, голодный равазаврик', 'Равазаврик выжидательно смотрит на вас, после чего начинает опять что-то рисовать в грязи.$B$BКонечно, рисунки очень грубые, но вам все же удается разобрать очертания деметродонов, стегодонов и терродактилей. Когда ящер заканчивает рисунок, он ощеривает зубы и выразительно щелкает челюстью.$B$BНаверное, ваш равазаврик хочет свежего мяса. Убейте несколько любых деметродонов, стегодонов и терродактилей в кратере Ун\'Горо и накормите голодного малыша.', 'Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.', 'Судя по довольному урчанию, равазаврик удовлетворен количеством мяса, но невозможно предугадать, когда он снова проголодается.', NULL, NULL, NULL, 'Свежее мясо динозавра скормлено равазаврику', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13903, 'Обед из улья Гориши', 'Равазаврик испытующе смотрит на вас, после чего начинает что-то рисовать в грязи.$B$BСреди нарисованных знаков вы разбираете изображения различных больших насекомых – в основном, горишских силитидов. Малыш заканчивает рисунок, после чего указывает на него короткой лапой, чавкает и облизывается.$B$BОчевидно, он хочет, чтобы вы отправились в Скользкий овраг, что на юге кратера Ун\'Горо, и принесли ему мясо силитидов. Когда соберете мясо, угостите им своего равазаврика.', 'Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.', 'Ваш равазаврик дарит вам ослепительно клыкастую улыбку и сыто облизывается.', NULL, NULL, NULL, 'Мясо силитида скормлено равазаврику', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13904, 'Всмятку, в мешочек или сырые?', 'Равазаврик пытается привлечь ваше внимание, и вы слышите, как бурчит у него в животе. Он рисует в грязи несколько силитидов и добавляет внизу какие-то овалы, настойчиво указывая на них когтем.$B$BСомнений нет – ему нужны яйца силитидов! К счастью, вы знаете, где раздобыть лакомство для малыша – в Ядовитом улье, который находится в западном Танарисе, рядом с кратером Ун\'Горо.', 'Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.', 'Ваш равазаврик довольно облизывается, расправившись с яйцами силитида. Вам показалось – или он слегка разочарован тем, что еда уже кончилась?', NULL, NULL, NULL, 'Яйца силитида скормлены равазаврику', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13905, 'Перья опаляющего руха', 'Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и указывает когтем сначала на рисунок, а потом на свои локти и колени.$B$BОн, вроде бы, не голоден, что бы значили эти перья?$B$BНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.', 'Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.', 'Равазаврик берет у вас перья и начинает рассматривать их, примеряя к повязкам на коленях.', 'Ваш равазаврик выжидательно смотрит на вас.', NULL, NULL, 'Перо опаляющего руха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13906, 'Они так быстро растут', 'При хорошем уходе равазавры быстро растут. По мере взросления молочные зубы заменятся коренными. Если ты будешь собирать все выпавшие зубы, то сможешь легко определить, когда он достаточно окрепнет для того, чтобы его можно было тренировать как верховое животное.$B$BОн сам даст тебе знать о том, что ему нужно, так что внимательно следи за ним и тщательно ухаживай за своим малышом. А когда все его молочные зубы выпадут, возвращайся ко мне со своим равазавром и всем, что нужно для его седла.', 'Вернитесь к Мор\'веку на юго-восток Топей в Кратер Ун\'Горо со своим равазавриком, а также принесите 20 молочных зубов равазавра, 20 отрезов рунической ткани, 20 кусков грубой кожи и 80 золотых монет.', 'Похоже, вам удалось-таки провести все это время вместе, не убив друг друга. $B$BНу, хорошо, сейчас все и закончим. Я выучил твоего ящера отвечать на команды этого свистка. $B$BМало кто способен так самоотверженно растить равазаврика, кормить его из рук, но он стоит всех этих усилий.', 'Ты хорошо заботился о своем ящере?', NULL, NULL, 'Равазаврик (Прилагается)', 'Молочный зуб равазавра', 'Руническая ткань', 'Грубая кожа');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13908, 'Приготовьтесь к поездке', 'Твой равазавр окреп, возмужал и сильно к тебе привязался. Пожалуй, вскоре ты сможешь ездить на нем – как только я доделаю седло и уздечку. Правда, их тоже придется укрепить, чтобы они выдержали воздействие яда равазавра.$B$BПринеси мне немного грубой кожи, рунической ткани и денег на остальные ингредиенты – и я тут же примусь за работу.', 'Принесите 20 кусков грубой кожи, 20 отрезов рунической ткани и 80 золотых монет Мор\'веку. Он ждет вас на юго-востоке Топей в Кратере Ун\'Горо', '', NULL, NULL, NULL, 'Грубая кожа', 'Руническая ткань', 'Требуется денег: 80', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13914, 'Перья опаляющего руха', 'Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и показывает когтем сначала на рисунок, а потом на свои локти и колени.$B$BОн, вроде бы, не голоден, что бы значили эти перья?$B$BНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.', 'Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.', 'Равазаврик берет у вас перья и начинает рассматривать их, примеряя к своим лапам.', 'Ваш равазаврик выжидательно смотрит на вас.', NULL, NULL, 'Перо опаляющего руха', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13915, 'Бедный, голодный равазаврик', 'Равазаврик выжидательно смотрит на вас, после чего начинает опять что-то рисовать в грязи.$B$BКонечно, рисунки очень грубые, но вам все же удается разобрать очертания деметродонов, стегодонов и терродактилей. Когда ящер заканчивает рисунок, он ощеривает зубы и выразительно щелкает челюстью.$B$BНаверное, ваш равазаврик хочет свежего мяса. Убейте несколько любых деметродонов, стегодонов и терродактилей в кратере Ун\'Горо и накормите голодного малыша.', 'Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.', 'Судя по довольному урчанию, равазаврик удовлетворен количеством мяса, но невозможно предугадать, когда он снова проголодается.', 'Малыш облизывается и выжидательно смотрит на вас.', NULL, NULL, 'Свежее мясо динозавра скормлено равазаврику', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13916, 'Всмятку, в мешочек или сырые?', 'Равазаврик пытается привлечь ваше внимание, и вы слышите, как бурчит у него в животе. Он рисует в грязи несколько силитидов и добавляет внизу какие-то овалы, настойчиво указывая на них когтем.$B$BСомнений нет – ему нужны яйца силитидов! К счастью, вы знаете, где раздобыть лакомство для малыша – в Ядовитом улье, который находится в западном Танарисе, рядом с кратером Ун\'Горо.', 'Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.', 'Ваш равазаврик довольно облизывается, расправившись с яйцами силитида. Вам показалось – или он слегка разочарован тем, что еда уже кончилась?', 'Малыш смотрит на вас.', NULL, NULL, 'Яйца силитида скормлены равазаврику', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13917, 'Обед из улья Гориши', 'Равазаврик испытующе смотрит на вас, после чего начинает что-то рисовать в грязи.$B$BСреди нарисованных знаков вы разбираете изображения различных больших насекомых – в основном, горишских силитидов. Малыш заканчивает рисунок, после чего указывает на него короткой лапой, чавкает и облизывается.$B$BОчевидно, он хочет, чтобы вы отправились в Скользкий овраг, что на юге кратера Ун\'Горо, и принесли ему мясо силитидов. Когда соберете мясо, угостите им своего равазаврика.', 'Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.', 'Ваш равазаврик дарит вам ослепительно клыкастую улыбку и сыто облизывается.', 'Малыш выжидательно смотрит на вас.', NULL, NULL, 'Мясо силитида скормлено равазаврику', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13926, 'Ру, оракул-сиротка', 'Дети будут очень рады такому другу, как вы, $N. Как замечательно, что вы станете опекать одного из них!$B$BВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.$B$BПозовите сиротку, $N! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.', 'Поговорите с попечительницей сирот Арией; после этого воспользуйтесь детской свистулькой оракула, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.', '', NULL, NULL, NULL, 'Поговорите с попечительницей сирот Арией', 'Детская свистулька оракула', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13927, 'Кекек, волчер-сиротка', 'Дети будут очень рады такому другу, как вы, $N. Как замечательно, что вы станете опекать одного из них!$B$BВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.$B$BПозовите сиротку, $N! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.', 'Поговорите с попечительницей сирот Арией, после этого воспользуйтесь детской свистулькой волчера, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.', '', NULL, NULL, NULL, 'Поговорите с попечительницей сирот Арией', 'Детская свистулька волчера', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13929, 'Самое большое дерево!', 'Мы помним, что еще перед большой войной Су-сэй рассказывал нам о большом-пребольшом дереве!$B$BСу-сэй, кажется, называл его Седой Пастью, и оно в центре Серых холмов. Нет, неправильно, он говорил иначе! Мы вспомнили! Большое дерево растет прямо посреди Седых холмов! Такое не пропустишь!$B$BТы отведешь нас туда, да? И мы заберемся прямо внутрь? Су-сэй говорил, там живут большие люди-медведи. Может нам удастся их увидеть.', 'Отведите вашего подопечного Ру к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Ру посетил Седую Пасть', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13930, 'Дом людей-медведей', 'Верховный шаман Ракжак всегда рассказывал истории о великих воинах прошлого. Как-то он поведал об огромных людях-медведях, которые сражались за великий город-дерево.$B$BКекек хочет посмотреть на то дерево и место битвы! Верховный шаман Ракжак сказал Кекеку, что город-дерево называется Седая Пасть и находится в самом центре Седых холмов.$B$BКекек никогда раньше не видел городов до того, как встретился с попечительницей сирот, но в этом городе нет воинов – только мужчины в фиолетовых одеждах. Кекек хочет увидеть настоящих героев, которые сражаются за свой город!', 'Отведите вашего подопечного Кекека к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Кекек посетил Седую Пасть', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13931, 'Новый подарок к новому году', 'Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.$B$BПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.', 'Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.', 'Что это? Купон на кружку? Любишь выпить? Отлично! Я дам тебе кружку, а ты пойди и выпей за мое здоровье! А потом еще немного выпей... А потом возвращайся сюда.$B$BВсе пути ведут ко мне, знаешь ли. Тебе придется отоваривать праздничные б$Nы, штампы защитника бочек и так далее.$B$BКороче, вот кружка. Приходи, еще поболтаем.', 'Что такое, красавчик? Ты ко мне по делу?', NULL, NULL, 'Купон на получение кружки Хмельного фестиваля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13932, 'Новый подарок к новому году', 'Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.$B$BВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.', 'Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.', 'Аххх, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$B$BЧао, увидимся. Ты ведь захочешь отоварить и другие праздничные купоны... Помни, я вся твоя...$B$BИли его... $B$BМожет, его...', 'Что такое, красавчик? Ты ко мне по делу?', NULL, NULL, 'Купон на получение кружки Хмельного фестиваля (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13933, 'Святилище бронзовых драконов', 'Иногда верховный оракул Су-сэй рассказывает истории о великой святыне драконов – не такой, конечно, как Великий камень дождя, а совсем другой. Су-сэй говорит, что мы можем увидеть в ней себя – точнее, какими мы будем через много лет.$B$BОтведешь нас туда? Мы помним, что это святилище бронзовых драконов, которое находится в Драконьем Погосте. Су-сэй говорит, что Великий камень дождя показал ему святилище на северо-востоке от Храма Драконьего Покоя или на северо-западе от места, которое сухокожие зовут Крепостью Стражей Зимы. Идем?', 'Отведите вашего подопечного Ру к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Ру посетил Бронзовое святилище драконов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13934, 'Святилище бронзовых драконов', 'Когда Кекек был щенком, он слышал, как старейшины рассказывали об одном далеком святилище. Они говорили, что род бронзовых драконов, который его оберегает, может видеть будущее.$B$BКекек станет великим воином! Пойдем, посмотрим каким вырастет Кекек. Святилище бронзовых драконов находится где-то на Драконьем Погосте, на северо-восток от храма Драконьего Покоя и на северо-запад от Крепости Стражей Зимы.$B$BПойдем, увидим будущее. Плохо, что попечительница ругает Кекека. Кекек воин, а не забияка.', 'Отведите вашего подопечного Кекека к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Кекек посетил Бронзовое святилище драконов', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13937, 'Поездка в \"Чудо чудное\".', 'А у нас есть еще минутка? Мы слышали, что в Даларане есть магазин игрушек, но никогда там не были. Госпожа попечительница говорит, что сирот слишком много, и мы будем мешать покупателям. Может быть, мы могли бы заглянуть туда вдвоем?$B$BА еще мы всегда хотели бумажный дирижаблик. Как ты думаешь, они продаются в \"Чуде чудном\"? Это наша мечта... Может быть, ты подаришь нам его?', 'Купите бумажный дирижаблик в магазине \"Чудо чудное\" и бросьте его вашему подопечному Ру.', '', NULL, NULL, NULL, 'Бросьте бумажный дирижаблик Ру', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13938, 'Заглянем в \"Чудо чудное\".', 'Может Кекек тебя еще кое о чем попросить? Попечительница рассказывала, что в Даларане есть магазин игрушек \"Чудо чудное\", но Кекека туда не пускают. Говорят, если Кекек туда пойдет, придется отвести и всех остальных сирот. Но Кекек очень хочет попасть в магазин!$B$BКекек видел, как другие дети играют с бумажными дирижабликами. Говорят, их продают в \"Чуде чудном\". Ты запустишь такой дирижаблик, чтобы он летал вокруг Кекека?', 'Купите бумажный дирижаблик в магазине \"Чудо чудное\" и отдайте его вашему подопечному Кекеку.', '', NULL, NULL, NULL, 'Бросьте бумажный дирижаблик Кекеку', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13950, 'Друзья детства!', 'Знаешь, в сиротском приюте так одиноко... Иногда нам хочется увидеть другие края, встретить новых друзей.$B$BМожет быть, ты отведешь нас туда, где живут другие детеныши? Мы слышали про такое место – Приют Зимних Плавников, которое находится в огромной Борейской тундре. Мы думаем, оно может находиться на границе с островом Хладарра.$B$BГоспожа попечительница говорит, что кто-то смелый спас выводок детенышей в этом месте. Наверное, им теперь тоже одиноко, и им нужны друзья. Ты отведешь нас туда?', 'Отведите вашего подопечного Ру к Приюту Зимних Плавников. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Ру посетил Приют Зимних Плавников', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13951, 'Друзья детства!', 'Кекеку грустно – в приюте слишком мало других щенят. Может быть, ты сводишь Кекека в гости?$B$BКекек знает племя, которое живет на Поляне Снегопада в Драконьем Погосте. Ты знаешь, где это? На севере от города людей-моржей в Гавани Моа\'ки и южнее Рубинового святилища драконов.$B$B<Кекек презрительно морщится при упоминании клыкарров.>$B$BОтведи туда Кекека. Может быть, Кекек встретит других волчеров и покажет им силу Бешеного Сердца!', 'Отведите вашего подопечного Кекека на Поляну Снегопада. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Кекек посетил Поляну Снегопада', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13952, 'Благодарный покойник', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестаралась... и съела все, что они приготовили для меня! Даже крошки подмела!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я была бы очень благодарна!$B$BКажется, рецепт можно купить у Чепмана.', 'Принесите поминальный хлеб веселому духу человека на кладбище Штормграда.Чтобы увидеть дух, используйте оранжевые бархатцы.', '', NULL, NULL, NULL, 'Поминальный хлеб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13954, 'Королева драконов', 'Верховный оракул Су-сэй говорил, что Великие создали всех драконов, и даже их королеву. Мы хотим ее увидеть! Ты отведешь нас на вершину Храма Драконьего Покоя? Мы помним, что Су-сэй рассказывал про храм – он в самом центре Драконьего Погоста.$B$BМы очень-очень хотим увидеть королеву драконов! Наверное, она очень большая и красивая. Может быть, она поможет нам найти новых родителей.$B$BПойдем?', 'Отведите вашего подопечного Ру познакомиться с Алекстразой Связующей Жизнь, которая обитает на вершине храма Драконьего Покоя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Ру познакомился с Алекстразой Хранительницей Жизни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13955, 'Королева драконов', 'Кекеку всегда нравились драконы. Кекек даже хотел превратиться в дракона, но госпожа попечительница не разрешила. Но она сказала, что ты можешь отвести Кекека познакомиться с королевой драконов.$B$BКекек думает, что госпожа попечительница наконец-то предложила что-то хорошее. Ты отведешь Кекека в Храм Драконьего Покоя, в центре Драконьего Погоста? Давай встретимся с королевой драконов! Наверное, она очень большая, раз живет на самой вершине! Кекеку не терпится познакомиться с ней!', 'Отведите вашего подопечного Кекека познакомиться с Алекстразой Хранительницей Жизни, на вершину храма Драконьего Покоя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Кекек познакомился с Алекстразой Хранительницей Жизни', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13956, 'Встреча с Великим', 'Верховный оракул Су-сэй всегда рассказывал нам про то, какие святилища строили Великие, и как мы дарили им блестяшки, но он сам никогда не видел Великих. Никто их не видел – но, может, ты знаешь, где их искать?$B$BСу-сэй говорит, что Великие построили врата и поставили их в центре южной части Шолазара. Су-сэй не знает, куда они ведут, но может быть, там мы найдем Великих! Отведи нас к вратам, $N, мы должны это выяснить!', 'Отведите вашего подопечного Ру к Этимидиану на Террасу Создателя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Ру посетил Этимидиана', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13957, 'Великий Хеминг Эрнестуэй', 'Знаешь, с кем Кекек всегда мечтал познакомиться? С Хемингом Эрнестуэем, про которого рассказывал Старейшина Харкек. Говорят, он странствует по Шолазару и охотится на огромных зверей! Даже старейшины племени Бешеного Сердца почитают Хеминга Эрнестуэя как великого охотника.$B$BСтарейшина Харкек сказал Кекеку, что Лагерь Эрнестуэя находится в центре западной части Шолазара, на берегу реки, которая называется Разлом Морского Потока. Своди Кекека туда, чтобы он спросил у Хеминга, как стать таким великим охотником!', 'Отведите вашего подопечного Кекека познакомиться с Хемингом Эрнестуэем в Лагерь Эрнестуэя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.', '', NULL, NULL, NULL, 'Кекек познакомился с Хемингом Эрнестуэем', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13959, 'Назад в приют', 'Нам было весело с тобой, $N. Жаль, что ты не можешь стать $gнашим папочкой:нашей мамочкой:, и нам пора возвращаться к попечительнице сирот Арии в Даларан.$B$BМожет быть, ты еще навестишь нас как-нибудь? Нам очень понравилось общаться с малышами Зимних Плавников и с королевой драконов. И никто нам не поверит, что мы видели одного из Великих!$B$BМы будем скучать по тебе, $N. Обещаем, мы будем тебе писать!', 'Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку оракула попечительнице сирот Арии.', '', NULL, NULL, NULL, 'Детская свистулька оракула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13960, 'Назад в приют', 'Знаешь, а мы не так уж и плохо провели время вместе, $N. Ты $gпоказал:показала: Кекеку много всяких интересных мест. Кекек нашел новых друзей и сделал много всего такого, что не снилось другим щенкам.$B$BТеперь мы друзья – Кекек, ты, Хеминг Эрнестуэй и щенки Поляны Снегопада. Может быть, ты когда-нибудь принесешь Кекеку книгу про зеленые холмы? А Кекек обещает написать тебе как-нибудь и рассказать, как идут дела. Может быть, Кекек даже не будет больше дразнить длинноязыких детей.$B$BА теперь Кекеку пора возвращаться к попечительнице Арии, в фиолетовый город людей.', 'Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку волчера попечительнице сирот Арии.', '', NULL, NULL, NULL, 'Детская свистулька волчера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13966, 'Подарок Зимнего Покрова', '', 'На маленьком ярлычке написано:С правздниками, $N!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (13986, 'Раненый товарищ', 'Думаю, ты знаешь, какие жаркие бои ведутся в этих краях, $C. Нам пока удается удержать позиции, но не всегда удается избежать потерь.$B$BОдин из наших воинов, Апони Светлая Грива, была ранена в руку в одном из сражений. Ее тут же отправили назад в Громовой Утес для лечения, и она была так расстроена этим решением, что забыла здесь свой щит. Не затруднит ли тебя передать его ей вместе с нашими наилучшими пожеланиями? Мы все соскучились по ее улыбке.$B$BТы найдешь ее на Вершине Старейшин.', 'Отнесите побитый фамильный щит Апони Светлой Гриве на Вершину Старейшин Громового Утеса.', 'Ах, это же мой щит! Жаль, что я еще не скоро смогу взять его в руки. Но все равно, спасибо тебе. Ты не представляешь, как мне тяжело сидеть здесь, вдали от поля боя, но с раненной рукой в бою от меня будет мало толку.$B$BТы уж береги себя, слышишь?', 'Привет! По-моему, мы не знакомы. Могу я чем-нибудь помочь тебе?', NULL, NULL, 'Побитый родовой щит (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14016, 'Проклятие Черного рыцаря', 'После твоей победы я было распорядилась убрать останки Черного рыцаря с Ристалища, но исповедница Пейлтресс настояла на том, чтобы похоронить его по всем правилам. И с тех пор на нашем кладбище происходят странные вещи, которые отпугивают жителей, желающих воздать почести павшим героям.$B$BТы не $gмог:могла: бы лично посетить кладбище и выяснить, что там творится? Оно находится на восточном краю Ристалища.', 'Рыцарь Райдалла из Серебряного павильона на Ристалище Серебряного Турнира просит вас осмотреть могилу Черного рыцаря.', '<Рыцарь Райдалла хмурится.>$B$BДумаешь, это было запланировано? Пожалуй, это не имеет значения, но мне кажется, что нас обвели вокруг пальца. Мы должны вмешаться!', NULL, NULL, NULL, 'Осмотреть могилу Черного рыцаря.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14017, 'Судьба Черного рыцаря', 'Говоришь, его тело забрали служители культа Проклятых? Я знаю только одно место, куда они могли бы его отнести: это Застава Вестника Смерти, что на западе от Ристалища.$B$BМы должны остановить их во что бы то ни стало. Это только подтверждает правдивость мрачных слухов... Среди них совершает свои темные обряды бесславный доктор Колер. Найди алтарь, возвышающийся над лагерем служителей культа, убей доктора и принеси мне доказательства его грязных деяний. Любой ценой замедли их работу!', 'Перехватите приказы доктора Колера на Заставе Вестника Смерти, а затем вернитесь к рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного Турнира.', 'У доктора не было времени закончить свою работу, но последователи довершат начатое. Судя по твоему отчету, слуги Короля-лича воскресили Черного рыцаря и наделили его новой силой. К несчастью, мы не можем предсказать, что задумал его зловещий повелитель, но ты помог пролить свет на этот заговор. Я сообщу о твоих находках Верховному крестоносцу Аделарду, и мы вместе предупредим участников турнира о надвигающейся опасности.', 'Тебе удалось выяснить, что они делают с останками Черного рыцаря?', NULL, NULL, 'Приказы доктора Колера', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14022, 'Пиршество странников', 'А ты не хочешь присоединиться к Пиршеству странников, $N? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.$B$BТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. $B$BА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Грегори Табора – он стоит рядом с вратами Штормграда.', 'Поговорите с Грегори Табором – он стоит рядом с вратами Штормграда.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14023, 'Пряная хлебная запеканка', 'Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт недаром включен в пиршественную поваренную книгу как самое популярное блюдо Штормграда.$B$BЕсли ты умеешь готовить, навести торговцев Пиршества странников и купи пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!$B$BКак только приготовишь хлебную запеканку, принеси ее Джасперу Муру, он стоит возле праздничных столов.', 'Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.', '', NULL, NULL, NULL, 'Приготовлено пряной хлебной запеканки', 'Пряная хлебная запеканка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14024, 'Тыквенный пирог', 'Ах, как ароматно пахнет приготовленная тобой пряная хлебная запеканка! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в Штормграде, поскольку готовится из спелых элвиннских тыкв, которые растут только в этих краях.$B$BЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.$B$BКстати, тебя не затруднит испечь несколько кусочков и отнести их Эдварду Уинслоу? Он накрывает столы рядом со Стальгорном, и тыквенный пирог наверняка у него уже кончился.', 'Испеките 5 кусков тыквенного пирога и принесите их Эдварду Уинслоу, который стоит возле праздничных столов Стальгорна.', '', NULL, NULL, NULL, 'Приготовлено тыквенного пирога', 'Тыквенный пирог', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14028, 'Клюквенный соус', 'Если ты еще не $gпробовал:пробовала: клюквенный соус – ты не знаешь вкус жизни. Он делается из свежайшей клюквы, которая растет в Болотине. Если хочешь попробовать его приготовить – купи все, что тебе надо, у продавца Пиршества странников.$B$BА рецепт должен быть в твоей пиршественной повареной книге.$B$BЕсли у тебя есть свободная минутка – может быть, ты поможешь Джасперу Муру приготовить очередную порцию соуса для штормградского стола? Я как раз собирался обменять пару порций на испеченный тобой пирог.', 'Приготовьте 5 порций клюквенного соуса и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.', '', NULL, NULL, NULL, 'Приготовлено клюквенного соуса', 'Клюквенный соус', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14030, 'Голодающие Дарнаса', 'Спасибо за клюквенный соус! Нам еще так много надо приготовить – я просто не успеваю за всем следить. Но самое главное – я должен заботиться о том, чтобы Исаак Аллертон из Дарнаса не испытывал недостатка в провизии, а у него как раз кончились все угощения. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты $gприготовил:приготовила: несколько порций хлебной запеканки и тыквенного пирога. Все нужные ингредиенты есть у продавца.$B$BОтнеси готовую еду к праздничным столам, которые накрыты рядом со входом в Дарнас, прямо под Террасой Воинов.', 'Приготовьте 5 порций хлебной запеканки и отнесите ее Исааку Аллертону, который стоит у входа в Дарнас.', '', NULL, NULL, NULL, 'Пряная хлебная запеканка', 'Тыквенный пирог', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14032, 'Нападение на лагерь кобольдов', 'Первое твое задание, $N, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.', 'Уничтожьте 8 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.', '', NULL, NULL, NULL, 'Кобольд-вредитель убито', 'Мурлок-добытчик убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14033, 'Засахаренный батат', 'Раз уж ты здесь, помоги нам пополнить запасы тельдрассильской сладкой картошки – она идет на изготовление самого вкусного засахаренного батата, который ты когда-либо $gпробовал:пробовала:.$B$BЕсли не веришь – приготовь $gсам:сама:, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Грегори Табором, который накрывает столы возле Штормграда. Он их просто обожает, хотя его послушать – так можно подумать, у него каждое блюдо самое любимое.', 'Приготовьте 5 порций засахаренного батата и отнесите их Грегори Табору, который стоит у ворот Штормграда.', '', NULL, NULL, NULL, 'Приготовлено засахаренных бататов', 'Засахаренный батат', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14035, 'Запеченная индейка', 'Какой же праздник Пиршества странников без главного украшения – и я вовсе не имею в виду бутафорский рог изобилия. Я говорю про огро$Nю жареную индейку, царицу праздничного стола!$B$BПо-моему, в твоей пиршественной поваренной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Элвиннском лесу, так что тебе не составит труда отыскать добычу.$B$BКак только закончишь готовить, принеси жареных индеек Исааку Аллертону к вратам Дарнаса, хорошо?', 'Приготовьте 5 запеченных индеек и отнесите их Исааку Аллертону к вратам Дарнаса.', '', NULL, NULL, NULL, 'Приготовлено запеченных индеек', 'Запеченная индейка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14036, 'Пиршество странников', 'Ты $gпришел:пришла: сюда, чтобы отпраздновать с нами Пиршество странников? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.$B$BТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. $B$BА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Майлса Стендиша во внутреннем дворе Подгорода.', 'Поговорите с Майлсом Стендишом во внутреннем дворе Подгорода.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14037, 'Пряная хлебная запеканка', 'Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт был придуман еще во времена расцвета Лордерона, и дошел до наших дней без изменений.$B$BЕсли ты умеешь готовить, навести торговцев Пиршества странников и приобрети пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!$B$BКак только приготовишь хлебную запеканку, принеси ее Вилльяму Маллинсу, который стоит возле праздничных столов.', 'Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Вилльяму Маллинсу, который стоит возле праздничных столов во внутреннем дворе Подгорода.', 'Как же трудно следить за тем, чтобы на столах всегда была еда. Подумать только – столько хлопот, хотя в нашем состоянии пища больше не нужна. $B$B<Уильям пожимает плечами.>$B$BОднако традицию нельзя нарушать.', 'На столах явно недостает пряной хлебной запеканки.', NULL, NULL, 'Приготовлено пряной хлебной запеканки', 'Пряная хлебная запеканка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14040, 'Тыквенный пирог', 'Ты $gприготовил:приготовила: отличную хлебную запеканку! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в наших краях, поскольку готовится из спелых тирисфальских тыкв, которые растут только в этих краях.$B$BЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.$B$BКстати, тебя не затруднит испечь несколько кусочков и отнести их Фрэнсису Итону? Он накрывает столы рядом со Оргриммаром, и наверняка у него уже кончился тыквенный пирог.', 'Испеките 5 кусков тыквенного пирога и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.', 'Этот пирог съедают быстрее всего – можно подумать, гости забывают про основные блюда и приступают сразу к десерту. Ты сам уже попробовал пирог?', 'Тыквенному пирогу мы всегда рады.', NULL, NULL, 'Приготовлено тыквенного пирога', 'Тыквенный пирог', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14041, 'Клюквенный соус', 'Ты уже $gпробовал:пробовала: клюквенный соус? Он делается из свежайшей клюквы с берегов реки Строптивой. Если хочешь его приготовить – купи все необходимое у торговца Пиршества странников.$B$BА рецепт записан в твоей пиршественной повареной книге.$B$BЕсли у тебя есть свободная минутка – может быть, ты поможешь Докину Дальнему Лугу приготовить немного соуса? Он стоит у подъемника на западе Громового Утеса.', 'Приготовьте пять порций клюквенного соуса и принесите их Докину Дальнему Лугу, который ждет у подъемника на западе Громового Утеса.', 'Новая порция клюквенного соуса? Отлично, он так быстро кончается!', 'Как идет празднование Пиршества странников?', NULL, NULL, 'Приготовлено клюквенного соуса', 'Клюквенный соус', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14043, 'Засахаренный батат', 'Раз уж ты здесь, помоги нам пополнить запасы мулгорской сладкой картошки – она идет на изготовление самого вкусного засахаренного батата, который ты когда-либо $gпробовал:пробовала:.$B$BЕсли не веришь – приготовь $gсам:сама:, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Фрэнсисом Итоном, который накрывает столы возле Оргриммара. Боюсь, у него опять кончились все запасы угощений, несмотря на все мои усилия.', 'Приготовьте 5 порций засахаренного батата и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.', 'А, Докин поручил тебе приготовить засахаренный батат?$B$B<Френсис улыбается.>$B$BОтлично, иначе он не справился бы. Спасибо за помощь!', 'А, привет еще раз, $N.', NULL, NULL, 'Приготовлено засахаренных бататов', 'Засахаренный батат', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14044, 'Нехватка продовольствия в Подгороде', 'Спасибо за то, что $gпринес:принесла: нам засахаренный батат! Нам еще так много надо приготовить – я просто не успеваю за всем следить. А тут еще Майлс жалуется на то, что у него практически кончился клюквенный соус и запеканка. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты $gприготовил:приготовила: несколько порций угощения. Все нужные ингредиенты есть у продавца.$B$BОтнеси готовую еду Майлсу к праздничным столам, которые накрыты в руинах над Подгородом.', 'Приготовьте 5 порций пряной хлебной запеканки и 5 порций клюквенного соуса, и отнесите их Майлсу Стендишу к входу в Подгород.', 'Спасибо за доставку – я уже начал волноваться. Плохо, когда на столах одни объедки.', 'Рад снова видеть тебя, $N.', NULL, NULL, 'Пряная хлебная запеканка', 'Клюквенный соус', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14047, 'Запеченная индейка', 'Какой же праздник Пиршества странников без главного украшения – огромной жареной индейки, царицы праздничного стола!$B$BПо-моему, в твоей пиршественной повареной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Тирисфальских лесах, так что тебе не составит труда отыскать добычу.$B$BКак только закончишь готовить, принеси жареных индеек Фрэнсису Итону к вратам Оргриммара, хорошо?', 'Приготовьте 5 запеченных индеек и принесите их Фрэнсису Итону к вратам Оргриммара.', 'Превосходно! Спасибо тебе, $N. Теперь тебе не составит труда накрыть свой собственный стол на праздник Пиршества странников.', 'Что привело тебя в Оргриммар, $N?', NULL, NULL, 'Приготовлено запеченных индеек', 'Запеченная индейка', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14048, 'Слишком мало индеек', 'С самого начала праздника я не отхожу от плиты, но угощений надо гораздо больше, чем я могу приготовить одна. Может быть, мне удастся уговорить тебя помочь?$B$BХорошую дикую индейку тут найти очень сложно, может ты сумеешь принести мне несколько порций? Ты можешь купить несколько порций уже готового блюда или приготовить $gсам:сама:. Если ты решишь их готовить, то могу посоветовать охотиться на птиц в Элвиннском лесу. Все остальные ингредиенты можно купить у любого торговца Пиршества странников.', 'Принесите 20 запеченных индеек Кэтрин Железный Чан к вратам Стальгорна.', '', NULL, NULL, NULL, 'Запеченная индейка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14051, 'Не забыть про запеканку!', 'Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!$B$BИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее $gсам:сама: – все ингредиенты можно купить прямо здесь.', 'Принесите 20 порций пряной хлебной запеканки Кэтрин Железный Чан к праздничным столам у ворот Стальгорна.', '', NULL, NULL, NULL, 'Пряная хлебная запеканка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14053, 'У нас опять кончился соус?', 'Мой супруг, Джаспер, собирался приготовить клюквенный соус, но потом оказалось, что на столах слишком мало засахаренного батата. Похоже, ему не справиться без посторонней помощи. Если ты умеешь готовить, можешь купить клюкву у продавца Пиршества странников – он стоит рядом с вратами в Стальгорн.$B$BА если тебе не хочется браться за половник – ты всегда можешь попросить кого-нибудь приготовить соус для тебя.', 'Принесите 20 порций клюквенного соуса Эллен Мур к праздничным столам возле Штормграда.', '', NULL, NULL, NULL, 'Клюквенный соус', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14054, 'Проще пареной тыквы', 'Исаак трудится не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из любимых блюд Исаака – тыквенный пирог – уже практически закончилось.$B$BТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых элвиннских тыкв у праздничного торговца возле Штормграда.', 'Принесите 20 кусков тыквенного пирога Мэри Аллертон к праздничным столам возле Дарнаса.', '', NULL, NULL, NULL, 'Тыквенный пирог', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14055, 'Батат – значит, батат!', 'Моя жена Эллен попросила меня проследить за тем, чтобы столы не пустовали, а сама никак не может определиться, что же ей приготовить. Сначала она поручила мне испечь тыквенный пирог, а потом передумала и решила делать засахаренный батат.$B$BА у меня уже тесто для пирога поднялось! Послушай, может быть, ты займешься этой сладкой картошкой? Представлешь, как она обрадуется, если мы приготовим все, что ей хотелось?$B$BКстати, все необходимые ингредиенты можно приобрести у праздничного торговца в Дарнасе. Удачи, $N.', 'Принесите 20 порций засахаренного батата Джасперу Муру к праздничным столам возле Штормграда.', '', NULL, NULL, NULL, 'Засахаренный батат', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14058, 'Батат – значит, батат!', 'Роберта Картер попросила меня помочь ей и приготовить одно из ее любимых блюд – засахаренный батат. Я бы рад помочь, но уже пообещал хозяйке накрыть на стол.$B$BМоя благодарность не будет иметь границ, если ты поможешь мне с этим. Роберта никогда не простит мне, если я ее подведу.$B$BКстати, если ты собираешься самостоятельно приготовить это блюдо, могу порекомендовать купить все необходимое у праздничного торговца в Громовом Утесе. Заранее спасибо, $N.', 'Принесите 20 порций засахаренного батата Вилльяму Маллинсу к праздничным столам над Подгородом.', 'Спасибо, $N. Теперь я смогу помочь хозяйке и не подведу при этом Роберту.', 'Засахаренный батат уже готов?', NULL, NULL, 'Засахаренный батат', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14059, 'У нас опять кончился соус?', 'Не понимаю, куда девается весь клюквенный соус – можно подумать, его поганищам скармливают, стоит мне только отвернуться. Поможешь мне приготовить еще? Если ты умеешь готовить, можешь купить сочную мулгорскую клюкву у праздничного торговца, который стоит возле Оргриммара.$B$BА если тебе лень возиться с ягодами – просто попроси кого-нибудь приготовить соус.', 'Принесите 20 порций клюквенного соуса Роберте Картер, которая стоит возле праздничных столов во внутреннем дворе Подгорода.', 'Спасибо за помощь, $N. Кстати, если узнаешь, куда девается клюквенный соус – дай мне знать.', 'Ты уже несешь клюквенный соус?', NULL, NULL, 'Клюквенный соус', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14060, 'Проще пареной тыквы', 'Докин и Лаха трудятся не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из наших любимых блюд – тыквенный пирог – уже практически закончилось.$B$BТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых тирисфальских тыкв у торговца Пиршества странников возле Подгорода.', 'Принесите 20 кусков тыквенного пирога Мархаре Голдвит к праздничным столам возле Громового Утеса.', 'Отличные пироги! Спасибо за помощь, $N.', 'Как там пироги, уже готовы?', NULL, NULL, 'Тыквенный пирог', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14061, 'Слишком мало индеек', 'С самого начала праздника я не отхожу от плиты, но угощений надо гораздо больше, чем я могу приготовить одна. Может быть, мне удастся уговорить тебя помочь?$B$BХорошую дикую индейку достать тут очень сложно – разве что ты сумеешь принесешь мне несколько порций. Если решишь лично их приготовить, то могу посоветовать охотиться на птиц в Тирисфальских лесах. Все остальные ингредиенты можно купить у любого торговца Пиршества странников.', 'Принесите 20 запеченных индеек Ондани Большой Мельнице к вратам Оргриммара.', 'Чудесные индейки! Они станут прекрасным украшением праздничного стола. Спасибо за то, что выручил меня.', 'Как идет охота на индеек?', NULL, NULL, 'Запеченная индейка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14062, 'Не забыть про запеканку!', 'Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!$B$BИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее $gсам:сама: – все ингредиенты можно купить прямо здесь.', 'Принесите 20 порций пряной хлебной запеканки Ондани Большой Мельнице к вратам Оргриммара.', 'Ты как раз вовремя! Самое время накрывать на стол и мне не хватает хлебной запеканки.', 'Тебе удалось достать запеканку?', NULL, NULL, 'Пряная хлебная запеканка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14064, 'Богатый пир', 'Если ты еще не $gпробовал:пробовала: блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!$B$BПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.$B$BКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.', 'Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.', '', NULL, NULL, NULL, 'Дух пиршества', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14065, 'Богатый пир', 'Если ты еще не $gпробовал:пробовала: блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!$B$BПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.$B$BКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.', 'Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.', 'Ах, какой пир!$B$BСпасибо, что присоединился к празднованию Пиршества странников!', NULL, NULL, NULL, 'Дух пиршества', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14074, 'Лапами кверху', 'Серебряный Авангард отправил сюда крейсерский корабль, перевозивший мясо долгоногов и прочие припасы для Ристалища, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.$B$BОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может кончиться провизия.', 'Верните 10 украденных окорочков долгонога Нараси Снежной Заре из Павильона Серебряного союза на Ристалище Серебряного турнира.', 'Мда, выглядят они... не очень, но есть можно. Крестоносцы будут рады узнать, что нам удалось спасти хоть какие-то припасы с корабля.', 'Тебе удалось найти украденные припасы?', NULL, NULL, 'Украденный окорочок долгонога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14076, 'Завтрак для чемпионов', 'Теперь, когда постройка Колизея закончена, Серебряный Авангард дал нам новое поручение – позаботиться о животных, с которыми предстоит сражаться чемпионам.$B$BУ этих гигантских йормунгаров странные вкусовые предпочтения – похоже, они питаются яйцами себе подобных. Самыми питательными считаются яйца глубинных йормунгаров.$B$BВот, отнеси этот барабан к Подножию в Грозовой Гряде и ударь в него рядом со снежными курганами. Звук пробудит глубинных йормунгаров, и ты сможешь одолеть их, чтобы завладеть яйцами.', 'Найдите 4 яйца йормунгаров и принесите их Савинии Певице Преданий на ристалище Серебряного турнира.', 'Отличная работа, $N. Я отнесу их в хранилище Серебряного Авангарда, и им останется только признать, что мы вносим гораздо больший вклад в общее дело, чем эти никчемные Похитители Солнца!', 'Тебе удалось добыть яйца йормунгаров? По-моему, эти червяки скоро примутся пожирать своих надсмотрщиков.', NULL, NULL, 'Яйца йормунгаров', 'Землетрясущий барабан', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14077, 'Милосердие Света', 'Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.$B$BУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.', 'Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.', '<Нараси забирает у вас молитвенник.>$B$BСпасибо. Этот молитвенник подарила мне сама Исповедница Пейлтресс. Она будет рада узнать, что он послужил благому делу.', 'Ты позаботился о душах убитых туаликов?', NULL, NULL, 'Проведено последних ритуалов', 'Молитвенник исповедницы (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14079, 'Уроки верховой езды в Элвиннском лесу', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Рандала Охотника.$B$BЕго можно найти на лесопилке Восточной долины, в Элвиннском лесу, вдоль дороги, ведущей из Штормграда.', 'Верните это рекламное сообщение Рандалу Охотнику на лесопилку Восточной долины в Элвиннском лесу.', 'Итак, начнем тренировку?', 'А, ты получила мое письмо? Отлично.', NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14080, 'Остановить нападение', 'Квалдиры, морские твари, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.$B$BАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.', 'Нараси Снежная Заря из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас убить 10 квалдиров.', 'Твои действия подтвердили, что мы сражаемся плечом к плечу с Серебряным Авангардом, в то время как Похитители Солнца прохлаждаются в тени.', NULL, NULL, NULL, 'Убито квалдиров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14081, 'Уроки верховой езды в Лесах Вечной Песни', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Пераскамина.$B$BЕго можно найти в Стойлах Турона, к юго-востоку от Врат Пастыря, ведущих из Луносвета.', 'Верните это рекламное сообщение Пераскамину в стойла Турона в Луносвете.', 'Итак, начнем тренировку?', 'А, ты получил мое письмо? Отлично.', NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14082, 'Уроки верховой езды в Экзодаре', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Аалун.$B$BЕе можно найти в Экзодаре на Острове Лазурной Дымки', 'Верните это рекламное сообщение Аалун, которая находится неподалеку от Экзодара на острове Лазурной Дымки.', 'Итак, начнем тренировку?', 'А, ты получила мое письмо? Отлично.', NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14083, 'Уроки верховой езды в Дун Мороге', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Ультама Громовой Рог.$B$BЕго можно найти на Ферме Янтарленов, которая расположена вдоль дороги, ведущей на восток от Стальгорна.', 'Верните это рекламное сообщение Ультаму Громовому Рогу на ферму Янтарленов в Дун Мороге.', 'Итак, начнем тренировку?', 'А, ты получил мое письмо? Отлично.', NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14084, 'Уроки верховой езды в Дун Мороге', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Бинджи Перосвиста.$B$BЕго можно найти в Поселке Сталежара к северо-востоку от Караноса в Дун Мороге.', 'Верните это рекламное сообщение Бинджи Перосвисту в поселок Сталежара в Дун Мороге.', 'Итак, начнем тренировку?', 'А, ты получила мое письмо? Отлично.', NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14085, 'Уроки верховой езды в Дарнасе', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Джартсама.$B$BЕго можно найти в Анклаве Кенария, в Дарнасе.', 'Верните это рекламное сообщение Джартсаму в анклав Кенария в Дарнасе.', 'Итак, начнем тренировку?', 'А, ты получила мое письмо? Отлично.', NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14086, 'Уроки верховой езды в Оргриммаре', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Кильдара.$B$BЕго можно найти в Аллее Чести Оргриммара.', 'Верните это рекламное сообщение Кильдару в Аллею Чести в Оргриммаре.', 'Итак, начнем тренировку?', 'А, ты получил мое письмо? Отлично.', NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14087, 'Уроки верховой езды в Мулгоре', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Кара Певца Бури.$B$BЕго можно найти в Мулгоре, в Деревне Кровавого Копыта.', 'Верните это рекламное сообщение Кару Певцу Бури в деревню Кровавого Копыта в Мулгоре.', '', NULL, NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14088, 'Уроки верховой езды в Дуротаре', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Ксар\'Ти.$B$BЕго можно найти в Деревне Сен\'джин, что в южном Дуротаре.', 'Верните это рекламное сообщение Ксар\'Ти в деревню Сен\'Джин в Дуротаре.', 'Итак, начнем тренировку?', 'А, ты получила мое письмо? Отлично.', NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14089, 'Уроки верховой езды в Тирисфальскх лесах', 'Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Вельмы Варнам.$B$BЕе можно найти в Брилле, в Тирисфальских лесах.', 'Верните это рекламное сообщение Вельме Варнам в Брилл в Тирисфальских лесах.', '', NULL, NULL, NULL, 'Брошюра об уроках верховой езды (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14090, 'Гормоку нужны снобольды', 'Уже двое моих людей погибли, пытаясь угомонить магнатавра по кличке Гормок, а это животное все еще буйствует – воет без остановки и требует своего любимого снобольда.$B$BЯ бы его собственными руками придушил, но Серебряный Авангард собирается выпустить его на бой в Колизее. Похоже, придется попытаться разыскать его любимую игрушку. Возьми эту сеть и отправляйся к Побоищу Гарма, что на юго-востоке Грозовой Гряды и к северо-востоку от К-3. Поймай там несколько снобольдов – и молись Свету, чтобы среди них оказался тот самый зверек.', 'Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Савинии Певице Преданий в Павильон Серебряного союза на Ристалище Серебряного турнира.', 'Чем быстрее мы уберем этих вонючих тварей в клетку, тем лучше. Жаль, что Серебряный Авангард не поручил Похитителям Солнца присматривать за этой тварью. Они так похожи, что им не составило бы труда найти общий язык.', NULL, NULL, NULL, 'Поймано последователей с Холмов Снежной Слепоты', 'Утяжеленная сеть', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14092, 'Завтрак Чемпионов', 'Теперь, когда строительство Колизея завершено, Серебряный Авангард поручил нам заботу о зверях, с которыми придется сразиться чемпионам.$B$BЭтим гигантским йормунгарам полагается странная диета – они питаются яйцами себе подобных. Самые сытные откладывают глубинные йормунгары.$B$BВот, отнеси этот барабан к Подножию, что в центре Грозовой Гряды, и ударь в них возле снежных курганов. Звук пробудит глубинных йормунгаров, и ты сможешь убить их, собрать яйца и принести на Ристалище.', 'Принесите 4 яйца йормунгаров Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.', 'Я сообщу крестоносцам, что пока Серебряный союз прохлаждался, ты вернулся с провиантом.', 'Тебе удалось добыть яйца? А то йормунгары уже проявляют недовольство.', NULL, NULL, 'Яйца йормунгаров', 'Землетрясущий барабан', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14095, 'Опознание останков', 'Неповрежденный зуб кракена – это действительно редкая находка. Наверняка она заинтересует Крестоносца Серебристый Рассвет из Серебряного павильона.', 'Отнесите зуб кракена Крестоносцу Серебристый Рассвет в Серебряный павильон.', 'Я знал, что тебе не составит труда справиться с кракеном. Теперь, когда это чудовище не нападает на наши корабли, квалдирам останется только спасаться бегством. Отличная работа, чемпион!', 'Что там у тебя, чемпион?', NULL, NULL, 'Зуб кракена (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14096, 'На этот раз ты нарвался, Кул', 'Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что приспешники культа Проклятых разбили лагерь на Заставе Вестника Смерти, что на западе от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.$B$BРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что злодеи принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя, найди ключи, спаси Кула и несчастных претендентов от ужасной участи!', 'Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.', 'Благодаря тебе Кул и другие претенденты снова вернулись в строй, чтобы сражаться с Плетью. К несчастью, нам не впервой спасать этого доблестного мужа от самого себя. Надеюсь, претенденты выберут себе другой пример для подражания.', NULL, NULL, NULL, 'Кул Безрассудный спасен', 'Спасено пленных претендентов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14100, 'Реликвия Служителей Земли', 'Ты уже многому $gнаучился:научилась:, $N. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохрянять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.$B$BПоговори с Готуром Четыре Ветра на Аллее Мудрости в Оргриммаре и обрети власть над четырьмя стихиями.', 'Принесите четыре тотема Готуру Четыре Ветра в Оргриммар.', '', NULL, NULL, NULL, 'Тотем огня', 'Тотем земли', 'Тотем воздуха', 'Тотем воды');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14101, 'Дроттинн Хротгар', 'Квалдиры, морские врайкулы, которые грабят корабли и прибрежные поселения, захватили остров клыкарров, что находится на севере пролива. Их предводитель – бывалый пират Дроттинн Хротгар, который давно уже стремится установить контроль над этими морями.$B$BПока он правит шайкой бандитов, наши корабли и транспортные суда находятся в постоянной опасности. А если мы окажемся отрезанными от остального мира, нам останется только сдаться на милость Королю-личу.$B$BВозьми этот боевой рог, который мы отняли у пленного квалдира, и отнеси его к кругу клыкаррских статуй на северо-востоке Лагеря Хротгара. С его помощью ты сможешь бросить вызов предводителю врайкулов.', 'Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Дроттинна Хротгара.', 'Смерть Дроттинна приведет к стычкам среди квалдиров, стремящихся занять его место, что поможет нам выиграть время. Крестоносцы турнира в долгу у тебя, чемпион.', NULL, NULL, NULL, 'Дроттинн Хротгар убито', 'Боевой рог Квалдира', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14102, 'Призыватель туманов Йингвар', 'Квалдиры вернулись на берега Нордскола – и это может стать для нас проблемой, если мы не обеспечим безопасность наших грузов и подкреплений. Один из их предводителей, Призыватель туманов Йингвар, поселился в пещере на западной стороне Лагеря Хротгара. Оттуда он управляет туманами, чтобы скрыть базы пиратов и подвластных квалдирам морских чудовищ.$B$BВозьми этот амулет и отправляйся на север от Ристалища, к Лагерю Хротгара. Найди пещеру призывателя туманов и воспользуйся амулетом, чтобы увидеть его.', 'Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Призывателя туманов Йингвара.', 'Ты помог нам выиграть драгоценное время для подготовки операции против квалдиров. Когда-нибудь мы очистим от них моря. Серебряный Авангард вновь у тебя в долгу, Альдемир.', NULL, NULL, NULL, 'Призыватель туманов Йингвар убито', 'Амулет призывателя туманов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14103, 'Титаниевый порошок', '', 'Привет, $N! Хочешь что-нибудь продать? +10 ед. репутации с Кирин-Тор', 'Превосходно! Еще одна порция порошка!$B$BТолько между нами, ювелирами – я знаю, как легко и непринужденно заработать много денег, продавая изделия из \"чистого титана\" незадачливым даларанским магам. Их великого ума не хватает на то, чтобы экономно относиться к золоту. Так что если добудешь еще порошка – с радостью куплю его у тебя.', NULL, NULL, NULL, 'Титановый порошок', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14104, 'Орнолф Меченый', 'Орнолф Меченый – безжалостный пират, о котором со страхом отзываются даже его собратья-квалдиры. Он и его команда \"Ярости Бора\" грабят суда и убивают наших людей.$B$BОрнолф и его бандиты были среди тех, кто принял участие в расправе над обитателями острова клыкарров, который теперь носит название Лагерь Хротгара. Корабль этого пирата стоит на якоре в гавани на востоке этого острова. Возьми этот захваченный флаг и установи его на корабле. Не сомневаюсь, это приведет Орнолфа в ярость, и он попытается лично расправиться с тобой. Удачи!', 'Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Орнолфа Меченого.', 'Команда Орнолфа захочет отомстить за своего вождя, но сейчас, когда они остались без предводителя, их будет легко уничтожить. Мы должны выполнить свою миссию и дожить до того дня, когда Ледяная Корона будет очищена от Плети и прочего зла.', NULL, NULL, NULL, 'Орнолф Меченый убито', 'Захваченное квалдирское знамя', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14105, 'Вестник смерти Карос', 'Культ Проклятых удвоил свои усилия, стремясь к нашему уничтожению. Они обнаглели настолько, что собрали свои силы на западе от Ристалища, на Заставе Вестника Смерти.$B$BВозглавляет их безжалостный Вестник Смерти Карос, и скоро его люди нападут на нас из-за возведенных укрытий.$B$BНаши солдаты и искатели славы готовятся отразить атаку, но только чемпионы могут обезглавить войско противника. Найди Вестника Смерти, $N, и убей его.', 'Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Вестника Смерти Кароса.', 'Ты служишь примером всем, кто собрался под нашими знаменами. Вместе мы покажем Плети, что нас не одолеть!', NULL, NULL, NULL, 'Вестник смерти Карос убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14107, 'Судьба Павших', 'Серебряный Авангард – не единственная сила, противостоящая Королю-личу в Ледяной Короне. Но наш враг хочет обратить против нас души павших союзников...$B$BИх духи блуждают по Долине павших героев, на юго-западе от ристалища и к западу от Алдуртара. Земля там буквально усыпана кристаллами душ, которые Плеть использует для подчинения призраков. Собери эти кристаллы и освяти с помощью Благословенной светом реликвии, чтобы даровать покой неприкаянным духам. Они это заслужили.', 'Крестоносец Серебристый Рассвет из Серебряного павильона просит вас даровать покой 6 духам павших героев.', 'Ты оказал великую услугу нашим павшим братьям и избавил нас от печальной участи уничтожать их на поле боя. Чем больше мы сражаемся с Плетью, тем сильнее беспокоит меня собственная судьба.$B$BХотелось бы мне, чтобы кто-то позаботился о моих бренных останках, если мне суждено пасть в бою. Мне невыносима мысль о том, что моим братьям придется убивать меня бесчисленное количество раз.', NULL, NULL, NULL, 'Благословлено духов павших героев', 'Благословенная светом реликвия', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14108, 'Изгнать Кракена!', 'Похитители Солнца и Серебряный союз отправили корабли на север, чтобы вступить в схватку с врайкулами, захватившими Лагерь Хротгара, но по пути были перехвачены пиратским флагманом. Хуже того, проклятые квалдиры нашли способ вызвать из глубин Северного моря свирепое чудовище – кракена. Если мы хотим спасти хоть кого-то из команды кораблей, мы должны изгнать кракена и прервать ритуал квалдиров.$B$BКрестоносец, возьми эти копья и пусть серебряный гиппогриф отнесет тебя в самую гущу битвы.', 'Крестоносец Серебристый Рассвет из Серебряного павильона просит вас оседлать серебряного гиппогрифа, бросить 6 пылающих копий в кракена Северного моря и поразить 3 врайкулов-пробудителей глубин.Серебряного гиппогрифа можно найти возле палатки Серебряного Авангарда на Ристалище Серебряного Турнира.', 'Крестоносец, благодаря твоим действиям моряки смогли избежять ужасной участи. Возможно, в следующий раз эти сорвиголовы из Серебряного союза и Похитителей Солнца прислушаются к нашим советам прежде, чем бросаться на амбразуры.', 'Неужели с кракеном еще не покончено? Поторопись, крестоносец – времени осталось мало!', NULL, NULL, 'Брошено копий в кракена', 'Квалдир-пробудитель глубин убито', 'Пылающие копья (Прилагается)', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14111, 'Реликвия Служителей Земли', 'Ты уже многому $gнаучился:научилась:, $N. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохрянять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.$B$BПоговори с Предсказателем Эанну в Стальгорне возле Великой Кузни – он поможет тебе отточить мастерство в повелевании стихиями.', 'Принесите четыре тотема Предсказателю Эанну в Стальгорн.', 'А, так значит, у тебя есть все четыре тотема. Можешь гордиться своими достижениями, юный $r, но это еще только начало.$B$BВот, прими это в дар от Служителей Земли. Носи эту реликвию с собой как символ власти над четырьмя стихиями.$B$BИ продолжай свои тренировки! Смертельная опасность нависла над этим миром – я чувствую ее в дыхании ветра и дрожи земли. Мы должны готовиться к худшему.', 'Да пребудут с тобой добрые духи. Что привело тебя к Служителям Земли?', NULL, NULL, 'Тотем огня', 'Тотем земли', 'Тотем воздуха', 'Тотем воды');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14112, 'Кстати, чем питаются йети?', 'Рыцари поймали огромного йети по кличке Ледяной Рев, который будет участвовать в гладиаторских боях, и поручили нам тренировать и кормить его.$B$BЖаль, им не понравилась моя идея отдать ему на растерзание парочку Похитителей Солнца. Эта тварь предпочитает мясо акул, так что тебе придется отправиться за ним на \"Серебряный Клинок\", который стоит на якоре к северу пролива. Возьми свежую наживку из бочек на борту и брось ее в воду – она привлечет внимание акул.', 'Савиния Певица Преданий из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести ей 3 куска мяса акулы Северного моря.', 'Я рада, что мы справились с этой задачей. Пусть это была не самая почетная миссия на свете, но раз уж мы заключили договор с Серебряным Авангардом, мы должны выполнять все, что они от нас потребуют. Во всяком случае, это выгодно отличает нас от Похитителей Солнца.', 'Надеюсь, ты принес еду для Ледяного Рева – иначе мне придется перевести его на диету из представителей Похитителей Солнца.', NULL, NULL, 'Мясо акулы Северного моря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14136, 'Спасательная операция на море', 'Квалдиры захватили маленький остров на севере и переименовали его в Лагерь Хротгара. Чтобы разведать ситуацию, мы отправили туда капитана Аэртаса Огненного Ястреба, но его корабль попал в засаду к пиратам неподалеку от Ристалища! К несчастью, квалдиры значительно превосходят по численности его команду. Прошу тебя, отправляйся туда и покажи этим бандитам, что они не на тех напали. $B$B\"Огненный Ястреб\" находится к северу от Ристалища, на западной части пролива.', 'Гирана Окровавленная из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас убить 8 квалдиров-берсерков и 3 квалдиров-гарпунеров, напавших на \"Огненный Ястреб\".', 'Отличная работа, Чемпион. Наша борьба еще не закончена, но теперь квалдиры поймут, что на нас нельзя нападать безнаказанно.', NULL, NULL, NULL, 'Квалдир-берсерк убито', 'Квалдир-гарпунер убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14140, 'Остановить нападение', 'Квалдиры, морские врайкулы, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.$B$BАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.', 'Гирана Окровавленная с Ристалища Серебряного турнира просит вас убить 10 квалдиров.', 'Твои действия подтвердили, что Похитители Солнца – гораздо более надежные союзники Серебряного Авангарда, нежели Серебряный союз. Вместе мы одержим победу!', NULL, NULL, NULL, 'Убито квалдиров', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14141, 'Гормоку нужны снобольды', 'Уже двое моих людей погибли, пытаясь угомонить магнатавра по кличке Гормок, а это животное все еще буйствует – воет без остановки и требует своего любимого снобольда.$B$BЯ бы его собственными руками придушил, но Серебряный Авангард собирается выпустить его на бой в Колизее. Похоже, придется попытаться разыскать его любимую игрушку. Возьми эту сеть и отправляйся к Побоищу Гарма, что на юго-востоке Грозовой Гряды и к северо-востоку от К-3. Поймай там несколько снобольдов – и молись Свету, чтобы среди них оказался тот самый зверек.', 'Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.', 'Чем быстрее мы уберем этих вонючих тварей в клетку, тем лучше. Жаль, что Серебряный Авангард не поручил Серебряному союзу присматривать за тварями. Вскоре им придется запачкать свои белоснежные ручки в борьбе за Цитадель Ледяной Короны, и я опасаюсь, что они окажутся слишком слабыми и ненадежными союзниками.', NULL, NULL, NULL, 'Поймано последователей с Холмов Снежной Слепоты', 'Утяжеленная сеть', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14142, 'На этот раз ты нарвался, Кул', 'Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что члены культа Проклятых разбили лагерь на Заставе Вестника Смерти, к западу от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.$B$BРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что мерзавцы принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя – найди ключи, спаси Кула и несчастных претендентов от ужасной участи!', 'Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира.', 'К сожалению, Кулу придется смириться с очередным поражением. Нам уже не раз приходилось спасать его от самого себя. Жаль, что некоторые претенденты берут с него пример и начинают вести себя как представители Серебряного союза.', NULL, NULL, NULL, 'Кул Безрассудный спасен', 'Спасено пленных претендентов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14143, 'Лапами кверху', 'Серебряный Авангард отправил сюда корабль, перевозивший мясо долгоногов и прочие припасы для Ристалища, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.$B$BОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может закончиться провизия.', 'Верните 10 украденных окорочков долгонога Гиране Окровавленной из Павильона Похитителей Солнца на Ристалище Серебряного турнира.', 'Мда, выглядят они... не очень, но есть можно. Крестоносцы будут рады узнать, что нам удалось спасти хоть какие-то припасы с корабля. А эти обглоданные куски можно будет отдать Серебряному союзу, что значительно улучшит мое настроение.', 'Тебе удалось найти украденные припасы?', NULL, NULL, 'Украденный окорочок долгонога', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14144, 'Милосердие Света', 'Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.$B$BУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.', 'Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Гиране Окровавленной в шатер Орды на Ристалище Серебряного турнира.', '<Гирана берет у вас молитвенник.>$B$BСпасибо. Мы редко общаемся с крестоносцами с глазу на глаз, но Исповедница Пейлтресс многому научила меня во время своего пребывания на Ристалище.', 'Ты позаботился о душах убитых туаликов?', NULL, NULL, 'Проведено последних ритуалов', 'Молитвенник исповедницы (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14145, 'Кстати, чем питаются йети?', 'Рыцари поймали огромного йети по кличке Ледяной Рев, который будет участвовать в гладиаторских боях, и поручили нам тренировать и кормить его.$B$BЖаль, им не понравилась моя идея отдать ему на растерзание парочку представителей Серебряного союза. Эта тварь предпочитает мясо акул, так что тебе придется отправиться за ним на \"Багровый Рассвет\", который стоит на якоре к северу пролива. Возьми свежую наживку из бочек на борту и брось ее в воду – она привлечет внимание акул.', 'Тайлос Вестник Зари из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести ему 3 куска мяса акулы Северного моря.', 'Я рад, что мы справились с этой задачей. Пусть это была не самая почетная миссия на свете, но раз уж мы заключили договор с Серебряным Авангардом, мы должны выполнять все, что они от нас потребуют. Во всяком случае, это выгодно отличает нас от Серебряного союза.', 'Надеюсь, ты принес еду для Ледяного Рева – иначе мне придется перевести его на диету из представителей Серебряного союза.', NULL, NULL, 'Мясо акулы Северного моря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14151, 'Багровый рубин', 'Багровый рубин обработать непросто – это самый изысканный камень во всем Нордсколе. На солнце он сияет подобно багровой хрустальной розе.$B$BНо прежде, чем я передам тебе рецепт, тебе придется сделать пять эпических трансмутаций драгоценных камней. Можешь создавать любые камни, даже одинаковые.$B$BВозвращайся, когда будешь $gготов:готова:.', 'Линзи Черноболт просит вас успешно трансмутировать пять эпических драгоценных камней с помощью алхимии. Можно трансмутировать аметрин, око Зула, страхолит, царский янтарь и величественный циркон.', '', NULL, NULL, NULL, 'Трансмутировано эпических камней', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14152, 'Спасательная операция на море', 'Послушай, чемпион: капитан Эллеан Гребень Волны повела свой корабль на север, чтобы изгнать квалдиров из Лагеря Хротгара, но по пути наткнулась на банду пиратов, направлявшихся к Ристалищу. К несчастью, квалдиры значительно превосходят по численности команду Эллеан, и нашим морякам все труднее сопротивляться натиску бандитов.$B$BОтправляйся на север, к кораблю в Проливе Хротгара, который находится между Ристалищем и Лагерем Хротгара, и помоги капитану отразить атаку пиратов. Схватка происходит на востоке пролива.', 'Отправляйтесь в Северное море и убейте 8 врайкулов-берсерков и 3 врайкулов-гарпунеров, напавших на \"Гребень Волны\".', 'Похоже, дела обстоят еще хуже, чем мы предполагали. Но с твоей помощью мы смогли спасти многих членов команды \"Гребня Волны\".', NULL, NULL, NULL, 'Квалдир-берсерк убито', 'Квалдир-гарпунер убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14160, 'Список заслуг', 'В этом свитке перечислены многие великие достижения, полученные |3-4($N) в области ювелирного искусства.$B$BОтнесите его Тимоти Джонсу и получите причитающуюся награду.', 'Доставьте Список заслуг Тимоти Джонсу в Даларан.', '', NULL, NULL, NULL, 'Список заслуг (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14163, 'К оружию! Остров Завоеваний', 'Чем ближе мы к схватке с Королем-личом, тем очевиднее тот факт, что Орда стоит на пути к нашей победе в Ледяной Короне.$B$BЧтобы отрезать нам путь к Острову Завоеваний, они выслали элитную армию стражей, известную как Кор\'крон. Стоит ли говорить о том, насколько стратегически важен этот клочок земли? Я поручаю тебе, $N, одержать победу в сражении за остров!', 'Победите на поле боя Острова Завоеваний и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Пока на нашей стороне сражаются такие солдаты, как ты, $N, Орде никогда не взять над нами верх.', NULL, NULL, NULL, 'Одержана победа на Острове Завоеваний', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14164, 'К оружию! Остров Завоеваний', 'Вскоре мы добьемся победы в Нордсколе... но для начала нам надо закрепиться в Ледяной Короне, наладить поставки продовольствия и подкреплений.$B$BОстров Завоеваний представляется мне идеальным плацдармом – это богатое ресурсами место легко защитить от нападений. Однако похоже, что Альянс пришел к такому же выводу и послал Седьмой Легион навстречу нашим войскам.$B$B$N, отправляйся туда и сделай все для нашей победы!', 'Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды, на Озеро Ледяных Оков, в Даларан или Шаттрат.', '', NULL, NULL, NULL, 'Одержана победа на Острове Завоеваний', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14166, 'Благодарный покойник', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.', 'Принесите поминальный хлеб веселому даларанскому духу на кладбище Даларана.Чтобы увидеть дух, используйте оранжевые бархатцы.', '', NULL, NULL, NULL, 'Поминальный хлеб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14167, 'Благодарный покойник', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.', 'Принесите поминальный хлеб веселому духу дворфа на кладбище Стальгорна.Чтобы увидеть дух, используйте оранжевые бархатцы.', '', NULL, NULL, NULL, 'Поминальный хлеб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14168, 'Благодарный покойник', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.', 'Принесите поминальный хлеб веселому духу гнома на кладбище Стальгорна.Чтобы увидеть дух, используйте оранжевые бархатцы.', '', NULL, NULL, NULL, 'Поминальный хлеб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14169, 'Благодарный покойник', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестаралась... и съела все, что они приготовили для меня! Даже крошки подмела!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я была бы очень благодарна!$B$BКажется, рецепт можно купить у Чепмана.', 'Принесите поминальный хлеб веселому духу дренея на кладбище Экзодара.Чтобы увидеть дух, используйте оранжевые бархатцы.', '', NULL, NULL, NULL, 'Поминальный хлеб', NULL, NULL, NULL);
