INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14174, 'Благодарный покойник', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.', 'Принесите поминальный хлеб веселому духу Отрекшегося на кладбище Подгорода.Чтобы увидеть дух, используйте оранжевые бархатцы.', '', NULL, NULL, NULL, 'Поминальный хлеб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14175, 'Благодарный покойник', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.', 'Принесите поминальный хлеб веселому духу орка на кладбище Оргриммара.Чтобы увидеть дух, используйте оранжевые бархатцы.', '', NULL, NULL, NULL, 'Поминальный хлеб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14176, 'Благодарный покойник', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.', 'Принесите поминальный хлеб веселому духу таурена на кладбище Громового Утеса.Чтобы увидеть дух, используйте оранжевые бархатцы.', '', NULL, NULL, NULL, 'Поминальный хлеб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14177, 'Благодарный покойник', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.', 'Принесите поминальный хлеб веселому духу тролля на кладбище Оргриммара.Чтобы увидеть дух, используйте оранжевые бархатцы.', '', NULL, NULL, NULL, 'Поминальный хлеб', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14178, 'К оружию! Низина Арати', 'Беда битвы на несколько фронтов, $gпарень:подруга:, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление.Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $N, и принеси нам победу. Мы не можем позволить Ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!', 'Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Превосходные новости,$C! Еще несколько подобных тактических побед – и Орда никогда не оправится от поражения.', NULL, NULL, NULL, 'Одержана победа в Низине Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14179, 'К оружию! Око Бури', 'Битва с Ордой не знает границ, $N. Даже в Запределье старая ненависть может вспыхнуть с новой силой, склонив чаши весов войны в пользу одного из противников.$B$BОтправляйся в Око Бури и убедись, что Альянс одержит верх в Запределье, как и по всему Азероту.', 'Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Мы еще на шаг приблизились к победе над Ордой. Нельзя позволить, чтобы наш враг чувствовал себя в безопасности.', 'Говори же, $N! Есть ли вести с фронтов?', NULL, NULL, 'Одержана победа в Оке Бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14180, 'К оружию! Ущелье Песни Войны', 'Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но не только из люви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Отличная работа, $N. Мы должны любой ценой защищать наши границы!', NULL, NULL, NULL, 'Одержана победа в Ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14181, 'К оружию! Низина Арати', 'Альянс вот-вот захватит Низину Арати! Мы немедленно должны послать туда подкрепление, иначе все наши труды пойдут прахом.$B$BНе медли, $C, отправляйся в Низину Арати и сокруши врагов. Орда победит!', 'Победите на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Ты покрыл славой знамена Орды, $N. Твоя сегодняшяя победа открыла путь к многим славным свершениям!', NULL, NULL, NULL, 'Одержана победа в Низине Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14182, 'К оружию! Око Бури', 'Мы будем сражаться с врагами повсюду – в Азероте и Запределье. $B$BНельзя позволить Альянсу закрепиться в Оке Бури. Брось им вызов сегодня, ибо завтра может быть слишком поздно!', 'Победите на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Мы гордимся тобой, $N. Враг должен знать, что ему нигде не укрыться от нашего возмездия!', 'Ты вернулся с вестями о нашей победе?', NULL, NULL, 'Одержана победа в Оке Бури', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14183, 'К оружию! Ущелье Песни Войны', 'Альянс – опасный противник, $N. Они заявляют, что защищают Ясеневый лес, пытаясь оправдать нападения на наши территории в Степях.$B$BНо сегодня у нас появилась возможность вытеснить противника с наших земель раз и навсегда! Отправляйся в Ущелье Песни Войны и отбери то, что по праву принадлежит нам!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', 'Орда в долгу перед тобой, Баландэрси. Твой народ может гордиться отвагой, проявленной тобой на поле боя.', NULL, NULL, NULL, 'Одержана победа в Ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14199, 'Доказательство смерти: Черный рыцарь', 'Мой коллега, Верховный маг Времиар, попросил меня предупредить тебя об опасности. Скоро ты будешь участвовать в Испытании чемпиона в Ледяной Короне. Остерегайся вмешательства со стороны соперника, известного как Черный рыцарь.$B$BПринеси мне осколок его души в доказательство того, что он больше не станет на пути Кирин-Тора. Мне было сказано, что в вашем противостоянии должен остаться лишь один.', 'Верховный маг Лан\'далок из Даларана просит вас принести ему осколок души Черного рыцаря.Это задание выполняется в героическом режиме.', 'Рад видеть, что ты вернулся с победой! Воистину, ты чемпион не только Серебряного Авангарда, но и Кирин-Тора.$B$BОстается надеяться, что нанесенный тобой удар был смертельным, и мы больше не услышим об этом злодее.', 'Так Времиар был прав? Черный рыцарь действительно попытался вмешаться?', NULL, NULL, 'Частица души Черного рыцаря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14203, 'Промокший рецепт', 'Похоже, это остатки смеси, применяемой для изготовления очень крепкого вина. Возможно, владелец лавки \"Еще по сто\" заинтересуется этим рецептом...', 'Принесите промокший рецепт Кристи Стоктон в Даларан.', '', NULL, NULL, NULL, 'Промокший рецепт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14349, 'Приказ по армии', '$C, к нам поступил приказ от самой Сильваны – отправить самых надежных агентов назад в Подгород для выполнения крайне важной тактической операции.$B$BК несчастью, все агенты, на которых я мог бы положиться в этом деле, были убиты три года назад. Вместо них мне пришлось набрать шайку безмозглых головорезов.$B$B<Натанос сурово смотрит на вас.>$B$BНемедленно отправляйся в Подгород на аудиенцию к Темной Госпоже. Постарайся не опозорить мои седины, $C!', 'Отправляйтесь в Подгород и поговорите с леди Сильваной Ветрокрылой.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14350, 'Курьер из Багрового Легиона', 'Мы не можем напрямую выступить против главнокомандующих Алого ордена – их слишком хорошо охраняют. Однако есть другие способы решения проблемы. Лишившись своей главной силы, они ничего не смогут нам противопоставить.$B$BМои верные стражи смерти уже давно собирают сведения о деятельности Алого ордена за пределами Стратхольма. Каждый день им присылают инструкции из центрального штаба в Длани Тира. Мы должны перехватить их, $r! Убей курьера из Багрового Легиона и забери бумагу. Отдашь ее Натаносу.', 'Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря.За дальнейшими указаниями обращайтесь к Натаносу Гнилостню.', '', NULL, NULL, NULL, 'Приказ верховного рыцаря', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14351, 'Битва за Хилсбрад', 'Поскольку ты $gпроявил:проявила: немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.$B$BОтнеси мое письмо Брагору Кровопалу в Подгород. Можешь гордиться собой, $C.', 'Отнесите запечатанное рекомендательное письмо Дарталии Брагору Кровопалу в Подгород.', '', NULL, NULL, NULL, 'Запечатанное рекомендательное письмо Дарталии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14352, 'Нечестивый союз', 'Госпожа моя!$B$BНаше предложение вам прекрасно известно. Для вас это отличная возможность получить безграничную власть над Степями и окрестными землями. От вас нам требуется лишь небольшое содействие – дайте нам свободу действий в этих землях.$B$BМы убедительно просим вас рассмотреть это предложение. Мы обладаем великой силой и охотно поделимся ею с тем, кто достаточно мудр, чтобы примкнуть к нам. Я буду ждать вас у Курганов Иглошкурых.$B$BС наилучшими пожеланиями,$BПосланник Малкин.', 'Отнесите маленький свиток Брагору Кровопалу в Подгород.', '', NULL, NULL, NULL, 'Маленький свиток (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14353, 'Нечестивый союз', 'Предположительно, этот Малкин находится за пределами Курганов Иглошкурых. Это не обсуждается – он должен умереть!$B$BМой связной из Оргриммара сообщил, что их разведчики обнаружили там следы чумы. Очевидно, что Иглошкуры тоже заражены – они стали слишком сильными. Мы должны немедленно положить конец козням Плети!$B$BНайди этого Малкина и убей его. Доложи мне, когда дело будет сделано.', 'Принести голову посла Брагору Кровопалу в Подгород.', '', NULL, NULL, NULL, 'Голова посланника Малкина', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14355, 'В монастырь Алого ордена', 'Одна из моих задач – помогать Отрекшимся охранять границы, и в этом ты, $C, можешь мне помочь.$B$BЖивой или мертвый – Алому ордену без разницы; они убивают моих людей наравне с нежитью. Они – моя главная проблема, с которой тебе предстоит разобраться.$B$BОтправляйся в Монастырь и убей верховного инквизитора Вайтмейн с ее лейтенантами.', 'Убейте верховного инквизитора Вайтмейн, командира Могрейна из Алого ордена, воителя Ирода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Брагору Кровопалу в Подгород.', 'Я уверен, что Сильвана будет счастлива узнать о благополучном решении проблемы. Я поручил тебе непростое задание, но ты вернулся с победой, $N. Я не забуду то, что ты для нас сделал.', NULL, NULL, NULL, 'Верховный инквизитор Вайтмейн убито', 'Командор Алого ордена Могрейн убито', 'Ирод убито', 'Псарь Локси убито');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14356, 'Силы разрушения...', 'Послушай, $C.$B$BТебе это, возможно, неизвестно, но Огриммар столкнулся с неожиданной проблемой. Глубоко в Огненной пропасти твоит свои зловещие дела секта Совета Теней – Пламенеющий Клинок. Она состоит в основном из орков, поэтому я не могу доверять вот этим бугаям. Твоя помощь придется как нельзя кстати.$B$BВо владении Совета оказались две книги, которые не должны попасть в руки Пламенеющего Клинка и Отрекшихся. Принеси их мне.', 'Принесите книги \"Заклинания Тьмы\" и \"Заклятия Пустоты\" Брагору Кровопалу в Подгород.', 'Отлично, $С. Ты справился с моим поручением. Эти книги я спрячу в безопасное место – меньше всего мне хочется узнать о том, что Совет Теней опять набрал силу.$B$BЗаглядывай ко мне время от времени – у нас еще полно дел, и мне может пригодиться толковый помощник.', 'Книги в безопасности? Нельзя, чтобы они попали не в те руки.', NULL, NULL, 'Заклинания Тьмы', 'Магическая формула Пустоты', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14409, 'Осторожное возвращение', 'Удели мне минутку внимания, $C.$B$BГрядут большие перемены, и это предчувствие заставило нас покинуть руины Эльдре\'Таласа. Я прибыл сюда для исследования этого города и не могу оторваться от своей работы, но если у тебя есть свободное время, я мог бы дать тебе поручение.$B$BОдин из моих коллег отправился в Дарнас побеседовать с Верховной жрицей – он надеется, что мы сможем найти с ней общий язык. Пожалуйста, отнеси ему этот журнал – он может помочь ему в выполнении дипломатической миссии. Моего коллегу зовут Мордент Вечерняя Тень, и сейчас он находится в храме.', 'Отнесите журнал Дароса Морденту Вечерней Тени в Дарнас.', 'А, это записи Дароса! Он всегда очень скурпулезно относился к своим заметкам. Пожалуй, из этого журнала можно выяснить, как далеко мы продвинулись.$B$BСпасибо, что принес мне его. Возможно, когда мне удастся убедить окружающих в том, что мы не желаем вам зла, мы будем видеться гораздо чаще.', 'Похоже, у меня еще много времени, так почему бы и не побеседовать. О чем пойдет речь?', NULL, NULL, 'Журнал Дароса (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14418, 'Cтражи смерти', 'Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства.$B$BХоукинс будет доволен, и раз именно ты $gсовершил:совершила: это открытие – тебе и сообщать о нем.$B$BАх да, как я мог забыть?$B$BДобро пожаловать в ряды стражей смерти.', 'Отнесите гроссбух Андрона Алерику Хоукинсу в Зал Темной Госпожи в Подгороде.', '', NULL, NULL, NULL, 'Гроссбух Андрона (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14419, 'Cтражи смерти', 'Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умен, чтобы заподозрить неладное.$B$BНаша госпожа подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства.$B$BПоговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалеку от Района Фармацевтов.', 'Поговорите с Андроном Гантом в Подгороде.', '', NULL, NULL, NULL, 'Рекомендательное письмо Астора (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14420, 'Cтражи смерти', 'Чтобы вступить в ряды стражей смерти, элитной охраны Темной Госпожи, тебе придется сперва доказать свои способности.$B$BНе буду лгать: это задание может окончиться твоей гибелью.$B$BМне нужна помощь в нескольких вопросах. Во-первых, принеси мне личные вещи Астора Хадрена – это вестник, путешествующий между Серебряным бором и Подгородом. Как ты это сделаешь – тебе решать.$B$BПока что это все, что тебе следует знать. Справишься – узнаешь больше.', 'Принесите рекомендательное письмо Астора Менниту Каркаду в Квартал Разбойников Подгорода.', '', NULL, NULL, NULL, 'Рекомендательное письмо Астора', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14421, 'Cтражи смерти', 'Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочел бы иметь дело с тобой.', 'Отнесите гроссбух Андрона Менниту Каркаду в Квартал Разбойников Подгорода.', '', NULL, NULL, NULL, 'Гроссбух Андрона', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14436, 'Дворфийские делишки', 'Некие дворфы готовят раскопки на северо-западе – полагают, что в земле скрыты великие тайны. В некотором роде они правы, но оскверняя и уродуя лик природы, нельзя постигнуть ее мудрость. $B$BСобери инструменты дворфов, уничтожь их и принеси мне.$B$BЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.', 'Соберите 5 кирок геолога.Сломайте их в кузнице. Отнесите 5 сломанных инструментов Ахмо Громовому Рогу в деревню Кровавого Копыта.', '', NULL, NULL, NULL, 'Сломанные инструменты', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14437, 'Обряды Матери-Земли', 'Чтобы продолжить прохождение обрядов Матери-Земли, ты $gдолжен:должна: выдержать еще два испытания. Тебе бы не помешало поднабраться опыта, $N.$B$BОтправляйся в Деревню Кровавого Копыта и найди Ахмо Громового Рога. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. $B$BОтнеси этот тотем Ахмо. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.$B$BСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!', 'Отнесите тотем Соколиного Ветра Ахмо Громовому Рогу в Деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.', '', NULL, NULL, NULL, 'Тотем Ястребиного Ветра (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14438, 'Недобрые соседи', '$N, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.$B$BГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.$B$BСловами их не остановить.', 'Убейте 10 дубильщиков, 8 шкуродеров и 5 браконьеров из стаи Бледногривов и возвращайтесь к Ахмо Громовому Рогу в деревню Кровавого Копыта.', '', NULL, NULL, NULL, 'Дубильщик из стаи Бледногривов убито', 'Шкуродер из стаи Бледногривов убито', 'Браконьер из стаи Бледногривов убито', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14439, 'Путешествие в Громовой Утес', 'Отныне тебя будут почитать в стенах нашего великого города. $gПрошедший:Прошедшая: обряды Матери-Земли заслуживает такой чести.$B$BВыполни последнее задание, отыщи благородного вождя Кэрна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.', 'Поговорите с Бейном Кровавым Копытом в Громовом Утесе.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14440, 'Обряды Матери-Земли', 'Ты $gпрошел:прошла: обряды Матери-Земли и $gзаслужил:заслужила: достойное место среди жителей Громового Утеса.$B$BЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.$B$BМы охотники, $N. Внизу, в Мулгоре, есть могучий кодо по имени Арра\'чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра\'чеи.', 'Бейн Кровавое Копыто из Громового Утеса попросил принести ему рог Арра\'чеи.', '', NULL, NULL, NULL, 'Рог Арра\'чеи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14441, 'Автограф Гарроша', 'Говорят, что Гаррош Адский Крик – один из величайших героев Орды. Когда я вырасту, я тоже хочу стать героем Орды!$B$BТы $gзнаком:знакома: с Гаррошем? Окажи мне услугу! Возьми у него автограф! Я не знаю, как его попросить, у него нет времени для таких, как я... другое дело ты! Ты $gтакой же искатель:такая же искательница: приключений, как и он! Готов поспорить, что тебе получить у него автограф – раз плюнуть!$B$BПожалуйста!', 'Отправляйтесь в Оргриммар и постарайтесь получить автограф Гарроша Адского Крика для своего подопечного.', '', NULL, NULL, NULL, 'Автограф Гарроша', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14443, 'Потертая рукоять', 'Эта потертая рукоять меча знавала лучшие дни, но даже сейчас по ней можно сказать, что делал ее настоящий мастер.$B$BИзящная гравировка и инкрустация драгоценными камнями свидетельствует о том, что оружие некогда принадлежало знатному человеку. Серебряный союз наверняка заинтересуется этой находкой. Найдите его представителя в Покое Кель\'Делара, он находится к югу от ристалища Серебряного турнира.', 'Принесите потертую рукоять Каладису Сияющему Копью в Покой Кель\'Делара к югу от ристалища Серебряного Турнира.', '<Каладис бережно забирает у вас рукоять и осматривает ее со всех сторон.>$B$BЧто-то знакомое видится мне в этой вещи... как будто я знаю, откуда она могла взяться. Говоришь, нашел ее в цитадели? Очень интересно.$B$BМало осталось кузнецов, способных выковать подобный клинок, но, возможно, они прольют свет на тайну твоей находки.', 'Что это у тебя?', NULL, NULL, 'Потертая рукоять (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14444, 'То, что знают драконы', 'Ошибки быть не может – это рукоять могущественного древнего клинка. Вот только что это был за клинок? Я не могу вспомнить ни одного меча с такой гравировкой, но не все еще потеряно.$B$BМы должны обратиться к Кориалстразу, более известному тебе как Крас. Он – давний друг кель\'дорай и Кирин-Тора. За его плечами мудрость рода красных драконов; наверняка, он сможет нам помочь. Отправляйся за его советом на вершину Храма Драконьего Покоя.', 'Поговорите с Красом на вершине Храма Драконьего Покоя.', '', NULL, NULL, NULL, 'Спросить Краса о происхождении рукояти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14457, 'План Похитителей Солнца', 'Один из моих шпионов в Клоаке заметил там посланника Похитителей Солнца, которые, как ты понимаешь, редко проявляют интерес к тому, что творится в канализации. А этот покупал реагенты у продавца с Черного рынка. Несомненно, они что-то затевают.$B$BОтправляйся в Клоаку, найди этого прихвостня Похитителей Солнца и разберись с ним. Обыщи его тело – может быть, у него найдется информация о местонахождении той книги из Храма Драконьего Покоя. Нельзя допустить, чтобы она оказалась в Ледяной Короне.', 'Добудьте приказы Похитителей Солнца.', '', NULL, NULL, NULL, 'Приказы Похитителей Солнца', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14483, 'Не любовь витает в воздухе (а что-то иное!)', 'Оборотная сторона открытки исчерчена подробными и зловещими планами по заражению всего Азерота. Вы должны немедленно отнести ее одному из следователей Хитрой Шестеренки!', 'Принесите выцветшую открытку ко дню всех влюбленных детективу Крямсу Гвоздезубу в Оргриммар.', 'Что это тут у нас?$B$BОго, это уже серьезно. Очень серьезно. Целая куча головоломных деталей в одной упаковке. Спасибо, ты очень помог нам в расследовании. Приятно было работать с тобой.', 'Ты позаботился об этих коварных злодеях?', NULL, NULL, 'Выцветшая открытка ко дню всех влюбленных (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (14488, 'Получите, распишитесь', 'Непросто было меня найти, да? Ну да ладно, пора действовать. Сейчас или никогда.$B$BВозьми этот набор и отправляйся вглубь крепости, чтобы передать документы главе этой мерзоносной фармацевтической корпорации, Хаммелу.$B$BВ сундучке лежат сами бумаги и некоторые нейтрализаторы газов. Они защитят тебя от любых неприятных сюрпризов, которые могут встретиться на пути.', 'Отнесите повестку в суд аптекарю Хаммелу в Крепость Темного Клыка.', 'Не твое дело, чем мы тут занимаемся...', 'Кажется, я не просил здесь убираться... Да, я аптекарь Хаммел... а это что за ерунда? Думаешь, эти бессмысленные бумажки могут меня остановить? Ха!', NULL, NULL, 'Повестка в суд', 'Стандартный докторский набор', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (20438, 'Подходящая маскировка', 'Заслать тебя в Прибежище Похитителя Солнца будет нелегко. Туда допускаются только обладатели гербовых накидок Похитителей Солнца. Если бы нам только удалось заполучить одну из них, остальное можно было бы решить с помощью пары заклинаний.$B$BНо у меня есть идея! На балконе над \"Нитями судьбы\" стоит некто Шанди Шикблеск. Я его пару раз выручал в прошлом, так что он задолжал мне ответную услугу. Он стирает одежду многих граждан этого города. Может быть, он согласится одолжить тебе гербовую накидку...', 'Позаимствуйте у Шанди Шикблеска гербовую накидку.', '', NULL, NULL, NULL, 'Позаимствованная гербовая накидка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (20439, 'Встреча с магистром Хаторелем', 'Я зачаровал эту гербовую накидку особым заклинанием, которое позволит тебе пробраться мимо охранников Прибежища Похитителя Солнца. Оно будет действовать недолго, но за это время ты $gдолжен:должна: успеть найти бар \"Грязное животное\" и встретиться там с представителем Похитителей Солнца, этим магистром Хаторелем.$B$BВозьми у него копию \"Древних клинков драконьей ковки\", которую его люди одолжили в Храме Драконьего Покоя, и сразу же возвращайся ко мне.', 'Возьмите книгу \"Древние клинки драконьей ковки\" у магистра Хатореля из Прибежища Похитителя Солнца.', '', NULL, NULL, NULL, 'Древние клинки драконьей ковки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24216, 'К оружию! Ущелье Песни Войны', 'Альянс – опасный противник, $N. Они заявляют, что защищают Ясеневый лес, пытаясь оправдать нападения на наши территории в Степях.$B$BНо сегодня у нас появилась возможность вытеснить противника с наших земель раз и навсегда! Отправляйся в Ущелье Песни Войны и отбери то, что по праву принадлежит нам!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24217, 'К оружию! Ущелье Песни Войны', 'Альянс – опасный противник, $N. Они заявляют, что защищают Ясеневый лес, пытаясь оправдать нападения на наши территории в Степях.$B$BНо сегодня у нас появилась возможность вытеснить противника с наших земель раз и навсегда! Отправляйся в Ущелье Песни Войны и отбери то, что по праву принадлежит нам!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24218, 'К оружию! Ущелье Песни Войны', 'Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но делаем это не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24219, 'К оружию! Ущелье Песни Войны', 'Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но делаем это не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24220, 'К оружию! Низина Арати', 'Беда битвы на несколько фронтов, $gпарень:подруга:, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление.Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $N, и принеси нам победу. Мы не можем позволить ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!', 'Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Низине Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24221, 'К оружию! Низина Арати', 'Альянс вот-вот захватит Низину Арати! Мы немедленно должны послать туда подкрепление, иначе все наши труды пойдут прахом.$B$BНе медли, $C, отправляйся в Низину Арати и сокруши врагов. Орда победит!', 'Победите на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Низине Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24223, 'К оружию! Низина Арати', 'Беда битвы на несколько фронтов, $gпарень:подруга:, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление.Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $N, и принеси нам победу. Мы не можем позволить ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!', 'Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Низине Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24224, 'К оружию! Ущелье Песни Войны', 'Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но делаем это не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24225, 'К оружию! Ущелье Песни Войны', 'Альянс – опасный противник, $N. Они заявляют, что защищают Ясеневый лес, пытаясь оправдать нападения на наши территории в Степях.$B$BНо сегодня у нас появилась возможность вытеснить противника с наших земель раз и навсегда! Отправляйся в Ущелье Песни Войны и отбери то, что по праву принадлежит нам!', 'Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Ущелье Песни Войны', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24226, 'К оружию! Низина Арати', 'Альянс вот-вот захватит Низину Арати! Мы немедленно должны послать туда подкрепление, иначе все наши труды пойдут прахом.$B$BНе медли, $C, отправляйся в Низину Арати и сокруши врагов. Орда победит!', 'Победите на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Низине Арати', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24426, 'К оружию! Альтеракская долина', 'Мы почти изгнали врагов, что вторглись в Альтеракскую долину из Грозовой Вершины. Теперь надо перебросить наши силы на помощь клану Северного Волка.$B$BРешительная победа позволит нам высвободить ресурсы, необходимые для сокрушения этих подонков из Альянса на всех остальных фронтах.$B$BСтупай, $N. Заслужи великую честь, откликнувшись на зов отважных воинов клана Северного Волка.', 'Победите на поле боя Альтеракской долины и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Альтеракской долине', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24427, 'К оружию! Альтеракская долина', 'Беда битвы на несколько фронтов, $gпарень:подруга:, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление.Сегодня войскам в Альтеракской долине требуются отважные бойцы.$B$BСтупай прямо сейчас, $N, и помоги стражам Грозовой Вершины. Мы не можем допустить, чтобы клан Северного Волка ушел без возмездия после всего того зла, что они причинили нашим собратьям!', 'Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.', '', NULL, NULL, NULL, 'Победа в Альтеракской долине', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24428, 'Странное стечение обстоятельств', 'Тебе удалось совершить невозможное! Царица черных драконов лежит мертвой у твоих ног. Отруби ей голову и отнеси ее Зардету Черному Когтю.', 'Отнесите голову Ониксии Зардету Черному Когтю. Он ждет вас в подвале \"Забитого ягненка\".', 'Что? Где ты это взяла? Разве она не... Впрочем, опустим детали. Ты, наверное, хочешь получить в награду одну из этих побрякушек, не так ли?', 'Клянусь зубом Ноздорму!', NULL, NULL, 'Голова Ониксии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24429, 'Странное стечение обстоятельств', 'Тебе удалось совершить невозможное! Царица черных драконов лежит мертвой у твоих ног. Отруби ей голову и отнеси ее Ниру Огненному Клинку.', 'Отнесите голову Ониксии Ниру Огненному Клинку в Расселину Теней.', 'Ты принес мне голову существа, которое... Нет, я даже не хочу об этом задумываться. Наверное, теперь ты хочешь награду за свой подвиг?', 'Это еще что значит?', NULL, NULL, 'Голова Ониксии (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24431, 'Промокший рецепт', 'Похоже, это остатки смеси, применяемой для изготовления очень крепкого вина. Возможно, владелец лавки \"Еще по сто\" заинтересуется этим рецептом...', 'Принесите промокший рецепт Кристи Стоктон в Даларан.', 'Отличная находка, $N. Я не могу позволить, чтобы ты продал ее кому-нибудь другому, так что предложу очень выгодную цену.', 'Я всегда говорила – вино должно быть достойно дегустатора.', NULL, NULL, 'Промокший рецепт (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24442, 'Планы нападения квалдиров', 'Изучив захваченные планы нападения, вы находите карту Восточных королевств и Калимдора с обозначением главных поселений. Прочитав приказы, вы узнаете, что капитаны квалдиров разработали план коварных нападений на города.$B$BСудя по этим приказам, атака начнется вскоре после того, как Призыватель туманов Йингвар \"получит совет Сердца тумана\". Возможно, вы сможете отложить нападение, выкрав предзнаменование из Пещеры призывателя туманов, что на западной стороне Лагеря Хротгара, и уведомив об этом Вершительницу правосудия Мариэль Чистосердечную.', 'Добудьте Сердце тумана и принесите его вместе с планами нападения квалдиров Вершительнице правосудия Мариэль Чистосердечной на ристалище Серебряного Турнира.', '', NULL, NULL, NULL, 'Квалдирский план нападения (Прилагается)', 'Сердце тумана', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24451, 'Встреча с чародеем', 'Я зачаровал эту гербовую накидку особым заклинанием, которое позволит тебе пробраться мимо охранников даларанского Серебряного Анклава. Оно будет действовать недолго, но за это время ты $gдолжен:должна: добраться до верхних этажей штаб-квартиры Серебряного Анклава и встретиться там с представителем Серебряного союза, этим чародеем Тибалином.$B$BВозьми у него копию \"Древних клинков драконьей ковки\", которую его люди одолжили в Храме Драконьего Покоя, и сразу же возвращайся ко мне.', 'Возьмите книгу \"Древние клинки драконьей ковки\" у чародея Тибалина.', '', NULL, NULL, NULL, 'Древние клинки драконьей ковки', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24454, 'Возвращение к Каладису Сияющему Копью.', 'Эту книгу надо немедленно отнести Каладису Сияющему Копью. Ты этим займешься? Никому другому я не могу доверить столь ценную ношу, а ты уже $gдоказал:доказала: свою верность, обхитрив Похитителей Солнца.$B$BТвой путь лежит в Покой Кель\'Делара, что на юге от ристалища Серебряного Турнира в Ледяной Короне. Каладис будет ждать тебя вместе с мечом. Чем быстрее мы сможем распознать этот клинок, тем скорее сможем им овладеть.', 'Отнесите книгу \"Древние клинки драконьей ковки\" Каладису Сияющему Копью в Покой Кель\'Делара.', '', NULL, NULL, NULL, 'Древние клинки драконьей ковки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24498, 'Путь в Цитадель', 'Похоже, что сюда сгоняют пленных солдат для работы в карьере. Убей их надсмотрщиков и освободи рабов – тогда они непременно захотят поддержать нас в битве с Повелителем Плети Тиранием.', 'Освободите 15 порабощенных солдат Альянса и убейте начальника кузни Гархлада.', 'Сегодня ты хорошо потрудился. Теперь, когда нам помогают освобожденные рабы, мы вскоре соберем сильную армию, чтобы пройти через эту яму и положить конец злодеяниям Повелителя Плети.', NULL, NULL, NULL, 'Порабощенные солдаты Альянса освобождены', 'Начальник кузни Гархлад убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24499, 'Тени замученных душ', 'Не знаю даже, как отблагодарить тебя за то, что $gпришел:пришла: на помощь. У нас не хватает людей, чтобы начать наступление на Цитадель, но такой шанс выпадает один раз в жизни, и мы не можем его упустить.$B$BОчень скоро к нам должны присоединиться чемпионы из Колизея, но, если слухи правдивы, ты прекрасно $gэкипирован:экипирована: для того, чтобы в одиночку расчистить путь через кузню. Пробейся к дальнему концу подземелья и обеспечь нам проход к Яме Сарона. Мы должны закрепиться на этом плацдарме прежде, чем пошлем солдат в Цитадель.$B$BПрошу тебя, $N, поторопись. Мы на тебя рассчитываем.', 'Чтобы обеспечить безопасный проход в Яму Сарона, убейте Броньяма и Пожирателя Душ.', 'Как раз вовремя! Спасибо, $N.$B$BВпереди ждет Яма Сарона. Если наши разведчики не ошибаются, именно через нее лежит путь к Залам Отражений. Там Артаса практически не охраняют. Возможно, там мы найдем способ его победить... или даже – кто знает? – сможем его вернуть.', NULL, NULL, NULL, 'Броньям убито', 'Пожиратель Душ убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24500, 'Гнев Короля-лича', 'Утер многое знал о том, как победить Артаса. Трудно поверить, что нанести ему поражение можно лишь на ступенях его собственного трона. Но кто примет корону Короля-лича, если до этого дойдет дело?$B$BТак много вопросов, и каждый ответ может сыграть решающую роль. Найди Джайну и спасись от Короля-лича, пока еще есть время.', 'Найдите леди Джайну Праудмур и выберитесь из Залов Отражений.', '<Джайна все еще пытается отдышаться.>$B$BНе могу поверить, что мы все еще живы. Как глупо было следовать за ним! В который раз уже я совершаю эту ошибку. А ты... как безответственно с твоей стороны следовать за мной вместо того, чтобы убежать и сохранить бесценную информацию! Но все равно... спасибо тебе. Ты истинный герой.$B$BТеперь же, с благословением Утера у нас есть шанс выстоять против Артаса. Ни одна сегодняшняя смерть не была напраcной.', NULL, NULL, NULL, 'Джайна Праудмур найдена', 'Побег от Короля-лича удался', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24506, 'В ледяную цитадель', '$C! Быстрее, иди сюда, нам надо поговорить.$B$BМоя королева, Леди Сильвана Ветрокрылая, обнаружила брешь в обороне цитадели Ледяной Короны – некое место, известное как Кузня Душ. Она оставила мне поручение найти тех, кто мог бы ей помочь... и я надеюсь, что ты не откажешь в этой просьбе.$B$BПожалуйста, найди ее как можно скорее.', 'Войдите в Кузню Душ со стороны Цитадели Ледяной Короны и найдите леди Сильвану Ветрокрылую.', 'Хорошо. $N, я знаю, кто ты. Ты идеально подойдешь для выполнения этого задания.$B$BНам предоставилась уникальная возможность проникнуть в Цитадель Ледяной Короны, но мы должны действовать быстро, пока Артас не догадался, что происходит.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24507, 'Путь в Цитадель', 'Похоже, что сюда сгоняют пленных солдат для работы в карьере. Убей их надсмотрщиков и освободи рабов, $C, тогда они непременно захотят поддержать нас в битве с Повелителем Плети Тиранием.', 'Освободите 15 порабощенных солдат Орды и убейте начальника кузни Гархлада.', 'Сегодня ты хорошо потрудился. Теперь, когда нам помогают освобожденные рабы, мы вскоре соберем сильную армию, чтобы пройти через эту яму и положить конец злодеяниям Повелителя Плети.', NULL, NULL, NULL, 'Порабощенные солдаты Орды освобождены', 'Начальник кузни Гархлад убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24510, 'В ледяную цитадель', '$C! Быстрее, иди сюда, нам надо поговорить.$B$BМоя покровительница, леди Джайна Праудмур, обнаружила брешь в обороне цитадели Ледяной Короны – некое место, известное как Кузня Душ. Она оставила мне поручение найти тех, кто мог бы ей помочь... и я надеюсь, что ты не откажешь в этой просьбе.$B$BПожалуйста, найди ее как можно скорее.', 'Войдите в Кузню Душ со стороны Цитадели Ледяной Короны и найдите леди Джайну Праудмур.', '$N! Я рада, что ты откликнулся на зов.$B$BНам предоставилась уникальная возможность проникнуть в Цитадель Ледяной Короны, но мы должны действовать быстро, пока Артас не догадался, что происходит.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24511, 'Тени замученных душ', 'Хорошо, что хоть кто-то пришел к нам на помощь. У нас не хватает людей, чтобы начать наступление на Цитадель, но такой шанс выпадает один раз в жизни, и мы не можем его упустить.$B$BОчень скоро к нам должны присоединиться чемпионы из Колизея, хотя если слухи правдивы, ты достаточно хорошо $gэкипирован:экипирована:, чтобы и в одиночку пройти через кузню. Пробейся к дальнему концу подземелья и обеспечь нам проход к Яме Сарона. Мы должны закрепиться на этом плацдарме прежде, чем посылать солдат в Цитадель.$B$BПрошу тебя, $N, поторопись. Время не терпит.', 'Чтобы обеспечить безопасный проход в Яму Сарона, убейте Броньяма и Пожирателя Душ.', 'Как раз вовремя! Спасибо, $C.$B$BВпереди ждет Яма Сарона. Если наши разведчики не ошибаются, именно через нее лежит путь к Залам Отражений. Там Артаса практически не охраняют. Возможно, там мы найдем его уязвимое место... и моя месть наконец-то свершится.', NULL, NULL, NULL, 'Броньям убито', 'Пожиратель Душ убито', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24536, 'Дышать нечем!', 'Присмотрись к этим ребятам. Хитрая Шестеренка уже не первый год заведует праздниками, а тут эти ребята сваливаются, как снег на голову. Они не входят в Хитрую Шестеренку, и картель наняла меня разобраться, что здесь к чему. Здесь просто невозможно дышать – и дело не только в духах.', '', '', 'Ты уже разобрался, что за \"ароматы\" витают в воздухе?', NULL, NULL, 'Исследовано надушенных стражников', 'Анализатор воздуха Гвоздезуба', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24541, 'Позаимствовать духи', 'Я так и знал, что дело здесь нечисто! Сюда добавлен какой-то химикат, влияющий на подсознание, но с тем количеством, которое у меня есть, хороший анализ не сделаешь. Мне нужно намного больше.', '', '', 'Они бросили тебе ящик для доставки?', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24545, 'Святость и скверна', 'Я дам тебе одно задание, $r, хоть это и противоречит моим убеждениям. Скорее всего ты не оправдаешь надежд.$B$BНо лучше забудь мои слова и посвяти все свои силы этому новому заданию. А я дам тебе необходимые знания и ресурсы. $B$BНайди Отмщение Света, молот, брошенный Артасом в Пещере Ледяной Скорби. Если усилить его саронитом и разъедающей кровью поганищ, он нам еще отлично послужит.', 'Поместите Отмщение Света, 25 кусков древнейшего саронита, разъедающую кровь Гниломорда и разъедающую кровь Тухлопуза в кузню рун Верховного лорда Могрейна в Цитадели Ледяной Короны.Разъедающую кровь Гниломорда и Тухлопуза можно получить в рейде для 25 игроков в Цитадели Ледяной Короны.', 'Когда вы погружаете предметы в огонь, вас охватывает непреодолимое чувство страха.', 'Когда вы подходите ближе, пламя кузни как будто начинает пылать еще яростней.', NULL, NULL, 'Отмщение Света', 'Древнейший саронит', 'Разъедающая кровь Тухлопуза', 'Разъедающая кровь Гниломорда');
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24547, 'Пиршество душ', 'Грань Тьмы – одно из самых могущественных орудий, которым может владеть $C. Теперь твоя жажда власти утолена?$B$B<Вы ощущаете на себе проницательный взгляд Верховного лорда.>$B$BЯ полагаю, что нет. В таком случае, вот мое последнее предупреждение...$B$BТы приступаешь к самой опасной части своей миссии. Обуздай свои желания, $r, ибо если твои устремления порочны, то душа твоя обречена.$B$BЭтот клинок – не более чем пустой сосуд, тень того, чем он может стать. Он откроет свою истинную силу лишь тогда, когда поглотит тысячу душ.', 'Верховный лорд Могрейн поручил вам убить 1000 слуг Короля-лича в Цитадели Ледяной Короны с помощью Грани Тьмы. Души будут засчитаны в рейде на 10 или 25 игроков.', '', NULL, NULL, NULL, 'Душ скормлено Грани Тьмы', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24549, 'Темная Скорбь...', '', 'Верховный лорд Могрейн просит вас принести ему Грань Тьмы.', 'Прими мои поздравления, $C.$B$BВсе было против тебя, но ты выстоял и получишь достойную награду.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24553, 'Очищение Кель\'Делара', 'Признаюсь, я сомневался в том, что тебе удалось перековать Кель\'Делар и что дух Талориена удостоит тебя вниманием. Ты не представляешь, что означает для меня и моего народа возвращение легендарного меча. $B$BКак и было обещано, я разрешаю тебе пройти к Солнечному Колодцу и встретиться с властителями Луносвета. Погрузи меч в Солнечный Колодец. После очищения его сила будет навеки связана с тобой. Затем отнеси меч Каладису Сияющему Копью в Покой Кель\'Делара.', 'Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.', '', NULL, NULL, NULL, 'Восстановленный Кель\'Делар', 'Оскверненный Кель\'Делар', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24554, 'Потертая рукоять', 'Эта потертая рукоять меча знавала лучшие дни, но даже сейчас по ней можно сказать, что делал ее настоящий мастер.$B$BИзящная гравировка и инкрустация драгоценными камнями свидетельствует о том, что оружие некогда принадлежало знатному человеку. Похитителей Солнца наверняка заинтересует эта находка. Найдите их представителя в Покое Кель\'Делара к югу от ристалища Серебряного Турнира.', 'Принесите потертую рукоять Миралию Блеску Солнца в Покой Кель\'Делара, что к югу от ристалища Серебряного Турнира.', '', NULL, NULL, NULL, 'Потертая рукоять (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24555, 'То, что знают драконы', 'Ошибки быть не может – это рукоять могущественного древнего клинка. Вот только что это был за клинок? Я не могу вспомнить ни одного меча с такой гравировкой, но не все еще потеряно.$B$BМы должны обратиться к Кориалстразу, более известному тебе как Крас. Он – давний друг кель\'дорай и Кирин-Тора. За его плечами мудрость рода красных драконов; наверняка, он сможет нам помочь. Отправляйся за его советом на вершину Храма Драконьего Покоя, после чего поговори с Магистром Хаторелем в даларанском Прибежище Похитителя Солнца.', 'Поговорите с Красом на вершине Храма Драконьего Покоя.', '', NULL, NULL, NULL, 'Спросить Краса о происхождении рукояти', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24556, 'Подходящая маскировка', 'Заслать тебя в Серебряный Анклав будет нелегко. Туда допускаются только обладатели гербовых накидок Серебряного союза. Если бы нам только удалось заполучить одну из них, остальное можно было бы решить с помощью пары заклинаний.$B$BНо у меня есть идея! На балконе над \"Нитями судьбы\" стоит некто Шанди Шикблеск. Я его пару раз выручал в прошлом, так что он задолжал мне ответную услугу. Он стирает одежду многих граждан этого города. Может быть, он согласится одолжить тебе гербовую накидку...', 'Позаимствуйте у Шанди Шикблеска гербовую накидку.', '', NULL, NULL, NULL, 'Позаимствованная гербовая накидка', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24557, 'Планы Серебряного союза', 'Один из моих шпионов в Клоаке заметил там посланника Серебряного союза, которые, как ты понимаешь, редко проявляют интерес к тому, что творится в канализации. А этот околачивался вокруг таверны \"Ведьма ворон\". Несомненно, они что-то затевают.$B$BОтправляйся в Клоаку, найди этого прихвостня Серебряного союза и разберись с ним. Обыщи его тело – может быть, у него найдется информация о местонахождении той книги из Храма Драконьего Покоя. Нельзя допустить, чтобы она оказалась в Ледяной Короне.', 'Перехватите приказы Серебряного союза.', '', NULL, NULL, NULL, 'Приказы Серебряного союза', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24558, 'Возвращение к Миралию Блеску Солнца', 'Эту книгу надо немедленно отнести Миралию Блеску Солнца. Ты этим займешься? Никому другому я не могу доверить столь ценную ношу, а ты уже $gдоказал:доказала: свою верность, обхитрив Серебряный союз.$B$BТвой путь лежит в Покой Кель\'Делара, что на юге от ристалища Серебряного Турнира в Ледяной Короне. Миралий будет ждать тебя вместе с мечом. Чем быстрее мы сможем распознать этот клинок, тем скорее сможем им овладеть и обратить против Короля-лича во имя Этаса Похитителя Солнца. Мы должны показать Даларану и Альянсу, кто достоин возглавить эту битву.', 'Принесите книгу \"Древние клинки драконьей ковки\" Миралию Блеску Солнца в Покой Кель\'Делара.', '', NULL, NULL, NULL, 'Древние клинки драконьей ковки (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24559, 'Перековать меч', 'Нельзя допустить, чтобы великий Кель\'Делар оставался расколотым и обесчещенным. Возьми фрагменты клинка вместе с потертой рукоятью и отправляйся в Яму Сарона, что в цитадели Ледяной Короны.$B$BВ этой яме слуги Короля-лича добывают и обрабатывают саронитовую руду. Только с помощью заряженного саронита можно перековать Кель\'Делар.$B$BТы $gдолжен:должна: собрать саронитовые слитки и перековать меч, вопользовавшись молотом и наковальней начальника кузни.', 'Возьмите 5 слитков зараженного саронита и молот начальника кузни, чтобы соединить фрагменты Кель\'Делара и создать перекованный Кель\'Делар.', '', NULL, NULL, NULL, 'Перекованный Кель\'Делар', 'Фрагменты Кель\'Делара', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24560, 'Закалить клинок', 'Наконец-то фрагменты Кель\'Делара воссоединились, и клинок снова стал целым. Но он еще не готов к битве, ибо для начала его надо закалить. Эти саронитовые зубцы очень хрупкие и могут отколоться в момент удара.$B$BНо глубоко под цитаделью Ледяной Короны есть Кузня Душ, в которой можно закалить подобный клинок. Отнеси Кель\'Делар в обитель Пожирателя Душ и найди там горнило душ. Закали меч и принеси его мне. Я буду ждать тебя в Ледяных залах.', 'Закалите перекованный Кель\'Делар в горниле душ.', '', NULL, NULL, NULL, 'Закаленный Кель\'Делар', 'Перекованный Кель\'Делар', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24561, 'Залы Отражений', 'Ты $gперековал и закалил:перековала и закалила: клинок, но я не чувствую в нем былой силы. Правильно ли я понял, что клинок побуждает тебя к действию, словно он обладает собственной волей?$B$BОсмелишься ли последовать его зову? Негоже великому мечу ржаветь в ножнах. Я боюсь, что мы никогда не узнаем его тайн, если не последуем велению его судьбы. Отнеси его в Залы Отражений, что в Цитадели Ледяной Короны, но будь $gготов:готова: ко всему. Я буду ждать тебя в Ледяных залах.', 'Отнесите Кель\'Делар в Покои Клинка, что в Залах Отражений.', '', NULL, NULL, NULL, 'Кель\'Делар доставлен в Залы Отражений', 'Укрощенный Кель\'Делар', 'Закаленный Кель\'Делар', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24562, 'Путешествие к Солнечному Колодцу', 'Как можно быстрее отнеси Кель\'Делар к Солнечному Колодцу! Мы должны поверить словам Утера о том, что оскверненный могуществом Короля-лича клинок не всегда будет тебе подвластен. Ты $gдолжен:должна: отправиться на Остров Кель\'Данас и найти вход в сам Солнечный Колодец. Только он обладает силой очистить меч.$B$BУчти, что стражники Солнечного Колодца не позволят тебе пройти без разрешения, поэтому тебе придется заручиться поддержкой Халдарона Светлого Крыла, начальника охраны.', 'Поговорите с Халдароном Светлым Крылом у входа на плато Солнечного Колодца на острове Кель\'Данас.', '', NULL, NULL, NULL, 'Закаленный Кель\'Делар (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24563, 'Талориен Искатель Рассвета', 'Ты ведь работаешь на Миралия Блеска Солнца, верно? Думаю, я знают способ испытать, что за клинок у тебя в руках. Полагаю, тебе известна история этого меча? Им владел Талориен Искатель Рассвета, что защищал Колодец от нашествия Плети. Талориен пал на том месте, что мы сейчас называем Тропой Мертвых. Ценой своей жизни он выиграл время, необходимое для того, чтобы его люди сумели подготовиться и встретить врага во всеоружии. Останки Талориена покоятся на этом острове в южном конце Тропы. Наведайся туда, и, если дух героя благословит тебя, я разрешу тебе пройти в Солнечный Колодец.', 'Наведайтесь к останкам Талориена Искателя Рассвета и получите его благословение на владение Кель\'Деларом.', '', NULL, NULL, NULL, 'Получено благословение Талориена', 'Закаленный Кель\'Делар (Прилагается)', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24576, 'Разговор по душам...', '<Рока с отвращением выслушивает, почему вы пытаетесь выследить Снивела.: $B$BТо есть, все это время я была под действием заклинания этого алхимика? Как я только могла купиться на эту подставу! Ну, попадись мне только этот маленький мерзавец – разорву на части!$B$BЕсли он закончил все свои дела, то должен направляться к башне дирижаблей, что на востоке от врат Оргриммара. $N, нельзя допустить, чтобы он поднялся на борт и улетел, избежав наказания!$B$BБеги к башне как можно быстрее!', 'Отправляйтесь к башне дирижаблей, что на востоке от врат Оргриммара, и допросите Снивела Ржавстера. Постарайтесь получить хоть какие-нибудь доказательства.', 'Ты принес его гроссбух? Отличная работа, $N. Здесь должна быть куча ценной информации!', 'Ты нашел этого парня – или он от тебя улизнул?', NULL, NULL, 'Гроссбух Снивела', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24579, 'Сартарион должен умереть!', 'Сартарион, Ониксовый страж, охраняет яйца сумеречных драконов. Он обитает в Обсидиановом святилище, в Драконьих чертогах под Храмом Драконьего Покоя.$B$BСовет Шести приговаривает Сартариона к смерти!', 'Убейте Сартариона.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', 'Теперь, когда Сартарион погиб, Смертокрылу и Зловестине придется пересмотреть свои планы.', NULL, NULL, NULL, 'Сартарион убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24580, 'Ануб\'Рекан должен умереть!', 'Ануб\'Рекан некогда был одним из сильнейших пауков-повелителей Неруба, но Королю-личу удалось захватить его и превратить в нежить.$B$BНыне владыка подземелий обитает в Паучьем квартале Наксрамаса, помогая Кел\'Тузаду строить зловещие планы.$B$BСовет Шести приговаривает Ануб\'Рекана к смерти!', 'Убейте Ануб\'Рекана.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', '', NULL, NULL, NULL, 'Ануб\'Рекан убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24581, 'Нот Чумной должен умереть!', 'Нот Чумной – трус и предатель! По количеству душ, обращенных на сторону Плети, он уступает только Королю-личу.$B$BПоторопись отправиться в Наксрамас. Ты найдешь Нота в Чумном квартале, где он прячется за спинами своих неживых слуг. $B$BУничтожь его, ибо Совет Шести приговорил Нота Чумного к смерти!', 'Убейте Нота Чумного.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', '', NULL, NULL, NULL, 'Нот Чумной убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24582, 'Инструктор Разувий должен умереть!', 'Инструктор Разувий напыщенно вышагивает по Военному кварталу Наксрамаса. Говорят, что только рыцарь смерти, лично обученный этим воином, может устоять против его меча.$B$BДокажи, что это не так. Совет Шести приговорил Разувия к смерти!', 'Убейте Инструктора Разувия.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', '', NULL, NULL, NULL, 'Инструктор Разувий убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24583, 'Лоскутик должен умереть!', 'Лоскутик, также известный как \"воплощение войны\", – самое совершенное из созданных Плетью поганищ. Он нанес огромный урон нашим войскам в Драконьем Погосте.$B$BСобери своих союзников и отправляйся в Квартал Мерзости Наксрамаса. Уничтожь это чудовище.$B$BСовет Шести приговорил Лоскутика к смерти!', 'Убейте Лоскутика.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', '', NULL, NULL, NULL, 'Лоскутик убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24584, 'Малигос должен умереть!', 'Наши ресурсы истощены. Малигос вытягивает магическую энергию из мира, дабы сконцентрировать ее в Оке Вечности. Без нее мы все обречены.$B$B$C, нужно положить конец войне Нексуса. Совет Шести приговаривает Малигоса к смерти!', 'Убейте Малигоса.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', '', NULL, NULL, NULL, 'Малигос убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24585, 'Огненный Левиафан должен умереть!', 'Первая линия обороны Ульдуара проходит через Плац: именно там несет караул Огненный Левиафан.$B$BДо Кирин-Тора дошла информация о том, что это творение Хранителей скоро переправят в неизвестное место, откуда он будет угрожать всем смертным Азерота.$B$BМы не можем позволить, чтобы это произошло. Совет Шести приговаривает Огненного Левиафана к смерти!', 'Убейте Огненного Левиафана.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', '', NULL, NULL, NULL, 'Огненный Левиафан убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24586, 'Острокрылая должна умереть!', 'Обычно Острокрылая не покидает пределов Гигантской кузни Ульдуара, но недавно ее видели за границами города $Nв. Она обрушивала огненный шквал на окрестные земли.$B$BСудьба праматери была нелегка, но сейчас она представляет угрозу всему Нордсколу. Совет Шести приговорил Острокрылую к смерти!', 'Убейте Острокрылую.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', '', NULL, NULL, NULL, 'Острокрылая убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24587, 'Повелитель горнов Игнис должен умереть!', 'Повелитель горнов Игнис, огненный великан, покинул пределы Гигантской кузни Ульдуара. По приказу Локена он создает орудия ужасающей силы.$B$BСовет Шести приговаривает Игниса к смерти!', 'Убейте Повелителя горнов Игниса.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', '', NULL, NULL, NULL, 'Повелитель Горнов Игнис убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24588, 'Разрушитель XT-002 должен умереть!', 'Другое странное творение Мимирона, Разрушитель XT-002, полагает, что он сын Хранителей. Но пусть тебя не обманывает его невинный вид. Это машина смерти!$B$BТы найдешь его на Мусорной свалке Ульдуара. Совет Шести приговорил Разрушителя к смерти!', 'Убейте Разрушителя XT-002.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', 'Величайшая слабость Ульдуара заключается в том, что его повелители слепо верят в механизмы, защищающие древний город.', NULL, NULL, NULL, 'Разрушитель XT-002 убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24589, 'Лорд Джараксус должен умереть!', 'Верховный маг Времиар предсказал ужасное событие, которое вскоре должно произойти. Некий глупый гном-чернокнижник вызовет эредарского повелителя Пылающего Легиона прямо во время Испытания крестоносца!$B$BБудь там, когда это случится, $C. Если лорд Джараксус получит свободу, он вновь откроет портал для войск Пылающего Легиона.$B$BСовет Шести приговорил Джараксуса к смерти!', 'Убейте лорда Джараксуса.Это задание можно выполнить на любом уровне сложности и любым составом рейда.', '', NULL, NULL, NULL, 'Лорд Джараксус убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24590, 'Лорд Ребрад должен умереть!', 'Лорд Ребрад – страж Ледяного Трона, стоящий у подножья Шпиля. Король-лич создал Ребрада из костей тысяч пропавших искателей приключений и вдохнул в него силу самого трона.$B$BЕсли мы не уничтожим это чудовищное костяное создание, нам никогда не захватить Цитадель Ледяной Короны.$B$BСовет Шести приговорил Ребрада к смерти!', 'Убейте Лорда Ребрада .Это задание можно выполнить на любом уровне сложности и любым составом рейда.', 'Благодаря тебе Ледяной Трон остался без своего верного стражника. Теперь мы сможем гораздо успешнее атаковать силы Короля-лича.', NULL, NULL, NULL, 'Лорд Ребрад убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24594, 'Очищение Кель\'Делара', 'Истекают часы изгнания Кель\'Делара. Тебя ждет Солнечный Колодец, $N.$B$BТам ты встретишь Лор\'темара Терона, регента Кель\'Таласа и Верховного магистра Роммата. Будь $gосторожен:осторожна: с ними, не давай вовлечь себя в политические махинации.$B$BСосредоточься на своей миссии. Когда ты будешь $gготов:готова: завершить восстановление Кель\'Делара, поговори с хранителем Солнечного Колодца. Окуни меч в Солнечный Колодец, а затем отнеси его Миралию Блеску Солнца в Покой Кель\'Делара.', 'Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.', '', NULL, NULL, NULL, 'Восстановленный Кель\'Делар', 'Оскверненный Кель\'Делар', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24597, 'Дар королю Штормграда', 'Хочешь создать чудесный браслет-оберег для короля Штормграда? Он будет в восторге.$B$BА у тебя есть набор собирателя прелестных оберегов?', 'Подарите чудесный браслет-оберег королю Штормграда Вариану Ринну.', 'Спасибо тебе за этот чудесный браслет-оберег.', 'Здравствуй, $C. Что это у тебя?', NULL, NULL, 'Чудесный браслет-оберег', 'Набор собирателя чудесных оберегов', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24598, 'Очищение Кель\'Делара', 'Истекают часы изгнания Кель\'Делара. Тебя ждет Солнечный Колодец, $N.$B$BТам ты встретишь Лор\'темара Терона, регента Кель\'Таласа и Верховного магистра Роммата. Будь $gосторожен:осторожна: с ними, не давай вовлечь себя в политические махинации.$B$BСосредоточься на своей миссии. Когда ты будешь $gготов:готова: завершить восстановление Кель\'Делара, поговори с хранителем Солнечного Колодца. Окуни меч в Солнечный Колодец, а затем отнеси его Миралию Блеску Солнца в Покой Кель\'Делара.', 'Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.', '', NULL, NULL, NULL, 'Восстановленный Кель\'Делар', 'Оскверненный Кель\'Делар', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24609, 'Дар повелителю Стальгорна', 'Хочешь создать чудесный браслет-оберег для короля Стальгорна? Он будет в восторге.$B$BА у тебя есть набор собирателя прелестных оберегов?', 'Подарите чудесный браслет-оберег королю Стальгорна Магни Бронзобороду.', 'Спасибо тебе за этот чудесный браслет-оберег.', 'Здравствуй, $C. Что это у тебя?', NULL, NULL, 'Чудесный браслет-оберег', 'Набор собирателя чудесных оберегов', NULL, NULL);
