INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24629, 'Легкий аромат духов', 'Похоже, ты умеешь делать деньги, $C. Как насчет одного беспроигрышного дельца?$B$BКоролевская компания хочет предложить образцы новых праздничных изделий как можно большему числу потенциальных клиентов. Помоги нам сеять любовь – а взамен получишь хорошую скидку на продукцию Королевской компании!$B$BВремя – деньги, дружище! Что скажешь?', 'Опрыскайте десять прохожих из флакончика духов королевской компании с распылителем.', 'Отличная работа, $N! Теперь за нашими духами целая очередь выстроится – раз уж клиенты успели опробовать их эффект.$B$BВот, держи небольшое вознаграждение за помощь.', NULL, NULL, NULL, 'Образцов роздано', 'Флакончик духов королевской компании с распылителем', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24635, 'Легкий аромат одеколона', 'Кажется, ты знаешь, как вести дела, $C. Как насчет небольшой сделки?$B$BКоролевская компания хочет предложить образцы новых праздничных изделий как можно большему числу потенциальных клиентов. Помоги нам сеять любовь – а взамен получишь хорошую скидку на продукцию Королевской компании!$B$BВремя – деньги, дружище! Что скажешь?', 'Опрыскайте десять прохожих из флакончика одеколона королевской компании с распылителем.', 'Отличная работа, $N! Теперь наши одеколоны будут ящиками покупать – раз уж клиенты успели опробовать их эффект.$B$BВот, держи небольшое вознаграждение за помощь.', 'Этот одеколон сам собой не распылится, $C.$B$BЗа работу!', NULL, NULL, 'Образцов роздано', 'Флакончик одеколона королевской компании с распылителем', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24636, 'Вкус конфет', 'Гляжу, у тебя есть предпринимательская хватка, $C. Не хочешь заработать немного звонких монет с моей помощью?$B$BКоролевская компания хочет предложить образцы новых праздничных изделий как можно большему числу потенциальных клиентов. Помоги нам сеять любовь – а взамен получишь хорошую скидку на продукцию Королевской компании!$B$BВремя – деньги, дружище! Что скажешь?', 'Раздайте десяти прохожим кусочки королевского шоколада.', 'Отличная работа, $N! Теперь клиенты будут драться за наши шоколадки – раз уж они успели оценить их изумительно нежный, сладкий вкус.$B$BВот, держи небольшое вознаграждение за помощь.', 'Знаешь, эти шоколадки сами собой не разлетятся.$B$BЗа работу!', NULL, NULL, 'Образцов роздано', 'Кусочек королевского шоколада', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24638, 'Конец Королевской компании', 'В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга: должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$B$BВот запись, которая меня особенно волнует: в ней говорится о месте за вратами Оргриммара, на западе! Не нравится меня это. Иди туда и разберись.$B$BДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', 'Убейте 5 служащих химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами к западу от врат Оргриммара в Дуротаре. После этого вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.', '', NULL, NULL, NULL, 'Повозка с химикатами уничтожена', NULL, 'Кориевая бомба Гвоздезуба', NULL);
