INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24650, 'Конец Королевской компании', 'В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга: должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$B$BВот запись, которая меня особенно волнует: в ней говорится о месте в Зимних ключах, к востоку от Круговзора! А вот это уже серьезно. Иди туда и разберись.$B$BДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', 'Убейте 5 окропителей химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами в Зимних ключах, к востоку от Круговзора. После этого вернитесь к детективу в Оргриммар.', '', NULL, NULL, NULL, 'Повозка с химикатами уничтожена', NULL, 'Кориевая бомба Гвоздезуба', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24651, 'Конец Королевской компании', 'В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга: должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$B$BВот запись, которая меня особенно волнует: в ней говорится о месте к востоку от Шаттрата, в лесу Тероккар! Иди туда и разберись.$B$BДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', 'Убейте 5 стажеров химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами к востоку от Шаттрата, в лесу Тероккар. После этого вернитесь к детективу в Оргриммар.', '', NULL, NULL, NULL, 'Повозка с химикатами уничтожена', NULL, 'Кориевая бомба Гвоздезуба', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24652, 'Конец Королевской компании', 'В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга: должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$B$BВот запись, которая меня особенно волнует: в ней говорится о месте в Опустевших лесах Хрустальной Песни, что к северо-западу от Зеркала Сумерек! Иди туда и разберись.$B$BДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', 'Убейте 5 распылителей химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами в Опустевших лесах Хрустальной Песни, что к северо-западу от Зеркала Сумерек. После этого вернитесь к детективу в Оргриммар.', 'Отличная работа, малыш. Ты заслуживаешь небольшой награды. Загляни ко мне завтра – вдруг у меня найдется еще какое-нибудь поручение для тебя.', NULL, NULL, NULL, 'Повозка с химикатами уничтожена', 'Распылитель химической компании убито', 'Кориевая бомба Гвоздезуба', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24655, 'Дышать нечем!', 'Присмотрись к этим ребятам. Хитрая Шестеренка уже не первый год заведует праздниками, а тут эти ребята сваливаются, как снег на голову. Они не входят в Хитрую Шестеренку, и картель наняла меня разобраться, что здесь к чему. Здесь пахнет жареным – и пахнет этим от духов.', '', '', NULL, NULL, NULL, 'Исследовано надушенных стражников', 'Анализатор воздуха Гвоздезуба', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24656, 'Позаимствовать духи', 'Я так и знал, что дело здесь нечисто! Сюда добавлен какой-то химикат, влияющий на подсознание, но с тем количеством, которое у меня есть, хороший анализ не сделаешь. Мне нужно намного больше.', '', '', 'Они бросили тебе ящик для доставки?', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24657, 'Разговор по душам...', '$gМарион с отвращением выслушивает, почему вы пытаетесь выследить Снивела.: $B$BХочешь сказать, он опрыскал меня каким-то химикатом? Фу! Как я только могла купиться на эту подставу!$B$BЕсли он закончил все свои дела, то должен направляться к докам, чтобы сесть на корабль, отправляющийся в Южные моря. $N, нельзя допустить, чтобы он поднялся на борт и уплыл, избежав наказания!$B$BБеги в Порт Штормграда как можно быстрее!', 'Отправляйтесь в Порт Штормграда и допросите Снивела Ржавстера. Постарайтесь получить хоть какие-нибудь доказательства.', 'Ты принес его гроссбух? Отличная работа, $N. Здесь должна быть куча ценной информации!', 'Ты нашел этого парня – или он от тебя улизнул?', NULL, NULL, 'Гроссбух Снивела', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24658, 'Конец Королевской компании', 'В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга: должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$B$BВот запись, которая меня особенно волнует: в ней говорится о месте к северо-востоку от Гарнизона у Западного ручья, что за пределами Элвиннского леса! Не нравится мне это. Иди туда и разберись.$B$BДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', 'Убейте 5 служащих химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами к северо-востоку от Гарнизона у Западного ручья, что за пределами Элвинна. После этого вернитесь к инспектору в Штормград.', '', NULL, NULL, NULL, 'Повозка с химикатами уничтожена', NULL, 'Кориевая бомба Гвоздезуба', NULL);
