INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24666, 'Конец Королевской компании', 'В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга: должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$B$BВот запись, которая меня особенно волнует: в ней говорится о месте в Опустевших лесах Хрустальной Песни, что к северо-западу от Зеркала Сумерек! Иди туда и разберись.$B$BДа, если увидишь что-то большое и опасное – брось в него эту бомбу.', 'Убейте 5 распылителей химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами в Опустевших лесах Хрустальной Песни, что к северо-западу от Зеркала Сумерек. После этого вернитесь к инспектору в Штормград.', 'Отличная работа, малыш. Ты заслуживаешь небольшой награды. Загляни ко мне завтра – вдруг у меня найдется еще какое-нибудь поручение для тебя.', 'Ты их проучил?', NULL, NULL, 'Повозка с химикатами уничтожена', 'Распылитель химической компании убито', 'Кориевая бомба Гвоздезуба', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24682, 'Яма Сарона', 'Быстрее, шагай в портал! Я присоединюсь к тебе позже.', 'Встретьтесь с леди Сильваной Ветрокрылой на входе в Яму Сарона.', 'Жалкие идиоты. Я уже начинаю сомневаться, что эти турнирные крысы способны хоть чем-то мне помочь. Надеюсь, ты не из их числа?', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24683, 'Яма Сарона', 'Быстрее, шагай в портал! Я присоединюсь к тебе позже.', 'Встретьтесь с леди Джайной Праудмур в Яме Сарона.', 'Я недооценила этого Повелителя Плети и расплатилась за свою ошибку жизнями людей. Каждый раз, когда я думаю, что не могу больше усугубить свою вину, приведшую к предательству Артаса, жизнь показывает, что это не так.$B$BНо мы не должны сдаваться! Нельзя допустить, чтобы эти смерти оказались бессмысленными.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24710, 'Зачистка Ямы', 'Чтобы добраться до обители Тирания, нам нужно будет подняться по главной тропе и пройти через пещеру. Тогда он будет вынужден принять бой, чтобы защитить проход к цитадели.$B$BИди же, $C. Мои люди помогут тебе, когда настает час битвы с Тиранием.', 'Убейте Повелителя Плети Тирания.', 'Какая бессмысленная утрата! Артас зашел слишком далеко. Остается только надеяться, что наш поход в Залы Отражений окупит нашу потерю.$B$BЕсли верить словам этого злобного гнома, там мы найдем Ледяную Скорбь, оружие которое поможет нам одолеть Артаса.', NULL, NULL, NULL, 'Повелитель Плети Тираний убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24711, 'Ледяная Скорбь', 'Мы не можем отступить сейчас, герой. Мы далеко зашли... почти приблизились к цели. Я покину тебя ненадолго, чтобы отправить Эландру обратно на воздушный корабль. Не знаю, как мы сможем вернуться назад, потеряв столько бойцов – сейчас нам пригодится любая помощь.$B$BПродолжай наше дело. Я присоединюсь к тебе в Залах Отражений.', 'Встретьтесь с леди Джайной Праудмур у входа в Залы Отражений.', 'Залы Отражений... Наконец-то.$B$BДай мне знать, когда будешь готов идти дальше. Возможно, Артаса там нет, но я не стала бы надеяться на то, что он оставит Ледяную Скорбь без должной охраны.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24743, 'Грань Тьмы', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24745, 'Не любовь витает в воздухе (а что-то иное!)', 'Оборотная сторона открытки исчерчена подробными и зловещими планами по заражению всего Азерота. Вы должны немедленно отнести ее одному из следователей Хитрой Шестеренки!', 'Принесите выцветшую открытку ко дню всех влюбленных инспектору Кромсу Гвоздезубу в Штормград.', 'Что это тут у нас?$B$BОго, это уже серьезно. Очень серьезно. Целая куча головоломных деталей в одной упаковке. Спасибо, ты очень помог нам в расследовании. Приятно было работать с тобой.', 'Ты позаботился об этих коварных злодеях?', NULL, NULL, 'Выцветшая открытка ко дню всех влюбленных (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24748, 'Последняя битва Короля-лича', 'Клинок Темной Скорби еще не успел остыть после ковки, но он уже стал частью истории этого мира как оружие неповторимой судьбы.$B$BПриняв его, ты возлагаешь на себя огро$Nю ответственность, и теперь тебе настало время совершить то, что предназначено.$B$BВозьми это оружие, выкованное из легенд и мифов, и отправляйся на бой с врагом. Отомсти за тысячи душ, погубленных за все время этой жестокой войны. Пусть они наконец-то обретут покой.$B$BОбрети мужество, $C, и веди Те$Nю Скорбь по дороге судьбы.', 'Верховный лорд Дарион Могрейн приказал вам убить Короля-лича.', 'Свершилось...$B$BПусть же навеки запомнят жители Азерота наши деяния. Пусть в сердцах их вечно горят жертвенные костры в память о тех, кто погиб на поле боя. И пусть никогда больше не коснется их смертельная опасность перед лицом великого зла.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24749, 'Сила нечестивости', 'Чтобы раскрыть истинный потенциал оружия, тебе придется наполнить клинок положенными ему силами, и прежде всего – нечестивостью.$B$BНайди и убей существо, зовущееся профессором Мерзоцидом... Впрочем, одной его смертью ты не добьешься своей цели. Тебе придется использовать его средства против него самого.$B$BНайди способ поглотить его мутривавшую слизь. Используй эту мерзостную субстанцию, чтобы наполнить оружие силой нечестивости. Если ты справишься с этим заданием, я скажу тебе, что делать дальше.', 'Верховный лорд Дарион Могрейн приказал вам наполнить Грань Тьмы силой нечестивости и убить профессора Мерзоцида.Это задание можно выполнить только в рейде для 25 игроков в Цитадели Ледяной Короны.', '', NULL, NULL, NULL, 'Наполните Грань Тьмы силой нечестивости и убейте профессора Мерзоцида.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24756, 'Сила крови', 'Итак, твое оружие готово к тому, чтобы его наделили силой крови.$B$BТебе предстоит сразиться с королевой Лана\'тель, ибо только так ты сможешь попасть под влияние ее Кровавого зеркала. С помощью этой силы Грань Тьмы выпьет кровь ближайшего живого существа – тебя, $r.$B$BКогда меч пробудится, поддайся бешеной кровожадности, которую насылает королева, и используй обретенную силу, чтобы убить ее.$B$BПусть ее крики дойдут до самого Короля-лича, и в ее предсмертном вопле он услышит свой приговор.', 'Верховный лорд Дарион Могрейн приказал вам наполнить Грань Тьмы силой крови и убить королеву Лана\'тель.Это задание можно выполнить только в рейде для 25 игроков в Цитадели Ледяной Короны.', '', NULL, NULL, NULL, 'Наполните Грань Тьмы силой крови и убейте Лана\'тель.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24757, 'Сила льда', 'Теперь Грань Тьмы готова впитать последний глоток силы.$B$BРади этого умрет Синдрагоса, что прогибает спину под самим Королем-личом. Но прежде чем она падет, тебе придется пережить четыре ее ледяных вздоха.$B$BПосле смерти Синдрагосы ничто не будет стоять между тобой и Королем-личом.', 'Верховный лорд Дарион Могрейн приказал вам четыре раза попасть под действие ледяного дыхания Синдрагосы, держа при себе Грань Тьмы, после чего убить дракона.Это задание можно выполнить только в рейде для 25 игроков в Цитадели Ледяной Короны.', '', NULL, NULL, NULL, 'Наполните Грань Тьмы силой льда и убейте Синдрагосу.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24792, 'Засланный шпион', 'Кажется мне, что ты вполне можешь стать во главе этой операции. В журнале сказано, что он скрывается в Крепости Темного Клыка, и именно туда я намереваюсь тебя послать.$B$BОдин из наших людей уже проделал этот путь, но он недостаточно силен, чтобы закончить начатое. Иди же и встреться со следователем – да не забудь прихватить с собой друзей!', 'Найдите следователя Феззена Клейстра в Крепости Темного Клыка.', 'Потрясающе! Мне как раз нужна помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24793, 'Засланный шпион', 'Кажется мне, что ты вполне можешь стать во главе этой операции. В журнале сказано, что он скрывается в Крепости Темного Клыка, и именно туда я намереваюсь тебя послать.$B$BОдин из наших людей уже проделал этот путь, но он недостаточно силен, чтобы закончить начатое. Иди же и встреться со следователем – да не забудь прихватить с собой друзей!', 'Найдите следователя Феззена Клейстра в Крепости Темного Клыка.', 'Потрясающе! Мне как раз нужна помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24800, 'Победа Похитителей Солнца', 'Наконец-то Кель\'Делар восстановлен во славу всех Похитителей Солнца и величайшей расы син\'дорай!$B$BОтныне ты – $gгерой:героиня: Луносвета и всей Орды, $N.$B$BВерховный маг Этас Похититель Солнца, предводитель Похитителей Солнца, просил о встрече с тобой после того, как ты вернешься из Солнечного Колодца. Захвати с собой Кель\'Делар и отправляйся в Аметистовую цитадель Даларана как можно быстрее. Полагаю, Верховный маг желает лично тебя поздравить!', 'Принесите восстановленный Кель\'Делар Верховному магу Этасу Похитителю Солнца в Аметистовую цитадель Даларана.', '', NULL, NULL, NULL, 'Восстановленный Кель\'Делар (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24802, 'Гнев Короля-лича', 'Утер многое знал о том, как победить Артаса. Трудно поверить, что нанести ему поражение можно лишь на ступенях его собственного трона. Но кто примет корону Короля-лича, если до этого дойдет дело?$B$BТак много вопросов, и каждый ответ может сыграть решающую роль. Найди Сильвану и спасись от Короля-лича, пока еще есть время.', 'Найдите леди Сильвану Ветрокрылую и выберитесь из Залов Отражений.', 'И снова мою месть пришлось отложить. Не могу поверить, что он стал еще сильнее с момента нашей последней встречи!$B$BГлупо с твоей стороны было возвращаться за мной, хотя мне приятно знать, что среди чемпионов Орды есть не одни только жалкие трусы. Информация, полученная мной от Утера, может помочь уничтожить Артаса, хотя теперь мне совершенно ясно, что Орда не справится с этим делом в одиночку.$B$BИди, $C. Твоя помощь мне вскоре понадобится.', NULL, NULL, NULL, 'Сильвана Ветрокрылая найдена', 'Побег от Короля-лича удался', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24803, 'Калуакское рыбоборье', '', '', '', NULL, NULL, NULL, 'Черная акула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24804, 'Необычные ароматы', 'Не нравится мне эта Королевская химическая компания... Ребята из Хитрой Шестеренки давно уже присматривают за ними, и им бы не помешала помощь.$B$BИди в Штормград, если хочешь принять участие в этом деле. Расследование возглавляет инспектор Кромс Гвоздезуб, и ему пригодятся толковые помощники.', 'Отчитайтесь перед инспектором Кромсом Гвоздезубом в Штормграде.', 'Привет! У тебя найдется для меня время? Мне бы пригодилась твоя помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24805, 'Необычные ароматы', 'Не нравится мне эта Королевская химическая компания... Ребята из Хитрой Шестеренки давно уже присматривают за ними, и им бы не помешала помощь.$B$BИди в Оргриммар, если хочешь принять участие в этом деле. Расследование возглавляет детектив Крямс Гвоздезуб, и ему пригодятся толковые помощники.', 'Отчитайтесь перед детективом Крямсом Гвоздезубом в Оргриммаре.', 'Привет! У тебя найдется для меня время? Мне бы пригодилась твоя помощь.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24806, 'Пусть тебе улыбнется удача – в другой раз!', '', '', '', NULL, NULL, NULL, 'Черная акула', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24815, 'Выбери свой путь', '', '', 'Чтобы искупить грехи, совершенные мной в качестве одного из рыцарей смерти Короля-лича, я посвятил свою жизнь изготовлению колец, наполненных великой силой. Пусть они помогут нашим братьям и сестрам в грядущей битве.Ты проявил себя как преданный союзник в борьбе с Плетью, потому специально тебя я могу сделать особенное предложение.Пусть твой выбор будет мудрым и обдуманным – перемены в душе не происходят просто так.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24819, 'Перемены в душе', '', '', '', NULL, NULL, NULL, 'Пепельное кольцо разрушения', 'Требуется денег: 200', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24820, 'Перемены в душе', '', '', '', NULL, NULL, NULL, 'Пепельное кольцо отмщения', 'Требуется денег: 200', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24821, 'Перемены в душе', '', '', '', NULL, NULL, NULL, 'Пепельное кольцо отваги', 'Требуется денег: 200', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24822, 'Перемены в душе', '', '', '', NULL, NULL, NULL, 'Пепельное кольцо мудрости', 'Требуется денег: 200', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24823, 'Путь разрушения', '', 'Ты желаешь и дальше идти путем разрушения?', 'Ты по-прежнему отважно сражаешься на нашей стороне, $N. Прими это кольцо не как дар, но как оружие в войне против Плети.', NULL, NULL, NULL, 'Пепельное кольцо великого разрушения', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24825, 'Путь мудрости', '', 'Ты желаешь и дальше идти путем мудрости?', 'Ты по-прежнему отважно сражаешься на нашей стороне, Ацкаяпалка. Прими это кольцо не как дар, но как оружие в войне против Плети.', NULL, NULL, NULL, 'Пепельное кольцо мудрости', NULL, NULL, NULL);
