INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24829, '', '', 'Ты желаешь и дальше идти путем разрушения?', 'Ты настоящий герой, сражающийся за правое дело, $N. Мало кто может сравниться с тобой на поле боя.$B$BВраги произносят твое имя испуганным шепотом, ибо знают, что с тобой нельзя не считаться.$B$BПрими этот скромный дар в благодарность за свершенные подвиги.', NULL, NULL, NULL, 'Пепельное кольцо непревзойденного разрушения', NULL, NULL, NULL);
