INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24848, 'Фейерверки в \"Позолоченной розе\"', '$gМалыш:Малышка:, это не просто дурно пахнет. В этом ящике хранились ракеты, начиненные каким-то химическим реактивом. Я не могу определить на месте, что это было, но и в лабораторию тебе бежать не придется.', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24849, 'По горячим следам', 'Это долгая история, $N. Я влюбилась в него с первого взгляда... понимаешь, было в этом гоблине что-то такое, особенное, что я глаз от него не могла отвести.$B$BМы провели вместе целую неделю, а потом Снивел сказал, что получил кучу денег, и потому берет меня с собой на отдых в Южных морях! Представляешь?$B$BВ общем, он велел мне собирать вещи, пока он улаживает кое-какие дела. Он собирался только зайти в банк, аукционный дом и парикмахерскую, но так и не вернулся! Я уже начинаю думать, что меня попросту обманули...', 'Поищите Снивела Ржавстера в счетной палате Штормграда, аукционном доме и парикмахерской.', 'Он говорил только о том, как смыться из города со всеми деньгами? Значит, он действительно меня бросил...$B$BАх, $N, как глупо было поверить его обещаниям, но я не могла удержаться. Он был таким обольстительным!', 'Ты его нашел?', NULL, NULL, 'Счетная палата Штормграда обыскана', 'Аукционный дом Штормграда обыскан', 'Парикмахерская Штормграда обыскана', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24850, 'Возлюбленная Ржавстера', '$gМалыш:Малышка:, это не просто дурно пахнет. В этом ящике хранились ракеты, начиненные каким-то химическим реактивом. Я не могу определить на месте, что это было, но и в лабораторию тебе бежать не придется.', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24851, 'По горячим следам', 'Это долгая история, $N. Я влюбилась в него с первого взгляда... понимаешь, было в этом гоблине что-то такое, особенное, что я глаз от него не могла отвести.$B$BМы провели вместе целую неделю, а потом Снивел сказал, что получил кучу денег, и потому берет меня с собой на отдых в Южных морях! Представляешь?$B$BВ общем, он велел мне собирать вещи, пока он улаживает кое-какие дела. Он собирался только зайти в банк, аукционный дом и парикмахерскую, но так и не вернулся! Я уже начинаю думать, что меня попросту обманули...', 'Поищите Снивела Ржавстера в банке Оргриммара, аукционном доме и парикмахерской.', 'Он говорил только о том, как смыться из города со всеми деньгами? Значит, он действительно меня бросил...$B$BАх, Профессия, как глупо было попасться на удочку этому мерзкому гоблину. Но он был таким обольстительным при нашей первой встрече!', 'Ты его нашел?', NULL, NULL, 'Банк Оргриммара обыскан', 'Аукционный дом Оргриммара обыскан', 'Парикмахерская Оргриммара обыскана', NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24857, 'Нападение на Лагерь Нараче', 'Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения племени Дыбогривов на Лагерь Нараче. $B$BВождь Соколиный Ветер непременно должен об этом узнать!', 'Отнесите план нападения племени Дыбогривов вождю Соколиному Ветру в Лагерь Нараче.', 'Это и в самом деле тревожные новости! Но, зная об этих коварных планах, мы сможем призвать своих сородичей из Деревни Кровавого Копыта и отразить атаку. Сегодня ты спас жизни многих тауренов, $N!', 'Ты чем-то обеспокоен, $N? Какую весть ты принес?', NULL, NULL, 'План нападения племени Дыбогривов (Прилагается)', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24869, 'Перевербовка', 'Мы планировали заслать агента в Культ Проклятых, чтобы получить возможность следить за действиями Короля-лича напрямую, но мы… недооценили силу Артаса и его приближенной, Леди Смертный Шепот.$B$BВ итоге, один из наших людей, Дарнаван, был обращен на их сторону.$B$BЕсли ты собираешься расчистить путь в молельню, прошу тебя, поищи Дарнавана. Если тебе удастся вернуть его живым, мы постараемся устранить последствия промывки мозгов.', 'Убейте Леди Смертный Шепот, сохранив жизнь Дарнавану.', 'Спасибо тебе, Ляруж!$B$BЯ в неоплатном долгу перед тобой за спасение друга, которого мы все считали навсегда потерянным в паутине Культа Проклятых. А Серебряный Авангард должен поблагодарить тебя за бесценные сведения, добытые Дарнаваном за то время, которое он провел в стенах Цитадели.$B$BПрошу тебя, прими это в знак нашей признательности, и пусть Свет озаряет твой путь, куда бы тебе не пришлось идти.', NULL, NULL, NULL, 'Дарнаван спасен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24870, 'Оборона Черепного вала', 'Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Альянса кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.', 'Убейте гниющего ледяного великана.', 'Великан мертв? Слава Орде!$B$BСкоро путь будет расчищен. В знак благодарности прими эти военные трофеи – и я с нетерпением буду ждать того дня, когда мы сможем выпить за разрушение Ледяного Трона!', NULL, NULL, NULL, 'Гниющий ледяной великан убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24873, 'Болезненная задача', 'Профессор Мерзоцид прячется в своей поганой лаборатории, ставит опыты и выводит все более и более смертоносные штаммы порчи, которыми он планирует заразить всех нас. Если только мы сможем получить чистые образцы этих токсинов, наши исследователи немедленно приступят к изготовлению противоядия, которое спасет множество жизней.$B$BНо есть одна проблема – для того, чтобы получить требуемый образец, надо заразить живое существо двумя активными штаммами. Но если вдруг тебе... не посчастливится... стать носителем этой заразы, немедленно возвращайся сюда, чтобы мы могли поставить на тебе опыты.', 'Если вы заразитесь оранжевой и зеленой порчей, вернитесь к алхимику Адрианне.', 'Наконец-то у нас есть образец для изучения! Сегодня ты спасла бесчисленное множество жизней, Ашали.$B$BПрошу, прими это в благодарность за твое великое деяние.', 'Профессор Мерзоцид – самая большая угроза для нас со стороны Плети.', NULL, NULL, 'Заразитесь двумя видами порчи.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24874, 'Каждая капля крови...', 'Эти проклятые кровопийцы Плети, что именуют себя Сан\'лейн... у меня от них мурашки по коже. За ними следил один из наших лучших агентов, но сегодня утром с ним случилась беда – он попал в плен. Теперь его допрашивает сама Королева, и его крики эхом разносятся по Багровым залам. Пожалуйста, спаси его, пока еще не поздно!', 'Спасите разведчика Минчара прежде, чем его казнят.', 'Фух! Я уж думал, что мне конец. Представляешь, я услышал о каком-то ритуале воскрешения, проходящем в этих залах, но когда я попытался взглянуть поближе, один из этих проклятых вампиров меня учуял. Они привязали меня здесь и принялись вытягивать мою жизненную энергию в надежде, что я выдам планы нападения. Можно подумать, Тирион доверяет мне такие сведения!$B$BПрими эти военные трофеи в благодарность за спасение моей жизни.', NULL, NULL, NULL, 'Минчар спасен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24876, 'Оборона Черепного вала', 'Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Орды кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.', 'Убейте гниющего ледяного великана.', 'Великан мертв? Слава Свету!$B$BСкоро путь будет расчищен. В знак благодарности прими эти военные трофеи – и я с нетерпением буду ждать того дня, когда мы сможем выпить за разрушение Ледяного Трона!', NULL, NULL, NULL, 'Гниющий ледяной великан убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24877, 'Оборона Черепного вала', 'Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Альянса кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.', 'Убейте гниющего ледяного великана.', 'Великан мертв? Слава Орде!$B$BСкоро путь будет расчищен. В знак благодарности прими эти военные трофеи – и я с нетерпением буду ждать того дня, когда мы сможем выпить за разрушение Ледяного Трона!', NULL, NULL, NULL, 'Гниющий ледяной великан убито', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24878, 'Болезненная задача', 'Профессор Мерзоцид прячется в своей поганой лаборатории, ставит опыты и выводит все более и более смертоносные штаммы порчи, которыми он планирует заразить всех нас. Если только мы сможем получить чистые образцы этих токсинов, наши исследователи немедленно приступят к изготовлению противоядия, которое спасет множество жизней.$B$BНо есть одна проблема – для того, чтобы получить требуемый образец, надо заразить живое существо двумя активными штаммами. Но если вдруг тебе... не посчастливится... стать носителем этой заразы, немедленно возвращайся сюда, чтобы мы могли поставить на тебе опыты.', 'Если вы заразитесь оранжевой и зеленой порчей, вернитесь к алхимику Адрианне.', 'Наконец-то у нас есть образец для изучения! Сегодня ты спасла бесчисленное множество жизней, $N.$B$BПрошу, прими это в благодарность за твое великое деяние.', NULL, NULL, NULL, 'Заразитесь двумя видами порчи.', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24879, 'Каждая капля крови...', 'Эти проклятые кровопийцы Плети, что именуют себя Сан\'лейн... у меня от них мурашки по коже. За ними следил один из наших лучших агентов, но сегодня утром с ним случилась беда – он попал в плен. Теперь его допрашивает сама Королева, и его крики эхом разносятся по Багровым залам. Пожалуйста, спаси его, пока еще не поздно!', 'Спасите разведчика Минчара прежде, чем его казнят.', 'Фух! Я уж думал, что мне конец. Представляешь, я услышал о каком-то ритуале воскрешения, проходящем в этих залах, но когда я попытался взглянуть поближе, один из этих проклятых вампиров меня учуял. Они привязали меня здесь и принялись вытягивать мою жизненную энергию в надежде, что я выдам планы нападения. Можно подумать, Тирион доверяет мне такие сведения!$B$BПрими эти военные трофеи в благодарность за спасение моей жизни.', NULL, NULL, NULL, 'Минчар спасен', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24880, 'Отдых для измученной души', 'Я прошу тебя и твоих спутников взять эти Кристаллы жизни. В них заключена великая сила Святилища драконов из Драконьего Погоста. Знай же, что только с их помощью мне так долго удавалось оградить это место от влияния темной магии. $B$BБрось вызов Синдрагосе, и когда силы ее истощатся в бою, четыре твоих спутника смогут активировать кристаллы, чтобы вытянуть покоящуюся внутри нее сущность. Если затем ты одержишь победу, ты сможешь вернуть ее душу в Святилище драконов.', 'Воспользуйтесь кристаллами жизни, чтобы сохранить душу Синдрагосы.', '<Калесгос вздыхает>$B$BСколько смертей, сколько разрушений... Тяжелые времена наступили для моих братьев и сестер. Но благодаря вам, благородные искатели приключений, одна благородная, хоть и затронутая порчей душа обретет покой.$B$BСпи спокойно, Синдрагоса. Ты вернулась домой...', 'Что у тебя в руках, смертный?', NULL, NULL, 'Хрустальная сущность Синдрагосы', 'Пульсирующий кристалл жизни', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24912, 'Великая сила', '', '<Верховный лорд Дарион Могрейн с настойчивостью обращается к вам.>Грань Тьмы впитала нужную силу.Настал час перековать этот топор в Те$Nю Скорбь...', 'Будь осторожен, $C.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24914, 'Личное имущество', 'На ящике не видно ни петель, ни замка. Если бы не шум перекатывающихся внутри предметов, его вполне можно было бы принять за цельный кусок металла. $B$BЕдинственным, кто смог бы его открыть, является верховный лорд Могрейн.', 'Отнесите запечатанный сундук верховному лорду Дариону Могрейну в цитадель Ледяной Короны.', '<После начертания замысловатого узора из рун на каждой стороне ящичка проявились границы крышки и звук щелчка эхом разнесся по помещению.>$B$BВот, держи.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24915, 'Воссоединение Могрейна', '', 'Что это у тебя, $C? Во мне пробуждаются чувства, которые, я думал, уже давно мертвы.', 'Невероятно… $B$BОтец, это ты?!$B$BТы совершил поистине великое дело, Рунаак. За это я готов вверить тебе поводья моего верного скакуна. Распоряжайся им по своему усмотрению, но не забывай тех, кто помог тебе совершить этот подвиг.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24916, 'Медальон Джайны', '', 'Чем я могу помочь тебе, $C?', 'Что… как тебе удалось раздобыть это!?$B$BТы оказал мне большую услугу, Рунаак. Мое сердце не выдержит, если этот медальон останется у меня. Поэтому бери его себе, а я наложу на него какое-нибудь полезное заклинание. Распоряжайся медальоном по своему усмотрению, но не забывай тех, кто помог тебе совершить этот подвиг.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24917, 'Плач Мурадина', '', 'Ну-ка, $r, что тут у тебя?', 'Да, мне знаком этот клинок… и я всегда буду ценить его – этот момент, который никогда больше не повторится.$B$BТы оказал мне большую услугу, Рунаак. Прими этот подарок от дворфов из клана Зиморожденных. Распоряжайся им по своему усмотрению, но не забывай тех, кто помог тебе совершить этот подвиг.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24918, 'Возмездие Сильваны', '', 'Что это, $r?', '<Сильвана на мгновенье задумывается, а потом ее взор снова устремляется на вас.>$B$BТы оказал мне большую услугу, Рунаак. Прими этот дар от королевы банши. Распоряжайся им по своему усмотрению, но не забывай тех, кто помог тебе совершить этот подвиг.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (24919, 'Искупление Утера Светоносного', '', 'Чем могу служить, $r?', '<Утер смотрит на медальон, на мгновение погрузившись в молчание.>$B$BМедальон Артаса.$B$BЯ до сих пор помню тот день, когда вручил ему его... $B$BТы совершил поистине великое дело, Рунаак. Моя душа теперь обретет покой. Я готов поделиться с тобой воспоминанием, затерявшимся в глубинах памяти. Распоряжайся им по своему усмотрению, но не забывай тех, кто помог тебе совершить этот подвиг.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (25239, 'Путь силы', '', 'Ты желаешь и дальше следовать путем силы?', 'Ты по-прежнему отважно сражаешься на нашей стороне, Ашалисс. Прими это не как дар, но как оружие в войне против Плети.', NULL, NULL, NULL, 'Пепельное кольцо мощи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (25240, 'Путь силы', '', 'Ты желаешь и дальше следовать путем силы?', 'Ты по-прежнему отважно сражаешься на нашей стороне, Ашалисс. Прими это не как дар, но как оружие в войне против Плети.', NULL, NULL, NULL, 'Пепельное кольцо великой мощи', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (25246, 'Перемены в душе', '', '', '', NULL, NULL, NULL, 'Пепельное кольцо безграничной мощи', 'Требуется денег: 200', NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (25247, 'Перемены в душе', '', '', '', NULL, NULL, NULL, 'Пепельное кольцо мощи', 'Требуется денег: 200', NULL, NULL);
