INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (25306, 'Теперь ты в армии, гном!', '', '', '', NULL, NULL, NULL, 'Система катапультирования проверена', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (25444, 'Идеальные шпионы', 'Глупо соваться туда вслепую, так что мы сначала зашлем наших маленьких шпионов собрать кое-какую информацию для Вол\'джина. Он должен знать, что творится на островах.$B$BЕсли хочешь помочь – я не против. Сначала поймай лягушек – они любят сидеть в тени пальм вокруг Сен\'джина.$B$BКак наловишь квакш, тащи к моему сторожевому тотему, мы заговорим их и прикрутим к ним мое зрение.', 'Поймайте 5 сен\'джинских лягушек и заговорите их, объединив их зрение со зрением Ваниры у сторожевого тотема.', '', NULL, NULL, NULL, 'Заговорено сен\'джинских лягушек', NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (26012, 'Беда в храме Драконьего Покоя', 'Мой старый друг Крас прислал известие об ужасный событиях в храме Драконьего Покоя, что в Драконьем Погосте. Его сообщение довольно краткое, но из него мне стало понятно, что на Рубиновое святилище, находящееся под храмом, совершено нападение.$B$BК сожалению, неотложные дела не позволяют мне покинуть Даларан и лично разобраться с этим происшествием, но, полагаю, я могу доверить это тебе? Ты так хорошо $gпроявил:проявила: себя в цитадели Короля-лича... пожалуйста, окажи помощь Красу!', 'Поговорите с Красом в храме Драконьего Покоя, что в Драконьем Погосте.', 'Спасибо, что ты откликнулся на просьбу о помощи, отважный искатель приключений.$B$BПозволь мне ввести тебя в курс дела. Нам будет полезно любое участие.', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (26013, 'Нападение на святилище', '$gраса:, в Рубиновом святилище под храмом произошло нечто ужасное!$B$BГлавный вход разрушен, стражи мертвы... Мы послали туда разведчиков, но никто не вернулся живым. Боюсь, нам надо готовиться к худшему.$B$BОтправляйся в Рубиновое святилище и выясни, кто осмелился поднять руку на дом моего племени. Как только у нас будет больше информации, мы сможем спланировать дальнейшие действия.', 'Осмотрите Рубиновое святилище под храмом Драконьего Покоя.', 'Еще раз, спасибо тебе за то, что спас меня из когтей Балтара!$B$BА теперь нам предстоит многое сделать...', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `locales_quest` (`entry`, `Title_loc8`, `Details_loc8`, `Objectives_loc8`, `OfferRewardText_loc8`, `RequestItemsText_loc8`, `EndText_loc8`, `CompletedText_loc8`, `ObjectiveText1_loc8`, `ObjectiveText2_loc8`, `ObjectiveText3_loc8`, `ObjectiveText4_loc8`) VALUES (26034, 'Сумеречный разрушитель', 'Нет, это было не случайное нападение, а организованная атака на род красных драконов.$B$BЯ вижу Заритриана, наблюдающего за битвой с вершины холма, но истинный лидер захватчиков – могущественный сумеречный дракон Халион. В первый раз после появления Даргонакса мы столкнулись со взрослым отпрыском Зловестины.$B$BУбей его, $N, изгони захватчиков и сообщи Красу обо всем, что ты здесь $gвидел:видела:.', 'Победите Халиона и отразите нападение на Рубиновое святилище.', 'Крас внимательно слушает ваш рассказ о битве с Халионом, и он не в силах скрыть изумление, когда вы упоминаете Смертокрыла.>$B$BМы все в долгу перед тобой, смертный, ибо ты изгнал захватчиков из Рубинового святилища. Но весть о Разрушителе взволновала меня куда сильнее. Мне надо обсудить это с остальными членами Драконьего союза.$B$BПрими этот дар в знак моей благодарности, и да поможет он тебе выстоять против надвигающейся бури.', NULL, NULL, NULL, 'Халион убито', NULL, NULL, NULL);
